INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('5f96278ad083a34ec4da00d8', '【太極苑】每週三晚上，大安森林公園二號出口，都有太極拳團練活動！', '無資料', '太極苑', ' 大安森林公園二號出口 ', '2019-07-03 00:00:00', '2025-07-09 00:00:00', '大安森林公園二號出口', 25.032435, 121.5349054, '免費', 'https://kktix.com/events/taichi7-copy-1/registrations/quickly', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【太極苑】每週三晚上，大安森林公園二號出口，都有太極拳團練活動！', `description`='無資料', `organizer`='太極苑', `address`=' 大安森林公園二號出口 ', `start_date`='2019-07-03 00:00:00', `end_date`='2025-07-09 00:00:00', `location`='大安森林公園二號出口', `latitude`=25.032435, `longitude`=121.5349054, `ticket_price`='免費', `source_url`='https://kktix.com/events/taichi7-copy-1/registrations/quickly', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('64a48ddf73f77c07602ba0c7', '傳藝植物園', '國立傳統藝術中心年度大展「傳藝植物園」，以傳統藝術中的植物為主題，呈現植物在生活應用、裝飾圖騰、工藝表現與文化象徵等面向所扮演的重要角色，展期從112年6月1日起至114年2月28日止。\r\n接續前一檔傳藝動物園展覽的陪伴，傳藝植物園展覽則呈現植物帶給我們生活中的豐富色彩，包括食衣住行等生活用品、在傳統工藝與表演藝術中的精湛表現，以及植物所蘊含的象徵寓意與文化信仰等，展現出人與天地、與植物間緊密的關係。透過「生命之樹」、「中高、中低海拔、水岸與海岸植物區」及「花果園區」等展覽單元，還有「香蕉絲服飾」、「樹皮衣」等難得一見的借展品，帶領民眾認識傳藝植物背後的故事。也歡迎大家來到宜蘭傳藝園區並參觀展覽，感受傳統藝術豐沛的生命力、知識內涵與想像。\r\n每一座植物園，都是人與自然關係的展現。許多植物園的空間規劃，再現亙古以來人類社會對於自然秩序的理解和宇宙觀。\r\n在這座傳藝植物園裡，透過「生命之樹」、「中高海拔、中低海拔、水岸與海岸植物區」、「花果園區」、「自造祝福」、「光之植生牆」等五大單元，我們將看到多元且豐富的工藝內涵與文化故事，依隨著臺灣多樣的植物生態共同呈現，這些人文與自然的保有與發展，也象徵臺灣藝術文化生生不息的泉源。\r\n國立歷史博物館參展的2件典藏陶器《交趾陶蓮霧》與《交趾陶柿子》將分期於「花果園區」展示，觀眾可以欣賞交趾陶之美，亦能了解瓜果植物被賦予的文化寓意，感受自然與人文的交融意趣。', '國立傳統藝術中心', '宜蘭縣五結鄉24鄰五濱路二段201號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '國立傳統藝術中心宜蘭園區', 24.68887343, 121.8058342, '門票--敬老票+75;門票--縣民票+100;門票--優待票+120;門票--普通票+150', 'https://event.culture.tw/mocweb/reg/NMH/ExhibitionDetail.init.ctr?actId=30014', '[]') ON DUPLICATE KEY UPDATE `activity_name`='傳藝植物園', `description`='國立傳統藝術中心年度大展「傳藝植物園」，以傳統藝術中的植物為主題，呈現植物在生活應用、裝飾圖騰、工藝表現與文化象徵等面向所扮演的重要角色，展期從112年6月1日起至114年2月28日止。\r\n接續前一檔傳藝動物園展覽的陪伴，傳藝植物園展覽則呈現植物帶給我們生活中的豐富色彩，包括食衣住行等生活用品、在傳統工藝與表演藝術中的精湛表現，以及植物所蘊含的象徵寓意與文化信仰等，展現出人與天地、與植物間緊密的關係。透過「生命之樹」、「中高、中低海拔、水岸與海岸植物區」及「花果園區」等展覽單元，還有「香蕉絲服飾」、「樹皮衣」等難得一見的借展品，帶領民眾認識傳藝植物背後的故事。也歡迎大家來到宜蘭傳藝園區並參觀展覽，感受傳統藝術豐沛的生命力、知識內涵與想像。\r\n每一座植物園，都是人與自然關係的展現。許多植物園的空間規劃，再現亙古以來人類社會對於自然秩序的理解和宇宙觀。\r\n在這座傳藝植物園裡，透過「生命之樹」、「中高海拔、中低海拔、水岸與海岸植物區」、「花果園區」、「自造祝福」、「光之植生牆」等五大單元，我們將看到多元且豐富的工藝內涵與文化故事，依隨著臺灣多樣的植物生態共同呈現，這些人文與自然的保有與發展，也象徵臺灣藝術文化生生不息的泉源。\r\n國立歷史博物館參展的2件典藏陶器《交趾陶蓮霧》與《交趾陶柿子》將分期於「花果園區」展示，觀眾可以欣賞交趾陶之美，亦能了解瓜果植物被賦予的文化寓意，感受自然與人文的交融意趣。', `organizer`='國立傳統藝術中心', `address`='宜蘭縣五結鄉24鄰五濱路二段201號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='國立傳統藝術中心宜蘭園區', `latitude`=24.68887343, `longitude`=121.8058342, `ticket_price`='門票--敬老票+75;門票--縣民票+100;門票--優待票+120;門票--普通票+150', `source_url`='https://event.culture.tw/mocweb/reg/NMH/ExhibitionDetail.init.ctr?actId=30014', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('64dfd8e073f77c2b484e67d0', '𝗧𝗔𝗙𝗔𝗟𝗢𝗡𝗚太巴塱起源⪤續存⪤社會', '展覽透過梳理代代口傳的神話故事以及文化物件，邀請大家行走在虛實交映間展開的路徑上，聆聽與遙望祖輩如何直面自然威脅並逐步建立生活，歷經一代代的消長與傳承，並於波瀾混沌之中蛻變出屬於部落文化傳統的價值。', '花蓮縣文化局', '花蓮縣光復鄉', '2025-01-01 00:00:00', '2025-08-18 00:00:00', '光復鄉（花蓮縣）=', 23.64658742, 121.4351231, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='𝗧𝗔𝗙𝗔𝗟𝗢𝗡𝗚太巴塱起源⪤續存⪤社會', `description`='展覽透過梳理代代口傳的神話故事以及文化物件，邀請大家行走在虛實交映間展開的路徑上，聆聽與遙望祖輩如何直面自然威脅並逐步建立生活，歷經一代代的消長與傳承，並於波瀾混沌之中蛻變出屬於部落文化傳統的價值。', `organizer`='花蓮縣文化局', `address`='花蓮縣光復鄉', `start_date`='2025-01-01 00:00:00', `end_date`='2025-08-18 00:00:00', `location`='光復鄉（花蓮縣）=', `latitude`=23.64658742, `longitude`=121.4351231, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('65299f9d73f77c62e4370998', '亞太樂器常設展', '臺灣，鑲嵌於太平洋島鍊上的亞洲之心。在時間的淬煉下，各族群的歷史記憶在這片土地上積累出音樂文化的結晶。\r\n本常設展將以臺灣及亞洲各國特色樂器，為您揭開亞太音樂文化的神祕面紗，太平洋上的各地風情將匯聚至此，音樂文化的豐麗瑰寶將呈獻予您！', '國立傳統藝術中心', '宜蘭縣五結鄉24鄰五濱路二段201號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '國立傳統藝術中心宜蘭園區', 24.68887343, 121.8058342, '門票--敬老票+75;門票--縣民票+100;門票--優待票+120;門票--普通票+150', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='亞太樂器常設展', `description`='臺灣，鑲嵌於太平洋島鍊上的亞洲之心。在時間的淬煉下，各族群的歷史記憶在這片土地上積累出音樂文化的結晶。\r\n本常設展將以臺灣及亞洲各國特色樂器，為您揭開亞太音樂文化的神祕面紗，太平洋上的各地風情將匯聚至此，音樂文化的豐麗瑰寶將呈獻予您！', `organizer`='國立傳統藝術中心', `address`='宜蘭縣五結鄉24鄰五濱路二段201號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='國立傳統藝術中心宜蘭園區', `latitude`=24.68887343, `longitude`=121.8058342, `ticket_price`='門票--敬老票+75;門票--縣民票+100;門票--優待票+120;門票--普通票+150', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('658de40e73f77c963806a59b', '【臺灣文學基地】繪本好時光（臺北）', '　   🌞臺灣文學基地🌞\n　繪本好時光📖說故事活動\n\n\n\n每週三、週六在臺灣文學基地都有說故事老師等待大朋友小朋友來訪，\n打開繪本的書頁，生動的聲音與肢體引領每一雙認真的眼睛、每一對專注的耳朵，\n聆聽故事的姿態如向著陽光的花草，在臺灣文學基地裡綻放搖曳，\n故事裡的文字寓意如種籽植栽在生活與心田，豐富生命的體會！\n\n \n\n適合年齡｜全年齡\n活動日期｜每週三、週六\n活動時間｜週三14:30-15:30、週六10:30-11:30\n活動地點｜臺灣文學基地 文學厝\n\n精彩繪本書單\n\n2/1(六)\n《雪地與雪泥》\n《世界上最棒的蛇》\n2/5(三)\n《老鼠娶新娘》\n《小狗阿疤想變羊》\n2/8(六)\n《石頭湯》《祖母的妙法》\n《小老鼠找新家》\n2/12(三)\n《森林的元宵節》\n《元宵節－細說太平春市圖》\n2/15(六)\n《你為什麼不開花》\n《小年獸出任務》\n2/19(三)\n《老奶奶，哪兒去？》《貓咪幫你找新家》\n《椅子樹》\n2/22(六)世界母語日！台語故事特別場：https://reurl.cc/LW1nme\n2/26(三)\n《如果你種下一棵樹》\n《樹可能記得》\n\n \n\n集點活動\n\n12歲以下的小朋友，每參加1場說故事活動，即可集1點。集滿6點，可兌換精美紀念品1份；集滿10點還可以抽臺灣文學館出版經典繪本！\n\n ', '國立台灣文學館', '無資料', '2025-02-26 00:00:00', '2025-02-26 00:00:00', '臺灣文學基地文學厝', 0, 0, '無資料', 'https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=30104', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【臺灣文學基地】繪本好時光（臺北）', `description`='　   🌞臺灣文學基地🌞\n　繪本好時光📖說故事活動\n\n\n\n每週三、週六在臺灣文學基地都有說故事老師等待大朋友小朋友來訪，\n打開繪本的書頁，生動的聲音與肢體引領每一雙認真的眼睛、每一對專注的耳朵，\n聆聽故事的姿態如向著陽光的花草，在臺灣文學基地裡綻放搖曳，\n故事裡的文字寓意如種籽植栽在生活與心田，豐富生命的體會！\n\n \n\n適合年齡｜全年齡\n活動日期｜每週三、週六\n活動時間｜週三14:30-15:30、週六10:30-11:30\n活動地點｜臺灣文學基地 文學厝\n\n精彩繪本書單\n\n2/1(六)\n《雪地與雪泥》\n《世界上最棒的蛇》\n2/5(三)\n《老鼠娶新娘》\n《小狗阿疤想變羊》\n2/8(六)\n《石頭湯》《祖母的妙法》\n《小老鼠找新家》\n2/12(三)\n《森林的元宵節》\n《元宵節－細說太平春市圖》\n2/15(六)\n《你為什麼不開花》\n《小年獸出任務》\n2/19(三)\n《老奶奶，哪兒去？》《貓咪幫你找新家》\n《椅子樹》\n2/22(六)世界母語日！台語故事特別場：https://reurl.cc/LW1nme\n2/26(三)\n《如果你種下一棵樹》\n《樹可能記得》\n\n \n\n集點活動\n\n12歲以下的小朋友，每參加1場說故事活動，即可集1點。集滿6點，可兌換精美紀念品1份；集滿10點還可以抽臺灣文學館出版經典繪本！\n\n ', `organizer`='國立台灣文學館', `address`='無資料', `start_date`='2025-02-26 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='臺灣文學基地文學厝', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=30104', `image_ur