INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('65b2cc9c73f77c4dc0ebe714', '【好戲在臺】布袋戲彩樓數位多媒體展', '布袋戲最早的雛型是單人演出的肩擔戲，一個人、一套演出道具、一個大布袋，演出行頭就都齊了。平常大布袋用來收納演出道具；演出時大布袋化身為表演舞臺，將演師遮住，讓觀眾目光集中在戲偶演出上。這個大布袋讓觀眾留下鮮明的視覺印象，也是「布袋戲」名稱的由來之一。在布袋戲表演舞臺中，以「彩樓」的外觀構思巧妙、獨具匠心，是最華美、也是最富傳統工藝表現的舞臺。\r\n本展覽主要展出中心典藏的「布袋戲彩樓」，並以「好戲在臺」為展題，「好戲」除了是上演的布袋戲，也是戲臺雕刻中的戲曲故事；從戲臺的演變，更能窺見布袋戲的發展歷程。此外，戲臺也乘載了布袋戲演師及樂師、請戲主與戲迷投注的熱情，從戲臺前方等著戲迷就坐的椅子，戲臺後整齊擺放的戲偶，戲臺上的千秋牌、戲路表、賞金等，都交織了臺前臺後的記憶故事，這些「好戲」都環繞著「戲臺」而發生。期以透過「好戲在臺」──一窺布袋戲戲臺上的情誼、記憶與故事。', '國立傳統藝術中心', '宜蘭縣五結鄉24鄰五濱路二段201號', '2025-01-01 00:00:00', '2025-09-17 00:00:00', '國立傳統藝術中心宜蘭園區', 24.68887343, 121.8058342, '門票--敬老票+75;門票--縣民票+100;門票--優待票+120;門票--普通票+150', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【好戲在臺】布袋戲彩樓數位多媒體展', `description`='布袋戲最早的雛型是單人演出的肩擔戲，一個人、一套演出道具、一個大布袋，演出行頭就都齊了。平常大布袋用來收納演出道具；演出時大布袋化身為表演舞臺，將演師遮住，讓觀眾目光集中在戲偶演出上。這個大布袋讓觀眾留下鮮明的視覺印象，也是「布袋戲」名稱的由來之一。在布袋戲表演舞臺中，以「彩樓」的外觀構思巧妙、獨具匠心，是最華美、也是最富傳統工藝表現的舞臺。\r\n本展覽主要展出中心典藏的「布袋戲彩樓」，並以「好戲在臺」為展題，「好戲」除了是上演的布袋戲，也是戲臺雕刻中的戲曲故事；從戲臺的演變，更能窺見布袋戲的發展歷程。此外，戲臺也乘載了布袋戲演師及樂師、請戲主與戲迷投注的熱情，從戲臺前方等著戲迷就坐的椅子，戲臺後整齊擺放的戲偶，戲臺上的千秋牌、戲路表、賞金等，都交織了臺前臺後的記憶故事，這些「好戲」都環繞著「戲臺」而發生。期以透過「好戲在臺」──一窺布袋戲戲臺上的情誼、記憶與故事。', `organizer`='國立傳統藝術中心', `address`='宜蘭縣五結鄉24鄰五濱路二段201號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-09-17 00:00:00', `location`='國立傳統藝術中心宜蘭園區', `latitude`=24.68887343, `longitude`=121.8058342, `ticket_price`='門票--敬老票+75;門票--縣民票+100;門票--優待票+120;門票--普通票+150', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('65dd040c73f77cabb836fdf5', '「尋（qimˇ）衫（samˊ）：六堆原客服飾圖紋个對話」特展 ', '服飾記載著各族群的歷史和遷移軌跡；而隱藏其中的圖紋，除了展現創作者的美感與織繡工藝外，也蘊藏著不同族群、地域、使用場合或社會階級的文化意涵，更作為族群識別的重要表徵。\r\n\r\n本展在尋衫的文化路徑上，以六堆地區客家與鄰近的原住民族及平埔族群的「服飾圖紋」為主題，帶您共下(kiung ha) 解開衣衫間的圖紋密碼，展現原、客族群間相遇、交流所發展的精采故事與多元文化樣貌。\r\n\r\n【原客織間】\r\n\r\n六堆地區的客家人與排灣族、魯凱族、馬卡道族及大武壠族群因地緣近，故交易、通婚互動頻繁；在現今屏東185縣道（沿山公路）途經的鄉鎮早期設有原客交換（易）所，因此服飾製作的形制、刺繡技法與圖紋樣式都有交流痕跡。\r\n\r\n【圖紋密語】\r\n\r\n客家人的刺繡圖紋常取圖紋諧音、隱喻、典故與傳說等含意，藉以表達對未來的期望與祝願的吉祥意涵。原住民族相信圖紋多具有靈力，呈現的是個人及家族在部落的階序及功蹟，也有製作者對服飾接受者最深切的守護與祝福。\r\n\r\n【傳承蛻變】\r\n\r\n隨著時代的變遷，各族群的工藝師們面臨不同的挑戰，有擔心傳統服飾技法斷層、有熱切尋回族群圖紋及身分認同的渴望，也有延續傳統並重新轉譯的創作，經由這些工藝師的努力耕耘，讓我們看見六堆原客服飾靚靚的未來！', '客家委員會客家文化發展中心', '屏東縣內埔鄉信義路588號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '六堆客家文化園區', 22.65116933, 120.5888222, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「尋（qimˇ）衫（samˊ）：六堆原客服飾圖紋个對話」特展 ', `description`='服飾記載著各族群的歷史和遷移軌跡；而隱藏其中的圖紋，除了展現創作者的美感與織繡工藝外，也蘊藏著不同族群、地域、使用場合或社會階級的文化意涵，更作為族群識別的重要表徵。\r\n\r\n本展在尋衫的文化路徑上，以六堆地區客家與鄰近的原住民族及平埔族群的「服飾圖紋」為主題，帶您共下(kiung ha) 解開衣衫間的圖紋密碼，展現原、客族群間相遇、交流所發展的精采故事與多元文化樣貌。\r\n\r\n【原客織間】\r\n\r\n六堆地區的客家人與排灣族、魯凱族、馬卡道族及大武壠族群因地緣近，故交易、通婚互動頻繁；在現今屏東185縣道（沿山公路）途經的鄉鎮早期設有原客交換（易）所，因此服飾製作的形制、刺繡技法與圖紋樣式都有交流痕跡。\r\n\r\n【圖紋密語】\r\n\r\n客家人的刺繡圖紋常取圖紋諧音、隱喻、典故與傳說等含意，藉以表達對未來的期望與祝願的吉祥意涵。原住民族相信圖紋多具有靈力，呈現的是個人及家族在部落的階序及功蹟，也有製作者對服飾接受者最深切的守護與祝福。\r\n\r\n【傳承蛻變】\r\n\r\n隨著時代的變遷，各族群的工藝師們面臨不同的挑戰，有擔心傳統服飾技法斷層、有熱切尋回族群圖紋及身分認同的渴望，也有延續傳統並重新轉譯的創作，經由這些工藝師的努力耕耘，讓我們看見六堆原客服飾靚靚的未來！', `organizer`='客家委員會客家文化發展中心', `address`='屏東縣內埔鄉信義路588號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='六堆客家文化園區', `latitude`=22.65116933, `longitude`=120.5888222, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6616ffce73f77c4d54c71391', '【地球you & me】恐龍石光跡', ' ■ 主題： 「恐龍石光跡」 🦕🦕\n\n   ►日期：2/23(日)\n\n   ►時間：14:00-15:00 / 15:30-16:30\n\n   ►內容：「恐龍石光跡」將帶領小朋友了解巨大的恐龍骨骼是為何來到博物館，再透過齒爪化石觸摸體驗，了解化石形成的奧妙，並且學習如何透過化石證據，推測恐龍滅絕之前的生活點滴。\n\n   --------------------------------------------------------------------------------\n\n   ■地點：古生物館 鯨豚平台\n\n   ■對象與人數： 建議6-12歲學童參加，每場孩童人數15人，歡迎家長一同參與。\n\n   ■報名方式：活動免費，當日先至服務台購買門票及登記場次。(活動30分鐘前開放報名)        \n\n \n\n \n\n    \n\n  \n\n​***課程可能會依授課狀況進行部分調整，若遇特殊狀況臨時更動，本館保有更改或取消場次之權利，敬請包涵***\n\n ', '國立臺灣博物館', '中正區襄陽路25號(臺博館斜對面)', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '臺博館古生物館 鯨豚平台', 25.0435644, 121.5143628, '活動免費，須憑當日古生物館或本館門票參加', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=90035', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【地球you & me】恐龍石光跡', `description`=' ■ 主題： 「恐龍石光跡」 🦕🦕\n\n   ►日期：2/23(日)\n\n   ►時間：14:00-15:00 / 15:30-16:30\n\n   ►內容：「恐龍石光跡」將帶領小朋友了解巨大的恐龍骨骼是為何來到博物館，再透過齒爪化石觸摸體驗，了解化石形成的奧妙，並且學習如何透過化石證據，推測恐龍滅絕之前的生活點滴。\n\n   --------------------------------------------------------------------------------\n\n   ■地點：古生物館 鯨豚平台\n\n   ■對象與人數： 建議6-12歲學童參加，每場孩童人數15人，歡迎家長一同參與。\n\n   ■報名方式：活動免費，當日先至服務台購買門票及登記場次。(活動30分鐘前開放報名)        \n\n \n\n \n\n    \n\n  \n\n​***課程可能會依授課狀況進行部分調整，若遇特殊狀況臨時更動，本館保有更改或取消場次之權利，敬請包涵***\n\n ', `organizer`='國立臺灣博物館', `address`='中正區襄陽路25號(臺博館斜對面)', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='臺博館古生物館 鯨豚平台', `latitude`=25.0435644, `longitude`=121.5143628, `ticket_price`='活動免費，須憑當日古生物館或本館門票參加', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=90035', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66353b6173f77c02209d11c1', '2025國際沈文程日 五月十一彼下埔巡迴演唱會 ', '無資料', '無資料', '台北市信義區信義路五段一號', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '台北國際會議中心大會堂', 25.0336111, 121.5608333, '3600、3200、2800、2400、2000、1600、1200', 'https://ticket.com.tw/Application/UTK02/UTK0201_.aspx?PRODUCT_ID=P0I5F83G', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025國際沈文程日 五月十一彼下埔巡迴演唱會 ', `description`='無資料', `organizer`='無資料', `address`='台北市信義區信義路五段一號', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='台北國際會議中心大會堂', `latitude`=25.0336111, `longitude`=121.5608333, `ticket_price`='3600、3200、2800、2400、2000、1600、1200', `source_url`='https://ticket.com.tw/Application/UTK02/UTK0201_.aspx?PRODUCT_ID=P0I5F83G', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6643d54626b32431709014f0', '「微觀．史觀」考古特展', '「微觀．史觀」考古特展\n\n在重新開館一年後，「微觀．史觀」考古特展以作為常設展廳的議題延伸，深化民眾對於三萬年來在臺灣這片土地故事及臺灣與世界交會的認識與理解。展示核心概念以考古微觀的研究成果，以植物矽酸體、玉、玻璃珠、礦物等細微證據作為主題，提出不同於過去對臺灣史前史的看法，讓大家可以認識臺灣史前史的重要發展內涵。\n\n     本特展運用色彩繽紛生動活潑的展示效果，期望將顯微鏡下繽紛的晶體與礦物融入展示中，讓觀眾沉浸在微觀的世界裡探索宏觀的視界。\n\n 展覽資訊 \n\n日期｜ 2024.05.18 - 2025.03.02\n時間｜週二至週日 09:00~17:00(週一休館)\n地點｜國立臺灣史前文化博物館康樂本館第一特展室\n地址｜臺東縣臺東市豐田里博物館路1號\n電話｜089-381166\n\n\n\n\n指導單位 | 文化部\n\n主辦單位 | 國立臺灣史前文化博物館\n\n督導 | 蔡志忍、方鈞瑋\n\n策展 |葉長庚、姚書宇、王仲群、康芸甯\n\n學術支援 | 王冠文、蔡哲嫻、方建能\n\n展示協助 | 吳星慧、夏麗芳、劉宜婷、吳詩婷、鍾緯澤、童靖倫、洪瑞恬\n\n展品協助 | 林怡如、陳俊男、蘇嘉蓉、林芳誠、蔡怡玲、劉浚佑、蘇迺承、巫珈葦、羅翊瑄、吳溢翔、黃芷芸、陳鈺琇、朱月瓏\n\n借展單位 | 花蓮縣文化局、新北市立十三行博物館、中央研究院歷史語言研究所\n\n圖像授權 |洪曉純、國立臺灣博物館、庶古文創事業股份有限公司\n\n影像授權 | NHK EDUCATIONAL CORPORATION\n\n統籌製作 | 綠地創意設計\n\n協力製作 | 林泉廣工作室、犇達資訊、大光工程、廣能科技、三形整合、林宗文\n\n ', '國立臺灣史前文化博物館', '950  臺東縣臺東市豐田里博物館路1號', '2024-05-18 00:00:00', '2025-03-02 00:00:00', '康樂本館第一特展', 22.75165721, 121.1103647, '無資料', 'https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=40032', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「微觀．史觀」考古特展', `description`='「微觀．史觀」考古特展\n\n在重新開館一年後，「微觀．史觀」考古特展以作為常設展廳的議題延伸，深化民眾對於三萬年來在臺灣這片土地故事及臺灣與世界交會的認識與理解。展示核心概念以考古微觀的研究成果，以植物矽酸體、玉、玻璃珠、礦物等細微證據作為主題，提出不同於過去對臺灣史前史的看法，讓大家可以認識臺灣史前史的重要發展內涵。\n\n     本特展運用色彩繽紛生動活潑的展示效果，期望將顯微鏡下繽紛的晶體與礦物融入展示中，讓觀眾沉浸在微觀的世界裡探索宏觀的視界。\n\n 展覽資訊 \n\n日期｜ 2024.05.18 - 2025.03.02\n時間｜週二至週日 09:00~17:00(週一休館)\n地點｜國立臺灣史前文化博物館康樂本館第一特展室\n地址｜臺東縣臺東市豐田里博物館路1號\n電話｜089-381166\n\n\n\n\n指導單位 | 文化部\n\n主辦單位 | 國立臺灣史前文化博物館\n\n督導 | 蔡志忍、方鈞瑋\n\n策展 |葉長庚、姚書宇、王仲群、康芸甯\n\n學術支援 | 王冠文、蔡哲嫻、方建能\n\n展示協助 | 吳星慧、夏麗芳、劉宜婷、吳詩婷、鍾緯澤、童靖倫、洪瑞恬\n\n展品協助 | 林怡如、陳俊男、蘇嘉蓉、林芳誠、蔡怡玲、劉浚佑、蘇迺承、巫珈葦、羅翊瑄、吳溢翔、黃芷芸、陳鈺琇、朱月瓏\n\n借展單位 | 花蓮縣文化局、新北市立十三行博物館、中央研究院歷史語言研究所\n\n圖像授權 |洪曉純、國立臺灣博物館、庶古文創事業股份有限公司\n\n影像授權 | NHK EDUCATIONAL CORPORATION\n\n統籌製作 | 綠地創意設計\n\n協力製作 | 林泉廣工作室、犇達資訊、大光工程、廣能科技、三形整合、林宗文\n\n ', `organizer`='國立臺灣史前文化博物館', `address`='950  臺東縣臺東市豐田里博物館路1號', `start_date`='2024-05-18 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='康樂本館第一特展', `latitude`=22.75165721, `longitude`=121.1103647, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=40032', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66637ce226b3242b6c2c581f', '【免費愛心席】線上登記(2024年7月至2025年7月期間場次)', '◎申請前請先詳閱NTSO國立臺灣交響樂團售票音樂會身心障礙者購票優惠及免費愛心席說明（請點擊連結網頁）\n\n◎ 場次若有更動，以最新公告內容為準。\n\n最後更新日期 2024/6/6\n\n ', '國立臺灣交響樂團', '413  臺中市霧峰區中正路738-2號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '國立臺灣交響樂團演奏廳', 22.624172, 120.3422105, '無資料', 'https://event.culture.tw/mocweb/reg/NTSO/Detail.init.ctr?actId=40119', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【免費愛心席】線上登記(2024年7月至2025年7月期間場次)', `description`='◎申請前請先詳閱NTSO國立臺灣交響樂團售票音樂會身心障礙者購票優惠及免費愛心席說明（請點擊連結網頁）\n\n◎ 場次若有更動，以最新公告內容為準。\n\n最後更新日期 2024/6/6\n\n ', `organizer`='國立臺灣交響樂團', `address`='413  臺中市霧峰區中正路738-2號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='國立臺灣交響樂團演奏廳', `latitude`=22.624172, `longitude`=120.3422105, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTSO/Detail.init.ctr?actId=40119', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6668bfd526b3242b6c2c58c1', '兒藝基地《「我記得……」：關於記憶與想像的拼貼》兒童藝術教育展', '「我記得……」：關於記憶與想像的拼貼\n“Remember When I...”: A Collage of Memory and Imagination\n\n2024年7月6日至2025年6月15日\n\n臺灣兒童藝術基地 教育展示空間\n\n \n\n參展藝術家：吳芊頤、莊普、黃至正、鹽池（顏鈺恬、吳有容）\n\n \n\n我記得…那個風和日麗的假日午後，和家人一起到附近的大公園遊玩，在樹林間穿梭、撿拾土地上紅色的落葉和圓滾滾的樹木種子。\n\n我還記得…海邊鹹鹹的味道、空氣中溫暖而濕潤的氣味；…經過煩囂喧鬧的路口、光彩奪目的霓虹燈招牌… \n\n你記得生活中哪些片刻的經驗嗎？有什麼特別印象深刻，讓你好想把記憶中的人們、事物、時光、氣味或是心情保存下來？藝術家也和你一樣，生活中的點點滴滴成為創作的靈感元素，透過不同的創作手法，把生命中重要或不經意的時刻保留下來，甚至…產生新的意義！\n\n本次兒童藝術教育展聚焦在當代藝術家如何透過各種「拼貼」的創作手法，將生活中的記憶透過藝術的語言表現。也邀請你在觀賞展覽後，細細回想生活中的片刻，用什麼方式最能表達心中的記憶？\n\n \n\n指導單位：文化部\n\n主辦單位：國立臺灣美術館\n\n策劃團隊：林忠憲、黃素雲、劉昕昀、黃莉婷\n\n空間設計：廖音喬\n\n視覺設計：dmp projects\n\n佈展執行：接上他的腿有限公司\n\n影像拍攝：凹焦影像工作室\n\n \n\n< 本展為「文化部重建臺灣藝術史專案計畫」>', '國立臺灣美術館', '403  臺中市西區414五權西路一段2號', '2024-07-06 00:00:00', '2025-06-15 00:00:00', '教育展示空間(Educational Exhibition Space)', 24.14391082, 120.6647579, '無資料', 'https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=40071', '[]') ON DUPLICATE KEY UPDATE `activity_name`='兒藝基地《「我記得……」：關於記憶與想像的拼貼》兒童藝術教育展', `description`='「我記得……」：關於記憶與想像的拼貼\n“Remember When I...”: A Collage of Memory and Imagination\n\n2024年7月6日至2025年6月15日\n\n臺灣兒童藝術基地 教育展示空間\n\n \n\n參展藝術家：吳芊頤、莊普、黃至正、鹽池（顏鈺恬、吳有容）\n\n \n\n我記得…那個風和日麗的假日午後，和家人一起到附近的大公園遊玩，在樹林間穿梭、撿拾土地上紅色的落葉和圓滾滾的樹木種子。\n\n我還記得…海邊鹹鹹的味道、空氣中溫暖而濕潤的氣味；…經過煩囂喧鬧的路口、光彩奪目的霓虹燈招牌… \n\n你記得生活中哪些片刻的經驗嗎？有什麼特別印象深刻，讓你好想把記憶中的人們、事物、時光、氣味或是心情保存下來？藝術家也和你一樣，生活中的點點滴滴成為創作的靈感元素，透過不同的創作手法，把生命中重要或不經意的時刻保留下來，甚至…產生新的意義！\n\n本次兒童藝術教育展聚焦在當代藝術家如何透過各種「拼貼」的創作手法，將生活中的記憶透過藝術的語言表現。也邀請你在觀賞展覽後，細細回想生活中的片刻，用什麼方式最能表達心中的記憶？\n\n \n\n指導單位：文化部\n\n主辦單位：國立臺灣美術館\n\n策劃團隊：林忠憲、黃素雲、劉昕昀、黃莉婷\n\n空間設計：廖音喬\n\n視覺設計：dmp projects\n\n佈展執行：接上他的腿有限公司\n\n影像拍攝：凹焦影像工作室\n\n \n\n< 本展為「文化部重建臺灣藝術史專案計畫」>', `organizer`='國立臺灣美術館', `address`='403  臺中市西區414五權西路一段2號', `start_date`='2024-07-06 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='教育展示空間(Educational Exhibition Space)', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=40071', `image_url`='[]';
