INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6670ad9d26b3242b6c2c5b48', '2024世界服飾展-專屬各國的復古櫥窗', '本年度常設展以世界傳統服飾為主題，規劃8個展版與展櫃，包括越南、印尼、菲律賓、泰國、緬甸、柬埔寨、印度、不丹、日本、韓國、俄羅斯、蒙古、中國、阿拉伯國家、埃及、伊朗、摩洛哥、美國、墨西哥、祕魯、玻利維亞、英國、西班牙、荷蘭、義大利、挪威、芬蘭、冰島及德國等29國特色服飾，藉此讓市民朋友從服裝認識各國的風土民情，並欣賞各地穿搭特色及文化多元性，歡迎踴躍蒞臨參觀。', '臺中市政府民政局', '臺中市南屯區', '2025-01-01 00:00:00', '2025-03-31 00:00:00', '南屯區（臺中市）=', 24.14165524, 120.6177379, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2024世界服飾展-專屬各國的復古櫥窗', `description`='本年度常設展以世界傳統服飾為主題，規劃8個展版與展櫃，包括越南、印尼、菲律賓、泰國、緬甸、柬埔寨、印度、不丹、日本、韓國、俄羅斯、蒙古、中國、阿拉伯國家、埃及、伊朗、摩洛哥、美國、墨西哥、祕魯、玻利維亞、英國、西班牙、荷蘭、義大利、挪威、芬蘭、冰島及德國等29國特色服飾，藉此讓市民朋友從服裝認識各國的風土民情，並欣賞各地穿搭特色及文化多元性，歡迎踴躍蒞臨參觀。', `organizer`='臺中市政府民政局', `address`='臺中市南屯區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('667151218f15d988f3626428', '德大字在：館藏榜書藝術特展', '無資料', '中台世界博物館', '南投縣埔里鎮中台路8號', '2024-07-27 00:00:00', '2025-05-18 00:00:00', '中台世界博物館', 23.97892591, 120.9625259, '全票 200元；團體（10人以上）優待票 100元', 'https://lihi1.com/a4Jb3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='德大字在：館藏榜書藝術特展', `description`='無資料', `organizer`='中台世界博物館', `address`='南投縣埔里鎮中台路8號', `start_date`='2024-07-27 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='中台世界博物館', `latitude`=23.97892591, `longitude`=120.9625259, `ticket_price`='全票 200元；團體（10人以上）優待票 100元', `source_url`='https://lihi1.com/a4Jb3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6672099c26b3242b6c2c5bcf', '《「我記得……」：關於記憶與想像的拼貼》兒童藝術教育展', '我記得…那個風和日麗的假日午後，和家人一起到附近的大公園遊玩，在樹林間穿梭、撿拾土地上紅色的落葉和圓滾滾的樹木種子。\r\n\r\n我還記得…海邊鹹鹹的味道、空氣中溫暖而濕潤的氣味；…經過煩囂喧鬧的路口、光彩奪目的霓虹燈招牌… \r\n\r\n你記得生活中哪些片刻的經驗嗎？有什麼特別印象深刻，讓你好想把記憶中的人們、事物、時光、氣味或是心情保存下來？藝術家也和你一樣，生活中的點點滴滴成為創作的靈感元素，透過不同的創作手法，把生命中重要或不經意的時刻保留下來，甚至…產生新的意義！\r\n\r\n本次兒童藝術教育展聚焦在當代藝術家如何透過各種「拼貼」的創作手法，將生活中的記憶透過藝術的語言表現。也邀請你在觀賞展覽後，細細回想生活中的片刻，用什麼方式最能表達心中的記憶？', '國立臺灣美術館', '臺中市西區五權西路一段2號', '2025-01-01 00:00:00', '2025-06-15 00:00:00', '國立臺灣美術館', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/Keo889', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《「我記得……」：關於記憶與想像的拼貼》兒童藝術教育展', `description`='我記得…那個風和日麗的假日午後，和家人一起到附近的大公園遊玩，在樹林間穿梭、撿拾土地上紅色的落葉和圓滾滾的樹木種子。\r\n\r\n我還記得…海邊鹹鹹的味道、空氣中溫暖而濕潤的氣味；…經過煩囂喧鬧的路口、光彩奪目的霓虹燈招牌… \r\n\r\n你記得生活中哪些片刻的經驗嗎？有什麼特別印象深刻，讓你好想把記憶中的人們、事物、時光、氣味或是心情保存下來？藝術家也和你一樣，生活中的點點滴滴成為創作的靈感元素，透過不同的創作手法，把生命中重要或不經意的時刻保留下來，甚至…產生新的意義！\r\n\r\n本次兒童藝術教育展聚焦在當代藝術家如何透過各種「拼貼」的創作手法，將生活中的記憶透過藝術的語言表現。也邀請你在觀賞展覽後，細細回想生活中的片刻，用什麼方式最能表達心中的記憶？', `organizer`='國立臺灣美術館', `address`='臺中市西區五權西路一段2號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='國立臺灣美術館', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/Keo889', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6672099d26b3242b6c2c5be0', '德大字在：館藏榜書藝術特展', '在生活中常見大字題寫於匾額、紙本，甚至刻於堅硬的岩面之上，這類書法文字一般被稱之為「榜書」。書寫大字除了考驗執筆者對文字結構、經營位置的掌握，以及運筆的流暢之外，實則首要重視「正心」二字。明代費瀛《大書長語》：「大書筆筆從心畫出，必端人雅士，胸次光瑩，膽壯氣完，肆筆而書，自然莊重溫雅，為世所珍。」因此大字書法珍貴之處，在於以文字之美體現了書寫者的品性與胸襟。\r\n「德」字作為本次特展的核心精神所在，含括了個人的人格及氣度表現。中華傳統文化中「道德」代表個人的品行、修養、節操，「福德」為生活之善果、福報、喜慶祝福，「功德」指功業德行的積累、成就，在展覽中以「品格涵養」、「生命祝願」、「功業成就」三個單元分別呈現。「德」字又通「得」也。展題「德大字在」取自佛教經文中「得大自在」之諧音，亦有儒家「素其位而行，無入而不自得」之蘊義，透過大字書法藝術的展出，祝願有君子之德性，心安自在之意涵。', '中台世界博物館', '南投縣埔里鎮', '2025-01-01 00:00:00', '2025-05-18 00:00:00', '埔里鎮（南投縣）=', 23.97892591, 120.9625259, '全票+200;團體（10人以上）優待票+100', 'https://lihi1.com/a4Jb3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='德大字在：館藏榜書藝術特展', `description`='在生活中常見大字題寫於匾額、紙本，甚至刻於堅硬的岩面之上，這類書法文字一般被稱之為「榜書」。書寫大字除了考驗執筆者對文字結構、經營位置的掌握，以及運筆的流暢之外，實則首要重視「正心」二字。明代費瀛《大書長語》：「大書筆筆從心畫出，必端人雅士，胸次光瑩，膽壯氣完，肆筆而書，自然莊重溫雅，為世所珍。」因此大字書法珍貴之處，在於以文字之美體現了書寫者的品性與胸襟。\r\n「德」字作為本次特展的核心精神所在，含括了個人的人格及氣度表現。中華傳統文化中「道德」代表個人的品行、修養、節操，「福德」為生活之善果、福報、喜慶祝福，「功德」指功業德行的積累、成就，在展覽中以「品格涵養」、「生命祝願」、「功業成就」三個單元分別呈現。「德」字又通「得」也。展題「德大字在」取自佛教經文中「得大自在」之諧音，亦有儒家「素其位而行，無入而不自得」之蘊義，透過大字書法藝術的展出，祝願有君子之德性，心安自在之意涵。', `organizer`='中台世界博物館', `address`='南投縣埔里鎮', `start_date`='2025-01-01 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='埔里鎮（南投縣）=', `latitude`=23.97892591, `longitude`=120.9625259, `ticket_price`='全票+200;團體（10人以上）優待票+100', `source_url`='https://lihi1.com/a4Jb3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6682e5ed26b3241884bc2896', '果陀劇場經典冒險喜劇《冒牌天使》', '無資料', '無資料', '臺北市士林區文林路751號', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '臺灣戲曲中心大表演廳', 25.1022766, 121.5197787, '無資料', 'https://www.opentix.life/program/1805544007073423361', '[]') ON DUPLICATE KEY UPDATE `activity_name`='果陀劇場經典冒險喜劇《冒牌天使》', `description`='無資料', `organizer`='無資料', `address`='臺北市士林區文林路751號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺灣戲曲中心大表演廳', `latitude`=25.1022766, `longitude`=121.5197787, `ticket_price`='無資料', `source_url`='https://www.opentix.life/program/1805544007073423361', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6696ffcf26b3240c380461da', '清法戰爭：西仔反印象記特展', '  140年前，法國政府和清廷因為越南的外交歸屬爭議，殃及孤懸海外的臺灣，不只基隆、淡水和澎湖相繼淪為戰場，臺灣全島更面臨商貿閉鎖的經濟困境。這場蔓延超過一年的戰禍——「清法戰爭」，在臺灣人口中稱作「西仔反」，「西仔」即「法蘭西」。\r\n   面對這個臺灣涉外關係的轉捩點，本特展透過彙集十餘年來有關地方社會研究的成果，聚焦當時臺灣社會在強敵壓境下如何組織動員、團結北上抵抗侵略的過程；並重新解讀法軍留下的攝影圖像、戰場紀實與家書，重建戰場的動態實況。\r\n   戰爭結束後，在法國湧現的報刊、書籍出版風潮，以及臺灣特有的贈匾、廟宇壁飾、儀式等追念方式，則呈現了戰爭如何以不同形式轉化，留存於歷史、民俗、傳說與記憶中。\r\n\r\n單元1 無端捲入戰事的臺灣\r\n    1884年，法國與越南的軍事衝突因黑旗軍的參戰陷入膠著，為了迫使清國勢力退出越南，法國發動對臺灣基隆、淡水、澎湖等地的軍事攻擊，意圖挾制臺灣作為和談的抵押品。\r\n    法軍在臺灣周遭的軍事行動，可分為4個階段：一、法國遠東艦隊的編成；二、在基隆跟淡水開啟戰火，占據基隆；三、封鎖臺灣海峽，攔截、騷擾往來沿海的船隻；四、轉進攻占澎湖，作為撤守基隆的藉口。\r\n    這場戰爭的起因與臺灣無關，臺灣卻無端被捲入戰火，最後被迫成為成敗的關鍵籌碼，在在顯示著戰爭本質的荒謬。\r\n\r\n單元2 死亦為鬼雄：自己的家鄉自己守\r\n    面對「西仔反」的挑戰，臺灣戰場的軍事動員，除了跨海調派來臺的湘軍和淮軍之外，臺灣在地義勇也參與作戰。面臨外國的侵略，在地人凝聚了共同體的意識，武裝動員到戰場支援，關鍵領袖包含林朝棟、張李成、姜紹基等。\r\n    至今基隆、淡水等地的廟宇中仍可見到交趾陶、壁畫、匾額訴說著神明助戰傳說；淡水「拜門口」祭拜亡魂儀式，以及保儀尊王從木柵到淡水的遶境路線，都體現了信仰、人群網絡與戰爭集體記憶的交織。\r\n\r\n單元3 戰火浮世：遙盼歸期的旅程\r\n    法國軍官安德烈・薩勒（Firmin André Salles）的紀實攝影，是目前所知臺灣史上首次留下戰爭過程的影像紀錄，將其與隨軍醫官助理科邦（René Coppin）書信，以及名列重要古物的嘉諾（Eugène Germain Garnot）著作——《1884～1885年法國人遠征福爾摩沙》地圖手繪稿及文字手稿共同對照，重新檢視法蘭西帝國於東亞擴張的意圖，亦能看見艱困的戰場實況，包括飲食、疾病問題，19世紀末的臺灣常民風土民情也不時閃現其中。\r\n    戰場寄回的家書、刊載在報紙上的訃文與行軍紀錄的纂輯出版，以不同的記憶與再現方式，重塑對這場戰事的認識與印象。', '國立臺灣歷史博物館', '臺南市安南區長和路一段250號', '2025-01-01 00:00:00', '2025-05-04 00:00:00', '國立臺灣歷史博物館', 23.04869681, 120.1526189, '無資料', 'https://www.nmth.gov.tw/News_Content2.aspx?n=4105&s=218349', '[]') ON DUPLICATE KEY UPDATE `activity_name`='清法戰爭：西仔反印象記特展', `description`='  140年前，法國政府和清廷因為越南的外交歸屬爭議，殃及孤懸海外的臺灣，不只基隆、淡水和澎湖相繼淪為戰場，臺灣全島更面臨商貿閉鎖的經濟困境。這場蔓延超過一年的戰禍——「清法戰爭」，在臺灣人口中稱作「西仔反」，「西仔」即「法蘭西」。\r\n   面對這個臺灣涉外關係的轉捩點，本特展透過彙集十餘年來有關地方社會研究的成果，聚焦當時臺灣社會在強敵壓境下如何組織動員、團結北上抵抗侵略的過程；並重新解讀法軍留下的攝影圖像、戰場紀實與家書，重建戰場的動態實況。\r\n   戰爭結束後，在法國湧現的報刊、書籍出版風潮，以及臺灣特有的贈匾、廟宇壁飾、儀式等追念方式，則呈現了戰爭如何以不同形式轉化，留存於歷史、民俗、傳說與記憶中。\r\n\r\n單元1 無端捲入戰事的臺灣\r\n    1884年，法國與越南的軍事衝