INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66b1c08d07f39cc9f0a38aa9', '無資料', '無資料', '苗栗縣苗北藝文中心', '苗栗縣350苗栗縣竹南鎮公園路206號', '苗栗縣苗北藝文中心', '無資料', '無資料', '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='無資料', `organizer`='苗栗縣苗北藝文中心', `address`='苗栗縣350苗栗縣竹南鎮公園路206號', `location`='苗栗縣苗北藝文中心', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66ba914226b3241b7cd56a1b', '未來戰士—永續地球環境特展', '藍星人的母星已不適合居住，由菁英組成「未來戰士」，在宇宙中尋找適宜居住的地方。最近，第十編組的未來戰士接收到首批先遣隊員的求援訊號，隨後來到停留在太陽系行星「Sol 3」的探索艦上，發現滿滿的收集品與研究日誌，提醒卻標註著美好的環境正面臨危機。\nK博士全力訪查環境情況寫成日誌，也把人類活動類型做成戰略模型，戰士們需要一起找出造成危機的原因，思考改善對策，也接受生活升級訓練，準備滲透行星「Sol 3」解決問題，讓這顆星球維持適合居住的環境，一起加入團隊吧！\n\n本展透過多媒體、標本和模型，將虛擬的故事脈絡與真實的環境議題互相結合，展場內以手持裝置結合互動遊戲及現場展示物件，將複雜的地球環境問題轉化呈現，並即時連動觀眾闖關方案數據紀錄，將大家協作的地球環境改善變化，以多媒體方式呈現於展場出口。\n\n現場還可以欣賞到藝術家楊順發《臺灣水沒》作品，感受藝術家對環境議題的關注。還有以大面積陳設的海洋廢棄物與各類資源回收物，甚至是與快時尚、電器，玩具等人類生活相關的生活物品，邀請觀眾以旁觀者視角俯看人類活動，呼籲觀眾反思並實踐友善使用地球資源的生活方式。\n \n\n \n\n參觀小秘訣🥼㊙️\n\n\n	\n		\n			\n			\n			🔎STEP 1. 領取任務\n\n			至展場【支援小隊招募】完成測驗「你是哪種未來戰士？」，\n\n			即可用手機／平板掃描 QRCode開始任務！\n\n			或使用「未來戰士出任務🚀」學習單一樣可以參與任務哦！\n\n			(現場可索取學習單或自行列印)\n			\n		\n		\n			\n			\n			🔎STEP 2. 博士日誌編號＝危機案例\n\n			進入Ｋ博士太空艙，從【大氣圈AIR】、【水圈WATER】、【陸地圈LAND】、【生物圈GENE】的博士日誌編號，找尋環境危機發生的原因。\n			\n		\n		\n			\n			\n			🔎STEP 3. 人類活動＝危機發生原因，\n\n			一起找尋改善方案！\n\n			從【人類活動模型】尋找與危機有關的人類活動及友善環境的改善解方。\n			\n		\n		\n			\n			\n			🔎STEP 4. 掃描條碼\n\n			完成任務！請至【結訓站】掃描條碼，上傳訓練成果！\n\n			學習單左下方也有條碼可以掃描哦！\n			\n		\n		\n			\n			㊙️展場中除了博士日誌，還有延伸小知識SCIENCE NEWS可以閱讀！\n		\n	\n\n\n ', '國立臺灣博物館', '中正區南昌路一段1號', '2024-08-20 00:00:00', '2025-08-31 00:00:00', '臺博館南門館', 25.0331483, 121.5159774, '全票：20元｜半票：10元', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40241', '[]') ON DUPLICATE KEY UPDATE `activity_name`='未來戰士—永續地球環境特展', `description`='藍星人的母星已不適合居住，由菁英組成「未來戰士」，在宇宙中尋找適宜居住的地方。最近，第十編組的未來戰士接收到首批先遣隊員的求援訊號，隨後來到停留在太陽系行星「Sol 3」的探索艦上，發現滿滿的收集品與研究日誌，提醒卻標註著美好的環境正面臨危機。\nK博士全力訪查環境情況寫成日誌，也把人類活動類型做成戰略模型，戰士們需要一起找出造成危機的原因，思考改善對策，也接受生活升級訓練，準備滲透行星「Sol 3」解決問題，讓這顆星球維持適合居住的環境，一起加入團隊吧！\n\n本展透過多媒體、標本和模型，將虛擬的故事脈絡與真實的環境議題互相結合，展場內以手持裝置結合互動遊戲及現場展示物件，將複雜的地球環境問題轉化呈現，並即時連動觀眾闖關方案數據紀錄，將大家協作的地球環境改善變化，以多媒體方式呈現於展場出口。\n\n現場還可以欣賞到藝術家楊順發《臺灣水沒》作品，感受藝術家對環境議題的關注。還有以大面積陳設的海洋廢棄物與各類資源回收物，甚至是與快時尚、電器，玩具等人類生活相關的生活物品，邀請觀眾以旁觀者視角俯看人類活動，呼籲觀眾反思並實踐友善使用地球資源的生活方式。\n \n\n \n\n參觀小秘訣🥼㊙️\n\n\n	\n		\n			\n			\n			🔎STEP 1. 領取任務\n\n			至展場【支援小隊招募】完成測驗「你是哪種未來戰士？」，\n\n			即可用手機／平板掃描 QRCode開始任務！\n\n			或使用「未來戰士出任務🚀」學習單一樣可以參與任務哦！\n\n			(現場可索取學習單或自行列印)\n			\n		\n		\n			\n			\n			🔎STEP 2. 博士日誌編號＝危機案例\n\n			進入Ｋ博士太空艙，從【大氣圈AIR】、【水圈WATER】、【陸地圈LAND】、【生物圈GENE】的博士日誌編號，找尋環境危機發生的原因。\n			\n		\n		\n			\n			\n			🔎STEP 3. 人類活動＝危機發生原因，\n\n			一起找尋改善方案！\n\n			從【人類活動模型】尋找與危機有關的人類活動及友善環境的改善解方。\n			\n		\n		\n			\n			\n			🔎STEP 4. 掃描條碼\n\n			完成任務！請至【結訓站】掃描條碼，上傳訓練成果！\n\n			學習單左下方也有條碼可以掃描哦！\n			\n		\n		\n			\n			㊙️展場中除了博士日誌，還有延伸小知識SCIENCE NEWS可以閱讀！\n		\n	\n\n\n ', `organizer`='國立臺灣博物館', `address`='中正區南昌路一段1號', `start_date`='2024-08-20 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='臺博館南門館', `latitude`=25.0331483, `longitude`=121.5159774, `ticket_price`='全票：20元｜半票：10元', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40241', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66bbe68f26b3241b7cd56a5a', '臺中市清水紫雲巖一一四年度觀音盃花燈比賽', '為落實心靈改革暨推行全民精神建設，倡導傳統民俗活動，藉以弘揚臺灣文化，並促進觀光事業之發展，激發師生與社會人士創作思考，培養良好互動之精神。\r\n\r\n*評審日期：民國 114 年 2 月 5 日（星期三）上午九時起。\r\n*參加作品自 114 年 1 月 7 日至 114 年 3 月 18 日止在清水紫雲巖展覽。', '清水紫雲巖管理委員會', '臺中市清水區', '2025-01-07 00:00:00', '2025-03-18 00:00:00', '清水區（臺中市）=', 24.29205743, 120.5809094, '無資料', 'http://www.tzuyunyen.org.tw/page10.html', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市清水紫雲巖一一四年度觀音盃花燈比賽', `description`='為落實心靈改革暨推行全民精神建設，倡導傳統民俗活動，藉以弘揚臺灣文化，並促進觀光事業之發展，激發師生與社會人士創作思考，培養良好互動之精神。\r\n\r\n*評審日期：民國 114 年 2 月 5 日（星期三）上午九時起。\r\n*參加作品自 114 年 1 月 7 日至 114 年 3 月 18 日止在清水紫雲巖展覽。', `organizer`='清水紫雲巖管理委員會', `address`='臺中市清水區', `start_date`='2025-01-07 00:00:00', `end_date`='2025-03-18 00:00:00', `location`='清水區（臺中市）=', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='http://www.tzuyunyen.org.tw/page10.html', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66bd32d026b3241b7cd56ac4', '【百年對話： 跨國移動者與臺博館藏的相遇】桃園市立圖書館聯合特展', '桃園市為引入東南亞外籍勞工人數最多的直轄市，本次邀請國立臺灣博物館展出東南亞地區相關藏品，以「藏品與社群連結」為主軸，結合本館的東南亞國家語言藏書，透過「人與物」和「物與書」的連結，展示新住民第一代勇敢地跨越國界，帶著對家族、國家、文化深層的念想，傳承在台灣出生與成長的新住民第二代，共同編織人與物、風土民情、信仰與藝術的故事。\n展覽期間包括中秋節和農曆新年，兩大重要傳統節日，在每逢佳節倍思親的時刻，特別以印尼峇里島神獸「巴龍（Barong）」展品(龍也是臺灣重要的文化象徵)進而串起臺灣與新住民母國之連結。\n另外，結合桃園分區資源中心辦理一系列相關友善多元族群閱讀推廣活動，藉此開啟多元文化交流與對話，讓各族群在探索及、認識彼此的過程，學會互相尊重彼此的文化差異，並鼓勵新住民、移工與市民朋友，多多利用公共圖書館的資源，讓他/她們看見自身，也能讓自身文化被看見，展現圖書館的文化平權。', '國立臺灣博物館', '330  桃園市桃園區 南平路303號', '2024-08-17 00:00:00', '2025-03-09 00:00:00', '桃園市立圖書館總館1樓享讀拾光', 25.00040024, 121.2996612, '免費', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40247', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【百年對話： 跨國移動者與臺博館藏的相遇】桃園市立圖書館聯合特展', `description`='桃園市為引入東南亞外籍勞工人數最多的直轄市，本次邀請國立臺灣博物館展出東南亞地區相關藏品，以「藏品與社群連結」為主軸，結合本館的東南亞國家語言藏書，透過「人與物」和「物與書」的連結，展示新住民第一代勇敢地跨越國界，帶著對家族、國家、文化深層的念想，傳承在台灣出生與成長的新住民第二代，共同編織人與物、風土民情、信仰與藝術的故事。\n展覽期間包括中秋節和農曆新年，兩大重要傳統節日，在每逢佳節倍思親的時刻，特別以印尼峇里島神獸「巴龍（Barong）」展品(龍也是臺灣重要的文化象徵)進而串起臺灣與新住民母國之連結。\n另外，結合桃園分區資源中心辦理一系列相關友善多元族群閱讀推廣活動，藉此開啟多元文化交流與對話，讓各族群在探索及、認識彼此的過程，學會互相尊重彼此的文化差異，並鼓勵新住民、移工與市民朋友，多多利用公共圖書館的資源，讓他/她們看見自身，也能讓自身文化被看見，展現圖書館的文化平權。', `organizer`='國立臺灣博物館', `address`='330  桃園市桃園區 南平路303號', `start_date`='2024-08-17 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='桃園市立圖書館總館1樓享讀拾光', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='免費', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40247', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66be867b26b3241b7cd56b96', '我走．我尋：當代原住民族的移動記事特展', '這是一檔關於「移動」的展覽，我們將呈現原住民族人在不同時代中所經歷的7則移動故事──從族群、部落，乃至於族人個體等多重層次的變化與變遷，大歷史如命運般的推力，如何捲動原住民族在地理、身分及情感上的搬遷與挪動，而族人將如何去訴說這份生命視角？\r\n\r\n單元「部落的回望」，談的是部落因不同國家政策而遷移的故事；單元「離鄉到都市」，談的是族人社群在市場推力下移動到都市的生活樣態；單元「身份的追溯」，則談出當代族人如何在今日追溯失落的族群認同。\r\n\r\n這些真切的生命故事與歷史記憶，是由臺南、高雄及屏東三區的9個原住民文物館共同書寫，館員及族人透過田野訪談、歷史資料蒐集，匯集許許多多的在地聲音而成，並與國立臺灣歷史博物館所共作完成的展覽。這不只是原住民族的故事，更是每一個渴望追溯這塊土地發生了甚麼事的人們，我們一起出發、一起探索、一起共鳴的故事。', '國立臺灣歷史博物館', '臺南市安南區長和路一段250號', '2025-01-01 00:00:00', '2025-03-16 00:00:00', '國立臺灣歷史博物館', 23.04869681, 120.1526189, '無資料', 'https://www.nmth.gov.tw/News_Content2.aspx?n=4105&s=220797', '[]') ON DUPLICATE KEY UPDATE `activity_name`='我走．我尋：當代原住民族的移動記事特展', `description`='這是一檔關於「移動」的展覽，我們將呈現原住民族人在不同時代中所經歷的7則移動故事──從族群、部落，乃至於族人個體等多重層次的變化與變遷，大歷史如命運般的推力，如何捲動原住民族在地理、身分及情感上的搬遷與挪動，而族人將如何去訴說這份生命視角？\r\n\r\n單元「部落的回望」，談的是部落因不同國家政策而遷移的故事；單元「離鄉到都市」，談的是族人社群在市場推力下移動到都市的生活樣態；單元「身份的追溯」，則談出當代族人如何在今日追溯失落的族群認同。\r\n\r\n這些真切的生命故事與歷史記憶，是由臺南、高雄及屏東三區的9個原住民文物館共同書寫，館員及族人透過田野訪談、歷史資料蒐集，匯集許許多多的在地聲音而成，並與國立臺灣歷史博物館所共作完成的展覽。這不只是原住民族的故事，更是每一個渴望追溯這塊土地發生了甚麼事的人們，我們一起出發、一起探索、一起共鳴的故事。', `organizer`='國立臺灣歷史博物館', `address`='臺南市安南區長和路一段250號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='國立臺灣歷史博物館', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='無資料', `source_url`='https://www.nmth.gov.tw/News_Content2.aspx?n=4105&s=220797', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66c3d01726b3241dc43a7674', '發現第一人巡迴展-臺中站', '考古犬收到委託，協助調查誰是「臺灣史前第一人」？透過時空資料庫搜尋大量考古資料，考古犬發現二條線索，分別位於馬祖亮島及臺南科學園區。憑藉生物人類學和考古學的專業知識，考古犬與夥伴逐步探索「第一人」的生活與生命故事。探尋過程來到臺中拜訪朋友安和石虎，也近一步了解臺中第一人的故事。\n\n\nThe“Archaeological dog”has been commissioned to help investigate who are“the first people of prehistoric Taiwan”. After searching a large amount of archaeological data in the spatiotemporal database, the “Archaeological Dog”has found two clues, which are respectively located in Liangdao of Matsu and in the Southern Taiwan Science Park. With expertise in biological anthropology and archaeology, the “Archaeological Dog”and his partners have gradually explored the lives of “the first people” in Taiwan and their life stories. During the search and exploration, the “Archaeological Dog” also came to Taichung to visit his friends AN,HE and Leopard Cat to learn more about the story of “the first people” in Taichung.\n\n ', '文化部文化資產局', '402  臺中市南區台中市南區復興路三段362號', '2024-09-17 00:00:00', '2025-03-02 00:00:00', 'B03藝文展覽館CD棟', 24.1334405, 120.6816622, '無資料', 'https://event.culture.tw/mocweb/reg/BOCH/Detail.init.ctr?actId=40021', '[]') ON DUPLICATE KEY UPDATE `activity_name`='發現第一人巡迴展-臺中站', `description`='考古犬收到委託，協助調查誰是「臺灣史前第一人」？透過時空資料庫搜尋大量考古資料，考古犬發現二條線索，分別位於馬祖亮島及臺南科學園區。憑藉生物人類學和考古學的專業知識，考古犬與夥伴逐步探索「第一人」的生活與生命故事。探尋過程來到臺中拜訪朋友安和石虎，也近一步了解臺中第一人的故事。\n\n\nThe“Archaeological dog”has been commissioned to help investigate who are“the first people of prehistoric Taiwan”. After searching a large amount of archaeological data in the spatiotemporal database, the “Archaeological Dog”has found two clues, which are respectively located in Liangdao of Matsu and in the Southern Taiwan Science Park. With expertise in biological anthropology and archaeology, the “Archaeological Dog”and his partners have gradually explored the lives of “the first people” in Taiwan and their life stories. During the search and exploration, the “Archaeological Dog” also came to Taichung to visit his friends AN,HE and Leopard Cat to learn more about the story of “the first people” in Taichung.\n\n ', `organizer`='文化部文化資產局', `address`='402  臺中市南區台中市南區復興路三段362號', `start_date`='2024-09-17 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='B03藝文展覽館CD棟', `latitude`=24.1334405, `longitude`=120.6816622, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/BOCH/Detail.init.ctr?actId=40021', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66c3d12126b3241dc43a769c', '遊賞鐵道風情－火車郵票特展', '火車的誕生為人類社會帶來劃時代的改變與進展，其功用、外觀及賦予人們的情感，是一頁頁迷人的故事篇章。為追憶火車的多元面貌及推廣鐵道文化，本館特規劃「遊賞鐵道風情－火車郵票特展」，期透過展出內容，引領民眾遊賞鐵路沿線迷人景致，一同探究火車演進的歷史變遷及其獨特魅力。', '郵政博物館', '高雄市三民區', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '三民區（高雄市）=', 22.64989883, 120.3179187, '優待票+15;全票+20', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='遊賞鐵道風情－火車郵票特展', `description`='火車的誕生為人類社會帶來劃時代的改變與進展，其功用、外觀及賦予人們的情感，是一頁頁迷人的故事篇章。為追憶火車的多元面貌及推廣鐵道文化，本館特規劃「遊賞鐵道風情－火車郵票特展」，期透過展出內容，引領民眾遊賞鐵路沿線迷人景致，一同探究火車演進的歷史變遷及其獨特魅力。', `organizer`='郵政博物館', `address`='高雄市三民區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='三民區（高雄市）=', `latitude`=22.64989883, `longitude`=120.3179187, `ticket_price`='優待票+15;全票+20', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66c5219526b3241dc43a76c7', '打開歷史現場 - 歷史 × 現場 × 再造', '「再造歷史現場」是文化部與地方政府攜手執行的重要計畫之一，期許能夠由下而上進行翻轉，從政策到治理，以文化為核心，讓世代傳承的文化資產可以重新回到當代人民的生活之中。再造歷史現場計畫規劃從單點的文化資產保存，結合地方文史、文化科技，推動「線」或「面」的區域保存；藉由「虛」（無形的歷史文化記憶）與「實」（有形生活空間、場域）、軟硬體的整合，以文化治理帶動城市或區域發展，進行場域空間的再生產並復育文化生態，讓歷史記憶回到生活，重建人與土地、人與人的連結。\n\n"Regeneration of Historic Sites" is one of the important projects jointly launched and implemented by the Ministry of Culture and local governments, which is expected to rebuild the national memory of cultural heritage through a bottom-up approach. With culture at its core, the project aims to bring the cultural assets which have been carried across generations back into the lives of contemporary people with policies and governance. The project "Regeneration of Historic Sites" plans to combine the preservation of cultural assets at a single point with local literature, history, culture and technology to promote the preservation of the cultural assets in a "line" or a “region”. Through the combination of "virtual" (intangible historical and cultural memory) and "real" (tangible living space, fields), and the integration of software and hardware, the project will drive the development of cities or regions through cultural governance and carry out the reproduction of space and restoration of cultural ecology, so that historical memory can return to people''s lives, thus to rebuild the connection between the people and land and among the people.', '文化部文化資產局', '402  臺中市南區台中市南區復興路三段362號', '2024-09-24 00:00:00', '2025-06-26 00:00:00', 'B09 雅堂館ABCD棟', 24.1334405, 120.6816622, '無資料', 'https://event.culture.tw/mocweb/reg/BOCH/Detail.init.ctr?actId=40024', '[]') ON DUPLICATE KEY UPDATE `activity_name`='打開歷史現場 - 歷史 × 現場 × 再造', `description`='「再造歷史現場」是文化部與地方政府攜手執行的重要計畫之一，期許能夠由下而上進行翻轉，從政策到治理，以文化為核心，讓世代傳承的文化資產可以重新回到當代人民的生活之中。再造歷史現場計畫規劃從單點的文化資產保存，結合地方文史、文化科技，推動「線」或「面」的區域保存；藉由「虛」（無形的歷史文化記憶）與「實」（有形生活空間、場域）、軟硬體的整合，以文化治理帶動城市或區域發展，進行場域空間的再生產並復育文化生態，讓歷史記憶回到生活，重建人與土地、人與人的連結。\n\n"Regeneration of Historic Sites" is one of the important projects jointly launched and implemented by the Ministry of Culture and local governments, which is expected to rebuild the national memory of cultural heritage through a bottom-up approach. With culture at its core, the project aims to bring the cultural assets which have been carried across generations back into the lives of contemporary people with policies and governance. The project "Regeneration of Historic Sites" plans to combine the preservation of cultural assets at a single point with local literature, history, culture and technology to promote the preservation of the cultural assets in a "line" or a “region”. Through the combination of "virtual" (intangible historical and cultural memory) and "real" (tangible living space, fields), and the integration of software and hardware, the project will drive the development of cities or regions through cultural governance and carry out the reproduction of space and restoration of cultural ecology, so that historical memory can return to people''s lives, thus to rebuild the connection between the people and land and among the people.', `organizer`='文化部文化資產局', `address`='402  臺中市南區台中市南區復興路三段362號', `start_date`='2024-09-24 00:00:00', `end_date`='2025-06-26 00:00:00', `location`='B09 雅堂館ABCD棟', `latitude`=24.1334405, `longitude`=120.6816622, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/BOCH/Detail.init.ctr?actId=40024', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66c5229426b3241dc43a7711', '亮島島尾考古遺址的發現、發掘到指定', '1️⃣發現：民國100年，連江縣前縣長楊綏生在亮島登島六十週年慶祝活動時，注意到戰備道路旁的 #貝塚。活動結束後，他馬上邀請考古學者來檢視，確立了 #亮島島尾I 和 #百勝港考古遺址 的存在！接著，進行全島調查，又陸續發現了 #亮島島尾II、III、IV考古遺址！\r\n\r\n2️⃣發掘的過程： 100年到104年間，陳仲玉老師帶領的馬祖亮島考古隊在島上進行了三次精彩的考古試掘。在亮島島尾I遺址，考古隊發掘出了兩座不同時期的墓葬，被親切地稱為「#亮島人」1號和2號，保存狀況超好，還成功提取了DNA樣本！\r\n\r\n除了墓葬外，遺址群還包括 #貝塚 和 #一般文化層 堆積，出土了許多火候不高的 #夾砂陶片，有些陶片上還有特別的紋飾，比如篦劃紋、壓印ㄑ字紋和附加堆紋等。石質遺物主要是 #打製石器，包括尖狀器、石錘和石片器。此外，考古隊還發掘出了很多魚類骨骼，顯示了亮島島尾的史前居民非常擅長利用當地的海洋資源呢。\r\n\r\n3️⃣亮島島尾考古遺址的指定：自103年連江縣政府將亮島島尾遺址公告為 #縣定考古遺址後，亮島島尾遺址仍持續多項學術研究計畫，研究成果對於亞洲大陸東部人群的移動有著關鍵意義，吸引了國際的高度關注。到了110年，文化部更是將它升格為 #國定考古遺址 哦！\r\n\r\n感謝看到這裡的你！偷偷跟你說，「#發現第一人_臺中站」將於113年9月17日在 #文化部文化資產園區 隆重開展，歡迎對考古及史前文化感興趣的大朋友小朋友來參觀！', '文化部文化資產局', '臺中市南區復興路三段362號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '文化部文化資產園區', 24.1329271, 120.6808935, '無資料', 'https://reurl.cc/Dl3O2m', '[]') ON DUPLICATE KEY UPDATE `activity_name`='亮島島尾考古遺址的發現、發掘到指定', `description`='1️⃣發現：民國100年，連江縣前縣長楊綏生在亮島登島六十週年慶祝活動時，注意到戰備道路旁的 #貝塚。活動結束後，他馬上邀請考古學者來檢視，確立了 #亮島島尾I 和 #百勝港考古遺址 的存在！接著，進行全島調查，又陸續發現了 #亮島島尾II、III、IV考古遺址！\r\n\r\n2️⃣發掘的過程： 100年到104年間，陳仲玉老師帶領的馬祖亮島考古隊在島上進行了三次精彩的考古試掘。在亮島島尾I遺址，考古隊發掘出了兩座不同時期的墓葬，被親切地稱為「#亮島人」1號和2號，保存狀況超好，還成功提取了DNA樣本！\r\n\r\n除了墓葬外，遺址群還包括 #貝塚 和 #一般文化層 堆積，出土了許多火候不高的 #夾砂陶片，有些陶片上還有特別的紋飾，比如篦劃紋、壓印ㄑ字紋和附加堆紋等。石質遺物主要是 #打製石器，包括尖狀器、石錘和石片器。此外，考古隊還發掘出了很多魚類骨骼，顯示了亮島島尾的史前居民非常擅長利用當地的海洋資源呢。\r\n\r\n3️⃣亮島島尾考古遺址的指定：自103年連江縣政府將亮島島尾遺址公告為 #縣定考古遺址後，亮島島尾遺址仍持續多項學術研究計畫，研究成果對於亞洲大陸東部人群的移動有著關鍵意義，吸引了國際的高度關注。到了110年，文化部更是將它升格為 #國定考古遺址 哦！\r\n\r\n感謝看到這裡的你！偷偷跟你說，「#發現第一人_臺中站」將於113年9月17日在 #文化部文化資產園區 隆重開展，歡迎對考古及史前文化感興趣的大朋友小朋友來參觀！', `organizer`='文化部文化資產局', `address`='臺中市南區復興路三段362號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='文化部文化資產園區', `latitude`=24.1329271, `longitude`=120.6808935, `ticket_price`='無資料', `source_url`='https://reurl.cc/Dl3O2m', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66ca7ad226b3241dc43a78ab', '白金鹽憶─臺灣鹽業檔案特展', '「白金鹽憶─臺灣鹽業檔案特展」精選1939年至2010年間具代表性的國家檔案，呈現臺灣鹽業興盛、衰退、停曬到轉型再利用的過程。\r\n本特展以「鹽」為主題，規劃4大單元展示及互動體驗，讓參觀者擁有不同的珍貴鹽業文化資產及檔案體驗樂趣，歡迎對臺灣鹽業有興趣的民眾，把握機會，撥冗蒞館觀賞。', '國家發展委員會檔案管理局', '南投縣南投市中正路2號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '臺灣省政資料館', 23.9557878, 120.686329, '無資料', 'https://www.archives.gov.tw/Publish.aspx?cnid=1708&p=5582', '[]') ON DUPLICATE KEY UPDATE `activity_name`='白金鹽憶─臺灣鹽業檔案特展', `description`='「白金鹽憶─臺灣鹽業檔案特展」精選1939年至2010年間具代表性的國家檔案，呈現臺灣鹽業興盛、衰退、停曬到轉型再利用的過程。\r\n本特展以「鹽」為主題，規劃4大單元展示及互動體驗，讓參觀者擁有不同的珍貴鹽業文化資產及檔案體驗樂趣，歡迎對臺灣鹽業有興趣的民眾，把握機會，撥冗蒞館觀賞。', `organizer`='國家發展委員會檔案管理局', `address`='南投縣南投市中正路2號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='臺灣省政資料館', `latitude`=23.9557878, `longitude`=120.686329, `ticket_price`='無資料', `source_url`='https://www.archives.gov.tw/Publish.aspx?cnid=1708&p=5582', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66ccd62a26b3241dc43a78f2', '蛙！！！30周年大戲〜我的寵物是恐龍', '無資料', '無資料', '嘉義市東區忠孝路275號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '嘉義市政府文化局音樂廳', 23.6959504, 120.52510397, '無資料', 'https://www.opentix.life/program/1821082225029763072', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蛙！！！30周年大戲〜我的寵物是恐龍', `description`='無資料', `organizer`='無資料', `address`='嘉義市東區忠孝路275號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='嘉義市政府文化局音樂廳', `latitude`=23.6959504, `longitude`=120.52510397, `ticket_price`='無資料', `source_url`='https://www.opentix.life/program/1821082225029763072', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66ce6e9e26b3241dc43a7937', '心繫臺灣：王育德文物捐贈展', '適逢王育德百歲冥誕，特展示有關王育德對文學、台語研究、台灣民主運動等多方面的貢獻，並延伸出相關的台北高等學校、海外黑名單展區。\n\n王育德（1924-1985），生於日治時期台南州台南市本町（現為民權路），就讀台北高校、東京帝國大學。228事件期間，兄長王育霖（1919-1947？）被便衣人員帶走後失蹤。1949年王育德逃到香港轉往日本，遭列黑名單，至辭世前都無法返回台灣。滯日期間，其仍致力於台灣相關研究論述，及台灣民主人權之推動。\n\n除王育德外，台灣文學界還有學者張良澤、作家賢伉儷郭松棻與李渝、台語作家胡民祥等人也曾被列入黑名單，他們被迫滯留海外這期間他們仍「心繫台灣」，念兹在兹。\n\n \n\n與台灣緊密連結的人生\n\n王育德流亡日本後，更致力於台灣文學、語言、歷史、文化、政治之論述，及台灣民主人權運動，都是以關懷台灣為中心。\n\n\n\n王育德全家福，王育德、夫人雪梅、長女曙薫、次女明理。1953年次女即將出生，屆時須報戶籍，王育德為逃亡偷渡前往警視廳自首。1954年獲准政治庇護，取得日本特別居留許可。同年，次女出生，全家拍照留影。王明理提供。\n\n  \n\n於自家書齋的王育德（約1980-1983）及其鋼筆，王明理捐贈館藏。許多台灣相關創作、研究都在此，用這支鋼筆完成。\n\n \n\n台北高等學校（1922-1945） \n\n為日治時期台灣唯一升大學的管道，國立臺灣師範大學之前身。學風自由，競爭激烈。培育出各界菁英，例如王育德（台語權威）及其兄長王育霖（日治時期在日本擔任檢察官），還有李登輝（前總統）、辜振甫及辜寬敏兄弟（企業家）、黃得時（台灣文學學者）、邱永漢（第34回直木獎得主）等人。\n\n\n\n就讀台北高校的王育德、東京帝國大學的王育霖，約1940-1942年。王明理提供。\n\n \n\n創作活動\n\n小說\n\n王育德喜愛文學，就讀台北高等學校文科時，首次創作的小說投稿該校文藝誌《翔風》。流亡日本後，1950年於小說家中河與一門下學習創作。戰後初期，於1946年龍瑛宗編輯的《中華日報》日文副刊發表小說〈春の戯れ〉（春之戲）。\n\n\n\n王育德與同門友人曾野綾子（左3，小說家中河與一門下），約1965年。王明理提供。\n\n\n\n1950年王育德自傳性小說手稿〈漂える民族：第一章空中霸王〉（漂泊的民族），王明理捐贈館藏。\n\n戲劇\n\n王育德創作劇本，也撰寫戲劇論述。首次編演的台語舞台劇《新生之朝》，於1945年台南「宮古座」戲院演出，為戰後首次演出的台語新劇。1985年去世前，也曾以居住日本的台灣人為主角創作〈僑領〉劇本，於世界台灣同鄉會演出。\n\n\n\n1945年王育德編演的《新生之朝》演員相片，王育德為中央扮演「陳老爺」的長者，時任職於台南一中。王明理提供。\n\n\n\n1985年王育德劇本〈僑領〉手稿，王明理捐贈館藏。\n\n \n\n研究論述\n\n論述\n\n王育德早於1946年《中華日報》日文欄發表〈彷徨的台灣文學〉。流亡日本後，1958年發表日文〈文學革命給台灣帶來的影響〉，此應為「戰後日本第一篇發表的台灣文學評論」。《王育德全集》也可見其長期針對台語、台灣文化、歷史、政治進行的研究、論述。\n\n台語研究\n\n1969年王育德以論文《閩音系研究》獲得東京大學文學博士學位，為第一位台語博士。王育德稱：「語言是民族的靈魂」、「會不會說台灣話，確實和台灣獨立沒有關係…但要促進獨立運動，發揚台灣民族主義是不可或缺的前提，因此必須讓台灣人明確意識到自己是台灣人」。\n\n\n\n1951年王育德台譯日本作家菊池寬的劇本〈父歸〉，王明理捐贈館藏。\n\n歷史\n\n王育德以台灣為主體撰寫台灣歷史，讓台灣人能了解自己歷史。1964年出版《台湾：苦悶するその歴史》，1979年出版華譯《台灣：苦悶的歷史》，其希望：「許許多多的人——不限於台灣人——發現並指出這本書的舛誤，使更好更充實的有關台灣人歷史的著作能夠出現。我本身和這本書只是為了台灣人的幸福而擊出的一支『犧牲打』而已」。\n\n\n\n1964年王育德《台湾：苦悶するその歴史》原文版，日本弘文堂，王明理捐贈館藏。\n\n \n\n台灣民主人權運動\n\n《台灣青年》\n\n台灣民主人權運動是王育德的終生志業，主要以1960年創立的台灣青年社《台灣青年》進行「台灣」研究論述，宣傳理念。創刊的〈社論〉，宣示其為台灣的「自由和幸福」而努力。\n\n\n\n1960年王育德和台灣留學生創立台灣青年社。王明理提供。\n\n\n\n《台灣青年》1960年創刊號，黃天橫捐贈館藏。發行至2002年500號「停刊紀念號」止。\n\n台籍日本兵補償運動\n\n王育德辭世前更致力於台籍日本兵補償運動，1975年成立「台灣人原日本兵之補償問題思考會」，並於《台灣青年》發聲。經各方人士協助，發展成日本人一起向日本政府請求補償的社會運動。王育德去世後，1987年日本國會通過法案，針對台籍日本兵傷、死者各發放弔慰金200萬日圓。雖金額不多，但那是台日共同努力的人權社會運動所獲得的極大成果。\n\n\n\n1975年3月2日於日本新宿，台籍日本兵補償運動之連署活動。王明理提供。\n\n\n\n1985年9月8日王育德絕筆手稿，〈「一寸の虫にも五分の魂」の戦い：二審は負けて勝つ 台湾人元日本兵の補償問題〉，可譯為〈「弱者也有志氣」之戰：二審敗也贏 台籍日本兵補償問題〉，描述台籍日本兵補償訴訟二審雖敗訴但實質已贏得勝利。王明理捐贈館藏。\n\n \n\n海外黑名單 \n\n除王育德外，學者張良澤、作家賢伉儷郭松棻與李渝、推廣台語的李豐明、台語作家胡民祥等人也曾被列入黑名單。這些有家歸不得的海外遊子，各自以自己的方式思念台灣、關懷台灣。\n\n\n\n1992年7月鍾肇政手稿，會長的話〈作家黑名單！！〉，鍾肇政捐贈館藏。1992年台灣筆會邀請張良澤回台參加研討會，當局拒絕其返台。當時的會長鍾肇政撰文，為「作家黑名單」提出最嚴正抗議。\n\n ', '國立台灣文學館', '700  臺南市中西區台南市中西區中正路1號', '2024-08-27 00:00:00', '2025-04-06 00:00:00', '國立台灣文學館-展覽室E', 22.9919899, 120.2045956, '無資料', 'https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=40069', '[]') ON DUPLICATE KEY UPDATE `activity_name`='心繫臺灣：王育德文物捐贈展', `description`='適逢王育德百歲冥誕，特展示有關王育德對文學、台語研究、台灣民主運動等多方面的貢獻，並延伸出相關的台北高等學校、海外黑名單展區。\n\n王育德（1924-1985），生於日治時期台南州台南市本町（現為民權路），就讀台北高校、東京帝國大學。228事件期間，兄長王育霖（1919-1947？）被便衣人員帶走後失蹤。1949年王育德逃到香港轉往日本，遭列黑名單，至辭世前都無法返回台灣。滯日期間，其仍致力於台灣相關研究論述，及台灣民主人權之推動。\n\n除王育德外，台灣文學界還有學者張良澤、作家賢伉儷郭松棻與李渝、台語作家胡民祥等人也曾被列入黑名單，他們被迫滯留海外這期間他們仍「心繫台灣」，念兹在兹。\n\n \n\n與台灣緊密連結的人生\n\n王育德流亡日本後，更致力於台灣文學、語言、歷史、文化、政治之論述，及台灣民主人權運動，都是以關懷台灣為中心。\n\n\n\n王育德全家福，王育德、夫人雪梅、長女曙薫、次女明理。1953年次女即將出生，屆時須報戶籍，王育德為逃亡偷渡前往警視廳自首。1954年獲准政治庇護，取得日本特別居留許可。同年，次女出生，全家拍照留影。王明理提供。\n\n  \n\n於自家書齋的王育德（約1980-1983）及其鋼筆，王明理捐贈館藏。許多台灣相關創作、研究都在此，用這支鋼筆完成。\n\n \n\n台北高等學校（1922-1945） \n\n為日治時期台灣唯一升大學的管道，國立臺灣師範大學之前身。學風自由，競爭激烈。培育出各界菁英，例如王育德（台語權威）及其兄長王育霖（日治時期在日本擔任檢察官），還有李登輝（前總統）、辜振甫及辜寬敏兄弟（企業家）、黃得時（台灣文學學者）、邱永漢（第34回直木獎得主）等人。\n\n\n\n就讀台北高校的王育德、東京帝國大學的王育霖，約1940-1942年。王明理提供。\n\n \n\n創作活動\n\n小說\n\n王育德喜愛文學，就讀台北高等學校文科時，首次創作的小說投稿該校文藝誌《翔風》。流亡日本後，1950年於小說家中河與一門下學習創作。戰後初期，於1946年龍瑛宗編輯的《中華日報》日文副刊發表小說〈春の戯れ〉（春之戲）。\n\n\n\n王育德與同門友人曾野綾子（左3，小說家中河與一門下），約1965年。王明理提供。\n\n\n\n1950年王育德自傳性小說手稿〈漂える民族：第一章空中霸王〉（漂泊的民族），王明理捐贈館藏。\n\n戲劇\n\n王育德創作劇本，也撰寫戲劇論述。首次編演的台語舞台劇《新生之朝》，於1945年台南「宮古座」戲院演出，為戰後首次演出的台語新劇。1985年去世前，也曾以居住日本的台灣人為主角創作〈僑領〉劇本，於世界台灣同鄉會演出。\n\n\n\n1945年王育德編演的《新生之朝》演員相片，王育德為中央扮演「陳老爺」的長者，時任職於台南一中。王明理提供。\n\n\n\n1985年王育德劇本〈僑領〉手稿，王明理捐贈館藏。\n\n \n\n研究論述\n\n論述\n\n王育德早於1946年《中華日報》日文欄發表〈彷徨的台灣文學〉。流亡日本後，1958年發表日文〈文學革命給台灣帶來的影響〉，此應為「戰後日本第一篇發表的台灣文學評論」。《王育德全集》也可見其長期針對台語、台灣文化、歷史、政治進行的研究、論述。\n\n台語研究\n\n1969年王育德以論文《閩音系研究》獲得東京大學文學博士學位，為第一位台語博士。王育德稱：「語言是民族的靈魂」、「會不會說台灣話，確實和台灣獨立沒有關係…但要促進獨立運動，發揚台灣民族主義是不可或缺的前提，因此必須讓台灣人明確意識到自己是台灣人」。\n\n\n\n1951年王育德台譯日本作家菊池寬的劇本〈父歸〉，王明理捐贈館藏。\n\n歷史\n\n王育德以台灣為主體撰寫台灣歷史，讓台灣人能了解自己歷史。1964年出版《台湾：苦悶するその歴史》，1979年出版華譯《台灣：苦悶的歷史》，其希望：「許許多多的人——不限於台灣人——發現並指出這本書的舛誤，使更好更充實的有關台灣人歷史的著作能夠出現。我本身和這本書只是為了台灣人的幸福而擊出的一支『犧牲打』而已」。\n\n\n\n1964年王育德《台湾：苦悶するその歴史》原文版，日本弘文堂，王明理捐贈館藏。\n\n \n\n台灣民主人權運動\n\n《台灣青年》\n\n台灣民主人權運動是王育德的終生志業，主要以1960年創立的台灣青年社《台灣青年》進行「台灣」研究論述，宣傳理念。創刊的〈社論〉，宣示其為台灣的「自由和幸福」而努力。\n\n\n\n1960年王育德和台灣留學生創立台灣青年社。王明理提供。\n\n\n\n《台灣青年》1960年創刊號，黃天橫捐贈館藏。發行至2002年500號「停刊紀念號」止。\n\n台籍日本兵補償運動\n\n王育德辭世前更致力於台籍日本兵補償運動，1975年成立「台灣人原日本兵之補償問題思考會」，並於《台灣青年》發聲。經各方人士協助，發展成日本人一起向日本政府請求補償的社會運動。王育德去世後，1987年日本國會通過法案，針對台籍日本兵傷、死者各發放弔慰金200萬日圓。雖金額不多，但那是台日共同努力的人權社會運動所獲得的極大成果。\n\n\n\n1975年3月2日於日本新宿，台籍日本兵補償運動之連署活動。王明理提供。\n\n\n\n1985年9月8日王育德絕筆手稿，〈「一寸の虫にも五分の魂」の戦い：二審は負けて勝つ 台湾人元日本兵の補償問題〉，可譯為〈「弱者也有志氣」之戰：二審敗也贏 台籍日本兵補償問題〉，描述台籍日本兵補償訴訟二審雖敗訴但實質已贏得勝利。王明理捐贈館藏。\n\n \n\n海外黑名單 \n\n除王育德外，學者張良澤、作家賢伉儷郭松棻與李渝、推廣台語的李豐明、台語作家胡民祥等人也曾被列入黑名單。這些有家歸不得的海外遊子，各自以自己的方式思念台灣、關懷台灣。\n\n\n\n1992年7月鍾肇政手稿，會長的話〈作家黑名單！！〉，鍾肇政捐贈館藏。1992年台灣筆會邀請張良澤回台參加研討會，當局拒絕其返台。當時的會長鍾肇政撰文，為「作家黑名單」提出最嚴正抗議。\n\n ', `organizer`='國立台灣文學館', `address`='700  臺南市中西區台南市中西區中正路1號', `start_date`='2024-08-27 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='國立台灣文學館-展覽室E', `latitude`=22.9919899, `longitude`=120.2045956, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=40069', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66cfb76e26b3241dc43a79f1', '第五特展室：山野兩路行－東勢卓蘭客庄聚落村史特展', '臺灣的客家族群依腔調分別有『四、海、大、平、安』等五大主要客語腔調，「大」指的是大埔客家，「平」則是饒平客家族群。\r\n本展覽以大甲溪及大安溪上的東勢、卓蘭及其周邊區域，帶出雙溪流域上的大埔客家、饒平客家為主軸規劃，透過語言腔調認識彼此，從古文書中探索客家先民與平埔族群互動的歷史足印；以風味獨特的「醢」和「打大粄」文化帶出族群間相互影響與區域性特色；從921地震後的重生到溫帶果樹栽種技術的創新展現客庄聚落的韌性。\r\n\r\n語言中認識彼此\r\n東勢、卓蘭雖分別位於大甲溪及大安溪畔，也使用不同的語言腔調，卻因地緣性、通婚、貿易等因素而形成一個共同生活圈。本單元將以具區域特色的童謠及詩歌文學作品，帶您認識生活在雙溪流域上的客家聚落特色。\r\n\r\n從文獻中看見開拓史\r\n本單元將以在地家族的古文書帶您了解客家與平埔族群、原住民族等不同族群間的互動。\r\n\r\n內心的苦甘與味緒\r\n從信仰中看早期因開墾、衝突的資源競合關係與族群互動，以及從在地具百年歷史的民俗文化與飲食探索區域生活特色。\r\n\r\n地動後的新秩序\r\n客家庄歷經九二一大地震後，在地居民攜手重建家園的歷程，以及不同時期因應時勢挑戰的產業變遷與反應。', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-01-01 00:00:00', '2025-03-06 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '無資料', 'https://thcdc.hakka.gov.tw/1241/1258/7372/120806/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第五特展室：山野兩路行－東勢卓蘭客庄聚落村史特展', `description`='臺灣的客家族群依腔調分別有『四、海、大、平、安』等五大主要客語腔調，「大」指的是大埔客家，「平」則是饒平客家族群。\r\n本展覽以大甲溪及大安溪上的東勢、卓蘭及其周邊區域，帶出雙溪流域上的大埔客家、饒平客家為主軸規劃，透過語言腔調認識彼此，從古文書中探索客家先民與平埔族群互動的歷史足印；以風味獨特的「醢」和「打大粄」文化帶出族群間相互影響與區域性特色；從921地震後的重生到溫帶果樹栽種技術的創新展現客庄聚落的韌性。\r\n\r\n語言中認識彼此\r\n東勢、卓蘭雖分別位於大甲溪及大安溪畔，也使用不同的語言腔調，卻因地緣性、通婚、貿易等因素而形成一個共同生活圈。本單元將以具區域特色的童謠及詩歌文學作品，帶您認識生活在雙溪流域上的客家聚落特色。\r\n\r\n從文獻中看見開拓史\r\n本單元將以在地家族的古文書帶您了解客家與平埔族群、原住民族等不同族群間的互動。\r\n\r\n內心的苦甘與味緒\r\n從信仰中看早期因開墾、衝突的資源競合關係與族群互動，以及從在地具百年歷史的民俗文化與飲食探索區域生活特色。\r\n\r\n地動後的新秩序\r\n客家庄歷經九二一大地震後，在地居民攜手重建家園的歷程，以及不同時期因應時勢挑戰的產業變遷與反應。', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-06 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='無資料', `source_url`='https://thcdc.hakka.gov.tw/1241/1258/7372/120806/', `image_url`='[]';
