INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('670c357f26b3241dc43a88c1', '國家地理女性經典影像展', '無資料', '無資料', '臺北市信義區光復南路133號', '2024-12-21 00:00:00', '2025-04-06 00:00:00', '松山文創園區 一號倉庫', 25.0435451, 121.5593832, '無資料', 'https://www.opentix.life/program/1843481299204407297', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國家地理女性經典影像展', `description`='無資料', `organizer`='無資料', `address`='臺北市信義區光復南路133號', `start_date`='2024-12-21 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='松山文創園區 一號倉庫', `latitude`=25.0435451, `longitude`=121.5593832, `ticket_price`='無資料', `source_url`='https://www.opentix.life/program/1843481299204407297', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('670da24726b3246898829357', '力的多重宇宙─臺灣運動文學特展', '展覽名稱:力的多重宇宙─臺灣運動文學特展\n\n展覽地點:國立臺灣文學館展覽室C\n\n展覽時間: 2024年10月17日至2025年9月14日\n\n展覽簡介:\n\n臺灣的運動文化不僅凝聚集體認同，也帶給個人身心放鬆的時刻。臺灣的運動文學發展也引領讀者一探不同力量打開的多重宇宙。\n\n臺灣的現代運動文化以及新文學同樣發軔於日治時期，在日本殖民統治之下，台灣人開始體驗到各式近代的運動競技，並自教育開始扎根進日常生活之中。戰後國民政府來台，運動競技與國家榮辱更加扣連，也開始轉向更為專業的運動培訓。八○年代隨著經濟水準上升、休閒時間增多，運動開始變成塑造生活風格的元素。而隨著媒體發展，國內外大型賽事的轉播與資訊流通逐步興盛，運動經驗鑲嵌進我們生活的周邊。\n\n文學描述各式運動的動態過程，時而化作賽場上的第一線，時而又俯瞰全場發展。精彩的賽評文字與報導嘗試重回現場，文學作品則深潛運動員的心理，隨著敘事發展，讓讀者也了解運動不單只是身體活動，還牽連到國族、社會、個人以及身體的多元可能。\n\n這場展覽將希望讓臺灣民眾發現運動在臺灣文學的發展，探索身體的多樣性到感受文學中的運動表現，呈現力的多重宇宙。\n\n ', '國立台灣文學館', '700  臺南市中西區中正路1號', '2024-10-17 00:00:00', '2025-09-14 00:00:00', '國立臺灣文學館-展覽室C', 22.9919899, 120.2045956, '無資料', 'https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=40084', '[]') ON DUPLICATE KEY UPDATE `activity_name`='力的多重宇宙─臺灣運動文學特展', `description`='展覽名稱:力的多重宇宙─臺灣運動文學特展\n\n展覽地點:國立臺灣文學館展覽室C\n\n展覽時間: 2024年10月17日至2025年9月14日\n\n展覽簡介:\n\n臺灣的運動文化不僅凝聚集體認同，也帶給個人身心放鬆的時刻。臺灣的運動文學發展也引領讀者一探不同力量打開的多重宇宙。\n\n臺灣的現代運動文化以及新文學同樣發軔於日治時期，在日本殖民統治之下，台灣人開始體驗到各式近代的運動競技，並自教育開始扎根進日常生活之中。戰後國民政府來台，運動競技與國家榮辱更加扣連，也開始轉向更為專業的運動培訓。八○年代隨著經濟水準上升、休閒時間增多，運動開始變成塑造生活風格的元素。而隨著媒體發展，國內外大型賽事的轉播與資訊流通逐步興盛，運動經驗鑲嵌進我們生活的周邊。\n\n文學描述各式運動的動態過程，時而化作賽場上的第一線，時而又俯瞰全場發展。精彩的賽評文字與報導嘗試重回現場，文學作品則深潛運動員的心理，隨著敘事發展，讓讀者也了解運動不單只是身體活動，還牽連到國族、社會、個人以及身體的多元可能。\n\n這場展覽將希望讓臺灣民眾發現運動在臺灣文學的發展，探索身體的多樣性到感受文學中的運動表現，呈現力的多重宇宙。\n\n ', `organizer`='國立台灣文學館', `address`='700  臺南市中西區中正路1號', `start_date`='2024-10-17 00:00:00', `end_date`='2025-09-14 00:00:00', `location`='國立臺灣文學館-展覽室C', `latitude`=22.9919899, `longitude`=120.2045956, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=40084', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('670da25026b324689882935c', '許敏雄老師-水彩畫B班師生成果展', '許敏雄老師-水彩畫B班師生成果展\n ', '國立國父紀念館', '無資料', '2024-10-14 00:00:00', '2025-12-31 00:00:00', '無資料', 0, 0, '無資料', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=40333', '[]') ON DUPLICATE KEY UPDATE `activity_name`='許敏雄老師-水彩畫B班師生成果展', `description`='許敏雄老師-水彩畫B班師生成果展\n ', `organizer`='國立國父紀念館', `address`='無資料', `start_date`='2024-10-14 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=40333', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('670f443926b324689882942b', '大南方多元史觀三部曲《珍珠—南方視野的女性藝術》', '《珍珠—南方視野的女性藝術》由高雄市立美術館與新加坡國家美術館、新加坡美術館共同策劃，以「南方」所匯聚的多元背景下代表性的女性藝術家為策展主題，關注邊緣化的歷史、性別、地理與藝術實踐，書寫多元且扎根於土地的故事，呈現了過去近三十年來臺灣與東南亞具開創性的女性藝術家創作，形塑當代女性藝術多元及繁盛紛陳的創作面貌，紀錄著女性視角下，小至個人、大至家國的生命歷程至今仍不斷帶給世人們的啟發，也透過本次展出呈現跨越海洋、島嶼邊界的跨族群與文化共同體，響應本展的展名：Ocean in Us。本展也是高美館三十週年館慶的代表展覽，並且是「大南方多元史觀」系列的第三個展覽，致力於展現南方文化的敘事。\r\n參展藝術家（按姓氏字母順位排列）︰阿拉瑪雅妮 Arahmaiani（印尼） 艾格妮絲・阿雷亞諾 Agnes Arellano（菲律賓） 張恩慈 Chang En-Tzu（臺灣） 陳慧嶠 Chen Hui-Chiao（臺灣） 陳云 Chen Yun（臺灣） 莊心珍 Chng Seok Tin（新加坡） 蒂梵妮・鍾 Tiffany Chung（越南/美國） 遷徙生態計畫 Migrant Ecologies Projects （新加坡） 童瓊 Quynh Dong（越南） 林介文 Labay Eyong（臺灣） 高媛 Gao Yuan（臺灣） 王良吟 Amanda Heng（新加坡） 何孟娟 Isa Ho（臺灣） 侯淑姿 Lulu Shur-Tzy Hou（臺灣） 薛保瑕 Hsueh Pao-Shia（臺灣） 黃文英 Huang Wen-Ying（臺灣） 洪素珍 Su-Chen Hung（臺灣） 梅拉・嘉思瑪 Mella Jaa', '高雄市立美術館', '高雄市鼓山區6鄰美術館路80號', '2025-01-01 00:00:00', '2025-03-16 00:00:00', '高雄市立美術館', 22.6566968, 120.2865511, '無資料', 'https://www.kmfa.gov.tw/ExhibitionDetailC001100.aspx?Cond=647d3144-ca24-4cf3-8e2c-a20a1c1e3465', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大南方多元史觀三部曲《珍珠—南方視野的女性藝術》', `description`='《珍珠—南方視野的女性藝術》由高雄市立美術館與新加坡國家美術館、新加坡美術館共同策劃，以「南方」所匯聚的多元背景下代表性的女性藝術家為策展主題，關注邊緣化的歷史、性別、地理與藝術實踐，書寫多元且扎根於土地的故事，呈現了過去近三十年來臺灣與東南亞具開創性的女性藝術家創作，形塑當代女性藝術多元及繁盛紛陳的創作面貌，紀錄著女性視角下，小至個人、大至家國的生命歷程至今仍不斷帶給世人們的啟發，也透過本次展出呈現跨越海洋、島嶼邊界的跨族群與文化共同體，響應本展的展名：Ocean in Us。本展也是高美館三十週年館慶的代表展覽，並且是「大南方多元史觀」系列的第三個展覽，致力於展現南方文化的敘事。\r\n參展藝術家（按姓氏字母順位排列）︰阿拉瑪雅妮 Arahmaiani（印尼） 艾格妮絲・阿雷亞諾 Agnes Arellano（菲律賓） 張恩慈 Chang En-Tzu（臺灣） 陳慧嶠 Chen Hui-Chiao（臺灣） 陳云 Chen Yun（臺灣） 莊心珍 Chng Seok Tin（新加坡） 蒂梵妮・鍾 Tiffany Chung（越南/美國） 遷徙生態計畫 Migrant Ecologies Projects （新加坡） 童瓊 Quynh Dong（越南） 林介文 Labay Eyong（臺灣） 高媛 Gao Yuan（臺灣） 王良吟 Amanda Heng（新加坡） 何孟娟 Isa Ho（臺灣） 侯淑姿 Lulu Shur-Tzy Hou（臺灣） 薛保瑕 Hsueh Pao-Shia（臺灣） 黃文英 Huang Wen-Ying（臺灣） 洪素珍 Su-Chen Hung（臺灣） 梅拉・嘉思瑪 Mella 