INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('670f605607f388994d7ae073', '2024-2025 來碗文學餐：經典上菜', '經典作品是重要的文化根基，應予以愛重、保留甚且發揚光大。紀州庵文學森林自開館以來的十餘年間，不斷努力推廣經典文學閱讀。\r\n\r\n2024年年末，紀州庵隆重推出「來碗文學餐──經典上菜」系列講座，邀請全台頂大中文系優秀青年學者，與大眾共賞經典文學風景。透過本講座的安排，讀者可以了解詩詞、戲曲、小說之內涵，並能快速建立經典文學的發展脈絡。\r\n\r\n本講座包含三大系列、共十八堂講座：\r\n\r\n「古典詩詞賞析」由祁立峰(台師大)、許銘全(清大)、徐國能(台師大)三位教授，講授樂府詩、陶淵明、謝靈運、李白、杜甫、辛棄疾六堂講座。\r\n\r\n「戲曲小說導讀」由汪詩珮(台大)、李志宏(台師大)、胡衍南(台師大)三位教授，講授《西廂記》、《牡丹亭》、《西遊記》、《儒林外史》、《金瓶梅》、《紅樓夢》六堂課程。\r\n\r\n「現代小說專題」由彭明偉(陽明交大)、蘇敏逸(成大)、郝譽翔(北教大)三位教授，講授魯迅、蕭紅、丁玲、張愛玲、韓少功、畢飛宇六堂課程。\r\n\r\n本系列講座提供實體課程與線上直播兩種參與方式，讓外縣市民眾也能跨越地域限制，體驗經典文學之美。\r\n', '紀州庵文學森林', '臺北市中正區同安街107號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '紀州庵文學森林', 25.03240487, 121.5198839, '★單堂500元。\r\n★單系列6堂(古典詩詞賞析、戲曲小說導讀、現代小說專題)，優惠價2400元，紀州庵舊學員優惠價2200元！\r\n★3系列全報早鳥優惠價6000元！', 'https://kishuan.org.tw/activity_detail1553.htm', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2024-2025 來碗文學餐：經典上菜', `description`='經典作品是重要的文化根基，應予以愛重、保留甚且發揚光大。紀州庵文學森林自開館以來的十餘年間，不斷努力推廣經典文學閱讀。\r\n\r\n2024年年末，紀州庵隆重推出「來碗文學餐──經典上菜」系列講座，邀請全台頂大中文系優秀青年學者，與大眾共賞經典文學風景。透過本講座的安排，讀者可以了解詩詞、戲曲、小說之內涵，並能快速建立經典文學的發展脈絡。\r\n\r\n本講座包含三大系列、共十八堂講座：\r\n\r\n「古典詩詞賞析」由祁立峰(台師大)、許銘全(清大)、徐國能(台師大)三位教授，講授樂府詩、陶淵明、謝靈運、李白、杜甫、辛棄疾六堂講座。\r\n\r\n「戲曲小說導讀」由汪詩珮(台大)、李志宏(台師大)、胡衍南(台師大)三位教授，講授《西廂記》、《牡丹亭》、《西遊記》、《儒林外史》、《金瓶梅》、《紅樓夢》六堂課程。\r\n\r\n「現代小說專題」由彭明偉(陽明交大)、蘇敏逸(成大)、郝譽翔(北教大)三位教授，講授魯迅、蕭紅、丁玲、張愛玲、韓少功、畢飛宇六堂課程。\r\n\r\n本系列講座提供實體課程與線上直播兩種參與方式，讓外縣市民眾也能跨越地域限制，體驗經典文學之美。\r\n', `organizer`='紀州庵文學森林', `address`='臺北市中正區同安街107號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='紀州庵文學森林', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='★單堂500元。\r\n★單系列6堂(古典詩詞賞析、戲曲小說導讀、現代小說專題)，優惠價2400元，紀州庵舊學員優惠價2200元！\r\n★3系列全報早鳥優惠價6000元！', `source_url`='https://kishuan.org.tw/activity_detail1553.htm', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('670ffa9626b324689882945f', '印象派150週年光影藝術展-高雄場', '無資料', '無資料', '高雄市三民區九如一路720號', '2024-12-28 00:00:00', '2025-04-06 00:00:00', '國立科學工藝博物館 一、二特展廳', 22.6414306, 120.3225512, '無資料', 'https://www.opentix.life/program/1843491177423667201', '[]') ON DUPLICATE KEY UPDATE `activity_name`='印象派150週年光影藝術展-高雄場', `description`='無資料', `organizer`='無資料', `address`='高雄市三民區九如一路720號', `start_date`='2024-12-28 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='國立科學工藝博物館 一、二特展廳', `latitude`=22.6414306, `longitude`=120.3225512, `ticket_price`='無資料', `source_url`='https://www.opentix.life/program/1843491177423667201', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('671017b826b3246898829492', '苗栗縣113學年度廣達游於藝「宋潮好好玩」巡迴展', '此展覽主要讓孩子認識先民的生活與藝術，體會南宋的創新精神，對文化傳承能做更深入的思考和探究，並轉化為未來文化創新成長的動能。\r\n展覽主題「宋『潮』好好玩」將南宋在傳統文化中的開創性作為核心重點，並將故宮國寶的複製品引入校園，讓師生以輕鬆自然的方式近距離接觸藝術。展品共分為四大主題：「時光倒轉八百年」、「宋『潮』大玩家」、「這樣生活才叫『潮』」及「佳評如『潮』．屹立不搖」，希望孩子們藉由這些形式多元且內容豐富的展覽，深入了解南宋時期的生活品味與美學風格，並促使他們延伸思考，與現代生活進行連結與比較。', '苗栗縣政府', '苗栗縣頭份市', '2025-02-24 00:00:00', '2025-03-16 00:00:00', '頭份市（苗栗縣）=', 24.67628243, 120.9189437, '無資料', 'https://www.miaoli.gov.tw/News_Content2.aspx?n=285&s=795651', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗栗縣113學年度廣達游於藝「宋潮好好玩」巡迴展', `description`='此展覽主要讓孩子認識先民的生活與藝術，體會南宋的創新精神，對文化傳承能做更深入的思考和探究，並轉化為未來文化創新成長的動能。\r\n展覽主題「宋『潮』好好玩」將南宋在傳統文化中的開創性作為核心重點，並將故宮國寶的複製品引入校園，讓師生以輕鬆自然的方式近距離接觸藝術。展品共分為四大主題：「時光倒轉八百年」、「宋『潮』大玩家」、「這樣生活才叫『潮』」及「佳評如『潮』．屹立不搖」，希望孩子們藉由這些形式多元且內容豐富的展覽，深入了解南宋時期的生活品味與美學風格，並促使他們延伸思考，與現代生活進行連結與比較。', `organizer`='苗栗縣政府', `address`='苗栗縣頭份市', `start_date`='2025-02-24 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='頭份市（苗栗縣）=', `latitude`=24.67628243, `longitude`=120.9189437, `ticket_price`='無資料', `source_url`='https://www.miaoli.gov.tw/News_Content2.aspx?n=285&s=795651', `image_url`='[]';
