INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6712af3c26b3246898829509', '「路徑・入境」臺灣文化路徑特展', '臺灣文化路徑打破過去單點式的文化資產保存形式，以「產業」與「族群」為主題，串聯有形與無形文化資產，梳理人與場域之間的關係變遷，整合出具有主題性，且能凝聚社群共識的文化路徑，共創更為深刻的文化網絡連結。\n\n本展覽介紹臺灣的水文化、糖業、煤礦業、多元族群、林業等五大主題之文化路徑經營成果，讓我們對於「臺灣文化」有更為多元、立體的視野和想像。文化路徑強調從具脈絡的敘事角度出發，傳遞文化系統性意義，帶領人們探究文化資產核心價值──「人」所構築的故事。讓我們一起「路徑・入境」走進文化路徑，體驗一場「超時空旅行」！\n\nThis exhibition introduces the achievements of Culture Routes of Taiwan under the five themes of hydrological characteristics, sugar industry, coal mining industry, diverse ethnic groups, and forestry. As a result, we can have a more diversified and three-dimensional vision and imagination of Taiwan culture. Culture Routes of Taiwan emphasize on conveying the systemic meaning of culture from a narrative perspective, and leads people to explore the core value of cultural assets, i.e. the stories constructed by ''human beings''. Embarking on the Cultural Routes of Taiwan, leading us to a journey of time.\n\n ', '文化部文化資產局', '402  臺中市南區台中市南區復興路三段362號', '2024-10-31 00:00:00', '2025-06-01 00:00:00', 'B03藝文展覽館AB館', 24.1334405, 120.6816622, '無資料', 'https://event.culture.tw/mocweb/reg/BOCH/Detail.init.ctr?actId=40030', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「路徑・入境」臺灣文化路徑特展', `description`='臺灣文化路徑打破過去單點式的文化資產保存形式，以「產業」與「族群」為主題，串聯有形與無形文化資產，梳理人與場域之間的關係變遷，整合出具有主題性，且能凝聚社群共識的文化路徑，共創更為深刻的文化網絡連結。\n\n本展覽介紹臺灣的水文化、糖業、煤礦業、多元族群、林業等五大主題之文化路徑經營成果，讓我們對於「臺灣文化」有更為多元、立體的視野和想像。文化路徑強調從具脈絡的敘事角度出發，傳遞文化系統性意義，帶領人們探究文化資產核心價值──「人」所構築的故事。讓我們一起「路徑・入境」走進文化路徑，體驗一場「超時空旅行」！\n\nThis exhibition introduces the achievements of Culture Routes of Taiwan under the five themes of hydrological characteristics, sugar industry, coal mining industry, diverse ethnic groups, and forestry. As a result, we can have a more diversified and three-dimensional vision and imagination of Taiwan culture. Culture Routes of Taiwan emphasize on conveying the systemic meaning of culture from a narrative perspective, and leads people to explore the core value of cultural assets, i.e. the stories constructed by ''human beings''. Embarking on the Cultural Routes of Taiwan, leading us to a journey of time.\n\n ', `organizer`='文化部文化資產局', `address`='402  臺中市南區台中市南區復興路三段362號', `start_date`='2024-10-31 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='B03藝文展覽館AB館', `latitude`=24.1334405, `longitude`=120.6816622, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/BOCH/Detail.init.ctr?actId=40030', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6712af4426b324689882950b', '黃慶源老師-山水寫生入門與山水寫生班師生成果展', '黃慶源老師-山水寫生入門與山水寫生班師生成果展\n\n ', '國立國父紀念館', '無資料', '2024-10-18 00:00:00', '2025-07-31 00:00:00', '無資料', 0, 0, '無資料', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=40338', '[]') ON DUPLICATE KEY UPDATE `activity_name`='黃慶源老師-山水寫生入門與山水寫生班師生成果展', `description`='黃慶源老師-山水寫生入門與山水寫生班師生成果展\n\n ', `organizer`='國立國父紀念館', `address`='無資料', `start_date`='2024-10-18 00:00:00', `end_date`='2025-07-31 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=40338', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6712b1cc26b3246898829533', '「千年俯瞰400：走向西拉雅族的原住民考古」特展', '本特展係要凸顯西拉雅族在臺南土地上的長久歷史，特展以原住民考古發掘行動成果作為展示，俯瞰意涵發掘過程中低頭對於坑面的遺物遺跡進行記錄，而「向」是西拉雅族傳統信仰中非常重要的角色，所有的儀式都和「向」有關，本次特展借用「走向」來說明西拉雅族追溯族源的行動。從西拉雅族的口傳，很早即居住在臺南，也超越400年的時間，此名稱旨在反思臺南建城400年歷史。\r\n\r\n', '國立臺灣史前文化博物館', '臺南市新市區南科三路10號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '國立臺灣史前文化博物館南科考古館', 23.08319496, 120.2923941, '全票+80;團體票+60;優待票+50', 'https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=40076&utm_source=NMP&utm_medium=query&utm_campaign=40076', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「千年俯瞰400：走向西拉雅族的原住民考古」特展', `description`='本特展係要凸顯西拉雅族在臺南土地上的長久歷史，特展以原住民考古發掘行動成果作為展示，俯瞰意涵發掘過程中低頭對於坑面的遺物遺跡進行記錄，而「向」是西拉雅族傳統信仰中非常重要的角色，所有的儀式都和「向」有關，本次特展借用「走向」來說明西拉雅族追溯族源的行動。從西拉雅族的口傳，很早即居住在臺南，也超越400年的時間，此名稱旨在反思臺南建城400年歷史。\r\n\r\n', `organizer`='國立臺灣史前文化博物館', `address`='臺南市新市區南科三路10號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='國立臺灣史前文化博物館南科考古館', `latitude`=23.08319496, `longitude`=120.2923941, `ticket_price`='全票+80;團體票+60;優待票+50', `source_url`='https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=40076&utm_source=NMP&utm_medium=query&utm_campaign=40076', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6712b1cc26b3246898829536', '李門木雕創作展“人生縮影”', '延續35年的創作理念和歷程，作品記錄對生命與人、事、物的關係，串連著歲月的堆積，只為一個理念，用木頭記錄著。\r\n\r\n 作品常是現實、現象的反射，或生命或情感或人性的感悟，以強烈的意念展現在作品中扭曲變形線條之技巧，是創作時靈感的實現及人性的探索。\r\n\r\n 生活美學也是創作的一個初衷，讓創作的作品能在生活空間中呈現或應用，不是止於展 演空間，讓所在空間充滿美感，心靈滿足。\r\n\r\n\r\n\r\n李門簡介\r\n1963年生,台灣南投縣人\r\n現居:台中縣龍井鄉東海街\r\n\r\n1997.2 南投縣立文化中心木雕創作個展\r\n1997.4 社區友好文化節展出\r\n1997-1999 加入台中雕塑協會\r\n1997 大墩民俗工藝錄\r\n1997.9 三義木雕博物館(地下室)邀請木雕個展\r\n1998.10 梧棲鄉土藝廊個展\r\n1999.2 台灣工藝美術接力展\r\n2001 苗栗縣立木雕類創作-佳作\r\n2002 台中廣播-大家來開講【世紀名人錄】專訪\r\n2002 台中市立文化局【李門心路-木雕創作個展】\r\n2003.1 荷蘭銀行(台中分行)藝術家聯展\r\n2007 台中火車站聯展\r\n2012 秋山堂聯展\r\n2013 三月山家展售\r\n2014 海塘美學空間展售\r\n2023 彰化美術館聯展\r\n2024 方圓美術館臺灣茶器聯展', '財團法人方圓文化藝術基金會', '臺南市將軍區1號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '臺南市方圓美術館', 23.20834413, 120.1276958, '門票+50', 'https://www.fy-mofa.org.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='李門木雕創作展“人生縮影”', `description`='延續35年的創作理念和歷程，作品記錄對生命與人、事、物的關係，串連著歲月的堆積，只為一個理念，用木頭記錄著。\r\n\r\n 作品常是現實、現象的反射，或生命或情感或人性的感悟，以強烈的意念展現在作品中扭曲變形線條之技巧，是創作時靈感的實現及人性的探索。\r\n\r\n 生活美學也是創作的一個初衷，讓創作的作品能在生活空間中呈現或應用，不是止於展 演空間，讓所在空間充滿美感，心靈滿足。\r\n\r\n\r\n\r\n李門簡介\r\n1963年生,台灣南投縣人\r\n現居:台中縣龍井鄉東海街\r\n\r\n1997.2 南投縣立文化中心木雕創作個展\r\n1997.4 社區友好文化節展出\r\n1997-1999 加入台中雕塑協會\r\n1997 大墩民俗工藝錄\r\n1997.9 三義木雕博物館(地下室)邀請木雕個展\r\n1998.10 梧棲鄉土藝廊個展\r\n1999.2 台灣工藝美術接力展\r\n2001 苗栗縣立木雕類創作-佳作\r\n2002 台中廣播-大家來開講【世紀名人錄】專訪\r\n2002 台中市立文化局【李門心路-木雕創作個展】\r\n2003.1 荷蘭銀行(台中分行)藝術家聯展\r\n2007 台中火車站聯展\r\n2012 秋山堂聯展\r\n2013 三月山家展售\r\n2014 海塘美學空間展售\r\n2023 彰化美術館聯展\r\n2024 方圓美術館臺灣茶器聯展', `organizer`='財團法人方圓文化藝術基金會', `address`='臺南市將軍區1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='臺南市方圓美術館', `latitude`=23.20834413, `longitude`=120.1276958, `ticket_price`='門票+50', `source_url`='https://www.fy-mofa.org.tw/', `image_url`='[]';
