INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6716a22626b324689882956a', '無資料', '1/30停課\n\n 本班12堂課\n\n\n	\n		\n			\n			課\n\n			程\n\n			大\n\n			綱\n			\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			養身關節操之一\n			\n			\n			  一、頸部旋轉。\n\n			  二、肩關節開合旋轉。\n\n			  三、左右甩臂。\n\n			  四、擴胸振臂。\n			\n		\n		\n			\n			2\n			\n			\n			養身關節操之二\n			\n			\n			  五、肘關節開合旋轉。\n\n			  六、腕部旋轉。\n\n			  七、輪臂拍打。\n\n			  八、握拳轉腰。\n			\n		\n		\n			\n			3\n			\n			\n			養身關節操之三\n			\n			\n			  九、扶腰旋轉。\n\n			  十、胯關節開合。\n\n			  十一、併膝旋轉。\n\n			  十二、踝關節旋轉。\n			\n		\n		\n			\n			4\n			\n			\n			易筋經第一式與第二式\n			\n			\n			（拱手當胸）肺經分解動作、（兩臂橫擔）大腸經分解動作。\n			\n		\n		\n			\n			5\n			\n			\n			易筋經第三式與第四式\n			\n			\n			（掌托天門）胃經分解動作、（摘星換斗式）脾經分解動作。\n			\n		\n		\n			\n			6\n			\n			\n			易筋經第五式與第六式\n			\n			\n			（出爪亮翅式）心經分解動作、\n\n			（倒拽九牛尾式）小腸經分解動作。\n			\n		\n		\n			\n			7\n			\n			\n			易筋經第七式與第八式\n			\n			\n			（九鬼拔馬刀式）膀胱經分解動作\n\n			（三盤落地式）腎經分解動作。\n			\n		\n		\n			\n			8\n			\n			\n			易筋經第九式與第十式\n			\n			\n			（青龍探爪式）心包經分解動作、\n\n			（臥虎撲食式）三焦經分解動作。\n			\n		\n		\n			\n			9\n			\n			\n			易筋經第十一式與第十二式\n			\n			\n			（打躬式）膽經分解動作、（掉尾式）肝經分解動作。\n			\n		\n		\n			\n			10\n			\n			\n			複習易筋經第一式到第六式\n			\n			\n			  複習並說明易筋經上半功法重點與經絡穴道關聯。\n			\n		\n		\n			\n			11\n			\n			\n			複習易筋經第七式到第十二式\n			\n			\n			  複習並說明易筋經下半功法重點與經絡穴道關聯。\n			\n		\n		\n			\n			12\n			\n			\n			易筋經總複習\n			\n			\n			  易筋經一到十二式總複習並解答學員課程內容問題。\n			\n		\n	\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', 'E306教室', 25.0367564, 121.519047, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='1/30停課\n\n 本班12堂課\n\n\n	\n		\n			\n			課\n\n			程\n\n			大\n\n			綱\n			\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			養身關節操之一\n			\n			\n			  一、頸部旋轉。\n\n			  二、肩關節開合旋轉。\n\n			  三、左右甩臂。\n\n			  四、擴胸振臂。\n			\n		\n		\n			\n			2\n			