INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6716a22726b3246898829572', '無資料', '2/3為第1堂課開始\n\n★請學員自備有厚度的止滑襪於上課時換穿\n\n  將針對高齡者體適能狀況設計授課內容，並根據實際能力調整進退階及循序漸進調整強度。利用簡單輕便、日常生活易取得的物品當器材，進行安全且有效運動訓練，達到健康促進及延緩失能。\n\n \n\n\n\n	\n		\n			\n			週次\n			\n			\n			內容及進度\n			\n		\n		\n			\n			第1週\n			\n			\n			認識核心（肌力+爆發）\n			介紹核心肌群的重要性，如何加強與訓練。\n		\n		\n			\n			第2週\n			\n			反擊退化的武器（肌力+協調）\n			複習核心肌群，並加強上肢與下肢肌群。\n		\n		\n			\n			第3週\n			\n			\n			燃脂降三高（心肺+協調）\n			跟者節奏超慢跑，說明快走，慢跑的差別，提高心肺能力。\n		\n		\n			\n			第4週\n			\n			\n			淪肌浹髓（肌力+協調）\n			加強肌力和綜合動作。\n		\n		\n			\n			第5週\n			\n			載歌載舞（心肺+協調）\n			跟著有節奏的舞曲，帶者學生們歡樂共舞。\n		\n		\n			\n			第6週\n			\n			\n			捷足先登（敏捷+爆發力）\n			如何正確地爬樓梯（視天候調整）。\n		\n		\n			\n			第7週\n			\n			踢進中正紀念堂（爆發力+平衡）\n			平衡訓練並加上跆拳道運動的元素。\n		\n		\n			\n			第8週\n			\n			\n			手舞足蹈（心肺+認知）\n			搭配歌曲，邊唱邊跳，享受音樂沉靜在舞蹈中。\n		\n		\n			\n			第9週\n			\n			舒壓美體（柔軟度+肌力）\n			透過瑜伽的引導進入體位法，有肌力同時也要有柔軟度。\n		\n		\n			\n			第10週\n			\n			\n			拔山舉鼎（肌力+敏捷）\n			搭配器材做肌力訓練。\n		\n		\n			\n			第11週\n			\n			強身健骨（肌力+平衡）\n			複習上週的肌力動作，並加上平衡的練習\n		\n		\n			\n			第12週\n			\n			身強力壯（肌力+認知）\n			融入肌力訓練與認知元素並分組互相教學以得知是否有正確的觀念與知識。\n		\n		\n			\n			第13週\n			\n			\n			舞態生風（心肺+協調）\n			跟隨有節奏的舞曲，享受音樂並融入其中。\n		\n		\n			\n			第14週\n			\n			歡欣鼓舞（全面性體適能）\n		\n	\n\n\n \n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', 'W319教室', 25.0367564, 121.519047, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='2/3為第1堂課開始\n\n★請學員自備有厚度的止滑襪於上課時換穿\n\n  將針對高齡者體適能狀況設計授課內容，並根據實際能力調整進退階及循序漸進調整強度。利用簡單輕便、日常生活易取得的物品當器材，進行安全且有效運動訓練，達到健康促進及延緩失能。\n\n \n\n\n\n	\n		\n			\n			週次\n			\n			\n			內容及進度\n			\n		\n		\n			\n			第1週\n			\n			\n			認識核心（肌力+爆發）\n			介紹核心肌群的重要性，如何加強與訓練。\n		\n		\n			\n			第2週\n			\n			反擊退化的武器（肌力+協調）\n			複習核心肌群，並加強上肢與下肢肌群。\n		\n		\n			\n			第3週\n			\n			\n			燃脂降三高（心肺+協調）\n			跟者節奏超慢跑，說明快走，慢跑的差別，提高心肺能力。\n		\n		\n			\n			第4週\n			\n			\n			淪肌浹髓（肌力+協調）\n			加強肌力和綜合動作。\n		\n		\n			\n			第5週\n			\n			載歌載舞（心肺+協調）\n			跟著有節奏的舞曲，帶者學生們歡樂共舞。\n		\n		\n			\n			第6週\n			\n			\n			捷足先登（敏捷+爆發力）\n			如何正確地爬樓梯（視天候調整）。\n		\n		\n			\n			第7週\n			\n			踢進中正紀念堂（爆發力+平衡）\n			平衡訓練並加上跆拳道運動的元素。\n		\n		\n			\n			第8週\n			\n			\n			手舞足蹈（心肺+認知）\n			搭配歌曲，邊唱邊跳，享受音樂沉靜在舞蹈中。\n		\n		\n			\n			第9週\n			\n			舒壓美體（柔軟度+肌力）\n			透過瑜伽的引導進入體位法，有肌力同時也要有柔軟度。\n		\n		\n			\n			第10週\n			\n			\n			拔山舉鼎（肌力+敏捷）\n			搭配器材做肌力訓練。\n		\n		\n			\n			第11週\n			\n			強身健骨（肌力+平衡）\n			複習上週的肌力動作，並加上平衡的練習\n		\n		\n			\n			第12週\n			\n			身強力壯（肌力+認知）\n			融入肌力訓練與認知元素並分組互相教學以得知是否有正確的觀念與知識。\n		\n		\n			\n			第13週\n			\n			\n			舞態生風（心肺+協調）\n			跟隨有節奏的舞曲，享受音樂並融入其中。\n		\n		\n			\n			第14週\n			\n			歡欣鼓舞（全面性體適能）\n		\n	\n\n\n \n\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `location`='W319教室', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6716a22726b3246898829574', '無資料', '1/28停課\n\n1、中國最後武狀元常東昇宗師嫡傳。\n\n2、南京中央國術館副館長李景林結合楊氏與武當益壽延年之完整功法，包括活絡鬆身法、增功練架法、靈活實用法、深息吞吐法。\n\n3、基礎班特別重視重心平衡之控制，增加手腳協調性及律動感，提升並訓練小肌肉組合運用，減緩四肢關節的負擔。\n\n4、武當丹派梳服功，理經絡，順氣脈，搓筋膜，強肌腱，開關竅，通穴道。  \n\n\n	\n		\n			\n			課\n\n			程\n\n			大\n\n			綱\n			\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.說明太極之含意與太極拳之對應。\n\n			2.手眼身步法君臣佐輔環環相扣之重要。\n\n			3.調息法一至四式[雲手樁]。\n\n			4.三抱圓起收歸一和息法之一。\n\n			5.挑掌排打功。\n\n			6.展臂伸筋法[採水果與扁擔架] 。\n			\n		\n		\n			\n			2\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.介紹常太極之特色、功能、傳承與天人一體關係。\n\n			2.常東昇宗師生平事蹟。\n\n			3.調息法五至七式[雲手樁] 。\n\n			4.三抱圓和息法之二。\n\n			5.挑掌排打功。\n\n			6.展臂伸筋法[採水果與扁擔架] 。\n			\n		\n		\n			\n			3\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.陰陽虛實、進退攻防、正反合圓弧繞之闡釋。\n\n			2.太極十三勢特色簡介。\n\n			3.雲手樁全複習。\n\n			4.三抱圓調息與挑掌排打功法複習。\n			\n		\n		\n			\n			4\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.攬雀尾左右連環。2.溜腿十四式。3.單鞭挒手樁。4.雲手樁全複習。\n			\n		\n		\n			\n			5\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1. 攬雀尾左右連環。\n\n			2.溜腿十四式。\n\n			3.提手琵琶樁。\n\n			4.雲手樁全複習。\n			\n		\n		\n			\n			6\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.攬雀尾左右逢源套路。\n\n			2.雲手樁全複習。\n\n			3.順風扯旗樁。\n\n			4.白鶴琵琶樁。\n			\n		\n		\n			\n			7\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.攬雀尾左右逢源套路。\n\n			2.順風扯旗樁.白鶴琵琶樁複習。\n\n			3.元飛捧樁。\n			\n		\n		\n			\n			8\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.攬雀尾左右八法活步套路。\n\n			2.迴身提手樁。\n\n			3.四方摟膝樁。\n			\n		\n		\n			\n			9\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.迴身提手樁。\n\n			2.四方摟膝樁。\n\n			3.攬雀尾左右八法活步套路。\n\n			4.採挒肘靠介紹。\n			\n		\n		\n			\n			10\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.攬雀尾連環、逢源、四方、八法整合複習。\n\n			2.單推手定步。\n			\n		\n		\n			\n			11\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.攬雀尾連環、逢源、四方、 八法整合複習。\n\n			2.扳攬捶樁。3.單推手活步。\n			\n		\n		\n			\n			12\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.攬雀尾四方一網套路。\n\n			2.攬雀尾四合一套路。\n\n			3.單推手活步。\n			\n		\n		\n			\n			13\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.攬雀尾四方一網套路。\n\n			2.攬雀尾四合一套路。\n\n			3.單推手活步。\n\n			4.雙推手定步。\n			\n		\n		\n			\n			14\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.常太極第一段套路介紹[至如封似閉十字手] 。\n\n			2.雙推手活步。\n			\n		\n		\n			\n			15\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.常太極第一段套路介紹[至如封似閉十字手] 。\n\n			2.單雙手定活步推手複習。\n\n			3.功法樁法總複習。\n\n			4.招式動作實用簡介。\n			\n		\n	\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', 'E305教室', 25.0367564, 121.519047, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='1/28停課\n\n1、中國最後武狀元常東昇宗師嫡傳。\n\n2、南京中央國術館副館長李景林結合楊氏與武當益壽延年之完整功法，包括活絡鬆身法、增功練架法、靈活實用法、深息吞吐法。\n\n3、基礎班特別重視重心平衡之控制，增加手腳協調性及律動感，提升並訓練小肌肉組合運用，減緩四肢關節的負擔。\n\n4、武當丹派梳服功，理經絡，順氣脈，搓筋膜，強肌腱，開關竅，通穴道。  \n\n\n	\n		\n			\n			課\n\n			程\n\n			大\n\n			綱\n			\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.說明太極之含意與太極拳之對應。\n\n			2.手眼身步法君臣佐輔環環相扣之重要。\n\n			3.調息法一至四式[雲手樁]。\n\n			4.三抱圓起收歸一和息法之一。\n\n			5.挑掌排打功。\n\n			6.展臂伸筋法[採水果與扁擔架] 。\n			\n		\n		\n			\n			2\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.介紹常太極之特色、功能、傳承與天人一體關係。\n\n			2.常東昇宗師生平事蹟。\n\n			3.調息法五至七式[雲手樁] 。\n\n			4.三抱圓和息法之二。\n\n			5.挑掌排打功。\n\n			6.展臂伸筋法[採水果與扁擔架] 。\n			\n		\n		\n			\n			3\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.陰陽虛實、進退攻防、正反合圓弧繞之闡釋。\n\n			2.太極十三勢特色簡介。\n\n			3.雲手樁全複習。\n\n			4.三抱圓調息與挑掌排打功法複習。\n			\n		\n		\n			\n			4\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.攬雀尾左右連環。2.溜腿十四式。3.單鞭挒手樁。4.雲手樁全複習。\n			\n		\n		\n			\n			5\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1. 攬雀尾左右連環。\n\n			2.溜腿十四式。\n\n			3.提手琵琶樁。\n\n			4.雲手樁全複習。\n			\n		\n		\n			\n			6\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.攬雀尾左右逢源套路。\n\n			2.雲手樁全複習。\n\n			3.順風扯旗樁。\n\n			4.白鶴琵琶樁。\n			\n		\n		\n			\n			7\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.攬雀尾左右逢源套路。\n\n			2.順風扯旗樁.白鶴琵琶樁複習。\n\n			3.元飛捧樁。\n			\n		\n		\n			\n			8\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.攬雀尾左右八法活步套路。\n\n			2.迴身提手樁。\n\n			3.四方摟膝樁。\n			\n		\n		\n			\n			9\n			\n			\n			樂活有氧長壽太極\n			\n			\n			1.迴身提手樁。\n\n		