INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6716a22826b324689882958a', '無資料', '1/28停課\n\n★請自備4B素描筆、軟橡皮、A4紙\n\n★本表所安排之課題及教學內容將依據學員程度及學習狀況斟酌調整。\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			意象速寫-啟發繪畫思維B\n			\n			\n			授課老師\n			\n			\n			王  弈\n			\n		\n		\n			\n			課\n\n			程\n\n			大\n\n			綱\n			\n			\n			次序\n			\n			\n			課程主題\n			\n			\n			教學內容\n			\n		\n		\n			\n			1\n			\n			\n			速寫到底是什麼呢？\n			\n			\n			放鬆了對繪畫規則的束縛就是速寫。\n			\n		\n		\n			\n			2\n			\n			\n			速寫需要懂素描嗎？\n			\n			\n			需要，故每個主題先學素描後速寫。\n			\n		\n		\n			\n			3\n			\n			\n			感覺速寫很像亂畫！\n			\n			\n			初學速寫就該隨性亂畫並破除規則。\n			\n		\n		\n			\n			4\n			\n			\n			覺得自己沒有創意！\n			\n			\n			回想兒時抬頭眺望雲卷雲舒的童年。\n			\n		\n		\n			\n			5\n			\n			\n			如何讓線畫的柔順？\n			\n			\n			使用心象能力，想像旋律幻化成線。\n			\n		\n		\n			\n			6\n			\n			\n			速寫對位如何掌握？\n			\n			\n			利用探線初定位，再用複線做微調。\n			\n		\n		\n			\n			7\n			\n			\n			畫面焦點如何選定？\n			\n			\n			以區塊範圍來定焦更勝以主體定焦。\n			\n		\n		\n			\n			8\n			\n			\n			如何表現光影明暗？\n			\n			\n			物體受光適合單線，背光則畫複線。\n			\n		\n		\n			\n			9\n			\n			\n			畫面背景很難表現！\n			\n			\n			背景可運用線條或宣染來表達意境。\n			\n		\n		\n			\n			10\n			\n			\n			速寫筆觸如何表現！\n			\n			\n			將物體細節，看成符號疊加的狀態。\n			\n		\n		\n			\n			11\n			\n			\n			畫真人時他會亂動！\n			\n			\n			記憶前一刻模樣，推敲後來的姿態。\n			\n		\n		\n			\n			12\n			\n			\n			怎樣畫才算有畫風？\n			\n			\n			除非刻意模仿，否則畫風本自俱足。\n			\n		\n		\n			\n			13\n			\n			\n			水彩也能表現速寫？\n			\n			\n			速寫追求意境，任何媒材皆能創作。\n			\n		\n		\n			\n			14\n			\n			\n			速寫與音樂有關嗎？\n			\n			\n			速寫，是一種被視覺化之後的音樂。\n			\n		\n		\n			\n			15\n			\n			\n			覺得自己進步很慢！\n			\n			\n			掌握訓練為目標，避免慣性去塗鴉。\n			\n		\n	\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', 'W320教室', 25.0367564, 121.519047, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='1/28停課\n\n★請自備4B素描筆、軟橡皮、A4紙\n\n★本表所安排之課題及教學內容將依據學員程度及學習狀況斟酌調整。\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			意象速寫-啟發繪畫思維B\n			\n			\n			授課老師\n			\n			\n			王  弈\n			\n		\n		\n			\n			課\n\n			程\n\n			大\n\n			綱\n			\n			\n			次序\n			\n			\n			課程主題\n			\n			\n			教學內容\n			\n		\n		\n			\n			1\n			\n			\n			速寫到底是什麼呢？\n			\n			\n			放鬆了對繪畫規則的束縛就是速寫。\n			\n		\n		\n			\n			2\n			\n			\n			速寫需要懂素描嗎？\n			\n			\n			需要，故每個主題先學素描後速寫。\n			\n		\n		\n			\n			3\n			\n			\n			感覺速寫很像亂畫！\n			\n			\n			初學速寫就該隨性亂畫並破除規則。\n			\n		\n		\n			\n			4\n			\n			\n			覺得自己沒有創意！\n			\n			\n			回想兒時抬頭眺望雲卷雲舒的童年。\n			\n		\n		\n			\n			5\n			\n			\n			如何讓線畫的柔順？\n			\n			\n			使用心象能力，想像旋律幻化成線。\n			\n		\n		\n			\n			6\n			\n			\n			速寫對位如何掌握？\n			\n			\n			利用探線初定位，再用複線做微調。\n			\n		\n		\n			\n			7\n			\n			\n			畫面焦點如何選定？\n			\n			\n			以區塊範圍來定焦更勝以主體定焦。\n			\n		\n		\n			\n			8\n			\n			\n			如何表現光影明暗？\n			\n			\n			物體受光適合單線，背光則畫複線。\n			\n		\n		\n			\n			9\n			\n			\n			畫面背景很難表現！\n			\n			\n			背景可運用線條或宣染來表達意境。\n			\n		\n		\n			\n			10\n			\n			\n			速寫筆觸如何表現！\n			\n			\n			將物體細節，看成符號疊加的狀態。\n			\n		\n		\n			\n			11\n			\n			\n			畫真人時他會亂動！\n			\n			\n			記憶前一刻模樣，推敲後來的姿態。\n			\n		\n		\n			\n			12\n			\n			\n			怎樣畫才算有畫風？\n			\n			\n			除非刻意模仿，否則畫風本自俱足。\n			\n		\n		\n			\n			13\n			\n			\n			水彩也能表現速寫？\n			\n			\n			速寫追求意境，任何媒材皆能創作。\n			\n		\n		\n			\n			14\n			\n			\n			速寫與音樂有關嗎？\n			\n			\n			速寫，是一種被視覺化之後的音樂。\n			\n		\n		\n			\n			15\n			\n			\n			覺得自己進步很慢！\n			\n			\n			掌握訓練為目標，避免慣性去塗鴉。\n			\n		\n	\n\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `location`='W320教室', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
