INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6716a22a26b3246898829598', '無資料', '1/27停課\n\n有鑑於現代人不均衡的生活方式及長期錯誤的坐姿、站姿及走路方式，但我們卻毫不自知，造成骨盆歪斜影響到背部脊柱的負擔。這些錯誤姿勢可以透過正位瑜珈動作進行矯正，不僅可以加強較弱的肌肉群、舒緩關節肌肉緊張，達到預防跟矯正的作用\n\n透過簡單的瑜珈體位法檢視自己的動作是否真的做正確。從最基本的正確念出發、了解正確的姿勢、體位，對人體健康的重要性。 \n\n\n	\n		\n			\n			週次\n			\n			\n			課程主題\n			\n			\n			教學內容\n			\n		\n		\n			\n			第1週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第2週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第3週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第4週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第5週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第6週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第7週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第8週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第9週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第10週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第11週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第12週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第13週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第14週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n		\n			\n			第15週\n			\n			\n			正位基礎動作練習。\n			\n			\n			熱身動作、呼吸練習、主題動作、緩和大休息。\n			\n		\n	\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', 'E306教室', 25.0367564, 121.519047, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='1/27停課\n\n有鑑於現代人不均衡的生活方式及長期錯誤的坐姿、站姿及走路方式，但我們卻毫不自知，造成骨盆歪斜影響到背部脊柱的負擔。這些錯誤姿