INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6716a22a26b32468988295a1', '無資料', '1/27停課\n\n陳醫師從事中醫臨床工作超過三十年，除醫治疑難雜症，教導民眾養生及保健之道。\n\n \n\n\n	\n		\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			1\n			感冒的中醫治療與康復\n			討論感冒的中醫治療與如何預防？\n		\n		\n			2\n			感冒初期常用中藥介紹\n			介紹感冒初期常用中藥：生薑、紫蘇、薄荷..\n		\n		\n			3\n			我的火氣大嗎？\n			討論中醫火氣大的相關問題。\n		\n		\n			4\n			降火氣常用中藥介紹(1)\n			介紹降火氣常用中藥：石膏、竹葉、梔子..\n		\n		\n			5\n			降火氣常用中藥介紹(2)\n			黃連、金銀花、魚腥草、地骨皮...\n		\n		\n			6\n			為什麼會便秘？\n			討論便秘的原因與治療及如何保健。\n		\n		\n			7\n			便祕常用中藥介紹\n			介紹便祕常用中藥：大黃、蘆薈.....\n		\n		\n			8\n			風濕痛是類風溼性關節炎嗎\n			討論肌肉關節酸痛的中醫治療。\n		\n		\n			9\n			常用袪風除濕中藥介紹\n			介紹常用袪風除濕中藥：木瓜、桑枝、五加皮..\n		\n		\n			10\n			我的溼氣重嗎？\n			討論中醫濕氣的相關問題。\n		\n		\n			11\n			常用化濕利濕中藥介紹\n			介紹常用化濕利濕中藥：豆蔻、茯苓、車前子\n		\n		\n			12\n			中醫常講的寒症是甚麼？\n			討論中醫寒證的相關問題。\n		\n		\n			13\n			常用溫裡中藥介紹\n			介紹常用溫裡中藥：乾薑、肉桂、胡椒....\n		\n		\n			14\n			甚麼是食積症？\n			討論中醫食積的中醫治療與養生。                                                                                                    \n		\n		\n			15\n			常用中藥消食藥介紹\n			介紹常用中藥消食藥：山楂、麥芽、雞內金                                                                               \n		\n	\n\n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', 'W311教室', 25.0367564, 121.519047, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='1/27停課\n\n陳醫師從事中醫臨床工作超過三十年，除醫治疑難雜症，教導民眾養生及保健之道。\n\n \n\n\n	\n		\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			1\n			感冒的中醫治療與康復\n			討論感冒的中醫治療與如何預防？\n		\n		\n			2\n			感冒初期常用中藥介紹\n			介紹感冒初期常用中藥：生薑、紫蘇、薄荷..\n		\n		\n			3\n			我的火氣大嗎？\n			討論中醫火氣大的相關問題。\n		\n		\n			4\n			降火氣常用中藥介紹(1)\n			介紹降火氣常用中藥：石膏、竹葉、梔子..\n		\n		\n			5\n			降火氣常用中藥介紹(2)\n			黃連、金銀花、魚腥草、地骨皮...\n		\n		\n			6\n			為什麼會便秘？\n			討論便秘的原因與治療及如何保健。\n		\n		\n			7\n			便祕常用中藥介紹\n			介紹便祕常用中藥：大黃、蘆薈.....\n		\n		\n			8\n			風濕痛是類風溼性關節炎嗎\n			討論肌肉關節酸痛的中醫治療。\n		\n		\n			9\n			常用袪風除濕中藥介紹\n			介紹常用袪風除濕中藥：木瓜、桑枝、五加皮..\n		\n		\n			10\n			我的溼氣重嗎？\n			討論中醫濕氣的相關問題。\n		\n		\n			11\n			常用化濕利濕中藥介紹\n			介紹常用化濕利濕中藥：豆蔻、茯苓、車前子\n		\n		\n			12\n			中醫常講的寒症是甚麼？\n			討論中醫寒證的相關問題。\n		\n		\n			13\n			常用溫裡中藥介紹\n			介紹常用溫裡中藥：乾薑、肉桂、胡椒....\n		\n		\n			14\n			甚麼是食積症？\n			討論中醫食積的中醫治療與養生。                                                                                                    \n		\n		\n			15\n			常用中藥消食藥介紹\n			介紹常用中藥消食藥：山楂、麥芽、雞內金                                                                               \n		\n	\n\n\n \n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `location`='W311教室', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6716a22b26b32468988295a8', '無資料', '1/31、2/28、4/4停課\n\n\n	\n		\n			\n			 \n			\n			\n			次序\n			\n			\n			課程主題\n			\n			\n			教學內容\n			\n		\n		\n			\n			課\n\n			 \n\n			 \n\n			程\n\n			 \n\n			 \n\n			大\n\n			 \n\n			 \n\n			綱\n			\n			\n			1\n			\n			\n			身體覺知\n			\n			\n			喚醒身體的自癒能力，正確的使用核心肌群。\n			\n		\n		\n			\n			2\n			\n			\n			吸吐之間\n			\n			\n			吐盡餘氣要腹肌內收，吸氣盈胸強化肋間肌。\n			\n		\n		\n			\n			3\n			\n			\n			律動自覺\n			\n			\n			無意識妄動有礙訓練，傾聽身息能有助學習。\n			\n		\n		\n			\n			4\n			\n			\n			端正姿態\n			\n			\n			正確姿態能增益骨骼，合宜坐臥能影響健康。\n			\n		\n		\n			\n			5\n			\n			\n			核心如衛\n			\n			\n			強健核心如天然盔甲，鍛鍊肌群能捍衛脊椎。\n			\n		\n		\n			\n			6\n			\n			\n			脊柱間隙\n			\n			\n			脊椎扭轉增加靈活度，伸展體位能舒緩脊椎。\n			\n		\n		\n			\n			7\n			\n			\n			綿延肌群\n			\n			\n			肌群延展能舒緩緊張，並能增強抗壓的能力。\n			\n		\n		\n			\n			8\n			\n			\n			厚積耐力\n			\n			\n			適度的鍛鍊肌群耐力，有益身體基礎代謝率。\n			\n		\n		\n			\n			9\n			\n			\n			伸屈合度\n			\n			\n			強迫伸展關節易不適，體位合度能促進健康。\n			\n		\n		\n			\n			10\n			\n			\n			坐立體旋\n			\n			\n			扭轉體式能增強脊柱，坐姿扭轉能伸展臀肌。\n			\n		\n		\n			\n			11\n			\n			\n			靈巧關節\n			\n			\n			不當施力使關節退化，正確活動能靈活關節。\n			\n		\n		\n			\n			12\n			\n			\n			周身協調\n			\n			\n			超人體式能促進平衡，游泳體式能協調周身。\n			\n		\n		\n			\n			13\n			\n			\n			縱橫韌帶\n			\n			\n			深蹲體式需避免過度，股四頭肌能穩定膝蓋。\n			\n		\n		\n			\n			14\n			\n			\n			骨盆若磐\n			\n			\n			閉鎖鏈式能穩定骨盆，開放鏈式能舒緩腰背。\n			\n		\n		\n			\n			15\n			\n			\n			回歸初心\n			\n			\n			跪姿前彎能回歸初心，靜坐默觀能認識自己。\n			\n		\n	\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', 'E305教室', 25.0367564, 121.519047, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='1/31、2/28、4/4停課\n\n\n	\n		\n			\n			 \n			\n			\n			次序\n			\n			\n			課程主題\n			\n			\n			教學內容\n			\n		\n		\n			\n			課\n\n			 \n\n			 \n\n			程\n\n			 \n\n			 \n\n			大\n\n			 \n\n			 \n\n			綱\n			\n			\n			1\n			\n			\n			身體覺知\n			\n			\n			喚醒身體的自癒能力，正確的使用核心