INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6716a22b26b32468988295b5', '無資料', '1/28停課\n\n★本表所安排之課題及教學內容將依據學員程度及學習狀況斟酌調整。 \n\n\n	\n		\n			\n			課程名稱\n			\n			\n			國畫A2嶺南彩墨花鳥(初級)\n			\n			\n			授課老師\n			\n			\n			趙文雄\n			\n		\n		\n			\n			 \n\n			 \n\n			課\n\n			程\n\n			大\n\n			綱\n\n			 \n			\n			\n			週次\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			畫具材料介紹\n			\n			\n			筆墨畫法(竹)-講解畫具、筆墨線條、顏色之運用\n			\n		\n		\n			\n			2\n			\n			\n			彩墨花卉基本筆法\n			\n			\n			墨竹畫法-竹葉、竹枝、竹竿畫法與筆墨運用。\n			\n		\n		\n			\n			3\n			\n			\n			筆墨線條運用\n			\n			\n			學員現場習作，老師點評批改。\n			\n		\n		\n			\n			4\n			\n			\n			木本花卉畫法\n			\n			\n			木本花卉(梅、桃)-花朵、枝葉畫法及賦色\n			\n		\n		\n			\n			5\n			\n			\n			木本花形\n			\n			\n			學員現場習作，老師點評批改。\n			\n		\n		\n			\n			6\n			\n			\n			勾勒填彩點葉法\n			\n			\n			舌狀花(菊花類)- 花朵、莖葉畫法及賦色。(草蟲)\n			\n		\n		\n			\n			7\n			\n			\n			舌狀花形\n			\n			\n			學員現場習作，老師點評批改。\n			\n		\n		\n			\n			8\n			\n			\n			草本花卉帶狀葉畫法\n			\n			\n			草本帶狀葉花卉(蘭、金針)-花朵、莖葉彩墨畫法及賦色。(蝴蝶)\n			\n		\n		\n			\n			9\n			\n			\n			帶狀葉花形\n			\n			\n			學員現場習作，老師點評批改。\n			\n		\n		\n			\n			10\n			\n			\n			單瓣長蒂花頭畫法\n			\n			\n			單瓣長蒂花(木棉)花朵、莖葉彩墨畫法及賦色。(麻雀)\n			\n		\n		\n			\n			11\n			\n			\n			單瓣花形\n			\n			\n			學員現場習作，老師點評批改。\n			\n		\n		\n			\n			12\n			\n			\n			藤花的畫法\n			\n			\n			藤花(紫藤)-花串、葉藤畫法及賦色。(八哥鳥)\n			\n		\n		\n			\n			13\n			\n			\n			藤花形\n			\n			\n			學員現場習作，老師點評批改。\n			\n		\n		\n			\n			14\n			\n			\n			繁瓣大花頭畫法\n			\n			\n			繁瓣大花(荷、牡丹) -花朵、枝葉畫法及賦色。(白頭翁鳥)\n			\n		\n		\n			\n			15\n			\n			\n			繁瓣大花形\n			\n			\n			學員現場習作，老師點評批改。\n			\n		\n	\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', 'W315教室', 25.0367564, 121.519047, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='1/28停課\n\n★本表所安排之課題及教學內容將依據學員程度及學習狀況斟酌調整。 \n\n\n	\n		\n			\n			課程名稱\n			\n			\n			國畫A2嶺南彩墨花鳥(初級)\n			\n			\n			授課老師\n			\n			\n			趙文雄\n			\n		\