INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6716a22d26b32468988295c7', '無資料', '1/29停課\n\n★材料費：青草材料費 1000 元，班費約 1000 元由學員自行收付運用。\n\n★上課內容可依當令節氣青草做調整。\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			節氣青草 養生廚房\n			\n			\n			授課老師：李嘉梅\n			\n		\n		\n			\n			 \n\n			 \n\n			課\n\n			程\n\n			大\n\n			綱\n\n			 \n			\n			\n			次序\n			\n			\n			日期\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			1/8\n			\n			\n			暖身青草相見歡\n\n			冬季滋陰補氣養生青草\n			\n			\n			冬季小寒節氣，日漸寒冷，養生首重補益氣血，，介紹民間常見的滋陰補氣青草：白龍船花、白粗糠、白紫蘇，認識其經常使用的保健功效，現場燉煮天然養氣的青草料理，介紹適合小寒養生料理。\n			\n		\n		\n			\n			2\n			\n			\n			1/15\n			\n			\n			冬季強腎補氣虛保健青草\n			\n			\n			冬季小寒天，寒冷還沒到達頂點，為迎接大寒來臨，除了防寒防涼外，養生注重補氣、補血、補陽、補陰，飲食養生注意滋養腎臟，介紹養腎利水青草及製作生津祛燥養生料理。\n			\n		\n		\n			\n			3\n			\n			\n			1/22\n			\n			\n			冬季大寒養生保健青草\n			\n			\n			冬日主收藏，養生首重精氣內聚以潤五臟天氣寒冷的大寒天，順應節氣調理身體，已抵禦外邪之氣入侵，介紹民間常使用溫中散寒、補虛養血保健青草，現場燉煮可補充熱量、抵禦寒燥之氣的青草料理。\n			\n		\n		\n			\n			4\n			\n			\n			2/5\n			\n			\n			立春五行五色花草世界\n\n			春天養生青草總篇\n			\n			\n			介紹花草世界中的五行(金木水火土)五色(白綠黑紅黃)與身體(肺肝腎心脾)的對話‧\n\n			一年之計在於春，春天陽氣正盛，吃什麼顏色、味道的食物可以有益五臟，開春介紹五行養生篇\n			\n		\n		\n			\n			5\n			\n			\n			2/12\n			\n			\n			迎春˙戶外課（一）\n			\n			\n			走進外雙溪原生植物園區找尋大樹下、步道旁的保健青草，親身認識身邊熟悉卻不知道其名稱的常見本土保健青草，了解其民間常使用的保健功效，讓學員體驗春季植物的在地性及多樣性。\n			\n		\n		\n			\n			6\n			\n			\n			2/19\n			\n			\n			春天的地被青草\n			\n			\n			雨水時節是青草生長的旺季，許多小型的地被植物更在此時茂生，唇形科的金錢薄荷是民間最常使用\n\n			在活血化瘀的鮮榨青草，薔薇科蛇莓是健胃整腸的保健青草，本週將介紹金錢薄荷、蛇莓的葉形特徵，保健功效，並現場榨杯健胃、活血的新鮮青草汁\n			\n		\n		\n			\n			7\n			\n			\n			2/26\n			\n			\n			春天的養肝青草\n			\n			\n			介紹養肝青草小金英又名兔兒草、鵝仔菜及五爪金英，民間最常使用清涼排毒的青草，每年生長時間為農曆年後清明節之間，所以跟著節氣介紹新鮮的小金英之保健功效與煎煮或榨汁的方法，另外認識苦茶草青草足跡。\n			\n		\n		\n			\n			8\n			\n			\n			3/5\n			\n			\n			驚蟄的野草及野菜\n			\n			\n			雨水豐沛的季節，戶外野草青綠，認識青草就是絕佳的野菜，應時養生必採摘的空心蓮子草、山芹菜、山茼蒿，搭配簡單自然的料理方式，成為餐桌上的佳餚及保健青草。\n			\n		\n		\n			\n			9\n			\n			\n			3/12\n			\n			\n			春天的新綠青草\n			\n			\n			春天是青草抽新芽的時節，此時青草新芽的味道芳香濃郁，芽葉又脆又嫩，香椿、刺蔥、是製作沾醬、沙拉的好時節，香椿、刺蔥不但嫩葉可做青草料理，民間也將其視為降低血糖、穩定血糖的保健青草，本週將現場煎煮香椿茶及製作香椿、刺蔥茶包。\n			\n		\n		\n			\n			10\n			\n			\n			3/19\n			\n			\n			春天的鄉野青草\n			\n			\n			春天的野地裡茂盛的生長著各式各樣野草，茄科的龍葵是民間最受歡迎的食用野草之一，食用其鮮嫩的莖葉，無論是川燙、煮粥、清炒都非常可口，而且龍葵全草可入藥，具有解熱、利尿、消炎的保健功效，現場將製作鮮嫩美味的龍葵粥及龍葵沙拉。\n			\n		\n		\n			\n			11\n			\n			\n			3/26\n			\n			\n			春天的戶外課（二）\n			\n			\n			走進新北市烏來綠色步道間的保健青草，親身認識藥草園及四季青草園、可愛動物區青草，並且了解其民間常使用的保健功效，讓學員體驗植物園植物的在地性及多樣性。\n			\n		\n		\n			\n			12\n			\n			\n			4/2\n			\n			\n			春分的保健青草\n			\n			\n			春分時節萬物正在恢復生機，人體的新陳代謝速度加快，調理注重陰陽平衡，順應氣候變化，介紹當令青草及現場製作有助陽氣提升的養生食物及料理。\n			\n		\n		\n			\n			13\n			\n			\n			4/9\n			\n			\n			清明時節清明草\n			\n			\n			在青草中被稱為清明草的有菊科的鼠麴草和蘭科的盤龍蔘，本週將介紹民間經常使用在鎮咳、袪痰、利尿、降壓的鼠麴草，生長期為每年冬至到隔年清明時節的鼠麴草，更是大家熟悉的草仔粿的基本材料，現場將親自製作好吃美味養生的草仔粿。\n			\n		\n		\n			\n			14\n			\n			\n			4/16\n			\n			\n			清明的保健青草\n			\n			\n			清明時節雨紛紛，天氣變化無常，忽冷忽熱，很容易感冒、咳嗽，介紹祛風散寒、增強抵抗力的溫性青草，現場煎煮桑葉、蜈蚣草、雞屎藤、等民間常使用的止咳化痰青草茶及平補養氣的青草料理。\n			\n		\n		\n			\n			15\n			\n			\n			4/23\n			\n			\n			穀雨的黃花青草\n			\n			\n			穀雨顧名思義：雨生百穀、春雨可貴，節氣到此萬物等待春雨降臨，而青草中菊科的黃花蜜菜及黃鵪菜正是繁華盛開，民間經常使用在解熱、降肝火、保肝、袪傷，是青草茶的基本材料，現場將煎煮或榨汁食用的方法。\n			\n		\n	\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '園區教室(二)', 25.0367564, 121.519047, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='1/29停課\n\n★材料費：青草材料費 1000 元，班費約 1000 元由學員自行收付運用。\n\n★上課內容可依當令節氣青草做調整。\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			節氣青草 養生廚房\n			\n			\n			授課老師：李嘉梅\n			\n		\n		\n			\n			 \n\n			 \n\n			課\n\n			程\n\n			大\n\n			綱\n\n			 \n			\n			\n			次序\n			\n			\n			日期\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			1/8\n			\n			\n			暖身青草相見歡\n\n			冬季滋陰補氣養生青草\n			\n			\n			冬季小寒節氣，日漸寒冷，養生首重補益氣血，，介紹民間常見的滋陰補氣青草：白龍船花、白粗糠、白紫蘇，認識其經常使用的保健功效，現場燉煮天然養氣的青草料理，介紹適合小寒養生料理。\n			\n		\n		\n			\n			2\n			\n			\n			1/15\n			\n			\n			冬季強腎補氣虛保健青草\n			\n			\n			冬季小寒天，寒冷還沒到達頂點，為迎接大寒來臨，除了防寒防涼外，養生注重補氣、補血、補陽、補陰，飲食養生注意滋養腎臟，介紹養腎利水青草及製作生津祛燥養生料理。\n			\n		\n		\n			\n			3\n			\n			\n			1/22\n			\n			\n			冬季大寒養生保健青草\n			\n			\n			冬日主收藏，養生首重精氣內聚以潤五臟天氣寒冷的大寒天，順應節氣調理身體，已抵禦外邪之氣入侵，介紹民間常使用溫中散寒、補虛養血保健青草，現場燉煮可補充熱量、抵禦寒燥之氣的青草料理。\n			\n		\n		\n			\n			4\n			\n			\n			2/5\n			\n			\n			立春五行五色花草世界\n\n			春天養生青草總篇\n			\n			\n			介紹花草世界中的五行(金木水火土)五色(白綠黑紅黃)與身體(肺肝腎心脾)的對話‧\n\n			一年之計在於春，春天陽氣正盛，吃什麼顏色、味道的食物可以有益五臟，開春介紹五行養生篇\n			\n		\n		\n			\n			5\n			\n			\n			2/12\n			\n			\n			迎春˙戶外課（一）\n			\n			\n			走進外雙溪原生植物園區找尋大樹下、步道旁的保健青草，親身認識身邊熟悉卻不知道其名稱的常見本土保健青草，了解其民間常使用的保健功效，讓學員體驗春季植物的在地性及多樣性。\n			\n		\n		\n			\n			6\n			\n			\n			2/19\n			\n			\n			春天的地被青草\n			\n			\n			雨水時節是青草生長的旺季，許多小型的地被植物更在此時茂生，唇形科的金錢薄荷是民間最常使用\n\n			在活血化瘀的鮮榨青草，薔薇科蛇莓是健胃整腸的保健青草，本週將介紹金錢薄荷、蛇莓的葉形特徵，保健功效，並現場榨杯健胃、活血的新鮮青草汁\n			\n		\n		\n			\n			7\n			\n			\n			2/26\n			\n			\n			春天的養肝青草\n			\n			\n			介紹養肝青草小金英又名兔兒草、鵝仔菜及五爪金英，民間最常使用清涼排毒的青草，每年生長時間為農曆年後清明節之間，所以跟著節氣介紹新鮮的小金英之保健功效與煎煮或榨汁的方法，另外認識苦茶草青草足跡。\n			\n		\n		\n			\n			8\n			\n			\n			3/5\n			\n			\n			驚蟄的野草及野菜\n			\n			\n			雨水豐沛的季節，戶外野草青綠，認識青草就是絕佳的野菜，應時養生必採摘的空心蓮子草、山芹菜、山茼蒿，搭配簡單自然的料理方式，成為餐桌上的佳餚及保健青草。\n			\n		\n		\n			\n			9\n			\n			\n			3/12\n			\n			\n			春天的新綠青草\n			\n			\n			春天是青草抽新芽的時節，此時青草新芽的味道芳香濃郁，芽葉又脆又嫩，香椿、刺蔥、是製作沾醬、沙拉的好時節，香椿、刺蔥不但嫩葉可做青草料理，民間也將其視為降低血糖、穩定血糖的保健青草，本週將現場煎煮香椿茶及製作香椿、刺蔥茶包。\n			\n		\n		\n			\n			10\n			\n			\n			3/19\n			\n			\n			春天的鄉野青草\n			\n			\n			春天的野地裡茂盛的生長著各式各樣野草，茄科的龍葵是民間最受歡迎的食用野草之一，食用其鮮嫩的莖葉，無論是川燙、煮粥、清炒都非常可口，而且龍葵全草可入藥，具有解熱、利尿、消炎的保健功效，現場將製作鮮嫩美味的龍葵粥及龍葵沙拉。\n			\n		\n		\n			\n			11\n			\n			\n			3/26\n			\n			\n			春天的戶外課（二）\n			\n			\n			走進新北市烏來綠色步道間的保健青草，親身認識藥草園及四季青草園、可愛動物區青草，並且了解其民間常使用的保健功效，讓學員體驗植物園植物的在地性及多樣性。\n			\n		\n		\n			\n			12\n			\n			\n			4/2\n			\n			\n			春分的保健青草\n			\n			\n			春分時節萬物正在恢復生機，人體的新陳代謝速度加快，調理注重陰陽平衡，順應氣候變化，介紹當令青草及現場製作有助陽氣提升的養生食物及料理。\n			\n		\n		\n			\n			13\n			\n			\n			4/9\n			\n			\n			清明時節清明草\n			\n			\n			在青草中被稱為清明草的有菊科的鼠麴草和蘭科的盤龍蔘，本週將介紹民間經常使用在鎮咳、袪痰、利尿、降壓的鼠麴草，生長期為每年冬至到隔年清明時節的鼠麴草，更是大家熟悉的草仔粿的基本材料，現場將親自製作好吃美味養生的草仔粿。\n			\n		\n		\n			\n			14\n			\n			\n			4/16\n			\n			\n			清明的保健青草\n			\n			\n			清明時節雨紛紛，天氣變化無常，忽冷忽熱，很容易感冒、咳嗽，介紹祛風散寒、增強抵抗力的溫性青草，現場煎煮桑葉、蜈蚣草、雞屎藤、等民間常使用的止咳化痰青草茶及平補養氣的青草料理。\n			\n		\n		\n			\n			15\n			\n			\n			4/23\n			\n			\n			穀雨的黃花青草\n			\n			\n			穀雨顧名思義：雨生百穀、春雨可貴，節氣到此萬物等待春雨降臨，而青草中菊科的黃花蜜菜及黃鵪菜正是繁華盛開，民間經常使用在解熱、降肝火、保肝、袪傷，是青草茶的基本材料，現場將煎煮或榨汁食用的方法。\n			\n		\n	\n\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `location`='園區教室(二)', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
