INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67229a2126b32468988298b5', '微塵競色≋科學攝影特展', '暑假前夕，國立自然科學博物館推出全新《微塵競色≋第8屆科學攝影特展》，展出66組全球華人投稿的科學攝影脫穎而出的得獎作品，涵蓋陸地、海洋、天文等10餘種主題。鏡頭下有以微距攝影呈現微生物培養基裡的結晶、遙遠天邊的美麗星團與銀河，歡迎科學迷、攝影愛好者、社會大眾一覽鏡頭下的生態奇觀和自然美景！\r\n\r\n國立自然科學博物館館長焦傳金表示，科學攝影橫跨科學、藝術，不論是社會大眾、青少年、國中小學生都能成為公民科學家，透過不同視角呈現自然界中令人驚嘆的瞬間；每一個快門的按下，都是一次對自然世界的探索，現在人人都有手機，可以隨時掌握生活中的科學之美。\r\n\r\n《微塵競色》策展人、科博館人類學組主任楊翎指出，科博館從2013年開始舉辦「驚豔‧新視野：科學攝影」徵件，廣邀全球華人共襄盛舉，迄今參與人數超過135萬人次、累積參賽作品4686組，共推出5次科學攝影特展，科學攝影是一種觀察世界的態度和角度，紀錄科學的美感與奧妙，也捕捉到了環境悄然變化的軌跡。', '國立自然科學博物館', '臺中市北區館前路1號', '2025-01-01 00:00:00', '2025-04-20 00:00:00', '國立自然科學博物館', 24.15863985, 120.6809521, '植物園溫室學生團體+10;植物園溫室全票+20;科學中心全票+20;921地震園區團體優+30;921地震園區全票+50;立體劇場學生團體+30;立體劇場一般團體+50;太空劇場學生團體+50;展示場學生團體+50;展示場一般團體+70;太空劇場一般團體+70;立體劇場全票+70;太空劇場全票+100;展示場全票+100', 'https://www.nmns.edu.tw/ch/information/news/News-001611/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='微塵競色≋科學攝影特展', `description`='暑假前夕，國立自然科學博物館推出全新《微塵競色≋第8屆科學攝影特展》，展出66組全球華人投稿的科學攝影脫穎而出的得獎作品，涵蓋陸地、海洋、天文等10餘種主題。鏡頭下有以微距攝影呈現微生物培養基裡的結晶、遙遠天邊的美麗星團與銀河，歡迎科學迷、攝影愛好者、社會大眾一覽鏡頭下的生態奇觀和自然美景！\r\n\r\n國立自然科學博物館館長焦傳金表示，科學攝影橫跨科學、藝術，不論是社會大眾、青少年、國中小學生都能成為公民科學家，透過不同視角呈現自然界中令人驚嘆的瞬間；每一個快門的按下，都是一次對自然世界的探索，現在人人都有手機，可以隨時掌握生活中的科學之美。\r\n\r\n《微塵競色》策展人、科博館人類學組主任楊翎指出，科博館從2013年開始舉辦「驚豔‧新視野：科學攝影」徵件，廣邀全球華人共襄盛舉，迄今參與人數超過135萬人次、累積參賽作品4686組，共推出5次科學攝影特展，科學攝影是一種觀察世界的態度和角度，紀錄科學的美感與奧妙，也捕捉到了環境悄然變化的軌跡。', `organizer`='國立自然科學博物館', `address`='臺中市北區館前路1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='國立自然科學博物館', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='植物園溫室學生團體+10;植物園溫室全票+20;科學中心全票+20;921地震園區團體優+30;921地震園區全票+50;立體劇場學生團體+30;立體劇場一般團體+50;太空劇場學生團體+50;展示場學生團體+50;展示場一般團體+70;太空劇場一般團體+70;立體劇場全票+70;太空劇場全票+100;展示場全票+100', `source_url`='https://www.nmns.edu.tw/ch/information/news/News-001611/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67254aba26b32468988299cb', '第一特展室：淺山樟力 ─ 臺三線上原客焗腦展', '昔日臺三線西北部的淺山地帶是擁有豐富樟樹資源的地區。這些資源帶來了巨大的經濟利益，吸引了國際列強、政府、地方資本家和漢人移民進行山地開墾，使得當時的臺灣成為全球最大的樟腦生產地。\r\n隨著19世紀樟腦產業的蓬勃發展，牽動著原住民族、閩南、客家在淺山地帶交會與競合。因此，本展覽將以中北部地區的樟腦產業作為起點，探討世界經貿和族群間焗腦的互動關係。期冀重現這段歷史的文化記憶，並傳達對不同族群的尊重和土地關懷，體現多元族群互為主體的史觀敘事。', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-01-01 00:00:00', '2025-05-19 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '無資料', 'https://thcdc.hakka.gov.tw/1241/1258/7372/lpsimplelist', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第一特展室：淺山樟力 ─ 臺三線上原客焗腦展', `description`='昔日臺三線西北部的淺山地帶是擁有豐富樟樹資源的地區。這些資源帶來了巨大的經濟利益，吸引了國際列強、政府、地方資本家和漢人移民進行山地開墾，使得當時的臺灣成為全球最大的樟腦生產地。\r\n隨著19世紀樟腦產業的蓬勃發展，牽動著原住民族、閩南、客家在淺山地帶交會與競合。因此，本展覽將以中北部地區的樟腦產業作為起點，探討世界經貿和族群間焗腦的互動關係。期冀重現這段歷史的文化記憶，並傳達對不同族群的尊重和土地關懷，體現多元族群互為主體的史觀敘事。', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-05-19 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='無資料', `source_url`='https://thcdc.hakka.gov.tw/1241/1258/7372/lpsimplelist', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67254aba26b32468988299cd', '第四特展室：拼．靚--臺灣客家多重面貌特展', '小氣、小炒、花布、桐花編織成當代臺灣客家刻板印象，然而真相就只有這樣嗎？臺灣客家在這片土地上持續地和各族群互動，為了追尋更好的生活，不斷調適與改變。因此，本展以「拼．靚」為主題，兼具雙重意義。其一表達客家人堅韌刻苦的精神與生活美學，展現客家文化傳統與創新的力與美；其二本展覽匯聚了重要的公私館藏，從歷史、生活、信仰、守護、創新、藝術等六個角度，分別以客語命名為「徙saiˋ、靚jiangˊ、敬gin、拚biang、變bien、尋qimˇ」，共筆勾勒出臺灣客家的多重面貌。\r\n\r\n一、徙：族群流動從未停歇\r\n  客家族群移民到臺灣後，歷經波折，或者定居，或者再移民。我們以客家遷徙至這片新土地後，與多元族群合作開墾的故事為起點，敘述客家墾拓與定居，同時又再流動至臺灣各地的過程。\r\n\r\n二、靚：花布以外的美麗安居\r\n  花布或桐花之外，客家美學其實十分豐富。我們以南臺灣佳冬蕭家的華麗嫁衣為起點，展現客家開枝散葉時，美麗的工藝以及精湛的文風與武藝。在這些精緻的文物中，看到了人們對美滿姻緣的期盼、對子孫的疼愛以及自我實現的努力。\r\n\r\n三、敬：虔誠帶來團結與安心\r\n  在變動不安的生活裡，人們虔誠敬獻祖先與神明，求得安心；也因為這些儀式，團結在一起。我們從解讀一張北臺灣20世紀初的「調單」為起點，觀察客庄敬天、祭神與崇祖的習俗；我們在這些習俗中意外地發現，原來搞樂團與群眾募資早已不是新鮮事了！\r\n\r\n四、拚：自我守護的力量\r\n  儘管臺灣政治與社會環境不斷變動，客家族群始終擁有一種凝聚族群意識以自我守護的力量。我們以據傳清嘉慶年間六堆大總理賴熊飛用長刃大刀為起點，從自衛組織、民變、戰爭與專制統治等主題，呈現不同世代的客家人保鄉衛土的精神。\r\n\r\n五、變：不斷調適的創造力\r\n  世界不是一成不變的，文化總是不斷地創新。我們以20世紀中葉非客籍的福州人林榮飛，從中臺灣到苗栗客庄的陶藝生涯之旅為起點，從工藝、產業與娛樂事業等主題，說明客家人持續因應外在時事挑戰與環境之變化，創造一波波的精彩。\r\n\r\n六、尋：誰是客家？\r\n  這是一頁從遷徙到定居、維護傳統與創新求變的族群史，我們以文學家林海音穿梭於多元族群的經驗為起點，藉由文學、藝術、攝影與傳播等作品，看看人們如何探尋與凝視自己的身份與土地。', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '無資料', 'https://thcdc.hakka.gov.tw/1241/1258/7372/108081/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第四特展室：拼．靚--臺灣客家多重面貌特展', `description`='小氣、小炒、花布、桐花編織成當代臺灣客家刻板印象，然而真相就只有這樣嗎？臺灣客家在這片土地上持續地和各族群互動，為了追尋更好的生活，不斷調適與改變。因此，本展以「拼．靚」為主題，兼具雙重意義。其一表達客家人堅韌刻苦的精神與生活美學，展現客家文化傳統與創新的力與美；其二本展覽匯聚了重要的公私館藏，從歷史、生活、信仰、守護、創新、藝術等六個角度，分別以客語命名為「徙saiˋ、靚jiangˊ、敬gin、拚biang、變bien、尋qimˇ」，共筆勾勒出臺灣客家的多重面貌。\r\n\r\n一、徙：族群流動從未停歇\r\n  客家族群移民到臺灣後，歷經波折，或者定居，或者再移民。我們以客家遷徙至這片新土地後，與多元族群合作開墾的故事為起點，敘述客家墾拓與定居，同時又再流動至臺灣各地的過程。\r\n\r\n二、靚：花布以外的美麗安居\r\n  花布或桐花之外，客家美學其實十分豐富。我們以南臺灣佳冬蕭家的華麗嫁衣為起點，展現客家開枝散葉時，美麗的工藝以及精湛的文風與武藝。在這些精緻的文物中，看到了人們對美滿姻緣的期盼、對子孫的疼愛以及自我實現的努力。\r\n\r\n三、敬：虔誠帶來團結與安心\r\n  在變動不安的生活裡，人們虔誠敬獻祖先與神明，求得安心；也因為這些儀式，團結在一起。我們從解讀一張北臺灣20世紀初的「調單」為起點，觀察客庄敬天、祭神與崇祖的習俗；我們在這些習俗中意外地發現，原來搞樂團與群眾募資早已不是新鮮事了！\r\n\r\n四、拚：自我守護的力量\r\n  儘管臺灣政治與社會環境不斷變動，客家族群始終擁有一種凝聚族群意識以自我守護的力量。我們以據傳清嘉慶年間六堆大總理賴熊飛用長刃大刀為起點，從自衛組織、民變、戰爭與專制統治等主題，呈現不同世代的客家人保鄉衛土的精神。\r\n\r\n五、變：不斷調適的創造力\r\n  世界不是一成不變的，文化總是不斷地創新。我們以20世紀中葉非客籍的福州人林榮飛，從中臺灣到苗栗客庄的陶藝生涯之旅為起點，從工藝、產業與娛樂事業等主題，說明客家人持續因應外在時事挑戰與環境之變化，創造一波波的精彩。\r\n\r\n六、尋：誰是客家？\r\n  這是一頁從遷徙到定居、維護傳統與創新求變的族群史，我們以文學家林海音穿梭於多元族群的經驗為起點，藉由文學、藝術、攝影與傳播等作品，看看人們如何探尋與凝視自己的身份與土地。', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='無資料', `source_url`='https://thcdc.hakka.gov.tw/1241/1258/7372/108081/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67254aba26b32468988299ce', '第三特展室（兒童館）：客庄遊樂去－探索客庄生活智慧及節慶生活', '臺灣客家文化館兒童館以「客庄遊樂去」為主軸，探索客庄生活智慧及節慶文化，將展區規劃分為「客家美食擂台」、「擂茶DIY」、「好客龍VR體驗館」、「土地生活區」、「晴耕雨讀區」及「童話秘密基地」六個分區。\r\n其中「客家美食擂台」與「擂茶DIY」開放體驗，歡迎大小朋友共下來挑戰。\r\n「客家美食擂台」，以觸控平板及互動牆面投影連動技術呈現，藉由遊戲中的25道客家名菜，包含四炆四炒、粄食、醃製食物等等經典菜餚，了解客家人克勤克儉、敬天惜物與熱情好客的精神及客家菜特有的風味。\r\n「擂茶DIY」，以虛擬觸控桌DIY的操作模式，藉由簡易趣味的研磨遊戲過程，可了解擂茶從原料到成品的製程，認識這道獨特的客家茶飲文化。\r\n\r\n凡持好客劇場入場券，即可至第三特展室（兒童館）免費體驗VR遊戲。兒童館活動時程：\r\n09:30-10:30 好客龍VR體驗館\r\n10:30-11:00 兒童說故事劇場\r\n11:00-12:00 好客龍VR體驗館\r\n12:00-13:30 清潔維護時間\r\n13:30-15:30 好客龍VR體驗館\r\n15:30-16:00 兒童說故事劇場\r\n\r\n【開放預約參觀囉】\r\n依據中央流行疫情指揮中心7月8日指示，防疫措施鬆綁逐步執行，並延長全國疫情警戒第三級至7月26日止，本館自7月14日起微解封開館：\r\n請於7月12日始於9：00-17：00來電037-985558分機732預約參觀，參觀時段為每天上午(9:00 & 11:00)下午(13:30 & 15:30)各2場次2小時為原則(最後一場至17：00)，完成預約之個人或團體再依預約時間準時到館參觀。\r\n入園/館前仍需進行人流分流管制：\r\n館內總人數限縮100人/單一特展室（或商場）限縮40人。', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '無資料', 'https://thcdc.hakka.gov.tw/1241/1258/7372/8011/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第三特展室（兒童館）：客庄遊樂去－探索客庄生活智慧及節慶生活', `description`='臺灣客家文化館兒童館以「客庄遊樂去」為主軸，探索客庄生活智慧及節慶文化，將展區規劃分為「客家美食擂台」、「擂茶DIY」、「好客龍VR體驗館」、「土地生活區」、「晴耕雨讀區」及「童話秘密基地」六個分區。\r\n其中「客家美食擂台」與「擂茶DIY」開放體驗，歡迎大小朋友共下來挑戰。\r\n「客家美食擂台」，以觸控平板及互動牆面投影連動技術呈現，藉由遊戲中的25道客家名菜，包含四炆四炒、粄食、醃製食物等等經典菜餚，了解客家人克勤克儉、敬天惜物與熱情好客的精神及客家菜特有的風味。\r\n「擂茶DIY」，以虛擬觸控桌DIY的操作模式，藉由簡易趣味的研磨遊戲過程，可了解擂茶從原料到成品的製程，認識這道獨特的客家茶飲文化。\r\n\r\n凡持好客劇場入場券，即可至第三特展室（兒童館）免費體驗VR遊戲。兒童館活動時程：\r\n09:30-10:30 好客龍VR體驗館\r\n10:30-11:00 兒童說故事劇場\r\n11:00-12:00 好客龍VR體驗館\r\n12:00-13:30 清潔維護時間\r\n13:30-15:30 好客龍VR體驗館\r\n15:30-16:00 兒童說故事劇場\r\n\r\n【開放預約參觀囉】\r\n依據中央流行疫情指揮中心7月8日指示，防疫措施鬆綁逐步執行，並延長全國疫情警戒第三級至7月26日止，本館自7月14日起微解封開館：\r\n請於7月12日始於9：00-17：00來電037-985558分機732預約參觀，參觀時段為每天上午(9:00 & 11:00)下午(13:30 & 15:30)各2場次2小時為原則(最後一場至17：00)，完成預約之個人或團體再依預約時間準時到館參觀。\r\n入園/館前仍需進行人流分流管制：\r\n館內總人數限縮100人/單一特展室（或商場）限縮40人。', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='無資料', `source_url`='https://thcdc.hakka.gov.tw/1241/1258/7372/8011/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67254aba26b32468988299cf', '「承蒙客家」臺灣客家文化館常設展', '本展係依據展前研究「承蒙」一書作為策展主軸，「承蒙」意指客家族群與臺灣社會之間相互致敬、感謝之意。主視覺以Hakka之H為意象，摹寫兩人「攜手」協力之體態，用以表達相互包容、共創精采的寶島特色文化精神；同時也有「拱手」致謝的意涵，由此彰顯展示主題「承蒙客家」之意。展覽內容從「歷史客家」、「全球客家」、「常民客家」、「文化客家」及「公民客家」等五個面向來重新詮釋客家文化；期透過本展印證客家是臺灣多元文化中不可或缺的一環，並表達臺灣滋養了客家文化，客家豐富了臺灣文化之普世價值。\r\n\r\n【開放預約參觀囉】\r\n依據中央流行疫情指揮中心7月8日指示，防疫措施鬆綁逐步執行，並延長全國疫情警戒第三級至7月26日止，本館自7月14日起微解封開館：\r\n請於7月12日始於9：00-17：00來電037-985558分機732預約參觀，參觀時段為每天上午(9:00 & 11:00)下午(13:30 & 15:30)各2場次2小時為原則(最後一場至17：00)，完成預約之個人或團體再依預約時間準時到館參觀。\r\n入園/館前仍需進行人流分流管制：\r\n館內總人數限縮100人/單一特展室（或商場）限縮40人。', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '無資料', 'https://thcdc.hakka.gov.tw/1241/1258/1259/1811/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「承蒙客家」臺灣客家文化館常設展', `description`='本展係依據展前研究「承蒙」一書作為策展主軸，「承蒙」意指客家族群與臺灣社會之間相互致敬、感謝之意。主視覺以Hakka之H為意象，摹寫兩人「攜手」協力之體態，用以表達相互包容、共創精采的寶島特色文化精神；同時也有「拱手」致謝的意涵，由此彰顯展示主題「承蒙客家」之意。展覽內容從「歷史客家」、「全球客家」、「常民客家」、「文化客家」及「公民客家」等五個面向來重新詮釋客家文化；期透過本展印證客家是臺灣多元文化中不可或缺的一環，並表達臺灣滋養了客家文化，客家豐富了臺灣文化之普世價值。\r\n\r\n【開放預約參觀囉】\r\n依據中央流行疫情指揮中心7月8日指示，防疫措施鬆綁逐步執行，並延長全國疫情警戒第三級至7月26日止，本館自7月14日起微解封開館：\r\n請於7月12日始於9：00-17：00來電037-985558分機732預約參觀，參觀時段為每天上午(9:00 & 11:00)下午(13:30 & 15:30)各2場次2小時為原則(最後一場至17：00)，完成預約之個人或團體再依預約時間準時到館參觀。\r\n入園/館前仍需進行人流分流管制：\r\n館內總人數限縮100人/單一特展室（或商場）限縮40人。', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='無資料', `source_url`='https://thcdc.hakka.gov.tw/1241/1258/1259/1811/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67293cc226b3246898829a2c', '美術館的一百種想像', '本展源自內惟二期計畫，意在激發思考美術館的建築種種。建築體驗是多感官的，形式、空間、光影、材質和色彩等相互作用。建築因而不只是看的藝術，更需全身心的投入感受。本展從建築的基本元素：造型、色彩、皮層和光線，以及建築師、插畫家的作品中，循序引導進入建築的內外之間。\r\n展演者︰參展建築師 侯林建築師事務所˙草原市務所+中村至男˙蕭有志 參展藝術家 平安˙吳修銘˙吳秋敏˙林芸巧˙草棉谷˙林家棟˙洪添賢˙黃馨瑩˙鄭宜芳˙鄭元欽˙蘇子涵˙黑碼藝識 參展學校 正修科技大學建築與室內設計系黃韻珊+邱信邦˙郭慧晶˙張成毅˙劉鑫煒 中山國小四年四班全體同學 作品指導洪添賢 學校老師王錦娥+劉芳婷', '高雄市立美術館', '高雄市鼓山區馬卡道路330號', '2025-01-01 00:00:00', '2025-03-01 00:00:00', '高雄兒童美術館', 22.6578576, 120.2828147, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='美術館的一百種想像', `description`='本展源自內惟二期計畫，意在激發思考美術館的建築種種。建築體驗是多感官的，形式、空間、光影、材質和色彩等相互作用。建築因而不只是看的藝術，更需全身心的投入感受。本展從建築的基本元素：造型、色彩、皮層和光線，以及建築師、插畫家的作品中，循序引導進入建築的內外之間。\r\n展演者︰參展建築師 侯林建築師事務所˙草原市務所+中村至男˙蕭有志 參展藝術家 平安˙吳修銘˙吳秋敏˙林芸巧˙草棉谷˙林家棟˙洪添賢˙黃馨瑩˙鄭宜芳˙鄭元欽˙蘇子涵˙黑碼藝識 參展學校 正修科技大學建築與室內設計系黃韻珊+邱信邦˙郭慧晶˙張成毅˙劉鑫煒 中山國小四年四班全體同學 作品指導洪添賢 學校老師王錦娥+劉芳婷', `organizer`='高雄市立美術館', `address`='高雄市鼓山區馬卡道路330號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='高雄兒童美術館', `latitude`=22.6578576, `longitude`=120.2828147, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67293cc626b3246898829a44', '「On Board 從基隆出發航向世界」常設展', '跟著陽明出發，像一座座漂浮的島嶼，閃閃發光。風吹浪打，船渡搖擺，每一艘貨櫃船都有其任務與目的地。\r\n在運與輸的海路上，有這麼一群離家背井的海運工作者在崗位堅守著，選擇離開熟悉的陸路生活，航向無際大海。本展跟著這群海運人，從他們的視角與動線，認識陽光折射浪花，閃閃發亮的海上時光。', '陽明海洋文化藝術館', '基隆市仁愛區港西街四號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '陽明海洋文化藝術館', 25.11945421, 121.7434205, '全票+150;優待票+100', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「On Board 從基隆出發航向世界」常設展', `description`='跟著陽明出發，像一座座漂浮的島嶼，閃閃發光。風吹浪打，船渡搖擺，每一艘貨櫃船都有其任務與目的地。\r\n在運與輸的海路上，有這麼一群離家背井的海運工作者在崗位堅守著，選擇離開熟悉的陸路生活，航向無際大海。本展跟著這群海運人，從他們的視角與動線，認識陽光折射浪花，閃閃發亮的海上時光。', `organizer`='陽明海洋文化藝術館', `address`='基隆市仁愛區港西街四號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='陽明海洋文化藝術館', `latitude`=25.11945421, `longitude`=121.7434205, `ticket_price`='全票+150;優待票+100', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('672a8af226b3246898829a4c', '「當代轉‧動—北區原文館聯合策展行動2.0」聯展', '本展由北區6間原文館新生代的族群文化專員及策展員全程主導，在臺博館與專業師資團隊長期密集的工作坊訓練中，由各館互助合作，從主題概念發想、架構文案發展、空間表現、文物選件、互動開發、觀眾溝通、文宣設計等逐步完成策展。\n\n\n本次展出內容包括：基隆市原住民文化會館展出「八尺門的野菜人」八尺門社區真實生活中，野菜園裡種植的阿美族野菜物種與野菜食譜；臺北市凱達格蘭文化館展出「登陸･火山･撤離･遺留──凱達格蘭族歷史絮語」以在地原生族群凱達格蘭族的觀點，透過族群起源傳說的踏查走讀，重新演繹北投與大屯山之故事； 新北市烏來泰雅民族博物館展出「Ulay‧織男」以翻轉傳統「泰雅織女」的刻板印象，從一位非典型的在地「泰雅織男」身上出發，呈現出當代烏來（Ulay）泰雅織藝的另類風貌；桃園市原住民族文化會館以「Tuying．都市原住民的樣貌——撤離．凝聚．重生」展出一群不習慣城市高樓大廈的阿美族人，陸續遷居落腳於 Sa’owac（撒烏瓦知）部落的過程與轉變；宜蘭縣南澳鄉泰雅文化館的「獵人逐跡 rapan c''oli mluyak」勾勒出南澳泰雅族獵人文化的今昔，呈現坐落於山海間的泰雅族南澳群（Klesan）獵人如何藉由對獵物的追逐實踐與追隨祖（Gaga）；宜蘭縣大同鄉泰雅生活館展出「大同小米 Trakis Datong」以小米（trakis）是生活裡的主食、祭儀中的焦點，也是泰雅永續農業生態智慧的精隨所在，呈現大同泰雅人對（trakis）小米的禮讚。\n\n \n\n \n\n文化部、原住民族委員會\n主辦單位：國立臺灣博物館、原住民族委員會原住民族文化發展中心\n協辦單位：臺北市政府原住民族事務委員會\n \n\n ', '國立臺灣博物館', '112  臺北市北投區中山路3-1號', '2024-11-05 00:00:00', '2025-03-30 00:00:00', '凱達格蘭文化館B1特展區', 25.1480682, 121.5177992, '無資料', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40273', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「當代轉‧動—北區原文館聯合策展行動2.0」聯展', `description`='本展由北區6間原文館新生代的族群文化專員及策展員全程主導，在臺博館與專業師資團隊長期密集的工作坊訓練中，由各館互助合作，從主題概念發想、架構文案發展、空間表現、文物選件、互動開發、觀眾溝通、文宣設計等逐步完成策展。\n\n\n本次展出內容包括：基隆市原住民文化會館展出「八尺門的野菜人」八尺門社區真實生活中，野菜園裡種植的阿美族野菜物種與野菜食譜；臺北市凱達格蘭文化館展出「登陸･火山･撤離･遺留──凱達格蘭族歷史絮語」以在地原生族群凱達格蘭族的觀點，透過族群起源傳說的踏查走讀，重新演繹北投與大屯山之故事； 新北市烏來泰雅民族博物館展出「Ulay‧織男」以翻轉傳統「泰雅織女」的刻板印象，從一位非典型的在地「泰雅織男」身上出發，呈現出當代烏來（Ulay）泰雅織藝的另類風貌；桃園市原住民族文化會館以「Tuying．都市原住民的樣貌——撤離．凝聚．重生」展出一群不習慣城市高樓大廈的阿美族人，陸續遷居落腳於 Sa’owac（撒烏瓦知）部落的過程與轉變；宜蘭縣南澳鄉泰雅文化館的「獵人逐跡 rapan c''oli mluyak」勾勒出南澳泰雅族獵人文化的今昔，呈現坐落於山海間的泰雅族南澳群（Klesan）獵人如何藉由對獵物的追逐實踐與追隨祖（Gaga）；宜蘭縣大同鄉泰雅生活館展出「大同小米 Trakis Datong」以小米（trakis）是生活裡的主食、祭儀中的焦點，也是泰雅永續農業生態智慧的精隨所在，呈現大同泰雅人對（trakis）小米的禮讚。\n\n \n\n \n\n文化部、原住民族委員會\n主辦單位：國立臺灣博物館、原住民族委員會原住民族文化發展中心\n協辦單位：臺北市政府原住民族事務委員會\n \n\n ', `organizer`='國立臺灣博物館', `address`='112  臺北市北投區中山路3-1號', `start_date`='2024-11-05 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='凱達格蘭文化館B1特展區', `latitude`=25.1480682, `longitude`=121.5177992, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40273', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('672a8c3126b3246898829ac4', '河海行舟—清明上河圖數位特展', '本次數位特展結合故宮「古畫動漫—清院本清明上河圖」與海科館的研究典藏，走入人類自古與河共生共榮的歷史，看見古人智慧與工藝美學的同時，反省今日隨著舟船、漁法技術進步，人們對河海資源的掠奪。另外亦特別邀請財團法人陽明海運文化基金會贊助11件中式古船模型展示。透過基金會典藏基隆在地木船工藝達人曾樹銘老師經典作品，講述自古以來各式舟船運載著人們生活的甘苦回憶，流動著各行各業的繁榮盛況。也因百川匯集成河海大洋，人類不停追求自由夢想的海洋精神，得以無所畏懼地跨越艱鉅的波濤洶湧，抵達嚮往的大洋彼方。', '國立故宮博物院', '基隆市中正區北寧路367號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '國立海洋科技博物館', 25.14365754, 121.7783549, '含主題館及第二特展廳+300', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='河海行舟—清明上河圖數位特展', `description`='本次數位特展結合故宮「古畫動漫—清院本清明上河圖」與海科館的研究典藏，走入人類自古與河共生共榮的歷史，看見古人智慧與工藝美學的同時，反省今日隨著舟船、漁法技術進步，人們對河海資源的掠奪。另外亦特別邀請財團法人陽明海運文化基金會贊助11件中式古船模型展示。透過基金會典藏基隆在地木船工藝達人曾樹銘老師經典作品，講述自古以來各式舟船運載著人們生活的甘苦回憶，流動著各行各業的繁榮盛況。也因百川匯集成河海大洋，人類不停追求自由夢想的海洋精神，得以無所畏懼地跨越艱鉅的波濤洶湧，抵達嚮往的大洋彼方。', `organizer`='國立故宮博物院', `address`='基隆市中正區北寧路367號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='國立海洋科技博物館', `latitude`=25.14365754, `longitude`=121.7783549, `ticket_price`='含主題館及第二特展廳+300', `source_url`='無資料', `image_url`='[]';
