INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('672b1b2807f388994d7ae082', '大唐生活美學館・2025年度徵件展', '為發掘並扶植台灣本土藝術家，鼓勵富有獨特性與當代性之多元創作，第二屆大唐徵件展我們將邀請學界與業界專業評審，共同審核。\r\n\r\n歡迎20歲至40歲之藝術創作者，踴躍投稿參加！\r\n\r\n首獎：一名，得於大唐舉辦個展一場\r\n優選：五名，將由本館規劃聯展公開展覽\r\n\r\n—— 歡迎您踴躍申請 ——\r\n\r\n⬢ 簡章資訊：\r\nhttps://reurl.cc/2j1kpv\r\n\r\n⬢ 徵件期間：\r\n即日起至2025年3月29下午6點止\r\n\r\n⬢ 收件方式：\r\n⑴ 下載文件並填寫報名表單\r\n⑵ 以「雲端資料夾或連結方式」寄送報名表及作品相關資料至大唐信箱：studiotang2017@gmail.com\r\n\r\n⬢ 展出日期：\r\n2025年7月8日至8月30日\r\n\r\n⬢ 洽詢聯繫：\r\n07-382-8858 分機號碼209 李小姐', '大唐生活美學館', '高雄市三民區九如一路588號', '2024-11-05 00:00:00', '2025-03-29 00:00:00', '大唐生活美學館', 22.64989883, 120.3179187, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大唐生活美學館・2025年度徵件展', `description`='為發掘並扶植台灣本土藝術家，鼓勵富有獨特性與當代性之多元創作，第二屆大唐徵件展我們將邀請學界與業界專業評審，共同審核。\r\n\r\n歡迎20歲至40歲之藝術創作者，踴躍投稿參加！\r\n\r\n首獎：一名，得於大唐舉辦個展一場\r\n優選：五名，將由本館規劃聯展公開展覽\r\n\r\n—— 歡迎您踴躍申請 ——\r\n\r\n⬢ 簡章資訊：\r\nhttps://reurl.cc/2j1kpv\r\n\r\n⬢ 徵件期間：\r\n即日起至2025年3月29下午6點止\r\n\r\n⬢ 收件方式：\r\n⑴ 下載文件並填寫報名表單\r\n⑵ 以「雲端資料夾或連結方式」寄送報名表及作品相關資料至大唐信箱：studiotang2017@gmail.com\r\n\r\n⬢ 展出日期：\r\n2025年7月8日至8月30日\r\n\r\n⬢ 洽詢聯繫：\r\n07-382-8858 分機號碼209 李小姐', `organizer`='大唐生活美學館', `address`='高雄市三民區九如一路588號', `start_date`='2024-11-05 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='大唐生活美學館', `latitude`=22.64989883, `longitude`=120.3179187, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
