INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('673506ae26b3246898829d5d', '南島織影-館藏原住民族衣飾文物特展', '衣飾是原住民族物質文化傳承的重要項目，無論是擷取材料、製作技藝、圖騰紋飾等面向，皆能反映族群所處的山海特性與天賦美感。「南島織影-館藏原住民族衣飾文物特展」便是運用館藏之臺灣原住民族原織文物進行策畫，展覽軸線分為二大主題，分別為：「衣飾文化的轉譯與融合」，從傳統南島民族的方衣系統到族群交流的漢式大襟衫，再至各族群特有織布技藝與圖騰文化，以及外來材質的交流與融合，所創造出獨特與多元的文化與美學風格。「山海恩澤的孕育與傳藝」則是呈現原住民族從山林、海洋中汲取獸皮、植物纖維、貝類等自然資源，製作各種質地的衣飾；另外也有來自海上的交易，取得本地未產的材料，諸如瑪瑙、琉璃珠、金、銀等，成為衣飾上的構件。透過展覽的呈現，讓我們能在這些珍貴的文物中，發掘箇中所含藏的創造力、想像力與社會文化意義。', '國史館臺灣文獻館', '南投縣南投市中興新村光明一路254號', '2025-01-01 00:00:00', '2025-05-04 00:00:00', '國史館臺灣文獻館', 23.9370101, 120.700722, '無資料', 'https://www.th.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南島織影-館藏原住民族衣飾文物特展', `description`='衣飾是原住民族物質文化傳承的重要項目，無論是擷取材料、製作技藝、圖騰紋飾等面向，皆能反映族群所處的山海特性與天賦美感。「南島織影-館藏原住民族衣飾文物特展」便是運用館藏之臺灣原住民族原織文物進行策畫，展覽軸線分為二大主題，分別為：「衣飾文化的轉譯與融合」，從傳統南島民族的方衣系統到族群交流的漢式大襟衫，再至各族群特有織布技藝與圖騰文化，以及外來材質的交流與融合，所創造出獨特與多元的文化與美學風格。「山海恩澤的孕育與傳藝」則是呈現原住民族從山林、海洋中汲取獸皮、植物纖維、貝類等自然資源，製作各種質地的衣飾；另外也有來自海上的交易，取得本地未產的材料，諸如瑪瑙、琉璃珠、金、銀等，成為衣飾上的構件。透過展覽的呈現，讓我們能在這些珍貴的文物中，發掘箇中所含藏的創造力、想像力與社會文化意義。', `organizer`='國史館臺灣文獻館', `address`='南投縣南投市中興新村光明一路254號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='國史館臺灣文獻館', `latitude`=23.9370101, `longitude`=120.700722, `ticket_price`='無資料', `source_url`='https://www.th.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6736344c26b3246898829d75', '【表演工作坊】《暗戀桃花源》', '無資料', '無資料', '臺中市西屯區惠來路二段101號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '臺中國家歌劇院大劇院', 24.1626492, 120.6403028, '無資料', 'https://www.opentix.life/program/1842015362624999425', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【表演工作坊】《暗戀桃花源》', `description`='無資料', `organizer`='無資料', `address`='臺中市西屯區惠來路二段101號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='臺中國家歌劇院大劇院', `latitude`=24.1626492, `longitude`=120.6403028, `ticket_price`='無資料', `source_url`='https://www.opentix.life/program/1842015362624999425', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('673653ac26b3246898829df3', '客語繪本主題書展＆走出戶外旅行趣 主題書展', '客語繪本主題書展\r\n除了展出「係做橋 抑係造橋」繪本外，也同時展出館內其它館藏的客語繪本。\r\n1.書展期間圖書館同步舉辦借閱客語(家)書籍免費索取繪本活動，凡當次借閱3本以上客語(家)相關書籍者，即可免費索取本繪本，限量50本，送完為止。\r\n2.當月的第一、第三週週六上午10點在圖書館一樓辦理「係做橋 抑係造橋」繪本客語說故事活動。\r\n3.贈書苗栗縣各公共圖書館，與造橋鄉內國國民小學與幼兒園。\r\n\r\n【走出戶外旅行趣 主題書展】\r\n當新的一年來臨，你準備好「好好吃、好好睡、好好玩」了嗎？\r\n旅遊，不僅是放鬆身心，更是給心靈充電，讓自己重新啟程，迎接生活中的每一個挑戰！\r\n造橋鄉立圖書館特別挑選了來自國內外的旅行書籍，讓你帶著玩樂的心情，輕鬆出發，開啟一段屬於你的旅程！', '苗栗縣造橋鄉公所', '苗栗縣造橋鄉14鄰1號', '2025-01-02 00:00:00', '2025-03-30 00:00:00', '苗栗縣造橋鄉立圖書館', 24.62481314, 120.8695663, '無資料', 'https://www.facebook.com/zaoqiao540040/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='客語繪本主題書展＆走出戶外旅行趣 主題書展', `description`='客語繪本主題書展\r\n除了展出「係做橋 抑係造橋」繪本外，也同時展出館內其它館藏的客語繪本。\r\n1.書展期間圖書館同步舉辦借閱客語(家)書籍免費索取繪本活動，凡當次借閱3本以上客語(家)相關書籍者，即可免費索取本繪本，限量50本，送完為止。\r\n2.當月的第一、第三週週六上午10點在圖書館一樓辦理「係做橋 抑係造橋」繪本客語說故事活動。\r\n3.贈書苗栗縣各公共圖書館，與造橋鄉內國國民小學與幼兒園。\r\n\r\n【走出戶外旅行趣 主題書展】\r\n當新的一年來臨，你準備好「好好吃、好好睡、好好玩」了嗎？\r\n旅遊，不僅是放鬆身心，更是給心靈充電，讓自己重新啟程，迎接生活中的每一個挑戰！\r\n造橋鄉立圖書館特別挑選了來自國內外的旅行書籍，讓你帶著玩樂的心情，輕鬆出發，開啟一段屬於你的旅程！', `organizer`='苗栗縣造橋鄉公所', `address`='苗栗縣造橋鄉14鄰1號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='苗栗縣造橋鄉立圖書館', `latitude`=24.62481314, `longitude`=120.8695663, `ticket_price`='無資料', `source_url`='https://www.facebook.com/zaoqiao540040/', `image_url`='[]';
