INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6737b28d26b3246898829e07', '「慢悠·自然」生活工藝特展', '「慢悠·自然」生活工藝特展\n\n慢悠．自然—生活工藝特展，透過永續工藝的視角，審視與自然的聯繫關係。以一種慢而有意識的生活美學，將工藝融合生存、生活、生命的三生共榮，讓每件作品體現對自然循環、材料及傳統技藝的尊重，展示當今快節奏下的另一種生活態度。\n\n以悠然自得的生活節奏與自然和諧共處的「慢悠．自然」為核心理念，感受作品與環境之間互動的「活工藝」，並展現藝師精湛的「工藝活」。\n \n\n"Slow Living, Embracing Nature-Living Craft Exhibition" explores the connection between sustainability and nature through the lens of traditional craftsmanship. This exhibition embraces a slow, mindful approach to life, where craft is intertwined with existence, daily living, and the essence of being. Each piece reflects a deep respect for nature''s cycles, the materials used, and the time-honored techniques of artisans, offering an alternative way of life amidst today''s fast-paced world.\n\nCentered around the theme of "Slow Living, Naturally," the exhibition celebrates a harmonious lifestyle in sync with nature. It showcases "living craftsmanship," where the works interact with their surroundings, and the "art of craft" that highlights the artisans'' mastery.\n \n\n \n\n「慢悠·自然」生活工藝特展\n\n展覽日期｜即日起-2025.6.30\n\n展覽時間 | 週二至週日09:00-17:00 (週一、除夕及初一休館)\n\n展覽地點｜國立臺灣工藝研究發展中心 生活工藝館1樓 （南投縣草屯鎮中正路573號）\n\n ', '國立台灣工藝研究發展中心', '542  南投縣草屯鎮中正路573號', '2024-09-28 00:00:00', '2025-06-29 00:00:00', '生活工藝館1樓', 23.9797002, 120.69095, '無資料', 'https://event.culture.tw/mocweb/reg/NTCRI/Detail.init.ctr?actId=40316', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「慢悠·自然」生活工藝特展', `description`='「慢悠·自然」生活工藝特展\n\n慢悠．自然—生活工藝特展，透過永續工藝的視角，審視與自然的聯繫關係。以一種慢而有意識的生活美學，將工藝融合生存、生活、生命的三生共榮，讓每件作品體現對自然循環、材料及傳統技藝的尊重，展示當今快節奏下的另一種生活態度。\n\n以悠然自得的生活節奏與自然和諧共處的「慢悠．自然」為核心理念，感受作品與環境之間互動的「活工藝」，並展現藝師精湛的「工藝活」。\n \n\n"Slow Living, Embracing Nature-Living Craft Exhibition" explores the connection between sustainability and nature through the lens of traditional craftsmanship. This exhibition embraces a slow, mindful approach to life, where craft is intertwined with existence, daily living, and the essence of being. Each piece reflects a deep respect for nature''s cycles, the materials used, and the time-honored techniques of artisans, offering an alternative way of life amidst today''s fast-paced world.\n\nCentered around the theme of "Slow Living, Naturally," the exhibition celebrates a harmonious lifestyle in sync with nature. It showcases "living craftsmanship," where the works interact with their surroundings, and the "art of craft" that highlights the artisans'' mastery.\n \n\n \n\n「慢悠·自然」生活工藝特展\n\n展覽日期｜即日起-2025.6.30\n\n展覽時間 | 週二至週日09:00-17:00 (週一、除夕及初一休館)\n\n展覽地點｜國立臺灣工藝研究發展中心 生活工藝館1樓 （南投縣草屯鎮中正路573號）\n\n ', `organizer`='國立台灣工藝研究發展中心', `address`='542  南投縣草屯鎮中正路573號', `start_date`='2024-09-28 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='生活工藝館1樓', `latitude`=23.9797002, `longitude`=120.69095, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTCRI/Detail.init.ctr?actId=40316', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6737b37c26b3246898829e18', '體感系閱讀：「視力檢查」天井書展', '人類接收外在資訊的方式，九成是由視覺而來，\r\n身處超級數位時代的我們，\r\n努力適應外界的快速變化，\r\n導致每個人的眼睛都有過勞的現象！\r\n\r\n以多數人共有的「視力檢查」體驗出發，\r\n借用常見的眼科檢測項目「眼壓測量」、「色覺檢測」、「黃斑部測試」\r\n以及舒緩眼部的「放鬆眼球」等四大主題的選讀分享，\r\n一同探索與拆解視覺表象背後的世界，\r\n打開感官的每一扇窗。\r\n', '高雄市立圖書館總館', '高雄市前鎮區21鄰新光路61號', '2025-01-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館總館', 22.6115529, 120.3024491, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='體感系閱讀：「視力檢查」天井書展', `description`='人類接收外在資訊的方式，九成是由視覺而來，\r\n身處超級數位時代的我們，\r\n努力適應外界的快速變化，\r\n導致每個人的眼睛都有過勞的現象！\r\n\r\n以多數人共有的「視力檢查」體驗出發，\r\n借用常見的眼科檢測項目「眼壓測量」、「色覺檢測」、「黃斑部測試」\r\n以及舒緩眼部的「放鬆眼球」等四大主題的選讀分享，\r\n一同探索與拆解視覺表象背後的世界，\r\n打開感官的每一扇窗。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市前鎮區21鄰新光路61號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館總館', `latitude`=22.6115529, `longitude`=120.3024491, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6737b3a026b3246898829e37', '無資料', '「書法是生動的建築，建築是立體的書法。」— 漢寶德\r\n\r\n2024年為漢寶德逝世十週年，為紀念這位傑出的文化巨擘，文化部推動系列展覽，由史博館辦理此次書法展覽呈現創作的完整面貌，藉此擴大展覽效益。\r\n建築是冰冷的石材與木材構建而成的空間藝術，書法是燃燒在紙上的情感與智慧。在漢寶德的書法中，每一筆每一劃，如同建築的每一條線條，每一處細節，都蘊含著創作者深沉的內涵與獨特的視角。當書法的筆墨與建築的結構相融合，我們看到藝術形式的交錯，體會文化精髓的深刻共鳴。\r\n書法，這門技藝承載著歷史的厚重與文化的精髓；其表現，更是一種文化的傳承與心靈的交流。藉由書寫而成的作品，超越時空的界限，讓我們能夠感受到古今文人的情懷與志趣。每一幅作品，都像是一首無聲的詩，讓人在品味其間，體悟書法之美與人生之真，作品便是內心世界的真實寫照。\r\n漢寶德對筆墨的掌控、對字形的構思、對結構的安排，都顯示出他對書法藝術的極致追求與深入理解。在他的作品中，我們看到傳統筆墨的學習，也感受到現代作品的勇於嘗試。以其獨特的風格和深邃的內涵，打破了時間的界限，讓古老的書法藝術在當代重新煥發出新的光彩。\r\n書法是漢寶德諸多成就中的一環，此次展出其對書法的研究與實踐的一部分，是文字的表達，也是對空間感知的一種延續，更是對美的敘述。透過這次展覽，相信能夠感受到書法筆劃的力量和建築設計的美感，在這種藝術的交融中，找到屬於自己的靈感與啟示。\r\n本展以漢寶德的書法觀念為出發，強調書法結合生活藝術。由家屬精選漢寶德書法作品102件展出。依其創作年代與風格面貌，分為循古、抒情、構成、新象等四部分進行展出。循古，即是傳統碑版學習的面貌。抒情，即是以書法內容傳遞內心意念。構成，為其對於畫面安排布置。新象，為其書法作品獨樹一格之處。從研究、臨摹到自創風格，寫書法是漢寶德回歸傳統的最終歷程，希冀透過本展讓民眾認識漢寶德的書法藝術。', '國立歷史博物館', '臺北市中正區濟南路二段27號', '臺灣文學基地', 25.03240487, 121.5198839, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='「書法是生動的建築，建築是立體的書法。」— 漢寶德\r\n\r\n2024年為漢寶德逝世十週年，為紀念這位傑出的文化巨擘，文化部推動系列展覽，由史博館辦理此次書法展覽呈現創作的完整面貌，藉此擴大展覽效益。\r\n建築是冰冷的石材與木材構建而成的空間藝術，書法是燃燒在紙上的情感與智慧。在漢寶德的書法中，每一筆每一劃，如同建築的每一條線條，每一處細節，都蘊含著創作者深沉的內涵與獨特的視角。當書法的筆墨與建築的結構相融合，我們看到藝術形式的交錯，體會文化精髓的深刻共鳴。\r\n書法，這門技藝承載著歷史的厚重與文化的精髓；其表現，更是一種文化的傳承與心靈的交流。藉由書寫而成的作品，超越時空的界限，讓我們能夠感受到古今文人的情懷與志趣。每一幅作品，都像是一首無聲的詩，讓人在品味其間，體悟書法之美與人生之真，作品便是內心世界的真實寫照。\r\n漢寶德對筆墨的掌控、對字形的構思、對結構的安排，都顯示出他對書法藝術的極致追求與深入理解。在他的作品中，我們看到傳統筆墨的學習，也感受到現代作品的勇於嘗試。以其獨特的風格和深邃的內涵，打破了時間的界限，讓古老的書法藝術在當代重新煥發出新的光彩。\r\n書法是漢寶德諸多成就中的一環，此次展出其對書法的研究與實踐的一部分，是文字的表達，也是對空間感知的一種延續，更是對美的敘述。透過這次展覽，相信能夠感受到書法筆劃的力量和建築設計的美感，在這種藝術的交融中，找到屬於自己的靈感與啟示。\r\n本展以漢寶德的書法觀念為出發，強調書法結合生活藝術。由家屬精選漢寶德書法作品102件展出。依其創作年代與風格面貌，分為循古、抒情、構成、新象等四部分進行展出。循古，即是傳統碑版學習的面貌。抒情，即是以書法內容傳遞內心意念。構成，為其對於畫面安排布置。新象，為其書法作品獨樹一格之處。從研究、臨摹到自創風格，寫書法是漢寶德回歸傳統的最終歷程，希冀透過本展讓民眾認識漢寶德的書法藝術。', `organizer`='國立歷史博物館', `address`='臺北市中正區濟南路二段27號', `location`='臺灣文學基地', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6737b3a526b3246898829e50', '「慢悠．自然」生活工藝特展', '慢悠．自然—生活工藝特展，透過永續工藝的視角，審視與自然的聯繫關係。以一種慢而有意識的生活美學，將工藝融合生存、生活、生命的三生共榮，讓每件作品體現對自然循環、材料及傳統技藝的尊重，展示當今快節奏下的另一種生活態度。\r\n以悠然自得的生活節奏與自然和諧共處的「慢悠．自然」為核心理念，感受作品與環境之間互動的「活工藝」，並展現藝師精湛的「工藝活」。', '國立臺灣工藝研究發展中心', '南投縣草屯鎮中正路573號', '2025-01-01 00:00:00', '2025-06-29 00:00:00', '國立臺灣工藝研究發展中心（臺灣工藝文化園區）', 23.9807747, 120.6918567, '無資料', 'https://www.ntcri.gov.tw/home/zh-tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「慢悠．自然」生活工藝特展', `description`='慢悠．自然—生活工藝特展，透過永續工藝的視角，審視與自然的聯繫關係。以一種慢而有意識的生活美學，將工藝融合生存、生活、生命的三生共榮，讓每件作品體現對自然循環、材料及傳統技藝的尊重，展示當今快節奏下的另一種生活態度。\r\n以悠然自得的生活節奏與自然和諧共處的「慢悠．自然」為核心理念，感受作品與環境之間互動的「活工藝」，並展現藝師精湛的「工藝活」。', `organizer`='國立臺灣工藝研究發展中心', `address`='南投縣草屯鎮中正路573號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='國立臺灣工藝研究發展中心（臺灣工藝文化園區）', `latitude`=23.9807747, `longitude`=120.6918567, `ticket_price`='無資料', `source_url`='https://www.ntcri.gov.tw/home/zh-tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('673b9ef326b3246898829eb4', '記憶盲盒—Meilin Lin纖維藝術創作個展', '17日（日）上午10時於南竿鄉民俗文物館1樓特展室，由連江縣政府主辦，沒毛病工作室承辦，邀請到國內知名纖維藝術創作者，也是馬祖東引鄉親林美玲老師，合作舉辦「記憶盲盒—Meilin Lin纖維藝術創作個展」，以童年小島裡的回憶，作為本次策展的主軸。\r\n\r\n    東引的熱鬧擺暝、黑央的臉譜、海上的船隻、傳統的石屋，甚至還有她對童年上課時，同學們臉上趣味表情的回憶，這些都是林美玲用纖維藝術所交織出的記憶，每一個作品都帶著馬祖特有的島嶼風情，融合了海洋、天空的色彩，讓人感受到濃濃的家鄉氣息。最讓人感動的是，她特別關注人文情懷，對那些老房子、舊聚落的留戀，讓家鄉的點滴真實地呈現在作品中，透過這些情感，喚起了我們對家鄉的記憶。\r\n\r\n    登記報名參加開展典禮的前30名朋友，且全程參加開展典禮，即可獲得本次特展專屬的「2025記憶盲盒精美桌曆」。欲參加者，請於線上報名：https://forms.gle/niSHGPG3HNJsJ1ti6。', '連江縣政府', '連江縣南竿鄉135號', '2025-01-01 00:00:00', '2025-03-16 00:00:00', '馬祖民俗文物館', 26.154321, 119.931128, '全票+40;優待票+20', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='記憶盲盒—Meilin Lin纖維藝術創作個展', `description`='17日（日）上午10時於南竿鄉民俗文物館1樓特展室，由連江縣政府主辦，沒毛病工作室承辦，邀請到國內知名纖維藝術創作者，也是馬祖東引鄉親林美玲老師，合作舉辦「記憶盲盒—Meilin Lin纖維藝術創作個展」，以童年小島裡的回憶，作為本次策展的主軸。\r\n\r\n    東引的熱鬧擺暝、黑央的臉譜、海上的船隻、傳統的石屋，甚至還有她對童年上課時，同學們臉上趣味表情的回憶，這些都是林美玲用纖維藝術所交織出的記憶，每一個作品都帶著馬祖特有的島嶼風情，融合了海洋、天空的色彩，讓人感受到濃濃的家鄉氣息。最讓人感動的是，她特別關注人文情懷，對那些老房子、舊聚落的留戀，讓家鄉的點滴真實地呈現在作品中，透過這些情感，喚起了我們對家鄉的記憶。\r\n\r\n    登記報名參加開展典禮的前30名朋友，且全程參加開展典禮，即可獲得本次特展專屬的「2025記憶盲盒精美桌曆」。欲參加者，請於線上報名：https://forms.gle/niSHGPG3HNJsJ1ti6。', `organizer`='連江縣政府', `address`='連江縣南竿鄉135號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='馬祖民俗文物館', `latitude`=26.154321, `longitude`=119.931128, `ticket_price`='全票+40;優待票+20', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('673cf0a426b3246898829ec7', '歌劇欣賞-詹明棧', '      \n\n\n	\n		\n			\n			國立國父紀念館第64期生活美學班課程大綱\n\n			課程名稱：歌劇欣賞                  授課教師：詹明棧\n\n			適合對象：                    \n			\n		\n		\n			\n			週次\n			\n			\n			日期\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			一\n			\n			\n			1/3\n			\n			\n			歌劇「門道」如何看？\n			\n			\n			文學、音樂、詠嘆、重唱、合唱、舞蹈、美術、演技。\n			\n		\n		\n			\n			二\n			\n			\n			1/10\n			\n			\n			歌劇名曲初體驗\n			\n			\n			愛情的煩惱、夜之后的怒火、花名冊之歌、一滴美妙的情淚、公主徹夜未眠、星光燦爛等\n			\n		\n		\n			\n			三\n			\n			\n			1/17\n			\n			\n			貝里尼的歌劇\n			\n			\n			清教徒\n			\n		\n		\n			\n			四\n			\n			\n			1/24\n			\n			\n			 \n			\n			\n			清教徒(續)\n			\n		\n		\n			\n			五\n			\n			\n			2/7\n			\n			\n			董尼采第的歌劇\n			\n			\n			聯隊之花\n			\n		\n		\n			\n			六\n			\n			\n			2/14\n			\n			\n			 \n			\n			\n			聯隊之花(續)\n			\n		\n		\n			\n			七\n			\n			\n			2/21\n			\n			\n			羅西尼的歌劇\n			\n			\n			賽蜜拉米德(Semiramide)\n			\n		\n		\n			\n			八\n			\n			\n			3/7\n			\n			\n			 \n			\n			\n			賽蜜拉米德(續)\n			\n		\n		\n			\n			九\n			\n			\n			3/14\n			\n			\n			華格納的歌劇\n			\n			\n			紐倫堡的名歌手\n			\n		\n		\n			\n			十\n			\n			\n			3/21\n			\n			\n			 \n			\n			\n			紐倫堡的名歌手(續)\n			\n		\n		\n			\n			十\n			\n			\n			3/28\n			\n			\n			 \n			\n			\n			紐倫堡的名歌手(續)\n			\n		\n		\n			\n			十二\n			\n			\n			4/11\n			\n			\n			馬士卡尼的歌劇\n			\n			\n			鄉村騎士\n			\n		\n	\n\n\n備註：本課程大綱，將隨課程進度以及學員的理解度，略作互動性的調整。\n      停課日期：1/31(春節)、2/28(紀念日)、4/4(清明節連續假期) \n\n\n \n\n\n\n \n\n                      \n\n\n\n\n\n ', '國立國父紀念館', '106  臺北市大安區信義路四段186巷7號', '2025-01-03 00:00:00', '2025-04-11 00:00:00', '12樓演講廳', 25.02677012, 121.5434446, '1800', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=40383', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歌劇欣賞-詹明棧', `description`='      \n\n\n	\n		\n			\n			國立國父紀念館第64期生活美學班課程大綱\n\n			課程名稱