INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('673cf0a626b3246898829ed8', '絹布油畫-黃明櫻', '   \n\n\n	\n		\n			\n			國立國父紀念館第64期生活美學班課程大綱\n\n			課程名稱：絹布油畫                                      授課教師：黃明櫻\n\n			適合對象：一般民眾\n			\n		\n		\n			\n			週次\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			一\n			\n			\n			絹布裱法\n			\n			\n			綁筆製作畫筆\n			\n		\n		\n			\n			二\n			\n			\n			藝術概論\n			\n			\n			構圖方法\n			\n		\n		\n			\n			三\n			\n			\n			藝術概論\n			\n			\n			水果與桌面布處理方法\n			\n		\n		\n			\n			四\n			\n			\n			藝術概論\n			\n			\n			花卉多元技法處理\n			\n		\n		\n			\n			五\n			\n			\n			藝術概論\n			\n			\n			有鱗片亮金金麟片畫法\n			\n		\n		\n			\n			六\n			\n			\n			藝術概論\n			\n			\n			多層次疊色風景畫法\n			\n		\n		\n			\n			七\n			\n			\n			藝術概論\n			\n			\n			透明毛絨的處理技法\n			\n		\n		\n			\n			八\n			\n			\n			藝術概論\n			\n			\n			濕中濕畫技法\n			\n		\n		\n			\n			九\n			\n			\n			肖像畫法\n			\n			\n			少女、兒童技巧處理\n			\n		\n		\n			\n			十\n			\n			\n			肖像畫法\n			\n			\n			老人皮膚質感處理\n			\n		\n		\n			\n			十一\n			\n			\n			肖像畫法\n			\n			\n			拼圖處理及黃金比例\n			\n		\n		\n			\n			十二\n			\n			\n			肖像畫法\n			\n			\n			拼圖處理及黃金比例\n			\n		\n	\n\n\n 註：1.本課程內容可能會隨著學員上課情形而有所調整,以實際上課情況為準\n\n  2.上課日期:1/4-4/26,共計12週,請學員注意上課日期！\n\n  3.停課:1/25、2/1、2/8、3/1、4/5\n\n                               \n\n  \n\n ', '國立國父紀念館', '106  臺北市大安區信義路四段186巷8號', '2025-01-04 00:00:00', '2025-04-26 00:00:00', '自衡樓教室2', 25.02677012, 121.5434446, '2600', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=40353', '[]') ON DUPLICATE KEY UPDATE `activity_name`='絹布油畫-黃明櫻', `description`='   \n\n\n	\n		\n			\n			國立國父紀念館第64期生活美學班課程大綱\n\n			課程名稱：絹布油畫                                      授課教師：黃明櫻\n\n			適合對象：一般民眾\n			\n		\n		\n			\n			週次\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			一\n			\n			\n			絹布裱法\n			\n			\n			綁筆製作畫筆\n			\n		\n		\n			\n			二\n			\n			\n			藝術概論\n			\n			\n			構圖方法\n			\n		\n		\n		