INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('673f92ce26b324689882a006', '永生花小樹球(小朋友6-12歲)', ' ※ 本課程最低開班人數：9 組 (須完成繳費)  。 \n\n（小朋友參加年齡依照學校入學分齡標準，以9月2日為分界）\n\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			永生花小樹球（親子課程/小朋友年齡6-12歲）\n			\n		\n		\n			\n			課程目標\n			\n			\n			引導學員運用創意，親手打造專屬的花藝作品，讓裝飾更具個人風格。\n\n			學習到不同植物與飾品的搭配，理解色彩與材質的協調性，進而提升美學眼光。透過親自製作的過程，不僅享受節日氛圍，也能感受到動手創作帶來的成就感。\n			\n		\n		\n			\n			時 間\n			\n			\n			課 程 主 題\n			\n			\n			教 學 內 容\n			\n		\n		\n			\n			8/3(日)\n\n			10:00-12:00\n			\n			\n			永生花小樹球\n			\n			\n			\n				引導學員使用永生花、苔蘚和微型飾品，創作出可長期保存的精緻小樹球擺飾。\n				學習基礎的花材處理、花與苔蘚的固定技法，以及樹球的整體造型設計。並運用色彩搭配與構圖，打造層次豐富、和諧美觀的樹球，並掌握永生花保養技巧。\n			\n			\n		\n		\n			\n			    備註：\n\n			  1. 請穿著不怕髒的衣服，或自備美術圍裙。\n\n			  2.自備剪刀、環保袋(帶回課程作品)\n			\n		\n	\n\n\n \n\n👉同類型美術創作、植物生態課程：\n\n春天的蒐集(2/9) 、與光同行(3/9)、植物的纖維(3/23)、春神的花園(4/13)、\n\n植物的果實與種子(4/27)、星星的祝福-星星的花(5/4)、四季之庭(6/8)、\n\n緩緩行走-光之河(7/6)、風裡的飛翔(9/7)、獼猴媽媽的愛(10/19)、\n\n內在的心星(11/2)、果好(12/7)、松果聖誕樹(12/21)\n\n\n \n\n【教室位置圖】：上課地點在W315教室\n\n\n\n★ 【W315教室位置圖】\n\n\n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-08-03 00:00:00', '2025-08-03 00:00:00', 'W315教室', 25.0367564, 121.519047, '850', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=41249', '[]') ON DUPLICATE KEY UPDATE `activity_name`='永生花小樹球(小朋友6-12歲)', `description`=' ※ 本課程最低開班人數：9 組 (須完成繳費)  。 \n\n（小朋友參加年齡依照學校入學分齡標準，以9月2日為分界）\n\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			永生花小樹球（親子課程/小朋友年齡6-12歲）\n			\n		\n		\n			\n			課程目標\n			\n			\n			引導學員運用創意，親手打造專屬的花藝作品，讓裝飾更具個人風格。\n\n			學習到不同植物與飾品的搭配，理解色彩與材質的協調性，進而提升美學眼光。透過親自製作的過程，不僅享受節日氛圍，也能感受到動手創作帶來的成就感。\n			\n		\n		\n			\n			時 間\n			\n			\n			課 程 主 題\n			\n			\n			教 學 內 容\n			\n		\n		\n			\n			8/3(日)\n\n			10:00-12:00\n			\n			\n			永生花小樹球\n			\n			\n			\n				引導學員使用永生花、苔蘚和微型飾品，創作出可長期保存的精緻小樹球擺飾。\n				學習基礎的花材處理、花與苔蘚的固定技法，以及樹球的整體造型設計。並運用色彩搭配與構圖，打造層次豐富、和諧美觀的樹球，並掌握永生花保養技巧。\n			\n			\n		\n		\n			\n			    備註：\n\n			  1. 請穿著不怕髒的衣服，或自備美術圍裙。\n\n			  2.自備剪刀、環保袋(帶回課程作品)\n			\n		\n	\n\n\n \n\n👉同類型美術創作、植物生態課程：\n\n春天的蒐集(2/9) 、與光同行(3/9)、植物的纖維(3/23)、春神的花園(4/13)、\n\n植物的果實與種子(4/27)、星星的祝福-星星的花(5/4)、四季之庭(6/8)、\n\n緩緩行走-光之河(7/6)、風裡的飛翔(9/7)、獼猴媽媽的愛(10/19)、\n\n內在的心星(11/2)、果好(12/7)、松果聖誕樹(12/21)\n\n\n \n\n【教室位置圖】：上課地點在W315教室\n\n\n\n★ 【W315教室位置圖】\n\n\n\n \n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-08-03 00:00:00', `end_date`='2025-08-03 00:00:00', `location`='W315教室', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='850', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=41249', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('673f92cf26b324689882a00a', '賞蛙趣-是蟾蜍還是青蛙?(小朋友3-6歲)', ' ※ 本課程最低開班人數：10組 (須完成繳費)  。 \n\n（小朋友參加年齡依照學校入學分齡標準，以9月2日為分界）\n\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			賞蛙趣-是蟾蜍還是青蛙?（親子課程/小朋友年齡3-6歲）\n			\n		\n		\n			\n			課程目標\n			\n			介紹各種蛙類的特徵和生命小故事，如何從鳴叫聲分辨出不同蛙類，認識蛙類生態及特殊育幼行為。\n		\n		\n			\n			時 間\n			\n			\n			課 程 主 題\n			\n			\n			教 學 內 容\n			\n		\n		\n			\n			11/16(日)\n\n			10:00-11:00\n			\n			\n			賞蛙趣-\n\n			是蟾蜍還是青蛙?\n			\n			\n			\n				帶領孩子認識蛙類的特徵和生命週期。\n				從各種蛙類鳴叫聲認識不同蛙類。\n				介紹蛙類的生態及特殊育幼行為。\n			\n			\n		\n		\n			\n			    備註：請穿著不怕髒的衣服，或自備美術圍裙。\n			\n		\n	\n\n\n \n\n\n👉同類型動植物相關、環境生態課程：\n\n植物的纖維(3/23)、植物的果實與種子(4/27) 、甲蟲王者-鍬形蟲與獨角仙(6/15)、\n\n永生花小樹球(8/3)、松果聖誕樹(12/21)\n\n\n\n \n\n【教室位置圖】：上課地點在W315教室\n\n\n\n★ 【W315教室位置圖】\n\n\n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-11-16 00:00:00', '2025-11-16 00:00:00', 'W315教室', 25.0367564, 121.519047, '450', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=41253', '[]') ON DUPLICATE KEY UPDATE `activity_name`='賞蛙趣-是蟾蜍還是青蛙?(小朋友3-6歲)', `description`=' ※ 本課程最低開班人數：10組 (須完成繳費)  。 \n\n（小朋友參加年齡依照學校入學分齡標準，以9月2日為分界）\n\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			賞蛙趣-是蟾蜍還是青蛙?（親子課程/小朋友年齡3-6歲）\n			\n		\n		\n			\n			課程目標\n			\n			介紹各種蛙類的特徵和生命小故事，如何從鳴叫聲分辨出不同蛙類，認識蛙類生態及特殊育幼行為。\n		\n		\n			\n			時 間\n			\n			\n			課 程 主 題\n			\n			\n			教 學 內 容\n			\n		\n		\n			\n			11/16(日)\n\n			10:00-11:00\n			\n			\n			賞蛙趣-\n\n			是蟾蜍還是青蛙?\n			\n			\n			\n				帶領孩子認識蛙類的特徵和生命週期。\n				從各種蛙類鳴叫聲認識不同蛙類。\n				介紹蛙類的生態及特殊育幼行為。\n			\n			\n		\n		\n			\n			    備註：請穿著不怕髒的衣服，或自備美術圍裙。\n			\n		\n	\n\n\n \n\n\n👉同類型動植物相關、環境生態課程：\n\n植物的纖維(3/23)、植物的果實與種子(4/27) 、甲蟲王者-鍬形蟲與獨角仙(6/15)、\n\n永生花小樹球(8/3)、松果聖誕樹(12/21)\n\n\n\n \n\n【教室位置圖】：上課地點在W315教室\n\n\n\n★ 【W315教室位置圖】\n\n\n\n \n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-11-16 00:00:00',