INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('673f92cf26b324689882a00b', '果好(小朋友3-8歲)【確定開班】', ' ※ 本課程最低開班人數：11 組 (須完成繳費)  。 \n\n（小朋友參加年齡依照學校入學分齡標準，以9月2日為分界）\n\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			果好（親子課程/小朋友年齡3-8歲）\n			\n		\n		\n			\n			課程目標\n			\n			讓孩子從大自然的藝術殿堂裡，發覺美，感覺美，表達美。\n		\n		\n			\n			時 間\n			\n			\n			課 程 主 題\n			\n			\n			教 學 內 容\n			\n		\n		\n			\n			12/7(日)\n\n			10:00-11:00\n			\n			\n			果好\n			\n			\n			大地果實，紫紫藍藍橘橘紅紅，這些渾圓成串的繽紛，是世界的禮物。他們帶著美滿的喜悅來到世界上，為大地帶來延續生命的力量。果實帶著安好平和的祝福，也會為我們帶來幸福。\n\n			創作｜紙藝+畫畫字\n			\n		\n		\n			\n			    備註：請穿著不怕髒的衣服，或自備美術圍裙。\n			\n		\n	\n\n\n \n\n\n👉同類型美術創作、植物生態課程：\n\n春天的蒐集(2/9) 、與光同行(3/9)、植物的纖維(3/23)、春神的花園(4/13)、\n\n植物的果實與種子(4/27)、星星的祝福-星星的花(5/4)、四季之庭(6/8)、\n\n緩緩行走-光之河(7/6)、永生花小樹球(8/3)、風裡的飛翔(9/7)、\n\n獼猴媽媽的愛(10/19)、松果聖誕樹(12/21)\n\n\n\n \n\n【教室位置圖】：上課地點在W315教室\n\n\n\n★ 【W315教室位置圖】\n\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-12-07 00:00:00', '2025-12-07 00:00:00', 'W315教室', 25.0367564, 121.519047, '500', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=41254', '[]') ON DUPLICATE KEY UPDATE `activity_name`='果好(小朋友3-8歲)【確定開班】', `description`=' ※ 本課程最低開班人數：11 組 (須完成繳費)  。 \n\n（小朋友參加年齡依照學校入學分齡標準，以9月2日為分界）\n\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			果好（親子課程/小朋友年齡3-8歲）\n			\n		\n		\n			\n			課程目標\n			\n			讓孩子從大自然的藝術殿堂裡，發覺美，感覺美，表達美。\n		\n		\n			\n			時 間\n			\n			\n			課 程 主 題\n			\n			\n			教 學 內 容\n			\n		\n		\n			\n			12/7(日)\n\n			10:00-11:00\n			\n			\n			果好\n			\n			\n			大地果實，紫紫藍藍橘橘紅紅，這些渾圓成串的繽紛，是世界的禮物。他們帶著美滿的喜悅來到世界上，為大地帶來延續生命的力量。果實帶著安好平和的祝福，也會為我們帶來幸福。\n\n			創作｜紙藝+畫畫字\n			\n		\n		\n			\n			    備註：請穿著不怕髒的衣服，或自備美術圍裙。\n			\n		\n	\n\n\n \n\n\n👉同類型美術創作、植物生態課程：\n\n春天的蒐集(2/9) 、與光同行(3/9)、植物的纖維(3/23)、春神的花園(4/13)、\n\n植物的果實與種子(4/27)、星星的祝福-星星的花(5/4)、四季之庭(6/8)、\n\n緩緩行走-光之河(7/6)、永生花小樹球(8/3)、風裡的飛翔(9/7)、\n\n獼猴媽媽的愛(10/19)、松果聖誕樹(12/21)\n\n\n\n \n\n【教室位置圖】：上課地點在W315教室\n\n\n\n