INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('673f941926b324689882a0a7', '客家大戲光影年代-客家大戲特展', '客家大戲源自於乾隆、嘉慶年間的三腳採茶戲，吸收了亂彈、四平等各種劇種的表演影響，逐漸從民間小戲形式發展成為具有高度藝術價值和娛樂性的劇場演出模式。\r\n隨著五十年代新興娛樂形式興起，尤其電視的普及，傳統客家戲面臨嚴峻的市場挑戰，但即便如此，客家大戲仍以適應民間宗教集會之需求的外臺戲，持續存在與發展，就是比較多人在廟會看過的『扮仙戲』，保有其重要的宗教和社會功能。\r\n本展覽大量的展示榮興客家採茶劇團歷年演出的大戲海報，不只呈現客家戲曲的歷史沿革與文化魅力，在現代娛樂衝擊下，更展現了客家大戲的生命力以及獨特的文化價值，讓您感受【戲曲魅力】最近的距離……。\r\n現場除展示大戲『劇服』、『頭飾』外，還播放曾於國家劇院公演的《婆媳風雲》等四部大戲精采演出片段，有著動人心弦的曲調，同時也讓您一飽眼福。', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-01-01 00:00:00', '2025-04-14 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '無資料', 'https://www.facebook.com/hakkapark', '[]') ON DUPLICATE KEY UPDATE `activity_name`='客家大戲光影年代-客家大戲特展', `description`='客家大戲源自於乾隆、嘉慶年間的三腳採茶戲，吸收了亂彈、四平等各種劇種的表演影響，逐漸從民間小戲形式發展成為具有高度藝術價值和娛樂性的劇場演出模式。\r\n隨著五十年代新興娛樂形式興起，尤其電視的普及，傳統客家戲面臨嚴峻的市場挑戰，但即便如此，客家大戲仍以適應民間宗教集會之需求的外臺戲，持續存在與發展，就是比較多人在廟會看過的『扮仙戲』，保有其重要的宗教和社會功能。\r\n本展覽大量的展示榮興客家採茶劇團歷年演出的大戲海報，不只呈現客家戲曲的歷史沿革與文化魅力，在現代娛樂衝擊下，更展現了客家大戲的生命力以及獨特的文化價值，讓您感受【戲曲魅力】最近的距離……。\r\n現場除展示大戲『劇服』、『頭飾』外，還播放曾於國家劇院公演的《婆媳風雲》等四部大戲精采演出片段，有著動人心弦的曲調，同時也讓您一飽眼福。', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-14 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='無資料', `source_url`='https://www.facebook.com/hakkapark', `image_url`='[]';
