INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6740e51d26b324689882a125', '北中寮：藝起來-書法藝文活動', '報名方式：即日起至114年1月2日開課前，至圖書館服務台報名並繳交報名名。每班招生人數至少15人。招生人數不足，不予開班。歡迎親子一起共學。', '南投縣中寮鄉公所', '南投縣中寮鄉', '2025-01-02 00:00:00', '2025-06-19 00:00:00', '中寮鄉（南投縣）=', 23.90589214, 120.7859159, '報名費+200', 'https://www.facebook.com/profile.php?id=100081167516780', '[]') ON DUPLICATE KEY UPDATE `activity_name`='北中寮：藝起來-書法藝文活動', `description`='報名方式：即日起至114年1月2日開課前，至圖書館服務台報名並繳交報名名。每班招生人數至少15人。招生人數不足，不予開班。歡迎親子一起共學。', `organizer`='南投縣中寮鄉公所', `address`='南投縣中寮鄉', `start_date`='2025-01-02 00:00:00', `end_date`='2025-06-19 00:00:00', `location`='中寮鄉（南投縣）=', `latitude`=23.90589214, `longitude`=120.7859159, `ticket_price`='報名費+200', `source_url`='https://www.facebook.com/profile.php?id=100081167516780', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6740e51e26b324689882a136', '《戀戀山之音》-三地門鄉排灣雙管口、鼻笛特展', '特展以「三地門排灣雙管口、鼻笛」為主題軸心發展， 除這排灣族雙管口、鼻笛樂音對於台灣的無形文化資產保存具有重要的意義與價值，同時也希望透過「聲音」、「文件」、「影像」創造更多元的參觀體驗，以不同形式展現三地門鄉的傳統樂音、文化藝術及傳說故事等。\r\n\r\n台灣原住民族在台灣世代的歷史情境中，其人文藝術扮演著台灣人生命氣息永續傳延的重要角色，而台灣原住民族在每一個不同的世代裡，總有一些獨特的在群山間傳述故事的人，人的「手」與「山」長出的植物、樹木相遇互動，衍生出族人活著的記憶和「故事」。', '屏東縣三地門鄉公所', '屏東縣三地門鄉中正路110號', '2025-01-01 00:00:00', '2025-03-31 00:00:00', '屏東縣三地門鄉原住民文化館', 22.79786847, 120.6865219, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《戀戀山之音》-三地門鄉排灣雙管口、鼻笛特展', `description`='特展以「三地門排灣雙管口、鼻笛」為主題軸心發展， 除這排灣族雙管口、鼻笛樂音對於台灣的無形文化資產保存具有重要的意義與價值，同時也希望透過「聲音」、「文件」、「影像」創造更多元的參觀體驗，以不同形式展現三地門鄉的傳統樂音、文化藝術及傳說故事等。\r\n\r\n台灣原住民族在台灣世代的歷史情境中，其人文藝術扮演著台灣人生命氣息永續傳延的重要角色，而台灣原住民族在每一個不同的世代裡，總有一些獨特的在群山間傳述故事的人，人的「手」與「山」長出的植物、樹木相遇互動，衍生出族人活著的記憶和「故事」。', `organizer`='屏東縣三地門鄉公所', `address`='屏東縣三地門鄉中正路110號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='屏東縣三地門鄉原住民文化館', `latitude`=22.79786847, `longitude`=120.6865219, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6740e52026b324689882a15f', '作伙歡喜來閱讀～閱翻悅有趣：老庄社區圖書展（借閱活動）', '老庄社區圖書借閱活動，由卓蘭鎮立圖書館提供書籍在老庄社區活動中心1樓社區書櫃展出，並提供社區民眾借閱。社區書櫃內容有：樂齡健康養生書、兒童繪本、青少年讀物、成人書籍等各類書籍。歡迎大小朋友一起【作伙歡喜來閱讀~閱翻悅有趣】讓書香伴您度過美好的一天！', '苗栗縣卓蘭鎮立圖書館', '苗栗縣卓蘭鎮', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '卓蘭鎮（苗栗縣）=', 24.32510167, 120.8561966, '無資料', 'https://www.juolan.gov.tw/Default.aspx', '[]') ON DUPLICATE KEY UPDATE `activity_name`='作伙歡喜來閱讀～閱翻悅有趣：老庄社區圖書展（借閱活動）', `description`='老庄社區圖書借閱活動，由卓蘭鎮立圖書館提供書籍在老庄社區活動中心1樓社區書櫃展出，並提供社區民眾借閱。社區書櫃內容有：樂齡健康養生書、兒童繪本、青少年讀物、成人書籍等各類書籍。歡迎大小朋友一起【作伙歡喜來閱讀~閱翻悅有趣】讓書香伴您度過美好的一天！', `organizer`='苗栗縣卓蘭鎮立圖書館', `address`='苗栗縣卓蘭鎮', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='卓蘭鎮（苗栗縣）=', `latitude`=24.32510167, `longitude`=120.8561966, `ticket_price`='無資料', `source_url`='https://www.juolan.gov.tw/Default.aspx', `image_url`='[]';
