INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6740e52026b324689882a163', '泰雅文物館常設展', '館內主要展示泰安鄉部落分布與遷移歷史、泰雅文化、歲時祭儀等，並有木雕、藤編、口簧琴及傳統服飾等文物收藏。\r\n洽詢電話：037-941805。', '苗栗縣政府原住民族及族群發展處', '苗栗縣泰安鄉圓墩6鄰46-3號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '苗栗縣泰雅原住民文化產業區', 24.41925819, 121.0681571, '無資料', 'https://cipa.miaoli.gov.tw/Default.aspx', '[]') ON DUPLICATE KEY UPDATE `activity_name`='泰雅文物館常設展', `description`='館內主要展示泰安鄉部落分布與遷移歷史、泰雅文化、歲時祭儀等，並有木雕、藤編、口簧琴及傳統服飾等文物收藏。\r\n洽詢電話：037-941805。', `organizer`='苗栗縣政府原住民族及族群發展處', `address`='苗栗縣泰安鄉圓墩6鄰46-3號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='苗栗縣泰雅原住民文化產業區', `latitude`=24.41925819, `longitude`=121.0681571, `ticket_price`='無資料', `source_url`='https://cipa.miaoli.gov.tw/Default.aspx', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6740e52026b324689882a167', '「榮興客家採茶劇團」特展', '榮興客家採茶劇團\r\n五０年代客家採茶戲名伶鄭美妹女士之孫－鄭榮興先生，於1986年重組其祖母當年劇團，1988年重新登記為「榮興客家採茶劇團」，曾獲教育部「民族藝術薪傳獎」、「推展社會教育有功團體獎」、「社教公益團體獎」，為苗栗縣「無形文化資產」傳統藝術類「採茶戲」之保存團體。\r\n榮興客家採茶劇團以研究、保存、傳承與推廣傳統客家戲曲藝術文化為宗旨，自成立以來，致力於推廣傳承客家戲曲表演藝術文化，培訓儲備客家戲曲表演人才，執行客家藝文資源調查研究專案，承辦相關藝術文化活動，呈現傳統藝術新風貌，發揚傳統客家文化之光華！', '臺灣客家八音戲曲推廣中心', '苗栗縣後龍鎮7鄰新港三路295號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺灣客家八音戲曲推廣中心（客家圓樓）', 24.6051162, 120.8229661, '全票+200;團體票+180;優待票+50', 'https://www.facebook.com/hakkarlove', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「榮興客家採茶劇團」特展', `description`='榮興客家採茶劇團\r\n五０年代客家採茶戲名伶鄭美妹女士之孫－鄭榮興先生，於1986年重組其祖母當年劇團，1988年重新登記為「榮興客家採茶劇團」，曾獲教育部「民族藝術薪傳獎」、「推展社會教育有功團體獎」、「社教公益團體獎」，為苗栗縣「無形文化資產」傳統藝術類「採茶戲」之保存團體。\r\n榮興客家採茶劇團以研究、保存、傳承與推廣傳統客家戲曲藝術文化為宗旨，自成立以來，致力於推廣傳承客家戲曲表演藝術文化，培訓儲備客家戲曲表演人才，執行客家藝文資源調查研究專案，承辦相關藝術文化活動，呈現傳統藝術新風貌，發揚傳統客家文化之光華！', `organizer`='臺灣客家八音戲曲推廣中心', `address`='苗栗縣後龍鎮7鄰新港三路295號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺灣客家八音戲曲推廣中心（客家圓樓）', `latitude`=24.6051162, `longitude`=120.8229661, `ticket_price`='全票+200;團體票+180;優待票+50', `source_url`='https://www.facebook.com/hakkarlove', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6740e52126b324689882a171', '臺灣意象展-變動中的臺灣人 ', '●變動中的臺灣人\r\n\r\n本展透過歷史上在臺灣交會過的人群所留下的紀錄、文物與遺跡，呈現在曲折變動的歷程中，他們如何互相影響、摩擦、爭執、交融，型塑出特殊的「臺灣人經驗」。同時也透過臺灣人經驗的雜揉性（hybridity），省思臺灣社會不同人群之間的關係，尋求更為開放、相互連結的可能性。\r\n\r\n●遭遇與接觸\r\n\r\n本展區分別以外來訪客與臺灣住民的視角，來看17世紀以降島上不同人群的交流。臺灣的人事或繪畫的形式，出現在這些造訪者的紀錄中。他們多半以獵奇的眼光描繪臺灣的住民，同時也呈現出他們在不同的情境下，為了各種原因，如貿易、殖民、漂流，來到臺灣的所見所聞。此外，臺灣住民與外來人群的接觸、交流經驗，也遺留在今日臺灣人的生活中，例如：火繩槍、新港文書。\r\n\r\n●人群的交會\r\n\r\n臺灣歷史上不同的統治者，都曾分類臺灣的人群，例如「番」、「熟番」、「漢」、「平埔族」、「高砂族」，乃至於今日的「四大族群」等。但無論是血統上或文化上的分類，都會有難以被界定的曖昧地帶，需要被特別關注。此外，被分類的臺灣住民不僅會因流動與通婚不斷變動；人們也會在統治規則的狹縫中，找尋有利自己的安身之處。改朝換代、政策轉變，也會帶來不同的人群分類以及不同性質的移民，再產生新一波的文化與社會交流。\r\n\r\n●文化的雜揉\r\n\r\n一波波人群的交會和互動，構成彼此的雜揉性（hybridity），具體而微地呈現在臺灣人生活的各個層面中，從日常起居中的各種物件、生活習慣，到形而上的信仰世界，藝術家、工藝家所呈現的美感也積累了不同人群的文化元素，以及不同時期主流文化對臺灣的影響。\r\n\r\n●人群的多重對話\r\n\r\n多元族群、多元文化的社會，不能只由各群體宣稱自己的獨特性與純粹的傳統，卻遮蔽掉群體內部的差別與不平等，而是認可與接受群體之間的差異，尋求更為多面向的連結與創意。近年臺灣社會的自由化與多元化，使那些原本被忽視、壓迫與邊緣化的人群，開始被看見與聽到。同時，原本無法輕易被分類定義的生活經驗與文化價值，也挑戰我們習以為常的規則與秩序。', '六堆客家文化園區', '屏東縣內埔鄉信義路588號', '2025-01-01 00:00:00', '2025-11-30 00:00:00', '六堆客家文化園區', 22.65116933, 120.5888222, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺灣意象展-變動中的臺灣人 ', `description`='●變動中的臺灣人\r\n\r\n本展透過歷史上在臺灣交會過的人群所留下的紀錄、文物與遺跡，呈現在曲折變動的歷程中，他們如何互相影響、摩擦、爭執、交融，型塑出特殊的「臺灣人經驗」。同時也透過臺灣人經驗的雜揉性（hybridity），省思臺灣社會不同人群之間的關係，尋求更為開放、相互連結的可能性。\r\n\r\n●遭遇與接觸\r\n\r\n本展區分別以外來訪客與臺灣住民的視角，來看17世紀以降島上不同人群的交流。臺灣的人事或繪畫的形式，出現在這些造訪者的紀錄中。他們多半以獵奇的眼光描繪臺灣的住民，同時也呈現出他們在不同的情境下，為了各種原因，如貿易、殖民、漂流，來到臺灣的所見所聞。此外，臺灣住民與外來人群的接觸、交流經驗，也遺留在今日臺灣人的生活中，例如：火繩槍、新港文書。\r\n\r\n●人群的交會\r\n\r\n臺灣歷史上不同的統治者，都曾分類臺灣的人群，例如「番」、「熟番」、「漢」、「平埔族」、「高砂族」，乃至於今日的「四大族群」等。但無論是血統上或文化上的分類，都會有難以被界定的曖昧地帶，需要被特別關注。此外，被分類的臺灣住民不僅會因流動與通婚不斷變動；人們也會在統治規則的狹縫中，找尋有利自己的安身之處。改朝換代、政策轉變，也會帶來不同的人群分類以及不同性質的移民，再產生新一波的文化與社會交流。\r\n\r\n●文化的雜揉\r\n\r\n一波波人群的交會和互動，構成彼此的雜揉性（hybridity），具體而微地呈現在臺灣人生活的各個層面中，從日常起居中的各種物件、生活習慣，到形而上的信仰世界，藝術家、工藝家所呈現的美感也積累了不同人群的文化元素，以及不同時期主流文化對臺灣的影響。\r\n\r\n●人群的多重對話\r\n\r\n多元族群、多元文化的社會，不能只由各群體宣稱自己的獨特性與純粹的傳統，卻遮蔽掉群體內部的差別與不平等，而是認可與接受群體之間的差異，尋求更為多面向的連結與創意。近年臺灣社會的自由化與多元化，使那些原本被忽視、壓迫與邊緣化的人群，開始被看見與聽到。同時，原本無法輕易被分類定義的生活經驗與文化價值，也挑戰我們習以為常的規則與秩序。', `organizer`='六堆客家文化園區', `address`='屏東縣內埔鄉信義路588號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='六堆客家文化園區', `latitude`=22.65116933, `longitude`=120.5888222, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
