INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6744e52426b324689882a206', '114年春季藝文研習班', '【研習時間】\r\n114年2月11日起至7月4日止\r\n(依實際上課時間為準，228、清明節、端午節等連假停課一次)。遇天然災害如颱風等，依行政院人事行政總處或臺中市政府所發布之公告為停復課依據，不另通知。停課則課程順延。\r\n\r\n\r\n【優待辦法】詳見網址\r\n【其他事項】詳見網址\r\n1.墨池常潤書法A 3/4-6/10 9:40-11:40\r\n2.焗瓷、金繕基礎班 3/4-5/6 19:00-21:00(10次)\r\n3.箏心琴藝 3/4-6/10 19:00-21:00\r\n4.基礎瑜珈A(週二班) 2/11-6/10 19:00-19:50(18次)\r\n5.基礎瑜珈B(週二班) 2/11-6/10 20:00-20:50(18次)\r\n6.陶雕技藝 3/5-6/11 9:00-16:00(8次)\r\n7.行書 日常的書寫 3/5-6/11 19:00-21:00\r\n8.禪棍脊椎核心照護運動 2/12-6/11 19:00-20:40(18次)\r\n9.漆器工藝漆繕 3/5-6/11 18:30-21:30\r\n10.墨池常潤書法B 3/6-6/19 13:30-15:30\r\n11.小兒童美術 A (週四班) 3/6-6/19 19:00-21:00\r\n12.中華花藝 2/20-6/5 19:00-21:00(8堂)\r\n13.基礎瑜珈C(週四班) 2/13-6/19 19:00-19:50(18次)\r\n14.基礎瑜珈D(週四班) 2/13-6/19 20:00-20:50\r\n15.數位單眼攝影入門(一) 3/6-6/19 19:00-21:00\r\n16.茶席生活美學 3/6-6/19 18:30-21:30\r\n17.粉彩與素描 2/21-6/20 13:30-16:30\r\n18.大兒童美術A(週五班) 2/21-6/20 19:00-21:00\r\n19.熟齡核心保健皮拉提斯 2/14-7/4 19:00-20:40(18次)\r\n20.世界少數民族編織 2/15-6/14 9:00-12:00\r\n21.水墨畫初階 2/15-6/14 9:00-12:00\r\n22.水墨畫進階 2/15-6/14 13:30-16:30\r\n23.揚琴研習 2/15-6/14 10:00-12:00\r\n24.油畫 2/15-6/14 13:30-16:30\r\n25.大兒童美術B(週六班)2/15-6/14 10:00-12:00\r\n26.快樂學陶笛 2/15-6/14 13:00-15:00\r\n27.小兒童美術B (週六班) 2/15-6/14 15:10-17:10\r\n28.素描藝術 2/15-6/14 18:30-21:30\r\n29.水彩專門研習 2/16-6/15 9:30-12:30\r\n30.素描速寫 2/16-6/15 14:00-17:00\r\n31.水彩畫趣 2/16-6/15 18:00-21:00\r\n32.創意生活木工 2/16-6/29 9:00-16:00\r\n', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-02-11 00:00:00', '2025-07-04 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Activity/Activity_More?id=3702188a76e74facb83ba1dd8f6f69e9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年春季藝文研習班', `description`='【研習時間】\r\n114年2月11日起至7月4日止\r\n(依實際上課時間為準，228、清明節、端午節等連假停課一次)。遇天然災害如颱風等，依行政院人事行政總處或臺中市政府所發布之公告為停復課依據，不另通知。停課則課程順延。\r\n\r\n\r\n【優待辦法】詳見網址\r\n