INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67463c0b26b324689882a24b', '「鳴蟲文化與科學特展」特展導覽  (2-3月場次)', '🦗鳴蟲文化與科學特展 導覽\n\n昆蟲常常出現在我們的生活中，可說是無所不在且到處可見，蟲鳴聲能讓人聽到就心有所感，人們為了能在室內聆賞於是開始捕捉、飼養、繁殖，形成特殊的鳴蟲文化和藝術；本特展聚焦於蟬、螽蟴與蟋蟀三類鳴蟲，透過專人導覽帶觀眾認識鳴蟲文化、鳴蟲生物學，希望藉由鳴蟲的保育喚醒觀眾共鳴。\n\n🦗導覽講師：本館教育推廣人員/本館志工\n\n🦗參加對象：一般大眾\n\n🦗報名方式：本館1樓服務台現場報名\n\n🦗費用：免費，需購票入館(全票30元、優待票15元)\n\n🦗時間：導覽時間原則約50分鐘，實際依現場為準\n\n🦗地點：本館1樓西展間\n\n \n\n 2月場次表 \n\n\n	\n		\n			日期\n			場次\n			備註\n		\n		\n			2/4(二)\n			10:30\n			 \n		\n		\n			2/11(二)\n			10:30\n			 \n		\n		\n			2/12(三)\n			10:30、14:30\n			 \n		\n		\n			2/18(二)\n			10:30\n			 \n		\n		\n			2/19(三)\n			10:30\n			 \n		\n		\n			2/22(六)\n			10:30\n			 \n		\n		\n			2/25(二)\n			10:30\n			 \n		\n	\n\n\n \n\n 3月場次表 \n\n\n	\n		\n			日期\n			場次\n			備註\n		\n		\n			3/4(二)\n			10:30\n			 \n		\n		\n			3/5(三)\n			10:30\n			 \n		\n		\n			3/18(二)\n			10:30\n			 \n		\n		\n			3/25(二)\n			10:30\n			 \n		\n	\n\n\n(📢如遇臨時更動，以現場公告為準)\n\n \n\n ', '國立臺灣博物館', '100  臺北市中正區中正區襄陽路2號(二二八公園內)', '2024-11-24 00:00:00', '2025-05-11 00:00:00', '臺博館本館1樓 西展間', 25.0418254, 121.5149875, '無資料', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40278', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「鳴蟲文化與科學特展」特展導覽  (2-3月場次)', `description`='🦗鳴蟲文化與科學特展 導覽\n\n昆蟲常常出現在我們的生活中，可說是無所不在且到處可見，蟲鳴聲能讓人聽到就心有所感，人們為了能在室內聆賞於是開始捕捉、飼養、繁殖，形成特殊的鳴蟲文化和藝術；本特展聚焦於蟬、螽蟴與蟋蟀三類鳴蟲，透過專人導覽帶觀眾認識鳴蟲文化、鳴蟲生物學，希望藉由鳴蟲的保育喚醒觀眾共鳴。\n\n🦗導覽講師：本館教育推廣人員/本館志工\n\n🦗參加對象：一般大眾\n\n🦗報名方式：本館1樓服務台現場報名\n\n🦗費用：免費，需購票入館(全票30元、優待票15元)\n\n🦗時間：導覽時間原則約50分鐘，實際依現場為準\n\n🦗地點：本館1樓西展間\n\n \n\n 2月場次表 \n\n\n	\n		\n			日期\n			場次\n			備註\n		\n		\n			2/4(二)\n			10:30\n			 \n		\n		\n			2/11(二)\n			10:30\n			 \n		\n		\n			2/12(三)\n			10:30、14:30\n			 \n		\n		\n			2/18(二)\n			10:30\n			 \n		\n		\n			2/19(三)\n			10:30\n			 \n		\n		\n			2/22(六)\n			10:30\n			 \n		\n		\n			2/25(二)\n			10:30\n			 \n		\n	\n\n\n \n\n 3月場次表 \n\n\n	\n		\n			日期\n			場次\n			備註\n		\n		\n			3/4(二)\n			10:30\n			 \n		\n		\n			3/5(三)\n			10:30\n			 \n		\n		\n			3/18(二)\n			10:30\n			 \n		\n		\n			3/25(二)\n			10:30\n			 \n		\n	\n\n\n(📢如遇臨時更動，以現場公告為準)\n\n \n\n ', `organizer`='國立臺灣博物館', `address`='100  臺北市中正區中正區襄陽路2號(二二八公園內)', `start_date`='2024-11-24 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='臺博館本館1樓 西展間', `latitude`=25.0418254, `longitude`=121.5149875, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40278', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67463c0b26b324689882a24c', '走揣・咱的所在－陳澄波百三特展', '2025年適逢臺灣前輩畫家陳澄波先生誕辰130週年紀念，陳澄波文化基金會將與國立臺灣博物館共同策展，從早期知識份子／藝術家的視野下與本館作為博物學關懷的對話下，呈現臺灣差異、多樣性的人文與自然發展，匯集而成今日島嶼之貌，而所擁有的幸福滋味。\n\n\n本特展將展出陳澄波畫作原件（共8件原件），搭配友達擬真藝屏製作微動畫，以及本館自然史典藏及新採集的標本。從陳澄波的作品如〈北回歸線地標〉、〈農家〉、〈東台灣臨海道路〉、〈濤聲〉、〈玉山積雪〉等油畫畫作破題，結合本館及新採集的魚類、植物等標本，討論與臺灣相遇而影響臺灣的自然現象，如洋流（黑潮）、季風（西南氣流、霧林帶）、氣候區（北回歸線、亞熱帶）等的獨特性，以及這些自然現象和所造成的物種高歧異性，交織而成 北半球生態系的縮影，進而孕育出豐富的文化多樣性，包含漁業發展及經濟交換等，闡述這塊土地上因這些現象的匯集而擁有的一切。\n\n透過陳澄波的畫作與自然史典藏，讓我們與陳澄波和博物學家一起探索臺灣島嶼自然力，走揣幸福快樂之所在。\n\n ', '國立臺灣博物館', '大同區延平北路一段2號', '2024-12-03 00:00:00', '2025-05-11 00:00:00', '臺博館鐵道部園區特展區', 25.0486841, 121.5112965, '全票：每張100元｜半票：每張50元', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40279', '[]') ON DUPLICATE KEY UPDATE `activity_name`='走揣・咱的所在－陳澄波百三特展', `description`='2025年適逢臺灣前輩畫家陳澄波先生誕辰130週年紀念，陳澄波文化基金會將與國立臺灣博物館共同策展，從早期知識份子／藝術家的視野下與本館作為博物學關懷的對話下，呈現臺灣差異、多樣性的人文與自然發展，匯集而成今日島嶼之貌，而所擁有的幸福滋味。\n\n\n本特展將展出陳澄波畫作原件（共8件原件），搭配友達擬真藝屏製作微動畫，以及本館自然史典藏及新採集的標本。從陳澄波的作品如〈北回歸線地標〉、〈農家〉、〈東台灣臨海道路〉、〈濤聲〉、〈玉山積雪〉等油畫畫作破題，結合本館及新採集的魚類、植物等標本，討論與臺灣相遇而影響臺灣的自然現象，如洋流（黑潮）、季風（西南氣流、霧林帶）、氣候區（北回歸線、亞熱帶）等的獨特性，以及這些自然現象和所造成的物種高歧異性，交織而成 北半球生態系的縮影，進而孕育出豐富的文化多樣性，包含漁業發展及經濟交換等，闡述這塊土地上因這些現象的匯集而擁有的一切。\n\n透過陳澄波的畫作與自然史典藏，讓我們與陳澄波和博物學家一起探索臺灣島嶼自然力，走揣幸福快樂之所在。\n\n ', `organizer`='國立臺灣博物館', `address`='大同區延平北路一段2號', `start_date`='2024-12-03 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='臺博館鐵道部園區特展區', `latitude`=25.0486841, `longitude`=121.5112965, `ticket_price`='全票：每張100元｜半票：每張50元', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40279', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67463cee26b324689882a2ae', 'Kacacefelisan 交會：阿美陶文化特展', '本次展覽以花蓮縣壽豐鄉豐田地區的臺灣閃玉礦產業為焦點，重現民國50年代的產業盛況。展覽將透過動態影像、聲音營造、學習體驗等多種展示教育資源，讓觀眾能夠身臨其境地感受當時閃玉礦業帶動臺灣玉產業的各個階段，從開礦、加工到銷售的全貌。此外，展覽還將展示豐富的文獻、照片、物件等資料，讓觀者對這段歷史產生深刻的情感連結。展覽籌備過程中，考古博物館積極與在地居民合作，反映他們探索、蒐整及解釋自己歷史的需求，真正體現了社區博物館的精神。\r\n值得一提的是，展覽場地本身就是一座饒富歷史意義的建築，現今的花蓮縣考古博物館二館前身是豐田村移民指導所事務室，其建築物可追溯至日治時期，原為移民村行政中心。戰後，這座建築又曾作為國語教學民教班和豐裡國小輔導教室使用，它見證了豐田地區村落發展的各個階段，凝聚了不同時代住民的生活記憶，選擇這樣一個富有歷史底蘊的場地舉辦臺灣玉產業歷史特展，更增添了展覽的深度和意義。', '花蓮縣文化局', '花蓮縣壽豐鄉', '2025-01-01 00:00:00', '2025-06-29 00:00:00', '壽豐鄉（花蓮縣）=', 23.84459714, 121.5341569, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Kacacefelisan 交會：阿美陶文化特展', `description`='本次展覽以花蓮縣壽豐鄉豐田地區的臺灣閃玉礦產業為焦點，重現民國50年代的產業盛況。展覽將透過動態影像、聲音營造、學習體驗等多種展示教育資源，讓觀眾能夠身臨其境地感受當時閃玉礦業帶動臺灣玉產業的各個階段，從開礦、加工到銷售的全貌。此外，展覽還將展示豐富的文獻、照片、物件等資料，讓觀者對這段歷史產生深刻的情感連結。展覽籌備過程中，考古博物館積極與在地居民合作，反映他們探索、蒐整及解釋自己歷史的需求，真正體現了社區博物館的精神。\r\n值得一提的是，展覽場地本身就是一座饒富歷史意義的建築，現今的花蓮縣考古博物館二館前身是豐田村移民指導所事務室，其建築物可追溯至日治時期，原為移民村行政中心。戰後，這座建築又曾作為國語教學民教班和豐裡國小輔導教室使用，它見證了豐田地區村落發展的各個階段，凝聚了不同時代住民的生活記憶，選擇這樣一個富有歷史底蘊的場地舉辦臺灣玉產業歷史特展，更增添了展覽的深度和意義。', `organizer`='花蓮縣文化局', `address`='花蓮縣壽豐鄉', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='壽豐鄉（花蓮縣）=', `latitude`=23.84459714, `longitude`=121.5341569, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67463cee26b324689882a2b1', '石綿山下的玉礦軌跡—臺灣玉近代產業歷史特展', '本次展覽以花蓮縣壽豐鄉豐田地區的臺灣閃玉礦產業為焦點，重現民國50年代的產業盛況。展覽將透過動態影像、聲音營造、學習體驗等多種展示教育資源，讓觀眾能夠身臨其境地感受當時閃玉礦業帶動臺灣玉產業的各個階段，從開礦、加工到銷售的全貌。此外，展覽還將展示豐富的文獻、照片、物件等資料，讓觀者對這段歷史產生深刻的情感連結。展覽籌備過程中，考古博物館積極與在地居民合作，反映他們探索、蒐整及解釋自己歷史的需求，真正體現了社區博物館的精神。\r\n值得一提的是，展覽場地本身就是一座饒富歷史意義的建築，現今的花蓮縣考古博物館二館前身是豐田村移民指導所事務室，其建築物可追溯至日治時期，原為移民村行政中心。戰後，這座建築又曾作為國語教學民教班和豐裡國小輔導教室使用，它見證了豐田地區村落發展的各個階段，凝聚了不同時代住民的生活記憶，選擇這樣一個富有歷史底蘊的場地舉辦臺灣玉產業歷史特展，更增添了展覽的深度和意義。', '花蓮縣文化局', '花蓮縣壽豐鄉', '2025-01-01 00:00:00', '2025-06-29 00:00:00', '壽豐鄉（花蓮縣）=', 23.84459714, 121.5341569, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='石綿山下的玉礦軌跡—臺灣玉近代產業歷史特展', `description`='本次展覽以花蓮縣壽豐鄉豐田地區的臺灣閃玉礦產業為焦點，重現民國50年代的產業盛況。展覽將透過動態影像、聲音營造、學習體驗等多種展示教育資源，讓觀眾能夠身臨其境地感受當時閃玉礦業帶動臺灣玉產業的各個階段，從開礦、加工到銷售的全貌。此外，展覽還將展示豐富的文獻、照片、物件等資料，讓觀者對這段歷史產生深刻的情感連結。展覽籌備過程中，考古博物館積極與在地居民合作，反映他們探索、蒐整及解釋自己歷史的需求，真正體現了社區博物館的精神。\r\n值得一提的是，展覽場地本身就是一座饒富歷史意義的建築，現今的花蓮縣考古博物館二館前身是豐田村移民指導所事務室，其建築物可追溯至日治時期，原為移民村行政中心。戰後，這座建築又曾作為國語教學民教班和豐裡國小輔導教室使用，它見證了豐田地區村落發展的各個階段，凝聚了不同時代住民的生活記憶，選擇這樣一個富有歷史底蘊的場地舉辦臺灣玉產業歷史特展，更增添了展覽的深度和意義。', `organizer`='花蓮縣文化局', `address`='花蓮縣壽豐鄉', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='壽豐鄉（花蓮縣）=', `latitude`=23.84459714, `longitude`=121.5341569, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67463cef26b324689882a2c1', '竹藝博物館2024竹藝產品開發競賽得獎作品展', '南投縣政府文化局所舉辦之竹藝產品開發競賽是每年度的盛事，匯聚來自全國各地竹藝創作者的心血結晶，經由評審從創作技法、創意特色、整體美學、經濟效益等4大面向進行縝密的綜合評比，進而評選出首獎、優選、佳作及入選等各類獎項。透過該競賽之舉辦，期能發揚竹藝現代美學及生活藝術化價值，將傳統竹藝技法賦予現代創意設計元素，吸引更多人才投注研發創新，激盪竹藝產業永續發展。\r\n本年度參賽作品共計87件，由文化局聘請竹藝、設計學界專家及優秀創作者共同評選，評審結果：首獎1名由陳盈池先生作品「允竹方寸之境」榮獲，優選2名由陳淑媛小姐作品「和韻」、石素鈴小姐作品「迴」獲得，佳作3名由李文忠先生作品「方形茶籠」、張國清、吳文亮、賴志廣先生共同創作作品「行之包」、張棋綾小姐作品「星羅棋布」分別獲選，其他入選作品共計57件。', '南投縣政府文化局', '南投縣南投市建國路135號', '2025-01-02 00:00:00', '2025-04-29 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='竹藝博物館2024竹藝產品開發競賽得獎作品展', `description`='南投縣政府文化局所舉辦之竹藝產品開發競賽是每年度的盛事，匯聚來自全國各地竹藝創作者的心血結晶，經由評審從創作技法、創意特色、整體美學、經濟效益等4大面向進行縝密的綜合評比，進而評選出首獎、優選、佳作及入選等各類獎項。透過該競賽之舉辦，期能發揚竹藝現代美學及生活藝術化價值，將傳統竹藝技法賦予現代創意設計元素，吸引更多人才投注研發創新，激盪竹藝產業永續發展。\r\n本年度參賽作品共計87件，由文化局聘請竹藝、設計學界專家及優秀創作者共同評選，評審結果：首獎1名由陳盈池先生作品「允竹方寸之境」榮獲，優選2名由陳淑媛小姐作品「和韻」、石素鈴小姐作品「迴」獲得，佳作3名由李文忠先生作品「方形茶籠」、張國清、吳文亮、賴志廣先生共同創作作品「行之包」、張棋綾小姐作品「星羅棋布」分別獲選，其他入選作品共計57件。', `organizer`='南投縣政府文化局', `address`='南投縣南投市建國路135號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67478da326b324689882a2dd', '《金剛經．諸相非相》', '《金剛經》是大乘佛教般若部經典之一，被尊為經中之王，讀此經者，從中體悟生命真諦。2024年，台灣在疫情、地震、颱風的重重考驗後，我們特別邀請蔣勳老師、藝術家曾永玲和董承濂，以《金剛經．諸相非相》為題，在天地大美的池上，嘗試將《金剛經》的要義幻化為形，呈現在穀倉中。\r\n\r\n對信眾而言，《金剛經》是信仰與修行，但是，蔣勳老師說，《金剛經》是一部口傳的筆記，是思想，也是哲學。數千年來，字裡行間，每個人自有參悟。《金剛經．諸相非相》跨域聯展，展出蔣勳恭敬虔誠的手抄經文與繪畫、曾永玲千錘百煉的金工演繹、董承濂虛實相應的多媒體裝置作品，以及國立故宮博物院及國家圖書館提供的經典復刻本，見證信仰帶動印刷發展的經典文獻。《金剛經．諸相非相》既分享藝術家探尋本心的過程及對生命的感知，也為眾生祈福，回到初衷，身心安頓。\r\n\r\n此外，《金剛經．諸相非相》跨域聯展也獲得蔣勳文化基金會與和通藝術文化基金會響應，在池上蔣勳書房及和通蔣勳書房策畫《金剛經．夢幻泡影》和《金剛經．應無所住》，跨越中央山脈，聆聽、靜思與冥想。\r\n\r\n誠摯地邀請您來到池上，在穀倉，體驗一場平靜自在的生命追尋。', '財團法人臺灣好文化基金會', '臺東縣池上鄉中西三路6號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '池上穀倉藝術館', 23.09248714, 121.2184501, '優惠票+20;全票+50', 'https://artchishang.lovelytaiwan.org.tw/barn/exhibitions/34112c', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《金剛經．諸相非相》', `description`='《金剛經》是大乘佛教般若部經典之一，被尊為經中之王，讀此經者，從中體悟生命真諦。2024年，台灣在疫情、地震、颱風的重重考驗後，我們特別邀請蔣勳老師、藝術家曾永玲和董承濂，以《金剛經．諸相非相》為題，在天地大美的池上，嘗試將《金剛經》的要義幻化為形，呈現在穀倉中。\r\n\r\n對信眾而言，《金剛經》是信仰與修行，但是，蔣勳老師說，《金剛經》是一部口傳的筆記，是思想，也是哲學。數千年來，字裡行間，每個人自有參悟。《金剛經．諸相非相》跨域聯展，展出蔣勳恭敬虔誠的手抄經文與繪畫、曾永玲千錘百煉的金工演繹、董承濂虛實相應的多媒體裝置作品，以及國立故宮博物院及國家圖書館提供的經典復刻本，見證信仰帶動印刷發展的經典文獻。《金剛經．諸相非相》既分享藝術家探尋本心的過程及對生命的感知，也為眾生祈福，回到初衷，身心安頓。\r\n\r\n此外，《金剛經．諸相非相》跨域聯展也獲得蔣勳文化基金會與和通藝術文化基金會響應，在池上蔣勳書房及和通蔣勳書房策畫《金剛經．夢幻泡影》和《金剛經．應無所住》，跨越中央山脈，聆聽、靜思與冥想。\r\n\r\n誠摯地邀請您來到池上，在穀倉，體驗一場平靜自在的生命追尋。', `organizer`='財團法人臺灣好文化基金會', `address`='臺東縣池上鄉中西三路6號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='池上穀倉藝術館', `latitude`=23.09248714, `longitude`=121.2184501, `ticket_price`='優惠票+20;全票+50', `source_url`='https://artchishang.lovelytaiwan.org.tw/barn/exhibitions/34112c', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67478de926b324689882a308', '臺中市藝術亮點-《愣筆墨暈》劉惠明書法個展', '展出藝術家劉惠明臨寫各家書體、嘗試多元筆法的書法作品，表達對傳統書法的熱愛，更透過書法充實退休生活，追求更踏實的每一天。', '正太筆墨坊', '臺中市豐原區成功路369號', '2025-01-01 00:00:00', '2025-02-27 00:00:00', '正太筆墨坊', 24.24990298, 120.7375715, '無資料', 'https://www.artspots-taichung.com.tw/tw/news-detail/296?root=8', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-《愣筆墨暈》劉惠明書法個展', `description`='展出藝術家劉惠明臨寫各家書體、嘗試多元筆法的書法作品，表達對傳統書法的熱愛，更透過書法充實退休生活，追求更踏實的每一天。', `organizer`='正太筆墨坊', `address`='臺中市豐原區成功路369號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='正太筆墨坊', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.artspots-taichung.com.tw/tw/news-detail/296?root=8', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6748c5fc26b324689882a398', '無資料', '狂美《讓我們從白雪公主開始》交響音樂會\r\n樂音與童話交織，交響音樂會炫目登場\r\n樂音與童話交織的詩篇\r\n一切源起 都從那顆被咬一口的毒蘋果開始 …\r\n翻開手上厚厚的精裝書，銀白色華麗城堡躍然紙上！\r\n好多故事的開端都是這樣。\r\n\r\n忙著工作的小矮人們在森林中列隊吹起了口哨、閃耀長髮的公主睜大眼睛，嚮往高塔外的老鷹翱翔。\r\n有的呢⋯則在遙遠的雪國看著麋鹿與雪人興奮的互打雪仗！\r\n對了，千萬別忘了午夜12點大鐘響！\r\n南瓜馬車在路上奔馳找尋灰姑娘。\r\n\r\n狂美樂隊裡的樂手們，奏響一首首童話主題曲的悠揚\r\n公主與王子們，穿上禮服在舞台上高唱愛與夢想\r\n當然，那位在現場說故事的領航者一樣重要。 　\r\n\r\n序章，翻開 Ep. 1 \r\n「讓我們從白雪公主開始」步步走進狂美的綺麗樂章\r\n\r\n【全場次演出曲目】\r\n《白雪公主》 Whistle While You Work\r\n《魔髮奇緣》 "Tangled" Medley\r\n《仙履奇緣》 Cinderella\r\n《海洋奇緣》 Selections from "Moana"\r\n《鐘樓怪人》 The Bells of Notre Dame\r\n《獅子王》 "The Lion King" Medley\r\n《魔法滿屋》 Symphonic Highlights from "ENCANTO"', '狂美交響管樂團', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='狂美《讓我們從白雪公主開始》交響音樂會\r\n樂音與童話交織，交響音樂會炫目登場\r\n樂音與童話交織的詩篇\r\n一切源起 都從那顆被咬一口的毒蘋果開始 …\r\n翻開手上厚厚的精裝書，銀白色華麗城堡躍然紙上！\r\n好多故事的開端都是這樣。\r\n\r\n忙著工作的小矮人們在森林中列隊吹起了口哨、閃耀長髮的公主睜大眼睛，嚮往高塔外的老鷹翱翔。\r\n有的呢⋯則在遙遠的雪國看著麋鹿與雪人興奮的互打雪仗！\r\n對了，千萬別忘了午夜12點大鐘響！\r\n南瓜馬車在路上奔馳找尋灰姑娘。\r\n\r\n狂美樂隊裡的樂手們，奏響一首首童話主題曲的悠揚\r\n公主與王子們，穿上禮服在舞台上高唱愛與夢想\r\n當然，那位在現場說故事的領航者一樣重要。 　\r\n\r\n序章，翻開 Ep. 1 \r\n「讓我們從白雪公主開始」步步走進狂美的綺麗樂章\r\n\r\n【全場次演出曲目】\r\n《白雪公主》 Whistle While You Work\r\n《魔髮奇緣》 "Tangled" Medley\r\n《仙履奇緣》 Cinderella\r\n《海洋奇緣》 Selections from "Moana"\r\n《鐘樓怪人》 The Bells of Notre Dame\r\n《獅子王》 "The Lion King" Medley\r\n《魔法滿屋》 Symphonic Highlights from "ENCANTO"', `organizer`='狂美交響管樂團', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
