INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('674a168d26b324689882a43d', '2024年小地方計畫', '課程介紹：\r\n1.身體魔術師：透過戲劇遊戲的練習讓學生發展肢體更多的可能性；規劃內容有：指令123、走走停-身體變、空間創造、分享與討論。\r\n2.聲音變變變：藉由練習，去發現聲音情緒的運用；規劃內容有：森林大火、今天天氣真好、唱給你聽、繪本段落練習。\r\n3.跟著感覺走：啟發學生運用身體之外的感官來認識世界並且將自己的感覺的呈現出來；規劃內容有：走路暖身、聽聲音做動作、鏡子練習。\r\n4.想像力爆炸：藉由簡單的物件，激發想想力，進而創造；規劃內容有：分享作業、我們一起、紙捲想像力、分享討論。\r\n5.尋找與建立：透過與夥伴的合作，找到屬於自己的地圖；規劃內容有：夏邦暖身、聲音導盲、導盲探索、分享討論。\r\n6.音樂畫畫派對：聽各種不同風格的音樂，畫下音樂畫面；規劃內容有：暖身、聽音樂畫畫-團體畫＆個人畫、分享討論。\r\n7.雕像博物館：主題聯想，再透過身體創造呈現給觀眾欣賞；規劃內容有：攻城堡暖身、走走停顏色物品、雕像博物館導覽、分享討論。\r\n8.綜合呈現：期末帶領學生回顧且再創作；分為分組找尋適當地點-發想排練、觀賞各組呈現及分享。', '阮劇團', '嘉義縣全區域', '2025-01-15 00:00:00', '2025-05-15 00:00:00', '嘉義縣', 0, 0, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2024年小地方計畫', `description`='課程介紹：\r\n1.身體魔術師：透過戲劇遊戲的練習讓學生發展肢體更多的可能性；規劃內容有：指令123、走走停-身體變、空間創造、分享與討論。\r\n2.聲音變變變：藉由練習，去發現聲音情緒的運用；規劃內容有：森林大火、今天天氣真好、唱給你聽、繪本段落練習。\r\n3.跟著感覺走：啟發學生運用身體之外的感官來認識世界並且將自己的感覺的呈現出來；規劃內容有：走路暖身、聽聲音做動作、鏡子練習。\r\n4.想像力爆炸：藉由簡單的物件，激發想想力，進而創造；規劃內容有：分享作業、我們一起、紙捲想像力、分享討論。\r\n5.尋找與建立：透過與夥伴的合作，找到屬於自己的地圖；規劃內容有：夏邦暖身、聲音導盲、導盲探索、分享討論。\r\n6.音樂畫畫派對：聽各種不同風格的音樂，畫下音樂畫面；規劃內容有：暖身、聽音樂畫畫-團體畫＆個人畫、分享討論。\r\n7.雕像博物館：主題聯想，再透過身體創造呈現給觀眾欣賞；規劃內容有：攻城堡暖身、走走停顏色物品、雕像博物館導覽、分享討論。\r\n8.綜合呈現：期末帶領學生回顧且再創作；分為分組找尋適當地點-發想排練、觀賞各組呈現及分享。', `organizer`='阮劇團', `address`='嘉義縣全區域', `start_date`='2025-01-15 00:00:00', `end_date`='2025-05-15 00:00:00', `location`='嘉義縣', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('674a168d26b324689882a442', '彰化縣文化局114年春季藝文研習班（1～3月）', '活動簡介：\r\n招生對象：有興趣之民眾均可報名。\r\n報名方式：填寫報名表，現場、電話、傳真、網路均可報名，並於開課前繳清報名費。\r\n報名請洽：彰化縣立圖書館藝文研習班報名處，電話：（04）7250057分機2102、1852\r\n報名傳真：(04)7244982，如以傳真方式報名者，請於傳真後撥打電話施小姐確認，以保障您的權益！\r\n報名時間：即日期至開課前(額滿提前截止) \r\n上課地點：縣立圖書館研習教室  標示★為南北管音樂戲曲館  ▲大成故事館（詳細內容以開課為準）\r\n (一)如遇不可抗力之天災、颱風，以縣府公告停課，不另通知，原課程順延。\r\n(二)各班不足開課人數，由本局通知辦理全額退費或轉班，請持收據辦理。\r\n(三)費用需上課前繳清，報名後除因兵役召集不克參加，可於活動前申請退費外，其餘數不退費。\r\n(四)謝絕旁聽、視聽，一人報名，一人上課，請勿攜家帶眷。\r\n(五)收費：新班一律以新生收費。\r\n(六)可登錄公務人員終身學習時數。(請於上課時將身分證字號交給研習班承辦員，以方便為您登錄公務人員終身學習時數不另通知)\r\n', '彰化縣文化局', '彰化縣彰化市中山路2段500號', '2025-01-02 00:00:00', '2025-04-11 00:00:00', '彰化縣立圖書館', 24.07532909, 120.5694208, '報名費+750;報名費+1500', 'https://www.bocach.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彰化縣文化局114年春季藝文研習班（1～3月）', `description`='活動簡介：\r\n招生對象：有興趣之民眾均可報名。\r\n報名方式：填寫報名表，現場、電話、傳真、網路均可報名，並於開課前繳清報名費。\r\n報名請洽：彰化縣立圖書館藝文研習班報名處，電話：（04）7250057分機2102、1852\r\n報名傳真：(04)7244982，如以傳真方式報名者，請於傳真後撥打電話施小姐確認，以保障您的權益！\r\n報名時間：即日期至開課前(額滿提前截止) \r\n上課地點：縣立圖書館研習教室  標示★為南北管音樂戲曲館  ▲大成故事館（詳細內容以開課為準）\r\n (一)如遇不可抗力之天災、颱風，以縣府公告停課，不另通知，原課程順延。\r\n(二)各班不足開課人數，由本局通知辦理全額退費或轉班，請持收據辦理。\r\n(三)費用需上課前繳清，報名後除因兵役召集不克參加，可於活動前申請退費外，其餘數不退費。\r\n(四)謝絕旁聽、視聽，一人報名，一人上課，請勿攜家帶眷。\r\n(五)收費：新班一律以新生收費。\r\n(六)可登錄公務人員終身學習時數。(請於上課時將身分證字號交給研習班承辦員，以方便為您登錄公務人員終身學習時數不另通知)\r\n', `organizer`='彰化縣文化局', `address`='彰化縣彰化市中山路2段500號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-04-11 00:00:00', `location`='彰化縣立圖書館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='報名費+750;報名費+1500', `source_url`='https://www.bocach.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('674a168e26b324689882a455', '譯．介．人生──林水福文學展', '此展覽為林教授翻譯生涯的縮影，呈現他如何透過翻譯成為中日文化對話的橋樑。他精確而細膩地保留作品的文化細節，促進兩國文學理解與交流，從《源氏物語》至村上春樹，跨越古今，深化文學價值，激發讀者探索異文化精髓，推動臺日文壇對話共鳴，豐富台灣文學視野。', '南投縣政府文化局', '南投縣南投市中興路669號', '2025-01-02 00:00:00', '2025-03-23 00:00:00', '南投縣政府文化局圖書館', 23.9027891, 120.691332, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='譯．介．人生──林水福文學展', `description`='此展覽為林教授翻譯生涯的縮影，呈現他如何透過翻譯成為中日文化對話的橋樑。他精確而細膩地保留作品的文化細節，促進兩國文學理解與交流，從《源氏物語》至村上春樹，跨越古今，深化文學價值，激發讀者探索異文化精髓，推動臺日文壇對話共鳴，豐富台灣文學視野。', `organizer`='南投縣政府文化局', `address`='南投縣南投市中興路669號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='南投縣政府文化局圖書館', `latitude`=23.9027891, `longitude`=120.691332, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('674b7ed326b324689882a47a', '光影巴洛克藝術展', '「廣達游於藝光影巴洛克藝術展」，以三大主題呈現巴洛克時期藝術的光影魅力，從展示17世紀歐洲宗教改革與科學革命的「舊交替的關鍵年代」，到探索巴洛克五位大師的光影技法「光影魔術師」，再到強調光影神奇力量的「光影魔力」，讓觀眾身臨其境感受情感張力。', '財團法人廣達文教基金會', '嘉義縣全區域', '2025-02-06 00:00:00', '2025-02-26 00:00:00', '嘉義縣', '無資料', '無資料', '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='光影巴洛克藝術展', `description`='「廣達游於藝光影巴洛克藝術展」，以三大主題呈現巴洛克時期藝術的光影魅力，從展示17世紀歐洲宗教改革與科學革命的「舊交替的關鍵年代」，到探索巴洛克五位大師的光影技法「光影魔術師」，再到強調光影神奇力量的「光影魔力」，讓觀眾身臨其境感受情感張力。', `organizer`='財團法人廣達文教基金會', `address`='嘉義縣全區域', `start_date`='2025-02-06 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='嘉義縣', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
