INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6750c36726b324689882a55e', '故事．集：說說典藏', '本展以「故事．集：說說典藏」為題，粹選本館典藏藝術家經典作品，集結藝術家創作思路、美術館蒐藏記事、藝研者導讀賞析，並行展閱經典於字裡行間。展覽期以作品故事的親善導賞，帶領觀眾由不同的觀看角度，多重感知本館重要典藏；透過閱讀故事而悅讀作品，促動觀眾走進典藏、走近藝術，共享藝術薈萃與典藏聚珍的甜實纍果。', '高雄市立美術館', '高雄市鼓山區6鄰美術館路80號', '2025-01-01 00:00:00', '2025-06-15 00:00:00', '高雄市立美術館', 22.6566968, 120.2865511, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='故事．集：說說典藏', `description`='本展以「故事．集：說說典藏」為題，粹選本館典藏藝術家經典作品，集結藝術家創作思路、美術館蒐藏記事、藝研者導讀賞析，並行展閱經典於字裡行間。展覽期以作品故事的親善導賞，帶領觀眾由不同的觀看角度，多重感知本館重要典藏；透過閱讀故事而悅讀作品，促動觀眾走進典藏、走近藝術，共享藝術薈萃與典藏聚珍的甜實纍果。', `organizer`='高雄市立美術館', `address`='高雄市鼓山區6鄰美術館路80號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='高雄市立美術館', `latitude`=22.6566968, `longitude`=120.2865511, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6750c36726b324689882a560', '潮壤相接 ', '展覽以「誰擁有土地與海洋？」這一核心問題為出發點，透過藝術家的作品，反映出自然資源所有權所引發的思索：包含水土破壞、族群衝突、文化傳承與環境保護等議題。這些作品不僅記錄了人與自然之間的各種互動關係，還展現了原住民在保護生態與文化傳統中的實踐，也以藝術家的視角，對當代資本主義與政治衝突提出探問。', '高雄市立美術館', '高雄市鼓山區6鄰美術館路80號', '2025-01-01 00:00:00', '2025-04-20 00:00:00', '高雄市立美術館', 22.6566968, 120.2865511, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='潮壤相接 ', `description`='展覽以「誰擁有土地與海洋？」這一核心問題為出發點，透過藝術家的作品，反映出自然資源所有權所引發的思索：包含水土破壞、族群衝突、文化傳承與環境保護等議題。這些作品不僅記錄了人與自然之間的各種互動關係，還展現了原住民在保護生態與文化傳統中的實踐，也以藝術家的視角，對當代資本主義與政治衝突提出探問。', `organizer`='高雄市立美術館', `address`='高雄市鼓山區6鄰美術館路80號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='高雄市立美術館', `latitude`=22.6566968, `longitude`=120.2865511, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6750c36926b324689882a588', '高雄市成功大學校友會春永雅集乙巳書法展 -- 翰墨傳薪', '高雄市國立成功大學校友會書法社是一群愛好書法藝術的校友們於民國102年成立。由書法名家郭春甫先生授課指導。本社亦曾於民國106年5月及110年9月於文化中心至高館舉辦2次聯展。社友們再經過數年的努力，雖然仍不盡理想，但也各體均備，期能拋磚引玉，對書法藝術傳承盡點棉薄之力。', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-02-14 00:00:00', '2025-02-25 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4064', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市成功大學校友會春永雅集乙巳書法展 -- 翰墨傳薪', `description`='高雄市國立成功大學校友會書法社是一群愛好書法藝術的校友們於民國102年成立。由書法名家郭春甫先生授課指導。本社亦曾於民國106年5月及110年9月於文化中心至高館舉辦2次聯展。社友們再經過數年的努力，雖然仍不盡理想，但也各體均備，期能拋磚引玉，對書法藝術傳承盡點棉薄之力。', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-02-14 00:00:00', `end_date`='2025-02-25 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4064', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6750c36926b324689882a58d', '三義木雕博物館常設展', '常設展區介紹：\r\n一館一樓／森林區、南島民族木雕、從面具看世界文化、木雕薪傳創作營特展區。\r\n一館二樓／三義木雕源流、木雕原木裁切、得獎暨典藏作品區、建築家具區、印模區及木雕工具區。\r\n二館二樓／寺廟神像。\r\n洽詢電話：三義木雕博物館 037-876009 \r\n', '苗栗縣政府', '苗栗縣三義鄉廣聲新城88號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '三義木雕博物館', 24.4059218, 120.7611814, '團體票（學生）+40;本局策略聯盟+40;學生票+50;優待票+50;團體票+70;全票+80', 'http://wood.mlc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三義木雕博物館常設展', `description`='常設展區介紹：\r\n一館一樓／森林區、南島民族木雕、從面具看世界文化、木雕薪傳創作營特展區。\r\n一館二樓／三義木雕源流、木雕原木裁切、得獎暨典藏作品區、建築家具區、印模區及木雕工具區。\r\n二館二樓／寺廟神像。\r\n洽詢電話：三義木雕博物館 037-876009 \r\n', `organizer`='苗栗縣政府', `address`='苗栗縣三義鄉廣聲新城88號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='三義木雕博物館', `latitude`=24.4059218, `longitude`=120.7611814, `ticket_price`='團體票（學生）+40;本局策略聯盟+40;學生票+50;優待票+50;團體票+70;全票+80', `source_url`='http://wood.mlc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6750c36a26b324689882a594', '傳承與創新-高雄市南海書畫學會50週年會員聯展', '本會成立於民國64年名：南海藝苑，由海軍資深書畫家-沈新吾籌組創立，以發揚中國傳統藝術、聯誼情感為宗旨。參加成員多為海軍退、現役軍官及眷屬所組成，每月舉辦雅集現場揮毫、作品交流、專題演講…等。\r\n民國78年人民團體法立案，更名為高雄市南海書畫學會。\r\n這幾年，經歷疫情殞落許多前輩，第10、11屆 李錦綿接任理事長，特別擴大招入新血，壯大南海，故此次展出命名 《傳承與創新》歡迎喜歡藝術的朋友，一起來見證南海的轉變。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-02-21 00:00:00', '2025-03-04 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4061', '[]') ON DUPLICATE KEY UPDATE `activity_name`='傳承與創新-高雄市南海書畫學會50週年會員聯展', `description`='本會成立於民國64年名：南海藝苑，由海軍資深書畫家-沈新吾籌組創立，以發揚中國傳統藝術、聯誼情感為宗旨。參加成員多為海軍退、現役軍官及眷屬所組成，每月舉辦雅集現場揮毫、作品交流、專題演講…等。\r\n民國78年人民團體法立案，更名為高雄市南海書畫學會。\r\n這幾年，經歷疫情殞落許多前輩，第10、11屆 李錦綿接任理事長，特別擴大招入新血，壯大南海，故此次展出命名 《傳承與創新》歡迎喜歡藝術的朋友，一起來見證南海的轉變。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-02-21 00:00:00', `end_date`='2025-03-04 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4061', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675213cc26b324689882a59c', '另一種現場：修澤蘭 特展', '修澤蘭於1949年進入臺灣鐵路局工作，曾規劃設計舊板橋車站等臺鐵相關建築，與鐵道部有著一定淵源。在國家建設時期投入全臺各地校園規劃與建築，是曾經克服陽明山硫磺地熱建造「中山樓」的建築師，也是在新店山林打造現代新社區「花園新城」的實業家。\n\n展覽以「初到．出道」、「獨樹一格的校園建築」、「大屯火山群中的傳奇建築」、「新店溪畔的理想家園」、「相遇．相惜」、「我與修澤蘭-集體記憶累積的現場」等六大單元，綜覽修澤蘭從求學、1949年到臺灣鐵路局工作設計舊板橋車站，結識具土木結構專長的同僚傅積寬，並成為相互扶持的伴侶，到共同創辦澤群建築師事務所，繼而完成後續各項校園建築，及完成陽明山「中山樓」、新店「花園新城」等代表建築。\n ', '國立臺灣博物館', '大同區延平北路一段2號', '2024-12-03 00:00:00', '2025-11-02 00:00:00', '臺博館鐵道部園區2樓特展區', 25.0486841, 121.5112965, '全票：每張100元｜半票：每張50元', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40282', '[]') ON DUPLICATE KEY UPDATE `activity_name`='另一種現場：修澤蘭 特展', `description`='修澤蘭於1949年進入臺灣鐵路局工作，曾規劃設計舊板橋車站等臺鐵相關建築，與鐵道部有著一定淵源。在國家建設時期投入全臺各地校園規劃與建築，是曾經克服陽明山硫磺地熱建造「中山樓」的建築師，也是在新店山林打造現代新社區「花園新城」的實業家。\n\n展覽以「初到．出道」、「獨樹一格的校園建築」、「大屯火山群中的傳奇建築」、「新店溪畔的理想家園」、「相遇．相惜」、「我與修澤蘭-集體記憶累積的現場」等六大單元，綜覽修澤蘭從求學、1949年到臺灣鐵路局工作設計舊板橋車站，結識具土木結構專長的同僚傅積寬，並成為相互扶持的伴侶，到共同創辦澤群建築師事務所，繼而完成後續各項校園建築，及完成陽明山「中山樓」、新店「花園新城」等代表建築。\n ', `organizer`='國立臺灣博物館', `address`='大同區延平北路一段2號', `start_date`='2024-12-03 00:00:00', `end_date`='2025-11-02 00:00:00', `location`='臺博館鐵道部園區2樓特展區', `latitude`=25.0486841, `longitude`=121.5112965, `ticket_price`='全票：每張100元｜半票：每張50元', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40282', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6752147d26b324689882a5c5', '蛤?蛇麼意思-生肖郵票特展', '民國114年歲次乙巳，生肖屬蛇。為迎接新年來臨，郵政博物館特舉辦「蛤?蛇麼意思-生肖郵票特展」，展出與蛇主題相關之郵票36套、介紹在東、西方各地蛇的神話故事、蛇類生態知識及播放保育影片，並設有彩繪海蛇互動體驗區與「春暖花開．蛇行天下」大型紙雕裝置。歡迎蒞臨參觀。', '郵政博物館', '臺北市中正區重慶南路2段45號', '2025-01-01 00:00:00', '2025-04-06 00:00:00', '郵政博物館', 25.03240487, 121.5198839, '無資料', 'https://museum.post.gov.tw/post/Postal_Museum/museum/index.jsp?ID=1525402201649&control_type=page&ne', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蛤?蛇麼意思-生肖郵票特展', `description`='民國114年歲次乙巳，生肖屬蛇。為迎接新年來臨，郵政博物館特舉辦「蛤?蛇麼意思-生肖郵票特展」，展出與蛇主題相關之郵票36套、介紹在東、西方各地蛇的神話故事、蛇類生態知識及播放保育影片，並設有彩繪海蛇互動體驗區與「春暖花開．蛇行天下」大型紙雕裝置。歡迎蒞臨參觀。', `organizer`='郵政博物館', `address`='臺北市中正區重慶南路2段45號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='郵政博物館', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://museum.post.gov.tw/post/Postal_Museum/museum/index.jsp?ID=1525402201649&control_type=page&ne', `image_url`='[]';
