INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6753641226b324689882a621', '與動物共享大自然 (2024/12/24-2025/03/02)', '雜木從大樹誕生出來，經由大地滋養又遭遇戲劇性變化，從深山經過一路的漂流，最後回到人類的手中，藝術家張弘欣利用漂流木的自然曲線、紋路反應在作品上，每一件成品都充滿有趣的故事，不僅讓木頭中的籃碳保留起來，也變成一件漂亮的藝術品，更讓環保理念能深植人心。\n\n \n\n藝術家簡歷-\n\n南投竹山非科班出身的張弘欣，利用空閒時間，把年幼家住濁水溪畔的撿漂流木經驗，結合長大後學習的木藝技巧，尋找特殊造型漂流木，一點一點拼接成犀牛、土狗、鴕鳥、長頸鹿、馬、公雞、鵜鶘，甚至有電影「星際異攻隊」的「格魯特」。張弘欣自2019年開始啟動斜槓人生，每年參與竹山燈會盛會，並多次參加竹山篁山藝術會南投文化局聯展、三義木雕博物館采風聯展，並於2021年獲邀臺灣設計週臺灣木雕藝師薪傳邀請展、2022年獲南投文化局玉山獎入選。\n\n   \n\n展覽資訊>\n\n展覽名稱：與動物共享大自然\n\n時間: 2024/12/24(二)-2025/03/02(日) 9:00~17:00(週一公休)\n\n地點: 國立新竹生活美學館 廣場（300新竹市武昌街110號）\n\n ', '國立新竹生活美學館', '300  新竹市武昌街110號', '2024-12-24 00:00:00', '2025-03-02 00:00:00', '國立新竹生活美學館-廣場', 24.8031317, 120.9671479, '0', 'https://event.culture.tw/mocweb/reg/NHCLAC/Detail.init.ctr?actId=40074', '[]') ON DUPLICATE KEY UPDATE `activity_name`='與動物共享大自然 (2024/12/24-2025/03/02)', `description`='雜木從大樹誕生出來，經由大地滋養又遭遇戲劇性變化，從深山經過一路的漂流，最後回到人類的手中，藝術家張弘欣利用漂流木的自然曲線、紋路反應在作品上，每一件成品都充滿有趣的故事，不僅讓木頭中的籃碳保留起來，也變成一件漂亮的藝術品，更讓環保理念能深植人心。\n\n \n\n藝術家簡歷-\n\n南投竹山非科班出身的張弘欣，利用空閒時間，把年幼家住濁水溪畔的撿漂流木經驗，結合長大後學習的木藝技巧，尋找特殊造型漂流木，一點一點拼接成犀牛、土狗、鴕鳥、長頸鹿、馬、公雞、鵜鶘，甚至有電影「星際異攻隊」的「格魯特」。張弘欣自2019年開始啟動斜槓人生，每年參與竹山燈會盛會，並多次參加竹山篁山藝術會南投文化局聯展、三義木雕博物館采風聯展，並於2021年獲邀臺灣設計週臺灣木雕藝師薪傳邀請展、2022年獲南投文化局玉山獎入選。\n\n   \n\n展覽資訊>\n\n展覽名稱：與動物共享大自然\n\n時間: 2024/12/24(二)-2025/03/02(日) 9:00~17:00(週一公休)\n\n地點: 國立新竹生活美學館 廣場（300新竹市武昌街110號）\n\n ', `organizer`='國立新竹生活美學館', `address`='300  新竹市武昌街110號', `start_date`='2024-12-24 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='國立新竹生活美學館-廣場', `latitude`=24.8031317, `longitude`=120.9671479, `ticket_price`='0', `source_url`='https://event.culture.tw/mocweb/reg/NHCLAC/Detail.init.ctr?actId=40074', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364c626b324689882a666', '無資料', '大雋藝術誠摯呈獻《In Between: Ephemeral Beauty轉瞬之美》—— Cathy Tabbakh與Angela Witmore雙人聯展，展覽將於2024年12月14日至2025年2月23日舉行。此展覽旨在引導觀者重新審視時光的流逝，並邀請他們在動靜交織之間，捕捉生活中的瞬息之美。\r\n\r\n值此新年來臨之際，我們誠邀您共聚一堂，與我們一起在這靜謐與流動的時刻之中尋找生活的詩意，慶賀每一個短暫卻深刻的瞬間，讓心靈在這些轉瞬即逝的美之中共鳴。', '大雋藝術', '臺中市南屯區惠文路489號', '大雋藝術', 24.14165524, 120.6177379, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='大雋藝術誠摯呈獻《In Between: Ephemeral Beauty轉瞬之美》—— Cathy Tabbakh與Angela Witmore雙人聯展，展覽將於2024年12月14日至2025年2月23日舉行。此展覽旨在引導觀者重新審視時光的流逝，並邀請他們在動靜交織之間，捕捉生活中的瞬息之美。\r\n\r\n值此新年來臨之際，我們誠邀您共聚一堂，與我們一起在這靜謐與流動的時刻之中尋找生活的詩意，慶賀每一個短暫卻深刻的瞬間，讓心靈在這些轉瞬即逝的美之中共鳴。', `organizer`='大雋藝術', `address`='臺中市南屯區惠文路489號', `location`='大雋藝術', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
