INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364ce26b324689882a6b9', '梯間智慧--「閱讀主題」海報展 ', '展出內容：「閱讀」主題相關海報。', '國立公共資訊圖書館中興分館', '南投縣南投市中興新村光華路 123 號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '國立公共資訊圖書館中興分館', 23.949518, 120.694397, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='梯間智慧--「閱讀主題」海報展 ', `description`='展出內容：「閱讀」主題相關海報。', `organizer`='國立公共資訊圖書館中興分館', `address`='南投縣南投市中興新村光華路 123 號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='國立公共資訊圖書館中興分館', `latitude`=23.949518, `longitude`=120.694397, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364cf26b324689882a6c8', '寓藝－王文華創作展', '取自客觀世界的形象來表達抽象思想與概念，再將抽象的思想與概念，以藝術的語言敘述之，意即以一種形變的追求，用概念和隱喻的手法，達到能與空間對話的詩意氣質。我認為只有當藝術家進入一個完全屬於精神學的領域，作品才能超越現實。因此～嘗試在傳統中找尋自我，透過作品呈顯無意識的世界，用奇幻取代現實，進而創造出我的藝術語彙。\r\n', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-02-14 00:00:00', '2025-02-25 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4066', '[]') ON DUPLICATE KEY UPDATE `activity_name`='寓藝－王文華創作展', `description`='取自客觀世界的形象來表達抽象思想與概念，再將抽象的思想與概念，以藝術的語言敘述之，意即以一種形變的追求，用概念和隱喻的手法，達到能與空間對話的詩意氣質。我認為只有當藝術家進入一個完全屬於精神學的領域，作品才能超越現實。因此～嘗試在傳統中找尋自我，透過作品呈顯無意識的世界，用奇幻取代現實，進而創造出我的藝術語彙。\r\n', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-02-14 00:00:00', `end_date`='2025-02-25 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4066', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364cf26b324689882a6c9', '自然史教育館常設展', '以文字、圖片、燈箱、圖表及農耕器具、飾物、標本等實物陳列展出。\r\n地下一樓展示區：飲食文化、服飾文化、原住民的陶瓷工藝文化、運輸文化等、農耕文化，漁、獵文化、居住文化等實物。\r\n一樓展示區：除有原住民木雕文化展示外，也與科博館建立巡迴特展，每半年展出不同主題特展。', '南投縣自然史教育館', '南投縣仁愛鄉山農巷27號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '國立仁愛高級農業職業學校', 24.0212391, 121.1345879, '無資料', 'https://nm.ravs.ntct.edu.tw/home?cid=3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='自然史教育館常設展', `description`='以文字、圖片、燈箱、圖表及農耕器具、飾物、標本等實物陳列展出。\r\n地下一樓展示區：飲食文化、服飾文化、原住民的陶瓷工藝文化、運輸文化等、農耕文化，漁、獵文化、居住文化等實物。\r\n一樓展示區：除有原住民木雕文化展示外，也與科博館建立巡迴特展，每半年展出不同主題特展。', `organizer`='南投縣自然史教育館', `address`='南投縣仁愛鄉山農巷27號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='國立仁愛高級農業職業學校', `latitude`=24.0212391, `longitude`=121.1345879, `ticket_price`='無資料', `source_url`='https://nm.ravs.ntct.edu.tw/home?cid=3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364cf26b324689882a6ca', '「水痕水佷」桃芝颱風特展', '桃芝颱風-這個發生在23年前的災害，兩百多條人命與44億農業損失只剩下寥寥幾行的文字記錄，漸漸地被民眾所淡忘了，尤其在近十幾年幾乎沒有嚴重的颱風事件的現在。本展希望藉由各種當時的影像與災民的口述歷史，讓從未經歷過這場災害的國人了解住在這個地震島嶼上的另一種宿命。\r\n「水痕水佷」桃芝颱風特展於113年6月1日起開展至114年5月31日，6/20將進行開幕活動，歡迎大家共襄盛舉，活動期間導覽及劇場將暫停，造成不便請見諒。\r\n活動流程\r\n09：30 媒體、貴賓報到\r\n10：00 表演活動—竹山鎮富州社區發展協會竹鼓班\r\n10：10 貴賓介紹\r\n10：15 國立自然科學博物館館長 焦傳金致詞\r\n       國家災害防救科技中心副主任 林李耀致詞\r\n       木屐寮生態文化協會理事長 賴進益致詞\r\n10：25 國立自然科學博物館策展人 鍾令和博士\r\n10：35 開幕式合影\r\n10：40 特展導覽', '國立自然科學博物館車籠埔斷層保存園區', '南投縣竹山鎮集山路二段345號', '2025-01-01 00:00:00', '2025-05-31 00:00:00', '車籠埔斷層保存園區', 23.794722, 120.710611, '全票+50;團體票（20人以上）+30;優待票+30;6 歲以上，未滿 12 歲兒童+25', 'https://www.nmns.edu.tw/park_cfpp/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「水痕水佷」桃芝颱風特展', `description`='桃芝颱風-這個發生在23年前的災害，兩百多條人命與44億農業損失只剩下寥寥幾行的文字記錄，漸漸地被民眾所淡忘了，尤其在近十幾年幾乎沒有嚴重的颱風事件的現在。本展希望藉由各種當時的影像與災民的口述歷史，讓從未經歷過這場災害的國人了解住在這個地震島嶼上的另一種宿命。\r\n「水痕水佷」桃芝颱風特展於113年6月1日起開展至114年5月31日，6/20將進行開幕活動，歡迎大家共襄盛舉，活動期間導覽及劇場將暫停，造成不便請見諒。\r\n活動流程\r\n09：30 媒體、貴賓報到\r\n10：00 表演活動—竹山鎮富州社區發展協會竹鼓班\r\n10：10 貴賓介紹\r\n10：15 國立自然科學博物館館長 焦傳金致詞\r\n       國家災害防救科技中心副主任 林李耀致詞\r\n       木屐寮生態文化協會理事長 賴進益致詞\r\n10：25 國立自然科學博物館策展人 鍾令和博士\r\n10：35 開幕式合影\r\n10：40 特展導覽', `organizer`='國立自然科學博物館車籠埔斷層保存園區', `address`='南投縣竹山鎮集山路二段345號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='車籠埔斷層保存園區', `latitude`=23.794722, `longitude`=120.710611, `ticket_price`='全票+50;團體票（20人以上）+30;優待票+30;6 歲以上，未滿 12 歲兒童+25', `source_url`='https://www.nmns.edu.tw/park_cfpp/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364cf26b324689882a6cc', '地質科學廳常設展', '地質科學廳為常設展區，利用3個展示區呈現地質科學教育的各種主題。第一區域以921地震為主軸，介紹斷層活動及研究過程，再透過互動教具演示，了解臺灣誕生的原因。第二區域介紹板塊構造學說的發展及砂箱實驗，臺灣原是海底的沉積物，受到板塊運動的影響，逐步抬升成擁有許多高山的海島，學者們想了解臺灣的造山運動，因此以砂箱模擬形成的過程，從中了解板塊運動與斷層的關係。本廳擁有豐富多元的科學教育資訊，使人們能以宏觀的角度體會地質的奧秘，並省思人類的定位與作為。\r\n此外，本區亦展示園區的吉祥物-中華穿山甲。穿山甲在世界上已是瀕臨絕種的生物，為了提倡保育活動，本區介紹穿山甲的生態習性，並展示標本及動物園的生態影片，讓大家更加了解穿山甲與保育的重要性。\r\n\r\n車籠埔斷層保存園區聯絡電話：049-2623108', '國立自然科學博物館車籠埔斷層保存園區', '南投縣竹山鎮集山路二段345號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '車籠埔斷層保存園區', 23.794722, 120.710611, '全票+50;團體票（20人以上）+30;優待票+30;6 歲以上，未滿 12 歲兒童+25', 'https://www.nmns.edu.tw/park_cfpp/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='地質科學廳常設展', `description`='地質科學廳為常設展區，利用3個展示區呈現地質科學教育的各種主題。第一區域以921地震為主軸，介紹斷層活動及研究過程，再透過互動教具演示，了解臺灣誕生的原因。第二區域介紹板塊構造學說的發展及砂箱實驗，臺灣原是海底的沉積物，受到板塊運動的影響，逐步抬升成擁有許多高山的海島，學者們想了解臺灣的造山運動，因此以砂箱模擬形成的過程，從中了解板塊運動與斷層的關係。本廳擁有豐富多元的科學教育資訊，使人們能以宏觀的角度體會地質的奧秘，並省思人類的定位與作為。\r\n此外，本區亦展示園區的吉祥物-中華穿山甲。穿山甲在世界上已是瀕臨絕種的生物，為了提倡保育活動，本區介紹穿山甲的生態習性，並展示標本及動物園的生態影片，讓大家更加了解穿山甲與保育的重要性。\r\n\r\n車籠埔斷層保存園區聯絡電話：049-2623108', `organizer`='國立自然科學博物館車籠埔斷層保存園區', `address`='南投縣竹山鎮集山路二段345號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='車籠埔斷層保存園區', `latitude`=23.794722, `longitude`=120.710611, `ticket_price`='全票+50;團體票（20人以上）+30;優待票+30;6 歲以上，未滿 12 歲兒童+25', `source_url`='https://www.nmns.edu.tw/park_cfpp/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364cf26b324689882a6ce', '斷層槽溝保存館常設展', '921地震是近年來對臺灣造成嚴重災害的地震之一，發生在民國88年9月21日，故稱為921地震，其震央位於集集鎮，因此又稱為集集地震。引起這場地震的主要原因是車籠埔斷層的再次錯動，因此為了瞭解斷層過往的錯動紀錄，地質學者開始進行相關研究。\r\n槽溝是研究古地震紀錄最直接的方式，過去活動造成的地質現象都有可能在地層間保留下來，竹山槽溝因留存較完整的古地震紀錄而被保留下來。\r\n斷層槽溝保存館是半圓球型的特殊建築，外觀如同小巨蛋，此特色來以於「天圓地方」的設計理念。主要功能在於維護科學研究的現場及展示珍貴的車籠埔斷層槽溝，進入保存館行走於館內設置的空橋，近距離的觀賞斷層剖面，可讓參觀民眾體會到大自然龐大的力量，並重新學習如何與大自然共處共存。\r\n斷層槽溝保存館於112年9月1日至113年8月2日進行整修作業，並重建參觀平台，新平台提供更寬敞的參觀場域，讓觀眾可以更親近槽溝中的地質現象，藉由觀察斷層剖面真實呈顯地震所產生的地層破壞，了解台灣不可避免的地震宿命。\r\n\r\n槽溝光雕影片\r\n此影片是將學者的研究資料，以動畫的方式在現場呈現。透過影片展示，能更加瞭解車籠埔斷層過往錯動時，在竹山一帶造成的影響。', '國立自然科學博物館車籠埔斷層保存園區', '南投縣竹山鎮集山路二段345號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '車籠埔斷層保存園區', 23.794722, 120.710611, '全票+50;團體票（20人以上）+30;優待票+30;6 歲以上，未滿 12 歲兒童+25', 'https://www.nmns.edu.tw/park_cfpp/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='斷層槽溝保存館常設展', `description`='921地震是近年來對臺灣造成嚴重災害的地震之一，發生在民國88年9月21日，故稱為921地震，其震央位於集集鎮，因此又稱為集集地震。引起這場地震的主要原因是車籠埔斷層的再次錯動，因此為了瞭解斷層過往的錯動紀錄，地質學者開始進行相關研究。\r\n槽溝是研究古地震紀錄最直接的方式，過去活動造成的地質現象都有可能在地層間保留下來，竹山槽溝因留存較完整的古地震紀錄而被保留下來。\r\n斷層槽溝保存館是半圓球型的特殊建築，外觀如同小巨蛋，此特色來以於「天圓地方」的設計理念。主要功能在於維護科學研究的現場及展示珍貴的車籠埔斷層槽溝，進入保存館行走於館內設置的空橋，近距離的觀賞斷層剖面，可讓參觀民眾體會到大自然龐大的力量，並重新學習如何與大自然共處共存。\r\n斷層槽溝保存館於112年9月1日至113年8月2日進行整修作業，並重建參觀平台，新平台提供更寬敞的參觀場域，讓觀眾可以更親近槽溝中的地質現象，藉由觀察斷層剖面真實呈顯地震所產生的地層破壞，了解台灣不可避免的地震宿命。\r\n\r\n槽溝光雕影片\r\n此影片是將學者的研究資料，以動畫的方式在現場呈現。透過影片展示，能更加瞭解車籠埔斷層過往錯動時，在竹山一帶造成的影響。', `organizer`='國立自然科學博物館車籠埔斷層保存園區', `address`='南投縣竹山鎮集山路二段345號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='車籠埔斷層保存園區', `latitude`=23.794722, `longitude`=120.710611, `ticket_price`='全票+50;團體票（20人以上）+30;優待票+30;6 歲以上，未滿 12 歲兒童+25', `source_url`='https://www.nmns.edu.tw/park_cfpp/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364cf26b324689882a6cf', '車籠埔斷層保存園區視聽中心影片欣賞', '影片介紹：\r\n一、飛覽車籠埔斷層地形 \r\n1999年9月21日，車籠埔斷層再次發生錯動，引發芮氏規模7.3的集集地震，在中臺灣造成2,415人罹難、11,305人受傷，另有5萬多棟房屋全倒。在地表上，留下長達約100公里的地表破裂。\r\n由於臺灣位於環太平洋地震帶，地震災害頻繁，對臺灣造成嚴重災害的不只921地震，還有1935年新竹–臺中地震及1906年梅山地震。\r\n國立中正大學鄰近嘉義梅山斷層，因此斷層造成1906年規模7.1的災害性地震，屬於高度地震危害區域，中正大學於1990年首先設立地震研究所，並於2002年成立地球與環境科學系，除了積極培育地科相關人才之外，更肩負推廣地震教育及防災的態度與觀念。\r\n本部影片是由國立中正大學規劃，要帶領大家飛覽車籠埔斷層沿線，了解斷層活動對臺灣的影響。\r\n建議對象：親子家庭、學生、教師、樂齡、一般大眾\r\n\r\n二、吉娃斯愛科學\r\n科學動畫影集，故事敘述主角吉娃斯為實現夢想，不斷努力吸收新知，期許自己能成為部落的第一個女性領袖。\r\n第一集：古戰場新願望\r\n科學知識：反應接觸面\r\n吉娃斯為了練習射箭，在古戰場遇到了巴彥，在巴彥的教導下學習如何製作火把及原理。 \r\n第二集：爸爸冒煙啦\r\n科學知識：地殼變動\r\n部落發生了地震、河邊冒出溫泉，巴彥說明這都與板塊運動相關。\r\n建議對象：親子、學生、教師、樂齡、一般大眾\r\n\r\n三、地球的極限-海冰的眼淚\r\n台視團隊跟著台灣科學家前往北緯78度，最接近北極點的國度，挪威 冷岸群島，此處位在高北極地區，團隊經過三次轉機還要再搭船，才終於抵達北極研究站，探勘冰川時，更親眼目賭冰川崩裂瞬間，氣候變遷對極地造成的衝擊在眼前真實上演，這些掉落海中的浮冰，彷彿海冰的眼淚，不斷傳來的冰震聲，彷彿是冰川在向人類發出求救訊號，人類聽到了嗎？\r\n建議對象：親子、學生、教師、樂齡、一般大眾', '國立自然科學博物館車籠埔斷層保存園區', '南投縣竹山鎮集山路二段345號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '車籠埔斷層保存園區', 23.794722, 120.710611, '全票+50;團體票（20人以上）+30;優待票+30;6 歲以上，未滿 12 歲兒童+25', 'https://www.nmns.edu.tw/park_cfpp/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='車籠埔斷層保存園區視聽中心影片欣賞', `description`='影片介紹：\r\n一、飛覽車籠埔斷層地形 \r\n1999年9月21日，車籠埔斷層再次發生錯動，引發芮氏規模7.3的集集地震，在中臺灣造成2,415人罹難、11,305人受傷，另有5萬多棟房屋全倒。在地表上，留下長達約100公里的地表破裂。\r\n由於臺灣位於環太平洋地震帶，地震災害頻繁，對臺灣造成嚴重災害的不只921地震，還有1935年新竹–臺中地震及1906年梅山地震。\r\n國立中正大學鄰近嘉義梅山斷層，因此斷層造成1906年規模7.1的災害性地震，屬於高度地震危害區域，中正大學於1990年首先設立地震研究所，並於2002年成立地球與環境科學系，除了積極培育地科相關人才之外，更肩負推廣地震教育及防災的態度與觀念。\r\n本部影片是由國立中正大學規劃，要帶領大家飛覽車籠埔斷層沿線，了解斷層活動對臺灣的影響。\r\n建議對象：親子家庭、學生、教師、樂齡、一般大眾\r\n\r\n二、吉娃斯愛科學\r\n科學動畫影集，故事敘述主角吉娃斯為實現夢想，不斷努力吸收新知，期許自己能成為部落的第一個女性領袖。\r\n第一集：古戰場新願望\r\n科學知識：反應接觸面\r\n吉娃斯為了練習射箭，在古戰場遇到了巴彥，在巴彥的教導下學習如何製作火把及原理。 \r\n第二集：爸爸冒煙啦\r\n科學知識：地殼變動\r\n部落發生了地震、河邊冒出溫泉，巴彥說明這都與板塊運動相關。\r\n建議對象：親子、學生、教師、樂齡、一般大眾\r\n\r\n三、地球的極限-海冰的眼淚\r\n台視團隊跟著台灣科學家前往北緯78度，最接近北極點的國度，挪威 冷岸群島，此處位在高北極地區，團隊經過三次轉機還要再搭船，才終於抵達北極研究站，探勘冰川時，更親眼目賭冰川崩裂瞬間，氣候變遷對極地造成的衝擊在眼前真實上演，這些掉落海中的浮冰，彷彿海冰的眼淚，不斷傳來的冰震聲，彷彿是冰川在向人類發出求救訊號，人類聽到了嗎？\r\n建議對象：親子、學生、教師、樂齡、一般大眾', `organizer`='國立自然科學博物館車籠埔斷層保存園區', `address`='南投縣竹山鎮集山路二段345號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='車籠埔斷層保存園區', `latitude`=23.794722, `longitude`=120.710611, `ticket_price`='全票+50;團體票（20人以上）+30;優待票+30;6 歲以上，未滿 12 歲兒童+25', `source_url`='https://www.nmns.edu.tw/park_cfpp/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364cf26b324689882a6d2', '電磁視界2.0：消失的科學家', '園區與台灣電力公司策劃一座結合電磁科學教育的璀璨電塔，搭配「電磁視界」特展開幕，在2017年平安夜開始帶大家一探電與磁的奧妙！\r\n為何在以地震、地質為主題的園區要舉辦電學的特展呢？主要原因就來自於入口處的高壓電塔，過往大眾對於高壓電塔都認為是極度危險的設施，不只是高壓電，電磁波更是高得嚇人，因此許多遊客在入口看見高壓電塔後就害怕不想入場參觀。但是，高壓電塔的電磁波真的如此危險嗎？\r\n\r\n本特展就是以電與電磁波為主軸，介紹生活用電與電磁波介紹，透過85個電磁波監測站，實際量測並視覺化展示園區內實際運作的超高壓電塔的電力電磁波，讓民眾可以親眼看到電磁波的強弱，同時在室內外提供許多互動展品，可以在玩樂中認識電力、電磁與能源的科學知識。\r\n「電磁視界2.0：消失的科學家」於2023年1月1日開放參觀，本次特展注重電與磁的科普傳播，2.0更新版建立於舊版基礎上，以神秘電磁場與原子意象作為入口設計。\r\n車籠埔斷層保存園區聯絡電話：049-2623108', '國立自然科學博物館車籠埔斷層保存園區', '南投縣竹山鎮集山路二段345號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '車籠埔斷層保存園區', 23.794722, 120.710611, '全票+50;團體票（20人以上）+30;優待票+30;6 歲以上，未滿 12 歲兒童+25', 'https://www.nmns.edu.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='電磁視界2.0：消失的科學家', `description`='園區與台灣電力公司策劃一座結合電磁科學教育的璀璨電塔，搭配「電磁視界」特展開幕，在2017年平安夜開始帶大家一探電與磁的奧妙！\r\n為何在以地震、地質為主題的園區要舉辦電學的特展呢？主要原因就來自於入口處的高壓電塔，過往大眾對於高壓電塔都認為是極度危險的設施，不只是高壓電，電磁波更是高得嚇人，因此許多遊客在入口看見高壓電塔後就害怕不想入場參觀。但是，高壓電塔的電磁波真的如此危險嗎？\r\n\r\n本特展就是以電與電磁波為主軸，介紹生活用電與電磁波介紹，透過85個電磁波監測站，實際量測並視覺化展示園區內實際運作的超高壓電塔的電力電磁波，讓民眾可以親眼看到電磁波的強弱，同時在室內外提供許多互動展品，可以在玩樂中認識電力、電磁與能源的科學知識。\r\n「電磁視界2.0：消失的科學家」於2023年1月1日開放參觀，本次特展注重電與磁的科普傳播，2.0更新版建立於舊版基礎上，以神秘電磁場與原子意象作為入口設計。\r\n車籠埔斷層保存園區聯絡電話：049-2623108', `organizer`='國立自然科學博物館車籠埔斷層保存園區', `address`='南投縣竹山鎮集山路二段345號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='車籠埔斷層保存園區', `latitude`=23.794722, `longitude`=120.710611, `ticket_price`='全票+50;團體票（20人以上）+30;優待票+30;6 歲以上，未滿 12 歲兒童+25', `source_url`='https://www.nmns.edu.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364d026b324689882a6d4', '走進片刻－凝視，是繼續延續蔓延的漣漪 藝術家聯展', '藝術與心靈的對話，創作者以畫筆描繪生命的片段，將歲月化為可凝視的美好瞬間。每一筆都是心靈的回音，邀請觀者走進片刻，凝視漣漪。在這場超越現實的視覺旅程中，觀者釋放想像，從色彩與線條中尋找共鳴。這不僅是一幅畫，而是人生的縮影，每一次凝視，都讓心靈充盈，體會生命的詩意。', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-02-28 00:00:00', '2025-03-11 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4067', '[]') ON DUPLICATE KEY UPDATE `activity_name`='走進片刻－凝視，是繼續延續蔓延的漣漪 藝術家聯展', `description`='藝術與心靈的對話，創作者以畫筆描繪生命的片段，將歲月化為可凝視的美好瞬間。每一筆都是心靈的回音，邀請觀者走進片刻，凝視漣漪。在這場超越現實的視覺旅程中，觀者釋放想像，從色彩與線條中尋找共鳴。這不僅是一幅畫，而是人生的縮影，每一次凝視，都讓心靈充盈，體會生命的詩意。', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-03-11 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4067', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364d026b324689882a6d7', '2025聯邦藝術巡迴展', '聯邦文教基金會長期以來對於推動藝術美學不遺餘力，27年來在聯邦銀行及聯邦租賃的贊助及支持下，致力於培養本土藝術人才，並提供藝術者展現活力與創意的舞台，聯邦藝術獎項包括：「聯邦美術新人獎」及「聯邦美術印象大獎」，以高額獎金鼓勵臺灣本土藝術創作者勇於創作實現夢想，透過比賽展現實力，脫穎而出的優秀畫家更因此受到各界的肯定與支持，本次展出內容包含聯邦藝術比賽之「第22屆聯邦美術印象大獎」與「第27屆聯邦美術新人獎」得獎作品，參觀民眾可同時欣賞到印象及寫實兩種不同油畫風格之參賽優秀作品。本次得獎者分別為「第22屆聯邦美術印象大獎」首獎：吳羽宸/優選：宋適生、吳岱瑾/入選：李承修、謝愷宸；「第26屆聯邦美術新人獎」首獎：李郁汝/優選：許品婕、白穆君/入選：翁昕吟、蔡依君。\r\n各式不同畫風的精彩畫作絕對可以讓所有熱愛繪畫藝術的民眾大飽眼福，是2025年不容錯過的藝術盛宴！\r\n', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-02-21 00:00:00', '2025-03-04 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=3908', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025聯邦藝術巡迴展', `description`='聯邦文教基金會長期以來對於推動藝術美學不遺餘力，27年來在聯邦銀行及聯邦租賃的贊助及支持下，致力於培養本土藝術人才，並提供藝術者展現活力與創意的舞台，聯邦藝術獎項包括：「聯邦美術新人獎」及「聯邦美術印象大獎」，以高額獎金鼓勵臺灣本土藝術創作者勇於創作實現夢想，透過比賽展現實力，脫穎而出的優秀畫家更因此受到各界的肯定與支持，本次展出內容包含聯邦藝術比賽之「第22屆聯邦美術印象大獎」與「第27屆聯邦美術新人獎」得獎作品，參觀民眾可同時欣賞到印象及寫實兩種不同油畫風格之參賽優秀作品。本次得獎者分別為「第22屆聯邦美術印象大獎」首獎：吳羽宸/優選：宋適生、吳岱瑾/入選：李承修、謝愷宸；「第26屆聯邦美術新人獎」首獎：李郁汝/優選：許品婕、白穆君/入選：翁昕吟、蔡依君。\r\n各式不同畫風的精彩畫作絕對可以讓所有熱愛繪畫藝術的民眾大飽眼福，是2025年不容錯過的藝術盛宴！\r\n', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-02-21 00:00:00', `end_date`='2025-03-04 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=3908', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364d026b324689882a6d9', '與熊共存-臺灣黑熊特展', '不只是說說的國寶，更是共同生活的一份子\r\n臺灣黑熊作為臺灣唯一的原生熊類、稀有的保育類動物，近年來因環境保護、生態保育意識興起，頻繁出現於大眾視野中，民眾開始瞭解其所面臨的生存壓力，包含非法狩獵、誤中陷阱或山屋滋擾等人熊衝突，但偶爾也有母熊帶小熊的溫馨畫面。根據多年研究調查及通報資料顯示，於玉山園區及周遭皆有其活動蹤跡，在在顯示基礎研究的重要性及國家公園推展保育行動的成效。在塔塔加地區漫步的大家，要巧遇牠也不無可能，只是您真的有做好心理準備要來與牠相遇了嗎？\r\n玉管處為讓國人更加認識臺灣的國寶-臺灣黑熊，與台灣黑熊保育協會合作，展出仿真1:1雕像、頭骨、足拓、作為食物來源的植物標本、研究採集的毛髮、糞便及啃咬痕等實物展品，另還有調查使用的設備器材，以及防熊設備等，近距離呈現給大眾，同時搭配有獎徵答活動，一步步從臺灣黑熊的身家背景到我們如何與其自在共存，全方位了解同處於臺灣寶島上的珍貴家人。\r\n\r\n守護牠，也是守護我們自己\r\n作為生態系食物鏈中不可或缺的大型食肉目動物，其食物來源有八成來自植物，加上其廣大的活動範圍，是許多植物重要的傳播者，更是健康山林的靈魂。近年來國內登山戶外活動風氣漸盛，國人開始走入山林，因此「人熊共存」，亦或是「與自然環境共存」是玉管處所肩負的保育重任及重要議題，其中最核心價值莫過於「無痕山林」，將對自然環境的影響降至最低，方能與自然萬物共生共存。希冀透過特展的呈現，將相關黑熊知識、與熊共存、無痕山林議題及國家公園於保育工作、教育推廣的努力傳遞出去，讓大眾了解自身行為小小的改變及積累，皆是為守護家園盡一份心力。', '玉山國家公園管理處', '南投縣信義鄉太平巷118號', '2025-01-01 00:00:00', '2025-08-31 00:00:00', '玉山國家公園管理處塔塔加遊客中心', 23.6777698, 120.9569588, '無資料', 'https://www.ysnp.gov.tw/Apply/ActivityRegistration/C030001', '[]') ON DUPLICATE KEY UPDATE `activity_name`='與熊共存-臺灣黑熊特展', `description`='不只是說說的國寶，更是共同生活的一份子\r\n臺灣黑熊作為臺灣唯一的原生熊類、稀有的保育類動物，近年來因環境保護、生態保育意識興起，頻繁出現於大眾視野中，民眾開始瞭解其所面臨的生存壓力，包含非法狩獵、誤中陷阱或山屋滋擾等人熊衝突，但偶爾也有母熊帶小熊的溫馨畫面。根據多年研究調查及通報資料顯示，於玉山園區及周遭皆有其活動蹤跡，在在顯示基礎研究的重要性及國家公園推展保育行動的成效。在塔塔加地區漫步的大家，要巧遇牠也不無可能，只是您真的有做好心理準備要來與牠相遇了嗎？\r\n玉管處為讓國人更加認識臺灣的國寶-臺灣黑熊，與台灣黑熊保育協會合作，展出仿真1:1雕像、頭骨、足拓、作為食物來源的植物標本、研究採集的毛髮、糞便及啃咬痕等實物展品，另還有調查使用的設備器材，以及防熊設備等，近距離呈現給大眾，同時搭配有獎徵答活動，一步步從臺灣黑熊的身家背景到我們如何與其自在共存，全方位了解同處於臺灣寶島上的珍貴家人。\r\n\r\n守護牠，也是守護我們自己\r\n作為生態系食物鏈中不可或缺的大型食肉目動物，其食物來源有八成來自植物，加上其廣大的活動範圍，是許多植物重要的傳播者，更是健康山林的靈魂。近年來國內登山戶外活動風氣漸盛，國人開始走入山林，因此「人熊共存」，亦或是「與自然環境共存」是玉管處所肩負的保育重任及重要議題，其中最核心價值莫過於「無痕山林」，將對自然環境的影響降至最低，方能與自然萬物共生共存。希冀透過特展的呈現，將相關黑熊知識、與熊共存、無痕山林議題及國家公園於保育工作、教育推廣的努力傳遞出去，讓大眾了解自身行為小小的改變及積累，皆是為守護家園盡一份心力。', `organizer`='玉山國家公園管理處', `address`='南投縣信義鄉太平巷118號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='玉山國家公園管理處塔塔加遊客中心', `latitude`=23.6777698, `longitude`=120.9569588, `ticket_price`='無資料', `source_url`='https://www.ysnp.gov.tw/Apply/ActivityRegistration/C030001', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364d026b324689882a6de', '臺灣省政資料館主題陳列特展', '包括「姊妹州文物陳列室」、「臺灣史蹟文物陳列室」、「國定古蹟模型陳列區」、「臺灣省歷任主席施政績效陳列室」、「臺灣省建設成果展示室」及「FUN檔案體驗展示室」等主題陳列特展，歡迎參觀。洽詢電話：2350530轉1626。\r\n\r\n姊妹州文物陳列室\r\n本陳列室於民國七十四年十月二十五日建置完成，展示與臺灣省政府締結姐妹州之各項文物及締盟資料。展現我中華民國人民愛好和平，崇尚自由民主，與世界各民主國家人民友好交誼的民族特色往來的成果。\r\n\r\n臺灣史蹟文物陳列室\r\n收集臺灣歷史文物資料，以圖片、模型、圖表、器物、多媒體表現，配合文字，序時陳列展示。使參觀來賓了解歷代開發建設臺灣的艱辛歷程，讓國人能更珍愛這片大地。\r\n\r\n國定古蹟模型陳列區\r\n介紹先民開發臺灣的重要史實，精製臺灣地區10處國定古蹟：基隆二沙灣砲台、淡水紅毛城、彰化孔廟、金廣福公館、祀典武廟、鹿港龍山寺、臺南孔子廟、赤嵌樓、億載金城、澎湖天后宮等十座古蹟模型，陳述其創建年代、歷史意義及特色等資料，讓來賓了解臺灣的歷史及傳統建築特色。\r\n\r\n臺灣省歷任主席施政績效陳列室\r\n本陳列室以歷任省府主席、省長主持省政為經，建設績效為緯。展現從民國34年10月25日至107年7月1日期間，推動省政建設，促成臺灣社會進步的成就。讓前來觀賞的來賓，對臺灣省政發展歷程，有更深入的了解。\r\n\r\n臺灣省建設成果展示室\r\n回首建設臺灣這片土地的年代，從政治制度、社會福利、經濟財政、交通運輸、教育文化等面向，省府團隊曾經投入心力參與各項政策的推動。本展示室透過六大建設內容，讓參訪民眾進入歷史長河中，回顧重要的建設發展歷程與成果，珍惜現有的資源，打造屬於每個人引以為傲的臺灣經驗。\r\n\r\nFUN檔案體驗展示室\r\n本展以「檔案生命週期」為主軸，經由8單元連結檔案的世界與多元價值，循著檔案專業分類的類-綱-目層級數碼，由檔案代言人阿凱將帶領參觀者展開檔案印象之旅，次第揭開各階段歷程，並以「便捷開放應用」為意象，結合「體驗檔案專業」現場，見證檔案專業的細膩，是國內首次以認識檔案為主題的展覽；展場空間更以檔案的英文「ARCHIVES」立體化鋪設，讓觀展的每個步伐與思緒隨之雀躍，也從中細細發掘檔案的保存價值。', '國家發展委員會檔案管理局', '南投縣南投市中正路2號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺灣省政資料館', 23.9557878, 120.686329, '無資料', 'https://www.archives.gov.tw/MenuList.aspx?cnid=103598', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺灣省政資料館主題陳列特展', `description`='包括「姊妹州文物陳列室」、「臺灣史蹟文物陳列室」、「國定古蹟模型陳列區」、「臺灣省歷任主席施政績效陳列室」、「臺灣省建設成果展示室」及「FUN檔案體驗展示室」等主題陳列特展，歡迎參觀。洽詢電話：2350530轉1626。\r\n\r\n姊妹州文物陳列室\r\n本陳列室於民國七十四年十月二十五日建置完成，展示與臺灣省政府締結姐妹州之各項文物及締盟資料。展現我中華民國人民愛好和平，崇尚自由民主，與世界各民主國家人民友好交誼的民族特色往來的成果。\r\n\r\n臺灣史蹟文物陳列室\r\n收集臺灣歷史文物資料，以圖片、模型、圖表、器物、多媒體表現，配合文字，序時陳列展示。使參觀來賓了解歷代開發建設臺灣的艱辛歷程，讓國人能更珍愛這片大地。\r\n\r\n國定古蹟模型陳列區\r\n介紹先民開發臺灣的重要史實，精製臺灣地區10處國定古蹟：基隆二沙灣砲台、淡水紅毛城、彰化孔廟、金廣福公館、祀典武廟、鹿港龍山寺、臺南孔子廟、赤嵌樓、億載金城、澎湖天后宮等十座古蹟模型，陳述其創建年代、歷史意義及特色等資料，讓來賓了解臺灣的歷史及傳統建築特色。\r\n\r\n臺灣省歷任主席施政績效陳列室\r\n本陳列室以歷任省府主席、省長主持省政為經，建設績效為緯。展現從民國34年10月25日至107年7月1日期間，推動省政建設，促成臺灣社會進步的成就。讓前來觀賞的來賓，對臺灣省政發展歷程，有更深入的了解。\r\n\r\n臺灣省建設成果展示室\r\n回首建設臺灣這片土地的年代，從政治制度、社會福利、經濟財政、交通運輸、教育文化等面向，省府團隊曾經投入心力參與各項政策的推動。本展示室透過六大建設內容，讓參訪民眾進入歷史長河中，回顧重要的建設發展歷程與成果，珍惜現有的資源，打造屬於每個人引以為傲的臺灣經驗。\r\n\r\nFUN檔案體驗展示室\r\n本展以「檔案生命週期」為主軸，經由8單元連結檔案的世界與多元價值，循著檔案專業分類的類-綱-目層級數碼，由檔案代言人阿凱將帶領參觀者展開檔案印象之旅，次第揭開各階段歷程，並以「便捷開放應用」為意象，結合「體驗檔案專業」現場，見證檔案專業的細膩，是國內首次以認識檔案為主題的展覽；展場空間更以檔案的英文「ARCHIVES」立體化鋪設，讓觀展的每個步伐與思緒隨之雀躍，也從中細細發掘檔案的保存價值。', `organizer`='國家發展委員會檔案管理局', `address`='南投縣南投市中正路2號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺灣省政資料館', `latitude`=23.9557878, `longitude`=120.686329, `ticket_price`='無資料', `source_url`='https://www.archives.gov.tw/MenuList.aspx?cnid=103598', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675364d026b324689882a6e1', '竹藝博物館常設展', '展區介紹：\r\n一、經典作品區，陳列竹編吳聖宗先生、黃塗山先生、李榮烈先生的竹編作品。還有結合竹材與其他媒材的創作，如黃麗淑女士的竹、漆結合；竹雕方面則有陳銘堂的「四勿」，葉基祥的「步步高升」，葉大川的「惜福」，林裕允的「蝴蝶蘭」等，都有很高的藝術造詣。\r\n二、農漁獵用具區，我國向來以農立國，先民早期生活以農業為主，人民所須之農業用具頗多，耕作時犁田所使用牛擔、牛嘴套、刈耙、畚箕、斗笠、龜甲笠等，採收茶葉之竹簍，烘茶籠，大都為竹器具，尤其以竹編居多。此外捕魚也是農業社會一種營生方式，本區同時展出魚筌﹝哥仔﹞、魚苗簍、蝦籠、水蛙籠、魚籗、捕魚用竹筏皆用竹材製成，包括救生筒也是採用竹筒製成的。\r\n三、竹雕區，竹雕依雕刻技法分為陰雕、陽雕、浮雕、透雕及立雕。本區展示竹雕用具與竹雕名家作品，如顏鄭森、施惠閔、盧士珍等藝術創作。\r\n四、竹編區，竹編創作竹材以桂竹、刺竹居多，孟宗竹、麻竹次之，程序是—選材、劈成竹條、竹片、編織、細部修飾、上色塗裝等五個步驟。本區展出邱錦緞、葉寶蓮、黃如窗、林秀鳳、李弘偉等精緻竹編作品。\r\n五、現代竹工藝區，現代竹工藝品除具實用性外，外表美觀也是設計的重點，展區內陳列吳美菊、吳柳燕等竹編提包其質感與價值，非LV皮包可媲美，另彭雅玲的蘭花漆杯及林建成的舞影燈飾均具現代美感及藝術風格。\r\n六、嫁娶節慶、竹屋建築展示區，展出內容包括嫁娶、節慶用具，竹筏、竹橋等竹製交通工具，竹建築屋內則陳列早期台灣廚房、書房、客廳、臥房等竹製家具。\r\n七影音資源及互動體驗區，本區多媒體影音播放竹藝相關影片，竹樂器、竹琴與「知足常樂」等互動設施，提供民眾體驗。', '南投縣政府文化局', '南投縣南投市建國路135號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='竹藝博物館常設展', `description`='展區介紹：\r\n一、經典作品區，陳列竹編吳聖宗先生、黃塗山先生、李榮烈先生的竹編作品。還有結合竹材與其他媒材的創作，如黃麗淑女士的竹、漆結合；竹雕方面則有陳銘堂的「四勿」，葉基祥的「步步高升」，葉大川的「惜福」，林裕允的「蝴蝶蘭」等，都有很高的藝術造詣。\r\n二、農漁獵用具區，我國向來以農立國，先民早期生活以農業為主，人民所須之農業用具頗多，耕作時犁田所使用牛擔、牛嘴套、刈耙、畚箕、斗笠、龜甲笠等，採收茶葉之竹簍，烘茶籠，大都為竹器具，尤其以竹編居多。此外捕魚也是農業社會一種營生方式，本區同時展出魚筌﹝哥仔﹞、魚苗簍、蝦籠、水蛙籠、魚籗、捕魚用竹筏皆用竹材製成，包括救生筒也是採用竹筒製成的。\r\n三、竹雕區，竹雕依雕刻技法分為陰雕、陽雕、浮雕、透雕及立雕。本區展示竹雕用具與竹雕名家作品，如顏鄭森、施惠閔、盧士珍等藝術創作。\r\n四、竹編區，竹編創作竹材以桂竹、刺竹居多，孟宗竹、麻竹次之，程序是—選材、劈成竹條、竹片、編織、細部修飾、上色塗裝等五個步驟。本區展出邱錦緞、葉寶蓮、黃如窗、林秀鳳、李弘偉等精緻竹編作品。\r\n五、現代竹工藝區，現代竹工藝品除具實用性外，外表美觀也是設計的重點，展區內陳列吳美菊、吳柳燕等竹編提包其質感與價值，非LV皮包可媲美，另彭雅玲的蘭花漆杯及林建成的舞影燈飾均具現代美感及藝術風格。\r\n六、嫁娶節慶、竹屋建築展示區，展出內容包括嫁娶、節慶用具，竹筏、竹橋等竹製交通工具，竹建築屋內則陳列早期台灣廚房、書房、客廳、臥房等竹製家具。\r\n七影音資源及互動體驗區，本區多媒體影音播放竹藝相關影片，竹樂器、竹琴與「知足常樂」等互動設施，提供民眾體驗。', `organizer`='南投縣政府文化局', `address`='南投縣南投市建國路135號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67547fc626b324689882a6ed', '十鼓藝術季-2025魔法夜祭', '無資料', '無資料', '臺南市仁德區文華路二段326號', '2025-03-13 00:00:00', '2025-03-13 00:00:00', '十鼓文創園區-夢糖劇場', 22.9404568, 120.2306078, '無資料', 'https://www.opentix.life/program/1859062466187223041', '[]') ON DUPLICATE KEY UPDATE `activity_name`='十鼓藝術季-2025魔法夜祭', `description`='無資料', `organizer`='無資料', `address`='臺南市仁德區文華路二段326號', `start_date`='2025-03-13 00:00:00', `end_date`='2025-03-13 00:00:00', `location`='十鼓文創園區-夢糖劇場', `latitude`=22.9404568, `longitude`=120.2306078, `ticket_price`='無資料', `source_url`='https://www.opentix.life/program/1859062466187223041', `image_url`='[]';
