INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675605a826b324689882a727', '嘉義火雞肉飯特展：來嘉呷飯', '展覽以火雞肉飯為主軸、嘉義市區為範疇，透過外來食材在地化的過程，描繪嘉義地方社會與日常生活的樣貌。\r\n透過不同的主題策展，向民眾闡述關於這座城市的故事。繼「前線的微笑老蕭－蕭萬長人物特展」結束後，緊接著以「來嘉呷飯-嘉義火雞肉飯特展」呈現嘉義市如火雞肉飯般，溫暖、實在的城市內涵。', '嘉義市政府文化局', '嘉義市東區忠孝路275-1號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '嘉義市立博物館', 23.48170334, 120.4706244, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='嘉義火雞肉飯特展：來嘉呷飯', `description`='展覽以火雞肉飯為主軸、嘉義市區為範疇，透過外來食材在地化的過程，描繪嘉義地方社會與日常生活的樣貌。\r\n透過不同的主題策展，向民眾闡述關於這座城市的故事。繼「前線的微笑老蕭－蕭萬長人物特展」結束後，緊接著以「來嘉呷飯-嘉義火雞肉飯特展」呈現嘉義市如火雞肉飯般，溫暖、實在的城市內涵。', `organizer`='嘉義市政府文化局', `address`='嘉義市東區忠孝路275-1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='嘉義市立博物館', `latitude`=23.48170334, `longitude`=120.4706244, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
