INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675ca23226b32458d4362e1b', '2025樂齡書法展(合辦單位:霧峰長青學苑)', '霧峰長青學苑的爺爺奶奶們每堂課都很用功的一筆一劃在學寫書法，經過一整年的學習，到2024歲末把一年學習的成果在這次展覽上展現出來，到圖書館借書的大家在書庫挑書時也請參觀一下我們的書法展，借書之餘還能修身養性，期待您的光臨﹗', '臺中市立圖書館霧峰以文分館', '臺中市霧峰區大同路8號', '2025-01-02 00:00:00', '2025-03-16 00:00:00', '臺中市立圖書館霧峰以文分館', 24.0615719, 120.699002, '無資料', 'https://www.library.taichung.gov.tw/public/activity2/index-1.asp?Parser=99,20,697,50,,,22100,,,,,338', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025樂齡書法展(合辦單位:霧峰長青學苑)', `description`='霧峰長青學苑的爺爺奶奶們每堂課都很用功的一筆一劃在學寫書法，經過一整年的學習，到2024歲末把一年學習的成果在這次展覽上展現出來，到圖書館借書的大家在書庫挑書時也請參觀一下我們的書法展，借書之餘還能修身養性，期待您的光臨﹗', `organizer`='臺中市立圖書館霧峰以文分館', `address`='臺中市霧峰區大同路8號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺中市立圖書館霧峰以文分館', `latitude`=24.0615719, `longitude`=120.699002, `ticket_price`='無資料', `source_url`='https://www.library.taichung.gov.tw/public/activity2/index-1.asp?Parser=99,20,697,50,,,22100,,,,,338', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675ca23626b32458d4362e27', '主題書展-繞著台灣讀美食~臺東篇', '台灣雖然面積不大，但同時容納閩南、客家、原住民和新住民，成為一個文化大融合的環境。而吃在任何文化中都是最重要的核心靈魂，不同的文化背景造就不同的口味、食材、烹調方式等，無論是閩南、客家、原住民、新住民等，都有各自豐富的飲食文化，這些也都是屬於台灣的味道，就讓我們繞著台灣讀美食~與臺東來場文化之旅。', '高雄市立圖書館總館', '高雄市楠梓區德惠路55號3樓', '2025-01-02 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館翠屏分館', 22.7267707, 120.302985, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='主題書展-繞著台灣讀美食~臺東篇', `description`='台灣雖然面積不大，但同時容納閩南、客家、原住民和新住民，成為一個文化大融合的環境。而吃在任何文化中都是最重要的核心靈魂，不同的文化背景造就不同的口味、食材、烹調方式等，無論是閩南、客家、原住民、新住民等，都有各自豐富的飲食文化，這些也都是屬於台灣的味道，就讓我們繞著台灣讀美食~與臺東來場文化之旅。', `organizer`='高雄市立圖書館總館', `address`='高雄市楠梓區德惠路55號3樓', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館翠屏分館', `latitude`=22.7267707, `longitude`=120.302985, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675ca23626b32458d4362e2a', '拾景詠情—王宏印油畫個展', '呈現了我對日常生活中平凡卻動人景象的深刻感受與讚頌。展出的作品涵蓋台灣多樣的自然景觀與人文風情，包括清新的山水、靜謐的溪流、蔚藍的海洋，以及栩栩如生的牛、雞、鴨等動物。此外，色彩鮮明的台灣水果與花卉更點綴了這片土地的獨特之美。每幅畫作都承載了我對生活的細膩觀察與內心的情感流露，希望觀者能與我一起拾起生活中的片刻感動，感受自然與人文的和諧之美。', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-02-21 00:00:00', '2025-03-04 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4070', '[]') ON DUPLICATE KEY UPDATE `activity_name`='拾景詠情—王宏印油畫個展', `description`='呈現了我對日常生活中平凡卻動人景象的深刻感受與讚頌。展出的作品涵蓋台灣多樣的自然景觀與人文風情，包括清新的山水、靜謐的溪流、蔚藍的海洋，以及栩栩如生的牛、雞、鴨等動物。此外，色彩鮮明的台灣水果與花卉更點綴了這片土地的獨特之美。每幅畫作都承載了我對生活的細膩觀察與內心的情感流露，希望觀者能與我一起拾起生活中的片刻感動，感受自然與人文的和諧之美。', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-02-21 00:00:00', `end_date`='2025-03-04 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4070', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675ca23626b32458d4362e2b', '「藝術美感」主題書展', '「藝術美感」主題書展\r\n於二樓設置專區放置相關主題書籍。定期更換推薦書籍，歡迎大家借閱。\r\n▪展演時間｜114年2月1日至2月28日／開館時間\r\n▪展演書單｜大師名作這樣看好好玩! 羅浮宮專家給孩子的藝術啟蒙課、地圖藝術實驗室、與眼睛看不見的白鳥先生一起看見藝術、原飾那麼美 : 臺灣原住民16族服飾文化藝術與生活美學、見微知著 : 景品與微書的藝術、台灣傳統剪紙的傳承、藝術家、藝術讓你笑哈哈、大自然的藝術家 : 不可思議的線條和形狀、不然你來養 : 古典藝術與人生、藝術原來是這樣..等書籍', '高雄市立圖書館總館', '高雄市湖內區3鄰保生路101號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '高雄市立圖書館湖內分館', 22.8955499, 120.2225563, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「藝術美感」主題書展', `description`='「藝術美感」主題書展\r\n於二樓設置專區放置相關主題書籍。定期更換推薦書籍，歡迎大家借閱。\r\n▪展演時間｜114年2月1日至2月28日／開館時間\r\n▪展演書單｜大師名作這樣看好好玩! 羅浮宮專家給孩子的藝術啟蒙課、地圖藝術實驗室、與眼睛看不見的白鳥先生一起看見藝術、原飾那麼美 : 臺灣原住民16族服飾文化藝術與生活美學、見微知著 : 景品與微書的藝術、台灣傳統剪紙的傳承、藝術家、藝術讓你笑哈哈、大自然的藝術家 : 不可思議的線條和形狀、不然你來養 : 古典藝術與人生、藝術原來是這樣..等書籍', `organizer`='高雄市立圖書館總館', `address`='高雄市湖內區3鄰保生路101號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='高雄市立圖書館湖內分館', `latitude`=22.8955499, `longitude`=120.2225563, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675ca23626b32458d4362e2e', '三民書法班', '聘請專業書法家，藉由心靈修持入門進入書法初階，以間架、點配線條、結體為學習重點，進入「神至筆至」的書寫樂趣，達到修心養性和諧精神境界。', '高雄市立圖書館總館', '高雄市三民區2鄰十全一路220號', '2025-01-09 00:00:00', '2025-12-25 00:00:00', '高雄市立圖書館三民分館', 22.646393, 120.306137, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三民書法班', `description`='聘請專業書法家，藉由心靈修持入門進入書法初階，以間架、點配線條、結體為學習重點，進入「神至筆至」的書寫樂趣，達到修心養性和諧精神境界。', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區2鄰十全一路220號', `start_date`='2025-01-09 00:00:00', `end_date`='2025-12-25 00:00:00', `location`='高雄市立圖書館三民分館', `latitude`=22.646393, `longitude`=120.306137, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675ca23726b32458d4362e35', '所有令人屏息的─ 2024亞洲藝術雙年展 How to Hold Your Breath - 2024 Asian Art Biennial', '所有令人屏息的\r\n\r\n2021年3月27日，克羅埃西亞自由潛水員迪米爾．索巴特（Budimir Šobat）以24分37.36秒創下了最長自主閉氣時間的新世界紀錄。\r\n\r\n1986 年，從人民力量革命（People Power Revolution）以非暴力方式推翻了菲律賓長達三十年的馬可仕獨裁統治到車諾比核災難，這充滿災難與異議的一年中，歌曲「Take My Breath Away（令我神魂顛倒）」登上了金曲暢銷排行榜首。\r\n\r\n在公元早期幾世紀間，帕坦伽利編撰的瑜伽經中描述「kumbhaka」為一種透過逐漸停止吸氣與吐息而暫停呼吸的調息法；屏息，是長久以來被認為最古老亦最簡單的改變心智狀態的技術之一。\r\n\r\n2024亞洲藝術雙年展題名為「所有令人屏息的」，由召喚這自行暫歇生命機能的行為，進而創造出一種期待的狀態。展題命名反轉了「別屏息以待」（don’t hold your breath）原意為別期望改變很快發生的警示，在此則暗示著潛在的希望。\r\n\r\n深呼吸並屏住氣息，將我們錨繫於當下時刻。當世界崩壞墜入下一層深淵之際，我們穿梭在晚期資本主義餘波的喧囂與塵埃中，在居所與流離之間持續遷徙與探航。這平靜呼吸、重整思緒的行為是在轉換的運動中，從一種現實過渡到另一種現實的預備。間歇作為一種音程，用以聆聽靜默之聲，重新調諧我們身體與地球之間新陳代謝的節律。\r\n\r\n如同一則可供使用又同時規避的參考指南，我們可以將「所有令人屏息的」視為一個號召，呼籲人們從可見性領域和延續暴力的系統中撤出，形成從中能產生新能動性的隱蔽空間。我們將之想像為在迎向未決與不確定未來之前的一次深潛。\r\n\r\n在2024亞洲藝術雙年展中，藝術家們從基於關係性、交互性和具回應能力的經驗知識與生活方式中獲得啟發，無論在政治性或美學層面，提出關於世界秩序的另類想像和實踐。在此核心的探問是：何種不具壓迫性之集體和政治形式能將我們凝聚在一起？\r\n\r\n透過多樣的媒介形式，參展作品向進步論和普世時間觀提出質疑，以揭示歷史如何與人、地方和位置緊密相連。在於當前帝國政治以及支配生活的新社會系統中，透過追溯纏結的殖民暴力，為替代性的解放未來開闢了空間。\r\n\r\n我們始終棲居於由多個世界共存並持續變動的複數多元宇宙中。展覽中的部分作品涉及了意識狀態的改變——無論是透過冥想、睡眠、夢境或藥物——被視為是一種邊界地帶，在其中允許著屬於複數世界中交替性、共時性、多穩態的感知方式。屏息此一形而上意義的行動，作為重構並重新想像世界的一種方式，喚起了在崩解之中的創造潛能。\r\n\r\n受到全球資本主義影響下之文化與地理的遷徙，持續改變著人類與非人的身份、意義與構成。植物、動物、礦物和人類在資本主義積累的分類體系中被位移、放逐、汲取、變形與物化，順應著商品與服務的邏輯。然而，在這些物品與人員流動過程之中與其外，新的連結與歸屬感逐漸浮現，如同新的物種與文化在既有的地圖和記憶之外演化一般。\r\n\r\n未來的敘事如何擺脫現代性末世神話的束縛而敞開，並將其他存在與行動者納入希望的實踐中？答案或許不在於宏大的願景，而在於那些我們可以與他人分享之具體臨在的想像中；無論是透過日常細微事物的連結，或是創生新的混合群體。正是在這些我們共同建立的關係連結中，在一同的屏息時刻，我們或將找到想像開啟新未來的種子，抵抗絕望。', '國立臺灣美術館', '臺中市西區五權西路一段2號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '國立臺灣美術館', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/O51rng', '[]') ON DUPLICATE KEY UPDATE `activity_name`='所有令人屏息的─ 2024亞洲藝術雙年展 How to Hold Your Breath - 2024 Asian Art Biennial', 