INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675f3b2626b32458d4362ec1', '心繫臺灣：王育德文物捐贈展', '王育德是第一位台語博士，也是第一位在日本大學開台語課的教授。適逢王育德百歲冥誕，特推出本次意義深具的展覽。主要爬梳館藏捐贈文物，描繪王育德對文學、台語研究、臺灣民主運動等多方面的貢獻，另有臺北高等學校、海外黑名單延伸展區，完整呈現王育德被迫滯留海外卻仍心繫臺灣，而開拓許多的「第一」創舉。', '國立臺灣文學館', '臺南市中西區中正路1號', '2025-01-01 00:00:00', '2025-04-06 00:00:00', '國立臺灣文學館', 22.992064, 120.203953, '無資料', 'https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=40069', '[]') ON DUPLICATE KEY UPDATE `activity_name`='心繫臺灣：王育德文物捐贈展', `description`='王育德是第一位台語博士，也是第一位在日本大學開台語課的教授。適逢王育德百歲冥誕，特推出本次意義深具的展覽。主要爬梳館藏捐贈文物，描繪王育德對文學、台語研究、臺灣民主運動等多方面的貢獻，另有臺北高等學校、海外黑名單延伸展區，完整呈現王育德被迫滯留海外卻仍心繫臺灣，而開拓許多的「第一」創舉。', `organizer`='國立臺灣文學館', `address`='臺南市中西區中正路1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='國立臺灣文學館', `latitude`=22.992064, `longitude`=120.203953, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=40069', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675f3b2626b32458d4362ec3', '打字機也會唱歌：捷克現當代文學展', '捷克與臺灣，分別位於歐洲的中心與亞洲的邊陲，彼此距離超過了九千公里。然而，歷經歡騰、噤聲、反抗、和平，二十世紀前後，捷克與臺灣各自劃出筆力遒勁的墨跡。如果，你對捷克的印象是古堡、舊城、布拉格廣場，那麼，邀請你走進另一個圍繞著革命、流亡、打字機與地下刊物的世界，重新想像從壓抑走向奔放的捷克文學風景。', '國立臺灣文學館', '臺南市中西區中正路1號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '國立臺灣文學館', 22.992064, 120.203953, '無資料', 'https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=40096', '[]') ON DUPLICATE KEY UPDATE `activity_name`='打字機也會唱歌：捷克現當代文學展', `description`='捷克與臺灣，分別位於歐洲的中心與亞洲的邊陲，彼此距離超過了九千公里。然而，歷經歡騰、噤聲、反抗、和平，二十世紀前後，捷克與臺灣各自劃出筆力遒勁的墨跡。如果，你對捷克的印象是古堡、舊城、布拉格廣場，那麼，邀請你走進另一個圍繞著革命、流亡、打字機與地下刊物的世界，重新想像從壓抑走向奔放的捷克文學風景。', `organizer`='國立臺灣文學館', `address`='臺南市中西區中正路1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='國立臺灣文學館', `latitude`=22.992064, `longitude`=120.203953, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=40096', `image_url`='[]';
