INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6764760726b32458d4362f8e', '「台江傳奇－臺南400．海與陸的記憶」特展', '配合臺南400主題系列推出特展內容以台江處近年推動的「戲說台江」解說志工戲劇說演為藍本，從荷蘭人進入台江展開以商貿為基礎的統治開始，依序介紹鄭氏、清領、日治等時期台江內海及周邊地區的重大變化，藉由古地圖搭配人物插畫，引導民眾認識史蹟、產業與文化地景背後的由來與變化。展區也設計【古地圖大富翁】和【台江NO.1】等互動體驗遊戲，來深入認識荷蘭人曾經在台江內海的探勘軌跡，以及台江內海變化而帶動的聚落、產業與政治經濟影響。\r\n「台江傳奇－臺南400．海與陸的記憶」特展自113年10月30日起至114年3月30日止，於台江處遊客中心2F特展室展出，歡迎民眾前來參觀體驗一趟歷史縮時之旅，認識台江在臺灣歷史洪流中的關鍵角色與故事。', '台江國家公園管理處', '臺南市安南區', '2025-01-01 00:00:00', '2025-03-30 00:00:00', '安南區（臺南市）=', 23.04869681, 120.1526189, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「台江傳奇－臺南400．海與陸的記憶」特展', `description`='配合臺南400主題系列推出特展內容以台江處近年推動的「戲說台江」解說志工戲劇說演為藍本，從荷蘭人進入台江展開以商貿為基礎的統治開始，依序介紹鄭氏、清領、日治等時期台江內海及周邊地區的重大變化，藉由古地圖搭配人物插畫，引導民眾認識史蹟、產業與文化地景背後的由來與變化。展區也設計【古地圖大富翁】和【台江NO.1】等互動體驗遊戲，來深入認識荷蘭人曾經在台江內海的探勘軌跡，以及台江內海變化而帶動的聚落、產業與政治經濟影響。\r\n「台江傳奇－臺南400．海與陸的記憶」特展自113年10月30日起至114年3月30日止，於台江處遊客中心2F特展室展出，歡迎民眾前來參觀體驗一趟歷史縮時之旅，認識台江在臺灣歷史洪流中的關鍵角色與故事。', `organizer`='台江國家公園管理處', `address`='臺南市安南區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='安南區（臺南市）=', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
