INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676b305626b32458d4363133', '竹頭文學讀書會', '竹頭文學讀書會，讓我們了解傳統習俗於古典文化之中，讓我們從文學出發認識不同的在地文化，從中更了解我們腳下的這片土地。\r\n歡迎有興趣民眾報名，報名表單請至欣榮圖書館一樓服務台索取。', '財團法人福田文教基金會', '南投縣竹山鎮大勇路 26 號', '2025-01-11 00:00:00', '2025-12-13 00:00:00', '欣榮紀念圖書館暨玉蘭文化會館', 23.7569747, 120.6749408, '無資料', 'http://www.hsinrong.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='竹頭文學讀書會', `description`='竹頭文學讀書會，讓我們了解傳統習俗於古典文化之中，讓我們從文學出發認識不同的在地文化，從中更了解我們腳下的這片土地。\r\n歡迎有興趣民眾報名，報名表單請至欣榮圖書館一樓服務台索取。', `organizer`='財團法人福田文教基金會', `address`='南投縣竹山鎮大勇路 26 號', `start_date`='2025-01-11 00:00:00', `end_date`='2025-12-13 00:00:00', `location`='欣榮紀念圖書館暨玉蘭文化會館', `latitude`=23.7569747, `longitude`=120.6749408, `ticket_price`='無資料', `source_url`='http://www.hsinrong.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676b305626b32458d4363135', '易學文化讀書會', '易學文化讀書會在吳金忠老師帶領下，研討姓名學的重要性，如何兼顧姓名筆劃的天格、人格、地格、總格，又能顧及生肖中的習性，還有五行的相生相剋，面面俱到地擁有一個好的名字。歡迎有興趣民眾報名，報名表單請至欣榮圖書館一樓服務台索取。', '財團法人福田文教基金會', '南投縣竹山鎮大勇路 26 號', '2025-01-21 00:00:00', '2025-12-23 00:00:00', '欣榮紀念圖書館暨玉蘭文化會館', 23.7569747, 120.6749408, '無資料', 'http://www.hsinrong.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='易學文化讀書會', `description`='易學文化讀書會在吳金忠老師帶領下，研討姓名學的重要性，如何兼顧姓名筆劃的天格、人格、地格、總格，又能顧及生肖中的習性，還有五行的相生相剋，面面俱到地擁有一個好的名字。歡迎有興趣民眾報名，報名表單請至欣榮圖書館一樓服務台索取。', `organizer`='財團法人福田文教基金會', `address`='南投縣竹山鎮大勇路 26 號', `start_date`='2025-01-21 00:00:00', `end_date`='2025-12-23 00:00:00', `location`='欣榮紀念圖書館暨玉蘭文化會館', `latitude`=23.7569747, `longitude`=120.6749408, `ticket_price`='無資料', `source_url`='http://www.hsinrong.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676b305626b32458d4363137', '【跈水路．打先鋒(tenˇ suiˋ lu．daˋ xienˊfungˊ)】先鋒堆聚落展', '展覽地點：\r\n屏東縣萬巒鄉大我伙房 (屏東縣萬巒鄉五溝村西盛路46號)\r\n屏東縣萬巒鄉萬成祖堂 (屏東縣萬巒鄉五溝村西盛路36號)\r\n復脈園水果冰淇淋店門前廊(屏東縣萬巒鄉和路8號)\r\n\r\n東縣萬巒鄉不只有聞名全臺个豬腳，更是南臺灣六堆客家傳統聚落範圍-先鋒堆。為呈現先鋒堆客家庄多樣个特色，在策展過程，我們特別結合✔田野調查，並與✔在地居民集思廣益、共作共創，✨展現在這塊土地上所孕育出來个故事，要帶領大家認識你知道个萬巒，以及你可能不知道个萬巒。', '客家委員會客家文化發展中心', '屏東縣萬巒鄉', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '萬巒鄉（屏東縣）=', 22.58233459, 120.601817, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【跈水路．打先鋒(tenˇ suiˋ lu．daˋ xienˊfungˊ)】先鋒堆聚落展', `description`='展覽地點：\r\n屏東縣萬巒鄉大我伙房 (屏東縣萬巒鄉五溝村西盛路46號)\r\n屏東縣萬巒鄉萬成祖堂 (屏東縣萬巒鄉五溝村西盛路36號)\r\n復脈園水果冰淇淋店門前廊(屏東縣萬巒鄉和路8號)\r\n\r\n東縣萬巒鄉不只有聞名全臺个豬腳，更是南臺灣六堆客家傳統聚落範圍-先鋒堆。為呈現先鋒堆客家庄多樣个特色，在策展過程，我們特別結合✔田野調查，並與✔在地居民集思廣益、共作共創，✨展現在這塊土地上所孕育出來个故事，要帶領大家認識你知道个萬巒，以及你可能不知道个萬巒。', `organizer`='客家委員會客家文化發展中心', `address`='屏東縣萬巒鄉', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='萬巒鄉（屏東縣）=', `latitude`=22.58233459, `longitude`=120.601817, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
