INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676c7ae526b32458d4363141', '【守護精靈-地底人入侵】臺灣台語動畫', '*本片由文化部國家語言整體發展方案支持，全片使用臺灣台語配音，並使用臺灣台語及英文字幕。\n\n\n場次資訊 \n\n\n	場次:  開館時間，一天4場次。上午：10:00、11:00  下午：14:00、15:00\n	地點：本館3樓東側 環形劇場 (臺北市中正區襄陽路2號)\n	報名：現場排隊依序自由入座，每場次前5分鐘開放進場(09:55、10:55、13:55、14:55)。\n	影片開始及場內人數達40人即停止入場。\n	10點場次先播映本片，接續播映「康熙臺灣輿圖」系列動畫I「輿圖紀遊」、動畫II「北臺紀遊」、微觀視界，中間不換場。\n\n\n\n	觀影規則\n\n\n\n	體驗人數：40人/場。\n	對象：年齡不限，6歲建議需大人陪同。\n	影片長度：約8分鐘。\n	本影片為沉浸式影片，觀影過程中若有頭暈目眩等任何不適情形，建議停止觀影，並請現場工作人員提供協助。\n	影片開始播放請勿任意進出。\n	全場禁止飲食。\n	請遵守現場工作人員動線指示。\n\n\n\n	劇情簡介\n	「守護精靈-地底人入侵」動畫講述遊客對一直住在博物館裡的7隻守護精靈們，漸漸失去新鮮感，守護精靈們攪盡腦汁好不容易想出新的「招式」吸引觀眾的目光，沒想到竟然被不懷好意的神秘地底人破壞，面臨保護文物的重要挑戰。全片透過童趣的動畫風格及劇情向親子觀眾傳遞文化守護的價值。\n\n\n \n\n*本活動為文化部「培育台語家庭計畫」活動，登錄「台語學習家庭」或「台語文化家庭」的家庭觀眾觀賞「守護精靈-地底人入侵」臺灣台語動畫，即可參加集點，累積點數達20點，可獲得台語獎勵金，並參加抽獎。\n\n ', '國立臺灣博物館', '100  臺北市中正區中正區襄陽路2號(二二八公園內)', '2024-12-24 00:00:00', '2025-12-31 00:00:00', '臺博館本館3樓環形劇場', 25.0418254, 121.5149875, '無資料', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40288', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【守護精靈-地底人入侵】臺灣台語動畫', `description`='*本片由文化部國家語言整體發展方案支持，全片使用臺灣台語配音，並使用臺灣台語及英文字幕。\n\n\n場次資訊 \n\n\n	場次:  開館時間，一天4場次。上午：10:00、11:00  下午：14:00、15:00\n	地點：本館3樓東側 環形劇場 (臺北市中正區襄陽路2號)\n	報名：現場排隊依序自由入座，每場次前5分鐘開放進場(09:55、10:55、13:55、14:55)。\n	影片開始及場內人數達40人即停止入場。\n	10點場次先播映本片，接續播映「康熙臺灣輿圖」系列動畫I「輿圖紀遊」、動畫II「北臺紀遊」、微觀視界，中間不換場。\n\n\n\n	觀影規則\n\n\n\n	體驗人數：40人/場。\n	對象：年齡不限，6歲建議需大人陪同。\n	影片長度：約8分鐘。\n	本影片為沉浸式影片，觀影過程中若有頭暈目眩等任何不適情形，建議停止觀影，並請現場工作人員提供協助。\n	影片開始播放請勿任意進出。\n	全場禁止飲食。\n	請遵守現場工作人員動線指示。\n\n\n\n	劇情簡介\n	「守護精靈-地底人入侵」動畫講述遊客對一直住在博物館裡的7隻守護精靈們，漸漸失去新鮮感，守護精靈們攪盡腦汁好不容易想出新的「招式」吸引觀眾的目光，沒想到竟然被不懷好意的神秘地底人破壞，面臨保護文物的重要挑戰。全片透過童趣的動畫風格及劇情向親子觀眾傳遞文化守護的價值。\n\n\n \n\n*本活動為文化部「培育台語家庭計畫」活動，登錄「台語學習家庭」或「台語文化家庭」的家庭觀眾觀賞「守護精靈-地底人入侵」臺灣台語動畫，即可參加集點，累積點數達20點，可獲得台語獎勵金，並參加抽獎。\n\n ', `organizer`='國立臺灣博物館', `address`='100  臺北市中正區中正區襄陽路2號(二二八公園內)', `start_date`='2024-12-24 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺博館本館3樓環形劇場', `latitude`=25.0418254, `longitude`=121.5149875, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40288', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676c7ba526b32458d4363161', '行舟‧運河─中國大運河博物館沉浸式舟楫文化展', '佛光緣美術館將舉辦一場驚艷的文化展覽，帶您走進古代舟楫的世界！這次展覽由佛光山文教基金會、佛光緣美術館與中國大運河博物館攜手合作，讓您在台灣親身感受大運河的舟楫文化。\r\n中國大運河是一條連結千年的水上之路，縱貫南北，現被列為「世界文化遺產」。運河沿線船隻的頻繁往返，不僅促進了沿岸的經濟繁榮，也蘊含著豐厚的歷史內涵。被譽為中國大運河「百科全書」的揚州中國大運河博物館，首次來台與佛光山進行交流展出，將春秋至明清時期等25艘船隻模型，以「虛實結合」的方式，講述大運河上舟楫的類型、演變等故事，共分為四個部分—「乘風破浪」、「百舸爭流」、「萬象繁繪」、「沙飛船」，已多媒體展示手法，帶領觀眾感受大運河文化與歷史風貌之美。', '中華文物交流協會', '高雄市大樹區012鄰興田路153號', '2025-01-01 00:00:00', '2025-07-02 00:00:00', '佛光山寺', 23.0074152, 120.6639313, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='行舟‧運河─中國大運河博物館沉浸式舟楫文化展', `description`='佛光緣美術館將舉辦一場驚艷的文化展覽，帶您走進古代舟楫的世界！這次展覽由佛光山文教基金會、佛光緣美術館與中國大運河博物館攜手合作，讓您在台灣親身感受大運河的舟楫文化。\r\n中國大運河是一條連結千年的水上之路，縱貫南北，現被列為「世界文化遺產」。運河沿線船隻的頻繁往返，不僅促進了沿岸的經濟繁榮，也蘊含著豐厚的歷史內涵。被譽為中國大運河「百科全書」的揚州中國大運河博物館，首次來台與佛光山進行交流展出，將春秋至明清時期等25艘船隻模型，以「虛實結合」的方式，講述大運河上舟楫的類型、演變等故事，共分為四個部分—「乘風破浪」、「百舸爭流」、「萬象繁繪」、「沙飛船」，已多媒體展示手法，帶領觀眾感受大運河文化與歷史風貌之美。', `organizer`='中華文物交流協會', `address`='高雄市大樹區012鄰興田路153號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-07-02 00:00:00', `location`='佛光山寺', `latitude`=23.0074152, `longitude`=120.6639313, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676c7ba826b32458d4363168', 'MiMi電影院（114年3月） ', '歡迎大朋友小朋友一起來看電影。\r\n親子教室遊戲區及繪本區都會不定期更新上架新的玩具及繪本供大家借用及閱讀，歡迎大朋友、小朋友、家長前來一起參與。\r\n提醒：持有家庭卡的讀者，記得每月參加一次親子相關活動以利續卡。', '欣榮紀念圖書館暨玉蘭文化會館', '南投縣竹山鎮大勇路 26 號', '2025-03-01 00:00:00', '2025-03-15 00:00:00', '欣榮紀念圖書館暨玉蘭文化會館', 23.7569747, 120.6749408, '無資料', 'http://hsinrong.org/news.php', '[]') ON DUPLICATE KEY UPDATE `activity_name`='MiMi電影院（114年3月） ', `description`='歡迎大朋友小朋友一起來看電影。\r\n親子教室遊戲區及繪本區都會不定期更新上架新的玩具及繪本供大家借用及閱讀，歡迎大朋友、小朋友、家長前來一起參與。\r\n提醒：持有家庭卡的讀者，記得每月參加一次親子相關活動以利續卡。', `organizer`='欣榮紀念圖書館暨玉蘭文化會館', `address`='南投縣竹山鎮大勇路 26 號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='欣榮紀念圖書館暨玉蘭文化會館', `latitude`=23.7569747, `longitude`=120.6749408, `ticket_price`='無資料', `source_url`='http://hsinrong.org/news.php', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676c7ba826b32458d436316e', '經典電影院（114年3月）', '放映影片\r\n寂寞調想師\r\n她是Dior天價聘請的調香大師！他是唯一敢嗆她的魯蛇司機！描述司機吉翁的新客戶是擁有絕對嗅覺的調香大師，個性古怪又難搞，但為了女兒的監護官司，他退無可退，卻也因此開啟兩人的特殊情誼。\r\n\r\n波麗露狂想曲\r\n巴黎，咆哮的二十年代，編舞家伊達魯賓斯坦找來作曲家莫里斯拉威爾為她下一首芭蕾舞劇編曲，她希望風格大膽、露骨，然而，著名且聲望崇高的拉威爾發現自己寫不出任何曲子，在重溫回憶，面對舊情舊愛與失敗的過程中，作曲家將寫出他有史以來最膾炙人口的一首曲子「波麗露」。', '財團法人福田文教基金會', '南投縣竹山鎮大勇路 26 號', '2025-03-01 00:00:00', '2025-03-15 00:00:00', '欣榮紀念圖書館暨玉蘭文化會館', 23.7569747, 120.6749408, '無資料', 'https://www.facebook.com/profile.php?id=100064705267614', '[]') ON DUPLICATE KEY UPDATE `activity_name`='經典電影院（114年3月）', `description`='放映影片\r\n寂寞調想師\r\n她是Dior天價聘請的調香大師！他是唯一敢嗆她的魯蛇司機！描述司機吉翁的新客戶是擁有絕對嗅覺的調香大師，個性古怪又難搞，但為了女兒的監護官司，他退無可退，卻也因此開啟兩人的特殊情誼。\r\n\r\n波麗露狂想曲\r\n巴黎，咆哮的二十年代，編舞家伊達魯賓斯坦找來作曲家莫里斯拉威爾為她下一首芭蕾舞劇編曲，她希望風格大膽、露骨，然而，著名且聲望崇高的拉威爾發現自己寫不出任何曲子，在重溫回憶，面對舊情舊愛與失敗的過程中，作曲家將寫出他有史以來最膾炙人口的一首曲子「波麗露」。', `organizer`='財團法人福田文教基金會', `address`='南投縣竹山鎮大勇路 26 號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='欣榮紀念圖書館暨玉蘭文化會館', `latitude`=23.7569747, `longitude`=120.6749408, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064705267614', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676c7ba826b32458d436316f', '經典電影院（114年4月）', '放映影片\r\n杜巴利伯爵夫人\r\n年輕的工人階級女性珍妮·沃伯尼爾（麥溫 飾）渴望文化和快樂，用她的智慧和魅力逐步爬上社會階梯。她成爲國王路易十五（約翰尼·德普 飾）的寵兒，路易十五並不知道她的妓女身份，通過她重拾了對生活的渴望，他們瘋狂地墜入愛河。珍妮違背所有禮儀和禮節搬到凡爾賽宮，她的到來在宮廷中 引起了軒然大波……\r\n\r\n說不出的告別\r\n奧斯卡影后蘇珊莎蘭登飾演一名罹患漸凍症的母親，決定選擇安樂死結束多年來與病痛的抗爭，她和先生邀請兩位女兒凱特溫絲蕾、蜜雅娃絲柯思卡與好友一起共度週末，陪她走完人生最後一哩路，而面對母親的離別抉擇，家人彼此間的心結與祕密也逐一浮現。\r\n莉莉被診斷出患有運動神經疾病，身體每況愈下，因此她決定吞藥安樂死，獨自靜靜地離開這個世界。\r\n她告知家中每位成員，將大家重聚在一起共度週末。家人起初都支持莉莉這個艱難的決定，但隨著彼此相處，堆積的衝突被漸漸激發，家人間各自的秘密也被揭露…', '財團法人福田文教基金會', '南投縣竹山鎮大勇路 26 號', '2025-04-05 00:00:00', '2025-04-19 00:00:00', '欣榮紀念圖書館暨玉蘭文化會館', 23.7569747, 120.6749408, '無資料', 'https://www.facebook.com/profile.php?id=100064705267614', '[]') ON DUPLICATE KEY UPDATE `activity_name`='經典電影院（114年4月）', `description`='放映影片\r\n杜巴利伯爵夫人\r\n年輕的工人階級女性珍妮·沃伯尼爾（麥溫 飾）渴望文化和快樂，用她的智慧和魅力逐步爬上社會階梯。她成爲國王路易十五（約翰尼·德普 飾）的寵兒，路易十五並不知道她的妓女身份，通過她重拾了對生活的渴望，他們瘋狂地墜入愛河。珍妮違背所有禮儀和禮節搬到凡爾賽宮，她的到來在宮廷中 引起了軒然大波……\r\n\r\n說不出的告別\r\n奧斯卡影后蘇珊莎蘭登飾演一名罹患漸凍症的母親，決定選擇安樂死結束多年來與病痛的抗爭，她和先生邀請兩位女兒凱特溫絲蕾、蜜雅娃絲柯思卡與好友一起共度週末，陪她走完人生最後一哩路，而面對母親的離別抉擇，家人彼此間的心結與祕密也逐一浮現。\r\n莉莉被診斷出患有運動神經疾病，身體每況愈下，因此她決定吞藥安樂死，獨自靜靜地離開這個世界。\r\n她告知家中每位成員，將大家重聚在一起共度週末。家人起初都支持莉莉這個艱難的決定，但隨著彼此相處，堆積的衝突被漸漸激發，家人間各自的秘密也被揭露…', `organizer`='財團法人福田文教基金會', `address`='南投縣竹山鎮大勇路 26 號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='欣榮紀念圖書館暨玉蘭文化會館', `latitude`=23.7569747, `longitude`=120.6749408, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064705267614', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676c7ba926b32458d4363170', '經典電影院（114年5月）', '放映影片\r\n催眠\r\n過著充實大學生活的英文系學生都賢（李大衛 飾），偶然因爲轉學生振浩（金南優 飾）而對催眠產生興趣。都賢在崔教授（孫昞昊 飾）的幫助下接受了催眠治療，但在催眠體驗後，他卻開始看見充滿疑惑的記憶幻影，朋友們也一個接一個開始深受幻影折磨，而遭遇奇怪的事件。崔教授對他們催眠的目的究竟爲何？\r\n\r\n燕\r\n中日混血棄子Tsubame，飄洋過海來到這個母親說很美的地方，尋回自我認同的起點，體悟到失去的反而是收穫。Tsubame 五歲起和母親分隔兩地，直到成年後仍無法釋懷為何別離，即使是溫柔的繼母也不甚了解他的心思。在父親的懇求下，他前往母親的故鄉臺灣和失聯23 年的哥哥見面。在和哥哥的孩子相處過程中，他幾次回憶起童年時與母親相處的片刻，漸漸理解自己其實從未被拋下⋯⋯\r\n今村圭佑長期以攝影指導身份，與導演藤井道人合作，本片為其首部執導劇情長片，在高雄市取景，將南臺灣 的烈陽與港都的粼光融成一幅幅濃烈的光景，以為早已逝去的母愛，遂隨倦燕歸巢盈滿眼眶。導演藉由無所不 在的新住民母語議題，拆解族裔的區隔; 常民生活的街頭巷尾、嘈雜的市集和靜默的墓地，似是異鄉的故鄉， 最是魔幻寫實的成長敘事。', '財團法人福田文教基金會', '南投縣竹山鎮大勇路 26 號', '2025-05-03 00:00:00', '2025-05-17 00:00:00', '欣榮紀念圖書館暨玉蘭文化會館', 23.7569747, 120.6749408, '無資料', 'https://www.facebook.com/profile.php?id=100064705267614', '[]') ON DUPLICATE KEY UPDATE `activity_name`='經典電影院（114年5月）', `description`='放映影片\r\n催眠\r\n過著充實大學生活的英文系學生都賢（李大衛 飾），偶然因爲轉學生振浩（金南優 飾）而對催眠產生興趣。都賢在崔教授（孫昞昊 飾）的幫助下接受了催眠治療，但在催眠體驗後，他卻開始看見充滿疑惑的記憶幻影，朋友們也一個接一個開始深受幻影折磨，而遭遇奇怪的事件。崔教授對他們催眠的目的究竟爲何？\r\n\r\n燕\r\n中日混血棄子Tsubame，飄洋過海來到這個母親說很美的地方，尋回自我認同的起點，體悟到失去的反而是收穫。Tsubame 五歲起和母親分隔兩地，直到成年後仍無法釋懷為何別離，即使是溫柔的繼母也不甚了解他的心思。在父親的懇求下，他前往母親的故鄉臺灣和失聯23 年的哥哥見面。在和哥哥的孩子相處過程中，他幾次回憶起童年時與母親相處的片刻，漸漸理解自己其實從未被拋下⋯⋯\r\n今村圭佑長期以攝影指導身份，與導演藤井道人合作，本片為其首部執導劇情長片，在高雄市取景，將南臺灣 的烈陽與港都的粼光融成一幅幅濃烈的光景，以為早已逝去的母愛，遂隨倦燕歸巢盈滿眼眶。導演藉由無所不 在的新住民母語議題，拆解族裔的區隔; 常民生活的街頭巷尾、嘈雜的市集和靜默的墓地，似是異鄉的故鄉， 最是魔幻寫實的成長敘事。', `organizer`='財團法人福田文教基金會', `address`='南投縣竹山鎮大勇路 26 號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='欣榮紀念圖書館暨玉蘭文化會館', `latitude`=23.7569747, `longitude`=120.6749408, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064705267614', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676c7ba926b32458d4363171', '經典電影院（114年6月）', '放映影片\r\n鋼琴師\r\n改編自澳洲著名鋼琴家大衛赫夫考(David Helfgott)的真人真事。本片故事呈現天才兒童的悲慘童年，同時大膽揭露父子間的愛與恨。\r\n出生在猶太家庭的大衛，從小在父親嚴厲的管教下學習鋼琴，父親把他對音樂的狂熱完全轉嫁到兒子身上，幸運的是大衛從小就顯露他過人的音樂天分，更是父親的驕傲。\r\n少年大衛在一次比賽中贏得由美國著名音樂家艾賽克史坦提供的獎學金，可以到美國進修。正當大家都為大衛高興之際，大衛的父親，卻沈著一張臉，最後宣布他兒子不去了！全然未曾理會大衛的意願，更不顧他的反對，他說了就算了。不久，英國皇家音樂學院，願意提供更好的條件給這位難得的天才進修機會，這回，大衛不顧一切，與父親決裂，隻身來到英國倫敦求學。可是他的天分雖然得到教授們的賞識，大衛與父親的決裂，卻在他心中留下無法抹滅的陰影。\r\n一日，他完成高難度的拉赫曼尼亞諾夫第三號鋼琴協奏曲後，緊繃的精神終於潰堤……\r\n回到澳洲後，大衛的父親十分不能諒解他，甚至覺得自己的兒子怎麼這麼丟臉。十年來，大衛就這麼在精神病院度日，一直到一天，在一個偶然的機會下，得到善心人士的幫助，讓他重新接觸鋼琴，更遇到他現任妻子，而在妻子的協助下，他終於可以重新回到表演舞台上。\r\n\r\n以愛之茗\r\n來自象牙海岸的女子愛亞，在婚禮上悔婚後來到異地展開新生活。他在一處中、非文化融合的區域邂逅了茶行老闆王材（張翰），並在王材教導他品茶這門藝術的過程中，發展出了一段曖昧情愫。為了正視彼此的情意，他們必須先放下包袱、直面各自不願提及的過去…', '財團法人福田文教基金會', '南投縣竹山鎮大勇路 26 號', '2025-06-07 00:00:00', '2025-06-21 00:00:00', '欣榮紀念圖書館暨玉蘭文化會館', 23.7569747, 120.6749408, '無資料', 'https://www.facebook.com/profile.php?id=100064705267614', '[]') ON DUPLICATE KEY UPDATE `activity_name`='經典電影院（114年6月）', `description`='放映影片\r\n鋼琴師\r\n改編自澳洲著名鋼琴家大衛赫夫考(David Helfgott)的真人真事。本片故事呈現天才兒童的悲慘童年，同時大膽揭露父子間的愛與恨。\r\n出生在猶太家庭的大衛，從小在父親嚴厲的管教下學習鋼琴，父親把他對音樂的狂熱完全轉嫁到兒子身上，幸運的是大衛從小就顯露他過人的音樂天分，更是父親的驕傲。\r\n少年大衛在一次比賽中贏得由美國著名音樂家艾賽克史坦提供的獎學金，可以到美國進修。正當大家都為大衛高興之際，大衛的父親，卻沈著一張臉，最後宣布他兒子不去了！全然未曾理會大衛的意願，更不顧他的反對，他說了就算了。不久，英國皇家音樂學院，願意提供更好的條件給這位難得的天才進修機會，這回，大衛不顧一切，與父親決裂，隻身來到英國倫敦求學。可是他的天分雖然得到教授們的賞識，大衛與父親的決裂，卻在他心中留下無法抹滅的陰影。\r\n一日，他完成高難度的拉赫曼尼亞諾夫第三號鋼琴協奏曲後，緊繃的精神終於潰堤……\r\n回到澳洲後，大衛的父親十分不能諒解他，甚至覺得自己的兒子怎麼這麼丟臉。十年來，大衛就這麼在精神病院度日，一直到一天，在一個偶然的機會下，得到善心人士的幫助，讓他重新接觸鋼琴，更遇到他現任妻子，而在妻子的協助下，他終於可以重新回到表演舞台上。\r\n\r\n以愛之茗\r\n來自象牙海岸的女子愛亞，在婚禮上悔婚後來到異地展開新生活。他在一處中、非文化融合的區域邂逅了茶行老闆王材（張翰），並在王材教導他品茶這門藝術的過程中，發展出了一段曖昧情愫。為了正視彼此的情意，他們必須先放下包袱、直面各自不願提及的過去…', `organizer`='財團法人福田文教基金會', `address`='南投縣竹山鎮大勇路 26 號', `start_date`='2025-06-07 00:00:00', `end_date`='2025-06-21 00:00:00', `location`='欣榮紀念圖書館暨玉蘭文化會館', `latitude`=23.7569747, `longitude`=120.6749408, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064705267614', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676c7ba926b32458d4363181', '兒童芭蕾小教室＆英文小教室（114年1-3月）', '兒童芭蕾小教室\r\n授課講師：謝姵寧\r\n本活動以故事的方式帶入芭蕾課程，帶領小朋友學習基礎的芭蕾動作。\r\n對象：幼兒園至國小低年級學童15人。\r\n\r\n英文小教室\r\n授課講師：汪宥穎\r\n本活動開設主題式英文學習課程，讓學童從遊戲過程中學習日常的英文對話。\r\n對象：國小一至六年級學童15人。\r\n\r\n活動洽詢：049-2637666欣榮圖書館。', '財團法人福田文教基金會', '南投縣竹山鎮大勇路 26 號', '2025-01-05 00:00:00', '2025-03-23 00:00:00', '欣榮紀念圖書館暨玉蘭文化會館', 23.7569747, 120.6749408, '無資料', 'http://www.hsinrong.org', '[]') ON DUPLICATE KEY UPDATE `activity_name`='兒童芭蕾小教室＆英文小教室（114年1-3月）', `description`='兒童芭蕾小教室\r\n授課講師：謝姵寧\r\n本活動以故事的方式帶入芭蕾課程，帶領小朋友學習基礎的芭蕾動作。\r\n對象：幼兒園至國小低年級學童15人。\r\n\r\n英文小教室\r\n授課講師：汪宥穎\r\n本活動開設主題式英文學習課程，讓學童從遊戲過程中學習日常的英文對話。\r\n對象：國小一至六年級學童15人。\r\n\r\n活動洽詢：049-2637666欣榮圖書館。', `organizer`='財團法人福田文教基金會', `address`='南投縣竹山鎮大勇路 26 號', `start_date`='2025-01-05 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='欣榮紀念圖書館暨玉蘭文化會館', `latitude`=23.7569747, `longitude`=120.6749408, `ticket_price`='無資料', `source_url`='http://www.hsinrong.org', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676c7ba926b32458d4363182', '樂齡國畫班—現代水墨畫(1月至3月)', '由參與的樂齡學員自行臨摹或創作水墨畫作，由老師一一修改指導及示範，從教導筆墨及色彩運用技巧，到深入理解國畫概念，培養審美規律，學會墨與色的和諧。', '高雄市立圖書館總館', '高雄市岡山區009鄰岡山南路42號', '2025-01-07 00:00:00', '2025-03-25 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樂齡國畫班—現代水墨畫(1月至3月)', `description`='由參與的樂齡學員自行臨摹或創作水墨畫作，由老師一一修改指導及示範，從教導筆墨及色彩運用技巧，到深入理解國畫概念，培養審美規律，學會墨與色的和諧。', `organizer`='高雄市立圖書館總館', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-01-07 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
