INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc90826b32458d43631ac', '《〝請說國語〞？！戰後語言政策與人權議題》特展', '展期：\n2024/12/23-114/08/31\n\n地點：\n白色恐怖景美紀念園區-兵舍五\n\n活動內容介紹：\n臺灣語言政策發展經歷日本殖民統治（1895–1945）、威權統治（1945–1992）的兩次「國語運動」，透過教育、政策、法規等，深入民眾的日常生活，壓抑了本土語言的發展。本展覽分為六個單元，包含「日治時期國語運動」、「在學校說國語，學ㄅㄆㄇㄈ」、「受到語言政策壓迫的白恐政治受難者」、「『母語』被禁的日常」、「我的語言日常」、「社會運動帶動母語保存文化」、「大家一起保護母語」等內容，利用沉浸式場景、實體文物及影像、聲音及互動體驗等，回顧過往不同時代下的語言政策及影響，深化社會對話，具體實踐語言平權與轉型正義。\n\n ', '國家人權博物館', '無資料', '2024-12-24 00:00:00', '2025-08-31 00:00:00', '無資料', 0, 0, '無資料', 'https://event.culture.tw/mocweb/reg/NHRM/Detail.init.ctr?actId=40062', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《〝請說國語〞？！戰後語言政策與人權議題》特展', `description`='展期：\n2024/12/23-114/08/31\n\n地點：\n白色恐怖景美紀念園區-兵舍五\n\n活動內容介紹：\n臺灣語言政策發展經歷日本殖民統治（1895–1945）、威權統治（1945–1992）的兩次「國語運動」，透過教育、政策、法規等，深入民眾的日常生活，壓抑了本土語言的發展。本展覽分為六個單元，包含「日治時期國語運動」、「在學校說國語，學ㄅㄆㄇㄈ」、「受到語言政策壓迫的白恐政治受難者」、「『母語』被禁的日常」、「我的語言日常」、「社會運動帶動母語保存文化」、「大家一起保護母語」等內容，利用沉浸式場景、實體文物及影像、聲音及互動體驗等，回顧過往不同時代下的語言政策及影響，深化社會對話，具體實踐語言平權與轉型正義。\n\n ', `organizer`='國家人權博物館', `address`='無資料', `start_date`='2024-12-24 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NHRM/Detail.init.ctr?actId=40062', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc90c26b32458d43631ae', '【SOS：未來戰士出動！】闖關活動', '未來戰士需要你的幫忙！臺博館誠摯邀請大朋友、小朋友，一起成為未來戰士，參與拯救地球的闖關體驗！在任務中，你將解鎖平常的食衣住行用品從哪裡來？地球上的空氣、土地、水資源，以及其他生物正面臨什麼挑戰？跟著導覽員的腳步，深入博物館中完成訓練挑戰，以不同視角認識地球危機，理解環境永續的重要性，並從行動中為地球未來注入更多希望！快來加入未來戰士的行列吧！記得戴上專屬的保衛星球工具(手機/平板)哦！\n\n \n\n🦸‍♀️ 活動對象：\n\n\n	班級場(平日)：國小中年級以上學生，以國小學校班級為申請單位\n	親子場(假日)：親子家庭觀眾20名/場，請依實際參與人數報名(如1位家長、1位兒童請報名2個名額)，建議國小1年級以上參與\n\n\n🚀 活動地點：南門館紅樓展示館2樓。請於活動前10分鐘於服務台完成購票並報到。\n\n🦸‍♀️  活動費用：活動免費，需購票入館。班級團體超過20人為半票優惠。\n\n🚀 報名方式：於臺博官網線上報名。\n\n🦸‍♀️  活動流程：分組及活動介紹(10分鐘)→展場導覽(20分鐘)→互動體驗闖關(30分鐘)，共1小時。\n\n   \n\n🚀 活動場次與時間：\n\n1. 113學年度第二學期班級體驗場次（平日）：\n\n\n	2025/2/11(二)開學起至6/30(一)，每月2場，二上午或四下午。\n	每場次1小時，可依照班級時間協調。\n	闖關體驗為分組進行，1組建議4-5人。\n	本館可提供3台平板，若超過3組請自備平板/手機等互動載具。\n\n\n\n	\n		\n			星期\n			 日期\n			   區間時段\n		\n		\n			二\n			 2/11、3/11、4/8、5/6、6/10\n			上午0930-1200\n		\n		\n			四\n			 2/27、3/27、4/24、5/22、6/26\n			下午1400-1600\n		\n	\n\n\n \n\n2. 親子家庭體驗場次（假日）：\n\n\n	每月1場，週六下午，每場次一小時。\n	日期：1/25、2/22、3/29、4/26、5/31、6/28、7/26、8/30\n\n\n \n\n🦸‍♀️  活動講師：本館教育推廣助理\n\n\n\n \n\n \n\n ', '國立臺灣博物館', '中正區南昌路一段1號', '2025-02-27 00:00:00', '2025-08-30 00:00:00', '臺博館南門館', 25.0331483, 121.5159774, '活動免費，需購票入館。團體20人以上半票優惠。', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40289', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【SOS：未來戰士出動！】闖關活動', `description`='未來戰士需要你的幫忙！臺博館誠摯邀請大朋友、小朋友，一起成為未來戰士，參與拯救地球的闖關體驗！在任務中，你將解鎖平常的食衣住行用品從哪裡來？地球上的空氣、土地、水資源，以及其他生物正面臨什麼挑戰？跟著導覽員的腳步，深入博物館中完成訓練挑戰，以不同視角認識地球危機，理解環境永續的重要性，並從行動中為地球未來注入更多希望！快來加入未來戰士的行列吧！記得戴上專屬的保衛星球工具(手機/平板)哦！\n\n \n\n🦸‍♀️ 活動對象：\n\n\n	班級場(平日)：國小中年級以上學生，以國小學校班級為申請單位\n	親子場(假日)：親子家庭觀眾20名/場，請依實際參與人數報名(如1位家長、1位兒童請報名2個名額)，建議國小1年級以上參與\n\n\n🚀 活動地點：南門館紅樓展示館2樓。請於活動前10分鐘於服務台完成購票並報到。\n\n🦸‍♀️  活動費用：活動免費，需購票入館。班級團體超過20人為半票優惠。\n\n🚀 報名方式：於臺博官網線上報名。\n\n🦸‍♀️  活動流程：分組及活動介紹(10分鐘)→展場導覽(20分鐘)→互動體驗闖關(30分鐘)，共1小時。\n\n   \n\n🚀 活動場次與時間：\n\n1. 113學年度第二學期班級體驗場次（平日）：\n\n\n	2025/2/11(二)開學起至6/30(一)，每月2場，二上午或四下午。\n	每場次1小時，可依照班級時間協調。\n	闖關體驗為分組進行，1組建議4-5人。\n	本館可提供3台平板，若超過3組請自備平板/手機等互動載具。\n\n\n\n	\n		\n			星期\n			 日期\n			   區間時段\n		\n		\n			二\n			 2/11、3/11、4/8、5/6、6/10\n			上午0930-1200\n		\n		\n			四\n			 2/27、3/27、4/24、5/22、6/26\n			下午1400-1600\n		\n	\n\n\n \n\n2. 親子家庭體驗場次（假日）：\n\n\n	每月1場，週六下午，每場次一小時。\n	日期：1/25、2/22、3/29、4/26、5/31、6/28、7/26、8/30\n\n\n \n\n🦸‍♀️  活動講師：本館教育推廣助理\n\n\n\n \n\n \n\n ', `organizer`='國立臺灣博物館', `address`='中正區南昌路一段1號', `start_date`='2025-02-27 00:00:00', `end_date`='2025-08-30 00:00:00', `location`='臺博館南門館', `latitude`=25.0331483, `longitude`=121.5159774, `ticket_price`='活動免費，需購票入館。團體20人以上半票優惠。', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40289', `image_url`='[]';
