INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91826b32458d43631b6', '525插花進階甲班(陳惠卿)', '講解並示範插作各式盆花、新娘捧花、花束、盆栽組合及會場佈置，並講解色彩學、空間美學之運用，以提昇學員的創作能力，更將全球流行之花藝資訊導入課程中，除美化家庭外，並以系統化方式培訓花藝設計師。（花材費用每堂約350元）\n\n\n\n \n\n ', '臺北市藝文推廣處', '103  臺北市大同區台北市大同區迪化街一段21號(大稻埕戲苑)', '2025-03-07 00:00:00', '2025-06-27 00:00:00', '大稻埕戲苑805教室', 25.0546733, 121.5103045, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40243', '[]') ON DUPLICATE KEY UPDATE `activity_name`='525插花進階甲班(陳惠卿)', `description`='講解並示範插作各式盆花、新娘捧花、花束、盆栽組合及會場佈置，並講解色彩學、空間美學之運用，以提昇學員的創作能力，更將全球流行之花藝資訊導入課程中，除美化家庭外，並以系統化方式培訓花藝設計師。（花材費用每堂約350元）\n\n\n\n \n\n ', `organizer`='臺北市藝文推廣處', `address`='103  臺北市大同區台北市大同區迪化街一段21號(大稻埕戲苑)', `start_date`='2025-03-07 00:00:00', `end_date`='2025-06-27 00:00:00', `location`='大稻埕戲苑805教室', `latitude`=25.0546733, `longitude`=121.5103045, `ticket_price`='2000', `source_url`='https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40243', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91826b32458d43631b7', '237 京劇生、旦基本功班(李佳麒 陳長燕)', '喜愛京劇傳統藝術的朋友們，歡迎來大稻埕藝研班加入練習基本功，您們會有不一樣的身體訓練，藉由京劇基本功身段功架及腿部訓練，來學習不一樣京劇傳統藝術，期待大家的到來。\n \n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱：京劇生、旦基本功班  (編號：237)教師：李佳麒、陳長燕            \n			\n		\n		\n			\n			教學目標\n\n			及\n\n			教學內容\n			\n			\n			親臨體驗，體現自身藝術魅力。\n\n			由戲曲基本功腿功身段亮相都來自於手眼身法步的身體記憶。\n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			 \n			\n			\n			生旦 壓腿 踢腿 山膀正反雲手等等 旦行 學習水袖及扇子等。\n\n			 \n\n			生行 學習槍花 起霸 膛馬身段組合練習   滾動式循序漸進。\n			\n		\n		\n			\n			第2堂課\n			\n			\n			 \n			\n			\n			生旦 壓腿 踢腿 山膀正反雲手等等 旦行 學習水袖及扇子等。\n\n			 \n\n			生行 學習槍花 起霸 膛馬身段組合練習   滾動式循序漸進。\n			\n		\n		\n			\n			第3堂課\n			\n			\n			 \n			\n			\n			生旦 壓腿 踢腿 山膀正反雲手等等 旦行 學習水袖及扇子等。\n\n			 \n\n			生行 學習槍花 起霸 膛馬身段組合練習   滾動式循序漸進。\n			\n		\n		\n			\n			第4堂課\n			\n			\n			 \n			\n			\n			生旦 壓腿 踢腿 山膀正反雲手等等 旦行 學習水袖及扇子等。\n\n			 \n\n			生行 學習槍花 起霸 膛馬身段組合練習   滾動式循序漸進。\n			\n		\n		\n			\n			第5堂課\n			\n			\n			 \n			\n			\n			生旦 壓腿 踢腿 山膀正反雲手等等 旦行 學習水袖及扇子等。\n\n			 \n\n			生行 學習槍花 起霸 膛馬身段組合練習   滾動式循序漸進。\n			\n		\n		\n			\n			第6堂課\n			\n			\n			 \n			\n			\n			生旦 壓腿 踢腿 山膀正反雲手等等 旦行 學習水袖及扇子等。\n\n			 \n\n			生行 學習槍花 起霸 膛馬身段組合練習  滾動式循序漸進。\n			\n		\n		\n			\n			第7堂課\n			\n			\n			 \n			\n			\n			生旦 壓腿 踢腿 山膀正反雲手等等 旦行 學習水袖及扇子等。\n\n			 \n\n			生行 學習槍花 起霸 膛馬身段組合練習   滾動式循序漸進。\n			\n		\n		\n			\n			第8堂課\n			\n			\n			 \n			\n			\n			生旦 壓腿 踢腿 山膀正反雲手等等 旦行 學習水袖及扇子等。\n\n			 \n\n			生行 學習槍花 起霸 膛馬身段組合練習   滾動式循序漸進。\n			\n		\n		\n			\n			第9堂課\n			\n			\n			 \n			\n			\n			生旦 壓腿 踢腿 山膀正反雲手等等 旦行 學習水袖及扇子等。\n\n			 \n\n			生行 學習槍花 起霸 膛馬身段組合練習  滾動式 循序漸進。\n			\n		\n		\n			\n			第10堂課\n			\n			\n			 \n			\n			\n			生旦 壓腿 踢腿 山膀正反雲手等等 旦行 學習水袖及扇子等。\n\n			 \n\n			生行 學習槍花 起霸 膛馬身段組合練習  滾動式循序漸進。\n			\n		\n		\n			\n			第11堂課\n		