INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91826b32458d43631b8', '331民俗音樂歌謠初級班-胡琴、月琴快樂學 (吳榮燦/林麗華)', '1.樂理介紹、節奏分析、歌唱咬字訓練、讀譜視唱教學。2.教唱：臺灣福佬系音樂、民謠與歌仔戲音樂、世紀經典金曲-國臺語懷念新老歌。3.樂器教學：二胡、月琴、殼仔弦、大廣弦等樂器，學習自拉自彈自唱的伴奏技巧與現場表演。(新、舊生教材200元)(樂器可班級團體訂購)\n\n \n\n \n\n\n\n中國文化大學\n曉峰音樂廳演出\n二胡：吳榮燦老師\n月琴：林麗華老師\n曲名：望春風\n作詞：李臨秋\n\nhttps://youtu.be/-b-Z5Gc0fyc\n\n \n\n中國文化大學\n曉峰音樂廳演出\n二胡：吳榮燦老師\n月琴：林麗華老師\n曲名：小城故事\n作詞：莊奴\n作曲：湯尼\nhttps://youtu.be/2lfIioPfMkk', '臺北市藝文推廣處', '103  臺北市大同區區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-05 00:00:00', '2025-06-11 00:00:00', '大稻埕戲苑801教室', 25.06342433, 121.5130417, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40245', '[]') ON DUPLICATE KEY UPDATE `activity_name`='331民俗音樂歌謠初級班-胡琴、月琴快樂學 (吳榮燦/林麗華)', `description`='1.樂理介紹、節奏分析、歌唱咬字訓練、讀譜視唱教學。2.教唱：臺灣福佬系音樂、民謠與歌仔戲音樂、世紀經典金曲-國臺語懷念新老歌。3.樂器教學：二胡、月琴、殼仔弦、大廣弦等樂器，學習自拉自彈自唱的伴奏技巧與現場表演。(新、舊生教材200元)(樂器可班級團體訂購)\n\n \n\n \n\n\n\n中國文化大學\n曉峰音樂廳演出\n二胡：吳榮燦老師\n月琴：林麗華老師\n曲名：望春風\n作詞：李臨秋\n\nhttps://youtu.be/-b-Z5Gc0fyc\n\n \n\n中國文化大學\n曉峰音樂廳演出\n二胡：吳榮燦老師\n月琴：林麗華老師\n曲名：小城故事\n作詞：莊奴\n作曲：湯尼\nhttps://youtu.be/2lfIioPfMkk', `organizer`='臺北市藝文推廣處', `address`='103  臺北市大同區區迪化街一段21號8樓(大稻埕戲苑)', `start_date`='2025-03-05 00:00:00', `end_date`='2025-06-11 00:00:00', `location`='大稻埕戲苑801教室', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='2000', `source_url`='https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40245', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91826b32458d43631b9', '336歌仔戲戊班 (李靜芳/周煌翔)', '課程以歌仔戲基本唱腔、身段為主軸，編寫適合學員程度的戲碼，以戲帶功加強學員的「唱唸做表」。課堂上會適度示範講解外台戲或內台公演的套路，讓學員能吸收到各種不同的表演型態。\n\n ', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-05 00:00:00', '2025-06-11 00:00:00', '大稻埕戲苑排練室二教室', 25.06342433, 121.5130417, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40247', '[]') ON DUPLICATE KEY UPDATE `activity_name`='336歌仔戲戊班 (李靜芳/周煌翔)', `description`='課程以歌仔戲基本唱腔、身段為主軸，編寫適合學員程度的戲碼，以戲帶功加強學員的「唱唸做表」。課堂上會適度示範講解外台戲或內台公演的套路，讓學員能吸收到各種不同的表演型態。\n\n ', `organizer`='臺北市藝文推廣處', `address`='103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', `start_date`='2025-03-05 00:00:00', `end_date`='2025-06-11 00:00:00', `location`='大稻埕戲苑排練室二教室', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='2000', `source_url`='https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40247', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91826b32458d43631ba', '421茶藝班 (唐文菁)', '大稻埕戲苑茶藝班交受六大茶類相關知識，每學期著重練習茶品沖泡，用不同的手法沖泡不同的茶品，品味茶湯的美味，與茶對話，用心感受身心的變化，從練習過程中養成茶人風範，寧靜、沉穩、敏銳、細膩。\n教師唐文菁具有十三年教學經驗、茶會、茶活動主辦資歷，歡迎報名，一起走在學茶的路上。(教材費約300元)\n\n\n教師介紹\n【茶藝春秋】茶道工作室  唐文菁\n十三年授課及豐富的茶會經驗\n詩人藝術家德亮文化工作室助理\n海峽兩岸第一屆茶藝技師\n2016年廈門東方茶席邀請賽金獎\n【普洱講堂】【茶藝春秋】【臺北市藝文推廣處大稻埕戲苑】指導老師\n曾任中華國際無我茶會常務理事\n曾任泡茶師聯會理事\n第五屆臺北市茶藝促進會理事長\n第五屆臺北市茶藝促進會理事長     \n第十四屆中華茶藝獎南區評審\n \n看似安靜的茶席，看似簡單的舉止，猶如清晨的湖面，清新自然，連呼吸都可以感受到空氣中似有若無，水的清香。\n行茶的歷程，忽如竹爐水沸，忽如壺起杯落，彷彿有風拂過待開的蓮花，水面下小魚兒躍起漣漪，甦醒的生命們趕在陽光照射之前用快慢交疊的節奏穿出水面，衝破寧靜，交流着迎接清晨的愉悅心情。\n在一動一靜間，茶湯昇華著精神氣，猶如朝霞般照亮湖面，輝映茶人的臉龐，於是茶湯的溫度點燃了茶人的生命。\n\n \n\n ', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-06 00:00:00', '2025-06-19 00:00:00', '大稻埕戲苑801教室', 25.06342433, 121.5130417, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40248', '[]') ON DUPLICATE KEY UPDATE `activity_name`='421茶藝班 (唐文菁)', `description`='大稻埕戲苑茶藝班交受六大茶類相關知識，每學期著重練習茶品沖泡，用不同的手法沖泡不同的茶品，品味茶湯的美味，與茶對話，用心感受身心的變化，從練習過程中養成茶人風範，寧靜、沉穩、敏銳、細膩。\n教師唐文菁具有十三年教學經驗、茶會、茶活動主辦資歷，歡迎報名，一起走在學茶的路上。(教材費約300元)\n\n\n教師介紹\n【茶藝春秋】茶道工作室  唐文菁\n十三年授課及豐富的茶會經驗\n詩人藝術家德亮文化工作室助理\n海峽兩岸第一屆茶藝技師\n2016年廈門東方茶席邀請賽金獎\n【普洱講堂】【茶藝春秋】【臺北市藝文推廣處大稻埕戲苑】指導老師\n曾任中華國際無我茶會常務理事\n曾任泡茶師聯會理事\n第五屆臺北市茶藝促進會理事長\n第五屆臺北市茶藝促進會理事長     \n第十四屆中華茶藝獎南區評審\n \n看似安靜的茶席，看似簡單的舉止，猶如清晨的湖面，清新自然，連呼吸都可以感受到空氣中似有若無，水的清香。\n行茶的歷程，忽如竹爐水沸，忽如壺起杯落，彷彿有風拂過待開的蓮花，水面下小魚兒躍起漣漪，甦醒的生命們趕在陽光照射之前用快慢交疊的節奏穿出水面，衝破寧靜，交流着迎接清晨的愉悅心情。\n在一動一靜間，茶湯昇華著精神氣，猶如朝霞般照亮湖面，輝映茶人的臉龐，於是茶湯的溫度點燃了茶人的生命。\n\n \n\n ', `organizer`='臺北市藝文推廣處', `address`='103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', `start_date`='2025-03-06 00:00:00', `end_date`='2025-06-19 00:00:00', `location`='大稻埕戲苑801教室', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='2000', `source_url`='https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40248', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91826b32458d43631bc', '436 客家戲班(鄭榮興/劉姿吟 )', ' \n\n客家戲為臺灣本土戲曲劇種之一，其劇種內涵不僅擁有豐富的文化特色，更有具「九腔十八調」之稱的多樣唱腔。本課程以實現客家戲曲舞台表演為目標，從入門基礎進而至舞台粉墨登場，引領大眾感受客家戲曲之美。\n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱：客家戲班           (編號：436 )教師：鄭榮興、劉姿吟\n			\n		\n		\n			\n			教學目標\n\n			及\n\n			教學內容\n			\n			\n			推廣客家戲曲，傳承客家戲曲表演藝術。\n\n			透過客家戲曲唱腔、表演身段做為課程基礎，進而至客家戲傳統劇目學習，呈現完整的客家戲演出。\n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/6\n			\n			\n			客家戲曲介紹及賞析\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/13\n			\n			\n			客家戲基礎唱腔介紹及教學\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/20\n			\n			\n			客家戲初階身段介紹及教學\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/27\n			\n			\n			客家戲曲劇目擬定及劇本導讀\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/10\n			\n			\n			客家戲生角行當介紹及教學\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/17\n			\n			\n			客家戲旦角行當介紹及教學\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/24\n			\n			\n			客家戲丑角行當介紹及教學\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5/1\n			\n			\n			客家戲曲劇目唱腔練習\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5/15\n			\n			\n			客家戲曲劇本加強導讀\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/22\n			\n			\n			客家戲曲角色身段學習\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/29\n			\n			\n			客家戲曲角色身段學習\n			\n		\n		\n			\n			第12堂課\n			\n			\n			6/5\n			\n			\n			客家戲曲劇目身段排演\n			\n		\n		\n			\n			第13堂課\n			\n			\n			6/12\n			\n			\n			客家戲曲劇目身段排演\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/19\n			\n			\n			客家戲曲劇目身段排演\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/26\n			\n			\n			學習成果總複習', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-06 00:00:00', '2025-06-19 00:00:00', '大稻埕戲苑排練室二教室', 25.06342433, 121.5130417, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40250', '[]') ON DUPLICATE KEY UPDATE `activity_nam