INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91826b32458d43631bd', '437 古箏進階班(黃熒熒)', '本班授課採合班上課，分組教學，個別訂正。教材內容涵蓋古箏傳統流派箏曲及通俗樂曲、重奏樂曲，期待箏樂以多風貌形態呈現。\n(新生材料費約250，舊生教材費300元，可自行購買或由班長代購)\n\n \n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱：古箏進階班        (編號：437)  教師：  黃熒熒   \n			\n		\n		\n			\n			教學目標\n\n			及\n\n			教學內容\n			\n			\n			箏為中華民族傳統樂器，音色清鑠典雅，可怡情冶性，亦可作學術研究，本著藝術向下紮根的理念，期待愛箏者因學習傳統流派及現代編創的古箏樂曲，達到陶冶身心靈和藝術教化人心的成效。\n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			114.03.16\n			\n			\n			1.始業式：(1)分配上課用箏(2)安排學員座位(3)學員須知宣導\n\n			浙江箏曲教學－雪山春曉(一)\n			\n		\n		\n			\n			第2堂課\n			\n			\n			114.03.13\n			\n			\n			浙江箏曲教學－雪山春曉(二)\n			\n		\n		\n			\n			第3堂課\n			\n			\n			114.03.20\n			\n			\n			浙江箏曲教學－雪山春曉(三)\n			\n		\n		\n			\n			第4堂課\n			\n			\n			114.03.27\n			\n			\n			浙江箏曲教學－雪山春曉(四)\n			\n		\n		\n			\n			第5堂課\n			\n			\n			114.04.10\n			\n			\n			浙江箏曲教學－雪山春曉(五)\n			\n		\n		\n			\n			第6堂課\n			\n			\n			114.04.17\n			\n			\n			重奏樂曲教學－四月望雨(一)\n			\n		\n		\n			\n			第7堂課\n			\n			\n			114.04.24\n			\n			\n			重奏樂曲教學－四月望雨(二)\n			\n		\n		\n			\n			第8堂課\n			\n			\n			114.05.01\n			\n			\n			重奏樂曲教學－四月望雨(三)\n			\n		\n		\n			\n			第9堂課\n			\n			\n			114.05.08\n			\n			\n			山東箏曲教學－四段曲(一)\n			\n		\n		\n			\n			第10堂課\n			\n			\n			114.05.15\n			\n			\n			山東箏曲教學－四段曲(二)\n			\n		\n		\n			\n			第11堂課\n			\n			\n			114.05.22\n			\n			\n			山東箏曲教學－四段曲(三)\n			\n		\n		\n			\n			第12堂課\n			\n			\n			114.05.29\n			\n			\n			通俗樂曲教學－菊次郎的夏天(一)\n			\n		\n		\n			\n			第13堂課\n			\n			\n			114.06.05\n			\n			\n			通俗樂曲教學－菊次郎的夏天(二)\n			\n		\n		\n			\n			第14堂課\n			\n			\n			114.06.12\n			\n			\n			彩排成果展曲目\n			\n		\n		\n			\n			第15堂課\n			\n			\n			114.06.19\n			\n			\n			成果發表', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-06 00:00:00', '2025-06-19 00:00:00', '大稻埕戲苑教學小劇場', 25.06342433, 121.5130417, '2500', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40251', '[]') ON DUPLICATE KEY UPDATE `activity_name`='437 古箏進階班(黃熒熒)', `description`='本班授課採合班上課，分組教學，個別訂正。教材內容涵蓋古箏傳統流派箏曲及通俗樂曲、重奏樂曲，期待箏樂以多風貌形態呈現。\n(新生材料費約250，舊生教材費300元，可自行購買或由班長代購)\n\n \n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱：古箏進階班        (編號：437)  教師：  黃熒熒   \n			\n		\n		\n			\n			教學目標\n\n			及\n\n			教學內容\n			\n			\n			箏為中華民族傳統樂器，音色清鑠典雅，可怡情冶性，亦可作學術研究，本著藝術向下紮根的理念，期待愛箏者因學習傳統流派及現代編創的古箏樂曲，達到陶冶身心靈和藝術教化人心的成效。\n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			114.03.16\n			\n			\n			1.始業式：(1)分配上課用箏(2)安排學員座位(3)學員須知宣導\n\n			浙江箏曲教學－雪山春曉(一)\n			\n		\n		\n			\n			第2堂課\n			\n			\n			114.03.13\n			\n			\n			浙江箏曲教學－雪山春曉(二)\n			\n		\n		\n			\n			第3堂課\n			\n			\n			114.03.20\n			\n			\n			浙江箏曲教學－雪山春曉(三)\n			\n		\n		\n			\n			第4堂課\n			\n			\n			114.03.27\n			\n			\n			浙江箏曲教學－雪山春曉(四)\n			\n		\n		\n			\n			第5堂課\n			\n			\n			114.04.10\n			\n			\n			浙江箏曲教學－雪山春曉(五)\n			\n		\n		\n			\n			第6堂課\n			\n			\n			114.04.17\n			\n			\n			重奏樂曲教學－四月望雨(一)\n			\n		\n		\n			\n			第7堂課\n			\n			\n			114.04.24\n			\n			\n			重奏樂曲教學－四月望雨(二)\n			\n		\n		\n			\n			第8堂課\n			\n			\n			114.05.01\n			\n			\n			重奏樂曲教學－四月望雨(三)\n			\n		\n		\n			\n			第9堂課\n			\n			\n			114.05.08\n			\n			\n			山東箏曲教學－四段曲(一)\n			\n		\n		\n			\n			第10堂課\n			\n			\n			114.05.15\n			\n			\n			山東箏曲教學－四段曲(二)\n			\n		\n		\n			\n			第11堂課\n			\n			\n			114.05.22\n			\n			\n			山東箏曲教學－四段曲(三)\n			\n		\n		\n			\n			第12堂課\n			\n			\n			114.05.29\n			\n			\n			通俗樂曲教學－菊次郎的夏天(一)\n			\n		\n		\n			\n			第13堂課\n			\n			\n			114.06.05\n			\n			\n			通俗樂曲教學－菊次郎的夏天(二)\n			\n		\n		\n			\n			第14堂課\n			\n			\n			114.06.12\n			\n			\n			彩排成果展曲目\n			\n		\n		\n			\n			第15堂課\n			\n			\n			114.06.19\n			\n			\n			成果發表', `organizer`='臺北市藝文推廣處', `address`='103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', `start_date`='2025-03-06 00:00:00', `end_date`='2025-06-19 00:00:00', `location`=