INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91a26b32458d43631be', '536黃梅戲進階班 (哈憶平/曾韻清)', '本課程為已上過本研習班的舊生為主，需具備基本初階程度以上之進階課程。從黃梅戲電影帶入傳統黃梅戲這個劇種，更近一步認識傳統戲去的優美世界，推廣發揚全民都能共同體驗並實際操作，於學期末時能粉墨登場，完整呈現成果。讓喜愛黃梅戲的朋友能更細緻的鑽研學習傳統戲曲優美的唱、吟、做、表，進階程度的更精進展現更多的折子戲目。(教材費視課程需求酌收)\n \n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱：黃梅戲進階班       (編號：536)教師：哈憶平/曾韻清    \n			\n		\n		\n			\n			教學目標\n\n			及\n\n			教學內容\n			\n			\n			除了推廣傳承之外，更進一步解析傳統「黃梅戲」劇種的民族特色精髓，在身段唱腔上擘劃更深入的教程，學員能更進階的展現。\n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/7\n			\n			\n			相見歡彼此介紹認識，黃梅戲概論，簡介基本功\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/14\n			\n			\n			基本功系統教學一(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段)本期折子唱腔教學\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/21\n			\n			\n			基本功系統教學二(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段)本期折子唱腔教學\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/28\n			\n			\n			基本功系統教學三(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段)本期折子唱腔教學\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/11\n			\n			\n			基本功系統教學四(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段加組合練習)，本期折子唱腔教學\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/18\n			\n			\n			基本功系統教學五(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段加組合練習)，本期折子唱腔教學並配合身段演練\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/25\n			\n			\n			基本功系統教學六(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段加組合練習、水袖基本式)，本期折子唱腔教學並配合身段演練\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5/2\n			\n			\n			基本功系統教學七(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段加組合練習、水袖基本式)，本期折子唱腔教學並配合身段演練\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5/9\n			\n			\n			基本功系統教學八(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段加組合練習、水袖基本式)，本期折子唱腔教學並配合身段演練\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/16\n			\n			\n			本期折子戲進行各個行當確認並分組練習\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/23\n			\n			\n			本期折子戲進行各個行當確認並分組練習\n			\n		\n		\n			\n			第12堂課\n			\n			\n			6/6\n			\n			\n			本期折子戲成果展演登記並分組練習\n			\n		\n		\n			\n			第13堂課\n			\n			\n			6/13\n			\n			\n			 本期折子戲成果展演登記並分組練習\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/20\n			\n			\n			各組總複習\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/27\n			\n			\n			排演成果發表', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-07 00:00:00', '2025-06-27 00:00:00', '大稻埕戲苑排練室二教室', 25.06342433, 121.5130417, '2500', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40252', '[]') ON DUPLICATE KEY UPDATE `activity_name`='536黃梅戲進階班 (哈憶平/曾韻清)', `description`='本課程為已上過本研習班的舊生為主，需具備基本初階程度以上之進階課程。從黃梅戲電影帶入傳統黃梅戲這個劇種，更近一步認識傳統戲去的優美世界，推廣發揚全民都能共同體驗並實際操作，於學期末時能粉墨登場，完整呈現成果。讓喜愛黃梅戲的朋友能更細緻的鑽研學習傳統戲曲優美的唱、吟、做、表，進階程度的更精進展現更多的折子戲目。(教材費視課程需求酌收)\n \n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱：黃梅戲進階班       (編號：536)教師：哈憶平/曾韻清    \n			\n		\n		\n			\n			教學目標\n\n			及\n\n			教學內容\n			\n			\n			除了推廣傳承之外，更進一步解析傳統「黃梅戲」劇種的民族特色精髓，在身段唱腔上擘劃更深入的教程，學員能更進階的展現。\n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/7\n			\n			\n			相見歡彼此介紹認識，黃梅戲概論，簡介基本功\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/14\n			\n			\n			基本功系統教學一(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段)本期折子唱腔教學\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/21\n			\n			\n			基本功系統教學二(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段)本期折子唱腔教學\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/28\n			\n			\n			基本功系統教學三(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段)本期折子唱腔教學\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/11\n			\n			\n			基本功系統教學四(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段加組合練習)，本期折子唱腔教學\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/18\n			\n			\n			基本功系統教學五(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段加組合練習)，本期折子唱腔教學並配合身段演練\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/25\n			\n			\n			基本功系統教學六(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段加組合練習、水袖基本式)，本期折子唱腔教學並配合身段演練\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5/2\n			\n			\n			基本功系統教學七(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段加組合練習、水袖基本式)，本期折子唱腔教學並配合身段演練\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5/9\n			\n			\n			基本功系統教學八(含壓腿各種踢腿式，生旦行當站姿走步、手勢身段加組合練習、水袖基本式)，本期折子唱腔教學並配合身段演練\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/16\n			\n			\n			本期折子戲進行各個行當確認並分組練習\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/23\n			