INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91a26b32458d43631c1', '435 插花進階乙班(劉慧娟)', '利用各類花材結合最新流行趨勢及設計，隨心所欲做出精緻又富創意之時尚花藝設計，如居家佈置商業設計，節慶花禮、使學員有獨立設計與創作之能力，可輔導考花藝證照。（材費用每堂約350元）\n\n \n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱：   插花進階乙班   (編號： 435)教師：  劉慧娟    \n			\n		\n		\n			\n			教學目標\n\n			及\n\n			教學內容\n			\n			\n			1.學員能認識花卉及花材處理方式\n\n			2.從當季花材中設計出精緻又有創意的花藝\n\n			3.利用各類花材結合最新流行趨勢及設計創作出與眾不同的時尚花藝\n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/6\n			\n			\n			自然花型\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/13\n			\n			\n			多層次花型\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/20\n			\n			\n			古典花型\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/27\n			\n			\n			兒童節設計\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/10\n			\n			\n			木片設計\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/17\n			\n			\n			異材質設計-紙\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/24\n			\n			\n			鐵絲網應用設計\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5/1\n			\n			\n			苔草的應用\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5/8\n			\n			\n			扇型變化\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/15\n			\n			\n			        木框應用設計\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/22\n			\n			\n			        端午節設計\n			\n		\n		\n			\n			第12堂課\n			\n			\n			5/29\n			\n			\n			        花束 \n			\n		\n		\n			\n			第13堂課\n			\n			\n			6/5\n			\n			\n			新娘捧花及胸花\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/12\n			\n			\n			       架構講解\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/19\n			\n			\n			        植物\n			\n		\n	\n\n\n ', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-06 00:00:00', '2025-06-19 00:00:00', '大稻埕戲苑805教室', 25.06342433, 121.5130417, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40255', '[]') ON DUPLICATE KEY UPDATE `activity_name`='435 插花進階乙班(劉慧娟)', `description`='利用各類花材結合最新流行趨勢及設計，隨心所欲做出精緻又富創意之時尚花藝設計，如居家佈置商業設計，節慶花禮、使學員有獨立設計與創作之能力，可輔導考花藝證照。（材費用每堂約350元）\n\n \n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱：   插花進階乙班   (編號： 435)教師：  劉慧娟    \n			\n		\n		\n			\n			教學目標\n\n			及\n\n			教學內容\n			\n			\n			1.學員能認識花卉及花材處理方式\n\n			2.從當季花材中設計出精緻又有創意的花藝\n\n			3.利用各類花材結合最新流行趨勢及設計創作出與眾不同的時尚花藝\n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/6\n			\n			\n			自然花型\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/13\n			\n			\n			多層次花型\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/20\n			\n			\n			古典花型\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/27\n			\n			\n			兒童節設計\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/10\n			\n			\n			木片設計\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/17\n			\n			\n			異材質設計-紙\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/24\n			\n			\n			鐵絲網應用設計\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5/1\n			\n			\n			苔草的應用\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5/8\n			\n			\n			扇型變化\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/15\n			\n			\n			        木框應用設計\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/22\n			\n			\n			        端午節設計\n			\n		\n		\n			\n			第12堂課\n			\n			\n			5/29\n			\n			\n			        花束 \n			\n		\n		\n			\n			第13堂課\n			\n			\n			6/5\n			\n			\n			新娘捧花及胸花\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/12\n			\n			\n			       架構講解\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/19\n			\n			\n			        植物\n			\n		\n	\n\n\n ', `organizer`='臺北市藝文推廣處', `address`='103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', `start_date`='2025-03-06 00:00:00', `end_date`='2025-06-19 00:00:00', `location`='大稻埕戲苑805教室', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='2000', `source_url`='https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40255', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91a26b32458d43631c2', '222 月琴彈唱初級班(柯銘峰 李咨英)', '月琴的演奏方式和內容非常自由，但與所有樂器一樣，都需要有正確的演奏姿勢和觀念。透過每次曲目的練習，學習基本演奏方法，兼顧純演奏與彈唱的技術，做為未來變化演奏的功底。\n\n \n\n\n\n \n\n ', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-04 00:00:00', '2025-06-10 00:00:00', '大稻埕戲苑802教室', 25.06342433, 121.5130417, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40257', '[]') ON DUPLICATE KEY UPDATE `activity_name`='222 月琴彈唱初級班(柯銘峰 李咨英)', `description`='月琴的演奏方式和內容非常自由，但與所有樂器一樣，都需要有正確的演奏姿勢和觀念。透過每次曲目的練習，學習基本演奏方法，兼顧純演奏與彈唱的技術，做為未來變化演奏的功底。\n\n \n\n\n\n \n\n ', `organizer`='臺北市藝文推廣處', `address`='103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', `start_date`='2025-03-04 00:00:00', `end_date`='2025-06-10 00:00:00', `location`='大稻埕戲苑802教室', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='2000', `source_url`='https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40257', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91a26b32458d43631c3', '438 歌仔戲班(陳禹安/林金泉)', '雙師資歌仔調與歌仔戲體驗式教學：戲曲身段、手、眼、身、法、步練習，唱、唸、做、表解拆，延續春季班之劇目，著重唱段教唱與劇藝排練，每年12月期末成果展演。無經驗也可報名。(新生教材費250元)(其他費用：成果演出必要之費用)\n\n成果展展出劇目：《菜刀 柴刀 剃頭刀》\n成果展展出時間：113年12月22日（日）18：30\n地點:大稻埕戲苑９樓劇場\n\n \n\n\n\n\n \n\n \n\n \n\n ', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-06 00:00:00', '2025-06-19 00:00:00', '大稻埕戲苑排練室一', 25.06342433, 121.5130417, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40258', '[]') ON DUPLICATE KEY UPDATE `activity_name`='438 歌仔戲班(陳禹安/林金泉)', `description`='雙師資歌仔調與歌仔戲體驗式教學：戲曲身段、手、眼、身、法、步練習，唱、唸、做、表解拆，延續春季班之劇目，著重唱段教唱與劇藝排練，每年12月期末成果展演。無經驗也可報名。(新生教材費250元)(其他費用：成果演出必要之費用)\n\n成果展展出劇目：《菜刀 柴刀 剃頭刀》\n成果展展出時間：113年12月22日（日）18：30\n地點:大稻埕戲苑９樓劇場\n\n \n\n\n\n\n \n\n \n\n \n\n ', `organizer`='臺北市藝文推廣處', `address`='103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', `start_date`='2025-03-06 00:00:00', `end_date`='2025-06-19 00:00:00', `location`='大稻埕戲苑排練室一', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='2000', `source_url`='https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40258', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91a26b32458d43631c4', '526臺灣鄉土舞蹈班 (胡松德)', '1.認識臺灣的民俗藝術，藉由肢體的本能動作與運動研習臺灣鄉土藝術舞蹈。\n2.透過臺灣民間鄉土與流行的音樂，重現傳統民俗舞蹈再編作。(需自行購買軟鞋)\n歡迎對本課程有興趣的民眾(性別不拘)報名參加\n\n\n成果展演影片  ←請點我\n\n ', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-07 00:00:00', '2025-06-27 00:00:00', '大稻埕戲苑排練室二教室', 25.06342433, 121.5130417, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40259', '[]') ON DUPLICATE KEY UPDATE `activity_name`='526臺灣鄉土舞蹈班 (胡松德)', `description`='1.認識臺灣的民俗藝術，藉由肢體的本能動作與運動研習臺灣鄉土藝術舞蹈。\n2.透過臺灣民間鄉土與流行的音樂，重現傳統民俗舞蹈再編作。(需自行購買軟鞋)\n歡迎對本課程有興趣的民眾(性別不拘)報名參加\n\n\n成果展演影片  ←請點我\n\n ', `organizer`='臺北市藝文推廣處', `address`='103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', `start_date`='2025-03-07 00:00:00', `end_date`='2025-06-27 00:00:00', `location`='大稻埕戲苑排練室二教室', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='2000', `source_url`='https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40259', `image_url`='[]';
