INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91a26b32458d43631c9', '424 二胡進階甲班(吳政翰 )', '二胡系統化教學：1.基本功養成與樂曲演奏。2.換把、揉弦、滑音、短弓等進階技巧。3.各調練習曲、樂曲〈流行樂曲為主〉。4.音樂賞析與詮釋。報名者需具備D調G調第二把位以上程度者為佳，教材費100元。\n\n \n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱：     二胡進階甲班     (編號：  424  )教師：  吳政翰 \n			\n		\n		\n			\n			教學目標\n\n			及\n\n			教學內容\n			\n			\n			以系統化教學方式帶領學習者進入進階程度，課程分為兩時段（進階技巧、樂曲詮釋），讓有基礎者學習進階技巧，有程度者更落實基本功運用。\n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/6\n			\n			\n			演奏姿勢概述_______教程：D調練習曲\n\n			台語歌曲\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/13\n			\n			\n			右手握弓姿勢_______教程：G調練習曲\n\n			台語歌曲\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/20\n			\n			\n			左手按弦姿勢_______教程：D調練習曲\n\n			國語歌曲\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/27\n			\n			\n			音程訓練___________教程：G調練習曲\n\n			國語歌曲\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/10\n			\n			\n			節奏訓練___________教程：D調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/17\n			\n			\n			右手運弓原理_______教程：G調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/24\n			\n			\n			左手按弦原理_______教程：D調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5/1\n			\n			\n			長弓練習___________教程：G調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5/8\n			\n			\n			音階練習___________教程：A調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/15\n			\n			\n			左手手指肌能練習___教程：A調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/22\n			\n			\n			換把技巧___________教程：A調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第12堂課\n			\n			\n			5/29\n			\n			\n			滑音技巧___________教程：A調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第13堂課\n			\n			\n			6/5\n			\n			\n			裝飾音技巧_________教程：A調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/12\n			\n			\n			揉弦技巧___________教程：A調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/19\n			\n			\n			成果發表\n			\n		\n	\n\n\n \n\n ', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-06 00:00:00', '2025-06-19 00:00:00', '大稻埕戲苑804教室', 25.06342433, 121.5130417, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40264', '[]') ON DUPLICATE KEY UPDATE `activity_name`='424 二胡進階甲班(吳政翰 )', `description`='二胡系統化教學：1.基本功養成與樂曲演奏。2.換把、揉弦、滑音、短弓等進階技巧。3.各調練習曲、樂曲〈流行樂曲為主〉。4.音樂賞析與詮釋。報名者需具備D調G調第二把位以上程度者為佳，教材費100元。\n\n \n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱：     二胡進階甲班     (編號：  424  )教師：  吳政翰 \n			\n		\n		\n			\n			教學目標\n\n			及\n\n			教學內容\n			\n			\n			以系統化教學方式帶領學習者進入進階程度，課程分為兩時段（進階技巧、樂曲詮釋），讓有基礎者學習進階技巧，有程度者更落實基本功運用。\n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/6\n			\n			\n			演奏姿勢概述_______教程：D調練習曲\n\n			台語歌曲\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/13\n			\n			\n			右手握弓姿勢_______教程：G調練習曲\n\n			台語歌曲\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/20\n			\n			\n			左手按弦姿勢_______教程：D調練習曲\n\n			國語歌曲\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/27\n			\n			\n			音程訓練___________教程：G調練習曲\n\n			國語歌曲\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/10\n			\n			\n			節奏訓練___________教程：D調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/17\n			\n			\n			右手運弓原理_______教程：G調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/24\n			\n			\n			左手按弦原理_______教程：D調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5/1\n			\n			\n			長弓練習___________教程：G調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5/8\n			\n			\n			音階練習___________教程：A調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/15\n			\n			\n			左手手指肌能練習___教程：A調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/22\n			\n			\n			換把技巧___________教程：A調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第12堂課\n			\n			\n			5/29\n			\n			\n			滑音技巧___________教程：A調練習曲\n\n			流行樂曲\n			\n		\n		\n			\n			第13堂課\n			\n			\n			6/5\n			\n			\n			裝飾音技巧_________教程：A調練習曲\n\n			流行樂曲\n		