INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91a26b32458d43631cb', '225 京劇唱腔研習班(唐文華 茅靜順)', '教授學員對傳統京戲身段、唱腔有更多認識，剖析唱念作打的舞台呈現，學員們可從觀賞到個人學習都能靈活地運用，推廣京戲傳統美學，豐富每位學員的認知。\n\n\n	\n		\n			\n			堂次\n			\n			\n			進度內容\n			\n		\n		\n			\n			第1堂  \n			\n			\n			京戲基本唱腔介紹\n			\n		\n		\n			\n			第2堂\n			\n			\n			認識生行及唱腔示範\n			\n		\n		\n			\n			第3堂\n			\n			\n			認識旦行及唱腔介紹\n			\n		\n		\n			\n			第4堂\n			\n			\n			認識其他行當及唱腔介紹\n			\n		\n		\n			\n			第5堂\n			\n			\n			學習授課唱腔\n			\n		\n		\n			\n			第6堂\n			\n			\n			復習授課內容\n			\n		\n		\n			\n			第7堂\n			\n			\n			經典生行唱段示範及教授\n			\n		\n		\n			\n			第8堂\n			\n			\n			經典生行唱段示範及教授\n			\n		\n		\n			\n			第9堂\n			\n			\n			經典生行唱段示範及教授\n			\n		\n		\n			\n			第10堂\n			\n			\n			經典旦行唱段示範及教授\n			\n		\n		\n			\n			第11堂\n			\n			\n			經典旦行唱段示範及教授\n			\n		\n		\n			\n			第12堂\n			\n			\n			經典淨行唱段示範及教授\n			\n		\n		\n			\n			第13堂\n			\n			\n			經典淨行唱段示範及教授\n			\n		\n		\n			\n			第14堂\n			\n			\n			經典行當唱段示範及教授\n			\n		\n		\n			\n			第15堂\n			\n			\n			學期研習成果發表及結業\n			\n		\n	\n\n\n \n\n \n\n ', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-04 00:00:00', '2025-06-10 00:00:00', '大稻埕戲苑805教室', 25.06342433, 121.5130417, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40268', '[]') ON DUPLICATE KEY UPDATE `activity_name`='225 京劇唱腔研習班(唐文華 茅靜順)', `description`='教授學員對傳統京戲身段、唱腔有更多認識，剖析唱念作打的舞台呈現，學員們可從觀賞到個人學習都能靈活地運用，推廣京戲傳統美學，豐富每位學員的認知。\n\n\n	\n		\n			\n			堂次\n			\n			\n			進度內容\n			\n		\n		\n			\n			第1堂  \n			\n			\n			京戲基本唱腔介紹\n			\n		\n		\n			\n			第2堂\n			\n			\n			認識生行及唱腔示範\n			\n		\n		\n			\n			第3堂\n			\n			\n			認識旦行及唱腔介紹\n			\n		\n		\n			\n			第4堂\n			\n			\n			認識其他行當及唱腔介紹\n			\n		\n		\n			\n			第5堂\n			\n			\n			學習授課唱腔\n			\n		\n		\n			\n			第6堂\n			\n			\n			復習授課內容\n			\n		\n		\n			\n			第7堂\n			\n			\n			經典生行唱段示範及教授\n			\n		\n		\n			\n			第8堂\n			\n			\n			經典生行唱段示範及教授\n			\n		\n		\n		