INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91a26b32458d43631ce', '612 漢文基礎與傳統吟調(洪澤南)', '融合中文系所與傳統漢學堂課程，吟讀詩詞歌賦並經書古文，研習傳統文人吟調，能吟詩，會作詩，提升古典文學賞析能力。\n\n ', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-08 00:00:00', '2025-06-28 00:00:00', '大稻埕戲苑802教室', 25.06342433, 121.5130417, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40272', '[]') ON DUPLICATE KEY UPDATE `activity_name`='612 漢文基礎與傳統吟調(洪澤南)', `description`='融合中文系所與傳統漢學堂課程，吟讀詩詞歌賦並經書古文，研習傳統文人吟調，能吟詩，會作詩，提升古典文學賞析能力。\n\n ', `organizer`='臺北市藝文推廣處', `address`='103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', `start_date`='2025-03-08 00:00:00', `end_date`='2025-06-28 00:00:00', `location`='大稻埕戲苑802教室', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='2000', `source_url`='https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40272', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91a26b32458d43631cf', '614 棉紙撕畫班(陳秀麗)', '紙撕畫運用棉紙的特性，利用柔軟且具有一定韌性與眾不同的質感的紙張而製作出來的作品。筆的運用方式展現、紙張的延展、泡水及撕開等獨特的技法，這種技法不僅可以展現出豐富的色彩和層次感，還能通過撕裂紙張的邊緣創造出獨特的紋理和形狀進而創造出蘊含無限的藝術品。\n棉紙撕畫是一種充滿創造力和趣味性的藝術形式，通過簡單的材料和技法，易學易懂，可以創作出色彩斑斕、層次豐富的藝術作品。歡迎一同走入棉紙撕畫世界，享受創作美的樂趣表達自己的藝術想像力。\n\n \n\n \n\n \n\n ', '臺北市藝文推廣處', '103  臺北市大同區台北市大同區迪化街一段21號(大稻埕戲苑)', '2025-03-08 00:00:00', '2025-06-28 00:00:00', '大稻埕戲苑804教室', 25.0546733, 121.5103045, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40273', '[]') ON DUPLICATE KEY UPDATE `activity_name`='614 棉紙撕畫班(陳秀麗)', `description`='紙撕畫運用棉紙的特性，利用柔軟且具有一定韌性與眾不同的質感的紙張而製作出來的作品。筆的運用方式展現、紙張的延展、泡水及撕開等獨特的技法，這種技法不僅可以展現出豐富的色彩和層次感，還能通過撕裂紙張的邊緣創造出獨特的紋理和形狀進而創造出蘊含無限的藝術品。\n棉紙撕畫是一種充滿創造力和趣味性的藝術形式，通過簡單的材料和技法，易學易懂，可以創作出色彩斑斕、層次豐富的藝術作品。歡迎一同走入棉紙撕畫世界，享受創作美的樂趣表達自己的藝術想像力。\n\n \n\n \n\n \n\n ', `organizer`='臺北市藝文推廣處', `address`='103  臺北市大同區台北市大同區迪化街一段21號(大稻埕戲苑)', `start_date`='2025-03-08 00:00:00', `end_date`='2025-06-28 00:00:00', `location`='大稻埕戲苑804教室', `latitude`=25.0546733, `longitude`=121.5103045, `ticket_price`='2000', `source_url`='https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40273', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91a26b32458d43631d3', '226 民族舞蹈班(林秀貞)', '本期教授蒙古族「安代舞」，它是流傳在内蒙古科爾沁草原上的民間舞蹈，「安代舞」通常舞於節慶或閒暇之際，没有時間、地點的限制，由一人领唱眾人與领唱者應和音樂的節奏甩巾踏步，是蒙古人喜聞樂見的踏歌形式，具有鲜明的民族特色和濃郁的生活氣息。\n歡迎對本課程有興趣的民眾(性別不拘)報名參加\n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱： 民族舞蹈班        (編號：226)      教師： 林秀貞 \n			\n		\n		\n			\n			教學目標\n\n			及\n\n			教學內容\n			\n			\n			本期教授蒙古族「安代舞」，它是蒙古人喜聞樂見的踏歌形式，具有鲜明的民族特色和濃郁的生活氣息。\n\n			 \n\n			 \n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/4\n			\n			\n			介紹蒙古族「安代舞」\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/11\n			\n			\n			蒙族舞的基本手位與腳位練習\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/18\n			\n			\n			蒙族舞的體態訓練\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/25\n			\n			\n			蒙族舞的步法練習\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/1\n			\n			\n			蒙族舞的動律練習\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/8\n			\n			\n			安代的重踏步與踏步跳練習\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/15\n			\n			\n			安代舞的踏點步與雙吸腿跳步\n			\n		\n		\n			\n			第8堂課\n			\n			\n			4/22\n			\n			\n			安代舞的換位步的雙人對舞\n			\n		\n		\n			\n			第9堂課\n			\n			\n			4/29\n			\n			\n			甩巾與綜合步法練習\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/6\n			\n			\n			甩巾與綜合步法練習\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/13\n			\n			\n			「安代舞」小品\n			\n		\n		\n			\n			第12堂課\n			\n			\n			5/20\n			\n			\n			「安代舞」小品\n			\n		\n		\n			\n			第13堂課\n			\n			\n			5/27\n			\n			\n			「安代舞」小品\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/4\n			\n			\n			「安代舞」小品\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/11\n			\n			\n			教學成果呈現', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-04 00:00:00', '2025-06-10 00:00:00', '大稻埕戲苑排練室二教室', 25.06342433, 121.5130417, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40277', '[]') ON DUPLICATE KEY UPDATE `activit