INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91b26b32458d43631d6', '329 劇本賞析班(劉秀庭)', '****原學費2,000元，新開班優惠學費7折為1,400元****\n\n\n劇本表達人對於內心與外在世界的思考與對話，本課程以臺灣豐富的劇種劇本為主，加上日治前輩經典，邀大家一同賞析。\n\n\n \n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱：劇本賞析      (編號：329)教師：劉秀庭\n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			03/05\n			\n			\n			日治時期名劇選讀。《閹雞》（一）\n			\n		\n		\n			\n			第2堂課\n			\n			\n			03/12\n			\n			\n			日治時期名劇選讀。《閹雞》（二）\n			\n		\n		\n			\n			第3堂課\n			\n			\n			03/19\n			\n			\n			北管福路戲劇本選讀。《黑四門》\n			\n		\n		\n			\n			第4堂課\n			\n			\n			03/26\n			\n			\n			北管西路戲劇本選讀。《天水關》\n			\n		\n		\n			\n			第5堂課\n			\n			\n			04/02\n			\n			\n			歌仔冊選讀。《最新王昭君冷宮歌》（一）\n			\n		\n		\n			\n			第6堂課\n			\n			\n			04/09\n			\n			\n			歌仔冊選讀。《最新王昭君冷宮歌》（二）\n			\n		\n		\n			\n			第7堂課\n			\n			\n			04/16\n			\n			\n			南管曲詞選讀。《陳三五娘》\n			\n		\n		\n			\n			第8堂課\n			\n			\n			04/23\n			\n			\n			移植電影的歌仔戲劇本選讀。林義成《陳世美》（一）\n			\n		\n		\n			\n			第9堂課\n			\n			\n			04/30\n			\n			\n			移植電影的歌仔戲劇本選讀。林義成《陳世美》（二）\n			\n		\n		\n			\n			第10堂課\n			\n			\n			05/07\n			\n			\n			布袋戲劇本選讀。李天祿《北遊記》（一）\n			\n		\n		\n			\n			第11堂課\n			\n			\n			05/14\n			\n			\n			布袋戲劇本選讀。李天祿《北遊記》（二）\n			\n		\n		\n			\n			第12堂課\n			\n			\n			05/21\n			\n			\n			舞台歌仔戲劇本選讀。陳永明《冉冉紅塵》（一）\n			\n		\n		\n			\n			第13堂課\n			\n			\n			05/29\n			\n			\n			舞台歌仔戲劇本選讀。陳永明《冉冉紅塵》（二）\n			\n		\n		\n			\n			第14堂課\n			\n			\n			06/05\n			\n			\n			外台歌仔戲田野本選讀。陳美雲歌劇團《道光斬子》（一）\n			\n		\n		\n			\n			第15堂課\n			\n			\n			06/12\n			\n			\n			外台歌仔戲田野本選讀。陳美雲歌劇團《道光斬子》（二）', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-05 00:00:00', '2025-06-11 00:00:00', '大稻埕戲苑簡報室', 25.06342433, 121.5130417, '1400', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40280', '[]') ON DUPLICATE KEY UPDATE `activ