INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc91b26b32458d43631d7', '337 進階把子功班 (李佳麒)', '「把子」也叫「刀槍把子」。\n為傳統戲曲演出所用的武器道具。他和「基本功、毯子功」是並列戲曲演員訓練的三大項目之一，在戲曲表演中佔有相當重要的地位。\n歡迎戲曲愛好者還有「素人」們，可以一起來學習在戲曲舞台上是如何「耍刀、耍槍」打把子的。\n\n\n \n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱：   進階把子功      (編號：337)教師：李佳麒             \n			\n		\n		\n			\n			教學目標\n\n			及\n\n			教學內容\n			\n			\n			「先會耍、在學打」。\n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			 \n			\n			\n			學習槍，刀，棍耍法。（滾動式教學）。\n			\n		\n		\n			\n			第2堂課\n			\n			\n			 \n			\n			\n			複習上週（滾動式教學）。\n			\n		\n		\n			\n			第3堂課\n			\n			\n			 \n			\n			\n			打「把子」過程中腳步如何正確使用。\n\n			例：﹙小快槍﹚\n			\n		\n		\n			\n			第4堂課\n			\n			\n			 \n			\n			\n			棍棒槍教學（一）（滾動式教學）。\n			\n		\n		\n			\n			第5堂課\n			\n			\n			 \n			\n			\n			棍棒槍教學（二）（滾動式教學）。\n			\n		\n		\n			\n			第6堂課\n			\n			\n			 \n			\n			\n			棍棒槍教學（三）（滾動式教學）。\n			\n		\n		\n			\n			第7堂課\n			\n			\n			 \n			\n			\n			前六週教學檢討與學員討論。複習棍棒槍。\n			\n		\n		\n			\n			第8堂課\n			\n			\n			 \n			\n			\n			學習﹙反天槓﹚（一）。\n			\n		\n		\n			\n			第9堂課\n			\n			\n			 \n			\n			\n			學習﹙反天槓﹚（二）。\n			\n		\n		\n			\n			第10堂課\n			\n			\n			 \n			\n			\n			        學習﹙反天槓﹚（ 三）。\n			\n		\n		\n			\n			第11堂課\n			\n			\n			 \n			\n			\n			           複習﹙反天槓、棍棒槍﹚。\n			\n		\n		\n			\n			第12堂課\n			\n			\n			 \n			\n			\n			          試學員學習裝況接受度，續教﹙大刀雙刀﹚。\n			\n		\n		\n			\n			第13堂課\n			\n			\n			 \n			\n			\n			   ﹙大刀雙刀﹚（一）。\n			\n		\n		\n			\n			第14堂課\n			\n			\n			 \n			\n			\n			           ﹙大刀雙刀﹚（二）。\n			\n		\n		\n			\n			第15堂課\n			\n			\n			 \n			\n			\n			  ﹙棍棒槍、反天槓、大刀雙刀﹚總複習討論。\n			\n		\n	\n\n\n ', '臺北市藝文推廣處', '103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', '2025-03-05 00:00:00', '2025-05-28 00:00:00', '大稻埕戲苑教學小劇場', 25.06342433, 121.5130417, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40281', '[]') ON DUPLICATE KEY UPDATE `activity_name`='337 進階把子功班 (李佳麒)', `description`='「把子」也叫「刀槍把子」。\n為傳統戲曲演出所用的武器道具。他和「基本功、毯子功」是並列戲曲演員訓練的三大項目之一，在戲曲表演中佔有相當重要的地位。\n歡迎戲曲愛好者還有「素人」們，可以一起來學習在戲曲舞台上是如何「耍刀、耍槍」打把子的。\n\n\n \n\n\n	\n		\n			\n			臺北市藝文推廣處大稻埕戲苑114年春季班課程規劃表\n\n			課程名稱：   進階把子功      (編號：337)教師：李佳麒             \n			\n		\n		\n			\n			教學目標\n\n			及\n\n			教學內容\n			\n			\n			「先會耍、在學打」。\n			\n		\n		\n			\n			堂次\n			\n			\n			上課日期\n			\n			\n			進        度        內        容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			 \n			\n			\n			學習槍，刀，棍耍法。（滾動式教學）。\n			\n		\n		\n			\n			第2堂課\n			\n			\n			 \n			\n			\n			複習上週（滾動式教學）。\n			\n		\n		\n			\n			第3堂課\n			\n			\n			 \n			\n			\n			打「把子」過程中腳步如何正確使用。\n\n			例：﹙小快槍﹚\n			\n		\n		\n			\n			第4堂課\n			\n			\n			 \n			\n			\n			棍棒槍教學（一）（滾動式教學）。\n			\n		\n		\n			\n			第5堂課\n			\n			\n			 \n			\n			\n			棍棒槍教學（二）（滾動式教學）。\n			\n		\n		\n			\n			第6堂課\n			\n			\n			 \n			\n			\n			棍棒槍教學（三）（滾動式教學）。\n			\n		\n		\n			\n			第7堂課\n			\n			\n			 \n			\n			\n			前六週教學檢討與學員討論。複習棍棒槍。\n			\n		\n		\n			\n			第8堂課\n			\n			\n			 \n			\n			\n			學習﹙反天槓﹚（一）。\n			\n		\n		\n			\n			第9堂課\n			\n			\n			 \n			\n			\n			學習﹙反天槓﹚（二）。\n			\n		\n		\n			\n			第10堂課\n			\n			\n			 \n			\n			\n			        學習﹙反天槓﹚（ 三）。\n			\n		\n		\n			\n			第11堂課\n			\n			\n			 \n			\n			\n			           複習﹙反天槓、棍棒槍﹚。\n			\n		\n		\n			\n			第12堂課\n			\n			\n			 \n			\n			\n			          試學員學習裝況接受度，續教﹙大刀雙刀﹚。\n			\n		\n		\n			\n			第13堂課\n			\n			\n			 \n			\n			\n			   ﹙大刀雙刀﹚（一）。\n			\n		\n		\n			\n			第14堂課\n			\n			\n			 \n			\n			\n			           ﹙大刀雙刀﹚（二）。\n			\n		\n		\n			\n			第15堂課\n			\n			\n			 \n			\n			\n			  ﹙棍棒槍、反天槓、大刀雙刀﹚總複習討論。\n			\n		\n	\n\n\n ', `organizer`='臺北市藝文推廣處', `address`='103  臺北市大同區迪化街一段21號8樓(大稻埕戲苑)', `start_date`='2025-03-05 00:00:00', `end_date`='2025-05-28 00:00:00', `location`='大稻埕戲苑教學小劇場', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='2000', `source_url`='https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40281', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc9b926b32458d43631e7', '張進丁書法展', '官田區公所於114年1月6日至3月31日，邀請張進丁老師於本所二樓藝文迴廊舉辦「張進丁書法展」。\r\n本次展出作品共12件，字體類型、書寫題材皆包羅萬象，不僅呈現書法藝術的多元性，亦展現人生當中各種課題和情感。', '臺南市官田區公所', '臺南市官田區', '2025-01-06 00:00:00', '2025-03-31 00:00:00', '官田區（臺南市）=', 23.19098548, 120.3479918, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='張進丁書法展', `description`='官田區公所於114年1月6日至3月31日，邀請張進丁老師於本所二樓藝文迴廊舉辦「張進丁書法展」。\r\n本次展出作品共12件，字體類型、書寫題材皆包羅萬象，不僅呈現書法藝術的多元性，亦展現人生當中各種課題和情感。', `organizer`='臺南市官田區公所', `address`='臺南市官田區', `start_date`='2025-01-06 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='官田區（臺南市）=', `latitude`=23.19098548, `longitude`=120.3479918, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc9bc26b32458d43631f3', '無資料', '陳泰元老師（1935~2024）出生於本市新化區，臺南師範學校藝術科畢業後投身於藝術教育及創作，1959年加入南美會，積極參與本市藝文活動，亦曾擔任南美會會長，1973年更獲全國教學方法優良教師等榮譽。\r\n陳泰元晚年潛心於研究光影與色彩的交互表現，追求創新繪畫技法與自我突破，其創作能量豐沛，是本市優秀藝術家。\r\n本展覽透過展出陳泰元老師的藝術創作與相關文獻，讓民眾更加了解其成就與貢獻。\r\n', '臺南市政府文化局', '臺南市東區中華東路三段332號', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='陳泰元老師（1935~2024）出生於本市新化區，臺南師範學校藝術科畢業後投身於藝術教育及創作，1959年加入南美會，積極參與本市藝文活動，亦曾擔任南美會會長，1973年更獲全國教學方法優良教師等榮譽。\r\n陳泰元晚年潛心於研究光影與色彩的交互表現，追求創新繪畫技法與自我突破，其創作能量豐沛，是本市優秀藝術家。\r\n本展覽透過展出陳泰元老師的藝術創作與相關文獻，讓民眾更加了解其成就與貢獻。\r\n', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc9cb26b32458d436322b', '魯蛇翻身（Loser翻身），2025新書展', '無資料', '南投縣草屯鎮公所', '南投縣草屯鎮草鞋墩一街8號', '2025-02-11 00:00:00', '2025-02-27 00:00:00', '南投縣草屯鎮立圖書館', 23.9736845, 120.6802819, '無資料', 'https://www.facebook.com/tsaotunlibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='魯蛇翻身（Loser翻身），2025新書展', `description`='無資料', `organizer`='南投縣草屯鎮公所', `address`='南投縣草屯鎮草鞋墩一街8號', `start_date`='2025-02-11 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='南投縣草屯鎮立圖書館', `latitude`=23.9736845, `longitude`=120.6802819, `ticket_price`='無資料', `source_url`='https://www.facebook.com/tsaotunlibrary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc9cb26b32458d436322e', '苗栗縣114年文狀元選拔競賽「翰墨鳴華．文狀元」推薦閱讀圖書全縣聯展', '114年文狀元選拔競賽推薦閱讀用書，係彙整文化部、縣圖邀請相關單位、學校及鄉鎮市圖書館等推薦的優良書籍，並經苗栗縣政府文狀元選拔競賽籌備委員會經初選、複選及決選，而精挑嚴選出國小10本、國中8本的優良讀物。\r\n國小組書單，計有：1.草蜢的幸福雜貨店。2.大海的孩子。3.泡泡男孩。4.我的馬拉松故事。5.星期天的音樂教室。6.作弊。7.值日追書生。8.人生重開機。9.終點站下車、10馬背上的少女。\r\n國中組書單，計有：1.國學潮人誌，古人超有料。2.超能少年1：超能研究社。3.誰搬走了我的乳酪？。4.那些散落的星星。5.華氏零度。6.少年噶瑪蘭。7.山與林的深處。8.童年母愛欠缺 長大後的妳，如何療癒對愛的匱乏，健全心中缺損的母親角色。', '苗栗縣立圖書館', '苗栗縣西湖鄉', '2025-01-02 00:00:00', '2025-04-30 00:00:00', '西湖鄉（苗栗縣）=', 24.54153218, 120.7614144, '無資料', 'https://lib.miaoli.gov.tw/wSite/mp', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗栗縣114年文狀元選拔競賽「翰墨鳴華．文狀元」推薦閱讀圖書全縣聯展', `description`='114年文狀元選拔競賽推薦閱讀用書，係彙整文化部、縣圖邀請相關單位、學校及鄉鎮市圖書館等推薦的優良書籍，並經苗栗縣政府文狀元選拔競賽籌備委員會經初選、複選及決選，而精挑嚴選出國小10本、國中8本的優良讀物。\r\n國小組書單，計有：1.草蜢的幸福雜貨店。2.大海的孩子。3.泡泡男孩。4.我的馬拉松故事。5.星期天的音樂教室。6.作弊。7.值日追書生。8.人生重開機。9.終點站下車、10馬背上的少女。\r\n國中組書單，計有：1.國學潮人誌，古人超有料。2.超能少年1：超能研究社。3.誰搬走了我的乳酪？。4.那些散落的星星。5.華氏零度。6.少年噶瑪蘭。7.山與林的深處。8.童年母愛欠缺 長大後的妳，如何療癒對愛的匱乏，健全心中缺損的母親角色。', `organizer`='苗栗縣立圖書館', `address`='苗栗縣西湖鄉', `start_date`='2025-01-02 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='西湖鄉（苗栗縣）=', `latitude`=24.54153218, `longitude`=120.7614144, `ticket_price`='無資料', `source_url`='https://lib.miaoli.gov.tw/wSite/mp', `image_url`='[]';
