INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676f0a9b26b32458d4363262', '無資料', '   「百花盛開- 謝富紀油畫創作展」訂於2025年1月2日至2月24日（週一至週五）AM9:00~PM12:00/PM13:30~PM17:00在財團法人英才文教基金會全球藝術中心（台中市西屯區府會園道179號4樓）展出，開幕式訂於1月8日（週三）下午2:30舉行，誠摯邀請愛好藝術的朋友蒞臨參觀指教。\r\n\r\n    1939年出生的謝富紀，生長於彰化縣北斗鎮，五歲時即酷愛塗鴉，連牆壁及塌塌米也不放過，父母不但不阻止，甚至還會鼓勵她。求學期間常受到師長稱讚與鼓勵，讓她加深了對繪畫的興趣與信心。1957年學校推薦她到美術專科學校就讀，但她同時通過國家考試，分發到學校擔任家政課程及行政工作，因此放棄了美專的學習機會。三年後離職走進家庭，1979年改任台南私立三一幼稚園園長，十年後才有時間請林鴻文老師指導繪畫，一年後移民美國紐約而暫停學習。2010年曾在台中蒙恩教會繪畫班向詹前毅老師學習，接著又回紐約陪伴年邁的母親，因此又中斷繪畫。2013年巧遇黃譓丞老師，在家人的鼓勵下繼續習畫至今。她終於圓了畫畫的心願，享受美夢成真的喜悅，梵谷說：「我夢想著繪畫，我畫我的夢想」恰是謝富紀人生的最佳寫照。\r\n\r\n    謝富紀以自身經歷作為創作的泉源，將生命經歷中愛的花朵，以及季節變化的感受等，透過不一樣的想法，運用美的形式，重新詮釋成為自己的繪畫語言。她的每幅作品，都體現「活到老，學到老」求新求變的創意，畫出她內在的心象。她強調，在學習過程中，手腦心並用，情緒疏導，心靈釋放，發揮想像的空間，腦力退化緩慢，豐富了多采多姿的生命，也享受了快樂的晚年。\r\n', '財團法人英才文教基金會', '臺中市西屯區府會園道179號4樓', '財團法人英才文教基金會全球藝術中心', 24.1604928, 120.6455336, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='   「百花盛開- 謝富紀油畫創作展」訂於2025年1月2日至2月24日（週一至週五）AM9:00~PM12:00/PM13:30~PM17:00在財團法人英才文教基金會全球藝術中心（台中市西屯區府會園道179號4樓）展出，開幕式訂於1月8日（週三）下午2:30舉行，誠摯邀請愛好藝術的朋友蒞臨參觀指教。\r\n\r\n    1939年出生的謝富紀，生長於彰化縣北斗鎮，五歲時即酷愛塗鴉，連牆壁及塌塌米也不放過，父母不但不阻止，甚至還會鼓勵她。求學期間常受到師長稱讚與鼓勵，讓她加深了對繪畫的興趣與信心。1957年學校推薦她到美術專科學校就讀，但她同時通過國家考試，分發到學校擔任家政課程及行政工作，因此放棄了美專的學習機會。三年後離職走進家庭，1979年改任台南私立三一幼稚園園長，十年後才有時間請林鴻文老師指導繪畫，一年後移民美國紐約而暫停學習。2010年曾在台中蒙恩教會繪畫班向詹前毅老師學習，接著又回紐約陪伴年邁的母親，因此又中斷繪畫。2013年巧遇黃譓丞老師，在家人的鼓勵下繼續習畫至今。她終於圓了畫畫的心願，享受美夢成真的喜悅，梵谷說：「我夢想著繪畫，我畫我的夢想」恰是謝富紀人生的最佳寫照。\r\n\r\n    謝富紀以自身經歷作為創作的泉源，將生命經歷中愛的花朵，以及季節變化的感受等，透過不一樣的想法，運用美的形式，重新詮釋成為自己的繪畫語言。她的每幅作品，都體現「活到老，學到老」求新求變的創意，畫出她內在的心象。她強調，在學習過程中，手腦心並用，情緒疏導，心靈釋放，發揮想像的空間，腦力退化緩慢，豐富了多采多姿的生命，也享受了快樂的晚年。\r\n', `organizer`='財團法人英才文教基金會', `address`='臺中市西屯區府會園道179號4樓', `location`='財團法人英才文教基金會全球藝術中心', `latitude`=24.1604928, `longitude`=120.6455336, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676f0a9d26b32458d4363269', '無資料', '收到宋少卿老師意外過世的新聞\r\n\r\n【喜劇團】立即幫他辦理了一場告別式\r\n各路英雄好漢、喜劇豪傑們紛紛趕來致意\r\n觀禮民眾、親朋好友都到齊了，但禮儀公司還沒來？\r\n喜劇團團長表示「喜劇人要有喜劇人自己的弔唁方式」\r\n各路人馬各自表演一段跟宋老師有關的表演向他致意\r\n是烏龍新聞？是喜劇追思大會？還是宋老師的幻想？\r\n《今夜無法說相聲之大師走了》不是單純的傳統相聲表演！是一齣用舞台劇包裝相聲、脫口秀、漫才、素描喜劇的喜劇作品\r\n \r\n\r\n朱德剛、宋少卿、蕭志瑋(八弟)、翁銓偉\r\n呂濟寬、陳妙音、林品澄、劉毓謙，八位演員笑爆告別式現場', '喜劇團', '臺中市清水區忠貞路21號', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='收到宋少卿老師意外過世的新聞\r\n\r\n【喜劇團】立即幫他辦理了一場告別式\r\n各路英雄好漢、喜劇豪傑們紛紛趕來致意\r\n觀禮民眾、親朋好友都到齊了，但禮儀公司還沒來？\r\n喜劇團團長表示「喜劇人要有喜劇人自己的弔唁方式」\r\n各路人馬各自表演一段跟宋老師有關的表演向他致意\r\n是烏龍新聞？是喜劇追思大會？還是宋老師的幻想？\r\n《今夜無法說相聲之大師走了》不是單純的傳統相聲表演！是一齣用舞台劇包裝相聲、脫口秀、漫才、素描喜劇的喜劇作品\r\n \r\n\r\n朱德剛、宋少卿、蕭志瑋(八弟)、翁銓偉\r\n呂濟寬、陳妙音、林品澄、劉毓謙，八位演員笑爆告別式現場', `organizer`='喜劇團', `address`='臺中市清水區忠貞路21號', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676f0a9f26b32458d436326c', '調皮的浣熊-兒童美術研習班成果展', '在港區藝術中心小小的角落裡，有一群小畫家，正用無限的創意與熱情，妝點屬於他們的藝術銀河系！\r\n\r\n★調皮的浣熊\r\n媒材：炭筆+粉彩\r\n展覽日期：114/1/1-3/31\r\n展出成員：大兒童美術B班\r\n展覽地點：港區小藝廊(雅書廊川堂)\r\n \r\n\r\n◆授課老師：張美翎\r\n◆大兒童美術對象：小學二～六年級\r\n◆課程內容：\r\n透過藝術欣賞及多元文化的認識，提升兒童的美感素養，建立其鑑賞能力及技法描繪能力。結合現代藝術多元媒材與自由創作方式，建立兒童自信展現自我特質。包含繪畫、素描、媒材運用、立體捏塑等。\r\n\r\n114年春季藝文研習班正受理報名\r\n大兒童美術A：星期五19:00 – 21:00\r\n大兒童美術B：星期六10:00 – 12:00', '臺中市政府文化局', '臺中市清水區忠貞路21號', '2025-01-01 00:00:00', '2025-03-31 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=6834e2802dd24a85b382826e8551616b', '[]') ON DUPLICATE KEY UPDATE `activity_name`='調皮的浣熊-兒童美術研習班成果展', `description`='在港區藝術中心小小的角落裡，有一群小畫家，正用無限的創意與熱情，妝點屬於他們的藝術銀河系！\r\n\r\n★調皮的浣熊\r\n媒材：炭筆+粉彩\r\n展覽日期：114/1/1-3/31\r\n展出成員：大兒童美術B班\r\n展覽地點：港區小藝廊(雅書廊川堂)\r\n \r\n\r\n◆授課老師：張美翎\r\n◆大兒童美術對象：小學二～六年級\r\n◆課程內容：\r\n透過藝術欣賞及多元文化的認識，提升兒童的美感素養，建立其鑑賞能力及技法描繪能力。結合現代藝術多元媒材與自由創作方式，建立兒童自信展現自我特質。包含繪畫、素描、媒材運用、立體捏塑等。\r\n\r\n114年春季藝文研習班正受理報名\r\n大兒童美術A：星期五19:00 – 21:00\r\n大兒童美術B：星期六10:00 – 12:00', `organizer`='臺中市政府文化局', `address`='臺中市清水區忠貞路21號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=6834e2802dd24a85b382826e8551616b', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676f0aa026b32458d4363270', '名間鄉立圖書館114年度讀書會', '本讀書會邀請老師帶領閱讀或專題演講，學員分享心得，知識交流。參加對象：對閱讀有興趣之社會民眾均可報名參加，名額30人。報名時間：即日起（星期一休館）請洽名間鄉立圖書館辦理報名。洽詢電話：049-2734848、傳真：049-2738097。', '南投縣名間鄉公所', '南投縣名間鄉彰南路42-2號三樓', '2025-01-14 00:00:00', '2025-12-09 00:00:00', '南投縣名間鄉立圖書館', 23.8385841, 120.702733, '無資料', 'http://www.mnjn.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='名間鄉立圖書館114年度讀書會', `description`='本讀書會邀請老師帶領閱讀或專題演講，學員分享心得，知識交流。參加對象：對閱讀有興趣之社會民眾均可報名參加，名額30人。報名時間：即日起（星期一休館）請洽名間鄉立圖書館辦理報名。洽詢電話：049-2734848、傳真：049-2738097。', `organizer`='南投縣名間鄉公所', `address`='南投縣名間鄉彰南路42-2號三樓', `start_date`='2025-01-14 00:00:00', `end_date`='2025-12-09 00:00:00', `location`='南投縣名間鄉立圖書館', `latitude`=23.8385841, `longitude`=120.702733, `ticket_price`='無資料', `source_url`='http://www.mnjn.gov.tw/', `image_url`='[]';
