INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6770747026b32458d4363286', '1202茶文學班(廖亭朝)', '  臺北市藝文推廣處114年春季班  \n\n			班序號:1202   班名: 茶文學班  課程規劃表  教師：廖亭朝\n			\n		\n		\n			\n			項次\n			\n			\n			日期\n			\n			\n			教學內容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/3\n			\n			\n			好山.好水.出好茶,來看茶的魔力變化\n\n			一年四季茶的變化及製作方式,辨識茶的種類及品飲方式\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/10\n			\n			\n			師父引進門,修行在泡茶\n\n			不留意泡茶動作,就泡不出好茶,正確沖茶觀念,可喝出香氣溢人的茶香\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/17\n			\n			\n			茶遊記,看茶壺不同風貌的演進\n\n			各類茶壺製方法及藝術鑑賞.選對壺具必定泡出美妙茶湯\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/24\n			\n			\n			春暖花開是喝茶的季節\n\n			春天美麗季節,正是齒頰留香喝好茶時刻,一杯茶,暖暖坎在心內\n			\n		\n		\n			\n			第5堂課\n			\n			\n			3/31\n			\n			\n			津甘溫,喝杯茶重養生\n\n			四季茶的各種風味,齡人迷戀,再配合身心養生樂趣\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/7\n			\n			\n			台灣最南端讓人印象深刻的茶\n\n			百年的茶味,飄香在南端,遙想先人們對這片土地的愛護\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/14\n			\n			\n			台灣高山茶新興產地在何處?\n\n			高山茶最後處女地,多元化的風味,是令人珍惜印象深刻\n			\n		\n		\n			\n			第8堂課\n			\n			\n			4/21\n			\n			\n			中國福建烏龍茶知多少?\n\n			閩北與閩南的產地,誕生多元化的飲茶故事,好好去品味\n			\n		\n		\n			\n			第9堂課\n			\n			\n			4/28\n			\n			\n			一場穿越東方到西方的紅茶故事\n\n			紅茶的起源地,飄香到不同地方,奧妙的風格展現在眾人心理\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/5\n			\n			\n			異國茶風味的簡述介紹\n\n			欣賞不同國家茶道文化精隨,觸發不同茶文化的體會\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/12\n			\n			\n			薪火相傳客家飲茶文化\n\n			客家人喝茶習性,帶給我們不同文化的思維與尊重\n			\n		\n		\n			\n			第12堂課\n			\n			\n			5/19\n			\n			\n			尋找茶香,打開普洱茶的新篇章嗎?\n\n			百年的產茶地揭開神秘面紗,是讓人值得欣賞獨特風味\n			\n		\n		\n			\n			第13堂課\n			\n			\n			5/26\n			\n			\n			得獎茶,大家一起來好喝\n\n			好的茶品,經專家評層層鑑定把關,讓我們以欣賞角度,體會得獎茶的優勢\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/2\n			\n			\n			翻開一篇篇帝王與茶的風韻雅事\n\n			帝王主宰千年飲茶的習性,代代相傳到至今,另人值得玩味\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/9\n			\n			\n			茶席結業式泡出不樣的茶\n\n			不同種類的茶,配合呈現該茶的特性,設計出相得益章的意境\n			\n		\n	\n\n\n ', '臺北市藝文推廣處', '105  臺北市松山區八德路三段25號(臺北市藝文推廣處)', '2025-03-03 00:00:00', '2025-06-09 00:00:00', '綜合教室-1', 25.0483541, 121.5523447, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40148', '[]') ON DUPLICATE KEY UPDATE `activity_name`='1202茶文學班(廖亭朝)', `description`='  臺北市藝文推廣處114年春季班  \n\n			班序號:1202   班名: 茶文學班  課程規劃表  教師：廖亭朝\n			\n		\n		\n			\n			項次\n			\n			\n			日期\n			\n			\n			教學內容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/3\n			\n			\n			好山.好水.出好茶,來看茶的魔力變化\n\n			一年四季茶的變化及製作方式,辨識茶的種類及品飲方式\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/10\n			\n			\n			師父引進門,修行在泡茶\n\n			不留意泡茶動作,就泡不出好茶,正確沖茶觀念,可喝出香氣溢人的茶香\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/17\n			\n			\n			茶遊記,看茶壺不同風貌的演進\n\n			各類茶壺製方法及藝術鑑賞.選對壺具必定泡出美妙茶湯\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/24\n			\n			\n			春暖花開是喝茶的季節\n\n			春天美麗季節,正是齒頰留香喝好茶時刻,一杯茶,暖暖坎在心內\n			\n		\n		\n			\n			第5堂課\n			\n			\n			3/31\n			\n			\n			津甘溫,喝杯茶重養生\n\n			四季茶的各種風味,齡人迷戀,再配合身心養生樂趣\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/7\n			\n			\n			台灣最南端讓人印象深刻的茶\n\n			百年的茶味,飄香在南端,遙想先人們對這片土地的愛護\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/14\n			\n			\n			台灣高山茶新興產地在何處?\n\n			高山茶最後處女地,多元化的風味,是令人珍惜印象深刻\n			\n		\n		\n			\n			第8堂課\n			\n			\n			4/21\n			\n			\n			中國福建烏龍茶知多少?\n\n			閩北與閩南的產地,誕生多元化的飲茶故事,好好去品味\n			\n		\n		\n			\n			第9堂課\n			\n			\n			4/28\n			\n			\n			一場穿越東方到西方的紅茶故事\n\n			紅茶的起源地,飄香到不同地方,奧妙的風格展現在眾人心理\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/5\n			\n			\n			異國茶風味的簡述介紹\n\n			欣賞不同國家茶道文化精隨,觸發不同茶文化的體會\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/12\n			\n			\n			薪火相傳客家飲茶文化\n\n			客家人喝茶習性,帶給我們不同文化的思維與尊重\n			\n		\n		\n			\n			第12堂課\n			\n			\n			5/19\n			\n			\n			尋找茶香,打開普洱茶的新篇章嗎?\n\n			百年的產茶地揭開神秘面紗,是讓人值得欣賞獨特風味\n			\n		\n		\n			\n			第13堂課\n			\n			\n			5/26\n			\n			\n			得獎茶,大家一起來好喝\n\n			好的茶品,經專家評層層鑑定把關,讓我們以欣賞角度,體會得獎茶的優勢\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/2\n			\n			\n			翻開一篇篇帝王與茶的風韻雅事\n\n			帝王主宰千年飲茶的習性,代代相傳到至今,另人值得玩味\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/9\n			\n			\n			茶席結業式泡出不樣的茶\n\n			不同種類的茶,配合呈現該茶的特性,設計出相得益章的意境\n			