INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6770747226b32458d43632a8', '5106活力熱舞班 (歐家齊)', '臺北市藝文推廣處114年春季\n\n			班名: 活力熱舞 班　課程規劃表　教師：歐家齊 \n			\n		\n		\n			\n			項次\n			\n			\n			日期\n			\n			\n			教學內容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/7\n			\n			\n			介紹課程，讓學員認識各種舞風，並著重於讓學員瞭解身體的各個關節、如何不受傷的使用身體，享受舞蹈。\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/14\n			\n			\n			暖身、關節活動、肌肉的延展以及肌肉的肌耐力的訓練、動作分解。\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/21\n			\n			\n			暖身、關節活動、肌肉的延展以及肌肉的肌耐力及爆發力的訓練，並要求正確度、動作分解。\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/28\n			\n			\n			暖身、關節的運用加上腳上的步伐以訓練協調度、動作分解。完成舞碼的1/4，並加以練習至熟練。\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/11\n			\n			\n			暖身、關節的運用以及延展動作加上腳上的步伐、動作分解。\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/18\n			\n			\n			暖身、關節的運用以及延展動作加上腳上的步伐、動作分解。\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/25\n			\n			\n			暖身、關節運用、延展動作的流動、動作分解。\n\n			完成舞碼的2/4，並加以練習至熟練。\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5/2\n			\n			\n			暖身、關節運用、延展動作的流動,加強爆 發力的動作訓練、動作分解。\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5/9\n			\n			\n			暖身、關節的運用以及延展動作加上腳上的步伐、動作分解。\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/16\n			\n			\n			暖身、關節的運用以及延展動作加上腳上的步伐、動作分解。\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/23\n			\n			\n			暖身、訓練協調以及方向感分解動作加上音樂。完成舞碼的3/4，並加以練習至熟練。\n			\n		\n		\n			\n			第12堂課\n			\n			\n			6/6\n			\n			\n			暖身、訓練學員瞭解並運用空間的變化、分解動作加上音樂。\n			\n		\n		\n			\n			第13堂課\n			\n			\n			6/13\n			\n			\n			暖身、要求音樂的準確、身體的協調及動作的美感，分解動作加上音樂。完成舞碼，並加以練習至熟練。分組觀摩。\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/20\n			\n			\n			暖身、要求學生舞碼中音樂的準確、身體的協調及動作的美感，加入情感及生動的表情，達到開心舞蹈肢體。分組觀摩。\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/27\n			\n			\n			暖身、要求學生舞碼中音樂的準確、身體的協調及動作的美感，加入情感及生動的表情，達到開心舞蹈肢體。成果呈現。\n			\n		\n	\n\n\n ', '臺北市藝文推廣處', '105  臺北市松山區八德路三段25號(臺北市藝文推廣處)', '2025-03-07 00:00:00', '2025-06-27 00:00:00', '舞蹈教室-1', 25.0483541, 121.5523447, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40206', '[]') ON DUPLICATE KEY UPDATE `activity_name`='5106活力熱舞班 (歐家齊)', `description`='臺北市藝文推廣處114年春季\n\n			班名: 活力熱舞 班　課程規劃表　教師：歐家齊 \n			\n		\n		\n			\n			項次\n			\n			\n			日期\n			\n			\n			教學內容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/7\n			\n			\n			介紹課程，讓學員認識各種舞風，並著重於讓學員瞭解身體的各個關節、如何不受傷的使用身體，享受舞蹈。\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/14\n			\n			\n			暖身、關節活動、肌肉的延展以及肌肉的肌耐力的訓練、動作分解。\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/21\n			\n			\n			暖身、關節活動、肌肉的延展以及肌肉的肌耐力及爆發力的訓練，並要求正確度、動作分解。\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/28\n			\n			\n			暖身、關節的運用加上腳上的步伐以訓練協調度、動作分解。完成舞碼的1/4，並加以練習至熟練。\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/11\n			\n			\n			暖身、關節的運用以及延展動作加上腳上的步伐、動作分解。\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/18\n			\n			\n			暖身、關節的運用以及延展動作加上腳上的步伐、動作分解。\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/25\n			\n			\n			暖身、關節運用、延展動作的流動、動作分解。\n\n			完成舞碼的2/4，並加以練習至熟練。\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5/2\n			\n			\n			暖身、關節運用、延展動作的流動,加強爆 發力的動作訓練、動作分解。\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5/9\n			\n			\n			暖身、關節的運用以及延展動作加上腳上的步伐、動作分解。\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/16\n			\n			\n			暖身、關節的運用以及延展動作加上腳上的步伐、動作分解。\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/23\n			\n			\n			暖身、訓練協調以及方向感分解動作加上音樂。完成舞碼的3/4，並加以練習至熟練。\n			\n		\n		\n			\n			第12堂課\n			\n			\n			6/6\n			\n			\n			暖身、訓練學員瞭解並運用空間的變化、分解動作加上音樂。\n			\n		\n		\n			\n			第13堂課\n			\n			\n			6/13\n			\n			\n			暖身、要求音樂的準確、身體的協調及動作的美感，分解動作加上音樂。完成舞碼，並加以練習至熟練。分組觀摩。\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/20\n			\n			\n			暖身、要求學生舞碼中音樂的準確、身體的協調及動作的美感，加入情感及生動的表情，達到開心舞蹈肢體。分組觀摩。\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/27\n			\n			\n			暖身、要求學生舞碼中音樂的準確、身體的協調及動作的美感，加入情感及生動的表情，達到開心舞蹈肢體。成果呈現。\n			\n		\n	\n\n\n ', `organizer`='臺北市藝文推廣處', `address`='105  臺北市松山區八德路三段25號(臺北市藝文推廣處)', `start_date`='2025-03-07 00:00:00', `end_date`='2025-06-27 00:00:00', `location`='舞蹈教室-1', `latitude`=25.0483541, `longitude`=121.5523447, `ticket_price`='2