INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6770747226b32458d43632a9', '5110墨韻飄香書法班 (吳麗琴)', '臺北市藝文推廣處114年春季\n\n			    班名:墨韻飄香書法班　課程規劃表　教師：吳麗琴\n			\n		\n		\n			\n			項次\n			\n			\n			日期\n			\n			\n			教學內容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/7\n			\n			\n			相見歡、班務活動、課程介紹、（文房用具、選帖、課程準備）\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/14\n			\n			\n			分組示範：各書體概論〈示範〉，全班習作研討。\n\n			實作練習以學員所選碑帖為範本。\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/21\n			\n			\n			實作基礎運筆示範和練習、書體源流及書體簡介\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/28\n			\n			\n			行書賞析入門、實作個別指導與全班習作研討。\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/11\n			\n			\n			分組示範：楷書、行楷書〈講義〉，全班習作修改訂正。\n\n			實作練習以學員所選碑帖為範本。\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/18\n			\n			\n			楷書講解，實作練習、習作研討。以學員所選碑帖為範本。\n			\n		\n		\n			\n			第7堂課\n			\n			\n			  4/25\n			\n			\n			臨摹要領由講師示範、碑帖筆法之比較與習作研討，習作訂正。\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5/2\n			\n			\n			隸書專題：行書介紹〈講義〉\n\n			實作練習以學員所  選碑帖為範本。\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5/9\n			\n			\n			臨摹要領由講師示範，實作個別指導與全班習作研討。\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/16\n			\n			\n			作品格式講解，小品作品實驗。\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/23\n			\n			\n			小品作品完成。\n			\n		\n		\n			\n			第12堂課\n			\n			\n			6/6\n			\n			\n			以各學員所選書體、書帖，嘗試完成期末作品。\n			\n		\n		\n			\n			第13堂課\n			\n			\n			6/13\n			\n			\n			書法文創示範與完成\n\n			作品鈐印、作品裱裝款式講解與欣賞。\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/20\n			\n			\n			作品完成。\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/27\n			\n			\n			完成本學期書法實驗作品。\n			\n		\n	\n\n\n ', '臺北市藝文推廣處', '105  臺北市松山區八德路三段25號(臺北市藝文推廣處)', '2025-03-07 00:00:00', '2025-06-27 00:00:00', '水墨教室', 25.0483541, 121.5523447, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40207', '[]') ON DUPLICATE KEY UPDATE `activity_name`='5110墨韻飄香書法班 (吳麗琴)', `description`='臺北市藝文推廣處114年春季\n\n			    班名:墨韻飄香書法班　課程規劃表