INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6770747226b32458d43632af', '5301陶笛-陶醉在笛聲班 (吳欣潓)', '臺北市藝文推廣處114年春季\n\n			班名: 陶笛-陶醉在笛聲班　課程規劃表　教師：吳欣潓\n			\n		\n		\n			\n			項次\n			\n			\n			日期\n			\n			\n			教學內容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/7\n			\n			\n			認識各式陶笛、陶笛的選擇、陶笛的保養，吹奏示範、持笛法、指法指序音階概念、運舌法。\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/14\n			\n			\n			簡譜視譜法(調性判斷、認識記號)，吹奏法、吐音運舌法、呼吸法、個別指導，樂曲練習。\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/21\n			\n			\n			練習經驗與方法、簡譜視譜法(節奏變化)，吹奏法，樂曲練習。\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/28\n			\n			\n			長音練習方法、簡譜視譜法(連結線、圓滑線)，吹奏法，樂曲練習。\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/11\n			\n			\n			簡譜視譜法(短音、斷奏)，吹奏法，樂曲練習。\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/18\n			\n			\n			節奏變化訓練，吹奏法，樂曲練習。\n			\n		\n		\n			\n			第7堂課\n			\n			\n			  4/25\n			\n			\n			裝飾音、打音，陶笛特殊音效與音色，吹奏法，樂曲練習。\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5/2\n			\n			\n			認識腹震音(氣顫音)。吹奏法、個別指導，樂曲練習。\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5/9\n			\n			\n			技巧運用、個別指導，樂曲練習。\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/16\n			\n			\n			和弦運用、雙聲部合奏，樂曲練習。\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/23\n			\n			\n			技巧運用、個別指導，樂曲練習。\n			\n		\n		\n			\n			第12堂課\n			\n			\n			6/6\n			\n			\n			曲式分析，分部合奏，樂曲複習。\n			\n		\n		\n			\n			第13堂課\n			\n			\n			6/13\n			\n			\n			總複習、個別指導，樂曲練習。\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/20\n			\n			\n			總複習，團體指導，樂曲練習。\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/27\n			\n			\n			期末成果展\n			\n		\n	\n\n\n ', '臺北市藝文推廣處', '105  臺北市松山區八德路三段25號(臺北市藝文推廣處)', '2025-03-07 00:00:00', '2025-06-27 00:00:00', '歌唱教室', 25.0483541, 121.5523447, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40215', '[]') ON DUPLICATE KEY UPDATE `activity_name`='5301陶笛-陶醉在笛聲班 (吳欣潓)', `description`='臺北市藝文推廣處114年春季\n\n			班名: 陶笛-陶醉在笛聲班　課程規劃表　教師：吳欣潓\n			\n		\n		\n			\n			項次\n			\n			\n			日期\n			\n			\n			教學內容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/7\n			\n			\n			認識各式陶笛、陶笛的選擇、陶笛的保養，吹奏示範、持笛法、指法指序音階概念、運舌法。\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/14\n			\n			\n			簡譜視譜法(調性判斷、認識記號)，吹奏法、吐音運舌法、呼吸法、個別指導，樂曲練習。\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/21\n			\n			\n			練習經驗與方法、簡譜視譜法(節奏變化)，吹奏法，樂曲練習。\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/28\n			\n			\n			長音練習方法、簡譜視譜法(連結線、圓滑線)，吹奏法，樂曲練習。\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/11\n			\n			\n			簡譜視譜法(短音、斷奏)，吹奏法，樂曲練習。\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/18\n			\n			\n			節奏變化訓練，吹奏法，樂曲練習。\n			\n		\n		\n			\n			第7堂課\n			\n			\n			  4/25\n			\n			\n			裝飾音、打音，陶笛特殊音效與音色，吹奏法，樂曲練習。\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5/2\n			\n			\n			認識腹震音(氣顫音)。吹奏法、個別指導，樂曲練習。\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5/9\n			\n			\n			技巧運用、個別指導，樂曲練習。\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/16\n			\n			\n			和弦運用、雙聲部合奏，樂曲練習。\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/23\n			\n			\n			技巧運用、個別指導，樂曲練習。\n			\n		\n		\n			\n			第12堂課\n			\n			\n			6/6\n			\n			\n			曲式分析，分部合奏，樂曲複習。\n			\n		\n		\n			\n			第13堂課\n			\n			\n			6/13\n			\n			\n			總複習、個別指導，樂曲練習。\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/20\n			\n			\n			總複習，團體指導，樂曲練習。\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/27\n			\n			\n			期末成果展\n			\n		\n	\n\n\n ', `organizer`='臺北市藝文推廣處', `address`='105  臺北市松山區八德路三段25號(臺北市藝文推廣處)', `start_date`='2025-03-07 00:00:00', `end_date`='2025-06-27 00:00:00', `location`='歌唱教室', `latitude`=25.0483541, `longitude`=121.5523447, `ticket_price`='2000', `source_url`='https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40215', `image_url`='[]';
