INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6770747326b32458d43632c3', '3201聲樂健聲進階班 (陳詩縈/伴奏王昱婷)', '臺北市藝文推廣處114年春季\n\n			班名: 聲樂健聲進階班　課程規劃表　教師：陳詩縈\n			\n		\n		\n			\n			項次\n			\n			\n			日期\n			\n			\n			教學內容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			03/05\n			\n			\n			課程解說、班務處理、暖身運動、正確呼吸練習。歌唱核心肌肉群之運動並融入發聲練習。(王昱婷老師)\n			\n		\n		\n			\n			第2堂課\n			\n			\n			03/12\n			\n			\n			以氣養聲，運用健康的歌唱方式保健聲帶、正確呼吸練習、基本發聲、義大利文歌曲教唱(王昱婷老師)\n			\n		\n		\n			\n			第3堂課\n			\n			\n			03/19\n			\n			\n			聲樂發聲理論概述、暖身運動、正確呼吸練習、基本發聲、練習曲練唱、義大利文歌曲教唱(王昱婷老師)\n			\n		\n		\n			\n			第4堂課\n			\n			\n			03/26\n			\n			\n			基本練習同前、練習曲練唱、外文藝術歌曲及歌劇選曲演唱，個別聲音指導2、外文歌曲教唱 (王昱婷老師)\n			\n		\n		\n			\n			第5堂課\n			\n			\n			04/02\n			\n			\n			基本練習同前、練習曲練唱、外文藝術歌曲及歌劇選曲演唱，個別聲音指導3、外文歌曲教唱(王昱婷老師)\n			\n		\n		\n			\n			第6堂課\n			\n			\n			04/09\n			\n			\n			基本練習同前、練習曲練唱、個別聲音指導4、中文歌曲教唱 (王昱婷老師)\n			\n		\n		\n			\n			第7堂課\n			\n			\n			04/16\n			\n			\n			基本練習同前、練習曲練唱、個別聲音指導5、中文藝術歌曲教唱 (王昱婷老師)\n			\n		\n		\n			\n			第8堂課\n			\n			\n			04/23\n			\n			\n			基本練習同前、練習曲練唱、外文藝術歌曲及歌劇選曲演唱，個別聲音指導6、台語歌曲教唱 (王昱婷老師)\n			\n		\n		\n			\n			第9堂課\n			\n			\n			04/30\n			\n			\n			基本練習同前、練習曲練唱、外文藝術歌曲及歌劇選曲演唱，個別聲音指導7、台語歌曲教唱 (王昱婷老師)\n			\n		\n		\n			\n			第10堂課\n			\n			\n			05/07\n			\n			\n			基本練習同前、練習曲練唱、外文藝術歌曲及歌劇選曲演唱，個別聲音指導8、重唱教唱1 (王昱婷老師)\n			\n		\n		\n			\n			第11堂課\n			\n			\n			05/14\n			\n			\n			基本練習同前、練習曲練唱、外文藝術歌曲及歌劇選曲演唱，個別聲音指導9、重唱教唱2 (王昱婷老師)\n			\n		\n		\n			\n			第12堂課\n			\n			\n			05/21\n			\n			\n			基本練習同前、練習曲練唱、外文藝術歌曲及歌劇選曲演唱，個別聲音指導10、重唱教唱3 (王昱婷老師)\n			\n		\n		\n			\n			第13堂課\n			\n			\n			05/28\n			\n			\n			發聲、外文藝術歌曲及歌劇選曲演唱 (王昱婷老師)\n			\n		\n		\n			\n			第14堂課\n			\n			\n			06/04\n			\n			\n			成果發表會綵排 (王昱婷老師)\n			\n		\n		\n			\n			第15堂課\n			\n			\n			06/12\n			\n			\n			成果發表會 (王昱婷老師)\n			\n		\n	\n\n\n ', '臺北市藝文推廣處', '105  臺北市松山區八德路三段25號(臺北市藝文推廣處)', '2025-03-05 00:00:00', '20