INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6770747326b32458d43632cb', '3108輕鬆學水彩 (成志偉)', '臺北市藝文推廣處114年春季\n\n			班名:  輕鬆學水彩 　班　課程規劃表　教師：成志偉　　\n			\n		\n		\n			\n			項次\n			\n			\n			日期\n			\n			\n			教學內容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/5\n			\n			\n			認識水彩\n\n			水彩用具材料的介紹與正確使用方法。水彩技法原理講解。\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/12\n			\n			\n			風景篇1：山巒\n\n			學習渲染法。色彩漸層、水份掌握的基礎練習。\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/19\n			\n			\n			風景篇2：山林\n\n			分析樹的造型，學習如何簡化。運筆、勾勒的基礎練習。\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/26\n			\n			\n			風景篇3：海景\n\n			運用渲染法暈染天空，編排組合岩石與海浪，以重疊技法修整完成。\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/2\n			\n			\n			風景篇4：溪流\n\n			運用渲染法營造氣氛，重疊技法完成水流與溪石。\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/9\n			\n			\n			風景篇5：溪流\n\n			運用渲染法營造氣氛，重疊技法完成水流與溪石。\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/16\n			\n			\n			風景篇6：鄉村\n\n			分析房子的結構，完成草稿。上色由遠到近，以重疊技法完成。\n			\n		\n		\n			\n			第8堂課\n			\n			\n			4/23\n			\n			\n			風景篇7：鄉村\n\n			分析房子的結構，完成草稿。上色由遠到近，以重疊技法完成。\n			\n		\n		\n			\n			第9堂課\n			\n			\n			4/30\n			\n			\n			植物花卉篇1\n\n			主要運用渲染與縫合技法構成畫面。 最後再以重疊技法修整完成。\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/7\n			\n			\n			植物花卉篇2\n\n			主要運用渲染與縫合技法構成畫面。 最後再以重疊技法修整完成。\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/14\n			\n			\n			植物花卉篇3\n\n			主要運用渲染與縫合技法構成畫面。 最後再以重疊技法修整完成。\n			\n		\n		\n			\n			第12堂課\n			\n			\n			5/21\n			\n			\n			可愛動物篇1\n\n			以局部特寫描繪動物的特徵，背景以渲染技法表現\n			\n		\n		\n			\n			第13堂課\n			\n			\n			5/28\n\n			/\n\n			 \n			\n			\n			可愛動物篇2\n\n			以局部特寫描繪動物的特徵，背景以渲染技法表現\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/4\n			\n			\n			可愛動物篇3\n\n			以局部特寫描繪動物的特徵，背景以渲染技法表現\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/11\n			\n			\n			可愛動物篇4\n\n			以局部特寫描繪動物的特徵，背景以渲染技法表現\n			\n		\n	\n\n\n ', '臺北市藝文推廣處', '105  臺北市松山區八德路三段25號(臺北市藝文推廣處)', '2025-03-05 00:00:00', '2025-06-11 00:00:00', '美術教室', 25.0483541, 121.5523447, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40222', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3108輕鬆學水彩 (成志偉)', `description`='臺北市藝文推廣處114年春季\n\n			班名:  輕鬆學水彩 　班　課程規劃表　教師：成志偉　　\n			\n		\n		\n			\n			項次\n			\n			\n			日期\n			\n			\n			教學內容\n			\n		\n		\n			\n			第1堂課\n			\n			\n			3/5\n			\n			\n			認識水彩\n\n			水彩用具材料的介紹與正確使用方法。水彩技法原理講解。\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3/12\n			\n			\n			風景篇1：山巒\n\n			學習渲染法。色彩漸層、水份掌握的基礎練習。\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3/19\n			\n			\n			風景篇2：山林\n\n			分析樹的造型，學習如何簡化。運筆、勾勒的基礎練習。\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3/26\n			\n			\n			風景篇3：海景\n\n			運用渲染法暈染天空，編排組合岩石與海浪，以重疊技法修整完成。\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4/2\n			\n			\n			風景篇4：溪流\n\n			運用渲染法營造氣氛，重疊技法完成水流與溪石。\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4/9\n			\n			\n			風景篇5：溪流\n\n			運用渲染法營造氣氛，重疊技法完成水流與溪石。\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4/16\n			\n			\n			風景篇6：鄉村\n\n			分析房子的結構，完成草稿。上色由遠到近，以重疊技法完成。\n			\n		\n		\n			\n			第8堂課\n			\n			\n			4/23\n			\n			\n			風景篇7：鄉村\n\n			分析房子的結構，完成草稿。上色由遠到近，以重疊技法完成。\n			\n		\n		\n			\n			第9堂課\n			\n			\n			4/30\n			\n			\n			植物花卉篇1\n\n			主要運用渲染與縫合技法構成畫面。 最後再以重疊技法修整完成。\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5/7\n			\n			\n			植物花卉篇2\n\n			主要運用渲染與縫合技法構成畫面。 最後再以重疊技法修整完成。\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5/14\n			\n			\n			植物花卉篇3\n\n			主要運用渲染與縫合技法構成畫面。 最後再以重疊技法修整完成。\n			\n		\n		\n			\n			第12堂課\n			\n			\n			5/21\n			\n			\n			可愛動物篇1\n\n			以局部特寫描繪動物的特徵，背景以渲染技法表現\n			\n		\n		\n			\n			第13堂課\n			\n			\n			5/28\n\n			/\n\n			 \n			\n			\n			可愛動物篇2\n\n			以局部特寫描繪動物的特徵，背景以渲染技法表現\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6/4\n			\n			\n			可愛動物篇3\n\n			以局部特寫描繪動物的特徵，背景以渲染技法表現\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6/11\n			\n			\n			可愛動物篇4\n\n			以局部特寫描繪動物的特徵，背景以渲染技法表現\n			\n		\n	\n\n\n ', `organizer`='臺北市藝文推廣處', `address`='105  臺北市松山區八德路三段25號(臺北市藝文推廣處)', `start_date`='2025-03-05 00:00:00', `end_date`='2025-06-11 00:00:00', `location`='美術教室', `latitude`=25.04835