INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6770747426b32458d43632cf', '6108創意水彩班 (吳俊學)', '🎨 探索水彩世界：活力課程啟動！\n想要輕鬆學習水彩嗎？我們的課程將以最具彈性的主題，以及生動有趣的方式，滿足你對水彩的所有好奇心！\n無論你是水彩達人或初學者，我們都致力於提供即時指導和教學，確保每個人在本班都能有意義的學習體驗。\n🖌課程亮點：\n線條的魔法：局部紀錄大揭秘！ 學習如何運用線條，捕捉畫面中的精華，讓你的作品更具藝術感。\n視覺饗宴：Youtube教學輔助呈現！ 透過課後生動的視頻教學，輕鬆掌握水彩技巧，享受創作的樂趣。\n同學互動：作業點評數位軟體修改問題！ 提交你的作業，獲得專業的寶貴意見，讓你的水彩之旅更上一層樓。\n🌈 一切所需，就在你手中：\n請自備上課用具，讓你在課程中得以更自由發揮創意！\n快來加入我們，一同揮灑水彩的色彩世界吧！不僅學習技巧，更享受藝術的樂趣！\n\n\n	\n		\n			\n			臺北市藝文推廣處114年春季\n\n			班名:創意水彩班　課程規劃表　教師:吳俊學　\n			\n			\n			 \n			\n		\n		\n			\n			項次\n			\n			\n			日期\n			\n			\n			教學內容\n			\n			\n			 \n			\n		\n		\n			\n			第1堂課\n			\n			\n			3月8日\n			\n			\n			水彩工具與材料介紹，基本操作技法（濕畫法與乾畫法）\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3月15日\n			\n			\n			顏色混合與光影技巧，學習表現立體感\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3月22日\n			\n			\n			基礎筆觸練習，靜物與簡單動物結合（水果與貓咪)\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3月29日\n			\n			\n			毛髮與羽毛的表現技巧（兔子與小鳥）\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4月12日\n			\n			\n			質感探索（玻璃、水珠與動物皮毛）\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4月19日\n			\n			\n			簡單風景（天空、雲層與山脈)\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4月26日\n			\n			\n			水體畫法（湖泊、溪流與水中魚類）\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5月3日\n			\n			\n			花卉與昆蟲結合（蝴蝶與蜜蜂）\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5月10日\n			\n			\n			森林場景與動物（狐狸、松鼠與鹿）\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5月17日\n			\n			\n			草原與野生動物（斑馬、長頸鹿）\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5月24日\n			\n			\n			多主題結合（靜物、動物與背景）\n			\n		\n		\n			\n			第12堂課\n			\n			\n			6月7日\n			\n			\n			極端環境題材（冰原上的北極熊或沙漠駱駝）\n			\n		\n		\n			\n			第13堂課\n			\n			\n			6月14日\n			\n			\n			個人選擇題材的草稿設計\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6月21日\n			\n			\n			個人專題創作與老師指導\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6月28日\n			\n			\n			作品完成與展示分享\n			\n		\n	\n\n\n ', '臺北市藝文推廣處', '105  臺北市松山區八德路三段25號(臺北市藝文推廣處)', '2025-03-08 00:00:00', '2025-06-28 00:00:00', '美術教室', 25.0483541, 121.5523447, '2000', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40226', '[]') ON DUPLICATE KEY UPDATE `activity_name`='6108創意水彩班 (吳俊學)', `description`='🎨 探索水彩世界：活力課程啟動！\n想要輕鬆學習水彩嗎？我們的課程將以最具彈性的主題，以及生動有趣的方式，滿足你對水彩的所有好奇心！\n無論你是水彩達人或初學者，我們都致力於提供即時指導和教學，確保每個人在本班都能有意義的學習體驗。\n🖌課程亮點：\n線條的魔法：局部紀錄大揭秘！ 學習如何運用線條，捕捉畫面中的精華，讓你的作品更具藝術感。\n視覺饗宴：Youtube教學輔助呈現！ 透過課後生動的視頻教學，輕鬆掌握水彩技巧，享受創作的樂趣。\n同學互動：作業點評數位軟體修改問題！ 提交你的作業，獲得專業的寶貴意見，讓你的水彩之旅更上一層樓。\n🌈 一切所需，就在你手中：\n請自備上課用具，讓你在課程中得以更自由發揮創意！\n快來加入我們，一同揮灑水彩的色彩世界吧！不僅學習技巧，更享受藝術的樂趣！\n\n\n	\n		\n			\n			臺北市藝文推廣處114年春季\n\n			班名:創意水彩班　課程規劃表　教師:吳俊學　\n			\n			\n			 \n			\n		\n		\n			\n			項次\n			\n			\n			日期\n			\n			\n			教學內容\n			\n			\n			 \n			\n		\n		\n			\n			第1堂課\n			\n			\n			3月8日\n			\n			\n			水彩工具與材料介紹，基本操作技法（濕畫法與乾畫法）\n			\n		\n		\n			\n			第2堂課\n			\n			\n			3月15日\n			\n			\n			顏色混合與光影技巧，學習表現立體感\n			\n		\n		\n			\n			第3堂課\n			\n			\n			3月22日\n			\n			\n			基礎筆觸練習，靜物與簡單動物結合（水果與貓咪)\n			\n		\n		\n			\n			第4堂課\n			\n			\n			3月29日\n			\n			\n			毛髮與羽毛的表現技巧（兔子與小鳥）\n			\n		\n		\n			\n			第5堂課\n			\n			\n			4月12日\n			\n			\n			質感探索（玻璃、水珠與動物皮毛）\n			\n		\n		\n			\n			第6堂課\n			\n			\n			4月19日\n			\n			\n			簡單風景（天空、雲層與山脈)\n			\n		\n		\n			\n			第7堂課\n			\n			\n			4月26日\n			\n			\n			水體畫法（湖泊、溪流與水中魚類）\n			\n		\n		\n			\n			第8堂課\n			\n			\n			5月3日\n			\n			\n			花卉與昆蟲結合（蝴蝶與蜜蜂）\n			\n		\n		\n			\n			第9堂課\n			\n			\n			5月10日\n			\n			\n			森林場景與動物（狐狸、松鼠與鹿）\n			\n		\n		\n			\n			第10堂課\n			\n			\n			5月17日\n			\n			\n			草原與野生動物（斑馬、長頸鹿）\n			\n		\n		\n			\n			第11堂課\n			\n			\n			5月24日\n			\n			\n			多主題結合（靜物、動物與背景）\n			\n		\n		\n			\n			第12堂課\n			\n			\n			6月7日\n			\n			\n			極端環境題材（冰原上的北極熊或沙漠駱駝）\n			\n		\n		\n			\n			第13堂課\n			\n			\n			6月14日\n			\n			\n			個人選擇題材的草稿設計\n			\n		\n		\n			\n			第14堂課\n			\n			\n			6月21日\n			\n			\n			個人專題創作與老師指導\n			\n		\n		\n			\n			第15堂課\n			\n			\n			6月28日\n			\n			\n			作品完成與展示分享\n			\n		\n	\n\n\n ', `organizer`='臺北市藝文推廣處', `address`='105  臺北市松山區八德路三段25號(臺北市藝