INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6771ca8526b32458d436331f', '114年「施情畫義．千動愛心」美術特展暨愛心活動', '為讓本縣轄區內弱勢族群在歲末寒冬之際，獲得政府、企業、藝術家及民間的關懷，苗栗縣政府於114年1月10日至3月2日在文化觀光局舉辦114年「施情畫義‧ 千動愛心」美術特展暨愛心活動，為響應本次舉辦之活動，台電、中油再次共同贊助參與公益活動，為苗栗縣弱勢族群注入一股暖流。\r\n愛心活動邀請在地藝術家，以無償創作作品參與愛心公益活動，透過創作來募集藝術品，藉由作品創作的力量來分享溫暖與善念；為鼓勵民眾踴躍參與社會公益，民眾捐助2千元至本縣7間社福團體做愛心，就能收藏藝術家原創作品1件，全數所得平均分配至本縣社福機構。\r\n114年捐款方式於1月10日(五)至2月20日(四) 以郵政劃撥至機構專戶，或直接至各機構、文化觀光局展演科臨櫃捐款，並於3月1日(六) 閉幕式以抽籤方式決定獲得之作品。', '苗栗縣政府', '苗栗縣苗栗市自治路50號', '2025-01-10 00:00:00', '2025-03-02 00:00:00', '苗栗縣政府文化觀光局', 24.565963, 120.8203986, '無資料', 'https://www.mlc.gov.tw/home.aspx', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年「施情畫義．千動愛心」美術特展暨愛心活動', `description`='為讓本縣轄區內弱勢族群在歲末寒冬之際，獲得政府、企業、藝術家及民間的關懷，苗栗縣政府於114年1月10日至3月2日在文化觀光局舉辦114年「施情畫義‧ 千動愛心」美術特展暨愛心活動，為響應本次舉辦之活動，台電、中油再次共同贊助參與公益活動，為苗栗縣弱勢族群注入一股暖流。\r\n愛心活動邀請在地藝術家，以無償創作作品參與愛心公益活動，透過創作來募集藝術品，藉由作品創作的力量來分享溫暖與善念；為鼓勵民眾踴躍參與社會公益，民眾捐助2千元至本縣7間社福團體做愛心，就能收藏藝術家原創作品1件，全數所得平均分配至本縣社福機構。\r\n114年捐款方式於1月10日(五)至2月20日(四) 以郵政劃撥至機構專戶，或直接至各機構、文化觀光局展演科臨櫃捐款，並於3月1日(六) 閉幕式以抽籤方式決定獲得之作品。', `organizer`='苗栗縣政府', `address`='苗栗縣苗栗市自治路50號', `start_date`='2025-01-10 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='苗栗縣政府文化觀光局', `latitude`=24.565963, `longitude`=120.8203986, `ticket_price`='無資料', `source_url`='https://www.mlc.gov.tw/home.aspx', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6771ca8526b32458d4363320', '匠心永續-黃紗榮創作展', '黃紗榮老師以蘭花、人物和昆蟲等作品，傳達對生命之美的讚美，另外還有一系列的宗教題材木雕作品，展露出本次展場上的木雕作品多樣性，還有木雕工藝的文化內涵。本次展覽藉由一系列融合鄉間元素的作品，呈現生機與巧妙的構思，體現歲月靜好的美好感受，引領我們重新思考自然與生活的關係。', '苗栗縣政府', '苗栗縣三義鄉廣聲新城88號', '2025-01-21 00:00:00', '2025-03-30 00:00:00', '三義木雕博物館', 24.4059218, 120.7611814, '本局策略聯盟+40;學生團體票（ 25 人以上）+40;學生票+50;優待票（苗栗縣縣民）+50;一般團體票（25 人以上）+70;全票+80', 'https://wood.mlc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='匠心永續-黃紗榮創作展', `description`='黃紗榮老師以蘭花、人物和昆蟲等作品，傳達對生命之美的讚美，另外還有一系列的宗教題材木雕作品，展露出本次展場上的木雕作品多樣性，還有木雕工藝的文化內涵。本次展覽藉由一系列融合鄉間元素的作品，呈現生機與巧妙的構思，體現歲月靜好的美好感受，引領我們重新思考自然與生活的關係。', `organizer`='苗栗縣政府', `address`='苗栗縣三義鄉廣聲新城88號', `start_date`='2025-01-21 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='三義木雕博物館', `latitude`=24.4059218, `longitude`=120.7611814, `ticket_price`='本局策略聯盟+40;學生團體票（ 25 人以上）+40;學生票+50;優待票（苗栗縣縣民）+50;一般團體票（25 人以上）+70;全票+80', `source_url`='https://wood.mlc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6771ca8526b32458d4363321', '蛇年主題袖珍木雕展—蛇發蛇GOOD', '《蛇發蛇GOOD》展以2025年農曆年新年生肖動物–「蛇」為創作主題的木雕聯展，邀請國內資深、青年和新銳三個不同世代的木雕藝術家，共同以具視覺親切感的袖珍木雕作品進行創作，以呼應農曆新年喜慶和賀歲氛圍，歡迎年節假期至三義木雕博物館走春欣賞。', '苗栗縣政府', '苗栗縣三義鄉廣聲新城88號', '2025-01-21 00:00:00', '2025-03-23 00:00:00', '三義木雕博物館', 24.4059218, 120.7611814, '本局策略聯盟+40;學生團體票（ 25 人以上）+40;學生票+50;優待票（苗栗縣縣民）+50;一般團體票（25 人以上）+70;全票+80', 'https://wood.mlc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蛇年主題袖珍木雕展—蛇發蛇GOOD', `description`='《蛇發蛇GOOD》展以2025年農曆年新年生肖動物–「蛇」為創作主題的木雕聯展，邀請國內資深、青年和新銳三個不同世代的木雕藝術家，共同以具視覺親切感的袖珍木雕作品進行創作，以呼應農曆新年喜慶和賀歲氛圍，歡迎年節假期至三義木雕博物館走春欣賞。', `organizer`='苗栗縣政府', `address`='苗栗縣三義鄉廣聲新城88號', `start_date`='2025-01-21 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='三義木雕博物館', `latitude`=24.4059218, `longitude`=120.7611814, `ticket_price`='本局策略聯盟+40;學生團體票（ 25 人以上）+40;學生票+50;優待票（苗栗縣縣民）+50;一般團體票（25 人以上）+70;全票+80', `source_url`='https://wood.mlc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6771ca8526b32458d4363323', '游於藝—苗栗縣傳揚書藝學會會員聯展', '苗栗縣傳揚書藝學會成立於113年4月，以傳承中華文化、發揚書法國粹為宗旨，推廣書法教育、培育書法人才、提升書法水準、弘揚書法藝術。藉由書法會員聯展，互相觀摩切磋、學習。此次聯展作品，內容從古文詩詞、經典語錄，各體皆備，格式多元化，歡迎熱愛藝文者踴躍前往觀賞，並不吝指教。', '苗栗縣西湖鄉公所', '苗栗縣西湖鄉13鄰194-4號', '2025-01-02 00:00:00', '2025-03-01 00:00:00', '吳濁流文學藝術館', 24.5235061, 120.7780948, '無資料', 'https://www.facebook.com/profile.php?id=100083139282083', '[]') ON DUPLICATE KEY UPDATE `activity_name`='游於藝—苗栗縣傳揚書藝學會會員聯展', `description`='苗栗縣傳揚書藝學會成立於113年4月，以傳承中華文化、發揚書法國粹為宗旨，推廣書法教育、培育書法人才、提升書法水準、弘揚書法藝術。藉由書法會員聯展，互相觀摩切磋、學習。此次聯展作品，內容從古文詩詞、經典語錄，各體皆備，格式多元化，歡迎熱愛藝文者踴躍前往觀賞，並不吝指教。', `organizer`='苗栗縣西湖鄉公所', `address`='苗栗縣西湖鄉13鄰194-4號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='吳濁流文學藝術館', `latitude`=24.5235061, `longitude`=120.7780948, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100083139282083', `image_url`='[]';
