INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6772d25226b32458d4363332', '北藝嚴選：碧娜．鮑許烏帕塔舞蹈劇場+陣地 波赫士．夏瑪茲《自由大教堂》', '無資料', '無資料', '臺北市士林區劍潭路1號', '2025-03-21 00:00:00', '2025-03-21 00:00:00', '臺北表演藝術中心 大劇院', 25.08470695, 121.52439927, '無資料', 'https://www.opentix.life/program/1871106570108354560', '[]') ON DUPLICATE KEY UPDATE `activity_name`='北藝嚴選：碧娜．鮑許烏帕塔舞蹈劇場+陣地 波赫士．夏瑪茲《自由大教堂》', `description`='無資料', `organizer`='無資料', `address`='臺北市士林區劍潭路1號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='臺北表演藝術中心 大劇院', `latitude`=25.08470695, `longitude`=121.52439927, `ticket_price`='無資料', `source_url`='https://www.opentix.life/program/1871106570108354560', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6773198c26b32458d4363337', '中華民國第40屆版印年畫「蛇彩繽紛–蛇年年畫特展」', '中華民國第40屆版印年畫：蛇彩繽紛-蛇年年畫特展\n\n「中華民國版印年畫徵選活動」自1985年開始辦理，迄今即將邁入第40屆。年畫是傳統農曆春節作為除舊佈新、避邪去惡，展現新生活、新氣象之應景飾物，隨著時代變遷，年畫從傳統的象徵吉祥、如意之裝飾或圖騰符號，逐漸發展出豐富、創新的藝術表現。文化部前身(行政院文化建設委員會) 1985年起推動「中華民國版印年畫徵選活動」，即是為喚起國人重視民俗節慶及提倡文化藝術，並由國立臺灣美術館主辦徵件、展覽及推廣工作，版印年畫不僅是國美館兼具傳統與創新內涵的特色活動，亦是向國人及世界各地介紹臺灣傳統文化藝術之重要媒介。第40屆版印年畫以「蛇彩繽紛」為題，承接歷屆版畫創作者的活力與成果，期迎來更具生機、在地特色的年畫藝術創作及年節氛圍。\n\n國美館籌辦版印年畫活動，從徵選、辦理特展、頒獎典禮及教育推廣等，希望讓民眾認識及欣賞版印年畫的藝術形式及創作表現。版印年畫具有複數性與間接性，其複數性可以大量複製流通推廣，增加欣賞者接觸的機會，帶給人們喜悅親近藝術之情，同時帶給民眾年節喜慶之感；其間接性則呈現獨特的藝術價值，讓藝術家們可以盡情發揮創意，展現各種創作形式與表現技法，豐富版印年畫的藝術性。\n\n本屆「蛇彩繽紛–蛇年年畫特展」參與徵選作品共計191件，由專業評審委員評選出首獎6件、優選10件、佳作20件及入選50件，另外特別邀請賴振輝、蘇憲法兩位藝術家委託創作〈乙巳兆豐年〉、〈春〉作品參與展出，展出委託創作、徵選得獎及入選作品共計88件。本屆作品呈現在地人文風情與特色、生命的寓意、生活的醒思及原住民文化特色等，其造形、構圖、色彩及技法皆蘊藏了豐富的版畫特性；題材的選擇則表現出話題性與時代性，展現創作者們對生活、環境的觀察，及對過年的多元詮釋。觀眾除了看到吉祥歡樂與避邪祈福的寓意之外，也能感受到對美好生活的期盼。\n\n為增進大眾更認識版畫藝術創作相關技術及發展，第40屆版印年畫「蛇彩繽紛–蛇年年畫特展」除了展出徵選作品以外，特別推出版印年畫教育展示體驗區，希望以寓教於樂的方式，提供版畫的小知識以及版印年畫印製的體驗，讓民眾親臨現場觀賞作品之餘，還可親手製作充滿年味的版印作品，為新的一年帶來的新氣象、好兆頭，也為年節增添平安、幸福、圓滿的歡欣氛圍。期待版印年畫徵選活動能持續促進藝術創作，並透過版印年畫的流通傳遞祝福與美好。\n\n \n\n ', '國立臺灣美術館', '403  臺中市西區535五權西路一段2號', '2025-01-11 00:00:00', '2025-03-23 00:00:00', '201展覽室(201 Gallery)', 24.1396657, 120.665874, '無資料', 'https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=40162', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中華民國第40屆版印年畫「蛇彩繽紛–蛇年年畫特展」', `description`='中華民國第40屆版印年畫：蛇彩繽紛-蛇年年畫特展\n\n「中華民國版印年畫徵選活動」自1985年開始辦理，迄今即將邁入第40屆。年畫是傳統農曆春節作為除舊佈新、避邪去惡，展現新生活、新氣象之應景飾物，隨著時代變遷，年畫從傳統的象徵吉祥、如意之裝飾或圖騰符號，逐漸發展出豐富、創新的藝術表現。文化部前身(行政院文化建設委員會) 1985年起推動「中華民國版印年畫徵選活動」，即是為喚起國人重視民俗節慶及提倡文化藝術，並由國立臺灣美術館主辦徵件、展覽及推廣工作，版印年畫不僅是國美館兼具傳統與創新內涵的特色活動，亦是向國人及世界各地介紹臺灣傳統文化藝術之重要媒介。第40屆版印年畫以「蛇彩繽紛」為題，承接歷屆版畫創作者的活力與成果，期迎來更具生機、在地特色的年畫藝術創作及年節氛圍。\n\n國美館籌辦版印年畫活動，從徵選、辦理特展、頒獎典禮及教育推廣等，希望讓民眾認識及欣賞版印年畫的藝術形式及創作表現。版印年畫具有複數性與間接性，其複數性可以大量複製流通推廣，增加欣賞者接觸的機會，帶給人們喜悅親近藝術之情，同時帶給民眾年節喜慶之感；其間接性則呈現獨特的藝術價值，讓藝術家們可以盡情發揮創意，展現各種創作形式與表現技法，豐富版印年畫的藝術性。\n\n本屆「蛇彩繽紛–蛇年年畫特展」參與徵選作品共計191件，由專業評審委員評選出首獎6件、優選10件、佳作20件及入選50件，另外特別邀請賴振輝、蘇憲法兩位藝術家委託創作〈乙巳兆豐年〉、〈春〉作品參與展出，展出委託創作、徵選得獎及入選作品共計88件。本屆作品呈現在地人文風情與特色、生命的寓意、生活的醒思及原住民文化特色等，其造形、構圖、色彩及技法皆蘊藏了豐富的版畫特性；題材的選擇則表現出話題性與時代性，展現創作者們對生活、環境的觀察，及對過年的多元詮釋。觀眾除了看到吉祥歡樂與避邪祈福的寓意之外，也能感受到對美好生活的期盼。\n\n為增進大眾更認識版畫藝術創作相關技術及發展，第40屆版印年畫「蛇彩繽紛–蛇年年畫特展」除了展出徵選作品以外，特別推出版印年畫教育展示體驗區，希望以寓教於樂的方式，提供版畫的小知識以及版印年畫印製的體驗，讓民眾親臨現場觀賞作品之餘，還可親手製作充滿年味的版印作品，為新的一年帶來的新氣象、好兆頭，也為年節增添平安、幸福、圓滿的歡欣氛圍。期待版印年畫徵選活動能持續促進藝術創作，並透過版印年畫的流通傳遞祝福與美好。\n\n \n\n ', `organizer`='國立臺灣美術館', `address`='403  臺中市西區535五權西路一段2號', `start_date`='2025-01-11 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='201展覽室(201 Gallery)', `latitude`=24.1396657, `longitude`=120.665874, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=40162', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67731a2926b32458d436333a', '無資料', '清水圖書館與合院日常於2025年再度攜手合作，邀請您與書本相遇、透過「閱讀」展望新的一年，迎接全新的自己。本書展將展出新年相關繪本、心理勵志、自我實現、目標管理、創造性思考等書目。歡迎於市定古蹟-清水社口楊宅內閱覽！', '臺中市立圖書館清水分館', '臺中市清水區', '清水區（臺中市）=', 24.29205743, 120.5809094, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='清水圖書館與合院日常於2025年再度攜手合作，邀請您與書本相遇、透過「閱讀」展望新的一年，迎接全新的自己。本書展將展出新年相關繪本、心理勵志、自我實現、目標管理、創造性思考等書目。歡迎於市定古蹟-清水社口楊宅內閱覽！', `organizer`='臺中市立圖書館清水分館', `address`='臺中市清水區', `location`='清水區（臺中市）=', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67731a2c26b32458d4363347', '藝文地政–「我的秘密華園」2025禎墨畫會郭美珠師生水墨畫聯展-師生聯手寫贈年畫結善緣', '龍井地政事務所自今(114)年1月1日至3月31日，於該所一、二樓文創迴廊同步展出「我的秘密華園」2025禎墨畫會郭美珠師生水墨畫聯展，作品豐富多元，並於114年1日2日上午9時30分由郭美珠老師率領學生寫畫「春聯年畫」致贈現場民眾，現場洋溢著熱鬧又歡欣的年節氣氛，郭美珠老師師生的「春聯年畫」讓大家的年節更增添了文藝氣息。', '臺中市龍井地政事務所', '臺中市龍井區', '2025-01-02 00:00:00', '2025-03-31 00:00:00', '龍井區（臺中市）=', 24.20062892, 120.5283728, '無資料', 'https://www.taichung.gov.tw/2259845/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝文地政–「我的秘密華園」2025禎墨畫會郭美珠師生水墨畫聯展-師生聯手寫贈年畫結善緣', `description`='龍井地政事務所自今(114)年1月1日至3月31日，於該所一、二樓文創迴廊同步展出「我的秘密華園」2025禎墨畫會郭美珠師生水墨畫聯展，作品豐富多元，並於114年1日2日上午9時30分由郭美珠老師率領學生寫畫「春聯年畫」致贈現場民眾，現場洋溢著熱鬧又歡欣的年節氣氛，郭美珠老師師生的「春聯年畫」讓大家的年節更增添了文藝氣息。', `organizer`='臺中市龍井地政事務所', `address`='臺中市龍井區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='龍井區（臺中市）=', `latitude`=24.20062892, `longitude`=120.5283728, `ticket_price`='無資料', `source_url`='https://www.taichung.gov.tw/2259845/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67731a2d26b32458d4363353', '靈感渡口第13屆臺中文學獎得獎作品展', '靈感渡口第13屆臺中文學獎得獎作品展 《4樓臺中作家圖書區》\r\n\r\n本屆以「靈感渡口──山海屯城的文學冶遊」為主題，結合臺中的特殊性與文化感，將來自四方的創作能量匯流其中，以筆墨書寫獨特的航線。\r\n\r\n邀請您親臨精武圖書館，並翻閱這本得獎作品集與歷屆作品集，無論是駕馭筆墨的高手、初次提筆的新人、或是喜愛閱讀的朋友，皆能共乘想像的船隻，從臺中文學獎這座渡口出發，以靈感為風帆、筆桿為船槳，穿梭於山海屯城的文化風景，享受一場別開生面的文學冶遊。\r\n\r\n 《靈感渡口：第十三屆臺中文學獎得獎作品集》，為第十三屆臺中文學獎小說類、散文類、新詩類、童話類、古典詩類、臺語詩類、客語詩類、童話類、國高中職生散文類的得獎作品彙集。\r\n\r\n除得獎作品集外，在臺中文學獎於今邁入第十三屆，此展特以該獎之特色：「猶如一座匯聚靈感的渡口，不僅串連城市，更象徵文化、思想與情感的交流」為主軸，於展場布置化為可視的視覺意象，讓文學饗宴不只停留在書本中，更能身在其中，感受文學的魅力。', '臺中市精武圖書館', '臺中市北區精武路291之3號', '2025-01-02 00:00:00', '2025-03-29 00:00:00', '臺中市精武圖書館', 24.15863985, 120.6809521, '無資料', 'https://www.library.taichung.gov.tw/public/activity2/index-1.asp?Parser=99,20,697,50,,,22928,,,,,170', '[]') ON DUPLICATE KEY UPDATE `activity_name`='靈感渡口第13屆臺中文學獎得獎作品展', `description`='靈感渡口第13屆臺中文學獎得獎作品展 《4樓臺中作家圖書區》\r\n\r\n本屆以「靈感渡口──山海屯城的文學冶遊」為主題，結合臺中的特殊性與文化感，將來自四方的創作能量匯流其中，以筆墨書寫獨特的航線。\r\n\r\n邀請您親臨精武圖書館，並翻閱這本得獎作品集與歷屆作品集，無論是駕馭筆墨的高手、初次提筆的新人、或是喜愛閱讀的朋友，皆能共乘想像的船隻，從臺中文學獎這座渡口出發，以靈感為風帆、筆桿為船槳，穿梭於山海屯城的文化風景，享受一場別開生面的文學冶遊。\r\n\r\n 《靈感渡口：第十三屆臺中文學獎得獎作品集》，為第十三屆臺中文學獎小說類、散文類、新詩類、童話類、古典詩類、臺語詩類、客語詩類、童話類、國高中職生散文類的得獎作品彙集。\r\n\r\n除得獎作品集外，在臺中文學獎於今邁入第十三屆，此展特以該獎之特色：「猶如一座匯聚靈感的渡口，不僅串連城市，更象徵文化、思想與情感的交流」為主軸，於展場布置化為可視的視覺意象，讓文學饗宴不只停留在書本中，更能身在其中，感受文學的魅力。', `organizer`='臺中市精武圖書館', `address`='臺中市北區精武路291之3號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市精武圖書館', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://www.library.taichung.gov.tw/public/activity2/index-1.asp?Parser=99,20,697,50,,,22928,,,,,170', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67731a2e26b32458d4363360', '【中市圖潭子分館】「台中食光」豐原天主堂樂齡中心聯合展I', 'strong【中市圖潭子分館】「台中食光」豐原天主堂樂齡中心聯合展/strong\r\n\r\np活動內容:/p\r\np\r\nul\r\nli本展覽由豐原天主堂樂齡中心手機攝影班/粉彩繪畫班聯合展出，展現出不同的展覽合作模式。主題為台中食光，由不同的方式來展現出台中的不同面貌景色。/li\r\nli拍攝者均為樂齡長者，藉由展出活動讓長者更有信心及活力。\r\n拍攝及創作者均為樂齡長者，此活動可讓長者將平時所見美景，美食以拍攝或繪畫方式展現，藉由展出活動讓長者更有信心及活力。/li\r\nli時間：113年1月24日(星期五)~113年3月14日(星期五)上午8:30~21:00/li\r\nli地點：中市圖|潭子分館-2F展覽區/li/ul\r\n/p', '臺中市立圖書館潭子分館', '臺中市潭子區中山路二段399號', '2025-01-24 00:00:00', '2025-03-14 00:00:00', '臺中市立圖書館潭子分館', 24.21171121, 120.710997, '無資料', 'https://www.library.taichung.gov.tw/public/topreview/index-1.asp?Parser=99,20,697,50,,,22381', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖潭子分館】「台中食光」豐原天主堂樂齡中心聯合展I', `description`='strong【中市圖潭子分館】「台中食光」豐原天主堂樂齡中心聯合展/strong\r\n\r\np活動內容:/p\r\np\r\nul\r\nli本展覽由豐原天主堂樂齡中心手機攝影班/粉彩繪畫班聯合展出，展現出不同的展覽合作模式。主題為台中食光，由不同的方式來展現出台中的不同面貌景色。/li\r\nli拍攝者均為樂齡長者，藉由展出活動讓長者更有信心及活力。\r\n拍攝及創作者均為樂齡長者，此活動可讓長者將平時所見美景，美食以拍攝或繪畫方式展現，藉由展出活動讓長者更有信心及活力。/li\r\nli時間：113年1月24日(星期五)~113年3月14日(星期五)上午8:30~21:00/li\r\nli地點：中市圖|潭子分館-2F展覽區/li/ul\r\n/p', `organizer`='臺中市立圖書館潭子分館', `address`='臺中市潭子區中山路二段399號', `start_date`='2025-01-24 00:00:00', `end_date`='2025-03-14 00:00:00', `location`='臺中市立圖書館潭子分館', `latitude`=24.21171121, `longitude`=120.710997, `ticket_price`='無資料', `source_url`='https://www.library.taichung.gov.tw/public/topreview/index-1.asp?Parser=99,20,697,50,,,22381', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67731a2f26b32458d4363365', '【無限低語 Infinite Whisper-陳昱榮個展】', '【策展論述】\r\n🎧無限低語🎧\r\n1899年，面對著機械科技文明的衝擊，高更以作品《我們是什麼？我們從何而來？我們從何而去？》提出了一個關於生命意義的提問。在虛實交織與迴饋循環中，物的「人化」（圖靈），趨勢無可避免地也將造成人的「物化」。人，遂從萬物的主宰者，逆向往物物相聯中的被主宰物演化。此次展覽《無限低語》中，藝術家運用AI技術作為輔助，探討聲音作為一種創作媒材，如何透過聲音資料庫的分析比對後與人類產生新的對話可能。聲音作為一種物種最早與世界溝通的管道，藝術家希望由此出發，逐步探索語言、文字以及程式所帶來的演化過程。\r\n作品「聲紋流」（Alter Spectrogram）以AI深度學習模組進行對弦樂演奏家的演奏聲響進行仿擬，透過機器音樂家與人類音樂家的即興對話練習，將透過聲音競奏過程中所產生的聲紋記錄下來，透過裝置、影像再現演算法所形成的共振波紋。此件作品源於藝術家對於數位時代的當代音樂演奏技術如何透過競演的方式尋找AI在深度學習模組後如何透過其聲音資料庫進行一種對話與回應關係的實驗。\r\n在作品《字源擬態》（Pixel-Text）中，藝術家透過大型語言學習模組，強化語言在演算過程中的遞迴延遲，並不斷生成新的字元結構。作品《回返》（The Revisit）則以「宇宙」作為關鍵字，透過電腦演算與圖像生成，從「微觀」到「巨集」的量化模式，讓圖像透過反覆生成的形式產生不同的質變。', '國立成功大學', '臺南市東區大學路1號', '2025-01-04 00:00:00', '2025-02-27 00:00:00', '國立成功大學', 22.98178202, 120.2281858, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【無限低語 Infinite Whisper-陳昱榮個展】', `description`='【策展論述】\r\n🎧無限低語🎧\r\n1899年，面對著機械科技文明的衝擊，高更以作品《我們是什麼？我們從何而來？我們從何而去？》提出了一個關於生命意義的提問。在虛實交織與迴饋循環中，物的「人化」（圖靈），趨勢無可避免地也將造成人的「物化」。人，遂從萬物的主宰者，逆向往物物相聯中的被主宰物演化。此次展覽《無限低語》中，藝術家運用AI技術作為輔助，探討聲音作為一種創作媒材，如何透過聲音資料庫的分析比對後與人類產生新的對話可能。聲音作為一種物種最早與世界溝通的管道，藝術家希望由此出發，逐步探索語言、文字以及程式所帶來的演化過程。\r\n作品「聲紋流」（Alter Spectrogram）以AI深度學習模組進行對弦樂演奏家的演奏聲響進行仿擬，透過機器音樂家與人類音樂家的即興對話練習，將透過聲音競奏過程中所產生的聲紋記錄下來，透過裝置、影像再現演算法所形成的共振波紋。此件作品源於藝術家對於數位時代的當代音樂演奏技術如何透過競演的方式尋找AI在深度學習模組後如何透過其聲音資料庫進行一種對話與回應關係的實驗。\r\n在作品《字源擬態》（Pixel-Text）中，藝術家透過大型語言學習模組，強化語言在演算過程中的遞迴延遲，並不斷生成新的字元結構。作品《回返》（The Revisit）則以「宇宙」作為關鍵字，透過電腦演算與圖像生成，從「微觀」到「巨集」的量化模式，讓圖像透過反覆生成的形式產生不同的質變。', `organizer`='國立成功大學', `address`='臺南市東區大學路1號', `start_date`='2025-01-04 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='國立成功大學', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67731a2f26b32458d4363367', '胡令豪 個展「城市光彩」City Radiance', '展覽《城市光彩》是一場城市的詩意旅程，藝術家胡令豪透過他的畫作，將不同城市的生活片段以光影和色彩的形式娓娓道來，彷彿在述說著一個個動人的故事。每一幅作品都像是一扇窗，讓觀者得以窺見城市中那些被忽略的瞬間，並在這些平凡的景象中找到不平凡的美感。，胡令豪的作品帶我們走進一個豐富的城市畫卷，展示了台灣城市獨特的風貌與文化。每一幅作品都是他對城市的深情告白，讓我們透過他的視角，重新感受那些建築與風景所隱藏的情感。\r\n\r\n', '玲廊滿藝', '臺南市永康區', '2025-01-01 00:00:00', '2025-04-29 00:00:00', '永康區（臺南市）=', 23.02729532, 120.2542795, '無資料', 'https://www.uniart.com.tw/topics/2493', '[]') ON DUPLICATE KEY UPDATE `activity_name`='胡令豪 個展「城市光彩」City Radiance', `description`='展覽《城市光彩》是一場城市的詩意旅程，藝術家胡令豪透過他的畫作，將不同城市的生活片段以光影和色彩的形式娓娓道來，彷彿在述說著一個個動人的故事。每一幅作品都像是一扇窗，讓觀者得以窺見城市中那些被忽略的瞬間，並在這些平凡的景象中找到不平凡的美感。，胡令豪的作品帶我們走進一個豐富的城市畫卷，展示了台灣城市獨特的風貌與文化。每一幅作品都是他對城市的深情告白，讓我們透過他的視角，重新感受那些建築與風景所隱藏的情感。\r\n\r\n', `organizer`='玲廊滿藝', `address`='臺南市永康區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='永康區（臺南市）=', `latitude`=23.02729532, `longitude`=120.2542795, `ticket_price`='無資料', `source_url`='https://www.uniart.com.tw/topics/2493', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67731a2f26b32458d436336f', '【新心生活藝術館】「穿過鏡子」自畫像聯展', '2025年的開始，我們推出既顛覆又有趣，既熟悉又陌生的展覽\r\n「穿過鏡子」自畫像聯展，15位藝術家參與。', '新心生活藝術館', '臺南市東區勝利路67號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '臺南新心藝術館', 22.98178202, 120.2281858, '無資料', 'https://www.facebook.com/singart1990/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新心生活藝術館】「穿過鏡子」自畫像聯展', `description`='2025年的開始，我們推出既顛覆又有趣，既熟悉又陌生的展覽\r\n「穿過鏡子」自畫像聯展，15位藝術家參與。', `organizer`='新心生活藝術館', `address`='臺南市東區勝利路67號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南新心藝術館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='https://www.facebook.com/singart1990/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6773a88607f35675d63f2dd3', '無資料', '「琵琶行歌、琴音結友」是一場結合深厚情誼與琵琶藝術的音樂盛宴，由蘇筠涵攜手多年好友--古箏演奏家與音樂學者林雅琇老師、揚琴演奏家王瑋琳老師共同打造。除帶來多首精彩的琵琶獨奏作品，包括古曲《霸王卸甲》、潮州樂曲《過江龍・梳妝》、劉德海創作的《天鵝》等，更將呈現多樣豐富的重奏曲目，包括琵琶與箏二重奏《春江花月夜》、《花前獨飲》，琵琶與揚琴二重奏《桑梓懷雁》，以及洋溢蘇州彈詞韻味的《彈詞韻》琵琶、古箏與揚琴三重奏，期待以音符牽動情感，為觀眾帶來溫暖而難忘的聆聽旅程。\r\n\r\n■演出： 琵琶｜蘇筠涵；古箏｜林雅琇；揚琴｜王瑋琳\r\n\r\n■時間：2025年2月23日（日）14:30（遲到或中途離場的聽眾至中場休息方可入場，建議提早抵達）\r\n\r\n■地點：林建生紀念圖書館演奏廳（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額200位，七歲以上，免費報名入場。\r\n#恕無現場後補\r\n\r\n■報名方式：2月13 日（四）10:00 起，網路報名：　https://www.accupass.com/go/1140223\r\n\r\n■演出曲目：\r\n古曲、浦東派演奏譜《霸王卸甲》\r\n潮州音樂《過江龍・梳妝》\r\n劉德海曲《天鵝》\r\n蘇筠涵曲《此時此刻》\r\n古曲、周成龍改編《春江花月夜》琵琶與箏二重奏\r\n水文彬曲《花前獨飲》琵琶與箏二重奏\r\n蔡睿恩曲 《桑梓懷雁》琵琶與揚琴二重奏\r\n周成龍曲《彈詞韻》琵琶、古箏與揚琴三重奏\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★歡迎加入Line 好友： https://bit.ly/2KFVgg2\r\n★網址： https://www.ljsedu.org.tw\r\n★粉絲專頁：https://www.facebook.com/linjiansheng\r\n', '財團法人紀念林建生教育基金會', '新北市蘆洲區三民路178號', '林建生紀念圖書館', 25.08927173, 121.4712461, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='「琵琶行歌、琴音結友」是一場結合深厚情誼與琵琶藝術的音樂盛宴，由蘇筠涵攜手多年好友--古箏演奏家與音樂學者林雅琇老師、揚琴演奏家王瑋琳老師共同打造。除帶來多首精彩的琵琶獨奏作品，包括古曲《霸王卸甲》、潮州樂曲《過江龍・梳妝》、劉德海創作的《天鵝》等，更將呈現多樣豐富的重奏曲目，包括琵琶與箏二重奏《春江花月夜》、《花前獨飲》，琵琶與揚琴二重奏《桑梓懷雁》，以及洋溢蘇州彈詞韻味的《彈詞韻》琵琶、古箏與揚琴三重奏，期待以音符牽動情感，為觀眾帶來溫暖而難忘的聆聽旅程。\r\n\r\n■演出： 琵琶｜蘇筠涵；古箏｜林雅琇；揚琴｜王瑋琳\r\n\r\n■時間：2025年2月23日（日）14:30（遲到或中途離場的聽眾至中場休息方可入場，建議提早抵達）\r\n\r\n■地點：林建生紀念圖書館演奏廳（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額200位，七歲以上，免費報名入場。\r\n#恕無現場後補\r\n\r\n■報名方式：2月13 日（四）10:00 起，網路報名：　https://www.accupass.com/go/1140223\r\n\r\n■演出曲目：\r\n古曲、浦東派演奏譜《霸王卸甲》\r\n潮州音樂《過江龍・梳妝》\r\n劉德海曲《天鵝》\r\n蘇筠涵曲《此時此刻》\r\n古曲、周成龍改編《春江花月夜》琵琶與箏二重奏\r\n水文彬曲《花前獨飲》琵琶與箏二重奏\r\n蔡睿恩曲 《桑梓懷雁》琵琶與揚琴二重奏\r\n周成龍曲《彈詞韻》琵琶、古箏與揚琴三重奏\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★歡迎加入Line 好友： https://bit.ly/2KFVgg2\r\n★網址： https://www.ljsedu.org.tw\r\n★粉絲專頁：https://www.facebook.com/linjiansheng\r\n', `organizer`='財團法人紀念林建生教育基金會', `address`='新北市蘆洲區三民路178號', `location`='林建生紀念圖書館', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
