INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677462de26b32458d436337e', '423 北管戲曲班 (吳代真)', '****原學費2,000元，新開班優惠學費7折為1,400元****\n讓從沒接觸戲曲的朋友，或對戲曲有興趣的觀眾朋友，多一個對亂彈戲曲認識、喜歡的機會。\n課程大綱：西路《放雁》說的是王寶釧苦守寒窯十八年，一日去悼念薛平貴 ，遇到太白星君化身的鴻雁飛下，王寶釧咬破手指，寫下血書一封，鴻雁替她寄書。透過角色學習正旦的小嗓發聲與水袖功 、亂彈戲的官話唸白、西路系統的各種板式曲腔，如：【西路原板】、【刀子】、【緊板】以及【哭科】。\n\n ', '臺北市藝文推廣處', '103  臺北市大同區台北市大同區迪化街一段21號(大稻埕戲苑)', '2025-03-06 00:00:00', '2025-06-19 00:00:00', '大稻埕戲苑803教室', 25.0546733, 121.5103045, '1400', 'https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40282', '[]') ON DUPLICATE KEY UPDATE `activity_name`='423 北管戲曲班 (吳代真)', `description`='****原學費2,000元，新開班優惠學費7折為1,400元****\n讓從沒接觸戲曲的朋友，或對戲曲有興趣的觀眾朋友，多一個對亂彈戲曲認識、喜歡的機會。\n課程大綱：西路《放雁》說的是王寶釧苦守寒窯十八年，一日去悼念薛平貴 ，遇到太白星君化身的鴻雁飛下，王寶釧咬破手指，寫下血書一封，鴻雁替她寄書。透過角色學習正旦的小嗓發聲與水袖功 、亂彈戲的官話唸白、西路系統的各種板式曲腔，如：【西路原板】、【刀子】、【緊板】以及【哭科】。\n\n ', `organizer`='臺北市藝文推廣處', `address`='103  臺北市大同區台北市大同區迪化街一段21號(大稻埕戲苑)', `start_date`='2025-03-06 00:00:00', `end_date`='2025-06-19 00:00:00', `location`='大稻埕戲苑803教室', `latitude`=25.0546733, `longitude`=121.5103045, `ticket_price`='1400', `source_url`='https://event.culture.tw/mocweb/reg/TAPO/Detail.init.ctr?actId=40282', `image_url`='[]';
