INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4f926b32458d43633ba', '漁業文物展', '常設展：\r\n1.模型：利用一座「海上寮舍」的實際模型，呈現潮間帶蛤蜊養殖的景觀，為漁民利用退潮時綿延四、五公里的沙灘，以孟宗竹立樁，搭建海上看守與平常遮風避雨休憩的寮舍。\r\n2.魚業相關文物：昔日使用的漁業文物、漁具大都已淘汰，為追懷早期漁業發展的歷史，館內也陳列了舊時沿岸漁撈業所使用的傳統漁具，如魚苗桶、魚罩、魚簍……等。另有漁具材料、漁航儀器、漁撈漁業、養殖常用漁具等展示區。\r\n3.漁類標本：藉由勒氏黃帶魚、經濟漁類標本、及魚類郵票展示區，達到漁業教育推廣的目的。', '彰化區漁會', '彰化縣鹿港鎮復興路485號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '彰化區漁會', 24.08286685, 120.4385491, '無資料', 'http://www.naffic.org.tw/webpad/webpad.aspx?EpfJdId9UuCxiL0BwNVv0W3AFZppSCERjavTYlE5R68%3D', '[]') ON DUPLICATE KEY UPDATE `activity_name`='漁業文物展', `description`='常設展：\r\n1.模型：利用一座「海上寮舍」的實際模型，呈現潮間帶蛤蜊養殖的景觀，為漁民利用退潮時綿延四、五公里的沙灘，以孟宗竹立樁，搭建海上看守與平常遮風避雨休憩的寮舍。\r\n2.魚業相關文物：昔日使用的漁業文物、漁具大都已淘汰，為追懷早期漁業發展的歷史，館內也陳列了舊時沿岸漁撈業所使用的傳統漁具，如魚苗桶、魚罩、魚簍……等。另有漁具材料、漁航儀器、漁撈漁業、養殖常用漁具等展示區。\r\n3.漁類標本：藉由勒氏黃帶魚、經濟漁類標本、及魚類郵票展示區，達到漁業教育推廣的目的。', `organizer`='彰化區漁會', `address`='彰化縣鹿港鎮復興路485號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='彰化區漁會', `latitude`=24.08286685, `longitude`=120.4385491, `ticket_price`='無資料', `source_url`='http://www.naffic.org.tw/webpad/webpad.aspx?EpfJdId9UuCxiL0BwNVv0W3AFZppSCERjavTYlE5R68%3D', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fa26b32458d43633bb', '光復初期台灣戶籍資料展（花壇鄉戶政事務所）', '文物展內容包含日據時期戶政文物、光復初期台灣戶籍制度之翻攝資料。', '彰化縣彰化市戶政事務所', '彰化縣花壇鄉', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '花壇鄉（彰化縣）=', 24.03006875, 120.5597655, '無資料', 'http://house.chcg.gov.tw/huatan/00home/index4.asp', '[]') ON DUPLICATE KEY UPDATE `activity_name`='光復初期台灣戶籍資料展（花壇鄉戶政事務所）', `description`='文物展內容包含日據時期戶政文物、光復初期台灣戶籍制度之翻攝資料。', `organizer`='彰化縣彰化市戶政事務所', `address`='彰化縣花壇鄉', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='花壇鄉（彰化縣）=', `latitude`=24.03006875, `longitude`=120.5597655, `ticket_price`='無資料', `source_url`='http://house.chcg.gov.tw/huatan/00home/index4.asp', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fa26b32458d43633bc', '蚵藝作品常態展', '將在地的蚵殼，加上泥塑土，轉化成人身的姿態，鳥類的羽身，結合漂流木、石頭、貝類等，不同素材，變化多端的作品，將平凡的蚵殼蛻變成動人的藝品，在館內展售。並有蚵殼DIY教學，在實際操作中可認識雕塑原理。', '王功蚵藝文化協會', '彰化縣芳苑鄉漁港路900號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '王功蚵藝文化館', 23.9537906, 120.3539226, '無資料', 'http://www.ork.org.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蚵藝作品常態展', `description`='將在地的蚵殼，加上泥塑土，轉化成人身的姿態，鳥類的羽身，結合漂流木、石頭、貝類等，不同素材，變化多端的作品，將平凡的蚵殼蛻變成動人的藝品，在館內展售。並有蚵殼DIY教學，在實際操作中可認識雕塑原理。', `organizer`='王功蚵藝文化協會', `address`='彰化縣芳苑鄉漁港路900號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='王功蚵藝文化館', `latitude`=23.9537906, `longitude`=120.3539226, `ticket_price`='無資料', `source_url`='http://www.ork.org.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fa26b32458d43633bd', '「四面亮麗，八方驚奇」玻璃特展', '由台明將公司創立的「台灣玻璃館」，除了展示玻璃藝品，並以「四面亮麗、八方驚奇」的創意呈現於社會大眾眼前。館內以寓教於樂的方式，使參觀者能與玻璃有「零距離的另類接觸」；突破玻璃業傳統的刻板印象，讓人耳目一新，並使大眾深入了解這個晶瑩剔透的大千世界，一次滿足所有玻璃相關的知識與資訊。\r\n\r\n基礎展示:\r\n文字沿革、基本素材：厚度、顏色、花紋…。\r\n現代加工：Low-E、奈米智潔…。\r\n傳統加工：切割、研磨、彎角、鑽孔、噴砂、磨砂、雕刻、印刷、彩繪、窯燒、強化、膠合、複層、彎曲…。\r\n世界之最：大小、長短、輕重、荷重量…\r\n\r\n介紹玻璃素材與應用技術：\r\n\r\n素材：厚度、顏色、花紋、反射（全反、半反）、鏡片\r\n烤漆：一般、銀粉、瑩光\r\n網印：各種圖案、彩色\r\n膠合：相片、絹絲、金箔、鐵網\r\n窯燒：曲面、彩釉、溶合\r\n磨邊：掃邊、平底細磨、圓弧細磨、樹脂光邊、斜邊、OG邊、牛頭邊\r\n雕刻：鑽雕、刻花\r\n鏡片３Ｄ：加工特質\r\n複層：隔音、隔熱\r\n防爆：砧板、滑鼠板\r\n太陽能板、液晶面板\r\n', '台灣玻璃館', '彰化縣鹿港鎮鹿工南四路30號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '台灣玻璃館', 24.08286685, 120.4385491, '無資料', 'https://www.timingjump.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「四面亮麗，八方驚奇」玻璃特展', `description`='由台明將公司創立的「台灣玻璃館」，除了展示玻璃藝品，並以「四面亮麗、八方驚奇」的創意呈現於社會大眾眼前。館內以寓教於樂的方式，使參觀者能與玻璃有「零距離的另類接觸」；突破玻璃業傳統的刻板印象，讓人耳目一新，並使大眾深入了解這個晶瑩剔透的大千世界，一次滿足所有玻璃相關的知識與資訊。\r\n\r\n基礎展示:\r\n文字沿革、基本素材：厚度、顏色、花紋…。\r\n現代加工：Low-E、奈米智潔…。\r\n傳統加工：切割、研磨、彎角、鑽孔、噴砂、磨砂、雕刻、印刷、彩繪、窯燒、強化、膠合、複層、彎曲…。\r\n世界之最：大小、長短、輕重、荷重量…\r\n\r\n介紹玻璃素材與應用技術：\r\n\r\n素材：厚度、顏色、花紋、反射（全反、半反）、鏡片\r\n烤漆：一般、銀粉、瑩光\r\n網印：各種圖案、彩色\r\n膠合：相片、絹絲、金箔、鐵網\r\n窯燒：曲面、彩釉、溶合\r\n磨邊：掃邊、平底細磨、圓弧細磨、樹脂光邊、斜邊、OG邊、牛頭邊\r\n雕刻：鑽雕、刻花\r\n鏡片３Ｄ：加工特質\r\n複層：隔音、隔熱\r\n防爆：砧板、滑鼠板\r\n太陽能板、液晶面板\r\n', `organizer`='台灣玻璃館', `address`='彰化縣鹿港鎮鹿工南四路30號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='台灣玻璃館', `latitude`=24.08286685, `longitude`=120.4385491, `ticket_price`='無資料', `source_url`='https://www.timingjump.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fa26b32458d43633be', '鹿港鎮史文物常態展', '鹿港鎮史館揭牌啟用後,即吸引民眾踴躍前往參觀,在環境典雅的展區內,襯著悠揚的音樂聲,加上館方人員詳細解說有關展覽的老照片、檔案史料等內容背景,讓參觀民眾不虛此行,紛紛簽名留念,也為鎮史館打響開館後第一炮。', '彰化縣鹿港鎮公所', '彰化縣鹿港鎮民權路160巷2號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '鹿港街長宿舍（鹿港鎮史館）', 24.08286685, 120.4385491, '無資料', 'http://www.lukang.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鹿港鎮史文物常態展', `description`='鹿港鎮史館揭牌啟用後,即吸引民眾踴躍前往參觀,在環境典雅的展區內,襯著悠揚的音樂聲,加上館方人員詳細解說有關展覽的老照片、檔案史料等內容背景,讓參觀民眾不虛此行,紛紛簽名留念,也為鎮史館打響開館後第一炮。', `organizer`='彰化縣鹿港鎮公所', `address`='彰化縣鹿港鎮民權路160巷2號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='鹿港街長宿舍（鹿港鎮史館）', `latitude`=24.08286685, `longitude`=120.4385491, `ticket_price`='無資料', `source_url`='http://www.lukang.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fa26b32458d43633bf', '彰化縣縣史常態特展', '家鄉事 故鄉史：\r\n近幾年，隨著鄉土文化意識的抬頭，每個人開始注意自己家鄉的事，關心家鄉的歷史、地理環境，進而收集與推廣本縣的歷史文化，基於此，本局將原先之史蹟資料室重新規劃、整修，賦予更多的功能，更名為縣史館，於民國八十八年一月重新開館，冀能提供想認識本縣之 歷史文化之民眾、研究學者、學子等一個好的環境。\r\n\r\n文獻資料區：\r\n本區主要收集本縣之文獻資料，如書籍、老照片、古文書、 古地圖等，提供民眾、研究學者查閱資料的好場所，同時成為本縣各級學校之鄉土教育之場所。惟本區資料以館內閱覽，恕無法提供外借參考之用。\r\n\r\n展示區：\r\n配合本縣歷史上的大事或是有關本縣歷史文獻(物)、風土民情等，不定期更換展覽。\r\n\r\n典藏區：\r\n主要典藏收集有關本縣之古契約書、老照片、古文物及藝文人事之手稿，提供良好的保存環境。', '彰化縣文化局', '彰化縣彰化市中山路2段500號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '彰化縣立圖書館', 24.07532909, 120.5694208, '無資料', 'http://www.bocach.gov.tw/subject/history/index.asp?act_id=4', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彰化縣縣史常態特展', `description`='家鄉事 故鄉史：\r\n近幾年，隨著鄉土文化意識的抬頭，每個人開始注意自己家鄉的事，關心家鄉的歷史、地理環境，進而收集與推廣本縣的歷史文化，基於此，本局將原先之史蹟資料室重新規劃、整修，賦予更多的功能，更名為縣史館，於民國八十八年一月重新開館，冀能提供想認識本縣之 歷史文化之民眾、研究學者、學子等一個好的環境。\r\n\r\n文獻資料區：\r\n本區主要收集本縣之文獻資料，如書籍、老照片、古文書、 古地圖等，提供民眾、研究學者查閱資料的好場所，同時成為本縣各級學校之鄉土教育之場所。惟本區資料以館內閱覽，恕無法提供外借參考之用。\r\n\r\n展示區：\r\n配合本縣歷史上的大事或是有關本縣歷史文獻(物)、風土民情等，不定期更換展覽。\r\n\r\n典藏區：\r\n主要典藏收集有關本縣之古契約書、老照片、古文物及藝文人事之手稿，提供良好的保存環境。', `organizer`='彰化縣文化局', `address`='彰化縣彰化市中山路2段500號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='彰化縣立圖書館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='http://www.bocach.gov.tw/subject/history/index.asp?act_id=4', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fa26b32458d43633c0', '與稻香共生常態展─台灣穀堡：稻米博物館', '  彰化縣是稻米栽種面積與產量的雙冠王，是台灣的糧倉，走在素樸的鄉間，稻田是充滿療癒的美景，自詡「米界模飯生」中興米，設立於埤頭鄉間的稻米博物館「台灣穀堡」，2010年開館以來成為稻田間的亮點，是體驗台灣稻米文化必訪的知性與感性場域。\r\n  文化 創意的年代，為讓遊客更深刻體驗從一粒米如何盪漾出美好生活文化風貌，不惜自廢武功、拆毀重練，大規模改造台灣穀堡，從一句最平凡的口語「好好吃飯」，重新演繹一粒米帶來的生活美好，期望嶄新的台灣穀堡，能將台灣的觀光工廠帶入新的2.0時代。\r\n  走進大廳是「天下糧倉」，已成功跨出國界行銷全球的中興米，蒐羅的世界各國的稻米樣品，大面舖成高牆，米是台灣的驕傲更是與世界交好的友誼橋樑。\r\n  拾級而上有稻米的文學詩性，傳統建築中曬穀的「埕」，是影音多媒體的溝通，透過美術動畫邀請您一起成為圓桌武士，改變從餐桌開始。\r\n  錯落的館內的屋中屋展間，像一幢幢田間的小聚落，您可以在小木屋間穿梭觀展，一層層多面向地從米看進去，進到生活裡，深成了文化長河。眾星都為了拱月，在ＤＩＹ教室裡，我們請您好好煮一鍋飯，由衷地呼吸一口米香，為白米飯增色、添香。落地窗外成排巨大的儲米糟、科技化的分裝廠，經典十足的工業風，來到這裡先餵飽你知性，再感性的享受餐飲，好好吃飯讓你體會真真正正的「飯局」。', '無資料', '彰化縣埤頭鄉彰水路二段526號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '台灣穀堡', 23.88234118, 120.4675642, '無資料', 'https://www.ricecastle.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='與稻香共生常態展─台灣穀堡：稻米博物館', `description`='  彰化縣是稻米栽種面積與產量的雙冠王，是台灣的糧倉，走在素樸的鄉間，稻田是充滿療癒的美景，自詡「米界模飯生」中興米，設立於埤頭鄉間的稻米博物館「台灣穀堡」，2010年開館以來成為稻田間的亮點，是體驗台灣稻米文化必訪的知性與感性場域。\r\n  文化 創意的年代，為讓遊客更深刻體驗從一粒米如何盪漾出美好生活文化風貌，不惜自廢武功、拆毀重練，大規模改造台灣穀堡，從一句最平凡的口語「好好吃飯」，重新演繹一粒米帶來的生活美好，期望嶄新的台灣穀堡，能將台灣的觀光工廠帶入新的2.0時代。\r\n  走進大廳是「天下糧倉」，已成功跨出國界行銷全球的中興米，蒐羅的世界各國的稻米樣品，大面舖成高牆，米是台灣的驕傲更是與世界交好的友誼橋樑。\r\n  拾級而上有稻米的文學詩性，傳統建築中曬穀的「埕」，是影音多媒體的溝通，透過美術動畫邀請您一起成為圓桌武士，改變從餐桌開始。\r\n  錯落的館內的屋中屋展間，像一幢幢田間的小聚落，您可以在小木屋間穿梭觀展，一層層多面向地從米看進去，進到生活裡，深成了文化長河。眾星都為了拱月，在ＤＩＹ教室裡，我們請您好好煮一鍋飯，由衷地呼吸一口米香，為白米飯增色、添香。落地窗外成排巨大的儲米糟、科技化的分裝廠，經典十足的工業風，來到這裡先餵飽你知性，再感性的享受餐飲，好好吃飯讓你體會真真正正的「飯局」。', `organizer`='無資料', `address`='彰化縣埤頭鄉彰水路二段526號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='台灣穀堡', `latitude`=23.88234118, `longitude`=120.4675642, `ticket_price`='無資料', `source_url`='https://www.ricecastle.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fa26b32458d43633c1', '彰化縣立圖書館-書道館常態特展', '彰化縣立圖書館-書道館常態特展\r\n書法藝術及用品展覽\r\n\r\n本縣自雍正元年(1723)設縣，因鹿港作為商港，商業繁盛，帶動文風鼎盛，為本縣文化發展的起始點，延伸至彰化、員林、北斗、二林、和美等地，詩文書畫名家輩出。時至今日，彰化縣書法學習風氣仍然勝於其他縣市。\r\n書法藝術盛行，民間學會林立，更顯著地展現在各種展覽、競賽、詩文活動之間，彰化縣文化局有感於書法風氣活躍，進而於104年成立書道館，作為書法推廣之重要據點。\r\n粘文意先生師承書法名家黃祖輝，自青年蒐羅書法相關資料50餘年，收藏書帖、工具書、書論及期刊等，深獲好評。而粘老師年歲增長，感念受先進提攜，決意將畢生珍藏相關資料約2,500件，無償提供「書道館」展陳，供書法愛好者查閱研究。\r\n彰化縣文化局書道館承接書法藝術薪火相傳的使命，作為本縣書法研究推廣中心，以保存、研究、展示、推廣為目的，提供民眾書法、教育或學術研究之處所，規劃書法常設展、主題展，並定期舉辦推廣活動、講學等，讓民眾重新發掘書法藝術的新價值並享受其中，以全面提升縣民之文化生活。\r\n', '彰化縣文化局', '彰化縣彰化市中山路2段500號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '彰化縣立圖書館', 24.07532909, 120.5694208, '無資料', 'http://www.bocach.gov.tw/ch/00home/home.asp', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彰化縣立圖書館-書道館常態特展', `description`='彰化縣立圖書館-書道館常態特展\r\n書法藝術及用品展覽\r\n\r\n本縣自雍正元年(1723)設縣，因鹿港作為商港，商業繁盛，帶動文風鼎盛，為本縣文化發展的起始點，延伸至彰化、員林、北斗、二林、和美等地，詩文書畫名家輩出。時至今日，彰化縣書法學習風氣仍然勝於其他縣市。\r\n書法藝術盛行，民間學會林立，更顯著地展現在各種展覽、競賽、詩文活動之間，彰化縣文化局有感於書法風氣活躍，進而於104年成立書道館，作為書法推廣之重要據點。\r\n粘文意先生師承書法名家黃祖輝，自青年蒐羅書法相關資料50餘年，收藏書帖、工具書、書論及期刊等，深獲好評。而粘老師年歲增長，感念受先進提攜，決意將畢生珍藏相關資料約2,500件，無償提供「書道館」展陳，供書法愛好者查閱研究。\r\n彰化縣文化局書道館承接書法藝術薪火相傳的使命，作為本縣書法研究推廣中心，以保存、研究、展示、推廣為目的，提供民眾書法、教育或學術研究之處所，規劃書法常設展、主題展，並定期舉辦推廣活動、講學等，讓民眾重新發掘書法藝術的新價值並享受其中，以全面提升縣民之文化生活。\r\n', `organizer`='彰化縣文化局', `address`='彰化縣彰化市中山路2段500號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='彰化縣立圖書館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='http://www.bocach.gov.tw/ch/00home/home.asp', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633c2', '捏麵作品常態展（巫家捏麵館）', '「巫家捏麵館」目前規劃有兩個區域，一是可容納150人的捏麵教室，從事教學推展，另外是利用三合院廂房作為捏麵展示館，展示台灣傳統捏麵技藝作品。', '巫家捏麵館', '彰化縣溪湖鎮', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '溪湖鎮（彰化縣）=', 23.95171456, 120.4831739, '無資料', 'https://www.facebook.com/wufigure/?fref=ts', '[]') ON DUPLICATE KEY UPDATE `activity_name`='捏麵作品常態展（巫家捏麵館）', `description`='「巫家捏麵館」目前規劃有兩個區域，一是可容納150人的捏麵教室，從事教學推展，另外是利用三合院廂房作為捏麵展示館，展示台灣傳統捏麵技藝作品。', `organizer`='巫家捏麵館', `address`='彰化縣溪湖鎮', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='溪湖鎮（彰化縣）=', `latitude`=23.95171456, `longitude`=120.4831739, `ticket_price`='無資料', `source_url`='https://www.facebook.com/wufigure/?fref=ts', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633c3', '元清觀民俗文物常態特展', '彰化市元清觀是全台唯一以觀為名、供奉玉皇大帝的寺廟，附設民藝館更是收藏豐富的文物，元清觀建於清乾隆廿八年，是全台唯一以觀為名並供奉玉皇大帝的寺廟，彰化地方信眾習慣稱為「天公壇」，屬國家級古蹟，九十五年四月發生一場火災正殿毀損，目前修復工程完工，重新開放。元清觀附屬民藝館已開館，主要就在元清觀歷史沿革、傳統建築藝術之美，並提供民俗技藝傳承研習園地，展示文物琳瑯滿目，為的就是在推廣文化觀光。 \r\n', '彰化市公所', '彰化縣彰化市陳稜路126號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '元清觀民藝館', 24.07532909, 120.5694208, '無資料', 'http://www.changhua.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='元清觀民俗文物常態特展', `description`='彰化市元清觀是全台唯一以觀為名、供奉玉皇大帝的寺廟，附設民藝館更是收藏豐富的文物，元清觀建於清乾隆廿八年，是全台唯一以觀為名並供奉玉皇大帝的寺廟，彰化地方信眾習慣稱為「天公壇」，屬國家級古蹟，九十五年四月發生一場火災正殿毀損，目前修復工程完工，重新開放。元清觀附屬民藝館已開館，主要就在元清觀歷史沿革、傳統建築藝術之美，並提供民俗技藝傳承研習園地，展示文物琳瑯滿目，為的就是在推廣文化觀光。 \r\n', `organizer`='彰化市公所', `address`='彰化縣彰化市陳稜路126號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='元清觀民藝館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='http://www.changhua.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633c4', '文化解密-彰化縣文化局檔案資料展', '由彰化縣文化局主辦的「文化解密――彰化縣文化局檔案資料展」，於111年11月18日在彰化縣立圖書館3樓長廊展區登場。本次展覽為常設展，展期長達兩年，規劃九大主題：一、「時光隧道~彰化縣文化局沿革」二、「歷史長河」三、「文學彰化」四、「歷史舞台」五、「節慶活動」六、「文資版圖」七、「千古傳唱」八、「表演藝術」九、「視覺藝術」。', '彰化縣文化局', '彰化縣彰化市中山路2段500號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '彰化縣立圖書館', 24.07532909, 120.5694208, '無資料', 'https://am11.archives.gov.tw/Event/EventDetail.aspx?cnid=5&p=511', '[]') ON DUPLICATE KEY UPDATE `activity_name`='文化解密-彰化縣文化局檔案資料展', `description`='由彰化縣文化局主辦的「文化解密――彰化縣文化局檔案資料展」，於111年11月18日在彰化縣立圖書館3樓長廊展區登場。本次展覽為常設展，展期長達兩年，規劃九大主題：一、「時光隧道~彰化縣文化局沿革」二、「歷史長河」三、「文學彰化」四、「歷史舞台」五、「節慶活動」六、「文資版圖」七、「千古傳唱」八、「表演藝術」九、「視覺藝術」。', `organizer`='彰化縣文化局', `address`='彰化縣彰化市中山路2段500號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='彰化縣立圖書館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://am11.archives.gov.tw/Event/EventDetail.aspx?cnid=5&p=511', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633c5', '鹿港民俗文物典藏展', '館內收集了許多鹿港當地文物，內容包括清代至民國初年共計六千餘件的民生用品，其中約三千件為鹿港當地耆老捐贈書畫、文物。展示廳一樓展有：文獻圖片、服裝配飾、戲曲樂器、宗教禮儀用品；二樓展示廳有：辜氏臥房、國際會議大廳、太師椅貴賓接待廳、閨女臥房、餐飲器皿及書畫文獻資料。另有一棟兩 百年歷史之傳統閩式建築：「古風樓」。現為私立的民俗文物館，未捐贈為官方所有。當時辜濂清秘書（1984年）、丁國富顧問手繪數種該館logo圖樣，共計七種，目前本館信封、名片logo為辜濂清手繪而成。\r\n\r\n館內典藏九大類民俗文物：\r\n書法、繪畫類\r\n傢俱、雕刻類\r\n戲曲、布偶類\r\n宗教、禮儀類\r\n瓷器、餐飲器皿類\r\n服飾、裁縫類\r\n生活用品類（綜合）\r\n歷史文獻資料\r\n清末家居用品類（古風樓）', '鹿港民俗文物館', '彰化縣鹿港鎮館前街88號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '鹿港民俗文物館', 24.08286685, 120.4385491, '全票+130;半票+70;團體票+90', 'http://www.lukangarts.org.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鹿港民俗文物典藏展', `description`='館內收集了許多鹿港當地文物，內容包括清代至民國初年共計六千餘件的民生用品，其中約三千件為鹿港當地耆老捐贈書畫、文物。展示廳一樓展有：文獻圖片、服裝配飾、戲曲樂器、宗教禮儀用品；二樓展示廳有：辜氏臥房、國際會議大廳、太師椅貴賓接待廳、閨女臥房、餐飲器皿及書畫文獻資料。另有一棟兩 百年歷史之傳統閩式建築：「古風樓」。現為私立的民俗文物館，未捐贈為官方所有。當時辜濂清秘書（1984年）、丁國富顧問手繪數種該館logo圖樣，共計七種，目前本館信封、名片logo為辜濂清手繪而成。\r\n\r\n館內典藏九大類民俗文物：\r\n書法、繪畫類\r\n傢俱、雕刻類\r\n戲曲、布偶類\r\n宗教、禮儀類\r\n瓷器、餐飲器皿類\r\n服飾、裁縫類\r\n生活用品類（綜合）\r\n歷史文獻資料\r\n清末家居用品類（古風樓）', `organizer`='鹿港民俗文物館', `address`='彰化縣鹿港鎮館前街88號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='鹿港民俗文物館', `latitude`=24.08286685, `longitude`=120.4385491, `ticket_price`='全票+130;半票+70;團體票+90', `source_url`='http://www.lukangarts.org.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633c6', '彰化縣1895八卦山抗日保台史蹟常態展', '館室入口一幕幕看板揭示清廷甲午戰爭失利，簽訂馬關條約割讓台灣，啟動台灣人民一連串抗日保台戰爭；1895乙未戰爭抗日義勇軍 一路打到八卦山，浴血奮戰寫下慘烈的一頁，可惜電影資金不足，沒在這一部分多著墨，但台灣人民乃至彰化人民愛台保國的勇敢無法從歷史上抹滅。\r\n導覽員為參觀抗日保台史蹟館的幼托園所兒童解說春帆樓史蹟，他說，春帆樓是很美的名字，100年多前那裡卻發生不幸的事，滿清朝廷和日本談判，造成台灣被割讓給日本。小朋友眨著天真雙眼，似懂非懂的點頭。\r\n文化局長吳蘭梅表示，縣長在95年間交代以戰爭史蹟館園區的概念規畫防空洞和隧道，喚起全民的抗日戰役記憶，並增加八卦山大佛風景區新遊憩主題，文化局因 此興建「八卦山戰史隧道－防空坑道體驗區」及「抗日烈士紀念碑公園規劃為乙未保台和平紀念公園」，今年二月乙未保台和平紀念公園落成。', '彰化縣文化局', '彰化縣彰化市中山路2段500號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '彰化縣立圖書館', 24.07532909, 120.5694208, '無資料', 'http://www.bocach.gov.tw/ch/00home/home.asp', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彰化縣1895八卦山抗日保台史蹟常態展', `description`='館室入口一幕幕看板揭示清廷甲午戰爭失利，簽訂馬關條約割讓台灣，啟動台灣人民一連串抗日保台戰爭；1895乙未戰爭抗日義勇軍 一路打到八卦山，浴血奮戰寫下慘烈的一頁，可惜電影資金不足，沒在這一部分多著墨，但台灣人民乃至彰化人民愛台保國的勇敢無法從歷史上抹滅。\r\n導覽員為參觀抗日保台史蹟館的幼托園所兒童解說春帆樓史蹟，他說，春帆樓是很美的名字，100年多前那裡卻發生不幸的事，滿清朝廷和日本談判，造成台灣被割讓給日本。小朋友眨著天真雙眼，似懂非懂的點頭。\r\n文化局長吳蘭梅表示，縣長在95年間交代以戰爭史蹟館園區的概念規畫防空洞和隧道，喚起全民的抗日戰役記憶，並增加八卦山大佛風景區新遊憩主題，文化局因 此興建「八卦山戰史隧道－防空坑道體驗區」及「抗日烈士紀念碑公園規劃為乙未保台和平紀念公園」，今年二月乙未保台和平紀念公園落成。', `organizer`='彰化縣文化局', `address`='彰化縣彰化市中山路2段500號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='彰化縣立圖書館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='http://www.bocach.gov.tw/ch/00home/home.asp', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633c7', '鎮館之寶─古月井記碑常態展', '嘉慶六年(西元一八Ο一年)仲春，古月井記碑由當時彰化縣令胡應魁立於城隍廟，高二Ο五公分，寬六七公分，主要材質為臺灣樟木，立碑至今已有兩百餘年。碑中詳敘縣令捐俸購井之事，旁及當時彰化之生活環境，為彰化開發史之重要文物。然久經忽視，亦曾淪為踏腳板，雖城隍方以水泥牌樓固定保存，內部仍不免嚴重蛀蝕、腐朽，幾近空心之程度，岌岌可危。市長溫國銘致力於藝術文化建設，除興建古月民俗館以介紹、保存彰化之史蹟與文物外，同理於胡縣令為民謀福之心，眼見文物毀損至此不忍坐視，於民國九十五年(西元二ΟΟ六年)延攬專家進行修復工程，為期三個月，以保存文物，重現古月井記碑當年原貌，使文物資產得以延續其生命。\r\n', '彰化市公所', '彰化縣彰化市中華路57號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '彰化市古月民俗館', 24.07532909, 120.5694208, '無資料', 'http://www.guyue-changhua.tw/show_list.jsp?type=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鎮館之寶─古月井記碑常態展', `description`='嘉慶六年(西元一八Ο一年)仲春，古月井記碑由當時彰化縣令胡應魁立於城隍廟，高二Ο五公分，寬六七公分，主要材質為臺灣樟木，立碑至今已有兩百餘年。碑中詳敘縣令捐俸購井之事，旁及當時彰化之生活環境，為彰化開發史之重要文物。然久經忽視，亦曾淪為踏腳板，雖城隍方以水泥牌樓固定保存，內部仍不免嚴重蛀蝕、腐朽，幾近空心之程度，岌岌可危。市長溫國銘致力於藝術文化建設，除興建古月民俗館以介紹、保存彰化之史蹟與文物外，同理於胡縣令為民謀福之心，眼見文物毀損至此不忍坐視，於民國九十五年(西元二ΟΟ六年)延攬專家進行修復工程，為期三個月，以保存文物，重現古月井記碑當年原貌，使文物資產得以延續其生命。\r\n', `organizer`='彰化市公所', `address`='彰化縣彰化市中華路57號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='彰化市古月民俗館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='http://www.guyue-changhua.tw/show_list.jsp?type=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633c8', '呂碧銓文物常態展（田中鎮碧銓文物館）', '本鎮百年古典詩社「蘭社」社長呂碧銓先生文物館於今（100）年5月29日落成啟用，展示其詩作、得獎紀念狀及書法作品，館址位於彰化縣田中鎮大社路1段70號，參觀預約電話(04)8742170、8751888。 \r\n「碧峰山人呂碧銓生於日治憂患之時，長於台島板蕩之世，既目見漢學興衰之遞變，又親體文化傳承之艱難。一生之志趣以詩為首，一身之遊歷以詩為最。縱然世音滔滔，仍才貫筆端華藻，奪金不落人後；即令年耄力遲，而詩篇蜂出依舊，毀譽無擾其心。詩人之執著處，亦詩人之可愛可敬處。 \r\n呂碧銓老詞丈，詩才馳名遠近，其出詩之迅捷，尤為詩壇所津津樂道，至今已出版《碧銓吟草》系列詩集達五巨冊，使常人難望其項背。其作詩及其詩作，均為當今詩壇所注目。', '彰化縣田中鎮公所', '彰化縣田中鎮', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '田中鎮（彰化縣）=', 23.85723872, 120.5903471, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='呂碧銓文物常態展（田中鎮碧銓文物館）', `description`='本鎮百年古典詩社「蘭社」社長呂碧銓先生文物館於今（100）年5月29日落成啟用，展示其詩作、得獎紀念狀及書法作品，館址位於彰化縣田中鎮大社路1段70號，參觀預約電話(04)8742170、8751888。 \r\n「碧峰山人呂碧銓生於日治憂患之時，長於台島板蕩之世，既目見漢學興衰之遞變，又親體文化傳承之艱難。一生之志趣以詩為首，一身之遊歷以詩為最。縱然世音滔滔，仍才貫筆端華藻，奪金不落人後；即令年耄力遲，而詩篇蜂出依舊，毀譽無擾其心。詩人之執著處，亦詩人之可愛可敬處。 \r\n呂碧銓老詞丈，詩才馳名遠近，其出詩之迅捷，尤為詩壇所津津樂道，至今已出版《碧銓吟草》系列詩集達五巨冊，使常人難望其項背。其作詩及其詩作，均為當今詩壇所注目。', `organizer`='彰化縣田中鎮公所', `address`='彰化縣田中鎮', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='田中鎮（彰化縣）=', `latitude`=23.85723872, `longitude`=120.5903471, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633c9', '媽袓文物展', '彰化市積極推動宗教文化，本館於九十五年二月動工興建，迄九十八年四月完工，九十九年四月二十五日開幕。為地面七樓之建物，是一處結合文物展示、文化交流及地方觀光住宿之公共空間，設有媽袓文物展覽室、多功能展示空間、會議禮堂、溫馨客房。\r\n\r\n本館以介紹南瑤宮媽祖之發源歷史並保存相關文物史料、蒐藏相關媽祖文物、展覽其他文化藝品為主，輔以結合彰化市觀光產業，舉辦多樣化人文活動，本館將籌設客房提供住宿，為參訪彰化市美景及歷史文化之新景點，更為彰化市古蹟活化開創另一個新的發展契機。', '彰化市公所', '彰化縣彰化市民族一街31號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '南瑤宮媽祖文化館', 24.07532909, 120.5694208, '無資料', 'https://www.facebook.com/ChanghuaMazu/?locale=zh_TW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='媽袓文物展', `description`='彰化市積極推動宗教文化，本館於九十五年二月動工興建，迄九十八年四月完工，九十九年四月二十五日開幕。為地面七樓之建物，是一處結合文物展示、文化交流及地方觀光住宿之公共空間，設有媽袓文物展覽室、多功能展示空間、會議禮堂、溫馨客房。\r\n\r\n本館以介紹南瑤宮媽祖之發源歷史並保存相關文物史料、蒐藏相關媽祖文物、展覽其他文化藝品為主，輔以結合彰化市觀光產業，舉辦多樣化人文活動，本館將籌設客房提供住宿，為參訪彰化市美景及歷史文化之新景點，更為彰化市古蹟活化開創另一個新的發展契機。', `organizer`='彰化市公所', `address`='彰化縣彰化市民族一街31號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='南瑤宮媽祖文化館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.facebook.com/ChanghuaMazu/?locale=zh_TW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633ca', '彰化基督教醫院院史文物展', '1896年11月29日，英國籍的蘭大衛醫師和梅監霧牧師，相偕到彰化來，他們選定中部地區，為醫療與宣教的工作據點。自此，彰化基督教醫院即成為中臺灣西方醫療的濫觴，他們帶來了西方的醫學與技術，也帶來了西方的教育、文明和人文思想。　　彰基院史文物館是一部活的資料記錄館，透過我們設計的歷史情境、文物介紹、每幅影像、每件文物都能道盡彰基的歷史與故事，重塑彰基的人文歷史，找尋彰基精神的典範人物，讓這一代的彰基人能從前人的佳美腳蹤去重新檢視及決定我們對未來的想法價值觀和吸取經驗。\r\n    院史文物館內容：分醫療史、宣教史、影像資料、影像展視、古老照片、老蘭醫生紀念室、百年前的醫療儀器及藥品等如手術用大小器械、木製遮眼板、洗眼用器具、婦產科使用的產鉗、單鉤、日本總督府贈送給蘭大衛醫師在臺服務滿40年的銅製花瓶、地契……等等，內容札實、豐富。\r\n', '彰化基督教醫院', '彰化縣彰化市南校街135號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '彰化基督教醫院', 24.07532909, 120.5694208, '無資料', 'http://pharm.cch.org.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彰化基督教醫院院史文物展', `description`='1896年11月29日，英國籍的蘭大衛醫師和梅監霧牧師，相偕到彰化來，他們選定中部地區，為醫療與宣教的工作據點。自此，彰化基督教醫院即成為中臺灣西方醫療的濫觴，他們帶來了西方的醫學與技術，也帶來了西方的教育、文明和人文思想。　　彰基院史文物館是一部活的資料記錄館，透過我們設計的歷史情境、文物介紹、每幅影像、每件文物都能道盡彰基的歷史與故事，重塑彰基的人文歷史，找尋彰基精神的典範人物，讓這一代的彰基人能從前人的佳美腳蹤去重新檢視及決定我們對未來的想法價值觀和吸取經驗。\r\n    院史文物館內容：分醫療史、宣教史、影像資料、影像展視、古老照片、老蘭醫生紀念室、百年前的醫療儀器及藥品等如手術用大小器械、木製遮眼板、洗眼用器具、婦產科使用的產鉗、單鉤、日本總督府贈送給蘭大衛醫師在臺服務滿40年的銅製花瓶、地契……等等，內容札實、豐富。\r\n', `organizer`='彰化基督教醫院', `address`='彰化縣彰化市南校街135號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='彰化基督教醫院', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='http://pharm.cch.org.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633cb', '蘭大弼根的故事常態展', '自稱「英籍台灣人」「我是台灣囝仔」的蘭大弼醫師曾說：「每一個人都有根，有根長入土地；我在台灣有根，人們記得我的家庭的好，很多人都記得我的父母….」，讓我們透過各種生活物品、藝術珍藏、生活展示、故事光廊、影像紀錄，一同感受深耕鄉土、關懷同仁、憐愛家人的蘭醫師。\r\n', '彰化基督教醫院', '彰化縣彰化市南校街135號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '彰化基督教醫院', 24.07532909, 120.5694208, '無資料', 'http://pharm.cch.org.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蘭大弼根的故事常態展', `description`='自稱「英籍台灣人」「我是台灣囝仔」的蘭大弼醫師曾說：「每一個人都有根，有根長入土地；我在台灣有根，人們記得我的家庭的好，很多人都記得我的父母….」，讓我們透過各種生活物品、藝術珍藏、生活展示、故事光廊、影像紀錄，一同感受深耕鄉土、關懷同仁、憐愛家人的蘭醫師。\r\n', `organizer`='彰化基督教醫院', `address`='彰化縣彰化市南校街135號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='彰化基督教醫院', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='http://pharm.cch.org.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633cc', '賴和文物常態展', '1994年財團法人賴和文教基金會成立，由賴和長孫賴悅顏任第一屆董事長。1995年成立賴和紀念館。館藏有完整之賴和遺物、藏書、字畫、手稿及相關文獻資料，並陸續蒐藏、展示彰化地區作家之手稿文物。\r\n\r\n', '賴和文教基金會', '彰化縣彰化市中正路1段242號4樓', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '賴和文教基金會（賴和紀念館）', 24.07532909, 120.5694208, '無資料', 'http://www.laiho.org.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='賴和文物常態展', `description`='1994年財團法人賴和文教基金會成立，由賴和長孫賴悅顏任第一屆董事長。1995年成立賴和紀念館。館藏有完整之賴和遺物、藏書、字畫、手稿及相關文獻資料，並陸續蒐藏、展示彰化地區作家之手稿文物。\r\n\r\n', `organizer`='賴和文教基金會', `address`='彰化縣彰化市中正路1段242號4樓', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='賴和文教基金會（賴和紀念館）', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='http://www.laiho.org.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633cd', '溪湖糖廠-蒸汽火車展示', '位於鐵道文化區內，建於1977年，原為鐵道檢車庫。2008年整修作為蒸汽火車展示館，展示台糖公司早期蒸汽火車頭（如編號604、326、364）、機關車、糖廠老照片及鐵道設施等，另可提供團體預約導覽服務。', '臺灣糖業股份有限公司', '彰化縣溪湖鎮彰水路二段762號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '溪湖糖廠', 23.95171456, 120.4831739, '無資料', 'http://tourism.chcg.gov.tw/AttractionsContent.aspx?id=30&chk=b11a2980-1154-43b4-be28-59c39fb6e8c2', '[]') ON DUPLICATE KEY UPDATE `activity_name`='溪湖糖廠-蒸汽火車展示', `description`='位於鐵道文化區內，建於1977年，原為鐵道檢車庫。2008年整修作為蒸汽火車展示館，展示台糖公司早期蒸汽火車頭（如編號604、326、364）、機關車、糖廠老照片及鐵道設施等，另可提供團體預約導覽服務。', `organizer`='臺灣糖業股份有限公司', `address`='彰化縣溪湖鎮彰水路二段762號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='溪湖糖廠', `latitude`=23.95171456, `longitude`=120.4831739, `ticket_price`='無資料', `source_url`='http://tourism.chcg.gov.tw/AttractionsContent.aspx?id=30&chk=b11a2980-1154-43b4-be28-59c39fb6e8c2', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633ce', '文化資產再利用成果展', '溪湖糖廠「文化資產再利用成果展」於溪湖糖廠文物館二樓展出，每日09:00-16:30開放自由參觀，歡迎各界蒞臨觀賞。 ', '臺灣糖業股份有限公司', '彰化縣溪湖鎮彰水路二段762號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '溪湖糖廠', 23.95171456, 120.4831739, '無資料', 'https://www.facebook.com/tsc14.taisugar/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='文化資產再利用成果展', `description`='溪湖糖廠「文化資產再利用成果展」於溪湖糖廠文物館二樓展出，每日09:00-16:30開放自由參觀，歡迎各界蒞臨觀賞。 ', `organizer`='臺灣糖業股份有限公司', `address`='彰化縣溪湖鎮彰水路二段762號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='溪湖糖廠', `latitude`=23.95171456, `longitude`=120.4831739, `ticket_price`='無資料', `source_url`='https://www.facebook.com/tsc14.taisugar/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633cf', '2025彰化月影燈季', '八卦山大佛風景區一直是許多彰化人心靈寄託，習慣會來參拜大佛為新年祈福。「2024彰化月影燈季」除了提供傳統歲末年初時節濃厚的過節氣氛，今年也設計不同以往的主題燈區讓大家前來賞燈哦！', '彰化縣政府', '彰化縣彰化市溫泉路31號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '彰化八卦山大佛區', 24.07532909, 120.5694208, '無資料', 'https://ch-emoji.mystrikingly.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025彰化月影燈季', `description`='八卦山大佛風景區一直是許多彰化人心靈寄託，習慣會來參拜大佛為新年祈福。「2024彰化月影燈季」除了提供傳統歲末年初時節濃厚的過節氣氛，今年也設計不同以往的主題燈區讓大家前來賞燈哦！', `organizer`='彰化縣政府', `address`='彰化縣彰化市溫泉路31號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='彰化八卦山大佛區', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://ch-emoji.mystrikingly.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fb26b32458d43633d7', '賴子昕西畫個展', '或許你也曾透過展場，跟著許多創作者關懷世界各個角落的人權、文化，感受不同地方的環境和人文，但在面對文字叢林以及斑斕而獨特視角的畫面時，是否曾提醒自己也擁有理解的自由?是不是都被慣性地遺忘生來就擁有的思辨?\r\n\r\n「自由」是創作的靈魂，經驗與意識因它而產生星火，直到燃燒了那與之共鳴的心。\r\n\r\n在每一筆的落下與提筆之間、在思緒沾滿顏料而忘我動筆之刻，創作者享受著對自己提問，揮灑著許多疑問與掙扎，而在最後一筆結束前，誠實的面對自己，領悟釋懷與解脫…\r\n\r\n   畫展延續著這樣的自由與疏狂，不想因為太多刻意的介紹而設下美的框架，讓畫展回歸觀看者與畫之間的對話和共鳴，找回從孩提時期就擁有的好奇和思辨，進而達到「自由之美的純粹」。\r\n\r\n   願每個走近畫前的觀眾都能帶著空白的心，與畫作之間激盪出屬於自己的人生故事，不再因為文字而受限的想像，能化作思考的星火，燃遍這自由而美的純粹天空。', '彰化縣文化局', '彰化縣員林市員林大道2段99號', '2025-02-11 00:00:00', '2025-03-02 00:00:00', '彰化縣員林演藝廳', 23.95650448, 120.593073, '無資料', 'https://performance.bocach.gov.tw/News_Content.aspx?n=1043&s=50605', '[]') ON DUPLICATE KEY UPDATE `activity_name`='賴子昕西畫個展', `description`='或許你也曾透過展場，跟著許多創作者關懷世界各個角落的人權、文化，感受不同地方的環境和人文，但在面對文字叢林以及斑斕而獨特視角的畫面時，是否曾提醒自己也擁有理解的自由?是不是都被慣性地遺忘生來就擁有的思辨?\r\n\r\n「自由」是創作的靈魂，經驗與意識因它而產生星火，直到燃燒了那與之共鳴的心。\r\n\r\n在每一筆的落下與提筆之間、在思緒沾滿顏料而忘我動筆之刻，創作者享受著對自己提問，揮灑著許多疑問與掙扎，而在最後一筆結束前，誠實的面對自己，領悟釋懷與解脫…\r\n\r\n   畫展延續著這樣的自由與疏狂，不想因為太多刻意的介紹而設下美的框架，讓畫展回歸觀看者與畫之間的對話和共鳴，找回從孩提時期就擁有的好奇和思辨，進而達到「自由之美的純粹」。\r\n\r\n   願每個走近畫前的觀眾都能帶著空白的心，與畫作之間激盪出屬於自己的人生故事，不再因為文字而受限的想像，能化作思考的星火，燃遍這自由而美的純粹天空。', `organizer`='彰化縣文化局', `address`='彰化縣員林市員林大道2段99號', `start_date`='2025-02-11 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='彰化縣員林演藝廳', `latitude`=23.95650448, `longitude`=120.593073, `ticket_price`='無資料', `source_url`='https://performance.bocach.gov.tw/News_Content.aspx?n=1043&s=50605', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fc26b32458d43633d9', '無資料', '本次聯展以“浮光絮語”為主題，匯聚了多位藝術家的創作，展現女性意象與自然生態的和諧共鳴。展覽中將體驗到多元化的藝術表現，從高跟鞋的象徵意義到動物與植物的交織，呈現多元而美麗的畫面，讓觀眾都能感受到生命的美好與情感的深度。\r\n\r\n展覽之一是高跟鞋的藝術表現。雖是時尚配飾品，更是女性獨立與自信的象徵。透過多樣化的創作手法，將它賦予新的生命，彰顯其優雅與力量。\r\n\r\n在鳥類畫品，這些畫作展現了鳥兒的自由與靈動，捕捉了自然界中微妙的瞬間。作品不僅展現了鳥類的美麗，也反映了藝術家對自然的熱愛與敬畏，也能與自然的聯結。\r\n\r\n此外優雅動物所帶來的親情與溫馨。鹿作為自然界中的象徵，代表著和平與和諧，這些畫作表達了人與動物之間深厚的情感聯繫。\r\n\r\n另一亮點可愛兔子與貓的畫品，更為展覽增添了輕鬆與愉悅。作品中充滿童趣與生動，讓欣賞者感受到生活中的簡單快樂。\r\n\r\n植物花卉展品則呈現出一種獨特的花意象，象徵著生命的活力更富有詩意與深意，並能感受到春天的生機與浪漫。\r\n\r\n在花卉和窗花兩者的結合，則象徵著家庭的溫暖與安全感。彷彿置身於一個充滿夢想與幻想的花園。傳達了自然的繁榮與家庭的溫暖\r\n\r\n展覽中特別展示了結藝畫，融合結繩與膠彩礦物為背景的畫品，除了寓意著吉祥與美好，也創造出獨特的視覺效果。讓觀者對於傳統與現代的思考，反思文化的延續與變遷。\r\n\r\n整體而言，本次聯展將藝術與自然、情感與文化緊密結合，期待每位參觀者能夠在這裡找到屬於自己的靈感與共鳴，感受到生活中的細膩與美好。', '彰化市公所', '彰化縣彰化市中山路2段542號', '彰化藝術館', 24.07532909, 120.5694208, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='本次聯展以“浮光絮語”為主題，匯聚了多位藝術家的創作，展現女性意象與自然生態的和諧共鳴。展覽中將體驗到多元化的藝術表現，從高跟鞋的象徵意義到動物與植物的交織，呈現多元而美麗的畫面，讓觀眾都能感受到生命的美好與情感的深度。\r\n\r\n展覽之一是高跟鞋的藝術表現。雖是時尚配飾品，更是女性獨立與自信的象徵。透過多樣化的創作手法，將它賦予新的生命，彰顯其優雅與力量。\r\n\r\n在鳥類畫品，這些畫作展現了鳥兒的自由與靈動，捕捉了自然界中微妙的瞬間。作品不僅展現了鳥類的美麗，也反映了藝術家對自然的熱愛與敬畏，也能與自然的聯結。\r\n\r\n此外優雅動物所帶來的親情與溫馨。鹿作為自然界中的象徵，代表著和平與和諧，這些畫作表達了人與動物之間深厚的情感聯繫。\r\n\r\n另一亮點可愛兔子與貓的畫品，更為展覽增添了輕鬆與愉悅。作品中充滿童趣與生動，讓欣賞者感受到生活中的簡單快樂。\r\n\r\n植物花卉展品則呈現出一種獨特的花意象，象徵著生命的活力更富有詩意與深意，並能感受到春天的生機與浪漫。\r\n\r\n在花卉和窗花兩者的結合，則象徵著家庭的溫暖與安全感。彷彿置身於一個充滿夢想與幻想的花園。傳達了自然的繁榮與家庭的溫暖\r\n\r\n展覽中特別展示了結藝畫，融合結繩與膠彩礦物為背景的畫品，除了寓意著吉祥與美好，也創造出獨特的視覺效果。讓觀者對於傳統與現代的思考，反思文化的延續與變遷。\r\n\r\n整體而言，本次聯展將藝術與自然、情感與文化緊密結合，期待每位參觀者能夠在這裡找到屬於自己的靈感與共鳴，感受到生活中的細膩與美好。', `organizer`='彰化市公所', `address`='彰化縣彰化市中山路2段542號', `location`='彰化藝術館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fc26b32458d43633da', '生活-藝術/彰化縣共硯生活藝術學會', '彰化縣共硯生活藝術學會52位成員為來自社會各階層的藝術同好,標舉「藝術生活化,生活藝術化」的宗旨,於2008年元月正式成立。再經彰化縣政府2023年3月2日府社發展字第1120059833號函准予立案備查。現代高度物質文明匆忙的生活步調中,唯有藝術的薰陶與陳前可提升心靈層次,帶來幸福感受,將藝術融入生活是美化人生的不二法門。會員們本著藝術修心為出發點,以恭敬心研習與創作,追求「真、善、美」為共同鵠的。\r\n\r\n \r\n\r\n傳統水墨/現代墨彩畫,兼容並蓄,楷書/行書/隸書各種書體呈現在成員的書法作品中,以鄉土風情為題材,師法自然,轉化真實景物於木雕創作,將傳統工藝導入日常生活中,用鐵絲纏繞為一盆姿態自如的盆栽作品,以細膩的手工縫製成維妙維肖的布偶,出色的禪繞畫,逼真的色鉛筆畫/粉彩畫處處可見。\r\n\r\n \r\n\r\n傳統中國花鳥畫”所謂「花若解語還多事,石不能言最可人」中國人的這種萬物有情觀,最能具限於花鳥畫中,畫中的 一隻一葉都流露了畫家的 詩情與處事態度.現代山水墨彩畫,畫家以筆墨點染出豐腴的山水靈韻.楷書/行書/隸書各種書體呈現在成員的書法作品中,以鄉土風情為題材,師法自然,轉化真實景物於木雕創作,將傳統工藝導入日常生活中,用鐵絲纏繞為一盆姿態自如的盆栽作品,以細膩的手工縫製成維妙維肖的布偶,出色的禪繞畫,逼真的色鉛筆畫/粉彩畫處處可見畫家的匠心,運用傳統的水印木刻風俗畫的技法與工具,將山水風景刻劃在木板上,並拓印在傳統的宣紙上,有別於傳統的水墨畫神韻,但有透明水彩畫的意境及表現.透過油畫及壓克力畫作抒發對生命的熱愛及美學的發想,將對自然萬物的共鳴、歲月的感動、心靈的沉思,透過創作實現內在與外在的轉譯兌現,每道筆觸、構圖都是生活的足跡、人生態度的體現.', '彰化市公所', '彰化縣彰化市中山路2段542號', '2025-02-25 00:00:00', '2025-03-18 00:00:00', '彰化藝術館', 24.07532909, 120.5694208, '無資料', 'https://www.changhua.gov.tw/RowContent/3355?pgid=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='生活-藝術/彰化縣共硯生活藝術學會', `description`='彰化縣共硯生活藝術學會52位成員為來自社會各階層的藝術同好,標舉「藝術生活化,生活藝術化」的宗旨,於2008年元月正式成立。再經彰化縣政府2023年3月2日府社發展字第1120059833號函准予立案備查。現代高度物質文明匆忙的生活步調中,唯有藝術的薰陶與陳前可提升心靈層次,帶來幸福感受,將藝術融入生活是美化人生的不二法門。會員們本著藝術修心為出發點,以恭敬心研習與創作,追求「真、善、美」為共同鵠的。\r\n\r\n \r\n\r\n傳統水墨/現代墨彩畫,兼容並蓄,楷書/行書/隸書各種書體呈現在成員的書法作品中,以鄉土風情為題材,師法自然,轉化真實景物於木雕創作,將傳統工藝導入日常生活中,用鐵絲纏繞為一盆姿態自如的盆栽作品,以細膩的手工縫製成維妙維肖的布偶,出色的禪繞畫,逼真的色鉛筆畫/粉彩畫處處可見。\r\n\r\n \r\n\r\n傳統中國花鳥畫”所謂「花若解語還多事,石不能言最可人」中國人的這種萬物有情觀,最能具限於花鳥畫中,畫中的 一隻一葉都流露了畫家的 詩情與處事態度.現代山水墨彩畫,畫家以筆墨點染出豐腴的山水靈韻.楷書/行書/隸書各種書體呈現在成員的書法作品中,以鄉土風情為題材,師法自然,轉化真實景物於木雕創作,將傳統工藝導入日常生活中,用鐵絲纏繞為一盆姿態自如的盆栽作品,以細膩的手工縫製成維妙維肖的布偶,出色的禪繞畫,逼真的色鉛筆畫/粉彩畫處處可見畫家的匠心,運用傳統的水印木刻風俗畫的技法與工具,將山水風景刻劃在木板上,並拓印在傳統的宣紙上,有別於傳統的水墨畫神韻,但有透明水彩畫的意境及表現.透過油畫及壓克力畫作抒發對生命的熱愛及美學的發想,將對自然萬物的共鳴、歲月的感動、心靈的沉思,透過創作實現內在與外在的轉譯兌現,每道筆觸、構圖都是生活的足跡、人生態度的體現.', `organizer`='彰化市公所', `address`='彰化縣彰化市中山路2段542號', `start_date`='2025-02-25 00:00:00', `end_date`='2025-03-18 00:00:00', `location`='彰化藝術館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.changhua.gov.tw/RowContent/3355?pgid=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fc26b32458d43633db', '明倫國中美術班第26屆畢業美展', '明倫國中美術班成立至今已28年，本次展覽為26屆學生們的作品，展出類別豐富，有素描、水彩、壓克力畫、水墨、版畫、電繪、漫畫…等.，因循著同學們各自的喜好，用自己的方式，表達對生活、現況、過去、時事、與未來等的感受和期待，每個人都有自己獨有的樣貌。\r\n\r\n在這個班上，同學們各個能文能武，自我風格鮮明，用屬於青春的語彙，揮灑出豐富色彩，這三年來累積的能量，在這次展覽中作最精彩的發揮。\r\n\r\n透過不同創作探索搭配，運用多元媒材創造多樣的質地，讓觀賞者更能沉澱在作品中作者所要敘述的靈感來源，及其背後的技法表達。\r\n\r\n……從視覺觀察作品之寧靜意境，及其所反映之創作技法，而一幅畫是由不同元素所構成的，蘊藏著統合感、質感、比例、明度、色彩、形體感、韻律感……等等。線條搭配適當的色彩，運用透明堆疊的筆觸、色塊，重新詮釋在光線與空間令人產生感動之題材，創作出一幅主次分明、虛實呼應，繼而產生之層次變化，以保持和諧及完美之畫面。透過這些元素來表達構思的成果，運用適當的彩度與色相，而色彩的佈局其實就是構成畫面的主要元素之一，從而讓觀賞者產生共鳴感!', '彰化縣文化局', '彰化縣員林市員林大道2段99號', '2025-03-04 00:00:00', '2025-03-23 00:00:00', '彰化縣員林演藝廳', 23.95650448, 120.593073, '無資料', 'https://www.bocach.gov.tw/News_Content.aspx?n=92&s=50557', '[]') ON DUPLICATE KEY UPDATE `activity_name`='明倫國中美術班第26屆畢業美展', `description`='明倫國中美術班成立至今已28年，本次展覽為26屆學生們的作品，展出類別豐富，有素描、水彩、壓克力畫、水墨、版畫、電繪、漫畫…等.，因循著同學們各自的喜好，用自己的方式，表達對生活、現況、過去、時事、與未來等的感受和期待，每個人都有自己獨有的樣貌。\r\n\r\n在這個班上，同學們各個能文能武，自我風格鮮明，用屬於青春的語彙，揮灑出豐富色彩，這三年來累積的能量，在這次展覽中作最精彩的發揮。\r\n\r\n透過不同創作探索搭配，運用多元媒材創造多樣的質地，讓觀賞者更能沉澱在作品中作者所要敘述的靈感來源，及其背後的技法表達。\r\n\r\n……從視覺觀察作品之寧靜意境，及其所反映之創作技法，而一幅畫是由不同元素所構成的，蘊藏著統合感、質感、比例、明度、色彩、形體感、韻律感……等等。線條搭配適當的色彩，運用透明堆疊的筆觸、色塊，重新詮釋在光線與空間令人產生感動之題材，創作出一幅主次分明、虛實呼應，繼而產生之層次變化，以保持和諧及完美之畫面。透過這些元素來表達構思的成果，運用適當的彩度與色相，而色彩的佈局其實就是構成畫面的主要元素之一，從而讓觀賞者產生共鳴感!', `organizer`='彰化縣文化局', `address`='彰化縣員林市員林大道2段99號', `start_date`='2025-03-04 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='彰化縣員林演藝廳', `latitude`=23.95650448, `longitude`=120.593073, `ticket_price`='無資料', `source_url`='https://www.bocach.gov.tw/News_Content.aspx?n=92&s=50557', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fc26b32458d43633dc', '返鄉/彰化縣政府退休主管書藝展', '我們曾是一群在彰化縣政府公務崗位上，為縣政各領域拼搏一輩子的中高階主管，如民國90年建設局長退休的徐英一、91年兵役局長退休的施國華、71年到78年任職彰化縣政府建設局的賴再生局長、112年退休的林淑連參議，以及民政處退休的蔡銘峯副處長、建設處退休的楊麗琴副處長、陳諸勤課長、行政室退休的張有泉副主任等八人。除了施國華局長早年即涉獵書法，並在全國舉辦多次個展，及出版書法專輯12冊外，好多人在退休前對藝術一竅不通，後因著藝術重新發現了生活的美好。\r\n\r\n這群主管在退休後，為了讓藝文點綴生活，讓藝術生活化，紛紛拜師學藝，開始接觸各種藝術形式，如師承李憲專老師書法及水彩畫林世輝老師的徐英一；師承王太田等名師學畫，後又再跟隨名師學流墨畫及噴墨畫的賴再生；師承吳燈錫及江慶章老師水墨畫及葉心慈老師工筆畫的楊麗琴；師承楊秀椿老師的林淑連工藝彩繪；師承粘文意老師書法的蔡銘峯、張有泉、陳諸勤等，均深深浸淫在藝術叢林中，如今更能夠舞文弄墨，表達內心的情感與想法，反映對生活的感悟和藝術的熱愛，進而在創作上得到成就與突破。\r\n', '彰化市公所', '彰化縣彰化市中山路2段542號', '2025-03-20 00:00:00', '2025-04-08 00:00:00', '彰化藝術館', 24.07532909, 120.5694208, '無資料', 'https://www.changhua.gov.tw/RowContent/3356?pgid=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='返鄉/彰化縣政府退休主管書藝展', `description`='我們曾是一群在彰化縣政府公務崗位上，為縣政各領域拼搏一輩子的中高階主管，如民國90年建設局長退休的徐英一、91年兵役局長退休的施國華、71年到78年任職彰化縣政府建設局的賴再生局長、112年退休的林淑連參議，以及民政處退休的蔡銘峯副處長、建設處退休的楊麗琴副處長、陳諸勤課長、行政室退休的張有泉副主任等八人。除了施國華局長早年即涉獵書法，並在全國舉辦多次個展，及出版書法專輯12冊外，好多人在退休前對藝術一竅不通，後因著藝術重新發現了生活的美好。\r\n\r\n這群主管在退休後，為了讓藝文點綴生活，讓藝術生活化，紛紛拜師學藝，開始接觸各種藝術形式，如師承李憲專老師書法及水彩畫林世輝老師的徐英一；師承王太田等名師學畫，後又再跟隨名師學流墨畫及噴墨畫的賴再生；師承吳燈錫及江慶章老師水墨畫及葉心慈老師工筆畫的楊麗琴；師承楊秀椿老師的林淑連工藝彩繪；師承粘文意老師書法的蔡銘峯、張有泉、陳諸勤等，均深深浸淫在藝術叢林中，如今更能夠舞文弄墨，表達內心的情感與想法，反映對生活的感悟和藝術的熱愛，進而在創作上得到成就與突破。\r\n', `organizer`='彰化市公所', `address`='彰化縣彰化市中山路2段542號', `start_date`='2025-03-20 00:00:00', `end_date`='2025-04-08 00:00:00', `location`='彰化藝術館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.changhua.gov.tw/RowContent/3356?pgid=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fc26b32458d43633dd', '星期五畫會-會員聯展', '「星期五畫會」是一個由一群熱愛藝術的人組成的聚會，每逢星期五早上我們相聚在一起，共同探索藝術的無限可能性，這個畫會成立已經有十多年的歷史。我們在「星期五畫會」的創作經歷帶來了許多啟發和新的創作思維，從與不同背景和風格的藝術交流中獲得了許多靈感，並且開拓了自己的視野。這對我們的創作風格和表達方式產生了積極的影響，並且讓我們能夠更好地傳達自己的情感和想法。\r\n\r\n在創作中，我們不斷地從日常生活中尋找靈感和素材。無論是一朵盛開的花朵、一個街頭的風景，還是一段深夜的對話，都可能 成為創作的起點。這些看似平凡的事物，在藝術中獲得了新的生命。通過觀察和體驗，我們將自己的生命經驗融入到作品中，使其更加豐富和真實，進入了一個充滿靜默和自由的空間。在這個空間中，我們不受任何約束，可以盡情地表達自己的情感和思想。這種對靈魂的撫慰和安撫，令人感到無比的平靜和寧靜。\r\n\r\n此次聯展是同好們在郭煥材老師的指導下，再一次嘗試突破，點畫出自己的話語，直指內心最原始的翻騰，形塑完整的自我，喚醒自我成長的力量與渴望，是現實生活中的轉換。描寫對 象從客觀的外在描寫到主觀內在表現，從國畫到西畫，每個人皆 展現出自己獨特且豐富多元的藝術語言。', '彰化市公所', '彰化縣彰化市中山路2段542號', '2025-04-10 00:00:00', '2025-04-27 00:00:00', '彰化藝術館', 24.07532909, 120.5694208, '無資料', 'https://www.changhua.gov.tw/RowContent/3357?pgid=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='星期五畫會-會員聯展', `description`='「星期五畫會」是一個由一群熱愛藝術的人組成的聚會，每逢星期五早上我們相聚在一起，共同探索藝術的無限可能性，這個畫會成立已經有十多年的歷史。我們在「星期五畫會」的創作經歷帶來了許多啟發和新的創作思維，從與不同背景和風格的藝術交流中獲得了許多靈感，並且開拓了自己的視野。這對我們的創作風格和表達方式產生了積極的影響，並且讓我們能夠更好地傳達自己的情感和想法。\r\n\r\n在創作中，我們不斷地從日常生活中尋找靈感和素材。無論是一朵盛開的花朵、一個街頭的風景，還是一段深夜的對話，都可能 成為創作的起點。這些看似平凡的事物，在藝術中獲得了新的生命。通過觀察和體驗，我們將自己的生命經驗融入到作品中，使其更加豐富和真實，進入了一個充滿靜默和自由的空間。在這個空間中，我們不受任何約束，可以盡情地表達自己的情感和思想。這種對靈魂的撫慰和安撫，令人感到無比的平靜和寧靜。\r\n\r\n此次聯展是同好們在郭煥材老師的指導下，再一次嘗試突破，點畫出自己的話語，直指內心最原始的翻騰，形塑完整的自我，喚醒自我成長的力量與渴望，是現實生活中的轉換。描寫對 象從客觀的外在描寫到主觀內在表現，從國畫到西畫，每個人皆 展現出自己獨特且豐富多元的藝術語言。', `organizer`='彰化市公所', `address`='彰化縣彰化市中山路2段542號', `start_date`='2025-04-10 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='彰化藝術館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.changhua.gov.tw/RowContent/3357?pgid=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fc26b32458d43633de', '彩藝交輝 彰化縣青溪新文藝學會', '【彩藝交輝】中彰投青溪新文藝學會是由臺中市，南投縣，彰化市青溪新文藝學會和臺中市青溪文藝學會，四個學會共同組成聯展。青溪新文藝學會是一個很特殊的學會，原各分屬各縣市團管區輔導及推動，於民國72年依據人民團體組織法社立之社會團體，成員包括後備軍人，親友，及藝文愛好者，推動「生活藝術化，藝術生活化」。多年來，青溪為促進國家藝文風尚，培養創作人才，宣揚戰鬥文藝，深化民眾對全民國防的瞭解與認同，共同努力。此次展覽項目有油畫，水彩，國畫，書法，雕刻，陶藝，泥塑，攝影……等創作多元化，內容豐富，多才多藝。我們拭目以待。', '彰化市公所', '彰化縣彰化市中山路2段542號', '2025-04-29 00:00:00', '2025-05-18 00:00:00', '彰化藝術館', 24.07532909, 120.5694208, '無資料', 'https://www.changhua.gov.tw/RowContent/3358?pgid=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彩藝交輝 彰化縣青溪新文藝學會', `description`='【彩藝交輝】中彰投青溪新文藝學會是由臺中市，南投縣，彰化市青溪新文藝學會和臺中市青溪文藝學會，四個學會共同組成聯展。青溪新文藝學會是一個很特殊的學會，原各分屬各縣市團管區輔導及推動，於民國72年依據人民團體組織法社立之社會團體，成員包括後備軍人，親友，及藝文愛好者，推動「生活藝術化，藝術生活化」。多年來，青溪為促進國家藝文風尚，培養創作人才，宣揚戰鬥文藝，深化民眾對全民國防的瞭解與認同，共同努力。此次展覽項目有油畫，水彩，國畫，書法，雕刻，陶藝，泥塑，攝影……等創作多元化，內容豐富，多才多藝。我們拭目以待。', `organizer`='彰化市公所', `address`='彰化縣彰化市中山路2段542號', `start_date`='2025-04-29 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='彰化藝術館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.changhua.gov.tw/RowContent/3358?pgid=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fc26b32458d43633df', '國際交流計畫成果展', '本次展覽為國立彰化師範大學美術系與英國SUP國際交流計畫的藝術創作成果展。展出的作品內容為，本系師生與英國二位藝術家在台灣彰化師範大學駐校期間的創作成果。英國來訪二位藝術家會以對台灣的自然景觀、社會文化或對當地社區的觀察，來展現反映在創作內容。此次展覽活動是英國與台灣之間很棒的藝術文化交流學習的橋樑，不僅促進雙方藝術的相互理解同時也讓彰化師範大學美術系師生跨文化的藝術合作學習。歡迎大家一同來參與這樣的國際藝術交流展覽活動，不僅可以欣賞作品，還能增進對於不同國際文化的理解，說不定還可以激發更多的個人創意和靈感。', '彰化市公所', '彰化縣彰化市中山路2段542號', '2025-05-20 00:00:00', '2025-06-08 00:00:00', '彰化藝術館', 24.07532909, 120.5694208, '無資料', 'https://www.changhua.gov.tw/RowContent/3359?pgid=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國際交流計畫成果展', `description`='本次展覽為國立彰化師範大學美術系與英國SUP國際交流計畫的藝術創作成果展。展出的作品內容為，本系師生與英國二位藝術家在台灣彰化師範大學駐校期間的創作成果。英國來訪二位藝術家會以對台灣的自然景觀、社會文化或對當地社區的觀察，來展現反映在創作內容。此次展覽活動是英國與台灣之間很棒的藝術文化交流學習的橋樑，不僅促進雙方藝術的相互理解同時也讓彰化師範大學美術系師生跨文化的藝術合作學習。歡迎大家一同來參與這樣的國際藝術交流展覽活動，不僅可以欣賞作品，還能增進對於不同國際文化的理解，說不定還可以激發更多的個人創意和靈感。', `organizer`='彰化市公所', `address`='彰化縣彰化市中山路2段542號', `start_date`='2025-05-20 00:00:00', `end_date`='2025-06-08 00:00:00', `location`='彰化藝術館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.changhua.gov.tw/RowContent/3359?pgid=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6775b4fc26b32458d43633e0', '林俊寅創作展', '林老師生於彰化縣線西鄉頂庄村的一個農村世家，祖父、父親素懷藝術材質，舉凡書畫、詩文、雕鏤皆有造詣，自幼深受薰陶和教導對於文學予以樹有著潛在的素養與興趣。\r\n\r\n初衷畢業考取台中師範，選修了美勞組，在林之助、呂佛庭名師的教導下，對於藝術創作才有基本的認識，對於藝術創作才有基本的認識，往後又在師專和私人畫室習畫多年，並到執教台中商專的楊啟東大師學習西畫，師專畢業後在小學任教，服務期滿參加(國)高中美術教師檢定，都在最短期限獲得通過。由於長期擔任美術教職，深深體悟「學然後知不足」的道理，他又考取台師大美術系與研究所進修，在學期間學、術科成績優異，精於中西繪畫與美術理論。再林玉山、陳慧坤、馬白水、梁秀中、王秀雄、李焜培、王哲雄…等名師的指導下，在繪畫的創作上有更遼闊的視野。期間沈國仁教授陪同全日水彩畫會理事長不破章八度來台寫生，深受指導也獲益良多。他在眾多名師指導下，奠定他紮實的創作根基。\r\n\r\n他一生創作持之以恆從不間斷，累積許多優秀作品，並參與國內外競賽，曾在日本國際美展，全國教師美展與公教美展獲獎多次。水彩、油畫連續七年八度入選法國藝術家沙龍、彰化縣展油畫、水彩、漫畫壁報、美術教具榮獲特優、首獎、第一名多次。並多次入選東京亞細亞美展與韓國文化大賞展及法國獨立沙龍展、中部美術協會在北京、安徽展出，被選為廣告看版，在台中、彰化、南投文化局四度以他的畫作做為每月藝文活動的封面、勞委會記事手冊、全國郵政總局發行郵冊、高鐵T Life雜誌封面都有其畫作呈現。歷任台中市美術家徵選、全國媽祖徵畫、彰化磺溪美術貢獻獎、美術家接力展、磺溪美展、全省學生美展、世界兒童美展、中部美展、寶成全國寫生、中部、台中、彰化寫生比賽評審委員，為中部地區少數有此殊榮者。\r\n\r\n他除了努力創作外，也熱心推動美育，彰化美術教師聯誼會、彰化縣美術學會的成立，均為發起人之一，並創設道東文教協會與卦山畫會，也任兩屆彰化縣美術學會的理事長，現任中部水彩畫會會長。也在彰化縣文化局的彰化藝文與救國團的彰化青年的圖文連載「畫我家鄉」三年之久。中學退休後轉任大學推廣部執教，總計大、中、小學任教五十年之久，作育英才無數。由於這些事蹟，榮獲文建會資深文化人獎、省府社教有功人員、建縣三百年文化藝術類特殊貢獻、彰化縣特殊優良教師、台中教育大學傑出校友、線西鄉傑出人士表揚，他經常應邀在國內外展出，個展二十次、聯展數百次。由彰化縣府、彰化市公所、員林市公所、建國科大編印專輯六冊。作品為公家機構與私人典藏。為享譽國內外的油畫、水彩畫名家。', '彰化市公所', '彰化縣彰化市中山路2段542號', '2025-06-10 00:00:00', '2025-06-29 00:00:00', '彰化藝術館', 24.07532909, 120.5694208, '無資料', 'https://www.changhua.gov.tw/RowContent/3360?pgid=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='林俊寅創作展', `description`='林老師生於彰化縣線西鄉頂庄村的一個農村世家，祖父、父親素懷藝術材質，舉凡書畫、詩文、雕鏤皆有造詣，自幼深受薰陶和教導對於文學予以樹有著潛在的素養與興趣。\r\n\r\n初衷畢業考取台中師範，選修了美勞組，在林之助、呂佛庭名師的教導下，對於藝術創作才有基本的認識，對於藝術創作才有基本的認識，往後又在師專和私人畫室習畫多年，並到執教台中商專的楊啟東大師學習西畫，師專畢業後在小學任教，服務期滿參加(國)高中美術教師檢定，都在最短期限獲得通過。由於長期擔任美術教職，深深體悟「學然後知不足」的道理，他又考取台師大美術系與研究所進修，在學期間學、術科成績優異，精於中西繪畫與美術理論。再林玉山、陳慧坤、馬白水、梁秀中、王秀雄、李焜培、王哲雄…等名師的指導下，在繪畫的創作上有更遼闊的視野。期間沈國仁教授陪同全日水彩畫會理事長不破章八度來台寫生，深受指導也獲益良多。他在眾多名師指導下，奠定他紮實的創作根基。\r\n\r\n他一生創作持之以恆從不間斷，累積許多優秀作品，並參與國內外競賽，曾在日本國際美