INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6778536326b32458d4363444', ' LEARPRINT 內惟聲響實驗 65聲道的交響體驗', '《LEARPRINT 內惟聲響實驗-65聲道的交響體驗》是法國音場設計與聲學創作人—阿蘭•馮榭（ALAIN FRANÇAIS）所作，乍看下為一顆顆純白簡樸的音箱組成，似乎不足為奇。但當你走進音箱之間，將感知到每種樂器無比清晰的聲音。每個音箱猶如一件件樂器真實地在耳邊演奏。與一般聆聽數位音樂不同，更多了立體及空間環繞之感，翻轉大家以往的聽覺體驗與享受。\r\n\r\n高雄為台灣少數同時擁有中、西兩個樂團的城市，2016年阿蘭•馮榭至高雄為高雄市交響樂團與高雄國樂團錄製了近15首樂團曲目。國樂與西樂在編製與樂器音量表現上大有不同，這項差異激發了他產生許多創意與挑戰，將音箱技術翻轉成為藝術展演。讓觀眾跟隨自己的好奇心，抬起步伐，穿梭於65顆音箱，捕捉每件樂器特定音色和位置，彷彿就是樂團音樂家的一員。\r\n\r\n現在，來內惟藝術中心除了欣賞展覽、找尋歷史循跡，品嘗美食，現在更將掀起一場音樂革命！《LEARPRINT 內惟聲響實驗-65聲道的交響體驗》打破了以往演奏者、觀賞者的身分界線，觀者不再只是遠遠的眺望，如同內惟藝術中心打開藝術與生活的藩籬，創造更多日常美學新體驗，邀請大家一起駐足於音箱之中，來一場前所未有的美好聆聽饗宴！', '高雄市立美術館', '高雄市鼓山區馬卡道路329號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '無資料', 'https://www.nwac.org.tw/tw/news-content/0378575Ae540', '[]') ON DUPLICATE KEY UPDATE `activity_name`=' LEARPRINT 內惟聲響實驗 65聲道的交響體驗', `description`='《LEARPRINT 內惟聲響實驗-65聲道的交響體驗》是法國音場設計與聲學創作人—阿蘭•馮榭（ALAIN FRANÇAIS）所作，乍看下為一顆顆純白簡樸的音箱組成，似乎不足為奇。但當你走進音箱之間，將感知到每種樂器無比清晰的聲音。每個音箱猶如一件件樂器真實地在耳邊演奏。與一般聆聽數位音樂不同，更多了立體及空間環繞之感，翻轉大家以往的聽覺體驗與享受。\r\n\r\n高雄為台灣少數同時擁有中、西兩個樂團的城市，2016年阿蘭•馮榭至高雄為高雄市交響樂團與高雄國樂團錄製了近15首樂團曲目。國樂與西樂在編製與樂器音量表現上大有不同，這項差異激發了他產生許多創意與挑戰，將音箱技術翻轉成為藝術展演。讓觀眾跟隨自己的好奇心，抬起步伐，穿梭於65顆音箱，捕捉每件樂器特定音色和位置，彷彿就是樂團音樂家的一員。\r\n\r\n現在，來內惟藝術中心除了欣賞展覽、找尋歷史循跡，品嘗美食，現在更將掀起一場音樂革命！《LEARPRINT 內惟聲響實驗-65聲道的交響體驗》打破了以往演奏者、觀賞者的身分界線，觀者不再只是遠遠的眺望，如同內惟藝術中心打開藝術與生活的藩籬，創造更多日常美學新體驗，邀請大家一起駐足於音箱之中，來一場前所未有的美好聆聽饗宴！', `organizer`='高雄市立美術館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='無資料', `source_url`='https://www.nwac.org.tw/tw/news-content/0378575Ae540', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6778536426b32458d4363445', '柴燒生活陶藝作品展', '林昭地大師對於陶作種類涉獵之廣，經歷之豐富，是當代傳統陶藝界罕見的，透過本次柴燒生活陶藝品的展出，不僅回顧傳統社會生活面向，更可體會林大師對製陶的堅持，勉勵珍惜當下生活資源。', '高雄市立圖書館總館', '高雄市大樹區25鄰久堂路97-1號', '2025-01-02 00:00:00', '2025-12-31 00:00:00', '高雄市立圖書館大樹二館', 22.6586226, 120.4192897, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='柴燒生活陶藝作品展', `description`='林昭地大師對於陶作種類涉獵之廣，經歷之豐富，是當代傳統陶藝界罕見的，透過本次柴燒生活陶藝品的展出，不僅回顧傳統社會生活面向，更可體會林大師對製陶的堅持，勉勵珍惜當下生活資源。', `organizer`='高雄市立圖書館總館', `address`='高雄市大樹區25鄰久堂路97-1號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄市立圖書館大樹二館', `latitude`=22.6586226, `longitude`=120.4192897, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6778536c26b32458d4363446', '科學發展史/海報主題展', '書庫間海報展:介紹科學發展史：物質、能(力.熱.光.電)、應用、生物與醫學..等。讓民眾到館藉由展覽了解阿基米德、牛頓、赫茲、孟德爾科學發展史的知識與由來。', '高雄市立圖書館總館', '高雄市左營區博愛三路453號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '高雄市立圖書館左新分館', 22.6783295, 120.3046289, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='科學發展史/海報主題展', `description`='書庫間海報展:介紹科學發展史：物質、能(力.熱.光.電)、應用、生物與醫學..等。讓民眾到館藉由展覽了解阿基米德、牛頓、赫茲、孟德爾科學發展史的知識與由來。', `organizer`='高雄市立圖書館總館', `address`='高雄市左營區博愛三路453號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄市立圖書館左新分館', `latitude`=22.6783295, `longitude`=120.3046289, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6778536c26b32458d4363447', '內惟藝術中心首展｜解惟．解圍 Once within Borders', '「內惟藝術中心」，一座由內惟向城市開放的新型態藝術中心。透過與多元藝術體驗之互動，啟動「生活藝術‧藝術生活」城市文化新樣態。在這個場域中，透過社區導向的對話式藝術、當代影像與經典電影、藝術修復與診療等機能，開展出一個親子互動共學的公共生活與生活美學空間。以跨域、跨世代、跨族群「跨、輕、新」之三大精神，融合各種可能性，實現沒有邊界與藩籬的藝術體驗，開啟新型態藝術生活的想像與實踐。\r\n\r\n開幕首展以《解惟‧解圍》為題，「解開圍籬、迎向內惟」透過歷史和當下的對話，從文化空間的敞開、公共場域的再形塑，以及在地社區歷史紋理的重新閱讀，內惟藝術中心將成為「社區縫合」之關鍵角色，形成新都市地貌與文化地景，迎向開放連結的新願景。開幕展以「藝術與空間對話」、「社區參與式創作」及「融入設計思維」的策展為三個核心概念組成。嘗試由藝術作品定義空間的新可能，透過多樣性的藝術觀賞與參與模式形塑居民新的共同經驗，結合社區環境並成為融入市民生活之中。', '內惟藝術中心', '高雄市鼓山區馬卡道路329號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='內惟藝術中心首展｜解惟．解圍 Once within Borders', `description`='「內惟藝術中心」，一座由內惟向城市開放的新型態藝術中心。透過與多元藝術體驗之互動，啟動「生活藝術‧藝術生活」城市文化新樣態。在這個場域中，透過社區導向的對話式藝術、當代影像與經典電影、藝術修復與診療等機能，開展出一個親子互動共學的公共生活與生活美學空間。以跨域、跨世代、跨族群「跨、輕、新」之三大精神，融合各種可能性，實現沒有邊界與藩籬的藝術體驗，開啟新型態藝術生活的想像與實踐。\r\n\r\n開幕首展以《解惟‧解圍》為題，「解開圍籬、迎向內惟」透過歷史和當下的對話，從文化空間的敞開、公共場域的再形塑，以及在地社區歷史紋理的重新閱讀，內惟藝術中心將成為「社區縫合」之關鍵角色，形成新都市地貌與文化地景，迎向開放連結的新願景。開幕展以「藝術與空間對話」、「社區參與式創作」及「融入設計思維」的策展為三個核心概念組成。嘗試由藝術作品定義空間的新可能，透過多樣性的藝術觀賞與參與模式形塑居民新的共同經驗，結合社區環境並成為融入市民生活之中。', `organizer`='內惟藝術中心', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6778537326b32458d4363448', '成人書法進階班', '＊執筆及運筆：學員能了解基本的執筆及運筆的方法，並養成良好的坐姿。\r\n＊永字八法：學會書法的基本筆法-永字八法側（點）、勒（橫）、努（豎）、趯（鉤）、策（挑）、掠（長撇）、啄（短撇）、碟（捺）和折法。\r\n＊筆畫的毛病：學員能知道並避免筆畫的毛病。\r\n＊書體簡介：學員能知道甲骨文、金文、篆書、隸書、草書、楷書及行書的特色，並學會如何欣賞書法之美。\r\n＊作品的形式：學員知道書法的各種作品形式，激發創作的欲望。\r\n＊落款的常識：學員學會落款的常識、位置、用語、字體及用印。', '高雄市立圖書館總館', '高雄市永安區005鄰永華路49號', '2025-01-08 00:00:00', '2025-03-26 00:00:00', '高雄市立圖書館永安分館', 22.8159848, 120.2244381, '一期三個月+1400', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='成人書法進階班', `description`='＊執筆及運筆：學員能了解基本的執筆及運筆的方法，並養成良好的坐姿。\r\n＊永字八法：學會書法的基本筆法-永字八法側（點）、勒（橫）、努（豎）、趯（鉤）、策（挑）、掠（長撇）、啄（短撇）、碟（捺）和折法。\r\n＊筆畫的毛病：學員能知道並避免筆畫的毛病。\r\n＊書體簡介：學員能知道甲骨文、金文、篆書、隸書、草書、楷書及行書的特色，並學會如何欣賞書法之美。\r\n＊作品的形式：學員知道書法的各種作品形式，激發創作的欲望。\r\n＊落款的常識：學員學會落款的常識、位置、用語、字體及用印。', `organizer`='高雄市立圖書館總館', `address`='高雄市永安區005鄰永華路49號', `start_date`='2025-01-08 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='高雄市立圖書館永安分館', `latitude`=22.8159848, `longitude`=120.2244381, `ticket_price`='一期三個月+1400', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6778537326b32458d4363449', '書法基礎B班', '＊執筆及運筆：學員能了解基本的執筆及運筆的方法，並養成良好的坐姿。\r\n＊永字八法：學會書法的基本筆法-永字八法側（點）、勒（橫）、努（豎）、趯（鉤）、策（挑）、掠（長撇）、啄（短撇）、碟（捺）和折法。\r\n＊筆畫的毛病：學員能知道並避免筆畫的毛病。\r\n＊書體簡介：學員能知道甲骨文、金文、篆書、隸書、草書、楷書及行書的特色，並學會如何欣賞書法之美。\r\n＊作品的形式：學員知道書法的各種作品形式，激發創作的欲望。\r\n＊落款的常識：學員學會落款的常識、位置、用語、字體及用印。', '高雄市立圖書館總館', '高雄市永安區005鄰永華路49號', '2025-01-05 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館永安分館', 22.8159848, 120.2244381, '一期三個月+1540', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='書法基礎B班', `description`='＊執筆及運筆：學員能了解基本的執筆及運筆的方法，並養成良好的坐姿。\r\n＊永字八法：學會書法的基本筆法-永字八法側（點）、勒（橫）、努（豎）、趯（鉤）、策（挑）、掠（長撇）、啄（短撇）、碟（捺）和折法。\r\n＊筆畫的毛病：學員能知道並避免筆畫的毛病。\r\n＊書體簡介：學員能知道甲骨文、金文、篆書、隸書、草書、楷書及行書的特色，並學會如何欣賞書法之美。\r\n＊作品的形式：學員知道書法的各種作品形式，激發創作的欲望。\r\n＊落款的常識：學員學會落款的常識、位置、用語、字體及用印。', `organizer`='高雄市立圖書館總館', `address`='高雄市永安區005鄰永華路49號', `start_date`='2025-01-05 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館永安分館', `latitude`=22.8159848, `longitude`=120.2244381, `ticket_price`='一期三個月+1540', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6778537526b32458d436344a', '書寫風景—橫山書法藝術館戶外燈光藝術展 Writing the Landscape: A Light Show', '桃園市立美術館｜橫山書法藝術館（以下簡稱書藝館）為響應臺灣燈會在桃園，在歡慶聖誕佳節至元宵之際，策辦「書寫風景-橫山書法藝術館戶外燈光藝術展」，邀請 4 組藝術家/團隊何景窗、劉名哲、步里赫森、太極影音，以筆墨線條、詩詞、篆刻等書藝元素結合燈光設計、投影，共同回應與營造橫山書法藝術館的「書寫風景」。展區包含「經典書法：曲水流觴」與「現代書藝：詩詞小語」，形成古今對話，邀請觀者不僅關注書法本身，而是進一步探索與感受書藝館夜間場域、書法藝術與我們的多樣關係。', '橫山書法藝術館', '桃園市大園區28鄰大仁路100號', '2025-01-01 00:00:00', '2025-02-24 00:00:00', '橫山書法藝術館', 25.06384709, 121.21177, '無資料', 'https://tmofa.tycg.gov.tw/ch/exhibitions/current-exhibitions/129', '[]') ON DUPLICATE KEY UPDATE `activity_name`='書寫風景—橫山書法藝術館戶外燈光藝術展 Writing the Landscape: A Light Show', `description`='桃園市立美術館｜橫山書法藝術館（以下簡稱書藝館）為響應臺灣燈會在桃園，在歡慶聖誕佳節至元宵之際，策辦「書寫風景-橫山書法藝術館戶外燈光藝術展」，邀請 4 組藝術家/團隊何景窗、劉名哲、步里赫森、太極影音，以筆墨線條、詩詞、篆刻等書藝元素結合燈光設計、投影，共同回應與營造橫山書法藝術館的「書寫風景」。展區包含「經典書法：曲水流觴」與「現代書藝：詩詞小語」，形成古今對話，邀請觀者不僅關注書法本身，而是進一步探索與感受書藝館夜間場域、書法藝術與我們的多樣關係。', `organizer`='橫山書法藝術館', `address`='桃園市大園區28鄰大仁路100號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-24 00:00:00', `location`='橫山書法藝術館', `latitude`=25.06384709, `longitude`=121.21177, `ticket_price`='無資料', `source_url`='https://tmofa.tycg.gov.tw/ch/exhibitions/current-exhibitions/129', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6778537726b32458d436346b', '《埔里的二十首情詩和一首絕望的歌》聯合詩展', '策展人：余鎮綸（是紐西蘭鳳興書院華語講師，是伊諾廚房大廚，是空靈鼓團鼓手，還有很多身份......)\r\n\r\n關於這一檔展覽，起源是\r\n聶魯達，拉丁美洲的文學家、政治家，是1964年的諾貝爾文學獎得主，他的作品以情詩聞名，讀過他的作品，不禁讓人好奇為何有如此多的詞藻與情感？縱觀整個拉丁美洲詩的發展，過去年代的拉美作家生長在外憂內患的時代裡，你會發現許多深邃的美麗與命運的哀愁。\r\n策展人為致敬聶魯達，以其經典作品《二十首情詩和一首絕望的歌》，參照其名稱，以《給埔里的二十首情詩和一首絕望的歌》為題，策畫一場用寫愛跟生活的角度來歌詠埔里這塊土地的人事物與時間的影像有聲詩展，並邀請埔里各行業居民以及暨大師生共同創作，並將最後一首詩作譜以樂音成歌。\r\n邀請您前來觀展。\r\n\r\n開幕茶會時間：114年1月4日 14:00-15:00\r\n茶會流程：\r\n13:45:14:00　活動報到\r\n14:00-14:10　來賓致詞\r\n14:10-14:25　創作者演出\r\n14:25-14:40　下午茶時間\r\n14:40-15:00　詩展導覽', '大灶美術館', '南投縣埔里鎮', '2025-01-04 00:00:00', '2025-03-02 00:00:00', '埔里鎮（南投縣）=', 23.97892591, 120.9625259, '無資料', 'https://www.facebook.com/dazaoart/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《埔里的二十首情詩和一首絕望的歌》聯合詩展', `description`='策展人：余鎮綸（是紐西蘭鳳興書院華語講師，是伊諾廚房大廚，是空靈鼓團鼓手，還有很多身份......)\r\n\r\n關於這一檔展覽，起源是\r\n聶魯達，拉丁美洲的文學家、政治家，是1964年的諾貝爾文學獎得主，他的作品以情詩聞名，讀過他的作品，不禁讓人好奇為何有如此多的詞藻與情感？縱觀整個拉丁美洲詩的發展，過去年代的拉美作家生長在外憂內患的時代裡，你會發現許多深邃的美麗與命運的哀愁。\r\n策展人為致敬聶魯達，以其經典作品《二十首情詩和一首絕望的歌》，參照其名稱，以《給埔里的二十首情詩和一首絕望的歌》為題，策畫一場用寫愛跟生活的角度來歌詠埔里這塊土地的人事物與時間的影像有聲詩展，並邀請埔里各行業居民以及暨大師生共同創作，並將最後一首詩作譜以樂音成歌。\r\n邀請您前來觀展。\r\n\r\n開幕茶會時間：114年1月4日 14:00-15:00\r\n茶會流程：\r\n13:45:14:00　活動報到\r\n14:00-14:10　來賓致詞\r\n14:10-14:25　創作者演出\r\n14:25-14:40　下午茶時間\r\n14:40-15:00　詩展導覽', `organizer`='大灶美術館', `address`='南投縣埔里鎮', `start_date`='2025-01-04 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='埔里鎮（南投縣）=', `latitude`=23.97892591, `longitude`=120.9625259, `ticket_price`='無資料', `source_url`='https://www.facebook.com/dazaoart/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6778537726b32458d4363473', '國立公共資訊圖書館中興分館電影欣賞（114年2月）', '放映影片\r\n2月1日／羅曼律師（西/輔/122分）\r\n2月2日／極限登峰（西/護/100分）\r\n2月5日／芭蕾舞伶與茶花女[紀錄片]（西/普/92分）\r\n2月8日／決勝女王（西/輔/141分）\r\n2月9日／金邊白樓青春夢（柬/普/90分）\r\n2月12日／大藝術家與我（西/普/124分）\r\n2月15日／我的阿茲海默症爸爸（西/護/90分）\r\n2月16日／溫蒂的幸福劇本（西/普/93分）\r\n2月19日／達利劇院美術館 瘋狂達利的奇想世界 [紀錄片]（西/普/56分）\r\n2月22日／當愛不見了（西/護/128分）\r\n2月23日／逆光教師（西/護/106分）\r\n2月26日／波伽利 聲命之歌（西/普/115分）\r\n保護級：6歲以下不宜觀賞\r\n輔導級：12歲以下不宜觀賞\r\n歡迎自由入場欣賞。', '國立公共資訊圖書館中興分館', '南投縣南投市中興新村光華路 123 號', '2025-02-01 00:00:00', '2025-02-26 00:00:00', '國立公共資訊圖書館中興分館', 23.949518, 120.694397, '無資料', 'https://www.facebook.com/NLPICH/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國立公共資訊圖書館中興分館電影欣賞（114年2月）', `description`='放映影片\r\n2月1日／羅曼律師（西/輔/122分）\r\n2月2日／極限登峰（西/護/100分）\r\n2月5日／芭蕾舞伶與茶花女[紀錄片]（西/普/92分）\r\n2月8日／決勝女王（西/輔/141分）\r\n2月9日／金邊白樓青春夢（柬/普/90分）\r\n2月12日／大藝術家與我（西/普/124分）\r\n2月15日／我的阿茲海默症爸爸（西/護/90分）\r\n2月16日／溫蒂的幸福劇本（西/普/93分）\r\n2月19日／達利劇院美術館 瘋狂達利的奇想世界 [紀錄片]（西/普/56分）\r\n2月22日／當愛不見了（西/護/128分）\r\n2月23日／逆光教師（西/護/106分）\r\n2月26日／波伽利 聲命之歌（西/普/115分）\r\n保護級：6歲以下不宜觀賞\r\n輔導級：12歲以下不宜觀賞\r\n歡迎自由入場欣賞。', `organizer`='國立公共資訊圖書館中興分館', `address`='南投縣南投市中興新村光華路 123 號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='國立公共資訊圖書館中興分館', `latitude`=23.949518, `longitude`=120.694397, `ticket_price`='無資料', `source_url`='https://www.facebook.com/NLPICH/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6778537726b32458d4363479', '性別平等主題書展：性別無界、愛是平權', '在當前社會中，性別平等已成為一項重要的普世價值。透過舉辦書展宣導認識並尊重多元性別差異，推廣尊重多元性別，並加強性別平等教育，破除性別刻板印象。\r\n強調建立友善校園及社會環境的重要性，每個人在這個世界上都是獨一無二的存在，學會用愛包容彼此的不同、尊重他人對於性別的認同與傾向都是重要的課題。\r\n展示性別平等相關主題的圖書資料，有助於深化民眾對性別平等教育的認識和意識。藉由挑選的書籍，期望促進社會對於性別角色多樣性的認識。', '高雄市立圖書館總館', '高雄市旗山區大德里6鄰中學路42號', '2025-01-15 00:00:00', '2025-02-27 00:00:00', '高雄市立圖書館旗山分館', 25.0421407, 121.5198716, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='性別平等主題書展：性別無界、愛是平權', `description`='在當前社會中，性別平等已成為一項重要的普世價值。透過舉辦書展宣導認識並尊重多元性別差異，推廣尊重多元性別，並加強性別平等教育，破除性別刻板印象。\r\n強調建立友善校園及社會環境的重要性，每個人在這個世界上都是獨一無二的存在，學會用愛包容彼此的不同、尊重他人對於性別的認同與傾向都是重要的課題。\r\n展示性別平等相關主題的圖書資料，有助於深化民眾對性別平等教育的認識和意識。藉由挑選的書籍，期望促進社會對於性別角色多樣性的認識。', `organizer`='高雄市立圖書館總館', `address`='高雄市旗山區大德里6鄰中學路42號', `start_date`='2025-01-15 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='高雄市立圖書館旗山分館', `latitude`=25.0421407, `longitude`=121.5198716, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6778537826b32458d436347c', '交通安全停看聽主題書展', '交通安全停看聽書展是由館內交通相關主題繪本展出,給民眾借閱。\r\n', '高雄市立圖書館總館', '高雄市新興區6鄰民生一路271號', '2025-01-02 00:00:00', '2025-02-28 00:00:00', '高雄市立圖書館新興民眾閱覽室', 22.6272175, 120.3068429, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='交通安全停看聽主題書展', `description`='交通安全停看聽書展是由館內交通相關主題繪本展出,給民眾借閱。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市新興區6鄰民生一路271號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='高雄市立圖書館新興民眾閱覽室', `latitude`=22.6272175, `longitude`=120.3068429, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6779a52626b32458d4363482', '2025苗栗𪹚龍：燈飾設計展', '歡迎來到苗栗市充滿元宵節喜慶氛圍的街道！今年的燈飾設計展現出「龍城」輪廓意象，在南苗三角公園旁與玉清路玉清宮牌樓旁的天幕上，分別有尾威武的龍形燈籠穿梭於雲霧之中，下方環繞著閃耀的球型燈飾與彩燈串，展現濃厚的火旁龍節慶文化。另，貓裏喵親子公園的生命之樹，更可吸引大眾目光並帶給大家溫暖與希望。\r\n在這璀璨的燈海中，讓我們一同提前感受元宵佳節的溫馨與喜悅！', '苗栗縣苗栗市公所', '苗栗縣苗栗市', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '苗栗市（苗栗縣）=', 24.56382141, 120.8112299, '無資料', 'https://www.facebook.com/mlcg01', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025苗栗𪹚龍：燈飾設計展', `description`='歡迎來到苗栗市充滿元宵節喜慶氛圍的街道！今年的燈飾設計展現出「龍城」輪廓意象，在南苗三角公園旁與玉清路玉清宮牌樓旁的天幕上，分別有尾威武的龍形燈籠穿梭於雲霧之中，下方環繞著閃耀的球型燈飾與彩燈串，展現濃厚的火旁龍節慶文化。另，貓裏喵親子公園的生命之樹，更可吸引大眾目光並帶給大家溫暖與希望。\r\n在這璀璨的燈海中，讓我們一同提前感受元宵佳節的溫馨與喜悅！', `organizer`='苗栗縣苗栗市公所', `address`='苗栗縣苗栗市', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='苗栗市（苗栗縣）=', `latitude`=24.56382141, `longitude`=120.8112299, `ticket_price`='無資料', `source_url`='https://www.facebook.com/mlcg01', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6779a52626b32458d4363483', '日本飛行船劇團《小飛俠彼得潘》', '日本飛行船劇團【小飛俠彼得潘】瘋狂魅力再度襲捲臺灣 \r\n獻給全世界的小朋友以及曾經是小朋友的人\r\n如果到夢幻島上可以永遠只當個孩子，你會選擇留在那裡嗎？\r\n所有的孩子都知道一個叫做「夢幻島」的地方（Neverland），大家可以在睡夢中到那兒玩耍。島上有一個叫做彼得潘的男孩，他不但會飛，而且永遠不會長大。他是孩子們心目中的英雄，也是夢幻島上迷途的孩子們最可靠的首領。為了找尋新的故事，他和小精靈來到另一個世界，卻不小心被溫蒂及她的兩個弟弟發現……。\r\n劇中有愛吃醋的小精靈、勇敢的泰雅莉莉公主，還有凶惡的虎克船長以及他的海盜們！將友誼與信念集結成一部有趣又驚奇的冒險故事。\r\n由蘇格蘭作家詹姆斯.馬修.貝瑞（James Matthew Barrie1860-1937）創作的經典童話彼得潘（Peter Pan），最初是發表於1904年。\r\n彼得潘的美麗新世界是由「勇敢、堅真、不畏惡勢力」的信念組成，期盼藉由演出喚醒沉睡在心靈深處的那一份真，亦希望將這份信念散播到世界的每一個角落，讓我們的孩子能永遠保有它。\r\n\r\n飛行船劇團\r\n成立於1966年的飛行船屬人偶劇團，擁有180餘名團員，所有演員皆具有芭蕾與體操素養，已在世界二十幾個國家公演過。其表演特色是以精緻的面具、服裝、道具及布景呈現絢麗的視覺效果，並運用融合電影和舞台劇的夢幻空間，以載歌載舞的表演型式呈現童話中的真、善、美。', '童歡藝術有限公司', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-03-28 00:00:00', '2025-03-28 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '票價+400;票價+600;票價+800;票價+1000;票價+1200;票價+1500', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='日本飛行船劇團《小飛俠彼得潘》', `description`='日本飛行船劇團【小飛俠彼得潘】瘋狂魅力再度襲捲臺灣 \r\n獻給全世界的小朋友以及曾經是小朋友的人\r\n如果到夢幻島上可以永遠只當個孩子，你會選擇留在那裡嗎？\r\n所有的孩子都知道一個叫做「夢幻島」的地方（Neverland），大家可以在睡夢中到那兒玩耍。島上有一個叫做彼得潘的男孩，他不但會飛，而且永遠不會長大。他是孩子們心目中的英雄，也是夢幻島上迷途的孩子們最可靠的首領。為了找尋新的故事，他和小精靈來到另一個世界，卻不小心被溫蒂及她的兩個弟弟發現……。\r\n劇中有愛吃醋的小精靈、勇敢的泰雅莉莉公主，還有凶惡的虎克船長以及他的海盜們！將友誼與信念集結成一部有趣又驚奇的冒險故事。\r\n由蘇格蘭作家詹姆斯.馬修.貝瑞（James Matthew Barrie1860-1937）創作的經典童話彼得潘（Peter Pan），最初是發表於1904年。\r\n彼得潘的美麗新世界是由「勇敢、堅真、不畏惡勢力」的信念組成，期盼藉由演出喚醒沉睡在心靈深處的那一份真，亦希望將這份信念散播到世界的每一個角落，讓我們的孩子能永遠保有它。\r\n\r\n飛行船劇團\r\n成立於1966年的飛行船屬人偶劇團，擁有180餘名團員，所有演員皆具有芭蕾與體操素養，已在世界二十幾個國家公演過。其表演特色是以精緻的面具、服裝、道具及布景呈現絢麗的視覺效果，並運用融合電影和舞台劇的夢幻空間，以載歌載舞的表演型式呈現童話中的真、善、美。', `organizer`='童歡藝術有限公司', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='票價+400;票價+600;票價+800;票價+1000;票價+1200;票價+1500', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
