INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6779a52726b32458d43634a7', '「藝韻臻美」苗栗縣文化產業藝術協會陶藝創作聯展', '本展由苗栗縣文化產業藝術協會李茂宗創會理事長、周美純理事長偕同會員共25位陶藝家聯合展出，為2025新的一年，開創嶄新的藝術饗宴。\r\n作品呈現個性化的創作力和陶瓷多樣的可塑性及豐富的釉彩變化，帶來作品風格新風貌。由於陶藝家共同參與彼此交流，流露出陶藝的多元性，追求藝術創作真、善美。更透過藝術創作，營造陶瓷藝術樸實不失精緻的特殊自然美感，期許探索陶藝大千世界未來的無限空間。', '五穀文化村', '苗栗縣公館鄉', '2025-01-04 00:00:00', '2025-03-30 00:00:00', '公館鄉（苗栗縣）=', 24.50249686, 120.8505904, '無資料', 'https://www.facebook.com/wuguu/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「藝韻臻美」苗栗縣文化產業藝術協會陶藝創作聯展', `description`='本展由苗栗縣文化產業藝術協會李茂宗創會理事長、周美純理事長偕同會員共25位陶藝家聯合展出，為2025新的一年，開創嶄新的藝術饗宴。\r\n作品呈現個性化的創作力和陶瓷多樣的可塑性及豐富的釉彩變化，帶來作品風格新風貌。由於陶藝家共同參與彼此交流，流露出陶藝的多元性，追求藝術創作真、善美。更透過藝術創作，營造陶瓷藝術樸實不失精緻的特殊自然美感，期許探索陶藝大千世界未來的無限空間。', `organizer`='五穀文化村', `address`='苗栗縣公館鄉', `start_date`='2025-01-04 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='公館鄉（苗栗縣）=', `latitude`=24.50249686, `longitude`=120.8505904, `ticket_price`='無資料', `source_url`='https://www.facebook.com/wuguu/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677a3f7e07f391d7b797cd9e', '曉劇場《毛皮瑪麗》', '「歷史都是騙人的，過去都是假的，只有明天會出現的鬼魂才是真實的！」\r\n\r\n男扮女裝的瑪利依循自己的喜好與規則養育仇人之子，美少年欣也作為對戲的人，配合瑪利的教養，是屈從還是為贏得「母親」 的喜愛與歡心。\r\n\r\n耽美頹敗的華麗意象裡， 穿著毛皮的瑪利一次又一次以自身叩問，這個世界的絕對標準究竟為何？\r\n\r\n關於寺山修司\r\n日本戲劇鬼才，被譽為「語言的煉金術師」，是一位劇作家、詩人、歌人、作家、電影導演及賽馬評論家。他在各領域皆有卓越表現，並與唐十郎、鈴木忠志、佐藤信並列為「前衛戲劇四大天王」。寺山的作品充滿虛實交錯的異想和悖德情節，探討社會問題，風格色彩飽滿且犀利。雖於1983年去世，但寺山修司的藝術遺產依然影響當代創作者，成為現代日本文化的重要組成部分。\r\n\r\n關於曉劇場\r\n曉劇場成立於2006年，現駐地萬華糖廍文化園區營運「萬座曉劇場」。創作涵括如《燕子》、《她獲得約翰的吻並成為胡立德的女人——一個妓女的房間》、《穢土天堂三部曲》、《焦土》等「社會議題」面向作品：改編張曼娟、黃春明、三島由紀夫、宮部美幸等文學大家的文學改編系列；及《夏日微涼夜話》鬼故事系列作品。同時以萬華在地為基地，每年春天主辦艋舺國際舞蹈節、藝術進駐計劃，並開設藝文推廣課程。曉劇場曾巡演上海國際當代戲劇節、曼谷國際劇場藝術節、臺北藝術節、亞洲表演藝術節、東京藝術節、韓國東亞人民劇場藝術節、愛丁堡藝穗節、立陶宛克萊佩達國家劇院及德國柏林文化中心演出。', '曉劇場', '臺北市萬華區大理街132-9號', '2025-03-21 00:00:00', '2025-03-21 00:00:00', '萬座曉劇場', 25.0285899, 121.4979858, 'NT$1000、1200\r\n早鳥7折優惠至2025/2/3 23:59', 'https://www.opentix.life/event/1867895534052487169?srsltid=AfmBOoonJgXTn_LqZhLRSN9M14w1-lgWb-3f_HMJJSjiLY4PUGB0K1AD', '[]') ON DUPLICATE KEY UPDATE `activity_name`='曉劇場《毛皮瑪麗》', `description`='「歷史都是騙人的，過去都是假的，只有明天會出現的鬼魂才是真實的！」\r\n\r\n男扮女裝的瑪利依循自己的喜好與規則養育仇人之子，美少年欣也作為對戲的人，配合瑪利的教養，是屈從還是為贏得「母親」 的喜愛與歡心。\r\n\r\n耽美頹敗的華麗意象裡， 穿著毛皮的瑪利一次又一次以自身叩問，這個世界的絕對標準究竟為何？\r\n\r\n關於寺山修司\r\n日本戲劇鬼才，被譽為「語言的煉金術師」，是一位劇作家、詩人、歌人、作家、電影導演及賽馬評論家。他在各領域皆有卓越表現，並與唐十郎、鈴木忠志、佐藤信並列為「前衛戲劇四大天王」。寺山的作品充滿虛實交錯的異想和悖德情節，探討社會問題，風格色彩飽滿且犀利。雖於1983年去世，但寺山修司的藝術遺產依然影響當代創作者，成為現代日本文化的重要組成部分。\r\n\r\n關於曉劇場\r\n曉劇場成立於2006年，現駐地萬華糖廍文化園區營運「萬座曉劇場」。創作涵括如《燕子》、《她獲得約翰的吻並成為胡立德的女人——一個妓女的房間》、《穢土天堂三部曲》、《焦土》等「社會議題」面向作品：改編張曼娟、黃春明、三島由紀夫、宮部美幸等文學大家的文學改編系列；及《夏日微涼夜話》鬼故事系列作品。同時以萬華在地為基地，每年春天主辦艋舺國際舞蹈節、藝術進駐計劃，並開設藝文推廣課程。曉劇場曾巡演上海國際當代戲劇節、曼谷國際劇場藝術節、臺北藝術節、亞洲表演藝術節、東京藝術節、韓國東亞人民劇場藝術節、愛丁堡藝穗節、立陶宛克萊佩達國家劇院及德國柏林文化中心演出。', `organizer`='曉劇場', `address`='臺北市萬華區大理街132-9號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='萬座曉劇場', `latitude`=25.0285899, `longitude`=121.4979858, `ticket_price`='NT$1000、1200\r\n早鳥7折優惠至2025/2/3 23:59', `source_url`='https://www.opentix.life/event/1867895534052487169?srsltid=AfmBOoonJgXTn_LqZhLRSN9M14w1-lgWb-3f_HMJJSjiLY4PUGB0K1AD', `image_url`='[]';
