INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677b6a9e8f1582914526adef', '杜沁澐小提琴獨奏會', '旅居法國多年的小提琴家杜沁澐與旅德鋼琴家余涵雯將帶來一套豐富多元的法國曲目，法蘭克A大調小提琴與鋼琴奏鳴曲，樂曲旋律動人、和聲結構巧妙。蕭頌《詩曲》靈感來自法國文學家薩瑪納詩集中的「幻影」，為蕭頌的經典作品。米堯《屋頂上的牛》展現其輕快、幽默的風格，同時也受到了巴西音樂的影響。整場曲目展現另類的法國音樂獨特的音樂魅力。', '就是愛樂管弦樂團', '臺北市中正區中山南路21-1號', '2025-02-27 00:00:00', '2025-02-27 00:00:00', '國家兩廳院演奏廳', 25.03240487, 121.5198839, '票價： 800 、1,000', 'https://www.opentix.life/event/1864571750204444673', '[]') ON DUPLICATE KEY UPDATE `activity_name`='杜沁澐小提琴獨奏會', `description`='旅居法國多年的小提琴家杜沁澐與旅德鋼琴家余涵雯將帶來一套豐富多元的法國曲目，法蘭克A大調小提琴與鋼琴奏鳴曲，樂曲旋律動人、和聲結構巧妙。蕭頌《詩曲》靈感來自法國文學家薩瑪納詩集中的「幻影」，為蕭頌的經典作品。米堯《屋頂上的牛》展現其輕快、幽默的風格，同時也受到了巴西音樂的影響。整場曲目展現另類的法國音樂獨特的音樂魅力。', `organizer`='就是愛樂管弦樂團', `address`='臺北市中正區中山南路21-1號', `start_date`='2025-02-27 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='國家兩廳院演奏廳', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='票價： 800 、1,000', `source_url`='https://www.opentix.life/event/1864571750204444673', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677c0b258f1579d1ccee33bc', '我吻。故我在 Attilio Chien 簡明正 個展', 'Attilio Chien 簡明正 個展\r\n\r\n主辦單位：彰濱秀傳紀念醫院 人文藝術館\r\n協辦單位：Attilio Arts\r\n展覽日期：2025年2月5日至3月9日 (免費入場)\r\n展覽時間：週一至週日08:30~17:30 彰化鹿港鎮工路6號\r\n聯絡電話：04-7813888 轉71135(人文藝術館）\r\n歡迎中部朋友參觀，歡迎學校團體預約看展。\r\n\r\n「我吻。故我在」I Kiss Therefore I am\r\n這是由數學家笛卡爾提出的「我思故我在」的經典哲學精神的延伸，以藝術觀點來探索與展現吻的各種面向和意義。當我吻時我必定存在。如果我停止了吻，就不會有我存在的證據。與思想不同，吻是一種最直接、最真摯用來表達愛的方式之一。每一次相吻，都是一種身體與心靈的交融，因為吻表明了愛的存在、也證明了你我彼此的存在。莎士比亞曾說：「吻，是愛情的印記」，而吻作為生活中的一部分，就是如此承載著豐富的情感和生命的能量。\r\n\r\n藝術家簡明正『Attilio Chien』透過藝術詮釋吻的多元性，探索與感受人與人之間的關係，從而引發情感共鳴。藉以創造『吻』的藝術文化，傳達著正面的能量。讓人們在欣賞過程中感受到美好與喜悅，亦同時拉近了人與人之間的距離，使彼此更加親近。這次規劃約五十件從 2015 - 2024 所創作的作品，作品中每個吻都有溫暖的故事，從人物眼睛裡的反射，到來自情感面的細節，觸動著你我。透過作品的互動，更使敏感的神經和孤獨的情緒無形中帶出一種『吻 暖』，讓整個空間充滿了溫度和情感。部分作品融合科技與燈光互動，現場並準備道具供參觀者拍照使用，還有裝置藝術，“懂得愛人的人，懂得生活。歡迎中部朋友、學校團體預約看展，一起用愛與溫暖來彼此相遇～讓愛繼續“吻”下去！', '彰濱秀傳紀念醫院人文藝術館', '彰化縣台灣彰化縣鹿港鎮鹿工路6號', '2025-02-05 00:00:00', '2025-03-09 00:00:00', '彰濱秀傳紀念醫院人文藝術館', 0, 0, '無資料', 'https://www.attilioarts.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='我吻。故我在 Attilio Chien 簡明正 個展', `description`='Attilio Chien 簡明正 個展\r\n\r\n主辦單位：彰濱秀傳紀念醫院 人文藝術館\r\n協辦單位：Attilio Arts\r\n展覽日期：2025年2月5日至3月9日 (免費入場)\r\n展覽時間：週一至週日08:30~17:30 彰化鹿港鎮工路6號\r\n聯絡電話：04-7813888 轉71135(人文藝術館）\r\n歡迎中部朋友參觀，歡迎學校團體預約看展。\r\n\r\n「我吻。故我在」I Kiss Therefore I am\r\n這是由數學家笛卡爾提出的「我思故我在」的經典哲學精神的延伸，以藝術觀點來探索與展現吻的各種面向和意義。當我吻時我必定存在。如果我停止了吻，就不會有我存在的證據。與思想不同，吻是一種最直接、最真摯用來表達愛的方式之一。每一次相吻，都是一種身體與心靈的交融，因為吻表明了愛的存在、也證明了你我彼此的存在。莎士比亞曾說：「吻，是愛情的印記」，而吻作為生活中的一部分，就是如此承載著豐富的情感和生命的能量。\r\n\r\n藝術家簡明正『Attilio Chien』透過藝術詮釋吻的多元性，探索與感受人與人之間的關係，從而引發情感共鳴。藉以創造『吻』的藝術文化，傳達著正面的能量。讓人們在欣賞過程中感受到美好與喜悅，亦同時拉近了人與人之間的距離，使彼此更加親近。這次規劃約五十件從 2015 - 2024 所創作的作品，作品中每個吻都有溫暖的故事，從人物眼睛裡的反射，到來自情感面的細節，觸動著你我。透過作品的互動，更使敏感的神經和孤獨的情緒無形中帶出一種『吻 暖』，讓整個空間充滿了溫度和情感。部分作品融合科技與燈光互動，現場並準備道具供參觀者拍照使用，還有裝置藝術，“懂得愛人的人，懂得生活。歡迎中部朋友、學