INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677c47cf26b32458d43634c0', '雙殊生的南北對話～廖靖凱及吳承翰得獎作品聯展', '南北對話～廖靖凱及吳承翰得獎作品聯展》！\r\n本次展覽活動以靖凱愛「玩顏色」，以水彩畫的方式用鮮亮的對比色讓整張畫的靈魂跳出來，充滿生命力的創作及承翰極富創意且充滿故事性的構圖，用圖畫代替語言，說出了內心對動物世界的水彩畫聯想創作，歡迎有興趣的小朋友、家長及民眾前往參觀，一起沉浸在圖畫的異想世界。', '臺中市西屯區戶政事務所', '臺中市西屯區', '2025-01-01 00:00:00', '2025-03-31 00:00:00', '西屯區（臺中市）=', 24.18308895, 120.6270131, '無資料', 'https://www.hxitun.taichung.gov.tw/1595260/1595273/1595275/3577186/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='雙殊生的南北對話～廖靖凱及吳承翰得獎作品聯展', `description`='南北對話～廖靖凱及吳承翰得獎作品聯展》！\r\n本次展覽活動以靖凱愛「玩顏色」，以水彩畫的方式用鮮亮的對比色讓整張畫的靈魂跳出來，充滿生命力的創作及承翰極富創意且充滿故事性的構圖，用圖畫代替語言，說出了內心對動物世界的水彩畫聯想創作，歡迎有興趣的小朋友、家長及民眾前往參觀，一起沉浸在圖畫的異想世界。', `organizer`='臺中市西屯區戶政事務所', `address`='臺中市西屯區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='西屯區（臺中市）=', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://www.hxitun.taichung.gov.tw/1595260/1595273/1595275/3577186/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677c47cf26b32458d43634c1', '潭雅神社區大學-墨樸書法社作品成果展', '潭雅神社區大學-墨樸書法社成立於民國l07年，由許多對傳統文化志同道合的人員所組成，以培養社員與各界書道文化交流，提昇社會祥和之氣為目標，鼓勵社員參與公眾事務之能力和各界書道文化交流。', '臺中市大雅區戶政事務所', '臺中市大雅區', '2025-01-02 00:00:00', '2025-03-31 00:00:00', '大雅區（臺中市）=', 24.22704181, 120.6411818, '無資料', 'https://www.hdaya.taichung.gov.tw/1516796/1516837/1516842/3576239/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='潭雅神社區大學-墨樸書法社作品成果展', `description`='潭雅神社區大學-墨樸書法社成立於民國l07年，由許多對傳統文化志同道合的人員所組成，以培養社員與各界書道文化交流，提昇社會祥和之氣為目標，鼓勵社員參與公眾事務之能力和各界書道文化交流。', `organizer`='臺中市大雅區戶政事務所', `address`='臺中市大雅區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='大雅區（臺中市）=', `latitude`=24.22704181, `longitude`=120.6411818, `ticket_price`='無資料', `source_url`='https://www.hdaya.taichung.gov.tw/1516796/1516837/1516842/3576239/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677c47d026b32458d43634c9', '臺中市中堅攝影學會聯合佈展', '臺中市中堅攝影學會創立於民國65年，為臺中市立案的社團法人，每年均舉辦多次攝影展覽活動及比賽，展出內容涵蓋了人文、風景、生態及心象攝影等多項題材，是會員這一年來參加會內及全國各項攝影大賽得獎作品的展出，對於創作與攝影技巧均有特別突出表現。', '中堅攝影學會', '臺中市新社區興社街二段28之1號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '臺中市新社區公所', 24.17769289, 120.8313228, '無資料', 'https://www.facebook.com/share/p/19ajjfAHzN/?mibextid=WC7FNe', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市中堅攝影學會聯合佈展', `description`='臺中市中堅攝影學會創立於民國65年，為臺中市立案的社團法人，每年均舉辦多次攝影展覽活動及比賽，展出內容涵蓋了人文、風景、生態及心象攝影等多項題材，是會員這一年來參加會內及全國各項攝影大賽得獎作品的展出，對於創作與攝影技巧均有特別突出表現。', `organizer`='中堅攝影學會', `address`='臺中市新社區興社街二段28之1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市新社區公所', `latitude`=24.17769289, `longitude`=120.8313228, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/19ajjfAHzN/?mibextid=WC7FNe', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677c47d126b32458d43634ce', '黑手仔堀/王語濃 影像敘事創作個展', '黑手仔堀 王語濃影像敘事創作展\r\n臺中東區的「黑手仔堀」，從日治時期就開始發展許多加工產業，黑手師傅們用雙手在此堅持打拼以及生活，但隨著時代變遷，他們的故事也面臨著挑戰。\r\n這次展覽，透過從小在東區長大的策展人#王語濃 的影像與文字紀錄，帶你認識從事打鐵仔工作一甲子的高其畑師傅\r\n\r\n――展覽資訊――\r\n日期| 𝟭𝟭𝟰⸝𝟬𝟭⸝𝟬𝟰 ㊅~𝟭𝟭𝟰⸝𝟬𝟮⸝𝟮𝟱 ㊁\r\n地點| 李科永紀念圖書分館(臺中市南屯區龍富路五段1號)', '無資料', '臺中市南屯區龍富路五段1號', '2025-01-04 00:00:00', '2025-02-25 00:00:00', '臺中市立圖書館李科永紀念圖書分館', 24.14165524, 120.6177379, '無資料', 'https://pse.is/6wz6eu', '[]') ON DUPLICATE KEY UPDATE `activity_name`='黑手仔堀/王語濃 影像敘事創作個展', `description`='黑手仔堀 王語濃影像敘事創作展\r\n臺中東區的「黑手仔堀」，從日治時期就開始發展許多加工產業，黑手師傅們用雙手在此堅持打拼以及生活，但隨著時代變遷，他們的故事也面臨著挑戰。\r\n這次展覽，透過從小在東區長大的策展人#王語濃 的影像與文字紀錄，帶你認識從事打鐵仔工作一甲子的高其畑師傅\r\n\r\n――展覽資訊――\r\n日期| 𝟭𝟭𝟰⸝𝟬𝟭⸝𝟬𝟰 ㊅~𝟭𝟭𝟰⸝𝟬𝟮⸝𝟮𝟱 ㊁\r\n地點| 李科永紀念圖書分館(臺中市南屯區龍富路五段1號)', `organizer`='無資料', `address`='臺中市南屯區龍富路五段1號', `start_date`='2025-01-04 00:00:00', `end_date`='2025-02-25 00:00:00', `location`='臺中市立圖書館李科永紀念圖書分館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://pse.is/6wz6eu', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677c47d226b32458d43634d7', '無資料', '本展「翰墨無邊—國際書法名家邀請展」，於2024年11月17日起至2025年2月24日隆重展出。本次集結來自中國、日本、韓國、臺灣，以及馬來西亞、新加坡、印尼、越南、阿根廷9地的書法名家，共展出59組件書法作品，呈現當代書法藝術的多元面貌與發展脈絡。\r\n書法作為文字藝術的獨特表現形式，歷經千年演變，與書寫者的情感心象緊密結合，發展出豐富的藝術內涵。展覽不僅匯聚了各國書法的傳統精髓，更呈現了各地現代書法創作的多樣風貌。從傳統筆法到創意表現，觀眾將能一覽漢字文化圈當前的發展走向，領略書法文化如何在不斷變遷的時代脈動中，賦予藝術新的生命力。\r\n本次展覽以「翰墨無邊」為主題，寓意書法藝術無窮無盡的發展可能性。透過書法這一載體，臺灣有幸在全球書法藝術領域中佔據一席之地，傳承並發揚漢字書法的精髓。本展希望能夠喚起更多對書法藝術的關注與熱愛，並藉此啟發觀眾思考書法文化的經典傳承之路與更多的可能。', '桃園市立美術館', '桃園市大園區28鄰大仁路100號', '橫山書法藝術館', 25.06384709, 121.21177, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='本展「翰墨無邊—國際書法名家邀請展」，於2024年11月17日起至2025年2月24日隆重展出。本次集結來自中國、日本、韓國、臺灣，以及馬來西亞、新加坡、印尼、越南、阿根廷9地的書法名家，共展出59組件書法作品，呈現當代書法藝術的多元面貌與發展脈絡。\r\n書法作為文字藝術的獨特表現形式，歷經千年演變，與書寫者的情感心象緊密結合，發展出豐富的藝術內涵。展覽不僅匯聚了各國書法的傳統精髓，更呈現了各地現代書法創作的多樣風貌。從傳統筆法到創意表現，觀眾將能一覽漢字文化圈當前的發展走向，領略書法文化如何在不斷變遷的時代脈動中，賦予藝術新的生命力。\r\n本次展覽以「翰墨無邊」為主題，寓意書法藝術無窮無盡的發展可能性。透過書法這一載體，臺灣有幸在全球書法藝術領域中佔據一席之地，傳承並發揚漢字書法的精髓。本展希望能夠喚起更多對書法藝術的關注與熱愛，並藉此啟發觀眾思考書法文化的經典傳承之路與更多的可能。', `organizer`='桃園市立美術館', `address`='桃園市大園區28鄰大仁路100號', `location`='橫山書法藝術館', `latitude`=25.06384709, `longitude`=121.21177, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677c47d526b32458d43634ea', '曾經的本島第一所：大廟口派出所常設展', '展覽透過有趣的展呈形式讓觀展者留下新鮮印象，以復古播盤式電話作為體驗亮點，邀請曾經與派出所有關係的人們進行訪談，讓觀展者感受到文史學家如何透過彼此看似無關的資料，發現其中的關聯性，建立繁華老城區與派出所的想像與連結，期待藉此重現桃園城歷史的畫面感、故事性與魅力。', '桃園市政府文化局', '桃園市桃園區中正路198號', '2025-01-02 00:00:00', '2025-12-31 00:00:00', '大廟口派出所-舊城再生基地辦公室', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='曾經的本島第一所：大廟口派出所常設展', `description`='展覽透過有趣的展呈形式讓觀展者留下新鮮印象，以復古播盤式電話作為體驗亮點，邀請曾經與派出所有關係的人們進行訪談，讓觀展者感受到文史學家如何透過彼此看似無關的資料，發現其中的關聯性，建立繁華老城區與派出所的想像與連結，期待藉此重現桃園城歷史的畫面感、故事性與魅力。', `organizer`='桃園市政府文化局', `address`='桃園市桃園區中正路198號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='大廟口派出所-舊城再生基地辦公室', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
