INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677d96a226b32458d436350a', '2025眷村春節特展', '眷村人每年除夕夜的團圓飯都會有準備十道菜的習俗，象徵著來年生活十全十美。『2025眷村春節特展』也準備十道菜色讓民眾用眼睛吃美食，每一道也都富有吉祥寓意，「糖醋魚」象徵年年有餘，「梅干扣肉」隱含慶豐年，「麻辣水煮牛」代表著紅紅火火，「蓮藕木耳」隱喻絲絲相連，「蜜汁鴨肉」代表甜甜蜜蜜，「東坡肉」期望可以四四方方吃四方，「包子」呈現出過年一家團團圓圓，「炒手」為招財進寶，「清蒸蝦」希望來年一路長紅，「什錦湯」意味萬事吉祥。眷村經歷了數十載物換星移幾度秋，不變的是堅持除夕夜一定要吃團圓飯的傳統風俗。\r\n\r\n眷村是台灣特有的社區型態，因戰亂遷徙來台的軍人及其眷屬，安身於竹籬笆搭建的屋舍內，家戶相鄰、雞犬相聞。在闔家團聚的春節，來自大江南北的人們辦置年貨，烹煮特色年菜，小孩子們肆無忌憚的玩鬧，來自大江南北的不同飲食、不同的方言、不同的習俗，過不同地區的新年，吃著不同的味道，有著多元文化地方，這就是眷村新年。\r\n\r\n「2025眷村春節特展」以眷村的新年裡生活為主題，充滿歲月痕跡的家具擺設彷彿還留著家人的身影，嶄新的窗花宣告新年新生活的來臨，而一桌豐盛的菜餚，則是對自己一年辛勞的犒賞，以及對家鄉的想念。歡迎民眾一同走入時光隧道，體驗眷村年節文化。', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-01-01 00:00:00', '2025-03-09 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=fd7d5dc4f558486e9e0ca284aae749c2', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025眷村春節特展', `description`='眷村人每年除夕夜的團圓飯都會有準備十道菜的習俗，象徵著來年生活十全十美。『2025眷村春節特展』也準備十道菜色讓民眾用眼睛吃美食，每一道也都富有吉祥寓意，「糖醋魚」象徵年年有餘，「梅干扣肉」隱含慶豐年，「麻辣水煮牛」代表著紅紅火火，「蓮藕木耳」隱喻絲絲相連，「蜜汁鴨肉」代表甜甜蜜蜜，「東坡肉」期望可以四四方方吃四方，「包子」呈現出過年一家團團圓圓，「炒手」為招財進寶，「清蒸蝦」希望來年一路長紅，「什錦湯」意味萬事吉祥。眷村經歷了數十載物換星移幾度秋，不變的是堅持除夕夜一定要吃團圓飯的傳統風俗。\r\n\r\n眷村是台灣特有的社區型態，因戰亂遷徙來台的軍人及其眷屬，安身於竹籬笆搭建的屋舍內，家戶相鄰、雞犬相聞。在闔家團聚的春節，來自大江南北的人們辦置年貨，烹煮特色年菜，小孩子們肆無忌憚的玩鬧，來自大江南北的不同飲食、不同的方言、不同的習俗，過不同地區的新年，吃著不同的味道，有著多元文化地方，這就是眷村新年。\r\n\r\n「2025眷村春節特展」以眷村的新年裡生活為主題，充滿歲月痕跡的家具擺設彷彿還留著家人的身影，嶄新的窗花宣告新年新生活的來臨，而一桌豐盛的菜餚，則是對自己一年辛勞的犒賞，以及對家鄉的想念。歡迎民眾一同走入時光隧道，體驗眷村年節文化。', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=fd7d5dc4f558486e9e0ca284aae749c2', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677d96b126b32458d436350b', '竹梅源文藝獎 第10屆全國油畫創作比賽得獎作品展', '竹梅源文藝獎全國油畫比賽，已經邁入第十年，為鼓勵愛好藝術者致力於美術創作，第十屆比賽畫作題目，仍以藝術創作為主，尺寸限定50號，期為藝術增添新的文化與生命力；共有來自全省各地計210件畫作熱烈參與，42件得獎作品， 2月22日星期六下午3點30分舉行頒獎典禮。歡迎蒞臨共襄盛舉。\r\n', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-02-21 00:00:00', '2025-03-04 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='竹梅源文藝獎 第10屆全國油畫創作比賽得獎作品展', `description`='竹梅源文藝獎全國油畫比賽，已經邁入第十年，為鼓勵愛好藝術者致力於美術創作，第十屆比賽畫作題目，仍以藝術創作為主，尺寸限定50號，期為藝術增添新的文化與生命力；共有來自全省各地計210件畫作熱烈參與，42件得獎作品， 2月22日星期六下午3點30分舉行頒獎典禮。歡迎蒞臨共襄盛舉。\r\n', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-02-21 00:00:00', `end_date`='2025-03-04 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
