INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677d96b526b32458d436350d', '眷村主題展：眷村說明書–清水眷村‧源生緣遠', '清水眷村文化園區，乘載著悠長的歷史，紀錄多少家庭的悲歡離合。讓我們來為您訴說這一段，大時代裡的小故事......\r\n\r\n展覽以清水眷村相關老照片、舊物件、故事記憶、影像等為主要載體，內容包含「清水眷村的回憶故事」、「降落傘廠的小故事」、「第三供應處在做什麼」、「紙本上的味蕾記憶」、「影像中的時光」，並增加AR設計與民眾互動，試圖建構延續清水眷村過往的記憶，並與眷村當下增添更多連結與能量。\r\n\r\n———— 展覽資訊 ————\r\n\r\n展覽時間｜114年1月1日(三) 至 114年4月30日(三)\r\n\r\n展覽地點｜清水眷村文化園區 西5號\r\n\r\n展覽媒材｜老照片、舊物、影像、AR、複合媒材', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-01-01 00:00:00', '2025-04-30 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Activity/Activity_More?id=bcf0a60ad9974c36b782d0570c643f49', '[]') ON DUPLICATE KEY UPDATE `activity_name`='眷村主題展：眷村說明書–清水眷村‧源生緣遠', `description`='清水眷村文化園區，乘載著悠長的歷史，紀錄多少家庭的悲歡離合。讓我們來為您訴說這一段，大時代裡的小故事......\r\n\r\n展覽以清水眷村相關老照片、舊物件、故事記憶、影像等為主要載體，內容包含「清水眷村的回憶故事」、「降落傘廠的小故事」、「第三供應處在做什麼」、「紙本上的味蕾記憶」、「影像中的時光」，並增加AR設計與民眾互動，試圖建構延續清水眷村過往的記憶，並與眷村當下增添更多連結與能量。\r\n\r\n———— 展覽資訊 ————\r\n\r\n展覽時間｜114年1月1日(三) 至 114年4月30日(三)\r\n\r\n展覽地點｜清水眷村文化園區 西5號\r\n\r\n展覽媒材｜老照片、舊物、影像、AR、複合媒材', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Activity/Activity_More?id=bcf0a60ad9974c36b782d0570c643f49', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677d96b526b32458d436350f', '無資料', '2025/2/22(六)『SOUNDSTATUES TAIWAN TOUR』\r\n\r\nSoundstatues即將重返台灣巡演！\r\n\r\n我們將演出您最喜歡的歌曲，\r\n以及以前從未在巡迴演出中發表過的新歌曲。', '迴響音樂藝文展演空間', '臺中市中區中山路108號', '迴響音樂藝文展演空間', 24.14168566, 120.680598, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='2025/2/22(六)『SOUNDSTATUES TAIWAN TOUR』\r\n\r\nSoundstatues即將重返台灣巡演！\r\n\r\n我們將演出您最喜歡的歌曲，\r\n以及以前從未在巡迴演出中發表過的新歌曲。', `organizer`='迴響音樂藝文展演空間', `address`='臺中市中區中山路108號', `location`='迴響音樂藝文展演空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677d96b526b32458d4363510', '無資料', '展出者在最青澀的時期拿下了第一座百號油畫優選，這對當時正處於人生低谷的他彷彿照進了一絲希望。當時沒碰過油畫但在內心想要闖闖看，於是買了畫布靠著多年的繪畫經驗，完成了人生第一張百號油畫，很幸運的進入了油畫的殿堂。\r\n\r\n「幽枯寂木」的創作史，啟發於尼采的一段話：「其實人跟樹是一樣的，越是嚮往高處的陽光，它的根就越要伸向黑暗的地底」我們往往要經歷過最痛苦的失敗，才會知道有多難多艱辛，藝術的道路是一個極度孤獨以及未知的路，但我們還是要去面對去突破，才能重新茁壯蛻變，根扎得越深廣，吸吮的養分才越豐富，也才能長成參天大樹，成為我們最想成為的樣子。這裡的每一幅畫刻畫著至「午夜夢迴」後對於生命每個階段的描繪。', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='展出者在最青澀的時期拿下了第一座百號油畫優選，這對當時正處於人生低谷的他彷彿照進了一絲希望。當時沒碰過油畫但在內心想要闖闖看，於是買了畫布靠著多年的繪畫經驗，完成了人生第一張百號油畫，很幸運的進入了油畫的殿堂。\r\n\r\n「幽枯寂木」的創作史，啟發於尼采的一段話：「其實人跟樹是一樣的，越是嚮往高處的陽光，它的根就越要伸向黑暗的地底」我們往往要經歷過最痛苦的失敗，才會知道有多難多艱辛，藝術的道路是一個極度孤獨以及未知的路，但我們還是要去面對去突破，才能重新茁壯蛻變，根扎得越深廣，吸吮的養分才越豐富，也才能長成參天大樹，成為我們最想成為的樣子。這裡的每一幅畫刻畫著至「午夜夢迴」後對於生命每個階段的描繪。', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677d96b626b32458d4363511', '李俞老師畫展', '藝術療癒人心，人生低谷時，除了學習油畫，也認識了禪繞畫，從中收穫快樂，難以用言語形容，祝福來看展的您，一切都往好的方向走，並且幸福美滿~', '臺中市中區戶政事務所', '臺中市中區', '2025-01-02 00:00:00', '2025-04-30 00:00:00', '中區（臺中市）=', 24.14168566, 120.680598, '無資料', 'https://www.facebook.com/share/p/1B7wLnJ71P/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='李俞老師畫展', `description`='藝術療癒人心，人生低谷時，除了學習油畫，也認識了禪繞畫，從中收穫快樂，難以用言語形容，祝福來看展的您，一切都往好的方向走，並且幸福美滿~', `organizer`='臺中市中區戶政事務所', `address`='臺中市中區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='中區（臺中市）=', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1B7wLnJ71P/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677d96b626b32458d4363512', '我們的卉畫時光-藝術展', '我們的卉畫時光\r\n屬於自己的療癒時刻\r\n靜下來，全心投入於其中，是多麼美好的事!\r\n從0開始，從空白畫布上找到屬於自己的幸福時刻!\r\n展出多幅壓克力、油畫、水墨..等作品，歡迎前往觀賞~', '臺中市立圖書館大甲分館', '臺中市大甲區雁門路172號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '臺中市立圖書館大甲分館', 24.37827161, 120.6357901, '無資料', 'https://reurl.cc/WAOWv5', '[]') ON DUPLICATE KEY UPDATE `activity_name`='我們的卉畫時光-藝術展', `description`='我們的卉畫時光\r\n屬於自己的療癒時刻\r\n靜下來，全心投入於其中，是多麼美好的事!\r\n從0開始，從空白畫布上找到屬於自己的幸福時刻!\r\n展出多幅壓克力、油畫、水墨..等作品，歡迎前往觀賞~', `organizer`='臺中市立圖書館大甲分館', `address`='臺中市大甲區雁門路172號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市立圖書館大甲分館', `latitude`=24.37827161, `longitude`=120.6357901, `ticket_price`='無資料', `source_url`='https://reurl.cc/WAOWv5', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677d96b626b32458d4363517', '「家有囍事」陳庭詩作品展', '本展展示太平知名國際級藝術家陳庭詩鐵雕、水墨、壓克力畫、篆刻、書信等35件展品。因展期適逢春節，策展單位特別挑選帶有紅色元素的作品，包括鐵雕〈家有囍事〉、紅梅水墨畫作等，除了為展覽增添喜氣氛圍，也傳達陳庭詩對所有家庭和文化價值的敬意。期望每一位觀賞者在「家有囍事」中，能夠找到屬於自己的故事，體會到那份對生活、對人、對家的溫暖與喜悅。', '臺中市太平區公所', '臺中市太平區東平路464號', '2025-01-02 00:00:00', '2025-07-08 00:00:00', '太平買菸場', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/Kdrpje', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「家有囍事」陳庭詩作品展', `description`='本展展示太平知名國際級藝術家陳庭詩鐵雕、水墨、壓克力畫、篆刻、書信等35件展品。因展期適逢春節，策展單位特別挑選帶有紅色元素的作品，包括鐵雕〈家有囍事〉、紅梅水墨畫作等，除了為展覽增添喜氣氛圍，也傳達陳庭詩對所有家庭和文化價值的敬意。期望每一位觀賞者在「家有囍事」中，能夠找到屬於自己的故事，體會到那份對生活、對人、對家的溫暖與喜悅。', `organizer`='臺中市太平區公所', `address`='臺中市太平區東平路464號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-07-08 00:00:00', `location`='太平買菸場', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/Kdrpje', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677d96b626b32458d4363518', '綻藝彩、語新生~2024太平鐵工藝術節成果展', '本檔展覽展出2024太平鐵工藝術節獲獎作品，計37件。社區黑手匠師以及勤益科大、修平科大數位媒體設計系、慈明高中廣告設計科、光華高工學生發揮創意巧思，利用工廠餘料創作鐵雕，賦予廢鐵新生命。\r\n\r\n歡迎蒞臨太平買菸場，感受本區五金加工產業技藝及各校學生豐沛的藝術創作能量。', '臺中市太平區公所', '臺中市太平區東平路464號', '2025-01-02 00:00:00', '2025-03-31 00:00:00', '太平買菸場', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/yDere8', '[]') ON DUPLICATE KEY UPDATE `activity_name`='綻藝彩、語新生~2024太平鐵工藝術節成果展', `description`='本檔展覽展出2024太平鐵工藝術節獲獎作品，計37件。社區黑手匠師以及勤益科大、修平科大數位媒體設計系、慈明高中廣告設計科、光華高工學生發揮創意巧思，利用工廠餘料創作鐵雕，賦予廢鐵新生命。\r\n\r\n歡迎蒞臨太平買菸場，感受本區五金加工產業技藝及各校學生豐沛的藝術創作能量。', `organizer`='臺中市太平區公所', `address`='臺中市太平區東平路464號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='太平買菸場', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/yDere8', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677d96b726b32458d436351a', '無資料', '為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動志工，至各分館說故事，歡迎有興趣小朋友踴躍參加！【本活動免費參加，自由入場（禁止攜帶飲料、食物）】', '高雄市立圖書館總館', '高雄市左營區2鄰啟文路12號', '高雄市立圖書館左營分館', 22.6735284, 120.2843433, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動志工，至各分館說故事，歡迎有興趣小朋友踴躍參加！【本活動免費參加，自由入場（禁止攜帶飲料、食物）】', `organizer`='高雄市立圖書館總館', `address`='高雄市左營區2鄰啟文路12號', `location`='高雄市立圖書館左營分館', `latitude`=22.6735284, `longitude`=120.2843433, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
