INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677d96b826b32458d436351d', '特色館藏主題書展~海洋魚類特展', '特色館藏主題書展~海洋魚類特展\r\n本館藉由辦理之『主題書展』，使到館民眾進一步認識館藏資源。所展示的主題書籍及相關延伸作品，都能使讀者徜徉在書海中，進一步領略閱讀之美、享受閱讀樂趣，亦能提升視野。\r\n', '高雄市立圖書館總館', '高雄市旗津區中洲三路528號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '高雄市立圖書館旗津分館', 22.561674, 120.306998, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='特色館藏主題書展~海洋魚類特展', `description`='特色館藏主題書展~海洋魚類特展\r\n本館藉由辦理之『主題書展』，使到館民眾進一步認識館藏資源。所展示的主題書籍及相關延伸作品，都能使讀者徜徉在書海中，進一步領略閱讀之美、享受閱讀樂趣，亦能提升視野。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市旗津區中洲三路528號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='高雄市立圖書館旗津分館', `latitude`=22.561674, `longitude`=120.306998, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
