INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8d626b32458d4363538', '田中達也特展-大師眼中的微型組合', '人氣新作首次來台，迷你世界大開箱\r\n\r\n2025年1月，風靡全球的田中達也微型展盛大回歸、再度登陸台北！Instagram累積近400萬粉絲追蹤、海內外特展巡迴突破250萬觀賞人次的日本熱門微型藝術大師－田中達也，將在中正紀念堂展出逾160組全新創作，涵蓋近50件立體模型，以及初次亮相、不可思議的精彩內容。快來跟隨田中達也的腳步，感受微縮藝術的神奇魅力、永遠用不完的創意驚喜！\r\n\r\n全新作品！七大主題，打造眼中的微型組合\r\n\r\n以日常為靈感出發，展覽內容橫跨HOME（家）、FORM（形狀）、COLOR（顏色）、SCALE（比例）、MOTION（動態變化）、LIFE（生命力）、WORLD（世界觀），將天馬行空的想像化為現實，拼湊源源不絕的創意，分別從「生活、形態、色彩、大小差異、動作」等各種新視角看待熟悉的事物，包含巧克力變書房、搭乘美味的麵包公車通勤去、在蔚藍衣架海上盡情地衝浪、用小小釘書針建造摩天高樓，以及在光碟片上享受溜冰的舞者等；並為食物注入鮮活生命力，與開著大亨堡車的香腸相遇；更嘗試在多樣化的地球村求同存異，讓防疫口罩變身夏日迷你游泳池。其中，人氣繪本《壽司買衣服》（白泉社刊）的新角色也將驚喜出場，深入展現田中老師的工作哲學「MITATE MIND（轉換視角）」，讓平凡的生活變得與眾不同!', '寬宏藝術經紀股份有限公司', '臺北市中正區中山南路21號', '2025-01-10 00:00:00', '2025-04-06 00:00:00', '國立中正紀念堂管理處', 25.03240487, 121.5198839, '全票+480;優惠票+450;愛心票+240', 'https://kham.com.tw/application/UTK02/UTK0201_.aspx?PRODUCT_ID=P0P5FIZZ', '[]') ON DUPLICATE KEY UPDATE `activity_name`='田中達也特展-大師眼中的微型組合', `description`='人氣新作首次來台，迷你世界大開箱\r\n\r\n2025年1月，風靡全球的田中達也微型展盛大回歸、再度登陸台北！Instagram累積近400萬粉絲追蹤、海內外特展巡迴突破250萬觀賞人次的日本熱門微型藝術大師－田中達也，將在中正紀念堂展出逾160組全新創作，涵蓋近50件立體模型，以及初次亮相、不可思議的精彩內容。快來跟隨田中達也的腳步，感受微縮藝術的神奇魅力、永遠用不完的創意驚喜！\r\n\r\n全新作品！七大主題，打造眼中的微型組合\r\n\r\n以日常為靈感出發，展覽內容橫跨HOME（家）、FORM（形狀）、COLOR（顏色）、SCALE（比例）、MOTION（動態變化）、LIFE（生命力）、WORLD（世界觀），將天馬行空的想像化為現實，拼湊源源不絕的創意，分別從「生活、形態、色彩、大小差異、動作」等各種新視角看待熟悉的事物，包含巧克力變書房、搭乘美味的麵包公車通勤去、在蔚藍衣架海上盡情地衝浪、用小小釘書針建造摩天高樓，以及在光碟片上享受溜冰的舞者等；並為食物注入鮮活生命力，與開著大亨堡車的香腸相遇；更嘗試在多樣化的地球村求同存異，讓防疫口罩變身夏日迷你游泳池。其中，人氣繪本《壽司買衣服》（白泉社刊）的新角色也將驚喜出場，深入展現田中老師的工作哲學「MITATE MIND（轉換視角）」，讓平凡的生活變得與眾不同!', `organizer`='寬宏藝術經紀股份有限公司', `address`='臺北市中正區中山南路21號', `start_date`='2025-01-10 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='國立中正紀念堂管理處', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='全票+480;優惠票+450;愛心票+240', `source_url`='https://kham.com.tw/application/UTK02/UTK0201_.aspx?PRODUCT_ID=P0P5FIZZ', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8de26b32458d4363548', '「我的奇幻動物朋友」台中市學童繪畫比賽暨台日學童繪畫交流展', '台中中區扶輪社為倡導美育之宗旨，特舉辦「我的奇幻動物朋友」台中市學童繪畫比賽，並於評選結束後與「台日學童繪畫交流展」得獎作品至臺中市大墩文化中心展出。', '臺中港中區扶輪社', '臺中市西區英才路600號', '2025-02-22 00:00:00', '2025-03-05 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.facebook.com/photo?fbid=994493986040694&set=a.646915317465231&locale=zh_TW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「我的奇幻動物朋友」台中市學童繪畫比賽暨台日學童繪畫交流展', `description`='台中中區扶輪社為倡導美育之宗旨，特舉辦「我的奇幻動物朋友」台中市學童繪畫比賽，並於評選結束後與「台日學童繪畫交流展」得獎作品至臺中市大墩文化中心展出。', `organizer`='臺中港中區扶輪社', `address`='臺中市西區英才路600號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.facebook.com/photo?fbid=994493986040694&set=a.646915317465231&locale=zh_TW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8df26b32458d436354d', '無資料', '畢婕（陳綵婕），擅長流體畫、永生花創作，將絢麗的壓克力顏料、油彩、金箔等複合媒材，透過條理序然的顏色深淺與層次分明的色彩堆疊，做出一件件動人的作品。此次展出的作品有「綻放」、「遠處的祈禱」、「映入眼簾」、「紅雲飛絮（粉紅同心圓）」等多元題材系列作品，大大小小總計十五件。其中的「紅雲飛絮（粉紅同心圓）」，以天空中的紅色雲朵為意象，展現花朵的輕盈和浪漫。「綻放」（抽象畫）以絢麗的壓克力顏料為底、佐以油彩、金箔等複合媒材，將習花藝多年的心得融入創作中，瞬間即是永恆。「花月」則是用具象插畫的手法呈現學習花藝多年的喜悅，各色玫瑰花卉充滿背景，如童話般的浪漫場景重現。歡迎大家一起來觀賞。', '臺中市西屯區公所', '臺中市西屯區市政北二路386號', '臺中市西屯區公所', 24.1654462, 120.6337766, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='畢婕（陳綵婕），擅長流體畫、永生花創作，將絢麗的壓克力顏料、油彩、金箔等複合媒材，透過條理序然的顏色深淺與層次分明的色彩堆疊，做出一件件動人的作品。此次展出的作品有「綻放」、「遠處的祈禱」、「映入眼簾」、「紅雲飛絮（粉紅同心圓）」等多元題材系列作品，大大小小總計十五件。其中的「紅雲飛絮（粉紅同心圓）」，以天空中的紅色雲朵為意象，展現花朵的輕盈和浪漫。「綻放」（抽象畫）以絢麗的壓克力顏料為底、佐以油彩、金箔等複合媒材，將習花藝多年的心得融入創作中，瞬間即是永恆。「花月」則是用具象插畫的手法呈現學習花藝多年的喜悅，各色玫瑰花卉充滿背景，如童話般的浪漫場景重現。歡迎大家一起來觀賞。', `organizer`='臺中市西屯區公所', `address`='臺中市西屯區市政北二路386號', `location`='臺中市西屯區公所', `latitude`=24.1654462, `longitude`=120.6337766, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e226b32458d4363552', '大墩典美‧藏藝 【鎏金歲月、冰裂紋甕】陶瓷、【憶】膠彩', '臺中市大墩文化中心透過空間規劃，於大廳設置多個典藏展示特區，展示平面類到立體類，包含油畫、水墨、書法、工藝、雕塑等多種類別的作品，並定期輪番展出。\r\n每件都是經典之作，在各類媒材上皆表現其不凡的獨特美學，邀請民眾細細欣賞藝術之美。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000770', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大墩典美‧藏藝 【鎏金歲月、冰裂紋甕】陶瓷、【憶】膠彩', `description`='臺中市大墩文化中心透過空間規劃，於大廳設置多個典藏展示特區，展示平面類到立體類，包含油畫、水墨、書法、工藝、雕塑等多種類別的作品，並定期輪番展出。\r\n每件都是經典之作，在各類媒材上皆表現其不凡的獨特美學，邀請民眾細細欣賞藝術之美。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000770', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e226b32458d4363553', '無資料', '活動目的:\r\n觀察世界的聲音，發現靈魂的脈動。我們在一次又一次的知遇中淬鍊彼此，以音樂為鑰，實現樂福人生。本場次2024樂福秋季音樂會，由台中市私立樂福音樂短期補習班主辦，將集結音樂教室自創立以來，地17場『樂福音樂家』公益音樂會。本次活動由本班師生家長共同協作幕後團隊，支持學生參與音樂與藝術展演活動，深厚藝術與人文素養提高藝術品味及生活品質。\r\n表演內容:\r\n1.林芮歆 鋼琴 小叮噹(菊池俊輔)\r\n2.吳睿恩 鋼琴 一笑江湖 (祝何)\r\n3.徐睿妤 小提琴 第三號協奏曲(莫札特)\r\n4.陳韋瑞 烏克麗麗 一笑傾城(汪蘇瀧)\r\n5.蘇稟原 吉他 知足(五月天)\r\n6.黃翊豪 吉他 你不是真正的快樂 (五月天)\r\n7.……等……曲目演出……\r\n', '台中市私立樂福音樂短期補習班', '臺中市西區英才路600號', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='活動目的:\r\n觀察世界的聲音，發現靈魂的脈動。我們在一次又一次的知遇中淬鍊彼此，以音樂為鑰，實現樂福人生。本場次2024樂福秋季音樂會，由台中市私立樂福音樂短期補習班主辦，將集結音樂教室自創立以來，地17場『樂福音樂家』公益音樂會。本次活動由本班師生家長共同協作幕後團隊，支持學生參與音樂與藝術展演活動，深厚藝術與人文素養提高藝術品味及生活品質。\r\n表演內容:\r\n1.林芮歆 鋼琴 小叮噹(菊池俊輔)\r\n2.吳睿恩 鋼琴 一笑江湖 (祝何)\r\n3.徐睿妤 小提琴 第三號協奏曲(莫札特)\r\n4.陳韋瑞 烏克麗麗 一笑傾城(汪蘇瀧)\r\n5.蘇稟原 吉他 知足(五月天)\r\n6.黃翊豪 吉他 你不是真正的快樂 (五月天)\r\n7.……等……曲目演出……\r\n', `organizer`='台中市私立樂福音樂短期補習班', `address`='臺中市西區英才路600號', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e226b32458d4363557', '關懷兒童才藝發展暨第十三屆學童寫生比賽', '台中港中區扶輪社為關懷港區兒童才藝發展、激發學童潛能，暨培養學童對寫生才藝之興趣，特辦理關懷兒童才藝發展暨第十三屆學童寫生比賽，並於114年4月19日至5月19日假港區藝術中心辦理展覽展出得獎作品。', '臺中港中區扶輪社', '臺中市清水區忠貞路21號', '2025-04-19 00:00:00', '2025-05-19 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://www.facebook.com/photo?fbid=946455130860040&set=a.478513834320841', '[]') ON DUPLICATE KEY UPDATE `activity_name`='關懷兒童才藝發展暨第十三屆學童寫生比賽', `description`='台中港中區扶輪社為關懷港區兒童才藝發展、激發學童潛能，暨培養學童對寫生才藝之興趣，特辦理關懷兒童才藝發展暨第十三屆學童寫生比賽，並於114年4月19日至5月19日假港區藝術中心辦理展覽展出得獎作品。', `organizer`='臺中港中區扶輪社', `address`='臺中市清水區忠貞路21號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-05-19 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://www.facebook.com/photo?fbid=946455130860040&set=a.478513834320841', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e226b32458d4363558', '織光繪影－丁水泉回顧紀念展', '丁水泉，一位以繪畫編織光影的藝術家。曾經，他的腳步遍滿臺灣大大小小的鄉鎮，為寶島的每一個小角落，留下美好的畫面。1966年，丁水泉出生於曙光之鄉——太麻里，從小喜愛塗鴉、繪畫，16歲時為了追求藝術夢想，前往港都高雄，一待就是50年。在高雄的日子裡，他在「具象視覺藝術畫室」將自己多年習得的素描、水彩、油畫技法傳授給熱愛藝術的學生。學生有老也有少，上課地點從文化中心開始，到七賢路、市議會，甚至是港邊、小巷……從一個人提著畫箱，到一群人一起寫生。雖然丁老師的腳步已經安歇，我們仍希望透過本次的回顧展，帶您一起欣賞他眼中的美麗鄉土，愛上織光繪影的世界。', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-03-08 00:00:00', '2025-04-01 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4073', '[]') ON DUPLICATE KEY UPDATE `activity_name`='織光繪影－丁水泉回顧紀念展', `description`='丁水泉，一位以繪畫編織光影的藝術家。曾經，他的腳步遍滿臺灣大大小小的鄉鎮，為寶島的每一個小角落，留下美好的畫面。1966年，丁水泉出生於曙光之鄉——太麻里，從小喜愛塗鴉、繪畫，16歲時為了追求藝術夢想，前往港都高雄，一待就是50年。在高雄的日子裡，他在「具象視覺藝術畫室」將自己多年習得的素描、水彩、油畫技法傳授給熱愛藝術的學生。學生有老也有少，上課地點從文化中心開始，到七賢路、市議會，甚至是港邊、小巷……從一個人提著畫箱，到一群人一起寫生。雖然丁老師的腳步已經安歇，我們仍希望透過本次的回顧展，帶您一起欣賞他眼中的美麗鄉土，愛上織光繪影的世界。', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-04-01 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4073', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e226b32458d436355a', '「悅讀好食力」主題書展', '以飲食教育為主題，內容涵蓋食物、食安、食桌、食農、食魚五類教育及透過繪本的溫暖筆觸與生動故事，一起探索食物背後的旅程，學習珍惜食物、關懷土地，建立永續的觀念，藉由書展，提升館藏借閱率。\r\n\r\n本次展示書：\r\n愛吹風的洋蔥\r\n營養蔬果ABC\r\n過年就是要吃阿媽的菜頭粿和外婆的蘿蔔糕\r\n玉蜀黍的長頭髮\r\n不想開花的高麗菜\r\n米從哪裡來\r\n餐盒裡的食物從哪兒來?\r\n今天的魚\r\n不想吃，就丟掉?\r\n好麥給你好麵包\r\n……等書籍', '高雄市立圖書館總館', '高雄市美濃區6鄰中正路一段59號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '高雄市立圖書館美濃分館', 22.9001672, 120.5418427, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「悅讀好食力」主題書展', `description`='以飲食教育為主題，內容涵蓋食物、食安、食桌、食農、食魚五類教育及透過繪本的溫暖筆觸與生動故事，一起探索食物背後的旅程，學習珍惜食物、關懷土地，建立永續的觀念，藉由書展，提升館藏借閱率。\r\n\r\n本次展示書：\r\n愛吹風的洋蔥\r\n營養蔬果ABC\r\n過年就是要吃阿媽的菜頭粿和外婆的蘿蔔糕\r\n玉蜀黍的長頭髮\r\n不想開花的高麗菜\r\n米從哪裡來\r\n餐盒裡的食物從哪兒來?\r\n今天的魚\r\n不想吃，就丟掉?\r\n好麥給你好麵包\r\n……等書籍', `organizer`='高雄市立圖書館總館', `address`='高雄市美濃區6鄰中正路一段59號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='高雄市立圖書館美濃分館', `latitude`=22.9001672, `longitude`=120.5418427, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e326b32458d436355f', '澎湖地方特色海洋資源展', '民國七十六年由行政院文建會委託中央研究院動物研究所張崑雄博士主持該研究規劃專案，標示出本館旨意在闡揚地域性海洋資源及文化特色，使用能將過去海洋發展的歷史以及今日人們對海洋的瞭解，甚至未來對海洋的開發方向做一銓釋，並從人文及自然科學的觀點，將與海洋有關的事物加以有系統的收集、整理和展示。', '澎湖縣政府文化局', '澎湖縣馬公市中華路230號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '澎湖縣政府文化局', 23.55534, 119.59234, '--+20', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='澎湖地方特色海洋資源展', `description`='民國七十六年由行政院文建會委託中央研究院動物研究所張崑雄博士主持該研究規劃專案，標示出本館旨意在闡揚地域性海洋資源及文化特色，使用能將過去海洋發展的歷史以及今日人們對海洋的瞭解，甚至未來對海洋的開發方向做一銓釋，並從人文及自然科學的觀點，將與海洋有關的事物加以有系統的收集、整理和展示。', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路230號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='澎湖縣政府文化局', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='--+20', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e326b32458d4363560', '洪根深美術館常設展', '洪根深(1946-)，本縣湖西鄉鼎灣村人，為台灣知名現代水墨畫家。國立台灣師範大學美術系畢業，返鄉任教一年後，移居高雄，先後任教高雄中學及高雄師範大學。其以當代水墨創作成為重要藝術家代表，並投身南台灣現代藝術運動，影響深遠，也是台灣水墨由「現代」走向「後現代」的導師型人物。為表彰其傑出藝術成就與貢獻，本縣以本歷史建築作為其專有美術館，並持續推動現代水墨藝術之發展。\r\n', '澎湖縣政府文化局', '澎湖縣馬公市民族路22號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '洪根深美術館', 23.55534, 119.59234, '無資料', '--', '[]') ON DUPLICATE KEY UPDATE `activity_name`='洪根深美術館常設展', `description`='洪根深(1946-)，本縣湖西鄉鼎灣村人，為台灣知名現代水墨畫家。國立台灣師範大學美術系畢業，返鄉任教一年後，移居高雄，先後任教高雄中學及高雄師範大學。其以當代水墨創作成為重要藝術家代表，並投身南台灣現代藝術運動，影響深遠，也是台灣水墨由「現代」走向「後現代」的導師型人物。為表彰其傑出藝術成就與貢獻，本縣以本歷史建築作為其專有美術館，並持續推動現代水墨藝術之發展。\r\n', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市民族路22號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='洪根深美術館', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='--', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e326b32458d4363561', '大嶼常民生活文物常設展', '透過圖片展示七美境內的人文景觀、自然生態、民俗節慶、農漁產業等。', '澎湖縣七美鄉公所', '澎湖縣七美鄉55號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '七美鄉老人文康活動中心', 23.20108, 119.43393, '無資料', 'http://www.chimi.gov.tw/Dayu/CP.aspx?s=140&n=10146', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大嶼常民生活文物常設展', `description`='透過圖片展示七美境內的人文景觀、自然生態、民俗節慶、農漁產業等。', `organizer`='澎湖縣七美鄉公所', `address`='澎湖縣七美鄉55號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='七美鄉老人文康活動中心', `latitude`=23.20108, `longitude`=119.43393, `ticket_price`='無資料', `source_url`='http://www.chimi.gov.tw/Dayu/CP.aspx?s=140&n=10146', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e326b32458d4363563', '二呆藝術展', '趙二呆先生本名同和，字中平，1916年生於江蘇鎮江，其作品禪、簡、靜、寂，極具個人色彩。本展覽展出趙二呆先生作品，包含水墨、油畫、陶藝、雕塑、版畫、素描、攝影、書法、詩、文、篆刻等才藝。', '澎湖縣政府文化局', '澎湖縣馬公市中華路230號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '澎湖縣政府文化局', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='二呆藝術展', `description`='趙二呆先生本名同和，字中平，1916年生於江蘇鎮江，其作品禪、簡、靜、寂，極具個人色彩。本展覽展出趙二呆先生作品，包含水墨、油畫、陶藝、雕塑、版畫、素描、攝影、書法、詩、文、篆刻等才藝。', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路230號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='澎湖縣政府文化局', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e326b32458d4363565', '澎湖開拓館常設展', '澎湖縣長公館坐落在馬市治平路與忠孝路交叉路口，佔地有六百多坪，是日治時期澎湖廳長宮邸，民國24年（昭和十年）竣工落成，是一幢典型日本「大正-昭和」時期建築，建築風格融合了東西方的建築特色，圓型的窗櫺、歐風八角窗、內開木質大門、日式拉門、日式屋頂、和澎湖特有的貓江石矮牆，顯現建築物的滄桑歲月，戶外庭園有百年古榕，高聳大葉欖仁與特有澎湖植物，提供優質休閒空間，與現有的縣府行政大樓（原澎湖廳舍）互相輝映，屬同一時期建築，深具地方歷史建築特色，在去年均登錄為澎湖的歷史建築來保存。縣長公館至今將近70年歷史，曾先後住過有二位官派的縣長和包括李玉林、徐詠黎、蔣祖武、呂安德、謝有溫、歐堅壯六位民選縣長，其中以李玉林縣長自第一屆至第三屆任內住了有九年五個月最久，但在第11屆王乾同縣長於民國81年10月任內病故之後閒置至今，包括之後的補選高植澎縣長、代理的陳丕積、鄭烈與現任的第14屆縣長賴峰偉等人都未再進住而閒置，但平時還有利用作為縣長宴請賓客的場所之一，這一段地方行政首長的公館的歷史也是地方自治施政上的一大史事。縣政府基於對保存歷史的使命感，加上近年來本土化意識帶動「澎湖學」熱潮，縣長賴峰偉上任大力推動開發與發揚澎湖的歷史意義，為保存縣長公館歷史建築風貌，發揮其文化機能再利用目標，將原建築規劃設置為「澎湖縣史館」，重新賦予歷史的意義，並列為施政重點。經縣府多方極力爭取，88年獲文建會(現為文化部)同意設置「澎湖開拓館」，並成立專案研究小組進行史料蒐集及研究，89年開工，軟硬體設備在今年6月完工，館內規劃設計包括：「澎湖開拓序曲」、「移民路迢迢」、「澎湖聚落拓墾」、「戰爭烽火澎湖」、「澎湖政經建設」、「澎湖文獻閱讀」、「澎湖官邸體驗區」等內部展示及庭園圍牆設置「航向澎湖島」、「媽祖聖績圖」等大型陶磚壁畫，不只要傳承過去的價值，更要開創發揚未來的價值。澎湖開拓館將系統展示澎湖開拓史料及文化，打造一處讓後代認識先民胼手胝足，開拓疆土的精神與智慧的文化空間，不僅是澎湖公有歷史建築保存再利用的典範，更是澎湖開拓歷史的象徵，意義深重。\r\n\r\n', '澎湖縣政府文化局', '澎湖縣馬公市治平路30號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '澎湖開拓館', 23.55534, 119.59234, '全票+30;團體票+20', 'http://phkt.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='澎湖開拓館常設展', `description`='澎湖縣長公館坐落在馬市治平路與忠孝路交叉路口，佔地有六百多坪，是日治時期澎湖廳長宮邸，民國24年（昭和十年）竣工落成，是一幢典型日本「大正-昭和」時期建築，建築風格融合了東西方的建築特色，圓型的窗櫺、歐風八角窗、內開木質大門、日式拉門、日式屋頂、和澎湖特有的貓江石矮牆，顯現建築物的滄桑歲月，戶外庭園有百年古榕，高聳大葉欖仁與特有澎湖植物，提供優質休閒空間，與現有的縣府行政大樓（原澎湖廳舍）互相輝映，屬同一時期建築，深具地方歷史建築特色，在去年均登錄為澎湖的歷史建築來保存。縣長公館至今將近70年歷史，曾先後住過有二位官派的縣長和包括李玉林、徐詠黎、蔣祖武、呂安德、謝有溫、歐堅壯六位民選縣長，其中以李玉林縣長自第一屆至第三屆任內住了有九年五個月最久，但在第11屆王乾同縣長於民國81年10月任內病故之後閒置至今，包括之後的補選高植澎縣長、代理的陳丕積、鄭烈與現任的第14屆縣長賴峰偉等人都未再進住而閒置，但平時還有利用作為縣長宴請賓客的場所之一，這一段地方行政首長的公館的歷史也是地方自治施政上的一大史事。縣政府基於對保存歷史的使命感，加上近年來本土化意識帶動「澎湖學」熱潮，縣長賴峰偉上任大力推動開發與發揚澎湖的歷史意義，為保存縣長公館歷史建築風貌，發揮其文化機能再利用目標，將原建築規劃設置為「澎湖縣史館」，重新賦予歷史的意義，並列為施政重點。經縣府多方極力爭取，88年獲文建會(現為文化部)同意設置「澎湖開拓館」，並成立專案研究小組進行史料蒐集及研究，89年開工，軟硬體設備在今年6月完工，館內規劃設計包括：「澎湖開拓序曲」、「移民路迢迢」、「澎湖聚落拓墾」、「戰爭烽火澎湖」、「澎湖政經建設」、「澎湖文獻閱讀」、「澎湖官邸體驗區」等內部展示及庭園圍牆設置「航向澎湖島」、「媽祖聖績圖」等大型陶磚壁畫，不只要傳承過去的價值，更要開創發揚未來的價值。澎湖開拓館將系統展示澎湖開拓史料及文化，打造一處讓後代認識先民胼手胝足，開拓疆土的精神與智慧的文化空間，不僅是澎湖公有歷史建築保存再利用的典範，更是澎湖開拓歷史的象徵，意義深重。\r\n\r\n', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市治平路30號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='澎湖開拓館', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='全票+30;團體票+20', `source_url`='http://phkt.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e326b32458d4363566', '澎湖生活博物館常設展', '展示內容主要規劃有七大展示主題： （一）海洋的澎湖： 1.發現澎湖（2.大航海時代3.唐山過澎湖（二）歷史風華： 1.軍事與生活2.探訪媽宮城）（三）天佑吾土： 1.信仰與崇拜2.與天同功-媽祖3.代天巡狩-王爺4.民俗紀事四）澎湖人的民俗與生活： 1.咱的年，咱的月（介紹澎湖每月的生業活動、民俗慶典、歲時節慶及生活諺語）2.做山-農的生活3.討海-漁的生活。4.歌吹相聞（介紹澎湖的傳統戲曲與音樂及褒歌等）（五（萬年富貴、瓜瓞綿綿： 1.澎湖的聚落2.生命禮俗（（六）生活筆記： 1.文風教育（澎湖文教發展介紹，從明清、日治、民國等不同時期的教育發展、文石書院及澎湖的先賢）2.休閒娛樂（介紹澎湖的休閒娛樂，包括傳統娛樂、童玩、現代海上活動）3.健康日記（介紹澎湖的民俗醫療、澎湖的醫療院所）4.我家的生活寶貝（由民眾提供具特殊意義的生活器物展）5.館藏的生活寶貝（館內所藏生活器物）（七）澎湖論壇： 1.菊島大代誌（回顧菊島大代誌）2.願景澎湖。3.澎湖劇場（以「菊島依戀」影片搭配文物、燈光演出，闡述年輕人對澎湖發展的情感對話。）\r\n', '澎湖縣政府文化局', '澎湖縣馬公市新生路327號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '澎湖生活博物館', 23.55534, 119.59234, '學生縣民優待票+30;團體票+60;全票+80;本縣學生優待票+15;縣民團體優待票+20', 'http://www.phlm.nat.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='澎湖生活博物館常設展', `description`='展示內容主要規劃有七大展示主題： （一）海洋的澎湖： 1.發現澎湖（2.大航海時代3.唐山過澎湖（二）歷史風華： 1.軍事與生活2.探訪媽宮城）（三）天佑吾土： 1.信仰與崇拜2.與天同功-媽祖3.代天巡狩-王爺4.民俗紀事四）澎湖人的民俗與生活： 1.咱的年，咱的月（介紹澎湖每月的生業活動、民俗慶典、歲時節慶及生活諺語）2.做山-農的生活3.討海-漁的生活。4.歌吹相聞（介紹澎湖的傳統戲曲與音樂及褒歌等）（五（萬年富貴、瓜瓞綿綿： 1.澎湖的聚落2.生命禮俗（（六）生活筆記： 1.文風教育（澎湖文教發展介紹，從明清、日治、民國等不同時期的教育發展、文石書院及澎湖的先賢）2.休閒娛樂（介紹澎湖的休閒娛樂，包括傳統娛樂、童玩、現代海上活動）3.健康日記（介紹澎湖的民俗醫療、澎湖的醫療院所）4.我家的生活寶貝（由民眾提供具特殊意義的生活器物展）5.館藏的生活寶貝（館內所藏生活器物）（七）澎湖論壇： 1.菊島大代誌（回顧菊島大代誌）2.願景澎湖。3.澎湖劇場（以「菊島依戀」影片搭配文物、燈光演出，闡述年輕人對澎湖發展的情感對話。）\r\n', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市新生路327號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='澎湖生活博物館', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='學生縣民優待票+30;團體票+60;全票+80;本縣學生優待票+15;縣民團體優待票+20', `source_url`='http://www.phlm.nat.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e326b32458d436356d', 'MOMO故事屋（114年3月）', '歡迎大朋友小朋友一起來聽故事。\r\n親子教室遊戲區及繪本區都會不定期更新上架新的玩具及繪本供大家借用及閱讀，歡迎大朋友、小朋友、家長前來一起參與。\r\n提醒：持有家庭卡的讀者，記得每月參加一次親子相關活動以利續卡。', '欣榮紀念圖書館暨玉蘭文化會館', '南投縣竹山鎮大勇路 26 號', '2025-03-08 00:00:00', '2025-03-22 00:00:00', '欣榮紀念圖書館暨玉蘭文化會館', 23.7569747, 120.6749408, '無資料', 'https://www.facebook.com/profile.php?id=100064705267614', '[]') ON DUPLICATE KEY UPDATE `activity_name`='MOMO故事屋（114年3月）', `description`='歡迎大朋友小朋友一起來聽故事。\r\n親子教室遊戲區及繪本區都會不定期更新上架新的玩具及繪本供大家借用及閱讀，歡迎大朋友、小朋友、家長前來一起參與。\r\n提醒：持有家庭卡的讀者，記得每月參加一次親子相關活動以利續卡。', `organizer`='欣榮紀念圖書館暨玉蘭文化會館', `address`='南投縣竹山鎮大勇路 26 號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='欣榮紀念圖書館暨玉蘭文化會館', `latitude`=23.7569747, `longitude`=120.6749408, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064705267614', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e426b32458d436356f', '無資料', '【金喇叭12年初衷】獲選113桃園市傑出演藝團隊\r\n\r\n團體簡介\r\n金喇叭成立於2012年6月。設立至今秉持創新改變的理念，期望突破以往大眾對銅管音樂過於形式化、沈重、吵雜的刻板印象。藉由將流行樂曲重新改編成銅管5重奏之形式，並融入許多臺灣在地元素（包含國語、閩南、客家等多元文化），希望帶給觀眾不同且獨特的音樂饗宴。\r\n金喇叭走過10年的歲月，創造出許多不同的演出形式，以輕鬆活潑的氛圍，搭配特製的節目效果，並結合傳統民謠、流行音樂、電視、電影配樂及世界名曲，讓音樂不只是「聽」，而是能夠樂在其中，享受當下的快樂。\r\n經營理念\r\n十年磨一劍，「音樂」能夠傳遞情感，每一場不同性質的演出，金喇叭期許藉由不同的主題來呈現音樂，以符合觀眾朋友們當下的聆聽情境。\r\n音樂與生活息息相關，有了音樂的陪伴，將使我們能更好地體驗生活中的美好。金喇叭希望每場參與音樂會的大小朋友們，都可以獲得滿滿的喜悅和幸福；並且也祈願演出結束後，能在每個人心中埋下音樂的種苗，持續地將美好延續下去。', '金喇叭銅管樂團', '南投縣南投市建國路135號', '南投縣政府文化局', 23.908225, 120.681559, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='【金喇叭12年初衷】獲選113桃園市傑出演藝團隊\r\n\r\n團體簡介\r\n金喇叭成立於2012年6月。設立至今秉持創新改變的理念，期望突破以往大眾對銅管音樂過於形式化、沈重、吵雜的刻板印象。藉由將流行樂曲重新改編成銅管5重奏之形式，並融入許多臺灣在地元素（包含國語、閩南、客家等多元文化），希望帶給觀眾不同且獨特的音樂饗宴。\r\n金喇叭走過10年的歲月，創造出許多不同的演出形式，以輕鬆活潑的氛圍，搭配特製的節目效果，並結合傳統民謠、流行音樂、電視、電影配樂及世界名曲，讓音樂不只是「聽」，而是能夠樂在其中，享受當下的快樂。\r\n經營理念\r\n十年磨一劍，「音樂」能夠傳遞情感，每一場不同性質的演出，金喇叭期許藉由不同的主題來呈現音樂，以符合觀眾朋友們當下的聆聽情境。\r\n音樂與生活息息相關，有了音樂的陪伴，將使我們能更好地體驗生活中的美好。金喇叭希望每場參與音樂會的大小朋友們，都可以獲得滿滿的喜悅和幸福；並且也祈願演出結束後，能在每個人心中埋下音樂的種苗，持續地將美好延續下去。', `organizer`='金喇叭銅管樂團', `address`='南投縣南投市建國路135號', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677ee8e426b32458d4363570', '【相聲瓦舍】《狐說》', '【相聲瓦舍】2025年全新創作《狐說》\r\n傳說…狐狸精修煉百年成人，千年成仙。\r\n今晚戲台上沒有人！\r\n水靈動人的狐媚妖精，把好色的雪神、貪杯的風神搞到PTSD？\r\n帥氣歐爸的九尾狐仙，夜夜笙歌，滿足各位姨太太。\r\n糊里糊塗的野狐禪，到底說的是什麼禪？\r\n【相聲瓦舍】前所未見的作品。來自平行宇宙的妖魔、獸靈、狐仙、女鬼。變身、飛天、打架、畸戀？！\r\n防不勝防的囈語狂想。小心，別露出狐狸尾巴！2025歡迎來聽我們胡說……，喔，是《狐說》。\r\n\r\n演出人員：馮翊綱、時一修、 御天十兵衛 、趙逸嵐 、巫明如、古辛 ', '相聲瓦舍', '南投縣南投市建國路135號', '2025-06-28 00:00:00', '2025-06-28 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '票價+400;票價+600;票價+800;票價+1000;票價+1200;票價+1500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【相聲瓦舍】《狐說》', `description`='【相聲瓦舍】2025年全新創作《狐說》\r\n傳說…狐狸精修煉百年成人，千年成仙。\r\n今晚戲台上沒有人！\r\n水靈動人的狐媚妖精，把好色的雪神、貪杯的風神搞到PTSD？\r\n帥氣歐爸的九尾狐仙，夜夜笙歌，滿足各位姨太太。\r\n糊里糊塗的野狐禪，到底說的是什麼禪？\r\n【相聲瓦舍】前所未見的作品。來自平行宇宙的妖魔、獸靈、狐仙、女鬼。變身、飛天、打架、畸戀？！\r\n防不勝防的囈語狂想。小心，別露出狐狸尾巴！2025歡迎來聽我們胡說……，喔，是《狐說》。\r\n\r\n演出人員：馮翊綱、時一修、 御天十兵衛 、趙逸嵐 、巫明如、古辛 ', `organizer`='相聲瓦舍', `address`='南投縣南投市建國路135號', `start_date`='2025-06-28 00:00:00', `end_date`='2025-06-28 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='票價+400;票價+600;票價+800;票價+1000;票價+1200;票價+1500', `source_url`='https://www.opentix.life/', `image_url`='[]';
