INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677f77978f1579d1ccee33c2', '【藝文講座】節氣．情詩．台灣島～周蘇宗台語詩', '周蘇宗先生為熱心公益的慈善家和閩南語詩人，其詩作《斯卡羅戰歌》獲「教育部第八屆閩客文學獎」閩南語現代詩社會組首獎。周老師經多年浸淫研究，將台語「文、語、字」一體到位，並用在台語詩的創作上。\r\n\r\n講座中，將發表其最近作品《風吹》詩集中的多首新作，同時將詩詞與音樂創作結合，更顯台語之美。期盼透過台語詩的吟唱改變大家對台語的刻板印象，共同領略台語之美！\r\n\r\n■時間：2025年3月15日（六）14：00-16：00\r\n■地點：林建生紀念圖書館地下樓（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額180位，七歲以上，免費報名入場。\r\n\r\n■報名方式：3/5（三）10:00起，網路報名  https://www.accupass.com/go/1140315\r\n#額滿後恕無現場報名\r\n\r\n■講者：周蘇宗（詩人）\r\n\r\n★凡參加講座者，將獲贈《風吹》詩集一本。\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★網址： https://www.ljsedu.org.tw\r\n★歡迎加入《林建生基金會》line 好友～ https://bit.ly/2KFVgg2\r\n', '財團法人紀念林建生教育基金會', '新北市蘆洲區三民路178號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '林建生紀念圖書館', 25.08927173, 121.4712461, '無資料', 'https://www.accupass.com/go/1140315', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【藝文講座】節氣．情詩．台灣島～周蘇宗台語詩', `description`='周蘇宗先生為熱心公益的慈善家和閩南語詩人，其詩作《斯卡羅戰歌》獲「教育部第八屆閩客文學獎」閩南語現代詩社會組首獎。周老師經多年浸淫研究，將台語「文、語、字」一體到位，並用在台語詩的創作上。\r\n\r\n講座中，將發表其最近作品《風吹》詩集中的多首新作，同時將詩詞與音樂創作結合，更顯台語之美。期盼透過台語詩的吟唱改變大家對台語的刻板印象，共同領略台語之美！\r\n\r\n■時間：2025年3月15日（六）14：00-16：00\r\n■地點：林建生紀念圖書館地下樓（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額180位，七歲以上，免費報名入場。\r\n\r\n■報名方式：3/5（三）10:00起，網路報名  https://www.accupass.com/go/1140315\r\n#額滿後恕無現場報名\r\n\r\n■講者：周蘇宗（詩人）\r\n\r\n★凡參加講座者，將獲贈《風吹》詩集一本。\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★網址： https://www.ljsedu.org.tw\r\n★歡迎加入《林建生基金會》line 好友～ https://bit.ly/2KFVgg2\r\n', `organizer`='財團法人紀念林建生教育基金會', `address`='新北市蘆洲區三民路178號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='林建生紀念圖書館', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='無資料', `source_url`='https://www.accupass.com/go/1140315', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('677f90598f1579d1ccee33c3', '安放的所在—2024歲末小品展 ', '每件作品，都有它安放的所在。或許是在博物館的典藏室裡，或是在美術館的展覽牆上，或成為了熙來攘往的鬧區地標，亦或是仍深藏在藝術家的工作室，也或者是在某個家庭的溫馨角落……。而若是抽象來看，這些作品的位置又多了更多可能性，它可能是大自然山野間的真實座標，可能是在虛無飄渺的虛幻世界，也可能是一個心靈喘息休憩的角落，又或者是他人賦予的評價及定位……等，此時，「位置」似乎象徵了創作者對於自己關注事物的寄情與信念，而作者也試圖從創作中獲得回饋與成長。\r\n\r\n「安放的所在」在承先啟後的年末時刻，希望帶給大家各種不同的風景，豐富滋養我們的藝術生活。一諾藝術邀請了五位藝術家：王惠仁、宋立、邱怡霖、許璧翎、鄭畬友，來和觀賞者一起創造屬於作品的位置，一起尋找那個連身心都能一併安放的所在。\r\n\r\n▌展覽資訊\r\n安放的所在—2024歲末小品展\r\n展    期12.15 (日) ―2.28(五)   \r\n藝術家 王惠仁、宋立、邱怡霖、許璧翎、鄭畬友\r\n\r\n地點│新瓦屋客家文化保存區 一諾藝術\r\n地址│新竹縣竹北市文興路一段123號-8\r\n電話│03-6685981\r\n', '一諾藝術', '新竹縣竹北市文興路一段123號-8 (新瓦屋展覽館)', '2025-02-23 00:00:00', '2025-02-28 00:00:00', '一諾藝術', 24.83816209, 120.9948704, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='安放的所在—2024歲末小品展 ', `description`='每件作品，都有它安放的所在。或許是在博物館的典藏室裡，或是在美術館的展覽牆上，或成為了熙來攘往的鬧區地標，亦或是仍深藏在藝術家的工作室，也或者是在某個家庭的溫馨角落……。而若是抽象來看，這些作品的位置又多了更多可能性，它可能是大自然山野間的真實座標，可能是在虛無飄渺的虛幻世界，也可能是一個心靈喘息休憩的角落，又或者是他人賦予的評價及定位……等，此時，「位置」似乎象徵了創作者對於自己關注事物的寄情與信念，而作者也試圖從創作中獲得回饋與成長。\r\n\r\n「安放的所在」在承先啟後的年末時刻，希望帶給大家各種不同的風景，豐富滋養我們的藝術生活。一諾藝術邀請了五位藝術家：王惠仁、宋立、邱怡霖、許璧翎、鄭畬友，來和觀賞者一起創造屬於作品的位置，一起尋找那個連身心都能一併安放的所在。\r\n\r\n▌展覽資訊\r\n安放的所在—2024歲末小品展\r\n展    期12.15 (日) ―2.28(五)   \r\n藝術家 王惠仁、宋立、邱怡霖、許璧翎、鄭畬友\r\n\r\n地點│新瓦屋客家文化保存區 一諾藝術\r\n地址│新竹縣竹北市文興路一段123號-8\r\n電話│03-6685981\r\n', `organizer`='一諾藝術', `address`='新竹縣竹北市文興路一段123號-8 (新瓦屋展覽館)', `start_date`='2025-02-23 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='一諾藝術', `latitude`=24.83816209, `longitude`=120.9948704, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
