INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67803aa626b32458d436357d', '臺灣客家茶文化館常設展 - 尋客茶路', '臺灣客家茶文化館常設展 —「尋客茶路」。以茶之名，一趟連結世界與臺灣內山的文化之路 路上交織著臺灣茶百年歷史與茶山風貌，看見臺灣人敬天、謝地、待人的生活內涵，理解茶葉到茶湯的風味緣由，紀錄東方美人冠軍茶師的土地精算哲學。', '桃園市政府客家事務局', '桃園市龍潭區高原路768號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺灣客家茶文化館', 24.85064954, 121.2117877, '一般票價+160;優惠票+80', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺灣客家茶文化館常設展 - 尋客茶路', `description`='臺灣客家茶文化館常設展 —「尋客茶路」。以茶之名，一趟連結世界與臺灣內山的文化之路 路上交織著臺灣茶百年歷史與茶山風貌，看見臺灣人敬天、謝地、待人的生活內涵，理解茶葉到茶湯的風味緣由，紀錄東方美人冠軍茶師的土地精算哲學。', `organizer`='桃園市政府客家事務局', `address`='桃園市龍潭區高原路768號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺灣客家茶文化館', `latitude`=24.85064954, `longitude`=121.2117877, `ticket_price`='一般票價+160;優惠票+80', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67803aad26b32458d436357e', '【偶．多元文化之身】特展', '本特展精選自台原藝術文化基金會董事長林經甫博士慷慨捐贈的萬餘件偶戲文物，包括戲偶、戲台、道具、劇本與面具等，展現偶戲文物乘載的多元文化，並由此帶領觀眾探索不同文化的相同之處，促進大眾理解與交流。', '國立臺灣博物館', '臺北市中正區襄陽路二號', '2025-01-01 00:00:00', '2025-08-31 00:00:00', '國立臺灣博物館', 25.03240487, 121.5198839, '全票+30;半票+15', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【偶．多元文化之身】特展', `description`='本特展精選自台原藝術文化基金會董事長林經甫博士慷慨捐贈的萬餘件偶戲文物，包括戲偶、戲台、道具、劇本與面具等，展現偶戲文物乘載的多元文化，並由此帶領觀眾探索不同文化的相同之處，促進大眾理解與交流。', `organizer`='國立臺灣博物館', `address`='臺北市中正區襄陽路二號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='國立臺灣博物館', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='全票+30;半票+15', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67803aaf26b32458d4363580', '【發現臺灣：重訪臺灣博物學與博物學家的年代】', '新世紀常設展「首部曲」隆重揭幕，時序回溯至臺博館的源起：一百多年前，臺博管初創立的20世紀初，臺灣博物學家擅場的「發現年代」，探索那些奠定今日臺博館收藏基礎、形塑臺博館風貌的博物學發現、發現者，與發現傳統。', '國立臺灣博物館', '臺北市中正區襄陽路二號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '國立臺灣博物館', 25.03240487, 121.5198839, '全票+30;半票+15', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【發現臺灣：重訪臺灣博物學與博物學家的年代】', `description`='新世紀常設展「首部曲」隆重揭幕，時序回溯至臺博館的源起：一百多年前，臺博管初創立的20世紀初，臺灣博物學家擅場的「發現年代」，探索那些奠定今日臺博館收藏基礎、形塑臺博館風貌的博物學發現、發現者，與發現傳統。', `organizer`='國立臺灣博物館', `address`='臺北市中正區襄陽路二號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='國立臺灣博物館', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='全票+30;半票+15', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67803aaf26b32458d4363581', '【博物臺灣】', '《博物臺灣》是臺博館新世紀常設展第三部曲，藉由「自然臺灣」及「浮生臺灣」兩大展示主軸，以臺博館特有蒐藏或具代表性的標本為重心，展現臺灣的在地特殊性與歷史新定位，並強調人文與自然交融的新時代觀點，呈現臺灣環境樣態與歷史文化。', '國立臺灣博物館', '臺北市中正區襄陽路二號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '國立臺灣博物館', 25.03240487, 121.5198839, '全票+30;半票+15', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【博物臺灣】', `description`='《博物臺灣》是臺博館新世紀常設展第三部曲，藉由「自然臺灣」及「浮生臺灣」兩大展示主軸，以臺博館特有蒐藏或具代表性的標本為重心，展現臺灣的在地特殊性與歷史新定位，並強調人文與自然交融的新時代觀點，呈現臺灣環境樣態與歷史文化。', `organizer`='國立臺灣博物館', `address`='臺北市中正區襄陽路二號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='國立臺灣博物館', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='全票+30;半票+15', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67803aaf26b32458d4363582', '【煎熬時代：樟腦產業與南門工場】', '南門館自2013年11月開館已屆10年，今年度將原有常設展覽與古蹟修復現地展示全面整合更新，內容包括：定義、市場、戰場、生產、樟腦專賣、鴉片專賣、南門工場以及現地展示等8大主題，以剖析臺灣近代化過程中特殊的樟腦、鴉片專賣產業史，以及園區前身之南門工場歷史沿革與古蹟建築特色。', '國立臺灣博物館', '臺北市中正區南昌路一段1號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '國立臺灣博物館南門館', 25.03240487, 121.5198839, '全票+20;半票+10', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=90088&request_locale=tw&useLanguage=tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【煎熬時代：樟腦產業與南門工場】', `description`='南門館自2013年11月開館已屆10年，今年度將原有常設展覽與古蹟修復現地展示全面整合更新，內容包括：定義、市場、戰場、生產、樟腦專賣、鴉片專賣、南門工場以及現地展示等8大主題，以剖析臺灣近代化過程中特殊的樟腦、鴉片專賣產業史，以及園區前身之南門工場歷史沿革與古蹟建築特色。', `organizer`='國立臺灣博物館', `address`='臺北市中正區南昌路一段1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='國立臺灣博物館南門館', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='全票+20;半票+10', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=90088&request_locale=tw&useLanguage=tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67803ab426b32458d4363586', '葉尹凡(Ivan Yehorov)「暖心大地」油畫個展', '「伊凡」為台灣女婿,用繪畫記錄台灣之美\r\n生活中平凡事物皆是描繪對象\r\n筆下的景物畫反應其生命際遇...\r\n誠摯邀請您來感受這位\r\n來自烏克蘭的畫家傳達藝術之美\r\n\r\n', '臺中市太平區戶政事務所', '臺中市太平區', '2025-01-01 00:00:00', '2025-04-30 00:00:00', '太平區（臺中市）=', 24.11477375, 120.7734217, '無資料', 'https://www.facebook.com/photo?fbid=1014299490737737&set=pcb.1014326320735054', '[]') ON DUPLICATE KEY UPDATE `activity_name`='葉尹凡(Ivan Yehorov)「暖心大地」油畫個展', `description`='「伊凡」為台灣女婿,用繪畫記錄台灣之美\r\n生活中平凡事物皆是描繪對象\r\n筆下的景物畫反應其生命際遇...\r\n誠摯邀請您來感受這位\r\n來自烏克蘭的畫家傳達藝術之美\r\n\r\n', `organizer`='臺中市太平區戶政事務所', `address`='臺中市太平區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='太平區（臺中市）=', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://www.facebook.com/photo?fbid=1014299490737737&set=pcb.1014326320735054', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67803ab926b32458d436358d', '《山的守護》', '在柴山腳下、內惟埤園區西側，內惟藝術中心優雅矗立，為來訪旅人準備好輕盈漫步的遊程。\r\n\r\n拾一隅喧囂間的寧靜，在內惟閱讀區裡，由藝術家Stella帶來軟石作品，呼應被山神、自然之光包圍的建築，陪伴我們在山的守護之中，共度暖浴祝福的每一天。\r\n\r\n \r\n展出作品/\r\n\r\n◇山的守護\r\n\r\n以山形疊石呼應被山神、自然之光包圍的內惟藝術中心，陪伴我們在山的守護之中，共度暖浴祝福的每一天。\r\n\r\n◇內惟地景地毯\r\n\r\n內惟埤原是高雄市最大的灌溉埤塘溼地，現在則有著美術館生態園區，以高雄市立美術館、兒童美術館、內惟藝術中心陪伴人們，與自然共構的園區，讓城市與生態共生。\r\n\r\n \r\n藝術家/ Stella\r\n\r\n本展邀請新銳藝術家Stella創作，以其擅長的簇絨媒材，用軟物件呈現硬材質的軟石作品，呼應場館突破框架的企圖心，帶來既是溫暖的軟調氣氛，又是能守護旅客的山石意象作品；同時為內惟埤塘創作地景地毯，供觀眾置身其中，象徵被與自然共構的園區所環抱之都市綠洲。', '內惟藝術中心', '高雄市鼓山區馬卡道路329號', '2025-01-07 00:00:00', '2025-06-08 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '無資料', 'https://www.nwac.org.tw/tw/art-content/943E211dd86c', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《山的守護》', `description`='在柴山腳下、內惟埤園區西側，內惟藝術中心優雅矗立，為來訪旅人準備好輕盈漫步的遊程。\r\n\r\n拾一隅喧囂間的寧靜，在內惟閱讀區裡，由藝術家Stella帶來軟石作品，呼應被山神、自然之光包圍的建築，陪伴我們在山的守護之中，共度暖浴祝福的每一天。\r\n\r\n \r\n展出作品/\r\n\r\n◇山的守護\r\n\r\n以山形疊石呼應被山神、自然之光包圍的內惟藝術中心，陪伴我們在山的守護之中，共度暖浴祝福的每一天。\r\n\r\n◇內惟地景地毯\r\n\r\n內惟埤原是高雄市最大的灌溉埤塘溼地，現在則有著美術館生態園區，以高雄市立美術館、兒童美術館、內惟藝術中心陪伴人們，與自然共構的園區，讓城市與生態共生。\r\n\r\n \r\n藝術家/ Stella\r\n\r\n本展邀請新銳藝術家Stella創作，以其擅長的簇絨媒材，用軟物件呈現硬材質的軟石作品，呼應場館突破框架的企圖心，帶來既是溫暖的軟調氣氛，又是能守護旅客的山石意象作品；同時為內惟埤塘創作地景地毯，供觀眾置身其中，象徵被與自然共構的園區所環抱之都市綠洲。', `organizer`='內惟藝術中心', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-01-07 00:00:00', `end_date`='2025-06-08 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='無資料', `source_url`='https://www.nwac.org.tw/tw/art-content/943E211dd86c', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67803ab926b32458d436358e', '三民書法班聯合書法展', '聘請專業書法家，藉由心靈修持入門進入書法初階，以間架、點配線條、結體為學習重點，進入「神至筆至」的書寫樂趣，達到修心養性和諧精神境界。\r\n本次將展出由張宗仁老師所帶領的三民書法班成員所揮毫的「三民書法班聯合書法展」，歡迎大家踴躍參觀。\r\n\r\n✅展出時間：114/1/9-2/28(開館時間)\r\n✅展出地點：三民分館3樓藝文廊道\r\n參觀民眾者有機會獲得斗方春聯喔✨\r\n\r\n#三民分館', '高雄市立圖書館總館', '高雄市三民區2鄰十全一路220號', '2025-01-09 00:00:00', '2025-02-28 00:00:00', '高雄市立圖書館三民分館', 22.646393, 120.306137, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三民書法班聯合書法展', `description`='聘請專業書法家，藉由心靈修持入門進入書法初階，以間架、點配線條、結體為學習重點，進入「神至筆至」的書寫樂趣，達到修心養性和諧精神境界。\r\n本次將展出由張宗仁老師所帶領的三民書法班成員所揮毫的「三民書法班聯合書法展」，歡迎大家踴躍參觀。\r\n\r\n✅展出時間：114/1/9-2/28(開館時間)\r\n✅展出地點：三民分館3樓藝文廊道\r\n參觀民眾者有機會獲得斗方春聯喔✨\r\n\r\n#三民分館', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區2鄰十全一路220號', `start_date`='2025-01-09 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='高雄市立圖書館三民分館', `latitude`=22.646393, `longitude`=120.306137, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67803ab926b32458d436358f', '無資料', '孩子是精靈，故事是魔法棒，點綴孩子的心，開啟孩子的夢，透過故事媽媽的口，故事將變成幸福的種子，灑向每個角落，讓高雄變成一座開滿五彩繽紛幸福花朵的書香城市。\r\n~高雄市立圖書館各分館fun心聽故事時間於每星期五、六早上10:00及星期日下午15:00免費入場，歡迎各位小朋友踴躍參加~', '高雄市立圖書館總館', '高雄市三民區2鄰十全一路220號', '高雄市立圖書館三民分館', 22.646393, 120.306137, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='孩子是精靈，故事是魔法棒，點綴孩子的心，開啟孩子的夢，透過故事媽媽的口，故事將變成幸福的種子，灑向每個角落，讓高雄變成一座開滿五彩繽紛幸福花朵的書香城市。\r\n~高雄市立圖書館各分館fun心聽故事時間於每星期五、六早上10:00及星期日下午15:00免費入場，歡迎各位小朋友踴躍參加~', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區2鄰十全一路220號', `location`='高雄市立圖書館三民分館', `latitude`=22.646393, `longitude`=120.306137, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67803abb26b32458d4363595', '山海聚—113工藝聚落成果展', '《山海聚》主要以「113年度工藝聚落振興發展計畫」及「好好吃飯－2024陶藝人才培訓課程計畫」執行成果為主。工藝聚落由傳統工藝的淬鍊與當地的文化交融而來，亦是世代傳承記憶與工藝技藝發芽的土地，在其承載的文化價值、情感聯繫、匠人精神與自然和諧共生的智慧下，誕生屬於他們極具識別性的特色工藝，讓工藝聚落不僅是工藝生產的場所，亦是地方創生價值的展現。\r\n《山海聚》展覽主題以「海中有山、山中有海」山海聚合相生相應概念，分述《海嶼》、《山海》兩個子題，書寫來自7個工藝聚落的生命故事，包含：\r\n「玉里聚落」提出風土餐桌的工藝服務，運用在地玉石瓷土及野菜食蔬設計工藝風土佳餚，帶領觀者體驗花東縱谷間的風土文化。\r\n「大溪聚落」從早期林木家具產業脈絡發跡，在大溪木藝生態博物館的推動下，積極進行國際交流並舉辦大溪工藝週系列活動，與大溪共榮共好。\r\n南迴公路上的「南迴聚落」，則以邊架舟串聯太麻里排灣族部落的木雕、琉璃珠與十字繡傳統原民工藝特色，探尋南島族群文化。\r\n而以青年工藝家為首的「澎湖聚落」，取材島嶼自然與海廢資源，辦理工坊、工藝青創市集及建置工藝地圖。\r\n「笨港聚落」以北港朝天宮傳統宗廟工藝為主軸，共同創作藝閣車與花燈，重現工藝遶境場景。\r\n「安平聚落」從在地劍獅文化出發，規劃設計遊程講座、劍獅藝品及微電影主題拍攝等，轉譯劍獅工藝文化。\r\n「鶯歌陶瓷」為臺灣著名的地域觀光特色，透過鶯歌陶藝人才培訓課程計畫，以飯桌食器為主題創作，走進鶯歌陶瓷聚落日常。', '苗栗工藝產業研發分館', '苗栗縣苗栗市水流娘巷11鄰8-2號', '2025-01-01 00:00:00', '2025-04-27 00:00:00', '苗栗工藝產業研發分館', 24.5328836, 120.8165288, '無資料', 'https://www.ntcri.gov.tw/home/zh-tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='山海聚—113工藝聚落成果展', `description`='《山海聚》主要以「113年度工藝聚落振興發展計畫」及「好好吃飯－2024陶藝人才培訓課程計畫」執行成果為主。工藝聚落由傳統工藝的淬鍊與當地的文化交融而來，亦是世代傳承記憶與工藝技藝發芽的土地，在其承載的文化價值、情感聯繫、匠人精神與自然和諧共生的智慧下，誕生屬於他們極具識別性的特色工藝，讓工藝聚落不僅是工藝生產的場所，亦是地方創生價值的展現。\r\n《山海聚》展覽主題以「海中有山、山中有海」山海聚合相生相應概念，分述《海嶼》、《山海》兩個子題，書寫來自7個工藝聚落的生命故事，包含：\r\n「玉里聚落」提出風土餐桌的工藝服務，運用在地玉石瓷土及野菜食蔬設計工藝風土佳餚，帶領觀者體驗花東縱谷間的風土文化。\r\n「大溪聚落」從早期林木家具產業脈絡發跡，在大溪木藝生態博物館的推動下，積極進行國際交流並舉辦大溪工藝週系列活動，與大溪共榮共好。\r\n南迴公路上的「南迴聚落」，則以邊架舟串聯太麻里排灣族部落的木雕、琉璃珠與十字繡傳統原民工藝特色，探尋南島族群文化。\r\n而以青年工藝家為首的「澎湖聚落」，取材島嶼自然與海廢資源，辦理工坊、工藝青創市集及建置工藝地圖。\r\n「笨港聚落」以北港朝天宮傳統宗廟工藝為主軸，共同創作藝閣車與花燈，重現工藝遶境場景。\r\n「安平聚落」從在地劍獅文化出發，規劃設計遊程講座、劍獅藝品及微電影主題拍攝等，轉譯劍獅工藝文化。\r\n「鶯歌陶瓷」為臺灣著名的地域觀光特色，透過鶯歌陶藝人才培訓課程計畫，以飯桌食器為主題創作，走進鶯歌陶瓷聚落日常。', `organizer`='苗栗工藝產業研發分館', `address`='苗栗縣苗栗市水流娘巷11鄰8-2號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='苗栗工藝產業研發分館', `latitude`=24.5328836, `longitude`=120.8165288, `ticket_pri