INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67803abb26b32458d436359f', '書海拾藝-李枝明老師師生作品展覽', '書法雅展\r\n一筆一畫筆墨之間，尋一份心靈的安然。\r\n一筆一劃也蘊藏著深厚的文化底蘊與動人的寧靜之美。\r\n在這裡，欣賞書法學員的作品，讓筆墨流轉的藝術魅力，平易走近書法的世界，來一段藝術與您相伴的時光。', '南投縣中寮鄉立圖書館', '南投縣中寮鄉永平路270號四樓', '2025-01-14 00:00:00', '2025-02-28 00:00:00', '南投縣中寮鄉立圖書館', 23.8790949, 120.7659918, '無資料', 'https://www.facebook.com/profile.php?id=100081167516780', '[]') ON DUPLICATE KEY UPDATE `activity_name`='書海拾藝-李枝明老師師生作品展覽', `description`='書法雅展\r\n一筆一畫筆墨之間，尋一份心靈的安然。\r\n一筆一劃也蘊藏著深厚的文化底蘊與動人的寧靜之美。\r\n在這裡，欣賞書法學員的作品，讓筆墨流轉的藝術魅力，平易走近書法的世界，來一段藝術與您相伴的時光。', `organizer`='南投縣中寮鄉立圖書館', `address`='南投縣中寮鄉永平路270號四樓', `start_date`='2025-01-14 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='南投縣中寮鄉立圖書館', `latitude`=23.8790949, `longitude`=120.7659918, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100081167516780', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6780f00b07f3ee9e312cb977', '台灣蠟筆藝術之美-王建民 Jam-Min Wang蠟筆王', '【台灣蠟筆藝術之美】\r\n一本初心，不斷追尋開拓蠟筆的新藝境\r\n丨展覽時間丨2025/01～2025/04\r\n丨展覽地點丨桃園機場第一航廈3F出境大廳北側展廳\r\n丨合作單位丨桃園國際機場股份有限公司、新東陽股份有限公司\r\n丨策展單位丨右岱藝術\r\n丨策 展 人丨徐予紅\r\n\r\n丨機場展覽、專業展覽規畫、展覽合作、媒體暨商品銷售窗口丨\r\n聯絡人：徐予紅 0975-638759; \r\n(LINE ID:yuhung1108)\r\nMail：uday.tpe@gmail.com\r\n＃右岱藝術 ＃策展 ＃藝術經紀\r\n\r\n展覽藝術家\r\n王建民Jam-Min Wang (蠟筆王)\r\n【現    任】\r\n文化大學推廣教育部/ 講師\r\n蘆洲林建生圖書館/ 講師\r\n中華文創學會/ 常務理事\r\n中華國際策展經紀交流協會/ 常務理事\r\n台灣國際藝術家協會/ 常務理事\r\n兒童藝術文教基金會/ 董事\r\n【重要著作】\r\n不可思議的蠟筆魔法書 (蠟筆畫技巧專書) \r\n\r\n王建民，又稱台灣蠟筆王，台灣知名蠟筆畫藝術家，獨創「板雕蠟彩」藝術，作品於海峽兩岸各地展覽，並將其蠟筆創作授權開發許多文創商品，號稱「蠟筆達人」，「台灣蠟筆藝術第一人」。\r\n蠟筆王從事藝術創作，始終堅持以蠟筆藝術為創作核心，獨創「板雕蠟彩」藝術，並堅持以蠟筆藝術為創作核心，不斷創新繪畫技巧與畫風，在藝術界獨樹一格，引領風潮，獲得業界衆多肯定與好評，作品獲邀於台灣及海峽兩岸各地展出個展與聯展逾百餘次。\r\n', '桃園國際機場股份有限公司', '桃園市337041桃園市大園區航站南路15號', '2025-01-06 00:00:00', '2025-04-30 00:00:00', '桃園機場第一航廈出境大廳北側展區', 0, 0, '無資料', 'https://www.facebook.com/share/p/12Cpuk2RXpC/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台灣蠟筆藝術之美-王建民 Jam-Min Wang蠟筆王', `description`='【台灣蠟筆藝術之美】\r\n一本初心，不斷追尋開拓蠟筆的新藝境\r\n丨展覽時間丨2025/01～2025/04\r\n丨展覽地點丨桃園機場第一航廈3F出境大廳北側展廳\r\n丨合作單位丨桃園國際機場股份有限公司、新東陽股份有限公司\r\n丨策展單位丨右岱藝術\r\n丨策 展 人丨徐予紅\r\n\r\n丨機場展覽、專業展覽規畫、展覽合作、媒體暨商品銷售窗口丨\r\n聯絡人：徐予紅 0975-638759; \r\n(LINE ID:yuhung1108)\r\nMail：uday.tpe@gmail.com\r\n＃右岱藝術 ＃策展 ＃藝術經紀\r\n\r\n展覽藝術家\r\n王建民Jam-Min Wang (蠟筆王)\r\n【現    任】\r\n文化大學推廣教育部/ 講師\r\n蘆洲林建生圖書館/ 講師\r\n中華文創學會/ 常務理事\r\n中華國際策展經紀交流協會/ 常務理事\r\n台灣國際藝術家協會/ 常務理事\r\n兒童藝術文教基金會/ 董事\r\n【重要著作】\r\n不可思議的蠟筆魔法書 (蠟筆畫技巧專書) \r\n\r\n王建民，又稱台灣蠟筆王，台灣知名蠟筆畫藝術家，獨創「板雕蠟彩」藝術，作品於海峽兩岸各地展覽，並將其蠟筆創作授權開發許多文創商品，號稱「蠟筆達人」，「台灣蠟筆藝術第一人」。\r\n蠟筆王從事藝術創作，始終堅持以蠟筆藝術為創作核心，獨創「板雕蠟彩」藝術，並堅持以蠟筆藝術為創作核心，不斷創新繪畫技巧與畫風，在藝術界獨樹一格，引領風潮，獲得業界衆多肯定與好評，作品獲邀於台灣及海峽兩岸各地展出個展與聯展逾百餘次。\r\n', `organizer`='桃園國際機場股份有限公司', `address`='桃園市337041桃園市大園區航站南路15號', `start_date`='2025-01-06 00:00:00', `