INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781893126b32458d43635b7', '臺灣客家茶文化館特展 - 花與茶圓舞曲', '花與茶的結合，是一場古老而續寫的圓舞曲。\r\n在這場旋律中，花的香氣與茶的味道編織出一段段難忘的故事，故事中充滿了文化、歷史和工藝的深沉。近年來，由於眾多茶品牌的持續推廣，東方窨製花茶再次贏得了大眾的喜愛，但它與西方花茶有著怎樣的區別呢？\r\n此次花與茶圓舞曲特展，除了介紹富含深厚文化背景以及製作工藝的東方窨花茶，還有富含豐富詩意的西方花茶聞香之樹，一起體驗一場東西方融合的嗅覺饗宴!', '臺灣客家茶文化館', '桃園市龍潭區高原路768號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺灣客家茶文化館', 24.85064954, 121.2117877, '一般票價+160;優惠票+80', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺灣客家茶文化館特展 - 花與茶圓舞曲', `description`='花與茶的結合，是一場古老而續寫的圓舞曲。\r\n在這場旋律中，花的香氣與茶的味道編織出一段段難忘的故事，故事中充滿了文化、歷史和工藝的深沉。近年來，由於眾多茶品牌的持續推廣，東方窨製花茶再次贏得了大眾的喜愛，但它與西方花茶有著怎樣的區別呢？\r\n此次花與茶圓舞曲特展，除了介紹富含深厚文化背景以及製作工藝的東方窨花茶，還有富含豐富詩意的西方花茶聞香之樹，一起體驗一場東西方融合的嗅覺饗宴!', `organizer`='臺灣客家茶文化館', `address`='桃園市龍潭區高原路768號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺灣客家茶文化館', `latitude`=24.85064954, `longitude`=121.2117877, `ticket_price`='一般票價+160;優惠票+80', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781893926b32458d43635b9', '「孩好有你」出生禮俗展', '本所收集各式抓周服飾及用品展出，讓民眾於洽公之餘參觀，讓您瞭解出生傳統禮俗，歡迎踴躍參觀。', '桃園市八德區戶政事務所', '桃園市八德區', '2025-01-02 00:00:00', '2025-12-31 00:00:00', '八德區（桃園市）=', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「孩好有你」出生禮俗展', `description`='本所收集各式抓周服飾及用品展出，讓民眾於洽公之餘參觀，讓您瞭解出生傳統禮俗，歡迎踴躍參觀。', `organizer`='桃園市八德區戶政事務所', `address`='桃園市八德區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='八德區（桃園市）=', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781893d26b32458d43635ba', '散彩重序：《眷村色彩散策》衍生設計徵選成果展', '眷村色彩採集計畫於2020-2022年期間，調查總計30處全臺尚未修復的眷村，透過田野調查、訪談等方法，將眷村建築、自然與人文歷史元素轉化眷村文化想像，接著2023年出版《眷村色彩散策－走讀全臺30眷村地景》一書，紀錄了全臺30處眷村具有地方識別性的450筆色彩元素。並於2024年舉辦【散彩重序：《眷村色彩散策》衍生設計徵選競賽】，藉由參賽者的視角呈現對於眷村色彩、文化的想像，本檔展覽將展出入圍決選之參賽者的作品提案，期待與觀者一起激發更多創意火花。', '桃園市政府文化局', '桃園市龜山區大同路138巷', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '憲光二村眷村文化園區', 25.02417472, 121.3569265, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='散彩重序：《眷村色彩散策》衍生設計徵選成果展', `description`='眷村色彩採集計畫於2020-2022年期間，調查總計30處全臺尚未修復的眷村，透過田野調查、訪談等方法，將眷村建築、自然與人文歷史元素轉化眷村文化想像，接著2023年出版《眷村色彩散策－走讀全臺30眷村地景》一書，紀錄了全臺30處眷村具有地方識別性的450筆色彩元素。並於2024年舉辦【散彩重序：《眷村色彩散策》衍生設計徵選競賽】，藉由參賽者的視角呈現對於眷村色彩、文化的想像，本檔展覽將展出入圍決選之參賽者的作品提案，期待與觀者一起激發更多創意火花。', `organizer`='桃園市政府文化局', `address`='桃園市龜山區大同路138巷', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='憲光二村眷村文化園區', `latitude`=25.02417472, `longitude`=121.3569265, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781893f26b32458d43635bb', '「花時間遊藝」張素秋油畫創作個展', '桃園市政府法務局於藝文走廊定期展出畫作，強化藝術連結，增進人文氣息。', '桃園市政府法務局', '桃園市桃園區縣府路1號', '2025-01-02 00:00:00', '2025-03-31 00:00:00', '桃園市政府', 24.9929026, 121.3010601, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「花時間遊藝」張素秋油畫創作個展', `description`='桃園市政府法務局於藝文走廊定期展出畫作，強化藝術連結，增進人文氣息。', `organizer`='桃園市政府法務局', `address`='桃園市桃園區縣府路1號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='桃園市政府', `latitude`=24.9929026, `longitude`=121.3010601, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894026b32458d43635bc', '原住民族環境教育常設展', '環境教育是強調人與其環境關係的一種教育過程。藉由著教育過程，使全民獲得保護及改善環境所需之倫理、知識、態度、技能及價值觀。其目的在發展、瞭解和重視介於人類文化及其生物、物理環境間合理的對待關係。桃園市原住民族文化會館為「文化保存與推廣」台灣原住民族文化，透過展覽結合傳統與現代跟在地生活及藝術，傳遞環境生態及生活知識，是認識原住民族知識重要的窗口，更是學習體驗原住民文化的重要場域。從館內專業的導覽解說員，進而從原住民知識中建立珍惜環境生態的環保觀念，都能讓參與民眾感受到原住民族人與文化及環境三者彼此間緊密的關係，並兼顧文化教育的意義，更成為學習與體驗原住民族文化的重要設施場所。\r\n展場規劃-\r\n1.互動教學區\r\n2.影音休憩區\r\n3.可變換互動教具', '桃園市政府原住民族行政局', '桃園市大溪區員林路一段29巷101號', '2025-01-02 00:00:00', '2025-12-31 00:00:00', '桃園市原住民族文化會館', 24.896414, 121.2822299, '無資料', 'https://walkinto.in/tour/WJ5pxC97IHb1xc6lR97LB', '[]') ON DUPLICATE KEY UPDATE `activity_name`='原住民族環境教育常設展', `description`='環境教育是強調人與其環境關係的一種教育過程。藉由著教育過程，使全民獲得保護及改善環境所需之倫理、知識、態度、技能及價值觀。其目的在發展、瞭解和重視介於人類文化及其生物、物理環境間合理的對待關係。桃園市原住民族文化會館為「文化保存與推廣」台灣原住民族文化，透過展覽結合傳統與現代跟在地生活及藝術，傳遞環境生態及生活知識，是認識原住民族知識重要的窗口，更是學習體驗原住民文化的重要場域。從館內專業的導覽解說員，進而從原住民知識中建立珍惜環境生態的環保觀念，都能讓參與民眾感受到原住民族人與文化及環境三者彼此間緊密的關係，並兼顧文化教育的意義，更成為學習與體驗原住民族文化的重要設施場所。\r\n展場規劃-\r\n1.互動教學區\r\n2.影音休憩區\r\n3.可變換互動教具', `organizer`='桃園市政府原住民族行政局', `address`='桃園市大溪區員林路一段29巷101號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='桃園市原住民族文化會館', `latitude`=24.896414, `longitude`=121.2822299, `ticket_price`='無資料', `source_url`='https://walkinto.in/tour/WJ5pxC97IHb1xc6lR97LB', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894126b32458d43635bd', '桃園市土地公文化館常設展-201兒童互動空間', '201兒童互動空間以親子互動遊戲為主題，透過多媒體小遊戲、主題繪本閱讀、文創商品多樣選擇，讓小朋友動手操作學習，從遊戲中了解土地公及祭祀的小知識。', '財團法人桃園市文化基金會', '桃園市桃園區三民路一段100號', '2025-01-02 00:00:00', '2025-12-31 00:00:00', '桃園市土地公文化館', 24.998189, 121.321246, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園市土地公文化館常設展-201兒童互動空間', `description`='201兒童互動空間以親子互動遊戲為主題，透過多媒體小遊戲、主題繪本閱讀、文創商品多樣選擇，讓小朋友動手操作學習，從遊戲中了解土地公及祭祀的小知識。', `organizer`='財團法人桃園市文化基金會', `address`='桃園市桃園區三民路一段100號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='桃園市土地公文化館', `latitude`=24.998189, `longitude`=121.321246, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894126b32458d43635be', '桃園市土地公文化館常設展-301特色廟宇與造像藝術', '土地公信仰遍布全臺各具特色，從早期的一顆石頭、三粒石到小祠或輝煌的廟宇，形成各具特色的廟宇與各具特色的土地公婆和虎爺造像，普遍的信仰中蘊含著豐富的工藝藝術，邀您一起來欣賞。', '財團法人桃園市文化基金會', '桃園市桃園區三民路一段100號', '2025-01-02 00:00:00', '2025-12-31 00:00:00', '桃園市土地公文化館', 24.998189, 121.321246, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園市土地公文化館常設展-301特色廟宇與造像藝術', `description`='土地公信仰遍布全臺各具特色，從早期的一顆石頭、三粒石到小祠或輝煌的廟宇，形成各具特色的廟宇與各具特色的土地公婆和虎爺造像，普遍的信仰中蘊含著豐富的工藝藝術，邀您一起來欣賞。', `organizer`='財團法人桃園市文化基金會', `address`='桃園市桃園區三民路一段100號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='桃園市土地公文化館', `latitude`=24.998189, `longitude`=121.321246, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894126b32458d43635bf', '桃園市土地公文化館常設展-302土地公節日慶典與科儀活動', '土地公祭祀活動及慶典科儀，除了日常性的固定祭祀，較為人熟知的有做牙、中元普渡等，本展間展示慶典科儀使用的祭祀用品、南北管演奏樂器、重要儀式中的三獻禮，道教信仰相關產業物品展示如製香、道袍，另有布袋戲及歌仔戲台提供民眾體驗、認識民間謝神文化。', '財團法人桃園市文化基金會', '桃園市桃園區三民路一段100號', '2025-01-02 00:00:00', '2025-12-31 00:00:00', '桃園市土地公文化館', 24.998189, 121.321246, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園市土地公文化館常設展-302土地公節日慶典與科儀活動', `description`='土地公祭祀活動及慶典科儀，除了日常性的固定祭祀，較為人熟知的有做牙、中元普渡等，本展間展示慶典科儀使用的祭祀用品、南北管演奏樂器、重要儀式中的三獻禮，道教信仰相關產業物品展示如製香、道袍，另有布袋戲及歌仔戲台提供民眾體驗、認識民間謝神文化。', `organizer`='財團法人桃園市文化基金會', `address`='桃園市桃園區三民路一段100號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='桃園市土地公文化館', `latitude`=24.998189, `longitude`=121.321246, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894126b32458d43635c0', '桃園市土地公文化館常設展-303海外土地公信仰', '土地神為華人社會共同的重要信仰對象，對土地神的崇敬處處可見，在各地的稱號有福德正神、大伯公、土地公等，各有其意義及脈絡，但對於土地神的虔誠信仰是相同的。本展間以實境呈現海外華人區大陸、新加坡、澳門、香港、馬來西亞等，在土地神信仰的不同祭祀情境，並藉由多媒體、展示品了解不同地區土地神信仰的特色祭祀方式及節慶。', '財團法人桃園市文化基金會', '桃園市桃園區三民路一段100號', '2025-01-02 00:00:00', '2025-12-31 00:00:00', '桃園市土地公文化館', 24.998189, 121.321246, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園市土地公文化館常設展-303海外土地公信仰', `description`='土地神為華人社會共同的重要信仰對象，對土地神的崇敬處處可見，在各地的稱號有福德正神、大伯公、土地公等，各有其意義及脈絡，但對於土地神的虔誠信仰是相同的。本展間以實境呈現海外華人區大陸、新加坡、澳門、香港、馬來西亞等，在土地神信仰的不同祭祀情境，並藉由多媒體、展示品了解不同地區土地神信仰的特色祭祀方式及節慶。', `organizer`='財團法人桃園市文化基金會', `address`='桃園市桃園區三民路一段100號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='桃園市土地公文化館', `latitude`=24.998189, `longitude`=121.321246, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894226b32458d43635c1', '倒映的國度-台韓國際版畫交流展', '透過版畫的藝術形式，轉譯兩地藝術家對自身文化的反思與對話。 臺灣版畫交流協會理事長林信源表示，此次展覽以「倒映的國度」為主題，創作出反映兩地藝術家對於此議題的論述以及版畫媒材實驗探索，呈現多元性樣貌，誠摯邀請喜愛藝術的朋友們前來觀展。 策展人張瀞予談到，此次「倒映的國度」透過版畫藝術探索兩地歷史地理、文化、社會之間的映射關係，展覽分為三大主題區域：「倒映」、「凝視」及「共振」，每一部分都將展示藝術家們的深刻體悟與展現。 高雄市文化中心邀請所有藝術愛好者和公眾人士踴躍參觀，共同體驗版畫藝術的魅力與深度。\r\n開幕時間: 2025年3月8日下午2:00', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-03-07 00:00:00', '2025-03-18 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='倒映的國度-台韓國際版畫交流展', `description`='透過版畫的藝術形式，轉譯兩地藝術家對自身文化的反思與對話。 臺灣版畫交流協會理事長林信源表示，此次展覽以「倒映的國度」為主題，創作出反映兩地藝術家對於此議題的論述以及版畫媒材實驗探索，呈現多元性樣貌，誠摯邀請喜愛藝術的朋友們前來觀展。 策展人張瀞予談到，此次「倒映的國度」透過版畫藝術探索兩地歷史地理、文化、社會之間的映射關係，展覽分為三大主題區域：「倒映」、「凝視」及「共振」，每一部分都將展示藝術家們的深刻體悟與展現。 高雄市文化中心邀請所有藝術愛好者和公眾人士踴躍參觀，共同體驗版畫藝術的魅力與深度。\r\n開幕時間: 2025年3月8日下午2:00', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-18 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894226b32458d43635c3', '無資料', '在寒假得時候，雄中雄女民吉合辦寒發，這是難得的表演機會！將半年以來的練習成果呈現出來。\r\n演出形式2/22(六)將由115、116級雄中雄女熱門音樂社社員輪流上台演出，每團表演一首歌，活動時長約為四至五小時。2/23(日)將由115、116級雄中雄女民謠吉他社社員輪流上台演出，每團表演一首歌，活動時長約為四至五小時。', '高雄市政府文化局', '高雄市鹽埕區8鄰大勇路1號', '高雄市駁二藝術特區', 22.6199666, 120.2816536, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='在寒假得時候，雄中雄女民吉合辦寒發，這是難得的表演機會！將半年以來的練習成果呈現出來。\r\n演出形式2/22(六)將由115、116級雄中雄女熱門音樂社社員輪流上台演出，每團表演一首歌，活動時長約為四至五小時。2/23(日)將由115、116級雄中雄女民謠吉他社社員輪流上台演出，每團表演一首歌，活動時長約為四至五小時。', `organizer`='高雄市政府文化局', `address`='高雄市鹽埕區8鄰大勇路1號', `location`='高雄市駁二藝術特區', `latitude`=22.6199666, `longitude`=120.2816536, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894326b32458d43635ca', '《舞，經典》', '在《舞，經典》作品重現的創作中，我們如同穿梭於時間的隧道，將過去的美好再度帶入眼前。經典作品中流露出的情感、思想與藝術魅力，透過當代的視角與技術，重新詮釋，讓我們能夠感受到那份久違的共鳴。\r\n重現的過程是一場深刻的對話，不僅是對經典的致敬，也是對自身藝術靈魂的探索。我們以創新的手法，將現代的元素融入，讓經典的故事在新的背景下再次閃耀。在這份重現的旅程中，情感的共鳴變得更加深刻。喜悅、悲傷、渴望與失落，如影隨形，交錯出一幅幅充滿感情色彩的畫面。每一次展現都像是一場時代的交融，讓觀者不僅能碰觸到歷史的脈動，還能在其中找到自己的影子。\r\n作為創作者，我們懷著敬意與熱情，將經典的美獻給當下的世界，讓那份永恆的感情在新的時空中延續。這是一次心靈的拼接與重塑，是對藝術、時間與情感的深刻致敬。', '高雄市政府文化局', '高雄市鹽埕區8鄰大勇路1號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '高雄市駁二藝術特區', 22.6199666, 120.2816536, '無資料', 'https://www.facebook.com/groups/144538425628482/user/100064015326447', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《舞，經典》', `description`='在《舞，經典》作品重現的創作中，我們如同穿梭於時間的隧道，將過去的美好再度帶入眼前。經典作品中流露出的情感、思想與藝術魅力，透過當代的視角與技術，重新詮釋，讓我們能夠感受到那份久違的共鳴。\r\n重現的過程是一場深刻的對話，不僅是對經典的致敬，也是對自身藝術靈魂的探索。我們以創新的手法，將現代的元素融入，讓經典的故事在新的背景下再次閃耀。在這份重現的旅程中，情感的共鳴變得更加深刻。喜悅、悲傷、渴望與失落，如影隨形，交錯出一幅幅充滿感情色彩的畫面。每一次展現都像是一場時代的交融，讓觀者不僅能碰觸到歷史的脈動，還能在其中找到自己的影子。\r\n作為創作者，我們懷著敬意與熱情，將經典的美獻給當下的世界，讓那份永恆的感情在新的時空中延續。這是一次心靈的拼接與重塑，是對藝術、時間與情感的深刻致敬。', `organizer`='高雄市政府文化局', `address`='高雄市鹽埕區8鄰大勇路1號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='高雄市駁二藝術特區', `latitude`=22.6199666, `longitude`=120.2816536, `ticket_price`='無資料', `source_url`='https://www.facebook.com/groups/144538425628482/user/100064015326447', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894326b32458d43635d4', '「剖木成材」INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894326b32458d43635d5', '「大溪知己」大溪創生館常設展', '認識大溪人、參與大溪人、成為大溪人\r\n——歡迎登入「大溪知己」展！\r\n「知己」一詞，可以指「了解自己的好友」，也可以是「認知自己」：建立對事物、環境⋯⋯等的認同、並發展自我的過程。\r\n展覽名為「大溪知己」，希望透過更多元、更鮮活的方式，讓每個到來的訪客，都能看見不同樣貌與視角的大溪。透過生態博物館思維，打破傳統的展覽形式，提供訪客前所未有的觀覽體驗：在展中，你可以認識當代大溪人，也能看見大溪的前世今生、發展脈絡，甚至有機會與AI科技互動，記錄、想像與創造大溪的未來，進階為大溪的一份子。\r\n歡迎來到「大溪知己」展，祝福你在大溪找到知己，也變成大溪的知己！\r\n\r\n知己好友\r\n如何交到大溪好朋友？\r\n\r\n——求認識！求帶路！在地知己舉個手！\r\n\r\n造訪一座城市，沒當地朋友帶路不行的！\r\n\r\n不過，這座城市有9萬多位居民，要怎麼開始打聽？\r\n\r\n為你介紹這群「大溪好朋友」，他們是木藝生態博物館最重要的共學夥伴——他們熱愛大溪，也熱愛分享與呈現這裡的生活文化；以在地人的觀點，抱著熱情持續深入挖掘，呈現出各種大溪特色的生活片段，十足熱血，充滿魅力！\r\n\r\n以下將現場交給他們，聽聽他們在大溪生活的各種故事！\r\n\r\n知己履歷\r\n是什麼讓大溪變成大溪？\r\n\r\n——每一個決定的當下，都是促成大溪改變的轉折點。\r\n\r\n一百年、十年、一個月、一分鐘⋯⋯你我認識的「大溪」，源於許多關鍵人事物的塑造與累積。這些事件在大溪演進的時空裡，各自展現了它們的影響力。\r\n\r\n本區帶你一探大溪的「景物改變大事紀」：說明形塑大溪的關鍵要素與時刻，並以景物今昔對照的紀錄，一起見證百餘年來的大溪改變。\r\n\r\n成為知己\r\n有沒有跟大溪更熟悉的方法？\r\n\r\n——成為「大溪好朋友」三部曲！\r\n\r\n無論是讓訪客更認識大溪，或是讓在地人更了解家鄉⋯⋯對於大溪一切的採集、整理、記錄、詮釋與學習，都是必經的過程。\r\n\r\n想要和這座老城更加熟悉，可以試試本區的三個步驟方法學：記錄、連結與觸發、創造。\r\n\r\n依序體驗，不只你將會有意想不到的收穫，大溪也會！\r\n\r\n知己PLUS\r\n番外篇：目睹他們正在創造的大溪！\r\n\r\n現今的大溪，「創造」依舊是進行式！\r\n\r\n這些大溪知己，是「街角館」的館長、也是與木藝博物館共學的夥伴。\r\n\r\n是友善的大溪好朋友，也是採取行動讓大溪發生改變的實踐家。\r\n\r\n本區展示他們的部分作品，藉由這些創作，你將更能體會大溪生生不息的文化行動，與永續的創造力，始終正在進行中！\r\n\r\n讓我們隨著展覽，一起走進大溪的製材廠，探索從原木到木材的轉變過程。透過展覽五個主題：「山林原木」、「選木取材」、「乾燥成材」、「匠心成器」及「製材產業的嶄新可能」，看見製材師傅們挑選剖切原木、打磨鋸帶、乾燥成材的職人精神，重新認識生活中無所不在的木材。', '桃園市立大溪木藝生態博物館', '桃園市大溪區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '大溪區（桃園市）=', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「大溪知己」大溪創生館常設展', `description`='認識大溪人、參與大溪人、成為大溪人\r\n——歡迎登入「大溪知己」展！\r\n「知己」一詞，可以指「了解自己的好友」，也可以是「認知自己」：建立對事物、環境⋯⋯等的認同、並發展自我的過程。\r\n展覽名為「大溪知己」，希望透過更多元、更鮮活的方式，讓每個到來的訪客，都能看見不同樣貌與視角的大溪。透過生態博物館思維，打破傳統的展覽形式，提供訪客前所未有的觀覽體驗：在展中，你可以認識當代大溪人，也能看見大溪的前世今生、發展脈絡，甚至有機會與AI科技互動，記錄、想像與創造大溪的未來，進階為大溪的一份子。\r\n歡迎來到「大溪知己」展，祝福你在大溪找到知己，也變成大溪的知己！\r\n\r\n知己好友\r\n如何交到大溪好朋友？\r\n\r\n——求認識！求帶路！在地知己舉個手！\r\n\r\n造訪一座城市，沒當地朋友帶路不行的！\r\n\r\n不過，這座城市有9萬多位居民，要怎麼開始打聽？\r\n\r\n為你介紹這群「大溪好朋友」，他們是木藝生態博物館最重要的共學夥伴——他們熱愛大溪，也熱愛分享與呈現這裡的生活文化；以在地人的觀點，抱著熱情持續深入挖掘，呈現出各種大溪特色的生活片段，十足熱血，充滿魅力！\r\n\r\n以下將現場交給他們，聽聽他們在大溪生活的各種故事！\r\n\r\n知己履歷\r\n是什麼讓大溪變成大溪？\r\n\r\n——每一個決定的當下，都是促成大溪改變的轉折點。\r\n\r\n一百年、十年、一個月、一分鐘⋯⋯你我認識的「大溪」，源於許多關鍵人事物的塑造與累積。這些事件在大溪演進的時空裡，各自展現了它們的影響力。\r\n\r\n本區帶你一探大溪的「景物改變大事紀」：說明形塑大溪的關鍵要素與時刻，並以景物今昔對照的紀錄，一起見證百餘年來的大溪改變。\r\n\r\n成為知己\r\n有沒有跟大溪更熟悉的方法？\r\n\r\n——成為「大溪好朋友」三部曲！\r\n\r\n無論是讓訪客更認識大溪，或是讓在地人更了解家鄉⋯⋯對於大溪一切的採集、整理、記錄、詮釋與學習，都是必經的過程。\r\n\r\n想要和這座老城更加熟悉，可以試試本區的三個步驟方法學：記錄、連結與觸發、創造。\r\n\r\n依序體驗，不只你將會有意想不到的收穫，大溪也會！\r\n\r\n知己PLUS\r\n番外篇：目睹他們正在創造的大溪！\r\n\r\n現今的大溪，「創造」依舊是進行式！\r\n\r\n這些大溪知己，是「街角館」的館長、也是與木藝博物館共學的夥伴。\r\n\r\n是友善的大溪好朋友，也是採取行動讓大溪發生改變的實踐家。\r\n\r\n本區展示他們的部分作品，藉由這些創作，你將更能體會大溪生生不息的文化行動，與永續的創造力，始終正在進行中！\r\n\r\n讓我們隨著展覽，一起走進大溪的製材廠，探索從原木到木材的轉變過程。透過展覽五個主題：「山林原木」、「選木取材」、「乾燥成材」、「匠心成器」及「製材產業的嶄新可能」，看見製材師傅們挑選剖切原木、打磨鋸帶、乾燥成材的職人精神，重新認識生活中無所不在的木材。', `organizer`='桃園市立大溪木藝生態博物館', `address`='桃園市大溪區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='大溪區（桃園市）=', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894326b32458d43635d7', '「尋找追夢人」鳳飛飛故事館常設展', '大溪出生的鳳飛飛，一生勇敢追夢，也愛鄉愛土，曾說過大溪是她最愛的地方，最終也長眠於此。\r\n\r\n鳳飛飛故事館以其膾炙人口的歌曲「追夢人」為構想，策劃常設展「尋找追夢人」，延伸鳳飛飛勇於追夢的典範，串連在地職人精神，並以「鳳飛大溪 地方再生」為目標，從探索鳳飛飛在大溪的生活軌跡及人文故事，連結大溪人文地景資源，設計鳳飛飛走讀地圖，發揮生態博物館特色。\r\n\r\n鳳飛飛故事館「尋找追夢人」常設展共分五大展區，依據鳳飛飛追夢的人生及對臺灣歌謠的貢獻，以其名曲「追夢人」為點題，5大展區主題包含：\r\n一、「飛：我們大溪女兒鳳飛飛」\r\n二、「響：鳳飛飛的追夢路」\r\n三、「虹：如彩虹般的專輯產出」\r\n四、「追：屬於我們與鳳飛飛的美好年代」\r\n五、「愛：取之社會、用之社會的大愛」區。 \r\n展館內典藏播放175首鳳飛飛歌曲，完整呈現她的音樂史，也反映她對臺灣音樂發展重要貢獻。', '桃園市立大溪木藝生態博物館', '桃園市大溪區普濟路5號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '桃園市立大溪木藝生態博物館-鳳飛飛故事館', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「尋找追夢人」鳳飛飛故事館常設展', `description`='大溪出生的鳳飛飛，一生勇敢追夢，也愛鄉愛土，曾說過大溪是她最愛的地方，最終也長眠於此。\r\n\r\n鳳飛飛故事館以其膾炙人口的歌曲「追夢人」為構想，策劃常設展「尋找追夢人」，延伸鳳飛飛勇於追夢的典範，串連在地職人精神，並以「鳳飛大溪 地方再生」為目標，從探索鳳飛飛在大溪的生活軌跡及人文故事，連結大溪人文地景資源，設計鳳飛飛走讀地圖，發揮生態博物館特色。\r\n\r\n鳳飛飛故事館「尋找追夢人」常設展共分五大展區，依據鳳飛飛追夢的人生及對臺灣歌謠的貢獻，以其名曲「追夢人」為點題，5大展區主題包含：\r\n一、「飛：我們大溪女兒鳳飛飛」\r\n二、「響：鳳飛飛的追夢路」\r\n三、「虹：如彩虹般的專輯產出」\r\n四、「追：屬於我們與鳳飛飛的美好年代」\r\n五、「愛：取之社會、用之社會的大愛」區。 \r\n展館內典藏播放175首鳳飛飛歌曲，完整呈現她的音樂史，也反映她對臺灣音樂發展重要貢獻。', `organizer`='桃園市立大溪木藝生態博物館', `address`='桃園市大溪區普濟路5號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='桃園市立大溪木藝生態博物館-鳳飛飛故事館', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894326b32458d43635d8', '「開箱大溪」常設展', '「開箱大溪」，看見大溪如何發展、大溪人如何經營地方的故事，從個人、家族或不同組織百年來發展及經營地方的角度切入，帶領大家逐步認識大溪土地與人的故事。大溪是在現地環境中展演生活的博物館，走進大溪就是走進博物館。\r\n大溪自清代起，基於大漢溪河運重要內陸河港的地理優勢，成為重要貨物集散地，成為國際貿易網絡的一環，並造就了桃園地區最早的熱鬧市街。百餘年來，市街文化累積豐厚的有形與無形文化內涵。「大溪歷史館」自2016年開館，帶領觀眾綜覽大溪產業、社會民俗，敘說大溪人的生活與歷史，2023年全面更新展示，增補歷年所持續累積的研究成果，結合在地展示資源，利用新媒體的展示手法，與觀眾一同開箱大溪的多元面貌。\r\n\r\n「開箱大溪」展覽共分為6大主題：「源自大漢溪」、「生根與拓展」、「樂為大溪事」、「大溪木發揚」、「共創共經營」與「大溪人說故事」其中亮點包括運用「機械木裝置結合投影」、「互動式觸控牆」、「情境投影」等進行展示設計，並有6部影片紀錄、5座擬真模型、11項實體及多媒體互動裝置及6處情境展示，將大溪豐富文獻資料、舊寫真圖像等知識內容，以全齡共融的方式親近觀眾，使艱澀的文史內容，不再只是帶有距離感的教材，為觀眾留下深刻印象。展場中並有多樣提供體驗木知識的互動教具，及大溪木藝師製作的各式實木椅供民眾試坐，感受大溪木藝的多樣風貌。', '桃園市立大溪木藝生態博物館', '桃園市大溪區普濟路17、19、21、23號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '桃園市立大溪木藝生態博物館-大溪歷史館', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「開箱大溪」常設展', `description`='「開箱大溪」，看見大溪如何發展、大溪人如何經營地方的故事，從個人、家族或不同組織百年來發展及經營地方的角度切入，帶領大家逐步認識大溪土地與人的故事。大溪是在現地環境中展演生活的博物館，走進大溪就是走進博物館。\r\n大溪自清代起，基於大漢溪河運重要內陸河港的地理優勢，成為重要貨物集散地，成為國際貿易網絡的一環，並造就了桃園地區最早的熱鬧市街。百餘年來，市街文化累積豐厚的有形與無形文化內涵。「大溪歷史館」自2016年開館，帶領觀眾綜覽大溪產業、社會民俗，敘說大溪人的生活與歷史，2023年全面更新展示，增補歷年所持續累積的研究成果，結合在地展示資源，利用新媒體的展示手法，與觀眾一同開箱大溪的多元面貌。\r\n\r\n「開箱大溪」展覽共分為6大主題：「源自大漢溪」、「生根與拓展」、「樂為大溪事」、「大溪木發揚」、「共創共經營」與「大溪人說故事」其中亮點包括運用「機械木裝置結合投影」、「互動式觸控牆」、「情境投影」等進行展示設計，並有6部影片紀錄、5座擬真模型、11項實體及多媒體互動裝置及6處情境展示，將大溪豐富文獻資料、舊寫真圖像等知識內容，以全齡共融的方式親近觀眾，使艱澀的文史內容，不再只是帶有距離感的教材，為觀眾留下深刻印象。展場中並有多樣提供體驗木知識的互動教具，及大溪木藝師製作的各式實木椅供民眾試坐，感受大溪木藝的多樣風貌。', `organizer`='桃園市立大溪木藝生態博物館', `address`='桃園市大溪區普濟路17、19、21、23號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='桃園市立大溪木藝生態博物館-大溪歷史館', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894326b32458d43635d9', '「大溪有緣客－客家文化現蹤」主題特展', '本次展覽從客家文化歷史的視角下，探索漳州移民開墾大溪的歷程，以及客家族群在地的淵源，並帶大家一同尋找大溪客家「或隱或顯」的人文地景，透過建築、信仰、產業、飲食等面向，進一步發現大溪多元族群交融之美。\r\n\r\n|第一展區｜發現大溪有緣客、溪客稀客從哪來\r\n|第二展區｜多族群開發大溪、溪客的宗教信仰\r\n|第三展區｜建築中的客家事、客蹤旅行地圖', '桃園市立大溪木藝生態博物館', '桃園市大溪區9鄰月眉34號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '桃園市立大溪木藝生態博物館-國定古蹟李騰芳古宅', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「大溪有緣客－客家文化現蹤」主題特展', `description`='本次展覽從客家文化歷史的視角下，探索漳州移民開墾大溪的歷程，以及客家族群在地的淵源，並帶大家一同尋找大溪客家「或隱或顯」的人文地景，透過建築、信仰、產業、飲食等面向，進一步發現大溪多元族群交融之美。\r\n\r\n|第一展區｜發現大溪有緣客、溪客稀客從哪來\r\n|第二展區｜多族群開發大溪、溪客的宗教信仰\r\n|第三展區｜建築中的客家事、客蹤旅行地圖', `organizer`='桃園市立大溪木藝生態博物館', `address`='桃園市大溪區9鄰月眉34號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='桃園市立大溪木藝生態博物館-國定古蹟李騰芳古宅', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894426b32458d43635da', '李金興家族簡介暨生活情境常設展', '李家清代自福建省漳州府詔安縣，輾轉來到大溪月眉。家族經營「金興商號」，透過大漢溪水運之利，運輸米糧而致富，並以仁善之風聞名當世。\r\n李家子孫人才輩出，除大溪唯一文舉人李騰芳（1814-1879）外，本次亦展出臺灣國家棒球隊總教練李詩計（1911-1951）、助產婦暨大溪鎮民代表李宣（1916-1995）的故事。\r\n\r\n\r\n\r\n展覽分為「生活情境」與「家族簡介」兩大展區。「生活情境」展區依據李家故事陳設，重現世家大族的生活情景；「家族簡介」展區則以圖文展版、影音文物幫助觀眾快速掌握李家歷史，五大主題包含：\r\n\r\n一、李金興家族緣起\r\n二、棒球先驅李詩計\r\n三、大溪助產婦李宣\r\n四、古宅模型劇場\r\n五、建築之美', '桃園市立大溪木藝生態博物館', '桃園市大溪區9鄰月眉34號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '桃園市立大溪木藝生態博物館-國定古蹟李騰芳古宅', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='李金興家族簡介暨生活情境常設展', `description`='李家清代自福建省漳州府詔安縣，輾轉來到大溪月眉。家族經營「金興商號」，透過大漢溪水運之利，運輸米糧而致富，並以仁善之風聞名當世。\r\n李家子孫人才輩出，除大溪唯一文舉人李騰芳（1814-1879）外，本次亦展出臺灣國家棒球隊總教練李詩計（1911-1951）、助產婦暨大溪鎮民代表李宣（1916-1995）的故事。\r\n\r\n\r\n\r\n展覽分為「生活情境」與「家族簡介」兩大展區。「生活情境」展區依據李家故事陳設，重現世家大族的生活情景；「家族簡介」展區則以圖文展版、影音文物幫助觀眾快速掌握李家歷史，五大主題包含：\r\n\r\n一、李金興家族緣起\r\n二、棒球先驅李詩計\r\n三、大溪助產婦李宣\r\n四、古宅模型劇場\r\n五、建築之美', `organizer`='桃園市立大溪木藝生態博物館', `address`='桃園市大溪區9鄰月眉34號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='桃園市立大溪木藝生態博物館-國定古蹟李騰芳古宅', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894426b32458d43635db', '「大溪老厝邊」警察宿舍群生活故事常設展', '「大溪老厝邊-警察宿舍生活故事展」是一個充滿「家」與「人」元素的展覽。\r\n展覽位於保有生活氛圍的警察宿舍群中，透過警察、宿舍原住戶以及大溪鄰居的觀點，去看待大溪警察任務的多元性以及特殊性，以及與常民生活的鏈結，將口述回憶用活潑的插畫、影音以及裝置藝術等手法，帶領觀眾進入宿舍群的生活場景及精彩故事中。\r\n\r\n\r\n\r\n展覽區域分為彈藥庫「探索警物．警務」的前導故事動畫、歡迎廳的「厝邊警察任務中」、生活廳「厝邊警察的生活」，這樣的安排不只可以看到日本時期到戰後警政制度與聚落變遷，大溪警察五花八門的任務，更可看見宿舍群警察及家眷們與大溪人之間的緊密互動。', '桃園市立大溪木藝生態博物館', '桃園市大溪區普濟路13巷11、13、15號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '桃園市立大溪木藝生態博物館-工藝基地', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「大溪老厝邊」警察宿舍群生活故事常設展', `description`='「大溪老厝邊-警察宿舍生活故事展」是一個充滿「家」與「人」元素的展覽。\r\n展覽位於保有生活氛圍的警察宿舍群中，透過警察、宿舍原住戶以及大溪鄰居的觀點，去看待大溪警察任務的多元性以及特殊性，以及與常民生活的鏈結，將口述回憶用活潑的插畫、影音以及裝置藝術等手法，帶領觀眾進入宿舍群的生活場景及精彩故事中。\r\n\r\n\r\n\r\n展覽區域分為彈藥庫「探索警物．警務」的前導故事動畫、歡迎廳的「厝邊警察任務中」、生活廳「厝邊警察的生活」，這樣的安排不只可以看到日本時期到戰後警政制度與聚落變遷，大溪警察五花八門的任務，更可看見宿舍群警察及家眷們與大溪人之間的緊密互動。', `organizer`='桃園市立大溪木藝生態博物館', `address`='桃園市大溪區普濟路13巷11、13、15號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='桃園市立大溪木藝生態博物館-工藝基地', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894426b32458d43635dc', '親子小提琴學習營第25班', '為提升本市音樂素養並增進親子互動，透過生動活潑的教學內容：個別指導、親子團體合奏，\r\n以及精彩的音樂賞析等方式，在充滿歡樂的跳躍音符中，讓孩童的兒時回憶更加多彩多姿。', '高雄市立圖書館總館', '高雄市岡山區公園路2-1號', '2025-01-04 00:00:00', '2025-04-19 00:00:00', '高雄市立圖書館岡山分館', 22.797164, 120.29288, '--+4200', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='親子小提琴學習營第25班', `description`='為提升本市音樂素養並增進親子互動，透過生動活潑的教學內容：個別指導、親子團體合奏，\r\n以及精彩的音樂賞析等方式，在充滿歡樂的跳躍音符中，讓孩童的兒時回憶更加多彩多姿。', `organizer`='高雄市立圖書館總館', `address`='高雄市岡山區公園路2-1號', `start_date`='2025-01-04 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='高雄市立圖書館岡山分館', `latitude`=22.797164, `longitude`=120.29288, `ticket_price`='--+4200', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894426b32458d43635dd', '六廿四故事館常設展', '大溪普濟堂主祀關聖帝君，為在地居民重要的信仰。每年農曆六月廿四日是關聖帝君誕辰，以大溪普濟堂為核心，地方社頭、大溪民眾共同協力，舉辦慶典及遶境相關活動，熱鬧非凡有如「大溪人的第二個過年」。\r\n「大溪普濟堂關聖帝君聖誕慶典」俗稱「迎六月廿四」，於2011年指定登錄為桃園市無形文化資產，是大溪重要的民俗活動。而為籌備慶典發展出的社頭文化、地方人情故事，更是大溪人世代相傳的精神食糧。\r\n\r\n2021年，歷史建築「大溪農會倉庫」由鄭文燦市長定位並命名為「六廿四故事館」，加入大溪木藝生態博物館的館舍群，未來作為推動「迎六月廿四」慶典以及傳承、教育與體驗的共學空間。\r\n【常設展覽 特色藝陣跳起來】\r\n一樓將不定期換展介紹陣頭的入門知識與在地特色，首檔展覽必看重點：\r\n◆ 大溪共義團｜\r\n　1973年的「關平」、「周倉」將軍\r\n　(111年2月起為興安社關平周倉將軍)\r\n◆ 金鴻慈惠堂醒獅團｜\r\n　五虎將之一「趙雲獅」\r\n◆ 大溪農友團｜\r\n　「風雨雷電」四尊童仔\r\n\r\n現場還有由共義團成員自行製作的神龍，以及「童仔步跳舞機」，讓您跟著七星步跳起來！', '桃園市立大溪木藝生態博物館', '桃園市大溪區普濟路48號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '桃園市立大溪木藝生態博物館-六廿四故事館', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='六廿四故事館常設展', `description`='大溪普濟堂主祀關聖帝君，為在地居民重要的信仰。每年農曆六月廿四日是關聖帝君誕辰，以大溪普濟堂為核心，地方社頭、大溪民眾共同協力，舉辦慶典及遶境相關活動，熱鬧非凡有如「大溪人的第二個過年」。\r\n「大溪普濟堂關聖帝君聖誕慶典」俗稱「迎六月廿四」，於2011年指定登錄為桃園市無形文化資產，是大溪重要的民俗活動。而為籌備慶典發展出的社頭文化、地方人情故事，更是大溪人世代相傳的精神食糧。\r\n\r\n2021年，歷史建築「大溪農會倉庫」由鄭文燦市長定位並命名為「六廿四故事館」，加入大溪木藝生態博物館的館舍群，未來作為推動「迎六月廿四」慶典以及傳承、教育與體驗的共學空間。\r\n【常設展覽 特色藝陣跳起來】\r\n一樓將不定期換展介紹陣頭的入門知識與在地特色，首檔展覽必看重點：\r\n◆ 大溪共義團｜\r\n　1973年的「關平」、「周倉」將軍\r\n　(111年2月起為興安社關平周倉將軍)\r\n◆ 金鴻慈惠堂醒獅團｜\r\n　五虎將之一「趙雲獅」\r\n◆ 大溪農友團｜\r\n　「風雨雷電」四尊童仔\r\n\r\n現場還有由共義團成員自行製作的神龍，以及「童仔步跳舞機」，讓您跟著七星步跳起來！', `organizer`='桃園市立大溪木藝生態博物館', `address`='桃園市大溪區普濟路48號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='桃園市立大溪木藝生態博物館-六廿四故事館', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894426b32458d43635de', '主題書展「愛」無限', '不論你相不相信「愛」的存在，你一定同意每個人對「愛」都有不同的定義。這次書展，以愛為核心，展出多元書籍，無論是親情、友情、愛情，還是對生命與自然的愛，這些繪本將用細膩的畫風與感人的故事，讓每個人找到屬於自己的愛的定義。讓我們透過繪本，重新感受那份溫暖與感動！', '高雄市立圖書館總館', '高雄市杉林區5鄰山仙路75號', '2025-01-02 00:00:00', '2025-02-27 00:00:00', '高雄市立圖書館杉林分館', 22.976957, 120.543457, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='主題書展「愛」無限', `description`='不論你相不相信「愛」的存在，你一定同意每個人對「愛」都有不同的定義。這次書展，以愛為核心，展出多元書籍，無論是親情、友情、愛情，還是對生命與自然的愛，這些繪本將用細膩的畫風與感人的故事，讓每個人找到屬於自己的愛的定義。讓我們透過繪本，重新感受那份溫暖與感動！', `organizer`='高雄市立圖書館總館', `address`='高雄市杉林區5鄰山仙路75號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='高雄市立圖書館杉林分館', `latitude`=22.976957, `longitude`=120.543457, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894426b32458d43635df', '蛇麼樣，才叫長大？ 繪本主題書展', '當蛇蛻掉一層舊皮，代表牠長大了 那人類呢？是身體的發育？還是心靈的成熟？又有什麼可以證明自己長大了呢？本次書展透過精選的繪本，看著故事中的主角跨越一個個挑戰，從依賴到獨立、從迷茫到自信，像蛇一樣蛻變、長大、進化成更好的自己！新的一年，邀請各位大朋友小朋友、家長孩子，一起在書展中 發現屬於自己的成長蜕變～', '高雄市立圖書館總館', '高雄市甲仙區6鄰中山路48號', '2025-01-03 00:00:00', '2025-02-27 00:00:00', '高雄市立圖書館甲仙分館', 23.0837971, 120.5877319, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蛇麼樣，才叫長大？ 繪本主題書展', `description`='當蛇蛻掉一層舊皮，代表牠長大了 那人類呢？是身體的發育？還是心靈的成熟？又有什麼可以證明自己長大了呢？本次書展透過精選的繪本，看著故事中的主角跨越一個個挑戰，從依賴到獨立、從迷茫到自信，像蛇一樣蛻變、長大、進化成更好的自己！新的一年，邀請各位大朋友小朋友、家長孩子，一起在書展中 發現屬於自己的成長蜕變～', `organizer`='高雄市立圖書館總館', `address`='高雄市甲仙區6鄰中山路48號', `start_date`='2025-01-03 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='高雄市立圖書館甲仙分館', `latitude`=23.0837971, `longitude`=120.5877319, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894426b32458d43635e0', '感動蛇 | 高美特展', '2025乙巳蛇年，高雄市立美術館與學學文化創意基金會共同合作「藝起來學學」臺灣文化色彩美感教育計畫，邀請藝術家莊普創作「感動蛇」原型，靈感來自傳說中排灣族的祖先百步蛇，造型以四角柱為上段蛇身，梯形柱為蛇頭，傳達百步蛇的智慧與靈動，蛇身中段以狀似圍巾纏繞的趣味，連結圓柱狀的下段蛇身，象徵蛇既柔軟又祥瑞，擁有不斷蛻變及生命循環的力量，並邀請高雄市、屏東縣、嘉義縣、臺南市、臺東縣、澎湖縣共29所國中小學校教師，帶領學生運用代表各校的五個家鄉文化色彩，表達出在地的情感與認同。本展展出逾八百件「小感動蛇」彩繪作品，展現各校多元的色彩觀察及豐沛的創作能量。', '高雄市立美術館', '高雄市鼓山區6鄰美術館路80號', '2025-01-23 00:00:00', '2025-04-13 00:00:00', '高雄市立美術館', 22.6566968, 120.2865511, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='感動蛇 | 高美特展', `description`='2025乙巳蛇年，高雄市立美術館與學學文化創意基金會共同合作「藝起來學學」臺灣文化色彩美感教育計畫，邀請藝術家莊普創作「感動蛇」原型，靈感來自傳說中排灣族的祖先百步蛇，造型以四角柱為上段蛇身，梯形柱為蛇頭，傳達百步蛇的智慧與靈動，蛇身中段以狀似圍巾纏繞的趣味，連結圓柱狀的下段蛇身，象徵蛇既柔軟又祥瑞，擁有不斷蛻變及生命循環的力量，並邀請高雄市、屏東縣、嘉義縣、臺南市、臺東縣、澎湖縣共29所國中小學校教師，帶領學生運用代表各校的五個家鄉文化色彩，表達出在地的情感與認同。本展展出逾八百件「小感動蛇」彩繪作品，展現各校多元的色彩觀察及豐沛的創作能量。', `organizer`='高雄市立美術館', `address`='高雄市鼓山區6鄰美術館路80號', `start_date`='2025-01-23 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='高雄市立美術館', `latitude`=22.6566968, `longitude`=120.2865511, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894426b32458d43635e1', '抵抗的美學－李素貞個展', '抵抗，是李素貞創作的驅力。她以直覺本真抵抗傳統教條，以謎樣歧義抵抗單一框架，她更想藉由創作描繪出理想的社會圖像，在那裡，人類有免於恐懼的自由。李素貞藉由創作展開自我情感與社會溝通的辯證，在筆觸間摸索畫面結構與敘事的途徑，她抵抗技術化、寫實化，也難以妥協在一個穩定的狀態，拒絕美感的安撫，作品可能是畫不完的半成品，也是持續變化的生命體。 \r\n本次展覽包含「母性肉身」、「夾縫風雲」、「抵抗意志」三大主題，傳達對台灣社會的關懷，以及對戒嚴時代、烏俄戰爭、亞太政局的深刻省思。李素貞期冀藉由抵抗的美學，彰顯人性的尊嚴，鼓舞不屈的意志，堅毅面對這世間的瘡痍。', '高雄市立美術館', '高雄市鼓山區6鄰美術館路80號', '2025-01-11 00:00:00', '2025-03-02 00:00:00', '高雄市立美術館', 22.6566968, 120.2865511, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='抵抗的美學－李素貞個展', `description`='抵抗，是李素貞創作的驅力。她以直覺本真抵抗傳統教條，以謎樣歧義抵抗單一框架，她更想藉由創作描繪出理想的社會圖像，在那裡，人類有免於恐懼的自由。李素貞藉由創作展開自我情感與社會溝通的辯證，在筆觸間摸索畫面結構與敘事的途徑，她抵抗技術化、寫實化，也難以妥協在一個穩定的狀態，拒絕美感的安撫，作品可能是畫不完的半成品，也是持續變化的生命體。 \r\n本次展覽包含「母性肉身」、「夾縫風雲」、「抵抗意志」三大主題，傳達對台灣社會的關懷，以及對戒嚴時代、烏俄戰爭、亞太政局的深刻省思。李素貞期冀藉由抵抗的美學，彰顯人性的尊嚴，鼓舞不屈的意志，堅毅面對這世間的瘡痍。', `organizer`='高雄市立美術館', `address`='高雄市鼓山區6鄰美術館路80號', `start_date`='2025-01-11 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='高雄市立美術館', `latitude`=22.6566968, `longitude`=120.2865511, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894426b32458d43635e2', '陳正雄90大展－一位抽象畫家和他的收藏', '不僅是一位藝術家。陳正雄生涯中對藝術領域的貢獻絕非僅止於抽象繪畫，他是原住民與清朝服飾文物研究的學者藏家，同時也是抽象藝術理論撰寫的教育者，更是帶領臺灣藝術家們走向國際藝壇的重要推手。多重的身分讓陳正雄早早即開啟了當代在談論的「跨領域」，在藝術創作的理論與傳統收藏中，展現出他獨有的色彩跨界對話。\r\n \r\n從1966年便開始收藏臺灣原住民服飾與文物的陳正雄，作品中奔放的飽和色調及抽象線條，似乎都能從其藏品來延伸出創作上的投射。1993年在參觀北京故宮博物院、瀋陽故宮博物院及大英博物館的過程中，他被宮廷服飾之美所震攝，也因而興起對清代宮廷服飾的購藏與研究。在梳理陳正雄與他的收藏中，最讓人驚艷的是他的抒情抽象繪畫與藏品間的高度連結，色系的對應就宛如當代設計中的色域思維，不僅建構出陳正雄作品中自帶的時尚感，更觸及了藝術家本人對於跨領域的成就與貢獻。\r\n \r\n不僅如此，旅居巴黎的知名作家祖慰在為陳正雄撰寫傳記時即以《畫布上的歡樂頌》一書，來稱讚其所帶給觀者的喜悅，而筆觸中自然流露的音樂與流動性，讓陳正雄在創作的畫面中，皆染上四季的氛圍。於是，四時流轉，萬物生機交融於天地人間，無論市井喧囂亦或是內觀心性，總能適度展示出如春之新鬱、夏之嬌豔、秋之閑靜，或是冬之冷瑟的章節。\r\n \r\n回到《陳正雄90大展－抽象畫家和他的收藏》展覽中，這次高美館以陳正雄的收藏帶出創作中所蘊含的「文化色彩」，我們不僅能從原民藏品中的海洋性，直接投射到陳正雄抽象繪畫中的「抒情海洋」，更能在他的《窗》與《數位空間》等系列作品中，看見書法與刺繡服飾間的線條呼應，他巧妙地以色彩突圍了東方元素，但卻在畫面中同時融合了西方抽象的精粹，就如同劉禹錫《董氏武砬集記》所提出的「境生子象外」一說：或許在我們體會「意境」的當下，感受到的正是陳正雄在創作上呈現出如史記的磅礡，但心領神會後，卻又能從其中看見被列傳所點綴出的璀璨時代。　', '高雄市立美術館', '高雄市鼓山區6鄰美術館路80號', '2025-01-25 00:00:00', '2025-05-11 00:00:00', '高雄市立美術館', 22.6566968, 120.2865511, '無資料', 'https://www.kmfa.gov.tw/exhibitiondetailc001100.aspx?Cond=7d76f82c-5ea4-4db0-a1a0-c7b97f7baf31', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陳正雄90大展－一位抽象畫家和他的收藏', `description`='不僅是一位藝術家。陳正雄生涯中對藝術領域的貢獻絕非僅止於抽象繪畫，他是原住民與清朝服飾文物研究的學者藏家，同時也是抽象藝術理論撰寫的教育者，更是帶領臺灣藝術家們走向國際藝壇的重要推手。多重的身分讓陳正雄早早即開啟了當代在談論的「跨領域」，在藝術創作的理論與傳統收藏中，展現出他獨有的色彩跨界對話。\r\n \r\n從1966年便開始收藏臺灣原住民服飾與文物的陳正雄，作品中奔放的飽和色調及抽象線條，似乎都能從其藏品來延伸出創作上的投射。1993年在參觀北京故宮博物院、瀋陽故宮博物院及大英博物館的過程中，他被宮廷服飾之美所震攝，也因而興起對清代宮廷服飾的購藏與研究。在梳理陳正雄與他的收藏中，最讓人驚艷的是他的抒情抽象繪畫與藏品間的高度連結，色系的對應就宛如當代設計中的色域思維，不僅建構出陳正雄作品中自帶的時尚感，更觸及了藝術家本人對於跨領域的成就與貢獻。\r\n \r\n不僅如此，旅居巴黎的知名作家祖慰在為陳正雄撰寫傳記時即以《畫布上的歡樂頌》一書，來稱讚其所帶給觀者的喜悅，而筆觸中自然流露的音樂與流動性，讓陳正雄在創作的畫面中，皆染上四季的氛圍。於是，四時流轉，萬物生機交融於天地人間，無論市井喧囂亦或是內觀心性，總能適度展示出如春之新鬱、夏之嬌豔、秋之閑靜，或是冬之冷瑟的章節。\r\n \r\n回到《陳正雄90大展－抽象畫家和他的收藏》展覽中，這次高美館以陳正雄的收藏帶出創作中所蘊含的「文化色彩」，我們不僅能從原民藏品中的海洋性，直接投射到陳正雄抽象繪畫中的「抒情海洋」，更能在他的《窗》與《數位空間》等系列作品中，看見書法與刺繡服飾間的線條呼應，他巧妙地以色彩突圍了東方元素，但卻在畫面中同時融合了西方抽象的精粹，就如同劉禹錫《董氏武砬集記》所提出的「境生子象外」一說：或許在我們體會「意境」的當下，感受到的正是陳正雄在創作上呈現出如史記的磅礡，但心領神會後，卻又能從其中看見被列傳所點綴出的璀璨時代。　', `organizer`='高雄市立美術館', `address`='高雄市鼓山區6鄰美術館路80號', `start_date`='2025-01-25 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='高雄市立美術館', `latitude`=22.6566968, `longitude`=120.2865511, `ticket_price`='無資料', `source_url`='https://www.kmfa.gov.tw/exhibitiondetailc001100.aspx?Cond=7d76f82c-5ea4-4db0-a1a0-c7b97f7baf31', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894426b32458d43635e3', '「水下探索號-認識世界的水下文化資產」特展--潛進世界博物館', '展覽運用多元展示手法，將百年歷史的歷史建築「澎湖郵便局」及「馬公水上警察官吏派出所」打造為一艘極具未來感的「水下探索號」潛水艇及具臨場感的水下考古現場，帶領民眾環遊世界水下文化資產，體驗水下博物館環形投影、水下實境影片、水下文物互動遊戲、欣賞出水文物展示及潛水專業裝備等。「澎湖郵便局」展示區分為:A區 【國際水下博物館】觀眾化身為水下考古員觸碰6間國際水下博物館、B區 【國際6間水下博物館水下遺物展示】、C區 【澎湖海洋文化影像】。', '文化部文化資產局', '澎湖縣馬公市中山路75號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '澎湖郵便局', 23.55534, 119.59234, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「水下探索號-認識世界的水下文化資產」特展--潛進世界博物館', `description`='展覽運用多元展示手法，將百年歷史的歷史建築「澎湖郵便局」及「馬公水上警察官吏派出所」打造為一艘極具未來感的「水下探索號」潛水艇及具臨場感的水下考古現場，帶領民眾環遊世界水下文化資產，體驗水下博物館環形投影、水下實境影片、水下文物互動遊戲、欣賞出水文物展示及潛水專業裝備等。「澎湖郵便局」展示區分為:A區 【國際水下博物館】觀眾化身為水下考古員觸碰6間國際水下博物館、B區 【國際6間水下博物館水下遺物展示】、C區 【澎湖海洋文化影像】。', `organizer`='文化部文化資產局', `address`='澎湖縣馬公市中山路75號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='澎湖郵便局', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894426b32458d43635e4', '「水下探索號-認識世界的水下文化資產」特展--沉船的命運交響曲', '展覽運用多元展示手法，將百年歷史的歷史建築「澎湖郵便局」及「馬公水上警察官吏派出所」打造為一艘極具未來感的「水下探索號」潛水艇及具臨場感的水下考古現場，帶領民眾環遊世界水下文化資產，體驗水下博物館環形投影、水下實境影片、水下文物互動遊戲、欣賞出水文物展示及潛水專業裝備等。展覽規劃成七大展區，分別為澎湖郵便局展館「潛進世界水下博物館」、「水底文物再現」、「探索水下澎湖」三個展區以及馬公水上警察官吏派出所展館「沉船的命運交響曲」、「再現水下文物實驗室」、「解密水下考古」、「臺灣的水下文化資產」四個展區。馬公水上警察官吏派出所展館展示區分為:D區【潛水裝備展示】【船艙鋼琴互動】\r\n 、E區 【水下創作實驗室】、F區【出水遺物燈箱】 。', '文化部文化資產局', '澎湖縣馬公市臨海路40號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '馬公水上警察官吏派出所', 23.55534, 119.59234, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「水下探索號-認識世界的水下文化資產」特展--沉船的命運交響曲', `description`='展覽運用多元展示手法，將百年歷史的歷史建築「澎湖郵便局」及「馬公水上警察官吏派出所」打造為一艘極具未來感的「水下探索號」潛水艇及具臨場感的水下考古現場，帶領民眾環遊世界水下文化資產，體驗水下博物館環形投影、水下實境影片、水下文物互動遊戲、欣賞出水文物展示及潛水專業裝備等。展覽規劃成七大展區，分別為澎湖郵便局展館「潛進世界水下博物館」、「水底文物再現」、「探索水下澎湖」三個展區以及馬公水上警察官吏派出所展館「沉船的命運交響曲」、「再現水下文物實驗室」、「解密水下考古」、「臺灣的水下文化資產」四個展區。馬公水上警察官吏派出所展館展示區分為:D區【潛水裝備展示】【船艙鋼琴互動】\r\n 、E區 【水下創作實驗室】、F區【出水遺物燈箱】 。', `organizer`='文化部文化資產局', `address`='澎湖縣馬公市臨海路40號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='馬公水上警察官吏派出所', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894426b32458d43635ea', '2025傑優青少年打擊樂團年度音樂會《青春進行式》', '2025傑優青少年打擊樂團年度音樂會《青春進行式》\r\n  每一次敲擊，都是夢想的追尋；每一段旋律，都是感動的記憶。在青春的舞台上，盡情揮灑熱情，創造只屬於我們的節奏！我們是傑優青少年打擊樂團，青春進行式，等你一同來參與！\r\n\r\n建議3歲以上觀賞，一人一票、憑票入場。', '財團法人擊樂文教基金會', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '票價+400', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025傑優青少年打擊樂團年度音樂會《青春進行式》', `description`='2025傑優青少年打擊樂團年度音樂會《青春進行式》\r\n  每一次敲擊，都是夢想的追尋；每一段旋律，都是感動的記憶。在青春的舞台上，盡情揮灑熱情，創造只屬於我們的節奏！我們是傑優青少年打擊樂團，青春進行式，等你一同來參與！\r\n\r\n建議3歲以上觀賞，一人一票、憑票入場。', `organizer`='財團法人擊樂文教基金會', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='票價+400', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894526b32458d43635f0', '蔡廷蘭進士第常設展', '澎湖興仁蔡進士第位於今馬公市東南方興仁里上村，為澎湖進士蔡廷蘭高中進士後所建，自道光二十六年（1846年）至今，已有一百五十年之久。澎湖興仁舊名雙頭掛，位於澎湖拱北山與獅山中間地帶，因村落居兩山頭中而得名。開拓之初，大抵為半漁半農的生活方式，其後墾地日漸向內地擴張，離海港漸遠，而耕地日增，農業逐漸取代漁業。聚落分上村、東村；上村，大抵為蔡氏族人所聚居，有祖廟蔡氏濟陽堂一座。興仁蔡氏後裔蔡廷蘭，於道光二十四年（1844年）中式，成為澎湖本地的第一位，也是唯一的一位進士。進士蔡廷蘭生於嘉慶六年（1801年），十三歲即以稚年補生員，後入學府，屢試屢中，補澎湖廳稟生。為人廉靜，好讀書，先後主崇文書院、引心書院及文石書院講習。道光十七年（1837年）秋試中舉人。道光二十四年（1844年）春晉京會試，中進士，以即用知縣分發江西省。此後仕途多在大陸內地，任官累遷至同知，咸豐九年（1859年）以病歿於任所。蔡進士中進士後三年，即道光二十六年（1846年），回鄉祭祖，便在雙頭掛舊宅右邊建進士第，以光耀門楣。由於蔡進士一生仕途皆在外地，進士第的興築，其象徵的意義大於實際宅第的意義。進士第的建築特色是門廊面寬四點五公尺，深進約三點三公尺，正立面為退凹式作法。其廂房為馬背硬山式作法，屋面為硬山燕尾屋脊，為澎湖民宅中唯一有燕尾作法。宅第中其他建築作法及裝飾，亦頗為精緻。由於蔡氏子孫並未對進士第大規模整修或改建，故整體結構至今大致上仍保存完整，但因日久失修，澎湖縣政府於民國100-101年進行修復工程，恢復進士第以往容貌。 ', '澎湖縣政府文化局', '澎湖縣馬公市29號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '蔡廷蘭進士第', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蔡廷蘭進士第常設展', `description`='澎湖興仁蔡進士第位於今馬公市東南方興仁里上村，為澎湖進士蔡廷蘭高中進士後所建，自道光二十六年（1846年）至今，已有一百五十年之久。澎湖興仁舊名雙頭掛，位於澎湖拱北山與獅山中間地帶，因村落居兩山頭中而得名。開拓之初，大抵為半漁半農的生活方式，其後墾地日漸向內地擴張，離海港漸遠，而耕地日增，農業逐漸取代漁業。聚落分上村、東村；上村，大抵為蔡氏族人所聚居，有祖廟蔡氏濟陽堂一座。興仁蔡氏後裔蔡廷蘭，於道光二十四年（1844年）中式，成為澎湖本地的第一位，也是唯一的一位進士。進士蔡廷蘭生於嘉慶六年（1801年），十三歲即以稚年補生員，後入學府，屢試屢中，補澎湖廳稟生。為人廉靜，好讀書，先後主崇文書院、引心書院及文石書院講習。道光十七年（1837年）秋試中舉人。道光二十四年（1844年）春晉京會試，中進士，以即用知縣分發江西省。此後仕途多在大陸內地，任官累遷至同知，咸豐九年（1859年）以病歿於任所。蔡進士中進士後三年，即道光二十六年（1846年），回鄉祭祖，便在雙頭掛舊宅右邊建進士第，以光耀門楣。由於蔡進士一生仕途皆在外地，進士第的興築，其象徵的意義大於實際宅第的意義。進士第的建築特色是門廊面寬四點五公尺，深進約三點三公尺，正立面為退凹式作法。其廂房為馬背硬山式作法，屋面為硬山燕尾屋脊，為澎湖民宅中唯一有燕尾作法。宅第中其他建築作法及裝飾，亦頗為精緻。由於蔡氏子孫並未對進士第大規模整修或改建，故整體結構至今大致上仍保存完整，但因日久失修，澎湖縣政府於民國100-101年進行修復工程，恢復進士第以往容貌。 ', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市29號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='蔡廷蘭進士第', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
