INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894526b32458d43635fd', '114年閱讀推廣藝文研習班(2班)', '1.書法班：每週二09:00-11:00，指導老師/黃煜華。如有課程取消或暫停一次，另外通知。\r\n\r\n2.讀經班：每週二19:30-20:30，指導老師/葉雲英、詹麗娟、吳華熙、許鴻鈞。\r\n【三字經】、【弟子規】、【弟子規】、【成語故事】、【論語】、【三十六計】、【唐詩三百首】，藉著共讀和有趣的互動有獎徵答，活潑生動的方式為小朋友奠定良好的品格教育。', '桃園市立圖書館', '桃園市新屋區中興路91巷11號', '2025-01-02 00:00:00', '2025-12-30 00:00:00', '桃園市立圖書館新屋分館', 24.97280352, 121.067758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年閱讀推廣藝文研習班(2班)', `description`='1.書法班：每週二09:00-11:00，指導老師/黃煜華。如有課程取消或暫停一次，另外通知。\r\n\r\n2.讀經班：每週二19:30-20:30，指導老師/葉雲英、詹麗娟、吳華熙、許鴻鈞。\r\n【三字經】、【弟子規】、【弟子規】、【成語故事】、【論語】、【三十六計】、【唐詩三百首】，藉著共讀和有趣的互動有獎徵答，活潑生動的方式為小朋友奠定良好的品格教育。', `organizer`='桃園市立圖書館', `address`='桃園市新屋區中興路91巷11號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-30 00:00:00', `location`='桃園市立圖書館新屋分館', `latitude`=24.97280352, `longitude`=121.067758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894526b32458d4363603', '迎風藝術群《伴生。絆生》海藻主題多媒材展', '迎風藝術群長期致力於藝術行銷澎湖，此次展覽由黃春鶯會長帶領策劃，以「伴生。絆生」為主題，展出的80件作品包含海藻標本創作、藍晒書籤、手工布包等，充分展示了藝術的多元可能性。\r\n\r\n\r\n', '澎湖縣湖西鄉公所', '澎湖縣湖西鄉43之11號', '2025-01-09 00:00:00', '2025-02-27 00:00:00', '澎湖縣湖西鄉公所', 23.57364, 119.64462, '無資料', 'http://www.hs885.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='迎風藝術群《伴生。絆生》海藻主題多媒材展', `description`='迎風藝術群長期致力於藝術行銷澎湖，此次展覽由黃春鶯會長帶領策劃，以「伴生。絆生」為主題，展出的80件作品包含海藻標本創作、藍晒書籤、手工布包等，充分展示了藝術的多元可能性。\r\n\r\n\r\n', `organizer`='澎湖縣湖西鄉公所', `address`='澎湖縣湖西鄉43之11號', `start_date`='2025-01-09 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='澎湖縣湖西鄉公所', `latitude`=23.57364, `longitude`=119.64462, `ticket_price`='無資料', `source_url`='http://www.hs885.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6782daf026b32458d4363606', '2025琴棋書畫在歸仁-第一季課程(1-3月)', '為活絡本區美學館各館室空間之使用，同時提供民眾假日休閒的好去處，及陶冶藝術人文氣息，特辦理本系列課程活動。\r\n第一季藝文課程:\r\n1/12、1/19、2/9、2/23、3/9、3/23\r\n10:00-12:00 多媒材繪畫、黏土班-陳麗珍(豆豆老師)\r\n1/8、1/15、1/22、2/5、2/19、2/26、3/5、3/12、3/19、3/26\r\n14:30-16:30 吉祥工筆畫-黃士哲老師\r\n1/11、1/18、2/15、2/22、3/8、3/22\r\n10:00-12:00 禪繞繪畫班-蔡翠雲老師\r\n單次課程：\r\n1/5 10:00-12:00 手捏馬克杯陶土DIY-吳家慧老師\r\n1/19 10:00-12:00 新春快樂木作組盆趣-許恩嫚老師\r\n3/9 10:00-12:00 側把茶海陶土DIY-吳家慧老師', '臺南市歸仁區公所', '臺南市歸仁區中山路一段568號', '2025-01-05 00:00:00', '2025-03-26 00:00:00', '臺南市歸仁美學館', 22.94679469, 120.2930627, '依課程不同，費用不同+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025琴棋書畫在歸仁-第一季課程(1-3月)', `description`='為活絡本區美學館各館室空間之使用，同時提供民眾假日休閒的好去處，及陶冶藝術人文氣息，特辦理本系列課程活動。\r\n第一季藝文課程:\r\n1/12、1/19、2/9、2/23、3/9、3/23\r\n10:00-12:00 多媒材繪畫、黏土班-陳麗珍(豆豆老師)\r\n1/8、1/15、1/22、2/5、2/19、2/26、3/5、3/12、3/19、3/26\r\n14:30-16:30 吉祥工筆畫-黃士哲老師\r\n1/11、1/18、2/15、2/22、3/8、3/22\r\n10:00-12:00 禪繞繪畫班-蔡翠雲老師\r\n單次課程：\r\n1/5 10:00-12:00 手捏馬克杯陶土DIY-吳家慧老師\r\n1/19 10:00-12:00 新春快樂木作組盆趣-許恩嫚老師\r\n3/9 10:00-12:00 側把茶海陶土DIY-吳家慧老師', `organizer`='臺南市歸仁區公所', `address`='臺南市歸仁區中山路一段568號', `start_date`='2025-01-05 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺南市歸仁美學館', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='依課程不同，費用不同+--', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6782db0c26b32458d436361c', '我的語言教室一新住民語言故事學習展', '將展場化為一處「語言學習發生的現場」，以影像、物件、裝置等形式呈現新住民學習語言的歷程和體驗，觀眾來到展覽這處「語言教室」，不僅認識來自不同國家的用語，也看見語言學習過程遭遇的文化差異，並體認語言學習的過程不僅關乎語言本身，還包括文化融入與社會互動；另一方面則藉由每個人初學語言的共有經過重新認識新住民，感受進入新的生活與文化環境進行的准備與付出的努力，進而邀請觀眾思考對文化差異的理解與包容。', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-01-24 00:00:00', '2025-03-30 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='我的語言教室一新住民語言故事學習展', `description`='將展場化為一處「語言學習發生的現場」，以影像、物件、裝置等形式呈現新住民學習語言的歷程和體驗，觀眾來到展覽這處「語言教室」，不僅認識來自不同國家的用語，也看見語言學習過程遭遇的文化差異，並體認語言學習的過程不僅關乎語言本身，還包括文化融入與社會互動；另一方面則藉由每個人初學語言的共有經過重新認識新住民，感受進入新的生活與文化環境進行的准備與付出的努力，進而邀請觀眾思考對文化差異的理解與包容。', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-01-24 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6782db0d26b32458d4363620', '《水深200公尺，沒有光》主題書展', '神祕的海洋，未知的比已知的還要多很多。\r\n那片汪洋不僅和全球生態、氣候密不可分，也和人類的過去與未來息息相關。\r\n', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-01-02 00:00:00', '2025-02-27 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《水深200公尺，沒有光》主題書展', `description`='神祕的海洋，未知的比已知的還要多很多。\r\n那片汪洋不僅和全球生態、氣候密不可分，也和人類的過去與未來息息相關。\r\n', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6782db0d26b32458d4363621', '《心•靈之鏡》主題書展', '《心•靈之鏡》主題書展\r\n以書為鏡，照見自我與人性的真諦；以書為器，深掘心靈深處的智慧；以書為燈，照亮內心的思考與感悟。\r\n', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-01-02 00:00:00', '2025-02-27 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《心•靈之鏡》主題書展', `description`='《心•靈之鏡》主題書展\r\n以書為鏡，照見自我與人性的真諦；以書為器，深掘心靈深處的智慧；以書為燈，照亮內心的思考與感悟。\r\n', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6782db0d26b32458d4363622', '《動物奇幻之旅》主題書展', '《動物奇幻之旅》主題書展\r\n曾經在公園、上學路上，甚至窗外聽過蟲鳴鳥叫，看過一閃而過的小身影嗎？一起來認識這些小鄰居吧！', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-01-02 00:00:00', '2025-02-27 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《動物奇幻之旅》主題書展', `description`='《動物奇幻之旅》主題書展\r\n曾經在公園、上學路上，甚至窗外聽過蟲鳴鳥叫，看過一閃而過的小身影嗎？一起來認識這些小鄰居吧！', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6782db0e26b32458d4363626', '陳啓榮「落羽松攝影詩作」個展', '創作者陳啓榮特別為每幅落羽松的攝影作品撰寫了生動的詩作，詩作與攝影相得益彰，讓觀眾在欣賞攝影作品並透過一篇篇動人的詩作，傳遞出藝術的美與智慧。\r\n', '臺南市六甲區公所', '臺南市六甲區中山路202號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '臺南市六甲區公所/六甲區圖書館', 23.2272672, 120.3800259, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陳啓榮「落羽松攝影詩作」個展', `description`='創作者陳啓榮特別為每幅落羽松的攝影作品撰寫了生動的詩作，詩作與攝影相得益彰，讓觀眾在欣賞攝影作品並透過一篇篇動人的詩作，傳遞出藝術的美與智慧。\r\n', `organizer`='臺南市六甲區公所', `address`='臺南市六甲區中山路202號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市六甲區公所/六甲區圖書館', `latitude`=23.2272672, `longitude`=120.3800259, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6782db0f26b32458d436362b', '珠光鳳影，綽綽琉彩展', '本次舉辦李麗玉老師創作個展，主題是「珠光鳳影，綽綽琉彩展」，全部作品皆由一顆顆0.2公分的小珠子，貼黏成一幅幅精彩絕倫的圖案；其中更有多幅採用梵谷經典畫作，藉由不同媒材，呈現不同視覺感受，透過光影流動分享給喜愛藝術的您，歡迎一同來品味美的事物。', '臺南市政府財政稅務局', '臺南市安平區永華路二段6號', '2025-01-03 00:00:00', '2025-03-31 00:00:00', '臺南市政府永華市政中心', 22.99008437, 120.1649949, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='珠光鳳影，綽綽琉彩展', `description`='本次舉辦李麗玉老師創作個展，主題是「珠光鳳影，綽綽琉彩展」，全部作品皆由一顆顆0.2公分的小珠子，貼黏成一幅幅精彩絕倫的圖案；其中更有多幅採用梵谷經典畫作，藉由不同媒材，呈現不同視覺感受，透過光影流動分享給喜愛藝術的您，歡迎一同來品味美的事物。', `organizer`='臺南市政府財政稅務局', `address`='臺南市安平區永華路二段6號', `start_date`='2025-01-03 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市政府永華市政中心', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6782db1126b32458d436362f', '音樂主題書展-  山谷傳來的歌聲- 原住民、客家歌謠', '在群山環抱的山谷中，總能聽見傳來的悠揚歌聲，那是大自然與文化的對話，也是歷史與情感的回響。客家歌謠與原住民歌謠，像兩條不同的溪流，從不同的源頭出發，卻在同一片土地上交匯，滋養了人們的心靈，也豐富了我們的文化記憶。\r\n\r\n圖書展區:', '許石音樂圖書館', '臺南市北區公園北路3號', '2025-01-02 00:00:00', '2025-02-27 00:00:00', '許石音樂圖書館', 23.01012179, 120.2068735, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='音樂主題書展-  山谷傳來的歌聲- 原住民、客家歌謠', `description`='在群山環抱的山谷中，總能聽見傳來的悠揚歌聲，那是大自然與文化的對話，也是歷史與情感的回響。客家歌謠與原住民歌謠，像兩條不同的溪流，從不同的源頭出發，卻在同一片土地上交匯，滋養了人們的心靈，也豐富了我們的文化記憶。\r\n\r\n圖書展區:', `organizer`='許石音樂圖書館', `address`='臺南市北區公園北路3號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='許石音樂圖書館', `latitude`=23.01012179, `longitude`=120.2068735, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6782db1126b32458d4363630', '月讀好時光-油畫欣賞', '為帶動北區藝文風潮，並鼓勵區民創作，於本所樓梯闢置藝文走廊，由社區熱心推廣藝文活動人士無償提供油畫作品懸掛，供民眾欣賞。\r\n油畫作品包含：\r\n《農村樂》《棉花糖》等，以講師的幼年經歷及成長歷程為基礎所繪製的多幅油畫，讓當時情景重現眼前，等著大家來了解與欣賞。', '臺南市北區區公所', '臺南市北區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '北區（臺南市）=', 23.01012179, 120.2068735, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='月讀好時光-油畫欣賞', `description`='為帶動北區藝文風潮，並鼓勵區民創作，於本所樓梯闢置藝文走廊，由社區熱心推廣藝文活動人士無償提供油畫作品懸掛，供民眾欣賞。\r\n油畫作品包含：\r\n《農村樂》《棉花糖》等，以講師的幼年經歷及成長歷程為基礎所繪製的多幅油畫，讓當時情景重現眼前，等著大家來了解與欣賞。', `organizer`='臺南市北區區公所', `address`='臺南市北區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='北區（臺南市）=', `latitude`=23.01012179, `longitude`=120.2068735, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6782db1226b32458d4363631', 'SUNDAY：臺灣當代移工藝術展', '臺灣自1990年代起開啟大量引入海外移工的篇章。截至2024年9月底勞動部統計數據，在臺移工人口數已突破80萬人次，成為臺灣當前產業運轉不可或缺的基礎引擎。近年來，社會對移工議題的關注日益增加；然而，移工作為勞動者以外的多重面向與需求仍時常不被看見。\r\n\r\n臺南市美術館透過當代藝術詮釋移工議題，邀請來自不同背景的移工及國內外藝術家，以「漂移之味」、「逃逸之方」、「艷陽下南風吹」三個子題，經由生命經驗的觀察、獨白與轉譯、交流與合作等創造過程，揭示移工不為人知的面貌。展覽也引發我們思考，在以移工為主體的多重情境中，始終隱藏著許多不被看見的心靈風景，應尊重彼此作為生命共同體，並發掘當代世界中，差異與相似皆真實存在。', '臺南市美術館', '臺南市中西區臺南市中西區忠義路二段 1 號', '2025-01-01 00:00:00', '2025-04-13 00:00:00', '臺南市美術館2館', 22.99594458, 120.192874, '詳參　https://www.tnam.museum/visit/hours_tickets+--', 'https://www.tnam.museum/exhibition/detail/567', '[]') ON DUPLICATE KEY UPDATE `activity_name`='SUNDAY：臺灣當代移工藝術展', `description`='臺灣自1990年代起開啟大量引入海外移工的篇章。截至2024年9月底勞動部統計數據，在臺移工人口數已突破80萬人次，成為臺灣當前產業運轉不可或缺的基礎引擎。近年來，社會對移工議題的關注日益增加；然而，移工作為勞動者以外的多重面向與需求仍時常不被看見。\r\n\r\n臺南市美術館透過當代藝術詮釋移工議題，邀請來自不同背景的移工及國內外藝術家，以「漂移之味」、「逃逸之方」、「艷陽下南風吹」三個子題，經由生命經驗的觀察、獨白與轉譯、交流與合作等創造過程，揭示移工不為人知的面貌。展覽也引發我們思考，在以移工為主體的多重情境中，始終隱藏著許多不被看見的心靈風景，應尊重彼此作為生命共同體，並發掘當代世界中，差異與相似皆真實存在。', `organizer`='臺南市美術館', `address`='臺南市中西區臺南市中西區忠義路二段 1 號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='臺南市美術館2館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='詳參　https://www.tnam.museum/visit/hours_tickets+--', `source_url`='https://www.tnam.museum/exhibition/detail/567', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67842a1e26b32458d4363654', '因原際會 ‧ 13有成 原住民族文化館年度成果特展', '這次展覽是對過去一年努力的總結，也是一場結合文化、藝術與教育的視覺盛宴，\r\n透過展覽讓更多民眾了解原住民族文化館的使命與價值，更期待您走進各地文化館，共享全國原住民族文化館的豐碩成果。\r\n★本次成果特展，以六大主題呈現原住民族文化的多元與深度：\r\n看見原文館如何成為在地文化知識的平台，感受地方能量，分享在地精采的文化傳承故事。\r\n★展覽亮點\r\n🔹 工藝：巧手巧心，藝憶生輝\r\n🔹 環教：與山海齊心，使寰宇滿星\r\n🔹 飲食：生養於自然，做個有鹽巴的人\r\n🔹 樂舞：行星之聲，以樂舞訴真情\r\n🔹 教育：實踐與傳承，讓我們不失根\r\n🔹 美學：環環相扣，原式美學', '原住民族委員會原住民族文化發展中心', '屏東縣瑪家鄉風景104號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '原住民族委員會原住民族文化發展中心', 22.67107764, 120.6799239, '全票+150;學生、軍警票+80;團體票+120', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='因原際會 ‧ 13有成 原住民族文化館年度成果特展', `description`='這次展覽是對過去一年努力的總結，也是一場結合文化、藝術與教育的視覺盛宴，\r\n透過展覽讓更多民眾了解原住民族文化館的使命與價值，更期待您走進各地文化館，共享全國原住民族文化館的豐碩成果。\r\n★本次成果特展，以六大主題呈現原住民族文化的多元與深度：\r\n看見原文館如何成為在地文化知識的平台，感受地方能量，分享在地精采的文化傳承故事。\r\n★展覽亮點\r\n🔹 工藝：巧手巧心，藝憶生輝\r\n🔹 環教：與山海齊心，使寰宇滿星\r\n🔹 飲食：生養於自然，做個有鹽巴的人\r\n🔹 樂舞：行星之聲，以樂舞訴真情\r\n🔹 教育：實踐與傳承，讓我們不失根\r\n🔹 美學：環環相扣，原式美學', `organizer`='原住民族委員會原住民族文化發展中心', `address`='屏東縣瑪家鄉風景104號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='原住民族委員會原住民族文化發展中心', `latitude`=22.67107764, `longitude`=120.6799239, `ticket_price`='全票+150;學生、軍警票+80;團體票+120', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67842a1f26b32458d4363655', '無資料', '明治時期，匠人們秉持一絲不苟的工藝態度，對細節極度講究，延續了日本千年以來的精湛工藝，傳統匠心精神體現於每一件作品中。不急功近利，而是追求長期的成就，願意花時間磨練技藝，積累經驗。培養耐心與持久的專注，創造出經得起時間考驗的作品。\r\n以【物】借喻自身，為文人常用的表現手法，透過對外物的描寫，寄託自己的心境和品格，表現出文人獨特的精神追求。黃逢徵先生為黃纘緒舉人四世孫，身為文人後代的他，藉由明治藝術約束自己，對待生活中的每一件事都保持認真、敬畏和責任感，卻同時蘊含著創新與突破的意志，不斷學習與實踐，融入創新於生活之中，不斷進步，將每一天視為一次自我挑戰的機會。\r\n今黃逢徵先生將畢生收藏之明治藝術帶回經居住過的老宅中，也希望將待人處事之道分享給每一位來黃舉人宅參觀的人們，透過明治藝術中的匠心，調整自身以實踐的精神去面對生活中的挑戰。', '財團法人全聯善美的文化藝術基金會', '宜蘭縣五結鄉24鄰五濱路二段201號', '國立傳統藝術中心宜蘭園區', 24.68887343, 121.8058342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='明治時期，匠人們秉持一絲不苟的工藝態度，對細節極度講究，延續了日本千年以來的精湛工藝，傳統匠心精神體現於每一件作品中。不急功近利，而是追求長期的成就，願意花時間磨練技藝，積累經驗。培養耐心與持久的專注，創造出經得起時間考驗的作品。\r\n以【物】借喻自身，為文人常用的表現手法，透過對外物的描寫，寄託自己的心境和品格，表現出文人獨特的精神追求。黃逢徵先生為黃纘緒舉人四世孫，身為文人後代的他，藉由明治藝術約束自己，對待生活中的每一件事都保持認真、敬畏和責任感，卻同時蘊含著創新與突破的意志，不斷學習與實踐，融入創新於生活之中，不斷進步，將每一天視為一次自我挑戰的機會。\r\n今黃逢徵先生將畢生收藏之明治藝術帶回經居住過的老宅中，也希望將待人處事之道分享給每一位來黃舉人宅參觀的人們，透過明治藝術中的匠心，調整自身以實踐的精神去面對生活中的挑戰。', `organizer`='財團法人全聯善美的文化藝術基金會', `address`='宜蘭縣五結鄉24鄰五濱路二段201號', `location`='國立傳統藝術中心宜蘭園區', `latitude`=24.68887343, `longitude`=121.8058342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67842a1f26b32458d4363656', '《無懼之路 春日500》2024 春日鄉人文歷史主題展', 'google位置：https://maps.app.goo.gl/WpWTv39FbS63iFP77\r\n長達500年的人文歷史展，如今春日鄉首次展出於春日鄉文創基地推動《無懼之路 春日500》💃\r\n\r\n⠀\r\n\r\n2024 年，在人文紀錄非常豐碩的當下，也在鄉親父老的期盼下誕生，如何展示春日鄉500年及其近代的風華，體驗浸水營古道濃厚的文化氣息；其後更加入當紅古華工藝師雕刻、人文、在地產業攤位、音樂會、地方文創商品等並配合活化天蠍棚歷史建築走入歷史空間。\r\n\r\n⠀\r\n\r\n十一月後，我們正式讓文化藝術帶出殿堂，貼近排灣族土地。將日治後的時間迴廊為出發點，用駐地藝術產區身分展開「無懼之路 春日500」三年計畫，每年透過不同主題來推動春日鄉在台灣歷史上的重要性，如今將帶著山與海的能量一一推行，展現春日鄉文化藝術強大的生命力。\r\n\r\n\r\n\r\n☀️ 文化遊程建議：gogo春日接駁訊息\r\n\r\n@策展區-往返-力里人神盟約祭Maljeveq（五年祭） 11/07-11/13\r\n\r\n@策展區-往返-歸崇人神盟約祭Maljeveq（五年祭） 11/19-11/25\r\n\r\n@策展區-往返-七佳人神盟約祭Maljeveq（五年祭） 11/26-12/02', '屏東縣春日鄉公所', '屏東縣春日鄉', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '春日鄉（屏東縣）=', 22.40399754, 120.6975799, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《無懼之路 春日500》2024 春日鄉人文歷史主題展', `description`='google位置：https://maps.app.goo.gl/WpWTv39FbS63iFP77\r\n長達500年的人文歷史展，如今春日鄉首次展出於春日鄉文創基地推動《無懼之路 春日500》💃\r\n\r\n⠀\r\n\r\n2024 年，在人文紀錄非常豐碩的當下，也在鄉親父老的期盼下誕生，如何展示春日鄉500年及其近代的風華，體驗浸水營古道濃厚的文化氣息；其後更加入當紅古華工藝師雕刻、人文、在地產業攤位、音樂會、地方文創商品等並配合活化天蠍棚歷史建築走入歷史空間。\r\n\r\n⠀\r\n\r\n十一月後，我們正式讓文化藝術帶出殿堂，貼近排灣族土地。將日治後的時間迴廊為出發點，用駐地藝術產區身分展開「無懼之路 春日500」三年計畫，每年透過不同主題來推動春日鄉在台灣歷史上的重要性，如今將帶著山與海的能量一一推行，展現春日鄉文化藝術強大的生命力。\r\n\r\n\r\n\r\n☀️ 文化遊程建議：gogo春日接駁訊息\r\n\r\n@策展區-往返-力里人神盟約祭Maljeveq（五年祭） 11/07-11/13\r\n\r\n@策展區-往返-歸崇人神盟約祭Maljeveq（五年祭） 11/19-11/25\r\n\r\n@策展區-往返-七佳人神盟約祭Maljeveq（五年祭） 11/26-12/02', `organizer`='屏東縣春日鄉公所', `address`='屏東縣春日鄉', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='春日鄉（屏東縣）=', `latitude`=22.40399754, `longitude`=120.6975799, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67842a1f26b32458d436365d', '屏東縣霧臺鄉部落研究員計畫成果展', '霧臺鄉的植物地名有三大意義：它們記錄了地方的自然特徵、承載了族群的文化記憶，還展現了豐富的生態智慧。例如，像Drakuaku（無患子之地）和Tatukutukulu（相思樹之地）這些地名，不僅描繪了植物的生長環境，還反映了它們對族人生活的重要性；Taupilricane（玉米鍋巴之地）更是透過故事保留了族人的共同回憶。', '屏東縣霧臺鄉公所', '屏東縣霧臺鄉', '2025-01-10 00:00:00', '2025-03-15 00:00:00', '霧臺鄉（屏東縣）=', 22.75990478, 120.8008099, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='屏東縣霧臺鄉部落研究員計畫成果展', `description`='霧臺鄉的植物地名有三大意義：它們記錄了地方的自然特徵、承載了族群的文化記憶，還展現了豐富的生態智慧。例如，像Drakuaku（無患子之地）和Tatukutukulu（相思樹之地）這些地名，不僅描繪了植物的生長環境，還反映了它們對族人生活的重要性；Taupilricane（玉米鍋巴之地）更是透過故事保留了族人的共同回憶。', `organizer`='屏東縣霧臺鄉公所', `address`='屏東縣霧臺鄉', `start_date`='2025-01-10 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='霧臺鄉（屏東縣）=', `latitude`=22.75990478, `longitude`=120.8008099, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6784a3818f1579d1ccee33c5', '牯嶺街小劇場【2025為你朗讀Ｘ】 ', '2025年2月，牯嶺街小劇場第十屆《為你朗讀》隆重登場！\r\n本次活動內容豐富，包括6部精彩讀劇、3場特別講座，以及2~3月份與牯嶺街擁有悠久歷史的二手書店-松林書局合辦文學書展 ! 活動將以嶄新方式探討劇場創作與表演。包含徵選三部新銳劇作《蛹夢》、《尾站》、《Baby Boy！超嬰溯作戰！》，並邀約許正平新作《換／幻妻》、李育芳《製造女孩》，以及原新營銀齡戲劇工作坊成員改編莎翁《仲夏夜之夢》的《波頓之夢》。三大單元共12場次讀劇演出，搭配演後導讀與創作者對談，深化藝術互動。\r\n此外，劇場導演Chongtham Jayanta Meetei（江譚佳彥）、演員 鄭尹真與劇作家施如芳三場專題講座，分享創作歷程與獨特視角。《為你朗讀》自牯嶺街小劇場起步，推動亞洲青年劇作，成為豐富創作與觀賞經驗的藝文盛事！', '身體氣象館 - 牯嶺街小劇場', '臺北市中正區牯嶺街5巷2號', '2025-02-05 00:00:00', '2025-03-30 00:00:00', '牯嶺街小劇場', 25.03240487, 121.5198839, '無資料', 'https://www.opentix.life/event/1874758147287814145', '[]') ON DUPLICATE KEY UPDATE `activity_name`='牯嶺街小劇場【2025為你朗讀Ｘ】 ', `description`='2025年2月，牯嶺街小劇場第十屆《為你朗讀》隆重登場！\r\n本次活動內容豐富，包括6部精彩讀劇、3場特別講座，以及2~3月份與牯嶺街擁有悠久歷史的二手書店-松林書局合辦文學書展 ! 活動將以嶄新方式探討劇場創作與表演。包含徵選三部新銳劇作《蛹夢》、《尾站》、《Baby Boy！超嬰溯作戰！》，並邀約許正平新作《換／幻妻》、李育芳《製造女孩》，以及原新營銀齡戲劇工作坊成員改編莎翁《仲夏夜之夢》的《波頓之夢》。三大單元共12場次讀劇演出，搭配演後導讀與創作者對談，深化藝術互動。\r\n此外，劇場導演Chongtham Jayanta Meetei（江譚佳彥）、演員 鄭尹真與劇作家施如芳三場專題講座，分享創作歷程與獨特視角。《為你朗讀》自牯嶺街小劇場起步，推動亞洲青年劇作，成為豐富創作與觀賞經驗的藝文盛事！', `organizer`='身體氣象館 - 牯嶺街小劇場', `address`='臺北市中正區牯嶺街5巷2號', `start_date`='2025-02-05 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='牯嶺街小劇場', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://www.opentix.life/event/1874758147287814145', `image_url`='[]';
