INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67857aed26b32458d436366e', '公共圖書館桃園分區資源中心主題書展1-2月', '主題書展1-2月：偶然之籤；開啟隨機故事之門\r\n您是否幻想過自己走進一個神祕空間，開啟一段充滿奇思妙想的旅程呢？\r\n旅程中的每個機遇都是屬於您的人生禮物，在平凡的生活中注入鮮活能量!\r\n我們想邀請您，跟著籤文的指示，打開藏有寶貴故事的大門，與作者不期而遇。', '國家圖書館', '桃園市桃園區南平路303號', '2025-01-02 00:00:00', '2025-02-26 00:00:00', '桃園市立圖書館總館', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='公共圖書館桃園分區資源中心主題書展1-2月', `description`='主題書展1-2月：偶然之籤；開啟隨機故事之門\r\n您是否幻想過自己走進一個神祕空間，開啟一段充滿奇思妙想的旅程呢？\r\n旅程中的每個機遇都是屬於您的人生禮物，在平凡的生活中注入鮮活能量!\r\n我們想邀請您，跟著籤文的指示，打開藏有寶貴故事的大門，與作者不期而遇。', `organizer`='國家圖書館', `address`='桃園市桃園區南平路303號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='桃園市立圖書館總館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67857b0c26b32458d436367c', '第15屆亞洲藝術聯盟大展在桃園', '「立足台灣、走向國際」是台灣「泛亞藝術聯盟協會」的初心與目標。在各方協助下、爭取到2025年第15屆亞洲藝術聯盟大展之主辦權。\r\n為了宣揚台灣在地文化，展覽以呈現多元族群文化之2025台灣燈會為開場，並於「桃園展演中心」舉辦這場20多個國家150幾位藝術家參與的國際藝術展覽。\r\n讓我們攜手共進，走向國際，用藝術搭起友誼的橋樑！', '泛亞藝術聯盟協會', '桃園市桃園區中正路1188號', '2025-02-21 00:00:00', '2025-03-09 00:00:00', '桃園展演中心', 25.00040024, 121.2996612, '無資料', 'https://15thasiaartallianceexhibition.weebly.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第15屆亞洲藝術聯盟大展在桃園', `description`='「立足台灣、走向國際」是台灣「泛亞藝術聯盟協會」的初心與目標。在各方協助下、爭取到2025年第15屆亞洲藝術聯盟大展之主辦權。\r\n為了宣揚台灣在地文化，展覽以呈現多元族群文化之2025台灣燈會為開場，並於「桃園展演中心」舉辦這場20多個國家150幾位藝術家參與的國際藝術展覽。\r\n讓我們攜手共進，走向國際，用藝術搭起友誼的橋樑！', `organizer`='泛亞藝術聯盟協會', `address`='桃園市桃園區中正路1188號', `start_date`='2025-02-21 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='桃園展演中心', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='https://15thasiaartallianceexhibition.weebly.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67857b0c26b32458d436367d', '無資料', '啟英高中設計群設有廣告設計科及室內設計科，在歷任科主任努力耕耘下，成為培育設計業界基礎人才搖籃。本次展覽為三年級學生運用所學，激盪靈感，發揮創意及技術，將團隊設計理念具象化呈現，為學生展現學習成就。', '啟英學校財團法人桃園市啟英高級中等學校', '桃園市中壢區中美路16號', '中壢藝術館', 24.958126, 121.227384, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='啟英高中設計群設有廣告設計科及室內設計科，在歷任科主任努力耕耘下，成為培育設計業界基礎人才搖籃。本次展覽為三年級學生運用所學，激盪靈感，發揮創意及技術，將團隊設計理念具象化呈現，為學生展現學習成就。', `organizer`='啟英學校財團法人桃園市啟英高級中等學校', `address`='桃園市中壢區中美路16號', `location`='中壢藝術館', `latitude`=24.958126, `longitude`=121.227384, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67857b0f26b32458d4363682', '孩子人際相處的故事繪本主題書展', '故事書是一個強大的工具，它能夠以生動的情節和可愛的角色讓孩子更容易地理解複雜的情感和人際互動。每一個故事都是一個鏡子，反映出孩子們在現實生活中可能面對的困難與挑戰，而這些故事也能提供解決問題的方法和策略。\r\n', '高雄市立圖書館總館', '高雄市岡山區009鄰岡山南路42號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='孩子人際相處的故事繪本主題書展', `description`='故事書是一個強大的工具，它能夠以生動的情節和可愛的角色讓孩子更容易地理解複雜的情感和人際互動。每一個故事都是一個鏡子，反映出孩子們在現實生活中可能面對的困難與挑戰，而這些故事也能提供解決問題的方法和策略。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67857b0f26b32458d4363683', '「台灣作家」主題書展', '「台灣作家」主題書展\r\n於二樓設置專區放置相關主題書籍。定期更換推薦書籍，歡迎大家借閱。\r\n▪展演時間｜114年3月1日至3月31日／開館時間\r\n▪展演書單｜寶島台灣、傳誠 : 台灣電聲推手廖祿立的人生思索、燈滅起跑 :賽車主播羅賓的快意人生、唐鳳 : 我所看待的自由與未來、我以我血獻青天 :飛行員的故事、唐鳳15個關鍵詞、古董張回憶錄、何不認真來悲傷、傀儡花、台灣作家一百年.等書籍', '高雄市立圖書館總館', '高雄市湖內區3鄰保生路101號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '高雄市立圖書館湖內分館', 22.8955499, 120.2225563, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「台灣作家」主題書展', `description`='「台灣作家」主題書展\r\n於二樓設置專區放置相關主題書籍。定期更換推薦書籍，歡迎大家借閱。\r\n▪展演時間｜114年3月1日至3月31日／開館時間\r\n▪展演書單｜寶島台灣、傳誠 : 台灣電聲推手廖祿立的人生思索、燈滅起跑 :賽車主播羅賓的快意人生、唐鳳 : 我所看待的自由與未來、我以我血獻青天 :飛行員的故事、唐鳳15個關鍵詞、古董張回憶錄、何不認真來悲傷、傀儡花、台灣作家一百年.等書籍', `organizer`='高雄市立圖書館總館', `address`='高雄市湖內區3鄰保生路101號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='高雄市立圖書館湖內分館', `latitude`=22.8955499, `longitude`=120.2225563, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
