INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67857b1026b32458d436368a', '歷史建築澎湖湖西鄉「湖西辛家古宅」展', '湖西辛家古宅為本縣登錄之歷史建築，為推廣文化資產的保存與記錄，保留左大間仔位置，以圖文輸出介紹其歷史沿革，配合屋頂構件，讓民眾近距離感受傳統建築工法。展覽主題除了手繪藝術家 -「朱朱－媽祖手繪作品」，大廳新增王旭昇師傅的糊紙作品，以西遊記為背景完成紙紮神像的大作展出。\r\n', '澎湖縣政府文化局', '澎湖縣湖西鄉', '2025-01-01 00:00:00', '2025-03-28 00:00:00', '湖西鄉（澎湖縣）=', 23.57364, 119.64462, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歷史建築澎湖湖西鄉「湖西辛家古宅」展', `description`='湖西辛家古宅為本縣登錄之歷史建築，為推廣文化資產的保存與記錄，保留左大間仔位置，以圖文輸出介紹其歷史沿革，配合屋頂構件，讓民眾近距離感受傳統建築工法。展覽主題除了手繪藝術家 -「朱朱－媽祖手繪作品」，大廳新增王旭昇師傅的糊紙作品，以西遊記為背景完成紙紮神像的大作展出。\r\n', `organizer`='澎湖縣政府文化局', `address`='澎湖縣湖西鄉', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='湖西鄉（澎湖縣）=', `latitude`=23.57364, `longitude`=119.64462, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67857b1026b32458d436368b', '「20214Openbook年度好書獎」書展', '2024 Openbook好書獎今年精選出202本優質作品入圍決選。最終評選出Openboo年度選書推薦給讀者，獎項分別為「年度中文創作」、「年度翻譯書」、「年度生活書」、「年度青少年圖書」及「年度童書」，合計共選出了40本精彩的年度好書。', '澎湖縣政府文化局', '澎湖縣馬公市中華路236之1號', '2025-01-23 00:00:00', '2025-03-02 00:00:00', '澎湖縣圖書館', 23.55534, 119.59234, '無資料', '--', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「20214Openbook年度好書獎」書展', `description`='2024 Openbook好書獎今年精選出202本優質作品入圍決選。最終評選出Openboo年度選書推薦給讀者，獎項分別為「年度中文創作」、「年度翻譯書」、「年度生活書」、「年度青少年圖書」及「年度童書」，合計共選出了40本精彩的年度好書。', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路236之1號', `start_date`='2025-01-23 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='澎湖縣圖書館', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='--', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67857b1026b32458d436368f', '無資料', '青仔欉 The Betel Palm—陳威齊個展\r\n「青仔欉」一詞源自台語發音，意指檳榔樹。\r\n家鄉位於南投埔里，地區的山坡地普遍栽種此樹，從而形塑出強烈的在地景觀與集體記憶。展覽試圖以自然景觀，描繪出因人性貪婪與制度性不公，對這失衡的環境進行的觀察。\r\n\r\n「青仔欉」同樣為日治時期曾發行的百元鈔票的稱呼，將「鈔票」與「資源」的概念並置，進一步強化財富象徵與社會現象之間的連結。也藉此探討諸如階級分化、炫富文化、詐騙行為等問題。展出的系列作品包含〈南安路〉、〈天下烏鴉一樣黑〉等，皆以各種社會現象為主題，以象徵諧仿的方式構成，思考其中無處不在的物質焦慮。\r\n作品〈煙囪、黑煙、垃圾袋〉則延伸至對環境污染背後的權責關係，質疑這些家鄉習以為常的景色，是否只是一場壟斷與剝削的假象，並進一步挑戰「公平正義」在現代社會中能否真正落實。\r\n\r\n展覽透過自然景色表達文化隱喻與象徵敘事，使用電腦繪圖輸出於不同基底材上，以節奏性的安排於牆面，帶著觀者走進種滿人性的青仔欉。', '高雄市政府文化局', '高雄市鹽埕區8鄰大勇路1號', '高雄市駁二藝術特區', 22.6199666, 120.2816536, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='青仔欉 The Betel Palm—陳威齊個展\r\n「青仔欉」一詞源自台語發音，意指檳榔樹。\r\n家鄉位於南投埔里，地區的山坡地普遍栽種此樹，從而形塑出強烈的在地景觀與集體記憶。展覽試圖以自然景觀，描繪出因人性貪婪與制度性不公，對這失衡的環境進行的觀察。\r\n\r\n「青仔欉」同樣為日治時期曾發行的百元鈔票的稱呼，將「鈔票」與「資源」的概念並置，進一步強化財富象徵與社會現象之間的連結。也藉此探討諸如階級分化、炫富文化、詐騙行為等問題。展出的系列作品包含〈南安路〉、〈天下烏鴉一樣黑〉等，皆以各種社會現象為主題，以象徵諧仿的方式構成，思考其中無處不在的物質焦慮。\r\n作品〈煙囪、黑煙、垃圾袋〉則延伸至對環境污染背後的權責關係，質疑這些家鄉習以為常的景色，是否只是一場壟斷與剝削的假象，並進一步挑戰「公平正義」在現代社會中能否真正落實。\r\n\r\n展覽透過自然景色表達文化隱喻與象徵敘事，使用電腦繪圖輸出於不同基底材上，以節奏性的安排於牆面，帶著觀者走進種滿人性的青仔欉。', `organizer`='高雄市政府文化局', `address`='高雄市鹽埕區8鄰大勇路1號', `location`='高雄市駁二藝術特區', `latitude`=22.6199666, `longitude`=120.2816536, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
