INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6785d7968f156cba57ab1ab9', '【日午音樂會172】董運昌指彈演奏會2025', '臺灣指彈吉他（Finger-Style Guitar）先驅，有「吉他詩人」之稱的董運昌，同時也是第10、14及第16屆金曲獎「最佳流行音樂演奏唱片獎」及「最佳流行音樂演奏專輯獎」得主。今年2025年適逢民歌50，董運昌將帶來數首民歌演奏版、鋼弦吉他經典曲目，以及曾經引領風潮的原創曲。\r\n\r\n■演出： 吉他｜董運昌\r\n\r\n■時間：2025年3月23日（日）14:30（遲到或中途離場的聽眾至中場休息方可入場，建議提早抵達）\r\n\r\n■地點：林建生紀念圖書館演奏廳（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額200位，七歲以上，免費報名入場。\r\n#恕無現場後補\r\n\r\n■報名方式：3月13 日（四）10:00 起，網路報名：　https://www.accupass.com/go/1140323\r\n\r\n■演出曲目：\r\n左岸印象、淚光閃閃、民歌組曲、雪落下的聲音、雪之華 、缺角地圖、阿爾罕布拉宮的回憶、南都夜曲、快樂的出航…等\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★歡迎加入Line 好友： https://bit.ly/2KFVgg2\r\n★網址： https://www.ljsedu.org.tw\r\n★粉絲專頁：https://www.facebook.com/linjiansheng\r\n', '財團法人紀念林建生教育基金會', '新北市蘆洲區三民路178號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '林建生紀念圖書館', 25.08927173, 121.4712461, '七歲以上，免費報名參加。', 'https://www.accupass.com/go/1140323', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【日午音樂會172】董運昌指彈演奏會2025', `description`='臺灣指彈吉他（Finger-Style Guitar）先驅，有「吉他詩人」之稱的董運昌，同時也是第10、14及第16屆金曲獎「最佳流行音樂演奏唱片獎」及「最佳流行音樂演奏專輯獎」得主。今年2025年適逢民歌50，董運昌將帶來數首民歌演奏版、鋼弦吉他經典曲目，以及曾經引領風潮的原創曲。\r\n\r\n■演出： 吉他｜董運昌\r\n\r\n■時間：2025年3月23日（日）14:30（遲到或中途離場的聽眾至中場休息方可入場，建議提早抵達）\r\n\r\n■地點：林建生紀念圖書館演奏廳（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額200位，七歲以上，免費報名入場。\r\n#恕無現場後補\r\n\r\n■報名方式：3月13 日（四）10:00 起，網路報名：　https://www.accupass.com/go/1140323\r\n\r\n■演出曲目：\r\n左岸印象、淚光閃閃、民歌組曲、雪落下的聲音、雪之華 、缺角地圖、阿爾罕布拉宮的回憶、南都夜曲、快樂的出航…等\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★歡迎加入Line 好友： https://bit.ly/2KFVgg2\r\n★網址： https://www.ljsedu.org.tw\r\n★粉絲專頁：https://www.facebook.com/linjiansheng\r\n', `organizer`='財團法人紀念林建生教育基金會', `address`='新北市蘆洲區三民路178號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='林建生紀念圖書館', `latitude`=25.08927173, `longitude`=121.4712461