INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6786ba0826b32458d4363697', '王若親薩克斯風獨奏音樂會', '無資料', '無資料', '高雄市苓雅區五福一路67號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '高雄市文化中心至善廳', 22.6257981, 120.31814, '100', 'https://ticket.com.tw/Application/UTK02/UTK0201_.aspx?PRODUCT_ID=P0RA4U9P', '[]') ON DUPLICATE KEY UPDATE `activity_name`='王若親薩克斯風獨奏音樂會', `description`='無資料', `organizer`='無資料', `address`='高雄市苓雅區五福一路67號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='高雄市文化中心至善廳', `latitude`=22.6257981, `longitude`=120.31814, `ticket_price`='100', `source_url`='https://ticket.com.tw/Application/UTK02/UTK0201_.aspx?PRODUCT_ID=P0RA4U9P', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6786d2df26b32458d436369e', '澎湖藝術家系列-「粉筆‧彩筆‧鄭獲義」特展', '鄭獲義（1902-1999）作為日治時期前輩藝術家之一，1924年前往高雄任教後定居，澎湖縣政府文化局於2023年進行了鄭獲義藝術史研究外，也將他當年贈予澎湖縣立文化中心(今澎湖縣政府文化局)之 12幅「澎湖鄉野之美」系列作品，委請彭雪芳修復師整飭展出。本展除了從文化局所典藏的「澎湖鄉野之美」系列精選作品外，也與其後代家屬鄭欣欣女士及白沙鄉鄭武雄前鄉長商借文物及作品，有難得一見的大正11年(1922年)「臺灣公學校教員免許狀」還有鄭獲義生前最後一張作品。讓民眾能認識鄭獲義的生平及藝術風格，也能符應到心理學的「需求層次理論」。\r\n', '澎湖縣政府', '澎湖縣馬公市中華路230號', '2025-01-01 00:00:00', '2025-03-09 00:00:00', '澎湖縣政府文化局', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='澎湖藝術家系列-「粉筆‧彩筆‧鄭獲義」特展', `description`='鄭獲義（1902-1999）作為日治時期前輩藝術家之一，1924年前往高雄任教後定居，澎湖縣政府文化局於2023年進行了鄭獲義藝術史研究外，也將他當年贈予澎湖縣立文化中心(今澎湖縣政府文化局)之 12幅「澎湖鄉野之美」系列作品，委請彭雪芳修復師整飭展出。本展除了從文化局所典藏的「澎湖鄉野之美」系列精選作品外，也與其後代家屬鄭欣欣女士及白沙鄉鄭武雄前鄉長商借文物及作品，有難得一見的大正11年(1922年)「臺灣公學校教員免許狀」還有鄭獲義生前最後一張作品。讓民眾能認識鄭獲義的生平及藝術風格，也能符應到心理學的「需求層次理論」。\r\n', `organizer`='澎湖縣政府', `address`='澎湖縣馬公市中華路230號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='澎湖縣政府文化局', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6786d2df26b32458d43636a2', '藝水千里～創禾雅集彩墨聯展', '本次展覽主題：藝水千里，藝術影響的層面的廣度和厚度如同潺潺流水延綿千里，細水長流一般，不僅廣泛且滲透至每一人生活中而不自覺，而且隨時間遞嬗而不絕。創禾雅集，由一群對水墨畫有興趣的人士參與展出，成員有退休校長、教授、主任、小學老師、自由業者，分別是林清鏡、王甘草、王苾芬、王玉琴、吳麗滿、邱淑惠、杜佳玲、林添生、郭勳章、許淑女、陳華守、陳碧戀、黃伴、詹珮琪、潘素珍等十五位學經歷豐富的藝術家，曾師承黃明山、林清鏡老師。他們秉持熱愛水墨畫的執著，透過水墨創作結識更多藝友，彼此切磋交流學習，藉此推廣水墨藝術。大家退休後離開職場，為充實生活，攜手用筆墨揮灑藝術人生，平時每月二次在彰化創禾教室與老師共學，假日到戶外寫生培養審美觀察力，拓展創作視野。', '國立水里高級商工職業學校', '南投縣水里鄉南湖路2號', '2025-01-02 00:00:00', '2025-02-27 00:00:00', '國立水里高級商工職業學校', 23.8063468, 120.8519197, '無資料', 'https://www.facebook.com/profile.php?id=100057098306038', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝水千里～創禾雅集彩墨聯展', `description`='本次展覽主題：藝水千里，藝術影響的層面的廣度和厚度如同潺潺流水延綿千里，細水長流一般，不僅廣泛且滲透至每一人生活中而不自覺，而且隨時間遞嬗而不絕。創禾雅集，由一群對水墨畫有興趣的人士參與展出，成員有退休校長、教授、主任、小學老師、自由業者，分別是林清鏡、王甘草、王苾芬、王玉琴、吳麗滿、邱淑惠、杜佳玲、林添生、郭勳章、許淑女、陳華守、陳碧戀、黃伴、詹珮琪、潘素珍等十五位學經歷豐富的藝術家，曾師承黃明山、林清鏡老師。他們秉持熱愛水墨畫的執著，透過水墨創作結識更多藝友，彼此切磋交流學習，藉此推廣水墨藝術。大家退休後離開職場，為充實生活，攜手用筆墨揮灑藝術人生，平時每月二次在彰化創禾教室與老師共學，假日到戶外寫生培養審美觀察力，拓展創作視野。', `organizer`='國立水里高級商工職業學校', `address`='南投縣水里鄉南湖路2號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='國立水里高級商工職業學校', `latitude`=23.8063468, `longitude`=120.8519197, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100057098306038', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6786d2df26b32458d43636a4', '造物星圖：工藝青年朝向自我實現的職人軌道', '當代工藝青年如同繁星，以各自的熱情與技藝，在浩瀚的工藝宇宙中開拓出屬於自己的軌跡。臺灣工藝青年特展《造物星圖：工藝青年朝向自我實現的職人軌道》展覽涵蓋六大主題區，包含「日常造物照起工」、「開工就是要開市」、「光環自造者」、「人人有功練的多重邊界」、「放光照耀著的恆星」及「一座藍海星圖的誕生」，呈現青年們如何在創作中找到自己的星軌道路。\r\n展覽共計邀請23位工藝青年及其53件作品展出，完整呈現臺灣工藝青年的創作樣貌，並透過職人故事展現時代精神，勾勒出臺灣當代工藝的群星圖景。邀請您透過這些青年創作，探索當代工藝並深入了解工藝背後的故事。', '國立臺灣工藝研究發展中心', '南投縣草屯鎮中正路573號', '2025-01-15 00:00:00', '2025-05-11 00:00:00', '國立臺灣工藝研究發展中心（臺灣工藝文化園區）', 23.9807747, 120.6918567, '無資料', 'https://www.ntcri.gov.tw/home/zh-tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='造物星圖：工藝青年朝向自我實現的職人軌道', `description`='當代工藝青年如同繁星，以各自的熱情與技藝，在浩瀚的工藝宇宙中開拓出屬於自己的軌跡。臺灣工藝青年特展《造物星圖：工藝青年朝向自我實現的職人軌道》展覽涵蓋六大主題區，包含「日常造物照起工」、「開工就是要開市」、「光環自造者」、「人人有功練的多重邊界」、「放光照耀著的恆星」及「一座藍海星圖的誕生」，呈現青年們如何在創作中找到自己的星軌道路。\r\n展覽共計邀請23位工藝青年及其53件作品展出，完整呈現臺灣工藝青年的創作樣貌，並透過職人故事展現時代精神，勾勒出臺灣當代工藝的群星圖景。邀請您透過這些青年創作，探索當代工藝並深入了解工藝背後的故事。', `organizer`='國立臺灣工藝研究發展中心', `address`='南投縣草屯鎮中正路573號', `start_date`='2025-01-15 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='國立臺灣工藝研究發展中心（臺灣工藝文化園區）', `latitude`=23.9807747, `longitude`=120.6918567, `ticket_price`='無資料', `source_url`='https://www.ntcri.gov.tw/home/zh-tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6787c5b407f3e62a5cec2f82', '靈性生態－看見愛的力量 2025年靈鷲山【四期教育】徵文辦法', '生命是一場分享的旅程，我們不僅努力淨化人心、淨化社會，更祈成就生命共享的世界。本屆徵文以四期教育和靈性生態為主題，期盼引領更多人分享佛法的生命智慧，以文字顯化生命之美，踏入靈性生態的宏觀世界。歡迎大眾踴躍參加，為社會的良善和諧貢獻一己之力。\r\n\r\n壹、宗旨\r\n\r\n(一)喚醒對靈性生命與生態的關懷，傳遞愛與守護地球的精神。\r\n(二)藉由學習佛法的實踐與分享，傳播正知、正見的生命價值觀。\r\n(三)透過徵文的正向主題，帶動社會良善與祥和的風氣。\r\n\r\n\r\n貳、辦理單位\r\n\r\n主辦單位：財團法人靈鷲山般若文教基金會\r\n承辦單位：靈鷲山教育院－慧命成長學院\r\n\r\n\r\n叁、徵文主題、對象、參考資料\r\n\r\n本屆徵文共分兩大主題與兩類投稿項目，參加者可挑選適合自己的項目進行投稿，若符合各項徵文條件，更歡迎全數參與，惟每個主題限投一篇，詳細說明如下：\r\n\r\n主題一、我所體會的靈性生態\r\n\r\n心道法師說：生命即是分享，靈性即是生態，一切本來就是和諧共生的。靈性就是愛心，是對人、對事、對一切都要有愛心。愛地球是生命共同的方向，是生命覺醒之後的再出發。每一個人都是地球的守護者，地球永續，人類才能永續。\r\n\r\n靈性生態是什麼？您是否找尋到這份愛的力量？不但改變了自己，更擴大了你的影響力！我們需要這份正向的力量，歡迎分享您的故事，一起為愛地球、愛和平而努力！\r\n\r\n●徵文對象：\r\n不限。\r\n\r\n參考資料：\r\n心道法師談靈性生態網頁：\r\nhttps://www.hsintao.org/spiritual\r\n\r\n主題二、四期教育與我\r\n\r\n學習靈鷲山成佛藍圖「四期教育」課程之後，透過將佛法的智慧融入生命，汲取深刻的啟發，並落實於生活中，邀請您譜寫出改變生命的精彩故事，見證佛法聞思修的智慧人生。\r\n\r\n●徵文對象：\r\n凡參加過靈鷲山【四期教育】課程之學員，無論是基礎課程《皈依三寶》、【阿含期】初階課程《', '靈鷲山般若文教基金會', '新北市靈鷲山教育網', '2025-01-01 00:00:00', '2025-05-01 00:00:00', '靈鷲山', 0, 0, '無資料', 'https://supr.link/PmyrO', '[]') ON DUPLICATE KEY UPDATE `activity_name`='靈性生態－看見愛的力量 2025年靈鷲山【四期教育】徵文辦法', `description`='生命是一場分享的旅程，我們不僅努力淨化人心、淨化社會，更祈成就生命共享的世界。本屆徵文以四期教育和靈性生態為主題，期盼引領更多人分享佛法的生命智慧，以文字顯化生命之美，踏入靈性生態的宏觀世界。歡迎大眾踴躍參加，為社會的良善和諧貢獻一己之力。\r\n\r\n壹、宗旨\r\n\r\n(一)喚醒對靈性生命與生態的關懷，傳遞愛與守護地球的精神。\r\n(二)藉由學習佛法的實踐與分享，傳播正知、正見的生命價值觀。\r\n(三)透過徵文的正向主題，帶動社會良善與祥和的風氣。\r\n\r\n\r\n貳、辦理單位\r\n\r\n主辦單位：財團法人靈鷲山般若文教基金會\r\n承辦單位：靈鷲山教育院－慧命成長學院\r\n\r\n\r\n叁、徵文主題、對象、參考資料\r\n\r\n本屆徵文共分兩大主題與兩類投稿項目，參加者可挑選適合自己的項目進行投稿，若符合各項徵文條件，更歡迎全數參與，惟每個主題限投一篇，詳細說明如下：\r\n\r\n主題一、我所體會的靈性生態\r\n\r\n心道法師說：生命即是分享，靈性即是生態，一切本來就是和諧共生的。靈性就是愛心，是對人、對事、對一切都要有愛心。愛地球是生命共同的方向，是生命覺醒之後的再出發。每一個人都是地球的守護者，地球永續，人類才能永續。\r\n\r\n靈性生態是什麼？您是否找尋到這份愛的力量？不但改變了自己，更擴大了你的影響力！我們需要這份正向的力量，歡迎分享您的故事，一起為愛地球、愛和平而努力！\r\n\r\n●徵文對象：\r\n不限。\r\n\r\n參考資料：\r\n心道法師談靈性生態網頁：\r\nhttps://www.hsintao.org/spiritual\r\n\r\n主題二、四期教育與我\r\n\r\n學習靈鷲山成佛藍圖「四期教育」課程之後，透過將佛法的智慧融入生命，汲取深刻的啟發，並落實於生活中，邀請您譜寫出改變生命的精彩故事，見證佛法聞思修的智慧人生。\r\n\r\n●徵文對象：\r\n凡參加過靈鷲山【四期教育】課程之學員，無論是基礎課程《皈依三寶》、【阿含期】初階課程《', `organizer`='靈鷲山般若文教基金會', `address`='新北市靈鷲山教育網', `start_date`='2025-01-01 00:00:00', `end_date`='2025-05-01 00:00:00', `location`='靈鷲山', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://supr.link/PmyrO', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6787ca7507f3e62a5cec2f83', '2025【四期教育】基礎：《皈依三寶》線上課程', '從皈依三寶、學習佛法開始，從現在去創造好的因，讓未來結出好的果，長遠的離苦得樂。 ~心道法師 法語\r\n\r\n什麼是皈依？皈依誰？皈依後要做什麼？佛門有什麼規矩？對於一個佛教徒而言，什麼是學佛之後可以做的學習？\r\n\r\n【阿含期】基礎：皈依三寶 是學佛入門的指南針。\r\n\r\n從認識「皈依」的意義，之後介紹皈依的對象「禮敬三寶-佛寶」，講述佛的名號等，令學員生起信心從而學習；「禮敬三寶-法寶」，了解法的功德與修學法寶的方法等；「禮敬三寶-僧寶」當中，有僧伽的使命、功德、與恭敬之方；還有學習生活上的「佛門行儀」教授，從行住坐臥四威儀、合掌、禮拜、拿香、入佛殿…等，瞭解每個動作的意涵與背後義理的精神所在。\r\n\r\n【阿含期】基礎：皈依三寶 線上課程(第六梯)\r\n授課講師：寶祥法師\r\n開課時間：2025年1月8日～11月26日\r\n課程時數：共10單元\r\n報名截止：2025年10月29日', '靈鷲山教育院', '臺北市全球線上', '2025-01-08 00:00:00', '2025-11-26 00:00:00', '靈鷲山教育院', 0, 0, '無資料', 'https://weborder.ljm.org.tw/order/Act_detail?PK=114U05_D07CN22201&type=3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025【四期教育】基礎：《皈依三寶》線上課程', `description`='從皈依三寶、學習佛法開始，從現在去創造好的因，讓未來結出好的果，長遠的離苦得樂。 ~心道法師 法語\r\n\r\n什麼是皈依？皈依誰？皈依後要做什麼？佛門有什麼規矩？對於一個佛教徒而言，什麼是學佛之後可以做的學習？\r\n\r\n【阿含期】基礎：皈依三寶 是學佛入門的指南針。\r\n\r\n從認識「皈依」的意義，之後介紹皈依的對象「禮敬三寶-佛寶」，講述佛的名號等，令學員生起信心從而學習；「禮敬三寶-法寶」，了解法的功德與修學法寶的方法等；「禮敬三寶-僧寶」當中，有僧伽的使命、功德、與恭敬之方；還有學習生活上的「佛門行儀」教授，從行住坐臥四威儀、合掌、禮拜、拿香、入佛殿…等，瞭解每個動作的意涵與背後義理的精神所在。\r\n\r\n【阿含期】基礎：皈依三寶 線上課程(第六梯)\r\n授課講師：寶祥法師\r\n開課時間：2025年1月8日～11月26日\r\n課程時數：共10單元\r\n報名截止：2025年10月29日', `organizer`='靈鷲山教育院', `address`='臺北市全球線上', `start_date`='2025-01-08 00:00:00', `end_date`='2025-11-26 00:00:00', `location`='靈鷲山教育院', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://weborder.ljm.org.tw/order/Act_detail?PK=114U05_D07CN22201&type=3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6787cc1e07f3e62a5cec2f84', '2025 四期教育【阿含期】初階《初轉之法》線上課程', '佛陀是誰？佛法教導些什麼？\r\n佛法對我的生命有什麼幫助？\r\n\r\n佛陀在人間初次的教導，會是解答這些問題很好的入口！2500多年前，歷經長時修行，最終在菩提樹下覺悟生命真相的佛陀，為人間最先帶來了四聖諦、八正道等教法。\r\n\r\n這些教導，提綱挈領地總攝了離苦得樂的智慧，也為我們帶來解脫的修行方法。\r\n\r\n從《初轉之法》課程中，我們將和佛陀一起反思生命充滿的各種辛苦、不圓滿。\r\n\r\n生命確實時時刻刻都必須面對不安穩與變化。苦的背後，則是從我們那習慣於追求更多、緊抓不放的「渴愛」所推動、產生的。\r\n\r\n就在眾生面對著一切都將消散、變化，卻又不知如何是好的迷惘時，佛陀指引了一條轉化生命的道路，引領我們熄滅苦因，超越一切生滅與苦痛。\r\n\r\n這條道路，通往那真正沒有煩惱、悲傷的清涼之處。\r\n\r\n【阿含期】初階：初轉之法 線上課程第八梯\r\n課程講師：了意法師、妙足法師、淨華法師\r\n開課時間：2025年1月8日-11月26日\r\n課程時數：共16單元\r\n報名截止：2025年10月29日', '靈鷲山教育院', '新北市全球線上', '2025-01-08 00:00:00', '2025-11-26 00:00:00', '靈鷲山教育網', 0, 0, '無資料', 'https://weborder.ljm.org.tw/order/Act_detail?PK=114U05_D07CN01601&type=3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 四期教育【阿含期】初階《初轉之法》線上課程', `description`='佛陀是誰？佛法教導些什麼？\r\n佛法對我的生命有什麼幫助？\r\n\r\n佛陀在人間初次的教導，會是解答這些問題很好的入口！2500多年前，歷經長時修行，最終在菩提樹下覺悟生命真相的佛陀，為人間最先帶來了四聖諦、八正道等教法。\r\n\r\n這些教導，提綱挈領地總攝了離苦得樂的智慧，也為我們帶來解脫的修行方法。\r\n\r\n從《初轉之法》課程中，我們將和佛陀一起反思生命充滿的各種辛苦、不圓滿。\r\n\r\n生命確實時時刻刻都必須面對不安穩與變化。苦的背後，則是從我們那習慣於追求更多、緊抓不放的「渴愛」所推動、產生的。\r\n\r\n就在眾生面對著一切都將消散、變化，卻又不知如何是好的迷惘時，佛陀指引了一條轉化生命的道路，引領我們熄滅苦因，超越一切生滅與苦痛。\r\n\r\n這條道路，通往那真正沒有煩惱、悲傷的清涼之處。\r\n\r\n【阿含期】初階：初轉之法 線上課程第八梯\r\n課程講師：了意法師、妙足法師、淨華法師\r\n開課時間：2025年1月8日-11月26日\r\n課程時數：共16單元\r\n報名截止：2025年10月29日', `organizer`='靈鷲山教育院', `address`='新北市全球線上', `start_date`='2025-01-08 00:00:00', `end_date`='2025-11-26 00:00:00', `location`='靈鷲山教育網', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://weborder.ljm.org.tw/order/Act_detail?PK=114U05_D07CN01601&type=3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6787ce0b07f3e62a5cec2f85', '2025 四期教育【阿含期】進階：《無我之道》線上課程', '先看清楚「我」到底是什麼？\r\n\r\n當明瞭之後，才能把「我」放下，真正體會「無我」的快樂。 —心道法師\r\n\r\n無始以來，眾生認定執取恆常、主宰有「我」，而受盡生艱苦，有如肩負重擔，流浪生死，無有出期。\r\n\r\n佛陀的「無我」教導，讓我們了解生命輪迴的緣起，學習熄滅渴愛與苦，如實了知生命實相，獲得「無我」的解脫智慧，如捨離重擔的快樂生命。\r\n\r\n靈鷲山成佛藍圖 四期教育\r\n\r\n🍀【四期教育】進階：無我之道 線上課程 第五梯\r\n\r\n開課時間：2025年1月8日-11月26日\r\n課程講師：了意法師、顯月法師、常存法師、淨華法師、寶祥法師\r\n課程時數：共10單元\r\n報名截止：2025年10月29日', '靈鷲山教育院', '新北市全球線上', '2025-01-08 00:00:00', '2025-11-26 00:00:00', '靈鷲山教育網', 0, 0, '無資料', 'https://weborder.ljm.org.tw/order/Act_detail?PK=114U05_D07CN02001&type=3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 四期教育【阿含期】進階：《無我之道》線上課程', `description`='先看清楚「我」到底是什麼？\r\n\r\n當明瞭之後，才能把「我」放下，真正體會「無我」的快樂。 —心道法師\r\n\r\n無始以來，眾生認定執取恆常、主宰有「我」，而受盡生艱苦，有如肩負重擔，流浪生死，無有出期。\r\n\r\n佛陀的「無我」教導，讓我們了解生命輪迴的緣起，學習熄滅渴愛與苦，如實了知生命實相，獲得「無我」的解脫智慧，如捨離重擔的快樂生命。\r\n\r\n靈鷲山成佛藍圖 四期教育\r\n\r\n🍀【四期教育】進階：無我之道 線上課程 第五梯\r\n\r\n開課時間：2025年1月8日-11月26日\r\n課程講師：了意法師、顯月法師、常存法師、淨華法師、寶祥法師\r\n課程時數：共10單元\r\n報名截止：2025年10月29日', `organizer`='靈鷲山教育院', `address`='新北市全球線上', `start_date`='2025-01-08 00:00:00', `end_date`='2025-11-26 00:00:00', `location`='靈鷲山教育網', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://weborder.ljm.org.tw/order/Act_detail?PK=114U05_D07CN02001&type=3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6787cf4c07f3e62a5cec2f86', '2025 四期教育【阿含期】高階：《解脫之門》線上課程', '佛法是一種體驗、證悟，當我們開始用心歷練、體認，慢慢地醞釀，讓我們的心得到證明，進而解脫我們的煩惱。~心道法師 \r\n\r\n阿含期高階「解脫之門」課程，課程介紹：\r\n\r\n從初階《初轉之法》，佛陀教導了四聖諦、八正道，令眾生明瞭如何離兩端、行中道來出離苦。在進階《無我之道》，教導眾生明白對於身心現象的無常、苦、無我，從十二因緣的流轉還滅了知生命的緣起正見，教導如何放下五取蘊的生命重擔。到了高階《解脫之門》，以佛陀因應眾生各式問題所教導的三十七道品，善巧引導眾生走向解脫之道，正是佛陀的教法最為珍貴之處。\r\n\r\n就像大海中藏有種種珍寶，三十七道品，正是佛法中的珍貴寶物。實踐道品，能夠啟發如實知見，讓一切煩惱隨之消滅！\r\n\r\n分為七組的道品，以不同的方式幫助修學者進步，不論是生活方式，還是學佛應具備的態度，到深刻的止觀禪修指引，能夠幫助學習者的道業進展，也能用來檢視、調整自己的修行方法。\r\n\r\n學習道品，就像是打開一扇扇通往解脫的門戶。就讓我們一起透過《解脫之門》，來尋找佛陀留給我們的寶藏吧！\r\n\r\n 【阿含期】高階：解脫之門 線上課程(第四梯)\r\n\r\n授課講師：常存法師、廣純法師、恆明法師、顯月法師、妙足法師、淨華法師、寶祥法師\r\n開課時間：2025年1月8日-11月26日\r\n課程時數：共12單元\r\n報名截止：2025年10月29日', '靈鷲山教育院', '臺北市全球線上', '2025-01-08 00:00:00', '2025-11-26 00:00:00', '靈鷲山數位學習網 和 妙心摩尼寶APP', 0, 0, '無資料', 'https://weborder.ljm.org.tw/order/Act_detail?PK=114U05_D07CN19201&type=3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 四期教育【阿含期】高階：《解脫之門》線上課程', `description`='佛法是一種體驗、證悟，當我們開始用心歷練、體認，慢慢地醞釀，讓我們的心得到證明，進而解脫我們的煩惱。~心道法師 \r\n\r\n阿含期高階「解脫之門」課程，課程介紹：\r\n\r\n從初階《初轉之法》，佛陀教導了四聖諦、八正道，令眾生明瞭如何離兩端、行中道來出離苦。在進階《無我之道》，教導眾生明白對於身心現象的無常、苦、無我，從十二因緣的流轉還滅了知生命的緣起正見，教導如何放下五取蘊的生命重擔。到了高階《解脫之門》，以佛陀因應眾生各式問題所教導的三十七道品，善巧引導眾生走向解脫之道，正是佛陀的教法最為珍貴之處。\r\n\r\n就像大海中藏有種種珍寶，三十七道品，正是佛法中的珍貴寶物。實踐道品，能夠啟發如實知見，讓一切煩惱隨之消滅！\r\n\r\n分為七組的道品，以不同的方式幫助修學者進步，不論是生活方式，還是學佛應具備的態度，到深刻的止觀禪修指引，能夠幫助學習者的道業進展，也能用來檢視、調整自己的修行方法。\r\n\r\n學習道品，就像是打開一扇扇通往解脫的門戶。就讓我們一起透過《解脫之門》，來尋找佛陀留給我們的寶藏吧！\r\n\r\n 【阿含期】高階：解脫之門 線上課程(第四梯)\r\n\r\n授課講師：常存法師、廣純法師、恆明法師、顯月法師、妙足法師、淨華法師、寶祥法師\r\n開課時間：2025年1月8日-11月26日\r\n課程時數：共12單元\r\n報名截止：2025年10月29日', `organizer`='靈鷲山教育院', `address`='臺北市全球線上', `start_date`='2025-01-08 00:00:00', `end_date`='2025-11-26 00:00:00', `location`='靈鷲山數位學習網 和 妙心摩尼寶APP', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://weborder.ljm.org.tw/order/Act_detail?PK=114U05_D07CN19201&type=3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6787d26007f3e62a5cec2f87', '2025四期教育【般若期】初階：《智慧之本》線上課程', '【般若期】初階:智慧之本線上課程(第一梯)\r\n\r\n般若是什麼？般若是佛法的根本智慧，它是超越語言文字的。\r\n修學般若的歷程，先從文字理解般若是什麼，再從觀照進入般若的實修，最後證入空性，從空性起悲心而實踐菩薩道。\r\n這才是真實的般若智慧,這時才是回到心的本來。\r\n\r\n授課講師：恆明法師\r\n開課時間：2025年1月8日-11月26日(共7章節)\r\n報名截止：2025年10月29日\r\n課程時數：共７單元', '靈鷲山教育院', '新北市全球線上', '2025-01-08 00:00:00', '2025-11-26 00:00:00', '靈鷲山教育網', 0, 0, '無資料', 'https://weborder.ljm.org.tw/order/Act_detail?PK=112U05_D07CN28501&type=3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025四期教育【般若期】初階：《智慧之本》線上課程', `description`='【般若期】初階:智慧之本線上課程(第一梯)\r\n\r\n般若是什麼？般若是佛法的根本智慧，它是超越語言文字的。\r\n修學般若的歷程，先從文字理解般若是什麼，再從觀照進入般若的實修，最後證入空性，從空性起悲心而實踐菩薩道。\r\n這才是真實的般若智慧,這時才是回到心的本來。\r\n\r\n授課講師：恆明法師\r\n開課時間：2025年1月8日-11月26日(共7章節)\r\n報名截止：2025年10月29日\r\n課程時數：共７單元', `organizer`='靈鷲山教育院', `address`='新北市全球線上', `start_date`='2025-01-08 00:00:00', `end_date`='2025-11-26 00:00:00', `location`='靈鷲山教育網', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://weborder.ljm.org.tw/order/Act_detail?PK=112U05_D07CN28501&type=3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6787d85a07f3e62a5cec2f88', '翻轉DNA－生命體驗小旅行 開始報名！', '#台灣東北角最美的生命體驗小旅行\r\n\r\n你是否曾經好奇：人生的意義是什麼？\r\n你是否渴望：在自然與心靈中找到全新的自己？\r\n你曾想過DNA也能翻轉嗎？\r\n\r\n靈鷲山誠摯邀請您，加入這場充滿驚喜的生命探索之旅\r\n👉「翻轉DNA—靈鷲山生命體驗小旅行」 \r\n\r\n這是一份為您精心設計的專屬行程，在充滿靈性與自然之美的「靈鷲山無生道場」，迎接全新的自己！\r\n\r\n走進象徵「虛空之眼」的天眼門，踏上蜿蜒的翠綠步道，迎風撲鼻的海味，一眼望去是令人心曠神怡的天海美景，過完年，送給自己一趟身心靈的洗禮。\r\n\r\n#小旅行一次體驗五大亮點：\r\n\r\n【第一站】好久不見，我是誰？\r\n透過體驗探索「我」的真實意義，覺察輪迴中的自我定位。\r\n\r\n【第二站】你我他的翻轉因緣網：\r\n探討生命課題的來源與解決方法，見證生命共同體的因緣之網。\r\n\r\n【第三站】生老病死的大體教室：\r\n面對生命課題，學習靈性智慧，調整對生老病死的態度，活得更自在。\r\n\r\n【第四站】DNA創作珠玉之網：\r\n透過創作過程，看見心念交織的因緣網，反思生命價值，創造靈性生態的美好。\r\n\r\n【第五站】翻轉秘笈的神奇寶貝：\r\n以生命智慧翻轉心念，啟動善能量，實踐三好善業，活出美好人生。\r\n\r\n#翻轉DNA體驗行程多元生動\r\n\r\n靈鷲山開山大和尚心道法師曾說：生命中發生的一切，都是心念而生的因果，心念就是DNA，心念就是記憶體。\r\n邀請您在新的一年，透過互動體驗、創作活動、情境劇場，讓翻轉DNA智慧融入生活吧！', '靈鷲山教育院', '花蓮縣花蓮市富安路65之1號2樓', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '靈鷲山花蓮中心', 0, 0, '無資料', 'https://weborder.ljm.org.tw/order/Act_detail?PK=114U05_D07CN3167&type=3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='翻轉DNA－生命體驗小旅行 開始報名！', `description`='#台灣東北角最美的生命體驗小旅行\r\n\r\n你是否曾經好奇：人生的意義是什麼？\r\n你是否渴望：在自然與心靈中找到全新的自己？\r\n你曾想過DNA也能翻轉嗎？\r\n\r\n靈鷲山誠摯邀請您，加入這場充滿驚喜的生命探索之旅\r\n👉「翻轉DNA—靈鷲山生命體驗小旅行」 \r\n\r\n這是一份為您精心設計的專屬行程，在充滿靈性與自然之美的「靈鷲山無生道場」，迎接全新的自己！\r\n\r\n走進象徵「虛空之眼」的天眼門，踏上蜿蜒的翠綠步道，迎風撲鼻的海味，一眼望去是令人心曠神怡的天海美景，過完年，送給自己一趟身心靈的洗禮。\r\n\r\n#小旅行一次體驗五大亮點：\r\n\r\n【第一站】好久不見，我是誰？\r\n透過體驗探索「我」的真實意義，覺察輪迴中的自我定位。\r\n\r\n【第二站】你我他的翻轉因緣網：\r\n探討生命課題的來源與解決方法，見證生命共同體的因緣之網。\r\n\r\n【第三站】生老病死的大體教室：\r\n面對生命課題，學習靈性智慧，調整對生老病死的態度，活得更自在。\r\n\r\n【第四站】DNA創作珠玉之網：\r\n透過創作過程，看見心念交織的因緣網，反思生命價值，創造靈性生態的美好。\r\n\r\n【第五站】翻轉秘笈的神奇寶貝：\r\n以生命智慧翻轉心念，啟動善能量，實踐三好善業，活出美好人生。\r\n\r\n#翻轉DNA體驗行程多元生動\r\n\r\n靈鷲山開山大和尚心道法師曾說：生命中發生的一切，都是心念而生的因果，心念就是DNA，心念就是記憶體。\r\n邀請您在新的一年，透過互動體驗、創作活動、情境劇場，讓翻轉DNA智慧融入生活吧！', `organizer`='靈鷲山教育院', `address`='花蓮縣花蓮市富安路65之1號2樓', `start_date`='2025-03-29 00:00:00'