INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678822f426b32458d43636b3', '造物星圖－工藝青年朝向自我實現的職人軌道', '《造物星圖：工藝青年朝向自我實現的職人軌道》展覽，為國立臺灣工藝研究發展中心邁向70週年的重要延續，圍繞工藝「漫活SLOHAS」理念，融合智慧、美學與永續的生活價值。展覽以當代工藝青年為核心，勾畫出屬於他們的工藝宇宙，呈現臺灣工藝從傳承到創新的活力與發展。\n\n \n\n展覽分為六大主題區域，包括「日常造物照起工」、「開工就是要開市」、「光環自造者」、「人人有功練的多重邊界」、「放光照耀著的恆星」，以及「一座藍海星圖的誕生」，帶領觀眾探索工藝青年如何結合地域文化、創意科技與實驗精神，從日常素材出發，創作出與地方深度聯結的作品，並實現傳統技藝的創新突破。同時亦揭示工藝青年在經濟創新、技藝精進與社會責任上的多面實踐。他們透過募資、市集和跨國銷售開創個人經濟軌跡，跨越學科與文化界限，注入多元創作養分，並以作品回應社會需求，推動文化傳承與地方工藝復興。最終，以「藍海星圖」象徵當代工藝青年的發展軌跡，描繪一幅廣闊且充滿未來可能性的圖景。\n\n \n\n《造物星圖：工藝青年朝向自我實現的職人軌道》展覽共展出23位工藝青年、53件作品，呈現他們如何在創作中找到自己的星軌道路，並以開放視角引領觀眾，從作品出發深入探索材質、技術與創作背後的故事，見證工藝青年如何透過創作點亮屬於自己的星軌，並為工藝未來開啟全新價值。\n\n \n\n展覽資訊\n\n造物星圖－工藝青年朝向自我實現的職人軌道\n\n展覽日期：2025年1月15日至5月11日\n\n展覽時間：每週二至週日 09:00-17:00 \n\n展覽地點：工藝設計館1-2樓\n\n ', '國立台灣工藝研究發展中心', '無資料', '2025-01-15 00:00:00', '2025-05-11 00:00:00', '工藝設計館1-2樓', 0, 0, '無資料', 'https://event.culture.tw/mocweb/reg/NTCRI/Detail.init.ctr?actId=50125', '[]') ON DUPLICATE KEY UPDATE `activity_name`='造物星圖－工藝青年朝向自我實現的職人軌道', `description`='《造物星圖：工藝青年朝向自我實現的職人軌道》展覽，為國立臺灣工藝研究發展中心邁向70週年的重要延續，圍繞工藝「漫活SLOHAS」理念，融合智慧、美學與永續的生活價值。展覽以當代工藝青年為核心，勾畫出屬於他們的工藝宇宙，呈現臺灣工藝從傳承到創新的活力與發展。\n\n \n\n展覽分為六大主題區域，包括「日常造物照起工」、「開工就是要開市」、「光環自造者」、「人人有功練的多重邊界」、「放光照耀著的恆星」，以及「一座藍海星圖的誕生」，帶領觀眾探索工藝青年如何結合地域文化、創意科技與實驗精神，從日常素材出發，創作出與地方深度聯結的作品，並實現傳統技藝的創新突破。同時亦揭示工藝青年在經濟創新、技藝精進與社會責任上的多面實踐。他們透過募資、市集和跨國銷售開創個人經濟軌跡，跨越學科與文化界限，注入多元創作養分，並以作品回應社會需求，推動文化傳承與地方工藝復興。最終，以「藍海星圖」象徵當代工藝青年的發展軌跡，描繪一幅廣闊且充滿未來可能性的圖景。\n\n \n\n《造物星圖：工藝青年朝向自我實現的職人軌道》展覽共展出23位工藝青年、53件作品，呈現他們如何在創作中找到自己的星軌道路，並以開放視角引領觀眾，從作品出發深入探索材質、技術與創作背後的故事，見證工藝青年如何透過創作點亮屬於自己的星軌，並為工藝未來開啟全新價值。\n\n \n\n展覽資訊\n\n造物星圖－工藝青年朝向自我實現的職人軌道\n\n展覽日期：2025年1月15日至5月11日\n\n展覽時間：每週二至週日 09:00-17:00 \n\n展覽地點：工藝設計館1-2樓\n\n ', `organizer`='國立台灣工藝研究發展中心', `address`='無資料', `start_date`='2025-01-15 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='工藝設計館1-2樓', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTCRI/Detail.init.ctr?actId=50125', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788235d26b32458d43636b8', ' bulabulay ‧原民之耀-臺灣原住民族經典文物聯展暨巡迴展', 'bulabulay ‧原民之耀-臺灣原住民族經典文物聯展暨巡迴展\r\n★展覽時間：2024.11.15(五)-2025.07.31(四)\r\n週二至週六09:30 ~ 17:00，週一、日與國定假日休館\r\n★定時導覽：週六上午10:00、下午14:00\r\n★團體導覽：10人以上，20以下團體得以申請。\r\n臺灣原住民族文化與史前文化的淵源，自日治時期起始，就廣受重視。\r\nbulabulay 原民之耀首展規劃五大展區，結合19座公私立博物館、6 位部落族人及資深收藏家等之特定文物，讓大家看到南島文化圈中擁有深厚內涵的臺灣原住民族文化資產，看到原住民族跨越傳統與當代之經典文物所傳達「文化之深、原民之耀」的臺灣精神。\r\n----\r\n協辦單位 (依筆劃排序)\r\n文化部文化資產局、中央研究院民族學研究所、中央研究院歷史語言研究所、中華民國博物館學會、北投文物館、東南科技大學、宜蘭縣立蘭陽博物館、屏東縣政府、原住民族委員會原住民族文化發展中心、高雄市立歷史博物館、財團法人原住民族文化事業基金會、財團法人富邦文教基金會、國立自然科學博物館、國立故宮博物院、國立臺灣大學人類學博物館、國立臺灣史前文化博物館、國立臺灣博物館、國立臺灣圖書館、國立臺灣歷史博物館、國立歷史博物館、國史館臺灣文獻館、順益台灣原住民博物館、雅凱藝術事業有限公司、新北市立十三行博物館、臺北市立文獻館、臺北市立動物園、臺東縣政府文化處、輔仁大學織品服裝學系中華服飾文化中心\r\n特別感謝 (依筆劃排序)\r\n小島大歌影音工作室、少多宜‧篩代先生、巴淑嫻女士、王煒昶先生、朱正宜先生、沈文伶Ljuzem Djubelang Djakudjakuc 女士、何秀蘭Dungi Banil 女士、李玟慧O’ol Kacaw小姐、李赫先生、李賢文先生、南天書局魏德文先生、屏東縣來義鄉望嘉部落羅俊傑tjaluljivak‧tjanubak先生、屏東縣泰武鄉佳平部落莊德才adrucangalj‧taluviljav先生、屏東縣霧臺鄉神山部落趙燕芬Zuluzulu‧Aputwane女士、國立清華大學人類學研究所邱鴻霖副教授、國立臺灣大學生態學與演化生物學研究所胡哲明教授與蔡政修副教授、黃百興先生、陳俊臣先生、張谷源先生、翔輝運通股份有限公司、臺北市政府原住民族事務委員會凱達格蘭文化館、楊政賢先生、楊政賢先生、廖清福先生、鄭惠中先生、鄭博仁先生', '財團法人福祿文化基金會', '臺北市大安區羅斯福路4段1號', '2025-01-01 00:00:00', '2025-07-31 00:00:00', '國立臺灣大學校史館', 25.02677012, 121.5434446, '無資料', 'https://bulabulay.com', '[]') ON DUPLICATE KEY UPDATE `activity_name`=' bulabulay ‧原民之耀-臺灣原住民族經典文物聯展暨巡迴展', `description`='bulabulay ‧原民之耀-臺灣原住民族經典文物聯展暨巡迴展\r\n★展覽時間：2024.11.15(五)-2025.07.31(四)\r\n週二至週六09:30 ~ 17:00，週一、日與國定假日休館\r\n★定時導覽：週六上午10:00、下午14:00\r\n★團體導覽：10人以上，20以下團體得以申請。\r\n臺灣原住民族文化與史前文化的淵源，自日治時期起始，就廣受重視。\r\nbulabulay 原民之耀首展規劃五大展區，結合19座公私立博物館、6 位部落族人及資深收藏家等之特定文物，讓大家看到南島文化圈中擁有深厚內涵的臺灣原住民族文化資產，看到原住民族跨越傳統與當代之經典文物所傳達「文化之深、原民之耀」的臺灣精神。\r\n----\r\n協辦單位 (依筆劃排序)\r\n文化部文化資產局、中央研究院民族學研究所、中央研究院歷史語言研究所、中華民國博物館學會、北投文物館、東南科技大學、宜蘭縣立蘭陽博物館、屏東縣政府、原住民族委員會原住民族文化發展中心、高雄市立歷史博物館、財團法人原住民族文化事業基金會、財團法人富邦文教基金會、國立自然科學博物館、國立故宮博物院、國立臺灣大學人類學博物館、國立臺灣史前文化博物館、國立臺灣博物館、國立臺灣圖書館、國立臺灣歷史博物館、國立歷史博物館、國史館臺灣文獻館、順益台灣原住民博物館、雅凱藝術事業有限公司、新北市立十三行博物館、臺北市立文獻館、臺北市立動物園、臺東縣政府文化處、輔仁大學織品服裝學系中華服飾文化中心\r\n特別感謝 (依筆劃排序)\r\n小島大歌影音工作室、少多宜‧篩代先生、巴淑嫻女士、王煒昶先生、朱正宜先生、沈文伶Ljuzem Djubelang Djakudjakuc 女士、何秀蘭Dungi Banil 女士、李玟慧O’ol Kacaw小姐、李赫先生、李賢文先生、南天書局魏德文先生、屏東縣來義鄉望嘉部落羅俊傑tjaluljivak‧tjanubak先生、屏東縣泰武鄉佳平部落莊德才adrucangalj‧taluviljav先生、屏東縣霧臺鄉神山部落趙燕芬Zuluzulu‧Aputwane女士、國立清華大學人類學研究所邱鴻霖副教授、國立臺灣大學生態學與演化生物學研究所胡哲明教授與蔡政修副教授、黃百興先生、陳俊臣先生、張谷源先生、翔輝運通股份有限公司、臺北市政府原住民族事務委員會凱達格蘭文化館、楊政賢先生、楊政賢先生、廖清福先生、鄭惠中先生、鄭博仁先生', `organizer`='財團法人福祿文化基金會', `address`='臺北市大安區羅斯福路4段1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-07-31 00:00:00', `location`='國立臺灣大學校史館', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='無資料', `source_url`='https://bulabulay.com', `image_url`='[]';
