INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788236526b32458d43636c0', '臺中市立圖書館興安分館~ 手機攝影展覽-視域追憶', '蔡楨永老師與臺中市潭雅神社大、臺中市后豐社大的學員，在興安分館3樓藝文走廊舉辦手機攝影成果展。\r\n一同來欣賞透過學員們的定格影像，從拍攝者的視角進行視覺探索，喚醒藏在腦中的經驗與記憶。', '臺中市立圖書館興安分館', '臺中市北屯區興安路一段162號', '2025-01-05 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館興安分館', 24.18400298, 120.7362319, '無資料', 'https://reurl.cc/genaYR', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館興安分館~ 手機攝影展覽-視域追憶', `description`='蔡楨永老師與臺中市潭雅神社大、臺中市后豐社大的學員，在興安分館3樓藝文走廊舉辦手機攝影成果展。\r\n一同來欣賞透過學員們的定格影像，從拍攝者的視角進行視覺探索，喚醒藏在腦中的經驗與記憶。', `organizer`='臺中市立圖書館興安分館', `address`='臺中市北屯區興安路一段162號', `start_date`='2025-01-05 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館興安分館', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://reurl.cc/genaYR', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788236626b32458d43636c5', '轉角遇見大師-陳誼芝作品展', '陳誼芝老師，常自稱「迷花」不事君，原名陳怡，字怡之，二○○五年改名為誼芝。畢業於省立臺北師範藝術科、國立師範大學歷史系(五七級)。國立臺中二中教師退休，曾任中部美展國畫部評審，逢甲大學及臺中市文英館、圖書館之國畫教師，藝術家俱樂部一九九五年會長、臺中市華藝女子畫會理事長、中華書畫藝術同心會、臺灣發展研究院及救國團之國畫教師。一九七七年於省立圖書館第一次個展，之後與夫婿張自強校長舉辦伉儷聯展約廿餘次(於高雄圖書館、臺中市文化中心等地展出，其中並數次為臺中啟明學校、國立豐原高中舉辦愛心義賣活動)。陳誼芝老師除個展及伉儷聯展外，並曾與其學生舉辦師生國畫展十餘次，可謂桃李成蹊矣。\r\n陳誼芝老師自一九五八年入北師藝術科，至今從事藝術創作已逾半世紀，人生角色上歷經：人女、人妻、人媳、人母及人師，艱辛挫折在所難免，而能一路平安走到現在，藝術創作對她的精神支撐功不可沒，可以這麼說：「沒有藝術就沒有現在的她」。夫婿張自強也非常支持，常帶她外出寫生，杉林溪的牡丹、溪湖的玉蘭花、公老坪的腊腸樹、公館的紅棗、官田的菱角、白河的荷花，不勝枚舉。此次展覽作品呈現其遊歷與日常所感，豐富精彩。', '臺中市屯區藝文中心', '臺中市太平區大興路201號', '2025-01-18 00:00:00', '2025-04-27 00:00:00', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', 'https://www.ttdac.taichung.gov.tw/nb5179850309094569475/nbArticleContent', '[]') ON DUPLICATE KEY UPDATE `activity_name`='轉角遇見大師-陳誼芝作品展', `description`='陳誼芝老師，常自稱「迷花」不事君，原名陳怡，字怡之，二○○五年改名為誼芝。畢業於省立臺北師範藝術科、國立師範大學歷史系(五七級)。國立臺中二中教師退休，曾任中部美展國畫部評審，逢甲大學及臺中市文英館、圖書館之國畫教師，藝術家俱樂部一九九五年會長、臺中市華藝女子畫會理事長、中華書畫藝術同心會、臺灣發展研究院及救國團之國畫教師。一九七七年於省立圖書館第一次個展，之後與夫婿張自強校長舉辦伉儷聯展約廿餘次(於高雄圖書館、臺中市文化中心等地展出，其中並數次為臺中啟明學校、國立豐原高中舉辦愛心義賣活動)。陳誼芝老師除個展及伉儷聯展外，並曾與其學生舉辦師生國畫展十餘次，可謂桃李成蹊矣。\r\n陳誼芝老師自一九五八年入北師藝術科，至今從事藝術創作已逾半世紀，人生角色上歷經：人女、人妻、人媳、人母及人師，艱辛挫折在所難免，而能一路平安走到現在，藝術創作對她的精神支撐功不可沒，可以這麼說：「沒有藝術就沒有現在的她」。夫婿張自強也非常支持，常帶她外出寫生，杉林溪的牡丹、溪湖的玉蘭花、公老坪的腊腸樹、公館的紅棗、官田的菱角、白河的荷花，不勝枚舉。此次展覽作品呈現其遊歷與日常所感，豐富精彩。', `organizer`='臺中市屯區藝文中心', `address`='臺中市太平區大興路201號', `start_date`='2025-01-18 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='https://www.ttdac.taichung.gov.tw/nb5179850309094569475/nbArticleContent', `image_url`='[]';
