INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788236926b32458d43636d5', '葉石濤文學紀念館特展「尼德蘭畫師藝術重構─Dutch Masters Reimagined」', '為紀念臺南400，表彰臺灣與荷蘭之間的文化交流，邀請旅荷藝術家王儷靜策畫「尼德蘭畫師藝術重構─Dutch Masters Reimagined」特展，展出來自荷蘭著名藝術學院Academie Renshof三位當代藝術家的作品，向17世紀荷蘭興盛的繪畫致敬，為觀眾帶來一場視覺盛宴，品味荷蘭繪畫經典在當代藝術的影響力，體會仿古技法與現代詮釋的巧妙融合，帶領觀眾穿越時空，欣賞跨越世紀與地域的藝術發展。', '臺南市政府文化局', '臺南市中西區友愛街8-3號', '2025-01-01 00:00:00', '2025-03-31 00:00:00', '葉石濤文學紀念館（直轄市定古蹟原臺南山林事務所）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='葉石濤文學紀念館特展「尼德蘭畫師藝術重構─Dutch Masters Reimagined」', `description`='為紀念臺南400，表彰臺灣與荷蘭之間的文化交流，邀請旅荷藝術家王儷靜策畫「尼德蘭畫師藝術重構─Dutch Masters Reimagined」特展，展出來自荷蘭著名藝術學院Academie Renshof三位當代藝術家的作品，向17世紀荷蘭興盛的繪畫致敬，為觀眾帶來一場視覺盛宴，品味荷蘭繪畫經典在當代藝術的影響力，體會仿古技法與現代詮釋的巧妙融合，帶領觀眾穿越時空，欣賞跨越世紀與地域的藝術發展。', `organizer`='臺南市政府文化局', `address`='臺南市中西區友愛街8-3號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='葉石濤文學紀念館（直轄市定古蹟原臺南山林事務所）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788236a26b32458d43636d7', '樂齡幸福編織藝術讀書會與花語風車拼布手作讀書會作品展', '樂齡幸福編織藝術讀書會和花語風車拼布手作讀書會上課學員作品成果展，利用館藏，共讀編織手作書籍，進行作品設計等。歡迎市民大小朋友一起來欣賞學員們的作品。\r\n', '高雄市立圖書館總館', '高雄市鹽埕區1鄰大仁路179號5樓、6樓', '2025-01-02 00:00:00', '2025-12-31 00:00:00', '高雄市立圖書館鹽埕分館', 22.626715, 120.281874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樂齡幸福編織藝術讀書會與花語風車拼布手作讀書會作品展', `description`='樂齡幸福編織藝術讀書會和花語風車拼布手作讀書會上課學員作品成果展，利用館藏，共讀編織手作書籍，進行作品設計等。歡迎市民大小朋友一起來欣賞學員們的作品。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市鹽埕區1鄰大仁路179號5樓、6樓', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄市立圖書館鹽埕分館', `latitude`=22.626715, `longitude`=120.281874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788236b26b32458d43636d8', '2025台灣燈會：「數位星辰  時空中的延展虛實」新媒體藝術展', '呼應2025台灣燈會「光聚千塘串桃園」的主題，千塘能具的光，當然也包含來自天空外宇宙中的滿天星斗，《數位星辰：時空中的延展虛實》將以水塘與宇宙的哲思作為靈感聯結，由黃心健藝術家的《蘊空》系列作品為展覽核心，透過沉浸式投影、裝置藝術，展現從微觀到宏觀的能量循環，並邀請觀眾以內心沈澱與外在探索，感受虛實之間的無限可能。', '桃園市政府智慧城鄉發展委員會', '桃園市中壢區', '2025-02-09 00:00:00', '2025-03-01 00:00:00', '中壢區（桃園市）=', 24.97993803, 121.2147243, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會：「數位星辰  時空中的延展虛實」新媒體藝術展', `description`='呼應2025台灣燈會「光聚千塘串桃園」的主題，千塘能具的光，當然也包含來自天空外宇宙中的滿天星斗，《數位星辰：時空中的延展虛實》將以水塘與宇宙的哲思作為靈感聯結，由黃心健藝術家的《蘊空》系列作品為展覽核心，透過沉浸式投影、裝置藝術，展現從微觀到宏觀的能量循環，並邀請觀眾以內心沈澱與外在探索，感受虛實之間的無限可能。', `organizer`='桃園市政府智慧城鄉發展委員會', `address`='桃園市中壢區', `start_date`='2025-02-09 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='中壢區（桃園市）=', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788237026b32458d43636dc', '臺南400農漁地景藝術節─生生萬物《孕》', '在總爺藝文中心，你將看到一顆巨大的「卵」形裝置藝術《孕》，高達4米、直徑10米的結構，以竹材為主要元素，象徵著大地的孕育與生命的延續。這座作品不僅是對臺南農漁歷史的回應，更傳達了自然與文明和諧共生的理念。\r\n《孕》由孟宗竹經過燒烤後彎曲而成，形成獨特的類卵型空間。白天，陽光透過竹材表面洩入，創造出自然的光影變幻，讓整個空間充滿生命力。而到了夜晚，800支燈條照亮周圍草皮，點點光芒交織，營造出夢幻且浪漫的氛圍。\r\n更特別的是，觀眾可以進入這個竹編的空間，坐在內部鋪設的草蓆上，感受自然的靜謐與文化的力量，帶來一場沉浸式體驗。作品的設計不僅強調視覺上的震撼，也希望透過與觀眾的互動，傳遞農漁文化與自然界相互滋養的深層意涵。', '臺南市政府文化局', '臺南市麻豆區總爺5號', '2025-01-01 00:00:00', '2025-04-30 00:00:00', '臺南市總爺藝文中心', 23.18248033, 120.241308, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南400農漁地景藝術節─生生萬物《孕》', `description`='在總爺藝文中心，你將看到一顆巨大的「卵」形裝置藝術《孕》，高達4米、直徑10米的結構，以竹材為主要元素，象徵著大地的孕育與生命的延續。這座作品不僅是對臺南農漁歷史的回應，更傳達了自然與文明和諧共生的理念。\r\n《孕》由孟宗竹經過燒烤後彎曲而成，形成獨特的類卵型空間。白天，陽光透過竹材表面洩入，創造出自然的光影變幻，讓整個空間充滿生命力。而到了夜晚，800支燈條照亮周圍草皮，點點光芒交織，營造出夢幻且浪漫的氛圍。\r\n更特別的是，觀眾可以進入這個竹編的空間，坐在內部鋪設的草蓆上，感受自然的靜謐與文化的力量，帶來一場沉浸式體驗。作品的設計不僅強調視覺上的震撼，也希望透過與觀眾的互動，傳遞農漁文化與自然界相互滋養的深層意涵。', `organizer`='臺南市政府文化局', `address`='臺南市麻豆區總爺5號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市總爺藝文中心', `latitude`=23.18248033, `longitude`=120.241308, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788237126b32458d43636e1', '乙巳年苗栗通霄鎮白沙屯拱天宮媽祖徒步進香民俗文化活動', '苗栗縣通霄鎮拱天宮「白沙屯媽祖進香」活動，苗栗縣一年一度民俗盛事，具有百年以上歷史，不僅歷史悠久、規模盛大，每年均有來自全國各地居民熱情參與徒步到北港朝天宮進香，全程近400公里，縱跨中部4縣市，因其進香日期與路程皆由媽祖神轎指引進行，無法事先預估且為全台路線最遠的徒步進香民俗活動，因其深具傳統性及特殊性，於民國97年登錄為苗栗縣無形文化資產，更於民國99年（西元2010年）獲文化部指定為國家重要民俗祭儀，也在民國102年（西元2013年）被選為內政部「台灣宗教百景」之一。\r\n今年將在國曆4月28日深夜23時50分放頭旗、5月1日23時25分登轎，登轎就緒後出發，5月3日抵達北港，5月4日0時40分進火，5月11日15時45分回宮，5月22日子時00:40開爐。歡迎民眾參與。\r\n進香報名日期：國曆3/27起每天08:00-12:00、13:00-18:00，報名至4/28下午18：00截止。', '白沙屯拱天宮管理委員會', '苗栗縣通霄鎮', '2025-04-28 00:00:00', '2025-05-22 00:00:00', '通霄鎮（苗栗縣）=', 24.4850464, 120.7146378, '無資料', 'https://www.facebook.com/bstmz', '[]') ON DUPLICATE KEY UPDATE `activity_name`='乙巳年苗栗通霄鎮白沙屯拱天宮媽祖徒步進香民俗文化活動', `description`='苗栗縣通霄鎮拱天宮「白沙屯媽祖進香」活動，苗栗縣一年一度民俗盛事，具有百年以上歷史，不僅歷史悠久、規模盛大，每年均有來自全國各地居民熱情參與徒步到北港朝天宮進香，全程近400公里，縱跨中部4縣市，因其進香日期與路程皆由媽祖神轎指引進行，無法事先預估且為全台路線最遠的徒步進香民俗活動，因其深具傳統性及特殊性，於民國97年登錄為苗栗縣無形文化資產，更於民國99年（西元2010年）獲文化部指定為國家重要民俗祭儀，也在民國102年（西元2013年）被選為內政部「台灣宗教百景」之一。\r\n今年將在國曆4月28日深夜23時50分放頭旗、5月1日23時25分登轎，登轎就緒後出發，5月3日抵達北港，5月4日0時40分進火，5月11日15時45分回宮，5月22日子時00:40開爐。歡迎民眾參與。\r\n進香報名日期：國曆3/27起每天08:00-12:00、13:00-18:00，報名至4/28下午18：00截止。', `organizer`='白沙屯拱天宮管理委員會', `address`='苗栗縣通霄鎮', `start_date`='2025-04-28 00:00:00', `end_date`='2025-05-22 00:00:00', `location`='通霄鎮（苗栗縣）=', `latitude`=24.4850464, `longitude`=120.7146378, `ticket_price`='無資料', `source_url`='https://www.facebook.com/bstmz', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788237126b32458d43636e2', '苗栗縣美術家邀請展—原鄉情，遠山在召喚—高秀明油畫創作展', '出生於苗栗造橋瓦窯村的高秀明，懷抱對藝術的熱愛，將繪畫視為一生的使命。他的創作靈感源於台灣的山川景致與人文情懷，作品以鮮明色彩和率真的筆觸，展現對土地的深切關懷與情感。高秀明早年拜師於「礦工畫家」蔣瑞坑，秉承「認真、天真、純真」的藝術哲學，逐步發展出獨特的風格。\r\n本次展覽以「原鄉情，遠山在召喚」為題，展出多幅生動描繪自然與人文的佳作，展現他對家鄉的深厚情感與藝術追求。生動展現了他對藝術的執著與熱情。展覽不僅是藝術的饗宴，更是他與觀眾的心靈對話，共同追尋土地與記憶的美好。', '苗栗縣政府', '苗栗縣苗栗市自治路50號', '2025-03-06 00:00:00', '2025-04-06 00:00:00', '苗栗縣政府文化觀光局', 24.565963, 120.8203986, '無資料', 'https://www.mlc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗栗縣美術家邀請展—原鄉情，遠山在召喚—高秀明油畫創作展', `description`='出生於苗栗造橋瓦窯村的高秀明，懷抱對藝術的熱愛，將繪畫視為一生的使命。他的創作靈感源於台灣的山川景致與人文情懷，作品以鮮明色彩和率真的筆觸，展現對土地的深切關懷與情感。高秀明早年拜師於「礦工畫家」蔣瑞坑，秉承「認真、天真、純真」的藝術哲學，逐步發展出獨特的風格。\r\n本次展覽以「原鄉情，遠山在召喚」為題，展出多幅生動描繪自然與人文的佳作，展現他對家鄉的深厚情感與藝術追求。生動展現了他對藝術的執著與熱情。展覽不僅是藝術的饗宴，更是他與觀眾的心靈對話，共同追尋土地與記憶的美好。', `organizer`='苗栗縣政府', `address`='苗栗縣苗栗市自治路50號', `start_date`='2025-03-06 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='苗栗縣政府文化觀光局', `latitude`=24.565963, `longitude`=120.8203986, `ticket_price`='無資料', `source_url`='https://www.mlc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788237126b32458d43636e3', '傀儡奇緣歡樂年--錦飛鳳傀儡戲劇團', '來自高雄市的「錦飛鳳傀儡戲劇團」歷經四代傳承，擁有百年的歷史，是臺灣唯一擅長文化場與儀式性展演的傀儡戲劇團，也是目前唯一的職業傀儡戲劇團，在第三代團長「薛熒源」的帶領之下，多次出國參與國際性藝術節的演出深獲好評，近年來除了精進表演藝術、並積極投入傳承與推廣的工作，成績斐然，至今已21度獲選為高雄市傑出演藝團隊，更是官方指定的（雙登錄：民俗類、傳統表演藝術類）無形文化資產保存團體，並於107年榮獲高雄市「藝術教育貢獻獎-績優團體」及111年第九屆教育部「藝術教育貢獻獎-活動奉獻獎」等殊榮，備受各界肯定。\r\n這次由薛熒源、張雪香夫妻檔領銜主演，帶來熱鬧精彩的節慶好戲《嘉禮迎春歡樂年》，將以人偶同臺的形式演出，主角為靈活輕巧及誇張滑稽的丑角，透過演師精湛技藝，活靈活現呈現傀儡生動活潑及細膩傳神的動作，輔以詼諧對白及歡鬧劇情，營造幽默歡笑的表演，讓觀眾純粹自然喜歡傳統戲曲及感染傳統傀儡藝術之美。\r\n本劇適合全家欣賞，除增進親子情感外，更透過示範、演出、互動展演及開放兒童上台親身體驗操偶樂趣，並提供精美禮物進行有獎徵答，活動內容精彩豐富，歡迎民眾踴躍先行前往索票，屆時憑票入場欣賞。\r\n本場活動採索票入場，自2月21日（五）上午9時起，在苗栗縣政府文化觀光局一樓服務台，以及高鐵苗栗站、台鐵竹南站、台鐵苗栗站之旅遊服務中心開放索取，每人限索2張，索完為止。', '苗栗縣政府', '苗栗縣苗栗市自治路50號', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '苗栗縣政府文化觀光局', 24.565963, 120.8203986, '無資料', 'https://www.mlc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='傀儡奇緣歡樂年--錦飛鳳傀儡戲劇團', `description`='來自高雄市的「錦飛鳳傀儡戲劇團」歷經四代傳承，擁有百年的歷史，是臺灣唯一擅長文化場與儀式性展演的傀儡戲劇團，也是目前唯一的職業傀儡戲劇團，在第三代團長「薛熒源」的帶領之下，多次出國參與國際性藝術節的演出深獲好評，近年來除了精進表演藝術、並積極投入傳承與推廣的工作，成績斐然，至今已21度獲選為高雄市傑出演藝團隊，更是官方指定的（雙登錄：民俗類、傳統表演藝術類）無形文化資產保存團體，並於107年榮獲高雄市「藝術教育貢獻獎-績優團體」及111年第九屆教育部「藝術教育貢獻獎-活動奉獻獎」等殊榮，備受各界肯定。\r\n這次由薛熒源、張雪香夫妻檔領銜主演，帶來熱鬧精彩的節慶好戲《嘉禮迎春歡樂年》，將以人偶同臺的形式演出，主角為靈活輕巧及誇張滑稽的丑角，透過演師精湛技藝，活靈活現呈現傀儡生動活潑及細膩傳神的動作，輔以詼諧對白及歡鬧劇情，營造幽默歡笑的表演，讓觀眾純粹自然喜歡傳統戲曲及感染傳統傀儡藝術之美。\r\n本劇適合全家欣賞，除增進親子情感外，更透過示範、演出、互動展演及開放兒童上台親身體驗操偶樂趣，並提供精美禮物進行有獎徵答，活動內容精彩豐富，歡迎民眾踴躍先行前往索票，屆時憑票入場欣賞。\r\n本場活動採索票入場，自2月21日（五）上午9時起，在苗栗縣政府文化觀光局一樓服務台，以及高鐵苗栗站、台鐵竹南站、台鐵苗栗站之旅遊服務中心開放索取，每人限索2張，索完為止。', `organizer`='苗栗縣政府', `address`='苗栗縣苗栗市自治路50號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='苗栗縣政府文化觀光局', `latitude`=24.565963, `longitude`=120.8203986, `ticket_price`='無資料', `source_url`='https://www.mlc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788237126b32458d43636e8', '埔鹽鄉立圖書館114年第1期研習活動', '埔鹽鄉立圖書館114年第1期研習活動招生簡章\r\n一、舉辦宗旨：配合政府推展終身教育，以建立學習型社會，達成培養人格發展、文化藝術、健康休閒等多元教育目標。\r\n二、主辦單位：埔鹽鄉公所(圖書館)\r\n三、研習時間：自114年1月4日起至114年3月29日止，請按當期簡章至本館上課，恕不另通知。\r\n（如有變動將另以簡訊通知，無手機者以市話通知)\r\n四、報名日期：自113年12月18日上午9點起至開課前二日截止！\r\n(星期一及國定假日休館)\r\n五、報名地點：埔鹽鄉立圖書館3樓地方文化館服務台(聯絡電話：04-8654075)。\r\n3樓休展時請至2樓借書處報名。 地址：埔鹽鄉好修村員鹿路二段60號。', '彰化縣埔鹽鄉公所', '彰化縣埔鹽鄉員鹿路2段60號', '2025-01-04 00:00:00', '2025-03-29 00:00:00', '彰化縣埔鹽鄉立圖書館', 23.99204417, 120.4594626, '無資料', 'https://www.facebook.com/PuyanLibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='埔鹽鄉立圖書館114年第1期研習活動', `description`='埔鹽鄉立圖書館114年第1期研習活動招生簡章\r\n一、舉辦宗旨：配合政府推展終身教育，以建立學習型社會，達成培養人格發展、文化藝術、健康休閒等多元教育目標。\r\n二、主辦單位：埔鹽鄉公所(圖書館)\r\n三、研習時間：自114年1月4日起至114年3月29日止，請按當期簡章至本館上課，恕不另通知。\r\n（如有變動將另以簡訊通知，無手機者以市話通知)\r\n四、報名日期：自113年12月18日上午9點起至開課前二日截止！\r\n(星期一及國定假日休館)\r\n五、報名地點：埔鹽鄉立圖書館3樓地方文化館服務台(聯絡電話：04-8654075)。\r\n3樓休展時請至2樓借書處報名。 地址：埔鹽鄉好修村員鹿路二段60號。', `organizer`='彰化縣埔鹽鄉公所', `address`='彰化縣埔鹽鄉員鹿路2段60號', `start_date`='2025-01-04 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='彰化縣埔鹽鄉立圖書館', `latitude`=23.99204417, `longitude`=120.4594626, `ticket_price`='無資料', `source_url`='https://www.facebook.com/PuyanLibrary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788237126b32458d43636ea', '無資料', '師資簡介：侯秀鳳、黃永仁、郭錦華、吳惠玲老師等(故事達人) \r\n活動對象：兒童 \r\n費用：免費，自由參加 \r\n活動時間：2/1,2/2,2/7,2/8,2/9,2/14,2/15,2/16,2/21,2/22,2/23，週五、六、日上午10時至11時 \r\n高雄市立圖書館陽明分館兒童圖書室 \r\n', '高雄市立圖書館總館', '高雄市三民區陽明路300號3樓', '高雄市立圖書館陽明分館', 22.643485, 120.34232, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='師資簡介：侯秀鳳、黃永仁、郭錦華、吳惠玲老師等(故事達人) \r\n活動對象：兒童 \r\n費用：免費，自由參加 \r\n活動時間：2/1,2/2,2/7,2/8,2/9,2/14,2/15,2/16,2/21,2/22,2/23，週五、六、日上午10時至11時 \r\n高雄市立圖書館陽明分館兒童圖書室 \r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區陽明路300號3樓', `location`='高雄市立圖書館陽明分館', `latitude`=22.643485, `longitude`=120.34232, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788237126b32458d43636eb', '2025青春美展  循光－南華大學視覺藝術與設計學系第19屆畢業成果展', '光點是自身的投射，也是我們吸收的知識與力量。光的軌跡，寓意不斷探索，吸納經驗與智慧，匯聚成長的過程。而光的匯聚是團結與進步，追尋中不斷突破的自我，更是熱忱與堅韌照亮的道路。「循光」是一種精神，也是一場向希望與可能致敬的旅程。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-04-18 00:00:00', '2025-04-29 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4082', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展  循光－南華大學視覺藝術與設計學系第19屆畢業成果展', `description`='光點是自身的投射，也是我們吸收的知識與力量。光的軌跡，寓意不斷探索，吸納經驗與智慧，匯聚成長的過程。而光的匯聚是團結與進步，追尋中不斷突破的自我，更是熱忱與堅韌照亮的道路。「循光」是一種精神，也是一場向希望與可能致敬的旅程。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-04-18 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4082', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678879088f156cba57ab1aba', '無資料', '教育部響應2025世界母語日以「『語生俱來』聽見島嶼在說話」為題，讓我們語名人相遇在「母語時代，從生活運用到創作表演」與談講座，還有主題活動「母語推廣市集」搭配聽見島嶼的聲音分享舞臺和多元學習闖關遊戲！2月23日邀請大家一起沉浸母語學習！\r\n\r\n-\r\n\r\n2/23 (日) 13:30－15:30\r\n「母語時代，從生活運用到創作表演」與談講座\r\n\r\n在臺灣多元母語時代之中，身為創作工作者，如何從自身母語文化、生命經驗等出發，到與其作品、表演連結。本場與談講座將邀請戲劇、歌唱等創作工作者分享與對談，一路以來的母語文化養成與實務創作運用，並且延伸探討母語轉譯背後的思維與思考起源。\r\n\r\n➤現在就點擊「活動網站連結」線上報名去！\r\n\r\n▌講座地點\r\n誠品生活松菸 B1誠品表演廳\r\n\r\n▌講座時間\r\n13:00開放入場、13:30講座開始\r\n13:30─13:35　主持引言\r\n13:35─14:50　名人分享\r\n14:50─15:20　與談時間\r\n15:20─15:30　問答時間\r\n\r\n▌主持人\r\n臺灣客語主持人｜溫士凱\r\n\r\n▌講者\r\n臺灣原住民族語言創作歌手｜ Ilid Kaolo 以莉高露\r\n臺灣台語劇團團長｜阮劇團 蔡明純\r\n臺灣客語創作歌手｜葉穎\r\n\r\n-\r\n\r\n場外加映活動──\r\n2/23 (日) 13:00－17:00\r\n「大家來說母語推廣市集」主題活動\r\n\r\n講座外還將同步舉辦「大家來說母語推廣市集」主題活動，現場不僅安排聽見島嶼的聲音分享舞臺的母語表演，還有各個母語推廣單位帶來多元學習闖關遊戲，完成4個關卡集點可兌換主題紀念品1份！（限量1,000份，換完為止）\r\n\r\n➤活動當天至現場服務臺領取集點卡，即可免費參與母語闖關遊戲！\r\n\r\n▌活動地點\r\n臺北文創 B1挑高中庭\r\n\r\n-\r\n\r\n※更多活動詳情請至「教育部響應2025世界母語日活動網站」查詢！', '教育部終身教育司', '臺北市信義區菸廠路88號', '市集：臺北文創 B1挑高中庭', 25.03062083, 121.5716697, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='教育部響應2025世界母語日以「『語生俱來』聽見島嶼在說話」為題，讓我們語名人相遇在「母語時代，從生活運用到創作表演」與談講座，還有主題活動「母語推廣市集」搭配聽見島嶼的聲音分享舞臺和多元學習闖關遊戲！2月23日邀請大家一起沉浸母語學習！\r\n\r\n-\r\n\r\n2/23 (日) 13:30－15:30\r\n「母語時代，從生活運用到創作表演」與談講座\r\n\r\n在臺灣多元母語時代之中，身為創作工作者，如何從自身母語文化、生命經驗等出發，到與其作品、表演連結。本場與談講座將邀請戲劇、歌唱等創作工作者分享與對談，一路以來的母語文化養成與實務創作運用，並且延伸探討母語轉譯背後的思維與思考起源。\r\n\r\n➤現在就點擊「活動網站連結」線上報名去！\r\n\r\n▌講座地點\r\n誠品生活松菸 B1誠品表演廳\r\n\r\n▌講座時間\r\n13:00開放入場、13:30講座開始\r\n13:30─13:35　主持引言\r\n13:35─14:50　名人分享\r\n14:50─15:20　與談時間\r\n15:20─15:30　問答時間\r\n\r\n▌主持人\r\n臺灣客語主持人｜溫士凱\r\n\r\n▌講者\r\n臺灣原住民族語言創作歌手｜ Ilid Kaolo 以莉高露\r\n臺灣台語劇團團長｜阮劇團 蔡明純\r\n臺灣客語創作歌手｜葉穎\r\n\r\n-\r\n\r\n場外加映活動──\r\n2/23 (日) 13:00－17:00\r\n「大家來說母語推廣市集」主題活動\r\n\r\n講座外還將同步舉辦「大家來說母語推廣市集」主題活動，現場不僅安排聽見島嶼的聲音分享舞臺的母語表演，還有各個母語推廣單位帶來多元學習闖關遊戲，完成4個關卡集點可兌換主題紀念品1份！（限量1,000份，換完為止）\r\n\r\n➤活動當天至現場服務臺領取集點卡，即可免費參與母語闖關遊戲！\r\n\r\n▌活動地點\r\n臺北文創 B1挑高中庭\r\n\r\n-\r\n\r\n※更多活動詳情請至「教育部響應2025世界母語日活動網站」查詢！', `organizer`='教育部終身教育司', `address`='臺北市信義區菸廠路88號', `location`='市集：臺北文創 B1挑高中庭', `latitude`=25.03062083, `longitude`=121.5716697, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6788bed48f156cba57ab1abb', '清心茶話~茶器 茶畫 茶事', '清心茶話~茶器 茶畫 茶事\r\n展期：2025.2.4-28	\r\n\r\n人生如茶，濃淡皆宜。晚唐劉貞亮言:「以茶利禮仁；以茶表敬意；以茶可行道；以茶可雅志。」以茶會友，乃身心一大樂事也。\r\n\r\n偷得浮生半日閒，於屋間置紫砂一具，陶器數盞，約三五知己好友，談談茶、文玩、文學，那是最愜意不過的事情了。喝茶的人通達明靜，霽月風清。就像日本禪學家鈴木大拙說的：“當我坐在茶室喝茶的時候，我是把整個宇宙喝到肚子裏，我舉起杯子之刻即是超越時空的永恒。”誰說不是呢？\r\n\r\n茶事展出如茶道具的嘉年華，聚集有：茶壺、茶碗、茶則、茶倉、茶杯、杯托、茶承、茶盤…等，另外還有文人字畫，復古家具相配。空氣中茶香繚繞，細細品味茶掛的水墨意境，香茗在手，喜悅滿足。\r\n\r\n開放時間  AM11:00-PM19:00 (週一休假) \r\n展出地點  孟焦畫坊  臺北市士林區雨農路17-2號1樓\r\n電話      (02)2834-4319	\r\n\r\n', '孟焦畫坊', '臺北市士林區雨農路17-2號1樓', '2025-02-04 00:00:00', '2025-02-28 00:00:00', '孟焦畫坊', 25.12546704, 121.5508473, '無資料', 'https://www.facebook.com/LookingForwardGallery/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='清心茶話~茶器 茶畫 茶事', `description`='清心茶話~茶器 茶畫 茶事\r\n展期：2025.2.4-28	\r\n\r\n人生如茶，濃淡皆宜。晚唐劉貞亮言:「以茶利禮仁；以茶表敬意；以茶可行道；以茶可雅志。」以茶會友，乃身心一大樂事也。\r\n\r\n偷得浮生半日閒，於屋間置紫砂一具，陶器數盞，約三五知己好友，談談茶、文玩、文學，那是最愜意不過的事情了。喝茶的人通達明靜，霽月風清。就像日本禪學家鈴木大拙說的：“當我坐在茶室喝茶的時候，我是把整個宇宙喝到肚子裏，我舉起杯子之刻即是超越時空的永恒。”誰說不是呢？\r\n\r\n茶事展出如茶道具的嘉年華，聚集有：茶壺、茶碗、茶則、茶倉、茶杯、杯托、茶承、茶盤…等，另外還有文人字畫，復古家具相配。空氣中茶香繚繞，細細品味茶掛的水墨意境，香茗在手，喜悅滿足。\r\n\r\n開放時間  AM11:00-PM19:00 (週一休假) \r\n展出地點  孟焦畫坊  臺北市士林區雨農路17-2號1樓\r\n電話      (02)2834-4319	\r\n\r\n', `organizer`='孟焦畫坊', `address`='臺北市士林區雨農路17-2號1樓', `start_date`='2025-02-04 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='孟焦畫坊', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='無資料', `source_url`='https://www.facebook.com/LookingForwardGallery/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789297207f3e7d36c5308c1', '華文音樂劇《我們》', '我在做什麼？我在想什麼？\r\n難道我就該這樣放棄掙扎？\r\n\r\n迷茫、夢想、重生、抉擇、尋根、彩虹，\r\n以六段不同的生命故事交織而成一段彩虹。\r\n偏鄉部落與高壓城市、主流與非主流價值觀、追求夢想與安分守己，每一個與眾不同的「我們」，究竟屬於哪裡，又該往哪裡走？\r\n\r\n\r\n劇情介紹｜\r\n五月時節，山青部落舉辦了一年一度的盛大慶典——射耳祭，部落裡滿溢著布農族傳統樂聲，以及節慶特有的熱鬧氛圍。許多外地的遊客為了感受不同於都市的原民傳統文化，紛紛入住當地民宿和旅店。\r\n\r\n少年 Abin在部落裡的民宿打工，忙碌的節慶期間接待了來自各地城市，為了體驗部落節慶活動與市集而短暫造訪的旅客；\r\n\r\n然而，其中有一些旅人來訪的理由不是慶典，在歡愉的慶典結束後仍留宿於部落，似乎有未完待續的人生考題，等待他們找出解方……。\r\n\r\n原本對城市生活有無限嚮往的Abin，在聽見、看見他們的故事後，開始對自己的家鄉有了不一樣的想法......。\r\n\r\n\r\n製作團隊｜\r\n指導顧問：陳尚盈\r\n製 作 人：許嘉軒\r\n導　　演：楊瑾雯\r\n共同編劇：楊瑾雯、楊文忻\r\n詞曲創作暨歌唱指導：楊文忻\r\n執行製作：黃莉芸\r\n協同編劇：江昭儀\r\n行政協力：陳晶婕\r\n導演助理暨舞台監督：江昭儀\r\n行銷宣傳：鍾育臻、廖字榆\r\n助理舞監：曾   瓅、劉鎧禎\r\n舞監助理：張家綾\r\n原民文化顧問：撒理嵐・伊斯坦大、蘇妙玲\r\n公　　關：李國堯、吳珮綺\r\n\r\n\r\n設計團隊｜\r\n音樂製作：詹維全\r\n音響設計：賴昱興\r\n燈光設計：張玉東\r\n助理燈光設計：廖品喻\r\n平面設計：楊若楚\r\n舞台暨道具設計：林建廷\r\n髮妝設計：葉芷廷\r\n服裝設計：吳昀珊\r\n肢體設計：鄭烺炘\r\n音樂音效執行：許嘉軒\r\n\r\n主辦單位｜小浪潮創作體\r\n演出單位｜HSUAN_studio\r\n\r\n演員團隊｜依姓氏筆畫排列\r\n李　亢、張志聖、華　時、黃治歆、葉承翰、廖梓羽、劉昀昀、潘書煒、蔡家宸、鄭烺炘', '小浪潮創作體', '高雄市鼓山區蓬萊路99號蓬萊區B9倉庫', '2025-03-07 00:00:00', '2025-03-07 00:00:00', '駁二正港小劇場', 22.65019525, 120.274163, '贊　助　票　 1000元\r\n原　價　票　 600元\r\n學　生　票 　540元（取票時須出示相關證明）\r\n團　體　票 　540元/張（須單筆訂單購買四張票卷以上）\r\n身障愛心票　 300元（取票時須出示相關證明）', 'https://www.opentix.life/event/1856619902909652992', '[]') ON DUPLICATE KEY UPDATE `activity_name`='華文音樂劇《我們》', `description`='我在做什麼？我在想什麼？\r\n難道我就該這樣放棄掙扎？\r\n\r\n迷茫、夢想、重生、抉擇、尋根、彩虹，\r\n以六段不同的生命故事交織而成一段彩虹。\r\n偏鄉部落與高壓城市、主流與非主流價值觀、追求夢想與安分守己，每一個與眾不同的「我們」，究竟屬於哪裡，又該往哪裡走？\r\n\r\n\r\n劇情介紹｜\r\n五月時節，山青部落舉辦了一年一度的盛大慶典——射耳祭，部落裡滿溢著布農族傳統樂聲，以及節慶特有的熱鬧氛圍。許多外地的遊客為了感受不同於都市的原民傳統文化，紛紛入住當地民宿和旅店。\r\n\r\n少年 Abin在部落裡的民宿打工，忙碌的節慶期間接待了來自各地城市，為了體驗部落節慶活動與市集而短暫造訪的旅客；\r\n\r\n然而，其中有一些旅人來訪的理由不是慶典，在歡愉的慶典結束後仍留宿於部落，似乎有未完待續的人生考題，等待他們找出解方……。\r\n\r\n原本對城市生活有無限嚮往的Abin，在聽見、看見他們的故事後，開始對自己的家鄉有了不一樣的想法......。\r\n\r\n\r\n製作團隊｜\r\n指導顧問：陳尚盈\r\n製