INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789787c26b32458d4363748', '鄭足仔「書綻陶舞」陶藝創作展', '大甲區公所藝文空間本期展出陶藝家鄭足仔創作作品，大甲區區長顏金源表示鄭足仔老師作品以故鄉情懷為出發點，將每個年代生活故事全部揉入土中淬煉成茶碗，以自己的方式詮釋發揮，將陶藝創作注入更多新的活力和創意。\r\n鄭足仔老師說創作是透過觀念與技藝的呈現，它的獨特性、現代性、突破性及世界性，正快速拉近人與人的距離。藉由一個簡單手作茶碗開始，試著將各種原料材質、製作技法、造型結構、裝飾質感、功用機能，到觀念意象的呈現，讓茶碗在情感設計與窯燒過程中熱到最高點。', '臺中市大甲區公所', '臺中市大甲區', '2025-01-01 00:00:00', '2025-03-28 00:00:00', '大甲區（臺中市）=', 24.37827161, 120.6357901, '無資料', 'https://ccss3172.blogspot.com/2025/01/blog-post_61.html', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鄭足仔「書綻陶舞」陶藝創作展', `description`='大甲區公所藝文空間本期展出陶藝家鄭足仔創作作品，大甲區區長顏金源表示鄭足仔老師作品以故鄉情懷為出發點，將每個年代生活故事全部揉入土中淬煉成茶碗，以自己的方式詮釋發揮，將陶藝創作注入更多新的活力和創意。\r\n鄭足仔老師說創作是透過觀念與技藝的呈現，它的獨特性、現代性、突破性及世界性，正快速拉近人與人的距離。藉由一個簡單手作茶碗開始，試著將各種原料材質、製作技法、造型結構、裝飾質感、功用機能，到觀念意象的呈現，讓茶碗在情感設計與窯燒過程中熱到最高點。', `organizer`='臺中市大甲區公所', `address`='臺中市大甲區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='大甲區（臺中市）=', `latitude`=24.37827161, `longitude`=120.6357901, `ticket_price`='無資料', `source_url`='https://ccss3172.blogspot.com/2025/01/blog-post_61.html', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789787d26b32458d436374a', '親子經典美術讀經班 (114年1-6月)', '兒童班:1.孝經、論語、唐詩、道德經、聲律啟蒙、弟子規、千字文... 2.增進孩子的語言與作文能力。 3.多元學習、禮儀集訓、品德驗收... 4.配合讀經進行親子美術手作，共同創作。 家長班:論語經典初探、情緒的魅力,語言的力量、多元化的財務經營、親職品格教育、婚姻觀。 注意事項:1.必須親子(家長與孩子)同時報名，研習學成發結業證書。 2.全部免費教學(預繳保證金1000元,全勤者全數退還,含彈性假五堂課) 3.自備課本或由基金會代購,每本120元。 4.美術材料費一學期酌收500元', '無資料', '臺中市大雅區樹德街255巷5號', '2025-01-07 00:00:00', '2025-06-24 00:00:00', '臺中市立圖書館上楓分館', 24.22704181, 120.6411818, '無資料', 'https://reurl.cc/6jb2rO', '[]') ON DUPLICATE KEY UPDATE `activity_name`='親子經典美術讀經班 (114年1-6月)', `description`='兒童班:1.孝經、論語、唐詩、道德經、聲律啟蒙、弟子規、千字文... 2.增進孩子的語言與作文能力。 3.多元學習、禮儀集訓、品德驗收... 4.配合讀經進行親子美術手作，共同創作。 家長班:論語經典初探、情緒的魅力,語言的力量、多元化的財務經營、親職品格教育、婚姻觀。 注意事項:1.必須親子(家長與孩子)同時報名，研習學成發結業證書。 2.全部免費教學(預繳保證金1000元,全勤者全數退還,含彈性假五堂課) 3.自備課本或由基金會代購,每本120元。 4.美術材料費一學期酌收500元', `organizer`='無資料', `address`='臺中市大雅區樹德街255巷5號', `start_date`='2025-01-07 00:00:00', `end_date`='2025-06-24 00:00:00', `location`='臺中市立圖書館上楓分館', `latitude`=24.22704181, `longitude`=120.6411818, `ticket_price`='無資料', `source_url`='https://reurl.cc/6jb2rO', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789787d26b32458d436374b', '上楓親子讀經班 (114年1-6月)', '三字經、千字文、百孝經等，唱跳律動、繪本分享、品格教育課程。 歡迎親子報名參加。 ', '無資料', '臺中市大雅區樹德街255巷5號', '2025-01-02 00:00:00', '2025-06-26 00:00:00', '臺中市立圖書館上楓分館', 24.22704181, 120.6411818, '無資料', 'https://reurl.cc/p9KyLa', '[]') ON DUPLICATE KEY UPDATE `activity_name`='上楓親子讀經班 (114年1-6月)', `description`='三字經、千字文、百孝經等，唱跳律動、繪本分享、品格教育課程。 歡迎親子報名參加。 ', `organizer`='無資料', `address`='臺中市大雅區樹德街255巷5號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-06-26 00:00:00', `location`='臺中市立圖書館上楓分館', `latitude`=24.22704181, `longitude`=120.6411818, `ticket_price`='無資料', `source_url`='https://reurl.cc/p9KyLa', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789787d26b32458d436374d', '“Crescendo” Group Exhibition of Indonesian Artists 「漸強」印尼藝術家群展', '在豔陽高照的南洋地區，一股強勁的藝術力量正悄然興起。複雜的殖民歷史，隨著全球化時代的浪潮，不斷被重新定義，國族的獨特性表現也面臨著如何被傳承與再現的挑戰。C Square Gallery 將於 2025 年初春呈獻一場以五位印尼藝術家，探討在強勢文化影響下，藝術家如何以創作自處並表達個人觀點。\r\n\r\n \r\n\r\n迪克·阿尤迪亞（Dikco Ayudya, b. 2004）來自藝術世家，在父母的影響下，阿尤迪亞踏上了追尋藝術之路。展出《小丑》系列，小丑符號在作品中，象徵著人類對情緒表達的羞怯以及情感結構的複雜性。畫面延伸至畫框，挑戰傳統畫作的概念完整性，激發觀者對作品形式與內容的重新思考。畫面中的小丑隱藏面孔，童趣的筆觸與色彩，以及孩童般的英文字體，表現出人們對自我認知的不確定。這些形象宛如孩子般對內心世界充滿未知，卻以高調的姿態渴望他人的關注與關愛。\r\n\r\n \r\n\r\n以超現實與蒙太奇手法著稱的貝斯塔·貝斯特里扎爾（Besta Bestrizal, b.1973），為各大拍賣所相當關注的印尼藝術家。緊密的炭筆排線、簡易線條符號、高飽和色彩的運用，觀看貝斯特里扎爾作品，宛若掉進一本古老的童話書。神秘的植物、文藝復興時期的圖樣、當代卡通的角色，層層堆疊與交織之下，講述了人類、文明、科技的三方角力，構成了專屬當代的寓言故事。\r\n\r\n \r\n\r\n帕利托‧佩拉克（Palito Perak, b. 1984）為印尼當地著名的平面設計師、藝術家。作品多啟發自社交媒體上如萬花筒般的世界，卻猶如霧裡看花，看不清真實的面貌。精選兩件以窗為主軸的畫作，以正向書寫上 Hope、Love、Hate 等字樣，顯示這些文字為內部書寫上的；濃厚的霧氣與朦朧的花叢，彷彿掙脫不出的牢籠。期望與擔心受傷害的情緒中，在觀看作品時無所遁形。\r\n\r\n \r\n\r\n澤塔·蘭尼里（Zeta Ranniry, b.2003）為印尼新生代女性藝術家，作品中以超高的寫實技巧，描繪著充滿動態的自畫像。除了傳遞對自身的了解，更是將自己放在大時代下，以第三者角度審視自己。展品 “Persona #2” 大笑的舉著開槍手勢，對著觀者，以開懷的情緒作出攻擊性的動作，搭配上細膩描繪的臉部，映襯著自由筆觸的衣著，充滿了戲劇張力。\r\n\r\n \r\n\r\n佩庫特·蘇曼特里（Pecut Sumantri, 1982）透過對日常生活中心緒的細膩觀察，快速的筆觸，捕捉生活中的每一個瞬間。 “Daily Life” 系列，精細描繪的物件搭配模糊的人像臉孔，敘述對意識認知的不確定與自我架構的不完整，同時也表達出人類形象建構，彷彿是物質的堆砌，而非自身個性的展現。\r\n\r\n \r\n\r\n五位來自不同世代的印尼藝術家，通過多樣的符號與創作手法，探討全球化世代中個體差異的意義。在這片蓬勃發展的土地上，他們以深刻而多元的視角邀請觀者一起重新審視文化、自然與個體的關係。C Square Gallery 誠摯邀請您在展覽中一同感受南洋藝術的無限可能。', 'C Square Gallery', '臺中市西屯區', '2025-01-04 00:00:00', '2025-03-09 00:00:00', '西屯區（臺中市）=', 24.18308895, 120.6270131, '無資料', 'https://reurl.cc/XZakE0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='“Crescendo” Group Exhibition of Indonesian Artists 「漸強」印尼藝術家群展', `description`='在豔陽高照的南洋地區，一股強勁的藝術力量正悄然興起。複雜的殖民歷史，隨著全球化時代的浪潮，不斷被重新定義，國族的獨特性表現也面臨著如何被傳承與再現的挑戰。C Square Gallery 將於 2025 年初春呈獻一場以五位印尼藝術家，探討在強勢文化影響下，藝術家如