INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789787e26b32458d4363750', '臺中市南區永和里國畫班嶺南水墨花鳥畫作展', '臺中市南區永和里國畫班啼聲初試，作品多以小品形式展現，藉由不同的花卉與姿態各異的禽鳥描繪，力求賞心悅目的畫面，冀能有 “自娛娛人” 之效。\r\n', '臺中市南區戶政事務所', '臺中市南區', '2025-01-01 00:00:00', '2025-03-31 00:00:00', '南區（臺中市）=', 24.12114107, 120.6646178, '無資料', 'https://reurl.cc/Nl9m4Q', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市南區永和里國畫班嶺南水墨花鳥畫作展', `description`='臺中市南區永和里國畫班啼聲初試，作品多以小品形式展現，藉由不同的花卉與姿態各異的禽鳥描繪，力求賞心悅目的畫面，冀能有 “自娛娛人” 之效。\r\n', `organizer`='臺中市南區戶政事務所', `address`='臺中市南區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='南區（臺中市）=', `latitude`=24.12114107, `longitude`=120.6646178, `ticket_price`='無資料', `source_url`='https://reurl.cc/Nl9m4Q', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789787e26b32458d4363752', '劉淑華老師&蕭辰妃老師油畫聯展', '本年度的首檔藝文展，榮幸邀請劉淑華老師與蕭辰妃老師共同舉辦油畫聯展。\r\n\r\n蕭辰妃老師是一位自學成才的畫家，熱愛以花草和風景為題材，並透過油畫呈現自然界的永恆美麗。她希望觀者在欣賞作品的同時，能感受到那份來自大自然的寧靜與美好。\r\n\r\n劉淑華老師則是一位深耕油畫創作的藝術家，致力於透過畫筆與色彩的表現，將自己內心的情感與思想具象化。她的作品充滿了豐沛的情感與生命力。\r\n\r\n本次展覽呈現了兩位藝術家風格各異的作品，從寫實到富有意境的表現手法，每一幅畫作都以斑斕的色彩展現了生動的視覺震撼。無論您喜愛何種風格，本次展覽都將帶給您一次豐富的視覺饗宴。', '臺中市烏日區戶政事務所', '臺中市烏日區', '2025-01-02 00:00:00', '2025-03-31 00:00:00', '烏日區（臺中市）=', 24.0839271, 120.6293305, '無資料', 'https://www.hwuri.taichung.gov.tw/3578494/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='劉淑華老師&蕭辰妃老師油畫聯展', `description`='本年度的首檔藝文展，榮幸邀請劉淑華老師與蕭辰妃老師共同舉辦油畫聯展。\r\n\r\n蕭辰妃老師是一位自學成才的畫家，熱愛以花草和風景為題材，並透過油畫呈現自然界的永恆美麗。她希望觀者在欣賞作品的同時，能感受到那份來自大自然的寧靜與美好。\r\n\r\n劉淑華老師則是一位深耕油畫創作的藝術家，致力於透過畫筆與色彩的表現，將自己內心的情感與思想具象化。她的作品充滿了豐沛的情感與生命力。\r\n\r\n本次展覽呈現了兩位藝術家風格各異的作品，從寫實到富有意境的表現手法，每一幅畫作都以斑斕的色彩展現了生動的視覺震撼。無論您喜愛何種風格，本次展覽都將帶給您一次豐富的視覺饗宴。', `organizer`='臺中市烏日區戶政事務所', `address`='臺中市烏日區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='烏日區（臺中市）=', `latitude`=24.0839271, `longitude`=120.6293305, `ticket_price`='無資料', `source_url`='https://www.hwuri.taichung.gov.tw/3578494/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789787f26b32458d4363754', '【「原」來識你】原住民服飾文物展', '    台灣的原住民族屬於南島民族，目前經政府認定的原住民族有16族，總原住民族人數約60萬人，約佔總人口數2％，為促進文化交流，大墩分館與修平科技大學原住民族學生資源中心合作，舉辦【「原」來識你】原住民服飾文物展。\r\n    展覽海報有各族的分佈區域，展品包括各式各樣的原住民服飾，以及不同部落的獨特風格和工藝：情人袋是具有特殊意義的傳統手工藝品，象徵著愛情與承諾；桌上織帶機展示了原住民精湛的織布技藝，口簧琴則是一種獨特的樂器。歡迎大家前來參觀，體驗這場豐富多彩的文化饗宴。 \r\n', '臺中市立圖書館大墩分館', '臺中市西區英才路600號', '2025-01-02 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館大墩分館', 24.14391082, 120.6647579, '無資料', 'https://pse.is/6xaqzk', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【「原」來識你】原住民服飾文物展', `description`='    台灣的原住民族屬於南島民族，目前經政府認定的原住民族有16族，總原住民族人數約60萬人，約佔總人口數2％，為促進文化交流，大墩分館與修平科技大學原住民族學生資源中心合作，舉辦【「原」來識你】原住民服飾文物展。\r\n    展覽海報有各族的分佈區域，展品包括各式各樣的原住民服飾，以及不同部落的獨特風格和工藝：情人袋是具有特殊意義的傳統手工藝品，象徵著愛情與承諾；桌上織帶機展示了原住民精湛的織布技藝，口簧琴則是一種獨特的樂器。歡迎大家前來參觀，體驗這場豐富多彩的文化饗宴。 \r\n', `organizer`='臺中市立圖書館大墩分館', `address`='臺中市西區英才路600號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館大墩分館', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://pse.is/6xaqzk', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789788126b32458d4363756', '從日常到永恆 - 瞿倩梅與姜淼', '在匆匆穿梭於日常的步履中，偶爾停下來，望向那超越人類語言的視野。這一瞬間，兩位藝術家的作品如同自然的深呼吸，輕輕擁抱我們，帶領我們進入她們的抽象宇宙。\r\n\r\n瞿倩梅的創作，猶如大地在無聲低語，天際迴響她的心聲。以岩彩、礦石和大漆為筆觸，層層堆疊，雕刻出一幅幅畫面，將自然的氣息深刻融入其中。每一層顏色、每一筆觸，都是對大自然無垠之美的頌歌。畫布上，岩彩的粗獷與漆的光澤交織，彷彿聽見大地的呼吸與天穹的回音。瞿倩梅以反覆的磨礪與堆疊，塑造出肌理豐厚的美感，畫作似被時間與土地浸潤，流動著自然的壯麗與永恆。雖屬抽象，但每一層次背後，都是對大自然的敬畏與感動，將她內心的情感與自然的景象融合成無聲的交響曲。每一筆的延展、每一次的疊加、每一道琢磨，都是她與大地心靈的對話，邀請觀者置身於那浩瀚無垠的大自然。\r\n\r\n姜淼的創作如同時間的河流，在無聲中洶湧翻騰。壓克力抽象畫層層堆積，記錄每日感觸，如細雨滲透泥土，日夜交替中孕育情感的種子。她以直覺揮灑色彩，翌日又覆蓋新的心境，那些隱藏於層層抽象色彩之下的記憶，宛若深埋的秘密，等待雕刻刀的雕琢觸碰將它們喚醒。姜淼的畫作承載著輪迴的節律，旋轉的能量如生命的脈動，陰陽交融如時空的對話。在挖掘的過程中，刀鋒如詩句劃過靜謐的畫面，情感的激流洶湧而出，揭開內心最深處的悸動。一次次凝視過去，也叩問未來。\r\n\r\n「從日常到永恆」瞿倩梅與姜淼，以無聲的語言，牽引我們穿越時間的流動與情感的漩渦。瞿倩梅與姜淼的作品如同詩意的橋樑，連結日常的片刻與永恆的深意，喚醒內心人們深處的共鳴，為這個時節增添一抹深邃而溫暖的色彩。\r\n\r\n#平畫繪畫  #複合媒材  #聯展', 'Modern Art Gallery｜現代畫廊', '臺中市西區公益路155巷9號B1', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '臺中市現代畫廊', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/86eVp7', '[]') ON DUPLICATE KEY UPDATE `activity_name`='從日常到永恆 - 瞿倩梅與姜淼', `description`='在匆匆穿梭於日常的步履中，偶爾停下來，望向那超越人類語言的視野。這一瞬間，兩位藝術家的作品如同自然的深呼吸，輕輕擁抱我們，帶領我們進入她們的抽象宇宙。\r\n\r\n瞿倩梅的創作，猶如大地在無聲低語，天際迴響她的心聲。以岩彩、礦石和大漆為筆觸，層層堆疊，雕刻出一幅幅畫面，將自然的氣息深刻融入其中。每一層顏色、每一筆觸，都是對大自然無垠之美的頌歌。畫布上，岩彩的粗獷與漆的光澤交織，彷彿聽見大地的呼吸與天穹的回音。瞿倩梅以反覆的磨礪與堆疊，塑造出肌理豐厚的美感，畫作似被時間與土地浸潤，流動著自然的壯麗與永恆。雖屬抽象，但每一層次背後，都是對大自然的敬畏與感動，將她內心的情感與自然的景象融合成無聲的交響曲。每一筆的延展、每一次的疊加、每一道琢磨，都是她與大地心靈的對話，邀請觀者置身於那浩瀚無垠的大自然。\r\n\r\n姜淼的創作如同時間的河流，在無聲中洶湧翻騰。壓克力抽象畫層層堆積，記錄每日感觸，如細雨滲透泥土，日夜交替中孕育情感的種子。她以直覺揮灑色彩，翌日又覆蓋新的心境，那些隱藏於層層抽象色彩之下的記憶，宛若深埋的秘密，等待雕刻刀的雕琢觸碰將它們喚醒。姜淼的畫作承載著輪迴的節律，旋轉的能量如生命的脈動，陰陽交融如時空的對話。在挖掘的過程中，刀鋒如詩句劃過靜謐的畫面，情感的激流洶湧而出，揭開內心最深處的悸動。一次次凝視過去，也叩問未來。\r\n\r\n「從日常到永恆」瞿倩梅與姜淼，以無聲的語言，牽引我們穿越時間的流動與情感的漩渦。瞿倩梅與姜淼的作品如同詩意的橋樑，連結日常的片刻與永恆的深意，喚醒內心人們深處的共鳴，為這個時節增添一抹深邃而溫暖的色彩。\r\n\r\n#平畫繪畫  #複合媒材  #聯展', `organizer`='Modern Art Gallery｜現代畫廊', `address`='臺中市西區公益路155巷9號B1', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市現代畫廊', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/86eVp7', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789788826b32458d4363757', '超越街頭：都市藝術的全球視角', '自20世紀末以來，都市藝術，特別是街頭藝術和塗鴉藝術，在全球範圍內迅速受到廣泛關注與喜愛。這些藝術形式起源於城市空間，涵蓋了塗鴉、壁畫、貼紙和裝置藝術等多種媒材。藝術家們通過這些表達形式詮釋都市文化、反映社會現狀，甚至批判現代社會中的制度和問題。與傳統藝術形式相比，都市藝術擁有顛覆性的特質，作品直接呈現在大眾視野中，充滿挑戰權威、顛覆常規的力量。\r\n\r\n都市藝術的歷史可追溯到1970年代的紐約，當時塗鴉成為年輕人抗議社會不公、展現個人身份的手段。隨著時間的推移，這些風格與技術變得更加多樣化，並迅速傳播至全球各地，形成了一種視覺風格強烈、批判社會的藝術運動。塗鴉藝術家運用噴漆、畫刷等工具在公共牆面上留下印記，隨著這些創作從地下文化逐漸進入主流，都市藝術也在當代藝術界獲得了認可。\r\n\r\n近年來，隨著畫廊和博物館對都市藝術的接納，這種藝術形式逐漸成為當代藝術市場的重要組成部分，並吸引了學術的討論。都市藝術不僅注重城市空間的利用，也探討了文化認同、全球化與消費主義等現代議題，反映出全球化都市生活的多樣性和複雜性。\r\n\r\n為推動都市藝術在亞洲的影響力，田奈藝術將於2025年1月8日舉辦一場國際藝術家聯展，呈現來自不同國家的都市藝術創作。此次展覽將匯聚波蘭藝術家 Igor Dobrowolski、美國藝術家 Joe Iurato、德國藝術家 Van Ray及日本藝術家 Kinjo（金城敏樹）；這些藝術家將在都市藝術多樣的風格中展現各自的獨特視角與創作手法。\r\n\r\n#聯展  #塗鴉  #裝置藝術  #街頭藝術', '田奈藝術 Gin Huang Gallery', '臺中市梧棲區', '2025-01-08 00:00:00', '2025-02-28 00:00:00', '梧棲區（臺中市）=', 24.24552431, 120.5301259, '無資料', 'https://reurl.cc/1XleY9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='超越街頭：都市藝術的全球視角', `description`='自20世紀末以來，都市藝術，特別是街頭藝術和塗鴉藝術，在全球範圍內迅速受到廣泛關注與喜愛。這些藝術形式起源於城市空間，涵蓋了塗鴉、壁畫、貼紙和裝置藝術等多種媒材。藝術家們通過這些表達形式詮釋都市文化、反映社會現狀，甚至批判現代社會中的制度和問題。與傳統藝術形式相比，都市藝術擁有顛覆性的特質，作品直接呈現在大眾視野中，充滿挑戰權威、顛覆常規的力量。\r\n\r\n都市藝術的歷史可追溯到1970年代的紐約，當時塗鴉成為年輕人抗議社會不公、展現個人身份的手段。隨著時間的推移，這些風格與技術變得更加多樣化，並迅速傳播至全球各地，形成了一種視覺風格強烈、批判社會的藝術運動。塗鴉藝術家運用噴漆、畫刷等工具在公共牆面上留下印記，隨著這些創作從地下文化逐漸進入主流，都市藝術也在當代藝術界獲得了認可。\r\n\r\n近年來，隨著畫廊和博物館對都市藝術的接納，這種藝術形式逐漸成為當代藝術市場的重要組成部分，並吸引了學術的討論。都市藝術不僅注重城市空間的利用，也探討了文化認同、全球化與消費主義等現代議題，反映出全球化都市生活的多樣性和複雜性。\r\n\r\n為推動都市藝術在亞洲的影響力，田奈藝術將於2025年1月8日舉辦一場國際藝術家聯展，呈現來自不同國家的都市藝術創作。此次展覽將匯聚波蘭藝術家 Igor Dobrowolski、美國藝術家 Joe Iurato、德國藝術家 Van Ray及日本藝術家 Kinjo（金城敏樹）；這些藝術家將在都市藝術多樣的風格中展現各自的獨特視角與創作手法。\r\n\r\n#聯展  #塗鴉  #裝置藝術  #街頭藝術', `organizer`='田奈藝術 Gin Huang Gallery', `address`='臺中市梧棲區', `start_date`='2025-01-08 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='梧棲區（臺中市）=', `latitude`=24.24552431, `longitude`=120.5301259, `ticket_price`='無資料', `source_url`='https://reurl.cc/1XleY9', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789788926b32458d4363758', '一德洋樓「質樸-謝志成陶藝展」', '藝術家以台灣苗栗土為媒材，拉胚成形為主要成形方式，作品以單純、不浮誇、樸實簡潔呈現，個人擅長以各色油滴釉為作品上彩妝，也常以切割粘結作為表現方式，以台灣特有苗栗土調製成紫砂、黃泥、朱泥等而製成精美的手拉坯壺，由於高中就讀台中高工機工科，所學也造就壺器極佳的密合度及精細度。\r\n期望此次展出能提升觀展者心靈層面，許多事，簡單樸實，反而能洞察出此時物慾充斥下的時代，反璞歸真方是正道。', '林懋陽故居(一德洋樓) ', '臺中市北屯區文昌東十一街14巷1號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '林懋陽故居(一德洋樓)', 24.18400298, 120.7362319, '無資料', 'https://www.facebook.com/share/p/18QAE9P4XN/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='一德洋樓「質樸-謝志成陶藝展」', `description`='藝術家以台灣苗栗土為媒材，拉胚成形為主要成形方式，作品以單純、不浮誇、樸實簡潔呈現，個人擅長以各色油滴釉為作品上彩妝，也常以切割粘結作為表現方式，以台灣特有苗栗土調製成紫砂、黃泥、朱泥等而製成精美的手拉坯壺，由於高中就讀台中高工機工科，所學也造就壺器極佳的密合度及精細度。\r\n期望此次展出能提升觀展者心靈層面，許多事，簡單樸實，反而能洞察出此時物慾充斥下的時代，反璞歸真方是正道。', `organizer`='林懋陽故居(一德洋樓) ', `address`='臺中市北屯區文昌東十一街14巷1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='林懋陽故居(一德洋樓)', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/18QAE9P4XN/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789788926b32458d4363759', '一德洋樓咆哮年代音樂時光第十季-1-2月歲末新春(共10場次)', '咆哮年代音樂時光，每一季安排都不同，一個場次1組表演團體；12到2月的藝人駐唱，一共安排12場次。\r\n這次規劃除了既有的人氣藝人駐唱外，也安排有樂器雙演奏的形式，更多元的演出形式，可望吸引更多不同族群或年齡層的偏好與參與度。因這段期間有農曆中國年節，故連續假期增加場次，活絡現場熱鬧與節慶氛圍。\r\n\r\n酒吧、爵士樂、香奈兒、女性觀念解放讓20年代變成一個特別的年代。它奔放、它華麗、他奢靡、如同一個百家爭鳴的時代，帶來的影響不僅僅是服裝上的解放，更讓社會大眾的思想也產生了大躍進，同時也讓上百年後的我們，回味與想像力無窮。', '林懋陽故居(一德洋樓) ', '臺中市北屯區文昌東十一街14巷1號', '2025-01-01 00:00:00', '2025-02-25 00:00:00', '林懋陽故居(一德洋樓)', 24.18400298, 120.7362319, '無資料', 'https://www.facebook.com/share/p/15LYrad81Q/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='一德洋樓咆哮年代音樂時光第十季-1-2月歲末新春(共10場次)', `description`='咆哮年代音樂時光，每一季安排都不同，一個場次1組表演團體；12到2月的藝人駐唱，一共安排12場次。\r\n這次規劃除了既有的人氣藝人駐唱外，也安排有樂器雙演奏的形式，更多元的演出形式，可望吸引更多不同族群或年齡層的偏好與參與度。因這段期間有農曆中國年節，故連續假期增加場次，活絡現場熱鬧與節慶氛圍。\r\n\r\n酒吧、爵士樂、香奈兒、女性觀念解放讓20年代變成一個特別的年代。它奔放、它華麗、他奢靡、如同一個百家爭鳴的時代，帶來的影響不僅僅是服裝上的解放，更讓社會大眾的思想也產生了大躍進，同時也讓上百年後的我們，回味與想像力無窮。', `organizer`='林懋陽故居(一德洋樓) ', `address`='臺中市北屯區文昌東十一街14巷1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-25 00:00:00', `location`='林懋陽故居(一德洋樓)', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/15LYrad81Q/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789788926b32458d436375a', '高鮮油畫創作個展─「與自然共遊」', '「與自然共遊」-是以描繪自然環境變化及自然景象為主。從具體外在視覺形象轉化內心情感的抒發，藉由寫意形式呈現，表達心中的感動及喜悅。希望帶給觀賞者對自然景象有無限的想像空間，並加以探討欣賞。\r\n敬邀各界人士蒞臨參觀指教。', '臺中市北區區公所', '臺中市北區永興街301號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '臺中市北區區公所', 24.1659284, 120.6823703, '無資料', 'https://www.north.taichung.gov.tw/834169/834170/1382237/3574586/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高鮮油畫創作個展─「與自然共遊」', `description`='「與自然共遊」-是以描繪自然環境變化及自然景象為主。從具體外在視覺形象轉化內心情感的抒發，藉由寫意形式呈現，表達心中的感動及喜悅。希望帶給觀賞者對自然景象有無限的想像空間，並加以探討欣賞。\r\n敬邀各界人士蒞臨參觀指教。', `organizer`='臺中市北區區公所', `address`='臺中市北區永興街301號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市北區區公所', `latitude`=24.1659284, `longitude`=120.6823703, `ticket_price`='無資料', `source_url`='https://www.north.taichung.gov.tw/834169/834170/1382237/3574586/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6789788d26b32458d436375f', '藝韻新觸動 - 東西方交流藝術家邀請展', '本次邀請展出作品包含東西方美學之美感呈現，參展藝術家有學者教授、藝術名家、藝術新秀等，共同以「藝韻新觸動」為主題，促進在地藝術家與學者的美學交流，呈現新創獨特多元藝術風格。期待在東西方交流與對比下，不僅可以呈現各自的藝術文化，也促進東西方美學間的融合和互相影響的可能性，激勵出新的藝術風格和創作理念。', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-03-14 00:00:00', '2025-03-25 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4079', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝韻新觸動 - 東西方交流藝術家邀請展', `description`='本次邀請展出作品包含東西方美學之美感呈現，參展藝術家有學者教授、藝術名家、藝術新秀等，共同以「藝韻新觸動」為主題，促進在地藝術家與學者的美學交流，呈現新創獨特多元藝術風格。期待在東西方交流與對比下，不僅可以呈現各自的藝術文化，也促進東西方美學間的融合和互相影響的可能性，激勵出新的藝術風格和創作理念。', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4079', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678a03598f15e3aa87f33119', '｢糖、香料，與一切美好的事物」— 曾詠晴個展', '▍展覽簡介｜\r\n\r\n一場讓｢粉紅色｣佔據版面和話語權，主導畫面與敘事的展覽，作品中用甜美討喜的流行元素裝飾反諷、美化、包裝，訴說「他者」被邊緣化的性別定位、種族差異、社會身份與殖民歷史記憶。粉紅色這個色彩本身就有著矛盾的多重定義，讓人貼上各種刻板標籤，正向或負面，都可能引發好惡分明的反應。\r\n\r\n藝術家身為台灣巴基斯坦混血，成長於中東，同時身為女性、有色人種、及伊斯蘭教徒，以當今西方世界主導的視角，本人即是十足的「他者」三重奏。\r\n\r\n她將粉紅色視為和自己一樣的「他者」去共感思考，作品中以拼貼媒材展現女性元素、服飾意象、傳統圖騰，串聯全球南方多重文化的生命軌跡，作為西方價值的鏡像反面，也帶來權勢倒置的視覺挑戰。\r\n\r\n▍藝術家｜曾詠晴\r\n▍展覽日期｜2025.02.06（四）－2025.03.06（四）\r\n▍開幕茶會｜2025.02.15（六） 14:30\r\n▍展覽地點｜新浜碼頭藝術空間\r\n▍主辦單位｜高雄市新浜碼頭藝術學會\r\n▍空間贊助單位｜國藝會\r\n▍新浜行政｜陳羚溱、吳宛倫\r\n▍實習生｜孔媛', '新浜碼頭藝術空間', '高雄市鹽埕區大勇路64號2F', '2025-02-06 00:00:00', '2025-03-06 00:00:00', '新浜碼頭藝術空間', 22.62424585, 120.2842331, '無資料', 'https://sinpink.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='｢糖、香料，與一切美好的事物」— 曾詠晴個展', `description`='▍展覽簡介｜\r\n\r\n一場讓｢粉紅色｣佔據版面和話語權，主導畫面與敘事的展覽，作品中用甜美討喜的流行元素裝飾反諷、美化、包裝，訴說「他者」被邊緣化的性別定位、種族差異、社會身份與殖民歷史記憶。粉紅色這個色彩本身就有著矛盾的多重定義，讓人貼上各種刻板標籤，正向或負面，都可能引發好惡分明的反應。\r\n\r\n藝術家身為台灣巴基斯坦混血，成長於中東，同時身為女性、有色人種、及伊斯蘭教徒，以當今西方世界主導的視角，本人即是十足的「他者」三重奏。\r\n\r\n她將粉紅色視為和自己一樣的「他者」去共感思考，作品中以拼貼媒材展現女性元素、服飾意象、傳統圖騰，串聯全球南方多重文化的生命軌跡，作為西方價值的鏡像反面，也帶來權勢倒置的視覺挑戰。\r\n\r\n▍藝術家｜曾詠晴\r\n▍展覽日期｜2025.02.06（四）－2025.03.06（四）\r\n▍開幕茶會｜2025.02.15（六） 14:30\r\n▍展覽地點｜新浜碼頭藝術空間\r\n▍主辦單位｜高雄市新浜碼頭藝術學會\r\n▍空間贊助單位｜國藝會\r\n▍新浜行政｜陳羚溱、吳宛倫\r\n▍實習生｜孔媛', `organizer`='新浜碼頭藝術空間', `address`='高雄市鹽埕區大勇路64號2F', `start_date`='2025-02-06 00:00:00', `end_date`='2025-03-06 00:00:00', `location`='新浜碼頭藝術空間', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='無資料', `source_url`='https://sinpink.com/', `image_url`='[]';
