INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678c1dfc26b32458d43637c9', '【黑白】與【彩色】李進裕攝影展', '2024黑面琵鷺保育季系列活動在10月20日起陸續登場，其中邀請李進裕老師展出生態主題攝影展，包括來台度冬的「國際明星鳥」黑面琵鷺，展現七股的生態之美。', '臺南市生態保育學會', '臺南市七股區海埔47號', '2025-01-01 00:00:00', '2025-03-31 00:00:00', '臺南市黑面琵鷺生態展示館', 23.12326578, 120.1005854, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【黑白】與【彩色】李進裕攝影展', `description`='2024黑面琵鷺保育季系列活動在10月20日起陸續登場，其中邀請李進裕老師展出生態主題攝影展，包括來台度冬的「國際明星鳥」黑面琵鷺，展現七股的生態之美。', `organizer`='臺南市生態保育學會', `address`='臺南市七股區海埔47號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市黑面琵鷺生態展示館', `latitude`=23.12326578, `longitude`=120.1005854, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678c1dfd26b32458d43637cb', '西方浪漫．臺灣製造—70年代臺灣瓷偶產業的故事', '國立臺灣工藝研究發展中心為促進地方工藝產業發展，推出「薪火相傳-玻璃工藝薪創展」，展出玻璃工藝師林瑤農師生創作共39件玻璃作品。本展以玻璃工藝作品為載體，於琉光溢彩之中呈現臺灣在地自然與人文的豐富內涵，誠摯邀請喜愛工藝以及想更加認識臺灣在地文化的朋友們共同來展場，感受多姿多采的臺灣玻璃工藝之美。\r\n臺灣的玻璃產業，從清光緒十三年（西元1887年）的台北地區發軔，中日戰爭前後，日本派遣技師調查新竹地區的珪砂蘊藏分佈情形，發現新竹地區具有豐富的蘊藏及得天獨厚的自然資源條件，傳統玻璃產業發達。後來，在時代變遷之下，新竹的玻璃產業迎來轉型，由工業漸漸朝向附加價值更高的玻璃藝術方向發展，進而形成獨具特色的地方工藝文化產業。 \r\n本展藉由玻璃大師林瑤農與林邑龍、林佑駿、陳建志的師生世代工藝傳承，演繹臺灣玻璃工藝的生命力。出生於新竹的林瑤農曾獲文化部臺灣工藝之家認證以及新竹市無形文化資產玻璃傳統技藝保存者肯定，將其對玻璃材質的獨特性，透明、多彩、延展、映射等特質的掌握，透過高溫烈焰的焠煉，手工人力雕塑結合其獨特的口吹玻璃及拉絲玻璃技法，創造出讓人可無限想像的驚奇作品，不僅融入自然的花鳥魚蟲，亦傳遞在地人文的美好意涵，諸如「海洋生態」、「風華再現」、「花開富貴」、「聚寶盆」等，質地晶瑩玲瓏的玻璃，透過匠心獨具的創意巧思，轉化而成溫暖的、抒情的藝術表現。', '國立臺灣工藝研究發展中心', '苗栗縣苗栗市水流娘巷11鄰8-2號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '苗栗工藝產業研發分館', 24.5328836, 120.8165288, '無資料', 'https://www.ntcri.gov.tw/home/zh-tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='西方浪漫．臺灣製造—70年代臺灣瓷偶產業的故事', `description`='國立臺灣工藝研究發展中心為促進地方工藝產業發展，推出「薪火相傳-玻璃工藝薪創展」，展出玻璃工藝師林瑤農師生創作共39件玻璃作品。本展以玻璃工藝作品為載體，於琉光溢彩之中呈現臺灣在地自然與人文的豐富內涵，誠摯邀請喜愛工藝以及想更加認識臺灣在地文化的朋友們共同來展場，感受多姿多采的臺灣玻璃工藝之美。\r\n臺灣的玻璃產業，從清光緒十三年（西元1887年）的台北地區發軔，中日戰爭前後，日本派遣技師調查新竹地區的珪砂蘊藏分佈情形，發現新竹地區具有豐富的蘊藏及得天獨厚的自然資源條件，傳統玻璃產業發達。後來，在時代變遷之下，新竹的玻璃產業迎來轉型，由工業漸漸朝向附加價值更高的玻璃藝術方向發展，進而形成獨具特色的地方工藝文化產業。 \r\n本展藉由玻璃大師林瑤農與林邑龍、林佑駿、陳建志的師生世代工藝傳承，演繹臺灣玻璃工藝的生命力。出生於新竹的林瑤農曾獲文化部臺灣工藝之家認證以及新竹市無形文化資產玻璃傳統技藝保存者肯定，將其對玻璃材質的獨特性，透明、多彩、延展、映射等特質的掌握，透過高溫烈焰的焠煉，手工人力雕塑結合其獨特的口吹玻璃及拉絲玻璃技法，創造出讓人可無限想像的驚奇作品，不僅融入自然的花鳥魚蟲，亦傳遞在地人文的美好意涵，諸如「海洋生態」、「風華再現」、「花開富貴」、「聚寶盆」等，質地晶瑩玲瓏的玻璃，透過匠心獨具的創意巧思，轉化而成溫暖的、抒情的藝術表現。', `organizer`='國立臺灣工藝研究發展中心', `address`='苗栗縣苗栗市水流娘巷11鄰8-2號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='苗栗工藝產業研發分館', `latitude`=24.5328836, `longitude`=120.8165288, `ticket_price`='無資料', `source_url`='https://www.ntcri.gov.tw/home/zh-tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678c1dfd26b32458d43637cc', '臺灣工藝百年進行式', '這是一個以工藝為主體，由時間的概念、觀看、感知，直入臺灣工藝的展覽。\r\n1920年《臺灣通史》出版，「工藝」首度成志。以百年為尺度，我們清楚看見工藝的模樣：是這塊土地上日常所生成的美、是人們豐富交流所煥發的活潑創意、是製作不歇的身影所凝聚的精神厚度，也是永遠迎向環境挑戰開創的勇氣。\r\n臺灣工藝，百年前已呈現虹彩般的光譜，此時此刻，我們習慣歸諸於傳統的，其實也和我們以為最新穎的，同樣屬於「現在」的一部分。這百年來，臺灣工藝所保有的多樣性，正是讓我們擁有能夠選擇的自由、面向未來的豐厚資本。\r\n於是，這個展覽並非意圖呈現一段線性發展的工藝史，而是希望透過百年的梳理，看見臺灣工藝滾動、累積並自我再生的特質。\r\n導覽預約 https://event.culture.tw/NTCRI/portal/Tour/J5401MAction', '國立臺灣工藝研究發展中心', '南投縣草屯鎮中正路573號', '2025-01-01 00:00:00', '2025-06-29 00:00:00', '國立臺灣工藝研究發展中心（臺灣工藝文化園區）', 23.9807747, 120.6918567, '無資料', 'https://www.ntcri.gov.tw/home/zh-tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺灣工藝百年進行式', `description`='這是一個以工藝為主體，由時間的概念、觀看、感知，直入臺灣工藝的展覽。\r\n1920年《臺灣通史》出版，「工藝」首度成志。以百年為尺度，我們清楚看見工藝的模樣：是這塊土地上日常所生成的美、是人們豐富交流所煥發的活潑創意、是製作不歇的身影所凝聚的精神厚度，也是永遠迎向環境挑戰開創的勇氣。\r\n臺灣工藝，百年前已呈現虹彩般的光譜，此時此刻，我們習慣歸諸於傳統的，其實也和我們以為最新穎的，同樣屬於「現在」的一部分。這百年來，臺灣工藝所保有的多樣性，正是讓我們擁有能夠選擇的自由、面向未來的豐厚資本。\r\n於是，這個展覽並非意圖呈現一段線性發展的工藝史，而是希望透過百年的梳理，看見臺灣工藝滾動、累積並自我再生的特質。\r\n導覽預約 https://event.culture.tw/NTCRI/portal/Tour/J5401MAction', `organizer`='國立臺灣工藝研究發展中心', `address`='南投縣草屯鎮中正路573號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='國立臺灣工藝研究發展中心（臺灣工藝文化園區）', `latitude`=23.9807747, `longitude`=120.6918567, `ticket_price`='無資料', `source_url`='https://www.ntcri.gov.tw/home/zh-tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678c1dfd26b32458d43637cd', '工藝線-地方特色工藝展', '臺灣因位處亞熱帶海島地理環境，擁有豐富的天然資源，隨著時間的推進，人們因應在地的自然風土文化，運用在地資源素材轉化形成多元樣貌的地方特色工藝。\r\n國立臺灣工藝研究發展中心自1994年配合文建會「社區總體營造」政策推動地方工藝產業、1999年921震區工藝扶植計畫、2002年推動「文化創意產業」-工藝旗艦計畫、2005年推動「多角化社區工藝扶植計畫」，2014年起更與行政院農委會水保局合作，推動「農村微型工藝產業培力補助計畫」，多年累積輔導超過130個工藝社區。輔導首先著重於培育地方人才，挖掘根源於土地的地方故事，將工藝與地方緊密結合，而後凝聚眾人之力，建立並拓展品牌形象。本次展覽首先挑選20個較具代表性及潛力之地方工藝，帶領民眾認識臺灣地方工藝。\r\n\r\n導覽預約 https://event.culture.tw/NTCRI/portal/Tour/J5401MAction', '國立臺灣工藝研究發展中心', '南投縣草屯鎮中正路573號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '國立臺灣工藝研究發展中心（臺灣工藝文化園區）', 23.9807747, 120.6918567, '無資料', 'https://www.ntcri.gov.tw/home/zh-tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='工藝線-地方特色工藝展', `description`='臺灣因位處亞熱帶海島地理環境，擁有豐富的天然資源，隨著時間的推進，人們因應在地的自然風土文化，運用在地資源素材轉化形成多元樣貌的地方特色工藝。\r\n國立臺灣工藝研究發展中心自1994年配合文建會「社區總體營造」政策推動地方工藝產業、1999年921震區工藝扶植計畫、2002年推動「文化創意產業」-工藝旗艦計畫、2005年推動「多角化社區工藝扶植計畫」，2014年起更與行政院農委會水保局合作，推動「農村微型工藝產業培力補助計畫」，多年累積輔導超過130個工藝社區。輔導首先著重於培育地方人才，挖掘根源於土地的地方故事，將工藝與地方緊密結合，而後凝聚眾人之力，建立並拓展品牌形象。本次展覽首先挑選20個較具代表性及潛力之地方工藝，帶領民眾認識臺灣地方工藝。\r\n\r\n導覽預約 https://event.culture.tw/NTCRI/portal/Tour/J5401MAction', `organizer`='國立臺灣工藝研究發展中心', `address`='南投縣草屯鎮中正路573號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='國立臺灣工藝研究發展中心（臺灣工藝文化園區）', `latitude`=23.9807747, `longitude`=120.6918567, `ticket_price`='無資料', `source_url`='https://www.ntcri.gov.tw/home/zh-tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678c1dfd26b32458d43637d3', '2025鹿谷燈會', '光線串聯的湖光山色，伴著烏龍茶香，結合農曆年節燈會文化，傳統文化結合藝術創新，在此打造一場沉浸式視覺饗宴，帶著民眾時空旅行，進入藝術交錯的派對空間。', '南投縣鹿谷鄉公所', '南投縣鹿谷鄉', '2025-01-24 00:00:00', '2025-03-19 00:00:00', '鹿谷鄉（南投縣）=', 23.73776029, 120.7815065, '無資料', 'https://rs-event.com.tw/2025NTL/index.html', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025鹿谷燈會', `description`='光線串聯的湖光山色，伴著烏龍茶香，結合農曆年節燈會文化，傳統文化結合藝術創新，在此打造一場沉浸式視覺饗宴，帶著民眾時空旅行，進入藝術交錯的派對空間。', `organizer`='南投縣鹿谷鄉公所', `address`='南投縣鹿谷鄉', `start_date`='2025-01-24 00:00:00', `end_date`='2025-03-19 00:00:00', `location`='鹿谷鄉（南投縣）=', `latitude`=23.73776029, `longitude`=120.7815065, `ticket_price`='無資料', `source_url`='https://rs-event.com.tw/2025NTL/index.html', `image_url`='[]';
