INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678d717326b32458d43637dc', '2025年世界母語日展覽─咱畫咱的話', '為推廣世界母語日，展覽匯集臺南市113學年度「魔法語花一頁書」競賽得獎作品及影音，融合語文、藝術與人文，展現母語的多樣性和豐富的文化底蘊，呈現多元文化與語言的繽紛魅力。', '臺南市政府教育局', '臺南市中西區中華西路二段34號', '2025-02-09 00:00:00', '2025-02-26 00:00:00', '國立臺南生活美學館', 22.99594458, 120.192874, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年世界母語日展覽─咱畫咱的話', `description`='為推廣世界母語日，展覽匯集臺南市113學年度「魔法語花一頁書」競賽得獎作品及影音，融合語文、藝術與人文，展現母語的多樣性和豐富的文化底蘊，呈現多元文化與語言的繽紛魅力。', `organizer`='臺南市政府教育局', `address`='臺南市中西區中華西路二段34號', `start_date`='2025-02-09 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='國立臺南生活美學館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678d717326b32458d43637dd', '臺南市奇美博物館【常設展】動物廳', '【常設展】動物廳\r\n\r\n走入動物廳，躍然眼前的是大象家族，牠們引領大批動物們列隊歡迎前來參觀的民眾，展現出來自非洲草原的生命力！本展廳依不同洲別將動物標本分類展示，中島型開放式的設計，拉近遊客與動物標本的距離，讓人彷彿參與一場動物大遊行；另有模擬自然生態、動物習性的情境展櫃，幫助民眾輕鬆認識動物特性。此外，化石展示區亦是一大特色，好好走一趟就能了解地球的生命演進史。', '奇美博物館', '臺南市仁德區文華路二段66號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺南市奇美博物館', 22.94130931, 120.2418788, '常設展全票+200;常設展優惠票+150', 'https://www.chimeimuseum.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市奇美博物館【常設展】動物廳', `description`='【常設展】動物廳\r\n\r\n走入動物廳，躍然眼前的是大象家族，牠們引領大批動物們列隊歡迎前來參觀的民眾，展現出來自非洲草原的生命力！本展廳依不同洲別將動物標本分類展示，中島型開放式的設計，拉近遊客與動物標本的距離，讓人彷彿參與一場動物大遊行；另有模擬自然生態、動物習性的情境展櫃，幫助民眾輕鬆認識動物特性。此外，化石展示區亦是一大特色，好好走一趟就能了解地球的生命演進史。', `organizer`='奇美博物館', `address`='臺南市仁德區文華路二段66號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺南市奇美博物館', `latitude`=22.94130931, `longitude`=120.2418788, `ticket_price`='常設展全票+200;常設展優惠票+150', `source_url`='https://www.chimeimuseum.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678d717326b32458d43637de', '臺南市奇美博物館【常設展】走入管弦樂團', '走入管弦樂團\r\n多聲道影音節目\r\n在這裡，您可以親身「走」入且穿梭在音樂家之間，近距離觀察樂器、了解管弦樂團的編制，並欣賞臨場感十足的精彩演奏。\r\n\r\n合作單位：NSO國家交響樂團\r\n\r\n整點時段｜所有樂器一起合奏\r\n其它時段｜各個音樂家輪流解說自己演奏的樂器\r\n語言｜華語\r\n\r\n合奏節目表｜\r\n史麥塔納–〈莫爾道河〉，選自《我的祖國》 \r\nBEDŘICH SMETANA –‘Vltava’from Má Vlast\r\n場次：10:00、13:00、16:00\r\n長度：約12分鐘\r\n\r\n貝多芬–第七號交響曲，第二樂章\r\nLUDWIG VAN BEETHOVEN–Symphony No. 7, Op. 92, Mvt. II\r\n場次：11:00、14:00、17:00\r\n長度：約8分鐘\r\n\r\n普羅科菲夫–〈騎士之舞〉，選自《羅密歐與茱麗葉》組曲\r\nSERGEI PROKOFIEV–‘Montagues and Capulets’ (Dance of the Knights),from Romeo et Juliet Suite No.2, Op.64\r\n場次：12:00、15:00\r\n長度：約5分鐘', '奇美博物館', '臺南市仁德區文華路二段66號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺南市奇美博物館', 22.94130931, 120.2418788, '常設展全票+200;常設展優惠票+150', 'https://www.chimeimuseum.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市奇美博物館【常設展】走入管弦樂團', `description`='走入管弦樂團\r\n多聲道影音節目\r\n在這裡，您可以親身「走」入且穿梭在音樂家之間，近距離觀察樂器、了解管弦樂團的編制，並欣賞臨場感十足的精彩演奏。\r\n\r\n合作單位：NSO國家交響樂團\r\n\r\n整點時段｜所有樂器一起合奏\r\n其它時段｜各個音樂家輪流解說自己演奏的樂器\r\n語言｜華語\r\n\r\n合奏節目表｜\r\n史麥塔納–〈莫爾道河〉，選自《我的祖國》 \r\nBEDŘICH SMETANA –‘Vltava’from Má Vlast\r\n場次：10:00、13:00、16:00\r\n長度：約12分鐘\r\n\r\n貝多芬–第七號交響曲，第二樂章\r\nLUDWIG VAN BEETHOVEN–Symphony No. 7, Op. 92, Mvt. II\r\n場次：11:00、14:00、17:00\r\n長度：約8分鐘\r\n\r\n普羅科菲夫–〈騎士之舞〉，選自《羅密歐與茱麗葉》組曲\r\nSERGEI PROKOFIEV–‘Montagues and Capulets’ (Dance of the Knights),from Romeo et Juliet Suite No.2, Op.64\r\n場次：12:00、15:00\r\n長度：約5分鐘', `organizer`='奇美博物館', `address`='臺南市仁德區文華路二段66號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺南市奇美博物館', `latitude`=22.94130931, `longitude`=120.2418788, `ticket_price`='常設展全票+200;常設展優惠票+150', `source_url`='https://www.chimeimuseum.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678d717326b32458d43637df', '臺南市奇美博物館【常設展】樂器廳', '蒐藏初心\r\n奇美博物館的樂器收藏包括世界民族樂器、自動樂器及名提琴。其中「名提琴」的收藏最為知名，以系統性的方式針對全球重要製琴師的師承派別、區域與年份進行蒐集，至今已是全球最大的提琴典藏機構。\r\n \r\n對喜愛音樂的許創辦人而言，蒐藏樂器是為了與民眾分享美好的音樂，為人們帶來幸福與感動，更是守護這些樂器可以長長久久流傳下去。特別是名琴，許創辦人曾說，名琴是人類文化遺產，只是暫時由奇美保管，奇美有義務及責任保護這些大師的樂器作品，讓子孫不是只能在書上想像古老名琴的音色，而是能夠真實聆賞它的悠揚樂音。名琴除了展示之外，也出借給臺灣學子就學及比賽所用。\r\n \r\n奇美博物館每年也不定期舉辦名琴音樂會，此外，積極參與各種國際級提琴交流活動，藉此實踐「共享共賞」的精神，讓流傳四、五百年的古琴，在當代社會發揮更深遠的影響力。\r\n\r\n【常設展】樂器廳\r\n\r\n奇美博物館「樂器廳」分為兩大部分，第一部分規劃「世界民族樂器」、「走入管弦樂團」、「機械音樂家」三大展區。「世界民族樂器」以地域分布為經、樂器發聲類型為緯，展出世界民族樂器的多元面貌。「走入管弦樂團」為全球首創的虛擬交響樂團，以管弦樂團的基礎配置作為空間設計，搭配多聲道影音畫面，讓民眾彷彿置身音樂會現場，而且還能走入樂團之中，從指揮家、演奏家的角度，體會各個樂器之於交響樂團所扮演的角色。「機械音樂家」呈現「自動樂器」等裝置如何將音樂留存下來、重複播放的發展過程。第二部分為獨立的「提琴」展區，精選藏品中各國最早製琴師的經典作品，同時設置提琴製作工坊、琴弓變革等內容。\r\n', '奇美博物館', '臺南市仁德區文華路二段66號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺南市奇美博物館', 22.94130931, 120.2418788, '常設展全票+200;常設展優惠票+150', 'https://www.chimeimuseum.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市奇美博物館【常設展】樂器廳', `description`='蒐藏初心\r\n奇美博物館的樂器收藏包括世界民族樂器、自動樂器及名提琴。其中「名提琴」的收藏最為知名，以系統性的方式針對全球重要製琴師的師承派別、區域與年份進行蒐集，至今已是全球最大的提琴典藏機構。\r\n \r\n對喜愛音樂的許創辦人而言，蒐藏樂器是為了與民眾分享美好的音樂，為人們帶來幸福與感動，更是守護這些樂器可以長長久久流傳下去。特別是名琴，許創辦人曾說，名琴是人類文化遺產，只是暫時由奇美保管，奇美有義務及責任保護這些大師的樂器作品，讓子孫不是只能在書上想像古老名琴的音色，而是能夠真實聆賞它的悠揚樂音。名琴除了展示之外，也出借給臺灣學子就學及比賽所用。\r\n \r\n奇美博物館每年也不定期舉辦名琴音樂會，此外，積極參與各種國際級提琴交流活動，藉此實踐「共享共賞」的精神，讓流傳四、五百年的古琴，在當代社會發揮更深遠的影響力。\r\n\r\n【常設展】樂器廳\r\n\r\n奇美博物館「樂器廳」分為兩大部分，第一部分規劃「世界民族樂器」、「走入管弦樂團」、「機械音樂家」三大展區。「世界民族樂器」以地域分布為經、樂器發聲類型為緯，展出世界民族樂器的多元面貌。「走入管弦樂團」為全球首創的虛擬交響樂團，以管弦樂團的基礎配置作為空間設計，搭配多聲道影音畫面，讓民眾彷彿置身音樂會現場，而且還能走入樂團之中，從指揮家、演奏家的角度，體會各個樂器之於交響樂團所扮演的角色。「機械音樂家」呈現「自動樂器」等裝置如何將音樂留存下來、重複播放的發展過程。第二部分為獨立的「提琴」展區，精選藏品中各國最早製琴師的經典作品，同時設置提琴製作工坊、琴弓變革等內容。\r\n', `organizer`='奇美博物館', `address`='臺南市仁德區文華路二段66號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺南市奇美博物館', `latitude`=22.94130931, `longitude`=120.2418788, `ticket_price`='常設展全票+200;常設展優惠票+150', `source_url`='https://www.chimeimuseum.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678d717326b32458d43637e0', '臺南市奇美博物館【常設展】兵器廳', '【常設展】兵器廳\r\n奇美博物館的兵器廳分為「歐洲」與「非歐洲」兩大展區。「歐洲區」將多元複雜的兵器分門別類介紹，並設置兵器演進長廊，展示史前至近現代十九世紀的代表性兵器，呈現兵器在歷史上整體進程的概念。「非歐洲區」則以地理位置劃分十多個不同展區，如中國、日本、非洲、印度波斯等，呈現豐富多樣的裝飾風格與文化特色。\r\n \r\n', '奇美博物館', '臺南市仁德區文華路二段66號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺南市奇美博物館', 22.94130931, 120.2418788, '常設展全票+200;常設展優惠票+150', 'https://www.chimeimuseum.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市奇美博物館【常設展】兵器廳', `description`='【常設展】兵器廳\r\n奇美博物館的兵器廳分為「歐洲」與「非歐洲」兩大展區。「歐洲區」將多元複雜的兵器分門別類介紹，並設置兵器演進長廊，展示史前至近現代十九世紀的代表性兵器，呈現兵器在歷史上整體進程的概念。「非歐洲區」則以地理位置劃分十多個不同展區，如中國、日本、非洲、印度波斯等，呈現豐富多樣的裝飾風格與文化特色。\r\n \r\n', `organizer`='奇美博物館', `address`='臺南市仁德區文華路二段66號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺南市奇美博物館', `latitude`=22.94130931, `longitude`=120.2418788, `ticket_price`='常設展全票+200;常設展優惠票+150', `source_url`='https://www.chimeimuseum.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678d717426b32458d43637e1', '臺南市奇美博物館【常設展】藝術廳', '【常設展】藝術廳\r\n\r\n西洋藝術作品以三大展廳呈現，包括「藝術廳」、「雕塑大道」、「羅丹廳」。遊走其間，能夠感受猶如置身國外美術館般的特別體驗，是許多台灣民眾印象深刻的主題場域。「藝術廳」將13至20世紀的藝術作品分成四個時期、八個展間呈現，跟隨策展邏輯循序觀賞，即可了解西洋藝術發展的時代概念。\r\n \r\n「雕塑大道」為館內唯一採用天窗設計的挑高空間，雕塑作品隨日照變化展現出光影層次的肌理美感，更加引人入勝。此區展示古希臘羅馬時代至20世紀的作品，希望建構出基礎的西洋雕塑觀賞脈絡。 「羅丹廳」帶您認識「現代雕塑之父」身處的時代背景與藝術環境，集結了羅丹本身，以及他的老師、同儕和學生的作品，並打造四大雕塑家工作室。從觀察與對照之中，可以看見羅丹與前後代、同輩之間的關係。', '奇美博物館', '臺南市仁德區文華路二段66號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺南市奇美博物館', 22.94130931, 120.2418788, '常設展全票+200;常設展優惠票+150', 'https://www.chimeimuseum.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市奇美博物館【常設展】藝術廳', `description`='【常設展】藝術廳\r\n\r\n西洋藝術作品以三大展廳呈現，包括「藝術廳」、「雕塑大道」、「羅丹廳」。遊走其間，能夠感受猶如置身國外美術館般的特別體驗，是許多台灣民眾印象深刻的主題場域。「藝術廳」將13至20世紀的藝術作品分成四個時期、八個展間呈現，跟隨策展邏輯循序觀賞，即可了解西洋藝術發展的時代概念。\r\n \r\n「雕塑大道」為館內唯一採用天窗設計的挑高空間，雕塑作品隨日照變化展現出光影層次的肌理美感，更加引人入勝。此區展示古希臘羅馬時代至20世紀的作品，希望建構出基礎的西洋雕塑觀賞脈絡。 「羅丹廳」帶您認識「現代雕塑之父」身處的時代背景與藝術環境，集結了羅丹本身，以及他的老師、同儕和學生的作品，並打造四大雕塑家工作室。從觀察與對照之中，可以看見羅丹與前後代、同輩之間的關係。', `organizer`='奇美博物館', `address`='臺南市仁德區文華路二段66號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺南市奇美博物館', `latitude`=22.94130931, `longitude`=120.2418788, `ticket_price`='常設展全票+200;常設展優惠票+150', `source_url`='https://www.chimeimuseum.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678d717426b32458d43637e2', '《穿越時空的航海家》', '《穿越時空的航海家》有別於《穹頂計畫》系列，是奇美博物館首款具AR擴增實境功能的實境遊戲INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678d717426b32458d43637e3', '臺南市奇美博物館【常設展】《時間的房間》', '時間的房間\r\n沉浸式劇場\r\n走入時間的房間，您將進入《音樂的寓意》天井畫的時代背景，身歷其境參與它從 19 世紀迄今的流轉境遇。\r\n\r\n場次｜華語解說每15分鐘一場、英語解說每整點一場\r\n長度｜約 8 分鐘\r\n資格｜自由參加，每場以 10 人為限，額滿為止', '奇美博物館', '臺南市仁德區文華路二段66號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺南市奇美博物館', 22.94130931, 120.2418788, '常設展全票+200;常設展優惠票+150', 'https://www.chimeimuseum.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市奇美博物館【常設展】《時間的房間》', `description`='時間的房間\r\n沉浸式劇場\r\n走入時間的房間，您將進入《音樂的寓意》天井畫的時代背景，身歷其境參與它從 19 世紀迄今的流轉境遇。\r\n\r\n場次｜華語解說每15分鐘一場、英語解說每整點一場\r\n長度｜約 8 分鐘\r\n資格｜自由參加，每場以 10 人為限，額滿為止', `organizer`='奇美博物館', `address`='臺南市仁德區文華路二段66號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺南市奇美博物館', `latitude`=22.94130931, `longitude`=120.2418788, `ticket_price`='常設展全票+200;常設展優惠票+150', `source_url`='https://www.chimeimuseum.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678d717426b32458d43637e4', '穹頂計畫', '密函、陰謀、寶藏\r\n一段跨越百年的糾葛，你是否能全身而退？\r\n \r\n\r\n遊戲中，你將化身為寶藏獵人《六奇士團》的成員，接受鑑定師委託前去奇美博物館調查名畫《音樂的寓意》，沒想到竟發現背後有著驚人的秘密！ 為了找出真相，你必須在各展廳中找尋線索，利用手機、道具和展品互相搭配，才能拼湊出百年前先人精心籌備的穹頂計畫，並找到傳說中的珍貴寶藏！\r\n\r\n涵蓋藝術、自然史、兵器、樂器 | 邀您穿梭展廳，解謎12道\r\n\r\n12組解謎任務\r\n（含8個關卡、4條支線挑戰）暗藏玄機、樣式各異的謎題道具，帶你穿梭常設展廳，一邊解謎一邊認識精彩藏品。\r\n\r\n遊戲盒帶入展廳即可開始玩！\r\n不需另外購買門票，不需下載APP，手機連上系統即可進入故事情節開啟挑戰。\r\n\r\n合作、競賽都行，越多人玩越有趣！\r\n一隊以3-6人為限，沒有場次限制、不需工作人員，想玩就出發！不限遊戲時間，玩到破關為止。', '奇美博物館', '臺南市仁德區文華路二段66號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺南市奇美博物館', 22.94130931, 120.2418788, '三人組+1500;四人組+1700;五人組+1900;六人組+2100', 'https://www.chimeimuseum.org/event/62b9622897e39', '[]') ON DUPLICATE KEY UPDATE `activity_name`='穹頂計畫', `description`='密函、陰謀、寶藏\r\n一段跨越百年的糾葛，你是否能全身而退？\r\n \r\n\r\n遊戲中，你將化身為寶藏獵人《六奇士團》的成員，接受鑑定師委託前去奇美博物館調查名畫《音樂的寓意》，沒想到竟發現背後有著驚人的秘密！ 為了找出真相，你必須在各展廳中找尋線索，利用手機、道具和展品互相搭配，才能拼湊出百年前先人精心籌備的穹頂計畫，並找到傳說中的珍貴寶藏！\r\n\r\n涵蓋藝術、自然史、兵器、樂器 | 邀您穿梭展廳，解謎12道\r\n\r\n12組解謎任務\r\n（含8個關卡、4條支線挑戰）暗藏玄機、樣式各異的謎題道具，帶你穿梭常設展廳，一邊解謎一邊認識精彩藏品。\r\n\r\n遊戲盒帶入展廳即可開始玩！\r\n不需另外購買門票，不需下載APP，手機連上系統即可進入故事情節開啟挑戰。\r\n\r\n合作、競賽都行，越多人玩越有趣！\r\n一隊以3-6人為限，沒有場次限制、不需工作人員，想玩就出發！不限遊戲時間，玩到破關為止。', `organizer`='奇美博物館', `address`='臺南市仁德區文華路二段66號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺南市奇美博物館', `latitude`=22.94130931, `longitude`=120.2418788, `ticket_price`='三人組+1500;四人組+1700;五人組+1900;六人組+2100', `source_url`='https://www.chimeimuseum.org/event/62b9622897e39', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678d717426b32458d43637e5', '穹頂計畫Ⅱ 潘神之子', '奇美博物館的三座雕像在半夜憑空消失，現場沒有破壞痕跡也找不到監控影像，只剩一封神祕信函，看似與希臘神話暗藏關係？！\r\n\r\n當警方全力追查失竊藏品時，寶藏獵人團「六奇士」現身博物館，指出竊盜者的目的並不是為了嘲笑警方，而是一個狂妄的犯罪預告！\r\n\r\n希臘神話貫穿主題館藏 | 穿梭展廳解謎任務 ‧ 緝捕怪盜「潘神之子」\r\n\r\n全新解謎任務\r\n（含8個關卡、4次部署任務）暗藏玄機、樣式各異的謎題道具，帶你穿梭常設展廳，一邊解謎一邊認識精彩藏品。\r\n\r\n遊戲盒帶入展廳即可開始玩！\r\n不需另外購買門票，不需下載APP，手機連上系統即可進入故事情節開啟挑戰。\r\n\r\n合作、競賽都行，越多人玩越有趣！\r\n一隊以3-6人為限，沒有場次限制、不需工作人員，想玩就出發！不限遊戲時間，玩到破關為止。\r\n\r\n面對神祕怪盜集團「潘神之子」接二連三的挑釁，身為六奇士的你，是找出真相…還是捲入更多的謎團？', '奇美博物館', '臺南市仁德區文華路二段66號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺南市奇美博物館', 22.94130931, 120.2418788, '費用+1980', 'https://www.chimeimuseum.org/event/62b96425d5e25', '[]') ON DUPLICATE KEY UPDATE `activity_name`='穹頂計畫Ⅱ 潘神之子', `description`='奇美博物館的三座雕像在半夜憑空消失，現場沒有破壞痕跡也找不到監控影像，只剩一封神祕信函，看似與希臘神話暗藏關係？！\r\n\r\n當警方全力追查失竊藏品時，寶藏獵人團「六奇士」現身博物館，指出竊盜者的目的並不是為了嘲笑警方，而是一個狂妄的犯罪預告！\r\n\r\n希臘神話貫穿主題館藏 | 穿梭展廳解謎任務 ‧ 緝捕怪盜「潘神之子」\r\n\r\n全新解謎任務\r\n（含8個關卡、4次部署任務）暗藏玄機、樣式各異的謎題道具，帶你穿梭常設展廳，一邊解謎一邊認識精彩藏品。\r\n\r\n遊戲盒帶入展廳即可開始玩！\r\n不需另外購買門票，不需下載APP，手機連上系統即可進入故事情節開啟挑戰。\r\n\r\n合作、競賽都行，越多人玩越有趣！\r\n一隊以3-6人為限，沒有場次限制、不需工作人員，想玩就出發！不限遊戲時間，玩到破關為止。\r\n\r\n面對神祕怪盜集團「潘神之子」接二連三的挑釁，身為六奇士的你，是找出真相…還是捲入更多的謎團？', `organizer`='奇美博物館', `address`='臺南市仁德區文華路二段66號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺南市奇美博物館', `latitude`=22.94130931, `longitude`=120.2418788, `ticket_price`='費用+1980', `source_url`='https://www.chimeimuseum.org/event/62b96425d5e25', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678d717426b32458d43637e6', '穹頂計畫III 末日慶典', '    在上次盜竊藏品功虧一簣後，隱藏版的第七位成員奧德修斯再次對六奇士提出挑戰。他將過去盜竊的十二件希臘文物寄送至奇美博物館，同時宣稱將啟動偉大的「末日慶典」計畫，讓世界陷入狂喜之中。身為六奇士的你們，手上的線索只有一張奧德修斯掉落的照片，以及四位沒有不在場證明的嫌疑人。\r\n你們的任務是要抓到奧德修斯，查清「末日慶典」的真面目，並阻止計畫啟動。\r\n\r\n    追查嫌疑犯的偵查推理類遊戲穿梭展廳解謎任務首度加入戶外園區解謎關卡。\r\n\r\n    全新解謎任務\r\n    (含6個關卡與審訊嫌疑犯任務）暗藏玄機、樣式各異的謎題道具，帶你穿梭常設展廳與戶外園區，一邊解謎一邊認識精彩藏品。\r\n\r\n    遊戲盒帶入展廳即可開始玩！\r\n不需另外購買門票，不需下載APP，手機連上系統即可進入故事情節開啟挑戰。\r\n\r\n    合作、競賽都行，越多人玩越有趣！\r\n一隊以3-6人為限，沒有場次限制、不需工作人員，想玩就出發！不限遊戲時間，玩到破關為止。', '奇美博物館', '臺南市仁德區文華路二段66號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺南市奇美博物館', 22.94130931, 120.2418788, '費用+1980', 'https://www.chimeimuseum.org/event/62b964cb3ff31', '[]') ON DUPLICATE KEY UPDATE `activity_name`='穹頂計畫III 末日慶典', `description`='    在上次盜竊藏品功虧一簣後，隱藏版的第七位成員奧德修斯再次對六奇士提出挑戰。他將過去盜竊的十二件希臘文物寄送至奇美博物館，同時宣稱將啟動偉大的「末日慶典」計畫，讓世界陷入狂喜之中。身為六奇士的你們，手上的線索只有一張奧德修斯掉落的照片，以及四位沒有不在場證明的嫌疑人。\r\n你們的任務是要抓到奧德修斯，查清「末日慶典」的真面目，並阻止計畫啟動。\r\n\r\n    追查嫌疑犯的偵查推理類遊戲穿梭展廳解謎任務首度加入戶外園區解謎關卡。\r\n\r\n    全新解謎任務\r\n    (含6個關卡與審訊嫌疑犯任務）暗藏玄機、樣式各異的謎題道具，帶你穿梭常設展廳與戶外園區，一邊解謎一邊認識精彩藏品。\r\n\r\n    遊戲盒帶入展廳即可開始玩！\r\n不需另外購買門票，不需下載APP，手機連上系統即可進入故事情節開啟挑戰。\r\n\r\n    合作、競賽都行，越多人玩越有趣！\r\n一隊以3-6人為限，沒有場次限制、不需工作人員，想玩就出發！不限遊戲時間，玩到破關為止。', `organizer`='奇美博物館', `address`='臺南市仁德區文華路二段66號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺南市奇美博物館', `latitude`=22.94130931, `longitude`=120.2418788, `ticket_price`='費用+1980', `source_url`='https://www.chimeimuseum.org/event/62b964cb3ff31', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678dbbf307f3e7d36c5308c3', 'VIVA LA VIDA - 生命禮讚-親愛的我就在你身邊', '《 VIVA LA VIDA - 生命禮讚》- 親愛的我就在你身邊\r\n\r\n《VIVA LA VIDA-生命禮讚》是一場對生命的藝術探索,藝術家林純如運用多重材質,創作出一系列豐富奇異又獨特的生命力作品。這些形態未曾存在於現實世界中,它們既像新生的生物,又富有戲劇感,突破了現實與想像的邊界,同時也反映體現了生命的脆弱與堅韌,更對文明進程和人類存在的意義進行了深刻的反思。\r\n獨特的創作語言,將生命的多樣性、變異性與無常性呈現在觀眾面前。\r\n\r\n生命並非單一的存在,而是多樣且充滿糾結的。無論是從生命演化還是從人類文明發展的角度來看,她的作品表達了對生命循環、再生以及生命本質的無限憧憬,同時也刻畫時間流轉、生命無常以及日常生活中尋找光芒的渴望。\r\n\r\n展覽日期｜2025.02.15(SAT.) - 2025.04.26(SAT.)\r\n展覽地點｜THE 201 ART 順天建築 • 文化 • 藝術中心\r\n展覽地址｜臺中市西屯區文心路二段201號B2F\r\n營業時間｜週二至週六 10:00 - 17:30\r\n-\r\n開幕茶會｜2025.02.15 (SAT) 15:00\r\n展覽座談｜2025.02.15 (SAT) 15:00\r\n報名連結｜https://reurl.cc/V07ZdQ\r\n主辦單位｜THE 201 ART 順天建築 • 文化 • 藝術中心\r\n', 'THE 201 ART 順天建築•文化•藝術中心', '臺中市西屯區文心路二段201號B2F', '2025-02-15 00:00:00', '2025-04-26 00:00:00', 'THE 201 ART 順天建築 • 文化 • 藝術中心', 24.18308895, 120.6270131, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='VIVA LA VIDA - 生命禮讚-親愛的我就在你身邊', `description`='《 VIVA LA VIDA - 生命禮讚》- 親愛的我就在你身邊\r\n\r\n《VIVA LA VIDA-生命禮讚》是一場對生命的藝術探索,藝術家林純如運用多重材質,創作出一系列豐富奇異又獨特的生命力作品。這些形態未曾存在於現實世界中,它們既像新生的生物,又富有戲劇感,突破了現實與想像的邊界,同時也反映體現了生命的脆弱與堅韌,更對文明進程和人類存在的意義進行了深刻的反思。\r\n獨特的創作語言,將生命的多樣性、變異性與無常性呈現在觀眾面前。\r\n\r\n生命並非單一的存在,而是多樣且充滿糾結的。無論是從生命演化還是從人類文明發展的角度來看,她的作品表達了對生命循環、再生以及生命本質的無限憧憬,同時也刻畫時間流轉、生命無常以及日常生活中尋找光芒的渴望。\r\n\r\n展覽日期｜2025.02.15(SAT.) - 2025.04.26(SAT.)\r\n展覽地點｜THE 201 ART 順天建築 • 文化 • 藝術中心\r\n展覽地址｜臺中市西屯區文心路二段201號B2F\r\n營業時間｜週二至週六 10:00 - 17:30\r\n-\r\n開幕茶會｜2025.02.15 (SAT) 15:00\r\n展覽座談｜2025.02.15 (SAT) 15:00\r\n報名連結｜https://reurl.cc/V07ZdQ\r\n主辦單位｜THE 201 ART 順天建築 • 文化 • 藝術中心\r\n', `organizer`='THE 201 ART 順天建築•文化•藝術中心', `address`='臺中市西屯區文心路二段201號B2F', `start_date`='2025-02-15 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='THE 201 ART 順天建築 • 文化 • 藝術中心', `latitude`=24.18308895, `longitude`=120.6270131, `ticket