INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec76d26b32458d43637fe', '一圜復始—鈔幣特展', '      國立歷史博物館擁有豐富的通貨收藏，包括先秦到現代的各式銅、銀幣、銀兩等。而中央銀行及所屬中央印製廠、中央造幣廠等(以下簡稱央行)，不但承擔印鑄國幣的重要使命，亦收藏自民國以來的鈔幣，以及其製作流程的豐富史料。本館與央行曾多次合作，展出包括「錢世金生」特展(2019年)，與前(2023)年於「中央銀行券幣數位博物館」展出「錢塵往事」等展覽。本次適逢新年將至，特別匯集雙方之藏品精華，舉辦鈔幣特展。\n\n      我國發行的金屬幣，均為圓形。究其起源，最早是由戰國時代的秦國開始使用「圜錢」，而傳統錢幣中有方孔，亦有對應「天圓地方」的意義，故「圜」字於歷史與金融上，均有重大的意義。\n\n      鈔幣在歷史研究上，擔任極重要的角色，因為鈔幣不僅是大眾日常交易的重要媒介，也承載著鈔票印製與錢幣鑄造當時，人們對自身歷史、文化、經濟、政治甚至是美感的觀點。\n\n      自宋朝開始常規鑄造「年號錢」讓錢幣帶有時間的印記，民國時期雖然已不再有帝王紀年，但年號的概念仍以「民國OO年」的形式保留下來。而使用民國紀元同時，於民間使用了數千年的干支紀年，也簡化成更親切的符號：每十二年為一輪的生肖，深入我們生活各層面。而採用當值生肖發行紀念套幣，是中央銀行開春的重要業務。\n\n      陰、陽曆和諧並行，各司其職的時間觀念，直至今日仍存於我們生活的各層面，也反映到現行流通的鈔幣上。因此，在本次特展中，我們結合了「生肖紀年的習俗」與「綿延的歷史傳承」這兩條展示線，配合新年的喜慶氣氛，透過展覽來體現；希望透過具有重要歷史意義的鈔幣，以及包括生肖主題在內，各種具有吉祥寓意的套幣與繪畫，讓觀眾能藉機體會隱含在鈔幣背後的文化意涵、工藝美感與歷史傳承。\n\n     因開展後便逢新年假期，本展也隨票提供了具有喜氣的吉祥卡片供民眾親手壓印，央行也提供了小禮物及精美的卡片，於年假期間贈送，祝願大家新年平安幸福，財源滾滾。\n\n ', '國立歷史博物館', '100  臺北市中正區南海路49號', '2025-01-23 00:00:00', '2025-04-06 00:00:00', '國立歷史博物館5樓', 25.03240487, 121.5198839, '無資料', 'https://event.culture.tw/mocweb/reg/NMH/Detail.init.ctr?actId=50027', '[]') ON DUPLICATE KEY UPDATE `activity_name`='一圜復始—鈔幣特展', `description`='      國立歷史博物館擁有豐富的通貨收藏，包括先秦到現代的各式銅、銀幣、銀兩等。而中央銀行及所屬中央印製廠、中央造幣廠等(以下簡稱央行)，不但承擔印鑄國幣的重要使命，亦收藏自民國以來的鈔幣，以及其製作流程的豐富史料。本館與央行曾多次合作，展出包括「錢世金生」特展(2019年)，與前(2023)年於「中央銀行券幣數位博物館」展出「錢塵往事」等展覽。本次適逢新年將至，特別匯集雙方之藏品精華，舉辦鈔幣特展。\n\n      我國發行的金屬幣，均為圓形。究其起源，最早是由戰國時代的秦國開始使用「圜錢」，而傳統錢幣中有方孔，亦有對應「天圓地方」的意義，故「圜」字於歷史與金融上，均有重大的意義。\n\n      鈔幣在歷史研究上，擔任極重要的角色，因為鈔幣不僅是大眾日常交易的重要媒介，也承載著鈔票印製與錢幣鑄造當時，人們對自身歷史、文化、經濟、政治甚至是美感的觀點。\n\n      自宋朝開始常規鑄造「年號錢」讓錢幣帶有時間的印記，民國時期雖然已不再有帝王紀年，但年號的概念仍以「民國OO年」的形式保留下來。而使用民國紀元同時，於民間使用了數千年的干支紀年，也簡化成更親切的符號：每十二年為一輪的生肖，深入我們生活各層面。而採用當值生肖發行紀念套幣，是中央銀行開春的重要業務。\n\n      陰、陽曆和諧並行，各司其職的時間觀念，直至今日仍存於我們生活的各層面，也反映到現行流通的鈔幣上。因此，在本次特展中，我們結合了「生肖紀年的習俗」與「綿延的歷史傳承」這兩條展示線，配合新年的喜慶氣氛，透過展覽來體現；希望透過具有重要歷史意義的鈔幣，以及包括生肖主題在內，各種具有吉祥寓意的套幣與繪畫，讓觀眾能藉機體會隱含在鈔幣背後的文化意涵、工藝美感與歷史傳承。\n\n     因開展後便逢新年假期，本展也隨票提供了具有喜氣的吉祥卡片供民眾親手壓印，央行也提供了小禮物及精美的卡片，於年假期間贈送，祝願大家新年平安幸福，財源滾滾。\n\n ', `organizer`='國立歷史博物館', `address`='100  臺北市中正區南海路49號', `start_date`='2025-01-23 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='國立歷史博物館5樓', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMH/Detail.init.ctr?actId=50027', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82526b32458d4363800', '潭聯藝廊〈蛇來運轉〉立體浮雕畫展', '老師的作品不同於平面創作，它是躍然紙上的，透過巧思與巧手，經由切割\\造型\\黏貼\\上亮光漆\\裱框\\等程序，將原本平面的圖畫變成一幅獨一無二、具有生命力的立體創作！️\r\n現場依風格分為異國風情、春節喜慶、西式及中式等展區，歡迎大家來潭子區公所潭聯藝廊參觀～一起踏入立體浮雕畫的世界！', '臺中市潭子區公所', '臺中市潭子區', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '潭子區（臺中市）=', 24.21171121, 120.710997, '無資料', 'https://www.tanzi.taichung.gov.tw/3576907/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='潭聯藝廊〈蛇來運轉〉立體浮雕畫展', `description`='老師的作品不同於平面創作，它是躍然紙上的，透過巧思與巧手，經由切割\\造型\\黏貼\\上亮光漆\\裱框\\等程序，將原本平面的圖畫變成一幅獨一無二、具有生命力的立體創作！️\r\n現場依風格分為異國風情、春節喜慶、西式及中式等展區，歡迎大家來潭子區公所潭聯藝廊參觀～一起踏入立體浮雕畫的世界！', `organizer`='臺中市潭子區公所', `address`='臺中市潭子區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='潭子區（臺中市）=', `latitude`=24.21171121, `longitude`=120.710997, `ticket_price`='無資料', `source_url`='https://www.tanzi.taichung.gov.tw/3576907/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82526b32458d4363802', '莊賜祿老師書法展', '書法為莊賜祿老師創作的核心，以傳統的篆隸為憑藉、融入含蓄、穩健而流暢的線條書寫，莊老師的書法作品包括:古典的書寫、英文書法、中英混成之書作，另外還有以金、銀混合墨汁所做的特殊效果，以及書與畫相融於作品當中等，傳統與實驗之表現形式並重，歡迎來欣賞!', '臺中市西區戶政事務所', '臺中市西區', '2025-01-02 00:00:00', '2025-02-28 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://www.hwest.taichung.gov.tw/3576190/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='莊賜祿老師書法展', `description`='書法為莊賜祿老師創作的核心，以傳統的篆隸為憑藉、融入含蓄、穩健而流暢的線條書寫，莊老師的書法作品包括:古典的書寫、英文書法、中英混成之書作，另外還有以金、銀混合墨汁所做的特殊效果，以及書與畫相融於作品當中等，傳統與實驗之表現形式並重，歡迎來欣賞!', `organizer`='臺中市西區戶政事務所', `address`='臺中市西區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.hwest.taichung.gov.tw/3576190/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82626b32458d4363807', '筆走龍蛇—2025曾淑貞書法年畫展', '==豐原戶政藝文展==\r\n喜迎農曆新年，本所藝文空間展出曾淑貞女士的書法年畫作品，歡迎市民朋友前來參觀，領略文字裡的動靜之美，展出資訊如下：\r\n展覽名稱：筆走龍蛇—2025曾淑貞書法年畫展\r\n展覽期間：2025.1.20～2025.2.27\r\n創作者：曾淑貞女士', '臺中市豐原區戶政事務所', '臺中市豐原區', '2025-01-20 00:00:00', '2025-02-27 00:00:00', '豐原區（臺中市）=', 24.24990298, 120.7375715, '無資料', 'https://www.hfengyuan.taichung.gov.tw/3583575/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='筆走龍蛇—2025曾淑貞書法年畫展', `description`='==豐原戶政藝文展==\r\n喜迎農曆新年，本所藝文空間展出曾淑貞女士的書法年畫作品，歡迎市民朋友前來參觀，領略文字裡的動靜之美，展出資訊如下：\r\n展覽名稱：筆走龍蛇—2025曾淑貞書法年畫展\r\n展覽期間：2025.1.20～2025.2.27\r\n創作者：曾淑貞女士', `organizer`='臺中市豐原區戶政事務所', `address`='臺中市豐原區', `start_date`='2025-01-20 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='豐原區（臺中市）=', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.hfengyuan.taichung.gov.tw/3583575/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82626b32458d436380a', '臺中市立圖書館東勢分館-2月主題書展', '【種出幸福:花草與你】書展\r\n展出館藏特色代表「園藝」相關書籍，推廣綠植栽與閱讀生活。\r\n【走自己的路:地理旅遊】書展\r\n精選地理旅遊相關書籍，\r\n【小小愛書人】書展\r\n配合國中小生寒假展出適合該年齡層的書籍。\r\n【每月新到圖書】書展\r\n每月新到書籍展覽', '臺中市立圖書館東勢分館', '臺中市東勢區豐勢路518號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺中市立圖書館東勢分館', 24.24952637, 120.8401401, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館東勢分館-2月主題書展', `description`='【種出幸福:花草與你】書展\r\n展出館藏特色代表「園藝」相關書籍，推廣綠植栽與閱讀生活。\r\n【走自己的路:地理旅遊】書展\r\n精選地理旅遊相關書籍，\r\n【小小愛書人】書展\r\n配合國中小生寒假展出適合該年齡層的書籍。\r\n【每月新到圖書】書展\r\n每月新到書籍展覽', `organizer`='臺中市立圖書館東勢分館', `address`='臺中市東勢區豐勢路518號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市立圖書館東勢分館', `latitude`=24.24952637, `longitude`=120.8401401, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82726b32458d436380b', '無資料', '本次參展的師生作品五十餘件，有臨寫晉唐法帖碑銘，亦有取法宋代行書的筆調，並融匯個人情性，透過殊異線條性質，呈現各自的筆情墨趣。此次展出不論是研墨濡筆多年的學員，或是近期才參與研習的初學者，大家均以薰染墨香為樂，並藉此由展出與同好分享書法之美。', '臺中市大墩文化中心', '臺中市西區英才路600號', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='本次參展的師生作品五十餘件，有臨寫晉唐法帖碑銘，亦有取法宋代行書的筆調，並融匯個人情性，透過殊異線條性質，呈現各自的筆情墨趣。此次展出不論是研墨濡筆多年的學員，或是近期才參與研習的初學者，大家均以薰染墨香為樂，並藉此由展出與同好分享書法之美。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82726b32458d4363810', '《50·贏心》徐珈惠油畫個展', '《 50 · 贏心 》《Heartful Victory》年入50歲，突破自我內心禁錮，詮釋心靈的療癒與蛻變，溫暖而具正能量的勝利 !\r\n 贏心 · 迎新。將禪學修行帶入創作，不是精彩賦予的感動，是源點躍遷不斷地流竄身脈，疊構多重意識空間，透過藝術治癒來形塑自我，解構生命殘跡，以抽象畫形式來詮釋對於物質與精神世界的永恆詰問與持續表達。在油畫作品中，向光心釋，厚度彩顏竟為一條遙遠的生命勁力，光灑自然的和諧力。\r\n《 50 · 贏心 》光筆觸流，溫暖且具有力量感，直接體現贏過自己的主題，凱旋的心，艷入當下，平面畫布轉譯「勝利」與「蛻變」的心鑰之鏡。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-02-08 00:00:00', '2025-02-26 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000861', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《50·贏心》徐珈惠油畫個展', `description`='《 50 · 贏心 》《Heartful Victory》年入50歲，突破自我內心禁錮，詮釋心靈的療癒與蛻變，溫暖而具正能量的勝利 !\r\n 贏心 · 迎新。將禪學修行帶入創作，不是精彩賦予的感動，是源點躍遷不斷地流竄身脈，疊構多重意識空間，透過藝術治癒來形塑自我，解構生命殘跡，以抽象畫形式來詮釋對於物質與精神世界的永恆詰問與持續表達。在油畫作品中，向光心釋，厚度彩顏竟為一條遙遠的生命勁力，光灑自然的和諧力。\r\n《 50 · 贏心 》光筆觸流，溫暖且具有力量感，直接體現贏過自己的主題，凱旋的心，艷入當下，平面畫布轉譯「勝利」與「蛻變」的心鑰之鏡。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-02-08 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000861', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82726b32458d4363811', '奧義‧大哉問－李杉峯創作展', '1950年出生的藝術家李杉峯，臺灣師範大學美術系畢業後投身教育工作，於2010年退休，至今仍持續為藝術教育貢獻心力。此外，李老師還參與多次藝術大展的評審工作，對於中部地區的藝術風貌和創作氛圍，亦有著不可忽視的影響力。\r\n李杉峯老師的創作，深受其人生哲學和學術背景的影響。他將「心」的領域轉向「靜觀」與「內化」，在這樣的心境中，宇宙、時空、生命、心識、宗教學、神祕學等課題逐漸浮現。初期他以「異次元」為主題，探索這些深邃的命題，並以「奧義」一詞來統括其創作的核心思想。\r\n李老師的創作，也深受英國著名理論物理學家史蒂芬·霍金的影響。霍金在尋求宇宙奧秘的過程中，始終堅持提問本身就是一種價值，而這些疑問與思考激發了人類智慧的不斷拓展。李老師同樣認為，對於未知的探索是一條永無止境的道路，因此他決定以「奧義·大哉問」作為此次展覽的主題，邀請觀者一同踏上這場關於宇宙與生命奧秘的探索之旅。\r\n李老師的作品中運用了多種複合媒材，將生活中各種素材轉化為藝術的語言，從木材到回收紙盒等，都成為他表達思想與情感的載體。在形式上呈現出繪畫與設計的交織，透過複合媒材、多元技法的摻揉，形成獨特的藝術風格。特別是自2011年起，他運用對稱構圖，強調中軸線，並在色彩上帶有濃厚的東方感，畫面裝飾性增強、持重而不輕狂，以視覺語言向觀者傳遞著無盡的哲理與情感。\r\n藝術之所以能引起共鳴，是因為它觸及人類心靈深處的悸動。李杉峯老師的創作，讓我們重新思考宇宙與生命的意義，邀請每一位觀者，與他一同發出心中的「大哉問」，深入心靈深處對話與探索。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-02-15 00:00:00', '2025-03-05 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000862', '[]') ON DUPLICATE KEY UPDATE `activity_name`='奧義‧大哉問－李杉峯創作展', `description`='1950年出生的藝術家李杉峯，臺灣師範大學美術系畢業後投身教育工作，於2010年退休，至今仍持續為藝術教育貢獻心力。此外，李老師還參與多次藝術大展的評審工作，對於中部地區的藝術風貌和創作氛圍，亦有著不可忽視的影響力。\r\n李杉峯老師的創作，深受其人生哲學和學術背景的影響。他將「心」的領域轉向「靜觀」與「內化」，在這樣的心境中，宇宙、時空、生命、心識、宗教學、神祕學等課題逐漸浮現。初期他以「異次元」為主題，探索這些深邃的命題，並以「奧義」一詞來統括其創作的核心思想。\r\n李老師的創作，也深受英國著名理論物理學家史蒂芬·霍金的影響。霍金在尋求宇宙奧秘的過程中，始終堅持提問本身就是一種價值，而這些疑問與思考激發了人類智慧的不斷拓展。李老師同樣認為，對於未知的探索是一條永無止境的道路，因此他決定以「奧義·大哉問」作為此次展覽的主題，邀請觀者一同踏上這場關於宇宙與生命奧秘的探索之旅。\r\n李老師的作品中運用了多種複合媒材，將生活中各種素材轉化為藝術的語言，從木材到回收紙盒等，都成為他表達思想與情感的載體。在形式上呈現出繪畫與設計的交織，透過複合媒材、多元技法的摻揉，形成獨特的藝術風格。特別是自2011年起，他運用對稱構圖，強調中軸線，並在色彩上帶有濃厚的東方感，畫面裝飾性增強、持重而不輕狂，以視覺語言向觀者傳遞著無盡的哲理與情感。\r\n藝術之所以能引起共鳴，是因為它觸及人類心靈深處的悸動。李杉峯老師的創作，讓我們重新思考宇宙與生命的意義，邀請每一位觀者，與他一同發出心中的「大哉問」，深入心靈深處對話與探索。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-02-15 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000862', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82726b32458d4363813', '《大叔的異想世界》黃國忠個展', '《大叔的異想世界》是一個關於探索、挑戰與融合的藝術實驗。它不僅是對傳統藝術形式的反思，更是對當代藝術的創新性嘗試。希望觀眾能在其中找到屬於自己的共鳴，感受每一件水彩、油畫作品背後無限的創意與想像空間。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-02-15 00:00:00', '2025-03-05 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000863', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《大叔的異想世界》黃國忠個展', `description`='《大叔的異想世界》是一個關於探索、挑戰與融合的藝術實驗。它不僅是對傳統藝術形式的反思，更是對當代藝術的創新性嘗試。希望觀眾能在其中找到屬於自己的共鳴，感受每一件水彩、油畫作品背後無限的創意與想像空間。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-02-15 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000863', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82726b32458d4363814', '旅行的意義~尤志瑛個展', '尤志瑛的作品多以灰色和馬卡龍色調為主，這些色彩呈現出純粹、寧靜或繽紛的氛圍，此次展出的壓克力繪畫，呈現她在藝術的持續探索與創新，透過輕快、活潑的色塊節奏，讓觀眾在欣賞中感受到輕鬆愉悅的心情。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-02-15 00:00:00', '2025-03-05 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000864', '[]') ON DUPLICATE KEY UPDATE `activity_name`='旅行的意義~尤志瑛個展', `description`='尤志瑛的作品多以灰色和馬卡龍色調為主，這些色彩呈現出純粹、寧靜或繽紛的氛圍，此次展出的壓克力繪畫，呈現她在藝術的持續探索與創新，透過輕快、活潑的色塊節奏，讓觀眾在欣賞中感受到輕鬆愉悅的心情。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-02-15 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000864', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82726b32458d4363815', '陶藝鑑賞－中道‧良倉系列/蕭巨昌陶研個展', '此次陶展是續承五年前在本中心，曾展出的茶器中流器的「流與斷」淺研個展；是一系列的實用陶藝人因工學介面研究心得的序進再發表。本展旨在實踐一個原創陶人對於藏茶器皿在實用美學上，對於「人」的人性化關照及體恤。藉新探成果既具象創物來表述良倉的精要三魂所在：1.高溫硬質燒結2.高密合度3.得宜的造形設計...等。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-02-15 00:00:00', '2025-03-05 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000865', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陶藝鑑賞－中道‧良倉系列/蕭巨昌陶研個展', `description`='此次陶展是續承五年前在本中心，曾展出的茶器中流器的「流與斷」淺研個展；是一系列的實用陶藝人因工學介面研究心得的序進再發表。本展旨在實踐一個原創陶人對於藏茶器皿在實用美學上，對於「人」的人性化關照及體恤。藉新探成果既具象創物來表述良倉的精要三魂所在：1.高溫硬質燒結2.高密合度3.得宜的造形設計...等。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-02-15 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000865', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82726b32458d4363816', '拓方印集三十二週年聯展', '集合中部地區愛好舞刀弄石之同好，以研究篆刻藝術、弘揚篆刻文化為宗旨。本會為推廣篆刻風氣及金石文化不遺餘力，歷年來在臺北、臺中、彰化及高雄縣市辦過十數場展覽及篆刻講座與現場刻印活動，始有今日之風貌。本次展出篆刻、書法及多媒材創作等作品，懇請各界先進賢達不吝賜教指正。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-02-15 00:00:00', '2025-03-05 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000866', '[]') ON DUPLICATE KEY UPDATE `activity_name`='拓方印集三十二週年聯展', `description`='集合中部地區愛好舞刀弄石之同好，以研究篆刻藝術、弘揚篆刻文化為宗旨。本會為推廣篆刻風氣及金石文化不遺餘力，歷年來在臺北、臺中、彰化及高雄縣市辦過十數場展覽及篆刻講座與現場刻印活動，始有今日之風貌。本次展出篆刻、書法及多媒材創作等作品，懇請各界先進賢達不吝賜教指正。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-02-15 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000866', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82726b32458d4363817', '2025臺中市美術教育學會會員創作展、臺日兒童繪畫交流暨臺中市學童繪畫比賽得獎作品展', '「臺中市美術教育學會」致力於推廣美術教育、提升美學涵養、促進國際美育交流，本次展出包含彩墨、油彩、水彩、書法、雕塑等多元作品，展現創新風貌，再加上本會協辦之「臺日兒童繪畫交流暨臺中市學童繪畫比賽得獎作品展」，期望透過展覽提升審美力、彼此觀摩、交流與學習，傳遞為建構美術教育努力之共同信念。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-02-22 00:00:00', '2025-03-05 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000867', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺中市美術教育學會會員創作展、臺日兒童繪畫交流暨臺中市學童繪畫比賽得獎作品展', `description`='「臺中市美術教育學會」致力於推廣美術教育、提升美學涵養、促進國際美育交流，本次展出包含彩墨、油彩、水彩、書法、雕塑等多元作品，展現創新風貌，再加上本會協辦之「臺日兒童繪畫交流暨臺中市學童繪畫比賽得獎作品展」，期望透過展覽提升審美力、彼此觀摩、交流與學習，傳遞為建構美術教育努力之共同信念。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000867', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82726b32458d4363818', '百聞不如藝見 臺中市立至善國中美術班畢業成果展', '25位至善藝術小將，創作了百餘件作品，包含了水彩、水墨、書法、電腦繪圖、複合媒材……等類型作品，表達對自身、對環境以及對社會文化的回應。在藝術的世界裡，我們不懼環境的變化與動盪，我們擁有豐沛的能量，創意又帶著浪漫。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-02-22 00:00:00', '2025-03-05 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000868', '[]') ON DUPLICATE KEY UPDATE `activity_name`='百聞不如藝見 臺中市立至善國中美術班畢業成果展', `description`='25位至善藝術小將，創作了百餘件作品，包含了水彩、水墨、書法、電腦繪圖、複合媒材……等類型作品，表達對自身、對環境以及對社會文化的回應。在藝術的世界裡，我們不懼環境的變化與動盪，我們擁有豐沛的能量，創意又帶著浪漫。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000868', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82a26b32458d436381a', '優化館藏主題書展', '本活動展示新購置兒童圖書3仟7佰餘本，圖書種類多元豐富，歡迎家長帶小朋友至本館兒童室閱讀，學習新知，感受閱讀之樂趣。', '高雄市立圖書館總館', '高雄市橋頭區24鄰隆豐路7號', '2025-01-02 00:00:00', '2025-08-31 00:00:00', '高雄市立圖書館橋頭分館', 22.758444, 120.3060122, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='優化館藏主題書展', `description`='本活動展示新購置兒童圖書3仟7佰餘本，圖書種類多元豐富，歡迎家長帶小朋友至本館兒童室閱讀，學習新知，感受閱讀之樂趣。', `organizer`='高雄市立圖書館總館', `address`='高雄市橋頭區24鄰隆豐路7號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='高雄市立圖書館橋頭分館', `latitude`=22.758444, `longitude`=120.3060122, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82a26b32458d436381c', '臺中市立圖書館西區分館【童眼看世界系列展】原來視這樣：奇幻視界VS.我眼中的你 攝影展', '長期義務進入部落服務的「臺灣兒童攝影教育推行會」，在113學年度以「奇幻視界」、「我眼中的你」為主題，在南投縣仁愛鄉都達國小、德鹿谷國小、法治國小、萬豐國小與南投縣信義鄉豐丘國小五所部落國小進行攝影教學，小朋友們各自用照相機展現眼中的世界，從1/2(四)到2/27(四)在西區分館精彩呈現。\r\n此次「奇幻視界」單元，有許多令人驚奇的展現。帶給讀者不一樣的驚喜。「我眼中的你」單元，鼓勵學童細想自己心中最想傳達的人事物景，並在部落周遭探詢生活裡的傳統服飾、圖騰、器具、文化儀式或生活形態，傳遞對文化的情感。藉由原住民學童的眼界觀察及部落寫真，帶領觀眾一起走入原鄉人文。', '臺中市立圖書館西區分館', '臺中市西區精誠路256號', '2025-01-02 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館西區分館', 24.14944, 120.654959, '無資料', 'https://reurl.cc/EgYk4v', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館西區分館【童眼看世界系列展】原來視這樣：奇幻視界VS.我眼中的你 攝影展', `description`='長期義務進入部落服務的「臺灣兒童攝影教育推行會」，在113學年度以「奇幻視界」、「我眼中的你」為主題，在南投縣仁愛鄉都達國小、德鹿谷國小、法治國小、萬豐國小與南投縣信義鄉豐丘國小五所部落國小進行攝影教學，小朋友們各自用照相機展現眼中的世界，從1/2(四)到2/27(四)在西區分館精彩呈現。\r\n此次「奇幻視界」單元，有許多令人驚奇的展現。帶給讀者不一樣的驚喜。「我眼中的你」單元，鼓勵學童細想自己心中最想傳達的人事物景，並在部落周遭探詢生活裡的傳統服飾、圖騰、器具、文化儀式或生活形態，傳遞對文化的情感。藉由原住民學童的眼界觀察及部落寫真，帶領觀眾一起走入原鄉人文。', `organizer`='臺中市立圖書館西區分館', `address`='臺中市西區精誠路256號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館西區分館', `latitude`=24.14944, `longitude`=120.654959, `ticket_price`='無資料', `source_url`='https://reurl.cc/EgYk4v', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82c26b32458d4363822', '臺中市藝術亮點-趙介凡花語樹特展', '星漾商旅一中館 2025第一季藝術亮點開展了~\r\n「趙介凡花語樹」特展，展出精采的油畫作品，以自然風景、花草樹木為主題，描繪花和人一樣,都會遇到各種境遇,展現萬物生命的強韌與幸福！', '星漾商旅', '臺中市北區', '2025-01-25 00:00:00', '2025-03-31 00:00:00', '北區（臺中市）=', 24.15863985, 120.6809521, '無資料', 'https://www.facebook.com/photo/?fbid=1142074957927942&set=pcb.1142075191261252', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-趙介凡花語樹特展', `description`='星漾商旅一中館 2025第一季藝術亮點開展了~\r\n「趙介凡花語樹」特展，展出精采的油畫作品，以自然風景、花草樹木為主題，描繪花和人一樣,都會遇到各種境遇,展現萬物生命的強韌與幸福！', `organizer`='星漾商旅', `address`='臺中市北區', `start_date`='2025-01-25 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='北區（臺中市）=', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://www.facebook.com/photo/?fbid=1142074957927942&set=pcb.1142075191261252', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82c26b32458d4363825', '無資料', '巧虎、琪琪、妙妙、桃樂比受到邀請，參加一年一度的花神祭慶典，但重要的花神杖卻消失了。巧虎他們與玫瑰公主決定進入充滿魔法的秘密花園中，踏上尋找花神杖的冒險之旅！', '日商倍樂生股份有限公司台北分公司', '臺中市北區學士路98號', '臺中市中山堂', 24.15863985, 120.6809521, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='巧虎、琪琪、妙妙、桃樂比受到邀請，參加一年一度的花神祭慶典，但重要的花神杖卻消失了。巧虎他們與玫瑰公主決定進入充滿魔法的秘密花園中，踏上尋找花神杖的冒險之旅！', `organizer`='日商倍樂生股份有限公司台北分公司', `address`='臺中市北區學士路98號', `location`='臺中市中山堂', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82c26b32458d4363826', '綠光世界劇場《當妳轉身之後》', '一位教學一絲不苟、略顯不近人情的文學女教授，無意間發現自己罹患卵巢癌。生命的消逝迫使她褪下教授的光環，只能躺在病床上，毫無尊嚴地接受各種化療。當她發現主治醫生竟是自己以前的學生，更讓她尷尬不已。隨著生命旅程接近尾聲，她開始對人生和自我展開不同的反思與對話。', '綠光創藝股份有限公司', '臺中市北區學士路98號', '2025-03-01 00:00:00', '2025-03-02 00:00:00', '臺中市中山堂', 24.15863985, 120.6809521, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='綠光世界劇場《當妳轉身之後》', `description`='一位教學一絲不苟、略顯不近人情的文學女教授，無意間發現自己罹患卵巢癌。生命的消逝迫使她褪下教授的光環，只能躺在病床上，毫無尊嚴地接受各種化療。當她發現主治醫生竟是自己以前的學生，更讓她尷尬不已。隨著生命旅程接近尾聲，她開始對人生和自我展開不同的反思與對話。', `organizer`='綠光創藝股份有限公司', `address`='臺中市北區學士路98號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='臺中市中山堂', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82c26b32458d4363827', '果陀劇場《最後14堂星期二的課》暫別舞台最終巡迴', '劇中描述一位體育專欄作家畢業十六年後，在自己的許多理想中迷失了自我。偶然從電視上看見大學時期對他期望最大的教授竟罹患了無藥可醫的「肌萎縮性脊髓側索硬化症」（簡稱ALS）。師生二人久別重逢，不畏懼「死亡」的教授以自己的生命為活教材，把自己最真實的生命經驗教授給這位世故而冷漠、追求物質的學生，希望透過學生的記錄，把自己走過來的生命歷程、生死的領悟記錄下來，利用14個星期二的時間裡與學生展開了既幽默又觸動人心的生死對話。', '果陀劇場', '臺中市北區學士路98號', '2025-03-21 00:00:00', '2025-03-22 00:00:00', '臺中市中山堂', 24.15863985, 120.6809521, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='果陀劇場《最後14堂星期二的課》暫別舞台最終巡迴', `description`='劇中描述一位體育專欄作家畢業十六年後，在自己的許多理想中迷失了自我。偶然從電視上看見大學時期對他期望最大的教授竟罹患了無藥可醫的「肌萎縮性脊髓側索硬化症」（簡稱ALS）。師生二人久別重逢，不畏懼「死亡」的教授以自己的生命為活教材，把自己最真實的生命經驗教授給這位世故而冷漠、追求物質的學生，希望透過學生的記錄，把自己走過來的生命歷程、生死的領悟記錄下來，利用14個星期二的時間裡與學生展開了既幽默又觸動人心的生死對話。', `organizer`='果陀劇場', `address`='臺中市北區學士路98號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺中市中山堂', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82c26b32458d4363828', '國立臺灣體育運動大學舞蹈學系第26屆畢業巡迴公演', '國立臺灣體育運動大學舞蹈學系第26屆畢業生將以五支同學精彩的舞作呈現我們四年來的學習成果，並特別邀請三支大師作品，整場演出精彩可期。\r\n大師作品介紹\r\n《陣》:潘莉君老師、林柏宏老師於2022年創作，以廟會鼓舞陣頭熱鬧開場,入火才具有神性的虎爺為神明開道,鎮護廟宇驅除癘疫,慶典儀式祈福家戶平安。\r\n《皿》:特別邀請蘇家賢老師編排新作品，以現代舞結合大型道具的装置豐富舞台的空間。\r\n《Wings of Winter》:黃建彪老師於2018年創作，展現優雅與力量之美。\r\n學生編創作品\r\n《Coppelia選粹》《龍魂焰躍》《儷劒》\r\n《呼和·薩吾爾登》《流˙躰》\r\n《儷劒》是2024年飛舞獎銀牌得主\r\n《流˙躰》是2024年飛舞獎銀牌得主\r\n這八支舞作不僅展現了我們對不同舞蹈形式的探索,更凝聚了我們對舞蹈創作與表演的熱情與專注。期待與觀眾一同分享這場融合創意與努力的精彩演出!\r\n', '國立臺灣體育運動大學', '臺中市北區學士路98號', '2025-03-14 00:00:00', '2025-03-14 00:00:00', '臺中市中山堂', 24.15863985, 120.6809521, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國立臺灣體育運動大學舞蹈學系第26屆畢業巡迴公演', `description`='國立臺灣體育運動大學舞蹈學系第26屆畢業生將以五支同學精彩的舞作呈現我們四年來的學習成果，並特別邀請三支大師作品，整場演出精彩可期。\r\n大師作品介紹\r\n《陣》:潘莉君老師、林柏宏老師於2022年創作，以廟會鼓舞陣頭熱鬧開場,入火才具有神性的虎爺為神明開道,鎮護廟宇驅除癘疫,慶典儀式祈福家戶平安。\r\n《皿》:特別邀請蘇家賢老師編排新作品，以現代舞結合大型道具的装置豐富舞台的空間。\r\n《Wings of Winter》:黃建彪老師於2018年創作，展現優雅與力量之美。\r\n學生編創作品\r\n《Coppelia選粹》《龍魂焰躍》《儷劒》\r\n《呼和·薩吾爾登》《流˙躰》\r\n《儷劒》是2024年飛舞獎銀牌得主\r\n《流˙躰》是2024年飛舞獎銀牌得主\r\n這八支舞作不僅展現了我們對不同舞蹈形式的探索,更凝聚了我們對舞蹈創作與表演的熱情與專注。期待與觀眾一同分享這場融合創意與努力的精彩演出!\r\n', `organizer`='國立臺灣體育運動大學', `address`='臺中市北區學士路98號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-14 00:00:00', `location`='臺中市中山堂', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82c26b32458d4363829', '一起來唱歌吧6', '　　一起來唱歌吧演出活動已成功步入第六年，秉持著創立宗旨，以愛聚合，因愛而唱，愛唱歌手合唱團將與三個子團繼續聯手帶來動人的合唱歌曲，歡迎闔家大小一同索票來參與我們的演出！\r\n　　愛唱歌手合唱團2013年成立於台中，成員來自各界音樂愛好者，包括老師、學者、設計師、上班族、科技業、醫護界和演藝人員等，各行各業混齡組合的多樣性，展現了立團宗旨的愛與包容，也是一種跨世代的大融合。本團藝術總監暨指揮為聲樂家林慧芬老師。\r\n　　愛唱小歌手在溫馨活潑的氣氛中學習健康正確的唱歌方式及基礎樂理，同時也訓練了音感、節奏感和與他人共同合作的能力，使小歌手擁有極佳的音色表現。現由指揮蔡宜珊老師指導。\r\n　　愛唱悠活合唱團廣泛招收各界人士，讓過去沒有合唱基礎或已經荒廢數十年合唱經驗的成年人，再次重新拾起對歌唱的熱忱和樂趣。\r\n 　　包酷哼歌手是取自德文年輪蛋糕之意，雖然年齡有點像年輪一樣密密麻麻，但內在還是像蛋糕一樣，鬆軟香甜，且還有多種口味變化，代表一群有年紀卻又保持赤子之心的人，雖然可能屆齡退休，但仍然可以締造另一個人生舞臺，重新展現自我。\r\n    愛唱歌手合唱團期盼用歌聲療癒人心，同時在推廣合唱藝術時亦不遺餘力，能在眾口齊聲的歡唱中，營造和諧優美的社會氛圍。\r\n', '愛唱歌手合唱團', '臺中市北區學士路98號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '臺中市中山堂', 24.15863985, 120.6809521, '無資料', 'https://hall.culture.taichung.gov.tw/HallFrontend/WatchShow/ShowInfoDetail?AADID=CCD0001114', '[]') ON DUPLICATE KEY UPDATE `activity_name`='一起來唱歌吧6', `description`='　　一起來唱歌吧演出活動已成功步入第六年，秉持著創立宗旨，以愛聚合，因愛而唱，愛唱歌手合唱團將與三個子團繼續聯手帶來動人的合唱歌曲，歡迎闔家大小一同索票來參與我們的演出！\r\n　　愛唱歌手合唱團2013年成立於台中，成員來自各界音樂愛好者，包括老師、學者、設計師、上班族、科技業、醫護界和演藝人員等，各行各業混齡組合的多樣性，展現了立團宗旨的愛與包容，也是一種跨世代的大融合。本團藝術總監暨指揮為聲樂家林慧芬老師。\r\n　　愛唱小歌手在溫馨活潑的氣氛中學習健康正確的唱歌方式及基礎樂理，同時也訓練了音感、節奏感和與他人共同合作的能力，使小歌手擁有極佳的音色表現。現由指揮蔡宜珊老師指導。\r\n　　愛唱悠活合唱團廣泛招收各界人士，讓過去沒有合唱基礎或已經荒廢數十年合唱經驗的成年人，再次重新拾起對歌唱的熱忱和樂趣。\r\n 　　包酷哼歌手是取自德文年輪蛋糕之意，雖然年齡有點像年輪一樣密密麻麻，但內在還是像蛋糕一樣，鬆軟香甜，且還有多種口味變化，代表一群有年紀卻又保持赤子之心的人，雖然可能屆齡退休，但仍然可以締造另一個人生舞臺，重新展現自我。\r\n    愛唱歌手合唱團期盼用歌聲療癒人心，同時在推廣合唱藝術時亦不遺餘力，能在眾口齊聲的歡唱中，營造和諧優美的社會氛圍。\r\n', `organizer`='愛唱歌手合唱團', `address`='臺中市北區學士路98號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市中山堂', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://hall.culture.taichung.gov.tw/HallFrontend/WatchShow/ShowInfoDetail?AADID=CCD0001114', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82e26b32458d436382d', '臺中市藝術亮點-臺灣當代名家木雕展售會   ', '本次展覽特別邀請木雕藝術典藏家們合作，展示各式木頭雕塑作品，包含人像、自然萬物等雕刻主題，現場也同步藝術藏品展售，讓民眾能感受並收藏木雕之美！', '臺中市猿緣園藝術館', '臺中市南區', '2025-01-03 00:00:00', '2025-06-26 00:00:00', '南區（臺中市）=', 24.12114107, 120.6646178, '無資料', 'https://www.artspots-taichung.com.tw/tw/news-detail/316?kind=11&root=8&page=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-臺灣當代名家木雕展售會   ', `description`='本次展覽特別邀請木雕藝術典藏家們合作，展示各式木頭雕塑作品，包含人像、自然萬物等雕刻主題，現場也同步藝術藏品展售，讓民眾能感受並收藏木雕之美！', `organizer`='臺中市猿緣園藝術館', `address`='臺中市南區', `start_date`='2025-01-03 00:00:00', `end_date`='2025-06-26 00:00:00', `location`='南區（臺中市）=', `latitude`=24.12114107, `longitude`=120.6646178, `ticket_price`='無資料', `source_url`='https://www.artspots-taichung.com.tw/tw/news-detail/316?kind=11&root=8&page=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82e26b32458d436382e', '臺中市藝術亮點-《陶金丶陶銀-杯杯好運》高志誠半百丹元歲月創作展', '半百是歲月與創作中繼點，是起點、是華麗轉身，也是返璞歸真的蛻變。\r\n展覽邀請藝術家高志誠展示工藝作品，以生活器具為主題，結合銀器與傳統工藝手法，創作各式陶金丶陶銀-杯杯好運系列作品。', '74藝術中心', '臺中市北屯區環中東路二段597號', '2025-02-04 00:00:00', '2025-04-06 00:00:00', '74藝術中心', 24.18400298, 120.7362319, '無資料', 'https://www.artspots-taichung.com.tw/tw/news-detail/311?kind=11&root=8&page=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-《陶金丶陶銀-杯杯好運》高志誠半百丹元歲月創作展', `description`='半百是歲月與創作中繼點，是起點、是華麗轉身，也是返璞歸真的蛻變。\r\n展覽邀請藝術家高志誠展示工藝作品，以生活器具為主題，結合銀器與傳統工藝手法，創作各式陶金丶陶銀-杯杯好運系列作品。', `organizer`='74藝術中心', `address`='臺中市北屯區環中東路二段597號', `start_date`='2025-02-04 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='74藝術中心', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://www.artspots-taichung.com.tw/tw/news-detail/311?kind=11&root=8&page=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82e26b32458d436382f', '臺中市藝術亮點-全心自由視：林益全KEVIN攝影展', '每當旅遊結束，都是心的昇華我們眼中所見的世界，\r\n也總在折射當時的自己。\r\n展覽展示攝影家林益全KEVIN精采攝影作品，這些照片，紀錄了異國真實面貌，旅途中有不完美，也有屏息的完美，都讓回憶，更顯深邃。\r\n', '和顏牙醫診所', '臺中市潭子區', '2025-02-17 00:00:00', '2025-03-31 00:00:00', '潭子區（臺中市）=', 24.21171121, 120.710997, '無資料', 'https://www.artspots-taichung.com.tw/tw/news-detail/321?kind=11&root=8&page=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-全心自由視：林益全KEVIN攝影展', `description`='每當旅遊結束，都是心的昇華我們眼中所見的世界，\r\n也總在折射當時的自己。\r\n展覽展示攝影家林益全KEVIN精采攝影作品，這些照片，紀錄了異國真實面貌，旅途中有不完美，也有屏息的完美，都讓回憶，更顯深邃。\r\n', `organizer`='和顏牙醫診所', `address`='臺中市潭子區', `start_date`='2025-02-17 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='潭子區（臺中市）=', `latitude`=24.21171121, `longitude`=120.710997, `ticket_price`='無資料', `source_url`='https://www.artspots-taichung.com.tw/tw/news-detail/321?kind=11&root=8&page=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82e26b32458d4363830', '臺中市藝術亮點-抱抱春彩：洪易雕塑藝術個展', '創作風格鮮明獨特的藝術家洪易作品總給人熱情正面、華麗繽紛、可愛近人且具有豐富感染力的視覺感受，自信展現出對家鄉臺灣的在地情感和充滿特色的象徵性符號。\r\n\r\n此次將以大自然中的可愛動物們為主題，展示多種精美雕塑作品，主視覺《無尾熊》雕塑作品是為出展澳洲而創作，將首次在臺中亮相！全身彩繪花卉繽紛綻放，象徵生活如春暖花開般璀璨耀眼，富貴發達，歡迎民眾一同來擁抱春彩。\r\n', '臺中市中友百貨公司', '臺中市北區三民路3段161號', '2025-02-20 00:00:00', '2025-04-14 00:00:00', '臺中中友百貨公司', 24.15863985, 120.6809521, '無資料', 'https://www.artspots-taichung.com.tw/tw/news-detail/319?kind=11&root=8&page=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-抱抱春彩：洪易雕塑藝術個展', `description`='創作風格鮮明獨特的藝術家洪易作品總給人熱情正面、華麗繽紛、可愛近人且具有豐富感染力的視覺感受，自信展現出對家鄉臺灣的在地情感和充滿特色的象徵性符號。\r\n\r\n此次將以大自然中的可愛動物們為主題，展示多種精美雕塑作品，主視覺《無尾熊》雕塑作品是為出展澳洲而創作，將首次在臺中亮相！全身彩繪花卉繽紛綻放，象徵生活如春暖花開般璀璨耀眼，富貴發達，歡迎民眾一同來擁抱春彩。\r\n', `organizer`='臺中市中友百貨公司', `address`='臺中市北區三民路3段161號', `start_date`='2025-02-20 00:00:00', `end_date`='2025-04-14 00:00:00', `location`='臺中中友百貨公司', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://www.artspots-taichung.com.tw/tw/news-detail/319?kind=11&root=8&page=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82e26b32458d4363831', '臺中市藝術亮點-「光流影轉/氣象萬千」林順孝西畫創作展', '藝術家林順孝擅長藉由光流影轉之氣化美學原創語彙，跨越抽象與具象之界限，營造一種深具東方人文特質的韻律與抒情氣象，本次展覽展出他精采的西畫作品，包含油畫及水彩畫等，呈現出渾沌浩瀚、充斥無限精神能量如極光的日耀雲彩與流盪大氣。', '財團法人英才文教基金會', '臺中市西屯區府會園道179號4樓', '2025-03-03 00:00:00', '2025-03-25 00:00:00', '財團法人英才文教基金會全球藝術中心', 24.1604928, 120.6455336, '無資料', 'https://www.artspots-taichung.com.tw/tw/news-detail/317?kind=11&root=8&page=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-「光流影轉/氣象萬千」林順孝西畫創作展', `description`='藝術家林順孝擅長藉由光流影轉之氣化美學原創語彙，跨越抽象與具象之界限，營造一種深具東方人文特質的韻律與抒情氣象，本次展覽展出他精采的西畫作品，包含油畫及水彩畫等，呈現出渾沌浩瀚、充斥無限精神能量如極光的日耀雲彩與流盪大氣。', `organizer`='財團法人英才文教基金會', `address`='臺中市西屯區府會園道179號4樓', `start_date`='2025-03-03 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='財團法人英才文教基金會全球藝術中心', `latitude`=24.1604928, `longitude`=120.6455336, `ticket_price`='無資料', `source_url`='https://www.artspots-taichung.com.tw/tw/news-detail/317?kind=11&root=8&page=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82f26b32458d4363833', '庶民生活-2024-張書榕創作展', '繪者簡介：\r\n張書榕，畢業於國立成功大學藝術研究所，現任水筆仔美術教室的老師。其藝術作品以庶民的辛勞與樸實為主題，靈感來自日常生活的點滴景象，透過細膩的筆觸及深刻的觀察力，捕捉並展現了勞動者的汗水與笑容、市井小民的堅韌與樂觀。她相信藝術源自於生活，並服務於生活，希望通過自己的作品，能夠喚起人們對平凡生活的珍視與熱愛。\r\n展出時間：114/01/2~114/3/30 開館時間週二~週六09:00-21:00，週日09:00-17:00\r\n展出地點：高市圖寶珠分館 自修室', '高雄市立圖書館總館', '高雄市三民區002鄰大順二路468號', '2025-01-02 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館寶珠分館', 22.649382, 120.3249695, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='庶民生活-2024-張書榕創作展', `description`='繪者簡介：\r\n張書榕，畢業於國立成功大學藝術研究所，現任水筆仔美術教室的老師。其藝術作品以庶民的辛勞與樸實為主題，靈感來自日常生活的點滴景象，透過細膩的筆觸及深刻的觀察力，捕捉並展現了勞動者的汗水與笑容、市井小民的堅韌與樂觀。她相信藝術源自於生活，並服務於生活，希望通過自己的作品，能夠喚起人們對平凡生活的珍視與熱愛。\r\n展出時間：114/01/2~114/3/30 開館時間週二~週六09:00-21:00，週日09:00-17:00\r\n展出地點：高市圖寶珠分館 自修室', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區002鄰大順二路468號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館寶珠分館', `latitude`=22.649382, `longitude`=120.3249695, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec82f26b32458d4363836', '李憶婷繪本原畫展', '與書店家熟識多年的插畫家李憶婷，自從赴英旅居後，每年都會像回娘家一樣帶著新作品回書店來和大家見面，今年要繼《美好動物園》和《美好食堂》之後再度推出豐富趣味的動物圖文書，深諳各種罕見動物和動物冷知識的憶婷，要讓大小朋友跟動物們一起下班，探索更多不為人知、神秘的動物習性和技能，二月書店裡的美好動物園將展出原畫和系列作品，歡迎大家來一網打盡成為動物萬事通！\r\n《動物們下班啦！意想不到的熱鬧生活》\r\n★繪本情境x超趣味知識x互動遊戲的動物圖文書\r\n★精選59種奇妙又有趣的動物冷知識\r\n★精美拉頁營造全景式畫面，逗趣細節一覽無遺！\r\n\r\n▍榮獲英國切爾騰那姆插畫獎畫家李憶婷最新力作\r\n▍認識動物、友善動物的最佳入門讀物\r\n跟著特派員尖尖的腳步，\r\n探訪動物們有趣又熱鬧的下班生活，\r\n揭開令人吃驚的動物習性及獨家技能，\r\n一起發現不為人知的動物祕密吧！\r\n\r\n即日即可參與新書預購（1/14～2/1)，及早預訂或報名活動都可獲得限量禮物！\r\n2/16憶婷將在晨熹社發表新書！來聽憶婷聊聊《動物們下班啦！意想不到的熱鬧生活》裡逗趣又新奇的動物小祕密，當天還有趣味的動物手作活動喔！\r\n▍《動物們下班啦！意想不到的熱鬧生活》新書見面會及趣味手作活動\r\n․主講：李憶婷Yiting Lee\r\n․時間：2∕16（日）14：30-16：00\r\n․地點：臺中晨熹社\r\n․報名方式：購書入場或每人酌收入場費100元，可全額折抵購書\r\n　採事先報名制，請私訊或來電向晨熹社登記報名。\r\n★名額有限，額滿截止。\r\n\r\n▍李憶婷繪本原畫展\r\n․展期：2∕7（五）~3∕9（日）\r\n․地點：臺中晨熹社\r\n', '晨熹社 asahikari ', '臺中市西區博館路234號', '2025-02-07 00:00:00', '2025-03-09 00:00:00', '晨熹社 asahikari', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/46vyM3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='李憶婷繪本原畫展', `description`='與書店家熟識多年的插畫家李憶婷，自從赴英旅居後，每年都會像回娘家一樣帶著新作品回書店來和大家見面，今年要繼《美好動物園》和《美好食堂》之後再度推出豐富趣味的動物圖文書，深諳各種罕見動物和動物冷知識的憶婷，要讓大小朋友跟動物們一起下班，探索更多不為人知、神秘的動物習性和技能，二月書店裡的美好動物園將展出原畫和系列作品，歡迎大家來一網打盡成為動物萬事通！\r\n《動物們下班啦！意想不到的熱鬧生活》\r\n★繪本情境x超趣味知識x互動遊戲的動物圖文書\r\n★精選59種奇妙又有趣的動物冷知識\r\n★精美拉頁營造全景式畫面，逗趣細節一覽無遺！\r\n\r\n▍榮獲英國切爾騰那姆插畫獎畫家李憶婷最新力作\r\n▍認識動物、友善動物的最佳入門讀物\r\n跟著特派員尖尖的腳步，\r\n探訪動物們有趣又熱鬧的下班生活，\r\n揭開令人吃驚的動物習性及獨家技能，\r\n一起發現不為人知的動物祕密吧！\r\n\r\n即日即可參與新書預購（1/14～2/1)，及早預訂或報名活動都可獲得限量禮物！\r\n2/16憶婷將在晨熹社發表新書！來聽憶婷聊聊《動物們下班啦！意想不到的熱鬧生活》裡逗趣又新奇的動物小祕密，當天還有趣味的動物手作活動喔！\r\n▍《動物們下班啦！意想不到的熱鬧生活》新書見面會及趣味手作活動\r\n․主講：李憶婷Yiting Lee\r\n․時間：2∕16（日）14：30-16：00\r\n․地點：臺中晨熹社\r\n․報名方式：購書入場或每人酌收入場費100元，可全額折抵購書\r\n　採事先報名制，請私訊或來電向晨熹社登記報名。\r\n★名額有限，額滿截止。\r\n\r\n▍李憶婷繪本原畫展\r\n․展期：2∕7（五）~3∕9（日）\r\n․地點：臺中晨熹社\r\n', `organizer`='晨熹社 asahikari ', `address`='臺中市西區博館路234號', `start_date`='2025-02-07 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='晨熹社 asahikari', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/46vyM3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec83026b32458d4363839', '【活動】《時光的見證》撕貼畫工作坊', '無資料', '國立故宮博物院', '嘉義縣太保市故宮大道888號', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '國立故宮博物院南部院區', 23.4704066, 120.2913281, '無資料', 'https://south.npm.gov.tw/ActivityInfoDetailC003210.aspx?Cond=fad48ceb-f39f-4462-b1dc-3279234e5d0d&ap', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【活動】《時光的見證》撕貼畫工作坊', `description`='無資料', `organizer`='國立故宮博物院', `address`='嘉義縣太保市故宮大道888號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='國立故宮博物院南部院區', `latitude`=23.4704066, `longitude`=120.2913281, `ticket_price`='無資料', `source_url`='https://south.npm.gov.tw/ActivityInfoDetailC003210.aspx?Cond=fad48ceb-f39f-4462-b1dc-3279234e5d0d&ap', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678ec83126b32458d436383d', '梅山文教基金會西畫班學員聯展：就是愛畫畫', '梅山文教基金會西畫班自105年6月開班至今，已歷經8年多精彩畫作，每一幅畫作背後，都是一段深刻的創作過程。\r\n學員對於畫畫的熱忱，用畫筆表達內心的創意與生命力，展現藝術的魅力，帶領觀眾穿越不同的情感與思想。', '財團法人梅山文教基金會', '嘉義縣梅山鄉健康街91號', '2025-01-04 00:00:00', '2025-02-27 00:00:00', '嘉義縣梅山文教基金會', 23.585762, 120.560558, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='梅山文教基金會西畫班學員聯展：就是愛畫畫', `description`='梅山文教基金會西畫班自105年6月開班至今，已歷經8年多精彩畫作，每一幅畫作背後，都是一段深刻的創作過程。\r\n學員對於畫畫的熱忱，用畫筆表達內心的創意與生命力，展現藝術的魅力，帶領觀眾穿越不同的情感與思想。', `organizer`='財團法人梅山文教基金會', `address`='嘉義縣梅山鄉健康街91號', `start_date`='2025-01-04 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='嘉義縣梅山文教基金會', `latitude`=23.585762, `longitude`=120.560558, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678efb7a8f15e3aa87f3311d', '承藝成藝 陶瓷聯展', '展覽名稱｜承藝成藝 陶瓷聯展 LEGACY AND INNOVATION : Ceramic Art Joint Exhibition\r\n展覽期間｜2025.02.06－2025.03.30\r\n開幕茶會｜2025.02.09 Sun. 15:00\r\n開放時間｜10：00－19：00（每月一、三週之星期二休館）\r\n地　　點｜光點藝術中心　三樓展覽廳\r\n地　　址｜新北市鶯歌區陶瓷街18號\r\n展覽專線｜02-2678-6577\r\n聯展介紹｜\r\n【承藝。成藝】巧妙地運用了兩個同音異字承先啟後，體現了傳承與創新之間的微妙平衡。\r\n\r\n【承藝】的意義在於，它是連結過去與未來的美學文化移轉。既是對歷史前人的尊重，也是對未來後輩的承諾。傳承技藝打造上一代的知識、技巧與智慧傳承至下一代的過程，它不僅是文化與歷史的傳承，更是對人類創造力的珍視與保存。我們讚嘆前人的技藝同時也從中學習理解到其內涵與精神的承載。進而與內心產生共鳴讓我們體會到藝術美學領域的淵博。\r\n\r\n【成藝】則代表著在傳承基礎上的創新與發展，讓藝術在時代的洪流中煥發新的生命力。成藝是對專業技能與藝術表現的不斷追求與提升，代表著個人在特定領域中達到卓越的境界。靈感的迸發、成就工藝的過程包含了對細節的打磨和對完美的執著追求。成就技藝的核心在於不斷創新與現代突破。技藝的成果技藝也反映了個人的價值和社會的認可，無形中激勵更多的人追隨並推動相關領域的發展。因此，成就技藝不僅是對專業的精益求精，更是對自身豐富的探索與超越，成就了自身在追求卓越過程中的無限可能性。', '鶯歌光點美學館', '新北市鶯歌區陶瓷街18號3F', '2025-02-06 00:00:00', '2025-03-30 00:00:00', '光點藝術中心 三樓展覽廳', 24.9566258, 121.3466269, '無資料', 'https://www.yinggo.com.tw/blogs/%E5%B1%95%E8%A6%BD%E9%A0%90%E5%91%8A', '[]') ON DUPLICATE KEY UPDATE `activity_name`='承藝成藝 陶瓷聯展', `description`='展覽名稱｜承藝成藝 陶瓷聯展 LEGACY AND INNOVATION : Ceramic Art Joint Exhibition\r\n展覽期間｜2025.02.06－2025.03.30\r\n開幕茶會｜2025.02.09 Sun. 15:00\r\n開放時間｜10：00－19：00（每月一、三週之星期二休館）\r\n地　　點｜光點藝術中心　三樓展覽廳\r\n地　　址｜新北市鶯歌區陶瓷街18號\r\n展覽專線｜02-2678-6577\r\n聯展介紹｜\r\n【承藝。成藝】巧妙地運用了兩個同音異字承先啟後，體現了傳承與創新之間的微妙平衡。\r\n\r\n【承藝】的意義在於，它是連結過去與未來的美學文化移轉。既是對歷史前人的尊重，也是對未來後輩的承諾。傳承技藝打造上一代的知識、技巧與智慧傳承至下一代的過程，它不僅是文化與歷史的傳承，更是對人類創造力的珍視與保存。我們讚嘆前人的技藝同時也從中學習理解到其內涵與精神的承載。進而與內心產生共鳴讓我們體會到藝術美學領域的淵博。\r\n\r\n【成藝】則代表著在傳承基礎上的創新與發展，讓藝術在時代的洪流中煥發新的生命力。成藝是對專業技能與藝術表現的不斷追求與提升，代表著個人在特定領域中達到卓越的境界。靈感的迸發、成就工藝的過程包含了對細節的打磨和對完美的執著追求。成就技藝的核心在於不斷創新與現代突破。技藝的成果技藝也反映了個人的價值和社會的認可，無形中激勵更多的人追隨並推動相關領域的發展。因此，成就技藝不僅是對專業的精益求精，更是對自身豐富的探索與超越，成就了自身在追求卓越過程中的無限可能性。', `organizer`='鶯歌光點美學館', `address`='新北市鶯歌區陶瓷街18號3F', `start_date`='2025-02-06 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='光點藝術中心 三樓展覽廳', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='https://www.yinggo.com.tw/blogs/%E5%B1%95%E8%A6%BD%E9%A0%90%E5%91%8A', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678f0ded26b32458d436383e', '特別的日常', '\n「特別的日常」呈現特殊生的日常面向，強調障礙並非局限，而是展現自我的方式。展覽透過藝術作品展示身心障礙者的創作成果，突顯他們在社會參與與文化共融中的重要性。以「自我寫照」、「親情與友誼」、「生活的片刻」、「心思•幻想」四個主題，展現他們的情感、經驗與夢想，並彰顯其獨特視角，啟發觀者體會他們的堅韌與生命力。\n"A Special Daily Life" illuminates the everyday experiences of individuals with special needs, reframing disabilities not as limitations but as avenues of self-expression. Highlighting their vital role in fostering social engagement and cultural inclusion, the exhibit explores four themes: "Self-Portraits," "Family and Friendship," "Moments of Life," and "Thoughts and Fantasies," capturing their emotions, experiences, and aspirations.\n', '無資料', '臺北市南海路四十七號', '2025-02-22 00:00:00', '2025-03-05 00:00:00', '第1、2展覽廳', 25.032319, 121.51206, '無資料', 'https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4410', '[]') ON DUPLICATE KEY UPDATE `activity_name`='特別的日常', `description`='\n「特別的日常」呈現特殊生的日常面向，強調障礙並非局限，而是展現自我的方式。展覽透過藝術作品展示身心障礙者的創作成果，突顯他們在社會參與與文化共融中的重要性。以「自我寫照」、「親情與友誼」、「生活的片刻」、「心思•幻想」四個主題，展現他們的情感、經驗與夢想，並彰顯其獨特視角，啟發觀者體會他們的堅韌與生命力。\n"A Special Daily Life" illuminates the everyday experiences of individuals with special needs, reframing disabilities not as limitations but as avenues of self-expression. Highlighting their vital role in fostering social engagement and cultural inclusion, the exhibit explores four themes: "Self-Portraits," "Family and Friendship," "Moments of Life," and "Thoughts and Fantasies," capturing their emotions, experiences, and aspirations.\n', `organizer`='無資料', `address`='臺北市南海路四十七號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='第1、2展覽廳', `latitude`=25.032319, `longitude`=121.51206, `ticket_price`='無資料', `source_url`='https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4410', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678f50e507f3e7d36c5308c4', '《 舊影重遊 x 如影隨形 》林莉酈x胡晴雯水墨雙個展', '2025年度的首檔展覽，當代一畫廊很榮幸邀請兩位女性藝術家——林莉酈與胡晴雯，攜手以雙個展的形式呈現她們的最新創作。本次雙個展呈現了兩位藝術家相互呼應的創作思考。林莉酈的作品以日常為題，將平凡轉化為深刻的生命省察；胡晴雯的作品則以光影為軸，描繪出瞬間與永恆的辯證。他們的作品在物質性與精神性之間搭建了一座橋樑，邀請觀者在光影與時間的流動中，感受生命的豐富與深邃，期望這些作品能為觀者帶來一場關於存在、記憶與永恆的視覺對話。', '當代一畫廊', '臺北市松山區光復南路22巷32號1樓', '2025-02-07 00:00:00', '2025-03-22 00:00:00', '當代一畫廊', 25.05999101, 121.5575876, '免費', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《 舊影重遊 x 如影隨形 》林莉酈x胡晴雯水墨雙個展', `description`='2025年度的首檔展覽，當代一畫廊很榮幸邀請兩位女性藝術家——林莉酈與胡晴雯，攜手以雙個展的形式呈現她們的最新創作。本次雙個展呈現了兩位藝術家相互呼應的創作思考。林莉酈的作品以日常為題，將平凡轉化為深刻的生命省察；胡晴雯的作品則以光影為軸，描繪出瞬間與永恆的辯證。他們的作品在物質性與精神性之間搭建了一座橋樑，邀請觀者在光影與時間的流動中，感受生命的豐富與深邃，期望這些作品能為觀者帶來一場關於存在、記憶與永恆的視覺對話。', `organizer`='當代一畫廊', `address`='臺北市松山區光復南路22巷32號1樓', `start_date`='2025-02-07 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='當代一畫廊', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='免費', `source_url`='無資料', `image_url`='[]';
