INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67915c4c26b32458d43638b6', '「綠野纖蹤」纖紅蜻蜓印象展', '珍稀物種纖紅蜻蜓\r\n僅分布於魚池鄉及埔里鎮的隱蔽草澤\r\n是在地的生態瑰寶與驕傲\r\n在大埔里公民科學家的鏡頭下\r\n呈現纖紅蜻蜓的獨特風采\r\n2025就從探訪綠野纖蹤開始！', '財團法人新故鄉文教基金會', '南投縣魚池鄉中山路', '2025-01-01 00:00:00', '2025-03-30 00:00:00', '日月潭國家風景區', 23.8565133, 120.9021315, '無資料', 'https://www.facebook.com/NewHomeland.1999.02.04', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「綠野纖蹤」纖紅蜻蜓印象展', `description`='珍稀物種纖紅蜻蜓\r\n僅分布於魚池鄉及埔里鎮的隱蔽草澤\r\n是在地的生態瑰寶與驕傲\r\n在大埔里公民科學家的鏡頭下\r\n呈現纖紅蜻蜓的獨特風采\r\n2025就從探訪綠野纖蹤開始！', `organizer`='財團法人新故鄉文教基金會', `address`='南投縣魚池鄉中山路', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='日月潭國家風景區', `latitude`=23.8565133, `longitude`=120.9021315, `ticket_price`='無資料', `source_url`='https://www.facebook.com/NewHomeland.1999.02.04', `image_url`='[]';
