INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67915c4d26b32458d43638b8', '無資料', '佔地150公頃的暨大，栽植逾千棵包含「八重櫻」、「山櫻花」、「枝垂櫻」及「昭和櫻」的櫻花，將陸陸續續在除夕之後逐一綻放。今年受暖冬影響櫻花仍在含苞待放，預估春節期間將逐一綻放，遊客可徜徉於美麗校園拍照留念。此次櫻花季結合櫻花、茶道、音樂與咖啡等主題，特於週末安排櫻花茶席，邀遊客櫻花林下品好茶、賞櫻花，享受心靈饗宴結合！\r\n線上報名 https://reurl.cc/b3a8zM\r\n活動洽詢：0931-666-806 大埔里地區觀光發展協會總幹事賴美月。', '國立暨南國際大學', '南投縣埔里鎮大學路1號', '國立暨南國際大學', 23.9511431, 120.9306649, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='佔地150公頃的暨大，栽植逾千棵包含「八重櫻」、「山櫻花」、「枝垂櫻」及「昭和櫻」的櫻花，將陸陸續續在除夕之後逐一綻放。今年受暖冬影響櫻花仍在含苞待放，預估春節期間將逐一綻放，遊客可徜徉於美麗校園拍照留念。此次櫻花季結合櫻花、茶道、音樂與咖啡等主題，特於週末安排櫻花茶席，邀遊客櫻花林下品好茶、賞櫻花，享受心靈饗宴結合！\r\n線上報名 https://reurl.cc/b3a8zM\r\n活動洽詢：0931-666-806 大埔里地區觀光發展協會總幹事賴美月。', `organizer`='國立暨南國際大學', `address`='南投縣埔里鎮大學路1號', `location`='國立暨南國際大學', `latitude`=23.9511431, `longitude`=120.9306649, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67915c4d26b32458d43638bc', '2025玉山國家公園1-2月冬日賞梅遊東埔-生態講座、導覽解說', '西北園區各服務據點也有許多導覽活動，冬日賞梅不僅僅只有繁花可看，山中歲月靜好、八通關古道今昔、東埔的風土人情於假期間，都有專業解說人員說給您聽，歡迎大小朋友攜手參加，豐富您的寒假歲月。洽詢電話：049-2701269。\r\n導覽解說主題\r\n上午場／東埔-父子斷崖導覽、雲龍巡查視氣候及步道狀況。\r\n下午場／帶隊導覽解說（溫泉區-東埔服務中心-吊橋）。\r\n集合地點：東埔溫泉廣場\r\n\r\n講座主題：\r\n1月31日／山中，歲月靜好\r\n2月01日／八通關古道簡介\r\n2月02日／東埔地區自然、人文環境介紹\r\n2月15日／玉山常見的野生動物\r\n2月16日／玉山常見的野生動物\r\n2月28日／玉山為名-玉山尋花\r\n3月01日／玉山主峰步道風采\r\n3月02日／塔塔加遊憩區步道風采\r\n活動地點：東埔帝綸溫泉大飯店', '玉山國家公園管理處', '南投縣信義鄉', '2025-01-31 00:00:00', '2025-03-02 00:00:00', '信義鄉（南投縣）=', 23.6554647, 121.0212867, '無資料', 'https://www.facebook.com/YuShanNationalPark', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025玉山國家公園1-2月冬日賞梅遊東埔-生態講座、導覽解說', `description`='西北園區各服務據點也有許多導覽活動，冬日賞梅不僅僅只有繁花可看，山中歲月靜好、八通關古道今昔、東埔的風土人情於假期間，都有專業解說人員說給您聽，歡迎大小朋友攜手參加，豐富您的寒假歲月。洽詢電話：049-2701269。\r\n導覽解說主題\r\n上午場／東埔-父子斷崖導覽、雲龍巡查視氣候及步道狀況。\r\n下午場／帶隊導覽解說（溫泉區-東埔服務中心-吊橋）。\r\n集合地點：東埔溫泉廣場\r\n\r\n講座主題：\r\n1月31日／山中，歲月靜好\r\n2月01日／八通關古道簡介\r\n2月02日／東埔地區自然、人文環境介紹\r\n2月15日／玉山常見的野生動物\r\n2月16日／玉山常見的野生動物\r\n2月28日／玉山為名-玉山尋花\r\n3月01日／玉山主峰步道風采\r\n3月02日／塔塔加遊憩區步道風采\r\n活動地點：東埔帝綸溫泉大飯店', `organizer`='玉山國家公園管理處', `address`='南投縣信義鄉', `start_date`='2025-01-31 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='信義鄉（南投縣）=', `latitude`=23.6554647, `longitude`=121.0212867, `ticket_price`='無資料', `source_url`='https://www.facebook.com/YuShanNationalPark', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67915c4d26b32458d43638be', '2025年1月【雲林縣二崙故事屋-詔安客家節慶特展】', '【新春特別企劃】詔安客家節慶特展\r\n1/22（三）～2/28（五）\r\n故事取材以「客家節慶」為主軸，包含客家生活的種種特色故事，例如：卜米籮、著年、摜雞酒及迎暗景等，透過主題導覽及講客家故事的活動，提昇民眾對詔安客家文化的認識。', '雲林縣政府文化觀光處', '雲林縣二崙鄉中山路102號', '2025-01-22 00:00:00', '2025-02-28 00:00:00', '二崙故事屋', 23.7695729, 120.4119282, '無資料', 'https://www.facebook.com/erlunstoryhouse', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年1月【雲林縣二崙故事屋-詔安客家節慶特展】', `description`='【新春特別企劃】詔安客家節慶特展\r\n1/22（三）～2/28（五）\r\n故事取材以「客家節慶」為主軸，包含客家生活的種種特色故事，例如：卜米籮、著年、摜雞酒及迎暗景等，透過主題導覽及講客家故事的活動，提昇民眾對詔安客家文化的認識。', `organizer`='雲林縣政府文化觀光處', `address`='雲林縣二崙鄉中山路102號', `start_date`='2025-01-22 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='二崙故事屋', `latitude`=23.7695729, `longitude`=120.4119282, `ticket_price`='無資料', `source_url`='https://www.facebook.com/erlunstoryhouse', `image_url`='[]';
