INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c726b32458d43638f9', 'POP! POP! POP!流行音樂互動展', '111年3月1日「POP! POP! POP!流行音樂互動展」於高流中心音浪塔開展,透過「全民策展」與「南方在地」2大概念出發，共設7大展區，分別為從後台出發、好歌共鳴、樂音流域、走入發聲現場、走入流行影像、在地音樂能量、及美麗島旋律，更與知名鐵三角合作，提供最好的聲音品質。', '高雄市政府', '高雄市鹽埕區17鄰真愛路1號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '無資料', 'https://kktix.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='POP! POP! POP!流行音樂互動展', `description`='111年3月1日「POP! POP! POP!流行音樂互動展」於高流中心音浪塔開展,透過「全民策展」與「南方在地」2大概念出發，共設7大展區，分別為從後台出發、好歌共鳴、樂音流域、走入發聲現場、走入流行影像、在地音樂能量、及美麗島旋律，更與知名鐵三角合作，提供最好的聲音品質。', `organizer`='高雄市政府', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='無資料', `source_url`='https://kktix.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c726b32458d43638fa', '歷史建築逍遙園常設展', '逍遙園建於昭和14年(1939)，為日本真宗西本願寺第22代法主大谷光瑞在台灣之別館。逍遙園具有日治時期建築美學之特色，空間複雜且兼具日式及西式建築風格與元素，除具建築史上之意義，有再利用之價值及潛力外，且見證時代與人文意涵，富含歷史文化價值。 大谷光瑞為著名日本宗教家與探險家，與大正天皇為連襟兄弟（皇后為大谷光瑞夫人之妹），曾於1940-1945年間擔任台灣總督府內閣參議，參與國家重大的經濟決策。昭和15年(1940)高雄新邸逍遙園落成啟用，設立目的為： 1、作為大谷光瑞在台灣發展農業與門徒教育的訓練基地。 2、作為大谷光瑞擔任政府要職來台短期居所與寫作的避暑別莊。 3、作為日治時期南台灣西本願寺勢力的分駐所。 4、選擇高雄市作為台灣進出南洋地區的重要門戶。 一、外觀特徵： 建築量體則依現況具有居住機能的特色，附屬於全體建築核心量體的西南角，屋頂變化豐富，其空間構成邏輯完全使用日式木構造的法則。進入此起居空間之動線以一外露之RC樓梯連結，有別於另一邊以內部樓梯進出之公共空間。 各建築量體間夾出的小空間則以露臺來填補，此類空間出現在本館東側，包圍核心量體的大半部，使得各量體間得以透過露臺聯繫，露臺全部由木材鋪設而成，做工精緻，建築美學與景觀用途，屋頂鋪設的瓦片則是精緻的合興窯黑瓦。 二、室內特徵： 1. 具備傳統日式住宅中無平面中心性的特質，即沒有中庭空間。 2. 擁有昭和時期中廊下型的特徵，全區空間可被區分為三大範圍:社交待客空間、服務空間及日常起居空間。日常起居空間有一側廊與外部空間串聯。 3. 由於別邸主人有留學海外之背景，並具備日本貴族身份，因此社交待客空間、日常起居空間的陳設皆出現和洋融合之現象。', '高雄市政府文化局', '高雄市新興區六一路55巷15號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '歷史建築逍遙園', 25.0421407, 121.5198716, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歷史建築逍遙園常設展', `description`='逍遙園建於昭和14年(1939)，為日本真宗西本願寺第22代法主大谷光瑞在台灣之別館。逍遙園具有日治時期建築美學之特色，空間複雜且兼具日式及西式建築風格與元素，除具建築史上之意義，有再利用之價值及潛力外，且見證時代與人文意涵，富含歷史文化價值。 大谷光瑞為著名日本宗教家與探險家，與大正天皇為連襟兄弟（皇后為大谷光瑞夫人之妹），曾於1940-1945年間擔任台灣總督府內閣參議，參與國家重大的經濟決策。昭和15年(1940)高雄新邸逍遙園落成啟用，設立目的為： 1、作為大谷光瑞在台灣發展農業與門徒教育的訓練基地。 2、作為大谷光瑞擔任政府要職來台短期居所與寫作的避暑別莊。 3、作為日治時期南台灣西本願寺勢力的分駐所。 4、選擇高雄市作為台灣進出南洋地區的重要門戶。 一、外觀特徵： 建築量體則依現況具有居住機能的特色，附屬於全體建築核心量體的西南角，屋頂變化豐富，其空間構成邏輯完全使用日式木構造的法則。進入此起居空間之動線以一外露之RC樓梯連結，有別於另一邊以內部樓梯進出之公共空間。 各建築量體間夾出的小空間則以露臺來填補，此類空間出現在本館東側，包圍核心量體的大半部，使得各量體間得以透過露臺聯繫，露臺全部由木材鋪設而成，做工精緻，建築美學與景觀用途，屋頂鋪設的瓦片則是精緻的合興窯黑瓦。 二、室內特徵： 1. 具備傳統日式住宅中無平面中心性的特質，即沒有中庭空間。 2. 擁有昭和時期中廊下型的特徵，全區空間可被區分為三大範圍:社交待客空間、服務空間及日常起居空間。日常起居空間有一側廊與外部空間串聯。 3. 由於別邸主人有留學海外之背景，並具備日本貴族身份，因此社交待客空間、日常起居空間的陳設皆出現和洋融合之現象。', `organizer`='高雄市政府文化局', `address`='高雄市新興區六一路55巷15號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='歷史建築逍遙園', `latitude`=25.0421407, `longitude`=121.5198716, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c726b32458d43638fb', '藍寶石大歌廳《秀場傳奇》故事展', '—  ❋ 藍寶石大歌廳《秀場傳奇》故事展 ❋  —\r\n—— 𝘿𝘼𝙉𝘾𝙀 𝙁𝙊𝙍 𝙔𝙊𝙐  𝄪 𝙎𝙄𝙉𝙂 𝙁𝙊𝙍 𝙔𝙊𝙐 —— \r\n⊹ 展覽亮點 ⊹\r\n2 大展區：回到一個群星匯聚，五光十色的藍寶石大歌廳。\r\n8 組深度訪談：從台前藝人、幕後工作者，再到文史工作者，一窺歌舞廳風華。\r\n11 套經典秀服：全新視角一睹當年秀服的繁華奪目盛況。\r\n超過 100 件珍貴展品：共同見證臺灣音樂與娛樂產業重要符號。\r\n⊹ 展覽介紹 ⊹\r\n一個群星匯聚，五光十色的華麗舞台\r\n「藍寶石大歌廳」是人們真情流露的盛大演出。這裡「演」的是人民的生活，「唱」的是心底的情懷。一演一唱，道盡了一代人青春年華的記憶。\r\n\r\n梳理珍貴史料、保存時代感物件、復刻經典華麗秀服，看見藍寶石大歌廳的風光歲月與興衰，認識秀場的種種趣事，以及感受群星聚集的盛況。\r\n\r\n重現台灣秀場大舞台 ——「演」的底蘊\r\n秀場主持人的穿針引線，讓環環相扣的演出顯得豐富多變、細膩有趣，讓秀場充滿笑料與歡樂。這裡凸顯了主持人各種「說、學、逗、唱」，「說」利用通俗易懂的笑話串聯每個演出，；「學」則以反串和誇張的模仿深植人心；「逗」以互相挖苦的自嘲引得觀眾捧腹大笑；而「唱」則常在不同的歌曲中即興改詞，創作出如豬哥亮的《山南山北》般的經典歪歌，為觀眾帶來無盡驚喜。\r\n\r\n這些歡聲笑語交織出歌廳秀的特殊景致，一起細數當時青春真摯的記憶。\r\n\r\n從台前到幕後——「唱」的魅力\r\n許多「台前」的精采演出，與「幕後」的努力息息相關。這裡我們將視角從「台前」轉向「幕後」，以「唱」為主題，展示了絢麗多變的舞蹈和歌手們的輝煌時刻，像是充滿動感與激情演出的林沖、獨特聲線的玉女歌手美黛，美艷性感的陳美鳳，深情款款的洪榮宏，這些秀場傳奇都令人難以忘懷。\r\n\r\n一件件華麗秀服、一張張泛黃相片、一段段深度訪談，讓那段美好歲月永留心間。', '高雄流行音樂中心', '高雄市鹽埕區17鄰真愛路1號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '敬老及里民票 +88;學生及團體票+128;全票+168', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藍寶石大歌廳《秀場傳奇》故事展', `description`='—  ❋ 藍寶石大歌廳《秀場傳奇》故事展 ❋  —\r\n—— 𝘿𝘼𝙉𝘾𝙀 𝙁𝙊𝙍 𝙔𝙊𝙐  𝄪 𝙎𝙄𝙉𝙂 𝙁𝙊𝙍 𝙔𝙊𝙐 —— \r\n⊹ 展覽亮點 ⊹\r\n2 大展區：回到一個群星匯聚，五光十色的藍寶石大歌廳。\r\n8 組深度訪談：從台前藝人、幕後工作者，再到文史工作者，一窺歌舞廳風華。\r\n11 套經典秀服：全新視角一睹當年秀服的繁華奪目盛況。\r\n超過 100 件珍貴展品：共同見證臺灣音樂與娛樂產業重要符號。\r\n⊹ 展覽介紹 ⊹\r\n一個群星匯聚，五光十色的華麗舞台\r\n「藍寶石大歌廳」是人們真情流露的盛大演出。這裡「演」的是人民的生活，「唱」的是心底的情懷。一演一唱，道盡了一代人青春年華的記憶。\r\n\r\n梳理珍貴史料、保存時代感物件、復刻經典華麗秀服，看見藍寶石大歌廳的風光歲月與興衰，認識秀場的種種趣事，以及感受群星聚集的盛況。\r\n\r\n重現台灣秀場大舞台 ——「演」的底蘊\r\n秀場主持人的穿針引線，讓環環相扣的演出顯得豐富多變、細膩有趣，讓秀場充滿笑料與歡樂。這裡凸顯了主持人各種「說、學、逗、唱」，「說」利用通俗易懂的笑話串聯每個演出，；「學」則以反串和誇張的模仿深植人心；「逗」以互相挖苦的自嘲引得觀眾捧腹大笑；而「唱」則常在不同的歌曲中即興改詞，創作出如豬哥亮的《山南山北》般的經典歪歌，為觀眾帶來無盡驚喜。\r\n\r\n這些歡聲笑語交織出歌廳秀的特殊景致，一起細數當時青春真摯的記憶。\r\n\r\n從台前到幕後——「唱」的魅力\r\n許多「台前」的精采演出，與「幕後」的努力息息相關。這裡我們將視角從「台前」轉向「幕後」，以「唱」為主題，展示了絢麗多變的舞蹈和歌手們的輝煌時刻，像是充滿動感與激情演出的林沖、獨特聲線的玉女歌手美黛，美艷性感的陳美鳳，深情款款的洪榮宏，這些秀場傳奇都令人難以忘懷。\r\n\r\n一件件華麗秀服、一張張泛黃相片、一段段深度訪談，讓那段美好歲月永留心間。', `organizer`='高雄流行音樂中心', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='敬老及里民票 +88;學生及團體票+128;全票+168', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c726b32458d43638fc', '「黃埔新村展示館」歷史文物展', '黃埔新村為台灣第一代眷村，因其建築特色及重要歷史背景，自2003年由高雄市政府登錄為文化景觀，全村完整保留。\r\n「眷村」概指20世紀中葉，從大陸遷徙來臺的軍眷們居住以及後續發展的聚落，眷村文化更是紀敘臺灣移民史及多元族群象徵的重要成分。\r\n因此「黃埔新村展示館」將臺灣眷村的文史脈絡，傳承眷戶們的生命記事，展示珍貴歷史文物與影像，邀請市民朋友一同參與開拓保存眷村文化新的里程碑，體驗臺灣的多元文化傳承。', '高雄市政府文化局', '高雄市鳳山區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '鳳山區（高雄市）=', 22.61379251, 120.3554359, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「黃埔新村展示館」歷史文物展', `description`='黃埔新村為台灣第一代眷村，因其建築特色及重要歷史背景，自2003年由高雄市政府登錄為文化景觀，全村完整保留。\r\n「眷村」概指20世紀中葉，從大陸遷徙來臺的軍眷們居住以及後續發展的聚落，眷村文化更是紀敘臺灣移民史及多元族群象徵的重要成分。\r\n因此「黃埔新村展示館」將臺灣眷村的文史脈絡，傳承眷戶們的生命記事，展示珍貴歷史文物與影像，邀請市民朋友一同參與開拓保存眷村文化新的里程碑，體驗臺灣的多元文化傳承。', `organizer`='高雄市政府文化局', `address`='高雄市鳳山區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='鳳山區（高雄市）=', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c726b32458d43638fd', '鳳鼻頭考古遺址常態展', '高雄林園鳳鼻頭遺址為全台十一處國定遺址之一，豐厚的多文化層堆積完整展現南部史前文化的演變歷程；2021年文化部委託高市府設置「鳳鼻頭考古教育館」擔負鳳鼻頭遺址教育的推廣基地，歷經近一年多的籌劃建置，112年2月24日起開放民眾參觀。展場空間結合遺址影音資訊說明及出土文物展示，藉以深入了解史前人類使用的器具及生活智慧。', '高雄市政府文化局', '高雄市林園區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '林園區（高雄市）=', 22.50813743, 120.399052, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鳳鼻頭考古遺址常態展', `description`='高雄林園鳳鼻頭遺址為全台十一處國定遺址之一，豐厚的多文化層堆積完整展現南部史前文化的演變歷程；2021年文化部委託高市府設置「鳳鼻頭考古教育館」擔負鳳鼻頭遺址教育的推廣基地，歷經近一年多的籌劃建置，112年2月24日起開放民眾參觀。展場空間結合遺址影音資訊說明及出土文物展示，藉以深入了解史前人類使用的器具及生活智慧。', `organizer`='高雄市政府文化局', `address`='高雄市林園區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='林園區（高雄市）=', `latitude`=22.50813743, `longitude`=120.399052, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c726b32458d43638fe', '林園歷史教室常設展', '林園歷史教室展示林園歷史、產業及生活等樣貌，呈現林園文化內涵及特色，讓參訪民眾瞭解林園的各個面貌，達文化教育效益。展示內容說明如下：\r\nA區：本歷史建築發展歷程：包含老屋故事、日治時期警察制度及老照片展示。\r\nB區：林園區導覽：以林園區大地圖介紹文化景點、重要信仰中心、產業、生態休閒及文教機構等，並展示代表林園歷史最悠久的國定遺址鳳鼻頭遺址文化內涵介紹，並有林園老街意象、林園各社區之文創商品及服務台多媒體設施。\r\nC區：林園傳奇：此區以林園文史及居住生活特色為主，展覽內容包容林半仙傳奇故事、林園地區堂號、大陳義胞村、歷史建築林園港埔黃家古厝及軍事設施-清水巖原日軍戰備坑道等。', '高雄市政府文化局', '高雄市林園區002鄰福興街97號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '原頂林仔邊警察官吏派出所', 22.5047336, 120.3948189, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='林園歷史教室常設展', `description`='林園歷史教室展示林園歷史、產業及生活等樣貌，呈現林園文化內涵及特色，讓參訪民眾瞭解林園的各個面貌，達文化教育效益。展示內容說明如下：\r\nA區：本歷史建築發展歷程：包含老屋故事、日治時期警察制度及老照片展示。\r\nB區：林園區導覽：以林園區大地圖介紹文化景點、重要信仰中心、產業、生態休閒及文教機構等，並展示代表林園歷史最悠久的國定遺址鳳鼻頭遺址文化內涵介紹，並有林園老街意象、林園各社區之文創商品及服務台多媒體設施。\r\nC區：林園傳奇：此區以林園文史及居住生活特色為主，展覽內容包容林半仙傳奇故事、林園地區堂號、大陳義胞村、歷史建築林園港埔黃家古厝及軍事設施-清水巖原日軍戰備坑道等。', `organizer`='高雄市政府文化局', `address`='高雄市林園區002鄰福興街97號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='原頂林仔邊警察官吏派出所', `latitude`=22.5047336, `longitude`=120.3948189, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c726b32458d43638ff', '歷史建築九曲堂泰芳商會鳳梨罐詰工場 (臺灣鳳梨工場)常設展', '大樹地區因為地理環境及氣侯條件適合鳳梨生長，成為鳳梨主要產區，先後曾有11家鳳梨罐頭工廠，而九曲堂因鐵路縱貫線設站以便於運輸，目前只剩泰芳商會第三、四工廠三棟建物，是全台唯一僅存日據時期的鳳梨產業建築，文化局歷經兩年修復工程，｢臺灣鳳梨工場｣於107年8月18日開放啟用。\r\n臺灣鳳梨工場分為三個館，A:大樹文史展示館 B:鳳梨產業展示館 C:旺來會社，近百年的產業設施蛻變轉型成為台灣鳳梨工場，成為認識、學習、體驗與休閒共存的場域，讓民眾感受台灣鳳梨罐頭的輝煌年代。\r\n', '高雄市政府文化局', '高雄市大樹區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '大樹區（高雄市）=', 22.71100364, 120.425407, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歷史建築九曲堂泰芳商會鳳梨罐詰工場 (臺灣鳳梨工場)常設展', `description`='大樹地區因為地理環境及氣侯條件適合鳳梨生長，成為鳳梨主要產區，先後曾有11家鳳梨罐頭工廠，而九曲堂因鐵路縱貫線設站以便於運輸，目前只剩泰芳商會第三、四工廠三棟建物，是全台唯一僅存日據時期的鳳梨產業建築，文化局歷經兩年修復工程，｢臺灣鳳梨工場｣於107年8月18日開放啟用。\r\n臺灣鳳梨工場分為三個館，A:大樹文史展示館 B:鳳梨產業展示館 C:旺來會社，近百年的產業設施蛻變轉型成為台灣鳳梨工場，成為認識、學習、體驗與休閒共存的場域，讓民眾感受台灣鳳梨罐頭的輝煌年代。\r\n', `organizer`='高雄市政府文化局', `address`='高雄市大樹區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='大樹區（高雄市）=', `latitude`=22.71100364, `longitude`=120.425407, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c726b32458d4363900', '市定古蹟鳳儀書院常設展', '鳳儀書院是台灣現存書院中年代最早，且規模完整與最大之書院，創建年代於清嘉慶19年(1814)。日治時期，台灣總督府大力推廣新式教育體制，書院因而日漸沒落，屋舍逐年殘破。戰後，屋舍相繼被租佔戶所用，書院格局嚴重受破壞。\r\n文化局於民國96年發包整修，於102年10月修復完成，著手進行展示規劃，於103年11月1日正式開園營運。館內配合書院氛圍，策畫鳳山、鳳儀書院及科舉歷史等展示，並呈現文昌祠祭祀空間，本場域為古蹟活化案例，非常值得您細細品味它的建築之美與文化歷史。', '高雄市政府文化局', '高雄市鳳山區013鄰鳳明街62號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '鳳儀書院', 22.6271266, 120.3589718, '優惠票+25;優待票+39;全票+66', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='市定古蹟鳳儀書院常設展', `description`='鳳儀書院是台灣現存書院中年代最早，且規模完整與最大之書院，創建年代於清嘉慶19年(1814)。日治時期，台灣總督府大力推廣新式教育體制，書院因而日漸沒落，屋舍逐年殘破。戰後，屋舍相繼被租佔戶所用，書院格局嚴重受破壞。\r\n文化局於民國96年發包整修，於102年10月修復完成，著手進行展示規劃，於103年11月1日正式開園營運。館內配合書院氛圍，策畫鳳山、鳳儀書院及科舉歷史等展示，並呈現文昌祠祭祀空間，本場域為古蹟活化案例，非常值得您細細品味它的建築之美與文化歷史。', `organizer`='高雄市政府文化局', `address`='高雄市鳳山區013鄰鳳明街62號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='鳳儀書院', `latitude`=22.6271266, `longitude`=120.3589718, `ticket_price`='優惠票+25;優待票+39;全票+66', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c726b32458d4363901', '歷史建築旗山車站–糖鐵故事館常設展', '「旗山車站-糖鐵故事館」漫步在旗山老街，一座青藍色的八角式屋頂的童話屋矗立在街道的底部。旗山車站，糖業鐵路-旗尾線最重要的站點，高雄內山九區的門戶，日治時代擔負起糖、甘蔗、香蕉等產業的運輸重任，支撐起屬於旗山最黃金的風華年代，2005年登錄為歷史建築，2016年以糖鐵故事館的面貌從新開幕。\r\n2021年重新整理內部空間使糖鐵故事館成為以糖、香蕉與火車的主題文創展示館與商店，旗尾線的旗字353號比利時小火車車頭及VR虛擬實境裝置等展示，還有獨家開發的文創商品，讓大家透過火車頭與虛擬科技重回旗尾線的懷舊時光，也可帶回滿滿觀光的紀念小物。\r\n', '高雄市政府文化局', '高雄市旗山區007鄰中山路1號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '旗山車站(原旗山驛)', 22.8846224, 120.4819792, '--+30', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歷史建築旗山車站–糖鐵故事館常設展', `description`='「旗山車站-糖鐵故事館」漫步在旗山老街，一座青藍色的八角式屋頂的童話屋矗立在街道的底部。旗山車站，糖業鐵路-旗尾線最重要的站點，高雄內山九區的門戶，日治時代擔負起糖、甘蔗、香蕉等產業的運輸重任，支撐起屬於旗山最黃金的風華年代，2005年登錄為歷史建築，2016年以糖鐵故事館的面貌從新開幕。\r\n2021年重新整理內部空間使糖鐵故事館成為以糖、香蕉與火車的主題文創展示館與商店，旗尾線的旗字353號比利時小火車車頭及VR虛擬實境裝置等展示，還有獨家開發的文創商品，讓大家透過火車頭與虛擬科技重回旗尾線的懷舊時光，也可帶回滿滿觀光的紀念小物。\r\n', `organizer`='高雄市政府文化局', `address`='高雄市旗山區007鄰中山路1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='旗山車站(原旗山驛)', `latitude`=22.8846224, `longitude`=120.4819792, `ticket_price`='--+30', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c726b32458d4363902', '「解密哨船頭」歴史展覽', '2018年高雄市政府透過「再造歷史現場–興濱計畫」，搬遷阻隔英國領事館與港灣長達33年的安檢所，使得水岸周邊歷史場域能延伸至港邊，融入市民生活，並且策畫「解密哨船頭」歴史展覽，藉由歷史描述、老照片、模型、影片等展示，讓民眾親臨歷史場景，一窺數百年來哨船頭的蛻變，具有絕佳景觀視野的哨船頭水岸歷史空間，也重現於世人眼前。', '高雄市政府文化局', '高雄市鼓山區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '鼓山區（高雄市）=', 22.65019525, 120.274163, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「解密哨船頭」歴史展覽', `description`='2018年高雄市政府透過「再造歷史現場–興濱計畫」，搬遷阻隔英國領事館與港灣長達33年的安檢所，使得水岸周邊歷史場域能延伸至港邊，融入市民生活，並且策畫「解密哨船頭」歴史展覽，藉由歷史描述、老照片、模型、影片等展示，讓民眾親臨歷史場景，一窺數百年來哨船頭的蛻變，具有絕佳景觀視野的哨船頭水岸歷史空間，也重現於世人眼前。', `organizer`='高雄市政府文化局', `address`='高雄市鼓山區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='鼓山區（高雄市）=', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c826b32458d4363903', '風雲變色打狗港-1895年乙未戰役常設展', '雄鎮北門自1876年完工以來，歷經軍事、鐵道部職工休閒場所、高雄港務單位工作及信號塔台等用途，古蹟輪廓隱沒於私人占用建物與廢棄宿舍間，甚為可惜。高雄市政府自2004年起努力溝通協調，陸續拆除古蹟周邊與景觀不相融之建物。迄2016年獲文化部經費支持進行興濱計畫，終於等到古蹟修復工程啟動的契機，並於2021年底重新對外開放。\r\n由於高雄市政府文化局在整個修復過程，特別嚴謹考據礮臺風貌，致力復原「南北兵房密勒樑」及「三合土頂版構造」，因此修復後民眾進入此空間，可直接感受到雄鎮北門清代兵房的空間氛圍。\r\n雄鎮北門的獨特地理位置，不但是觀賞大船入港及西子灣夕陽的最佳地點，南北兵房獨特的歷史空間也規劃歷史主題展示，希望古蹟成為市民生活中俯拾即是的美學養份及引以為傲的文化地標。', '高雄市政府文化局', '高雄市鼓山區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '鼓山區（高雄市）=', 22.65019525, 120.274163, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='風雲變色打狗港-1895年乙未戰役常設展', `description`='雄鎮北門自1876年完工以來，歷經軍事、鐵道部職工休閒場所、高雄港務單位工作及信號塔台等用途，古蹟輪廓隱沒於私人占用建物與廢棄宿舍間，甚為可惜。高雄市政府自2004年起努力溝通協調，陸續拆除古蹟周邊與景觀不相融之建物。迄2016年獲文化部經費支持進行興濱計畫，終於等到古蹟修復工程啟動的契機，並於2021年底重新對外開放。\r\n由於高雄市政府文化局在整個修復過程，特別嚴謹考據礮臺風貌，致力復原「南北兵房密勒樑」及「三合土頂版構造」，因此修復後民眾進入此空間，可直接感受到雄鎮北門清代兵房的空間氛圍。\r\n雄鎮北門的獨特地理位置，不但是觀賞大船入港及西子灣夕陽的最佳地點，南北兵房獨特的歷史空間也規劃歷史主題展示，希望古蹟成為市民生活中俯拾即是的美學養份及引以為傲的文化地標。', `organizer`='高雄市政府文化局', `address`='高雄市鼓山區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='鼓山區（高雄市）=', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c826b32458d4363905', '解鎖！北號誌樓常設展', '高雄港站北號誌樓是目前全國唯一完整保存號誌樓建築及聯鎖裝置、聯動鐵管、轉轍器等設施的號誌樓。睽違14年的北號誌樓，111年修復完工啟用，以經典設計重現的型態展示百年前的鐵道聯鎖技術。\r\n北號誌樓的核心號誌樓最核心、也最複雜的機能就是達成「號誌與號誌」、「號誌與道岔」、「道岔與道岔」之間的聯鎖。藉由聯鎖盤確保閘柄之間的運作協調一致，閘柄再以電器和機械的方式「遙控」遠方的道岔、號誌，以使這些裝置間也協調一致。在沒有無線電的年代，號誌樓員工亦可透過高聲電話，控制並監視整個高雄港站的車輛調度。', '高雄市政府文化局', '高雄市鼓山區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '鼓山區（高雄市）=', 22.65019525, 120.274163, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='解鎖！北號誌樓常設展', `description`='高雄港站北號誌樓是目前全國唯一完整保存號誌樓建築及聯鎖裝置、聯動鐵管、轉轍器等設施的號誌樓。睽違14年的北號誌樓，111年修復完工啟用，以經典設計重現的型態展示百年前的鐵道聯鎖技術。\r\n北號誌樓的核心號誌樓最核心、也最複雜的機能就是達成「號誌與號誌」、「號誌與道岔」、「道岔與道岔」之間的聯鎖。藉由聯鎖盤確保閘柄之間的運作協調一致，閘柄再以電器和機械的方式「遙控」遠方的道岔、號誌，以使這些裝置間也協調一致。在沒有無線電的年代，號誌樓員工亦可透過高聲電話，控制並監視整個高雄港站的車輛調度。', `organizer`='高雄市政府文化局', `address`='高雄市鼓山區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='鼓山區（高雄市）=', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c826b32458d4363906', '打狗英國領事館文化園區常設展', '英國領事館與登山古道，是全台唯一完整保存官邸及辦公室之領事館園區，引領民眾認識打狗開港及其在世界海洋經貿歷史發展的特殊文化意義。打狗英國領事館有得天獨厚遠眺西子灣海景夕照的迷人景致，歷年在博物館與地方文化館計畫補助下，完成修復及活化再利用，已成為全台最熱門的古蹟文化館之一，園區內有栩栩如生的時空場景模擬，重現英國領事館及過往時代風貌的主題展示，並提供專業導覽解說、精緻文創藝品展售、優質餐飲服務，是值得您細細品味的文化之旅。', '高雄市政府文化局', '高雄市鼓山區蓮海路20號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '打狗英國領事館文化園區', 22.618911, 120.26685, '優惠票+39;二十人以上優待票+49;全票+99', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='打狗英國領事館文化園區常設展', `description`='英國領事館與登山古道，是全台唯一完整保存官邸及辦公室之領事館園區，引領民眾認識打狗開港及其在世界海洋經貿歷史發展的特殊文化意義。打狗英國領事館有得天獨厚遠眺西子灣海景夕照的迷人景致，歷年在博物館與地方文化館計畫補助下，完成修復及活化再利用，已成為全台最熱門的古蹟文化館之一，園區內有栩栩如生的時空場景模擬，重現英國領事館及過往時代風貌的主題展示，並提供專業導覽解說、精緻文創藝品展售、優質餐飲服務，是值得您細細品味的文化之旅。', `organizer`='高雄市政府文化局', `address`='高雄市鼓山區蓮海路20號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='打狗英國領事館文化園區', `latitude`=22.618911, `longitude`=120.26685, `ticket_price`='優惠票+39;二十人以上優待票+49;全票+99', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c826b32458d4363907', '旗山生活文化園區常設展', '旗山生活文化園區北棟教室1樓策畫「一日小學生．時光膠囊」主題展示開放參觀。111年3月完成徵選高雄市旗美社區大學、佳莉編織坊、實踐大學、財團法人高雄市飛揚福利服務協會及高雄市旗山東區扶輪社等5單位進駐園區，藉公私共管模式延續古蹟原作為學習教育殿堂的場域精神、促進地方交流互動。園區禮堂及戶外空間不定期借用予在地民眾及社團辦理活動、講座及聚會等使用', '高雄市政府文化局', '高雄市旗山區022鄰文中路7號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '高雄市旗山生活文化園區(原舊鼓山國小)', 22.8903798, 120.4811207, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='旗山生活文化園區常設展', `description`='旗山生活文化園區北棟教室1樓策畫「一日小學生．時光膠囊」主題展示開放參觀。111年3月完成徵選高雄市旗美社區大學、佳莉編織坊、實踐大學、財團法人高雄市飛揚福利服務協會及高雄市旗山東區扶輪社等5單位進駐園區，藉公私共管模式延續古蹟原作為學習教育殿堂的場域精神、促進地方交流互動。園區禮堂及戶外空間不定期借用予在地民眾及社團辦理活動、講座及聚會等使用', `organizer`='高雄市政府文化局', `address`='高雄市旗山區022鄰文中路7號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄市旗山生活文化園區(原舊鼓山國小)', `latitude`=22.8903798, `longitude`=120.4811207, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c826b32458d4363908', '「遇艦RO仙境傳說」特展', '韓國GRAVITY遊戲_可愛的天使波利初登場！\r\n一整個療癒滿滿，還有巴風特、小惡魔、小野豬、群葉貓等經典角色，陪你一起踏上冒險的旅程。', '安平定情碼頭德陽艦園區', '臺南市安平區安億路121號', '2025-01-17 00:00:00', '2025-12-31 00:00:00', '臺南市安平德陽艦', 22.99008437, 120.1649949, '全票+100;65歲以上及設籍台南市民+80;未滿6歲+免費', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「遇艦RO仙境傳說」特展', `description`='韓國GRAVITY遊戲_可愛的天使波利初登場！\r\n一整個療癒滿滿，還有巴風特、小惡魔、小野豬、群葉貓等經典角色，陪你一起踏上冒險的旅程。', `organizer`='安平定情碼頭德陽艦園區', `address`='臺南市安平區安億路121號', `start_date`='2025-01-17 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺南市安平德陽艦', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='全票+100;65歲以上及設籍台南市民+80;未滿6歲+免費', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c826b32458d436390c', '「基礎攝影技巧與教學」書展、「城市閱讀」書展--2月書展', '【基礎攝影技巧與教學】書展\r\n展出期間：2025/02/01~2025/02/27\r\n展出內容：您對相機的「快門速度」、「光圈」、「ISO感光度」、「曝光補償」、「白平衡」等術語的意思感到困惑嗎？無須擔憂，本次書展將展出一系列相機的基本知識及攝影基礎概念等相關書籍，讓您不但能更了解您的相機，更能清楚地了解如何改變相機模式和設定來拍攝嘆為觀止的相片。\r\n\r\n【城市閱讀】書展\r\n展出期間：2025/02/01~2025/02/27\r\n展出內容：書展期間將展出中區分館走讀相關書籍，臺中舊城區，臺中文化歷史，生命教育等相關書籍，提供讀者閱讀。', '臺中市立圖書館中區分館', '臺中市中區成功路300號7樓', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館中區分館', 24.14168566, 120.680598, '無資料', 'https://reurl.cc/74LVmQ ； https://reurl.cc/A6L3ZZ', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「基礎攝影技巧與教學」書展、「城市閱讀」書展--2月書展', `description`='【基礎攝影技巧與教學】書展\r\n展出期間：2025/02/01~2025/02/27\r\n展出內容：您對相機的「快門速度」、「光圈」、「ISO感光度」、「曝光補償」、「白平衡」等術語的意思感到困惑嗎？無須擔憂，本次書展將展出一系列相機的基本知識及攝影基礎概念等相關書籍，讓您不但能更了解您的相機，更能清楚地了解如何改變相機模式和設定來拍攝嘆為觀止的相片。\r\n\r\n【城市閱讀】書展\r\n展出期間：2025/02/01~2025/02/27\r\n展出內容：書展期間將展出中區分館走讀相關書籍，臺中舊城區，臺中文化歷史，生命教育等相關書籍，提供讀者閱讀。', `organizer`='臺中市立圖書館中區分館', `address`='臺中市中區成功路300號7樓', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館中區分館', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='https://reurl.cc/74LVmQ ； https://reurl.cc/A6L3ZZ', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c826b32458d436390e', '展覽-攝影展-2024-2025 【影想台中】 跨年展', '請閉上眼睛，想像一下你家巷口轉角或公園的樣子，最讓你印象深刻的是什麼？試著用文字描述那個地方的各種細節。\r\n透過智慧型手機記錄生活周遭的各種影像，觀察並發掘背後的故事和獨特美感。觀眾透過學員們的定格影像，從拍攝者的視角進行視覺探索，喚醒藏在腦中的經驗與記憶。', '臺中市立圖書館神岡分館', '臺中市神岡區中山路1460號', '2025-01-05 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館神岡分館', 24.26568008, 120.6733321, '無資料', 'https://www.library.taichung.gov.tw/public/activity2/index-1.asp?Parser=99,20,697,50,,,23376,,,,,48', '[]') ON DUPLICATE KEY UPDATE `activity_name`='展覽-攝影展-2024-2025 【影想台中】 跨年展', `description`='請閉上眼睛，想像一下你家巷口轉角或公園的樣子，最讓你印象深刻的是什麼？試著用文字描述那個地方的各種細節。\r\n透過智慧型手機記錄生活周遭的各種影像，觀察並發掘背後的故事和獨特美感。觀眾透過學員們的定格影像，從拍攝者的視角進行視覺探索，喚醒藏在腦中的經驗與記憶。', `organizer`='臺中市立圖書館神岡分館', `address`='臺中市神岡區中山路1460號', `start_date`='2025-01-05 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館神岡分館', `latitude`=24.26568008, `longitude`=120.6733321, `ticket_price`='無資料', `source_url`='https://www.library.taichung.gov.tw/public/activity2/index-1.asp?Parser=99,20,697,50,,,23376,,,,,48', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c826b32458d436390f', '【大里分館】02/07-02/27 「古文物~懷舊歷史風情」展覽', '大里舊稱大里杙，古云:「一府二鹿三艋舺，四竹塹五諸羅六大里杙」，大里杙在清朝時期是臺灣六大繁榮城市之一，本次展覽展出早期的生活器具用品，讓人遙想當年人文薈萃的大里杙生活。展品:洗臉盆、雞籠、捕魚籠、謝籃、米篩等。\r\n文物提供者:民眾提供', '臺中市立圖書館大里分館', '臺中市大里區中興路一段163號', '2025-02-07 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館大里分館', 24.09575742, 120.6926261, '無資料', 'https://reurl.cc/eG7MlM', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【大里分館】02/07-02/27 「古文物~懷舊歷史風情」展覽', `description`='大里舊稱大里杙，古云:「一府二鹿三艋舺，四竹塹五諸羅六大里杙」，大里杙在清朝時期是臺灣六大繁榮城市之一，本次展覽展出早期的生活器具用品，讓人遙想當年人文薈萃的大里杙生活。展品:洗臉盆、雞籠、捕魚籠、謝籃、米篩等。\r\n文物提供者:民眾提供', `organizer`='臺中市立圖書館大里分館', `address`='臺中市大里區中興路一段163號', `start_date`='2025-02-07 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館大里分館', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://reurl.cc/eG7MlM', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c826b32458d4363910', '【大里分館】02/01-02/27 冬季養生，健康迎春書展', '展出冬季養生圖書，包含藥膳進補、茶飲，搭配穴道按摩、氣功、瑜珈等書籍，引導您了解養生的重要，達到強身健體的目的，讓您順應節氣做好養生保健，安穩過冬，歡迎讀者借閱！', '臺中市立圖書館大里分館', '臺中市大里區中興路一段163號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館大里分館', 24.09575742, 120.6926261, '無資料', 'https://reurl.cc/L5La83', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【大里分館】02/01-02/27 冬季養生，健康迎春書展', `description`='展出冬季養生圖書，包含藥膳進補、茶飲，搭配穴道按摩、氣功、瑜珈等書籍，引導您了解養生的重要，達到強身健體的目的，讓您順應節氣做好養生保健，安穩過冬，歡迎讀者借閱！', `organizer`='臺中市立圖書館大里分館', `address`='臺中市大里區中興路一段163號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館大里分館', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://reurl.cc/L5La83', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c926b32458d4363913', '中區分館-「再現舊城風華」攝影展', '「再現舊城風華」攝影展\r\n展出期間：2025/02/01~2025/02/27\r\n展出內容：\r\n臺中舊城區，在清治時期曾是省城的預定地，亦是日治時期台中州廳的所在，管轄中彰投，更是縱貫線上南來北往的交通樞紐，曾活躍歷史舞台，卻又一度褪去風華。這次讓我們透過老照片的紀錄，回憶、了解、認識我們舊城區的各種風華再現。', '臺中市立圖書館中區分館', '臺中市中區成功路300號7樓', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館中區分館', 24.14168566, 120.680598, '無資料', 'https://reurl.cc/NbLN0m', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中區分館-「再現舊城風華」攝影展', `description`='「再現舊城風華」攝影展\r\n展出期間：2025/02/01~2025/02/27\r\n展出內容：\r\n臺中舊城區，在清治時期曾是省城的預定地，亦是日治時期台中州廳的所在，管轄中彰投，更是縱貫線上南來北往的交通樞紐，曾活躍歷史舞台，卻又一度褪去風華。這次讓我們透過老照片的紀錄，回憶、了解、認識我們舊城區的各種風華再現。', `organizer`='臺中市立圖書館中區分館', `address`='臺中市中區成功路300號7樓', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館中區分館', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='https://reurl.cc/NbLN0m', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c926b32458d4363914', '【大里分館】2/11-2/27 靜智老師紙黏土娃娃屋特展', '"主題是尋常的居家環境，或都市轉角曾經的面貌。當歲月流轉風景不再，娃娃屋便是具象的歷史存檔，相信比文字更能讓不同的人代入。靜智老師投注個人情感留住在意的風景，讓觀看者填充情感，連結無數個別也集體的回憶。把迷你尺寸的仿真物件握在手裡，能帶來圓滿的感受。常見的玩具模型題材大都跟現實息息相關，是對生活簡化或美化的憧憬。想到這裡發現，愛玩迷你模型的大人或小孩，應該內心都藏著對世界、對生活的熱愛與失落。老師用紙黏土、布料等各種材質呈現出溫暖可愛的娃娃屋，小小的物件精美的細節，期待你來仔細的品味﹗\r\n\r\n                     \r\n', '臺中市立圖書館大里分館', '臺中市大里區中興路一段163號', '2025-02-11 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館大里分館', 24.09575742, 120.6926261, '無資料', 'https://reurl.cc/EgLYYa', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【大里分館】2/11-2/27 靜智老師紙黏土娃娃屋特展', `description`='"主題是尋常的居家環境，或都市轉角曾經的面貌。當歲月流轉風景不再，娃娃屋便是具象的歷史存檔，相信比文字更能讓不同的人代入。靜智老師投注個人情感留住在意的風景，讓觀看者填充情感，連結無數個別也集體的回憶。把迷你尺寸的仿真物件握在手裡，能帶來圓滿的感受。常見的玩具模型題材大都跟現實息息相關，是對生活簡化或美化的憧憬。想到這裡發現，愛玩迷你模型的大人或小孩，應該內心都藏著對世界、對生活的熱愛與失落。老師用紙黏土、布料等各種材質呈現出溫暖可愛的娃娃屋，小小的物件精美的細節，期待你來仔細的品味﹗\r\n\r\n                     \r\n', `organizer`='臺中市立圖書館大里分館', `address`='臺中市大里區中興路一段163號', `start_date`='2025-02-11 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館大里分館', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://reurl.cc/EgLYYa', `image_url`='[]';
