INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c926b32458d4363918', '梧棲親子館_2月份主題書展：情緒你我他', '生活中每天都會有好多不同的情緒，無時無刻伴隨在身邊。快樂、悲傷、生氣、害怕等感覺如何面對，小朋友理解嗎？透過本次書展引導讀者進入繪本故事，了解面對情緒的方式並接納自己的情緒，和他做朋友。', '臺中市立圖書館梧棲親子館', '臺中市梧棲區民生街15之77號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館梧棲親子館', 24.251815, 120.533022, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='梧棲親子館_2月份主題書展：情緒你我他', `description`='生活中每天都會有好多不同的情緒，無時無刻伴隨在身邊。快樂、悲傷、生氣、害怕等感覺如何面對，小朋友理解嗎？透過本次書展引導讀者進入繪本故事，了解面對情緒的方式並接納自己的情緒，和他做朋友。', `organizer`='臺中市立圖書館梧棲親子館', `address`='臺中市梧棲區民生街15之77號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館梧棲親子館', `latitude`=24.251815, `longitude`=120.533022, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c926b32458d436391b', '臺中市藝術亮點-李育昇服裝冠盔工藝展', '榮獲「第43屆電視金鐘獎最佳美術設計」的塑神藝術家李育昇，以創作詮釋當代社會與傳統民間信仰的融合，展現對臺灣文化的深厚熱愛。\r\n\r\n本次展覽展出〈雷火金冠〉、〈福虎金冠〉、〈鳳翎金冠〉、〈臺灣神獸-臺灣雲豹盔〉、花魁禮服與藝旦馬面裙等多元工藝創作，呈現一場精采的文化與藝術的視覺饗宴！', '臺中市中友百貨公司', '臺中市北區三民路3段161號', '2025-01-16 00:00:00', '2025-03-03 00:00:00', '臺中中友百貨公司', 24.15863985, 120.6809521, '無資料', 'https://www.chungyo.com.tw/gallery.html?id=creativityplatform', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-李育昇服裝冠盔工藝展', `description`='榮獲「第43屆電視金鐘獎最佳美術設計」的塑神藝術家李育昇，以創作詮釋當代社會與傳統民間信仰的融合，展現對臺灣文化的深厚熱愛。\r\n\r\n本次展覽展出〈雷火金冠〉、〈福虎金冠〉、〈鳳翎金冠〉、〈臺灣神獸-臺灣雲豹盔〉、花魁禮服與藝旦馬面裙等多元工藝創作，呈現一場精采的文化與藝術的視覺饗宴！', `organizer`='臺中市中友百貨公司', `address`='臺中市北區三民路3段161號', `start_date`='2025-01-16 00:00:00', `end_date`='2025-03-03 00:00:00', `location`='臺中中友百貨公司', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://www.chungyo.com.tw/gallery.html?id=creativityplatform', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6c926b32458d436391c', '且徐行—於同生知命書藝展', '剛屆知天命之年的於同生是位出生於高雄的知名書法家，其立基於傳統而譜出新意的創作在國內各獎賽中屢拔頭籌。 浸淫於書道30餘年，於同生從魏碑的渾厚圓潤氣勢出發，首創英文字母漢化變形的「英文書藝」。 他的創作游離在書法範疇邊緣，但更趨近於抽象表現主義，構成介於英文字母及漢字之間的畫面，使人如臨抽象畫般的意境。\r\n\r\n此次在靜宜大學的書藝展分成「書齋雅風」、「展廳振翅」、「陳酒新壺」三個主題，呈現於同生歷年來的書風變化以及多樣性的嘗試。 書齋是過去文人讀書的場所之外，故「書齋雅風」呈現行書對聯、行草書立軸，以及篆體隸意的斗方等作品。 「展廳振翅」主要呈現具「金石氣」的漢簡書風作品，展廳是公眾領域的場所，以「振翅」為名，應是藝術家期待自己如雄鷹般翱翔於書藝的天空。 「陳酒新壺」則透過春節十二生肖斗方書法，以及英文書法這二項最具藝術家代表性的表現，彰顯這個時代所需要的新風貌。\r\n\r\n於同生為此次展覽設定的標題取自蘇軾〈定風波〉中的「莫聽穿林打葉聲，何妨吟嘯且徐行」，他讀此詩有感，尋繹與古人拼搏而走出一條獨屬自己的書藝之道， 回應清朝初期石濤的名言「筆墨當隨時代，猶詩文風氣所轉」，內心平靜而緩步地向書藝新局前進，為書法成就當代藝術之尊而努力。\r\n\r\n#書法  #個展', '靜宜大學藝術中心', '臺中市沙鹿區臺灣大道7段200號', '2025-02-19 00:00:00', '2025-04-11 00:00:00', '靜宜大學', 24.23425212, 120.5838628, '無資料', 'https://reurl.cc/V0QZoA', '[]') ON DUPLICATE KEY UPDATE `activity_name`='且徐行—於同生知命書藝展', `description`='剛屆知天命之年的於同生是位出生於高雄的知名書法家，其立基於傳統而譜出新意的創作在國內各獎賽中屢拔頭籌。 浸淫於書道30餘年，於同生從魏碑的渾厚圓潤氣勢出發，首創英文字母漢化變形的「英文書藝」。 他的創作游離在書法範疇邊緣，但更趨近於抽象表現主義，構成介於英文字母及漢字之間的畫面，使人如臨抽象畫般的意境。\r\n\r\n此次在靜宜大學的書藝展分成「書齋雅風」、「展廳振翅」、「陳酒新壺」三個主題，呈現於同生歷年來的書風變化以及多樣性的嘗試。 書齋是過去文人讀書的場所之外，故「書齋雅風」呈現行書對聯、行草書立軸，以及篆體隸意的斗方等作品。 「展廳振翅」主要呈現具「金石氣」的漢簡書風作品，展廳是公眾領域的場所，以「振翅」為名，應是藝術家期待自己如雄鷹般翱翔於書藝的天空。 「陳酒新壺」則透過春節十二生肖斗方書法，以及英文書法這二項最具藝術家代表性的表現，彰顯這個時代所需要的新風貌。\r\n\r\n於同生為此次展覽設定的標題取自蘇軾〈定風波〉中的「莫聽穿林打葉聲，何妨吟嘯且徐行」，他讀此詩有感，尋繹與古人拼搏而走出一條獨屬自己的書藝之道， 回應清朝初期石濤的名言「筆墨當隨時代，猶詩文風氣所轉」，內心平靜而緩步地向書藝新局前進，為書法成就當代藝術之尊而努力。\r\n\r\n#書法  #個展', `organizer`='靜宜大學藝術中心', `address`='臺中市沙鹿區臺灣大道7段200號', `start_date`='2025-02-19 00:00:00', `end_date`='2025-04-11 00:00:00', `location`='靜宜大學', `latitude`=24.23425212, `longitude`=120.5838628, `ticket_price`='無資料', `source_url`='https://reurl.cc/V0QZoA', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6ca26b32458d436391e', '臺中市藝術亮點-「漢字花開．青春芳華」楊鼎献個展', '豐邑文教基金會與浩恩文教基金會攜手知名藝術家楊鼎献，於豐藝館盛大舉辦「漢字花開．青春芳華」畫展。此次展覽集結數十幅充滿生命力的小鳥「青春」系列畫作，以及24節氣意涵交織的作品，包含油畫及多媒材創作，從視覺、觸覺到心靈，帶領觀眾走入一場關於環境、文化與心靈的深層對話。', '財團法人豐邑文教基金會', '臺中市西區五權西路一段110號', '2025-01-01 00:00:00', '2025-05-13 00:00:00', '豐藝館', 24.14391082, 120.6647579, '無資料', 'https://www.facebook.com/photo/?fbid=1128664142597792&set=a.531575015640044', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-「漢字花開．青春芳華」楊鼎献個展', `description`='豐邑文教基金會與浩恩文教基金會攜手知名藝術家楊鼎献，於豐藝館盛大舉辦「漢字花開．青春芳華」畫展。此次展覽集結數十幅充滿生命力的小鳥「青春」系列畫作，以及24節氣意涵交織的作品，包含油畫及多媒材創作，從視覺、觸覺到心靈，帶領觀眾走入一場關於環境、文化與心靈的深層對話。', `organizer`='財團法人豐邑文教基金會', `address`='臺中市西區五權西路一段110號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-05-13 00:00:00', `location`='豐藝館', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.facebook.com/photo/?fbid=1128664142597792&set=a.531575015640044', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6ca26b32458d436391f', '2月主題書展', '日期:114年2/01-2/27               \r\n時間:8:30-21:00                    \r\n地點:1樓大廳                       \r\n書展名稱: 『萌寵大會』書展 \r\n生活中的瑣事，通膨的壓力，在在使人疲憊不堪，各位看倌別煩悶，梧棲分館于2/4-2/27舉辦萌寵大會書展，嘿就讓萌寵書給你帶來滿滿的活力，幫助你舒緩情緒，提升心情，2/4-2/27不要忘記來圖書館找我們喔                   \r\n\r\n日期:114年2/01-2/09               \r\n時間:8:30-21:00                   \r\n內容地點:1樓大廳                   \r\n書展名稱:『故事之島：從臺灣到波隆那』書展\r\n書展主題國為「義大利」，2025台北國際書展以「閱讀異世界」為主題，號召出版社與讀者共同進入迷人奪目的閱讀異世界!本屆書展邀請義大利為主題國。義大利以其歷史悠久且持續迷人的文化實力吸引全球關注，在出版與創作不僅名家大師輩出，亦有不容小覷的後起新秀。近年義大利積極參與台北國際書展，從國家館的設置到線上插畫展及漫畫展，展覽形式多元、內容豐富，亦曾擔任多個國際重要書展的主題國，可見其出版品深受全球出版市場與讀者的喜愛與肯定。', '臺中市立圖書館梧棲分館', '臺中市梧棲區雲集街72號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館梧棲分館', 24.24552431, 120.5301259, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月主題書展', `description`='日期:114年2/01-2/27               \r\n時間:8:30-21:00                    \r\n地點:1樓大廳                       \r\n書展名稱: 『萌寵大會』書展 \r\n生活中的瑣事，通膨的壓力，在在使人疲憊不堪，各位看倌別煩悶，梧棲分館于2/4-2/27舉辦萌寵大會書展，嘿就讓萌寵書給你帶來滿滿的活力，幫助你舒緩情緒，提升心情，2/4-2/27不要忘記來圖書館找我們喔                   \r\n\r\n日期:114年2/01-2/09               \r\n時間:8:30-21:00                   \r\n內容地點:1樓大廳                   \r\n書展名稱:『故事之島：從臺灣到波隆那』書展\r\n書展主題國為「義大利」，2025台北國際書展以「閱讀異世界」為主題，號召出版社與讀者共同進入迷人奪目的閱讀異世界!本屆書展邀請義大利為主題國。義大利以其歷史悠久且持續迷人的文化實力吸引全球關注，在出版與創作不僅名家大師輩出，亦有不容小覷的後起新秀。近年義大利積極參與台北國際書展，從國家館的設置到線上插畫展及漫畫展，展覽形式多元、內容豐富，亦曾擔任多個國際重要書展的主題國，可見其出版品深受全球出版市場與讀者的喜愛與肯定。', `organizer`='臺中市立圖書館梧棲分館', `address`='臺中市梧棲區雲集街72號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館梧棲分館', `latitude`=24.24552431, `longitude`=120.5301259, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6ca26b32458d4363920', '臺中市藝術亮點-「臺灣鄉土 ‧ 人間映像」李鳴鵰攝影展', '攝影家李鳴鵰的作品為早期臺灣庶民生活情景，留下雋永的畫面。1970 年代後，遊歷世界各地，以「日日是好日」的理念，拍攝各地民族風情與自然景觀。\r\n\r\n本展精選其關注人們生活景象的紀實攝影，以兒童、女性為素材的主題影像，以及具地域特色的建築形貌、風土民情創作。期許觀者透過珍貴的時代留影、獨特的構圖藝術，感受李鳴鵰作品中的人文意涵。', '台灣創價學會', '臺中市西屯區大容東街90號3樓', '2025-02-05 00:00:00', '2025-05-09 00:00:00', '台灣創價學會臺中藝文中心', 24.18308895, 120.6270131, '無資料', 'https://www.sokaculture.org.tw/exhibition/%E5%8F%B0%E7%81%A3%E9%84%89%E5%9C%9F-%E4%BA%BA%E9%96%93%E6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-「臺灣鄉土 ‧ 人間映像」李鳴鵰攝影展', `description`='攝影家李鳴鵰的作品為早期臺灣庶民生活情景，留下雋永的畫面。1970 年代後，遊歷世界各地，以「日日是好日」的理念，拍攝各地民族風情與自然景觀。\r\n\r\n本展精選其關注人們生活景象的紀實攝影，以兒童、女性為素材的主題影像，以及具地域特色的建築形貌、風土民情創作。期許觀者透過珍貴的時代留影、獨特的構圖藝術，感受李鳴鵰作品中的人文意涵。', `organizer`='台灣創價學會', `address`='臺中市西屯區大容東街90號3樓', `start_date`='2025-02-05 00:00:00', `end_date`='2025-05-09 00:00:00', `location`='台灣創價學會臺中藝文中心', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://www.sokaculture.org.tw/exhibition/%E5%8F%B0%E7%81%A3%E9%84%89%E5%9C%9F-%E4%BA%BA%E9%96%93%E6', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6ca26b32458d4363921', '2月 蛇來運轉年畫書畫展', '為迎接蛇年到來，本分館特別邀請書畫創作達人李文寶先生為我們揮毫創作了蛇年的吉祥畫，創作媒材為毛筆及傳統書法用具等，歡迎大家到館參觀。', '臺中市立圖書館霧峰以文分館', '臺中市霧峰區大同路8號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺中市立圖書館霧峰以文分館', 24.0615719, 120.699002, '無資料', 'https://www.library.taichung.gov.tw/public/activity2/index-1.asp?Parser=99,20,697,50,,,24108,,,,,338', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月 蛇來運轉年畫書畫展', `description`='為迎接蛇年到來，本分館特別邀請書畫創作達人李文寶先生為我們揮毫創作了蛇年的吉祥畫，創作媒材為毛筆及傳統書法用具等，歡迎大家到館參觀。', `organizer`='臺中市立圖書館霧峰以文分館', `address`='臺中市霧峰區大同路8號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市立圖書館霧峰以文分館', `latitude`=24.0615719, `longitude`=120.699002, `ticket_price`='無資料', `source_url`='https://www.library.taichung.gov.tw/public/activity2/index-1.asp?Parser=99,20,697,50,,,24108,,,,,338', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6cb26b32458d4363928', '永續生活  非你Book繪本主題書展', 'SDGs理念看似遙遠，相關議題其實持續發生在你我生活中，永續發展共有十七大永續發展目標項目，包含潔淨能源、永續城市與社區、消除飢餓、促進性別平權、減緩氣候變遷等17項，指引全球共同努力、邁向永續，不僅通過政府機關或企業主的決策，從幼童到大人，每個人經由每一次的行動，將SDGs永續發展落實在日常生活中，藉由書展更進一步認識SDGs永續發展目標。', '高雄市立圖書館總館', '高雄市六龜區2鄰光復路70號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '高雄市立圖書館六龜分館', 23.0063302, 120.6549199, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='永續生活  非你Book繪本主題書展', `description`='SDGs理念看似遙遠，相關議題其實持續發生在你我生活中，永續發展共有十七大永續發展目標項目，包含潔淨能源、永續城市與社區、消除飢餓、促進性別平權、減緩氣候變遷等17項，指引全球共同努力、邁向永續，不僅通過政府機關或企業主的決策，從幼童到大人，每個人經由每一次的行動，將SDGs永續發展落實在日常生活中，藉由書展更進一步認識SDGs永續發展目標。', `organizer`='高雄市立圖書館總館', `address`='高雄市六龜區2鄰光復路70號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='高雄市立圖書館六龜分館', `latitude`=23.0063302, `longitude`=120.6549199, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6cb26b32458d436392a', '九族櫻花祭特別加演：太鼓迎春快閃（每日3場） ', '在九族春天的櫻花祭壇上，我們要盡情的敲打春天、歌誦櫻花之美，請聽太鼓撼春的感動。\r\n本節目於戶外展演，若遇雨天則暫停演出。', '九族文化村股份有限公司', '南投縣魚池鄉', '2025-02-03 00:00:00', '2025-03-02 00:00:00', '魚池鄉（南投縣）=', 23.87601213, 120.9256736, '成人票+980;學生票+880;兒童票+780;博幼票+490', 'https://nine.com.tw/page/activity/index.aspx?kind=33', '[]') ON DUPLICATE KEY UPDATE `activity_name`='九族櫻花祭特別加演：太鼓迎春快閃（每日3場） ', `description`='在九族春天的櫻花祭壇上，我們要盡情的敲打春天、歌誦櫻花之美，請聽太鼓撼春的感動。\r\n本節目於戶外展演，若遇雨天則暫停演出。', `organizer`='九族文化村股份有限公司', `address`='南投縣魚池鄉', `start_date`='2025-02-03 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='魚池鄉（南投縣）=', `latitude`=23.87601213, `longitude`=120.9256736, `ticket_price`='成人票+980;學生票+880;兒童票+780;博幼票+490', `source_url`='https://nine.com.tw/page/activity/index.aspx?kind=33', `image_url`='[]';
