INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6cb26b32458d436392c', '九族櫻花祭特別加演：櫻花鄉情民歌（每日1場） ', '原住民的歌聲是上帝親吻的恩賜，原住民原鄉傳唱的民謠是天籟的美音，每天下午在櫻花湖畔，一首接一首的原住民美麗的歌聲將陪伴你，共度閒情的櫻花季節。\r\n說明事項 : 本節目於戶外展演，若遇雨天則暫停演出。', '九族文化村股份有限公司', '南投縣魚池鄉', '2025-02-03 00:00:00', '2025-03-02 00:00:00', '魚池鄉（南投縣）=', 23.87601213, 120.9256736, '成人票+980;學生票+880;兒童票+780;博幼票+490', 'https://nine.com.tw/page/activity/index.aspx?kind=33', '[]') ON DUPLICATE KEY UPDATE `activity_name`='九族櫻花祭特別加演：櫻花鄉情民歌（每日1場） ', `description`='原住民的歌聲是上帝親吻的恩賜，原住民原鄉傳唱的民謠是天籟的美音，每天下午在櫻花湖畔，一首接一首的原住民美麗的歌聲將陪伴你，共度閒情的櫻花季節。\r\n說明事項 : 本節目於戶外展演，若遇雨天則暫停演出。', `organizer`='九族文化村股份有限公司', `address`='南投縣魚池鄉', `start_date`='2025-02-03 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='魚池鄉（南投縣）=', `latitude`=23.87601213, `longitude`=120.9256736, `ticket_price`='成人票+980;學生票+880;兒童票+780;博幼票+490', `source_url`='https://nine.com.tw/page/activity/index.aspx?kind=33', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6cb26b32458d436392d', '九族櫻花祭特別加演：夜櫻夜夜點燈儀式（每日1場） ', '邀您提著燈籠一起來參加點燈儀式，將由大祭師與舞者帶領遊客參與，一起為夜櫻的活動點燈揭開璀璨的夜櫻。\r\n\r\n九族夜櫻款-提燈籠賞夜櫻\r\n九族夜櫻款就是提燈籠賞夜櫻。請來領取免費燈籠，跟著大祭師點燈後、和舞者一起巡遊到櫻花林。\r\n提燈籠賞夜櫻的台灣第一夜櫻，提了燈籠，你就是夜櫻，大家都是夜櫻的一部分。\r\n免費燈籠發放：平日每天前100名、假日前200名，送完截止。\r\n\r\n說明事項：本節目於戶外展演，若遇雨天則暫停演出。', '九族文化村股份有限公司', '南投縣魚池鄉', '2025-02-03 00:00:00', '2025-03-02 00:00:00', '魚池鄉（南投縣）=', 23.87601213, 120.9256736, '成人票+980;學生票+880;兒童票+780;博幼票+490', 'https://nine.com.tw/page/activity/index.aspx?kind=33', '[]') ON DUPLICATE KEY UPDATE `activity_name`='九族櫻花祭特別加演：夜櫻夜夜點燈儀式（每日1場） ', `description`='邀您提著燈籠一起來參加點燈儀式，將由大祭師與舞者帶領遊客參與，一起為夜櫻的活動點燈揭開璀璨的夜櫻。\r\n\r\n九族夜櫻款-提燈籠賞夜櫻\r\n九族夜櫻款就是提燈籠賞夜櫻。請來領取免費燈籠，跟著大祭師點燈後、和舞者一起巡遊到櫻花林。\r\n提燈籠賞夜櫻的台灣第一夜櫻，提了燈籠，你就是夜櫻，大家都是夜櫻的一部分。\r\n免費燈籠發放：平日每天前100名、假日前200名，送完截止。\r\n\r\n說明事項：本節目於戶外展演，若遇雨天則暫停演出。', `organizer`='九族文化村股份有限公司', `address`='南投縣魚池鄉', `start_date`='2025-02-03 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='魚池鄉（南投縣）=', `latitude`=23.87601213, `longitude`=120.9256736, `ticket_price`='成人票+980;學生票+880;兒童票+780;博幼票+490', `source_url`='https://nine.com.tw/page/activity/index.aspx?kind=33', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6cb26b32458d436392e', '九族櫻花祭特別加演：夜舞祭（每日1場） ', '夜櫻期間限定的表演節目，玩了一整天的遊客，請欣賞最後一場精彩的異國風情與火舞演出。\r\n說明事項：本節目於戶外展演，若遇雨天則暫停演出。', '九族文化村股份有限公司', '南投縣魚池鄉', '2025-02-03 00:00:00', '2025-03-02 00:00:00', '魚池鄉（南投縣）=', 23.87601213, 120.9256736, '成人票+980;學生票+880;兒童票+780;博幼票+490', 'https://nine.com.tw/page/activity/index.aspx?kind=33', '[]') ON DUPLICATE KEY UPDATE `activity_name`='九族櫻花祭特別加演：夜舞祭（每日1場） ', `description`='夜櫻期間限定的表演節目，玩了一整天的遊客，請欣賞最後一場精彩的異國風情與火舞演出。\r\n說明事項：本節目於戶外展演，若遇雨天則暫停演出。', `organizer`='九族文化村股份有限公司', `address`='南投縣魚池鄉', `start_date`='2025-02-03 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='魚池鄉（南投縣）=', `latitude`=23.87601213, `longitude`=120.9256736, `ticket_price`='成人票+980;學生票+880;兒童票+780;博幼票+490', `source_url`='https://nine.com.tw/page/activity/index.aspx?kind=33', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6cb26b32458d4363931', '九族櫻花祭：櫻花茶會《帶有咖啡、酒香的櫻花茶席》（2場次）', '李宜玲-烏克麗麗琴演奏(貞藏、小瓶子主場)\r\n\r\n活動辦法\r\n開放現場遊客免費入席，歡迎預約訂保留席(提早10分鐘報到入席)。\r\n請自備飲杯，現場販售櫻花祭25回花形紀念茶杯每只100元。\r\n歡迎線上報名。\r\n', '九族文化村股份有限公司', '南投縣魚池鄉', '2025-03-07 00:00:00', '2025-03-07 00:00:00', '魚池鄉（南投縣）=', 23.87601213, 120.9256736, '成人票+980;學生票+880;兒童票+780;博幼票+490', 'https://nine.com.tw/page/activity/index.aspx?kind=33', '[]') ON DUPLICATE KEY UPDATE `activity_name`='九族櫻花祭：櫻花茶會《帶有咖啡、酒香的櫻花茶席》（2場次）', `description`='李宜玲-烏克麗麗琴演奏(貞藏、小瓶子主場)\r\n\r\n活動辦法\r\n開放現場遊客免費入席，歡迎預約訂保留席(提早10分鐘報到入席)。\r\n請自備飲杯，現場販售櫻花祭25回花形紀念茶杯每只100元。\r\n歡迎線上報名。\r\n', `organizer`='九族文化村股份有限公司', `address`='南投縣魚池鄉', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-07 00:00:00', `location`='魚池鄉（南投縣）=', `latitude`=23.87601213, `longitude`=120.9256736, `ticket_price`='成人票+980;學生票+880;兒童票+780;博幼票+490', `source_url`='https://nine.com.tw/page/activity/index.aspx?kind=33', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6cb26b32458d4363933', '九族櫻花祭：櫻花大道召集令-櫻花戰國武士、太鼓行列遊行（2場） ', '富士櫻太鼓弄春\r\n盛開的櫻花大道就是一個大舞台，邀請大家一起來櫻花樹下野餐花見，欣賞舞之鼓、鳳天神鼓雙團演出。\r\n櫻花戰國武士、太鼓行列遊行\r\n邀請台灣武士甲冑隊在櫻花大道遊行，純粹日本櫻花祭的特色風格，不用到日本也看得到。', '九族文化村股份有限公司', '南投縣魚池鄉', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '魚池鄉（南投縣）=', 23.87601213, 120.9256736, '成人票+980;學生票+880;兒童票+780;博幼票+490', 'https://nine.com.tw/page/activity/index.aspx?kind=33', '[]') ON DUPLICATE KEY UPDATE `activity_name`='九族櫻花祭：櫻花大道召集令-櫻花戰國武士、太鼓行列遊行（2場） ', `description`='富士櫻太鼓弄春\r\n盛開的櫻花大道就是一個大舞台，邀請大家一起來櫻花樹下野餐花見，欣賞舞之鼓、鳳天神鼓雙團演出。\r\n櫻花戰國武士、太鼓行列遊行\r\n邀請台灣武士甲冑隊在櫻花大道遊行，純粹日本櫻花祭的特色風格，不用到日本也看得到。', `organizer`='九族文化村股份有限公司', `address`='南投縣魚池鄉', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='魚池鄉（南投縣）=', `latitude`=23.87601213, `longitude`=120.9256736, `ticket_price`='成人票+980;學生票+880;兒童票+780;博幼票+490', `source_url`='https://nine.com.tw/page/activity/index.aspx?kind=33', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6cb26b32458d4363934', '柳營牛樂園_光影藝術迎新年@柳營區公所', '臺南市柳營區公所為迎接農曆年到來，以「柳營牛樂園」為主題，結合地方特色與美學創意在乳香公園設置獨特燈飾造景_動物造型資源回收創作藝術品，營造充滿童趣的歡樂氛圍，展現乳香之鄉新魅力。', '臺南市柳營區公所', '臺南市柳營區', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '柳營區（臺南市）=', 23.26887001, 120.3549205, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='柳營牛樂園_光影藝術迎新年@柳營區公所', `description`='臺南市柳營區公所為迎接農曆年到來，以「柳營牛樂園」為主題，結合地方特色與美學創意在乳香公園設置獨特燈飾造景_動物造型資源回收創作藝術品，營造充滿童趣的歡樂氛圍，展現乳香之鄉新魅力。', `organizer`='臺南市柳營區公所', `address`='臺南市柳營區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='柳營區（臺南市）=', `latitude`=23.26887001, `longitude`=120.3549205, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6792c6cc26b32458d436393c', '回家:小林村的故事', '「回家—小林村的故事」常設展，展覽內容包括記憶中的家、消失的家園、組合屋的日子、新家生活等四單元，透過口述記憶影像、文物、模型，搭配互動遊戲，以尋根探索型態呈現早期文獻記錄為「四社平埔」的大武壠族人如何來到這片土地建立家園、延續傳統；並刻劃經歷殤災的大武壠後裔如何展現堅韌意志聯手重建家園。希望藉由展覽呈現這塊土地的故事、經由村民尋覓那份歸鄉返家的情感，帶領大家一同探尋先民在這塊土地生活的痕跡，和逐漸被遺忘、消逝的的傳統文化，娓娓道出小林村從風災前、歷經災變到重建的故事。', '高雄市政府文化局', '高雄市甲仙區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '甲仙區（高雄市）=', 23.11654995, 120.6232895, '無資料', 'https://xiaolin.khcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='回家:小林村的故事', `description`='「回家—小林村的故事」常設展，展覽內容包括記憶中的家、消失的家園、組合屋的日子、新家生活等四單元，透過口述記憶影像、文物、模型，搭配互動遊戲，以尋根探索型態呈現早期文獻記錄為「四社平埔」的大武壠族人如何來到這片土地建立家園、延續傳統；並刻劃經歷殤災的大武壠後裔如何展現堅韌意志聯手重建家園。希望藉由展覽呈現這塊土地的故事、經由村民尋覓那份歸鄉返家的情感，帶領大家一同探尋先民在這塊土地生活的痕跡，和逐漸被遺忘、消逝的的傳統文化，娓娓道出小林村從風災前、歷經災變到重建的故事。', `organizer`='高雄市政府文化局', `address`='高雄市甲仙區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='甲仙區（高雄市）=', `latitude`=23.11654995, `longitude`=120.6232895, `ticket_price`='無資料', `source_url`='https://xiaolin.khcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679352b907f3fcdc7f9ef391', '2025「盛世壁藏～唐代壁畫文化特展．三部曲」', '歷經5年滋養茁壯，2025「盛世壁藏～唐代壁畫文化特展」將迎來三部曲最終章。三部曲以「青春年華」為題，洋溢跨越千年時空的青春氣息，獲得觀眾的一致好評。\r\n今年，新春伊始，三部曲特別加碼首度展出享有「網紅壁畫」美名的「舞女圖」，以及唐代貴族出遊的「出行儀仗圖」！前者在西安展出時，以其跨時空的舞姿吸引無數觀眾前來打卡，千萬不可錯過！\r\n展覽分為五個單元：\r\n夢想之都\r\n錦瑟年華\r\n少年歡歌\r\n逐夢青雲\r\n青春之夢\r\n以不同的視角一窺唐代青年男女的青春歲月，展覽之外還有豐富有趣的體驗活動，身為唐朝文青，你不能不知道的展覽亮點\r\n穿上唐代的優雅與詩意：「漢服體驗」\r\n勾勒出絕美壁畫作品：「壁畫臨摹牆」\r\n皇子歸來，奪回王權：必玩「解謎遊戲」\r\n沉浸現場中豐富有趣的展覽活動\r\n乾貨滿滿的各式工作坊與藝文講座\r\n【展覽資訊】\r\n臺中站\r\n東海大學 藝術中心\r\n2/21（五）～3/22（五）\r\n週一到週六 12:00-18:00（週日及例假日不開放）\r\n新北站\r\n國立台灣藝術大學 有章博物館大觀藝廊及真善美藝廊\r\n3/26（三）～4/12（六）\r\n週一到週六 09:00-17:00（週日及例假日不開放）\r\n新竹站\r\n國立陽明交通大學 藝文中心\r\n4/17（四）～5/16（五）\r\n週一到週五 10:30-18:30\r\n週六       10:30-16:30（週日及例假日不開放）\r\n2025盛世壁藏活動官網\r\nhttps://tdbh.hanwei-hanya.com\r\n', '社團法人中華翰維文化推廣協會', '臺中市西屯區台灣大道四段1727號', '2025-02-21 00:00:00', '2025-03-22 00:00:00', '臺中東海大學 藝術中心', 24.18308895, 120.6270131, '無資料', 'https://tdbh.hanwei-hanya.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025「盛世壁藏～唐代壁畫文化特展．三部曲」', `description`='歷經5年滋養茁壯，2025「盛世壁藏～唐代壁畫文化特展」將迎來三部曲最終章。三部曲以「青春年華」為題，洋溢跨越千年時空的青春氣息，獲得觀眾的一致好評。\r\n今年，新春伊始，三部曲特別加碼首度展出享有「網紅壁畫」美名的「舞女圖」，以及唐代貴族出遊的「出行儀仗圖」！前者在西安展出時，以其跨時空的舞姿吸引無數觀眾前來打卡，千萬不可錯過！\r\n展覽分為五個單元：\r\n夢想之都\r\n錦瑟年華\r\n少年歡歌\r\n逐夢青雲\r\n青春之夢\r\n以不同的視角一窺唐代青年男女的青春歲月，展覽之外還有豐富有趣的體驗活動，身為唐朝文青，你不能不知道的展覽亮點\r\n穿上唐代的優雅與詩意：「漢服體驗」\r\n勾勒出絕美壁畫作品：「壁畫臨摹牆」\r\n皇子歸來，奪回王權：必玩「解謎遊戲」\r\n沉浸現場中豐富有趣的展覽活動\r\n乾貨滿滿的各式工作坊與藝文講座\r\n【展覽資訊】\r\n臺中站\r\n東海大學 藝術中心\r\n2/21（五）～3/22（五）\r\n週一到週六 12:00-18:00（週日及例假日不開放）\r\n新北站\r\n國立台灣藝術大學 有章博物館大觀藝廊及真善美藝廊\r\n3/26（三）～4/12（六）\r\n週一到週六 09:00-17:00（週日及例假日不開放）\r\n新竹站\r\n國立陽明交通大學 藝文中心\r\n4/17（四）～5/16（五）\r\n週一到週五 10:30-18:30\r\n週六       10:30-16:30（週日及例假日不開放）\r\n2025盛世壁藏活動官網\r\nhttps://tdbh.hanwei-hanya.com\r\n', `organizer`='社團法人中華翰維文化推廣協會', `address`='臺中市西屯區台灣大道四段1727號', `start_date`='2025-02-21 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺中東海大學 藝術中心', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://tdbh.hanwei-hanya.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6793c7a726b32458d436393f', '2025陳谷榕薩克斯風的奇幻旅程V皮亞佐拉的天使與惡魔', '無資料', '無資料', '高雄市鳳山區三多一路1號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '衛武營國家藝術文化中心表演廳', 22.62301792, 120.34243412, '無資料', 'https://www.opentix.life/program/1871477453868994561', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025陳谷榕薩克斯風的奇幻旅程V皮亞佐拉的天使與惡魔', `description`='無資料', `organizer`='無資料', `address`='高雄市鳳山區三多一路1號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='衛武營國家藝術文化中心表演廳', `latitude`=22.62301792, `longitude`=120.34243412, `ticket_price`='無資料', `source_url`='https://www.opentix.life/program/1871477453868994561', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679413c126b32458d4363940', '羽化的百步蛇─熊鷹講座', '熊鷹是臺灣最壯碩的猛禽，翼展長可達160公分，體重可達3公斤，生性隱密，利用原始森林棲地，是食物鏈中的頂級消費者，在森林生態系扮演重要角色。因棲地喪失及獵捕壓力，全臺族群量約500對左右，是瀕臨絕種保育類野生動物。\n\n熊鷹亞成鳥飛羽上的三角形斑與百步蛇斑紋相似，排灣族及魯凱族人將百步蛇視為祖靈或守護神，在傳說中熊鷹即為羽化的百步蛇。另根據學者胡台麗老師在來義鄉古樓村的田調，紀錄著排灣族人、百步蛇及熊鷹轉生的傳說。\n\n臺史博「我走‧我尋：當代原住民族移動記事」特展中可見多處百步蛇圖騰，其中「從山裡來的魯凱人」單元中展示貴族婦女傳統服飾，羽飾即為熊鷹羽毛，而館藏中有日本時代排灣族頭目配戴熊鷹羽毛頭飾的照片。傳統上排灣及魯凱族配戴熊鷹羽毛象徵身分、榮耀，非「一般」人可配戴。但在傳統文化漸勢微下，羽飾規範鬆散，羽毛逐漸商品化，使得熊鷹遭受巨大的獵捕壓力。\n\n孫元勳教授將由熊鷹與原住民族的關係切入，介紹近年研究的熊鷹生態、保育情形，以及期望減少熊鷹獵捕壓力而在部落推廣的仿真羽毛。\n\n透過講座認識熊鷹及象徵的文化意涵，共感我們與臺灣這塊土地上所有原生物種共存、共好(aka永續)的重要性。\n\n \n\n\n	講師：國立屏東科技大學野生動物保育研究所 孫元勳特聘研究員(野生動物保育研究所教授退休)\n	時間：114年3月8日(週六) 13:30-16:00 (13:15-13:30報到)\n	地點：國立臺灣歷史博物館 展示教育大樓階梯教室\n	費用：免費\n	備註：活動準時開始，敬請提前報到入座\n\n\n ', '國立臺灣歷史博物館', '709  臺南市安南區長和路1段250號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '國立臺灣歷史博物館展示教育大樓階梯教室', 23.0583737, 120.2349839, '無資料', 'https://event.culture.tw/mocweb/reg/NMTH/Detail.init.ctr?actId=50028', '[]') ON DUPLICATE KEY UPDATE `activity_name`='羽化的百步蛇─熊鷹講座', `description`='熊鷹是臺灣最壯碩的猛禽，翼展長可達160公分，體重可達3公斤，生性隱密，利用原始森林棲地，是食物鏈中的頂級消費者，在森林生態系扮演重要角色。因棲地喪失及獵捕壓力，全臺族群量約500對左右，是瀕臨絕種保育類野生動物。\n\n熊鷹亞成鳥飛羽上的三角形斑與百步蛇斑紋相似，排灣族及魯凱族人將百步蛇視為祖靈或守護神，在傳說中熊鷹即為羽化的百步蛇。另根據學者胡台麗老師在來義鄉古樓村的田調，紀錄著排灣族人、百步蛇及熊鷹轉生的傳說。\n\n臺史博「我走‧我尋：當代原住民族移動記事」特展中可見多處百步蛇圖騰，其中「從山裡來的魯凱人」單元中展示貴族婦女傳統服飾，羽飾即為熊鷹羽毛，而館藏中有日本時代排灣族頭目配戴熊鷹羽毛頭飾的照片。傳統上排灣及魯凱族配戴熊鷹羽毛象徵身分、榮耀，非「一般」人可配戴。但在傳統文化漸勢微下，羽飾規範鬆散，羽毛逐漸商品化，使得熊鷹遭受巨大的獵捕壓力。\n\n孫元勳教授將由熊鷹與原住民族的關係切入，介紹近年研究的熊鷹生態、保育情形，以及期望減少熊鷹獵捕壓力而在部落推廣的仿真羽毛。\n\n透過講座認識熊鷹及象徵的文化意涵，共感我們與臺灣這塊土地上所有原生物種共存、共好(aka永續)的重要性。\n\n \n\n\n	講師：國立屏東科技大學野生動物保育研究所 孫元勳特聘研究員(野生動物保育研究所教授退休)\n	時間：114年3月8日(週六) 13:30-16:00 (13:15-13:30報到)\n	地點：國立臺灣歷史博物館 展示教育大樓階梯教室\n	費用：免費\n	備註：活動準時開始，敬請提前報到入座\n\n\n ', `organizer`='國立臺灣歷史博物館', `address`='709  臺南市安南區長和路1段250號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='國立臺灣歷史博物館展示教育大樓階梯教室', `latitude`=23.0583737, `longitude`=120.2349839, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMTH/Detail.init.ctr?actId=50028', `image_url`='[]';
