INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679413d726b32458d4363942', '2025 年「國美進駐」國際駐館人員公開甄選', '一、主辦：國立臺灣美術館（以下簡稱本館）。\n\n \n\n二、甄選對象須符合以下所有資格：\n\n（一）不具備中華民國國籍之藝術家、策展人、藝術史學者、評論家、理論家與美術館專業人士。\n\n（二）非在學學生。\n\n（三）須對本館、國美典藏、臺灣的文化與藝術有一定的認知與理解。\n\n（四）具五年以上藝術、研究等相關工作經歷，且最近二年內未曾接受本館支應進駐本館者。\n\n（五）具備英文或中文語言基本溝通能力者。\n\n \n\n三、甄選名額：\n\n正取 1 名、備取 2 名。\n\n \n\n四、進駐時段與時程：\n\n2025 年 9月 15 日至 11 月 18 日，進駐至少 30天，至多  65 天。\n\n \n\n五、 本館支應項目：\n\n（一）獲選者由出發地至臺灣之來回經濟艙機票一張。\n\n（二）機場至本館來回一趟之大眾運輸交通費用。\n\n（三）保險費。\n\n（四）進駐經費。\n\n（五）免費工作室一間。\n\n（六）得依駐館計畫申請進入典藏庫房觀察相關之典藏品。\n\n（七）本館藝術圖書中心之使用權。\n\n \n\n六、評審項目.\n\n1. 進駐計畫與本館甄選重點的符合度與計畫可行性及完整度（40%） \n\n     *本館甄選重點: \n\nA. 本館典藏品。(請參考國美典藏 https://ntmofa-collections.ntmofa.gov.tw/en/default.aspx) \n\nB. 臺灣藝術史。\n\nC. 臺灣藝術家。\n\nD. 科技藝術。\n\n2. 藝文推廣計畫或公開發表可行性與完整度（25%）。\n\n3. 申請人履歷與著作/作品 (20%)。\n\n4. 現場簡報與答詢（15%）。\n\n \n\n七、如何申請\n\n請參考附件中「國美進駐計畫駐館人員申請書」與「申請人簡介、履歷與進駐計畫內容」需求表。\n\n=================================================================\n\n***更多資訊請詳見附件簡章\n\n ', '國立臺灣美術館', '403  臺中市西區五權西路一段2號', '2025-03-01 00:00:00', '2025-03-24 00:00:00', '國立臺灣美術館', 24.1411826, 120.6633086, '無資料', 'https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=54928', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 年「國美進駐」國際駐館人員公開甄選', `description`='一、主辦：國立臺灣美術館（以下簡稱本館）。\n\n \n\n二、甄選對象須符合以下所有資格：\n\n（一）不具備中華民國國籍之藝術家、策展人、藝術史學者、評論家、理論家與美術館專業人士。\n\n（二）非在學學生。\n\n（三）須對本館、國美典藏、臺灣的文化與藝術有一定的認知與理解。\n\n（四）具五年以上藝術、研究等相關工作經歷，且最近二年內未曾接受本館支應進駐本館者。\n\n（五）具備英文或中文語言基本溝通能力者。\n\n \n\n三、甄選名額：\n\n正取 1 名、備取 2 名。\n\n \n\n四、進駐時段與時程：\n\n2025 年 9月 15 日至 11 月 18 日，進駐至少 30天，至多  65 天。\n\n \n\n五、 本館支應項目：\n\n（一）獲選者由出發地至臺灣之來回經濟艙機票一張。\n\n（二）機場至本館來回一趟之大眾運輸交通費用。\n\n（三）保險費。\n\n（四）進駐經費。\n\n（五）免費工作室一間。\n\n（六）得依駐館計畫申請進入典藏庫房觀察相關之典藏品。\n\n（七）本館藝術圖書中心之使用權。\n\n \n\n六、評審項目.\n\n1. 進駐計畫與本館甄選重點的符合度與計畫可行性及完整度（40%） \n\n     *本館甄選重點: \n\nA. 本館典藏品。(請參考國美典藏 https://ntmofa-collections.ntmofa.gov.tw/en/default.aspx) \n\nB. 臺灣藝術史。\n\nC. 臺灣藝術家。\n\nD. 科技藝術。\n\n2. 藝文推廣計畫或公開發表可行性與完整度（25%）。\n\n3. 申請人履歷與著作/作品 (20%)。\n\n4. 現場簡報與答詢（15%）。\n\n \n\n七、如何申請\n\n請參考附件中「國美進駐計畫駐館人員申請書」與「申請人簡介、履歷與進駐計畫內容」需求表。\n\n=================================================================\n\n***更多資訊請詳見附件簡章\n\n ', `organizer`='國立臺灣美術館', `address`='403  臺中市西區五權西路一段2號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-24 00:00:00', `location`='國立臺灣美術館', `latitude`=24.1411826, `longitude`=120.6633086, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=54928', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679413d826b32458d4363943', '「蛇來運轉好運來」系列活動', ' \n\n蛇是種動物，也不只是種動物。在漢人習俗中，牠可以是十二生肖之一；在原住民神話中，牠也可以是信仰的象徵；在西方預言故事中，牠亦可以成為警醒世人的主角。配合蛇年的到來，除規劃「蛇」的主題書區外，也將透過繪本故事活動，引導小朋友發掘與認識蛇的百百種面向。\n\n \n\n一、活動地點：本館兒童繪本區\n\n二、活動對象：親子家庭觀眾\n\n三、活動人數：親子共50位(網路預約人數30人、現場抽號碼牌人數20人)\n\n四、報名方式：活動前14日開放預約，至遲於參觀前2日完成，請至「兒童繪本區入場預約申請」\n\n五、活動內容：\n\n\n	\n		\n			\n			序號\n			\n			\n			日期/時間\n			\n			\n			活動名稱\n			\n			\n			活動內容\n			\n			\n			講師\n			\n		\n		\n			\n			1\n			\n			\n			02/08(六)\n\n			11：00-12：00\n			\n			\n			十二小守護過新年：起飛吧！小螣蛇\n			\n			\n			繪本故事導賞\n\n			手作DIY\n			\n			\n			李翠玲\n			\n		\n		\n			\n			2\n			\n			\n			02/15(六) \n\n			15：00-16：00\n			\n			\n			小蛇古斯想要腿\n			\n			\n			歐陽安褀\n			\n		\n		\n			\n			3\n			\n			\n			02/16 (日) \n\n			15：00-16：00\n			\n			\n			十二生肖的故事\n			\n			\n			陳麗華\n			\n		\n		\n			\n			4\n			\n			\n			03/02(日) \n\n			15：00-16：00\n			\n			\n			世界上最棒的蛇\n			\n			\n			劉明珠\n			\n		\n		\n			\n			5\n			\n			\n			03/15(六) \n\n			11：00-12：00\n			\n			\n			太陽卵.陶甕.百步蛇\n			\n			\n			李慧敏\n			\n		\n		\n			\n			6\n			\n			\n			03/23(日) \n\n			15：00-16：00\n			\n			\n			小蛇散步\n			\n			\n			詹季銀\n			\n		\n	\n\n\n ', '國立臺灣美術館', '403  臺中市西區535五權西路一段2號', '2025-02-08 00:00:00', '2025-03-23 00:00:00', '兒童繪本區Picture Book Area', 24.1396657, 120.665874, '無資料', 'https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=54930', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「蛇來運轉好運來」系列活動', `description`=' \n\n蛇是種動物，也不只是種動物。在漢人習俗中，牠可以是十二生肖之一；在原住民神話中，牠也可以是信仰的象徵；在西方預言故事中，牠亦可以成為警醒世人的主角。配合蛇年的到來，除規劃「蛇」的主題書區外，也將透過繪本故事活動，引導小朋友發掘與認識蛇的百百種面向。\n\n \n\n一、活動地點：本館兒童繪本區\n\n二、活動對象：親子家庭觀眾\n\n三、活動人數：親子共50位(網路預約人數30人、現場抽號碼牌人數20人)\n\n四、報名方式：活動前14日開放預約，至遲於參觀前2日完成，請至「兒童繪本區入場預約申請」\n\n五、活動內容：\n\n\n	\n		\n			\n			序號\n			\n			\n			日期/時間\n			\n			\n			活動名稱\n			\n			\n			活動內容\n			\n			\n			講師\n			\n		\n		\n			\n			1\n			\n			\n			02/08(六)\n\n			11：00-12：00\n			\n			\n			十二小守護過新年：起飛吧！小螣蛇\n			\n			\n			繪本故事導賞\n\n			手作DIY\n			\n			\n			李翠玲\n			\n		\n		\n			\n			2\n			\n			\n			02/15(六) \n\n			15：00-16：00\n			\n			\n			小蛇古斯想要腿\n			\n			\n			歐陽安褀\n			\n		\n		\n			\n			3\n			\n			\n			02/16 (日) \n\n			15：00-16：00\n			\n			\n			十二生肖的故事\n			\n			\n			陳麗華\n			\n		\n		\n			\n			4\n			\n			\n			03/02(日) \n\n			15：00-16：00\n			\n			\n			世界上最棒的蛇\n			\n			\n			劉明珠\n			\n		\n		\n			\n			5\n			\n			\n			03/15(六) \n\n			11：00-12：00\n			\n			\n			太陽卵.陶甕.百步蛇\n			\n			\n			李慧敏\n			\n		\n		\n			\n			6\n			\n			\n			03/23(日) \n\n			15：00-16：00\n			\n			\n			小蛇散步\n			\n			\n			詹季銀\n			\n		\n	\n\n\n ', `organizer`='國立臺灣美術館', `address`='403  臺中市西區535五權西路一段2號', `start_date`='2025-02-08 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='兒童繪本區Picture Book Area', `latitude`=24.1396657, `longitude`=120.665874, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=54930', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a726b32458d4363948', '【石岡分館】《漫游客庄閱新春》－2月書展', '「漫游客庄閱新春」書展\r\n前進浪漫台三線,本館書展區展出客家文化、石岡物產及新年書籍,處處都蘊藏著豐富的客家閱讀氣息。', '臺中市立圖書館石岡分館', '臺中市石岡區明德路175號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館石岡分館', 24.26493299, 120.7903822, '無資料', 'https://www.facebook.com/share/1BHAJw9Sdy/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【石岡分館】《漫游客庄閱新春》－2月書展', `description`='「漫游客庄閱新春」書展\r\n前進浪漫台三線,本館書展區展出客家文化、石岡物產及新年書籍,處處都蘊藏著豐富的客家閱讀氣息。', `organizer`='臺中市立圖書館石岡分館', `address`='臺中市石岡區明德路175號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館石岡分館', `latitude`=24.26493299, `longitude`=120.7903822, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/1BHAJw9Sdy/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a726b32458d4363949', '張淑智老師水彩個展~餐桌上的藝術', '本所藝文展覽自114年1月2日起展出張淑智老師水彩個展，從生活中發現平凡之美，平凡的餐桌上，也能展現出美麗的藝術喔！希望大家也能欣賞自己家中餐桌上的藝術之美~', '臺中市東區戶政事務所', '臺中市東區', '2025-01-02 00:00:00', '2025-04-18 00:00:00', '東區（臺中市）=', 24.13733209, 120.6970865, '無資料', 'https://reurl.cc/ZZ4LnW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='張淑智老師水彩個展~餐桌上的藝術', `description`='本所藝文展覽自114年1月2日起展出張淑智老師水彩個展，從生活中發現平凡之美，平凡的餐桌上，也能展現出美麗的藝術喔！希望大家也能欣賞自己家中餐桌上的藝術之美~', `organizer`='臺中市東區戶政事務所', `address`='臺中市東區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-04-18 00:00:00', `location`='東區（臺中市）=', `latitude`=24.13733209, `longitude`=120.6970865, `ticket_price`='無資料', `source_url`='https://reurl.cc/ZZ4LnW', `image_url`='[]';
