INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a726b32458d436394d', '2月主題書展(2場)', '1F-【元宵萬花筒】書展\r\n展出元宵燈謎相關圖書，歡迎到館閱覽。\r\n2F-【燃脂健身之道】書展\r\n展出健身相關圖書，歡迎到館閱覽。', '臺中市立圖書館南屯分館', '臺中市南屯區大墩12街361號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館南屯分館', 24.14165524, 120.6177379, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月主題書展(2場)', `description`='1F-【元宵萬花筒】書展\r\n展出元宵燈謎相關圖書，歡迎到館閱覽。\r\n2F-【燃脂健身之道】書展\r\n展出健身相關圖書，歡迎到館閱覽。', `organizer`='臺中市立圖書館南屯分館', `address`='臺中市南屯區大墩12街361號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館南屯分館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a726b32458d436394f', '無資料', '對於袋熊瑪琪來說，生活變得有點煩人了，雖然天堂市的犯罪率創下了歷史新低，但她現在卻比以往更忙，整天忙著疏通下水道和報稅，而不是拯救世界，這不是她想要的生活！當一個邪惡的科技天才威脅要把整個城市困在一個「完美」的虛擬世界時，瑪琪和阿蜜再次聯手出擊，但這會是這對充滿活力的搭檔的最後一搏嗎？快一起來看看吧~', '臺中市立圖書館南屯分館', '臺中市南屯區大墩12街361號', '臺中市立圖書館南屯分館', 24.14165524, 120.6177379, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='對於袋熊瑪琪來說，生活變得有點煩人了，雖然天堂市的犯罪率創下了歷史新低，但她現在卻比以往更忙，整天忙著疏通下水道和報稅，而不是拯救世界，這不是她想要的生活！當一個邪惡的科技天才威脅要把整個城市困在一個「完美」的虛擬世界時，瑪琪和阿蜜再次聯手出擊，但這會是這對充滿活力的搭檔的最後一搏嗎？快一起來看看吧~', `organizer`='臺中市立圖書館南屯分館', `address`='臺中市南屯區大墩12街361號', `location`='臺中市立圖書館南屯分館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a726b32458d4363950', '無資料', '新年新氣象，本次展覽邀請美國禪繞畫認證講師沐風老師，以「花圈」為主題，繪畫數幅禪繞畫作品，作品筆觸呈現豐富細膩的用心，在年節期間一起來南屯分館欣賞這些作品吧！', '臺中市立圖書館南屯分館', '臺中市南屯區大墩12街361號', '臺中市立圖書館南屯分館', 24.14165524, 120.6177379, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='新年新氣象，本次展覽邀請美國禪繞畫認證講師沐風老師，以「花圈」為主題，繪畫數幅禪繞畫作品，作品筆觸呈現豐富細膩的用心，在年節期間一起來南屯分館欣賞這些作品吧！', `organizer`='臺中市立圖書館南屯分館', `address`='臺中市南屯區大墩12街361號', `location`='臺中市立圖書館南屯分館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
