INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a926b32458d436395f', '114年頭份市客語中高級、中級及初級認證班', '招生對象：\r\n客語初級班／報考114年客語初級認證之學員。正取15人、備取5人。\r\n客語中高班／報考114年客語中高級認證之學員。正取15人、備取5人。\r\n報名時間：\r\n客語初級班／即日起至114.04.10(四)17時止\r\n客語中高班／即日起至114.05.10(六)17時止\r\n填妥報名表 寄至電子郵件：lin39828@gmail.com 收件人：林火清\r\n保證金與報名表必須二者完成手續，並致電0937-271265 林火清確認收到，給予上課編號後才算完成報名。\r\n報名截止若未達15人，無法開課時，會通知所繳保證金無息退還。', '林火清', '苗栗縣頭份市', '2025-04-29 00:00:00', '2025-09-25 00:00:00', '頭份市（苗栗縣）=', 24.67628243, 120.9189437, '保證金+3000', 'https://www.facebook.com/profile.php?id=100068581104944', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年頭份市客語中高級、中級及初級認證班', `description`='招生對象：\r\n客語初級班／報考114年客語初級認證之學員。正取15人、備取5人。\r\n客語中高班／報考114年客語中高級認證之學員。正取15人、備取5人。\r\n報名時間：\r\n客語初級班／即日起至114.04.10(四)17時止\r\n客語中高班／即日起至114.05.10(六)17時止\r\n填妥報名表 寄至電子郵件：lin39828@gmail.com 收件人：林火清\r\n保證金與報名表必須二者完成手續，並致電0937-271265 林火清確認收到，給予上課編號後才算完成報名。\r\n報名截止若未達15人，無法開課時，會通知所繳保證金無息退還。', `organizer`='林火清', `address`='苗栗縣頭份市', `start_date`='2025-04-29 00:00:00', `end_date`='2025-09-25 00:00:00', `location`='頭份市（苗栗縣）=', `latitude`=24.67628243, `longitude`=120.9189437, `ticket_price`='保證金+3000', `source_url`='https://www.facebook.com/profile.php?id=100068581104944', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a926b32458d4363960', '苗北藝術學苑2025苗北講堂：拉威爾的生平介紹與獨奏鋼琴作品欣賞', '本場演講，林仁斌老師將為您介紹拉威爾的生平與獨奏鋼琴作品：從早期深受德布西與李斯特的音樂印象洗禮，在琴音起落間水花翻飛、光影晃動的唯美之景栩栩如生；步入成熟期，重拾法國古典的典雅，並以西班牙的民俗風情融入異國風民間音樂的活力，並勇於蛻變。拉威爾以恣意揮灑音色的奇妙變幻，奠定其在近代法國重要地位。\r\n欣賞曲目：\r\n〈古風小步舞曲〉\r\n〈水的嬉戲〉\r\n〈鏡〉組曲\r\n〈夜之加斯巴〉\r\n〈高貴而傷感的圓舞曲〉\r\n\r\n報名方式：\r\n請優先使用官網線上報名系統（信用卡、匯款、臨櫃現金繳費)。\r\n紙本報名請下載印出報名表，並繳交至苗北藝文中心1樓服務台（匯款、臨櫃現金繳費)。', '苗栗縣苗北藝文中心', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-03-02 00:00:00', '2025-03-02 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '費用（單場）+150;套票5堂+525', 'https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2XS9BWQxUAEw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗北藝術學苑2025苗北講堂：拉威爾的生平介紹與獨奏鋼琴作品欣賞', `description`='本場演講，林仁斌老師將為您介紹拉威爾的生平與獨奏鋼琴作品：從早期深受德布西與李斯特的音樂印象洗禮，在琴音起落間水花翻飛、光影晃動的唯美之景栩栩如生；步入成熟期，重拾法國古典的典雅，並以西班牙的民俗風情融入異國風民間音樂的活力，並勇於蛻變。拉威爾以恣意揮灑音色的奇妙變幻，奠定其在近代法國重要地位。\r\n欣賞曲目：\r\n〈古風小步舞曲〉\r\n〈水的嬉戲〉\r\n〈鏡〉組曲\r\n〈夜之加斯巴〉\r\n〈高貴而傷感的圓舞曲〉\r\n\r\n報名方式：\r\n請優先使用官網線上報名系統（信用卡、匯款、臨櫃現金繳費)。\r\n紙本報名請下載印出報名表，並繳交至苗北藝文中心1樓服務台（匯款、臨櫃現金繳費)。', `organizer`='苗栗縣苗北藝文中心', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='費用（單場）+150;套票5堂+525', `source_url`='https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2XS9BWQxUAEw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a926b32458d4363961', '生命科學主題書展', '生命科學書籍展示，介紹生命科學資訊，讓市民了解日後查閱有關生命科學知識，可至本館充分利用現有之資源，發揮公共圖書館最大之效能。', '高雄市立圖書館總館', '高雄市鳳山區7鄰自強一路119巷75號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '高雄市立圖書館鳳山二館', 22.589421, 120.3273098, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='生命科學主題書展', `description`='生命科學書籍展示，介紹生命科學資訊，讓市民了解日後查閱有關生命科學知識，可至本館充分利用現有之資源，發揮公共圖書館最大之效能。', `organizer`='高雄市立圖書館總館', `address`='高雄市鳳山區7鄰自強一路119巷75號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='高雄市立圖書館鳳山二館', `latitude`=22.589421, `longitude`=120.3273098, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a926b32458d4363962', '苗北藝術學苑2025苗北講堂：「古典與創新」～談拉威爾鋼琴協奏作品集', '本場演講，林仁斌老師將為您介紹拉威爾完成於 1931 年，完美地融合古典協奏曲形式與爵士與當代音樂元素之〈G 大調鋼琴協奏曲〉以及為一戰中失去右臂的鋼琴家的請求所寫的特殊〈左手鋼琴協奏曲，這兩首協奏曲突破了傳統協奏曲的音樂、演奏技巧等常規，更展現了拉威爾的創意無限與對於鋼琴演奏技巧的探索。\r\n欣賞曲目：\r\nG大調鋼琴協奏曲\r\n左手鋼琴協奏曲\r\n\r\n報名方式：\r\n請優先使用官網線上報名系統（信用卡、匯款、臨櫃現金繳費)。\r\n紙本報名請下載印出報名表，並繳交至苗北藝文中心1樓服務台（匯款、臨櫃現金繳費)。', '苗栗縣苗北藝文中心', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '費用（單場）+150;套票5堂+525', 'https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2XS9BWQxUAEw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗北藝術學苑2025苗北講堂：「古典與創新」～談拉威爾鋼琴協奏作品集', `description`='本場演講，林仁斌老師將為您介紹拉威爾完成於 1931 年，完美地融合古典協奏曲形式與爵士與當代音樂元素之〈G 大調鋼琴協奏曲〉以及為一戰中失去右臂的鋼琴家的請求所寫的特殊〈左手鋼琴協奏曲，這兩首協奏曲突破了傳統協奏曲的音樂、演奏技巧等常規，更展現了拉威爾的創意無限與對於鋼琴演奏技巧的探索。\r\n欣賞曲目：\r\nG大調鋼琴協奏曲\r\n左手鋼琴協奏曲\r\n\r\n報名方式：\r\n請優先使用官網線上報名系統（信用卡、匯款、臨櫃現金繳費)。\r\n紙本報名請下載印出報名表，並繳交至苗北藝文中心1樓服務台（匯款、臨櫃現金繳費)。', `organizer`='苗栗縣苗北藝文中心', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='費用（單場）+150;套票5堂+525', `source_url`='https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2XS9BWQxUAEw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a926b32458d4363963', '苗北藝術學苑2025苗北講堂：「道地西班牙」～談兩首拉威爾管弦精彩作品集', '本場演講，林仁斌老師將為您介紹拉威爾充滿鮮明的異國情調國特色的管弦樂精彩作品。擁有母系西班牙血統的拉威爾，在成熟期創作中將西班牙風格與古典主義的結構和技巧相融合，並以充滿特色之樂節奏與特色打擊樂器，帶領聽眾帶入一種狂熱的氛圍並展現出西班牙音樂中熱情與慵懶交織的獨特風情。\r\n欣賞曲目：\r\n〈西班牙狂想曲〉\r\n〈波麗路舞曲〉\r\n\r\n報名方式：\r\n請優先使用官網線上報名系統（信用卡、匯款、臨櫃現金繳費)。\r\n紙本報名請下載印出報名表，並繳交至苗北藝文中心1樓服務台（匯款、臨櫃現金繳費)。', '苗栗縣苗北藝文中心', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '費用（單場）+150;套票5堂+525', 'https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2XS9BWQxUAEw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗北藝術學苑2025苗北講堂：「道地西班牙」～談兩首拉威爾管弦精彩作品集', `description`='本場演講，林仁斌老師將為您介紹拉威爾充滿鮮明的異國情調國特色的管弦樂精彩作品。擁有母系西班牙血統的拉威爾，在成熟期創作中將西班牙風格與古典主義的結構和技巧相融合，並以充滿特色之樂節奏與特色打擊樂器，帶領聽眾帶入一種狂熱的氛圍並展現出西班牙音樂中熱情與慵懶交織的獨特風情。\r\n欣賞曲目：\r\n〈西班牙狂想曲〉\r\n〈波麗路舞曲〉\r\n\r\n報名方式：\r\n請優先使用官網線上報名系統（信用卡、匯款、臨櫃現金繳費)。\r\n紙本報名請下載印出報名表，並繳交至苗北藝文中心1樓服務台（匯款、臨櫃現金繳費)。', `organizer`='苗栗縣苗北藝文中心', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='費用（單場）+150;套票5堂+525', `source_url`='https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2XS9BWQxUAEw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a926b32458d4363964', '苗北藝術學苑2025苗北講堂：「最美的日出」～談拉威爾之精彩芭蕾音樂', '本場演講，林仁斌老師將為您介紹拉威爾人生中唯一為芭蕾舞劇創作的音樂，後來被改編為兩套管弦樂組曲～《達夫尼與克羅埃》。這部作品具有獨特的音樂風格與生動的音樂形象，並包含了強烈的情感表達與高超的演奏技巧。拉威爾在創作中運用了豐富的元素，音樂蘊含著豐富的情感，包括愛情、喜悅、悲傷等，炫技的演奏更成為全球管弦樂團的最愛。\r\n欣賞曲目：\r\n《達夫尼與克羅埃》音樂组曲\r\n〈展覽會之畫〉拉威爾配器版\r\n\r\n報名方式：\r\n請優先使用官網線上報名系統（信用卡、匯款、臨櫃現金繳費)。\r\n紙本報名請下載印出報名表，並繳交至苗北藝文中心1樓服務台（匯款、臨櫃現金繳費)。', '苗栗縣苗北藝文中心', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '費用（單場）+150;套票5堂+525', 'https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2XS9BWQxUAEw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗北藝術學苑2025苗北講堂：「最美的日出」～談拉威爾之精彩芭蕾音樂', `description`='本場演講，林仁斌老師將為您介紹拉威爾人生中唯一為芭蕾舞劇創作的音樂，後來被改編為兩套管弦樂組曲～《達夫尼與克羅埃》。這部作品具有獨特的音樂風格與生動的音樂形象，並包含了強烈的情感表達與高超的演奏技巧。拉威爾在創作中運用了豐富的元素，音樂蘊含著豐富的情感，包括愛情、喜悅、悲傷等，炫技的演奏更成為全球管弦樂團的最愛。\r\n欣賞曲目：\r\n《達夫尼與克羅埃》音樂组曲\r\n〈展覽會之畫〉拉威爾配器版\r\n\r\n報名方式：\r\n請優先使用官網線上報名系統（信用卡、匯款、臨櫃現金繳費)。\r\n紙本報名請下載印出報名表，並繳交至苗北藝文中心1樓服務台（匯款、臨櫃現金繳費)。', `organizer`='苗栗縣苗北藝文中心', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='費用（單場）+150;套票5堂+525', `source_url`='https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2XS9BWQxUAEw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a926b32458d4363965', '苗北藝術學苑2025苗北講堂：談拉威爾的室內樂作品', '本場演講，林仁斌老師將為您介紹拉威爾的精彩室內樂作品：拉威爾的室內樂如印象派畫家捕捉光影一樣，以用音樂捕捉音樂萬千各種瞬間精彩的樣貌，不但有音色和和聲的細膩變化，且在樂章的佈局、主題的呈示和發展等方面，都有著古典主義的嚴謹性。從弦樂奏鳴曲到鋼琴三重奏、弦樂四重奏與大編制室內樂，均值得您細細品味。\r\n欣賞曲目：\r\n小提琴奏鳴曲\r\n大提琴奏鳴曲\r\n鋼琴三重奏\r\n弦樂四重奏\r\n前奏與快板（為豎琴、長笛、單簧管與弦樂四重奏而作）\r\n\r\n報名方式：\r\n請優先使用官網線上報名系統（信用卡、匯款、臨櫃現金繳費)。\r\n紙本報名請下載印出報名表，並繳交至苗北藝文中心1樓服務台（匯款、臨櫃現金繳費)。', '苗栗縣苗北藝文中心', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-04-27 00:00:00', '2025-04-27 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '費用（單場）+150;套票5堂+525', 'https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2XS9BWQxUAEw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗北藝術學苑2025苗北講堂：談拉威爾的室內樂作品', `description`='本場演講，林仁斌老師將為您介紹拉威爾的精彩室內樂作品：拉威爾的室內樂如印象派畫家捕捉光影一樣，以用音樂捕捉音樂萬千各種瞬間精彩的樣貌，不但有音色和和聲的細膩變化，且在樂章的佈局、主題的呈示和發展等方面，都有著古典主義的嚴謹性。從弦樂奏鳴曲到鋼琴三重奏、弦樂四重奏與大編制室內樂，均值得您細細品味。\r\n欣賞曲目：\r\n小提琴奏鳴曲\r\n大提琴奏鳴曲\r\n鋼琴三重奏\r\n弦樂四重奏\r\n前奏與快板（為豎琴、長笛、單簧管與弦樂四重奏而作）\r\n\r\n報名方式：\r\n請優先使用官網線上報名系統（信用卡、匯款、臨櫃現金繳費)。\r\n紙本報名請下載印出報名表，並繳交至苗北藝文中心1樓服務台（匯款、臨櫃現金繳費)。', `organizer`='苗栗縣苗北藝文中心', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='費用（單場）+150;套票5堂+525', `source_url`='https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2XS9BWQxUAEw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a926b32458d4363966', '2025苗北藝術工坊–慢活樂學習系列', '活動項目：\r\n慢活樂學習－綿柔柔羊毛氈\r\n活動時間：2025年3月15日(六) 09:30-11:30\r\n活動地點：苗北藝文中心B1(137)研習教室\r\n綿柔柔羊毛氈這次帶來羊毛氈帆布袋的課程：羊毛氈化身成可愛圖案氈在帆布袋上，為白紙般的布袋添上童話般的夢幻色彩～製作過程紓壓治癒，出門在外也不怕撞包呦！\r\n可攜回一個羊毛氈帆布袋。\r\n授課講師：張媛婷\r\n課程人數限制：30人\r\n\r\n慢活樂學習－幸福多肉壁掛\r\n活動時間：2025年3月22日(六) 09:30-11:30\r\n活動地點：苗北藝文中心B1(137)研習教室\r\n盆栽已經擺不下了嗎？那就來一起來製作獨創的幸福多肉壁掛吧～\r\n將可愛的多肉植物組合在質感木板上，把綠意掛在生活的每一面牆上！\r\n可攜回一個多肉植栽。\r\n授課講師：謝宜君\r\n課程人數限制：40人\r\n\r\n慢活樂學習－水噹噹字母燈\r\n活動時間：2025年3月29日(六) 09:30-11:30\r\n活動地點：苗北藝文中心B1(137)研習教室\r\n本課程將讓學員實際學習環氧樹脂的使用技巧，並發揮個人創意進行花漾字母的設計，製作出屬於獨一無二的水噹噹字母燈，既實用又美觀。\r\n授課講師：劉慧清\r\n課程人數限制：40人\r\n\r\n歡迎至活動網站線上報名\r\n活動洽詢：展覽育成部 吳小姐 037-612669#525', '苗栗縣苗北藝文中心', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-03-15 00:00:00', '2025-03-29 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '綿柔柔羊毛氈+650;幸福多肉壁掛+650;水噹噹字母燈+750', 'https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1cWXtfFmhpbgM4Vg', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025苗北藝術工坊–慢活樂學習系列', `description`='活動項目：\r\n慢活樂學習－綿柔柔羊毛氈\r\n活動時間：2025年3月15日(六) 09:30-11:30\r\n活動地點：苗北藝文中心B1(137)研習教室\r\n綿柔柔羊毛氈這次帶來羊毛氈帆布袋的課程：羊毛氈化身成可愛圖案氈在帆布袋上，為白紙般的布袋添上童話般的夢幻色彩～製作過程紓壓治癒，出門在外也不怕撞包呦！\r\n可攜回一個羊毛氈帆布袋。\r\n授課講師：張媛婷\r\n課程人數限制：30人\r\n\r\n慢活樂學習－幸福多肉壁掛\r\n活動時間：2025年3月22日(六) 09:30-11:30\r\n活動地點：苗北藝文中心B1(137)研習教室\r\n盆栽已經擺不下了嗎？那就來一起來製作獨創的幸福多肉壁掛吧～\r\n將可愛的多肉植物組合在質感木板上，把綠意掛在生活的每一面牆上！\r\n可攜回一個多肉植栽。\r\n授課講師：謝宜君\r\n課程人數限制：40人\r\n\r\n慢活樂學習－水噹噹字母燈\r\n活動時間：2025年3月29日(六) 09:30-11:30\r\n活動地點：苗北藝文中心B1(137)研習教室\r\n本課程將讓學員實際學習環氧樹脂的使用技巧，並發揮個人創意進行花漾字母的設計，製作出屬於獨一無二的水噹噹字母燈，既實用又美觀。\r\n授課講師：劉慧清\r\n課程人數限制：40人\r\n\r\n歡迎至活動網站線上報名\r\n活動洽詢：展覽育成部 吳小姐 037-612669#525', `organizer`='苗栗縣苗北藝文中心', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='綿柔柔羊毛氈+650;幸福多肉壁掛+650;水噹噹字母燈+750', `source_url`='https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1cWXtfFmhpbgM4Vg', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a926b32458d4363968', '2025金喇叭【卡通大冒險-Bingo親子音樂會】', '【金喇叭12年初衷】獲選113桃園市傑出演藝團隊\r\n金喇叭成立於2012年6月。設立至今秉持創新改變的理念，期望突破以往大眾對銅管音樂過於形式化、沈重、吵雜的刻板印象。藉由將流行樂曲重新改編成銅管5重奏之形式，並融入許多臺灣在地元素（包含國語、閩南、客家等多元文化），希望帶給觀眾不同且獨特的音樂饗宴。\r\n金喇叭走過10年的歲月，創造出許多不同的演出形式，以輕鬆活潑的氛圍，搭配特製的節目效果，並結合傳統民謠、流行音樂、電視、電影配樂及世界名曲，讓音樂不只是「聽」，而是能夠樂在其中，享受當下的快樂。\r\n\r\n經營理念\r\n十年磨一劍，「音樂」能夠傳遞情感，每一場不同性質的演出，金喇叭期許藉由不同的主題來呈現音樂，以符合觀眾朋友們當下的聆聽情境。\r\n音樂與生活息息相關，有了音樂的陪伴，將使我們能更好地體驗生活中的美好。金喇叭希望每場參與音樂會的大小朋友們，都可以獲得滿滿的喜悅和幸福；並且也祈願演出結束後，能在每個人心中埋下音樂的種苗，持續地將美好延續下去。', '金喇叭銅管樂團', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-09-14 00:00:00', '2025-09-14 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '票價+400;票價+600;票價+800;票價+1000;票價+1200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025金喇叭【卡通大冒險-Bingo親子音樂會】', `description`='【金喇叭12年初衷】獲選113桃園市傑出演藝團隊\r\n金喇叭成立於2012年6月。設立至今秉持創新改變的理念，期望突破以往大眾對銅管音樂過於形式化、沈重、吵雜的刻板印象。藉由將流行樂曲重新改編成銅管5重奏之形式，並融入許多臺灣在地元素（包含國語、閩南、客家等多元文化），希望帶給觀眾不同且獨特的音樂饗宴。\r\n金喇叭走過10年的歲月，創造出許多不同的演出形式，以輕鬆活潑的氛圍，搭配特製的節目效果，並結合傳統民謠、流行音樂、電視、電影配樂及世界名曲，讓音樂不只是「聽」，而是能夠樂在其中，享受當下的快樂。\r\n\r\n經營理念\r\n十年磨一劍，「音樂」能夠傳遞情感，每一場不同性質的演出，金喇叭期許藉由不同的主題來呈現音樂，以符合觀眾朋友們當下的聆聽情境。\r\n音樂與生活息息相關，有了音樂的陪伴，將使我們能更好地體驗生活中的美好。金喇叭希望每場參與音樂會的大小朋友們，都可以獲得滿滿的喜悅和幸福；並且也祈願演出結束後，能在每個人心中埋下音樂的種苗，持續地將美好延續下去。', `organizer`='金喇叭銅管樂團', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-09-14 00:00:00', `end_date`='2025-09-14 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='票價+400;票價+600;票價+800;票價+1000;票價+1200', `source_url`='https://www.opentix.life/', `image_url`='[]';
