INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414aa26b32458d436397f', '苗栗縣公共圖書館響應【世界母語日】活動：主題書展＆【愛的索書號】主題書展', '苗栗縣政府重視母語教育的傳承與推廣，並響應【世界母語日】辦理一系列本土語言推廣活動，透過講座與閱讀、書展，傳承本土語言，認識臺灣多元文化。亦分別在苗栗縣立圖書館、後龍鎮立圖書館、頭屋鄉立圖書館、頭份市立圖書館、公館鄉立圖書館、西湖鄉立圖書館、三義鄉立圖書館、造橋鄉立圖書館及南庄鄉立圖書館等9所圖書館，辦理「客家文化」、「閩南文化」及「泰雅、賽夏文化」等主題書展，讓民眾透過閱讀探索不同族群的文化、脈絡與歷史。\r\n\r\n【愛的索書號】主題書展\r\n展期：14/02/13-114/02/28\r\n地點：圖書館二樓\r\n看見愛情其實是一個關於自己的故事，無論是曾經為愛執迷不悟、飛蛾撲火，或者膽怯不安、寂寞流淚的你，能在這些經典故事裡，讀懂自己，也在愛情裡，成為更好的自己。你曾陷在愛情裡嗎？能否在愛情裡成為更好的自己', '苗栗縣政府', '苗栗縣造橋鄉14鄰1號', '2025-02-01 00:00:00', '2025-03-31 00:00:00', '苗栗縣造橋鄉立圖書館', 24.62481314, 120.8695663, '無資料', 'https://lib.miaoli.gov.tw/wSite/ct?xItem=19710&ctNode=227&mp=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗栗縣公共圖書館響應【世界母語日】活動：主題書展＆【愛的索書號】主題書展', `description`='苗栗縣政府重視母語教育的傳承與推廣，並響應【世界母語日】辦理一系列本土語言推廣活動，透過講座與閱讀、書展，傳承本土語言，認識臺灣多元文化。亦分別在苗栗縣立圖書館、後龍鎮立圖書館、頭屋鄉立圖書館、頭份市立圖書館、公館鄉立圖書館、西湖鄉立圖書館、三義鄉立圖書館、造橋鄉立圖書館及南庄鄉立圖書館等9所圖書館，辦理「客家文化」、「閩南文化」及「泰雅、賽夏文化」等主題書展，讓民眾透過閱讀探索不同族群的文化、脈絡與歷史。\r\n\r\n【愛的索書號】主題書展\r\n展期：14/02/13-114/02/28\r\n地點：圖書館二樓\r\n看見愛情其實是一個關於自己的故事，無論是曾經為愛執迷不悟、飛蛾撲火，或者膽怯不安、寂寞流淚的你，能在這些經典故事裡，讀懂自己，也在愛情裡，成為更好的自己。你曾陷在愛情裡嗎？能否在愛情裡成為更好的自己', `organizer`='苗栗縣政府', `address`='苗栗縣造橋鄉14鄰1號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='苗栗縣造橋鄉立圖書館', `latitude`=24.62481314, `longitude`=120.8695663, `ticket_price`='無資料', `source_url`='https://lib.miaoli.gov.tw/wSite/ct?xItem=19710&ctNode=227&mp=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414ab26b32458d4363981', '無資料', '一年一度重頭戲2025金門 #元宵燈節「福蛇迎春」\r\n2月12日至2月23日將在金湖鎮蘭湖及瓊林登場\r\n本次燈節共規劃 #蘭湖、#瓊林 及 #小徑 三大燈區\r\n\r\n\r\n各燈區展示現代創意燈組，讓民眾尋訪老街、湖邊還能感受刺激燈光體驗！\r\n\r\n\r\n2月12日蘭湖點燈晚會有精彩樂團表演以及獎品豐富的猜燈謎趣味活動，現場並發放限量紀念小物，2月12日、2月13日還有元宵市集，要讓大家歡度兼具傳統優雅與當代震撼的華麗元宵燈節！\r\n\r\n\r\n2025金門元宵燈節\r\n瓊林聚落光環境｜01/01-02/28　18:00-22:00｜瓊林聚落\r\n水舞 ｜01/25-02/23　18:30、19:00、19:30、20:00、20:30｜蘭湖週邊\r\n蘭湖週邊光環境｜02/12-02/23　18:30-22:00｜蘭湖週邊\r\n主燈點燈、猜燈謎｜02/12　19:00｜蘭湖週邊\r\n元宵市集｜02/12-02/23　16:00-22:00｜蘭湖週邊', '金門縣文化局', '金門縣全區域', '金門縣', '無資料', '無資料', '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='一年一度重頭戲2025金門 #元宵燈節「福蛇迎春」\r\n2月12日至2月23日將在金湖鎮蘭湖及瓊林登場\r\n本次燈節共規劃 #蘭湖、#瓊林 及 #小徑 三大燈區\r\n\r\n\r\n各燈區展示現代創意燈組，讓民眾尋訪老街、湖邊還能感受刺激燈光體驗！\r\n\r\n\r\n2月12日蘭湖點燈晚會有精彩樂團表演以及獎品豐富的猜燈謎趣味活動，現場並發放限量紀念小物，2月12日、2月13日還有元宵市集，要讓大家歡度兼具傳統優雅與當代震撼的華麗元宵燈節！\r\n\r\n\r\n2025金門元宵燈節\r\n瓊林聚落光環境｜01/01-02/28　18:00-22:00｜瓊林聚落\r\n水舞 ｜01/25-02/23　18:30、19:00、19:30、20:00、20:30｜蘭湖週邊\r\n蘭湖週邊光環境｜02/12-02/23　18:30-22:00｜蘭湖週邊\r\n主燈點燈、猜燈謎｜02/12　19:00｜蘭湖週邊\r\n元宵市集｜02/12-02/23　16:00-22:00｜蘭湖週邊', `organizer`='金門縣文化局', `address`='金門縣全區域', `location`='金門縣', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414ab26b32458d4363982', '「情緒百寶箱」主題繪本展', '「情緒百寶箱」主題繪本展\r\n我們的情緒會隨著外在環境、壓力和生活變化而波動，認識與理解情緒，並且用適當的方式表達，公館圖書館精心挑選館內不同情緒的繪本，透過不同的故事情境，希望小朋友可以更認識了解自己的情緒，有興趣的小朋友及家長均歡迎借閱。', '苗栗縣公館鄉立圖書館', '苗栗縣公館鄉館中村8鄰宮前路6-1號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '苗栗縣公館鄉立圖書館', 24.50249686, 120.8505904, '無資料', 'https://www.facebook.com/kungkuanbooks', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「情緒百寶箱」主題繪本展', `description`='「情緒百寶箱」主題繪本展\r\n我們的情緒會隨著外在環境、壓力和生活變化而波動，認識與理解情緒，並且用適當的方式表達，公館圖書館精心挑選館內不同情緒的繪本，透過不同的故事情境，希望小朋友可以更認識了解自己的情緒，有興趣的小朋友及家長均歡迎借閱。', `organizer`='苗栗縣公館鄉立圖書館', `address`='苗栗縣公館鄉館中村8鄰宮前路6-1號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='苗栗縣公館鄉立圖書館', `latitude`=24.50249686, `longitude`=120.8505904, `ticket_price`='無資料', `source_url`='https://www.facebook.com/kungkuanbooks', `image_url`='[]';
