INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679d482126b32458d43639b9', '「斯土斯民：臺灣的故事」常設展', '陪伴我們的臺灣島嶼，一起穿越數百年的記憶流轉吧！在這裡，你會從神秘的起源傳說開始，跟著這塊土地，一次次歷經時代的更迭與鉅變，看見大歷史之下人群的樣貌、聲音與故事。\r\n\r\n展覽以「時代」作為單元，分為「臺灣，交會之島」、「最初的抵岸」、「倚海而生的島與人」、「山海之間的共存與競逐」、「新秩序下的苦悶與夢想」、「邁向民主這條路」、「大家的博物館」7大單元；從史前到當代，相異的時空情境中，是否喚起你似曾相似的共鳴？', '國立臺灣歷史博物館', '臺南市安南區長和路一段250號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '國立臺灣歷史博物館', 23.04869681, 120.1526189, '無資料', 'https://www.nmth.gov.tw/permanentall?uid=126', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「斯土斯民：臺灣的故事」常設展', `description`='陪伴我們的臺灣島嶼，一起穿越數百年的記憶流轉吧！在這裡，你會從神秘的起源傳說開始，跟著這塊土地，一次次歷經時代的更迭與鉅變，看見大歷史之下人群的樣貌、聲音與故事。\r\n\r\n展覽以「時代」作為單元，分為「臺灣，交會之島」、「最初的抵岸」、「倚海而生的島與人」、「山海之間的共存與競逐」、「新秩序下的苦悶與夢想」、「邁向民主這條路」、「大家的博物館」7大單元；從史前到當代，相異的時空情境中，是否喚起你似曾相似的共鳴？', `organizer`='國立臺灣歷史博物館', `address`='臺南市安南區長和路一段250號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='國立臺灣歷史博物館', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='無資料', `source_url`='https://www.nmth.gov.tw/permanentall?uid=126', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679d482126b32458d43639ba', '數味食光：臺灣飲食記憶特展', '記憶如何捕捉？如何承載？哪些記憶得以被保存與傳遞？自2021年起，國立臺灣歷史博物館接手營運「國家文化記憶庫」這個由全民共筆的資料庫，累積了眾人的記憶與故事，透過民眾的自我書寫、記錄和上傳，建構出豐富多元的臺灣文化地景。我們相信每個人所見的世界皆值得被分享，這些記憶片段成為我們共同的文化資產。\r\n\r\n在本展覽中，以「飲食」作為入口，進入記憶庫所匯聚的文化寶藏之中。如果用「吃」當作認識臺灣大眾記憶的鑰匙，透過「15組」飲食關鍵字，我們將看見甚麼樣的記憶面貌？又能感受到甚麼樣的時代脈絡？\r\n\r\n展覽中，我們將利用國家文化記憶庫素材，搭配博物館、個人與在地社區的蒐藏，加上各式流行素材與資料，勾勒出臺灣大眾飲食記憶的輪廓，願與您的味蕾會心一笑。', '國立臺灣歷史博物館', '臺南市安南區長和路一段250號', '2025-03-11 00:00:00', '2025-11-19 00:00:00', '國立臺灣歷史博物館', 23.04869681, 120.1526189, '無資料', 'https://www.nmth.gov.tw/News_Content2.aspx?n=8019&s=230545', '[]') ON DUPLICATE KEY UPDATE `activity_name`='數味食光：臺灣飲食記憶特展', `description`='記憶如何捕捉？如何承載？哪些記憶得以被保存與傳遞？自2021年起，國立臺灣歷史博物館接手營運「國家文化記憶庫」這個由全民共筆的資料庫，累積了眾人的記憶與故事，透過民眾的自我書寫、記錄和上傳，建構出豐富多元的臺灣文化地景。我們相信每個人所見的世界皆值得被分享，這些記憶片段成為我們共同的文化資產。\r\n\r\n在本展覽中，以「飲食」作為入口，進入記憶庫所匯聚的文化寶藏之中。如果用「吃」當作認識臺灣大眾記憶的鑰匙，透過「15組」飲食關鍵字，我們將看見甚麼樣的記憶面貌？又能感受到甚麼樣的時代脈絡？\r\n\r\n展覽中，我們將利用國家文化記憶庫素材，搭配博物館、個人與在地社區的蒐藏，加上各式流行素材與資料，勾勒出臺灣大眾飲食記憶的輪廓，願與您的味蕾會心一笑。', `organizer`='國立臺灣歷史博物館', `address`='臺南市安南區長和路一段250號', `start_date`='2025-03-11 00:00:00', `end_date`='2025-11-19 00:00:00', `location`='國立臺灣歷史博物館', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='無資料', `source_url`='https://www.nmth.gov.tw/News_Content2.aspx?n=8019&s=230545', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679d482126b32458d43639bb', '2024-2025年臺史博戲劇【戲遊時光：小人物說歷史】', '臺史博戲劇融合歷史教育與戲劇互動，運用解說、戲劇、歌曲等方式，帶領觀眾在展場中進行互動體驗，重現歷史的時代風貌。而在各種角色及情境變換中，也讓歷史的多元視角，藉由戲劇展開不一樣的對話及想像！', '國立臺灣歷史博物館', '臺南市安南區長和路一段250號', '2025-01-01 00:00:00', '2025-03-01 00:00:00', '國立臺灣歷史博物館', 23.04869681, 120.1526189, '全票+100;優待票+50;一般團體優待票+90;學生團體票+60', 'https://event.culture.tw/mocweb/reg/NMTH/Detail.init.ctr?actId=40041', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2024-2025年臺史博戲劇【戲遊時光：小人物說歷史】', `description`='臺史博戲劇融合歷史教育與戲劇互動，運用解說、戲劇、歌曲等方式，帶領觀眾在展場中進行互動體驗，重現歷史的時代風貌。而在各種角色及情境變換中，也讓歷史的多元視角，藉由戲劇展開不一樣的對話及想像！', `organizer`='國立臺灣歷史博物館', `address`='臺南市安南區長和路一段250號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='國立臺灣歷史博物館', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='全票+100;優待票+50;一般團體優待票+90;學生團體票+60', `source_url`='https://event.culture.tw/mocweb/reg/NMTH/Detail.init.ctr?actId=40041', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679d482126b32458d43639bc', 'AR仙怪歷險記-常設展AR遊戲', '什麼！？臺史博「斯土斯民」常設展居然藏著一個平行異時空？文物仙怪穿越了歷史，遊走在異時空場域裡，他們有自己的故事、有自己的想法，還有話想說！據說，只要採集故事，汲取仙怪的文物能量值，身體就會發生不可思議的升級變化。趕快開啟擴增實境鏡頭，找出這些神秘客的藏匿地點，看見遊走於時空中的無形之物吧！\r\n\r\n', '國立臺灣歷史博物館', '臺南市安南區長和路一段250號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '國立臺灣歷史博物館', 23.04869681, 120.1526189, '全票+100;優待票+50;一般團體優待票+90;學生團體票+60', 'https://event.culture.tw/mocweb/reg/NMTH/Detail.init.ctr?actId=20442&utm_source=moc&utm_medium=queryHot&utm_campaign=20442', '[]') ON DUPLICATE KEY UPDATE `activity_name`='AR仙怪歷險記-常設展AR遊戲', `description`='什麼！？臺史博「斯土斯民」常設展居然藏著一個平行異時空？文物仙怪穿越了歷史，遊走在異時空場域裡，他們有自己的故事、有自己的想法，還有話想說！據說，只要採集故事，汲取仙怪的文物能量值，身體就會發生不可思議的升級變化。趕快開啟擴增實境鏡頭，找出這些神秘客的藏匿地點，看見遊走於時空中的無形之物吧！\r\n\r\n', `organizer`='國立臺灣歷史博物館', `address`='臺南市安南區長和路一段250號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='國立臺灣歷史博物館', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='全票+100;優待票+50;一般團體優待票+90;學生團體票+60', `source_url`='https://event.culture.tw/mocweb/reg/NMTH/Detail.init.ctr?actId=20442&utm_source=moc&utm_medium=queryHot&utm_campaign=20442', `image_url`='[]';
