INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679fe93f26b32458d43639c2', '「宜蘭設治兩百年」常設展', '宜蘭設治紀念館建於日治初年，原為近百年來歷任地方首長官邸，為一棟和洋式混合建築，擁有恬靜優雅的日式庭園景觀；自1997年修復以來，即成為本縣歷史建築再生的重要典範，也是兼具人文與休閒的好去處。\r\n館內展覽主要說明宜蘭自清代以來設官治理之過程，故名為設治紀念館，內容涵蓋清朝、日治與戰後迄今宜蘭縣政發展概要。', '宜蘭縣史館', '宜蘭縣宜蘭市舊城南路力行3巷3號', '2025-01-02 00:00:00', '2025-12-30 00:00:00', '宜蘭設治紀念館', 24.75021184, 121.7569358, '半票+15;優待票+20;全票+30', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「宜蘭設治兩百年」常設展', `description`='宜蘭設治紀念館建於日治初年，原為近百年來歷任地方首長官邸，為一棟和洋式混合建築，擁有恬靜優雅的日式庭園景觀；自1997年修復以來，即成為本縣歷史建築再生的重要典範，也是兼具人文與休閒的好去處。\r\n館內展覽主要說明宜蘭自清代以來設官治理之過程，故名為設治紀念館，內容涵蓋清朝、日治與戰後迄今宜蘭縣政發展概要。', `organizer`='宜蘭縣史館', `address`='宜蘭縣宜蘭市舊城南路力行3巷3號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-30 00:00:00', `location`='宜蘭設治紀念館', `latitude`=24.75021184, `longitude`=121.7569358, `ticket_price`='半票+15;優待票+20;全票+30', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679fe93f26b32458d43639c3', '「快樂學歷史」常設展', '「快樂學歷史」旨在向大眾傳達每個人都能成為歷史學家的理念。簡單來說，每個人都擁有自己的故事可分享，同時也能探索並分享他人的故事。然而，發現和講述故事需要一些敏銳度和技巧，而展覽則是指引您如何做到這一點的指南。\r\n我們最終的目標是讓歷史變得更親近，消除人們對於學習和死記硬背的壓力，讓學習歷史成為一件快樂的事。因此，我們鼓勵每個人發掘、分享和欣賞歷史故事的魅力，並提供相關技能和知識以讓每個人都能參與歷史的傳承。', '宜蘭縣史館', '宜蘭縣宜蘭市縣政北路3號', '2025-01-02 00:00:00', '2025-12-30 00:00:00', '宜蘭縣史館', 24.75021184, 121.7569358, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「快樂學歷史」常設展', `description`='「快樂學歷史」旨在向大眾傳達每個人都能成為歷史學家的理念。簡單來說，每個人都擁有自己的故事可分享，同時也能探索並分享他人的故事。然而，發現和講述故事需要一些敏銳度和技巧，而展覽則是指引您如何做到這一點的指南。\r\n我們最終的目標是讓歷史變得更親近，消除人們對於學習和死記硬背的壓力，讓學習歷史成為一件快樂的事。因此，我們鼓勵每個人發掘、分享和欣賞歷史故事的魅力，並提供相關技能和知識以讓每個人都能參與歷史的傳承。', `organizer`='宜蘭縣史館', `address`='宜蘭縣宜蘭市縣政北路3號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-30 00:00:00', `location`='宜蘭縣史館', `latitude`=24.75021184, `longitude`=121.7569358, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a04eb107f3fcdc7f9ef393', '《水中之屋》', '劇作家許正平以新文本的文類混聲，\r\n以語言的針線在劇場裡編織與刺繡，\r\n展開一幅幅專屬於這塊土地的鄉村奇幻。\r\n\r\n#劇情簡介\r\n西南沿海小村莊，一場颱風帶來的大水，\r\n拆散了海產三姊妹蚵仔、蜆仔、螺仔緊密相依的童年，\r\n家園毀壞，親人永別，天涯離散。\r\n\r\n二十年後，地下電台主持人Aniki來到這個破落的村莊，\r\n尋找他如謎一般消失在綿綿夜雨中的愛慕之人Lara；\r\n同時，飄搖小屋𥚃燈光乍亮，長大的海產三姊妹也終於重逢，\r\n但他們甦醒的童年記憶卻也同時喚回了龍王大水⋯⋯\r\n\r\n颱風再度登陸的夜晚，\r\n狂風暴雨眼看就要摧毀三人好不容易拼湊回來的重建；\r\nAniki虔誠的祝禱，能否喚醒媽祖婆的溫柔垂憐？\r\n一曲《惜別的海岸》能不能讓無言的結局改變？\r\n\r\n#關於本劇\r\n《水中之屋》是劇作家許正平以嘉義東石四股社區及與其傍鄰的鰲鼓濕地作為創作原型，描寫一個近乎遺世獨立的偏鄉村落，關於人口外移、產業沒落、自然災害與歷史變遷，以及居民自我認同等種種命題，並以新文本魔幻寫實的手法，建構一則關於家的失落與重建的寓言故事。\r\n\r\n#製作團隊\r\n製作人│李維睦、呂柏伸\r\n編劇│許正平\r\n導演│呂柏伸\r\n助理導演│陳奕愷\r\n舞臺設計│李柏霖\r\n燈光設計│李意舜\r\n服裝設計│李育昇\r\n音樂設計│徐啟洋\r\n主視覺道具設計│李育昇\r\n主視覺攝影│陳又維\r\n主視覺設計│郭保伸\r\n\r\n演員 │ 古辛、甘立安、杜瑋哲、林曉函、洪健藏、張家禎、曹瑜（依姓氏筆劃排序）\r\n\r\n製作經理│劉辰君\r\n舞臺監督│林岱蓉、周賢欣\r\n舞臺技術統籌│劉柏言\r\n燈光技術統籌│郭欣怡\r\n導演助理│黃家豪\r\n舞臺設計助理│楊凱淇\r\n音響技術│唐宋音響\r\n服裝管理│林昕誼、廖瑩璇\r\n妝髮造型│Teddy、吳曉芳(Sarah)\r\n票務會計│紀美玲\r\n行銷宣傳│林耿邦\r\n\r\n指導單位│文化部\r\n主辦單位│台南人劇團\r\n贊助單位│國藝會、藝響空間\r\n場地提供│臺北市政府文化局\r\n台南人劇團為2024TAIWAN TOP演藝團隊', '台南人劇團', '臺北市中正區羅斯福路四段92號10樓', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '水源劇場', 25.03240487, 121.5198839, ' 票價： 1,200 、1,500 、1,800元', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《水中之屋》', `description`='劇作家許正平以新文本的文類混聲，\r\n以語言的針線在劇場裡編織與刺繡，\r\n展開一幅幅專屬於這塊土地的鄉村奇幻。\r\n\r\n#劇情簡介\r\n西南沿海小村莊，一場颱風帶來的大水，\r\n拆散了海產三姊妹蚵仔、蜆仔、螺仔緊密相依的童年，\r\n家園毀壞，親人永別，天涯離散。\r\n\r\n二十年後，地下電台主持人Aniki來到這個破落的村莊，\r\n尋找他如謎一般消失在綿綿夜雨中的愛慕之人Lara；\r\n同時，飄搖小屋𥚃燈光乍亮，長大的海產三姊妹也終於重逢，\r\n但他們甦醒的童年記憶卻也同時喚回了龍王大水⋯⋯\r\n\r\n颱風再度登陸的夜晚，\r\n狂風暴雨眼看就要摧毀三人好不容易拼湊回來的重建；\r\nAniki虔誠的祝禱，能否喚醒媽祖婆的溫柔垂憐？\r\n一曲《惜別的海岸》能不能讓無言的結局改變？\r\n\r\n#關於本劇\r\n《水中之屋》是劇作家許正平以嘉義東石四股社區及與其傍鄰的鰲鼓濕地作為創作原型，描寫一個近乎遺世獨立的偏鄉村落，關於人口外移、產業沒落、自然災害與歷史變遷，以及居民自我認同等種種命題，並以新文本魔幻寫實的手法，建構一則關於家的失落與重建的寓言故事。\r\n\r\n#製作團隊\r\n製作人│李維睦、呂柏伸\r\n編劇│許正平\r\n導演│呂柏伸\r\n助理導演│陳奕愷\r\n舞臺設計│李柏霖\r\n燈光設計│李意舜\r\n服裝設計│李育昇\r\n音樂設計│徐啟洋\r\n主視覺道具設計│李育昇\r\n主視覺攝影│陳又維\r\n主視覺設計│郭保伸\r\n\r\n演員 │ 古辛、甘立安、杜瑋哲、林曉函、洪健藏、張家禎、曹瑜（依姓氏筆劃排序）\r\n\r\n製作經理│劉辰君\r\n舞臺監督│林岱蓉、周賢欣\r\n舞臺技術統籌│劉柏言\r\n燈光技術統籌│郭欣怡\r\n導演助理│黃家豪\r\n舞臺設計助理│楊凱淇\r\n音響技術│唐宋音響\r\n服裝管理│林昕誼、廖瑩璇\r\n妝髮造型│Teddy、吳曉芳(Sarah)\r\n票務會計│紀美玲\r\n行銷宣傳│林耿邦\r\n\r\n指導單位│文化部\r\n主辦單位│台南人劇團\r\n贊助單位│國藝會、藝響空間\r\n場地提供│臺北市政府文化局\r\n台南人劇團為2024TAIWAN TOP演藝團隊', `organizer`='台南人劇團', `address`='臺北市中正區羅斯福路四段92號10樓', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='水源劇場', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`=' 票價： 1,200 、1,500 、1,800元', `source_url`='無資料', `image_url`='[]';
