INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a140b926b32418088f18e9', '2月高雄市電影館｜我們愛過一次【限制級】', '他們的愛，在慾望與愛恨之間糾纏… \r\n\r\n\r\n\r\n剛離開少年監護中心的威林頓，在同志電影院被成熟帥氣的男妓羅納多深深吸引，而面臨生存危機的羅納多，則需要威林頓加入陣容一起攬客，漸漸地，兩人的關係演變成一種矛盾的激情，像是夥伴，像是父子，像是朋友，又像是戀人……。\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n票價資訊\r\n票價：原價260元\r\n．影友優惠票200元：持有效期限內「高雄市電影館CLASSIC／GOLD+影友卡」購買者(進場請出示卡片)\r\n．愛心票130元：65歲以上人士（憑相關證件）、身心障礙人士（憑相關證件）與陪同者限一名享愛心票優惠\r\n\r\n\r\n\r\n注意事項\r\n◆內惟藝術中心 Reel two 2廳Ａ排、Ｂ排為單人沙發座\r\n◆現場購票可至官方網站查詢場館營業時間；年代售票網站(郵寄.便利商店取票)、全台年代售票端點、四大超商機台皆可購票\r\n\r\n◆CLASSIC／GOLD+會員之影友優惠票規範詳情請參閱官方網站公告\r\n\r\n◆場次開演後10分停止售票／20分後不得入場；持優惠票入場時須出示證件，如未出示須補足差額方可入場\r\n\r\n◆退票需於開演前30分臨櫃依規定辦理；換票視同退票，如需更換場次，請依退票方式辦理並酌收退票手續費10%\r\n\r\n◆取票手續費、轉帳手續費及郵資票券等額外手續費非屬票價部分不在退款範圍之內，需由購票人自行負擔\r\n\r\n◆本節目退換票請洽主辦單位-高雄市電影館07-5511211# 2015\r\n\r\n◆如不可抗因素致演出取消，購票者同意依據主辦方制定退票規則辦理', '高雄市電影館', '高雄市鹽埕區4鄰河西路10號', '2025-02-18 00:00:00', '2025-02-26 00:00:00', '高雄市電影館', 22.622671, 120.289122, '愛心票+130;影友優惠票+200;兒童票+208;原價+260', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月高雄市電影館｜我們愛過一次【限制級】', `description`='他們的愛，在慾望與愛恨之間糾纏… \r\n\r\n\r\n\r\n剛離開少年監護中心的威林頓，在同志電影院被成熟帥氣的男妓羅納多深深吸引，而面臨生存危機的羅納多，則需要威林頓加入陣容一起攬客，漸漸地，兩人的關係演變成一種矛盾的激情，像是夥伴，像是父子，像是朋友，又像是戀人……。\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n票價資訊\r\n票價：原價260元\r\n．影友優惠票200元：持有效期限內「高雄市電影館CLASSIC／GOLD+影友卡」購買者(進場請出示卡片)\r\n．愛心票130元：65歲以上人士（憑相關證件）、身心障礙人士（憑相關證件）與陪同者限一名享愛心票優惠\r\n\r\n\r\n\r\n注意事項\r\n◆內惟藝術中心 Reel two 2廳Ａ排、Ｂ排為單人沙發座\r\n◆現場購票可至官方網站查詢場館營業時間；年代售票網站(郵寄.便利商店取票)、全台年代售票端點、四大超商機台皆可購票\r\n\r\n◆CLASSIC／GOLD+會員之影友優惠票規範詳情請參閱官方網站公告\r\n\r\n◆場次開演後10分停止售票／20分後不得入場；持優惠票入場時須出示證件，如未出示須補足差額方可入場\r\n\r\n◆退票需於開演前30分臨櫃依規定辦理；換票視同退票，如需更換場次，請依退票方式辦理並酌收退票手續費10%\r\n\r\n◆取票手續費、轉帳手續費及郵資票券等額外手續費非屬票價部分不在退款範圍之內，需由購票人自行負擔\r\n\r\n◆本節目退換票請洽主辦單位-高雄市電影館07-5511211# 2015\r\n\r\n◆如不可抗因素致演出取消，購票者同意依據主辦方制定退票規則辦理', `organizer`='高雄市電影館', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-02-18 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='愛心票+130;影友優惠票+200;兒童票+208;原價+260', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a140b926b32418088f18ea', '2月高雄市電影館｜喵的奇幻漂流【普遍級】', '奧斯卡金獎名導吉勒摩戴托羅盛讚 獲獎無數年度必看動畫\r\n\r\n\r\n\r\n當世界即將走向末日，卻充斥著人類存在的痕跡。而當一隻黑貓的家園被大洪水摧毀後，登上一艘小船當作它的避難所，但卻發現船上住著各式各樣的動物，儘管他們無法溝通，但它們仍必須合作，穿梭於神秘的漂流世界，面對各種挑戰和危險。\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n票價資訊\r\n票價：原價260元\r\n．影友優惠票200元：持有效期限內「高雄市電影館CLASSIC／GOLD+影友卡」購買者(進場請出示卡片)\r\n．兒童票208元：未滿12歲兒童（憑相關證件）享全票八折優惠\r\n．愛心票130元：65歲以上人士（憑相關證件）、身心障礙人士（憑相關證件）與陪同者限一名享愛心票優惠\r\n\r\n《喵的奇幻漂流》限定！流體貓DIY 課程套票\r\n\r\n《喵的奇幻漂流》貓之日限定！喵然心動：流體貓DIY\r\n\r\n限量推出「流體貓咪 DIY 創作課程」\r\n\r\n用流動的色彩，親手打造專屬你的獨一無二喵星人！\r\n\r\n \r\n\r\n活動詳情及購票請至 《喵的奇幻漂流》限定！流體貓DIY 課程套票\r\n\r\n\r\n\r\n\r\n注意事項\r\n◆內惟藝術中心 Reel two 2廳Ａ排、Ｂ排為單人沙發座\r\n◆現場購票可至官方網站查詢場館營業時間；年代售票網站(郵寄.便利商店取票)、全台年代售票端點、四大超商機台皆可購票\r\n\r\n◆CLASSIC／GOLD+會員之影友優惠票規範詳情請參閱官方網站公告\r\n\r\n◆場次開演後10分停止售票／20分後不得入場；持優惠票入場時須出示證件，如未出示須補足差額方可入場\r\n\r\n◆退票需於開演前30分臨櫃依規定辦理；換票視同退票，如需更換場次，請依退票方式辦理並酌收退票手續費10%\r\n\r\n◆取票手續費、轉帳手續費及郵資票券等額外手續費非屬票價部分不在退款範圍之內，需由購票人自行負擔\r\n\r\n◆本節目退換票請洽主辦單位-高雄市電影館07-5511211# 2015\r\n\r\n◆如不可抗因素致演出取消，購票者同意依據主辦方制定退票規則辦理', '高雄市電影館', '高雄市鹽埕區4鄰河西路10號', '2025-02-21 00:00:00', '2025-02-26 00:00:00', '高雄市電影館', 22.622671, 120.289122, '愛心票+130;影友優惠票+200;兒童票+208;原價+260', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月高雄市電影館｜喵的奇幻漂流【普遍級】', `description`='奧斯卡金獎名導吉勒摩戴托羅盛讚 獲獎無數年度必看動畫\r\n\r\n\r\n\r\n當世界即將走向末日，卻充斥著人類存在的痕跡。而當一隻黑貓的家園被大洪水摧毀後，登上一艘小船當作它的避難所，但卻發現船上住著各式各樣的動物，儘管他們無法溝通，但它們仍必須合作，穿梭於神秘的漂流世界，面對各種挑戰和危險。\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n票價資訊\r\n票價：原價260元\r\n．影友優惠票200元：持有效期限內「高雄市電影館CLASSIC／GOLD+影友卡」購買者(進場請出示卡片)\r\n．兒童票208元：未滿12歲兒童（憑相關證件）享全票八折優惠\r\n．愛心票130元：65歲以上人士（憑相關證件）、身心障礙人士（憑相關證件）與陪同者限一名享愛心票優惠\r\n\r\n《喵的奇幻漂流》限定！流體貓DIY 課程套票\r\n\r\n《喵的奇幻漂流》貓之日限定！喵然心動：流體貓DIY\r\n\r\n限量推出「流體貓咪 DIY 創作課程」\r\n\r\n用流動的色彩，親手打造專屬你的獨一無二喵星人！\r\n\r\n \r\n\r\n活動詳情及購票請至 《喵的奇幻漂流》限定！流體貓DIY 課程套票\r\n\r\n\r\n\r\n\r\n注意事項\r\n◆內惟