INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2895126b32418088f190a', '《GIFT x 記憶》近藤悟攝影個展', '在這場展覽中，藝術家透過相機鏡頭，試圖捕捉那些笑臉背後的故事、歲月的痕跡，與每一個瞬間的力量。每一張照片，都像是一段未完成的故事，邀請觀者走進那個充滿溫暖與深情的世界，感受時間的流動與生命的韌性。\r\n每一張笑臉、每一段記憶，都在無聲地訴說著人生的真諦。', '新北市政府文化局', '新北市板橋區漢生東路166號3樓', '2025-01-01 00:00:00', '2025-02-27 00:00:00', '新板藝廊', 25.01186453, 121.4579675, '無資料', 'https://www.facebook.com/newtaipei.gallery/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《GIFT x 記憶》近藤悟攝影個展', `description`='在這場展覽中，藝術家透過相機鏡頭，試圖捕捉那些笑臉背後的故事、歲月的痕跡，與每一個瞬間的力量。每一張照片，都像是一段未完成的故事，邀請觀者走進那個充滿溫暖與深情的世界，感受時間的流動與生命的韌性。\r\n每一張笑臉、每一段記憶，都在無聲地訴說著人生的真諦。', `organizer`='新北市政府文化局', `address`='新北市板橋區漢生東路166號3樓', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='新板藝廊', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='https://www.facebook.com/newtaipei.gallery/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2895326b32418088f190c', '流光憶彩－粉彩藝術聯展', '「流光憶彩」-在流動的時光中，用色彩記憶生活中的感動。此聯展是由九位畫家呈現多年來的作品，展出的內容多元且豐富。粉彩的本質可輕柔、可厚重，有細緻的寫實，也有那曾經的印象，此外，還可以與其他媒材做結合，展現不同的風貌。多幅作品在國內外的比賽得過不少獎項，也曾到海外展出，與他國藝術家多有交流，世界各國都看見了臺灣，歡迎蒞臨賞畫。', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-03-14 00:00:00', '2025-03-25 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='流光憶彩－粉彩藝術聯展', `description`='「流光憶彩」-在流動的時光中，用色彩記憶生活中的感動。此聯展是由九位畫家呈現多年來的作品，展出的內容多元且豐富。粉彩的本質可輕柔、可厚重，有細緻的寫實，也有那曾經的印象，此外，還可以與其他媒材做結合，展現不同的風貌。多幅作品在國內外的比賽得過不少獎項，也曾到海外展出，與他國藝術家多有交流，世界各國都看見了臺灣，歡迎蒞臨賞畫。', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2895826b32418088f190d', '2月高雄市電影館｜粗獷派建築師 The Brutalist【輔12級】', '《戰地琴人》安卓亞布洛迪 強勢橫掃各大影展\r\n\r\n★ 2024 威尼斯影展 最佳導演獎\r\n★ 2025 金球獎 戲劇類最佳影片、導演、男主角獎 提名\r\n\r\n富有遠見的建築師拉斯洛托特在戰後逃離歐洲，來到美國重建他的生活、工作，以及他與妻子艾莉莎貝的婚姻生活，在戰爭期間，兩人由於邊境和政權的變化一度被迫分開。在這陌生的新國度，拉斯洛定居在賓州，知名富商哈里森李范布倫相當欣賞他的建築才華，然而權力和機會需要付出沉重的代價。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優惠票+208;全票+260', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月高雄市電影館｜粗獷派建築師 The Brutalist【輔12級】', `description`='《戰地琴人》安卓亞布洛迪 強勢橫掃各大影展\r\n\r\n★ 2024 威尼斯影展 最佳導演獎\r\n★ 2025 金球獎 戲劇類最佳影片、導演、男主角獎 提名\r\n\r\n富有遠見的建築師拉斯洛托特在戰後逃離歐洲，來到美國重建他的生活、工作，以及他與妻子艾莉莎貝的婚姻生活，在戰爭期間，兩人由於邊境和政權的變化一度被迫分開。在這陌生的新國度，拉斯洛定居在賓州，知名富商哈里森李范布倫相當欣賞他的建築才華，然而權力和機會需要付出沉重的代價。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優惠票+208;全票+260', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2896326b32418088f1910', '信仰與傳承－蓬萊山道教文化特展', '本次特展由蓬萊山洞玄道院統籌，以蓬萊山道教的修行路徑為主題，通過珍貴文物、經典典籍與當代實踐的對照，全面呈現道教信仰修持的傳統與文化精髓。展覽深入探索歷代祖師的精神傳承，融匯道教的信仰、美學與生活智慧，帶領觀者感受蓬萊山深厚的文化底蘊與超然的精神力量。', '臺灣傳統文化藝術教育協會', '臺南市中西區民權路二段30號', '2025-02-09 00:00:00', '2025-03-02 00:00:00', '臺南市吳園藝文中心', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='信仰與傳承－蓬萊山道教文化特展', `description`='本次特展由蓬萊山洞玄道院統籌，以蓬萊山道教的修行路徑為主題，通過珍貴文物、經典典籍與當代實踐的對照，全面呈現道教信仰修持的傳統與文化精髓。展覽深入探索歷代祖師的精神傳承，融匯道教的信仰、美學與生活智慧，帶領觀者感受蓬萊山深厚的文化底蘊與超然的精神力量。', `organizer`='臺灣傳統文化藝術教育協會', `address`='臺南市中西區民權路二段30號', `start_date`='2025-02-09 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='臺南市吳園藝文中心', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2896926b32418088f1916', '總爺藝文中心－【特展】《迷霧-陳世憲意象書法展》', '陳世憲是一個具有強烈在地性又兼具國際視野的書法家，其書法作品突破傳統的書畫，從文字的書寫可見完整的創作故事，匯聚意象、美感及創意，在書法界是非常難能可貴的成就。\r\n老師的作品一筆一畫之間都隱藏著背後的故事，體現了「詩中有畫、畫中有詩」，大家知道這幅「正義」背後藏著怎樣的故事嗎?\r\n「正義 是存在的，但是時常模糊！」\r\n這次作品正如同此次展覽的主題，想藉由墨色表現出社會上人與人間的延伸、模糊與豁達，邀請參觀者一起走入「迷霧」之中。', '臺南市政府文化局', '臺南市麻豆區總爺5號', '2025-01-17 00:00:00', '2025-05-25 00:00:00', '臺南市總爺藝文中心', 23.18248033, 120.241308, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總爺藝文中心－【特展】《迷霧-陳世憲意象書法展》', `description`='陳世憲是一個具有強烈在地性又兼具國際視野的書法家，其書法作品突破傳統的書畫，從文字的書寫可見完整的創作故事，匯聚意象、美感及創意，在書法界是非常難能可貴的成就。\r\n老師的作品一筆一畫之間都隱藏著背後的故事，體現了「詩中有畫、畫中有詩」，大家知道這幅「正義」背後藏著怎樣的故事嗎?\r\n「正義 是存在的，但是時常模糊！」\r\n這次作品正如同此次展覽的主題，想藉由墨色表現出社會上人與人間的延伸、模糊與豁達，邀請參觀者一起走入「迷霧」之中。', `organizer`='臺南市政府文化局', `address`='臺南市麻豆區總爺5號', `start_date`='2025-01-17 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='臺南市總爺藝文中心', `latitude`=23.18248033, `longitude`=120.241308, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
