INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2896b26b32418088f1918', '陳振芳傳統工藝螺鈿漆藝傳習課程進階班', '延續113年舉行陳振芳傳統工藝螺鈿漆藝推廣傳習工作坊初階課程，本次新竹縣螺鈿工藝保存者陳振芳老師將帶領學員進一步學習螺鈿工藝木質地鑲嵌技法，練習雕刻木材、貝殼鑲嵌工作、補土製作及利用天然漆製塗裝，製作精美之螺鈿木質工藝作品。', '新竹縣政府文化局', '新竹縣竹北市縣政九路146號', '2025-01-04 00:00:00', '2025-03-29 00:00:00', '新竹縣政府文化局', 24.83816209, 120.9948704, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陳振芳傳統工藝螺鈿漆藝傳習課程進階班', `description`='延續113年舉行陳振芳傳統工藝螺鈿漆藝推廣傳習工作坊初階課程，本次新竹縣螺鈿工藝保存者陳振芳老師將帶領學員進一步學習螺鈿工藝木質地鑲嵌技法，練習雕刻木材、貝殼鑲嵌工作、補土製作及利用天然漆製塗裝，製作精美之螺鈿木質工藝作品。', `organizer`='新竹縣政府文化局', `address`='新竹縣竹北市縣政九路146號', `start_date`='2025-01-04 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='新竹縣政府文化局', `latitude`=24.83816209, `longitude`=120.9948704, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
