INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2896b26b32418088f191a', '無資料', '假日電影播放\r\n3/2-笑星撞地球\r\n3/9-變身特務\r\n3/16-嚕嚕米\r\n3/23-冰雪奇緣2\r\n3/30-外星人來了', '臺南市龍崎區圖書館', '臺南市龍崎區新市子38號', '臺南市龍崎區圖書館', 22.95482276, 120.3869373, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='假日電影播放\r\n3/2-笑星撞地球\r\n3/9-變身特務\r\n3/16-嚕嚕米\r\n3/23-冰雪奇緣2\r\n3/30-外星人來了', `organizer`='臺南市龍崎區圖書館', `address`='臺南市龍崎區新市子38號', `location`='臺南市龍崎區圖書館', `latitude`=22.95482276, `longitude`=120.3869373, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2896b26b32418088f191b', '樹人國小版畫展•有板有眼看菊島', '澎湖，這座美麗的島嶼，不僅擁有壯麗的自然風光，更蘊藏著豐富的人文歷史。透過駐校藝術家吳鴻滄老師的藝術引導，樹人國小15位學子展開了一趟充滿驚奇的澎湖走讀之旅。他們用畫筆記錄下沿途所見所感，將澎湖的獨特魅力轉化為一幅幅精緻的版畫作品。「有板有眼看菊島」成果展，讓孩子們從走讀創作中與澎湖建立深厚的連結，更體現了藝術與教育的結合。誠摯邀請您蒞臨觀展，一同欣賞孩子們的創作，感受澎湖的獨特魅力！ ', '臺南市政府教育局', '臺南市新營區民治路36號', '2025-02-08 00:00:00', '2025-02-25 00:00:00', '臺南市民治市政中心', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樹人國小版畫展•有板有眼看菊島', `description`='澎湖，這座美麗的島嶼，不僅擁有壯麗的自然風光，更蘊藏著豐富的人文歷史。透過駐校藝術家吳鴻滄老師的藝術引導，樹人國小15位學子展開了一趟充滿驚奇的澎湖走讀之旅。他們用畫筆記錄下沿途所見所感，將澎湖的獨特魅力轉化為一幅幅精緻的版畫作品。「有板有眼看菊島」成果展，讓孩子們從走讀創作中與澎湖建立深厚的連結，更體現了藝術與教育的結合。誠摯邀請您蒞臨觀展，一同欣賞孩子們的創作，感受澎湖的獨特魅力！ ', `organizer`='臺南市政府教育局', `address`='臺南市新營區民治路36號', `start_date`='2025-02-08 00:00:00', `end_date`='2025-02-25 00:00:00', `location`='臺南市民治市政中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2896f26b32418088f191d', '無資料', '於4樓區域撥放館員精選影片，提供讀者民眾一假日休閒選擇，場次如下：\r\n2月9日《幸福路上》(普)\r\n2月23日《喵的詐騙集團》(普)\r\n', '臺南市東區林森圖書館', '臺南市東區林森路二段46號', '臺南市東區林森圖書館', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='於4樓區域撥放館員精選影片，提供讀者民眾一假日休閒選擇，場次如下：\r\n2月9日《幸福路上》(普)\r\n2月23日《喵的詐騙集團》(普)\r\n', `organizer`='臺南市東區林森圖書館', `address`='臺南市東區林森路二段46號', `location`='臺南市東區林森圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2896f26b32418088f191e', '｜東區林森圖書館｜生態攝影常設展 ', '本館與荒野保護協會-台南分會合作，於本館公共樓梯間展示各攝影作家精彩生態攝影作品，藉由藝術美學傳達環境保護與重視生態觀念。', '臺南市東區林森圖書館', '臺南市東區林森路二段46號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南市東區林森圖書館', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='｜東區林森圖書館｜生態攝影常設展 ', `description`='本館與荒野保護協會-台南分會合作，於本館公共樓梯間展示各攝影作家精彩生態攝影作品，藉由藝術美學傳達環境保護與重視生態觀念。', `organizer`='臺南市東區林森圖書館', `address`='臺南市東區林森路二段46號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市東區林森圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2896f26b32418088f191f', '親子故事時光-2月中文說故事', '2/9(日)10:00 - 10:30 貪心的草莓大叔 景芳、小魚兒\r\n\r\n2/12(三)10:00 - 10:30 壽司買衣服 大角羊、麻雀\r\n\r\n2/16(日)10:00 - 10:30 羅倫斯和蘇菲雅 佳佳、巫拉拉\r\n\r\n2/19(三)10:00 - 10:30 吱嚕吱嚕撲通1 2 3 噗嚕嚕\r\n餅乾、燕子\r\n2/23(日)10:00 - 10:30 青蛙出門去\r\n                森林裡有多少顆樹 莉莉、雪碧、慧華\r\n\r\n2/23(日)14:00 - 15:00 台語猜燈謎活動 莉莉、Apple、麻雀、小花馬迷、巫拉拉、小籠包、曉薇阿姨\r\n\r\n2/26(三)10:00 - 10:30 豬爸爸賺力氣 蝴蝶結、安安\r\n', '臺南市立圖書館-公園總館', '臺南市北區公園北路3號', '2025-02-09 00:00:00', '2025-02-26 00:00:00', '臺南市立圖書館(北區)', 23.01012179, 120.2068735, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='親子故事時光-2月中文說故事', `description`='2/9(日)10:00 - 10:30 貪心的草莓大叔 景芳、小魚兒\r\n\r\n2/12(三)10:00 - 10:30 壽司買衣服 大角羊、麻雀\r\n\r\n2/16(日)10:00 - 10:30 羅倫斯和蘇菲雅 佳佳、巫拉拉\r\n\r\n2/19(三)10:00 - 10:30 吱嚕吱嚕撲通1 2 3 噗嚕嚕\r\n餅乾、燕子\r\n2/23(日)10:00 - 10:30 青蛙出門去\r\n                森林裡有多少顆樹 莉莉、雪碧、慧華\r\n\r\n2/23(日)14:00 - 15:00 台語猜燈謎活動 莉莉、Apple、麻雀、小花馬迷、巫拉拉、小籠包、曉薇阿姨\r\n\r\n2/26(三)10:00 - 10:30 豬爸爸賺力氣 蝴蝶結、安安\r\n', `organizer`='臺南市立圖書館-公園總館', `address`='臺南市北區公園北路3號', `start_date`='2025-02-09 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='臺南市立圖書館(北區)', `latitude`=23.01012179, `longitude`=120.2068735, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897126b32418088f1920', '2025台灣燈會-畫「籠」點「青」—色彩燈籠共創作品展', '邀請藝術家張智宇與在地學校桃園市中壢區青園國民小學師生，就大園尖山考古展示館、青埔、大園地景文化歷史，共創色彩燈籠，並將作品佈置於大園尖山考古展示館入口處，營造色彩燈廊。', '桃園市政府文化局', '桃園市大園區28鄰大仁路100號 (橫山書法藝術館C棟B1)', '2025-01-21 00:00:00', '2025-03-02 00:00:00', '大園尖山考古展示館', 25.06384709, 121.21177, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會-畫「籠」點「青」—色彩燈籠共創作品展', `description`='邀請藝術家張智宇與在地學校桃園市中壢區青園國民小學師生，就大園尖山考古展示館、青埔、大園地景文化歷史，共創色彩燈籠，並將作品佈置於大園尖山考古展示館入口處，營造色彩燈廊。', `organizer`='桃園市政府文化局', `address`='桃園市大園區28鄰大仁路100號 (橫山書法藝術館C棟B1)', `start_date`='2025-01-21 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='大園尖山考古展示館', `latitude`=25.06384709, `longitude`=121.21177, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897126b32418088f1921', '總爺藝文中心－【特展】《信仰的畫卷一楊義勳個展誌》', '府城為萬神之鄉與藝陣之都,也是先民渡台之地;\r\n渡台之際先民將故卿神祉供奉於船上,以求安渡險惡的黑水溝。安抵後建廟祭祀,以安定民心並具規範道德之社教功能,亦具驅邪,除瘟之神力,進而演化成臺灣特有之廟會文化。\r\n作者以傳承之志,把臺灣廟會文化一系列呈現,將已消失或漸失傳的藝陣繪出,讓後人得以見到先民智慧,宗教文化及藝陣之美。', '臺南市政府文化局', '臺南市麻豆區總爺5號', '2025-01-23 00:00:00', '2025-04-27 00:00:00', '臺南市總爺藝文中心', 23.18248033, 120.241308, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總爺藝文中心－【特展】《信仰的畫卷一楊義勳個展誌》', `description`='府城為萬神之鄉與藝陣之都,也是先民渡台之地;\r\n渡台之際先民將故卿神祉供奉於船上,以求安渡險惡的黑水溝。安抵後建廟祭祀,以安定民心並具規範道德之社教功能,亦具驅邪,除瘟之神力,進而演化成臺灣特有之廟會文化。\r\n作者以傳承之志,把臺灣廟會文化一系列呈現,將已消失或漸失傳的藝陣繪出,讓後人得以見到先民智慧,宗教文化及藝陣之美。', `organizer`='臺南市政府文化局', `address`='臺南市麻豆區總爺5號', `start_date`='2025-01-23 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺南市總爺藝文中心', `latitude`=23.18248033, `longitude`=120.241308, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897826b32418088f1924', '喜樹圖書館:「追本溯源」本土語言書展', '展示本土語言相關圖書，幫助民眾了解並學習自己的母語，激發對文化根源的認同感。透過書展讓更多人意識到本土語言的重要性，並為語言文化的保存與發展貢獻力量。\r\n凡於活動期間完成以下其中一項，即可至櫃檯領取便利貼一份。數量有限，送完為止。\r\n1.借閱５本(內含1本土圖書展示區）書籍。\r\n2.於喜樹圖書館FB此貼文按讚並上傳書展照片。', '臺南市南區喜樹圖書館', '臺南市南區喜樹路179號', '2025-01-17 00:00:00', '2025-02-27 00:00:00', '臺南市南區喜樹圖書館', 22.95561863, 120.1903743, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='喜樹圖書館:「追本溯源」本土語言書展', `description`='展示本土語言相關圖書，幫助民眾了解並學習自己的母語，激發對文化根源的認同感。透過書展讓更多人意識到本土語言的重要性，並為語言文化的保存與發展貢獻力量。\r\n凡於活動期間完成以下其中一項，即可至櫃檯領取便利貼一份。數量有限，送完為止。\r\n1.借閱５本(內含1本土圖書展示區）書籍。\r\n2.於喜樹圖書館FB此貼文按讚並上傳書展照片。', `organizer`='臺南市南區喜樹圖書館', `address`='臺南市南區喜樹路179號', `start_date`='2025-01-17 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺南市南區喜樹圖書館', `latitude`=22.95561863, `longitude`=120.1903743, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897826b32418088f1926', '無資料', '假日電影院(免報名.自由入座）\r\n2月09日 電影屁屁偵探(普遍級)\r\n2月23日 哆啦A夢大雄的南極冰天雪地大冒險 (普遍級)\r\n\r\n地點：喜樹圖書館三樓多功能室', '臺南市南區喜樹圖書館', '臺南市南區喜樹路179號', '臺南市南區喜樹圖書館', 22.95561863, 120.1903743, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='假日電影院(免報名.自由入座）\r\n2月09日 電影屁屁偵探(普遍級)\r\n2月23日 哆啦A夢大雄的南極冰天雪地大冒險 (普遍級)\r\n\r\n地點：喜樹圖書館三樓多功能室', `organizer`='臺南市南區喜樹圖書館', `address`='臺南市南區喜樹路179號', `location`='臺南市南區喜樹圖書館', `latitude`=22.95561863, `longitude`=120.1903743, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897826b32418088f1927', '2月高雄市電影館｜悲情城市 4K數位版	A City of Sadness 【輔12級】', '「在今天以前，這個故事，你聽不到，也不能講…。」\r\n★ 1989 威尼斯影展 金獅獎 \r\n★ 1989 金馬獎 最佳導演獎、最佳男主角獎\r\n\r\n1945年日本戰敗，是日基隆林氏家族大哥文雄喜獲一子，取名光明。林家四兄弟，大哥是地方角頭，經營酒家；二哥於戰時被徵召至南洋，生死未卜；三哥文良戰後返台，活動於上海人的非法生意；四弟文清後天聾啞，在金瓜石經營相館，結識知青寬榮的妹妹寬美。然而命運乖舛，國軍入駐後臺灣因二二八事件實施戒嚴，知識青年受迫潛藏山中，林家三兄弟亦各自遭遇不幸。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-02-27 00:00:00', '2025-02-28 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;全票+260', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月高雄市電影館｜悲情城市 4K數位版	A City of Sadness 【輔12級】', `description`='「在今天以前，這個故事，你聽不到，也不能講…。」\r\n★ 1989 威尼斯影展 金獅獎 \r\n★ 1989 金馬獎 最佳導演獎、最佳男主角獎\r\n\r\n1945年日本戰敗，是日基隆林氏家族大哥文雄喜獲一子，取名光明。林家四兄弟，大哥是地方角頭，經營酒家；二哥於戰時被徵召至南洋，生死未卜；三哥文良戰後返台，活動於上海人的非法生意；四弟文清後天聾啞，在金瓜石經營相館，結識知青寬榮的妹妹寬美。然而命運乖舛，國軍入駐後臺灣因二二八事件實施戒嚴，知識青年受迫潛藏山中，林家三兄弟亦各自遭遇不幸。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-02-27 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;全票+260', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897826b32418088f1929', '2月高雄市電影館｜艾諾拉 Anora 【限制級】', '《歡迎光臨奇幻城堡》西恩貝克登頂坎城，力指奧斯卡 \r\n\r\n來自布魯克林的脫衣舞孃艾諾拉，在俱樂部遇見來美國度假的俄國富二代伊凡，深深為艾諾拉著迷的伊凡，在她一週的陪伴後衝動結婚。當這個消息傳回俄羅斯時，怒不可遏的伊凡父母決定對這段婚姻強硬喊停，艾諾拉眼看「飛上枝頭當鳳凰」的美夢就要畫下句點，決定拿出嗆辣本事，抗爭到底！', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-02-14 00:00:00', '2025-02-26 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;全票+260', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月高雄市電影館｜艾諾拉 Anora 【限制級】', `description`='《歡迎光臨奇幻城堡》西恩貝克登頂坎城，力指奧斯卡 \r\n\r\n來自布魯克林的脫衣舞孃艾諾拉，在俱樂部遇見來美國度假的俄國富二代伊凡，深深為艾諾拉著迷的伊凡，在她一週的陪伴後衝動結婚。當這個消息傳回俄羅斯時，怒不可遏的伊凡父母決定對這段婚姻強硬喊停，艾諾拉眼看「飛上枝頭當鳳凰」的美夢就要畫下句點，決定拿出嗆辣本事，抗爭到底！', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-02-14 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;全票+260', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897826b32418088f192d', '2月高雄市電影館｜吸血鬼：諾斯費拉圖  Nosferatu 【輔15級】', '「站在我面前的就是死神，但我未曾如此快樂過。」 \r\n\r\n羅柏艾格斯自編自導，再現招牌哥德式驚悚。《吸血鬼：諾斯費拉圖》翻拍自1922年德國無聲電影，講述了一個被鬼附身的年輕女子和迷戀她的可怕吸血鬼之間的癡戀，當她的靈魂慢慢被「吸血鬼」諾斯費拉圖誘惑，最終屈服於他黑暗中的邪惡輪廓。\r\n', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-02-21 00:00:00', '2025-02-28 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;全票+260', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月高雄市電影館｜吸血鬼：諾斯費拉圖  Nosferatu 【輔15級】', `description`='「站在我面前的就是死神，但我未曾如此快樂過。」 \r\n\r\n羅柏艾格斯自編自導，再現招牌哥德式驚悚。《吸血鬼：諾斯費拉圖》翻拍自1922年德國無聲電影，講述了一個被鬼附身的年輕女子和迷戀她的可怕吸血鬼之間的癡戀，當她的靈魂慢慢被「吸血鬼」諾斯費拉圖誘惑，最終屈服於他黑暗中的邪惡輪廓。\r\n', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-02-21 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;全票+260', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897826b32418088f192e', '無資料', '奧斯卡金獎名導吉勒摩戴托羅盛讚 獲獎無數年度必看動畫\r\n★ 2024 安錫國際動畫影展 評審團獎、最佳原創音樂獎\r\n★ 2025 金球獎 最佳動畫長片獎\r\n\r\n當世界即將走向末日，卻充斥著人類存在的痕跡。而當一隻黑貓的家園被大洪水摧毀後，登上一艘小船當作它的避難所，但卻發現船上住著各式各樣的動物，儘管他們無法溝通，但它們仍必須合作，穿梭於神秘的漂流世界，面對各種挑戰和危險。\r\n\r\n', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '內惟藝術中心', 22.65019525, 120.274163, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='奧斯卡金獎名導吉勒摩戴托羅盛讚 獲獎無數年度必看動畫\r\n★ 2024 安錫國際動畫影展 評審團獎、最佳原創音樂獎\r\n★ 2025 金球獎 最佳動畫長片獎\r\n\r\n當世界即將走向末日，卻充斥著人類存在的痕跡。而當一隻黑貓的家園被大洪水摧毀後，登上一艘小船當作它的避難所，但卻發現船上住著各式各樣的動物，儘管他們無法溝通，但它們仍必須合作，穿梭於神秘的漂流世界，面對各種挑戰和危險。\r\n\r\n', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897926b32418088f192f', '2月高雄市電影館｜劇場版派遣女醫 X FINAL Doctor X: The Movie 【保護級】', '所有角色全數回歸 大門未知子登上大銀幕華麗謝幕！\r\n\r\n由米倉涼子主演的國民級話題神劇《派遣女醫X》自2012年開始播出至今，終於迎來最終章，前所未有的危機即將降臨，「從來不會失敗」的外科醫生大門未知子該如何應對？同時，他未知的過去也即將被解開。\r\n\r\n', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-02-21 00:00:00', '2025-02-28 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;全票+260', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月高雄市電影館｜劇場版派遣女醫 X FINAL Doctor X: The Movie 【保護級】', `description`='所有角色全數回歸 大門未知子登上大銀幕華麗謝幕！\r\n\r\n由米倉涼子主演的國民級話題神劇《派遣女醫X》自2012年開始播出至今，終於迎來最終章，前所未有的危機即將降臨，「從來不會失敗」的外科醫生大門未知子該如何應對？同時，他未知的過去也即將被解開。\r\n\r\n', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-02-21 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;全票+260', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897926b32418088f1930', '無資料', '堂本剛 ✕ 綾野剛 ✕ 吉岡里帆 ✕ 小林聰美 讓你的心◯滾滾地開始轉動\r\n★ 2024 台灣國際紀錄片影展 國際競賽評審團大獎\r\n★ 2023 山形國際紀錄片影展 評審團特別獎\r\n\r\n畢業於美術大學的澤田，無法靠藝術維生，只能擔任人氣現代美術家的助理，淡然做著被指派的事。某天，上班途中的意外讓他丟了工作。回到房間的澤田觀察著地上的螞蟻，受到引領畫出了一個◯，這個◯在不知不覺間於社群網路瘋傳，更讓他一夜成名，成為了來歷不明的藝術家。\r\n', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '內惟藝術中心', 22.65019525, 120.274163, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='堂本剛 ✕ 綾野剛 ✕ 吉岡里帆 ✕ 小林聰美 讓你的心◯滾滾地開始轉動\r\n★ 2024 台灣國際紀錄片影展 國際競賽評審團大獎\r\n★ 2023 山形國際紀錄片影展 評審團特別獎\r\n\r\n畢業於美術大學的澤田，無法靠藝術維生，只能擔任人氣現代美術家的助理，淡然做著被指派的事。某天，上班途中的意外讓他丟了工作。回到房間的澤田觀察著地上的螞蟻，受到引領畫出了一個◯，這個◯在不知不覺間於社群網路瘋傳，更讓他一夜成名，成為了來歷不明的藝術家。\r\n', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897926b32418088f1931', '2月高雄市電影館｜Thunderbolt Fantasy 東離劍遊紀 最終章【保護級】', '驚天動地的幻想奇譚，將在此正式完結！\r\n\r\n凜雪鴉、殤不患、裂魔弦聯手擊敗魔神刑亥，但浪巫謠仍囚於魔王城爐心，被夢魘折磨。為救浪巫謠，嘲風在禍世螟蝗點化下成為神蝗盟法師・葬心嬌，再次踏入魔界。魔王掀起第二次窮暮之戰，魔界大軍來襲，欲焚盡人界，人類以護印師為首奮勇迎戰！\r\n', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-02-21 00:00:00', '2025-02-26 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;全票+260', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月高雄市電影館｜Thunderbolt Fantasy 東離劍遊紀 最終章【保護級】', `description`='驚天動地的幻想奇譚，將在此正式完結！\r\n\r\n凜雪鴉、殤不患、裂魔弦聯手擊敗魔神刑亥，但浪巫謠仍囚於魔王城爐心，被夢魘折磨。為救浪巫謠，嘲風在禍世螟蝗點化下成為神蝗盟法師・葬心嬌，再次踏入魔界。魔王掀起第二次窮暮之戰，魔界大軍來襲，欲焚盡人界，人類以護印師為首奮勇迎戰！\r\n', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-02-21 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;全票+260', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897926b32418088f1932', '2月高雄市電影館｜火線追緝令 Se7en【輔12】', '大衛芬奇驚悚犯罪代表作 30周年4K修復經典重映\r\n★ 1996 奧斯卡金像獎 最佳剪輯獎提名\r\n\r\n一位即將退休的警探和他的接任者，合作調查由宗教儀式「七大罪」布局之連環謀殺案，他們試圖在兇手成功謀殺七名受害者前緝拿他歸案，然而事實的真相以及人性黑暗面讓他們難以承受。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-02-27 00:00:00', '2025-02-28 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;全票+260', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月高雄市電影館｜火線追緝令 Se7en【輔12】', `description`='大衛芬奇驚悚犯罪代表作 30周年4K修復經典重映\r\n★ 1996 奧斯卡金像獎 最佳剪輯獎提名\r\n\r\n一位即將退休的警探和他的接任者，合作調查由宗教儀式「七大罪」布局之連環謀殺案，他們試圖在兇手成功謀殺七名受害者前緝拿他歸案，然而事實的真相以及人性黑暗面讓他們難以承受。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-02-27 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;全票+260', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897926b32418088f1933', '2月高雄市電影館｜夜校女生 The Uniform【普遍級】', '「日校是太陽，夜校是月亮。」\r\n\r\n1997年，小愛（陳姸霏 飾）在升學壓力下進入體制特殊的「一女中夜校」就讀。但夜校生總被認為不如日校生優秀，造成她極度自卑。她與日校好友敏敏（項婕如 飾）一起喜歡上男校的資優生路克（邱以太 飾），持續假冒成日校生，並把自己推向巨大的謊言坑洞，直到謊言被揭穿。\r\n', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;全票+260', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月高雄市電影館｜夜校女生 The Uniform【普遍級】', `description`='「日校是太陽，夜校是月亮。」\r\n\r\n1997年，小愛（陳姸霏 飾）在升學壓力下進入體制特殊的「一女中夜校」就讀。但夜校生總被認為不如日校生優秀，造成她極度自卑。她與日校好友敏敏（項婕如 飾）一起喜歡上男校的資優生路克（邱以太 飾），持續假冒成日校生，並把自己推向巨大的謊言坑洞，直到謊言被揭穿。\r\n', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;全票+260', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897a26b32418088f1935', '打開畫匣子－美術在高雄 《花非花 花系列-葉宸君創作展》', '策 展 人：高師大跨藝所碩士 曾琬婷\r\n    葉宸君印象最深刻的童年，是父親喜歡把庭院種滿五顏六色的鮮花，從那時起她的童年增添了許多色彩，比如冬天的花有哪些種類？春天的花是什麼?在夏天季節白天可看到許多蝴蝶、蜜蜂及小瓢蟲在花園裡飛來飛去，群蝶飛舞的深刻印象讓葉宸君看了很興奮、喜歡。\r\n    民國70年結婚，丈夫從事繪畫教學，葉宸君空暇之餘會去開辦的畫室幫忙，看見許多國中小在職校長、老師來學油畫，他們的成果讓她好感動，心想大家大老遠的來學繪畫，自己如果沒有參與學習，以後和丈夫會背道而馳、沒話可說，於是毅然決然跟丈夫說喜歡油畫的感覺，也想學畫畫！\r\n    當時葉宸君種了許多玫瑰花，丈夫就說去剪一朵玫瑰插在透明玻璃杯開始畫鉛筆素描。由於丈夫的耐心鼓勵，讓她更有信心，就一頭栽進去繪畫的世界裡。葉宸君的公公也是從事美術教育的國小老師，每次看到葉宸君的畫作都會說好棒！繼續！讓她很開心及更有信心，每天晚上忙完了就從八點開始畫，幾乎畫到凌晨，真的渾然忘我，都不感覺疲憊，越畫越有感受。\r\n    葉宸君認為畫圖能夠整理思緒、反省自我，更可貴的是內在覺醒，能夠更清楚自己在做什麼，達到感官與內在的平衡。她體會到「靜」得下是一種享受「單獨」的可貴，與自己內在的小孩溝通成長，能夠畫自己心靈世界所傳達的訊息，是一種享受與幸福，感受它的真善美是如此的清徹美好，彷彿從內在喚醒真正的自我，是那麼的舒適、平和，每完成一幅創作是那麼喜悅和滿足，只要動筆去感受、去突破，又是一種新的契機。\r\n', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-02-19 00:00:00', '2025-03-02 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4083', '[]') ON DUPLICATE KEY UPDATE `activity_name`='打開畫匣子－美術在高雄 《花非花 花系列-葉宸君創作展》', `description`='策 展 人：高師大跨藝所碩士 曾琬婷\r\n    葉宸君印象最深刻的童年，是父親喜歡把庭院種滿五顏六色的鮮花，從那時起她的童年增添了許多色彩，比如冬天的花有哪些種類？春天的花是什麼?在夏天季節白天可看到許多蝴蝶、蜜蜂及小瓢蟲在花園裡飛來飛去，群蝶飛舞的深刻印象讓葉宸君看了很興奮、喜歡。\r\n    民國70年結婚，丈夫從事繪畫教學，葉宸君空暇之餘會去開辦的畫室幫忙，看見許多國中小在職校長、老師來學油畫，他們的成果讓她好感動，心想大家大老遠的來學繪畫，自己如果沒有參與學習，以後和丈夫會背道而馳、沒話可說，於是毅然決然跟丈夫說喜歡油畫的感覺，也想學畫畫！\r\n    當時葉宸君種了許多玫瑰花，丈夫就說去剪一朵玫瑰插在透明玻璃杯開始畫鉛筆素描。由於丈夫的耐心鼓勵，讓她更有信心，就一頭栽進去繪畫的世界裡。葉宸君的公公也是從事美術教育的國小老師，每次看到葉宸君的畫作都會說好棒！繼續！讓她很開心及更有信心，每天晚上忙完了就從八點開始畫，幾乎畫到凌晨，真的渾然忘我，都不感覺疲憊，越畫越有感受。\r\n    葉宸君認為畫圖能夠整理思緒、反省自我，更可貴的是內在覺醒，能夠更清楚自己在做什麼，達到感官與內在的平衡。她體會到「靜」得下是一種享受「單獨」的可貴，與自己內在的小孩溝通成長，能夠畫自己心靈世界所傳達的訊息，是一種享受與幸福，感受它的真善美是如此的清徹美好，彷彿從內在喚醒真正的自我，是那麼的舒適、平和，每完成一幅創作是那麼喜悅和滿足，只要動筆去感受、去突破，又是一種新的契機。\r\n', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-02-19 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4083', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897a26b32418088f1936', '高雄市攝影家協會會員聯展', '高雄市攝影家協會的成員來自各行各業，會員所拍攝的題材五花八門，一般普羅大眾看得懂的美美照片，我們並不排斥，燒腦的攝影藝術創作作品我們也很擅長，每年各大美展得獎作品常有我們的足跡，更是我們堅持到底，永不放棄的目標。\r\n\r\n\r\n攝影的觀念隨著科技的進步不斷拓展，本次聯展我們也秉持突破傳統，讓觀眾能看到心靈層面的作品，歡迎來現場體驗。\r\n', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-04-18 00:00:00', '2025-04-29 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4068', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市攝影家協會會員聯展', `description`='高雄市攝影家協會的成員來自各行各業，會員所拍攝的題材五花八門，一般普羅大眾看得懂的美美照片，我們並不排斥，燒腦的攝影藝術創作作品我們也很擅長，每年各大美展得獎作品常有我們的足跡，更是我們堅持到底，永不放棄的目標。\r\n\r\n\r\n攝影的觀念隨著科技的進步不斷拓展，本次聯展我們也秉持突破傳統，讓觀眾能看到心靈層面的作品，歡迎來現場體驗。\r\n', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-04-18 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4068', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897a26b32418088f1937', '打開畫匣子－美術在高雄 《靜雅悅心　陳芮蓉水墨畫展》', '台大歷史系畢業投入補教業三十多年，民國100年陳芮蓉因緣際會拜林端姮老師學習書法，一年半後啟蒙於水墨花鳥專家蕭屏妮老師，民國107年水墨山水啟蒙於黃榮德老師，數年前又受業於嶺南畫派大師賴明郎老師學習嶺南山水及花鳥至今。\r\n    由於曾投入花藝十餘年，水墨花鳥的學習很快便進入狀況，若干年後深感不足，陳芮蓉於是興起水墨山水的學習。她的生性務實、專注、沉靜、崇尚自由民主，自我要求期許甚深，喜歡畫作讓人一看就懂，不需解釋也能理解原意，這樣的個性與行事風格自然表現在作品中，讓人內心沉靜、充滿歡喜。\r\n    因為非科班出身，陳芮蓉因此格外認真學習，她認為思考、觀察與閱讀（包含讀圖）能力的加強可以豐富正確的邏輯概念，秉承此概念與中庸之道（平衡）的運用，如虛實、明暗、遠近、大小等，將使畫作更具生命力。\r\n    藝術之美具絕對主觀性，陳芮蓉期盼人們因為她的畫作得到身心靈的撫慰，如同個展的主題「靜雅悅心」一樣，散發出人性的真善美，藉此美化純樸良善的社會風氣，讓藝文活動得以正向發展。\r\n', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-03-05 00:00:00', '2025-03-16 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4084', '[]') ON DUPLICATE KEY UPDATE `activity_name`='打開畫匣子－美術在高雄 《靜雅悅心　陳芮蓉水墨畫展》', `description`='台大歷史系畢業投入補教業三十多年，民國100年陳芮蓉因緣際會拜林端姮老師學習書法，一年半後啟蒙於水墨花鳥專家蕭屏妮老師，民國107年水墨山水啟蒙於黃榮德老師，數年前又受業於嶺南畫派大師賴明郎老師學習嶺南山水及花鳥至今。\r\n    由於曾投入花藝十餘年，水墨花鳥的學習很快便進入狀況，若干年後深感不足，陳芮蓉於是興起水墨山水的學習。她的生性務實、專注、沉靜、崇尚自由民主，自我要求期許甚深，喜歡畫作讓人一看就懂，不需解釋也能理解原意，這樣的個性與行事風格自然表現在作品中，讓人內心沉靜、充滿歡喜。\r\n    因為非科班出身，陳芮蓉因此格外認真學習，她認為思考、觀察與閱讀（包含讀圖）能力的加強可以豐富正確的邏輯概念，秉承此概念與中庸之道（平衡）的運用，如虛實、明暗、遠近、大小等，將使畫作更具生命力。\r\n    藝術之美具絕對主觀性，陳芮蓉期盼人們因為她的畫作得到身心靈的撫慰，如同個展的主題「靜雅悅心」一樣，散發出人性的真善美，藉此美化純樸良善的社會風氣，讓藝文活動得以正向發展。\r\n', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4084', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897a26b32418088f1938', '打開畫匣子－美術在高雄 《雷日晶彩墨個展》', ' 父親書法造詣深厚，母親國畫基礎札實，雷日晶出身書香門第，自幼耳濡目染，喜愛舞文弄墨。小學由名師指導學素描和鋼琴，至高中仍勤學不斷；大學期間時深受吳振芝教授關心和尉素秋、李勉教授等個別指導詩詞。\r\n    執教時期，高師大史墨卿教授曾幫助刊載論文，獲益良多！雷日晶也曾在救國團學習，由容天圻老師啟蒙，專攻三年梅花和四君子，又先後隨黃光男、王蛟、薛清茂、蕭屏妮等教授學習山水花鳥。她曾先後參加高雄市書畫學會、高雄市懷古門美術研究會、高雄市空大文藝系學會，暢遊歐美各大美術館後，雷日晶也能動筆潑灑油畫，並接受空大陳曉峰教授指導石膏版畫，讓生活更加美化溫馨。\r\n    此次收集歷年閒情偶寄，隨興所發，附庸風雅，作為砥勵學行之進階，也祈盼各位先進不吝指教！', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-03-19 00:00:00', '2025-03-30 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4085', '[]') ON DUPLICATE KEY UPDATE `activity_name`='打開畫匣子－美術在高雄 《雷日晶彩墨個展》', `description`=' 父親書法造詣深厚，母親國畫基礎札實，雷日晶出身書香門第，自幼耳濡目染，喜愛舞文弄墨。小學由名師指導學素描和鋼琴，至高中仍勤學不斷；大學期間時深受吳振芝教授關心和尉素秋、李勉教授等個別指導詩詞。\r\n    執教時期，高師大史墨卿教授曾幫助刊載論文，獲益良多！雷日晶也曾在救國團學習，由容天圻老師啟蒙，專攻三年梅花和四君子，又先後隨黃光男、王蛟、薛清茂、蕭屏妮等教授學習山水花鳥。她曾先後參加高雄市書畫學會、高雄市懷古門美術研究會、高雄市空大文藝系學會，暢遊歐美各大美術館後，雷日晶也能動筆潑灑油畫，並接受空大陳曉峰教授指導石膏版畫，讓生活更加美化溫馨。\r\n    此次收集歷年閒情偶寄，隨興所發，附庸風雅，作為砥勵學行之進階，也祈盼各位先進不吝指教！', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-03-19 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4085', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897a26b32418088f1939', '《黑水溝傳奇》高雄市西瀛畫會會員聯展', '西瀛畫會原是由一群旅居高雄的澎湖籍藝術家組成，現在廣納各地藝術愛好者。創會會長洪根深交由許叁陸再傳洪條根律師等...，目前由張瓊華担任會長。一向作品內容都重在以具有澎湖歷史文化、人物風情為主題，每年展出二次，一次在高雄，一次在澎湖。每次在澎湖辦展，都强調"鮭魚返鄉"的故鄉情懷，若在高雄，則意在喚起旅高的澎湖鄉親對故鄉的思念與情感。此即為與眾不同的畫展特色，也藉此廣招澎湖鄉親的熱烈参與，共同凝聚鄉心，或可稍解幾許鄉愁。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-05-02 00:00:00', '2025-05-13 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4086', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《黑水溝傳奇》高雄市西瀛畫會會員聯展', `description`='西瀛畫會原是由一群旅居高雄的澎湖籍藝術家組成，現在廣納各地藝術愛好者。創會會長洪根深交由許叁陸再傳洪條根律師等...，目前由張瓊華担任會長。一向作品內容都重在以具有澎湖歷史文化、人物風情為主題，每年展出二次，一次在高雄，一次在澎湖。每次在澎湖辦展，都强調"鮭魚返鄉"的故鄉情懷，若在高雄，則意在喚起旅高的澎湖鄉親對故鄉的思念與情感。此即為與眾不同的畫展特色，也藉此廣招澎湖鄉親的熱烈参與，共同凝聚鄉心，或可稍解幾許鄉愁。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-02 00:00:00', `end_date`='2025-05-13 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4086', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897a26b32418088f193a', '高雄市筆禪書法學會會員聯展', '『筆禪書法簡介』\r\n本會創會會長櫓翁　黃華山先生，有鑑於傳統六藝的書法道統，必須承接再予以發揚光大，於是創立了筆禪書法，這並不是一味的復古擬古，而是給予道統重新的評估和肯定，取其精華去其糟粕。\r\n茲將本會宗旨簡介如下：\r\n１、道法自然，自然為大宗師。\r\n２、融合禪、氣功、太極拳之養生原理。\r\n３、以草書入手，一開始學書即可享受到心靈的舞蹈性、音樂性，幼年到老年均適用。\r\n４、起先以雙手抱筆書寫，使腦神經之運作，由左腦的理性，移轉啟發右腦之感性、靈性，當心筆合一時才改為單手。\r\n５、以書稿滿摹法導引大家進入筆禪的靈性世界，開啟每個人內在的無限創造性，養護腦神經，當可益壽延年。\r\n', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-04-04 00:00:00', '2025-04-15 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4080', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市筆禪書法學會會員聯展', `description`='『筆禪書法簡介』\r\n本會創會會長櫓翁　黃華山先生，有鑑於傳統六藝的書法道統，必須承接再予以發揚光大，於是創立了筆禪書法，這並不是一味的復古擬古，而是給予道統重新的評估和肯定，取其精華去其糟粕。\r\n茲將本會宗旨簡介如下：\r\n１、道法自然，自然為大宗師。\r\n２、融合禪、氣功、太極拳之養生原理。\r\n３、以草書入手，一開始學書即可享受到心靈的舞蹈性、音樂性，幼年到老年均適用。\r\n４、起先以雙手抱筆書寫，使腦神經之運作，由左腦的理性，移轉啟發右腦之感性、靈性，當心筆合一時才改為單手。\r\n５、以書稿滿摹法導引大家進入筆禪的靈性世界，開啟每個人內在的無限創造性，養護腦神經，當可益壽延年。\r\n', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-04-04 00:00:00', `end_date`='2025-04-15 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4080', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897a26b32418088f193b', '善化區圖書館：上半年第一期藝文研習班', '善圖為推廣普及藝文活動特開設3個月為一期的藝文研習班，特聘請專業師資到館教授，課程頗受好評，讓藝文活動更加深入民眾生活。課程分別有台語文化班、兒童美術A、B班、兒童作文班、書法早班、花鳥水墨畫班。', '臺南市善化區圖書館', '臺南市善化區中山路377號3樓', '2025-01-01 00:00:00', '2025-03-31 00:00:00', '臺南市善化區圖書館', 23.14031072, 120.2988274, '--+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='善化區圖書館：上半年第一期藝文研習班', `description`='善圖為推廣普及藝文活動特開設3個月為一期的藝文研習班，特聘請專業師資到館教授，課程頗受好評，讓藝文活動更加深入民眾生活。課程分別有台語文化班、兒童美術A、B班、兒童作文班、書法早班、花鳥水墨畫班。', `organizer`='臺南市善化區圖書館', `address`='臺南市善化區中山路377號3樓', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市善化區圖書館', `latitude`=23.14031072, `longitude`=120.2988274, `ticket_price`='--+--', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897c26b32418088f193c', '無資料', '2月9日-5個孩子的校長\r\n2月16日-超熊瑪琪\r\n2月23日-我的老婆是老公?', '臺南市七股區圖書館', '臺南市七股區377號', '臺南市七股區圖書館', 23.12326578, 120.1005854, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='2月9日-5個孩子的校長\r\n2月16日-超熊瑪琪\r\n2月23日-我的老婆是老公?', `organizer`='臺南市七股區圖書館', `address`='臺南市七股區377號', `location`='臺南市七股區圖書館', `latitude`=23.12326578, `longitude`=120.1005854, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897c26b32418088f193d', '親愛的動物們', '本展從「動物友善與環境永續」議題，探討動物與人的情感關係，透過藝術創作與互動教具，從想像和繪本的擬人化動物、被馴化、豢養的寵物、台灣瀕危野生動物，以及周遭特有野生動物等，期待孩子能用更多同理心，去理解動物的感受與需要，共同營造一個對動物友善的生活環境。', '高雄市立美術館', '高雄市鼓山區馬卡道路330號', '2025-01-01 00:00:00', '2025-08-31 00:00:00', '高雄兒童美術館', 22.6578576, 120.2828147, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='親愛的動物們', `description`='本展從「動物友善與環境永續」議題，探討動物與人的情感關係，透過藝術創作與互動教具，從想像和繪本的擬人化動物、被馴化、豢養的寵物、台灣瀕危野生動物，以及周遭特有野生動物等，期待孩子能用更多同理心，去理解動物的感受與需要，共同營造一個對動物友善的生活環境。', `organizer`='高雄市立美術館', `address`='高雄市鼓山區馬卡道路330號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='高雄兒童美術館', `latitude`=22.6578576, `longitude`=120.2828147, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897d26b32418088f1942', '無資料', '藉由週末假日疏解平日忙碌生活，邀請您攜好友、伴家人 親子同行，坐在高眺建築視覺美感空間內，跟著優美的弦律，共度悠閒的樂活時光。\r\n演出地點：大東藝術文化中心演藝廳前廳 (高雄市鳳山區光遠路161號，橘線大東站2號出口)\r\n\r\n', '高雄市政府文化局', '高雄市鳳山區017鄰光遠路161號', '大東文化藝術中心', 22.625059, 120.363422, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='藉由週末假日疏解平日忙碌生活，邀請您攜好友、伴家人 親子同行，坐在高眺建築視覺美感空間內，跟著優美的弦律，共度悠閒的樂活時光。\r\n演出地點：大東藝術文化中心演藝廳前廳 (高雄市鳳山區光遠路161號，橘線大東站2號出口)\r\n\r\n', `organizer`='高雄市政府文化局', `address`='高雄市鳳山區017鄰光遠路161號', `location`='大東文化藝術中心', `latitude`=22.625059, `longitude`=120.363422, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897d26b32418088f1944', '無資料', '法印管樂團自102年成立至今，廣受各界人士的支持與肯定，今年法印管樂團，更以「誇越年齡，老少共學」的方式，一同大手拉小手，譜出一場青銀同樂的音樂響宴，歡迎大家114年2月22日晚上7:00大東文化藝術中心演藝廳見。\r\n上半場\r\n\r\nKA BOOM\r\n\r\nDANCE CELEBRATION\r\n\r\nTHE BEST BEETHOVEN\r\n\r\nTHE MAGNIFICENT SEVEN\r\n\r\nSUMMON THE HEROES\r\n\r\nSTAR WAR\r\n\r\nDRUMS OLE\r\n\r\nY.M.C.A.\r\n\r\n \r\n\r\n下半場\r\n\r\n冬季演歌組曲\r\n\r\n麵包超人\r\n\r\n夢幻莫扎特\r\n\r\n望春風\r\n\r\n海海人生\r\n\r\n相思雨\r\n\r\n高山青', '法印管樂團', '高雄市鳳山區017鄰光遠路161號', '大東文化藝術中心', 22.625059, 120.363422, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='法印管樂團自102年成立至今，廣受各界人士的支持與肯定，今年法印管樂團，更以「誇越年齡，老少共學」的方式，一同大手拉小手，譜出一場青銀同樂的音樂響宴，歡迎大家114年2月22日晚上7:00大東文化藝術中心演藝廳見。\r\n上半場\r\n\r\nKA BOOM\r\n\r\nDANCE CELEBRATION\r\n\r\nTHE BEST BEETHOVEN\r\n\r\nTHE MAGNIFICENT SEVEN\r\n\r\nSUMMON THE HEROES\r\n\r\nSTAR WAR\r\n\r\nDRUMS OLE\r\n\r\nY.M.C.A.\r\n\r\n \r\n\r\n下半場\r\n\r\n冬季演歌組曲\r\n\r\n麵包超人\r\n\r\n夢幻莫扎特\r\n\r\n望春風\r\n\r\n海海人生\r\n\r\n相思雨\r\n\r\n高山青', `organizer`='法印管樂團', `address`='高雄市鳳山區017鄰光遠路161號', `location`='大東文化藝術中心', `latitude`=22.625059, `longitude`=120.363422, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897d26b32418088f1945', '樂動忠聲──忠孝國中國樂班成果發表會', '忠孝國中國樂班創始於民國82年音樂實驗班，旨在延續各國小國樂樂團的學習，力求傳承國樂藝術之文化。民國86年，經教育部核准成立，成為高雄縣唯一之國中國樂資優班。成班後，已多次榮獲全國音樂比賽國樂合奏優等、絲竹室內樂全國優等，更在藝術才能班訪視評鑑中獲評為「值得推薦學校」，表現十分亮眼，深受各界好評。\r\n    因應教育部政策，自100學年度開始，改制為音樂類藝術才能班。設班目標仍為繼續培育具優異藝術才能之學生，施以專業音樂教育，輔導其適性發展，以期能培育出多元且專業的藝術人才。\r\n    而在品德教育與學術科並重的策略之下，忠孝國中藝才班不僅術科成績表現亮眼，升學方面，無論畢業後是就讀各高中普通班、音樂班或者藝術大學等，都有不錯的成績。歷年來，確實已成功培育出不少優秀的人才。\r\n    一年一度的「樂動忠聲」成果發表會，是忠孝國民中學國樂班多年以來的傳統，學生們也藉此獲得自我展現的舞台與機會。此次表演節目內容相當精采，包含全體國樂大合奏以及多首協奏曲，曲目內容有：〈鷂風蘭陽〉、〈臨安遺恨〉、〈人生的旋轉木馬&永遠常在〉、〈The Entertainer& Saber Dance〉、〈綻放〉及〈沙迪爾傳奇選段〉等多元曲目演出，誠摯歡迎各界蒞臨觀賞，與我們共享樂音飄揚的美好夜晚，欣賞學生們辛苦的學習成果。', '高雄市立忠孝國民中學', '高雄市鳳山區017鄰光遠路161號', '2025-02-25 00:00:00', '2025-02-25 00:00:00', '大東文化藝術中心', 22.625059, 120.363422, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樂動忠聲──忠孝國中國樂班成果發表會', `description`='忠孝國中國樂班創始於民國82年音樂實驗班，旨在延續各國小國樂樂團的學習，力求傳承國樂藝術之文化。民國86年，經教育部核准成立，成為高雄縣唯一之國中國樂資優班。成班後，已多次榮獲全國音樂比賽國樂合奏優等、絲竹室內樂全國優等，更在藝術才能班訪視評鑑中獲評為「值得推薦學校」，表現十分亮眼，深受各界好評。\r\n    因應教育部政策，自100學年度開始，改制為音樂類藝術才能班。設班目標仍為繼續培育具優異藝術才能之學生，施以專業音樂教育，輔導其適性發展，以期能培育出多元且專業的藝術人才。\r\n    而在品德教育與學術科並重的策略之下，忠孝國中藝才班不僅術科成績表現亮眼，升學方面，無論畢業後是就讀各高中普通班、音樂班或者藝術大學等，都有不錯的成績。歷年來，確實已成功培育出不少優秀的人才。\r\n    一年一度的「樂動忠聲」成果發表會，是忠孝國民中學國樂班多年以來的傳統，學生們也藉此獲得自我展現的舞台與機會。此次表演節目內容相當精采，包含全體國樂大合奏以及多首協奏曲，曲目內容有：〈鷂風蘭陽〉、〈臨安遺恨〉、〈人生的旋轉木馬&永遠常在〉、〈The Entertainer& Saber Dance〉、〈綻放〉及〈沙迪爾傳奇選段〉等多元曲目演出，誠摯歡迎各界蒞臨觀賞，與我們共享樂音飄揚的美好夜晚，欣賞學生們辛苦的學習成果。', `organizer`='高雄市立忠孝國民中學', `address`='高雄市鳳山區017鄰光遠路161號', `start_date`='2025-02-25 00:00:00', `end_date`='2025-02-25 00:00:00', `location`='大東文化藝術中心', `latitude`=22.625059, `longitude`=120.363422, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897d26b32418088f1948', '竹山鎮親子館-影片欣賞（114年2月） ', '歡迎自由入場欣賞。\r\n活動洽詢：049-2645530。', '南投縣竹山鎮公所', '南投縣竹山鎮公所路120號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '南投縣竹山鎮立親子館', 23.69805518, 120.7100797, '無資料', 'https://www.zhushan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='竹山鎮親子館-影片欣賞（114年2月） ', `description`='歡迎自由入場欣賞。\r\n活動洽詢：049-2645530。', `organizer`='南投縣竹山鎮公所', `address`='南投縣竹山鎮公所路120號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='南投縣竹山鎮立親子館', `latitude`=23.69805518, `longitude`=120.7100797, `ticket_price`='無資料', `source_url`='https://www.zhushan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897d26b32418088f194d', '2月繪本主題書展 「食在農讚」', '民以食為天，食物是每天必需補充的能量，你的飲食健康嗎? 營養夠嗎?\r\n從產地到餐桌\r\n你知道我們每天吃的食物從哪裡來嗎?\r\n你知道每天要吃多少東西，可以吃什麼東西嗎?\r\n要怎麼吃得好、吃得巧、吃得健康又營養呢?\r\n來館內試試看你到底吃的對對。大手牽小手一起來一場食物桌遊趣。\r\n1.根據衛服部每天所需的營養設計一款自己的餐盤讓大小朋友都來拚一拚自己一天所需的食物種類及營養量。\r\n2.書籍簡介。\r\n3.提供高雄市及鄰近兩縣市的在地食材資訊參考。\r\n\r\n\r\n   ', '高雄市立圖書館總館', '高雄市彌陀區2鄰中正路281巷50號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '高雄市立圖書館彌陀公園分館', 22.780227, 120.249503, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月繪本主題書展 「食在農讚」', `description`='民以食為天，食物是每天必需補充的能量，你的飲食健康嗎? 營養夠嗎?\r\n從產地到餐桌\r\n你知道我們每天吃的食物從哪裡來嗎?\r\n你知道每天要吃多少東西，可以吃什麼東西嗎?\r\n要怎麼吃得好、吃得巧、吃得健康又營養呢?\r\n來館內試試看你到底吃的對對。大手牽小手一起來一場食物桌遊趣。\r\n1.根據衛服部每天所需的營養設計一款自己的餐盤讓大小朋友都來拚一拚自己一天所需的食物種類及營養量。\r\n2.書籍簡介。\r\n3.提供高雄市及鄰近兩縣市的在地食材資訊參考。\r\n\r\n\r\n   ', `organizer`='高雄市立圖書館總館', `address`='高雄市彌陀區2鄰中正路281巷50號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='高雄市立圖書館彌陀公園分館', `latitude`=22.780227, `longitude`=120.249503, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897d26b32418088f194f', '「旅讀東南亞遊山玩水趣」--東南亞主題書展', '「蛇」來閱讀東南亞嘍!\r\n一起從書中漫步世界遺產-吳哥窟，縱情風下之鄉-沙巴，走入天使之城-泰國曼谷……一次讓你旅讀到飽。\r\n', '高雄市立圖書館總館', '高雄市彌陀區14鄰四維路一之一號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '高雄市立圖書館彌陀分館', 22.7832231, 120.2455033, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「旅讀東南亞遊山玩水趣」--東南亞主題書展', `description`='「蛇」來閱讀東南亞嘍!\r\n一起從書中漫步世界遺產-吳哥窟，縱情風下之鄉-沙巴，走入天使之城-泰國曼谷……一次讓你旅讀到飽。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市彌陀區14鄰四維路一之一號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='高雄市立圖書館彌陀分館', `latitude`=22.7832231, `longitude`=120.2455033, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897d26b32418088f1951', '世界母語日~台語說故事', '3/12虎姑婆繪本:寶妹的爸媽不在家，狡猾老虎精假扮姑婆，想拐騙寶妹打開家門、吃掉她。聰明的寶妹不但機智應對，還得到老鼠精送的三個香包，把虎姑婆整得再也不敢下山吃小孩。兇惡的老虎精為何屢屢失手，寶妹又是如何逃出虎掌的呢？\r\n3/13豆油找親戚本書採擬人化的手法，敘述故事主人翁－豆油，尋找親戚的過程；並採用有如數數一般的閱讀方式，從一周日期的變化，發展符合邏輯性的串連，不但具有語文性（國語、台語），也兼具數學性（星期的排列）。還有一個有趣的發現：讀故事的同時，能夠學習到中文量詞正確的用法，如：一杯、一罐、一壺等等，也算是在讀故事書之餘的另一項收穫。', '高雄市立圖書館總館', '高雄市岡山區009鄰岡山南路42號', '2025-03-12 00:00:00', '2025-03-13 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='世界母語日~台語說故事', `description`='3/12虎姑婆繪本:寶妹的爸媽不在家，狡猾老虎精假扮姑婆，想拐騙寶妹打開家門、吃掉她。聰明的寶妹不但機智應對，還得到老鼠精送的三個香包，把虎姑婆整得再也不敢下山吃小孩。兇惡的老虎精為何屢屢失手，寶妹又是如何逃出虎掌的呢？\r\n3/13豆油找親戚本書採擬人化的手法，敘述故事主人翁－豆油，尋找親戚的過程；並採用有如數數一般的閱讀方式，從一周日期的變化，發展符合邏輯性的串連，不但具有語文性（國語、台語），也兼具數學性（星期的排列）。還有一個有趣的發現：讀故事的同時，能夠學習到中文量詞正確的用法，如：一杯、一罐、一壺等等，也算是在讀故事書之餘的另一項收穫。', `organizer`='高雄市立圖書館總館', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-03-13 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897d26b32418088f1953', '（兒童館）繪本說故事（114年2月）', '在大大的樹下，來聽老師活潑生動的講述繪本故事。', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '無資料', 'https://www.facebook.com/hakkapark', '[]') ON DUPLICATE KEY UPDATE `activity_name`='（兒童館）繪本說故事（114年2月）', `description`='在大大的樹下，來聽老師活潑生動的講述繪本故事。', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='無資料', `source_url`='https://www.facebook.com/hakkapark', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a2897e26b32418088f1958', '念念常心－林凱婷個展', '展覽文述\r\n\r\n我們的生活中，總有一些事情值得反覆想念、深深珍藏——那些無數次出現在心頭的回憶、支持與夢想，都化作了持續前行的力量。在這次展覽中，作家林凱婷以溫暖而誠摯的隨筆插畫，邀請每一位觀者進入她的內心世界，感受那些埋藏於心的情感與信念。\r\n「常」，是一種持續；「心」，是一份牽掛。凱婷坦言，創作是她對夢想的堅守，也是對支持她的人們的感恩。她曾經是一位家具業務、軟裝顧問，而現在她用繪畫作品述說著心底的話語：關於不放棄、關於感恩、關於將每一次鼓勵化作日常的勇氣。\r\n這是一場溫柔而充滿力量的展覽，它不僅是作家的自我表白，更是一份對每一位曾支持過她的人致上的深深祝福。讓我們一起走進《念念常心》，在作品中找到那份與自己心靈相通的感動，也將這份感動珍藏於心。\r\n\r\n\r\n\r\n作家文述\r\n\r\n／念念常心／\r\n\r\n「常」  有時常，有不斷的意思，所以我\r\n不斷的在心裡，常常想你\r\n不斷的在心裡，提醒自己不要放棄你\r\n不斷的在心裡，提醒自己不要在乎別人怎麼說你\r\n不斷的在心裡，提醒自己還有一些人在乎及欣賞你\r\n\r\n常常提醒自己要視無常為常\r\n突然我幸運地來了一個禮物\r\n擁有了一個可以完成夢想的機會，來自熱情的高雄\r\n這一次告訴自己走吧！\r\n\r\n「你」指的是自己 ，是我的作品\r\n是鼓勵我、支持我的你們，\r\n放在心裡，感恩你們、謝謝你們\r\n\r\n不斷的想念你們的鼓勵是我的日常\r\n放在心裡是我對你們深深的感恩及祝福\r\n\r\n\r\n／關於我／\r\n\r\n我是林凱婷，1972年生於台北，有一個非常快樂的童年。從來都不覺得自己會畫畫，高職我學的是建築，到專科才真的開始用力的畫設計圖。畢業後做了約17年的家具業務，這也是我創作的養分之一。\r\n\r\n我很羨慕會畫Free hand的人，某天，看到一個圓，啟發了我，突然發現畫畫好像沒那麼難，就開始了我畫畫的生活。\r\n\r\n我一直都是臨摹再做一些調整的在畫畫，沒有自己的創意，這困擾我長達快20年。直到我任職的家具公司結束營業，記得是2017年的10月，我腦中突然出現一個畫面，我就畫下來，突然創意靈感大發，沒日沒夜的一直畫一直畫；2018年我手繪了 200張紅包袋，還有數多張的春聯，我稱那真是光輝的十月！\r\n\r\n我的畫裡有很多動物尤其是類似鳥類，有一些符號會一直重覆在不同的畫裡，其實每一幅畫多少都和自己的日常有關，有時事、有諷刺、有時看似歡樂實則藏著傷心。\r\n\r\n這次的展覽包含了我非常多的突破和嘗試，以及對許多人的感謝。\r\n總之⋯⋯歡迎你們來到我的奇異世界\r\n謝謝你們參與我第一次的出場 《念念常心》', '大唐生活美學館', '高雄市三民區', '2025-02-22 00:00:00', '2025-03-15 00:00:00', '三民區（高雄市）=', 22.64989883, 120.3179187, '無資料', 'https://studiotang.com.tw/exhibition_detail.php?id=342', '[]') ON DUPLICATE KEY UPDATE `activity_name`='念念常心－林凱婷個展', `description`='展覽文述\r\n\r\n我們的生活中，總有一些事情值得反覆想念、深深珍藏——那些無數次出現在心頭的回憶、支持與夢想，都化作了持續前行的力量。在這次展覽中，作家林凱婷以溫暖而誠摯的隨筆插畫，邀請每一位觀者進入她的內心世界，感受那些埋藏於心的情感與信念。\r\n「常」，是一種持續；「心」，是一份牽掛。凱婷坦言，創作是她對夢想的堅守，也是對支持她的人們的感恩。她曾經是一位家具業務、軟裝顧問，而現在她用繪畫作品述說著心底的話語：關於不放棄、關於感恩、關於將每一次鼓勵化作日常的勇氣。\r\n這是一場溫柔而充滿力量的展覽，它不僅是作家的自我表白，更是一份對每一位曾支持過她的人致上的深深祝福。讓我們一起走進《念念常心》，在作品中找到那份與自己心靈相通的感動，也將這份感動珍藏於心。\r\n\r\n\r\n\