INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bbea26b32418088f197a', '2025台灣燈會－星光點點烏龜燈展覽', '龜山眷村故事館特邀龜山國中學生共同創作而成。透過學生們的巧手，將眷村意象巧妙融入燈罩設計中，為這座燈飾增添濃厚的文化意涵與地方認同感。\r\n「烏龜燈」的設計以烏龜為主題，象徵著穩定與長久，呼應了龜山地方的命名來源，也展現了眷村居民彼此扶持的堅韌精神。燈飾的繪圖中穿插眷村中的日常景象，重溫眷村居民共同努力書寫的時代記憶。', '龜山眷村故事館', '桃園市龜山區光峰路43號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '龜山眷村故事館', 25.0001286, 121.3417715, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會－星光點點烏龜燈展覽', `description`='龜山眷村故事館特邀龜山國中學生共同創作而成。透過學生們的巧手，將眷村意象巧妙融入燈罩設計中，為這座燈飾增添濃厚的文化意涵與地方認同感。\r\n「烏龜燈」的設計以烏龜為主題，象徵著穩定與長久，呼應了龜山地方的命名來源，也展現了眷村居民彼此扶持的堅韌精神。燈飾的繪圖中穿插眷村中的日常景象，重溫眷村居民共同努力書寫的時代記憶。', `organizer`='龜山眷村故事館', `address`='桃園市龜山區光峰路43號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='龜山眷村故事館', `latitude`=25.0001286, `longitude`=121.3417715, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
