INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bbf426b32418088f1980', '【新竹逗席攝影節 】 2025/新竹、竹東篇', '〔2025新竹逗席攝影節–在地攝影藝術家邀請展〕在攝影創作者、策展人陳玉書的策展規劃下，本第二屆一共邀集了資深攝影藝術家三十位參與展出。依姓氏筆畫序，分別是余白（法國攝影家）、吳慶杰、林駿嵐、施性忠、施秀芳、施麗娟、徐煥相、陳雲錦、陳國珍、陳騰芳、陳玉書、陳文堂、陳永鎰、彭茂中、彭啟原、彭文生、湯景光、梁朝安、萬一一、許仁和、葉忠達、葉甫盛、楊偉廷、曾煥龍、劉漪晴、劉達治、潘國正、蔡聖、蔡世明、鍾奇芬。他們都是在攝影藝術擁有極深的資歷與不凡的成就，2025展覽能邀請到這麼多在地攝影藝術家共襄盛舉，實為今年的新竹逗席攝影節增添無上的光彩與榮耀。', '新竹市文化局', '新竹市北區中正路120號', '2025-02-19 00:00:00', '2025-03-09 00:00:00', '新竹市政府/新竹州廳', 24.82269542, 120.9491233, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新竹逗席攝影節 】 2025/新竹、竹東篇', `description`='〔2025新竹逗席攝影節–在地攝影藝術家邀請展〕在攝影創作者、策展人陳玉書的策展規劃下，本第二屆一共邀集了資深攝影藝術家三十位參與展出。依姓氏筆畫序，分別是余白（法國攝影家）、吳慶杰、林駿嵐、施性忠、施秀芳、施麗娟、徐煥相、陳雲錦、陳國珍、陳騰芳、陳玉書、陳文堂、陳永鎰、彭茂中、彭啟原、彭文生、湯景光、梁朝安、萬一一、許仁和、葉忠達、葉甫盛、楊偉廷、曾煥龍、劉漪晴、劉達治、潘國正、蔡聖、蔡世明、鍾奇芬。他們都是在攝影藝術擁有極深的資歷與不凡的成就，2025展覽能邀請到這麼多在地攝影藝術家共襄盛舉，實為今年的新竹逗席攝影節增添無上的光彩與榮耀。', `organizer`='新竹市文化局', `address`='新竹市北區中正路120號', `start_date`='2025-02-19 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='新竹市政府/新竹州廳', `latitude`=24.82269542, `longitude`=120.9491233, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bbf726b32418088f1981', '地政鑄檔 案藏桃園', '地政檔案豐富多元，也關係著民眾財產權益，本所與八德、龜山及蘆竹所合作，藉由「時光列車」、「百年尋驛」及「i趣桃園」等三大主題，見證日治時期至今，土地行政及跨所發展樣貌，結合在地民間信仰「桃園大廟景福宮」、「五福宮」、「三元宮」、「壽山巖觀音寺」，跨所、跨域合作展出「寺廟」、「土地公」及「百年鐵道」等歷史文化之美，廟語如神，再現百年風華。', '桃園市桃園地政事務所', '桃園市桃園區', '2025-01-02 00:00:00', '2025-03-31 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='地政鑄檔 案藏桃園', `description`='地政檔案豐富多元，也關係著民眾財產權益，本所與八德、龜山及蘆竹所合作，藉由「時光列車」、「百年尋驛」及「i趣桃園」等三大主題，見證日治時期至今，土地行政及跨所發展樣貌，結合在地民間信仰「桃園大廟景福宮」、「五福宮」、「三元宮」、「壽山巖觀音寺」，跨所、跨域合作展出「寺廟」、「土地公」及「百年鐵道」等歷史文化之美，廟語如神，再現百年風華。', `organizer`='桃園市桃園地政事務所', `address`='桃園市桃園區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bbf726b32418088f1982', '「百年老店 風華蛻變」、「埤地相生 壢檔永存」雙主題檔案應用展覽', '本次檔案展覽分成二大部分：\r\n(1)「百年老店 風華蛻變」：中壢地政事務所百年變遷沿革、數次搬遷分所歷史文檔，以及中壢地方老照片等史料展出。\r\n(2)「埤地相生 壢檔永存」：埤塘的產生運用及發展，伴隨著地政業務的精進與蛻變，相輔相生，密不可分。從埤塘的現在、過去與未來，穿插水利與地政各時期圖籍簿冊照片等史料，從地政的角度出發，展開地政與埤塘的故事。', '桃園市中壢地政事務所', '桃園市中壢區', '2025-01-02 00:00:00', '2025-02-27 00:00:00', '中壢區（桃園市）=', 24.97993803, 121.2147243, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「百年老店 風華蛻變」、「埤地相生 壢檔永存」雙主題檔案應用展覽', `description`='本次檔案展覽分成二大部分：\r\n(1)「百年老店 風華蛻變」：中壢地政事務所百年變遷沿革、數次搬遷分所歷史文檔，以及中壢地方老照片等史料展出。\r\n(2)「埤地相生 壢檔永存」：埤塘的產生運用及發展，伴隨著地政業務的精進與蛻變，相輔相生，密不可分。從埤塘的現在、過去與未來，穿插水利與地政各時期圖籍簿冊照片等史料，從地政的角度出發，展開地政與埤塘的故事。', `organizer`='桃園市中壢地政事務所', `address`='桃園市中壢區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='中壢區（桃園市）=', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bbf826b32418088f1983', '桃花源–劉秀蘭水墨畫展', '水墨畫裡以中融西，運用色彩、線條堆疊，呈現自然生動，仿若寫實的意境。', '桃園市楊梅地政事務所', '桃園市楊梅區', '2025-01-02 00:00:00', '2025-03-31 00:00:00', '楊梅區（桃園市）=', 24.91820989, 121.1291697, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃花源–劉秀蘭水墨畫展', `description`='水墨畫裡以中融西，運用色彩、線條堆疊，呈現自然生動，仿若寫實的意境。', `organizer`='桃園市楊梅地政事務所', `address`='桃園市楊梅區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='楊梅區（桃園市）=', `latitude`=24.91820989, `longitude`=121.1291697, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bbf826b32418088f1984', '八德地政檔案展「30有你，好德憶」', '地政檔案與民眾權益息息相關，本所為配合國家發展委員會檔案管理局檔案月活動，以及適逢本所創所30周年，特舉辦八德地政檔案成果展「30有你，好德憶」，吸引民眾瞭解本所的自創所、搬遷、得獎、周邊歷史、權狀、登記簿及測量儀器等歷史演進，同時結合本所典藏檔案資料展覽說明。', '桃園市八德地政事務所', '桃園市八德區', '2025-01-01 00:00:00', '2025-10-01 00:00:00', '八德區（桃園市）=', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='八德地政檔案展「30有你，好德憶」', `description`='地政檔案與民眾權益息息相關，本所為配合國家發展委員會檔案管理局檔案月活動，以及適逢本所創所30周年，特舉辦八德地政檔案成果展「30有你，好德憶」，吸引民眾瞭解本所的自創所、搬遷、得獎、周邊歷史、權狀、登記簿及測量儀器等歷史演進，同時結合本所典藏檔案資料展覽說明。', `organizer`='桃園市八德地政事務所', `address`='桃園市八德區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-10-01 00:00:00', `location`='八德區（桃園市）=', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc0226b32418088f1985', '《多情的歲月紀實The Lyrical Ages》2025Happening（Davina’s Solo Exhibition）謝攸青繪畫創作展', '開幕︱02/16(日)14:00 \r\n講座︱02/23(日)14:00\r\n謝攸青，現為以油畫創作為主，同時探索其他媒材可能為輔的藝術行動學者藝術家，國立勤益科技大學藝術專任副教授退休。\r\n學歷：國立台灣師範大學美術學系、碩士、博士\r\n創作理念：\r\n藝術是生命行遠的寄託，意象是在藝術行動中產生，是思緒情感的沉澱與表達，情感寄託於日常所見的自然或平凡事物，畫面總非刻意的，不論喜悅與悲傷，景物總能在創作的實踐中自己彰顯出它不可思議的精神力量，產生某種生命的積極性意義。繪畫風格總有象徵主義的詩性隱喻，偏好東方或野獸派以來的設色邏輯與多重時空，德勒茲後結構主義的視覺邏輯，並非超現實，但潛意識卻往往是創作過程中不可忽視的因素，我稱之為「第三方我」。繪畫行動是追尋自由『第三方我』的視覺表達過程。即使是失落的境遇，也能因為藝術而產生如同蕭邦音樂的美感節奏而振奮。白雲、藍天、各種事物的美麗色彩更常是鼓舞心靈的主角。\r\n卡布羅（Kaprow）偶發藝術Happening的藝術事件理念，是結合在整個創作生命行動中，是種種抉擇下的生命走向與景觀，藝術靈感隨著實踐的過程，結果往往在預期之外，這也是潛意識作用的神秘之處。', '隱藝空間工作室', '桃園市大園區大仁路48號', '2025-02-12 00:00:00', '2025-03-09 00:00:00', '隱藝術', 25.06384709, 121.21177, '無資料', 'https://www.yinartspace.org', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《多情的歲月紀實The Lyrical Ages》2025Happening（Davina’s Solo Exhibition）謝攸青繪畫創作展', `description`='開幕︱02/16(日)14:00 \r\n講座︱02/23(日)14:00\r\n謝攸青，現為以油畫創作為主，同時探索其他媒材可能為輔的藝術行動學者藝術家，國立勤益科技大學藝術專任副教授退休。\r\n學歷：國立台灣師範大學美術學系、碩士、博士\r\n創作理念：\r\n藝術是生命行遠的寄託，意象是在藝術行動中產生，是思緒情感的沉澱與表達，情感寄託於日常所見的自然或平凡事物，畫面總非刻意的，不論喜悅與悲傷，景物總能在創作的實踐中自己彰顯出它不可思議的精神力量，產生某種生命的積極性意義。繪畫風格總有象徵主義的詩性隱喻，偏好東方或野獸派以來的設色邏輯與多重時空，德勒茲後結構主義的視覺邏輯，並非超現實，但潛意識卻往往是創作過程中不可忽視的因素，我稱之為「第三方我」。繪畫行動是追尋自由『第三方我』的視覺表達過程。即使是失落的境遇，也能因為藝術而產生如同蕭邦音樂的美感節奏而振奮。白雲、藍天、各種事物的美麗色彩更常是鼓舞心靈的主角。\r\n卡布羅（Kaprow）偶發藝術Happening的藝術事件理念，是結合在整個創作生命行動中，是種種抉擇下的生命走向與景觀，藝術靈感隨著實踐的過程，結果往往在預期之外，這也是潛意識作用的神秘之處。', `organizer`='隱藝空間工作室', `address`='桃園市大園區大仁路48號', `start_date`='2025-02-12 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='隱藝術', `latitude`=25.06384709, `longitude`=121.21177, `ticket_price`='無資料', `source_url`='https://www.yinartspace.org', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc0a26b32418088f1986', '2025台灣燈會-南崁兒童藝術村社區共創燈光計畫燈飾作品展', '南崁兒童藝術村配合114年臺灣燈會在桃園的活動，提出「元宵節戶外妝點計畫」，規劃自113年12月10日至114年3月2日，以綠色生活、永續環保為策展概念，以「鎏光魅影」、「自由靈魂蒲公英」和「煥彩風車」三大親手製作屬於自己的花燈：提供專業指導與材料，無論是大人或小孩都能輕鬆上手，創造獨一無二的花燈作品。本次活動為增加燈飾創意作品的多元性，結合地方文化創意工作者及其團隊，邀請百色美術、WoodyMommy 手作雜貨屋、好室 自助画室舉辦燈飾DIY 體驗工作坊，創作作品燈會期間於園區展出，展期結束再提供予參與民眾帶回留念。', '桃園市政府文化局', '桃園市蘆竹區吉林路34、36、38、40、42、44、46號，長春路3巷3號1.2樓、4號1.2樓、5號1.2樓，長春路5巷1號1樓', '2025-01-20 00:00:00', '2025-03-02 00:00:00', '南崁兒童藝術村', 25.06073337, 121.2831266, '無資料', 'https://www.facebook.com/nankanartvillage/?locale=zh_TW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會-南崁兒童藝術村社區共創燈光計畫燈飾作品展', `description`='南崁兒童藝術村配合114年臺灣燈會在桃園的活動，提出「元宵節戶外妝點計畫」，規劃自113年12月10日至114年3月2日，以綠色生活、永續環保為策展概念，以「鎏光魅影」、「自由靈魂蒲公英」和「煥彩風車」三大親手製作屬於自己的花燈：提供專業指導與材料，無論是大人或小孩都能輕鬆上手，創造獨一無二的花燈作品。本次活動為增加燈飾創意作品的多元性，結合地方文化創意工作者及其團隊，邀請百色美術、WoodyMommy 手作雜貨屋、好室 自助画室舉辦燈飾DIY 體驗工作坊，創作作品燈會期間於園區展出，展期結束再提供予參與民眾帶回留念。', `organizer`='桃園市政府文化局', `address`='桃園市蘆竹區吉林路34、36、38、40、42、44、46號，長春路3巷3號1.2樓、4號1.2樓、5號1.2樓，長春路5巷1號1樓', `start_date`='2025-01-20 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='南崁兒童藝術村', `latitude`=25.06073337, `longitude`=121.2831266, `ticket_price`='無資料', `source_url`='https://www.facebook.com/nankanartvillage/?locale=zh_TW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc0e26b32418088f1988', '高雄市立圖書館大樹分館114年2月主題書展', '1.【SDGs#5(性別平等)主題書展】--因應聯合國2015年宣佈「2030永續發展目標」中第五項目標，實現性別平等及所有女性之賦權，展出刻板印象、女性權利、性平教育、人權、性別歧視、性騷擾等相關書籍，供民眾翻閱。(展期:114.1.2~3.30)\r\n2.【多元之美：「泰」、「印」、「越」書香之旅】--透過書籍增進對泰國、印度和越南豐富文化的認識,促進包容性和理解，這次書展將成為一個讓人們相遇與對話的場所，展示書籍的力量如何連結不同文化的心靈。(展期:114.1.2~3.30)\r\n', '高雄市立圖書館總館', '高雄市大樹區17鄰中興西路50號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '高雄市立圖書館大樹分館', 22.6912015, 120.4303983, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市立圖書館大樹分館114年2月主題書展', `description`='1.【SDGs#5(性別平等)主題書展】--因應聯合國2015年宣佈「2030永續發展目標」中第五項目標，實現性別平等及所有女性之賦權，展出刻板印象、女性權利、性平教育、人權、性別歧視、性騷擾等相關書籍，供民眾翻閱。(展期:114.1.2~3.30)\r\n2.【多元之美：「泰」、「印」、「越」書香之旅】--透過書籍增進對泰國、印度和越南豐富文化的認識,促進包容性和理解，這次書展將成為一個讓人們相遇與對話的場所，展示書籍的力量如何連結不同文化的心靈。(展期:114.1.2~3.30)\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市大樹區17鄰中興西路50號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='高雄市立圖書館大樹分館', `latitude`=22.6912015, `longitude`=120.4303983, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
