INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc1326b32418088f198f', '色鉛筆插畫班', '繪畫在現代是紓壓的好方法，透過學習更可以從身邊的題材，培養出對土地的情感與加深連結，以及增強觀察能力，從簡單的題材和技巧開始，慢慢提升難度和挑戰，讓學生逐漸提高技術和自信心。', '高雄市立圖書館總館', '高雄市楠梓區楠梓路262號', '2025-02-26 00:00:00', '2025-06-25 00:00:00', '高雄市立圖書館楠仔坑分館', 22.7334902, 120.3278826, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='色鉛筆插畫班', `description`='繪畫在現代是紓壓的好方法，透過學習更可以從身邊的題材，培養出對土地的情感與加深連結，以及增強觀察能力，從簡單的題材和技巧開始，慢慢提升難度和挑戰，讓學生逐漸提高技術和自信心。', `organizer`='高雄市立圖書館總館', `address`='高雄市楠梓區楠梓路262號', `start_date`='2025-02-26 00:00:00', `end_date`='2025-06-25 00:00:00', `location`='高雄市立圖書館楠仔坑分館', `latitude`=22.7334902, `longitude`=120.3278826, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc1626b32418088f1990', '「敲敲繪本大門」成人繪本讀書會', '本讀書會希望藉由各式繪本作品之介紹閱讀，與您共賞繪本世界的文學與藝術之"重奏"，重溫童年純真、閱覽生命百樣，並藉此強化親子共讀的深度與廣度。\r\n\r\n114/01/24 作者賞析:與宮澤賢治共遊銀河鐵道\r\n114/02/21 主題賞析:繪本裡的熟齡點滴\r\n114/03/28 作者賞析:林小杯的有情世界\r\n114/04/25 主題賞析:繪本之音樂旋律\r\n114/05/23 作者賞析:兒童文學界的巨人Ruth Krauss\r\n114/06/27 主題賞析:種下繪本哲學種子\r\n\r\n上課方式：採現場與線上同步進行\r\n實體講座地點：寶珠分館 藝文研習室(高雄市三民區大順二路468號4樓)\r\n線上講座(使用Google Meet線上會議室)：務必留下正確電子信箱，以寄送線上會議室連結。\r\n因本課程需繳交成果，會於課程截圖拍照。\r\n活動對象：歡迎有興趣之民眾報名參加，限40名。\r\n報名方式：線上報名', '高雄市立圖書館總館', '高雄市三民區002鄰大順二路468號', '2025-01-24 00:00:00', '2025-06-27 00:00:00', '高雄市立圖書館寶珠分館', 22.649382, 120.3249695, '教材費+600', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「敲敲繪本大門」成人繪本讀書會', `description`='本讀書會希望藉由各式繪本作品之介紹閱讀，與您共賞繪本世界的文學與藝術之"重奏"，重溫童年純真、閱覽生命百樣，並藉此強化親子共讀的深度與廣度。\r\n\r\n114/01/24 作者賞析:與宮澤賢治共遊銀河鐵道\r\n114/02/21 主題賞析:繪本裡的熟齡點滴\r\n114/03/28 作者賞析:林小杯的有情世界\r\n114/04/25 主題賞析:繪本之音樂旋律\r\n114/05/23 作者賞析:兒童文學界的巨人Ruth Krauss\r\n114/06/27 主題賞析:種下繪本哲學種子\r\n\r\n上課方式：採現場與線上同步進行\r\n實體講座地點：寶珠分館 藝文研習室(高雄市三民區大順二路468號4樓)\r\n線上講座(使用Google Meet線上會議室)：務必留下正確電子信箱，以寄送線上會議室連結。\r\n因本課程需繳交成果，會於課程截圖拍照。\r\n活動對象：歡迎有興趣之民眾報名參加，限40名。\r\n報名方式：線上報名', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區002鄰大順二路468號', `start_date`='2025-01-24 00:00:00', `end_date`='2025-06-27 00:00:00', `location`='高雄市立圖書館寶珠分館', `latitude`=22.649382, `longitude`=120.3249695, `ticket_price`='教材費+600', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc1826b32418088f1993', '東南亞主題書展-閱讀越南', '挑選館內東南亞語相閱書藉，讓讀者可以借閱，了解東南亞文化和藝術。', '高雄市立圖書館總館', '高雄市新興區6鄰民生一路271號', '2025-02-01 00:00:00', '2025-03-31 00:00:00', '高雄市立圖書館新興民眾閱覽室', 22.6272175, 120.3068429, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='東南亞主題書展-閱讀越南', `description`='挑選館內東南亞語相閱書藉，讓讀者可以借閱，了解東南亞文化和藝術。', `organizer`='高雄市立圖書館總館', `address`='高雄市新興區6鄰民生一路271號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='高雄市立圖書館新興民眾閱覽室', `latitude`=22.6272175, `longitude`=120.3068429, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc1926b32418088f1994', '「考古埕－尋找熱蘭遮市鎮」特展(2025)', '「考古埕-尋找熱蘭遮市鎮」特展\r\n►►四大展區║探坑走廊／距今實驗室／鯤島旅行社／修復里院║\r\n「這場持續探尋臺南四百年歷史時空的考古行動，象徵著古都臺南過去、現在與未來樣貌的鏈結。」由劍獅埕／考古埕歷年研究發掘成果相伴，走向城市時空、物質、常民生活的反思，踏上今昔交錯／虛實交織的跨時空旅行，終於回歸彌足珍貴的每個當下和日常。\r\n四大展區內容包括近年大員市鎮考古發掘探坑、相關考古遺物展示及成果說明、考古科學體驗以及以大員市鎮為背景的電玩遊戲體驗等等。本次特展帶領觀者透過實體考古探坑及虛擬數位電玩回到四百年以前的大員市鎮，在安平現地感受今昔交錯與考古學穿越時空的魅力。', '臺南市文化資產管理處', '臺南市安平區', '2025-01-01 00:00:00', '2025-03-23 00:00:00', '安平區（臺南市）=', 22.99008437, 120.1649949, '無資料', 'https://www.facebook.com/tmach20101225/?locale=zh_TW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「考古埕－尋找熱蘭遮市鎮」特展(2025)', `description`='「考古埕-尋找熱蘭遮市鎮」特展\r\n►►四大展區║探坑走廊／距今實驗室／鯤島旅行社／修復里院║\r\n「這場持續探尋臺南四百年歷史時空的考古行動，象徵著古都臺南過去、現在與未來樣貌的鏈結。」由劍獅埕／考古埕歷年研究發掘成果相伴，走向城市時空、物質、常民生活的反思，踏上今昔交錯／虛實交織的跨時空旅行，終於回歸彌足珍貴的每個當下和日常。\r\n四大展區內容包括近年大員市鎮考古發掘探坑、相關考古遺物展示及成果說明、考古科學體驗以及以大員市鎮為背景的電玩遊戲體驗等等。本次特展帶領觀者透過實體考古探坑及虛擬數位電玩回到四百年以前的大員市鎮，在安平現地感受今昔交錯與考古學穿越時空的魅力。', `organizer`='臺南市文化資產管理處', `address`='臺南市安平區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='安平區（臺南市）=', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='https://www.facebook.com/tmach20101225/?locale=zh_TW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc1926b32418088f1995', '「考古埕－尋找熱蘭遮市鎮」特展-📽️考古埕x小影展📽️', '透過國立成功大學考古學研究所團隊製作的4部主題影片放映，分享考古埕現地的考古歷程及歷史脈絡。\r\n\r\n「考古埕-尋找熱蘭遮市鎮」特展\r\n►►四大展區║探坑走廊／距今實驗室／鯤島旅行社／修復里院║\r\n「這場持續探尋臺南四百年歷史時空的考古行動，象徵著古都臺南過去、現在與未來樣貌的鏈結。」由劍獅埕／考古埕歷年研究發掘成果相伴，走向城市時空、物質、常民生活的反思，踏上今昔交錯／虛實交織的跨時空旅行，終於回歸彌足珍貴的每個當下和日常。\r\n四大展區內容包括近年大員市鎮考古發掘探坑、相關考古遺物展示及成果說明、考古科學體驗以及以大員市鎮為背景的電玩遊戲體驗等等。本次特展帶領觀者透過實體考古探坑及虛擬數位電玩回到四百年以前的大員市鎮，在安平現地感受今昔交錯與考古學穿越時空的魅力。', '臺南市文化資產管理處', '臺南市安平區', '2025-01-01 00:00:00', '2025-03-23 00:00:00', '安平區（臺南市）=', 22.99008437, 120.1649949, '無資料', 'https://tmach-culture.tainan.gov.tw/activity.asp?mainid=6361FDA7-290C-4E6B-95D6-BEC2F0FF6DDE#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「考古埕－尋找熱蘭遮市鎮」特展-📽️考古埕x小影展📽️', `description`='透過國立成功大學考古學研究所團隊製作的4部主題影片放映，分享考古埕現地的考古歷程及歷史脈絡。\r\n\r\n「考古埕-尋找熱蘭遮市鎮」特展\r\n►►四大展區║探坑走廊／距今實驗室／鯤島旅行社／修復里院║\r\n「這場持續探尋臺南四百年歷史時空的考古行動，象徵著古都臺南過去、現在與未來樣貌的鏈結。」由劍獅埕／考古埕歷年研究發掘成果相伴，走向城市時空、物質、常民生活的反思，踏上今昔交錯／虛實交織的跨時空旅行，終於回歸彌足珍貴的每個當下和日常。\r\n四大展區內容包括近年大員市鎮考古發掘探坑、相關考古遺物展示及成果說明、考古科學體驗以及以大員市鎮為背景的電玩遊戲體驗等等。本次特展帶領觀者透過實體考古探坑及虛擬數位電玩回到四百年以前的大員市鎮，在安平現地感受今昔交錯與考古學穿越時空的魅力。', `organizer`='臺南市文化資產管理處', `address`='臺南市安平區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='安平區（臺南市）=', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='https://tmach-culture.tainan.gov.tw/activity.asp?mainid=6361FDA7-290C-4E6B-95D6-BEC2F0FF6DDE#', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc1926b32418088f1996', '「考古埕－尋找熱蘭遮市鎮」特展-考古埕x小書房', '📚考古埕x小書房📚\r\n臺南文化資產管理處《熱蘭遮城日誌》等出版品,將於《考古埕－尋找熱蘭遮市鎮》特展開放借閱，讓我們透過文字帶領，穿越時空看古今！\r\n\r\n↪️借閱時間：展館營運開放日09:30-16:30\r\n↪️借閱地點：考古埕@距今實驗室\r\n\r\n借閱方式＆注意事項：\r\n‼️借閱者本人憑身分證明證件於櫃檯押證借閱，請於借閱當日歸還，每人每次限借1冊。\r\n‼️所借書冊僅限於本特展空間範圍內進行閱讀，請愛惜公物，切勿擅自攜離。如有造成書冊毀損遺失，由借閱者照價賠償。\r\n\r\n「考古埕-尋找熱蘭遮市鎮」特展\r\n►►四大展區║探坑走廊／距今實驗室／鯤島旅行社／修復里院║\r\n「這場持續探尋臺南四百年歷史時空的考古行動，象徵著古都臺南過去、現在與未來樣貌的鏈結。」由劍獅埕／考古埕歷年研究發掘成果相伴，走向城市時空、物質、常民生活的反思，踏上今昔交錯／虛實交織的跨時空旅行，終於回歸彌足珍貴的每個當下和日常。\r\n四大展區內容包括近年大員市鎮考古發掘探坑、相關考古遺物展示及成果說明、考古科學體驗以及以大員市鎮為背景的電玩遊戲體驗等等。本次特展帶領觀者透過實體考古探坑及虛擬數位電玩回到四百年以前的大員市鎮，在安平現地感受今昔交錯與考古學穿越時空的魅力。', '臺南市文化資產管理處', '臺南市安平區', '2025-01-01 00:00:00', '2025-03-23 00:00:00', '安平區（臺南市）=', 22.99008437, 120.1649949, '無資料', 'https://tmach-culture.tainan.gov.tw/activity.asp?mainid=6361FDA7-290C-4E6B-95D6-BEC2F0FF6DDE#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「考古埕－尋找熱蘭遮市鎮」特展-考古埕x小書房', `description`='📚考古埕x小書房📚\r\n臺南文化資產管理處《熱蘭遮城日誌》等出版品,將於《考古埕－尋找熱蘭遮市鎮》特展開放借閱，讓我們透過文字帶領，穿越時空看古今！\r\n\r\n↪️借閱時間：展館營運開放日09:30-16:30\r\n↪️借閱地點：考古埕@距今實驗室\r\n\r\n借閱方式＆注意事項：\r\n‼️借閱者本人憑身分證明證件於櫃檯押證借閱，請於借閱當日歸還，每人每次限借1冊。\r\n‼️所借書冊僅限於本特展空間範圍內進行閱讀，請愛惜公物，切勿擅自攜離。如有造成書冊毀損遺失，由借閱者照價賠償。\r\n\r\n「考古埕-尋找熱蘭遮市鎮」特展\r\n►►四大展區║探坑走廊／距今實驗室／鯤島旅行社／修復里院║\r\n「這場持續探尋臺南四百年歷史時空的考古行動，象徵著古都臺南過去、現在與未來樣貌的鏈結。」由劍獅埕／考古埕歷年研究發掘成果相伴，走向城市時空、物質、常民生活的反思，踏上今昔交錯／虛實交織的跨時空旅行，終於回歸彌足珍貴的每個當下和日常。\r\n四大展區內容包括近年大員市鎮考古發掘探坑、相關考古遺物展示及成果說明、考古科學體驗以及以大員市鎮為背景的電玩遊戲體驗等等。本次特展帶領觀者透過實體考古探坑及虛擬數位電玩回到四百年以前的大員市鎮，在安平現地感受今昔交錯與考古學穿越時空的魅力。', `organizer`='臺南市文化資產管理處', `address`='臺南市安平區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='安平區（臺南市）=', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='https://tmach-culture.tainan.gov.tw/activity.asp?mainid=6361FDA7-290C-4E6B-95D6-BEC2F0FF6DDE#', `image_url`='