INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc1926b32418088f1997', '「考古埕－尋找熱蘭遮市鎮」特展-公眾考古見學【探索地下安平2025】', 'Ø 公眾考古見學－探索地下安平\r\n由考古學家帶路，走訪熱蘭遮市鎮，重新認識安平文化歷史！\r\n\r\n▍場次：10/17(四)、10/29(二)、11/6(三)、11/27(三)、12/18(三)、1/3(二)、1/22(三)、2/11(二)、2/27(四)\r\n\r\n★活動時間：15:00-17:00（預計導覽：1.5-2小時）\r\n★報到地點：鯤島旅行社-臺南市安平區延平街35號\r\n\r\n「考古埕-尋找熱蘭遮市鎮」特展\r\n►►四大展區║探坑走廊／距今實驗室／鯤島旅行社／修復里院║\r\n「這場持續探尋臺南四百年歷史時空的考古行動，象徵著古都臺南過去、現在與未來樣貌的鏈結。」由劍獅埕／考古埕歷年研究發掘成果相伴，走向城市時空、物質、常民生活的反思，踏上今昔交錯／虛實交織的跨時空旅行，終於回歸彌足珍貴的每個當下和日常。\r\n四大展區內容包括近年大員市鎮考古發掘探坑、相關考古遺物展示及成果說明、考古科學體驗以及以大員市鎮為背景的電玩遊戲體驗等等。本次特展帶領觀者透過實體考古探坑及虛擬數位電玩回到四百年以前的大員市鎮，在安平現地感受今昔交錯與考古學穿越時空的魅力。', '臺南市文化資產管理處', '臺南市安平區', '2025-01-03 00:00:00', '2025-02-27 00:00:00', '安平區（臺南市）=', 22.99008437, 120.1649949, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「考古埕－尋找熱蘭遮市鎮」特展-公眾考古見學【探索地下安平2025】', `description`='Ø 公眾考古見學－探索地下安平\r\n由考古學家帶路，走訪熱蘭遮市鎮，重新認識安平文化歷史！\r\n\r\n▍場次：10/17(四)、10/29(二)、11/6(三)、11/27(三)、12/18(三)、1/3(二)、1/22(三)、2/11(二)、2/27(四)\r\n\r\n★活動時間：15:00-17:00（預計導覽：1.5-2小時）\r\n★報到地點：鯤島旅行社-臺南市安平區延平街35號\r\n\r\n「考古埕-尋找熱蘭遮市鎮」特展\r\n►►四大展區║探坑走廊／距今實驗室／鯤島旅行社／修復里院║\r\n「這場持續探尋臺南四百年歷史時空的考古行動，象徵著古都臺南過去、現在與未來樣貌的鏈結。」由劍獅埕／考古埕歷年研究發掘成果相伴，走向城市時空、物質、常民生活的反思，踏上今昔交錯／虛實交織的跨時空旅行，終於回歸彌足珍貴的每個當下和日常。\r\n四大展區內容包括近年大員市鎮考古發掘探坑、相關考古遺物展示及成果說明、考古科學體驗以及以大員市鎮為背景的電玩遊戲體驗等等。本次特展帶領觀者透過實體考古探坑及虛擬數位電玩回到四百年以前的大員市鎮，在安平現地感受今昔交錯與考古學穿越時空的魅力。', `organizer`='臺南市文化資產管理處', `address`='臺南市安平區', `start_date`='2025-01-03 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='安平區（臺南市）=', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
