INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc1926b32418088f199a', '臺灣客家文化館教育推廣課程（114年1-3月）', '活動對象：一般民眾\r\n現場報名\r\n\r\n活動主題\r\n一月【節剪愛做家】：1、4、5、11、12、18、19、25、26、27\r\n為了迎接農曆新年，除舊布新，遽來共下瞭解客家剪紙的美麗吧\r\n農曆年【好客揤福趣】：1/29、30、31、2/1、2/2\r\n手作項目：相框\r\n\r\n二月【咚龍咚龍鏘】：8、9、15、16、22、23、28\r\n正月十五日元宵節這天對於苗栗客家人有一項重要的傳統活動「龍」，國語為ㄅㄤˋ（注音符號），客語讀為bong（羅馬音標，bong  liungˇ)。是鞭炮炸的意思，也就是用鞭炮「炸龍」的意思。龍活動不僅有迎春納福的意涵，更保有傳統習俗及文化傳承的深遠意義。歡迎來苗栗尞\r\n手作項目：火旁龍風鈴、福菜\r\n\r\n三月【窯滾讚炭】：1、2、8、9、15、16、22、23、29、30\r\n運用客家民族的產業代表「相思木炭」，讓學員瞭解客家民族如何就地取材自然環境中的相思樹，透過炭窯的建造，將相思木變成火燄旺、少碳、少煙、天然無毒的相思木炭\r\n手作項目：相思種子貼畫', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-01-04 00:00:00', '2025-03-30 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '剪紙相框+50;福菜瓶+50;火旁龍風鈴+50;相思種子貼畫+80', 'https://thcdc.hakka.gov.tw/1240/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺灣客家文化館教育推廣課程（114年1-3月）', `description`='活動對象：一般民眾\r\n現場報名\r\n\r\n活動主題\r\n一月【節剪愛做家】：1、4、5、11、12、18、19、25、26、27\r\n為了迎接農曆新年，除舊布新，遽來共下瞭解客家剪紙的美麗吧\r\n農曆年【好客揤福趣】：1/29、30、31、2/1、2/2\r\n手作項目：相框\r\n\r\n二月【咚龍咚龍鏘】：8、9、15、16、22、23、28\r\n正月十五日元宵節這天對於苗栗客家人有一項重要的傳統活動「龍」，國語為ㄅㄤˋ（注音符號），客語讀為bong（羅馬音標，bong  liungˇ)。是鞭炮炸的意思，也就是用鞭炮「炸龍」的意思。龍活動不僅有迎春納福的意涵，更保有傳統習俗及文化傳承的深遠意義。歡迎來苗栗尞\r\n手作項目：火旁龍風鈴、福菜\r\n\r\n三月【窯滾讚炭】：1、2、8、9、15、16、22、23、29、30\r\n運用客家民族的產業代表「相思木炭」，讓學員瞭解客家民族如何就地取材自然環境中的相思樹，透過炭窯的建造，將相思木變成火燄旺、少碳、少煙、天然無毒的相思木炭\r\n手作項目：相思種子貼畫', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-01-04 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='剪紙相框+50;福菜瓶+50;火旁龍風鈴+50;相思種子貼畫+80', `source_url`='https://thcdc.hakka.gov.tw/1240/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc1926b32418088f199b', '藝術生活化．生活化時尚', '關於皇墨藝\r\n公司成立於2022年，更專注提升孩童學習藝術與接觸複合式精品藝廊的成效，仍是皇墨藝藝術最大特色，皇墨藝公司擁有經驗豐富的團隊，來帶領孩童至國際觀的學習！以拓展藝術不僅僅是繪畫，更在生活當中成為相輔相成的角色。\r\n\r\n《 藝術生活化 生活化時尚》乃是皇墨藝藝術宗旨。\r\n皇墨藝藝術透過此次展覽，分享藝術美學的奧妙，追求的是孩子學習藝術上基本要領與多元領域，在藝術團隊帶領下更具備充分專業教學核心！未來，皇墨藝藝術更致力提升核心競爭力，追求細水長流、持續發展的向心力！', '苗栗縣苗北藝文中心', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-03-08 00:00:00', '2025-03-16 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝術生活化．生活化時尚', `description`='關於皇墨藝\r\n公司成立於2022年，更專注提升孩童學習藝術與接觸複合式精品藝廊的成效，仍是皇墨藝藝術最大特色，皇墨藝公司擁有經驗豐富的團隊，來帶領孩童至國際觀的學習！以拓展藝術不僅僅是繪畫，更在生活當中成為相輔相成的角色。\r\n\r\n《 藝術生活化 生活化時尚》乃是皇墨藝藝術宗旨。\r\n皇墨藝藝術透過此次展覽，分享藝術美學的奧妙，追求的是孩子學習藝術上基本要領與多元領域，在藝術團隊帶領下更具備充分專業教學核心！未來，皇墨藝藝術更致力提升核心競爭力，追求細水長流、持續發展的向心力！', `organizer`='苗栗縣苗北藝文中心', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc1926b32418088f199c', '創價公演--極緻天籟 無限美聲 RAJATON芬蘭阿卡貝拉之夜（2場次）', '2025創價公演邀請到享譽國際的「Rajaton」來台演出，帶給台灣樂迷無限驚喜！Rajaton是一支來自芬蘭的阿卡貝拉樂團，旨在以「人聲」之美與其無窮的可能性打動人心。芬蘭語中「Rajaton」意指「無邊無際」，恰如其分地反映了這支無伴奏合唱團對音樂獨特的詮釋方式。\r\nRajaton每年定期舉行約百場音樂會與工作坊，帶來各式各樣的歌曲、精彩紛呈的演唱風格及舞台呈現，讓全球樂迷為之瘋狂。\r\n這群特立獨行的音樂人始終以真誠的心及堅持來面對各種音樂風格。很難想像有任何人不會被他們的聲音所打動，或是有任何音樂風格他們無法駕馭。\r\n在故鄉芬蘭，Rajaton是一個真正成功的流行現象，他們對音樂的詮釋彌合了古典樂與主流樂之間常見的鴻溝。在藝術上不斷創新的挑戰，例如與電影或編舞家合作，更讓他們在音樂上「無邊無際」地成長與進化！\r\n或許正是他們對合唱藝術的深厚熱情、樂於分享的精神以及對歌唱的純粹享受，贏得了全球樂迷和評論家的喜愛與讚賞。他們的能量具有感染性，他們的音樂具有娛樂性和啟發性，歡迎透過這次的創價公演一起來認識並感受—Rajaton的「極緻天籟，無限美聲！」\r\n\r\n獲獎相關：Rajaton在芬蘭國內已獲得8張金唱片獎，3次「白金」獎，以及1次「雙白金」獎。此外，他們的專輯《Maa》在美國獲得了「最佳民謠歌曲獎」和「最佳民謠專輯獎」。被譽為「芬蘭精靈」的女子花式滑冰選手基拉‧科爾皮（Kiira Korpi）曾在「溫哥華奧運會」中使用了他們的歌曲《Butterfly》，讓Rajaton的音樂受到世界樂迷更多的矚目。', '台灣創價學會', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '票價+900;票價+1200;票價+1500;票價+1800;票價+2000', 'https://www.sokaculture.org.tw/performance/2025-soka-rajaton', '[]') ON DUPLICATE KEY UPDATE `activity_name`='創價公演--極緻天籟 無限美聲 RAJATON芬蘭阿卡貝拉之夜（2場次）', `description`='2025創價公演邀請到享譽國際的「Rajaton」來台演出，帶給台灣樂迷無限驚喜！Rajaton是一支來自芬蘭的阿卡貝拉樂團，旨在以「人聲」之美與其無窮的可能性打動人心。芬蘭語中「Rajaton」意指「無邊無際」，恰如其分地反映了這支無伴奏合唱團對音樂獨特的詮釋方式。\r\nRajaton每年定期舉行約百場音樂會與工作坊，帶來各式各樣的歌曲、精彩紛呈的演唱風格及舞台呈現，讓全球樂迷為之瘋狂。\r\n這群特立獨行的音樂人始終以真誠的心及堅持來面對各種音樂風格。很難想像有任何人不會被他們的聲音所打動，或是有任何音樂風格他們無法駕馭。\r\n在故鄉芬蘭，Rajaton是一個真正成功的流行現象，他們對音樂的詮釋彌合了古典樂與主流樂之間常見的鴻溝。在藝術上不斷創新的挑戰，例如與電影或編舞家合作，更讓他們在音樂上「無邊無際」地成長與進化！\r\n或許正是他們對合唱藝術的深厚熱情、樂於分享的精神以及對歌唱的純粹享受，贏得了全球樂迷和評論家的喜愛與讚賞。他們的能量具有感染性，他們的音樂具有娛樂性和啟發性，歡迎透過這次的創價公演一起來認識並感受—Rajaton的「極緻天籟，無限美聲！」\r\n\r\n獲獎相關：Rajaton在芬蘭國內已獲得8張金唱片獎，3次「白金」獎，以及1次「雙白金」獎。此外，他們的專輯《Maa》在美國獲得了「最佳民謠歌曲獎」和「最佳民謠專輯獎」。被譽為「芬蘭精靈」的女子花式滑冰選手基拉‧科爾皮（Kiira Korpi）曾在「溫哥華奧運會」中使用了他們的歌曲《Butterfly》，讓Rajaton的音樂受到世界樂迷更多的矚目。', `organizer`='台灣創價學會', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='票價+900;票價+1200;票價+1500;票價+1800;票價+2000', `source_url`='https://www.sokaculture.org.tw/performance/2025-soka-rajaton', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc1926b32418088f199d', '無資料', '為了譜寫在地藝術發展脈絡、純煉臺灣美學特色，本館以關注前輩藝術家歷史貢獻為宗旨，成立「藝術家專室」。展覽以《南薰藝韻》為名，向世人引見陳澄波、郭柏川、許武勇及沈哲哉，藉由梳理他們對於現代繪畫的探索，乃至東西方藝術互用與自身文化底蘊結合的內化過程，定義其對地方斯土的重要性。\r\n\r\n這四位畫家共同反映了臺灣現代藝術的發展，從第一代畫家在日治時期官展嶄露鋒芒開始，在臺灣這座四季如夏、所見之人事物景均閃動著白光的島嶼上，畫家多發展出使用豔彩純色或醒目光色來凸顯形象的立體、形狀與光影，而在這個看似大膽強烈、追求表現的特徵之下，卻又因自身文化的溯源省思、鄉土關懷和個人質地的透顯而展現一種纖巧與別緻，使得這些畫家的作品歷久彌新，陽剛中帶溫柔、獷達中見精巧、飽和中飛揚神采。端看他們奉獻給繪畫創作的一生，可見到臺灣美術第一代、第二代本土西畫家反映時代、寫照土地和表現自我的企圖。', '臺南市美術館', '臺南市中西區臺南市中西區忠義路二段 1 號', '臺南市美術館2館', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='為了譜寫在地藝術發展脈絡、純煉臺灣美學特色，本館以關注前輩藝術家歷史貢獻為宗旨，成立「藝術家專室」。展覽以《南薰藝韻》為名，向世人引見陳澄波、郭柏川、許武勇及沈哲哉，藉由梳理他們對於現代繪畫的探索，乃至東西方藝術互用與自身文化底蘊結合的內化過程，定義其對地方斯土的重要性。\r\n\r\n這四位畫家共同反映了臺灣現代藝術的發展，從第一代畫家在日治時期官展嶄露鋒芒開始，在臺灣這座四季如夏、所見之人事物景均閃動著白光的島嶼上，畫家多發展出使用豔彩純色或醒目光色來凸顯形象的立體、形狀與光影，而在這個看似大膽強烈、追求表現的特徵之下，卻又因自身文化的溯源省思、鄉土關懷和個人質地的透顯而展現一種纖巧與別緻，使得這些畫家的作品歷久彌新，陽剛中帶溫柔、獷達中見精巧、飽和中飛揚神采。端看他們奉獻給繪畫創作的一生，可見到臺灣美術第一代、第二代本土西畫家反映時代、寫照土地和表現自我的企圖。', `organizer`='臺南市美術館', `address`='臺南市中西區臺南市中西區忠義路二段 1 號', `location`='臺南市美術館2館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a3bc1926b32418088f199e', '2025年客家合唱比賽：一般合唱類、傳統山歌合唱類比賽暨頒獎典禮', '2025年客家合唱比賽\r\n為推動客家語言與文化永續傳承，透過客家歌曲之傳唱，提升客家語言文化與精神之能見度，增進客家族群認同及其他族群彼此尊重與欣賞，使客家語言豐富臺灣多元文化，特舉辦「客家合唱比賽」。\r\n\r\n比賽日期\r\n114年5月24日（星期六）至25日（星期日）／一般合唱類、傳統山歌合唱類比賽暨頒獎典禮\r\n114年5月25日（星期日）／現代阿卡貝拉類比賽\r\n\r\n比賽組別與資格\r\n(一)一般合唱類（Chorus）\r\n1.兒少組：國中以下（含國中）\r\n2.青少組：19歲以下、國中以上（含國中）\r\n3.社會組：18歲以上（含18歲）\r\n4.樂線組：55歲以上（含55歲）\r\n(二)傳統山歌合唱類（Hakka Folk Songs Chorus），年齡不限。\r\n(三)現代阿卡貝拉類（Contemporary A Cappella）\r\n1.學生組：在學學生（全團皆須現場持學生證佐證）\r\n2. 社會組：年齡不限\r\n年齡規範\r\n18歲以上【限民國96年5月25日(含)前出生】\r\n19歲以下【限民國95年5月25日後出生】\r\n55歲以上【限民國59年5月25日(含)前出生】\r\n一般合唱類參賽人員年齡資格以外人員比例，以不超過該團隊總參賽人數10%為原則。\r\n參賽人數\r\n一般合唱類、傳統山歌合唱類每隊可設指揮1人及伴奏若干人，無伴奏亦可，各隊人數（不含指揮、伴奏）至少16人，至多不超過60人，並得增報4人為候補團員；現代阿卡貝拉類每隊至少3人，至多不超過12人（不含音控）。\r\n同一人可跨類報名，但各類僅能報名一隊參賽。\r\n（例：1.林○明19歲，報名一般合唱類青少組某一隊，不得同時報名參加其他一般合唱類青少組之隊伍，亦不得再以社會組參加某一隊伍；2.黃○勛加入XX合唱團參賽一般合唱類青少組，可同時持學生證加入△△阿卡貝拉團參賽阿卡貝拉類學生組；3.陳○逸國小五年級，報名合唱類兒少組XX國小合唱團，可同時再加入△△社區合唱團，參與傳統山歌類賽事)。\r\n報名時間：即日起至114年4月14日（星期一）23時59分止。\r\n報名方式：本比賽一律採網路報名，並於114年4月14日（星期一）前以郵寄方式繳交書面資料，供主辦單位審查。\r\n比賽獎勵\r\n各類(組)獎勵如下\r\n第一名\r\n每類(組)1隊，各頒給獎座1座及獎狀1幀，獎金新臺幣10萬元整（含稅）\r\n第二名\r\n每類(組)1隊，各頒給獎座1座及獎狀1幀，獎金新臺幣6萬元整（含稅）\r\n第三名\r\n每類(組)1隊，各頒給獎座1座及獎狀1幀，獎金新臺幣4萬元整（含稅）\r\n佳作獎\r\n一般合唱類及現代阿卡貝拉類每組3隊、傳統山歌合唱類1隊，各頒給獎狀1幀，獎金新臺幣2萬元整（含稅）；惟一般合唱類樂線組，評審可依參賽團隊演出情形，另取佳作若干名。\r\n現代阿卡貝拉類評審團特別獎\r\n1隊，頒給獎狀1幀，獎金新臺幣1萬元整（含稅），評審團特別獎由評審於阿卡貝拉類依現場參賽團隊演出情形提名，且須經由評審過半以上認同，方可獲獎。\r\n比賽詳情請至活動網站查詢', '客家委員會', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-05-24 00:00:00', '2025-05-25 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', 'https://www.bigsong.com.tw/Hakkachoir', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年客家合唱比賽：一般合唱類、傳統山歌合唱類比賽暨頒獎典禮', `description`='2025年客家合唱比賽\r\n為推動客家語言與文化永續傳承，透過客家歌曲之傳唱，提升客家語言文化與精神之能見度，增進客家族群認同及其他族群彼此尊重與欣賞，使客家語言豐富臺灣多元文化，特舉辦「客家合唱比賽」。\r\n\r\n比賽日期\r\n114年5月24日（星期六）至25日（星期日）／一般合唱類、傳統山歌合唱類比賽暨頒獎典禮\r\n114年5月25日（星期日）／現代阿卡貝拉類比賽\r\n\r\n比賽組別與資格\r\n(一)一般合唱類（Chorus）\r\n1.兒少組：國中以下（含國中）\r\n2.青少組：19歲以下、國中以上（含國中）\r\n3.社會組：18歲以上（含18歲）\r\n4.樂線組：55歲以上（含55歲）\r\n(二)傳統山歌合唱類（Hakka Folk Songs Chorus），年齡不限。\r\n(三)現代阿卡貝拉類（Contemporary A Cappella）\r\n1.學生組：在學學生（全團皆須現場持學生證佐證）\r\n2. 社會組：年齡不限\r\n年齡規範\r\n18歲以上【限民國96年5月25日(含)前出生】\r\n19歲以下【限民國95年5月25日後出生】\r\n55歲以上【限民國59年5月25日(含)前出生】\r\n一般合唱類參賽人員年齡資格以外人員比例，以不超過該團隊總參賽人數10%為原則。\r\n參賽人數\r\n一般合唱類、傳統山歌合唱類每隊可設指揮1人及伴奏若干人，無伴奏亦可，各隊人數（不含指揮、伴奏）至少16人，至多不超過60人，並得增報4人為候補團員；現代阿卡貝拉類每隊至少3人，至多不超過12人（不含音控）。\r\n同一人可跨類報名，但各類僅能報名一隊參賽。\r\n（例：1.林○明19歲，報名一般合唱類青少組某一隊，不得同時報名參加其他一般合唱類青少組之隊伍，亦不得再以社會組參加某一隊伍；2.黃○勛加入XX合唱團參賽一般合唱類青少組，可同時持學生證加入△△阿卡貝拉團參賽阿卡貝拉類學生組；3.陳○逸國小五年級，報名合唱類兒少組XX國小合唱團，可同時再加入△△社區合唱團，參與傳統山歌類賽事)。\r\n報名時間：即日起至114年4月14日（星期一）23時59分止。\r\n報名方式：本比賽一律採網路報名，並於114年4月14日（星期一）前以郵寄方式繳交書面資料，供主辦單位審查。\r\n比賽獎勵\r\n各類(組)獎勵如下\r\n第一名\r\n每類(組)1隊，各頒給獎座1座及獎狀1幀，獎金新臺幣10萬元整（含稅）\r\n第二名\r\n每類(組)1隊，各頒給獎座1座及獎狀1幀，獎金新臺幣6萬元整（含稅）\r\n第三名\r\n每類(組)1隊，各頒給獎座1座及獎狀1幀，獎金新臺幣4萬元整（含稅）\r\n佳作獎\r\n一般合唱類及現代阿卡貝拉類每組3隊、傳統山歌合唱類1隊，各頒給獎狀1幀，獎金新臺幣2萬元整（含稅）；惟一般合唱類樂線組，評審可依參賽團隊演出情形，另取佳作若干名。\r\n現代阿卡貝拉類評審團特別獎\r\n1隊，頒給獎狀1幀，獎金新臺幣1萬元整（含稅），評審團特別獎由評審於阿卡貝拉類依現場參賽團隊演出情形提名，且須經由評審過半以上認同，方可獲獎。\r\n比賽詳情請至活動網站查詢', `organizer`='客家委員會', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-05-24 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='https://www.bigsong.com.tw/Hakkachoir', `image_url`='[]';
