INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535d126b3240c403d93a1', '台灣客家語言文化系列演講3 (共9場)', '為推廣本土語言，本館辦理台灣客家語言文化系列演講3，歡迎民眾踴躍參與。', '桃園市立圖書館', '桃園市中壢區中美路76號', '2025-01-16 00:00:00', '2025-06-19 00:00:00', '桃園市立圖書館中壢分館', 24.97993803, 121.2147243, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台灣客家語言文化系列演講3 (共9場)', `description`='為推廣本土語言，本館辦理台灣客家語言文化系列演講3，歡迎民眾踴躍參與。', `organizer`='桃園市立圖書館', `address`='桃園市中壢區中美路76號', `start_date`='2025-01-16 00:00:00', `end_date`='2025-06-19 00:00:00', `location`='桃園市立圖書館中壢分館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535d326b3240c403d93a3', '114年度【永續光環境創意展】', '本次展覽為鼓勵各種永續材料之開發、設計應用及提升工藝技藝，活絡生活應用與藝術創作，展現永續意識與優秀的創意品味，以「永續‧創新‧實驗」舉辦永續光環境創意競賽，發掘更多優秀的藝術創作者，以促進臺灣開發永續材料的可能性及生活美學之蓬勃發展。\r\n競賽獲獎燈光裝置作品將於2024/12/20-2025/3/9期間於中原文創園區戶外區域展出，夜間作品燈光齊發，展現全新能量，一同感受透過環境所構築出的永續之光！', '無資料', '桃園市中壢區忠仁路33號', '2025-01-01 00:00:00', '2025-03-09 00:00:00', '中原文創園區', 24.97993803, 121.2147243, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度【永續光環境創意展】', `description`='本次展覽為鼓勵各種永續材料之開發、設計應用及提升工藝技藝，活絡生活應用與藝術創作，展現永續意識與優秀的創意品味，以「永續‧創新‧實驗」舉辦永續光環境創意競賽，發掘更多優秀的藝術創作者，以促進臺灣開發永續材料的可能性及生活美學之蓬勃發展。\r\n競賽獲獎燈光裝置作品將於2024/12/20-2025/3/9期間於中原文創園區戶外區域展出，夜間作品燈光齊發，展現全新能量，一同感受透過環境所構築出的永續之光！', `organizer`='無資料', `address`='桃園市中壢區忠仁路33號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='中原文創園區', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535d726b3240c403d93a4', 'Pinilimayan石生繪世錄．紋山路–2024楊慕仁繪畫個展 (2024/12/04-2025/03/31)', '繪畫創作藝術家楊慕仁，1980年生，臺東卑南族石生群\r\n知本部落及初鹿部落族人，族名Ushiw Pakaruku。年幼時期喜歡握筆塗鴉而對繪畫產生濃厚厚興趣，小時候因許多有趣的漫畫、繪本及故事書，尤其是日本已故知名漫畫藝術家鳥山明先生的阿拉蕾與七龍珠，更是他童年時期大量臨摹的圆繪範本。除漫畫外，其伊索寓言、格林童話、安徒生童話、天方夜譚等世界知書籍中的故事和精美插畫，更是使他開始踏進繪畫神奇彩色的世界裡頭重要媒介成因，其成長過程至今，幾乎從事與繪畫相關的創作工作為主。此外，長年以來於部落學習、參與卑南族文化及族語振興相關工作，對於自身族群各文化領域有著深切的成長情感。', '桃園市政府原住民族行政局', '桃園市大溪區員林路一段29巷101號', '2025-01-01 00:00:00', '2025-03-05 00:00:00', '桃園市原住民族文化會館', 24.896414, 121.2822299, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Pinilimayan石生繪世錄．紋山路–2024楊慕仁繪畫個展 (2024/12/04-2025/03/31)', `description`='繪畫創作藝術家楊慕仁，1980年生，臺東卑南族石生群\r\n知本部落及初鹿部落族人，族名Ushiw Pakaruku。年幼時期喜歡握筆塗鴉而對繪畫產生濃厚厚興趣，小時候因許多有趣的漫畫、繪本及故事書，尤其是日本已故知名漫畫藝術家鳥山明先生的阿拉蕾與七龍珠，更是他童年時期大量臨摹的圆繪範本。除漫畫外，其伊索寓言、格林童話、安徒生童話、天方夜譚等世界知書籍中的故事和精美插畫，更是使他開始踏進繪畫神奇彩色的世界裡頭重要媒介成因，其成長過程至今，幾乎從事與繪畫相關的創作工作為主。此外，長年以來於部落學習、參與卑南族文化及族語振興相關工作，對於自身族群各文化領域有著深切的成長情感。', `organizer`='桃園市政府原住民族行政局', `address`='桃園市大溪區員林路一段29巷101號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='桃園市原住民族文化會館', `latitude`=24.896414, `longitude`=121.2822299, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535d826b3240c403d93a6', '戀舊喜新/新樂軒北管四點睛古物修復成果展｜金長和媽祖水仙文物館', '😄🎉🎉展期延長至114年6月30日喔~~\r\n「喜新戀舊~新樂軒北管四點睛古物修復成果展」自今 (113) 年6月29日開展以來，除了特展之外，也規劃了文物修復體驗、修復倫理，結合實作與理論等課程，獲大家一致好評，原訂展期至12月31日，經與借展老師(蔡楊吉鑿花保存藝師、莊竣傑修復師)協商後，展期延長至114年6月30日，歡迎您蒞臨金長和媽祖水仙文物館參觀!!!\r\n新樂軒為日治時期新竹傳統戲曲北管之一，長期受當地商紳支持，出陣傢俬以精緻華麗著稱，其中四點睛托燈、彩牌、鑼桿、鼓架等木質古物，堪稱新竹地區精湛木雕工藝的代表作，更是出陣隊伍中最吸睛的四件傢俬。忠實紀錄日治初期竹塹北管戲曲演出盛況，見證竹塹地區北管戲曲與木雕工藝發展歷史，2019年由新竹市政府指定為一般古物。\r\n百年古物歷經歲月滄桑，出陣遊街不免偶有磕碰，又因曾經流落在外，保存環境惡劣，造成構件受損佚失等傷害。所幸古物終能回歸新樂軒，由長和宮金長和媽祖水仙文物館典藏公開展示，再次回到大家眼前。', '新竹市長和宮', '新竹市北區北門街155號', '2025-01-01 00:00:00', '2025-06-30 00:00:00', '新竹市長和宮', 24.8093581, 120.965119, '無資料', 'https://www.facebook.com/permalink.php?story_fbid=pfbid02z99DDMQqxTNTRe8rh4BJE7uH6YQ9R9wNEA38skBLSiw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='戀舊喜新/新樂軒北管四點睛古物修復成果展｜金長和媽祖水仙文物館', `description`='😄🎉🎉展期延長至114年6月30日喔~~\r\n「喜新戀舊~新樂軒北管四點睛古物修復成果展」自今 (113) 年6月29日開展以來，除了特展之外，也規劃了文物修復體驗、修復倫理，結合實作與理論等課程，獲大家一致好評，原訂展期至12月31日，經與借展老師(蔡楊吉鑿花保存藝師、莊竣傑修復師)協商後，展期延長至114年6月30日，歡迎您蒞臨金長和媽祖水仙文物館參觀!!!\r\n新樂軒為日治時期新竹傳統戲曲北管之一，長期受當地商紳支持，出陣傢俬以精緻華麗著稱，其中四點睛托燈、彩牌、鑼桿、鼓架等木質古物，堪稱新竹地區精湛木雕工藝的代表作，更是出陣隊伍中最吸睛的四件傢俬。忠實紀錄日治初期竹塹北管戲曲演出盛況，見證竹塹地區北管戲曲與木雕工藝發展歷史，2019年由新竹市政府指定為一般古物。\r\n百年古物歷經歲月滄桑，出陣遊街不免偶有磕碰，又因曾經流落在外，保存環境惡劣，造成構件受損佚失等傷害。所幸古物終能回歸新樂軒，由長和宮金長和媽祖水仙文物館典藏公開展示，再次回到大家眼前。', `organizer`='新竹市長和宮', `address`='新竹市北區北門街155號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='新竹市長和宮', `latitude`=24.8093581, `longitude`=120.965119, `ticket_price`='無資料', `source_url`='https://www.facebook.com/permalink.php?story_fbid=pfbid02z99DDMQqxTNTRe8rh4BJE7uH6YQ9R9wNEA38skBLSiw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535dd26b3240c403d93a8', '臺南市東區裕文圖書館- 114年2月 小葫蘆歡樂唱遊', '由志工老師精心挑選優質繪本，推廣親子共讀，帶領孩子一起進入書中世界，同時會在故事結束後增加一些小手作，讓孩子聽得開心、玩得開心。\r\n2/05 長壽湯仙女 - 圓圓阿姨 \r\n2/12 我們的俱樂部 - 小蟲子阿姨 \r\n2/19 跳吧!青蛙小畢 - Apple阿姨 \r\n2/26 哈利的花毛衣 - 藍鯨媽媽', '臺南市東區裕文圖書館', '臺南市東區裕信路237號', '2025-02-05 00:00:00', '2025-02-26 00:00:00', '臺南市東區裕文圖書館', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市東區裕文圖書館- 114年2月 小葫蘆歡樂唱遊', `description`='由志工老師精心挑選優質繪本，推廣親子共讀，帶領孩子一起進入書中世界，同時會在故事結束後增加一些小手作，讓孩子聽得開心、玩得開心。\r\n2/05 長壽湯仙女 - 圓圓阿姨 \r\n2/12 我們的俱樂部 - 小蟲子阿姨 \r\n2/19 跳吧!青蛙小畢 - Apple阿姨 \r\n2/26 哈利的花毛衣 - 藍鯨媽媽', `organizer`='臺南市東區裕文圖書館', `address`='臺南市東區裕信路237號', `start_date`='2025-02-05 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='臺南市東區裕文圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
