INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535e026b3240c403d93aa', '「波力Poli遊馬村」特展', '馬村設計實驗室秉持著「為老空間找到新鮮事，為舊事物賦予新生命」的核心精神，2025年以「眷村休閒娛樂」出發，邀請原住戶分享當時的生活的場域及生活紀事，透過田野調查梳理整體眷村文化脈絡，媒合文創產業透過設計重新詮釋過往的記 憶，打造桃園專屬的在地生活品牌。\r\n本次「波力 Poli 遊馬村」特展透過口述歷史搜集相關展品呈現眷村的休閒娛樂、童年回憶與社區生活，並邀請到小朋友的偶像-波力 Poli 救援小英雄加入，以及馬祖新村的眷村精靈帶領，透過故事的方式啟發更多觀眾對於空間與社群的連結以及 文化傳承的思考，同時結合展區的解謎任務，邀請民眾探索歷史背景下的生活點滴; 最後以角色串連眷村生活中常見的娛樂方式打造焦點商品，在賦予新樣貌的同時，共同保留下眷村文化的溫暖與韌性。\r\n特展的展覽區域內容精彩豐富，分為三大主題區：「眷村話家常」，讓大家重溫眷村的公共生活氛圍；「懷舊時光機」，展示老物件重現當年生活的點滴記憶；「紀念的禮物」，推出與波力小英雄合作的限定文創商品，包括「波力象棋」、「波力撲克牌」，還有琺瑯杯、筆記本、限量貼紙等，絕對讓波力迷們愛不釋手！', '桃園市政府文化局', '桃園市中壢區馬祖新村11~20號', '2025-01-23 00:00:00', '2025-03-23 00:00:00', '馬祖新村眷村文創園區', 24.935843, 121.237822, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「波力Poli遊馬村」特展', `description`='馬村設計實驗室秉持著「為老空間找到新鮮事，為舊事物賦予新生命」的核心精神，2025年以「眷村休閒娛樂」出發，邀請原住戶分享當時的生活的場域及生活紀事，透過田野調查梳理整體眷村文化脈絡，媒合文創產業透過設計重新詮釋過往的記 憶，打造桃園專屬的在地生活品牌。\r\n本次「波力 Poli 遊馬村」特展透過口述歷史搜集相關展品呈現眷村的休閒娛樂、童年回憶與社區生活，並邀請到小朋友的偶像-波力 Poli 救援小英雄加入，以及馬祖新村的眷村精靈帶領，透過故事的方式啟發更多觀眾對於空間與社群的連結以及 文化傳承的思考，同時結合展區的解謎任務，邀請民眾探索歷史背景下的生活點滴; 最後以角色串連眷村生活中常見的娛樂方式打造焦點商品，在賦予新樣貌的同時，共同保留下眷村文化的溫暖與韌性。\r\n特展的展覽區域內容精彩豐富，分為三大主題區：「眷村話家常」，讓大家重溫眷村的公共生活氛圍；「懷舊時光機」，展示老物件重現當年生活的點滴記憶；「紀念的禮物」，推出與波力小英雄合作的限定文創商品，包括「波力象棋」、「波力撲克牌」，還有琺瑯杯、筆記本、限量貼紙等，絕對讓波力迷們愛不釋手！', `organizer`='桃園市政府文化局', `address`='桃園市中壢區馬祖新村11~20號', `start_date`='2025-01-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='馬祖新村眷村文創園區', `latitude`=24.935843, `longitude`=121.237822, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535e026b3240c403d93ab', '藝文沙龍：114年2月影片欣賞', '藝文沙龍 The Art Salon\r\n活動名稱》影片欣賞\r\n活動時間》每週六、週日 9:30各一場\r\n活動地點》臺南文化中心藝文沙龍\r\n活動內容》\r\n03/01(六)、03/02(日) 快一秒的他 One Second Ahead（普遍級，片長119分）\r\n\r\n03/08(六)、03/09 (日) 本日公休 Day Off (普遍級，片長105分）\r\n\r\n03/15(六)、03/16(日) 芭比 Barbie (普遍級，片長114 分)\r\n\r\n03/22(六)、03/23(日) 米其林主廚：百年的滋味 sio：Beginning of a Restaurant Lasts 100 Years (普遍級，紀錄片，片長74 分)\r\n\r\n03/29(六)、03/30(日) 我的天堂城市 My Heavenly City (保護級，片長120 分)\r\n\r\n叮嚀事項》\r\n1.憑身分相關證件或市立圖書館借閱證於開演前半小時入場（每場限30人）。     \r\n2.準時開演，逾時不候；開演15分鐘後禁止入場。\r\n3.國中以下學童請由家長全程陪同觀賞。\r\n※每月最後一週五為清潔日(3/28)，該日閉館。\r\n', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝文沙龍：114年2月影片欣賞', `description`='藝文沙龍 The Art Salon\r\n活動名稱》影片欣賞\r\n活動時間》每週六、週日 9:30各一場\r\n活動地點》臺南文化中心藝文沙龍\r\n活動內容》\r\n03/01(六)、03/02(日) 快一秒的他 One Second Ahead（普遍級，片長119分）\r\n\r\n03/08(六)、03/09 (日) 本日公休 Day Off (普遍級，片長105分）\r\n\r\n03/15(六)、03/16(日) 芭比 Barbie (普遍級，片長114 分)\r\n\r\n03/22(六)、03/23(日) 米其林主廚：百年的滋味 sio：Beginning of a Restaurant Lasts 100 Years (普遍級，紀錄片，片長74 分)\r\n\r\n03/29(六)、03/30(日) 我的天堂城市 My Heavenly City (保護級，片長120 分)\r\n\r\n叮嚀事項》\r\n1.憑身分相關證件或市立圖書館借閱證於開演前半小時入場（每場限30人）。     \r\n2.準時開演，逾時不候；開演15分鐘後禁止入場。\r\n3.國中以下學童請由家長全程陪同觀賞。\r\n※每月最後一週五為清潔日(3/28)，該日閉館。\r\n', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
