INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535e426b3240c403d93b2', '2025台灣燈會-《游光小鯉》共創燈光展', '《游光小鯉》是與新街國小學童共創的燈籠藝術，以金魚為造型，燈籠材料選用環保紙質，運用水拓技法，展現多彩、流動的金魚之美。作品不僅象徵春節的吉祥寓意，更透過與孩子的創作合作，彰顯在地文化的共融與傳承。', '桃園市政府文化局', '桃園市中壢區復興路99號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '中平路故事館', 24.9555605, 121.2245426, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會-《游光小鯉》共創燈光展', `description`='《游光小鯉》是與新街國小學童共創的燈籠藝術，以金魚為造型，燈籠材料選用環保紙質，運用水拓技法，展現多彩、流動的金魚之美。作品不僅象徵春節的吉祥寓意，更透過與孩子的創作合作，彰顯在地文化的共融與傳承。', `organizer`='桃園市政府文化局', `address`='桃園市中壢區復興路99號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='中平路故事館', `latitude`=24.9555605, `longitude`=121.2245426, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535e426b3240c403d93b3', '2025台灣燈會-《街巷微光》共創燈光展 ', '《街巷微光》是與中壢商圈店家共創的燈箱裝置，每個燈箱內部填充著店家與顧客們的留言互動小卡，燈箱外部採用壓克力材質，內置LED燈光。這些燈箱如街巷中的微光，串聯起商圈與故事館的文化脈絡，呈現出在地的豐富故事。', '桃園市政府文化局', '桃園市中壢區復興路99號', '2025-01-01 00:00:00', '2025-03-31 00:00:00', '中平路故事館', 24.9555605, 121.2245426, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會-《街巷微光》共創燈光展 ', `description`='《街巷微光》是與中壢商圈店家共創的燈箱裝置，每個燈箱內部填充著店家與顧客們的留言互動小卡，燈箱外部採用壓克力材質，內置LED燈光。這些燈箱如街巷中的微光，串聯起商圈與故事館的文化脈絡，呈現出在地的豐富故事。', `organizer`='桃園市政府文化局', `address`='桃園市中壢區復興路99號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='中平路故事館', `latitude`=24.9555605, `longitude`=121.2245426, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535e526b3240c403d93b4', '2025台灣燈會：《好癒時光》共創燈飾展', '《好癒時光》共創燈飾展，邀請彩墨花⿃畫林宏玲講師、⽇本植物彩繪盧詩詠講師與在地社區，就⽇式宿舍文化歷史，共創藝術燈籠，並結合園區特色打造夢幻燈飾，沉浸於日式建築暖心氛圍中，邀請大家一起來點亮桃園77藝文町！', '桃園市政府文化局', '桃園市桃園區中正路77巷5號', '2025-01-04 00:00:00', '2025-03-02 00:00:00', '桃園77藝文町', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會：《好癒時光》共創燈飾展', `description`='《好癒時光》共創燈飾展，邀請彩墨花⿃畫林宏玲講師、⽇本植物彩繪盧詩詠講師與在地社區，就⽇式宿舍文化歷史，共創藝術燈籠，並結合園區特色打造夢幻燈飾，沉浸於日式建築暖心氛圍中，邀請大家一起來點亮桃園77藝文町！', `organizer`='桃園市政府文化局', `address`='桃園市桃園區中正路77巷5號', `start_date`='2025-01-04 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='桃園77藝文町', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535e626b3240c403d93b5', '2025台灣燈會-馬祖新村園區點亮-「星星點燈計畫」展', '馬祖新村是一個擁有「星星滿天飛」美名的將軍村！這次以「星星點燈計畫」為主軸，設計了陸軍彩繪小戰車主燈牆，30輛超可愛的小戰車在夜晚閃閃發光，每一輛都是民眾共創的結晶，超級吸睛！沿著步道走到悅心亭，滿地的星星燈就像在說：「快來走走，跟我們一起閃耀吧！」馬村1號眷舍戶外，還有藝術駐村紀念的手印大地球燈，上面印的手手真的是可愛到不行！整個園區星光點點，簡直是懷舊與現代完美融合！', '桃園市政府文化局', '桃園市中壢區馬祖新村11~20號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '馬祖新村眷村文創園區', 24.935843, 121.237822, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會-馬祖新村園區點亮-「星星點燈計畫」展', `description`='馬祖新村是一個擁有「星星滿天飛」美名的將軍村！這次以「星星點燈計畫」為主軸，設計了陸軍彩繪小戰車主燈牆，30輛超可愛的小戰車在夜晚閃閃發光，每一輛都是民眾共創的結晶，超級吸睛！沿著步道走到悅心亭，滿地的星星燈就像在說：「快來走走，跟我們一起閃耀吧！」馬村1號眷舍戶外，還有藝術駐村紀念的手印大地球燈，上面印的手手真的是可愛到不行！整個園區星光點點，簡直是懷舊與現代完美融合！', `organizer`='桃園市政府文化局', `address`='桃園市中壢區馬祖新村11~20號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='馬祖新村眷村文創園區', `latitude`=24.935843, `longitude`=121.237822, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
