INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535f026b3240c403d93bf', '「考古埕－尋找熱蘭遮市鎮」特展-【親子大眾考古走讀2025】', 'Ø 親子大眾考古走讀\r\n熱蘭遮市鎮探索趣，穿越時空看古今！\r\n*走讀小旅行原則訂於展覽期間每月第三週週末上午、下午舉辦。\r\n\r\n▍ 場次：10/26(六)、10/27(日)、11/16(六)、11/17(日)、12/21(六)、12/22(日)、1/18(六)、1/19(日)、2/15(六)、2/16(日)、3/15(六)、3/16(日)\r\n\r\n★上午活動時間：10:00-12:00\r\n★下午活動時間：13:30-15:30\r\n★報到地點：鯤島旅行社-臺南市安平區延平街35號\r\n\r\n★親子大眾考古走讀－學校／社區加碼開團：特展營運期間，另有額外開放各級學校及社區團體預約申請報名「考古埕－尋找熱蘭遮市鎮」導覽走讀行程，每個月限定10團，每團人數原則限定25人以內（若有超過人數上限之報團需求，請於洽詢時提前告知，以利執行單位評估確認可行性）。\r\n\r\n★親子大眾考古走讀－學校／社區加場報團方式：如有報團意願，敬請掃描相關附件海報QR-Code加入特展官方LINE社群，或與協辦執行單位「傑森全球整合行銷」團隊洽詢聯繫，將有專人服務說明並協助後續事宜。（聯絡窗口：王先生；電話：0972-011511；電子郵件:shuhaowang@liontravel.com）\r\n\r\n「考古埕-尋找熱蘭遮市鎮」特展\r\n►►四大展區║探坑走廊／距今實驗室／鯤島旅行社／修復里院║\r\n「這場持續探尋臺南四百年歷史時空的考古行動，象徵著古都臺南過去、現在與未來樣貌的鏈結。」由劍獅埕／考古埕歷年研究發掘成果相伴，走向城市時空、物質、常民生活的反思，踏上今昔交錯／虛實交織的跨時空旅行，終於回歸彌足珍貴的每個當下和日常。\r\n四大展區內容包括近年大員市鎮考古發掘探坑、相關考古遺物展示及成果說明、考古科學體驗以及以大員市鎮為背景的電玩遊戲體驗等等。本次特展帶領觀者透過實體考古探坑及虛擬數位電玩回到四百年以前的大員市鎮，在安平現地感受今昔交錯與考古學穿越時空的魅力。\r\n', '臺南市文化資產管理處', '臺南市安平區', '2025-01-18 00:00:00', '2025-03-16 00:00:00', '安平區（臺南市）=', 22.99008437, 120.1649949, '--+--', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「考古埕－尋找熱蘭遮市鎮」特展-【親子大眾考古走讀2025】', `description`='Ø 親子大眾考古走讀\r\n熱蘭遮市鎮探索趣，穿越時空看古今！\r\n*走讀小旅行原則訂於展覽期間每月第三週週末上午、下午舉辦。\r\n\r\n▍ 場次：10/26(六)、10/27(日)、11/16(六)、11/17(日)、12/21(六)、12/22(日)、1/18(六)、1/19(日)、2/15(六)、2/16(日)、3/15(六)、3/16(日)\r\n\r\n★上午活動時間：10:00-12:00\r\n★下午活動時間：13:30-15:30\r\n★報到地點：鯤島旅行社-臺南市安平區延平街35號\r\n\r\n★親子大眾考古走讀－學校／社區加碼開團：特展營運期間，另有額外開放各級學校及社區團體預約申請報名「考古埕－尋找熱蘭遮市鎮」導覽走讀行程，每個月限定10團，每團人數原則限定25人以內（若有超過人數上限之報團需求，請於洽詢時提前告知，以利執行單位評估確認可行性）。\r\n\r\n★親子大眾考古走讀－學校／社區加場報團方式：如有報團意願，敬請掃描相關附件海報QR-Code加入特展官方LINE社群，或與協辦執行單位「傑森全球整合行銷」團隊洽詢聯繫，將有專人服務說明並協助後續事宜。（聯絡窗口：王先生；電話：0972-011511；電子郵件:shuhaowang@liontravel.com）\r\n\r\n「考古埕-尋找熱蘭遮市鎮」特展\r\n►►四大展區║探坑走廊／距今實驗室／鯤島旅行社／修復里院║\r\n「這場持續探尋臺南四百年歷史時空的考古行動，象徵著古都臺南過去、現在與未來樣貌的鏈結。」由劍獅埕／考古埕歷年研究發掘成果相伴，走向城市時空、物質、常民生活的反思，踏上今昔交錯／虛實交織的跨時空旅行，終於回歸彌足珍貴的每個當下和日常。\r\n四大展區內容包括近年大員市鎮考古發掘探坑、相關考古遺物展示及成果說明、考古科學體驗以及以大員市鎮為背景的電玩遊戲體驗等等。本次特展帶領觀者透過實體考古探坑及虛擬數位電玩回到四百年以前的大員市鎮，在安平現地感受今昔交錯與考古學穿越時空的魅力。\r\n', `organizer`='臺南市文化資產管理處', `address`='臺南市安平區', `start_date`='2025-01-18 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='安平區（臺南市）=', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='--+--', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535f026b3240c403d93c0', '梅澤捨次郎－檔案中的生命軌跡', '歡迎走進梅澤捨次郎的建築世界！作為臺南市美術館（原臺南警察署）一館的建築師創造出許多經典的建築設計。本展以家屬於2024年捐贈的珍貴檔案為核心，帶您認識他的生平故事、建築特色，並揭開檔案保存背後的價值與意義。一起來感受時代的脈動與歷史的溫度！', '臺南市美術館', '臺南市中西區臺南市中西區南門路 37 號', '2025-01-25 00:00:00', '2025-12-31 00:00:00', '臺南市美術館1館', 22.99594458, 120.192874, '無資料', 'https://www.tnam.museum/exhibition/detail/577', '[]') ON DUPLICATE KEY UPDATE `activity_name`='梅澤捨次郎－檔案中的生命軌跡', `description`='歡迎走進梅澤捨次郎的建築世界！作為臺南市美術館（原臺南警察署）一館的建築師創造出許多經典的建築設計。本展以家屬於2024年捐贈的珍貴檔案為核心，帶您認識他的生平故事、建築特色，並揭開檔案保存背後的價值與意義。一起來感受時代的脈動與歷史的溫度！', `organizer`='臺南市美術館', `address`='臺南市中西區臺南市中西區南門路 37 號', `start_date`='2025-01-25 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺南市美術館1館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='https://www.tnam.museum/exhibition/detail/577', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535f026b3240c403d93c1', '吉祥歲月__十二生肖版印年畫展', '展覽展出作品包含從第29屆至第40屆(2014―2025)，這12年在版印年畫徵選競賽中，各屆首獎與邀請製作作品。每位創作者，以自己的繪畫語言和版畫技巧，創作出兼具傳統與現代美學的現代年畫。版印年畫是與大眾分享的藝術品，表現力最廣、感染力最強、觀賞性最佳的一種版畫類型，親民易懂且清晰傳達著祈福平安的心意。 在新的一年來臨之際，欣賞十二生肖版印年畫帶來的年味，同時感受創作者藉以年畫內容來傳達祝福之意，祝福人人萬事如事，平安吉祥。', '臺南市美術館', '臺南市中西區臺南市中西區南門路 37 號', '2025-01-24 00:00:00', '2025-03-02 00:00:00', '臺南市美術館1館', 22.99594458, 120.192874, '詳參　https://www.tnam.museum/visit/hours_tickets+--', 'https://www.tnam.museum/exhibition/detail/579', '[]') ON DUPLICATE KEY UPDATE `activity_name`='吉祥歲月__十二生肖版印年畫展', `description`='展覽展出作品包含從第29屆至第40屆(2014―2025)，這12年在版印年畫徵選競賽中，各屆首獎與邀請製作作品。每位創作者，以自己的繪畫語言和版畫技巧，創作出兼具傳統與現代美學的現代年畫。版印年畫是與大眾分享的藝術品，表現力最廣、感染力最強、觀賞性最佳的一種版畫類型，親民易懂且清晰傳達著祈福平安的心意。 在新的一年來臨之際，欣賞十二生肖版印年畫帶來的年味，同時感受創作者藉以年畫內容來傳達祝福之意，祝福人人萬事如事，平安吉祥。', `organizer`='臺南市美術館', `address`='臺南市中西區臺南市中西區南門路 37 號', `start_date`='2025-01-24 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='臺南市美術館1館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='詳參　https://www.tnam.museum/visit/hours_tickets+--', `source_url`='https://www.tnam.museum/exhibition/detail/579', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535f026b3240c403d93c2', '展覽 : 全齡敞開「創˙銀鈴」', '臺南市美術館「創˙銀鈴」是對全齡敞開、強調多元包容與尊重差異的學習空間，與大眾一起探索什麼是「成長」，鼓勵大家在人生的旅途之中，認識自己並迎接生命的變化與挑戰。無論現在走到生命的哪一個階段，邀請你走入展間，一同感受成長的酸甜苦澀、想像未知但值得期待的未來，然後勇敢綻放屬於自己的絢爛色彩！', '臺南市美術館', '臺南市中西區臺南市中西區南門路 37 號', '2025-01-01 00:00:00', '2025-12-28 00:00:00', '臺南市美術館1館', 22.99594458, 120.192874, '--+--', 'https://www.tnam.museum/exhibition/detail/570', '[]') ON DUPLICATE KEY UPDATE `activity_name`='展覽 : 全齡敞開「創˙銀鈴」', `description`='臺南市美術館「創˙銀鈴」是對全齡敞開、強調多元包容與尊重差異的學習空間，與大眾一起探索什麼是「成長」，鼓勵大家在人生的旅途之中，認識自己並迎接生命的變化與挑戰。無論現在走到生命的哪一個階段，邀請你走入展間，一同感受成長的酸甜苦澀、想像未知但值得期待的未來，然後勇敢綻放屬於自己的絢爛色彩！', `organizer`='臺南市美術館', `address`='臺南市中西區臺南市中西區南門路 37 號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-28 00:00:00', `location`='臺南市美術館1館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='--+--', `source_url`='https://www.tnam.museum/exhibition/detail/570', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535f026b3240c403d93c3', '無資料', '2024 實構築展覽 Non-Parallel: [ 無 ] 平行，旨在呈現疫情解封後完工的建築作品。我們將揭開建築背後不同單位——建築師、營造廠、業主——之間的多重宇宙，勾勒出一個看似平行卻環環相扣的實構築世界，這些「平行」狀態不僅反映了臺灣當下的現實，更是臺灣社會的縮影。\r\n\r\n本次展覽所挑選的作品，各自反映了當代社會所面臨的各種議題的真實面對。觀者可以從這些建築作品中看見建築師、營造廠與業主在面對這些議題時的不同角度和立場，以及最終建成空間所展現的態度與構築回應。', '臺南市美術館', '臺南市中西區臺南市中西區忠義路二段 1 號', '臺南市美術館2館', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='2024 實構築展覽 Non-Parallel: [ 無 ] 平行，旨在呈現疫情解封後完工的建築作品。我們將揭開建築背後不同單位——建築師、營造廠、業主——之間的多重宇宙，勾勒出一個看似平行卻環環相扣的實構築世界，這些「平行」狀態不僅反映了臺灣當下的現實，更是臺灣社會的縮影。\r\n\r\n本次展覽所挑選的作品，各自反映了當代社會所面臨的各種議題的真實面對。觀者可以從這些建築作品中看見建築師、營造廠與業主在面對這些議題時的不同角度和立場，以及最終建成空間所展現的態度與構築回應。', `organizer`='臺南市美術館', `address`='臺南市中西區臺南市中西區忠義路二段 1 號', `location`='臺南市美術館2館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535f026b3240c403d93c5', '吾妄之境 The Fantasy Wonderland', 'ACG為數位時代下日益蓬勃發展且日常化的創作類別，逐漸流行並普及於大眾生活場域中。而作為新興的藝術表現形式，在這二次元的世界中，其一以女性向為主，蓬勃發展中的創作主題－－BL（Boy’s Love），成為值得關注的現象。本次展覽將透過時代背景及性別凝視轉換的觀點切入，探討BL主題如何突破次元，進入當代社會。', '臺南市美術館', '臺南市中西區臺南市中西區忠義路二段 1 號', '2025-01-01 00:00:00', '2025-03-16 00:00:00', '臺南市美術館2館', 22.99594458, 120.192874, '詳參　https://www.tnam.museum/visit/hours_tickets+--', 'https://www.tnam.museum/exhibition/detail/561', '[]') ON DUPLICATE KEY UPDATE `activity_name`='吾妄之境 The Fantasy Wonderland', `description`='ACG為數位時代下日益蓬勃發展且日常化的創作類別，逐漸流行並普及於大眾生活場域中。而作為新興的藝術表現形式，在這二次元的世界中，其一以女性向為主，蓬勃發展中的創作主題－－BL（Boy’s Love），成為值得關注的現象。本次展覽將透過時代背景及性別凝視轉換的觀點切入，探討BL主題如何突破次元，進入當代社會。', `organizer`='臺南市美術館', `address`='臺南市中西區臺南市中西區忠義路二段 1 號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺南市美術館2館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='詳參　https://www.tnam.museum/visit/hours_tickets+--', `source_url`='https://www.tnam.museum/exhibition/detail/561', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535f026b3240c403d93c7', '版畫浪潮：2024臺南國際版畫展', '「版畫浪潮-2024臺南國際版畫展」是一場聚焦亞太地區優秀版畫藝術且極具意義的國際藝術盛事，邀請臺灣、日本、韓國、泰國、美國、澳洲、馬來西亞、孟加拉等國的藝術家齊聚臺南，透過版畫這一歷史悠久的藝術形式，進行文化的碰撞與思想的交流。臺灣週邊擁有如黑潮等太平洋上重要的洋流，不僅象徵著自然界中跨越國界的力量，也暗示著文化與藝術的流動。臺灣作為太平洋流流經的重要路線之一，自古便是東西方文化的交匯點，這次展覽正是以此為寓意，將臺灣作為連結亞太藝術的樞紐，展現當代版畫藝術的多樣性與創新性。\r\n\r\n臺南市美術館透過當代藝術詮釋移工議題，邀請來自不同背景的移工及國內外藝術家，以「漂移之味」、「逃逸之方」、「艷陽下南風吹」三個子題，經由生命經驗的觀察、獨白與轉譯、交流與合作等創造過程，揭示移工不為人知的面貌。展覽也引發我們思考，在以移工為主體的多重情境中，始終隱藏著許多不被看見的心靈風景，應尊重彼此作為生命共同體，並發掘當代世界中，差異與相似皆真實存在。', '臺南市美術館', '臺南市中西區臺南市中西區忠義路二段 1 號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '臺南市美術館2館', 22.99594458, 120.192874, '--+--', 'https://www.tnam.museum/exhibition/detail/563', '[]') ON DUPLICATE KEY UPDATE `activity_name`='版畫浪潮：2024臺南國際版畫展', `description`='「版畫浪潮-2024臺南國際版畫展」是一場聚焦亞太地區優秀版畫藝術且極具意義的國際藝術盛事，邀請臺灣、日本、韓國、泰國、美國、澳洲、馬來西亞、孟加拉等國的藝術家齊聚臺南，透過版畫這一歷史悠久的藝術形式，進行文化的碰撞與思想的交流。臺灣週邊擁有如黑潮等太平洋上重要的洋流，不僅象徵著自然界中跨越國界的力量，也暗示著文化與藝術的流動。臺灣作為太平洋流流經的重要路線之一，自古便是東西方文化的交匯點，這次展覽正是以此為寓意，將臺灣作為連結亞太藝術的樞紐，展現當代版畫藝術的多樣性與創新性。\r\n\r\n臺南市美術館透過當代藝術詮釋移工議題，邀請來自不同背景的移工及國內外藝術家，以「漂移之味」、「逃逸之方」、「艷陽下南風吹」三個子題，經由生命經驗的觀察、獨白與轉譯、交流與合作等創造過程，揭示移工不為人知的面貌。展覽也引發我們思考，在以移工為主體的多重情境中，始終隱藏著許多不被看見的心靈風景，應尊重彼此作為生命共同體，並發掘當代世界中，差異與相似皆真實存在。', `organizer`='臺南市美術館', `address`='臺南市中西區臺南市中西區忠義路二段 1 號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='臺南市美術館2館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='--+--', `source_url`='https://www.tnam.museum/exhibition/detail/563', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535f126b3240c403d93d1', '頭份親子館外展活動：說故事活動（114年3月-2場次）', '資格：0-6歲親子，三灣鄉親子優先。\r\n有繪本分享、遊戲、手作，歡迎報名。\r\n活動請洽 03-7833430 三灣鄉立圖書館', '苗栗縣政府', '苗栗縣三灣鄉11鄰親民路17-1 號', '2025-03-05 00:00:00', '2025-03-19 00:00:00', '苗栗縣三灣鄉立圖書館', 24.63599405, 120.9525745, '無資料', 'https://www.facebook.com/profile.php?id=100079997630565', '[]') ON DUPLICATE KEY UPDATE `activity_name`='頭份親子館外展活動：說故事活動（114年3月-2場次）', `description`='資格：0-6歲親子，三灣鄉親子優先。\r\n有繪本分享、遊戲、手作，歡迎報名。\r\n活動請洽 03-7833430 三灣鄉立圖書館', `organizer`='苗栗縣政府', `address`='苗栗縣三灣鄉11鄰親民路17-1 號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-19 00:00:00', `location`='苗栗縣三灣鄉立圖書館', `latitude`=24.63599405, `longitude`=120.9525745, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100079997630565', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a535f126b3240c403d93d3', '臺南市東區裕文圖書館- 114年1、2月 主題書展 - 動．吃．噠次', '每月主題書展，提供讀者快速選擇主題相關書籍，並借閱。\r\n你知道你的母語是什麼嗎?那你會說嗎?\r\n是台語、客語還是原住民語呢?\r\n現在有很多人都不太會說自己的母語了，\r\n希望藉由書展的推廣，宣傳保護語言的重要、促進母語傳播、教育等活動，避免世界各地的語言逐漸消失。\r\n裕文圖書館 114年1、2月主題書展 展覽用書可外借', '臺南市東區裕文圖書館', '臺南市東區裕信路237號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '臺南市東區裕文圖書館', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市東區裕文圖書館- 114年1、2月 主題書展 - 動．吃．噠次', `description`='每月主題書展，提供讀者快速選擇主題相關書籍，並借閱。\r\n你知道你的母語是什麼嗎?那你會說嗎?\r\n是台語、客語還是原住民語呢?\r\n現在有很多人都不太會說自己的母語了，\r\n希望藉由書展的推廣，宣傳保護語言的重要、促進母語傳播、教育等活動，避免世界各地的語言逐漸消失。\r\n裕文圖書館 114年1、2月主題書展 展覽用書可外借', `organizer`='臺南市東區裕文圖書館', `address`='臺南市東區裕信路237號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市東區裕文圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
