INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a60e6f8f1583c74c1b3142', '青天白日滿地「虹」- 積吶虹光LEF', '在青天白日的映照下，大地披上了彩虹的盛裝，那是自由的舞動、平等的閃耀與博愛的光芒。\r\n\r\n自由(Liberty)如垂直線那無垠的藍天，無邊無際、無拘無束、無懼風雨，照亮每一個角落，讓所有的心靈都能追尋屬於自己的天地；平等(Equality)如水平線在大地上的光影，無論多遠多近都擁有同樣的光芒，平等共存；博愛(Fraternity)如光譜上的彩虹，彼此交融，帶著無盡的溫暖，將心與心緊緊相連，不論種族、信仰或背景，都能感受到無私的愛。\r\n\r\n青天白日滿地「虹」彷彿施展了魔法，其美麗象徵幸運，希望能將這份幸運留給地球人，展覽以「自由、平等、博愛 (LEF)」為核心理念，倡導中道精神，呼籲人們應攜手合作，共同追求一個更美好、更和平的世界。\r\n\r\nhttps://www.peopo.org/news/798946', '無資料', '雲林縣國立虎尾科技大學藝術中心展覽室', '2025-02-24 00:00:00', '2025-02-24 00:00:00', '青天白日滿地「虹」 - 積吶虹光', 0, 0, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='青天白日滿地「虹」- 積吶虹光LEF', `description`='在青天白日的映照下，大地披上了彩虹的盛裝，那是自由的舞動、平等的閃耀與博愛的光芒。\r\n\r\n自由(Liberty)如垂直線那無垠的藍天，無邊無際、無拘無束、無懼風雨，照亮每一個角落，讓所有的心靈都能追尋屬於自己的天地；平等(Equality)如水平線在大地上的光影，無論多遠多近都擁有同樣的光芒，平等共存；博愛(Fraternity)如光譜上的彩虹，彼此交融，帶著無盡的溫暖，將心與心緊緊相連，不論種族、信仰或背景，都能感受到無私的愛。\r\n\r\n青天白日滿地「虹」彷彿施展了魔法，其美麗象徵幸運，希望能將這份幸運留給地球人，展覽以「自由、平等、博愛 (LEF)」為核心理念，倡導中道精神，呼籲人們應攜手合作，共同追求一個更美好、更和平的世界。\r\n\r\nhttps://www.peopo.org/news/798946', `organizer`='無資料', `address`='雲林縣國立虎尾科技大學藝術中心展覽室', `start_date`='2025-02-24 00:00:00', `end_date`='2025-02-24 00:00:00', `location`='青天白日滿地「虹」 - 積吶虹光', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
