INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65af826b3240c403d93f8', '「呷飯 ( puínn ) 配滷蛋 - 宜蘭米故事」特展', '全臺唯一計畫性推動水稻一年一作，秋冬田地湛(蓄)水休耕的宜蘭縣，多年來友善耕作普及，讓好吃的宜蘭米成為生活日常。\r\n在全球化與都市化趨勢下，宜蘭農村面臨永續議題，但也有許多新的契機，其中，包含綠色飲食成為顯學，從產地到餐桌，除了計算食物旅程的碳排問題，也關注生產履歷、食物安全以及在地的環境敘事。\r\n展覽從土地永續關懷出發，進入宜蘭土壤和水源、人文地理、稻耕成果、農人精神以及米食文化，從多面向的角度，認識宜蘭各具地域特色的「品牌米」以及充滿小農故事的「米品牌」。', '宜蘭縣立蘭陽博物館', '宜蘭縣頭城鎮青雲路三段750號', '2025-01-01 00:00:00', '2025-04-27 00:00:00', '宜蘭縣立蘭陽博物館', 24.90075882, 121.845797, '每人+30', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「呷飯 ( puínn ) 配滷蛋 - 宜蘭米故事」特展', `description`='全臺唯一計畫性推動水稻一年一作，秋冬田地湛(蓄)水休耕的宜蘭縣，多年來友善耕作普及，讓好吃的宜蘭米成為生活日常。\r\n在全球化與都市化趨勢下，宜蘭農村面臨永續議題，但也有許多新的契機，其中，包含綠色飲食成為顯學，從產地到餐桌，除了計算食物旅程的碳排問題，也關注生產履歷、食物安全以及在地的環境敘事。\r\n展覽從土地永續關懷出發，進入宜蘭土壤和水源、人文地理、稻耕成果、農人精神以及米食文化，從多面向的角度，認識宜蘭各具地域特色的「品牌米」以及充滿小農故事的「米品牌」。', `organizer`='宜蘭縣立蘭陽博物館', `address`='宜蘭縣頭城鎮青雲路三段750號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='宜蘭縣立蘭陽博物館', `latitude`=24.90075882, `longitude`=121.845797, `ticket_price`='每人+30', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b0626b3240c403d93fb', '好木成森系列展-坐的二十四式 24 Forms of Seating', '「坐」是現代人在生活中最常使用到的姿勢，用餐、聊天、工作、休息，人們總是坐著處理各種日常瑣事。\r\n本次特展將二十四張來自國內外經典設計的坐具，分為餐椅、休憩椅、搖椅和凳四類。透過親身入座，體會設計與人體需求相對話，並感受工藝之精湛與細膩。\r\n\r\n\r\n\r\n此外，本次特別展出桃園市立大溪木藝生態博物館的六件典藏品，讓大家瞭解當代經典坐具的同時，也回顧傳統漢體及融合時代演變的形式風格表現。\r\n\r\n現在，試著放慢腳步，以身體與心靈好好感受每件作品的材質、線條形態與工藝技法。\r\n\r\n世界上不存在最好的椅子，但一定存在最適合您的椅子。請坐！      ', '桃園市立大溪木藝生態博物館', '桃園市大溪區普濟路33-3號', '2025-01-01 00:00:00', '2025-04-06 00:00:00', '桃園市立大溪木藝生態博物館-武德殿', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='好木成森系列展-坐的二十四式 24 Forms of Seating', `description`='「坐」是現代人在生活中最常使用到的姿勢，用餐、聊天、工作、休息，人們總是坐著處理各種日常瑣事。\r\n本次特展將二十四張來自國內外經典設計的坐具，分為餐椅、休憩椅、搖椅和凳四類。透過親身入座，體會設計與人體需求相對話，並感受工藝之精湛與細膩。\r\n\r\n\r\n\r\n此外，本次特別展出桃園市立大溪木藝生態博物館的六件典藏品，讓大家瞭解當代經典坐具的同時，也回顧傳統漢體及融合時代演變的形式風格表現。\r\n\r\n現在，試著放慢腳步，以身體與心靈好好感受每件作品的材質、線條形態與工藝技法。\r\n\r\n世界上不存在最好的椅子，但一定存在最適合您的椅子。請坐！      ', `organizer`='桃園市立大溪木藝生態博物館', `address`='桃園市大溪區普濟路33-3號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='桃園市立大溪木藝生態博物館-武德殿', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b0c26b3240c403d93fd', '桃園市土地公文化館常設展-202 當伯公遇見土地公', '桃園市是一個多元族群融合的城市，202展間的常設展以「當伯公（客語bag gungˋ）遇見土地公（閩南語thóo-tī-kong）」為主題，作為參觀者前往三樓展場深入了解土地公文化前的一個導讀。\r\n展覽呈現多元文化特色，設計了許多互動裝置。參觀者可以用翻翻牌來瞭解閩客土地公信仰習俗與稱謂之不同、用華容道滑塊遊戲來閱讀土地公小百科、掃掃看！就可以體驗AR供桌擴增實境、360度的特色土地公投影欣賞讓人目不轉睛，現場還可以跟超大超可愛的好運虎爺互動自拍。這些極具巧思的安排，增加了展覽的趣味性，讓參觀者以最輕鬆的方式更深入地了解土地公文化。', '財團法人桃園市文化基金會', '桃園市桃園區三民路一段100號', '2025-01-02 00:00:00', '2025-12-31 00:00:00', '桃園市土地公文化館', 24.998189, 121.321246, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園市土地公文化館常設展-202 當伯公遇見土地公', `description`='桃園市是一個多元族群融合的城市，202展間的常設展以「當伯公（客語bag gungˋ）遇見土地公（閩南語thóo-tī-kong）」為主題，作為參觀者前往三樓展場深入了解土地公文化前的一個導讀。\r\n展覽呈現多元文化特色，設計了許多互動裝置。參觀者可以用翻翻牌來瞭解閩客土地公信仰習俗與稱謂之不同、用華容道滑塊遊戲來閱讀土地公小百科、掃掃看！就可以體驗AR供桌擴增實境、360度的特色土地公投影欣賞讓人目不轉睛，現場還可以跟超大超可愛的好運虎爺互動自拍。這些極具巧思的安排，增加了展覽的趣味性，讓參觀者以最輕鬆的方式更深入地了解土地公文化。', `organizer`='財團法人桃園市文化基金會', `address`='桃園市桃園區三民路一段100號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='桃園市土地公文化館', `latitude`=24.998189, `longitude`=121.321246, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b1126b3240c403d93ff', '新化區圖書館:114年2月份-主題書展-旅遊文化', '新化區圖書館:114年2月份-主題書展-旅遊文化\r\n', '臺南市新化區圖書館', '臺南市新化區中山路132號', '2025-02-04 00:00:00', '2025-02-27 00:00:00', '臺南市新化區圖書館', 23.03394545, 120.3357964, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新化區圖書館:114年2月份-主題書展-旅遊文化', `description`='新化區圖書館:114年2月份-主題書展-旅遊文化\r\n', `organizer`='臺南市新化區圖書館', `address`='臺南市新化區中山路132號', `start_date`='2025-02-04 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺南市新化區圖書館', `latitude`=23.03394545, `longitude`=120.3357964, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b1626b3240c403d9400', '⟪Pathfinder • 先行者⟫ 愛上藝廊2025新年典藏展｜iart gallery愛上藝廊', '【 展覽預告 ⎮ Pathfinder • 先行者 】\r\n-\r\n在2025年的伊始，愛上藝廊將呈獻一場別具啟發性的當代藝術典藏展《Pathfinder • 先行者》。策展源起自送子鳥診所創辦人——賴興華醫師的企業經營哲學——「兩路哲學」：\r\n.\r\n「我們只走兩條路，一條是困難的路，另一條是別人不敢走的路。」\r\n.\r\n本次展覽以全新視角策劃，集結多位國際當代藝術家之精選作品，涵蓋繪畫、漆藝、版畫、數位影像等多元媒材，反映藝術家在不同時代與社會文化背景下，如何突破傳統邊界、打破既有思維，創造出獨樹一幟的藝術語言。其中有善於洞察並以超現實手法表現人類情感的舟越桂；揉合東西方哲學與精神價值的趙葆康；以透鏡的錯視與動態浮動感營造畫面張力的Jeff Robb，每件作品都分別表述藝術家們在探索未知的過程中，勇於挑戰「困難」與「他人不敢」的創作心路，進而以「先行者」之姿引領新的風格或潮流。\r\n.\r\n《Pathfinder • 先行者》企圖展現藝術的多元樣貌，不僅止於呈現美感表象，更重於啟發觀者思考，引領大家勇於踏上未知的征途。這場展覽將成為藝術家與觀眾對話的跨時空橋樑，不論是挑戰自我、尋覓真相、探求真理，還是開創未來，我們都期待能以此激發並鼓勵每個人去尋找屬於自己的道路，並勇敢成為自己的「先行者」。', '愛上藝廊', '新竹市東區忠孝路80號1樓', '2025-01-13 00:00:00', '2025-02-28 00:00:00', 'iart Gallery 愛上藝廊', 24.79028174, 120.9927505, '無資料', 'https://www.facebook.com/gallery.iart/posts/pfbid0Gg1qGWjof6r5WMiq5bfRHFec43h3DsK3ki8PgiYq2fcpw6AZaa', '[]') ON DUPLICATE KEY UPDATE `activity_name`='⟪Pathfinder • 先行者⟫ 愛上藝廊2025新年典藏展｜iart gallery愛上藝廊', `description`='【 展覽預告 ⎮ Pathfinder • 先行者 】\r\n-\r\n在2025年的伊始，愛上藝廊將呈獻一場別具啟發性的當代藝術典藏展《Pathfinder • 先行者》。策展源起自送子鳥診所創辦人——賴興華醫師的企業經營哲學——「兩路哲學」：\r\n.\r\n「我們只走兩條路，一條是困難的路，另一條是別人不敢走的路。」\r\n.\r\n本次展覽以全新視角策劃，集結多位國際當代藝術家之精選作品，涵蓋繪畫、漆藝、版畫、數位影像等多元媒材，反映藝術家在不同時代與社會文化背景下，如何突破傳統邊界、打破既有思維，創造出獨樹一幟的藝術語言。其中有善於洞察並以超現實手法表現人類情感的舟越桂；揉合東西方哲學與精神價值的趙葆康；以透鏡的錯視與動態浮動感營造畫面張力的Jeff Robb，每件作品都分別表述藝術家們在探索未知的過程中，勇於挑戰「困難」與「他人不敢」的創作心路，進而以「先行者」之姿引領新的風格或潮流。\r\n.\r\n《Pathfinder • 先行者》企圖展現藝術的多元樣貌，不僅止於呈現美感表象，更重於啟發觀者思考，引領大家勇於踏上未知的征途。這場展覽將成為藝術家與觀眾對話的跨時空橋樑，不論是挑戰自我、尋覓真相、探求真理，還是開創未來，我們都期待能以此激發並鼓勵每個人去尋找屬於自己的道路，並勇敢成為自己的「先行者」。', `organizer`='愛上藝廊', `address`='新竹市東區忠孝路80號1樓', `start_date`='2025-01-13 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='iart Gallery 愛上藝廊', `latitude`=24.79028174, `longitude`=120.9927505, `ticket_price`='無資料', `source_url`='https://www.facebook.com/gallery.iart/posts/pfbid0Gg1qGWjof6r5WMiq5bfRHFec43h3DsK3ki8PgiYq2fcpw6AZaa', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b1926b3240c403d9413', '2025台灣燈會-太武特色場域裝置燈飾展', '太武新村眷村文化園區以藝術文創聚落為主軸，為營造具自然人文特色之環境場域，期待透過藝術打造太武新村成為極具藝術特色之藝術園區。\r\n以於面慈光一街的藝術裝置「新芽」且結合眷舍建物本體以燈線勾勒出完整的輪廓意象。燈飾的佈置也將融入與社區共創的彩繪燈籠，為場地添增喜慶氣氛。\r\n燈飾的效果從園區內向外散發，除了在夜間可以打亮此面園區內的眷舍，在園區外人們行經時也可感受到藝術與歷史建物融合成為一體的氛圍。', '桃園市政府文化局', '桃園市大溪區太武新村22號 (慈光街與慈光一街轉角處)', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '太武新村眷村文化園區', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會-太武特色場域裝置燈飾展', `description`='太武新村眷村文化園區以藝術文創聚落為主軸，為營造具自然人文特色之環境場域，期待透過藝術打造太武新村成為極具藝術特色之藝術園區。\r\n以於面慈光一街的藝術裝置「新芽」且結合眷舍建物本體以燈線勾勒出完整的輪廓意象。燈飾的佈置也將融入與社區共創的彩繪燈籠，為場地添增喜慶氣氛。\r\n燈飾的效果從園區內向外散發，除了在夜間可以打亮此面園區內的眷舍，在園區外人們行經時也可感受到藝術與歷史建物融合成為一體的氛圍。', `organizer`='桃園市政府文化局', `address`='桃園市大溪區太武新村22號 (慈光街與慈光一街轉角處)', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='太武新村眷村文化園區', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b1a26b3240c403d9417', '無資料', '《善良的歹人》\r\n※原訂2024年12月7日（六）14:30、12月8日（日）14:30於戲劇院演出之台語流行音樂劇《第三者》節目，因故延期至2025年2月22日（六）14:30、2月23日（日）14:30於原場地演出，節目名稱異動為《善良的歹人》，造成不便，敬請見諒。\r\n\r\n※因節目異動，已購票觀眾可持原票券入場，或辦理全額退票，請詳異動公告。\r\n\r\n \r\n\r\n《善良的歹人》是根據金曲歌王蘇明淵創作的台語歌曲改編的音樂劇。\r\n\r\n故事描述帝皇建設總經理鍾志生與妻子周詩鵑，在人前是恩愛夫妻，背地裡卻關係惡劣，導致他們的孩子身心受創，需要求助身心科醫生。沒想到志生卻與身心科醫生劉巧馨有了關係，巧馨明知自己是破壞別人家庭的第三者，卻還是深陷其中。 詩鵑在得知志生外遇之後，下定決心要離開志生，找上自己的初戀情人吳瑞騰幫她打離婚官司。吳瑞騰是一位知名的人權律師，常常幫助環保團體，此時他正在處理一樁殺警案。環保團體成員李維成在一次抗議行動中，捲入一樁殺警案，整個案情陷入膠著，令瑞騰十分苦惱。\r\n\r\n瑞騰答應詩鵑的離婚官司，來找巧馨談判，遇見巧馨的病人徐義凱。義凱心裡暗藏一個不可告人的秘密，這個祕密居然跟殺警案有關。\r\n\r\n所有的線索都匯集在一起，其中甚至牽連一樁進行中的龐大土地開發案。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n藝術總監｜郎祖筠 \r\n\r\n音樂總監｜蘇明淵 \r\n\r\n製 作 人｜郎祖明、吳怡毅 \r\n\r\n導演、編劇｜陳世杰 \r\n\r\n副 導 演｜趙偉丞 \r\n\r\n作曲｜蘇明淵 \r\n\r\n燈光設計｜藍俊鵬 \r\n\r\n舞台設計｜傅寯 \r\n\r\n服裝造型設計｜林恒正 \r\n\r\n編曲配樂｜聶琳 \r\n\r\n影像設計｜王奕盛 \r\n\r\n編 舞｜陳映慈\r\n\r\n歌唱指導｜李昀陵 \r\n\r\n音樂執行製作｜謝東翰 \r\n\r\n主要演員｜郎祖筠、王柏森、王耿豪、楊小黎、黃浩詠 ', '春河劇團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='《善良的歹人》\r\n※原訂2024年12月7日（六）14:30、12月8日（日）14:30於戲劇院演出之台語流行音樂劇《第三者》節目，因故延期至2025年2月22日（六）14:30、2月23日（日）14:30於原場地演出，節目名稱異動為《善良的歹人》，造成不便，敬請見諒。\r\n\r\n※因節目異動，已購票觀眾可持原票券入場，或辦理全額退票，請詳異動公告。\r\n\r\n \r\n\r\n《善良的歹人》是根據金曲歌王蘇明淵創作的台語歌曲改編的音樂劇。\r\n\r\n故事描述帝皇建設總經理鍾志生與妻子周詩鵑，在人前是恩愛夫妻，背地裡卻關係惡劣，導致他們的孩子身心受創，需要求助身心科醫生。沒想到志生卻與身心科醫生劉巧馨有了關係，巧馨明知自己是破壞別人家庭的第三者，卻還是深陷其中。 詩鵑在得知志生外遇之後，下定決心要離開志生，找上自己的初戀情人吳瑞騰幫她打離婚官司。吳瑞騰是一位知名的人權律師，常常幫助環保團體，此時他正在處理一樁殺警案。環保團體成員李維成在一次抗議行動中，捲入一樁殺警案，整個案情陷入膠著，令瑞騰十分苦惱。\r\n\r\n瑞騰答應詩鵑的離婚官司，來找巧馨談判，遇見巧馨的病人徐義凱。義凱心裡暗藏一個不可告人的秘密，這個祕密居然跟殺警案有關。\r\n\r\n所有的線索都匯集在一起，其中甚至牽連一樁進行中的龐大土地開發案。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n藝術總監｜郎祖筠 \r\n\r\n音樂總監｜蘇明淵 \r\n\r\n製 作 人｜郎祖明、吳怡毅 \r\n\r\n導演、編劇｜陳世杰 \r\n\r\n副 導 演｜趙偉丞 \r\n\r\n作曲｜蘇明淵 \r\n\r\n燈光設計｜藍俊鵬 \r\n\r\n舞台設計｜傅寯 \r\n\r\n服裝造型設計｜林恒正 \r\n\r\n編曲配樂｜聶琳 \r\n\r\n影像設計｜王奕盛 \r\n\r\n編 舞｜陳映慈\r\n\r\n歌唱指導｜李昀陵 \r\n\r\n音樂執行製作｜謝東翰 \r\n\r\n主要演員｜郎祖筠、王柏森、王耿豪、楊小黎、黃浩詠 ', `organizer`='春河劇團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b1a26b3240c403d9419', '無資料', '【武營來跳舞】瘋迷24柴可夫斯基特別場《Dancing in the midnight》\r\n柴可夫斯基因對孩童的喜愛、以及故事題材的激發，加上精湛的管弦樂法和旋律天賦，所寫的三大芭蕾舞劇無一不成為扭轉後人對芭蕾舞劇配樂觀點的重量級作品，也成畢生的代表作。除了芭蕾舞劇之外，他令人心醉的《C大調弦樂小夜曲》更讓新古典芭蕾之父喬治巴蘭欽畫下新世紀的起點。\r\n\r\n今夜我們的芭蕾要從古典跳到現代～\r\n\r\n \r\n\r\n  場次簡介  \r\n\r\n2/22(六)23:45 《柴可夫斯基的三大芭蕾課》\r\n\r\n因兩人對芭蕾舞的熱情，柴可夫斯基與法裔俄羅斯編舞家佩提巴（Marius Petipa）致力於創作三大芭蕾舞劇《天鵝湖》、《睡美人》及《胡桃鉗》，今晚我們分別用身體來認識三大芭蕾舞劇中芭蕾和音樂的重要三種節奏與組合：慢板「Adagio」、 快板「allegro」、快速舞步「coda」。\r\n\r\n \r\n\r\n2/23(日)01:30 《柴可夫斯基的芭蕾晚課-小夜曲》\r\n\r\n新古典芭蕾之父-喬治巴蘭欽因對柴可夫斯基的喜愛而編創《小夜曲》。去除故事、情節、華麗的佈景和服裝，音符與舞步的關係充滿情緒又感情複雜。也是巴蘭欽到了美國新創他的芭蕾帝國爲學校學生編的第一支舞。讓我們今夜一起感受這浪漫又純粹的芭蕾旅程。\r\n\r\n \r\n\r\n★ 誰來跳舞：\r\n\r\n葉名樺\r\n\r\n參加對象：歡迎喜歡藝術活動的朋友，一起來跳舞!\r\n\r\n報名方式：報名參加，免費入場(單場人數限量50名，額滿為止)\r\n\r\n報名網址：報名請點我\r\n\r\n本場活動僅開放《瘋迷24柴可夫斯基》購票民眾參與\r\n\r\n活動地點：樹冠大廳東側露台\r\n\r\n \r\n\r\n  舞者簡介  \r\n\r\n葉名樺\r\n\r\n臺灣編舞家及舞者，1983年出生於高雄，畢業於臺北藝術大學舞蹈學院。創作以身體、感官詮釋來思考時間與空間，並以多媒材、跨領域的演出實踐回應敘事與事件。2019-2020年受邀衛武營國家藝術文化中心「四國駐地交流計畫」發表實驗型公共場域創作。2020年受臺北市立美術館委託製作《牆後的院宅》，並獲得第19屆台新藝術獎年度大獎肯定。2022年衛武營「臺灣舞蹈平台」創作開幕演出《跳芭蕾》。2023-2024衛武營《音樂芭蕾劇場：遇見胡桃鉗的女孩》。 \r\n\r\n \r\n\r\n  節目資訊  \r\n\r\n2/22(六)17:00-2/23(日)17:00\r\n\r\n►《瘋迷24柴可夫斯基》', '國家表演藝術中心衛武營國家藝術文化中心', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='【武營來跳舞】瘋迷24柴可夫斯基特別場《Dancing in the midnight》\r\n柴可夫斯基因對孩童的喜愛、以及故事題材的激發，加上精湛的管弦樂法和旋律天賦，所寫的三大芭蕾舞劇無一不成為扭轉後人對芭蕾舞劇配樂觀點的重量級作品，也成畢生的代表作。除了芭蕾舞劇之外，他令人心醉的《C大調弦樂小夜曲》更讓新古典芭蕾之父喬治巴蘭欽畫下新世紀的起點。\r\n\r\n今夜我們的芭蕾要從古典跳到現代～\r\n\r\n \r\n\r\n  場次簡介  \r\n\r\n2/22(六)23:45 《柴可夫斯基的三大芭蕾課》\r\n\r\n因兩人對芭蕾舞的熱情，柴可夫斯基與法裔俄羅斯編舞家佩提巴（Marius Petipa）致力於創作三大芭蕾舞劇《天鵝湖》、《睡美人》及《胡桃鉗》，今晚我們分別用身體來認識三大芭蕾舞劇中芭蕾和音樂的重要三種節奏與組合：慢板「Adagio」、 快板「allegro」、快速舞步「coda」。\r\n\r\n \r\n\r\n2/23(日)01:30 《柴可夫斯基的芭蕾晚課-小夜曲》\r\n\r\n新古典芭蕾之父-喬治巴蘭欽因對柴可夫斯基的喜愛而編創《小夜曲》。去除故事、情節、華麗的佈景和服裝，音符與舞步的關係充滿情緒又感情複雜。也是巴蘭欽到了美國新創他的芭蕾帝國爲學校學生編的第一支舞。讓我們今夜一起感受這浪漫又純粹的芭蕾旅程。\r\n\r\n \r\n\r\n★ 誰來跳舞：\r\n\r\n葉名樺\r\n\r\n參加對象：歡迎喜歡藝術活動的朋友，一起來跳舞!\r\n\r\n報名方式：報名參加，免費入場(單場人數限量50名，額滿為止)\r\n\r\n報名網址：報名請點我\r\n\r\n本場活動僅開放《瘋迷24柴可夫斯基》購票民眾參與\r\n\r\n活動地點：樹冠大廳東側露台\r\n\r\n \r\n\r\n  舞者簡介  \r\n\r\n葉名樺\r\n\r\n臺灣編舞家及舞者，1983年出生於高雄，畢業於臺北藝術大學舞蹈學院。創作以身體、感官詮釋來思考時間與空間，並以多媒材、跨領域的演出實踐回應敘事與事件。2019-2020年受邀衛武營國家藝術文化中心「四國駐地交流計畫」發表實驗型公共場域創作。2020年受臺北市立美術館委託製作《牆後的院宅》，並獲得第19屆台新藝術獎年度大獎肯定。2022年衛武營「臺灣舞蹈平台」創作開幕演出《跳芭蕾》。2023-2024衛武營《音樂芭蕾劇場：遇見胡桃鉗的女孩》。 \r\n\r\n \r\n\r\n  節目資訊  \r\n\r\n2/22(六)17:00-2/23(日)17:00\r\n\r\n►《瘋迷24柴可夫斯基》', `organizer`='國家表演藝術中心衛武營國家藝術文化中心', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b1a26b3240c403d941a', '【衛武營小時光】卡米地喜劇俱樂部 《歐耶 x 壯壯 喜劇秀》', '【衛武營小時光】卡米地喜劇俱樂部 《歐耶 x 壯壯 喜劇秀》\r\n《歐耶 x 壯壯  喜劇秀》\r\n\r\n歐耶 x  壯壯  要來高雄了\r\n\r\n每場演出都是現場限定，別的地方聽不到\r\n\r\n滿滿的60分鐘歡笑？只能講60分鐘嗎？\r\n\r\n請高雄的朋友多多指教 \r\n\r\n \r\n\r\n#漫才是什麼？\r\n\r\n漫才源自於日本，是一種類似相聲的喜劇形式，通常由兩個人搭檔，一人擔任「裝傻」；\r\n\r\n另一人則負責「吐槽」。兩人藉由一連串貼近生活的對話與互動，製造出無厘頭的笑料，是非常適合放鬆且娛樂性極高的一種表演形式。\r\n\r\n \r\n\r\n  演出者  \r\n\r\n歐耶老師、壯壯', '國家表演藝術中心衛武營國家藝術文化中心', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-02-26 00:00:00', '2025-02-26 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+300;--+600', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【衛武營小時光】卡米地喜劇俱樂部 《歐耶 x 壯壯 喜劇秀》', `description`='【衛武營小時光】卡米地喜劇俱樂部 《歐耶 x 壯壯 喜劇秀》\r\n《歐耶 x 壯壯  喜劇秀》\r\n\r\n歐耶 x  壯壯  要來高雄了\r\n\r\n每場演出都是現場限定，別的地方聽不到\r\n\r\n滿滿的60分鐘歡笑？只能講60分鐘嗎？\r\n\r\n請高雄的朋友多多指教 \r\n\r\n \r\n\r\n#漫才是什麼？\r\n\r\n漫才源自於日本，是一種類似相聲的喜劇形式，通常由兩個人搭檔，一人擔任「裝傻」；\r\n\r\n另一人則負責「吐槽」。兩人藉由一連串貼近生活的對話與互動，製造出無厘頭的笑料，是非常適合放鬆且娛樂性極高的一種表演形式。\r\n\r\n \r\n\r\n  演出者  \r\n\r\n歐耶老師、壯壯', `organizer`='國家表演藝術中心衛武營國家藝術文化中心', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-02-26 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+300;--+600', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b1a26b3240c403d941c', '2025《遇見大師－蘇顯達》', '2025《遇見大師－蘇顯達》\r\n當享譽國際的小提琴大師與兩位新生代音樂家一同以三重奏的形式踏上前往十九世紀歐洲的旅程，一路上究竟會擦出什麼樣的藝術火花呢？本場音樂會特別邀請臺灣最重量級小提琴家-蘇顯達教授，攜手新生代鋼琴家王一幸及大提琴家謝孟軒，一同演繹兩首十九世紀德國的經典代表作：《貝多芬降B大調鋼琴三重奏，作品97》以及《布拉姆斯B大調鋼琴三重奏，作品8》，透過彼此手中的樂器相互闡述各自對於藝術的堅持與理念，一同帶給聽眾們一場跨越世代的音樂對話。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n貝多芬: 降B大調鋼琴三重奏，作品97 \r\n\r\n布拉姆斯: B大調鋼琴三重奏，作品8\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n小提琴家｜蘇顯達\r\n\r\n大提琴家｜謝孟軒\r\n\r\n鋼琴家｜王一幸', '台中室內樂集', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+300;--+500;--+800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025《遇見大師－蘇顯達》', `description`='2025《遇見大師－蘇顯達》\r\n當享譽國際的小提琴大師與兩位新生代音樂家一同以三重奏的形式踏上前往十九世紀歐洲的旅程，一路上究竟會擦出什麼樣的藝術火花呢？本場音樂會特別邀請臺灣最重量級小提琴家-蘇顯達教授，攜手新生代鋼琴家王一幸及大提琴家謝孟軒，一同演繹兩首十九世紀德國的經典代表作：《貝多芬降B大調鋼琴三重奏，作品97》以及《布拉姆斯B大調鋼琴三重奏，作品8》，透過彼此手中的樂器相互闡述各自對於藝術的堅持與理念，一同帶給聽眾們一場跨越世代的音樂對話。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n貝多芬: 降B大調鋼琴三重奏，作品97 \r\n\r\n布拉姆斯: B大調鋼琴三重奏，作品8\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n小提琴家｜蘇顯達\r\n\r\n大提琴家｜謝孟軒\r\n\r\n鋼琴家｜王一幸', `organizer`='台中室內樂集', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+300;--+500;--+800', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2626b3240c403d941f', '無資料', '2/9(日) annie姊姊 一百萬個親親\r\n2/16(日) 阿湯老師 躲貓貓\r\n2/22(六) 簡單老師 張開大嘴呱呱呱\r\n2/23(日) 鈴鐺老師 從頭動到腳', '臺南市歸仁區圖書館', '臺南市歸仁區大德路127號', '臺南市歸仁區圖書館', 22.94679469, 120.2930627, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='2/9(日) annie姊姊 一百萬個親親\r\n2/16(日) 阿湯老師 躲貓貓\r\n2/22(六) 簡單老師 張開大嘴呱呱呱\r\n2/23(日) 鈴鐺老師 從頭動到腳', `organizer`='臺南市歸仁區圖書館', `address`='臺南市歸仁區大德路127號', `location`='臺南市歸仁區圖書館', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2726b3240c403d9423', '六甲區圖書館-本土語言主題書展', '本土語言主題書展\r\n\r\n展出時間：114.01.21~02.27\r\n\r\n希望透過本書展活動，提升讀者對母語的認同感，也能帶動周遭環境對語言文化的重視，共同營造一個尊重多元語言的社會。\r\n\r\n主題書展小活動：\r\n1.按讚本篇貼文。\r\n2.在本篇貼文下方「上傳您最喜歡展覽中的哪一本【本土語言】書籍」照片。\r\n3.出示手機畫面即可向館員索取小禮物(每個FB帳號限領一次，數量有限，送完為止)。', '臺南市六甲區公所', '臺南市六甲區中山路202號', '2025-01-21 00:00:00', '2025-02-27 00:00:00', '臺南市六甲區公所/六甲區圖書館', 23.2272672, 120.3800259, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='六甲區圖書館-本土語言主題書展', `description`='本土語言主題書展\r\n\r\n展出時間：114.01.21~02.27\r\n\r\n希望透過本書展活動，提升讀者對母語的認同感，也能帶動周遭環境對語言文化的重視，共同營造一個尊重多元語言的社會。\r\n\r\n主題書展小活動：\r\n1.按讚本篇貼文。\r\n2.在本篇貼文下方「上傳您最喜歡展覽中的哪一本【本土語言】書籍」照片。\r\n3.出示手機畫面即可向館員索取小禮物(每個FB帳號限領一次，數量有限，送完為止)。', `organizer`='臺南市六甲區公所', `address`='臺南市六甲區中山路202號', `start_date`='2025-01-21 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺南市六甲區公所/六甲區圖書館', `latitude`=23.2272672, `longitude`=120.3800259, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2826b3240c403d9425', '無資料', '透過故事繪本「生氣王子」帶領孩子自由創作出專屬自己的作品，特別邀請吳瑟絹老師，一同推出「山海驛町小基地」系列課程，以每月一堂課的方式，透過課程學習激發出孩子們更多創造潛能及想像力。', '高雄市立圖書館總館', '高雄市鼓山區延平街87-13號', '高雄市立圖書館南鼓山分館', 22.623302, 120.2730466, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='透過故事繪本「生氣王子」帶領孩子自由創作出專屬自己的作品，特別邀請吳瑟絹老師，一同推出「山海驛町小基地」系列課程，以每月一堂課的方式，透過課程學習激發出孩子們更多創造潛能及想像力。', `organizer`='高雄市立圖書館總館', `address`='高雄市鼓山區延平街87-13號', `location`='高雄市立圖書館南鼓山分館', `latitude`=22.623302, `longitude`=120.2730466, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2826b3240c403d9428', '無資料', '為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動\r\n志工，至各分館說故事。【本活動免費參加，自由入場(禁止攜帶飲料、食物)】', '高雄市立圖書館總館', '高雄市鼓山區延平街87-13號', '高雄市立圖書館南鼓山分館', 22.623302, 120.2730466, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動\r\n志工，至各分館說故事。【本活動免費參加，自由入場(禁止攜帶飲料、食物)】', `organizer`='高雄市立圖書館總館', `address`='高雄市鼓山區延平街87-13號', `location`='高雄市立圖書館南鼓山分館', `latitude`=22.623302, `longitude`=120.2730466, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2826b3240c403d942a', '無資料', '【2025世界母語日】鬧鬧熱熱•聽台語\r\n \r\n入來美術館，聽台語，唱台語，講台語\r\n \r\n1947 年，英國撤出印度半島後，巴基斯坦宣布獨立，但新政府獨尊烏爾都語，此舉惹火了講孟加拉語的人民。幾年後一群學生走上街頭，發表抗議宣言，不幸遭政府派軍警射殺！抗議事件越演越烈，最後政府屈服，將孟加拉語同列為官方語言。這次行動，史上稱為「孟加拉語言運動」。\r\n \r\n1999年，聯合國教科文組織提出訂定世界母語日（又稱國際母語日，International Mother Language Day）需求。隔年定案2月21日。為何聯合國教科文組織提出世界母語日？據統計，這個世界每兩個星期可能就有1種語言瀕臨危險或有消失可能性，到 21 世紀末，全球目前的7000 多種語言（亦有6000-8000種估算）可能將剩下3000多種。\r\n \r\n在台灣，許多原住民語言已消失，如馬賽（巴賽）語、凱達格蘭語等。台語、客語看似很多人會講，但大多在家或私下聊天，人們在教育現場或職場並不常使用。由此，向世界宣傳保護語言、促進母語的傳播，成為刻不容緩的文化行動。\r\n \r\n主辦單位：高雄市立美術館\r\n\r\n★高美館│唱台語歌 \r\n● 2/23（日）孩子王\r\n15:00-15:45  一樓雕塑大廳（14:30開始入場）\r\n\r\n「孩子王」主唱阿達佮鼓手強尼兩个人，一面唱歌，一面講古，和逐家分享創作甘苦談。', '高雄市立美術館', '高雄市鼓山區6鄰美術館路80號', '高雄市立美術館', 22.6566968, 120.2865511, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='【2025世界母語日】鬧鬧熱熱•聽台語\r\n \r\n入來美術館，聽台語，唱台語，講台語\r\n \r\n1947 年，英國撤出印度半島後，巴基斯坦宣布獨立，但新政府獨尊烏爾都語，此舉惹火了講孟加拉語的人民。幾年後一群學生走上街頭，發表抗議宣言，不幸遭政府派軍警射殺！抗議事件越演越烈，最後政府屈服，將孟加拉語同列為官方語言。這次行動，史上稱為「孟加拉語言運動」。\r\n \r\n1999年，聯合國教科文組織提出訂定世界母語日（又稱國際母語日，International Mother Language Day）需求。隔年定案2月21日。為何聯合國教科文組織提出世界母語日？據統計，這個世界每兩個星期可能就有1種語言瀕臨危險或有消失可能性，到 21 世紀末，全球目前的7000 多種語言（亦有6000-8000種估算）可能將剩下3000多種。\r\n \r\n在台灣，許多原住民語言已消失，如馬賽（巴賽）語、凱達格蘭語等。台語、客語看似很多人會講，但大多在家或私下聊天，人們在教育現場或職場並不常使用。由此，向世界宣傳保護語言、促進母語的傳播，成為刻不容緩的文化行動。\r\n \r\n主辦單位：高雄市立美術館\r\n\r\n★高美館│唱台語歌 \r\n● 2/23（日）孩子王\r\n15:00-15:45  一樓雕塑大廳（14:30開始入場）\r\n\r\n「孩子王」主唱阿達佮鼓手強尼兩个人，一面唱歌，一面講古，和逐家分享創作甘苦談。', `organizer`='高雄市立美術館', `address`='高雄市鼓山區6鄰美術館路80號', `location`='高雄市立美術館', `latitude`=22.6566968, `longitude`=120.2865511, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2826b3240c403d942b', '喜閱網 主題書展', '高雄市政府教育局於102年開始發展與建置喜閱網迄今已進入第13年，長期投入評選國小1到6年級適合學生閱讀的書籍及閱讀理解命題，持續投入人力及物力資源，進行相關網站管理及命審題教師人力資源培訓工作，目前已累積660本書的閱讀理解檢測資源，並持續以每年60本書增加當中，為國內目前最有價值之線上閱讀教學資源之一，高雄市每年使用網站的學童人數高達6萬多人，約佔本市所有學童比例的70%，累計通過認證的書籍數量達100萬冊，已成為目前高雄市推動閱讀的重要資源。\r\n　　喜閱網雖然是課後學習的輔助網站，但書籍的選擇與命題經過嚴謹的歷程，網站中為孩子們提供的推薦書單，共分為12個等級，學校老師或家長配合識字量測驗的結果，提供符合孩子程度的書籍。家長、老師或孩子可以循序漸進選擇適合的書籍來閱讀，網站也保留了學童的完整學習歷程，學童能了解自己的學習狀況，通過閱讀測驗，可不斷累積點數，若沒有闖關成功，也能在重新閱讀後再次挑戰。\r\n我們特別把此類書籍專區展示，增加家長與學童能專區挑選書籍的便利性!', '高雄市立圖書館總館', '高雄市鼓山區延平街87-13號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '高雄市立圖書館南鼓山分館', 22.623302, 120.2730466, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='喜閱網 主題書展', `description`='高雄市政府教育局於102年開始發展與建置喜閱網迄今已進入第13年，長期投入評選國小1到6年級適合學生閱讀的書籍及閱讀理解命題，持續投入人力及物力資源，進行相關網站管理及命審題教師人力資源培訓工作，目前已累積660本書的閱讀理解檢測資源，並持續以每年60本書增加當中，為國內目前最有價值之線上閱讀教學資源之一，高雄市每年使用網站的學童人數高達6萬多人，約佔本市所有學童比例的70%，累計通過認證的書籍數量達100萬冊，已成為目前高雄市推動閱讀的重要資源。\r\n　　喜閱網雖然是課後學習的輔助網站，但書籍的選擇與命題經過嚴謹的歷程，網站中為孩子們提供的推薦書單，共分為12個等級，學校老師或家長配合識字量測驗的結果，提供符合孩子程度的書籍。家長、老師或孩子可以循序漸進選擇適合的書籍來閱讀，網站也保留了學童的完整學習歷程，學童能了解自己的學習狀況，通過閱讀測驗，可不斷累積點數，若沒有闖關成功，也能在重新閱讀後再次挑戰。\r\n我們特別把此類書籍專區展示，增加家長與學童能專區挑選書籍的便利性!', `organizer`='高雄市立圖書館總館', `address`='高雄市鼓山區延平街87-13號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='高雄市立圖書館南鼓山分館', `latitude`=22.623302, `longitude`=120.2730466, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2826b3240c403d942c', '高雄市立圖書館大樹三館114年2月主題書展', '1.SDGs 10(減少國內及國家間不平等)主題書展-因應聯合國2015年宣佈「2030永續發展目標」中第十項目標，減少國家内部和國家之間的不平等，展出多元文化、移工、食物銀行、志工、宗教信仰、交朋友、尊重他人等相關書籍，供民眾翻閱。展期：(114/01/02~114/03/30)\r\n2.生機盎然:在書海中探索食農的樂趣-透過《生機盎然：在書海中探索食農的樂趣》等相關書籍，供民眾翻閱。，讓讀者將不僅能夠獲得食農知識，也能在實踐中與自然建立更深的聯絡。希望能激發更多人對於食物來源的重視以及保護自然的行動。展期：(114/01/02~114/02/27)', '高雄市立圖書館總館', '高雄市大樹區溪埔路77號3樓', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '高雄市立圖書館大樹三館', 22.71100364, 120.425407, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市立圖書館大樹三館114年2月主題書展', `description`='1.SDGs 10(減少國內及國家間不平等)主題書展-因應聯合國2015年宣佈「2030永續發展目標」中第十項目標，減少國家内部和國家之間的不平等，展出多元文化、移工、食物銀行、志工、宗教信仰、交朋友、尊重他人等相關書籍，供民眾翻閱。展期：(114/01/02~114/03/30)\r\n2.生機盎然:在書海中探索食農的樂趣-透過《生機盎然：在書海中探索食農的樂趣》等相關書籍，供民眾翻閱。，讓讀者將不僅能夠獲得食農知識，也能在實踐中與自然建立更深的聯絡。希望能激發更多人對於食物來源的重視以及保護自然的行動。展期：(114/01/02~114/02/27)', `organizer`='高雄市立圖書館總館', `address`='高雄市大樹區溪埔路77號3樓', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='高雄市立圖書館大樹三館', `latitude`=22.71100364, `longitude`=120.425407, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2926b3240c403d942d', '無資料', '竹子是南投重要物產，竹業文化歷史悠久，現代的竹文化發展也與時俱進，傳統產業透過轉型後成為兼具觀光休閒、生態保育、地方產業、教育傳承的南投特色文化。此次「2025南投竹夢森活節」共有4天活動，活動以當地的竹美食、竹文化與竹生活為基底，揉合創意推出四天主題活動，體驗竹的百變風貌，DIY、茶席及導覽等相關體驗活動自即日起開放報名。\r\n南投「竹夢森活節」即將登場！走進竹林深處，感受竹藝、茶席與自然交織的靜謐時光，讓身心沉浸在綠意與茶香之中。這不僅是一場活動，更是一場回歸自然、品味生活的美好體驗。\r\n活動亮點\r\n竹藝術裝置／2/15-2/23\r\n活動邀請國際知名的3位台灣竹藝大師-范承宗、游文富、林靖格合作，結合竹林地景打造南投專屬的竹工藝，他們將在竹林中各自創作一件專屬的竹藝術裝置，為現場增添藝術氛圍，遊客可能漫步於竹林間，近距離欣賞大師級藝術作品，體驗竹林與藝術交融的獨特魅力。\r\n竹林療癒／2/15、2/23 10:00-11:30、14:00-15:30、2/16、2/22 14:00-15:30\r\n練習開啟身體五感，覺察自然環境，最後找到自己的內心，就如同「休息」一詞，就是一個人依靠著一棵樹，找到自己的心。 \r\n頌缽音療／2/16、2/23 10:00-11:30\r\n竹筒飯／2/15-2/16 9:00-13:00（2梯次）\r\n一起來動手作享用最道地的竹筒飯吧！享用完後的竹筒還可以現場彩繪，化身筆筒帶回家！還有熱騰騰的筍湯可以享用。\r\n黃金竹筍包／2/22-2/23 9:00-13:00（2梯次）\r\n來到鹿谷不能錯過美味竹筍包！親手製作一份竹筍包帶回家，還有熱騰騰的筍湯可以享用。\r\nBoojour竹夢午茶／2/16 14:30-16:00\r\n請曾於多家米其林三星法式餐廳服務過的主廚Pierre Mosser為竹夢森活節全新打造-“Boo”jour!竹夢午茶菜單，以在地最新鮮美味的筍為主角入菜，再由米其林主廚賦予全新的靈魂；加上在地的竹筍小點、南投冠軍咖啡，以及在地的竹藝DIY體驗，享受一個知性浪漫的午後時光\r\n竹林生態導覽&竹林茶席品茗／2/15-2/16、2/22-2/23，09:00-14:30，每天5梯次，體驗時間約2小時。\r\n以導覽長源圳生態步道、解說方式闡述地方生活文化與早期農業發展及由圳溝灌溉延伸的生活型態。並瞭解孟宗竹發源、林爽文最後戰役的歷史文化故事，並實地認知竹的生態成長等豐富內容，加深遊客對小半天的文化印象。在遊覽完後前往竹林茶席，透過茶席演繹瞭解茶文化，體驗慢活休閒之旅，達到減塑行銷目的。\r\n\r\n線上報名\r\n千人竹筒飯&黃金竹筍包\r\nhttps://2025nantoubamboo.kktix.cc/events/bamboorice\r\n竹林療癒\r\nhttps://2025nantoubamboo.kktix.cc/events/healing\r\n竹林生態導覽+茶席\r\nhttps://2025nantoubamboo.kktix.cc/events/naturetea\r\nBoojour竹夢午茶\r\nhttps://2025nantoubamboo.kktix.cc/events/afternoontea2', '南投縣政府', '南投縣鹿谷鄉', '鹿谷鄉（南投縣）=', 23.73776029, 120.7815065, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='竹子是南投重要物產，竹業文化歷史悠久，現代的竹文化發展也與時俱進，傳統產業透過轉型後成為兼具觀光休閒、生態保育、地方產業、教育傳承的南投特色文化。此次「2025南投竹夢森活節」共有4天活動，活動以當地的竹美食、竹文化與竹生活為基底，揉合創意推出四天主題活動，體驗竹的百變風貌，DIY、茶席及導覽等相關體驗活動自即日起開放報名。\r\n南投「竹夢森活節」即將登場！走進竹林深處，感受竹藝、茶席與自然交織的靜謐時光，讓身心沉浸在綠意與茶香之中。這不僅是一場活動，更是一場回歸自然、品味生活的美好體驗。\r\n活動亮點\r\n竹藝術裝置／2/15-2/23\r\n活動邀請國際知名的3位台灣竹藝大師-范承宗、游文富、林靖格合作，結合竹林地景打造南投專屬的竹工藝，他們將在竹林中各自創作一件專屬的竹藝術裝置，為現場增添藝術氛圍，遊客可能漫步於竹林間，近距離欣賞大師級藝術作品，體驗竹林與藝術交融的獨特魅力。\r\n竹林療癒／2/15、2/23 10:00-11:30、14:00-15:30、2/16、2/22 14:00-15:30\r\n練習開啟身體五感，覺察自然環境，最後找到自己的內心，就如同「休息」一詞，就是一個人依靠著一棵樹，找到自己的心。 \r\n頌缽音療／2/16、2/23 10:00-11:30\r\n竹筒飯／2/15-2/16 9:00-13:00（2梯次）\r\n一起來動手作享用最道地的竹筒飯吧！享用完後的竹筒還可以現場彩繪，化身筆筒帶回家！還有熱騰騰的筍湯可以享用。\r\n黃金竹筍包／2/22-2/23 9:00-13:00（2梯次）\r\n來到鹿谷不能錯過美味竹筍包！親手製作一份竹筍包帶回家，還有熱騰騰的筍湯可以享用。\r\nBoojour竹夢午茶／2/16 14:30-16:00\r\n請曾於多家米其林三星法式餐廳服務過的主廚Pierre Mosser為竹夢森活節全新打造-“Boo”jour!竹夢午茶菜單，以在地最新鮮美味的筍為主角入菜，再由米其林主廚賦予全新的靈魂；加上在地的竹筍小點、南投冠軍咖啡，以及在地的竹藝DIY體驗，享受一個知性浪漫的午後時光\r\n竹林生態導覽&竹林茶席品茗／2/15-2/16、2/22-2/23，09:00-14:30，每天5梯次，體驗時間約2小時。\r\n以導覽長源圳生態步道、解說方式闡述地方生活文化與早期農業發展及由圳溝灌溉延伸的生活型態。並瞭解孟宗竹發源、林爽文最後戰役的歷史文化故事，並實地認知竹的生態成長等豐富內容，加深遊客對小半天的文化印象。在遊覽完後前往竹林茶席，透過茶席演繹瞭解茶文化，體驗慢活休閒之旅，達到減塑行銷目的。\r\n\r\n線上報名\r\n千人竹筒飯&黃金竹筍包\r\nhttps://2025nantoubamboo.kktix.cc/events/bamboorice\r\n竹林療癒\r\nhttps://2025nantoubamboo.kktix.cc/events/healing\r\n竹林生態導覽+茶席\r\nhttps://2025nantoubamboo.kktix.cc/events/naturetea\r\nBoojour竹夢午茶\r\nhttps://2025nantoubamboo.kktix.cc/events/afternoontea2', `organizer`='南投縣政府', `address`='南投縣鹿谷鄉', `location`='鹿谷鄉（南投縣）=', `latitude`=23.73776029, `longitude`=120.7815065, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2926b3240c403d942f', '《世界上光的光》 二二八紀念草地音樂會', '多年來以草地音樂會開闊自由的形式讓更多人參與今年以《世界上光的光》為名的二二八紀念草地音樂會，/28(五)晚上七點在高美館草坡登場，集結歌手-以莉．高露、林宗興、高雄室內合唱團和由楊智欽指揮的高雄市交響樂團現場演出十多首與愛和台灣有關的曲目。', '財團法人高雄市愛樂文化藝術基金會', '高雄市鼓山區6鄰美術館路80號', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '高雄市立美術館', 22.6566968, 120.2865511, '無資料', 'https://ksaf.khcc.gov.tw/tour/Details.aspx?Parser=99,6,22,,,,178', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《世界上光的光》 二二八紀念草地音樂會', `description`='多年來以草地音樂會開闊自由的形式讓更多人參與今年以《世界上光的光》為名的二二八紀念草地音樂會，/28(五)晚上七點在高美館草坡登場，集結歌手-以莉．高露、林宗興、高雄室內合唱團和由楊智欽指揮的高雄市交響樂團現場演出十多首與愛和台灣有關的曲目。', `organizer`='財團法人高雄市愛樂文化藝術基金會', `address`='高雄市鼓山區6鄰美術館路80號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='高雄市立美術館', `latitude`=22.6566968, `longitude`=120.2865511, `ticket_price`='無資料', `source_url`='https://ksaf.khcc.gov.tw/tour/Details.aspx?Parser=99,6,22,,,,178', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2926b3240c403d9430', 'KSAF《小魔女-瑪蒂達》電影交響草地音樂會/ Matilda in Concert', '改編自英國著名兒童文學作家羅德·達爾（Roald Dahl）的獲獎小說，並由丹尼·德維托（Danny DeVito）執導，劇本由尼古拉斯·卡贊（Nicholas Kazan）和羅賓·史薇寇德（Robin Swicord）共同創作，由吳曜宇指揮率領高雄市交響樂團現場演奏，音樂與電影畫面完美融合，為觀眾帶來全新的視覺與聽覺震撼體驗。', '高雄市政府文化局', '高雄市鼓山區6鄰美術館路80號', '2025-03-08 00:00:00', '2025-03-09 00:00:00', '高雄市立美術館', 22.6566968, 120.2865511, '--+499', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='KSAF《小魔女-瑪蒂達》電影交響草地音樂會/ Matilda in Concert', `description`='改編自英國著名兒童文學作家羅德·達爾（Roald Dahl）的獲獎小說，並由丹尼·德維托（Danny DeVito）執導，劇本由尼古拉斯·卡贊（Nicholas Kazan）和羅賓·史薇寇德（Robin Swicord）共同創作，由吳曜宇指揮率領高雄市交響樂團現場演奏，音樂與電影畫面完美融合，為觀眾帶來全新的視覺與聽覺震撼體驗。', `organizer`='高雄市政府文化局', `address`='高雄市鼓山區6鄰美術館路80號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='高雄市立美術館', `latitude`=22.6566968, `longitude`=120.2865511, `ticket_price`='--+499', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2926b3240c403d9432', '春日野遊音樂會', '三天連假的最佳安排，就是這場音樂會！\r\n今年的假期怎麼過？當然是來溪頭米堤聽場好音樂。\r\n特別邀請多位超實力派音樂家，用美妙的旋律，陪你一起開啟最放鬆、最愉快的夜晚。\r\n邀請您和親朋好友一起來吧，感受現場音樂的魅力，坐在悠閒的氛圍中，享受一段真正屬於自己的時光。', '米堤大飯店集團', '南投縣鹿谷鄉', '2025-02-28 00:00:00', '2025-03-01 00:00:00', '鹿谷鄉（南投縣）=', 23.73776029, 120.7815065, '無資料', 'https://www.facebook.com/LeMidiHotel', '[]') ON DUPLICATE KEY UPDATE `activity_name`='春日野遊音樂會', `description`='三天連假的最佳安排，就是這場音樂會！\r\n今年的假期怎麼過？當然是來溪頭米堤聽場好音樂。\r\n特別邀請多位超實力派音樂家，用美妙的旋律，陪你一起開啟最放鬆、最愉快的夜晚。\r\n邀請您和親朋好友一起來吧，感受現場音樂的魅力，坐在悠閒的氛圍中，享受一段真正屬於自己的時光。', `organizer`='米堤大飯店集團', `address`='南投縣鹿谷鄉', `start_date`='2025-02-28 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='鹿谷鄉（南投縣）=', `latitude`=23.73776029, `longitude`=120.7815065, `ticket_price`='無資料', `source_url`='https://www.facebook.com/LeMidiHotel', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2926b3240c403d9433', '用藝術傳遞愛心：《竹光山影》義賣展覽', '竹山，一個對孩童而言是純真又充滿想像的小鎮。鴨子學苑的孩子們近半年的時間用畫筆與色彩重新詮釋了他們心中的家鄉。這些作品不只是畫，更是他們對故鄉的想像、情感與記憶的具象呈現。每一幅畫作都展現了他們獨特的視角，跨越了時間與空間。在翠綠的竹林與飄渺的雲霧間，孩子們捕捉著家鄉的每一道光影，每一片情感。這些畫作仿佛讓人看見了小鎮的靜謐與自然的詩意。當您細細品味時，彷彿也能感受到孩子們那份純真的熱情與對家鄉的深情。', '米堤大飯店集團', '南投縣鹿谷鄉', '2025-01-01 00:00:00', '2025-03-31 00:00:00', '鹿谷鄉（南投縣）=', 23.73776029, 120.7815065, '無資料', 'https://www.facebook.com/LeMidiHotel', '[]') ON DUPLICATE KEY UPDATE `activity_name`='用藝術傳遞愛心：《竹光山影》義賣展覽', `description`='竹山，一個對孩童而言是純真又充滿想像的小鎮。鴨子學苑的孩子們近半年的時間用畫筆與色彩重新詮釋了他們心中的家鄉。這些作品不只是畫，更是他們對故鄉的想像、情感與記憶的具象呈現。每一幅畫作都展現了他們獨特的視角，跨越了時間與空間。在翠綠的竹林與飄渺的雲霧間，孩子們捕捉著家鄉的每一道光影，每一片情感。這些畫作仿佛讓人看見了小鎮的靜謐與自然的詩意。當您細細品味時，彷彿也能感受到孩子們那份純真的熱情與對家鄉的深情。', `organizer`='米堤大飯店集團', `address`='南投縣鹿谷鄉', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='鹿谷鄉（南投縣）=', `latitude`=23.73776029, `longitude`=120.7815065, `ticket_price`='無資料', `source_url`='https://www.facebook.com/LeMidiHotel', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2926b3240c403d9435', '藝思C複合媒材創作展', '在2024年度特別邀請溪口鄉內的藝術創作者林嘉鈴老師，帶領長者們展開一系列生活美學創作課程。這些課程獨特地將藝術與溪口當地文化結合，讓「醫事C」活動轉型升級為有意義的「藝思C」美學，持續激發長者的學習興趣，並透過教學互動實現相互成長，真正展現「活到老、學到老、享受老」的精神。\r\n本展覽特邀溪口衛生所回到客家館(原舊衛生所)進行展出，具有非凡的意義。此次參展的長者們，平均年齡約為75歲，其中年紀最長者達90歲。在這個活動中，長者們積極參與，豐富他們的人生經歷，提升自我實現的感受。', '嘉義縣溪口鄉公所', '嘉義縣全區域', '2025-01-17 00:00:00', '2025-03-31 00:00:00', '嘉義縣', 0, 0, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝思C複合媒材創作展', `description`='在2024年度特別邀請溪口鄉內的藝術創作者林嘉鈴老師，帶領長者們展開一系列生活美學創作課程。這些課程獨特地將藝術與溪口當地文化結合，讓「醫事C」活動轉型升級為有意義的「藝思C」美學，持續激發長者的學習興趣，並透過教學互動實現相互成長，真正展現「活到老、學到老、享受老」的精神。\r\n本展覽特邀溪口衛生所回到客家館(原舊衛生所)進行展出，具有非凡的意義。此次參展的長者們，平均年齡約為75歲，其中年紀最長者達90歲。在這個活動中，長者們積極參與，豐富他們的人生經歷，提升自我實現的感受。', `organizer`='嘉義縣溪口鄉公所', `address`='嘉義縣全區域', `start_date`='2025-01-17 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='嘉義縣', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2926b3240c403d9437', '陽明分館114年2月主題書展', '當月主題如下：\r\n1.東南亞主題書展：越讀越愛~閱讀越南之旅\r\n展期：114/01/01~114/12/31\r\n展示：看故事學越南語、用中文說越南語、越南語一學就上手\r\n等優良圖書。\r\n2.新春主題書展~金蛇騰達\r\n展期:114/01/01~114/02/27\r\n展示:買下未來、錢的分配術、存股輕鬆學等優良圖書。舉辦圖書展覽，增進讀者閱讀習慣。', '高雄市立圖書館總館', '高雄市三民區陽明路300號3樓', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '高雄市立圖書館陽明分館', 22.643485, 120.34232, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陽明分館114年2月主題書展', `description`='當月主題如下：\r\n1.東南亞主題書展：越讀越愛~閱讀越南之旅\r\n展期：114/01/01~114/12/31\r\n展示：看故事學越南語、用中文說越南語、越南語一學就上手\r\n等優良圖書。\r\n2.新春主題書展~金蛇騰達\r\n展期:114/01/01~114/02/27\r\n展示:買下未來、錢的分配術、存股輕鬆學等優良圖書。舉辦圖書展覽，增進讀者閱讀習慣。', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區陽明路300號3樓', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='高雄市立圖書館陽明分館', `latitude`=22.643485, `longitude`=120.34232, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2926b3240c403d9441', '臺灣工藝百年進行式特展', '這是一個以工藝為主體，由時間的概念、觀看、感知，直入臺灣工藝的展覽。\r\n1920年《臺灣通史》出版，「工藝」首度成志。以百年為尺度，我們清楚看見工藝的模樣：是這塊土地上日常所生成的美、是人們豐富交流所煥發的活潑創意、是製作不歇的身影所凝聚的精神厚度，也是永遠迎向環境挑戰開創的勇氣。\r\n臺灣工藝，百年前已呈現虹彩般的光譜，此時此刻，我們習慣歸諸於傳統的，其實也和我們以為最新穎的，同樣屬於「現在」的一部分。這百年來，臺灣工藝所保有的多樣性，正是讓我們擁有能夠選擇的自由、面向未來的豐厚資本。\r\n於是，這個展覽並非意圖呈現一段線性發展的工藝史，而是希望透過百年的梳理，看見臺灣工藝滾動、累積並自我再生的特質。\r\n\r\n導覽預約 https://event.culture.tw/NTCRI/portal/Tour/J5401MAction', '國立臺灣工藝研究發展中心', '南投縣草屯鎮中正路573號', '2025-01-01 00:00:00', '2025-06-29 00:00:00', '國立臺灣工藝研究發展中心（臺灣工藝文化園區）', 23.9807747, 120.6918567, '無資料', 'https://www.ntcri.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺灣工藝百年進行式特展', `description`='這是一個以工藝為主體，由時間的概念、觀看、感知，直入臺灣工藝的展覽。\r\n1920年《臺灣通史》出版，「工藝」首度成志。以百年為尺度，我們清楚看見工藝的模樣：是這塊土地上日常所生成的美、是人們豐富交流所煥發的活潑創意、是製作不歇的身影所凝聚的精神厚度，也是永遠迎向環境挑戰開創的勇氣。\r\n臺灣工藝，百年前已呈現虹彩般的光譜，此時此刻，我們習慣歸諸於傳統的，其實也和我們以為最新穎的，同樣屬於「現在」的一部分。這百年來，臺灣工藝所保有的多樣性，正是讓我們擁有能夠選擇的自由、面向未來的豐厚資本。\r\n於是，這個展覽並非意圖呈現一段線性發展的工藝史，而是希望透過百年的梳理，看見臺灣工藝滾動、累積並自我再生的特質。\r\n\r\n導覽預約 https://event.culture.tw/NTCRI/portal/Tour/J5401MAction', `organizer`='國立臺灣工藝研究發展中心', `address`='南投縣草屯鎮中正路573號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='國立臺灣工藝研究發展中心（臺灣工藝文化園區）', `latitude`=23.9807747, `longitude`=120.6918567, `ticket_price`='無資料', `source_url`='https://www.ntcri.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2a26b3240c403d9446', '高雄市現代畫學會雙年展  「 邊陲的中央 - 挑戰AI的思維」', '高雄長期被視為藝術「邊陲」，然而資訊科技的普及讓地方藝術快速獲得關注，打破主流媒體對「邊陲藝術」的刻板印象。隨著AI技術挑戰藝術創作的傳統，從模仿行為到創作過程的極簡化，藝術家面臨巨大衝擊，但他們以不服輸的熱情應對挑戰，將危機化為轉機。AI兵臨城下，藝術家透過創造力突破技術瓶頸，實現思想與藝術形式的革新。這場藝術與科技的對抗，將決定未來創作的可能性與深度。', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-03-21 00:00:00', '2025-04-01 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4076', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市現代畫學會雙年展  「 邊陲的中央 - 挑戰AI的思維」', `description`='高雄長期被視為藝術「邊陲」，然而資訊科技的普及讓地方藝術快速獲得關注，打破主流媒體對「邊陲藝術」的刻板印象。隨著AI技術挑戰藝術創作的傳統，從模仿行為到創作過程的極簡化，藝術家面臨巨大衝擊，但他們以不服輸的熱情應對挑戰，將危機化為轉機。AI兵臨城下，藝術家透過創造力突破技術瓶頸，實現思想與藝術形式的革新。這場藝術與科技的對抗，將決定未來創作的可能性與深度。', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-04-01 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4076', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a65b2a26b3240c403d9447', '嘉義縣林業職業工會烙畫工藝展', '烙畫是一種透過電燒筆在木材、皮革等材質上創作的藝術，以不同温度的燒烙技巧，描繪出如素描般的層次與明暗，呈現獨特的藝術魅力。\r\n相比油畫、水彩等畫作，烙畫注重細膩層次的表現，需耐心雕琢，緩慢烙出深淺變化，構成精美的圖像。\r\n木材是最理想的創作素材，無論大小形狀，只要平整即可化為藝術精品，增添木材的價值與保存意義。\r\n創作過程能讓人靜心，急躁者也能在其中培養耐性，達到「心、身、靈」的平和境界，徹底沉浸於這門獨特的藝術之中。 因此烙畫又被稱為一神奇的藝術美學。', '嘉義縣番路鄉公所', '嘉義縣全區域', '2025-01-01 00:00:00', '2025-02-27 00:00:00', '嘉義縣', '無資料', '無資料', '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='嘉義縣林業職業工會烙畫工藝展', `description`='烙畫是一種透過電燒筆在木材、皮革等材質上創作的藝術，以不同温度的燒烙技巧，描繪出如素描般的層次與明暗，呈現獨特的藝術魅力。\r\n相比油畫、水彩等畫作，烙畫注重細膩層次的表現，需耐心雕琢，緩慢烙出深淺變化，構成精美的圖像。\r\n木材是最理想的創作素材，無論大小形狀，只要平整即可化為藝術精品，增添木材的價值與保存意義。\r\n創作過程能讓人靜心，急躁者也能在其中培養耐性，達到「心、身、靈」的平和境界，徹底沉浸於這門獨特的藝術之中。 因此烙畫又被稱為一神奇的藝術美學。', `organizer`='嘉義縣番路鄉公所', `address`='嘉義縣全區域', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='嘉義縣', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a6ff6907f3a329be637c82', '神技之巔.幻獸齊聚—開拓盃原型賽經典作品聯展', '開拓盃原型賽自創立以來，已走過十年歷程，成為亞洲歷史最悠久、規模最大且最具影響力的原型創作賽事。每年參賽作品數量穩定超過200件，展現新銳與資深創作者的非凡創意與精湛技藝。近年來，賽事更特別邀請日本頂尖原型師擔任評審，為賽事注入國際視野，並大幅提升其專業性與公信力。\r\n本次展覽精選得獎作品與評審的優秀創作，涵蓋多樣風格與題材。每件作品都體現創作者對藝術的不懈追求與對細節的極致掌控，彰顯獨具個性的雕塑風格與高超技術。這是一場藝術與創意的饗宴，誠邀您前來共襄盛舉，感受原型藝術的非凡魅力！', '苗栗縣苗北藝文中心', '苗栗縣350苗栗縣竹南鎮公園路206號', '2025-03-08 00:00:00', '2025-05-18 00:00:00', '苗栗縣苗北藝文中心展覽室', 0, 0, '無資料', 'https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2XS9BWQxUDEA', '[]') ON DUPLICATE KEY UPDATE `activity_name`='神技之巔.幻獸齊聚—開拓盃原型賽經典作品聯展', `description`='開拓盃原型賽自創立以來，已走過十年歷程，成為亞洲歷史最悠久、規模最大且最具影響力的原型創作賽事。每年參賽作品數量穩定超過200件，展現新銳與資深創作者的非凡創意與精湛技藝。近年來，賽事更特別邀請日本頂尖原型師擔任評審，為賽事注入國際視野，並大幅提升其專業性與公信力。\r\n本次展覽精選得獎作品與評審的優秀創作，涵蓋多樣風格與題材。每件作品都體現創作者對藝術的不懈追求與對細節的極致掌控，彰顯獨具個性的雕塑風格與高超技術。這是一場藝術與創意的饗宴，誠邀您前來共襄盛舉，感受原型藝術的非凡魅力！', `organizer`='苗栗縣苗北藝文中心', `address`='苗栗縣350苗栗縣竹南鎮公園路206號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='苗栗縣苗北藝文中心展覽室', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2XS9BWQxUDEA', `image_url`='[]';
