INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a78e2826b3240c403d944f', '2025TIFA X 法律白話文運動《誰是惡女？重新定義她的反派人生》', '無資料', '無資料', '臺北市中山區林森北路107巷10號B1', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '濕地Venue B1', 25.03531287, 121.51816187, '無資料', 'https://www.opentix.life/program/1886373783225688064', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025TIFA X 法律白話文運動《誰是惡女？重新定義她的反派人生》', `description`='無資料', `organizer`='無資料', `address`='臺北市中山區林森北路107巷10號B1', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='濕地Venue B1', `latitude`=25.03531287, `longitude`=121.51816187, `ticket_price`='無資料', `source_url`='https://www.opentix.life/program/1886373783225688064', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c85526b3240c403d9450', '觸動時刻-鄭志德師生聯展(免費參觀)', '主辦單位表示，藝術家鄭志德現任教於國立臺灣師範大學進修推廣學院，個人作品曾獲得第16屆奇美藝術人才培訓首獎、第4屆聯邦美術新人獎優選、第2屆全國百號油畫大賽第二名、2013年法國藝術家沙龍銀牌獎等國內外許多藝術獎項，此次展覽由鄭老師帶領16位學生展現師生創作成果，展覽名稱「觸動時刻」，傳達出參展者在人物、風景、靜物等主題創作及生活中的體悟及靈光乍現的感動時刻。\n\n \n\n  本次展品類別多元，如鄭老師的《太空遊記》－期許將來臺灣可以放眼國際也放眼太空，表現童趣。林美嫻的《穿和服的女孩》－以溫潤色調表現女孩的稚嫩及喜氣。陳俊誠的《誰打破恐龍蛋》－以詼諧趣味導引觀眾重新組合他們的故事。劉立潔的《佛朗明哥舞者》－透過描繪舞者傳遞異國文化的風采。簡子寧的《池塘》－看似微不足道的事物，卻有其獨特與價值等等。敬邀一同感受藝術家的觸動時刻。', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-02-22 00:00:00', '2025-03-09 00:00:00', '三樓藝廊', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50670', '[]') ON DUPLICATE KEY UPDATE `activity_name`='觸動時刻-鄭志德師生聯展(免費參觀)', `description`='主辦單位表示，藝術家鄭志德現任教於國立臺灣師範大學進修推廣學院，個人作品曾獲得第16屆奇美藝術人才培訓首獎、第4屆聯邦美術新人獎優選、第2屆全國百號油畫大賽第二名、2013年法國藝術家沙龍銀牌獎等國內外許多藝術獎項，此次展覽由鄭老師帶領16位學生展現師生創作成果，展覽名稱「觸動時刻」，傳達出參展者在人物、風景、靜物等主題創作及生活中的體悟及靈光乍現的感動時刻。\n\n \n\n  本次展品類別多元，如鄭老師的《太空遊記》－期許將來臺灣可以放眼國際也放眼太空，表現童趣。林美嫻的《穿和服的女孩》－以溫潤色調表現女孩的稚嫩及喜氣。陳俊誠的《誰打破恐龍蛋》－以詼諧趣味導引觀眾重新組合他們的故事。劉立潔的《佛朗明哥舞者》－透過描繪舞者傳遞異國文化的風采。簡子寧的《池塘》－看似微不足道的事物，卻有其獨特與價值等等。敬邀一同感受藝術家的觸動時刻。', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='三樓藝廊', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50670', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c85526b3240c403d9452', '「畫出性別界限，勇敢Say No」114年性平推廣活動(免費參加)', '緣起\r\n	為落實推動聯合國性別平等永續發展目標與落實行政院持續推動性平三法修法通過等政策，並呼應行政院性別平等會提出「推動性別平等政策綱領」與「落實消除對婦女一切形式歧視公約(CEDAW)」工作目標，114年與臺北市婦女館合辦規劃「畫出性別界限，勇敢Say No」性平推廣活動，透過工作坊及親子活動，引導家庭照顧者與教育者對兒童性平教育、自我表達能力及自我保護的重視。\r\n	合辦單位\r\n	臺北市婦女館 \r\n	時間\r\n	\r\n		4月12日(六) 下午15:30-17:30。\r\n		5月24日(六) 下午13:30-16:30。\r\n		6月  7日(六) 下午14:00-16:00。\r\n	\r\n	\r\n	地點\r\n	中正紀念堂圖書室(3展廳內)。\r\n	費用\r\n	活動皆免費報名參加。\r\n	活動講師\r\n	陳東玉老師/秘蜜基地繪本屋創辦人、臺北婦女館性平教材《性別有界線著色本》顧問。\r\n	活動內容\r\n\r\n\r\n\r\n	\r\n		\r\n			\r\n			場次\r\n			\r\n			\r\n			時間\r\n			\r\n			\r\n			活動名稱\r\n			\r\n			\r\n			對象\r\n			\r\n		\r\n		\r\n			\r\n			1\r\n			\r\n			\r\n			4/12(週六)\r\n\r\n			15:30~17:30\r\n			\r\n			\r\n			「我的身體是我的，我自己決定－身體界線」親子工作坊\r\n			\r\n			\r\n			20組親子\r\n\r\n			一大一小，小孩年齡3-6歲\r\n			\r\n		\r\n		\r\n			\r\n			2\r\n			\r\n			\r\n			5/24(週六)\r\n\r\n			13:30~16:30\r\n			\r\n			\r\n			「找到自在的距離－身體界線」種子師資培力工作坊\r\n\r\n			4/1(二)本系統開放報名\r\n			\r\n			\r\n			25人\r\n\r\n			博物館與教職人員為優先\r\n			\r\n		\r\n		\r\n			\r\n			3\r\n			\r\n			\r\n			6/7(週六)\r\n\r\n			14:00~16:00\r\n			\r\n			\r\n			「我的身體是我的，我自己決定－身體界線」親子工作坊\r\n\r\n			4/21(一)本系統開放報名\r\n			\r\n			\r\n			20組親子\r\n\r\n			一大一小，小孩年齡7-10歲\r\n			\r\n		\r\n	\r\n\r\n\r\n\r\n	時數證明\r\n\r\n\r\n      參與5月24日種子師資培力工作坊場次之學員，由本處發給研習時數證書。\r\n\r\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '中正紀念堂圖書室（3展廳內）', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50529', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「畫出性別界限，勇敢Say No」114年性平推廣活動(免費參加)', `description`='緣起\r\n	為落實推動聯合國性別平等永續發展目標與落實行政院持續推動性平三法修法通過等政策，並呼應行政院性別平等會提出「推動性別平等政策綱領」與「落實消除對婦女一切形式歧視公約(CEDAW)」工作目標，114年與臺北市婦女館合辦規劃「畫出性別界限，勇敢Say No」性平推廣活動，透過工作坊及親子活動，引導家庭照顧者與教育者對兒童性平教育、自我表達能力及自我保護的重視。\r\n	合辦單位\r\n	臺北市婦女館 \r\n	時間\r\n	\r\n		4月12日(六) 下午15:30-17:30。\r\n		5月24日(六) 下午13:30-16:30。\r\n		6月  7日(六) 下午14:00-16:00。\r\n	\r\n	\r\n	地點\r\n	中正紀念堂圖書室(3展廳內)。\r\n	費用\r\n	活動皆免費報名參加。\r\n	活動講師\r\n	陳東玉老師/秘蜜基地繪本屋創辦人、臺北婦女館性平教材《性別有界線著色本》顧問。\r\n	活動內容\r\n\r\n\r\n\r\n	\r\n		\r\n			\r\n			場次\r\n			\r\n			\r\n			時間\r\n			\r\n			\r\n			活動名稱\r\n			\r\n			\r\n			對象\r\n			\r\n		\r\n		\r\n			\r\n			1\r\n			\r\n			\r\n			4/12(週六)\r\n\r\n			15:30~17:30\r\n			\r\n			\r\n			「我的身體是我的，我自己決定－身體界線」親子工作坊\r\n			\r\n			\r\n			20組親子\r\n\r\n			一大一小，小孩年齡3-6歲\r\n			\r\n		\r\n		\r\n			\r\n			2\r\n			\r\n			\r\n			5/24(週六)\r\n\r\n			13:30~16:30\r\n			\r\n			\r\n			「找到自在的距離－身體界線」種子師資培力工作坊\r\n\r\n			4/1(二)本系統開放報名\r\n			\r\n			\r\n			25人\r\n\r\n			博物館與教職人員為優先\r\n			\r\n		\r\n		\r\n			\r\n			3\r\n			\r\n			\r\n			6/7(週六)\r\n\r\n			14:00~16:00\r\n			\r\n			\r\n			「我的身體是我的，我自己決定－身體界線」親子工作坊\r\n\r\n			4/21(一)本系統開放報名\r\n			\r\n			\r\n			20組親子\r\n\r\n			一大一小，小孩年齡7-10歲\r\n			\r\n		\r\n	\r\n\r\n\r\n\r\n	時數證明\r\n\r\n\r\n      參與5月24日種子師資培力工作坊場次之學員，由本處發給研習時數證書。\r\n\r\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='中正紀念堂圖書室（3展廳內）', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50529', `image_url`='[]';
