INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c92826b3240c403d9459', '(114年度)第二階段「校外文化體驗計畫」(9條路線、200台遊覽車)(113年9月至114年11月)', '2025年 #校外文化體驗 全新路線來啦！\r\n本次開放報名路線將讓學童在遊戲中學習，透過手作、館舍實境解謎遊戲包，參與遊戲活動同時認識新竹的歷史與族群文化，認識新竹多元文化特色。\r\n󠀠\r\n老師同學們 準備好一起來探索了嗎😎\r\n', '新竹市文化局', '新竹市全區域', '2025-02-01 00:00:00', '2025-11-30 00:00:00', '新竹市', 0, 0, '無資料', 'https://www.hccg.gov.tw/ch/home.jsp?id=30121&parentpath=0,16&mcustomize=municipalnews_view.jsp&tools', '[]') ON DUPLICATE KEY UPDATE `activity_name`='(114年度)第二階段「校外文化體驗計畫」(9條路線、200台遊覽車)(113年9月至114年11月)', `description`='2025年 #校外文化體驗 全新路線來啦！\r\n本次開放報名路線將讓學童在遊戲中學習，透過手作、館舍實境解謎遊戲包，參與遊戲活動同時認識新竹的歷史與族群文化，認識新竹多元文化特色。\r\n󠀠\r\n老師同學們 準備好一起來探索了嗎😎\r\n', `organizer`='新竹市文化局', `address`='新竹市全區域', `start_date`='2025-02-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='新竹市', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.hccg.gov.tw/ch/home.jsp?id=30121&parentpath=0,16&mcustomize=municipalnews_view.jsp&tools', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c92926b3240c403d945a', '十年征途 疾速歲月 清大賽車工廠追夢之旅｜國立清華大學圖書館', '「清大賽車工廠(NTHU Racing )」是由一群對賽車懷抱熱忱的清華學生，於2015年3月所組成的「學生方程式賽車團隊」。網羅清華校內各系所來自不同領域熱愛賽車及喜愛工程技術的學生發揮巧思，將工程學以致用，不斷研發精進技術，更考驗團隊商業行銷、專案合作與知識傳承的多元能力，是全方位的學習與磨練。\r\n從零打造一台賽車，團隊成員須自主籌備資金、參加考試、鑽研技術，串連各個專業領域並從中培養解決問題的能力，「清大賽車工廠」可說是清大跨領域多元學習最好的體現。\r\n期盼藉由本展覽，讓觀者看見在跨領域多元學習中，同學如何透過更多的自我探索與多元化的學習模式，並憑藉在校所學及自身創意，親手設計、打造出一台「學生方程式賽車」。藉此鼓勵清華學子勇於追求夢想，在這條逐夢的道路上，能盡情發揮所長，創造學生時期的獨特記憶。', '國立清華大學', '新竹市東區光復路二段101號', '2025-01-01 00:00:00', '2025-03-18 00:00:00', '國立清華大學', 24.7964538, 120.9966725, '無資料', 'https://www.lib.nthu.edu.tw/events/2024/Racing/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='十年征途 疾速歲月 清大賽車工廠追夢之旅｜國立清華大學圖書館', `description`='「清大賽車工廠(NTHU Racing )」是由一群對賽車懷抱熱忱的清華學生，於2015年3月所組成的「學生方程式賽車團隊」。網羅清華校內各系所來自不同領域熱愛賽車及喜愛工程技術的學生發揮巧思，將工程學以致用，不斷研發精進技術，更考驗團隊商業行銷、專案合作與知識傳承的多元能力，是全方位的學習與磨練。\r\n從零打造一台賽車，團隊成員須自主籌備資金、參加考試、鑽研技術，串連各個專業領域並從中培養解決問題的能力，「清大賽車工廠」可說是清大跨領域多元學習最好的體現。\r\n期盼藉由本展覽，讓觀者看見在跨領域多元學習中，同學如何透過更多的自我探索與多元化的學習模式，並憑藉在校所學及自身創意，親手設計、打造出一台「學生方程式賽車」。藉此鼓勵清華學子勇於追求夢想，在這條逐夢的道路上，能盡情發揮所長，創造學生時期的獨特記憶。', `organizer`='國立清華大學', `address`='新竹市東區光復路二段101號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-18 00:00:00', `location`='國立清華大學', `latitude`=24.7964538, `longitude`=120.9966725, `ticket_price`='無資料', `source_url`='https://www.lib.nthu.edu.tw/events/2024/Racing/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c93026b3240c403d945b', '《拾‧舞 15》原林藝術舞集‧Y.L.A.D.C', '原林藝術舞集‧Y.L.A.D.C是桃園市政府原住民族行政局培植之原民藝術樂舞團隊，2010年成立至今，已逾15年之久。本館為團隊表演及創作基地，於館內進行樂舞展演與舞蹈創作，除了傳承傳統原民樂舞外，也致力發展創新的表演形式，試圖突破與追求嶄新的表演藝術。本展以《拾‧舞 15》為展覽主題，來回顧團隊15年來的精彩畫面，期許透過精彩的歌舞創作，讓來訪的旅客感受到原住民文魅力。\r\n※展出媒材以舞團簡介、歷年成果事蹟、各大演出活動影像播放。', '桃園市政府原住民族行政局', '桃園市大溪區員林路一段29巷101號', '2025-01-01 00:00:00', '2025-06-30 00:00:00', '桃園市原住民族文化會館', 24.896414, 121.2822299, '無資料', 'https://walkinto.in/tour/WJ5pxC97IHb1xc6lR97LB', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《拾‧舞 15》原林藝術舞集‧Y.L.A.D.C', `description`='原林藝術舞集‧Y.L.A.D.C是桃園市政府原住民族行政局培植之原民藝術樂舞團隊，2010年成立至今，已逾15年之久。本館為團隊表演及創作基地，於館內進行樂舞展演與舞蹈創作，除了傳承傳統原民樂舞外，也致力發展創新的表演形式，試圖突破與追求嶄新的表演藝術。本展以《拾‧舞 15》為展覽主題，來回顧團隊15年來的精彩畫面，期許透過精彩的歌舞創作，讓來訪的旅客感受到原住民文魅力。\r\n※展出媒材以舞團簡介、歷年成果事蹟、各大演出活動影像播放。', `organizer`='桃園市政府原住民族行政局', `address`='桃園市大溪區員林路一段29巷101號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='桃園市原住民族文化會館', `latitude`=24.896414, `longitude`=121.2822299, `ticket_price`='無資料', `source_url`='https://walkinto.in/tour/WJ5pxC97IHb1xc6lR97LB', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c93926b3240c403d945c', '無資料', '利用公播影片，播放供讀者欣賞，增加不同的閱讀視野。\r\n讓讀者走進圖書館裡，瞭解圖書館除了影視以外，還有豐富的館藏，進而感受書香氛圍，提升對閱讀的興趣。\r\n片名:小松鼠大偵探', '臺南市東區裕文圖書館', '臺南市東區裕信路237號', '臺南市東區裕文圖書館', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='利用公播影片，播放供讀者欣賞，增加不同的閱讀視野。\r\n讓讀者走進圖書館裡，瞭解圖書館除了影視以外，還有豐富的館藏，進而感受書香氛圍，提升對閱讀的興趣。\r\n片名:小松鼠大偵探', `organizer`='臺南市東區裕文圖書館', `address`='臺南市東區裕信路237號', `location`='臺南市東區裕文圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c93a26b3240c403d945d', '研書戲墨—研墨書會乙已會員展', '作品皆為紙本墨色媒材，甚而以書入畫，交織一體，錯落有致。將現代風格融入書作，為古老的藝術注入新的元素，創造出一股清新風貌。作者將情感籍由筆墨，以巧思融入於作品，從而獲得心靈的喜悅與平靜。篆隸楷行草各種書體在大作與小品中展現奇特美感，章法完善，變化靈活。', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-02-14 00:00:00', '2025-03-09 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='研書戲墨—研墨書會乙已會員展', `description`='作品皆為紙本墨色媒材，甚而以書入畫，交織一體，錯落有致。將現代風格融入書作，為古老的藝術注入新的元素，創造出一股清新風貌。作者將情感籍由筆墨，以巧思融入於作品，從而獲得心靈的喜悅與平靜。篆隸楷行草各種書體在大作與小品中展現奇特美感，章法完善，變化靈活。', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-02-14 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c93f26b3240c403d9460', '無資料', '由本館故事達人藉由說繪本故事，陪伴孩子們進入閱讀世界中，進而培養兒童閱讀的習慣與興趣，奠定良好的學習基礎。', '高雄市立圖書館總館', '高雄市前鎮區保泰路303號4樓', '高雄市立圖書館前鎮分館', 22.602476, 120.333005, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='由本館故事達人藉由說繪本故事，陪伴孩子們進入閱讀世界中，進而培養兒童閱讀的習慣與興趣，奠定良好的學習基礎。', `organizer`='高雄市立圖書館總館', `address`='高雄市前鎮區保泰路303號4樓', `location`='高雄市立圖書館前鎮分館', `latitude`=22.602476, `longitude`=120.333005, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c93f26b3240c403d9461', '114前鎮分館辦理【【賴lua-賴lua蛇】 兒童繪本主題書展', '帶孩子認識動物蛇的習性，以及有趣的蛇相關的有趣繪本故事內容。', '高雄市立圖書館總館', '高雄市前鎮區保泰路303號4樓', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '高雄市立圖書館前鎮分館', 22.602476, 120.333005, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114前鎮分館辦理【【賴lua-賴lua蛇】 兒童繪本主題書展', `description`='帶孩子認識動物蛇的習性，以及有趣的蛇相關的有趣繪本故事內容。', `organizer`='高雄市立圖書館總館', `address`='高雄市前鎮區保泰路303號4樓', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='高雄市立圖書館前鎮分館', `latitude`=22.602476, `longitude`=120.333005, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c94026b3240c403d9462', '無資料', '由高雄市立圖書館所培訓的一群義務故事志工，透過豐富的肢體語言與生動有大象不跳趣的互動方式，為小朋友說故事，現場並擺設相關書籍展示，歡迎大家踴躍參加。 ', '高雄市立圖書館總館', '高雄市小港區博學路365號', '高雄市立圖書館小港分館', 22.5605891, 120.3705758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='由高雄市立圖書館所培訓的一群義務故事志工，透過豐富的肢體語言與生動有大象不跳趣的互動方式，為小朋友說故事，現場並擺設相關書籍展示，歡迎大家踴躍參加。 ', `organizer`='高雄市立圖書館總館', `address`='高雄市小港區博學路365號', `location`='高雄市立圖書館小港分館', `latitude`=22.5605891, `longitude`=120.3705758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c94026b3240c403d9463', '綠色未來 閱讀啟航：SDGs主題書展', '翻閱書頁的同時，我們也翻開守護地球的行動篇章。書展精選SDGs（聯合國永續發展目標）相關主題書籍，涵蓋環境保護、氣候變遷、生態保育、綠色生活與循環經濟等領域，帶領讀者深入探索如何在日常生活中實踐永續理念。                                                                                                                                                        　　　透過閱讀，我們希望啟發每位讀者成為改變世界的一份子，從書本中汲取靈感，讓環保意識深植心中，邁向更美好的綠色未來。無論是親子共讀、學校教材，或是個人心靈成長，都能在這場書展中找到屬於自己的綠色航道。', '高雄市立圖書館總館', '高雄市小港區博學路365號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '高雄市立圖書館小港分館', 22.5605891, 120.3705758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='綠色未來 閱讀啟航：SDGs主題書展', `description`='翻閱書頁的同時，我們也翻開守護地球的行動篇章。書展精選SDGs（聯合國永續發展目標）相關主題書籍，涵蓋環境保護、氣候變遷、生態保育、綠色生活與循環經濟等領域，帶領讀者深入探索如何在日常生活中實踐永續理念。                                                                                                                                                        　　　透過閱讀，我們希望啟發每位讀者成為改變世界的一份子，從書本中汲取靈感，讓環保意識深植心中，邁向更美好的綠色未來。無論是親子共讀、學校教材，或是個人心靈成長，都能在這場書展中找到屬於自己的綠色航道。', `organizer`='高雄市立圖書館總館', `address`='高雄市小港區博學路365號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='高雄市立圖書館小港分館', `latitude`=22.5605891, `longitude`=120.3705758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c94226b3240c403d9465', '常設展-巧藝天工：傳統藝閣的經典創新', '本展提供傳統工藝發展、保存以及演繹的空間，除蓪草工藝打造紅雲搖曳的桃花林，並在充滿桃仔園意象的場景裡置放今年桃園閩南文化節得獎的藝閣車及製作工法。另有古早文創商店及暖板凳食堂，提供特色美食小吃。', '桃園市政府文化局', '桃園市八德區重慶街36-1號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '八塊厝民俗藝術村', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='常設展-巧藝天工：傳統藝閣的經典創新', `description`='本展提供傳統工藝發展、保存以及演繹的空間，除蓪草工藝打造紅雲搖曳的桃花林，並在充滿桃仔園意象的場景裡置放今年桃園閩南文化節得獎的藝閣車及製作工法。另有古早文創商店及暖板凳食堂，提供特色美食小吃。', `organizer`='桃園市政府文化局', `address`='桃園市八德區重慶街36-1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='八塊厝民俗藝術村', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c94226b3240c403d9466', '常設展-說咱的話：臺灣閩南語的說學逗唱', '映入眼簾呈現的是古早書院氛圍，書架上陳列相關閩南語繪本、書籍、電子書等，透過語言地圖讓參觀民眾了解桃園目前語言分布狀況，呈現閩南語各種腔調、分部或源流。', '桃園市政府文化局', '桃園市八德區重慶街36-1號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '八塊厝民俗藝術村', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='常設展-說咱的話：臺灣閩南語的說學逗唱', `description`='映入眼簾呈現的是古早書院氛圍，書架上陳列相關閩南語繪本、書籍、電子書等，透過語言地圖讓參觀民眾了解桃園目前語言分布狀況，呈現閩南語各種腔調、分部或源流。', `organizer`='桃園市政府文化局', `address`='桃園市八德區重慶街36-1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='八塊厝民俗藝術村', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c94226b3240c403d9467', '常設展-眾神庇佑：信仰文化的常民美學', '館內展覽以重要民俗信仰及節慶活動為主題，展出在地信仰特色、相關文物及慶典活動，透過寺廟分布圖及文化年曆，說明重大歲時節慶。', '桃園市政府文化局', '桃園市八德區重慶街36-1號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '八塊厝民俗藝術村', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='常設展-眾神庇佑：信仰文化的常民美學', `description`='館內展覽以重要民俗信仰及節慶活動為主題，展出在地信仰特色、相關文物及慶典活動，透過寺廟分布圖及文化年曆，說明重大歲時節慶。', `organizer`='桃園市政府文化局', `address`='桃園市八德區重慶街36-1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='八塊厝民俗藝術村', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c94226b3240c403d9468', '常設展-搬戲看戲：鑼鼓聲裡的戲棚千秋', '館內展示南北管、皮影戲、傀儡戲、偶戲、歌仔戲等劇種實際道具或戲臺，從歷史發展、樂器介紹、服裝道具、在地特色一一做說明，並搭配互動體驗，以多功能展演空間方式呈現。', '桃園市政府文化局', '桃園市八德區重慶街36-1號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '八塊厝民俗藝術村', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='常設展-搬戲看戲：鑼鼓聲裡的戲棚千秋', `description`='館內展示南北管、皮影戲、傀儡戲、偶戲、歌仔戲等劇種實際道具或戲臺，從歷史發展、樂器介紹、服裝道具、在地特色一一做說明，並搭配互動體驗，以多功能展演空間方式呈現。', `organizer`='桃園市政府文化局', `address`='桃園市八德區重慶街36-1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='八塊厝民俗藝術村', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c94226b3240c403d9469', '八德歷史人文特展《尋找八德DNA》', '本次特展透過歷史資料整理調查研究，爬梳八德(八塊厝)的前世今生，讓參觀民眾深度認識八德，包含地名由來、地形、氣候、水文、自然環境、交通運輸、人文特色、藝術(在地工藝匠師、表演藝術…)、宗教信仰、民俗活動、建築(古蹟、歷史建築)等，挖掘八德在地豐富的文化底蘊，推薦在地觀光景點介紹，如：浣衣池、埤塘、美食…等。', '桃園市政府文化局', '桃園市八德區重慶街36-1號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '八塊厝民俗藝術村', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='八德歷史人文特展《尋找八德DNA》', `description`='本次特展透過歷史資料整理調查研究，爬梳八德(八塊厝)的前世今生，讓參觀民眾深度認識八德，包含地名由來、地形、氣候、水文、自然環境、交通運輸、人文特色、藝術(在地工藝匠師、表演藝術…)、宗教信仰、民俗活動、建築(古蹟、歷史建築)等，挖掘八德在地豐富的文化底蘊，推薦在地觀光景點介紹，如：浣衣池、埤塘、美食…等。', `organizer`='桃園市政府文化局', `address`='桃園市八德區重慶街36-1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='八塊厝民俗藝術村', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c94426b3240c403d946b', '2025台灣燈會-希望之光—桃園市土地公文化館平安天燈共創展', '希望之光—桃園市土地公文化館平安天燈共創計畫\r\n\r\n每一盞天燈都承載著人們的願望，在夜空中飛舞的光影，象徵著對未來的希望和祈願。「希望之光計畫」邀集了三民里里民、虎爺志工隊以及喜愛藝文的市民朋友，一起創作新版的祈福天燈，透過親手剪裁、組裝、繪畫，將心中的願望化成具象的天燈。一整片共創的天燈閃動著光影的魔力，照亮人們的心靈。燈上的願望隨著微風輕拂翱翔天際，不僅是對美好未來的期盼，也是對現實生活的美好祝福。\r\n\r\n我們希望藉由此活動喚起大眾對傳統文化的共鳴，並在心中種下一顆顆希望的種子，無論面對多大的困難，這些希望之光都將成為我們前行的力量，指引我們迎向光明的未來。\r\n', '桃園市土地公文化館', '桃園市桃園區三民路一段100號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '桃園市土地公文化館', 24.998189, 121.321246, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會-希望之光—桃園市土地公文化館平安天燈共創展', `description`='希望之光—桃園市土地公文化館平安天燈共創計畫\r\n\r\n每一盞天燈都承載著人們的願望，在夜空中飛舞的光影，象徵著對未來的希望和祈願。「希望之光計畫」邀集了三民里里民、虎爺志工隊以及喜愛藝文的市民朋友，一起創作新版的祈福天燈，透過親手剪裁、組裝、繪畫，將心中的願望化成具象的天燈。一整片共創的天燈閃動著光影的魔力，照亮人們的心靈。燈上的願望隨著微風輕拂翱翔天際，不僅是對美好未來的期盼，也是對現實生活的美好祝福。\r\n\r\n我們希望藉由此活動喚起大眾對傳統文化的共鳴，並在心中種下一顆顆希望的種子，無論面對多大的困難，這些希望之光都將成為我們前行的力量，指引我們迎向光明的未來。\r\n', `organizer`='桃園市土地公文化館', `address`='桃園市桃園區三民路一段100號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='桃園市土地公文化館', `latitude`=24.998189, `longitude`=121.321246, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c94426b3240c403d946c', '2025台灣燈會《2025社區共創彩繪燈籠展》', '八塊厝民俗藝術村配合2025台灣燈會，辦理4場社區共創工作坊，並於園區民俗大道展示，展期從113/12/31一路到114/2/28，歡迎大家前來觀賞八德居民手做燈籠，一起迎新春！', '桃園市政府文化局', '桃園市八德區重慶街36-1號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '八塊厝民俗藝術村', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會《2025社區共創彩繪燈籠展》', `description`='八塊厝民俗藝術村配合2025台灣燈會，辦理4場社區共創工作坊，並於園區民俗大道展示，展期從113/12/31一路到114/2/28，歡迎大家前來觀賞八德居民手做燈籠，一起迎新春！', `organizer`='桃園市政府文化局', `address`='桃園市八德區重慶街36-1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='八塊厝民俗藝術村', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c94e26b3240c403d946d', '「百年對話：跨國移動者與臺博館藏的相遇」桃園市立圖書館聯合特展', '桃園市為引入東南亞外籍勞工人數最多的直轄市，本次邀請國立臺灣博物館展出東南亞地區相關藏品，以「藏品與社群連結」為主軸，結合本館的東南亞國家語言藏書，透過「人與物」和「物與書」的連結，展示新住民第一代勇敢地跨越國界，帶著對家族、國家、文化深層的念想，傳承在台灣出生與成長的新住民第二代，共同編織人與物、風土民情、信仰與藝術的故事。\r\n展覽期間包括中秋節和農曆新年，兩大重要傳統節日，在每逢佳節倍思親的時刻，特別以印尼峇里島神獸「巴龍（Barong）」展品(龍也是臺灣重要的文化象徵)進而串起臺灣與新住民母國之連結。\r\n另外，結合桃園分區資源中心辦理一系列相關友善多元族群閱讀推廣活動，藉此開啟多元文化交流與對話，讓各族群在探索及、認識彼此的過程，學會互相尊重彼此的文化差異，並鼓勵新住民、移工與市民朋友，多多利用公共圖書館的資源，讓他/她們看見自身，也能讓自身文化被看見，展現圖書館的文化平權。', '國立臺灣博物館', '桃園市桃園區南平路303號', '2025-01-02 00:00:00', '2025-03-09 00:00:00', '桃園市立圖書館總館', 25.00040024, 121.2996612, '無資料', 'https://www.typl.gov.tw/zh-tw/Activity/Content/6917', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「百年對話：跨國移動者與臺博館藏的相遇」桃園市立圖書館聯合特展', `description`='桃園市為引入東南亞外籍勞工人數最多的直轄市，本次邀請國立臺灣博物館展出東南亞地區相關藏品，以「藏品與社群連結」為主軸，結合本館的東南亞國家語言藏書，透過「人與物」和「物與書」的連結，展示新住民第一代勇敢地跨越國界，帶著對家族、國家、文化深層的念想，傳承在台灣出生與成長的新住民第二代，共同編織人與物、風土民情、信仰與藝術的故事。\r\n展覽期間包括中秋節和農曆新年，兩大重要傳統節日，在每逢佳節倍思親的時刻，特別以印尼峇里島神獸「巴龍（Barong）」展品(龍也是臺灣重要的文化象徵)進而串起臺灣與新住民母國之連結。\r\n另外，結合桃園分區資源中心辦理一系列相關友善多元族群閱讀推廣活動，藉此開啟多元文化交流與對話，讓各族群在探索及、認識彼此的過程，學會互相尊重彼此的文化差異，並鼓勵新住民、移工與市民朋友，多多利用公共圖書館的資源，讓他/她們看見自身，也能讓自身文化被看見，展現圖書館的文化平權。', `organizer`='國立臺灣博物館', `address`='桃園市桃園區南平路303號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='桃園市立圖書館總館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='https://www.typl.gov.tw/zh-tw/Activity/Content/6917', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c95126b3240c403d9470', '無資料', '2/9  《變身少女露比》\r\n\r\n2/23 《汪汪隊立大功》\r\n', '臺南市下營區圖書館', '臺南市下營區文化街117號', '臺南市下營區圖書館', 23.23103978, 120.26484, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='2/9  《變身少女露比》\r\n\r\n2/23 《汪汪隊立大功》\r\n', `organizer`='臺南市下營區圖書館', `address`='臺南市下營區文化街117號', `location`='臺南市下營區圖書館', `latitude`=23.23103978, `longitude`=120.26484, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c95426b3240c403d9471', '藝生向陽—陳來興回顧展', '歲月如歌，生命如畫。經歷了這些，我們更珍惜陳來興老師的每一步，因為它們編織了老師獨一無二的故事。在這些故事中，老師不斷成長、前行。當有一天我們回首時，會發現那些腳印早已鋪就了屬於陳來興老師的人生之路，展現自我，活出精彩。因此，透過這次展出的畫作及仿照陳來興老師的過往畫室及經歷，我們藉由這次展覽一一述說老師精彩的一生。', '慈林教育基金會', '宜蘭縣五結鄉二結路', '2025-03-01 00:00:00', '2025-05-30 00:00:00', '慈林台灣民主運動館', 24.68887343, 121.8058342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝生向陽—陳來興回顧展', `description`='歲月如歌，生命如畫。經歷了這些，我們更珍惜陳來興老師的每一步，因為它們編織了老師獨一無二的故事。在這些故事中，老師不斷成長、前行。當有一天我們回首時，會發現那些腳印早已鋪就了屬於陳來興老師的人生之路，展現自我，活出精彩。因此，透過這次展出的畫作及仿照陳來興老師的過往畫室及經歷，我們藉由這次展覽一一述說老師精彩的一生。', `organizer`='慈林教育基金會', `address`='宜蘭縣五結鄉二結路', `start_date`='2025-03-01 00:00:00', `end_date`='2025-05-30 00:00:00', `location`='慈林台灣民主運動館', `latitude`=24.68887343, `longitude`=121.8058342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c95426b3240c403d9472', '2月份土城圖書館-魔法故事團歡樂說故事', '2/9	貓咪雷弟學游泳\r\n2/16	我是章魚燒，我叫章魚三郎\r\n2/23	2025世界母語日-台語猜燈謎', '臺南市安南區土城圖書館', '臺南市安南區城安路85號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南市安南區土城圖書館', 23.04869681, 120.1526189, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月份土城圖書館-魔法故事團歡樂說故事', `description`='2/9	貓咪雷弟學游泳\r\n2/16	我是章魚燒，我叫章魚三郎\r\n2/23	2025世界母語日-台語猜燈謎', `organizer`='臺南市安南區土城圖書館', `address`='臺南市安南區城安路85號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市安南區土城圖書館', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c95426b3240c403d9473', '駐村藝術家印卡個展 超鵞 ', '印卡\r\n詩人與跨領域藝術創作者。印卡發表了多本詩集和散文集，包括《Rorschach Inkblot》、《一座星系的幾何》等作品。過去曾任英國灣園、新加坡Grey Projects、UNESCO布拉格文學之都駐村作家或藝術家。近年來注意漢字書寫多樣性與東南亞華裔書寫體系與翻譯系統的研究，並將其放在生態關係、地緣政治、冷戰結構或殖民結構中進行相關創作。', '臺南市政府文化局', '臺南市佳里區六安130號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '臺南市蕭壠文化園區', 23.1669941, 120.178593, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='駐村藝術家印卡個展 超鵞 ', `description`='印卡\r\n詩人與跨領域藝術創作者。印卡發表了多本詩集和散文集，包括《Rorschach Inkblot》、《一座星系的幾何》等作品。過去曾任英國灣園、新加坡Grey Projects、UNESCO布拉格文學之都駐村作家或藝術家。近年來注意漢字書寫多樣性與東南亞華裔書寫體系與翻譯系統的研究，並將其放在生態關係、地緣政治、冷戰結構或殖民結構中進行相關創作。', `organizer`='臺南市政府文化局', `address`='臺南市佳里區六安130號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市蕭壠文化園區', `latitude`=23.1669941, `longitude`=120.178593, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c95426b3240c403d9474', '駐村藝術家王耀億個展', '王耀億，臺灣臺南人，畢業於中正大學傳播學系與芝加哥藝術學院(SAIC)電影與新媒體研究所。王耀億的個人創作媒材以實驗敘事影片與錄像藝術為主，並於作品中交織虛構與現實的非線性敘事，以書寫不再被重視的過往，並對照當代時事再現歷史的重複性。曾獲2019年臺北美術獎優選與第22屆台新藝術獎季提名，並於臺北市立美術館與高雄駁二藝術特區舉辦個展，作品展出於臺灣臺北、美國芝加哥與日本橫濱等地。', '臺南市政府文化局', '臺南市佳里區六安130號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '臺南市蕭壠文化園區', 23.1669941, 120.178593, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='駐村藝術家王耀億個展', `description`='王耀億，臺灣臺南人，畢業於中正大學傳播學系與芝加哥藝術學院(SAIC)電影與新媒體研究所。王耀億的個人創作媒材以實驗敘事影片與錄像藝術為主，並於作品中交織虛構與現實的非線性敘事，以書寫不再被重視的過往，並對照當代時事再現歷史的重複性。曾獲2019年臺北美術獎優選與第22屆台新藝術獎季提名，並於臺北市立美術館與高雄駁二藝術特區舉辦個展，作品展出於臺灣臺北、美國芝加哥與日本橫濱等地。', `organizer`='臺南市政府文化局', `address`='臺南市佳里區六安130號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市蕭壠文化園區', `latitude`=23.1669941, `longitude`=120.178593, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c95426b3240c403d9475', '臺南市立圖書館:2月中文說故事', '別再親來親去、送花給你、牙婆婆，我會乖乖刷牙、小小熊和小小影、好棒的假期、元宵喜圓滿、大海、生氣湯、元宵節的故事、123噗嚕嚕、小兔踏踏上學去、真的！這裡沒有鱷魚', '臺南市立圖書館', '臺南市永康區710038 臺南市永康區東橋里康橋大道255號', '2025-02-02 00:00:00', '2025-02-26 00:00:00', '臺南市立圖書館(新總館)', 23.02729532, 120.2542795, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市立圖書館:2月中文說故事', `description`='別再親來親去、送花給你、牙婆婆，我會乖乖刷牙、小小熊和小小影、好棒的假期、元宵喜圓滿、大海、生氣湯、元宵節的故事、123噗嚕嚕、小兔踏踏上學去、真的！這裡沒有鱷魚', `organizer`='臺南市立圖書館', `address`='臺南市永康區710038 臺南市永康區東橋里康橋大道255號', `start_date`='2025-02-02 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='臺南市立圖書館(新總館)', `latitude`=23.02729532, `longitude`=120.2542795, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c95526b3240c403d9476', '駐村藝術家李欣芫個展', '「無字」唱出一歌詩（台文），是轉化《水、土到舌尖》田野（地）探索的階段性創作。\r\n駐村期間我將這幾年陸續開展，仍持續觀察、學習、體驗、實踐的，在《水、土到舌尖》探索裡四個主題：麴和發酵、自然農法、西拉雅語（古謠）、聲音意識，放在一起，聚焦其中的關聯進行創作轉化。\r\n ', '臺南市政府文化局', '臺南市佳里區六安130號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '臺南市蕭壠文化園區', 23.1669941, 120.178593, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='駐村藝術家李欣芫個展', `description`='「無字」唱出一歌詩（台文），是轉化《水、土到舌尖》田野（地）探索的階段性創作。\r\n駐村期間我將這幾年陸續開展，仍持續觀察、學習、體驗、實踐的，在《水、土到舌尖》探索裡四個主題：麴和發酵、自然農法、西拉雅語（古謠）、聲音意識，放在一起，聚焦其中的關聯進行創作轉化。\r\n ', `organizer`='臺南市政府文化局', `address`='臺南市佳里區六安130號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市蕭壠文化園區', `latitude`=23.1669941, `longitude`=120.178593, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c95526b3240c403d9477', '駐村藝術家許維倫與蘇麗平雙人展', '展覽《你們都不用害怕我們所說的話》被視作時間軸上的一個節點，如同一艘於汪洋中不穩定的船隻。我們在這艘船上，凝視著臺灣這座島嶼—其遙遠的「過去」。歷史本身猶如一座島嶼 — 難以捉摸、遙遙遠望。我們的視野—對這個島嶼的視野，就像將我們與之隔開的大海一樣，清而不清。', '臺南市政府文化局', '臺南市佳里區六安130號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '臺南市蕭壠文化園區', 23.1669941, 120.178593, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='駐村藝術家許維倫與蘇麗平雙人展', `description`='展覽《你們都不用害怕我們所說的話》被視作時間軸上的一個節點，如同一艘於汪洋中不穩定的船隻。我們在這艘船上，凝視著臺灣這座島嶼—其遙遠的「過去」。歷史本身猶如一座島嶼 — 難以捉摸、遙遙遠望。我們的視野—對這個島嶼的視野，就像將我們與之隔開的大海一樣，清而不清。', `organizer`='臺南市政府文化局', `address`='臺南市佳里區六安130號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市蕭壠文化園區', `latitude`=23.1669941, `longitude`=120.178593, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c95526b3240c403d9478', '藝術家聯展《無敵翻譯機》The Most Powerful Translator', '《無敵翻譯機》The Most Powerful Translator\r\n圖像、語文在大腦內應用的比例也在因人而異之下，發展出對事物有不同面向的思考切入，因而產生不同思維的表現。也因轉變過程以著循序漸進式的發展，儘管我們很難在當下察覺思維的改變，但透過各自擅長領域的追求及表現下，圖像與語文如同人類進化史的左腦及右腦，分工協力將文明開發並推進。\r\n在這快速變遷的世界，無論是個人與團體的世代用語汰換、訊息傳遞載體更新、事件紀錄的精準，甚至人與人之間的情感思維交流，#圖像的表達才是最無敵的翻譯機。', '臺南市政府文化局', '臺南市佳里區六安130號', '2025-01-01 00:00:00', '2025-06-01 00:00:00', '臺南市蕭壠文化園區', 23.1669941, 120.178593, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝術家聯展《無敵翻譯機》The Most Powerful Translator', `description`='《無敵翻譯機》The Most Powerful Translator\r\n圖像、語文在大腦內應用的比例也在因人而異之下，發展出對事物有不同面向的思考切入，因而產生不同思維的表現。也因轉變過程以著循序漸進式的發展，儘管我們很難在當下察覺思維的改變，但透過各自擅長領域的追求及表現下，圖像與語文如同人類進化史的左腦及右腦，分工協力將文明開發並推進。\r\n在這快速變遷的世界，無論是個人與團體的世代用語汰換、訊息傳遞載體更新、事件紀錄的精準，甚至人與人之間的情感思維交流，#圖像的表達才是最無敵的翻譯機。', `organizer`='臺南市政府文化局', `address`='臺南市佳里區六安130號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='臺南市蕭壠文化園區', `latitude`=23.1669941, `longitude`=120.178593, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c95526b3240c403d9479', '「和通蔣勳書房」開幕大展__金剛經~應無所住', '展品包含了蔣勳老師的手抄金剛經、悉達多油畫與金剛經字畫等作品，曾永玲老師的葉影系列金工作品，以及董承濂老師的「八十八吉祥 - 開悟的勝利幢」及「金剛經 - 應無所住而生其心」作品，展覽自113/11/1至114/6/1止，歡迎大家一起來感受3位老師的作品及金剛經的魅力吧！！', '臺南市政府文化局', '臺南市南區興中街7巷18弄5號', '2025-01-01 00:00:00', '2025-06-01 00:00:00', '水交社文化園區', 22.95561863, 120.1903743, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「和通蔣勳書房」開幕大展__金剛經~應無所住', `description`='展品包含了蔣勳老師的手抄金剛經、悉達多油畫與金剛經字畫等作品，曾永玲老師的葉影系列金工作品，以及董承濂老師的「八十八吉祥 - 開悟的勝利幢」及「金剛經 - 應無所住而生其心」作品，展覽自113/11/1至114/6/1止，歡迎大家一起來感受3位老師的作品及金剛經的魅力吧！！', `organizer`='臺南市政府文化局', `address`='臺南市南區興中街7巷18弄5號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='水交社文化園區', `latitude`=22.95561863, `longitude`=120.1903743, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c95526b3240c403d947a', '柯潤家陶偶創作個展', '柯潤家以陶偶創作，不斷構築出一張張鮮明生動、溫暖心房的人物圖像，充滿對周遭生活的深切關懷與思考，更是對生命的敬畏和多元存在的讚美！', '財團法人竹崎文化藝術基金會', '嘉義縣竹崎鄉坑仔坪93之1號', '2025-02-06 00:00:00', '2025-02-28 00:00:00', '嘉義縣竹崎文教基金會', 23.5167816, 120.5532749, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='柯潤家陶偶創作個展', `description`='柯潤家以陶偶創作，不斷構築出一張張鮮明生動、溫暖心房的人物圖像，充滿對周遭生活的深切關懷與思考，更是對生命的敬畏和多元存在的讚美！', `organizer`='財團法人竹崎文化藝術基金會', `address`='嘉義縣竹崎鄉坑仔坪93之1號', `start_date`='2025-02-06 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='嘉義縣竹崎文教基金會', `latitude`=23.5167816, `longitude`=120.5532749, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c95526b3240c403d947b', '百年宜蘭線．轉動新世紀–113宜蘭線鐵道全線通車百年紀念展', '宜蘭線鐵道（八堵蘇澳間）於1924年12月1日全線通車，作為進出宜蘭的主要交通方式，承載民眾的生活記憶，並帶動沿線鄉鎮邁向新里程。於今屆滿百週年，透過展覽，讓民眾瞭解鐵路興建的過程及通車帶來的變化，為宜蘭線鐵道轉進下一個百年揭開序幕。\r\n展區介紹：\r\n宜蘭線鐵道與創建\r\n鐵道是日本時代臺灣最重要的現代交通工具，讓人與貨物可以快速移動，改變人們的時空概念。本展區呈現宜蘭線鐵道的興建緣由、歷程、工程成就與鐵道設施特色。\r\n宜蘭線鐵道與常民生活\r\n在國道五號通車前，宜蘭線鐵道影響了沿線鄉鎮民眾的生活與產業發展。本展區呈現宜蘭線鐵道開通後，在鐵道車站、月台經常可見的生活場景與產業風情，或是具時代性的鐵道休閒印象。\r\n宜蘭線鐵道與地方觀光\r\n鐵道是日本時代推動觀光產業最重要的交通設施。宜蘭線鐵道沿線風景壯麗，通車之後也帶動沿線城鎮的觀光發展。本展區呈現日本時代鐵道部出版之旅行指南書《臺灣鐵道旅行案內》，看看百年前的人搭火車去哪些地方旅行。\r\n宜蘭線鐵道與藝術表現\r\n宜蘭線鐵道沿線空間變化豐富，河谷、平原、大洋兼備，成為許多藝術創作者的靈感來源或故事場景。本展區呈現日本時代迄今，與宜蘭線鐵道相關且較具代表性之藝術表現。', '宜蘭縣立蘭陽博物館', '宜蘭縣頭城鎮青雲路三段750號', '2025-01-01 00:00:00', '2025-06-07 00:00:00', '宜蘭縣立蘭陽博物館', 24.90075882, 121.845797, '優待票+30;學生票+50;團體票+80;全票+100', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='百年宜蘭線．轉動新世紀–113宜蘭線鐵道全線通車百年紀念展', `description`='宜蘭線鐵道（八堵蘇澳間）於1924年12月1日全線通車，作為進出宜蘭的主要交通方式，承載民眾的生活記憶，並帶動沿線鄉鎮邁向新里程。於今屆滿百週年，透過展覽，讓民眾瞭解鐵路興建的過程及通車帶來的變化，為宜蘭線鐵道轉進下一個百年揭開序幕。\r\n展區介紹：\r\n宜蘭線鐵道與創建\r\n鐵道是日本時代臺灣最重要的現代交通工具，讓人與貨物可以快速移動，改變人們的時空概念。本展區呈現宜蘭線鐵道的興建緣由、歷程、工程成就與鐵道設施特色。\r\n宜蘭線鐵道與常民生活\r\n在國道五號通車前，宜蘭線鐵道影響了沿線鄉鎮民眾的生活與產業發展。本展區呈現宜蘭線鐵道開通後，在鐵道車站、月台經常可見的生活場景與產業風情，或是具時代性的鐵道休閒印象。\r\n宜蘭線鐵道與地方觀光\r\n鐵道是日本時代推動觀光產業最重要的交通設施。宜蘭線鐵道沿線風景壯麗，通車之後也帶動沿線城鎮的觀光發展。本展區呈現日本時代鐵道部出版之旅行指南書《臺灣鐵道旅行案內》，看看百年前的人搭火車去哪些地方旅行。\r\n宜蘭線鐵道與藝術表現\r\n宜蘭線鐵道沿線空間變化豐富，河谷、平原、大洋兼備，成為許多藝術創作者的靈感來源或故事場景。本展區呈現日本時代迄今，與宜蘭線鐵道相關且較具代表性之藝術表現。', `organizer`='宜蘭縣立蘭陽博物館', `address`='宜蘭縣頭城鎮青雲路三段750號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-07 00:00:00', `location`='宜蘭縣立蘭陽博物館', `latitude`=24.90075882, `longitude`=121.845797, `ticket_price`='優待票+30;學生票+50;團體票+80;全票+100', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a7c95526b3240c403d947d', '宜蘭鐵道百年映像–鐵道技手前畑彥太郎攝影展', '鐵道技手前畑彥太郎之父川端喜作於日治初期來臺參與鐵道建設，前畑彥太郎跟隨父親腳步，於1917-1927年任職臺灣總督府鐵道部，1919年調任瑞芳建設事務所擔任工事現場監督員，在參與宜蘭鐵道興築過程拍攝140張宜蘭線鐵道照片，用鏡頭紀錄百年前宜蘭線鐵道風光、興築過程及人員群像，留下珍貴影像紀錄，2023年本館獲贈典藏前畑彥太郎攝影照片全集。\r\n為慶祝宜蘭線鐵道全線通車百年並紀念前畑彥太郎留下的珍貴資產，透過本展與後續教育推廣活動，提供更多人可以目睹珍貴的鐵道映像，使民眾瞭解昔日鐵道興築樣貌，活化文化資產之運用。', '宜蘭縣立蘭陽博物館', '宜蘭縣頭城鎮青雲路三段750號', '2025-01-01 00:00:00', '2025-04-08 00:00:00', '宜蘭縣立蘭陽博物館', 24.90075882, 121.845797, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='宜蘭鐵道百年映像–鐵道技手前畑彥太郎攝影展', `description`='鐵道技手前畑彥太郎之父川端喜作於日治初期來臺參與鐵道建設，前畑彥太郎跟隨父親腳步，於1917-1927年任職臺灣總督府鐵道部，1919年調任瑞芳建設事務所擔任工事現場監督員，在參與宜蘭鐵道興築過程拍攝140張宜蘭線鐵道照片，用鏡頭紀錄百年前宜蘭線鐵道風光、興築過程及人員群像，留下珍貴影像紀錄，2023年本館獲贈典藏前畑彥太郎攝影照片全集。\r\n為慶祝宜蘭線鐵道全線通車百年並紀念前畑彥太郎留下的珍貴資產，透過本展與後續教育推廣活動，提供更多人可以目睹珍貴的鐵道映像，使民眾瞭解昔日鐵道興築樣貌，活化文化資產之運用。', `organizer`='宜蘭縣立蘭陽博物館', `address`='宜蘭縣頭城鎮青雲路三段750號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-08 00:00:00', `location`='宜蘭縣立蘭陽博物館', `latitude`=24.90075882, `longitude`=121.845797, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a869d307f3a329be637c84', '許芯慈 創作個展【自我的版圖】', '⭓ 藝術家介紹\r\n許芯慈，1995年出生於臺南，目前居住於臺北。畢業於國立臺北藝術大學美術系，於荷蘭Frank Mohr Institute 研究所取得藝術碩士。她的創作多以複合媒材、裝置及影像為表現形式，探索遷移者如何將對於空間的身體經驗及記憶，在移居的過程中重新想像與體現。近期，她關注個人身體與周遭物質環境的關係，在勞動與生產的過程中尋找自我的位置。\r\n\r\n⭓ 展覽介紹\r\n本次個展「自我的版圖」觀察跨國遷移者如何透過身體與周遭物質環境的關係來確立自我，並在工作過程中想像自身的位置。展覽以藝術家在荷蘭餐廳打工的經驗為發想，將廚房中的流理臺視為地域與疆界，器皿則是棋，而勞動的過程如同不斷地試探與調整，在重複性的動作中探索，並嘗試建構自我的版圖。藉由廚房物件與遊戲的聯想，重現遷移者在認同形構過程中的無奈與期待，以及他們如何在混雜的場域中協商界線與認同。\r\n\r\n󠀠藝術家專訪➢https://kingcar.pro/en14x6NNf\r\n\r\n⭓ 展覽資訊\r\n許芯慈 創作個展「自我的版圖」\r\nShiu Jui-Tsz Solo Exhibition: Territory of Self\r\n展期：2025.02.11 (二) – 04.02 (三)\r\n開幕：2025.02.22 (六) 14:00\r\n地點：金車文藝中心 承德館\r\n地址：臺北市承德路三段131號\r\n主辦單位：金車文教基金會 / 金車文藝中心KCCA', '財團法人金車文教基金會', '臺北市大同區承德路三段131號', '2025-02-11 00:00:00', '2025-04-02 00:00:00', '金車文藝中心承德館', 25.06342433, 121.5130417, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='許芯慈 創作個展【自我的版圖】', `description`='⭓ 藝術家介紹\r\n許芯慈，1995年出生於臺南，目前居住於臺北。畢業於國立臺北藝術大學美術系，於荷蘭Frank Mohr Institute 研究所取得藝術碩士。她的創作多以複合媒材、裝置及影像為表現形式，探索遷移者如何將對於空間的身體經驗及記憶，在移居的過程中重新想像與體現。近期，她關注個人身體與周遭物質環境的關係，在勞動與生產的過程中尋找自我的位置。\r\n\r\n⭓ 展覽介紹\r\n本次個展「自我的版圖」觀察跨國遷移者如何透過身體與周遭物質環境的關係來確立自我，並在工作過程中想像自身的位置。展覽以藝術家在荷蘭餐廳打工的經驗為發想，將廚房中的流理臺視為地域與疆界，器皿則是棋，而勞動的過程如同不斷地試探與調整，在重複性的動作中探索，並嘗試建構自我的版圖。藉由廚房物件與遊戲的聯想，重現遷移者在認同形構過程中的無奈與期待，以及他們如何在混雜的場域中協商界線與認同。\r\n\r\n󠀠藝術家專訪➢https://kingcar.pro/en14x6NNf\r\n\r\n⭓ 展覽資訊\r\n許芯慈 創作個展「自我的版圖」\r\nShiu Jui-Tsz Solo Exhibition: Territory of Self\r\n展期：2025.02.11 (二) – 04.02 (三)\r\n開幕：2025.02.22 (六) 14:00\r\n地點：金車文藝中心 承德館\r\n地址：臺北市承德路三段131號\r\n主辦單位：金車文教基金會 / 金車文藝中心KCCA', `organizer`='財團法人金車文教基金會', `address`='臺北市大同區承德路三段131號', `start_date`='2025-02-11 00:00:00', `end_date`='2025-04-02 00:00:00', `location`='金車文藝中心承德館', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a91a8226b3240c403d9481', '「113年南投縣客庄地方記憶空間專案輔導團」地方共識說明會-林屋伙房記憶價值', '說到南投客庄的空間保留，大多數人第一個聯想到的會是「林屋伙房」，那您知道林屋伙房過去的生活的型態及建築內每個匾額的由來嗎？林屋伙房位於國姓鄉南港村，是林氏族人於西元1911年來此地狩獵，而後轉為養鹿事業的居所，更曾接待蔣經國等政要，其除保留傳統三合院建築，亦有傳統客家信仰祭祀空間，與南投縣客家移民歷史密切相連。而一百多年前這棟林家所居住的生活空間、其發生的日常故事成為了南投客庄內以家族為主的深刻記憶，同時也是一般人可以瞭解客庄傳統生活痕跡的管道。 \r\n本次說明會將帶領參與者思考，如何將這些記憶空間以多元的方式展示給民眾，讓民眾更深入瞭解客家文化的價值，亦藉由林家後代子嗣的分享，帶領公所、地方組織、民眾等人回到林氏族人的傳統生活，想像過去林屋伙房生活的軌跡，探討地方記憶文化的永續發展和保存。\r\n參加對象：國姓鄉公所及其轄內客家協會、社區組織，以及對客家歷史、空間、文化資源有興趣之民眾、社區組織、地方文史工作者、學者、研究生及地方青年組織等。\r\n報名時間：即日起至114年3月6日(星期四)下午5時止。\r\n報名網址 https://forms.gle/WFgbHsGR9bC85ib4A\r\n\r\n活動流程\r\n14:30-14:40  長官致詞\r\n14:40-15:40  講座：文化資產與觀光的連結\r\n             主講者：林宗德\r\n15:50-16:20  講座：林屋伙房發展故事分享\r\n             主講者：林男彥、林秀霙\r\n16:20-16:30  意見Q&A', '南投縣客家發展所', '南投縣國姓鄉', '2025-03-11 00:00:00', '2025-03-11 00:00:00', '國姓鄉（南投縣）=', 24.03135413, 120.8676052, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「113年南投縣客庄地方記憶空間專案輔導團」地方共識說明會-林屋伙房記憶價值', `description`='說到南投客庄的空間保留，大多數人第一個聯想到的會是「林屋伙房」，那您知道林屋伙房過去的生活的型態及建築內每個匾額的由來嗎？林屋伙房位於國姓鄉南港村，是林氏族人於西元1911年來此地狩獵，而後轉為養鹿事業的居所，更曾接待蔣經國等政要，其除保留傳統三合院建築，亦有傳統客家信仰祭祀空間，與南投縣客家移民歷史密切相連。而一百多年前這棟林家所居住的生活空間、其發生的日常故事成為了南投客庄內以家族為主的深刻記憶，同時也是一般人可以瞭解客庄傳統生活痕跡的管道。 \r\n本次說明會將帶領參與者思考，如何將這些記憶空間以多元的方式展示給民眾，讓民眾更深入瞭解客家文化的價值，亦藉由林家後代子嗣的分享，帶領公所、地方組織、民眾等人回到林氏族人的傳統生活，想像過去林屋伙房生活的軌跡，探討地方記憶文化的永續發展和保存。\r\n參加對象：國姓鄉公所及其轄內客家協會、社區組織，以及對客家歷史、空間、文化資源有興趣之民眾、社區組織、地方文史工作者、學者、研究生及地方青年組織等。\r\n報名時間：即日起至114年3月6日(星期四)下午5時止。\r\n報名網址 https://forms.gle/WFgbHsGR9bC85ib4A\r\n\r\n活動流程\r\n14:30-14:40  長官致詞\r\n14:40-15:40  講座：文化資產與觀光的連結\r\n             主講者：林宗德\r\n15:50-16:20  講座：林屋伙房發展故事分享\r\n             主講者：林男彥、林秀霙\r\n16:20-16:30  意見Q&A', `organizer`='南投縣客家發展所', `address`='南投縣國姓鄉', `start_date`='2025-03-11 00:00:00', `end_date`='2025-03-11 00:00:00', `location`='國姓鄉（南投縣）=', `latitude`=24.03135413, `longitude`=120.8676052, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a9723907f3a329be637c85', '生命故事輕鬆聊 心理課程', '生命故事就在生活中流動著\r\n如何彙整生命故事，讓往後過得更精彩\r\n定期地透過生命故事 ——來認識自己\r\n也可以聽聽他人的故事\r\n-\r\n2/12 關係系列—友情中的情與義\r\n● 梳理生命經驗中的人際關係脈絡\r\n● 從他人的眼中聚合自己的樣貌\r\n-\r\n2/19 關係系列—愛情中的愛恨交織\r\n● 回顧生命中愛情的大小故事。\r\n● 認識自己關於愛、情緒與互動的模式\r\n-\r\n2/26 關係系列—家庭中酸甜苦處\r\n● 探索生命故事中原生家庭/新建家庭的經驗與關係\r\n● 重新建立與自己連結，與自己對話\r\n-\r\n【課程資訊】\r\n主辦單位：和泰純青基金會\r\n課程網址：https://reurl.cc/O5Gdpv\r\n授課講師：陳彥融 諮商心理師\r\n課程地址：臺北市松山區光復北路190巷35號2樓\r\n#心理 #生命故事', '和泰純青基金會', '臺北市松山區光復北路190巷35號2樓', '2025-02-26 00:00:00', '2025-02-26 00:00:00', '和泰純青基金會', 25.05999101, 121.5575876, '課程費用：900元\r\n單堂費用：350元', 'https://www.chun-ching.org.tw/lesson/family_lesson/241', '[]') ON DUPLICATE KEY UPDATE `activity_name`='生命故事輕鬆聊 心理課程', `description`='生命故事就在生活中流動著\r\n如何彙整生命故事，讓往後過得更精彩\r\n定期地透過生命故事 ——來認識自己\r\n也可以聽聽他人的故事\r\n-\r\n2/12 關係系列—友情中的情與義\r\n● 梳理生命經驗中的人際關係脈絡\r\n● 從他人的眼中聚合自己的樣貌\r\n-\r\n2/19 關係系列—愛情中的愛恨交織\r\n● 回顧生命中愛情的大小故事。\r\n● 認識自己關於愛、情緒與互動的模式\r\n-\r\n2/26 關係系列—家庭中酸甜苦處\r\n● 探索生命故事中原生家庭/新建家庭的經驗與關係\r\n● 重新建立與自己連結，與自己對話\r\n-\r\n【課程資訊】\r\n主辦單位：和泰純青基金會\r\n課程網址：https://reurl.cc/O5Gdpv\r\n授課講師：陳彥融 諮商心理師\r\n課程地址：臺北市松山區光復北路190巷35號2樓\r\n#心理 #生命故事', `organizer`='和泰純青基金會', `address`='臺北市松山區光復北路190巷35號2樓', `start_date`='2025-02-26 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='和泰純青基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='課程費用：900元\r\n單堂費用：350元', `source_url`='https://www.chun-ching.org.tw/lesson/family_lesson/241', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a9774e8f15d8562cfcd6d0', '【免費公益講座】我們的關係健檢', '三月週四 19:00-20:50 以婚姻、感情為主題的講座\r\n適合對象\r\n※想增進親密關係的你\r\n※想修復親密關係的你\r\n※想改善溝通模式的你\r\n※面對親密關係感到不安的你\r\n-\r\n3/6 打開心扉的鑰匙—增進親密關係的秘方\r\n張宇傑 諮商心理師\r\n1、認識親密關係地雷\r\n2、如何慎重排除地雷\r\n本場次講座為「行動式講座」，將透過學員間的分享討論以及經驗式的活動，進行本講座的個人深入探索與覺察，以更貼切回應自身需求，並一起學習和成長。\r\n-\r\n3/13 幸福保衛站—關係品質的檢視與修復\r\n詹惠文 諮商心理師\r\n你在感情中，是否有感覺到你跟另一半關係疏離或常常吵架呢？\r\n透過講座，針對你的婚姻與感情健檢，看看在你們的關係裡，出現哪些不良的警訊？又有什麼方式可以改善？\r\n並談談遇到外遇時，可以怎麼面對、處理跟修復關係。\r\n-\r\n3/20 我們怎麼了？翻轉關係的互動練習！\r\n蔡秀娟 諮商心理師\r\n1、看見彼此溝通模式帶來的影響\r\n2、發現關係中NG的溝通\r\n3、重拾關係品質的四方法\r\n-\r\n3/27 揮別焦慮不安的愛情—親密關係衝突與和解\r\n張宇傑 諮商心理師\r\n1、探索為何在親密關係中如此焦慮不安\r\n2、健康的親密關係經營與溝通策略\r\n本場次為「行動式講座」，將透過學員間的分享討論以及經驗式的活動，進行本講座的個人深入探索與覺察，以更貼切回應自身需求，並一起學習和成長。', '和泰純青基金會', '臺北市松山區光復北路190巷35號2樓', '2025-03-06 00:00:00', '2025-03-06 00:00:00', '和泰純青基金會', 25.05999101, 121.5575876, '無資料', 'https://www.chun-ching.org.tw/lesson/family_lesson/247', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【免費公益講座】我們的關係健檢', `description`='三月週四 19:00-20:50 以婚姻、感情為主題的講座\r\n適合對象\r\n※想增進親密關係的你\r\n※想修復親密關係的你\r\n※想改善溝通模式的你\r\n※面對親密關係感到不安的你\r\n-\r\n3/6 打開心扉的鑰匙—增進親密關係的秘方\r\n張宇傑 諮商心理師\r\n1、認識親密關係地雷\r\n2、如何慎重排除地雷\r\n本場次講座為「行動式講座」，將透過學員間的分享討論以及經驗式的活動，進行本講座的個人深入探索與覺察，以更貼切回應自身需求，並一起學習和成長。\r\n-\r\n3/13 幸福保衛站—關係品質的檢視與修復\r\n詹惠文 諮商心理師\r\n你在感情中，是否有感覺到你跟另一半關係疏離或常常吵架呢？\r\n透過講座，針對你的婚姻與感情健檢，看看在你們的關係裡，出現哪些不良的警訊？又有什麼方式可以改善？\r\n並談談遇到外遇時，可以怎麼面對、處理跟修復關係。\r\n-\r\n3/20 我們怎麼了？翻轉關係的互動練習！\r\n蔡秀娟 諮商心理師\r\n1、看見彼此溝通模式帶來的影響\r\n2、發現關係中NG的溝通\r\n3、重拾關係品質的四方法\r\n-\r\n3/27 揮別焦慮不安的愛情—親密關係衝突與和解\r\n張宇傑 諮商心理師\r\n1、探索為何在親密關係中如此焦慮不安\r\n2、健康的親密關係經營與溝通策略\r\n本場次為「行動式講座」，將透過學員間的分享討論以及經驗式的活動，進行本講座的個人深入探索與覺察，以更貼切回應自身需求，並一起學習和成長。', `organizer`='和泰純青基金會', `address`='臺北市松山區光復北路190巷35號2樓', `start_date`='2025-03-06 00:00:00', `end_date`='2025-03-06 00:00:00', `location`='和泰純青基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='https://www.chun-ching.org.tw/lesson/family_lesson/247', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a978498f15d8562cfcd6d1', '【免費公益講座】孩子的情緒教育不能等', '三月週二 19:00-20:50 以親職教養為主題的講座\r\n適合對象：\r\n※想學習如何培養孩子同理心的你\r\n※想知道如何陪伴孩子面對挫折的你\r\n※想學習如何和青少年溝通的你\r\n-\r\n3/4 情緒共感—談同理心對親子情緒互動的升溫感\r\n郭蕙寧 諮商心理師\r\n適合對象：0-12歲孩子的家長\r\n同理心是孩子感到幸福的關鍵之一。同理心的內涵不單是對自我與他人情緒感受的體察，還有對道德的判斷、周遭人事物的關懷，是培養情緒EQ能力的重要指標。孩子最初的同理心，來自於家庭與親子間的互動，情緒教養心理師與您分享，陪伴孩子滋養出一輩子受用的同理心能力。\r\n-\r\n3/11 當孩子的神隊友—陪伴孩子走出失落的情緒\r\n柯宥璿 諮商心理師\r\n適合對象：6-15歲孩子的家長\r\n講座大綱：人生難免會遇到不順意的事，而當孩子因為受挫而失\r\n落時，大人的應對方式也影響著孩子未來面對挫折的態度。好好面對孩子的情緒，就能將危機化成轉機。\r\n在這場講座中，我們將帶你深入了解：\r\n1、從生理、心理及社會各角度來看待孩子的情緒\r\n2、如何提升孩子辨識、表達及運用情緒的能力\r\n3、如何適當回應孩子的負面情緒\r\n-\r\n3/18 與青少年談情緒說愛意\r\n張宇傑 諮商心理師\r\n適合對象：13-18歲孩子的家長\r\n1、認識青少年情緒與發展\r\n2、創造溫柔又溫柔不失堅定的溝通\r\n本場次為「行動式講座」，將透過學員間的分享討論以及經驗式的活動，進行本講座的個人深入探索與覺察，以更貼切回應自身需求，並一起學習和成長。\r\n-\r\n3/25 親職教育情緒教育—培養孩子的挫折耐受力\r\n石麗君 諮商心理師\r\n適合對象：0~8歲孩子的家長\r\n1、 孩子的個體化～孩子得發展階段\r\n2、倒底是愛還是害\r\n3、家有小霸王～噴火龍\r\n4、面對固執、很拗、情緒張力很大的孩子怎麼辦\r\n5、如何培養挫折耐受力\r\n-\r\n\r\n本系列講座規劃的主要聽眾為家長，較不適合帶小孩參加', '和泰純青基金會', '臺北市松山區光復北路190巷35號2樓', '2025-03-04 00:00:00', '2025-03-04 00:00:00', '和泰純青基金會', 25.05999101, 121.5575876, '無資料', 'https://www.chun-ching.org.tw/lesson/family_lesson/249', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【免費公益講座】孩子的情緒教育不能等', `description`='三月週二 19:00-20:50 以親職教養為主題的講座\r\n適合對象：\r\n※想學習如何培養孩子同理心的你\r\n※想知道如何陪伴孩子面對挫折的你\r\n※想學習如何和青少年溝通的你\r\n-\r\n3/4 情緒共感—談同理心對親子情緒互動的升溫感\r\n郭蕙寧 諮商心理師\r\n適合對象：0-12歲孩子的家長\r\n同理心是孩子感到幸福的關鍵之一。同理心的內涵不單是對自我與他人情緒感受的體察，還有對道德的判斷、周遭人事物的關懷，是培養情緒EQ能力的重要指標。孩子最初的同理心，來自於家庭與親子間的互動，情緒教養心理師與您分享，陪伴孩子滋養出一輩子受用的同理心能力。\r\n-\r\n3/11 當孩子的神隊友—陪伴孩子走出失落的情緒\r\n柯宥璿 諮商心理師\r\n適合對象：6-15歲孩子的家長\r\n講座大綱：人生難免會遇到不順意的事，而當孩子因為受挫而失\r\n落時，大人的應對方式也影響著孩子未來面對挫折的態度。好好面對孩子的情緒，就能將危機化成轉機。\r\n在這場講座中，我們將帶你深入了解：\r\n1、從生理、心理及社會各角度來看待孩子的情緒\r\n2、如何提升孩子辨識、表達及運用情緒的能力\r\n3、如何適當回應孩子的負面情緒\r\n-\r\n3/18 與青少年談情緒說愛意\r\n張宇傑 諮商心理師\r\n適合對象：13-18歲孩子的家長\r\n1、認識青少年情緒與發展\r\n2、創造溫柔又溫柔不失堅定的溝通\r\n本場次為「行動式講座」，將透過學員間的分享討論以及經驗式的活動，進行本講座的個人深入探索與覺察，以更貼切回應自身需求，並一起學習和成長。\r\n-\r\n3/25 親職教育情緒教育—培養孩子的挫折耐受力\r\n石麗君 諮商心理師\r\n適合對象：0~8歲孩子的家長\r\n1、 孩子的個體化～孩子得發展階段\r\n2、倒底是愛還是害\r\n3、家有小霸王～噴火龍\r\n4、面對固執、很拗、情緒張力很大的孩子怎麼辦\r\n5、如何培養挫折耐受力\r\n-\r\n\r\n本系列講座規劃的主要聽眾為家長，較不適合帶小孩參加', `organizer`='和泰純青基金會', `address`='臺北市松山區光復北路190巷35號2樓', `start_date`='2025-03-04 00:00:00', `end_date`='2025-03-04 00:00:00', `location`='和泰純青基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='https://www.chun-ching.org.tw/lesson/family_lesson/249', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a978fd8f15d8562cfcd6d2', '【免費公益講座】姻親關係面面觀', '三月週五 19:00-20:50 以家庭為主題的講座\r\n適合對象：\r\n※不擅長與姻親相處的你\r\n※想改善婆媳關係的妳\r\n※想與另一半一同改善家庭氣氛的你\r\n-\r\n3/7 如何與另一半的家人相處？\r\n石麗君 諮商心理師\r\n1、結婚怎麼有怎麼多事\r\n個體內在（認知、行為、情緒、生理）－人際（關係）－系統（家庭、親密法律）－文化\r\n2、婚姻中的佛地魔\r\n婚姻的癌症是外遇：我很痛，我要不要跟雙方的家庭長輩說？\r\n你（妳）每個假日都回你媽家，那我算什麼？\r\n為何假日都要跟你（妳）爸媽together啊\r\n你知道我很討厭你家的姊姊（大嫂、哥哥）嗎？\r\n你爸媽這麼寵小孩，這樣我怎麼教小孩，你能不能去跟你爸媽講啊\r\n知道你（妳）家人介入我們之間很多嗎？\r\n3、家庭人際與關係修復\r\n喪偶的悲傷失落\r\n家有疾病兒\r\n家有拒學兒\r\n-\r\n3/14 都很糟，選沒那麼糟一點的吧！(婆媳相處之道)\r\n張宇傑 諮商心理師\r\n1、淺談台灣文化下婆媳關係的困境\r\n2、找到婆媳相處扣分最少的選擇\r\n-\r\n3/21 婆媳相處的黃金距離美學\r\n羅迦馨 諮商心理師\r\n1、學習設立健康界限，減少誤會與衝突。\r\n2、掌握溝通技巧，促進婆媳關係的理解與和諧。\r\n3、強化夫妻合作，共同建立良好家庭相處氛圍。\r\n-\r\n3/28 尋找與伴侶家人相處的最大公約數\r\n謝暉明 諮商心理師\r\n台灣的婚姻觀念，逐漸由「父子軸」轉為「夫妻軸」，一部份承繼了固有傳統文化，一部分更重視自我與平權。在這新舊交鋒的過渡階段，與伴侶家人相處如何創造共贏？在大家庭、婚姻與個人之間如何保持平衡？所謂知己知彼、百戰不殆，若能有所洞察和準備，更能好整以暇、輕鬆應對。即使已經進入婚姻並遇到問題，打算調整，還是有機會。\r\n', '和泰純青基金會', '臺北市松山區光復北路190巷35號2樓', '2025-03-07 00:00:00', '2025-03-07 00:00:00', '和泰純青基金會', 25.05999101, 121.5575876, '無資料', 'https://www.chun-ching.org.tw/lesson/family_lesson/251', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【免費公益講座】姻親關係面面觀', `description`='三月週五 19:00-20:50 以家庭為主題的講座\r\n適合對象：\r\n※不擅長與姻親相處的你\r\n※想改善婆媳關係的妳\r\n※想與另一半一同改善家庭氣氛的你\r\n-\r\n3/7 如何與另一半的家人相處？\r\n石麗君 諮商心理師\r\n1、結婚怎麼有怎麼多事\r\n個體內在（認知、行為、情緒、生理）－人際（關係）－系統（家庭、親密法律）－文化\r\n2、婚姻中的佛地魔\r\n婚姻的癌症是外遇：我很痛，我要不要跟雙方的家庭長輩說？\r\n你（妳）每個假日都回你媽家，那我算什麼？\r\n為何假日都要跟你（妳）爸媽together啊\r\n你知道我很討厭你家的姊姊（大嫂、哥哥）嗎？\r\n你爸媽這麼寵小孩，這樣我怎麼教小孩，你能不能去跟你爸媽講啊\r\n知道你（妳）家人介入我們之間很多嗎？\r\n3、家庭人際與關係修復\r\n喪偶的悲傷失落\r\n家有疾病兒\r\n家有拒學兒\r\n-\r\n3/14 都很糟，選沒那麼糟一點的吧！(婆媳相處之道)\r\n張宇傑 諮商心理師\r\n1、淺談台灣文化下婆媳關係的困境\r\n2、找到婆媳相處扣分最少的選擇\r\n-\r\n3/21 婆媳相處的黃金距離美學\r\n羅迦馨 諮商心理師\r\n1、學習設立健康界限，減少誤會與衝突。\r\n2、掌握溝通技巧，促進婆媳關係的理解與和諧。\r\n3、強化夫妻合作，共同建立良好家庭相處氛圍。\r\n-\r\n3/28 尋找與伴侶家人相處的最大公約數\r\n謝暉明 諮商心理師\r\n台灣的婚姻觀念，逐漸由「父子軸」轉為「夫妻軸」，一部份承繼了固有傳統文化，一部分更重視自我與平權。在這新舊交鋒的過渡階段，與伴侶家人相處如何創造共贏？在大家庭、婚姻與個人之間如何保持平衡？所謂知己知彼、百戰不殆，若能有所洞察和準備，更能好整以暇、輕鬆應對。即使已經進入婚姻並遇到問題，打算調整，還是有機會。\r\n', `organizer`='和泰純青基金會', `address`='臺北市松山區光復北路190巷35號2樓', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-07 00:00:00', `location`='和泰純青基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='https://www.chun-ching.org.tw/lesson/family_lesson/251', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a997d28f15d8562cfcd6d3', '心能量寫書法', '從揮筆運轉去體會心態上的平靜及流動，\r\n在筆觸之下培養寧靜和諧的心，練字亦養心，\r\n可訓練耐心、專注力，亦達到收心、安心、修心的效果。\r\n-\r\n\r\n【課程資訊】\r\n授課講師：林子琪老師\r\n報名時間：隨時\r\n上課堂數：一期八堂，可請假兩堂\r\n課程日期：1/16、1/23、2/6、2/13、2/20、2/27、3/6、3/13，14:30-16:30\r\n課程費用：2400元\r\n單堂費用：350元\r\n最低開課人數：8人\r\n用具自備(毛筆、墨汁、硯台、九宮格紙)', '和泰純青基金會', '臺北市松山區光復北路190巷35號2樓', '2025-02-27 00:00:00', '2025-02-27 00:00:00', '和泰純青基金會', 25.05999101, 121.5575876, '課程費用：2400元\r\n單堂費用：350元', 'https://www.chun-ching.org.tw/lesson/family_lesson/242', '[]') ON DUPLICATE KEY UPDATE `activity_name`='心能量寫書法', `description`='從揮筆運轉去體會心態上的平靜及流動，\r\n在筆觸之下培養寧靜和諧的心，練字亦養心，\r\n可訓練耐心、專注力，亦達到收心、安心、修心的效果。\r\n-\r\n\r\n【課程資訊】\r\n授課講師：林子琪老師\r\n報名時間：隨時\r\n上課堂數：一期八堂，可請假兩堂\r\n課程日期：1/16、1/23、2/6、2/13、2/20、2/27、3/6、3/13，14:30-16:30\r\n課程費用：2400元\r\n單堂費用：350元\r\n最低開課人數：8人\r\n用具自備(毛筆、墨汁、硯台、九宮格紙)', `organizer`='和泰純青基金會', `address`='臺北市松山區光復北路190巷35號2樓', `start_date`='2025-02-27 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='和泰純青基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='課程費用：2400元\r\n單堂費用：350元', `source_url`='https://www.chun-ching.org.tw/lesson/family_lesson/242', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a998c58f15d8562cfcd6d4', '【免費公益講座】職場適應力', '三月週三19:00-20:50 以職場為主題的講座\r\n適合對象\r\n※想增加職場適應力的你\r\n※想學習適應新職場環境的你\r\n※想找尋最自在的工作模式的你\r\n※想要在職場有好表現的你\r\n-\r\n3/5 職場適應力：在變動中找到穩定\r\n吳天慈 諮商心理師\r\n環境變動對我們的影響可大可小，此講座我們將聚焦如何提高職場環境的「適應力」，除了介紹適應力的概念，我也會提供具體的應對策略，協助各位建立適應新環境的心理彈性，讓大家不論在轉職潮、晉升或職務變動中皆能順利過渡與調整。\r\n-\r\n3/12 重新定再出發，開啟職場新篇章\r\n張蓓雯 諮商心理師\r\n職場斷捨離：從「遺憾」到「釋然」\r\n培養心理韌性：到職前的準備\r\n建立職場角色與定位：讓優勢發光發熱\r\n-\r\n3/19 破解職場內耗，找到最自在的工作模式\r\n蔡柏堯 諮商心理師\r\n面對不同的職場總是令人身心憔悴，「安靜離職 」少做少錯成為職場新常態。\r\n工作變成只是為了生活而做，少了成就感，越做越迷惘，究竟為什麼那麼容易感到心累疲憊，自我內耗嚴重？\r\n讓我們一起從榮格心理學角度，探索自己的職場「原型」故事，活出最自在的職場人生。\r\n-\r\n3/26 突破自我懷疑：在主管期待中展現最佳表現\r\n曹國璽 諮商心理師\r\n1、洞悉壓力根源：釋放重擔\r\n2、破解慣性模式的惡性循環\r\n3、成為掌握人生價值的舵手\r\n4、開啟成為想要的自己航程', '和泰純青基金會', '臺北市松山區光復北路190巷35號2樓', '2025-03-05 00:00:00', '2025-03-05 00:00:00', '和泰純青基金會', 25.05999101, 121.5575876, '無資料', 'https://www.chun-ching.org.tw/lesson/family_lesson/246', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【免費公益講座】職場適應力', `description`='三月週三19:00-20:50 以職場為主題的講座\r\n適合對象\r\n※想增加職場適應力的你\r\n※想學習適應新職場環境的你\r\n※想找尋最自在的工作模式的你\r\n※想要在職場有好表現的你\r\n-\r\n3/5 職場適應力：在變動中找到穩定\r\n吳天慈 諮商心理師\r\n環境變動對我們的影響可大可小，此講座我們將聚焦如何提高職場環境的「適應力」，除了介紹適應力的概念，我也會提供具體的應對策略，協助各位建立適應新環境的心理彈性，讓大家不論在轉職潮、晉升或職務變動中皆能順利過渡與調整。\r\n-\r\n3/12 重新定再出發，開啟職場新篇章\r\n張蓓雯 諮商心理師\r\n職場斷捨離：從「遺憾」到「釋然」\r\n培養心理韌性：到職前的準備\r\n建立職場角色與定位：讓優勢發光發熱\r\n-\r\n3/19 破解職場內耗，找到最自在的工作模式\r\n蔡柏堯 諮商心理師\r\n面對不同的職場總是令人身心憔悴，「安靜離職 」少做少錯成為職場新常態。\r\n工作變成只是為了生活而做，少了成就感，越做越迷惘，究竟為什麼那麼容易感到心累疲憊，自我內耗嚴重？\r\n讓我們一起從榮格心理學角度，探索自己的職場「原型」故事，活出最自在的職場人生。\r\n-\r\n3/26 突破自我懷疑：在主管期待中展現最佳表現\r\n曹國璽 諮商心理師\r\n1、洞悉壓力根源：釋放重擔\r\n2、破解慣性模式的惡性循環\r\n3、成為掌握人生價值的舵手\r\n4、開啟成為想要的自己航程', `organizer`='和泰純青基金會', `address`='臺北市松山區光復北路190巷35號2樓', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='和泰純青基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='https://www.chun-ching.org.tw/lesson/family_lesson/246', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a99a138f15d8562cfcd6d5', '【免費公益講座】樂學翻轉 — 生命心靈的饗宴', '三月週二 9:30-11:30\r\n心靈也和身體一樣需要同樣的照顧、治療與保健，持續樂齡族注重心理健康\r\n-\r\n三月份邀請到諮商心理師、臨床心理師，透過講師們專業的講解，讓學員更能面對銀髮、樂齡的生活。\r\n-\r\n3/4 以榮格心理學看待生命意義與邁向轉化\r\n蔡柏堯 諮商心理師\r\n古人說：三十而立、四十不惑、五十知天命；是古人中晚年省思自己人生，在心靈上安身立命的方式。\r\n現代醫療進步延長壽命，心靈上卻沒人告訴人們該如何過日子，暮遲之年後漸漸出現慌恐、不安，\r\n偉大的心理學家榮格，一生致力於探索人類潛意識，為迷惘的心靈點一盞黑暗之光，找到心靈歸宿，讓心靈得以整合、寧靜。\r\n你活出自己的神話了嗎？感知自己的天命(SELF)了嗎？\r\n一起聽聽看榮格心理學如何理解生命的意義與轉化。\r\n-\r\n3/11 樂齡婚姻的「心」方向\r\n洪培芸 臨床心理師\r\n如果伴侶不改變，總是壞脾氣，你可以為自己做什麼事？從自己能夠做的部分開始著手，無需盼望、等候伴侶有朝一日能改善脾氣及調整行為。開始將人生的重心從外在轉向內在，從伴侶的身上移到自己。當你開始為了興趣開始學習與進修，願意走出去結交新朋友，自然也減少了和伴侶在家中大眼瞪小眼的機會。持續探索什麼是你的真心所愛，持續去做熱愛的事，生活就會源源不斷地注入活水。假以時日，你能感染你身邊所有你在乎、你關心的人，一起活好人生。\r\n-\r\n3/18 隨著生命的流動，你的心還在當下嗎？\r\n黃意茜 臨床心理師\r\n◆ 生命的流動與當下的意義\r\n◆ 腦：我們都在自動導航嗎？\r\n◆ 心：不必要的重量\r\n◆ 身：你與自己的感受有多靠近？\r\n◆ 與自己締結「當下的約定」\r\n-\r\n3/25 冬去春來，心靈也需要換季\r\n吳天慈 諮商心理師\r\n三月，入春之際，在這場講座中，我們將一起聊聊：季節轉換對心理造成的影響，透過一些小方法協助我們辨認心情上的變化、學習與之共處，也讓我們一起設立小目標，重新展現生命的春暖花開。', '和泰純青基金會', '臺北市松山區光復北路190巷35號2樓', '2025-03-04 00:00:00', '2025-03-04 00:00:00', '和泰純青基金會', 25.05999101, 121.5575876, '無資料', 'https://www.chun-ching.org.tw/lesson/family_lesson/244', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【免費公益講座】樂學翻轉 — 生命心靈的饗宴', `description`='三月週二 9:30-11:30\r\n心靈也和身體一樣需要同樣的照顧、治療與保健，持續樂齡族注重心理健康\r\n-\r\n三月份邀請到諮商心理師、臨床心理師，透過講師們專業的講解，讓學員更能面對銀髮、樂齡的生活。\r\n-\r\n3/4 以榮格心理學看待生命意義與邁向轉化\r\n蔡柏堯 諮商心理師\r\n古人說：三十而立、四十不惑、五十知天命；是古人中晚年省思自己人生，在心靈上安身立命的方式。\r\n現代醫療進步延長壽命，心靈上卻沒人告訴人們該如何過日子，暮遲之年後漸漸出現慌恐、不安，\r\n偉大的心理學家榮格，一生致力於探索人類潛意識，為迷惘的心靈點一盞黑暗之光，找到心靈歸宿，讓心靈得以整合、寧靜。\r\n你活出自己的神話了嗎？感知自己的天命(SELF)了嗎？\r\n一起聽聽看榮格心理學如何理解生命的意義與轉化。\r\n-\r\n3/11 樂齡婚姻的「心」方向\r\n洪培芸 臨床心理師\r\n如果伴侶不改變，總是壞脾氣，你可以為自己做什麼事？從自己能夠做的部分開始著手，無需盼望、等候伴侶有朝一日能改善脾氣及調整行為。開始將人生的重心從外在轉向內在，從伴侶的身上移到自己。當你開始為了興趣開始學習與進修，願意走出去結交新朋友，自然也減少了和伴侶在家中大眼瞪小眼的機會。持續探索什麼是你的真心所愛，持續去做熱愛的事，生活就會源源不斷地注入活水。假以時日，你能感染你身邊所有你在乎、你關心的人，一起活好人生。\r\n-\r\n3/18 隨著生命的流動，你的心還在當下嗎？\r\n黃意茜 臨床心理師\r\n◆ 生命的流動與當下的意義\r\n◆ 腦：我們都在自動導航嗎？\r\n◆ 心：不必要的重量\r\n◆ 身：你與自己的感受有多靠近？\r\n◆ 與自己締結「當下的約定」\r\n-\r\n3/25 冬去春來，心靈也需要換季\r\n吳天慈 諮商心理師\r\n三月，入春之際，在這場講座中，我們將一起聊聊：季節轉換對心理造成的影響，透過一些小方法協助我們辨認心情上的變化、學習與之共處，也讓我們一起設立小目標，重新展現生命的春暖花開。', `organizer`='和泰純青基金會', `address`='臺北市松山區光復北路190巷35號2樓', `start_date`='2025-03-04 00:00:00', `end_date`='2025-03-04 00:00:00', `location`='和泰純青基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='https://www.chun-ching.org.tw/lesson/family_lesson/244', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a99bca8f15d8562cfcd6d6', '【免費公益講座】健康新知簡單學 — 順應天時的養生之道', '三月週五 9:30-11:30 以健康為主題的講座\r\n健康新知簡單學系列講座邀請專業講師向大家介紹各種健康、營養等主題的新知，希望每個人上完講座能學習到健康新知，讓生活更美好！\r\n-\r\n三月的主題為「順應天時的養生之道」，請到中醫師為大家講解，讓大家過得更健康，歡迎大家踴躍參加！\r\n-\r\n3/7 驚蟄後的活力增強食療\r\n許祐瑄 中醫師\r\n1、驚蟄與春夏養陽的觀點\r\n2、養陽的飲食原則和中藥食療應用\r\n3、只要貼穴位就可以保存陽氣？三伏貼解密\r\n-\r\n3/14 春養肝脾好時機\r\n許祐瑄 中醫師\r\n1、春季與肝、脾有何相關？\r\n2、春日鬱悶、眼睛乾澀的調養\r\n3、疏理肝氣的養生藥膳茶飲\r\n-\r\n3/21 春分除濕平肝氣\r\n許祐瑄 中醫師\r\n1、春分養生重健脾去濕\r\n2、防春睏、降肝火的養生茶飲\r\n3、養肝緩解春天換季皮膚癢\r\n-\r\n3/28 常見的春季疾病\r\n許祐瑄 中醫師\r\n1、春日中風高發如何預防\r\n2、春季過敏怎麼辦\r\n3、樂齡的食養天真', '和泰純青基金會', '臺北市松山區光復北路190巷35號2樓', '2025-03-07 00:00:00', '2025-03-07 00:00:00', '和泰純青基金會', 25.05999101, 121.5575876, '無資料', 'https://www.chun-ching.org.tw/lesson/family_lesson/248', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【免費公益講座】健康新知簡單學 — 順應天時的養生之道', `description`='三月週五 9:30-11:30 以健康為主題的講座\r\n健康新知簡單學系列講座邀請專業講師向大家介紹各種健康、營養等主題的新知，希望每個人上完講座能學習到健康新知，讓生活更美好！\r\n-\r\n三月的主題為「順應天時的養生之道」，請到中醫師為大家講解，讓大家過得更健康，歡迎大家踴躍參加！\r\n-\r\n3/7 驚蟄後的活力增強食療\r\n許祐瑄 中醫師\r\n1、驚蟄與春夏養陽的觀點\r\n2、養陽的飲食原則和中藥食療應用\r\n3、只要貼穴位就可以保存陽氣？三伏貼解密\r\n-\r\n3/14 春養肝脾好時機\r\n許祐瑄 中醫師\r\n1、春季與肝、脾有何相關？\r\n2、春日鬱悶、眼睛乾澀的調養\r\n3、疏理肝氣的養生藥膳茶飲\r\n-\r\n3/21 春分除濕平肝氣\r\n許祐瑄 中醫師\r\n1、春分養生重健脾去濕\r\n2、防春睏、降肝火的養生茶飲\r\n3、養肝緩解春天換季皮膚癢\r\n-\r\n3/28 常見的春季疾病\r\n許祐瑄 中醫師\r\n1、春日中風高發如何預防\r\n2、春季過敏怎麼辦\r\n3、樂齡的食養天真', `organizer`='和泰純青基金會', `address`='臺北市松山區光復北路190巷35號2樓', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-07 00:00:00', `location`='和泰純青基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='https://www.chun-ching.org.tw/lesson/family_lesson/248', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a9afa18f15d8562cfcd6d7', '樂齡體適能 — 居家運動課', '三月週五 14:00-16:00 以居家運動、健康為主題的付費課程\r\n本系列課程請來專業教練鄭迪升\r\n從各個方面教你運動與相關知識\r\n能幫助你提升身體素質，維護健康\r\n健康生活就從「樂齡體適能 — 居家運動課」開始\r\n-\r\n課程說明：\r\n前半段為靜態課程。\r\n後半段將進行運動課程，含暖身、訓練與收操。會使用椅子當輔具教學。\r\n-\r\n提醒事項：\r\n請自備彈力帶、瑜伽墊或巧拼墊、水壺、毛巾，著運動服裝。\r\n-\r\n3/7 防癌飲食\r\n遠離癌症\r\n吃對食物與適當烹煮才是王道\r\n-\r\n3/14 代謝症候群預防與面對\r\n遠離代謝症候群\r\n五大絕招要做到\r\n好的生活習慣，遠離病痛更有效\r\n-\r\n3/21 筋膜放鬆 （一）\r\n下肢放鬆技巧與注意事項\r\n-\r\n3/28 筋膜放鬆 （二）\r\n上肢放鬆技巧與注意事項\r\n-\r\n【課程資訊】\r\n授課講師：鄭迪升(強森) 教練\r\n單堂費用：350元\r\n整期費用：1200元\r\n最低開課人數：10人\r\n(可單堂報名，不會有銜接問題)', '和泰純青基金會', '臺北市松山區光復北路190巷35號2樓', '2025-03-07 00:00:00', '2025-03-07 00:00:00', '和泰純青基金會', 25.05999101, 121.5575876, '單堂費用：350元\r\n整期費用：1200元', 'https://www.chun-ching.org.tw/lesson/family_lesson/255', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樂齡體適能 — 居家運動課', `description`='三月週五 14:00-16:00 以居家運動、健康為主題的付費課程\r\n本系列課程請來專業教練鄭迪升\r\n從各個方面教你運動與相關知識\r\n能幫助你提升身體素質，維護健康\r\n健康生活就從「樂齡體適能 — 居家運動課」開始\r\n-\r\n課程說明：\r\n前半段為靜態課程。\r\n後半段將進行運動課程，含暖身、訓練與收操。會使用椅子當輔具教學。\r\n-\r\n提醒事項：\r\n請自備彈力帶、瑜伽墊或巧拼墊、水壺、毛巾，著運動服裝。\r\n-\r\n3/7 防癌飲食\r\n遠離癌症\r\n吃對食物與適當烹煮才是王道\r\n-\r\n3/14 代謝症候群預防與面對\r\n遠離代謝症候群\r\n五大絕招要做到\r\n好的生活習慣，遠離病痛更有效\r\n-\r\n3/21 筋膜放鬆 （一）\r\n下肢放鬆技巧與注意事項\r\n-\r\n3/28 筋膜放鬆 （二）\r\n上肢放鬆技巧與注意事項\r\n-\r\n【課程資訊】\r\n授課講師：鄭迪升(強森) 教練\r\n單堂費用：350元\r\n整期費用：1200元\r\n最低開課人數：10人\r\n(可單堂報名，不會有銜接問題)', `organizer`='和泰純青基金會', `address`='臺北市松山區光復北路190巷35號2樓', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-07 00:00:00', `location`='和泰純青基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='單堂費用：350元\r\n整期費用：1200元', `source_url`='https://www.chun-ching.org.tw/lesson/family_lesson/255', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a9b57b8f15d8562cfcd6d8', '懷舊照片大復活', '以教學手機操作為主題的付費課程\r\n-\r\n歲月留下生活故事，美好駐留塵封相片，可曾想過：我們的歲月有多少的故事和回憶，是值得被永久記錄？\r\n透過人手一機的數位科技，將塵封已久的老照片及深藏內蘊的豐功偉業，紀錄在專屬自己的人生風雲榜，隨時隨地與親朋好友分享。\r\n一起【好漢重提當年勇，美女回眸昔日嬌】，重溫當年風光時刻。藉此【做中學，學中做】，讓自己的平凡生活更有趣！\r\n-\r\n以手機教學為主題的課程\r\n講師以一對一的耐心指導、小班制、深入淺出教學\r\n手機實作比講座更多\r\n歡迎對喜歡學習、手機實作有興趣者參加\r\n-\r\n課程目標：\r\n1、將家中老舊照片數位化，隨時都能回味往事\r\n2、透過分享彼此的老照片，重燃生活熱情，連結更多的他人與探索自己\r\n-\r\n事前預備：\r\n1、學員需自備10張老照片\r\n2、學員需自備智慧型手機\r\n-\r\n3/4 老照片數位化\r\n● 為何要將老照片轉成數位相片\r\n● App [Photo Scan] 掃描老照片上\r\n● 分享相片的故事\r\n● 上網註冊[從前從前]、加入社群、官方帳號\r\n● 複習、Q&A (小小練習題-手寫回憶)\r\n-\r\n3/11 老照片雲端化\r\n● 掃描老相片的小密技\r\n● 拍下紀念物品、放入雲端永久保存\r\n● 輸入紀念相片、物品的基本資料 (人、時、地、事、物)\r\n● 分享故事 (發布貼文)\r\n● 發給LINE 親友、群組\r\n-\r\n3/18 老照片復刻化\r\n● 依照老相片 (人、時、地、事、物) 尋找資料\r\n● 在 [從前從前] 網站，永久保存\r\n● 與好友分享，設定[公開/私密]權限\r\n● 結合短影音分享故事\r\n● Q&A\r\n-\r\n3/25 老照片連結化\r\n● 練習將相片發佈貼文\r\n● 複習功能教學（回憶、#標籤）\r\n● 練習將『社群』照片，放入『從前從前』官網\r\n● 5~10則以上分享發佈在從前從前的故事\r\n● 結合短影音分享故事\r\n● 問卷調查\r\n-\r\n【課程資訊】\r\n授課講師：郭惠敏 老師\r\n課程費用：1200元\r\n', '和泰純青基金會', '臺北市松山區光復北路190巷35號2樓', '2025-03-04 00:00:00', '2025-03-04 00:00:00', '和泰純青基金會', 25.05999101, 121.5575876, '課程費用：1200元\r\n可單堂報名 350元，建議您整期報名以利銜接課程進度', 'https://www.chun-ching.org.tw/lesson/family_lesson/245', '[]') ON DUPLICATE KEY UPDATE `activity_name`='懷舊照片大復活', `description`='以教學手機操作為主題的付費課程\r\n-\r\n歲月留下生活故事，美好駐留塵封相片，可曾想過：我們的歲月有多少的故事和回憶，是值得被永久記錄？\r\n透過人手一機的數位科技，將塵封已久的老照片及深藏內蘊的豐功偉業，紀錄在專屬自己的人生風雲榜，隨時隨地與親朋好友分享。\r\n一起【好漢重提當年勇，美女回眸昔日嬌】，重溫當年風光時刻。藉此【做中學，學中做】，讓自己的平凡生活更有趣！\r\n-\r\n以手機教學為主題的課程\r\n講師以一對一的耐心指導、小班制、深入淺出教學\r\n手機實作比講座更多\r\n歡迎對喜歡學習、手機實作有興趣者參加\r\n-\r\n課程目標：\r\n1、將家中老舊照片數位化，隨時都能回味往事\r\n2、透過分享彼此的老照片，重燃生活熱情，連結更多的他人與探索自己\r\n-\r\n事前預備：\r\n1、學員需自備10張老照片\r\n2、學員需自備智慧型手機\r\n-\r\n3/4 老照片數位化\r\n● 為何要將老照片轉成數位相片\r\n● App [Photo Scan] 掃描老照片上\r\n● 分享相片的故事\r\n● 上網註冊[從前從前]、加入社群、官方帳號\r\n● 複習、Q&A (小小練習題-手寫回憶)\r\n-\r\n3/11 老照片雲端化\r\n● 掃描老相片的小密技\r\n● 拍下紀念物品、放入雲端永久保存\r\n● 輸入紀念相片、物品的基本資料 (人、時、地、事、物)\r\n● 分享故事 (發布貼文)\r\n● 發給LINE 親友、群組\r\n-\r\n3/18 老照片復刻化\r\n● 依照老相片 (人、時、地、事、物) 尋找資料\r\n● 在 [從前從前] 網站，永久保存\r\n● 與好友分享，設定[公開/私密]權限\r\n● 結合短影音分享故事\r\n● Q&A\r\n-\r\n3/25 老照片連結化\r\n● 練習將相片發佈貼文\r\n● 複習功能教學（回憶、#標籤）\r\n● 練習將『社群』照片，放入『從前從前』官網\r\n● 5~10則以上分享發佈在從前從前的故事\r\n● 結合短影音分享故事\r\n● 問卷調查\r\n-\r\n【課程資訊】\r\n授課講師：郭惠敏 老師\r\n課程費用：1200元\r\n', `organizer`='和泰純青基金會', `address`='臺北市松山區光復北路190巷35號2樓', `start_date`='2025-03-04 00:00:00', `end_date`='2025-03-04 00:00:00', `location`='和泰純青基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='課程費用：1200元\r\n可單堂報名 350元，建議您整期報名以利銜接課程進度', `source_url`='https://www.chun-ching.org.tw/lesson/family_lesson/245', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a9b6248f15d8562cfcd6d9', '生命故事輕鬆聊 心理課程', '三月週三 9:30-11:30\r\n生命故事就在生活中流動著\r\n如何彙整生命故事，讓往後過得更精彩\r\n定期地透過生命故事 ——來認識自己\r\n也可以聽聽他人的故事\r\n-\r\n3/5 嗨！原來「我」一直都在！？\r\n生命經驗與體會的累積有時帶來智慧，有時卻也帶來「遺忘」，你還記得曾經那些讓自己感到充滿活力的自己嗎？又有哪些早已多年不復相見了呢？\r\n● 分享生命故事與經歷，重新找回生命裡遺落的力量。\r\n● 媒材：每位夥伴須攜帶1-2張童年時期的照片或物品。\r\n-\r\n3/12 與我的重新相遇、相癒\r\n生活常常教導著我們什麼是應該具備的生存與應對能力，只是隨著歲月增長，我們也越來知曉什麼「東西」正在我內心蠢蠢欲動…\r\n● 探詢心靈裡那些難以被言說與嶄露的「我」樣貌。\r\n● 進學員減緩生活裡自我內耗與內心焦躁打架的時刻。\r\n-\r\n3/19 重新建立「我」王國？\r\n每個人的內在都擁有一個專屬於自己的王國，在這片心靈國土裡，我們擁有各式各樣的特質與因應能力，你也期待能夠探詢自己擁有哪些美好特質嗎？\r\n● 協助學員經驗與體會自我內在心理世界的整合。\r\n-\r\n3/26 學習擁抱美好的自我\r\n學習好好愛自己是件既簡單卻也真心不容易的事情，如何能夠「重新」也「從心」好好擁抱自己更是件美好到不行的事情，你也期待給予自己如此地擁抱嗎…\r\n● 協助學員親身體驗並從心擁抱自我，找到自我那些足夠好也美好的樣貌。\r\n-\r\n【課程資訊】\r\n授課講師：鄧年嘉 諮商心理師\r\n課程費用：1200元\r\n單堂費用：350元\r\n最低開課人數：14人', '和泰純青基金會', '臺北市松山區光復北路190巷35號2樓', '2025-03-05 00:00:00', '2025-03-05 00:00:00', '和泰純青基金會', 25.05999101, 121.5575876, '課程費用：1200元\r\n單堂費用：350元', 'https://www.chun-ching.org.tw/lesson/family_lesson/243', '[]') ON DUPLICATE KEY UPDATE `activity_name`='生命故事輕鬆聊 心理課程', `description`='三月週三 9:30-11:30\r\n生命故事就在生活中流動著\r\n如何彙整生命故事，讓往後過得更精彩\r\n定期地透過生命故事 ——來認識自己\r\n也可以聽聽他人的故事\r\n-\r\n3/5 嗨！原來「我」一直都在！？\r\n生命經驗與體會的累積有時帶來智慧，有時卻也帶來「遺忘」，你還記得曾經那些讓自己感到充滿活力的自己嗎？又有哪些早已多年不復相見了呢？\r\n● 分享生命故事與經歷，重新找回生命裡遺落的力量。\r\n● 媒材：每位夥伴須攜帶1-2張童年時期的照片或物品。\r\n-\r\n3/12 與我的重新相遇、相癒\r\n生活常常教導著我們什麼是應該具備的生存與應對能力，只是隨著歲月增長，我們也越來知曉什麼「東西」正在我內心蠢蠢欲動…\r\n● 探詢心靈裡那些難以被言說與嶄露的「我」樣貌。\r\n● 進學員減緩生活裡自我內耗與內心焦躁打架的時刻。\r\n-\r\n3/19 重新建立「我」王國？\r\n每個人的內在都擁有一個專屬於自己的王國，在這片心靈國土裡，我們擁有各式各樣的特質與因應能力，你也期待能夠探詢自己擁有哪些美好特質嗎？\r\n● 協助學員經驗與體會自我內在心理世界的整合。\r\n-\r\n3/26 學習擁抱美好的自我\r\n學習好好愛自己是件既簡單卻也真心不容易的事情，如何能夠「重新」也「從心」好好擁抱自己更是件美好到不行的事情，你也期待給予自己如此地擁抱嗎…\r\n● 協助學員親身體驗並從心擁抱自我，找到自我那些足夠好也美好的樣貌。\r\n-\r\n【課程資訊】\r\n授課講師：鄧年嘉 諮商心理師\r\n課程費用：1200元\r\n單堂費用：350元\r\n最低開課人數：14人', `organizer`='和泰純青基金會', `address`='臺北市松山區光復北路190巷35號2樓', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='和泰純青基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='課程費用：1200元\r\n單堂費用：350元', `source_url`='https://www.chun-ching.org.tw/lesson/family_lesson/243', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a9b7dc8f15d8562cfcd6da', 'DIY—石膏繃帶肌理畫', '利用石膏繃帶創作出富有肌理感的藝術作品，透過實作與理論結合，學員將學會基本技術及色彩創意表達\r\n-\r\n【課程內容】\r\n1、肌理畫的色彩藝術概念\r\n2、石膏繃帶、顏料、工具的選擇\r\n3、石膏繃帶的使用方法\r\n4、創建基礎形狀與結構\r\n5、肌理效果的創作技巧\r\n-\r\n【課程須知】\r\n1、報名與繳費截止日為2025/3/6。\r\n2、材料形狀可選擇：愛心、正方形、長方形、圓形，請在線上報名時於「備註」欄位填寫。\r\n3、若為親子報名 (1大人+1小孩，建議學齡：小學生9-12歲)，線上報名時於「備註」欄位填寫小孩姓名、年紀與自選材料形狀，例：高小明，9歲，30cm愛心+20cm方形。\r\n-\r\n【課程資訊】\r\n開課時間：3/29 (週六) 13:30-16:00\r\n講師：劉芷瑜 老師\r\n劉芷瑜老師有豐富的手作課程教學經驗，除了手作編織包之外，還有手作擴香石、香氛蠟燭、石膏肌理畫、毛料娃娃、香氛風鈴、酒精墨水畫、壓克力流動畫、石膏花捏塑等課程的教學經驗。', '和泰純青基金會', '臺北市松山區光復北路190巷35號2樓', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '和泰純青基金會', 25.05999101, 121.5575876, '課程費用：850、1590元\r\n\r\n850元 單人報名 (含一個直徑30cm材料)\r\n1590元 親子報名 (含直徑30cm與20cm材料各一個)', 'https://www.chun-ching.org.tw/lesson/family_lesson/250', '[]') ON DUPLICATE KEY UPDATE `activity_name`='DIY—石膏繃帶肌理畫', `description`='利用石膏繃帶創作出富有肌理感的藝術作品，透過實作與理論結合，學員將學會基本技術及色彩創意表達\r\n-\r\n【課程內容】\r\n1、肌理畫的色彩藝術概念\r\n2、石膏繃帶、顏料、工具的選擇\r\n3、石膏繃帶的使用方法\r\n4、創建基礎形狀與結構\r\n5、肌理效果的創作技巧\r\n-\r\n【課程須知】\r\n1、報名與繳費截止日為2025/3/6。\r\n2、材料形狀可選擇：愛心、正方形、長方形、圓形，請在線上報名時於「備註」欄位填寫。\r\n3、若為親子報名 (1大人+1小孩，建議學齡：小學生9-12歲)，線上報名時於「備註」欄位填寫小孩姓名、年紀與自選材料形狀，例：高小明，9歲，30cm愛心+20cm方形。\r\n-\r\n【課程資訊】\r\n開課時間：3/29 (週六) 13:30-16:00\r\n講師：劉芷瑜 老師\r\n劉芷瑜老師有豐富的手作課程教學經驗，除了手作編織包之外，還有手作擴香石、香氛蠟燭、石膏肌理畫、毛料娃娃、香氛風鈴、酒精墨水畫、壓克力流動畫、石膏花捏塑等課程的教學經驗。', `organizer`='和泰純青基金會', `address`='臺北市松山區光復北路190巷35號2樓', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='和泰純青基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='課程費用：850、1590元\r\n\r\n850元 單人報名 (含一個直徑30cm材料)\r\n1590元 親子報名 (含直徑30cm與20cm材料各一個)', `source_url`='https://www.chun-ching.org.tw/lesson/family_lesson/250', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a9c33d8f15d8562cfcd6dc', '經絡滾筒', '健康的身體需要調養生息以及有益身心的發展，藉此理念養成正確的運動方法非常重要，進入中年後如何運動？睡眠品質不佳如何運動？自律神經失調怎麼運動能改善？情感壓抑的人能透過運動排解嗎？\r\n-\r\n經絡滾筒課程讓您學習疏通12條經絡，認識每條經絡的功能與病理相關，也練習覺察自己身體的訊號、覺知身體的需求，把肌肉層層疏通氣脈相通後還能改善生活習慣所帶來的不良身體結構，逐漸地提升良好的身型達到運動的效應。想讓體態變年輕或感覺身體總是卡卡，歡迎加入體驗喔！\r\n\r\n-\r\n【課程須知】\r\n1、開課人數：8~10人(須達8人(含)以上，才開班。統計至3/13截止)\r\n2、一期4堂1500元 (報名單堂400元)(若報名一期，欲請假，則以單堂計費方式進行退費)\r\n例：報名4堂課，請假一次，1500-400*3=300，因此退費300元\r\n3、第一期成班後，接續開放後續期別報名\r\n* 上課務必自備瑜珈墊\r\n* 上課用滾筒：若已有滾筒可自備，無滾筒或款式不合適者，可由老師代購，代購價為780元\r\n\r\n-\r\n【課程資訊】\r\n開課時間：第一期 3/20、3/27、4/10、4/17 (週四) 19:20 -20:50\r\n講師： 劉芷妍Julia (牛奶糖老師)\r\n奧福音樂舞蹈教學國際大師班/英國皇家芭蕾教學專業教師\r\n舞蹈治療助理教師/經絡與動作師資培訓\r\n奧福音樂舞蹈教學研發講師/台灣教育部全國學生舞蹈大賽指導老師/國小人文藝術課程研發講師/幼兒成長感覺統合研發與教學講師\r\nYMCA、幼兒園所、舞蹈教室/公司尾牙編排老師/經絡滾筒/私人經絡瑜珈教學/身體大健康講座講師', '和泰純青基金會', '臺北市松山區光復北路190巷35號2樓', '2025-03-20 00:00:00', '2025-03-20 00:00:00', '和泰純青基金會', 25.05999101, 121.5575876, '課程費用：1500元', 'https://www.chun-ching.org.tw/lesson/family_lesson/252', '[]') ON DUPLICATE KEY UPDATE `activity_name`='經絡滾筒', `description`='健康的身體需要調養生息以及有益身心的發展，藉此理念養成正確的運動方法非常重要，進入中年後如何運動？睡眠品質不佳如何運動？自律神經失調怎麼運動能改善？情感壓抑的人能透過運動排解嗎？\r\n-\r\n經絡滾筒課程讓您學習疏通12條經絡，認識每條經絡的功能與病理相關，也練習覺察自己身體的訊號、覺知身體的需求，把肌肉層層疏通氣脈相通後還能改善生活習慣所帶來的不良身體結構，逐漸地提升良好的身型達到運動的效應。想讓體態變年輕或感覺身體總是卡卡，歡迎加入體驗喔！\r\n\r\n-\r\n【課程須知】\r\n1、開課人數：8~10人(須達8人(含)以上，才開班。統計至3/13截止)\r\n2、一期4堂1500元 (報名單堂400元)(若報名一期，欲請假，則以單堂計費方式進行退費)\r\n例：報名4堂課，請假一次，1500-400*3=300，因此退費300元\r\n3、第一期成班後，接續開放後續期別報名\r\n* 上課務必自備瑜珈墊\r\n* 上課用滾筒：若已有滾筒可自備，無滾筒或款式不合適者，可由老師代購，代購價為780元\r\n\r\n-\r\n【課程資訊】\r\n開課時間：第一期 3/20、3/27、4/10、4/17 (週四) 19:20 -20:50\r\n講師： 劉芷妍Julia (牛奶糖老師)\r\n奧福音樂舞蹈教學國際大師班/英國皇家芭蕾教學專業教師\r\n舞蹈治療助理教師/經絡與動作師資培訓\r\n奧福音樂舞蹈教學研發講師/台灣教育部全國學生舞蹈大賽指導老師/國小人文藝術課程研發講師/幼兒成長感覺統合研發與教學講師\r\nYMCA、幼兒園所、舞蹈教室/公司尾牙編排老師/經絡滾筒/私人經絡瑜珈教學/身體大健康講座講師', `organizer`='和泰純青基金會', `address`='臺北市松山區光復北路190巷35號2樓', `start_date`='2025-03-20 00:00:00', `end_date`='2025-03-20 00:00:00', `location`='和泰純青基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='課程費用：1500元', `source_url`='https://www.chun-ching.org.tw/lesson/family_lesson/252', `image_url`='[]';
