INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67aa6e7b26b3240c403d94aa', '「有多彩多姿，也有美麗的壯觀」世界文化巡迴書展', '展示關於「異國風情」、「多元文化」主題書籍，亦提供多樣特色展品展示，閱讀的同時也可以館賞異國文化小物。', '澎湖縣政府文化局', '澎湖縣馬公市中華路236之1號', '2025-01-01 00:00:00', '2025-02-28 00:00:00', '澎湖縣圖書館', 23.55534, 119.59234, '無資料', '--', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「有多彩多姿，也有美麗的壯觀」世界文化巡迴書展', `description`='展示關於「異國風情」、「多元文化」主題書籍，亦提供多樣特色展品展示，閱讀的同時也可以館賞異國文化小物。', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路236之1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='澎湖縣圖書館', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='--', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67aa6e7b26b3240c403d94ab', '藝遊人生-林顯宗油畫世界', '非學院出身的林顯宗，跟隨前輩畫家張義雄、李石樵、楊三郎的身影，一生不懈地投入藝術，力行恩師施教的多元創作理念，並擁有豐富的寫生實戰歷練。他透過官展、臺陽展等競技的洗禮，深獲畫壇肯定，更設置畫室培養後進。林顯宗畢生以創作為志業，奮力向前；同時不吝分享繪事歷程，致力藝術社會教育之推廣，九十餘歲仍鬥志昂揚而未停歇。樂觀開朗的林顯宗，半生悠遊藝術之海且卓然有成，正是藝遊人生的最佳寫照！創價美術館推出「藝遊人生—林顯宗油畫世界」，期盼觀眾體悟藝術家悠游人生之作、感受當中的藝術情懷。\r\n\r\n林顯宗（1933-）生於宜蘭蘇澳，20 歲隻身前往台北，進入張義雄「純粹美術班」習畫，並於美術設計工作之餘勤勉創作。他陸續向李石樵、楊三郎習畫，確立個人用色濃厚、追尋自然寫生的創作風格。1984 年起作品屢獲台陽美展、全國油畫展獎項肯定，始成為全職畫家。驅動畫筆六十餘年，累積豐富的創作外，也投入畫會社群傾力推廣台灣美術運動。', '台灣創價學會', '桃園市大園區高鐵北路二段140號7樓', '2025-02-05 00:00:00', '2025-05-09 00:00:00', '台灣創價學會美術館桃園館', 25.0207895, 121.2223355, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝遊人生-林顯宗油畫世界', `description`='非學院出身的林顯宗，跟隨前輩畫家張義雄、李石樵、楊三郎的身影，一生不懈地投入藝術，力行恩師施教的多元創作理念，並擁有豐富的寫生實戰歷練。他透過官展、臺陽展等競技的洗禮，深獲畫壇肯定，更設置畫室培養後進。林顯宗畢生以創作為志業，奮力向前；同時不吝分享繪事歷程，致力藝術社會教育之推廣，九十餘歲仍鬥志昂揚而未停歇。樂觀開朗的林顯宗，半生悠遊藝術之海且卓然有成，正是藝遊人生的最佳寫照！創價美術館推出「藝遊人生—林顯宗油畫世界」，期盼觀眾體悟藝術家悠游人生之作、感受當中的藝術情懷。\r\n\r\n林顯宗（1933-）生於宜蘭蘇澳，20 歲隻身前往台北，進入張義雄「純粹美術班」習畫，並於美術設計工作之餘勤勉創作。他陸續向李石樵、楊三郎習畫，確立個人用色濃厚、追尋自然寫生的創作風格。1984 年起作品屢獲台陽美展、全國油畫展獎項肯定，始成為全職畫家。驅動畫筆六十餘年，累積豐富的創作外，也投入畫會社群傾力推廣台灣美術運動。', `organizer`='台灣創價學會', `address`='桃園市大園區高鐵北路二段140號7樓', `start_date`='2025-02-05 00:00:00', `end_date`='2025-05-09 00:00:00', `location`='台灣創價學會美術館桃園館', `latitude`=25.0207895, `longitude`=121.2223355, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67aa6e7b26b3240c403d94ac', '113學年度全國學生美術比賽特優作品巡迴展', '展出全國學生美術比賽得獎作品，共分七大類別，包括：國小組-繪畫、書法、平面設計、漫畫、水墨畫、版畫；國中組、高中（職）組及大專組-西畫、書法、平面設計、漫畫、水墨畫、版畫。自國小至大專共計55組，並展出113學年度全國學生美術比賽特優得獎作品。', '國立臺灣藝術教育館', '澎湖縣馬公市中華路230號', '2025-02-19 00:00:00', '2025-03-06 00:00:00', '澎湖縣政府文化局', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='113學年度全國學生美術比賽特優作品巡迴展', `description`='展出全國學生美術比賽得獎作品，共分七大類別，包括：國小組-繪畫、書法、平面設計、漫畫、水墨畫、版畫；國中組、高中（職）組及大專組-西畫、書法、平面設計、漫畫、水墨畫、版畫。自國小至大專共計55組，並展出113學年度全國學生美術比賽特優得獎作品。', `organizer`='國立臺灣藝術教育館', `address`='澎湖縣馬公市中華路230號', `start_date`='2025-02-19 00:00:00', `end_date`='2025-03-06 00:00:00', `location`='澎湖縣政府文化局', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67aa9c4a07f37a26088be578', '穿越時空的宮廷盛宴', '體驗從環地中海到東方的味蕾旅程嗎？「穿越時空的宮廷盛宴」課程將帶你探索古代宮廷的飲食文化，從地中海到中國的歷史美食演變。更透過多部經典影視作品深入解析與探討現實與影視中的異同與差距。', '國立政治大學公共行政及企業管理教育中心', '臺北市金華街187號', '2025-03-19 00:00:00', '2025-03-19 00:00:00', '國立政治大學公共行政及企業管理教育中心', 0, 0, '學費4000元', 'https://cpbae.nccu.edu.tw/cpbae/class?id=4&classId=N0A2B4032', '[]') ON DUPLICATE KEY UPDATE `activity_name`='穿越時空的宮廷盛宴', `description`='體驗從環地中海到東方的味蕾旅程嗎？「穿越時空的宮廷盛宴」課程將帶你探索古代宮廷的飲食文化，從地中海到中國的歷史美食演變。更透過多部經典影視作品深入解析與探討現實與影視中的異同與差距。', `organizer`='國立政治大學公共行政及企業管理教育中心', `address`='臺北市金華街187號', `start_date`='2025-03-19 00:00:00', `end_date`='2025-03-19 00:00:00', `location`='國立政治大學公共行政及企業管理教育中心', `latitude`=0, `longitude`=0, `ticket_price`='學費4000元', `source_url`='https://cpbae.nccu.edu.tw/cpbae/class?id=4&classId=N0A2B4032', `image_url`='[]';
