INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ab180407f37a26088be57b', '張亞蓁 創作個展【異景．心戲】', '本次個展張亞蓁以「園林」為核心，探索「人造空間」與「主觀世界」的對話。一是以現代家居為基礎，構築私人樂園般的理想小天地；二是從臺灣在地的園林造景中汲取靈感，描繪內心的世界。\r\n「園林」不僅是自然的縮影，更是張亞蓁心中理想之地的投射與寄託。她的創作彷彿在現代生活中創造一座異托邦，邀請觀者沉浸於她的內心風景，感受其中的詩意與幻境。', '金車文藝中心 KCCA', '臺北市中山區南京東路二段1號3樓', '2025-02-08 00:00:00', '2025-03-23 00:00:00', '金車文藝中心 臺北南京館', 25.06969917, 121.5381597, '無資料', 'https://www.kingcarart.org.tw/exhibitions-detail/218', '[]') ON DUPLICATE KEY UPDATE `activity_name`='張亞蓁 創作個展【異景．心戲】', `description`='本次個展張亞蓁以「園林」為核心，探索「人造空間」與「主觀世界」的對話。一是以現代家居為基礎，構築私人樂園般的理想小天地；二是從臺灣在地的園林造景中汲取靈感，描繪內心的世界。\r\n「園林」不僅是自然的縮影，更是張亞蓁心中理想之地的投射與寄託。她的創作彷彿在現代生活中創造一座異托邦，邀請觀者沉浸於她的內心風景，感受其中的詩意與幻境。', `organizer`='金車文藝中心 KCCA', `address`='臺北市中山區南京東路二段1號3樓', `start_date`='2025-02-08 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='金車文藝中心 臺北南京館', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='https://www.kingcarart.org.tw/exhibitions-detail/218', `image_url`='[]';
