INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0126b3240c403d94cb', '大高雄歷史常設展', '作為高雄重要歷史地標的高雄市立歷史博物館，將化身為民眾認識高雄的重要入口站，透過常態性展示，為在地高雄居民提供重新認識故鄉的契機，同時帶領外縣市觀光客、海外的國際友人，看見百年來高雄人的勞動身影以及城市、鄉村地景的變遷，並以河、港、鐵路網絡為子題勾勒出高雄從漁村到國際商港的百年城市脈動。', '高雄市立歷史博物館', '高雄市鹽埕區019鄰中正四路272號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '高雄市立歷史博物館', 22.6267591, 120.2868723, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大高雄歷史常設展', `description`='作為高雄重要歷史地標的高雄市立歷史博物館，將化身為民眾認識高雄的重要入口站，透過常態性展示，為在地高雄居民提供重新認識故鄉的契機，同時帶領外縣市觀光客、海外的國際友人，看見百年來高雄人的勞動身影以及城市、鄉村地景的變遷，並以河、港、鐵路網絡為子題勾勒出高雄從漁村到國際商港的百年城市脈動。', `organizer`='高雄市立歷史博物館', `address`='高雄市鹽埕區019鄰中正四路272號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄市立歷史博物館', `latitude`=22.6267591, `longitude`=120.2868723, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0126b3240c403d94cc', '二二八‧0306', '本館原為日治時期高雄市役所，戰後改為高雄市政府，乃是二二八事件在高雄的重要歷史現場之一。1947年3月6日伴隨著飄落的細雨，政府軍隊武力鎮壓的第一聲槍響便是在此響起，也開始了高雄二二八事件中一連串的犧牲。本展製作國內首見二二八事件中於舊高雄市政府武力鎮壓事件模型場景，再現當時的歷史情境，並搭配相關文物展示，使參觀民眾不僅能夠身歷其境，更能藉由二二八事件的歷史再現，使這段歷史成為重要教材。透過本展，期許參觀民眾能夠由認識、理解，進而思索二二八事件在高雄的特殊性、爭議性及歷史意義。展示二二八，或許也是讓不同觀點的人們共同參與對話及反省的契機。', '高雄市立歷史博物館', '高雄市鹽埕區019鄰中正四路272號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '高雄市立歷史博物館', 22.6267591, 120.2868723, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='二二八‧0306', `description`='本館原為日治時期高雄市役所，戰後改為高雄市政府，乃是二二八事件在高雄的重要歷史現場之一。1947年3月6日伴隨著飄落的細雨，政府軍隊武力鎮壓的第一聲槍響便是在此響起，也開始了高雄二二八事件中一連串的犧牲。本展製作國內首見二二八事件中於舊高雄市政府武力鎮壓事件模型場景，再現當時的歷史情境，並搭配相關文物展示，使參觀民眾不僅能夠身歷其境，更能藉由二二八事件的歷史再現，使這段歷史成為重要教材。透過本展，期許參觀民眾能夠由認識、理解，進而思索二二八事件在高雄的特殊性、爭議性及歷史意義。展示二二八，或許也是讓不同觀點的人們共同參與對話及反省的契機。', `organizer`='高雄市立歷史博物館', `address`='高雄市鹽埕區019鄰中正四路272號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄市立歷史博物館', `latitude`=22.6267591, `longitude`=120.2868723, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0126b3240c403d94cd', '高小雄冒險記', '本館為5歲以上的小朋友打造一個適合親子同樂的體驗空間，以擬人化的比喻手法，將「高雄」化身為一位名叫「高小雄」的男孩，搭配妹妹「高小美」及魔法師「高史伯」的角色，拉近與兒童觀眾的距離，並透過多元的展示媒介與互動參與方式來引導學習，希望小朋友玩得很開心，也可以學到關於高雄的知識。', '高雄市立歷史博物館', '高雄市鹽埕區019鄰中正四路272號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '高雄市立歷史博物館', 22.6267591, 120.2868723, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高小雄冒險記', `description`='本館為5歲以上的小朋友打造一個適合親子同樂的體驗空間，以擬人化的比喻手法，將「高雄」化身為一位名叫「高小雄」的男孩，搭配妹妹「高小美」及魔法師「高史伯」的角色，拉近與兒童觀眾的距離，並透過多元的展示媒介與互動參與方式來引導學習，希望小朋友玩得很開心，也可以學到關於高雄的知識。', `organizer`='高雄市立歷史博物館', `address`='高雄市鹽埕區019鄰中正四路272號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄市立歷史博物館', `latitude`=22.6267591, `longitude`=120.2868723, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0126b3240c403d94ce', '高雄文獻研究中心史料文獻展', '文獻中心廣泛蒐集各類型與高雄暨臺灣歷史發展軌跡相關之資料，館藏包含史料、圖書、期刊、地圖及資料庫等，期能發揮高雄暨臺灣歷史文化之蒐藏、研究、教育及交流之功能。', '高雄市立歷史博物館', '高雄市鹽埕區019鄰中正四路272號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '高雄市立歷史博物館', 22.6267591, 120.2868723, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄文獻研究中心史料文獻展', `description`='文獻中心廣泛蒐集各類型與高雄暨臺灣歷史發展軌跡相關之資料，館藏包含史料、圖書、期刊、地圖及資料庫等，期能發揮高雄暨臺灣歷史文化之蒐藏、研究、教育及交流之功能。', `organizer`='高雄市立歷史博物館', `address`='高雄市鹽埕區019鄰中正四路272號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄市立歷史博物館', `latitude`=22.6267591, `longitude`=120.2868723, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0126b3240c403d94cf', '「誰把高雄變大了?」──高雄設市百年特展', '1924年12月25日高雄市役所正式成立，宣告了高雄做為地方自治組織、具備獨立財政的新時代來臨。百年來，高雄市從臨港市街發展為工業大城，如今更是南臺灣重要都會區。若問是誰把高雄變大了？不同階段的「產業」有效提振經濟、創造就業、捲動內需，即為關鍵。首先是海港物流奠定城市底蘊，而後，化工業、石化工業、加工出口區、重工業，乃至近年的高科技產業等，先後注入動能，牽引各種日常和非常的生活產業。\r\n本特展盤點19項產業與職人，並將概分二大主題：一是對於出口做出貢獻者，二是對於城市內需提供助力者。我們簡述產業、勾勒職人，藉由影像、物件傳達歷史幾許，對無數從業者的付出獻上敬意。\r\n產業與其背後的職人塑造了城市的個性。當初從各地聚集，在各產業中打拼的人，是城市發展背後的推手，也是形塑高雄的高雄人。適逢百年紀念的此刻，我們更應感念這群默默為高雄貢獻的人們。在複雜的產業體系中，本特展盤點19項產業與職人，並將概分二大主題：一是對於出口做出貢獻者，二是對於城市內需提供助力者。我們簡述產業、勾勒職人，藉由影像、物件傳達歷史幾許，對無數從業者的付出獻上敬意。', '高雄市立歷史博物館', '高雄市鹽埕區019鄰中正四路272號', '2025-01-01 00:00:00', '2025-06-15 00:00:00', '高雄市立歷史博物館', 22.6267591, 120.2868723, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「誰把高雄變大了?」──高雄設市百年特展', `description`='1924年12月25日高雄市役所正式成立，宣告了高雄做為地方自治組織、具備獨立財政的新時代來臨。百年來，高雄市從臨港市街發展為工業大城，如今更是南臺灣重要都會區。若問是誰把高雄變大了？不同階段的「產業」有效提振經濟、創造就業、捲動內需，即為關鍵。首先是海港物流奠定城市底蘊，而後，化工業、石化工業、加工出口區、重工業，乃至近年的高科技產業等，先後注入動能，牽引各種日常和非常的生活產業。\r\n本特展盤點19項產業與職人，並將概分二大主題：一是對於出口做出貢獻者，二是對於城市內需提供助力者。我們簡述產業、勾勒職人，藉由影像、物件傳達歷史幾許，對無數從業者的付出獻上敬意。\r\n產業與其背後的職人塑造了城市的個性。當初從各地聚集，在各產業中打拼的人，是城市發展背後的推手，也是形塑高雄的高雄人。適逢百年紀念的此刻，我們更應感念這群默默為高雄貢獻的人們。在複雜的產業體系中，本特展盤點19項產業與職人，並將概分二大主題：一是對於出口做出貢獻者，二是對於城市內需提供助力者。我們簡述產業、勾勒職人，藉由影像、物件傳達歷史幾許，對無數從業者的付出獻上敬意。', `organizer`='高雄市立歷史博物館', `address`='高雄市鹽埕區019鄰中正四路272號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='高雄市立歷史博物館', `latitude`=22.6267591, `longitude`=120.2868723, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0126b3240c403d94d0', '100%言論自由：鄭南榕和自由時代', '台灣民主發展歷程中經過了無數的社會運動，從黨禁、報禁，到出版品、歌曲、戲劇等都受到政府的審查、限制甚至制裁。其中鄭南榕先生為爭取言論自由，勇敢的壯烈犧牲的事件，更是值得大眾深入了解，本館與鄭南榕基金會合作，以南北串連方式籌劃「100%言論自由：鄭南榕和自由時代」特展，共同紀念這一位台灣民主運動先驅的同時，邀請民眾走進鄭南榕的生命故事，一同思考人權與自由民主的價值。', '財團法人鄭南榕基金會', '高雄市鹽埕區019鄰中正四路272號', '2025-01-01 00:00:00', '2025-04-20 00:00:00', '高雄市立歷史博物館', 22.6267591, 120.2868723, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='100%言論自由：鄭南榕和自由時代', `description`='台灣民主發展歷程中經過了無數的社會運動，從黨禁、報禁，到出版品、歌曲、戲劇等都受到政府的審查、限制甚至制裁。其中鄭南榕先生為爭取言論自由，勇敢的壯烈犧牲的事件，更是值得大眾深入了解，本館與鄭南榕基金會合作，以南北串連方式籌劃「100%言論自由：鄭南榕和自由時代」特展，共同紀念這一位台灣民主運動先驅的同時，邀請民眾走進鄭南榕的生命故事，一同思考人權與自由民主的價值。', `organizer`='財團法人鄭南榕基金會', `address`='高雄市鹽埕區019鄰中正四路272號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='高雄市立歷史博物館', `latitude`=22.6267591, `longitude`=120.2868723, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0126b3240c403d94d1', '鳳邑雙城記線上展', '清治臺灣鳳山縣，曾經有過兩個縣治，一新一舊。這在臺灣歷史上絕無僅有，而且對後來高雄的歷史發展也影響深遠。\r\n鳳山縣舊城和新城之形成除了地方上民變動亂，也跟統治者與人民對縣城應該側重何種功能有關。究竟應該落腳於有利於海防的左營舊城，還是要選擇經濟重心的下埤頭，兩種看法相持百餘年。最終鳳山縣城轉移到下埤頭，離開原來以防守目的為主的興隆莊。\r\n20世紀後，交通、建設與技術的進步，新城發展成為經濟和文化發達之地。進入21世紀，舊城因為高鐵通車，鐵路地下化以及市府推動再現舊城的見城計畫，再度受到人們的注目。展望未來，期待雙城煥發新猷，再次引領大高雄風華。為了解高雄城市的歷史脈絡，且讓我們一起探索「鳳邑雙城記」。', '高雄市立歷史博物館', '高雄市鹽埕區019鄰中正四路272號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '高雄市立歷史博物館', 22.6267591, 120.2868723, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鳳邑雙城記線上展', `description`='清治臺灣鳳山縣，曾經有過兩個縣治，一新一舊。這在臺灣歷史上絕無僅有，而且對後來高雄的歷史發展也影響深遠。\r\n鳳山縣舊城和新城之形成除了地方上民變動亂，也跟統治者與人民對縣城應該側重何種功能有關。究竟應該落腳於有利於海防的左營舊城，還是要選擇經濟重心的下埤頭，兩種看法相持百餘年。最終鳳山縣城轉移到下埤頭，離開原來以防守目的為主的興隆莊。\r\n20世紀後，交通、建設與技術的進步，新城發展成為經濟和文化發達之地。進入21世紀，舊城因為高鐵通車，鐵路地下化以及市府推動再現舊城的見城計畫，再度受到人們的注目。展望未來，期待雙城煥發新猷，再次引領大高雄風華。為了解高雄城市的歷史脈絡，且讓我們一起探索「鳳邑雙城記」。', `organizer`='高雄市立歷史博物館', `address`='高雄市鹽埕區019鄰中正四路272號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄市立歷史博物館', `latitude`=22.6267591, `longitude`=120.2868723, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0126b3240c403d94d2', '匯流的形狀-愛河記憶線上展', '高雄的城市之河─愛河，貫穿了城市發展的起源與歷程。\r\n潮汐孕育愛河豐富的生態資源，史前時代起即是先民賴以維生的漁獲地。鄭氏時期與清代，漁鹽和港渡呈現鳳山八景「丹渡晴帆」的風情；曹公圳闢成後，愛河成為圳道尾閭，圳水上善，高雄平原聚落得以安身立命。日治時期，高雄實施築港工程，河道與港灣被梳理成今日樣貌，河與港一體成為運輸通道，河的下游成為政經中心、繁華鬧區。1930-80年代，各式工業在港灣及河畔快速成長，帶來就業、也帶來汙染，愛河逐漸失色甚至惡臭。歷時40餘年的整治，重生後的愛河，功能逐漸轉向防洪、觀光休憩，更成為凝聚城市認同的重要景觀。\r\n對高雄市民而言，愛河是跨世代的，也是日常的。多數高雄人的生命歷程，皆能與愛河相映出一段段生活情感記憶，並將記憶化約成一個個的形容詞，刻劃著某種性質、狀態、屬性等意涵。因此，本展試圖以各式各樣的形容詞，召喚愛河的每個小單位，勾勒出歷史記憶中的愛河多元面貌。', '高雄市立歷史博物館', '高雄市鹽埕區019鄰中正四路272號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '高雄市立歷史博物館', 22.6267591, 120.2868723, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='匯流的形狀-愛河記憶線上展', `description`='高雄的城市之河─愛河，貫穿了城市發展的起源與歷程。\r\n潮汐孕育愛河豐富的生態資源，史前時代起即是先民賴以維生的漁獲地。鄭氏時期與清代，漁鹽和港渡呈現鳳山八景「丹渡晴帆」的風情；曹公圳闢成後，愛河成為圳道尾閭，圳水上善，高雄平原聚落得以安身立命。日治時期，高雄實施築港工程，河道與港灣被梳理成今日樣貌，河與港一體成為運輸通道，河的下游成為政經中心、繁華鬧區。1930-80年代，各式工業在港灣及河畔快速成長，帶來就業、也帶來汙染，愛河逐漸失色甚至惡臭。歷時40餘年的整治，重生後的愛河，功能逐漸轉向防洪、觀光休憩，更成為凝聚城市認同的重要景觀。\r\n對高雄市民而言，愛河是跨世代的，也是日常的。多數高雄人的生命歷程，皆能與愛河相映出一段段生活情感記憶，並將記憶化約成一個個的形容詞，刻劃著某種性質、狀態、屬性等意涵。因此，本展試圖以各式各樣的形容詞，召喚愛河的每個小單位，勾勒出歷史記憶中的愛河多元面貌。', `organizer`='高雄市立歷史博物館', `address`='高雄市鹽埕區019鄰中正四路272號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄市立歷史博物館', `latitude`=22.6267591, `longitude`=120.2868723, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0326b3240c403d94d3', '高雄市左營孔子廟常設展', '為提昇參觀民眾對孔子及孔廟相關主題之認識，策劃辦理孔廟常設展覽，期藉由豐富多元的展示內容讓民眾對在地孔廟的歷史發展有更加深入的瞭解。', '高雄市立歷史博物館', '高雄市左營區蓮潭路400號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '高雄市左營孔子廟', 22.6892386, 120.2990417, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市左營孔子廟常設展', `description`='為提昇參觀民眾對孔子及孔廟相關主題之認識，策劃辦理孔廟常設展覽，期藉由豐富多元的展示內容讓民眾對在地孔廟的歷史發展有更加深入的瞭解。', `organizer`='高雄市立歷史博物館', `address`='高雄市左營區蓮潭路400號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄市左營孔子廟', `latitude`=22.6892386, `longitude`=120.2990417, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0326b3240c403d94d4', '戰爭與和平紀念公園主題館常設展', '館內展示台籍老兵的各類文物與文史資料，包括許昭榮先生數十年為台籍老兵權益奮鬥史及相關台灣兵紀錄影片。主題館定期舉辦台灣兵紀念儀式與相關文化推廣活動、文史學術研究以及志工培訓。', '高雄市立歷史博物館', '高雄市旗津區旗津二路701號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '戰爭與和平紀念公園主題館', 22.587232, 120.286871, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='戰爭與和平紀念公園主題館常設展', `description`='館內展示台籍老兵的各類文物與文史資料，包括許昭榮先生數十年為台籍老兵權益奮鬥史及相關台灣兵紀錄影片。主題館定期舉辦台灣兵紀念儀式與相關文化推廣活動、文史學術研究以及志工培訓。', `organizer`='高雄市立歷史博物館', `address`='高雄市旗津區旗津二路701號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='戰爭與和平紀念公園主題館', `latitude`=22.587232, `longitude`=120.286871, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0326b3240c403d94d5', '再見捌捌陸 – 臺灣眷村文化園區常設展', '「再見捌捌陸─臺灣眷村文化園區」以「再見」為題，一方面向流逝的眷村歲月致意，另一方面為迎接眷村新生表示喜悅。全區主要以4大棟建物組成：「眷村時代館」訴說漂流及落定的烽火歲月，展出如勳獎章、逃難時的舊皮箱、砲彈箱米缸等；「眷村聚樂部」呈現來臺後軍區文藝與娛樂空間氛圍，展出如眷補證、紀念牌、《創世紀詩刊》等，呈現俱樂部、電影院與創世紀詩社的文化氛圍；「眷村．潮」則是介紹眷改後眷村所面臨的衝擊與轉變，並加入AR體感式再現眷村的新舊對比；「眷村共生基地」希望創造喜愛眷村文化的創作者，有一可交流的平台，在基地空間中分享創作，園區也將不定期辦理創作坊及展演活動。', '高雄市立歷史博物館', '高雄市左營區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '左營區（高雄市）=', 22.68395699, 120.2951588, '優待票+35;團體票+40;單人票+50', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='再見捌捌陸 – 臺灣眷村文化園區常設展', `description`='「再見捌捌陸─臺灣眷村文化園區」以「再見」為題，一方面向流逝的眷村歲月致意，另一方面為迎接眷村新生表示喜悅。全區主要以4大棟建物組成：「眷村時代館」訴說漂流及落定的烽火歲月，展出如勳獎章、逃難時的舊皮箱、砲彈箱米缸等；「眷村聚樂部」呈現來臺後軍區文藝與娛樂空間氛圍，展出如眷補證、紀念牌、《創世紀詩刊》等，呈現俱樂部、電影院與創世紀詩社的文化氛圍；「眷村．潮」則是介紹眷改後眷村所面臨的衝擊與轉變，並加入AR體感式再現眷村的新舊對比；「眷村共生基地」希望創造喜愛眷村文化的創作者，有一可交流的平台，在基地空間中分享創作，園區也將不定期辦理創作坊及展演活動。', `organizer`='高雄市立歷史博物館', `address`='高雄市左營區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='左營區（高雄市）=', `latitude`=22.68395699, `longitude`=120.2951588, `ticket_price`='優待票+35;團體票+40;單人票+50', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0326b3240c403d94d6', '再見捌捌陸 – 將軍好宅常設展', '眷村，臺灣近代歷史發展下的產物，在這場域中的日常平凡事，人情暖噓問，構築成獨特的眷村文化紋理；每一個眷村，簡單的人事物，都有著當時各種同甘共苦的情懷與思念。本展透過眷村家庭成員的生活物件開箱，窺見眷村既平凡又特殊的生活語境，穿越時光隧道，一同共享平凡迷人的眷村風華，捕捉將消逝的歷史痕跡，拼貼眷村日常記憶圖像。', '高雄市立歷史博物館', '高雄市左營區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '左營區（高雄市）=', 22.68395699, 120.2951588, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='再見捌捌陸 – 將軍好宅常設展', `description`='眷村，臺灣近代歷史發展下的產物，在這場域中的日常平凡事，人情暖噓問，構築成獨特的眷村文化紋理；每一個眷村，簡單的人事物，都有著當時各種同甘共苦的情懷與思念。本展透過眷村家庭成員的生活物件開箱，窺見眷村既平凡又特殊的生活語境，穿越時光隧道，一同共享平凡迷人的眷村風華，捕捉將消逝的歷史痕跡，拼貼眷村日常記憶圖像。', `organizer`='高雄市立歷史博物館', `address`='高雄市左營區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='左營區（高雄市）=', `latitude`=22.68395699, `longitude`=120.2951588, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0326b3240c403d94d7', '舊打狗驛故事館常設展', '打狗鐵道故事館為台鐵高雄港車站轉變而來，目前館內保留了許多珍貴的鐵道文化資產，並將1960-70年代鐵道貨運全盛時期的氛圍，原汁原味保存展示，提供參觀者豐富的時空體驗。2017年9月輕軌哈瑪星站通車，10月1日起本館更名為舊打狗驛故事館。', '高雄市立歷史博物館', '高雄市鼓山區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '鼓山區（高雄市）=', 22.65019525, 120.274163, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='舊打狗驛故事館常設展', `description`='打狗鐵道故事館為台鐵高雄港車站轉變而來，目前館內保留了許多珍貴的鐵道文化資產，並將1960-70年代鐵道貨運全盛時期的氛圍，原汁原味保存展示，提供參觀者豐富的時空體驗。2017年9月輕軌哈瑪星站通車，10月1日起本館更名為舊打狗驛故事館。', `organizer`='高雄市立歷史博物館', `address`='高雄市鼓山區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='鼓山區（高雄市）=', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0326b3240c403d94d8', '見城館常設展', '「見城館」以左營「鳳山縣舊城」歷史為核心，為全臺唯一結合光雕投影且動態演繹百年歷史的舊城模型展示，新科技演繹老歷史，一樓展示空間有具科技性的AR「穿越時空見城」及二樓VR「我們的舊城」的互動裝置設計，企望重新詮釋並再現舊城自明鄭迄今的歷史軌跡，讓民眾享受如重臨百年舊城、跨越古今的3D互動實感體驗，帶你穿越時空遊舊城。', '高雄市立歷史博物館', '高雄市左營區龜山巷157-2號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '見城館', 22.68395699, 120.2951588, '優待票+29;團體票+39;一般民眾+49', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='見城館常設展', `description`='「見城館」以左營「鳳山縣舊城」歷史為核心，為全臺唯一結合光雕投影且動態演繹百年歷史的舊城模型展示，新科技演繹老歷史，一樓展示空間有具科技性的AR「穿越時空見城」及二樓VR「我們的舊城」的互動裝置設計，企望重新詮釋並再現舊城自明鄭迄今的歷史軌跡，讓民眾享受如重臨百年舊城、跨越古今的3D互動實感體驗，帶你穿越時空遊舊城。', `organizer`='高雄市立歷史博物館', `address`='高雄市左營區龜山巷157-2號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='見城館', `latitude`=22.68395699, `longitude`=120.2951588, `ticket_price`='優待票+29;團體票+39;一般民眾+49', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0326b3240c403d94d9', '南國故鄉：柯旗化故居常設展', '為紀念已故柯旗化先生的貢獻，以其故居轉化為展示空間，部分家具陳設保留當時生活場景，搭配書信、照片等相關文物展示；並以柯旗化先生經歷為切入點，以情境互動裝置設計，帶出白色恐怖與高雄人權運動的時代背景，期望呈現台灣民主進程，並紀念這位及英文文法家、作家與政治受難者等多重身分於一身的先行者。', '高雄市立歷史博物館', '高雄市新興區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '新興區（高雄市）=', 22.62992906, 120.3067337, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南國故鄉：柯旗化故居常設展', `description`='為紀念已故柯旗化先生的貢獻，以其故居轉化為展示空間，部分家具陳設保留當時生活場景，搭配書信、照片等相關文物展示；並以柯旗化先生經歷為切入點，以情境互動裝置設計，帶出白色恐怖與高雄人權運動的時代背景，期望呈現台灣民主進程，並紀念這位及英文文法家、作家與政治受難者等多重身分於一身的先行者。', `organizer`='高雄市立歷史博物館', `address`='高雄市新興區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='新興區（高雄市）=', `latitude`=22.62992906, `longitude`=120.3067337, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0326b3240c403d94da', '高雄市皮影戲館常設展', '館內常設展覽亦重新規劃，不僅展示皮影戲偶、樂器、燈光、影窗等文物，更強調互動體驗與視覺效果的變化，像是設計早期皮影戲演出的暗室，搭設原始牛車戲台，享受最真實的古早味光、影演出實境。創新的親子劇場則設計可移動式舞台及親子座位，除讓偶戲演出有無限的可能，更拉近民眾之間的距離。難到來到皮影戲館的民眾，還可以在影藏1號店選購皮影戲館獨家設計的文創商品作為紀念。', '高雄市立歷史博物館', '高雄市岡山區009鄰岡山南路42號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市皮影戲館常設展', `description`='館內常設展覽亦重新規劃，不僅展示皮影戲偶、樂器、燈光、影窗等文物，更強調互動體驗與視覺效果的變化，像是設計早期皮影戲演出的暗室，搭設原始牛車戲台，享受最真實的古早味光、影演出實境。創新的親子劇場則設計可移動式舞台及親子座位，除讓偶戲演出有無限的可能，更拉近民眾之間的距離。難到來到皮影戲館的民眾，還可以在影藏1號店選購皮影戲館獨家設計的文創商品作為紀念。', `organizer`='高雄市立歷史博物館', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0326b3240c403d94db', '回‧聲－皮影戲的跨域藝術', '在光影的印照下，戲偶活靈活現的舞動，吸引觀眾的目光與喝采。影窗前總是焦點，很少人關注影窗後的精彩。皮偶與戲台僅是一個物件，台詞本身也沒有生命，在窗影後的藝師藉由自己的生命經驗與經歷，賦予皮偶靈魂，透過操偶的動作，搭配著旁白的抑揚頓挫，表達出皮影的性感與性格，「人」與「偶」合一才能具備整齣戲的生命力。本次展覽藉由跨藝術的展現，將焦點放回藝師個「人」身上，從聲音與記憶的藝術創作，以不同的視野，帶領觀眾認識藝師的技藝與記憶。', '高雄市立歷史博物館', '高雄市岡山區009鄰岡山南路42號', '2025-01-01 00:00:00', '2025-06-01 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='回‧聲－皮影戲的跨域藝術', `description`='在光影的印照下，戲偶活靈活現的舞動，吸引觀眾的目光與喝采。影窗前總是焦點，很少人關注影窗後的精彩。皮偶與戲台僅是一個物件，台詞本身也沒有生命，在窗影後的藝師藉由自己的生命經驗與經歷，賦予皮偶靈魂，透過操偶的動作，搭配著旁白的抑揚頓挫，表達出皮影的性感與性格，「人」與「偶」合一才能具備整齣戲的生命力。本次展覽藉由跨藝術的展現，將焦點放回藝師個「人」身上，從聲音與記憶的藝術創作，以不同的視野，帶領觀眾認識藝師的技藝與記憶。', `organizer`='高雄市立歷史博物館', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0326b3240c403d94dd', '林芬美「遊於藝創作個展」', '安平區公所區政藝廊推出林芬美老師「遊於藝創作個展」，展出林老師精選風景畫作，老師居住於安平區，作品除從住處安平出發取材外，亦以作品記錄了老師與家人旅遊至各處之足跡，諸如:安平望月、安平魚塭、法國小徑……等創作。  ', '臺南市安平區公所', '臺南市安平區安北路42號', '2025-02-07 00:00:00', '2025-04-30 00:00:00', '臺南市安平區公所', 22.99008437, 120.1649949, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='林芬美「遊於藝創作個展」', `description`='安平區公所區政藝廊推出林芬美老師「遊於藝創作個展」，展出林老師精選風景畫作，老師居住於安平區，作品除從住處安平出發取材外，亦以作品記錄了老師與家人旅遊至各處之足跡，諸如:安平望月、安平魚塭、法國小徑……等創作。  ', `organizer`='臺南市安平區公所', `address`='臺南市安平區安北路42號', `start_date`='2025-02-07 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市安平區公所', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0326b3240c403d94df', '人體藝術之美－20mins Sketch聯展', '本展主題以人為主，媒材有素描、水彩、油畫、速寫、塑造 …等，在巧思下，善用熟悉的媒材，各有巧妙趣味性，風格從傳統具象寫實到半抽象、立體。人體美學的表達平易，不高深，需長期持續並堅持。做對的事，自己走過的路，印象最清楚，並懇請各界指教。', '高雄市政府文化局', '高雄市岡山區009鄰岡山南路42號', '2025-02-12 00:00:00', '2025-03-02 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='人體藝術之美－20mins Sketch聯展', `description`='本展主題以人為主，媒材有素描、水彩、油畫、速寫、塑造 …等，在巧思下，善用熟悉的媒材，各有巧妙趣味性，風格從傳統具象寫實到半抽象、立體。人體美學的表達平易，不高深，需長期持續並堅持。做對的事，自己走過的路，印象最清楚，並懇請各界指教。', `organizer`='高雄市政府文化局', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-02-12 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbd0326b3240c403d94e1', '『二月』好書推薦主題書展', '知識的意義不在於追逐名利，在於內心充實及對真理的渴望，懂得珍惜眼前的風景，感受當下的滿足，唯有知足，才能自足。\r\n展出書目：霸稜真相，可能跟你想的不一樣、職場霸凌： 法律調停專家教你維護職場權益，化解工作場合的欺壓侵犯、陪孩子面對霸凌：父母師長的行動指南、人生很難， 你可以不必假裝強大、走吧！去做你真正渴望的事：創造有意義人生的7分鐘微行動、地球另一端的眼淚：知足-我在人道救援的1000天後學到的事、荷蘭-小國大幸福：與天合作-知足常樂、你不可以霸凌我、佛洛姆：自由自在活著，不怕孤獨等。', '高雄市立圖書館總館', '高雄市田寮區17鄰崗安路71-1號', '2025-02-10 00:00:00', '2025-02-28 00:00:00', '高雄市立圖書館田寮分館', 22.8633474, 120.4011911, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='『二月』好書推薦主題書展', `description`='知識的意義不在於追逐名利，在於內心充實及對真理的渴望，懂得珍惜眼前的風景，感受當下的滿足，唯有知足，才能自足。\r\n展出書目：霸稜真相，可能跟你想的不一樣、職場霸凌： 法律調停專家教你維護職場權益，化解工作場合的欺壓侵犯、陪孩子面對霸凌：父母師長的行動指南、人生很難， 你可以不必假裝強大、走吧！去做你真正渴望的事：創造有意義人生的7分鐘微行動、地球另一端的眼淚：知足-我在人道救援的1000天後學到的事、荷蘭-小國大幸福：與天合作-知足常樂、你不可以霸凌我、佛洛姆：自由自在活著，不怕孤獨等。', `organizer`='高雄市立圖書館總館', `address`='高雄市田寮區17鄰崗安路71-1號', `start_date`='2025-02-10 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='高雄市立圖書館田寮分館', `latitude`=22.8633474, `longitude`=120.4011911, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
