INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf42c26b3240c403d9503', '｢糖、香料，與一切美好的事物」— 曾詠晴個展', '一場讓｢粉紅色｣佔據版面和話語權，主導畫面與敘事的展覽，作品中用甜美討喜的流行元素裝飾反諷、美化、包裝，訴說「他者」被邊緣化的性別定位、種族差異、社會身份與殖民歷史記憶。粉紅色這個色彩本身就有著矛盾的多重定義，讓人貼上各種刻板標籤，正向或負面，都可能引發好惡分明的反應。\r\n藝術家身為台灣巴基斯坦混血，成長於中東，同時身為女性、有色人種、及伊斯蘭教徒，以當今西方世界主導的視角，本人即是十足的「他者」三重奏。\r\n她將粉紅色視為和自己一樣的「他者」去共感思考，作品中以拼貼媒材展現女性元素、服飾意象、傳統圖騰，串聯全球南方多重文化的生命軌跡，作為西方價值的鏡像反面，也帶來權勢倒置的視覺挑戰。', '新浜碼頭藝術空間', '高雄市鹽埕區015鄰大勇路64號2樓', '2025-02-06 00:00:00', '2025-03-06 00:00:00', '新浜碼頭藝術空間', 22.6228436, 120.2835667, '無資料', 'https://sinpink.com', '[]') ON DUPLICATE KEY UPDATE `activity_name`='｢糖、香料，與一切美好的事物」— 曾詠晴個展', `description`='一場讓｢粉紅色｣佔據版面和話語權，主導畫面與敘事的展覽，作品中用甜美討喜的流行元素裝飾反諷、美化、包裝，訴說「他者」被邊緣化的性別定位、種族差異、社會身份與殖民歷史記憶。粉紅色這個色彩本身就有著矛盾的多重定義，讓人貼上各種刻板標籤，正向或負面，都可能引發好惡分明的反應。\r\n藝術家身為台灣巴基斯坦混血，成長於中東，同時身為女性、有色人種、及伊斯蘭教徒，以當今西方世界主導的視角，本人即是十足的「他者」三重奏。\r\n她將粉紅色視為和自己一樣的「他者」去共感思考，作品中以拼貼媒材展現女性元素、服飾意象、傳統圖騰，串聯全球南方多重文化的生命軌跡，作為西方價值的鏡像反面，也帶來權勢倒置的視覺挑戰。', `organizer`='新浜碼頭藝術空間', `address`='高雄市鹽埕區015鄰大勇路64號2樓', `start_date`='2025-02-06 00:00:00', `end_date`='2025-03-06 00:00:00', `location`='新浜碼頭藝術空間', `latitude`=22.6228436, `longitude`=120.2835667, `ticket_price`='無資料', `source_url`='https://sinpink.com', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf42d26b3240c403d9504', '114年3月FUN心聽故事', '由故事達人透過繪本故事說演，引導親子共讀繪本故事，進入故事情境，進而喜歡閱讀，並配合親子共讀，設計延伸活動。\r\n3/1 蔡芝芬老師/繪本閱讀趣\r\n3/8 許靜淑老師 /繪本童樂會\r\n3/15林春秀老師 /童繪島\r\n3/22潘慧君老師 /英文繪本故事', '高雄市立圖書館總館', '高雄市路竹區24鄰國昌路86巷9號', '2025-03-01 00:00:00', '2025-03-22 00:00:00', '高雄市立圖書館路竹分館', 22.8541831, 120.2611866, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年3月FUN心聽故事', `description`='由故事達人透過繪本故事說演，引導親子共讀繪本故事，進入故事情境，進而喜歡閱讀，並配合親子共讀，設計延伸活動。\r\n3/1 蔡芝芬老師/繪本閱讀趣\r\n3/8 許靜淑老師 /繪本童樂會\r\n3/15林春秀老師 /童繪島\r\n3/22潘慧君老師 /英文繪本故事', `organizer`='高雄市立圖書館總館', `address`='高雄市路竹區24鄰國昌路86巷9號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='高雄市立圖書館路竹分館', `latitude`=22.8541831, `longitude`=120.2611866, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf42d26b3240c403d9505', '114年路竹分館3月書展', '1.童心繪夢閱讀奇遇:用台語話故事，用雙手繪童夢:精心佈置書展展區!走進台語的世界，開啟繪本的奇幻旅程！熱情邀約故事達人以流利台語講述經典與創意繪本故事，讓孩子在聆聽中學習母語。活動中，我們用台語「話」出充滿溫度的故事，邀請大朋友與小朋友一同感受母語的魅力。在故事聲中，我們將動手創作，設計多樣化的手作活動，透過台語故事與手作，為童心添上最美的色彩，用雙手共同繪出專屬於童年的美好夢境。\r\n2.閱讀無界：越語繪卷,語言文化風采之美:越南語是東南亞地區獨具特色的一種語言，它既承載著深厚的歷史，也展現了豐富的文化風采。提供書展引領讀者於字裡行間,感受越南語的藝術魅力，並穿越文化的邊界，體驗越南語言文學世界的獨特之美及越南語言如何在時代洪流中傳遞民族情感、記錄文化記憶，並與世界接軌。', '高雄市立圖書館總館', '高雄市路竹區24鄰國昌路86巷9號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '高雄市立圖書館路竹分館', 22.8541831, 120.2611866, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年路竹分館3月書展', `description`='1.童心繪夢閱讀奇遇:用台語話故事，用雙手繪童夢:精心佈置書展展區!走進台語的世界，開啟繪本的奇幻旅程！熱情邀約故事達人以流利台語講述經典與創意繪本故事，讓孩子在聆聽中學習母語。活動中，我們用台語「話」出充滿溫度的故事，邀請大朋友與小朋友一同感受母語的魅力。在故事聲中，我們將動手創作，設計多樣化的手作活動，透過台語故事與手作，為童心添上最美的色彩，用雙手共同繪出專屬於童年的美好夢境。\r\n2.閱讀無界：越語繪卷,語言文化風采之美:越南語是東南亞地區獨具特色的一種語言，它既承載著深厚的歷史，也展現了豐富的文化風采。提供書展引領讀者於字裡行間,感受越南語的藝術魅力，並穿越文化的邊界，體驗越南語言文學世界的獨特之美及越南語言如何在時代洪流中傳遞民族情感、記錄文化記憶，並與世界接軌。', `organizer`='高雄市立圖書館總館', `address`='高雄市路竹區24鄰國昌路86巷9號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='高雄市立圖書館路竹分館', `latitude`=22.8541831, `longitude`=120.2611866, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf43026b3240c403d9506', '台語閱讀與手作', '1.3/8陳竑棛(默默老師):推廣世界母語日，利用台灣原創繪本導讀，讓學齡兒童認識台語，增加手作加深對繪本的印象。繪本導讀:五顏六色的市場\r\n2.3/15蔡芝芬老師:世界母語日，目標是向全球宣傳保護語言的重要，促進母語傳播的運動，避免地球大部分語言的消失。繪本導讀:西北雨\r\n第一節課\r\n藉由講故事來詮釋，歌謠西北雨中的歌詞意境。再藉由歌詞中的魚類來認識台灣本土魚的名稱及母語發音。最後再以輕鬆活潑的歌唱律動來結束。\r\n第二節課\r\n手作DIY:魚吊飾\r\n3.3/22陳竑棛(默默老師):推廣世界母語日，利用台灣原創繪本導讀，讓學齡兒童認識台語，增加手作加深對繪本的印象。繪本導讀:食飽沒', '高雄市立圖書館總館', '高雄市路竹區24鄰國昌路86巷9號', '2025-03-08 00:00:00', '2025-03-22 00:00:00', '高雄市立圖書館路竹分館', 22.8541831, 120.2611866, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台語閱讀與手作', `description`='1.3/8陳竑棛(默默老師):推廣世界母語日，利用台灣原創繪本導讀，讓學齡兒童認識台語，增加手作加深對繪本的印象。繪本導讀:五顏六色的市場\r\n2.3/15蔡芝芬老師:世界母語日，目標是向全球宣傳保護語言的重要，促進母語傳播的運動，避免地球大部分語言的消失。繪本導讀:西北雨\r\n第一節課\r\n藉由講故事來詮釋，歌謠西北雨中的歌詞意境。再藉由歌詞中的魚類來認識台灣本土魚的名稱及母語發音。最後再以輕鬆活潑的歌唱律動來結束。\r\n第二節課\r\n手作DIY:魚吊飾\r\n3.3/22陳竑棛(默默老師):推廣世界母語日，利用台灣原創繪本導讀，讓學齡兒童認識台語，增加手作加深對繪本的印象。繪本導讀:食飽沒', `organizer`='高雄市立圖書館總館', `address`='高雄市路竹區24鄰國昌路86巷9號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='高雄市立圖書館路竹分館', `latitude`=22.8541831, `longitude`=120.2611866, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf43026b3240c403d9507', 'FUN心聽故事(中庄分館3月份)', '孩子是精靈，故事是魔法棒，點綴孩子的心，開啟孩子的夢，透過故事達人的口，故事將變成幸福的種子，灑向每個角落，讓小朋友的世界變成一座開滿五彩繽紛幸福花朵的書香城市。', '高雄市立圖書館總館', '高雄市大寮區40鄰光明路3段1437號', '2025-03-01 00:00:00', '2025-03-15 00:00:00', '高雄市立圖書館中庄分館', 22.6285347, 120.4098142, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽故事(中庄分館3月份)', `description`='孩子是精靈，故事是魔法棒，點綴孩子的心，開啟孩子的夢，透過故事達人的口，故事將變成幸福的種子，灑向每個角落，讓小朋友的世界變成一座開滿五彩繽紛幸福花朵的書香城市。', `organizer`='高雄市立圖書館總館', `address`='高雄市大寮區40鄰光明路3段1437號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='高雄市立圖書館中庄分館', `latitude`=22.6285347, `longitude`=120.4098142, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf43026b3240c403d9508', '翠屏分館114年3月FUN心聽故事', '由高雄市立圖書館所培訓的一群義務故事志工，透過生動有趣的說演方式說故事的親子活動~\r\n歡迎大手牽小手一起來參加。\r\n本活動免費參加~自由入場\r\n', '高雄市立圖書館總館', '高雄市楠梓區德惠路55號3樓', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '高雄市立圖書館翠屏分館', 22.7267707, 120.302985, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='翠屏分館114年3月FUN心聽故事', `description`='由高雄市立圖書館所培訓的一群義務故事志工，透過生動有趣的說演方式說故事的親子活動~\r\n歡迎大手牽小手一起來參加。\r\n本活動免費參加~自由入場\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市楠梓區德惠路55號3樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='高雄市立圖書館翠屏分館', `latitude`=22.7267707, `longitude`=120.302985, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf43126b3240c403d9509', '世界母語日-台語繪出台灣味', '透過繪本《十粒卵》看圖、讀內容，讓孩子發揮想像力、及觀察力，帶領孩子運用（五感）觸覺、聽覺、視覺、嗅覺、味覺來一同享受這個可愛的故事。\r\n配合繪本《十粒卵》延伸簡單的歌謠，及台語歌謠：《煎卵歌》帶動唱，來增加趣味性。\r\n', '高雄市立圖書館總館', '高雄市旗山區大德里6鄰中學路42號', '2025-03-12 00:00:00', '2025-03-12 00:00:00', '高雄市立圖書館旗山分館', 25.0421407, 121.5198716, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='世界母語日-台語繪出台灣味', `description`='透過繪本《十粒卵》看圖、讀內容，讓孩子發揮想像力、及觀察力，帶領孩子運用（五感）觸覺、聽覺、視覺、嗅覺、味覺來一同享受這個可愛的故事。\r\n配合繪本《十粒卵》延伸簡單的歌謠，及台語歌謠：《煎卵歌》帶動唱，來增加趣味性。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市旗山區大德里6鄰中學路42號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-03-12 00:00:00', `location`='高雄市立圖書館旗山分館', `latitude`=25.0421407, `longitude`=121.5198716, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf43426b3240c403d950a', 'FUN心聽故事(澄觀分館114年03月)', '由高雄市立圖書館所培訓的一群義務故事志工，透過豐富的肢體語言與生動有趣的互動方式，為小朋友說故事，歡迎親子一起參加！【本活動免費參加，自由入場（禁止攜帶飲料、食物）】。', '高雄市立圖書館總館', '高雄市仁武區005鄰澄仁路200號', '2025-03-14 00:00:00', '2025-03-28 00:00:00', '高雄市立圖書館澄觀分館', 22.6803285, 120.3446974, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽故事(澄觀分館114年03月)', `description`='由高雄市立圖書館所培訓的一群義務故事志工，透過豐富的肢體語言與生動有趣的互動方式，為小朋友說故事，歡迎親子一起參加！【本活動免費參加，自由入場（禁止攜帶飲料、食物）】。', `organizer`='高雄市立圖書館總館', `address`='高雄市仁武區005鄰澄仁路200號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='高雄市立圖書館澄觀分館', `latitude`=22.6803285, `longitude`=120.3446974, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
