INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf43626b3240c403d950e', 'Fun心聽故事(鹽埕分館2025年3月)', '由高雄市立圖書館所培訓的故事志工，透過豐富的肢體語言與生動有趣的互動方式，為小朋友說故事，歡迎親子一起參加！本活動免費參加，自由入場（禁止攜帶飲料、食物）', '高雄市立圖書館總館', '高雄市鹽埕區1鄰大仁路179號5樓、6樓', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館鹽埕分館', 22.626715, 120.281874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Fun心聽故事(鹽埕分館2025年3月)', `description`='由高雄市立圖書館所培訓的故事志工，透過豐富的肢體語言與生動有趣的互動方式，為小朋友說故事，歡迎親子一起參加！本活動免費參加，自由入場（禁止攜帶飲料、食物）', `organizer`='高雄市立圖書館總館', `address`='高雄市鹽埕區1鄰大仁路179號5樓、6樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館鹽埕分館', `latitude`=22.626715, `longitude`=120.281874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf43826b3240c403d950f', '說說唱唱-陪寶貝讀繪本', '03/01 世界第一長的圍巾、猜一猜我喜歡吃什麼?、彩虹花/林月娥、范秀盈老師帶領\r\n03/02 野貓軍團飛上天、第七位客人、金鳥；羽毛婆婆/周紫榮、楊秀貞老師帶領\r\n03/07 阿吉的魔法紅球、阿寶的生日禮物、我是大象過獨木橋/古馨如、梁台玲、黃美芳老師帶領\r\n03/08 不想告訴媽媽的祕密、猴與龜、一隻減肥的豬/陳玲月、葉惠喜、孫若薇老師帶領\r\n03/09 我要吃掉你、不會寫字的獅子、神探狗汪汪/李素榮、梁台玲老師帶領\r\n03/14 五個黃金罈子、九層之家、和獅子一起去上學/張美君、林忍老師帶領\r\n03/15 月亮，你好嗎?、我不怕，我再試試看、是蝸牛開始的/范秀盈、陳玲月、熊筱薇老師帶領\r\n03/16 躱貓貓真好玩、酪梨很想問：我是水果還是蔬菜？、真的!/楊秀貞、林月娥老師帶領\r\n03/21 呼～吸～、稻米仙女、紅龜粿chhōe姊妹/楊秀貞、姚慧琪老師帶領\r\n03/22 感冒的魚、動物大派對、克利的微笑 /林月娥、丘淑芳、葉惠喜老師帶領\r\n03/23 鴨子家族大搬家、小鵪鶉捉迷藏、小美一個人看家/李素榮、陳秀和、熊筱薇老師帶領\r\n03/28 小彌的奇幻之旅、獅子變小了?、14隻老鼠搗年糕/張美君、呂淑貞老師帶領\r\n03/29 餃子阿嬤、南瓜湯、新老鼠娶親/范秀盈、陳玲月老師帶領\r\n03/30 野貓軍團開火車、世界上最棒的蛇、蘋果國王/范秀盈、林月娥老師帶領', '高雄市立圖書館總館', '高雄市鼓山區4鄰鼓山三路19-3號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館鼓山分館', 22.6544722, 120.275386, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='說說唱唱-陪寶貝讀繪本', `description`='03/01 世界第一長的圍巾、猜一猜我喜歡吃什麼?、彩虹花/林月娥、范秀盈老師帶領\r\n03/02 野貓軍團飛上天、第七位客人、金鳥；羽毛婆婆/周紫榮、楊秀貞老師帶領\r\n03/07 阿吉的魔法紅球、阿寶的生日禮物、我是大象過獨木橋/古馨如、梁台玲、黃美芳老師帶領\r\n03/08 不想告訴媽媽的祕密、猴與龜、一隻減肥的豬/陳玲月、葉惠喜、孫若薇老師帶領\r\n03/09 我要吃掉你、不會寫字的獅子、神探狗汪汪/李素榮、梁台玲老師帶領\r\n03/14 五個黃金罈子、九層之家、和獅子一起去上學/張美君、林忍老師帶領\r\n03/15 月亮，你好嗎?、我不怕，我再試試看、是蝸牛開始的/范秀盈、陳玲月、熊筱薇老師帶領\r\n03/16 躱貓貓真好玩、酪梨很想問：我是水果還是蔬菜？、真的!/楊秀貞、林月娥老師帶領\r\n03/21 呼～吸～、稻米仙女、紅龜粿chhōe姊妹/楊秀貞、姚慧琪老師帶領\r\n03/22 感冒的魚、動物大派對、克利的微笑 /林月娥、丘淑芳、葉惠喜老師帶領\r\n03/23 鴨子家族大搬家、小鵪鶉捉迷藏、小美一個人看家/李素榮、陳秀和、熊筱薇老師帶領\r\n03/28 小彌的奇幻之旅、獅子變小了?、14隻老鼠搗年糕/張美君、呂淑貞老師帶領\r\n03/29 餃子阿嬤、南瓜湯、新老鼠娶親/范秀盈、陳玲月老師帶領\r\n03/30 野貓軍團開火車、世界上最棒的蛇、蘋果國王/范秀盈、林月娥老師帶領', `organizer`='高雄市立圖書館總館', `address`='高雄市鼓山區4鄰鼓山三路19-3號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館鼓山分館', `latitude`=22.6544722, `longitude`=120.275386, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf43826b3240c403d9510', '鼓山電影院：共賞《丹麥女孩(The Danish Girl)》', '鼓山電影院：共賞《丹麥女孩(The Danish Girl)》\r\n(長度：120分，劇情類，級別：輔導級)。\r\n\r\n《丹麥女孩》（英語：The Danish Girl）是一部2015年英美傳記劇情電影，由湯姆·霍伯執導，改編自大衛·埃伯肖夫於2000年出版的同名小說，以丹麥畫家莉莉·埃爾伯與格蕾塔·魏格納生活為靈感啟發，他是已知最早接受性別重置手術的人。', '高雄市立圖書館總館', '高雄市鼓山區4鄰鼓山三路19-3號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '高雄市立圖書館鼓山分館', 22.6544722, 120.275386, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鼓山電影院：共賞《丹麥女孩(The Danish Girl)》', `description`='鼓山電影院：共賞《丹麥女孩(The Danish Girl)》\r\n(長度：120分，劇情類，級別：輔導級)。\r\n\r\n《丹麥女孩》（英語：The Danish Girl）是一部2015年英美傳記劇情電影，由湯姆·霍伯執導，改編自大衛·埃伯肖夫於2000年出版的同名小說，以丹麥畫家莉莉·埃爾伯與格蕾塔·魏格納生活為靈感啟發，他是已知最早接受性別重置手術的人。', `organizer`='高雄市立圖書館總館', `address`='高雄市鼓山區4鄰鼓山三路19-3號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='高雄市立圖書館鼓山分館', `latitude`=22.6544722, `longitude`=120.275386, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf43d26b3240c403d9513', '【導覽】群生藝相：書畫中的動物形象與其意涵', '主講人：賴國生；國立故宮博物院南院處助理研究員\r\n​名額20名。', '國立故宮博物院', '嘉義縣太保市故宮大道888號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '國立故宮博物院南部院區', 23.4704066, 120.2913281, '無資料', 'https://south.npm.gov.tw/ActivityInfoDetailC003210.aspx?Cond=c86e3732-024a-4121-9d75-2486da1f40a5&ap', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【導覽】群生藝相：書畫中的動物形象與其意涵', `description`='主講人：賴國生；國立故宮博物院南院處助理研究員\r\n​名額20名。', `organizer`='國立故宮博物院', `address`='嘉義縣太保市故宮大道888號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='國立故宮博物院南部院區', `latitude`=23.4704066, `longitude`=120.2913281, `ticket_price`='無資料', `source_url`='https://south.npm.gov.tw/ActivityInfoDetailC003210.aspx?Cond=c86e3732-024a-4121-9d75-2486da1f40a5&ap', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf43d26b3240c403d9514', '群生藝相-書畫中的動物形象與意涵', '動物是人類在地球上最親密的夥伴。從遠古的神話時代直到現在，牠們不斷以各種型態出現在人類生活的各種層面，伴隨人類文明發展的進程。\r\n在書畫、文學等藝術作品中，動物的出現尤其頻繁且精采。古今中外的藝術家們，持續以客觀的描寫或主觀的想像等方式，表現人類對動物的想法與感受。大量優秀藝術作品根據動物創造、渲染出各種意象，並賦予深刻的內涵，使之雋永。\r\n有鑑於此，本展覽敬邀觀眾欣賞院藏有關動物的書畫作品，探究其意象及其美感之底蘊。', '國立故宮博物院', '嘉義縣太保市故宮大道888號', '2025-01-14 00:00:00', '2025-04-13 00:00:00', '國立故宮博物院南部院區', 23.4704066, 120.2913281, '全票+150;優待票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='群生藝相-書畫中的動物形象與意涵', `description`='動物是人類在地球上最親密的夥伴。從遠古的神話時代直到現在，牠們不斷以各種型態出現在人類生活的各種層面，伴隨人類文明發展的進程。\r\n在書畫、文學等藝術作品中，動物的出現尤其頻繁且精采。古今中外的藝術家們，持續以客觀的描寫或主觀的想像等方式，表現人類對動物的想法與感受。大量優秀藝術作品根據動物創造、渲染出各種意象，並賦予深刻的內涵，使之雋永。\r\n有鑑於此，本展覽敬邀觀眾欣賞院藏有關動物的書畫作品，探究其意象及其美感之底蘊。', `organizer`='國立故宮博物院', `address`='嘉義縣太保市故宮大道888號', `start_date`='2025-01-14 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='國立故宮博物院南部院區', `latitude`=23.4704066, `longitude`=120.2913281, `ticket_price`='全票+150;優待票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf44326b3240c403d9516', '無資料', '平常生活走過、路過的地方，現在有機會讓我們了解這些故事。\r\n本次走讀邀請藝術教育工作者一李意婕，攜手一群新營地區高中師生，帶領大家探索新營的「白色歷史」人權地景。\r\n故事圍繞1953年被槍決的糖廠技術員李明珠及其牽涉的「碗公會事件」，本活動將透過走訪、聽導還原他倉促的一生。\r\n| 走讀路線| 新營曬書店（文本導讀）一臺南市政府警察局新營分局（原台南縣警局）一新營圓環一第一市場一上帝廟一舊廠前站一新營糖廠一公誠國小（原公誠代用國民學校）一新營曬書店（心得分享與回饋）\r\n|走讀文本|《不只哀悼：如果記憶有形狀》、《等待天光：臺南人權歷史場址II》', '曬書店X新營市民學堂', '臺南市新營區中山路93-2號2樓', '曬書店×新營市民學堂', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='平常生活走過、路過的地方，現在有機會讓我們了解這些故事。\r\n本次走讀邀請藝術教育工作者一李意婕，攜手一群新營地區高中師生，帶領大家探索新營的「白色歷史」人權地景。\r\n故事圍繞1953年被槍決的糖廠技術員李明珠及其牽涉的「碗公會事件」，本活動將透過走訪、聽導還原他倉促的一生。\r\n| 走讀路線| 新營曬書店（文本導讀）一臺南市政府警察局新營分局（原台南縣警局）一新營圓環一第一市場一上帝廟一舊廠前站一新營糖廠一公誠國小（原公誠代用國民學校）一新營曬書店（心得分享與回饋）\r\n|走讀文本|《不只哀悼：如果記憶有形狀》、《等待天光：臺南人權歷史場址II》', `organizer`='曬書店X新營市民學堂', `address`='臺南市新營區中山路93-2號2樓', `location`='曬書店×新營市民學堂', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf44326b3240c403d9517', '小橋・流水・無人家-二呆的「橋」特展', '二呆藝館典藏趙同和千餘件藝術作品，其中有關於「橋」的作品計40幅，包含水墨、油畫及素描。本展擷取元曲《天淨沙・秋思》一句「小橋流水人家」為引，片段中好似安逸閑居的田園生活，而不是天涯遊子的思愁。「擷取片段」乃為平面藝術作品的特色，如何在風景畫中產生時間的流動，便仰賴觀者的想像。「人家」，據教育部重編國語辭典修訂本作為住宅、稱呼他人…等用法，本展以「他人」為解釋，並以「無」字作為破題，傳達展出作品，雖有人的生活建築設施，如小橋、舟船或房舍，卻少有人物的出現。「橋」向來為中國水墨畫的「點景」，但在本展將轉換配角的身分，作為帶領觀眾走入畫中世界的媒介。', '澎湖縣政府文化局', '澎湖縣馬公市中華路230號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '澎湖縣政府文化局', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='小橋・流水・無人家-二呆的「橋」特展', `description`='二呆藝館典藏趙同和千餘件藝術作品，其中有關於「橋」的作品計40幅，包含水墨、油畫及素描。本展擷取元曲《天淨沙・秋思》一句「小橋流水人家」為引，片段中好似安逸閑居的田園生活，而不是天涯遊子的思愁。「擷取片段」乃為平面藝術作品的特色，如何在風景畫中產生時間的流動，便仰賴觀者的想像。「人家」，據教育部重編國語辭典修訂本作為住宅、稱呼他人…等用法，本展以「他人」為解釋，並以「無」字作為破題，傳達展出作品，雖有人的生活建築設施，如小橋、舟船或房舍，卻少有人物的出現。「橋」向來為中國水墨畫的「點景」，但在本展將轉換配角的身分，作為帶領觀眾走入畫中世界的媒介。', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路230號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='澎湖縣政府文化局', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf44326b3240c403d951c', '2025鹿谷麒麟潭燈會', '內容：入口意象-迎賓團員慶佳年、九曲仙道、花香鳥語、麗谷麒麟、水上燈組、景觀台水面亮化、涼亭亮化、耀動湖畔、魚耀麒麟、花飄浮光與漫步蘆葦等。', '南投縣鹿谷鄉公所', '南投縣鹿谷鄉', '2025-01-24 00:00:00', '2025-03-16 00:00:00', '鹿谷鄉（南投縣）=', 23.73776029, 120.7815065, '無資料', 'https://www.facebook.com/profile.php?id=100064507040051', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025鹿谷麒麟潭燈會', `description`='內容：入口意象-迎賓團員慶佳年、九曲仙道、花香鳥語、麗谷麒麟、水上燈組、景觀台水面亮化、涼亭亮化、耀動湖畔、魚耀麒麟、花飄浮光與漫步蘆葦等。', `organizer`='南投縣鹿谷鄉公所', `address`='南投縣鹿谷鄉', `start_date`='2025-01-24 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='鹿谷鄉（南投縣）=', `latitude`=23.73776029, `longitude`=120.7815065, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064507040051', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf44326b3240c403d951d', '2025世界母語日-電影欣賞：柿子色的街灯、漂流遇見你', '響應世界母語日，辦理電影欣賞活動，播映：「柿子色的街灯」、「漂流遇見你」，讓民眾認知語言平等的重要性，進而學習自己的母語。\r\n放映影片：\r\n柿子色的街燈／普遍級、動畫片、120分鐘，客語發音。\r\n改編自臺灣客籍兒童文學作家陳素宜同名作品。片名具有客家味，內容也充滿客家傳風情，希望帶領孩子一起進入迷人詩意的童话世界。故事圍繞著主角可欣和失憶的姨婆發展，期間可欣經歷了一段奇幻旅程，和新認識的朋友小燕子一同冒險遊歷。在兩人愈來愈緊密的友谊過程中，可欣也一步步發現小燕子和姨婆之間的關聯。\r\n漂流遇見你／普遍級、紀錄片、90分鐘，國、法語發音。\r\n"人與人之間不要拒絕相遇"，而世界上有很多種人，會不會在世界的另一端，有一群跟自己有著相同文化背景與命運的人，在不同的地方漂流著？台灣原住民音樂人舒米恩與保卜，應<<只要我長大>>導演陳潔瑤邀請，跨越太平洋，到南太平洋的法屬小島：新喀里多尼亞，與當地原住民音樂人進行一趟音樂交流之旅，在經歷一個月的旅行中，他們與當地人一同生活，一起玩音樂，一起創作。在旅途結尾，他們發現了走向世界最重要的秘訣，就是尋回自己的根底。', '南投縣政府文化局', '南投縣南投市中興路669號', '2025-03-01 00:00:00', '2025-03-08 00:00:00', '南投縣政府文化局圖書館', 23.9027891, 120.691332, '無資料', 'https://www.nthcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025世界母語日-電影欣賞：柿子色的街灯、漂流遇見你', `description`='響應世界母語日，辦理電影欣賞活動，播映：「柿子色的街灯」、「漂流遇見你」，讓民眾認知語言平等的重要性，進而學習自己的母語。\r\n放映影片：\r\n柿子色的街燈／普遍級、動畫片、120分鐘，客語發音。\r\n改編自臺灣客籍兒童文學作家陳素宜同名作品。片名具有客家味，內容也充滿客家傳風情，希望帶領孩子一起進入迷人詩意的童话世界。故事圍繞著主角可欣和失憶的姨婆發展，期間可欣經歷了一段奇幻旅程，和新認識的朋友小燕子一同冒險遊歷。在兩人愈來愈緊密的友谊過程中，可欣也一步步發現小燕子和姨婆之間的關聯。\r\n漂流遇見你／普遍級、紀錄片、90分鐘，國、法語發音。\r\n"人與人之間不要拒絕相遇"，而世界上有很多種人，會不會在世界的另一端，有一群跟自己有著相同文化背景與命運的人，在不同的地方漂流著？台灣原住民音樂人舒米恩與保卜，應<<只要我長大>>導演陳潔瑤邀請，跨越太平洋，到南太平洋的法屬小島：新喀里多尼亞，與當地原住民音樂人進行一趟音樂交流之旅，在經歷一個月的旅行中，他們與當地人一同生活，一起玩音樂，一起創作。在旅途結尾，他們發現了走向世界最重要的秘訣，就是尋回自己的根底。', `organizer`='南投縣政府文化局', `address`='南投縣南投市中興路669號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='南投縣政府文化局圖書館', `latitude`=23.9027891, `longitude`=120.691332, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf44326b3240c403d951e', '週末電影院（114年3月）', '南投縣政府文化局圖書館7樓電影放映廳於星期六下午2時播放影片供民眾欣賞，提供您休閒娛樂的好去處！歡迎您全家前來圖書館欣賞影片。\r\n\r\n播放影片\r\n3月15日／我的大猩猩媽媽（保護級）\r\n3月22日／露西亞的願望-魔法時光機（普遍級）\r\n3月29日／美人魚-深海奇緣（普遍級）\r\n\r\n電影欣賞注意事項：                             \r\n一、請遵守電影分級制度：\r\n(一)普遍級：一般觀眾皆可觀賞。\r\n(二)保護級：未滿六歲之兒童不得觀賞，六歲以上未滿十二歲需父母一起觀賞、十二歲以上自行觀賞。\r\n(三)輔12級；未滿十二歲之兒童不宜觀賞。\r\n二、請於下午1：45後入場，2：00準時放映，敬請準時入場。\r\n三、請勿攜帶飲料及食物入內、手機敬請關機或設定震動狀態。\r\n四、電影播放中請勿任意走動或喧嘩，影響欣賞電影品質，謝謝合作。', '南投縣政府文化局', '南投縣南投市中興路669號', '2025-03-15 00:00:00', '2025-03-29 00:00:00', '南投縣政府文化局圖書館', 23.9027891, 120.691332, '無資料', 'https://www.nthcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='週末電影院（114年3月）', `description`='南投縣政府文化局圖書館7樓電影放映廳於星期六下午2時播放影片供民眾欣賞，提供您休閒娛樂的好去處！歡迎您全家前來圖書館欣賞影片。\r\n\r\n播放影片\r\n3月15日／我的大猩猩媽媽（保護級）\r\n3月22日／露西亞的願望-魔法時光機（普遍級）\r\n3月29日／美人魚-深海奇緣（普遍級）\r\n\r\n電影欣賞注意事項：                             \r\n一、請遵守電影分級制度：\r\n(一)普遍級：一般觀眾皆可觀賞。\r\n(二)保護級：未滿六歲之兒童不得觀賞，六歲以上未滿十二歲需父母一起觀賞、十二歲以上自行觀賞。\r\n(三)輔12級；未滿十二歲之兒童不宜觀賞。\r\n二、請於下午1：45後入場，2：00準時放映，敬請準時入場。\r\n三、請勿攜帶飲料及食物入內、手機敬請關機或設定震動狀態。\r\n四、電影播放中請勿任意走動或喧嘩，影響欣賞電影品質，謝謝合作。', `organizer`='南投縣政府文化局', `address`='南投縣南投市中興路669號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='南投縣政府文化局圖書館', `latitude`=23.9027891, `longitude`=120.691332, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf44326b3240c403d951f', '歡樂故事列車（114年3月）', '南投縣政府文化局舉辦歡樂故事列車活動，除了有說故事志工演說好聽有趣的童話故事給小朋友聽外，並於每月辦理一場英語故事屋活動，邀請佳音英語南投分校英文講師到圖書館說英文故事唱英文歌曲給小朋友聽。 \r\n歡樂故事列車活動除英語故事屋活動需事先報名外，其餘場次皆為自由入場。歡迎大朋友小朋友一起來圖書館聽故事，\r\n將帶你體驗多元化的繪本故事！\r\n活動洽詢：049-2221619轉201。', '南投縣政府文化局', '南投縣南投市中興路669號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '南投縣政府文化局圖書館', 23.9027891, 120.691332, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歡樂故事列車（114年3月）', `description`='南投縣政府文化局舉辦歡樂故事列車活動，除了有說故事志工演說好聽有趣的童話故事給小朋友聽外，並於每月辦理一場英語故事屋活動，邀請佳音英語南投分校英文講師到圖書館說英文故事唱英文歌曲給小朋友聽。 \r\n歡樂故事列車活動除英語故事屋活動需事先報名外，其餘場次皆為自由入場。歡迎大朋友小朋友一起來圖書館聽故事，\r\n將帶你體驗多元化的繪本故事！\r\n活動洽詢：049-2221619轉201。', `organizer`='南投縣政府文化局', `address`='南投縣南投市中興路669號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='南投縣政府文化局圖書館', `latitude`=23.9027891, `longitude`=120.691332, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf44326b3240c403d9520', '中興高中高三學生藝術創作展-光的書寫', '一場尋找光影現象的呈現，屬於觀察感受與思辯的體驗，期許彼此在這溫馨的學習環境中，共同尋找屬於自己、獨一無二的記憶與情感，徜徉在月光中的浪漫，遨遊在湛藍的夢幻海進行探險，找到屬於自己的獨特光彩。高三學生作品展，豐富多樣，歡迎前往參觀。', '國立中興高級中學', '南投縣南投市中興新村中學路2號', '2025-02-10 00:00:00', '2025-03-14 00:00:00', '國立中興高級中學', 23.9179739, 120.6774812, '無資料', 'https://www.facebook.com/chsh.library', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中興高中高三學生藝術創作展-光的書寫', `description`='一場尋找光影現象的呈現，屬於觀察感受與思辯的體驗，期許彼此在這溫馨的學習環境中，共同尋找屬於自己、獨一無二的記憶與情感，徜徉在月光中的浪漫，遨遊在湛藍的夢幻海進行探險，找到屬於自己的獨特光彩。高三學生作品展，豐富多樣，歡迎前往參觀。', `organizer`='國立中興高級中學', `address`='南投縣南投市中興新村中學路2號', `start_date`='2025-02-10 00:00:00', `end_date`='2025-03-14 00:00:00', `location`='國立中興高級中學', `latitude`=23.9179739, `longitude`=120.6774812, `ticket_price`='無資料', `source_url`='https://www.facebook.com/chsh.library', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf44326b3240c403d9521', '圖畫生態˙漫游古書—袁金塔2025台江特展', '袁金塔，1949年生於彰化，為現代水墨與複合媒材藝術大師，曾任國立台灣師範大學教授及當代美術館館長。其作品融合東西方藝術理念，重塑傳統水墨。本展覽分為「古籍今說」、「水墨新顏」及「紙漿立體書工作坊」三大系列，並與台南應用科技大學合作，旨在提升公眾參與度與展覽效益。', '臺南市政府文化局', '臺南市安南區安吉路一段205、207號', '2025-01-10 00:00:00', '2025-04-06 00:00:00', '台江文化中心', 23.04869681, 120.1526189, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='圖畫生態˙漫游古書—袁金塔2025台江特展', `description`='袁金塔，1949年生於彰化，為現代水墨與複合媒材藝術大師，曾任國立台灣師範大學教授及當代美術館館長。其作品融合東西方藝術理念，重塑傳統水墨。本展覽分為「古籍今說」、「水墨新顏」及「紙漿立體書工作坊」三大系列，並與台南應用科技大學合作，旨在提升公眾參與度與展覽效益。', `organizer`='臺南市政府文化局', `address`='臺南市安南區安吉路一段205、207號', `start_date`='2025-01-10 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='台江文化中心', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf44326b3240c403d9522', '114前鎮分館辦理【泰文化泰趣味】 東南亞主題書展', '透過書籍展示，從閱讀中讓讀者了解泰國歷史文化及美食日常生活文化。', '高雄市立圖書館總館', '高雄市前鎮區保泰路303號4樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '高雄市立圖書館前鎮分館', 22.602476, 120.333005, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114前鎮分館辦理【泰文化泰趣味】 東南亞主題書展', `description`='透過書籍展示，從閱讀中讓讀者了解泰國歷史文化及美食日常生活文化。', `organizer`='高雄市立圖書館總館', `address`='高雄市前鎮區保泰路303號4樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='高雄市立圖書館前鎮分館', `latitude`=22.602476, `longitude`=120.333005, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf44326b3240c403d9523', '｢人造光 攝影展」-林育諄個展', '｢人造光 攝影展」-林育諄個展\r\n藝術家：林育諄\r\n展覽日期：2025/3/6 (四)~ 3/30(日) 17:00\r\n展覽地點：新浜碼頭藝術空間 Pin-Bien館\r\n展覽開幕：2025/3/8(六)，14:00\r\n與談人：徐婉禎、蔡伊婷\r\n網站連結：https://sinpink.com/\r\n展覽簡介：\r\n燈，是日常生活中不可或缺的物件，隨處可見，簡單而實用。它承載著時代的痕跡，既照亮世界，也照進我們的內心。在這次展覽中，燈作為拍攝的主題，透過日常且刻意的視角，探索平凡物件中的深意與美感。\r\n拍攝燈光是一個刻意的行為，透過相機以第一人稱的視角重新審視其存在。直視燈光或許刺眼，但藉由科技的調和，在照片中能看到平常無法看到的細節。我曾試圖顛倒室內燈光，以不尋常的視角模糊虛與實的邊界，讓燈光成為心靈的隱喻，開啟一場介於現實與幻想之間的對話。\r\n展覽作品分為兩部分：一部分是室外燈，以路燈為主體，呈現其在城市空間中作為文明象徵的存在；另一部分是室內燈，聚焦於家中常見的吊燈，透過不尋常的視角打破常態，模糊虛實邊界，邀請觀者進行一場與平凡物件和生活哲學的連結與對話\r\n參展經歷：\r\n2022青春設計節-深夜快爆，駁二藝術特區 B5, 高雄\r\n2024 台灣茶日本行攝影聯展，豆象複合式空間，大阪\r\n2024 城市肖像 -攝影聯展，義守大學新媒體創作中心，高雄', '無資料', '高雄市鹽埕區015鄰大勇路64號2樓', '2025-03-06 00:00:00', '2025-03-30 00:00:00', '新浜碼頭藝術空間', 22.6228436, 120.2835667, '無資料', 'https://sinpink.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='｢人造光 攝影展」-林育諄個展', `description`='｢人造光 攝影展」-林育諄個展\r\n藝術家：林育諄\r\n展覽日期：2025/3/6 (四)~ 3/30(日) 17:00\r\n展覽地點：新浜碼頭藝術空間 Pin-Bien館\r\n展覽開幕：2025/3/8(六)，14:00\r\n與談人：徐婉禎、蔡伊婷\r\n網站連結：https://sinpink.com/\r\n展覽簡介：\r\n燈，是日常生活中不可或缺的物件，隨處可見，簡單而實用。它承載著時代的痕跡，既照亮世界，也照進我們的內心。在這次展覽中，燈作為拍攝的主題，透過日常且刻意的視角，探索平凡物件中的深意與美感。\r\n拍攝燈光是一個刻意的行為，透過相機以第一人稱的視角重新審視其存在。直視燈光或許刺眼，但藉由科技的調和，在照片中能看到平常無法看到的細節。我曾試圖顛倒室內燈光，以不尋常的視角模糊虛與實的邊界，讓燈光成為心靈的隱喻，開啟一場介於現實與幻想之間的對話。\r\n展覽作品分為兩部分：一部分是室外燈，以路燈為主體，呈現其在城市空間中作為文明象徵的存在；另一部分是室內燈，聚焦於家中常見的吊燈，透過不尋常的視角打破常態，模糊虛實邊界，邀請觀者進行一場與平凡物件和生活哲學的連結與對話\r\n參展經歷：\r\n2022青春設計節-深夜快爆，駁二藝術特區 B5, 高雄\r\n2024 台灣茶日本行攝影聯展，豆象複合式空間，大阪\r\n2024 城市肖像 -攝影聯展，義守大學新媒體創作中心，高雄', `organizer`='無資料', `address`='高雄市鹽埕區015鄰大勇路64號2樓', `start_date`='2025-03-06 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='新浜碼頭藝術空間', `latitude`=22.6228436, `longitude`=120.2835667, `ticket_price`='無資料', `source_url`='https://sinpink.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67acf44326b3240c403d9524', 'TCO劇院─臺灣歌劇《我的媽媽欠栽培》', '原創歌劇經典再現，最貼心的故鄉回憶，還全天下「欠栽培」 的媽媽一個溫暖的公道。《花甲男孩》作家楊富閔深情原著，北市國跨界製作臺灣歌劇《我的媽媽欠栽培》，用歌、用戲、用偶、用音樂，歌詠最悲喜交織的倫理親情，懷想最 哭笑不得的成長回憶。在城鄉差距與人倫關係的變動間，留下最深刻的文化風景，一同喚醒深藏在心底的陳年感動。', '臺北市立國樂團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-06-07 00:00:00', '2025-06-08 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500;--+1000;--+1500;--+2000;--+2500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='TCO劇院─臺灣歌劇《我的媽媽欠栽培》', `description`='原創歌劇經典再現，最貼心的故鄉回憶，還全天下「欠栽培」 的媽媽一個溫暖的公道。《花甲男孩》作家楊富閔深情原著，北市國跨界製作臺灣歌劇《我的媽媽欠栽培》，用歌、用戲、用偶、用音樂，歌詠最悲喜交織的倫理親情，懷想最 哭笑不得的成長回憶。在城鄉差距與人倫關係的變動間，留下最深刻的文化風景，一同喚醒深藏在心底的陳年感動。', `organizer`='臺北市立國樂團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-06-07 00:00:00', `end_date`='2025-06-08 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500;--+1000;--+1500;--+2000;--+2500', `source_url`='https://www.opentix.life/', `image_url`='[]';
