INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ae441e26b3240c403d9538', '幸福公路與客家主題巡展-打開台9線，你上線了嗎？', '想在新的一年開運轉運嗎？\r\n這場展覽，帶你走進台9線的歷史與未來，從公路建設到客家文化的發展，讓你深度了解這條連結東西、融合經濟與文化的奇幻之路。\r\n\r\n「客隨運轉展」聚焦公路幕後及東部客家的故事，策展團隊透過取材看手相的巧思，完整呈現台9線過去到未來，一再突破吉凶禍福的挑戰，在公路建設創新及客家族群文化經濟找到各自發展「事業線」、「感情線」、「生命線」、「智慧線」的生命歷程，公開超過30件的金馬號、金馬小姐、工程和監理文物，以及客家從西部遷居到東部從未在臺東展出的故事。\r\n\r\n本次展覽主視覺獲得臺灣設計領域最高獎項的2024金點設計獎「Communication Design」金點標章。以公路上的「路面、橋樑、隧道」為視覺主體的三種主視覺，與象徵客家本色的柿餅橘、藍布衫、草仔粿綠巧妙融合，展現公路與客家相容相生的緊密鏈結，從主視覺就打開對本展兩種主題的新視角。路面蜿蜒起伏的「忐忑」、橋梁連接兩地的「跨越」、隧道貫通後的「轉變」，呼應本展主題「客隨運轉」，在當時臺灣東部這片新天地，面臨挑戰，以創新與專業轉運未來。', '交通部公路總局', '臺東縣臺東市南京路25號', '2025-01-07 00:00:00', '2025-03-06 00:00:00', '臺東縣政府文化處', 22.75165721, 121.1103647, '無資料', 'https://twhwmuseum.thb.gov.tw/tw/cp-1272-9378-fd481-7.html', '[]') ON DUPLICATE KEY UPDATE `activity_name`='幸福公路與客家主題巡展-打開台9線，你上線了嗎？', `description`='想在新的一年開運轉運嗎？\r\n這場展覽，帶你走進台9線的歷史與未來，從公路建設到客家文化的發展，讓你深度了解這條連結東西、融合經濟與文化的奇幻之路。\r\n\r\n「客隨運轉展」聚焦公路幕後及東部客家的故事，策展團隊透過取材看手相的巧思，完整呈現台9線過去到未來，一再突破吉凶禍福的挑戰，在公路建設創新及客家族群文化經濟找到各自發展「事業線」、「感情線」、「生命線」、「智慧線」的生命歷程，公開超過30件的金馬號、金馬小姐、工程和監理文物，以及客家從西部遷居到東部從未在臺東展出的故事。\r\n\r\n本次展覽主視覺獲得臺灣設計領域最高獎項的2024金點設計獎「Communication Design」金點標章。以公路上的「路面、橋樑、隧道」為視覺主體的三種主視覺，與象徵客家本色的柿餅橘、藍布衫、草仔粿綠巧妙融合，展現公路與客家相容相生的緊密鏈結，從主視覺就打開對本展兩種主題的新視角。路面蜿蜒起伏的「忐忑」、橋梁連接兩地的「跨越」、隧道貫通後的「轉變」，呼應本展主題「客隨運轉」，在當時臺灣東部這片新天地，面臨挑戰，以創新與專業轉運未來。', `organizer`='交通部公路總局', `address`='臺東縣臺東市南京路25號', `start_date`='2025-01-07 00:00:00', `end_date`='2025-03-06 00:00:00', `location`='臺東縣政府文化處', `latitude`=22.75165721, `longitude`=121.1103647, `ticket_price`='無資料', `source_url`='https://twhwmuseum.thb.gov.tw/tw/cp-1272-9378-fd481-7.html', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ae443826b3240c403d9549', '工藝故事屋（114年3月）', '「聽」是兒童吸收文化能量的重要管道，聽故事不僅充滿樂趣，且可激發兒童的創造思考能力，並與孩子分享正面的想法，培養正確的價值觀，型塑良好的品德。 小朋友在聽故事的過程中，透過故事經驗訊息的輸入與適性引導，學習正確的情緒抒發方式，並從中感受到愛與溫暖，進而健全兒童心理層面之發展，且從動手操作中，引導對工藝的認識及啟萌，使成長成為一位身心靈都健康的公民。 本活動於每週六上午及下午各辦理一場，在工藝資訊館2樓進行，不用報名，免費參加。\r\n活動對象：限國小(含)以下親子，需家長陪同', '國立臺灣工藝研究發展中心', '南投縣草屯鎮中正路573號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '國立臺灣工藝研究發展中心（臺灣工藝文化園區）', 23.9807747, 120.6918567, '無資料', 'https://www.ntcri.gov.tw/home/zh-tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='工藝故事屋（114年3月）', `description`='「聽」是兒童吸收文化能量的重要管道，聽故事不僅充滿樂趣，且可激發兒童的創造思考能力，並與孩子分享正面的想法，培養正確的價值觀，型塑良好的品德。 小朋友在聽故事的過程中，透過故事經驗訊息的輸入與適性引導，學習正確的情緒抒發方式，並從中感受到愛與溫暖，進而健全兒童心理層面之發展，且從動手操作中，引導對工藝的認識及啟萌，使成長成為一位身心靈都健康的公民。 本活動於每週六上午及下午各辦理一場，在工藝資訊館2樓進行，不用報名，免費參加。\r\n活動對象：限國小(含)以下親子，需家長陪同', `organizer`='國立臺灣工藝研究發展中心', `address`='南投縣草屯鎮中正路573號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='國立臺灣工藝研究發展中心（臺灣工藝文化園區）', `latitude`=23.9807747, `longitude`=120.6918567, `ticket_price`='無資料', `source_url`='https://www.ntcri.gov.tw/home/zh-tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ae443826b3240c403d954b', '青洲灣派對-藝術沙雕展演', '邀請日本知名沙雕藝術家\r\n松木由子、保板俊彥、林真理大師共同創作\r\n並由陳坤田老師操刀策展，話題十足！\r\n總共創作𝟙𝟘座神獸主題沙雕作品\r\n運用青洲灣黑沙場地優勢\r\n結合生肖及過年氛圍雕刻年獸沙雕進行展演\r\n這次沙雕藝術展會橫跨春節到元宵節喔！', '交通部觀光局大鵬灣國家風景區管理處', '屏東縣東港鎮大潭路169號', '2025-01-17 00:00:00', '2025-02-25 00:00:00', '交通部觀光局大鵬灣國家風景區管理處', 22.46265635, 120.4751333, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='青洲灣派對-藝術沙雕展演', `description`='邀請日本知名沙雕藝術家\r\n松木由子、保板俊彥、林真理大師共同創作\r\n並由陳坤田老師操刀策展，話題十足！\r\n總共創作𝟙𝟘座神獸主題沙雕作品\r\n運用青洲灣黑沙場地優勢\r\n結合生肖及過年氛圍雕刻年獸沙雕進行展演\r\n這次沙雕藝術展會橫跨春節到元宵節喔！', `organizer`='交通部觀光局大鵬灣國家風景區管理處', `address`='屏東縣東港鎮大潭路169號', `start_date`='2025-01-17 00:00:00', `end_date`='2025-02-25 00:00:00', `location`='交通部觀光局大鵬灣國家風景區管理處', `latitude`=22.46265635, `longitude`=120.4751333, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ae443826b3240c403d954c', '移動觀察者', '四組藝術家奠基於嘉義建城320年未來想像，融合嘉義現在／過去／未來的地景，以不同形式創作，探討生活的身體、在嘉義地景中的運動感知（perception-in-motion），邀請觀眾化身為「移動觀察者」，打開對於生活中無所不在地景的更強感知能力。', '嘉義市美術館', '嘉義市西區廣寧街101號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '嘉義市立美術館', 25.0421407, 121.5198716, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='移動觀察者', `description`='四組藝術家奠基於嘉義建城320年未來想像，融合嘉義現在／過去／未來的地景，以不同形式創作，探討生活的身體、在嘉義地景中的運動感知（perception-in-motion），邀請觀眾化身為「移動觀察者」，打開對於生活中無所不在地景的更強感知能力。', `organizer`='嘉義市美術館', `address`='嘉義市西區廣寧街101號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='嘉義市立美術館', `latitude`=25.0421407, `longitude`=121.5198716, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67aedf2807f37a26088be580', '家劇場系列《爸爸的白書套》 Father’s Secret', '演出與場地資訊：\r\n本次演出場地為新北市政府文化局活化的舊空間，位於三樓，無電梯。部分座位為席地而坐，部分為可移動座位，腿部不便者請特別留意。\r\n\r\n巡演口碑推薦\r\n2022-2023全臺巡演廣受好評，感動無數觀眾：\r\n作家林蔚昀：「這齣戲了不起的地方，就是呈現出真實幽微的人性。」\r\n二刷家長廖小姐：「有內涵深度，卻又讓孩子能明瞭且感動。」\r\n高雄楊先生：「情感拿捏恰到好處，光影與投影技術令人驚艷。」\r\n大學生賴同學：「父女讀信的告解片段讓我數度落淚。」\r\n二寶媽陳小姐：「父女相認時，僅透過背影就讓劇場瀰漫濃烈情感。」\r\n\r\n✰2025年定目劇 全新升級✰\r\n頑書趣工作室將於2025年推出定目劇，連演四週16場，期待透過長期演出，促進更深層的對話與交流。不論是家人之間的愛、社會的倡議，還是不同群體的對話，這部劇都希望帶來更多啟發，讓孩子與青少年看見自由世代的珍貴，也陪伴成人思考愛與包容的真諦。\r\n\r\n成人場 & 親子場 分齡演出\r\n由於前兩年演出讓許多成人觀眾感動落淚，今年特別將演出分為「成人場」與「親子場」。\r\n\r\n成人場：情感更深、劇情更沉重，適合希望體驗更深層次情感的觀眾。\r\n親子場：適合15歲以下孩童，讓親子一同感受溫暖動人的親情故事。\r\n\r\n【故事簡介】\r\n即便不在你身邊，對你的愛一直都在。\r\n陳阿火過世了，女兒念生在一箱箱紙箱裡，發現了爸爸與媽媽的秘密。\r\n捨不得離開的阿火，回到家中偷偷關心念生。當念生翻閱一本本日記，過去的記憶也隨之浮現——民國40到70年間，阿火因種種不得已的原因離家，這些過往讓念生漸漸理解了爸爸曾經的難言之隱......\r\n無法再觸碰彼此的父女，透過白書套包裹的日記，一點一滴解開誤會，讓彼此的心再次緊緊相擁。\r\n\r\n一同邀請親朋好友相約來看戲！\r\n頑書趣工作室將再次運用光影技術、現場樂手、沉浸式體驗豐富您的視覺饗宴！', '頑書趣工作室', '新北市板橋區國光路76號2樓', '2025-03-21 00:00:00', '2025-04-13 00:00:00', '新北藝棧76', 25.01186453, 121.4579675, '500元（一般票）、900元（藝文贊助票）', 'https://www.opentix.life/event/1876826175796072448?srsltid=AfmBOopFd50WnTEq3irnMKwVvdKKAhxuOzK0aieNPKlNTVe2rxL6af_C', '[]') ON DUPLICATE KEY UPDATE `activity_name`='家劇場系列《爸爸的白書套》 Father’s Secret', `description`='演出與場地資訊：\r\n本次演出場地為新北市政府文化局活化的舊空間，位於三樓，無電梯。部分座位為席地而坐，部分為可移動座位，腿部不便者請特別留意。\r\n\r\n巡演口碑推薦\r\n2022-2023全臺巡演廣受好評，感動無數觀眾：\r\n作家林蔚昀：「這齣戲了不起的地方，就是呈現出真實幽微的人性。」\r\n二刷家長廖小姐：「有內涵深度，卻又讓孩子能明瞭且感動。」\r\n高雄楊先生：「情感拿捏恰到好處，光影與投影技術令人驚艷。」\r\n大學生賴同學：「父女讀信的告解片段讓我數度落淚。」\r\n二寶媽陳小姐：「父女相認時，僅透過背影就讓劇場瀰漫濃烈情感。」\r\n\r\n✰2025年定目劇 全新升級✰\r\n頑書趣工作室將於2025年推出定目劇，連演四週16場，期待透過長期演出，促進更深層的對話與交流。不論是家人之間的愛、社會的倡議，還是不同群體的對話，這部劇都希望帶來更多啟發，讓孩子與青少年看見自由世代的珍貴，也陪伴成人思考愛與包容的真諦。\r\n\r\n成人場 & 親子場 分齡演出\r\n由於前兩年演出讓許多成人觀眾感動落淚，今年特別將演出分為「成人場」與「親子場」。\r\n\r\n成人場：情感更深、劇情更沉重，適合希望體驗更深層次情感的觀眾。\r\n親子場：適合15歲以下孩童，讓親子一同感受溫暖動人的親情故事。\r\n\r\n【故事簡介】\r\n即便不在你身邊，對你的愛一直都在。\r\n陳阿火過世了，女兒念生在一箱箱紙箱裡，發現了爸爸與媽媽的秘密。\r\n捨不得離開的阿火，回到家中偷偷關心念生。當念生翻閱一本本日記，過去的記憶也隨之浮現——民國40到70年間，阿火因種種不得已的原因離家，這些過往讓念生漸漸理解了爸爸曾經的難言之隱......\r\n無法再觸碰彼此的父女，透過白書套包裹的日記，一點一滴解開誤會，讓彼此的心再次緊緊相擁。\r\n\r\n一同邀請親朋好友相約來看戲！\r\n頑書趣工作室將再次運用光影技術、現場樂手、沉浸式體驗豐富您的視覺饗宴！', `organizer`='頑書趣工作室', `address`='新北市板橋區國光路76號2樓', `start_date`='2025-03-21 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='新北藝棧76', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='500元（一般票）、900元（藝文贊助票）', `source_url`='https://www.opentix.life/event/1876826175796072448?srsltid=AfmBOopFd50WnTEq3irnMKwVvdKKAhxuOzK0aieNPKlNTVe2rxL6af_C', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67af18e107f37a26088be581', 'Prolonged Moments', '《 Prolonged Moments 》個展創作靈感源於日常生活與異常狀態之間的交錯，這些作品試圖捕捉一種異化的日常——熟悉與陌生的並存，讓人從平凡事物中感受到不尋常的氣息。藝術家 馬寧遠（Jennifer Ning-yuan Ma）以視覺語言來重新審視日常中的細節，從人物、燈具、電線到建築景觀，甚至是生活中奇特或怪異的場景。\r\n​\r\n在她的作品中，日常物件從單純的物件轉變為具有多重義意的象徵。這些描繪常常暗示當代生活中的各種心理狀態，例如慾望的潛逃與宣洩、情感的漠然與焦慮，或不安於現狀的表現。她以作品為媒介，呈現對當代社會情感與心理的反思。\r\n​\r\n她特別著迷於熟悉事物突然給人陌生感的那一瞬間。這種語意的飽和與模糊，使人感到既親近又遙遠，像是一場心理的拉扯遊戲。她希望作品能呈現一種既熟悉又陌生的視覺體驗，透過這種微妙的不適感，挑戰對現實與日常的既有認知。\r\n', '福利社 FreeS Art Space', '臺北市中山區新生北路三段82號B1', '2025-02-22 00:00:00', '2025-03-26 00:00:00', '福利社 FreeS Art Space', 25.06969917, 121.5381597, '無資料', 'https://www.facebook.com/freesartspace', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Prolonged Moments', `description`='《 Prolonged Moments 》個展創作靈感源於日常生活與異常狀態之間的交錯，這些作品試圖捕捉一種異化的日常——熟悉與陌生的並存，讓人從平凡事物中感受到不尋常的氣息。藝術家 馬寧遠（Jennifer Ning-yuan Ma）以視覺語言來重新審視日常中的細節，從人物、燈具、電線到建築景觀，甚至是生活中奇特或怪異的場景。\r\n​\r\n在她的作品中，日常物件從單純的物件轉變為具有多重義意的象徵。這些描繪常常暗示當代生活中的各種心理狀態，例如慾望的潛逃與宣洩、情感的漠然與焦慮，或不安於現狀的表現。她以作品為媒介，呈現對當代社會情感與心理的反思。\r\n​\r\n她特別著迷於熟悉事物突然給人陌生感的那一瞬間。這種語意的飽和與模糊，使人感到既親近又遙遠，像是一場心理的拉扯遊戲。她希望作品能呈現一種既熟悉又陌生的視覺體驗，透過這種微妙的不適感，挑戰對現實與日常的既有認知。\r\n', `organizer`='福利社 FreeS Art Space', `address`='臺北市中山區新生北路三段82號B1', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='福利社 FreeS Art Space', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='https://www.facebook.com/freesartspace', `image_url`='[]';
