INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afafc426b3240c403d957e', '創藝黏土玩花漾休閒證照班', '可以學習到各種不同的捏塑，上色等技巧並結合拼貼，並配合生活週遭器具..做出實用或送禮兩相宜的花卉與娃娃等..藝術品，在休閒之餘也能取得證照!並使大家透過淺顯易懂的技巧輕鬆成為居家生活達人喔!\n請自備圍裙及小剪刀、尺、牙籤、公文夾、抹布，或上課由老師公佈。(材料費另計、證照費另計)\n\n年齡：18歲以上皆可\n\n ', '國立彰化生活美學館', '500  彰化縣彰化市74卦山路18號', '2025-04-11 00:00:00', '2025-06-13 00:00:00', '第二研習教室', 24.0765278, 120.5573442, '1800', 'https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50348', '[]') ON DUPLICATE KEY UPDATE `activity_name`='創藝黏土玩花漾休閒證照班', `description`='可以學習到各種不同的捏塑，上色等技巧並結合拼貼，並配合生活週遭器具..做出實用或送禮兩相宜的花卉與娃娃等..藝術品，在休閒之餘也能取得證照!並使大家透過淺顯易懂的技巧輕鬆成為居家生活達人喔!\n請自備圍裙及小剪刀、尺、牙籤、公文夾、抹布，或上課由老師公佈。(材料費另計、證照費另計)\n\n年齡：18歲以上皆可\n\n ', `organizer`='國立彰化生活美學館', `address`='500  彰化縣彰化市74卦山路18號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-06-13 00:00:00', `location`='第二研習教室', `latitude`=24.0765278, `longitude`=120.5573442, `ticket_price`='1800', `source_url`='https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50348', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afafc626b3240c403d957f', '現代繪畫美學A班', '只要你是熱愛繪畫喜歡美麗的事物.不管你是學習或單純的欣賞.特別是曾經有不好的學習經驗過程.這堂課可以給你改變不同的學習觀點.讓你的視野與思考更豐富寬廣.課程中會教你用最簡單的方法學習技巧.淺顯易懂的方式示範素描.水彩.油畫.水墨.書法...不管是新人還是舊生這堂課將為你排除障礙..課堂中更排入色彩學與視覺空間理論.生活攝影等課程讓你品味生活.豐富人生!\n(用具顏料請自備)', '國立彰化生活美學館', '500  彰化縣彰化市彰化市卦山路18號', '2025-04-11 00:00:00', '2025-06-13 00:00:00', '工藝教室', 24.0768296, 120.5585119, '1500', 'https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50322', '[]') ON DUPLICATE KEY UPDATE `activity_name`='現代繪畫美學A班', `description`='只要你是熱愛繪畫喜歡美麗的事物.不管你是學習或單純的欣賞.特別是曾經有不好的學習經驗過程.這堂課可以給你改變不同的學習觀點.讓你的視野與思考更豐富寬廣.課程中會教你用最簡單的方法學習技巧.淺顯易懂的方式示範素描.水彩.油畫.水墨.書法...不管是新人還是舊生這堂課將為你排除障礙..課堂中更排入色彩學與視覺空間理論.生活攝影等課程讓你品味生活.豐富人生!\n(用具顏料請自備)', `organizer`='國立彰化生活美學館', `address`='500  彰化縣彰化市彰化市卦山路18號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-06-13 00:00:00', `location`='工藝教室', `latitude`=24.0768296, `longitude`=120.5585119, `ticket_price`='1500', `source_url`='https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50322', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afafc626b3240c403d9580', '二胡班', '二胡是弦樂中最為普遍的樂器之一，同時在音樂中的表現也極為突出的。用輕鬆愉快的方式，和您們分享音樂的樂趣。感受演奏的喜悅，逐步達成初級演奏能力自娛娛人，用樂器演奏簡易台灣民謠,民歌,地方小調的能力，進而學習到各種樂器演奏曲目。歡迎無基礎者，一起來學習。樂器可自備或於第一節登記團購。\n\n \n\n ', '國立彰化生活美學館', '500  彰化縣彰化市74卦山路18號', '2025-04-08 00:00:00', '2025-06-10 00:00:00', '工藝教室', 24.0765278, 120.5573442, '1800', 'https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50323', '[]') ON DUPLICATE KEY UPDATE `activity_name`='二胡班', `description`='二胡是弦樂中最為普遍的樂器之一，同時在音樂中的表現也極為突出的。用輕鬆愉快的方式，和您們分享音樂的樂趣。感受演奏的喜悅，逐步達成初級演奏能力自娛娛人，用樂器演奏簡易台灣民謠,民歌,地方小調的能力，進而學習到各種樂器演奏曲目。歡迎無基礎者，一起來學習。樂器可自備或於第一節登記團購。\n\n \n\n ', `organizer`='國立彰化生活美學館', `address`='500  彰化縣彰化市74卦山路18號', `start_date`='2025-04-08 00:00:00', `end_date`='2025-06-10 00:00:00', `location`='工藝教室', `latitude`=24.0765278, `longitude`=120.5573442, `ticket_price`='1800', `source_url`='https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50323', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afafc626b3240c403d9581', '小原流插花及歐美花藝設計班', '直上型、直立型、傾斜型、花意匠(開展式、旋轉式、排列式)現代水平型、寫景插花、現代S型+瀑布型、歐美花藝半球型、創意花藝、節慶花藝、對稱型應用。（亦可申請證照檢定）(材料費另計)', '國立彰化生活美學館', '500  彰化縣彰化市74卦山路18號', '2025-04-10 00:00:00', '2025-06-12 00:00:00', '工藝教室', 24.0765278, 120.5573442, '1500', 'https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50324', '[]') ON DUPLICATE KEY UPDATE `activity_name`='小原流插花及歐美花藝設計班', `description`='直上型、直立型、傾斜型、花意匠(開展式、旋轉式、排列式)現代水平型、寫景插花、現代S型+瀑布型、歐美花藝半球型、創意花藝、節慶花藝、對稱型應用。（亦可申請證照檢定）(材料費另計)', `organizer`='國立彰化生活美學館', `address`='500  彰化縣彰化市74卦山路18號', `start_date`='2025-04-10 00:00:00', `end_date`='2025-06-12 00:00:00', `location`='工藝教室', `latitude`=24.0765278, `longitude`=120.5573442, `ticket_price`='1500', `source_url`='https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50324', `image_url`='[]';
