INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afafc626b3240c403d9583', '氧身瑜珈C班', '氧身瑜珈欲紓解生活壓力、強化肌膚、血液順暢、改善體質、刺激末梢神經(含彼拉提斯課程)。彼拉提斯是利用身體軀幹力量，帶動四肢伸展運動，健身兼養身，傷害復健，瑜珈身體平衡。', '國立彰化生活美學館', '500  彰化縣彰化市卦山路18號', '2025-04-09 00:00:00', '2025-06-11 00:00:00', '舞蹈教室', 24.0768296, 120.5585119, '1000', 'https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50326', '[]') ON DUPLICATE KEY UPDATE `activity_name`='氧身瑜珈C班', `description`='氧身瑜珈欲紓解生活壓力、強化肌膚、血液順暢、改善體質、刺激末梢神經(含彼拉提斯課程)。彼拉提斯是利用身體軀幹力量，帶動四肢伸展運動，健身兼養身，傷害復健，瑜珈身體平衡。', `organizer`='國立彰化生活美學館', `address`='500  彰化縣彰化市卦山路18號', `start_date`='2025-04-09 00:00:00', `end_date`='2025-06-11 00:00:00', `location`='舞蹈教室', `latitude`=24.0768296, `longitude`=120.5585119, `ticket_price`='1000', `source_url`='https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50326', `image_url`='[]';
