INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afafc626b3240c403d9587', '青少年兒童武術功夫班', '兒童功夫的課程，是一套輔助孩子成長的武術系統課程．以武術動作中的各種伸展跳躍、平衡、節奏、速度等動作，幫助孩子建立協調性、空間感、平衡感、模仿力…等成長的因子，更在長期的課程訓練中，讓孩子在思想與肢體的發展上，取得平衡與協調課程中更加入氣功與暝想的課程，有效強化體質及增強免疫力，激發孩子的潛能與創造力，讓孩子在學習過程中，防身健身更培養對自己的自信心及健康有活力的人生觀。年齡：5-12歲\n\n ', '國立彰化生活美學館', '500  彰化縣彰化市彰化市卦山路18號', '2025-04-10 00:00:00', '2025-06-12 00:00:00', '舞蹈教室', 24.0768296, 120.5585119, '1800', 'https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50338', '[]') ON DUPLICATE KEY UPDATE `activity_name`='青少年兒童武術功夫班', `description`='兒童功夫的課程，是一套輔助孩子成長的武術系統課程．以武術動作中的各種伸展跳躍、平衡、節奏、速度等動作，幫助孩子建立協調性、空間感、平衡感、模仿力…等成長的因子，更在長期的課程訓練中，讓孩子在思想與肢體的發展上，取得平衡與協調課程中更加入氣功與暝想的課程，有效強化體質及增強免疫力，激發孩子的潛能與創造力，讓孩子在學習過程中，防身健身更培養對自己的自信心及健康有活力的人生觀。年齡：5-12歲\n\n ', `organizer`='國立彰化生活美學館', `address`='500  彰化縣彰化市彰化市卦山路18號', `start_date`='2025-04-10 00:00:00', `end_date`='2025-06-12 00:00:00', `location`='舞蹈教室', `latitude`=24.0768296, `longitude`=120.5585119, `ticket_price`='1800', `source_url`='https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50338', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afafc626b3240c403d958d', '生命動能-青少年領袖班', '1.講授、心靈閱讀、個案研討、心得交流、心靈對話、心靈書寫。\n\n2. 青少年心胸、視野與器度的涵養。\n\n3.從內在品質轉變開始，積極地自我成長，發展身心智慧，健康快樂地邁向理想學府。\n\n ', '國立彰化生活美學館', '500  彰化縣彰化市74卦山路18號', '2025-04-11 00:00:00', '2025-06-13 00:00:00', '第三研習教室', 24.0765278, 120.5573442, '1500', 'https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50344', '[]') ON DUPLICATE KEY UPDATE `activity_name`='生命動能-青少年領袖班', `description`='1.講授、心靈閱讀、個案研討、心得交流、心靈對話、心靈書寫。\n\n2. 青少年心胸、視野與器度的涵養。\n\n3.從內在品質轉變開始，積極地自我成長，發展身心智慧，健康快樂地邁向理想學府。\n\n ', `organizer`='國立彰化生活美學館', `address`='500  彰化縣彰化市74卦山路18號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-06-13 00:00:00', `location`='第三研習教室', `latitude`=24.0765278, `longitude`=120.5573442, `ticket_price`='1500', `source_url`='https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50344', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afafc726b3240c403d9590', '少林瘋魔棍(五行健康操)', '少林瘋魔棍，以心行氣，以氣養生，用氣而不用力，息息之間，充滿天地萬物之精華，不僅可消除疲勞、活絡筋骨、調氣養神、增強免疫能力之功能，更可促進血液循環，滋潤肌膚保持氣色良好。\n\n ', '國立彰化生活美學館', '500  彰化縣彰化市74卦山路18號', '2025-04-13 00:00:00', '2025-06-15 00:00:00', '聯誼廳', 24.0765278, 120.5573442, '1000', 'https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50331', '[]') ON DUPLICATE KEY UPDATE `activity_name`='少林瘋魔棍(五行健康操)', `description`='少林瘋魔棍，以心行氣，以氣養生，用氣而不用力，息息之間，充滿天地萬物之精華，不僅可消除疲勞、活絡筋骨、調氣養神、增強免疫能力之功能，更可促進血液循環，滋潤肌膚保持氣色良好。\n\n ', `organizer`='國立彰化生活美學館', `address`='500  彰化縣彰化市74卦山路18號', `start_date`='2025-04-13 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='聯誼廳', `latitude`=24.0765278, `longitude`=120.5573442, `ticket_price`='1000', `source_url`='https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50331', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afafc726b3240c403d9596', '編織班', '沒有什麼能比自己打的隨身物品更能提供溫暖，從線開始讓圍巾、帽子、背心、上衣、外套、披肩完成您的愛心。(材料費另計)\n\n ', '國立彰化生活美學館', '500  彰化縣彰化市74卦山路18號', '2025-04-08 00:00:00', '2025-06-10 00:00:00', '綜合教室(B)', 24.0765278, 120.5573442, '1200', 'https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50349', '[]') ON DUPLICATE KEY UPDATE `activity_name`='編織班', `description`='沒有什麼能比自己打的隨身物品更能提供溫暖，從線開始讓圍巾、帽子、背心、上衣、外套、披肩完成您的愛心。(材料費另計)\n\n ', `organizer`='國立彰化生活美學館', `address`='500  彰化縣彰化市74卦山路18號', `start_date`='2025-04-08 00:00:00', `end_date`='2025-06-10 00:00:00', `location`='綜合教室(B)', `latitude`=24.0765278, `longitude`=120.5573442, `ticket_price`='1200', `source_url`='https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50349', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afafce26b3240c403d9599', '時代留聲－114年轉型正義推廣活動', ' \n\n \n\n \n\n20場系列活動類別如下（可點選直接跳至該項活動）\n\n\n	不義遺址走讀活動\n	禁歌暨人權歌曲說唱會\n	報禁工作坊\n	轉型正義講座/對談\n	戲劇工作坊\n	多元形式活動\n\n\n \n\n\n\n\n\n \n\n \n\n \n\n \n\n►不義遺址走讀活動      2u反        \n\n\n	走讀路線A\n	★主題：二二八被遺忘的軌跡\n	★時間：3/2(日) 14:00-17:00\n	★走讀路線：中正紀念堂3樓多媒體人權展區前集合與導覽 → 臺灣菸酒公司（原臺灣省專賣局）→臺北市立大學 （原日治時期師範學校）→台北二二八紀念館→ 開南商工→ 審定不義遺址－原臺灣省行政長官公署暨廣場（今日名稱：行政院）\n	★走讀帶領人：廖品硯老師 / 前台灣共生青年協會秘書\n	★參考文本：《不沉默紀錄：屬於臺灣人的二二八行動主義》\n	★報名參加並出席加贈紀念小禮\n\n\n \n\n\n	走讀路線B\n	★主題：安康接待室\n	★時間：3/9(日) 14:00-17:00\n	★走讀路線：中正紀念堂3樓多媒體人權展區前集合與導覽 → 輕軌玫瑰中國城站 → 二叭仔聚落介紹 → 二叭仔溪 → 審定不義遺址－原司法行政部調查局安康接待室（今日名稱：安康接待室）\n	★走讀帶領人：吳柏瑋老師、顏宏穎老師 / 暗坑文化工作室\n	★參考文本：《不義遺址：轉型正義的空間實踐》\n	★報名參加並出席加贈新北淡海輕軌 & 安坑輕軌一日套票乙張\n\n\n \n\n\n	走讀路線C\n	★主題：紀念背後的真相：我們在追憶什麼？\n	★時間：5/3(六) 14:00-17:00 \n	★走讀路線：中正紀念堂3樓多媒體人權展區前集合與導覽  →潛在不義遺址－原陸軍總部軍法處看守所（上海路）（今日名稱：中正紀念堂園區）→ 二二八和平公園 → 二二八和平紀念碑 → 白色恐怖政治受難者紀念碑\n	★走讀帶領人：凌宗魁老師 / 建築史與文化資產研究工作者\n	★參考文本：《被消失的建築考：從日治到民國，那些藏在檔案裡的日產建築20帖》\n\n\n \n\n\n	走讀路線D \n	★主題：解密：一趟黨產追查之旅\n	★時間：6/7(六)  14:00-17:00\n	★走讀路線：中正紀念堂3樓多媒體人權展區前集合與導覽 → 財團法人張榮發基金會 → 原裕台公司（現址為：天仁喫茶趣衡陽店） → 潛在不義遺址－中山堂（今日名稱：中山堂）→ 新世界中影大樓 → 東吳大學城中校區\n	★走讀帶領人：廖品硯老師 / 前台灣共生青年協會秘書\n	★參考文本：《黨產偵探旅行團》\n	\n	點選返回活動類別\n\n	\n\n\n►禁歌暨人權歌曲說唱會\n\n\n	禁歌暨人權歌曲說唱會 part ♪ \n	★時間：7/27(日)  14:30-16:30\n	★地點：堂內演藝廳\n	★講者：徐睿楷老師 / 台灣流行音樂研究者\n	★演出者：朱約信 / 知名創作歌手\n	★歌單：規劃中敬請期待！\n\n\n \n\n\n	禁歌暨人權歌曲說唱會 part ♪♪ \n	★時間：9/14(日)  14:30-16:30\n	★地點：堂內演藝廳\n	★講者：張嘉祥 / 裝咖人樂團團長\n	★演出者：裝咖人樂團 / 臺灣台語獨立樂團、入圍第33屆金曲獎最佳新人獎\n	★歌單：規劃中敬請期待！\n	\n	點選返回活動類別\n\n	\n\n\n►報禁工作坊\n\n\n	工作坊場次（一）\n	★主題：報禁、禁報－解嚴下的媒體\n	★講者：李筱峰老師 / 國立臺北教育大學臺灣文化研究所名譽教授\n	★時間：4/13(日)  14:30-16:30\n	★地點：堂內圖書室（1樓的三展廳內）\n\n\n \n\n\n	工作坊場次（二）\n	★主題：小小記者打開時光盒子：過去想說卻不能說的故事\n	★講者：黃琳懿老師 / 腳踏史地工作室負責人\n	★時間：9/20(六)  14:30-16:30\n	★地點：堂內圖書室（1樓的三展廳內）\n	★歡迎親子共同參與，孩童年齡建議國小中高年級，12歲(含)以下孩童需家長陪同且親子皆需報名\n	\n	點選返回活動類別\n\n	\n\n\n►轉型正義講座/對談\n\n\n	講座/對談（一）\n	★主題：南韓轉型正義未竟之路：從濟州43到光州事件\n	★講者：朱立熙老師 / 知韓文化協會執行長\n	★時間：3/23(日)  14:30-16:30\n	★地點：堂內圖書室（1樓的三展廳內）\n	★事前閱讀資料：https://hre.pro.edu.tw/article/5273\n\n\n \n\n\n	講座/對談（二）\n	★主題：臺灣轉型正義與黨產問題\n	★講者：許文堂老師 / 中央研究院近代史研究所退休副研究員、羅承宗老師 / 國立高雄科技大學科技法律研究所教授\n	★時間：5/11(日)  14:30-16:30\n	★地點：堂內圖書室（1樓的三展廳內）\n	\n	點選返回活動類別\n\n	\n\n\n►戲劇工作坊\n\n\n	工作坊場次（一）\n	★主題：希望小提琴：一段關於自由與希望的旅程\n	★講師：巫素琪老師 / 巫婆戲劇魔法故事屋負責人\n	★時間：2/23(日)  14:30-16:30\n	★地點：堂內圖書室（1樓的三展廳內）\n	★參考文本：《希望小提琴》\n	★建議年齡15歲以上\n\n\n \n\n\n	工作坊場次（二）\n	★主題：當白霧散去後\n	★講師：林純珮老師 / 藝術治療工作者、悅萃坊合作講師\n	★時間：7/12(六)  14:30-16:30\n	★地點：堂內201教室（僅能爬樓梯上2樓）\n	★歡迎高中生踴躍報名參加\n\n\n \n\n\n	工作坊場次（三）\n	★主題：從前從前，火車來到小島\n	★講師：巫素琪老師 / 巫婆戲劇魔法故事屋負責人\n	★時間：7/13(日)  14:30-16:30\n	★地點：堂內圖書室（1樓的三展廳內）\n	★參考文本：《從前從前，火車來到小島》\n	★歡迎親子共同參與，孩童年齡建議大班到國小低年級，12歲(含)以下孩童需家長陪同且親子皆需報名\n\n\n \n\n\n	工作坊場次（四）\n	★主題：第一個原住民政治家－Losin Watan的傳奇\n	★講師：蘇慶元老師 / 悅萃坊執行長、國立臺北藝術大學兼任助理教授、國立台灣藝術大學兼任助理教授    \n	★時間：9/7(日)  14:30-16:30\n	★地點：堂內201教室（僅能爬樓梯上2樓）\n	★歡迎國中生踴躍報名參加\n	\n	點選返回活動類別\n\n	\n\n\n►多元形式活動\n\n\n	多元形式活動（一）\n	★主題：星星國王－獨裁者與自由的靈魂 ＜親子場＞\n	★講師：黃琳懿老師 / 腳踏史地工作室負責人\n	★時間：3/15(六)  14:30-16:30\n	★地點：捷運中正紀念堂站5號出口集合\n	★歡迎親子共同參與，12歲(含)以下孩童需家長陪同且親子皆需報名\n\n\n \n\n\n	多元形式活動（二）\n	★主題：舞動靈魂的玫瑰古蹟：舞蹈體驗 ＜親子場＞\n	★講師：詹天甄老師 / 蔡瑞月舞蹈研究社\n	★時間：4/19(六)  13:00-15:00\n	★地點：玫瑰古蹟（臺北市中山區中山北路二段48巷10號）\n	★參考文本：《海燕之舞－蔡瑞月的故事》\n	★歡迎親子共同參與，12歲(含)以下孩童需家長陪同且親子皆需報名\n\n\n \n\n\n	多元形式活動（三）\n	★主題：希望小提琴：人權論壇劇場\n	★講師：巫素琪老師 / 巫婆戲劇魔法故事屋負責人\n	★時間：6/28(日)  14:30-16:30\n	★地點：堂內圖書室（1樓的三展廳內）\n\n\n \n\n\n	多元形式活動（四）\n	★主題：文學中的二二八或白色恐怖小說\n	★講師：朱宥勳老師 / 專職作家、國立清華大學中國文學系兼任講師\n	★時間：7/5(六)  14:30-16:30\n	★地點：堂內圖書室（1樓的三展廳內）\n	★歡迎高中生踴躍報名參加\n\n\n \n\n\n	多元形式活動（五）\n	★主題：舞動記憶：在蔡瑞月舞蹈社尋找自由\n	★講師：蔡瑞月舞蹈研究社\n	★時間：8/9(六)  13:00-15:00\n	★地點：玫瑰古蹟（臺北市中山區中山北路二段48巷10號）\n	★歡迎國、高中生踴躍報名參加\n\n\n \n\n\n	多元形式活動（六）\n	★主題：白色說書人讀劇會\n	★講師：邱安忱老師 / 同黨劇團團長、吳榮昌老師 / 弘宛然古典布袋戲團長、黃武山老師 / 山宛然客語布袋戲團長\n	★時間：8/24(日)  14:30-16:30\n	★地點：堂內演藝廳\n	\n	\n	點選返回活動類別\n\n	\n\n\n交通資訊及教室位置詳參下方連結\n\n\n	地理及交通資訊(請點我)\n	堂內平面圖(請點我)\n	堂內圖書室(位於1樓的三展廳內)及教室位置圖：\n