INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afb0c526b3240c403d95b3', '音樂飛揚 創生大地-大村國小合唱團x水里國小音樂演奏', '用愛心與音樂，點亮這一天！\r\n一場特別的音樂市集，即將在2/28帶來滿滿感動！\r\n大村國小合唱團x水里國小音樂演奏，純淨嗓音直擊心靈！\r\n文創x公益市集，買好物也能支持孩子圓夢！\r\n所得將幫助大村國小合唱團遠赴國外比賽，把台灣的美妙歌聲帶向世界！\r\n用音樂交流、用行動支持，這一天，我們一起見證夢想起飛！\r\n快來相約，讓我們一起飛揚吧！', '南投縣車埕藝文觀光發展協會', '南投縣水里鄉', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '水里鄉（南投縣）=', 23.79612907, 120.8622721, '無資料', 'https://www.facebook.com/grovetaiwan', '[]') ON DUPLICATE KEY UPDATE `activity_name`='音樂飛揚 創生大地-大村國小合唱團x水里國小音樂演奏', `description`='用愛心與音樂，點亮這一天！\r\n一場特別的音樂市集，即將在2/28帶來滿滿感動！\r\n大村國小合唱團x水里國小音樂演奏，純淨嗓音直擊心靈！\r\n文創x公益市集，買好物也能支持孩子圓夢！\r\n所得將幫助大村國小合唱團遠赴國外比賽，把台灣的美妙歌聲帶向世界！\r\n用音樂交流、用行動支持，這一天，我們一起見證夢想起飛！\r\n快來相約，讓我們一起飛揚吧！', `organizer`='南投縣車埕藝文觀光發展協會', `address`='南投縣水里鄉', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='水里鄉（南投縣）=', `latitude`=23.79612907, `longitude`=120.8622721, `ticket_price`='無資料', `source_url`='https://www.facebook.com/grovetaiwan', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afb0c526b3240c403d95b5', '2025蛇來好運 All in 員林燈會', '2025蛇來好運 All in 員林燈會\r\n 時間｜1/25-3/2 (18:00-22:00亮燈)\r\n 地點｜員林公園', '彰化縣員林市公所', '彰化縣員林市三民街1號', '2025-01-25 00:00:00', '2025-03-02 00:00:00', '員林市公園（興賢書院）', 23.95650448, 120.593073, '無資料', 'https://www.facebook.com/profile.php?id=61571870139093', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025蛇來好運 All in 員林燈會', `description`='2025蛇來好運 All in 員林燈會\r\n 時間｜1/25-3/2 (18:00-22:00亮燈)\r\n 地點｜員林公園', `organizer`='彰化縣員林市公所', `address`='彰化縣員林市三民街1號', `start_date`='2025-01-25 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='員林市公園（興賢書院）', `latitude`=23.95650448, `longitude`=120.593073, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=61571870139093', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afb0c526b3240c403d95b6', '2025代化堂─米糕龜傳統文化祭', '一年一度的「米糕龜傳統文化祭」即將來臨，如果你對地景繪畫、手作DIY、宮廟文化，還有親子活動有興趣，那你一定不能錯過這個盛會！\r\n每年農曆二月初二，麒麟宮代化堂都會秉持傳統，為土地公製作和供奉米糕龜，這是一場融入文化的獨特慶典。今年，我們特別推出了全新系列的體驗活動，帶你走進這段美麗的歷史！\r\n今年，主打畫家x廚師雙饗宴「麒麟小畫家x米糕大廚師」雙重活動！上午的繪畫比賽，下午的米糕體驗，報名後，你都可以全程參與，一起動手畫畫、一起親手做米糕，享受傳統文化與創意碰撞的樂趣！\r\n大朋友小朋友，一起來感受這場充滿樂趣與創意的文化盛宴吧！\r\n線上報名 https://forms.gle/Ks8Bmjmbz4HmS8vk6', '魚池鄉麒麟宮代化堂', '南投縣魚池鄉', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '魚池鄉（南投縣）=', 23.87601213, 120.9256736, '報名者費用+100;陪同者費用+50', 'https://www.facebook.com/YuchiFestival/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025代化堂─米糕龜傳統文化祭', `description`='一年一度的「米糕龜傳統文化祭」即將來臨，如果你對地景繪畫、手作DIY、宮廟文化，還有親子活動有興趣，那你一定不能錯過這個盛會！\r\n每年農曆二月初二，麒麟宮代化堂都會秉持傳統，為土地公製作和供奉米糕龜，這是一場融入文化的獨特慶典。今年，我們特別推出了全新系列的體驗活動，帶你走進這段美麗的歷史！\r\n今年，主打畫家x廚師雙饗宴「麒麟小畫家x米糕大廚師」雙重活動！上午的繪畫比賽，下午的米糕體驗，報名後，你都可以全程參與，一起動手畫畫、一起親手做米糕，享受傳統文化與創意碰撞的樂趣！\r\n大朋友小朋友，一起來感受這場充滿樂趣與創意的文化盛宴吧！\r\n線上報名 https://forms.gle/Ks8Bmjmbz4HmS8vk6', `organizer`='魚池鄉麒麟宮代化堂', `address`='南投縣魚池鄉', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='魚池鄉（南投縣）=', `latitude`=23.87601213, `longitude`=120.9256736, `ticket_price`='報名者費用+100;陪同者費用+50', `source_url`='https://www.facebook.com/YuchiFestival/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afb0c526b3240c403d95b7', '【魅力語言伸展台】書市市集', '「豎起書市集的旌旗是為了壯大閱讀同好者的聲勢與社群，吸引更多人接觸書本、參與閱讀行動。」本著這樣的想法，我們計劃以語言特色作為書市集核心主題，號召更多人來探索語言建構起來的世界。書市集現場邀請近20家書店、出版社帶來最完整的閱讀體驗，同時也邀請縣內四個小學來分享語言教學與歌謠，並安排雙語繪本說故事、透過「有來有往」的方式分享語言學習與編輯書寫應用方面的經驗。', '文化部', '南投縣埔里鎮中華路239號', '2025-04-26 00:00:00', '2025-04-27 00:00:00', '南投縣埔里藝文中心', 23.9719221, 120.9713138, '無資料', 'https://readtaiwan.moc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【魅力語言伸展台】書市市集', `description`='「豎起書市集的旌旗是為了壯大閱讀同好者的聲勢與社群，吸引更多人接觸書本、參與閱讀行動。」本著這樣的想法，我們計劃以語言特色作為書市集核心主題，號召更多人來探索語言建構起來的世界。書市集現場邀請近20家書店、出版社帶來最完整的閱讀體驗，同時也邀請縣內四個小學來分享語言教學與歌謠，並安排雙語繪本說故事、透過「有來有往」的方式分享語言學習與編輯書寫應用方面的經驗。', `organizer`='文化部', `address`='南投縣埔里鎮中華路239號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='南投縣埔里藝文中心', `latitude`=23.9719221, `longitude`=120.9713138, `ticket_price`='無資料', `source_url`='https://readtaiwan.moc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afb0c526b3240c403d95b8', '「澎湖嶋意象π」黃天富水彩畫個展', '黃天富是馬公國中美術教師，退休後仍持續動筆創作至今，喜歡用畫筆記錄澎湖一畫一景，不論是自然景觀或是人文環境，都有著濃濃的澎湖味；畫作中，包括四眼井老街、拉車、建國戲院等作品，都引起許多人的共同回憶。本次展覽為黃天富老師第二次個人畫展，續接第一次畫展將主題訂為「澎湖嶋意象πⅡ」，「嶋」象徵錠鉤嶼的山島景觀與燕鷗交織帶來的創作靈感；「π」字代表圓周率，象徵作品的多元性和廣度；本次展出約45件作品，以水彩畫作為主。　 \r\n', ' 澎湖縣馬公市公所', '澎湖縣馬公市永福街30號', '2025-03-10 00:00:00', '2025-04-11 00:00:00', '澎湖縣馬公市公所', 23.55534, 119.59234, '無資料', 'http://www.mkcity.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「澎湖嶋意象π」黃天富水彩畫個展', `description`='黃天富是馬公國中美術教師，退休後仍持續動筆創作至今，喜歡用畫筆記錄澎湖一畫一景，不論是自然景觀或是人文環境，都有著濃濃的澎湖味；畫作中，包括四眼井老街、拉車、建國戲院等作品，都引起許多人的共同回憶。本次展覽為黃天富老師第二次個人畫展，續接第一次畫展將主題訂為「澎湖嶋意象πⅡ」，「嶋」象徵錠鉤嶼的山島景觀與燕鷗交織帶來的創作靈感；「π」字代表圓周率，象徵作品的多元性和廣度；本次展出約45件作品，以水彩畫作為主。　 \r\n', `organizer`=' 澎湖縣馬公市公所', `address`='澎湖縣馬公市永福街30號', `start_date`='2025-03-10 00:00:00', `end_date`='2025-04-11 00:00:00', `location`='澎湖縣馬公市公所', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.mkcity.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afb0c526b3240c403d95b9', '乙巳年-蛇年年畫展', '年畫是傳統春節除舊佈新迎接新年的應景裝飾，具有吉祥歡樂與避邪祈福的功能，創作題材廣泛又多元、內容精采且包羅萬象。版印年畫作品因版畫的複數性，增加了與欣賞者接觸的機會，普遍帶給人們喜悅親近之情；版印年畫因版畫的間接性，可顯現獨特性質藝術價值，也可完全看到藝術家的創作表現。\r\n\r\n　　本次展出國立台灣美術館蛇年年畫特展」年畫作品，創作內容主題聚焦表現乙巳年生肖（蛇）、年節風情、喜穫收成、故事傳說，以及吉祥符號的拼貼和組合，展現創作者豐富的的創造力和想像力。歡迎一睹深具創作美學及民俗祈福的版印年畫作品，並感受年節的歡喜氣氛。', '彰化縣文化局', '彰化縣彰化市中山路2段500號', '2025-01-18 00:00:00', '2025-06-30 00:00:00', '彰化縣立圖書館', 24.07532909, 120.5694208, '無資料', 'https://www.bocach.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='乙巳年-蛇年年畫展', `description`='年畫是傳統春節除舊佈新迎接新年的應景裝飾，具有吉祥歡樂與避邪祈福的功能，創作題材廣泛又多元、內容精采且包羅萬象。版印年畫作品因版畫的複數性，增加了與欣賞者接觸的機會，普遍帶給人們喜悅親近之情；版印年畫因版畫的間接性，可顯現獨特性質藝術價值，也可完全看到藝術家的創作表現。\r\n\r\n　　本次展出國立台灣美術館蛇年年畫特展」年畫作品，創作內容主題聚焦表現乙巳年生肖（蛇）、年節風情、喜穫收成、故事傳說，以及吉祥符號的拼貼和組合，展現創作者豐富的的創造力和想像力。歡迎一睹深具創作美學及民俗祈福的版印年畫作品，並感受年節的歡喜氣氛。', `organizer`='彰化縣文化局', `address`='彰化縣彰化市中山路2段500號', `start_date`='2025-01-18 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='彰化縣立圖書館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.bocach.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afb0c526b3240c403d95bb', '南投區親子館外展服務--繪本說故事＆美勞DIY', '活動內容：\r\n1、繪本-猜猜我是誰\r\n2、美勞-大象的長鼻子\r\n3、教玩具／圖書借閱。\r\n\r\n美勞活動限制10對名額。\r\n活動對象為0-6歲。\r\n預約電話：049-2247511', '南投縣政府', '南投縣草屯鎮', '2025-02-27 00:00:00', '2025-02-27 00:00:00', '草屯鎮（南投縣）=', 23.98321081, 120.7326182, '無資料', 'https://www.facebook.com/ntdrc', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南投區親子館外展服務--繪本說故事＆美勞DIY', `description`='活動內容：\r\n1、繪本-猜猜我是誰\r\n2、美勞-大象的長鼻子\r\n3、教玩具／圖書借閱。\r\n\r\n美勞活動限制10對名額。\r\n活動對象為0-6歲。\r\n預約電話：049-2247511', `organizer`='南投縣政府', `address`='南投縣草屯鎮', `start_date`='2025-02-27 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='草屯鎮（南投縣）=', `latitude`=23.98321081, `longitude`=120.7326182, `ticket_price`='無資料', `source_url`='https://www.facebook.com/ntdrc', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afb0c526b3240c403d95bc', '蔣維珊個展【 少女壇城 】', '《少女壇城》是一場關於內在世界的創造，一次個人的神聖儀式與符號的構築、也是關於夢境、真理與自我探索的藝術實驗。我將壇城視為潛意識顯現的場域，並不指涉現實宗教傳統中的儀式，而是一種超越語言的視覺探索，一種屬於個人精神領域的神聖私密圖像學。\r\n作為一名創作者，我不斷追尋人生與世界的真理，並在夢境與積極想像中接收無法用邏輯解釋的啟示。夢不只是夜晚的幻象，而是通往內在宇宙的門戶；想像不再是封閉的夢幻泡影，而是內在原型與意象的爆發。\r\n我試圖在創作中捕捉這些來自潛意識的象徵，並透過繪畫與影像，創造屬於自己的壇城——一座由少女之眼觀看介於夢與現實、私密與神聖之間的場域。這是一場個人的儀式，一場關於成長、存在與神性連結的靜謐對話。\r\n在這個展覽中，符號與儀式不再是既定的，而是個人神聖性的延伸。少女的視角並非脆弱，而是一種細緻入微的觀看方式，能夠感知世界的隱秘法則。在這座壇城中，觀者將進入一個全新的感知場域，與自己的潛意識相遇，在這裡，夢與想像不是虛幻，而是真理的倒影，並在影像與符號之間尋找個人意義的回音。\r\n《少女壇城》不只是我的創造，更是一場心理的遷移，一場退行至直覺與象徵的過程。在這座壇城中，夢境與現實相互滲透，私密符號與集體原型交錯成形。這裡沒有固定的敘事，只有象徵與意識碎片的堆疊。當觀者進入這座壇城，他們或許能在混沌與未知之中，尋回屬於自己的內在少女。', '蔣維珊', '高雄市鹽埕區', '2025-02-15 00:00:00', '2025-03-16 00:00:00', '鹽埕區（高雄市）=', 22.62424585, 120.2842331, '無資料', 'https://www.facebook.com/share/p/1BFssfkcaT/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蔣維珊個展【 少女壇城 】', `description`='《少女壇城》是一場關於內在世界的創造，一次個人的神聖儀式與符號的構築、也是關於夢境、真理與自我探索的藝術實驗。我將壇城視為潛意識顯現的場域，並不指涉現實宗教傳統中的儀式，而是一種超越語言的視覺探索，一種屬於個人精神領域的神聖私密圖像學。\r\n作為一名創作者，我不斷追尋人生與世界的真理，並在夢境與積極想像中接收無法用邏輯解釋的啟示。夢不只是夜晚的幻象，而是通往內在宇宙的門戶；想像不再是封閉的夢幻泡影，而是內在原型與意象的爆發。\r\n我試圖在創作中捕捉這些來自潛意識的象徵，並透過繪畫與影像，創造屬於自己的壇城——一座由少女之眼觀看介於夢與現實、私密與神聖之間的場域。這是一場個人的儀式，一場關於成長、存在與神性連結的靜謐對話。\r\n在這個展覽中，符號與儀式不再是既定的，而是個人神聖性的延伸。少女的視角並非脆弱，而是一種細緻入微的觀看方式，能夠感知世界的隱秘法則。在這座壇城中，觀者將進入一個全新的感知場域，與自己的潛意識相遇，在這裡，夢與想像不是虛幻，而是真理的倒影，並在影像與符號之間尋找個人意義的回音。\r\n《少女壇城》不只是我的創造，更是一場心理的遷移，一場退行至直覺與象徵的過程。在這座壇城中，夢境與現實相互滲透，私密符號與集體原型交錯成形。這裡沒有固定的敘事，只有象徵與意識碎片的堆疊。當觀者進入這座壇城，他們或許能在混沌與未知之中，尋回屬於自己的內在少女。', `organizer`='蔣維珊', `address`='高雄市鹽埕區', `start_date`='2025-02-15 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='鹽埕區（高雄市）=', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1BFssfkcaT/', `image_url`='[]';
