INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fe0a26b3240c403d95bf', '「偶‧多元文化之身」特展導覽', '國立臺灣博物館自日本時代即陸續蒐藏閩南及南洋地區與偶戲相關的文物，在總督府博物館和台灣省立博物館的既有基礎上，累積偶戲館藏約1千餘件。2020年台原亞洲偶戲博物館的林經甫博士，將其多達1萬1千多件遍及全球之偶戲文物捐贈至臺博館，使臺博館偶戲典藏多達1萬5千餘件，躋身當今世界擁有重要亞洲偶戲藏品的博物館之列。\n\n林經甫博士捐贈的偶戲文物包含臺灣、閩南、客家的傳統戲偶，還有緬甸、越南、柬埔寨、印尼、泰國、印度、日本等國家，是亞洲最具完整性的戲偶收藏。同時有多類偶戲之戲台、戲偶、戲服、道具與劇本，亦有諸多相關的繪畫、雕塑與面具等，種類極豐。其中還有許多來自世界各地的「民間佚名」藝師之手，承載著各地多元文化中以往較不被關注的重要瑰寶。\n\n本展精選台原捐贈的偶戲文物之精華，以「偶‧多元文化之身」為名，點出：偶之身是因一地文化而塑成，因此其亦可視為文化之身。\n\n內容劃分三大主題：「打開偶戲珍寶箱」、「偶戲千面收萬象」及「觀覽偶戲萬花筒」，突破過往多從地域論偶戲的格套，以更寬廣的視角探討偶戲的文化價值與多元風貌。\n\n「偶‧多元文化之身」特展導覽\n\n🙂參加對象：一般大眾\n\n😡報名方式：請依場次時間至國立臺灣博物館本館服務台報名登記\n\n😭費用：免費，須購票入館(全票30元、優待票15元)\n\n🤣地點：國立臺灣博物館本館(1樓東側展間)\n\n2月場次\n\n\n	\n		\n			\n			導覽日期\n			\n			\n			時段(上午)\n			\n			\n			時段(下午)\n			\n		\n		\n			\n			02/18(二)\n			\n			\n			10:30-11:30\n			\n			\n			 \n			\n		\n		\n			02/19(三)\n			10:30-11:30\n			 \n		\n	\n\n\n \n\n3月場次\n\n\n	\n		\n			導覽日期\n			時段(上午)\n			時段(下午)\n		\n		\n			03/01(六)\n			10:30-11:30\n			 \n		\n		\n			03/08(六)\n			10:30-11:30\n			14:30-15:30\n		\n		\n			03/11(二)\n			10:30-11:30\n			 \n		\n		\n			03/12(三)\n			 \n			14:30-15:30\n		\n		\n			03/15(六)\n			10:30-11:30\n			 \n		\n		\n			03/16(日)\n			10:30-11:30\n			 \n		\n		\n			03/20(四)\n			10:30-1130\n			14:30-15:30\n		\n		\n			03/22(六)\n			 \n			14:30-15:30\n		\n		\n			03/29(六)\n			10:30-11:30\n			 \n		\n	\n\n\n ', '國立臺灣博物館', '100  臺北市中正區中正區襄陽路2號(二二八公園內)', '2025-02-18 00:00:00', '2025-03-29 00:00:00', '臺博館本館', 25.0418254, 121.5149875, '無資料', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=50078', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「偶‧多元文化之身」特展導覽', `description`='國立臺灣博物館自日本時代即陸續蒐藏閩南及南洋地區與偶戲相關的文物，在總督府博物館和台灣省立博物館的既有基礎上，累積偶戲館藏約1千餘件。2020年台原亞洲偶戲博物館的林經甫博士，將其多達1萬1千多件遍及全球之偶戲文物捐贈至臺博館，使臺博館偶戲典藏多達1萬5千餘件，躋身當今世界擁有重要亞洲偶戲藏品的博物館之列。\n\n林經甫博士捐贈的偶戲文物包含臺灣、閩南、客家的傳統戲偶，還有緬甸、越南、柬埔寨、印尼、泰國、印度、日本等國家，是亞洲最具完整性的戲偶收藏。同時有多類偶戲之戲台、戲偶、戲服、道具與劇本，亦有諸多相關的繪畫、雕塑與面具等，種類極豐。其中還有許多來自世界各地的「民間佚名」藝師之手，承載著各地多元文化中以往較不被關注的重要瑰寶。\n\n本展精選台原捐贈的偶戲文物之精華，以「偶‧多元文化之身」為名，點出：偶之身是因一地文化而塑成，因此其亦可視為文化之身。\n\n內容劃分三大主題：「打開偶戲珍寶箱」、「偶戲千面收萬象」及「觀覽偶戲萬花筒」，突破過往多從地域論偶戲的格套，以更寬廣的視角探討偶戲的文化價值與多元風貌。\n\n「偶‧多元文化之身」特展導覽\n\n🙂參加對象：一般大眾\n\n😡報名方式：請依場次時間至國立臺灣博物館本館服務台報名登記\n\n😭費用：免費，須購票入館(全票30元、優待票15元)\n\n🤣地點：國立臺灣博物館本館(1樓東側展間)\n\n2月場次\n\n\n	\n		\n			\n			導覽日期\n			\n			\n			時段(上午)\n			\n			\n			時段(下午)\n			\n		\n		\n			\n			02/18(二)\n			\n			\n			10:30-11:30\n			\n			\n			 \n			\n		\n		\n			02/19(三)\n			10:30-11:30\n			 \n		\n	\n\n\n \n\n3月場次\n\n\n	\n		\n			導覽日期\n			時段(上午)\n			時段(下午)\n		\n		\n			03/01(六)\n			10:30-11:30\n			 \n		\n		\n			03/08(六)\n			10:30-11:30\n			14:30-15:30\n		\n		\n			03/11(二)\n			10:30-11:30\n			 \n		\n		\n			03/12(三)\n			 \n			14:30-15:30\n		\n		\n			03/15(六)\n			10:30-11:30\n			 \n		\n		\n			03/16(日)\n			10:30-11:30\n			 \n		\n		\n			03/20(四)\n			10:30-1130\n			14:30-15:30\n		\n		\n			03/22(六)\n			 \n			14:30-15:30\n		\n		\n			03/29(六)\n			10:30-11:30\n			 \n		\n	\n\n\n ', `organizer`='國立臺灣博物館', `address`='100  臺北市中正區中正區襄陽路2號(二二八公園內)', `start_date`='2025-02-18 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺博館本館', `latitude`=25.0418254, `longitude`=121.5149875, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=50078', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fe0c26b3240c403d95c0', '卑南遺址公園｜假日賞屋團', '活動日期｜3/15 （六）13:30-16:30\n報名費用｜500元（含手作體驗）\n報到地點｜臺東市文化公園路底，近考古現場\n\n注意事項｜\n1. 為維持賞屋品質，僅提供給16歲以上報名參加\n2. 僅開放5位貴賓蒞臨體驗\n3. 過程中高低階落差較大，請評估身體狀況。\n\n賞屋體驗行程包含｜\n史家建案鑽玉體驗，手作玉佩皮件吊飾作為賞屋紀念\n\n\n \n\n活動進行時將拍攝影像作為紀錄與成果使用，感謝！\n\n ', '國立臺灣史前文化博物館', '無資料', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '無資料', 0, 0, '無資料', 'https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=50140', '[]') ON DUPLICATE KEY UPDATE `activity_name`='卑南遺址公園｜假日賞屋團', `description`='活動日期｜3/15 （六）13:30-16:30\n報名費用｜500元（含手作體驗）\n報到地點｜臺東市文化公園路底，近考古現場\n\n注意事項｜\n1. 為維持賞屋品質，僅提供給16歲以上報名參加\n2. 僅開放5位貴賓蒞臨體驗\n3. 過程中高低階落差較大，請評估身體狀況。\n\n賞屋體驗行程包含｜\n史家建案鑽玉體驗，手作玉佩皮件吊飾作為賞屋紀念\n\n\n \n\n活動進行時將拍攝影像作為紀錄與成果使用，感謝！\n\n ', `organizer`='國立臺灣史前文化博物館', `address`='無資料', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=50140', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fea626b3240c403d95c1', '煥彩逸境~郭金保個展', '郭金保台南府城人，字行雲，號德聞。少時從工筆花卉及人物入門，爾後鑽研嶺南畫派，再以山水技法轉為潑墨寫意。在創畫中以簡潔、單純的線條構成並塑造出萬丈絕壁的雄偉氣勢，形廓線條頓挫勁健，岩石皴法緊峭有力，雲煙以彩墨潑之，形成了對比強烈的視覺效果。今以「煥彩逸境」為展覽主題，來呈現大自然帶給人們的嚮往與追尋。', '臺南市政府文化局', '臺南市歸仁區信義南路78號', '2025-02-21 00:00:00', '2025-03-16 00:00:00', '歸仁文化中心', 22.94679469, 120.2930627, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='煥彩逸境~郭金保個展', `description`='郭金保台南府城人，字行雲，號德聞。少時從工筆花卉及人物入門，爾後鑽研嶺南畫派，再以山水技法轉為潑墨寫意。在創畫中以簡潔、單純的線條構成並塑造出萬丈絕壁的雄偉氣勢，形廓線條頓挫勁健，岩石皴法緊峭有力，雲煙以彩墨潑之，形成了對比強烈的視覺效果。今以「煥彩逸境」為展覽主題，來呈現大自然帶給人們的嚮往與追尋。', `organizer`='臺南市政府文化局', `address`='臺南市歸仁區信義南路78號', `start_date`='2025-02-21 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='歸仁文化中心', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fea626b3240c403d95c2', '青天白日滿地虹 - 積吶虹光', '積吶虹光LEF將帶領觀眾進入一個充滿愛與和平的藝術世界，展覽以虹為核心，深入探索這一自然現象的象徵意義。虹，是自然中的迷人光學現象，不僅在視覺上令人驚豔，更承載著希望、和平、轉變和連接的深刻象徵，虹的每一道色彩都在講述一個故事，積吶虹光將這些故事交織成一幅幅充滿愛與和平的畫作，希望讓觀眾感受到虹的魅力及帶來的幸運與祝福。', '臺南市政府文化局', '臺南市歸仁區信義南路78號', '2025-02-22 00:00:00', '2025-03-16 00:00:00', '歸仁文化中心', 22.94679469, 120.2930627, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='青天白日滿地虹 - 積吶虹光', `description`='積吶虹光LEF將帶領觀眾進入一個充滿愛與和平的藝術世界，展覽以虹為核心，深入探索這一自然現象的象徵意義。虹，是自然中的迷人光學現象，不僅在視覺上令人驚豔，更承載著希望、和平、轉變和連接的深刻象徵，虹的每一道色彩都在講述一個故事，積吶虹光將這些故事交織成一幅幅充滿愛與和平的畫作，希望讓觀眾感受到虹的魅力及帶來的幸運與祝福。', `organizer`='臺南市政府文化局', `address`='臺南市歸仁區信義南路78號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='歸仁文化中心', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0feaa26b3240c403d95c4', '向陽美展-臺南市北區國民中小學美術班聯合畢業美展 ', '向陽美展是臺南市民德國中及立人國小美術班應屆畢業學生聯合展出，「向陽花木早逢春」，期待美術班學生有如向陽花木，透過美術專業課程培育，能及早開發在藝術創作上的天賦與潛能，獲得最佳發展。\r\n今年適逢臺南走向別具意義里程，我們以「建城三百，府看向陽」之姿，藉由聯合美展活動期望呈現孩子純真視角下的繽紛世界，傳達出他們對藝術、對生命的體驗與情感，描繪出對藝術的想像及熱情，邀請您一起來進行一場豐富精采的藝術饗宴！\r\n', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-02-22 00:00:00', '2025-03-09 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='向陽美展-臺南市北區國民中小學美術班聯合畢業美展 ', `description`='向陽美展是臺南市民德國中及立人國小美術班應屆畢業學生聯合展出，「向陽花木早逢春」，期待美術班學生有如向陽花木，透過美術專業課程培育，能及早開發在藝術創作上的天賦與潛能，獲得最佳發展。\r\n今年適逢臺南走向別具意義里程，我們以「建城三百，府看向陽」之姿，藉由聯合美展活動期望呈現孩子純真視角下的繽紛世界，傳達出他們對藝術、對生命的體驗與情感，描繪出對藝術的想像及熱情，邀請您一起來進行一場豐富精采的藝術饗宴！\r\n', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fead26b3240c403d95c5', '楠西區圖書館：2月主題書展「星座」', '有１２個星座，而每個星座的個性人格，都有所不同，跟著楠西圖書館帶著大家，探尋有趣、奇妙的星座。', '臺南市楠西區圖書館', '臺南市楠西區中正路309號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南市楠西區圖書館', 23.17885854, 120.5170304, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='楠西區圖書館：2月主題書展「星座」', `description`='有１２個星座，而每個星座的個性人格，都有所不同，跟著楠西圖書館帶著大家，探尋有趣、奇妙的星座。', `organizer`='臺南市楠西區圖書館', `address`='臺南市楠西區中正路309號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市楠西區圖書館', `latitude`=23.17885854, `longitude`=120.5170304, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
