INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0feb526b3240c403d95c8', '關廟區圖書館:「2024 open book好書獎」主題書展', '主題書展—「2024 Open Book好書獎圖書聯展」,即日起開始提供外借服務,歡迎讀者至一樓展示區借閱。', '臺南市關廟區圖書館', '臺南市關廟區文化街1號', '2025-02-04 00:00:00', '2025-02-27 00:00:00', '臺南市關廟區圖書館', 22.95577909, 120.3342821, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='關廟區圖書館:「2024 open book好書獎」主題書展', `description`='主題書展—「2024 Open Book好書獎圖書聯展」,即日起開始提供外借服務,歡迎讀者至一樓展示區借閱。', `organizer`='臺南市關廟區圖書館', `address`='臺南市關廟區文化街1號', `start_date`='2025-02-04 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺南市關廟區圖書館', `latitude`=22.95577909, `longitude`=120.3342821, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0febc26b3240c403d95ca', '新市區圖書館:二月主題書展', '成人-投資理財\r\n隨著通貨膨脹，錢的幣值感愈來愈薄，傳統的存錢方式已經跟不上通膨的\r\n速度，投資方式百百種，進行任何投資之前，建議先釐清自身的投資目的，才能選擇合適標的。投資有一定風險，雞蛋不要放在同一個籃子，分散風險，才能賺得更多。\r\n兒童-新視野學習百科\r\n百科全書最大的功能就是透過不同主題，從天文到地理，從人文至科學，啟發人們各方面的知識，擴大視野，書本身就像一座寶藏，所謂書中自有黃金屋，不但可以獲取知識，有時還能從中增長人生智慧。', '臺南市新市區圖書館', '臺南市新市區民族路192號', '2025-02-04 00:00:00', '2025-02-27 00:00:00', '臺南市新市區圖書館', 23.08319496, 120.2923941, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新市區圖書館:二月主題書展', `description`='成人-投資理財\r\n隨著通貨膨脹，錢的幣值感愈來愈薄，傳統的存錢方式已經跟不上通膨的\r\n速度，投資方式百百種，進行任何投資之前，建議先釐清自身的投資目的，才能選擇合適標的。投資有一定風險，雞蛋不要放在同一個籃子，分散風險，才能賺得更多。\r\n兒童-新視野學習百科\r\n百科全書最大的功能就是透過不同主題，從天文到地理，從人文至科學，啟發人們各方面的知識，擴大視野，書本身就像一座寶藏，所謂書中自有黃金屋，不但可以獲取知識，有時還能從中增長人生智慧。', `organizer`='臺南市新市區圖書館', `address`='臺南市新市區民族路192號', `start_date`='2025-02-04 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺南市新市區圖書館', `latitude`=23.08319496, `longitude`=120.2923941, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0febf26b3240c403d95cb', '｜東區林森圖書館｜2月主題書展 - ', '由館員選書，針對各式的「科技」專題書籍，主軸：連結未來，啟發無限可能，進行小型策展，提供讀者參考與借閱指引。', '臺南市東區林森圖書館', '臺南市東區林森路二段46號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南市東區林森圖書館', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='｜東區林森圖書館｜2月主題書展 - ', `description`='由館員選書，針對各式的「科技」專題書籍，主軸：連結未來，啟發無限可能，進行小型策展，提供讀者參考與借閱指引。', `organizer`='臺南市東區林森圖書館', `address`='臺南市東區林森路二段46號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市東區林森圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fec026b3240c403d95cc', '蕭壠兒童圖書館-2月主題書展-十二生肖同樂會', '延續上個月生肖主題，大家過新年會依據各種生肖來看運勢，因此特別展出有關十二生肖的各種繪本，生動有趣的故事，讓小朋友了解十二生肖各種動物的由來故事，也可認識自己的生肖動物。', '蕭壠兒童圖書館', '臺南市佳里區六安130號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南市蕭壠文化園區', 23.1669941, 120.178593, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蕭壠兒童圖書館-2月主題書展-十二生肖同樂會', `description`='延續上個月生肖主題，大家過新年會依據各種生肖來看運勢，因此特別展出有關十二生肖的各種繪本，生動有趣的故事，讓小朋友了解十二生肖各種動物的由來故事，也可認識自己的生肖動物。', `organizer`='蕭壠兒童圖書館', `address`='臺南市佳里區六安130號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市蕭壠文化園區', `latitude`=23.1669941, `longitude`=120.178593, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fec826b3240c403d95cd', '喜樹圖書館:浪漫閱讀(書香情人)書展', '本次書展以愛情、浪漫、情感表達相關的各類書籍為主。書展內容包括了國內外浪漫文學作品（各種愛情小說、經典浪漫文學、現代浪漫故事等），及戀愛心理學、婚姻、情感教育方面的書籍，歡迎民眾到館閱讀借閱。\r\n', '臺南市南區喜樹圖書館', '臺南市南區喜樹路179號', '2025-02-05 00:00:00', '2025-02-27 00:00:00', '臺南市南區喜樹圖書館', 22.95561863, 120.1903743, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='喜樹圖書館:浪漫閱讀(書香情人)書展', `description`='本次書展以愛情、浪漫、情感表達相關的各類書籍為主。書展內容包括了國內外浪漫文學作品（各種愛情小說、經典浪漫文學、現代浪漫故事等），及戀愛心理學、婚姻、情感教育方面的書籍，歡迎民眾到館閱讀借閱。\r\n', `organizer`='臺南市南區喜樹圖書館', `address`='臺南市南區喜樹路179號', `start_date`='2025-02-05 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺南市南區喜樹圖書館', `latitude`=22.95561863, `longitude`=120.1903743, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fecc26b3240c403d95ce', '安平區圖書館:2月書展養生食譜', '過年期間是不是天天吃得像皇帝一樣，\r\n魚肉盛宴呢？\r\n不如在年後來點新花樣，\r\n親手煮一頓健康餐，\r\n恢復那迷人的身材', '無資料', '臺南市安平區育平路320號', '2025-02-03 00:00:00', '2025-02-28 00:00:00', '臺南市安平區圖書館', 22.99008437, 120.1649949, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='安平區圖書館:2月書展養生食譜', `description`='過年期間是不是天天吃得像皇帝一樣，\r\n魚肉盛宴呢？\r\n不如在年後來點新花樣，\r\n親手煮一頓健康餐，\r\n恢復那迷人的身材', `organizer`='無資料', `address`='臺南市安平區育平路320號', `start_date`='2025-02-03 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市安平區圖書館', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fecc26b3240c403d95cf', '白河區圖書館 :2月份主題書展-自在身心 樂享人生', '在現代步入高齡化社會下，您知道如何繼續維持健康、或改善身體活動功能嗎？多動腦預防失智並透過運動維持身體健康、紓解壓力，保持正向的人生觀，活得快樂最重要!', '臺南市白河區圖書館', '臺南市白河區新興路573號', '2025-02-03 00:00:00', '2025-02-27 00:00:00', '張慶芳紀念圖書館(白河區圖書館)', 23.35132068, 120.4578565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='白河區圖書館 :2月份主題書展-自在身心 樂享人生', `description`='在現代步入高齡化社會下，您知道如何繼續維持健康、或改善身體活動功能嗎？多動腦預防失智並透過運動維持身體健康、紓解壓力，保持正向的人生觀，活得快樂最重要!', `organizer`='臺南市白河區圖書館', `address`='臺南市白河區新興路573號', `start_date`='2025-02-03 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='張慶芳紀念圖書館(白河區圖書館)', `latitude`=23.35132068, `longitude`=120.4578565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
