INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fecf26b3240c403d95d7', '「考古埕－尋找熱蘭遮市鎮」特展-2025「貓之日x貓之影」第一屆考古埕曬貓大會(展示活動)', '↪️2025「貓之日x貓之影」第一屆考古埕曬貓大會 | \r\n😸讓生活中的貓咪剪影，跟隨400年前的先貓腳步，一同在2025年度「貓之日」入侵考古埕的小宇宙！\r\n曬貓展出： 𝟐.𝟐𝟐~ 𝟑.𝟑(「考古埕-尋找熱蘭遮市鎮」特展營運開放時段）\r\n\r\n「考古埕-尋找熱蘭遮市鎮」特展\r\n►►四大展區║探坑走廊／距今實驗室／鯤島旅行社／修復里院║\r\n「這場持續探尋臺南四百年歷史時空的考古行動，象徵著古都臺南過去、現在與未來樣貌的鏈結。」由劍獅埕／考古埕歷年研究發掘成果相伴，走向城市時空、物質、常民生活的反思，踏上今昔交錯／虛實交織的跨時空旅行，終於回歸彌足珍貴的每個當下和日常。\r\n四大展區內容包括近年大員市鎮考古發掘探坑、相關考古遺物展示及成果說明、考古科學體驗以及以大員市鎮為背景的電玩遊戲體驗等等。本次特展帶領觀者透過實體考古探坑及虛擬數位電玩回到四百年以前的大員市鎮，在安平現地感受今昔交錯與考古學穿越時空的魅力。', '臺南市文化資產管理處', '臺南市安平區', '2025-02-22 00:00:00', '2025-03-03 00:00:00', '安平區（臺南市）=', 22.99008437, 120.1649949, '無資料', 'https://lihi.cc/v9Xvf', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「考古埕－尋找熱蘭遮市鎮」特展-2025「貓之日x貓之影」第一屆考古埕曬貓大會(展示活動)', `description`='↪️2025「貓之日x貓之影」第一屆考古埕曬貓大會 | \r\n😸讓生活中的貓咪剪影，跟隨400年前的先貓腳步，一同在2025年度「貓之日」入侵考古埕的小宇宙！\r\n曬貓展出： 𝟐.𝟐𝟐~ 𝟑.𝟑(「考古埕-尋找熱蘭遮市鎮」特展營運開放時段）\r\n\r\n「考古埕-尋找熱蘭遮市鎮」特展\r\n►►四大展區║探坑走廊／距今實驗室／鯤島旅行社／修復里院║\r\n「這場持續探尋臺南四百年歷史時空的考古行動，象徵著古都臺南過去、現在與未來樣貌的鏈結。」由劍獅埕／考古埕歷年研究發掘成果相伴，走向城市時空、物質、常民生活的反思，踏上今昔交錯／虛實交織的跨時空旅行，終於回歸彌足珍貴的每個當下和日常。\r\n四大展區內容包括近年大員市鎮考古發掘探坑、相關考古遺物展示及成果說明、考古科學體驗以及以大員市鎮為背景的電玩遊戲體驗等等。本次特展帶領觀者透過實體考古探坑及虛擬數位電玩回到四百年以前的大員市鎮，在安平現地感受今昔交錯與考古學穿越時空的魅力。', `organizer`='臺南市文化資產管理處', `address`='臺南市安平區', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-03 00:00:00', `location`='安平區（臺南市）=', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='https://lihi.cc/v9Xvf', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fed126b3240c403d95d8', '東山區圖書館 : 02月主題書展-青少年文學書展', '2月主題:青少年文學書展\r\n閱讀可以透過書籍得到某種樂趣,自我紓解與療癒。\r\n青少年小說十分適合「閱讀」,能輕鬆引領孩子進入文學的世界,領略文字的美麗,享受閱讀的樂趣。\r\n所以不只是青少年,大家一起來閱讀青少年小說吧', '臺南市東山區圖書館', '臺南市東山區225之4號2F', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南市東山區圖書館', 23.2783187, 120.4441211, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='東山區圖書館 : 02月主題書展-青少年文學書展', `description`='2月主題:青少年文學書展\r\n閱讀可以透過書籍得到某種樂趣,自我紓解與療癒。\r\n青少年小說十分適合「閱讀」,能輕鬆引領孩子進入文學的世界,領略文字的美麗,享受閱讀的樂趣。\r\n所以不只是青少年,大家一起來閱讀青少年小說吧', `organizer`='臺南市東山區圖書館', `address`='臺南市東山區225之4號2F', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市東山區圖書館', `latitude`=23.2783187, `longitude`=120.4441211, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fed126b3240c403d95d9', '安南圖書館-2月書展「濕地世界」、「EASY玩科學」', '「濕地世界」：濕地是介於陸生和水生生態系統間的地帶，水分充足的環境下孕育出豐富的生態系統，如此「細膩」的環境成為了水生植物和鳥類的天堂，更有「地球之肺」的美稱。2月2日是世界濕地日，由國際濕地公約常委會於1996年10月確立。\r\n「EASY玩科學」：對於日常生活當中常見的科學原理，民眾總是一知半解，藉由本月書展陪您與孩子從生活中常見現象的科學原理，引起孩子的「好奇心」並了解科學的意義，再將概念應用在人與自然之間。一起翻開書去找出你們最想體驗的實驗遊戲，陪孩子玩出聰明腦以及解決問題的能力。', '臺南市安南區安南圖書館', '臺南市安南區安中路二段 301號3樓', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南市安南區安南圖書館', 23.04869681, 120.1526189, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='安南圖書館-2月書展「濕地世界」、「EASY玩科學」', `description`='「濕地世界」：濕地是介於陸生和水生生態系統間的地帶，水分充足的環境下孕育出豐富的生態系統，如此「細膩」的環境成為了水生植物和鳥類的天堂，更有「地球之肺」的美稱。2月2日是世界濕地日，由國際濕地公約常委會於1996年10月確立。\r\n「EASY玩科學」：對於日常生活當中常見的科學原理，民眾總是一知半解，藉由本月書展陪您與孩子從生活中常見現象的科學原理，引起孩子的「好奇心」並了解科學的意義，再將概念應用在人與自然之間。一起翻開書去找出你們最想體驗的實驗遊戲，陪孩子玩出聰明腦以及解決問題的能力。', `organizer`='臺南市安南區安南圖書館', `address`='臺南市安南區安中路二段 301號3樓', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市安南區安南圖書館', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
