INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fed426b3240c403d95dc', '安定區圖書館：2月主題書展-情有讀鐘', '愛是一種行動，是人力量的發揮，讓我們從閱讀探索之間了解愛.學習愛，尋找你專屬的幸福。展出的書有56本，對愛入座、愛情市場學、相親相愛不簡單、愛的能量、愛他也愛自己、過度付出的愛、兒童愛之語、愛事一切答案、發現愛的那一天、說100次我愛你、愛的小旅行....等等。', '臺南市安定區圖書館', '臺南市安定區262之8號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南市安定區圖書館', 23.09974927, 120.2296235, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='安定區圖書館：2月主題書展-情有讀鐘', `description`='愛是一種行動，是人力量的發揮，讓我們從閱讀探索之間了解愛.學習愛，尋找你專屬的幸福。展出的書有56本，對愛入座、愛情市場學、相親相愛不簡單、愛的能量、愛他也愛自己、過度付出的愛、兒童愛之語、愛事一切答案、發現愛的那一天、說100次我愛你、愛的小旅行....等等。', `organizer`='臺南市安定區圖書館', `address`='臺南市安定區262之8號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市安定區圖書館', `latitude`=23.09974927, `longitude`=120.2296235, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fed426b3240c403d95dd', '南區鹽埕圖書館：關於愛主題書展', '希望民眾能透過閱讀關於親情、愛情、友情等與愛相關的書籍，能與身邊的人相處更加融洽。', '臺南市南區鹽埕圖書館', '臺南市南區新和東路51號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺南市南區鹽埕圖書館', 22.95561863, 120.1903743, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南區鹽埕圖書館：關於愛主題書展', `description`='希望民眾能透過閱讀關於親情、愛情、友情等與愛相關的書籍，能與身邊的人相處更加融洽。', `organizer`='臺南市南區鹽埕圖書館', `address`='臺南市南區新和東路51號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺南市南區鹽埕圖書館', `latitude`=22.95561863, `longitude`=120.1903743, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fed426b3240c403d95de', '臺南市113學年度北區國民中小學美術班聯合畢業美展', '本次聯展由54名學生參與，共計展出183件優秀作品。\r\n立人國小美術班六年級27名畢業生以「未來展場」為主題，作品包含了彩畫、平面設計、水墨、書法、複合媒材…等，其中複合媒材的作品「自畫像」也運用了資訊AI與作品做結合，藉由科技的輔助幫助孩子們剖析內心想法，從繪畫中了解創作脈絡並同時療癒自己，相輔相成更多面向的創作與學習。\r\n民德國中美術班由本屆27名畢業生共同完成，展覽內容豐富多元，涵蓋素描、水彩、水墨、版畫、漫畫、平面設計、複合媒材等，學生們對於生活、環境具有高度的敏銳度，再加上熟練的媒材技法，完成許多豐富且精彩的作品。', '臺南市政府教育局', '臺南市東區中華東路三段332號', '2025-02-22 00:00:00', '2025-03-09 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市113學年度北區國民中小學美術班聯合畢業美展', `description`='本次聯展由54名學生參與，共計展出183件優秀作品。\r\n立人國小美術班六年級27名畢業生以「未來展場」為主題，作品包含了彩畫、平面設計、水墨、書法、複合媒材…等，其中複合媒材的作品「自畫像」也運用了資訊AI與作品做結合，藉由科技的輔助幫助孩子們剖析內心想法，從繪畫中了解創作脈絡並同時療癒自己，相輔相成更多面向的創作與學習。\r\n民德國中美術班由本屆27名畢業生共同完成，展覽內容豐富多元，涵蓋素描、水彩、水墨、版畫、漫畫、平面設計、複合媒材等，學生們對於生活、環境具有高度的敏銳度，再加上熟練的媒材技法，完成許多豐富且精彩的作品。', `organizer`='臺南市政府教育局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fed526b3240c403d95df', '春鳴夏喚-曹程凱膠彩畫展', '2/15（六）14：00 開幕茶會', '星紅藝廊', '南投縣南投市', '2025-02-11 00:00:00', '2025-03-11 00:00:00', '南投市（南投縣）=', 23.92173537, 120.6787658, '無資料', 'https://www.facebook.com/HsingKungArtGallery', '[]') ON DUPLICATE KEY UPDATE `activity_name`='春鳴夏喚-曹程凱膠彩畫展', `description`='2/15（六）14：00 開幕茶會', `organizer`='星紅藝廊', `address`='南投縣南投市', `start_date`='2025-02-11 00:00:00', `end_date`='2025-03-11 00:00:00', `location`='南投市（南投縣）=', `latitude`=23.92173537, `longitude`=120.6787658, `ticket_price`='無資料', `source_url`='https://www.facebook.com/HsingKungArtGallery', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fed526b3240c403d95e0', '「物與物」王譽霖＆周霽恩金工創作展', '工具為物，材料為物\r\n我們在一方桌前，以鋸弓切鋸、以銼刀銼修、以鎚鏨敲形、以火槍焊接、以藥劑化染、以砂紙拋磨……在各種工具與金屬的層疊作用間，試圖造出一柄尺，一把刀，蝴蝶的翅脈，甲蟲的大顎，竹子的葉梢，纖柔的花瓣與竄生的枝芽。 \r\n\r\n而物不僅止於物\r\n物是隱喻，是專業與興趣的標誌，是時間的凝結，亦是感知的拓荒。我們以物造物，有時為了留下一段不忍其逝去的記憶，抑或為了讓某些難以言述、細膩而幽微的情感得以棲居。在物與物的交疊錯落間，一次次重燃對生命的想像、提問、追尋與感受。\r\n\r\n王譽霖 X 周霽恩\r\n個性與創作風格截然不同的兩人，自2014年於臺南藝術大學應用藝術研究所畢業後，一同成立「臍加厝手路金工」工作室。\r\n王譽霖的創作擅於探究工具與人之間的關係，在精細俐落的幾何造型間，呈現作者細膩而獨特的機構美感。作品曾入選美國LARK BOOKS 《Showcase 500 Art Necklaces》、獲臺灣國際金屬工藝大賽器物類金質獎，並受新北市立黃金博物館典藏。\r\n周霽恩擅於運用金屬的延展性，形塑出花、葉、卵石等自然間的有機線條與肌理，金工是她幻想並豢養綠意的方式。作品曾獲日本伊丹國際首飾展入選與臺灣國際金屬工藝大賽佳作。', '財團法人毓繡文化基金會', '南投縣草屯鎮健行路150巷26號', '2025-03-08 00:00:00', '2025-07-27 00:00:00', '毓繡美術館', 23.9859227, 120.766731, '無資料', 'https://www.yu-hsiu.org/exhibition/2/data/39', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「物與物」王譽霖＆周霽恩金工創作展', `description`='工具為物，材料為物\r\n我們在一方桌前，以鋸弓切鋸、以銼刀銼修、以鎚鏨敲形、以火槍焊接、以藥劑化染、以砂紙拋磨……在各種工具與金屬的層疊作用間，試圖造出一柄尺，一把刀，蝴蝶的翅脈，甲蟲的大顎，竹子的葉梢，纖柔的花瓣與竄生的枝芽。 \r\n\r\n而物不僅止於物\r\n物是隱喻，是專業與興趣的標誌，是時間的凝結，亦是感知的拓荒。我們以物造物，有時為了留下一段不忍其逝去的記憶，抑或為了讓某些難以言述、細膩而幽微的情感得以棲居。在物與物的交疊錯落間，一次次重燃對生命的想像、提問、追尋與感受。\r\n\r\n王譽霖 X 周霽恩\r\n個性與創作風格截然不同的兩人，自2014年於臺南藝術大學應用藝術研究所畢業後，一同成立「臍加厝手路金工」工作室。\r\n王譽霖的創作擅於探究工具與人之間的關係，在精細俐落的幾何造型間，呈現作者細膩而獨特的機構美感。作品曾入選美國LARK BOOKS 《Showcase 500 Art Necklaces》、獲臺灣國際金屬工藝大賽器物類金質獎，並受新北市立黃金博物館典藏。\r\n周霽恩擅於運用金屬的延展性，形塑出花、葉、卵石等自然間的有機線條與肌理，金工是她幻想並豢養綠意的方式。作品曾獲日本伊丹國際首飾展入選與臺灣國際金屬工藝大賽佳作。', `organizer`='財團法人毓繡文化基金會', `address`='南投縣草屯鎮健行路150巷26號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-07-27 00:00:00', `location`='毓繡美術館', `latitude`=23.9859227, `longitude`=120.766731, `ticket_price`='無資料', `source_url`='https://www.yu-hsiu.org/exhibition/2/data/39', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fed526b3240c403d95e1', '藝文講堂：隱匿於物的另一層真實', '主講者：丹．馬諸卡（羅馬尼亞），透過炭筆風景探索記憶與現實的交錯。牧田愛（日本），以機械構造隱喻生命，探討科技與自然的界線。\r\n主持人：\r\n汪正翔，擅長以平易近人的文字轉化賞析當代藝術的獨到視角。\r\n免費參加，歡迎提前預約03/09參觀，即可入座參與講座！\r\n預約參觀 https://www.yu-hsiu.org/visit', '財團法人毓繡文化基金會', '南投縣草屯鎮健行路150巷26號', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '毓繡美術館', 23.9859227, 120.766731, '無資料', 'https://www.facebook.com/yuhsiu.museum', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝文講堂：隱匿於物的另一層真實', `description`='主講者：丹．馬諸卡（羅馬尼亞），透過炭筆風景探索記憶與現實的交錯。牧田愛（日本），以機械構造隱喻生命，探討科技與自然的界線。\r\n主持人：\r\n汪正翔，擅長以平易近人的文字轉化賞析當代藝術的獨到視角。\r\n免費參加，歡迎提前預約03/09參觀，即可入座參與講座！\r\n預約參觀 https://www.yu-hsiu.org/visit', `organizer`='財團法人毓繡文化基金會', `address`='南投縣草屯鎮健行路150巷26號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='毓繡美術館', `latitude`=23.9859227, `longitude`=120.766731, `ticket_price`='無資料', `source_url`='https://www.facebook.com/yuhsiu.museum', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fed526b3240c403d95e2', '鹿力同心．茸華客庄-2025年國姓鄉鹿神祭產業文化活動：彩妝踩街活動', '南投縣養殖的水鹿數量約4,600頭，約占全國數量的三分之一以上，是全國養殖水鹿數量、鹿茸產量最多的縣市，每年3至6月是鹿茸產季，年產值高達2.5億元，國姓鄉公所每年皆搭配在地產業及客家文化，辦理「鹿神祭」產業文化活動，凝聚地方向心力，促進鹿茸消費。\r\n今年的「鹿力同心．茸華客庄-2025年國姓鄉鹿神祭產業文化活動」結合第42屆全鄉運動會擴大辦理，並將「客庄好食．鹿茸養生宴」改在晚間舉行，就是要邀請全鄉居民一起來參與。當日白天將辦理彩妝踩街活動，在北山國中集結後則進行鹿神祭與全鄉運動會及社區趣味競賽，晚間則是在南天宮席開50桌的鹿茸養生宴及晚會表演，歡迎大家前來感受國姓客庄好客風情。', '南投縣國姓鄉公所', '南投縣國姓鄉', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '國姓鄉（南投縣）=', 24.03135413, 120.8676052, '無資料', 'https://www.guoshing.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鹿力同心．茸華客庄-2025年國姓鄉鹿神祭產業文化活動：彩妝踩街活動', `description`='南投縣養殖的水鹿數量約4,600頭，約占全國數量的三分之一以上，是全國養殖水鹿數量、鹿茸產量最多的縣市，每年3至6月是鹿茸產季，年產值高達2.5億元，國姓鄉公所每年皆搭配在地產業及客家文化，辦理「鹿神祭」產業文化活動，凝聚地方向心力，促進鹿茸消費。\r\n今年的「鹿力同心．茸華客庄-2025年國姓鄉鹿神祭產業文化活動」結合第42屆全鄉運動會擴大辦理，並將「客庄好食．鹿茸養生宴」改在晚間舉行，就是要邀請全鄉居民一起來參與。當日白天將辦理彩妝踩街活動，在北山國中集結後則進行鹿神祭與全鄉運動會及社區趣味競賽，晚間則是在南天宮席開50桌的鹿茸養生宴及晚會表演，歡迎大家前來感受國姓客庄好客風情。', `organizer`='南投縣國姓鄉公所', `address`='南投縣國姓鄉', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='國姓鄉（南投縣）=', `latitude`=24.03135413, `longitude`=120.8676052, `ticket_price`='無資料', `source_url`='https://www.guoshing.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fed526b3240c403d95e3', '2025年國姓鄉鹿神祭產業文化活動：客庄好食．鹿茸養生宴＆晚會表演', '南投縣養殖的水鹿數量約4,600頭，約占全國數量的三分之一以上，是全國養殖水鹿數量、鹿茸產量最多的縣市，每年3至6月是鹿茸產季，年產值高達2.5億元，國姓鄉公所每年皆搭配在地產業及客家文化，辦理「鹿神祭」產業文化活動，凝聚地方向心力，促進鹿茸消費。\r\n今年國姓鄉公所特別攜手南投縣烹飪商業同業公會推出每桌6,600元「客庄好食．鹿茸養生宴2.0」優化再升級，訂餐連結：https://reurl.cc/WAoyVk。而除了珍貴的鹿茸滋補養生食材，也將國姓鄉農特產品融入料理，訂餐好禮多重送，有限量活動手提餐盒、家電摸彩品及生鮮鹿茸抽獎。\r\n晚宴現場邀請藝人及在地團體演出，將是一場視覺、味覺與養生兼具的饗宴。', '南投縣國姓鄉公所', '南投縣國姓鄉', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '國姓鄉（南投縣）=', 24.03135413, 120.8676052, '鹿茸養生宴+6600', 'https://www.nantou.gov.tw/big5/news_content.php?dptid=376480000&cid=75&id=159974', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年國姓鄉鹿神祭產業文化活動：客庄好食．鹿茸養生宴＆晚會表演', `description`='南投縣養殖的水鹿數量約4,600頭，約占全國數量的三分之一以上，是全國養殖水鹿數量、鹿茸產量最多的縣市，每年3至6月是鹿茸產季，年產值高達2.5億元，國姓鄉公所每年皆搭配在地產業及客家文化，辦理「鹿神祭」產業文化活動，凝聚地方向心力，促進鹿茸消費。\r\n今年國姓鄉公所特別攜手南投縣烹飪商業同業公會推出每桌6,600元「客庄好食．鹿茸養生宴2.0」優化再升級，訂餐連結：https://reurl.cc/WAoyVk。而除了珍貴的鹿茸滋補養生食材，也將國姓鄉農特產品融入料理，訂餐好禮多重送，有限量活動手提餐盒、家電摸彩品及生鮮鹿茸抽獎。\r\n晚宴現場邀請藝人及在地團體演出，將是一場視覺、味覺與養生兼具的饗宴。', `organizer`='南投縣國姓鄉公所', `address`='南投縣國姓鄉', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='國姓鄉（南投縣）=', `latitude`=24.03135413, `longitude`=120.8676052, `ticket_price`='鹿茸養生宴+6600', `source_url`='https://www.nantou.gov.tw/big5/news_content.php?dptid=376480000&cid=75&id=159974', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fed526b3240c403d95e4', '音樂會-穿越時空 薩克斯風重奏', '演奏團體：二輪瑪吉斯\r\n二輪瑪吉斯將為大家帶來民歌組曲「恰似你的溫柔」、「動不動就說愛我」，還有大家都很熟悉的「熱情的沙漠」、「流浪到淡水」、「思慕的人」、「雨夜花」，另外還有童趣十足的「龍貓組曲」以及英文組曲「Close to you」、「Women in love」等優美樂章。邀請大家親近大自然的同時，一同感受被音樂及藝術畫作環繞的浪漫時分。\r\n本活動需事先報名。線上報名：https://forms.gle/mLnWWqFTYZBWtx1X9\r\n洽詢電話：049-2752203（營業時間 09:30-17:00）', '益品美術館', '南投縣鹿谷鄉中正路二段211巷19號', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '益品美術館', 23.73776029, 120.7815065, '門票+100', 'https://www.facebook.com/epmuseum', '[]') ON DUPLICATE KEY UPDATE `activity_name`='音樂會-穿越時空 薩克斯風重奏', `description`='演奏團體：二輪瑪吉斯\r\n二輪瑪吉斯將為大家帶來民歌組曲「恰似你的溫柔」、「動不動就說愛我」，還有大家都很熟悉的「熱情的沙漠」、「流浪到淡水」、「思慕的人」、「雨夜花」，另外還有童趣十足的「龍貓組曲」以及英文組曲「Close to you」、「Women in love」等優美樂章。邀請大家親近大自然的同時，一同感受被音樂及藝術畫作環繞的浪漫時分。\r\n本活動需事先報名。線上報名：https://forms.gle/mLnWWqFTYZBWtx1X9\r\n洽詢電話：049-2752203（營業時間 09:30-17:00）', `organizer`='益品美術館', `address`='南投縣鹿谷鄉中正路二段211巷19號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='益品美術館', `latitude`=23.73776029, `longitude`=120.7815065, `ticket_price`='門票+100', `source_url`='https://www.facebook.com/epmuseum', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fed626b3240c403d95e7', '台江圖書館：2月主題書展「我.自.己」', '閱讀，讓我們更靠近真實的自己 「我.自.己」不僅是書展的名字，更是一段自我認識的過程。翻開這些書籍，遇見一個不同的「你」——勇敢、溫柔、自主, 歡迎借閱 ,親子共讀，讓閱讀成為一場探尋自我的旅程。', '臺南市政府文化局', '臺南市安南區安吉路一段205、207號', '2025-02-02 00:00:00', '2025-02-27 00:00:00', '台江文化中心', 23.04869681, 120.1526189, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台江圖書館：2月主題書展「我.自.己」', `description`='閱讀，讓我們更靠近真實的自己 「我.自.己」不僅是書展的名字，更是一段自我認識的過程。翻開這些書籍，遇見一個不同的「你」——勇敢、溫柔、自主, 歡迎借閱 ,親子共讀，讓閱讀成為一場探尋自我的旅程。', `organizer`='臺南市政府文化局', `address`='臺南市安南區安吉路一段205、207號', `start_date`='2025-02-02 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='台江文化中心', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
