INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b0fed626b3240c403d95ec', '國際民俗舞蹈體驗及書展（114年3月）', '「國際民俗舞蹈」體驗營，每月第三個週六下午舉辦，教授不同國家民俗舞蹈，帶領民眾藉由音樂與舞蹈，享受環遊世界的樂趣。現場並展示教授國家相關書籍及服飾。\r\n活動完全免費，歡迎體驗，洽詢電話：049-2317071', '國立公共資訊圖書館中興分館', '南投縣南投市中興新村光華路 123 號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '國立公共資訊圖書館中興分館', 23.949518, 120.694397, '無資料', 'https://www.facebook.com/NLPICH/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國際民俗舞蹈體驗及書展（114年3月）', `description`='「國際民俗舞蹈」體驗營，每月第三個週六下午舉辦，教授不同國家民俗舞蹈，帶領民眾藉由音樂與舞蹈，享受環遊世界的樂趣。現場並展示教授國家相關書籍及服飾。\r\n活動完全免費，歡迎體驗，洽詢電話：049-2317071', `organizer`='國立公共資訊圖書館中興分館', `address`='南投縣南投市中興新村光華路 123 號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='國立公共資訊圖書館中興分館', `latitude`=23.949518, `longitude`=120.694397, `ticket_price`='無資料', `source_url`='https://www.facebook.com/NLPICH/', `image_url`='[]';
