INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b24ff226b3240c403d9604', '文化局中文英文繪本故事屋：二月故事屋-SDG3健康福祉', '114年2月兒童中外文故事屋活動內容來囉\r\n114年主打主題SDGs永續發展3.0升級版、 #STEAM\r\n2月是主題SDG3健康福祉\r\n每個月除了有說故事活動之外，現場還有小型書展，歡迎借閱!\r\n114年中外文故事屋2月主題書展SDG3 https://reurl.cc/zpEdYa\r\n114年中外文故事屋2月主題書展SDG3書單https://reurl.cc/M6xyd4\r\n每個月最後一個星期日中文故事屋，\r\n2月23日週日10點到11點會有本土語言金門話推廣喔！\r\n歡迎大小朋友一起來聽故事，創造美好回憶🥰\r\n#每週六日10點到11點\r\n（不用報名，現場入座即可）\r\n地點：南棟一樓', '金門縣文化局', '金門縣金城鎮環島北路一段66號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '金門縣文化局', 24.38402, 118.30128, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='文化局中文英文繪本故事屋：二月故事屋-SDG3健康福祉', `description`='114年2月兒童中外文故事屋活動內容來囉\r\n114年主打主題SDGs永續發展3.0升級版、 #STEAM\r\n2月是主題SDG3健康福祉\r\n每個月除了有說故事活動之外，現場還有小型書展，歡迎借閱!\r\n114年中外文故事屋2月主題書展SDG3 https://reurl.cc/zpEdYa\r\n114年中外文故事屋2月主題書展SDG3書單https://reurl.cc/M6xyd4\r\n每個月最後一個星期日中文故事屋，\r\n2月23日週日10點到11點會有本土語言金門話推廣喔！\r\n歡迎大小朋友一起來聽故事，創造美好回憶🥰\r\n#每週六日10點到11點\r\n（不用報名，現場入座即可）\r\n地點：南棟一樓', `organizer`='金門縣文化局', `address`='金門縣金城鎮環島北路一段66號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='金門縣文化局', `latitude`=24.38402, `longitude`=118.30128, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b24ff326b3240c403d9605', '金門金響亮樂團「歌詠金門」音樂會(地點：山外社區發展協會）', '金門金響亮樂團「歌詠金門」音樂會\r\n-巡演啟動 音樂譜寫歷史文化新篇章-\r\n展開一系列社區與機構巡演，透過音樂展現金門豐厚的歷史底蘊與獨特的人文風情，為觀眾帶來一場視覺與聽覺兼具的文化饗宴。\r\n本次演出不僅是對金門文化的致敬，更是一次創新與傳承的結合。\r\n金門金響亮樂團 以金門的自然環境與文化特色為核心，精心編排曲目，透過悠揚旋律勾勒這片土地的故事，期望讓觀眾在樂聲中感受金門的深遠韻味，並建立更深厚的文化認同。\r\n「歌詠金門」音樂會將於下列時間與地點舉行：\r\n114年2月21日(五)19:00｜山外社區發展協會\r\n114年3月8日(六)  14:30｜大同之家\r\n114年3月29日(六)19:00｜上林社區發展協會\r\n114年4月12日(六)19:00｜信義社區發展協會\r\n114年5月17日(六)19:00｜古寧頭辦公室\r\n114年6月14日)六)19:00｜瓊林里辦公室\r\n歡迎有興趣的大小朋友共襄盛舉，透過音樂感受金門的歷史脈動與文化魅力，並在樂聲中尋找到對這片土地的全新詮釋與共鳴。歡迎民眾踴躍參與，一同沉浸於這場充滿情感與故事的音樂旅程。', '金門縣文化局', '金門縣金湖鎮', '2025-02-21 00:00:00', '2025-02-24 00:00:00', '金湖鎮（金門縣）=', 24.41496, 118.40373, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='金門金響亮樂團「歌詠金門」音樂會(地點：山外社區發展協會）', `description`='金門金響亮樂團「歌詠金門」音樂會\r\n-巡演啟動 音樂譜寫歷史文化新篇章-\r\n展開一系列社區與機構巡演，透過音樂展現金門豐厚的歷史底蘊與獨特的人文風情，為觀眾帶來一場視覺與聽覺兼具的文化饗宴。\r\n本次演出不僅是對金門文化的致敬，更是一次創新與傳承的結合。\r\n金門金響亮樂團 以金門的自然環境與文化特色為核心，精心編排曲目，透過悠揚旋律勾勒這片土地的故事，期望讓觀眾在樂聲中感受金門的深遠韻味，並建立更深厚的文化認同。\r\n「歌詠金門」音樂會將於下列時間與地點舉行：\r\n114年2月21日(五)19:00｜山外社區發展協會\r\n114年3月8日(六)  14:30｜大同之家\r\n114年3月29日(六)19:00｜上林社區發展協會\r\n114年4月12日(六)19:00｜信義社區發展協會\r\n114年5月17日(六)19:00｜古寧頭辦公室\r\n114年6月14日)六)19:00｜瓊林里辦公室\r\n歡迎有興趣的大小朋友共襄盛舉，透過音樂感受金門的歷史脈動與文化魅力，並在樂聲中尋找到對這片土地的全新詮釋與共鳴。歡迎民眾踴躍參與，一同沉浸於這場充滿情感與故事的音樂旅程。', `organizer`='金門縣文化局', `address`='金門縣金湖鎮', `start_date`='2025-02-21 00:00:00', `end_date`='2025-02-24 00:00:00', `location`='金湖鎮（金門縣）=', `latitude`=24.41496, `longitude`=118.40373, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
