INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b3881326b3240c403d9629', '2024 Openbook 好書獎．圖書館聯展', 'Openbook閱讀誌是2017創立、文化部鼎力支持的非營利線上書評媒體，總編及顧問團隊皆出身具30年歷史的專業書評版「開卷」。承襲獨立公正客觀精神，Openbook閱讀誌每年邀請專業評審。分初選、複選、決選三階段，從4000多本新書中，評選出4大類十大年度好書（共40本）。因嚴謹的評選過程，被創作者及出版人譽為「最想獲得的書籍獎項」。', 'Openbook閱讀誌', '桃園市蘆竹區五福一路255號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '桃園市立圖書館蘆竹分館', 25.06073337, 121.2831266, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2024 Openbook 好書獎．圖書館聯展', `description`='Openbook閱讀誌是2017創立、文化部鼎力支持的非營利線上書評媒體，總編及顧問團隊皆出身具30年歷史的專業書評版「開卷」。承襲獨立公正客觀精神，Openbook閱讀誌每年邀請專業評審。分初選、複選、決選三階段，從4000多本新書中，評選出4大類十大年度好書（共40本）。因嚴謹的評選過程，被創作者及出版人譽為「最想獲得的書籍獎項」。', `organizer`='Openbook閱讀誌', `address`='桃園市蘆竹區五福一路255號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='桃園市立圖書館蘆竹分館', `latitude`=25.06073337, `longitude`=121.2831266, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
