INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b3883426b3240c403d9638', '主題書展2月	', '主題書展「少年科普創意GO!」\r\n本月針對青少年以科普閱讀為發想，把自然科學的繁瑣的內容，用有趣的方法呈現，亦能培養學生好奇心、用淺白方式敘述準確的科學資料，使得科學新知能在大眾生活之間產生效應，民眾也能在學習新知過程中領會科普資訊。\r\n', '桃園市立圖書館', '桃園市觀音區新生路76巷8弄1號2樓之1', '2025-02-03 00:00:00', '2025-02-26 00:00:00', '桃園市立圖書館新坡分館', 25.02671611, 121.1155021, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='主題書展2月	', `description`='主題書展「少年科普創意GO!」\r\n本月針對青少年以科普閱讀為發想，把自然科學的繁瑣的內容，用有趣的方法呈現，亦能培養學生好奇心、用淺白方式敘述準確的科學資料，使得科學新知能在大眾生活之間產生效應，民眾也能在學習新知過程中領會科普資訊。\r\n', `organizer`='桃園市立圖書館', `address`='桃園市觀音區新生路76巷8弄1號2樓之1', `start_date`='2025-02-03 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='桃園市立圖書館新坡分館', `latitude`=25.02671611, `longitude`=121.1155021, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
