INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b3883f26b3240c403d9648', '台灣燈會-2025蘆竹炫YA科技藝術燈飾展', '本次以「光舞山林」為策展主軸，除配合情人節佈置心形燈飾及金紅色調營造吉祥的節慶氛圍，也將蘆竹在地特色巧妙融入燈飾設計中，以稻穗造型燈飾展現豐收景象，讓每位遊客在光影之間感受蘆竹的鄉土情懷與文化底蘊。', '桃園市蘆竹區公所', '桃園市蘆竹區', '2025-02-07 00:00:00', '2025-03-31 00:00:00', '蘆竹區（桃園市）=', 25.06073337, 121.2831266, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台灣燈會-2025蘆竹炫YA科技藝術燈飾展', `description`='本次以「光舞山林」為策展主軸，除配合情人節佈置心形燈飾及金紅色調營造吉祥的節慶氛圍，也將蘆竹在地特色巧妙融入燈飾設計中，以稻穗造型燈飾展現豐收景象，讓每位遊客在光影之間感受蘆竹的鄉土情懷與文化底蘊。', `organizer`='桃園市蘆竹區公所', `address`='桃園市蘆竹區', `start_date`='2025-02-07 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='蘆竹區（桃園市）=', `latitude`=25.06073337, `longitude`=121.2831266, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
