INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b3884526b3240c403d964c', 'SDGs繪本展-優質教育篇', '為發揮公共圖書館既有圖書資源，期使深入社區推動閱讀，每場主題繪本根據永續發展目標為依據展示，讓讀者透由繪本故事更加了解各項目標主旨及意義。', '高雄市立圖書館總館', '高雄市左營區2鄰啟文路12號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '高雄市立圖書館左營分館', 22.6735284, 120.2843433, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='SDGs繪本展-優質教育篇', `description`='為發揮公共圖書館既有圖書資源，期使深入社區推動閱讀，每場主題繪本根據永續發展目標為依據展示，讓讀者透由繪本故事更加了解各項目標主旨及意義。', `organizer`='高雄市立圖書館總館', `address`='高雄市左營區2鄰啟文路12號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='高雄市立圖書館左營分館', `latitude`=22.6735284, `longitude`=120.2843433, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b3f1658f15d8562cfcd6df', '2025彩雲講堂-綠色建築建築永續-MVRDV零碳建築的挑戰', '實現零碳建築是當今建築界，面臨的最急迫且具有挑戰性的目標之一。本次講座MVRDV將深入探討如何在個案中為達成創造永續建築的目標必須克服的諸多複雜性和障礙。創新的材料、先進的技術以及最前端的設計策略，這些正在重新定義我們對建築和能源使用的思考方式。從採用環保材料、實施可再生能源系統到翻新現有建築和確保建築高效運行，我們在邁向零碳的每一步，都需要精心的規劃、執行和承諾。\r\n\r\n誠摯歡迎您加入講座，探討如何通過深思熟慮的建築設計豐富城市生活。且一同揭開零碳建築的多面挑戰，並深入了解環保建築的未來。這段旅程雖然艱難，但為了我們的地球和未來世代，這一努力絕對值得。', '麗寶文化藝術基金會', '臺北市台北市信義區菸廠路88號B1', '2025-03-14 00:00:00', '2025-03-14 00:00:00', '松菸誠品表演廳', 0, 0, '免費藝文公益講座', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025彩雲講堂-綠色建築建築永續-MVRDV零碳建築的挑戰', `description`='實現零碳建築是當今建築界，面臨的最急迫且具有挑戰性的目標之一。本次講座MVRDV將深入探討如何在個案中為達成創造永續建築的目標必須克服的諸多複雜性和障礙。創新的材料、先進的技術以及最前端的設計策略，這些正在重新定義我們對建築和能源使用的思考方式。從採用環保材料、實施可再生能源系統到翻新現有建築和確保建築高效運行，我們在邁向零碳的每一步，都需要精心的規劃、執行和承諾。\r\n\r\n誠摯歡迎您加入講座，探討如何通過深思熟慮的建築設計豐富城市生活。且一同揭開零碳建築的多面挑戰，並深入了解環保建築的未來。這段旅程雖然艱難，但為了我們的地球和未來世代，這一努力絕對值得。', `organizer`='麗寶文化藝術基金會', `address`='臺北市台北市信義區菸廠路88號B1', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-14 00:00:00', `location`='松菸誠品表演廳', `latitude`=0, `longitude`=0, `ticket_price`='免費藝文公益講座', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4023c07f37a26088be582', '埔里美術館首展 - 藝起共眠 共鳴自然', '撰文者/策展人 田志興\r\n    2024是極端氣候爆發的一年，全球暖化伴隨而來的熱浪、洪水、乾旱及強烈風暴等天災進入常態化，是大自然對地球反噬警訊，所以每個人都必須從自身做起，減低對地球破壞的程度，而用藝術作品融入自然永續議題就是藝術家用實際行動來關心環境與人文的寫照。\r\n    在埔里鎮寶大飯店展開主題「藝起共眠 共鳴自然」許慶福石雕．張家銘石雕．曾俊豪油畫三個展，就是聯合三位長期關懷生態自然、社會人文的當代藝術翹楚所促成的展覽，現場約200件多品，除了是三位老師智慧與人生閱歷累積，作品本身也代表每段歲月光陰的故事。\r\n    這次展出石雕作品來響應環境議題的許慶福老師，曾在國立台灣工藝研究發展中心技術組任職，是具有石雕、玉石研磨、魚骨創作與複合媒材等多方面專業的大師級藝術職人。許慶福老師喜愛與大自然對話，以舊物作素材，由素材本身的造型、質地、紋理牽引出新的生命力，他創作的理念精神可以簡單用幾句話來傳遞，就是「只要用心觀察、材料無貴賤、處處都有其剩餘價值」。而許慶福老師具有環保指標的魚骨創作，是採用大自然給予的最佳免費材料-溪石，搭配吳郭魚的骨頭，結合成的絕妙作品，當時他花了八年時間嘗試了19種本土魚種，才發現吳郭魚的腮、齶擁有奇特與美麗的元素很適合創作，與這次展覽精神的自然永續議題完全契合。\r\n    身兼藝術家與鎮寶大飯店董事長秘書的張家銘老師，則具有石雕、複合媒材與油畫等創作專長，他在這回展出也以擅長的石雕為主題，與其他兩名藝術家共同擦出首展的話題之火。而在常人看似平淡無奇的石頭材料，經由許慶福與張家銘兩位石雕家手中，顯現的確是凹與凸的極致藝術，他們利用光影變幻的線條呈現出雕刻的趣味與美感，還利用石材自然的紋理呈現自己的樣貌。在藝術家者眼中，一切都是美的，因為他們銳利的慧眼，能夠注視到一切眾生萬物的核心．抉發其性，透過外在形象觸及其內在真實，這就是真實即是美的具體表現手法', '鎮寶大飯店', '南投縣南投縣埔里鎮忠孝路299號', '2025-02-22 00:00:00', '2025-03-25 00:00:00', '鎮寶美術館', 0, 0, '免費', '無', '[]') ON DUPLICATE KEY UPDATE `activity_name`='埔里美術館首展 - 藝起共眠 共鳴自然', `description`='撰文者/策展人 田志興\r\n    2024是極端氣候爆發的一年，全球暖化伴隨而來的熱浪、洪水、乾旱及強烈風暴等天災進入常態化，是大自然對地球反噬警訊，所以每個人都必須從自身做起，減低對地球破壞的程度，而用藝術作品融入自然永續議題就是藝術家用實際行動來關心環境與人文的寫照。\r\n    在埔里鎮寶大飯店展開主題「藝起共眠 共鳴自然」許慶福石雕．張家銘石雕．曾俊豪油畫三個展，就是聯合三位長期關懷生態自然、社會人文的當代藝術翹楚所促成的展覽，現場約200件多品，除了是三位老師智慧與人生閱歷累積，作品本身也代表每段歲月光陰的故事。\r\n    這次展出石雕作品來響應環境議題的許慶福老師，曾在國立台灣工藝研究發展中心技術組任職，是具有石雕、玉石研磨、魚骨創作與複合媒材等多方面專業的大師級藝術職人。許慶福老師喜愛與大自然對話，以舊物作素材，由素材本身的造型、質地、紋理牽引出新的生命力，他創作的理念精神可以簡單用幾句話來傳遞，就是「只要用心觀察、材料無貴賤、處處都有其剩餘價值」。而許慶福老師具有環保指標的魚骨創作，是採用大自然給予的最佳免費材料-溪石，搭配吳郭魚的骨頭，結合成的絕妙作品，當時他花了八年時間嘗試了19種本土魚種，才發現吳郭魚的腮、齶擁有奇特與美麗的元素很適合創作，與這次展覽精神的自然永續議題完全契合。\r\n    身兼藝術家與鎮寶大飯店董事長秘書的張家銘老師，則具有石雕、複合媒材與油畫等創作專長，他在這回展出也以擅長的石雕為主題，與其他兩名藝術家共同擦出首展的話題之火。而在常人看似平淡無奇的石頭材料，經由許慶福與張家銘兩位石雕家手中，顯現的確是凹與凸的極致藝術，他們利用光影變幻的線條呈現出雕刻的趣味與美感，還利用石材自然的紋理呈現自己的樣貌。在藝術家者眼中，一切都是美的，因為他們銳利的慧眼，能夠注視到一切眾生萬物的核心．抉發其性，透過外在形象觸及其內在真實，這就是真實即是美的具體表現手法', `organizer`='鎮寶大飯店', `address`='南投縣南投縣埔里鎮忠孝路299號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='鎮寶美術館', `latitude`=0, `longitude`=0, `ticket_price`='免費', `source_url`='無', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b41a9707f37a26088be584', '女性泌尿道健康與常見疾病X常見三大婦科癌常見三大婦科癌', '常常頻尿，或是尿急又尿不出來嗎？女性的尿道短，容易受到細菌感染，導致急性尿道炎，因此平日的預防保健很重要，讓北榮泌尿部醫師帶您認識常見的女性泌尿道疾病，以及如何保持泌尿道健康。\r\n\r\n女性十大癌症好發排行榜中，婦科癌就佔據其中三名，早期發現早期治療，讓北榮婦女醫學部主任教授帶您認識常見三大婦科癌症及如何及早防治\r\n\r\n時間：2025年3月15日(六)上午10:00-12:00\r\n地點：國家圖書館 B1多功能展演廳（臺北市中正區中山南路20號）\r\n講題及講師：\r\n【女性泌尿道健康與常見疾病】臺北榮民總醫院泌尿部 范玉華醫師\r\n【常見三大婦科癌症的簡介及防治】臺北榮民總醫院婦女醫學部 王鵬惠教授', '千禧之愛健康基金會', '臺北市中正區中山南路20號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '國家圖書館B1多功能展演廳', 25.03240487, 121.5198839, '免費，但須事先報名，額滿為止。', 'https://www.1000-love.org.tw/booking/content?id=46', '[]') ON DUPLICATE KEY UPDATE `activity_name`='女性泌尿道健康與常見疾病X常見三大婦科癌常見三大婦科癌', `description`='常常頻尿，或是尿急又尿不出來嗎？女性的尿道短，容易受到細菌感染，導致急性尿道炎，因此平日的預防保健很重要，讓北榮泌尿部醫師帶您認識常見的女性泌尿道疾病，以及如何保持泌尿道健康。\r\n\r\n女性十大癌症好發排行榜中，婦科癌就佔據其中三名，早期發現早期治療，讓北榮婦女醫學部主任教授帶您認識常見三大婦科癌症及如何及早防治\r\n\r\n時間：2025年3月15日(六)上午10:00-12:00\r\n地點：國家圖書館 B1多功能展演廳（臺北市中正區中山南路20號）\r\n講題及講師：\r\n【女性泌尿道健康與常見疾病】臺北榮民總醫院泌尿部 范玉華醫師\r\n【常見三大婦科癌症的簡介及防治】臺北榮民總醫院婦女醫學部 王鵬惠教授', `organizer`='千禧之愛健康基金會', `address`='臺北市中正區中山南路20號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='國家圖書館B1多功能展演廳', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='免費，但須事先報名，額滿為止。', `source_url`='https://www.1000-love.org.tw/booking/content?id=46', `image_url`='[]';
