INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f326b3240c403d9685', '2025【武營來跳舞】Party Dance跳進靈魂列車', '大眾參與，與眾不同的舞蹈初體驗\r\n\r\n跳舞是什麼？\r\n\r\n《武營來跳舞》能滿足您對舞蹈的好奇，一起探索跳舞的樂趣！\r\n\r\n為使愛跳舞、想嘗試跳舞的您有更多機會親近舞蹈，《武營來跳舞》在每個月的第一個星期三的晚上，與您相約在衛武營榕樹廣場西側平台。\r\n\r\n透過不同舞團與藝術家帶領，認識舞蹈的基礎語言，探索舞動的美好，找尋你與他身體之間的共振。\r\n\r\n邀請您報名參與，盡情享受舞蹈及活動空間，感受舞動的自由吧！\r\n\r\n3/5(三) 《Party Dance 跳進靈魂列車》\r\n\r\n源於街頭文化在1970年代的美國，受到嘻哈、霹靂舞等街舞風格的影響。在社區聚會和舞會，讓人們可以自由表現自我，這種舞蹈風格會隨著音樂的變化而演變，並融合了多種舞蹈元素，進而形成了獨特的派對舞蹈文化。\r\n\r\n我們將透過這堂課讓大眾體驗街舞的活力與魅力，無論是舞蹈新手或有經驗的舞者，都能找到樂趣。透過基本社交舞步的練習，提升自信與身體協調性。我們將創造一個輕鬆愉快的環境，讓大家在音樂中釋放壓力、建立友誼，並享受舞動的樂趣。\r\n ', '國家表演藝術中心衛武營國家藝術文化中心', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-05 00:00:00', '2025-03-05 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025【武營來跳舞】Party Dance跳進靈魂列車', `description`='大眾參與，與眾不同的舞蹈初體驗\r\n\r\n跳舞是什麼？\r\n\r\n《武營來跳舞》能滿足您對舞蹈的好奇，一起探索跳舞的樂趣！\r\n\r\n為使愛跳舞、想嘗試跳舞的您有更多機會親近舞蹈，《武營來跳舞》在每個月的第一個星期三的晚上，與您相約在衛武營榕樹廣場西側平台。\r\n\r\n透過不同舞團與藝術家帶領，認識舞蹈的基礎語言，探索舞動的美好，找尋你與他身體之間的共振。\r\n\r\n邀請您報名參與，盡情享受舞蹈及活動空間，感受舞動的自由吧！\r\n\r\n3/5(三) 《Party Dance 跳進靈魂列車》\r\n\r\n源於街頭文化在1970年代的美國，受到嘻哈、霹靂舞等街舞風格的影響。在社區聚會和舞會，讓人們可以自由表現自我，這種舞蹈風格會隨著音樂的變化而演變，並融合了多種舞蹈元素，進而形成了獨特的派對舞蹈文化。\r\n\r\n我們將透過這堂課讓大眾體驗街舞的活力與魅力，無論是舞蹈新手或有經驗的舞者，都能找到樂趣。透過基本社交舞步的練習，提升自信與身體協調性。我們將創造一個輕鬆愉快的環境，讓大家在音樂中釋放壓力、建立友誼，並享受舞動的樂趣。\r\n ', `organizer`='國家表演藝術中心衛武營國家藝術文化中心', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f326b3240c403d9689', '舞台劇《謝謝大家收看》', '舞台劇《謝謝大家收看》\r\n\r\n \r\n\r\n王偉忠這回要說的，不是他的故事，是他朋友「王忠偉」的事。\r\n\r\n忠偉事業有成，家庭和樂，和偉忠一樣是個電視人、到了高鐵半價的年紀，遇上長江後浪吃前浪、婚姻關係更年期，連往事都只剩回味...面對歲月風暴來襲，該怎麼迎接人生的秋冬？\r\n\r\n影視老兵王偉忠攜手合作多年的于子育、郭子乾，加上劇場頂尖編導設計群及演員，到底會變出什麼新招？疫情後最佳生活喜劇，笑料滿點，但千萬別忘了攜帶手帕加面紙！\r\n\r\n人生如戲，不論演什麼角色，都有機會獲得掌聲、也可能落漆被噓，經過努力，就值得一聲「謝謝大家收看」！\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n主辦單位｜金星文創、聯合數位文創、好位子劇團\r\n\r\n監製｜王偉忠\r\n\r\n主要演員｜于子育、郭子乾、王偉忠\r\n\r\n演員｜王意萱、周定緯、達姆拉．楚優吉、鄭慕岑（兩點）（依姓氏筆畫順序）\r\n\r\n操偶演員｜邱米溱\r\n\r\n編劇統籌｜王蓉\r\n\r\n導演｜陳威宇', '金星文創製作有限公司', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-08 00:00:00', '2025-03-09 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+800;--+1400;--+1600;--+2000;--+2200;--+2600;--+3200;--+3600', 'https://tickets.udnfunlife.com/application/utk01/utk0101_.aspx', '[]') ON DUPLICATE KEY UPDATE `activity_name`='舞台劇《謝謝大家收看》', `description`='舞台劇《謝謝大家收看》\r\n\r\n \r\n\r\n王偉忠這回要說的，不是他的故事，是他朋友「王忠偉」的事。\r\n\r\n忠偉事業有成，家庭和樂，和偉忠一樣是個電視人、到了高鐵半價的年紀，遇上長江後浪吃前浪、婚姻關係更年期，連往事都只剩回味...面對歲月風暴來襲，該怎麼迎接人生的秋冬？\r\n\r\n影視老兵王偉忠攜手合作多年的于子育、郭子乾，加上劇場頂尖編導設計群及演員，到底會變出什麼新招？疫情後最佳生活喜劇，笑料滿點，但千萬別忘了攜帶手帕加面紙！\r\n\r\n人生如戲，不論演什麼角色，都有機會獲得掌聲、也可能落漆被噓，經過努力，就值得一聲「謝謝大家收看」！\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n主辦單位｜金星文創、聯合數位文創、好位子劇團\r\n\r\n監製｜王偉忠\r\n\r\n主要演員｜于子育、郭子乾、王偉忠\r\n\r\n演員｜王意萱、周定緯、達姆拉．楚優吉、鄭慕岑（兩點）（依姓氏筆畫順序）\r\n\r\n操偶演員｜邱米溱\r\n\r\n編劇統籌｜王蓉\r\n\r\n導演｜陳威宇', `organizer`='金星文創製作有限公司', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+800;--+1400;--+1600;--+2000;--+2200;--+2600;--+3200;--+3600', `source_url`='https://tickets.udnfunlife.com/application/utk01/utk0101_.aspx', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f326b3240c403d968d', '苗栗分區資源中心「新思維 新的可能」主題書展', '為鼓勵民眾在新的一年探索全新視野，激發創意思維，苗栗分區資源中心辦理「新思維 新的可能」主題書展。本次書展精選50本書籍，內容涵蓋個人成長、創新思維、未來趨勢及技能學習，適合希望在新的一年自我提升的讀者。\r\n本次展示的書籍包括：《努力，不如用對力：認真≠績效，精準做重點才是贏家！》、《內心對話的力量：遠離自我批判，提升心靈自癒力的11種練習》、《創意，練習就有》以及《AI新世界》等，從心靈啟發到實用技能，鼓勵讀者探索未知的領域和可能性。', '公共圖書館苗栗分區資源中心', '苗栗縣苗栗市自治路50號', '2025-02-12 00:00:00', '2025-03-31 00:00:00', '苗栗縣立圖書館', 24.565963, 120.8203986, '無資料', 'https://lib.miaoli.gov.tw/wSite/ct?xItem=19747&ctNode=227&mp=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗栗分區資源中心「新思維 新的可能」主題書展', `description`='為鼓勵民眾在新的一年探索全新視野，激發創意思維，苗栗分區資源中心辦理「新思維 新的可能」主題書展。本次書展精選50本書籍，內容涵蓋個人成長、創新思維、未來趨勢及技能學習，適合希望在新的一年自我提升的讀者。\r\n本次展示的書籍包括：《努力，不如用對力：認真≠績效，精準做重點才是贏家！》、《內心對話的力量：遠離自我批判，提升心靈自癒力的11種練習》、《創意，練習就有》以及《AI新世界》等，從心靈啟發到實用技能，鼓勵讀者探索未知的領域和可能性。', `organizer`='公共圖書館苗栗分區資源中心', `address`='苗栗縣苗栗市自治路50號', `start_date`='2025-02-12 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='苗栗縣立圖書館', `latitude`=24.565963, `longitude`=120.8203986, `ticket_price`='無資料', `source_url`='https://lib.miaoli.gov.tw/wSite/ct?xItem=19747&ctNode=227&mp=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f426b3240c403d968e', '「南美藝揚」-臺南市美術學會會員聯展   ', '臺南市美術學會致力於凝聚會員藝術創作能量、展現多元藝術風貌，推廣藝術生活，此次展出涵蓋種類有油畫、水彩、粉彩、素描、複合媒材；水墨、書法、膠彩；陶藝、雕塑等，歡迎各界藝術愛好朋友蒞臨參觀。\r\n', '高雄市政府文化局', '高雄市岡山區009鄰岡山南路42號', '2025-03-05 00:00:00', '2025-03-23 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「南美藝揚」-臺南市美術學會會員聯展   ', `description`='臺南市美術學會致力於凝聚會員藝術創作能量、展現多元藝術風貌，推廣藝術生活，此次展出涵蓋種類有油畫、水彩、粉彩、素描、複合媒材；水墨、書法、膠彩；陶藝、雕塑等，歡迎各界藝術愛好朋友蒞臨參觀。\r\n', `organizer`='高雄市政府文化局', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f426b3240c403d968f', '2025南區藝術家聯展(慶祝4/3國際藝術家節)', '2025南區藝術家聯展(慶祝4/3國際藝術家節)是由國際知名的藝術家、慈善及靈性導師SMCH在2018年1月16日發起，並於同年1月25日在SMTV電視正式確立每年4月3日為「國際藝術家節」 。本活動的宗旨，是向傾心高雅藝術創作、帶給世界真善美的藝術家們致敬！讚頌！ ', '高雄市政府文化局', '高雄市岡山區009鄰岡山南路42號', '2025-03-26 00:00:00', '2025-04-13 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025南區藝術家聯展(慶祝4/3國際藝術家節)', `description`='2025南區藝術家聯展(慶祝4/3國際藝術家節)是由國際知名的藝術家、慈善及靈性導師SMCH在2018年1月16日發起，並於同年1月25日在SMTV電視正式確立每年4月3日為「國際藝術家節」 。本活動的宗旨，是向傾心高雅藝術創作、帶給世界真善美的藝術家們致敬！讚頌！ ', `organizer`='高雄市政府文化局', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-03-26 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f426b3240c403d9691', '員林市警察故事館展覽', '為了帶動地方觀光發展，由員林鎮公所編列經費整修員林郡役場舊警察宿舍，與縣警局將舊警察宿舍規劃成警察故事館，陳列從日據時期至80年代的珍貴文物，包括二二八事件時源泉派出所提報的「奸徒名冊」和大村村長自清報告，還有40年代溪湖派出所員警到酒家查訪的珍貴照片，及早期警察使用的手搖式警報器、防空燈、防空鑼鼓、大型蒐證錄音機等。\r\n\r\n警察故事館於民國102年12月19日落成啟用。建館目的旨在藉陳展各時期警察之文物史料，以弘揚警察犧牲、奉獻、服務精神，藉由珍貴警察文化資產的展示，共同延續、傳承警察優良文化，彰顯警察特色，使民眾藉此瞭解警察文化內涵，提高對警察之認同感，發揮對外行銷之積極功能。\r\n\r\n警察故事館做為一個警察歷史文物保存和社會教育媒介，以蘊含不同層面的軟實力，感念警察同仁犧牲的奉獻精神，彰顯警察為保衛社會安全及增進人民福利所付出的無私情操，其重要性不言可喻。\r\n\r\n本館之存在價值，不僅關係到警察向心力的凝聚及服務精神提升，更扮演著承先啟後的角色，同時兼具「回顧」與「前瞻」的雙重使命，希望在社會各界與同仁的支持下繼續光耀警察使命。', '彰化縣警察局', '彰化縣員林市', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '員林市（彰化縣）=', 23.95650448, 120.593073, '無資料', 'http://viablog.okmall.tw/blogview.php?blogid=1667', '[]') ON DUPLICATE KEY UPDATE `activity_name`='員林市警察故事館展覽', `description`='為了帶動地方觀光發展，由員林鎮公所編列經費整修員林郡役場舊警察宿舍，與縣警局將舊警察宿舍規劃成警察故事館，陳列從日據時期至80年代的珍貴文物，包括二二八事件時源泉派出所提報的「奸徒名冊」和大村村長自清報告，還有40年代溪湖派出所員警到酒家查訪的珍貴照片，及早期警察使用的手搖式警報器、防空燈、防空鑼鼓、大型蒐證錄音機等。\r\n\r\n警察故事館於民國102年12月19日落成啟用。建館目的旨在藉陳展各時期警察之文物史料，以弘揚警察犧牲、奉獻、服務精神，藉由珍貴警察文化資產的展示，共同延續、傳承警察優良文化，彰顯警察特色，使民眾藉此瞭解警察文化內涵，提高對警察之認同感，發揮對外行銷之積極功能。\r\n\r\n警察故事館做為一個警察歷史文物保存和社會教育媒介，以蘊含不同層面的軟實力，感念警察同仁犧牲的奉獻精神，彰顯警察為保衛社會安全及增進人民福利所付出的無私情操，其重要性不言可喻。\r\n\r\n本館之存在價值，不僅關係到警察向心力的凝聚及服務精神提升，更扮演著承先啟後的角色，同時兼具「回顧」與「前瞻」的雙重使命，希望在社會各界與同仁的支持下繼續光耀警察使命。', `organizer`='彰化縣警察局', `address`='彰化縣員林市', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='員林市（彰化縣）=', `latitude`=23.95650448, `longitude`=120.593073, `ticket_price`='無資料', `source_url`='http://viablog.okmall.tw/blogview.php?blogid=1667', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f426b3240c403d9692', '書香情人&談情說愛主題書展', '活動洽詢：037-357801苗栗市立圖書館', '苗栗縣苗栗市公所', '苗栗縣苗栗市高苗里大同路82號', '2025-02-11 00:00:00', '2025-02-28 00:00:00', '苗栗縣苗栗市立圖書館', 24.56382141, 120.8112299, '無資料', 'https://www.facebook.com/ml8287', '[]') ON DUPLICATE KEY UPDATE `activity_name`='書香情人&談情說愛主題書展', `description`='活動洽詢：037-357801苗栗市立圖書館', `organizer`='苗栗縣苗栗市公所', `address`='苗栗縣苗栗市高苗里大同路82號', `start_date`='2025-02-11 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='苗栗縣苗栗市立圖書館', `latitude`=24.56382141, `longitude`=120.8112299, `ticket_price`='無資料', `source_url`='https://www.facebook.com/ml8287', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f426b3240c403d9693', '無資料', '透過故事說演方式，探討人類長久以來對性別角色的看法。\r\n透過故事小劇場方式呈現故事內容，教會孩子同理，進一步重新定義家事的分工。\r\n1.台語唸謠親子律動\r\n2.手作DIY\r\n20組學齡前至國小親子家庭\r\n\r\n報名網址 https://www.beclass.com/rid=294fe6767b01ce258e28', '苗栗縣苑裡鎮公所', '苗栗縣苑裡鎮信義路1-1號', '苗栗縣苑裡鎮立圖書館', 24.4110232, 120.6882195, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='透過故事說演方式，探討人類長久以來對性別角色的看法。\r\n透過故事小劇場方式呈現故事內容，教會孩子同理，進一步重新定義家事的分工。\r\n1.台語唸謠親子律動\r\n2.手作DIY\r\n20組學齡前至國小親子家庭\r\n\r\n報名網址 https://www.beclass.com/rid=294fe6767b01ce258e28', `organizer`='苗栗縣苑裡鎮公所', `address`='苗栗縣苑裡鎮信義路1-1號', `location`='苗栗縣苑裡鎮立圖書館', `latitude`=24.4110232, `longitude`=120.6882195, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f426b3240c403d9695', '普通隊長首張專輯發片巡迴 Round2：贖身大作戰－高雄', '普通隊長首張專輯發片巡迴 Round2：贖身大作戰\r\nCaptain Ordinary 1st Album Release Tour Round 2: The Redemption Mission\r\n第一次巡迴是為了熱情\r\n第二次巡迴是為了還債\r\n3/8高雄場一樣在LIVE WAREHOUSE小庫。\r\n今年我們依然沒有上大港，說不難過一定是騙人的，超難過。但轉念一想，上大港的話也很可能一樣在LIVE WAREHOUSE演出，我們自己辦還能想演多久就演多久！\r\n大庫那天也還有檔期，這次不會再讓你買不到票了，票賣得夠快我們就大庫見！\r\n3/9在臺中場在迴響。\r\n這場是辦給那些整天敲碗「怎麼沒有臺中場」的朋友們，怎麼會沒有？一定有，已經有。我們到時見！\r\n3/14臺北場在The Wall。\r\n上次巡迴我們嘗試逼出自己的極限，最強的特邀陣容、最堅強的幕後團隊，對500人的場地發起挑戰！結果失敗了，賠了十幾萬。\r\n這次我們捲土重來，找了Pop Punk怪獸粗大Band！3/14情人節就讓Punk Rock陪你一起度過！', '普通音樂', '高雄市鹽埕區17鄰真愛路1號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '預售單人票+800;預售雙人票+1400;有錢人現場票+1000', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='普通隊長首張專輯發片巡迴 Round2：贖身大作戰－高雄', `description`='普通隊長首張專輯發片巡迴 Round2：贖身大作戰\r\nCaptain Ordinary 1st Album Release Tour Round 2: The Redemption Mission\r\n第一次巡迴是為了熱情\r\n第二次巡迴是為了還債\r\n3/8高雄場一樣在LIVE WAREHOUSE小庫。\r\n今年我們依然沒有上大港，說不難過一定是騙人的，超難過。但轉念一想，上大港的話也很可能一樣在LIVE WAREHOUSE演出，我們自己辦還能想演多久就演多久！\r\n大庫那天也還有檔期，這次不會再讓你買不到票了，票賣得夠快我們就大庫見！\r\n3/9在臺中場在迴響。\r\n這場是辦給那些整天敲碗「怎麼沒有臺中場」的朋友們，怎麼會沒有？一定有，已經有。我們到時見！\r\n3/14臺北場在The Wall。\r\n上次巡迴我們嘗試逼出自己的極限，最強的特邀陣容、最堅強的幕後團隊，對500人的場地發起挑戰！結果失敗了，賠了十幾萬。\r\n這次我們捲土重來，找了Pop Punk怪獸粗大Band！3/14情人節就讓Punk Rock陪你一起度過！', `organizer`='普通音樂', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='預售單人票+800;預售雙人票+1400;有錢人現場票+1000', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f426b3240c403d9696', 'GFRIEND 10th Anniversary＜Season of Memories＞in Kaohsiung', 'GFRIEND被BUDDY們的熱情與期待震撼了！💌\r\n希望讓更多BUDDY一起分享這段難忘的回憶，\r\nGFRIEND 10th Anniversary Season of Memories in Kaohsiung高雄場正式宣佈加場！ 🎊\r\n最後機會千萬不要錯過喔~\r\n\r\n【GFRIEND 10th Anniversary Season of Memories in Kaohsiung】\r\n\r\n⬣ 演出日期：2025/03/22 (六) 6PM，2025/03/23 (日) 4PM [加場]（實際演出時間以現場公告為準）\r\n⬣ 演出地點 : 高雄流行音樂中心海音館 KAOHSIUNG MUSIC CENTER\r\n⬣ 售票時間：2025/02/08(六)，2025/02/15(六) [加場] 11AM 拓元售票系統全面開賣\r\n\r\n#여자친구 #GFRIEND\r\n#Season_of_Memories\r\n#Season_of_Memories_in_Kaohsiung\r\n#APPLEWOOD #APPLEWOODTW', 'APPLEWOOD TAIWAN', '高雄市鹽埕區17鄰真愛路1號', '2025-03-22 00:00:00', '2025-03-23 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '2F 身障席座位區+2900;Zone B 座位區+3800;Zone A 座位區+5800;VIP 2F座位區+6500;VIP A/B搖滾站區+6500', 'https://tixcraft.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='GFRIEND 10th Anniversary＜Season of Memories＞in Kaohsiung', `description`='GFRIEND被BUDDY們的熱情與期待震撼了！💌\r\n希望讓更多BUDDY一起分享這段難忘的回憶，\r\nGFRIEND 10th Anniversary Season of Memories in Kaohsiung高雄場正式宣佈加場！ 🎊\r\n最後機會千萬不要錯過喔~\r\n\r\n【GFRIEND 10th Anniversary Season of Memories in Kaohsiung】\r\n\r\n⬣ 演出日期：2025/03/22 (六) 6PM，2025/03/23 (日) 4PM [加場]（實際演出時間以現場公告為準）\r\n⬣ 演出地點 : 高雄流行音樂中心海音館 KAOHSIUNG MUSIC CENTER\r\n⬣ 售票時間：2025/02/08(六)，2025/02/15(六) [加場] 11AM 拓元售票系統全面開賣\r\n\r\n#여자친구 #GFRIEND\r\n#Season_of_Memories\r\n#Season_of_Memories_in_Kaohsiung\r\n#APPLEWOOD #APPLEWOODTW', `organizer`='APPLEWOOD TAIWAN', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='2F 身障席座位區+2900;Zone B 座位區+3800;Zone A 座位區+5800;VIP 2F座位區+6500;VIP A/B搖滾站區+6500', `source_url`='https://tixcraft.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f426b3240c403d9697', '庸俗救星《Little Battle》專輯同名巡迴演唱會 高雄場', '人生是一場接一場的小小戰役，\r\n偶爾輸得徹底，偶爾贏得驚喜，\r\n但無論如何，我們都會繼續前進。\r\n2025年讓庸俗救星陪你一起！\r\n面對生活中那些不完美、不順遂、不服輸的瞬間\r\n帶著新專輯《Little Battle》與你並肩作戰', '高雄流行音樂中心', '高雄市鹽埕區17鄰真愛路1號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '身障票+500;救星督察預售票+900;一般預售票+1000;現場票+1200', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='庸俗救星《Little Battle》專輯同名巡迴演唱會 高雄場', `description`='人生是一場接一場的小小戰役，\r\n偶爾輸得徹底，偶爾贏得驚喜，\r\n但無論如何，我們都會繼續前進。\r\n2025年讓庸俗救星陪你一起！\r\n面對生活中那些不完美、不順遂、不服輸的瞬間\r\n帶著新專輯《Little Battle》與你並肩作戰', `organizer`='高雄流行音樂中心', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='身障票+500;救星督察預售票+900;一般預售票+1000;現場票+1200', `source_url`='https://www.indievox.com/', `image_url`='[]';
