INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f526b3240c403d969e', '＜世界母語日＞主題書展', '由聯合國教科文組織（UNESCO）於1999年提出，並在2000年決議每年慶祝的節日。世界母語日的由來是為了向全世界宣傳保護語言的重要、促進母語傳播、教育等活動，避免世界各地的語言逐漸消失。\r\n目前圖書館內設有＜世界母語日－主題書展＞\r\n客庄的母語～客語\r\n國際的語言～英語\r\n新住民專區～東南亞文\r\n歡迎您，走進圖書館，一起愛上閱讀', '苗栗縣銅鑼鄉公所', '苗栗縣銅鑼鄉', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '銅鑼鄉（苗栗縣）=', 24.45591832, 120.7992043, '無資料', 'https://www.facebook.com/tongluolib#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='＜世界母語日＞主題書展', `description`='由聯合國教科文組織（UNESCO）於1999年提出，並在2000年決議每年慶祝的節日。世界母語日的由來是為了向全世界宣傳保護語言的重要、促進母語傳播、教育等活動，避免世界各地的語言逐漸消失。\r\n目前圖書館內設有＜世界母語日－主題書展＞\r\n客庄的母語～客語\r\n國際的語言～英語\r\n新住民專區～東南亞文\r\n歡迎您，走進圖書館，一起愛上閱讀', `organizer`='苗栗縣銅鑼鄉公所', `address`='苗栗縣銅鑼鄉', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='銅鑼鄉（苗栗縣）=', `latitude`=24.45591832, `longitude`=120.7992043, `ticket_price`='無資料', `source_url`='https://www.facebook.com/tongluolib#', `image_url`='[]';
