INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f526b3240c403d96a2', '2025上半年度藺編初級工藝師認證課程（4梯次）', '初級課程為藺編基礎入門課，課程內容包含草料處理與壓一、壓二平面編織與結尾收編技法教學，適合從未接觸過藺編的新手，也歡迎舊生一起來複習基礎技法！\r\n報名連結：\r\n第一梯次 https://reurl.cc/geAvML\r\n第二梯次 https://reurl.cc/Nbmmy9\r\n第三梯次 https://reurl.cc/d1jjLV\r\n第四梯次 https://reurl.cc/A6eedQ', '台灣藺草學會', '苗栗縣苑裡鎮', '2025-03-14 00:00:00', '2025-06-13 00:00:00', '苑裡鎮（苗栗縣）=', 24.4110232, 120.6882195, '課程費用+6400', 'https://www.facebook.com/trianglarlin/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025上半年度藺編初級工藝師認證課程（4梯次）', `description`='初級課程為藺編基礎入門課，課程內容包含草料處理與壓一、壓二平面編織與結尾收編技法教學，適合從未接觸過藺編的新手，也歡迎舊生一起來複習基礎技法！\r\n報名連結：\r\n第一梯次 https://reurl.cc/geAvML\r\n第二梯次 https://reurl.cc/Nbmmy9\r\n第三梯次 https://reurl.cc/d1jjLV\r\n第四梯次 https://reurl.cc/A6eedQ', `organizer`='台灣藺草學會', `address`='苗栗縣苑裡鎮', `start_date`='2025-03-14 00:00:00', `end_date`='2025-06-13 00:00:00', `location`='苑裡鎮（苗栗縣）=', `latitude`=24.4110232, `longitude`=120.6882195, `ticket_price`='課程費用+6400', `source_url`='https://www.facebook.com/trianglarlin/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f526b3240c403d96a3', '大家用台語來唸歌謠', '邀請紙芝居劇團紅豆冰哥哥，以母語教大家用台語來唸歌謠、唱遊與聆賞，透過劇團說演方式，以詼諧有趣的豐富歌謠內容吸引大小朋友共鳴，達到本土語言學習與傳承之目的。', '高雄市立圖書館總館', '高雄市小港區博學路365號', '2025-03-07 00:00:00', '2025-03-21 00:00:00', '高雄市立圖書館小港分館', 22.5605891, 120.3705758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大家用台語來唸歌謠', `description`='邀請紙芝居劇團紅豆冰哥哥，以母語教大家用台語來唸歌謠、唱遊與聆賞，透過劇團說演方式，以詼諧有趣的豐富歌謠內容吸引大小朋友共鳴，達到本土語言學習與傳承之目的。', `organizer`='高雄市立圖書館總館', `address`='高雄市小港區博學路365號', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='高雄市立圖書館小港分館', `latitude`=22.5605891, `longitude`=120.3705758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f526b3240c403d96a4', 'FUN心聽故事(旗山分館114年3月)', '由故事媽媽取材繪本故事來帶領兒童，從不同故事內容去瞭解各自所含意境及學習其繪本正面所帶來影響，透過簡單的律動營造歡樂的故事情境。', '高雄市立圖書館總館', '高雄市旗山區大德里6鄰中學路42號', '2025-03-02 00:00:00', '2025-03-23 00:00:00', '高雄市立圖書館旗山分館', 25.0421407, 121.5198716, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽故事(旗山分館114年3月)', `description`='由故事媽媽取材繪本故事來帶領兒童，從不同故事內容去瞭解各自所含意境及學習其繪本正面所帶來影響，透過簡單的律動營造歡樂的故事情境。', `organizer`='高雄市立圖書館總館', `address`='高雄市旗山區大德里6鄰中學路42號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='高雄市立圖書館旗山分館', `latitude`=25.0421407, `longitude`=121.5198716, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b4f5f526b3240c403d96a5', '東南亞故事時間-「亞熱帶故事家」-泰國說故事', '大家知道泰國的文化及美食嗎？\r\n這次的說故事活動由泰國新二代的妮妮老師帶來泰北作家的《爸爸的破酥包》。故事中，小女孩與父親在日常生活中的互動，帶領大家了解泰國的特色美食，並透過製作破酥包與祭祖的習俗，呈現泰國人獨特的生活方式與文化。故事活動結束後，妮妮老師也將帶領大家進行有趣的遊戲，也與孩子們分享泰國美食特色，一起學會尊重與包容不同的文化。活動採自由入場，不需報名，期待與您在圖書館一起體驗這場故事的盛宴！\r\n', '高雄市立圖書館總館', '高雄市前鎮區21鄰新光路61號', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '高雄市立圖書館總館', 22.6115529, 120.3024491, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='東南亞故事時間-「亞熱帶故事家」-泰國說故事', `description`='大家知道泰國的文化及美食嗎？\r\n這次的說故事活動由泰國新二代的妮妮老師帶來泰北作家的《爸爸的破酥包》。故事中，小女孩與父親在日常生活中的互動，帶領大家了解泰國的特色美食，並透過製作破酥包與祭祖的習俗，呈現泰國人獨特的生活方式與文化。故事活動結束後，妮妮老師也將帶領大家進行有趣的遊戲，也與孩子們分享泰國美食特色，一起學會尊重與包容不同的文化。活動採自由入場，不需報名，期待與您在圖書館一起體驗這場故事的盛宴！\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市前鎮區21鄰新光路61號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='高雄市立圖書館總館', `latitude`=22.6115529, `longitude`=120.3024491, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b584eb8f15d8562cfcd6e2', '《嘻客派對》絲竹空爵士樂團', '《嘻客派對》絲竹空爵士樂團\r\nHip Hakka Party\r\n\r\n演出時間：2025/03/13 (四) 19:30\r\n演出地點：陽明交大演藝廳 / 學生活動中心二樓 (新竹市大學路1001號)\r\n入場方式：免費、報名入場  (2/13(四) 12:00開放網路報名)\r\n報名傳送門：https://reurl.cc/96GGzn\r\n\r\n▌演出者\r\n\r\n藝術總監、作曲編曲、鋼琴 / 彭郁雯\r\n作曲、二胡、打擊 / 吳政君\r\n作曲、電貝斯 / 藤井俊充\r\n笛子、巴烏 / 黃治評\r\n中阮、柳琴 / 陳崇青\r\n爵士鼓 / 林冠良\r\n特別邀演：客語饒舌歌手 / 王鍾惟\r\n\r\n絲竹空爵士樂團除了持續其對台灣音樂元素的融合再造，更將觸角延伸至嘻哈音樂，探索更多語言、節奏和音色上的可能性！嘻哈音樂從1970年代起源於紐約非裔美人的封街派對，因其音樂上的多元性，以及歌詞裡的豐富議題，發展至今成為席捲全球的樂種。\r\n\r\n絲竹空這次邀請新生代客語饒舌歌手VUIZE王鍾惟合作，將其充滿能量的客語饒舌，以及時尚的嘻哈律動，與絲竹空不設限的音樂想像力結合，和觀眾一起台上台下全面開趴！\r\n\r\n▌演出曲目\r\n\r\n山居：彭郁雯 作曲\r\n恩主公很忙 (大團圓)：客家八音曲調、彭郁雯 改編\r\n山歌仔：客家山歌曲調、彭郁雯 改編\r\n老羅賣鵝：彭郁雯 作曲\r\nSing Along：VUIZE 王鍾惟 詞曲\r\n起：VUIZE 王鍾惟 詞曲\r\n膽膽大：彭郁雯 作曲\r\n拈：VUIZE 王鍾惟 詞曲\r\n曼波七號：歌仔戲曲調、藤井俊充 改編', '國立陽明交通大學藝文中心', '新竹市大學路1001號', '2025-03-13 00:00:00', '2025-03-13 00:00:00', '陽明交大演藝廳', 0, 0, '無資料', 'https://reurl.cc/96GGzn', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《嘻客派對》絲竹空爵士樂團', `description`='《嘻客派對》絲竹空爵士樂團\r\nHip Hakka Party\r\n\r\n演出時間：2025/03/13 (四) 19:30\r\n演出地點：陽明交大演藝廳 / 學生活動中心二樓 (新竹市大學路1001號)\r\n入場方式：免費、報名入場  (2/13(四) 12:00開放網路報名)\r\n報名傳送門：https://reurl.cc/96GGzn\r\n\r\n▌演出者\r\n\r\n藝術總監、作曲編曲、鋼琴 / 彭郁雯\r\n作曲、二胡、打擊 / 吳政君\r\n作曲、電貝斯 / 藤井俊充\r\n笛子、巴烏 / 黃治評\r\n中阮、柳琴 / 陳崇青\r\n爵士鼓 / 林冠良\r\n特別邀演：客語饒舌歌手 / 王鍾惟\r\n\r\n絲竹空爵士樂團除了持續其對台灣音樂元素的融合再造，更將觸角延伸至嘻哈音樂，探索更多語言、節奏和音色上的可能性！嘻哈音樂從1970年代起源於紐約非裔美人的封街派對，因其音樂上的多元性，以及歌詞裡的豐富議題，發展至今成為席捲全球的樂種。\r\n\r\n絲竹空這次邀請新生代客語饒舌歌手VUIZE王鍾惟合作，將其充滿能量的客語饒舌，以及時尚的嘻哈律動，與絲竹空不設限的音樂想像力結合，和觀眾一起台上台下全面開趴！\r\n\r\n▌演出曲目\r\n\r\n山居：彭郁雯 作曲\r\n恩主公很忙 (大團圓)：客家八音曲調、彭郁雯 改編\r\n山歌仔：客家山歌曲調、彭郁雯 改編\r\n老羅賣鵝：彭郁雯 作曲\r\nSing Along：VUIZE 王鍾惟 詞曲\r\n起：VUIZE 王鍾惟 詞曲\r\n膽膽大：彭郁雯 作曲\r\n拈：VUIZE 王鍾惟 詞曲\r\n曼波七號：歌仔戲曲調、藤井俊充 改編', `organizer`='國立陽明交通大學藝文中心', `address`='新竹市大學路1001號', `start_date`='2025-03-13 00:00:00', `end_date`='2025-03-13 00:00:00', `location`='陽明交大演藝廳', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://reurl.cc/96GGzn', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b587858f15d8562cfcd6e3', '《動物音律》宇宙流', '《動物音律》宇宙流\r\nThe Sound of Animals\r\n\r\n演出時間：2025/03/18 (二) 19:30\r\n演出地點：陽明交大演藝廳 / 學生活動中心二樓 (新竹市大學路1001號)\r\n入場方式：免費、報名入場  (2/18 (二) 12:00開放網路報名)\r\n報名傳送門：https://reurl.cc/A60QgY\r\n\r\n▌演出者\r\n\r\nFluido Cósmico 宇宙流\r\n手碟，口簧琴，古琴樂手 / 陶然 Fao\r\n手鼓樂手 / 林亞蒨 Ya-Chien Lin\r\n\r\n這個充滿原創性的樂團：Fluido Cósmico (宇宙流)，正在準備他們的第四張專輯《Animals》(中譯：動物)，預計於 2025 年發行。 此音樂會將重點放在地球上各種多樣化的動物形式，用音樂來展現動物的風貌與肢體流動方式。 \r\n\r\nFluido Cósmico將原創作品與多重節奏技術融為一體，並結合了傳統古典和現代的非傳統新潮樂器：如中國最老樂器—古琴，在世界各地文化中流傳的古老樂器：各式的口簧琴與手鼓 (Mouth harp / Frame Drums)，以及近年來新生富含旋律性的金屬打擊樂器：手碟 (handpan)，並融入充滿實驗性的電子音樂。\r\n\r\n在這場演出中，觀眾將藉由聽覺的享受進入一場個人內在的探索旅程，時而迷幻，時而充滿舞動節奏，這將是一場全新的音樂饗宴。他們將展現幾首全新作品，也包括先前幾張專輯裡的最愛：《EARTH》、《Cosmovisión》和《Traveling with a handpan》。千萬別錯過這個在充滿活力氛圍中體驗尖端音樂和以獨特方式詮釋音樂的特別機會！\r\n', '國立陽明交通大學藝文中心', '新竹市新竹市大學路1001號', '2025-03-18 00:00:00', '2025-03-18 00:00:00', '陽明交大演藝廳 ', 0, 0, '無資料', 'https://reurl.cc/A60QgY', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《動物音律》宇宙流', `description`='《動物音律》宇宙流\r\nThe Sound of Animals\r\n\r\n演出時間：2025/03/18 (二) 19:30\r\n演出地點：陽明交大演藝廳 / 學生活動中心二樓 (新竹市大學路1001號)\r\n入場方式：免費、報名入場  (2/18 (二) 12:00開放網路報名)\r\n報名傳送門：https://reurl.cc/A60QgY\r\n\r\n▌演出者\r\n\r\nFluido Cósmico 宇宙流\r\n手碟，口簧琴，古琴樂手 / 陶然 Fao\r\n手鼓樂手 / 林亞蒨 Ya-Chien Lin\r\n\r\n這個充滿原創性的樂團：Fluido Cósmico (宇宙流)，正在準備他們的第四張專輯《Animals》(中譯：動物)，預計於 2025 年發行。 此音樂會將重點放在地球上各種多樣化的動物形式，用音樂來展現動物的風貌與肢體流動方式。 \r\n\r\nFluido Cósmico將原創作品與多重節奏技術融為一體，並結合了傳統古典和現代的非傳統新潮樂器：如中國最老樂器—古琴，在世界各地文化中流傳的古老樂器：各式的口簧琴與手鼓 (Mouth harp / Frame Drums)，以及近年來新生富含旋律性的金屬打擊樂器：手碟 (handpan)，並融入充滿實驗性的電子音樂。\r\n\r\n在這場演出中，觀眾將藉由聽覺的享受進入一場個人內在的探索旅程，時而迷幻，時而充滿舞動節奏，這將是一場全新的音樂饗宴。他們將展現幾首全新作品，也包括先前幾張專輯裡的最愛：《EARTH》、《Cosmovisión》和《Traveling with a handpan》。千萬別錯過這個在充滿活力氛圍中體驗尖端音樂和以獨特方式詮釋音樂的特別機會！\r\n', `organizer`='國立陽明交通大學藝文中心', `address`='新竹市新竹市大學路1001號', `start_date`='2025-03-18 00:00:00', `end_date`='2025-03-18 00:00:00', `location`='陽明交大演藝廳 ', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://reurl.cc/A60QgY', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b588a08f15d8562cfcd6e4', '艸雨田舞蹈劇場《新竹人跳舞吧 – 藝術駐校工作坊》', '艸雨田舞蹈劇場《新竹人跳舞吧 – 藝術駐校工作坊》\r\nLEI Dance Theater workshop\r\n艸雨田身為新竹唯一的職業現代舞團，致力於在資源相對稀缺的大新竹地區推廣舞蹈藝術，從生活切入，引領民眾探索台灣表演藝術的多樣性與公共性，開拓全新的視野與想像。\r\n\r\n舞團深耕在地，期望吸引對舞蹈有興趣的素人，透過精心設計的肢體與表演開發課程，邀請他們走進劇場，感受舞蹈的魅力。透過工作坊引導肢體突破，讓藝術變得觸手可及、生動有趣，並以輕鬆卻富挑戰性的方式完成創意發想與練習。\r\n\r\n2025年，艸雨田將攜手駐團編舞家鄭伊雯及國際客席編舞家 Ole Khamchanla，於陽明交通大學舉辦「舞蹈劇場表演開發」工作坊，歡迎對舞蹈零基礎的大學生加入，共同探索舞蹈劇場的多元可能性！\r\n\r\n▌Part I 指導老師：鄭伊雯\r\n\r\n第一堂【解放大腦、解放身體】\r\n第二堂【你也可以表演，找到自己的跳舞風格!】\r\n\r\n▌ Part II 指導老師：Ole Khamchanla 奧萊・康詹拉\r\n第三堂【當現代舞遇上嘻哈街舞以及東南亞傳統舞蹈】\r\n▌ 時間 2025/04/29、05/13 、05/20 (二) 19:00 -21:00\r\n\r\n▌ 地點 陽明交大演藝廳 (光復校區/ 學生活動中心二樓)\r\n\r\n▌ 參加辦法 \r\n參加方式 | 名額有限，2025/3/01起開放報名至額滿為止\r\n報名資格 | 限陽明交大教職員工生 / Only for NYCU \r\n報名費用 | 500元/堂 (保證金，全程參與者方可退費)\r\n報名網址 | https://reurl.cc/M6ya0L (每堂課為獨立單元，可單堂報名)', '國立陽明交通大學藝文中心', '新竹市大學路1001號', '2025-04-29 00:00:00', '2025-04-29 00:00:00', '陽明交大演藝廳', 0, 0, '無資料', 'https://reurl.cc/M6ya0L', '[]') ON DUPLICATE KEY UPDATE `activity_name`='艸雨田舞蹈劇場《新竹人跳舞吧 – 藝術駐校工作坊》', `description`='艸雨田舞蹈劇場《新竹人跳舞吧 – 藝術駐校工作坊》\r\nLEI Dance Theater workshop\r\n艸雨田身為新竹唯一的職業現代舞團，致力於在資源相對稀缺的大新竹地區推廣舞蹈藝術，從生活切入，引領民眾探索台灣表演藝術的多樣性與公共性，開拓全新的視野與想像。\r\n\r\n舞團深耕在地，期望吸引對舞蹈有興趣的素人，透過精心設計的肢體與表演開發課程，邀請他們走進劇場，感受舞蹈的魅力。透過工作坊引導肢體突破，讓藝術變得觸手可及、生動有趣，並以輕鬆卻富挑戰性的方式完成創意發想與練習。\r\n\r\n2025年，艸雨田將攜手駐團編舞家鄭伊雯及國際客席編舞家 Ole Khamchanla，於陽明交通大學舉辦「舞蹈劇場表演開發」工作坊，歡迎對舞蹈零基礎的大學生加入，共同探索舞蹈劇場的多元可能性！\r\n\r\n▌Part I 指導老師：鄭伊雯\r\n\r\n第一堂【解放大腦、解放身體】\r\n第二堂【你也可以表演，找到自己的跳舞風格!】\r\n\r\n▌ Part II 指導老師：Ole Khamchanla 奧萊・康詹拉\r\n第三堂【當現代舞遇上嘻哈街舞以及東南亞傳統舞蹈】\r\n▌ 時間 2025/04/29、05/13 、05/20 (二) 19:00 -21:00\r\n\r\n▌ 地點 陽明交大演藝廳 (光復校區/ 學生活動中心二樓)\r\n\r\n▌ 參加辦法 \r\n參加方式 | 名額有限，2025/3/01起開放報名至額滿為止\r\n報名資格 | 限陽明交大教職員工生 / Only for NYCU \r\n報名費用 | 500元/堂 (保證金，全程參與者方可退費)\r\n報名網址 | https://reurl.cc/M6ya0L (每堂課為獨立單元，可單堂報名)', `organizer`='國立陽明交通大學藝文中心', `address`='新竹市大學路1001號', `start_date`='2025-04-29 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='陽明交大演藝廳', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://reurl.cc/M6ya0L', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b589638f15d8562cfcd6e5', '「之間」音樂會', '「之間」音樂會\r\n“in between” Concert\r\n演出時間：2025/04/30 (三) 19:30\r\n演出地點：陽明交大演藝廳 / 學生活動中心二樓 (新竹市大學路1001號)\r\n入場方式：免費、報名入場  (3/30 (日) 12:00開放網路報名)\r\n報名傳送門：https://reurl.cc/mR0VMA\r\n\r\n▌演出者\r\n\r\n鋼琴 / 許佳穎\r\n\r\n「之間 in between」系列音樂會，鋼琴家許佳穎將以法國作曲家梅湘的《二十個對聖嬰耶穌的凝視》作為系列音樂會的開場，這部由二十首標題樂曲組成的鉅作，深切表達梅湘的天主教信仰，及對聖經的多層次探索。梅湘描述這是「充滿神祕之愛的語言」，它充滿變化，時而強而有力，甚至粗暴，卻又時而溫和柔軟，形成洋溢多重色彩的音樂表現。每個「凝視」都蘊含了作曲家獨特的創作語彙，透過多重色彩的音樂表現，譜寫出神聖之愛的洞見。\r\n\r\n▌演出曲目\r\n\r\n梅湘：二十個對聖嬰耶穌的凝視', '國立陽明交通大學藝文中心', '新竹市大學路1001號', '2025-04-30 00:00:00', '2025-04-30 00:00:00', '陽明交大演藝廳', 0, 0, '無資料', 'https://reurl.cc/mR0VMA', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「之間」音樂會', `description`='「之間」音樂會\r\n“in between” Concert\r\n演出時間：2025/04/30 (三) 19:30\r\n演出地點：陽明交大演藝廳 / 學生活動中心二樓 (新竹市大學路1001號)\r\n入場方式：免費、報名入場  (3/30 (日) 12:00開放網路報名)\r\n報名傳送門：https://reurl.cc/mR0VMA\r\n\r\n▌演出者\r\n\r\n鋼琴 / 許佳穎\r\n\r\n「之間 in between」系列音樂會，鋼琴家許佳穎將以法國作曲家梅湘的《二十個對聖嬰耶穌的凝視》作為系列音樂會的開場，這部由二十首標題樂曲組成的鉅作，深切表達梅湘的天主教信仰，及對聖經的多層次探索。梅湘描述這是「充滿神祕之愛的語言」，它充滿變化，時而強而有力，甚至粗暴，卻又時而溫和柔軟，形成洋溢多重色彩的音樂表現。每個「凝視」都蘊含了作曲家獨特的創作語彙，透過多重色彩的音樂表現，譜寫出神聖之愛的洞見。\r\n\r\n▌演出曲目\r\n\r\n梅湘：二十個對聖嬰耶穌的凝視', `organizer`='國立陽明交通大學藝文中心', `address`='新竹市大學路1001號', `start_date`='2025-04-30 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='陽明交大演藝廳', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://reurl.cc/mR0VMA', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b58a038f15d8562cfcd6e6', '《舌燦蓮花》漢霖民俗說唱藝術團', '《舌燦蓮花》漢霖民俗說唱藝術團\r\nPlausible Lotus Tongue\r\n演出時間：2025/05/06 (二) 19:30\r\n演出地點：陽明交大演藝廳 / 學生活動中心二樓 (新竹市大學路1001號)\r\n入場方式：免費、報名入場  (4/06 (日) 12:00開放網路報名)\r\n報名傳送門：https://reurl.cc/04Z5K6\r\n\r\n▌演出者\r\n\r\n王振全、張春泉、林惠煖、錢君銜、賈祥國、謝湘翊\r\n\r\n民國114年是農曆的「蛇」年，特別推出應景節目《舌燦蓮花》。「舌燦蓮花」用來形容一個人口齒伶俐，能言善道，說話如蓮花般動聽，讓人樂於接受。\r\n\r\n「漢霖民俗說唱藝術團」將於2025年迎來40歲的生日。《舌燦蓮花》節目內容豐富，包含相聲、戲劇、雙黃等元素，藝員們各展所長，只為了爭「誰的口才更出色？」「誰說得更精彩？」同時，以最擅長的表演形式和精心編排的節目內容，證明自己「舌燦蓮花」！\r\n\r\n▌演出段子\r\n\r\n對口相聲：【口吐蓮花】\r\n文學相聲：【詩情畫意】\r\n時代相聲：【蛇年談蛇】\r\n竹板快書：【小白蛇傳】\r\n台語相聲：【喊玲瓏賣什(蛇)細】\r\n雙黃：【魯蛇翻身】', '國立陽明交通大學藝文中心', '新竹市大學路1001號', '2025-05-06 00:00:00', '2025-05-06 00:00:00', '陽明交大演藝廳 ', 0, 0, '無資料', 'https://reurl.cc/04Z5K6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《舌燦蓮花》漢霖民俗說唱藝術團', `description`='《舌燦蓮花》漢霖民俗說唱藝術團\r\nPlausible Lotus Tongue\r\n演出時間：2025/05/06 (二) 19:30\r\n演出地點：陽明交大演藝廳 / 學生活動中心二樓 (新竹市大學路1001號)\r\n入場方式：免費、報名入場  (4/06 (日) 12:00開放網路報名)\r\n報名傳送門：https://reurl.cc/04Z5K6\r\n\r\n▌演出者\r\n\r\n王振全、張春泉、林惠煖、錢君銜、賈祥國、謝湘翊\r\n\r\n民國114年是農曆的「蛇」年，特別推出應景節目《舌燦蓮花》。「舌燦蓮花」用來形容一個人口齒伶俐，能言善道，說話如蓮花般動聽，讓人樂於接受。\r\n\r\n「漢霖民俗說唱藝術團」將於2025年迎來40歲的生日。《舌燦蓮花》節目內容豐富，包含相聲、戲劇、雙黃等元素，藝員們各展所長，只為了爭「誰的口才更出色？」「誰說得更精彩？」同時，以最擅長的表演形式和精心編排的節目內容，證明自己「舌燦蓮花」！\r\n\r\n▌演出段子\r\n\r\n對口相聲：【口吐蓮花】\r\n文學相聲：【詩情畫意】\r\n時代相聲：【蛇年談蛇】\r\n竹板快書：【小白蛇傳】\r\n台語相聲：【喊玲瓏賣什(蛇)細】\r\n雙黃：【魯蛇翻身】', `organizer`='國立陽明交通大學藝文中心', `address`='新竹市大學路1001號', `start_date`='2025-05-06 00:00:00', `end_date`='2025-05-06 00:00:00', `location`='陽明交大演藝廳 ', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://reurl.cc/04Z5K6', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b58aa78f15d8562cfcd6e7', '《靈魂的旅程》橫跨200多年的東西方音樂經典', '《靈魂的旅程》橫跨200多年的東西方音樂經典\r\nThe Journey of the Soul:\r\nOver 200 Years of Eastern and Western Music Classics\r\n演出時間：2025/05/14 (三) 19:30\r\n演出地點：陽明交大演藝廳 / 學生活動中心二樓 (新竹市大學路1001號)\r\n入場方式：免費、報名入場  (4/14 (一) 12:00開放網路報名)\r\n報名傳送門：https://reurl.cc/eGdekR\r\n\r\n▌演出者\r\n\r\n木笛 / 梁益彰\r\n女高音 / 吉澤真紀 Maki Yoshizawa\r\n大鍵琴 / 須藤真地子 Machiko Suto\r\n\r\n這場音樂會由台灣與日本音樂家攜手合作，採用木笛、女高音與大鍵琴的編制，呈現橫跨巴洛克時期至20世紀的東西方經典聲樂與器樂作品。西方曲目以巴洛克時期的代表作曲家，如韓德爾、泰勒曼、巴貝爾等人的作品為主，展現該時代的燦爛與永恆之美；東方曲目則選自日本近代知名作曲家山田耕筰、別宮貞雄、武滿徹和細川俊夫的作品，體現濃厚的東方美學與哲思。\r\n\r\n音樂會以「歌」與「靈魂」為主題，透過風格與情感各異的聲樂與器樂作品，展現歌的多樣風貌，並透過跨時代作品，探討人類對靈魂本質的深刻追尋，展現東西方音樂的融合之美。\r\n\r\n▌演出曲目\r\n\r\n泰勒曼：清唱劇《靈魂啊，學會認識自己吧》\r\n細川俊夫：垂直的歌\r\n泰勒曼：〈A大調奏鳴曲〉，選自《12首教學奏鳴曲》\r\n武滿徹：雨夢\r\n山田耕筰：唄\r\n別宮貞雄：櫻花小徑\r\n山田耕筰：松島音頭\r\n巴貝爾：〈前奏曲〉與〈讓我哭泣吧〉，選自《最著名的大鍵琴曲集》\r\n韓德爾：〈我的靈魂被聽見看見了〉，選自《9首德文歌曲》', '國立陽明交通大學藝文中心', '新竹市大學路1001號', '2025-05-14 00:00:00', '2025-05-14 00:00:00', '陽明交大演藝廳', 0, 0, '無資料', 'https://reurl.cc/eGdekR', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《靈魂的旅程》橫跨200多年的東西方音樂經典', `description`='《靈魂的旅程》橫跨200多年的東西方音樂經典\r\nThe Journey of the Soul:\r\nOver 200 Years of Eastern and Western Music Classics\r\n演出時間：2025/05/14 (三) 19:30\r\n演出地點：陽明交大演藝廳 / 學生活動中心二樓 (新竹市大學路1001號)\r\n入場方式：免費、報名入場  (4/14 (一) 12:00開放網路報名)\r\n報名傳送門：https://reurl.cc/eGdekR\r\n\r\n▌演出者\r\n\r\n木笛 / 梁益彰\r\n女高音 / 吉澤真紀 Maki Yoshizawa\r\n大鍵琴 / 須藤真地子 Machiko Suto\r\n\r\n這場音樂會由台灣與日本音樂家攜手合作，採用木笛、女高音與大鍵琴的編制，呈現橫跨巴洛克時期至20世紀的東西方經典聲樂與器樂作品。西方曲目以巴洛克時期的代表作曲家，如韓德爾、泰勒曼、巴貝爾等人的作品為主，展現該時代的燦爛與永恆之美；東方曲目則選自日本近代知名作曲家山田耕筰、別宮貞雄、武滿徹和細川俊夫的作品，體現濃厚的東方美學與哲思。\r\n\r\n音樂會以「歌」與「靈魂」為主題，透過風格與情感各異的聲樂與器樂作品，展現歌的多樣風貌，並透過跨時代作品，探討人類對靈魂本質的深刻追尋，展現東西方音樂的融合之美。\r\n\r\n▌演出曲目\r\n\r\n泰勒曼：清唱劇《靈魂啊，學會認識自己吧》\r\n細川俊夫：垂直的歌\r\n泰勒曼：〈A大調奏鳴曲〉，選自《12首教學奏鳴曲》\r\n武滿徹：雨夢\r\n山田耕筰：唄\r\n別宮貞雄：櫻花小徑\r\n山田耕筰：松島音頭\r\n巴貝爾：〈前奏曲〉與〈讓我哭泣吧〉，選自《最著名的大鍵琴曲集》\r\n韓德爾：〈我的靈魂被聽見看見了〉，選自《9首德文歌曲》', `organizer`='國立陽明交通大學藝文中心', `address`='新竹市大學路1001號', `start_date`='2025-05-14 00:00:00', `end_date`='2025-05-14 00:00:00', `location`='陽明交大演藝廳', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://reurl.cc/eGdekR', `image_url`='[]';
