INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b654f926b3240c403d96b5', '無資料', '好康報報!!\n\n「就是愛，台灣：2025林磐聳台灣意象展」講座及專場導覽，參加者還有機會獲得經典限量明信片組，完全免費，千萬別錯過喔!!\n\n \n\n林磐聳教授將帶領大家瞭解他以台灣島嶼圖像的創作歷程，從故鄉東港談海洋性格，到他如何將台灣印象海報設計成為國際識別符碼，以及「台灣練習曲」、「台灣觀自在」及「台灣家書」等等系列創作，不藏私地大方公開其多年來創作核心密碼!!\n\n \n\n「我的台灣，看見心靈的故鄉」專題演講\n\n講者：林磐聳教授\n\n時間：114年2月22日（週六），上午10:00- 12:00\n\n地點：中正紀念堂三樓318教室\n\n \n\n「就是愛，台灣」專場導覽 \n\n第1場\n\n講者：藝術家 林磐聳教授\n\n時間：114年2月22日（週六），下午14:00-15:30\n\n地點：中正紀念堂一樓3展廳集合\n\n \n\n第2場\n\n講者：策展人 廖仁義教授\n\n時間：114年2月23日（週日），下午14:00-15:30\n\n地點：中正紀念堂一樓3展廳集合\n\n \n\n「就是愛，台灣：2025林磐聳台灣意象展」 展覽資訊請參考 連結\n\n展覽地點：中正紀念堂2、3展廳（台北市中正區中山南路21號）\n\n展覽期間：2025/1/15（三）- 2025/3/10（一）\n\n開放時間：週一至週日9：00-18：00\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '3展廳', 25.0367564, 121.519047, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='好康報報!!\n\n「就是愛，台灣：2025林磐聳台灣意象展」講座及專場導覽，參加者還有機會獲得經典限量明信片組，完全免費，千萬別錯過喔!!\n\n \n\n林磐聳教授將帶領大家瞭解他以台灣島嶼圖像的創作歷程，從故鄉東港談海洋性格，到他如何將台灣印象海報設計成為國際識別符碼，以及「台灣練習曲」、「台灣觀自在」及「台灣家書」等等系列創作，不藏私地大方公開其多年來創作核心密碼!!\n\n \n\n「我的台灣，看見心靈的故鄉」專題演講\n\n講者：林磐聳教授\n\n時間：114年2月22日（週六），上午10:00- 12:00\n\n地點：中正紀念堂三樓318教室\n\n \n\n「就是愛，台灣」專場導覽 \n\n第1場\n\n講者：藝術家 林磐聳教授\n\n時間：114年2月22日（週六），下午14:00-15:30\n\n地點：中正紀念堂一樓3展廳集合\n\n \n\n第2場\n\n講者：策展人 廖仁義教授\n\n時間：114年2月23日（週日），下午14:00-15:30\n\n地點：中正紀念堂一樓3展廳集合\n\n \n\n「就是愛，台灣：2025林磐聳台灣意象展」 展覽資訊請參考 連結\n\n展覽地點：中正紀念堂2、3展廳（台北市中正區中山南路21號）\n\n展覽期間：2025/1/15（三）- 2025/3/10（一）\n\n開放時間：週一至週日9：00-18：00\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `location`='3展廳', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6550526b3240c403d96b6', '鍾理和讀劇：《 美濃農事旱雨記》', '為紀念擅長書寫鄉土的客家作家鍾理和（1915/1960）2025年為冥誕110年，文學好客計畫特別邀請「那個劇團」 改編鍾理和的日記、〈西北雨〉、〈旱〉等文章演出讀劇《美濃農事旱雨記》。跟著劇情我們將走進鍾理和的作品和真實生活中，一起感受當時鍾理和當時的所處所景、客家庄的地貌文化。\n\n鍾理和讀劇：《美濃農事旱雨記》 於3/23（日）14:30和16:30演出2場。每場演出包含演後座談。主要為華語演出但有部分臺灣客語台詞。第1場於14:00開放入場、第2場於16:00開放入場。\n\n \n\n鍾理和讀劇：《美濃農事旱雨記》 14:30場次\n\n\n	\n		\n			時間\n			內容\n		\n		\n			14:00-14:30\n			報到                                       \n		\n		\n			14:30-15:10\n			演出\n		\n		\n			15:10-15:30\n			演後座談\n		\n	\n\n\n \n\n鍾理和讀劇：《美濃農事旱雨記》 16:30場次\n\n\n	\n		\n			時間\n			內容\n		\n		\n			16:00-16:30\n			報到                                       \n		\n		\n			16:30-17:10\n			演出\n		\n		\n			17:10-17:30\n			演後座談\n		\n	\n\n\n活動承辦臺文館邱小姐：hsin@nmtl.gov.tw/06-221-7201＃2214\n\n ', '國立台灣文學館', '700  臺南市中西區台南市中西區中正路1號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '國立臺灣文學館1樓演講廳', 22.9919899, 120.2045956, '無資料', 'https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=50049', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鍾理和讀劇：《 美濃農事旱雨記》', `description`='為紀念擅長書寫鄉土的客家作家鍾理和（1915/1960）2025年為冥誕110年，文學好客計畫特別邀請「那個劇團」 改編鍾理和的日記、〈西北雨〉、〈旱〉等文章演出讀劇《美濃農事旱雨記》。跟著劇情我們將走進鍾理和的作品和真實生活中，一起感受當時鍾理和當時的所處所景、客家庄的地貌文化。\n\n鍾理和讀劇：《美濃農事旱雨記》 於3/23（日）14:30和16:30演出2場。每場演出包含演後座談。主要為華語演出但有部分臺灣客語台詞。第1場於14:00開放入場、第2場於16:00開放入場。\n\n \n\n鍾理和讀劇：《美濃農事旱雨記》 14:30場次\n\n\n	\n		\n			時間\n			內容\n		\n		\n			14:00-14:30\n			報到                                       \n		\n		\n			14:30-15:10\n			演出\n		\n		\n			15:10-15:30\n			演後座談\n		\n	\n\n\n \n\n鍾理和讀劇：《美濃農事旱雨記》 16:30場次\n\n\n	\n		\n			時間\n			內容\n		\n		\n			16:00-16:30\n			報到                                       \n		\n		\n			16:30-17:10\n			演出\n		\n		\n			17:10-17:30\n			演後座談\n		\n	\n\n\n活動承辦臺文館邱小姐：hsin@nmtl.gov.tw/06-221-7201＃2214\n\n ', `organizer`='國立台灣文學館', `address`='700  臺南市中西區台南市中西區中正路1號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='國立臺灣文學館1樓演講廳', `latitude`=22.9919899, `longitude`=120.2045956, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=50049', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6551826b3240c403d96b7', '「諸神與眾生」專家導覽', ' \n\n \n\n\n\n \n\n\n活動亮點\n\n\n \n\n耕耘攝影創作與教育的鄧博仁，帶我們走入展間，一同欣賞「諸神與眾生」展覽：\n\n \n\n                         ►追尋諸神、思索眾生處境？漫遊作品之間，認識展覽主軸！\n\n                         ►從媒材到創作手法，藝術家視角分享本展作品的豐富呈現方式！\n\n                         ►透過創作，藝術家們想說什麼？走讀展間，解讀作品背後的意義！\n\n \n\n \n\n\n講者簡介\n\n\n \n\n鄧博仁｜藝術家\n\n國立臺灣科技大學設計系兼任助理教授，同時也是影像創作、媒體工作者。熱衷於時尚、紀實、編導、觀念攝影，並擅長用影像拼貼說故事，創作議題關心人與城市及所生長的環境。目前從事媒體工作、攝影教學，及持續不斷的攝影藝術創作。\n\n \n\n \n\n\n \n\n活動時間\n\n\n2025年3月8日（六）\n\n14:00~16:00\n\n \n\n\n活動地點\n\n\n國家攝影文化中心 臺北館 2、3樓展間\n\n來館交通：交通資訊點此\n\n \n\n \n\n ', '國家攝影文化中心', '100  臺北市中正區忠孝西路一段70號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '國家攝影文化中心臺北館2、3樓展間', 25.0466999, 121.514495, '無資料', 'https://event.culture.tw/mocweb/reg/NCPI/Detail.init.ctr?actId=50002', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「諸神與眾生」專家導覽', `description`=' \n\n \n\n\n\n \n\n\n活動亮點\n\n\n \n\n耕耘攝影創作與教育的鄧博仁，帶我們走入展間，一同欣賞「諸神與眾生」展覽：\n\n \n\n                         ►追尋諸神、思索眾生處境？漫遊作品之間，認識展覽主軸！\n\n                         ►從媒材到創作手法，藝術家視角分享本展作品的豐富呈現方式！\n\n                         ►透過創作，藝術家們想說什麼？走讀展間，解讀作品背後的意義！\n\n \n\n \n\n\n講者簡介\n\n\n \n\n鄧博仁｜藝術家\n\n國立臺灣科技大學設計系兼任助理教授，同時也是影像創作、媒體工作者。熱衷於時尚、紀實、編導、觀念攝影，並擅長用影像拼貼說故事，創作議題關心人與城市及所生長的環境。目前從事媒體工作、攝影教學，及持續不斷的攝影藝術創作。\n\n \n\n \n\n\n \n\n活動時間\n\n\n2025年3月8日（六）\n\n14:00~16:00\n\n \n\n\n活動地點\n\n\n國家攝影文化中心 臺北館 2、3樓展間\n\n來館交通：交通資訊點此\n\n \n\n \n\n ', `organizer`='國家攝影文化中心', `address`='100  臺北市中正區忠孝西路一段70號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='國家攝影文化中心臺北館2、3樓展間', `latitude`=25.0466999, `longitude`=121.514495, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NCPI/Detail.init.ctr?actId=50002', `image_url`='[]';
