INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655cf26b3240c403d96b9', '《班奈兔環遊世界》油畫個展', 'Bennett Bunny Around the World\r\n2025年，班奈兔迎接首次的個展，展覽裡將會展出班奈兔從2020開始在世界各地旅遊及探險的足跡，一起來看看班奈兔都去了哪了哪裡冒險、穿梭在世界的那些角落吧。', '桃園市立圖書館', '桃園市中壢區中美路76號', '2025-02-04 00:00:00', '2025-02-25 00:00:00', '桃園市立圖書館中壢分館', 24.97993803, 121.2147243, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《班奈兔環遊世界》油畫個展', `description`='Bennett Bunny Around the World\r\n2025年，班奈兔迎接首次的個展，展覽裡將會展出班奈兔從2020開始在世界各地旅遊及探險的足跡，一起來看看班奈兔都去了哪了哪裡冒險、穿梭在世界的那些角落吧。', `organizer`='桃園市立圖書館', `address`='桃園市中壢區中美路76號', `start_date`='2025-02-04 00:00:00', `end_date`='2025-02-25 00:00:00', `location`='桃園市立圖書館中壢分館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655e026b3240c403d96c1', '七十光影·心的開始-謝雪華個展', '藝術家謝雪華老師擅長以油畫創作，刻下農、漁家向天討生活、刻苦堅韌的寫照；本次展出作品，以家鄉中部海線為靈感，記錄海線地區的鄉土人文及勞動者的日常堅韌，將農漁生活與自然景觀化為藝術語彙。如描繪在地人文特色的〈浣〉、〈印象家鄉〉，溫馨回憶了南勢溪洗衣婦女的身影與鄉野田園的景緻，喚起觀者對漸逝鄉土映像的共鳴。\r\n透過藝術家的筆調，呈現二十年來的創作精華，邀請觀者感受對生命韌性與天地哲思的深刻詮釋。傳達對家鄉、土地的認同與關懷珍惜。', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-02-01 00:00:00', '2025-03-02 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=bf88c5bfa9144891b116570c5dea0413', '[]') ON DUPLICATE KEY UPDATE `activity_name`='七十光影·心的開始-謝雪華個展', `description`='藝術家謝雪華老師擅長以油畫創作，刻下農、漁家向天討生活、刻苦堅韌的寫照；本次展出作品，以家鄉中部海線為靈感，記錄海線地區的鄉土人文及勞動者的日常堅韌，將農漁生活與自然景觀化為藝術語彙。如描繪在地人文特色的〈浣〉、〈印象家鄉〉，溫馨回憶了南勢溪洗衣婦女的身影與鄉野田園的景緻，喚起觀者對漸逝鄉土映像的共鳴。\r\n透過藝術家的筆調，呈現二十年來的創作精華，邀請觀者感受對生命韌性與天地哲思的深刻詮釋。傳達對家鄉、土地的認同與關懷珍惜。', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=bf88c5bfa9144891b116570c5dea0413', `image_url`='[]';
