INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655e726b3240c403d96cf', '臺中市立圖書館大墩分館2月主題書展', '臺中市立圖書館大墩分館2月主題書展\r\n2樓兒童書展區:「漢」韻書香主題書展\r\n漢語為世界上母語使用者人數最多的語言，透過書展兒童可了解漢字的文學創作與文化的傳承。\r\n3樓開架閱覽區:寵物幸福樂園書展 \r\n牠們不只是寵物，更是我們的家人。近年因動物意識抬頭，人們愈加重視動物平權議題，寵物在我們生活中所佔的比例愈來愈高，也帶動寵物法律機制完善及寵物經濟的趨勢，透過這次書展，可以了解寵物的需要及知識。\r\n', '臺中市立圖書館大墩分館', '臺中市西區英才路600號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺中市立圖書館大墩分館', 24.14391082, 120.6647579, '無資料', 'https://pse.is/729qlt  ;  https://pse.is/729q7e', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館大墩分館2月主題書展', `description`='臺中市立圖書館大墩分館2月主題書展\r\n2樓兒童書展區:「漢」韻書香主題書展\r\n漢語為世界上母語使用者人數最多的語言，透過書展兒童可了解漢字的文學創作與文化的傳承。\r\n3樓開架閱覽區:寵物幸福樂園書展 \r\n牠們不只是寵物，更是我們的家人。近年因動物意識抬頭，人們愈加重視動物平權議題，寵物在我們生活中所佔的比例愈來愈高，也帶動寵物法律機制完善及寵物經濟的趨勢，透過這次書展，可以了解寵物的需要及知識。\r\n', `organizer`='臺中市立圖書館大墩分館', `address`='臺中市西區英才路600號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市立圖書館大墩分館', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://pse.is/729qlt  ;  https://pse.is/729q7e', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655e826b3240c403d96d0', '粉彩起舞-畫展', '粉彩起舞-畫展\r\n展出者：秦嗣華老師\r\n經歷：1.台中教育大學進修推廣部「兒童藝術啟蒙師資培訓」  2.日本和諧粉彩準指導師\r\n展覽地點：霧峰戶政事務所一樓\r\n展覽時間：(週一～週五8:00～17:30)\r\n歡迎大小朋友一同來觀賞', '臺中市霧峰區戶政事務所', '臺中市霧峰區', '2025-01-03 00:00:00', '2025-05-30 00:00:00', '霧峰區（臺中市）=', 24.04332785, 120.7201989, '無資料', 'https://reurl.cc/oVG9aj', '[]') ON DUPLICATE KEY UPDATE `activity_name`='粉彩起舞-畫展', `description`='粉彩起舞-畫展\r\n展出者：秦嗣華老師\r\n經歷：1.台中教育大學進修推廣部「兒童藝術啟蒙師資培訓」  2.日本和諧粉彩準指導師\r\n展覽地點：霧峰戶政事務所一樓\r\n展覽時間：(週一～週五8:00～17:30)\r\n歡迎大小朋友一同來觀賞', `organizer`='臺中市霧峰區戶政事務所', `address`='臺中市霧峰區', `start_date`='2025-01-03 00:00:00', `end_date`='2025-05-30 00:00:00', `location`='霧峰區（臺中市）=', `latitude`=24.04332785, `longitude`=120.7201989, `ticket_price`='無資料', `source_url`='https://reurl.cc/oVG9aj', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655e826b3240c403d96d1', '審計新村368新創聚落114年2月街藝表演', '台中審計新村全稱為「審計新村368新創聚落」，前身為臺中省政府審計處的員工宿舍，而在1998年凍省後被閒置荒廢多年，直到2015年因配合臺中市政府的創業基地進駐計畫，加入藝術元素整修改造，才讓審計新村得以用全新的面貌被大眾認識。\r\n喜歡音樂的你們，聚落邀請你們一同來欣賞表演，並支持你尬意的街頭藝人。', '審計368新創聚落', '臺中市西區', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://lurl.cc/TyZfrk', '[]') ON DUPLICATE KEY UPDATE `activity_name`='審計新村368新創聚落114年2月街藝表演', `description`='台中審計新村全稱為「審計新村368新創聚落」，前身為臺中省政府審計處的員工宿舍，而在1998年凍省後被閒置荒廢多年，直到2015年因配合臺中市政府的創業基地進駐計畫，加入藝術元素整修改造，才讓審計新村得以用全新的面貌被大眾認識。\r\n喜歡音樂的你們，聚落邀請你們一同來欣賞表演，並支持你尬意的街頭藝人。', `organizer`='審計368新創聚落', `address`='臺中市西區', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://lurl.cc/TyZfrk', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655e826b3240c403d96d2', '2月主題書展- 山不在高，有仙則名-登山主題書展', '2月主題書展-山不在高，有仙則名 (登山主題)\r\n登山主題書展精選多元書籍，涵蓋登山技巧、冒險故事、山地文化及自然生態，為愛山者提供豐富的知識與靈感。', '臺中市立圖書館太平分館', '臺中市太平區太平三街20號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館太平分館', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/NbM8Yx', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月主題書展- 山不在高，有仙則名-登山主題書展', `description`='2月主題書展-山不在高，有仙則名 (登山主題)\r\n登山主題書展精選多元書籍，涵蓋登山技巧、冒險故事、山地文化及自然生態，為愛山者提供豐富的知識與靈感。', `organizer`='臺中市立圖書館太平分館', `address`='臺中市太平區太平三街20號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館太平分館', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/NbM8Yx', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655e926b3240c403d96d3', '無資料', '小鷺說故事\r\n在港藝蘇州庭園的荷花池邊，小白鷺鷥，靜靜站立在石頭上等待魚兒，風雨無阻，盡心盡力，日以繼夜等待您的蒞臨觀賞。\r\n\r\n臺中市立港區藝術中心志工服務隊以這隻白色小鷺為主題，規劃了小鷺說故事活動。\r\n\r\n每個小孩就像小白鷺鷥，家長們可以在假期與孩子們來一起來港藝享受大自然，欣賞藝術作品，一起聽故事，陪伴孩子成長的饗宴。\r\n\r\n今年2024臺中市立港區藝術中心志工服務隊於2024年3月24日於美術家資料館繪本故事屋辦理首場小鷺說故事，邀請您一同前往聽小鷺說故事。\r\n\r\n每月第4個週日，下午3點於美術家資料館\r\n2025年2月23日於美術家資料館', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='小鷺說故事\r\n在港藝蘇州庭園的荷花池邊，小白鷺鷥，靜靜站立在石頭上等待魚兒，風雨無阻，盡心盡力，日以繼夜等待您的蒞臨觀賞。\r\n\r\n臺中市立港區藝術中心志工服務隊以這隻白色小鷺為主題，規劃了小鷺說故事活動。\r\n\r\n每個小孩就像小白鷺鷥，家長們可以在假期與孩子們來一起來港藝享受大自然，欣賞藝術作品，一起聽故事，陪伴孩子成長的饗宴。\r\n\r\n今年2024臺中市立港區藝術中心志工服務隊於2024年3月24日於美術家資料館繪本故事屋辦理首場小鷺說故事，邀請您一同前往聽小鷺說故事。\r\n\r\n每月第4個週日，下午3點於美術家資料館\r\n2025年2月23日於美術家資料館', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655e926b3240c403d96d4', '六路社區照顧關懷據點與您同樂薩克斯風流行歌曲演奏(4場)', '《曲目》\r\n快樂的出帆、雲中月圓、甜蜜成雙對、月亮代表我的心、小城故事、深情海岸、月兒望月想愛人、好男兒、疼你若生命、情深深、阿母的手、媽媽請您也保重、春夏秋冬、彼個小姑娘、榕樹下、針線情、月夜情、啟田純情曲、期待再相會\r\n\r\n每月演出時，以上曲目現場輪流選曲演出\r\n\r\n演出團隊：飛歌薩克斯風樂團\r\n\r\n \r\n\r\n#臺中市政府文化局\r\n#表演藝術類活動補助', '臺中市沙鹿區六路社區發展協會', '臺中市沙鹿區', '2025-03-04 00:00:00', '2025-06-17 00:00:00', '沙鹿區（臺中市）=', 24.23425212, 120.5838628, '無資料', 'https://www.culture.taichung.gov.tw/2885477/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='六路社區照顧關懷據點與您同樂薩克斯風流行歌曲演奏(4場)', `description`='《曲目》\r\n快樂的出帆、雲中月圓、甜蜜成雙對、月亮代表我的心、小城故事、深情海岸、月兒望月想愛人、好男兒、疼你若生命、情深深、阿母的手、媽媽請您也保重、春夏秋冬、彼個小姑娘、榕樹下、針線情、月夜情、啟田純情曲、期待再相會\r\n\r\n每月演出時，以上曲目現場輪流選曲演出\r\n\r\n演出團隊：飛歌薩克斯風樂團\r\n\r\n \r\n\r\n#臺中市政府文化局\r\n#表演藝術類活動補助', `organizer`='臺中市沙鹿區六路社區發展協會', `address`='臺中市沙鹿區', `start_date`='2025-03-04 00:00:00', `end_date`='2025-06-17 00:00:00', `location`='沙鹿區（臺中市）=', `latitude`=24.23425212, `longitude`=120.5838628, `ticket_price`='無資料', `source_url`='https://www.culture.taichung.gov.tw/2885477/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655eb26b3240c403d96d6', '精武圖書館-2月書展', '《新年好！畫出你的乙巳年》 1樓歲月流金區\r\n新年好，從充滿四季景象的窗，\r\n看見對乙巳年的展望✨\r\n可以一個人完成，也可以一群人經歷。\r\n\r\n此展覽特別推薦與過年相關的書籍，包含關於新年的知識，描繪過年節慶的圖書內容，陪伴讀者更了解本國的民俗及節慶文化。\r\n同時也以窗花、剪紙為主題意象，向大家介紹有關剪紙的技巧方法，包含剪鏤及刀刻兩種方式，先描繪草稿，再標註要留下及剪去的地方，特殊小技巧則為遇到圓滑曲線，以轉紙方始取代轉刀，即可使線條更為滑順。\r\n透過可視的工藝技法，帶領讀者一起走向乙巳年。\r\n祝福大家新年快樂，身體健康、萬事如意🏮\r\n除此之外，展區也備有留言小紙條🖊️\r\n歡迎大家寫下對新年的展望！\r\n\r\n《Yes I Cat國際貓咪日》  2樓文學區\r\n在日本2月22日「貓之日」（猫の日），1987年由日本寵物食品協會設立，該節意義是表達人與貓隻和平相處，\r\n而選擇此日的原因是「2」在日語的讀音與相關擬聲詞「ニャン」相近似，所以定於此日為「貓之日」。\r\n\r\n貓咪在現代網路高度發達、社交模式改變，生活節奏緊湊的社會中，也逐漸成為生活夥伴的首選之一。\r\n此書展將介紹貓咪的冷知識及照顧方式等有趣內容，也有從貓咪視角而創作的圖文集文學等作品。\r\n\r\n總有一本書、一個故事、一隻貓貓，可以成為生活中的療癒小天使，\r\n忙碌完年末，迎接新年的開始，邀請各位讀者來到精武圖書館，尋找屬於您的幸運貓貓！', '臺中市精武圖書館', '臺中市北區精武路291之3號', '2025-02-02 00:00:00', '2025-02-27 00:00:00', '臺中市精武圖書館', 24.15863985, 120.6809521, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='精武圖書館-2月書展', `description`='《新年好！畫出你的乙巳年》 1樓歲月流金區\r\n新年好，從充滿四季景象的窗，\r\n看見對乙巳年的展望✨\r\n可以一個人完成，也可以一群人經歷。\r\n\r\n此展覽特別推薦與過年相關的書籍，包含關於新年的知識，描繪過年節慶的圖書內容，陪伴讀者更了解本國的民俗及節慶文化。\r\n同時也以窗花、剪紙為主題意象，向大家介紹有關剪紙的技巧方法，包含剪鏤及刀刻兩種方式，先描繪草稿，再標註要留下及剪去的地方，特殊小技巧則為遇到圓滑曲線，以轉紙方始取代轉刀，即可使線條更為滑順。\r\n透過可視的工藝技法，帶領讀者一起走向乙巳年。\r\n祝福大家新年快樂，身體健康、萬事如意🏮\r\n除此之外，展區也備有留言小紙條🖊️\r\n歡迎大家寫下對新年的展望！\r\n\r\n《Yes I Cat國際貓咪日》  2樓文學區\r\n在日本2月22日「貓之日」（猫の日），1987年由日本寵物食品協會設立，該節意義是表達人與貓隻和平相處，\r\n而選擇此日的原因是「2」在日語的讀音與相關擬聲詞「ニャン」相近似，所以定於此日為「貓之日」。\r\n\r\n貓咪在現代網路高度發達、社交模式改變，生活節奏緊湊的社會中，也逐漸成為生活夥伴的首選之一。\r\n此書展將介紹貓咪的冷知識及照顧方式等有趣內容，也有從貓咪視角而創作的圖文集文學等作品。\r\n\r\n總有一本書、一個故事、一隻貓貓，可以成為生活中的療癒小天使，\r\n忙碌完年末，迎接新年的開始，邀請各位讀者來到精武圖書館，尋找屬於您的幸運貓貓！', `organizer`='臺中市精武圖書館', `address`='臺中市北區精武路291之3號', `start_date`='2025-02-02 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市精武圖書館', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655eb26b3240c403d96d9', '畫喜充滿 美善人生~蔡淑貞師生彩墨展', '此次展出的作品，是長者們近6年的成果展現，將自然之美、人文情懷以及長者的生命故事融入其中，不僅展現長者的藝術才華，也讓人感受到生命的豐富與美好。', '臺中市政府地方稅務局', '臺中市西屯區文心路二段99號', '2025-02-03 00:00:00', '2025-02-27 00:00:00', '臺中市政府地方稅務局', 24.18308895, 120.6270131, '無資料', 'https://www.tax.taichung.gov.tw/4499/5200/5420/34124/normalPost', '[]') ON DUPLICATE KEY UPDATE `activity_name`='畫喜充滿 美善人生~蔡淑貞師生彩墨展', `description`='此次展出的作品，是長者們近6年的成果展現，將自然之美、人文情懷以及長者的生命故事融入其中，不僅展現長者的藝術才華，也讓人感受到生命的豐富與美好。', `organizer`='臺中市政府地方稅務局', `address`='臺中市西屯區文心路二段99號', `start_date`='2025-02-03 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市政府地方稅務局', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://www.tax.taichung.gov.tw/4499/5200/5420/34124/normalPost', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655eb26b3240c403d96da', '無資料', '2/02(日)-「炊粿慶團圓」-瓊玉\r\n2/09(日)-「巧克力女孩」-淑禎\r\n2/16(日)-「做一件很棒的事」-饅頭\r\n2/23(日)-「我的花卉寶寶」-饅頭', '臺中市立圖書館豐原分館', '臺中市豐原區育仁路81號', '臺中市立圖書館豐原分館', 24.24990298, 120.7375715, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='2/02(日)-「炊粿慶團圓」-瓊玉\r\n2/09(日)-「巧克力女孩」-淑禎\r\n2/16(日)-「做一件很棒的事」-饅頭\r\n2/23(日)-「我的花卉寶寶」-饅頭', `organizer`='臺中市立圖書館豐原分館', `address`='臺中市豐原區育仁路81號', `location`='臺中市立圖書館豐原分館', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655eb26b3240c403d96dc', '林權助紀念基金會 攝影巡迴展', '林權助為臺灣最早期研究彩色攝影與沖印之先驅，其沖印之彩色相片，色調豐富，層次分明。而攝影取材角度，聚焦於人、物、地景與田園風光之農村生活，將當時的臺灣風貌，完整地保存下來。本次與林權助紀念基金會籌備處合辦，以展出林權助於1950至1970年代拍攝之田園風光攝影作品，呈現臺灣農村豐富的生命力。', '臺中市立圖書館豐原分館', '臺中市豐原區育仁路81號', '2025-01-22 00:00:00', '2025-02-26 00:00:00', '臺中市立圖書館豐原分館', 24.24990298, 120.7375715, '無資料', 'https://reurl.cc/Q5G2Oq', '[]') ON DUPLICATE KEY UPDATE `activity_name`='林權助紀念基金會 攝影巡迴展', `description`='林權助為臺灣最早期研究彩色攝影與沖印之先驅，其沖印之彩色相片，色調豐富，層次分明。而攝影取材角度，聚焦於人、物、地景與田園風光之農村生活，將當時的臺灣風貌，完整地保存下來。本次與林權助紀念基金會籌備處合辦，以展出林權助於1950至1970年代拍攝之田園風光攝影作品，呈現臺灣農村豐富的生命力。', `organizer`='臺中市立圖書館豐原分館', `address`='臺中市豐原區育仁路81號', `start_date`='2025-01-22 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='臺中市立圖書館豐原分館', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://reurl.cc/Q5G2Oq', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655ec26b3240c403d96dd', '無資料', '2/02(日)-「小白兔學孵雞」-湘亭\r\n2/09(日)-「元宵湯圓秘四逃脫」-櫻花\r\n2/16(日)- (台語)「再等一下下」-饅頭\r\n2/23(日)- (台語)「我有好多話要說」-饅頭', '臺中市立圖書館豐原南嵩分館', '臺中市豐原區臺中市豐原區水源路17巷2號', '臺中市立圖書館豐原南嵩分館', 24.24990298, 120.7375715, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='2/02(日)-「小白兔學孵雞」-湘亭\r\n2/09(日)-「元宵湯圓秘四逃脫」-櫻花\r\n2/16(日)- (台語)「再等一下下」-饅頭\r\n2/23(日)- (台語)「我有好多話要說」-饅頭', `organizer`='臺中市立圖書館豐原南嵩分館', `address`='臺中市豐原區臺中市豐原區水源路17巷2號', `location`='臺中市立圖書館豐原南嵩分館', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655ec26b3240c403d96de', '2025盛世壁藏～唐代壁畫文化特展三部曲', '歷經6年15場展覽的淬鍊，終於提煉出2025「盛世壁藏～唐代壁畫文化特展．三部曲」！展覽從唐代少年少女的全新視角切入，結合首部曲、二部曲經典壁畫，並融入多幅近年考古發現的壁畫珍品，打造出大唐盛世的「青春年華」！ \r\n展覽共分為「夢想之都」、「錦瑟年華」、「少年歡歌」、「逐夢青雲」、「青春之夢」五個單元，從長安城的生活空間說起，並介紹唐代少男少女的青春風貌與運動愛好，追尋他們的成長軌跡與求學歷程，最後展現當代從事壁畫保護與修復工作青年男女身影，讓壁畫成為溝通古今青春歲月的跨海大橋，使今人可以透過壁畫，穿越時空，遇見唐朝。\r\n今(2025)年展覽將巡迴臺中、新北、新竹三站，以壁畫、模型、影片、體驗裝置等，帶領觀眾多元探索唐代文化，同時規劃文化講座、漢服體驗、展覽解謎遊戲、工作坊等周邊活動，以豐富有趣的互動模式，邀請觀眾穿越時空，走進盛世長安，共赴一場青春之約。\r\n', '社團法人中華翰維文化推廣協會', '臺中市西屯區灣大道四段1727號', '2025-02-21 00:00:00', '2025-03-22 00:00:00', '東海大學', 24.1804743, 120.6207566, '無資料', 'https://tdbh.hanwei-hanya.com', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025盛世壁藏～唐代壁畫文化特展三部曲', `description`='歷經6年15場展覽的淬鍊，終於提煉出2025「盛世壁藏～唐代壁畫文化特展．三部曲」！展覽從唐代少年少女的全新視角切入，結合首部曲、二部曲經典壁畫，並融入多幅近年考古發現的壁畫珍品，打造出大唐盛世的「青春年華」！ \r\n展覽共分為「夢想之都」、「錦瑟年華」、「少年歡歌」、「逐夢青雲」、「青春之夢」五個單元，從長安城的生活空間說起，並介紹唐代少男少女的青春風貌與運動愛好，追尋他們的成長軌跡與求學歷程，最後展現當代從事壁畫保護與修復工作青年男女身影，讓壁畫成為溝通古今青春歲月的跨海大橋，使今人可以透過壁畫，穿越時空，遇見唐朝。\r\n今(2025)年展覽將巡迴臺中、新北、新竹三站，以壁畫、模型、影片、體驗裝置等，帶領觀眾多元探索唐代文化，同時規劃文化講座、漢服體驗、展覽解謎遊戲、工作坊等周邊活動，以豐富有趣的互動模式，邀請觀眾穿越時空，走進盛世長安，共赴一場青春之約。\r\n', `organizer`='社團法人中華翰維文化推廣協會', `address`='臺中市西屯區灣大道四段1727號', `start_date`='2025-02-21 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='東海大學', `latitude`=24.1804743, `longitude`=120.6207566, `ticket_price`='無資料', `source_url`='https://tdbh.hanwei-hanya.com', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655ec26b3240c403d96df', '【中市圖清水分館】2月-幸福語見：台語囡仔古主題書展 ', '配合「2025世界母語日」所規劃之主題書展活動。清水分館將母語生活化，透過繪本及台語文學選書，鼓勵親子、祖孫一起說台語、唱童謠，重新發掘世代相傳的傳說與真實存在過的故事，將無形珍寶的美麗語言傳承下去。予故事繼續行，予台語袂孤單。歡迎做伙來欣賞台語囡仔古！\r\n\r\n※臺中市立圖書館清水分館，工程期間展覽地點移至臨時服務處。\r\n', '臺中市立圖書館清水分館', '臺中市清水區', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '清水區（臺中市）=', 24.29205743, 120.5809094, '無資料', 'https://reurl.cc/36Q6XL', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖清水分館】2月-幸福語見：台語囡仔古主題書展 ', `description`='配合「2025世界母語日」所規劃之主題書展活動。清水分館將母語生活化，透過繪本及台語文學選書，鼓勵親子、祖孫一起說台語、唱童謠，重新發掘世代相傳的傳說與真實存在過的故事，將無形珍寶的美麗語言傳承下去。予故事繼續行，予台語袂孤單。歡迎做伙來欣賞台語囡仔古！\r\n\r\n※臺中市立圖書館清水分館，工程期間展覽地點移至臨時服務處。\r\n', `organizer`='臺中市立圖書館清水分館', `address`='臺中市清水區', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='清水區（臺中市）=', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://reurl.cc/36Q6XL', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655ed26b3240c403d96e0', '無資料', '龍井龍津分館親子閱讀活動\r\n\r\n由劉淑芬老師傳達繪本的各種觀點與訊息加上各種互動方式帶領親子一起來讀書，帶領爸爸媽媽從零到一建立起正確的閱讀觀念。開啓孩子的閱讀之旅，享受閱讀的益處。\r\n\r\n親子讀書會時程表\r\n1/5 (日) 巴士來了\r\n1/12(日) 城市中的森林\r\n1/19(日) 揭密宇宙\r\n1/26(日) 地板下的新鄰居\r\n2/2 (日) 一樣不一樣\r\n2/9 (日) 再試一下\r\n2/16 (日) 我做得到\r\n2/23 (日) 小精靈派對', '臺中市立圖書館龍井龍津分館', '臺中市龍井區', '龍井區（臺中市）=', 24.20062892, 120.5283728, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='龍井龍津分館親子閱讀活動\r\n\r\n由劉淑芬老師傳達繪本的各種觀點與訊息加上各種互動方式帶領親子一起來讀書，帶領爸爸媽媽從零到一建立起正確的閱讀觀念。開啓孩子的閱讀之旅，享受閱讀的益處。\r\n\r\n親子讀書會時程表\r\n1/5 (日) 巴士來了\r\n1/12(日) 城市中的森林\r\n1/19(日) 揭密宇宙\r\n1/26(日) 地板下的新鄰居\r\n2/2 (日) 一樣不一樣\r\n2/9 (日) 再試一下\r\n2/16 (日) 我做得到\r\n2/23 (日) 小精靈派對', `organizer`='臺中市立圖書館龍井龍津分館', `address`='臺中市龍井區', `location`='龍井區（臺中市）=', `latitude`=24.20062892, `longitude`=120.5283728, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655ed26b3240c403d96e1', '日常花事', '日常花事"主題書展，以花卉為核心，呈現花卉與日常生活的深厚聯繫。書展涵蓋從植物學、藝術創作到花卉文化等多方面書籍，邀請讀者一同探索花卉在生活中的美學與意義，感受自然與藝術的交融。\r\n書展地點:豐原分館B棟\r\n書展日期:02/01(六)-02/27(四)', '臺中市立圖書館豐原分館', '臺中市豐原區育仁路81號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館豐原分館', 24.24990298, 120.7375715, '無資料', 'https://www.facebook.com/share/p/15DsHVCaq5/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='日常花事', `description`='日常花事"主題書展，以花卉為核心，呈現花卉與日常生活的深厚聯繫。書展涵蓋從植物學、藝術創作到花卉文化等多方面書籍，邀請讀者一同探索花卉在生活中的美學與意義，感受自然與藝術的交融。\r\n書展地點:豐原分館B棟\r\n書展日期:02/01(六)-02/27(四)', `organizer`='臺中市立圖書館豐原分館', `address`='臺中市豐原區育仁路81號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館豐原分館', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/15DsHVCaq5/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655ed26b3240c403d96e2', '饗閱多肉植物療癒趣', '擺上幾盆小盆栽喚起一天的元氣，美觀又可創造出你的理想生活!\r\n書展中涵蓋了認識多肉，瞭解多肉植物名稱的由來，以及到入手多肉必備專業知識，包括購買原則、基質選擇、專用工具、盆器選擇，以及光照、溫度、澆水、通風、施肥、病蟲害防治、繁殖等養護技巧，指導製作多肉創意組合盆栽，面面俱到，為多肉植物的愛好者提供詳盡的培育知識。\r\n書展地點:南嵩分館\r\n書展日期:02/01(六)-02/27(四)', '臺中市立圖書館豐原南嵩分館', '臺中市豐原區臺中市豐原區水源路17巷2號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館豐原南嵩分館', 24.24990298, 120.7375715, '無資料', 'https://www.facebook.com/share/p/15DsHVCaq5/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='饗閱多肉植物療癒趣', `description`='擺上幾盆小盆栽喚起一天的元氣，美觀又可創造出你的理想生活!\r\n書展中涵蓋了認識多肉，瞭解多肉植物名稱的由來，以及到入手多肉必備專業知識，包括購買原則、基質選擇、專用工具、盆器選擇，以及光照、溫度、澆水、通風、施肥、病蟲害防治、繁殖等養護技巧，指導製作多肉創意組合盆栽，面面俱到，為多肉植物的愛好者提供詳盡的培育知識。\r\n書展地點:南嵩分館\r\n書展日期:02/01(六)-02/27(四)', `organizer`='臺中市立圖書館豐原南嵩分館', `address`='臺中市豐原區臺中市豐原區水源路17巷2號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館豐原南嵩分館', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/15DsHVCaq5/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655ed26b3240c403d96e3', '臺中市立圖書館北屯分館2月主題書展', '情緒主題書展是一個專注於探討情緒、心理健康與情感經歷的書籍展覽。這類書展通常會展示與情緒管理、心理治療、情感表達以及人際關係等相關的書籍和資源。目的是讓讀者更加了解自己和他人的情感世界，並通過書籍學習如何應對壓力、焦慮、抑鬱等情緒挑戰。', '臺中市立圖書館北屯分館', '臺中市北屯區', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '北屯區（臺中市）=', 24.18400298, 120.7362319, '無資料', 'https://reurl.cc/aZAQXZ', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館北屯分館2月主題書展', `description`='情緒主題書展是一個專注於探討情緒、心理健康與情感經歷的書籍展覽。這類書展通常會展示與情緒管理、心理治療、情感表達以及人際關係等相關的書籍和資源。目的是讓讀者更加了解自己和他人的情感世界，並通過書籍學習如何應對壓力、焦慮、抑鬱等情緒挑戰。', `organizer`='臺中市立圖書館北屯分館', `address`='臺中市北屯區', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='北屯區（臺中市）=', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://reurl.cc/aZAQXZ', `image_url`='[]';
