INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655ee26b3240c403d96e5', '大溪中正公園街頭藝人表演(114年2月)', '為提升觀光效益，活化藝文氣息，本處依桃園市政府風景區管理處轄管場地使用管理要點，特於假日期間安排街頭藝人於轄管場地進行流行歌曲彈唱展演。\r\n大溪相撲廣場(10-12/13-17)\r\n2月1日謝妙音\r\n2月2日羅文生\r\n2月9日黃明旺\r\n2月15日呂芳金\r\n2月16日李光榮\r\n2月22日趙秀蕊\r\n2月23日梁志o\r\n2月28日楊德雄\r\n大溪騎馬銅像廣場(10-12/13-17)\r\n2月1日趙秀蕊\r\n2月2日許朔羿\r\n2月9日王振鴻\r\n2月15日蔡政武\r\n2月16日宜誠\r\n2月22日黃宥棕\r\n2月23日陳慶泉\r\n2月28日吳禹萱\r\n大溪中正公園帆船區(10-12/13-17)\r\n2月1日鍾文瑞\r\n2月2日李建民\r\n2月9日鄭安育\r\n2月15日劉婉怡\r\n2月16日黃鼎力\r\n2月22日光榮\r\n2月23日耿嘉蕊\r\n2月28日曾淑芬\r\n', '桃園市政府風景區管理處', '桃園市大溪區--', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '桃園市大溪中正公園', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大溪中正公園街頭藝人表演(114年2月)', `description`='為提升觀光效益，活化藝文氣息，本處依桃園市政府風景區管理處轄管場地使用管理要點，特於假日期間安排街頭藝人於轄管場地進行流行歌曲彈唱展演。\r\n大溪相撲廣場(10-12/13-17)\r\n2月1日謝妙音\r\n2月2日羅文生\r\n2月9日黃明旺\r\n2月15日呂芳金\r\n2月16日李光榮\r\n2月22日趙秀蕊\r\n2月23日梁志o\r\n2月28日楊德雄\r\n大溪騎馬銅像廣場(10-12/13-17)\r\n2月1日趙秀蕊\r\n2月2日許朔羿\r\n2月9日王振鴻\r\n2月15日蔡政武\r\n2月16日宜誠\r\n2月22日黃宥棕\r\n2月23日陳慶泉\r\n2月28日吳禹萱\r\n大溪中正公園帆船區(10-12/13-17)\r\n2月1日鍾文瑞\r\n2月2日李建民\r\n2月9日鄭安育\r\n2月15日劉婉怡\r\n2月16日黃鼎力\r\n2月22日光榮\r\n2月23日耿嘉蕊\r\n2月28日曾淑芬\r\n', `organizer`='桃園市政府風景區管理處', `address`='桃園市大溪區--', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='桃園市大溪中正公園', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655ee26b3240c403d96e6', '拉拉山遊客中心街頭藝人表演(114年2月)', '為提升觀光效益，活化藝文氣息，本處依桃園市政府風景區管理處轄管場地使用管理要點，特於假日期間安排街頭藝人於轄管場地進行流行歌曲彈唱展演。', '桃園市政府風景區管理處', '桃園市復興區', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '復興區（桃園市）=', 24.72949884, 121.3754588, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='拉拉山遊客中心街頭藝人表演(114年2月)', `description`='為提升觀光效益，活化藝文氣息，本處依桃園市政府風景區管理處轄管場地使用管理要點，特於假日期間安排街頭藝人於轄管場地進行流行歌曲彈唱展演。', `organizer`='桃園市政府風景區管理處', `address`='桃園市復興區', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='復興區（桃園市）=', `latitude`=24.72949884, `longitude`=121.3754588, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655ef26b3240c403d96e7', '「作家的房間」特展：偽魚販指南之魚占卜之家', '從形形色色的魚市場，看盡人生的百態。本展覽邀約《偽魚販指南》的作者林楷倫，一同帶領讀者看見市場百態，以及魚販人生哲學的有趣體悟，展間內將展出書中章節〈偽裝魚販的指南〉文中魚販的穿著打扮介紹，還有有趣的「魚之占卜」──從魚販角度觀察體悟出形形色色的顧客心理。最後，展示林楷倫對家族的記憶，如二輪腳踏車….等，邀請大家探訪林楷倫的創作觀。\r\n\r\n\r\n\r\n策展人介紹\r\n\r\n林楷倫，1986年生，想像朋友寫作會的魚販。林榮三文學獎2020年短篇小說首獎、2021年三獎，時報文學獎2021年二獎、台北文學獎、台中文學獎等。著有「偽魚販指南」與新作「雪卡毒」。', '臺中市政府文化局', '臺中市西區樂群街38號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '臺中文學館', 24.1396799, 120.672764, '無資料', 'https://www.tlm.taichung.gov.tw/latestevent/Details.aspx?Parser=9,5,124,,,,1994', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「作家的房間」特展：偽魚販指南之魚占卜之家', `description`='從形形色色的魚市場，看盡人生的百態。本展覽邀約《偽魚販指南》的作者林楷倫，一同帶領讀者看見市場百態，以及魚販人生哲學的有趣體悟，展間內將展出書中章節〈偽裝魚販的指南〉文中魚販的穿著打扮介紹，還有有趣的「魚之占卜」──從魚販角度觀察體悟出形形色色的顧客心理。最後，展示林楷倫對家族的記憶，如二輪腳踏車….等，邀請大家探訪林楷倫的創作觀。\r\n\r\n\r\n\r\n策展人介紹\r\n\r\n林楷倫，1986年生，想像朋友寫作會的魚販。林榮三文學獎2020年短篇小說首獎、2021年三獎，時報文學獎2021年二獎、台北文學獎、台中文學獎等。著有「偽魚販指南」與新作「雪卡毒」。', `organizer`='臺中市政府文化局', `address`='臺中市西區樂群街38號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='臺中文學館', `latitude`=24.1396799, `longitude`=120.672764, `ticket_price`='無資料', `source_url`='https://www.tlm.taichung.gov.tw/latestevent/Details.aspx?Parser=9,5,124,,,,1994', `image_url`='[]';
