INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655f026b3240c403d96ea', '羊米人《無夢少年家》專輯巡迴大冒險', '2025 最熱血\r\n羊米人Yummy Man《無夢少年家》\r\n三月全台超展開！\r\n\r\n「我甘願按呢過一世人，這毋是失望只是希望會當永遠做所愛的夢。」\r\n\r\n《無夢少年家》以詼諧、叛逆、調皮的態度，挑戰世人定義的「媠氣人生」。\r\n鼓勵人們擺脫設定好的人生，擁抱夢想、勇敢去愛以及保持善良。', '迴響音樂藝文展演空間', '臺中市中區中山路108號', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '迴響音樂藝文展演空間', 24.14168566, 120.680598, '預售票+600;現場票+700;雙人套票+1000', 'https://www.facebook.com/photo?fbid=1146964896823374&set=a.714006010119267&locale=zh_TW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='羊米人《無夢少年家》專輯巡迴大冒險', `description`='2025 最熱血\r\n羊米人Yummy Man《無夢少年家》\r\n三月全台超展開！\r\n\r\n「我甘願按呢過一世人，這毋是失望只是希望會當永遠做所愛的夢。」\r\n\r\n《無夢少年家》以詼諧、叛逆、調皮的態度，挑戰世人定義的「媠氣人生」。\r\n鼓勵人們擺脫設定好的人生，擁抱夢想、勇敢去愛以及保持善良。', `organizer`='迴響音樂藝文展演空間', `address`='臺中市中區中山路108號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='迴響音樂藝文展演空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='預售票+600;現場票+700;雙人套票+1000', `source_url`='https://www.facebook.com/photo?fbid=1146964896823374&set=a.714006010119267&locale=zh_TW', `image_url`='[]';
