INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655f726b3240c403d96f3', '《讓思緒飄走 》2025林芷彤個展', '林芷彤，優雅細緻地在現瓷土與軟質介面的共舞，佐以文字或詩，放大了觀者個感官知覺，在作品之間，漫步進入到一處純粹的心境場域。\r\n\r\n展出者：林芷彤，陶藝家，有多場展覽參展經驗；如：2024年桃園「在黑幕前 -法國時期 林芷彤個展」。亦有多項得獎經驗，如：雲林文化藝術獎工藝類優選，與2023·花蓮洄瀾美展經點典媒材創作類立體造型組 銅獎，及2021年第五屆 桃園臺灣青年陶藝獎雙年展入選。更有多次國際藝術合作，如2022年參與法國藝術家 Laure Bréaud 行為藝術作品演出與錄像藝術作品製作。', '無資料', '桃園市龜山區復興一路8號3樓', '2025-02-07 00:00:00', '2025-03-16 00:00:00', '桃園A8藝文中心', 25.02417472, 121.3569265, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《讓思緒飄走 》2025林芷彤個展', `description`='林芷彤，優雅細緻地在現瓷土與軟質介面的共舞，佐以文字或詩，放大了觀者個感官知覺，在作品之間，漫步進入到一處純粹的心境場域。\r\n\r\n展出者：林芷彤，陶藝家，有多場展覽參展經驗；如：2024年桃園「在黑幕前 -法國時期 林芷彤個展」。亦有多項得獎經驗，如：雲林文化藝術獎工藝類優選，與2023·花蓮洄瀾美展經點典媒材創作類立體造型組 銅獎，及2021年第五屆 桃園臺灣青年陶藝獎雙年展入選。更有多次國際藝術合作，如2022年參與法國藝術家 Laure Bréaud 行為藝術作品演出與錄像藝術作品製作。', `organizer`='無資料', `address`='桃園市龜山區復興一路8號3樓', `start_date`='2025-02-07 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='桃園A8藝文中心', `latitude`=25.02417472, `longitude`=121.3569265, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655fa26b3240c403d96f4', 'Soundstatues《Special Acoustic Show》', '《Special Acoustic Show》\r\n展演者:Soundstatues\r\n時間:2025.03.02 (日) 1830\r\n地點:音浪塔1F 海邊的卡夫卡-高流店 Kafka by the Sea\r\n應眾多台灣聽眾的要求，Soundstatues即將重返台灣！\r\n樂團主打歌曲“Fade”和許多其它原作歌曲一樣，有幸成為台灣粉絲們的最愛。\r\n這場音樂會上Soundstatues 將用不插電的方式呈獻樂團的曲目。', '海邊的卡夫卡-高流店 Kafka by the Sea', '高雄市鹽埕區17鄰真愛路1號', '2025-03-02 00:00:00', '2025-03-02 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人預售票+350;當日現場票+400', 'https://kktix.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Soundstatues《Special Acoustic Show》', `description`='《Special Acoustic Show》\r\n展演者:Soundstatues\r\n時間:2025.03.02 (日) 1830\r\n地點:音浪塔1F 海邊的卡夫卡-高流店 Kafka by the Sea\r\n應眾多台灣聽眾的要求，Soundstatues即將重返台灣！\r\n樂團主打歌曲“Fade”和許多其它原作歌曲一樣，有幸成為台灣粉絲們的最愛。\r\n這場音樂會上Soundstatues 將用不插電的方式呈獻樂團的曲目。', `organizer`='海邊的卡夫卡-高流店 Kafka by the Sea', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人預售票+350;當日現場票+400', `source_url`='https://kktix.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655fa26b3240c403d96f5', 'CHANCE EMERSON：TAIWANESE TROUBADOUR TOUR - 高雄場', 'Chance Emerson 是一位台美混血的民謠搖滾歌手，目前定居於 USA，在 2025 年回來台灣展開巡迴演唱。\r\n\r\n他曾經為 Shakey Graves、Sam Barber、Vincent Lima、Blues Traveler、Brett Dennen、Eli Young Band、Johnnyswim、Lawrence，以及 Nancy Wilson’s Heart 等歌手的演唱會進行開場演出。他的最新張專輯《Ginkgo》也在各大音樂平台累積超過 300 萬次的播放。\r\n\r\nChance 很興奮因為他終於可以來台灣表演了，讓我們在現場見面吧！', '無資料', '高雄市鹽埕區17鄰真愛路1號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人預售票+500;現場票+600;雙人預售票+900', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='CHANCE EMERSON：TAIWANESE TROUBADOUR TOUR - 高雄場', `description`='Chance Emerson 是一位台美混血的民謠搖滾歌手，目前定居於 USA，在 2025 年回來台灣展開巡迴演唱。\r\n\r\n他曾經為 Shakey Graves、Sam Barber、Vincent Lima、Blues Traveler、Brett Dennen、Eli Young Band、Johnnyswim、Lawrence，以及 Nancy Wilson’s Heart 等歌手的演唱會進行開場演出。他的最新張專輯《Ginkgo》也在各大音樂平台累積超過 300 萬次的播放。\r\n\r\nChance 很興奮因為他終於可以來台灣表演了，讓我們在現場見面吧！', `organizer`='無資料', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人預售票+500;現場票+600;雙人預售票+900', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655fa26b3240c403d96f6', '偶又回來玩樂團！', '在夜黑風高的晚上\r\n\r\n瑪修獨自一人迷路在漆黑的森林\r\n\r\n走著走著看見了魔女與惡魔正在較勁歌喉\r\n\r\n愛唱歌的瑪修開心的加入她們的對決\r\n\r\n完全忘記自己正在迷路', '高雄流行音樂中心', '高雄市鹽埕區17鄰真愛路1號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '預售票+500;現場票+600', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='偶又回來玩樂團！', `description`='在夜黑風高的晚上\r\n\r\n瑪修獨自一人迷路在漆黑的森林\r\n\r\n走著走著看見了魔女與惡魔正在較勁歌喉\r\n\r\n愛唱歌的瑪修開心的加入她們的對決\r\n\r\n完全忘記自己正在迷路', `organizer`='高雄流行音樂中心', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='預售票+500;現場票+600', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655fa26b3240c403d96f7', '2025青春美展   「靈魂共振」－國立臺東大學美術產業學系114級畢業展', '「靈魂共振」是一場關於當代人類情感與心靈連結的探索。在數位化、全球化的今天，尤其是經歷了新冠疫情的Z世代，對於人際互動的需求與表達方式發生了深刻變化。\r\n本次展覽匯集了平面設計、數位媒體、影像藝術、立體雕塑、陶藝……等多種創作形式。這場展覽將帶領觀眾進入一場情感與藝術的深度對話，展現新世代藝術創作者的獨特視角和豐富創作。學生們透過多樣的藝術媒材，探討生命的記憶、時間的流動，甚至人與自然之間的微妙聯繫。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-04-04 00:00:00', '2025-04-15 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4090', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展   「靈魂共振」－國立臺東大學美術產業學系114級畢業展', `description`='「靈魂共振」是一場關於當代人類情感與心靈連結的探索。在數位化、全球化的今天，尤其是經歷了新冠疫情的Z世代，對於人際互動的需求與表達方式發生了深刻變化。\r\n本次展覽匯集了平面設計、數位媒體、影像藝術、立體雕塑、陶藝……等多種創作形式。這場展覽將帶領觀眾進入一場情感與藝術的深度對話，展現新世代藝術創作者的獨特視角和豐富創作。學生們透過多樣的藝術媒材，探討生命的記憶、時間的流動，甚至人與自然之間的微妙聯繫。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-04-04 00:00:00', `end_date`='2025-04-15 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4090', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655fa26b3240c403d96f8', '叩首 X 團結英雄會', '༺.𓋹 𝟤𝟢𝟤𝟧 叩首音樂祭 × 團結英雄會 𓋹.༻\r\n\r\n𝟸𝟶𝟸𝟻 𝔠𝔬𝔯𝔢𝔰𝔬𝔲𝔩 𝔪𝔢𝔱𝔞𝔩 𝔪𝔲𝔰𝔦𝔠 𝔣𝔢𝔰𝔱𝔦𝔳𝔞𝔩 × 𝔲𝔫𝔦𝔱𝔢𝔡 𝔥𝔢𝔯𝔬𝔰 𝔩𝔢𝔞𝔤𝔲𝔢 × 𝔟𝔞𝔫𝔞𝔫𝔞 𝔪𝔲𝔰𝔦𝔠 𝔥𝔞𝔩𝔩\r\n\r\n \r\n\r\n╋━━━━━━━━━━\r\n\r\n⚡ 弦動怒吼，金屬不息 ⚡\r\n\r\n━━━━━━━━━━━╋\r\n\r\n \r\n\r\n來自四方的英雄集結，共同締造一場前所未有的音樂革命。\r\n\r\n準備好在舞台前叩首，感受每一段狂放音波的轟炸，\r\n\r\n讓心中的熱血與每一聲弓弦的顫動同步燃燒！\r\n\r\n 🔥LIVE WAREHOUSE舞台\r\n\r\n \r\n\r\n這次，LIVE WAREHOUSE為金屬樂迷打造最震撼的沉浸式音樂體驗！\r\n\r\n最強的音響設備、最熱血的現場氛圍，帶來前所未有的靈魂衝擊！\r\n\r\n讓我們在LIVE WAREHOUSE的舞台上，見證每一次音波炸裂的瞬間！\r\n\r\n \r\n\r\n🔥Banana音樂館舞台\r\n\r\n為熱血學生打造免費的舞台！這是叩首音樂祭中的自由角落，給予學生們一個露出鋒芒的機會，點燃觀眾的靈魂！\r\n\r\n \r\n\r\n來吧，準備好迎接那場撼動心靈的重擊！\r\n\r\n一同加入這場震撼的祭典，讓我們在音符中團結，以旋律為劍，\r\n\r\n叩響靈魂深處的共鳴！⋆✴˚｡⋆', '高雄流行音樂中心', '高雄市鹽埕區17鄰真愛路1號', '2025-05-16 00:00:00', '2025-05-17 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '小庫單人票+800;大庫單人票+1300;通行單人票+1800;現場通行票+2100;通行四人套票（限量）+6660', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='叩首 X 團結英雄會', `description`='༺.𓋹 𝟤𝟢𝟤𝟧 叩首音樂祭 × 團結英雄會 𓋹.༻\r\n\r\n𝟸𝟶𝟸𝟻 𝔠𝔬𝔯𝔢𝔰𝔬𝔲𝔩 𝔪𝔢𝔱𝔞𝔩 𝔪𝔲𝔰𝔦𝔠 𝔣𝔢𝔰𝔱𝔦𝔳𝔞𝔩 × 𝔲𝔫𝔦𝔱𝔢𝔡 𝔥𝔢𝔯𝔬𝔰 𝔩𝔢𝔞𝔤𝔲𝔢 × 𝔟𝔞𝔫𝔞𝔫𝔞 𝔪𝔲𝔰𝔦𝔠 𝔥𝔞𝔩𝔩\r\n\r\n \r\n\r\n╋━━━━━━━━━━\r\n\r\n⚡ 弦動怒吼，金屬不息 ⚡\r\n\r\n━━━━━━━━━━━╋\r\n\r\n \r\n\r\n來自四方的英雄集結，共同締造一場前所未有的音樂革命。\r\n\r\n準備好在舞台前叩首，感受每一段狂放音波的轟炸，\r\n\r\n讓心中的熱血與每一聲弓弦的顫動同步燃燒！\r\n\r\n 🔥LIVE WAREHOUSE舞台\r\n\r\n \r\n\r\n這次，LIVE WAREHOUSE為金屬樂迷打造最震撼的沉浸式音樂體驗！\r\n\r\n最強的音響設備、最熱血的現場氛圍，帶來前所未有的靈魂衝擊！\r\n\r\n讓我們在LIVE WAREHOUSE的舞台上，見證每一次音波炸裂的瞬間！\r\n\r\n \r\n\r\n🔥Banana音樂館舞台\r\n\r\n為熱血學生打造免費的舞台！這是叩首音樂祭中的自由角落，給予學生們一個露出鋒芒的機會，點燃觀眾的靈魂！\r\n\r\n \r\n\r\n來吧，準備好迎接那場撼動心靈的重擊！\r\n\r\n一同加入這場震撼的祭典，讓我們在音符中團結，以旋律為劍，\r\n\r\n叩響靈魂深處的共鳴！⋆✴˚｡⋆', `organizer`='高雄流行音樂中心', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-05-16 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='小庫單人票+800;大庫單人票+1300;通行單人票+1800;現場通行票+2100;通行四人套票（限量）+6660', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655fa26b3240c403d96f9', '114年前鎮分館Fun心聽故事活動(3月)', '由本館故事達人藉由說繪本故事，陪伴孩子們進入閱讀世界中，進而培養兒童閱讀的習慣與興趣，奠定良好的學習基礎。', '高雄市立圖書館總館', '高雄市前鎮區保泰路303號4樓', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館前鎮分館', 22.602476, 120.333005, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年前鎮分館Fun心聽故事活動(3月)', `description`='由本館故事達人藉由說繪本故事，陪伴孩子們進入閱讀世界中，進而培養兒童閱讀的習慣與興趣，奠定良好的學習基礎。', `organizer`='高雄市立圖書館總館', `address`='高雄市前鎮區保泰路303號4樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館前鎮分館', `latitude`=22.602476, `longitude`=120.333005, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655fb26b3240c403d96fa', '2025青春美展 觀測漫遊－實踐大學高雄校區電腦動畫學士學位學程青春美展', '本學程創立於民國105年，以培養國際專業動畫人才為目標，將動畫作為本體，資訊科技為工具，設計整合為目標，培育具有美學素養與創意設計能力的動畫設計人才，此次畢業展以「漫遊宇宙」作為發想中心，將觀眾帶入觀測者的視角，為了將人類的歷史以及精神流傳下去，獨自一人身兼重擔，日以繼夜以專業動畫守護人的意識，帶著對未來的期待，在浩瀚的宇宙中航行。', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-05-02 00:00:00', '2025-05-13 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4096', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展 觀測漫遊－實踐大學高雄校區電腦動畫學士學位學程青春美展', `description`='本學程創立於民國105年，以培養國際專業動畫人才為目標，將動畫作為本體，資訊科技為工具，設計整合為目標，培育具有美學素養與創意設計能力的動畫設計人才，此次畢業展以「漫遊宇宙」作為發想中心，將觀眾帶入觀測者的視角，為了將人類的歷史以及精神流傳下去，獨自一人身兼重擔，日以繼夜以專業動畫守護人的意識，帶著對未來的期待，在浩瀚的宇宙中航行。', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-02 00:00:00', `end_date`='2025-05-13 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4096', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655fb26b3240c403d96fb', '主題書展2月份', '書展主題：情人節\r\n浪漫書香，愛在每一頁！\r\n來自心靈的愛，流淌在書頁上。在這個充滿愛意的情人節，讓書籍成為您心中的那份深情。無論是愛情故事、詩集，還是浪漫小說，每本書都承載著不一樣的感動與驚喜，陪伴您和心愛的人一同享受這個特別的日子。', '桃園市立圖書館', '桃園市大溪區康莊路641號 (大溪高中勤學樓1樓)', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '桃園市立圖書館康莊分館', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='主題書展2月份', `description`='書展主題：情人節\r\n浪漫書香，愛在每一頁！\r\n來自心靈的愛，流淌在書頁上。在這個充滿愛意的情人節，讓書籍成為您心中的那份深情。無論是愛情故事、詩集，還是浪漫小說，每本書都承載著不一樣的感動與驚喜，陪伴您和心愛的人一同享受這個特別的日子。', `organizer`='桃園市立圖書館', `address`='桃園市大溪區康莊路641號 (大溪高中勤學樓1樓)', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='桃園市立圖書館康莊分館', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655ff26b3240c403d96fe', 'Hear a Pin Drop 林詩硯個展', 'Hear a Pin Drop 林詩硯個展\r\n​\r\n⟣展覽日期：2025.2.22(六)-2025.3.24(一) \r\n⟣地點：好地下藝術空間(花蓮市節約街37號B1) \r\n⟣開放時間：每周五、六、日、一 12:00-20:00 \r\n⟣開幕茶會：2025.2.22(六)14:00-15:00\r\n​\r\n​\r\n​\r\n【展覽簡介】\r\n​\r\n在生命的旅途中，我們或許都曾經面臨過痛苦的幽谷，而藝術有時便是那微弱卻深刻的光芒，引導我們穿越黑暗。林詩硯的首部作品《Hear a Pin Drop》，帶領我們進入一個不輕易被人提起的領域：自傷者的生命故事。\r\n​\r\n林詩硯，1991年生於台北，2020年取得東京藝術大學先端藝術碩士學位，畢業後留校擔任攝影中心助教。自2021年起，她透過精神健康互助網站募集自傷經驗者，展開了一場橫跨日本各地的拍攝計畫，歷時三年半。這項創作源自林詩硯自身的生命經驗，她嘗試透過攝影探索心中多年的疑問：自傷的行為背後是什麼樣難以言說的心理狀態？是對生命的拒絕，還是渴望？\r\n​\r\n詩硯以極大的耐心處理與被攝者之間的關係。在拍攝前，她透過電子郵件與被攝者溝通，討論拍攝時間與地點，並研究當地氣象。碰面時，她總是花時間聊天，專心聆聽他們的故事，等對方感到放鬆後才開始拍照。這份溫柔的不僅是人際互動，更是她與每位被攝者建立信任的過程。每一次的拍攝，詩硯都像是一位默默的陪伴者，用影像將那未曾說出又的感受留下。\r\n​\r\n​\r\n​\r\n【展期活動】 ​ \r\n​\r\n座談➀｜2025.2.22(六) 15:00-16:30\r\n與談人：杜韻飛(藝術家)、林詩硯(藝術家)、羅惠瑜(策展人)\r\n​\r\n以攝影為主要創作媒材的藝術家杜韻飛，曾在拍攝安樂死流浪犬最後身影的作品《生殤相》介紹中寫：「看見他者，就是看見自己。」面對自己以外的生命，攝影家在觀景窗背後各自露出什麼樣的眼光？透過鏡頭，我們又在他者的臉上看見什麼？\r\n​\r\n​\r\n座談➁｜2025.3.15(六) 14:00-16:00　\r\n講題：朝向一本攝影書的完成\r\n與談人：林詩硯(藝術家)、根本匠(設計師)　\r\n日文口譯：侯鵬暉(國立臺灣海洋大學海洋文創設計產業學系助理教授)\r\n​\r\n從櫻桃子到吉田戰車再到金滿里，橫跨藝文各領域的日本書籍設計師根本匠面對好友的第一本攝影書，給了一個乾淨簡樸的答案。\r\n設計師和作者聊《針の落ちる音》的誕生：他如何將第一次看到作品的感受轉化為實體，並以什麼樣的姿態介入到作者與讀者之間？\r\n​\r\n​\r\n​\r\n【藝術家簡介】\r\n​\r\n林詩硯 Lin Shihyen\r\n​\r\n攝影師林詩硯2020年取得東京藝術大學先端藝術表現碩士學位，2020-2024年間於東京藝術大學攝影中心擔任教育研究助手。曾於新宿Totempole Photo Gallery、新宿 Nikon Salon、京都 Purple 等畫廊舉辦個展。2021 年入選為 Portrait of Japan 與 IMA next "Memory" 代表；2023 年榮獲第 3 屆 PITCH GRANT 大獎；2024年於赤赤舍出版《針の落ちる音》攝影書，並以此書榮獲2024年第24回攝影都市相模原攝影新人獎。\r\n​\r\n​\r\n⟣海報設計：根本匠', '好地下藝術空間', '花蓮縣花蓮市節約街37號B1', '2025-02-22 00:00:00', '2025-03-24 00:00:00', '好地下藝術空間', 23.99700271, 121.6071463, '無資料', 'https://www.facebook.com/goodunderground/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Hear a Pin Drop 林詩硯個展', `description`='Hear a Pin Drop 林詩硯個展\r\n​\r\n⟣展覽日期：2025.2.22(六)-2025.3.24(一) \r\n⟣地點：好地下藝術空間(花蓮市節約街37號B1) \r\n⟣開放時間：每周五、六、日、一 12:00-20:00 \r\n⟣開幕茶會：2025.2.22(六)14:00-15:00\r\n​\r\n​\r\n​\r\n【展覽簡介】\r\n​\r\n在生命的旅途中，我們或許都曾經面臨過痛苦的幽谷，而藝術有時便是那微弱卻深刻的光芒，引導我們穿越黑暗。林詩硯的首部作品《Hear a Pin Drop》，帶領我們進入一個不輕易被人提起的領域：自傷者的生命故事。\r\n​\r\n林詩硯，1991年生於台北，2020年取得東京藝術大學先端藝術碩士學位，畢業後留校擔任攝影中心助教。自2021年起，她透過精神健康互助網站募集自傷經驗者，展開了一場橫跨日本各地的拍攝計畫，歷時三年半。這項創作源自林詩硯自身的生命經驗，她嘗試透過攝影探索心中多年的疑問：自傷的行為背後是什麼樣難以言說的心理狀態？是對生命的拒絕，還是渴望？\r\n​\r\n詩硯以極大的耐心處理與被攝者之間的關係。在拍攝前，她透過電子郵件與被攝者溝通，討論拍攝時間與地點，並研究當地氣象。碰面時，她總是花時間聊天，專心聆聽他們的故事，等對方感到放鬆後才開始拍照。這份溫柔的不僅是人際互動，更是她與每位被攝者建立信任的過程。每一次的拍攝，詩硯都像是一位默默的陪伴者，用影像將那未曾說出又的感受留下。\r\n​\r\n​\r\n​\r\n【展期活動】 ​ \r\n​\r\n座談➀｜2025.2.22(六) 15:00-16:30\r\n與談人：杜韻飛(藝術家)、林詩硯(藝術家)、羅惠瑜(策展人)\r\n​\r\n以攝影為主要創作媒材的藝術家杜韻飛，曾在拍攝安樂死流浪犬最後身影的作品《生殤相》介紹中寫：「看見他者，就是看見自己。」面對自己以外的生命，攝影家在觀景窗背後各自露出什麼樣的眼光？透過鏡頭，我們又在他者的臉上看見什麼？\r\n​\r\n​\r\n座談➁｜2025.3.15(六) 14:00-16:00　\r\n講題：朝向一本攝影書的完成\r\n與談人：林詩硯(藝術家)、根本匠(設計師)　\r\n日文口譯：侯鵬暉(國立臺灣海洋大學海洋文創設計產業學系助理教授)\r\n​\r\n從櫻桃子到吉田戰車再到金滿里，橫跨藝文各領域的日本書籍設計師根本匠面對好友的第一本攝影書，給了一個乾淨簡樸的答案。\r\n設計師和作者聊《針の落ちる音》的誕生：他如何將第一次看到作品的感受轉化為實體，並以什麼樣的姿態介入到作者與讀者之間？\r\n​\r\n​\r\n​\r\n【藝術家簡介】\r\n​\r\n林詩硯 Lin Shihyen\r\n​\r\n攝影師林詩硯2020年取得東京藝術大學先端藝術表現碩士學位，2020-2024年間於東京藝術大學攝影中心擔任教育研究助手。曾於新宿Totempole Photo Gallery、新宿 Nikon Salon、京都 Purple 等畫廊舉辦個展。2021 年入選為 Portrait of Japan 與 IMA next "Memory" 代表；2023 年榮獲第 3 屆 PITCH GRANT 大獎；2024年於赤赤舍出版《針の落ちる音》攝影書，並以此書榮獲2024年第24回攝影都市相模原攝影新人獎。\r\n​\r\n​\r\n⟣海報設計：根本匠', `organizer`='好地下藝術空間', `address`='花蓮縣花蓮市節約街37號B1', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-24 00:00:00', `location`='好地下藝術空間', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='無資料', `source_url`='https://www.facebook.com/goodunderground/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b655ff26b3240c403d96ff', '【導覽】東亞茶文化', '東亞茶文化—專廳導覽\r\n場次/展廳：\r\n主講人：鄭涵云；國立故宮博物院南院處助理研究員\r\n每場20人，當日開放報名，額滿為止', '國立故宮博物院', '嘉義縣太保市故宮大道888號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '國立故宮博物院南部院區', 23.4704066, 120.2913281, '全票+150', 'https://south.npm.gov.tw/ActivityInfoDetailC003210.aspx?Cond=d3cf127e-6058-4667-bdce-2c469e09ed90&ap', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【導覽】東亞茶文化', `description`='東亞茶文化—專廳導覽\r\n場次/展廳：\r\n主講人：鄭涵云；國立故宮博物院南院處助理研究員\r\n每場20人，當日開放報名，額滿為止', `organizer`='國立故宮博物院', `address`='嘉義縣太保市故宮大道888號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='國立故宮博物院南部院區', `latitude`=23.4704066, `longitude`=120.2913281, `ticket_price`='全票+150', `source_url`='https://south.npm.gov.tw/ActivityInfoDetailC003210.aspx?Cond=d3cf127e-6058-4667-bdce-2c469e09ed90&ap', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d9700', '南投縣青溪會員聯展', '南投縣青溪新文藝學會宗旨係為配合國家文化建設，普及文藝教育，倡導美育活動為主；透過會員們旺盛的創作企圖心，帶動了全民參與藝文的風尚。每年辦理的青溪美展，在歷任理事長及現任理事長陳勇穆的帶領之下，從展覽籌辦到出版專輯，累積多年已有豐碩成果，使青溪成為地方推動藝文活動的主要團體之一。本次美展將邀請現任會員與資深顧問，提供最新的創作共同參展，展現創作能量，也為南投縣的文化藝術傳承，持續寫下新的篇章。\r\n開幕式：3月2日(日)10:00', '南投縣政府', '南投縣南投市建國路135號', '2025-03-01 00:00:00', '2025-03-12 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南投縣青溪會員聯展', `description`='南投縣青溪新文藝學會宗旨係為配合國家文化建設，普及文藝教育，倡導美育活動為主；透過會員們旺盛的創作企圖心，帶動了全民參與藝文的風尚。每年辦理的青溪美展，在歷任理事長及現任理事長陳勇穆的帶領之下，從展覽籌辦到出版專輯，累積多年已有豐碩成果，使青溪成為地方推動藝文活動的主要團體之一。本次美展將邀請現任會員與資深顧問，提供最新的創作共同參展，展現創作能量，也為南投縣的文化藝術傳承，持續寫下新的篇章。\r\n開幕式：3月2日(日)10:00', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-12 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d9701', '山海．生活-莊國賓油彩個展', '作品曾獲公教美展免審查（1995～1997連續三年前三名）、教育部文藝創作獎、青溪文藝金環獎、銀像獎，多次入選台北市美展、高雄市美展、全國美展。是一位攀登百岳的高山嚮導，也是一位能駕船航行大海的船長，一生迷戀著台灣海島的大山大海，我不是在山上就是在海上的生活，饋予他生命溫柔的律動、深情渾厚的凝視，提供他豐富多樣的創作元素。透過油畫、水彩和各種媒材運用，在作品中呈現多元化的表現形式，表達出他對山與海的深深依戀。\r\n茶敘：3月2日(日)14:30', '南投縣政府', '南投縣南投市建國路135號', '2025-03-01 00:00:00', '2025-03-12 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='山海．生活-莊國賓油彩個展', `description`='作品曾獲公教美展免審查（1995～1997連續三年前三名）、教育部文藝創作獎、青溪文藝金環獎、銀像獎，多次入選台北市美展、高雄市美展、全國美展。是一位攀登百岳的高山嚮導，也是一位能駕船航行大海的船長，一生迷戀著台灣海島的大山大海，我不是在山上就是在海上的生活，饋予他生命溫柔的律動、深情渾厚的凝視，提供他豐富多樣的創作元素。透過油畫、水彩和各種媒材運用，在作品中呈現多元化的表現形式，表達出他對山與海的深深依戀。\r\n茶敘：3月2日(日)14:30', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-12 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d9702', '清流畫會聯展', '由一群亦師亦友之藝術工作者，為促進彼此交流，提升繪畫品質而成立，多年來以「志於道，據於德，依於仁，游於藝」之宗旨推展水墨藝術，並以追求東方繪畫為內涵。目前有會員77人來自全省各地，包含大專院校、公教人員及社會人士，除潛心藝術創作且相互交流，會員舉辦個展、出版專輯或參加過國內外各項美展屢獲佳績，多方位的發展表現不僅促使各地方藝術活動活絡，更在美術教育工作上默默耕耘，肩負起承先啟後的藝術傳承重責，透過持續推行美育活動，吸引全民參與藝文欣賞、創作、研究，進而提高文化水平，改善社會風氣，充實文化精神休閒領域，並提升地方的藝文發展，備受各界肯定。', '南投縣政府', '南投縣南投市建國路135號', '2025-03-01 00:00:00', '2025-03-12 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='清流畫會聯展', `description`='由一群亦師亦友之藝術工作者，為促進彼此交流，提升繪畫品質而成立，多年來以「志於道，據於德，依於仁，游於藝」之宗旨推展水墨藝術，並以追求東方繪畫為內涵。目前有會員77人來自全省各地，包含大專院校、公教人員及社會人士，除潛心藝術創作且相互交流，會員舉辦個展、出版專輯或參加過國內外各項美展屢獲佳績，多方位的發展表現不僅促使各地方藝術活動活絡，更在美術教育工作上默默耕耘，肩負起承先啟後的藝術傳承重責，透過持續推行美育活動，吸引全民參與藝文欣賞、創作、研究，進而提高文化水平，改善社會風氣，充實文化精神休閒領域，並提升地方的藝文發展，備受各界肯定。', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-12 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d9703', '畫墨遊藝-台中市榮美藝文傳承協會聯展', '由一群對中華文化書畫藝術同好所共同籌組而成，成員有軍公教退休人員及公司行號等社會人士等，每位成員均對書畫藝術抱持學習鑽研與喜愛的態度，廣結藝術善緣推動書畫藝術的社會活動，將藝文活動帶入生活傳承古人對書畫藝術的尊榮，推廣光大藝文的精神文明生活，改善社會生氣平衡物質與精神生活的和諧，一同切磋藝文素養雅俗共賞為理想目標。', '南投縣政府', '南投縣南投市建國路135號', '2025-03-15 00:00:00', '2025-03-26 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='畫墨遊藝-台中市榮美藝文傳承協會聯展', `description`='由一群對中華文化書畫藝術同好所共同籌組而成，成員有軍公教退休人員及公司行號等社會人士等，每位成員均對書畫藝術抱持學習鑽研與喜愛的態度，廣結藝術善緣推動書畫藝術的社會活動，將藝文活動帶入生活傳承古人對書畫藝術的尊榮，推廣光大藝文的精神文明生活，改善社會生氣平衡物質與精神生活的和諧，一同切磋藝文素養雅俗共賞為理想目標。', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d9704', '心境。日誌', '此展是由國立臺南大學視覺藝術學系與國立東華大學藝術與設計學系兩校碩士班學生自發性組成之展出，由藝術家與自己內心的日常談話，像日誌般紀錄日常瑣事，不管是生活片段、瑣碎的事情，都可經由自身體悟及情感寄託在作品上傳達給觀眾。\r\n花蓮與臺南相隔373公里，這是場前後山跨距的展覽盛宴，期共同打造、碰撞出不同以往的藝術創作。本展內容多元，包含石雕、版畫、平面繪畫、工筆、篆刻等。在這裡，透過作品詮釋對生命的感悟和內心的情感寄託於藝術之中，期能與您一起分享那微妙而真摯的心靈共鳴。或許在這些作品的交融中，我們都能尋得一種默契，讓彼此的心境在此刻達到連結與沉靜。', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-02-06 00:00:00', '2025-03-09 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='心境。日誌', `description`='此展是由國立臺南大學視覺藝術學系與國立東華大學藝術與設計學系兩校碩士班學生自發性組成之展出，由藝術家與自己內心的日常談話，像日誌般紀錄日常瑣事，不管是生活片段、瑣碎的事情，都可經由自身體悟及情感寄託在作品上傳達給觀眾。\r\n花蓮與臺南相隔373公里，這是場前後山跨距的展覽盛宴，期共同打造、碰撞出不同以往的藝術創作。本展內容多元，包含石雕、版畫、平面繪畫、工筆、篆刻等。在這裡，透過作品詮釋對生命的感悟和內心的情感寄託於藝術之中，期能與您一起分享那微妙而真摯的心靈共鳴。或許在這些作品的交融中，我們都能尋得一種默契，讓彼此的心境在此刻達到連結與沉靜。', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-02-06 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d9705', '以家之名-柯適中一家畫展', '柯耀東(1933－2021)為國寶級書畫家，出生於草屯石頭埔的農家，早年於戲院畫電影看板，與戲院千金郭皆貴結為連理，成為鄉里佳話。1963年開始於手工藝研習所（台灣工藝研究發展中心前身）擔任公職服務至退休。曾多次參與美展比賽獲得佳績，國內外展覽無數，並創立九九美術學會，亦是南投縣美術學會的創會會員，帶動南投藝文風氣，造福後進，榮獲南投縣玉山美術貢獻獎。  \r\n郭皆貴（1939－2018）從小即被譽為才女，婚後與柯耀東於創作上相互切磋，常一起舉辦聯展。郭皆貴早期擅畫仕女、人物畫，而後專攻花鳥，柯耀東評自己「畫山畫水」，郭皆貴「畫花畫蕊」，即是兩人指在創作上各自的偏愛。\r\n柯適中1966年生畢業於國立藝專（今國立台灣藝術學院）美國芳邦大學藝術碩士，曾任教育南開科技大學文化創意設計系教授，以及藝術中心主任。國內比賽獲獎無數，並擔任全國美展，大墩美展，全國白號油畫展，以及玉山美展評審等。創作風格早期以風景為主而今轉換偏向表現主意，以及超現實與象徵風格。\r\n開幕式：3月15日(六)14:30', '南投縣政府', '南投縣南投市建國路135號', '2025-03-15 00:00:00', '2025-03-26 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='以家之名-柯適中一家畫展', `description`='柯耀東(1933－2021)為國寶級書畫家，出生於草屯石頭埔的農家，早年於戲院畫電影看板，與戲院千金郭皆貴結為連理，成為鄉里佳話。1963年開始於手工藝研習所（台灣工藝研究發展中心前身）擔任公職服務至退休。曾多次參與美展比賽獲得佳績，國內外展覽無數，並創立九九美術學會，亦是南投縣美術學會的創會會員，帶動南投藝文風氣，造福後進，榮獲南投縣玉山美術貢獻獎。  \r\n郭皆貴（1939－2018）從小即被譽為才女，婚後與柯耀東於創作上相互切磋，常一起舉辦聯展。郭皆貴早期擅畫仕女、人物畫，而後專攻花鳥，柯耀東評自己「畫山畫水」，郭皆貴「畫花畫蕊」，即是兩人指在創作上各自的偏愛。\r\n柯適中1966年生畢業於國立藝專（今國立台灣藝術學院）美國芳邦大學藝術碩士，曾任教育南開科技大學文化創意設計系教授，以及藝術中心主任。國內比賽獲獎無數，並擔任全國美展，大墩美展，全國白號油畫展，以及玉山美展評審等。創作風格早期以風景為主而今轉換偏向表現主意，以及超現實與象徵風格。\r\n開幕式：3月15日(六)14:30', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d9706', '「LISTEN MY HEART」林小南創作個展', '而身為一個民謠歌手，林小南的個人藝術創作將生活中垂手可得的吉他與鋼琴作為基本創作題材，創造出鋼琴葉、鋼琴花、吉他鳥、和弦屋等音樂元素，或切割或解構與音符融入大自然裡，形成林小南獨特的繪畫語言與高辨識度的藝術符碼。音樂是有聲的繪畫，繪畫是無聲的音樂，在她半抽象的畫裡交融迴盪。\r\n林小南表示藝術創作對她的存在意義為：『透過美好的正能量傳導世界的良善，願世界和善能長存。Listen My Heart 包括遊歷花蓮山水後的最新創作，以及喚醒和向大師致敬的微系列，希望觀展的民眾能從我的畫作中聽見我內心對藝術的熱情。』這次個展作品將3年來地沈潛轉化成多元化創作視野，呈現讓人眼睛為之一亮的嶄新畫風與概念。', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-02-06 00:00:00', '2025-03-09 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「LISTEN MY HEART」林小南創作個展', `description`='而身為一個民謠歌手，林小南的個人藝術創作將生活中垂手可得的吉他與鋼琴作為基本創作題材，創造出鋼琴葉、鋼琴花、吉他鳥、和弦屋等音樂元素，或切割或解構與音符融入大自然裡，形成林小南獨特的繪畫語言與高辨識度的藝術符碼。音樂是有聲的繪畫，繪畫是無聲的音樂，在她半抽象的畫裡交融迴盪。\r\n林小南表示藝術創作對她的存在意義為：『透過美好的正能量傳導世界的良善，願世界和善能長存。Listen My Heart 包括遊歷花蓮山水後的最新創作，以及喚醒和向大師致敬的微系列，希望觀展的民眾能從我的畫作中聽見我內心對藝術的熱情。』這次個展作品將3年來地沈潛轉化成多元化創作視野，呈現讓人眼睛為之一亮的嶄新畫風與概念。', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-02-06 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d9707', '柯廷個展', '柯廷（1997－）為北藝大美術系畢業後，又取得英國金斯頓大學（Kingston University）插畫碩士學位，是以超現實魔幻風格聞名的刺青師。', '南投縣政府', '南投縣南投市建國路135號', '2025-03-15 00:00:00', '2025-03-26 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='柯廷個展', `description`='柯廷（1997－）為北藝大美術系畢業後，又取得英國金斯頓大學（Kingston University）插畫碩士學位，是以超現實魔幻風格聞名的刺青師。', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d9708', '「行走光影 意象生動」攝影聯展', '攝影是記錄美的物相，美是心靈共鳴及和諧的感覺，我們沉浸在美的領域，感受大自然季節的變化，聆聽藝術的召喚，是心靈最富有的一群。一張好照片，是活的！不管是天地間的大美，人文的幽默、生命的強韌，每張照片都是攝影師揹著沉重的裝備追、趕、跑、跳、碰，和運氣賭博；每張照片都是在冷露中通宵深情的守候，深怕錯過而產生遺憾。每張照片都考驗著攝影師的眼光與美感。\r\n一個傑出的攝影師，他得先是個「擅長說故事」的專家。一個會說故事的攝影師，無論對象是人、物或風景，都懂得透過心與眼，看出誰是鏡頭下真正的主角，而自己想要鋪排怎樣的故事情節，掌握了靈光一現的想法，在按下快門那一剎那，才能成功拍出心中理想的照片。', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-02-06 00:00:00', '2025-03-09 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「行走光影 意象生動」攝影聯展', `description`='攝影是記錄美的物相，美是心靈共鳴及和諧的感覺，我們沉浸在美的領域，感受大自然季節的變化，聆聽藝術的召喚，是心靈最富有的一群。一張好照片，是活的！不管是天地間的大美，人文的幽默、生命的強韌，每張照片都是攝影師揹著沉重的裝備追、趕、跑、跳、碰，和運氣賭博；每張照片都是在冷露中通宵深情的守候，深怕錯過而產生遺憾。每張照片都考驗著攝影師的眼光與美感。\r\n一個傑出的攝影師，他得先是個「擅長說故事」的專家。一個會說故事的攝影師，無論對象是人、物或風景，都懂得透過心與眼，看出誰是鏡頭下真正的主角，而自己想要鋪排怎樣的故事情節，掌握了靈光一現的想法，在按下快門那一剎那，才能成功拍出心中理想的照片。', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-02-06 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d9709', '陳淑欣個展', '陳淑欣主要從事藝術教育，新竹教育大學美勞教學碩士畢業後，於國小擔任美術教師至今，2021年又取得台南藝術大學應用藝術研究所纖維組碩士，投入纖維藝術創作，擅長以織品為主的複合媒材立體表現。', '南投縣政府', '南投縣南投市建國路135號', '2025-03-15 00:00:00', '2025-03-26 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陳淑欣個展', `description`='陳淑欣主要從事藝術教育，新竹教育大學美勞教學碩士畢業後，於國小擔任美術教師至今，2021年又取得台南藝術大學應用藝術研究所纖維組碩士，投入纖維藝術創作，擅長以織品為主的複合媒材立體表現。', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d970a', '有藝思-南投縣漳和國小美術班畢業成果展', '今年為第七屆畢業生辦理畢業成果展，是四年來學習結晶的展現。此次展覽的作品類別琳瑯滿目，包括平面藝術創作的素描、彩畫、水墨、版畫、油畫、書法等；立體藝術創作的紙藝、陶藝、拼布、木工、3D列印、雷射雕刻、大型集體創作等。學生的創作來源也許是來自對週遭環境的觀察，也許是對生活經歷的體悟，又或者純粹是天馬行空的想像，無論如何，藝術已成為他們生活不可或缺的一角，落實了「有藝思-在藝術中找到趣味」的理念，請大家細細欣賞他們如何用畫筆讓自己的小學階段變得更多采多姿。\r\n開幕式：3月29日(六)10:00', '南投縣政府', '南投縣南投市建國路135號', '2025-03-29 00:00:00', '2025-04-09 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='有藝思-南投縣漳和國小美術班畢業成果展', `description`='今年為第七屆畢業生辦理畢業成果展，是四年來學習結晶的展現。此次展覽的作品類別琳瑯滿目，包括平面藝術創作的素描、彩畫、水墨、版畫、油畫、書法等；立體藝術創作的紙藝、陶藝、拼布、木工、3D列印、雷射雕刻、大型集體創作等。學生的創作來源也許是來自對週遭環境的觀察，也許是對生活經歷的體悟，又或者純粹是天馬行空的想像，無論如何，藝術已成為他們生活不可或缺的一角，落實了「有藝思-在藝術中找到趣味」的理念，請大家細細欣賞他們如何用畫筆讓自己的小學階段變得更多采多姿。\r\n開幕式：3月29日(六)10:00', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-09 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d970b', '茹初之光-莊秀茹水彩個展', '莊秀茹南投縣草屯鎮人，水彩畫作曾入選台陽美術獎、台中市大墩美術獎及玉山美術獎等，創作皆來自生活美的感受，水彩顏料的渲染碰撞與光影互動表現出畫作的生動自然。\r\n開幕式：3月29日(六)13:30', '南投縣政府', '南投縣南投市建國路135號', '2025-03-29 00:00:00', '2025-04-09 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='茹初之光-莊秀茹水彩個展', `description`='莊秀茹南投縣草屯鎮人，水彩畫作曾入選台陽美術獎、台中市大墩美術獎及玉山美術獎等，創作皆來自生活美的感受，水彩顏料的渲染碰撞與光影互動表現出畫作的生動自然。\r\n開幕式：3月29日(六)13:30', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-09 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d970c', '復興崗書畫會聯展', '復興崗書畫會由臺北海洋科技大學副校長陳合成教授於民國110年肇造。本會初創成員均為國防大學政戰學院藝術系校友，係凝聚志同道合的水墨、書法、油畫精英15人所組成。畫會除聯繫會員情誼，倡導美術交流活動及弘揚藝文外，秉持互相切磋砥礪的精神，從關愛社會、擁抱人群的人文關懷，以展現多元兼具的創作理念，發揚各自擅長的創新特色風格為主軸。會員作品從道法自然到融合作者內心情感，進一步想鏈結到觀賞者，盼本次聯展能提供南投縣民一場具有同頻共鳴節奏美的饗宴。', '南投縣政府', '南投縣南投市建國路135號', '2025-03-29 00:00:00', '2025-04-09 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='復興崗書畫會聯展', `description`='復興崗書畫會由臺北海洋科技大學副校長陳合成教授於民國110年肇造。本會初創成員均為國防大學政戰學院藝術系校友，係凝聚志同道合的水墨、書法、油畫精英15人所組成。畫會除聯繫會員情誼，倡導美術交流活動及弘揚藝文外，秉持互相切磋砥礪的精神，從關愛社會、擁抱人群的人文關懷，以展現多元兼具的創作理念，發揚各自擅長的創新特色風格為主軸。會員作品從道法自然到融合作者內心情感，進一步想鏈結到觀賞者，盼本次聯展能提供南投縣民一場具有同頻共鳴節奏美的饗宴。', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-09 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d970d', '心相．意象-王子維、郭琦、戴裕峰陶塑創作三人聯展', '「心相」，視日常生活為創作素材，從自身生命經驗中翻閱，找尋互相契合的靈魂，在柔和身心靈的過程中，搭載創作者與陶土之間的對話媒介，緩緩地傾訴內心所知所感…。\r\n「意象」，重新梳理創作者與雕塑人像之間的情緒與情感，引領觀者在凝視雕塑人像的過程中，感受創作者的表現手法與內心世界外，也引導觀者探索自身的心靈空間，引發對日常生活的不同觀點與想像。在「心相」與「意象」間揉捻著泥土，型塑每段生命經驗的寶貴時光。', '南投縣政府', '南投縣南投市建國路135號', '2025-03-29 00:00:00', '2025-04-16 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='心相．意象-王子維、郭琦、戴裕峰陶塑創作三人聯展', `description`='「心相」，視日常生活為創作素材，從自身生命經驗中翻閱，找尋互相契合的靈魂，在柔和身心靈的過程中，搭載創作者與陶土之間的對話媒介，緩緩地傾訴內心所知所感…。\r\n「意象」，重新梳理創作者與雕塑人像之間的情緒與情感，引領觀者在凝視雕塑人像的過程中，感受創作者的表現手法與內心世界外，也引導觀者探索自身的心靈空間，引發對日常生活的不同觀點與想像。在「心相」與「意象」間揉捻著泥土，型塑每段生命經驗的寶貴時光。', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-16 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d970e', '彷彿若有光－彭雅美雕塑個展', '本次個展彭雅美首次以大型雕塑不銹鋼+銅雕塑的創作形式、挑戰高難度的金屬雕塑技術，作品跳脫出物件（Object）思考進而嘗試與空間對話，展現其獨特的創作風格和對生命的深刻思考。本次展出彭雅美歷年代表作品，共七個系列作，包括「蕨類系列」、「時空之花」、「繁花無盡」、「泡影如夢」、「剎那。永恆」、「種子的旅程」及「風起雲湧」等。', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-01-18 00:00:00', '2025-03-30 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '全票+20;半票+10', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彷彿若有光－彭雅美雕塑個展', `description`='本次個展彭雅美首次以大型雕塑不銹鋼+銅雕塑的創作形式、挑戰高難度的金屬雕塑技術，作品跳脫出物件（Object）思考進而嘗試與空間對話，展現其獨特的創作風格和對生命的深刻思考。本次展出彭雅美歷年代表作品，共七個系列作，包括「蕨類系列」、「時空之花」、「繁花無盡」、「泡影如夢」、「剎那。永恆」、「種子的旅程」及「風起雲湧」等。', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-01-18 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='全票+20;半票+10', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560026b3240c403d970f', '真雲林閣掌中劇團《台灣演義-九頭十八手》', '來自雲林縣真雲林閣掌中劇團，曾榮獲多項藝文獎項殊榮，也曾榮獲第27屆傳藝金曲獎「最佳個人表演新秀獎」，本次演出講述雲林口湖鄉沿海一帶的傳奇故事，戰水英雄的由來，透過逗趣活潑的布袋戲，讓家長可以帶著孩子們認識傳統文化，體會偶戲之美，同時寓教於樂，是一齣值得大家期待的精采好戲。', '南投縣政府', '南投縣南投市建國路135號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='真雲林閣掌中劇團《台灣演義-九頭十八手》', `description`='來自雲林縣真雲林閣掌中劇團，曾榮獲多項藝文獎項殊榮，也曾榮獲第27屆傳藝金曲獎「最佳個人表演新秀獎」，本次演出講述雲林口湖鄉沿海一帶的傳奇故事，戰水英雄的由來，透過逗趣活潑的布袋戲，讓家長可以帶著孩子們認識傳統文化，體會偶戲之美，同時寓教於樂，是一齣值得大家期待的精采好戲。', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d9710', '雷峰掌中劇團《小神童柯包》', '多次榮獲本縣傑出演藝團隊以及藝起同樂演出團隊殊榮，本次演出由柯建宇副團長主演，帶來神童柯包奇幻旅程，同時劇情帶入環保議題，講述百果山快樂山莊被骯髒魔王破壞霸佔，神童柯包剷奸除惡，透過傳統布袋戲融合新創編排，以寓教於樂方式帶領親子共同體驗神童柯包的奇幻旅程。', '南投縣政府', '南投縣南投市建國路135號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='雷峰掌中劇團《小神童柯包》', `description`='多次榮獲本縣傑出演藝團隊以及藝起同樂演出團隊殊榮，本次演出由柯建宇副團長主演，帶來神童柯包奇幻旅程，同時劇情帶入環保議題，講述百果山快樂山莊被骯髒魔王破壞霸佔，神童柯包剷奸除惡，透過傳統布袋戲融合新創編排，以寓教於樂方式帶領親子共同體驗神童柯包的奇幻旅程。', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d9711', '「滲透與默化」花蓮公共藝術教育展', '策展人胡朝聖以「滲透與默化」作為本次展覽的主題，聚焦公共藝術在當今社會的深刻影響。從視覺、文化到環境氛圍，公共藝術已無所不在，並在城市空間中與人群日常生活密切交織。胡朝聖指出，公共藝術不僅僅是文化政策的輔助/延伸，更是當代城市發展中的核心元素。作為文化符號，它提升了生活品質與美學素養，並彰顯了土地的歷史與文化脈動，成為城市面貌中不可或缺的一部分。', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-01-18 00:00:00', '2025-03-30 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '全票+20;半票+10', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「滲透與默化」花蓮公共藝術教育展', `description`='策展人胡朝聖以「滲透與默化」作為本次展覽的主題，聚焦公共藝術在當今社會的深刻影響。從視覺、文化到環境氛圍，公共藝術已無所不在，並在城市空間中與人群日常生活密切交織。胡朝聖指出，公共藝術不僅僅是文化政策的輔助/延伸，更是當代城市發展中的核心元素。作為文化符號，它提升了生活品質與美學素養，並彰顯了土地的歷史與文化脈動，成為城市面貌中不可或缺的一部分。', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-01-18 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='全票+20;半票+10', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d9712', '南投縣私立弘明實驗高級中學《微風中的歌聲舞影》', '本次演出以「風」為主題，包含多國語言，有國語、台語、日語、英語等有關風的歌曲，透過清新美好的歌聲，唱出四季的風，以及風的各種色彩，多采多姿的演出內容，更加入了古典舞、民族舞和民俗舞蹈演出，藉由載歌載舞的微風中歌聲舞影，帶給觀眾美好的聽覺視覺饗宴。\r\n索票入場：2月20日起於南投縣私立弘明實驗高級中學索票，請洽049-2731799劉主任。', '南投縣政府', '南投縣南投市建國路135號', '2025-03-28 00:00:00', '2025-03-28 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南投縣私立弘明實驗高級中學《微風中的歌聲舞影》', `description`='本次演出以「風」為主題，包含多國語言，有國語、台語、日語、英語等有關風的歌曲，透過清新美好的歌聲，唱出四季的風，以及風的各種色彩，多采多姿的演出內容，更加入了古典舞、民族舞和民俗舞蹈演出，藉由載歌載舞的微風中歌聲舞影，帶給觀眾美好的聽覺視覺饗宴。\r\n索票入場：2月20日起於南投縣私立弘明實驗高級中學索票，請洽049-2731799劉主任。', `organizer`='南投縣政府', `address`='南投縣南投市建國路135號', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d9713', '李靜芳歌仔戲團公演', '由南投縣傑出演藝團隊李靜芳歌仔戲團帶來精彩演出，團長李靜芳長期助力於歌仔戲推廣以及戲曲文化推向國際發展，更入圍第32屆傳藝金曲獎最佳傳統音樂專輯獎、最佳演唱獎；更入圍第35屆傳藝金曲獎「最佳演員獎」殊榮，透過年年不斷創作，搬演精緻好戲，期盼將傳統藝術更接近普羅大眾。', '南投縣政府', '南投縣竹山鎮', '2025-03-28 00:00:00', '2025-03-28 00:00:00', '竹山鎮（南投縣）=', 23.69805518, 120.7100797, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='李靜芳歌仔戲團公演', `description`='由南投縣傑出演藝團隊李靜芳歌仔戲團帶來精彩演出，團長李靜芳長期助力於歌仔戲推廣以及戲曲文化推向國際發展，更入圍第32屆傳藝金曲獎最佳傳統音樂專輯獎、最佳演唱獎；更入圍第35屆傳藝金曲獎「最佳演員獎」殊榮，透過年年不斷創作，搬演精緻好戲，期盼將傳統藝術更接近普羅大眾。', `organizer`='南投縣政府', `address`='南投縣竹山鎮', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='竹山鎮（南投縣）=', `latitude`=23.69805518, `longitude`=120.7100797, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d9714', '「石況製造－從產地到日常」石材科普常設展', '花蓮是臺灣石頭的故鄉，探討花蓮的石（實）況製造現場\r\n1960年代，臺灣東西橫貫公路開闢，掀起了花蓮石材產業發展的序幕，並隨著經濟起飛快速發展，花蓮產出高品質的大理石及蛇紋石等石材，內外銷舉世聞名，優異的品質與加工更讓臺灣在當時成為僅次於義大利，全球第二大的石材加工出口國，獲得「石頭故鄉」的美名，並成為花蓮縣獨具特色的重要產業。\r\n展覽依循相關產業的發展脈絡，具體以「石礦科普知識」、「石礦開採與產業發展史」、「當代石材的生活應用」以及「民眾體驗互動學習」等四大面向，呈現石材產業的過去、現在與未來發展，體驗石材自產地到日常應用的科普知識，深入了解花蓮的「石（實）況製造」。\r\n ', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '全票+20;半票+10', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「石況製造－從產地到日常」石材科普常設展', `description`='花蓮是臺灣石頭的故鄉，探討花蓮的石（實）況製造現場\r\n1960年代，臺灣東西橫貫公路開闢，掀起了花蓮石材產業發展的序幕，並隨著經濟起飛快速發展，花蓮產出高品質的大理石及蛇紋石等石材，內外銷舉世聞名，優異的品質與加工更讓臺灣在當時成為僅次於義大利，全球第二大的石材加工出口國，獲得「石頭故鄉」的美名，並成為花蓮縣獨具特色的重要產業。\r\n展覽依循相關產業的發展脈絡，具體以「石礦科普知識」、「石礦開採與產業發展史」、「當代石材的生活應用」以及「民眾體驗互動學習」等四大面向，呈現石材產業的過去、現在與未來發展，體驗石材自產地到日常應用的科普知識，深入了解花蓮的「石（實）況製造」。\r\n ', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='全票+20;半票+10', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d9715', '非相．無邊-李宥榛創作展', '此次主題『非相-無邊』的創作理念為一般人容易被認知所框架而失去了直覺的想像力，一幅作品是經過畫家心腦內外整合意識所呈現出的樣貌，愛因斯坦說：｢萬物皆『振動』｣；佛家亦云：『凡所有相皆是虛妄』。作者將其解釋為「相」皆為頻率也是能量的流動，讓觀看者內在意識的連想與自我探索，是作者此次所欲傳達與互動的方式。 \r\n開幕式：3月16日(日)14:30', '南投縣政府文化局', '南投縣南投市彰南路二段61號', '2025-03-15 00:00:00', '2025-04-09 00:00:00', '南投縣藝術家資料館', 23.9095346, 120.6846092, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='非相．無邊-李宥榛創作展', `description`='此次主題『非相-無邊』的創作理念為一般人容易被認知所框架而失去了直覺的想像力，一幅作品是經過畫家心腦內外整合意識所呈現出的樣貌，愛因斯坦說：｢萬物皆『振動』｣；佛家亦云：『凡所有相皆是虛妄』。作者將其解釋為「相」皆為頻率也是能量的流動，讓觀看者內在意識的連想與自我探索，是作者此次所欲傳達與互動的方式。 \r\n開幕式：3月16日(日)14:30', `organizer`='南投縣政府文化局', `address`='南投縣南投市彰南路二段61號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-04-09 00:00:00', `location`='南投縣藝術家資料館', `latitude`=23.9095346, `longitude`=120.6846092, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d9716', '2024中山青年藝術獎巡迴展', '國立國父紀念館主辦「2024中山青年藝術獎作品展」，預計展出得獎作品共54件（水墨類13件、書法類28件、油畫類13件）。「中山青年藝術獎」徵件競賽，鼓勵20至45歲的年輕藝術家創作，今年邁入第9屆，參賽作品2百餘件作品報名，經過初審及複審2階段選出40位得獎者，包含水墨類13名、書法類14名、油畫類13名。中山獎得主分別為水墨類劉信義、書法類蘇梓靖、油畫類李梓維，各獲得獎金30萬元及獎座1座，同時獲得免審查方式申請於國父紀念館辦理個展。', '國立國父紀念館', '南投縣南投市中興新村環山路95巷26號', '2025-03-07 00:00:00', '2025-04-09 00:00:00', '虎山藝術館', 23.9179739, 120.6774812, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2024中山青年藝術獎巡迴展', `description`='國立國父紀念館主辦「2024中山青年藝術獎作品展」，預計展出得獎作品共54件（水墨類13件、書法類28件、油畫類13件）。「中山青年藝術獎」徵件競賽，鼓勵20至45歲的年輕藝術家創作，今年邁入第9屆，參賽作品2百餘件作品報名，經過初審及複審2階段選出40位得獎者，包含水墨類13名、書法類14名、油畫類13名。中山獎得主分別為水墨類劉信義、書法類蘇梓靖、油畫類李梓維，各獲得獎金30萬元及獎座1座，同時獲得免審查方式申請於國父紀念館辦理個展。', `organizer`='國立國父紀念館', `address`='南投縣南投市中興新村環山路95巷26號', `start_date`='2025-03-07 00:00:00', `end_date`='2025-04-09 00:00:00', `location`='虎山藝術館', `latitude`=23.9179739, `longitude`=120.6774812, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d9717', '114年第一期鋼筆畫班及淡彩班', '開設班別：鋼筆畫班、淡彩班\r\n研習內容：由講師親自講解，學員現場實畫。\r\n參加對象：對學習鋼筆畫（含所有硬筆畫）、淡彩畫，有興趣的樂齡、銀髮族（含婦女），舊學員優先，每班人數以30人為限。\r\n洽詢電話：049-2226156。', '南投縣南投市公所', '南投縣南投市漳興巷51號', '2025-02-14 00:00:00', '2025-06-27 00:00:00', '南投市立圖書館（臨時圖書館）', 23.9146117, 120.680837, '無資料', 'https://www.facebook.com/profile.php?id=100064333496575#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年第一期鋼筆畫班及淡彩班', `description`='開設班別：鋼筆畫班、淡彩班\r\n研習內容：由講師親自講解，學員現場實畫。\r\n參加對象：對學習鋼筆畫（含所有硬筆畫）、淡彩畫，有興趣的樂齡、銀髮族（含婦女），舊學員優先，每班人數以30人為限。\r\n洽詢電話：049-2226156。', `organizer`='南投縣南投市公所', `address`='南投縣南投市漳興巷51號', `start_date`='2025-02-14 00:00:00', `end_date`='2025-06-27 00:00:00', `location`='南投市立圖書館（臨時圖書館）', `latitude`=23.9146117, `longitude`=120.680837, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064333496575#', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d9718', '113-1期「熊愛閱讀」說情畫意活動縣長獎作品展', '南投縣政府文化局與18度C文化基金會合作辦理「熊愛閱讀」閱讀護照計畫，其中學生以8開圖畫紙作畫並書寫心得的「『說』情『畫』意」活動，係由各校學生完成項目一「閱讀集點趣」活動之基本閱讀冊數門檻後，由各校老師認證資格後方可參加。學生以8開圖畫紙作畫並書寫心得，鼓勵學生藉由閱讀發揮想像力，進而獨立創作，參與圖、文閱讀分享活動，倡導閱讀風氣，增進學生寫作思考能力，歡迎大家一起到圖書館欣賞獲獎學生的創作心得！\r\n113-1期「熊愛閱讀」縣長獎選出心得達人共計36位，歡迎大家一起到圖書館欣賞獲獎學生的創作心得！', '南投縣政府文化局', '南投縣集集鎮育才街166號', '2025-03-06 00:00:00', '2025-04-15 00:00:00', '集集鎮文化服務所（圖書館）', 23.828033, 120.788368, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='113-1期「熊愛閱讀」說情畫意活動縣長獎作品展', `description`='南投縣政府文化局與18度C文化基金會合作辦理「熊愛閱讀」閱讀護照計畫，其中學生以8開圖畫紙作畫並書寫心得的「『說』情『畫』意」活動，係由各校學生完成項目一「閱讀集點趣」活動之基本閱讀冊數門檻後，由各校老師認證資格後方可參加。學生以8開圖畫紙作畫並書寫心得，鼓勵學生藉由閱讀發揮想像力，進而獨立創作，參與圖、文閱讀分享活動，倡導閱讀風氣，增進學生寫作思考能力，歡迎大家一起到圖書館欣賞獲獎學生的創作心得！\r\n113-1期「熊愛閱讀」縣長獎選出心得達人共計36位，歡迎大家一起到圖書館欣賞獲獎學生的創作心得！', `organizer`='南投縣政府文化局', `address`='南投縣集集鎮育才街166號', `start_date`='2025-03-06 00:00:00', `end_date`='2025-04-15 00:00:00', `location`='集集鎮文化服務所（圖書館）', `latitude`=23.828033, `longitude`=120.788368, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d9719', '「經典瓊瑤」書展', '洽詢電話：049-2221619轉101陳小姐。', '南投縣政府文化局', '南投縣南投市中興路669號', '2025-03-04 00:00:00', '2025-04-30 00:00:00', '南投縣政府文化局圖書館', 23.9027891, 120.691332, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「經典瓊瑤」書展', `description`='洽詢電話：049-2221619轉101陳小姐。', `organizer`='南投縣政府文化局', `address`='南投縣南投市中興路669號', `start_date`='2025-03-04 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='南投縣政府文化局圖書館', `latitude`=23.9027891, `longitude`=120.691332, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d971a', '磊山保經xAccusefive告五人 [MY MAGIC 宇宙超有趣] 新世界巡迴演唱會｜2025世運極限版', '【 磊山保經xAccusefive告五人 [MY MAGIC 宇宙超有趣] 新世界巡迴演唱會｜2025世運極限版 】\r\n\r\n有沒有一種感覺？\r\n是港口與城市同時包圍著你\r\n漫步夜晚的輕鬆舒心\r\n\r\n有沒有一種感覺？\r\n是你站在星星底下的花園\r\n聽著你命中注定的那首歌曲為你盛開\r\n\r\n有沒有一種感覺？\r\n是整個宇宙圍繞著你\r\n你愛的人和愛你的人\r\n為你特別了昨天今天和明天\r\n\r\n最後是你自己\r\n辛苦在這個宇宙奮鬥的自己\r\n勇敢並從不放棄\r\n追逐愛的模樣\r\n\r\n歡迎來到這裡\r\n我們和你一起站在新世界的草地\r\n看盡宇宙超有趣\r\n給你一場魔法夜生活\r\n“ You Are My Magic ! ”\r\n\r\n演出日期｜2025.4.12 (六) 19:00\r\n演出地點｜高雄世運主場館（高雄市左營區世運大道100號）\r\n售票時間｜2025.2.15 (六) 12:00\r\n售票單位｜拓元售票系統\r\n票價｜3850 / 3350 / 3050 / 2550 / 2050 / 1550 / 750 ＊全場對號入座\r\n身障票｜1525 / 1275  (線上訂購）', '相信音樂國際股份有限公司', '高雄市左營區002鄰世運大道100號', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '高雄國家體育場﹝2009世運會主場館﹞', 22.7023314, 120.2946956, '身障票+1275;身障票+1525;--+750;--+1550;--+2050;--+2550;--+3050;--+3350;--+3850', 'https://tixcraft.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='磊山保經xAccusefive告五人 [MY MAGIC 宇宙超有趣] 新世界巡迴演唱會｜2025世運極限版', `description`='【 磊山保經xAccusefive告五人 [MY MAGIC 宇宙超有趣] 新世界巡迴演唱會｜2025世運極限版 】\r\n\r\n有沒有一種感覺？\r\n是港口與城市同時包圍著你\r\n漫步夜晚的輕鬆舒心\r\n\r\n有沒有一種感覺？\r\n是你站在星星底下的花園\r\n聽著你命中注定的那首歌曲為你盛開\r\n\r\n有沒有一種感覺？\r\n是整個宇宙圍繞著你\r\n你愛的人和愛你的人\r\n為你特別了昨天今天和明天\r\n\r\n最後是你自己\r\n辛苦在這個宇宙奮鬥的自己\r\n勇敢並從不放棄\r\n追逐愛的模樣\r\n\r\n歡迎來到這裡\r\n我們和你一起站在新世界的草地\r\n看盡宇宙超有趣\r\n給你一場魔法夜生活\r\n“ You Are My Magic ! ”\r\n\r\n演出日期｜2025.4.12 (六) 19:00\r\n演出地點｜高雄世運主場館（高雄市左營區世運大道100號）\r\n售票時間｜2025.2.15 (六) 12:00\r\n售票單位｜拓元售票系統\r\n票價｜3850 / 3350 / 3050 / 2550 / 2050 / 1550 / 750 ＊全場對號入座\r\n身障票｜1525 / 1275  (線上訂購）', `organizer`='相信音樂國際股份有限公司', `address`='高雄市左營區002鄰世運大道100號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='高雄國家體育場﹝2009世運會主場館﹞', `latitude`=22.7023314, `longitude`=120.2946956, `ticket_price`='身障票+1275;身障票+1525;--+750;--+1550;--+2050;--+