INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d971b', '《生命脈動-林園之美》攝影展', '由林園愛鄉協會成員陳俊強、黃鳳芬、黃冠維、劉瀞文、黃振興、林文麗、李宜蓁、曾文煌、周柄保、陳宗明多位攝影專家，拍攝出許多精豔林園生態攝影，攝影作品訴說林園海洋濕地生態故事、不同紅樹林生態生長環境、生物多樣性，邀請有興趣的市民朋友們一同來觀展。', '高雄市立圖書館總館', '高雄市林園區林園北路236號', '2025-03-08 00:00:00', '2025-04-26 00:00:00', '高雄市立圖書館林園分館', 22.5075991, 120.3949167, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《生命脈動-林園之美》攝影展', `description`='由林園愛鄉協會成員陳俊強、黃鳳芬、黃冠維、劉瀞文、黃振興、林文麗、李宜蓁、曾文煌、周柄保、陳宗明多位攝影專家，拍攝出許多精豔林園生態攝影，攝影作品訴說林園海洋濕地生態故事、不同紅樹林生態生長環境、生物多樣性，邀請有興趣的市民朋友們一同來觀展。', `organizer`='高雄市立圖書館總館', `address`='高雄市林園區林園北路236號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄市立圖書館林園分館', `latitude`=22.5075991, `longitude`=120.3949167, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d971c', '流域連結——城市之外的藝術教育經驗交流會＆教案開發工作坊 —遊物時間', '流域連結——城市之外的藝術教育經驗交流會\r\n日期：2025年3月22日（六）\r\n地點：毓繡美術館 百書咖啡\r\n「流域連結」象徵文化館舍與美術館如同不同的流域，各自在土地上深耕，以獨特的方式滋養社群，累積知識與經驗。而這條看不見的河流，正因為每一個館舍努力而持續流動。長期推動中部地區偏鄉美感教育的毓繡美術館，首次舉辦這場交流活動，正是希望藉此「匯流」的契機，讓來自不同地域、擁有不同資源條件與實踐方式的藝術教育工作者相聚，彼此對話、交融經驗，為藝術教育與文化推廣帶來更豐沛的可能性。\r\n我們特別邀請同樣深耕南投集集、致力於館校藝術計畫的趨勢教育基金會，與毓繡美術館形成對話，兩者將以自身的經驗出發，透過案例分享、共創工作坊與開放對話，探討藝術教育計畫的推動歷程，盤點資源，並思索未來的發展方向。我們期望透過這次相聚，深化非都會地區文化館舍、學校及藝術教育工作者之間的對話與合作，讓各自累積的經驗與資源得以交流互惠，持續為這片文化流域注入生命力。使藝術教育不僅是知識的傳遞，更是對社會的想像與實踐。\r\n本活動採邀請制，對象包括中部地區的文化館舍從業人員、學校教師、藝術教育研究者與教學型藝術家。\r\n活動內容：主題座談、綜合對談、共創工作坊、當期展覽導覽參觀\r\n活動流程：\r\n10:30 開放報到\r\n10:40-10:45 活動開場\r\n10:45-11:25 「從都會到小鎮：集思廣藝的共學與共創」\r\n             分享者：趨勢教育基金會/楊豐維、廖涵羽\r\n11:30-12:10 「偏鄉美術館裡的藝術計畫」\r\n            分享者：毓繡美術館/館長 黃翔、學習及參與計畫統籌 賴建甫\r\n12:10-13:30 午餐時間\r\n13:30-14:10 綜合對談\r\n            與談人：毓繡美術館/館長 黃翔、趨勢教育基金會/楊豐維\r\n14:15-15:00 共創工作坊：「藝術計畫從0到1的距離」\r\n15:00-15:35 毓繡美術館園區暨當期展覽導覽\r\n15:40-16:00 自由交流時間\r\n\r\n教案開發工作坊 ——遊物時間\r\n日期：2025年3月23日（日）\r\n地點：毓繡美術館\r\n以當期展覽「遊物時間」為靈感，集結青年藝術家共創美感教案，探索藝術教育的更多可能。\r\n工作坊期間發展出的教案雛形，將有機會成為「我的美術課在美術館」或「藝術快遞」課程，進一步落實於校園與美術館教學現場。\r\n我們期待具備藝術創作或教學經驗的夥伴報名參加，將依報名狀況進行審核，確保參與者能在相近經驗基礎上充分交流，共同激盪更多教學現場的創意火花。\r\n參加者須於3/22同步參與「流域連結」交流會，以理解在地藝術教育脈絡。\r\n內容：展覽導覽、教案實驗、創作交流\r\n對象：具藝術創作或藝術教學經驗之藝術家、藝術教師\r\n人數：8-10人\r\n流程\r\n10:10-10:50 創意發想\r\n            透過思考工具發散思維，尋找有趣的教案點子。\r\n11:00-11:50 個人構思時間\r\n            參與者初步書寫教案構想與核心概念。現場提供插座與創作材料。\r\n12:00~13:30 午餐時間X前輩分享聊\r\n            過去教學藝術家經驗分享，透過輕鬆對談與Q&A交流，了解實務經驗與挑戰。\r\n13:30-15:00 個人構思時間\r\n            進一步整理與準備教案概念提案。\r\n15:00-16:30 提案與交流\r\n            教案提案與綜合討論，進行彼此回饋。\r\n報名：即日起至 3/10（日）開放報名，名額有限\r\n表單：https://forms.gle/SdEgJ3ggKDW6d7rY9', '財團法人毓繡文化基金會', '南投縣草屯鎮健行路150巷26號', '2025-03-22 00:00:00', '2025-03-23 00:00:00', '毓繡美術館', 23.9859227, 120.766731, '無資料', 'https://www.facebook.com/yuhsiu.museum', '[]') ON DUPLICATE KEY UPDATE `activity_name`='流域連結——城市之外的藝術教育經驗交流會＆教案開發工作坊 —遊物時間', `description`='流域連結——城市之外的藝術教育經驗交流會\r\n日期：2025年3月22日（六）\r\n地點：毓繡美術館 百書咖啡\r\n「流域連結」象徵文化館舍與美術館如同不同的流域，各自在土地上深耕，以獨特的方式滋養社群，累積知識與經驗。而這條看不見的河流，正因為每一個館舍努力而持續流動。長期推動中部地區偏鄉美感教育的毓繡美術館，首次舉辦這場交流活動，正是希望藉此「匯流」的契機，讓來自不同地域、擁有不同資源條件與實踐方式的藝術教育工作者相聚，彼此對話、交融經驗，為藝術教育與文化推廣帶來更豐沛的可能性。\r\n我們特別邀請同樣深耕南投集集、致力於館校藝術計畫的趨勢教育基金會，與毓繡美術館形成對話，兩者將以自身的經驗出發，透過案例分享、共創工作坊與開放對話，探討藝術教育計畫的推動歷程，盤點資源，並思索未來的發展方向。我們期望透過這次相聚，深化非都會地區文化館舍、學校及藝術教育工作者之間的對話與合作，讓各自累積的經驗與資源得以交流互惠，持續為這片文化流域注入生命力。使藝術教育不僅是知識的傳遞，更是對社會的想像與實踐。\r\n本活動採邀請制，對象包括中部地區的文化館舍從業人員、學校教師、藝術教育研究者與教學型藝術家。\r\n活動內容：主題座談、綜合對談、共創工作坊、當期展覽導覽參觀\r\n活動流程：\r\n10:30 開放報到\r\n10:40-10:45 活動開場\r\n10:45-11:25 「從都會到小鎮：集思廣藝的共學與共創」\r\n             分享者：趨勢教育基金會/楊豐維、廖涵羽\r\n11:30-12:10 「偏鄉美術館裡的藝術計畫」\r\n            分享者：毓繡美術館/館長 黃翔、學習及參與計畫統籌 賴建甫\r\n12:10-13:30 午餐時間\r\n13:30-14:10 綜合對談\r\n            與談人：毓繡美術館/館長 黃翔、趨勢教育基金會/楊豐維\r\n14:15-15:00 共創工作坊：「藝術計畫從0到1的距離」\r\n15:00-15:35 毓繡美術館園區暨當期展覽導覽\r\n15:40-16:00 自由交流時間\r\n\r\n教案開發工作坊 ——遊物時間\r\n日期：2025年3月23日（日）\r\n地點：毓繡美術館\r\n以當期展覽「遊物時間」為靈感，集結青年藝術家共創美感教案，探索藝術教育的更多可能。\r\n工作坊期間發展出的教案雛形，將有機會成為「我的美術課在美術館」或「藝術快遞」課程，進一步落實於校園與美術館教學現場。\r\n我們期待具備藝術創作或教學經驗的夥伴報名參加，將依報名狀況進行審核，確保參與者能在相近經驗基礎上充分交流，共同激盪更多教學現場的創意火花。\r\n參加者須於3/22同步參與「流域連結」交流會，以理解在地藝術教育脈絡。\r\n內容：展覽導覽、教案實驗、創作交流\r\n對象：具藝術創作或藝術教學經驗之藝術家、藝術教師\r\n人數：8-10人\r\n流程\r\n10:10-10:50 創意發想\r\n            透過思考工具發散思維，尋找有趣的教案點子。\r\n11:00-11:50 個人構思時間\r\n            參與者初步書寫教案構想與核心概念。現場提供插座與創作材料。\r\n12:00~13:30 午餐時間X前輩分享聊\r\n            過去教學藝術家經驗分享，透過輕鬆對談與Q&A交流，了解實務經驗與挑戰。\r\n13:30-15:00 個人構思時間\r\n            進一步整理與準備教案概念提案。\r\n15:00-16:30 提案與交流\r\n            教案提案與綜合討論，進行彼此回饋。\r\n報名：即日起至 3/10（日）開放報名，名額有限\r\n表單：https://forms.gle/SdEgJ3ggKDW6d7rY9', `organizer`='財團法人毓繡文化基金會', `address`='南投縣草屯鎮健行路150巷26號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='毓繡美術館', `latitude`=23.9859227, `longitude`=120.766731, `ticket_price`='無資料', `source_url`='