INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d971d', '信義鄉原住民文化館：傳統編織（地織）課程', '名額：8人，歡迎對傳統編織（地織）有興趣者報名參加。\r\n洽詢電話：049-2831132 信義鄉原住民文化館。', '南投縣信義鄉公所', '南投縣信義鄉', '2025-03-22 00:00:00', '2025-07-19 00:00:00', '信義鄉（南投縣）=', 23.6554647, 121.0212867, '保證金+1000', 'https://www.facebook.com/icmost2831132', '[]') ON DUPLICATE KEY UPDATE `activity_name`='信義鄉原住民文化館：傳統編織（地織）課程', `description`='名額：8人，歡迎對傳統編織（地織）有興趣者報名參加。\r\n洽詢電話：049-2831132 信義鄉原住民文化館。', `organizer`='南投縣信義鄉公所', `address`='南投縣信義鄉', `start_date`='2025-03-22 00:00:00', `end_date`='2025-07-19 00:00:00', `location`='信義鄉（南投縣）=', `latitude`=23.6554647, `longitude`=121.0212867, `ticket_price`='保證金+1000', `source_url`='https://www.facebook.com/icmost2831132', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6560126b3240c403d971e', '產品社群新時代：AI圖像與影音生成應用', '講師：許可妮，跨界策略顧問股份有限公司-設計師。\r\n課程大綱：課程涵蓋產品定位、圖像生成、文案撰寫與動態剪輯實作，幫助學員創作高品質品牌內容，提升創意表現與效率。\r\n透過實際操作，掌握產品行銷的全方位技能，應對數位行銷挑戰，打造引人注目的社群平台宣傳！\r\n課程大綱：\r\n1、產品定位與宣傳風格探討\r\n2、圖像生成 AI 概論\r\n3、產品LOGO實戰教學\r\n4、文案生成與實作\r\n5、社群平台文案、圖卡應用\r\n6、影片、音樂動態生成與剪輯\r\n報名時間：2月26日19時至3月17日23時59分\r\n本課程一律採線上報名，不開放現場報名參加。', '勞動部勞動力發展署中彰投分署', '南投縣南投市', '2025-03-22 00:00:00', '2025-03-23 00:00:00', '南投市（南投縣）=', 23.92173537, 120.6787658, '無資料', 'https://ysmb.wda.gov.tw/activity_detail.php?id=1839', '[]') ON DUPLICATE KEY UPDATE `activity_name`='產品社群新時代：AI圖像與影音生成應用', `description`='講師：許可妮，跨界策略顧問股份有限公司-設計師。\r\n課程大綱：課程涵蓋產品定位、圖像生成、文案撰寫與動態剪輯實作，幫助學員創作高品質品牌內容，提升創意表現與效率。\r\n透過實際操作，掌握產品行銷的全方位技能，應對數位行銷挑戰，打造引人注目的社群平台宣傳！\r\n課程大綱：\r\n1、產品定位與宣傳風格探討\r\n2、圖像生成 AI 概論\r\n3、產品LOGO實戰教學\r\n4、文案生成與實作\r\n5、社群平台文案、圖卡應用\r\n6、影片、音樂動態生成與剪輯\r\n報名時間：2月26日19時至3月17日23時59分\r\n本課程一律採線上報名，不開放現場報名參加。', `organizer`='勞動部勞動力發展署中彰投分署', `address`='南投縣南投市', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='南投市（南投縣）=', `latitude`=23.92173537, `longitude`=120.6787658, `ticket_price`='無資料', `source_url`='https://ysmb.wda.gov.tw/activity_detail.php?id=1839', `image_url`='[]';
