INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e7e26b3240c403d9760', '【波滔滔兮來迎，魚鱗鱗兮媵予：從文學到影像，從回顧到創造】第二場3/22顏智英教授主講「微物多用：先秦至宋代的「蚌蛤」文化」', '海洋一直是最不可思議的世界，而潛藏在水底深處的海洋生物，持續在古老的神話與文學作品中引發無盡的想像，並在現代影像中綻放出新的光芒。海洋生物富有生命力，山海經曾提到：「東海之渚中，有神」，而海洋作家夏曼．藍波安筆下關於蘭嶼的飛魚神話，或是紀錄片《刪海經》「鱟」的獨特身影，海洋生物的故事是文學、是影像、是生活、也是我們的未來。\r\n\r\n本系列講座特以海洋生物為主題，邀讀者來國圖一起遊書海，重新發掘海底之美。在這個結合文學與影像的旅程中，我們可以激發無限的想像力，「波滔滔兮來迎，魚鱗鱗兮媵予」，我們也可以像自由自在的魚一樣，遨遊四海。而今年與國立海洋生物博物館以及臺灣海洋教育中心攜手合作，並加碼手作課程，讓大朋友小朋友都來本館多媒體實驗中心體驗知識的樂趣。2025春季閱讀講座讓我們一起追隨經典海洋故事的足跡，探索那些仍在等待揭示的深海奧秘。\r\n\r\n第二場3/22顏智英教授主講「微物多用：先秦至宋代的「蚌蛤」文化」\r\n\r\n報名日期：即日起~2024/3/19\r\n\r\n課程時間及地點：\r\n時　　間：民國114年3月22日（星期六）下午2:00~5:00\r\n地　　點：國家圖書館藝文中心3樓國際會議廳（臺北市中山南路20號）\r\n主題活動網址：https://actio.ncl.edu.tw/114_spring\r\n活動報名網址：https://actio.ncl.edu.tw/activitydetails?uid=6&pid=714\r\n', '國家圖書館', '臺北市中正區中山南路20號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '國家圖書館', 25.03240487, 121.5198839, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【波滔滔兮來迎，魚鱗鱗兮媵予：從文學到影像，從回顧到創造】第二場3/22顏智英教授主講「微物多用：先秦至宋代的「蚌蛤」文化」', `description`='海洋一直是最不可思議的世界，而潛藏在水底深處的海洋生物，持續在古老的神話與文學作品中引發無盡的想像，並在現代影像中綻放出新的光芒。海洋生物富有生命力，山海經曾提到：「東海之渚中，有神」，而海洋作家夏曼．藍波安筆下關於蘭嶼的飛魚神話，或是紀錄片《刪海經》「鱟」的獨特身影，海洋生物的故事是文學、是影像、是生活、也是我們的未來。\r\n\r\n本系列講座特以海洋生物為主題，邀讀者來國圖一起遊書海，重新發掘海底之美。在這個結合文學與影像的旅程中，我們可以激發無限的想像力，「波滔滔兮來迎，魚鱗鱗兮媵予」，我們也可以像自由自在的魚一樣，遨遊四海。而今年與國立海洋生物博物館以及臺灣海洋教育中心攜手合作，並加碼手作課程，讓大朋友小朋友都來本館多媒體實驗中心體驗知識的樂趣。2025春季閱讀講座讓我們一起追隨經典海洋故事的足跡，探索那些仍在等待揭示的深海奧秘。\r\n\r\n第二場3/22顏智英教授主講「微物多用：先秦至宋代的「蚌蛤」文化」\r\n\r\n報名日期：即日起~2024/3/19\r\n\r\n課程時間及地點：\r\n時　　間：民國114年3月22日（星期六）下午2:00~5:00\r\n地　　點：國家圖書館藝文中心3樓國際會議廳（臺北市中山南路20號）\r\n主題活動網址：https://actio.ncl.edu.tw/114_spring\r\n活動報名網址：https://actio.ncl.edu.tw/activitydetails?uid=6&pid=714\r\n', `organizer`='國家圖書館', `address`='臺北市中正區中山南路20號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='國家圖書館', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e7e26b3240c403d9761', '【波滔滔兮來迎，魚鱗鱗兮媵予：從文學到影像，從回顧到創造】第三場3/29洪淳修導演主講「那些海洋教我的事」', '海洋一直是最不可思議的世界，而潛藏在水底深處的海洋生物，持續在古老的神話與文學作品中引發無盡的想像，並在現代影像中綻放出新的光芒。海洋生物富有生命力，山海經曾提到：「東海之渚中，有神」，而海洋作家夏曼．藍波安筆下關於蘭嶼的飛魚神話，或是紀錄片《刪海經》「鱟」的獨特身影，海洋生物的故事是文學、是影像、是生活、也是我們的未來。\r\n\r\n本系列講座特以海洋生物為主題，邀讀者來國圖一起遊書海，重新發掘海底之美。在這個結合文學與影像的旅程中，我們可以激發無限的想像力，「波滔滔兮來迎，魚鱗鱗兮媵予」，我們也可以像自由自在的魚一樣，遨遊四海。而今年與國立海洋生物博物館以及臺灣海洋教育中心攜手合作，並加碼手作課程，讓大朋友小朋友都來本館多媒體實驗中心體驗知識的樂趣。2025春季閱讀講座讓我們一起追隨經典海洋故事的足跡，探索那些仍在等待揭示的深海奧秘。\r\n\r\n第三場3/29洪淳修導演主講「那些海洋教我的事」\r\n\r\n報名日期：即日起~2024/3/26\r\n\r\n課程時間及地點：\r\n時　　間：民國114年3月29日（星期六）下午2:00~5:00\r\n地　　點：國家圖書館藝文中心3樓國際會議廳（臺北市中山南路20號）\r\n主題活動網址：https://actio.ncl.edu.tw/114_spring\r\n活動報名網址：https://actio.ncl.edu.tw/activitydetails?uid=6&pid=714\r\n', '國家圖書館', '臺北市中正區中山南路20號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '國家圖書館', 25.03240487, 121.5198839, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【波滔滔兮來迎，魚鱗鱗兮媵予：從文學到影像，從回顧到創造】第三場3/29洪淳修導演主講「那些海洋教我的事」', `description`='海洋一直是最不可思議的世界，而潛藏在水底深處的海洋生物，持續在古老的神話與文學作品中引發無盡的想像，並在現代影像中綻放出新的光芒。海洋生物富有生命力，山海經曾提到：「東海之渚中，有神」，而海洋作家夏曼．藍波安筆下關於蘭嶼的飛魚神話，或是紀錄片《刪海經》「鱟」的獨特身影，海洋生物的故事是文學、是影像、是生活、也是我們的未來。\r\n\r\n本系列講座特以海洋生物為主題，邀讀者來國圖一起遊書海，重新發掘海底之美。在這個結合文學與影像的旅程中，我們可以激發無限的想像力，「波滔滔兮來迎，魚鱗鱗兮媵予」，我們也可以像自由自在的魚一樣，遨遊四海。而今年與國立海洋生物博物館以及臺灣海洋教育中心攜手合作，並加碼手作課程，讓大朋友小朋友都來本館多媒體實驗中心體驗知識的樂趣。2025春季閱讀講座讓我們一起追隨經典海洋故事的足跡，探索那些仍在等待揭示的深海奧秘。\r\n\r\n第三場3/29洪淳修導演主講「那些海洋教我的事」\r\n\r\n報名日期：即日起~2024/3/26\r\n\r\n課程時間及地點：\r\n時　　間：民國114年3月29日（星期六）下午2:00~5:00\r\n地　　點：國家圖書館藝文中心3樓國際會議廳（臺北市中山南路20號）\r\n主題活動網址：https://actio.ncl.edu.tw/114_spring\r\n活動報名網址：https://actio.ncl.edu.tw/activitydetails?uid=6&pid=714\r\n', `organizer`='國家圖書館', `address`='臺北市中正區中山南路20號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='國家圖書館', `latitude`=25.03240487, `longitude`=121.5198839, `ti