INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e7e26b3240c403d9762', '【波滔滔兮來迎，魚鱗鱗兮媵予：從文學到影像，從回顧到創造】第四場4/12松松X拉亞主講「海洋聲音的浪潮：打造吸引人的 Podcast 從內容策劃到上架全攻略」', '海洋一直是最不可思議的世界，而潛藏在水底深處的海洋生物，持續在古老的神話與文學作品中引發無盡的想像，並在現代影像中綻放出新的光芒。海洋生物富有生命力，山海經曾提到：「東海之渚中，有神」，而海洋作家夏曼．藍波安筆下關於蘭嶼的飛魚神話，或是紀錄片《刪海經》「鱟」的獨特身影，海洋生物的故事是文學、是影像、是生活、也是我們的未來。\r\n\r\n本系列講座特以海洋生物為主題，邀讀者來國圖一起遊書海，重新發掘海底之美。在這個結合文學與影像的旅程中，我們可以激發無限的想像力，「波滔滔兮來迎，魚鱗鱗兮媵予」，我們也可以像自由自在的魚一樣，遨遊四海。而今年與國立海洋生物博物館以及臺灣海洋教育中心攜手合作，並加碼手作課程，讓大朋友小朋友都來本館多媒體實驗中心體驗知識的樂趣。2025春季閱讀講座讓我們一起追隨經典海洋故事的足跡，探索那些仍在等待揭示的深海奧秘。\r\n\r\n第四場4/12松松X拉亞主講「海洋聲音的浪潮：打造吸引人的 Podcast 從內容策劃到上架全攻略」\r\n\r\n報名日期：即日起~2024/4/9\r\n\r\n課程時間及地點：\r\n時　　間：民國114年4月12日（星期六）下午2:00~5:00\r\n地　　點：國家圖書館藝文中心3樓國際會議廳（臺北市中山南路20號）\r\n主題活動網址：https://actio.ncl.edu.tw/114_spring\r\n活動報名網址：https://actio.ncl.edu.tw/activitydetails?uid=6&pid=714\r\n', '國家圖書館', '臺北市中正區中山南路20號', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '國家圖書館', 25.03240487, 121.5198839, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【波滔滔兮來迎，魚鱗鱗兮媵予：從文學到影像，從回顧到創造】第四場4/12松松X拉亞主講「海洋聲音的浪潮：打造吸引人的 Podcast 從內容策劃到上架全攻略」', `description`='海洋一直是最不可思議的世界，而潛藏在水底深處的海洋生物，持續在古老的神話與文學作品中引發無盡的想像，並在現代影像中綻放出新的光芒。海洋生物富有生命力，山海經曾提到：「東海之渚中，有神」，而海洋作家夏曼．藍波安筆下關於蘭嶼的飛魚神話，或是紀錄片《刪海經》「鱟」的獨特身影，海洋生物的故事是文學、是影像、是生活、也是我們的未來。\r\n\r\n本系列講座特以海洋生物為主題，邀讀者來國圖一起遊書海，重新發掘海底之美。在這個結合文學與影像的旅程中，我們可以激發無限的想像力，「波滔滔兮來迎，魚鱗鱗兮媵予」，我們也可以像自由自在的魚一樣，遨遊四海。而今年與國立海洋生物博物館以及臺灣海洋教育中心攜手合作，並加碼手作課程，讓大朋友小朋友都來本館多媒體實驗中心體驗知識的樂趣。2025春季閱讀講座讓我們一起追隨經典海洋故事的足跡，探索那些仍在等待揭示的深海奧秘。\r\n\r\n第四場4/12松松X拉亞主講「海洋聲音的浪潮：打造吸引人的 Podcast 從內容策劃到上架全攻略」\r\n\r\n報名日期：即日起~2024/4/9\r\n\r\n課程時間及地點：\r\n時　　間：民國114年4月12日（星期六）下午2:00~5:00\r\n地　　點：國家圖書館藝文中心3樓國際會議廳（臺北市中山南路20號）\r\n主題活動網址：https://actio.ncl.edu.tw/114_spring\r\n活動報名網址：https://actio.ncl.edu.tw/activitydetails?uid=6&pid=714\r\n', `organizer`='國家圖書館', `address`='臺北市中正區中山南路20號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='國家圖書館', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e7f26b3240c403d9763', '【波滔滔兮來迎，魚鱗鱗兮媵予：從文學到影像，從回顧到創造】第六場5/03羅雅真老師主講「微講座暨工作坊：誰吃誰？海洋生態大解密！」', '海洋一直是最不可思議的世界，而潛藏在水底深處的海洋生物，持續在古老的神話與文學作品中引發無盡的想像，並在現代影像中綻放出新的光芒。海洋生物富有生命力，山海經曾提到：「東海之渚中，有神」，而海洋作家夏曼．藍波安筆下關於蘭嶼的飛魚神話，或是紀錄片《刪海經》「鱟」的獨特身影，海洋生物的故事是文學、是影像、是生活、也是我們的未來。\r\n\r\n本系列講座特以海洋生物為主題，邀讀者來國圖一起遊書海，重新發掘海底之美。在這個結合文學與影像的旅程中，我們可以激發無限的想像力，「波滔滔兮來迎，魚鱗鱗兮媵予」，我們也可以像自由自在的魚一樣，遨遊四海。而今年與國立海洋生物博物館以及臺灣海洋教育中心攜手合作，並加碼手作課程，讓大朋友小朋友都來本館多媒體實驗中心體驗知識的樂趣。2025春季閱讀講座讓我們一起追隨經典海洋故事的足跡，探索那些仍在等待揭示的深海奧秘。\r\n\r\n第六場5/03羅雅真老師主講「微講座暨工作坊：誰吃誰？海洋生態大解密！」\r\n\r\n報名日期：即日起~2024/4/30\r\n\r\n課程時間及地點：\r\n時　　間：民國114年5月3日（星期六）下午2:00~5:00\r\n地　　點：國家圖書館多媒體創意實驗中心 OPEN LAB（臺北市中正區秀山街4號14樓）\r\n主題活動網址：https://actio.ncl.edu.tw/114_spring\r\n活動報名網址：https://actio.ncl.edu.tw/activitydetails?uid=6&pid=714\r\n', '國家圖書館', '臺北市中正區中山南路20號', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '國家圖書館', 25.03240487, 121.5198839, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【波滔滔兮來迎，魚鱗鱗兮媵予：從文學到影像，從回顧到創造】第六場5/03羅雅真老師主講「微講座暨工作坊：誰吃誰？海洋生態大解密！」', `description`='海洋一直是最不可思議的世界，而潛藏在水底深處的海洋生物，持續在古老的神話與文學作品中引發無盡的想像，並在現代影像中綻放出新的光芒。海洋生物富有生命力，山海經曾提到：「東海之渚中，有神」，而海洋作家夏曼．藍波安筆下關於蘭嶼的飛魚神話，或是紀錄片《刪海經》「鱟」的獨特身影，海洋生物的故事是文學、是影像、是生活、也是我們的未來。\r\n\r\n本系列講座特以海洋生物為主題，邀讀者來國圖一起遊書海，重新發掘海底之美。在這個結合文學與影像的旅程中，我們可以激發無限的想像力，「波滔滔兮來迎，魚鱗鱗兮媵予」，我們也可以像自由自在的魚一樣，遨遊四海。而今年與國立海洋生物博物館以及臺灣海洋教育中心攜手合作，並加碼手作課程，讓大朋友小朋友都來本館多媒體實驗中心體驗知識的樂趣。2025春季閱讀講座讓我們一起追隨經典海洋故事的足跡，探索那些仍在等待揭示的深海奧秘。\r\n\r\n第六場5/03羅雅真老師主講「微講座暨工作坊：誰吃誰？海洋生態大解密！」\r\n\r\n報名日期：即日起~2024/4/30\r\n\r\n課程時間及地點：\r\n時　　間：民國114年5月3日（星期六）下午2:00~5:00\r\n地　　點：國家圖書館多媒體創意實驗中心 OPEN LAB（臺北市中正區秀山街4號14樓）\r\n主題活動網址：https://actio.ncl.edu.tw/114_spring\r\n活動報名網址：https://actio.ncl.edu.tw/activitydetails?uid=6&pid=714\r\n', `organizer`='國家圖書館', `address`='臺北市中正區中山南路20號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `loc