INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e7f26b3240c403d9764', '【新北市立圖書館樹林樂山圖書閱覽室】114年2月主題書展 ', '世界童話故事\r\n除了格林童話、安徒生童話這些家喻戶曉的故事集，其他國家也有很多充滿正義、勇氣、智慧、好品格……的故事，快來一起進入童話世界吧！\r\n\r\n活動時間：114年02月01日至02月28日\r\n\r\n活動地點︰樹林樂山圖書閱覽室主題展示區(樹林區中和街38號)\r\n \r\n洽詢電話：(02) 2680-7120\r\n \r\n※展示期間，歡迎借閱。\r\n', '新北市立圖書館總館', '新北市樹林區中和街38號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '新北市立圖書館樹林樂山圖書閱覽室', 24.97970609, 121.401034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館樹林樂山圖書閱覽室】114年2月主題書展 ', `description`='世界童話故事\r\n除了格林童話、安徒生童話這些家喻戶曉的故事集，其他國家也有很多充滿正義、勇氣、智慧、好品格……的故事，快來一起進入童話世界吧！\r\n\r\n活動時間：114年02月01日至02月28日\r\n\r\n活動地點︰樹林樂山圖書閱覽室主題展示區(樹林區中和街38號)\r\n \r\n洽詢電話：(02) 2680-7120\r\n \r\n※展示期間，歡迎借閱。\r\n', `organizer`='新北市立圖書館總館', `address`='新北市樹林區中和街38號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='新北市立圖書館樹林樂山圖書閱覽室', `latitude`=24.97970609, `longitude`=121.401034, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
