INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8226b3240c403d9767', '【中市圖潭子分館】主題書展2月(2場)', '~2月主題書展~\r\n\r\n~原客閩新展魅力~ ~世界母語好溫馨~\r\n\r\n為展現「原客閩新展魅力 世界母語好溫馨」之主題，及推廣世界母語日之精神，閩南、新住民、客家、原住民展現本土語言與族群文化傳承，族群文化的兼容並蓄，共同響應母語傳承的重要。\r\n(貼心小提醒:書展當中有部分書籍，必須等到書展結束，才開始提供外借喔!)\r\n\r\n●時間：114年2月1日(六)~114年2月28日(五) 8:30~21:00\r\n●地點：中市圖潭子分館 1樓展覽區\r\n----------------------------------------------\r\n~2月主題書展~\r\n\r\n新年到 慶元宵 猜燈謎\r\n\r\n春節，讓我們從送灶神開始，辦年貨、認識年獸、吃團圓飯，也聽聽12生肖的故事。\r\n正月十五元宵節，猜燈謎、提花燈、放煙花過小年後，才算真正完成了「過年」的慶祝。\r\n\r\n想知道更多有關春節節日的相關習俗嗎？本館準備相關書籍，歡迎到館借閱。\r\n\r\n●時間：114年2月1日(六)~114年2月28日(五) 8:30~21:00\r\n●地點：中市圖潭子分館 3樓展覽區\r\n', '臺中市立圖書館潭子分館', '臺中市潭子區中山路二段399號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺中市立圖書館潭子分館', 24.21171121, 120.710997, '無資料', 'https://www.library.taichung.gov.tw/public/topreview/index-1.asp?Parser=99,20,697,50,,,24216', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖潭子分館】主題書展2月(2場)', `description`='~2月主題書展~\r\n\r\n~原客閩新展魅力~ ~世界母語好溫馨~\r\n\r\n為展現「原客閩新展魅力 世界母語好溫馨」之主題，及推廣世界母語日之精神，閩南、新住民、客家、原住民展現本土語言與族群文化傳承，族群文化的兼容並蓄，共同響應母語傳承的重要。\r\n(貼心小提醒:書展當中有部分書籍，必須等到書展結束，才開始提供外借喔!)\r\n\r\n●時間：114年2月1日(六)~114年2月28日(五) 8:30~21:00\r\n●地點：中市圖潭子分館 1樓展覽區\r\n----------------------------------------------\r\n~2月主題書展~\r\n\r\n新年到 慶元宵 猜燈謎\r\n\r\n春節，讓我們從送灶神開始，辦年貨、認識年獸、吃團圓飯，也聽聽12生肖的故事。\r\n正月十五元宵節，猜燈謎、提花燈、放煙花過小年後，才算真正完成了「過年」的慶祝。\r\n\r\n想知道更多有關春節節日的相關習俗嗎？本館準備相關書籍，歡迎到館借閱。\r\n\r\n●時間：114年2月1日(六)~114年2月28日(五) 8:30~21:00\r\n●地點：中市圖潭子分館 3樓展覽區\r\n', `organizer`='臺中市立圖書館潭子分館', `address`='臺中市潭子區中山路二段399號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市立圖書館潭子分館', `latitude`=24.21171121, `longitude`=120.710997, `ticket_price`='無資料', `source_url`='https://www.library.taichung.gov.tw/public/topreview/index-1.asp?Parser=99,20,697,50,,,24216', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8226b3240c403d9769', '無資料', '1.本活動為例行性週日10:30~11:30說故事。\r\n地點:2樓幼兒閱讀區\r\n2.故事名稱：\r\n2/2 不要隨便跟陌生人走/童話童田教育團隊林雅薇\r\n2/16 膽小龍/台中市山海屯故事協會王淑芬\r\n2/23 貪心的貝貝/翁銘壎', '臺中市立圖書館烏日分館', '臺中市烏日區興祥街121號', '臺中市立圖書館烏日分館', 24.1096375, 120.6374111, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='1.本活動為例行性週日10:30~11:30說故事。\r\n地點:2樓幼兒閱讀區\r\n2.故事名稱：\r\n2/2 不要隨便跟陌生人走/童話童田教育團隊林雅薇\r\n2/16 膽小龍/台中市山海屯故事協會王淑芬\r\n2/23 貪心的貝貝/翁銘壎', `organizer`='臺中市立圖書館烏日分館', `address`='臺中市烏日區興祥街121號', `location`='臺中市立圖書館烏日分館', `latitude`=24.1096375, `longitude`=120.6374111, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8226b3240c403d976a', '舒發意象 妏心昂揚-陳舒妏個展', '我是陳舒妏，今年31歲，是一名唐氏症患者。但對我來說，這個標籤並不限制我的生命，而是讓我更努力突破自我、活出屬於自己的精彩人生。\r\n\r\n從小，我就對藝術有濃厚的興趣。無論是繪畫還是紙黏土，我都能沉浸在創作的世界中，感受到純粹的快樂與成就感。透過手中的畫筆和紙黏土，我不僅創造了各種色彩斑斕的作品，更用這些作品表達了我的內心與情感。每一幅畫、每一件黏土作品，都是我與世界溝通的方式，彷彿在告訴大家：「看，我的世界也很美！」', '無資料', '臺中市太平區大興路201號', '2025-02-15 00:00:00', '2025-03-09 00:00:00', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', 'https://www.ttdac.taichung.gov.tw/nb5406283333916174353/nbArticleContent', '[]') ON DUPLICATE KEY UPDATE `activity_name`='舒發意象 妏心昂揚-陳舒妏個展', `description`='我是陳舒妏，今年31歲，是一名唐氏症患者。但對我來說，這個標籤並不限制我的生命，而是讓我更努力突破自我、活出屬於自己的精彩人生。\r\n\r\n從小，我就對藝術有濃厚的興趣。無論是繪畫還是紙黏土，我都能沉浸在創作的世界中，感受到純粹的快樂與成就感。透過手中的畫筆和紙黏土，我不僅創造了各種色彩斑斕的作品，更用這些作品表達了我的內心與情感。每一幅畫、每一件黏土作品，都是我與世界溝通的方式，彷彿在告訴大家：「看，我的世界也很美！」', `organizer`='無資料', `address`='臺中市太平區大興路201號', `start_date`='2025-02-15 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='https://www.ttdac.taichung.gov.tw/nb5406283333916174353/nbArticleContent', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8226b3240c403d976b', '涵融萬殊八 — 臺中市東方水墨畫會會員團體展', '臺中市東方水墨畫會是由水墨行者何木火大師於90年策劃成立，其主要成員是何木火大師的學生來自中部地區的學員所組成，成立以來推展藝術不遺餘力，於98年正式向台中縣政府申請立案，後因縣市合併於102年4月更改現名。在何木火大師不斷推廣繪畫教育下，會員們在各縣市文化中心，各區公務機關陸續舉辦個展，更在各項美展比賽中，屢獲獎項成績斐然，新秀備出。臺中市水墨薪傳獎得主學員就有三位陳從珍、塗文超、易亭伃老師等。\r\n\r\n榮譽理事長「水墨行者」何木火大師已於98年10月起，在台視健康娛樂台播放「水墨行者何木火 揮灑台灣之美」電視水墨教學DVD365集，何大師將水墨觀念技法鉅細靡遺一一示範，是一部對水墨學習者最佳的教學利器，引起廣大迴響。在2010年以作品《古林秘境》在香港「國際香港亞洲週」的四國連拍中告捷，《秋痕》在金仕發春拍中拍定，同年11月行草《臨江仙》也於“易拍好”2010秋拍中拍定，奠定「水墨行者」何木火大師的作品在藝術拍賣市場的價值。\r\n\r\n臺中市東方水墨畫會的成立，是為提倡藝術氣息、培養藝術人才、增廣創作領域、開闢藝術人生。會員除定期的藝術研習與文化活動，增進會員情誼，也藉會員團體展與社會大眾互相切磋勉勵，每年提供展最新完成的創作或最新美展得獎作品辦理展覽；會員們盼藉展覽拋磚引玉，促進社會正能量正思維，期許水墨精神如東方之光生生不息。', '無資料', '臺中市太平區大興路201號', '2025-02-22 00:00:00', '2025-03-16 00:00:00', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', 'https://www.ttdac.taichung.gov.tw/nb5206553402552704853/nbArticleContent', '[]') ON DUPLICATE KEY UPDATE `activity_name`='涵融萬殊八 — 臺中市東方水墨畫會會員團體展', `description`='臺中市東方水墨畫會是由水墨行者何木火大師於90年策劃成立，其主要成員是何木火大師的學生來自中部地區的學員所組成，成立以來推展藝術不遺餘力，於98年正式向台中縣政府申請立案，後因縣市合併於102年4月更改現名。在何木火大師不斷推廣繪畫教育下，會員們在各縣市文化中心，各區公務機關陸續舉辦個展，更在各項美展比賽中，屢獲獎項成績斐然，新秀備出。臺中市水墨薪傳獎得主學員就有三位陳從珍、塗文超、易亭伃老師等。\r\n\r\n榮譽理事長「水墨行者」何木火大師已於98年10月起，在台視健康娛樂台播放「水墨行者何木火 揮灑台灣之美」電視水墨教學DVD365集，何大師將水墨觀念技法鉅細靡遺一一示範，是一部對水墨學習者最佳的教學利器，引起廣大迴響。在2010年以作品《古林秘境》在香港「國際香港亞洲週」的四國連拍中告捷，《秋痕》在金仕發春拍中拍定，同年11月行草《臨江仙》也於“易拍好”2010秋拍中拍定，奠定「水墨行者」何木火大師的作品在藝術拍賣市場的價值。\r\n\r\n臺中市東方水墨畫會的成立，是為提倡藝術氣息、培養藝術人才、增廣創作領域、開闢藝術人生。會員除定期的藝術研習與文化活動，增進會員情誼，也藉會員團體展與社會大眾互相切磋勉勵，每年提供展最新完成的創作或最新美展得獎作品辦理展覽；會員們盼藉展覽拋磚引玉，促進社會正能量正思維，期許水墨精神如東方之光生生不息。', `organizer`='無資料', `address`='臺中市太平區大興路201號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='https://www.ttdac.taichung.gov.tw/nb5206553402552704853/nbArticleContent', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8226b3240c403d976c', '無資料', '狂美《讓我們從白雪公主開始》交響音樂會\r\n樂音與童話交織，交響音樂會炫目登場 🌌 ✨\r\n2/21導聆:郭彥均、歌手:周定緯 2/22 導聆:陳明珠 歌手:梁文音\r\n\r\n樂音與童話交織的詩篇\r\n\r\n一切源起 都從那顆被咬一口的毒蘋果開始🍎 …\r\n翻開手上厚厚的精裝書，🏰 銀白色華麗城堡躍然紙上！\r\n好多故事的開端都是這樣。\r\n忙著工作的小矮人們在森林中🌳列隊吹起了口哨、\r\n閃耀長髮的公主睜大眼睛，嚮往高塔外的老鷹翱翔🦅\r\n有的呢⋯\r\n則在遙遠的雪國看著麋鹿與雪人興奮的互打雪仗！\r\n對了，千萬別忘了午夜12點大鐘響🕰️！\r\n🎠-🎃 南瓜馬車在路上奔馳找尋灰姑娘。\r\n\r\n\r\n狂美樂隊裡的樂手們，奏響一首首童話主題曲的悠揚\r\n公主👸與王子🤴們，穿上禮服在舞台上高唱愛與夢想\r\n當然，那位在現場說故事的領航者一樣重要。\r\n序章，翻開 Ep. 1 📖\r\n「讓我們從白雪公主開始」步步走進狂美的綺麗樂章 🎼\r\n【全場次演出曲目】\r\n《白雪公主》 Whistle While You Work\r\n《魔髮奇緣》 "Tangled" Medley\r\n《仙履奇緣》 Cinderella\r\n《海洋奇緣》 Selections from "Moana"\r\n《鐘樓怪人》 The Bells of Notre Dame\r\n《獅子王》 "The Lion King" Medley\r\n《魔法滿屋》 Symphonic Highlights from "ENCANTO"\r\n【👸公主獻唱版 - 限定演出曲目】\r\n《冰雪奇緣》放開手 Let it Go\r\n《小美人魚》嚮往的世界 Part of Your World\r\n《木蘭》 心湖倒影 Reflection\r\n【🤴王子獻唱版 - 限定演出曲目】\r\n《阿拉丁》阿里王子 Prince Ali\r\n《大力士》去向遠方 Go The Distance\r\n《泰山》永存我心 You''ll Be In My Heart\r\n\r\n', '無資料', '臺中市太平區大興路201號', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='狂美《讓我們從白雪公主開始》交響音樂會\r\n樂音與童話交織，交響音樂會炫目登場 🌌 ✨\r\n2/21導聆:郭彥均、歌手:周定緯 2/22 導聆:陳明珠 歌手:梁文音\r\n\r\n樂音與童話交織的詩篇\r\n\r\n一切源起 都從那顆被咬一口的毒蘋果開始🍎 …\r\n翻開手上厚厚的精裝書，🏰 銀白色華麗城堡躍然紙上！\r\n好多故事的開端都是這樣。\r\n忙著工作的小矮人們在森林中🌳列隊吹起了口哨、\r\n閃耀長髮的公主睜大眼睛，嚮往高塔外的老鷹翱翔🦅\r\n有的呢⋯\r\n則在遙遠的雪國看著麋鹿與雪人興奮的互打雪仗！\r\n對了，千萬別忘了午夜12點大鐘響🕰️！\r\n🎠-🎃 南瓜馬車在路上奔馳找尋灰姑娘。\r\n\r\n\r\n狂美樂隊裡的樂手們，奏響一首首童話主題曲的悠揚\r\n公主👸與王子🤴們，穿上禮服在舞台上高唱愛與夢想\r\n當然，那位在現場說故事的領航者一樣重要。\r\n序章，翻開 Ep. 1 📖\r\n「讓我們從白雪公主開始」步步走進狂美的綺麗樂章 🎼\r\n【全場次演出曲目】\r\n《白雪公主》 Whistle While You Work\r\n《魔髮奇緣》 "Tangled" Medley\r\n《仙履奇緣》 Cinderella\r\n《海洋奇緣》 Selections from "Moana"\r\n《鐘樓怪人》 The Bells of Notre Dame\r\n《獅子王》 "The Lion King" Medley\r\n《魔法滿屋》 Symphonic Highlights from "ENCANTO"\r\n【👸公主獻唱版 - 限定演出曲目】\r\n《冰雪奇緣》放開手 Let it Go\r\n《小美人魚》嚮往的世界 Part of Your World\r\n《木蘭》 心湖倒影 Reflection\r\n【🤴王子獻唱版 - 限定演出曲目】\r\n《阿拉丁》阿里王子 Prince Ali\r\n《大力士》去向遠方 Go The Distance\r\n《泰山》永存我心 You''ll Be In My Heart\r\n\r\n', `organizer`='無資料', `address`='臺中市太平區大興路201號', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8226b3240c403d976e', '無資料', '女主角IVY，學生時期是啦啦隊長，畢業後在航空公司擔任空服員20多年。因公司經營變革，無預警遭裁員。家中老父失智多年，工作與照顧父親佔據了她的生活，最終導致男友提出分手。\r\n\r\n失業、失戀與家庭壓力接踵而來，讓她難以喘息。正當人生陷入低谷，一支啦啦隊比賽影片喚醒了她的熱情，促使她決定找回校友，重組隊伍參賽。\r\n\r\n一場關於友情、歡笑與感動的旅程就此展開。這群橫跨老中青三代的校友如何聚在一起？他們又將經歷哪些意想不到的挑戰與奇蹟？\r\n\r\n這是一部笑中帶淚、熱血溫馨，超乎想像的勵志電影，等你「一起一起」，一探究竟。\r\n\r\n報名連結：https://www.accupass.com/event/2501030138021839298543', '臺中市屯區藝文中心', '臺中市太平區大興路201號', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='女主角IVY，學生時期是啦啦隊長，畢業後在航空公司擔任空服員20多年。因公司經營變革，無預警遭裁員。家中老父失智多年，工作與照顧父親佔據了她的生活，最終導致男友提出分手。\r\n\r\n失業、失戀與家庭壓力接踵而來，讓她難以喘息。正當人生陷入低谷，一支啦啦隊比賽影片喚醒了她的熱情，促使她決定找回校友，重組隊伍參賽。\r\n\r\n一場關於友情、歡笑與感動的旅程就此展開。這群橫跨老中青三代的校友如何聚在一起？他們又將經歷哪些意想不到的挑戰與奇蹟？\r\n\r\n這是一部笑中帶淚、熱血溫馨，超乎想像的勵志電影，等你「一起一起」，一探究竟。\r\n\r\n報名連結：https://www.accupass.com/event/2501030138021839298543', `organizer`='臺中市屯區藝文中心', `address`='臺中市太平區大興路201號', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8326b3240c403d976f', '無資料', '    說故事與閱讀長久以來一直就在親子互動過程中扮演著重要的角色，藉由多元的說演故事活動，以故事為橋樑，啟發孩子閱讀的興趣，激發孩子無窮的想像力與創造力。歡迎大、小朋友一同來屯區聽故事～', '臺中市屯區藝文中心', '臺中市太平區大興路201號', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='    說故事與閱讀長久以來一直就在親子互動過程中扮演著重要的角色，藉由多元的說演故事活動，以故事為橋樑，啟發孩子閱讀的興趣，激發孩子無窮的想像力與創造力。歡迎大、小朋友一同來屯區聽故事～', `organizer`='臺中市屯區藝文中心', `address`='臺中市太平區大興路201號', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8326b3240c403d9770', '【臺中市立圖書館潭子分館】「時序」~蔡美環油畫個展~', '【臺中市立圖書館潭子分館】「時序」~蔡美環油畫個展~\r\n\r\n訂於114年2月舉辦「時序」蔡美環油畫個展，歡迎大家踴躍參觀。\r\n畫家蔡美環以油畫來描繪出時序\r\n本展覽展現農村風光，有靜物、創作、印象，有寫實多元展現油畫的多樣性。\r\n作者喜愛鄉村風景並展現兒時記憶，將它創作並用油畫表現出來。\r\n\r\n●時間：114年2月8日(六)~114年2月27日(四)8:30~21:00\r\n●地點：臺中市立圖書館潭子分館 B1多功能活動室\r\n', '臺中市立圖書館潭子分館', '臺中市潭子區中山路二段399號', '2025-02-08 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館潭子分館', 24.21171121, 120.710997, '無資料', 'https://www.library.taichung.gov.tw/public/topreview/index-1.asp?Parser=99,20,697,50,,,24275', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【臺中市立圖書館潭子分館】「時序」~蔡美環油畫個展~', `description`='【臺中市立圖書館潭子分館】「時序」~蔡美環油畫個展~\r\n\r\n訂於114年2月舉辦「時序」蔡美環油畫個展，歡迎大家踴躍參觀。\r\n畫家蔡美環以油畫來描繪出時序\r\n本展覽展現農村風光，有靜物、創作、印象，有寫實多元展現油畫的多樣性。\r\n作者喜愛鄉村風景並展現兒時記憶，將它創作並用油畫表現出來。\r\n\r\n●時間：114年2月8日(六)~114年2月27日(四)8:30~21:00\r\n●地點：臺中市立圖書館潭子分館 B1多功能活動室\r\n', `organizer`='臺中市立圖書館潭子分館', `address`='臺中市潭子區中山路二段399號', `start_date`='2025-02-08 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館潭子分館', `latitude`=24.21171121, `longitude`=120.710997, `ticket_price`='無資料', `source_url`='https://www.library.taichung.gov.tw/public/topreview/index-1.asp?Parser=99,20,697,50,,,24275', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8626b3240c403d9773', '同窗灼灼 林永松陶藝&湯雙進西畫雙個展', '當年離開教職選擇專業做陶，除了對陶藝本身的熱愛之外，也冀望藉此扛起家庭經濟重擔，是以當時市場的脈動常左右整個工作室的風格走向。\r\n近年來不再汲汲營營於他人的好惡，窯體由原先的電窯、兩用窯到現在的瓦斯窯，除了重拾當年在華岡做陶的初衷，更想一探陶藝世界的諸多美好！銅釉與灰釉向來是我喜歡嘗試與表現的釉色，尤其銅釉、氧化還原各有殊勝；也因為變數大與原先預期有相當落差，常在出窯後只留少數甚至把整窯作品打掉，只為那份莫名的堅持！\r\n這次展覽提供了幾件早期化妝土作品以展現不同時期的作陶情懷。期望大家來指正！(撰文：林永松)\r\n\r\n光是變幻端的魔術師，它在天地間漫游，為景物披上一層層不同的色彩與情感。《隨光逐流》延續2023年在國父紀念館個展的基調，試圖捕捉光影變化下的自然之美，以具象的表現手法呈現山林、水流、花草、錦鯉等主題，透過瞬間的光影交錯，展現景物轉瞬即逝的美感。\r\n山間晨曦的金黃、溪流的粼粼波光、花朵在微風中閃爍的光彩，都是時間與光影交織的瞬間詩篇。我試圖以細膩的筆觸與層層堆疊的色彩，捕捉這些微妙變化，讓觀者在畫面中感受光的律動與流轉。\r\n流水，是展覽中的重要意象之一。水在光的映照下呈現不同的面貌，有時如絲綢般柔和，有時如鏡面般清澈，亦或是在波動間折射出萬千色彩。錦鯉悠遊於水波間，它們的身影因光線折射而變幻莫測，呈現出靈動的生命力，象徵著隨遇而安的自在。\r\n而山林與花草則象徵著靜謐與生機。當光線灑落於樹葉間，映照出斑駁的陰影，或是在晨霧中柔和地渲染景色，那一刻的美是不可復刻的。我希望透過畫筆，將這些大自然的片刻之美凝結於畫布、紙張之上，讓觀者在欣賞作品時，感受到光影流轉的韻律，並在繁忙的生活中，找到一絲寧靜與共鳴。\r\n《隨光逐流》，不僅是一場視覺的饗宴，更是對光與時間、對自然與生命的一種思考。我希望透過這次展覽，讓觀者體會光影帶來的情感共鳴，並從中發現每一個瞬間的珍貴與美好。(撰文：湯雙進)\r\n', '孟焦畫廊', '臺北市士林區雨農路17-2號1樓', '2025-03-16 00:00:00', '2025-03-30 00:00:00', '孟焦畫坊', 25.12546704, 121.5508473, '無資料', 'https://web.hocom.tw/h/?key=399852860856', '[]') ON DUPLICATE KEY UPDATE `activity_name`='同窗灼灼 林永松陶藝&湯雙進西畫雙個展', `description`='當年離開教職選擇專業做陶，除了對陶藝本身的熱愛之外，也冀望藉此扛起家庭經濟重擔，是以當時市場的脈動常左右整個工作室的風格走向。\r\n近年來不再汲汲營營於他人的好惡，窯體由原先的電窯、兩用窯到現在的瓦斯窯，除了重拾當年在華岡做陶的初衷，更想一探陶藝世界的諸多美好！銅釉與灰釉向來是我喜歡嘗試與表現的釉色，尤其銅釉、氧化還原各有殊勝；也因為變數大與原先預期有相當落差，常在出窯後只留少數甚至把整窯作品打掉，只為那份莫名的堅持！\r\n這次展覽提供了幾件早期化妝土作品以展現不同時期的作陶情懷。期望大家來指正！(撰文：林永松)\r\n\r\n光是變幻端的魔術師，它在天地間漫游，為景物披上一層層不同的色彩與情感。《隨光逐流》延續2023年在國父紀念館個展的基調，試圖捕捉光影變化下的自然之美，以具象的表現手法呈現山林、水流、花草、錦鯉等主題，透過瞬間的光影交錯，展現景物轉瞬即逝的美感。\r\n山間晨曦的金黃、溪流的粼粼波光、花朵在微風中閃爍的光彩，都是時間與光影交織的瞬間詩篇。我試圖以細膩的筆觸與層層堆疊的色彩，捕捉這些微妙變化，讓觀者在畫面中感受光的律動與流轉。\r\n流水，是展覽中的重要意象之一。水在光的映照下呈現不同的面貌，有時如絲綢般柔和，有時如鏡面般清澈，亦或是在波動間折射出萬千色彩。錦鯉悠遊於水波間，它們的身影因光線折射而變幻莫測，呈現出靈動的生命力，象徵著隨遇而安的自在。\r\n而山林與花草則象徵著靜謐與生機。當光線灑落於樹葉間，映照出斑駁的陰影，或是在晨霧中柔和地渲染景色，那一刻的美是不可復刻的。我希望透過畫筆，將這些大自然的片刻之美凝結於畫布、紙張之上，讓觀者在欣賞作品時，感受到光影流轉的韻律，並在繁忙的生活中，找到一絲寧靜與共鳴。\r\n《隨光逐流》，不僅是一場視覺的饗宴，更是對光與時間、對自然與生命的一種思考。我希望透過這次展覽，讓觀者體會光影帶來的情感共鳴，並從中發現每一個瞬間的珍貴與美好。(撰文：湯雙進)\r\n', `organizer`='孟焦畫廊', `address`='臺北市士林區雨農路17-2號1樓', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='孟焦畫坊', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='無資料', `source_url`='https://web.hocom.tw/h/?key=399852860856', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8826b3240c403d9774', '《漂流 (序曲) -沈昭良攝影展》', '「對台灣人來說，特別是在解嚴之後，國家認同與疆界一直是內部分歧和爭執的根源。包括過往的歷史和印記，這些看似不見卻又潛藏的真實，正在形塑我們的命運發展和可能願景。」 - 沈昭良\r\n\r\n「漂流」系列梳理過去十年來台灣內部含括殖民主義、國家認同、族群、冷戰、人權、原住民、生態、環境、能源等等潛在課題。這些複雜且龐大的議題，都在藝術家沈昭良兼具寫實與敘情的拍攝視野中轉為深邃的情感訴諸。「漂流」，第一眼抓住你的或許是熟悉的天空、台灣特有的體感濕度、樹路燈。而後還看進了微妙而有力的鄉土情愁與文化的斑斑痕跡，盡在繁枝細節裡隱隱發酵。每一處地景既是對台灣土地的真實呈現，更是對歷史記憶如何影響台灣人民的身份認同與文化傳承的細膩描繪，凝視同時也忍不住地跳出許多反思詰問，藉此擴大了每件作品涵蓋的故事縱深。\r\n\r\n2025.02.13 (四) - 2025.03.22 (六) 藝術家沈昭良以獨到的視角和符號化的風景意象，引領觀者參與這場對話，進入具有強烈時代感的視覺旅程。\r\n\r\n▌藝術座談：複返敘事與迴流風景：沈昭良的攝影創作實踐\r\n2025.02.22 (六) 15:30 – 17:30\r\n主持人 | 沈裕融 / 華梵大學攝影與VR設計系 助理教授\r\n與談人 | 鄭乃銘 / 當代藝術新聞 總編輯\r\n沈昭良 / 華梵大學攝影與VR設計系 教授\r\n\r\n▌藝術座談：凝視風景 - 沈昭良地景攝影中的敘情與詩性\r\n2025.03.08 (六) 15:30 – 17:30\r\n主持人 | 龔卓軍 / 台南藝術大學藝術創作理論研究所博士班 教授\r\n與談人 | 栖來光 / 旅台日籍作家\r\n王聖閎 / 中央大學藝術學研究所 助理教授\r\n沈昭良 / 華梵大學攝影與VR設計系 教授', '也趣藝廊', '臺北市大同區民族西路141號', '2025-02-13 00:00:00', '2025-03-22 00:00:00', '也趣藝廊 AKI Gallery', 25.06342433, 121.5130417, '無資料', 'https://www.galleryaki.com/zh/exhibition/content/post/293', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《漂流 (序曲) -沈昭良攝影展》', `description`='「對台灣人來說，特別是在解嚴之後，國家認同與疆界一直是內部分歧和爭執的根源。包括過往的歷史和印記，這些看似不見卻又潛藏的真實，正在形塑我們的命運發展和可能願景。」 - 沈昭良\r\n\r\n「漂流」系列梳理過去十年來台灣內部含括殖民主義、國家認同、族群、冷戰、人權、原住民、生態、環境、能源等等潛在課題。這些複雜且龐大的議題，都在藝術家沈昭良兼具寫實與敘情的拍攝視野中轉為深邃的情感訴諸。「漂流」，第一眼抓住你的或許是熟悉的天空、台灣特有的體感濕度、樹路燈。而後還看進了微妙而有力的鄉土情愁與文化的斑斑痕跡，盡在繁枝細節裡隱隱發酵。每一處地景既是對台灣土地的真實呈現，更是對歷史記憶如何影響台灣人民的身份認同與文化傳承的細膩描繪，凝視同時也忍不住地跳出許多反思詰問，藉此擴大了每件作品涵蓋的故事縱深。\r\n\r\n2025.02.13 (四) - 2025.03.22 (六) 藝術家沈昭良以獨到的視角和符號化的風景意象，引領觀者參與這場對話，進入具有強烈時代感的視覺旅程。\r\n\r\n▌藝術座談：複返敘事與迴流風景：沈昭良的攝影創作實踐\r\n2025.02.22 (六) 15:30 – 17:30\r\n主持人 | 沈裕融 / 華梵大學攝影與VR設計系 助理教授\r\n與談人 | 鄭乃銘 / 當代藝術新聞 總編輯\r\n沈昭良 / 華梵大學攝影與VR設計系 教授\r\n\r\n▌藝術座談：凝視風景 - 沈昭良地景攝影中的敘情與詩性\r\n2025.03.08 (六) 15:30 – 17:30\r\n主持人 | 龔卓軍 / 台南藝術大學藝術創作理論研究所博士班 教授\r\n與談人 | 栖來光 / 旅台日籍作家\r\n王聖閎 / 中央大學藝術學研究所 助理教授\r\n沈昭良 / 華梵大學攝影與VR設計系 教授', `organizer`='也趣藝廊', `address`='臺北市大同區民族西路141號', `start_date`='2025-02-13 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='也趣藝廊 AKI Gallery', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='無資料', `source_url`='https://www.galleryaki.com/zh/exhibition/content/post/293', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8826b3240c403d9775', '【新北市立圖書館鶯歌分館】114年3月主題書展 ', '魅力歐洲之行，帶你走進經典\r\n\r\n踏上這趟歐洲之旅，感受巴黎的浪漫、羅馬的古老風情，探索盧浮宮的藝術瑰寶與梵蒂岡的神聖氣息。漫步阿姆斯特丹運河，欣賞阿爾卑斯山美景，品味義大利佳餚美酒，探訪德國童話小鎮。這是一次穿越時空的文化之旅，帶您發現經典之美！\r\n\r\n活動時間：114年03月01日至03月31日\r\n \r\n活動地點︰鶯歌分館1樓主題展示區(鶯歌區中山路150號)\r\n \r\n洽詢電話：（02）2678-0219#10\r\n\r\n※展示期間，歡迎借閱。', '新北市立圖書館總館', '新北市鶯歌區中山路150號B1至1樓及3至5樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館鶯歌分館', 24.9566258, 121.3466269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館鶯歌分館】114年3月主題書展 ', `description`='魅力歐洲之行，帶你走進經典\r\n\r\n踏上這趟歐洲之旅，感受巴黎的浪漫、羅馬的古老風情，探索盧浮宮的藝術瑰寶與梵蒂岡的神聖氣息。漫步阿姆斯特丹運河，欣賞阿爾卑斯山美景，品味義大利佳餚美酒，探訪德國童話小鎮。這是一次穿越時空的文化之旅，帶您發現經典之美！\r\n\r\n活動時間：114年03月01日至03月31日\r\n \r\n活動地點︰鶯歌分館1樓主題展示區(鶯歌區中山路150號)\r\n \r\n洽詢電話：（02）2678-0219#10\r\n\r\n※展示期間，歡迎借閱。', `organizer`='新北市立圖書館總館', `address`='新北市鶯歌區中山路150號B1至1樓及3至5樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館鶯歌分館', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8826b3240c403d9776', '【新北市立圖書館鶯歌二甲圖書閱覽室】114年3月主題書展 ', '為「女」寫書\r\n\r\n三月擁有屬於女性的節日──婦女節，在這個特殊的日子裡，我們將書籍與女性的靈魂交織，讓每一頁的文字都能講述妳們的故事，以書為橋，搭建一個屬於女性的世界。所以，請跟隨這個為「女」而生的主題書展，愜意地享受這個屬於「妳們」的月份。\r\n\r\n活動時間：114年03月01日至03月31日\r\n \r\n活動地點︰鶯歌二甲閱覽室主題展示區(鶯歌區二甲路288號2樓)\r\n \r\n洽詢電話：(02) 2679-8790\r\n\r\n※展示期間，歡迎借閱。', '新北市立圖書館總館', '新北市鶯歌區二甲路36-2號2樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館鶯歌二甲圖書閱覽室', 24.9566258, 121.3466269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館鶯歌二甲圖書閱覽室】114年3月主題書展 ', `description`='為「女」寫書\r\n\r\n三月擁有屬於女性的節日──婦女節，在這個特殊的日子裡，我們將書籍與女性的靈魂交織，讓每一頁的文字都能講述妳們的故事，以書為橋，搭建一個屬於女性的世界。所以，請跟隨這個為「女」而生的主題書展，愜意地享受這個屬於「妳們」的月份。\r\n\r\n活動時間：114年03月01日至03月31日\r\n \r\n活動地點︰鶯歌二甲閱覽室主題展示區(鶯歌區二甲路288號2樓)\r\n \r\n洽詢電話：(02) 2679-8790\r\n\r\n※展示期間，歡迎借閱。', `organizer`='新北市立圖書館總館', `address`='新北市鶯歌區二甲路36-2號2樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館鶯歌二甲圖書閱覽室', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8826b3240c403d9777', '春日・雲隱 – 王勁之 個展', '藝術家王勁之即將舉辦個展《春日・雲隱》，邀請觀眾進入他的藝術世界，透過他對生活、自然與自我的詮釋，感受隱藏於日常中的美。展覽將於2025年2月8日（星期六）至3月16日（星期日）展出，開幕式定於2025年2月9日（星期日）下午3:00，屆時藝術家將親臨現場，我們誠摯邀請您的蒞臨。\r\n\r\n對王勁之而言，創作是一場與自我對話的過程。他回憶起第一次拿起畫筆時的稚嫩與衝動，並將這份源自內心的驅動力視為持續創作的核心。他將創作比喻為在蔚藍深海中探險，探索未知，並在不斷嘗試中找到屬於自己的創作風格。\r\n\r\n王勁之對自然有著深厚情感，特別關注人與自然之間的微妙聯繫。展覽作品中，花卉和自然景象是他反覆表現的主題，他從日常生活中尋找美麗，將這些無聲的元素融入創作。他的天馬行空的想像力和細膩的觀察力，讓他在自然中汲取無限創作靈感，從滿月到一朵花，這些瞬間成為作品中的情感養份。\r\n\r\n近兩年，王勁之在世界各地走動，他認為岩彩承載著原始的能量，讓他聯想到古人利用礦石創作的力量，這股能量使他更理解人與自然的關聯。大自然的壯麗景觀讓他感受到自身的渺小，而這些感受則轉化為畫作中的美好瞬間。《春日・雲隱》不僅是一次視覺盛宴，更是一次心靈的旅程。王勁之希望透過這些作品，將四季流轉中的短暫美好傳遞給觀眾，讓大家感受自然與生命的美麗與力量。\r\n\r\n展期：2025 年2月8日（星期六）至2025年3月16日（星期日）\r\n開幕：2025年2月9日（星期日）下午3:00，藝術家將出席。\r\n\r\n\r\n藝術家創作自述：\r\n\r\n關於創作，像是我和自己的對話，是我生活的寫照，回想起拿起筆的第一次是那麼的稚嫩，驅動我的不是任何理由，僅僅是發自內心的衝動。\r\n\r\n藝術創作就像是一片蔚藍深海，我在其中不斷探索，尋找自己的道路，不斷的嘗試，不斷尋找自己喜歡的創作樣貌，我特別喜歡自然和人之間的關係，這也是我在創作中大量出現花卉的原因，花卉無聲卻默默點綴著我們的環境，我喜歡去紀錄生活中的平凡，一花一木都是我駐足的理由，我常常被說是水瓶座的典型，天馬行空並在特殊的點上觀察，會看著閃耀的滿月發呆，仔細端詳一朵我沒有見過的花，我想那些都是我創作的養分。\r\n\r\n這兩年在世界各地走動後，給我的感觸特別多，登了之久，仍在這個時代被大家追捧和探討，連我也是為它沉迷，在面對岩彩的時候，他像是有一股牽引的能力，在千年前古代人砸碎礦石將其塗抹而繪製出圖案的那種原始的動能，好像還流淌雪山，看了大西洋的海，在一望無盡的視野中，特別感覺自己的渺小，我能記錄下的只能是那些很美好的瞬間，我想帶給觀者的也是四季生活中的短暫煙火，希望將這份小小的美傳達給大家。\r\n', '涅普頓畫廊', '臺北市中山區', '2025-02-08 00:00:00', '2025-03-16 00:00:00', '中山區（臺北市）=', 25.06969917, 121.5381597, '無資料', 'https://neptune-gallery.com/exhibitions_art_fair/%e3%80%90%e6%98%a5%e6%97%a5%e3%83%bb%e9%9b%b2%e9%9a', '[]') ON DUPLICATE KEY UPDATE `activity_name`='春日・雲隱 – 王勁之 個展', `description`='藝術家王勁之即將舉辦個展《春日・雲隱》，邀請觀眾進入他的藝術世界，透過他對生活、自然與自我的詮釋，感受隱藏於日常中的美。展覽將於2025年2月8日（星期六）至3月16日（星期日）展出，開幕式定於2025年2月9日（星期日）下午3:00，屆時藝術家將親臨現場，我們誠摯邀請您的蒞臨。\r\n\r\n對王勁之而言，創作是一場與自我對話的過程。他回憶起第一次拿起畫筆時的稚嫩與衝動，並將這份源自內心的驅動力視為持續創作的核心。他將創作比喻為在蔚藍深海中探險，探索未知，並在不斷嘗試中找到屬於自己的創作風格。\r\n\r\n王勁之對自然有著深厚情感，特別關注人與自然之間的微妙聯繫。展覽作品中，花卉和自然景象是他反覆表現的主題，他