INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8b26b3240c403d9778', '穿越時空的宮廷盛宴(二)', '✨ 學員心得分享 ✨\r\n🔹 料理品嚐可以這麼專業，歷史探究可以這麼美味！\r\n🔹 課程充滿經典菜餚剖析、飲食文化故事與師生精彩互動，每次下課鐘聲響起，都讓人意猶未盡，恨不得再「加點」一堂！\r\n', '國立政治大學公共行政及企業管理教育中心', '臺北市大安區', '2025-03-18 00:00:00', '2025-04-08 00:00:00', '大安區（臺北市）=', 25.02677012, 121.5434446, '/+4000', 'https://cpbae.nccu.edu.tw/cpbae/class?id=4&classId=N0A2B4031', '[]') ON DUPLICATE KEY UPDATE `activity_name`='穿越時空的宮廷盛宴(二)', `description`='✨ 學員心得分享 ✨\r\n🔹 料理品嚐可以這麼專業，歷史探究可以這麼美味！\r\n🔹 課程充滿經典菜餚剖析、飲食文化故事與師生精彩互動，每次下課鐘聲響起，都讓人意猶未盡，恨不得再「加點」一堂！\r\n', `organizer`='國立政治大學公共行政及企業管理教育中心', `address`='臺北市大安區', `start_date`='2025-03-18 00:00:00', `end_date`='2025-04-08 00:00:00', `location`='大安區（臺北市）=', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='/+4000', `source_url`='https://cpbae.nccu.edu.tw/cpbae/class?id=4&classId=N0A2B4031', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8b26b3240c403d9779', '穿越時空的宮廷盛宴', '體驗從環地中海到東方的味蕾旅程嗎？「穿越時空的宮廷盛宴」課程將帶你探索古代宮廷的飲食文化，從地中海到中國的歷史美食演變。更透過多部經典影視作品深入解析與探討現實與影視中的異同與差距。', '國立政治大學公共行政及企業管理教育中心', '臺北市大安區', '2025-03-19 00:00:00', '2025-04-09 00:00:00', '大安區（臺北市）=', 25.02677012, 121.5434446, '/+4000', 'https://cpbae.nccu.edu.tw/cpbae/class?id=4&classId=N0A2B4032', '[]') ON DUPLICATE KEY UPDATE `activity_name`='穿越時空的宮廷盛宴', `description`='體驗從環地中海到東方的味蕾旅程嗎？「穿越時空的宮廷盛宴」課程將帶你探索古代宮廷的飲食文化，從地中海到中國的歷史美食演變。更透過多部經典影視作品深入解析與探討現實與影視中的異同與差距。', `organizer`='國立政治大學公共行政及企業管理教育中心', `address`='臺北市大安區', `start_date`='2025-03-19 00:00:00', `end_date`='2025-04-09 00:00:00', `location`='大安區（臺北市）=', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='/+4000', `source_url`='https://cpbae.nccu.edu.tw/cpbae/class?id=4&classId=N0A2B4032', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8c26b3240c403d977b', '無資料', '近年屢獲獎項肯定且跨足不同領域如古典樂、流行樂、電子實驗聲響等音樂計畫的爵士鋼琴家許郁瑛這次攜手來自澳洲、日本與德國的好友們，回到最真實的原音樂器世界，展開一場爵士原聲探索之旅，曲目多選自團員創作與即興，一期一會，see you soon!', '台中市歐洲文化創意產業協會', '臺中市南屯區', '南屯區（臺中市）=', 24.14165524, 120.6177379, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='近年屢獲獎項肯定且跨足不同領域如古典樂、流行樂、電子實驗聲響等音樂計畫的爵士鋼琴家許郁瑛這次攜手來自澳洲、日本與德國的好友們，回到最真實的原音樂器世界，展開一場爵士原聲探索之旅，曲目多選自團員創作與即興，一期一會，see you soon!', `organizer`='台中市歐洲文化創意產業協會', `address`='臺中市南屯區', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8d26b3240c403d977c', '【新北市立圖書館鶯歌分館】114年3月假日瘋電影 ', '【鶯歌分館】114年3月假日瘋電影\r\n\r\n承辦館別：新北市立圖書館鶯歌分館\r\n地址：鶯歌區中山路150號/B1 故事劇場\r\n電話：26780219#10\r\n時間：每周日14:00-16:00\r\n\r\n03/02［日］*魔法少女歐拉 : 學校的秘密 ( 普 ) 90分\r\n03/09［日］*獅子王 ( 普 ) 118分\r\n03/16［日］我和喵喵的冒險旅行 ( 普 ) 83分\r\n03/23［日］*海島小英雄馬可 ( 普 ) 73分\r\n03/30［日］*電影屁屁偵探 : 咖哩香料事件 + 瓢蟲遺蹟之謎( 普 ) 78分\r\n\r\n希望經由影片欣賞，滿足觀賞民眾休閒娛樂的需求，並經由影片深入淺出的表演方式，給予民眾不同於日常生活領域的知識與體驗，歡迎有興趣的讀者踴躍參加。\r\n\r\n※播放影片與時間若有更動，以活動現場公告為主，不便之處，敬請見諒。', '新北市立圖書館總館', '新北市鶯歌區中山路150號B1至1樓及3至5樓', '2025-03-02 00:00:00', '2025-03-30 00:00:00', '新北市立圖書館鶯歌分館', 24.9566258, 121.3466269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館鶯歌分館】114年3月假日瘋電影 ', `description`='【鶯歌分館】114年3月假日瘋電影\r\n\r\n承辦館別：新北市立圖書館鶯歌分館\r\n地址：鶯歌區中山路150號/B1 故事劇場\r\n電話：26780219#10\r\n時間：每周日14:00-16:00\r\n\r\n03/02［日］*魔法少女歐拉 : 學校的秘密 ( 普 ) 90分\r\n03/09［日］*獅子王 ( 普 ) 118分\r\n03/16［日］我和喵喵的冒險旅行 ( 普 ) 83分\r\n03/23［日］*海島小英雄馬可 ( 普 ) 73分\r\n03/30［日］*電影屁屁偵探 : 咖哩香料事件 + 瓢蟲遺蹟之謎( 普 ) 78分\r\n\r\n希望經由影片欣賞，滿足觀賞民眾休閒娛樂的需求，並經由影片深入淺出的表演方式，給予民眾不同於日常生活領域的知識與體驗，歡迎有興趣的讀者踴躍參加。\r\n\r\n※播放影片與時間若有更動，以活動現場公告為主，不便之處，敬請見諒。', `organizer`='新北市立圖書館總館', `address`='新北市鶯歌區中山路150號B1至1樓及3至5樓', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='新北市立圖書館鶯歌分館', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8e26b3240c403d977d', '尋隱者：月影搖曳下的時間與記憶——賴靜個展', '賴靜 (b. 1981, 中國成都) 現居住、工作於重慶。求學期間即嶄露頭角，獲得「首屆張曉剛研究生當代藝術創作獎學金」等重要獎項，並於四川美術學院取得碩士學位。\r\n她的作品融合中國文人畫的經典美學與當代視覺表現，兼具傳統符號和個人風格。賴靜選擇了藝術史最悠久的絹本作為創作載體，卻在筆墨、氛圍與題材上突破框架，拓展水墨的表現疆界；並以鏡面、窗框等元素構築多層次空間，探討「可見與不可見」、「記憶與現實」之間的張力。她擅長以低飽和色調與細膩層疊的筆法營造幽微靜謐的畫面，使作品在抑制與流動之間展現獨特的視覺語境。\r\n\r\n此次個展「尋隱者：月影搖曳下的時間與記憶」中，賴靜透過光影、空間與記憶的重組，引領觀者進入游離於現實與幻象之間，在觀看中發掘被時間掩映的碎片。她的作品在寧靜與悖返之間流轉，使傳統筆墨在當代語境中折射出新的光芒。', '曙畫廊', '臺北市士林區', '2025-02-22 00:00:00', '2025-04-12 00:00:00', '士林區（臺北市）=', 25.12546704, 121.5508473, '無資料', 'https://enlighten-gallery.com/%e8%b3%b4%e9%9d%9c%e5%80%8b%e5%b1%95/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='尋隱者：月影搖曳下的時間與記憶——賴靜個展', `description`='賴靜 (b. 1981, 中國成都) 現居住、工作於重慶。求學期間即嶄露頭角，獲得「首屆張曉剛研究生當代藝術創作獎學金」等重要獎項，並於四川美術學院取得碩士學位。\r\n她的作品融合中國文人畫的經典美學與當代視覺表現，兼具傳統符號和個人風格。賴靜選擇了藝術史最悠久的絹本作為創作載體，卻在筆墨、氛圍與題材上突破框架，拓展水墨的表現疆界；並以鏡面、窗框等元素構築多層次空間，探討「可見與不可見」、「記憶與現實」之間的張力。她擅長以低飽和色調與細膩層疊的筆法營造幽微靜謐的畫面，使作品在抑制與流動之間展現獨特的視覺語境。\r\n\r\n此次個展「尋隱者：月影搖曳下的時間與記憶」中，賴靜透過光影、空間與記憶的重組，引領觀者進入游離於現實與幻象之間，在觀看中發掘被時間掩映的碎片。她的作品在寧靜與悖返之間流轉，使傳統筆墨在當代語境中折射出新的光芒。', `organizer`='曙畫廊', `address`='臺北市士林區', `start_date`='2025-02-22 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='士林區（臺北市）=', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='無資料', `source_url`='https://enlighten-gallery.com/%e8%b3%b4%e9%9d%9c%e5%80%8b%e5%b1%95/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e8f26b3240c403d977e', '【新北市立圖書館鶯歌分館】114年3月彩虹故事屋', '【鶯歌分館】114年3月彩虹故事屋\r\n\r\n館別:新北市立圖書館【鶯歌分館】\r\n地址:鶯歌區中山路150號/B1 兒童室\r\n電話：26780219#10\r\n時間：09:30-10:30    \r\n\r\n活動場次:\r\n3/1(六)《你還是我的朋友!》何素娟老師\r\n3/8(六) 《三球毛線，編織自由》&《神奇的編織高手史丹利》陳淑慧老師\r\n3/15(六) 《我是藝術家》王淑青老師\r\n\r\n希望藉由繪本來為孩子說故事，啟發孩子的語言與學習興趣，開展孩子的想像與創造力，以及學習情緒的抒發、喜歡閱讀等，不但能在親子間建立良好的共讀習慣，也能推動更美好的書香環境！\r\n\r\n了解更多活動相關訊息歡迎加入【鶯歌閱讀活動推廣】平台!\r\n\r\n**活動單位保有取消、變更之權利，詳情請依現場為主。', '新北市立圖書館總館', '新北市鶯歌區中山路150號B1至1樓及3至5樓', '2025-03-01 00:00:00', '2025-03-15 00:00:00', '新北市立圖書館鶯歌分館', 24.9566258, 121.3466269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館鶯歌分館】114年3月彩虹故事屋', `description`='【鶯歌分館】114年3月彩虹故事屋\r\n\r\n館別:新北市立圖書館【鶯歌分館】\r\n地址:鶯歌區中山路150號/B1 兒童室\r\n電話：26780219#10\r\n時間：09:30-10:30    \r\n\r\n活動場次:\r\n3/1(六)《你還是我的朋友!》何素娟老師\r\n3/8(六) 《三球毛線，編織自由》&《神奇的編織高手史丹利》陳淑慧老師\r\n3/15(六) 《我是藝術家》王淑青老師\r\n\r\n希望藉由繪本來為孩子說故事，啟發孩子的語言與學習興趣，開展孩子的想像與創造力，以及學習情緒的抒發、喜歡閱讀等，不但能在親子間建立良好的共讀習慣，也能推動更美好的書香環境！\r\n\r\n了解更多活動相關訊息歡迎加入【鶯歌閱讀活動推廣】平台!\r\n\r\n**活動單位保有取消、變更之權利，詳情請依現場為主。', `organizer`='新北市立圖書館總館', `address`='新北市鶯歌區中山路150號B1至1樓及3至5樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='新北市立圖書館鶯歌分館', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9026b3240c403d9780', '鋼琴畫布：小提琴和中提琴的音律筆觸台北場', '張智欽與陳思涵皆為醫療工作者，忙碌的身份並沒有澆熄他們對於音樂的熱情與對於提琴的熱愛，反而促使他們更加努力成為優秀的演奏家，經常參與演出並擔任樂團首席及獨奏。\r\n今年，小提琴家張智欽與中提琴家陳思涵，將與鋼琴家陳昭惠帶來韓德爾/哈沃森、托瑪索．韋塔利、羅伯特．福克斯及羅伯特·舒曼之作品，期盼透過絕美的音色與技巧，在後疫情時代帶領觀眾進入音樂的療癒世界。\r\n\r\n🎻演出陣容：\r\n小提琴｜張智欽 \r\n中提琴｜陳思涵 \r\n鋼琴｜陳昭惠\r\n\r\n🎶演出曲目：\r\nG. F. Handel / Johan Halvorsen: "Passacaglia" for Violin and Viola\r\n韓德爾/哈沃森：《帕薩卡利亞舞曲》給小提琴與中提琴\r\nTomaso Vitali: "Chaconne" for Violin and Piano\r\n托瑪索．韋塔利：《夏康舞曲》給小提琴與鋼琴\r\nRobert Fuchs: 7 Phantasiestücke, Op. 57\r\n羅伯特．福克斯：七首幻想練習曲，作品57\r\nRobert Schumann: Fantasiestücke for Violin and Piano, Op. 73\r\n羅伯特．舒曼：《幻想練習曲》給小提琴與鋼琴，作品73\r\nRobert Schumann: Adagio and Allegro for Viola and Piano, Op. 70\r\n羅伯特．舒曼：慢板與快板給中提琴與鋼琴，作品70\r\nRobert Schumann: Fairy Tales for Violin, Viola and Piano, Op. 132\r\n羅伯特．舒曼：童話故事給小提琴、中提琴與鋼琴，作品132 \r\n(主辦單位保有曲目異動權)\r\n\r\n📆演出時間與地點：\r\n2025年03月07日（五）晚上7:30 @ 衛武營國家藝術文化中心 表演廳（高雄市鳳山區三多一路 1 號）\r\n2025年03月11日（二）晚上7:30 @ 國家兩廳院 演奏廳（台北市中正區中山南路21-1號）\r\n\r\n🎉票價優惠：兩廳院之友、衛武營會員、學生9折、團體10張(含以上)9折；身障者及65歲(含)以上長者享5折優惠', '醫聲室內樂團', '臺北市中正區中山南路21之1號', '2025-03-11 00:00:00', '2025-03-11 00:00:00', '國家兩廳院', 25.03240487, 121.5198839, '/+300;/+500;/+800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鋼琴畫布：小提琴和中提琴的音律筆觸台北場', `description`='張智欽與陳思涵皆為醫療工作者，忙碌的身份並沒有澆熄他們對於音樂的熱情與對於提琴的熱愛，反而促使他們更加努力成為優秀的演奏家，經常參與演出並擔任樂團首席及獨奏。\r\n今年，小提琴家張智欽與中提琴家陳思涵，將與鋼琴家陳昭惠帶來韓德爾/哈沃森、托瑪索．韋塔利、羅伯特．福克斯及羅伯特·舒曼之作品，期盼透過絕美的音色與技巧，在後疫情時代帶領觀眾進入音樂的療癒世界。\r\n\r\n🎻演出陣容：\r\n小提琴｜張智欽 \r\n中提琴｜陳思涵 \r\n鋼琴｜陳昭惠\r\n\r\n🎶演出曲目：\r\nG. F. Handel / Johan Halvorsen: "Passacaglia" for Violin and Viola\r\n韓德爾/哈沃森：《帕薩卡利亞舞曲》給小提琴與中提琴\r\nTomaso Vitali: "Chaconne" for Violin and Piano\r\n托瑪索．韋塔利：《夏康舞曲》給小提琴與鋼琴\r\nRobert Fuchs: 7 Phantasiestücke, Op. 57\r\n羅伯特．福克斯：七首幻想練習曲，作品57\r\nRobert Schumann: Fantasiestücke for Violin and Piano, Op. 73\r\n羅伯特．舒曼：《幻想練習曲》給小提琴與鋼琴，作品73\r\nRobert Schumann: Adagio and Allegro for Viola and Piano, Op. 70\r\n羅伯特．舒曼：慢板與快板給中提琴與鋼琴，作品70\r\nRobert Schumann: Fairy Tales for Violin, Viola and Piano, Op. 132\r\n羅伯特．舒曼：童話故事給小提琴、中提琴與鋼琴，作品132 \r\n(主辦單位保有曲目異動權)\r\n\r\n📆演出時間與地點：\r\n2025年03月07日（五）晚上7:30 @ 衛武營國家藝術文化中心 表演廳（高雄市鳳山區三多一路 1 號）\r\n2025年03月11日（二）晚上7:30 @ 國家兩廳院 演奏廳（台北市中正區中山南路21-1號）\r\n\r\n🎉票價優惠：兩廳院之友、衛武營會員、學生9折、團體10張(含以上)9折；身障者及65歲(含)以上長者享5折優惠', `organizer`='醫聲室內樂團', `address`='臺北市中正區中山南路21之1號', `start_date`='2025-03-11 00:00:00', `end_date`='2025-03-11 00:00:00', `location`='國家兩廳院', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='/+300;/+500;/+800', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9126b3240c403d9781', '穿過鏡子-自畫像聯展', '2025年的開始，\r\n推出既顛覆又有趣，既熟悉又陌生的展覽\r\n「穿過鏡子」自畫像聯展2025/1/4-2/28\r\n15位藝術家參與，一次別開生面的show歡迎大家前來觀賞', '新心生活藝術館', '臺南市東區', '2025-01-04 00:00:00', '2025-02-28 00:00:00', '東區（臺南市）=', 22.98178202, 120.2281858, '無資料', 'https://www.facebook.com/singart1990', '[]') ON DUPLICATE KEY UPDATE `activity_name`='穿過鏡子-自畫像聯展', `description`='2025年的開始，\r\n推出既顛覆又有趣，既熟悉又陌生的展覽\r\n「穿過鏡子」自畫像聯展2025/1/4-2/28\r\n15位藝術家參與，一次別開生面的show歡迎大家前來觀賞', `organizer`='新心生活藝術館', `address`='臺南市東區', `start_date`='2025-01-04 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='東區（臺南市）=', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='https://www.facebook.com/singart1990', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9226b3240c403d9783', '紙風車劇團【蕃薯森林奇遇記】', '這個過年，蕃薯國王熬夜又暴飲暴食，身體微恙\r\n虎克船長帶著綜藝團show一場娛樂國王\r\n而真正讓人煩惱的，則是被破壞的蕃薯森林\r\n​\r\n虎克與機靈的小飛俠合體將解決這棘手的問題\r\n找回幸福鳥，讓這裡恢復美麗的模樣', '無資料', '臺中市太平區', '2025-03-02 00:00:00', '2025-03-02 00:00:00', '太平區（臺中市）=', 24.11477375, 120.7734217, '無資料', 'https://www.facebook.com/story.php?story_fbid=1035763101911434&id=100064332623617&rdid=VR4B2IlBMZZg8', '[]') ON DUPLICATE KEY UPDATE `activity_name`='紙風車劇團【蕃薯森林奇遇記】', `description`='這個過年，蕃薯國王熬夜又暴飲暴食，身體微恙\r\n虎克船長帶著綜藝團show一場娛樂國王\r\n而真正讓人煩惱的，則是被破壞的蕃薯森林\r\n​\r\n虎克與機靈的小飛俠合體將解決這棘手的問題\r\n找回幸福鳥，讓這裡恢復美麗的模樣', `organizer`='無資料', `address`='臺中市太平區', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='太平區（臺中市）=', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://www.facebook.com/story.php?story_fbid=1035763101911434&id=100064332623617&rdid=VR4B2IlBMZZg8', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9226b3240c403d9784', '紙風車劇團【巫頂環遊世界】', '開學至今，還在提不起勁躲在被窩裡賴床嗎💤\r\n巫頂家的小孩賴床經驗值可是「頂港有名聲，下港有出名」\r\n另一個出名的就是貝里斯森林裡的牛蛙歌聲🎤\r\n​\r\n巫頂去環遊世界不只要帶歡樂給大家\r\n也要去探索各地的好吃又好玩\r\n​\r\n這次，我們一起相聚枇杷之鄉—台中太平囉~\r\n​', '無資料', '臺中市太平區', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '太平區（臺中市）=', 24.11477375, 120.7734217, '無資料', 'https://www.facebook.com/share/p/1L3p7cpkhm/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='紙風車劇團【巫頂環遊世界】', `description`='開學至今，還在提不起勁躲在被窩裡賴床嗎💤\r\n巫頂家的小孩賴床經驗值可是「頂港有名聲，下港有出名」\r\n另一個出名的就是貝里斯森林裡的牛蛙歌聲🎤\r\n​\r\n巫頂去環遊世界不只要帶歡樂給大家\r\n也要去探索各地的好吃又好玩\r\n​\r\n這次，我們一起相聚枇杷之鄉—台中太平囉~\r\n​', `organizer`='無資料', `address`='臺中市太平區', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='太平區（臺中市）=', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1L3p7cpkhm/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9226b3240c403d9785', '後影像上癮', '當下是多巴胺控制著身體的時代，在社群媒體的高速運行下，影像不再只是記錄真實，而是一種無限再造的幻象。短影音、快影像的迅速生成與消逝，使視覺內容成為一種即時的、強效的神經刺激。人工智慧的介入，更讓影像的生產從技術門檻轉變為點擊式體驗，濾鏡、換臉、深度偽造，一切皆可輕易生成，模糊了真實與虛構的界線。影像的消費模式從靜態觀看演變為極具節奏感的「滑動快感」，影像不斷閃爍、流動，帶來即時且高效的感官刺激，如同數位時代的感官麻醉品。短短幾秒的畫面，便能觸發大腦的獎勵機制，使多巴胺分泌，讓人沉浸其中，難以自拔。影像成為一種無形的癮，讓觀看者在無限滑動的過程中尋找下一個刺激點，而這種觀看方式，亦深刻塑造了我們對世界的感知方式。\r\n\r\n當影像的製作與消費變得高度自動化與碎片化，我們如何在這場視覺狂歡中保持警覺？如何在真假難辨的影像環境中重新建立信任？當影像不再純粹是觀看的對象，而成為影響我們思考與行動的工具，我們是否仍然擁有選擇權？展覽《後影像上癮》試圖在這場影像狂潮中提出思考，透過藝術與科技的交錯，探討影像如何成為一種會讓人上癮的機制，並且如何塑造我們的知覺、記憶與認同。在影像加速的時代，觀看不再只是觀看，而是一種被演算法引導的沉迷其中的我們，如何擁有觀看的自主權。\r\n文 / 羅禾淋\r\n\r\n▍藝術家｜林亭羽、張承濬、黃雅詩、楊佳蓁、劉友真、潘保源、黃姿婷、黃孟凡、謝雨庭、陳昱維\r\n▍展覽日期｜2025.03.19(三) ~ 2025.04.06(日)\r\n▍開幕茶會｜2025.03.22(六)14:00\r\n▍展覽地點｜新浜碼頭藝術空間\r\n▍空間贊助單位｜國藝會\r\n▍新浜行政｜陳羚溱、吳宛倫\r\n▍實習生｜陳咨蓉', '高雄市新浜碼頭藝術學會', '高雄市鹽埕區015鄰大勇路64號2樓', '2025-03-19 00:00:00', '2025-04-06 00:00:00', '新浜碼頭藝術空間', 22.6228436, 120.2835667, '無資料', 'https://sinpink93874536.wordpress.com/wp-admin/post.php?post=14857&action=edit', '[]') ON DUPLICATE KEY UPDATE `activity_name`='後影像上癮', `description`='當下是多巴胺控制著身體的時代，在社群媒體的高速運行下，影像不再只是記錄真實，而是一種無限再造的幻象。短影音、快影像的迅速生成與消逝，使視覺內容成為一種即時的、強效的神經刺激。人工智慧的介入，更讓影像的生產從技術門檻轉變為點擊式體驗，濾鏡、換臉、深度偽造，一切皆可輕易生成，模糊了真實與虛構的界線。影像的消費模式從靜態觀看演變為極具節奏感的「滑動快感」，影像不斷閃爍、流動，帶來即時且高效的感官刺激，如同數位時代的感官麻醉品。短短幾秒的畫面，便能觸發大腦的獎勵機制，使多巴胺分泌，讓人沉浸其中，難以自拔。影像成為一種無形的癮，讓觀看者在無限滑動的過程中尋找下一個刺激點，而這種觀看方式，亦深刻塑造了我們對世界的感知方式。\r\n\r\n當影像的製作與消費變得高度自動化與碎片化，我們如何在這場視覺狂歡中保持警覺？如何在真假難辨的影像環境中重新建立信任？當影像不再純粹是觀看的對象，而成為影響我們思考與行動的工具，我們是否仍然擁有選擇權？展覽《後影像上癮》試圖在這場影像狂潮中提出思考，透過藝術與科技的交錯，探討影像如何成為一種會讓人上癮的機制，並且如何塑造我們的知覺、記憶與認同。在影像加速的時代，觀看不再只是觀看，而是一種被演算法引導的沉迷其中的我們，如何擁有觀看的自主權。\r\n文 / 羅禾淋\r\n\r\n▍藝術家｜林亭羽、張承濬、黃雅詩、楊佳蓁、劉友真、潘保源、黃姿婷、黃孟凡、謝雨庭、陳昱維\r\n▍展覽日期｜2025.03.19(三) ~ 2025.04.06(日)\r\n▍開幕茶會｜2025.03.22(六)14:00\r\n▍展覽地點｜新浜碼頭藝術空間\r\n▍空間贊助單位｜國藝會\r\n▍新浜行政｜陳羚溱、吳宛倫\r\n▍實習生｜陳咨蓉', `organizer`='高雄市新浜碼頭藝術學會', `address`='高雄市鹽埕區015鄰大勇路64號2樓', `start_date`='2025-03-19 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='新浜碼頭藝術空間', `latitude`=22.6228436, `longitude`=120.2835667, `ticket_price`='無資料', `source_url`='https://sinpink93874536.wordpress.com/wp-admin/post.php?post=14857&action=edit', `image_url`='[]';
