INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9226b3240c403d9788', '花蓮粥會114乙巳年書畫聯展', '花蓮粥會創立於101年3月14日，為全球粥會第72粥會(目前全球共201粥會)，歷任理事長王鎮華、彭明德、石炳輝、楊豐碩、賴尚甫皆為花蓮詩書畫名家及收藏家。粥會活動以雅集為重點，「閒話家常，笑談古今」為旨趣，和睦相處交誼為依歸，以文學藝術為共同話題，致力於兩岸三地書畫交流及服務本縣偏鄉地區辦理書藝研習班，促進書畫藝術的傳承與交流。\r\n本年度開春大展集結20多位會員，展出70餘幅的書畫創作，書法作品篆、隸、行、草、楷等各體水墨丹青濃淡合宜氣韻生動。', '花蓮縣吉安鄉公所', '花蓮縣吉安鄉中山路三段475號', '2025-02-08 00:00:00', '2025-03-02 00:00:00', '吉安鄉好客藝術村', 23.95546585, 121.5646738, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='花蓮粥會114乙巳年書畫聯展', `description`='花蓮粥會創立於101年3月14日，為全球粥會第72粥會(目前全球共201粥會)，歷任理事長王鎮華、彭明德、石炳輝、楊豐碩、賴尚甫皆為花蓮詩書畫名家及收藏家。粥會活動以雅集為重點，「閒話家常，笑談古今」為旨趣，和睦相處交誼為依歸，以文學藝術為共同話題，致力於兩岸三地書畫交流及服務本縣偏鄉地區辦理書藝研習班，促進書畫藝術的傳承與交流。\r\n本年度開春大展集結20多位會員，展出70餘幅的書畫創作，書法作品篆、隸、行、草、楷等各體水墨丹青濃淡合宜氣韻生動。', `organizer`='花蓮縣吉安鄉公所', `address`='花蓮縣吉安鄉中山路三段475號', `start_date`='2025-02-08 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='吉安鄉好客藝術村', `latitude`=23.95546585, `longitude`=121.5646738, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9226b3240c403d9789', '新營區圖書館 : 2月繪本閱讀分享會', '由一群志同道合的故事媽媽，一起研讀繪本，輪流分享心得，每月2-3次的分享，每位夥伴認領導讀1至3本書。\r\n1月14日 09:00-11:30 相見歡 陳偉玲\r\n1月21日 09:00-11:30 地下花園 楊千慧', '臺南市新營區圖書館', '臺南市新營區45之8號', '2025-02-11 00:00:00', '2025-02-25 00:00:00', '臺南市新營區圖書館', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新營區圖書館 : 2月繪本閱讀分享會', `description`='由一群志同道合的故事媽媽，一起研讀繪本，輪流分享心得，每月2-3次的分享，每位夥伴認領導讀1至3本書。\r\n1月14日 09:00-11:30 相見歡 陳偉玲\r\n1月21日 09:00-11:30 地下花園 楊千慧', `organizer`='臺南市新營區圖書館', `address`='臺南市新營區45之8號', `start_date`='2025-02-11 00:00:00', `end_date`='2025-02-25 00:00:00', `location`='臺南市新營區圖書館', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9226b3240c403d978a', '「貓裏．遊藝」苗栗美展雙年展一一三年精選', '「苗栗美展」自民國88年創辦以來，致力於激勵藝術工作者，營造多元創作風氣，101年起由地方美展擴大徵件範圍至全國，105年起改為雙年展模式。為因應現代藝術創作媒材豐富多元，廣邀全國優秀好手前來競技，體現出各種具原創性的佳作，以提升苗栗藝術水平。\r\n113年全國徵件共分東方媒材、西方媒材、攝影與新媒體藝術、立體造型4大類，經專業評審從404件精彩作品中，選出85件得獎作品，再從各類首獎作品中選出「貓裏獎」1件，於頒獎典禮時副縣長邱俐俐表示：有感於來自全國優秀之作品，於本局展覽完畢應移至外地，讓更多民眾有機會欣賞到這麼精彩之專業創作，故促成在國家衛生研究院再度展出，讓藝術風華再現。\r\n本次邀請參展作品有「貓裏獎」得主西方媒材類吳金河《鏡花水月遊樂園》、東方媒材類首獎張簡可筠《心浪．憶》、攝影與新媒體藝術類首獎李媛《兩者》及獲優選獎以上作品等29件，這些作品充分展現創作者對生命歷程的探索，題材多元，風格獨具，精彩可期。2月20日(四)上午11時30分辦理開幕式，歡迎民眾踴躍前往參觀。', '苗栗縣政府', '苗栗縣竹南鎮', '2025-02-17 00:00:00', '2025-04-30 00:00:00', '竹南鎮（苗栗縣）=', 24.69862459, 120.8777316, '無資料', 'https://www.mlc.gov.tw/latestevent/Details.aspx?Parser=9,3,25,,,,4471', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「貓裏．遊藝」苗栗美展雙年展一一三年精選', `description`='「苗栗美展」自民國88年創辦以來，致力於激勵藝術工作者，營造多元創作風氣，101年起由地方美展擴大徵件範圍至全國，105年起改為雙年展模式。為因應現代藝術創作媒材豐富多元，廣邀全國優秀好手前來競技，體現出各種具原創性的佳作，以提升苗栗藝術水平。\r\n113年全國徵件共分東方媒材、西方媒材、攝影與新媒體藝術、立體造型4大類，經專業評審從404件精彩作品中，選出85件得獎作品，再從各類首獎作品中選出「貓裏獎」1件，於頒獎典禮時副縣長邱俐俐表示：有感於來自全國優秀之作品，於本局展覽完畢應移至外地，讓更多民眾有機會欣賞到這麼精彩之專業創作，故促成在國家衛生研究院再度展出，讓藝術風華再現。\r\n本次邀請參展作品有「貓裏獎」得主西方媒材類吳金河《鏡花水月遊樂園》、東方媒材類首獎張簡可筠《心浪．憶》、攝影與新媒體藝術類首獎李媛《兩者》及獲優選獎以上作品等29件，這些作品充分展現創作者對生命歷程的探索，題材多元，風格獨具，精彩可期。2月20日(四)上午11時30分辦理開幕式，歡迎民眾踴躍前往參觀。', `organizer`='苗栗縣政府', `address`='苗栗縣竹南鎮', `start_date`='2025-02-17 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='竹南鎮（苗栗縣）=', `latitude`=24.69862459, `longitude`=120.8777316, `ticket_price`='無資料', `source_url`='https://www.mlc.gov.tw/latestevent/Details.aspx?Parser=9,3,25,,,,4471', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9226b3240c403d978c', '森棻手感木座', '森棻手感木座\r\n是兼具實用功能的多功能木座\r\n有興趣的朋友們趕快報名起來\r\n預約報名的費用直接包含門票\r\n期待大家一起來木雕館走走\r\n\r\n課程介紹：森棻手感木座\r\n從三義木雕源流故事、講述「奇木巧雕」與「樟木」對於三義木雕的意義。\r\n用線鋸、雕刻、拼接、炙燒等技法，設計完成獨一無二的手感木座，可以放手機、名片、卡片等各種生活用品，還可以點上精油擴香，幫生活加點儀式感，增加森林的療癒氣息。讓平凡生活變得不平凡。\r\n費用：360元/位\r\n人數：每場10位，名額有限，額滿為止。\r\n報名方式：1.預約報名（費用含門票）\r\n            報名連結 https://www.surveycake.com/s/O629G\r\n          2.現場報名（當日門票可折抵50元）\r\n地點：木雕博物館一館B1教室\r\n任何課程相關問題請洽陸沐森棻共創空間', '苗栗縣政府文化觀光局', '苗栗縣三義鄉廣聲新城88號', '2025-02-28 00:00:00', '2025-03-02 00:00:00', '三義木雕博物館', 24.4059218, 120.7611814, '團體票（學生）+40;本局策略聯盟+40;學生票+50;優待票+50;團體票+70;全票+80', 'https://wood.mlc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='森棻手感木座', `description`='森棻手感木座\r\n是兼具實用功能的多功能木座\r\n有興趣的朋友們趕快報名起來\r\n預約報名的費用直接包含門票\r\n期待大家一起來木雕館走走\r\n\r\n課程介紹：森棻手感木座\r\n從三義木雕源流故事、講述「奇木巧雕」與「樟木」對於三義木雕的意義。\r\n用線鋸、雕刻、拼接、炙燒等技法，設計完成獨一無二的手感木座，可以放手機、名片、卡片等各種生活用品，還可以點上精油擴香，幫生活加點儀式感，增加森林的療癒氣息。讓平凡生活變得不平凡。\r\n費用：360元/位\r\n人數：每場10位，名額有限，額滿為止。\r\n報名方式：1.預約報名（費用含門票）\r\n            報名連結 https://www.surveycake.com/s/O629G\r\n          2.現場報名（當日門票可折抵50元）\r\n地點：木雕博物館一館B1教室\r\n任何課程相關問題請洽陸沐森棻共創空間', `organizer`='苗栗縣政府文化觀光局', `address`='苗栗縣三義鄉廣聲新城88號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='三義木雕博物館', `latitude`=24.4059218, `longitude`=120.7611814, `ticket_price`='團體票（學生）+40;本局策略聯盟+40;學生票+50;優待票+50;團體票+70;全票+80', `source_url`='https://wood.mlc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9226b3240c403d978d', '新營區圖書館-2月主題書展-東西神祈有點Q', '為推廣宗教文化，透過展示宗教主題相關館藏，吸引民眾關注並了解宗教歷史文化與特色，增進民眾對宗教文化的認識與興趣。', '臺南市新營區圖書館', '臺南市新營區45之8號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南市新營區圖書館', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新營區圖書館-2月主題書展-東西神祈有點Q', `description`='為推廣宗教文化，透過展示宗教主題相關館藏，吸引民眾關注並了解宗教歷史文化與特色，增進民眾對宗教文化的認識與興趣。', `organizer`='臺南市新營區圖書館', `address`='臺南市新營區45之8號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市新營區圖書館', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9326b3240c403d978e', '志工說故事活動（114年3月-14場）', '春雷乍響，萬物甦醒，生機盎然的春日景象已然浮現。隨著春天的第一聲雷響報到，沉睡中的大自然悄悄伸展了身軀，而此般驚蟄節氣正是春天的重要標誌。你是否想了解驚蟄的意義及其習俗？春天的氣息又是如何感染我們的生活呢？今年3月，苗栗縣立圖書館將帶來一系列以「驚蟄雷響萬物醒 春分花開新樹植」為主題的精彩志工說故事活動，邀請大家一同走進故事的世界，探索春天的奧妙。\r\n這次活動將從3月起推出，共計14場故事，涵蓋《春雷乍響鬧驚蟄》、《開滿花的樹》、《春·驚蟄》以及《奉茶》等精彩內容。故事將帶領大小朋友了解冬眠動物的甦醒、春天萬物的變化與生機，感受春天的蓬勃與生氣。\r\n本次活動特別適合0至5歲嬰幼兒、幼兒園及國小低中年級的學童家庭參與。活動時間為每週三下午3:00至4:00，及每週六與週日上午10:00至11:00。歡迎家長陪同孩子一同來到圖書館，免費入場，享受與孩子共享故事的快樂時光。\r\n此外，苗栗縣立圖書館將於3月1日（星期六）上午10:00至11:00，特別舉辦一場客語故事《奉茶》。這個故事帶領我們走進臺灣早期濃厚的人情味與茶文化，通過故事中的茶事，孩子們不僅能學習客語辭彙，還能深刻體會客家文化的獨特魅力與價值。\r\n為了讓更多孩子能夠接觸這些有趣又富教育意義的故事，圖書館將安排多位志工輪流講述故事。這不僅有助於提升孩子們的聽覺學習能力和專注力，也能激發他們對學習與生活的熱情，培養他們的閱讀興趣與習慣。', '苗栗縣立圖書館', '苗栗縣苗栗市自治路50號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '苗栗縣立圖書館', 24.565963, 120.8203986, '無資料', 'https://www.miaoli.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='志工說故事活動（114年3月-14場）', `description`='春雷乍響，萬物甦醒，生機盎然的春日景象已然浮現。隨著春天的第一聲雷響報到，沉睡中的大自然悄悄伸展了身軀，而此般驚蟄節氣正是春天的重要標誌。你是否想了解驚蟄的意義及其習俗？春天的氣息又是如何感染我們的生活呢？今年3月，苗栗縣立圖書館將帶來一系列以「驚蟄雷響萬物醒 春分花開新樹植」為主題的精彩志工說故事活動，邀請大家一同走進故事的世界，探索春天的奧妙。\r\n這次活動將從3月起推出，共計14場故事，涵蓋《春雷乍響鬧驚蟄》、《開滿花的樹》、《春·驚蟄》以及《奉茶》等精彩內容。故事將帶領大小朋友了解冬眠動物的甦醒、春天萬物的變化與生機，感受春天的蓬勃與生氣。\r\n本次活動特別適合0至5歲嬰幼兒、幼兒園及國小低中年級的學童家庭參與。活動時間為每週三下午3:00至4:00，及每週六與週日上午10:00至11:00。歡迎家長陪同孩子一同來到圖書館，免費入場，享受與孩子共享故事的快樂時光。\r\n此外，苗栗縣立圖書館將於3月1日（星期六）上午10:00至11:00，特別舉辦一場客語故事《奉茶》。這個故事帶領我們走進臺灣早期濃厚的人情味與茶文化，通過故事中的茶事，孩子們不僅能學習客語辭彙，還能深刻體會客家文化的獨特魅力與價值。\r\n為了讓更多孩子能夠接觸這些有趣又富教育意義的故事，圖書館將安排多位志工輪流講述故事。這不僅有助於提升孩子們的聽覺學習能力和專注力，也能激發他們對學習與生活的熱情，培養他們的閱讀興趣與習慣。', `organizer`='苗栗縣立圖書館', `address`='苗栗縣苗栗市自治路50號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='苗栗縣立圖書館', `latitude`=24.565963, `longitude`=120.8203986, `ticket_price`='無資料', `source_url`='https://www.miaoli.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9326b3240c403d9790', '無資料', '冼村，廣州最有個性的「城中村」，廣州政府下令改造多年未果。2010 年不滿賠償方案，村民肉身阻止政府強拆，警方出動兩千多名警力鎮壓。五年後婁燁前往冼村勘景，劇情片計畫《風中有朵雨做的雲》正式啟動。導演馬英力近身跟拍，知名編劇張家魯、攝影包軒鳴、演員秦昊、井柏然、宋佳等人現身說法。實景試拍、演員讀本、開拍後的現場衝突、冼村遭遇的重重難關等，紀錄的眼睛如影隨形，真實呈現攝影機外觀眾看不到的瘋狂世界，亦完整記錄下婁燁的造夢路程。。', '花蓮縣文化局', '花蓮縣花蓮市中山路71號', '花蓮鐵道文化館一館', 23.99700271, 121.6071463, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='冼村，廣州最有個性的「城中村」，廣州政府下令改造多年未果。2010 年不滿賠償方案，村民肉身阻止政府強拆，警方出動兩千多名警力鎮壓。五年後婁燁前往冼村勘景，劇情片計畫《風中有朵雨做的雲》正式啟動。導演馬英力近身跟拍，知名編劇張家魯、攝影包軒鳴、演員秦昊、井柏然、宋佳等人現身說法。實景試拍、演員讀本、開拍後的現場衝突、冼村遭遇的重重難關等，紀錄的眼睛如影隨形，真實呈現攝影機外觀眾看不到的瘋狂世界，亦完整記錄下婁燁的造夢路程。。', `organizer`='花蓮縣文化局', `address`='花蓮縣花蓮市中山路71號', `location`='花蓮鐵道文化館一館', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
