INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9326b3240c403d9793', '【愛上學習，使用說明書】主題書展', '【愛上學習，使用說明書】\r\n這2年的暢銷書裡赫然發現...「媽媽使用說明書」、「老公使用說明書」、「青少年使用說明書」，還有「人生使用說明書」…，可見這「說明書」深受大家的認同。\r\n幫助您用最簡單、最有效率的方法來利用該人、事、物，真的不能輕易忽略。\r\n於是，圖書館規劃了「陪孩子愛上學習」的使用說明書，希望能陪大家在「親子互動」時，更加無往不利；後續會再推薦更多這類好書，歡迎大家多多利用。', '苗栗縣三灣鄉公所', '苗栗縣三灣鄉11鄰親民路17-1 號', '2025-02-19 00:00:00', '2025-02-28 00:00:00', '苗栗縣三灣鄉立圖書館', 24.63599405, 120.9525745, '無資料', 'https://www.facebook.com/sanwanlib#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【愛上學習，使用說明書】主題書展', `description`='【愛上學習，使用說明書】\r\n這2年的暢銷書裡赫然發現...「媽媽使用說明書」、「老公使用說明書」、「青少年使用說明書」，還有「人生使用說明書」…，可見這「說明書」深受大家的認同。\r\n幫助您用最簡單、最有效率的方法來利用該人、事、物，真的不能輕易忽略。\r\n於是，圖書館規劃了「陪孩子愛上學習」的使用說明書，希望能陪大家在「親子互動」時，更加無往不利；後續會再推薦更多這類好書，歡迎大家多多利用。', `organizer`='苗栗縣三灣鄉公所', `address`='苗栗縣三灣鄉11鄰親民路17-1 號', `start_date`='2025-02-19 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='苗栗縣三灣鄉立圖書館', `latitude`=24.63599405, `longitude`=120.9525745, `ticket_price`='無資料', `source_url`='https://www.facebook.com/sanwanlib#', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9326b3240c403d9794', '【So Good！走進展間．獸骨如柴 】漂流木藝術創作展', '農曆年前渾沌之際，走進花創園區來一場破碎與重生的心靈對話，藝術家林進展 四段生命自我叩問，引領你體驗大自然重構源源不絕的生命力：\r\n第一段.「困獸重生｜取走身上的一塊骨」\r\n第二段.「攻陷之戰｜負重前行」\r\n第三段.「渾沌之境｜目光之外」\r\n第四段.「脫胎換骨｜翻越這座山」', '財團法人臺灣生活美學基金會', '花蓮縣花蓮市中華路144號', '2025-01-18 00:00:00', '2025-04-13 00:00:00', '花蓮文化創意產業園區', 23.99700271, 121.6071463, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【So Good！走進展間．獸骨如柴 】漂流木藝術創作展', `description`='農曆年前渾沌之際，走進花創園區來一場破碎與重生的心靈對話，藝術家林進展 四段生命自我叩問，引領你體驗大自然重構源源不絕的生命力：\r\n第一段.「困獸重生｜取走身上的一塊骨」\r\n第二段.「攻陷之戰｜負重前行」\r\n第三段.「渾沌之境｜目光之外」\r\n第四段.「脫胎換骨｜翻越這座山」', `organizer`='財團法人臺灣生活美學基金會', `address`='花蓮縣花蓮市中華路144號', `start_date`='2025-01-18 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='花蓮文化創意產業園區', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
