INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9326b3240c403d9796', '紙風車劇團【蕃薯森林奇遇記】', '紙風車《蕃薯森林奇遇記》改編自經典童話《小飛俠》的冒險故事情節，故事描述蕃薯島上的蕃薯國王生病沒有了笑容，於是蕃薯大臣邀請各路英雄想盡各種方法取悅國王，甚至還請出紙風車雜技團，但都沒有效果，後來發現原來要治好國王的病，必須要到蕃薯森林尋找「幸福鳥」。', '中國信託慈善基金會', '南投縣竹山鎮', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '竹山鎮（南投縣）=', 23.69805518, 120.7100797, '無資料', 'https://www.facebook.com/paperwindmilltheatre', '[]') ON DUPLICATE KEY UPDATE `activity_name`='紙風車劇團【蕃薯森林奇遇記】', `description`='紙風車《蕃薯森林奇遇記》改編自經典童話《小飛俠》的冒險故事情節，故事描述蕃薯島上的蕃薯國王生病沒有了笑容，於是蕃薯大臣邀請各路英雄想盡各種方法取悅國王，甚至還請出紙風車雜技團，但都沒有效果，後來發現原來要治好國王的病，必須要到蕃薯森林尋找「幸福鳥」。', `organizer`='中國信託慈善基金會', `address`='南投縣竹山鎮', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='竹山鎮（南投縣）=', `latitude`=23.69805518, `longitude`=120.7100797, `ticket_price`='無資料', `source_url`='https://www.facebook.com/paperwindmilltheatre', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9326b3240c403d9797', '無資料', '每週六「小鎮躍動」由駐唱歌手、樂團、魔術、泡泡秀…等，來自不同團體帶來的各類精彩演出，歡迎鄉親們來菸葉館欣賞表演。\r\n如遇天候不佳，主辦單位有取消活動的權利。', '南投縣竹山鎮公所', '南投縣竹山鎮', '竹山鎮（南投縣）=', 23.69805518, 120.7100797, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='每週六「小鎮躍動」由駐唱歌手、樂團、魔術、泡泡秀…等，來自不同團體帶來的各類精彩演出，歡迎鄉親們來菸葉館欣賞表演。\r\n如遇天候不佳，主辦單位有取消活動的權利。', `organizer`='南投縣竹山鎮公所', `address`='南投縣竹山鎮', `location`='竹山鎮（南投縣）=', `latitude`=23.69805518, `longitude`=120.7100797, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b78e9326b3240c403d9798', '「藝起共眠 共鳴自然」首展-許慶福．張家銘．曾俊豪三人個展', '這次在鎮寶大飯店進行的「藝起共眠 共鳴自然」首展，除了呼籲大家對氣候議題重視，也希望透過三位自然系藝術家許慶福、張家銘、曾俊豪的視角，讓埔里居民與遊客感受藝術家如何以尊重環境的心，運用台灣在地素材，將石雕、油畫作品與大自然產生共鳴。\r\n許慶福(石雕)、張家銘(石雕)、曾俊豪(木雕、玻璃)三名藝術家有著許多共通點，他們除了都是重視環保的自然系藝術家，也是立體雕塑家，且具有豐富國際藝術駐村與展覽經驗。值得一提的是，擔任南投縣醉石創藝協會創會長的許慶福、擔任臺灣木雕協會理事長的曾俊豪，以及擔任I KOKO國際創作交流組織營運長的張家銘，都是世界知名藝術組織「ISSA國際雕塑創作營聯盟」成員，因為這些共通處，促成三名藝術家在具有豐富自然生態資源的埔里小鎮合體。', '鎮寶大飯店', '南投縣埔里鎮', '2025-02-22 00:00:00', '2025-03-25 00:00:00', '埔里鎮（南投縣）=', 23.97892591, 120.9625259, '無資料', 'https://www.chengpao.com.tw/news/ins.php?index_id=56&index_m_id=0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「藝起共眠 共鳴自然」首展-許慶福．張家銘．曾俊豪三人個展', `description`='這次在鎮寶大飯店進行的「藝起共眠 共鳴自然」首展，除了呼籲大家對氣候議題重視，也希望透過三位自然系藝術家許慶福、張家銘、曾俊豪的視角，讓埔里居民與遊客感受藝術家如何以尊重環境的心，運用台灣在地素材，將石雕、油畫作品與大自然產生共鳴。\r\n許慶福(石雕)、張家銘(石雕)、曾俊豪(木雕、玻璃)三名藝術家有著許多共通點，他們除了都是重視環保的自然系藝術家，也是立體雕塑家，且具有豐富國際藝術駐村與展覽經驗。值得一提的是，擔任南投縣醉石創藝協會創會長的許慶福、擔任臺灣木雕協會理事長的曾俊豪，以及擔任I KOKO國際創作交流組織營運長的張家銘，都是世界知名藝術組織「ISSA國際雕塑創作營聯盟」成員，因為這些共通處，促成三名藝術家在具有豐富自然生態資源的埔里小鎮合體。', `organizer`='鎮寶大飯店', `address`='南投縣埔里鎮', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='埔里鎮（南投縣）=', `latitude`=23.97892591, `longitude`=120.9625259, `ticket_price`='無資料', `source_url`='https://www.chengpao.com.tw/news/ins.php?index_id=56&index_m_id=0', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80beb26b3240c403d9799', '功能肌力瑜珈【新開班】【3月25日上午10點開放報名】', '5/24為第1堂課開始\n\n5/31停課\n\n本期上課為14堂課                     \n\n\n	\n		\n			\n			課\n\n			程\n\n			大\n\n			綱\n			\n			\n			次序\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			靜心與梵唱、完全式呼吸、全身關節肌肉暖身、核心肌力訓練與腰背伸展\n		\n		\n			\n			2\n			\n			靜心與梵唱、完全式呼吸、全身關節肌肉暖身、髖關節活動練習\n		\n		\n			\n			3\n			\n			靜心與梵唱、完全式呼吸、全身關節肌肉暖身、腿部肌力訓練與腿前後側伸展體位法\n		\n		\n			\n			4\n			\n			靜心與梵唱、完全式呼吸、全身關節肌肉暖身、臀肌訓練與臀髖放鬆\n		\n		\n			\n			5\n			\n			靜心與梵唱、完全式呼吸、全身關節肌肉暖身、肩背胸訓練與放鬆\n		\n		\n			\n			6\n			\n			\n			靜心與梵唱、完全式呼吸、全身關節肌肉暖身、平衡體位法\n			\n		\n		\n			\n			7\n			\n			靜心與梵唱、完全式呼吸、全身關節肌肉暖身、手部力量練習\n		\n		\n			\n			8\n			\n			\n			靜心與梵唱、腹式呼吸、全身關節肌肉暖身、古典拜日式\n			\n		\n		\n			\n			9\n			\n			靜心與梵唱、腹式呼吸、全身關節肌肉暖身、貓式變化伸展\n		\n		\n			\n			10\n			\n			靜心與梵唱、腹式呼吸、全身關節肌肉暖身、前後彎體位法練習\n		\n		\n			\n			11\n			\n			\n			靜心與梵唱、腹式呼吸、全身關節肌肉暖身、臀腿訓練與伸展\n			\n		\n		\n			\n			12\n			\n			靜心與梵唱、腹式呼吸、全身關節肌肉暖身、腹部核心穩定訓練\n		\n		\n			\n			13\n			\n			\n			靜心與梵唱、腹式呼吸、全身關節肌肉暖身、上肢肌力訓練與肩頸放鬆\n			\n		\n		\n			\n			14\n			\n			靜心與梵唱、腹式呼吸、全身關節肌肉暖身、戰士系列變化\n		\n	\n\n\n★ 請學員自備瑜珈磚、瑜珈墊 \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-24 00:00:00', '2025-08-30 00:00:00', 'E305教室', 25.0367564, 121.519047, '1867', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50675', '[]') ON DUPLICATE KEY UPDATE `activity_name`='功能肌力瑜珈【新開班】【3月25日上午10點開放報名】', `description`='5/24為第1堂課開始\n\n5/31停課\n\n本期上課為14堂課                     \n\n\n	\n		\n			\n			課\n\n			程\n\n			大\n\n			綱\n			\n			\n			次序\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			靜心與梵唱、完全式呼吸、全身關節肌肉暖身、核心肌力訓練與腰背伸展\n		\n		\n			\n			2\n			\n			靜心與梵唱、完全式呼吸、全身關節肌肉暖身、髖關節活動練習\n		\n		\n			\n			3\n			\n			靜心與梵唱、完全式呼吸、全身關節肌肉暖身、腿部肌力訓練與腿前後側伸展體位法\n		\n		\n			\n			4\n			\n			靜心與梵唱、完全式呼吸、全身關節肌肉暖身、臀肌訓練與臀髖放鬆\n		\n		\n			\n			5\