INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80beb26b3240c403d979b', '踢踏電台舞團【踢踏復古學-1920踢踏爵士舞宴】（免費觀賞）', '💖演出團體介紹：\n\n踢踏電台舞團是台灣極少數強調「即興聲響」創作踢踏舞團體，以發揚美式踢踏舞為驅力，強調「美式」踢踏元素與不同類型音樂的跨界混種，隨著不同的音樂氛圍，踏出獨特且引人注目的踢踏個性。\n\n🕒演出時間：114年3月22日 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n結合爵士舞、搖擺舞舞風，分析踢踏黃金年代，舞步作為時代顯影，復刻過去經典曲目、舞碼，跨足1920、30、40年代，融合近代編舞，與舞蹈發展維度，一同見證屬於踢踏舞與爵士音樂的共融性格，回歸美式踢踏的復古傳承，迸發出屬於百年前的傳承踢踏聲響。\n\n除了踢踏電台擅長的爵士曲風，本次演出也將挑戰不一樣的樂風混搭，歡迎一起前來與我們一起同樂!\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50680', '[]') ON DUPLICATE KEY UPDATE `activity_name`='踢踏電台舞團【踢踏復古學-1920踢踏爵士舞宴】（免費觀賞）', `description`='💖演出團體介紹：\n\n踢踏電台舞團是台灣極少數強調「即興聲響」創作踢踏舞團體，以發揚美式踢踏舞為驅力，強調「美式」踢踏元素與不同類型音樂的跨界混種，隨著不同的音樂氛圍，踏出獨特且引人注目的踢踏個性。\n\n🕒演出時間：114年3月22日 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n結合爵士舞、搖擺舞舞風，分析踢踏黃金年代，舞步作為時代顯影，復刻過去經典曲目、舞碼，跨足1920、30、40年代，融合近代編舞，與舞蹈發展維度，一同見證屬於踢踏舞與爵士音樂的共融性格，回歸美式踢踏的復古傳承，迸發出屬於百年前的傳承踢踏聲響。\n\n除了踢踏電台擅長的爵士曲風，本次演出也將挑戰不一樣的樂風混搭，歡迎一起前來與我們一起同樂!\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50680', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80beb26b3240c403d979d', '君涵樂坊【世界音樂大賞】（免費觀賞）', '💖演出團體介紹：\n\n君涵樂坊致力於推廣傳統藝術與文化，積極參與基層巡演，並在國內外音樂廳及國際藝術節演出，多次獲得國際媒體報導。除了音樂會演出，還辦理傳統文化的研習班，推動文化交流與傳承，促進國際間的文化互動與合作。\n\n🕒演出時間：114年3月29日 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n本音樂會匯集了多首具有代表性的經典作品，涵蓋中西方音樂的精髓。《揚鞭催馬運糧忙》以東北民間音樂風格描繪豐收後農民載糧的熱情景象；《海濱之歌》則是日本作曲家成田為三的傳世佳作；《台灣民謠組曲》描繪台灣農村生活及風俗。西方經典方面，莫札特的《土耳其進行曲》以流暢旋律深入人心，而布拉姆斯的《匈牙利舞曲》則展現了匈牙利民族粗獷豪放的特質。\n\n特邀知名聲樂家與優秀演奏家，透過傳統樂器融匯中西音樂元素，以全新編排詮釋經典名曲，注入現代演奏技巧與情感，呈現出充滿活力的音樂風貌，帶領聽眾深入探索音樂歷史的多元情懷。\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50682', '[]') ON DUPLICATE KEY UPDATE `activity_name`='君涵樂坊【世界音樂大賞】（免費觀賞）', `description`='💖演出團體介紹：\n\n君涵樂坊致力於推廣傳統藝術與文化，積極參與基層巡演，並在國內外音樂廳及國際藝術節演出，多次獲得國際媒體報導。除了音樂會演出，還辦理傳統文化的研習班，推動文化交流與傳承，促進國際間的文化互動與合作。\n\n🕒演出時間：114年3月29日 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n本音樂會匯集了多首具有代表性的經典作品，涵蓋中西方音樂的精髓。《揚鞭催馬運糧忙》以東北民間音樂風格描繪豐收後農民載糧的熱情景象；《海濱之歌》則是日本作曲家成田為三的傳世佳作；《台灣民謠組曲》描繪台灣農村生活及風俗。西方經典方面，莫札特的《土耳其進行曲》以流暢旋律深入人心，而布拉姆斯的《匈牙利舞曲》則展現了匈牙利民族粗獷豪放的特質。\n\n特邀知名聲樂家與優秀演奏家，透過傳統樂器融匯中西音樂元素，以全新編排詮釋經典名曲，注入現代演奏技巧與情感，呈現出充滿活力的音樂風貌，帶領聽眾深入探索音樂歷史的多元情懷。\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50682', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80beb26b3240c403d979e', '曼斯特低音銅管四重奏【低音狂潮】（免費觀賞）', '💖演出團體介紹：\n\n曼斯特低音銅管四重奏，由國內四位優秀的低音號/上低音號演奏家，加上一位擊樂演奏家所組成。成員皆擁有國內外專業演奏碩士文憑並任教於國內大專院校音樂系及各級學校音樂班。2016年初，團長林禮文老師，鑑於國內較少見到專業低音號與上低音號四重奏團體，因而邀請四位優秀音樂家共同組團。除了低音銅管四重奏的原創曲目之外，曲風更橫跨古典、爵士、流行音樂，希望能帶給聽眾精緻且優美的低音饗宴。\n\n🕒演出時間：114年4月12日 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n1 One More Time/再一次\n2 Japanese Graffiti V/日本風情畫 V\n3 Michael Jackson Hit Mix/麥可傑克森精選\n4 Takumi/匠\n5 Animated Heroes/動漫英雄大集合\n6 かげむしゃ/影武者\n7 涙そうそう/淚光閃閃\n8 YOASOBI Medley /YOASOBI 精選\n9 Hallelujah /哈雷路亞\n10 君が好きだと叫びたい/我想大聲說喜歡你\n11 Deep Purple Medley/深紫樂團精選\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50683', '[]') ON DUPLICATE KEY UPDATE `activity_name`='曼斯特低音銅管四重奏【低音狂潮】（免費觀賞）', `description`='💖演出團體介紹：\n\n曼斯特低音銅管四重奏，由國內四位優秀的低音號/上低音號演奏家，加上一位擊樂演奏家所組成。成員皆擁有國內外專業演奏碩士文憑並任教於國內大專院校音樂系及各級學校音樂班。2016年初，團長林禮文老師，鑑於國內較少見到專業低音號與上低音號四重奏團體，因而邀請四位優秀音樂家共同組團。除了低音銅管四重奏的原創曲目之外，曲風更橫跨古典、爵士、流行音樂，希望能帶給聽眾精緻且優美的低音饗宴。\n\n🕒演出時間：114年4月12日 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n1 One More Time/再一次\n2 Japanese Graffiti V/日本風情畫 V\n3 Michael Jackson Hit Mix/麥可傑克森精選\n4 Takumi/匠\n5 Animated Heroes/動漫英雄大集合\n6 かげむしゃ/影武者\n7 涙そうそう/淚光閃閃\n8 YOASOBI Medley /YOASOBI 精選\n9 Hallelujah /哈雷路亞\n10 君が好きだと叫びたい/我想大聲說喜歡你\n11 Deep Purple Medley/深紫樂團精選\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mo