INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bf326b3240c403d982a', '啟動悅讀心思維(適5-7年級)', '★本課程開班標準：報名繳費達13人。\n\n★授課師資：陳馨老師\n\n★前期(114年1-4月)課程表  供參考\n\n★課程主題及教學內容將依學員程度及學習狀況斟酌調整\n\n\n\n	\n		\n			\n			堂數\n			\n			\n			日期\n			\n			\n			課程主題\n			\n			\n			學習目標\n			\n		\n		\n			\n			1\n			\n			\n			5/4\n			\n			\n			經典文言文\n			\n			\n			〈猛政苛於虎〉選自《禮記》\n			\n		\n		\n			\n			2\n			\n			\n			5/11\n			\n			\n			名家散文\n			\n			\n			〈走在放學回家的路上〉示現修辭練習\n			\n		\n		\n			\n			3\n			\n			\n			5/18\n			\n			\n			經典文言文\n			\n			\n			〈不死之藥〉選自《韓非子》\n			\n		\n		\n			\n			4\n			\n			\n			5/25\n			\n			\n			名家散文\n			\n			\n			〈珍珠淚〉象徵修辭練習\n			\n		\n		\n			\n			停課\n			\n			\n			6/1\n			\n			\n			端午節連假\n			\n		\n		\n			\n			5\n			\n			\n			6/8\n			\n			\n			經典文言文\n			\n			\n			〈逾淮為枳〉選自《晏子春秋》\n			\n		\n		\n			\n			6\n			\n			\n			6/15\n			\n			\n			名家散文\n			\n			\n			〈巨人阿達〉人物描寫練習\n			\n		\n		\n			\n			7\n			\n			\n			6/22\n			\n			\n			經典韻文\n			\n			\n			七言律詩〈暮春〉唐‧陸游\n			\n		\n		\n			\n			8\n			\n			\n			6/29\n			\n			\n			名家散文\n			\n			\n			〈班長下臺〉對話情境練習\n			\n		\n		\n			\n			9\n			\n			\n			7/6\n			\n			\n			經典文言文\n			\n			\n			〈陋室銘〉選自《劉禹錫集》\n			\n		\n		\n			\n			10\n			\n			\n			7/13\n			\n			\n			實務演練\n			\n			\n			文法句型‧翻轉變身秀\n			\n		\n		\n			\n			11\n			\n			\n			7/20\n			\n			\n			實務演練\n			\n			\n			簡報力／上台報告\n			\n		\n		\n			\n			12\n			\n			\n			7/27\n			\n			\n			實務演練\n			\n			\n			表達力／心得分享\n			\n		\n		\n			\n			13\n			\n			\n			8/3\n			\n			\n			綜合演練\n			\n			\n			國語文素養評量\n			\n		\n		\n			\n			14\n			\n			\n			8/10\n			\n			\n			經典文言文\n			\n			\n			〈逾淮為枳〉選自《晏子春秋》\n			\n		\n		\n			\n			15\n			\n			\n			8/17\n			\n			\n			名家散文\n			\n			\n			〈巨人阿達〉人物描寫練習\n			\n		\n	\n\n\n\n上課教室位置圖\n\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-05-04 00:00:00', '2025-08-17 00:00:00', 'W311教室', 25.0367564, 121.519047, '4700', 'https://ev