INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e31b26b3240c403d985f', 'RE ³ (Recreate X Reimagine X Remake)布袋戲特展', '今年適逢布袋戲文物館成立20周年，新北市政府文化局特別規劃了RE ³布袋戲特展 (Recreate X Reimagine X Remake)，邀請新莊在地布袋戲團隊之一－真快樂掌中劇團策劃展覽，並與3組不同領域的藝術家及團隊聯合展出，從在地歷史人文為底蘊為基點，將布袋戲為核心概念主軸，運用影像、雕塑、繪畫、造型、科技等多元媒材，以「重新」為經緯－重新創造(Recreate)、重新想像(Reimagine)、重新製作(Remake)，形塑出不同以往的布袋戲新風貌。', '新莊文化藝術中心', '新北市新莊區中平路133號', '2025-01-01 00:00:00', '2025-03-02 00:00:00', '新莊文化藝術中心', 25.0358303, 121.4367535, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='RE ³ (Recreate X Reimagine X Remake)布袋戲特展', `description`='今年適逢布袋戲文物館成立20周年，新北市政府文化局特別規劃了RE ³布袋戲特展 (Recreate X Reimagine X Remake)，邀請新莊在地布袋戲團隊之一－真快樂掌中劇團策劃展覽，並與3組不同領域的藝術家及團隊聯合展出，從在地歷史人文為底蘊為基點，將布袋戲為核心概念主軸，運用影像、雕塑、繪畫、造型、科技等多元媒材，以「重新」為經緯－重新創造(Recreate)、重新想像(Reimagine)、重新製作(Remake)，形塑出不同以往的布袋戲新風貌。', `organizer`='新莊文化藝術中心', `address`='新北市新莊區中平路133號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='新莊文化藝術中心', `latitude`=25.0358303, `longitude`=121.4367535, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e31c26b3240c403d9860', 'Woo礦石色', '金瓜石、水湳洞與九份地區擁有豐富的地質礦物資源，昔日以盛產黃金而聞名，礦石除了提煉貴金屬的經濟價值之外，也應用在人類的藝術創作上，例如較為人熟知的油畫或是膠彩畫，所使用的顏料都屬於礦物顏料的一種。\r\n礦物顏料的使用源遠流長，從人類穴居壁畫、原始民族身體彩繪、文明時期的宗教壁畫和建築彩繪等，其原料皆來自不同礦物研磨後的色粉，調和不同的著合劑後所形成。例如加上蛋黃為蛋彩、以亞麻仁油調和為油畫顏料、和入動物膠為膠彩或礦物彩等等。隨著歷史發展經過不同的改良、調整礦物顏料也形塑出不同的藝術風格。\r\n本展覽預計展出16組礦物標本與礦物色粉，以及15件當代礦物彩繪藝術作品。看礦石如何轉化為畫布上的五顏六色，從礦物科學到藝術賞析，帶領您驚艷礦物的多元用途與特性。', '新北市立黃金博物館', '新北市瑞芳區金光路8號', '2025-01-01 00:00:00', '2025-03-23 00:00:00', '新北市立黃金博物館', 25.0981293, 121.8232018, '全票+80', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Woo礦石色', `description`='金瓜石、水湳洞與九份地區擁有豐富的地質礦物資源，昔日以盛產黃金而聞名，礦石除了提煉貴金屬的經濟價值之外，也應用在人類的藝術創作上，例如較為人熟知的油畫或是膠彩畫，所使用的顏料都屬於礦物顏料的一種。\r\n礦物顏料的使用源遠流長，從人類穴居壁畫、原始民族身體彩繪、文明時期的宗教壁畫和建築彩繪等，其原料皆來自不同礦物研磨後的色粉，調和不同的著合劑後所形成。例如加上蛋黃為蛋彩、以亞麻仁油調和為油畫顏料、和入動物膠為膠彩或礦物彩等等。隨著歷史發展經過不同的改良、調整礦物顏料也形塑出不同的藝術風格。\r\n本展覽預計展出16組礦物標本與礦物色粉，以及15件當代礦物彩繪藝術作品。看礦石如何轉化為畫布上的五顏六色，從礦物科學到藝術賞析，帶領您驚艷礦物的多元用途與特性。', `organizer`='新北市立黃金博物館', `address`='新北市瑞芳區金光路8號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='新北市立黃金博物館', `latitude`=25.0981293, `longitude`=121.8232018, `ticket_price`='全票+80', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e32226b3240c403d9861', '2025台灣南方藝術聯盟年度大展 - 邊界 ', '邊界—是視線所能觸及的極限，也是心靈感知的起點。當我們凝視任何景物，無論是山巒的起伏、海洋的廣闊，邊界不僅標示著存在的範疇，更是我們觀看的立場與角度所決定的框架。\r\n    台灣南方藝術聯盟以「在地連結」與「多元對話」為創作核心，致力於探索台灣的多樣性，並將其轉化為當代藝術語言，並與國際藝術潮流接軌，建立屬於台灣南方藝術聯盟的全球視野。\r\n\r\n', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-02-28 00:00:00', '2025-03-16 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣南方藝術聯盟年度大展 - 邊界 ', `description`='邊界—是視線所能觸及的極限，也是心靈感知的起點。當我們凝視任何景物，無論是山巒的起伏、海洋的廣闊，邊界不僅標示著存在的範疇，更是我們觀看的立場與角度所決定的框架。\r\n    台灣南方藝術聯盟以「在地連結」與「多元對話」為創作核心，致力於探索台灣的多樣性，並將其轉化為當代藝術語言，並與國際藝術潮流接軌，建立屬於台灣南方藝術聯盟的全球視野。\r\n\r\n', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e32526b3240c403d9862', 'FUN心說故事(左新分館114年3月)', '為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動志工，至各分館說故事。【本活動免費參加，自由入場（禁止攜帶飲料、食物）】', '高雄市立圖書館總館', '高雄市左營區博愛三路453號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '高雄市立圖書館左新分館', 22.6783295, 120.3046289, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心說故事(左新分館114年3月)', `description`='為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動志工，至各分館說故事。【本活動免費參加，自由入場（禁止攜帶飲料、食物）】', `organizer`='高雄市立圖書館總館', `address`='高雄市左營區博愛三路453號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='高雄市立圖書館左新分館', `latitude`=22.6783295, `longitude`=120.3046289, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e32626b3240c403d9863', '《大東講堂》一段建築與音樂的演進旅程', '講師簡介：\r\n\r\n \r\n\r\n林宛蓁侯林設計共同主持人，哈佛大學設計學院都市設計暨建築碩士，國立成功大學建築學系兼任助理教授。曾任美國Steven Holl 建築師事務所以及荷蘭Mecanoo Architecten。\r\n從美國歐陸的工作經驗到台灣的在地執業，其中近9年時間投入高雄衛武營國家藝術文化中心與高雄車站，2016年與侯慶謀建築師在高雄創立侯林設計。2022年事務所完成了全台最大有聲公共藝術---大港迴聲。深信建築應源自土地，由共鳴而引發共識，是城市文化向前走最重要的力量。內容介紹：建築作為音樂的載體，兩種藝術型態在時間的長河中，獨立演進又相互影響。本次講座試圖撥開音樂與建築起源的層層迷霧，聚焦在隨著時代變遷而進化的聲響，並帶大家從音樂與建築的角度認識衛武營藝術文化中心、大港迴聲，最後以2025即將完成的高火科技廟作為總結，開啟這場高雄音樂藝術行動。', '高雄市立圖書館總館', '高雄市鳳山區017鄰光遠路161號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '大東文化藝術中心', 22.625059, 120.363422, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《大東講堂》一段建築與音樂的演進旅程', `description`='講師簡介：\r\n\r\n \r\n\r\n林宛蓁侯林設計共同主持人，哈佛大學設計學院都市設計暨建築碩士，國立成功大學建築學系兼任助理教授。曾任美國Steven Holl 建築師事務所以及荷蘭Mecanoo Architecten。\r\n從美國歐陸的工作經驗到台灣的在地執業，其中近9年時間投入高雄衛武營國家藝術文化中心與高雄車站，2016年與侯慶謀建築師在高雄創立侯林設計。2022年事務所完成了全台最大有聲公共藝術---大港迴聲。深信建築應源自土地，由共鳴而引發共識，是城市文化向前走最重要的力量。內容介紹：建築作為音樂的載體，兩種藝術型態在時間的長河中，獨立演進又相互影響。本次講座試圖撥開音樂與建築起源的層層迷霧，聚焦在隨著時代變遷而進化的聲響，並帶大家從音樂與建築的角度認識衛武營藝術文化中心、大港迴聲，最後以2025即將完成的高火科技廟作為總結，開啟這場高雄音樂藝術行動。', `organizer`='高雄市立圖書館總館', `address`='高雄市鳳山區017鄰光遠路161號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='大東文化藝術中心', `latitude`=22.625059, `longitude`=120.363422, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e32626b3240c403d9864', '《大東講堂》馬賽克磁磚鑲嵌藝術', '以台灣最常見建材磁磚，藉由巧思創意與精妙的剪排，將各式不同色彩與大小形狀的瓷片拼貼成色澤鮮豔的畫面與造型，讓平凡的建材轉化為驚奇的藝術作品。\r\n\r\n講師簡介：\r\n國立高雄師範大學視覺設計系教授(退休)\r\n國立臺灣師範大學美術研究所碩士\r\n台灣美術院院士\r\n紅毛港文化創意有限公司藝術顧問\r\n2018-2022 澎湖縣公共藝術審議委員、2007-2011 屏東縣公共藝術審議委員、2008-2010 高雄市公共藝術審議委員、2006-2008 國立高雄師範大學視覺設計系主任、2005-2007 國立高雄師範大學視覺傳達設計研究所所長、2007 國立大學評鑑委員、2005-2018 高雄市歷史博物館典藏委員、2018 桃園美術館典藏委員\r\n展覽與得獎紀錄\r\n2020文化部第七屆公共藝術獎「知識之翼」\r\n2018文化部第六屆公共藝術獎「母雞帶小雞」\r\n2014文化部第四屆公共藝術獎「山海美」', '高雄市立圖書館大東藝術圖書館', '高雄市鳳山區017鄰光遠路161號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '大東文化藝術中心', 22.625059, 120.363422, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《大東講堂》馬賽克磁磚鑲嵌藝術', `description`='以台灣最常見建材磁磚，藉由巧思創意與精妙的剪排，將各式不同色彩與大小形狀的瓷片拼貼成色澤鮮豔的畫面與造型，讓平凡的建材轉化為驚奇的藝術作品。\r\n\r\n講師簡介：\r\n國立高雄師範大學視覺設計系教授(退休)\r\n國立臺灣師範大學美術研究所碩士\r\n台灣美術院院士\r\n紅毛港文化創意有限公司藝術顧問\r\n2018-2022 澎湖縣公共藝術審議委員、2007-2011 屏東縣公共藝術審議委員、2008-2010 高雄市公共藝術審議委員、2006-2008 國立高雄師範大學視覺設計系主任、2005-2007 國立高雄師範大學視覺傳達設計研究所所長、2007 國立大學評鑑委員、2005-2018 高雄市歷史博物館典藏委員、2018 桃園美術館典藏委員\r\n展覽與得獎紀錄\r\n2020文化部第七屆公共藝術獎「知識之翼」\r\n2018文化部第六屆公共藝術獎「母雞帶小雞」\r\n2014文化部第四屆公共藝術獎「山海美」', `organizer`='高雄市立圖書館大東藝術圖書館', `address`='高雄市鳳山區017鄰光遠路161號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='大東文化藝術中心', `latitude`=22.625059, `longitude`=120.363422, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e32826b3240c403d9869', '融舊創新─金光布袋戲教父「黃俊雄」特展', '本次展覽由金光多媒體有限公司策畫，以黃俊雄大師傳承創新布袋戲的脈絡為主軸，規劃五大展區，分別為《時光走廊》以文字與歷年精華影片介紹金光布袋戲的源起、革新與傳承。《主題實偶展區》再現劇中場景，呈現戲偶經典的對決時刻。《角色形象演變區》以史豔文為主，藉由不同時期的戲偶形象，讓民眾得以近距離欣賞木偶雕刻之演變。《兵器道具偶衣展示區》展出經典角色之飾品、配件，輔以設計概念說明，讓民眾對角色有更深入的認識。《實體互動區》融合布袋戲元素的趣味小遊戲讓民眾可與角色互動。\r\n透過生動有趣的互動展覽，讓民眾深入理解布袋戲一路以來的成長與變化，以及藝師們追求戲偶藝術不斷精進的職人精神，成為臺灣獨特的工藝代表。', '臺北市藝文推廣處', '臺北市大同區迪化街1段21號', '2025-01-01 00:00:00', '2025-06-15 00:00:00', '臺北市藝文推廣處-大稻埕戲苑', 25.06342433, 121.5130417, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='融舊創新─金光布袋戲教父「黃俊雄」特展', `description`='本次展覽由金光多媒體有限公司策畫，以黃俊雄大師傳承創新布袋戲的脈絡為主軸，規劃五大展區，分別為《時光走廊》以文字與歷年精華影片介紹金光布袋戲的源起、革新與傳承。《主題實偶展區》再現劇中場景，呈現戲偶經典的對決時刻。《角色形象演變區》以史豔文為主，藉由不同時期的戲偶形象，讓民眾得以近距離欣賞木偶雕刻之演變。《兵器道具偶衣展示區》展出經典角色之飾品、配件，輔以設計概念說明，讓民眾對角色有更深入的認識。《實體互動區》融合布袋戲元素的趣味小遊戲讓民眾可與角色互動。\r\n透過生動有趣的互動展覽，讓民眾深入理解布袋戲一路以來的成長與變化，以及藝師們追求戲偶藝術不斷精進的職人精神，成為臺灣獨特的工藝代表。', `organizer`='臺北市藝文推廣處', `address`='臺北市大同區迪化街1段21號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='臺北市藝文推廣處-大稻埕戲苑', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
