INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e32c26b3240c403d986b', '走出校園、文化to go─臺南歷史建築寶庫–永華國小', '臺南是一個充滿歷史與人文的地方，身為臺灣第一座城市及博物館之都，本路線以臺南400為主軸，讓學生進一步認識臺南從古到今的歷史文化演變，了解臺南歷史及建築。', '臺南市政府文化局', '臺南市中西區中正路1號', '2025-02-25 00:00:00', '2025-02-25 00:00:00', '國立臺灣文學館', 22.992064, 120.203953, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='走出校園、文化to go─臺南歷史建築寶庫–永華國小', `description`='臺南是一個充滿歷史與人文的地方，身為臺灣第一座城市及博物館之都，本路線以臺南400為主軸，讓學生進一步認識臺南從古到今的歷史文化演變，了解臺南歷史及建築。', `organizer`='臺南市政府文化局', `address`='臺南市中西區中正路1號', `start_date`='2025-02-25 00:00:00', `end_date`='2025-02-25 00:00:00', `location`='國立臺灣文學館', `latitude`=22.992064, `longitude`=120.203953, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
