INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e32d26b3240c403d986e', '無資料', '南都樂團是以特殊樂器黑管(豎笛)、尺八，配合薩克斯風、keyboard及吉他結合成團，演奏主要以台灣懷舊民謠小調國台語老歌。', '臺南市政府文化局', '臺南市東區中華東路三段332號', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='南都樂團是以特殊樂器黑管(豎笛)、尺八，配合薩克斯風、keyboard及吉他結合成團，演奏主要以台灣懷舊民謠小調國台語老歌。', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33026b3240c403d986f', '【寧中夢】楊諭沁 個展', '【盛放的花朵】\r\n桃樹上有盛放的花朵\r\n並非每朵花都能結果\r\n在藍天白雲的映照下\r\n它們如玫瑰色泡沫，嬌柔閃耀\r\n靈感泉湧也如花朵盛放\r\n一日千百朵\r\n讓花朵盛放吧，讓事物流走\r\n別問有多少收穫\r\n那裡必定也有嬉戲、純真\r\n以及滿溢的花朵，否則\r\n對我們來說，這世界將會太小\r\n而生命也不是享受\r\n摘自赫曼·赫塞--園圃之歌\r\n\r\n我帶著無比的幸福與好奇看著這裡一件件即時、即興、隨興、任意、恣意的作品；卻又件件匠心帷幄，心在，感在，意在，情在，品在，人在。\r\n「心在」的狀態進行藝術傳達，便能擁有下述三個本能，一是「專注」地導引自我美感關係，一是「放鬆」身心在周邊情意中流動，再者是「象徵」地以媒材品質化爲儀式而連結世界與人。\r\n所以說，作者像園丁那樣，自發性地整一畝田和種下可以漸漸發芽、成長、開花結果的種子。\r\n期待當下正在看展的您們，不僅看見作者與作品間關係的流動，也可以透過每一件如夢似幻的作品享受在這城市中難得的片刻寧靜！\r\n\r\n策展人／林靜宜', '無資料', '臺北市中山區', '2025-02-22 00:00:00', '2025-03-01 00:00:00', '中山區（臺北市）=', 25.06969917, 121.5381597, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【寧中夢】楊諭沁 個展', `description`='【盛放的花朵】\r\n桃樹上有盛放的花朵\r\n並非每朵花都能結果\r\n在藍天白雲的映照下\r\n它們如玫瑰色泡沫，嬌柔閃耀\r\n靈感泉湧也如花朵盛放\r\n一日千百朵\r\n讓花朵盛放吧，讓事物流走\r\n別問有多少收穫\r\n那裡必定也有嬉戲、純真\r\n以及滿溢的花朵，否則\r\n對我們來說，這世界將會太小\r\n而生命也不是享受\r\n摘自赫曼·赫塞--園圃之歌\r\n\r\n我帶著無比的幸福與好奇看著這裡一件件即時、即興、隨興、任意、恣意的作品；卻又件件匠心帷幄，心在，感在，意在，情在，品在，人在。\r\n「心在」的狀態進行藝術傳達，便能擁有下述三個本能，一是「專注」地導引自我美感關係，一是「放鬆」身心在周邊情意中流動，再者是「象徵」地以媒材品質化爲儀式而連結世界與人。\r\n所以說，作者像園丁那樣，自發性地整一畝田和種下可以漸漸發芽、成長、開花結果的種子。\r\n期待當下正在看展的您們，不僅看見作者與作品間關係的流動，也可以透過每一件如夢似幻的作品享受在這城市中難得的片刻寧靜！\r\n\r\n策展人／林靜宜', `organizer`='無資料', `address`='臺北市中山區', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='中山區（臺北市）=', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33226b3240c403d9870', 'Fun 心聽故事(林園分館114年03月)', '由高雄市立圖書館所培訓一群義務及熱情的故事志工伙伴，\r\n透過豐富的肢體語言及生動活潑表情演出，\r\n每週六將帶來不同驚喜、有趣、感人動聽的故事，\r\n不僅為小朋友們說故事、更帶領小朋友們與家長間的親子互動與閱讀推廣，\r\n享受親子間的閱讀樂趣。\r\n每週六上午10點-11點，將在林園分館 1F 兒童閱覽室演出，每場將有意想不到的精采故事，邀請喜愛聽故事的大朋友、小朋友們，一同大手牽小手，相約到林園分館聽故事唷~', '高雄市立圖書館總館', '高雄市林園區林園北路236號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '高雄市立圖書館林園分館', 22.5075991, 120.3949167, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Fun 心聽故事(林園分館114年03月)', `description`='由高雄市立圖書館所培訓一群義務及熱情的故事志工伙伴，\r\n透過豐富的肢體語言及生動活潑表情演出，\r\n每週六將帶來不同驚喜、有趣、感人動聽的故事，\r\n不僅為小朋友們說故事、更帶領小朋友們與家長間的親子互動與閱讀推廣，\r\n享受親子間的閱讀樂趣。\r\n每週六上午10點-11點，將在林園分館 1F 兒童閱覽室演出，每場將有意想不到的精采故事，邀請喜愛聽故事的大朋友、小朋友們，一同大手牽小手，相約到林園分館聽故事唷~', `organizer`='高雄市立圖書館總館', `address`='高雄市林園區林園北路236號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='高雄市立圖書館林園分館', `latitude`=22.5075991, `longitude`=120.3949167, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
