INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33526b3240c403d9872', '無資料', '孩子們在平日課程中透過有趣的學習方式接觸不同材質與音色的多樣性打擊樂器，擴大對音樂的定義、廣度與包容性。\r\n打擊樂如同我們心跳般自然，孩子們正處於想像力無限的發展階段，打擊樂器的豐富度不只在上課中探索，下課後的生活中隨處可發展節奏律動，將生活周遭物品變成打擊樂器，創造無限的音樂可能性～\r\n透過朱宗慶教學系統－桃園中華教學中心於114年02月23日舉辦的擊樂114年度音樂會，可以聆聽到不同曲風的打擊音樂之外，還能透過本場音樂會認識豐富多樣性的打擊樂器。\r\n歡迎於開放時間來電桃園中華教學中心，索票蒞臨文化局演藝廳觀賞孩子們的精采演出。\r\n演者︰女高音黃姵綺、男高音黃孫、鋼琴黃子軒', '朱宗慶打擊樂教學系統', '桃園市桃園區縣府路21號', '桃園市政府文化局', 24.994125, 121.300519, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='孩子們在平日課程中透過有趣的學習方式接觸不同材質與音色的多樣性打擊樂器，擴大對音樂的定義、廣度與包容性。\r\n打擊樂如同我們心跳般自然，孩子們正處於想像力無限的發展階段，打擊樂器的豐富度不只在上課中探索，下課後的生活中隨處可發展節奏律動，將生活周遭物品變成打擊樂器，創造無限的音樂可能性～\r\n透過朱宗慶教學系統－桃園中華教學中心於114年02月23日舉辦的擊樂114年度音樂會，可以聆聽到不同曲風的打擊音樂之外，還能透過本場音樂會認識豐富多樣性的打擊樂器。\r\n歡迎於開放時間來電桃園中華教學中心，索票蒞臨文化局演藝廳觀賞孩子們的精采演出。\r\n演者︰女高音黃姵綺、男高音黃孫、鋼琴黃子軒', `organizer`='朱宗慶打擊樂教學系統', `address`='桃園市桃園區縣府路21號', `location`='桃園市政府文化局', `latitude`=24.994125, `longitude`=121.300519, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33526b3240c403d9873', '楊三郎 名畫說故事系列展', '每幅畫作背後都有不為人知的故事，從創作歷程到流傳經過，甚至市場的跌宕起伏，有時一張照片或一本著錄便能改變命運，使其從冷門偽作變為歷史天價。展出作品來自長流美術館館長黃承志的親身收藏經歷，記錄了畫作的流傳故事、遭遇事件以及最終的結果。希望名畫說故事系列展能為愛藝者提供收藏參考，亦請各界不吝指教。', '長流美術館股份有限公司', '臺北市中正區仁愛路二段63號B1', '2025-01-15 00:00:00', '2025-03-16 00:00:00', '長流美術館 台北館', 25.03240487, 121.5198839, '無資料', 'https://www.chanliu.com/2025/01/11/%e6%a5%8a%e4%b8%89%e9%83%8e-%e5%90%8d%e7%95%ab%e8%aa%aa%e6%95%85%', '[]') ON DUPLICATE KEY UPDATE `activity_name`='楊三郎 名畫說故事系列展', `description`='每幅畫作背後都有不為人知的故事，從創作歷程到流傳經過，甚至市場的跌宕起伏，有時一張照片或一本著錄便能改變命運，使其從冷門偽作變為歷史天價。展出作品來自長流美術館館長黃承志的親身收藏經歷，記錄了畫作的流傳故事、遭遇事件以及最終的結果。希望名畫說故事系列展能為愛藝者提供收藏參考，亦請各界不吝指教。', `organizer`='長流美術館股份有限公司', `address`='臺北市中正區仁愛路二段63號B1', `start_date`='2025-01-15 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='長流美術館 台北館', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://www.chanliu.com/2025/01/11/%e6%a5%8a%e4%b8%89%e9%83%8e-%e5%90%8d%e7%95%ab%e8%aa%aa%e6%95%85%', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33626b3240c403d9877', '2025台北國際書展大獎入圍書展   ', ' 邁入第18屆的「書展大獎」，徵件自2023年10月1日起至2024年9月30日（含）期間首次出版之作品參賽，總件數達660件，包括「小說獎」110件，「非小說獎」329件，「兒童及青少年獎」221件。各獎項參賽作品水準精彩，競爭激烈，不僅呈現台灣年度出版趨勢、表彰台灣原創，也希冀透過台北國際書展、全台北中南圖書館串聯展出、線上及實體書展啟動等豐富多元活動，邀請全民矚目樂讀得獎好書。', '文化部', '桃園市中壢區光華三街10號2、3樓', '2025-02-17 00:00:00', '2025-03-31 00:00:00', '桃園市立圖書館內壢分館', 24.97993803, 121.2147243, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台北國際書展大獎入圍書展   ', `description`=' 邁入第18屆的「書展大獎」，徵件自2023年10月1日起至2024年9月30日（含）期間首次出版之作品參賽，總件數達660件，包括「小說獎」110件，「非小說獎」329件，「兒童及青少年獎」221件。各獎項參賽作品水準精彩，競爭激烈，不僅呈現台灣年度出版趨勢、表彰台灣原創，也希冀透過台北國際書展、全台北中南圖書館串聯展出、線上及實體書展啟動等豐富多元活動，邀請全民矚目樂讀得獎好書。', `organizer`='文化部', `address`='桃園市中壢區光華三街10號2、3樓', `start_date`='2025-02-17 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='桃園市立圖書館內壢分館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33726b3240c403d987a', '無資料', '02/23 (日) 14:00\r\nK歌情人 Music and Lyrics\r\n馬克羅倫斯｜2007｜美國｜劇情｜HD｜104分｜護｜英語\r\n\r\n★全球票房47億臺幣\r\n★2008 休士頓影評人協會獎最佳電影歌曲提名\r\n\r\n艾力克斯佛萊契(休葛蘭飾)是個80年代過氣的流行音樂歌手，他在鄉村市集以及音樂娛樂公園舉行懷舊巡迴演唱的機會逐漸遞減。而當流行天后卡羅柯曼邀他寫歌，並且和他一起二重唱灌唱片，富有魅力且才氣十足的他終於得到機會重返歌壇。但艾力克斯卻碰到創作瓶頸，他已經好幾年寫不出一條歌，加上從未填寫過歌詞的他，現在卻必須在短短幾天內寫出一首暢銷曲。蘇菲費雪 (茱兒芭莉摩飾)是一位古靈精怪的女子，對字句擁有相當敏銳的感覺力，與努力不懈的流行歌曲家艾力克斯的邂逅撥動了她的心弦，回想過去那一段失敗的感情，蘇菲不再願意相信感情，更害怕給予艾力克斯承諾。', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='02/23 (日) 14:00\r\nK歌情人 Music and Lyrics\r\n馬克羅倫斯｜2007｜美國｜劇情｜HD｜104分｜護｜英語\r\n\r\n★全球票房47億臺幣\r\n★2008 休士頓影評人協會獎最佳電影歌曲提名\r\n\r\n艾力克斯佛萊契(休葛蘭飾)是個80年代過氣的流行音樂歌手，他在鄉村市集以及音樂娛樂公園舉行懷舊巡迴演唱的機會逐漸遞減。而當流行天后卡羅柯曼邀他寫歌，並且和他一起二重唱灌唱片，富有魅力且才氣十足的他終於得到機會重返歌壇。但艾力克斯卻碰到創作瓶頸，他已經好幾年寫不出一條歌，加上從未填寫過歌詞的他，現在卻必須在短短幾天內寫出一首暢銷曲。蘇菲費雪 (茱兒芭莉摩飾)是一位古靈精怪的女子，對字句擁有相當敏銳的感覺力，與努力不懈的流行歌曲家艾力克斯的邂逅撥動了她的心弦，回想過去那一段失敗的感情，蘇菲不再願意相信感情，更害怕給予艾力克斯承諾。', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33726b3240c403d987c', '中壢光影電影館2月主題影展-浪漫聲活手冊｜曼哈頓戀習曲 Begin Again', '02/28 (五) 14:00\r\n曼哈頓戀習曲 Begin Again\r\n約翰卡尼｜2013｜美國｜劇情｜HD｜104分｜護｜英語\r\n\r\n★2015 奧斯卡金像獎最佳電影歌曲提名\r\n★2015 廣播影評人協會獎最佳電影歌曲提名\r\n★2015 愛爾蘭電影電視學院獎最佳導演提名\r\n\r\n唱片公司高層丹穆里根在最絕望的時候，意外聽見素人歌手葛莉塔的歌聲，此時的她在經歷挫折後，正準備放棄音樂夢想。兩條失落的生命因為音樂而相遇，也因為音樂而拯救了他們的人生。', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館2月主題影展-浪漫聲活手冊｜曼哈頓戀習曲 Begin Again', `description`='02/28 (五) 14:00\r\n曼哈頓戀習曲 Begin Again\r\n約翰卡尼｜2013｜美國｜劇情｜HD｜104分｜護｜英語\r\n\r\n★2015 奧斯卡金像獎最佳電影歌曲提名\r\n★2015 廣播影評人協會獎最佳電影歌曲提名\r\n★2015 愛爾蘭電影電視學院獎最佳導演提名\r\n\r\n唱片公司高層丹穆里根在最絕望的時候，意外聽見素人歌手葛莉塔的歌聲，此時的她在經歷挫折後，正準備放棄音樂夢想。兩條失落的生命因為音樂而相遇，也因為音樂而拯救了他們的人生。', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33726b3240c403d987d', '中壢光影電影館2月主題影展-浪漫聲活手冊｜心頌 Sing Song', '02/25 (二) 19:00\r\n心頌 Sing Song\r\n米莎坎普｜2017｜荷蘭｜劇情｜HD｜96分｜普｜荷蘭語\r\n\r\n★2018 芝加哥國際兒童電影節評審團大獎\r\n★2018 紐約國際兒童電影節\r\n★2017 奧盧國際兒童電影節\r\n\r\n16歲的茉莉受邀去蘇利南參加歌唱比賽。滿懷著對音樂的熱情，茉莉和她的吉他手史丹來到充滿異國風情的家鄉參賽。其實她去那裡的目的不只是要唱歌，她還打算偷偷尋找媽媽。這個心願讓她和史丹的友誼以及比賽的勝利都陷於險境。窮途末路之際她發現了一個驚人的事實，而這將完全改變她的人生...', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-02-25 00:00:00', '2025-02-25 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館2月主題影展-浪漫聲活手冊｜心頌 Sing Song', `description`='02/25 (二) 19:00\r\n心頌 Sing Song\r\n米莎坎普｜2017｜荷蘭｜劇情｜HD｜96分｜普｜荷蘭語\r\n\r\n★2018 芝加哥國際兒童電影節評審團大獎\r\n★2018 紐約國際兒童電影節\r\n★2017 奧盧國際兒童電影節\r\n\r\n16歲的茉莉受邀去蘇利南參加歌唱比賽。滿懷著對音樂的熱情，茉莉和她的吉他手史丹來到充滿異國風情的家鄉參賽。其實她去那裡的目的不只是要唱歌，她還打算偷偷尋找媽媽。這個心願讓她和史丹的友誼以及比賽的勝利都陷於險境。窮途末路之際她發現了一個驚人的事實，而這將完全改變她的人生...', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-02-25 00:00:00', `end_date`='2025-02-25 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33726b3240c403d987e', '無資料', '02/23 (日) 17:00\r\n法蘭克 Frank\r\n藍尼亞伯漢森｜2014｜愛爾蘭、英國｜劇情｜HD｜95分｜普｜英語、法語、德語\r\n\r\n★2014 英國獨立電影獎最佳劇本、最佳音樂技術成就；最佳導演、最佳男配角、最佳女配角提名\r\n★2015 愛爾蘭電影電視獎最佳導演、最佳男配角、最佳攝影；最佳電影、最佳男主角、最佳配樂等6項提名\r\n★2015 金馬奇幻影展\r\n\r\n害羞的男孩住在偏僻的小鎮，沒事看海發呆，生活平靜的像個白日夢，卻渴望用音樂理解這個世界。直到某天，一個另類神秘的搖滾樂團悄悄來到鎮上，鍵盤手自殺未遂，男孩自告奮勇替補，站上台才發現主唱竟然是個戴著面具的怪咖「法蘭克」。當鼓聲落下，一段為了音樂不要命、衰事連連的搞怪突槌之旅就此展開……', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='02/23 (日) 17:00\r\n法蘭克 Frank\r\n藍尼亞伯漢森｜2014｜愛爾蘭、英國｜劇情｜HD｜95分｜普｜英語、法語、德語\r\n\r\n★2014 英國獨立電影獎最佳劇本、最佳音樂技術成就；最佳導演、最佳男配角、最佳女配角提名\r\n★2015 愛爾蘭電影電視獎最佳導演、最佳男配角、最佳攝影；最佳電影、最佳男主角、最佳配樂等6項提名\r\n★2015 金馬奇幻影展\r\n\r\n害羞的男孩住在偏僻的小鎮，沒事看海發呆，生活平靜的像個白日夢，卻渴望用音樂理解這個世界。直到某天，一個另類神秘的搖滾樂團悄悄來到鎮上，鍵盤手自殺未遂，男孩自告奮勇替補，站上台才發現主唱竟然是個戴著面具的怪咖「法蘭克」。當鼓聲落下，一段為了音樂不要命、衰事連連的搞怪突槌之旅就此展開……', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33a26b3240c403d987f', '《樂陶吉春》台灣岩礦陶藝協會聯展', '捏陶是一種快樂，分享陶藝更是幸福！「樂陶吉春」是一場春意盎然的陶藝展覽，由呂志強理事長與吳興昌老師帶領協會藝術家精心創作的作品共同演繹，帶您走進泥土與春天交織的藝術世界。', '台灣岩礦陶藝協會', '桃園市八德區重慶街36-1號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '八塊厝民俗藝術村', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《樂陶吉春》台灣岩礦陶藝協會聯展', `description`='捏陶是一種快樂，分享陶藝更是幸福！「樂陶吉春」是一場春意盎然的陶藝展覽，由呂志強理事長與吳興昌老師帶領協會藝術家精心創作的作品共同演繹，帶您走進泥土與春天交織的藝術世界。', `organizer`='台灣岩礦陶藝協會', `address`='桃園市八德區重慶街36-1號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='八塊厝民俗藝術村', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33a26b3240c403d9880', '生態自然之美-羅維欽膠彩個展', '「生態畫家」羅維欽，曾獲桃園美展首獎，多次入選全省美展、南瀛美展、台陽美展，亞太藝術大獎賽優選，及日本國美藝術展……等等國內外獎項之肯定。他生性沉篤，本著一份執著，近年作品呈現對生態保育的期許及本土文化的關懷。言其對生態作品之取材，不但新穎，且畫風細膩，更可藉其作品寫實中，窺伺台灣自然生態之美。而本著他作畫謹嚴的態度，質樸敦厚的個性，更能將台灣的生態之美，於其作品中重新詮釋。', '無資料', '桃園市桃園區縣府路21號', '2025-02-26 00:00:00', '2025-03-16 00:00:00', '桃園市政府文化局', 24.994125, 121.300519, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='生態自然之美-羅維欽膠彩個展', `description`='「生態畫家」羅維欽，曾獲桃園美展首獎，多次入選全省美展、南瀛美展、台陽美展，亞太藝術大獎賽優選，及日本國美藝術展……等等國內外獎項之肯定。他生性沉篤，本著一份執著，近年作品呈現對生態保育的期許及本土文化的關懷。言其對生態作品之取材，不但新穎，且畫風細膩，更可藉其作品寫實中，窺伺台灣自然生態之美。而本著他作畫謹嚴的態度，質樸敦厚的個性，更能將台灣的生態之美，於其作品中重新詮釋。', `organizer`='無資料', `address`='桃園市桃園區縣府路21號', `start_date`='2025-02-26 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='桃園市政府文化局', `latitude`=24.994125, `longitude`=121.300519, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33a26b3240c403d9881', '翰墨寄情-彩墨兩岸名家聯展', '由牡丹皇后梁瑞琴領銜，帶領臺灣世界藝術家交流會會員進行聯展。\r\n台灣世界藝術家交流會為史元欽前會長於民國81年12月27日創立。原宗旨為「為建立兩岸藝文界友好關係，相互支援發展優良創作並提昇中華藝文創作家之地位，並一起發心舉辦聯展暨推廣文藝活動」。', '無資料', '桃園市桃園區縣府路21號', '2025-02-26 00:00:00', '2025-03-16 00:00:00', '桃園市政府文化局', 24.994125, 121.300519, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='翰墨寄情-彩墨兩岸名家聯展', `description`='由牡丹皇后梁瑞琴領銜，帶領臺灣世界藝術家交流會會員進行聯展。\r\n台灣世界藝術家交流會為史元欽前會長於民國81年12月27日創立。原宗旨為「為建立兩岸藝文界友好關係，相互支援發展優良創作並提昇中華藝文創作家之地位，並一起發心舉辦聯展暨推廣文藝活動」。', `organizer`='無資料', `address`='桃園市桃園區縣府路21號', `start_date`='2025-02-26 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='桃園市政府文化局', `latitude`=24.994125, `longitude`=121.300519, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33a26b3240c403d9882', 'E人〜桃園國中第38屆美術班畢業成果畫展', '美術班的26位學生透過主題「E人」，為觀眾帶來三年時光裡累積的創作與熱情，「E人」代表著創作的靈魂，合作的火花，不僅象徵外向，更是創作者們賦予畫布生命與情感的代名詞，他們在白紙上揮灑靈感，將內心的想法化作線條與色彩，在畫筆下釋放無限光芒，畫筆成為創作者的語言，每一幅作品都記錄著他們的想法與心境，運用畫筆描繪屬於他們的青春。', '無資料', '桃園市桃園區縣府路21號', '2025-02-19 00:00:00', '2025-03-02 00:00:00', '桃園市政府文化局', 24.994125, 121.300519, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='E人〜桃園國中第38屆美術班畢業成果畫展', `description`='美術班的26位學生透過主題「E人」，為觀眾帶來三年時光裡累積的創作與熱情，「E人」代表著創作的靈魂，合作的火花，不僅象徵外向，更是創作者們賦予畫布生命與情感的代名詞，他們在白紙上揮灑靈感，將內心的想法化作線條與色彩，在畫筆下釋放無限光芒，畫筆成為創作者的語言，每一幅作品都記錄著他們的想法與心境，運用畫筆描繪屬於他們的青春。', `organizer`='無資料', `address`='桃園市桃園區縣府路21號', `start_date`='2025-02-19 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='桃園市政府文化局', `latitude`=24.994125, `longitude`=121.300519, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e33f26b3240c403d9883', '無資料', '光志老師說故事：\r\n02/23(日)15:00-16:00 癩蛤蟆與變色龍、小兔踏踏上學去、嗨！你好！', '桃園市立圖書館', '桃園市觀音區莊敬路186號4樓', '桃園市立圖書館草漯分館', 25.02671611, 121.1155021, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='光志老師說故事：\r\n02/23(日)15:00-16:00 癩蛤蟆與變色龍、小兔踏踏上學去、嗨！你好！', `organizer`='桃園市立圖書館', `address`='桃園市觀音區莊敬路186號4樓', `location`='桃園市立圖書館草漯分館', `latitude`=25.02671611, `longitude`=121.1155021, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34026b3240c403d9884', '蔡宇貞 創作個展 【視角成為一種收藏】 ', '「視角成為一種收藏」\r\n繪畫的過程像是收藏，實現藝術家自我的收藏目標，把對時間的感知、對空間、物件與生活感受的探索融入作品之中，讓繪畫成為分享獨特視角的媒介，在生活中尋覓一種規則例外的美麗。對於收藏，每個人的定義各不相同。藝術家透過創作的眼睛，感知每一個微小而真摯的時刻，讓每一次的觀看，都是一種新的收藏。這樣的收藏，不是將某物固著於某個時間點，而是藉由創作的流動性，由腦海喚醒，將所欲收藏之物藉由繪畫賦予它新的生命與詮釋，同時也作為藝術家創作歷程的保存與展示。藝術家所認為的收藏並不僅僅是保存，更是一種不斷生長的過程。將所見所感重新賦予生命和意義，每個故事都是獨立的，在對的時間到了對的空間，也在藝術的創作中，變得鮮活而有溫度。透過宇貞式的「視角」表現，作品既源於真實的觀察和經驗，但同時也帶有創造性的虛構和詮釋，雖然虛幻，但感受卻深刻而真切，亦真亦假為創作中的微妙狀態，一種對「存有」的深刻回應。\r\n󠀠\r\n因此，透過宇貞的每一次的觀看，用新的眼光重新拾起那些過往的時刻，繪畫讓它們在心中綻放出獨特的光彩。這樣的收藏不斷地自我更新，也不斷地擴展著藝術的疆域，成為宇貞心靈中無限的收藏宇宙。\r\n󠀠\r\n藝術語言「定格」瞬間\r\n特別著重於畫面中的三維空間建構，運用類似攝影運鏡擷取畫面的方法來構築繪畫空間，創作的視野宛如一場舞動，以俯瞰的視角作為起始，從一個角落輕柔地延展，逐漸擴展至整個空間。隨著畫面規模的拓展，視角如同舞者的步伐般靈活變化，探索物件之美，敘述繪畫中獨特視角的表現方式。', '財團法人金車文教基金會', '臺北市中山區', '2025-02-08 00:00:00', '2025-03-23 00:00:00', '中山區（臺北市）=', 25.06969917, 121.5381597, '無資料', 'https://www.kingcarart.org.tw/exhibitions-detail/217', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蔡宇貞 創作個展 【視角成為一種收藏】 ', `description`='「視角成為一種收藏」\r\n繪畫的過程像是收藏，實現藝術家自我的收藏目標，把對時間的感知、對空間、物件與生活感受的探索融入作品之中，讓繪畫成為分享獨特視角的媒介，在生活中尋覓一種規則例外的美麗。對於收藏，每個人的定義各不相同。藝術家透過創作的眼睛，感知每一個微小而真摯的時刻，讓每一次的觀看，都是一種新的收藏。這樣的收藏，不是將某物固著於某個時間點，而是藉由創作的流動性，由腦海喚醒，將所欲收藏之物藉由繪畫賦予它新的生命與詮釋，同時也作為藝術家創作歷程的保存與展示。藝術家所認為的收藏並不僅僅是保存，更是一種不斷生長的過程。將所見所感重新賦予生命和意義，每個故事都是獨立的，在對的時間到了對的空間，也在藝術的創作中，變得鮮活而有溫度。透過宇貞式的「視角」表現，作品既源於真實的觀察和經驗，但同時也帶有創造性的虛構和詮釋，雖然虛幻，但感受卻深刻而真切，亦真亦假為創作中的微妙狀態，一種對「存有」的深刻回應。\r\n󠀠\r\n因此，透過宇貞的每一次的觀看，用新的眼光重新拾起那些過往的時刻，繪畫讓它們在心中綻放出獨特的光彩。這樣的收藏不斷地自我更新，也不斷地擴展著藝術的疆域，成為宇貞心靈中無限的收藏宇宙。\r\n󠀠\r\n藝術語言「定格」瞬間\r\n特別著重於畫面中的三維空間建構，運用類似攝影運鏡擷取畫面的方法來構築繪畫空間，創作的視野宛如一場舞動，以俯瞰的視角作為起始，從一個角落輕柔地延展，逐漸擴展至整個空間。隨著畫面規模的拓展，視角如同舞者的步伐般靈活變化，探索物件之美，敘述繪畫中獨特視角的表現方式。', `organizer`='財團法人金車文教基金會', `address`='臺北市中山區', `start_date`='2025-02-08 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='中山區（臺北市）=', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='https://www.kingcarart.org.tw/exhibitions-detail/217', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34526b3240c403d9885', '潭雅神社區大學【色鉛筆展聯展】繪畫作品展', '(1)活動名稱:潭雅神社區大學色鉛筆展聯展\r\n(2)地點名稱:大雅分館\r\n(3)場地名稱:三樓展區\r\n(4)活動日期:2/1(六)-2/27(四)\r\n(5)活動時間:開館時間\r\n(6)活動內容：\r\n展出潭雅神社區大學色鉛筆班學員優秀的素描水彩畫作品。\r\n指導老師：林志芃 老師\r\n', '無資料', '臺中市大雅區雅潭路四段800號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館大雅分館', 24.22704181, 120.6411818, '無資料', 'https://reurl.cc/xp2m21', '[]') ON DUPLICATE KEY UPDATE `activity_name`='潭雅神社區大學【色鉛筆展聯展】繪畫作品展', `description`='(1)活動名稱:潭雅神社區大學色鉛筆展聯展\r\n(2)地點名稱:大雅分館\r\n(3)場地名稱:三樓展區\r\n(4)活動日期:2/1(六)-2/27(四)\r\n(5)活動時間:開館時間\r\n(6)活動內容：\r\n展出潭雅神社區大學色鉛筆班學員優秀的素描水彩畫作品。\r\n指導老師：林志芃 老師\r\n', `organizer`='無資料', `address`='臺中市大雅區雅潭路四段800號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館大雅分館', `latitude`=24.22704181, `longitude`=120.6411818, `ticket_price`='無資料', `source_url`='https://reurl.cc/xp2m21', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34526b3240c403d9886', '【故事之島：從臺灣到波隆那】/【元宵喜圓滿】/【課：「風邪」】/【愛的語言】主題書展', '【故事之島：從臺灣到波隆那】主題書展\r\n展出「2024波隆那兒童書展臺灣館入選書」，本次書展將帶您穿越不同的文化與故事，【義大利波隆那兒童書展】台灣館入選書籍，包括海洋主題及年度推薦書，為您呈現一場豐富多彩的閱讀之旅，為了共同慶祝【義大利波隆那兒童書展】以及於2月4日至9日舉辦的台北國際書展，中市圖特別串聯多場精彩活動，誠摯邀請您來一同參與這場充滿文化與創意的盛宴！\r\n【元宵喜圓滿】主題書展\r\n元宵節是春節的尾聲，有小過年之稱，代表家庭團圓和美好祝福的傳統節日。家家戶戶，張燈結彩，吃元宵、賞花燈、猜燈謎，本書展將帶領讀者探索元宵節的有趣習俗與傳說。\r\n【課：「風邪」】主題書展\r\n乍暖還寒之際，易受風寒所困，如何強身健體、飲食養生從日常做起。\r\n【愛的語言】主題書展\r\n2/14為情人節，不只是情人，家人，朋友也都能一起渡過情人節，本次書展選擇愛情小說、愛的繪本及新詩，慶祝情人節。', '臺中市立圖書館大雅分館', '臺中市大雅區雅潭路四段800號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館大雅分館', 24.22704181, 120.6411818, '無資料', 'https://reurl.cc/r37DmZ', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【故事之島：從臺灣到波隆那】/【元宵喜圓滿】/【課：「風邪」】/【愛的語言】主題書展', `description`='【故事之島：從臺灣到波隆那】主題書展\r\n展出「2024波隆那兒童書展臺灣館入選書」，本次書展將帶您穿越不同的文化與故事，【義大利波隆那兒童書展】台灣館入選書籍，包括海洋主題及年度推薦書，為您呈現一場豐富多彩的閱讀之旅，為了共同慶祝【義大利波隆那兒童書展】以及於2月4日至9日舉辦的台北國際書展，中市圖特別串聯多場精彩活動，誠摯邀請您來一同參與這場充滿文化與創意的盛宴！\r\n【元宵喜圓滿】主題書展\r\n元宵節是春節的尾聲，有小過年之稱，代表家庭團圓和美好祝福的傳統節日。家家戶戶，張燈結彩，吃元宵、賞花燈、猜燈謎，本書展將帶領讀者探索元宵節的有趣習俗與傳說。\r\n【課：「風邪」】主題書展\r\n乍暖還寒之際，易受風寒所困，如何強身健體、飲食養生從日常做起。\r\n【愛的語言】主題書展\r\n2/14為情人節，不只是情人，家人，朋友也都能一起渡過情人節，本次書展選擇愛情小說、愛的繪本及新詩，慶祝情人節。', `organizer`='臺中市立圖書館大雅分館', `address`='臺中市大雅區雅潭路四段800號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館大雅分館', `latitude`=24.22704181, `longitude`=120.6411818, `ticket_price`='無資料', `source_url`='https://reurl.cc/r37DmZ', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34526b3240c403d9887', '親子共讀創意說故事（台語）（2月2場）', '2/16\r\n潭子親子館煦珞老師-綿羊小雪\r\n該剪羊毛了！\r\n可惜綿羊小雪年紀太小，還不能剪毛，她決定先到外面的世界看看。一路上她遇到了許多動物朋友，小雪的毛也越來越長，大家都好羨慕她的毛。沒想到……"\r\n2/27\r\n大吳老師-阿嬤的果子園\r\n《阿媽的果子園》從寶寶指物認識世界開始，以「水果」為主題，希望讓嬰幼兒從愉悅、幸福的故事裡，學習到臺灣家庭生活中常食用的水果之臺語。故事特地塑造了外貌中性的角色「圓仔」和阿公、阿媽熱情互動，不但希望引領孩子們投射角色，勇敢大聲說臺語，亦期望能鼓勵長輩們盡情用母語跟孫子、孫女說故事，讓孩子們擁有更多機會聆聽到本土語言在音調、詞彙上獨有的優雅雋朗。', '臺中市立圖書館大雅分館', '臺中市大雅區雅潭路四段800號', '2025-02-16 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館大雅分館', 24.22704181, 120.6411818, '無資料', 'https://reurl.cc/xp2my4', '[]') ON DUPLICATE KEY UPDATE `activity_name`='親子共讀創意說故事（台語）（2月2場）', `description`='2/16\r\n潭子親子館煦珞老師-綿羊小雪\r\n該剪羊毛了！\r\n可惜綿羊小雪年紀太小，還不能剪毛，她決定先到外面的世界看看。一路上她遇到了許多動物朋友，小雪的毛也越來越長，大家都好羨慕她的毛。沒想到……"\r\n2/27\r\n大吳老師-阿嬤的果子園\r\n《阿媽的果子園》從寶寶指物認識世界開始，以「水果」為主題，希望讓嬰幼兒從愉悅、幸福的故事裡，學習到臺灣家庭生活中常食用的水果之臺語。故事特地塑造了外貌中性的角色「圓仔」和阿公、阿媽熱情互動，不但希望引領孩子們投射角色，勇敢大聲說臺語，亦期望能鼓勵長輩們盡情用母語跟孫子、孫女說故事，讓孩子們擁有更多機會聆聽到本土語言在音調、詞彙上獨有的優雅雋朗。', `organizer`='臺中市立圖書館大雅分館', `address`='臺中市大雅區雅潭路四段800號', `start_date`='2025-02-16 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館大雅分館', `latitude`=24.22704181, `longitude`=120.6411818, `ticket_price`='無資料', `source_url`='https://reurl.cc/xp2my4', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34526b3240c403d9889', '臺中市立圖書館北屯分館影像書法展', '這個展覽以「書法」為主題，書法展的主要目的是弘揚書法藝術，讓觀眾了解書法的歷史、文化背景及其獨特的美學價值。', '臺中市立圖書館北屯分館', '臺中市北屯區大連路三段122號', '2025-01-17 00:00:00', '2025-02-28 00:00:00', '臺中市立圖書館北屯分館', 24.18400298, 120.7362319, '無資料', 'https://reurl.cc/kMM653', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館北屯分館影像書法展', `description`='這個展覽以「書法」為主題，書法展的主要目的是弘揚書法藝術，讓觀眾了解書法的歷史、文化背景及其獨特的美學價值。', `organizer`='臺中市立圖書館北屯分館', `address`='臺中市北屯區大連路三段122號', `start_date`='2025-01-17 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市立圖書館北屯分館', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://reurl.cc/kMM653', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34626b3240c403d988b', '無資料', '外語老師Allen透過有趣的英文繪本，以故事表演、玩玩具、猜猜看、兒歌等輕鬆玩樂的方式，讓小朋友體驗快樂學習英語的樂趣。                \r\n2/16 If Animals Kissed Good Night \r\n2/23 Move Over', '臺中市立圖書館龍井山頂分館', '臺中市龍井區中沙路新庄仔巷19-1號2樓', '臺中市立圖書館龍井山頂分館', 24.20062892, 120.5283728, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='外語老師Allen透過有趣的英文繪本，以故事表演、玩玩具、猜猜看、兒歌等輕鬆玩樂的方式，讓小朋友體驗快樂學習英語的樂趣。                \r\n2/16 If Animals Kissed Good Night \r\n2/23 Move Over', `organizer`='臺中市立圖書館龍井山頂分館', `address`='臺中市龍井區中沙路新庄仔巷19-1號2樓', `location`='臺中市立圖書館龍井山頂分館', `latitude`=24.20062892, `longitude`=120.5283728, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34626b3240c403d988c', '「線之形，線之語」主題書展(2月1場)', '線條，是構成藝術與設計的靈魂。它可以是刺繡間的細膩，也可以是鋁線中的力量；它既能縱橫交錯，也能優雅流動。這場書展，邀請您欣賞線條的多樣性，從材料到形式，從技術到情感，發現線的無限美感。', '臺中市立圖書館龍井山頂分館', '臺中市龍井區中沙路新庄仔巷19-1號2樓', '2025-02-02 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館龍井山頂分館', 24.20062892, 120.5283728, '無資料', 'https://reurl.cc/O5gy5R', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「線之形，線之語」主題書展(2月1場)', `description`='線條，是構成藝術與設計的靈魂。它可以是刺繡間的細膩，也可以是鋁線中的力量；它既能縱橫交錯，也能優雅流動。這場書展，邀請您欣賞線條的多樣性，從材料到形式，從技術到情感，發現線的無限美感。', `organizer`='臺中市立圖書館龍井山頂分館', `address`='臺中市龍井區中沙路新庄仔巷19-1號2樓', `start_date`='2025-02-02 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館龍井山頂分館', `latitude`=24.20062892, `longitude`=120.5283728, `ticket_price`='無資料', `source_url`='https://reurl.cc/O5gy5R', `image_url`='[]';
