INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34726b3240c403d9891', '金蛇獻瑞-微型展覽', '將傳統結合，加上流行元素。\r\n很手工的編織，很幸福的緣分。\r\n歡迎前往觀賞~', '臺中市立圖書館大甲分館', '臺中市大甲區雁門路172號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺中市立圖書館大甲分館', 24.37827161, 120.6357901, '無資料', 'https://reurl.cc/geonQz', '[]') ON DUPLICATE KEY UPDATE `activity_name`='金蛇獻瑞-微型展覽', `description`='將傳統結合，加上流行元素。\r\n很手工的編織，很幸福的緣分。\r\n歡迎前往觀賞~', `organizer`='臺中市立圖書館大甲分館', `address`='臺中市大甲區雁門路172號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市立圖書館大甲分館', `latitude`=24.37827161, `longitude`=120.6357901, `ticket_price`='無資料', `source_url`='https://reurl.cc/geonQz', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34826b3240c403d9894', '無資料', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n   【黑白電影：光影交織的經典】\r\n\r\n放映日期：02/23(日)\r\n放映時間：14：00\r\n\r\n中文片│意亂情迷\r\n英文片│Spellbound\r\n\r\n導演│希區考克\r\n美國│1945│普遍級│劇情類│黑白│英語│111分鐘\r\n\r\n簡介\r\n愛德華因小時候誤傷弟弟，對弟弟的死一直內疚，所以有了精神疾病，也進而被捲入殺害新院長愛德華案件中，後來真相大白，原來是老院長默奇遜大夫為了保住自己的院長位置而打死了愛德華，而這個假的愛德華也與康斯坦有情人終成眷屬。', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n   【黑白電影：光影交織的經典】\r\n\r\n放映日期：02/23(日)\r\n放映時間：14：00\r\n\r\n中文片│意亂情迷\r\n英文片│Spellbound\r\n\r\n導演│希區考克\r\n美國│1945│普遍級│劇情類│黑白│英語│111分鐘\r\n\r\n簡介\r\n愛德華因小時候誤傷弟弟，對弟弟的死一直內疚，所以有了精神疾病，也進而被捲入殺害新院長愛德華案件中，後來真相大白，原來是老院長默奇遜大夫為了保住自己的院長位置而打死了愛德華，而這個假的愛德華也與康斯坦有情人終成眷屬。', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34826b3240c403d9895', '【黑白電影：光影交織的經典】│《郵差總按二次鈴》', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n   【黑白電影：光影交織的經典】\r\n\r\n放映日期：02/28(五)\r\n放映時間：14：00\r\n\r\n中文片│郵差總按二次鈴\r\n英文片│Postman Always Rings Twice\r\n\r\n導演│泰伊嘉奈特\r\n美國│1946│普遍級│劇情類│彩色│英語│113分鐘\r\n\r\n簡介\r\n四處漂泊的流浪漢與公路餐廳老闆娘相識，天雷勾動地火的兩人，很快將腦筋動到餐廳老闆頭上，他們能成功殺害餐廳老闆從此高枕無憂，廝守終生嗎？', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【黑白電影：光影交織的經典】│《郵差總按二次鈴》', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n   【黑白電影：光影交織的經典】\r\n\r\n放映日期：02/28(五)\r\n放映時間：14：00\r\n\r\n中文片│郵差總按二次鈴\r\n英文片│Postman Always Rings Twice\r\n\r\n導演│泰伊嘉奈特\r\n美國│1946│普遍級│劇情類│彩色│英語│113分鐘\r\n\r\n簡介\r\n四處漂泊的流浪漢與公路餐廳老闆娘相識，天雷勾動地火的兩人，很快將腦筋動到餐廳老闆頭上，他們能成功殺害餐廳老闆從此高枕無憂，廝守終生嗎？', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
