INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34826b3240c403d9898', '人尹合作社—寶寶劇場《馬麻，地球塑膠了！》演出及工作坊', '本活動邀請人尹合作社進行寶寶劇場演出及工作坊，帶領小小朋友及父母們一起運用戲劇技巧對生活中輕巧又方便的塑膠施加不可思議的魔法，展開這場塑膠奇幻冒險。', '桃園市兒童美術館', '桃園市中壢區高鐵南路二段90號', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '桃園市兒童美術館', 24.97993803, 121.2147243, '費用+200', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='人尹合作社—寶寶劇場《馬麻，地球塑膠了！》演出及工作坊', `description`='本活動邀請人尹合作社進行寶寶劇場演出及工作坊，帶領小小朋友及父母們一起運用戲劇技巧對生活中輕巧又方便的塑膠施加不可思議的魔法，展開這場塑膠奇幻冒險。', `organizer`='桃園市兒童美術館', `address`='桃園市中壢區高鐵南路二段90號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='桃園市兒童美術館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='費用+200', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34926b3240c403d989a', '無資料', '由來一家人為了照顧年邁的阿嬤，從東京搬到會下雪的北方鄉下。要適應新學校已經夠艱難了，偏偏這還是一間教會學校！一開始他對於「做禮拜」「福音」「講道」這些事都非常困惑，對於上帝是否存在也充滿懷疑，但久而久之他也漸漸習慣校內活動。有天，在禱告的時候，他看到迷你耶穌出現在自己眼前，而他向祂許的每個願望都成真了，他開始相信世上真的有「神蹟」。', '桃園市政府文化局', '桃園市桃園區埔新路12號', '桃園光影文化館', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='由來一家人為了照顧年邁的阿嬤，從東京搬到會下雪的北方鄉下。要適應新學校已經夠艱難了，偏偏這還是一間教會學校！一開始他對於「做禮拜」「福音」「講道」這些事都非常困惑，對於上帝是否存在也充滿懷疑，但久而久之他也漸漸習慣校內活動。有天，在禱告的時候，他看到迷你耶穌出現在自己眼前，而他向祂許的每個願望都成真了，他開始相信世上真的有「神蹟」。', `organizer`='桃園市政府文化局', `address`='桃園市桃園區埔新路12號', `location`='桃園光影文化館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34926b3240c403d989b', '無資料', '紀錄片｜2024｜美國｜BD｜110分鐘｜英語、韓語、德語發音｜中文字幕. 導演：Amanda Kim\r\n早在1960年代網路尚未發展之時，白南準便以「破壞藝術家」之稱聞名，透過錄像藝術刻畫他對未來資訊科技發展的奇思。1974年，他便以「資訊高速公路」形容數據媒體傳播。這樣的概念在當時極度創新，大膽又準確預測了當今世界各地實時交流、新媒體的急速傳播；他的前衛之舉，更創造出一種空前的視覺饗宴。本片帶領觀眾深入白南準世界裡科學、藝術、流行文化的破格及融合，同時也見證身處未來的我們，如何活出白南準眼中的異想世界！', '桃園市政府文化局', '桃園市桃園區埔新路12號', '桃園光影文化館', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='紀錄片｜2024｜美國｜BD｜110分鐘｜英語、韓語、德語發音｜中文字幕. 導演：Amanda Kim\r\n早在1960年代網路尚未發展之時，白南準便以「破壞藝術家」之稱聞名，透過錄像藝術刻畫他對未來資訊科技發展的奇思。1974年，他便以「資訊高速公路」形容數據媒體傳播。這樣的概念在當時極度創新，大膽又準確預測了當今世界各地實時交流、新媒體的急速傳播；他的前衛之舉，更創造出一種空前的視覺饗宴。本片帶領觀眾深入白南準世界裡科學、藝術、流行文化的破格及融合，同時也見證身處未來的我們，如何活出白南準眼中的異想世界！', `organizer`='桃園市政府文化局', `address`='桃園市桃園區埔新路12號', `location`='桃園光影文化館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34926b3240c403d989c', '無資料', '探討BL創作在性別與愛情表現上的突破，包括其挑戰傳統性別刻板印象，探索多元愛情形式，並分析其對文化多樣性與社會價值觀的影響，以及如何促進性別平權與跨文化交流的可能性。', '臺南市美術館', '臺南市中西區臺南市中西區忠義路二段 1 號', '臺南市美術館2館', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='探討BL創作在性別與愛情表現上的突破，包括其挑戰傳統性別刻板印象，探索多元愛情形式，並分析其對文化多樣性與社會價值觀的影響，以及如何促進性別平權與跨文化交流的可能性。', `organizer`='臺南市美術館', `address`='臺南市中西區臺南市中西區忠義路二段 1 號', `location`='臺南市美術館2館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34a26b3240c403d989d', 'bulabulay．原民之耀-葫蘆講堂：經典的原民衣飾文化', '「bulabulay • 原民之耀」大展集結臺灣博物館界19座公私立博物館、3位部落族人(阿美、排灣、魯凱)、2位收藏家、1位畫家，提供共近200組件國寶、重要古物、一般古物與經典展品。期間辦理免費講座，發現深厚內涵的臺灣原住民族文化寶藏。\r\n※講題：經典的原民衣飾文化\r\n※講者：李莎莉女士(財團法人福祿文化基金會執行長)\r\n※大綱：臺灣原住民族的服飾多彩多姿，不論在形制、技法、圖紋以及色彩上，均保存著傳統文化的內涵，講座將分享各原住民族「穿的藝術」以及文化意涵。其經典之處在於美學藝術的創造與節慶祭典的保存與傳承。', '財團法人福祿文化基金會', '臺北市大安區羅斯福路4段1號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '國立臺灣大學校史館', 25.02677012, 121.5434446, '無資料', 'https://bulabulay.com/lecture', '[]') ON DUPLICATE KEY UPDATE `activity_name`='bulabulay．原民之耀-葫蘆講堂：經典的原民衣飾文化', `description`='「bulabulay • 原民之耀」大展集結臺灣博物館界19座公私立博物館、3位部落族人(阿美、排灣、魯凱)、2位收藏家、1位畫家，提供共近200組件國寶、重要古物、一般古物與經典展品。期間辦理免費講座，發現深厚內涵的臺灣原住民族文化寶藏。\r\n※講題：經典的原民衣飾文化\r\n※講者：李莎莉女士(財團法人福祿文化基金會執行長)\r\n※大綱：臺灣原住民族的服飾多彩多姿，不論在形制、技法、圖紋以及色彩上，均保存著傳統文化的內涵，講座將分享各原住民族「穿的藝術」以及文化意涵。其經典之處在於美學藝術的創造與節慶祭典的保存與傳承。', `organizer`='財團法人福祿文化基金會', `address`='臺北市大安區羅斯福路4段1號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='國立臺灣大學校史館', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='無資料', `source_url`='https://bulabulay.com/lecture', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34a26b3240c403d989e', '2025 新聲代．巡演ing-阿丹玩球球 ⨯ 阿克沃', '︙ 阿丹玩球球\r\n每個人心中都有一個阿丹\r\n他喜歡玩球、追夢\r\n可是大人說要長大就不能玩球？\r\n\r\n有時浪漫、有時深陷黑洞，散步的時候可以聽、也可以在環島公路上大聲哼唱著，不管好的壞的、失速或是超重，海浪說會帶我們去遠方，阿丹玩球球會把地球送給你。\r\n𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄\r\n  ︙ 阿克沃\r\n那些夜裡的寂寞難耐\r\n理想的求而不得\r\n感情的離情別緒\r\n這些遺憾、糾結、痛苦和無奈\r\n就由我們來承接吧\r\n我們是阿克沃\r\n\r\n大家好我們是阿克沃，這個名字其實就是尷尬的英文（awkward）直接音譯過來的，尷尬是社交過程的人之常情，但如果是透過音樂所認識的朋友卻能馬上混熟幾乎不尷尬。取名為阿克沃就是希望我們能夠成為讓人不尷尬的樂團 ，讓聽眾都能放下心中的芥蒂、享受片刻的音樂。', '臺南市政府文化局', '臺南市新營區', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '新營區（臺南市）=', 23.30152488, 120.2954067, '低消入場+--', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 新聲代．巡演ing-阿丹玩球球 ⨯ 阿克沃', `description`='︙ 阿丹玩球球\r\n每個人心中都有一個阿丹\r\n他喜歡玩球、追夢\r\n可是大人說要長大就不能玩球？\r\n\r\n有時浪漫、有時深陷黑洞，散步的時候可以聽、也可以在環島公路上大聲哼唱著，不管好的壞的、失速或是超重，海浪說會帶我們去遠方，阿丹玩球球會把地球送給你。\r\n𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄𓐄\r\n  ︙ 阿克沃\r\n那些夜裡的寂寞難耐\r\n理想的求而不得\r\n感情的離情別緒\r\n這些遺憾、糾結、痛苦和無奈\r\n就由我們來承接吧\r\n我們是阿克沃\r\n\r\n大家好我們是阿克沃，這個名字其實就是尷尬的英文（awkward）直接音譯過來的，尷尬是社交過程的人之常情，但如果是透過音樂所認識的朋友卻能馬上混熟幾乎不尷尬。取名為阿克沃就是希望我們能夠成為讓人不尷尬的樂團 ，讓聽眾都能放下心中的芥蒂、享受片刻的音樂。', `organizer`='臺南市政府文化局', `address`='臺南市新營區', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='新營區（臺南市）=', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='低消入場+--', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34b26b3240c403d98a1', '香蕉電影院：世界母語日', '在螢幕前度過的時光，電影成為了我們通往不同世界的窗戶。無論是感人至深的劇情、驚心動魄的動作場面，還是輕鬆幽默的喜劇，觀看電影讓我們沉浸於各種情感之中，享受故事所帶來的魅力和心靈的震撼。\r\n\r\n配合世界母語日台語主題播放影片：\r\n花田少年史:台語版', '高雄市立圖書館總館', '高雄市旗山區大德里6鄰中學路42號', '2025-03-28 00:00:00', '2025-03-28 00:00:00', '高雄市立圖書館旗山分館', 25.0421407, 121.5198716, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='香蕉電影院：世界母語日', `description`='在螢幕前度過的時光，電影成為了我們通往不同世界的窗戶。無論是感人至深的劇情、驚心動魄的動作場面，還是輕鬆幽默的喜劇，觀看電影讓我們沉浸於各種情感之中，享受故事所帶來的魅力和心靈的震撼。\r\n\r\n配合世界母語日台語主題播放影片：\r\n花田少年史:台語版', `organizer`='高雄市立圖書館總館', `address`='高雄市旗山區大德里6鄰中學路42號', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='高雄市立圖書館旗山分館', `latitude`=25.0421407, `longitude`=121.5198716, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34c26b3240c403d98a5', '無資料', '泛亞藝術聯盟協會透過「第15屆亞洲藝術聯盟大展2025在桃園」提供藝術交流平台，邀集來自不同文化背景的藝術家與藝術愛好者互動，不僅促進理解與尊重，也激發在地創作靈感與技術提升。\r\n主講者：謝亞修（台灣新世代收藏家）', '泛亞藝術聯盟協會', '桃園市桃園區中正路1188號', '桃園展演中心', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='泛亞藝術聯盟協會透過「第15屆亞洲藝術聯盟大展2025在桃園」提供藝術交流平台，邀集來自不同文化背景的藝術家與藝術愛好者互動，不僅促進理解與尊重，也激發在地創作靈感與技術提升。\r\n主講者：謝亞修（台灣新世代收藏家）', `organizer`='泛亞藝術聯盟協會', `address`='桃園市桃園區中正路1188號', `location`='桃園展演中心', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34c26b3240c403d98a6', '無資料', '泛亞藝術聯盟協會透過「第15屆亞洲藝術聯盟大展2025在桃園」提供藝術交流平台，邀集來自不同文化背景的藝術家與藝術愛好者互動，不僅促進理解與尊重，也激發在地創作靈感與技術提升。\r\n主講者：蕭瓊瑞教授（策展人）', '泛亞藝術聯盟協會', '桃園市桃園區中正路1188號', '桃園展演中心', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='泛亞藝術聯盟協會透過「第15屆亞洲藝術聯盟大展2025在桃園」提供藝術交流平台，邀集來自不同文化背景的藝術家與藝術愛好者互動，不僅促進理解與尊重，也激發在地創作靈感與技術提升。\r\n主講者：蕭瓊瑞教授（策展人）', `organizer`='泛亞藝術聯盟協會', `address`='桃園市桃園區中正路1188號', `location`='桃園展演中心', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34c26b3240c403d98a7', '温度：蒲添生x蒲浩明父子雕塑展', '本展以「溫度」呈現父子間的情感連結及作品脈絡，探討血緣與創作的交織。展覽結合家族親情與藝術史，闡述臺灣美術史在二十世紀前後的變遷，並從親情、身體、歷史與社會等多元視角，與觀眾分享兩位藝術家創作的發展與故事。\r\n\r\n雕塑作品不止可以觀看，觸覺在藝術家的創作過程中，舉凡材質的選擇、表面肌理的營造，都可以反映出藝術家個人獨特的語彙。藉由這個雕塑展，我們也規劃了專屬觸摸學習區，同時讓眼明和眼盲的觀眾，都可以用與雕塑家「手談」，感受藝術家想要傳達的人文內涵與「温度」。', '臺南市美術館', '臺南市中西區臺南市中西區南門路 37 號', '2025-02-25 00:00:00', '2025-06-01 00:00:00', '臺南市美術館1館', 22.99594458, 120.192874, '詳參　https://www.tnam.museum/visit/hours_tickets+--', 'https://www.tnam.museum/exhibition/detail/584', '[]') ON DUPLICATE KEY UPDATE `activity_name`='温度：蒲添生x蒲浩明父子雕塑展', `description`='本展以「溫度」呈現父子間的情感連結及作品脈絡，探討血緣與創作的交織。展覽結合家族親情與藝術史，闡述臺灣美術史在二十世紀前後的變遷，並從親情、身體、歷史與社會等多元視角，與觀眾分享兩位藝術家創作的發展與故事。\r\n\r\n雕塑作品不止可以觀看，觸覺在藝術家的創作過程中，舉凡材質的選擇、表面肌理的營造，都可以反映出藝術家個人獨特的語彙。藉由這個雕塑展，我們也規劃了專屬觸摸學習區，同時讓眼明和眼盲的觀眾，都可以用與雕塑家「手談」，感受藝術家想要傳達的人文內涵與「温度」。', `organizer`='臺南市美術館', `address`='臺南市中西區臺南市中西區南門路 37 號', `start_date`='2025-02-25 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='臺南市美術館1館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='詳參　https://www.tnam.museum/visit/hours_tickets+--', `source_url`='https://www.tnam.museum/exhibition/detail/584', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34c26b3240c403d98a8', '臺南市立圖書館:2月台語說故事', '(台語) 小蛇散步、(台語) 吃掉了什麼', '臺南市立圖書館', '臺南市永康區710038 臺南市永康區東橋里康橋大道255號', '2025-02-26 00:00:00', '2025-02-26 00:00:00', '臺南市立圖書館(新總館)', 23.02729532, 120.2542795, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市立圖書館:2月台語說故事', `description`='(台語) 小蛇散步、(台語) 吃掉了什麼', `organizer`='臺南市立圖書館', `address`='臺南市永康區710038 臺南市永康區東橋里康橋大道255號', `start_date`='2025-02-26 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='臺南市立圖書館(新總館)', `latitude`=23.02729532, `longitude`=120.2542795, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34c26b3240c403d98a9', '無資料', '職男人生系列是以日式搞笑風格為主的表演，內容包含漫才和短劇兩種形式，主要由4位演員董軒、耿賢、阿量、木森自編自導自演。\r\n於2019年創團，目前全台累積超過30萬人票房。\r\n曾與全台威秀影城合作，開創舞台劇在影城演出的特別體驗。\r\n職男人生系列目前已至全台7縣市巡演，邀請各位觀眾一同進入捧腹大笑的世界。', '面白大丈夫劇團', '臺北市信義區市府路1號', '臺北市政府', 25.03062083, 121.5716697, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='職男人生系列是以日式搞笑風格為主的表演，內容包含漫才和短劇兩種形式，主要由4位演員董軒、耿賢、阿量、木森自編自導自演。\r\n於2019年創團，目前全台累積超過30萬人票房。\r\n曾與全台威秀影城合作，開創舞台劇在影城演出的特別體驗。\r\n職男人生系列目前已至全台7縣市巡演，邀請各位觀眾一同進入捧腹大笑的世界。', `organizer`='面白大丈夫劇團', `address`='臺北市信義區市府路1號', `location`='臺北市政府', `latitude`=25.03062083, `longitude`=121.5716697, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34c26b3240c403d98aa', '無資料', '復興京劇團全樑上霸、精銳盡出，演出七雄聚義智取生辰綱、大鬧江州、三打祝家莊、吳用智取大名府、英雄義《一箭仇》等水滸傳經典故事。', '國立臺灣戲曲學院', '臺北市松山區八德路3段25號', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='復興京劇團全樑上霸、精銳盡出，演出七雄聚義智取生辰綱、大鬧江州、三打祝家莊、吳用智取大名府、英雄義《一箭仇》等水滸傳經典故事。', `organizer`='國立臺灣戲曲學院', `address`='臺北市松山區八德路3段25號', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34d26b3240c403d98ab', '許芯慈 創作個展「自我的版圖」 ', '⭓ 藝術家介紹\r\n許芯慈，1995年出生於臺南，目前居住於臺北。畢業於國立臺北藝術大學美術系，於荷蘭Frank Mohr Institute 研究所取得藝術碩士。她的創作多以複合媒材、裝置及影像為表現形式，探索遷移者如何將對於空間的身體經驗及記憶，在移居的過程中重新想像與體現。近期，她關注個人身體與周遭物質環境的關係，在勞動與生產的過程中尋找自我的位置。\r\n\r\n⭓ 展覽介紹\r\n本次個展「自我的版圖」觀察跨國遷移者如何透過身體與周遭物質環境的關係來確立自我，並在工作過程中想像自身的位置。展覽以藝術家在荷蘭餐廳打工的經驗為發想，將廚房中的流理臺視為地域與疆界，器皿則是棋，而勞動的過程如同不斷地試探與調整，在重複性的動作中探索，並嘗試建構自我的版圖。藉由廚房物件與遊戲的聯想，重現遷移者在認同形構過程中的無奈與期待，以及他們如何在混雜的場域中協商界線與認同。\r\n\r\n󠀠藝術家專訪➢https://kingcar.pro/en14x6NNf\r\n\r\n⭓ 展覽資訊\r\n許芯慈 創作個展「自我的版圖」\r\nShiu Jui-Tsz Solo Exhibition: Territory of Self\r\n展期：2025.02.11 (二) – 04.02 (三)\r\n開幕：2025.02.22 (六) 14:00\r\n地點：金車文藝中心 承德館\r\n地址：臺北市承德路三段131號\r\n主辦單位：金車文教基金會 / 金車文藝中心KCCA', '財團法人金車文教基金會', '臺北市大同區', '2025-02-11 00:00:00', '2025-04-02 00:00:00', '大同區（臺北市）=', 25.06342433, 121.5130417, '無資料', 'https://www.kingcarart.org.tw/exhibitions-detail/220', '[]') ON DUPLICATE KEY UPDATE `activity_name`='許芯慈 創作個展「自我的版圖」 ', `description`='⭓ 藝術家介紹\r\n許芯慈，1995年出生於臺南，目前居住於臺北。畢業於國立臺北藝術大學美術系，於荷蘭Frank Mohr Institute 研究所取得藝術碩士。她的創作多以複合媒材、裝置及影像為表現形式，探索遷移者如何將對於空間的身體經驗及記憶，在移居的過程中重新想像與體現。近期，她關注個人身體與周遭物質環境的關係，在勞動與生產的過程中尋找自我的位置。\r\n\r\n⭓ 展覽介紹\r\n本次個展「自我的版圖」觀察跨國遷移者如何透過身體與周遭物質環境的關係來確立自我，並在工作過程中想像自身的位置。展覽以藝術家在荷蘭餐廳打工的經驗為發想，將廚房中的流理臺視為地域與疆界，器皿則是棋，而勞動的過程如同不斷地試探與調整，在重複性的動作中探索，並嘗試建構自我的版圖。藉由廚房物件與遊戲的聯想，重現遷移者在認同形構過程中的無奈與期待，以及他們如何在混雜的場域中協商界線與認同。\r\n\r\n󠀠藝術家專訪➢https://kingcar.pro/en14x6NNf\r\n\r\n⭓ 展覽資訊\r\n許芯慈 創作個展「自我的版圖」\r\nShiu Jui-Tsz Solo Exhibition: Territory of Self\r\n展期：2025.02.11 (二) – 04.02 (三)\r\n開幕：2025.02.22 (六) 14:00\r\n地點：金車文藝中心 承德館\r\n地址：臺北市承德路三段131號\r\n主辦單位：金車文教基金會 / 金車文藝中心KCCA', `organizer`='財團法人金車文教基金會', `address`='臺北市大同區', `start_date`='2025-02-11 00:00:00', `end_date`='2025-04-02 00:00:00', `location`='大同區（臺北市）=', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='無資料', `source_url`='https://www.kingcarart.org.tw/exhibitions-detail/220', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34d26b3240c403d98ac', '李芳妤 創作個展【Tile Tail】', '藝術家介紹\r\n李芳妤，1997年出生於臺灣臺北，目前就讀於國立臺北藝術大學美術學系碩士班，擅長以幽默與輕盈的視覺語言探索日常符號的藝術家。她的創作關注觀看的變異性，擅長透過拼貼、圖像錯位與材質實驗，挑戰固有認知框架解構重組，轉化為獨特的視覺語彙。\r\n\r\n展覽介紹\r\n《Tile Tail》試圖延續這種「好像有關係又沒關係」的連結，將不同時間軸下的日常物件與符號重新組合，以模糊既有的習慣認知。透過這些看似隨機的重組與拼接，作品邀請觀者從熟悉的觀看方式中跳脫，重新感受那些被忽略或視為平凡的事物之間所孕育的新奇與趣味。創作並不尋求沉重的意義或深刻的闡釋，而是以輕盈的態度在空間中進行探索。這些作品像是日常生活的遊戲，從隨意的聯想出發，以幽默而自由的方式串聯視覺與感知經驗。希望觀者能在這樣的創作中感受到不受限的可能性，並與這些「無意義卻充滿趣味」的片段產生對話。\r\n\r\n文章連結➤ https://www.kingcarart.org.tw/exhibitions-detail/221\r\n', '財團法人金車文教基金會', '臺北市大同區', '2025-02-11 00:00:00', '2025-04-02 00:00:00', '大同區（臺北市）=', 25.06342433, 121.5130417, '無資料', 'https://www.kingcarart.org.tw/exhibitions-detail/221', '[]') ON DUPLICATE KEY UPDATE `activity_name`='李芳妤 創作個展【Tile Tail】', `description`='藝術家介紹\r\n李芳妤，1997年出生於臺灣臺北，目前就讀於國立臺北藝術大學美術學系碩士班，擅長以幽默與輕盈的視覺語言探索日常符號的藝術家。她的創作關注觀看的變異性，擅長透過拼貼、圖像錯位與材質實驗，挑戰固有認知框架解構重組，轉化為獨特的視覺語彙。\r\n\r\n展覽介紹\r\n《Tile Tail》試圖延續這種「好像有關係又沒關係」的連結，將不同時間軸下的日常物件與符號重新組合，以模糊既有的習慣認知。透過這些看似隨機的重組與拼接，作品邀請觀者從熟悉的觀看方式中跳脫，重新感受那些被忽略或視為平凡的事物之間所孕育的新奇與趣味。創作並不尋求沉重的意義或深刻的闡釋，而是以輕盈的態度在空間中進行探索。這些作品像是日常生活的遊戲，從隨意的聯想出發，以幽默而自由的方式串聯視覺與感知經驗。希望觀者能在這樣的創作中感受到不受限的可能性，並與這些「無意義卻充滿趣味」的片段產生對話。\r\n\r\n文章連結➤ https://www.kingcarart.org.tw/exhibitions-detail/221\r\n', `organizer`='財團法人金車文教基金會', `address`='臺北市大同區', `start_date`='2025-02-11 00:00:00', `end_date`='2025-04-02 00:00:00', `location`='大同區（臺北市）=', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='無資料', `source_url`='https://www.kingcarart.org.tw/exhibitions-detail/221', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34d26b3240c403d98ad', '璀璨新屋.客庄樂學-新陽平社區大學社區學習藝文展演', '邀請社區班隊進行土風舞及現代舞表演，現場另有樂活綠市集展出。', '桃園市社會教育協進會', '桃園市新屋區中華路658號', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '桃園市私立清華高級中學', 24.97280352, 121.067758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='璀璨新屋.客庄樂學-新陽平社區大學社區學習藝文展演', `description`='邀請社區班隊進行土風舞及現代舞表演，現場另有樂活綠市集展出。', `organizer`='桃園市社會教育協進會', `address`='桃園市新屋區中華路658號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='桃園市私立清華高級中學', `latitude`=24.97280352, `longitude`=121.067758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34e26b3240c403d98b0', '黃紫瑜 創作個展 【金屬宣言：一種想像中的物質】', '☖ 藝術家介紹 \r\n黃紫瑜的創作主要以雕塑、數位影像等形式為主。\r\n個人創作脈絡以雕塑創作技術背景作為出發，由雕塑延伸的感知、空間、材質、技術作為創作的核心議題，並將材質政治、金屬材質、奇石、夢核(Dreamcore)、城市景觀、數位經驗等等作為創作的方向，重新思考雕塑與文化擴延的可能性與表演性的展開。\r\n近期創作關注於對金屬這項材料、物質的本質思考，反思材質分類形成的原因及其建構過程，純金屬的純粹是否只是相對的純，而金屬是否只是想像中的物質，並以雕塑與其材質政治作為雕塑創作的可能性。\r\n\r\n採訪文章 ► https://reurl.cc/oVAoDv\r\n\r\n☖ 展覽介紹\r\n從有金屬冶煉技術以來，金屬材質特性與提煉、純粹執念，延伸人類至的統治系統，從神話、宗教、現代國家、殖民體系到科學當中，金屬宣言創作計畫嘗試藉由金屬梳理出一條關於物質所塑造的排他性支配思想與意識形態，展覽作品將金屬分為三種，傳統金屬、科技金屬與數位金屬。傳統金屬展現了其自身的質感，支撐著視覺化的神聖、純潔與高貴等象徵意義，並反映出排他性的支配思想與意識形態。科技金屬關聯於當代科學體制，象徵權力的暴力與高貴，探討金屬如何成為掌權者的暴力縮影。而數位金屬則包含複雜的視覺化與文化意義，呈現未來感與科幻感，反映出對未來的想像與可能性。藉由對物的思考，探索物質與人類精神性、超越性與未來性建構的緊密關聯。另同時擴展雕塑與其材質政治與未來想像作為雕塑創作的可能性。\r\n\r\n☖ 展覽資訊\r\n黃紫瑜 創作個展 【金屬宣言：一種想像中的物質】\r\nHuang Tzu-Yu Solo Exhibition: Metal Manifesto: A Substance of Hypothetical\r\n展期：2025/02/11(二)-04/06(日)\r\n開幕：2025.02.22 (六) 下午15:00\r\n地點：KCCA 承德館\r\n地址：臺北市大同區承德路三段131號\r\n主辦單位｜金車文教基金會 / 金車文藝中心 KCCA', '金車文藝中心', '臺北市大同區', '2025-02-11 00:00:00', '2025-04-02 00:00:00', '大同區（臺北市）=', 25.06342433, 121.5130417, '無資料', 'https://www.kingcarart.org.tw/exhibitions-detail/219', '[]') ON DUPLICATE KEY UPDATE `activity_name`='黃紫瑜 創作個展 【金屬宣言：一種想像中的物質】', `description`='☖ 藝術家介紹 \r\n黃紫瑜的創作主要以雕塑、數位影像等形式為主。\r\n個人創作脈絡以雕塑創作技術背景作為出發，由雕塑延伸的感知、空間、材質、技術作為創作的核心議題，並將材質政治、金屬材質、奇石、夢核(Dreamcore)、城市景觀、數位經驗等等作為創作的方向，重新思考雕塑與文化擴延的可能性與表演性的展開。\r\n近期創作關注於對金屬這項材料、物質的本質思考，反思材質分類形成的原因及其建構過程，純金屬的純粹是否只是相對的純，而金屬是否只是想像中的物質，並以雕塑與其材質政治作為雕塑創作的可能性。\r\n\r\n採訪文章 ► https://reurl.cc/oVAoDv\r\n\r\n☖ 展覽介紹\r\n從有金屬冶煉技術以來，金屬材質特性與提煉、純粹執念，延伸人類至的統治系統，從神話、宗教、現代國家、殖民體系到科學當中，金屬宣言創作計畫嘗試藉由金屬梳理出一條關於物質所塑造的排他性支配思想與意識形態，展覽作品將金屬分為三種，傳統金屬、科技金屬與數位金屬。傳統金屬展現了其自身的質感，支撐著視覺化的神聖、純潔與高貴等象徵意義，並反映出排他性的支配思想與意識形態。科技金屬關聯於當代科學體制，象徵權力的暴力與高貴，探討金屬如何成為掌權者的暴力縮影。而數位金屬則包含複雜的視覺化與文化意義，呈現未來感與科幻感，反映出對未來的想像與可能性。藉由對物的思考，探索物質與人類精神性、超越性與未來性建構的緊密關聯。另同時擴展雕塑與其材質政治與未來想像作為雕塑創作的可能性。\r\n\r\n☖ 展覽資訊\r\n黃紫瑜 創作個展 【金屬宣言：一種想像中的物質】\r\nHuang Tzu-Yu Solo Exhibition: Metal Manifesto: A Substance of Hypothetical\r\n展期：2025/02/11(二)-04/06(日)\r\n開幕：2025.02.22 (六) 下午15:00\r\n地點：KCCA 承德館\r\n地址：臺北市大同區承德路三段131號\r\n主辦單位｜金車文教基金會 / 金車文藝中心 KCCA', `organizer`='金車文藝中心', `address`='臺北市大同區', `start_date`='2025-02-11 00:00:00', `end_date`='2025-04-02 00:00:00', `location`='大同區（臺北市）=', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='無資料', `source_url`='https://www.kingcarart.org.tw/exhibitions-detail/219', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34f26b3240c403d98b1', '2025復興區櫻花季推廣活動－帶著相機去賞櫻攝影比賽收件', '復興區擁有豐富的自然景觀，每到春天復興各地區沿途依著海拔及氣候溫度此起彼落開著各種櫻花，非常浪漫美麗。為展現復興區風采，推廣在地觀光旅遊，並發掘更多賞櫻地點，故於櫻花季活動期間舉辦「2025復興區櫻花季攝影比賽」，串聯在地，讓民眾透過鏡頭發現復興區之美。\r\n參加資格：凡愛好攝影人士，均歡迎報名參加。參賽者未滿18歲者，需有法定代理人簽名同意。\r\n參加組別：1.照片組、2.短片組。\r\n攝影主題：\r\n限定以復興區櫻花季期間(限定 114 年 2 月 17 日-3 月 31 日)各種櫻花為主角的攝影作品，以「我與我的_______，跟著櫻花去復興區旅行」為題來做創意發想。如有拍攝地點標示不清、非復興區拍攝，或者查有不實者，一律取消參賽資格。\r\n報名方式：\r\n1.本競賽活動免報名費用，填寫相關資料即可報名，作品名稱請統一為：「組別_參賽者姓名_作品名稱」 ，例如「照片組_王大明_我與我的拉拉山櫻花，跟著櫻花去復興區旅行」。\r\n2.作品及報名文件繳交：\r\n需將作品與報名附件一同繳交完成，未於期限內補件者視同放棄資格，逾期不受理。\r\n3.報名必須檢附「報名表、授權書與切結書」等文件，詳附件 1及附件2，每個作品皆須個別填寫並簽名。\r\n4.下載報名表及附件，詳讀內容並親簽名後，於活動截止日前將報名表及附件與作品置於同一資料夾，再以壓縮檔寄送至活動指定 mail：fuxingsakura@gmail.com。\r\n5.主辦單位確認收件後會以mail回覆，作為收件證明，若缺件將提醒並告知最後收件日期。\r\n獎勵方式：\r\n1.照片組\r\n第一名(1名) 獎金新臺幣10,000 元，獎狀乙紙。\r\n第二名(1名) 獎金新臺幣8,000 元，獎狀乙紙。\r\n第三名(1名) 獎金新臺幣5,000 元，獎狀乙紙。\r\n佳作(20名) 獎金新臺幣1,600 元，獎狀乙紙。\r\n2.短片組\r\n特優獎(1名) 獎金新臺幣15,000 元，獎狀乙紙。\r\n優選獎(5名) 獎金新臺幣8,000 元，獎狀乙紙。\r\n佳作(10名) 獎金新臺幣2,500 元，獎狀乙紙。', '桃園市復興區公所', '桃園市復興區中正路20號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '桃園市復興區公所', 24.72949884, 121.3754588, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025復興區櫻花季推廣活動－帶著相機去賞櫻攝影比賽收件', `description`='復興區擁有豐富的自然景觀，每到春天復興各地區沿途依著海拔及氣候溫度此起彼落開著各種櫻花，非常浪漫美麗。為展現復興區風采，推廣在地觀光旅遊，並發掘更多賞櫻地點，故於櫻花季活動期間舉辦「2025復興區櫻花季攝影比賽」，串聯在地，讓民眾透過鏡頭發現復興區之美。\r\n參加資格：凡愛好攝影人士，均歡迎報名參加。參賽者未滿18歲者，需有法定代理人簽名同意。\r\n參加組別：1.照片組、2.短片組。\r\n攝影主題：\r\n限定以復興區櫻花季期間(限定 114 年 2 月 17 日-3 月 31 日)各種櫻花為主角的攝影作品，以「我與我的_______，跟著櫻花去復興區旅行」為題來做創意發想。如有拍攝地點標示不清、非復興區拍攝，或者查有不實者，一律取消參賽資格。\r\n報名方式：\r\n1.本競賽活動免報名費用，填寫相關資料即可報名，作品名稱請統一為：「組別_參賽者姓名_作品名稱」 ，例如「照片組_王大明_我與我的拉拉山櫻花，跟著櫻花去復興區旅行」。\r\n2.作品及報名文件繳交：\r\n需將作品與報名附件一同繳交完成，未於期限內補件者視同放棄資格，逾期不受理。\r\n3.報名必須檢附「報名表、授權書與切結書」等文件，詳附件 1及附件2，每個作品皆須個別填寫並簽名。\r\n4.下載報名表及附件，詳讀內容並親簽名後，於活動截止日前將報名表及附件與作品置於同一資料夾，再以壓縮檔寄送至活動指定 mail：fuxingsakura@gmail.com。\r\n5.主辦單位確認收件後會以mail回覆，作為收件證明，若缺件將提醒並告知最後收件日期。\r\n獎勵方式：\r\n1.照片組\r\n第一名(1名) 獎金新臺幣10,000 元，獎狀乙紙。\r\n第二名(1名) 獎金新臺幣8,000 元，獎狀乙紙。\r\n第三名(1名) 獎金新臺幣5,000 元，獎狀乙紙。\r\n佳作(20名) 獎金新臺幣1,600 元，獎狀乙紙。\r\n2.短片組\r\n特優獎(1名) 獎金新臺幣15,000 元，獎狀乙紙。\r\n優選獎(5名) 獎金新臺幣8,000 元，獎狀乙紙。\r\n佳作(10名) 獎金新臺幣2,500 元，獎狀乙紙。', `organizer`='桃園市復興區公所', `address`='桃園市復興區中正路20號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='桃園市復興區公所', `latitude`=24.72949884, `longitude`=121.3754588, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34f26b3240c403d98b2', '第四屆「舞告厲害」全國反毒K-POP創意舞蹈大賽', '藉由此次活動提供年輕學子一個展示自己的舞台,並在競賽中融入反毒議題,提升年輕學子反自我保護意識,透過比賽促進校與校之間的交流。\r\n參加對象：全國高中職、大專校院在學學生。\r\n獎項：\r\n高中職組：\r\n    冠軍(1隊)：獎金12,000元及獎狀乙紙。\r\n    亞軍(1隊)：獎金8,000元及獎狀乙紙。\r\n    季軍(1隊)：獎金5,000元及獎狀乙紙。\r\n    優選(1隊)：獎金3,000元及獎狀乙紙。\r\n    特殊表現獎(2隊)：獎金3,000元及獎狀乙紙。\r\n    獨立獎項(5隊)：獎金1,000元及獎狀乙紙。\r\n大專校院組：\r\n    冠軍(1隊)：獎金8,000元及獎狀乙紙。\r\n    亞軍(1隊)：獎金5,000元及獎狀乙紙。\r\n    季軍(1隊)：獎金3,000元及獎狀乙紙。\r\n*本活動有對外開放開放觀賽。', '開南大學', '桃園市蘆竹區開南路1號', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '開南大學', 25.0113673, 121.270208, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第四屆「舞告厲害」全國反毒K-POP創意舞蹈大賽', `description`='藉由此次活動提供年輕學子一個展示自己的舞台,並在競賽中融入反毒議題,提升年輕學子反自我保護意識,透過比賽促進校與校之間的交流。\r\n參加對象：全國高中職、大專校院在學學生。\r\n獎項：\r\n高中職組：\r\n    冠軍(1隊)：獎金12,000元及獎狀乙紙。\r\n    亞軍(1隊)：獎金8,000元及獎狀乙紙。\r\n    季軍(1隊)：獎金5,000元及獎狀乙紙。\r\n    優選(1隊)：獎金3,000元及獎狀乙紙。\r\n    特殊表現獎(2隊)：獎金3,000元及獎狀乙紙。\r\n    獨立獎項(5隊)：獎金1,000元及獎狀乙紙。\r\n大專校院組：\r\n    冠軍(1隊)：獎金8,000元及獎狀乙紙。\r\n    亞軍(1隊)：獎金5,000元及獎狀乙紙。\r\n    季軍(1隊)：獎金3,000元及獎狀乙紙。\r\n*本活動有對外開放開放觀賽。', `organizer`='開南大學', `address`='桃園市蘆竹區開南路1號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='開南大學', `latitude`=25.0113673, `longitude`=121.270208, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34f26b3240c403d98b3', '張亞蓁 創作個展【異景．心戲】', '本次個展張亞蓁以「園林」為核心，探索「人造空間」與「主觀世界」的對話。一是以現代家居為基礎，構築私人樂園般的理想小天地；二是從臺灣在地的園林造景中汲取靈感，描繪內心的世界。\r\n「園林」不僅是自然的縮影，更是張亞蓁心中理想之地的投射與寄託。她的創作彷彿在現代生活中創造一座異托邦，邀請觀者沉浸於她的內心風景，感受其中的詩意與幻境。', '金車文藝中心', '臺北市中山區', '2025-02-08 00:00:00', '2025-03-23 00:00:00', '中山區（臺北市）=', 25.06969917, 121.5381597, '無資料', 'https://www.kingcarart.org.tw/exhibitions-detail/218', '[]') ON DUPLICATE KEY UPDATE `activity_name`='張亞蓁 創作個展【異景．心戲】', `description`='本次個展張亞蓁以「園林」為核心，探索「人造空間」與「主觀世界」的對話。一是以現代家居為基礎，構築私人樂園般的理想小天地；二是從臺灣在地的園林造景中汲取靈感，描繪內心的世界。\r\n「園林」不僅是自然的縮影，更是張亞蓁心中理想之地的投射與寄託。她的創作彷彿在現代生活中創造一座異托邦，邀請觀者沉浸於她的內心風景，感受其中的詩意與幻境。', `organizer`='金車文藝中心', `address`='臺北市中山區', `start_date`='2025-02-08 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='中山區（臺北市）=', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='https://www.kingcarart.org.tw/exhibitions-detail/218', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e34f26b3240c403d98b4', '無資料', '泰雅族自約五千年前即開始在台灣活動，族群文化從狩獵演變至農耕，並逐步建立聚落。其中，小米（trakis）是泰雅族的重要主食與文化象徵，族人傳統上於每年12月開始整地，透過焚燒雜木、雜草與灰燼作為天然肥料，以提升土壤肥力。\r\n泰雅族人倚靠著土地與小米為生，伴隨著小米生產過程，也衍生泰雅族的重要祭典，維繫著族群文化命脈，讓在外的遊子及不同族群的您深度認識泰雅族祭典文化。', '桃園市復興區公所', '桃園市復興區', '復興區（桃園市）=', 24.72949884, 121.3754588, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='泰雅族自約五千年前即開始在台灣活動，族群文化從狩獵演變至農耕，並逐步建立聚落。其中，小米（trakis）是泰雅族的重要主食與文化象徵，族人傳統上於每年12月開始整地，透過焚燒雜木、雜草與灰燼作為天然肥料，以提升土壤肥力。\r\n泰雅族人倚靠著土地與小米為生，伴隨著小米生產過程，也衍生泰雅族的重要祭典，維繫著族群文化命脈，讓在外的遊子及不同族群的您深度認識泰雅族祭典文化。', `organizer`='桃園市復興區公所', `address`='桃園市復興區', `location`='復興區（桃園市）=', `latitude`=24.72949884, `longitude`=121.3754588, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35026b3240c403d98b5', '2025青春美展   國立高雄大學工藝與創意設計學系114級畢業展－「熾 Blaze」', ' 熾焰淬鍊，手心留溫。\r\n《熾》以「火光、烈焰」為主軸，傳達本系各工藝媒材的共通之處：「熾焰」。金屬工藝焊接時的火花、陶瓷工藝的高溫窯燒、木作工藝使用機具切製產生的火光；甚至是無形的熾熱感：數位建模渲染時設備形成的「燃燒」的感覺。「熾」象徵四季炎熱的高雄，也代表我們對設計有著熾熱不滅的心。透過各種工藝媒材與技法，每件作品猶如一顆炙熱的火苗，體現創作的溫度。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-04-04 00:00:00', '2025-04-15 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展   國立高雄大學工藝與創意設計學系114級畢業展－「熾 Blaze」', `description`=' 熾焰淬鍊，手心留溫。\r\n《熾》以「火光、烈焰」為主軸，傳達本系各工藝媒材的共通之處：「熾焰」。金屬工藝焊接時的火花、陶瓷工藝的高溫窯燒、木作工藝使用機具切製產生的火光；甚至是無形的熾熱感：數位建模渲染時設備形成的「燃燒」的感覺。「熾」象徵四季炎熱的高雄，也代表我們對設計有著熾熱不滅的心。透過各種工藝媒材與技法，每件作品猶如一顆炙熱的火苗，體現創作的溫度。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-04-04 00:00:00', `end_date`='2025-04-15 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35026b3240c403d98b6', 'SSr Vol.53', 'SSr Vol.53\r\n日期：2025/3/1\r\n時間：開場11:00 開演11:30\r\n地點：高雄LIVE WAREHOUSE小庫\r\n演出者：\r\n\r\n木苺FRUCTOSE\r\n\r\n初恋Eternal\r\n\r\n時空Astria\r\n\r\nRuka Banana\r\n\r\n存在証明 NO FACE NO REaLiTY\r\n\r\nCANDY☆STAR\r\n\r\n紫苑アスター\r\n\r\nもりもり', '高雄流行音樂中心', '高雄市鹽埕區17鄰真愛路1號', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '預售票+600;現場票+700', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='SSr Vol.53', `description`='SSr Vol.53\r\n日期：2025/3/1\r\n時間：開場11:00 開演11:30\r\n地點：高雄LIVE WAREHOUSE小庫\r\n演出者：\r\n\r\n木苺FRUCTOSE\r\n\r\n初恋Eternal\r\n\r\n時空Astria\r\n\r\nRuka Banana\r\n\r\n存在証明 NO FACE NO REaLiTY\r\n\r\nCANDY☆STAR\r\n\r\n紫苑アスター\r\n\r\nもりもり', `organizer`='高雄流行音樂中心', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='預售票+600;現場票+700', `source_url`='https://www.indievox.com/', `image_url`='[]';
