INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35126b3240c403d98b9', '2025真愛秀．藍寶石大歌廳', '✽.。.:* 2025 真愛秀．藍寶石大歌廳💎・*.:。✽\r\n🌊海音響起的彼个所在　捎來真愛的約定💝\r\n\r\n音樂經過無數人傳頌，成為經典🎵\r\n故事在時間的打磨下，匯聚成世代的記憶\r\n藍寶石大歌廳便是如此乘載了高雄一代人的青春\r\n\r\n如今高雄流行音樂中心陪你回望秀場風華\r\n也與你約定每一年動人的相聚時分\r\n\r\n💙「嘿！猶閣見面了，你嘛一切攏好，真好。」💙\r\n\r\n一年一會，看波光粼粼敢若藍寶石閃耀\r\n雙人作伙，感受來自南方的旋律與溫暖祝福\r\n四季平安，相約用飛揚神采迎接魅力四射的演出\r\n\r\n🌟四個不容錯過的理由🌟\r\n天籟實力的金曲歌者\r\n跨越時空的經典之作\r\n目不暇給的舞台特效\r\n出神入化的樂手演奏\r\n\r\n毋管四季按怎輪替，望你我港款平安\r\n海風輕拂的彼个所在\r\n閣作伙一起續寫屬於港都的故事✍️', '高雄流行音樂中心', '高雄市鹽埕區17鄰真愛路1號', '2025-05-10 00:00:00', '2025-05-11 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '輪椅身障票+1040;輪椅身障票+1440;輪椅身障票+1640;--+980;--+1680;--+2080;--+2280;--+2480;--+2880;--+3280', 'https://www.ibon.com.tw/default.aspx#gsc.tab=0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025真愛秀．藍寶石大歌廳', `description`='✽.。.:* 2025 真愛秀．藍寶石大歌廳💎・*.:。✽\r\n🌊海音響起的彼个所在　捎來真愛的約定💝\r\n\r\n音樂經過無數人傳頌，成為經典🎵\r\n故事在時間的打磨下，匯聚成世代的記憶\r\n藍寶石大歌廳便是如此乘載了高雄一代人的青春\r\n\r\n如今高雄流行音樂中心陪你回望秀場風華\r\n也與你約定每一年動人的相聚時分\r\n\r\n💙「嘿！猶閣見面了，你嘛一切攏好，真好。」💙\r\n\r\n一年一會，看波光粼粼敢若藍寶石閃耀\r\n雙人作伙，感受來自南方的旋律與溫暖祝福\r\n四季平安，相約用飛揚神采迎接魅力四射的演出\r\n\r\n🌟四個不容錯過的理由🌟\r\n天籟實力的金曲歌者\r\n跨越時空的經典之作\r\n目不暇給的舞台特效\r\n出神入化的樂手演奏\r\n\r\n毋管四季按怎輪替，望你我港款平安\r\n海風輕拂的彼个所在\r\n閣作伙一起續寫屬於港都的故事✍️', `organizer`='高雄流行音樂中心', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='輪椅身障票+1040;輪椅身障票+1440;輪椅身障票+1640;--+980;--+1680;--+2080;--+2280;--+2480;--+2880;--+3280', `source_url`='https://www.ibon.com.tw/default.aspx#gsc.tab=0', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35126b3240c403d98ba', '「動物觀察家」主題書展', '「動物觀察家」主題書展\r\n於二樓設置專區放置相關主題書籍。定期更換推薦書籍，歡迎大家借閱。\r\n▪展演時間｜114年5月1日至5月31日／開館時間\r\n▪展演書單｜台北動物園的動物鮮事、水生有毒動物、動物歷險記、中國珍稀動物、臺灣哺乳動物、中國人與動物、千姿百態的動物與昆蟲、小朋友最愛問的為什麼 :布瓜總動員 .動物篇、動物漫談、動物的生殖、草原動物、	沙漠中的動物、動物們的夜生活、極地野生動物..等書籍', '高雄市立圖書館總館', '高雄市湖內區3鄰保生路101號', '2025-05-01 00:00:00', '2025-05-31 00:00:00', '高雄市立圖書館湖內分館', 22.8955499, 120.2225563, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「動物觀察家」主題書展', `description`='「動物觀察家」主題書展\r\n於二樓設置專區放置相關主題書籍。定期更換推薦書籍，歡迎大家借閱。\r\n▪展演時間｜114年5月1日至5月31日／開館時間\r\n▪展演書單｜台北動物園的動物鮮事、水生有毒動物、動物歷險記、中國珍稀動物、臺灣哺乳動物、中國人與動物、千姿百態的動物與昆蟲、小朋友最愛問的為什麼 :布瓜總動員 .動物篇、動物漫談、動物的生殖、草原動物、	沙漠中的動物、動物們的夜生活、極地野生動物..等書籍', `organizer`='高雄市立圖書館總館', `address`='高雄市湖內區3鄰保生路101號', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='高雄市立圖書館湖內分館', `latitude`=22.8955499, `longitude`=120.2225563, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35126b3240c403d98bb', '剪紙變奏曲─張瑞頻個展', '張瑞頻，台北藝術大學畢業，美國加州大學研究所進修，後旅居加拿大、英國十餘年。國內外展覽經歷豐富，且獲獎無數。連年駐村，創作橫跨歐洲、美洲、亞洲各國。多次於歐、美、新加坡、台灣畫廊及藝術中心舉辦個展。這是第一次在家鄉-中壢舉辦個展。\r\n此次展覽，呈現其十餘年來在各國藝術駐村創作的成果，運用剪紙、拼貼和繪畫，以多媒材、豐富的色彩與光影變化，展現了具創新和實驗性的作品。展場設有互動體驗環節，讓觀眾可以親自嘗試剪紙，感受其魅力與樂趣。此展覽展現剪紙藝術從傳統到當代的變化與發展，欣賞這一古老又充滿活力的藝術形式。', '中原大學藝術中心', '桃園市中壢區中北路200號', '2025-02-17 00:00:00', '2025-03-29 00:00:00', '中原大學', 24.9574977, 121.240539, '無資料', 'https://www.facebook.com/CYCUARTCENTER', '[]') ON DUPLICATE KEY UPDATE `activity_name`='剪紙變奏曲─張瑞頻個展', `description`='張瑞頻，台北藝術大學畢業，美國加州大學研究所進修，後旅居加拿大、英國十餘年。國內外展覽經歷豐富，且獲獎無數。連年駐村，創作橫跨歐洲、美洲、亞洲各國。多次於歐、美、新加坡、台灣畫廊及藝術中心舉辦個展。這是第一次在家鄉-中壢舉辦個展。\r\n此次展覽，呈現其十餘年來在各國藝術駐村創作的成果，運用剪紙、拼貼和繪畫，以多媒材、豐富的色彩與光影變化，展現了具創新和實驗性的作品。展場設有互動體驗環節，讓觀眾可以親自嘗試剪紙，感受其魅力與樂趣。此展覽展現剪紙藝術從傳統到當代的變化與發展，欣賞這一古老又充滿活力的藝術形式。', `organizer`='中原大學藝術中心', `address`='桃園市中壢區中北路200號', `start_date`='2025-02-17 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='中原大學', `latitude`=24.9574977, `longitude`=121.240539, `ticket_price`='無資料', `source_url`='https://www.facebook.com/CYCUARTCENTER', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35126b3240c403d98bc', '針．友．趣–姚明芬聯展', '藝術家姚明芬以「亂針繪繡」展現傳統女紅的創新魅力。亂針繪繡，又名飛針繡，結合繪畫與刺繡技法，以針代替筆、以布代替紙、以絲線代替顏料，線條交織中呈現光影層次，遠觀如畫，近看亂中有序，展現立體感與豐富細節。\r\n此次展覽匯集姚老師21年的個人創作與教學成果，主題涵蓋自然景物與個人情感，透過亂針繪繡重新定義傳統刺繡，充分體現這項技法的藝術性與感染力。針線間傳達創作者對生活藝術的熱忱，邀您走進針與線交織的世界，感受這門傳統與創新交融的藝術形式之美。', '中原大學藝術中心', '桃園市中壢區中北路200號', '2025-02-17 00:00:00', '2025-03-29 00:00:00', '中原大學', 24.9574977, 121.240539, '無資料', 'https://www.facebook.com/CYCUARTCENTER', '[]') ON DUPLICATE KEY UPDATE `activity_name`='針．友．趣–姚明芬聯展', `description`='藝術家姚明芬以「亂針繪繡」展現傳統女紅的創新魅力。亂針繪繡，又名飛針繡，結合繪畫與刺繡技法，以針代替筆、以布代替紙、以絲線代替顏料，線條交織中呈現光影層次，遠觀如畫，近看亂中有序，展現立體感與豐富細節。\r\n此次展覽匯集姚老師21年的個人創作與教學成果，主題涵蓋自然景物與個人情感，透過亂針繪繡重新定義傳統刺繡，充分體現這項技法的藝術性與感染力。針線間傳達創作者對生活藝術的熱忱，邀您走進針與線交織的世界，感受這門傳統與創新交融的藝術形式之美。', `organizer`='中原大學藝術中心', `address`='桃園市中壢區中北路200號', `start_date`='2025-02-17 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='中原大學', `latitude`=24.9574977, `longitude`=121.240539, `ticket_price`='無資料', `source_url`='https://www.facebook.com/CYCUARTCENTER', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35126b3240c403d98bd', '精武圖書館-3月書展', '【與幾米再浪漫一回】 2樓文學區\r\n\r\n幾米曾在廣告公司工作十二年，後來為報紙、雜誌等各種出版品畫插畫。\r\n1995年，幾米患血癌，後病情被控制住。在家休養三年，重新開始畫插畫。\r\n\r\n圖文書於不同年齡層，皆富有感染力和引發思考的效果，尤其對青少年而言，在銜接學習生涯和未來規劃的階段，有許多迷茫和不確定感，希望透過此書展，療癒、陪伴每一位心底的少年。\r\n\r\n【呷飽EAT起做運動】 1樓歲月流金區\r\n\r\n隨著高齡化社會發展，關注身心健康的意識刻不容緩，\r\n同時為配合與財團法人台中市教育文教基金會合作的講座「調整體態-日常生活可以這樣做」，我們將於03/02（日）至03/29（六）舉辦一場與之相關的主題書展。\r\n在這次的書展中，精選了各類與體態調整、健康運動及飲食有關的書籍，\r\n旨在鼓勵大家養成良好的生活習慣，改善久坐所帶來的不適。\r\n邀請各位讀者一同來到精武圖書館1樓，透過閱讀與實踐，從今天開始改變自己的日常吧！\r\n\r\n【臺語冊．講乎咱聽】 2F閱覽區\r\n\r\n本書展以中市圖台語串聯活動【做伙】為主軸，並以台語歌謠為主題，展出台語成為可書寫的文字，以及童謠書，讓母語透過書本與文字融入日常生活。\r\n透過此書展，再次將常以口說方式傳播的台語，轉化為可圖像記憶的美好語言。\r\n\r\n書單連結：https://reurl.cc/KdYZOj', '臺中市精武圖書館', '臺中市北區精武路291之3號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市精武圖書館', 24.15863985, 120.6809521, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='精武圖書館-3月書展', `description`='【與幾米再浪漫一回】 2樓文學區\r\n\r\n幾米曾在廣告公司工作十二年，後來為報紙、雜誌等各種出版品畫插畫。\r\n1995年，幾米患血癌，後病情被控制住。在家休養三年，重新開始畫插畫。\r\n\r\n圖文書於不同年齡層，皆富有感染力和引發思考的效果，尤其對青少年而言，在銜接學習生涯和未來規劃的階段，有許多迷茫和不確定感，希望透過此書展，療癒、陪伴每一位心底的少年。\r\n\r\n【呷飽EAT起做運動】 1樓歲月流金區\r\n\r\n隨著高齡化社會發展，關注身心健康的意識刻不容緩，\r\n同時為配合與財團法人台中市教育文教基金會合作的講座「調整體態-日常生活可以這樣做」，我們將於03/02（日）至03/29（六）舉辦一場與之相關的主題書展。\r\n在這次的書展中，精選了各類與體態調整、健康運動及飲食有關的書籍，\r\n旨在鼓勵大家養成良好的生活習慣，改善久坐所帶來的不適。\r\n邀請各位讀者一同來到精武圖書館1樓，透過閱讀與實踐，從今天開始改變自己的日常吧！\r\n\r\n【臺語冊．講乎咱聽】 2F閱覽區\r\n\r\n本書展以中市圖台語串聯活動【做伙】為主軸，並以台語歌謠為主題，展出台語成為可書寫的文字，以及童謠書，讓母語透過書本與文字融入日常生活。\r\n透過此書展，再次將常以口說方式傳播的台語，轉化為可圖像記憶的美好語言。\r\n\r\n書單連結：https://reurl.cc/KdYZOj', `organizer`='臺中市精武圖書館', `address`='臺中市北區精武路291之3號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市精武圖書館', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35226b3240c403d98be', 'Gallery Talk│潮壤相接：「男人與女人的海：阿美族海洋文化對話」', '在男人與女人的海中，探索阿美族文化的脈動與延續\r\n\r\n在這場對話中，葉海地將分享她從女性視角出發，探索海洋文化中脆弱與堅韌交織的創作歷程；蔡政良則談及他如何透過文化教育與海洋保育，復甦都蘭部落的傳統與自信。兩位講者將從不同性別、文化與遷徙經驗出發，引領觀眾穿越海洋文化的多重面向，揭示海洋作為生命之源、文化脈絡與靈性載體的深層意涵。\r\n歡迎您參與這場文化與自然交織的深度對話，與我們一同感受阿美族海洋文化中流動的生命力與韌性。\r\n\r\n[注意事項] \r\n1. 本活動請線上報名，預留座位。如現場有空位，可現場候補入座。\r\n2. 本活動免費，惟入館參觀看展需入館門票，符合免票、優惠票資格者請準備相關證件驗證入場。\r\n3. 本館保留活動異動之權利，倘有異動以現場說明為主。\r\n\r\n[肖像權聲明] \r\n活動中將進行現場攝影記錄，參與本活動即同意授權承辦單位高雄市立美術館進行活動攝影，且同意高雄市立美術館將相關影像用於本館網站、社群媒體、出版品製作、研究發表等非營利之教育推廣用途，且同意本館擁有公開宣傳、傳輸前述影像等權利。\r\n', '高雄市立美術館', '高雄市鼓山區6鄰美術館路80號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '高雄市立美術館', 22.6566968, 120.2865511, '優惠票+45;全票+90', 'https://www.kmfa.gov.tw/OnlineApplyDetailC001200.aspx?Cond=6e4e00fd-76b5-4570-a5f4-8370b6dcf733', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Gallery Talk│潮壤相接：「男人與女人的海：阿美族海洋文化對話」', `description`='在男人與女人的海中，探索阿美族文化的脈動與延續\r\n\r\n在這場對話中，葉海地將分享她從女性視角出發，探索海洋文化中脆弱與堅韌交織的創作歷程；蔡政良則談及他如何透過文化教育與海洋保育，復甦都蘭部落的傳統與自信。兩位講者將從不同性別、文化與遷徙經驗出發，引領觀眾穿越海洋文化的多重面向，揭示海洋作為生命之源、文化脈絡與靈性載體的深層意涵。\r\n歡迎您參與這場文化與自然交織的深度對話，與我們一同感受阿美族海洋文化中流動的生命力與韌性。\r\n\r\n[注意事項] \r\n1. 本活動請線上報名，預留座位。如現場有空位，可現場候補入座。\r\n2. 本活動免費，惟入館參觀看展需入館門票，符合免票、優惠票資格者請準備相關證件驗證入場。\r\n3. 本館保留活動異動之權利，倘有異動以現場說明為主。\r\n\r\n[肖像權聲明] \r\n活動中將進行現場攝影記錄，參與本活動即同意授權承辦單位高雄市立美術館進行活動攝影，且同意高雄市立美術館將相關影像用於本館網站、社群媒體、出版品製作、研究發表等非營利之教育推廣用途，且同意本館擁有公開宣傳、傳輸前述影像等權利。\r\n', `organizer`='高雄市立美術館', `address`='高雄市鼓山區6鄰美術館路80號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='高雄市立美術館', `latitude`=22.6566968, `longitude`=120.2865511, `ticket_price`='優惠票+45;全票+90', `source_url`='https://www.kmfa.gov.tw/OnlineApplyDetailC001200.aspx?Cond=6e4e00fd-76b5-4570-a5f4-8370b6dcf733', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35426b3240c403d98c0', 'bulabulay．原民之耀-葫蘆講堂', '「bulabulay • 原民之耀」大展集結臺灣博物館界19座公私立博物館、3位部落族人(阿美、排灣、魯凱)、2位收藏家、1位畫家，提供共近200組件國寶、重要古物、一般古物與經典展品。期間辦理免費講座，發現深厚內涵的臺灣原住民族文化寶藏。\r\n※講題：雲之森—雲豹復育與在地保育\r\n※講者：姜博仁先生(社團法人雲豹復育研究會理事長)', '財團法人福祿文化基金會', '臺北市大安區羅斯福路4段1號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '國立臺灣大學校史館', 25.02677012, 121.5434446, '無資料', 'https://bulabulay.com/lecture', '[]') ON DUPLICATE KEY UPDATE `activity_name`='bulabulay．原民之耀-葫蘆講堂', `description`='「bulabulay • 原民之耀」大展集結臺灣博物館界19座公私立博物館、3位部落族人(阿美、排灣、魯凱)、2位收藏家、1位畫家，提供共近200組件國寶、重要古物、一般古物與經典展品。期間辦理免費講座，發現深厚內涵的臺灣原住民族文化寶藏。\r\n※講題：雲之森—雲豹復育與在地保育\r\n※講者：姜博仁先生(社團法人雲豹復育研究會理事長)', `organizer`='財團法人福祿文化基金會', `address`='臺北市大安區羅斯福路4段1號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='國立臺灣大學校史館', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='無資料', `source_url`='https://bulabulay.com/lecture', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35526b3240c403d98c1', 'bulabulay．原民之耀-葫蘆講堂：原住民給臺灣的禮物', '「bulabulay • 原民之耀」大展集結臺灣博物館界19座公私立博物館、3位部落族人(阿美、排灣、魯凱)、2位收藏家、1位畫家，提供共近200組件國寶、重要古物、一般古物與經典展品。期間辦理免費講座，發現深厚內涵的臺灣原住民族文化寶藏。\r\n※講題：原住民給臺灣的禮物\r\n※講者：孫大川先生(臺大臺灣文學研究所兼任副教授)\r\n※大綱：我們一般習慣從弱勢的角度看待原住民，其實原住民文化的豐富性，遠遠超乎你的想像，首先，以從本土化的角度，看原住民對台灣歷史、文化和政治發展的意義；其次，原住民是台灣多元文化以及民主社會品質的試金石；再其次，原住民是台灣聯結南𡷊𡷊與遼濶海洋世界的紐帶；最後，原住民和全球原住民一樣，是一種召喚，邀請我們重新釐清人與自然的關係，超越國族的框框，邁向人類更根源性的認同。', '財團法人福祿文化基金會', '臺北市大安區羅斯福路4段1號', '2025-05-17 00:00:00', '2025-05-17 00:00:00', '國立臺灣大學校史館', 25.02677012, 121.5434446, '無資料', 'https://bulabulay.com/lecture', '[]') ON DUPLICATE KEY UPDATE `activity_name`='bulabulay．原民之耀-葫蘆講堂：原住民給臺灣的禮物', `description`='「bulabulay • 原民之耀」大展集結臺灣博物館界19座公私立博物館、3位部落族人(阿美、排灣、魯凱)、2位收藏家、1位畫家，提供共近200組件國寶、重要古物、一般古物與經典展品。期間辦理免費講座，發現深厚內涵的臺灣原住民族文化寶藏。\r\n※講題：原住民給臺灣的禮物\r\n※講者：孫大川先生(臺大臺灣文學研究所兼任副教授)\r\n※大綱：我們一般習慣從弱勢的角度看待原住民，其實原住民文化的豐富性，遠遠超乎你的想像，首先，以從本土化的角度，看原住民對台灣歷史、文化和政治發展的意義；其次，原住民是台灣多元文化以及民主社會品質的試金石；再其次，原住民是台灣聯結南𡷊𡷊與遼濶海洋世界的紐帶；最後，原住民和全球原住民一樣，是一種召喚，邀請我們重新釐清人與自然的關係，超越國族的框框，邁向人類更根源性的認同。', `organizer`='財團法人福祿文化基金會', `address`='臺北市大安區羅斯福路4段1號', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='國立臺灣大學校史館', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='無資料', `source_url`='https://bulabulay.com/lecture', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35526b3240c403d98c2', 'bulabulay．原民之耀-葫蘆講堂：七腳川系原住民族地域性美感的看見', '「bulabulay • 原民之耀」大展集結臺灣博物館界19座公私立博物館、3位部落族人(阿美、排灣、魯凱)、2位收藏家、1位畫家，提供共近200組件國寶、重要古物、一般古物與經典展品。期間辦理免費講座，發現深厚內涵的臺灣原住民族文化寶藏。\r\n※講題：七腳川系原住民族地域性美感的看見\r\n※講者：王昱心女士(國立東華大學原住民族樂舞與藝術學士學位學程教授)\r\n※大綱：在浸淫原民藝術領域多年的日子裡，從貝珠製作過程中，認識了阿美族的衣飾歷史。而在東華原民院民藝所服務期間，有機會了解到Rinahem/壽豐光榮部落的女性帽飾與服飾。另在男性大羽冠的重製學習中，則看到了七腳川系整體的衣著飾品。凡此經驗均使人深切感受到地區性美感所演繹出來的跨族群在地風潮，織作工藝與材料、以及配件交易的選擇等等，清楚透露出相同裡的相異，而其中色彩的轉換與重製，更代表著美感經驗的延伸。', '財團法人福祿文化基金會', '臺北市大安區羅斯福路4段1號', '2025-06-14 00:00:00', '2025-06-14 00:00:00', '國立臺灣大學校史館', 25.02677012, 121.5434446, '無資料', 'https://bulabulay.com/lecture', '[]') ON DUPLICATE KEY UPDATE `activity_name`='bulabulay．原民之耀-葫蘆講堂：七腳川系原住民族地域性美感的看見', `description`='「bulabulay • 原民之耀」大展集結臺灣博物館界19座公私立博物館、3位部落族人(阿美、排灣、魯凱)、2位收藏家、1位畫家，提供共近200組件國寶、重要古物、一般古物與經典展品。期間辦理免費講座，發現深厚內涵的臺灣原住民族文化寶藏。\r\n※講題：七腳川系原住民族地域性美感的看見\r\n※講者：王昱心女士(國立東華大學原住民族樂舞與藝術學士學位學程教授)\r\n※大綱：在浸淫原民藝術領域多年的日子裡，從貝珠製作過程中，認識了阿美族的衣飾歷史。而在東華原民院民藝所服務期間，有機會了解到Rinahem/壽豐光榮部落的女性帽飾與服飾。另在男性大羽冠的重製學習中，則看到了七腳川系整體的衣著飾品。凡此經驗均使人深切感受到地區性美感所演繹出來的跨族群在地風潮，織作工藝與材料、以及配件交易的選擇等等，清楚透露出相同裡的相異，而其中色彩的轉換與重製，更代表著美感經驗的延伸。', `organizer`='財團法人福祿文化基金會', `address`='臺北市大安區羅斯福路4段1號', `start_date`='2025-06-14 00:00:00', `end_date`='2025-06-14 00:00:00', `location`='國立臺灣大學校史館', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='無資料', `source_url`='https://bulabulay.com/lecture', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35526b3240c403d98c3', 'bulabulay．原民之耀-葫蘆講堂：文化—文物與文物之外', '「bulabulay • 原民之耀」大展集結臺灣博物館界19座公私立博物館、3位部落族人(阿美、排灣、魯凱)、2位收藏家、1位畫家，提供共近200組件國寶、重要古物、一般古物與經典展品。期間辦理免費講座，發現深厚內涵的臺灣原住民族文化寶藏。\r\n※講題：文化—文物與文物之外\r\n※講者：謝世忠先生(國立臺灣大學人類學系兼任教授)\r\n※大綱：大展本場接近尾聲，咸信大家都已經目睹過精彩，也體驗了驚豔。這批文物給予視覺最高美感，從而讓人見識到文化的具象實體。問題是，具象實體文物所透露出的文化是什麼? 我們能否具體而微侃侃而談? 又，它們與整體面向的各相關族群部落文化，是否能夠劃上等號? 事實上，一是單品獨項，微觀細絲，另一則萬物納入，宏觀包容。', '財團法人福祿文化基金會', '臺北市大安區羅斯福路4段1號', '2025-07-12 00:00:00', '2025-07-12 00:00:00', '國立臺灣大學校史館', 25.02677012, 121.5434446, '無資料', 'https://bulabulay.com/lecture', '[]') ON DUPLICATE KEY UPDATE `activity_name`='bulabulay．原民之耀-葫蘆講堂：文化—文物與文物之外', `description`='「bulabulay • 原民之耀」大展集結臺灣博物館界19座公私立博物館、3位部落族人(阿美、排灣、魯凱)、2位收藏家、1位畫家，提供共近200組件國寶、重要古物、一般古物與經典展品。期間辦理免費講座，發現深厚內涵的臺灣原住民族文化寶藏。\r\n※講題：文化—文物與文物之外\r\n※講者：謝世忠先生(國立臺灣大學人類學系兼任教授)\r\n※大綱：大展本場接近尾聲，咸信大家都已經目睹過精彩，也體驗了驚豔。這批文物給予視覺最高美感，從而讓人見識到文化的具象實體。問題是，具象實體文物所透露出的文化是什麼? 我們能否具體而微侃侃而談? 又，它們與整體面向的各相關族群部落文化，是否能夠劃上等號? 事實上，一是單品獨項，微觀細絲，另一則萬物納入，宏觀包容。', `organizer`='財團法人福祿文化基金會', `address`='臺北市大安區羅斯福路4段1號', `start_date`='2025-07-12 00:00:00', `end_date`='2025-07-12 00:00:00', `location`='國立臺灣大學校史館', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='無資料', `source_url`='https://bulabulay.com/lecture', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35526b3240c403d98c4', '無資料', '為培養音樂素養，特邀任職於台南應用科技大學音樂學系魏美惠老師進行鋼琴音樂講座，以及任職於國立清華大學音樂系的徐子儀進行管樂講座，帶來一場場精彩的音樂薰陶之旅。', '臺南市立佳里國民中學', '臺南市佳里區', '佳里區（臺南市）=', 23.1669941, 120.178593, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='為培養音樂素養，特邀任職於台南應用科技大學音樂學系魏美惠老師進行鋼琴音樂講座，以及任職於國立清華大學音樂系的徐子儀進行管樂講座，帶來一場場精彩的音樂薰陶之旅。', `organizer`='臺南市立佳里國民中學', `address`='臺南市佳里區', `location`='佳里區（臺南市）=', `latitude`=23.1669941, `longitude`=120.178593, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35526b3240c403d98c5', '博物館文化沙龍- 倫敦老城區經典獵奇景點', '邀請到英國藍牌導覽員Craig小高老師，分享入門倫敦老城區經典之處，裡面穿插都市小巷，在地人才知道的小秘境！', '桃園市立大溪木藝生態博物館', '桃園市大溪區普濟路25、27號', '2025-02-26 00:00:00', '2025-02-26 00:00:00', '桃園市立大溪木藝生態博物館-歡迎廳', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='博物館文化沙龍- 倫敦老城區經典獵奇景點', `description`='邀請到英國藍牌導覽員Craig小高老師，分享入門倫敦老城區經典之處，裡面穿插都市小巷，在地人才知道的小秘境！', `organizer`='桃園市立大溪木藝生態博物館', `address`='桃園市大溪區普濟路25、27號', `start_date`='2025-02-26 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='桃園市立大溪木藝生態博物館-歡迎廳', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35626b3240c403d98c6', '114年善化區草莓季產業文化展演活動', '為推廣善化在地優質的草莓，並讓民眾體驗採草莓之樂趣，本次規劃主題/周邊系列活動，廣邀各地民眾前來共襄盛舉，以趣味和美味、開發新創意及點子，將「114年善化區草莓季產業文化活動」系列活動的特色透過創意行銷方式推廣全台。現場有DIY草莓拔絲糖葫蘆，亦會設置草莓周邊製品展示區，活動當天不僅可以和YOYO家族-草莓姐姐一起同樂，欣賞勁歌熱舞表演，還有夢幻泡泡活動，期吸引大小朋友一同來善化度過歡樂時光。', '臺南市善化區公所', '臺南市善化區', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '善化區（臺南市）=', 23.14031072, 120.2988274, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年善化區草莓季產業文化展演活動', `description`='為推廣善化在地優質的草莓，並讓民眾體驗採草莓之樂趣，本次規劃主題/周邊系列活動，廣邀各地民眾前來共襄盛舉，以趣味和美味、開發新創意及點子，將「114年善化區草莓季產業文化活動」系列活動的特色透過創意行銷方式推廣全台。現場有DIY草莓拔絲糖葫蘆，亦會設置草莓周邊製品展示區，活動當天不僅可以和YOYO家族-草莓姐姐一起同樂，欣賞勁歌熱舞表演，還有夢幻泡泡活動，期吸引大小朋友一同來善化度過歡樂時光。', `organizer`='臺南市善化區公所', `address`='臺南市善化區', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='善化區（臺南市）=', `latitude`=23.14031072, `longitude`=120.2988274, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35626b3240c403d98c7', '3月小太陽映像館-妖果小學 水果奶奶的大秘密', '本片是由台灣播出超過23年\r\n最長壽的兒童節目《水果冰淇淋》🍦\r\n所加深發展出來的動畫電影\r\n故事中的角色設定，融入眾多文化傳說\r\n包含邵族、布農族、阿美族、魯凱族\r\n以及台灣燈猴的原型...\r\n\r\n故事開始於一段幽靜常青的小路\r\n正專心看手上地圖的白髮奶奶\r\n被眼前的白鹿雕像咬掉地圖\r\n窸窸窣窣的聲音將她引向妖怪世界……。\r\n\r\n一場奇幻冒險的巨浪即將開始🌊\r\n歡迎來精武圖書館一起觀影🎞', '臺中市精武圖書館', '臺中市北區精武路291之3號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '臺中市精武圖書館', 24.15863985, 120.6809521, '無資料', 'https://www.facebook.com/share/p/15kC1bVZtp/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月小太陽映像館-妖果小學 水果奶奶的大秘密', `description`='本片是由台灣播出超過23年\r\n最長壽的兒童節目《水果冰淇淋》🍦\r\n所加深發展出來的動畫電影\r\n故事中的角色設定，融入眾多文化傳說\r\n包含邵族、布農族、阿美族、魯凱族\r\n以及台灣燈猴的原型...\r\n\r\n故事開始於一段幽靜常青的小路\r\n正專心看手上地圖的白髮奶奶\r\n被眼前的白鹿雕像咬掉地圖\r\n窸窸窣窣的聲音將她引向妖怪世界……。\r\n\r\n一場奇幻冒險的巨浪即將開始🌊\r\n歡迎來精武圖書館一起觀影🎞', `organizer`='臺中市精武圖書館', `address`='臺中市北區精武路291之3號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='臺中市精武圖書館', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/15kC1bVZtp/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35726b3240c403d98c8', '2025青春美展 【框金又包銀】臺藝大古蹟系110級畢業展', '國立臺灣藝術大學古蹟藝術修護學系成立超過二十年，多年來致力傳授傳統建築裝飾的技法知識予年輕學子。【框金又包銀】展出多件揉合傳統工藝和吉祥寓意的作品，涵蓋古蹟系木雕、彩繪、剪黏以及交趾陶等核心術科課程，是一眾「師仔」希望向大眾分享的四年學藝成果，以期回應民眾對文化資產教育的關切。', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-05-16 00:00:00', '2025-05-27 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展 【框金又包銀】臺藝大古蹟系110級畢業展', `description`='國立臺灣藝術大學古蹟藝術修護學系成立超過二十年，多年來致力傳授傳統建築裝飾的技法知識予年輕學子。【框金又包銀】展出多件揉合傳統工藝和吉祥寓意的作品，涵蓋古蹟系木雕、彩繪、剪黏以及交趾陶等核心術科課程，是一眾「師仔」希望向大眾分享的四年學藝成果，以期回應民眾對文化資產教育的關切。', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-16 00:00:00', `end_date`='2025-05-27 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35826b3240c403d98cd', '萬花 Retenir｜暮拉多元藝術空間｜台南展覽', '「就好像一道泉源存在於一個封口的瓶子裡，它的聲波卻持續在這個瓶子的瓶身上造成回響，讓瓶裡充滿了它們的聲響。或者更進一步說，就好像打獵的號角聲，以其回音在四處迴盪，讓最小、最纖細的葉子和苔蘚都會在日常的動作中發抖，進而改變了整個森林，使森林鼓脹至極限，成為一個共振、響亮的世界…… 。」—— 尤金．閔可夫斯基(Eugene Minkowski)，《邁向宇宙論》。\r\n如何認識藝術家所形構出的世界，倘若從日常身邊的物件、從最平凡的生活觀察開始，我們似乎可以發現經驗所累積的知識基本材料，是來自於與「物質」的接觸。然而，物質引動情感與回應生命經驗，同時透過想像的拉升，直接且自然地使物質意象邁向精神層次，使其具備了詩意與文學性。於是，人們對於物質有了一個理解的培育養成與意義賦予的進程。', '暮拉多元藝術空間', '臺南市中西區國華街三段15號', '2025-02-25 00:00:00', '2025-04-27 00:00:00', '暮拉多元藝術空間', 22.99594458, 120.192874, '無資料', 'https://themoolahart.com/retentir/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='萬花 Retenir｜暮拉多元藝術空間｜台南展覽', `description`='「就好像一道泉源存在於一個封口的瓶子裡，它的聲波卻持續在這個瓶子的瓶身上造成回響，讓瓶裡充滿了它們的聲響。或者更進一步說，就好像打獵的號角聲，以其回音在四處迴盪，讓最小、最纖細的葉子和苔蘚都會在日常的動作中發抖，進而改變了整個森林，使森林鼓脹至極限，成為一個共振、響亮的世界…… 。」—— 尤金．閔可夫斯基(Eugene Minkowski)，《邁向宇宙論》。\r\n如何認識藝術家所形構出的世界，倘若從日常身邊的物件、從最平凡的生活觀察開始，我們似乎可以發現經驗所累積的知識基本材料，是來自於與「物質」的接觸。然而，物質引動情感與回應生命經驗，同時透過想像的拉升，直接且自然地使物質意象邁向精神層次，使其具備了詩意與文學性。於是，人們對於物質有了一個理解的培育養成與意義賦予的進程。', `organizer`='暮拉多元藝術空間', `address`='臺南市中西區國華街三段15號', `start_date`='2025-02-25 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='暮拉多元藝術空間', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='https://themoolahart.com/retentir/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35826b3240c403d98ce', '無資料', '明華園星字戲劇團於2002年正式在明華園的故鄉臺南成軍，現由明華園第三代陳子權擔任團長。不僅沿襲歌仔戲外台戲的演出，同時加入更多新式表演風格及型態，求新求變，讓歌仔戲藝術更為現代觀眾所接受，年平均演出場次可達百場，曾遠征韓國釜山、中國大陸、美國紐約等地。本次將演出〈濟公傳奇之接引怒〉劇目。', '台南市柳營慈靈宮', '臺南市柳營區', '柳營區（臺南市）=', 23.26887001, 120.3549205, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='明華園星字戲劇團於2002年正式在明華園的故鄉臺南成軍，現由明華園第三代陳子權擔任團長。不僅沿襲歌仔戲外台戲的演出，同時加入更多新式表演風格及型態，求新求變，讓歌仔戲藝術更為現代觀眾所接受，年平均演出場次可達百場，曾遠征韓國釜山、中國大陸、美國紐約等地。本次將演出〈濟公傳奇之接引怒〉劇目。', `organizer`='台南市柳營慈靈宮', `address`='臺南市柳營區', `location`='柳營區（臺南市）=', `latitude`=23.26887001, `longitude`=120.3549205, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35826b3240c403d98cf', '《SDGs進行市》永續環境主題繪本書展', '我們的生活環境正在發生哪些變化?\r\n長期推動的 SDGs 究竟是什麼?\r\n󠀠󠀠全球氣候得變遷，為了讓未來能更加友善環境，我們持續努力，一點一滴邁向永續發展，守護地球為目標，這次高雄市立圖書館國際繪本中心策展融合「SDGs聯合國永續發展」核心指標裡的4項訴求「消除飢餓」、「永續城鄉」、「陸域生態」、「氣候行動」，透過繪本閱讀，邀請大小讀者一同探索更美好的城市與環境守護。', '高雄市立圖書館總館', '高雄市前鎮區21鄰新光路61號', '2025-02-18 00:00:00', '2025-05-18 00:00:00', '高雄市立圖書館總館', 22.6115529, 120.3024491, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《SDGs進行市》永續環境主題繪本書展', `description`='我們的生活環境正在發生哪些變化?\r\n長期推動的 SDGs 究竟是什麼?\r\n󠀠󠀠全球氣候得變遷，為了讓未來能更加友善環境，我們持續努力，一點一滴邁向永續發展，守護地球為目標，這次高雄市立圖書館國際繪本中心策展融合「SDGs聯合國永續發展」核心指標裡的4項訴求「消除飢餓」、「永續城鄉」、「陸域生態」、「氣候行動」，透過繪本閱讀，邀請大小讀者一同探索更美好的城市與環境守護。', `organizer`='高雄市立圖書館總館', `address`='高雄市前鎮區21鄰新光路61號', `start_date`='2025-02-18 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='高雄市立圖書館總館', `latitude`=22.6115529, `longitude`=120.3024491, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35826b3240c403d98d0', '《 SDGs進行市 》用繪本談SDGs', '此次高市圖國際繪本中心特別邀請南加州師範學院的劉淑雯教授前來與親子共讀的家長們介紹如何用繪本帶著孩子一同閱讀SDGs聯合國永續發展目標，以閱讀拓展更好的城市。\r\n講師：南加州師範學院教授-劉淑雯。\r\n報名對象：6-12歲親子家庭＊限30組親子(每組限1大1小)。', '高雄市立圖書館總館', '高雄市前鎮區21鄰新光路61號', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '高雄市立圖書館總館', 22.6115529, 120.3024491, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《 SDGs進行市 》用繪本談SDGs', `description`='此次高市圖國際繪本中心特別邀請南加州師範學院的劉淑雯教授前來與親子共讀的家長們介紹如何用繪本帶著孩子一同閱讀SDGs聯合國永續發展目標，以閱讀拓展更好的城市。\r\n講師：南加州師範學院教授-劉淑雯。\r\n報名對象：6-12歲親子家庭＊限30組親子(每組限1大1小)。', `organizer`='高雄市立圖書館總館', `address`='高雄市前鎮區21鄰新光路61號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='高雄市立圖書館總館', `latitude`=22.6115529, `longitude`=120.3024491, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35926b3240c403d98d1', '夢與復原 - 長笛與鋼琴的對話', '雅卓藝術多年來為國內外專業長笛演奏家打造藝文推廣平台，致力於提升長笛音樂藝術的普及與發展。作曲家郭嘉琳博士為加拿大歸國的優秀作曲家，近年來致力於台加兩國文化交流與推廣。郭老師的作品細膩而充滿人性溫暖。對音樂會發起人的郭老師來說，也是充滿愛與感恩的旅程。\r\n\r\n\r\n\r\n\r\n\r\n【製作人/作曲家】郭嘉琳（Cathy Kuo）\r\n\r\n\r\n\r\n成長於台灣的台加作曲家郭嘉琳，有著特殊的跨界經歷。古典鋼琴啟蒙於孫愛光老師，就讀古亭國小音樂班期間，師事吳漪曼教授。大學畢業於輔仁大學社會系，後至美國波士頓大學攻讀傳播碩士，主修電視製作。返台後在影視傳播界工作, 製作片頭配樂（東森電視）。\r\n\r\n\r\n至三十歲，開始學習作曲。隨金希文教授學習兩年後，獲得加州大學爾灣分校(Univ. of California, Irvine)音樂研究所的全額獎學金，師事Christopher Dobrian，畢業作品《青春舞曲鋼琴協奏曲》於加州爾灣首演。回台後任北市大與台藝大音樂系兼任講師。2013年獲加拿大英屬哥倫比亞大學(UBC)博士班全額獎學金，師事作曲家Stephan Chatman教授，2018年獲得作曲博士學位(D.M.A)。留加期間，管弦作品也連續兩年在溫哥華交響樂團舉辦的作曲比賽獲選。2018年的大型管弦作品Urban Suite（《異鄉人組曲》）獲選在加拿大溫尼伯新音樂節發表，並於當年四月在台北國家音樂廳, 由孫愛光博士指揮陽光台北交響樂團舉行台灣首演。\r\n\r\n\r\n目前為國立臺灣藝術大學音樂系與國立臺北教育大學通識中心的兼任助理教授。曾受邀陽光台北交響樂團、溫哥華跨文化樂團(Vancouver Inter-Cultural Orchestra)、閃亮木管五重奏、溫哥華Elysian Trio, Paragon Trio與Meeks Duo (米克鋼琴雙人組) 等樂團委託於台北國家演奏廳、誠品演藝廳、中山堂等發表新作。近年保持參與加拿大音樂活動，如: 2023 Sonic Boom, 2022 Blueridge Chamber Fest, 2019 Canada Music Day。郭嘉琳目前加入ACL亞洲作曲家聯盟、加拿大作曲家聯盟(Canadian Music Centre)與加拿大女性作曲家協會(Association of Canadian Women Composers)。\r\n\r\n\r\n\r\n\r\n\r\n【演出者】\r\n\r\n\r\n\r\n長笛/潘宗賢\r\n美國紐約市立大學長笛演奏碩士，師事法國長笛大師Marcel Moyse的嫡傳弟子—前匹茲堡交響樂團長笛首席 Bernard Z. Goldberg，在台期間受教於戴念平、陳幸政、賴妍妙等教授。旅美時期曾多次獲得獎學金，並應邀於CUNY電視台中演出，此外，潘宗賢也擔任音樂月刊駐美特派員。返台後，除了經常擔任各級考試及比賽評審外，更廣受各方的邀約演出，包括財團法人許常惠文化藝術基金會、長榮交響樂團、法鼓文化、台北聖樂團等等。此外，潘宗賢也經常以獨奏或重奏的形式，受邀於各大國際藝術節中演出， 目前擔任於真理大學音樂應用學系兼任講師, 並任教於多所中小學音樂班，教授長笛、室內樂及長笛合奏等課程。\r\n\r\n \r\n\r\n鋼琴/游適伃\r\n臺灣鋼琴演奏家，國立臺北藝術大學博士。幼時即展現優異演奏天分，考取桃園西門國小音樂班榜首，保送國立臺灣師範大學音樂學系。後於德國國立弗萊堡音樂院（Staatliche Hochschule für Musik Freiburg）深造，師從俄籍名家Vitali Berzon，以最優等成績取得藝術家文憑。後以榜首考取臺北藝術大學攻讀博士畢業，師事王美齡教授。\r\n\r\n豎笛/邱詩平\r\n美國西北大學單簧管演奏碩士。旅美期間曾獲得Leni FeBland Foundation, Eckstein Fund, Dean’s Talent Awards等多項獎學金。2002年贏得美國俄亥俄州交響樂與室內樂協會比賽第二名，隔年應該協會邀請於年度研討會演出。2003年入選為美國音樂榮譽學術協會永久會員。曾多次於國家演奏廳等地舉辦個人獨奏會，並受邀擔任獨奏家於台北、嘉義、美國等地演出。現任教於淡江中學及光仁小學音樂班，並擔任P³鋼琴三重奏團長。\r\n\r\n\r\n長笛/卓彥秀\r\n長笛演奏家、編曲家、作曲家、講師、策展人與長笛藝術推手之全方位音樂家- 卓彥秀，2012年自巴黎高等師範音樂院（École Normale  de Musique de Paris）學成返國後，以長/短笛演奏、管弦樂團、管樂團、室內樂、長笛推廣、長笛出版等活躍於台灣音樂圈。 卓彥秀的作品公開出版著作有：《牧神的午後前奏曲》、《莫札特長笛協奏曲集》、《大象與蒼蠅》、《莫札特長笛協奏曲集2》、《ANDERSEN給長笛的二十四首大練習曲作品第15號》、《李斯特-魔鬼圓舞曲第一號：給長笛、單簧管與鋼琴》..等等。現為 台北市立交響樂團TSO管樂團團員、 潘神室內樂團員、雅卓藝術總監、 臺灣長笛嘉年華總監。\r\n\r\n \r\n\r\n\r\n\r\n【演出曲目】\r\n\r\n1. K. Wakiyama : A Musical Triptych for Resilience for Flute and Piano\r\n脇山幹士：《災難、復原、希望的三部曲》給長笛與鋼琴\r\n\r\n2. Cathy Kuo : L’arc en ciel(Rainbow)for Flute , Clarinet and Piano\r\n郭嘉琳：《彩虹》給長笛、單簧管與鋼琴\r\n\r\n3. Cathy Kuo : Reveries for Flute and Piano\r\n郭嘉琳：《給長笛與鋼琴的夢幻絮語》\r\n\r\n4. Mel Bonis : Sonata for Flute and Piano\r\n梅蘭妮·波尼斯：給長笛與鋼琴的奏鳴曲\r\n\r\n5. Stephen Chatman : Sneaky\r\n查特曼：鬼祟\r\n\r\n6. Stephen Chatman : Katherine\r\n查特曼：凱瑟琳\r\n\r\n7. Stephen Chatman : Spring Celebration\r\n查特曼：春之慶典\r\n\r\n8. Stephen Chou : Saturday\r\n周彥宇 ：星期六\r\n\r\n9. Yang Chen :Butterfly Dancefor Two Flutes , Clarinet and Piano (arr. Yen Hsiu Cho)\r\n陳揚：《蝶舞》給兩支長笛、單簧管與鋼琴（卓彥秀改編）\r\n\r\n10. Cathy Kuo : The Wizard, The Fairy for Flute, Clarinet and Piano\r\n郭嘉琳：《巫師與仙子》給長笛、單簧管與鋼琴\r\n\r\n*主辦單位保有節目異動之權利', '雅卓有限公司', '臺北市大安區羅斯福路4段1號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '國立臺灣大學', 25.02677012, 121.5434446, '/+380', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='夢與復原 - 長笛與鋼琴的對話', `description`='雅卓藝術多年來為國內外專業長笛演奏家打造藝文推廣平台，致力於提升長笛音樂藝術的普及與發展。作曲家郭嘉琳博士為加拿大歸國的優秀作曲家，近年來致力於台加兩國文化交流與推廣。郭老師的作品細膩而充滿人性溫暖。對音樂會發起人的郭老師來說，也是充滿愛與感恩的旅程。\r\n\r\n\r\n\r\n\r\n\r\n【製作人/作曲家】郭嘉琳（Cathy Kuo）\r\n\r\n\r\n\r\n成長於台灣的台加作曲家郭嘉琳，有著特殊的跨界經歷。古典鋼琴啟蒙於孫愛光老師，就讀古亭國小音樂班期間，師事吳漪曼教授。大學畢業於輔仁大學社會系，後至美國波士頓大學攻讀傳播碩士，主修電視製作。返台後在影視傳播界工作, 製作片頭配樂（東森電視）。\r\n\r\n\r\n至三十歲，開始學習作曲。隨金希文教授學習兩年後，獲得加州大學爾灣分校(Univ. of California, Irvine)音樂研究所的全額獎學金，師事Christopher Dobrian，畢業作品《青春舞曲鋼琴協奏曲》於加州爾灣首演。回台後任北市大與台藝大音樂系兼任講師。2013年獲加拿大英屬哥倫比亞大學(UBC)博士班全額獎學金，師事作曲家Stephan Chatman教授，2018年獲得作曲博士學位(D.M.A)。留加期間，管弦作品也連續兩年在溫哥華交響樂團舉辦的作曲比賽獲選。2018年的大型管弦作品Urban Suite（《異鄉人組曲》）獲選在加拿大溫尼伯新音樂節發表，並於當年四月在台北國家音樂廳, 由孫愛光博士指揮陽光台北交響樂團舉行台灣首演。\r\n\r\n\r\n目前為國立臺灣藝術大學音樂系與國立臺北教育大學通識中心的兼任助理教授。曾受邀陽光台北交響樂團、溫哥華跨文化樂團(Vancouver Inter-Cultural Orchestra)、閃亮木管五重奏、溫哥華Elysian Trio, Paragon Trio與Meeks Duo (米克鋼琴雙人組) 等樂團委託於台北國家演奏廳、誠品演藝廳、中山堂等發表新作。近年保持參與加拿大音樂活動，如: 2023 Sonic Boom, 2022 Blueridge Chamber Fest, 2019 Canada Music Day。郭嘉琳目前加入ACL亞洲作曲家聯盟、加拿大作曲家聯盟(Canadian Music Centre)與加拿大女性作曲家協會(Association of Canadian Women Composers)。\r\n\r\n\r\n\r\n\r\n\r\n【演出者】\r\n\r\n\r\n\r\n長笛/潘宗賢\r\n美國紐約市立大學長笛演奏碩士，師事法國長笛大師Marcel Moyse的嫡傳弟子—前匹茲堡交響樂團長笛首席 Bernard Z. Goldberg，在台期間受教於戴念平、陳幸政、賴妍妙等教授。旅美時期曾多次獲得獎學金，並應邀於CUNY電視台中演出，此外，潘宗賢也擔任音樂月刊駐美特派員。返台後，除了經常擔任各級考試及比賽評審外，更廣受各方的邀約演出，包括財團法人許常惠文化藝術基金會、長榮交響樂團、法鼓文化、台北聖樂團等等。此外，潘宗賢也經常以獨奏或重奏的形式，受邀於各大國際藝術節中演出， 目前擔任於真理大學音樂應用學系兼任講師, 並任教於多所中小學音樂班，教授長笛、室內樂及長笛合奏等課程。\r\n\r\n \r\n\r\n鋼琴/游適伃\r\n臺灣鋼琴演奏家，國立臺北藝術大學博士。幼時即展現優異演奏天分，考取桃園西門國小音樂班榜首，保送國立臺灣師範大學音樂學系。後於德國國立弗萊堡音樂院（Staatliche Hochschule für Musik Freiburg）深造，師從俄籍名家Vitali Berzon，以最優等成績取得藝術家文憑。後以榜首考取臺北藝術大學攻讀博士畢業，師事王美齡教授。\r\n\r\n豎笛/邱詩平\r\n美國西北大學單簧管演奏碩士。旅美期間曾獲得Leni FeBland Foundation, Eckstein Fund, Dean’s Talent Awards等多項獎學金。2002年贏得美國俄亥俄州交響樂與室內樂協會比賽第二名，隔年應該協會邀請於年度研討會演出。2003年入選為美國音樂榮譽學術協會永久會員。曾多次於國家演奏廳等地舉辦個人獨奏會，並受邀擔任獨奏家於台北、嘉義、美國等地演出。現任教於淡江中學及光仁小學音樂班，並擔任P³鋼琴三重奏團長。\r\n\r\n\r\n長笛/卓彥秀\r\n長笛演奏家、編曲家、作曲家、講師、策展人與長笛藝術推手之全方位音樂家- 卓彥秀，2012年自巴黎高等師範音樂院（École Normale  de Musique de Paris）學成返國後，以長/短笛演奏、管弦樂團、管樂團、室內樂、長笛推廣、長笛出版等活躍於台灣音樂圈。 卓彥秀的作品公開出版著作有：《牧神的午後前奏曲》、《莫札特長笛協奏曲集》、《大象與蒼蠅》、《莫札特長笛協奏曲集2》、《ANDERSEN給長笛的二十四首大練習曲作品第15號》、《李斯特-魔鬼圓舞曲第一號：給長笛、單簧管與鋼琴》..等等。現為 台北市立交響樂團TSO管樂團團員、 潘神室內樂團員、雅卓藝術總監、 臺灣長笛嘉年華總監。\r\n\r\n \r\n\r\n\r\n\r\n【演出曲目】\r\n\r\n1. K. Wakiyama : A Musical Triptych for Resilience for Flute and Piano\r\n脇山幹士：《災難、復原、希望的三部曲》給長笛與鋼琴\r\n\r\n2. Cathy Kuo : L’arc en ciel(Rainbow)for Flute , Clarinet and Piano\r\n郭嘉琳：《彩虹》給長笛、單簧管與鋼琴\r\n\r\n3. Cathy Kuo : Reveries for Flute and Piano\r\n郭嘉琳：《給長笛與鋼琴的夢幻絮語》\r\n\r\n4. Mel Bonis : Sonata for Flute and Piano\r\n梅蘭妮·波尼斯：給長笛與鋼琴的奏鳴曲\r\n\r\n5. Stephen Chatman : Sneaky\r\n查特曼：鬼祟\r\n\r\n6. Stephen Chatman : Katherine\r\n查特曼：凱瑟琳\r\n\r\n7. Stephen Chatman : Spring Celebration\r\n查特曼：春之慶典\r\n\r\n8. Stephen Chou : Saturday\r\n周彥宇 ：星期六\r\n\r\n9. Yang Chen :Butterfly Dancefor Two Flutes , Clarinet and Piano (arr. Yen Hsiu Cho)\r\n陳揚：《蝶舞》給兩支長笛、單簧管與鋼琴（卓彥秀改編）\r\n\r\n10. Cathy Kuo : The Wizard, The Fairy for Flute, Clarinet and Piano\r\n郭嘉琳：《巫師與仙子》給長笛、單簧管與鋼琴\r\n\r\n*主辦單位保有節目異動之權利', `organizer`='雅卓有限公司', `address`='臺北市大安區羅斯福路4段1號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='國立臺灣大學', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='/+380', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35926b3240c403d98d2', '《SDGs進行市》繪本分享工作坊', '藉由SDGs繪客室主題，此次高雄市立圖書館國際繪本中心特別邀請繪本作家林柏廷老師，曾著作《一個像海的地方》、《好想回家》等環境生態的繪本。\r\n曾獲得第一屆和第四屆豐子愷兒童圖畫書獎入選，以及2020 OpenBook好書獎最佳童書、入圍第30屆金鼎獎最佳圖畫書獎，更是永續發展教育圖書評鑑入選書單，豐富的獎項經驗與參與生態保育等議題，這次老師將帶著親子共讀，探討環境永續，啟發對大自然的愛護與尊重，一起打造更美好的未來！\r\n講師：繪本作家-林柏廷。\r\n報名對象：6-12歲親子家庭＊限20組親子(每組限1大1小)。', '高雄市立圖書館總館', '高雄市前鎮區21鄰新光路61號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '高雄市立圖書館總館', 22.6115529, 120.3024491, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《SDGs進行市》繪本分享工作坊', `description`='藉由SDGs繪客室主題，此次高雄市立圖書館國際繪本中心特別邀請繪本作家林柏廷老師，曾著作《一個像海的地方》、《好想回家》等環境生態的繪本。\r\n曾獲得第一屆和第四屆豐子愷兒童圖畫書獎入選，以及2020 OpenBook好書獎最佳童書、入圍第30屆金鼎獎最佳圖畫書獎，更是永續發展教育圖書評鑑入選書單，豐富的獎項經驗與參與生態保育等議題，這次老師將帶著親子共讀，探討環境永續，啟發對大自然的愛護與尊重，一起打造更美好的未來！\r\n講師：繪本作家-林柏廷。\r\n報名對象：6-12歲親子家庭＊限20組親子(每組限1大1小)。', `organizer`='高雄市立圖書館總館', `address`='高雄市前鎮區21鄰新光路61號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='高雄市立圖書館總館', `latitude`=22.6115529, `longitude`=120.3024491, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
