INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35926b3240c403d98d9', '無資料', '活動內容：\r\n2月02日／花語擴香石\r\n2月15日／馬賽克拼貼\r\n2月16日／春暖花開竹編瓶\r\n2月23日／春暖花開竹編瓶\r\n報名方式將於活動前在粉專另行公告。\r\n活動洽詢：049-2645530。', '南投縣竹山鎮公所', '南投縣竹山鎮公所路120號', '南投縣竹山鎮立親子館', 23.69805518, 120.7100797, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='活動內容：\r\n2月02日／花語擴香石\r\n2月15日／馬賽克拼貼\r\n2月16日／春暖花開竹編瓶\r\n2月23日／春暖花開竹編瓶\r\n報名方式將於活動前在粉專另行公告。\r\n活動洽詢：049-2645530。', `organizer`='南投縣竹山鎮公所', `address`='南投縣竹山鎮公所路120號', `location`='南投縣竹山鎮立親子館', `latitude`=23.69805518, `longitude`=120.7100797, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35926b3240c403d98da', '萬榮鄉太魯閣族20周年特展', '來自於 T rukuTruwan的民族，約三、四百年前來自南投縣\r\n境越過中央山脈奇萊山，克服自然環境的險峻，沿著立霧溪山谷向東遷移；經歷歷史政權的更迭、曾徘徊在自我認同的迷霧\r\n中太魯閣族人發起正名運動，經過族人長期的努力，終於在\r\n2004 年 1 月 14 日獲得官方正名，成為全國第 12 個\r\n原住民族；透過此特展了解太魯閣族正名歷史脈絡及過程， 啟發太魯閣族人對於於「我們」的故事。', '花蓮縣萬榮鄉公所', '花蓮縣萬榮鄉', '2025-01-01 00:00:00', '2025-04-30 00:00:00', '萬榮鄉（花蓮縣）=', 23.72772629, 121.3189531, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='萬榮鄉太魯閣族20周年特展', `description`='來自於 T rukuTruwan的民族，約三、四百年前來自南投縣\r\n境越過中央山脈奇萊山，克服自然環境的險峻，沿著立霧溪山谷向東遷移；經歷歷史政權的更迭、曾徘徊在自我認同的迷霧\r\n中太魯閣族人發起正名運動，經過族人長期的努力，終於在\r\n2004 年 1 月 14 日獲得官方正名，成為全國第 12 個\r\n原住民族；透過此特展了解太魯閣族正名歷史脈絡及過程， 啟發太魯閣族人對於於「我們」的故事。', `organizer`='花蓮縣萬榮鄉公所', `address`='花蓮縣萬榮鄉', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='萬榮鄉（花蓮縣）=', `latitude`=23.72772629, `longitude`=121.3189531, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35926b3240c403d98db', '草山百年風華聯展', '為使民眾親近陽明山上的藝文館舍，促進對陽明山歷史的了解，由臺北市政府工務局公園路燈工程管理處花卉試驗中心(花季承辦單位暨辛亥光復樓管理)與陽明山國家公園管理處陽明書屋、閻錫山故居、中國文化大學華岡博物館、國立臺灣圖書館中山樓管理所和林語堂故居等單位合作，共同舉辦「草山百年風華─陽明山館舍串聯活動」。\r\n', '臺北市政府工務局公園路燈工程管理處', '臺北市北投區', '2025-01-24 00:00:00', '2025-03-16 00:00:00', '北投區（臺北市）=', 25.1480682, 121.5177992, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='草山百年風華聯展', `description`='為使民眾親近陽明山上的藝文館舍，促進對陽明山歷史的了解，由臺北市政府工務局公園路燈工程管理處花卉試驗中心(花季承辦單位暨辛亥光復樓管理)與陽明山國家公園管理處陽明書屋、閻錫山故居、中國文化大學華岡博物館、國立臺灣圖書館中山樓管理所和林語堂故居等單位合作，共同舉辦「草山百年風華─陽明山館舍串聯活動」。\r\n', `organizer`='臺北市政府工務局公園路燈工程管理處', `address`='臺北市北投區', `start_date`='2025-01-24 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='北投區（臺北市）=', `latitude`=25.1480682, `longitude`=121.5177992, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35926b3240c403d98dc', '音樂會 — 五吉樂團：春暖花開音樂會 ', '【音樂會 — 五吉樂團：春暖花開音樂會】\r\n每年「春暖花開」「百花爭艷」之際都會邀請【五吉樂團】來鹿谷益品美術館精彩演出，讓大家感受聆聽薩克斯風與歌聲、舞群在山巒中帶來的美妙旋律，使午後的休閒充滿音樂的悸動與大自然和諧的歡樂時刻!在歡樂氣氛中揭開春遊的序幕。\r\n今年「春暖花開音樂會」特別挑選校園民歌、西洋歌曲、台語流行金曲、薩克斯風演奏等，與我們一同迎接春暖花開的美好時光。\r\n「張三的歌」、「情字這條路」、「戀曲1990」等民歌紀錄著年少歲月，國台語好歌，首首都值得我們细细品味、慢慢咀嚼，熱愛音樂、喜歡哼哼唱唱的街頭藝人「五吉樂團」，他們與益品美術館除邀請大家一起歡樂外，更準備最火的舞蹈「科目三」、「APT」，為2025年春暖花開開啟最歡愉的時刻。\r\n表演者：五吉樂團\r\n周安平/吉他彈唱、廖經綸/薩克斯風、向淑娟/Key Board\r\n舞蹈表演/戴貴花、向淑娟\r\n時間：3/21(五) 14:00-15:30\r\n報名方式\r\n線上：https://forms.gle/LA4fhG3fYCz6dGnK6\r\n𝑳𝑰𝑵𝑬：https://lin.ee/a6udYIj\r\n電話：049-2752203', '益品美術館', '南投縣鹿谷鄉中正路二段211巷19號', '2025-03-21 00:00:00', '2025-03-21 00:00:00', '益品美術館', 23.73776029, 120.7815065, '入館費+100', 'https://www.facebook.com/epmuseum', '[]') ON DUPLICATE KEY UPDATE `activity_name`='音樂會 — 五吉樂團：春暖花開音樂會 ', `description`='【音樂會 — 五吉樂團：春暖花開音樂會】\r\n每年「春暖花開」「百花爭艷」之際都會邀請【五吉樂團】來鹿谷益品美術館精彩演出，讓大家感受聆聽薩克斯風與歌聲、舞群在山巒中帶來的美妙旋律，使午後的休閒充滿音樂的悸動與大自然和諧的歡樂時刻!在歡樂氣氛中揭開春遊的序幕。\r\n今年「春暖花開音樂會」特別挑選校園民歌、西洋歌曲、台語流行金曲、薩克斯風演奏等，與我們一同迎接春暖花開的美好時光。\r\n「張三的歌」、「情字這條路」、「戀曲1990」等民歌紀錄著年少歲月，國台語好歌，首首都值得我們细细品味、慢慢咀嚼，熱愛音樂、喜歡哼哼唱唱的街頭藝人「五吉樂團」，他們與益品美術館除邀請大家一起歡樂外，更準備最火的舞蹈「科目三」、「APT」，為2025年春暖花開開啟最歡愉的時刻。\r\n表演者：五吉樂團\r\n周安平/吉他彈唱、廖經綸/薩克斯風、向淑娟/Key Board\r\n舞蹈表演/戴貴花、向淑娟\r\n時間：3/21(五) 14:00-15:30\r\n報名方式\r\n線上：https://forms.gle/LA4fhG3fYCz6dGnK6\r\n𝑳𝑰𝑵𝑬：https://lin.ee/a6udYIj\r\n電話：049-2752203', `organizer`='益品美術館', `address`='南投縣鹿谷鄉中正路二段211巷19號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='益品美術館', `latitude`=23.73776029, `longitude`=120.7815065, `ticket_price`='入館費+100', `source_url`='https://www.facebook.com/epmuseum', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35926b3240c403d98de', '「不老~精彩人生」-主題書展', '本館希望藉由辦理之『主題書展』，使到館民眾進一步認識館藏資源。入選的書具相當可讀性「是好書、也是好看的書」而我們期許，所展示的主題書籍及相關延伸作品，都能使讀者徜徉在書海中，進一步領略閱讀之美、享受閱讀樂趣，亦能提升視野。', '高雄市立圖書館總館', '高雄市茄萣區24鄰濱海路四段31巷1號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館茄萣分館', 22.9068919, 120.1824779, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「不老~精彩人生」-主題書展', `description`='本館希望藉由辦理之『主題書展』，使到館民眾進一步認識館藏資源。入選的書具相當可讀性「是好書、也是好看的書」而我們期許，所展示的主題書籍及相關延伸作品，都能使讀者徜徉在書海中，進一步領略閱讀之美、享受閱讀樂趣，亦能提升視野。', `organizer`='高雄市立圖書館總館', `address`='高雄市茄萣區24鄰濱海路四段31巷1號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館茄萣分館', `latitude`=22.9068919, `longitude`=120.1824779, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
