INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35a26b3240c403d98ec', '【百行百業台語sa攏有講座】人權開講——自由ná像空氣', '【百行百業台語sa攏有講座】人權開講——自由ná像空氣\r\n\r\n費用：免費參加，請先報名，實名制。\r\n報名網址 https://forms.gle/zS7643MV27HsWWF29\r\n台語使用比例:100%\r\n預計認列點數:2\r\n#配合文化部培育台語家庭計畫集點 ＃文化部國家語言整體發展方案支持\r\n主講人：林仁惠\r\nBat擔任台灣人公共事務會（FAPA）辦公室主任、環境法律人協會秘書長\r\n現任：國際特赦組織台灣分會理事長、四二四教育基金會執行長\r\n\r\n大綱：\r\nEcho自1994年開始投入人權ê工作，做到tsit-má已經滿30年，伊beh tuì家己ê成長、教育背景開始，分享按怎行入人權運動tsit條路。\r\n● 戒嚴下ê成長\r\n● 人權交陪走天下\r\n● 人權親像空氣：無空氣kám活ē落--去?\r\n● 台灣人權團體lóng teh創啥?\r\n● 日常ê人權課題\r\n\r\n\r\n▎活動時間：2025/3/12(拜三) 19:30 ~ 21:30\r\n▎名額：網路報名50人\r\n▎地點：濟南教會 (台北市中山南路3號，主日學教室)\r\n台北火車頭kap捷運「善導寺」站附近。\r\n\r\n\r\n\r\n洽詢電話：02-23112199\r\n聯絡信箱：bongpo1996@gmail.com\r\n\r\n主辦單位：李江却台語文教基金會\r\n協辦單位：台灣基督長老教會濟南教會\r\n補助單位：文化部\r\n--------------------------------\r\n【百行百業台語sa攏有講座】人權開講——自由ná像空氣\r\n\r\n台語家庭集點計劃：上「國家語言數位資訊網」，進入台語家庭會員平台，登錄成做預備台語家庭，每一个人lóng ài先申請會員口座(身分證抑是健保卡電子檔)，其中一位綁定厝內人，選擇「台語學習/文化家庭」，開始報名活動kah課程，集點換台語獎勵金、抽獎機會。\r\n台語家庭會員平台常見問題 https://tg.moc.gov.tw/ptgl-user-service/faq-login.html\r\n--------------------------------\r\n歡迎捐款贊助　#李江却台語文教基金會　\r\n（捐款可抵稅，匯款後請通知02-23112199）\r\n線上捐款(定期定額)\r\nhttps://donate.newebpay.com/Period/akhioh/lkk\r\n線上捐款(單筆)\r\nhttps://donate.newebpay.com/akhioh/lkk\r\n郵政劃撥：19021486\r\n戶名：財團法人李江却台語文教基金會\r\n電匯：123-20-050514-2 華南銀行士林分行活儲\r\n戶名：財團法人李江却台語文教基金會\r\n#百行百業台語sa攏有講座 #李江却台語文教基金會 #台灣基督長老教會濟南教會 #林仁惠 #文化部', '李江却台語文教基金會', '臺北市中山區', '2025-03-12 00:00:00', '2025-03-12 00:00:00', '中山區（臺北市）=', 25.06969917, 121.5381597, '無資料', 'https://forms.gle/zS7643MV27HsWWF29', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【百行百業台語sa攏有講座】人權開講——自由ná像空氣', `description`='【百行百業台語sa攏有講座】人權開講——自由ná像空氣\r\n\r\n費用：免費參加，請先報名，實名制。\r\n報名網址 https://forms.gle/zS7643MV27HsWWF29\r\n台語使用比例:100%\r\n預計認列點數:2\r\n#配合文化部培育台語家庭計畫集點 ＃文化部國家語言整體發展方案支持\r\n主講人：林仁惠\r\nBat擔任台灣人公共事務會（FAPA）辦公室主任、環境法律人協會秘書長\r\n現任：國際特赦組織台灣分會理事長、四二四教育基金會執行長\r\n\r\n大綱：\r\nEcho自1994年開始投入人權ê工作，做到tsit-má已經滿30年，伊beh tuì家己ê成長、教育背景開始，分享按怎行入人權運動tsit條路。\r\n● 戒嚴下ê成長\r\n● 人權交陪走天下\r\n● 人權親像空氣：無空氣kám活ē落--去?\r\n● 台灣人權團體lóng teh創啥?\r\n● 日常ê人權課題\r\n\r\n\r\n▎活動時間：2025/3/12(拜三) 19:30 ~ 21:30\r\n▎名額：網路報名50人\r\n▎地點：濟南教會 (台北市中山南路3號，主日學教室)\r\n台北火車頭kap捷運「善導寺」站附近。\r\n\r\n\r\n\r\n洽詢電話：02-23112199\r\n聯絡信箱：bongpo1996@gmail.com\r\n\r\n主辦單位：李江却台語文教基金會\r\n協辦單位：台灣基督長老教會濟南教會\r\n補助單位：文化部\r\n--------------------------------\r\n【百行百業台語sa攏有講座】人權開講——自由ná像空氣\r\n\r\n台語家庭集點計劃：上「國家語言數位資訊網」，進入台語家庭會員平台，登錄成做預備台語家庭，每一个人lóng ài先申請會員口座(身分證抑是健保卡電子檔)，其中一位綁定厝內人，選擇「台語學習/文化家庭」，開始報名活動kah課程，集點換台語獎勵金、抽獎機會。\r\n台語家庭會員平台常見問題 https://tg.moc.gov.tw/ptgl-user-service/faq-login.html\r\n--------------------------------\r\n歡迎捐款贊助　#李江却台語文教基金會　\r\n（捐款可抵稅，匯款後請通知02-23112199）\r\n線上捐款(定期定額)\r\nhttps://donate.newebpay.com/Period/akhioh/lkk\r\n線上捐款(單筆)\r\nhttps://donate.newebpay.com/akhioh/lkk\r\n郵政劃撥：19021486\r\n戶名：財團法人李江却台語文教基金會\r\n電匯：123-20-050514-2 華南銀行士林分行活儲\r\n戶名：財團法人李江却台語文教基金會\r\n#百行百業台語sa攏有講座 #李江却台語文教基金會 #台灣基督長老教會濟南教會 #林仁惠 #文化部', `organizer`='李江却台語文教基金會', `address`='臺北市中山區', `start_date`='2025-03-12 00:00:00', `end_date`='2025-03-12 00:00:00', `location`='中山區（臺北市）=', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='https://forms.gle/zS7643MV27HsWWF29', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35a26b3240c403d98ed', '茄萣分館小蜻蜓兒童讀書會', '1.為有效運用圖書館既有資源，期分館能深入社區推動閱讀，提升社區閱讀風氣。\r\n2.透過同儕學習的模式，讓兒童體會閱讀的樂趣。\r\n導讀繪本書單：\r\n3/09神奇漢藥房\r\n3/16修一修.老房子\r\n3/23長腳的房子\r\n3/30會呼吸的土團屋', '高雄市立圖書館總館', '高雄市茄萣區24鄰濱海路四段31巷1號', '2025-03-09 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館茄萣分館', 22.9068919, 120.1824779, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='茄萣分館小蜻蜓兒童讀書會', `description`='1.為有效運用圖書館既有資源，期分館能深入社區推動閱讀，提升社區閱讀風氣。\r\n2.透過同儕學習的模式，讓兒童體會閱讀的樂趣。\r\n導讀繪本書單：\r\n3/09神奇漢藥房\r\n3/16修一修.老房子\r\n3/23長腳的房子\r\n3/30會呼吸的土團屋', `organizer`='高雄市立圖書館總館', `address`='高雄市茄萣區24鄰濱海路四段31巷1號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館茄萣分館', `latitude`=22.9068919, `longitude`=120.1824779, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35a26b3240c403d98ee', '舞蹈學系第 26 屆畢業巡迴公演《爍光》', '學生編創作品，演出長度約為 105 分鐘，透過本次展演驗收大學四年之舞蹈專業訓練成果。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-04 00:00:00', '2025-03-04 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '/+300;/+500;/+800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='舞蹈學系第 26 屆畢業巡迴公演《爍光》', `description`='學生編創作品，演出長度約為 105 分鐘，透過本次展演驗收大學四年之舞蹈專業訓練成果。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-04 00:00:00', `end_date`='2025-03-04 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='/+300;/+500;/+800', `source_url`='https://www.opentix.life/', `image_url`='[]';
