INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35a26b3240c403d98f2', '《綠野仙蹤》', '挑戰製作膾炙人口的百老匯經典作品《Wizard of Oz 綠野仙蹤》，一行人經歷一場場冒險和重重挑戰前往奧茲帝國，希望達成自己的心願。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-28 00:00:00', '2025-03-30 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '/+600;/+900;/+1200;/+1600;/+2000;/+2500;/+3000;/+3500', 'https://tixfun.com/UTK0101_', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《綠野仙蹤》', `description`='挑戰製作膾炙人口的百老匯經典作品《Wizard of Oz 綠野仙蹤》，一行人經歷一場場冒險和重重挑戰前往奧茲帝國，希望達成自己的心願。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='/+600;/+900;/+1200;/+1600;/+2000;/+2500;/+3000;/+3500', `source_url`='https://tixfun.com/UTK0101_', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35a26b3240c403d98f3', '《樂舞飛揚》', '《樂舞飛揚》是一場獨特的音樂與舞蹈的聯合演出，將為觀眾呈現一場充滿動感與藝術魅力的視聽盛宴。在這場節目中，樂團與舞蹈演員將巧妙交織，音樂與舞蹈如同翅膀般展翅高飛，讓每一個音符和每一個舞步都充滿生命的力量。\r\n本場演出以音樂和舞蹈為兩大主軸，精彩的樂團演奏與激情四溢的舞蹈表演將穿插進行，呈現出絕妙的視聽協奏。樂團將演奏多樣化的曲目，從經典的國樂作品，到動感十足的現代音樂。而舞蹈演員則會隨著音樂的節奏，無論是古典舞、現代舞還是民族舞，將每一個舞步都演繹得淋漓盡致，創造出動感與靜謐美學的完美融合。', '台北絲竹樂團', '臺北市信義區市府路1號', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '臺北市政府', 25.03062083, 121.5716697, '/+1500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《樂舞飛揚》', `description`='《樂舞飛揚》是一場獨特的音樂與舞蹈的聯合演出，將為觀眾呈現一場充滿動感與藝術魅力的視聽盛宴。在這場節目中，樂團與舞蹈演員將巧妙交織，音樂與舞蹈如同翅膀般展翅高飛，讓每一個音符和每一個舞步都充滿生命的力量。\r\n本場演出以音樂和舞蹈為兩大主軸，精彩的樂團演奏與激情四溢的舞蹈表演將穿插進行，呈現出絕妙的視聽協奏。樂團將演奏多樣化的曲目，從經典的國樂作品，到動感十足的現代音樂。而舞蹈演員則會隨著音樂的節奏，無論是古典舞、現代舞還是民族舞，將每一個舞步都演繹得淋漓盡致，創造出動感與靜謐美學的完美融合。', `organizer`='台北絲竹樂團', `address`='臺北市信義區市府路1號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='臺北市政府', `latitude`=25.03062083, `longitude`=121.5716697, `ticket_price`='/+1500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35a26b3240c403d98f4', '《親愛的彼得先生》', '故事總是發生在準備踏入婚姻那一刻…… 熱愛寫作的計畫控葉揚（張稜 飾）與個性樂天、著迷運動的彼得（王為 飾）準備結婚。愛情長跑14年的他們，原以為婚姻是甜蜜生活的開始，殊不知婚後卻成了彼此最可怕的照妖鏡。\r\n彼得的樂天婚後竟成無腦過動大直男，葉揚婚前是才華洋的文藝作家，一進入婚姻卻演變為崩潰怨婦，他們兩人從買房、結婚、蜜月到生子，生命中太多的關卡要彼此突破、生活中太多的平衡要不斷拿捏得與失，\r\n然而，面對婚姻中接連發生的種種危機，他們究竟會選擇躺平放棄？還是用愛化險為夷？\r\n 獻給所有在親密關係中的妳和你。', '果陀劇場', '臺北市信義區市府路1號', '2025-03-14 00:00:00', '2025-03-16 00:00:00', '臺北市政府', 25.03062083, 121.5716697, '/+800;/+1000;/+1500;/+2000', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《親愛的彼得先生》', `description`='故事總是發生在準備踏入婚姻那一刻…… 熱愛寫作的計畫控葉揚（張稜 飾）與個性樂天、著迷運動的彼得（王為 飾）準備結婚。愛情長跑14年的他們，原以為婚姻是甜蜜生活的開始，殊不知婚後卻成了彼此最可怕的照妖鏡。\r\n彼得的樂天婚後竟成無腦過動大直男，葉揚婚前是才華洋的文藝作家，一進入婚姻卻演變為崩潰怨婦，他們兩人從買房、結婚、蜜月到生子，生命中太多的關卡要彼此突破、生活中太多的平衡要不斷拿捏得與失，\r\n然而，面對婚姻中接連發生的種種危機，他們究竟會選擇躺平放棄？還是用愛化險為夷？\r\n 獻給所有在親密關係中的妳和你。', `organizer`='果陀劇場', `address`='臺北市信義區市府路1號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺北市政府', `latitude`=25.03062083, `longitude`=121.5716697, `ticket_price`='/+800;/+1000;/+1500;/+2000', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35a26b3240c403d98f5', '《『哈特魔界歷險』音樂劇》', '『哈特魔界歷險』故事敘述哈特、安潔、馬克、露比四位好朋友通過黑夜隧道進入魔界，為受困在凡間的女巫尊者艾瑟琳尋找五顆魔法石的故事。全劇情節緊湊，毫無冷場，歌曲支支動聽，舞蹈設計絕妙，採用虛擬實境背景畫面，首創以沈浸式的體驗觀賞音樂劇。全劇描述友情的珍貴，團結一心的重要，是一部適合全家一起觀賞的絕妙好戲。', '哈特音樂劇坊', '臺北市信義區市府路1號', '2025-03-22 00:00:00', '2025-03-23 00:00:00', '臺北市政府', 25.03062083, 121.5716697, '/+480;/+580;/+680;/+880;/+1080;/+1280;/+1480', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《『哈特魔界歷險』音樂劇》', `description`='『哈特魔界歷險』故事敘述哈特、安潔、馬克、露比四位好朋友通過黑夜隧道進入魔界，為受困在凡間的女巫尊者艾瑟琳尋找五顆魔法石的故事。全劇情節緊湊，毫無冷場，歌曲支支動聽，舞蹈設計絕妙，採用虛擬實境背景畫面，首創以沈浸式的體驗觀賞音樂劇。全劇描述友情的珍貴，團結一心的重要，是一部適合全家一起觀賞的絕妙好戲。', `organizer`='哈特音樂劇坊', `address`='臺北市信義區市府路1號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='臺北市政府', `latitude`=25.03062083, `longitude`=121.5716697, `ticket_price`='/+480;/+580;/+680;/+880;/+1080;/+1280;/+1480', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8e35a26b3240c403d98f6', '《2025雙舞影舞團年度展演【雙舞大地】》', '大地之舞，生生不息。\r\n山野間甦醒，小河邊蕩漾。\r\n2025邀您一同感受大地的生命力與民間舞蹈的無限魅力，悠遊於山川大地，飛舞在部落民間。\r\n2025年雙雙舞集.雙舞影舞團展演', '雙舞影舞團', '臺北市信義區市府路1號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '臺北市政府', 25.03062083, 121.5716697, '/+400;/+600;/+800;/+1000', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025雙舞影舞團年度展演【雙舞大地】》', `description`='大地之舞，生生不息。\r\n山野間甦醒，小河邊蕩漾。\r\n2025邀您一同感受大地的生命力與民間舞蹈的無限魅力，悠遊於山川大地，飛舞在部落民間。\r\n2025年雙雙舞集.雙舞影舞團展演', `organizer`='雙舞影舞團', `address`='臺北市信義區市府路1號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺北市政府', `latitude`=25.03062083, `longitude`=121.5716697, `ticket_price`='/+400;/+600;/+800;/+1000', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('5b3dd544aaa378d7ca9a2e9a', '科博館《古代人說故事》南屯山仔腳遺址出土的鐵刀首亮相!', '    想要了解東海岸舊石器時代八仙洞，新石器時代的卑南、麒麟文化及中部大坌坑、牛罵頭、大馬璘、營埔及番仔園文化嗎?科博館更新常設展區，推出《古代人說故事》，展覽內容生動活潑，並以動畫影像剪輯及多媒體互動方式呈現，除了認識歷史課本寫的考古學是什麼外，更能讓您親身體驗臺灣古代人的生活方式!\r\n\r\n    目前中部地區是臺灣考古學研究的重心之一，近二十年來考古工作者在各地獲得豐碩的挖掘成果，因此科博館決定依據最新考古發掘資料，更新該常設展區，除了展示臺中安和遺址發現栽種的稻米、母與子、戴鯊魚牙玉飾的青年及南屯山仔腳出土完整的鐵刀， 此外還有民間蒐藏家蔡坤玉先生提供一件澎湖海溝帶人工鋸痕的鹿角，結合張鈞翔博士澎湖原人的研究，證明19至45萬年前就有獵人到臺灣。歡迎民眾踴躍參觀!', '國立自然科學博物館', '臺中市40453 臺中市北區館前路一號', '2025-02-23 00:00:00', '2025-02-23 00:00:00', '人類文化廳二樓', 24.157234, 120.66606, '全票100元，半票70元。', 'http://www.nmns.edu.tw/ch/visit/price.htm', '[]') ON DUPLICATE KEY UPDATE `activity_name`='科博館《古代人說故事》南屯山仔腳遺址出土的鐵刀首亮相!', `description`='    想要了解東海岸舊石器時代八仙洞，新石器時代的卑南、麒麟文化及中部大坌坑、牛罵頭、大馬璘、營埔及番仔園文化嗎?科博館更新常設展區，推出《古代人說故事》，展覽內容生動活潑，並以動畫影像剪輯及多媒體互動方式呈現，除了認識歷史課本寫的考古學是什麼外，更能讓您親身體驗臺灣古代人的生活方式!\r\n\r\n    目前中部地區是臺灣考古學研究的重心之一，近二十年來考古工作者在各地獲得豐碩的挖掘成果，因此科博館決定依據最新考古發掘資料，更新該常設展區，除了展示臺中安和遺址發現栽種的稻米、母與子、戴鯊魚牙玉飾的青年及南屯山仔腳出土完整的鐵刀， 此外還有民間蒐藏家蔡坤玉先生提供一件澎湖海溝帶人工鋸痕的鹿角，結合張鈞翔博士澎湖原人的研究，證明19至45萬年前就有獵人到臺灣。歡迎民眾踴躍參觀!', `organizer`='國立自然科學博物館', `address`='臺中市40453 臺中市北區館前路一號', `start_date`='2025-02-23 00:00:00', `end_date`='2025-02-23 00:00:00', `location`='人類文化廳二樓', `latitude`=24.157234, `longitude`=120.66606, `ticket_price`='全票100元，半票70元。', `source_url`='http://www.nmns.edu.tw/ch/visit/price.htm', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('5cd25532aaa3f054c2cc6bad', '魔幻琺瑯/七宝烧體驗課程', '琺瑯工藝/Enamel Process\r\n\r\n琺瑯器即金屬胎琺瑯器，是一種集金屬製作與琺瑯釉料加工處理為一體的複合性工藝製品。它既具備金屬貴重、堅固的特點，又具備琺瑯釉料晶瑩、光滑及適用於裝飾的特點。\r\n\r\n依據金屬胎琺瑯器在金屬加工工藝和琺瑯釉料具體處理方法上的不同，一般可將金屬胎琺瑯器分為畫琺瑯器、掐絲琺瑯器，透明琺瑯器，錘胎琺瑯器，鏨胎琺瑯器等幾個品種。\r\n\r\n築好用〝玩藝〞來表達藝術的可親近性，所以用〝玩〞樂的創意態度來親近〝藝〞術，將人文藝術融入生活。\r\n邀請您加築好玩藝Line好友LINE ID：@dto7895b ～連結網址  https://line.me/R/ti/p/%40dto7895b 可用Line主動私訊築好聯絡相關事宜。\r\n\r\n 陶藝、金屬工藝、琺瑯工藝、羊毛氈手工藝、織染拼布工藝、複合媒材工藝、多媒體數位視覺藝術，台南好玩旅遊新選項 歡迎蒞臨台南旅人『3人』以上預約專班課程，及企業團體學校社團預約活動課程，可設計專屬主題課程，課程作品可依您需求設計。\r\n\r\n課程資訊→ \r\n https://www.facebook.com/pg/juhauwanyi/events/\r\n課程規劃以熟練工藝工法為目標，會有單日體驗跟期班課程設計！', '築好玩藝', '臺南市西門路一段６８９巷５９號', '2025-02-23 00:00:00', '2025-02-23 00:00:00', '藍晒圖文創園區', 22.986726, 120.196627, '1000↑', 'https://www.facebook.com/pg/juhauwanyi/events/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='魔幻琺瑯/七宝烧體驗課程', `description`='琺瑯工藝/Enamel Process\r\n\r\n琺瑯器即金屬胎琺瑯器，是一種集金屬製作與琺瑯釉料加工處理為一體的複合性工藝製品。它既具備金屬貴重、堅固的特點，又具備琺瑯釉料晶瑩、光滑及適用於裝飾的特點。\r\n\r\n依據金屬胎琺瑯器在金屬加工工藝和琺瑯釉料具體處理方法上的不同，一般可將金屬胎琺瑯器分為畫琺瑯器、掐絲琺瑯器，透明琺瑯器，錘胎琺瑯器，鏨胎琺瑯器等幾個品種。\r\n\r\n築好用〝玩藝〞來表達藝術的可親近性，所以用〝玩〞樂的創意態度來親近〝藝〞術，將人文藝術融入生活。\r\n邀請您加築好玩藝Line好友LINE ID：@dto7895b ～連結網址  https://line.me/R/ti/p/%40dto7895b 可用Line主動私訊築好聯絡相關事宜。\r\n\r\n 陶藝、金屬工藝、琺瑯工藝、羊毛氈手工藝、織染拼布工藝、複合媒材工藝、多媒體數位視覺藝術，台南好玩旅遊新選項 歡迎蒞臨台南旅人『3人』以上預約專班課程，及企業團體學校社團預約活動課程，可設計專屬主題課程，課程作品可依您需求設計。\r\n\r\n課程資訊→ \r\n https://www.facebook.com/pg/juhauwanyi/events/\r\n課程規劃以熟練工藝工法為目標，會有單日體驗跟期班課程設計！', `organizer`='築好玩藝', `address`='臺南市西門路一段６８９巷５９號', `start_date`='2025-02-23 00:00:00', `end_date`='2025-02-23 00:00:00', `location`='藍晒圖文創園區', `latitude`=22.986726, `longitude`=120.196627, `ticket_price`='1000↑', `source_url`='https://www.facebook.com/pg/juhauwanyi/events/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('63ef217c31be352145f9ff2b', 'platform A 第二波創作者募集', '＼Open Call／藝術家們～platform A 第二波徵件來了！！\r\n\r\n為了持續替藏家開發多樣的藝術作品風格，我們要開始第二波徵件啦～\r\n\r\n徵件主題：平面作品，媒材不限\r\n申請方式：至 platform A 官網下方「創作者專區>合作方式」投件\r\nhttps://www.platform-a.art/creators\r\n\r\nplatform A 籌備上線以來，一直希望能打造出「創作友善」的藝術電商。我們致力與創作者建立友善、對等的合作關係，也在各種層面支持創作者。\r\n\r\n我們不收取上架費，協助解決作品倉儲、裱框配送等各種瑣事。更重要的是願意提供合作創作者們更好的分潤條件，就是希望創作者們能專心創作！\r\n\r\nplatform A 會持續透過串聯各領域的資源，陪伴平台上的創作者走得更遠，讓創作這樣美好的歷程能得到更多關注、被更多人看見。\r\n\r\n歡迎分享資訊給身旁堅持創作的朋友們，我們期待大家的作品。\r\n', '無資料', '臺北市platform A 網站', '2023-02-17 00:00:00', '2033-02-17 00:00:00', 'platform A', 0, 0, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='platform A 第二波創作者募集', `description`='＼Open Call／藝術家們～platform A 第二波徵件來了！！\r\n\r\n為了持續替藏家開發多樣的藝術作品風格，我們要開始第二波徵件啦～\r\n\r\n徵件主題：平面作品，媒材不限\r\n申請方式：至 platform A 官網下方「創作者專區>合作方式」投件\r\nhttps://www.platform-a.art/creators\r\n\r\nplatform A 籌備上線以來，一直希望能打造出「創作友善」的藝術電商。我們致力與創作者建立友善、對等的合作關係，也在各種層面支持創作者。\r\n\r\n我們不收取上架費，協助解決作品倉儲、裱框配送等各種瑣事。更重要的是願意提供合作創作者們更好的分潤條件，就是希望創作者們能專心創作！\r\n\r\nplatform A 會持續透過串聯各領域的資源，陪伴平台上的創作者走得更遠，讓創作這樣美好的歷程能得到更多關注、被更多人看見。\r\n\r\n歡迎分享資訊給身旁堅持創作的朋友們，我們期待大家的作品。\r\n', `organizer`='無資料', `address`='臺北市platform A 網站', `start_date`='2023-02-17 00:00:00', `end_date`='2033-02-17 00:00:00', `location`='platform A', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('65299f9d73f77c62e4370999', '亞太樂器常設展', '臺灣，鑲嵌於太平洋島鍊上的亞洲之心。在時間的淬煉下，各族群的歷史記憶在這片土地上積累出音樂文化的結晶。\r\n本常設展將以臺灣及亞洲各國特色樂器，為您揭開亞太音樂文化的神祕面紗，太平洋上的各地風情將匯聚至此，音樂文化的豐麗瑰寶將呈獻予您！', '國立傳統藝術中心', '宜蘭縣五結鄉24鄰五濱路二段201號', '2026-01-01 00:00:00', '2026-07-01 00:00:00', '國立傳統藝術中心宜蘭園區', 24.68887343, 121.8058342, '門票--敬老票+75;門票--縣民票+100;門票--優待票+120;門票--普通票+150', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='亞太樂器常設展', `description`='臺灣，鑲嵌於太平洋島鍊上的亞洲之心。在時間的淬煉下，各族群的歷史記憶在這片土地上積累出音樂文化的結晶。\r\n本常設展將以臺灣及亞洲各國特色樂器，為您揭開亞太音樂文化的神祕面紗，太平洋上的各地風情將匯聚至此，音樂文化的豐麗瑰寶將呈獻予您！', `organizer`='國立傳統藝術中心', `address`='宜蘭縣五結鄉24鄰五濱路二段201號', `start_date`='2026-01-01 00:00:00', `end_date`='2026-07-01 00:00:00', `location`='國立傳統藝術中心宜蘭園區', `latitude`=24.68887343, `longitude`=121.8058342, `ticket_price`='門票--敬老票+75;門票--縣民票+100;門票--優待票+120;門票--普通票+150', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('65eaa9c931bef923aa07d72e', '科博館《奇幻自然》常設展', '國立自然科學博物館迎來生命科學廳的華麗轉身，全新常設展《奇幻自然》即日起開幕，展區規劃5大主題，由科博館內近20名研究人員共同策劃，深入淺出呈現自然界的規則與奧祕。踏進展場首先映入眼簾是一件逾400歲的巨大臺灣雲杉標本，觀眾可在體驗區用嗅覺、觸覺感受它的氣味及紋理，還有身長近4公尺，可手動操作的機械魷魚，吸睛又酷炫。\r\n\r\n《奇幻自然》常設展區位於生命科學廳地下1樓，展區面積253坪，從規劃評估、設計提案凝聚20名共同策展人、知名御匠設計公司及其合作團隊心血，歷經3年多溝通琢磨，才將它的前身《數與形》改頭換面。\r\n\r\n《奇幻自然》包含5單元：〈哇自然！嗨科學〉、〈圓不圓：蛋科學〉、〈動一動：生物力學〉、〈追呀追：計算與行為〉、〈說故事：探索自然，發現科學〉，細緻介紹自然界的多樣性、形態、功能、行為和科學探究，觀眾可盡情探索琳瑯滿目的科學故事。\r\n\r\n博物館常設展一般會展出10年至20年，拜科技所賜，如今學界每隔幾年就可能「發現新物種」或「建立新理論」，因此展示櫃特別設計成「前開式」，方便未來依據學術發現與時俱進、即時更新展品或標本，也能配合講座或導覽需求與觀眾互動。\r\n\r\n國立自然科學博物館生命科學廳1988年完工，由首任館長漢寶德邀請英籍設計師James Gardner設計、英國Beck & Politzer公司製作，以大自然的奧祕為主題，展示遠古生物到現代人類的精彩演化，深受大眾歡迎。當時《數與形》就有多種趣味互動裝置，搭配簡單易懂、延伸性數科概念，為無數人打開自然科學視野。\r\n', '國立自然科學博物館', '臺中市北區館前路1號', '2024-01-19 00:00:00', '2034-12-31 00:00:00', '國立自然科學博物館', 24.15863985, 120.6809521, '憑恐龍卡或展示場門票即可參觀，票價參考：https://www.nmns.edu.tw/ch/visit/ticket/', 'https://iticket.nmns.edu.tw/iticket/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='科博館《奇幻自然》常設展', `description`='國立自然科學博物館迎來生命科學廳的華麗轉身，全新常設展《奇幻自然》即日起開幕，展區規劃5大主題，由科博館內近20名研究人員共同策劃，深入淺出呈現自然界的規則與奧祕。踏進展場首先映入眼簾是一件逾400歲的巨大臺灣雲杉標本，觀眾可在體驗區用嗅覺、觸覺感受它的氣味及紋理，還有身長近4公尺，可手動操作的機械魷魚，吸睛又酷炫。\r\n\r\n《奇幻自然》常設展區位於生命科學廳地下1樓，展區面積253坪，從規劃評估、設計提案凝聚20名共同策展人、知名御匠設計公司及其合作團隊心血，歷經3年多溝通琢磨，才將它的前身《數與形》改頭換面。\r\n\r\n《奇幻自然》包含5單元：〈哇自然！嗨科學〉、〈圓不圓：蛋科學〉、〈動一動：生物力學〉、〈追呀追：計算與行為〉、〈說故事：探索自然，發現科學〉，細緻介紹自然界的多樣性、形態、功能、行為和科學探究，觀眾可盡情探索琳瑯滿目的科學故事。\r\n\r\n博物館常設展一般會展出10年至20年，拜科技所賜，如今學界每隔幾年就可能「發現新物種」或「建立新理論」，因此展示櫃特別設計成「前開式」，方便未來依據學術發現與時俱進、即時更新展品或標本，也能配合講座或導覽需求與觀眾互動。\r\n\r\n國立自然科學博物館生命科學廳1988年完工，由首任館長漢寶德邀請英籍設計師James Gardner設計、英國Beck & Politzer公司製作，以大自然的奧祕為主題，展示遠古生物到現代人類的精彩演化，深受大眾歡迎。當時《數與形》就有多種趣味互動裝置，搭配簡單易懂、延伸性數科概念，為無數人打開自然科學視野。\r\n', `organizer`='國立自然科學博物館', `address`='臺中市北區館前路1號', `start_date`='2024-01-19 00:00:00', `end_date`='2034-12-31 00:00:00', `location`='國立自然科學博物館', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='憑恐龍卡或展示場門票即可參觀，票價參考：https://www.nmns.edu.tw/ch/visit/ticket/', `source_url`='https://iticket.nmns.edu.tw/iticket/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67608cfe26b32458d4362eca', '「藝百家100+」 百位藝師誕生的現在進行式', '這是一場關於 22 種傳統技藝、114 位準藝師如何誕生的展覽。走進展間，你將沈浸在準藝師們的動畫世界中，不只透過靜態的文字閱讀，還能彷彿身歷其境般地一邊品味藝術、一邊被藝師們平凡中見不凡的成長故事所感動，在他們流動的身段與技藝中得到啟發，進而想像自己閃閃發光的未來.....\n\nThis is an exhibition on the birth of 22 traditional crafts and 114 aspiring artists. Visiting the exhibition room, you will immerse yourself in the animation world of aspiring artists, reading static text, savoring art and being moved by the extraordinary growth stories of artists. Inspired by their flowing figures and skills, you will imagine your own shining future.', '文化部文化資產局', '402  臺中市南區台中市南區復興路三段362號', '2025-01-18 00:00:00', '2026-01-17 00:00:00', '國際展演館A館', 24.1334405, 120.6816622, '無資料', 'https://event.culture.tw/mocweb/reg/BOCH/Detail.init.ctr?actId=40040', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「藝百家100+」 百位藝師誕生的現在進行式', `description`='這是一場關於 22 種傳統技藝、114 位準藝師如何誕生的展覽。走進展間，你將沈浸在準藝師們的動畫世界中，不只透過靜態的文字閱讀，還能彷彿身歷其境般地一邊品味藝術、一邊被藝師們平凡中見不凡的成長故事所感動，在他們流動的身段與技藝中得到啟發，進而想像自己閃閃發光的未來.....\n\nThis is an exhibition on the birth of 22 traditional crafts and 114 aspiring artists. Visiting the exhibition room, you will immerse yourself in the animation world of aspiring artists, reading static text, savoring art and being moved by the extraordinary growth stories of artists. Inspired by their flowing figures and skills, you will imagine your own shining future.', `organizer`='文化部文化資產局', `address`='402  臺中市南區台中市南區復興路三段362號', `start_date`='2025-01-18 00:00:00', `end_date`='2026-01-17 00:00:00', `location`='國際展演館A館', `latitude`=24.1334405, `longitude`=120.6816622, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/BOCH/Detail.init.ctr?actId=40040', `image_url`='[]';
