INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6778537826b32458d436347a', '藝術市集街頭藝人表演', '為扶植在地文化創意產業，邀請取得高雄市街頭藝人認證標章街頭藝人，於每週六、日16時至21時30分在文化中心藝術大道之假日藝術市集中提供陶笛、二胡、薩克斯風、電子吹管及鋼琴演奏等表演活動。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝術市集街頭藝人表演', `description`='為扶植在地文化創意產業，邀請取得高雄市街頭藝人認證標章街頭藝人，於每週六、日16時至21時30分在文化中心藝術大道之假日藝術市集中提供陶笛、二胡、薩克斯風、電子吹管及鋼琴演奏等表演活動。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678188c926b32458d43635b5', '樽藏文資：檔案上的第五酒廠與文化資產局', '展覽地點：文化資產園區綠建築一樓\n\n展覽時間：每週一至週五9:00~17:00，國定假日不開放\n\n從酒廠到歷史建築，「樽藏文資：檔案上的第五酒廠與文化資產局」是一場探索歷史與機關檔案的展覽，透過機關珍藏的檔案來了解曾經的酒廠如何轉型為現今的文化資產保存重鎮。展出內容包括文資局的公務檔案、第五酒廠的歷史建築公告，甚至是《文化資產保存法》初版總統府公報！這些珍貴資料，揭示了第五酒廠的歷史以及文資局的前世今生！展覽的標題「樽藏文資」，象徵著對歷史檔案的珍藏與保存，與園區的酒廠歷史緊密相連。無論您是對文化資產有興趣，還是對第五酒廠的歷史充滿好奇，這裡都有您想了解的一切！快來與我們一起探索那些被「樽藏」的歷史檔案吧！\n\n ', '文化部文化資產局', '402  臺中市南區復興路三段362號', '2025-01-01 00:00:00', '2028-01-01 00:00:00', '文化資產園區綠建築一樓', 24.1334779, 120.6816938, '無資料', 'https://event.culture.tw/mocweb/reg/BOCH/Detail.init.ctr?actId=50001', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樽藏文資：檔案上的第五酒廠與文化資產局', `description`='展覽地點：文化資產園區綠建築一樓\n\n展覽時間：每週一至週五9:00~17:00，國定假日不開放\n\n從酒廠到歷史建築，「樽藏文資：檔案上的第五酒廠與文化資產局」是一場探索歷史與機關檔案的展覽，透過機關珍藏的檔案來了解曾經的酒廠如何轉型為現今的文化資產保存重鎮。展出內容包括文資局的公務檔案、第五酒廠的歷史建築公告，甚至是《文化資產保存法》初版總統府公報！這些珍貴資料，揭示了第五酒廠的歷史以及文資局的前世今生！展覽的標題「樽藏文資」，象徵著對歷史檔案的珍藏與保存，與園區的酒廠歷史緊密相連。無論您是對文化資產有興趣，還是對第五酒廠的歷史充滿好奇，這裡都有您想了解的一切！快來與我們一起探索那些被「樽藏」的歷史檔案吧！\n\n ', `organizer`='文化部文化資產局', `address`='402  臺中市南區復興路三段362號', `start_date`='2025-01-01 00:00:00', `end_date`='2028-01-01 00:00:00', `location`='文化資產園區綠建築一樓', `latitude`=24.1334779, `longitude`=120.6816938, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/BOCH/Detail.init.ctr?actId=50001', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894526b32458d43635f5', '研習：澎湖縣政府文化局合唱團培訓', '文化局合唱團成立至今已屆29年，期間曾連續2年勇奪全國音樂比賽24強第5名暨第4名的佳績，102年再獲全國社會組合唱比賽混聲組銅質獎；亦曾在澎湖縣辦理的3次國際合唱節中與國際團體同台飆歌，獲得外國合唱指揮的讚譽；平均每年辦理1次音樂會，更為了提昇本團演出經驗與水準，這幾年爭取部分經費補助與國外團體交流，造訪國家有美國愛德荷州、香港、新加坡、日本、大陸泉州、北京、廈門、福州、杭州等，將澎湖人美麗的嗓音傳播到世界更多的角落，最重要的是讓更多人認識澎湖，推動澎湖的觀光。', '澎湖縣政府文化局', '澎湖縣馬公市中華路230號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '澎湖縣政府文化局', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='研習：澎湖縣政府文化局合唱團培訓', `description`='文化局合唱團成立至今已屆29年，期間曾連續2年勇奪全國音樂比賽24強第5名暨第4名的佳績，102年再獲全國社會組合唱比賽混聲組銅質獎；亦曾在澎湖縣辦理的3次國際合唱節中與國際團體同台飆歌，獲得外國合唱指揮的讚譽；平均每年辦理1次音樂會，更為了提昇本團演出經驗與水準，這幾年爭取部分經費補助與國外團體交流，造訪國家有美國愛德荷州、香港、新加坡、日本、大陸泉州、北京、廈門、福州、杭州等，將澎湖人美麗的嗓音傳播到世界更多的角落，最重要的是讓更多人認識澎湖，推動澎湖的觀光。', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路230號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='澎湖縣政府文化局', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6781894526b32458d43635f8', '研習：澎湖縣政府文化局南管班培訓', '由蘇菁萍、張建勝老師每週一晚間7時-9時、週六下午3時-5時於本局演藝廳文藝之家辦理南管樂培訓，並經常獲邀至本縣各鄉市巡演，使傳統南管樂推廣至各社區，希望藉由演出使民眾品味古人優雅雋永的樂風，吸引有興趣民眾參與南管音樂，增進南管技藝，進而達成南管音樂人才培育與推廣。', '澎湖縣政府文化局', '澎湖縣馬公市中華路230號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '澎湖縣政府文化局', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='研習：澎湖縣政府文化局南管班培訓', `description`='由蘇菁萍、張建勝老師每週一晚間7時-9時、週六下午3時-5時於本局演藝廳文藝之家辦理南管樂培訓，並經常獲邀至本縣各鄉市巡演，使傳統南管樂推廣至各社區，希望藉由演出使民眾品味古人優雅雋永的樂風，吸引有興趣民眾參與南管音樂，增進南管技藝，進而達成南管音樂人才培育與推廣。', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路230號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='澎湖縣政府文化局', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678b1d128f15e3aa87f3311c', '寶嚴山寶嚴禪寺2025課程', '無資料', '寶嚴山寶嚴禪寺', '新北市板橋區四川路一段178-180號', '2025-02-24 00:00:00', '2025-12-31 00:00:00', '寶嚴禪寺各分院', 25.01186453, 121.4579675, '隨喜護持', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='寶嚴山寶嚴禪寺2025課程', `description`='無資料', `organizer`='寶嚴山寶嚴禪寺', `address`='新北市板橋區四川路一段178-180號', `start_date`='2025-02-24 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='寶嚴禪寺各分院', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='隨喜護持', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67abbc0126b3240c403d94b2', '毫端照大千-劉嘉成書法篆刻展', '文化部所屬國立彰化生活美學館自114年2月20日至4月6日，在該館第一、二展覽室舉辦「毫端照大千—劉嘉成書法篆刻展」，展出國立臺灣藝術大學劉嘉成老師的書法及篆刻創作。集書法與篆刻技藝於一身的劉嘉成，無論教學或創作，兩種藝術類型皆已融會貫通，相輔相成，體現「剛柔並濟｣的境界。本次展覽主題「毫端照大千-劉嘉成書法篆刻展｣，正是著眼於細微如絲的筆端，能夠寫盡萬象，觀照大千世界、啟迪人心。\n\n書法篆刻家劉嘉成，是出身彰化的農家子弟，先天不具備接觸藝術的環境下，卻在舅舅陳秋聲的啟蒙下，開始接觸書法、繪畫等諸多才藝；課餘之暇，經常閱讀歷代法帖相關典故，進而領略古法，心摹手追，為往後奠定基礎。進而自大學，乃至碩士、博士等研究階段，一路都在書畫藝術學系學習，取得博士學位後繼續留校服務，現為國立臺灣藝術大學書畫藝術學系助理教授。\n\n劉嘉成深受傳統古典作品洗滌，或習見今人大膽下筆等創意啟發，不時激發自身創作靈感，或轉瞬即逝，礙於條件所限，或課堂示範，或隨手草稿，工拙不計，卻隨著時間推移而沉澱積累。對他而言，書法，藉由文字的書寫，無論是經典雋語，或是通俗吉語，皆反映人在不同時空中，高度地凝煉表達書家自身的情感與寄託。對於外在，技術層次須高度掌握書寫工具材料，經由筆法、結體、章法逐漸架構而成，無論是技法的書寫或視覺造型的衝擊外，皆有其用心之處；對於內在，書法史的傳承深化，因為時空背景影響，逐漸影響個人的思想，更是自身的情感寄託之處。因此，此道似易實難，亦為畫、印之根本。\n\n也正因為書法家的創作，是內外呼應的結晶。本次展出劉嘉成的書法作品「崔子玉座右銘｣，不但有其生命歷程上的重要意義，其內容也如師長的叮囑，時時刻刻提醒處世所應自持的克己復禮；另外，劉嘉成引《論語･述而》寫下的「志於道、據於德、依於仁、游於藝｣，也將在本次展覽呈現。從其書法作品，不僅看到他書藝的精湛，更能看到他嚮往的聖賢之道，以及對於人生樂觀正面的社會意義。\n\n同時也是本次展覽亮點的篆刻藝術，歷史源遠流長。先秦開始有官私印，功能多元，姓名字號章至今仍為憑證之信物。印章沿至元明，文人參與，與詩書畫結合，形成閒章，獨立形成藝術。此外，透過毛筆設計書寫或文或圖，再「鐵筆」鐫刻雕鑿始成，缺一不可，為二度加工之藝品。印材除了習見的葉蠟軟石之外，亦嘗試以竹木、牙角、陶瓷、金屬等材料創作，如金屬印可鑄可鑿，陶瓷則需燒熟，皆需相應工具與工法始成，皆考驗刻家跨領域的駕馭能力。劉嘉成透過蠟雕鑄造所打造的銅印鈕式，以及刻劃素坯所燒製的陶板瓷盤，開創了印材與印文的新格局，相信會給觀展的金石愛好者，耳目一新的視覺饗宴。\n\n \n\n ', '國立彰化生活美學館', '500  彰化縣彰化市74卦山路18號', '2025-02-20 00:00:00', '2028-02-20 00:00:00', '國立彰化生活美學館第一、二展覽室', 24.0765278, 120.5573442, '無資料', 'https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50351', '[]') ON DUPLICATE KEY UPDATE `activity_name`='毫端照大千-劉嘉成書法篆刻展', `description`='文化部所屬國立彰化生活美學館自114年2月20日至4月6日，在該館第一、二展覽室舉辦「毫端照大千—劉嘉成書法篆刻展」，展出國立臺灣藝術大學劉嘉成老師的書法及篆刻創作。集書法與篆刻技藝於一身的劉嘉成，無論教學或創作，兩種藝術類型皆已融會貫通，相輔相成，體現「剛柔並濟｣的境界。本次展覽主題「毫端照大千-劉嘉成書法篆刻展｣，正是著眼於細微如絲的筆端，能夠寫盡萬象，觀照大千世界、啟迪人心。\n\n書法篆刻家劉嘉成，是出身彰化的農家子弟，先天不具備接觸藝術的環境下，卻在舅舅陳秋聲的啟蒙下，開始接觸書法、繪畫等諸多才藝；課餘之暇，經常閱讀歷代法帖相關典故，進而領略古法，心摹手追，為往後奠定基礎。進而自大學，乃至碩士、博士等研究階段，一路都在書畫藝術學系學習，取得博士學位後繼續留校服務，現為國立臺灣藝術大學書畫藝術學系助理教授。\n\n劉嘉成深受傳統古典作品洗滌，或習見今人大膽下筆等創意啟發，不時激發自身創作靈感，或轉瞬即逝，礙於條件所限，或課堂示範，或隨手草稿，工拙不計，卻隨著時間推移而沉澱積累。對他而言，書法，藉由文字的書寫，無論是經典雋語，或是通俗吉語，皆反映人在不同時空中，高度地凝煉表達書家自身的情感與寄託。對於外在，技術層次須高度掌握書寫工具材料，經由筆法、結體、章法逐漸架構而成，無論是技法的書寫或視覺造型的衝擊外，皆有其用心之處；對於內在，書法史的傳承深化，因為時空背景影響，逐漸影響個人的思想，更是自身的情感寄託之處。因此，此道似易實難，亦為畫、印之根本。\n\n也正因為書法家的創作，是內外呼應的結晶。本次展出劉嘉成的書法作品「崔子玉座右銘｣，不但有其生命歷程上的重要意義，其內容也如師長的叮囑，時時刻刻提醒處世所應自持的克己復禮；另外，劉嘉成引《論語･述而》寫下的「志於道、據於德、依於仁、游於藝｣，也將在本次展覽呈現。從其書法作品，不僅看到他書藝的精湛，更能看到他嚮往的聖賢之道，以及對於人生樂觀正面的社會意義。\n\n同時也是本次展覽亮點的篆刻藝術，歷史源遠流長。先秦開始有官私印，功能多元，姓名字號章至今仍為憑證之信物。印章沿至元明，文人參與，與詩書畫結合，形成閒章，獨立形成藝術。此外，透過毛筆設計書寫或文或圖，再「鐵筆」鐫刻雕鑿始成，缺一不可，為二度加工之藝品。印材除了習見的葉蠟軟石之外，亦嘗試以竹木、牙角、陶瓷、金屬等材料創作，如金屬印可鑄可鑿，陶瓷則需燒熟，皆需相應工具與工法始成，皆考驗刻家跨領域的駕馭能力。劉嘉成透過蠟雕鑄造所打造的銅印鈕式，以及刻劃素坯所燒製的陶板瓷盤，開創了印材與印文的新格局，相信會給觀展的金石愛好者，耳目一新的視覺饗宴。\n\n \n\n ', `organizer`='國立彰化生活美學館', `address`='500  彰化縣彰化市74卦山路18號', `start_date`='2025-02-20 00:00:00', `end_date`='2028-02-20 00:00:00', `location`='國立彰化生活美學館第一、二展覽室', `latitude`=24.0765278, `longitude`=120.5573442, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50351', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('849', '無資料', '武陵農場海拔高度位於1,740至2,200公尺間，自民國82年（西元1993年）開始種植櫻花樹，被譽為全台賞櫻首選勝地，近年來因撫育得當，每年1至2月櫻花季期間一片粉白花海花況甚佳，在遊客主動透過部落格、臉書及網路等傳送下廣受媒體關注，於花季期間來場採訪報導，吸引數十萬民眾蜂擁上山賞花。', '國軍退除役官兵輔導委員會武陵農場', '臺中市 和平區武陵農場', '臺中市 和平區武陵農場', 24.3523587, 121.3085972, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='武陵農場海拔高度位於1,740至2,200公尺間，自民國82年（西元1993年）開始種植櫻花樹，被譽為全台賞櫻首選勝地，近年來因撫育得當，每年1至2月櫻花季期間一片粉白花海花況甚佳，在遊客主動透過部落格、臉書及網路等傳送下廣受媒體關注，於花季期間來場採訪報導，吸引數十萬民眾蜂擁上山賞花。', `organizer`='國軍退除役官兵輔導委員會武陵農場', `address`='臺中市 和平區武陵農場', `location`='臺中市 和平區武陵農場', `latitude`=24.3523587, `longitude`=121.3085972, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('872', '無資料', '2025台灣燈會介紹     \n\r\r\n     「2025台灣燈會」在桃園將以「光聚千塘串桃園」打造親子與文化結合的光影盛宴，透過桃園眾多埤塘如鏡面般的水面，映照出桃園的城市樣貌，閃閃發光的埤塘如同燈飾作品訴說著地方故事，透過燈藝串連桃園地方特色，營造一個光影交織的幸福城市。      \n\r\r\n活動地點：桃園     \n\r\r\n活動日期：2025年2月12日 ～ 2月23日\r\n \r\n元宵節提燈籠原本是傳統的民俗活動，在融合本土風情及新科技後，台灣燈會更打造出國際級觀光盛會的氣勢，不但主燈展演美不勝收，國內外民俗團體的精采獻藝，以及一波波表演團隊之熱絡表演，使得來臺參加台灣燈會的國外嘉賓及旅客都讚聲連連。西元2007年間，美國Discovery節目製作人來臺參訪台灣燈會元宵活動，將其評選為「全球最佳慶典活動」之一。\r\n ', '交通部觀光署、桃園市政府', '桃園市 中壢區A18高鐵桃園站', '桃園市 中壢區A18高鐵桃園站', 25.01380563, 121.21406896, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='2025台灣燈會介紹     \n\r\r\n     「2025台灣燈會」在桃園將以「光聚千塘串桃園」打造親子與文化結合的光影盛宴，透過桃園眾多埤塘如鏡面般的水面，映照出桃園的城市樣貌，閃閃發光的埤塘如同燈飾作品訴說著地方故事，透過燈藝串連桃園地方特色，營造一個光影交織的幸福城市。      \n\r\r\n活動地點：桃園     \n\r\r\n活動日期：2025年2月12日 ～ 2月23日\r\n \r\n元宵節提燈籠原本是傳統的民俗活動，在融合本土風情及新科技後，台灣燈會更打造出國際級觀光盛會的氣勢，不但主燈展演美不勝收，國內外民俗團體的精采獻藝，以及一波波表演團隊之熱絡表演，使得來臺參加台灣燈會的國外嘉賓及旅客都讚聲連連。西元2007年間，美國Discovery節目製作人來臺參訪台灣燈會元宵活動，將其評選為「全球最佳慶典活動」之一。\r\n ', `organizer`='交通部觀光署、桃園市政府', `address`='桃園市 中壢區A18高鐵桃園站', `location`='桃園市 中壢區A18高鐵桃園站', `latitude`=25.01380563, `longitude`=121.21406896, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('818', '2025 馬祖擺暝文化祭', '擺暝文化為馬祖最具代表性的文化活動，極具獨特性，於2019年通過登錄文化部國家重要民俗之一。「擺暝（音ㄅㄟˇ ㄇㄢˋ）」是福州話，為「排夜」的意思，簡單來說就是在夜晚的時候排放供品祭神酬神，在每年的元宵節前後舉行，夜間各廟宇的神還會出宮繞境，以祈求全境平安。此習俗最早源自於福州長樂、連江一帶，流傳至馬祖成為一年當中最重要、最盛大且特有的節慶活動。', '連江縣政府文化處', '連江縣 北竿鄉坂里大宅前廣場', '2025-02-09 00:00:00', '2025-02-26 00:00:00', '連江縣 北竿鄉坂里大宅前廣場', 26.21630973, 119.97420308, '無資料', 'https://www.matsu-news.gov.tw/news/article/227352', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 馬祖擺暝文化祭', `description`='擺暝文化為馬祖最具代表性的文化活動，極具獨特性，於2019年通過登錄文化部國家重要民俗之一。「擺暝（音ㄅㄟˇ ㄇㄢˋ）」是福州話，為「排夜」的意思，簡單來說就是在夜晚的時候排放供品祭神酬神，在每年的元宵節前後舉行，夜間各廟宇的神還會出宮繞境，以祈求全境平安。此習俗最早源自於福州長樂、連江一帶，流傳至馬祖成為一年當中最重要、最盛大且特有的節慶活動。', `organizer`='連江縣政府文化處', `address`='連江縣 北竿鄉坂里大宅前廣場', `start_date`='2025-02-09 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='連江縣 北竿鄉坂里大宅前廣場', `latitude`=26.21630973, `longitude`=119.97420308, `ticket_price`='無資料', `source_url`='https://www.matsu-news.gov.tw/news/article/227352', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('731', '2024-2025屏東落山風藝術季', '屏東落山風藝術季以車城海口港「落山風之吹風看海地」及旁邊沙灘為主要場地，以大型藝術裝置及表演活動形式，展現風與地方之特色。', '屏東縣政府傳播暨國際事務處', '屏東縣 車城鄉海口港看海美術館', '2024-12-20 00:00:00', '2025-03-02 00:00:00', '屏東縣 車城鄉海口港看海美術館', 22.0899521, 120.7152878, '無資料', 'https://www.facebook.com/lsf.arts?locale=zh_TW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2024-2025屏東落山風藝術季', `description`='屏東落山風藝術季以車城海口港「落山風之吹風看海地」及旁邊沙灘為主要場地，以大型藝術裝置及表演活動形式，展現風與地方之特色。', `organizer`='屏東縣政府傳播暨國際事務處', `address`='屏東縣 車城鄉海口港看海美術館', `start_date`='2024-12-20 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='屏東縣 車城鄉海口港看海美術館', `latitude`=22.0899521, `longitude`=120.7152878, `ticket_price`='無資料', `source_url`='https://www.facebook.com/lsf.arts?locale=zh_TW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('858', '2025暨大櫻花季', '暨大賞櫻活動已辦理12年，與日月潭觀光圈串聯，整合日月潭觀光圈櫻花手作活動、台灣之心爸媽放風主題日的親子遊程與台灣之心-埔里鎮吉祥物噗哩等主題活動，亦於日月潭觀光圈舉辦創意市集等，在櫻花季結合「櫻花」、「茶道」、「音樂」、與「咖啡」等主題活動。', '國立暨南國際大學、交通部觀光署日月潭國家風景區管理處', '南投縣 埔里鎮大學路一號', '2025-02-03 00:00:00', '2025-03-02 00:00:00', '南投縣 埔里鎮大學路一號', 23.9494326, 120.9376825, '無資料', 'https://sakura.ncnu.edu.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025暨大櫻花季', `description`='暨大賞櫻活動已辦理12年，與日月潭觀光圈串聯，整合日月潭觀光圈櫻花手作活動、台灣之心爸媽放風主題日的親子遊程與台灣之心-埔里鎮吉祥物噗哩等主題活動，亦於日月潭觀光圈舉辦創意市集等，在櫻花季結合「櫻花」、「茶道」、「音樂」、與「咖啡」等主題活動。', `organizer`='國立暨南國際大學、交通部觀光署日月潭國家風景區管理處', `address`='南投縣 埔里鎮大學路一號', `start_date`='2025-02-03 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='南投縣 埔里鎮大學路一號', `latitude`=23.9494326, `longitude`=120.9376825, `ticket_price`='無資料', `source_url`='https://sakura.ncnu.edu.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('817', '2025北竿硬地超級馬拉松', '「北竿硬地超級馬拉松」自民國106年（西元2017年）首度舉辦，由於地形陡峻起伏多變，賽道上幾乎沒有平坦的路段，極具挑戰性，因此跑友們稱其為「最硬賽道」，故而取名為硬地超級馬拉松。亦獲得國際超級馬拉松運動協會的銅標籤認證。除了賽道的獨特性外，北竿的戰地景觀及特殊的海島風光也是讓跑友們最津津樂道之處，沿途美景處處，藍天碧海相伴，使報名參與賽事的人數逐年成長。', '連江縣政府交通旅遊局', '連江縣 北竿鄉北竿塘岐村迎賓館前廣場', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '連江縣 北竿鄉北竿塘岐村迎賓館前廣場', 26.223938, 119.997139, '無資料', 'https://www.facebook.com/MatsuBeiganUltraMarathon?locale2=ms_MY', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025北竿硬地超級馬拉松', `description`='「北竿硬地超級馬拉松」自民國106年（西元2017年）首度舉辦，由於地形陡峻起伏多變，賽道上幾乎沒有平坦的路段，極具挑戰性，因此跑友們稱其為「最硬賽道」，故而取名為硬地超級馬拉松。亦獲得國際超級馬拉松運動協會的銅標籤認證。除了賽道的獨特性外，北竿的戰地景觀及特殊的海島風光也是讓跑友們最津津樂道之處，沿途美景處處，藍天碧海相伴，使報名參與賽事的人數逐年成長。', `organizer`='連江縣政府交通旅遊局', `address`='連江縣 北竿鄉北竿塘岐村迎賓館前廣場', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='連江縣 北竿鄉北竿塘岐村迎賓館前廣場', `latitude`=26.223938, `longitude`=119.997139, `ticket_price`='無資料', `source_url`='https://www.facebook.com/MatsuBeiganUltraMarathon?locale2=ms_MY', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('866', '2025八卦山賞鷹季系列活動', '灰面鵟鷹又稱為灰面鷲，主要是因為牠的雄鳥臉部為灰色而得名，因為其在清明前後抵達八卦山及大肚山區，中部地區民眾稱其為「清明鳥」或「掃墓鳥」，又因其由南邊而來，也被稱為「南路鷹」。灰面鵟鷹也是彰化縣縣鳥，象徵彰化人重承諾、守信用及慎終追遠的意義，牠為珍貴稀有保育類動物。\r\n每年三月到四月春天期間，灰面鵟鷹由渡冬地北返過境八卦山，地區賞鷹活動至今已舉辦長達30年，活動辦理是為了長期守護灰面鵟鷹，提倡宣導生態保育觀念。', '參山國家風景區管理處、彰化縣政府、農業部林業及自然保育署南投林區管理處、農業部水土保持局南投分局', '彰化縣 芬園鄉文德國小', '2025-03-12 00:00:00', '2025-03-30 00:00:00', '彰化縣 芬園鄉文德國小', 24.0785005, 120.5556363, '無資料', 'https://www.trimt-nsa.gov.tw/zh-tw/event/7965/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025八卦山賞鷹季系列活動', `description`='灰面鵟鷹又稱為灰面鷲，主要是因為牠的雄鳥臉部為灰色而得名，因為其在清明前後抵達八卦山及大肚山區，中部地區民眾稱其為「清明鳥」或「掃墓鳥」，又因其由南邊而來，也被稱為「南路鷹」。灰面鵟鷹也是彰化縣縣鳥，象徵彰化人重承諾、守信用及慎終追遠的意義，牠為珍貴稀有保育類動物。\r\n每年三月到四月春天期間，灰面鵟鷹由渡冬地北返過境八卦山，地區賞鷹活動至今已舉辦長達30年，活動辦理是為了長期守護灰面鵟鷹，提倡宣導生態保育觀念。', `organizer`='參山國家風景區管理處、彰化縣政府、農業部林業及自然保育署南投林區管理處、農業部水土保持局南投分局', `address`='彰化縣 芬園鄉文德國小', `start_date`='2025-03-12 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='彰化縣 芬園鄉文德國小', `latitude`=24.0785005, `longitude`=120.5556363, `ticket_price`='無資料', `source_url`='https://www.trimt-nsa.gov.tw/zh-tw/event/7965/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('669', '2024-2025雙年賞蝶', '茂林國家風景區位於高屏山區，長久以「紫蝶幽谷」特殊景象聞名國內外，亦為綠色米其林指南推薦三星生態景點。「雙年賞蝶」是每年11月開始至隔年3月在茂林國家風景區的重頭戲，此時，會有成千上萬的紫斑蝶遠渡重洋，來到此地棲息，形成壯觀的「紫蝶幽谷」生態現象。', '交通部觀光署茂林國家風景區管理處、高雄市政府、高雄市茂林區公所', '高雄市 茂林區茂林生態公園', '2024-11-16 00:00:00', '2025-03-31 00:00:00', '高雄市 茂林區茂林生態公園', 22.887377, 120.6631441, '無資料', 'https://theme.maolin-nsa.gov.tw/butterfly2024/ch/page-2.html#main', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2024-2025雙年賞蝶', `description`='茂林國家風景區位於高屏山區，長久以「紫蝶幽谷」特殊景象聞名國內外，亦為綠色米其林指南推薦三星生態景點。「雙年賞蝶」是每年11月開始至隔年3月在茂林國家風景區的重頭戲，此時，會有成千上萬的紫斑蝶遠渡重洋，來到此地棲息，形成壯觀的「紫蝶幽谷」生態現象。', `organizer`='交通部觀光署茂林國家風景區管理處、高雄市政府、高雄市茂林區公所', `address`='高雄市 茂林區茂林生態公園', `start_date`='2024-11-16 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='高雄市 茂林區茂林生態公園', `latitude`=22.887377, `longitude`=120.6631441, `ticket_price`='無資料', `source_url`='https://theme.maolin-nsa.gov.tw/butterfly2024/ch/page-2.html#main', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('721', '經濟部商業署臺菜餐廳系列活動', '為帶動我國餐飲產業發展，持續推廣並傳承臺菜文化，以「臺菜」為主軸運用主題式行銷、國際推廣及商機促進，以吸引國內外旅客體驗臺灣美食好滋味。活動廣召並遴選出全臺60家以上優質臺菜餐廳業者，透過展售活動及聯合行銷方式來提升品牌知名度與業績，預計每年活動可吸引至少1萬人次參與。', '經濟部商業署', '臺北市 文山區星靚點花園飯店', '2025-02-28 00:00:00', '2025-03-31 00:00:00', '臺北市 文山區星靚點花園飯店', 24.9920823, 121.5435788, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='經濟部商業署臺菜餐廳系列活動', `description`='為帶動我國餐飲產業發展，持續推廣並傳承臺菜文化，以「臺菜」為主軸運用主題式行銷、國際推廣及商機促進，以吸引國內外旅客體驗臺灣美食好滋味。活動廣召並遴選出全臺60家以上優質臺菜餐廳業者，透過展售活動及聯合行銷方式來提升品牌知名度與業績，預計每年活動可吸引至少1萬人次參與。', `organizer`='經濟部商業署', `address`='臺北市 文山區星靚點花園飯店', `start_date`='2025-02-28 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺北市 文山區星靚點花園飯店', `latitude`=24.9920823, `longitude`=121.5435788, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('843', '2025高雄內門宋江陣', '高雄內門宋江陣自西元2001年起開始舉辦，由高雄市政府及內門三大廟宇共同辦理，結合民俗藝陣、地方節慶、觀光旅遊、產業經濟等元素，將原屬地方廟會活動擴大為融合表演藝術、宗教信仰與在地文化底蘊的在地嘉年華，係內門、旗山區一年一度宗教暨文化慶典盛事。', '高雄市政府', '高雄市 內門區內門順賢宮', '2025-03-28 00:00:00', '2025-04-06 00:00:00', '高雄市 內門區內門順賢宮', 22.91258485, 120.47076319, '無資料', 'https://www.facebook.com/kaohsiungwhoha/?locale=zh_TW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025高雄內門宋江陣', `description`='高雄內門宋江陣自西元2001年起開始舉辦，由高雄市政府及內門三大廟宇共同辦理，結合民俗藝陣、地方節慶、觀光旅遊、產業經濟等元素，將原屬地方廟會活動擴大為融合表演藝術、宗教信仰與在地文化底蘊的在地嘉年華，係內門、旗山區一年一度宗教暨文化慶典盛事。', `organizer`='高雄市政府', `address`='高雄市 內門區內門順賢宮', `start_date`='2025-03-28 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='高雄市 內門區內門順賢宮', `latitude`=22.91258485, `longitude`=120.47076319, `ticket_price`='無資料', `source_url`='https://www.facebook.com/kaohsiungwhoha/?locale=zh_TW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('867', '2025大鵬灣帆船生活節', ' \r\n「大鵬灣帆船生活節」每年四月份在濱灣碼頭辦理，結合遊艇活動推廣、船聚、大鵬灣CIQS服務、帆船嘉年華、帆船競技嘉年華、一日船長體驗、遊艇自駕體驗及屏東觀光圈市集等，是國內規模最大之帆船競技嘉年華。\r\n ', '交通部觀光署大鵬灣國家風景區管理處', '屏東縣 東港鎮濱灣碼頭', '2025-04-11 00:00:00', '2025-04-13 00:00:00', '屏東縣 東港鎮濱灣碼頭', 22.4366226, 120.4773865, '無資料', 'https://bao-ming.com/eb/content/6378#29944', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025大鵬灣帆船生活節', `description`=' \r\n「大鵬灣帆船生活節」每年四月份在濱灣碼頭辦理，結合遊艇活動推廣、船聚、大鵬灣CIQS服務、帆船嘉年華、帆船競技嘉年華、一日船長體驗、遊艇自駕體驗及屏東觀光圈市集等，是國內規模最大之帆船競技嘉年華。\r\n ', `organizer`='交通部觀光署大鵬灣國家風景區管理處', `address`='屏東縣 東港鎮濱灣碼頭', `start_date`='2025-04-11 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='屏東縣 東港鎮濱灣碼頭', `latitude`=22.4366226, `longitude`=120.4773865, `ticket_price`='無資料', `source_url`='https://bao-ming.com/eb/content/6378#29944', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('860', '西拉雅森活節', '西拉雅森活節規劃於旅遊淡季4-5月份舉辦，以官田遊客中心為核心，與園區基地打造屬於西拉雅草原風格的活動。\r\n活動結合音樂演出、創意市集、舞台活動、草原活動、毛孩運動會以及熱氣球嘉年華等一系列多元豐富具有特色及創意的活動內容，並邀請大西拉雅觀光圈業者一同共襄盛舉，創造西拉雅獨有的草原景象。', '西拉雅國家風景區管理處', '臺南市 官田區福田路99號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺南市 官田區福田路99號', 23.1884966, 120.3354993, '無資料', 'https://www.siraya-nsa.gov.tw/zh-tw/event/news/14133', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081557/a1720ab0ffc6cd690971c4c1e09108580ac86693.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='西拉雅森活節', `description`='西拉雅森活節規劃於旅遊淡季4-5月份舉辦，以官田遊客中心為核心，與園區基地打造屬於西拉雅草原風格的活動。\r\n活動結合音樂演出、創意市集、舞台活動、草原活動、毛孩運動會以及熱氣球嘉年華等一系列多元豐富具有特色及創意的活動內容，並邀請大西拉雅觀光圈業者一同共襄盛舉，創造西拉雅獨有的草原景象。', `organizer`='西拉雅國家風景區管理處', `address`='臺南市 官田區福田路99號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市 官田區福田路99號', `latitude`=23.1884966, `longitude`=120.3354993, `ticket_price`='無資料', `source_url`='https://www.siraya-nsa.gov.tw/zh-tw/event/news/14133', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081557/a1720ab0ffc6cd690971c4c1e09108580ac86693.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('802', '桃園龍岡米干節', ' 桃園龍岡地區擁有全臺難得的少數民族文化，如景頗、傣、傈僳族等。為讓民眾對異域金三角文化有更深認識，桃園市政府自2011年以在地美食「米干」為主軸說故事，透過活動展示異域金三角文化表演藝術、美食佳餚。活動內容包含金三角文化慶典、特色滇緬泰文化體驗以及龍岡商圈小旅行。\r\n ', '桃園市政府觀光旅遊局', '桃園市 中壢區龍岡大操場', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '桃園市 中壢區龍岡大操場', 24.92768113, 121.25433091, '無資料', 'https://travel.tycg.gov.tw/zh-tw/event/calendardetail/5197', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081437/fe345cc68a8fdb98e90660ce2b7eb64ff078d92f.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='桃園龍岡米干節', `description`=' 桃園龍岡地區擁有全臺難得的少數民族文化，如景頗、傣、傈僳族等。為讓民眾對異域金三角文化有更深認識，桃園市政府自2011年以在地美食「米干」為主軸說故事，透過活動展示異域金三角文化表演藝術、美食佳餚。活動內容包含金三角文化慶典、特色滇緬泰文化體驗以及龍岡商圈小旅行。\r\n ', `organizer`='桃園市政府觀光旅遊局', `address`='桃園市 中壢區龍岡大操場', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='桃園市 中壢區龍岡大操場', `latitude`=24.92768113, `longitude`=121.25433091, `ticket_price`='無資料', `source_url`='https://travel.tycg.gov.tw/zh-tw/event/calendardetail/5197', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081437/fe345cc68a8fdb98e90660ce2b7eb64ff078d92f.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('809', '2025南庄花卉節', '首年於2019舉辦南庄恆浪漫繡球花節打響南庄花卉節的品牌知名度;後建立「南庄花卉節」的品牌意涵，讓旅遊與在地資源深度連結。', '交通部觀光署參山國家風景區管理處', '苗栗縣 南庄鄉南庄鄉', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '苗栗縣 南庄鄉南庄鄉', 24.595344, 121.0003555, '無資料', '無資料', '["None"]') ON DUPLICATE KEY UPDATE `activity_name`='2025南庄花卉節', `description`='首年於2019舉辦南庄恆浪漫繡球花節打響南庄花卉節的品牌知名度;後建立「南庄花卉節」的品牌意涵，讓旅遊與在地資源深度連結。', `organizer`='交通部觀光署參山國家風景區管理處', `address`='苗栗縣 南庄鄉南庄鄉', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='苗栗縣 南庄鄉南庄鄉', `latitude`=24.595344, `longitude`=121.0003555, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["None"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('781', '2025苗栗通霄白沙屯拱天宮媽祖民俗文化系列活動', '苗栗縣通霄鎮拱天宮「白沙屯媽祖進香」活動為苗栗縣一年一度民俗盛事，具有百年以上歷史，不僅歷史悠久、規模盛大，每年均有來自全國各地居民熱情參與徒步到北港朝天宮進香，全程近400公里，縱跨中部4縣市。因其深具傳統性及特殊性，民國99年（西元2010年）獲文化部指定為國家重要民俗祭儀，也在民國102年（西元2013年）被選為內政部「台灣宗教百景」之一。', '苗栗縣政府、苗栗縣政府文化觀光局、苗栗縣通霄鎮公所', '苗栗縣 通霄鎮白東里8號', '2025-05-01 00:00:00', '2025-05-11 00:00:00', '苗栗縣 通霄鎮白東里8號', 24.5713722, 120.7092948, '無資料', 'https://www.facebook.com/baishatun.com.tw/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081402/2b91e99f4f3e2dda18ff6a8b375188c296cf03d1.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025苗栗通霄白沙屯拱天宮媽祖民俗文化系列活動', `description`='苗栗縣通霄鎮拱天宮「白沙屯媽祖進香」活動為苗栗縣一年一度民俗盛事，具有百年以上歷史，不僅歷史悠久、規模盛大，每年均有來自全國各地居民熱情參與徒步到北港朝天宮進香，全程近400公里，縱跨中部4縣市。因其深具傳統性及特殊性，民國99年（西元2010年）獲文化部指定為國家重要民俗祭儀，也在民國102年（西元2013年）被選為內政部「台灣宗教百景」之一。', `organizer`='苗栗縣政府、苗栗縣政府文化觀光局、苗栗縣通霄鎮公所', `address`='苗栗縣 通霄鎮白東里8號', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='苗栗縣 通霄鎮白東里8號', `latitude`=24.5713722, `longitude`=120.7092948, `ticket_price`='無資料', `source_url`='https://www.facebook.com/baishatun.com.tw/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081402/2b91e99f4f3e2dda18ff6a8b375188c296cf03d1.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('784', '2025宜蘭綠色博覽會', '宜蘭綠色博覽會於西元2000年創辦，融合文化藝術展演，創造園藝花卉地景，紮根環保生態教育，扶植農漁業產業轉型升級，帶動觀光休閒人潮，是宜蘭縣春季著名的大型環境教育旗艦活動。', '宜蘭縣政府', '宜蘭縣 蘇澳鎮武荖坑風景區', '2025-03-29 00:00:00', '2025-05-11 00:00:00', '宜蘭縣 蘇澳鎮武荖坑風景區', 24.6106408, 121.81446599, '無資料', 'https://www.facebook.com/yilangreenexpo/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081408/2c9dd1c2cf494b6325126274dfc4bc7fa0c5d6de.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025宜蘭綠色博覽會', `description`='宜蘭綠色博覽會於西元2000年創辦，融合文化藝術展演，創造園藝花卉地景，紮根環保生態教育，扶植農漁業產業轉型升級，帶動觀光休閒人潮，是宜蘭縣春季著名的大型環境教育旗艦活動。', `organizer`='宜蘭縣政府', `address`='宜蘭縣 蘇澳鎮武荖坑風景區', `start_date`='2025-03-29 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='宜蘭縣 蘇澳鎮武荖坑風景區', `latitude`=24.6106408, `longitude`=121.81446599, `ticket_price`='無資料', `source_url`='https://www.facebook.com/yilangreenexpo/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081408/2c9dd1c2cf494b6325126274dfc4bc7fa0c5d6de.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('792', '2025臺中媽祖國際觀光文化節', '臺中媽祖信仰獨具特色，大甲媽祖繞境全長340多公里，信徒們全程徒步隨行，結合臺中市轄內12間百年宮廟，在傳統宗教儀式的基礎上，整合不同地區媽祖信仰文化活動，希望將媽祖文化推展至國際舞臺，吸引世界各地的文化朝聖者來臺中體驗民俗信仰之美。', '臺中市政府文化局', '臺中市 大甲區12間百年宮廟', '2025-02-01 00:00:00', '2025-05-17 00:00:00', '臺中市 大甲區12間百年宮廟', 0, 0, '無資料', 'https://www.facebook.com/taichung.mazu.International.Festival/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081422/03717854adf39eaa9c0c59fb9a58373a514081b9.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺中媽祖國際觀光文化節', `description`='臺中媽祖信仰獨具特色，大甲媽祖繞境全長340多公里，信徒們全程徒步隨行，結合臺中市轄內12間百年宮廟，在傳統宗教儀式的基礎上，整合不同地區媽祖信仰文化活動，希望將媽祖文化推展至國際舞臺，吸引世界各地的文化朝聖者來臺中體驗民俗信仰之美。', `organizer`='臺中市政府文化局', `address`='臺中市 大甲區12間百年宮廟', `start_date`='2025-02-01 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='臺中市 大甲區12間百年宮廟', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.facebook.com/taichung.mazu.International.Festival/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081422/03717854adf39eaa9c0c59fb9a58373a514081b9.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('788', '2025 TIFA台灣國際藝術節', '台灣國際藝術節（Taiwan International Festival of Arts，簡稱TIFA）為台灣一年一度最重要的藝術節慶、亞洲最具亮點的藝文盛會。TIFA自2009年推出，於每年春天舉辦，至今已呈現近300檔的國內外經典節目，讓國內的觀眾放眼世界潮流，更將台灣的藝術能量穿透國際，TIFA不僅是國際藝術家匯聚交流的舞台，更是精采紛呈、讓觀眾每一年都引頸期盼的藝術慶典。\r\n\r\n    兩廳院夏日爵士\r\n    NTT遇見巨人\r\n    衛武營國際音樂節\r\n    衛武營旗艦歌劇\r\n\r\n ', '國家兩廳院', '臺北市 中正區國家兩廳院', '2025-02-21 00:00:00', '2025-05-18 00:00:00', '臺北市 中正區國家兩廳院', 25.0368857, 121.5187903, '無資料', 'https://npac-ntch.org/programs/series/tifa/2025', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081418/d6bc0ca6c89a6e263b000d3bbdb69933c94a6b03.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025 TIFA台灣國際藝術節', `description`='台灣國際藝術節（Taiwan International Festival of Arts，簡稱TIFA）為台灣一年一度最重要的藝術節慶、亞洲最具亮點的藝文盛會。TIFA自2009年推出，於每年春天舉辦，至今已呈現近300檔的國內外經典節目，讓國內的觀眾放眼世界潮流，更將台灣的藝術能量穿透國際，TIFA不僅是國際藝術家匯聚交流的舞台，更是精采紛呈、讓觀眾每一年都引頸期盼的藝術慶典。\r\n\r\n    兩廳院夏日爵士\r\n    NTT遇見巨人\r\n    衛武營國際音樂節\r\n    衛武營旗艦歌劇\r\n\r\n ', `organizer`='國家兩廳院', `address`='臺北市 中正區國家兩廳院', `start_date`='2025-02-21 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='臺北市 中正區國家兩廳院', `latitude`=25.0368857, `longitude`=121.5187903, `ticket_price`='無資料', `source_url`='https://npac-ntch.org/programs/series/tifa/2025', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081418/d6bc0ca6c89a6e263b000d3bbdb69933c94a6b03.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('853', '2025光復馬太鞍濕地-螢饗', '活動在螢火蟲出沒期間辦理，在花東最美木棧道的茅草屋中，與馬太鞍來場浪漫螢光晚餐，餐點採用光復鄉當地特色農產與當季食材。', '欣綠農園、勝利不廢商號、後山白日夢、馬太鞍導覽解說班、行政院農業委員會水土保持局花蓮分局', '花蓮縣 光復鄉大全街60號', '2025-03-16 00:00:00', '2025-05-18 00:00:00', '花蓮縣 光復鄉大全街60號', 23.6578313, 121.4091837, '無資料', 'https://www.facebook.com/fataan.wetland/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081544/5f9446a16e25f02d46d20afece084a518a51b1db.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025光復馬太鞍濕地-螢饗', `description`='活動在螢火蟲出沒期間辦理，在花東最美木棧道的茅草屋中，與馬太鞍來場浪漫螢光晚餐，餐點採用光復鄉當地特色農產與當季食材。', `organizer`='欣綠農園、勝利不廢商號、後山白日夢、馬太鞍導覽解說班、行政院農業委員會水土保持局花蓮分局', `address`='花蓮縣 光復鄉大全街60號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='花蓮縣 光復鄉大全街60號', `latitude`=23.6578313, `longitude`=121.4091837, `ticket_price`='無資料', `source_url`='https://www.facebook.com/fataan.wetland/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081544/5f9446a16e25f02d46d20afece084a518a51b1db.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('834', '南投星空季', '2019年合歡山暗空公園通過國際認證，成為國內首座、亞洲第3座暗空公園，自此之後，每年都會在適合觀星的夏季，舉辦「南投星空季」來推廣南投獨有的觀光亮點，以合歡山為首的知名觀星景點－日月潭、杉林溪、溪頭等地區，透過秘境星空、觀星導覽、野餐晚會等活動，讓「觀星旅遊來南投」將這個口號打響成為大眾皆知的旅遊話題。', '南投縣政府', '南投縣 仁愛鄉清境農場', '2025-05-01 00:00:00', '2025-05-31 00:00:00', '南投縣 仁愛鄉清境農場', 24.05851, 121.16282, '無資料', 'https://www.facebook.com/nantouwelcome', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081509/8565f30c46e6f28eafa2fe3042aa650c1736acbb.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='南投星空季', `description`='2019年合歡山暗空公園通過國際認證，成為國內首座、亞洲第3座暗空公園，自此之後，每年都會在適合觀星的夏季，舉辦「南投星空季」來推廣南投獨有的觀光亮點，以合歡山為首的知名觀星景點－日月潭、杉林溪、溪頭等地區，透過秘境星空、觀星導覽、野餐晚會等活動，讓「觀星旅遊來南投」將這個口號打響成為大眾皆知的旅遊話題。', `organizer`='南投縣政府', `address`='南投縣 仁愛鄉清境農場', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='南投縣 仁愛鄉清境農場', `latitude`=24.05851, `longitude`=121.16282, `ticket_price`='無資料', `source_url`='https://www.facebook.com/nantouwelcome', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081509/8565f30c46e6f28eafa2fe3042aa650c1736acbb.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('837', '鹿港慶端陽系列活動', '緣起於民國67年鹿港民俗才藝活動，以行銷鹿港古蹟、人文、工藝、文化、美食在地特色為活動主軸。活動內容包含「迎龍王」儀式、中部縣市首長邀請賽、國際龍舟錦標賽、童玩技藝、魯班公宴等，促進城市互動與國際交流，展現鹿港鼎盛的文化風格；為讓更多人留宿鹿港，特別打造鹿港慶端陽光影藝術，以結合現代燈光科技，投影在公會堂歷史古蹟建築上，呈現光影交錯的時空對話', '彰化縣政府、鹿港鎮公所、福興鄉公所', '彰化縣 鹿港鎮福鹿溪龍舟會場', '2025-05-01 00:00:00', '2025-06-30 00:00:00', '彰化縣 鹿港鎮福鹿溪龍舟會場', 24.0483807, 120.4292502, '無資料', 'https://lukang-dragonboat.net/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081513/9479a8351aa547a3a0363c032991e8e7def61d0a.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='鹿港慶端陽系列活動', `description`='緣起於民國67年鹿港民俗才藝活動，以行銷鹿港古蹟、人文、工藝、文化、美食在地特色為活動主軸。活動內容包含「迎龍王」儀式、中部縣市首長邀請賽、國際龍舟錦標賽、童玩技藝、魯班公宴等，促進城市互動與國際交流，展現鹿港鼎盛的文化風格；為讓更多人留宿鹿港，特別打造鹿港慶端陽光影藝術，以結合現代燈光科技，投影在公會堂歷史古蹟建築上，呈現光影交錯的時空對話', `organizer`='彰化縣政府、鹿港鎮公所、福興鄉公所', `address`='彰化縣 鹿港鎮福鹿溪龍舟會場', `start_date`='2025-05-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='彰化縣 鹿港鎮福鹿溪龍舟會場', `latitude`=24.0483807, `longitude`=120.4292502, `ticket_price`='無資料', `source_url`='https://lukang-dragonboat.net/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081513/9479a8351aa547a3a0363c032991e8e7def61d0a.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('814', '2025東海岸運動觀光活動', '每年5月辦理的長濱雙浪金剛馬拉松，跑者在晨曦中奔馳在稻穗累累的金剛大道，徜徉於海浪及稻浪交織的東海岸美景奔向太平洋，沿途還有部落居民自組的啦啦隊熱情的為跑者加油打氣，是不可錯過的馬拉松賽事。\r\n秀姑巒溪泛舟鐵人三項是全台唯一不會游泳也能參加的鐵人賽事，除了鐵人比賽項目外，還有純泛舟組提供非鐵人民眾也能報名參賽，體驗泛舟競速的快感。', '交通部觀光署東部海岸國家風景區管理處', '花蓮縣 瑞穗鄉秀姑巒溪遊客中心', '2025-05-01 00:00:00', '2025-06-30 00:00:00', '花蓮縣 瑞穗鄉秀姑巒溪遊客中心', 23.4878928, 121.4010781, '無資料', 'https://www.eastcoast-nsa.gov.tw/zh-tw/event/activitylist/2025/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081471/0149d2fe38455a517d1fdba76d57f6d6d83dc04b.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025東海岸運動觀光活動', `description`='每年5月辦理的長濱雙浪金剛馬拉松，跑者在晨曦中奔馳在稻穗累累的金剛大道，徜徉於海浪及稻浪交織的東海岸美景奔向太平洋，沿途還有部落居民自組的啦啦隊熱情的為跑者加油打氣，是不可錯過的馬拉松賽事。\r\n秀姑巒溪泛舟鐵人三項是全台唯一不會游泳也能參加的鐵人賽事，除了鐵人比賽項目外，還有純泛舟組提供非鐵人民眾也能報名參賽，體驗泛舟競速的快感。', `organizer`='交通部觀光署東部海岸國家風景區管理處', `address`='花蓮縣 瑞穗鄉秀姑巒溪遊客中心', `start_date`='2025-05-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='花蓮縣 瑞穗鄉秀姑巒溪遊客中心', `latitude`=23.4878928, `longitude`=121.4010781, `ticket_price`='無資料', `source_url`='https://www.eastcoast-nsa.gov.tw/zh-tw/event/activitylist/2025/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081471/0149d2fe38455a517d1fdba76d57f6d6d83dc04b.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('811', '觀音觀鷹-樂活行腳系列活動', '(一)觀音觀鷹：配合猛禽過境期間，結合專業賞鷹、賞鳥團體辦理賞鷹生態解說、觀音山生態研討會、生態市集等活動，透過多元面向帶領民眾認識觀音山生態，達到寓教於樂目的。\r\n(二)綠竹筍季活動：綠竹筍素有「觀音山綠寶石」美名，為當地特色農產品，在夏季時節引領民眾上山嚐美食，學做一日農夫，或在樹林裡聆聽觀音山老故事，體驗處處是寶的觀音山深度旅遊。\r\n(三)觀音山登高及文旦柚季活動：秋高季節結合觀音山步道、文旦柚季辦理硬漢嶺尋寶挑戰賽、柚香甜品競賽、步道導覽活動、文旦柚季觀光市集及闖關遊戲。', '交通部觀光署北海岸及觀音山國家風景區管理處', '新北市 五股區觀音山遊客中心', '2025-04-01 00:00:00', '2025-06-30 00:00:00', '新北市 五股區觀音山遊客中心', 25.129446, 121.418201, '無資料', 'https://theme.northguan-nsa.gov.tw/hawkwatching/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081461/708a160edb3d3b37f4f6a9eb66ebc4927c3975b6.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='觀音觀鷹-樂活行腳系列活動', `description`='(一)觀音觀鷹：配合猛禽過境期間，結合專業賞鷹、賞鳥團體辦理賞鷹生態解說、觀音山生態研討會、生態市集等活動，透過多元面向帶領民眾認識觀音山生態，達到寓教於樂目的。\r\n(二)綠竹筍季活動：綠竹筍素有「觀音山綠寶石」美名，為當地特色農產品，在夏季時節引領民眾上山嚐美食，學做一日農夫，或在樹林裡聆聽觀音山老故事，體驗處處是寶的觀音山深度旅遊。\r\n(三)觀音山登高及文旦柚季活動：秋高季節結合觀音山步道、文旦柚季辦理硬漢嶺尋寶挑戰賽、柚香甜品競賽、步道導覽活動、文旦柚季觀光市集及闖關遊戲。', `organizer`='交通部觀光署北海岸及觀音山國家風景區管理處', `address`='新北市 五股區觀音山遊客中心', `start_date`='2025-04-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='新北市 五股區觀音山遊客中心', `latitude`=25.129446, `longitude`=121.418201, `ticket_price`='無資料', `source_url`='https://theme.northguan-nsa.gov.tw/hawkwatching/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081461/708a160edb3d3b37f4f6a9eb66ebc4927c3975b6.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('701', '2024-2025台灣好湯-溫泉美食嘉年華', '時序逐漸進入冬天，也正式宣告臺灣已進入溫泉泡湯旺季！臺灣得天獨厚，擁有冷泉、熱泉、濁泉、海底泉等多樣性泉質，是世界知名的溫泉勝地。「溫泉美食嘉年華」不但讓國內遊客全臺溫泉區泡透透，處處都享優惠，對國際觀光客也是深具魅力，更是帶動秋冬臺灣溫泉旅遊熱潮的年度盛事。\r\n\r\n    <!--臺南關子嶺溫泉美食節\r\n    四重溪溫泉季系列活動\r\n    礁溪溫泉馬拉松\r\n    花蓮太平洋溫泉季-->\r\n\r\n ', '交通部觀光署', '臺北市 北投區新北投溫泉區', '2024-09-14 00:00:00', '2025-06-30 00:00:00', '臺北市 北投區新北投溫泉區', 25.1369429, 121.5026492, '無資料', 'https://taiwanhotspring.net/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081188/9461add1cf93710d7982c3943c2a61a9bf9709e4.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2024-2025台灣好湯-溫泉美食嘉年華', `description`='時序逐漸進入冬天，也正式宣告臺灣已進入溫泉泡湯旺季！臺灣得天獨厚，擁有冷泉、熱泉、濁泉、海底泉等多樣性泉質，是世界知名的溫泉勝地。「溫泉美食嘉年華」不但讓國內遊客全臺溫泉區泡透透，處處都享優惠，對國際觀光客也是深具魅力，更是帶動秋冬臺灣溫泉旅遊熱潮的年度盛事。\r\n\r\n    <!--臺南關子嶺溫泉美食節\r\n    四重溪溫泉季系列活動\r\n    礁溪溫泉馬拉松\r\n    花蓮太平洋溫泉季-->\r\n\r\n ', `organizer`='交通部觀光署', `address`='臺北市 北投區新北投溫泉區', `start_date`='2024-09-14 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='臺北市 北投區新北投溫泉區', `latitude`=25.1369429, `longitude`=121.5026492, `ticket_price`='無資料', `source_url`='https://taiwanhotspring.net/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081188/9461add1cf93710d7982c3943c2a61a9bf9709e4.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('874', '2025 澎湖國際海上花火節', '澎湖國際海上花火節於約在每年5至7月於觀音亭園區及澎湖幾個知名離島舉辦，美麗的煙火與得天獨厚的海灣環境、浪漫的西瀛虹橋相得益彰。除了炫麗煙火外，舞台活動則邀請許多知名藝人及在地表演團體輪番精采演出，遊客可盡情沉沁在悠閒浪漫的氛圍中。', '澎湖縣政府', '澎湖縣 馬公市觀音亭親水遊憩區', '2025-05-05 00:00:00', '2025-07-29 00:00:00', '澎湖縣 馬公市觀音亭親水遊憩區', 23.5686457, 119.562431, '無資料', 'https://www.facebook.com/phfireworks/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081549/21d9267d5df19e987f8ce379745b2a08df10962b.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025 澎湖國際海上花火節', `description`='澎湖國際海上花火節於約在每年5至7月於觀音亭園區及澎湖幾個知名離島舉辦，美麗的煙火與得天獨厚的海灣環境、浪漫的西瀛虹橋相得益彰。除了炫麗煙火外，舞台活動則邀請許多知名藝人及在地表演團體輪番精采演出，遊客可盡情沉沁在悠閒浪漫的氛圍中。', `organizer`='澎湖縣政府', `address`='澎湖縣 馬公市觀音亭親水遊憩區', `start_date`='2025-05-05 00:00:00', `end_date`='2025-07-29 00:00:00', `location`='澎湖縣 馬公市觀音亭親水遊憩區', `latitude`=23.5686457, `longitude`=119.562431, `ticket_price`='無資料', `source_url`='https://www.facebook.com/phfireworks/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081549/21d9267d5df19e987f8ce379745b2a08df10962b.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('854', '南投國姓咖啡節', '自2010年起辦理，活動以1日為主，透過辦理南投縣國姓鄉的年度盛事咖啡節，推廣獲得各項認證與評鑑肯定且品質優良的精品咖啡。', '農業部農村發展及水土保持署 南投分署、南投縣國姓鄉公所、南投縣國姓鄉民代表會、南投縣糯米橋休閒農業區促進協會', '南投縣 國姓鄉國姓鄉福龜村橋聳雲天綠雕園區', '2025-07-01 00:00:00', '2025-07-31 00:00:00', '南投縣 國姓鄉國姓鄉福龜村橋聳雲天綠雕園區', 24.0097453, 120.8137677, '無資料', 'https://www.facebook.com/GuoShingCoffee/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081545/11e3fffa88e918e07238e12ecb3e972b5f717a76.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='南投國姓咖啡節', `description`='自2010年起辦理，活動以1日為主，透過辦理南投縣國姓鄉的年度盛事咖啡節，推廣獲得各項認證與評鑑肯定且品質優良的精品咖啡。', `organizer`='農業部農村發展及水土保持署 南投分署、南投縣國姓鄉公所、南投縣國姓鄉民代表會、南投縣糯米橋休閒農業區促進協會', `address`='南投縣 國姓鄉國姓鄉福龜村橋聳雲天綠雕園區', `start_date`='2025-07-01 00:00:00', `end_date`='2025-07-31 00:00:00', `location`='南投縣 國姓鄉國姓鄉福龜村橋聳雲天綠雕園區', `latitude`=24.0097453, `longitude`=120.8137677, `ticket_price`='無資料', `source_url`='https://www.facebook.com/GuoShingCoffee/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081545/11e3fffa88e918e07238e12ecb3e972b5f717a76.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('863', '野柳石光-夜訪女王', ' \r\n野柳地質公園因獨特地質景觀與優質遊憩品質享譽國際，每年吸引大量國際旅客到訪，更受到國際媒體相繼報導，美國CNN曾譽為媲美太空以及獲選亞洲十大熱門打卡點。\n\r\r\n「野柳石光-夜訪女王」以夜間觀賞奇石地景，營造野柳夜間浪漫光環境為活動主軸，規劃具主題故事之光影互動及特效，搭配日間藝文表演、環境教育、地景保育課程等系列活動。\r\n ', '交通部觀光署北海岸及觀音山國家風景區管理處', '新北市 萬里區野柳地質公園', '2025-06-01 00:00:00', '2025-07-31 00:00:00', '新北市 萬里區野柳地質公園', 25.204757, 121.6896172, '無資料', 'https://www.facebook.com/yehliugeopark/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081564/a5f723efa0ea513c4b9178f577831bda5b3a89fe.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='野柳石光-夜訪女王', `description`=' \r\n野柳地質公園因獨特地質景觀與優質遊憩品質享譽國際，每年吸引大量國際旅客到訪，更受到國際媒體相繼報導，美國CNN曾譽為媲美太空以及獲選亞洲十大熱門打卡點。\n\r\r\n「野柳石光-夜訪女王」以夜間觀賞奇石地景，營造野柳夜間浪漫光環境為活動主軸，規劃具主題故事之光影互動及特效，搭配日間藝文表演、環境教育、地景保育課程等系列活動。\r\n ', `organizer`='交通部觀光署北海岸及觀音山國家風景區管理處', `address`='新北市 萬里區野柳地質公園', `start_date`='2025-06-01 00:00:00', `end_date`='2025-07-31 00:00:00', `location`='新北市 萬里區野柳地質公園', `latitude`=25.204757, `longitude`=121.6896172, `ticket_price`='無資料', `source_url`='https://www.facebook.com/yehliugeopark/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081564/a5f723efa0ea513c4b9178f577831bda5b3a89fe.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('780', '2025花蓮夏戀嘉年華', '花蓮夏戀嘉年華是花蓮一年一度的盛大音樂饗宴，歷年以大型演唱會舞台規格，廣邀國際性巨星與知名歌手登台演出。夏戀嘉年華活動是暑假期間國人熟知且熱愛的節慶活動之一，也是知名巨星歌手、偶像團體的表演殿堂，不但引領整個亞洲流行音樂，更吸引國際友人及愛好流行音樂的朋友們，來到東台灣認識花蓮、愛上花蓮。', '花蓮縣政府觀光處', '花蓮縣 花蓮市2025年活動地點尚未確定', '2025-07-01 00:00:00', '2025-07-31 00:00:00', '花蓮縣 花蓮市2025年活動地點尚未確定', 0, 0, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081401/77d48223a3f49cf57dfe9d43e98b9625d080c6d7.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025花蓮夏戀嘉年華', `description`='花蓮夏戀嘉年華是花蓮一年一度的盛大音樂饗宴，歷年以大型演唱會舞台規格，廣邀國際性巨星與知名歌手登台演出。夏戀嘉年華活動是暑假期間國人熟知且熱愛的節慶活動之一，也是知名巨星歌手、偶像團體的表演殿堂，不但引領整個亞洲流行音樂，更吸引國際友人及愛好流行音樂的朋友們，來到東台灣認識花蓮、愛上花蓮。', `organizer`='花蓮縣政府觀光處', `address`='花蓮縣 花蓮市2025年活動地點尚未確定', `start_date`='2025-07-01 00:00:00', `end_date`='2025-07-31 00:00:00', `location`='花蓮縣 花蓮市2025年活動地點尚未確定', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081401/77d48223a3f49cf57dfe9d43e98b9625d080c6d7.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('823', '2025太平洋南島聯合豐年節', '聯合豐年節結合樂舞展演，呈現原住民族歌謠、舞蹈與文化祭儀的精髓，保存、傳承原住民族文化，並設置特色攤位如原住民特色美食區、手工藝品、農特產品展售區及部落微旅行簡介等，展現花蓮原住民族獨特的文化內涵。', '花蓮縣政府原住民行政處', '花蓮縣 花蓮市達固湖彎大路23號', '2025-07-01 00:00:00', '2025-07-31 00:00:00', '花蓮縣 花蓮市達固湖彎大路23號', 24.005294, 121.583018, '無資料', 'https://www.erv-nsa.gov.tw/zh-tw/event/calendardetail/6720', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081498/9a6c31824a8846e9e5c86567a7fa686a539ee3a2.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025太平洋南島聯合豐年節', `description`='聯合豐年節結合樂舞展演，呈現原住民族歌謠、舞蹈與文化祭儀的精髓，保存、傳承原住民族文化，並設置特色攤位如原住民特色美食區、手工藝品、農特產品展售區及部落微旅行簡介等，展現花蓮原住民族獨特的文化內涵。', `organizer`='花蓮縣政府原住民行政處', `address`='花蓮縣 花蓮市達固湖彎大路23號', `start_date`='2025-07-01 00:00:00', `end_date`='2025-07-31 00:00:00', `location`='花蓮縣 花蓮市達固湖彎大路23號', `latitude`=24.005294, `longitude`=121.583018, `ticket_price`='無資料', `source_url`='https://www.erv-nsa.gov.tw/zh-tw/event/calendardetail/6720', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081498/9a6c31824a8846e9e5c86567a7fa686a539ee3a2.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('824', '羅東藝穗節', '以表演、童趣、踩街、文創、行旅、產業連結六大主軸，帶動羅東文化產業觀光價值。自2002年舉辦，活動為期14天，安排各類藝文活動，結合國內外知名表演團隊展演及踩街。', '宜蘭縣羅東鎮公所', '宜蘭縣 羅東鎮羅東中山公園', '2025-07-01 00:00:00', '2025-07-31 00:00:00', '宜蘭縣 羅東鎮羅東中山公園', 24.676638, 121.769023, '無資料', 'https://www.luodong-fringefestival.tw/index.php#news', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081499/eb70d7c14565331f2b236d9e99a1dfed52b5e291.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='羅東藝穗節', `description`='以表演、童趣、踩街、文創、行旅、產業連結六大主軸，帶動羅東文化產業觀光價值。自2002年舉辦，活動為期14天，安排各類藝文活動，結合國內外知名表演團隊展演及踩街。', `organizer`='宜蘭縣羅東鎮公所', `address`='宜蘭縣 羅東鎮羅東中山公園', `start_date`='2025-07-01 00:00:00', `end_date`='2025-07-31 00:00:00', `location`='宜蘭縣 羅東鎮羅東中山公園', `latitude`=24.676638, `longitude`=121.769023, `ticket_price`='無資料', `source_url`='https://www.luodong-fringefestival.tw/index.php#news', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081499/eb70d7c14565331f2b236d9e99a1dfed52b5e291.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('825', '屏東黑鮪魚文化觀光季', '黑鮪魚季結合在地農漁及觀光產業打造「黑鮪魚文化觀光季在屏東」的國家品牌節慶活動，考量近年升溫之海洋資源枯竭、生態保育等議題，規劃感恩收穫─第一鮪拍賣會、開幕晚會等系列活動，促進當地經濟效益、創造行銷話題。', '屏東縣政府傳播暨國際事務處', '屏東縣 東港鎮東隆宮', '2025-05-01 00:00:00', '2025-07-31 00:00:00', '屏東縣 東港鎮東隆宮', 22.4630654, 120.4488068, '無資料', 'https://www.amazing-pingtung.com/ptcf', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081500/56001b8e0a222e3cfdc7c34db4c6fb0cc1895599.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='屏東黑鮪魚文化觀光季', `description`='黑鮪魚季結合在地農漁及觀光產業打造「黑鮪魚文化觀光季在屏東」的國家品牌節慶活動，考量近年升溫之海洋資源枯竭、生態保育等議題，規劃感恩收穫─第一鮪拍賣會、開幕晚會等系列活動，促進當地經濟效益、創造行銷話題。', `organizer`='屏東縣政府傳播暨國際事務處', `address`='屏東縣 東港鎮東隆宮', `start_date`='2025-05-01 00:00:00', `end_date`='2025-07-31 00:00:00', `location`='屏東縣 東港鎮東隆宮', `latitude`=22.4630654, `longitude`=120.4488068, `ticket_price`='無資料', `source_url`='https://www.amazing-pingtung.com/ptcf', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081500/56001b8e0a222e3cfdc7c34db4c6fb0cc1895599.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('832', '東石海之夏', '為嘉義縣暑期濱海觀光指標性活動，以濱海觀光與歡樂親子遊為主題，包含流行音樂會、特色產業DIY、親子活動等，結合外傘頂洲踏浪、吃海鮮觀海景之獨特濱海遊程，持續帶動嘉義沿海東石、布袋相關產業觀光收益。', '嘉義縣政府文化觀光局、交通部觀光署雲嘉南濱海國家風景區管理處', '嘉義縣 東石鄉東石漁人碼頭', '2025-07-01 00:00:00', '2025-07-31 00:00:00', '嘉義縣 東石鄉東石漁人碼頭', 23.449047, 120.1350677, '無資料', 'https://www.facebook.com/2014dshot/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081507/e01779566d37f97f3086c96e5e38e1d5e6252192.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='東石海之夏', `description`='為嘉義縣暑期濱海觀光指標性活動，以濱海觀光與歡樂親子遊為主題，包含流行音樂會、特色產業DIY、親子活動等，結合外傘頂洲踏浪、吃海鮮觀海景之獨特濱海遊程，持續帶動嘉義沿海東石、布袋相關產業觀光收益。', `organizer`='嘉義縣政府文化觀光局、交通部觀光署雲嘉南濱海國家風景區管理處', `address`='嘉義縣 東石鄉東石漁人碼頭', `start_date`='2025-07-01 00:00:00', `end_date`='2025-07-31 00:00:00', `location`='嘉義縣 東石鄉東石漁人碼頭', `latitude`=23.449047, `longitude`=120.1350677, `ticket_price`='無資料', `source_url`='https://www.facebook.com/2014dshot/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081507/e01779566d37f97f3086c96e5e38e1d5e6252192.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('864', '2025台灣美食展', '台灣美食展以食藝文化結合名廚料理、各地特產食材結合成在地美食，風格愈來愈多樣，除了色香味美的菜色，也有動態十足的廚藝競賽，遠從各國慕名參賽的名廚，讓美食展更國際化。', '財團法人台灣觀光協會', '臺北市 信義區台北世界貿易中心展覽一館', '2025-08-01 00:00:00', '2025-08-04 00:00:00', '臺北市 信義區台北世界貿易中心展覽一館', 25.033155, 121.562347, '無資料', 'https://www.tcetva.tw/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081571/86058b72587912c0326acd513d1764096ad42fd3.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣美食展', `description`='台灣美食展以食藝文化結合名廚料理、各地特產食材結合成在地美食，風格愈來愈多樣，除了色香味美的菜色，也有動態十足的廚藝競賽，遠從各國慕名參賽的名廚，讓美食展更國際化。', `organizer`='財團法人台灣觀光協會', `address`='臺北市 信義區台北世界貿易中心展覽一館', `start_date`='2025-08-01 00:00:00', `end_date`='2025-08-04 00:00:00', `location`='臺北市 信義區台北世界貿易中心展覽一館', `latitude`=25.033155, `longitude`=121.562347, `ticket_price`='無資料', `source_url`='https://www.tcetva.tw/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081571/86058b72587912c0326acd513d1764096ad42fd3.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('852', '臺灣文化創意設計博覽會', '臺灣文化創意博覽會自99年起首辦，以策展呈現當代文化趨勢，以商展打造文創商品與圖像授權交易平臺，經過逾10年的耕耘，已為臺灣最具規模的國際性文創展會。', '文化部', '臺北市 南港區南港展覽館', '2025-08-07 00:00:00', '2025-08-13 00:00:00', '臺北市 南港區南港展覽館', 25.05663967, 121.61812042, '無資料', 'https://www.moc.gov.tw/News_Content2.aspx?n=105&s=223220', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081543/9810a4e354c75017738a2da318a439542b324e51.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='臺灣文化創意設計博覽會', `description`='臺灣文化創意博覽會自99年起首辦，以策展呈現當代文化趨勢，以商展打造文創商品與圖像授權交易平臺，經過逾10年的耕耘，已為臺灣最具規模的國際性文創展會。', `organizer`='文化部', `address`='臺北市 南港區南港展覽館', `start_date`='2025-08-07 00:00:00', `end_date`='2025-08-13 00:00:00', `location`='臺北市 南港區南港展覽館', `latitude`=25.05663967, `longitude`=121.61812042, `ticket_price`='無資料', `source_url`='https://www.moc.gov.tw/News_Content2.aspx?n=105&s=223220', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081543/9810a4e354c75017738a2da318a439542b324e51.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('799', '2025臺灣國際熱氣球嘉年華', ' \r\n臺灣國際熱氣球嘉年華於每年暑假熱鬧登場，已經成為最令人期待的夏日盛宴之一，2018年更獲知名旅遊頻道(Travel Channel)入選世界12處令人驚豔的熱氣球節之一。\r\n ', '臺東縣政府', '臺東縣 鹿野鄉鹿野高台', '2025-07-05 00:00:00', '2025-08-21 00:00:00', '臺東縣 鹿野鄉鹿野高台', 22.926726, 121.126734, '無資料', 'https://balloontaiwan.taitung.gov.tw/zh-tw', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081433/6a61dad1fd059ad4b1c2cd192656723da66f673f.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺灣國際熱氣球嘉年華', `description`=' \r\n臺灣國際熱氣球嘉年華於每年暑假熱鬧登場，已經成為最令人期待的夏日盛宴之一，2018年更獲知名旅遊頻道(Travel Channel)入選世界12處令人驚豔的熱氣球節之一。\r\n ', `organizer`='臺東縣政府', `address`='臺東縣 鹿野鄉鹿野高台', `start_date`='2025-07-05 00:00:00', `end_date`='2025-08-21 00:00:00', `location`='臺東縣 鹿野鄉鹿野高台', `latitude`=22.926726, `longitude`=121.126734, `ticket_price`='無資料', `source_url`='https://balloontaiwan.taitung.gov.tw/zh-tw', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081433/6a61dad1fd059ad4b1c2cd192656723da66f673f.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('813', '縱谷原遊會 部落食樂園', '結合在地部落體驗及行銷花東縱谷原住民多元美食為主體的活動，亦為全國首創且規模最大部落食物體驗樂園。活動集結超過20個原住民部落齊聚一堂，邀請花東縱谷地區包括阿美族、布農族、賽德克族、太魯閣和卑南族等原住民族群共同推出山野獵場 、mumu廚房、美學家屋、限定野宴、山谷舞台及選品市集等特色主題區場域。', '交通部觀光署花東縱谷國家風景區管理處', '花蓮縣 富里鄉羅山遊客中心', '2025-08-01 00:00:00', '2025-08-31 00:00:00', '花蓮縣 富里鄉羅山遊客中心', 23.2020702, 121.2749417, '無資料', 'https://www.facebook.com/erv.festival/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081465/154128d3890b62c5fa5ce9c29dfbed546ba233a9.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='縱谷原遊會 部落食樂園', `description`='結合在地部落體驗及行銷花東縱谷原住民多元美食為主體的活動，亦為全國首創且規模最大部落食物體驗樂園。活動集結超過20個原住民部落齊聚一堂，邀請花東縱谷地區包括阿美族、布農族、賽德克族、太魯閣和卑南族等原住民族群共同推出山野獵場 、mumu廚房、美學家屋、限定野宴、山谷舞台及選品市集等特色主題區場域。', `organizer`='交通部觀光署花東縱谷國家風景區管理處', `address`='花蓮縣 富里鄉羅山遊客中心', `start_date`='2025-08-01 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='花蓮縣 富里鄉羅山遊客中心', `latitude`=23.2020702, `longitude`=121.2749417, `ticket_price`='無資料', `source_url`='https://www.facebook.com/erv.festival/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081465/154128d3890b62c5fa5ce9c29dfbed546ba233a9.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('816', '2025東引軍事越野障礙賽', '東引軍事越野障礙賽為全台唯一，以軍事主題推行之路跑活動，以「運動嘉年華會」的行事作為主軸，賽場橫跨東引各大觀光景點，打造成全台獨家的軍事越野障礙賽，也是馬祖四鄉五島當中最具有特色的活動之一。', '連江縣東引鄉公所', '連江縣 東引鄉忠誠門', '2025-08-01 00:00:00', '2025-08-31 00:00:00', '連江縣 東引鄉忠誠門', 45.2065094, 1.5155574, '無資料', 'https://www.facebook.com/p/%E6%9D%B1%E5%BC%95%E8%BB%8D%E4%BA%8B%E8%B6%8A%E9%87%8E%E9%9A%9C%E7%A4%99%E8%B3%BD-100089916847940/?_rdr', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081473/a505c16c8c207ad84c0aa61682066e0da93ef574.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025東引軍事越野障礙賽', `description`='東引軍事越野障礙賽為全台唯一，以軍事主題推行之路跑活動，以「運動嘉年華會」的行事作為主軸，賽場橫跨東引各大觀光景點，打造成全台獨家的軍事越野障礙賽，也是馬祖四鄉五島當中最具有特色的活動之一。', `organizer`='連江縣東引鄉公所', `address`='連江縣 東引鄉忠誠門', `start_date`='2025-08-01 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='連江縣 東引鄉忠誠門', `latitude`=45.2065094, `longitude`=1.5155574, `ticket_price`='無資料', `source_url`='https://www.facebook.com/p/%E6%9D%B1%E5%BC%95%E8%BB%8D%E4%BA%8B%E8%B6%8A%E9%87%8E%E9%9A%9C%E7%A4%99%E8%B3%BD-100089916847940/?_rdr', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081473/a505c16c8c207ad84c0aa61682066e0da93ef574.jpg"]';
