INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('846', '基隆潮境海灣節', '2015至2017年由國立海洋科技博物館辦理三屆「Aquatopia渥托邦-海洋狂想」海洋生活博覽會系列活動，每年吸引上萬人次參加，2018年起由基隆市政府接繼辦理相關海灣體驗活動，並與產官學研相關單位合作，推出五大「潮」活動，舉凡海灣可發展之海洋運動、生態旅遊、海洋工作假期、漁村活絡、海底影像紀錄、海洋音樂、美食等，規劃寓教於樂的海洋體驗活動，吸引大眾走進基隆的海洋場域。', '基隆市政府', '基隆市 中正區碧砂漁港', '2025-06-01 00:00:00', '2025-08-31 00:00:00', '基隆市 中正區碧砂漁港', 25.147141, 121.78629, '無資料', 'https://www.chaojingbay.com.tw/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081537/839b0a6916108b9861af53bae355a17b033dbc68.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='基隆潮境海灣節', `description`='2015至2017年由國立海洋科技博物館辦理三屆「Aquatopia渥托邦-海洋狂想」海洋生活博覽會系列活動，每年吸引上萬人次參加，2018年起由基隆市政府接繼辦理相關海灣體驗活動，並與產官學研相關單位合作，推出五大「潮」活動，舉凡海灣可發展之海洋運動、生態旅遊、海洋工作假期、漁村活絡、海底影像紀錄、海洋音樂、美食等，規劃寓教於樂的海洋體驗活動，吸引大眾走進基隆的海洋場域。', `organizer`='基隆市政府', `address`='基隆市 中正區碧砂漁港', `start_date`='2025-06-01 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='基隆市 中正區碧砂漁港', `latitude`=25.147141, `longitude`=121.78629, `ticket_price`='無資料', `source_url`='https://www.chaojingbay.com.tw/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081537/839b0a6916108b9861af53bae355a17b033dbc68.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('839', '義魄千秋-全國義民祭在新竹縣', '新埔褒忠亭（義民廟）是北臺灣客家人的信仰中心，也是新竹縣的縣定古蹟，創建至今已超過230年。褒忠亭義民祭典的十五聯庄輪值的歷史至少可以追溯至西元1835年，迄今亦超過180年，是客家族群第一項榮獲文化部指定的國家重要民俗，也由客委會列為「客庄12大節慶」之一。新埔褒忠亭兼具「有形」與「無形」兩項文化資產身份，不但是客家文化傳承的重要資產，也是我國文化豐富多元與多樣化的具體展現。\r\n義民祭之所以受到客家鄉親甚至全國的關注，主要是傳承220餘年來的文化祭典，係由新竹縣、市、桃園市等3縣市、20鄉鎮市區組成15大聯庄祭典區輪值主辦，維持嚴謹的經營管理制度，不斷投入民間資源，完整保存傳統輪值制度與祭儀，充分展現了民間自發力量與社群凝聚力。今日，新竹縣褒忠亭的分香廟宇遍佈全臺，義民信仰地位屹立不搖。\r\n ', '新竹縣政府、財團法人台灣省新竹縣褒忠亭、新埔聯庄輪值祭典區', '新竹縣 新埔鎮新埔枋寮義民廟', '2025-08-01 00:00:00', '2025-08-31 00:00:00', '新竹縣 新埔鎮新埔枋寮義民廟', 24.8442494, 121.0363907, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081521/453c51592ce64b9cdfaaca5f515ac619392ed8a2.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='義魄千秋-全國義民祭在新竹縣', `description`='新埔褒忠亭（義民廟）是北臺灣客家人的信仰中心，也是新竹縣的縣定古蹟，創建至今已超過230年。褒忠亭義民祭典的十五聯庄輪值的歷史至少可以追溯至西元1835年，迄今亦超過180年，是客家族群第一項榮獲文化部指定的國家重要民俗，也由客委會列為「客庄12大節慶」之一。新埔褒忠亭兼具「有形」與「無形」兩項文化資產身份，不但是客家文化傳承的重要資產，也是我國文化豐富多元與多樣化的具體展現。\r\n義民祭之所以受到客家鄉親甚至全國的關注，主要是傳承220餘年來的文化祭典，係由新竹縣、市、桃園市等3縣市、20鄉鎮市區組成15大聯庄祭典區輪值主辦，維持嚴謹的經營管理制度，不斷投入民間資源，完整保存傳統輪值制度與祭儀，充分展現了民間自發力量與社群凝聚力。今日，新竹縣褒忠亭的分香廟宇遍佈全臺，義民信仰地位屹立不搖。\r\n ', `organizer`='新竹縣政府、財團法人台灣省新竹縣褒忠亭、新埔聯庄輪值祭典區', `address`='新竹縣 新埔鎮新埔枋寮義民廟', `start_date`='2025-08-01 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='新竹縣 新埔鎮新埔枋寮義民廟', `latitude`=24.8442494, `longitude`=121.0363907, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081521/453c51592ce64b9cdfaaca5f515ac619392ed8a2.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('779', '2025花蓮紅面鴨FUN暑假', '運用鯉魚潭特有景觀，以花蓮觀光吉祥物展出，白天遊客可以在鯉魚潭悠遊的享受湖光山色，夜晚欣賞燈光水舞表演，為全台最大型水舞表演。\r\n', '花蓮縣政府觀光處', '花蓮縣 壽豐鄉鯉魚潭', '2025-07-01 00:00:00', '2025-08-31 00:00:00', '花蓮縣 壽豐鄉鯉魚潭', 23.9278268, 121.5098787, '無資料', 'https://www.erv-nsa.gov.tw/zh-tw/event/calendardetail/6719', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081400/c93ab7596b14d04c199b6f171a50953255c0dae0.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025花蓮紅面鴨FUN暑假', `description`='運用鯉魚潭特有景觀，以花蓮觀光吉祥物展出，白天遊客可以在鯉魚潭悠遊的享受湖光山色，夜晚欣賞燈光水舞表演，為全台最大型水舞表演。\r\n', `organizer`='花蓮縣政府觀光處', `address`='花蓮縣 壽豐鄉鯉魚潭', `start_date`='2025-07-01 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='花蓮縣 壽豐鄉鯉魚潭', `latitude`=23.9278268, `longitude`=121.5098787, `ticket_price`='無資料', `source_url`='https://www.erv-nsa.gov.tw/zh-tw/event/calendardetail/6719', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081400/c93ab7596b14d04c199b6f171a50953255c0dae0.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('785', '2025宜蘭國際童玩藝術節', '創辦於1996年的宜蘭國際童玩藝術節，以展覽、演出、遊戲、交流為四大訴求，是亞洲第一個以「兒童」為主題，獲得「國際民俗藝術節協會」( CIOFF&reg; )認證之民俗藝術節。', '宜蘭縣政府', '宜蘭縣 五結鄉親河路二段2號', '2025-07-01 00:00:00', '2025-08-31 00:00:00', '宜蘭縣 五結鄉親河路二段2號', 24.6729935, 121.8158161, '無資料', 'https://www.yicfff.tw/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081412/84a78e00cd3e930b527619baed1dc5d034669a16.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025宜蘭國際童玩藝術節', `description`='創辦於1996年的宜蘭國際童玩藝術節，以展覽、演出、遊戲、交流為四大訴求，是亞洲第一個以「兒童」為主題，獲得「國際民俗藝術節協會」( CIOFF&reg; )認證之民俗藝術節。', `organizer`='宜蘭縣政府', `address`='宜蘭縣 五結鄉親河路二段2號', `start_date`='2025-07-01 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='宜蘭縣 五結鄉親河路二段2號', `latitude`=24.6729935, `longitude`=121.8158161, `ticket_price`='無資料', `source_url`='https://www.yicfff.tw/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081412/84a78e00cd3e930b527619baed1dc5d034669a16.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('790', '臺東最美星空系列活動', '活動場次請以官網公告為主\r\n臺東最美星空系列活動整體區分為三部份，分別為導遊培訓、導覽活動和最美星空音樂會。由於臺東地域地廣人稀，即使交通比之西部來的不便，卻因此保留西部所沒有的天然環境，低汙染、低噪音、沒有高樓大廈的遮蔽，沒有嚴重的光害跟PM2.5，與西部相較之下，觀賞星星容易許多，觀星的地方多不勝數。搭配星空音樂會、導覽解說及相關星空活動，不僅提升遊客或民眾對天文的知識及興趣，也能增加民眾對星空的熟悉度。', '臺東縣政府', '臺東縣 關山鎮2025年活動地點尚未確定', '2025-06-01 00:00:00', '2025-08-31 00:00:00', '臺東縣 關山鎮2025年活動地點尚未確定', 22.95524403, 121.2902952, '無資料', 'https://www.facebook.com/StarryTaitung', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081420/88a8643c64547a319f130720671a61300993558a.jpeg"]') ON DUPLICATE KEY UPDATE `activity_name`='臺東最美星空系列活動', `description`='活動場次請以官網公告為主\r\n臺東最美星空系列活動整體區分為三部份，分別為導遊培訓、導覽活動和最美星空音樂會。由於臺東地域地廣人稀，即使交通比之西部來的不便，卻因此保留西部所沒有的天然環境，低汙染、低噪音、沒有高樓大廈的遮蔽，沒有嚴重的光害跟PM2.5，與西部相較之下，觀賞星星容易許多，觀星的地方多不勝數。搭配星空音樂會、導覽解說及相關星空活動，不僅提升遊客或民眾對天文的知識及興趣，也能增加民眾對星空的熟悉度。', `organizer`='臺東縣政府', `address`='臺東縣 關山鎮2025年活動地點尚未確定', `start_date`='2025-06-01 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='臺東縣 關山鎮2025年活動地點尚未確定', `latitude`=22.95524403, `longitude`=121.2902952, `ticket_price`='無資料', `source_url`='https://www.facebook.com/StarryTaitung', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081420/88a8643c64547a319f130720671a61300993558a.jpeg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('865', '台灣仲夏節', '「台灣仲夏節Solar Festival in TAIWAN 」為交通部觀光署夏季主題活動，整合南台灣國家風景區管理處及各縣市夏季特色旅遊活動，並與產業跨界結盟合作，形塑夏季觀光活動新品牌，讓國內外遊客感受南台灣夏季旅遊新魅力。\r\n\r\n    新竹市國際風箏節\r\n', '交通部觀光署', '臺南市 將軍區馬沙溝濱海遊憩區', '2025-06-01 00:00:00', '2025-09-01 00:00:00', '臺南市 將軍區馬沙溝濱海遊憩區', 23.2166014, 120.0837121, '無資料', 'https://summerfestival.taiwan.net.tw/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081575/79505b5d6b34dd6cf6b0818337da03dcbb07d3a1.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='台灣仲夏節', `description`='「台灣仲夏節Solar Festival in TAIWAN 」為交通部觀光署夏季主題活動，整合南台灣國家風景區管理處及各縣市夏季特色旅遊活動，並與產業跨界結盟合作，形塑夏季觀光活動新品牌，讓國內外遊客感受南台灣夏季旅遊新魅力。\r\n\r\n    新竹市國際風箏節\r\n', `organizer`='交通部觀光署', `address`='臺南市 將軍區馬沙溝濱海遊憩區', `start_date`='2025-06-01 00:00:00', `end_date`='2025-09-01 00:00:00', `location`='臺南市 將軍區馬沙溝濱海遊憩區', `latitude`=23.2166014, `longitude`=120.0837121, `ticket_price`='無資料', `source_url`='https://summerfestival.taiwan.net.tw/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081575/79505b5d6b34dd6cf6b0818337da03dcbb07d3a1.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('875', '2025東海岸大地藝術節暨月光・海音樂會', '東海岸大地藝術節(TECLandArt Festival)是交通部觀光署東部海岸國家風景管理處於2015年開始委託專業承辦，以東海岸原始生活方式結合動態靜態兼具的藝術氛圍，邀請藝術團隊、藝術工作者打造轄區內優質的觀光活動。', '交通部觀光署東部海岸國家風景區管理處', '臺東縣 成功鎮信義里新村路25號', '2025-06-21 00:00:00', '2025-09-09 00:00:00', '臺東縣 成功鎮信義里新村路25號', 23.0203465, 121.3249613, '無資料', 'https://www.eastcoast-nsa.gov.tw/zh-tw/event/activity/5624/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081553/55830079aae809aebac0ddcb48e0b26e8ff670b0.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025東海岸大地藝術節暨月光・海音樂會', `description`='東海岸大地藝術節(TECLandArt Festival)是交通部觀光署東部海岸國家風景管理處於2015年開始委託專業承辦，以東海岸原始生活方式結合動態靜態兼具的藝術氛圍，邀請藝術團隊、藝術工作者打造轄區內優質的觀光活動。', `organizer`='交通部觀光署東部海岸國家風景區管理處', `address`='臺東縣 成功鎮信義里新村路25號', `start_date`='2025-06-21 00:00:00', `end_date`='2025-09-09 00:00:00', `location`='臺東縣 成功鎮信義里新村路25號', `latitude`=23.0203465, `longitude`=121.3249613, `ticket_price`='無資料', `source_url`='https://www.eastcoast-nsa.gov.tw/zh-tw/event/activity/5624/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081553/55830079aae809aebac0ddcb48e0b26e8ff670b0.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('753', '綠島人權藝術季', '自2019年起辦理，為期約4個月，以當代藝術展覽性質舉辦《綠島人權藝術季》，每兩年辦理一次，邀請約20組國內外藝術家參展，透過當代藝術的多元呈現形式及結合跨領域媒材，傳遞人權價值理念。', '國家人權博物館', '臺東縣 綠島鄉20號', '2025-05-17 00:00:00', '2025-09-21 00:00:00', '臺東縣 綠島鄉20號', 22.6755208, 121.4943739, '無資料', 'https://www.nhrm.gov.tw/w/nhrm/News_24111815365642501', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081342/3e3536b85a74d045114cd99d700106d9d0129904.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='綠島人權藝術季', `description`='自2019年起辦理，為期約4個月，以當代藝術展覽性質舉辦《綠島人權藝術季》，每兩年辦理一次，邀請約20組國內外藝術家參展，透過當代藝術的多元呈現形式及結合跨領域媒材，傳遞人權價值理念。', `organizer`='國家人權博物館', `address`='臺東縣 綠島鄉20號', `start_date`='2025-05-17 00:00:00', `end_date`='2025-09-21 00:00:00', `location`='臺東縣 綠島鄉20號', `latitude`=22.6755208, `longitude`=121.4943739, `ticket_price`='無資料', `source_url`='https://www.nhrm.gov.tw/w/nhrm/News_24111815365642501', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081342/3e3536b85a74d045114cd99d700106d9d0129904.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('783', '2025鷄籠中元祭', '雞籠中元祭起源於西元1855年，為臺灣規模最大的中元祭典，不僅是臺灣歷史最悠久的民俗祭典之一，也是第一個被指定為「重要民俗」類國家文化資產的節慶，辦理時間長達1個月。\r\n ', '基隆市政府', '基隆市 安樂區老大公廟', '2025-08-22 00:00:00', '2025-09-22 00:00:00', '基隆市 安樂區老大公廟', 25.1290706, 121.7331009, '無資料', 'https://www.klccab.gov.tw/CulturalFestival/Details/0e51aca0-c8db-4221-b01f-0d1745f58a28?itemId=a8de7aa5-d437-49e8-9907-c01142b9ce82&firstpage=1&secondPage=1', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081404/afcb2315df4c7732737c0f9bde3299f512116f3b.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025鷄籠中元祭', `description`='雞籠中元祭起源於西元1855年，為臺灣規模最大的中元祭典，不僅是臺灣歷史最悠久的民俗祭典之一，也是第一個被指定為「重要民俗」類國家文化資產的節慶，辦理時間長達1個月。\r\n ', `organizer`='基隆市政府', `address`='基隆市 安樂區老大公廟', `start_date`='2025-08-22 00:00:00', `end_date`='2025-09-22 00:00:00', `location`='基隆市 安樂區老大公廟', `latitude`=25.1290706, `longitude`=121.7331009, `ticket_price`='無資料', `source_url`='https://www.klccab.gov.tw/CulturalFestival/Details/0e51aca0-c8db-4221-b01f-0d1745f58a28?itemId=a8de7aa5-d437-49e8-9907-c01142b9ce82&firstpage=1&secondPage=1', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081404/afcb2315df4c7732737c0f9bde3299f512116f3b.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('778', '臺中國際踩舞嘉年華', '「臺中國際踩舞嘉年華」藉由舞蹈表演之推廣，結合節慶活動，建立運動觀光與藝術文化交流平臺，表演團體包含國內外知名踩街舞蹈隊伍、傳統文化民俗舞蹈團體、流行音樂舞蹈團體、街舞、國標舞、現代舞等，並擴 大邀請亞洲地區包含日本、韓國、東南亞諸國、港澳大陸地區等國家專業舞蹈表演團體，體現「嘉年華」狂歡慶祝之意。', '臺中市政府觀光旅遊局', '臺中市 西區臺中市民廣場', '2025-09-01 00:00:00', '2025-09-30 00:00:00', '臺中市 西區臺中市民廣場', 24.1500276, 120.66346914, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081399/cb17749cb32dd9a48178beb19add4d23048cc75d.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='臺中國際踩舞嘉年華', `description`='「臺中國際踩舞嘉年華」藉由舞蹈表演之推廣，結合節慶活動，建立運動觀光與藝術文化交流平臺，表演團體包含國內外知名踩街舞蹈隊伍、傳統文化民俗舞蹈團體、流行音樂舞蹈團體、街舞、國標舞、現代舞等，並擴 大邀請亞洲地區包含日本、韓國、東南亞諸國、港澳大陸地區等國家專業舞蹈表演團體，體現「嘉年華」狂歡慶祝之意。', `organizer`='臺中市政府觀光旅遊局', `address`='臺中市 西區臺中市民廣場', `start_date`='2025-09-01 00:00:00', `end_date`='2025-09-30 00:00:00', `location`='臺中市 西區臺中市民廣場', `latitude`=24.1500276, `longitude`=120.66346914, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081399/cb17749cb32dd9a48178beb19add4d23048cc75d.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('810', '2025島嶼生活節', '和平島為北台灣最早躍進世界舞台的島嶼，從最早的平埔族原住民、西班牙人、荷蘭人後來的琉球王國人、日本人、福州人等，這塊土地有著豐厚的故事，但隨著時間流動，這些文化歷史及過去的美好友誼逐漸被遺忘，和平島公園使用音樂、美食、藝術創作等來包裝文化、歷史等對於一般遊客來說較為生硬的議題。一年一度提供回憶重塑的有趣活動，邀請曾經在這片土地生活的各國人們，一起在這場無國界的美學派對中發掘更多美好生活，在這裡展演過去、現在、未來我們共享的生活樣貌。\r\n島嶼生活節打破疆界，台灣的在地文化就是經由這幾百年來不同國家文化的揉合、衝突、再轉化，在島嶼生活節不只做跨域跨國際合作、更希望讓那條國家間的界線變得透明，並且讓台灣創作者能在這裡被看見，醞釀更豐富的「台灣永續活動品牌」的能量！', '交通部觀光署北海岸及觀音山國家風景區管理處', '基隆市 中正區和平島公園', '2025-09-01 00:00:00', '2025-09-30 00:00:00', '基隆市 中正區和平島公園', 25.160629, 121.76384, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081460/0cbbfad466cd178177ef27fb1d885da9a32894dd.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025島嶼生活節', `description`='和平島為北台灣最早躍進世界舞台的島嶼，從最早的平埔族原住民、西班牙人、荷蘭人後來的琉球王國人、日本人、福州人等，這塊土地有著豐厚的故事，但隨著時間流動，這些文化歷史及過去的美好友誼逐漸被遺忘，和平島公園使用音樂、美食、藝術創作等來包裝文化、歷史等對於一般遊客來說較為生硬的議題。一年一度提供回憶重塑的有趣活動，邀請曾經在這片土地生活的各國人們，一起在這場無國界的美學派對中發掘更多美好生活，在這裡展演過去、現在、未來我們共享的生活樣貌。\r\n島嶼生活節打破疆界，台灣的在地文化就是經由這幾百年來不同國家文化的揉合、衝突、再轉化，在島嶼生活節不只做跨域跨國際合作、更希望讓那條國家間的界線變得透明，並且讓台灣創作者能在這裡被看見，醞釀更豐富的「台灣永續活動品牌」的能量！', `organizer`='交通部觀光署北海岸及觀音山國家風景區管理處', `address`='基隆市 中正區和平島公園', `start_date`='2025-09-01 00:00:00', `end_date`='2025-09-30 00:00:00', `location`='基隆市 中正區和平島公園', `latitude`=25.160629, `longitude`=121.76384, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081460/0cbbfad466cd178177ef27fb1d885da9a32894dd.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('840', '桃園地景藝術節', '地景藝術節與歐洲文化首都(ECC)的移動策略概念相近，藉由「移動」的特性，喚起地方意識。地景藝術節每年擇定不同展區，藉由藝術節翻轉空間、提升公共建設、擾動社區社群，重新認識桃園每一處地方，也藉由市府及民間資源的投入，讓各區域再次被大家認識。\r\n  ', '桃園市政府文化局', '桃園市2025年活動地點尚未確定', '2025-09-01 00:00:00', '2025-09-30 00:00:00', '桃園市2025年活動地點尚未確定', 0, 0, '無資料', 'https://www.facebook.com/TaoyuanLandArt/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081522/118602996577bb2c6e3b95bcdb1a77f4f055912f.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='桃園地景藝術節', `description`='地景藝術節與歐洲文化首都(ECC)的移動策略概念相近，藉由「移動」的特性，喚起地方意識。地景藝術節每年擇定不同展區，藉由藝術節翻轉空間、提升公共建設、擾動社區社群，重新認識桃園每一處地方，也藉由市府及民間資源的投入，讓各區域再次被大家認識。\r\n  ', `organizer`='桃園市政府文化局', `address`='桃園市2025年活動地點尚未確定', `start_date`='2025-09-01 00:00:00', `end_date`='2025-09-30 00:00:00', `location`='桃園市2025年活動地點尚未確定', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.facebook.com/TaoyuanLandArt/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081522/118602996577bb2c6e3b95bcdb1a77f4f055912f.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('835', '日月潭國際萬人泳渡', '起始於民國72年（西元1983年）的日月潭國際萬人泳渡活動，1995年獲得國際奧林匹克委員會認證，2002年正式列入世界游泳名人堂；自行車環島、登玉山與橫渡日月潭，被稱為是台灣人應該要完成的壯舉。\r\n', '南投縣政府、中華民國成人游泳協會、埔里鎮四季早泳會', '南投縣 魚池鄉日月潭', '2025-09-01 00:00:00', '2025-09-30 00:00:00', '南投縣 魚池鄉日月潭', 23.8573342, 120.9159131, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081511/135935d714258af9509377b745af2a833c466113.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='日月潭國際萬人泳渡', `description`='起始於民國72年（西元1983年）的日月潭國際萬人泳渡活動，1995年獲得國際奧林匹克委員會認證，2002年正式列入世界游泳名人堂；自行車環島、登玉山與橫渡日月潭，被稱為是台灣人應該要完成的壯舉。\r\n', `organizer`='南投縣政府、中華民國成人游泳協會、埔里鎮四季早泳會', `address`='南投縣 魚池鄉日月潭', `start_date`='2025-09-01 00:00:00', `end_date`='2025-09-30 00:00:00', `location`='南投縣 魚池鄉日月潭', `latitude`=23.8573342, `longitude`=120.9159131, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081511/135935d714258af9509377b745af2a833c466113.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('829', '城隍夜巡夯枷解厄', '國定古蹟嘉義城隍廟城隍夜巡夯枷解厄活動涵蓋有近百年歷史的嘉義城隍中元祭，炸寒單庇佑信眾平安等，今年嘉義城隍夜巡，推出的創新活動之一，與在地劇團阮劇團合作，將民眾口中有關嘉義城隍中元祭的靈異傳奇，用微電影模式製作成短片，除此以外還邀請兩岸三地城隍爺及民眾參加，如金門的公背婆、打花草、及大陸新加坡的大爺二爺等，使本活動兼具國際性、獨特性和永續性。\r\n', '財團法人台灣省嘉義市城隍廟', '嘉義市 東區吳鳳北路168號', '2025-09-01 00:00:00', '2025-09-30 00:00:00', '嘉義市 東區吳鳳北路168號', 23.4783899, 120.454027, '無資料', 'https://www.facebook.com/ChiayiChenghuangTemple/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081504/6ecc30e471d514ba133eaad5d6911bbc4b2b99a5.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='城隍夜巡夯枷解厄', `description`='國定古蹟嘉義城隍廟城隍夜巡夯枷解厄活動涵蓋有近百年歷史的嘉義城隍中元祭，炸寒單庇佑信眾平安等，今年嘉義城隍夜巡，推出的創新活動之一，與在地劇團阮劇團合作，將民眾口中有關嘉義城隍中元祭的靈異傳奇，用微電影模式製作成短片，除此以外還邀請兩岸三地城隍爺及民眾參加，如金門的公背婆、打花草、及大陸新加坡的大爺二爺等，使本活動兼具國際性、獨特性和永續性。\r\n', `organizer`='財團法人台灣省嘉義市城隍廟', `address`='嘉義市 東區吳鳳北路168號', `start_date`='2025-09-01 00:00:00', `end_date`='2025-09-30 00:00:00', `location`='嘉義市 東區吳鳳北路168號', `latitude`=23.4783899, `longitude`=120.454027, `ticket_price`='無資料', `source_url`='https://www.facebook.com/ChiayiChenghuangTemple/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081504/6ecc30e471d514ba133eaad5d6911bbc4b2b99a5.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('830', '嘉義市光織影舞-光影藝術展', '結合嘉義市特色及文化，以四季與中秋節為主題，設置8件光影藝術裝置，搭配表演活動，吸引旅客來嘉義市駐留體驗。\r\n\r\n    嘉義市國際藝術紀錄影展\r\n\r\n ', '嘉義市政府', '嘉義市 西區北香湖公園', '2025-09-01 00:00:00', '2025-09-30 00:00:00', '嘉義市 西區北香湖公園', 23.4920481, 120.4453452, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081505/0d53ee99479b553c83a2aebfe26bfd53bd147375.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='嘉義市光織影舞-光影藝術展', `description`='結合嘉義市特色及文化，以四季與中秋節為主題，設置8件光影藝術裝置，搭配表演活動，吸引旅客來嘉義市駐留體驗。\r\n\r\n    嘉義市國際藝術紀錄影展\r\n\r\n ', `organizer`='嘉義市政府', `address`='嘉義市 西區北香湖公園', `start_date`='2025-09-01 00:00:00', `end_date`='2025-09-30 00:00:00', `location`='嘉義市 西區北香湖公園', `latitude`=23.4920481, `longitude`=120.4453452, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081505/0d53ee99479b553c83a2aebfe26bfd53bd147375.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('844', '基隆鎖管季', '每年8~9月間洄游於基隆市附近海域，鎖管成為燈火漁業的主要漁獲；以「與海共生、里海永續」理念融入「鎖管季主題日」、「海釣學院」、「海上王爺文化祭」等系列活動，期能引領民眾親自走訪基隆漁村，體驗特有漁業、傳統人文、民俗歷史等海洋體驗活動，並富含海洋及漁業永續發展的重要意義。\r\n\r\n    基隆海洋老鷹嘉年華\r\n\r\n ', '基隆市政府', '基隆市 中正區碧砂漁港', '2025-06-01 00:00:00', '2025-09-30 00:00:00', '基隆市 中正區碧砂漁港', 25.1471415, 121.7862931, '無資料', 'https://www.klsogood.tw/%E9%8E%96%E7%AE%A1%E5%AD%A3%E9%AB%94%E9%A9%97%E6%B4%BB%E5%8B%95', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081535/0ba55ecc32122b3e5711f113721cef8695d722b6.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='基隆鎖管季', `description`='每年8~9月間洄游於基隆市附近海域，鎖管成為燈火漁業的主要漁獲；以「與海共生、里海永續」理念融入「鎖管季主題日」、「海釣學院」、「海上王爺文化祭」等系列活動，期能引領民眾親自走訪基隆漁村，體驗特有漁業、傳統人文、民俗歷史等海洋體驗活動，並富含海洋及漁業永續發展的重要意義。\r\n\r\n    基隆海洋老鷹嘉年華\r\n\r\n ', `organizer`='基隆市政府', `address`='基隆市 中正區碧砂漁港', `start_date`='2025-06-01 00:00:00', `end_date`='2025-09-30 00:00:00', `location`='基隆市 中正區碧砂漁港', `latitude`=25.1471415, `longitude`=121.7862931, `ticket_price`='無資料', `source_url`='https://www.klsogood.tw/%E9%8E%96%E7%AE%A1%E5%AD%A3%E9%AB%94%E9%A9%97%E6%B4%BB%E5%8B%95', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081535/0ba55ecc32122b3e5711f113721cef8695d722b6.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('786', '2025臺北時裝週', '為扶植時尚產業創新發展及提升我國時尚產業國際能見度與形象，自西元2018年起開始辦理，迄今辦理8屆，定位成為亞洲四大時裝週(東京、首爾、上海、臺北)之一。\r\n ', '文化部', '臺北市 信義區松山文創園區', '2025-03-27 00:00:00', '2025-10-21 00:00:00', '臺北市 信義區松山文創園區', 25.043848, 121.5606384, '無資料', 'https://tpefw.com/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081416/6fa3c55f336bde053f217a3bc98dbd90bf90a378.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺北時裝週', `description`='為扶植時尚產業創新發展及提升我國時尚產業國際能見度與形象，自西元2018年起開始辦理，迄今辦理8屆，定位成為亞洲四大時裝週(東京、首爾、上海、臺北)之一。\r\n ', `organizer`='文化部', `address`='臺北市 信義區松山文創園區', `start_date`='2025-03-27 00:00:00', `end_date`='2025-10-21 00:00:00', `location`='臺北市 信義區松山文創園區', `latitude`=25.043848, `longitude`=121.5606384, `ticket_price`='無資料', `source_url`='https://tpefw.com/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081416/6fa3c55f336bde053f217a3bc98dbd90bf90a378.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('857', '2025 台灣設計展', '自2003開始辦理已有20年，是台灣每年最具規模的大型設計展會之一，透過徵選與各縣市合作辦理的全民美學及設計價值展覽活動，主要內涵以設計導入城市治理與發展為策劃內容。', '經濟部、彰化市政府', '彰化縣2025年活動地點尚未確定', '2025-10-10 00:00:00', '2025-10-26 00:00:00', '彰化縣2025年活動地點尚未確定', 0, 0, '無資料', 'https://www.facebook.com/Taiwandesignexpo/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081548/00f103a98dc3a708109cd5d01d1d59533db31e4e.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025 台灣設計展', `description`='自2003開始辦理已有20年，是台灣每年最具規模的大型設計展會之一，透過徵選與各縣市合作辦理的全民美學及設計價值展覽活動，主要內涵以設計導入城市治理與發展為策劃內容。', `organizer`='經濟部、彰化市政府', `address`='彰化縣2025年活動地點尚未確定', `start_date`='2025-10-10 00:00:00', `end_date`='2025-10-26 00:00:00', `location`='彰化縣2025年活動地點尚未確定', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.facebook.com/Taiwandesignexpo/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081548/00f103a98dc3a708109cd5d01d1d59533db31e4e.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('789', '2025 Art Taipei 台北國際藝術博覽會', 'ART TAIPEI 台北國際藝術博覽會，每年透過邀請海內外畫廊的參展，帶來許多國際藝壇的重要作品，增進海內外藝術交流，並且推廣藝術生活和全民收藏。ART TAIPEI 台北國際藝術博覽會已是各畫廊和亞洲地區重要收藏家、畫廊、媒體互動的重要管道。有鑑於此，畫廊協會將會抱持著對藝術熱愛的精神，持續為臺灣藝術產業努力，不僅提供藝術家與藝術市場創造平台，更協助亞洲畫廊與國際畫廊多元交流。', '社團法人中華民國畫廊協會、文化部、中華民國對外貿易發展協會', '臺北市 信義區台北世界貿易中心展覽一館', '2025-10-24 00:00:00', '2025-10-27 00:00:00', '臺北市 信義區台北世界貿易中心展覽一館', 25.033155, 121.562347, '無資料', 'https://2025.art-taipei.com/taipei/tw/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081419/22eee32bfd41e20368f194ea0272ec6a6aac90cb.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025 Art Taipei 台北國際藝術博覽會', `description`='ART TAIPEI 台北國際藝術博覽會，每年透過邀請海內外畫廊的參展，帶來許多國際藝壇的重要作品，增進海內外藝術交流，並且推廣藝術生活和全民收藏。ART TAIPEI 台北國際藝術博覽會已是各畫廊和亞洲地區重要收藏家、畫廊、媒體互動的重要管道。有鑑於此，畫廊協會將會抱持著對藝術熱愛的精神，持續為臺灣藝術產業努力，不僅提供藝術家與藝術市場創造平台，更協助亞洲畫廊與國際畫廊多元交流。', `organizer`='社團法人中華民國畫廊協會、文化部、中華民國對外貿易發展協會', `address`='臺北市 信義區台北世界貿易中心展覽一館', `start_date`='2025-10-24 00:00:00', `end_date`='2025-10-27 00:00:00', `location`='臺北市 信義區台北世界貿易中心展覽一館', `latitude`=25.033155, `longitude`=121.562347, `ticket_price`='無資料', `source_url`='https://2025.art-taipei.com/taipei/tw/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081419/22eee32bfd41e20368f194ea0272ec6a6aac90cb.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('791', '臺中爵士音樂節', '臺中爵士音樂節以自由即興的風格展現多元的音樂型式開放空間的展演，呼應臺中市輕鬆、悠閒的都會生活文化特色，吸引民眾參與戶外藝術休閒活動，帶動週邊商業與休閒旅遊產業發展。自2003年開始辦理，活動期間至少9天，打造最高等級戶外劇院式舞台，地點以市民廣場、草悟道為中心，每年吸引百萬人次參與，並成為和東京、曼谷、首爾等城市並列的亞洲四大爵士音樂節之一。', '臺中市政府文化局', '臺中市 西區臺中市市民廣場', '2025-10-01 00:00:00', '2025-10-31 00:00:00', '臺中市 西區臺中市市民廣場', 24.15, 120.6635, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081421/f2ee922d6ea7592ef6295f62063438443ae0eeb9.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='臺中爵士音樂節', `description`='臺中爵士音樂節以自由即興的風格展現多元的音樂型式開放空間的展演，呼應臺中市輕鬆、悠閒的都會生活文化特色，吸引民眾參與戶外藝術休閒活動，帶動週邊商業與休閒旅遊產業發展。自2003年開始辦理，活動期間至少9天，打造最高等級戶外劇院式舞台，地點以市民廣場、草悟道為中心，每年吸引百萬人次參與，並成為和東京、曼谷、首爾等城市並列的亞洲四大爵士音樂節之一。', `organizer`='臺中市政府文化局', `address`='臺中市 西區臺中市市民廣場', `start_date`='2025-10-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='臺中市 西區臺中市市民廣場', `latitude`=24.15, `longitude`=120.6635, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081421/f2ee922d6ea7592ef6295f62063438443ae0eeb9.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('807', '2025臺灣鹽生活節-鹽文化藝術嘉年華', '臺61線西濱快速道路，是最靠近西海岸的公路，從新北八里到臺南七股，全長308公里，帶領沿海鄉鎮走出屬於自己的海洋風情，串連當地人文及觀光景點，讓旅客行車途中總有驚奇。由嘉義布袋沿著海岸往南至臺南七股，兩側舉目可見綿延的魚塭、蚵架等養殖景緻，交錯著漁村聚落及濕地生態等景觀，公路沿線一望無際的漁村風光盡收眼底。南臺灣熱情的陽光與海水，在雲嘉南濱海國家風景區留下雪白的結晶，七股鹽山與井仔腳瓦盤鹽田保留著這一片純淨的白，見證臺灣濱海鹽業的歷史。「2024臺灣鹽生活節-鹽文化藝術嘉年華」正是為了向遊客展現出南台灣在地特有的風貌，利用雲嘉南特有的鹽素材，嘗試搭配各種不同元素，創作一場年度藝術饗宴。\n\r\r\n「2024臺灣鹽生活節-鹽文化藝術嘉年華」構想以「鹽」與其他藝術創作媒材，結合民眾發想創作的展示平台，營造全臺獨一無二的藝術展場，並提供活動DIY體驗，串連鹽文化及雲嘉南周邊觀光景點之寓教於樂，宣傳61幸福公路之美，吸引全國遊客到雲嘉南濱海戶外旅遊，藉以提升觀光人潮，活絡地方觀光產業。\n\r\r\n\n\r\r\n ', '交通部觀光署雲嘉南濱海國家風景區管理處', '臺南市 七股區七股鹽山', '2025-08-01 00:00:00', '2025-10-31 00:00:00', '臺南市 七股區七股鹽山', 23.1541259, 120.0999988, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081457/8c237ec1e091bc896c9a7e4e478f45421b841592.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺灣鹽生活節-鹽文化藝術嘉年華', `description`='臺61線西濱快速道路，是最靠近西海岸的公路，從新北八里到臺南七股，全長308公里，帶領沿海鄉鎮走出屬於自己的海洋風情，串連當地人文及觀光景點，讓旅客行車途中總有驚奇。由嘉義布袋沿著海岸往南至臺南七股，兩側舉目可見綿延的魚塭、蚵架等養殖景緻，交錯著漁村聚落及濕地生態等景觀，公路沿線一望無際的漁村風光盡收眼底。南臺灣熱情的陽光與海水，在雲嘉南濱海國家風景區留下雪白的結晶，七股鹽山與井仔腳瓦盤鹽田保留著這一片純淨的白，見證臺灣濱海鹽業的歷史。「2024臺灣鹽生活節-鹽文化藝術嘉年華」正是為了向遊客展現出南台灣在地特有的風貌，利用雲嘉南特有的鹽素材，嘗試搭配各種不同元素，創作一場年度藝術饗宴。\n\r\r\n「2024臺灣鹽生活節-鹽文化藝術嘉年華」構想以「鹽」與其他藝術創作媒材，結合民眾發想創作的展示平台，營造全臺獨一無二的藝術展場，並提供活動DIY體驗，串連鹽文化及雲嘉南周邊觀光景點之寓教於樂，宣傳61幸福公路之美，吸引全國遊客到雲嘉南濱海戶外旅遊，藉以提升觀光人潮，活絡地方觀光產業。\n\r\r\n\n\r\r\n ', `organizer`='交通部觀光署雲嘉南濱海國家風景區管理處', `address`='臺南市 七股區七股鹽山', `start_date`='2025-08-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='臺南市 七股區七股鹽山', `latitude`=23.1541259, `longitude`=120.0999988, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081457/8c237ec1e091bc896c9a7e4e478f45421b841592.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('804', '南投世界茶業博覽會', '南投有八大茶區，更是台灣茶葉主要產地，透過展館搭建與展售會，提供遊客茶知識、體驗、展演。並舉辦數場大型特色主題活動，如千人茶會、千人擂茶以及千人野餐等活動，推廣多元豐富的茶文化。', '南投縣政府', '南投縣 南投市中興新村 中興會堂', '2025-10-01 00:00:00', '2025-10-31 00:00:00', '南投縣 南投市中興新村 中興會堂', 23.9492923, 120.6962211, '無資料', 'https://teaexpo.mmweb.tw/?ptype=f3ck&id=916', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081442/4a33504769dc3dcf259c270c4cbc031ef0605b86.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='南投世界茶業博覽會', `description`='南投有八大茶區，更是台灣茶葉主要產地，透過展館搭建與展售會，提供遊客茶知識、體驗、展演。並舉辦數場大型特色主題活動，如千人茶會、千人擂茶以及千人野餐等活動，推廣多元豐富的茶文化。', `organizer`='南投縣政府', `address`='南投縣 南投市中興新村 中興會堂', `start_date`='2025-10-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='南投縣 南投市中興新村 中興會堂', `latitude`=23.9492923, `longitude`=120.6962211, `ticket_price`='無資料', `source_url`='https://teaexpo.mmweb.tw/?ptype=f3ck&id=916', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081442/4a33504769dc3dcf259c270c4cbc031ef0605b86.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('775', '雲林國際偶戲節', ' \r\n「雲林國際偶戲節」內容包含開幕音樂會、閉幕-金掌獎頒獎典禮、人間國寶大師演出、口白創意競賽、藝師帶偶去旅行等多樣化系列活動。\r\n ', '雲林縣政府', '雲林縣 虎尾鎮雲林布袋戲館', '2025-10-01 00:00:00', '2025-10-31 00:00:00', '雲林縣 虎尾鎮雲林布袋戲館', 23.709297, 120.4335627, '無資料', 'https://www.facebook.com/puppet.yunlin.gov.tw/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081393/2f0a45abc494b22a3bf0277777bb7a833355dcb9.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='雲林國際偶戲節', `description`=' \r\n「雲林國際偶戲節」內容包含開幕音樂會、閉幕-金掌獎頒獎典禮、人間國寶大師演出、口白創意競賽、藝師帶偶去旅行等多樣化系列活動。\r\n ', `organizer`='雲林縣政府', `address`='雲林縣 虎尾鎮雲林布袋戲館', `start_date`='2025-10-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='雲林縣 虎尾鎮雲林布袋戲館', `latitude`=23.709297, `longitude`=120.4335627, `ticket_price`='無資料', `source_url`='https://www.facebook.com/puppet.yunlin.gov.tw/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081393/2f0a45abc494b22a3bf0277777bb7a833355dcb9.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('776', '高雄左營萬年季', '每年10月中旬在左營蓮池潭登場的萬年季活動，自民國90年（西元2001年）舉辦迄今，運用左營獨有天然景觀（蓮池潭及周邊林立的寺廟）、結合特殊民情風俗（攻炮城、迓火獅）等在地因素規劃而成，由於活動設計極具地方特色，每年吸引許多參觀人潮，已發展成為本市重要民俗文化觀光節慶活動。', '高雄市政府民政局', '高雄市 左營區左營孔廟', '2025-10-01 00:00:00', '2025-10-31 00:00:00', '高雄市 左營區左營孔廟', 22.6893396, 120.2987334, '無資料', 'https://www.facebook.com/FireLion.Kaohsiung/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081397/50058f64044fcc35b96fcac8b6fad475adc1f18a.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='高雄左營萬年季', `description`='每年10月中旬在左營蓮池潭登場的萬年季活動，自民國90年（西元2001年）舉辦迄今，運用左營獨有天然景觀（蓮池潭及周邊林立的寺廟）、結合特殊民情風俗（攻炮城、迓火獅）等在地因素規劃而成，由於活動設計極具地方特色，每年吸引許多參觀人潮，已發展成為本市重要民俗文化觀光節慶活動。', `organizer`='高雄市政府民政局', `address`='高雄市 左營區左營孔廟', `start_date`='2025-10-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='高雄市 左營區左營孔廟', `latitude`=22.6893396, `longitude`=120.2987334, `ticket_price`='無資料', `source_url`='https://www.facebook.com/FireLion.Kaohsiung/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081397/50058f64044fcc35b96fcac8b6fad475adc1f18a.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('777', '三義木雕藝術節系列活動', '2022三義木雕藝術節系列活動，強調木雕藝術傳承的使命感。除了木藝慢活嘉年華現場活動以動態藝表演、木雕表演、木藝體驗、文創市集、慢城旅遊、茶席等系列活動，營造親子、互動、熱鬧氛圍，塑造三義慢城獨特木雕藝術文化形象，「木雕」為三義最具代表性的傳統文化特色，木雕藝術發展蓬勃，透過木雕技藝與形式的延續，讓經典成為永恆。', '苗栗縣政府文化觀光局', '苗栗縣 三義鄉三義木雕博物館', '2025-10-01 00:00:00', '2025-10-31 00:00:00', '苗栗縣 三義鄉三義木雕博物館', 24.4059435, 120.7609731, '無資料', 'https://www.sanyi-woodart.com.tw/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081398/c15f65532f21b33a73bfdc43a16323cd29c9b69a.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='三義木雕藝術節系列活動', `description`='2022三義木雕藝術節系列活動，強調木雕藝術傳承的使命感。除了木藝慢活嘉年華現場活動以動態藝表演、木雕表演、木藝體驗、文創市集、慢城旅遊、茶席等系列活動，營造親子、互動、熱鬧氛圍，塑造三義慢城獨特木雕藝術文化形象，「木雕」為三義最具代表性的傳統文化特色，木雕藝術發展蓬勃，透過木雕技藝與形式的延續，讓經典成為永恆。', `organizer`='苗栗縣政府文化觀光局', `address`='苗栗縣 三義鄉三義木雕博物館', `start_date`='2025-10-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='苗栗縣 三義鄉三義木雕博物館', `latitude`=24.4059435, `longitude`=120.7609731, `ticket_price`='無資料', `source_url`='https://www.sanyi-woodart.com.tw/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081398/c15f65532f21b33a73bfdc43a16323cd29c9b69a.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('845', '基隆潮藝術', '自2015年起辦理迄今，從潮境公園拓張至舊正濱漁會大樓、阿根廷造船廠遺構，並打造極具特色的海上美術館，從海洋關懷出發，不管鼓勵激發民眾思考基隆與海洋、藝術與環境的關係，透過藝術重新喚起在地認同。', '基隆市政府文化局', '基隆市 中正區正濱漁港', '2025-09-01 00:00:00', '2025-10-31 00:00:00', '基隆市 中正區正濱漁港', 25.1519519, 121.7660559, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081536/760fc7ff04055f61688ef73d042adf63115ace76.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='基隆潮藝術', `description`='自2015年起辦理迄今，從潮境公園拓張至舊正濱漁會大樓、阿根廷造船廠遺構，並打造極具特色的海上美術館，從海洋關懷出發，不管鼓勵激發民眾思考基隆與海洋、藝術與環境的關係，透過藝術重新喚起在地認同。', `organizer`='基隆市政府文化局', `address`='基隆市 中正區正濱漁港', `start_date`='2025-09-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='基隆市 中正區正濱漁港', `latitude`=25.1519519, `longitude`=121.7660559, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081536/760fc7ff04055f61688ef73d042adf63115ace76.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('847', '故宮亞洲藝術節—馬來西亞月', '自2017年起於南部院區辦理「故宮亞洲藝術節」，每年聚焦特定亞洲國家，配合當期亞洲主題特展，於10月份推出主題展示、闖關遊戲、服飾體驗創意課程、藝文表演、專題講座等活動，前已辦理印度、新加坡、泰國、蒙古、印尼、越南及韓國等7國文化系列活動，每年度活動辦理期間吸引8萬至10萬國內外遊客參與體驗。', '國立故宮博物院', '嘉義縣 太保市故宮大道888號', '2025-10-01 00:00:00', '2025-10-31 00:00:00', '嘉義縣 太保市故宮大道888號', 23.4731294, 120.2927165, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081538/c56d5ec3397e475d07409d300c1097c30ea05387.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='故宮亞洲藝術節—馬來西亞月', `description`='自2017年起於南部院區辦理「故宮亞洲藝術節」，每年聚焦特定亞洲國家，配合當期亞洲主題特展，於10月份推出主題展示、闖關遊戲、服飾體驗創意課程、藝文表演、專題講座等活動，前已辦理印度、新加坡、泰國、蒙古、印尼、越南及韓國等7國文化系列活動，每年度活動辦理期間吸引8萬至10萬國內外遊客參與體驗。', `organizer`='國立故宮博物院', `address`='嘉義縣 太保市故宮大道888號', `start_date`='2025-10-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='嘉義縣 太保市故宮大道888號', `latitude`=23.4731294, `longitude`=120.2927165, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081538/c56d5ec3397e475d07409d300c1097c30ea05387.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('826', '迎王平安祭典', '迎王平安祭典是屏東縣東港鎮、琉球鄉與南州鄉地區傳承百年之久三年一科的宗教文化節慶，透過恭請王駕、過神火、王船法會、遷船遶境暨宴王、恭送王駕等儀式，恭迎代天巡狩千歲爺王駕，完成此行代天巡狩的神聖任務。', '財團法人臺灣省屏東縣東港東隆宮', '屏東縣 東港鎮東隆街21-1號', '2025-09-01 00:00:00', '2025-10-31 00:00:00', '屏東縣 東港鎮東隆街21-1號', 22.463075, 120.448765, '無資料', 'https://www.66.org.tw/m1_file/detail.php?id=1&mid=2&category=x&nid=121', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081501/8b7acaddd1d6907f528d42133f986d7b560edcb9.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='迎王平安祭典', `description`='迎王平安祭典是屏東縣東港鎮、琉球鄉與南州鄉地區傳承百年之久三年一科的宗教文化節慶，透過恭請王駕、過神火、王船法會、遷船遶境暨宴王、恭送王駕等儀式，恭迎代天巡狩千歲爺王駕，完成此行代天巡狩的神聖任務。', `organizer`='財團法人臺灣省屏東縣東港東隆宮', `address`='屏東縣 東港鎮東隆街21-1號', `start_date`='2025-09-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='屏東縣 東港鎮東隆街21-1號', `latitude`=22.463075, `longitude`=120.448765, `ticket_price`='無資料', `source_url`='https://www.66.org.tw/m1_file/detail.php?id=1&mid=2&category=x&nid=121', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081501/8b7acaddd1d6907f528d42133f986d7b560edcb9.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('819', '金門縣烈嶼鄉芋頭季系列活動', '整體芋頭季活動包含芋頭季活動開幕式及芋頭季期間配套活動二大部分，配套活動內容有：優質芋頭競賽比賽、芋頭季徵圖比賽、獎助遊客蒞鄉消費活動、芋頭季主題情境體驗暨打卡活動等。', '金門縣政府、金門縣烈嶼鄉公所', '金門縣東林複合式運動場', '2025-10-01 00:00:00', '2025-10-31 00:00:00', '金門縣東林複合式運動場', 24.42994136, 118.25145194, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081494/1d23ee257bd9a17c73827fc299a0d93f2d8256e1.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='金門縣烈嶼鄉芋頭季系列活動', `description`='整體芋頭季活動包含芋頭季活動開幕式及芋頭季期間配套活動二大部分，配套活動內容有：優質芋頭競賽比賽、芋頭季徵圖比賽、獎助遊客蒞鄉消費活動、芋頭季主題情境體驗暨打卡活動等。', `organizer`='金門縣政府、金門縣烈嶼鄉公所', `address`='金門縣東林複合式運動場', `start_date`='2025-10-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='金門縣東林複合式運動場', `latitude`=24.42994136, `longitude`=118.25145194, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081494/1d23ee257bd9a17c73827fc299a0d93f2d8256e1.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('821', '金門中秋博狀元餅', '中秋博狀元餅活動在金門地區已是三百多年歷史的民俗文化活動，以科舉進程及追求人上人為博狀元餅遊戲之寄寓發展，透過遊戲普及民間。亦藉由此活動，吸引國際觀光客一起來金門體驗閩鄉傳統民俗之趣味。\r\n', '金門縣政府', '金門縣 金城鎮清金門鎮總兵署', '2025-08-01 00:00:00', '2025-10-31 00:00:00', '金門縣 金城鎮清金門鎮總兵署', 24.4322994, 118.3184081, '無資料', 'https://kinmen.travel/zh-tw/event-calendar/details/3923', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081496/652774752114a9231799e1ecf628571012753380.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='金門中秋博狀元餅', `description`='中秋博狀元餅活動在金門地區已是三百多年歷史的民俗文化活動，以科舉進程及追求人上人為博狀元餅遊戲之寄寓發展，透過遊戲普及民間。亦藉由此活動，吸引國際觀光客一起來金門體驗閩鄉傳統民俗之趣味。\r\n', `organizer`='金門縣政府', `address`='金門縣 金城鎮清金門鎮總兵署', `start_date`='2025-08-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='金門縣 金城鎮清金門鎮總兵署', `latitude`=24.4322994, `longitude`=118.3184081, `ticket_price`='無資料', `source_url`='https://kinmen.travel/zh-tw/event-calendar/details/3923', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081496/652774752114a9231799e1ecf628571012753380.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('870', '鯤鯓王平安鹽祭', ' \r\n鯤鯓王平安鹽祭將沙洲景觀結合當地傳統「王爺信仰」，並以獨特的「鹽」文化作為活動主題，藉由此活動讓國內外的遊客更了解臺灣當地民俗信仰、鹽業文化。\r\n ', '雲嘉南濱海國家風景區管理處', '臺南市 北門區南鯤鯓代天府', '2025-10-01 00:00:00', '2025-10-31 00:00:00', '臺南市 北門區南鯤鯓代天府', 23.2860869, 120.143135, '無資料', 'https://www.swcoast-nsa.gov.tw/zh-tw/event-calendar/details/2270', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081601/fefdfa25c8bac98c26c1d40716fa07d425308c67.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='鯤鯓王平安鹽祭', `description`=' \r\n鯤鯓王平安鹽祭將沙洲景觀結合當地傳統「王爺信仰」，並以獨特的「鹽」文化作為活動主題，藉由此活動讓國內外的遊客更了解臺灣當地民俗信仰、鹽業文化。\r\n ', `organizer`='雲嘉南濱海國家風景區管理處', `address`='臺南市 北門區南鯤鯓代天府', `start_date`='2025-10-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='臺南市 北門區南鯤鯓代天府', `latitude`=23.2860869, `longitude`=120.143135, `ticket_price`='無資料', `source_url`='https://www.swcoast-nsa.gov.tw/zh-tw/event-calendar/details/2270', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081601/fefdfa25c8bac98c26c1d40716fa07d425308c67.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('871', '阿里山神木下婚禮', '「阿里山神木下婚禮」除聚焦主活動及貳部曲「阿里山星光下婚禮」，也將阿里山的美景、森林鐵路、神木、傳統的鄒族文化及多元的在地產業推向國際舞台，打造戀人至阿里山約會、婚拍及蜜月的難忘浪漫回憶，吸引國內外旅客至阿里山體驗浪漫之旅。\r\n\r\n    星光下婚禮：3月13日至14日\r\n    神木下婚禮：10月\r\n -->', '交通部觀光署阿里山國家風景區管理處', '嘉義縣 阿里山鄉阿里山國家森林遊樂區-香林神木', '2025-10-01 00:00:00', '2025-10-31 00:00:00', '嘉義縣 阿里山鄉阿里山國家森林遊樂區-香林神木', 23.5173506, 120.8081305, '無資料', 'https://www.ali-nsa.net/zh-tw/event/calendardetail/3239', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081605/6485d40371d78b112d4b907a90307f9fabc1b8f5.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='阿里山神木下婚禮', `description`='「阿里山神木下婚禮」除聚焦主活動及貳部曲「阿里山星光下婚禮」，也將阿里山的美景、森林鐵路、神木、傳統的鄒族文化及多元的在地產業推向國際舞台，打造戀人至阿里山約會、婚拍及蜜月的難忘浪漫回憶，吸引國內外旅客至阿里山體驗浪漫之旅。\r\n\r\n    星光下婚禮：3月13日至14日\r\n    神木下婚禮：10月\r\n -->', `organizer`='交通部觀光署阿里山國家風景區管理處', `address`='嘉義縣 阿里山鄉阿里山國家森林遊樂區-香林神木', `start_date`='2025-10-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='嘉義縣 阿里山鄉阿里山國家森林遊樂區-香林神木', `latitude`=23.5173506, `longitude`=120.8081305, `ticket_price`='無資料', `source_url`='https://www.ali-nsa.net/zh-tw/event/calendardetail/3239', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081605/6485d40371d78b112d4b907a90307f9fabc1b8f5.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('855', '2025 水流東紅酒音樂祭', '迄今辦理四屆，推廣「地酒到地域」的深度體驗之旅，搭配綠色運具-自行車騎旅串聯，草地市集結合在地四大酒莊推出的紅酒音樂祭活動，以后里圳、桐花步道貫穿串聯周邊六分社區、永豐社區、特色的農場體驗，打造水流東休區特有的紅酒美學，預計參與人次達千人。', '臺中市外埔區農會、臺中市外埔區水流東休閒農業區發展協會', '臺中市 外埔區外埔農藝傳坊', '2025-10-01 00:00:00', '2025-10-31 00:00:00', '臺中市 外埔區外埔農藝傳坊', 24.32044788, 120.67439969, '無資料', 'https://www.facebook.com/p/%E6%B0%B4%E6%B5%81%E6%9D%B1%E7%B4%85%E9%85%92%E9%9F%B3%E6%A8%82%E7%A5%AD-100084127444743/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081546/1ea0961219f0a142160496e2c5540013d71653a4.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025 水流東紅酒音樂祭', `description`='迄今辦理四屆，推廣「地酒到地域」的深度體驗之旅，搭配綠色運具-自行車騎旅串聯，草地市集結合在地四大酒莊推出的紅酒音樂祭活動，以后里圳、桐花步道貫穿串聯周邊六分社區、永豐社區、特色的農場體驗，打造水流東休區特有的紅酒美學，預計參與人次達千人。', `organizer`='臺中市外埔區農會、臺中市外埔區水流東休閒農業區發展協會', `address`='臺中市 外埔區外埔農藝傳坊', `start_date`='2025-10-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='臺中市 外埔區外埔農藝傳坊', `latitude`=24.32044788, `longitude`=120.67439969, `ticket_price`='無資料', `source_url`='https://www.facebook.com/p/%E6%B0%B4%E6%B5%81%E6%9D%B1%E7%B4%85%E9%85%92%E9%9F%B3%E6%A8%82%E7%A5%AD-100084127444743/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081546/1ea0961219f0a142160496e2c5540013d71653a4.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('856', '經濟部商業署美食推薦活動', '為帶動我國餐飲產業發展，持續推廣並傳承臺菜文化，以「臺菜」為主軸運用主題式行銷、國際推廣及商機促進，以吸引國內外旅客體驗臺灣美食好滋味。活動廣召並遴選出全臺60家以上優質臺菜餐廳業者，透過展售活動及聯合行銷方式來提升品牌知名度與業績，預計每年活動可吸引至少1萬人次參與。', '經濟部商業署', '臺北市2025年活動地點尚未確定', '2025-09-01 00:00:00', '2025-10-31 00:00:00', '臺北市2025年活動地點尚未確定', 0, 0, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081547/d0791e0967f375d96667fcaff141d47f3813d674.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='經濟部商業署美食推薦活動', `description`='為帶動我國餐飲產業發展，持續推廣並傳承臺菜文化，以「臺菜」為主軸運用主題式行銷、國際推廣及商機促進，以吸引國內外旅客體驗臺灣美食好滋味。活動廣召並遴選出全臺60家以上優質臺菜餐廳業者，透過展售活動及聯合行銷方式來提升品牌知名度與業績，預計每年活動可吸引至少1萬人次參與。', `organizer`='經濟部商業署', `address`='臺北市2025年活動地點尚未確定', `start_date`='2025-09-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='臺北市2025年活動地點尚未確定', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081547/d0791e0967f375d96667fcaff141d47f3813d674.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('859', '琅嶠鷹季系列活動', '每年南來北往經過或留下渡冬的候鳥，多達200種以上，吸引來自各地的鳥友及民眾前來觀賞一年一度的盛會，便是每年秋季過境的日行性猛禽遷徙景觀，賞鷹寫生比賽、環境電影院、市集包含滿州鄉農特產品展售、文創商品、恆春半島各生態旅遊社區與屏南社區大學合作的友善農業小農。', '墾丁國家公園管理處', '屏東縣 滿州鄉文化路32號(滿州國中)', '2025-09-01 00:00:00', '2025-10-31 00:00:00', '屏東縣 滿州鄉文化路32號(滿州國中)', 22.0238789, 120.8396558, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081552/fbd2fbd3237c60c349816f03aeac0aa331a3f8e9.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='琅嶠鷹季系列活動', `description`='每年南來北往經過或留下渡冬的候鳥，多達200種以上，吸引來自各地的鳥友及民眾前來觀賞一年一度的盛會，便是每年秋季過境的日行性猛禽遷徙景觀，賞鷹寫生比賽、環境電影院、市集包含滿州鄉農特產品展售、文創商品、恆春半島各生態旅遊社區與屏南社區大學合作的友善農業小農。', `organizer`='墾丁國家公園管理處', `address`='屏東縣 滿州鄉文化路32號(滿州國中)', `start_date`='2025-09-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='屏東縣 滿州鄉文化路32號(滿州國中)', `latitude`=22.0238789, `longitude`=120.8396558, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081552/fbd2fbd3237c60c349816f03aeac0aa331a3f8e9.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('861', '臺灣自行車旅遊節', '臺灣的公路系統完善，再加上地形優勢，騎著自行車時還可邊欣賞沿路壯闊美景，在臺灣單車環島是最方便又享受的旅遊行程！「臺灣自行車節」系列活動就是以自行車旅遊活動，結合了各縣市的觀光與交通資源力量，呈現出多元與在地的文化旅遊特色。在好山好水的陪伴下，吸引全世界自行車愛好者都能來朝聖，提供國內外遊客們多樣豐富休憩旅遊體驗。\r\n\r\n    國際自由車環台公路大賽「浪漫台三線站」\r\n    西拉雅趣飛車\n\r\r\n     \r\n\r\n ', '交通部觀光署', '新北市2024年活動地點尚未確定', '2025-09-01 00:00:00', '2025-11-30 00:00:00', '新北市2024年活動地點尚未確定', 0, 0, '無資料', 'https://taiwanbike.tw/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081558/3bed403337f277d0a554fa4390d475b9ecdf1b9f.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='臺灣自行車旅遊節', `description`='臺灣的公路系統完善，再加上地形優勢，騎著自行車時還可邊欣賞沿路壯闊美景，在臺灣單車環島是最方便又享受的旅遊行程！「臺灣自行車節」系列活動就是以自行車旅遊活動，結合了各縣市的觀光與交通資源力量，呈現出多元與在地的文化旅遊特色。在好山好水的陪伴下，吸引全世界自行車愛好者都能來朝聖，提供國內外遊客們多樣豐富休憩旅遊體驗。\r\n\r\n    國際自由車環台公路大賽「浪漫台三線站」\r\n    西拉雅趣飛車\n\r\r\n     \r\n\r\n ', `organizer`='交通部觀光署', `address`='新北市2024年活動地點尚未確定', `start_date`='2025-09-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='新北市2024年活動地點尚未確定', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://taiwanbike.tw/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081558/3bed403337f277d0a554fa4390d475b9ecdf1b9f.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('862', '菊島澎湖跨海馬拉松', '菊島澎湖跨海馬拉松，是堪稱為外島首創的A-B點不折返、跳島、不繞圈的賽道，此賽道已於2018年取得中華民國田徑協會之國際田徑總會「IAAF/AIMS國際賽道認證」，搭配賽道沿線設置之特色美食補給及創意啦啦隊，讓跑友們更能全程以一步一腳印的方式，深入體驗澎湖之美。', '交通部觀光署澎湖國家風景區管理處', '澎湖縣 馬公市中興里介壽路7號', '2025-11-01 00:00:00', '2025-11-30 00:00:00', '澎湖縣 馬公市中興里介壽路7號', 23.567705, 119.561956, '無資料', 'https://www.facebook.com/PHCSM/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081559/44dc40354d25ddb294912fd905d82fca520e22a3.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='菊島澎湖跨海馬拉松', `description`='菊島澎湖跨海馬拉松，是堪稱為外島首創的A-B點不折返、跳島、不繞圈的賽道，此賽道已於2018年取得中華民國田徑協會之國際田徑總會「IAAF/AIMS國際賽道認證」，搭配賽道沿線設置之特色美食補給及創意啦啦隊，讓跑友們更能全程以一步一腳印的方式，深入體驗澎湖之美。', `organizer`='交通部觀光署澎湖國家風景區管理處', `address`='澎湖縣 馬公市中興里介壽路7號', `start_date`='2025-11-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='澎湖縣 馬公市中興里介壽路7號', `latitude`=23.567705, `longitude`=119.561956, `ticket_price`='無資料', `source_url`='https://www.facebook.com/PHCSM/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081559/44dc40354d25ddb294912fd905d82fca520e22a3.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('869', '臺灣國際觀鳥馬拉松', '臺灣能觀賞得到全世界約15分之1的鳥種，超過686種以上的鳥類，而雲嘉南濱海地區，因地理環境得天獨厚，擁有潟湖、沖積沙洲、鹽田濕地&hellip;等豐富生態，提供眾多鳥類棲息、繁殖、哺育的友善環境，在雲嘉南能看到70%全球罕見『黑面琵鷺』。秋冬是候鳥遷徙的高峰期，雲嘉南濱海國家風景區管理處辦理11年的『臺灣國際觀鳥馬拉松』活動，是24小時不間斷穿越山海刺激有趣尋鳥馬拉松比賽活動，已為世界級知名賞鳥愛好者畢生必定踏訪活動。', '雲嘉南濱海國家風景區管理處', '臺南市 北門區北門遊客中心', '2025-11-01 00:00:00', '2025-11-30 00:00:00', '臺南市 北門區北門遊客中心', 23.2671522, 120.1239695, '無資料', 'https://www.facebook.com/swcoast', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081595/b2291f3fa05638af54dd8c2aed27869b4c98afc7.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='臺灣國際觀鳥馬拉松', `description`='臺灣能觀賞得到全世界約15分之1的鳥種，超過686種以上的鳥類，而雲嘉南濱海地區，因地理環境得天獨厚，擁有潟湖、沖積沙洲、鹽田濕地&hellip;等豐富生態，提供眾多鳥類棲息、繁殖、哺育的友善環境，在雲嘉南能看到70%全球罕見『黑面琵鷺』。秋冬是候鳥遷徙的高峰期，雲嘉南濱海國家風景區管理處辦理11年的『臺灣國際觀鳥馬拉松』活動，是24小時不間斷穿越山海刺激有趣尋鳥馬拉松比賽活動，已為世界級知名賞鳥愛好者畢生必定踏訪活動。', `organizer`='雲嘉南濱海國家風景區管理處', `address`='臺南市 北門區北門遊客中心', `start_date`='2025-11-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='臺南市 北門區北門遊客中心', `latitude`=23.2671522, `longitude`=120.1239695, `ticket_price`='無資料', `source_url`='https://www.facebook.com/swcoast', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081595/b2291f3fa05638af54dd8c2aed27869b4c98afc7.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('876', '日月潭Come!BikeDay花火音樂嘉年華', '日月潭是我國最負盛名、國內外名聞遐邇之觀光遊憩區，每年造訪日月潭之旅客平均達350萬人次，曾被美國有線電視新聞網（CNN）旗下生活旅遊網站CNNGO評選為全球十大最美自行車道。日月潭花火音樂嘉年華系列活動以音樂藝術、運動休閒、在地產業文化等活動特色與傳統為主軸，延續「Come!BikeDay自行車」及「大型戶外花火音樂會」活動雙核心亮點，吸引更多國內外旅客到訪。\r\n ', '交通部觀光署日月潭國家風景區管理處', '南投縣 魚池鄉水社碼頭', '2025-10-01 00:00:00', '2025-11-30 00:00:00', '南投縣 魚池鄉水社碼頭', 23.864501, 120.911917, '無資料', 'https://www.sunmoonlake.gov.tw/zh-tw/event/calendardetail/2798', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081598/523e79afa02ffe762dfe258ddd7c071546407215.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='日月潭Come!BikeDay花火音樂嘉年華', `description`='日月潭是我國最負盛名、國內外名聞遐邇之觀光遊憩區，每年造訪日月潭之旅客平均達350萬人次，曾被美國有線電視新聞網（CNN）旗下生活旅遊網站CNNGO評選為全球十大最美自行車道。日月潭花火音樂嘉年華系列活動以音樂藝術、運動休閒、在地產業文化等活動特色與傳統為主軸，延續「Come!BikeDay自行車」及「大型戶外花火音樂會」活動雙核心亮點，吸引更多國內外旅客到訪。\r\n ', `organizer`='交通部觀光署日月潭國家風景區管理處', `address`='南投縣 魚池鄉水社碼頭', `start_date`='2025-10-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='南投縣 魚池鄉水社碼頭', `latitude`=23.864501, `longitude`=120.911917, `ticket_price`='無資料', `source_url`='https://www.sunmoonlake.gov.tw/zh-tw/event/calendardetail/2798', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081598/523e79afa02ffe762dfe258ddd7c071546407215.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('878', '2025澎湖四季旅遊', '顛覆以往大家對澎湖觀光遊玩的認知，澎湖旅遊不只4-9月好好玩，其餘時間氣候舒適、人潮較少，讓你玩得更盡興！澎管處規劃「澎湖四季旅遊」一系列活動，帶你探索傳統自然、純樸有趣的澎湖，四季樣貌各展風情，就等你來親身體會囉！', '交通部觀光署澎湖國家風景區管理處', '澎湖縣 馬公市澎湖縣馬公市光華里171號', '2024-02-10 00:00:00', '2025-11-30 00:00:00', '澎湖縣 馬公市澎湖縣馬公市光華里171號', 23.55673207, 119.60665932, '無資料', 'https://www.penghu-nsa.gov.tw/activities/penghufourseasons/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081621/29285c1c69f6dfcceb581044627e6f5ca0d388d9.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025澎湖四季旅遊', `description`='顛覆以往大家對澎湖觀光遊玩的認知，澎湖旅遊不只4-9月好好玩，其餘時間氣候舒適、人潮較少，讓你玩得更盡興！澎管處規劃「澎湖四季旅遊」一系列活動，帶你探索傳統自然、純樸有趣的澎湖，四季樣貌各展風情，就等你來親身體會囉！', `organizer`='交通部觀光署澎湖國家風景區管理處', `address`='澎湖縣 馬公市澎湖縣馬公市光華里171號', `start_date`='2024-02-10 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='澎湖縣 馬公市澎湖縣馬公市光華里171號', `latitude`=23.55673207, `longitude`=119.60665932, `ticket_price`='無資料', `source_url`='https://www.penghu-nsa.gov.tw/activities/penghufourseasons/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081621/29285c1c69f6dfcceb581044627e6f5ca0d388d9.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('812', '2025馬祖馬拉松', '馬祖是台灣的離島，與國內馬拉松場地比較，其地形高低起伏較大，為一挑戰型賽事，為配合天候，馬祖馬拉松訂於每年11月舉辦，希望藉由當地特色聚落文化、戰地景觀及閩東風俗民情，提高運動觀光能見度，因地形因素其相對挑戰難度亦較高，對於喜愛從事挑戰型路跑運動的民眾而言，相對具有很高的挑戰性。', '連江縣政府、交通部觀光署馬祖國家風景區管理處', '連江縣 南竿鄉福澳運動場', '2025-11-01 00:00:00', '2025-11-30 00:00:00', '連江縣 南竿鄉福澳運動場', 26.1594159, 119.9440593, '無資料', 'https://www.facebook.com/matsumarathon/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081463/709cb290e188edc328a76d453c231428705edef5.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025馬祖馬拉松', `description`='馬祖是台灣的離島，與國內馬拉松場地比較，其地形高低起伏較大，為一挑戰型賽事，為配合天候，馬祖馬拉松訂於每年11月舉辦，希望藉由當地特色聚落文化、戰地景觀及閩東風俗民情，提高運動觀光能見度，因地形因素其相對挑戰難度亦較高，對於喜愛從事挑戰型路跑運動的民眾而言，相對具有很高的挑戰性。', `organizer`='連江縣政府、交通部觀光署馬祖國家風景區管理處', `address`='連江縣 南竿鄉福澳運動場', `start_date`='2025-11-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='連江縣 南竿鄉福澳運動場', `latitude`=26.1594159, `longitude`=119.9440593, `ticket_price`='無資料', `source_url`='https://www.facebook.com/matsumarathon/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081463/709cb290e188edc328a76d453c231428705edef5.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('851', '西藏文化藝術節', '每年舉辦以「西藏文化藝術節」為主題之系列活動，包含文物特展、學術研討會、攝影展、繪畫展、工藝展、音樂會、文化體驗活動及專題講座，以促進文化扎根秉持多元創新精神。', '文化部', '臺北市 士林區臺灣戲曲中心', '2025-09-01 00:00:00', '2025-11-30 00:00:00', '臺北市 士林區臺灣戲曲中心', 25.1022766, 121.5197787, '無資料', 'https://tibetanfestival.moc.gov.tw/index/zh-tw', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081542/9ac830ec840236024bb61c5ffa4b35b7fd6a755e.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='西藏文化藝術節', `description`='每年舉辦以「西藏文化藝術節」為主題之系列活動，包含文物特展、學術研討會、攝影展、繪畫展、工藝展、音樂會、文化體驗活動及專題講座，以促進文化扎根秉持多元創新精神。', `organizer`='文化部', `address`='臺北市 士林區臺灣戲曲中心', `start_date`='2025-09-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='臺北市 士林區臺灣戲曲中心', `latitude`=25.1022766, `longitude`=121.5197787, `ticket_price`='無資料', `source_url`='https://tibetanfestival.moc.gov.tw/index/zh-tw', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081542/9ac830ec840236024bb61c5ffa4b35b7fd6a755e.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('836', '二水國際跑水節', '「二水跑水節」為全國特有的水圳節慶活動，在深具歷史文化意涵的八堡圳舉辦跑引水活動，傳揚歷經十年開鑿的辛勞。每年11月進入秋收冬藏之際，在八堡圳舉辦一系列祈福活動，結合二水文化、跑水體驗、山海線農特產品、國際城鄉交流等，行銷二水鄉的觀光特色，活化農村經濟。', '彰化縣政府文化局', '彰化縣 二水鄉2025年活動地點尚未確定', '2025-11-01 00:00:00', '2025-11-30 00:00:00', '彰化縣 二水鄉2025年活動地點尚未確定', 0, 0, '無資料', 'https://www.facebook.com/watermarathon/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081512/cc67e287fc12caab8255c0cfcd40cb7a72835367.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='二水國際跑水節', `description`='「二水跑水節」為全國特有的水圳節慶活動，在深具歷史文化意涵的八堡圳舉辦跑引水活動，傳揚歷經十年開鑿的辛勞。每年11月進入秋收冬藏之際，在八堡圳舉辦一系列祈福活動，結合二水文化、跑水體驗、山海線農特產品、國際城鄉交流等，行銷二水鄉的觀光特色，活化農村經濟。', `organizer`='彰化縣政府文化局', `address`='彰化縣 二水鄉2025年活動地點尚未確定', `start_date`='2025-11-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='彰化縣 二水鄉2025年活動地點尚未確定', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.facebook.com/watermarathon/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081512/cc67e287fc12caab8255c0cfcd40cb7a72835367.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('773', '2025高雄戲獅甲', '自2006年起開始舉辦，將原來屬於「地方的」與「廟會的」舞獅競技、陣頭表演，逐年擴大為融合了具國際性的高樁舞獅競賽、獨特的地方藝陣表演藝術。', '高雄市政府', '高雄市 苓雅區中正一路94巷1號', '2025-11-01 00:00:00', '2025-11-30 00:00:00', '高雄市 苓雅區中正一路94巷1號', 22.628819, 120.3350376, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081360/a410495bb2bd55e79ce03319cbf43f63359ffcd8.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025高雄戲獅甲', `description`='自2006年起開始舉辦，將原來屬於「地方的」與「廟會的」舞獅競技、陣頭表演，逐年擴大為融合了具國際性的高樁舞獅競賽、獨特的地方藝陣表演藝術。', `organizer`='高雄市政府', `address`='高雄市 苓雅區中正一路94巷1號', `start_date`='2025-11-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='高雄市 苓雅區中正一路94巷1號', `latitude`=22.628819, `longitude`=120.3350376, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081360/a410495bb2bd55e79ce03319cbf43f63359ffcd8.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('806', '南島族群婚禮', '本處轄區位於高屏山麓，在轄管的6個鄉區中，有5個鄉區為原住民地區，族群包含魯凱、排灣、布農及拉阿魯哇族等，呈現多元的原住民文化特色。為推廣本轄特有的原住民文化，帶動部落觀光發展，希望藉由「南島族群婚禮活動」之辦理，以原住民傳統婚禮為主軸，原鄉文化觀光組織為核心，運用觀光行銷手法，將婚禮活動包裝為具有文化特色的觀光活動，並以系列活動引導遊客漫遊高屏山麓，感受幸福原鄉。\r\n本婚禮主活動為排灣族、魯凱族的傳統貴族婚禮，其求婚、送採薪禮、豎鞦韆架、下聘、成婚等古禮儀式是排灣族、魯凱族獨特的文化，讓參與活動的新人們可以深度體驗原住民族傳統文化及婚禮，在部落族人及耆老共同見證下，遵循部落古禮完成人生大事，並藉觀光活動及套裝遊程的推動，讓遊客對於原住民文化有更多的了解與尊重。', '交通部觀光署茂林國家風景區管理處', '屏東縣 瑪家鄉2025年活動地點尚未確定', '2025-11-01 00:00:00', '2025-11-30 00:00:00', '屏東縣 瑪家鄉2025年活動地點尚未確定', 0, 0, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081456/79397120d560ff2e30033b889135a44af7c920c4.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='南島族群婚禮', `description`='本處轄區位於高屏山麓，在轄管的6個鄉區中，有5個鄉區為原住民地區，族群包含魯凱、排灣、布農及拉阿魯哇族等，呈現多元的原住民文化特色。為推廣本轄特有的原住民文化，帶動部落觀光發展，希望藉由「南島族群婚禮活動」之辦理，以原住民傳統婚禮為主軸，原鄉文化觀光組織為核心，運用觀光行銷手法，將婚禮活動包裝為具有文化特色的觀光活動，並以系列活動引導遊客漫遊高屏山麓，感受幸福原鄉。\r\n本婚禮主活動為排灣族、魯凱族的傳統貴族婚禮，其求婚、送採薪禮、豎鞦韆架、下聘、成婚等古禮儀式是排灣族、魯凱族獨特的文化，讓參與活動的新人們可以深度體驗原住民族傳統文化及婚禮，在部落族人及耆老共同見證下，遵循部落古禮完成人生大事，並藉觀光活動及套裝遊程的推動，讓遊客對於原住民文化有更多的了解與尊重。', `organizer`='交通部觀光署茂林國家風景區管理處', `address`='屏東縣 瑪家鄉2025年活動地點尚未確定', `start_date`='2025-11-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='屏東縣 瑪家鄉2025年活動地點尚未確定', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081456/79397120d560ff2e30033b889135a44af7c920c4.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('803', '台灣米倉田中馬拉松', '「台灣米倉田中馬拉松 Taiwan''s Rice Heaven－Tianzhong Marathon」自西元2012年開辦，打響國內外知名度，廣受國內外跑者民眾喜愛，並評價為臺灣經典賽事前三名，為國內外跑者來台指定參與賽事。', '彰化縣政府、中華民國舒康樂活運動協會、彰化縣馬拉松路跑協會', '彰化縣 田中鎮景崧文化教育園區', '2025-11-01 00:00:00', '2025-11-30 00:00:00', '彰化縣 田中鎮景崧文化教育園區', 23.8573781, 120.5816341, '無資料', 'https://www.tianzhongmarathon.com/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081440/8b33fa61762d9a31c7049f2050a1725b77e62f47.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='台灣米倉田中馬拉松', `description`='「台灣米倉田中馬拉松 Taiwan''s Rice Heaven－Tianzhong Marathon」自西元2012年開辦，打響國內外知名度，廣受國內外跑者民眾喜愛，並評價為臺灣經典賽事前三名，為國內外跑者來台指定參與賽事。', `organizer`='彰化縣政府、中華民國舒康樂活運動協會、彰化縣馬拉松路跑協會', `address`='彰化縣 田中鎮景崧文化教育園區', `start_date`='2025-11-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='彰化縣 田中鎮景崧文化教育園區', `latitude`=23.8573781, `longitude`=120.5816341, `ticket_price`='無資料', `source_url`='https://www.tianzhongmarathon.com/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081440/8b33fa61762d9a31c7049f2050a1725b77e62f47.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('794', 'Taiwan PASIWALI Festival原住民族國際音樂節', ' 「PASIWALI」是阿美族語，往東方的意思，東方是太陽升起的地方，也是孕育臺灣許多原住民族群的地方，便以「PASIWALI」為名，打造一場原住民族的音樂盛會，音樂節每年皆邀請國內外原住民族音樂人參與音樂節演出，持續的用音樂與國際交流，而音樂節現場設立部落屋、攤商市集及部落大跳舞，不僅呈現南島民族多元文化內涵，也讓參與活動民眾可認識更多原住民族文化的不同面向。\r\n\r\n     World Indigenous Tourism Summit (世界原住民族旅遊高峰會）\r\n', '原住民族委員會', '臺東縣 臺東市華泰路300號', '2025-11-01 00:00:00', '2025-11-30 00:00:00', '臺東縣 臺東市華泰路300號', 22.7634187, 121.1588754, '無資料', 'https://taiwanpasiwalifestival.com/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081425/afa548c8a7a2d7559d1972b25e25be7e510c2912.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='Taiwan PASIWALI Festival原住民族國際音樂節', `description`=' 「PASIWALI」是阿美族語，往東方的意思，東方是太陽升起的地方，也是孕育臺灣許多原住民族群的地方，便以「PASIWALI」為名，打造一場原住民族的音樂盛會，音樂節每年皆邀請國內外原住民族音樂人參與音樂節演出，持續的用音樂與國際交流，而音樂節現場設立部落屋、攤商市集及部落大跳舞，不僅呈現南島民族多元文化內涵，也讓參與活動民眾可認識更多原住民族文化的不同面向。\r\n\r\n     World Indigenous Tourism Summit (世界原住民族旅遊高峰會）\r\n', `organizer`='原住民族委員會', `address`='臺東縣 臺東市華泰路300號', `start_date`='2025-11-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='臺東縣 臺東市華泰路300號', `latitude`=22.7634187, `longitude`=121.1588754, `ticket_price`='無資料', `source_url`='https://taiwanpasiwalifestival.com/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081425/afa548c8a7a2d7559d1972b25e25be7e510c2912.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('796', '臺北白晝之夜', '「Nuit Blanche 白晝之夜」是2002年創始於法國巴黎，臺北市自2016年起舉辦，強調跨夜舉辦、免費參加及公民參與三大精神，透過多樣化藝術作品及演出安排，讓人自然接觸藝術，自由穿梭於城市空間中。', '臺北市政府文化局', '臺北市2025年活動地點尚未確定', '2025-11-01 00:00:00', '2025-11-30 00:00:00', '臺北市2025年活動地點尚未確定', 25.0296587, 121.5362867, '無資料', 'https://www.nuitblanche.taipei/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081427/111c44592f1ec3d0a20d572a66665ec7baccdfef.png"]') ON DUPLICATE KEY UPDATE `activity_name`='臺北白晝之夜', `description`='「Nuit Blanche 白晝之夜」是2002年創始於法國巴黎，臺北市自2016年起舉辦，強調跨夜舉辦、免費參加及公民參與三大精神，透過多樣化藝術作品及演出安排，讓人自然接觸藝術，自由穿梭於城市空間中。', `organizer`='臺北市政府文化局', `address`='臺北市2025年活動地點尚未確定', `start_date`='2025-11-01 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='臺北市2025年活動地點尚未確定', `latitude`=25.0296587, `longitude`=121.5362867, `ticket_price`='無資料', `source_url`='https://www.nuitblanche.taipei/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081427/111c44592f1ec3d0a20d572a66665ec7baccdfef.png"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('798', '臺北最HIGH新年城-跨年晚會', ' \r\n於臺北市政府前市民廣場舉辦大型展演活動，邀請國內外知名藝人及表演團體輪番表演，並搭配101新年大秀，與全世界民眾一起倒數迎向新年。\r\n ', '臺北市政府觀光傳播局、台北101', '臺北市 信義區臺北市市民廣場', '2025-12-01 00:00:00', '2025-12-31 00:00:00', '臺北市 信義區臺北市市民廣場', 25.0379213, 121.5631307, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081432/b30997358c34f5e4e1ce5f1d444617be826d8fad.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='臺北最HIGH新年城-跨年晚會', `description`=' \r\n於臺北市政府前市民廣場舉辦大型展演活動，邀請國內外知名藝人及表演團體輪番表演，並搭配101新年大秀，與全世界民眾一起倒數迎向新年。\r\n ', `organizer`='臺北市政府觀光傳播局、台北101', `address`='臺北市 信義區臺北市市民廣場', `start_date`='2025-12-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺北市 信義區臺北市市民廣場', `latitude`=25.0379213, `longitude`=121.5631307, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081432/b30997358c34f5e4e1ce5f1d444617be826d8fad.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('808', '阿里山四季茶旅活動', '阿里山四季茶旅活動係藉由培訓在地茶旅達人、茶旅體驗環境氛圍營造及行銷推廣活動，推廣阿里山好茶及多元品茗情境；四季茶會活動以二十四節氣為主題，結合在地茶旅達人司茶，伴著阿里山自然地景風貌（如：櫻花、螢火蟲、瀑布、竹林、森林、黃頭鷺、紫藤、雲瀑等），山林芬多精，品茗阿里山優質茶湯滋味；本計畫並將旅遊動線串連到產地製茶體驗、旅宿及品茗，開發多元茶品、茶輕食、茶文創商品，並搭配本處阿里山日產業展及國際旅展等聯合行銷茶旅遊程，提供國人與國際人士預約體驗深度茶之旅，形塑專屬阿里山茶文化體驗觀光品牌，促進阿里山茶文化、生態、產業等在地創生及深耕，活絡阿里山在地觀光產業，創造阿里山茶旅觀光產業整體效益與產值。', '交通部觀光署阿里山國家風景區管理處', '嘉義縣 梅山鄉圓潭自然生態園區', '2025-04-01 00:00:00', '2025-12-31 00:00:00', '嘉義縣 梅山鄉圓潭自然生態園區', 23.5289436, 120.6593311, '無資料', 'https://www.ali-nsa.net/zh-tw/event/calendardetail/3241', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081458/9695861ee05c12e2603df94619bd987e283d3996.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='阿里山四季茶旅活動', `description`='阿里山四季茶旅活動係藉由培訓在地茶旅達人、茶旅體驗環境氛圍營造及行銷推廣活動，推廣阿里山好茶及多元品茗情境；四季茶會活動以二十四節氣為主題，結合在地茶旅達人司茶，伴著阿里山自然地景風貌（如：櫻花、螢火蟲、瀑布、竹林、森林、黃頭鷺、紫藤、雲瀑等），山林芬多精，品茗阿里山優質茶湯滋味；本計畫並將旅遊動線串連到產地製茶體驗、旅宿及品茗，開發多元茶品、茶輕食、茶文創商品，並搭配本處阿里山日產業展及國際旅展等聯合行銷茶旅遊程，提供國人與國際人士預約體驗深度茶之旅，形塑專屬阿里山茶文化體驗觀光品牌，促進阿里山茶文化、生態、產業等在地創生及深耕，活絡阿里山在地觀光產業，創造阿里山茶旅觀光產業整體效益與產值。', `organizer`='交通部觀光署阿里山國家風景區管理處', `address`='嘉義縣 梅山鄉圓潭自然生態園區', `start_date`='2025-04-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='嘉義縣 梅山鄉圓潭自然生態園區', `latitude`=23.5289436, `longitude`=120.6593311, `ticket_price`='無資料', `source_url`='https://www.ali-nsa.net/zh-tw/event/calendardetail/3241', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081458/9695861ee05c12e2603df94619bd987e283d3996.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('774', '新社花海暨臺中國際花毯節', '新社花海暨臺中國際花毯節為中部地區最盛大的花卉慶典，逐年淬煉成為全臺首屈一指、具品牌知名度的花卉與休閒農業活動。推廣花卉產業是中臺灣的在地特色，藉由花卉裝置藝術、社區及在地產業協作，串連花草、農特產、觀光休閒等臺中特色產業，活絡地方商機，提升在地產業量能，深化社區營造，促進地方自立永續發展，帶動山城區域觀光產業鏈更加緊密，吸引各地及國際遊客參觀。', '臺中市政府、行政院農業部種苗改良繁殖場', '臺中市 新社區行政院農業部種苗改良繁殖場第二苗圃', '2025-11-01 00:00:00', '2025-12-31 00:00:00', '臺中市 新社區行政院農業部種苗改良繁殖場第二苗圃', 24.2032599, 120.8059929, '無資料', 'https://www.facebook.com/xinsheflowersea/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081391/dc952669303627a20d31e57a4748ed633c9358e9.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='新社花海暨臺中國際花毯節', `description`='新社花海暨臺中國際花毯節為中部地區最盛大的花卉慶典，逐年淬煉成為全臺首屈一指、具品牌知名度的花卉與休閒農業活動。推廣花卉產業是中臺灣的在地特色，藉由花卉裝置藝術、社區及在地產業協作，串連花草、農特產、觀光休閒等臺中特色產業，活絡地方商機，提升在地產業量能，深化社區營造，促進地方自立永續發展，帶動山城區域觀光產業鏈更加緊密，吸引各地及國際遊客參觀。', `organizer`='臺中市政府、行政院農業部種苗改良繁殖場', `address`='臺中市 新社區行政院農業部種苗改良繁殖場第二苗圃', `start_date`='2025-11-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺中市 新社區行政院農業部種苗改良繁殖場第二苗圃', `latitude`=24.2032599, `longitude`=120.8059929, `ticket_price`='無資料', `source_url`='https://www.facebook.com/xinsheflowersea/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081391/dc952669303627a20d31e57a4748ed633c9358e9.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('833', '高山茶都-嘉義博茶會', '嘉義的茶文化產業豐富且興盛，阿里山茶葉更是為國內外所盛讚的經典茗茶，與茶產業共生共長的還有深厚的茶文化涵養，結合嘉義縣精緻工藝與豐美農特產，讓遊客滿載而歸。\r\n嘉義縣除了傑出的茶文化產業引人入勝外，本活動亦結合本縣豐饒的農特產品、得天獨厚的優美景觀、珍貴精緻的工藝品，多元且全面的展現嘉義縣的優質條件，吸引各地旅客再三來訪。', '嘉義縣政府', '嘉義縣 中埔鄉中埔鄉農會金蘭分部', '2025-12-01 00:00:00', '2025-12-31 00:00:00', '嘉義縣 中埔鄉中埔鄉農會金蘭分部', 23.4470255, 120.4927796, '無資料', 'https://www.facebook.com/tbocc01/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081508/4338f0b2c5cd64eddd410daf3dddef868ffb2cb2.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='高山茶都-嘉義博茶會', `description`='嘉義的茶文化產業豐富且興盛，阿里山茶葉更是為國內外所盛讚的經典茗茶，與茶產業共生共長的還有深厚的茶文化涵養，結合嘉義縣精緻工藝與豐美農特產，讓遊客滿載而歸。\r\n嘉義縣除了傑出的茶文化產業引人入勝外，本活動亦結合本縣豐饒的農特產品、得天獨厚的優美景觀、珍貴精緻的工藝品，多元且全面的展現嘉義縣的優質條件，吸引各地旅客再三來訪。', `organizer`='嘉義縣政府', `address`='嘉義縣 中埔鄉中埔鄉農會金蘭分部', `start_date`='2025-12-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='嘉義縣 中埔鄉中埔鄉農會金蘭分部', `latitude`=23.4470255, `longitude`=120.4927796, `ticket_price`='無資料', `source_url`='https://www.facebook.com/tbocc01/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081508/4338f0b2c5cd64eddd410daf3dddef868ffb2cb2.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('848', '六堆秋收祭系列活動', '客家人利用「春祈、夏耘、秋收、冬藏」大自然時序變化，來調整一年作息的生活方式，是代代相傳的優美文化，而每年十月底十一月初正是豐收的時節，各地均會酬神以慶祝一年一度秋收祭的到來。系列活動包含伯公祈福廠暨還福祭儀、六堆逗鬧熱踩街遊園開幕式、特色野餐饗宴、客家美食小棧、食福宴暨晚會等，活動場地以六堆客家文化園區為中心延伸到六堆12鄉區。', '客家委員會客家文化發展中心', '屏東縣 內埔鄉信義路588號', '2025-11-01 00:00:00', '2025-12-31 00:00:00', '屏東縣 內埔鄉信義路588號', 22.6584186, 120.5588158, '無資料', 'https://www.facebook.com/liuduihakka/?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081539/43b019a27d31ce9a87054642addd32505c6101d3.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='六堆秋收祭系列活動', `description`='客家人利用「春祈、夏耘、秋收、冬藏」大自然時序變化，來調整一年作息的生活方式，是代代相傳的優美文化，而每年十月底十一月初正是豐收的時節，各地均會酬神以慶祝一年一度秋收祭的到來。系列活動包含伯公祈福廠暨還福祭儀、六堆逗鬧熱踩街遊園開幕式、特色野餐饗宴、客家美食小棧、食福宴暨晚會等，活動場地以六堆客家文化園區為中心延伸到六堆12鄉區。', `organizer`='客家委員會客家文化發展中心', `address`='屏東縣 內埔鄉信義路588號', `start_date`='2025-11-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='屏東縣 內埔鄉信義路588號', `latitude`=22.6584186, `longitude`=120.5588158, `ticket_price`='無資料', `source_url`='https://www.facebook.com/liuduihakka/?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081539/43b019a27d31ce9a87054642addd32505c6101d3.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('815', '草嶺古道芒花季', '為讓遊客欣賞大片芒花壯闊盛開之景，感受草嶺古道那段跨越百年山海時光長廊的記憶，自2002年開始舉辦，每年度總吸引約8萬人次遊客前往欣賞滿山芒花搖曳的迷人風采，近年來已成為東北角地區觀光旅遊品牌活動。', '交通部觀光署東北角及宜蘭海岸國家風景區管理處', '新北市 貢寮區草嶺古道', '2025-11-01 00:00:00', '2025-12-31 00:00:00', '新北市 貢寮區草嶺古道', 24.9900071, 121.9253726, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081472/188177f01852154eab28a77efba87834dbb89da6.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='草嶺古道芒花季', `description`='為讓遊客欣賞大片芒花壯闊盛開之景，感受草嶺古道那段跨越百年山海時光長廊的記憶，自2002年開始舉辦，每年度總吸引約8萬人次遊客前往欣賞滿山芒花搖曳的迷人風采，近年來已成為東北角地區觀光旅遊品牌活動。', `organizer`='交通部觀光署東北角及宜蘭海岸國家風景區管理處', `address`='新北市 貢寮區草嶺古道', `start_date`='2025-11-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='新北市 貢寮區草嶺古道', `latitude`=24.9900071, `longitude`=121.9253726, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081472/188177f01852154eab28a77efba87834dbb89da6.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('822', '台東光祭', '匯集12件國際級聲光藝術，敘述在地情感與人文故事，邀集包括國際知名法國聲光藝術團隊Groupe Laps與在地卑南族藝術家伊命&bull;瑪法琉等，國內外12組藝界舉足輕重的藝術家團隊於知本溫泉區現地創作，分別在樹林間、草地上，創作出夢幻詩意且令人驚艷的聲光藝術作品。除了藝術展示外，亦辦理主題工作坊及在地餐桌計畫。', '臺東縣政府文化處', '臺東縣 卑南鄉知本溫泉區', '2025-10-01 00:00:00', '2025-12-31 00:00:00', '臺東縣 卑南鄉知本溫泉區', 22.69305751, 121.01812132, '無資料', 'https://www.facebook.com/TaitungLightFestival', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081497/130897788f088f8b670e371e158326166269586f.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='台東光祭', `description`='匯集12件國際級聲光藝術，敘述在地情感與人文故事，邀集包括國際知名法國聲光藝術團隊Groupe Laps與在地卑南族藝術家伊命&bull;瑪法琉等，國內外12組藝界舉足輕重的藝術家團隊於知本溫泉區現地創作，分別在樹林間、草地上，創作出夢幻詩意且令人驚艷的聲光藝術作品。除了藝術展示外，亦辦理主題工作坊及在地餐桌計畫。', `organizer`='臺東縣政府文化處', `address`='臺東縣 卑南鄉知本溫泉區', `start_date`='2025-10-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺東縣 卑南鄉知本溫泉區', `latitude`=22.69305751, `longitude`=121.01812132, `ticket_price`='無資料', `source_url`='https://www.facebook.com/TaitungLightFestival', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081497/130897788f088f8b670e371e158326166269586f.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('868', '山谷燈光節', '歲末年初佳節歡樂氣氛，利用梨山賓館前兩棵具有歷史意義的雪松，打造成為「全臺最高聖誕樹」活動亮點及活動品牌，於谷關梨山街區布置光環境燈飾，結合在地原民與部落元素，配合特色展演活動，展現梨山谷關之美。', '參山國家風景區管理處', '臺中市 和平區梨山賓館前廣場', '2025-11-01 00:00:00', '2025-12-31 00:00:00', '臺中市 和平區梨山賓館前廣場', 24.254294, 121.251584, '無資料', 'https://www.trimt-nsa.gov.tw/zh-tw/news/5856/', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081584/dbe24cee033be2800923c21a61aac0ff2ffedaa3.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='山谷燈光節', `description`='歲末年初佳節歡樂氣氛，利用梨山賓館前兩棵具有歷史意義的雪松，打造成為「全臺最高聖誕樹」活動亮點及活動品牌，於谷關梨山街區布置光環境燈飾，結合在地原民與部落元素，配合特色展演活動，展現梨山谷關之美。', `organizer`='參山國家風景區管理處', `address`='臺中市 和平區梨山賓館前廣場', `start_date`='2025-11-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺中市 和平區梨山賓館前廣場', `latitude`=24.254294, `longitude`=121.251584, `ticket_price`='無資料', `source_url`='https://www.trimt-nsa.gov.tw/zh-tw/news/5856/', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081584/dbe24cee033be2800923c21a61aac0ff2ffedaa3.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('793', '龍崎光節空山祭', '「龍崎光節&mdash;空山祭」以龍崎區虎形山公園為基地，展出由藝術家與社區居民、生活環境互動交流、共創的藝術裝置作品，每件作品皆為現地創作，激盪出專屬於龍崎山林的浪漫夜晚。同時，龍崎光節以關注地方議題模式策展，發掘龍崎過去被低估的在地價值，並以藝術擾動地方，將文化節慶節和地方社群結合，翻轉龍崎，振興地方，展現屬於南關線的獨特魅力。', '臺南市政府文化局', '臺南市 龍崎區虎形山公園', '2025-12-01 00:00:00', '2026-02-28 00:00:00', '臺南市 龍崎區虎形山公園', 22.9645328, 120.3598256, '無資料', 'https://www.facebook.com/longcilightfestival', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081424/9997abd40b5e9f56c452a38601bb4994ad3f05d8.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='龍崎光節空山祭', `description`='「龍崎光節&mdash;空山祭」以龍崎區虎形山公園為基地，展出由藝術家與社區居民、生活環境互動交流、共創的藝術裝置作品，每件作品皆為現地創作，激盪出專屬於龍崎山林的浪漫夜晚。同時，龍崎光節以關注地方議題模式策展，發掘龍崎過去被低估的在地價值，並以藝術擾動地方，將文化節慶節和地方社群結合，翻轉龍崎，振興地方，展現屬於南關線的獨特魅力。', `organizer`='臺南市政府文化局', `address`='臺南市 龍崎區虎形山公園', `start_date`='2025-12-01 00:00:00', `end_date`='2026-02-28 00:00:00', `location`='臺南市 龍崎區虎形山公園', `latitude`=22.9645328, `longitude`=120.3598256, `ticket_price`='無資料', `source_url`='https://www.facebook.com/longcilightfestival', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081424/9997abd40b5e9f56c452a38601bb4994ad3f05d8.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES (1, '喧囂的孤獨：臺灣膠彩百年尋道', '臺灣歷經不同的政治社會發展時期，使膠彩畫在定名及定位上有諸多複雜的擺盪，也影響其傳承發展，先後經歷日治時期日本畫技的初期傳播及二戰後的私塾師徒制傳承，至大學系所開設膠彩畫課程後，接引起新一波膠彩畫學習與創作發展。本次展覽以膠彩畫在材質與繪畫追求上既東可西的特質為本，依循官辦美展及與教育體制的時間軸線概括其發展處境與面對方式，呈現膠彩畫在臺灣落地化的表現樣貌。透過藝術家及其創作聚合的臺灣膠彩畫發展圖譜，察見臺灣膠彩畫自原生來源與外在刺激的吸納及反芻中重新詮釋出新樣貌，尋找創作之道的進程擺盪在東西繪畫表現之間。', '臺北市立美術館', '臺北市中山區中山北路三段181號', '臺北市立美術館', 25.072943, 121.524536, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='喧囂的孤獨：臺灣膠彩百年尋道', `description`='臺灣歷經不同的政治社會發展時期，使膠彩畫在定名及定位上有諸多複雜的擺盪，也影響其傳承發展，先後經歷日治時期日本畫技的初期傳播及二戰後的私塾師徒制傳承，至大學系所開設膠彩畫課程後，接引起新一波膠彩畫學習與創作發展。本次展覽以膠彩畫在材質與繪畫追求上既東可西的特質為本，依循官辦美展及與教育體制的時間軸線概括其發展處境與面對方式，呈現膠彩畫在臺灣落地化的表現樣貌。透過藝術家及其創作聚合的臺灣膠彩畫發展圖譜，察見臺灣膠彩畫自原生來源與外在刺激的吸納及反芻中重新詮釋出新樣貌，尋找創作之道的進程擺盪在東西繪畫表現之間。', `organizer`='臺北市立美術館', `address`='臺北市中山區中山北路三段181號', `location`='臺北市立美術館', `latitude`=25.072943, `longitude`=121.524536, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES (2, '開放式結局：TFAM放映計畫', '「所以，你的故事終究有個美好的結局了?」作家這麼問著。「這得看你怎麼想。」PI這樣回答。──少年PI的奇幻漂流「開放式結局」意指一則沒有提供結論的故事，一條未知終點的道路，它可以在文學及戲劇文本中留下懸念，同時將自由詮釋的空間交給觀者，讓故事不僅僅是傳統觀看經驗裡被強加灌輸的答案藍本，而是他們與創作者間的雙向對話。就像導演李安於《少年PI的奇幻漂流》一片結尾，通過主角PI之口對作家∕鏡外觀者道出的問題：「你喜歡哪一個故事？」今年秋天，北美館嘗試翻轉博物館白盒子空間，在地下樓打造一座獨特的藝術影院。通過跨領域策展合作，我們邀請亞歐為主之重量級影像藝術家暨電影導演，並以「類影展」型態為觀者精選、呈現多部難得一見的單頻道影片作品。其中包括鮮少曝光之錄像藝術作品、短片、紀錄片、藝術電影、實驗電影、動畫短片&hellip;&hellip;等。有別於大眾熟知的劇情長片，這類作品往往不具特定情節走向、強烈的情感渲染，更多是對當代議題的留白反思，以及對各種影像實驗性手法之解鎖與探究。「開放式結局：TFAM放映計畫」試圖從廣為人知的電影∕戲劇概念切入，通過帶狀展出期程內不同主題、片單的組合呈現，期望開放出更多的想像與可能性，這裡的「開放」除了是對觀者詮釋的寬容外，更可以是一種對影像形式手法的解構，對另類浪潮的致敬，以及對藝術定義的不設限。在這空間裡，故事由導演與藝術家們撰寫，而故事的結尾就交由你來定義。&emsp;主辦單位：臺北市立美術館策展團隊：簡正怡、曾炫淳、林木材、黃聖閎&nbsp;單元簡介：羊皮紙 &nbsp; (放映日期：2024.10.12－12.29)此展廳就像複寫紙，一間複寫的空間，像古時取來反覆銘刻、刮除、再重寫的羊皮紙。混雜了因擦除而遺留的殘跡，與在其上覆寫的印記，新與舊的多重疊印、融接、重組起複數的意涵。這張羊皮紙上投映的，不只是每件影像作品內在所涉入對歷史、記憶的對話，及其消解敘事性的頑抗，還有這些作品在電影院、在影展、在美術館各式空間所衍生出多重版本之間的蒙太奇，以及每件作品之間互通聲息的藝術實驗，終在所有被識讀的過程中，彼此引述、滲透和被對讀。尚盧‧高達｜電影史精選時刻蔡明亮｜你的臉蔡明亮｜是夢蔡明亮｜化生蔡明亮｜漫不經心楊福東｜陌生天堂陳界仁｜殘響世界白噪音 &nbsp; (放映日期：2024.10.12－12.29) &nbsp;&nbsp;「白噪音」意指一個空間裡所有的動作所發表的各種音頻噪音之總合，也包括為壓制這些噪音而產生的聲音。本專題以美國文學家唐．德里羅 (Don Delillo)於1985年出版之小說《白噪音》為靈感，通過精選亞洲導演／藝術家獨具特色之長、短片作品，思索人類面對當代處境的種種掙扎與矛盾：資訊的氾濫、環境變遷及迫近的威脅、科技帶來的進步與毀滅、生存與死亡、同化與抵抗&hellip;&hellip;，一幕幕熟悉卻荒誕風景宛如縈繞不去的白噪音，我們該如何回應？又是否有可能自這扭曲迷亂的聲場中遁逃，尋回最寧靜的初心？鍾孟宏｜逃亡鍾孟宏｜驅魔鍾孟宏｜慶典荒木悠｜炉趙亮｜無去來處蘇匯宇｜未來的衝擊－永恆的消逝蘇匯宇｜未來的衝擊曹斐｜霾阮純詩｜賓童龍的來信螺旋槳小組｜生者要光，死者賞樂', '臺北市立美術館', '臺北市中山區中山北路三段181號', '臺北市立美術館', 25.072943, 121.524536, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='開放式結局：TFAM放映計畫', `description`='「所以，你的故事終究有個美好的結局了?」作家這麼問著。「這得看你怎麼想。」PI這樣回答。──少年PI的奇幻漂流「開放式結局」意指一則沒有提供結論的故事，一條未知終點的道路，它可以在文學及戲劇文本中留下懸念，同時將自由詮釋的空間交給觀者，讓故事不僅僅是傳統觀看經驗裡被強加灌輸的答案藍本，而是他們與創作者間的雙向對話。就像導演李安於《少年PI的奇幻漂流》一片結尾，通過主角PI之口對作家∕鏡外觀者道出的問題：「你喜歡哪一個故事？」今年秋天，北美館嘗試翻轉博物館白盒子空間，在地下樓打造一座獨特的藝術影院。通過跨領域策展合作，我們邀請亞歐為主之重量級影像藝術家暨電影導演，並以「類影展」型態為觀者精選、呈現多部難得一見的