INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9361218', '[轉知]打詐臺北隊114年2月份反詐宣導', '警惕假買家詐騙！勿輕信「開通金融協議」或「測試轉帳」要求，避免依指示操作ATM或網銀，以免受騙。', '臺北市政府工務局衛生下水道工程處', '無資料', '2025-02-21 00:00:00', '2025-03-11 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=340CEB4B3D6830EA', '[]') ON DUPLICATE KEY UPDATE `activity_name`='[轉知]打詐臺北隊114年2月份反詐宣導', `description`='警惕假買家詐騙！勿輕信「開通金融協議」或「測試轉帳」要求，避免依指示操作ATM或網銀，以免受騙。', `organizer`='臺北市政府工務局衛生下水道工程處', `address`='無資料', `start_date`='2025-02-21 00:00:00', `end_date`='2025-03-11 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=340CEB4B3D6830EA', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9350753', '天文魔法小書包(3/1)', '臺北天文館推出融入STEAM教育的「天文魔法小書包」活動，讓親子跟隨著專業解說員，體驗展場好玩的展品，搭乘宇宙探險車遨遊太陽系，並完成科學教具動手做，透過輕鬆有趣的方式學習天文，共享親子間美好的共學時光。活動時間：3月1日（六）14:00-16:00。活動對象：親子（家長、幼稚園大班至國小四年級以下學童皆可）。活動地點：展示場、宇宙探險。活動費用：本活動須購買展示場、宇宙探險門票 ，票價請參閱購票資訊。報名方式：線上報名。注意事項：家長及孩童皆需報名（每張表單僅填一名參加者），每場次以50位親子為限，額滿為止。如有餘額則開放合乎資格之現場民眾參加。活動一週前，接受網路預約報名。洽詢電話：02-28314551轉706展示組陳小姐。「天文魔法小書包」活動流程表時間活動內容活動地點14:00-14:15報到中庭服務台14:15-15:00搭乘軌道車、主題導覽展示場、4F宇宙探險15:00-16:00DIY課程展示場1F天文教室16:00活動證請交還工作人員如有疑問，請找現場服務人員。', '臺北市立天文科學教育館', '無資料', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=6B9DC03B766E95BC', '[]') ON DUPLICATE KEY UPDATE `activity_name`='天文魔法小書包(3/1)', `description`='臺北天文館推出融入STEAM教育的「天文魔法小書包」活動，讓親子跟隨著專業解說員，體驗展場好玩的展品，搭乘宇宙探險車遨遊太陽系，並完成科學教具動手做，透過輕鬆有趣的方式學習天文，共享親子間美好的共學時光。活動時間：3月1日（六）14:00-16:00。活動對象：親子（家長、幼稚園大班至國小四年級以下學童皆可）。活動地點：展示場、宇宙探險。活動費用：本活動須購買展示場、宇宙探險門票 ，票價請參閱購票資訊。報名方式：線上報名。注意事項：家長及孩童皆需報名（每張表單僅填一名參加者），每場次以50位親子為限，額滿為止。如有餘額則開放合乎資格之現場民眾參加。活動一週前，接受網路預約報名。洽詢電話：02-28314551轉706展示組陳小姐。「天文魔法小書包」活動流程表時間活動內容活動地點14:00-14:15報到中庭服務台14:15-15:00搭乘軌道車、主題導覽展示場、4F宇宙探險15:00-16:00DIY課程展示場1F天文教室16:00活動證請交還工作人員如有疑問，請找現場服務人員。', `organizer`='臺北市立天文科學教育館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=6B9DC03B766E95BC', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9360598', '總館吳大猷科學沙龍-6/21(六)「從蟹狀星雲談黑洞與重力波」，歡迎參加！', '在金牛座，有一團著名的蟹狀星雲，它的形狀不斷變化，引起了天文學家的關注。透過對蟹狀星雲的研究，科學家能將古代觀測紀錄與現代科技結合，探索宇宙的奧秘。而近期備受關注的黑洞與重力波研究，與這類的星雲密切相關。讓我們一起穿越時空，看看天文學家如何用歷史與科技拼湊出宇宙的故事！歡迎對主題有興趣的您蒞館參加！【從蟹狀星雲談黑洞與重力波】講座資訊時間：6月21日（六）10時至12時講者：黃麗錦（中原大學通識教育中心兼任教師）地點：臺北市立圖書館總館10樓國際會議廳/大安區建國南路2段125號本活動不需報名，自由入場，敬請提早入座全程參與者提供公務人員終身學習認證時數2小時及閱讀存摺點數5點', '臺北市立圖書館', '無資料', '2025-02-21 00:00:00', '2025-06-21 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=23205D0546A8B0EC', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館吳大猷科學沙龍-6/21(六)「從蟹狀星雲談黑洞與重力波」，歡迎參加！', `description`='在金牛座，有一團著名的蟹狀星雲，它的形狀不斷變化，引起了天文學家的關注。透過對蟹狀星雲的研究，科學家能將古代觀測紀錄與現代科技結合，探索宇宙的奧秘。而近期備受關注的黑洞與重力波研究，與這類的星雲密切相關。讓我們一起穿越時空，看看天文學家如何用歷史與科技拼湊出宇宙的故事！歡迎對主題有興趣的您蒞館參加！【從蟹狀星雲談黑洞與重力波】講座資訊時間：6月21日（六）10時至12時講者：黃麗錦（中原大學通識教育中心兼任教師）地點：臺北市立圖書館總館10樓國際會議廳/大安區建國南路2段125號本活動不需報名，自由入場，敬請提早入座全程參與者提供公務人員終身學習認證時數2小時及閱讀存摺點數5點', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-21 00:00:00', `end_date`='2025-06-21 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=23205D0546A8B0EC', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9360593', '總館吳大猷科學沙龍-6/8(日)「實用天文觀星指南」，歡迎參加！', '走出戶外，仰望星空，總讓人深刻體會宇宙的浩瀚與人類的渺小。自古以來，我們對夜空的好奇與探索從未停歇。在這場講座中，我們將以輕鬆有趣、深入淺出的方式，帶您了解如何觀賞銀河、深空天體、流星雨、日全食等壯麗天文現象，並分享實用的觀星技巧與建議。讓我們一同踏入星空的奇幻世界，發掘更多迷人的景象與無窮樂趣！歡迎對主題有興趣的您蒞館參加！【實用天文觀星指南】講座資訊時間：6月8日（日）10時至12時講者：胡佳伶（前臺北市立天文科學教育館解說員）地點：臺北市立圖書館總館10樓國際會議廳/大安區建國南路2段125號本活動不需報名，自由入場，敬請提早入座全程參與者提供公務人員終身學習認證時數2小時及閱讀存摺點數5點', '臺北市立圖書館', '無資料', '2025-02-21 00:00:00', '2025-06-08 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8F0C1596154C2AA7', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館吳大猷科學沙龍-6/8(日)「實用天文觀星指南」，歡迎參加！', `description`='走出戶外，仰望星空，總讓人深刻體會宇宙的浩瀚與人類的渺小。自古以來，我們對夜空的好奇與探索從未停歇。在這場講座中，我們將以輕鬆有趣、深入淺出的方式，帶您了解如何觀賞銀河、深空天體、流星雨、日全食等壯麗天文現象，並分享實用的觀星技巧與建議。讓我們一同踏入星空的奇幻世界，發掘更多迷人的景象與無窮樂趣！歡迎對主題有興趣的您蒞館參加！【實用天文觀星指南】講座資訊時間：6月8日（日）10時至12時講者：胡佳伶（前臺北市立天文科學教育館解說員）地點：臺北市立圖書館總館10樓國際會議廳/大安區建國南路2段125號本活動不需報名，自由入場，敬請提早入座全程參與者提供公務人員終身學習認證時數2小時及閱讀存摺點數5點', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-21 00:00:00', `end_date`='2025-06-08 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8F0C1596154C2AA7', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9360590', '總館吳大猷科學沙龍-5/3(六)「我們和宇宙邊緣的距離」，歡迎參加！', '隨著科學的發展，我們有越來越多的方法能測量天體的距離，這些方法都是站在巨人的肩膀上才得以發現的，這其中常有許多有趣的故事，讓我們一起隨著天文學的發展史，一步一步地朝向宇宙的邊緣邁進。歡迎對主題有興趣的您蒞館參加！【我們和宇宙邊緣的距離】講座資訊時間：5月3日（六）10時至12時講者：顏鴻選（星天日和工作室執行長）地點：臺北市立圖書館總館10樓國際會議廳/大安區建國南路2段125號本活動不需報名，自由入場，敬請提早入座全程參與者提供公務人員終身學習認證時數2小時及閱讀存摺點數5點', '臺北市立圖書館', '無資料', '2025-02-21 00:00:00', '2025-05-03 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=04A3E564BD91640E', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館吳大猷科學沙龍-5/3(六)「我們和宇宙邊緣的距離」，歡迎參加！', `description`='隨著科學的發展，我們有越來越多的方法能測量天體的距離，這些方法都是站在巨人的肩膀上才得以發現的，這其中常有許多有趣的故事，讓我們一起隨著天文學的發展史，一步一步地朝向宇宙的邊緣邁進。歡迎對主題有興趣的您蒞館參加！【我們和宇宙邊緣的距離】講座資訊時間：5月3日（六）10時至12時講者：顏鴻選（星天日和工作室執行長）地點：臺北市立圖書館總館10樓國際會議廳/大安區建國南路2段125號本活動不需報名，自由入場，敬請提早入座全程參與者提供公務人員終身學習認證時數2小時及閱讀存摺點數5點', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-21 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=04A3E564BD91640E', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9360585', '總館吳大猷科學沙龍-3/23(日)「小行星撞地球：致命的撞擊」，歡迎參加！', '太陽系裡有些小行星的軌道靠近地球，它們有撞上地球的可能。如果小行星撞上地球，將造成毀滅性的災難，人類要如何防範這個來自外太空的「天災」呢？歡迎對主題有興趣的您蒞館參加！【小行星撞地球：致命的撞擊】講座資訊時間：3月23日（日）10時至12時講者：李昫岱（中正大學兼任助理教授）地點：臺北市立圖書館總館10樓國際會議廳/大安區建國南路2段125號本活動不需報名，自由入場，敬請提早入座全程參與者提供公務人員終身學習認證時數2小時及閱讀存摺點數5點', '臺北市立圖書館', '無資料', '2025-02-21 00:00:00', '2025-03-23 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C44DBDEAFF38F699', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館吳大猷科學沙龍-3/23(日)「小行星撞地球：致命的撞擊」，歡迎參加！', `description`='太陽系裡有些小行星的軌道靠近地球，它們有撞上地球的可能。如果小行星撞上地球，將造成毀滅性的災難，人類要如何防範這個來自外太空的「天災」呢？歡迎對主題有興趣的您蒞館參加！【小行星撞地球：致命的撞擊】講座資訊時間：3月23日（日）10時至12時講者：李昫岱（中正大學兼任助理教授）地點：臺北市立圖書館總館10樓國際會議廳/大安區建國南路2段125號本活動不需報名，自由入場，敬請提早入座全程參與者提供公務人員終身學習認證時數2小時及閱讀存摺點數5點', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-21 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C44DBDEAFF38F699', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9354009', '三興分館「單人舞讀書會（34）」', '一、活動目的：藉由「閱讀」引領著你我遊歷各類各式精采人生。二、活動內容：閱讀《給予：華頓商學院最啟發人心的一堂課》、《依賴陷阱》兩本書籍，討論電影《那個男人》與參加戶外藝文活動。三、活動時間：2月21日起至6月27日止，每月第一、三、四週的週五上午10時至12時。四、活動地點：臺北市立圖書館三興分館5樓會議室。五、參加對象：凡對閱讀分享有興趣的朋友。六、活動費用：免費。七、報名方式：自由參加。', '臺北市立圖書館', '無資料', '2025-02-21 00:00:00', '2025-06-27 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=AE350F5CEABF3A41', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三興分館「單人舞讀書會（34）」', `description`='一、活動目的：藉由「閱讀」引領著你我遊歷各類各式精采人生。二、活動內容：閱讀《給予：華頓商學院最啟發人心的一堂課》、《依賴陷阱》兩本書籍，討論電影《那個男人》與參加戶外藝文活動。三、活動時間：2月21日起至6月27日止，每月第一、三、四週的週五上午10時至12時。四、活動地點：臺北市立圖書館三興分館5樓會議室。五、參加對象：凡對閱讀分享有興趣的朋友。六、活動費用：免費。七、報名方式：自由參加。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-21 00:00:00', `end_date`='2025-06-27 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=AE350F5CEABF3A41', `image_url`='[]';
