INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9360619', '【轉知】中華帕拉林匹克總會辦理「114年全國視覺障礙者柔道訓練營」活動', '主辦單位：中華帕拉林匹克總會承辦單位：臺北市大理高級中學、中華民國帕拉林匹克視障運動協會活動時程：(一)活動日期：114年3月7日至114年5月30日止，共10堂課(確切課程日期詳見下方課程表）。(二)活動時間：每周五15點至18點、周日為13點至16點。(會因狀況更動時間)活動地點：臺北市大理高級中學學生活動中心、臺北啟明學校柔道場參與對象：(一) 具中華民國國籍且持有身心障礙證明者（視覺障礙）。(二) 報名參加2025雙北世壯運視障柔道項目者優先報名 。(三) 未滿 18歲之學員需有一位陪同人員（直系親屬或法定代理人）。報名資訊：(一)報名日期：即日起至114年2月28日17:00止 (若額滿則提前截止 )。(二)報名方式：臺北市立大理高級中學 杜天佑 老師 (電話 :0936864778 )詳細資訊請參照附件實施辦法。', '臺北市政府體育局', '無資料', '2025-02-20 00:00:00', '2025-02-28 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=0A36EF0353896EE4', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【轉知】中華帕拉林匹克總會辦理「114年全國視覺障礙者柔道訓練營」活動', `description`='主辦單位：中華帕拉林匹克總會承辦單位：臺北市大理高級中學、中華民國帕拉林匹克視障運動協會活動時程：(一)活動日期：114年3月7日至114年5月30日止，共10堂課(確切課程日期詳見下方課程表）。(二)活動時間：每周五15點至18點、周日為13點至16點。(會因狀況更動時間)活動地點：臺北市大理高級中學學生活動中心、臺北啟明學校柔道場參與對象：(一) 具中華民國國籍且持有身心障礙證明者（視覺障礙）。(二) 報名參加2025雙北世壯運視障柔道項目者優先報名 。(三) 未滿 18歲之學員需有一位陪同人員（直系親屬或法定代理人）。報名資訊：(一)報名日期：即日起至114年2月28日17:00止 (若額滿則提前截止 )。(二)報名方式：臺北市立大理高級中學 杜天佑 老師 (電話 :0936864778 )詳細資訊請參照附件實施辦法。', `organizer`='臺北市政府體育局', `address`='無資料', `start_date`='2025-02-20 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=0A36EF0353896EE4', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9360534', '114年臺北市中山區整合性預防保健服務場次', '您是否做過成人健檢及癌症篩檢嗎?請您使用健保快易通App查詢資格，如您有符合成人健康檢查資格，請您選擇一場有空的時間來參加，請您檢查前8小時空腹，歡迎踴躍參加!~歡迎轉傳親友~', '臺北市中山區健康服務中心', '無資料', '2025-02-01 00:00:00', '2025-08-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=BDEA481D73459FB0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年臺北市中山區整合性預防保健服務場次', `description`='您是否做過成人健檢及癌症篩檢嗎?請您使用健保快易通App查詢資格，如您有符合成人健康檢查資格，請您選擇一場有空的時間來參加，請您檢查前8小時空腹，歡迎踴躍參加!~歡迎轉傳親友~', `organizer`='臺北市中山區健康服務中心', `address`='無資料', `start_date`='2025-02-01 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=BDEA481D73459FB0', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9360439', '樂齡談天活動【 24節氣＆「1年」是怎麼定出來的？】', '又到了春分這個重要的節氣，您是否好奇為什麼春分當天，白天和晚上的時間長度恰好相等？一年之中24節氣的日期是怎麼決定的？而一年的時間長度又是怎麼確認的呢？這些都和太陽與地球的相對運動有關。如果各位樂齡的朋友們(滿55歲)，想知道24節氣和「1年」是怎麼定出來的？歡迎親臨臺北天文館，除可以讓您了解一年之中節氣制定的方式，還可欣賞立體劇場，並由專人帶領進行展示場導覽。&nbsp;參加對象：年滿55歲以上之樂齡朋友，以活動當天年滿55歲為準（報到時請攜帶身份證件）。活動時間：114年3月21日（五）09:00-11:40。報名日期：114年2月27日（四）09:00起電話報名（每通電話僅能報名2位），名額40人，額滿為止。報名電話：02-28314551轉204。活動費用：免費。活動流程及其他注意事項：請參閱活動簡章。', '臺北市立天文科學教育館', '臺北市士林區基河路363號', '2025-03-21 00:00:00', '2025-03-21 00:00:00', '臺北天文館', 25.12546704, 121.5508473, '免費', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8A5A19B2D10C4827', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樂齡談天活動【 24節氣＆「1年」是怎麼定出來的？】', `description`='又到了春分這個重要的節氣，您是否好奇為什麼春分當天，白天和晚上的時間長度恰好相等？一年之中24節氣的日期是怎麼決定的？而一年的時間長度又是怎麼確認的呢？這些都和太陽與地球的相對運動有關。如果各位樂齡的朋友們(滿55歲)，想知道24節氣和「1年」是怎麼定出來的？歡迎親臨臺北天文館，除可以讓您了解一年之中節氣制定的方式，還可欣賞立體劇場，並由專人帶領進行展示場導覽。&nbsp;參加對象：年滿55歲以上之樂齡朋友，以活動當天年滿55歲為準（報到時請攜帶身份證件）。活動時間：114年3月21日（五）09:00-11:40。報名日期：114年2月27日（四）09:00起電話報名（每通電話僅能報名2位），名額40人，額滿為止。報名電話：02-28314551轉204。活動費用：免費。活動流程及其他注意事項：請參閱活動簡章。', `organizer`='臺北市立天文科學教育館', `address`='臺北市士林區基河路363號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='臺北天文館', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='免費', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8A5A19B2D10C4827', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9360435', '大直分館「浮生遊戲館」借閱推廣活動', '★活動內容：&nbsp; &nbsp; 人生載浮載沉，沒想到連「書生」也跟著漂浮不定。相信大家都有發現圖書館內最近多了一個區域叫「浮動館藏」，此區放置的是來自他館的圖書，讓各位讀者有機會借到平常在大直看不到的書，也可以參考別人都借了什麼書來看。&nbsp; &nbsp; 春節期間剛過，大家是否玩得意猶未盡呢?為了增加點借書趣味，現在在活動期間來大直分館借書3本即可於當天玩1次彈珠檯兌換獎品哦!★活動時間：2月20日(四)至3月31日(一)。★活動辦法：(一)借3本浮動館藏圖書即可於當天玩1次彈珠檯，並依彈珠落入之數字兌換獎品。(二)1張借閱證一天限玩1次。(三)獎品種類將視庫存調整，數量有限，換完為止。★活動地點：臺北市立圖書館大直分館三樓服務臺(浮動館藏區靠近三樓入口處，可詢問櫃檯)地址：臺北市中山區大直街25號3樓電話：02-25336535', '臺北市立圖書館', '無資料', '2025-02-20 00:00:00', '2025-03-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=36869EF8403A1076', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大直分館「浮生遊戲館」借閱推廣活動', `description`='★活動內容：&nbsp; &nbsp; 人生載浮載沉，沒想到連「書生」也跟著漂浮不定。相信大家都有發現圖書館內最近多了一個區域叫「浮動館藏」，此區放置的是來自他館的圖書，讓各位讀者有機會借到平常在大直看不到的書，也可以參考別人都借了什麼書來看。&nbsp; &nbsp; 春節期間剛過，大家是否玩得意猶未盡呢?為了增加點借書趣味，現在在活動期間來大直分館借書3本即可於當天玩1次彈珠檯兌換獎品哦!★活動時間：2月20日(四)至3月31日(一)。★活動辦法：(一)借3本浮動館藏圖書即可於當天玩1次彈珠檯，並依彈珠落入之數字兌換獎品。(二)1張借閱證一天限玩1次。(三)獎品種類將視庫存調整，數量有限，換完為止。★活動地點：臺北市立圖書館大直分館三樓服務臺(浮動館藏區靠近三樓入口處，可詢問櫃檯)地址：臺北市中山區大直街25號3樓電話：02-25336535', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-20 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=36869EF8403A1076', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9360431', '民生分館市民生活講座「親子精油舒壓DIY」', '學習安全的精油居家應用，讓孩子在香氣中快樂成長。透過簡單的手療按摩互動，享受親子間親密相處時光。活動時間：3月22日(六)14:00~16:00活動地點：民生分館5樓視聽室活動對象：無限制報名方式：請利用電話(TEL：2713-8083)或親至民生分館報名', '臺北市立圖書館', '無資料', '2025-02-19 00:00:00', '2025-03-15 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=353324A5B90BB563', '[]') ON DUPLICATE KEY UPDATE `activity_name`='民生分館市民生活講座「親子精油舒壓DIY」', `description`='學習安全的精油居家應用，讓孩子在香氣中快樂成長。透過簡單的手療按摩互動，享受親子間親密相處時光。活動時間：3月22日(六)14:00~16:00活動地點：民生分館5樓視聽室活動對象：無限制報名方式：請利用電話(TEL：2713-8083)或親至民生分館報名', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-19 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=353324A5B90BB563', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9360422', '臺北市中正區公所114年度開辦新住民TQUK國際咖啡師輔導考照班，歡迎報名參加。', '臺北市中正區公所將於114年4月30日至6月29日止，每週三(18:00~21:00)與週六(09:30~12:30、13:30~16:30)於臺北市中正區中華路二段315巷14號2樓（南機場樂活園地旁邊）辦理新住民課程，其中6月29日（星期日）為檢定日及成果發表暨同樂會，預計共17堂課咖啡專業課程。報名方式採網路線上報名，114年3月3日上午9時30分起受理報名，將依報名時間依序錄取至額滿為止，歡迎符合資格新住民報名參加，詳情請洽2341-6721轉317張小姐。', '臺北市內湖區戶政事務所', '無資料', '2025-04-30 00:00:00', '2025-06-29 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=76EF4E089B2E43A5', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺北市中正區公所114年度開辦新住民TQUK國際咖啡師輔導考照班，歡迎報名參加。', `description`='臺北市中正區公所將於114年4月30日至6月29日止，每週三(18:00~21:00)與週六(09:30~12:30、13:30~16:30)於臺北市中正區中華路二段315巷14號2樓（南機場樂活園地旁邊）辦理新住民課程，其中6月29日（星期日）為檢定日及成果發表暨同樂會，預計共17堂課咖啡專業課程。報名方式採網路線上報名，114年3月3日上午9時30分起受理報名，將依報名時間依序錄取至額滿為止，歡迎符合資格新住民報名參加，詳情請洽2341-6721轉317張小姐。', `organizer`='臺北市內湖區戶政事務所', `address`='無資料', `start_date`='2025-04-30 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=76EF4E089B2E43A5', `image_url`='[]';
