INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9360288', '無資料', '北投就業服務站將於114年3月4日(週二)下午2-4時辦理【皓群科技股份有限公司】微型徵才活動活動時間：3月4日(二)下午2:00~4:00活動地點：北投就業服務站 (臺北市北投區新市街30號5樓)洽詢電話：(02)28981819#115職務名稱：(淡水信義線/松山新店線)站務員需求人數：40學歷要求：高中職以上工作經驗：不拘工作內容：1.旅客諮詢、遺失物處理、走失親友協尋、視障或行動不便旅客服務。2.車站現金、票證及行銷商品販售作業。3.站內自動收費系統之監控處理、車站門禁管制、保全及清潔工作之執行檢查、車站設備監控、報修及管制維修工作。4.旅客糾紛、受傷事件處理。5.處理緊急事件及異常事故、車站人潮管制及疏散作業、車站緊急設備操作、配合執行車站消防編組及各項演練。6.協助捷運行政大樓、各站務段、運務中心辦公室事務性行政工作。7.站務勤務工作。8.其他經指定之工作。薪資待遇：月薪33174元工作時間：06:30-14:30/14:15-22:15/16:00-24:00工作地點：淡水信義線/松山新店線職務名稱：(信義線/新蘆線)水電維護人員需求人數：10學歷要求：高中職以上工作經驗：無經驗可、有證照佳工作內容：1.維修捷運站水電、消防等設備。2.捷運照明、給水與排水系統之保養維護。3.具水電、消防設備維修經驗者佳。4.緊急事故協助處理。5.配合主管交辦事項。薪資待遇：月薪30000-32000元工作時間：08:00-16:00/16:00-24:00/24:00-08:00工作地點：台北車站/台北橋', '北投就業服務站', '台北市北投區新市街30號5樓', '北投就業服務站', 25.1480682, 121.5177992, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='北投就業服務站將於114年3月4日(週二)下午2-4時辦理【皓群科技股份有限公司】微型徵才活動活動時間：3月4日(二)下午2:00~4:00活動地點：北投就業服務站 (臺北市北投區新市街30號5樓)洽詢電話：(02)28981819#115職務名稱：(淡水信義線/松山新店線)站務員需求人數：40學歷要求：高中職以上工作經驗：不拘工作內容：1.旅客諮詢、遺失物處理、走失親友協尋、視障或行動不便旅客服務。2.車站現金、票證及行銷商品販售作業。3.站內自動收費系統之監控處理、車站門禁管制、保全及清潔工作之執行檢查、車站設備監控、報修及管制維修工作。4.旅客糾紛、受傷事件處理。5.處理緊急事件及異常事故、車站人潮管制及疏散作業、車站緊急設備操作、配合執行車站消防編組及各項演練。6.協助捷運行政大樓、各站務段、運務中心辦公室事務性行政工作。7.站務勤務工作。8.其他經指定之工作。薪資待遇：月薪33174元工作時間：06:30-14:30/14:15-22:15/16:00-24:00工作地點：淡水信義線/松山新店線職務名稱：(信義線/新蘆線)水電維護人員需求人數：10學歷要求：高中職以上工作經驗：無經驗可、有證照佳工作內容：1.維修捷運站水電、消防等設備。2.捷運照明、給水與排水系統之保養維護。3.具水電、消防設備維修經驗者佳。4.緊急事故協助處理。5.配合主管交辦事項。薪資待遇：月薪30000-32000元工作時間：08:00-16:00/16:00-24:00/24:00-08:00工作地點：台北車站/台北橋', `organizer`='北投就業服務站', `address`='台北市北投區新市街30號5樓', `location`='北投就業服務站', `latitude`=25.1480682, `longitude`=121.5177992, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
