INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9347432', '無資料', '小龍年來了!準備好迎接更好的自己了嗎?「蛇」在許多文化裡有療癒與智慧、重生與力量之意涵，為迎接農曆小龍年並鼓勵民眾學習使用便利之資訊服務，李科永紀念圖書館特別推出「蛇來運轉」自助借書換好禮活動，歡迎舊雨新知加入蛻變的行列!活動目地：為鼓勵讀者進館，並熟悉自助借書機或手機借書的操作，以達到學習使用新科技及節省人力時間之目的，特舉辦此自助借書推廣活動。活動時間：2月20日至4月30日。適用對象：持有本館個人借閱證活動內容：使用本館自助借閱服務(北市圖App手機借書功能、自助借書機)當日借滿3冊圖書(不含附件)，臨櫃經館員確認後，即可再搭配閱讀存摺點數兌換好禮。獎品種類多元、數量有限，兌完即止。活動地點：李科永紀念圖書館1樓服務臺。(地址：臺北市士林區中正路15號，電話：2883-3453)', '臺北市立圖書館', '無資料', '無資料', '無資料', '無資料', '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='小龍年來了!準備好迎接更好的自己了嗎?「蛇」在許多文化裡有療癒與智慧、重生與力量之意涵，為迎接農曆小龍年並鼓勵民眾學習使用便利之資訊服務，李科永紀念圖書館特別推出「蛇來運轉」自助借書換好禮活動，歡迎舊雨新知加入蛻變的行列!活動目地：為鼓勵讀者進館，並熟悉自助借書機或手機借書的操作，以達到學習使用新科技及節省人力時間之目的，特舉辦此自助借書推廣活動。活動時間：2月20日至4月30日。適用對象：持有本館個人借閱證活動內容：使用本館自助借閱服務(北市圖App手機借書功能、自助借書機)當日借滿3冊圖書(不含附件)，臨櫃經館員確認後，即可再搭配閱讀存摺點數兌換好禮。獎品種類多元、數量有限，兌完即止。活動地點：李科永紀念圖書館1樓服務臺。(地址：臺北市士林區中正路15號，電話：2883-3453)', `organizer`='臺北市立圖書館', `address`='無資料', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
