INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('4ccb02d90d99ff3874c258647782a75e', '2025(上)板橋生活講座--「人生一定要嘗試的10種旅行」', '「板橋生活講座」7/23(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請行銷公關專案賴彥如(Q娜)演講「人生一定要嘗試的10種旅行」。思想家聖‧奧古斯丁曾說：「世界是一本書，不旅行的人只讀了一頁。」在忙碌的工作之餘你有多久沒有好好旅行了？想規劃出專屬於自己的旅行意義，創造出獨一無二的美好回憶嗎？本講座邀請有著豐富旅行經驗、環遊世界86國的人氣旅遊達人與您分享今生一定要嘗試的10種旅行方式，從帝皇級高規格到小資女類型，從個人自助行到家庭旅行，讓您輕鬆選擇最適合自己的旅遊方式，自由自在體驗異國城市及鄉村小鎮的風俗民情。', '板橋區公所', '新北市板橋區府中路30號6樓', '板橋區公所6樓大禮堂', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025(上)板橋生活講座--「人生一定要嘗試的10種旅行」', `description`='「板橋生活講座」7/23(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請行銷公關專案賴彥如(Q娜)演講「人生一定要嘗試的10種旅行」。思想家聖‧奧古斯丁曾說：「世界是一本書，不旅行的人只讀了一頁。」在忙碌的工作之餘你有多久沒有好好旅行了？想規劃出專屬於自己的旅行意義，創造出獨一無二的美好回憶嗎？本講座邀請有著豐富旅行經驗、環遊世界86國的人氣旅遊達人與您分享今生一定要嘗試的10種旅行方式，從帝皇級高規格到小資女類型，從個人自助行到家庭旅行，讓您輕鬆選擇最適合自己的旅遊方式，自由自在體驗異國城市及鄉村小鎮的風俗民情。', `organizer`='板橋區公所', `address`='新北市板橋區府中路30號6樓', `location`='板橋區公所6樓大禮堂', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('4ccb02d90d99ff38041c5d4c5146a19f', '2025(上)板橋生活講座--「每天睡得好，八十不見老」', '「板橋生活講座」7/9(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請中醫師陳一帆演講「每天睡得好，八十不見老」。俗話說：「每天睡得好，八十不見老」，強調了充足睡眠對健康與抗老的重要性，良好的睡眠品質能促進新陳代謝、修復身體機能，並維持皮膚彈性與大腦活力，讓人精神飽滿、青春常駐。不論年齡，每天保持規律的作息與適當的睡眠時間，有助於減少慢性病風險，提升生活品質。本講座邀請中醫師，帶領大家培養健康的睡眠習慣，讓我們越活越年輕，80歲依然充滿活力！', '板橋區公所', '新北市板橋區府中路30號6樓', '板橋區公所6樓大禮堂', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025(上)板橋生活講座--「每天睡得好，八十不見老」', `description`='「板橋生活講座」7/9(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請中醫師陳一帆演講「每天睡得好，八十不見老」。俗話說：「每天睡得好，八十不見老」，強調了充足睡眠對健康與抗老的重要性，良好的睡眠品質能促進新陳代謝、修復身體機能，並維持皮膚彈性與大腦活力，讓人精神飽滿、青春常駐。不論年齡，每天保持規律的作息與適當的睡眠時間，有助於減少慢性病風險，提升生活品質。本講座邀請中醫師，帶領大家培養健康的睡眠習慣，讓我們越活越年輕，80歲依然充滿活力！', `organizer`='板橋區公所', `address`='新北市板橋區府中路30號6樓', `location`='板橋區公所6樓大禮堂', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('4ccb02d90d99ff3840db35769a54ae88', '2025(上)板橋生活講座--「台灣女鬼佗位來？探討民俗背後的性別議題」', '「板橋生活講座」6/25(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請台灣友性創心協會理事長郭怡伶演講「台灣女鬼佗位來？探討民俗背後的性別議題」。想想大家耳熟能詳的鬼故事，是不是會發現女鬼的故事好像要比男鬼來得多？談起鬼，人人都怕，然而世界各地都有鬼故事，為什麼在台灣的故事中女鬼特別多？為什麼有可怕的紅衣小女孩卻沒有小男孩？若林投姐是林投哥，那她還會含冤而死嗎？讓我們一起從女鬼故事裡，透析台灣傳統習俗文化及民俗脈絡中的性別意涵。', '板橋區公所', '新北市板橋區府中路30號6樓', '板橋區公所6樓大禮堂', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025(上)板橋生活講座--「台灣女鬼佗位來？探討民俗背後的性別議題」', `description`='「板橋生活講座」6/25(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請台灣友性創心協會理事長郭怡伶演講「台灣女鬼佗位來？探討民俗背後的性別議題」。想想大家耳熟能詳的鬼故事，是不是會發現女鬼的故事好像要比男鬼來得多？談起鬼，人人都怕，然而世界各地都有鬼故事，為什麼在台灣的故事中女鬼特別多？為什麼有可怕的紅衣小女孩卻沒有小男孩？若林投姐是林投哥，那她還會含冤而死嗎？讓我們一起從女鬼故事裡，透析台灣傳統習俗文化及民俗脈絡中的性別意涵。', `organizer`='板橋區公所', `address`='新北市板橋區府中路30號6樓', `location`='板橋區公所6樓大禮堂', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('4ccb02d90d99ff3811bb05f14781a518', '2025(上)板橋生活講座--「做得到的健康建議-預防慢性病」', '「板橋生活講座」6/11(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請藥師、國衛院顧問胡廷岳演講「做得到的健康建議-預防慢性病」。「遇到藥物副作用，藥還要吃完嗎？」看病、減藥、照顧好自己，其實是學校沒有教，但又比「微積分」還重要100萬倍的事情。本講座邀請藥師，從看懂藥袋開始，帶著您辨識壞藥，幫家人排除後遺症；辨識好藥，預防健康惡化，用白話的方式，以做得到的健康建議，讓你我預防慢性病惡化。', '板橋區公所', '新北市板橋區府中路30號6樓', '板橋區公所6樓大禮堂', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025(上)板橋生活講座--「做得到的健康建議-預防慢性病」', `description`='「板橋生活講座」6/11(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請藥師、國衛院顧問胡廷岳演講「做得到的健康建議-預防慢性病」。「遇到藥物副作用，藥還要吃完嗎？」看病、減藥、照顧好自己，其實是學校沒有教，但又比「微積分」還重要100萬倍的事情。本講座邀請藥師，從看懂藥袋開始，帶著您辨識壞藥，幫家人排除後遺症；辨識好藥，預防健康惡化，用白話的方式，以做得到的健康建議，讓你我預防慢性病惡化。', `organizer`='板橋區公所', `address`='新北市板橋區府中路30號6樓', `location`='板橋區公所6樓大禮堂', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('4ccb02d90d99ff380e61efbd3301b6a8', '2025(上)板橋生活講座--「品酒鑑賞-漫談葡萄酒的故鄉與風味」', '「板橋生活講座」5/28(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請西班牙小酒館副理張湘霆演講「品酒鑑賞-漫談葡萄酒的故鄉與風味」。從經典的赤霞珠到甜美的麝香，葡萄酒的世界充滿多樣性。每種葡萄品種都有獨特風味，讓你的味蕾探險不斷。紅酒富含抗氧化物，有助於心血管健康，還能增進消化，每天一小杯，讓你心情愉快又健康。透過張湘霆老師專業的講解，告訴大家法國葡萄酒的分級、產區，以及食物搭配與侍酒方式，無論你喜愛哪種風味，總有一款適合你！', '板橋區公所', '新北市板橋區府中路30號6樓', '板橋區公所6樓大禮堂', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025(上)板橋生活講座--「品酒鑑賞-漫談葡萄酒的故鄉與風味」', `description`='「板橋生活講座」5/28(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請西班牙小酒館副理張湘霆演講「品酒鑑賞-漫談葡萄酒的故鄉與風味」。從經典的赤霞珠到甜美的麝香，葡萄酒的世界充滿多樣性。每種葡萄品種都有獨特風味，讓你的味蕾探險不斷。紅酒富含抗氧化物，有助於心血管健康，還能增進消化，每天一小杯，讓你心情愉快又健康。透過張湘霆老師專業的講解，告訴大家法國葡萄酒的分級、產區，以及食物搭配與侍酒方式，無論你喜愛哪種風味，總有一款適合你！', `organizer`='板橋區公所', `address`='新北市板橋區府中路30號6樓', `location`='板橋區公所6樓大禮堂', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('4ccb02d90d99ff38945c43a63371da1d', '2025(上)板橋生活講座--「培養閱讀從家開始〜親子共讀」', '「板橋生活講座」5/7(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請國立空中大學講師許陳玉玟演講「培養閱讀從家開始〜親子共讀」。「嬰幼兒時期」是腦力發展的黃金階段，閱讀是刺激腦力最直接有效的方式，而親子共讀不僅可培養親子間的感情，也能增進孩子語言發展與理解能力。本次講座將帶領家長，從繪本的認識、各種說故事及共讀方法開始，營造愉悅的共讀情境，逐步培養孩子閱讀興趣，進而提升孩子思考、專注及表達能力，激發孩子的自主學習力。', '板橋區公所', '新北市板橋區府中路30號6樓', '板橋區公所6樓大禮堂', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025(上)板橋生活講座--「培養閱讀從家開始〜親子共讀」', `description`='「板橋生活講座」5/7(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請國立空中大學講師許陳玉玟演講「培養閱讀從家開始〜親子共讀」。「嬰幼兒時期」是腦力發展的黃金階段，閱讀是刺激腦力最直接有效的方式，而親子共讀不僅可培養親子間的感情，也能增進孩子語言發展與理解能力。本次講座將帶領家長，從繪本的認識、各種說故事及共讀方法開始，營造愉悅的共讀情境，逐步培養孩子閱讀興趣，進而提升孩子思考、專注及表達能力，激發孩子的自主學習力。', `organizer`='板橋區公所', `address`='新北市板橋區府中路30號6樓', `location`='板橋區公所6樓大禮堂', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('4ccb02d90d99ff38353e53414c3cc8a6', '2025(上)板橋生活講座--「輕鬆揮別腰痠背痛」', '「板橋生活講座」4/23(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請中醫師李棟樑演講「輕鬆揮別腰痠背痛」。您經常腰酸背痛嗎？您是否因體態不佳而煩惱？您知道姿勢不良可能導致的嚴重後果嗎？為此，本次講座邀請中醫師，將針對職場人困惱的腰痠背痛等姿勢不良疾病，分門別類找出病徵，讓各領域職場人遠離腰痠背痛，輕鬆達到壓力的舒緩與釋放。', '板橋區公所', '新北市板橋區府中路30號6樓', '板橋區公所6樓大禮堂', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025(上)板橋生活講座--「輕鬆揮別腰痠背痛」', `description`='「板橋生活講座」4/23(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請中醫師李棟樑演講「輕鬆揮別腰痠背痛」。您經常腰酸背痛嗎？您是否因體態不佳而煩惱？您知道姿勢不良可能導致的嚴重後果嗎？為此，本次講座邀請中醫師，將針對職場人困惱的腰痠背痛等姿勢不良疾病，分門別類找出病徵，讓各領域職場人遠離腰痠背痛，輕鬆達到壓力的舒緩與釋放。', `organizer`='板橋區公所', `address`='新北市板橋區府中路30號6樓', `location`='板橋區公所6樓大禮堂', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('4ccb02d90d99ff383dc517462cd76f65', '2025(上)板橋生活講座--「育兒、從母姓-家庭裡的性平話題」', '「板橋生活講座」4/9(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請生育改革行動聯盟理事長諶淑婷演講「育兒、從母姓-家庭裡的性平話題」。開始育兒後，我們面對生活的天翻地覆，諸如處理家務分配不均的問題，對於孩子從誰的姓氏各有堅持，過著「看似有所選擇其實沒有選擇」的矛盾生活。本次講座將帶領大家了解，即便工作、家務兩頭燒，現代家長還是有辦法在家庭內實踐性別平等，以各種多元易行的行動方案，看見多元可能、隱形框框，生養出了解、支持性別平權的下一代。', '板橋區公所', '新北市板橋區府中路30號6樓', '板橋區公所6樓大禮堂', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025(上)板橋生活講座--「育兒、從母姓-家庭裡的性平話題」', `description`='「板橋生活講座」4/9(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請生育改革行動聯盟理事長諶淑婷演講「育兒、從母姓-家庭裡的性平話題」。開始育兒後，我們面對生活的天翻地覆，諸如處理家務分配不均的問題，對於孩子從誰的姓氏各有堅持，過著「看似有所選擇其實沒有選擇」的矛盾生活。本次講座將帶領大家了解，即便工作、家務兩頭燒，現代家長還是有辦法在家庭內實踐性別平等，以各種多元易行的行動方案，看見多元可能、隱形框框，生養出了解、支持性別平權的下一代。', `organizer`='板橋區公所', `address`='新北市板橋區府中路30號6樓', `location`='板橋區公所6樓大禮堂', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('4ccb02d90d99ff38b916f1fcec9c1b70', '2025(上)板橋生活講座--「當憂鬱已成文明病，你可以這麼做」', '「板橋生活講座」3/26(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請衛生福利部雙和醫院臨床心理師沈晏羽演講「當憂鬱已成文明病，你可以這麼做」。現代人因憂鬱而前往醫院治療的比例越來越高，您有想過嗎，憂鬱這件事居然也發生在孩子身上？根據統計，青少年自殺、自傷的比例逐年攀升，與憂鬱情緒有很大的關聯。本講座邀請心理師針對青少年及兒童的憂鬱現況及成因作介紹，讓大家了解身邊的孩子若為憂鬱情緒所困時，該如何應對，在家庭教育中又該如何預防孩子產生負向情緒，提升與孩子的感情，讓彼此更靠近。', '板橋區公所', '新北市板橋區府中路30號6樓', '板橋區公所6樓大禮堂', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025(上)板橋生活講座--「當憂鬱已成文明病，你可以這麼做」', `description`='「板橋生活講座」3/26(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請衛生福利部雙和醫院臨床心理師沈晏羽演講「當憂鬱已成文明病，你可以這麼做」。現代人因憂鬱而前往醫院治療的比例越來越高，您有想過嗎，憂鬱這件事居然也發生在孩子身上？根據統計，青少年自殺、自傷的比例逐年攀升，與憂鬱情緒有很大的關聯。本講座邀請心理師針對青少年及兒童的憂鬱現況及成因作介紹，讓大家了解身邊的孩子若為憂鬱情緒所困時，該如何應對，在家庭教育中又該如何預防孩子產生負向情緒，提升與孩子的感情，讓彼此更靠近。', `organizer`='板橋區公所', `address`='新北市板橋區府中路30號6樓', `location`='板橋區公所6樓大禮堂', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('4ccb02d90d99ff388098e85a6b7f6a7d', '2025(上)板橋生活講座--「房東房客必知的租屋法律知識」', '「板橋生活講座」3/12(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請仁永法律事務所主持律師劉琦富演講「房東房客必知的租屋法律知識」。租賃專法自民國107年6月27日上路已6年多，政府也陸續推動社會住宅包租代管、租金補貼等等不同政策，只是您真的知道租賃專法在講什麼嗎？租約要怎麼簽才不會違法？遇到租霸和惡房東該怎麼透過法律才能進一步保障自己的權益？本次講座邀請律師分享租賃糾紛處理訴訟實務及案例，讓您避免踩到租屋的地雷。', '板橋區公所', '新北市板橋區府中路30號6樓', '板橋區公所6樓大禮堂', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025(上)板橋生活講座--「房東房客必知的租屋法律知識」', `description`='「板橋生活講座」3/12(三)晚上7點於板橋區公所6樓大禮堂(板橋區府中路30號)，邀請仁永法律事務所主持律師劉琦富演講「房東房客必知的租屋法律知識」。租賃專法自民國107年6月27日上路已6年多，政府也陸續推動社會住宅包租代管、租金補貼等等不同政策，只是您真的知道租賃專法在講什麼嗎？租約要怎麼簽才不會違法？遇到租霸和惡房東該怎麼透過法律才能進一步保障自己的權益？本次講座邀請律師分享租賃糾紛處理訴訟實務及案例，讓您避免踩到租屋的地雷。', `organizer`='板橋區公所', `address`='新北市板橋區府中路30號6樓', `location`='板橋區公所6樓大禮堂', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('269979a3c30712266b31ce6068b82513', '【新北市立圖書館淡海小書房】114年3月主題書展 :《搭地鐵玩遍世界》', '「搭地鐵玩遍世界」主題書展時間：3/1(六)-3/31(一) 開館時間地點：淡海小書房（淡水區中正東路2段68號）電話：02-2808-0400簡介：旅行是煩悶、忙碌生活的最佳調劑，近年來自由行更是蔚為風潮，因此善用鐡路進行有效率的移動方式，怎麼買票最划算、怎樣安排路線最方便，既能省錢、又能玩得開心也玩得安全，書中整理了所有的資訊，讓讀者能一目瞭然。備註：1.開館時間為每日11時至19時。2.3月27日(四)清館日，不對外開放。', '新北市立圖書館', '新北市淡水區中正東路2段68號', '淡海小書房', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡海小書房】114年3月主題書展 :《搭地鐵玩遍世界》', `description`='「搭地鐵玩遍世界」主題書展時間：3/1(六)-3/31(一) 開館時間地點：淡海小書房（淡水區中正東路2段68號）電話：02-2808-0400簡介：旅行是煩悶、忙碌生活的最佳調劑，近年來自由行更是蔚為風潮，因此善用鐡路進行有效率的移動方式，怎麼買票最划算、怎樣安排路線最方便，既能省錢、又能玩得開心也玩得安全，書中整理了所有的資訊，讓讀者能一目瞭然。備註：1.開館時間為每日11時至19時。2.3月27日(四)清館日，不對外開放。', `organizer`='新北市立圖書館', `address`='新北市淡水區中正東路2段68號', `location`='淡海小書房', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('272858548ed8e90acbb47cd61a4f3233', '【樹林分館】114年3月閱讀書籤主題書展', '主題書展女力潮流書展/男女平權是現今重要議題，本期探討女性議題及介紹各式女性著名人物並鼓勵和啟發更多女性追求夢想和目標。兒童書展種樹救地球書展/3月12日是台灣植樹節，由其現今溫室效應等各式天然災害，本期來認識各類植物，並培養愛護環境責任。', '新北市立圖書館', '新北市樹林區樹新路40-7號3、4樓', '新北市立圖書館【樹林分館】', 24.97970609, 121.401034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【樹林分館】114年3月閱讀書籤主題書展', `description`='主題書展女力潮流書展/男女平權是現今重要議題，本期探討女性議題及介紹各式女性著名人物並鼓勵和啟發更多女性追求夢想和目標。兒童書展種樹救地球書展/3月12日是台灣植樹節，由其現今溫室效應等各式天然災害，本期來認識各類植物，並培養愛護環境責任。', `organizer`='新北市立圖書館', `address`='新北市樹林區樹新路40-7號3、4樓', `location`='新北市立圖書館【樹林分館】', `latitude`=24.97970609, `longitude`=121.401034, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
