INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('269979a3c307122603c1fde719bd7283', '【新北市立圖書館淡水分館】《3月主題書展 : 巴哈姆特ACG創作大賽》', '《巴哈姆特ACG創作大賽》時間：3/3(一)-3/30(日)地點：淡水分館3F漫畫區（淡水區文化路65號3F）電話：02-26224664簡介：「巴哈姆特ACG創作大賽」是當代台灣年輕人的年度盛事，不僅是年輕人展現才華的舞台，更是年輕人透過網路投票凝聚認同的關鍵時刻。「ACG創作大賽」共分為「動畫組」、「漫畫組」、「遊戲組」三大賽事組別，並串連廠商贊助增設各類特別獎項，自2012年開辦至今培養不少台灣漫迷和創作者。身為台灣人我們必須認識這股原創的力量。"', '新北市立圖書館', '新北市淡水區文化路65號', '淡水分館3F漫畫區', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡水分館】《3月主題書展 : 巴哈姆特ACG創作大賽》', `description`='《巴哈姆特ACG創作大賽》時間：3/3(一)-3/30(日)地點：淡水分館3F漫畫區（淡水區文化路65號3F）電話：02-26224664簡介：「巴哈姆特ACG創作大賽」是當代台灣年輕人的年度盛事，不僅是年輕人展現才華的舞台，更是年輕人透過網路投票凝聚認同的關鍵時刻。「ACG創作大賽」共分為「動畫組」、「漫畫組」、「遊戲組」三大賽事組別，並串連廠商贊助增設各類特別獎項，自2012年開辦至今培養不少台灣漫迷和創作者。身為台灣人我們必須認識這股原創的力量。"', `organizer`='新北市立圖書館', `address`='新北市淡水區文化路65號', `location`='淡水分館3F漫畫區', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('d91399d6e6a813d4eba87f4bfd0be100', '無資料', '動保處於2月23日上午10時至下午16時於淡水天元宮舉辦【相遇櫻花下毛寶貝認養會】，現場有寵物認養及狂犬疫苗及晶片注射等活動邀您一起參與。現場認養除了動保處所贈送之籠具、保健品等價值千元以上的認養大禮包外，還有飼料廠商所提供的認養好禮，讓每一位認養者都能帶著滿滿的祝福，迎接毛寶貝回家', '新北市政府動物保護防疫處', '新北市淡水區北新路三段36號', '淡水無極天元宮', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='動保處於2月23日上午10時至下午16時於淡水天元宮舉辦【相遇櫻花下毛寶貝認養會】，現場有寵物認養及狂犬疫苗及晶片注射等活動邀您一起參與。現場認養除了動保處所贈送之籠具、保健品等價值千元以上的認養大禮包外，還有飼料廠商所提供的認養好禮，讓每一位認養者都能帶著滿滿的祝福，迎接毛寶貝回家', `organizer`='新北市政府動物保護防疫處', `address`='新北市淡水區北新路三段36號', `location`='淡水無極天元宮', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('269979a3c30712269687c68d821e9bf2', '無資料', '《工作細胞》主題書展時間：3/1(六)-3/29(六 )駐點時間地點：淡水行動書車電話：02-26292879轉12簡介：受到全球暖化影響，夏天一年比一年還要熱不只人類汗流浹背，工作細胞也快要受不了啦！紅血球聚集到微血管協助散熱、細胞們也努降温但體温卻仍持續升高。這難道就是………中暑勤奮但冒失的紅血球，今天也在身體裡四處迷路當她差點被邪惡的肺炎鏈球菌攻擊時冷靜幹練的白血球現身拯救了她然而，危機卻還沒有結束…………….缺乏歷練的初始T細胞，遇見了恐怖的流感病毒雖然幸運被白血球和巨噬細胞救回一命卻也受到學長---殺手T細胞狠狠責備從戰場上逃走的膽小初始T細胞能成為獨當一面的工作細胞嗎?https://reurl.cc/xpWmv4行動書車執勤服務時間與地點詳如新北市立圖書館官網。', '新北市立圖書館', '新北市淡水區中山北路一段158號', '淡水行動書車', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無資料', `description`='《工作細胞》主題書展時間：3/1(六)-3/29(六 )駐點時間地點：淡水行動書車電話：02-26292879轉12簡介：受到全球暖化影響，夏天一年比一年還要熱不只人類汗流浹背，工作細胞也快要受不了啦！紅血球聚集到微血管協助散熱、細胞們也努降温但體温卻仍持續升高。這難道就是………中暑勤奮但冒失的紅血球，今天也在身體裡四處迷路當她差點被邪惡的肺炎鏈球菌攻擊時冷靜幹練的白血球現身拯救了她然而，危機卻還沒有結束…………….缺乏歷練的初始T細胞，遇見了恐怖的流感病毒雖然幸運被白血球和巨噬細胞救回一命卻也受到學長---殺手T細胞狠狠責備從戰場上逃走的膽小初始T細胞能成為獨當一面的工作細胞嗎?https://reurl.cc/xpWmv4行動書車執勤服務時間與地點詳如新北市立圖書館官網。', `organizer`='新北市立圖書館', `address`='新北市淡水區中山北路一段158號', `location`='淡水行動書車', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
