INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67a5353626b3240c403d939b', '小百科，請回答！—醜蔬果與羊毛氈工作坊', '講師：環毛氈護生志業手作團隊，運用天然的羊毛素材，以環境關懷為本，傳遞愛護生命的理念。\n\n課程流程：\n\n(一)認識醜蔬果：透過製作羊毛氈水果小物，在生活中提醒著我們醜蔬果的營養價值一樣滿滿喲。\n\n(二)羊毛氈教學：講師將進行約10分鐘的教學示範，讓學員瞭解製作步驟。（依現場學員學習狀況，亦可能會分為兩階段示範）\n\n(三)動手創意DIY：學員實際製作，講師會現場協助指導每位學員，順利完成作品。\n\n(四)交流分享及大合照\n\n \n\n備註1：本課程學員無須自備材料。\n\n備註2：由於本課程將使用羊毛氈戳針，戳刺過程須保持專注，並需家長一同協助孩童之用針安全。\n\n\n\n \n\n ', '桃園市立美術館', '320  桃園市中壢區中壢區高鐵南路二段 90 號', '2025-03-01 00:00:00', '2025-03-15 00:00:00', '桃園市兒童美術館', 24.97993803, 121.2147243, '無資料', 'https://event.culture.tw/mocweb/reg/TMOFA/Detail.init.ctr?actId=50006', '[]') ON DUPLICATE KEY UPDATE `activity_name`='小百科，請回答！—醜蔬果與羊毛氈工作坊', `description`='講師：環毛氈護生志業手作團隊，運用天然的羊毛素材，以環境關懷為本，傳遞愛護生命的理念。\n\n課程流程：\n\n(一)認識醜蔬果：透過製作羊毛氈水果小物，在生活中提醒著我們醜蔬果的營養價值一樣滿滿喲。\n\n(二)羊毛氈教學：講師將進行約10分鐘的教學示範，讓學員瞭解製作步驟。（依現場學員學習狀況，亦可能會分為兩階段示範）\n\n(三)動手創意DIY：學員實際製作，講師會現場協助指導每位學員，順利完成作品。\n\n(四)交流分享及大合照\n\n \n\n備註1：本課程學員無須自備材料。\n\n備註2：由於本課程將使用羊毛氈戳針，戳刺過程須保持專注，並需家長一同協助孩童之用針安全。\n\n\n\n \n\n ', `organizer`='桃園市立美術館', `address`='320  桃園市中壢區中壢區高鐵南路二段 90 號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='桃園市兒童美術館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/TMOFA/Detail.init.ctr?actId=50006', `image_url`='[]';
