INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9353404', '總館視聽室2025年3月電影賞析講座', '每月精選各國藝術電影，邀請電影導讀老師評析，引導民眾瞭解電影語言，增加觀賞電影的深度。一、主辦單位：臺北市立圖書館視聽室(2755-2823分機2802)二、參加對象：一般民眾三、參加方式：不需報名，免費自由參加四、活動地點：總館10樓會議廳五、活動時間：3月9日(週日)下午1：30（下午1:00開始入場，實際結束時間視影片長短而定）六、影片名稱：老狐狸/112分鐘（普遍級）七、講 &nbsp; &nbsp;師：林世媛心理師備註：本活動提供終身學習時數認證3小時，請於現場辦理簽到。場次內容若有異動，將另行發布異動訊息', '臺北市立圖書館', '無資料', '2025-02-23 00:00:00', '2025-03-09 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1A7A26245A0BAB27', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館視聽室2025年3月電影賞析講座', `description`='每月精選各國藝術電影，邀請電影導讀老師評析，引導民眾瞭解電影語言，增加觀賞電影的深度。一、主辦單位：臺北市立圖書館視聽室(2755-2823分機2802)二、參加對象：一般民眾三、參加方式：不需報名，免費自由參加四、活動地點：總館10樓會議廳五、活動時間：3月9日(週日)下午1：30（下午1:00開始入場，實際結束時間視影片長短而定）六、影片名稱：老狐狸/112分鐘（普遍級）七、講 &nbsp; &nbsp;師：林世媛心理師備註：本活動提供終身學習時數認證3小時，請於現場辦理簽到。場次內容若有異動，將另行發布異動訊息', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-23 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1A7A26245A0BAB27', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9322537', '文山分館「文山親子電影院」3月節目表', '文山分館每週日播放適合闔家觀賞之影片，提供大朋友、小朋友週末假日休憩和充電的好去處。週日午後，讓我們一起到圖書館看場精彩的電影吧！一、活動時間：每週日下午2：00起放映。二、播映影片：3月 2 日：哆啦A夢-大雄與綠之巨人傳（普）112分3月 9 日：我們這一家-超能力花媽（普）43分3月16日：海賊天團（護）88分3月23日：荷頓奇遇記（普）86分3月30日：幻想曲（普）120分&nbsp;三、活動地點：臺北市立圖書館文山分館9樓多功能活動室。(臺北市文山區興隆路2段160號，電話：2931-5339)四、注意事項：&nbsp;本活動免費參加，入場請遵守影片分級制度。', '臺北市立圖書館', '無資料', '2025-02-23 00:00:00', '2025-03-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=5AE0EEF362ECAB12', '[]') ON DUPLICATE KEY UPDATE `activity_name`='文山分館「文山親子電影院」3月節目表', `description`='文山分館每週日播放適合闔家觀賞之影片，提供大朋友、小朋友週末假日休憩和充電的好去處。週日午後，讓我們一起到圖書館看場精彩的電影吧！一、活動時間：每週日下午2：00起放映。二、播映影片：3月 2 日：哆啦A夢-大雄與綠之巨人傳（普）112分3月 9 日：我們這一家-超能力花媽（普）43分3月16日：海賊天團（護）88分3月23日：荷頓奇遇記（普）86分3月30日：幻想曲（普）120分&nbsp;三、活動地點：臺北市立圖書館文山分館9樓多功能活動室。(臺北市文山區興隆路2段160號，電話：2931-5339)四、注意事項：&nbsp;本活動免費參加，入場請遵守影片分級制度。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-23 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=5AE0EEF362ECAB12', `image_url`='[]';
