INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414aa26b32458d4363972', '114年教育部補助本土語言閱讀推廣計畫：世界母語日-竹編美學', '邀請涂惠芳老師分享「竹子」在客家文化中的涵義，帶領參與者認識竹子象徵的「節節向上」與「步步高升」意象，並體驗竹藝生活美學，進一步探討如何傳承與創新竹編技藝。\r\n報名網址 https://forms.gle/eFu9c4AduwahQn4m9\r\n洽詢專線：037-833430', '苗栗縣政府', '苗栗縣三灣鄉11鄰親民路17-1 號', '2025-03-02 00:00:00', '2025-03-16 00:00:00', '苗栗縣三灣鄉立圖書館', 24.63599405, 120.9525745, '費用+400', 'https://www.facebook.com/sanwanlib#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年教育部補助本土語言閱讀推廣計畫：世界母語日-竹編美學', `description`='邀請涂惠芳老師分享「竹子」在客家文化中的涵義，帶領參與者認識竹子象徵的「節節向上」與「步步高升」意象，並體驗竹藝生活美學，進一步探討如何傳承與創新竹編技藝。\r\n報名網址 https://forms.gle/eFu9c4AduwahQn4m9\r\n洽詢專線：037-833430', `organizer`='苗栗縣政府', `address`='苗栗縣三灣鄉11鄰親民路17-1 號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='苗栗縣三灣鄉立圖書館', `latitude`=24.63599405, `longitude`=120.9525745, `ticket_price`='費用+400', `source_url`='https://www.facebook.com/sanwanlib#', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ba365126b3240c403d98f8', '2月主題書展-源源不絕.創意的秘密', '創意從何而來：讓好點子源源不絕的7大模式,藉由作者提出的「長變焦」觀察法──即以不同的尺度來觀察，優點是能發現只用單一尺度觀察時容易忽略或低估的模式──可以了解，資源共享、多人共同協做的環境，最有利於創意和創新。不論您從事什麼行業、擔任何種職位，只要掌握本書的七大模式，不僅能提昇自己的創意能力，更能創造出可促成更多好點子的優勢環境。藝術是展現自由的方式.自由是一種心理的狀態。\r\n', '臺南市山上區圖書館', '臺南市山上區53號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南市山上區圖書館', 23.09689329, 120.370977, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月主題書展-源源不絕.創意的秘密', `description`='創意從何而來：讓好點子源源不絕的7大模式,藉由作者提出的「長變焦」觀察法──即以不同的尺度來觀察，優點是能發現只用單一尺度觀察時容易忽略或低估的模式──可以了解，資源共享、多人共同協做的環境，最有利於創意和創新。不論您從事什麼行業、擔任何種職位，只要掌握本書的七大模式，不僅能提昇自己的創意能力，更能創造出可促成更多好點子的優勢環境。藝術是展現自由的方式.自由是一種心理的狀態。\r\n', `organizer`='臺南市山上區圖書館', `address`='臺南市山上區53號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市山上區圖書館', `latitude`=23.09689329, `longitude`=120.370977, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
