INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ba365126b3240c403d98fd', '集集鎮114年度土風舞班（3班）', '為了促進身心健康、活絡社區情感，集集鎮公所特別開辦社區土風舞班！透過輕鬆愉快的舞步，讓我們一起享受音樂與舞蹈的樂趣，還能結交新朋友，認識各國文化風情！\r\n開班日期與地點：\r\n永昌里土風舞班\r\n日期：114.2.20 (四) 19:00\r\n地點：武昌宮前廣場\r\n田寮里土風舞班\r\n日期：114.3.10 (一) 19:00\r\n地點：田寮社區活動中心\r\n八張里土風舞班\r\n日期：114.3.12 (三) 19:00\r\n地點：武昌宮前廣場\r\n\r\n講師：凃國鐙，資深土風舞老師。\r\n參加對象：集集鎮民。\r\n名額有限：每班預計招收20人。', '南投縣集集鎮公所', '南投縣集集鎮', '2025-02-20 00:00:00', '2025-06-30 00:00:00', '集集鎮（南投縣）=', 23.83701687, 120.7854192, '無資料', 'https://www.facebook.com/jijitownshipoffice', '[]') ON DUPLICATE KEY UPDATE `activity_name`='集集鎮114年度土風舞班（3班）', `description`='為了促進身心健康、活絡社區情感，集集鎮公所特別開辦社區土風舞班！透過輕鬆愉快的舞步，讓我們一起享受音樂與舞蹈的樂趣，還能結交新朋友，認識各國文化風情！\r\n開班日期與地點：\r\n永昌里土風舞班\r\n日期：114.2.20 (四) 19:00\r\n地點：武昌宮前廣場\r\n田寮里土風舞班\r\n日期：114.3.10 (一) 19:00\r\n地點：田寮社區活動中心\r\n八張里土風舞班\r\n日期：114.3.12 (三) 19:00\r\n地點：武昌宮前廣場\r\n\r\n講師：凃國鐙，資深土風舞老師。\r\n參加對象：集集鎮民。\r\n名額有限：每班預計招收20人。', `organizer`='南投縣集集鎮公所', `address`='南投縣集集鎮', `start_date`='2025-02-20 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='集集鎮（南投縣）=', `latitude`=23.83701687, `longitude`=120.7854192, `ticket_price`='無資料', `source_url`='https://www.facebook.com/jijitownshipoffice', `image_url`='[]';
