INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afafc726b3240c403d9595', '編結首飾設計班', '以淺顯易學的結式，引導學員利用平常日收集的珠玉佩飾設計製作出具個人風格的手飾，將個人美學見解落實在日常生活中。\n\n(教材費約另計)\n\n ', '國立彰化生活美學館', '500  彰化縣彰化市74卦山路18號', '2025-04-08 00:00:00', '2025-06-10 00:00:00', '第二研習教室', 24.0765278, 120.5573442, '1500', 'https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50336', '[]') ON DUPLICATE KEY UPDATE `activity_name`='編結首飾設計班', `description`='以淺顯易學的結式，引導學員利用平常日收集的珠玉佩飾設計製作出具個人風格的手飾，將個人美學見解落實在日常生活中。\n\n(教材費約另計)\n\n ', `organizer`='國立彰化生活美學館', `address`='500  彰化縣彰化市74卦山路18號', `start_date`='2025-04-08 00:00:00', `end_date`='2025-06-10 00:00:00', `location`='第二研習教室', `latitude`=24.0765278, `longitude`=120.5573442, `ticket_price`='1500', `source_url`='https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50336', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bf226b3240c403d981a', '【新開班】達克羅茲兒童音樂律動(適幼兒園大班-2年級)【3月17日上午9點開放報名】', '★本課程開班標準：報名繳費達10人。 \n\n★授課老師：張慈珊老師 、賴怡穎老師   \n\n★課程主題及教學內容將依學員程度及學習狀況斟酌調整\n\n\n	\n		\n			\n			堂數\n			\n			\n			日期\n			\n			\n			課程主題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			5/4\n			\n			\n			動作音樂(一)\n\n			高音低音(一)\n\n			拍子(一)\n			\n			\n			\n				Walking Jogging\n				用動物帶入高低音的差別\n				拍點在哪裡？\n			\n			\n		\n		\n			\n			2\n			\n			\n			5/11\n			\n			\n			動作音樂(二)\n\n			高/低 + 強/弱\n\n			拍子(二)\n			\n			\n			\n				New : Marching \n				小鳥/大象 + f/p\n				4拍練習\n			\n			\n		\n		\n			\n			3\n			\n			\n			5/18\n			\n			\n			動作音樂(三)\n\n			高/低 + 強/弱\n\n			拍子(三)\n			\n			\n			\n				New : Swing\n				高/低音譜記號 + f/p\n				3拍練習\n			\n			\n		\n		\n			\n			4\n			\n			\n			5/25\n			\n			\n			動作音樂(四)\n\n			音高認識\n\n			拍子(四)\n			\n			\n			\n				New : Galloping\n				音高CDE 聽唱\n				2拍練習 \n			\n			\n		\n		\n			\n			停課\n			\n			\n			6/1\n			\n			\n			端午節連假\n			\n		\n		\n			\n			5\n			\n			\n			6/8\n			\n			\n			動作音樂(五)\n\n			音高認識\n\n			拍子(五)\n			\n			\n			\n				New : Skipping\n				音高CDE創作\n				2、3、4拍混合 \n			\n			\n		\n		\n			\n			6\n			\n			\n			6/15\n			\n			\n			認識五線譜(一)\n\n			音高認識\n\n			拍子(四)\n			\n			\n			\n				線/間 的概念\n				音高CDEFG 上/下行聽唱\n				2、3、4拍進階練習  \n			\n			\n		\n		\n			\n			7\n			\n			\n			6/22\n			\n			\n			認識五線譜(一)\n\n			音高認識\n\n			節奏型認識\n			\n			\n			\n				線/間 的應用\n				音高CDEFG 創作旋律\n				Anna-past/Dac-tylic\n			\n			\n		\n		\n			\n			8\n			\n			\n			6/29\n			\n			\n			認識五線譜(二)\n\n			音高認識\n\n			節奏型認識\n			\n			\n			\n				中央CDE在五線譜的位置\n				音高CDEFGABC 上/下行聽唱\n				New : Tro-chee\n			\n			\n		\n		\n			\n			9\n			\n			\n			7/6\n			\n			\n			認識五線譜(二)\n\n			音高認識\n\n			節奏型認識\n			\n			\n			\n				中央CDEFG在五線譜的位置\n				音高CDEFGAC 創作旋律\n				New : I-amb\n			\n			\n		\n		\n			\n			10\n			\n			\n			7/13\n			\n			\n			認識五線譜(二)\n\n			音高認識\n\n			節奏型認識\n			\n			\n			\n				中央CDEFGABC在五線譜的位置\n				C大調裡C,G的代表的意義\n				四種節奏混合練習\n			\n			\n		\n		\n			\n			11\n			\n			\n			7/20\n			\n			\n			休止符的認識\n\n			節奏型認識\n			\n			\n			\n				大調/小調的音感建立\n				休止符的概念與應用\n				New : An-pha-brac\n			\n			\n		\n		\n			\n			12\n			\n			\n			7/27\n			\n			\n			休止符的認識\n\n			樂句的概念\n			\n			\n			休止符在拍號裡的應用\n\n			如何分辨樂句\n			\n		\n		\n			\n			13\n			\n			\n			8/3\n			\n			\n			連結線的認識(一)\n\n			帶入Plastic Animee\n			\n			\n			連結線的概念與應用\n\n			教唱樂曲\n			\n		\n		\n			\n			14\n			\n			\n			8/10\n			\n			\n			連結線的認識(二)\n\n			Plastic Animee\n			\n			\n			連結線與五個節奏型的關聯\n\n			樂曲與動作的連結\n			\n		\n		\n			\n			15\n			\n			\n			8/17\n			\n			\n			總結\n			\n			\n			總結五種動作音,五個節奏音型\n\n			三種基本拍,C to C 音階\n\n			Plastic Animee 完整表演\n			\n		\n	\n\n\n上課教室位置圖\n\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-05-04 00:00:00', '2025-08-17 00:00:00', '201教室', 25.0367564, 121.519047, '3000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50715', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新開班】達克羅茲兒童音樂律動(適幼兒園大班-2年級)【3月17日上午9點開放報名】', `description`='★本課程開班標準：報名繳費達10人。 \n\n★授課老師：張慈珊老師 、賴怡穎老師   \n\n★課程主題及教學內容將依學員程度及學習狀況斟酌調整\n\n\n	\n		\n			\n			堂數\n			\n			\n			日期\n			\n			\n			課程主題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			5/4\n			\n			\n			動作音樂(一)\n\n			高音低音(一)\n\n			拍子(一)\n			\n			\n			\n				Walking Jogging\n				用動物帶入高低音的差別\n				拍點在哪裡？\n			\n			\n		\n		\n			\n			2\n			\n			\n			5/11\n			\n			\n			動作音樂(二)\n\n			高/低 + 強/弱\n\n			拍子(二)\n			\n			\n			\n				New : Marching \n				小鳥/大象 + f/p\n				4拍練習\n			\n			\n		\n		\n			\n			3\n			\n			\n			5/18\n			\n			\n			動作音樂(三)\n\n			高/低 + 強/弱\n\n			拍子(三)\n			\n			\n			\n				New : Swing\n				高/低音譜記號 + f/p\n				3拍練習\n			\n			\n		\n		\n			\n			4\n			\n			\n			5/25\n			\n			\n			動作音樂(四)\n\n			音高認識\n\n			拍子(四)\n			\n			\n			\n				New : Galloping\n				音高CDE 聽唱\n				2拍練習 \n			\n			\n		\n		\n			\n			停課\n			\n			\n			6/1\n			\n			\n			端午節連假\n			\n		\n		\n			\n			5\