INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9360290', '天文親子營【星座】', '臺北市低收入家庭通過驗證可免費參加本活動，歡迎來電詢問及報名!「天文親子營」透過生動的展示場導覽、深入淺出的主題課程，帶您認識星座及相關的天文新知，還有星座盤動手做DIY，可以從動手做中學習如何尋找星座、並認識每個星座的特別之處 。活動中也安排了觀賞宇宙劇場、立體劇場影片，以及搭乘宇宙探險車等，活動內容豐富有趣又活潑，歡迎親子及祖孫一起參加！活動時間：第 1 梯次：3月 8日（六）08:50-16:30。第 2 梯次：3月 9日（日）08:50-16:30。第 3 梯次：3月 16日（日）08:50-16:30。活動對象：國小一年級以上親子，歡迎祖孫報名參加，本活動為親子活動，每組報名需至少一位家長陪同參加，僅接受國小以上學童報名。活動費用：一般民眾：須購買展示場、宇宙探險、11:00宇宙劇場、13:00立體劇場門票 ，票價請參閱購票資訊。※本活動為套裝行程，不接受單獨行程購票，亦不接受其他優惠套票抵用。臺北市低收入家庭：免費（含午餐便當）。報名日期：一般民眾：3月 4日（二）09:00起開放網路報名，一次最多登錄4個名額，共130個名額，額滿為止。臺北市低收入家庭：3月 4日（二）10:00起撥打以下電話報名（每人每年度限參加1次）。洽詢電話：02-28314551轉 211或 204 &nbsp;推廣組。活動流程與其他注意事項：請參考活動簡章。', '臺北市立天文科學教育館', '無資料', '2025-03-08 00:00:00', '2025-03-16 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A41B18009DFCF744', '[]') ON DUPLICATE KEY UPDATE `activity_name`='天文親子營【星座】', `description`='臺北市低收入家庭通過驗證可免費參加本活動，歡迎來電詢問及報名!「天文親子營」透過生動的展示場導覽、深入淺出的主題課程，帶您認識星座及相關的天文新知，還有星座盤動手做DIY，可以從動手做中學習如何尋找星座、並認識每個星座的特別之處 。活動中也安排了觀賞宇宙劇場、立體劇場影片，以及搭乘宇宙探險車等，活動內容豐富有趣又活潑，歡迎親子及祖孫一起參加！活動時間：第 1 梯次：3月 8日（六）08:50-16:30。第 2 梯次：3月 9日（日）08:50-16:30。第 3 梯次：3月 16日（日）08:50-16:30。活動對象：國小一年級以上親子，歡迎祖孫報名參加，本活動為親子活動，每組報名需至少一位家長陪同參加，僅接受國小以上學童報名。活動費用：一般民眾：須購買展示場、宇宙探險、11:00宇宙劇場、13:00立體劇場門票 ，票價請參閱購票資訊。※本活動為套裝行程，不接受單獨行程購票，亦不接受其他優惠套票抵用。臺北市低收入家庭：免費（含午餐便當）。報名日期：一般民眾：3月 4日（二）09:00起開放網路報名，一次最多登錄4個名額，共130個名額，額滿為止。臺北市低收入家庭：3月 4日（二）10:00起撥打以下電話報名（每人每年度限參加1次）。洽詢電話：02-28314551轉 211或 204 &nbsp;推廣組。活動流程與其他注意事項：請參考活動簡章。', `organizer`='臺北市立天文科學教育館', `address`='無資料', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A41B18009DFCF744', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9327647', '建成分館3月「雙連電影院」精選好片上映', '建成分館於3月第2、4個週日播放精彩影片，提供您週末假日休憩和充電的好去處，全程參與單一場次可獲得閱讀存摺點數5點，歡迎蒞臨觀賞。一、活動時間：每月第2、4個週日下午2：00起。二、播映影片：3月9日(週日)：老娘演很大（輔導級，片長96分）3月23日(週日)：溫特的故事：泳不放棄（普遍級，片長113分）三、活動地點：臺北市立圖書館建成分館多功能活動室。(臺北市大同區民生西路198-20號4樓，雙連市場4樓)四、注意事項：&nbsp;(一)請依據影片分級制度入場觀賞。(二)請準時入場。五、交通：臺北市立圖書館-分館閱覽室簡介-建成分館簡介 (gov.taipei)', '臺北市立圖書館', '無資料', '2025-02-24 00:00:00', '2025-03-23 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F1EB6675E1CD07E7', '[]') ON DUPLICATE KEY UPDATE `activity_name`='建成分館3月「雙連電影院」精選好片上映', `description`='建成分館於3月第2、4個週日播放精彩影片，提供您週末假日休憩和充電的好去處，全程參與單一場次可獲得閱讀存摺點數5點，歡迎蒞臨觀賞。一、活動時間：每月第2、4個週日下午2：00起。二、播映影片：3月9日(週日)：老娘演很大（輔導級，片長96分）3月23日(週日)：溫特的故事：泳不放棄（普遍級，片長113分）三、活動地點：臺北市立圖書館建成分館多功能活動室。(臺北市大同區民生西路198-20號4樓，雙連市場4樓)四、注意事項：&nbsp;(一)請依據影片分級制度入場觀賞。(二)請準時入場。五、交通：臺北市立圖書館-分館閱覽室簡介-建成分館簡介 (gov.taipei)', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-24 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F1EB6675E1CD07E7', `image_url`='[]';
