INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a0f2ffdc02b3096e65c8317bbc3e91ef', '3/22(六)真人圖書分享會-買房首購族的必修攻略/陳宇凱', '講座簡介：好不容易存了一筆頭期款的買房首購族，遇上現今房市政策多變及詐騙猖獗的情況下，該如何保全自己的資金買到理想的房子呢？自住購屋講師陳宇凱再次蒞臨真人圖書館，為買房首購族量身打造一堂買房必修講座， 將從以下三面向深入介紹，讓你輕鬆掌握買房重點！一、房貸應用：了解最新政府房貸信用管制政策，並且快速了解銀行審核房貸邏輯。二、房產活化：運用房產活化來規劃退休配置。三、房產傳承：快速釐清遺產稅、贈與稅、土增稅、房地合一稅等基礎房產買賣、傳承稅負問題。', '新北市立圖書館', '新北市板橋區貴興路139號', '新北市立圖書館總館1樓活動推廣區', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3/22(六)真人圖書分享會-買房首購族的必修攻略/陳宇凱', `description`='講座簡介：好不容易存了一筆頭期款的買房首購族，遇上現今房市政策多變及詐騙猖獗的情況下，該如何保全自己的資金買到理想的房子呢？自住購屋講師陳宇凱再次蒞臨真人圖書館，為買房首購族量身打造一堂買房必修講座， 將從以下三面向深入介紹，讓你輕鬆掌握買房重點！一、房貸應用：了解最新政府房貸信用管制政策，並且快速了解銀行審核房貸邏輯。二、房產活化：運用房產活化來規劃退休配置。三、房產傳承：快速釐清遺產稅、贈與稅、土增稅、房地合一稅等基礎房產買賣、傳承稅負問題。', `organizer`='新北市立圖書館', `address`='新北市板橋區貴興路139號', `location`='新北市立圖書館總館1樓活動推廣區', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a0f2ffdc02b3096e3c4cf60248d466df', '【新北市立圖書館總館】3/8 洪鈞培健康公益講座', '本館與洪鈞培文教基金會合作辦理公益系列講座，邀請各大醫院院長、副院長、外科主任及各科專業精神、神經科專家蒞臨演講，3月將以「腦部健康・快樂生活」、「肺癌防治・掌握先機」兩大主題深入介紹，講座免費入場，將針對專業的經驗與會民眾共同分享，歡迎各界人士踴躍參加。【免費入場，直接入座，不需報名】★上午場名稱：腦部健康・快樂生活時間：3/08(六)10:00-12:00光田綜合醫院沙鹿總院 陳子勇院長★下午場名稱：肺防治癌・掌握先機時間：3/8(六)14:00-16:00臺大醫院癌醫中心分院副院長 王鶴健教授', '新北市立圖書館', '新北市板橋區貴興路139號', '新北市立圖書館總館3樓演講廳', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館總館】3/8 洪鈞培健康公益講座', `description`='本館與洪鈞培文教基金會合作辦理公益系列講座，邀請各大醫院院長、副院長、外科主任及各科專業精神、神經科專家蒞臨演講，3月將以「腦部健康・快樂生活」、「肺癌防治・掌握先機」兩大主題深入介紹，講座免費入場，將針對專業的經驗與會民眾共同分享，歡迎各界人士踴躍參加。【免費入場，直接入座，不需報名】★上午場名稱：腦部健康・快樂生活時間：3/08(六)10:00-12:00光田綜合醫院沙鹿總院 陳子勇院長★下午場名稱：肺防治癌・掌握先機時間：3/8(六)14:00-16:00臺大醫院癌醫中心分院副院長 王鶴健教授', `organizer`='新北市立圖書館', `address`='新北市板橋區貴興路139號', `location`='新北市立圖書館總館3樓演講廳', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b6a8c907f37a26088be587', '夢與復原 - 長笛與鋼琴的對話', '雅卓藝術多年來為國內外專業長笛演奏家打造藝文推廣平台，致力於提升長笛音樂藝術的普及與發展。作曲家郭嘉琳博士為加拿大歸國的優秀作曲家，近年來致力於台加兩國文化交流與推廣。郭老師的作品細膩而充滿人性溫暖。對音樂會發起人的郭老師來說，也是充滿愛與感恩的旅程。\r\n\r\n時間：2025/04/26 14:00開演\r\n地點：台大藝文中心雅頌坊\r\n演出者：長笛/潘宗賢 鋼琴/游適伃 單簧管/邱詩平 長笛/卓彥秀', '雅卓藝術', '臺北市中正區羅斯福路三段302號8樓', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '臺大藝文中心雅頌坊', 25.03240487, 121.5198839, '全票：380元', 'https://www.opentix.life/event/1879012363642134529', '[]') ON DUPLICATE KEY UPDATE `activity_name`='夢與復原 - 長笛與鋼琴的對話', `description`='雅卓藝術多年來為國內外專業長笛演奏家打造藝文推廣平台，致力於提升長笛音樂藝術的普及與發展。作曲家郭嘉琳博士為加拿大歸國的優秀作曲家，近年來致力於台加兩國文化交流與推廣。郭老師的作品細膩而充滿人性溫暖。對音樂會發起人的郭老師來說，也是充滿愛與感恩的旅程。\r\n\r\n時間：2025/04/26 14:00開演\r\n地點：台大藝文中心雅頌坊\r\n演出者：長笛/潘宗賢 鋼琴/游適伃 單簧管/邱詩平 長笛/卓彥秀', `organizer`='雅卓藝術', `address`='臺北市中正區羅斯福路三段302號8樓', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='臺大藝文中心雅頌坊', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='全票：380元', `source_url`='https://www.opentix.life/event/1879012363642134529', `image_url`='[]';
