INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b70ae607f37a26088be58f', '玉龍山游虺-塵三個展  ', ' 蛇年新氣象，乙巳年穎川畫廊隆重推出藝術家塵三個展「玉龍山游虺」。\r\n此次展覽以雲南玉龍山為靈感泉源，從雪山的壯闊景致激發出心靈的迴響。玉龍山頂終年白雪靄靄，山腰雲騰霧繞，遠望如一條矯健的玉龍，從碧空婉蜒而來的壯麗意象，與蛇年象徵彼此呼應。\r\n塵三即興揮灑的筆觸如情感的自然流瀉，將繽紛亮麗的色彩化作情感的昇華，捕捉眼前不可思議的美景，每一筆都是對眼前山水的讚美與歌詠。此次展出的水墨作品〈洱海〉、〈靈山路〉、〈宿家歡〉、〈桃花弄〉等作品，輕逸出塵的色彩如仙子下凡點亮人間，又不失對生命的期許與讚嘆 ，帶點歡樂愉悅的氣息。油畫作品〈刑山〉、〈輞川〉、〈洱海玄境〉、〈雪地〉、如生命的謳歌，又有著對眼前虛幻美景的神往。塵三之水墨作品遠看恬淡怡人，風光旑旎如入桃花源尋幽；油畫作品色彩紛呈，靜中有動、動中有「境」，此境不單指「意境 」之妙，更有超越時空的個人絕對意志之表徵。\r\n 雄鷹盤旋於蒼穹，振翅九霄翱翔千里，颯爽英姿宛若王者叱吒雲霓。塵三用快意瀟灑的筆觸，書寫著生命的激情與理想的探求，凌雲之志不因年紀而自縛。其超越形式的自由與豁達，提醒人在逆境中用昂揚的鬥志衝破難關，方能借力順風翱翔，智慧之泉源源不絕湧現。也期許觀者能從作品中找到心靈的共鳴與屬於自己的桃花源。', '穎川畫廊', '臺北市中正區仁愛路一段45號2F', '2025-03-08 00:00:00', '2025-04-25 00:00:00', '穎川畫廊', 25.03240487, 121.5198839, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='玉龍山游虺-塵三個展  ', `description`=' 蛇年新氣象，乙巳年穎川畫廊隆重推出藝術家塵三個展「玉龍山游虺」。\r\n此次展覽以雲南玉龍山為靈感泉源，從雪山的壯闊景致激發出心靈的迴響。玉龍山頂終年白雪靄靄，山腰雲騰霧繞，遠望如一條矯健的玉龍，從碧空婉蜒而來的壯麗意象，與蛇年象徵彼此呼應。\r\n塵三即興揮灑的筆觸如情感的自然流瀉，將繽紛亮麗的色彩化作情感的昇華，捕捉眼前不可思議的美景，每一筆都是對眼前山水的讚美與歌詠。此次展出的水墨作品〈洱海〉、〈靈山路〉、〈宿家歡〉、〈桃花弄〉等作品，輕逸出塵的色彩如仙子下凡點亮人間，又不失對生命的期許與讚嘆 ，帶點歡樂愉悅的氣息。油畫作品〈刑山〉、〈輞川〉、〈洱海玄境〉、〈雪地〉、如生命的謳歌，又有著對眼前虛幻美景的神往。塵三之水墨作品遠看恬淡怡人，風光旑旎如入桃花源尋幽；油畫作品色彩紛呈，靜中有動、動中有「境」，此境不單指「意境 」之妙，更有超越時空的個人絕對意志之表徵。\r\n 雄鷹盤旋於蒼穹，振翅九霄翱翔千里，颯爽英姿宛若王者叱吒雲霓。塵三用快意瀟灑的筆觸，書寫著生命的激情與理想的探求，凌雲之志不因年紀而自縛。其超越形式的自由與豁達，提醒人在逆境中用昂揚的鬥志衝破難關，方能借力順風翱翔，智慧之泉源源不絕湧現。也期許觀者能從作品中找到心靈的共鳴與屬於自己的桃花源。', `organizer`='穎川畫廊', `address`='臺北市中正區仁愛路一段45號2F', `start_date`='2025-03-08 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='穎川畫廊', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b8015c8f15d8562cfcd6ea', '青天白日滿地「虹」日月星晨 - 積吶虹光', '在青天的寧靜中，那無垠的白日鋪展化作一片溫暖的光，親吻著大地，虹在遠方浮現如晨星悄然映在空中，跨越日與月之間。日出時，光如暖流將一切喚醒；月升時，銀輝輕拂著虹；星晨點點時，似漫天閃爍的心跳，在虛空中輕聲低語。每一縷光、每一抹影，都彷彿訴說著日月星辰的秘密，一種無聲的愛超越了時間與空間，凝視著廣袤的宇宙，仰望那由虹編織的霓裳，彷彿見證了日與月相依、星與晨共舞。\r\n\r\nhttps://artemperor.tw/tidbits/17845', '無資料', '臺南市臺南市歸仁文化中心 第一畫廊 (台南市歸仁區信義南路78號)', '2025-02-26 00:00:00', '2025-02-26 00:00:00', '青天白日滿地「虹」日月星晨 - 積吶虹光', 0, 0, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='青天白日滿地「虹」日月星晨 - 積吶虹光', `description`='在青天的寧靜中，那無垠的白日鋪展化作一片溫暖的光，親吻著大地，虹在遠方浮現如晨星悄然映在空中，跨越日與月之間。日出時，光如暖流將一切喚醒；月升時，銀輝輕拂著虹；星晨點點時，似漫天閃爍的心跳，在虛空中輕聲低語。每一縷光、每一抹影，都彷彿訴說著日月星辰的秘密，一種無聲的愛超越了時間與空間，凝視著廣袤的宇宙，仰望那由虹編織的霓裳，彷彿見證了日與月相依、星與晨共舞。\r\n\r\nhttps://artemperor.tw/tidbits/17845', `organizer`='無資料', `address`='臺南市臺南市歸仁文化中心 第一畫廊 (台南市歸仁區信義南路78號)', `start_date`='2025-02-26 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='青天白日滿地「虹」日月星晨 - 積吶虹光', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
