INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9362210', '大安分處-台北杜鵑花季暨租稅宣導活動', '&nbsp; &nbsp; (一)活動名稱：台北杜鵑花季暨租稅宣導活動。&nbsp; &nbsp;&nbsp;(二)活動時間：114年3月1日（星期六）下午2時至4時。&nbsp; &nbsp;&nbsp;(三)活動地點：大安森林公園3號出口大草坪。&nbsp; &nbsp;&nbsp;(四)活動內容：&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;１、完成現場指定活動，即可兌換精美小禮物1份。&ensp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;２、捐贈114年1-3月未登打統一編號且消費金額大於10元雲端發票，可兌換宣導品。（每人每次&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;限兌換3份宣導品，數量有限，換完為止。）&nbsp; &nbsp;&nbsp;(五)說明：&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;１、本活動所募發票將全數捐贈公益慈善團體，雲端發票經捐贈完成，即無法退還或兌獎。&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;２、宣導品兌換以現場實物為準，主辦單位保有修改或變更宣導品的權利。&ensp;&ensp;聯絡人：大安分處&ensp;范小姐&nbsp; &nbsp;聯絡電話：2358-1770分機413=====================稅務宣導=========================★雲端發票專屬獎高達13.67億元，500元獎245萬組！發票存載具，對獎機會多1次！★歡迎申辦以電子方式傳送繳款書及繳納證明。★稅務視訊服務雲空中E化無國界，一鍵就能搞定稅務大小事。★國地稅免付費專線整合為0800-000-321。★納稅者權利保護法已施行，本處設置納保官保障納稅者權益。★請多加利用財政部地方稅LINE官方帳號與智慧客服。★直撥退稅線上回復，免擔心支票遺失或逾期。★當志工樂趣多，邀請一同加入志工服務行列。★申辦「稅籍異動即時通」服務，讓您掌握不動產移轉動態。★稅捐稽徵法修正，稅捐逾繳納期限始繳納，須加徵滯納金之加徵方式，修正為「每逾3日」按滯納數&nbsp; &nbsp;額加徵1％，總加徵率降為10％。★性別平等從你我做起，落實性別平權繼承與贈與不分性別。★臺北市公益性出租房屋租稅優惠。★國外帶回之免稅菸酒不得販賣，網路禁賣菸酒。★對滯納（欠）使用牌照稅案件，請交通工具所有人或使用人依限繳納，以免欠稅車輛使用（停放）&nbsp; &nbsp;公共道路被查獲而受罰。★交通工具如不擬使用，請向監理機關申報停止使用。★請多加利用各項E化繳稅管道（含行動支付、臨櫃信用卡、TW&ensp;FidO、Line&ensp;Pay等）及財政部擴大&nbsp; &nbsp;線上繳稅機制。★不動產移轉一站式服務。★臺北市分期繳納地方稅申請辦法。★全功能自動化服務機自助申辦或查調稅務案件、補發稅單及繳稅。★房屋稅差別稅率2.0新制(俗稱囤房稅2.0)於113年7月起施行，自住住家用房屋本人、配偶或直系親屬&nbsp; &nbsp;應辦竣戶籍登記，始可適用自住住家用稅率課徵房屋稅。', '臺北市稅捐稽徵處', '無資料', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8FA899C722BFE1F1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大安分處-台北杜鵑花季暨租稅宣導活動', `description`='&nbsp; &nbsp; (一)活動名稱：台北杜鵑花季暨租稅宣導活動。&nbsp; &nbsp;&nbsp;(二)活動時間：114年3月1日（星期六）下午2時至4時。&nbsp; &nbsp;&nbsp;(三)活動地點：大安森林公園3號出口大草坪。&nbsp; &nbsp;&nbsp;(四)活動內容：&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;１、完成現場指定活動，即可兌換精美小禮物1份。&ensp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;２、捐贈114年1-3月未登打統一編號且消費金額大於10元雲端發票，可兌換宣導品。（每人每次&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;限兌換3份宣導品，數量有限，換完為止。）&nbsp; &nbsp;&nbsp;(五)說明：&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;１、本活動所募發票將全數捐贈公益慈善團體，雲端發票經捐贈完成，即無法退還或兌獎。&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;２、宣導品兌換以現場實物為準，主辦單位保有修改或變更宣導品的權利。&ensp;&ensp;聯絡人：大安分處&ensp;范小姐&nbsp; &nbsp;聯絡電話：2358-1770分機413=====================稅務宣導=========================★雲端發票專屬獎高達13.67億元，500元獎245萬組！發票存載具，對獎機會多1次！★歡迎申辦以電子方式傳送繳款書及繳納證明。★稅務視訊服務雲空中E化無國界，一鍵就能搞定稅務大小事。★國地稅免付費專線整合為0800-000-321。★納稅者權利保護法已施行，本處設置納保官保障納稅者權益。★請多加利用財政部地方稅LINE官方帳號與智慧客服。★直撥退稅線上回復，免擔心支票遺失或逾期。★當志工樂趣多，邀請一同加入志工服務行列。★申辦「稅籍異動即時通」服務，讓您掌握不動產移轉動態。★稅捐稽徵法修正，稅捐逾繳納期限始繳納，須加徵滯納金之加徵方式，修正為「每逾3日」按滯納數&nbsp; &nbsp;額加徵1％，總加徵率降為10％。★性別平等從你我做起，落實性別平權繼承與贈與不分性別。★臺北市公益性出租房屋租稅優惠。★國外帶回之免稅菸酒不得販賣，網路禁賣菸酒。★對滯納（欠）使用牌照稅案件，請交通工具所有人或使用人依限繳納，以免欠稅車輛使用（停放）&nbsp; &nbsp;公共道路被查獲而受罰。★交通工具如不擬使用，請向監理機關申報停止使用。★請多加利用各項E化繳稅管道（含行動支付、臨櫃信用卡、TW&ensp;FidO、Line&ensp;Pay等）及財政部擴大&nbsp; &nbsp;線上繳稅機制。★不動產移轉一站式服務。★臺北市分期繳納地方稅申請辦法。★全功能自動化服務機自助申辦或查調稅務案件、補發稅單及繳稅。★房屋稅差別稅率2.0新制(俗稱囤房稅2.0)於113年7月起施行，自住住家用房屋本人、配偶或直系親屬&nbsp; &nbsp;應辦竣戶籍登記，始可適用自住住家用稅率課徵房屋稅。', `organizer`='臺北市稅捐稽徵處', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8FA899C722BFE1F1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9362206', '[轉知]中正區2025歷史復活節，系列豐富藝文活動2/15-10/31登場！歡迎免費報名參加！', '「2025歷史復活節～中正．時空旅行」系列藝文活動，於114年2月15日至10月31日登場！豐富精采的系列活動，邀您一起互動體驗，品味獨特的中正區地方文化！詳情請上臺北市中正區公所網站基層藝文專區或歷史復活節FB粉絲團查詢，活動簡介如下：5月至10月「食」－美味食刻．尋味食客。4月26日、6月7日「衣」－幸福約，布約？客家文化體驗及蓮花季單身聯誼活動。9月20日「住」－建築．眷逐，嘉禾新村眷村導覽手作活動。3月至9月「行」－邊走．遍讀，包含電影欣賞、博物館日導覽、古蹟電子集章換禮物、實境解謎遊戲、新住民親子課程等。3月29日「育」－轉大人的必修課，中正區工藝文化體驗成年禮。2月15日「樂」－蛇來弄樂．親子戲音，親子國樂體驗課程。10月18日歷史復活節－萬國博覽市集，含成果影片．公益設攤．互動體驗．紀念印章．古蹟音樂會活動。', '臺北市政府工務局衛生下水道工程處', '無資料', '2025-02-24 00:00:00', '2025-10-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=3E7568E3A0198FA9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='[轉知]中正區2025歷史復活節，系列豐富藝文活動2/15-10/31登場！歡迎免費報名參加！', `description`='「2025歷史復活節～中正．時空旅行」系列藝文活動，於114年2月15日至10月31日登場！豐富精采的系列活動，邀您一起互動體驗，品味獨特的中正區地方文化！詳情請上臺北市中正區公所網站基層藝文專區或歷史復活節FB粉絲團查詢，活動簡介如下：5月至10月「食」－美味食刻．尋味食客。4月26日、6月7日「衣」－幸福約，布約？客家文化體驗及蓮花季單身聯誼活動。9月20日「住」－建築．眷逐，嘉禾新村眷村導覽手作活動。3月至9月「行」－邊走．遍讀，包含電影欣賞、博物館日導覽、古蹟電子集章換禮物、實境解謎遊戲、新住民親子課程等。3月29日「育」－轉大人的必修課，中正區工藝文化體驗成年禮。2月15日「樂」－蛇來弄樂．親子戲音，親子國樂體驗課程。10月18日歷史復活節－萬國博覽市集，含成果影片．公益設攤．互動體驗．紀念印章．古蹟音樂會活動。', `organizer`='臺北市政府工務局衛生下水道工程處', `address`='無資料', `start_date`='2025-02-24 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=3E7568E3A0198FA9', `image_url`='[]';
