INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bbf1e58f15d8562cfcd6ef', '【淺淺微風】－羅宇成水彩創作展', '展覽名稱｜【淺淺微風】－羅宇成水彩創作展\r\n展覽期間｜2025.03.07－2025.04.27\r\n開幕茶會｜2025.03.09 Sun. 15:00\r\n開放時間｜10：00－19：00（每月一、三週之星期二休館）\r\n地　　點｜光點藝術中心　三樓展覽廳\r\n地　　址｜新北市鶯歌區陶瓷街18號\r\n展覽專線｜02-2678-6577\r\n\r\n藝術家展覽自述｜\r\n自從開始專注於「海系列」創作，不知不覺間，這段旅程已經走過近十年。至今，我依然在「海」的世界裡沉浮，持續探索，未曾止步。這次展覽的名稱為「淺淺微風」如同海風輕輕吹拂的瞬間，捕捉那份柔和而深遠的流動感。展覽中乘載我對海洋的觀察與情感，從大海到隱藏其中的生命律動，我透過畫筆呈現我對海洋的感受－既廣闊又細膩，深沈卻又輕盈。「淺淺微風」是一種輕盈的觸動，也是一場與海洋對話的邀請。\r\n\r\n海洋帶給我取之不盡、用之不竭的靈感，但我的創作不僅僅停留在「如實描繪」。因此，我嘗試以隨性的染色、率性的疊色，讓畫面在偶然與刻意之間交織，最後再尋找平衡，使作品達到完整的狀態。如今，這樣的創作方式已經成為我的習慣，讓我在作畫時能夠更輕鬆愉快地享受每一筆觸的流動。\r\n\r\n我始終在日常觀察中尋找靈感，透過生活片段來反映自己對世界的感知與理解。身為一名熱愛海洋的創作者，我深深著迷於海洋的無窮魅力，特別是海洋生物的多樣性與奇妙生態。海洋不僅是壯麗的自然景觀，更是無數生命繁衍生息的舞台。每一種生物的外型、色彩與行為，都隱藏著關於生存、逃逸、偽裝與繁衍的故事。這些故事不斷啟發著我，驅使我透過繪畫來記錄與表達海洋世界的奧秘與生命的韻律，也是與我生命中的連結。', '鶯歌光點美學館', '新北市鶯歌區陶瓷街18號3F', '2025-03-07 00:00:00', '2025-04-27 00:00:00', '光點藝術中心', 24.9566258, 121.3466269, '無資料', 'https://www.yinggo.com.tw/blogs/%E7%95%B6%E6%9C%9F%E5%B1%95%E8%A6%BD', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【淺淺微風】－羅宇成水彩創作展', `description`='展覽名稱｜【淺淺微風】－羅宇成水彩創作展\r\n展覽期間｜2025.03.07－2025.04.27\r\n開幕茶會｜2025.03.09 Sun. 15:00\r\n開放時間｜10：00－19：00（每月一、三週之星期二休館）\r\n地　　點｜光點藝術中心　三樓展覽廳\r\n地　　址｜新北市鶯歌區陶瓷街18號\r\n展覽專線｜02-2678-6577\r\n\r\n藝術家展覽自述｜\r\n自從開始專注於「海系列」創作，不知不覺間，這段旅程已經走過近十年。至今，我依然在「海」的世界裡沉浮，持續探索，未曾止步。這次展覽的名稱為「淺淺微風」如同海風輕輕吹拂的瞬間，捕捉那份柔和而深遠的流動感。展覽中乘載我對海洋的觀察與情感，從大海到隱藏其中的生命律動，我透過畫筆呈現我對海洋的感受－既廣闊又細膩，深沈卻又輕盈。「淺淺微風」是一種輕盈的觸動，也是一場與海洋對話的邀請。\r\n\r\n海洋帶給我取之不盡、用之不竭的靈感，但我的創作不僅僅停留在「如實描繪」。因此，我嘗試以隨性的染色、率性的疊色，讓畫面在偶然與刻意之間交織，最後再尋找平衡，使作品達到完整的狀態。如今，這樣的創作方式已經成為我的習慣，讓我在作畫時能夠更輕鬆愉快地享受每一筆觸的流動。\r\n\r\n我始終在日常觀察中尋找靈感，透過生活片段來反映自己對世界的感知與理解。身為一名熱愛海洋的創作者，我深深著迷於海洋的無窮魅力，特別是海洋生物的多樣性與奇妙生態。海洋不僅是壯麗的自然景觀，更是無數生命繁衍生息的舞台。每一種生物的外型、色彩與行為，都隱藏著關於生存、逃逸、偽裝與繁衍的故事。這些故事不斷啟發著我，驅使我透過繪畫來記錄與表達海洋世界的奧秘與生命的韻律，也是與我生命中的連結。', `organizer`='鶯歌光點美學館', `address`='新北市鶯歌區陶瓷街18號3F', `start_date`='2025-03-07 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='光點藝術中心', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='https://www.yinggo.com.tw/blogs/%E7%95%B6%E6%9C%9F%E5%B1%95%E8%A6%BD', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bc29ec8f15d8562cfcd6f0', '繪本、影像與兒童｜春季班', '「繪本、影像與兒童｜春季班」新課程即將登場，將透過繪本賞析、共讀經典兒童文學故事與電影，帶你呼喚住在心底的小孩，一起找回童心，探索繪本的力量，享受閱讀繪本的樂趣。\r\n￼\r\n上完一學期的課，你會學到......\r\n・認識60本英、美、歐、日、台等世界各國的好繪本！\r\n・深入賞析繪本大師的人生與創作的精采繪本！\r\n・共讀兒童文學經典童書與電影！\r\n・朗讀與演奏繪本的技巧！\r\n・探索「兒童的特質」＆賞析兒童人權議題繪本！\r\n・還有......還有更多，來上課才會知道的喔！\r\n￼\r\n適合對象：\r\n・對繪本有興趣的大人\r\n・繪本愛好者\r\n・繪本創作者\r\n・說故事老師／志工\r\n・想了解親子共讀的家長\r\n・關心兒童的大人\r\n・童心未泯的大人\r\n・想要找回童心的大人\r\n\r\n詳細課程內容，請詳報名連結>> https://pse.is/75kbha\r\n\r\n上課日期｜3/12~7/2\r\n上課時間｜每週三 19:00（2.5小時）\r\n上課地點｜永和社區大學（新北市永和區永利路71號）\r\n\r\n【講師簡介】熊君君\r\n閱讀推廣人及文字工作者。新北市永和社區大學「繪本、影像與兒童」課程講師、「小大繪本學校」共同創辦人、國家人權博物館「兒童人權學習基地」策展人、Podcast《童書，然後呢？》節目主持人。曾任親子天下童書編輯、閱讀頻道企劃編輯、「兒童文化研究社」前社長、YOYO親子讀書會主持人，長期與「兒童文化研究社」夥伴致力於親子共讀、繪本與兒童人權的推廣。', '永和社區大學', '新北市永和區永利路71號 ', '2025-03-12 00:00:00', '2025-07-02 00:00:00', '永和社區大學', 25.00810199, 121.516745, '請詳報名購票連結。', 'https://pse.is/75kbha', '[]') ON DUPLICATE KEY UPDATE `activity_name`='繪本、影像與兒童｜春季班', `description`='「繪本、影像與兒童｜春季班」新課程即將登場，將透過繪本賞析、共讀經典兒童文學故事與電影，帶你呼喚住在心底的小孩，一起找回童心，探索繪本的力量，享受閱讀繪本的樂趣。\r\n￼\r\n上完一學期的課，你會學到......\r\n・認識60本英、美、歐、日、台等世界各國的好繪本！\r\n・深入賞析繪本大師的人生與創作的精采繪本！\r\n・共讀兒童文學經典童書與電影！\r\n・朗讀與演奏繪本的技巧！\r\n・探索「兒童的特質」＆賞析兒童人權議題繪本！\r\n・還有......還有更多，來上課才會知道的喔！\r\n￼\r\n適合對象：\r\n・對繪本有興趣的大人\r\n・繪本愛好者\r\n・繪本創作者\r\n・說故事老師／志工\r\n・想了解親子共讀的家長\r\n・關心兒童的大人\r\n・童心未泯的大人\r\n・想要找回童心的大人\r\n\r\n詳細課程內容，請詳報名連結>> https://pse.is/75kbha\r\n\r\n上課日期｜3/12~7/2\r\n上課時間｜每週三 19:00（2.5小時）\r\n上課地點｜永和社區大學（新北市永和區永利路71號）\r\n\r\n【講師簡介】熊君君\r\n閱讀推廣人及文字工作者。新北市永和社區大學「繪本、影像與兒童」課程講師、「小大繪本學校」共同創辦人、國家人權博物館「兒童人權學習基地」策展人、Podcast《童書，然後呢？》節目主持人。曾任親子天下童書編輯、閱讀頻道企劃編輯、「兒童文化研究社」前社長、YOYO親子讀書會主持人，長期與「兒童文化研究社」夥伴致力於親子共讀、繪本與兒童人權的推廣。', `organizer`='永和社區大學', `address`='新北市永和區永利路71號 ', `start_date`='2025-03-12 00:00:00', `end_date`='2025-07-02 00:00:00', `location`='永和社區大學', `latitude`=25.00810199, `longitude`=121.516745, `ticket_price`='請詳報名購票連結。', `source_url`='https://pse.is/75kbha', `image_url`='[]';
