INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9361935', '舊莊分館—「擁抱情緒」主題書展', '每個人每天都會遇到大大小小的事情，要懂得用適當的情緒來面對各種狀況，才能做出妥善的應對處理。舊莊分館透過主題書展，向讀者介紹情緒管理相關的書籍，給予讀者掌握自己情緒的建議，不會任意、無節制地釋放情緒，也不會過度壓抑導致身心皆受損，有了正確的情緒管理方式才能使生活真正過得順心，與其他人之間的相處也才能更加順利、愉快。展覽時間：3月1日至3月31日活動地點：舊莊分館2樓書展區(臺北市南港區舊莊街1段91巷11號2樓)活動對象：一般民眾交通路線：https://reurl.cc/MO81d4', '臺北市立圖書館', '無資料', '2025-02-25 00:00:00', '2025-03-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B18698C6EB82F1BC', '[]') ON DUPLICATE KEY UPDATE `activity_name`='舊莊分館—「擁抱情緒」主題書展', `description`='每個人每天都會遇到大大小小的事情，要懂得用適當的情緒來面對各種狀況，才能做出妥善的應對處理。舊莊分館透過主題書展，向讀者介紹情緒管理相關的書籍，給予讀者掌握自己情緒的建議，不會任意、無節制地釋放情緒，也不會過度壓抑導致身心皆受損，有了正確的情緒管理方式才能使生活真正過得順心，與其他人之間的相處也才能更加順利、愉快。展覽時間：3月1日至3月31日活動地點：舊莊分館2樓書展區(臺北市南港區舊莊街1段91巷11號2樓)活動對象：一般民眾交通路線：https://reurl.cc/MO81d4', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-25 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B18698C6EB82F1BC', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9360461', '東園分館「四季輪迴：二十四節氣的生活智慧」館藏特色及一般主題書展', '二十四節氣是什麼？它是如何影響我們的生活？本次館藏特色主題書展，帶領大家認識二十四節氣，以及與之衍生的養生、文化風俗、歲時節日與飲食等生活智慧。一、活動日期：2月25日至4月30日二、活動對象：一般民眾三、活動地點：東園分館3樓梯間主題書展區（臺北市東園街199號）', '臺北市立圖書館', '無資料', '2025-02-25 00:00:00', '2025-04-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B7D829FBDE8ACD0E', '[]') ON DUPLICATE KEY UPDATE `activity_name`='東園分館「四季輪迴：二十四節氣的生活智慧」館藏特色及一般主題書展', `description`='二十四節氣是什麼？它是如何影響我們的生活？本次館藏特色主題書展，帶領大家認識二十四節氣，以及與之衍生的養生、文化風俗、歲時節日與飲食等生活智慧。一、活動日期：2月25日至4月30日二、活動對象：一般民眾三、活動地點：東園分館3樓梯間主題書展區（臺北市東園街199號）', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-25 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B7D829FBDE8ACD0E', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9353408', '總館視聽室「週末電影賞析講座」3月放映會', '每月精選各國藝術電影，邀請電影導讀老師評析，引導民眾瞭解電影語言，增加觀賞電影的深度。主辦單位：臺北市立圖書館視聽室(2755-2823分機2802)參加對象：一般民眾參加方式：不需報名，免費自由參加活動地點：總館10樓會議廳活動時間：3月8日(週六)下午1：30（下午1:00開始入場，實際結束時間視影片長短而定）影片名稱：美國隊長/125分鐘/保護級講 &nbsp; &nbsp;師：江怡音場次及時間：詳情請見市圖首頁/關於市圖/服務項目/視聽服務/電影賞析時數認證：本活動提供終身學習時數認證3小時，請於現場辦理簽到', '臺北市立圖書館', '無資料', '2025-02-25 00:00:00', '2025-03-08 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=4D9F371919E6E0DA', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館視聽室「週末電影賞析講座」3月放映會', `description`='每月精選各國藝術電影，邀請電影導讀老師評析，引導民眾瞭解電影語言，增加觀賞電影的深度。主辦單位：臺北市立圖書館視聽室(2755-2823分機2802)參加對象：一般民眾參加方式：不需報名，免費自由參加活動地點：總館10樓會議廳活動時間：3月8日(週六)下午1：30（下午1:00開始入場，實際結束時間視影片長短而定）影片名稱：美國隊長/125分鐘/保護級講 &nbsp; &nbsp;師：江怡音場次及時間：詳情請見市圖首頁/關於市圖/服務項目/視聽服務/電影賞析時數認證：本活動提供終身學習時數認證3小時，請於現場辦理簽到', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-25 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=4D9F371919E6E0DA', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6712af3926b32468988294f8', '語文寫作素養-啟蒙A(適2-3年級初學、無上過寫作課程者)', '創藝學園學員參加中華民國作文教育會第64屆全國作文徵文比賽得獎人獎狀及參賽作品https://drive.google.com/drive/folders/1_wVdEhZMwVMimcIliP5wEF951Q6i_ReR?usp=sharing\n\n ★本課程計有6套不同課程大綱，舊學員學習上不會重複，完整學習至少須為1年。\n\n ★本課程開班標準：報名繳費達16人。\n\n★授課師資：林雪琪老師(本期因故授課至1/18日)、曾寶萱老師(2/15起授課)\n\n ★前期(113年9-12月)課程表  供參考\n\n\n	\n		\n			\n			堂數\n			\n			\n			日期\n			\n			\n			課程主題\n			\n			\n			學習目標\n			\n		\n		\n			\n			1\n			\n			\n			1/4\n			\n			\n			舉一反三\n			\n			\n			同義詞、反義詞的練習\n			\n		\n		\n			\n			2\n			\n			\n			1/11\n			\n			\n			心領神會\n			\n			\n			五感摹寫的運用\n			\n		\n		\n			\n			3\n			\n			\n			1/18\n			\n			\n			震古鑠今\n			\n			\n			引用名言佳句，讓文章更有深度\n			\n		\n		\n			\n			停課\n			\n			\n			1/25\n			\n			\n			農曆春節連假\n			\n		\n		\n			\n			停課\n			\n			\n			2/1\n			\n			\n			農曆春節連假\n			\n		\n		\n			\n			停課\n			\n			\n			2/8\n			\n			\n			補行上班課日\n			\n		\n		\n			\n			4\n			\n			\n			2/15\n			\n			\n			伺機而「動」\n			\n			\n			動作摹寫的練習\n			\n		\n		\n			\n			5\n			\n			\n			2/22\n			\n			\n			引經據典\n			\n			\n			舉出史實或事例，加強文章論點\n			\n		\n		\n			\n			停課\n			\n			\n			3/1\n			\n			\n			和平紀念日連假\n			\n		\n		\n			\n			6\n			\n			\n			3/8\n			\n			\n			綜合演練\n			\n		\n		\n			\n			7\n			\n			\n			3/15\n			\n			\n			瞻前顧後\n			\n			\n			讓主題鮮明深刻，全文連貫\n			\n		\n		\n			\n			8\n			\n			\n			3/22\n			\n			\n			連雲疊嶂\n			\n			\n			學習運用類疊修辭\n			\n		\n		\n			\n			9\n			\n			\n			3/29\n			\n			\n			錦上添花\n			\n			\n			運用擴寫技巧，使文章內容更豐富\n			\n		\n		\n			\n			停課\n			\n			\n			4/5\n			\n			\n			兒童節及民族掃墓節連假\n			\n		\n		\n			\n			10\n			\n			\n			4/12\n			\n			\n			龍吟虎嘯\n			\n			\n			學習狀聲詞，並運用造句。\n			\n		\n		\n			\n			11\n			\n			\n			4/19\n			\n			\n			大展鴻圖\n			\n			\n			練習視覺摹寫。\n			\n		\n		\n			\n			12\n			\n			\n			4/26\n			\n			\n			綜合演練\n			\n		\n	\n\n\n上課教室位置圖 \n\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-01-04 00:00:00', '2025-04-26 00:00:00', 'W320教室', 25.0367564, 121.519047, '2000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=41214', '[]') ON DUPLICATE KEY UPDATE `activity_name`='語文寫作素養-啟蒙A(適2-3年級初學、無上過寫作課程者)', `description`='創藝學園學員參加中華民國作文教育會第64屆全國作文徵文比賽得獎人獎狀及參賽作品https://drive.google.com/drive/folders/1_wVdEhZMwVMimcIliP5wEF951Q6i_ReR?usp=sharing\n\n ★本課程計有6套不同課程大綱，舊學員學習上不會重複，完整學習至少須為1年。\n\n ★本課程開班標準：報名繳費達16人。\n\n★授課師資：林雪琪老師(本期因故授課至1/18日)、曾寶萱老師(2/15起授課)\n\n ★前期(113年9-12月)課程表  供參考\n\n\n	\n		\n			\n			堂數\n			\n			\n			日期\n			\n			\n			課程主題\n			\n			\n			學習目標\n			\n		\n		\n			\n			1\n			\n			\n			1/4\n			\n			\n			舉一反三\n			\n			\n			同義詞、反義詞的練習\n			\n		\n		\n			\n			2\n			\n			\n			1/11\n			\n			\n			心領神會\n			\n			\n			五感摹寫的運用\n			\n		\n		\n			\n			3\n			\n			\n			1/18\n			\n			\n			震古鑠今\n			\n			\n			引用名言佳句，讓文章更有深度\n			\n		\n		\n			\n			停課\n			\n			\n			1/25\n			\n			\n			農曆春節連假\n			\n		\n		\n			\n			停課\n			\n			\n			2/1\n			\n			\n			農曆春節連假\n			\n		\n		\n			\n			停課\n			\n			\n			2/8\n			\n			\n			補行上班課日\n			\n		\n		\n			\n			4\n			\n			\n			2/15\n			\n			\n			伺機而「動」\n			\n			\n			動作摹寫的練習\n			\n		\n		\n			\n			5\n			\n			\n			2/22\n			\n			\n			引經據典\n			\n			\n			舉出史實或事例，加強文章論點\n			\n		\n		\n			\n			停課\n			\n			\n			3/1\n			\n			\n			和平紀念日連假\n			\n		\n		\n			\n			6\n			\n			\n			3/8\n			\n			\n			綜合演練\n			\n		\n		\n			\n			7\n			\n			\n			3/15\n			\n			\n			瞻前顧後\n			\n			\n			讓主題鮮明深刻，全文連貫\n			\n		\n		\n			\n			8\n			\n			\n			3/22\n			\n			\n			連雲疊嶂\n			\n			\n			學習運用類疊修辭\n			\n		\n		\n			\n			9\n			\n			\n			3/29\n			\n			\n			錦上添花\n			\n			\n			運用擴寫技巧，使文章內容更豐富\n			\n		\n		\n			\n			停課\n			\n			\n			4/5\n			\n			\n			兒童節及民族掃墓節連假\n			\n		\n		\n			\n			10\n			\n			\n			4/12\n			\n			\n			龍吟虎嘯\n			\n			\n			學習狀聲詞，並運用造句。\n			\n		\n		\n			\n			11\n			\n			\n			4/19\n			\n			\n			大展鴻圖\n			\n			\n			練習視覺摹寫。\n			\n		\n		\n			\n			12\n			\n			\n			4/26\n			\n			\n			綜合演練\n			\n		\n	\n\n\n上課教室位置圖 \n\n\n\n ', `organizer`='國立中正紀念堂管理處', `addre