INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6716a22b26b32468988295b1', '經絡養生操&能量舞（進階）', '2/4為第1堂課開始\n\n【經絡養生操】古代醫療體操結合現代運動方式(有氧、肌力、平衡、伸展)，依循人體經絡穴位及痠痛點設計以舒展全身、促進氣血運行、增強抵抗力、保持健康機能，著重於「預防與調整」。\n\n【敦煌能量舞】～結合「太極能量符號」與「敦煌舞姿元素」輔以吐納，形成風格獨特的氣功舞蹈，具多元複方的養生功效，促進自我療癒功能，著重於「修護與補充」，達到身心靈和諧。\n\n\n	\n		\n			\n			課\n\n			程\n\n			大\n\n			綱\n			\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			經絡養生操\n\n			能量氣功舞蹈\n			\n			\n			暖身、有氧律動、經絡伸展\n\n			基本訓練(腳步)+足舞\n			\n		\n		\n			\n			2\n			\n			\n			經絡養生操\n\n			能量氣功舞蹈\n			\n			\n			暖身、有氧律動、經絡伸展\n\n			基本訓練(腳步、手姿) +足舞\n			\n		\n		\n			\n			3\n			\n			\n			經絡養生操\n\n			能量氣功舞蹈\n			\n			\n			暖身、有氧律動、經絡伸展\n\n			基本訓練(腳步、手姿) +足舞\n			\n		\n		\n			\n			4\n			\n			\n			經絡養生操\n\n			能量氣功舞蹈\n			\n			\n			暖身、有氧律動、經絡伸展\n\n			基本訓練(腳步、手姿) +足舞\n			\n		\n		\n			\n			5\n			\n			\n			經絡養生操\n\n			能量氣功舞蹈\n			\n			\n			暖身、有氧律動、經絡伸展\n\n			基本訓練(腳步、手姿、身形) +足舞\n			\n		\n		\n			\n			6\n			\n			\n			經絡養生操\n\n			能量氣功舞蹈\n			\n			\n			暖身、有氧律動、經絡伸展\n\n			基本訓練(腳步、手姿、身形) +足舞\n			\n		\n		\n			\n			7\n			\n			\n			經絡養生操\n\n			能量氣功舞蹈\n			\n			\n			暖身、有氧律動、經絡伸展\n\n			基本訓練(腳步、手姿、身形) +足舞\n			\n		\n		\n			\n			8\n			\n			\n			經絡養生操\n\n			能量氣功舞蹈\n			\n			\n			暖身、有氧律動、經絡伸展\n\n			基本訓練(腳步、手姿、身形、吐納) +足舞、舞式功法\n			\n		\n		\n			\n			9\n			\n			\n			經絡養生操\n\n			能量氣功舞蹈\n			\n			\n			暖身、有氧律動、經絡伸展\n\n			基本訓練(腳步、手姿、身形、吐納) +足舞、舞式功法\n			\n		\n		\n			\n			10\n			\n			\n			經絡養生操\n\n			能量氣功舞蹈\n			\n			\n			暖身、有氧律動、經絡伸展\n\n			基本訓練(腳步、手姿、身形、吐納) +足舞、舞式功法\n			\n		\n		\n			\n			11\n			\n			\n			經絡養生操\n\n			能量氣功舞蹈\n			\n			\n			暖身、有氧律動、經絡伸展\n\n			基本訓練(腳步、手姿、身形、吐納、提沉) +足舞、呼吸律動、舞式功法\n			\n		\n		\n			\n			12\n			\n			\n			經絡養生操\n\n			能量氣功舞蹈\n			\n			\n			暖身、有氧律動、經絡伸展\n\n			基本訓練(腳步、手姿、身形、吐納、提沉) +足舞、呼吸律動\n\n			舞式功法\n			\n		\n		\n			\n			13\n			\n			\n			經絡養生操\n\n			能量氣功舞蹈\n			\n			\n			暖身、有氧律動、經絡伸展\n\n			基本訓