INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e126b3240c403d991b', '響室內樂團【情歌與民謠的對話：鄧雨賢 X 鄧麗君】（免費觀賞）', '💖演出團體介紹：\n\n響室內樂團由小提琴演奏碩士張凱竣創辦，號召多位來自國內大專院校音樂系學/碩士所組成，成員皆具備紮實的古典音樂訓練和豐富的演出經驗。我們致力於在專業演奏中融入多元的音樂元素，不僅擅長詮釋經典樂章，也能靈活演繹現代流行、跨界音樂。\n\n🕒演出時間：114年4月19日(六) 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n為了紀念台灣客家作曲家鄧雨賢逝世《80週年》，以鄧雨賢的經典台灣民謠為核心，並融入鄧麗君的華語情歌，展現台灣音樂文化的時代交匯。\n\n這次演出特別邀請到台灣新生代作曲家葉子齊，改編鄧雨賢寫作的曲目 (四季紅、雨夜花、望春風、月夜愁)，加入鄧麗君的經典名曲集(任時光從身邊流逝、甜蜜蜜、愛人、我只在乎你、獨上西樓、夜來香、恰似你的溫柔、月亮代表我的心)之元素，寫作了兩首給鋼琴五重奏的作品。\n\n演出時也特別請台灣音樂教育碩士藍翊寧為觀眾介紹曲目與導聆，讓小朋友認識台灣民謠與經典情歌，同時讓大朋友重溫昔日的感動與情懷，用音樂牽起回憶的橋梁。\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50685', '[]') ON DUPLICATE KEY UPDATE `activity_name`='響室內樂團【情歌與民謠的對話：鄧雨賢 X 鄧麗君】（免費觀賞）', `description`='💖演出團體介紹：\n\n響室內樂團由小提琴演奏碩士張凱竣創辦，號召多位來自國內大專院校音樂系學/碩士所組成，成員皆具備紮實的古典音樂訓練和豐富的演出經驗。我們致力於在專業演奏中融入多元的音樂元素，不僅擅長詮釋經典樂章，也能靈活演繹現代流行、跨界音樂。\n\n🕒演出時間：114年4月19日(六) 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n為了紀念台灣客家作曲家鄧雨賢逝世《80週年》，以鄧雨賢的經典台灣民謠為核心，並融入鄧麗君的華語情歌，展現台灣音樂文化的時代交匯。\n\n這次演出特別邀請到台灣新生代作曲家葉子齊，改編鄧雨賢寫作的曲目 (四季紅、雨夜花、望春風、月夜愁)，加入鄧麗君的經典名曲集(任時光從身邊流逝、甜蜜蜜、愛人、我只在乎你、獨上西樓、夜來香、恰似你的溫柔、月亮代表我的心)之元素，寫作了兩首給鋼琴五重奏的作品。\n\n演出時也特別請台灣音樂教育碩士藍翊寧為觀眾介紹曲目與導聆，讓小朋友認識台灣民謠與經典情歌，同時讓大朋友重溫昔日的感動與情懷，用音樂牽起回憶的橋梁。\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50685', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e126b3240c403d991c', '境外藝術【爵饗-浣熊們的爵士特餐】（免費觀賞）', '💖演出團體介紹：\n\n「境外藝術」由林語桐成立，以爵士樂創作、演奏、跨界合作為主要活動，\n\n如 2018-19連續參加南京藝術學院流行音樂高峰論壇暨爵士大師班主講、2019受日本中洲爵士音樂節、中正紀念堂、中原大學、中山堂、故宮博物院、板橋435藝文特區等場館演出。\n\n🕒演出時間：114年4月20日(日) 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n1. Equinox  Sing/ 春分之歌\n2. Blue Rondo a La Turk/ 土耳其藍調迴旋曲\n3. Nica''s Dream/ 妮卡的夢\n4. So Tinha De Ser Com Voce (This Love That I Found)/ 你是一切\n5. AGUA DE BEBER/ 甘泉\n6. WORK SONG/ 工作歌\n7. The Jody Grind/ 喬迪·格林\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50686', '[]') ON DUPLICATE KEY UPDATE `activity_name`='境外藝術【爵饗-浣熊們的爵士特餐】（免費觀賞）', `description`='💖演出團體介紹：\n\n「境外藝術」由林語桐成立，以爵士樂創作、演奏、跨界合作為主要活動，\n\n如 2018-19連續參加南京藝術學院流行音樂高峰論壇暨爵士大師班主講、2019受日本中洲爵士音樂節、中正紀念堂、中原大學、中山堂、故宮博物院、板橋435藝文特區等場館演出。\n\n🕒演出時間：114年4月20日(日) 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n1. Equinox  Sing/ 春分之歌\n2. Blue Rondo a La Turk/ 土耳其藍調迴旋曲\n3. Nica''s Dream/ 妮卡的夢\n4. So Tinha De Ser Com Voce (This Love That I Found)/ 你是一切\n5. AGUA DE BEBER/ 甘泉\n6. WORK SONG/ 工作歌\n7. The Jody Grind/ 喬迪·格林\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50686', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e126b3240c403d991d', '林中光樂會【有愛的海‧古錐的歌】（免費觀賞）', '💖演出團體介紹：\n\n林中光樂會自2002年成立，成員分別來自不同的藝術及文化領域。秉持將光明寫實的風格實踐於創作，用取材自生活中溫暖的國、台語，把傳統與現代的樂器如竹笛、三弦、胡琴、阮、吉他、打擊等語彙融合於各首曲樂中，化成自己的文化詩歌。\n\n🕒演出時間：114年4月26日(六) 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n老船長是一位熱愛大自然，熱愛海洋的詩人，他最喜歡開著他的船，四處遨遊，收集海上的故事。然而，隨著老船長年歲漸長，他回想著早年，這片大海所孕育的各式海物，是偶逢節慶時，左鄰右舍呼朋引伴用的餐食和器物。而這些與人們生存發展和文化密切的生物，因為濫捕、環境變遷，變得越來越少，老船長為此感到哀傷，尤其是大海因為各類工廠排放的廢水廢油和任意傾倒的廢棄物，導致海面不再是湛藍清澈的樣貌，四處充斥漂浮著五顏六色的污染物，海裡及海潮的生物也受到了影響。因此，老船長將他的感慨，寫成一首首的歌曲，盼望這些歌曲，能喚起人們對海洋保育、海洋永續的重視與用心。\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50687', '[]') ON DUPLICATE KEY UPDATE `activity_name`='林中光樂會【有愛的海‧古錐的歌】（免費觀賞）', `description`='💖演出團體介紹：\n\n林中光樂會自2002年成立，成員分別來自不同的藝術及文化領域。秉持將光明寫實的風格實踐於創作，用取材自生活中溫暖的國、台語，把傳統與現代的樂器如竹笛、三弦、胡琴、阮、吉他、打擊等語彙融合於各首曲樂中，化成自己的文化詩歌。\n\n🕒演出時間：114年4月26日(六) 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n老船長是一位熱愛大自然，熱愛海洋的詩人，他最喜歡開著他的船，四處遨遊，收集海上的故事。然而，隨著老船長年歲漸長，他回想著早年，這片大海所孕育的各式海物，是偶逢節慶時，左鄰右舍呼朋引伴用的餐食和器物。而這些與人們生存發展和文化密切的生物，因為濫捕、環境變遷，變得越來越少，老船長為此感到哀傷，尤其是大海因為各類工廠排放的廢水廢油和任意傾倒的廢棄物，導致海面不再是湛藍清澈的樣貌，四處充斥漂浮著五顏六色的污染物，海裡及海潮的生物也受到了影響。因此，老船長將他的感慨，寫成一首首的歌曲，盼望這些歌曲，能喚起人們對海洋保育、海洋永續的重視與用心。\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50687', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d991e', '華藝文化學會【經典世界電影名曲主題音樂會】（免費觀賞）', '💖演出團體介紹：\n\n華藝文化學會推行發揚藝術文化，積極參與各類演出，將團隊推向國內外藝術殿堂。團隊不拘泥於傳統音樂，開創具本土性及國際視野的音樂風格，致力於傳統與創新間的發展，透過多元演出形式呈現獨特音樂性格，並朝向國際舞台發展。\n\n🕒演出時間：114年4月13日(日) 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n【經典世界電影名曲主題音樂會】旨在以絲竹樂獨特的風格，重新詮釋多首經典電影名曲，將傳統音樂與現代電影音樂結合，跨越不同時代的經典作品，帶領聽眾進入電影情境中，喚起那一份深刻的回憶。\n\n此音樂會具有獨特特色，無論是在演奏樂器、樂曲選擇，或是演奏家的表現上，都做了最精心的安排；通過國樂的音色與表現，展現出電影音樂的多樣性與深度，讓更多觀眾欣賞到國樂的美麗，每一段充滿特色且極具吸引力的曲目，都由專業演奏家共同呈現，為聽眾帶來一場難忘的音樂饗宴，感受藝術的無限魅力與動人心弦的力量。\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-04-13 00:00:00', '2025-04-13 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50684', '[]') ON DUPLICATE KEY UPDATE `activity_name`='華藝文化學會【經典世界電影名曲主題音樂會】（免費觀賞）', `description`='💖演出團體介紹：\n\n華藝文化學會推行發揚藝術文化，積極參與各類演出，將團隊推向國內外藝術殿堂。團隊不拘泥於傳統音樂，開創具本土性及國際視野的音樂風格，致力於傳統與創新間的發展，透過多元演出形式呈現獨特音樂性格，並朝向國際舞台發展。\n\n🕒演出時間：114年4月13日(日) 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n【經典世界電影名曲主題音樂會】旨在以絲竹樂獨特的風格，重新詮釋多首經典電影名曲，將傳統音樂與現代電影音樂結合，跨越不同時代的經典作品，帶領聽眾進入電影情境中，喚起那一份深刻的回憶。\n\n此音樂會具有獨特特色，無論是在演奏樂器、樂曲選擇，或是演奏家的表現上，都做了最精心的安排；通過國樂的音色與表現，展現出電影音樂的多樣性與深度，讓更多觀眾欣賞到國樂的美麗，每一段充滿特色且極具吸引力的曲目，都由專業演奏家共同呈現，為聽眾帶來一場難忘的音樂饗宴，感受藝術的無限魅力與動人心弦的力量。\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-04-13 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50684', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d9920', 'Quatuor Parfumé【綠色之音《與自然的和諧共鳴》】（免費觀賞）', '💖演出團體介紹：\n\nQuatuor Parfumé 由三位長笛手與一位鋼琴家組成，融合深厚音樂造詣與細膩演奏風格。音樂從巴洛克到當代，創造出優雅、獨特的氛圍。長笛旋律如香氣流動，鋼琴則增添層次與深度，每場演出猶如感官之旅，帶來新穎的音樂體驗。\n\n🕒演出時間：114年5月4日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n2024 年，後疫情時代，我們逐漸習慣與病毒共處，但強震和強颱的襲來提醒我們，自然的力量依然不可忽視。然而，無論風雨如何變遷，自然的美麗與溫柔依舊存在，像夕陽、月圓、微風和細雨。\n\n在這場音樂會中，我們將通過長笛、短笛和電鋼琴，歌頌自然的偉大與力量。每首樂曲都選自自然元素，傳達人類與自然和諧共處的美好願景。\n\n演出曲目：\n1. Celtic Forest 塞爾特之森\n2. Aqua 水\n3. Fireflies 螢火蟲\n4. 花は咲く 花正在開\n5. Raising Oceans 海平面上升\n6. Earth 地球\n7. Color of the Wind 風中奇緣\n8. Claire de Lune 月光\n9. O Sole Mio 我的太陽\n10. Little 007 Star 小星星四重奏\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-05-04 00:00:00', '2025-05-04 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50690', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Quatuor Parfumé【綠色之音《與自然的和諧共鳴》】（免費觀賞）', `description`='💖演出團體介紹：\n\nQuatuor Parfumé 由三位長笛手與一位鋼琴家組成，融合深厚音樂造詣與細膩演奏風格。音樂從巴洛克到當代，創造出優雅、獨特的氛圍。長笛旋律如香氣流動，鋼琴則增添層次與深度，每場演出猶如感官之旅，帶來新穎的音樂體驗。\n\n🕒演出時間：114年5月4日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n2024 年，後疫情時代，我們逐漸習慣與病毒共處，但強震和強颱的襲來提醒我們，自然的力量依然不可忽視。然而，無論風雨如何變遷，自然的美麗與溫柔依舊存在，像夕陽、月圓、微風和細雨。\n\n在這場音樂會中，我們將通過長笛、短笛和電鋼琴，歌頌自然的偉大與力量。每首樂曲都選自自然元素，傳達人類與自然和諧共處的美好願景。\n\n演出曲目：\n1. Celtic Forest 塞爾特之森\n2. Aqua 水\n3. Fireflies 螢火蟲\n4. 花は咲く 花正在開\n5. Raising Oceans 海平面上升\n6. Earth 地球\n7. Color of the Wind 風中奇緣\n8. Claire de Lune 月光\n9. O Sole Mio 我的太陽\n10. Little 007 Star 小星星四重奏\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-05-04 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50690', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d9921', '台灣揚琴樂團【聽風的歲月-台灣校園民歌音樂會】（免費觀賞）', '💖演出團體介紹：\n\n台灣揚琴樂團於2002年成立，以發展揚琴樂藝術為宗旨，持續推動揚琴藝術與音樂創作，秉持熱情與務實的態度，每年穩定地創作、舉辦音樂會並於台灣各級學校演出，及出國交流演出，至今國內外演出超過500場，獲得廣大民眾及政府的肯定。\n\n🕒演出時間：114年5月17日(六) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n校園民歌是台灣在1970年代發展出的流行音樂風格。它的特質是歌詞通俗而真摯，曲調優美而樸質、節奏明朗而生動，結構簡短而自然，使人聽了有身歷其境的感覺歌謠具深刻思想內容，反映社會的光明面及純正價值觀。故此次《聽風的歲月-台灣校園民歌之夜》本團特邀請作曲家精挑1970-1990台灣流行的校園民歌經典演唱曲目，重新加以編曲，改以揚琴合奏及演唱形式呈現，展現出不同其他樂器演奏之風貌，並輔於導聆解說台灣校園民歌歷史或動人的小故事。\n演出曲目：\n1.今山古道(演奏)\n2.外婆的澎湖灣(演奏)\n3.捉泥鰍(演奏)\n4.妳那好冷的小手(演唱)\n5.那一盆火(演唱)\n6.拜訪春天(演奏)\n7.歸人沙城(演奏)\n8.橄欖樹(演唱)\n9.月琴(演唱)\n10.秋蟬(演唱)\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-05-17 00:00:00', '2025-05-17 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50691', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台灣揚琴樂團【聽風的歲月-台灣校園民歌音樂會】（免費觀賞）', `description`='💖演出團體介紹：\n\n台灣揚琴樂團於2002年成立，以發展揚琴樂藝術為宗旨，持續推動揚琴藝術與音樂創作，秉持熱情與務實的態度，每年穩定地創作、舉辦音樂會並於台灣各級學校演出，及出國交流演出，至今國內外演出超過500場，獲得廣大民眾及政府的肯定。\n\n🕒演出時間：114年5月17日(六) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n校園民歌是台灣在1970年代發展出的流行音樂風格。它的特質是歌詞通俗而真摯，曲調優美而樸質、節奏明朗而生動，結構簡短而自然，使人聽了有身歷其境的感覺歌謠具深刻思想內容，反映社會的光明面及純正價值觀。故此次《聽風的歲月-台灣校園民歌之夜》本團特邀請作曲家精挑1970-1990台灣流行的校園民歌經典演唱曲目，重新加以編曲，改以揚琴合奏及演唱形式呈現，展現出不同其他樂器演奏之風貌，並輔於導聆解說台灣校園民歌歷史或動人的小故事。\n演出曲目：\n1.今山古道(演奏)\n2.外婆的澎湖灣(演奏)\n3.捉泥鰍(演奏)\n4.妳那好冷的小手(演唱)\n5.那一盆火(演唱)\n6.拜訪春天(演奏)\n7.歸人沙城(演奏)\n8.橄欖樹(演唱)\n9.月琴(演唱)\n10.秋蟬(演唱)\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50691', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d9922', '潘神室內樂【穿梭流行與經典年代】（免費觀賞）', '💖演出團體介紹：\n\n潘神室內樂（Ensemble de Pan）成立於2014年，是個以長笛為主軸的團隊。潘神（Pan）的是希臘神話中的牧神，有著半人半羊的外貌，也是為吹笛子的高手，潘神室內樂希望藉由各種不同的演出形式與編制來推動長笛室內樂發展、以原創或改編的可能性，傳達更多美好的長笛音樂與大家分享。\n\n🕒演出時間：114年5月18日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n期望透過長笛重奏的形式改編，由潘神室內樂的潘宗賢、卓彥秀、張芝瑄、簡馥瞳四位專業級的長笛演奏家，精選古典、動漫、流行等曲目，由長笛的精彩詮釋，讓普羅大眾能進一步了解長笛音色及魅力。\n\n1. Holst：The Planets-Jupiter,the Briner of Jollity（霍爾斯特：木星-選自組曲《行星》）\n2. Edward Elgar：Pomp and Circumstance Marches（愛德華·艾爾加：威風廩廩進行曲）\n3. Edward Elgar：Salut d''Amour（愛德華·艾爾加：愛的禮讚）\n4. Johann Pachelbel： Canon（約翰·帕海貝爾：卡農）\n5. Astor Piazzolla : Libertango（阿斯托爾·皮亞佐拉：自由的探戈）\n6. 久石讓：：鄰家的龍貓\n7. 島津秀雄：仰望著看夜晚的星星\n8. 大野克夫/島津秀雄：名偵探柯南主題曲\n9. 野田洋次郎/三浦秀秋：前前前世\n10. 田中公平/島津秀雄： We are \n11. 佐藤英敏/高橋宏樹：殘酷天使的行動綱領\n12. Bach : Jesu, Joy of Man''s Desiring（巴哈：《耶穌，世人仰望的喜悅》）\n13. Mozart : The Marriage of Figaro（莫札特：費加洛的婚禮）\n14. J. Lauber : Vision de Corse for Flute Quartet, Op.54（約瑟夫・羅伯：《放眼科西嘉》給長笛四重奏，作品第54號）\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-05-18 00:00:00', '2025-05-18 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50692', '[]') ON DUPLICATE KEY UPDATE `activity_name`='潘神室內樂【穿梭流行與經典年代】（免費觀賞）', `description`='💖演出團體介紹：\n\n潘神室內樂（Ensemble de Pan）成立於2014年，是個以長笛為主軸的團隊。潘神（Pan）的是希臘神話中的牧神，有著半人半羊的外貌，也是為吹笛子的高手，潘神室內樂希望藉由各種不同的演出形式與編制來推動長笛室內樂發展、以原創或改編的可能性，傳達更多美好的長笛音樂與大家分享。\n\n🕒演出時間：114年5月18日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n期望透過長笛重奏的形式改編，由潘神室內樂的潘宗賢、卓彥秀、張芝瑄、簡馥瞳四位專業級的長笛演奏家，精選古典、動漫、流行等曲目，由長笛的精彩詮釋，讓普羅大眾能進一步了解長笛音色及魅力。\n\n1. Holst：The Planets-Jupiter,the Briner of Jollity（霍爾斯特：木星-選自組曲《行星》）\n2. Edward Elgar：Pomp and Circumstance Marches（愛德華·艾爾加：威風廩廩進行曲）\n3. Edward Elgar：Salut d''Amour（愛德華·艾爾加：愛的禮讚）\n4. Johann Pachelbel： Canon（約翰·帕海貝爾：卡農）\n5. Astor Piazzolla : Libertango（阿斯托爾·皮亞佐拉：自由的探戈）\n6. 久石讓：：鄰家的龍貓\n7. 島津秀雄：仰望著看夜晚的星星\n8. 大野克夫/島津秀雄：名偵探柯南主題曲\n9. 野田洋次郎/三浦秀秋：前前前世\n10. 田中公平/島津秀雄： We are \n11. 佐藤英敏/高橋宏樹：殘酷天使的行動綱領\n12. Bach : Jesu, Joy of Man''s Desiring（巴哈：《耶穌，世人仰望的喜悅》）\n13. Mozart : The Marriage of Figaro（莫札特：費加洛的婚禮）\n14. J. Lauber : Vision de Corse for Flute Quartet, Op.54（約瑟夫・羅伯：《放眼科西嘉》給長笛四重奏，作品第54號）\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-05-18 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50692', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d9924', '雷音劇坊【鮕鮐兄點姻緣】（免費觀賞）', '💖演出團體介紹：\n\n雷音劇坊為2024新北市傑出演藝團隊，創立於2020年，以推廣、傳承台灣布袋戲為宗旨。劇團作品主要以台灣在地故事為背景、台語創作為精神、融入台灣在地歌仔調音樂為主要特色。\n\n劇坊成員們透過表演不斷精進操偶與口白等演技，平時鑽研戲偶頭雕刻彩繪、衣飾、盔帽、道具……製作及戲曲演出，期許為臺灣布袋戲盡份心力。成員們更多次受邀重要演出與演講課程，致力於國中、小社團及寒暑假推廣活動。\n\n🕒演出時間：114年5月31日(六) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n鮕鮐兄因為老婆不會縫補而去阿鱔師家偷天蠶寶衣，卻誤偷成傳家大刀，隨後被武館追殺，所幸逃至鯽仔魚家中躲過一劫，而鮕鮐兄為報鯽仔魚的救命之恩，即將偷來的大刀贈於他，欠缺盤資上京赴考的鯽仔魚欣喜，便將大刀典當，不料遭武館發現此事，卻害得鯽仔魚受牢獄之災。\n\n故事中並無真正的壞人，而小人物的刻畫鮮明，最後鮕鮐兄與妻巧計，讓鯽仔魚得以平反，是一齣非常有趣且豐富的戲。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-05-31 00:00:00', '2025-05-31 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50694', '[]') ON DUPLICATE KEY UPDATE `activity_name`='雷音劇坊【鮕鮐兄點姻緣】（免費觀賞）', `description`='💖演出團體介紹：\n\n雷音劇坊為2024新北市傑出演藝團隊，創立於2020年，以推廣、傳承台灣布袋戲為宗旨。劇團作品主要以台灣在地故事為背景、台語創作為精神、融入台灣在地歌仔調音樂為主要特色。\n\n劇坊成員們透過表演不斷精進操偶與口白等演技，平時鑽研戲偶頭雕刻彩繪、衣飾、盔帽、道具……製作及戲曲演出，期許為臺灣布袋戲盡份心力。成員們更多次受邀重要演出與演講課程，致力於國中、小社團及寒暑假推廣活動。\n\n🕒演出時間：114年5月31日(六) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n鮕鮐兄因為老婆不會縫補而去阿鱔師家偷天蠶寶衣，卻誤偷成傳家大刀，隨後被武館追殺，所幸逃至鯽仔魚家中躲過一劫，而鮕鮐兄為報鯽仔魚的救命之恩，即將偷來的大刀贈於他，欠缺盤資上京赴考的鯽仔魚欣喜，便將大刀典當，不料遭武館發現此事，卻害得鯽仔魚受牢獄之災。\n\n故事中並無真正的壞人，而小人物的刻畫鮮明，最後鮕鮐兄與妻巧計，讓鯽仔魚得以平反，是一齣非常有趣且豐富的戲。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-05-31 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50694', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d9925', '景勝客家戲劇團【薛丁山與樊梨花】（免費觀賞）', '💖演出團體介紹：\n\n景勝客家戲劇團成立於民國104年，致力推動客家戲曲藝術，拓展年輕族群參與，增進對客家文化的理解與認同。劇團秉持傳承與創新理念，透過現代舞台展現傳統戲曲的當代價值，賦予客家戲新生命，開拓藝術新可能。\n\n🕒演出時間：114年6月1日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n薛丁山帶兵攻打寒江關，樊洪父子出戰兵敗而回，樊梨花下山得知父兄與唐軍交戰，助其父兄迎戰唐軍，陣前獨點薛丁山出戰，薛丁山妻妹先後出戰卻都非樊梨花的對手，薛丁山出兵與樊梨花交戰，梨花對丁山一見鍾情，設陷阱抓拿丁山並向其求親，而丁山為求保命，欺騙梨花，梨花故以三擒三放，最終使薛丁山折服於裙下。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-06-01 00:00:00', '2025-06-01 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50695', '[]') ON DUPLICATE KEY UPDATE `activity_name`='景勝客家戲劇團【薛丁山與樊梨花】（免費觀賞）', `description`='💖演出團體介紹：\n\n景勝客家戲劇團成立於民國104年，致力推動客家戲曲藝術，拓展年輕族群參與，增進對客家文化的理解與認同。劇團秉持傳承與創新理念，透過現代舞台展現傳統戲曲的當代價值，賦予客家戲新生命，開拓藝術新可能。\n\n🕒演出時間：114年6月1日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n薛丁山帶兵攻打寒江關，樊洪父子出戰兵敗而回，樊梨花下山得知父兄與唐軍交戰，助其父兄迎戰唐軍，陣前獨點薛丁山出戰，薛丁山妻妹先後出戰卻都非樊梨花的對手，薛丁山出兵與樊梨花交戰，梨花對丁山一見鍾情，設陷阱抓拿丁山並向其求親，而丁山為求保命，欺騙梨花，梨花故以三擒三放，最終使薛丁山折服於裙下。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-06-01 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50695', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d9927', '逸蘭軒掌中劇團【豬兒們の消防奇遇】（免費觀賞）', '💖演出團體介紹：\n\n本劇團成立於2018年，由團長鍾逸彥創立。團長自幼熱愛布袋戲，習藝多年，積累深厚的本土文化底蘊。劇團名「逸蘭軒掌中劇團」，寓意「逸蘭軒鳴，掌中乾靈」，展現對傳統藝術的敬意與追求。\n\n劇團以扎實功底承襲五洲園派特色，結合傳統技藝與創新表演，推廣布袋戲。透過演出與教學，推動文化傳承與發展。2024年獲選為苗栗傑出演藝團隊，進一步獲得肯定。\n\n🕒演出時間：114年6月8日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n在一個陽光燦爛的暑假，三隻小豬——豬大哥、豬二姊和豬小弟，興奮地籌備生日派對，期待與朋友共度歡樂時光。然而，家中老舊電器與雜亂電線暗藏危機，沒人察覺潛在的危險。\n\n正當派對熱鬧進行時，火怪先生悄然現身，引燃了豬大哥的草屋。大火伴隨濃煙蔓延，野狼的威脅更讓小豬們驚慌失措。就在危急時刻，勇敢的消防喵喵趕到，不僅撲滅火勢，還教導小豬們如何應對火災、預防危險。\n\n經歷這場驚險事件後，小豬們將派對轉變為安全教育活動，與朋友們分享寶貴的消防知識，讓歡樂與學習並行。透過這齣消防主題的親子布袋戲，讓觀眾在輕鬆愉快的氛圍中學習消防安全，寓教於樂，讓正確的安全觀念深植人心。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-06-08 00:00:00', '2025-06-08 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50697', '[]') ON DUPLICATE KEY UPDATE `activity_name`='逸蘭軒掌中劇團【豬兒們の消防奇遇】（免費觀賞）', `description`='💖演出團體介紹：\n\n本劇團成立於2018年，由團長鍾逸彥創立。團長自幼熱愛布袋戲，習藝多年，積累深厚的本土文化底蘊。劇團名「逸蘭軒掌中劇團」，寓意「逸蘭軒鳴，掌中乾靈」，展現對傳統藝術的敬意與追求。\n\n劇團以扎實功底承襲五洲園派特色，結合傳統技藝與創新表演，推廣布袋戲。透過演出與教學，推動文化傳承與發展。2024年獲選為苗栗傑出演藝團隊，進一步獲得肯定。\n\n🕒演出時間：114年6月8日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n在一個陽光燦爛的暑假，三隻小豬——豬大哥、豬二姊和豬小弟，興奮地籌備生日派對，期待與朋友共度歡樂時光。然而，家中老舊電器與雜亂電線暗藏危機，沒人察覺潛在的危險。\n\n正當派對熱鬧進行時，火怪先生悄然現身，引燃了豬大哥的草屋。大火伴隨濃煙蔓延，野狼的威脅更讓小豬們驚慌失措。就在危急時刻，勇敢的消防喵喵趕到，不僅撲滅火勢，還教導小豬們如何應對火災、預防危險。\n\n經歷這場驚險事件後，小豬們將派對轉變為安全教育活動，與朋友們分享寶貴的消防知識，讓歡樂與學習並行。透過這齣消防主題的親子布袋戲，讓觀眾在輕鬆愉快的氛圍中學習消防安全，寓教於樂，讓正確的安全觀念深植人心。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-06-08 00:00:00', `end_date`='2025-06-08 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50697', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d9928', '台北室內女聲合唱團2【芳華絕代-唱遊知音系列音樂會】（免費觀賞）', '💖演出團體介紹：\n\n2013年，隸屬於台北室內合唱團的「台北室內女聲合唱團2」成立(原名「台北室內婦女合唱團2」)，在指揮鄭有席老師帶領下，2017年獲得「第六屆新加坡國際華文合唱節」金獎總冠軍，並登上國家音樂廳演出，隔年首次於國家演奏廳舉行《芳華絕代》專場音樂會，並陸續踏上日本、義大利、新加坡等地舞台，展現來自台灣精緻女聲的獨特風格！\n\n🕒演出時間：114年6月14日(六) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n以歌築夢，凝聚台灣女聲放眼世界的開闊胸懷\n\n台北室內女聲合唱團2 將以不同語言及主題的合唱作品，展現自信歌聲，以及專注於合唱的熱忱。曲目安排從西方聖樂，到東方的民謠、台灣客語新編歌曲、原住民歌曲等，透過各種鮮明風格的呈現，凝聚台灣精緻女聲放眼世界的開闊胸懷。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-06-14 00:00:00', '2025-06-14 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50698', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台北室內女聲合唱團2【芳華絕代-唱遊知音系列音樂會】（免費觀賞）', `description`='💖演出團體介紹：\n\n2013年，隸屬於台北室內合唱團的「台北室內女聲合唱團2」成立(原名「台北室內婦女合唱團2」)，在指揮鄭有席老師帶領下，2017年獲得「第六屆新加坡國際華文合唱節」金獎總冠軍，並登上國家音樂廳演出，隔年首次於國家演奏廳舉行《芳華絕代》專場音樂會，並陸續踏上日本、義大利、新加坡等地舞台，展現來自台灣精緻女聲的獨特風格！\n\n🕒演出時間：114年6月14日(六) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n以歌築夢，凝聚台灣女聲放眼世界的開闊胸懷\n\n台北室內女聲合唱團2 將以不同語言及主題的合唱作品，展現自信歌聲，以及專注於合唱的熱忱。曲目安排從西方聖樂，到東方的民謠、台灣客語新編歌曲、原住民歌曲等，透過各種鮮明風格的呈現，凝聚台灣精緻女聲放眼世界的開闊胸懷。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-06-14 00:00:00', `end_date`='2025-06-14 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50698', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d992a', '山河樂集【友善海洋音樂故事-珊瑚滿天星】（免費觀賞）', '💖演出團體介紹：\n\n「山河樂集」成立於2011年，是由一群出身臺灣各地的專業音樂人組織的創作型樂團。致力創作屬於臺灣文化的現代鄉土音樂，並於各地演出與分享。強調以在地生活性的音樂文化為基礎，做出好聽、好記又好唱的獨特創意風格為主要旨趣。\n\n🕒演出時間：114年6月21日(六) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n在一個寧靜的夜晚，海龜小綠在沙灘上誕生了，他躲過了海鳥的攻擊，螃蟹的抓捕，費了一番功夫才爬進海裡。在海裡，小綠遇見了跟他搶食水母的龜嬸，沒想到龜嬸吃下肚的竟然是塑膠袋，小綠緊張的帶著龜嬸到處尋找可以幫忙醫治的魚醫生，也因此結識了其他的好朋友。他們一起度過各種危機，彼此幫助，最後終於在龜嬸的彩色珊瑚社區定居下來。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-06-21 00:00:00', '2025-06-21 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50700', '[]') ON DUPLICATE KEY UPDATE `activity_name`='山河樂集【友善海洋音樂故事-珊瑚滿天星】（免費觀賞）', `description`='💖演出團體介紹：\n\n「山河樂集」成立於2011年，是由一群出身臺灣各地的專業音樂人組織的創作型樂團。致力創作屬於臺灣文化的現代鄉土音樂，並於各地演出與分享。強調以在地生活性的音樂文化為基礎，做出好聽、好記又好唱的獨特創意風格為主要旨趣。\n\n🕒演出時間：114年6月21日(六) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n在一個寧靜的夜晚，海龜小綠在沙灘上誕生了，他躲過了海鳥的攻擊，螃蟹的抓捕，費了一番功夫才爬進海裡。在海裡，小綠遇見了跟他搶食水母的龜嬸，沒想到龜嬸吃下肚的竟然是塑膠袋，小綠緊張的帶著龜嬸到處尋找可以幫忙醫治的魚醫生，也因此結識了其他的好朋友。他們一起度過各種危機，彼此幫助，最後終於在龜嬸的彩色珊瑚社區定居下來。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-06-21 00:00:00', `end_date`='2025-06-21 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50700', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d992b', '建中子恩合唱團【發聲II-復原與重生】（免費觀賞）', '💖演出團體介紹：\n\n因子相遇、珍惜感恩。102年一群建中家長成立子恩合唱團，在指揮魯以諾老師帶領下，109年獲臺北國際合唱大賽樂齡組首獎，113年登上國家音樂廳演奏廳。子恩期許藉歌聲將對孩子的愛轉為傳愛傳遞到社會各個角落\n\n🕒演出時間：114年6月22日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n《發聲》之涵義，除了合唱本是一發出聲音的表演形式外，還有為了特定族群、議題發出聲音、引起關注之意。《發聲Ⅱ─復原與重生》立基於2024年7月第一場製作《發聲─那些在街頭的故事》的精神，將觸角延伸至其他弱勢族群，以更寫實的方式，將不同背景人們的生命經歷撰寫出來，多數都是沉重且發人深省的，同時強調生命的復原力（resilience），呈現挫折、破敗後重生的希望永在。2025年7月本製作將在國家演奏廳首演，演出前一月先在大孝門廣場搶先看，期盼能將合唱音樂內富含的人文價值帶給更多人認識。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-06-22 00:00:00', '2025-06-22 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50701', '[]') ON DUPLICATE KEY UPDATE `activity_name`='建中子恩合唱團【發聲II-復原與重生】（免費觀賞）', `description`='💖演出團體介紹：\n\n因子相遇、珍惜感恩。102年一群建中家長成立子恩合唱團，在指揮魯以諾老師帶領下，109年獲臺北國際合唱大賽樂齡組首獎，113年登上國家音樂廳演奏廳。子恩期許藉歌聲將對孩子的愛轉為傳愛傳遞到社會各個角落\n\n🕒演出時間：114年6月22日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n《發聲》之涵義，除了合唱本是一發出聲音的表演形式外，還有為了特定族群、議題發出聲音、引起關注之意。《發聲Ⅱ─復原與重生》立基於2024年7月第一場製作《發聲─那些在街頭的故事》的精神，將觸角延伸至其他弱勢族群，以更寫實的方式，將不同背景人們的生命經歷撰寫出來，多數都是沉重且發人深省的，同時強調生命的復原力（resilience），呈現挫折、破敗後重生的希望永在。2025年7月本製作將在國家演奏廳首演，演出前一月先在大孝門廣場搶先看，期盼能將合唱音樂內富含的人文價值帶給更多人認識。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-06-22 00:00:00', `end_date`='2025-06-22 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50701', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d9930', 'String via 室內樂團【宮崎駿的音樂世界】（免費觀賞）', '💖演出團體介紹：\n\nString via室內樂團是以兩支小提琴、一支中提琴、一支大提琴所組成的弦樂四重奏。我們從事婚禮或尾牙等活動已有四年之久，曾在全國音樂比賽大專組室內樂比賽當中獲得優勝，並積極參與大大小小的活動及展演。\n\n🕒演出時間：114年7月27日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n1.風之谷配樂精選\n2.天空之城配樂精選\n3.鄰家的龍貓配樂精選\n4.神隱少女配樂精選\n5.幽靈公主配樂精選\n6.魔女宅急便配樂精選\n7.霍爾的移動城堡配樂精選\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-07-27 00:00:00', '2025-07-27 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50706', '[]') ON DUPLICATE KEY UPDATE `activity_name`='String via 室內樂團【宮崎駿的音樂世界】（免費觀賞）', `description`='💖演出團體介紹：\n\nString via室內樂團是以兩支小提琴、一支中提琴、一支大提琴所組成的弦樂四重奏。我們從事婚禮或尾牙等活動已有四年之久，曾在全國音樂比賽大專組室內樂比賽當中獲得優勝，並積極參與大大小小的活動及展演。\n\n🕒演出時間：114年7月27日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n1.風之谷配樂精選\n2.天空之城配樂精選\n3.鄰家的龍貓配樂精選\n4.神隱少女配樂精選\n5.幽靈公主配樂精選\n6.魔女宅急便配樂精選\n7.霍爾的移動城堡配樂精選\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-07-27 00:00:00', `end_date`='2025-07-27 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50706', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d9931', '節慶長笛樂團【您一定喜愛的古典音樂小品】（免費觀賞）', '💖演出團體介紹：\n\n節慶長笛樂團由旅法音樂家林仁斌擔任團長與樂團指揮，周欣穎擔任音樂總監，每年舉辦音樂會與文化藝術交流並與各單位合作音樂會與特別主題演講，豐富多元之動規劃及編曲結合完整長笛家族樂器編制演奏，廣受各界好評。\n\n🕒演出時間：114年8月9日(六) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n《您一定喜愛的音樂小品》是節慶長笛樂團精心設計之導聆式音樂會，由知名導聆人林仁斌主持/介紹，每首樂曲演出前，介紹背景故事與特色，讓觀眾更深刻感受音樂魅力： 音樂會以巴哈的《G弦之歌》寧靜溫暖的氛圍展開，韓德爾《席巴女王進城》的華麗、莫札特《土耳其進行曲》的輕快以及舒伯特《軍隊進行曲》展現古典音樂之多樣美；浪漫與當代作品如薩提《吉諾佩蒂》的極簡美、比才《卡門組曲》與普契尼《杜蘭朵公主》戲劇張力與細膩，直觸人心 最後以韋伯《歌劇魅影》與爵士名作《Fly Me To The Moon》、探戈《Por Una Cabeza》為音樂會劃下浪漫熱情的句點。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-08-09 00:00:00', '2025-08-09 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50707', '[]') ON DUPLICATE KEY UPDATE `activity_name`='節慶長笛樂團【您一定喜愛的古典音樂小品】（免費觀賞）', `description`='💖演出團體介紹：\n\n節慶長笛樂團由旅法音樂家林仁斌擔任團長與樂團指揮，周欣穎擔任音樂總監，每年舉辦音樂會與文化藝術交流並與各單位合作音樂會與特別主題演講，豐富多元之動規劃及編曲結合完整長笛家族樂器編制演奏，廣受各界好評。\n\n🕒演出時間：114年8月9日(六) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n《您一定喜愛的音樂小品》是節慶長笛樂團精心設計之導聆式音樂會，由知名導聆人林仁斌主持/介紹，每首樂曲演出前，介紹背景故事與特色，讓觀眾更深刻感受音樂魅力： 音樂會以巴哈的《G弦之歌》寧靜溫暖的氛圍展開，韓德爾《席巴女王進城》的華麗、莫札特《土耳其進行曲》的輕快以及舒伯特《軍隊進行曲》展現古典音樂之多樣美；浪漫與當代作品如薩提《吉諾佩蒂》的極簡美、比才《卡門組曲》與普契尼《杜蘭朵公主》戲劇張力與細膩，直觸人心 最後以韋伯《歌劇魅影》與爵士名作《Fly Me To The Moon》、探戈《Por Una Cabeza》為音樂會劃下浪漫熱情的句點。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-08-09 00:00:00', `end_date`='2025-08-09 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50707', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e326b3240c403d9934', '李宛儒中東文化藝術團【為和平而舞—中東民俗舞蹈巡覽】（免費觀賞）', '💖演出團體介紹：\n\n李宛儒中東文化藝術團由畢業自耶路撒冷希伯來大學中東政治與文化碩士的李宛儒老師於2002年創辦，以舞蹈美化人心、美化人性、美化人生為出發點，積極介紹中東各國的民俗舞蹈與音樂，促進國人親近中東文化與藝術。\n\n🕒演出時間：114年9月14日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n國內提到中東的藝術文化，大抵想到肚皮舞(原名東方舞)，其實中東有22個阿拉伯國家外加3個非阿拉伯國家，每個國家不同地區都有其特殊的傳統音樂、歌舞和服裝，生動活潑、富含當地民情風俗。透過舞蹈的呈現，和觀眾分享中東不同地區的傳統舞蹈音樂之美，寓教育於娛樂。\n\n乘著音樂飛毯，暢遊中東，欣賞各國特殊的民族樂舞\n\n1.土耳其大鼓舞\n2.土耳其黑海舞\n3.土耳其吉普賽舞\n4.伊拉克吉普賽舞\n5.波斯灣哈里基舞\n6.沙烏地戰舞\n7.波斯鼓樂與舞蹈\n8.敘利亞德布卡舞\n9. 巴勒斯坦舞\n10.安達魯西亞穆娃霞哈舞\n11.埃及Melaya舞\n12.蘇伊士湯匙舞\n13.埃及Shabbi舞\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-09-14 00:00:00', '2025-09-14 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50710', '[]') ON DUPLICATE KEY UPDATE `activity_name`='李宛儒中東文化藝術團【為和平而舞—中東民俗舞蹈巡覽】（免費觀賞）', `description`='💖演出團體介紹：\n\n李宛儒中東文化藝術團由畢業自耶路撒冷希伯來大學中東政治與文化碩士的李宛儒老師於2002年創辦，以舞蹈美化人心、美化人性、美化人生為出發點，積極介紹中東各國的民俗舞蹈與音樂，促進國人親近中東文化與藝術。\n\n🕒演出時間：114年9月14日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n國內提到中東的藝術文化，大抵想到肚皮舞(原名東方舞)，其實中東有22個阿拉伯國家外加3個非阿拉伯國家，每個國家不同地區都有其特殊的傳統音樂、歌舞和服裝，生動活潑、富含當地民情風俗。透過舞蹈的呈現，和觀眾分享中東不同地區的傳統舞蹈音樂之美，寓教育於娛樂。\n\n乘著音樂飛毯，暢遊中東，欣賞各國特殊的民族樂舞\n\n1.土耳其大鼓舞\n2.土耳其黑海舞\n3.土耳其吉普賽舞\n4.伊拉克吉普賽舞\n5.波斯灣哈里基舞\n6.沙烏地戰舞\n7.波斯鼓樂與舞蹈\n8.敘利亞德布卡舞\n9. 巴勒斯坦舞\n10.安達魯西亞穆娃霞哈舞\n11.埃及Melaya舞\n12.蘇伊士湯匙舞\n13.埃及Shabbi舞\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-09-14 00:00:00', `end_date`='2025-09-14 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50710', `image_url`='