INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e326b3240c403d9935', '基隆快樂藝術團【古早ㄟ說唱，大家來聽 (part2)】（免費觀賞）', '💖演出團體介紹：\n\n基隆快樂藝術團登記成立於107年，成立目的係為保存台灣傳統說唱藝術，熱衷於唸歌文化保存及發揚。目前團務發展持續，結合優秀演出者尋找演出舞台，讓此項美麗的傳統說唱藝術呈現在觀眾面前。\n\n🕒演出時間：114年10月19日(日) 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n1.十二生肖歌：歌詞為有趣生肖描述及忠孝節義的故事(薛雄飛大廣弦唸唱、李育容月琴伴奏)\n2.周成過台灣：內容係清代台灣移民唐山過台灣的故事(李育容彈唱、曾素鑾大廣弦伴奏)\n3.胡蠅大戰蚊子歌：有趣的故事，原來昆蟲也會吵架，令人會心一笑(溫秀英彈唱、薛雄飛大廣弦伴奏、陳延嘉笛子)\n4.母子答：山伯苦戀英台，梁山伯的媽媽幽默風趣，智慧無極限(李育容彈唱、薛雄飛大廣弦拉唱)\n5.乞丐開藝旦：在古早古早的時候、藝旦與客人之間的恩怨情仇(鄭美彈唱、曾素鑾大廣弦伴奏、陳延嘉笛子)\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-10-19 00:00:00', '2025-10-19 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50711', '[]') ON DUPLICATE KEY UPDATE `activity_name`='基隆快樂藝術團【古早ㄟ說唱，大家來聽 (part2)】（免費觀賞）', `description`='💖演出團體介紹：\n\n基隆快樂藝術團登記成立於107年，成立目的係為保存台灣傳統說唱藝術，熱衷於唸歌文化保存及發揚。目前團務發展持續，結合優秀演出者尋找演出舞台，讓此項美麗的傳統說唱藝術呈現在觀眾面前。\n\n🕒演出時間：114年10月19日(日) 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n1.十二生肖歌：歌詞為有趣生肖描述及忠孝節義的故事(薛雄飛大廣弦唸唱、李育容月琴伴奏)\n2.周成過台灣：內容係清代台灣移民唐山過台灣的故事(李育容彈唱、曾素鑾大廣弦伴奏)\n3.胡蠅大戰蚊子歌：有趣的故事，原來昆蟲也會吵架，令人會心一笑(溫秀英彈唱、薛雄飛大廣弦伴奏、陳延嘉笛子)\n4.母子答：山伯苦戀英台，梁山伯的媽媽幽默風趣，智慧無極限(李育容彈唱、薛雄飛大廣弦拉唱)\n5.乞丐開藝旦：在古早古早的時候、藝旦與客人之間的恩怨情仇(鄭美彈唱、曾素鑾大廣弦伴奏、陳延嘉笛子)\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-10-19 00:00:00', `end_date`='2025-10-19 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50711', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf60226b3240c403d9938', '「懷素抱樸」中華插花藝術展 (2025/3/6-3/25)', '展覽簡述-\n\n本次展出主題以老子道德經–見素抱樸為引言，「懷素抱樸」意指回歸自然、保持著純樸與赤子之心和歸真的心靈，呈現花藝創作的靈魂。透過創作展現大自然的奧妙之美，讓生活中的我們放慢步調，欣賞當下寧靜與花對話，保有一顆簡單純粹的心，進而與自然界融合共生。\n\n展出內容有四大類型–寫景花、理念花、心象花及造型花區，作品出神入化、獨具匠心、妙趣橫生，創作中也包涵著現代、古典，文人式的相融契合，聚集眾多花藝老師的獨特創作思維，呈現情感表達與精湛的專藝，既具傳統傳承韻味，又賦予內心當代創意的想法，讓展覽有著多變而驚艷的人文感觀，讓人在靜靜欣賞之餘更能感受那份靜謐與和諧！\n\n展覽資訊-\n\n展覽名稱：「懷素抱樸」-中華插花藝術展\n\n時間: 2025/3/6(四)-3/25(二) 9:00~17:00(週一公休)\n\n第一梯次展:2025/3/6(四)-3/16(日)\n\n第二梯次展:2025/3/18(二)-3/25(二)\n\n地點: 國立新竹生活美學館 美學堂（300新竹市武昌街110號）\n\n ', '國立新竹生活美學館', '300  新竹市武昌街110號', '2025-03-06 00:00:00', '2025-03-25 00:00:00', '國立新竹生活美學館-美學堂', 24.8031317, 120.9671479, '0', 'https://event.culture.tw/mocweb/reg/NHCLAC/Detail.init.ctr?actId=50078', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「懷素抱樸」中華插花藝術展 (2025/3/6-3/25)', `description`='展覽簡述-\n\n本次展出主題以老子道德經–見素抱樸為引言，「懷素抱樸」意指回歸自然、保持著純樸與赤子之心和歸真的心靈，呈現花藝創作的靈魂。透過創作展現大自然的奧妙之美，讓生活中的我們放慢步調，欣賞當下寧靜與花對話，保有一顆簡單純粹的心，進而與自然界融合共生。\n\n展出內容有四大類型–寫景花、理念花、心象花及造型花區，作品出神入化、獨具匠心、妙趣橫生，創作中也包涵著現代、古典，文人式的相融契合，聚集眾多花藝老師的獨特創作思維，呈現情感表達與精湛的專藝，既具傳統傳承韻味，又賦予內心當代創意的想法，讓展覽有著多變而驚艷的人文感觀，讓人在靜靜欣賞之餘更能感受那份靜謐與和諧！\n\n展覽資訊-\n\n展覽名稱：「懷素抱樸」-中華插花藝術展\n\n時間: 2025/3/6(四)-3/25(二) 9:00~17:00(週一公休)\n\n第一梯次展:2025/3/6(四)-3/16(日)\n\n第二梯次展:2025/3/18(二)-3/25(二)\n\n地點: 國立新竹生活美學館 美學堂（300新竹市武昌街110號）\n\n ', `organizer`='國立新竹生活美學館', `address`='300  新竹市武昌街110號', `start_date`='2025-03-06 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='國立新竹生活美學館-美學堂', `latitude`=24.8031317, `longitude`=120.9671479, `ticket_price`='0', `source_url`='https://event.culture.tw/mocweb/reg/NHCLAC/Detail.init.ctr?actId=50078', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6a226b3240c403d9942', '《星光慶典》', '小小的星光，有大大的力量\r\n能點亮黑夜，指引方向，能照亮一座城市，還能寄託希望。\r\n別小看自己，期許未來也能成為一道星光，為別人帶來溫暖和希望！\r\n\r\n感謝生命中相遇的點點星光\r\n感謝每顆為我們燃燒自己照亮前方的星，祈禱永遠平安健康；\r\n感謝黑暗中溫暖擁抱的星光，願善良永遠相伴，生命充滿愛和希望。', '臺北市藝文推廣處', '臺北市文山區景文街32號', '2025-01-01 00:00:00', '2025-08-31 00:00:00', '臺北市藝文推廣處-文山劇場', 24.98857934, 121.5736082, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《星光慶典》', `description`='小小的星光，有大大的力量\r\n能點亮黑夜，指引方向，能照亮一座城市，還能寄託希望。\r\n別小看自己，期許未來也能成為一道星光，為別人帶來溫暖和希望！\r\n\r\n感謝生命中相遇的點點星光\r\n感謝每顆為我們燃燒自己照亮前方的星，祈禱永遠平安健康；\r\n感謝黑暗中溫暖擁抱的星光，願善良永遠相伴，生命充滿愛和希望。', `organizer`='臺北市藝文推廣處', `address`='臺北市文山區景文街32號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='臺北市藝文推廣處-文山劇場', `latitude`=24.98857934, `longitude`=121.5736082, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6ac26b3240c403d9943', '114-1期(113年1月-4月)創藝學園', '為提升兒童及少年藝文參與，培育其藝術涵養與美感素養，推廣藝術紮根，於週末規劃辦理兒少藝文推廣課程。\r\n以視覺藝術及表演藝術為核心，涵蓋文學、美術及科技應用等多元領域。\r\n本期新開班「兒童流行街舞」、「相聲藝起樂」及「複合媒材藝術創作」。', '國立中正紀念堂管理處', '臺北市中正區中山南路21號', '2025-01-04 00:00:00', '2025-05-11 00:00:00', '國立中正紀念堂管理處', 25.03240487, 121.5198839, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/QueryReg.init.ctr?dataVo.actKind=500', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114-1期(113年1月-4月)創藝學園', `description`='為提升兒童及少年藝文參與，培育其藝術涵養與美感素養，推廣藝術紮根，於週末規劃辦理兒少藝文推廣課程。\r\n以視覺藝術及表演藝術為核心，涵蓋文學、美術及科技應用等多元領域。\r\n本期新開班「兒童流行街舞」、「相聲藝起樂」及「複合媒材藝術創作」。', `organizer`='國立中正紀念堂管理處', `address`='臺北市中正區中山南路21號', `start_date`='2025-01-04 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='國立中正紀念堂管理處', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/QueryReg.init.ctr?dataVo.actKind=500', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6ac26b3240c403d9944', '114年藝學堂親子藝術課程(2-4月)', '《假日親子藝術課程》114年2-4月\r\n1.「春天的蒐集(2/9 上午10:00-11:00)」：藉由欣賞自然物的美，將他們的特徵拼貼成形，串掛在季節的微風與光影中。\r\n\r\n2.「與光同行(3/9 上午10:00-11:00)」：黏貼拼湊新綠的枝枒，枝枒間加入開心出遊的大小朋友，像是手牽手一起走在綠色隧道中享受自然，幸福地與光同行。\r\n\r\n3.「植物的纖維(3/23 上午10:00-12:00)」：紙張與衣服究竟是怎麼產生?一起認識植物纖維的奧秘，跟著老師製作手抄紙！\r\n\r\n4.「春神的花園(4/13 上午10:00-11:00)」：帶著大地的自然物，印壓出美麗的紋理，染上春神的色彩，圍著圈，讓美麗的春神花園包圍你。\r\n\r\n5.「植物的果實與種子(4/27 上午10:00-12:00)」：一起來認識各種植物的果實與種子，了解植物的生長過程，課程中將帶領大小朋友體驗栽種可愛的種子小盆栽喔!', '國立中正紀念堂管理處', '臺北市中正區中山南路21號', '2025-02-09 00:00:00', '2025-04-27 00:00:00', '國立中正紀念堂管理處', 25.03240487, 121.5198839, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/QueryReg.init.ctr?dataVo.actKind=002', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年藝學堂親子藝術課程(2-4月)', `description`='《假日親子藝術課程》114年2-4月\r\n1.「春天的蒐集(2/9 上午10:00-11:00)」：藉由欣賞自然物的美，將他們的特徵拼貼成形，串掛在季節的微風與光影中。\r\n\r\n2.「與光同行(3/9 上午10:00-11:00)」：黏貼拼湊新綠的枝枒，枝枒間加入開心出遊的大小朋友，像是手牽手一起走在綠色隧道中享受自然，幸福地與光同行。\r\n\r\n3.「植物的纖維(3/23 上午10:00-12:00)」：紙張與衣服究竟是怎麼產生?一起認識植物纖維的奧秘，跟著老師製作手抄紙！\r\n\r\n4.「春神的花園(4/13 上午10:00-11:00)」：帶著大地的自然物，印壓出美麗的紋理，染上春神的色彩，圍著圈，讓美麗的春神花園包圍你。\r\n\r\n5.「植物的果實與種子(4/27 上午10:00-12:00)」：一起來認識各種植物的果實與種子，了解植物的生長過程，課程中將帶領大小朋友體驗栽種可愛的種子小盆栽喔!', `organizer`='國立中正紀念堂管理處', `address`='臺北市中正區中山南路21號', `start_date`='2025-02-09 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='國立中正紀念堂管理處', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/QueryReg.init.ctr?dataVo.actKind=002', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6ac26b3240c403d9945', '114年藝學堂親子藝術課程(5-8月)', '《假日親子藝術課程》114年5-8月\r\n1.「星星的祝福-星星的花(5/4 上午10:00-11:00)」：花朵是地上的星星，許多落葉植物，吐露新芽、含苞待放，讓我們做一個小小的花圈，送給心愛的家人與朋友，也把星星的祝福一起送給他們。\r\n\r\n2.「四季之庭(6/8 上午10:00-11:00)」：邀請孩子們，來到自己的大地庭園，與植物們，一起好好呼吸，慢慢生活。\r\n\r\n3.「甲蟲王者-鍬形蟲與獨角仙(6/15上午10:00-11:00)」：認識甲蟲的生命小故事，如何區別臺灣鍬形蟲與獨角仙的幼蟲，並學習甲蟲飼養小知識。\r\n\r\n4.「緩緩行走-光之河(7/6 上午10:00-11:00)」：帶著大地的自然物，印壓出美麗的紋理，染上春神的色彩，圍著圈，讓美麗的春神花園包圍你。\r\n\r\n5.「永生花小樹球(8/3 上午10:00-12:00)」：認識基礎花藝知識，學習色彩搭配與構圖，打造層次豐富、和諧美觀的樹球，並掌握永生花保養技巧。', '國立中正紀念堂管理處', '臺北市中正區中山南路21號', '2025-05-04 00:00:00', '2025-08-03 00:00:00', '國立中正紀念堂管理處', 25.03240487, 121.5198839, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/QueryReg.init.ctr?dataVo.actKind=002', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年藝學堂親子藝術課程(5-8月)', `description`='《假日親子藝術課程》114年5-8月\r\n1.「星星的祝福-星星的花(5/4 上午10:00-11:00)」：花朵是地上的星星，許多落葉植物，吐露新芽、含苞待放，讓我們做一個小小的花圈，送給心愛的家人與朋友，也把星星的祝福一起送給他們。\r\n\r\n2.「四季之庭(6/8 上午10:00-11:00)」：邀請孩子們，來到自己的大地庭園，與植物們，一起好好呼吸，慢慢生活。\r\n\r\n3.「甲蟲王者-鍬形蟲與獨角仙(6/15上午10:00-11:00)」：認識甲蟲的生命小故事，如何區別臺灣鍬形蟲與獨角仙的幼蟲，並學習甲蟲飼養小知識。\r\n\r\n4.「緩緩行走-光之河(7/6 上午10:00-11:00)」：帶著大地的自然物，印壓出美麗的紋理，染上春神的色彩，圍著圈，讓美麗的春神花園包圍你。\r\n\r\n5.「永生花小樹球(8/3 上午10:00-12:00)」：認識基礎花藝知識，學習色彩搭配與構圖，打造層次豐富、和諧美觀的樹球，並掌握永生花保養技巧。', `organizer`='國立中正紀念堂管理處', `address`='臺北市中正區中山南路21號', `start_date`='2025-05-04 00:00:00', `end_date`='2025-08-03 00:00:00', `location`='國立中正紀念堂管理處', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/QueryReg.init.ctr?dataVo.actKind=002', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6ac26b3240c403d9946', '114年藝學堂親子藝術課程(9-12月)', '《假日親子藝術課程》114年9-12月\r\n1.「風裡的飛翔(9/7 上午10:00-11:00)」：當風吹向羽毛，就像賦予他們飛行的力量一般。從觀察羽毛開始，畫出一隻擁有美麗雙翼的雁鴉。\r\n\r\n2.「獼猴媽媽的愛(10/19 上午10:00-11:00)」：臺灣美麗的山林裡住著一群可愛的獼猴家族，小獼猴有著驚人的活力，就跟我們小時候一樣，必須在媽媽的擁抱裡慢慢成長茁壯，媽媽就是寶寶最溫暖的依靠。\r\n\r\n3.「內在的心星(11/2 上午10:00-11:00)」：一顆顆星子旋轉著完美的和諧，讓宇宙的初始充滿奧妙。我們生命的源頭，來自那遙遠的星辰，邀請您向宇宙領受，一份永恆的祝福。\r\n\r\n4.「賞蛙趣-是蟾蜍還是青蛙?(11/16 上午10:00-11:00)」：介紹各種蛙類的特徵和生命小故事，如何從鳴叫聲分辨出不同蛙類，認識蛙類生態及特殊育幼行為。\r\n\r\n5.「果好(12/7 上午10:00-11:00)」：大地果實，紫紫藍藍橘橘紅紅，這些渾圓成串的繽紛，是世界的禮物。他們帶著美滿的喜悅來到世界上，為大地帶來延續生命的力量。果實帶著安好平和的祝福，也會為我們帶來幸福。\r\n\r\n6.「松果聖誕樹(12/21 上午10:00-12:00)」：大認識基礎花藝知識，學習松果排列技巧與飾品的組合搭配，利用不同顏色與材質營造出豐富的層次感。', '國立中正紀念堂管理處', '臺北市中正區中山南路21號', '2025-09-07 00:00:00', '2025-12-21 00:00:00', '國立中正紀念堂管理處', 25.03240487, 121.5198839, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/QueryReg.init.ctr?dataVo.actKind=002', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年藝學堂親子藝術課程(9-12月)', `description`='《假日親子藝術課程》114年9-12月\r\n1.「風裡的飛翔(9/7 上午10:00-11:00)」：當風吹向羽毛，就像賦予他們飛行的力量一般。從觀察羽毛開始，畫出一隻擁有美麗雙翼的雁鴉。\r\n\r\n2.「獼猴媽媽的愛(10/19 上午10:00-11:00)」：臺灣美麗的山林裡住著一群可愛的獼猴家族，小獼猴有著驚人的活力，就跟我們小時候一樣，必須在媽媽的擁抱裡慢慢成長茁壯，媽媽就是寶寶最溫暖的依靠。\r\n\r\n3.「內在的心星(11/2 上午10:00-11:00)」：一顆顆星子旋轉著完美的和諧，讓宇宙的初始充滿奧妙。我們生命的源頭，來自那遙遠的星辰，邀請您向宇宙領受，一份永恆的祝福。\r\n\r\n4.「賞蛙趣-是蟾蜍還是青蛙?(11/16 上午10:00-11:00)」：介紹各種蛙類的特徵和生命小故事，如何從鳴叫聲分辨出不同蛙類，認識蛙類生態及特殊育幼行為。\r\n\r\n5.「果好(12/7 上午10:00-11:00)」：大地果實，紫紫藍藍橘橘紅紅，這些渾圓成串的繽紛，是世界的禮物。他們帶著美滿的喜悅來到世界上，為大地帶來延續生命的力量。果實帶著安好平和的祝福，也會為我們帶來幸福。\r\n\r\n6.「松果聖誕樹(12/21 上午10:00-12:00)」：大認識基礎花藝知識，學習松果排列技巧與飾品的組合搭配，利用不同顏色與材質營造出豐富的層次感。', `organizer`='國立中正紀念堂管理處', `address`='臺北市中正區中山南路21號', `start_date`='2025-09-07 00:00:00', `end_date`='2025-12-21 00:00:00', `location`='國立中正紀念堂管理處', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/QueryReg.init.ctr?dataVo.actKind=002', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6af26b3240c403d9947', '花藝裝置藝術-盛境迎春', '盧大衛創新霸王棕櫚葉迎春的裝置藝術於臺中市纖維工藝博物館帶來年節氛圍的詩意空間\r\n\r\n本次裝置藝術以大型紅色與黃色的霸王棕櫚葉為主視覺設計，象徵繁茂生機與祥和氣息。霸王棕櫚葉的挺拔姿態如同春日的新生，為空間注入強烈的視覺張力與文化厚度。葉片間點綴著圓形東方牡丹圖騰，牡丹作為富貴與祥瑞的象徵，將東方之美與節慶氛圍深度融合。\r\n\r\n紅色燈籠懸掛於空間各處，宛如夜空中的點點星火，穿梭於棕櫚葉與牡丹圖騰之間，營造出流動的年節氛圍。燈籠的圓潤造型散發著濃厚的喜慶氣息，為整體作品增添更多層次感與情感溫度。\r\n\r\n這件裝置藝術作品，不僅運用纖維材質並展現了傳統文化符號的現代美學詮釋，也在細節處傳遞出節慶的熱鬧氛圍與團圓喜悅。無論是俯視還是仰望，作品都能帶給觀者視覺與心靈的雙重震撼，邀請每位駐足的人共同感受如纖如詩交織的春節文化底蘊與生命的喜悅。', '無資料', '臺中市大里區勝利二路1號', '2025-01-13 00:00:00', '2025-02-28 00:00:00', '臺中市纖維工藝博物館', 24.09575742, 120.6926261, '無資料', 'https://mofia.taichung.gov.tw/Exhibit/122', '[]') ON DUPLICATE KEY UPDATE `activity_name`='花藝裝置藝術-盛境迎春', `description`='盧大衛創新霸王棕櫚葉迎春的裝置藝術於臺中市纖維工藝博物館帶來年節氛圍的詩意空間\r\n\r\n本次裝置藝術以大型紅色與黃色的霸王棕櫚葉為主視覺設計，象徵繁茂生機與祥和氣息。霸王棕櫚葉的挺拔姿態如同春日的新生，為空間注入強烈的視覺張力與文化厚度。葉片間點綴著圓形東方牡丹圖騰，牡丹作為富貴與祥瑞的象徵，將東方之美與節慶氛圍深度融合。\r\n\r\n紅色燈籠懸掛於空間各處，宛如夜空中的點點星火，穿梭於棕櫚葉與牡丹圖騰之間，營造出流動的年節氛圍。燈籠的圓潤造型散發著濃厚的喜慶氣息，為整體作品增添更多層次感與情感溫度。\r\n\r\n這件裝置藝術作品，不僅運用纖維材質並展現了傳統文化符號的現代美學詮釋，也在細節處傳遞出節慶的熱鬧氛圍與團圓喜悅。無論是俯視還是仰望，作品都能帶給觀者視覺與心靈的雙重震撼，邀請每位駐足的人共同感受如纖如詩交織的春節文化底蘊與生命的喜悅。', `organizer`='無資料', `address`='臺中市大里區勝利二路1號', `start_date`='2025-01-13 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市纖維工藝博物館', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://mofia.taichung.gov.tw/Exhibit/122', `image_url`='[]';
