INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6bb26b3240c403d994b', '藝文展覽-視覺饗宴~擬真黏土創作展', '視覺饗宴~歡迎來視吃\r\n這次邀請到Paggy老師為我們開啟新春第一展!\r\n黏土在老師巧手下化為一個個精緻又可口的小點心\r\n不論是中式或西式\r\n作品栩栩如生令人食指大動、難以抗拒\r\n讓人看在眼裡，甜在心裡~新的一年甜蜜又歡喜\r\n歡迎進館參觀\r\n展出者：Paggy老師\r\n展出時間：2/1(六)-2/27(四)\r\n展出地點：大肚分館一樓多元文化區', '臺中市立圖書館大肚分館', '臺中市大肚區大德六街 30 號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館大肚分館', 24.1558358, 120.5461103, '無資料', 'https://reurl.cc/XZgzoa', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝文展覽-視覺饗宴~擬真黏土創作展', `description`='視覺饗宴~歡迎來視吃\r\n這次邀請到Paggy老師為我們開啟新春第一展!\r\n黏土在老師巧手下化為一個個精緻又可口的小點心\r\n不論是中式或西式\r\n作品栩栩如生令人食指大動、難以抗拒\r\n讓人看在眼裡，甜在心裡~新的一年甜蜜又歡喜\r\n歡迎進館參觀\r\n展出者：Paggy老師\r\n展出時間：2/1(六)-2/27(四)\r\n展出地點：大肚分館一樓多元文化區', `organizer`='臺中市立圖書館大肚分館', `address`='臺中市大肚區大德六街 30 號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館大肚分館', `latitude`=24.1558358, `longitude`=120.5461103, `ticket_price`='無資料', `source_url`='https://reurl.cc/XZgzoa', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6bb26b3240c403d994c', '臺中市立圖書館大肚分館-2月份主題書展', '大肚分館2025年2月主題書展⋯⋯⋯♡\r\n1F-臺灣魂與筆\r\n這是一場屬於臺灣作家的文字盛宴\r\n用文字織就出的無數動人故事，都是這片土地最真實的聲音\r\n現在就讓我們一起參與這場書香宴席，品出最自然的臺灣味.ᐟ.ᐟ\r\n•┈┈┈┈┈┈୨୧┈┈┈┈┈┈•\r\n2F-奇幻冒險世界\r\n打開一扇通向夢幻世界的大門，重新找回童年的純真與幻想，\r\n來場從現實世界跳脫的奇妙之旅吧\r\n現在就讓我們在夢幻童話的天地裡邂逅想象，找到屬於自己的驚喜與感動\r\n•┈┈┈┈┈┈୨୧┈┈┈┈┈┈•\r\n3F-寵愛貓咪\r\n寵愛貓咪我來囉\r\n貓咪是人類的神奇寶貝.ᐟ.ᐟ而人類是貓咪的僕人.ᐟ.ᐟ\r\n寵物貓咪已成生活日常，喵、喵、喵………………..\r\n牠們的情緒、喜惡，你知曉嗎?想要更了解你的愛貓嗎?\r\n邀請您一起來探索愛貓與人類奇妙的牽絆\r\n讓我們一起「寵愛貓咪」，做個快樂的貓奴吧.ᐟ.ᐟ\r\n展出期間：2/1(六)~2/28(五)\r\n展出地點：各樓層主題書展區', '臺中市立圖書館大肚分館', '臺中市大肚區大德六街 30 號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺中市立圖書館大肚分館', 24.1558358, 120.5461103, '無資料', 'https://reurl.cc/46OKjL', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館大肚分館-2月份主題書展', `description`='大肚分館2025年2月主題書展⋯⋯⋯♡\r\n1F-臺灣魂與筆\r\n這是一場屬於臺灣作家的文字盛宴\r\n用文字織就出的無數動人故事，都是這片土地最真實的聲音\r\n現在就讓我們一起參與這場書香宴席，品出最自然的臺灣味.ᐟ.ᐟ\r\n•┈┈┈┈┈┈୨୧┈┈┈┈┈┈•\r\n2F-奇幻冒險世界\r\n打開一扇通向夢幻世界的大門，重新找回童年的純真與幻想，\r\n來場從現實世界跳脫的奇妙之旅吧\r\n現在就讓我們在夢幻童話的天地裡邂逅想象，找到屬於自己的驚喜與感動\r\n•┈┈┈┈┈┈୨୧┈┈┈┈┈┈•\r\n3F-寵愛貓咪\r\n寵愛貓咪我來囉\r\n貓咪是人類的神奇寶貝.ᐟ.ᐟ而人類是貓咪的僕人.ᐟ.ᐟ\r\n寵物貓咪已成生活日常，喵、喵、喵………………..\r\n牠們的情緒、喜惡，你知曉嗎?想要更了解你的愛貓嗎?\r\n邀請您一起來探索愛貓與人類奇妙的牽絆\r\n讓我們一起「寵愛貓咪」，做個快樂的貓奴吧.ᐟ.ᐟ\r\n展出期間：2/1(六)~2/28(五)\r\n展出地點：各樓層主題書展區', `organizer`='臺中市立圖書館大肚分館', `address`='臺中市大肚區大德六街 30 號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市立圖書館大肚分館', `latitude`=24.1558358, `longitude`=120.5461103, `ticket_price`='無資料', `source_url`='https://reurl.cc/46OKjL', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6bb26b3240c403d994d', '靜 穆 Silent Serenity', '靜穆是一種帶有深度安靜與莊嚴氛圍的狀態或感受，能引發人內心的平和與沉思。它不僅僅是單純的靜止或無聲，更包含一種精神層面的寧靜與肅穆感，通常與內在的探索、敬畏或禮讚相關。\r\n在展覽中藝術家傳遞出的平靜與神聖氣息。這種氛圍能讓觀者感到一種超越日常的平和，彷彿被引入一個內心沉思的空間，與自己的情感或更高層次的精神連結。\r\n靜穆既有莊嚴與神聖的層面，那種既安靜又充滿深度意涵的存在感。它不僅止於視覺上的感受，而是一種全身心的沉浸狀態，讓人能夠專注並感知生活中細微而深遠的美。', '養心藝術 Artnutri Gallery', '臺中市南屯區', '2025-02-08 00:00:00', '2025-03-16 00:00:00', '南屯區（臺中市）=', 24.14165524, 120.6177379, '無資料', 'https://www.facebook.com/share/p/15GXCeGoug/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='靜 穆 Silent Serenity', `description`='靜穆是一種帶有深度安靜與莊嚴氛圍的狀態或感受，能引發人內心的平和與沉思。它不僅僅是單純的靜止或無聲，更包含一種精神層面的寧靜與肅穆感，通常與內在的探索、敬畏或禮讚相關。\r\n在展覽中藝術家傳遞出的平靜與神聖氣息。這種氛圍能讓觀者感到一種超越日常的平和，彷彿被引入一個內心沉思的空間，與自己的情感或更高層次的精神連結。\r\n靜穆既有莊嚴與神聖的層面，那種既安靜又充滿深度意涵的存在感。它不僅止於視覺上的感受，而是一種全身心的沉浸狀態，讓人能夠專注並感知生活中細微而深遠的美。', `organizer`='養心藝術 Artnutri Gallery', `address`='臺中市南屯區', `start_date`='2025-02-08 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/15GXCeGoug/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6bf26b3240c403d994e', '「I DO MY BEST」PENPENJUNE SOLO EXHIBITION ', '「I DO MY BEST」，是一種每一次都全力以赴的狀態。\r\n\r\n這次展覽，與其說是關於完成什麼，不如說是關於不斷去做。\r\n\r\n創作對我來說是一種行動，在不同的創作練習中摸索、推翻、再來一次。這些作品，是過去兩年累積而成的痕跡，是「DO」的結果，也是「DO」本身。\r\n\r\n我希望觀者能在這些層層堆疊的筆觸與拼貼裡，看見未經修飾的、當下的、實驗性的美，以及在時間淬煉下——「我盡力做出最好」的過程。\r\n\r\n【藝術家簡介】 \r\n\r\nPENPENJUNE，自學繪畫近四年，專注於壓克力與混合媒材創作。風格強調色塊、線條與塗鴉，並結合網路文化與設計元素，用直覺的筆觸，傳達快樂、自由、不受拘束的創作狀態。\r\n\r\n我的創作旅程始於 Procreate 電繪，隨著探索深入，我開始自由實驗壓克力、粉彩、蠟筆與異材質拼貼，透過堆疊層次，尋找畫面中的韻律與張力。我喜歡在畫布上即興創作，不打草稿、也不預設主題，讓每一次落筆都是當下狀態與內心的對話。\r\n\r\n很榮幸受邀中國科大藝文中心展出。這是一場圍繞「DO」展開的展覽，我期待觀者能在其中看見藝術誕生的過程——從練習到變化，從實驗到突破。透過這些作品，呈現創作的即興性、探索的軌跡，以及那些充滿趣味的筆觸與拼貼，讓「做」藝術的過程具象化。\r\n', '中國科技大學藝文中心', '臺北市文山區', '2025-03-10 00:00:00', '2025-04-09 00:00:00', '文山區（臺北市）=', 24.98857934, 121.5736082, '無資料', 'https://art.gm.cute.edu.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「I DO MY BEST」PENPENJUNE SOLO EXHIBITION ', `description`='「I DO MY BEST」，是一種每一次都全力以赴的狀態。\r\n\r\n這次展覽，與其說是關於完成什麼，不如說是關於不斷去做。\r\n\r\n創作對我來說是一種行動，在不同的創作練習中摸索、推翻、再來一次。這些作品，是過去兩年累積而成的痕跡，是「DO」的結果，也是「DO」本身。\r\n\r\n我希望觀者能在這些層層堆疊的筆觸與拼貼裡，看見未經修飾的、當下的、實驗性的美，以及在時間淬煉下——「我盡力做出最好」的過程。\r\n\r\n【藝術家簡介】 \r\n\r\nPENPENJUNE，自學繪畫近四年，專注於壓克力與混合媒材創作。風格強調色塊、線條與塗鴉，並結合網路文化與設計元素，用直覺的筆觸，傳達快樂、自由、不受拘束的創作狀態。\r\n\r\n我的創作旅程始於 Procreate 電繪，隨著探索深入，我開始自由實驗壓克力、粉彩、蠟筆與異材質拼貼，透過堆疊層次，尋找畫面中的韻律與張力。我喜歡在畫布上即興創作，不打草稿、也不預設主題，讓每一次落筆都是當下狀態與內心的對話。\r\n\r\n很榮幸受邀中國科大藝文中心展出。這是一場圍繞「DO」展開的展覽，我期待觀者能在其中看見藝術誕生的過程——從練習到變化，從實驗到突破。透過這些作品，呈現創作的即興性、探索的軌跡，以及那些充滿趣味的筆觸與拼貼，讓「做」藝術的過程具象化。\r\n', `organizer`='中國科技大學藝文中心', `address`='臺北市文山區', `start_date`='2025-03-10 00:00:00', `end_date`='2025-04-09 00:00:00', `location`='文山區（臺北市）=', `latitude`=24.98857934, `longitude`=121.5736082, `ticket_price`='無資料', `source_url`='https://art.gm.cute.edu.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6bf26b3240c403d994f', '《永皴燒－邱永豐創作展》', '邱永豐創造出無數變化自在的荒寒山巒，山在手中行，目光在無盡連綿的線條中遊走。山川異域，枯寂而虛靜，歲荒寒機趣生。「永皴燒」是自然的永恆期許、泥線與火吻的印契！', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-02-27 00:00:00', '2025-04-06 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《永皴燒－邱永豐創作展》', `description`='邱永豐創造出無數變化自在的荒寒山巒，山在手中行，目光在無盡連綿的線條中遊走。山川異域，枯寂而虛靜，歲荒寒機趣生。「永皴燒」是自然的永恆期許、泥線與火吻的印契！', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-02-27 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6bf26b3240c403d9950', '《平衡」與「拼貼——熊妤個展》', '連結不同的物種，聚合一堂，我的任務就是用創意授粉，為現在與未來開闢虛實交錯的路徑。\r\n「拼貼與平衡」是寓意化實驗的精神，也是藝術創作技巧的體現。希望觀者享受物件之間的關連並樂在其中。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-02-22 00:00:00', '2025-03-06 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《平衡」與「拼貼——熊妤個展》', `description`='連結不同的物種，聚合一堂，我的任務就是用創意授粉，為現在與未來開闢虛實交錯的路徑。\r\n「拼貼與平衡」是寓意化實驗的精神，也是藝術創作技巧的體現。希望觀者享受物件之間的關連並樂在其中。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-06 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6bf26b3240c403d9951', '《荷花創作（瘋荷）》', '本來只是喜歡拍攝荷花\r\n後來發現毛毛蟲刻畫出精緻的圖騰\r\n以自然為師跟著毛毛蟲一起創作\r\n燈荷 、星芒之荷、滴水成荷、水彩之荷、墨荷\r\n為了拍一個特寫人與相機掉進荷池\r\n換了衣服與相機\r\n又繼續拍攝\r\n這些作品是一位瘋荷成痴的人拍的\r\n所以稱它為瘋荷', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-02-22 00:00:00', '2025-03-06 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《荷花創作（瘋荷）》', `description`='本來只是喜歡拍攝荷花\r\n後來發現毛毛蟲刻畫出精緻的圖騰\r\n以自然為師跟著毛毛蟲一起創作\r\n燈荷 、星芒之荷、滴水成荷、水彩之荷、墨荷\r\n為了拍一個特寫人與相機掉進荷池\r\n換了衣服與相機\r\n又繼續拍攝\r\n這些作品是一位瘋荷成痴的人拍的\r\n所以稱它為瘋荷', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-06 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6bf26b3240c403d9952', '《發現藝術~謝嘉明師生聯展》', '畫展是每位投入藝術繪畫者在創作道路上的一個深刻體驗，也是對自己藝術創作道路上審視自我在藝術學習成果中的重要里程碑。每件畫作所表現的內容都是學生們費盡心力最真摯誠懇的生活分享，畫中所記錄的點點滴滴展現出來的都是對藝術的熱情與執著。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-02-22 00:00:00', '2025-03-06 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《發現藝術~謝嘉明師生聯展》', `description`='畫展是每位投入藝術繪畫者在創作道路上的一個深刻體驗，也是對自己藝術創作道路上審視自我在藝術學習成果中的重要里程碑。每件畫作所表現的內容都是學生們費盡心力最真摯誠懇的生活分享，畫中所記錄的點點滴滴展現出來的都是對藝術的熱情與執著。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-06 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6c026b3240c403d9953', '知音時間《我們喜愛的歌》', '「好歌與知音分享，讓我們在愉悅的歌聲中，迎接每一個美好的明天！」是知音合唱團最大的心願。我們以悠揚動聽的歌聲，打動了許多知音的心弦，衷心歡迎，所有愛好老歌的朋友們一起努力，把詞曲優美的好歌繼續傳承下去，讓大家在難忘的老歌聲中，重溫舊日美好的時光。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-02-26 00:00:00', '2025-02-26 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='知音時間《我們喜愛的歌》', `description`='「好歌與知音分享，讓我們在愉悅的歌聲中，迎接每一個美好的明天！」是知音合唱團最大的心願。我們以悠揚動聽的歌聲，打動了許多知音的心弦，衷心歡迎，所有愛好老歌的朋友們一起努力，把詞曲優美的好歌繼續傳承下去，讓大家在難忘的老歌聲中，重溫舊日美好的時光。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-02-26 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6c026b3240c403d9954', '2月份繪本朗讀《屬於我的自信魔法》', '在你的魔法世界中，有哪些東西是屬於你的魔法呢？自信魔法？交朋友魔法？關心魔法？讓我們一起從自己出發成為亮亮魔法師，展現自己的專屬魔法吧！', '臺北市藝文推廣處', '臺北市文山區景文街32號', '2025-02-05 00:00:00', '2025-02-26 00:00:00', '臺北市藝文推廣處-文山劇場', 24.98857934, 121.5736082, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月份繪本朗讀《屬於我的自信魔法》', `description`='在你的魔法世界中，有哪些東西是屬於你的魔法呢？自信魔法？交朋友魔法？關心魔法？讓我們一起從自己出發成為亮亮魔法師，展現自己的專屬魔法吧！', `organizer`='臺北市藝文推廣處', `address`='臺北市文山區景文街32號', `start_date`='2025-02-05 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='臺北市藝文推廣處-文山劇場', `latitude`=24.98857934, `longitude`=121.5736082, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6c526b3240c403d9956', '展覽~看不見的生命：尼泊爾內戰衝突中失落與堅韌的故事/智邦藝術基金會  ', '這場展覽深入揭露一九九六至二〇〇六年間尼泊爾境內武裝衝突裡的心碎故事，許多受到內戰衝擊的家庭，同時展現出生命的韌性與希望。這個展覽所呈現的不只是攝影作品，更是獻給堅韌靈魂的一曲頌歌──他們雖經歷常人難以想像的痛苦掙扎，仍舊持續追尋真相與正義。', '財團法人智邦藝術基金會', '新竹市東區金城一路69號', '2025-02-26 00:00:00', '2025-03-23 00:00:00', '將軍村開放圖書資訊園區', 24.79028174, 120.9927505, '無資料', 'https://www.facebook.com/acctongallery/?ref=nf&hc_ref=ARTuOcaqjTpvVPiZb56VRC38xhHEeq4-aAmzu_fHZ4ZQGA', '[]') ON DUPLICATE KEY UPDATE `activity_name`='展覽~看不見的生命：尼泊爾內戰衝突中失落與堅韌的故事/智邦藝術基金會  ', `description`='這場展覽深入揭露一九九六至二〇〇六年間尼泊爾境內武裝衝突裡的心碎故事，許多受到內戰衝擊的家庭，同時展現出生命的韌性與希望。這個展覽所呈現的不只是攝影作品，更是獻給堅韌靈魂的一曲頌歌──他們雖經歷常人難以想像的痛苦掙扎，仍舊持續追尋真相與正義。', `organizer`='財團法人智邦藝術基金會', `address`='新竹市東區金城一路69號', `start_date`='2025-02-26 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='將軍村開放圖書資訊園區', `latitude`=24.79028174, `longitude`=120.9927505, `ticket_price`='無資料', `source_url`='https://www.facebook.com/acctongallery/?ref=nf&hc_ref=ARTuOcaqjTpvVPiZb56VRC38xhHEeq4-aAmzu_fHZ4ZQGA', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6c926b3240c403d9957', '異國繪本故事遊記《虎姑婆》/巨城購物中心', '聰明善良的小寶妹救了一隻小老鼠，但卻遇上了可怕凶狠的虎姑婆。她冷靜地和知恩圖報的小老鼠一起想出好辦法解救自己，懲罰虎姑婆。', 'Big City遠東巨城購物中心', '新竹市東區', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '東區（新竹市）=', 24.79028174, 120.9927505, '無資料', 'https://www.febigcity.com/bigcity/event/%E7%89%B9%E5%88%A5%E4%BC%81%E5%8A%83/3ca84db9-290e-4360-b8c4', '[]') ON DUPLICATE KEY UPDATE `activity_name`='異國繪本故事遊記《虎姑婆》/巨城購物中心', `description`='聰明善良的小寶妹救了一隻小老鼠，但卻遇上了可怕凶狠的虎姑婆。她冷靜地和知恩圖報的小老鼠一起想出好辦法解救自己，懲罰虎姑婆。', `organizer`='Big City遠東巨城購物中心', `address`='新竹市東區', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='東區（新竹市）=', `latitude`=24.79028174, `longitude`=120.9927505, `ticket_price`='無資料', `source_url`='https://www.febigcity.com/bigcity/event/%E7%89%B9%E5%88%A5%E4%BC%81%E5%8A%83/3ca84db9-290e-4360-b8c4', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6ca26b3240c403d9958', '異國繪本故事遊記《我是章魚燒，我叫章魚三郎》》/巨城購物中心', '老闆在製作三郎時忘了在他身體裡放上章魚，所以他一直覺得自己與別人不一樣，直到長老提醒三郎要有自信，世上總會有喜歡他的人。', 'Big City遠東巨城購物中心', '新竹市東區', '2025-02-28 00:00:00', '2025-03-28 00:00:00', '東區（新竹市）=', 24.79028174, 120.9927505, '無資料', 'https://www.febigcity.com/bigcity/event/%E7%89%B9%E5%88%A5%E4%BC%81%E5%8A%83/a13ed19b-5052-485d-8fe2', '[]') ON DUPLICATE KEY UPDATE `activity_name`='異國繪本故事遊記《我是章魚燒，我叫章魚三郎》》/巨城購物中心', `description`='老闆在製作三郎時忘了在他身體裡放上章魚，所以他一直覺得自己與別人不一樣，直到長老提醒三郎要有自信，世上總會有喜歡他的人。', `organizer`='Big City遠東巨城購物中心', `address`='新竹市東區', `start_date`='2025-02-28 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='東區（新竹市）=', `latitude`=24.79028174, `longitude`=120.9927505, `ticket_price`='無資料', `source_url`='https://www.febigcity.com/bigcity/event/%E7%89%B9%E5%88%A5%E4%BC%81%E5%8A%83/a13ed19b-5052-485d-8fe2', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6ca26b3240c403d9959', '114藝起推廣音樂文化研習課程', '由潘俊華老師指導，分享音樂藝術，帶領民眾唱國語流行音樂及台語流行音樂。', '桃園市桃園區公所', '桃園市桃園區', '2025-02-06 00:00:00', '2025-03-27 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114藝起推廣音樂文化研習課程', `description`='由潘俊華老師指導，分享音樂藝術，帶領民眾唱國語流行音樂及台語流行音樂。', `organizer`='桃園市桃園區公所', `address`='桃園市桃園區', `start_date`='2025-02-06 00:00:00', `end_date`='2025-03-27 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cb26b3240c403d995a', '《114年名家邀請及會員書畫聯展》', '本會立案登記於民國85年6月，迄今已近30年。會中不乏知名之書、畫老師及專家。\r\n此次聯展，係本會年度活動之一，包括各會員新創之書法、繪畫，約近百幅。另，邀約名家参與，俾共同切磋、學習、成長！', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-08 00:00:00', '2025-03-20 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《114年名家邀請及會員書畫聯展》', `description`='本會立案登記於民國85年6月，迄今已近30年。會中不乏知名之書、畫老師及專家。\r\n此次聯展，係本會年度活動之一，包括各會員新創之書法、繪畫，約近百幅。另，邀約名家参與，俾共同切磋、學習、成長！', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-20 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cb26b3240c403d995b', '《粉彩饗宴 --- 光影色交響曲》', '此次展出以粉彩畫為主，透過柔和的色彩、細膩的筆觸，呈現出美麗的光影變化，更以多層次的顏色堆疊，豐富畫作的視覺效果。每幅畫皆傳達著浪漫與幸福，散發出溫暖的力量，療癒人心。透過這次展覽，希望觀眾感受到粉彩的柔美與溫暖，並邀請大家一起來體驗這段獨特的藝術旅程！', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-08 00:00:00', '2025-03-20 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《粉彩饗宴 --- 光影色交響曲》', `description`='此次展出以粉彩畫為主，透過柔和的色彩、細膩的筆觸，呈現出美麗的光影變化，更以多層次的顏色堆疊，豐富畫作的視覺效果。每幅畫皆傳達著浪漫與幸福，散發出溫暖的力量，療癒人心。透過這次展覽，希望觀眾感受到粉彩的柔美與溫暖，並邀請大家一起來體驗這段獨特的藝術旅程！', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-20 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d995c', '《寓目游心—水墨山水畫展》', '水墨山水畫既承載了深厚的文化與哲學的意義，更展現創作者藝術哲思中企求回歸自然的生命追求。從傳統山水臨摹入手，堅持以具象或半具象的方式創作，表現水墨山水屬於東方的獨特風格。期能將寓於目中的山水景致賦予個人情志，使觀者感受到悠遠寧靜的水墨意境。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-08 00:00:00', '2025-03-20 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《寓目游心—水墨山水畫展》', `description`='水墨山水畫既承載了深厚的文化與哲學的意義，更展現創作者藝術哲思中企求回歸自然的生命追求。從傳統山水臨摹入手，堅持以具象或半具象的方式創作，表現水墨山水屬於東方的獨特風格。期能將寓於目中的山水景致賦予個人情志，使觀者感受到悠遠寧靜的水墨意境。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-20 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d995d', '《「對半切」——生命焦點的凝視》', '「對半切」 ——臺師大美術系水墨組7人畢業聯展\r\n本展藉由「切入」各自面對的生命經驗，從環境、家庭、個人的角度出發，並以繪畫、錄像、裝置等多種藝術形式，表達自身對於特定的主體,甚至是平時無所察覺的對象,所擁有的感受與詮釋。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-22 00:00:00', '2025-04-03 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《「對半切」——生命焦點的凝視》', `description`='「對半切」 ——臺師大美術系水墨組7人畢業聯展\r\n本展藉由「切入」各自面對的生命經驗，從環境、家庭、個人的角度出發，並以繪畫、錄像、裝置等多種藝術形式，表達自身對於特定的主體,甚至是平時無所察覺的對象,所擁有的感受與詮釋。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-04-03 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d995e', '《心領神繪 創作成果展》', '為展現社會大眾的創造力與力，本展覽由財團法人智冠科技文化藝術基金會所舉辦，\r\n分別展出由成人與兒童繪製的藝術繪畫作品，為期兩周的展覽，集結80件作品，展出不同 且多元的美感與創意作品，更期望藉由本次展覽，達到帶動全齡文化藝術蓬勃發展的目的。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-22 00:00:00', '2025-04-03 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《心領神繪 創作成果展》', `description`='為展現社會大眾的創造力與力，本展覽由財團法人智冠科技文化藝術基金會所舉辦，\r\n分別展出由成人與兒童繪製的藝術繪畫作品，為期兩周的展覽，集結80件作品，展出不同 且多元的美感與創意作品，更期望藉由本次展覽，達到帶動全齡文化藝術蓬勃發展的目的。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-04-03 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d995f', '周末輕鬆講— 藝享拾光《陶文、行山—邱永豐的陶藝特色》', '邱永豐的永皴燒，提供當代臺灣陶藝界一個重新思考「傳統與當代」、「工藝與藝術」界限的一個凸顯案例。蕭教授以他多年的觀察與研究，向聽眾講述他的專業見解，提升大眾的美學通識。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='周末輕鬆講— 藝享拾光《陶文、行山—邱永豐的陶藝特色》', `description`='邱永豐的永皴燒，提供當代臺灣陶藝界一個重新思考「傳統與當代」、「工藝與藝術」界限的一個凸顯案例。蕭教授以他多年的觀察與研究，向聽眾講述他的專業見解，提升大眾的美學通識。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d9960', '周末輕鬆講《我們是書的奴隸，還是夢想的戰士？》', '在打工的租書店師大白鹿洞即將關店時，解永華決心頂下店面，如今她不畏風雨每日守著租書店，並以創新多元的經營模式，開創「充滿個性的」新生師大白鹿洞。\r\n「這講題是不是充滿壯烈的情感和使命感，讓人熱血沸騰呀，在大家都在滑手機的年代，開租書店就是這麼的超現實喔。」', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='周末輕鬆講《我們是書的奴隸，還是夢想的戰士？》', `description`='在打工的租書店師大白鹿洞即將關店時，解永華決心頂下店面，如今她不畏風雨每日守著租書店，並以創新多元的經營模式，開創「充滿個性的」新生師大白鹿洞。\r\n「這講題是不是充滿壯烈的情感和使命感，讓人熱血沸騰呀，在大家都在滑手機的年代，開租書店就是這麼的超現實喔。」', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d9961', '周末輕鬆講《從零開始搞藝術》', '自從研究亨利．馬蒂斯的後期藝術，蔡霓臻就一頭栽進陌生的藝術領域，憑著對剪畫藝術的熱愛與膽試，開始籌備自己的第一個展覽，在展覽中與許多人交流，進而開始第一次的開課，直到現在累積許多學生與教育界的授課邀約，開拓自己的藝術品牌-蔡霓臻剪畫藝術。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='周末輕鬆講《從零開始搞藝術》', `description`='自從研究亨利．馬蒂斯的後期藝術，蔡霓臻就一頭栽進陌生的藝術領域，憑著對剪畫藝術的熱愛與膽試，開始籌備自己的第一個展覽，在展覽中與許多人交流，進而開始第一次的開課，直到現在累積許多學生與教育界的授課邀約，開拓自己的藝術品牌-蔡霓臻剪畫藝術。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d9962', '周末輕鬆講-藝享拾光《【陶瓷彩繪—西式面具】DIY活動》', '經由江羽葦老師講解後，現場提供白瓷素坯與彩繪用具，講師從旁協助並指導參與者繪製坯體，完成後參與者可帶回使用。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='周末輕鬆講-藝享拾光《【陶瓷彩繪—西式面具】DIY活動》', `description`='經由江羽葦老師講解後，現場提供白瓷素坯與彩繪用具，講師從旁協助並指導參與者繪製坯體，完成後參與者可帶回使用。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d9963', '音樂沙龍《時空漫旅-與浪漫三重奏的音樂對話》 ', '本場演出呈現跨越不同歷史時期和音樂風格的形式，帶領觀眾穿梭於各個時代的音樂世界。透過各個作曲家的寫作手法，相信不僅會給觀眾帶來豐富的音樂體驗，還會讓他們感受到音樂在時間長河中的傳承與創新。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='音樂沙龍《時空漫旅-與浪漫三重奏的音樂對話》 ', `description`='本場演出呈現跨越不同歷史時期和音樂風格的形式，帶領觀眾穿梭於各個時代的音樂世界。透過各個作曲家的寫作手法，相信不僅會給觀眾帶來豐富的音樂體驗，還會讓他們感受到音樂在時間長河中的傳承與創新。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d9964', '音樂沙龍《午後樂聚-經典旋律的時光漫遊》 ', '本次台北打擊樂團【午後樂聚--經典旋律的時光漫遊】精選多首非凡經典的作品，琅琅上口的世界名曲，以細膩的聲音精湛的演出，饒富富意重新詮釋作品，拉近與觀眾的距離，共同感受音樂的細膩與張力，更展現台北打擊樂團的經典聲音，也讓觀眾能夠更加認識打擊樂，進而推廣打擊樂藝術。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='音樂沙龍《午後樂聚-經典旋律的時光漫遊》 ', `description`='本次台北打擊樂團【午後樂聚--經典旋律的時光漫遊】精選多首非凡經典的作品，琅琅上口的世界名曲，以細膩的聲音精湛的演出，饒富富意重新詮釋作品，拉近與觀眾的距離，共同感受音樂的細膩與張力，更展現台北打擊樂團的經典聲音，也讓觀眾能夠更加認識打擊樂，進而推廣打擊樂藝術。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d9965', '音樂沙龍《戀人絮語：女高音與大提琴的溫柔對話》 ', '聲樂具有人聲特有的表現力，大提琴則被譽為最接近人聲的樂器。在本場音樂會中，女高音與大提琴的聲音如戀人般傾訴，時而深情款款，時而柔和婉轉。曲目涵蓋中文與外文、古典與近代，從莫扎特的典雅到佛瑞的浪漫，帶領觀眾進入情感豐富的音樂世界。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='音樂沙龍《戀人絮語：女高音與大提琴的溫柔對話》 ', `description`='聲樂具有人聲特有的表現力，大提琴則被譽為最接近人聲的樂器。在本場音樂會中，女高音與大提琴的聲音如戀人般傾訴，時而深情款款，時而柔和婉轉。曲目涵蓋中文與外文、古典與近代，從莫扎特的典雅到佛瑞的浪漫，帶領觀眾進入情感豐富的音樂世界。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d9966', '音樂沙龍《謎-大提琴四重奏》 ', '大提琴—最親近人聲的樂器—謎-大提琴四重奏由旅美大提琴家黃品潔與好友們，在教學之餘一起完成對室內樂演奏的熱愛；透過艾爾加謎之變奏曲的思念與回憶，我們想保有對音樂藝術最單純的敬愛與熱情。\r\n\r\n展演者︰黃品潔；黃祐甫；陳貫今；鄭伃庭\r\n\r\n', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='音樂沙龍《謎-大提琴四重奏》 ', `description`='大提琴—最親近人聲的樂器—謎-大提琴四重奏由旅美大提琴家黃品潔與好友們，在教學之餘一起完成對室內樂演奏的熱愛；透過艾爾加謎之變奏曲的思念與回憶，我們想保有對音樂藝術最單純的敬愛與熱情。\r\n\r\n展演者︰黃品潔；黃祐甫；陳貫今；鄭伃庭\r\n\r\n', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d9967', '藝術下午茶《永皴燒——發想與堅持》', '「永皴燒」是創作者在創作初期的發想過程中，受到日常削蘋果產生螺旋果皮的概念啟發，透過將之再還原的想法，形成自成一格的成形技法，明顯有別於普遍運用揉搓泥條盤築而成的方式。歷程中不斷的實驗、重組、改良，思索著突破的可能性，並透過重新認識與發現中國山水畫的符碼—皴，經過幾個年頭，終於發展出獨具特色的皴塑成形，並命名為「永皴燒」。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-05 00:00:00', '2025-03-05 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝術下午茶《永皴燒——發想與堅持》', `description`='「永皴燒」是創作者在創作初期的發想過程中，受到日常削蘋果產生螺旋果皮的概念啟發，透過將之再還原的想法，形成自成一格的成形技法，明顯有別於普遍運用揉搓泥條盤築而成的方式。歷程中不斷的實驗、重組、改良，思索著突破的可能性，並透過重新認識與發現中國山水畫的符碼—皴，經過幾個年頭，終於發展出獨具特色的皴塑成形，並命名為「永皴燒」。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d9968', '藝術下午茶《那些博物館不想說的黑歷史》', '說到博物館，你會想到什麼？藝術畫作？古董珍玩？還是標本？這些看起來相當嚴肅的展品，有的背後其實充滿著獵奇或難以啟齒的故事。像是：目前全世界館藏最多、最知名的「大英博物館」典藏的《女史箴圖》真得是英國軍官「剛好」撿到的嗎？歐洲博物館裡的木乃伊是買來、挖來、還是盜墓來的？近年西方博物館開始正視館藏的身世之謎，一起透過這些故事來開箱世界知名的博物館吧！', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-19 00:00:00', '2025-03-19 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝術下午茶《那些博物館不想說的黑歷史》', `description`='說到博物館，你會想到什麼？藝術畫作？古董珍玩？還是標本？這些看起來相當嚴肅的展品，有的背後其實充滿著獵奇或難以啟齒的故事。像是：目前全世界館藏最多、最知名的「大英博物館」典藏的《女史箴圖》真得是英國軍官「剛好」撿到的嗎？歐洲博物館裡的木乃伊是買來、挖來、還是盜墓來的？近年西方博物館開始正視館藏的身世之謎，一起透過這些故事來開箱世界知名的博物館吧！', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-19 00:00:00', `end_date`='2025-03-19 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d9969', '知音時間《聯合藝術合唱團》', '蘇麗文女士所指揮帶領的聯合藝術合唱團（2013年4月成立），以演唱經典正面且膾炙人口的歌曲為主。蘇麗文女士（留美歌唱家）除過去在國家演奏廳舉辦之獨唱音樂《藝術世界．歌唱人生》且帶領聯合藝術合唱團多以中小公益、服務性、社區性 如在台北市行政區活動中心 (大安、文山、民生等)，校園、養老院等訪演。', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-12 00:00:00', '2025-03-12 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='知音時間《聯合藝術合唱團》', `description`='蘇麗文女士所指揮帶領的聯合藝術合唱團（2013年4月成立），以演唱經典正面且膾炙人口的歌曲為主。蘇麗文女士（留美歌唱家）除過去在國家演奏廳舉辦之獨唱音樂《藝術世界．歌唱人生》且帶領聯合藝術合唱團多以中小公益、服務性、社區性 如在台北市行政區活動中心 (大安、文山、民生等)，校園、養老院等訪演。', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-03-12 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d996a', '知音時間《好歌大家唱》', '「重相逢合唱團」於民國86年成立，宗旨乃希望藉由好歌教唱，提供中、老年人週未假期正當休閒活動及精神寄託。\r\n26年來團員們發揮成立宗旨，希望將歡樂帶給周邊的朋友。在李德嫺團長的帶領下熱心參與公益活動，經常到各地慈善演出。 ', '臺北市藝文推廣處', '臺北市松山區八德路3段25號', '2025-03-26 00:00:00', '2025-03-26 00:00:00', '臺北市藝文推廣處藝文大樓(含城市舞台)', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='知音時間《好歌大家唱》', `description`='「重相逢合唱團」於民國86年成立，宗旨乃希望藉由好歌教唱，提供中、老年人週未假期正當休閒活動及精神寄託。\r\n26年來團員們發揮成立宗旨，希望將歡樂帶給周邊的朋友。在李德嫺團長的帶領下熱心參與公益活動，經常到各地慈善演出。 ', `organizer`='臺北市藝文推廣處', `address`='臺北市松山區八德路3段25號', `start_date`='2025-03-26 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺北市藝文推廣處藝文大樓(含城市舞台)', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d996b', '社巡-Fire Mosa：啟航', '為經典「FireMosa火爾摩莎傳奇」續集，公主與王子經過重重困難相遇並互許終生，在他們治理之下「火焰之島」逐漸繁榮。但是有這麼簡單嗎？島上的居民們不會叛變？而島外的勢力能夠不覬覦火焰的力量嗎？是否要向遠處尋找解方？又會面臨什麼樣的考驗呢？', '臺北市政府文化局', '臺北市北投區', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '北投區（臺北市）=', 25.1480682, 121.5177992, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='社巡-Fire Mosa：啟航', `description`='為經典「FireMosa火爾摩莎傳奇」續集，公主與王子經過重重困難相遇並互許終生，在他們治理之下「火焰之島」逐漸繁榮。但是有這麼簡單嗎？島上的居民們不會叛變？而島外的勢力能夠不覬覦火焰的力量嗎？是否要向遠處尋找解方？又會面臨什麼樣的考驗呢？', `organizer`='臺北市政府文化局', `address`='臺北市北投區', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='北投區（臺北市）=', `latitude`=25.1480682, `longitude`=121.5177992, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cc26b3240c403d996c', '社巡-《光陰的故事》台北青管社區音樂會', '老歌音樂會以「光陰的故事」為標題，演出曲目包含了二十世紀以來西洋、日本與臺灣各年代的懷舊金曲。配合主持人幽默風趣的曲目解說，並邀請聲樂家、流行歌手共同演出，與觀眾一同回味年輕時的雋永時光；也讓年輕人對經典的流行音樂有更多的認識和體驗。', '臺北市政府文化局', '臺北市信義區', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '信義區（臺北市）=', 25.03062083, 121.5716697, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='社巡-《光陰的故事》台北青管社區音樂會', `description`='老歌音樂會以「光陰的故事」為標題，演出曲目包含了二十世紀以來西洋、日本與臺灣各年代的懷舊金曲。配合主持人幽默風趣的曲目解說，並邀請聲樂家、流行歌手共同演出，與觀眾一同回味年輕時的雋永時光；也讓年輕人對經典的流行音樂有更多的認識和體驗。', `organizer`='臺北市政府文化局', `address`='臺北市信義區', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='信義區（臺北市）=', `latitude`=25.03062083, `longitude`=121.5716697, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cd26b3240c403d996d', '社巡-咱來搬演囡仔歌', '以童謠為經、故事為緯，賦予朗朗上口的童謠新面貌，藉著生動表演，傳承台灣共同的文化記憶。結合10首臺語童謠，由音樂統籌丁乙恆老師全新改編，邀請台北成功兒童合唱團、專業歌手重新配唱，加上演員生動表演，透過故事串聯起不同世代的回憶和情感，創作臺灣本土的音樂故事！', '臺北市政府文化局', '臺北市萬華區', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '萬華區（臺北市）=', 25.0285899, 121.4979858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='社巡-咱來搬演囡仔歌', `description`='以童謠為經、故事為緯，賦予朗朗上口的童謠新面貌，藉著生動表演，傳承台灣共同的文化記憶。結合10首臺語童謠，由音樂統籌丁乙恆老師全新改編，邀請台北成功兒童合唱團、專業歌手重新配唱，加上演員生動表演，透過故事串聯起不同世代的回憶和情感，創作臺灣本土的音樂故事！', `organizer`='臺北市政府文化局', `address`='臺北市萬華區', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='萬華區（臺北市）=', `latitude`=25.0285899, `longitude`=121.4979858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cd26b3240c403d996e', '社巡-《Sounds Good》秋•夜', 'Sounds good團員皆畢業於國內各大藝術學校音樂科系，以專業表演活耀於音樂舞台，並積極嘗試跨界形式演出，本次演出挑選經典老歌及流行歌曲，並改編傳統國樂曲目，將帶給觀眾一場愉悅的音樂饗宴。', '臺北市政府文化局', '臺北市內湖區', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '南港區（臺北市）=', 25.08370623, 121.5923828, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='社巡-《Sounds Good》秋•夜', `description`='Sounds good團員皆畢業於國內各大藝術學校音樂科系，以專業表演活耀於音樂舞台，並積極嘗試跨界形式演出，本次演出挑選經典老歌及流行歌曲，並改編傳統國樂曲目，將帶給觀眾一場愉悅的音樂饗宴。', `organizer`='臺北市政府文化局', `address`='臺北市內湖區', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='南港區（臺北市）=', `latitude`=25.08370623, `longitude`=121.5923828, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cd26b3240c403d996f', '3月份繪本朗讀《鬼鬼、妖怪、奇幻異世界》', '鬼就一定是邪惡的嗎?_妖怪就一定很恐怖嗎? 讓我們一起踏入奇幻的異世界，和鬼鬼當朋友、跟妖怪一起玩，還可能驚喜的被巫婆邀請參加party!!三月的繪本朗讀，我們一起探險魔幻的世界!', '臺北市藝文推廣處', '臺北市文山區景文街32號', '2025-03-05 00:00:00', '2025-03-26 00:00:00', '臺北市藝文推廣處-文山劇場', 24.98857934, 121.5736082, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月份繪本朗讀《鬼鬼、妖怪、奇幻異世界》', `description`='鬼就一定是邪惡的嗎?_妖怪就一定很恐怖嗎? 讓我們一起踏入奇幻的異世界，和鬼鬼當朋友、跟妖怪一起玩，還可能驚喜的被巫婆邀請參加party!!三月的繪本朗讀，我們一起探險魔幻的世界!', `organizer`='臺北市藝文推廣處', `address`='臺北市文山區景文街32號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺北市藝文推廣處-文山劇場', `latitude`=24.98857934, `longitude`=121.5736082, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cd26b3240c403d9970', '《小氣財神》', '改編英國作家狄更斯最經典的聖誕故事。富有卻吝嗇的史古基，沒有同情心也不喜歡幫助別人。在聖誕節前夕，他突然遇見三個精靈，帶著他穿越時空，看見過去、現在與未來，他會遇到哪些人？最後會不會改變自己的想法呢？', '臺北市藝文推廣處', '臺北市文山區景文街32號', '2025-03-28 00:00:00', '2025-03-30 00:00:00', '臺北市藝文推廣處-文山劇場', 24.98857934, 121.5736082, '/+200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《小氣財神》', `description`='改編英國作家狄更斯最經典的聖誕故事。富有卻吝嗇的史古基，沒有同情心也不喜歡幫助別人。在聖誕節前夕，他突然遇見三個精靈，帶著他穿越時空，看見過去、現在與未來，他會遇到哪些人？最後會不會改變自己的想法呢？', `organizer`='臺北市藝文推廣處', `address`='臺北市文山區景文街32號', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺北市藝文推廣處-文山劇場', `latitude`=24.98857934, `longitude`=121.5736082, `ticket_price`='/+200', `source_url`='https://www.opentix.life/', `image_url`='[]';
