INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cd26b3240c403d9972', '《若沒有你，我還會是關羽？！》', '東漢末年，關羽為救甘夫人暫投曹營，爾後千里走單騎，過五關斬六將，卻遭誤解，最終重拾兄弟信任。然而，在長年征戰下，青龍偃月刀與赤兔馬因關羽的忽略關心與保養，心生怨懟化為英靈欲訴心聲，導致最後關羽失刀喪命麥城，赤兔絕食而亡。百年後，關羽、偃月與赤兔在廟中重聚，訴說過往彼此誤解，決心再戰麥城，重拾榮光。', '臺北市藝文推廣處', '臺北市大同區迪化街1段21號', '2025-03-08 00:00:00', '2025-03-09 00:00:00', '臺北市藝文推廣處-大稻埕戲苑', 25.06342433, 121.5130417, '/+300;/+600;/+900;/+1200;/+1500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《若沒有你，我還會是關羽？！》', `description`='東漢末年，關羽為救甘夫人暫投曹營，爾後千里走單騎，過五關斬六將，卻遭誤解，最終重拾兄弟信任。然而，在長年征戰下，青龍偃月刀與赤兔馬因關羽的忽略關心與保養，心生怨懟化為英靈欲訴心聲，導致最後關羽失刀喪命麥城，赤兔絕食而亡。百年後，關羽、偃月與赤兔在廟中重聚，訴說過往彼此誤解，決心再戰麥城，重拾榮光。', `organizer`='臺北市藝文推廣處', `address`='臺北市大同區迪化街1段21號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='臺北市藝文推廣處-大稻埕戲苑', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='/+300;/+600;/+900;/+1200;/+1500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cd26b3240c403d9973', '《暗夜花香來》', '地痞王小鹿、好商千雲宗、錦衣衛指揮使齊天恆、夜族族長夜未央、歌姬李快樂、船醫，齊聚開往京城，獻出夜語花凝露給西廠廠督汪直的大明畫舫。 暗夜劇變，凝露失蹤，富商殞命。為了查兇手、找貢品，構陷他人以自保，揭露往事以自清，迷霧的往事甚過黑夜，幽暗的人性比江浪洶湧。真相為何？天亮前，命運是否會還人間一個公道？', '臺北市藝文推廣處', '臺北市大同區迪化街1段21號', '2025-03-15 00:00:00', '2025-03-16 00:00:00', '臺北市藝文推廣處-大稻埕戲苑', 25.06342433, 121.5130417, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《暗夜花香來》', `description`='地痞王小鹿、好商千雲宗、錦衣衛指揮使齊天恆、夜族族長夜未央、歌姬李快樂、船醫，齊聚開往京城，獻出夜語花凝露給西廠廠督汪直的大明畫舫。 暗夜劇變，凝露失蹤，富商殞命。為了查兇手、找貢品，構陷他人以自保，揭露往事以自清，迷霧的往事甚過黑夜，幽暗的人性比江浪洶湧。真相為何？天亮前，命運是否會還人間一個公道？', `organizer`='臺北市藝文推廣處', `address`='臺北市大同區迪化街1段21號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺北市藝文推廣處-大稻埕戲苑', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cd26b3240c403d9974', '《烏麻吐鬚》', '《烏麻吐鬚》改編自民間故事《蛇郎君》，是一齣融合童話、歌謠、古調的親情歌仔戲，由國寶名伶王金櫻擔任說故事耆老，她將娓娓道來一個古老傳說，帶領觀眾走進山野的原始小村落…村子裡的人們物質缺乏，卻都樂天無憂，直到有一天，蛇郎君的出現，讓平靜的村子風雲變色！蛇郎君打算帶走豬屎伯的一個女兒當新娘，如果不答應，他就放火燒了全村，小女兒雞卵面為了救父親只好答應嫁給蛇；離家那天豬屎伯遞給雞卵面一袋烏麻 (芝麻) 種子，讓她沿路撒，這樣等到秋天烏麻吐鬚長大了，才能沿著烏麻欉去探望她…', '臺北市藝文推廣處', '臺北市大同區迪化街1段21號', '2025-03-22 00:00:00', '2025-03-23 00:00:00', '臺北市藝文推廣處-大稻埕戲苑', 25.06342433, 121.5130417, '/+300;/+600;/+900;/+1200;/+1500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《烏麻吐鬚》', `description`='《烏麻吐鬚》改編自民間故事《蛇郎君》，是一齣融合童話、歌謠、古調的親情歌仔戲，由國寶名伶王金櫻擔任說故事耆老，她將娓娓道來一個古老傳說，帶領觀眾走進山野的原始小村落…村子裡的人們物質缺乏，卻都樂天無憂，直到有一天，蛇郎君的出現，讓平靜的村子風雲變色！蛇郎君打算帶走豬屎伯的一個女兒當新娘，如果不答應，他就放火燒了全村，小女兒雞卵面為了救父親只好答應嫁給蛇；離家那天豬屎伯遞給雞卵面一袋烏麻 (芝麻) 種子，讓她沿路撒，這樣等到秋天烏麻吐鬚長大了，才能沿著烏麻欉去探望她…', `organizer`='臺北市藝文推廣處', `address`='臺北市大同區迪化街1段21號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='臺北市藝文推廣處-大稻埕戲苑', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='/+300;/+600;/+900;/+1200;/+1500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cd26b3240c403d9975', '《吳門江湖》', '由《歌唱二村》、《一身是膽》、《巾幗八扇屏》、《洪羊洞》四段相聲組成，其中有ＰＫ、有典故、有野史、有女力、有諷刺，也有一人捅了多女馬蜂窩的傻膽直男……每段都或明或暗的含有「勇氣」或「江湖」主題。演出人員最大65歲，最小19歲，也代表著相聲傳承、生生不息。', '臺北市藝文推廣處', '臺北市大同區迪化街1段21號', '2025-03-29 00:00:00', '2025-03-30 00:00:00', '臺北市藝文推廣處-大稻埕戲苑', 25.06342433, 121.5130417, '/+300;/+600;/+900;/+1200;/+1500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《吳門江湖》', `description`='由《歌唱二村》、《一身是膽》、《巾幗八扇屏》、《洪羊洞》四段相聲組成，其中有ＰＫ、有典故、有野史、有女力、有諷刺，也有一人捅了多女馬蜂窩的傻膽直男……每段都或明或暗的含有「勇氣」或「江湖」主題。演出人員最大65歲，最小19歲，也代表著相聲傳承、生生不息。', `organizer`='臺北市藝文推廣處', `address`='臺北市大同區迪化街1段21號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺北市藝文推廣處-大稻埕戲苑', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='/+300;/+600;/+900;/+1200;/+1500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cd26b3240c403d9976', '《東方神鬼奇航之鄭和下西洋》', '由於元順帝私帶大明朝開國玉璽，逃往西洋方向，大明天子永樂君出旨令掌宮大使鄭和掛帥，率領千號戰船，百萬雄軍，追緝元順帝奪回大明開國玉璽，鄭和船隊順利經過暗洋與吃鐵嶺，明朝艦隊來到散髮國，被其軍師金毛道人阻擋，雙方展開一場道行上較勁、又鬥法、鬥寶的激烈鬥爭，使得鄭和奉旨下西洋追回傳國玉璽，又遭受一場驚心動魄的戰役', '臺北市藝文推廣處', '臺北市大同區迪化街1段21號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺北市藝文推廣處-大稻埕戲苑', 25.06342433, 121.5130417, '/+100', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《東方神鬼奇航之鄭和下西洋》', `description`='由於元順帝私帶大明朝開國玉璽，逃往西洋方向，大明天子永樂君出旨令掌宮大使鄭和掛帥，率領千號戰船，百萬雄軍，追緝元順帝奪回大明開國玉璽，鄭和船隊順利經過暗洋與吃鐵嶺，明朝艦隊來到散髮國，被其軍師金毛道人阻擋，雙方展開一場道行上較勁、又鬥法、鬥寶的激烈鬥爭，使得鄭和奉旨下西洋追回傳國玉璽，又遭受一場驚心動魄的戰役', `organizer`='臺北市藝文推廣處', `address`='臺北市大同區迪化街1段21號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺北市藝文推廣處-大稻埕戲苑', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='/+100', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cd26b3240c403d9977', '｢霓虹森林：轉瞬即逝的歲月拓片｣馬堤耶·馬哈切克個展', '安卓藝術很欣喜於今年三月推出藝術家馬堤耶‧馬哈切克的個展「霓虹森林：轉瞬即逝的歲月拓片」(Glowing Forests: Slices of Transient World)。這是馬哈切克至今最大規模的個展，也是他在安卓藝術的首次展出。展覽預計呈現這位捷克藝術家的30多幅新作，包含壓克力顏料與水墨等不同媒材的畫作。藝術家希望通過鮮明的色彩和大膽揮灑的筆觸來將其日常的見聞進行轉譯與深化。展期定於2025年3月8日至2025年4月11日之間，並於3月8日星期六下午3點30分舉辦開幕酒會，藝術家也將出席開幕活動。我們誠摯邀請您的蒞臨。\r\n\r\n馬哈切克為此次個展創作了一個全新的三聯幅作品：《火山牧場》、《石子小徑》與《瀑布》。這三張高度將近三米的畫作，充分體現藝術家所見所感之物及其在內心的呈現：山川與樹木皆有如紀念碑一般高大威嚴，彼此毗鄰而生，在廣袤的土地上不斷綿延。馬哈切克給這些自然風物添上近乎半透明的霓虹一般色彩，化日常所見為異世界的奇觀，將世界中的一個個切片賦予了自己的地景語彙。\r\n\r\n馬哈切克獨特的色彩運用於世界觀是兩種原因的奇妙組合：一方面他深諳當代社會的視覺元素，而同時他也為過去繪畫大師們的色彩深深吸引。藝術家對當下時代的運行速度頗有感知，當不斷發展的科技把生活中的一切都加速得令人頭暈目眩時，他有意識地遠離這些嘈雜，並嘗試保留生命中那些讓人靈魂昇華的時刻。瑪哈切克從梵谷與高更這樣的印象派大師的創作中獲取靈感，並嘗試將意外的邂逅在筆下轉化為非凡的瞬間。世間的平凡萬物，如風景、動物、遠方的地平線等皆在他恣意揮灑的筆觸下重現，化身成他理想世界中超越時空的歲月拓片。在那個萬花筒般的烏托邦裡，馬哈切克的藝術修為與他的記憶、思考和想像不斷碰撞出火花，最終融為一體成了更高的精神世界。\r\n\r\n對於馬哈切克來說，繪畫是對生活真諦的終極追尋，是為後世留下些許意義的途徑。他的偶像梵谷也在虛構的平行時空中回應了這種思緒。在電影「在永恆之門」中，梵谷在恍惚間頓悟了繪畫的意義，他脫口而出：\r\n\r\n「在繪畫之時，我的思緒停止了，仿佛我變成了外在與內在萬物的一部分……我曾經以為藝術家應當展示看待世界的方式，但我不再這麼想了。我現在只思考自己與永恆之間的關係。」\r\n', '安卓藝術', '臺北市內湖區', '2025-03-08 00:00:00', '2025-04-11 00:00:00', '內湖區（臺北市）=', 25.08370623, 121.5923828, '無資料', 'https://www.art-msac.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='｢霓虹森林：轉瞬即逝的歲月拓片｣馬堤耶·馬哈切克個展', `description`='安卓藝術很欣喜於今年三月推出藝術家馬堤耶‧馬哈切克的個展「霓虹森林：轉瞬即逝的歲月拓片」(Glowing Forests: Slices of Transient World)。這是馬哈切克至今最大規模的個展，也是他在安卓藝術的首次展出。展覽預計呈現這位捷克藝術家的30多幅新作，包含壓克力顏料與水墨等不同媒材的畫作。藝術家希望通過鮮明的色彩和大膽揮灑的筆觸來將其日常的見聞進行轉譯與深化。展期定於2025年3月8日至2025年4月11日之間，並於3月8日星期六下午3點30分舉辦開幕酒會，藝術家也將出席開幕活動。我們誠摯邀請您的蒞臨。\r\n\r\n馬哈切克為此次個展創作了一個全新的三聯幅作品：《火山牧場》、《石子小徑》與《瀑布》。這三張高度將近三米的畫作，充分體現藝術家所見所感之物及其在內心的呈現：山川與樹木皆有如紀念碑一般高大威嚴，彼此毗鄰而生，在廣袤的土地上不斷綿延。馬哈切克給這些自然風物添上近乎半透明的霓虹一般色彩，化日常所見為異世界的奇觀，將世界中的一個個切片賦予了自己的地景語彙。\r\n\r\n馬哈切克獨特的色彩運用於世界觀是兩種原因的奇妙組合：一方面他深諳當代社會的視覺元素，而同時他也為過去繪畫大師們的色彩深深吸引。藝術家對當下時代的運行速度頗有感知，當不斷發展的科技把生活中的一切都加速得令人頭暈目眩時，他有意識地遠離這些嘈雜，並嘗試保留生命中那些讓人靈魂昇華的時刻。瑪哈切克從梵谷與高更這樣的印象派大師的創作中獲取靈感，並嘗試將意外的邂逅在筆下轉化為非凡的瞬間。世間的平凡萬物，如風景、動物、遠方的地平線等皆在他恣意揮灑的筆觸下重現，化身成他理想世界中超越時空的歲月拓片。在那個萬花筒般的烏托邦裡，馬哈切克的藝術修為與他的記憶、思考和想像不斷碰撞出火花，最終融為一體成了更高的精神世界。\r\n\r\n對於馬哈切克來說，繪畫是對生活真諦的終極追尋，是為後世留下些許意義的途徑。他的偶像梵谷也在虛構的平行時空中回應了這種思緒。在電影「在永恆之門」中，梵谷在恍惚間頓悟了繪畫的意義，他脫口而出：\r\n\r\n「在繪畫之時，我的思緒停止了，仿佛我變成了外在與內在萬物的一部分……我曾經以為藝術家應當展示看待世界的方式，但我不再這麼想了。我現在只思考自己與永恆之間的關係。」\r\n', `organizer`='安卓藝術', `address`='臺北市內湖區', `start_date`='2025-03-08 00:00:00', `end_date`='2025-04-11 00:00:00', `location`='內湖區（臺北市）=', `latitude`=25.08370623, `longitude`=121.5923828, `ticket_price`='無資料', `source_url`='https://www.art-msac.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cd26b3240c403d9978', '「未來遺緒」 安德利亞．梅達爾', '安卓藝術很開心於Project Room展出代理藝術家安德利亞．梅達爾的裝置作品《未來遺緒》，作為藝術家同期於關渡美術館的個展「從你的窗櫺開始綻放以來」的引言，以利觀眾更多面向地閱讀梅達爾的藝術實踐。展覽將於3月8日至5月24日之間展開，並由CMC中環文化基金會贊助，我們誠摯歡迎您的蒞臨。\r\n《未來遺緒》（Leftovers from the Future）是｢日光室：永恆花園」計畫的第二章，探索羅馬尼亞拉柯伊村的園藝傳統與文化遺產。該村因人口外流瀕臨消失，而梅達爾透過「重演（reenactment）」，構築一座後末日未來的「精神花園」，在祖父花園的再造中連結家族記憶，尋找過去與當下的平衡。在｢日光室：永恆花園」的第一章中，梅達爾以手工縫製塑膠材料重構祖傳花園，而第二章裡，她則記錄下祖父離世一年後的花園景況。儘管家族不再從事園藝，但荒蕪的園地裡仍舊持續地生長出蔬菜，彷彿象徵著傳統的韌性與延續。\r\n作品靈感來自村內最古老的1726年建築，並呈現祖屋的感性場景——這棟曾是學校的歷史建築，隨祖母埃琳娜離世後無人居住。本作透過手工縫製塑膠技術串聯不同時期的片段，象徵性地保存失落的傳統——如手工播種。而梅達爾使用塑膠材料創作，亦呼應當地村民以透明塑膠桌布覆蓋祖輩手工縫製的布料，隱喻著對於傳統的最後一絲保護與記憶。\r\n', '安卓藝術', '臺北市內湖區', '2025-03-08 00:00:00', '2025-05-24 00:00:00', '內湖區（臺北市）=', 25.08370623, 121.5923828, '無資料', 'https://www.art-msac.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「未來遺緒」 安德利亞．梅達爾', `description`='安卓藝術很開心於Project Room展出代理藝術家安德利亞．梅達爾的裝置作品《未來遺緒》，作為藝術家同期於關渡美術館的個展「從你的窗櫺開始綻放以來」的引言，以利觀眾更多面向地閱讀梅達爾的藝術實踐。展覽將於3月8日至5月24日之間展開，並由CMC中環文化基金會贊助，我們誠摯歡迎您的蒞臨。\r\n《未來遺緒》（Leftovers from the Future）是｢日光室：永恆花園」計畫的第二章，探索羅馬尼亞拉柯伊村的園藝傳統與文化遺產。該村因人口外流瀕臨消失，而梅達爾透過「重演（reenactment）」，構築一座後末日未來的「精神花園」，在祖父花園的再造中連結家族記憶，尋找過去與當下的平衡。在｢日光室：永恆花園」的第一章中，梅達爾以手工縫製塑膠材料重構祖傳花園，而第二章裡，她則記錄下祖父離世一年後的花園景況。儘管家族不再從事園藝，但荒蕪的園地裡仍舊持續地生長出蔬菜，彷彿象徵著傳統的韌性與延續。\r\n作品靈感來自村內最古老的1726年建築，並呈現祖屋的感性場景——這棟曾是學校的歷史建築，隨祖母埃琳娜離世後無人居住。本作透過手工縫製塑膠技術串聯不同時期的片段，象徵性地保存失落的傳統——如手工播種。而梅達爾使用塑膠材料創作，亦呼應當地村民以透明塑膠桌布覆蓋祖輩手工縫製的布料，隱喻著對於傳統的最後一絲保護與記憶。\r\n', `organizer`='安卓藝術', `address`='臺北市內湖區', `start_date`='2025-03-08 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='內湖區（臺北市）=', `latitude`=25.08370623, `longitude`=121.5923828, `ticket_price`='無資料', `source_url`='https://www.art-msac.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6ce26b3240c403d9979', '【2025台文系列講座】做夥來寫字──Lâi siá-jī台語文學書寫創作工作坊(入門課)', '高雄文學館自2020年開始與在地台語推廣社團「打狗台語文促進協會」合作，結合在地台語社團活力，帶動高雄在地台語文學之推廣以及母語學習。\r\n\r\n【做夥來寫字──Lâi siá-jī台語文學書寫創作工作坊】\r\n帶領有興趣從事台語文書寫的朋友，實際投入台語文創作。透過線下實體寫作工作坊形式，每二週進行一次課程，並開設入門、散文、小說不同程度之主題，民眾可依自身台語能力程度及興趣報名參與，由講師帶領、引導學員練習以台語寫作。\r\n\r\n※入門課程（共四堂）※\r\n時間｜5/10、5/24、6/7、6/21，14:00-16:00\r\n講師｜打狗台語文促進協會\r\n地點｜高雄文學館二樓文學討論室', '高雄市立圖書館高雄文學館', '高雄市前金區24鄰民生二路39號', '2025-05-10 00:00:00', '2025-06-21 00:00:00', '高雄市立圖書館高雄文學館', 22.625524, 120.298017, '無資料', 'https://www.facebook.com/ksliterary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025台文系列講座】做夥來寫字──Lâi siá-jī台語文學書寫創作工作坊(入門課)', `description`='高雄文學館自2020年開始與在地台語推廣社團「打狗台語文促進協會」合作，結合在地台語社團活力，帶動高雄在地台語文學之推廣以及母語學習。\r\n\r\n【做夥來寫字──Lâi siá-jī台語文學書寫創作工作坊】\r\n帶領有興趣從事台語文書寫的朋友，實際投入台語文創作。透過線下實體寫作工作坊形式，每二週進行一次課程，並開設入門、散文、小說不同程度之主題，民眾可依自身台語能力程度及興趣報名參與，由講師帶領、引導學員練習以台語寫作。\r\n\r\n※入門課程（共四堂）※\r\n時間｜5/10、5/24、6/7、6/21，14:00-16:00\r\n講師｜打狗台語文促進協會\r\n地點｜高雄文學館二樓文學討論室', `organizer`='高雄市立圖書館高雄文學館', `address`='高雄市前金區24鄰民生二路39號', `start_date`='2025-05-10 00:00:00', `end_date`='2025-06-21 00:00:00', `location`='高雄市立圖書館高雄文學館', `latitude`=22.625524, `longitude`=120.298017, `ticket_price`='無資料', `source_url`='https://www.facebook.com/ksliterary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6ce26b3240c403d997a', '玉龍山游虺-塵三個展 ', '蛇年新氣象，乙巳年穎川畫廊隆重推出藝術家塵三個展「玉龍山游虺」。\r\n此次展覽以雲南玉龍山為靈感泉源，從雪山的壯闊景致激發出心靈的迴響。玉龍山頂終年白雪靄靄，山腰雲騰霧繞，遠望如一條矯健的玉龍，從碧空婉蜒而來的壯麗意象，與蛇年象徵彼此呼應。\r\n塵三即興揮灑的筆觸如情感的自然流瀉，將繽紛亮麗的色彩化作情感的昇華，捕捉眼前不可思議的美景，每一筆都是對眼前山水的讚美與歌詠。此次展出的水墨作品〈洱海〉、〈靈山路〉、〈宿家歡〉、〈桃花弄〉等作品，輕逸出塵的色彩如仙子下凡點亮人間，又不失對生命的期許與讚嘆 ，帶點歡樂愉悅的氣息。油畫作品〈刑山〉、〈輞川〉、〈洱海玄境〉、〈雪地〉、如生命的謳歌，又有著對眼前虛幻美景的神往。塵三之水墨作品遠看恬淡怡人，風光旑旎如入桃花源尋幽；油畫作品色彩紛呈，靜中有動、動中有「境」，此境不單指「意境 」之妙，更有超越時空的個人絕對意志之表徵。\r\n雄鷹盤旋於蒼穹，振翅九霄翱翔千里，颯爽英姿宛若王者叱吒雲霓。塵三用快意瀟灑的筆觸，書寫著生命的激情與理想的探求，凌雲之志不因年紀而自縛。其超越形式的自由與豁達，提醒人在逆境中用昂揚的鬥志衝破難關，方能借力順風翱翔，智慧之泉源源不絕湧現。也期許觀者能從作品中找到心靈的共鳴與屬於自己的桃花源。\r\n', '穎川畫廊 In River Gallery', '臺北市中正區', '2025-03-08 00:00:00', '2025-04-25 00:00:00', '中正區（臺北市）=', 25.03240487, 121.5198839, '無資料', 'https://www.facebook.com/InRiverGallery', '[]') ON DUPLICATE KEY UPDATE `activity_name`='玉龍山游虺-塵三個展 ', `description`='蛇年新氣象，乙巳年穎川畫廊隆重推出藝術家塵三個展「玉龍山游虺」。\r\n此次展覽以雲南玉龍山為靈感泉源，從雪山的壯闊景致激發出心靈的迴響。玉龍山頂終年白雪靄靄，山腰雲騰霧繞，遠望如一條矯健的玉龍，從碧空婉蜒而來的壯麗意象，與蛇年象徵彼此呼應。\r\n塵三即興揮灑的筆觸如情感的自然流瀉，將繽紛亮麗的色彩化作情感的昇華，捕捉眼前不可思議的美景，每一筆都是對眼前山水的讚美與歌詠。此次展出的水墨作品〈洱海〉、〈靈山路〉、〈宿家歡〉、〈桃花弄〉等作品，輕逸出塵的色彩如仙子下凡點亮人間，又不失對生命的期許與讚嘆 ，帶點歡樂愉悅的氣息。油畫作品〈刑山〉、〈輞川〉、〈洱海玄境〉、〈雪地〉、如生命的謳歌，又有著對眼前虛幻美景的神往。塵三之水墨作品遠看恬淡怡人，風光旑旎如入桃花源尋幽；油畫作品色彩紛呈，靜中有動、動中有「境」，此境不單指「意境 」之妙，更有超越時空的個人絕對意志之表徵。\r\n雄鷹盤旋於蒼穹，振翅九霄翱翔千里，颯爽英姿宛若王者叱吒雲霓。塵三用快意瀟灑的筆觸，書寫著生命的激情與理想的探求，凌雲之志不因年紀而自縛。其超越形式的自由與豁達，提醒人在逆境中用昂揚的鬥志衝破難關，方能借力順風翱翔，智慧之泉源源不絕湧現。也期許觀者能從作品中找到心靈的共鳴與屬於自己的桃花源。\r\n', `organizer`='穎川畫廊 In River Gallery', `address`='臺北市中正區', `start_date`='2025-03-08 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='中正區（臺北市）=', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://www.facebook.com/InRiverGallery', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cf26b3240c403d997b', '17th新人新視野', '——虛實真假之間的挑戰——\r\n魔術、小丑與民間信仰的極限碰撞，重塑表演的想像！\r\n虛實之間，創意交鋒；真假遊走，挑戰視野；打破界限，玩出全新表演語言！\r\n\r\n——17th新人及作品——\r\n林陸傑 Lin Lu-Chieh《錯誤（的）引導》Misdirected\r\n世界就是一場魔術，裡頭藏著無限秘密。\r\n\r\n郭鎧瑞 Guo Kai-Ruei《一炷香的時間》An Incense Stick of Time\r\n在迷失的愛戀與靈性中掙扎，最終尋找自我與真實情感。\r\n\r\n劉唐成 Liu Tang-Cheng《小丑與他的創造者》Clown and His Creator\r\n小丑對扮演自己失去熱忱的演員發出的調解通知書。', '財團法人國家文化藝術基金會', '臺北市中正區中山南路21之1號', '2025-05-09 00:00:00', '2025-05-11 00:00:00', '國家兩廳院', 25.03240487, 121.5198839, '/+1000', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='17th新人新視野', `description`='——虛實真假之間的挑戰——\r\n魔術、小丑與民間信仰的極限碰撞，重塑表演的想像！\r\n虛實之間，創意交鋒；真假遊走，挑戰視野；打破界限，玩出全新表演語言！\r\n\r\n——17th新人及作品——\r\n林陸傑 Lin Lu-Chieh《錯誤（的）引導》Misdirected\r\n世界就是一場魔術，裡頭藏著無限秘密。\r\n\r\n郭鎧瑞 Guo Kai-Ruei《一炷香的時間》An Incense Stick of Time\r\n在迷失的愛戀與靈性中掙扎，最終尋找自我與真實情感。\r\n\r\n劉唐成 Liu Tang-Cheng《小丑與他的創造者》Clown and His Creator\r\n小丑對扮演自己失去熱忱的演員發出的調解通知書。', `organizer`='財團法人國家文化藝術基金會', `address`='臺北市中正區中山南路21之1號', `start_date`='2025-05-09 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='國家兩廳院', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='/+1000', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6cf26b3240c403d997c', '?te WINTER TOUR(高雄場)', '本次巡演以展現壞特獨特的音樂魅力與深厚的爵士情感，巡演計劃於北中南五個城市，此次巡演旨在以壞特的音樂風格為媒介，連結聽眾與爵士樂的情感共鳴，並持續深化她在音樂創作上的獨特標籤。\r\n\r\n活動目標為推廣爵士文化，吸引熱愛音樂的群眾參與，並為每座城市注入藝術活力，期待透過音樂與觀眾交流。', '高雄流行音樂中心', '高雄市鹽埕區17鄰真愛路1號', '2025-02-25 00:00:00', '2025-02-25 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '身障票+600;預售票+1000;普通票+1200', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='?te WINTER TOUR(高雄場)', `description`='本次巡演以展現壞特獨特的音樂魅力與深厚的爵士情感，巡演計劃於北中南五個城市，此次巡演旨在以壞特的音樂風格為媒介，連結聽眾與爵士樂的情感共鳴，並持續深化她在音樂創作上的獨特標籤。\r\n\r\n活動目標為推廣爵士文化，吸引熱愛音樂的群眾參與，並為每座城市注入藝術活力，期待透過音樂與觀眾交流。', `organizer`='高雄流行音樂中心', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-02-25 00:00:00', `end_date`='2025-02-25 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='身障票+600;預售票+1000;普通票+1200', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf6a126b3240c403d9941', '《魔幻森林─文山劇場工作坊》', '本展覽在文山劇場兒童戲劇及親子藝文活動的定位下，以趣味、創意、互動的展覽設計為前提，帶領學童由後臺出發，進入後臺各部門到前臺表演區的各項劇場體驗，歷經一趟從劇場製作到舞臺演出的神秘之旅！一窺支撐舞臺表演的各專業領域是如何創作及執行。', '臺北市藝文推廣處', '臺北市文山區景文街32號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '臺北市藝文推廣處-文山劇場', 24.98857934, 121.5736082, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《魔幻森林─文山劇場工作坊》', `description`='本展覽在文山劇場兒童戲劇及親子藝文活動的定位下，以趣味、創意、互動的展覽設計為前提，帶領學童由後臺出發，進入後臺各部門到前臺表演區的各項劇場體驗，歷經一趟從劇場製作到舞臺演出的神秘之旅！一窺支撐舞臺表演的各專業領域是如何創作及執行。', `organizer`='臺北市藝文推廣處', `address`='臺北市文山區景文街32號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺北市藝文推廣處-文山劇場', `latitude`=24.98857934, `longitude`=121.5736082, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9362686', '114年母乳哺育系列課程(上半年)~邀請對母乳哺育有興趣者一同參加。', '「114年母乳哺育系列課程」活動訊息(上半年)母乳哺育系列課程~邀請對母乳哺育有興趣者一同參加~本中心為增進媽媽們母乳哺餵知識及概念，以提升母乳的哺餵意願，並建立完善支持性環境，辦理相關課程訊息如下：時間：114年2月20日至6月19日，共辦理5&nbsp;堂課程。二&nbsp;、地點：小小貓頭鷹玩樂屋（士林區雨聲街53巷1號）。三、對象：正在哺乳的婦女、0~6歲親子、對母乳哺育有興趣者。四、費用：課程免費，大人入館請穿襪子。五、報名方式：採現場報名，名額20人，額滿為止，請提早到場。&nbsp;&nbsp;六、洽詢專線：(02)2836-0200&nbsp;小小貓頭鷹玩樂屋七、詳情請見附件:114年母乳哺育系列課程表。', '臺北市士林區健康服務中心', '無資料', '2025-02-25 00:00:00', '2025-06-19 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=399BC669CCB712B7', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年母乳哺育系列課程(上半年)~邀請對母乳哺育有興趣者一同參加。', `description`='「114年母乳哺育系列課程」活動訊息(上半年)母乳哺育系列課程~邀請對母乳哺育有興趣者一同參加~本中心為增進媽媽們母乳哺餵知識及概念，以提升母乳的哺餵意願，並建立完善支持性環境，辦理相關課程訊息如下：時間：114年2月20日至6月19日，共辦理5&nbsp;堂課程。二&nbsp;、地點：小小貓頭鷹玩樂屋（士林區雨聲街53巷1號）。三、對象：正在哺乳的婦女、0~6歲親子、對母乳哺育有興趣者。四、費用：課程免費，大人入館請穿襪子。五、報名方式：採現場報名，名額20人，額滿為止，請提早到場。&nbsp;&nbsp;六、洽詢專線：(02)2836-0200&nbsp;小小貓頭鷹玩樂屋七、詳情請見附件:114年母乳哺育系列課程表。', `organizer`='臺北市士林區健康服務中心', `address`='無資料', `start_date`='2025-02-25 00:00:00', `end_date`='2025-06-19 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=399BC669CCB712B7', `image_url`='[]';
