INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9362558', '歡迎大小朋友進入「書式生活圈-幸福共讀」吧!', '凡至總館參加指定嬰幼兒說故事活動，並於當天借滿5本兒童書，即可獲得專屬集點卡「幸福點數」1點，集滿3點者可自選3本二手精美好書。自即日起至8月31日集滿24點者，則可再兌換小玩具1份。一、活動期間： 3月1日至8月31日二、活動對象：持本館有效借閱證之讀者三、活動地點：總館地下1樓兒童室、地下2樓小小世界外文圖書館四、總館嬰幼兒說故事活動&nbsp;(一) Qbaby雙語說故時間：對象為2至6歲的親子；第1、3、5個週五上午10時30分至11時。活動消息網址:https://reurl.cc/A6vW6j&nbsp;(二) 嬰幼兒說故事時間：對象為0至3歲的親子；第2、4個週六，上午10時至10時30分以及上午11時至11時30分(兩場老師及內容皆相同，參加2場者可獲得點數2點)。活動消息網址: https://reurl.cc/XZKrA3&nbsp;（三）日文繪本童樂趣：對象為0至3歲的親子；每週三上午11時30分至12時30分。活動消息網址: https://reurl.cc/mRKbkl五、活動辦法：於活動開始15分鐘內，工作人員會於教室門口發放集點卡。活動結束即可找當天說故事老師蓋說故事專屬章；再至地下2樓櫃檯查核當天已借滿5本兒童書，即可獲得幸福點數1點。兌換獎勵請至總館地下2樓小小世界櫃檯。小小世界外文圖書館地址：臺北市大安區建國南路2段125號地下2樓服務時間：週一、週日9：00～17：00；週二至週六9：00～18：00洽詢電話：（02）2755-2823 #2140交通資訊：https://reurl.cc/mrXRm9', '臺北市立圖書館', '無資料', '2025-02-25 00:00:00', '2025-08-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1D406E52E2BA6AE9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歡迎大小朋友進入「書式生活圈-幸福共讀」吧!', `description`='凡至總館參加指定嬰幼兒說故事活動，並於當天借滿5本兒童書，即可獲得專屬集點卡「幸福點數」1點，集滿3點者可自選3本二手精美好書。自即日起至8月31日集滿24點者，則可再兌換小玩具1份。一、活動期間： 3月1日至8月31日二、活動對象：持本館有效借閱證之讀者三、活動地點：總館地下1樓兒童室、地下2樓小小世界外文圖書館四、總館嬰幼兒說故事活動&nbsp;(一) Qbaby雙語說故時間：對象為2至6歲的親子；第1、3、5個週五上午10時30分至11時。活動消息網址:https://reurl.cc/A6vW6j&nbsp;(二) 嬰幼兒說故事時間：對象為0至3歲的親子；第2、4個週六，上午10時至10時30分以及上午11時至11時30分(兩場老師及內容皆相同，參加2場者可獲得點數2點)。活動消息網址: https://reurl.cc/XZKrA3&nbsp;（三）日文繪本童樂趣：對象為0至3歲的親子；每週三上午11時30分至12時30分。活動消息網址: https://reurl.cc/mRKbkl五、活動辦法：於活動開始15分鐘內，工作人員會於教室門口發放集點卡。活動結束即可找當天說故事老師蓋說故事專屬章；再至地下2樓櫃檯查核當天已借滿5本兒童書，即可獲得幸福點數1點。兌換獎勵請至總館地下2樓小小世界櫃檯。小小世界外文圖書館地址：臺北市大安區建國南路2段125號地下2樓服務時間：週一、週日9：00～17：00；週二至週六9：00～18：00洽詢電話：（02）2755-2823 #2140交通資訊：https://reurl.cc/mrXRm9', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-25 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='無資料', 