INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('272858548ed8e90ab2c017c6962eb03f', '新北市板橋地政事務所自114年2月24日起至3月24日止舉辦「謄本查驗辨真假 輕鬆防偽不被詐」大家一起來找查體驗活動有獎徵答網站活動', '新北市板橋地政事務所自114年2月24日起至3月24日止舉辦「謄本查驗辨真假 輕鬆防偽不被詐」大家一起來找查體驗活動有獎徵答網站活動！民眾只要體驗謄本查驗功能並至活動頁面填寫回饋，將隨機抽出30名參與活動且完整填寫回饋之幸運兒贈送神秘小禮物1份，歡迎大家共襄盛舉', '新北市板橋地政事務所', '新北市板橋區實踐路1號', '新北市板橋地政事務所全球資訊網', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新北市板橋地政事務所自114年2月24日起至3月24日止舉辦「謄本查驗辨真假 輕鬆防偽不被詐」大家一起來找查體驗活動有獎徵答網站活動', `description`='新北市板橋地政事務所自114年2月24日起至3月24日止舉辦「謄本查驗辨真假 輕鬆防偽不被詐」大家一起來找查體驗活動有獎徵答網站活動！民眾只要體驗謄本查驗功能並至活動頁面填寫回饋，將隨機抽出30名參與活動且完整填寫回饋之幸運兒贈送神秘小禮物1份，歡迎大家共襄盛舉', `organizer`='新北市板橋地政事務所', `address`='新北市板橋區實踐路1號', `location`='新北市板橋地政事務所全球資訊網', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9362914', '三月臺北花博農民市集 小龍添春色 花博氣象新', '臺北花博農民市集(捷運圓山站1號出口)&nbsp; &nbsp; 春暖花開的季節到來，萬物復甦，草木萌芽，三月份「小龍添春色 花博氣象新」主題月，歡迎到市集挑選喜愛的農產品，迎接新的氣象，享受美好悠閒的週末！&nbsp; &nbsp; 本月於3月1-2日舉行「春日野餐趣 小龍遊花博」主題活動，當週展售臺北市農特產品，內湖蜂蜜、南港包種茶、士林山藥加工品與農創小品盆栽等多樣新鮮蔬果。活動兩日將推出400份摸彩好禮，憑當日消費累計滿800元之農民收據，即可參加1次摸彩。獎項包含臺北市特色農產品、花博農民市集野餐墊等。此外，為感謝大家長期以來對市集的支持，臺北市政府產業發展局更推出滿額贈，憑當日消費累計滿500元之農民收據，即可兌換1份花博農民市集造型雞蛋糕，一日限量100份。另活動當週舞台區將舉行一系列DIY活動，邀請臺北市農民應用在地農產品製作創意料理，欲參加者憑當日消費指定金額之收據至舞台區報名。以上活動，同一張農民收據擇一報名參加。數量有限，把握機會，歡迎來參加！&nbsp;&nbsp; &nbsp; 執行單位台北市農會為讓消費者更深入了解臺北市的在地美味，3月29日特別邀請士林區菁山農場的農民葉奕沛，舉辦「芽菜食農教育-認識寒食節、潤餅捲DIY」，活動中將介紹陽明山地區栽種的新鮮芽菜，並結合應景的潤餅捲DIY體驗。讓參與者在趣味手作的過程中，也能認識士林區在地農業、更了解傳統的節日習俗與文化。活動憑市集全場消費滿500元之收據至舞台區報名，為向青年朋友及親子推廣臺北市在地特色農產品，保障10名青年或親子免收據參加，名額有限，額滿為止！&nbsp; &nbsp; 花博農民市集每週匯集全臺各地特色農產品，特別規劃縣市特展週，邀請各縣市輪流展售在地優質農產，3月8-9日臺東農特產品展售-紅烏龍茶、鳳梨釋迦，紅烏龍是鹿野地區的特色茶，無論冷泡或熱泡皆宜，尤其冷泡更凸顯其甘醇滋味，特別適合喜愛醇厚茶韻的品茗者；3月15-16日彰化農特產品展售-蛋、蜂蜜，營養豐富的雞蛋可變化出多種美味料理，而彰化是全臺最大的雞蛋產地，歡迎當週前來選購，品嚐品質優良的彰化雞蛋；3月22-23日花蓮農特產品展售-箭筍，外型細長、僅手指寬的箭筍，主要產地位於花蓮，口感甘甜脆嫩，無論是煲湯或拌炒皆別有一番風味；3月29-30日嘉義農特產品展售-香蕉、木瓜、高山茶，嘉義阿里山高山茶享譽國際，茶農們在高海拔山區細心栽培與採收，培植出耐寒且品質優良的茶葉，想一品高山茶獨有的茶香韻味，歡迎當週前來市集品茗！&nbsp; &nbsp; 想知道更多市集的活動訊息，請鎖定Facebook粉絲團「台北花博農民市集」及「臺北市政府產業發展局」粉絲專頁，或臺北花博農民市集官網（https://www.expofarmersmarket.gov.taipei/index2.php），等你來挖寶喔！(市集營業時間為每週六、日早上10:00至晚上18:00，在花博公園圓山園區)&nbsp;圖1.&nbsp;臺東紅烏龍茶圖2. 彰化雞蛋圖3.&nbsp;花蓮箭筍圖4.&nbsp;嘉義高山茶圖5.&nbsp;臺北市士林區菁山農場種植各式新鮮芽菜圖6.歡迎到市集品茗臺北好茶&nbsp; &nbsp;&nbsp;', '臺北市政府產業發展局', '無資料', '2025-03-01 00:00:00', '2025-05-01 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B9A8A180854FC4D1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三月臺北花博農民市集 小龍添春色 花博氣象新', `description`='臺北花博農民市集(捷運圓山站1號出口)&nbsp; &nbsp; 春暖花開的季節到來，萬物復甦，草木萌芽，三月份「小龍添春色 花博氣象新」主題月，歡迎到市集挑選喜愛的農產品，迎接新的氣象，享受美好悠閒的週末！&nbsp; &nbsp; 本月於3月1-2日舉行「春日野餐趣 小龍遊花博」