INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9362810', '總館美國資料中心-「未來創作力：AI × 藝術 × 設計」研習活動，歡迎踴躍參加﹗', '&nbsp; &nbsp; 本館與美國在台協會合辦「未來創作力：AI &times; 藝術 &times; 設計」研習活動，邀請奇響創意有限公司負責人Peggy講師，辦理4場AI主題的研習活動，此活動圍繞 AI、藝術、設計和創意應用，邀請大眾學習AI科技應用，掌握未來技能。一、活動主題、時間3月8日(週六)下午2時至4時/從藝術家到策展人：台灣科技藝術創業之路3月15日(週六)下午1時30分至5時30分/POP Art X AI：專屬提袋設計工作坊3月22日(週六)下午2時至5時/簡報溝通術：AI 簡報技巧3月29日(週六)下午2時至5時/AI 繪圖創作：AI插畫藝術入門二、活動對象：一般大眾三、活動地點：總館9樓電腦教室四、講師：Peggy(奇響創意有限公司負責人)五、報名網址：將於3月1日(週六)發布於臺北市立圖書館服務讚粉絲專頁(https://www.facebook.com/taipeilibrary/)六、備註1：教室有提供電腦供參與者操作，參與者也可自備筆電備註2：需自行準備一式Google帳號，請留意是否有綁定特定裝置的雙重驗證功能，以免現場無法登入帳號', '臺北市立圖書館', '無資料', '2025-02-25 00:00:00', '2025-03-29 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=9150C5ACAFAD8F70', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館美國資料中心-「未來創作力：AI × 藝術 × 設計」研習活動，歡迎踴躍參加﹗', `description`='&nbsp; &nbsp; 本館與美國在台協會合辦「未來創作力：AI &times; 藝術 &times; 設計」研習活動，邀請奇響創意有限公司負責人Peggy講師，辦理4場AI主題的研習活動，此活動圍繞 AI、藝術、設計和創意應用，邀請大眾學習AI科技應用，掌握未來技能。一、活動主題、時間3月8日(週六)下午2時至4時/從藝術家到策展人：台灣科技藝術創業之路3月15日(週六)下午1時30分至5時30分/POP Art X AI：專屬提袋設計工作坊3月22日(週六)下午2時至5時/簡報溝通術：AI 簡報技巧3月29日(週六)下午2時至5時/AI 繪圖創作：AI插畫藝術入門二、活動對象：一般大眾三、活動地點：總館9樓電腦教室四、講師：Peggy(奇響創意有限公司負責人)五、報名網址：將於3月1日(週六)發布於臺北市立圖書館服務讚粉絲專頁(https://www.facebook.com/taipeilibrary/)六、備註1：教室有提供電腦供參與者操作，參與者也可自備筆電備註2：需自行準備一式Google帳號，請留意是否有綁定特定裝置的雙重驗證功能，以免現場無法登入帳號', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-25 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=9150C5ACAFAD8F70', `image_url`='[]';
