INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be239826b3240c403d999b', '假日廣場-飛伶越舞創作舞集《2025舞我春風異國藝術舞蹈展》', '結合飛伶越舞創作舞集師資及團隊，一起協力完成。\r\n為此舞蹈可以是一首有形的歌，是一幅流動的畫，表現於形體的生活態度，當舞蹈躍過海洋與另一世界碰撞，會產生許多不一樣的火花，融合出更獨特的樣貌。本活動是一場結合北中南優秀名師、舞者的大型藝術交流活動，藉由舞蹈方式，以展示出專屬於自己獨特的生命歷程，絕對讓人眼前一亮，久久無法忘懷。\r\n', '飛伶越舞創作舞集', '臺南市東區中華東路三段332號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='假日廣場-飛伶越舞創作舞集《2025舞我春風異國藝術舞蹈展》', `description`='結合飛伶越舞創作舞集師資及團隊，一起協力完成。\r\n為此舞蹈可以是一首有形的歌，是一幅流動的畫，表現於形體的生活態度，當舞蹈躍過海洋與另一世界碰撞，會產生許多不一樣的火花，融合出更獨特的樣貌。本活動是一場結合北中南優秀名師、舞者的大型藝術交流活動，藉由舞蹈方式，以展示出專屬於自己獨特的生命歷程，絕對讓人眼前一亮，久久無法忘懷。\r\n', `organizer`='飛伶越舞創作舞集', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23a426b3240c403d999c', '【繪彩之心-通識油畫課精選作品展】12.20-5.25@總圖書館4F-6F藝想空間', '本次展覽展示了來自不同學科的學生在通識油畫課程中的精選作品，展示學生在學習過程中對油畫藝術的探索與創新。這些作品表示了油畫藝術的獨特魅力，並展現學生們對色彩和技法的靈活掌握。每一幅畫作都蘊藏著創作者的心靈故事，是情感、靈感與思維的交織與碰撞。\r\n透過這場展覽，我們邀請觀者深入體驗油畫的美感與力量，感受學生們在畫布上所描繪的豐富情感與無限想像。', '國立清華大學', '新竹市東區光復路二段101號', '2025-01-01 00:00:00', '2025-05-25 00:00:00', '國立清華大學', 24.7964538, 120.9966725, '無資料', 'https://www.lib.nthu.edu.tw/news/default.html#rss_exhibit.xml!1467', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【繪彩之心-通識油畫課精選作品展】12.20-5.25@總圖書館4F-6F藝想空間', `description`='本次展覽展示了來自不同學科的學生在通識油畫課程中的精選作品，展示學生在學習過程中對油畫藝術的探索與創新。這些作品表示了油畫藝術的獨特魅力，並展現學生們對色彩和技法的靈活掌握。每一幅畫作都蘊藏著創作者的心靈故事，是情感、靈感與思維的交織與碰撞。\r\n透過這場展覽，我們邀請觀者深入體驗油畫的美感與力量，感受學生們在畫布上所描繪的豐富情感與無限想像。', `organizer`='國立清華大學', `address`='新竹市東區光復路二段101號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='國立清華大學', `latitude`=24.7964538, `longitude`=120.9966725, `ticket_price`='無資料', `source_url`='https://www.lib.nthu.edu.tw/news/default.html#rss_exhibit.xml!1467', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23a426b3240c403d999d', '臺中市2025年親子繪畫寫生比賽', '台中市豐原國際同濟會為淬鍊繪畫寫生技巧、增益愛鄉戀土情懷，訂於114年3月1日(星期六)假豐原葫蘆墩公園舉辦臺中市2025年親子繪畫寫生比賽，並於114年4月2日至4月30日展出得獎作品。', '國際同濟會台灣總會台中區  ', '臺中市豐原區育仁路81號', '2025-04-02 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館豐原分館', 24.24990298, 120.7375715, '無資料', 'https://www.facebook.com/groups/899501746803487/permalink/8897681116985470/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市2025年親子繪畫寫生比賽', `description`='台中市豐原國際同濟會為淬鍊繪畫寫生技巧、增益愛鄉戀土情懷，訂於114年3月1日(星期六)假豐原葫蘆墩公園舉辦臺中市2025年親子繪畫寫生比賽，並於114年4月2日至4月30日展出得獎作品。', `organizer`='國際同濟會台灣總會台中區  ', `address`='臺中市豐原區育仁路81號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館豐原分館', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.facebook.com/groups/899501746803487/permalink/8897681116985470/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23a426b3240c403d999e', '英語說故事時間（2月，5場）', '寶貝故事屋－ABC說英文故事 14:30-15:00\r\nABC說英文故事 14:30-15:00\r\n2月15日下午 (主講) Jasmine Chiu /The Duck Who Didn''t Like Water\r\n\r\n※英語說故事時間\r\n由外籍老師帶領小小朋友(嬰幼兒)聽英文故事與互動遊戲', '臺中市立圖書館總館', '臺中市北屯區豐樂路二段158號', '2025-02-06 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館總館', 24.18400298, 120.7362319, '無資料', 'https://reurl.cc/969DGd', '[]') ON DUPLICATE KEY UPDATE `activity_name`='英語說故事時間（2月，5場）', `description`='寶貝故事屋－ABC說英文故事 14:30-15:00\r\nABC說英文故事 14:30-15:00\r\n2月15日下午 (主講) Jasmine Chiu /The Duck Who Didn''t Like Water\r\n\r\n※英語說故事時間\r\n由外籍老師帶領小小朋友(嬰幼兒)聽英文故事與互動遊戲', `organizer`='臺中市立圖書館總館', `address`='臺中市北屯區豐樂路二段158號', `start_date`='2025-02-06 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館總館', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://reurl.cc/969DGd', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23a426b3240c403d999f', '上楓主題書展(2月3場)', '2/1-2/9【故事之島：從臺灣到波隆那】書展\r\n地點:1樓入口展區\r\n義大利波隆那兒童書展-故事之島：從臺灣到波隆那\r\n台北國際書展訂於1/2-2/9舉辦，為共襄盛舉書展活動，中市圖將共同串聯活動。\r\n\r\n2/1-2/27【We live together環境生態】書展\r\n地點:二樓前端展區\r\n上楓分館是臺中市首座以「環境教育」為主題特色的圖書館，以【We live together環境生態】書展展出環保教育好書，陳列與地球生態、氣候、環保等相關的精彩好書。 邀請大家，走進上楓分館，傾聽地球的聲音！\r\n為加強讀者對2050年SDGs目標的認識，本月特展出:\r\n目標9建設具防災能力的基礎設施，促進具包容性的永續工業化及推動創新。\r\n目標10減少國家內部和國家之間的不平等。\r\n\r\n2/11-2/27 開學趣主題書展\r\n地點:一樓入口展區\r\n又到了開學季，上楓分館為學子們備好書籍，讓您開學閱讀趣，越讀越有趣！學習變得更學單有趣喲！歡迎借閱！', '臺中市立圖書館上楓分館', '臺中市大雅區樹德街255巷5號', '2025-02-01 00:00:00', '2025-02-27 00:00:00', '臺中市立圖書館上楓分館', 24.22704181, 120.6411818, '無資料', 'https://reurl.cc/WAo0MZ', '[]') ON DUPLICATE KEY UPDATE `activity_name`='上楓主題書展(2月3場)', `description`='2/1-2/9【故事之島：從臺灣到波隆那】書展\r\n地點:1樓入口展區\r\n義大利波隆那兒童書展-故事之島：從臺灣到波隆那\r\n台北國際書展訂於1/2-2/9舉辦，為共襄盛舉書展活動，中市圖將共同串聯活動。\r\n\r\n2/1-2/27【We live together環境生態】書展\r\n地點:二樓前端展區\r\n上楓分館是臺中市首座以「環境教育」為主題特色的圖書館，以【We live together環境生態】書展展出環保教育好書，陳列與地球生態、氣候、環保等相關的精彩好書。 邀請大家，走進上楓分館，傾聽地球的聲音！\r\n為加強讀者對2050年SDGs目標的認識，本月特展出:\r\n目標9建設具防災能力的基礎設施，促進具包容性的永續工業化及推動創新。\r\n目標10減少國家內部和國家之間的不平等。\r\n\r\n2/11-2/27 開學趣主題書展\r\n地點:一樓入口展區\r\n又到了開學季，上楓分館為學子們備好書籍，讓您開學閱讀趣，越讀越有趣！學習變得更學單有趣喲！歡迎借閱！', `organizer`='臺中市立圖書館上楓分館', `address`='臺中市大雅區樹德街255巷5號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-27 00:00:00', `location`='臺中市立圖書館上楓分館', `latitude`=24.22704181, `longitude`=120.6411818, `ticket_price`='無資料', `source_url`='https://reurl.cc/WAo0MZ', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23a426b3240c403d99a0', '臺中市立圖書館后里分館-2月主題書展', '2月14日是國際公認的情人節🥰\r\n以愛為核心，透過書籍探索愛情。\r\n本次內容將展出情感關係中的互相尊重與理解、\r\n面對不適合的人要如何告別等相關書籍，\r\n讓我們重新審視愛的意義。💘', '臺中市立圖書館后里分館', '臺中市后里區文化路28號', '2025-01-26 00:00:00', '2025-02-26 00:00:00', '臺中市立圖書館后里分館', 24.30962483, 120.7146127, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館后里分館-2月主題書展', `description`='2月14日是國際公認的情人節🥰\r\n以愛為核心，透過書籍探索愛情。\r\n本次內容將展出情感關係中的互相尊重與理解、\r\n面對不適合的人要如何告別等相關書籍，\r\n讓我們重新審視愛的意義。💘', `organizer`='臺中市立圖書館后里分館', `address`='臺中市后里區文化路28號', `start_date`='2025-01-26 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='臺中市立圖書館后里分館', `latitude`=24.30962483, `longitude`=120.7146127, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23a526b3240c403d99a1', '臺中市立圖書館總館2月主題書展', '1樓－山林．癒書展\r\n「山林．癒」書展以文字為橋，邀請您在自然與心靈間找到和諧與平衡。在每一頁書中，您將感受到山林的溫暖與撫慰，聽見大自然低語般的召喚。\r\n\r\n1樓－Openbook好書獎\r\n2024 Openbook好書獎精選的作品，展現從外部衝突到人與自然、科技、生命網絡的深度連結。性別視角滲透各領域，本土創作釋放豐沛生命力，童書綻放想像，議題書寫照亮忽視的角落。\r\n\r\n2樓閱讀解憂書房－我的小日子書展\r\n簡介：新的一年，整理你的家也整理你的心～透過整頓身心、整理收納心法，打造舒適又溫馨的家，迎接煥然一新的生活！\r\n\r\n2樓迴廊－聯想書展\r\n聯想書展以展出與想像力和創作力相關的書籍為核心，致力於激發讀者的無限可能。本次書展結合總館二樓全國兒童聯想創作比賽，呈現孩子們充滿奇思妙想的得獎作品，讓參觀者感受純真的創作魅力。\r\n無論是從故事情節中發掘驚喜，還是從視覺藝術中汲取靈感，書展旨在鼓勵讀者開拓視野，將聯想力化為創作的動力，讓想像力成為日常生活中不可或缺的一部分。\r\n\r\n2樓－故事之島：從臺灣到波隆那書展\r\n簡介：2025台北國際書展主題國為「義大利」，中市圖推出「故事之島：從臺灣到波隆那」主題書展，精選2024義大利波隆那書展臺灣館之原創書，將臺灣魅力分享給讀者。\r\n', '臺中市立圖書館總館', '臺中市北屯區豐樂路二段158號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺中市立圖書館總館', 24.18400298, 120.7362319, '無資料', 'https://reurl.cc/Q5oam0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館總館2月主題書展', `description`='1樓－山林．癒書展\r\n「山林．癒」書展以文字為橋，邀請您在自然與心靈間找到和諧與平衡。在每一頁書中，您將感受到山林的溫暖與撫慰，聽見大自然低語般的召喚。\r\n\r\n1樓－Openbook好書獎\r\n2024 Openbook好書獎精選的作品，展現從外部衝突到人與自然、科技、生命網絡的深度連結。性別視角滲透各領域，本土創作釋放豐沛生命力，童書綻放想像，議題書寫照亮忽視的角落。\r\n\r\n2樓閱讀解憂書房－我的小日子書展\r\n簡介：新的一年，整理你的家也整理你的心～透過整頓身心、整理收納心法，打造舒適又溫馨的家，迎接煥然一新的生活！\r\n\r\n2樓迴廊－聯想書展\r\n聯想書展以展出與想像力和創作力相關的書籍為核心，致力於激發讀者的無限可能。本次書展結合總館二樓全國兒童聯想創作比賽，呈現孩子們充滿奇思妙想的得獎作品，讓參觀者感受純真的創作魅力。\r\n無論是從故事情節中發掘驚喜，還是從視覺藝術中汲取靈感，書展旨在鼓勵讀者開拓視野，將聯想力化為創作的動力，讓想像力成為日常生活中不可或缺的一部分。\r\n\r\n2樓－故事之島：從臺灣到波隆那書展\r\n簡介：2025台北國際書展主題國為「義大利」，中市圖推出「故事之島：從臺灣到波隆那」主題書展，精選2024義大利波隆那書展臺灣館之原創書，將臺灣魅力分享給讀者。\r\n', `organizer`='臺中市立圖書館總館', `address`='臺中市北屯區豐樂路二段158號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市立圖書館總館', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://reurl.cc/Q5oam0', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23a526b3240c403d99a2', '2025小願遊「蛇趣海線」', '2025 小願遊「蛇趣海線」。\r\n\r\n由中港高中、大秀國小聯合清水小願文化創意協會精心策劃，於2025年1月26日正式開幕\r\n\r\n大秀國小蛇年版畫展：哲理與童趣的完美結合\r\n指導老師邱雅琴、楊偵琴引領學生們以蛇年為題進行版畫創作，結合中西方關於「蛇」的傳說，尤其是以銜尾蛇的無限循環為主題，創作出多件兼具童趣與哲理的作品，透過藝術表現了「生命生生不息」的理念。\r\n\r\n蛇趣踅夜市動漫展：創意行銷地方特色\r\n由中港高中國中部美術班策劃的「蛇趣踅夜市動漫展」，以清水五權夜市為靈感，創作出28 件真人大小的動漫立牌，包括「阿中牛肉湯」、「柯南臭豆腐」、「洪帥烤肉」等角色，將夜市美食轉化為創意角色，增添趣味性，巧妙結合了學生的藝術專長與地方特色。\r\n\r\n萌蛇彩蛋陶藝展：濃厚年節氛圍\r\n在陶藝家李承恩及白宗平老師的指導下，中港高中美術班學生創作出多件以蛇年為主題的「萌蛇彩蛋」陶塑作品及繽紛陶杯，並搭配手繪蛇年春聯，展現濃厚的年節氛圍。\r\n\r\n展覽資訊\r\n時間：1/26(日)-4/13(日) 09:30-17:30(周一休園)\r\n地點：清水眷村文化園區 西6號房舍', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-01-26 00:00:00', '2025-04-13 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Activity/Activity_More?id=6699e308bc3847c9914f858bc6db8ada', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025小願遊「蛇趣海線」', `description`='2025 小願遊「蛇趣海線」。\r\n\r\n由中港高中、大秀國小聯合清水小願文化創意協會精心策劃，於2025年1月26日正式開幕\r\n\r\n大秀國小蛇年版畫展：哲理與童趣的完美結合\r\n指導老師邱雅琴、楊偵琴引領學生們以蛇年為題進行版畫創作，結合中西方關於「蛇」的傳說，尤其是以銜尾蛇的無限循環為主題，創作出多件兼具童趣與哲理的作品，透過藝術表現了「生命生生不息」的理念。\r\n\r\n蛇趣踅夜市動漫展：創意行銷地方特色\r\n由中港高中國中部美術班策劃的「蛇趣踅夜市動漫展」，以清水五權夜市為靈感，創作出28 件真人大小的動漫立牌，包括「阿中牛肉湯」、「柯南臭豆腐」、「洪帥烤肉」等角色，將夜市美食轉化為創意角色，增添趣味性，巧妙結合了學生的藝術專長與地方特色。\r\n\r\n萌蛇彩蛋陶藝展：濃厚年節氛圍\r\n在陶藝家李承恩及白宗平老師的指導下，中港高中美術班學生創作出多件以蛇年為主題的「萌蛇彩蛋」陶塑作品及繽紛陶杯，並搭配手繪蛇年春聯，展現濃厚的年節氛圍。\r\n\r\n展覽資訊\r\n時間：1/26(日)-4/13(日) 09:30-17:30(周一休園)\r\n地點：清水眷村文化園區 西6號房舍', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-01-26 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Activity/Activity_More?id=6699e308bc3847c9914f858bc6db8ada', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23a626b3240c403d99a3', '【銀藝流光】2025年第1季銀齡主題推廣活動-非常「動」人˙「藝」起長大(銀齡場)', '童年與兒時玩伴一起玩遊戲，打彈珠、跳格子、紅綠燈、躲貓貓……好多熟悉的身體動作和聲音陪伴我們，成為我們青春的記憶。你是否也想跟家人、朋友、夥伴分享這些青春的美好片刻？南美館今年度第1季推出肢體工作坊，除了以繪本故事帶領大家回顧或想像「長大」這件事，更將透過奔跑、跳躍等等身體動作與遊戲參與，探索自己的生命故事，與夥伴一起找尋青春的印記、想像無限可能的未來、重拾童心未泯的快樂！', '臺南市美術館', '臺南市中西區臺南市中西區南門路 37 號', '2025-03-14 00:00:00', '2025-03-14 00:00:00', '臺南市美術館1館', 22.99594458, 120.192874, '活動免費，入館需依規定購票+--', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【銀藝流光】2025年第1季銀齡主題推廣活動-非常「動」人˙「藝」起長大(銀齡場)', `description`='童年與兒時玩伴一起玩遊戲，打彈珠、跳格子、紅綠燈、躲貓貓……好多熟悉的身體動作和聲音陪伴我們，成為我們青春的記憶。你是否也想跟家人、朋友、夥伴分享這些青春的美好片刻？南美館今年度第1季推出肢體工作坊，除了以繪本故事帶領大家回顧或想像「長大」這件事，更將透過奔跑、跳躍等等身體動作與遊戲參與，探索自己的生命故事，與夥伴一起找尋青春的印記、想像無限可能的未來、重拾童心未泯的快樂！', `organizer`='臺南市美術館', `address`='臺南市中西區臺南市中西區南門路 37 號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-14 00:00:00', `location`='臺南市美術館1館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='活動免費，入館需依規定購票+--', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23a826b3240c403d99a4', '臺中市立中港高中國中部第十七屆美術班畢業展-火龍果', '中港高中國中部第十七屆美術班裡每個學生就像是一顆顆獨特的火龍果，外表色彩鮮豔，內心充滿活力和潛力。班級就像是一籃子的火龍果，每一顆都閃耀著獨特的光芒，共同構成了一個充滿活力和生機的整體。\r\n同學就像火龍果一樣，外表看似雷同，卻各具特色，內心充滿了創造力和想像力，讓整個班級充滿了生機和熱情，讓人感受到無限的可能和希望！\r\n中港高中國中部第十七屆美術班以「火龍果」為畢業展主題，運用多元豐富的媒材、技法，創作出獨一無二、各具風格的作品，來呈現學習成果。真心期待同學們的作品與您的心靈能有一場美好的邂逅。', '臺中市立中港高級中學', '臺中市清水區忠貞路21號', '2025-02-08 00:00:00', '2025-03-09 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=04922f2663dd47658540b0d9a5bf8097', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立中港高中國中部第十七屆美術班畢業展-火龍果', `description`='中港高中國中部第十七屆美術班裡每個學生就像是一顆顆獨特的火龍果，外表色彩鮮豔，內心充滿活力和潛力。班級就像是一籃子的火龍果，每一顆都閃耀著獨特的光芒，共同構成了一個充滿活力和生機的整體。\r\n同學就像火龍果一樣，外表看似雷同，卻各具特色，內心充滿了創造力和想像力，讓整個班級充滿了生機和熱情，讓人感受到無限的可能和希望！\r\n中港高中國中部第十七屆美術班以「火龍果」為畢業展主題，運用多元豐富的媒材、技法，創作出獨一無二、各具風格的作品，來呈現學習成果。真心期待同學們的作品與您的心靈能有一場美好的邂逅。', `organizer`='臺中市立中港高級中學', `address`='臺中市清水區忠貞路21號', `start_date`='2025-02-08 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=04922f2663dd47658540b0d9a5bf8097', `image_url`='[]';
