INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23a926b3240c403d99a9', '亞洲盃菁英全國大賽', '【亞洲盃菁英全國大賽】，是為了成為學子們一展長才的表演舞台而創立，冀望能為亞洲地區的音樂學子們藉由比賽的參與，推展國內音樂教育，提供表演舞台，發掘更多傑出音樂人才，為台灣貢獻一份心力。各項樂器的比賽相互切磋，內容有古典鋼琴、爵士鋼琴、四手聯彈，打擊類有爵士鼓、太鼓…各項樂器有吉他、電吉他…之上各項樂器的比賽，在亞太地區樂界更上一層，讓學習音樂的孩子們在過程中有一明確的目標與發展空間，將此一理念推展至全國各地，期盼台灣音樂的發展能成為亞太地區樂界的標竿。\r\n【單位簡介】本單位以推廣爵士鼓教學，推動地方音樂風氣，發起地方文化，並積極與地方單位、公益團體結合舉辦大型活動、比賽…等，並藉由爵士鼓、吉他、電吉他、烏克麗麗讓兒童及青少年有紓壓管道及舞台，進而增加自信為本會宗旨。', '亞洲音樂有限公司', '臺中市西區英才路600號', '2025-03-29 00:00:00', '2025-03-30 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://lurl.cc/SvMigF', '[]') ON DUPLICATE KEY UPDATE `activity_name`='亞洲盃菁英全國大賽', `description`='【亞洲盃菁英全國大賽】，是為了成為學子們一展長才的表演舞台而創立，冀望能為亞洲地區的音樂學子們藉由比賽的參與，推展國內音樂教育，提供表演舞台，發掘更多傑出音樂人才，為台灣貢獻一份心力。各項樂器的比賽相互切磋，內容有古典鋼琴、爵士鋼琴、四手聯彈，打擊類有爵士鼓、太鼓…各項樂器有吉他、電吉他…之上各項樂器的比賽，在亞太地區樂界更上一層，讓學習音樂的孩子們在過程中有一明確的目標與發展空間，將此一理念推展至全國各地，期盼台灣音樂的發展能成為亞太地區樂界的標竿。\r\n【單位簡介】本單位以推廣爵士鼓教學，推動地方音樂風氣，發起地方文化，並積極與地方單位、公益團體結合舉辦大型活動、比賽…等，並藉由爵士鼓、吉他、電吉他、烏克麗麗讓兒童及青少年有紓壓管道及舞台，進而增加自信為本會宗旨。', `organizer`='亞洲音樂有限公司', `address`='臺中市西區英才路600號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://lurl.cc/SvMigF', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23a926b3240c403d99aa', '云兮水月箏樂團音樂會', '緣起：\r\n中華文化源遠流長，傳統音樂藝術更是歷史悠久。獨自練琴是一件估躁乏味的事情，尤其不能閉門造車，在老師的鼓勵下，定期舉辦音樂會。藉由表演，讓各位來賓更認識古箏這個樂器，帶動大家對音樂的熱情，也欣賞到音樂家在古箏上長時間磨練與鑽研的結果。\r\n樂團簡介：\r\n云溪水越這個樂團是2023年由熱愛古箏的四位音樂家組成的團體，皆師從韋宛伶老師。曲風多樣，演出時不僅有古箏，更能搭配多元化的樂器來應用。使樂團在表演的時候，既能有默契地互相搭配，又能融合不同的個人特色。\r\n表演曲目：\r\n春節序曲\r\n春到拉薩\r\n茉莉芬芳\r\n嘉陵江之歌\r\n菊次郎的夏天\r\n常相守\r\n山居秋暝\r\n……等……曲目演出……\r\n【索票表單】 https://forms.gle/Hwpm8gr7WVFkmXsC6', '韋宛伶古箏樂團', '臺中市西區英才路600號', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/M6e9A3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='云兮水月箏樂團音樂會', `description`='緣起：\r\n中華文化源遠流長，傳統音樂藝術更是歷史悠久。獨自練琴是一件估躁乏味的事情，尤其不能閉門造車，在老師的鼓勵下，定期舉辦音樂會。藉由表演，讓各位來賓更認識古箏這個樂器，帶動大家對音樂的熱情，也欣賞到音樂家在古箏上長時間磨練與鑽研的結果。\r\n樂團簡介：\r\n云溪水越這個樂團是2023年由熱愛古箏的四位音樂家組成的團體，皆師從韋宛伶老師。曲風多樣，演出時不僅有古箏，更能搭配多元化的樂器來應用。使樂團在表演的時候，既能有默契地互相搭配，又能融合不同的個人特色。\r\n表演曲目：\r\n春節序曲\r\n春到拉薩\r\n茉莉芬芳\r\n嘉陵江之歌\r\n菊次郎的夏天\r\n常相守\r\n山居秋暝\r\n……等……曲目演出……\r\n【索票表單】 https://forms.gle/Hwpm8gr7WVFkmXsC6', `organizer`='韋宛伶古箏樂團', `address`='臺中市西區英才路600號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/M6e9A3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23a926b3240c403d99ab', '三隻小豬感恩演唱會', '活動背景：\r\n這場家庭感恩演唱會是我們一個階段性夢想的實現。每個人不同的方式記錄自己的人生，而在我們家庭中，唱歌始終扮演著非常重要的角色。我們夫妻因歌唱結緣，我們的歌聲更伴隨著孩子的成長。唱歌是我們家人情感交流的重要方式，承載的我們人生各個階段的回憶。每一首歌都有著它特定的時空背景、意義和紀念性，見證著我們的成長與生命得軌跡。這正是我們舉辦家庭演唱會的初衷。用演唱會的形式記錄與回顧我們的生命故事，同時傳遞感恩的心情，與更多人分想這份溫暖，並將這份問暖展現在公益捐款。\r\n活動目標：\r\n1.以音樂的形式促進家庭成員之間的情感交流。\r\n2.分享我們的生命故事，傳遞感恩與幸福的力量。\r\n3.將門票收入扣除成本後捐贈公益團體，以行動回饋社會，傳承關懷的力量。\r\n活動流程：\r\n1.以幾首民歌拉開序幕，喚起觀眾對青春歲月的懷念與共鳴。\r\n2.再以幾首經典粵語歌回顧港劇盛行的年代，最後呈現對我們具有特殊意義的歌曲。\r\n3.以具有紀念的「第一首歌」串聯我們生命中的重要時刻。例如：孩子第一次上台表演的歌曲或紀念意義的歌曲。 \r\n', '巫易卿', '臺中市西區英才路600號', '2025-03-02 00:00:00', '2025-03-02 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://lurl.cc/N2X1JI', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三隻小豬感恩演唱會', `description`='活動背景：\r\n這場家庭感恩演唱會是我們一個階段性夢想的實現。每個人不同的方式記錄自己的人生，而在我們家庭中，唱歌始終扮演著非常重要的角色。我們夫妻因歌唱結緣，我們的歌聲更伴隨著孩子的成長。唱歌是我們家人情感交流的重要方式，承載的我們人生各個階段的回憶。每一首歌都有著它特定的時空背景、意義和紀念性，見證著我們的成長與生命得軌跡。這正是我們舉辦家庭演唱會的初衷。用演唱會的形式記錄與回顧我們的生命故事，同時傳遞感恩的心情，與更多人分想這份溫暖，並將這份問暖展現在公益捐款。\r\n活動目標：\r\n1.以音樂的形式促進家庭成員之間的情感交流。\r\n2.分享我們的生命故事，傳遞感恩與幸福的力量。\r\n3.將門票收入扣除成本後捐贈公益團體，以行動回饋社會，傳承關懷的力量。\r\n活動流程：\r\n1.以幾首民歌拉開序幕，喚起觀眾對青春歲月的懷念與共鳴。\r\n2.再以幾首經典粵語歌回顧港劇盛行的年代，最後呈現對我們具有特殊意義的歌曲。\r\n3.以具有紀念的「第一首歌」串聯我們生命中的重要時刻。例如：孩子第一次上台表演的歌曲或紀念意義的歌曲。 \r\n', `organizer`='巫易卿', `address`='臺中市西區英才路600號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://lurl.cc/N2X1JI', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99ac', '2025中部水彩畫會會員聯展', '「中部水彩畫會」展出都有先進畫家的經驗表現及會員們各自創作獨特的風格，展出作品皆深獲觀者好評，歡迎各位喜愛水彩藝術的同好前來欣賞指教。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-01 00:00:00', '2025-03-12 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000869', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025中部水彩畫會會員聯展', `description`='「中部水彩畫會」展出都有先進畫家的經驗表現及會員們各自創作獨特的風格，展出作品皆深獲觀者好評，歡迎各位喜愛水彩藝術的同好前來欣賞指教。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-12 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000869', `image_url`='[]';
