INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99ae', '藝文研習成果展－柳炎辰師生篆刻展', '篆刻藝術，是文字線條一脈相承的歷史軌跡，治印在傳統中延伸，且筆刀相融心手相應，妙造自然融古出新，每方印章皆擁有不可言傳的生動旨趣。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-01 00:00:00', '2025-03-26 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000870', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝文研習成果展－柳炎辰師生篆刻展', `description`='篆刻藝術，是文字線條一脈相承的歷史軌跡，治印在傳統中延伸，且筆刀相融心手相應，妙造自然融古出新，每方印章皆擁有不可言傳的生動旨趣。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000870', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99af', '2025臺中市女性藝術家邀請展', '在春暖花開的三月，由女性藝術家們傾心打造的藝術盛宴正在臺中綻放。這是一場充滿溫度的展覽，每一件作品背後，都蘊藏著一個獨特而動人的故事。\r\n\r\n隨著時代進步，女性在社會中的角色已突破傳統框架，藝術成為她們表達自我的重要途徑。「臺中市女性藝術家邀請展」自2005年創辦以來，走過二十一個春秋，已成為全國最具規模的公辦女性藝術家聯展，見證了無數女性藝術家的成長與蛻變。\r\n\r\n走進展場，126位女性藝術家的創作如繁星點點，在大墩文化中心熠熠生輝。她們以畫筆為媒，以心靈為引，將生命中的每一次感動轉化為藝術的靈感。今年展覽匯集了126件精彩作品，這些女性創作者以多元的媒材描繪城市風景、自然生態、生活況味與社會議題。從傳統的油畫、水彩、膠彩、墨彩、書法、篆刻，到現代的攝影、雕塑、美術工藝、版畫及壓克力、複合媒材等，每一件作品都是藝術家內心世界的真實投射，展現了她們飽滿的創作能量與無限的想像力。\r\n\r\n藝術的魅力在於它能讓觀者超越時空的限制，在美的世界裡相遇、共鳴、成長。透過藝術創作，我們看見這群女性藝術家不僅展現了對生命的熱情，更彰顯了對社會、人文和自然的關懷。每一幅作品都如同一扇窗，引領觀眾進入創作者的內心世界，感受她們最真摯的情感與最深刻的思考。\r\n\r\n秉持「富市台中，新好生活」與「文化富足」的精神，文化局積極打造優質藝文環境，期待透過展覽繼續推動性別平等的藝術環境，並為下一代女性藝術開創更多元的風貌。展覽自3月8日起至26日止，在這個春意盎然的季節，歡迎喜歡藝術的大小朋友共襄盛舉，結伴相約親臨這場精美的視覺饗宴，感受眾多女性藝術家們用心編織成的美麗篇章，共同譜寫出一曲動人的春日藝文交響！', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-08 00:00:00', '2025-03-26 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000871', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺中市女性藝術家邀請展', `description`='在春暖花開的三月，由女性藝術家們傾心打造的藝術盛宴正在臺中綻放。這是一場充滿溫度的展覽，每一件作品背後，都蘊藏著一個獨特而動人的故事。\r\n\r\n隨著時代進步，女性在社會中的角色已突破傳統框架，藝術成為她們表達自我的重要途徑。「臺中市女性藝術家邀請展」自2005年創辦以來，走過二十一個春秋，已成為全國最具規模的公辦女性藝術家聯展，見證了無數女性藝術家的成長與蛻變。\r\n\r\n走進展場，126位女性藝術家的創作如繁星點點，在大墩文化中心熠熠生輝。她們以畫筆為媒，以心靈為引，將生命中的每一次感動轉化為藝術的靈感。今年展覽匯集了126件精彩作品，這些女性創作者以多元的媒材描繪城市風景、自然生態、生活況味與社會議題。從傳統的油畫、水彩、膠彩、墨彩、書法、篆刻，到現代的攝影、雕塑、美術工藝、版畫及壓克力、複合媒材等，每一件作品都是藝術家內心世界的真實投射，展現了她們飽滿的創作能量與無限的想像力。\r\n\r\n藝術的魅力在於它能讓觀者超越時空的限制，在美的世界裡相遇、共鳴、成長。透過藝術創作，我們看見這群女性藝術家不僅展現了對生命的熱情，更彰顯了對社會、人文和自然的關懷。每一幅作品都如同一扇窗，引領觀眾進入創作者的內心世界，感受她們最真摯的情感與最深刻的思考。\r\n\r\n秉持「富市台中，新好生活」與「文化富足」的精神，文化局積極打造優質藝文環境，期待透過展覽繼續推動性別平等的藝術環境，並為下一代女性藝術開創更多元的風貌。展覽自3月8日起至26日止，在這個春意盎然的季節，歡迎喜歡藝術的大小朋友共襄盛舉，結伴相約親臨這場精美的視覺饗宴，感受眾多女性藝術家們用心編織成的美麗篇章，共同譜寫出一曲動人的春日藝文交響！', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000871', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99b0', '天遠樓五鳳書法聯展', '展出者五鳳之一張靜娟的「廬山煙雨浙江潮」以拙筆漲墨寫出煙雨縹渺的「廬山」加上滾動的「潮」水，既有「目視」之精到，更有「神遇」之快哉！五鳳的作品既有傳統書法的傳承，亦有現代書法的創新，精采可期。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-08 00:00:00', '2025-03-26 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000872', '[]') ON DUPLICATE KEY UPDATE `activity_name`='天遠樓五鳳書法聯展', `description`='展出者五鳳之一張靜娟的「廬山煙雨浙江潮」以拙筆漲墨寫出煙雨縹渺的「廬山」加上滾動的「潮」水，既有「目視」之精到，更有「神遇」之快哉！五鳳的作品既有傳統書法的傳承，亦有現代書法的創新，精采可期。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000872', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99b1', '群藝齊揚－臺中市墨緣雅集畫會會員聯展', '「臺中市墨緣雅集畫會」成員以臺中市為中心遍及北中南各地，成員不乏大學教授及專業藝術家，精湛筆墨技巧在藝術界備受矚目。今年聯展以「群藝齊揚」為主題，作品多元，以水墨為主，更融傳統與現代於一體，展現藝術家的個人風格與創新思維，誠邀藝術愛好者前來與我們共同沉浸這場視覺盛宴。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-08 00:00:00', '2025-03-19 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000873', '[]') ON DUPLICATE KEY UPDATE `activity_name`='群藝齊揚－臺中市墨緣雅集畫會會員聯展', `description`='「臺中市墨緣雅集畫會」成員以臺中市為中心遍及北中南各地，成員不乏大學教授及專業藝術家，精湛筆墨技巧在藝術界備受矚目。今年聯展以「群藝齊揚」為主題，作品多元，以水墨為主，更融傳統與現代於一體，展現藝術家的個人風格與創新思維，誠邀藝術愛好者前來與我們共同沉浸這場視覺盛宴。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-19 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000873', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99b2', '「花影橫斜」沈東榮2025個展', '時序的花語形像落於油畫畫布中，繁櫻紛飛、黃金如雨阿勃勒、荷塘亭亭、如蝶野薑花，都是自然生命美好的靜觀收藏，緩緩描繪下它的細節姿態，那段對語的過程，無待且沈靜。花影橫斜，歲月無言。畫家得幸參與其中，且觀得這一季美好。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-08 00:00:00', '2025-03-26 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000874', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「花影橫斜」沈東榮2025個展', `description`='時序的花語形像落於油畫畫布中，繁櫻紛飛、黃金如雨阿勃勒、荷塘亭亭、如蝶野薑花，都是自然生命美好的靜觀收藏，緩緩描繪下它的細節姿態，那段對語的過程，無待且沈靜。花影橫斜，歲月無言。畫家得幸參與其中，且觀得這一季美好。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000874', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99b3', '我型我塑－王慕賢皮革創作個展', '展覽中有許多有趣的作品，可以看到以寵物照片為靈感的皮雕系列，把家中毛孩子的樣子生動刻畫在皮革上；也有造型獨特的手縫立體皮件，充滿童趣和趣味性。另外，實用與美感兼具的皮革花器、別緻的皮革壁飾與燈飾，甚至還有一群超可愛的「方舟探險隊」小物，等著你來發掘。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-08 00:00:00', '2025-03-26 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000875', '[]') ON DUPLICATE KEY UPDATE `activity_name`='我型我塑－王慕賢皮革創作個展', `description`='展覽中有許多有趣的作品，可以看到以寵物照片為靈感的皮雕系列，把家中毛孩子的樣子生動刻畫在皮革上；也有造型獨特的手縫立體皮件，充滿童趣和趣味性。另外，實用與美感兼具的皮革花器、別緻的皮革壁飾與燈飾，甚至還有一群超可愛的「方舟探險隊」小物，等著你來發掘。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000875', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99b4', '樂陶陶－臺中市陶藝文化協會', '本次活動為陶藝家提供了交流與學習的平台，分享創作心得與技術技巧，共同探討陶藝的未來發展。觀眾則可藉此了解陶藝的歷史文化、製作工藝與美學價值，增進藝術知識與鑑賞能力。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-08 00:00:00', '2025-03-26 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000876', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樂陶陶－臺中市陶藝文化協會', `description`='本次活動為陶藝家提供了交流與學習的平台，分享創作心得與技術技巧，共同探討陶藝的未來發展。觀眾則可藉此了解陶藝的歷史文化、製作工藝與美學價值，增進藝術知識與鑑賞能力。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000876', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99b5', '春之舞-【日知書學會】乙巳聯展', '以『春之舞』為主題，展出新作，時際三月好春時節，以『春之舞』命為展覽主題。書法作品表現形式、或傳統、或實驗、或英文、或彩色，則各自發揮；期能透過豐富靈動的筆墨，詮釋墨舞春風的意涵。今春，就隨「日知書學會」一起沉浸在書法的墨舞春風香裡吧！', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-15 00:00:00', '2025-03-26 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000877', '[]') ON DUPLICATE KEY UPDATE `activity_name`='春之舞-【日知書學會】乙巳聯展', `description`='以『春之舞』為主題，展出新作，時際三月好春時節，以『春之舞』命為展覽主題。書法作品表現形式、或傳統、或實驗、或英文、或彩色，則各自發揮；期能透過豐富靈動的筆墨，詮釋墨舞春風的意涵。今春，就隨「日知書學會」一起沉浸在書法的墨舞春風香裡吧！', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000877', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99b6', '臺中市朝中畫會「三十有成」2025會員聯展暨萬春宮兒童創作展', '「朝中畫會」秉持「藝術創作貴在誠摯與恆心」的理念，對真、善、美的追求從未間斷。會員們每年以畫會友、觀摩切磋，更將生命意境轉化為藝術能量，展出油畫、水彩、水墨等多元題材。今年更特別與「臺中萬春宮」合作辦理臺中市學童寫生比賽，展出學童充滿活力的作品，讓純真與老成相映成趣、互相輝映，誠摯邀請各界蒞臨欣賞。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-22 00:00:00', '2025-04-01 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000878', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市朝中畫會「三十有成」2025會員聯展暨萬春宮兒童創作展', `description`='「朝中畫會」秉持「藝術創作貴在誠摯與恆心」的理念，對真、善、美的追求從未間斷。會員們每年以畫會友、觀摩切磋，更將生命意境轉化為藝術能量，展出油畫、水彩、水墨等多元題材。今年更特別與「臺中萬春宮」合作辦理臺中市學童寫生比賽，展出學童充滿活力的作品，讓純真與老成相映成趣、互相輝映，誠摯邀請各界蒞臨欣賞。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-04-01 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000878', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99b7', '325美術節－相遇臺灣水彩巨擘李澤藩', '李澤藩（1907年6月5日—1989年7月10日），臺灣新竹市人。於72年（1983年）獲行政院文化建設委員會(101年升格為文化部)遴選為十位臺灣前輩畫家之一，為1986年諾貝爾化學獎得主李遠哲的父親。先生畫風樸實，偏愛臺灣鄉間山水風景寫生，更獨創特有的「水洗」、「重疊色層」等風格，尤以重複擦洗修改的「擦洗法」成為他最著名的水彩畫技法。洗畫技法，源自於「捨不得」水彩紙，便嘗試以水沖洗畫壞的畫作，「想不到效果還不錯」便就此自成一家。李澤藩的不透明水彩畫法，以及專擅的寫景風光，對臺灣水彩畫創作影響至深，大墩文化中心特於114年美術節介紹臺灣水彩巨擘李澤藩，以饗大眾。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-25 00:00:00', '2025-04-06 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000879', '[]') ON DUPLICATE KEY UPDATE `activity_name`='325美術節－相遇臺灣水彩巨擘李澤藩', `description`='李澤藩（1907年6月5日—1989年7月10日），臺灣新竹市人。於72年（1983年）獲行政院文化建設委員會(101年升格為文化部)遴選為十位臺灣前輩畫家之一，為1986年諾貝爾化學獎得主李遠哲的父親。先生畫風樸實，偏愛臺灣鄉間山水風景寫生，更獨創特有的「水洗」、「重疊色層」等風格，尤以重複擦洗修改的「擦洗法」成為他最著名的水彩畫技法。洗畫技法，源自於「捨不得」水彩紙，便嘗試以水沖洗畫壞的畫作，「想不到效果還不錯」便就此自成一家。李澤藩的不透明水彩畫法，以及專擅的寫景風光，對臺灣水彩畫創作影響至深，大墩文化中心特於114年美術節介紹臺灣水彩巨擘李澤藩，以饗大眾。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-25 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000879', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99b8', '島嶼印記－洪東標的鄉土情懷70創作展', '臺灣水彩界，洪東標老師是一位重量級的佼佼者。2003年應邀半島藝術季駐村，重回學生時期寫生的描寫大自然，對臺灣這一塊土地有了新的認識，2005亞太水彩協會成立，和林業試驗所合作完成六個國家級植物園的專書，2010年製作了鰲鼓溼地專輯，2012年機車環島寫生記錄臺灣海岸之美，2016年開始6年的從「海上看臺灣」的創作計畫，洪東標始終相信藝術的靈感都來自於生活的體驗，從臺灣這塊土地找到無數的美和靈感，在這次展出中收集了15年來對臺灣這一塊土地記錄中的70餘件水彩作品，有不同時間不同季節和不同天候中的光影場景，他曾經暗自期許和躊躇要努力地成為臺灣的安德魯‧魏斯，很期待讓更多人體會到作者對這座島嶼的感動，而更愛臺灣這塊土地。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-29 00:00:00', '2025-04-16 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000880', '[]') ON DUPLICATE KEY UPDATE `activity_name`='島嶼印記－洪東標的鄉土情懷70創作展', `description`='臺灣水彩界，洪東標老師是一位重量級的佼佼者。2003年應邀半島藝術季駐村，重回學生時期寫生的描寫大自然，對臺灣這一塊土地有了新的認識，2005亞太水彩協會成立，和林業試驗所合作完成六個國家級植物園的專書，2010年製作了鰲鼓溼地專輯，2012年機車環島寫生記錄臺灣海岸之美，2016年開始6年的從「海上看臺灣」的創作計畫，洪東標始終相信藝術的靈感都來自於生活的體驗，從臺灣這塊土地找到無數的美和靈感，在這次展出中收集了15年來對臺灣這一塊土地記錄中的70餘件水彩作品，有不同時間不同季節和不同天候中的光影場景，他曾經暗自期許和躊躇要努力地成為臺灣的安德魯‧魏斯，很期待讓更多人體會到作者對這座島嶼的感動，而更愛臺灣這塊土地。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-16 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000880', `image_url`='[]';
