INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99ba', '王國衍（Alif王教練）斜槓人生攝影個展', '以鳥類生態及昆蟲微距為主，人文、民俗風情、無人機空拍為輔。王國衍近年透過觀鳥，拍鳥，關注生態。113年4月前往東馬婆羅洲熱帶雨林，四十度高溫拍攝環境，冒著毒蛇、毒蠍、螞蝗叮咬之危險，記錄到數十餘種熱帶雨林顏色艶麗鮮明的鳥類，在此次攝影展覽中全數呈現！', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-29 00:00:00', '2025-04-16 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000881', '[]') ON DUPLICATE KEY UPDATE `activity_name`='王國衍（Alif王教練）斜槓人生攝影個展', `description`='以鳥類生態及昆蟲微距為主，人文、民俗風情、無人機空拍為輔。王國衍近年透過觀鳥，拍鳥，關注生態。113年4月前往東馬婆羅洲熱帶雨林，四十度高溫拍攝環境，冒著毒蛇、毒蠍、螞蝗叮咬之危險，記錄到數十餘種熱帶雨林顏色艶麗鮮明的鳥類，在此次攝影展覽中全數呈現！', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-16 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000881', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99bb', '韓湘琴的花花世界', '資深藝人韓湘琴近年畫作於形色虛實之間，氣韻自成一格，憑藉紮實底功呈現出自由奔放的線條，如水墨流動的生命盛宴，透過濃烈筆觸和大膽用色傳達獨特的美力哲學，獲得許多前輩先進和繪畫同好的共鳴。隨著不同的人生階段和體悟，筆下畫作也綻放出不同的光彩。沉澱自身的創作歷程，希望這次展出的墨彩畫及水墨瓷瓶新作能夠療癒並鼓舞人心，為不停變動的世界注入活力。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-29 00:00:00', '2025-04-16 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000882', '[]') ON DUPLICATE KEY UPDATE `activity_name`='韓湘琴的花花世界', `description`='資深藝人韓湘琴近年畫作於形色虛實之間，氣韻自成一格，憑藉紮實底功呈現出自由奔放的線條，如水墨流動的生命盛宴，透過濃烈筆觸和大膽用色傳達獨特的美力哲學，獲得許多前輩先進和繪畫同好的共鳴。隨著不同的人生階段和體悟，筆下畫作也綻放出不同的光彩。沉澱自身的創作歷程，希望這次展出的墨彩畫及水墨瓷瓶新作能夠療癒並鼓舞人心，為不停變動的世界注入活力。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-16 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000882', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99bc', '2025春秋美術學會第50屆92回大展', '網羅中部畫壇最傑出的藝術家，成為臺灣畫壇名聞遐邇的指標性重要畫會，展出類別有油畫、水彩、膠彩、複合媒材等。最難得的是個個成員都秉有非凡成就，秉持著楊啟東大師「人生晨露、藝術千秋」的座右銘，努力不懈的創作，風格獨特並各自發展出一片天。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-29 00:00:00', '2025-04-16 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000883', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025春秋美術學會第50屆92回大展', `description`='網羅中部畫壇最傑出的藝術家，成為臺灣畫壇名聞遐邇的指標性重要畫會，展出類別有油畫、水彩、膠彩、複合媒材等。最難得的是個個成員都秉有非凡成就，秉持著楊啟東大師「人生晨露、藝術千秋」的座右銘，努力不懈的創作，風格獨特並各自發展出一片天。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-16 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000883', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99bd', '石語的軌跡－生命旅程  張吉龍個展', '張吉龍老師的石雕以半抽象方式用人物或擬人作品去表現生活行為的情感或需求，讓觀賞者去感受不同角色裡的自己，感受人在歲月累積的生老過程，作為回顧與省思的觸感，雕塑作品延伸著故事性的特質，把生活上的痕跡記錄了下來，作品中也呈現著承先啟後的平凡寓意，令人會心，亦具大自然生生不息的循環理哲得其所悟。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-29 00:00:00', '2025-04-16 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000884', '[]') ON DUPLICATE KEY UPDATE `activity_name`='石語的軌跡－生命旅程  張吉龍個展', `description`='張吉龍老師的石雕以半抽象方式用人物或擬人作品去表現生活行為的情感或需求，讓觀賞者去感受不同角色裡的自己，感受人在歲月累積的生老過程，作為回顧與省思的觸感，雕塑作品延伸著故事性的特質，把生活上的痕跡記錄了下來，作品中也呈現著承先啟後的平凡寓意，令人會心，亦具大自然生生不息的循環理哲得其所悟。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-16 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000884', `image_url`='[]';
