INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99bf', '心相‧意象－王子維、林伯翰、戴裕峰陶塑創作三人聯展', '創作者王子維、林伯翰與戴裕峰三人師承張舒嵎，學習陶藝雕塑，善於捏塑人像主題，透過陶藝呈現人在生活場景中的情感連結，引領觀者細品日常情境下的真實互動。感受創作者的表現手法與內心世界，在「心相」與「意象」間揉捻著泥土，型塑每段生命經驗的寶貴時光。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-29 00:00:00', '2025-04-23 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000885', '[]') ON DUPLICATE KEY UPDATE `activity_name`='心相‧意象－王子維、林伯翰、戴裕峰陶塑創作三人聯展', `description`='創作者王子維、林伯翰與戴裕峰三人師承張舒嵎，學習陶藝雕塑，善於捏塑人像主題，透過陶藝呈現人在生活場景中的情感連結，引領觀者細品日常情境下的真實互動。感受創作者的表現手法與內心世界，在「心相」與「意象」間揉捻著泥土，型塑每段生命經驗的寶貴時光。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-23 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000885', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ab26b3240c403d99c0', '見山－黎世榮岩礦壺個展', '此次展出作品以臺灣苗栗三義的岩礦土為主。從挖土、練土、篩土、燒窯到作品的呈現，每一件作品中呈現的是堅持35年來的心路歷程。無非是～見山是山、見山不是山、見山還是山。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-29 00:00:00', '2025-04-23 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000886', '[]') ON DUPLICATE KEY UPDATE `activity_name`='見山－黎世榮岩礦壺個展', `description`='此次展出作品以臺灣苗栗三義的岩礦土為主。從挖土、練土、篩土、燒窯到作品的呈現，每一件作品中呈現的是堅持35年來的心路歷程。無非是～見山是山、見山不是山、見山還是山。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-23 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000886', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ac26b3240c403d99c1', '畫墨遊藝~臺中市榮美藝文傳承協會會員聯展', '臺中市榮美藝文傳承協會由一群對中華文化書畫藝術同好所共同籌組而成，每位成員均對書畫藝術抱持學習鑽研與喜愛的態度，廣結藝術善緣推動書畫藝術的社會活動，將藝文活動帶入生活傳承古人對書畫藝術的尊榮。\r\n本次參展作品都是創作者們努力透過筆觸毫端，展現平時用功精實練習不綴的成果，無論年齡資歷天份的高低，均秉持一份對藝術文化的熱愛，在作品中蘊育清新之氣，超塵脫俗各具不同韻致，或許以專業書畫家的角度來看尚有未逮之處，但以業餘的視野審視已是難能可貴。', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-02-22 00:00:00', '2025-03-16 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=ec90f67c5ea64fdd86983947716c9007', '[]') ON DUPLICATE KEY UPDATE `activity_name`='畫墨遊藝~臺中市榮美藝文傳承協會會員聯展', `description`='臺中市榮美藝文傳承協會由一群對中華文化書畫藝術同好所共同籌組而成，每位成員均對書畫藝術抱持學習鑽研與喜愛的態度，廣結藝術善緣推動書畫藝術的社會活動，將藝文活動帶入生活傳承古人對書畫藝術的尊榮。\r\n本次參展作品都是創作者們努力透過筆觸毫端，展現平時用功精實練習不綴的成果，無論年齡資歷天份的高低，均秉持一份對藝術文化的熱愛，在作品中蘊育清新之氣，超塵脫俗各具不同韻致，或許以專業書畫家的角度來看尚有未逮之處，但以業餘的視野審視已是難能可貴。', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=ec90f67c5ea64fdd86983947716c9007', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ac26b3240c403d99c2', '街頭藝人演出(114年3月)', '清水廣場3月1日 10：00-13：00  阿寶 薩克斯風演奏、造型氣球\r\n清水廣場3月2日 10：00-14：00  阿寶 薩克斯風演奏、造型氣球\r\n清水廣場 3月1。15。16。22。23。29。30日 14：00  楊桑 吉他彈唱\r\n清水廣場 3月2日 11：00-16：00  手染布手作紡紗織布藝品、種子創作、陶瓷彩繪', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Activity/Activity_More?id=308aeeaccac04b128b15512015e36cd3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='街頭藝人演出(114年3月)', `description`='清水廣場3月1日 10：00-13：00  阿寶 薩克斯風演奏、造型氣球\r\n清水廣場3月2日 10：00-14：00  阿寶 薩克斯風演奏、造型氣球\r\n清水廣場 3月1。15。16。22。23。29。30日 14：00  楊桑 吉他彈唱\r\n清水廣場 3月2日 11：00-16：00  手染布手作紡紗織布藝品、種子創作、陶瓷彩繪', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Activity/Activity_More?id=308aeeaccac04b128b15512015e36cd3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ac26b3240c403d99c3', '3月高雄市電影館｜長短腳電影院—小小世界Life秀【普遍級】', '3月｜長短腳電影院—小小世界Life秀\r\n在我們都看不見的迷你世界裡，原來還藏著大大的宇宙！這裡的居民也像我們一樣充滿生命力，跳舞歌唱、追逐著四季變化。也會用意想不到的方式，與我們世界的你我互動溝通！更令人驚奇的是，迷你城市裡還可以繼續向下探索，潛入更小的微觀宇宙！本單元用童趣的視角來觀察我們平常都忽略的微物世界觀，以天馬行空的創意架構我們不曾見過的小小世界。\r\n\r\n普遍級｜適合3歲以上兒童觀賞｜單元片長36min｜無對白\r\n\r\n▶ 點我下載精彩節目冊 ◀\r\n　(連結：https://reurl.cc/2670dn )\r\n\r\n【3/9親子活動：故事童樂劇場】\r\n活動講師：小強老師｜腹語藝術老師', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-03-09 00:00:00', '2025-03-29 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '節目票+120;活動票+200', 'https://www.nwac.org.tw/tw/movies-list', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月高雄市電影館｜長短腳電影院—小小世界Life秀【普遍級】', `description`='3月｜長短腳電影院—小小世界Life秀\r\n在我們都看不見的迷你世界裡，原來還藏著大大的宇宙！這裡的居民也像我們一樣充滿生命力，跳舞歌唱、追逐著四季變化。也會用意想不到的方式，與我們世界的你我互動溝通！更令人驚奇的是，迷你城市裡還可以繼續向下探索，潛入更小的微觀宇宙！本單元用童趣的視角來觀察我們平常都忽略的微物世界觀，以天馬行空的創意架構我們不曾見過的小小世界。\r\n\r\n普遍級｜適合3歲以上兒童觀賞｜單元片長36min｜無對白\r\n\r\n▶ 點我下載精彩節目冊 ◀\r\n　(連結：https://reurl.cc/2670dn )\r\n\r\n【3/9親子活動：故事童樂劇場】\r\n活動講師：小強老師｜腹語藝術老師', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='節目票+120;活動票+200', `source_url`='https://www.nwac.org.tw/tw/movies-list', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ae26b3240c403d99c4', '善美真華德福教育戲劇公演 蝴蝶戀人-梁祝', '清水在地耕耘多年的善美真華德福教育，繼2020年藝術祭「屋頂上的提琴手」音樂劇，這次帶來膾炙人口的中國經典愛情故事~蝴蝶戀人:梁祝。\r\n劇中結合了話劇、黃梅調、中西樂演奏和現代舞蹈之多元表演藝術，演員們不只在台前演出還親自製作戲服，並兼任許多幕後工作。\r\n演員們正好是正值二八年華的國三、高一的學生，他們會如何詮釋這齣古典的愛情故事? 敬請大家進來演藝廳一同觀賞。\r\n', '華德福大地實驗教育機構', '臺中市清水區忠貞路21號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '全票+50', 'https://tcsac.taichung.gov.tw/PerformingArts/Performing_More?id=46ad6c754ff74f0e85297bb21d02f052', '[]') ON DUPLICATE KEY UPDATE `activity_name`='善美真華德福教育戲劇公演 蝴蝶戀人-梁祝', `description`='清水在地耕耘多年的善美真華德福教育，繼2020年藝術祭「屋頂上的提琴手」音樂劇，這次帶來膾炙人口的中國經典愛情故事~蝴蝶戀人:梁祝。\r\n劇中結合了話劇、黃梅調、中西樂演奏和現代舞蹈之多元表演藝術，演員們不只在台前演出還親自製作戲服，並兼任許多幕後工作。\r\n演員們正好是正值二八年華的國三、高一的學生，他們會如何詮釋這齣古典的愛情故事? 敬請大家進來演藝廳一同觀賞。\r\n', `organizer`='華德福大地實驗教育機構', `address`='臺中市清水區忠貞路21號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='全票+50', `source_url`='https://tcsac.taichung.gov.tw/PerformingArts/Performing_More?id=46ad6c754ff74f0e85297bb21d02f052', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ae26b3240c403d99c5', '3月高雄市電影館｜艾諾拉 Anora【限制級】', '《歡迎光臨奇幻城堡》西恩貝克登頂坎城，力指奧斯卡 \r\n\r\n來自布魯克林的脫衣舞孃艾諾拉，在俱樂部遇見來美國度假的俄國富二代伊凡，深深為艾諾拉著迷的伊凡，在她一週的陪伴後衝動結婚。當這個消息傳回俄羅斯時，怒不可遏的伊凡父母決定對這段婚姻強硬喊停，艾諾拉眼看「飛上枝頭當鳳凰」的美夢就要畫下句點，決定拿出嗆辣本事，抗爭到底！', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-03-01 00:00:00', '2025-03-08 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;享兒童優惠票+208;全票+260', 'https://www.nwac.org.tw/tw/movie-showings', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月高雄市電影館｜艾諾拉 Anora【限制級】', `description`='《歡迎光臨奇幻城堡》西恩貝克登頂坎城，力指奧斯卡 \r\n\r\n來自布魯克林的脫衣舞孃艾諾拉，在俱樂部遇見來美國度假的俄國富二代伊凡，深深為艾諾拉著迷的伊凡，在她一週的陪伴後衝動結婚。當這個消息傳回俄羅斯時，怒不可遏的伊凡父母決定對這段婚姻強硬喊停，艾諾拉眼看「飛上枝頭當鳳凰」的美夢就要畫下句點，決定拿出嗆辣本事，抗爭到底！', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;享兒童優惠票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movie-showings', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ae26b3240c403d99c6', '悅讀曉天下書展(外展)', '慈興文教基金會配合政府辦理舉辦各項研習及修行活動，在上楓分館固定有讀經班活動。\r\n展出主題:悅讀曉天下\r\n展出時間:114/1/16～2/28\r\n展出地點:台中市梧棲區中華路一段160號\r\n展出對象:國小生\r\n展出內容:各式詩詞，經典古文新讀，中英文兒童繪本，多樣科學藝術書籍供大家現場閱讀，書展層次豐富，吸引學童目光！', '臺中市立圖書館上楓分館', '臺中市梧棲區', '2025-01-16 00:00:00', '2025-02-28 00:00:00', '梧棲區（臺中市）=', 24.24552431, 120.5301259, '無資料', 'https://reurl.cc/M6Q3mK', '[]') ON DUPLICATE KEY UPDATE `activity_name`='悅讀曉天下書展(外展)', `description`='慈興文教基金會配合政府辦理舉辦各項研習及修行活動，在上楓分館固定有讀經班活動。\r\n展出主題:悅讀曉天下\r\n展出時間:114/1/16～2/28\r\n展出地點:台中市梧棲區中華路一段160號\r\n展出對象:國小生\r\n展出內容:各式詩詞，經典古文新讀，中英文兒童繪本，多樣科學藝術書籍供大家現場閱讀，書展層次豐富，吸引學童目光！', `organizer`='臺中市立圖書館上楓分館', `address`='臺中市梧棲區', `start_date`='2025-01-16 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='梧棲區（臺中市）=', `latitude`=24.24552431, `longitude`=120.5301259, `ticket_price`='無資料', `source_url`='https://reurl.cc/M6Q3mK', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23af26b3240c403d99c7', '3月高雄市電影館｜吸血鬼：諾斯費拉圖  Nosferatu【輔15級】', '「站在我面前的就是死神，但我未曾如此快樂過。」 \r\n\r\n羅柏艾格斯自編自導，再現招牌哥德式驚悚。《吸血鬼：諾斯費拉圖》翻拍自1922年德國無聲電影，講述了一個被鬼附身的年輕女子和迷戀她的可怕吸血鬼之間的癡戀，當她的靈魂慢慢被「吸血鬼」諾斯費拉圖誘惑，最終屈服於他黑暗中的邪惡輪廓。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-03-01 00:00:00', '2025-03-20 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;全票+260', 'https://www.nwac.org.tw/tw/movies-list', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月高雄市電影館｜吸血鬼：諾斯費拉圖  Nosferatu【輔15級】', `description`='「站在我面前的就是死神，但我未曾如此快樂過。」 \r\n\r\n羅柏艾格斯自編自導，再現招牌哥德式驚悚。《吸血鬼：諾斯費拉圖》翻拍自1922年德國無聲電影，講述了一個被鬼附身的年輕女子和迷戀她的可怕吸血鬼之間的癡戀，當她的靈魂慢慢被「吸血鬼」諾斯費拉圖誘惑，最終屈服於他黑暗中的邪惡輪廓。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-20 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23af26b3240c403d99c8', '3月高雄市電影館｜喵的奇幻漂流	Flow【普通級】', '奧斯卡金獎名導吉勒摩戴托羅盛讚 獲獎無數年度必看動畫\r\n\r\n★ 2024 安錫國際動畫影展 評審團獎、最佳原創音樂獎\r\n★ 2025 金球獎 最佳動畫長片獎\r\n\r\n當世界即將走向末日，卻充斥著人類存在的痕跡。而當一隻黑貓的家園被大洪水摧毀後，登上一艘小船當作它的避難所，但卻發現船上住著各式各樣的動物，儘管他們無法溝通，但它們仍必須合作，穿梭於神秘的漂流世界，面對各種挑戰和危險。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-03-01 00:00:00', '2025-03-08 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優惠票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月高雄市電影館｜喵的奇幻漂流	Flow【普通級】', `description`='奧斯卡金獎名導吉勒摩戴托羅盛讚 獲獎無數年度必看動畫\r\n\r\n★ 2024 安錫國際動畫影展 評審團獎、最佳原創音樂獎\r\n★ 2025 金球獎 最佳動畫長片獎\r\n\r\n當世界即將走向末日，卻充斥著人類存在的痕跡。而當一隻黑貓的家園被大洪水摧毀後，登上一艘小船當作它的避難所，但卻發現船上住著各式各樣的動物，儘管他們無法溝通，但它們仍必須合作，穿梭於神秘的漂流世界，面對各種挑戰和危險。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優惠票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23af26b3240c403d99c9', '3月高雄市電影館｜劇場版派遣女醫 X FINAL Doctor X: The Movie【輔12級】', '所有角色全數回歸 大門未知子登上大銀幕華麗謝幕！\r\n\r\n由米倉涼子主演的國民級話題神劇《派遣女醫X》自2012年開始播出至今，終於迎來最終章，前所未有的危機即將降臨，「從來不會失敗」的外科醫生大門未知子該如何應對？同時，他未知的過去也即將被解開。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-03-01 00:00:00', '2025-03-13 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優惠票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月高雄市電影館｜劇場版派遣女醫 X FINAL Doctor X: The Movie【輔12級】', `description`='所有角色全數回歸 大門未知子登上大銀幕華麗謝幕！\r\n\r\n由米倉涼子主演的國民級話題神劇《派遣女醫X》自2012年開始播出至今，終於迎來最終章，前所未有的危機即將降臨，「從來不會失敗」的外科醫生大門未知子該如何應對？同時，他未知的過去也即將被解開。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-13 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優惠票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23af26b3240c403d99ca', '3月高雄市電影館｜火線追緝令  Se7en【輔12級】', '大衛芬奇驚悚犯罪代表作 30周年4K修復經典重映\r\n\r\n★ 1996 奧斯卡金像獎 最佳剪輯獎提名\r\n\r\n一位即將退休的警探和他的接任者，合作調查由宗教儀式「七大罪」布局之連環謀殺案，他們試圖在兇手成功謀殺七名受害者前緝拿他歸案，然而事實的真相以及人性黑暗面讓他們難以承受。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月高雄市電影館｜火線追緝令  Se7en【輔12級】', `description`='大衛芬奇驚悚犯罪代表作 30周年4K修復經典重映\r\n\r\n★ 1996 奧斯卡金像獎 最佳剪輯獎提名\r\n\r\n一位即將退休的警探和他的接任者，合作調查由宗教儀式「七大罪」布局之連環謀殺案，他們試圖在兇手成功謀殺七名受害者前緝拿他歸案，然而事實的真相以及人性黑暗面讓他們難以承受。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23af26b3240c403d99cb', '3月高雄市電影館｜粗獷派建築師 The Brutalist【輔12級】', '《戰地琴人》安卓亞布洛迪 強勢橫掃各大影展\r\n★ 2024 威尼斯影展 最佳導演獎\r\n★ 2025 金球獎 戲劇類最佳影片、導演、男主角獎 提名\r\n\r\n富有遠見的建築師拉斯洛托特在戰後逃離歐洲，來到美國重建他的生活、工作，以及他與妻子艾莉莎貝的婚姻生活，在戰爭期間，兩人由於邊境和政權的變化一度被迫分開。在這陌生的新國度，拉斯洛定居在賓州，知名富商哈里森李范布倫相當欣賞他的建築才華，然而權力和機會需要付出沉重的代價。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-03-01 00:00:00', '2025-03-26 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月高雄市電影館｜粗獷派建築師 The Brutalist【輔12級】', `description`='《戰地琴人》安卓亞布洛迪 強勢橫掃各大影展\r\n★ 2024 威尼斯影展 最佳導演獎\r\n★ 2025 金球獎 戲劇類最佳影片、導演、男主角獎 提名\r\n\r\n富有遠見的建築師拉斯洛托特在戰後逃離歐洲，來到美國重建他的生活、工作，以及他與妻子艾莉莎貝的婚姻生活，在戰爭期間，兩人由於邊境和政權的變化一度被迫分開。在這陌生的新國度，拉斯洛定居在賓州，知名富商哈里森李范布倫相當欣賞他的建築才華，然而權力和機會需要付出沉重的代價。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23af26b3240c403d99cc', '3月高雄市電影館｜夜校女生 The Uniform【普遍級】', '「日校是太陽，夜校是月亮。」\r\n\r\n1997年，小愛（陳姸霏 飾）在升學壓力下進入體制特殊的「一女中夜校」就讀。但夜校生總被認為不如日校生優秀，造成她極度自卑。她與日校好友敏敏（項婕如 飾）一起喜歡上男校的資優生路克（邱以太 飾），持續假冒成日校生，並把自己推向巨大的謊言坑洞，直到謊言被揭穿。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-03-02 00:00:00', '2025-03-23 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月高雄市電影館｜夜校女生 The Uniform【普遍級】', `description`='「日校是太陽，夜校是月亮。」\r\n\r\n1997年，小愛（陳姸霏 飾）在升學壓力下進入體制特殊的「一女中夜校」就讀。但夜校生總被認為不如日校生優秀，造成她極度自卑。她與日校好友敏敏（項婕如 飾）一起喜歡上男校的資優生路克（邱以太 飾），持續假冒成日校生，並把自己推向巨大的謊言坑洞，直到謊言被揭穿。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23af26b3240c403d99cd', '3月高雄市電影館｜辛辛監獄劇團 Sing Sing【保護級】', '監獄的冷牆鎖不住希望 實力派演員與真實獄友最觸動人心的演出\r\n\r\n★ 2025 奧斯卡金像獎 最佳男主角、改編劇本、歌曲獎 提名\r\n\r\n藝術能否改變人生？紐約州辛辛監獄內，一位熱愛戲劇的囚犯導演發起並指導了一齣舞台劇。而當新囚犯加入團隊，他們也因性格與過往產生強烈碰撞，眾夥該如何建立起友誼和信任？伴隨劇目排練進行，他們將透過舞台重捨尊嚴以及希望，並對自由和人性間提出深刻詰問。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-03-06 00:00:00', '2025-03-13 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月高雄市電影館｜辛辛監獄劇團 Sing Sing【保護級】', `description`='監獄的冷牆鎖不住希望 實力派演員與真實獄友最觸動人心的演出\r\n\r\n★ 2025 奧斯卡金像獎 最佳男主角、改編劇本、歌曲獎 提名\r\n\r\n藝術能否改變人生？紐約州辛辛監獄內，一位熱愛戲劇的囚犯導演發起並指導了一齣舞台劇。而當新囚犯加入團隊，他們也因性格與過往產生強烈碰撞，眾夥該如何建立起友誼和信任？伴隨劇目排練進行，他們將透過舞台重捨尊嚴以及希望，並對自由和人性間提出深刻詰問。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-03-06 00:00:00', `end_date`='2025-03-13 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b026b3240c403d99ce', '假日廣場-鼓手道館｜爵士鼓發表會', '鼓手道館｜爵士鼓發表會\r\n炎炎午後，是時候來點振奮人心的音樂了，無論大小朋友，都能感受從我們的爵士鼓合奏中感受到音樂的魅力與鼓點的動感，多首經典好歌，誠摯邀請各位前來觀賞，與我們一同享受這場音樂盛宴！當天跟大家約定好，下午見囉！\r\n', '鼓手道館', '臺南市東區中華東路三段332號', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='假日廣場-鼓手道館｜爵士鼓發表會', `description`='鼓手道館｜爵士鼓發表會\r\n炎炎午後，是時候來點振奮人心的音樂了，無論大小朋友，都能感受從我們的爵士鼓合奏中感受到音樂的魅力與鼓點的動感，多首經典好歌，誠摯邀請各位前來觀賞，與我們一同享受這場音樂盛宴！當天跟大家約定好，下午見囉！\r\n', `organizer`='鼓手道館', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b026b3240c403d99cf', '蝶夢璀璨－透視光影變奏', '本次展覽「蝶夢璀璨－透視光影變奏」融合莊子的哲學理念與現代藝術創作，以玻璃為主要媒材，透過藝術的多元形式詮釋，重新探討夢境與現實之間的模糊界線，並展開一場視覺與心靈的對話，探索生命的真實與幻象、轉變與對立。邀請曾俊豪、真真鑲嵌玻璃研究所 X DDD ceramics、走路草農/藝團及李吉祥等4組藝術家透過對玻璃的多樣性運用與形象的轉換，展現莊子哲思的現代化詮釋。', '新竹市文化局', '新竹市東區東大路一段2號', '2025-01-01 00:00:00', '2025-04-13 00:00:00', '新竹市玻璃工藝博物館', 24.8012033, 120.9781361, '全票+50;優待票+30', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蝶夢璀璨－透視光影變奏', `description`='本次展覽「蝶夢璀璨－透視光影變奏」融合莊子的哲學理念與現代藝術創作，以玻璃為主要媒材，透過藝術的多元形式詮釋，重新探討夢境與現實之間的模糊界線，並展開一場視覺與心靈的對話，探索生命的真實與幻象、轉變與對立。邀請曾俊豪、真真鑲嵌玻璃研究所 X DDD ceramics、走路草農/藝團及李吉祥等4組藝術家透過對玻璃的多樣性運用與形象的轉換，展現莊子哲思的現代化詮釋。', `organizer`='新竹市文化局', `address`='新竹市東區東大路一段2號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='新竹市玻璃工藝博物館', `latitude`=24.8012033, `longitude`=120.9781361, `ticket_price`='全票+50;優待票+30', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b426b3240c403d99d1', '吳燕卿攝影展•手機漫遊嘉南', '有鑑於智慧型手機的普遍化，手機的功能增強，攝影拍照畫素提升，方便性符合一般民眾的需求，透過手機走到哪就拍，嘉南許多秘境，持續發掘出來，是吳燕卿老師這次展覽的主題。 ', '臺南市政府秘書處', '臺南市新營區民治路36號', '2025-03-03 00:00:00', '2025-03-28 00:00:00', '臺南市民治市政中心', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='吳燕卿攝影展•手機漫遊嘉南', `description`='有鑑於智慧型手機的普遍化，手機的功能增強，攝影拍照畫素提升，方便性符合一般民眾的需求，透過手機走到哪就拍，嘉南許多秘境，持續發掘出來，是吳燕卿老師這次展覽的主題。 ', `organizer`='臺南市政府秘書處', `address`='臺南市新營區民治路36號', `start_date`='2025-03-03 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='臺南市民治市政中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b426b3240c403d99d2', '「天上人間—王美玥創作40年回顧展」藝術家導覽活動', '藝術家王美玥在1994年創立的「洗墨法」，突破傳統水墨的表現界限，結合宣紙與描圖紙創作出獨特的水波紋畫，這一項創新技法在當代水墨畫中嶄露頭角。透過這些作品，王老師將自然景物與哲學思考、歷史溯源與文學視角融合，賦予每一幅畫作以深刻的文化內涵與時代印記。\r\n\r\n此次展覽不僅呈現了藝術家對不同媒材的探索與實踐，更體現了她在心靈層次與技法上的不斷創新，傳遞著她對生命、藝術與世界的深刻感悟。\r\n\r\n本場活動，將由藝術家親自導覽介紹作品，歡迎對藝術有興趣的朋友，讓我們一同走進王美玥老師的藝術世界，開啟一場思想與美學的對話之旅。\r\n\r\n \r\n\r\n時間: 114年3月1日上午10點30分至11點30分\r\n地點: 臺中市港區藝術中心掬月廳\r\n年齡:一般民眾\r\n*免費、自由參加，無須報名', '臺中市政府文化局', '臺中市清水區忠貞路21號', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Activity/Activity_More?id=ee64f638742d4d08b46cd9f81ec0ad90', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「天上人間—王美玥創作40年回顧展」藝術家導覽活動', `description`='藝術家王美玥在1994年創立的「洗墨法」，突破傳統水墨的表現界限，結合宣紙與描圖紙創作出獨特的水波紋畫，這一項創新技法在當代水墨畫中嶄露頭角。透過這些作品，王老師將自然景物與哲學思考、歷史溯源與文學視角融合，賦予每一幅畫作以深刻的文化內涵與時代印記。\r\n\r\n此次展覽不僅呈現了藝術家對不同媒材的探索與實踐，更體現了她在心靈層次與技法上的不斷創新，傳遞著她對生命、藝術與世界的深刻感悟。\r\n\r\n本場活動，將由藝術家親自導覽介紹作品，歡迎對藝術有興趣的朋友，讓我們一同走進王美玥老師的藝術世界，開啟一場思想與美學的對話之旅。\r\n\r\n \r\n\r\n時間: 114年3月1日上午10點30分至11點30分\r\n地點: 臺中市港區藝術中心掬月廳\r\n年齡:一般民眾\r\n*免費、自由參加，無須報名', `organizer`='臺中市政府文化局', `address`='臺中市清水區忠貞路21號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Activity/Activity_More?id=ee64f638742d4d08b46cd9f81ec0ad90', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b426b3240c403d99d3', '《2024-25今日畫會•今日畫展》 創作導覽', '今日畫會提供作品包括油畫、壓克力、水彩、水墨、版畫和複合媒材。畫會成員現場解說作品表達藝術觀點，探討和發揚當今臺灣的美好與價值，以分享創作經驗與民眾相互交流。', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Activity/Activity_More?id=8d1b8b3516f1450a9bb5da3c3d7954e4', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2024-25今日畫會•今日畫展》 創作導覽', `description`='今日畫會提供作品包括油畫、壓克力、水彩、水墨、版畫和複合媒材。畫會成員現場解說作品表達藝術觀點，探討和發揚當今臺灣的美好與價值，以分享創作經驗與民眾相互交流。', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Activity/Activity_More?id=8d1b8b3516f1450a9bb5da3c3d7954e4', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b426b3240c403d99d4', '114日本演歌藝文推廣活動', '日本演歌藝術講座內容包演歌的起源與發展、演歌與日本文化的關聯、唱腔與發聲技巧、情感表達與舞台演出及日語發音與語感掌握，屬於跨文化的音樂交流。', '桃園市桃園區公所', '桃園市桃園區', '2025-02-06 00:00:00', '2025-03-27 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114日本演歌藝文推廣活動', `description`='日本演歌藝術講座內容包演歌的起源與發展、演歌與日本文化的關聯、唱腔與發聲技巧、情感表達與舞台演出及日語發音與語感掌握，屬於跨文化的音樂交流。', `organizer`='桃園市桃園區公所', `address`='桃園市桃園區', `start_date`='2025-02-06 00:00:00', `end_date`='2025-03-27 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b526b3240c403d99d5', '【梧棲巧藝】 徐碧姿老師結藝創作展', '徐碧姿老師創作膠彩畫多年，參加比賽屢獲佳績，成為獨有技法專業領域之藝術家，作品畫面常用多色打底、流動、霧吹、積滯、貼箔…等各類技法在畫面中，營造空間與物件和諧與層次感。閒暇時喜歡織作中國結，發現傳統結藝編織技藝漸漸式微，便嘗試帶入結藝編織元素，進一步提升創作廣度。\r\n本次特別安排於臺中市藝術亮點鰲西藝廊展出，與民眾分享歷年來的作品，藉由多種素材將美感傳遞。', '梧棲行旅', '臺中市梧棲區', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '梧棲區（臺中市）=', 24.24552431, 120.5301259, '無資料', 'https://www.facebook.com/share/p/15wxqDT5eE/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【梧棲巧藝】 徐碧姿老師結藝創作展', `description`='徐碧姿老師創作膠彩畫多年，參加比賽屢獲佳績，成為獨有技法專業領域之藝術家，作品畫面常用多色打底、流動、霧吹、積滯、貼箔…等各類技法在畫面中，營造空間與物件和諧與層次感。閒暇時喜歡織作中國結，發現傳統結藝編織技藝漸漸式微，便嘗試帶入結藝編織元素，進一步提升創作廣度。\r\n本次特別安排於臺中市藝術亮點鰲西藝廊展出，與民眾分享歷年來的作品，藉由多種素材將美感傳遞。', `organizer`='梧棲行旅', `address`='臺中市梧棲區', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='梧棲區（臺中市）=', `latitude`=24.24552431, `longitude`=120.5301259, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/15wxqDT5eE/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b526b3240c403d99d6', '114年度喜迎新春歌唱秀', '邀請歌手透過民歌表演，讓不同年齡層的市民欣賞民歌演唱與樂器伴奏，深化音樂教育，民歌表演歌曲為茉莉花、我只在乎你、龍的傳人、小雨中的回憶等等多首膾炙人口的經典歌曲，因民歌旋律簡單易學，適合群眾參與，表演活動地點位於桃園區田川餐廳，可供一般民眾自由進入欣賞，讓音樂成為大眾日常生活的一部分。', '桃園市桃園區公所', '桃園市桃園區', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度喜迎新春歌唱秀', `description`='邀請歌手透過民歌表演，讓不同年齡層的市民欣賞民歌演唱與樂器伴奏，深化音樂教育，民歌表演歌曲為茉莉花、我只在乎你、龍的傳人、小雨中的回憶等等多首膾炙人口的經典歌曲，因民歌旋律簡單易學，適合群眾參與，表演活動地點位於桃園區田川餐廳，可供一般民眾自由進入欣賞，讓音樂成為大眾日常生活的一部分。', `organizer`='桃園市桃園區公所', `address`='桃園市桃園區', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b526b3240c403d99d7', '【2025台文系列講座】 Thiaⁿ kò͘-sū台語繪本說故事2', '高雄文學館自2020年開始與在地台語推廣社團「打狗台語文促進協會」合作，結合在地台語社團活力，帶動高雄在地台語文學之推廣以及母語學習。\r\n\r\n【做夥聽故事──Thiaⁿ kò͘-sū台語繪本說故事】\r\n以孩童、親子及家庭為對象，舉辦三場說故事活動，邀請作者本人以台語朗讀說故事。\r\n\r\n第二場\r\n時間｜4/26(六)15:00-16:00\r\n講師｜林小杯\r\n讀本｜《大稻埕動物園》（2022，是路故事）、《喀噠喀達喀噠》（2020，步步）\r\n\r\n', '高雄市立圖書館總館', '高雄市前金區24鄰民生二路39號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '高雄市立圖書館高雄文學館', 22.625524, 120.298017, '無資料', 'https://www.facebook.com/ksliterary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025台文系列講座】 Thiaⁿ kò͘-sū台語繪本說故事2', `description`='高雄文學館自2020年開始與在地台語推廣社團「打狗台語文促進協會」合作，結合在地台語社團活力，帶動高雄在地台語文學之推廣以及母語學習。\r\n\r\n【做夥聽故事──Thiaⁿ kò͘-sū台語繪本說故事】\r\n以孩童、親子及家庭為對象，舉辦三場說故事活動，邀請作者本人以台語朗讀說故事。\r\n\r\n第二場\r\n時間｜4/26(六)15:00-16:00\r\n講師｜林小杯\r\n讀本｜《大稻埕動物園》（2022，是路故事）、《喀噠喀達喀噠》（2020，步步）\r\n\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市前金區24鄰民生二路39號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄市立圖書館高雄文學館', `latitude`=22.625524, `longitude`=120.298017, `ticket_price`='無資料', `source_url`='https://www.facebook.com/ksliterary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b526b3240c403d99d8', '走出校園、文化to go─臺南水道遺產與近代生活–依仁國小', '全國最大、也是唯一水利設施國定古蹟的水道博物館，完成於日治時期，也是臺南開始有潔淨民生用水的重要里程碑，見證臺灣現代化發展過程。究竟水道有什麼厲害的地方、為什麼有必要性、為現代社會帶來什麼影響呢、又有哪些引人入勝的故事？是時候走一遭了！', '臺南市政府文化局', '臺南市山上區山上16號', '2025-03-04 00:00:00', '2025-03-04 00:00:00', '臺南山上花園水道博物館', 23.09689329, 120.370977, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='走出校園、文化to go─臺南水道遺產與近代生活–依仁國小', `description`='全國最大、也是唯一水利設施國定古蹟的水道博物館，完成於日治時期，也是臺南開始有潔淨民生用水的重要里程碑，見證臺灣現代化發展過程。究竟水道有什麼厲害的地方、為什麼有必要性、為現代社會帶來什麼影響呢、又有哪些引人入勝的故事？是時候走一遭了！', `organizer`='臺南市政府文化局', `address`='臺南市山上區山上16號', `start_date`='2025-03-04 00:00:00', `end_date`='2025-03-04 00:00:00', `location`='臺南山上花園水道博物館', `latitude`=23.09689329, `longitude`=120.370977, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b526b3240c403d99d9', '走出校園、文化to go─全糖路線––在蕭壠看見臺南生活-安慶國小', '臺南的歷史教室由工業遺址的蕭壠文化園區為起點，搭配南科考古館，從日治時期糖業發展、當代藝術實驗基地推展至臺灣史前文化，讓學童從觀察周遭生活環境開始、學習表達自我感受，引導並培養孩童對於藝術、文化歷史的感知與興趣，提供學子美學與文化兼具的知性之旅。', '臺南市政府文化局', '臺南市佳里區六安130號', '2025-03-14 00:00:00', '2025-03-14 00:00:00', '臺南市蕭壠文化園區', 23.1669941, 120.178593, '依活動而定+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='走出校園、文化to go─全糖路線––在蕭壠看見臺南生活-安慶國小', `description`='臺南的歷史教室由工業遺址的蕭壠文化園區為起點，搭配南科考古館，從日治時期糖業發展、當代藝術實驗基地推展至臺灣史前文化，讓學童從觀察周遭生活環境開始、學習表達自我感受，引導並培養孩童對於藝術、文化歷史的感知與興趣，提供學子美學與文化兼具的知性之旅。', `organizer`='臺南市政府文化局', `address`='臺南市佳里區六安130號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-14 00:00:00', `location`='臺南市蕭壠文化園區', `latitude`=23.1669941, `longitude`=120.178593, `ticket_price`='依活動而定+--', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b626b3240c403d99da', '林澄博士藝術講座：轉古鑄今「話」臺灣', '台中市墨緣雅集畫會為推動美感教育與提升藝術欣賞素養，特別邀請林澄博士舉辦藝術講座，以「轉古鑄今『話』臺灣」為題，分享三個創作系列：《順風相送》探討從「岱員」到大航海時代的臺灣史；《海上的島》敘述霧峰林家開臺祖林石的歷史故事；《展開城市》則從在地視角描繪城市景觀，歡迎對藝術欣賞與創作有興趣的民眾參加。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000698', '[]') ON DUPLICATE KEY UPDATE `activity_name`='林澄博士藝術講座：轉古鑄今「話」臺灣', `description`='台中市墨緣雅集畫會為推動美感教育與提升藝術欣賞素養，特別邀請林澄博士舉辦藝術講座，以「轉古鑄今『話』臺灣」為題，分享三個創作系列：《順風相送》探討從「岱員」到大航海時代的臺灣史；《海上的島》敘述霧峰林家開臺祖林石的歷史故事；《展開城市》則從在地視角描繪城市景觀，歡迎對藝術欣賞與創作有興趣的民眾參加。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000698', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b626b3240c403d99db', '徐璽豐吉他彈唱', '1.吉他現場彈唱(中 日 英語 歌曲)\r\n2.與現場民眾良好互動', '徐璽豐', '臺中市西區英才路600號', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://lurl.cc/jho4sm', '[]') ON DUPLICATE KEY UPDATE `activity_name`='徐璽豐吉他彈唱', `description`='1.吉他現場彈唱(中 日 英語 歌曲)\r\n2.與現場民眾良好互動', `organizer`='徐璽豐', `address`='臺中市西區英才路600號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://lurl.cc/jho4sm', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b826b3240c403d99dc', '展開.刻印.人生旅程 高春英版畫個展/國立新竹生活美學館', '展覽簡述-\r\n\r\n版畫創作可以說是一種結合繪畫、雕刻、設計、印刷的獨特風格藝術。\r\n\r\n版畫透過製版再印製出作品，其間接性的壓印行為產生其無可取代的趣味與美感。某些程度的不可預測性帶來的緊張與驚喜像極了人生。\r\n\r\n版畫的複數性使他成為一種可以分享與廣泛交流的藝術。也是最能充分利用在日常生活的藝術。仔細想想與觀察，日常生活中食衣住行處處可見版畫技巧的應用。\r\n\r\n在我的作品中，構圖上採用紙盒攤展開的形象，亦或是幾何切割的畫面。\r\n\r\n不同階段收納的紙盒承載著不同事件的情感記憶。展開的紙盒恰如其分的方寸，是宇宙能量的定律。人生是在這恰如其分的宇宙中的一場旅程，在頭尾不變的定律裡，我們在中間經歷著人生的悲歡離合生老病死。\r\n\r\n創作的思緒從個人記憶到生活堆積，從飼養種植到標本製成。生命中的大大小小，碰撞擷取美好的片段，延伸出新的療癒意象。完整的真實是眾多片段的組合，片段切割的畫面，真實與虛幻，現實與潛意識，變與不變。人生取決在於自身的中心思想意志，環境不會改變，解決之道在於改變自己。在作品中，思考、成長、完滿我的人生。', '國立新竹生活美學館', '新竹市東區武昌街110號', '2025-03-05 00:00:00', '2025-03-25 00:00:00', '國立新竹生活美學館', 24.8033334, 120.9673139, '無資料', 'https://event.culture.tw/mocweb/reg/NHCLAC/Detail.init.ctr?actId=50074&utm_source=moc&utm_medium=ind', '[]') ON DUPLICATE KEY UPDATE `activity_name`='展開.刻印.人生旅程 高春英版畫個展/國立新竹生活美學館', `description`='展覽簡述-\r\n\r\n版畫創作可以說是一種結合繪畫、雕刻、設計、印刷的獨特風格藝術。\r\n\r\n版畫透過製版再印製出作品，其間接性的壓印行為產生其無可取代的趣味與美感。某些程度的不可預測性帶來的緊張與驚喜像極了人生。\r\n\r\n版畫的複數性使他成為一種可以分享與廣泛交流的藝術。也是最能充分利用在日常生活的藝術。仔細想想與觀察，日常生活中食衣住行處處可見版畫技巧的應用。\r\n\r\n在我的作品中，構圖上採用紙盒攤展開的形象，亦或是幾何切割的畫面。\r\n\r\n不同階段收納的紙盒承載著不同事件的情感記憶。展開的紙盒恰如其分的方寸，是宇宙能量的定律。人生是在這恰如其分的宇宙中的一場旅程，在頭尾不變的定律裡，我們在中間經歷著人生的悲歡離合生老病死。\r\n\r\n創作的思緒從個人記憶到生活堆積，從飼養種植到標本製成。生命中的大大小小，碰撞擷取美好的片段，延伸出新的療癒意象。完整的真實是眾多片段的組合，片段切割的畫面，真實與虛幻，現實與潛意識，變與不變。人生取決在於自身的中心思想意志，環境不會改變，解決之道在於改變自己。在作品中，思考、成長、完滿我的人生。', `organizer`='國立新竹生活美學館', `address`='新竹市東區武昌街110號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='國立新竹生活美學館', `latitude`=24.8033334, `longitude`=120.9673139, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NHCLAC/Detail.init.ctr?actId=50074&utm_source=moc&utm_medium=ind', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b826b3240c403d99dd', '「機場日常」-簡川特個展/國立新竹生活美學館', '本次展覽由簡川特展出近年來的精采創作，作品包含了油畫與水彩，以記錄的方式帶來親身體驗的寫實感，更透過工作時的仔細觀察力，轉化成一幅幅美麗的作品。\r\n機場不僅僅是旅行的起點與終點，更是無數故事的集合。這裡的每一位工作人員，無論是為旅客服務的職人，還是匆匆而過的旅客，各自帶著故事與回憶。我透過畫筆捕捉這些片刻，讓一個個短暫的片刻匯集成精彩的獨特魅力。機場承載著無數的夢想與期待，揮別與迎接、興奮與期盼、旅人陌生又熟悉的腳步，每一段旅程，滿滿地記錄著生命中的美好。', '國立新竹生活美學館', '新竹市東區武昌街110號', '2025-02-05 00:00:00', '2025-03-02 00:00:00', '國立新竹生活美學館', 24.8033334, 120.9673139, '無資料', 'https://event.culture.tw/mocweb/reg/NHCLAC/Detail.init.ctr?actId=50075&utm_source=moc&utm_medium=ind', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「機場日常」-簡川特個展/國立新竹生活美學館', `description`='本次展覽由簡川特展出近年來的精采創作，作品包含了油畫與水彩，以記錄的方式帶來親身體驗的寫實感，更透過工作時的仔細觀察力，轉化成一幅幅美麗的作品。\r\n機場不僅僅是旅行的起點與終點，更是無數故事的集合。這裡的每一位工作人員，無論是為旅客服務的職人，還是匆匆而過的旅客，各自帶著故事與回憶。我透過畫筆捕捉這些片刻，讓一個個短暫的片刻匯集成精彩的獨特魅力。機場承載著無數的夢想與期待，揮別與迎接、興奮與期盼、旅人陌生又熟悉的腳步，每一段旅程，滿滿地記錄著生命中的美好。', `organizer`='國立新竹生活美學館', `address`='新竹市東區武昌街110號', `start_date`='2025-02-05 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='國立新竹生活美學館', `latitude`=24.8033334, `longitude`=120.9673139, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NHCLAC/Detail.init.ctr?actId=50075&utm_source=moc&utm_medium=ind', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b826b3240c403d99de', '【2025榜書藝術特展】舞動書藝─ 親子肢體律動工作坊', '「舞動書藝─兒童肢體律動工作坊」邀請爸爸媽媽與孩子們用身體書寫書法，透過肢體律動轉化筆墨的揮灑，讓「橫、豎、撇、捺」不只是筆劃，而是舞動的節奏。\r\n\r\n課程中，肢體將成為筆墨，展廳空間將化為紙張，孩子們將親身感受榜書的壯闊氣勢，在律動間探索書法的無限可能！快來體驗這場充滿創意與藝術能量的書法之旅，一起舞動書藝吧！\r\n\r\n【課程內容】\r\n榜書探索之旅｜透過解說與靜心引導認識榜書藝術，感受大字的氣勢與美感\r\n肢體書法模仿｜用身體演繹「橫、豎、撇、捺」，體驗書法的動感與韻律\r\n肢體書藝創作 ｜讓孩子自由發揮，將自己的名字或喜愛的字「寫」進空間中\r\n水寫書藝創作｜結合身體律動與水寫筆創作，完成獨特的書法作品\r\n\r\n【活動資訊】\r\n☆ 合作講師｜森林小丘藝術空間 婷婷老師（紐約大學舞蹈教育碩士）\r\n☆ 日期｜2025年3月15日（六）\r\n☆ 時間｜14:00—16:00\r\n☆ 地點｜中台世界博物館301B（榜書特展展廳）\r\n☆ 報名對象｜7-12歲孩童與家長、對肢體律動感興趣之觀眾（2人1組，限額 15 組）\r\n☆ 費用｜300元/組（含2張門票）\r\n☆ 特別提醒｜課程將邀請家長一同參與探索，每位學童皆須由一位家長陪同。\r\n★ 歡迎親子共遊，在舞動中探索書法的無限可能！\r\n\r\n【報名連結】\r\nhttps://forms.gle/cRAPocFYumXnZd6AA', '中台世界博物館', '南投縣埔里鎮', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '埔里鎮（南投縣）=', 23.97892591, 120.9625259, '費用+300', 'https://lihi.cc/lFMh2', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025榜書藝術特展】舞動書藝─ 親子肢體律動工作坊', `description`='「舞動書藝─兒童肢體律動工作坊」邀請爸爸媽媽與孩子們用身體書寫書法，透過肢體律動轉化筆墨的揮灑，讓「橫、豎、撇、捺」不只是筆劃，而是舞動的節奏。\r\n\r\n課程中，肢體將成為筆墨，展廳空間將化為紙張，孩子們將親身感受榜書的壯闊氣勢，在律動間探索書法的無限可能！快來體驗這場充滿創意與藝術能量的書法之旅，一起舞動書藝吧！\r\n\r\n【課程內容】\r\n榜書探索之旅｜透過解說與靜心引導認識榜書藝術，感受大字的氣勢與美感\r\n肢體書法模仿｜用身體演繹「橫、豎、撇、捺」，體驗書法的動感與韻律\r\n肢體書藝創作 ｜讓孩子自由發揮，將自己的名字或喜愛的字「寫」進空間中\r\n水寫書藝創作｜結合身體律動與水寫筆創作，完成獨特的書法作品\r\n\r\n【活動資訊】\r\n☆ 合作講師｜森林小丘藝術空間 婷婷老師（紐約大學舞蹈教育碩士）\r\n☆ 日期｜2025年3月15日（六）\r\n☆ 時間｜14:00—16:00\r\n☆ 地點｜中台世界博物館301B（榜書特展展廳）\r\n☆ 報名對象｜7-12歲孩童與家長、對肢體律動感興趣之觀眾（2人1組，限額 15 組）\r\n☆ 費用｜300元/組（含2張門票）\r\n☆ 特別提醒｜課程將邀請家長一同參與探索，每位學童皆須由一位家長陪同。\r\n★ 歡迎親子共遊，在舞動中探索書法的無限可能！\r\n\r\n【報名連結】\r\nhttps://forms.gle/cRAPocFYumXnZd6AA', `organizer`='中台世界博物館', `address`='南投縣埔里鎮', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='埔里鎮（南投縣）=', `latitude`=23.97892591, `longitude`=120.9625259, `ticket_price`='費用+300', `source_url`='https://lihi.cc/lFMh2', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b826b3240c403d99df', '「蕙心.繪情」大目降美術學會聯展', '台南市美術與藝術學會林立，是藝術之都，因此大目降美術學會會員心懷熱情，與各學會共同為這藝術之都來努力。本次參展藝術家有16位，作品有47件，聯展作品有陳春陽、彭瓊瑩、李牡丹、林淑貞、康家嘉、陳榮典、謝麗琇、江文國、蔡麗杏與黃景菊等會員的油畫與複合材料畫作品，葉基祥、張憲文、郭金玲、蔡錦明與洪清文等會員的書法與水墨畫作品，楊輝宗老師的水彩畫作品，以及葉仁峰老師的立體造型作品，每幅畫、每幅書法與每座立體造型作品均是老師們的竭力之作。', '國家科學及技術委員會南部科學園區管理局', '臺南市新市區道爺路3號', '2025-02-22 00:00:00', '2025-03-30 00:00:00', '臺南市新市區新港社地方文化館', 23.08319496, 120.2923941, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「蕙心.繪情」大目降美術學會聯展', `description`='台南市美術與藝術學會林立，是藝術之都，因此大目降美術學會會員心懷熱情，與各學會共同為這藝術之都來努力。本次參展藝術家有16位，作品有47件，聯展作品有陳春陽、彭瓊瑩、李牡丹、林淑貞、康家嘉、陳榮典、謝麗琇、江文國、蔡麗杏與黃景菊等會員的油畫與複合材料畫作品，葉基祥、張憲文、郭金玲、蔡錦明與洪清文等會員的書法與水墨畫作品，楊輝宗老師的水彩畫作品，以及葉仁峰老師的立體造型作品，每幅畫、每幅書法與每座立體造型作品均是老師們的竭力之作。', `organizer`='國家科學及技術委員會南部科學園區管理局', `address`='臺南市新市區道爺路3號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市新市區新港社地方文化館', `latitude`=23.08319496, `longitude`=120.2923941, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b826b3240c403d99e0', '府城chill事大徵集', '｢ 你知道府城的「城」，當初是怎麼築建起來的嗎 ？ ｣\r\n臺南府城現存的大南門、大東門、小西門片段城牆和一些城門周邊的城垣殘蹟，都有百年歷史，並被指定為國定古蹟「臺灣府城城門及城垣殘蹟」。\r\n\r\n三百年前，清朝統治臺灣初期，動亂頻仍，為加強防衛，官方在1725年以木柵築起城牆，「府城」的界線於焉定型；但防禦性低的木柵讓城內居民仍感到身家性命的不安，於是在1788年，府城紳民以捐資方式，自力將城牆換成堅固耐用的三合土材料，這樣的府城範圍一直持續百餘年，直到日治時期進行市區改正計畫才被打破。\r\n\r\n臺南府城作為臺灣歷史悠久的文化重鎮，府城的城門、城牆不僅見證臺南這座城市發展變遷的文化遺產，更是凝聚居民情感的重要象徵，同時也承載了許多市民的日常生活記憶。\r\n\r\n2025年適逢府城建城三百年，為了喚起市民對於城門、城牆文化遺產的重視與情感連結，邀請市民一同分享與府城城門或城牆有關的獨特故事，透過不同世代、年齡的市民，分享對府城城門或城牆的印象與記憶，讓更多人也能感受到府城城牆、城門存有的溫度與生命力。\r\n\r\n歡迎分享你我在城門、城牆周邊的日常樂事，串連成紀念府城建城300年一大樂事！\r\n📢 府城chill事大徵集 📢\r\n✋參與對象：只要你對臺南府城的城門、城牆有任何的生活記憶，不管是照片或故事，而且願意與公眾分享，都歡迎投稿喔！\r\n📩徵集內容\r\n📷照片：與臺南的城門或城牆周邊相關的生活照片。照片須附相關的記憶、見聞或感想，字數在100-500字之間。每位參加者最多可提交三張照片。\r\n📝文字：與臺南城門、城牆或舊城整體相關的記憶、見聞、感想等，字數在200-800字之間。每位參加者最多可提交三篇文字內容。\r\n⏰徵件及展出時間\r\n🔸線上徵件：114年2月1日(六)~5月31日(六)截止\r\n🔸實體展出：於《眾志成城：第一屆城牆市鎮論壇》會場公開展示，預計114年7月中旬舉辦。\r\n📩投稿連結：https://forms.gle/99QZm7QEJYWCdzzT7\r\n🏆評選標準：\r\n▶︎投稿作品將由本案顧問共同篩選出適合於城牆市鎮論壇現場展示之作品。\r\n▶︎投稿經獲選展示後，可獲得本案企業贊助之臺南在地伴手禮(或紀念品)一份。\r\n⚠️注意事項\r\n1️⃣投稿需附上參加者姓名、聯繫方式和簡短的自我介紹，字數限50字內。\r\n2️⃣投稿作品須全為本人之創作或擁有。在投稿同時，即代表同意且未違反與第三者之協議，未侵犯其他任何個人或實體之版權、商標權、人格權、隱私／公開權、以及智慧財產權，且未有第三者對該投稿作品具備任何權利、所有權、主張擁有或相關利益，亦未有違反其他法令情事。\r\n3️⃣凡徵集入選之作品，視為同意授權機關（臺南市文化局及臺南市文化資產管理處）永久無限期、地域、次數，不限形式之自由使用，並同意機關委託之廠商進行各種宣傳、公開展示、出版或加值應用等業務相關用途，不另給酬。\r\n4️⃣主辦單位保有隨時修改及終止本活動之權利，如有任何變更內容或詳細注意事項，\r\n將依最新公布資訊為主，恕不另行通知。', '臺南市文化資產管理處', '臺南市全區域', '2025-02-01 00:00:00', '2025-05-31 00:00:00', '臺南市', 0, 0, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='府城chill事大徵集', `description`='｢ 你知道府城的「城」，當初是怎麼築建起來的嗎 ？ ｣\r\n臺南府城現存的大南門、大東門、小西門片段城牆和一些城門周邊的城垣殘蹟，都有百年歷史，並被指定為國定古蹟「臺灣府城城門及城垣殘蹟」。\r\n\r\n三百年前，清朝統治臺灣初期，動亂頻仍，為加強防衛，官方在1725年以木柵築起城牆，「府城」的界線於焉定型；但防禦性低的木柵讓城內居民仍感到身家性命的不安，於是在1788年，府城紳民以捐資方式，自力將城牆換成堅固耐用的三合土材料，這樣的府城範圍一直持續百餘年，直到日治時期進行市區改正計畫才被打破。\r\n\r\n臺南