INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b826b3240c403d99e1', '《潮壤相接》｜《入山》（Ndaan Mpmaduk）紀錄片放映及座談', '《Ndaan Mpmaduk 入山》紀錄片放映\r\n講者：Tommaso Muzzi 多木子、Lucas Mesalles\r\n日期：2025年3月22日（六）\r\n時間：下午2:00-4:00\r\n地點：內惟藝術中心REEL TWO影廳\r\n流程：\r\n14:00-15:20 紀錄片放映\r\n15:20-16:00 對談Q&A（多木子、Lucas Mesalles）\r\n簡介：\r\n《Ndaan Mpmaduk 入山》由多木子執導，紀錄太魯閣族人如何遵循著祖先的狩獵文化，在部落傳統和現代文明交織的脈絡下與山林土地、動物及神靈共處。該片榮獲第二屆臺灣生態環境影展最佳剪輯獎、第58屆金鐘獎節目類導演獎、節目類剪輯獎以及節目類聲音設計獎入圍。本次放映邀請導演多木子以及助理導演Lucas Mesalles、同時也在陽明交通大學研究的地質學家Lucas Mesalles出席映後座談，跟觀眾分享他們對於狩獵以及太魯閣族文化在當代社會的處境觀察。※講者簡介 Tommaso Muzzi 多木子 義大利籍影像工作者，自2009年旅居台灣，深受台灣原住民文化、花東人文地景吸引，長年投入太魯閣族部落田野紀錄，也多次參與花東地方文史調查、 藝術跨域等合作案。其執導紀錄片 《Ndaan Mpmaduk 入山》榮獲第二屆臺灣生態環境影展最佳剪輯獎、第58屆金鐘獎節目類導演獎、節目類剪輯獎以及節目類聲音設計獎入圍。 Lucas Mesalles 《Ndaan Mpmaduk 入山》助理導演，現為國立中正大學（台灣）研究員，專注於環太平洋弧形造山帶（日本、台灣與菲律賓）的地質研究與地球年代測定。', '高雄市立美術館', '高雄市鼓山區馬卡道路329號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '無資料', 'https://www.kmfa.gov.tw/OnlineApplyDetailC001200.aspx?Cond=6ae1fff0-526f-4744-9740-6ca74eda1547', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《潮壤相接》｜《入山》（Ndaan Mpmaduk）紀錄片放映及座談', `description`='《Ndaan Mpmaduk 入山》紀錄片放映\r\n講者：Tommaso Muzzi 多木子、Lucas Mesalles\r\n日期：2025年3月22日（六）\r\n時間：下午2:00-4:00\r\n地點：內惟藝術中心REEL TWO影廳\r\n流程：\r\n14:00-15:20 紀錄片放映\r\n15:20-16:00 對談Q&A（多木子、Lucas Mesalles）\r\n簡介：\r\n《Ndaan Mpmaduk 入山》由多木子執導，紀錄太魯閣族人如何遵循著祖先的狩獵文化，在部落傳統和現代文明交織的脈絡下與山林土地、動物及神靈共處。該片榮獲第二屆臺灣生態環境影展最佳剪輯獎、第58屆金鐘獎節目類導演獎、節目類剪輯獎以及節目類聲音設計獎入圍。本次放映邀請導演多木子以及助理導演Lucas Mesalles、同時也在陽明交通大學研究的地質學家Lucas Mesalles出席映後座談，跟觀眾分享他們對於狩獵以及太魯閣族文化在當代社會的處境觀察。※講者簡介 Tommaso Muzzi 多木子 義大利籍影像工作者，自2009年旅居台灣，深受台灣原住民文化、花東人文地景吸引，長年投入太魯閣族部落田野紀錄，也多次參與花東地方文史調查、 藝術跨域等合作案。其執導紀錄片 《Ndaan Mpmaduk 入山》榮獲第二屆臺灣生態環境影展最佳剪輯獎、第58屆金鐘獎節目類導演獎、節目類剪輯獎以及節目類聲音設計獎入圍。 Lucas Mesalles 《Ndaan Mpmaduk 入山》助理導演，現為國立中正大學（台灣）研究員，專注於環太平洋弧形造山帶（日本、台灣與菲律賓）的地質研究與地球年代測定。', `organizer`='高雄市立美術館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='無資料', `source_url`='https://www.kmfa.gov.tw/OnlineApplyDetailC001200.aspx?Cond=6ae1fff0-526f-4744-9740-6ca74eda1547', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b826b3240c403d99e2', '《金剛經:應無所住》展覽', '水交社文化園區和通蔣勳書房\r\n展品包含了蔣勳老師的手抄金剛經、悉達多油畫與金剛經字畫等作品，曾永玲老師的葉影系列金工作品，以及董承濂老師的「八十八吉祥 - 開悟的勝利幢」及「金剛經 - 應無所住而生其心」作品，導覽中將透過頌缽、金剛經展出，以聽覺、觸覺、嗅覺，讓前來的朋友感受《金剛經》的藝術價值，更能透過志工的引導，感受到其深厚的哲理與智慧，啟迪心靈，追求內心的平靜與智慧，歡迎大家一起來感受3位老師的作品及金剛經的魅力吧！！', '臺南市政府文化局', '臺南市南區興中街7巷18弄5號', '2025-01-01 00:00:00', '2025-06-01 00:00:00', '水交社文化園區', 22.95561863, 120.1903743, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《金剛經:應無所住》展覽', `description`='水交社文化園區和通蔣勳書房\r\n展品包含了蔣勳老師的手抄金剛經、悉達多油畫與金剛經字畫等作品，曾永玲老師的葉影系列金工作品，以及董承濂老師的「八十八吉祥 - 開悟的勝利幢」及「金剛經 - 應無所住而生其心」作品，導覽中將透過頌缽、金剛經展出，以聽覺、觸覺、嗅覺，讓前來的朋友感受《金剛經》的藝術價值，更能透過志工的引導，感受到其深厚的哲理與智慧，啟迪心靈，追求內心的平靜與智慧，歡迎大家一起來感受3位老師的作品及金剛經的魅力吧！！', `organizer`='臺南市政府文化局', `address`='臺南市南區興中街7巷18弄5號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='水交社文化園區', `latitude`=22.95561863, `longitude`=120.1903743, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b826b3240c403d99e3', '歸心', '🎶 【歸心】售票演唱會｜城市遊子的音樂告白 🎤\r\n當音樂響起，歸心的路也隨之展開。\r\n這一次，四組風格獨特的音樂人攜手登台，用最純粹的聲音，帶你找回記憶中的故鄉。\r\n✨ 最強卡司 陪你尋回母語的感動\r\n🎤 Ella 陳嘉樺｜影視歌三棲巨星，陪伴無數人成長的音樂力量\r\n🎤 彭佳慧｜史上首位金曲雙語歌后，用深情嗓音詮釋人生故事\r\n🎤 王若琳｜開口即征服全場，獨樹一格的創作女伶\r\n🎤 林生祥｜三金得主，國際大獎肯定的音樂詩人\r\n📍3月15日｜高雄流行音樂中心海音館\r\n當城市遊子回望家鄉，當旋律勾起深藏心底的回憶；這一夜，讓我們一起用音樂對話，尋回最初心的嚮往💙\r\n📢 售票資訊\r\n🎫 開賣時間：2025.02.20（四）18:00｜KKTIX\r\n🎟 演出時間：2025.03.15（六）19:00-21:30\r\n📍 演出地點：高雄流行音樂中心 海音館\r\n💰 票價：\r\n🔹 一樓 NT$1,200（對號入座）\r\n🔹 二樓 NT$1,000（對號入座）\r\n🔥 限時搶購優惠 🔥\r\n📅 2025.02.20（四）12:00-14:00\r\n🎟 限量9折優惠（售完為止）\r\n用音樂歸心，從這裡開始 🎶\r\nLet’s start from here… 🎵', '客家委員會', '高雄市鹽埕區17鄰真愛路1號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '二樓+1000;一樓+1200', 'https://kktix.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歸心', `description`='🎶 【歸心】售票演唱會｜城市遊子的音樂告白 🎤\r\n當音樂響起，歸心的路也隨之展開。\r\n這一次，四組風格獨特的音樂人攜手登台，用最純粹的聲音，帶你找回記憶中的故鄉。\r\n✨ 最強卡司 陪你尋回母語的感動\r\n🎤 Ella 陳嘉樺｜影視歌三棲巨星，陪伴無數人成長的音樂力量\r\n🎤 彭佳慧｜史上首位金曲雙語歌后，用深情嗓音詮釋人生故事\r\n🎤 王若琳｜開口即征服全場，獨樹一格的創作女伶\r\n🎤 林生祥｜三金得主，國際大獎肯定的音樂詩人\r\n📍3月15日｜高雄流行音樂中心海音館\r\n當城市遊子回望家鄉，當旋律勾起深藏心底的回憶；這一夜，讓我們一起用音樂對話，尋回最初心的嚮往💙\r\n📢 售票資訊\r\n🎫 開賣時間：2025.02.20（四）18:00｜KKTIX\r\n🎟 演出時間：2025.03.15（六）19:00-21:30\r\n📍 演出地點：高雄流行音樂中心 海音館\r\n💰 票價：\r\n🔹 一樓 NT$1,200（對號入座）\r\n🔹 二樓 NT$1,000（對號入座）\r\n🔥 限時搶購優惠 🔥\r\n📅 2025.02.20（四）12:00-14:00\r\n🎟 限量9折優惠（售完為止）\r\n用音樂歸心，從這裡開始 🎶\r\nLet’s start from here… 🎵', `organizer`='客家委員會', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='二樓+1000;一樓+1200', `source_url`='https://kktix.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b926b3240c403d99e4', '『春宵苦短、一期一會』～CANDY☆STAR いちご生誕祭～', '高雄在地深耕15年女子偶像團體【CANDY☆STAR】團長小莓\r\n即將舉辦團體最後一年的生誕祭！\r\n與CANDY☆STAR成員及其他偶像嘉賓\r\n帶來滿滿三小時的精彩唱跳演出！\r\n「漫長的舞台生涯，因為有你的陪伴，\r\n我比任何人都還要幸福。」', '高雄流行音樂中心', '高雄市鹽埕區17鄰真愛路1號', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '預售票+600;現場票+700', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='『春宵苦短、一期一會』～CANDY☆STAR いちご生誕祭～', `description`='高雄在地深耕15年女子偶像團體【CANDY☆STAR】團長小莓\r\n即將舉辦團體最後一年的生誕祭！\r\n與CANDY☆STAR成員及其他偶像嘉賓\r\n帶來滿滿三小時的精彩唱跳演出！\r\n「漫長的舞台生涯，因為有你的陪伴，\r\n我比任何人都還要幸福。」', `organizer`='高雄流行音樂中心', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='預售票+600;現場票+700', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b926b3240c403d99e5', 'SLAMMING GORE EXECUTION', '「當肉體崩裂之時，殺戮便是唯一的真理。」\r\n“When Flesh Tears Apart, Slaughter Becomes the Sole Truth.”\r\n這是一場將殘酷、血腥與謀殺推向極致的殘暴死亡金屬盛宴！音浪如同解剖刀般切割你的意識，每一次SLAM的重擊都像碎骨之錘，敲擊你的靈魂深處，激發對殺戮的原始渴望！\r\n在這座肉體堆砌的屠場，每一聲低吼都是斬首的指令，每一輪狂躁都蘊藏著暴力的血腥詩篇。這是一場無人倖免的殘酷屠殺，為所有深陷暴力美學的靈魂帶來屠殺的快感！\r\n加入這場殺戮！殘殺、淩虐、死亡——所有的一切都在這裡等著你享受！', '高雄流行音樂中心', '高雄市鹽埕區17鄰真愛路1號', '2025-04-27 00:00:00', '2025-04-27 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '預售票+500;現場票+600', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='SLAMMING GORE EXECUTION', `description`='「當肉體崩裂之時，殺戮便是唯一的真理。」\r\n“When Flesh Tears Apart, Slaughter Becomes the Sole Truth.”\r\n這是一場將殘酷、血腥與謀殺推向極致的殘暴死亡金屬盛宴！音浪如同解剖刀般切割你的意識，每一次SLAM的重擊都像碎骨之錘，敲擊你的靈魂深處，激發對殺戮的原始渴望！\r\n在這座肉體堆砌的屠場，每一聲低吼都是斬首的指令，每一輪狂躁都蘊藏著暴力的血腥詩篇。這是一場無人倖免的殘酷屠殺，為所有深陷暴力美學的靈魂帶來屠殺的快感！\r\n加入這場殺戮！殘殺、淩虐、死亡——所有的一切都在這裡等著你享受！', `organizer`='高雄流行音樂中心', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='預售票+500;現場票+600', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b926b3240c403d99e6', '《繪心一笑》小畫家大世界', '孩子們的藝術視界 × 西洋美術史 × 永續創作\r\n\r\n當童真的眼光遇上西洋美術史，會碰撞出怎樣的火花？此展覽透過15位小畫家的視角，重新詮釋從文藝復興到現代藝術的經典作品。他們的筆觸或許天真，卻蘊含無限創意；他們的理解或許純粹，卻直擊藝術的靈魂。\r\n\r\n🔹 你將看到——\r\n🎨 煥然一新重塑經典藝術之美：\r\n透過孩子的眼睛，變得更加生動有趣！\r\n\r\n🖌  藝術知識x孩子們的創意：\r\n每幅畫作皆搭配簡單易懂的美術史介紹！\r\n\r\n🌟 顛覆想像的藝術對話：\r\n當小朋友遇上經典，他們的想法遠比你想的更精彩！\r\n\r\n讓我們透過孩子們的畫筆，探索藝術的無限可能，一同感受美的純粹與驚喜！\r\n\r\n🔹 展覽亮點：\r\n✨ 油畫 / 粉彩 / 炭筆 / 廢材藝術創作\r\n✨ 從西洋美術史出發，探索創意與色彩\r\n✨ 玉米藝術實驗室15位小畫家的精彩作品，邀請您一同感受純真的藝術魅力！', '桃園十一份美術館', '桃園市龍潭區佳安西路5號(A棟2樓)', '2025-02-23 00:00:00', '2025-04-06 00:00:00', '桃園十一份美術館', 24.85064954, 121.2117877, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《繪心一笑》小畫家大世界', `description`='孩子們的藝術視界 × 西洋美術史 × 永續創作\r\n\r\n當童真的眼光遇上西洋美術史，會碰撞出怎樣的火花？此展覽透過15位小畫家的視角，重新詮釋從文藝復興到現代藝術的經典作品。他們的筆觸或許天真，卻蘊含無限創意；他們的理解或許純粹，卻直擊藝術的靈魂。\r\n\r\n🔹 你將看到——\r\n🎨 煥然一新重塑經典藝術之美：\r\n透過孩子的眼睛，變得更加生動有趣！\r\n\r\n🖌  藝術知識x孩子們的創意：\r\n每幅畫作皆搭配簡單易懂的美術史介紹！\r\n\r\n🌟 顛覆想像的藝術對話：\r\n當小朋友遇上經典，他們的想法遠比你想的更精彩！\r\n\r\n讓我們透過孩子們的畫筆，探索藝術的無限可能，一同感受美的純粹與驚喜！\r\n\r\n🔹 展覽亮點：\r\n✨ 油畫 / 粉彩 / 炭筆 / 廢材藝術創作\r\n✨ 從西洋美術史出發，探索創意與色彩\r\n✨ 玉米藝術實驗室15位小畫家的精彩作品，邀請您一同感受純真的藝術魅力！', `organizer`='桃園十一份美術館', `address`='桃園市龍潭區佳安西路5號(A棟2樓)', `start_date`='2025-02-23 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='桃園十一份美術館', `latitude`=24.85064954, `longitude`=121.2117877, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b926b3240c403d99e8', '探索雕刻藝術的魅力_陳正雄', '將傳統與創新雕刻藝術完美結合，帶給您不一樣的視覺與心靈震撼！\r\n陳正雄老師的人物木雕與銅雕：每一件雕塑都是陳老師對人物情感的深刻詮釋，您將會在細膩的雕刻技法中感受到作品的故事與靈魂。\r\n 陳建智老師與黃基興老師的劍獅木雕與銅雕作品：這些劍獅雕塑不僅呈現了傳統工藝的精華，還融入現代設計，讓每一尊劍獅都充滿生命力！', '陳正雄雕刻美術館', '臺南市安平區', '2025-02-15 00:00:00', '2025-03-16 00:00:00', '安平區（臺南市）=', 22.99008437, 120.1649949, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='探索雕刻藝術的魅力_陳正雄', `description`='將傳統與創新雕刻藝術完美結合，帶給您不一樣的視覺與心靈震撼！\r\n陳正雄老師的人物木雕與銅雕：每一件雕塑都是陳老師對人物情感的深刻詮釋，您將會在細膩的雕刻技法中感受到作品的故事與靈魂。\r\n 陳建智老師與黃基興老師的劍獅木雕與銅雕作品：這些劍獅雕塑不僅呈現了傳統工藝的精華，還融入現代設計，讓每一尊劍獅都充滿生命力！', `organizer`='陳正雄雕刻美術館', `address`='臺南市安平區', `start_date`='2025-02-15 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='安平區（臺南市）=', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b926b3240c403d99e9', '明新書院週年院慶暨文昌帝君聖誕-第23屆文昌盃語文演講及才藝表演', '明新書院自民國90年至今，每年舉辦文昌盃語文（英文、閩南語）競賽，提升集集鎮學子語文風氣、鼓勵學生敦品好學；更推廣社區文化理念，培養永昌國小學生成為明新書院的小小解說員，及發掘培育社區藝文人才，長期贊助認養永昌國小兒童樂隊，提升地方文化藝術水準，提供孩子們從小接觸國內、外語文及音樂練習的管道，培養國際觀，為社會開創前瞻性未來。往後將持續努力，發揮書院文化傳承與協助教育的功能。\r\n活動內容有：安斗、點燈、開經和布袋戲演出，及語文演講及才藝表演等。', '明新書院管理委員會', '南投縣集集鎮', '2025-03-02 00:00:00', '2025-03-02 00:00:00', '集集鎮（南投縣）=', 23.83701687, 120.7854192, '無資料', 'https://www.facebook.com/jijitownshipoffice', '[]') ON DUPLICATE KEY UPDATE `activity_name`='明新書院週年院慶暨文昌帝君聖誕-第23屆文昌盃語文演講及才藝表演', `description`='明新書院自民國90年至今，每年舉辦文昌盃語文（英文、閩南語）競賽，提升集集鎮學子語文風氣、鼓勵學生敦品好學；更推廣社區文化理念，培養永昌國小學生成為明新書院的小小解說員，及發掘培育社區藝文人才，長期贊助認養永昌國小兒童樂隊，提升地方文化藝術水準，提供孩子們從小接觸國內、外語文及音樂練習的管道，培養國際觀，為社會開創前瞻性未來。往後將持續努力，發揮書院文化傳承與協助教育的功能。\r\n活動內容有：安斗、點燈、開經和布袋戲演出，及語文演講及才藝表演等。', `organizer`='明新書院管理委員會', `address`='南投縣集集鎮', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='集集鎮（南投縣）=', `latitude`=23.83701687, `longitude`=120.7854192, `ticket_price`='無資料', `source_url`='https://www.facebook.com/jijitownshipoffice', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b926b3240c403d99ea', '2025台北國際書展大獎入圍書展 ', ' 邁入第18屆的「書展大獎」，徵件自2023年10月1日起至2024年9月30日（含）期間首次出版之作品參賽，總件數達660件，包括「小說獎」110件，「非小說獎」329件，「兒童及青少年獎」221件。各獎項參賽作品水準精彩，競爭激烈，不僅呈現台灣年度出版趨勢、表彰台灣原創，也希冀透過台北國際書展、全台北中南圖書館串聯展出、線上及實體書展啟動等豐富多元活動，邀請全民矚目樂讀得獎好書。', '文化部', '桃園市平鎮區環南路三段88號', '2025-02-03 00:00:00', '2025-02-26 00:00:00', '桃園市立圖書館平鎮分館', 24.92117923, 121.2140051, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台北國際書展大獎入圍書展 ', `description`=' 邁入第18屆的「書展大獎」，徵件自2023年10月1日起至2024年9月30日（含）期間首次出版之作品參賽，總件數達660件，包括「小說獎」110件，「非小說獎」329件，「兒童及青少年獎」221件。各獎項參賽作品水準精彩，競爭激烈，不僅呈現台灣年度出版趨勢、表彰台灣原創，也希冀透過台北國際書展、全台北中南圖書館串聯展出、線上及實體書展啟動等豐富多元活動，邀請全民矚目樂讀得獎好書。', `organizer`='文化部', `address`='桃園市平鎮區環南路三段88號', `start_date`='2025-02-03 00:00:00', `end_date`='2025-02-26 00:00:00', `location`='桃園市立圖書館平鎮分館', `latitude`=24.92117923, `longitude`=121.2140051, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
