INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b926b3240c403d99ee', '柳營區圖書館:2月書展~【 2025啟程：自我提升】', '2025年新篇章已經翻開，是時候給自己一個全新的開始！\r\n柳營區圖書館準備一系列關於時間管理、情緒管理、目標設定、習慣養成等書籍，幫助您在新的一年中找到更多動力與成長的契機~\r\n', '臺南市柳營區圖書館', '臺南市柳營區柳營路二段59號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南市柳營區圖書館', 23.26887001, 120.3549205, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='柳營區圖書館:2月書展~【 2025啟程：自我提升】', `description`='2025年新篇章已經翻開，是時候給自己一個全新的開始！\r\n柳營區圖書館準備一系列關於時間管理、情緒管理、目標設定、習慣養成等書籍，幫助您在新的一年中找到更多動力與成長的契機~\r\n', `organizer`='臺南市柳營區圖書館', `address`='臺南市柳營區柳營路二段59號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市柳營區圖書館', `latitude`=23.26887001, `longitude`=120.3549205, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b926b3240c403d99ef', '物有所適－生活儀式感特展', '展覽以「生活儀式感」為題，隨著人們對於當代生活質感的追求提升，工藝不再只是功能性的器物，透過實際的五感體驗，成為兼具實用與美感的生活好物，盼帶領觀者重新思考工藝如何融入當代生活，探索當代生活的風格美學，成為日常生活中的儀式感，讓更多人理解並欣賞工藝之美。 \r\n工藝不只是技藝的展現，更是蘊含生活智慧與文化歷史的載體，透過探討「福爾摩沙美學」（Formosa Style）展現臺灣在地美學如何融合多元文化，形塑出獨特的生活語彙，結合臺灣工藝的創新設計概念，讓工藝成為生活空間中不可或缺的一部分。而本展作為今年工藝中心工藝「漫活SLOHAS」系列活動之一，強調「慢活SLOW」與「樂活LOHAS」為自身的生活態度，SLOHAS並融合簡單（Simple）、生活型態（Lifestyle）、原創性（Original）、健康（Health）、美學（Aesthetics）與永續發展（Sustainability）等關鍵字，倡議工藝的親近與融入生活日常的精神，喚起人們重新思考生活方式，在日常細節中找到屬於自我的生活儀式感與美學風格。\r\n工藝取材於自然，從草、木、皮到土、金、石，每種材質都有其獨特的文化語境與歷史背景，透過有別於傳統的展覽陳列方式，打造宛如樣品屋的沉浸式生活空間，將工藝品與實際生活場景結合，讓觀者親身感受與體驗無距離的真實美感工藝，並學習如何在現代生活中融入工藝風格。展場選用三個日常生活核心場域，如「客廳」、「餐廳」與「個人空間」，透過人們的日常視角與精選工藝品，體現當代生活美學風格，在空間中激發人們對「質感生活」的深度思考，並搭配四種不同生活風格，如「自然奢野（Glamping Living）」、「當代洗鍊（Contemporary Living）」、「沉靜樸實（Tranquil Living）」與「喧動馥郁（Vibrant Living）」等面向，詮釋工藝的多元特性，展現工藝融入生活之美。', '國立臺灣工藝研究發展中心', '南投縣草屯鎮中正路573號', '2025-01-21 00:00:00', '2025-11-30 00:00:00', '國立臺灣工藝研究發展中心（臺灣工藝文化園區）', 23.9807747, 120.6918567, '無資料', 'https://www.ntcri.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='物有所適－生活儀式感特展', `description`='展覽以「生活儀式感」為題，隨著人們對於當代生活質感的追求提升，工藝不再只是功能性的器物，透過實際的五感體驗，成為兼具實用與美感的生活好物，盼帶領觀者重新思考工藝如何融入當代生活，探索當代生活的風格美學，成為日常生活中的儀式感，讓更多人理解並欣賞工藝之美。 \r\n工藝不只是技藝的展現，更是蘊含生活智慧與文化歷史的載體，透過探討「福爾摩沙美學」（Formosa Style）展現臺灣在地美學如何融合多元文化，形塑出獨特的生活語彙，結合臺灣工藝的創新設計概念，讓工藝成為生活空間中不可或缺的一部分。而本展作為今年工藝中心工藝「漫活SLOHAS」系列活動之一，強調「慢活SLOW」與「樂活LOHAS」為自身的生活態度，SLOHAS並融合簡單（Simple）、生活型態（Lifestyle）、原創性（Original）、健康（Health）、美學（Aesthetics）與永續發展（Sustainability）等關鍵字，倡議工藝的親近與融入生活日常的精神，喚起人們重新思考生活方式，在日常細節中找到屬於自我的生活儀式感與美學風格。\r\n工藝取材於自然，從草、木、皮到土、金、石，每種材質都有其獨特的文化語境與歷史背景，透過有別於傳統的展覽陳列方式，打造宛如樣品屋的沉浸式生活空間，將工藝品與實際生活場景結合，讓觀者親身感受與體驗無距離的真實美感工藝，並學習如何在現代生活中融入工藝風格。展場選用三個日常生活核心場域，如「客廳」、「餐廳」與「個人空間」，透過人們的日常視角與精選工藝品，體現當代生活美學風格，在空間中激發人們對「質感生活」的深度思考，並搭配四種不同生活風格，如「自然奢野（Glamping Living）」、「當代洗鍊（Contemporary Living）」、「沉靜樸實（Tranquil Living）」與「喧動馥郁（Vibrant Living）」等面向，詮釋工藝的多元特性，展現工藝融入生活之美。', `organizer`='國立臺灣工藝研究發展中心', `address`='南投縣草屯鎮中正路573號', `start_date`='2025-01-21 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='國立臺灣工藝研究發展中心（臺灣工藝文化園區）', `latitude`=23.9807747, `longitude`=120.6918567, `ticket_price`='無資料', `source_url`='https://www.ntcri.gov.tw/', `image_url`='[]';
