INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b926b3240c403d99f3', '114年3月FUN心聽故事', '孩子是精靈，故事是魔法棒，點綴孩子的心，開啟孩子夢，透過故事媽媽媽說演故事，故事將變成幸福的種子，灑向每個角落，讓小朋友的世界變成一座開滿五彩繽紛幸福花朵的書香城市。', '高雄市立圖書館總館', '高雄市大寮區16鄰進學路133號', '2025-03-08 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館大寮分館', 22.6047403, 120.3934764, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年3月FUN心聽故事', `description`='孩子是精靈，故事是魔法棒，點綴孩子的心，開啟孩子夢，透過故事媽媽媽說演故事，故事將變成幸福的種子，灑向每個角落，讓小朋友的世界變成一座開滿五彩繽紛幸福花朵的書香城市。', `organizer`='高雄市立圖書館總館', `address`='高雄市大寮區16鄰進學路133號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館大寮分館', `latitude`=22.6047403, `longitude`=120.3934764, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23b926b3240c403d99f4', '【講座】馮翊綱 — 這個村子很有戲', '【講座：馮翊綱 — 這個村子很有戲】\r\n在表演藝術裡相聲喜劇是無所不在的一圈金環，從軍中康樂隊，到露天茶棚、到廣播、到電視、到錄音帶……到消失……，忽然搖身一變，成爲了劇場的燈光焦點！\r\n【相聲瓦舍】團長馮翊綱老師，以《這個村子很有戲》回溯自幼生活在左營眷村—崇實新村的點滴，分別呈現來自彼岸大江南北的各種口音、地方戲曲、飲食文化等，以及對他在編劇創作和表演人物等等的關鍵影響！\r\n講座亮點：\r\n真正的藝術創作價值是從消逝中創造\r\n懷抱老文化，同時創立屬於新世紀的文人觀點\r\n追求更有品味的當下與更有希望的未來\r\n時間：3/29 (六) 10:30-12:00 （10:15前報到）\r\n地點：益品美術館（鹿谷鄉中正路二段211巷19號）\r\n\r\n【相聲瓦舍】 二十年間以每年近百場的演出、總平均百分之九十以上的爆炸性票房，成為華文世界家喻戶曉的表演人物。\r\n益品美術館邀請大家一同來感受馮翊綱老師的說唱渲染，以及久違的眷村故事！\r\n【報名方式】\r\n線上：https://forms.gle/AhKA6rWAGtmTL5Mm7\r\n𝑳𝑰𝑵𝑬：https://lin.ee/a6udYIj\r\n電話：049-2752203(營業時間: 9:30-17:00)', '益品美術館', '南投縣鹿谷鄉中正路二段211巷19號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '益品美術館', 23.73776029, 120.7815065, '門票+100', 'https://www.facebook.com/epmuseum', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【講座】馮翊綱 — 這個村子很有戲', `description`='【講座：馮翊綱 — 這個村子很有戲】\r\n在表演藝術裡相聲喜劇是無所不在的一圈金環，從軍中康樂隊，到露天茶棚、到廣播、到電視、到錄音帶……到消失……，忽然搖身一變，成爲了劇場的燈光焦點！\r\n【相聲瓦舍】團長馮翊綱老師，以《這個村子很有戲》回溯自幼生活在左營眷村—崇實新村的點滴，分別呈現來自彼岸大江南北的各種口音、地方戲曲、飲食文化等，以及對他在編劇創作和表演人物等等的關鍵影響！\r\n講座亮點：\r\n真正的藝術創作價值是從消逝中創造\r\n懷抱老文化，同時創立屬於新世紀的文人觀點\r\n追求更有品味的當下與更有希望的未來\r\n時間：3/29 (六) 10:30-12:00 （10:15前報到）\r\n地點：益品美術館（鹿谷鄉中正路二段211巷19號）\r\n\r\n【相聲瓦舍】 二十年間以每年近百場的演出、總平均百分之九十以上的爆炸性票房，成為華文世界家喻戶曉的表演人物。\r\n益品美術館邀請大家一同來感受馮翊綱老師的說唱渲染，以及久違的眷村故事！\r\n【報名方式】\r\n線上：https://forms.gle/AhKA6rWAGtmTL5Mm7\r\n𝑳𝑰𝑵𝑬：https://lin.ee/a6udYIj\r\n電話：049-2752203(營業時間: 9:30-17:00)', `organizer`='益品美術館', `address`='南投縣鹿谷鄉中正路二段211巷19號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='益品美術館', `latitude`=23.73776029, `longitude`=120.7815065, `ticket_price`='門票+100', `source_url`='https://www.facebook.com/epmuseum', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ba26b3240c403d99f5', '繪本書展-彩虹魅力紅色', '那些沒有目的只想閱讀的時候可以怎麼找書呢？或者你也有突然忘記書名，但記得封面顏色的時候！這次圖書館把繪本書海裡紅色封面的書集中起來，一起來看看「紅色封面的繪本」會有哪些有趣的內容吧！', '高雄市立圖書館總館', '高雄市燕巢區2鄰中民路592號', '2025-02-25 00:00:00', '2025-03-25 00:00:00', '高雄市立圖書館燕巢分館', 22.7932892, 120.3623705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='繪本書展-彩虹魅力紅色', `description`='那些沒有目的只想閱讀的時候可以怎麼找書呢？或者你也有突然忘記書名，但記得封面顏色的時候！這次圖書館把繪本書海裡紅色封面的書集中起來，一起來看看「紅色封面的繪本」會有哪些有趣的內容吧！', `organizer`='高雄市立圖書館總館', `address`='高雄市燕巢區2鄰中民路592號', `start_date`='2025-02-25 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='高雄市立圖書館燕巢分館', `latitude`=22.7932892, `longitude`=120.3623705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ba26b3240c403d99f6', '講座：看向太平洋的頌歌-詩人的詩人聶魯達', '拉丁美洲（大家常說的中南美洲）因為殖民的歷史脈絡，被認為是破碎的、哀愁的，但是這塊土地上的人們仍堅韌的生活著，對生活有愛、有熱情，是美麗的。也因為這些過往扉頁，成就多元的音樂、繪畫、電影、文學等領域的作品。\r\n此次邀請暨大中文系教授分享拉美風情，並以智利詩人聶魯達(Pablo Neruda)為核心，感受太平洋的風如何吹送他的情詩？ 如何產生詩的連鎖反應？他啊！成了詩人的詩人，藉此，我們可以多層次認識那與臺灣遙遙相望的迦南拉美地。\r\n\r\n講題：看向太平洋的頌歌－詩人的詩人聶魯達\r\n講者：陳正芳教授（國立暨南國際大學中國語文學系教授兼系主任）\r\n本場演講為「給埔里的二十首情詩和一首絕望的歌」聯合詩展相關活動，相關訊息請私訊詩展臉書粉絲專頁。\r\nhttps://www.facebook.com/beyondcultureinpuli\r\n本場演講為中小學教師研習相關活動，可登錄研習時數', '大灶美術館', '南投縣埔里鎮', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '埔里鎮（南投縣）=', 23.97892591, 120.9625259, '無資料', 'https://www.facebook.com/dazaoart/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='講座：看向太平洋的頌歌-詩人的詩人聶魯達', `description`='拉丁美洲（大家常說的中南美洲）因為殖民的歷史脈絡，被認為是破碎的、哀愁的，但是這塊土地上的人們仍堅韌的生活著，對生活有愛、有熱情，是美麗的。也因為這些過往扉頁，成就多元的音樂、繪畫、電影、文學等領域的作品。\r\n此次邀請暨大中文系教授分享拉美風情，並以智利詩人聶魯達(Pablo Neruda)為核心，感受太平洋的風如何吹送他的情詩？ 如何產生詩的連鎖反應？他啊！成了詩人的詩人，藉此，我們可以多層次認識那與臺灣遙遙相望的迦南拉美地。\r\n\r\n講題：看向太平洋的頌歌－詩人的詩人聶魯達\r\n講者：陳正芳教授（國立暨南國際大學中國語文學系教授兼系主任）\r\n本場演講為「給埔里的二十首情詩和一首絕望的歌」聯合詩展相關活動，相關訊息請私訊詩展臉書粉絲專頁。\r\nhttps://www.facebook.com/beyondcultureinpuli\r\n本場演講為中小學教師研習相關活動，可登錄研習時數', `organizer`='大灶美術館', `address`='南投縣埔里鎮', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='埔里鎮（南投縣）=', `latitude`=23.97892591, `longitude`=120.9625259, `ticket_price`='無資料', `source_url`='https://www.facebook.com/dazaoart/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ba26b3240c403d99f7', '2025大武門音樂祭', '邁入第三年的屏菸週年系列活動以「BURN! LEAD THE WAY」為主題,邀請極具份量的音樂人帶來跨域、跨界等多元精彩流行、R&B、饒舌音樂表演，並推出獨特「競演Battle」，由觀眾歡呼互動評選，結合大「武」門的Fighting碰撞精神展現嘻哈文化中重要Battle元素，另有街舞擂台、美式嘻哈髮廊、潮牌聯名商品，期間限定潮流文化主題市集等豐富內容。\r\n\r\n嘻哈舞台:15:00-20:00\r\n街舞擂台:14:30-18:40\r\n\r\n卡司：\r\n康康xDJ Question Mark | 美麗本人 x BOBONE |  Green Father 比杰 | NXWV EXPRESS(HowZ、SiNNER MOON、Taji) | 林潔心 | C.Holly | 大成 | 小卡比 | JAYRoll | 西屯純愛組 | G5SH |  Y.O MOB｜孤兒收容所', '屏東縣政府', '屏東縣屏東市菸廠路1號', '2025-02-28 00:00:00', '2025-03-01 00:00:00', '屏菸1936文化基地', 22.6647375, 120.4799948, '無資料', 'https://www.facebook.com/@pt1936', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025大武門音樂祭', `description`='邁入第三年的屏菸週年系列活動以「BURN! LEAD THE WAY」為主題,邀請極具份量的音樂人帶來跨域、跨界等多元精彩流行、R&B、饒舌音樂表演，並推出獨特「競演Battle」，由觀眾歡呼互動評選，結合大「武」門的Fighting碰撞精神展現嘻哈文化中重要Battle元素，另有街舞擂台、美式嘻哈髮廊、潮牌聯名商品，期間限定潮流文化主題市集等豐富內容。\r\n\r\n嘻哈舞台:15:00-20:00\r\n街舞擂台:14:30-18:40\r\n\r\n卡司：\r\n康康xDJ Question Mark | 美麗本人 x BOBONE |  Green Father 比杰 | NXWV EXPRESS(HowZ、SiNNER MOON、Taji) | 林潔心 | C.Holly | 大成 | 小卡比 | JAYRoll | 西屯純愛組 | G5SH |  Y.O MOB｜孤兒收容所', `organizer`='屏東縣政府', `address`='屏東縣屏東市菸廠路1號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='屏菸1936文化基地', `latitude`=22.6647375, `longitude`=120.4799948, `ticket_price`='無資料', `source_url`='https://www.facebook.com/@pt1936', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ba26b3240c403d99f8', '燕巢分館114年3月Fun心聽故事', '志工媽媽透過故事說演，引導親子共讀繪本故事，進入故事情境，進而喜歡閱讀，並配合親子共讀，設計延伸活動。故事名稱：《麵包小偷4》、《因為我愛你》', '高雄市立圖書館總館', '高雄市燕巢區2鄰中民路592號', '2025-03-08 00:00:00', '2025-03-15 00:00:00', '高雄市立圖書館燕巢分館', 22.7932892, 120.3623705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='燕巢分館114年3月Fun心聽故事', `description`='志工媽媽透過故事說演，引導親子共讀繪本故事，進入故事情境，進而喜歡閱讀，並配合親子共讀，設計延伸活動。故事名稱：《麵包小偷4》、《因為我愛你》', `organizer`='高雄市立圖書館總館', `address`='高雄市燕巢區2鄰中民路592號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='高雄市立圖書館燕巢分館', `latitude`=22.7932892, `longitude`=120.3623705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ba26b3240c403d99f9', '魚池勝春園北管成果小演：福祿壽仙來～啡咿！', '活動流程：\r\n14:00-14:20 開場致詞  \r\n14:20-14:40 勝春園精彩演出  \r\n14:45-14:50 梨春園特別演出  \r\n14:50-15:00 結語＆大合照\r\n此次演出將帶來充滿福祿壽仙的祝福與北管獨特的韻味，讓您陶醉在傳統音樂的世界裡，感受歲月的悠揚與回響。無論是親朋好友，還是喜愛音樂的長輩們，這都是一場不容錯過的聚會！讓我們一起走進音樂的世界，與傳統文化共舞，期待您的蒞臨！', '魚池戲劇團', '南投縣魚池鄉', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '魚池鄉（南投縣）=', 23.87601213, 120.9256736, '無資料', 'https://www.facebook.com/YuchiFestival/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='魚池勝春園北管成果小演：福祿壽仙來～啡咿！', `description`='活動流程：\r\n14:00-14:20 開場致詞  \r\n14:20-14:40 勝春園精彩演出  \r\n14:45-14:50 梨春園特別演出  \r\n14:50-15:00 結語＆大合照\r\n此次演出將帶來充滿福祿壽仙的祝福與北管獨特的韻味，讓您陶醉在傳統音樂的世界裡，感受歲月的悠揚與回響。無論是親朋好友，還是喜愛音樂的長輩們，這都是一場不容錯過的聚會！讓我們一起走進音樂的世界，與傳統文化共舞，期待您的蒞臨！', `organizer`='魚池戲劇團', `address`='南投縣魚池鄉', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='魚池鄉（南投縣）=', `latitude`=23.87601213, `longitude`=120.9256736, `ticket_price`='無資料', `source_url`='https://www.facebook.com/YuchiFestival/', `image_url`='[]';
