INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ba26b3240c403d9a01', '114年度伊達邵地區藝文活動展演：邵式生活行旅', '以生活博物館概念，由在地族人帶遊客走訪部落祭場、家屋、渔獵等空間場域，以生活當下日常所見，連結瞭解邵族文化，以邵式生活行旅實踐越在地越國際的精神，讓部落空間即日博物館\r\n導覽老師：\r\n陳玉聖，邵文協總幹事。\r\n陳忠駿，伊達邵社區主委。\r\n線上預約：10位\r\n現場報名：5位\r\n線上預約 https://www.surveycake.com/s/NY8Xe', '交通部觀光署日月潭國家風景區管理處', '南投縣魚池鄉中山路', '2025-03-01 00:00:00', '2025-12-28 00:00:00', '日月潭國家風景區', 23.8565133, 120.9021315, '無資料', 'https://www.facebook.com/profile.php?id=61553972986060', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度伊達邵地區藝文活動展演：邵式生活行旅', `description`='以生活博物館概念，由在地族人帶遊客走訪部落祭場、家屋、渔獵等空間場域，以生活當下日常所見，連結瞭解邵族文化，以邵式生活行旅實踐越在地越國際的精神，讓部落空間即日博物館\r\n導覽老師：\r\n陳玉聖，邵文協總幹事。\r\n陳忠駿，伊達邵社區主委。\r\n線上預約：10位\r\n現場報名：5位\r\n線上預約 https://www.surveycake.com/s/NY8Xe', `organizer`='交通部觀光署日月潭國家風景區管理處', `address`='南投縣魚池鄉中山路', `start_date`='2025-03-01 00:00:00', `end_date`='2025-12-28 00:00:00', `location`='日月潭國家風景區', `latitude`=23.8565133, `longitude`=120.9021315, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=61553972986060', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ba26b3240c403d9a03', '澎湖縣圖書館3月天人菊說故事劇坊 ', '研習課程內容，說故事的技巧、圖畫書口述故事技巧、簡易道具偶說演故事技巧等相關課程。3月2日我不想睡 。3月16日比一比誰最長。3月23日鱷魚柯尼列斯。3月30日爸爸的車最棒。        ', '澎湖縣政府文化局', '澎湖縣馬公市中華路236之1號', '2025-03-02 00:00:00', '2025-03-30 00:00:00', '澎湖縣圖書館', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='澎湖縣圖書館3月天人菊說故事劇坊 ', `description`='研習課程內容，說故事的技巧、圖畫書口述故事技巧、簡易道具偶說演故事技巧等相關課程。3月2日我不想睡 。3月16日比一比誰最長。3月23日鱷魚柯尼列斯。3月30日爸爸的車最棒。        ', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路236之1號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='澎湖縣圖書館', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ba26b3240c403d9a04', '114年度伊達邵地區藝文活動展演：邵族杵音展演', '邵族人的新年是在農曆八月一日，邵人會在除夕前一夜晚上，聚集到袁氏頭人家mashtatun（祭儀性杵音） \r\n婦女們會以不同長短粗細的木杵與竹筒，敲擊石頭，以一定的節奏與韻律，發出聲響\r\n除了通知部落族人新年即將到來之外，也讓還在山上狩獵的獵人聽到杵音聲音要趕緊回家好迎接新年。  \r\n而現於日常出現的演出，是邵族最知名的mashbabiar（表演性杵音）\r\n小知識：兩者差異在於，表演性杵音中間有演唱迎賓曲izakua；祭儀性杵音是會不間斷敲擊至早晨。\r\n\r\n如遇雨天或活動，場地另行公告。', '交通部觀光署日月潭國家風景區管理處', '南投縣魚池鄉中山路', '2025-03-01 00:00:00', '2025-03-28 00:00:00', '日月潭國家風景區', 23.8565133, 120.9021315, '無資料', 'https://www.facebook.com/profile.php?id=61553972986060', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度伊達邵地區藝文活動展演：邵族杵音展演', `description`='邵族人的新年是在農曆八月一日，邵人會在除夕前一夜晚上，聚集到袁氏頭人家mashtatun（祭儀性杵音） \r\n婦女們會以不同長短粗細的木杵與竹筒，敲擊石頭，以一定的節奏與韻律，發出聲響\r\n除了通知部落族人新年即將到來之外，也讓還在山上狩獵的獵人聽到杵音聲音要趕緊回家好迎接新年。  \r\n而現於日常出現的演出，是邵族最知名的mashbabiar（表演性杵音）\r\n小知識：兩者差異在於，表演性杵音中間有演唱迎賓曲izakua；祭儀性杵音是會不間斷敲擊至早晨。\r\n\r\n如遇雨天或活動，場地另行公告。', `organizer`='交通部觀光署日月潭國家風景區管理處', `address`='南投縣魚池鄉中山路', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='日月潭國家風景區', `latitude`=23.8565133, `longitude`=120.9021315, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=61553972986060', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ba26b3240c403d9a06', '邵族杵音及歌謠展演（114年2月-7場）', '邵族人的新年是在農曆八月一日，邵人會在除夕前一夜晚上，聚集到袁氏頭人家mashtatun（祭儀性杵音） \r\n婦女們會以不同長短粗細的木杵與竹筒，敲擊石頭，以一定的節奏與韻律，發出聲響\r\n除了通知部落族人新年即將到來之外，也讓還在山上狩獵的獵人聽到杵音聲音要趕緊回家好迎接新年。  \r\n而現於日常出現的演出，是邵族最知名的mashbabiar（表演性杵音）\r\n小知識：兩者差異在於，表演性杵音中間有演唱迎賓曲izakua；祭儀性杵音是會不間斷敲擊至早晨。\r\n除了邵族杵音，還有歌謠展演，歡迎蒞覽欣賞。', '南投縣魚池鄉邵族文化發展協會', '南投縣魚池鄉中山路', '2025-02-14 00:00:00', '2025-02-28 00:00:00', '日月潭國家風景區', 23.8565133, 120.9021315, '無資料', 'https://www.facebook.com/profile.php?id=61553972986060', '[]') ON DUPLICATE KEY UPDATE `activity_name`='邵族杵音及歌謠展演（114年2月-7場）', `description`='邵族人的新年是在農曆八月一日，邵人會在除夕前一夜晚上，聚集到袁氏頭人家mashtatun（祭儀性杵音） \r\n婦女們會以不同長短粗細的木杵與竹筒，敲擊石頭，以一定的節奏與韻律，發出聲響\r\n除了通知部落族人新年即將到來之外，也讓還在山上狩獵的獵人聽到杵音聲音要趕緊回家好迎接新年。  \r\n而現於日常出現的演出，是邵族最知名的mashbabiar（表演性杵音）\r\n小知識：兩者差異在於，表演性杵音中間有演唱迎賓曲izakua；祭儀性杵音是會不間斷敲擊至早晨。\r\n除了邵族杵音，還有歌謠展演，歡迎蒞覽欣賞。', `organizer`='南投縣魚池鄉邵族文化發展協會', `address`='南投縣魚池鄉中山路', `start_date`='2025-02-14 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='日月潭國家風景區', `latitude`=23.8565133, `longitude`=120.9021315, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=61553972986060', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ba26b3240c403d9a07', '澎湖縣政府文化局3月份影片欣賞', '本片為澎湖縣文化局例行性播放影片，歡迎民眾踴躍前往觀賞。3月1日：油麻菜籽（護）陳秋燕、柯一正 （臺灣）。3月8日：媽的多重宇宙（輔）紫瓊、史蒂芬妮．許（美國）。3月15日：護樹．精靈（護）希頓．唐寧、文迪．哈里奧特(美國）。3月22日：超難搞先生（護)普湯姆．漢克斯、瑪麗安娜．特維諾(美國）。3月29日：汪汪隊立大功：超級大電影（普）麥肯娜．葛瑞絲、泰拉姬．P．漢森(美國）。\r\n', '澎湖縣政府文化局', '澎湖縣馬公市中華路236之1號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '澎湖縣圖書館', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='澎湖縣政府文化局3月份影片欣賞', `description`='本片為澎湖縣文化局例行性播放影片，歡迎民眾踴躍前往觀賞。3月1日：油麻菜籽（護）陳秋燕、柯一正 （臺灣）。3月8日：媽的多重宇宙（輔）紫瓊、史蒂芬妮．許（美國）。3月15日：護樹．精靈（護）希頓．唐寧、文迪．哈里奧特(美國）。3月22日：超難搞先生（護)普湯姆．漢克斯、瑪麗安娜．特維諾(美國）。3月29日：汪汪隊立大功：超級大電影（普）麥肯娜．葛瑞絲、泰拉姬．P．漢森(美國）。\r\n', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路236之1號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='澎湖縣圖書館', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ba26b3240c403d9a08', '第十三屆府城普濟燈會-日本青森睡魔祭', '台南一年一度的文化盛事「第十三屆府城普濟燈會」，今年活動亮點之一，就是主燈展出來自「日本青森睡魔祭」之燈藝作品，還規劃國際燈藝交流區，設置「日本宮城·仙台ランタンエリア燈籠區」，展出日本民眾創作的花燈彩繪作品，深化台日文化交流。', '台南市普濟文史研究協會', '臺南市中西區', '2025-01-24 00:00:00', '2025-03-01 00:00:00', '中西區（臺南市）=', 22.99594458, 120.192874, '無資料', 'https://tainan-newyear.tw/index.php?inter=detial&id=68', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十三屆府城普濟燈會-日本青森睡魔祭', `description`='台南一年一度的文化盛事「第十三屆府城普濟燈會」，今年活動亮點之一，就是主燈展出來自「日本青森睡魔祭」之燈藝作品，還規劃國際燈藝交流區，設置「日本宮城·仙台ランタンエリア燈籠區」，展出日本民眾創作的花燈彩繪作品，深化台日文化交流。', `organizer`='台南市普濟文史研究協會', `address`='臺南市中西區', `start_date`='2025-01-24 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='中西區（臺南市）=', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='https://tainan-newyear.tw/index.php?inter=detial&id=68', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ba26b3240c403d9a09', '第十三屆府城普濟燈會-蛇年剪紙巷燈籠展', '台南一年一度的文化盛事「第十三屆府城普濟燈會」-「蛇年剪紙巷燈籠展」以台灣原住民文化為主題，呈現動物傳說與自然意象，更特別深入東部地區，邀請105位長輩與孩童共同創作，展現各族原住民之美。', '台南市普濟文史研究協會', '臺南市中西區', '2025-01-24 00:00:00', '2025-03-01 00:00:00', '中西區（臺南市）=', 22.99594458, 120.192874, '無資料', 'https://tainan-newyear.tw/index.php?inter=detial&id=68', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十三屆府城普濟燈會-蛇年剪紙巷燈籠展', `description`='台南一年一度的文化盛事「第十三屆府城普濟燈會」-「蛇年剪紙巷燈籠展」以台灣原住民文化為主題，呈現動物傳說與自然意象，更特別深入東部地區，邀請105位長輩與孩童共同創作，展現各族原住民之美。', `organizer`='台南市普濟文史研究協會', `address`='臺南市中西區', `start_date`='2025-01-24 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='中西區（臺南市）=', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='https://tainan-newyear.tw/index.php?inter=detial&id=68', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be23ba26b3240c403d9a02', '114年度伊達邵地區藝文活動展演：多元體驗學堂（手作體驗） ', '規劃編織、地方風土素材，植物採集等活動，讓部落傳統智慧媒合轉驛與當代生活結合應用…手作編織奇力魚、貓頭鷹。\r\n指導老師：葉玉杏，邵族杵音藝術團副團長\r\n線上預約：10位\r\n現場報名：5位\r\n線上預約 https://www.surveycake.com/s/NY8Xe', '交通部觀光署日月潭國家風景區管理處', '南投縣魚池鄉中山路', '2025-03-06 00:00:00', '2025-12-31 00:00:00', '日月潭國家風景區', 23.8565133, 120.9021315, '無資料', 'https://www.facebook.com/profile.php?id=61553972986060', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度伊達邵地區藝文活動展演：多元體驗學堂（手作體驗） ', `description`='規劃編織、地方風土素材，植物採集等活動，讓部落傳統智慧媒合轉驛與當代生活結合應用…手作編織奇力魚、貓頭鷹。\r\n指導老師：葉玉杏，邵族杵音藝術團副團長\r\n線上預約：10位\r\n現場報名：5位\r\n線上預約 https://www.surveycake.com/s/NY8Xe', `organizer`='交通部觀光署日月潭國家風景區管理處', `address`='南投縣魚池鄉中山路', `start_date`='2025-03-06 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='日月潭國家風景區', `latitude`=23.8565133, `longitude`=120.9021315, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=61553972986060', `image_url`='[]';
