INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9363167', '臺北市中山區114年健行暨環保活動', '報到時間：114年3月1日（星期六）上午8時。活動地點：圓山花海廣場及圓山河濱公園。集合地點：臺北市中山區圓山花海廣場。參加方式：本活動採各里預先報名制，活動當日請於8:00至8:30於集合地點（圓山花海廣場）領取兌換券，一人限領一份，逾時不候，後續健行至折返點蓋章，回到集合地點，並於11:00前，完成兌換宣導品（僅憑券換取，不可代領宣導品）。', '臺北市中山區公所', '無資料', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F7FF3CECF41E5ED2', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺北市中山區114年健行暨環保活動', `description`='報到時間：114年3月1日（星期六）上午8時。活動地點：圓山花海廣場及圓山河濱公園。集合地點：臺北市中山區圓山花海廣場。參加方式：本活動採各里預先報名制，活動當日請於8:00至8:30於集合地點（圓山花海廣場）領取兌換券，一人限領一份，逾時不候，後續健行至折返點蓋章，回到集合地點，並於11:00前，完成兌換宣導品（僅憑券換取，不可代領宣導品）。', `organizer`='臺北市中山區公所', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F7FF3CECF41E5ED2', `image_url`='[]';
