INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9362535', '大直分館「生活中的綠意」主題書展', '一、活動內容：人與植物的關係密不可分，舉凡路邊的行道樹、家裡擺設的盆栽，又或者森林茂密的植被，它們不僅是空氣的淨化者，更是妝點生活色彩的勃勃生機。大直分館將透過辦理書展，期待能讓更多人接觸介紹植物相關內容的書籍。二、活動時間：2月26日至3月28日，開館期間。三、活動地點：臺北市立圖書館大直分館主題書展區地址：臺北市中山區大直街25號3樓電話：02-25336535', '臺北市立圖書館', '無資料', '2025-02-26 00:00:00', '2025-03-28 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=96A85090FB3427EE', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大直分館「生活中的綠意」主題書展', `description`='一、活動內容：人與植物的關係密不可分，舉凡路邊的行道樹、家裡擺設的盆栽，又或者森林茂密的植被，它們不僅是空氣的淨化者，更是妝點生活色彩的勃勃生機。大直分館將透過辦理書展，期待能讓更多人接觸介紹植物相關內容的書籍。二、活動時間：2月26日至3月28日，開館期間。三、活動地點：臺北市立圖書館大直分館主題書展區地址：臺北市中山區大直街25號3樓電話：02-25336535', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-26 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=96A85090FB3427EE', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9361945', '建成分館「閱讀不寂寞，好禮歡樂兌2」閱讀存摺推廣活動', '一、活動期間：3月1日至6月30日。二、活動方式：凡持本館有效個人借閱證之讀者，於活動期間內自行於「閱讀存摺」系統依借閱證點數選擇本活動提供之獎勵品，並至建成分館完成自助借書達5冊，即可於服務臺兌換好禮（數量有限，兌完為止）。三、注意事項：1.閱讀存摺系統相關規定依本館「閱讀存摺集點及點數兌換說明」辦理。2.借書不可當日隨借隨還，如經查獲則取消參加活動資格。3.請在兌換期限內至建成分館兌換獎品，逾期失效。4.本分館保留活動詮釋、異動之權利，如有內容更動，以分館公告為主。四、活動地點：建成分館(臺北市大同區民生西路198-20號4樓[交通資訊連結]，電話：02-25582320)', '臺北市立圖書館', '無資料', '2025-02-26 00:00:00', '2025-06-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=89FE72B1A04A7621', '[]') ON DUPLICATE KEY UPDATE `activity_name`='建成分館「閱讀不寂寞，好禮歡樂兌2」閱讀存摺推廣活動', `description`='一、活動期間：3月1日至6月30日。二、活動方式：凡持本館有效個人借閱證之讀者，於活動期間內自行於「閱讀存摺」系統依借閱證點數選擇本活動提供之獎勵品，並至建成分館完成自助借書達5冊，即可於服務臺兌換好禮（數量有限，兌完為止）。三、注意事項：1.閱讀存摺系統相關規定依本館「閱讀存摺集點及點數兌換說明」辦理。2.借書不可當日隨借隨還，如經查獲則取消參加活動資格。3.請在兌換期限內至建成分館兌換獎品，逾期失效。4.本分館保留活動詮釋、異動之權利，如有內容更動，以分館公告為主。四、活動地點：建成分館(臺北市大同區民生西路198-20號4樓[交通資訊連結]，電話：02-25582320)', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-26 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=89FE72B1A04A7621', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9361940', '六合分館：社區外展活動-玩具圖書館', '活動名稱：社區外展活動-玩具圖書館活動宗旨：透過故事分享、教玩具樂園、親子DIY等豐富、有趣的活動內容，親子到現場共玩同樂。活動時間：3月9日（星期日）下午2：00~4：00活動地點：臺北市立圖書館六合分館5樓視聽室（地址：臺北市信義區松仁路240巷19號5樓，若有相關問題歡迎來電洽詢，電話：2729-2485）主辦單位：臺北市信義親子館合辦單位：臺北市立圖書館六合分館活動內容：1.故事分享：適齡繪本結合DIY手作活動2.教玩具樂園：豐富好玩的教玩具探索天地3.親子DIY：趣味材料包手作，動動小手玩創意報名方式：1.至臺北育兒網&rarr;登入會員&rarr;親子館活動報名&rarr;點選信義親子館&rarr; 報名。2.直接至現場報名參加。交通方式', '臺北市立圖書館', '無資料', '2025-02-26 00:00:00', '2025-03-09 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=22FD593A8D78C878', '[]') ON DUPLICATE KEY UPDATE `activity_name`='六合分館：社區外展活動-玩具圖書館', `description`='活動名稱：社區外展活動-玩具圖書館活動宗旨：透過故事分享、教玩具樂園、親子DIY等豐富、有趣的活動內容，親子到現場共玩同樂。活動時間：3月9日（星期日）下午2：00~4：00活動地點：臺北市立圖書館六合分館5樓視聽室（地址：臺北市信義區松仁路240巷19號5樓，若有相關問題歡迎來電洽詢，電話：2729-2485）主辦單位：臺北市信義親子館合辦單位：臺北市立圖書館六合分館活動內容：1.故事分享：適齡繪本結合DIY手作活動2.教玩具樂園：豐富好玩的教玩具探索天地3.親子DIY：趣味材料包手作，動動小手玩創意報名方式：1.至臺北育兒網&rarr;登入會員&rarr;親子館活動報名&rarr;點選信義親子館&rarr; 報名。2.直接至現場報名參加。交通方式', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-26 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=22FD593A8D78C878', `image_url`='[]';
