INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9344246', '「清江電影臺，片片都精彩」清江分館3-4月好片上映', '一、活動名稱：清江電影臺暨電影讀書會二、活動宗旨：以辦理影片欣賞及讀書會之活動方式吸引民眾來館，除透過活動提供民眾休閒娛樂外，亦引導其使用圖書館的各項服務和資源。三、活動辦法：免費入場，自由參加。入場請遵守影片分級制度。四、活動節目:3月9日：吐司 敬!美味人生Toast (普遍級)&nbsp;3月23日：名偵探奶奶Oh! My Gran (普遍級) 【本日播映完畢後舉行讀書會】4月13日：快樂鄉頌Mademoiselle Mumu (保護級)4月27日：下流正義The Lincoln Lawyer (輔12級) 【本日播映完畢後舉行讀書會】五、活動時間：3、4月第2、4週週日下午2時起放映,3月23日、4月27日播映完畢後舉行讀書會。六、活動地點：清江分館多功能活動室（臺北市北投區公館路198號3樓）七、交 &nbsp; 通清江分館交通位置八、洽詢電話：臺北市立圖書館清江分館02-28960315。', '臺北市立圖書館', '無資料', '2025-02-26 00:00:00', '2025-03-25 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=4E00DBA1B30203EF', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「清江電影臺，片片都精彩」清江分館3-4月好片上映', `description`='一、活動名稱：清江電影臺暨電影讀書會二、活動宗旨：以辦理影片欣賞及讀書會之活動方式吸引民眾來館，除透過活動提供民眾休閒娛樂外，亦引導其使用圖書館的各項服務和資源。三、活動辦法：免費入場，自由參加。入場請遵守影片分級制度。四、活動節目:3月9日：吐司 敬!美味人生Toast (普遍級)&nbsp;3月23日：名偵探奶奶Oh! My Gran (普遍級) 【本日播映完畢後舉行讀書會】4月13日：快樂鄉頌Mademoiselle Mumu (保護級)4月27日：下流正義The Lincoln Lawyer (輔12級) 【本日播映完畢後舉行讀書會】五、活動時間：3、4月第2、4週週日下午2時起放映,3月23日、4月27日播映完畢後舉行讀書會。六、活動地點：清江分館多功能活動室（臺北市北投區公館路198號3樓）七、交 &nbsp; 通清江分館交通位置八、洽詢電話：臺北市立圖書館清江分館02-28960315。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-26 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=4E00DBA1B30203EF', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9329669', '大直分館3月假日電影院', '一、活動宗旨：大直分館於每週日播放精彩電影，讓社區民眾，在輕鬆休閒的日子裡，可以和同學、朋友、家人相約至圖書館一同欣賞影片，分享人生。二、播映影片：播放日期影片名稱長度分級3月2日等待, 只為了與你相會 Say hello for me113普遍級3月9日Letters from Iwo Jima 來自硫磺島的信141保護級3月16日白米炸彈客 The rice bomber117輔導級3月23日姊姊的守護者 My sister&#39;s keeper109普遍級3月30日文生去看海 Vincent wants to Sea91保護級三、活動時間：每週日下午2點，請依影片分級制度自由入場觀看。四、活動地點：大直分館（地址：臺北市中山區大直街25號5樓視聽室）', '臺北市立圖書館', '無資料', '2025-02-26 00:00:00', '2025-03-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=38FCDB6DDE9D8949', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大直分館3月假日電影院', `description`='一、活動宗旨：大直分館於每週日播放精彩電影，讓社區民眾，在輕鬆休閒的日子裡，可以和同學、朋友、家人相約至圖書館一同欣賞影片，分享人生。二、播映影片：播放日期影片名稱長度分級3月2日等待, 只為了與你相會 Say hello for me113普遍級3月9日Letters from Iwo Jima 來自硫磺島的信141保護級3月16日白米炸彈客 The rice bomber117輔導級3月23日姊姊的守護者 My sister&#39;s keeper109普遍級3月30日文生去看海 Vincent wants to Sea91保護級三、活動時間：每週日下午2點，請依影片分級制度自由入場觀看。四、活動地點：大直分館（地址：臺北市中山區大直街25號5樓視聽室）', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-26 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=38FCDB6DDE9D8949', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9313121', '親子美育數位圖書館電影欣賞：「星期六電影同樂會」，讓你有個愉快的週末。', '&nbsp; 電影是能夠陶冶心靈的一門藝術，無論是喜劇片、動畫片又或是劇情片，必然會有值得思考或是學習的地方。透過電影，更能看出導演縝密的創作世界。 &nbsp;&nbsp; 週末假期親子美育數位圖書館安排系列電影，適合大小朋友前來觀賞。此外，小朋友還能透過集點兌換精美小禮物，讓星期六的午後成為最期待的時光吧。活動時間：3月每週週六下午2時至4時。播映影片：3月1日 白蛇:緣起(普)&nbsp;3月8日 阿卡的冒險:光子秘密(普)3月15日機器戰士TOBO:機器人軍團的襲擊(普)3月22日 阿嬤的小公主(普)3月29日劇場版新幹線變形機器人：來自未來的神速阿爾法X (普)活動對象：12歲以下兒童及其家長活動地點：親子美育數位圖書館 &nbsp;2樓多功能放映室(臺北市南港區研究院路2段61巷15號2樓)報名方式：無須報名，自由入場交通路線：https://reurl.cc/yYX9Xl', '臺北市立圖書館', '無資料', '2025-02-26 00:00:00', '2025-03-26 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=758B3BE70D28572E', '[]') ON DUPLICATE KEY UPDATE `activity_name`='親子美育數位圖書館電影欣賞：「星期六電影同樂會」，讓你有個愉快的週末。', `description`='&nbsp; 電影是能夠陶冶心靈的一門藝術，無論是喜劇片、動畫片又或是劇情片，必然會有值得思考或是學習的地方。透過電影，更能看出導演縝密的創作世界。 &nbsp;&nbsp; 週末假期親子美育數位圖書館安排系列電影，適合大小朋友前來觀賞。此外，小朋友還能透過集點兌換精美小禮物，讓星期六的午後成為最期待的時光吧。活動時間：3月每週週六下午2時至4時。播映影片：3月1日 白蛇:緣起(普)&nbsp;3月8日 阿卡的冒險:光子秘密(普)3月15日機器戰士TOBO:機器人軍團的襲擊(普)3月22日 阿嬤的小公主(普)3月29日劇場版新幹線變形機器人：來自未來的神速阿爾法X (普)活動對象：12歲以下兒童及其家長活動地點：親子美育數位圖書館 &nbsp;2樓多功能放映室(臺北市南港區研究院路2段61巷15號2樓)報名方式：無須報名，自由入場交通路線：https://reurl.cc/yYX9Xl', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-26 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=758B3BE70D28572E', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9362989', '時代劇場：當代影像的複數演繹', ' #展覽', '臺北市立美術館', '[]', '2025-03-29 00:00:00', '2025-07-13 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=AB66B23E5C9CD0A5', '[]') ON DUPLICATE KEY UPDATE `activity_name`='時代劇場：當代影像的複數演繹', `description`=' #展覽', `organizer`='臺北市立美術館', `address`='[]', `start_date`='2025-03-29 00:00:00', `end_date`='2025-07-13 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=AB66B23E5C9CD0A5', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('22ebd8830714b0d6948f5693c4c602ee', '【新北市立圖書館總館】3/22「打造風格圖書館」參與式預算工作坊', '你曾想過，如果能親自決定圖書館的樣貌，會是什麼模樣嗎？是引進更多你愛的書籍，還是舉辦獨特的活動，甚至重新規劃空間與服務，讓圖書館更貼近地方特色及你的需求？參與式預算是一種讓公民直接參與決策的民主機制，而這場工作坊將帶你深入了解其概念與運作模式！透過專業講師帶領，我們將以 「打造風格圖書館」 為題，從館藏、活動到服務，一起發想、模擬提案並進行投票，親身體驗如何讓想法變成行動！【主講人】董祥開教授【時間】114年3月22日(六)14:00-16:00【地點】新北市立圖書館5樓研習教室(新北市板橋區貴興路139號)【報名方式】網路報名【洽詢方式】(02)29537868分機8006黃小姐', '新北市立圖書館', '新北市板橋區貴興路139號', '新北市立圖書館總館5樓研習教室', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館總館】3/22「打造風格圖書館」參與式預算工作坊', `description`='你曾想過，如果能親自決定圖書館的樣貌，會是什麼模樣嗎？是引進更多你愛的書籍，還是舉辦獨特的活動，甚至重新規劃空間與服務，讓圖書館更貼近地方特色及你的需求？參與式預算是一種讓公民直接參與決策的民主機制，而這場工作坊將帶你深入了解其概念與運作模式！透過專業講師帶領，我們將以 「打造風格圖書館」 為題，從館藏、活動到服務，一起發想、模擬提案並進行投票，親身體驗如何讓想法變成行動！【主講人】董祥開教授【時間】114年3月22日(六)14:00-16:00【地點】新北市立圖書館5樓研習教室(新北市板橋區貴興路139號)【報名方式】網路報名【洽詢方式】(02)29537868分機8006黃小姐', `organizer`='新北市立圖書館', `address`='新北市板橋區貴興路139號', `location`='新北市立圖書館總館5樓研習教室', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('22ebd8830714b0d62943b429af8e6d22', '【新北市立圖書館總館】2025世界母語日「閱讀閱在地」系列活動- 總館', '為響應2025世界母語日，推出本土語言系列活動，精彩的DIY、說故事活動、講座和主題書展，歡迎讀者踴躍參加！2025年一起閱讀閱在地！活動內容:1. 戲說繪本─姆姆的眼睛（魯凱族語）：3/15（六）11：00-12：002. 阿美族文化分享與紙藝筆記本DIY：3/15（六）10：00-12：00（阿美族語）3. 布農族百步蛇傳說與彩繪杯墊DIY：3/15（六）14：00-16：00（布農族語）4. 「閱讀閱在地」主題書展：2/21-3/16', '新北市立圖書館', '新北市板橋區貴興路139號', '新北市立圖書館總館', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館總館】2025世界母語日「閱讀閱在地」系列活動- 總館', `description`='為響應2025世界母語日，推出本土語言系列活動，精彩的DIY、說故事活動、講座和主題書展，歡迎讀者踴躍參加！2025年一起閱讀閱在地！活動內容:1. 戲說繪本─姆姆的眼睛（魯凱族語）：3/15（六）11：00-12：002. 阿美族文化分享與紙藝筆記本DIY：3/15（六）10：00-12：00（阿美族語）3. 布農族百步蛇傳說與彩繪杯墊DIY：3/15（六）14：00-16：00（布農族語）4. 「閱讀閱在地」主題書展：2/21-3/16', `organizer`='新北市立圖書館', `address`='新北市板橋區貴興路139號', `location`='新北市立圖書館總館', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
