INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('057500759bab0ba2e3201f80631278d5', '【新北市立圖書館新莊中港分館】114年3月《閱讀書籤-主題書展》大手牽小手', '【新北市立圖書館新莊中港分館】114年3月《閱讀書籤-主題書展》大手牽小手 ●內容：為孩子述說地方有關趣事、故事及傳說並與孩子共同閱讀書籍，讓孩子們在聆聽書籍故事及知識後，能激發更多的想像力、創造力、思考力及理解與分析力。 ●展期：114年3月1日-3月31日／開館時間 ●地點：新北市立圖書館新莊中港分館／7樓書展區（新北市新莊區中港路350號） ●洽詢電話：02-29912053', '新北市立圖書館', '新北市新莊區中港路350號', '新北市立圖書館新莊中港分館／7樓書庫區', 25.0358303, 121.4367535, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新莊中港分館】114年3月《閱讀書籤-主題書展》大手牽小手', `description`='【新北市立圖書館新莊中港分館】114年3月《閱讀書籤-主題書展》大手牽小手 ●內容：為孩子述說地方有關趣事、故事及傳說並與孩子共同閱讀書籍，讓孩子們在聆聽書籍故事及知識後，能激發更多的想像力、創造力、思考力及理解與分析力。 ●展期：114年3月1日-3月31日／開館時間 ●地點：新北市立圖書館新莊中港分館／7樓書展區（新北市新莊區中港路350號） ●洽詢電話：02-29912053', `organizer`='新北市立圖書館', `address`='新北市新莊區中港路350號', `location`='新北市立圖書館新莊中港分館／7樓書庫區', `latitude`=25.0358303, `longitude`=121.4367535, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('272858548ed8e90a8ed6241980ec5afa', '【新北市立圖書館鶯歌二甲閱覽室】114年3月《主題書展》─為「女」寫書', '【新北市立圖書館鶯歌二甲閱覽室】114年3月《主題書展》─為「女」寫書活動內容︰三月擁有屬於女性的節日──婦女節，在這個特殊的日子裡，我們將書籍與女性的靈魂交織，讓每一頁的文字都能講述妳們的故事，以書為橋，搭建一個屬於女性的世界。所以，請跟隨這個為「女」而生的主題書展，愜意地享受這個屬於「妳們」的月份。活動時間：114年03月01日至03月31日活動地點︰鶯歌二甲閱覽室主題展示區(鶯歌區二甲路288號2樓)洽詢電話：(02) 2679-8790※展示期間，歡迎借閱。', '新北市立圖書館', '新北市鶯歌區二甲路288號二樓', '鶯歌二甲閱覽室主題展示區', 24.9566258, 121.3466269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館鶯歌二甲閱覽室】114年3月《主題書展》─為「女」寫書', `description`='【新北市立圖書館鶯歌二甲閱覽室】114年3月《主題書展》─為「女」寫書活動內容︰三月擁有屬於女性的節日──婦女節，在這個特殊的日子裡，我們將書籍與女性的靈魂交織，讓每一頁的文字都能講述妳們的故事，以書為橋，搭建一個屬於女性的世界。所以，請跟隨這個為「女」而生的主題書展，愜意地享受這個屬於「妳們」的月份。活動時間：114年03月01日至03月31日活動地點︰鶯歌二甲閱覽室主題展示區(鶯歌區二甲路288號2樓)洽詢電話：(02) 2679-8790※展示期間，歡迎借閱。', `organizer`='新北市立圖書館', `address`='新北市鶯歌區二甲路288號二樓', `location`='鶯歌二甲閱覽室主題展示區', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('22ebd8830714b0d635aa538ae006034a', '【新北市立圖書館鶯歌分館】114年03月22日(六) 10:00-12:00 「閱讀閱在地」世界母語日-琉璃珠吊飾（排灣族語）(3/8 8:30開放報名)', '【新北市立圖書館鶯歌分館】114年03月22日(六) 10:00-12:00 「閱讀閱在地」世界母語日-琉璃珠吊飾（排灣族語）(3/8 8:30開放報名)邀請包鳯玲講師主講1.淺談排灣族語言與文化2.只要提到琉璃珠，大家都知道是排灣族三寶之一，但你知道每顆琉璃珠都有它的故事嗎？例：（淚痕之珠）相傳太陽與排灣族人很好，但太陽越來越靠近部落，族人發現越來越熱，農作物也完全無法生長，當族人擔心煩憂時，有位聰明的排灣族婦人就想到一個非常好的辦法，不傷太陽也可讓農作物生長的辦法，那到底婦人是用什麼方法呢？就讓我們一起來進入故事中一窺究竟吧！認識排灣琉璃珠並一起動動手來完成屬於自己的琉璃珠吊飾吧！活動時間：114年03月22日(六) 10:00-12:00活動地點：新北市立圖書館鶯歌分館1樓多功能教室(鶯歌區中山路150號)活動對象:一般民眾報名方式：網路報名(限額10位)、電話或櫃台報名(限額10位)，額滿為止。網路報名連結:https://docs.google.com/forms/d/1Ha1rG9SQQmJg8WBZ94JRwBC_fe8bq9U1bMHxfmCPOjs/edit洽詢專線：(02)2678-0219#10了解更多活動相關訊息歡迎加入【鶯歌閱讀活動推廣】平台!＊活動單位保有取消、變更之權利，詳情請依現場為主', '新北市立圖書館', '新北市鶯歌區中山路150號', '新北市立圖書館鶯歌分館1樓多功能教室', 24.9566258, 121.3466269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館鶯歌分館】114年03月22日(六) 10:00-12:00 「閱讀閱在地」世界母語日-琉璃珠吊飾（排灣族語）(3/8 8:30開放報名)', `description`='【新北市立圖書館鶯歌分館】114年03月22日(六) 10:00-12:00 「閱讀閱在地」世界母語日-琉璃珠吊飾（排灣族語）(3/8 8:30開放報名)邀請包鳯玲講師主講1.淺談排灣族語言與文化2.只要提到琉璃珠，大家都知道是排灣族三寶之一，但你知道每顆琉璃珠都有它的故事嗎？例：（淚痕之珠）相傳太陽與排灣族人很好，但太陽越來越靠近部落，族人發現越來越熱，農作物也完全無法生長，當族人擔心煩憂時，有位聰明的排灣族婦人就想到一個非常好的辦法，不傷太陽也可讓農作物生長的辦法，那到底婦人是用什麼方法呢？就讓我們一起來進入故事中一窺究竟吧！認識排灣琉璃珠並一起動動手來完成屬於自己的琉璃珠吊飾吧！活動時間：114年03月22日(六) 10:00-12:00活動地點：新北市立圖書館鶯歌分館1樓多功能教室(鶯歌區中山路150號)活動對象:一般民眾報名方式：網路報名(限額10位)、電話或櫃台報名(限額10位)，額滿為止。網路報名連結:https://docs.google.com/forms/d/1Ha1rG9SQQmJg8WBZ94JRwBC_fe8bq9U1bMHxfmCPOjs/edit洽詢專線：(02)2678-0219#10了解更多活動相關訊息歡迎加入【鶯歌閱讀活動推廣】平台!＊活動單位保有取消、變更之權利，詳情請依現場為主', `organizer`='新北市立圖書館', `address`='新北市鶯歌區中山路150號', `location`='新北市立圖書館鶯歌分館1樓多功能教室', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('22ebd8830714b0d6fb5f5fc2510ee160', '【新北市立圖書館樹林樂山圖書閱覽室】114年3月《主題書展》──玩樂綠生活', '【新北市立圖書館樹林樂山圖書閱覽室】114年3月《主題書展》──玩樂綠生活活動內容︰植物不僅可以淨化空氣、美化環境，加上一些獨特的創意巧思後，小盆栽馬上搖身一變成為吸睛焦點，打造的過程更充滿治癒心靈的魔力，趕快來打造自己的專屬花草園吧！活動時間：114年03月01日至03月31日活動地點︰樹林樂山圖書閱覽室主題展示區(樹林區中和街38號)洽詢電話：(02) 2680-7120※展示期間，歡迎借閱。', '新北市立圖書館', '新北市樹林區中和街38號', '樹林樂山圖書閱覽室主題展示區', 24.97970609, 121.401034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館樹林樂山圖書閱覽室】114年3月《主題書展》──玩樂綠生活', `description`='【新北市立圖書館樹林樂山圖書閱覽室】114年3月《主題書展》──玩樂綠生活活動內容︰植物不僅可以淨化空氣、美化環境，加上一些獨特的創意巧思後，小盆栽馬上搖身一變成為吸睛焦點，打造的過程更充滿治癒心靈的魔力，趕快來打造自己的專屬花草園吧！活動時間：114年03月01日至03月31日活動地點︰樹林樂山圖書閱覽室主題展示區(樹林區中和街38號)洽詢電話：(02) 2680-7120※展示期間，歡迎借閱。', `organizer`='新北市立圖書館', `address`='新北市樹林區中和街38號', `location`='樹林樂山圖書閱覽室主題展示區', `latitude`=24.97970609, `longitude`=121.401034, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
