INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('057500759bab0ba2d7605b8d92ff485e', '【新北市立圖書館鶯歌分館】114年3月假日瘋電影', '【鶯歌分館】114年3月假日瘋電影承辦館別：新北市立圖書館鶯歌分館地址：鶯歌區中山路150號/B1 故事劇場電話：26780219#10時間：每周日14:00-16:0003/02［日］*魔法少女歐拉 : 學校的秘密 ( 普 ) 90分03/09［日］*獅子王 ( 普 ) 118分03/16［日］我和喵喵的冒險旅行 ( 普 ) 83分03/23［日］*海島小英雄馬可 ( 普 ) 73分03/30［日］*電影屁屁偵探 : 咖哩香料事件 + 瓢蟲遺蹟之謎( 普 ) 78分希望經由影片欣賞，滿足觀賞民眾休閒娛樂的需求，並經由影片深入淺出的表演方式，給予民眾不同於日常生活領域的知識與體驗，歡迎有興趣的讀者踴躍參加。※播放影片與時間若有更動，以活動現場公告為主，不便之處，敬請見諒。', '新北市立圖書館', '新北市鶯歌區中山路150號', '鶯歌區中山路150號/B1 故事劇場', 24.9566258, 121.3466269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館鶯歌分館】114年3月假日瘋電影', `description`='【鶯歌分館】114年3月假日瘋電影承辦館別：新北市立圖書館鶯歌分館地址：鶯歌區中山路150號/B1 故事劇場電話：26780219#10時間：每周日14:00-16:0003/02［日］*魔法少女歐拉 : 學校的秘密 ( 普 ) 90分03/09［日］*獅子王 ( 普 ) 118分03/16［日］我和喵喵的冒險旅行 ( 普 ) 83分03/23［日］*海島小英雄馬可 ( 普 ) 73分03/30［日］*電影屁屁偵探 : 咖哩香料事件 + 瓢蟲遺蹟之謎( 普 ) 78分希望經由影片欣賞，滿足觀賞民眾休閒娛樂的需求，並經由影片深入淺出的表演方式，給予民眾不同於日常生活領域的知識與體驗，歡迎有興趣的讀者踴躍參加。※播放影片與時間若有更動，以活動現場公告為主，不便之處，敬請見諒。', `organizer`='新北市立圖書館', `address`='新北市鶯歌區中山路150號', `location`='鶯歌區中山路150號/B1 故事劇場', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('272858548ed8e90a6a8ce551611c4ae0', '【新北市立圖書館鶯歌分館】114年3月《主題書展》──魅力歐洲之行，帶你走進經典', '【新北市立圖書館鶯歌分館】114年3月《主題書展》──魅力歐洲之行，帶你走進經典活動內容︰踏上這趟歐洲之旅，感受巴黎的浪漫、羅馬的古老風情，探索盧浮宮的藝術瑰寶與梵蒂岡的神聖氣息。漫步阿姆斯特丹運河，欣賞阿爾卑斯山美景，品味義大利佳餚美酒，探訪德國童話小鎮。這是一次穿越時空的文化之旅，帶您發現經典之美！活動時間：114年03月01日至03月31日活動地點︰鶯歌分館1樓主題展示區(鶯歌區中山路150號)洽詢電話：（02）2678-0219#10※展示期間，歡迎借閱。', '新北市立圖書館', '新北市鶯歌區中山路150號', '新北市立圖書館鶯歌分館1樓主題展示區', 24.9566258, 121.3466269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館鶯歌分館】114年3月《主題書展》──魅力歐洲之行，帶你走進經典', `description`='【新北市立圖書館鶯歌分館】114年3月《主題書展》──魅力歐洲之行，帶你走進經典活動內容︰踏上這趟歐洲之旅，感受巴黎的浪漫、羅馬的古老風情，探索盧浮宮的藝術瑰寶與梵蒂岡的神聖氣息。漫步阿姆斯特丹運河，欣賞阿爾卑斯山美景，品味義大利佳餚美酒，探訪德國童話小鎮。這是一次穿越時空的文化之旅，帶您發現經典之美！活動時間：114年03月01日至03月31日活動地點︰鶯歌分館1樓主題展示區(鶯歌區中山路150號)洽詢電話：（02）2678-0219#10※展示期間，歡迎借閱。', `organizer`='新北市立圖書館', `address`='新北市鶯歌區中山路150號', `location`='新北市立圖書館鶯歌分館1樓主題展示區', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('272858548ed8e90a3aa9046d08d36a72', '【新北市立圖書館鶯歌分館】114年3月《主題書展》──好繪看好繪想', '【新北市立圖書館鶯歌分館】114年3月《主題書展》──好繪看好繪想活動內容︰讓小朋友走進繽紛的圖畫世界，發現繪本中的奇幻故事和美麗插畫。看到各種色彩鮮豔、形狀各異的繪本，每一本書都充滿了無限的創意與想像，是一場視覺的享受，還將啟發孩子們的語言與表達能力。每一本書背後都藏著故事的智慧，激發小朋友的創意與想像，感受繪本帶來的無窮魅力。活動時間：114年03月01日至03月31日活動地點︰鶯歌分館1樓主題展示區(鶯歌區中山路150號)洽詢電話：（02）2678-0219#10※展示期間，歡迎借閱。', '新北市立圖書館', '新北市鶯歌區中山路150號', '新北市立圖書館鶯歌分館1樓主題展示區', 24.9566258, 121.3466269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館鶯歌分館】114年3月《主題書展》──好繪看好繪想', `description`='【新北市立圖書館鶯歌分館】114年3月《主題書展》──好繪看好繪想活動內容︰讓小朋友走進繽紛的圖畫世界，發現繪本中的奇幻故事和美麗插畫。看到各種色彩鮮豔、形狀各異的繪本，每一本書都充滿了無限的創意與想像，是一場視覺的享受，還將啟發孩子們的語言與表達能力。每一本書背後都藏著故事的智慧，激發小朋友的創意與想像，感受繪本帶來的無窮魅力。活動時間：114年03月01日至03月31日活動地點︰鶯歌分館1樓主題展示區(鶯歌區中山路150號)洽詢電話：（02）2678-0219#10※展示期間，歡迎借閱。', `organizer`='新北市立圖書館', `address`='新北市鶯歌區中山路150號', `location`='新北市立圖書館鶯歌分館1樓主題展示區', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9363517', '文山分館「解鎖手機功能：數位化生活的必學技能」—臺北市社區數位好幫手系列課程', '日常生活中常用的智慧型手機，於現代生活中扮演重要角色，講座介紹通訊軟體的操作與應用，智慧型手機的攝影技巧與空間優化，藉由講師解說與民眾實際操作互動，熟悉基本功能外，更活用智慧型手機相關功能，幫助讀者高效便捷的使用手機，輕鬆運用科技改善日常生活。一、活動時間3月15日（六）10：00&ndash;12：00，「當我們LINE再一起」。（本場次於2月24日，09：00起開放報名）4月12日（六）10：00&ndash;12：00，「手機攝影魔術師」。（本場次於3月24日，09：00起開放報名）5月17日（六）10：00&ndash;12：00，「手機清理術」。（本場次於4月28日，09：00起開放報名）二、活動地點臺北市立圖書館文山分館9樓多功能活動室（地址：臺北市文山區興隆路2段160號9樓，電話：2931-5339）三、活動對象一般民眾，共25名。四、活動報名親洽文山分館櫃檯或來電（02）2931-5339。請自備智慧型手機。五、主辦單位國立臺灣師範大學六、合辦單位臺北市立圖書館文山分館七、交通資訊詳情請洽文山分館簡介網頁', '臺北市立圖書館', '無資料', '2025-02-24 00:00:00', '2025-05-17 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C59C0EF911D8BBD0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='文山分館「解鎖手機功能：數位化生活的必學技能」—臺北市社區數位好幫手系列課程', `description`='日常生活中常用的智慧型手機，於現代生活中扮演重要角色，講座介紹通訊軟體的操作與應用，智慧型手機的攝影技巧與空間優化，藉由講師解說與民眾實際操作互動，熟悉基本功能外，更活用智慧型手機相關功能，幫助讀者高效便捷的使用手機，輕鬆運用科技改善日常生活。一、活動時間3月15日（六）10：00&ndash;12：00，「當我們LINE再一起」。（本場次於2月24日，09：00起開放報名）4月12日（六）10：00&ndash;12：00，「手機攝影魔術師」。（本場次於3月24日，09：00起開放報名）5月17日（六）10：00&ndash;12：00，「手機清理術」。（本場次於4月28日，09：00起開放報名）二、活動地點臺北市立圖書館文山分館9樓多功能活動室（地址：臺北市文山區興隆路2段160號9樓，電話：2931-5339）三、活動對象一般民眾，共25名。四、活動報名親洽文山分館櫃檯或來電（02）2931-5339。請自備智慧型手機。五、主辦單位國立臺灣師範大學六、合辦單位臺北市立圖書館文山分館七、交通資訊詳情請洽文山分館簡介網頁', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-24 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C59C0EF911D8BBD0', `image_url`='[]';
