INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be879426b3240c403d9a0a', '第七屆臺灣墨秀書道會師生聯展', '\n有人說書法是了解並深入中華文化最好的入門，那麼它也是台日文化交流的最佳媒介。本展是渡邊秀碩先生及門生聯展，展出篆、隸、楷、行、草五體書作外，楷、行、草書的作品更展現日本書海社百年傳承的俊秀、清麗、典雅流暢的芳翠流書風。\nCalligraphy is often regarded as the quintessential gateway to comprehending and immersing oneself in Chinese culture, serving as an unparalleled medium for Taiwan-Japan cultural exchange. This exhibition features works by Mr. Watanabe Shuseki and his disciples, showcasing zhuan (篆, seal script), li (隸, clerical script), kai (楷, regular script), xing (行, semi-cursive script), and cao (草, cursive script). The kai, xing, and cao scripts exemplify the refined, fluid, and graceful aesthetics of Japan’s shokaisha, a legacy preserved for over a century.\n', '無資料', '臺北市南海路四十七號', '2025-03-29 00:00:00', '2025-04-06 00:00:00', '第1、2展覽廳', 25.032319, 121.51206, '無資料', 'https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4420', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第七屆臺灣墨秀書道會師生聯展', `description`='\n有人說書法是了解並深入中華文化最好的入門，那麼它也是台日文化交流的最佳媒介。本展是渡邊秀碩先生及門生聯展，展出篆、隸、楷、行、草五體書作外，楷、行、草書的作品更展現日本書海社百年傳承的俊秀、清麗、典雅流暢的芳翠流書風。\nCalligraphy is often regarded as the quintessential gateway to comprehending and immersing oneself in Chinese culture, serving as an unparalleled medium for Taiwan-Japan cultural exchange. This exhibition features works by Mr. Watanabe Shuseki and his disciples, showcasing zhuan (篆, seal script), li (隸, clerical script), kai (楷, regular script), xing (行, semi-cursive script), and cao (草, cursive script). The kai, xing, and cao scripts exemplify the refined, fluid, and graceful aesthetics of Japan’s shokaisha, a legacy preserved for over a century.\n', `organizer`='無資料', `address`='臺北市南海路四十七號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='第1、2展覽廳', `latitude`=25.032319, `longitude`=121.51206, `ticket_price`='無資料', `source_url`='https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4420', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be879526b3240c403d9a0b', 'Rolling', '\n「Rolling」，蘊含多層次的象徵意義，涵蓋時間的流動、生命的成長以及命運的變化。它可解釋為翻滾、滾動，也延伸至不斷向前的動態力量，象徵生命無法停下的進程。無論是時間的推進、人生的挑戰，還是內心的韌性，「Rolling」鼓勵觀眾以自身經歷解讀其中的多重意涵。\n"Rolling" encapsulates layered symbolism, signifying the flow of time, the evolution of life, and the vicissitudes of fate. It can be interpreted as tumbling or rolling, further extending into the dynamic force propelling life inexorably forward. Be it the passage of time, the trials of existence, or the fortitude of the soul, "Rolling" inspires viewers to discern its multifaceted connotations through their personal experiences.\n', '無資料', '臺北市南海路四十七號', '2025-03-21 00:00:00', '2025-03-26 00:00:00', '第1、2展覽廳', 25.032319, 121.51206, '無資料', 'https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4419', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Rolling', `description`='\n「Rolling」，蘊含多層次的象徵意義，涵蓋時間的流動、生命的成長以及命運的變化。它可解釋為翻滾、滾動，也延伸至不斷向前的動態力量，象徵生命無法停下的進程。無論是時間的推進、人生的挑戰，還是內心的韌性，「Rolling」鼓勵觀眾以自身經歷解讀其中的多重意涵。\n"Rolling" encapsulates layered symbolism, signifying the flow of time, the evolution of life, and the vicissitudes of fate. It can be interpreted as tumbling or rolling, further extending into the dynamic force propelling life inexorably forward. Be it the passage of time, the trials of existence, or the fortitude of the soul, "Rolling" inspires viewers to discern its multifaceted connotations through their personal experiences.\n', `organizer`='無資料', `address`='臺北市南海路四十七號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='第1、2展覽廳', `latitude`=25.032319, `longitude`=121.51206, `ticket_price`='無資料', `source_url`='https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4419', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be879526b3240c403d9a0c', '114藝術研習班水彩、素描、油性粉彩聯展', '\n藝教館推廣藝術研習多年，透過藝術研習班推動美感教育，本次展覽為西畫類：分為水彩、素描及油性粉彩，在藝教館美學空間展出學員們藝術研習學習成果，藉此引起國民學習興趣，參與本館藝術研習課程，提昇國民生活美學。\nFor years, the Arts Education Center has championed aesthetic enrichment through its comprehensive art workshops. This exhibition, showcasing Western art forms—watercolor, sketch, and oil pastel─highlights the creative achievements of participants. Displayed in the center''s aesthetic space, it seeks to ignite public enthusiasm for artistic exploration and elevate the nation’s collective aesthetic sensibility.\n', '無資料', '臺北市南海路四十七號', '2025-03-21 00:00:00', '2025-03-30 00:00:00', '美學空間', 25.032319, 121.51206, '無資料', 'https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4424', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114藝術研習班水彩、素描、油性粉彩聯展', `description`='\n藝教館推廣藝術研習多年，透過藝術研習班推動美感教育，本次展覽為西畫類：分為水彩、素描及油性粉彩，在藝教館美學空間展出學員們藝術研習學習成果，藉此引起國民學習興趣，參與本館藝術研習課程，提昇國民生活美學。\nFor years, the Arts Education Center has championed aesthetic enrichment through its comprehensive art workshops. This exhibition, showcasing Western art forms—watercolor, sketch, and oil pastel─highlights the creative achievements of participants. Displayed in the center''s aesthetic space, it seeks to ignite public enthusiasm for artistic exploration and elevate the nation’s collective aesthetic sensibility.\n', `organizer`='無資料', `address`='臺北市南海路四十七號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='美學空間', `latitude`=25.032319, `longitude`=121.51206, `ticket_price`='無資料', `source_url`='https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4424', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be879526b3240c403d9a0d', '臺銀藝術祭', '\n為提升優秀藝術家的能見度，規劃「臺灣銀行藝術祭系列」得獎作品於全臺巡迴展覽。歡迎民眾攜家帶眷踴躍參觀，廣為周知親友前往欣賞作品，為得獎藝術家喝采，給予藝術家實質鼓勵，增添生活美學。\nTo amplify the prominence of exceptional artists, the "Bank of Taiwan Arts Festival Series" orchestrates a nationwide tour showcasing award-winning creations. Citizens are warmly invited to attend with family and friends, spreading the word to appreciate these masterpieces. Let us cheer for the laureates, offering them tangible support while infusing our lives with artistic elegance.\n', '無資料', '臺北市南海路四十七號', '2025-03-21 00:00:00', '2025-03-30 00:00:00', '第3展覽廳', 25.032319, 121.51206, '無資料', 'https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4423', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺銀藝術祭', `description`='\n為提升優秀藝術家的能見度，規劃「臺灣銀行藝術祭系列」得獎作品於全臺巡迴展覽。歡迎民眾攜家帶眷踴躍參觀，廣為周知親友前往欣賞作品，為得獎藝術家喝采，給予藝術家實質鼓勵，增添生活美學。\nTo amplify the prominence of exceptional artists, the "Bank of Taiwan Arts Festival Series" orchestrates a nationwide tour showcasing award-winning creations. Citizens are warmly invited to attend with family and friends, spreading the word to appreciate these masterpieces. Let us cheer for the laureates, offering them tangible support while infusing our lives with artistic elegance.\n', `organizer`='無資料', `address`='臺北市南海路四十七號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='第3展覽廳', `latitude`=25.032319, `longitude`=121.51206, `ticket_price`='無資料', `source_url`='https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4423', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67be879526b3240c403d9a10', '回首•前瞻-陳能梨七十隨心彩墨創作展', '\n作者生於戰亂中的金門，自小喜愛塗鴉.藝術創作之路極其不易，歷經塗鴉、習畫、創作、教學等過程，畢生執著於藝術創作之路上戰戰競競不敢鬆懈，在古稀之年做此個展，意在反思重整過往，前瞻規劃未來，望有生之年持續不斷樂此不疲隨心創作。\nBorn amid the turmoil of wartime Kinmen, the artist’s passion for doodling began in childhood. The arduous path of artistic creation involved relentless dedication across doodling, studying, crafting, and teaching. With unwavering perseverance, the artist has devoted her life to the pursuit of artistic excellence. Now, in her seventies, this solo exhibition serves as an introspective reevaluation of the past and a visionary blueprint for the future, sustaining an unyielding zeal for freehand artistry.\n', '無資料', '臺北市南海路四十七號', '2025-03-08 00:00:00', '2025-03-18 00:00:00', '第1、2展覽廳', 25.032319, 121.51206, '無資料', 'https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4418', '[]') ON DUPLICATE KEY UPDATE `activity_name`='回首•前瞻-陳能梨七十隨心彩墨創作展', `description`='\n作者生於戰亂中的金門，自小喜愛塗鴉.藝術創作之路極其不易，歷經塗鴉、習畫、創作、教學等過程，畢生執著於藝術創作之路上戰戰競競不敢鬆懈，在古稀之年做此個展，意在反思重整過往，前瞻規劃未來，望有生之年持續不斷樂此不疲隨心創作。\nBorn amid the turmoil of wartime Kinmen, the artist’s passion for doodling began in childhood. The arduous path of artistic creation involved relentless dedication across doodling, studying, crafting, and teaching. With unwavering perseverance, the artist has devoted her life to the pursuit of artistic excellence. Now, in her seventies, this solo exhibition serves as an introspective reevaluation of the past and a visionary blueprint for the future, sustaining an unyielding zeal for freehand artistry.\n', `organizer`='無資料', `address`='臺北市南海路四十七號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-18 00:00:00', `location`='第1、2展覽廳', `latitude`=25.032319, `longitude`=121.51206, `ticket_price`='無資料', `source_url`='https://www.arte.gov.tw/pro1_ex