INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9358912', '總館「手機借書享好禮」活動，快來借書拿好禮！', '你知道「手機借書」服務嗎？自113年3月起，除親子美育數位圖書館及社子島智慧圖書館，本館全面啟用「手機借書」服務，為鼓勵讀者多加利用本項服務，凡於活動期間，持個人借閱證使用手機借書功能借書，借閱冊數前20名之讀者，即可獲得Benefit press福利即享券500元。累計借閱冊數達350冊的讀者，還可再抽Sudio A1 Pro，借書用手機，好禮送給你！一、活動時間：3月1日至7月31日二、活動對象：持本館個人借閱證並使用手機借書功能借閱館藏之讀者。三、活動地點：本館手機借書適用館（排除親子美育數位圖書館及社子島智慧圖書館）。四、活動辦法（一）參加資格1.持個人借閱證至本館使用手機借書功能借閱館藏，3-7月累計借閱冊數前20名之讀者即可獲得Benefit press福利即享券500元。2. 3-7月累計借閱冊數達350冊之讀者，可再參加抽獎活動。3.借閱冊數僅計算透過「手機借書」借閱之借閱量，非透過手機借書之借閱量，均不列入計算。4.同一借閱證經由上述管道借閱之冊數得合併計算，惟不同借閱證之借閱冊數不可合併計算。（二）抽獎方式：由本館產製符合抽獎資格之讀者清單，以電腦隨機方式抽出得獎名單，並於8月20日前，公布於官網。（三）詳細活動內容及領獎方式請見「活動辦法」。', '臺北市立圖書館', '無資料', '2025-02-27 00:00:00', '2025-07-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A4FF0CFA381270FB', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館「手機借書享好禮」活動，快來借書拿好禮！', `description`='你知道「手機借書」服務嗎？自113年3月起，除親子美育數位圖書館及社子島智慧圖書館，本館全面啟用「手機借書」服務，為鼓勵讀者多加利用本項服務，凡於活動期間，持個人借閱證使用手機借書功能借書，借閱冊數前20名之讀者，即可獲得Benefit press福利即享券500元。累計借閱冊數達350冊的讀者，還可再抽Sudio A1 Pro，借書用手機，好禮送給你！一、活動時間：3月1日至7月31日二、活動對象：持本館個人借閱證並使用手機借書功能借閱館藏之讀者。三、活動地點：本館手機借書適用館（排除親子美育數位圖書館及社子島智慧圖書館）。四、活動辦法（一）參加資格1.持個人借閱證至本館使用手機借書功能借閱館藏，3-7月累計借閱冊數前20名之讀者即可獲得Benefit press福利即享券500元。2. 3-7月累計借閱冊數達350冊之讀者，可再參加抽獎活動。3.借閱冊數僅計算透過「手機借書」借閱之借閱量，非透過手機借書之借閱量，均不列入計算。4.同一借閱證經由上述管道借閱之冊數得合併計算，惟不同借閱證之借閱冊數不可合併計算。（二）抽獎方式：由本館產製符合抽獎資格之讀者清單，以電腦隨機方式抽出得獎名單，並於8月20日前，公布於官網。（三）詳細活動內容及領獎方式請見「活動辦法」。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-27 00:00:00', `end_date`='2025-07-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A4FF0CFA381270FB', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9327650', '西湖分館《週三電影院》─經典影片，歡迎蒞臨觀賞', '活動時間：3月1日至3月31日，每週三晚上6:30開始活動地點：西湖分館4樓音樂廳(臺北市內湖區內湖路1段594號)洽詢電話：(02)2797-3183播映影片：3月5日 調職令是警察樂隊！Offbeat Cops (普遍級 /日語發音 /119分)3月12日 槍決追殺令 Guns of Eden (輔導級 / 英語發音 /92分)3月19日 我們的黎明 Break of Dawn (普遍級 /日語發音 /120分)3月26日 浪浪回家路 Gump (普遍級 /捷克語發音 /87分)本活動免費參加，觀賞影片請遵守影片分級制入場，本館及音樂廳內皆請勿飲食。若有感冒症狀請配戴口罩，感謝您。', '臺北市立圖書館', '無資料', '2025-02-27 00:00:00', '2025-03-26 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=AF8EC2AB5A56DDF9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='西湖分館《週三電影院》─經典影片，歡迎蒞臨觀賞', `description`='活動時間：3月1日至3月31日，每週三晚上6:30開始活動地點：西湖分館4樓音樂廳(臺北市內湖區內湖路1段594號)洽詢電話：(02)2797-3183播映影片：3月5日 調職令是警察樂隊！Offbeat Cops (普遍級 /日語發音 /119分)3月12日 槍決追殺令 Guns of Eden (輔導級 / 英語發音 /92分)3月19日 我們的黎明 Break of Dawn (普遍級 /日語發音 /120分)3月26日 浪浪回家路 Gump (普遍級 /捷克語發音 /87分)本活動免費參加，觀賞影片請遵守影片分級制入場，本館及音樂廳內皆請勿飲食。若有感冒症狀請配戴口罩，感謝您。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-02-27 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=AF8EC2AB5A56DDF9', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9363627', '「2025雙北世界壯年運動會」賽會影片', '2025雙北世界壯年運動會於5月17日~5月30日在雙北舉行；5月17日在大巨蛋開幕，等你一起和世界挑一場！ ', '臺北市政府警察局婦幼警察隊', '無資料', '2025-02-26 00:00:00', '2025-05-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C30E2B5F01035842', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「2025雙北世界壯年運動會」賽會影片', `description`='2025雙北世界壯年運動會於5月17日~5月30日在雙北舉行；5月17日在大巨蛋開幕，等你一起和世界挑一場！ ', `organizer`='臺北市政府警察局婦幼警察隊', `address`='無資料', `start_date`='2025-02-26 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C30E2B5F01035842', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('676dc9cb26b32458d436322c', '張國森彩陶飛舞個展 ', '陶藝創作家張國森以獨特的藝術語言將陶土幻化成飛舞的生命，每一件作品都充滿動感，彷彿在空間中翩然起舞，讓人陶醉於色彩、形態與情感的交融之中！張國森的作品充滿著活潑奔放的創意，從絢麗的色彩到自由的線條，彷彿帶有呼吸、充滿靈性，也如同都有著自己的故事。大膽的色彩對比，流動的曲線變化，讓作品融入自然中；如花朵盛放的豔麗、流水奔騰的張力、飛鳥展翅的活力，每一件作品都在空間中洋溢著蓬勃的生機，讓觀者如同置身大自然的懷抱，感受到無窮的生命力。\r\n張國森啟蒙師承苗栗老陶師張火木先生，以自己多年來熟稔的技藝與豐富的情感，將無機的泥土塑造成充滿情感的藝術瑰寶，此次個展的作品題材多元，涵蓋自然風貌、生命形態與人文情懷的深層詮釋，每一作品都展現了他對生活深刻的體悟與對藝術無止境的追求，充滿活力且讓人目不轉睛。從自然形態的呈現到抽象元素的揮灑，他以彩陶作為媒介，重新詮釋了色彩與藝術的交織，觀眾將在展覽中見證到彩陶藝術的無限可能，感受到藝術家與作品之間互動的微妙韻律，宛如生命之韻在觀展者眼前躍動。\r\n「張國森 彩陶飛舞 個展」將帶領觀眾進入一個充滿活力、張力與詩意的彩陶世界，這不僅是一次展覽，更是一場色彩與創意交融的藝術饗宴！誠摯邀請所有愛好藝術跟好奇藝術的各界朋友，親臨現場一同來見證張國森如何以獨特的創作語言賦予泥土新的靈魂與情感！', '苗栗縣政府文化觀光局', '苗栗縣公館鄉14鄰館南352號', '2025-01-01 00:00:00', '2025-03-13 00:00:00', '苗栗陶瓷農創園區', 25.0422099, 121.51947, '無資料', 'https://www.facebook.com/miaoliceramics', '[]') ON DUPLICATE KEY UPDATE `activity_name`='張國森彩陶飛舞個展 ', `description`='陶藝創作家張國森以獨特的藝術語言將陶土幻化成飛舞的生命，每一件作品都充滿動感，彷彿在空間中翩然起舞，讓人陶醉於色彩、形態與情感的交融之中！張國森的作品充滿著活潑奔放的創意，從絢麗的色彩到自由的線條，彷彿帶有呼吸、充滿靈性，也如同都有著自己的故事。大膽的色彩對比，流動的曲線變化，讓作品融入自然中；如花朵盛放的豔麗、流水奔騰的張力、飛鳥展翅的活力，每一件作品都在空間中洋溢著蓬勃的生機，讓觀者如同置身大自然的懷抱，感受到無窮的生命力。\r\n張國森啟蒙師承苗栗老陶師張火木先生，以自己多年來熟稔的技藝與豐富的情感，將無機的泥土塑造成充滿情感的藝術瑰寶，此次個展的作品題材多元，涵蓋自然風貌、生命形態與人文情懷的深層詮釋，每一作品都展現了他對生活深刻的體悟與對藝術無止境的追求，充滿活力且讓人目不轉睛。從自然形態的呈現到抽象元素的揮灑，他以彩陶作為媒介，重新詮釋了色彩與藝術的交織，觀眾將在展覽中見證到彩陶藝術的無限可能，感受到藝術家與作品之間互動的微妙韻律，宛如生命之韻在觀展者眼前躍動。\r\n「張國森 彩陶飛舞 個展」將帶領觀眾進入一個充滿活力、張力與詩意的彩陶世界，這不僅是一次展覽，更是一場色彩與創意交融的藝術饗宴！誠摯邀請所有愛好藝術跟好奇藝術的各界朋友，親臨現場一同來見證張國森如何以獨特的創作語言賦予泥土新的靈魂與情感！', `organizer`='苗栗縣政府文化觀光局', `address`='苗栗縣公館鄉14鄰館南352號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-13 00:00:00', `location`='苗栗陶瓷農創園區', `latitude`=25.0422099, `longitude`=121.51947, `ticket_price`='無資料', `source_url`='https://www.facebook.com/miaoliceramics', `image_url`='[]';
