INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bec8db07f360878991a212', '探索勇氣的旅程 插畫創作聯展', '《探索勇氣的旅程》插畫創作聯展集結17位插畫創作者共51件原創手稿，創作者以畫筆開啟探索勇氣的旅程、以畫面引領觀者進入探索勇氣的旅程，期盼大家在本展感受並補充滿滿的勇氣能量，繼續前往人生的下一站~\r\n\r\n\r\n17位參展插畫家｜2024典美插畫大賞入圍 (依姓氏筆畫排序)\r\n王德馨、李季蓉、吳韶寶、林欣柔、陳麗芳、許壬甄、黃翊筑、黃雅靖、趙書巧、劉宇珊、戴芳庭、造己、歐啦、尼果 Nico Tsai、Chloé Kong、Shadowstory、Kuri Art\r\n\r\n\r\n兩檔展期活動｜報名網址https://forms.gle/72JtTCiJwFc2g7EA9\r\n\r\n3/22(六) 14:00-16:00創作者分享會(免費預約入場) \r\n由本次參展插畫家分享自身創作經歷與靈感來源，讓大家深入認識創作者與其作品，同時打造溫馨的藝文交流圈，歡迎對插畫有興趣的朋友踴躍參加！\r\n\r\n\r\n3/29(六) 14:00-15:00插畫講座｜來小黃間插畫插話(費用NT200)\r\n主講者：小黃間little yellow studio｜Barry\r\n\r\n【講座介紹】\r\n傳播工具何其多，如何讓自己的作品脫穎而出？持續「經營」是創意工作者成功的關鍵之一，無論是經營自己或是經營品牌，讓藝術與商業共存並發揮到最大值，才能兼顧夢想與麵包。本講座邀請到小黃間Barry來分享經營插畫品牌/小黃間little yellow studio，以及斜槓自媒體的超實用指南，也聊聊小黃間Barry如何在「作畫」和「說話」間取得平衡，期待陪伴創作者走出屬於自己的品牌之路。\r\n\r\n\r\n', '財團法人典美文化基金會', '臺北市台北市信義區信義路五段150巷2號14樓之3', '2025-03-17 00:00:00', '2025-04-11 00:00:00', '典美藝文空間', 0, 0, '請至少提前一日來電預約', 'https://forms.gle/72JtTCiJwFc2g7EA9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='探索勇氣的旅程 插畫創作聯展', `description`='《探索勇氣的旅程》插畫創作聯展集結17位插畫創作者共51件原創手稿，創作者以畫筆開啟探索勇氣的旅程、以畫面引領觀者進入探索勇氣的旅程，期盼大家在本展感受並補充滿滿的勇氣能量，繼續前往人生的下一站~\r\n\r\n\r\n17位參展插畫家｜2024典美插畫大賞入圍 (依姓氏筆畫排序)\r\n王德馨、李季蓉、吳韶寶、林欣柔、陳麗芳、許壬甄、黃翊筑、黃雅靖、趙書巧、劉宇珊、戴芳庭、造己、歐啦、尼果 Nico Tsai、Chloé Kong、Shadowstory、Kuri Art\r\n\r\n\r\n兩檔展期活動｜報名網址https://forms.gle/72JtTCiJwFc2g7EA9\r\n\r\n3/22(六) 14:00-16:00創作者分享會(免費預約入場) \r\n由本次參展插畫家分享自身創作經歷與靈感來源，讓大家深入認識創作者與其作品，同時打造溫馨的藝文交流圈，歡迎對插畫有興趣的朋友踴躍參加！\r\n\r\n\r\n3/29(六) 14:00-15:00插畫講座｜來小黃間插畫插話(費用NT200)\r\n主講者：小黃間little yellow studio｜Barry\r\n\r\n【講座介紹】\r\n傳播工具何其多，如何讓自己的作品脫穎而出？持續「經營」是創意工作者成功的關鍵之一，無論是經營自己或是經營品牌，讓藝術與商業共存並發揮到最大值，才能兼顧夢想與麵包。本講座邀請到小黃間Barry來分享經營插畫品牌/小黃間little yellow studio，以及斜槓自媒體的超實用指南，也聊聊小黃間Barry如何在「作畫」和「說話」間取得平衡，期待陪伴創作者走出屬於自己的品牌之路。\r\n\r\n\r\n', `organizer`='財團法人典美文化基金會', `address`='臺北市台北市信義區信義路五段150巷2號14樓之3', `start_date`='2025-03-17 00:00:00', `end_date`='2025-04-11 00:00:00', `location`='典美藝文空間', `latitude`=0, `longitude`=0, `ticket_price`='請至少提前一日來電預約', `source_url`='https://forms.gle/72JtTCiJwFc2g7EA9', `image_url`='[]';
