INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf767926b32418d001b7b6', '「光影畫語」譚先芬師生聯合展覽', '新北市板橋地政事務所為美化洽公環境，提供一個讓民眾及同仁辦公時皆能感受人文氣息的藝文空間，自114年1月2日起至3月31日止，舉辦「光影畫語」譚先芬師生聯合展覽，惠請里長協助推廣，歡迎愛好藝文的人士共襄盛舉，一同享受藝術饗宴。', '新北市板橋地政事務所', '新北市板橋區', '2025-01-02 00:00:00', '2025-03-31 00:00:00', '板橋區（新北市）=', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「光影畫語」譚先芬師生聯合展覽', `description`='新北市板橋地政事務所為美化洽公環境，提供一個讓民眾及同仁辦公時皆能感受人文氣息的藝文空間，自114年1月2日起至3月31日止，舉辦「光影畫語」譚先芬師生聯合展覽，惠請里長協助推廣，歡迎愛好藝文的人士共襄盛舉，一同享受藝術饗宴。', `organizer`='新北市板橋地政事務所', `address`='新北市板橋區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='板橋區（新北市）=', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf767a26b32418d001b7b7', '年年有餘系列展', '以「吉祥紋飾」為核心概念，展品涵蓋與蒙藏族群生活文化息息相關之不同材質各式吉祥文物，包括蒙藏文化館典藏之吉祥文物；及結合臺灣2位女性傑出藝術家連寶猜女士、粘碧華女士參與展出，以期引領社會大眾更加認識臺灣女性藝術家巨大的創作能量，同時展示臺灣、蒙古及西藏之多元吉祥文物及工藝之美。', '文化部蒙藏文化中心', '臺北市大安區青田街八巷三號', '2025-01-01 00:00:00', '2025-05-18 00:00:00', '蒙藏文化館', 25.02677012, 121.5434446, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='年年有餘系列展', `description`='以「吉祥紋飾」為核心概念，展品涵蓋與蒙藏族群生活文化息息相關之不同材質各式吉祥文物，包括蒙藏文化館典藏之吉祥文物；及結合臺灣2位女性傑出藝術家連寶猜女士、粘碧華女士參與展出，以期引領社會大眾更加認識臺灣女性藝術家巨大的創作能量，同時展示臺灣、蒙古及西藏之多元吉祥文物及工藝之美。', `organizer`='文化部蒙藏文化中心', `address`='臺北市大安區青田街八巷三號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='蒙藏文化館', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
