INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76aa26b32418d001b7fe', '高雄市立英明國中藝才管弦樂班2025年度音樂會《織音》', '高雄市立英明國中藝才管弦樂班2025年度音樂會《織音》\r\n高雄市立英明國民中學藝才管弦樂班以「織音」為題的年度音樂會，上半場將由校內獲選的協奏曲及室內樂得獎同學，以一首首不同樂派風格的曲目，透過協奏與重奏形式，交織成舞台上最精湛動人的演出。接下來下半場則是樂團的重頭戲，安排漢普汀克根據格林童話「糖果屋」所創作的《漢賽爾與葛麗特組曲》中多首曲目，這部作品是漢普汀克作為華格納的後繼者，成功將華格納的神話世界轉化為童話世界的首部經典之作，深信定能帶給大家不同的藝術境界與感受。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n指揮｜林裕錫 \r\n\r\n樂團｜高雄市立英明國民中學藝才管弦樂班', '高雄市立英明國民中學', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-11 00:00:00', '2025-03-11 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+100;--+200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市立英明國中藝才管弦樂班2025年度音樂會《織音》', `description`='高雄市立英明國中藝才管弦樂班2025年度音樂會《織音》\r\n高雄市立英明國民中學藝才管弦樂班以「織音」為題的年度音樂會，上半場將由校內獲選的協奏曲及室內樂得獎同學，以一首首不同樂派風格的曲目，透過協奏與重奏形式，交織成舞台上最精湛動人的演出。接下來下半場則是樂團的重頭戲，安排漢普汀克根據格林童話「糖果屋」所創作的《漢賽爾與葛麗特組曲》中多首曲目，這部作品是漢普汀克作為華格納的後繼者，成功將華格納的神話世界轉化為童話世界的首部經典之作，深信定能帶給大家不同的藝術境界與感受。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n指揮｜林裕錫 \r\n\r\n樂團｜高雄市立英明國民中學藝才管弦樂班', `organizer`='高雄市立英明國民中學', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-11 00:00:00', `end_date`='2025-03-11 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+100;--+200', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76aa26b32418d001b7ff', '《簧— 2025年臺北市傳統藝術季開幕音樂會》', '《簧— 2025年臺北市傳統藝術季開幕音樂會》\r\n笙為中華文化中宮廷雅樂及傳統民間合奏樂隊的樂器之一，管風琴則是西方的樂器之王，至今超過2千多年歷史，臺北市立國樂團將在首席指揮張宇安的帶領下，透過東西方最古老樂器的並置演出，一起釋放古樂器的老靈魂，散發充滿對比色彩的音樂張力。 在這場2025年臺北市傳統藝術季的開幕音樂會上，透過作曲家王乙聿的《簧》笙、管風琴協奏曲、李佳盈《法雅之火》與關迺忠的《第二交響樂》等，將聽見北市國探尋簧類樂器可能性，感受傳統的當代性。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n邱浩源：《六色氤氳》（委託創作，世界首演）\r\n\r\n王乙聿：《簧》笙、管風琴協奏曲\r\n\r\n李佳盈：《法雅之火》笙協奏曲\r\n\r\n關迺忠：第二交響樂為大型民族樂隊與管風琴而作\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n指揮｜張宇安\r\n\r\n管風琴｜克利斯蒂安‧舒密特\r\n\r\n笙｜朱樂寧、孫衍詳\r\n\r\n臺北市立國樂團', '臺北市立國樂團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-12 00:00:00', '2025-03-12 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+300;--+500;--+800;--+1000;--+1200;--+1500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《簧— 2025年臺北市傳統藝術季開幕音樂會》', `description`='《簧— 2025年臺北市傳統藝術季開幕音樂會》\r\n笙為中華文化中宮廷雅樂及傳統民間合奏樂隊的樂器之一，管風琴則是西方的樂器之王，至今超過2千多年歷史，臺北市立國樂團將在首席指揮張宇安的帶領下，透過東西方最古老樂器的並置演出，一起釋放古樂器的老靈魂，散發充滿對比色彩的音樂張力。 在這場2025年臺北市傳統藝術季的開幕音樂會上，透過作曲家王乙聿的《簧》笙、管風琴協奏曲、李佳盈《法雅之火》與關迺忠的《第二交響樂》等，將聽見北市國探尋簧類樂器可能性，感受傳統的當代性。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n邱浩源：《六色氤氳》（委託創作，世界首演）\r\n\r\n王乙聿：《簧》笙、管風琴協奏曲\r\n\r\n李佳盈：《法雅之火》笙協奏曲\r\n\r\n關迺忠：第二交響樂為大型民族樂隊與管風琴而作\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n指揮｜張宇安\r\n\r\n管風琴｜克利斯蒂安‧舒密特\r\n\r\n笙｜朱樂寧、孫衍詳\r\n\r\n臺北市立國樂團', `organizer`='臺北市立國樂團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-03-12 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+300;--+500;--+800;--+1000;--+1200;--+1500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76aa26b32418d001b800', '《職男人生8－空降部隊》', '《職男人生8－空降部隊》\r\n表演為現場喜劇演出，類似傳統相聲，以更加輕快的節奏及平易近人的生活題材，更能讓觀眾產生共鳴及歡笑。除了經典的日式漫才以外，短劇更是面白大丈夫的招牌，以幽默有趣的對白以及劇情為主。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n製作人｜面白大丈夫\r\n\r\n劇本統籌｜耿賢\r\n\r\n編劇｜面白大丈夫\r\n\r\n演員｜董軒、耿賢、阿量、木森\r\n\r\n行政經理｜陳婉芸\r\n\r\n視覺設計｜羿辰\r\n\r\n燈光音響統籌｜藍圖整合行銷 廖俊榮\r\n\r\n燈光設計｜張善婷\r\n\r\n音樂、音效設計｜阿量\r\n\r\n影像、廣告設計｜阿量\r\n\r\n行銷宣傳｜面白大丈夫', '面白大丈夫劇團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-14 00:00:00', '2025-03-16 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+600;--+800;--+1000;--+1200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《職男人生8－空降部隊》', `description`='《職男人生8－空降部隊》\r\n表演為現場喜劇演出，類似傳統相聲，以更加輕快的節奏及平易近人的生活題材，更能讓觀眾產生共鳴及歡笑。除了經典的日式漫才以外，短劇更是面白大丈夫的招牌，以幽默有趣的對白以及劇情為主。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n製作人｜面白大丈夫\r\n\r\n劇本統籌｜耿賢\r\n\r\n編劇｜面白大丈夫\r\n\r\n演員｜董軒、耿賢、阿量、木森\r\n\r\n行政經理｜陳婉芸\r\n\r\n視覺設計｜羿辰\r\n\r\n燈光音響統籌｜藍圖整合行銷 廖俊榮\r\n\r\n燈光設計｜張善婷\r\n\r\n音樂、音效設計｜阿量\r\n\r\n影像、廣告設計｜阿量\r\n\r\n行銷宣傳｜面白大丈夫', `organizer`='面白大丈夫劇團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+600;--+800;--+1000;--+1200', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76aa26b32418d001b801', '【衛武營親子日】奇妙的故事圍裙', '【衛武營親子日】奇妙的故事圍裙\r\n  活動故事內容介紹  \r\n\r\n改編自繪本作家劉旭恭老師的作品《車票去哪裡了？》。一陣風吹來，吹散了正等著搭乘公車的人們的車票，公車司機該如何使命必達的尋找車票，展開旅程？故事圍裙上，故事的旅程被縫進布料，驚喜藏入彩線裡，小小的開合、收納有大大的樂趣。在活動裡參與的親子將合力完成屬於自己的故事圍裙。\r\n\r\n \r\n\r\n  玩樂指南  \r\n\r\n發現警喜認識臺灣繪本作家作品\r\n\r\n親子互動協作，設計自己專屬的圍裙\r\n\r\n創造物件的空間與想像力\r\n\r\n \r\n\r\n  活動時間、活動地點  \r\n\r\n時間：2025/3/15(六)\r\n\r\n10:00-11:30、14:00-15:30（90分鐘）\r\n\r\n地點：1186排練室\r\n\r\n \r\n\r\n  報名對象與方式  \r\n\r\n建議報名對象：4-8歲孩童\r\n*本活動針對該年齡層設計，如不在建議報名年齡範圍內，請家長自行評估是否合適參與\r\n報名費用：單次費用新臺幣650元（1位大人+1位小朋友）。\r\n* 為維護參與者活動權益，未經過主辦單位核可，陪同親屬請勿擅自進入活動空間並參與活動，避免影響活動進度。\r\n報名時程：截止3/14(五)23:59\r\n報名人數：25組，額滿為止。\r\n報名流程：官網報名→繳交費用→檢視官網報名狀況→完成報名。\r\n \r\n\r\n  其他補充注意事項  \r\n\r\n因考量場地空間大小，活動進行中，一位小朋友陪同一位家長，如有其他家屬請至一旁休息區稍作休息。\r\n請自備水壺、衛生紙、擦汗毛巾。\r\n請著輕便好動的服裝以褲裝為佳。\r\n進場前請先依照工作人員指示完成報到。\r\n活動場地不宜飲食，一定要先吃完正餐或是點心再來哦！\r\n為能讓大家更投入於活動情境中，建議活動中不使用手機拍照、錄影與滑手機(無強制性)，請參與家長協助配合，活動結束後歡迎自行拍照留影。\r\n本活動安排之相關攝錄影紀錄，以藝文推廣或非營利性之目的為限，報名即視為同意拍攝，若不便入鏡，請於報到時告知工作人員及索取標示貼紙。\r\n \r\n\r\n  授課老師  \r\n\r\n圖片\r\n故事演出｜彭浩秦\r\n\r\n劇場和影像表演者。畢業於國立臺北藝術大學戲劇系。2024以客家電視台《學學嘴學學鼻》獲金鐘獎「兒童少年節目主持人獎」。2020以客家電視台電視電影《大桔大利闔家平安》獲2021溫哥華國際電影獎最佳男主角。\r\n\r\n \r\n\r\n圖片\r\n\r\n講師｜蔡奉瑾\r\n\r\n臺南藝術大學造形藝術研究所碩士。劇場工作者，喜愛在眾材質間摸索造形之趣味，如服裝設計、視覺設計等；也是一名肢體豐富極具感染力的表演者，曾參與黃蝶南天舞踏團、差事劇團演出。曾任「動物動物動茲動」、「一起穿故事」工作坊講師。\r\n\r\n\r\n \r\n\r\n  團隊介紹  \r\n\r\n不想睡遊戲\r\n\r\n圖片\r\n「不想睡遊戲社」由一群擁有豐富劇場經驗，且熱愛遊戲的大孩子所組成，致力於0 - 6歲學齡前幼兒的戲劇編創發展。自2012年創團以來，不想睡遊戲社不拘泥任何既定的演出形式，每回的作品皆出自對生活的觀察，與探索的好奇心建構而成。創造讓身處不同發展階段的孩童皆能專注享受的劇場時光。\r\n\r\n演出製作： 2012《奌奌子》、2013《水在哪裡》、2014《轉轉喀啦搭》、2015《黑白跳跳》、2016《一欉樹仔》、2017～2018「李彥駐團玩具劇場計劃」製作故事圍裙《車票去哪裡了》、2020《冬冬的第一次飛行》（與和英出版社合作）、2021故宮兒童學藝中心特展演出《宋貨郎說故事》、2023《一欉樹仔：乘風的旅程》、與夜夜生歌工作室合作《未來溫室的植物保育園：給孩子們的電音派對》、2024《陽光隱身術》。 音樂家故事散步系列：《貝多芬先生，您好》、《柴可夫斯基先生，您好》、《巴哈先生，您好》、《布拉姆斯先生，您好》、《史特拉汶斯基先生，您好》。', '國家表演藝術中心衛武營國家藝術文化中心', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+650', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【衛武營親子日】奇妙的故事圍裙', `description`='【衛武營親子日】奇妙的故事圍裙\r\n  活動故事內容介紹  \r\n\r\n改編自繪本作家劉旭恭老師的作品《車票去哪裡了？》。一陣風吹來，吹散了正等著搭乘公車的人們的車票，公車司機該如何使命必達的尋找車票，展開旅程？故事圍裙上，故事的旅程被縫進布料，驚喜藏入彩線裡，小小的開合、收納有大大的樂趣。在活動裡參與的親子將合力完成屬於自己的故事圍裙。\r\n\r\n \r\n\r\n  玩樂指南  \r\n\r\n發現警喜認識臺灣繪本作家作品\r\n\r\n親子互動協作，設計自己專屬的圍裙\r\n\r\n創造物件的空間與想像力\r\n\r\n \r\n\r\n  活動時間、活動地點  \r\n\r\n時間：2025/3/15(六)\r\n\r\n10:00-11:30、14:00-15:30（90分鐘）\r\n\r\n地點：1186排練室\r\n\r\n \r\n\r\n  報名對象與方式  \r\n\r\n建議報名對象：4-8歲孩童\r\n*本活動針對該年齡層設計，如不在建議報名年齡範圍內，請家長自行評估是否合適參與\r\n報名費用：單次費用新臺幣650元（1位大人+1位小朋友）。\r\n* 為維護參與者活動權益，未經過主辦單位核可，陪同親屬請勿擅自進入活動空間並參與活動，避免影響活動進度。\r\n報名時程：截止3/14(五)23:59\r\n報名人數：25組，額滿為止。\r\n報名流程：官網報名→繳交費用→檢視官網報名狀況→完成報名。\r\n \r\n\r\n  其他補充注意事項  \r\n\r\n因考量場地空間大小，活動進行中，一位小朋友陪同一位家長，如有其他家屬請至一旁休息區稍作休息。\r\n請自備水壺、衛生紙、擦汗毛巾。\r\n請著輕便好動的服裝以褲裝為佳。\r\n進場前請先依照工作人員指示完成報到。\r\n活動場地不宜飲食，一定要先吃完正餐或是點心再來哦！\r\n為能讓大家更投入於活動情境中，建議活動中不使用手機拍照、錄影與滑手機(無強制性)，請參與家長協助配合，活動結束後歡迎自行拍照留影。\r\n本活動安排之相關攝錄影紀錄，以藝文推廣或非營利性之目的為限，報名即視為同意拍攝，若不便入鏡，請於報到時告知工作人員及索取標示貼紙。\r\n \r\n\r\n  授課老師  \r\n\r\n圖片\r\n故事演出｜彭浩秦\r\n\r\n劇場和影像表演者。畢業於國立臺北藝術大學戲劇系。2024以客家電視台《學學嘴學學鼻》獲金鐘獎「兒童少年節目主持人獎」。2020以客家電視台電視電影《大桔大利闔家平安》獲2021溫哥華國際電影獎最佳男主角。\r\n\r\n \r\n\r\n圖片\r\n\r\n講師｜蔡奉瑾\r\n\r\n臺南藝術大學造形藝術研究所碩士。劇場工作者，喜愛在眾材質間摸索造形之趣味，如服裝設計、視覺設計等；也是一名肢體豐富極具感染力的表演者，曾參與黃蝶南天舞踏團、差事劇團演出。曾任「動物動物動茲動」、「一起穿故事」工作坊講師。\r\n\r\n\r\n \r\n\r\n  團隊介紹  \r\n\r\n不想睡遊戲\r\n\r\n圖片\r\n「不想睡遊戲社」由一群擁有豐富劇場經驗，且熱愛遊戲的大孩子所組成，致力於0 - 6歲學齡前幼兒的戲劇編創發展。自2012年創團以來，不想睡遊戲社不拘泥任何既定的演出形式，每回的作品皆出自對生活的觀察，與探索的好奇心建構而成。創造讓身處不同發展階段的孩童皆能專注享受的劇場時光。\r\n\r\n演出製作： 2012《奌奌子》、2013《水在哪裡》、2014《轉轉喀啦搭》、2015《黑白跳跳》、2016《一欉樹仔》、2017～2018「李彥駐團玩具劇場計劃」製作故事圍裙《車票去哪裡了》、2020《冬冬的第一次飛行》（與和英出版社合作）、2021故宮兒童學藝中心特展演出《宋貨郎說故事》、2023《一欉樹仔：乘風的旅程》、與夜夜生歌工作室合作《未來溫室的植物保育園：給孩子們的電音派對》、2024《陽光隱身術》。 音樂家故事散步系列：《貝多芬先生，您好》、《柴可夫斯基先生，您好》、《巴哈先生，您好》、《布拉姆斯先生，您好》、《史特拉汶斯基先生，您好》。', `organizer`='國家表演藝術中心衛武營國家藝術文化中心', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `star