INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76aa26b32418d001b802', '2025年春季巧虎大型舞臺劇《花神祭》', '2025年春季巧虎大型舞臺劇《花神祭》\r\n巧虎、琪琪、妙妙和桃樂比受邀到玫瑰王國參加十年一次的花神祭慶典，但重要的花神杖卻消失了。\r\n\r\n巧虎他們與玫瑰公主決定進入充滿魔法的祕密花園中，開啟一段尋找花神杖的冒險旅程！\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\nＯ劇團', '日商倍樂生股份有限公司台北分公司', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-15 00:00:00', '2025-03-16 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500;--+700;--+900;--+1100;--+1300;--+1500;--+1800;--+2000', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年春季巧虎大型舞臺劇《花神祭》', `description`='2025年春季巧虎大型舞臺劇《花神祭》\r\n巧虎、琪琪、妙妙和桃樂比受邀到玫瑰王國參加十年一次的花神祭慶典，但重要的花神杖卻消失了。\r\n\r\n巧虎他們與玫瑰公主決定進入充滿魔法的祕密花園中，開啟一段尋找花神杖的冒險旅程！\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\nＯ劇團', `organizer`='日商倍樂生股份有限公司台北分公司', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500;--+700;--+900;--+1100;--+1300;--+1500;--+1800;--+2000', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76aa26b32418d001b803', '《光影之間——梵志登X馮勇智》', '《光影之間——梵志登X馮勇智》\r\n馮勇智展現了令人驚嘆的演奏技巧，他充分的展現了他的才華，琴弦在他精湛的控制力下，創造出獨特，且專屬於他的的音樂拼圖。  —— Benicia Herald\r\n\r\n \r\n\r\n由華格納唯一的喜劇《紐倫堡的名歌手》序曲作為開端，描繪文藝復興名歌手公會的歡慶氛圍。前紐約愛樂音樂總監——梵志登，史上最年輕的柴科夫斯基國際大賽大提琴金牌得主——馮勇智，將與近期掀起一波話題的長榮交響樂團，共同演繹經典的《洛可可主題變奏曲》，展現溫柔婉約的旋律線，大提琴與樂團的細膩對話。柴科夫斯基對命運的思考與掙扎，透過第四號交響曲呈現，旋律充滿戲劇張力，從無法抵抗惴惴不安的命運，走向超越悲痛、浴火重生的生存希望！你絕對可以從中引起共鳴！\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n華格納：《紐倫堡的名歌手》序曲\r\n\r\n柴科夫斯基：《洛可可主題變奏曲》\r\n大提琴：馮勇智\r\n\r\n柴科夫斯基：F小調第四號交響曲\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n長榮交響樂團\r\n\r\n指揮｜梵志登\r\n\r\n大提琴｜馮勇智', '長榮交響樂團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+400;--+800;--+1200;--+1600;--+2000;--+2500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《光影之間——梵志登X馮勇智》', `description`='《光影之間——梵志登X馮勇智》\r\n馮勇智展現了令人驚嘆的演奏技巧，他充分的展現了他的才華，琴弦在他精湛的控制力下，創造出獨特，且專屬於他的的音樂拼圖。  —— Benicia Herald\r\n\r\n \r\n\r\n由華格納唯一的喜劇《紐倫堡的名歌手》序曲作為開端，描繪文藝復興名歌手公會的歡慶氛圍。前紐約愛樂音樂總監——梵志登，史上最年輕的柴科夫斯基國際大賽大提琴金牌得主——馮勇智，將與近期掀起一波話題的長榮交響樂團，共同演繹經典的《洛可可主題變奏曲》，展現溫柔婉約的旋律線，大提琴與樂團的細膩對話。柴科夫斯基對命運的思考與掙扎，透過第四號交響曲呈現，旋律充滿戲劇張力，從無法抵抗惴惴不安的命運，走向超越悲痛、浴火重生的生存希望！你絕對可以從中引起共鳴！\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n華格納：《紐倫堡的名歌手》序曲\r\n\r\n柴科夫斯基：《洛可可主題變奏曲》\r\n大提琴：馮勇智\r\n\r\n柴科夫斯基：F小調第四號交響曲\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n長榮交響樂團\r\n\r\n指揮｜梵志登\r\n\r\n大提琴｜馮勇智', `organizer`='長榮交響樂團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+400;--+800;--+1200;--+1600;--+2000;--+2500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76aa26b32418d001b804', '《2025新逸寰宇旗艦系列 舞臺生涯一甲子回顧－陳泰成鋼琴獨奏會》', '《2025新逸寰宇旗艦系列 舞臺生涯一甲子回顧－陳泰成鋼琴獨奏會》\r\n自1964年第一次登台演出協奏曲至今，轉眼一甲子逝去。身為臺灣第一代最傑出鋼琴演奏家之一，陳泰成早已掙脫年少青澀的桎梏而更臻成熟，如同老酒佳釀，越陳越香，經歷歲月的淬煉，對音樂的詮釋具有獨到的見解，其演奏亦更能滲透生命之意涵。此次演出的曲目，巴哈的第六號帕蒂塔組曲與貝多芬的110號奏鳴曲皆爲作曲家的巔峰之作，而莫札特的330號奏鳴曲則為喪母之慟所作，為鋼琴家心境之寫照，透過琴聲傾訴心靈深處的情感。 \r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n巴哈：平均律第二冊E大調前奏曲與賦格  BWV 878\r\n\r\n巴哈：平均律第二冊升c小調前奏曲與賦格  BWV 873\r\n\r\n巴哈：第六號e小調Partita 組曲  BWV 830\r\n\r\n莫札特：a小調奏鳴曲  K.310\r\n\r\n貝多芬：降A大調奏鳴曲  Op.110\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n鋼琴｜陳泰成', '新逸藝術有限公司', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+400;--+700;--+1000;--+1500', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025新逸寰宇旗艦系列 舞臺生涯一甲子回顧－陳泰成鋼琴獨奏會》', `description`='《2025新逸寰宇旗艦系列 舞臺生涯一甲子回顧－陳泰成鋼琴獨奏會》\r\n自1964年第一次登台演出協奏曲至今，轉眼一甲子逝去。身為臺灣第一代最傑出鋼琴演奏家之一，陳泰成早已掙脫年少青澀的桎梏而更臻成熟，如同老酒佳釀，越陳越香，經歷歲月的淬煉，對音樂的詮釋具有獨到的見解，其演奏亦更能滲透生命之意涵。此次演出的曲目，巴哈的第六號帕蒂塔組曲與貝多芬的110號奏鳴曲皆爲作曲家的巔峰之作，而莫札特的330號奏鳴曲則為喪母之慟所作，為鋼琴家心境之寫照，透過琴聲傾訴心靈深處的情感。 \r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n巴哈：平均律第二冊E大調前奏曲與賦格  BWV 878\r\n\r\n巴哈：平均律第二冊升c小調前奏曲與賦格  BWV 873\r\n\r\n巴哈：第六號e小調Partita 組曲  BWV 830\r\n\r\n莫札特：a小調奏鳴曲  K.310\r\n\r\n貝多芬：降A大調奏鳴曲  Op.110\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n鋼琴｜陳泰成', `organizer`='新逸藝術有限公司', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+400;--+700;--+1000;--+1500', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76aa26b32418d001b805', '《堅持夢想－現代雙簧管音樂詩篇》', '《堅持夢想－現代雙簧管音樂詩篇》\r\n由國內雙簧管演奏家洪小琴與鋼琴家黃楚涵攜手合作，此場音樂會將呈現美國現代作曲家巴伯（S. Barber）、尼德爾曼（K. Needleman）及埃瓦森（E. Ewazen）的雙簧管作品，引領觀眾感悟情感的真摯，尋找內在自我的共鳴與蛻變。在這場深具意象與觸動心靈的現代雙簧管獨奏會裡，現代雙簧音詩徜徉於美國當代音樂的詩情與感性之中。我們期待一同探索作曲家們卓越的風格與創意，共同參與一場河流般的時光旅程與豐富多彩的音樂饗宴。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n巴伯：短曲，作品四十八\r\n\r\n埃瓦森：《順流而下的時間之河》、《堅持你的夢想》\r\n\r\n尼德爾曼：《從餘燼中重生》 \r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n雙簧管｜洪小琴\r\n\r\n鋼琴｜黃楚涵\r\n\r\n導聆｜林采誼', '高雄市管樂團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500;--+800;--+1000', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《堅持夢想－現代雙簧管音樂詩篇》', `description`='《堅持夢想－現代雙簧管音樂詩篇》\r\n由國內雙簧管演奏家洪小琴與鋼琴家黃楚涵攜手合作，此場音樂會將呈現美國現代作曲家巴伯（S. Barber）、尼德爾曼（K. Needleman）及埃瓦森（E. Ewazen）的雙簧管作品，引領觀眾感悟情感的真摯，尋找內在自我的共鳴與蛻變。在這場深具意象與觸動心靈的現代雙簧管獨奏會裡，現代雙簧音詩徜徉於美國當代音樂的詩情與感性之中。我們期待一同探索作曲家們卓越的風格與創意，共同參與一場河流般的時光旅程與豐富多彩的音樂饗宴。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n巴伯：短曲，作品四十八\r\n\r\n埃瓦森：《順流而下的時間之河》、《堅持你的夢想》\r\n\r\n尼德爾曼：《從餘燼中重生》 \r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n雙簧管｜洪小琴\r\n\r\n鋼琴｜黃楚涵\r\n\r\n導聆｜林采誼', `organizer`='高雄市管樂團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500;--+800;--+1000', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76aa26b32418d001b806', '2025【探索管風琴音樂】【春日管風琴派對】', '2025【探索管風琴音樂】\r\n走進衛武營音樂廳，除了驚嘆葡萄園式觀眾席與極佳音響效果外，位於最頂層的管風琴，也是眾人矚目的焦點。\r\n\r\n若是您曾經好奇，這台亞洲最大的音樂廳管風琴，究竟能展現什麼樣的百變樣貌，「探索管風琴音樂」系列活動，將是得到解答的大好機會！\r\n\r\n衛武營特別邀請臺灣專業管風琴家們設計獨家節目，搭配其他樂器以及加入燈光效果等特殊聆賞規劃，加上平易近人的專業解說，展現管風琴的萬千變換與可親可愛。\r\n\r\n活動特別安排「舞台零距離體驗場」將舞台區轉變為觀眾席區，讓您近距離一睹管風琴風采；「自由移動體驗場」在曲目間安排換位橋段，透過體驗不同的觀看視角，做為您日後蒞臨音樂廳欣賞演出的座位參考。\r\n\r\n每月一小時，相約「探索管風琴音樂」，揭開管風琴的神祕面紗，拉近管風琴與我們的距離！\r\n\r\n3/19(三)14:30\r\n\r\n【春日管風琴派對】\r\n\r\n※管風琴家：劉信宏、魏佳玲\r\n\r\n立即購票\r\n\r\n\r\n\r\n3月初春暖陽，來衛武營開一場管風琴派對！此月精選最耳熟能詳的古典樂金曲，從威爾第歌劇《阿依達》裡燦爛輝煌的凱旋進行曲，到葛利格《皮爾金》戲劇配樂中群魔亂舞的〈山大王的宮殿〉，從聖歌天籟的〈奇異恩典〉到管風琴家改編的《小小世界》和《當你許下星願時》，此外還有最受歡迎的聖桑《動物狂歡節》選粹，更特別的是，本場管風琴還會變身為「管絃樂團」，與鋼琴獨奏演出莫札特最寧靜甜美的第21號鋼琴協奏曲第二樂章，為派對帶來最璀璨的音樂饗宴。\r\n\r\n \r\n\r\n孟德爾頌：第三號管風琴奏鳴曲，作品編號65之3，第一樂章\r\n\r\n威爾第：凱旋進行曲，選自歌劇《阿伊達》\r\n\r\n葛利格：〈山魔王的宮殿〉選自《皮爾金組曲》\r\n\r\n聖桑：《動物狂歡節》選粹\r\n\r\nI. 〈獅子之序曲與皇家進行曲〉\r\n\r\nII. 〈母雞與公雞〉\r\n\r\nXIII. 〈天鵝〉\r\n\r\nXIV.〈終曲〉\r\n\r\n斯萬改編：《奇異恩典》\r\n\r\n魏佳玲改編：《小小世界》和《當你許下星願時》\r\n\r\n斯萬改編：《聖安妮節慶觸技曲》\r\n\r\n莫札特：C大調鋼琴協奏曲第21號，第二樂章行板\r\n\r\n  好書推薦  \r\n\r\n《打開管風琴的祕密》\r\n\r\n由來自德國的繪本作者西妮雅．博尼希編寫繪製，衛武營取得授權後和時報出版合作在臺發行繁體中文版。以淺顯易懂的文字和充滿童趣插圖，講解樂器之王管風琴的組成構造、發聲原理，以及衛武營音樂廳中全亞洲最大管風琴，如何由德國波昂的百年管風琴製造廠Johannes Klais Orgelbau， 歷經三年多時間設計製造，並橫跨9,500多公里搬運來到高雄衛武營組裝完工的巨大挑戰 。\r\n►購買連結\r\n\r\n《打開管風琴的祕密》圖片\r\n \r\n\r\n  藝文支持  \r\n\r\n瑞儀教育基金會', '國家表演藝術中心衛武營國家藝術文化中心', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-19 00:00:00', '2025-03-19 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025【探索管風琴音樂】【春日管風琴派對】', `description`='2025【探索管風琴音樂】\r\n走進衛武營音樂廳，除了驚嘆葡萄園式觀眾席與極佳音響效果外，位於最頂層的管風琴，也是眾人矚目的焦點。\r\n\r\n若是您曾經好奇，這台亞洲最大的音樂廳管風琴，究竟能展現什麼樣的百變樣貌，「探索管風琴音樂」系列活動，將是得到解答的大好機會！\r\n\r\n衛武營特別邀請臺灣專業管風琴家們設計獨家節目，搭配其他樂器以及加入燈光效果等特殊聆賞規劃，加上平易近人的專業解說，展現管風琴的萬千變換與可親可愛。\r\n\r\n活動特別安排「舞台零距離體驗場」將舞台區轉變為觀眾席區，讓您近距離一睹管風琴風采；「自由移動體驗場」在曲目間安排換位橋段，透過體驗不同的觀看視角，做為您日後蒞臨音樂廳欣賞演出的座位參考。\r\n\r\n每月一小時，相約「探索管風琴音樂」，揭開管風琴的神祕面紗，拉近管風琴與我們的距離！\r\n\r\n3/19(三)14:30\r\n\r\n【春日管風琴派對】\r\n\r\n※管風琴家：劉信宏、魏佳玲\r\n\r\n立即購票\r\n\r\n\r\n\r\n3月初春暖陽，來衛武營開一場管風琴派對！此月精選最耳熟能詳的古典樂金曲，從威爾第歌劇《阿依達》裡燦爛輝煌的凱旋進行曲，到葛利格《皮爾金》戲劇配樂中群魔亂舞的〈山大王的宮殿〉，從聖歌天籟的〈奇異恩典〉到管風琴家改編的《小小世界》和《當你許下星願時》，此外還有最受歡迎的聖桑《動物狂歡節》選粹，更特別的是，本場管風琴還會變身為「管絃樂團」，與鋼琴獨奏演出莫札特最寧靜甜美的第21號鋼琴協奏曲第二樂章，為派對帶來最璀璨的音樂饗宴。\r\n\r\n \r\n\r\n孟德爾頌：第三號管風琴奏鳴曲，作品編號65之3，第一樂章\r\n\r\n威爾第：凱旋進行曲，選自歌劇《阿伊達》\r\n\r\n葛利格：〈山魔王的宮殿〉選自《皮爾金組曲》\r\n\r\n聖桑：《動物狂歡節》選粹\r\n\r\nI. 〈獅子之序曲與皇家進行曲〉\r\n\r\nII. 〈母雞與公雞〉\r\n\r\nXIII. 〈天鵝〉\r\n\r\nXIV.〈終曲〉\r\n\r\n斯萬改編：《奇異恩典》\r\n\r\n魏佳玲改編：《小小世界》和《當你許下星願時》\r\n\r\n斯萬改編：《聖安妮節慶觸技曲》\r\n\r\n莫札特：C大調鋼琴協奏曲第21號，第二樂章行板\r\n\r\n  好書推薦  \r\n\r\n《打開管風琴的祕密》\r\n\r\n由來自德國的繪本作者西妮雅．博尼希編寫繪製，衛武營取得授權後和時報出版合作在臺發行繁體中文版。以淺顯易懂的文字和充滿童趣插圖，講解樂器之王管風琴的組成構造、發聲原理，以及衛武營音樂廳中全亞洲最大管風琴，如何由德國波昂的百年管風琴製造廠Johannes Klais Orgelbau， 歷經三年多時間設計製造，並橫跨9,500多公里搬運來到高雄衛武營組裝完工的巨大挑戰 。\r\n►購買連結\r\n\r\n《打開管風琴的祕密》圖片\r\n \r\n\r\n  藝文支持  \r\n\r\n瑞儀教育基金會', `organizer`='國家表演藝術中心衛武營國家藝術文化中心', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-19 00:00:00', `end_date`='2025-03-19 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
