INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ab26b32418d001b80a', '【中市圖清水分館】3月-與食俱進：自然環境與食農教育主題書展', '為推廣食農教育，強化飲食、環境與農業之連結，傳承與發揚飲食及農業文化，所規劃之主題書展活動。鼓勵民眾透過閱讀，提升對農業生產、友善環境、農業議題之瞭解。本展精選自然環境、食農等相關書目。歡迎閱覽！\r\n\r\n※臺中市立圖書館清水分館，工程期間展覽地點移至臨時服務處。', '臺中市立圖書館清水分館', '臺中市清水區', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '清水區（臺中市）=', 24.29205743, 120.5809094, '無資料', 'https://reurl.cc/kM6479', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖清水分館】3月-與食俱進：自然環境與食農教育主題書展', `description`='為推廣食農教育，強化飲食、環境與農業之連結，傳承與發揚飲食及農業文化，所規劃之主題書展活動。鼓勵民眾透過閱讀，提升對農業生產、友善環境、農業議題之瞭解。本展精選自然環境、食農等相關書目。歡迎閱覽！\r\n\r\n※臺中市立圖書館清水分館，工程期間展覽地點移至臨時服務處。', `organizer`='臺中市立圖書館清水分館', `address`='臺中市清水區', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='清水區（臺中市）=', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://reurl.cc/kM6479', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ab26b32418d001b80b', '《2025愛你愛我週末音樂會》 -《泰雅男伶》', '成員是來自新竹縣尖石、五峰鄉各行各業的四位泰雅族男高音。當中有學校老師、音樂、文化工作者、以及北藝大在校生，來歷皆如此不同，卻因為藝術把男伶聚在一起，都有著一顆熱愛音樂的心。\r\n本場曲目將帶來跨足古典、宗教、爵士、當代、音樂劇以及民族音樂等多種不同風貌歌曲，並且以獨唱或重唱編制形式演出，邀請大家一同來聆聽。', '音樂巷文化股份有限公司', '新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '音樂巷(原竹東文創藝術村)', 24.73075802, 121.0753632, '無資料', 'https://musicalley.freestore.tw/ticket', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025愛你愛我週末音樂會》 -《泰雅男伶》', `description`='成員是來自新竹縣尖石、五峰鄉各行各業的四位泰雅族男高音。當中有學校老師、音樂、文化工作者、以及北藝大在校生，來歷皆如此不同，卻因為藝術把男伶聚在一起，都有著一顆熱愛音樂的心。\r\n本場曲目將帶來跨足古典、宗教、爵士、當代、音樂劇以及民族音樂等多種不同風貌歌曲，並且以獨唱或重唱編制形式演出，邀請大家一同來聆聽。', `organizer`='音樂巷文化股份有限公司', `address`='新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='音樂巷(原竹東文創藝術村)', `latitude`=24.73075802, `longitude`=121.0753632, `ticket_price`='無資料', `source_url`='https://musicalley.freestore.tw/ticket', `image_url`='[]';
