INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ab26b32418d001b80e', '【中市圖清水分館 x 合院日常】幸福語見：台語囡仔古主題書展', '清水圖書館與合院日常於2025年再度攜手合作，以台灣母語-台語為規劃之主題書展活動。將母語生活化，透過繪本及台語文學選書，鼓勵親子、祖孫一起說台語、唱童謠，重新發掘世代相傳的傳說與真實存在過的故事，將無形珍寶的美麗語言傳承下去。予故事繼續行，予台語袂孤單。歡迎做伙來欣賞台語囡仔古！', '臺中市立圖書館清水分館', '臺中市清水區', '2025-03-07 00:00:00', '2025-04-27 00:00:00', '清水區（臺中市）=', 24.29205743, 120.5809094, '無資料', 'https://reurl.cc/kM6479', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖清水分館 x 合院日常】幸福語見：台語囡仔古主題書展', `description`='清水圖書館與合院日常於2025年再度攜手合作，以台灣母語-台語為規劃之主題書展活動。將母語生活化，透過繪本及台語文學選書，鼓勵親子、祖孫一起說台語、唱童謠，重新發掘世代相傳的傳說與真實存在過的故事，將無形珍寶的美麗語言傳承下去。予故事繼續行，予台語袂孤單。歡迎做伙來欣賞台語囡仔古！', `organizer`='臺中市立圖書館清水分館', `address`='臺中市清水區', `start_date`='2025-03-07 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='清水區（臺中市）=', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://reurl.cc/kM6479', `image_url`='[]';
