INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ab26b32418d001b810', '《2025愛你愛我週末音樂會》 -《親愛的孩子》', '記得第一場售票的音樂會，帶著我們一路走到了現在，從原本的25人，到現在的90人大團體，莫忘，我們都還是親愛的孩子', '音樂巷文化股份有限公司', '新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', '2025-04-06 00:00:00', '2025-04-06 00:00:00', '音樂巷(原竹東文創藝術村)', 24.73075802, 121.0753632, '無資料', 'https://musicalley.freestore.tw/ticket', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025愛你愛我週末音樂會》 -《親愛的孩子》', `description`='記得第一場售票的音樂會，帶著我們一路走到了現在，從原本的25人，到現在的90人大團體，莫忘，我們都還是親愛的孩子', `organizer`='音樂巷文化股份有限公司', `address`='新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', `start_date`='2025-04-06 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='音樂巷(原竹東文創藝術村)', `latitude`=24.73075802, `longitude`=121.0753632, `ticket_price`='無資料', `source_url`='https://musicalley.freestore.tw/ticket', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ab26b32418d001b811', '《2025愛你愛我週末音樂會》 -【小城故事】茶席劇場', '「小城故事多，充滿喜和樂」\r\n2025【小城故事】茶席劇場，以「功夫相聲」、「即興故事」、「組曲彈唱」為節目主題 ，帶領觀眾以相聲探索城事 ，讓喜劇走進生活！沐寧相聲攜手親愛愛樂，打造特色茶席劇場，營造復古茶館情境，台上說書唱曲，台下喝茶聽戲，邊喝茶邊看相聲，快樂最「對味」！相聲不再是老掉牙的傳統藝術，本團引進新型態喜劇元素-即興企劃，帶領觀眾共創劇情，收穫驚喜連連的劇場「笑果」！我們期待和親愛愛樂一起玩轉相聲、擁抱喜劇，聽見最有趣的城事笑談！\r\n', '音樂巷文化股份有限公司', '新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '音樂巷(原竹東文創藝術村)', 24.73075802, 121.0753632, '無資料', 'https://musicalley.freestore.tw/ticket', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025愛你愛我週末音樂會》 -【小城故事】茶席劇場', `description`='「小城故事多，充滿喜和樂」\r\n2025【小城故事】茶席劇場，以「功夫相聲」、「即興故事」、「組曲彈唱」為節目主題 ，帶領觀眾以相聲探索城事 ，讓喜劇走進生活！沐寧相聲攜手親愛愛樂，打造特色茶席劇場，營造復古茶館情境，台上說書唱曲，台下喝茶聽戲，邊喝茶邊看相聲，快樂最「對味」！相聲不再是老掉牙的傳統藝術，本團引進新型態喜劇元素-即興企劃，帶領觀眾共創劇情，收穫驚喜連連的劇場「笑果」！我們期待和親愛愛樂一起玩轉相聲、擁抱喜劇，聽見最有趣的城事笑談！\r\n', `organizer`='音樂巷文化股份有限公司', `address`='新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='音樂巷(原竹東文創藝術村)', `latitude`=24.73075802, `longitude`=121.0753632, `ticket_price`='無資料', `source_url`='https://musicalley.freestore.tw/ticket', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ab26b32418d001b812', '《2025愛你愛我週末音樂會》 -音樂與生活的共鳴--黑膠唱片中的經典回聲', '音樂，總是在我們的生命中悄然流淌，如同一位默默陪伴的老朋友，為日常注入溫度與色彩。當黑膠唱針輕落，一段旋律便彷彿穿越時光，帶我們回到那些值得回味的瞬間。', '音樂巷文化股份有限公司', '新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '音樂巷(原竹東文創藝術村)', 24.73075802, 121.0753632, '無資料', 'https://musicalley.freestore.tw/ticket', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025愛你愛我週末音樂會》 -音樂與生活的共鳴--黑膠唱片中的經典回聲', `description`='音樂，總是在我們的生命中悄然流淌，如同一位默默陪伴的老朋友，為日常注入溫度與色彩。當黑膠唱針輕落，一段旋律便彷彿穿越時光，帶我們回到那些值得回味的瞬間。', `organizer`='音樂巷文化股份有限公司', `address`='新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='音樂巷(原竹東文創藝術村)', `latitude`=24.73075802, `longitude`=121.0753632, `ticket_price`='無資料', `source_url`='https://musicalley.freestore.tw/ticket', `image_url`='[]';
