INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ab26b32418d001b814', '《2025愛你愛我週末音樂會》 - 聲旅奇緣：跨世新連音人聲音樂會', '這場音樂會是由兩個人聲團體所組成，曲風從流行到搖滾、從民謠風唱到山頂的黑狗兄，希望透過音樂，帶給大家歡愉的午後。\r\n同時，將邀請親愛愛樂特別演出，帶來全球首演的弦樂。\r\n讓我們一起沉浸在聲音的旅程中，感受音樂所帶來的美好。\r\n', '音樂巷文化股份有限公司', '新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '音樂巷(原竹東文創藝術村)', 24.73075802, 121.0753632, '無資料', 'https://musicalley.freestore.tw/ticket', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025愛你愛我週末音樂會》 - 聲旅奇緣：跨世新連音人聲音樂會', `description`='這場音樂會是由兩個人聲團體所組成，曲風從流行到搖滾、從民謠風唱到山頂的黑狗兄，希望透過音樂，帶給大家歡愉的午後。\r\n同時，將邀請親愛愛樂特別演出，帶來全球首演的弦樂。\r\n讓我們一起沉浸在聲音的旅程中，感受音樂所帶來的美好。\r\n', `organizer`='音樂巷文化股份有限公司', `address`='新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='音樂巷(原竹東文創藝術村)', `latitude`=24.73075802, `longitude`=121.0753632, `ticket_price`='無資料', `source_url`='https://musicalley.freestore.tw/ticket', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ab26b32418d001b815', '《2025愛你愛我週末音樂會》 - 《Lawa的彩虹橋》', '生命，會給你什麼？每個人的答案，或許都不一樣。這是一場關於愛與勇氣的冒險。', '音樂巷文化股份有限公司', '新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '音樂巷(原竹東文創藝術村)', 24.73075802, 121.0753632, '無資料', 'https://musicalley.freestore.tw/ticket', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025愛你愛我週末音樂會》 - 《Lawa的彩虹橋》', `description`='生命，會給你什麼？每個人的答案，或許都不一樣。這是一場關於愛與勇氣的冒險。', `organizer`='音樂巷文化股份有限公司', `address`='新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='音樂巷(原竹東文創藝術村)', `latitude`=24.73075802, `longitude`=121.0753632, `ticket_price`='無資料', `source_url`='https://musicalley.freestore.tw/ticket', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ab26b32418d001b816', '《2025愛你愛我週末音樂會》 - 樂來樂好-鋼琴演奏會', '從巴洛克、古典、浪漫派到現代，\r\n鋼琴家許幼莉\r\n無菜單料理音樂饗宴～\r\n初夏午後獨家推出，限量名額\r\n彈與談，與您一同品味…\r\n', '音樂巷文化股份有限公司', '新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', '2025-05-17 00:00:00', '2025-05-17 00:00:00', '音樂巷(原竹東文創藝術村)', 24.73075802, 121.0753632, '無資料', 'https://musicalley.freestore.tw/ticket', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025愛你愛我週末音樂會》 - 樂來樂好-鋼琴演奏會', `description`='從巴洛克、古典、浪漫派到現代，\r\n鋼琴家許幼莉\r\n無菜單料理音樂饗宴～\r\n初夏午後獨家推出，限量名額\r\n彈與談，與您一同品味…\r\n', `organizer`='音樂巷文化股份有限公司', `address`='新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='音樂巷(原竹東文創藝術村)', `latitude`=24.73075802, `longitude`=121.0753632, `ticket_price`='無資料', `source_url`='https://musicalley.freestore.tw/ticket', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ab26b32418d001b817', '《2025愛你愛我週末音樂會》 - 以愛之名 In the name of love', '人～因愛而生，因愛而活，因愛而死！\r\nAgape的愛，Phileo的愛，Eros的愛…..\r\n無論是超越的愛，親情流轉，浪漫情懷或是對生命的熱愛，都將在歌聲與彈指間流淌。\r\n以愛之名，相聚於竹東親愛提琴村，以音樂傳遞愛與感動，呈現多種愛的方程式～\r\n邀您一起來聆聽music for love，共度一場美好的音樂響宴！\r\n', '音樂巷文化股份有限公司', '新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', '2025-06-01 00:00:00', '2025-06-01 00:00:00', '音樂巷(原竹東文創藝術村)', 24.73075802, 121.0753632, '無資料', 'https://musicalley.freestore.tw/ticket', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025愛你愛我週末音樂會》 - 以愛之名 In the name of love', `description`='人～因愛而生，因愛而活，因愛而死！\r\nAgape的愛，Phileo的愛，Eros的愛…..\r\n無論是超越的愛，親情流轉，浪漫情懷或是對生命的熱愛，都將在歌聲與彈指間流淌。\r\n以愛之名，相聚於竹東親愛提琴村，以音樂傳遞愛與感動，呈現多種愛的方程式～\r\n邀您一起來聆聽music for love，共度一場美好的音樂響宴！\r\n', `organizer`='音樂巷文化股份有限公司', `address`='新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', `start_date`='2025-06-01 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='音樂巷(原竹東文創藝術村)', `latitude`=24.73075802, `longitude`=121.0753632, `ticket_price`='無資料', `source_url`='https://musicalley.freestore.tw/ticket', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ab26b32418d001b818', '《2025愛你愛我週末音樂會》 - 《黑孩子音樂會》', '經歷過黑暗的孩子，更渴望光明！透過音樂，詮釋黑孩子的生命故事。', '音樂巷文化股份有限公司', '新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', '2025-06-07 00:00:00', '2025-06-07 00:00:00', '音樂巷(原竹東文創藝術村)', 24.73075802, 121.0753632, '無資料', 'https://musicalley.freestore.tw/ticket', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025愛你愛我週末音樂會》 - 《黑孩子音樂會》', `description`='經歷過黑暗的孩子，更渴望光明！透過音樂，詮釋黑孩子的生命故事。', `organizer`='音樂巷文化股份有限公司', `address`='新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', `start_date`='2025-06-07 00:00:00', `end_date`='2025-06-07 00:00:00', `location`='音樂巷(原竹東文創藝術村)', `latitude`=24.73075802, `longitude`=121.0753632, `ticket_price`='無資料', `source_url`='https://musicalley.freestore.tw/ticket', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ab26b32418d001b819', '《2025愛你愛我週末音樂會》 - 莫札特弦樂五重奏', '由國立臺南藝術大學音樂學系的五位教授攜手呈現「莫札特弦樂五重奏系列」的第三場音樂會，帶來莫札特晚年最具成熟風格的兩首弦樂五重奏——K. 593與K. 614。這兩部作品兼具深邃的音樂對話與輕盈的歌唱性，是莫札特室內樂創作中的瑰寶。', '音樂巷文化股份有限公司', '新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', '2025-06-14 00:00:00', '2025-06-14 00:00:00', '音樂巷(原竹東文創藝術村)', 24.73075802, 121.0753632, '無資料', 'https://musicalley.freestore.tw/ticket', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025愛你愛我週末音樂會》 - 莫札特弦樂五重奏', `description`='由國立臺南藝術大學音樂學系的五位教授攜手呈現「莫札特弦樂五重奏系列」的第三場音樂會，帶來莫札特晚年最具成熟風格的兩首弦樂五重奏——K. 593與K. 614。這兩部作品兼具深邃的音樂對話與輕盈的歌唱性，是莫札特室內樂創作中的瑰寶。', `organizer`='音樂巷文化股份有限公司', `address`='新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', `start_date`='2025-06-14 00:00:00', `end_date`='2025-06-14 00:00:00', `location`='音樂巷(原竹東文創藝術村)', `latitude`=24.73075802, `longitude`=121.0753632, `ticket_price`='無資料', `source_url`='https://musicalley.freestore.tw/ticket', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ab26b32418d001b81a', '《2025愛你愛我週末音樂會》 - 午后月光——范俊逸沙龍演唱會', '詩人·小說家·詞曲作家·歌手·廣播主持人，這些標籤交織出范俊逸的藝術生命。他的文字溫柔深邃，他的音樂如月色般靜靜流淌，影響了一代人的記憶與情感。他用詩寫歌，用音樂講述故事，用廣播陪伴無數個靜謐的夜晚。\r\n這個午后，他將在舞台上，為你唱歌、朗讀、分享，與你共度一場詩意滿溢的音樂時光。\r\n從他創作的《想你的夜》到《不是我不小心》，從《河岸月光》到《我在梵谷的回憶等你》，他的作品承載著時光的餘韻，見證了音樂與文字如何在歲月裡悄然發酵，成為記憶的一部分。這場演唱會，不僅是一場音樂饗宴，更是一場心靈的對話，他將用音樂訴說人生的離合悲歡，也將以文學帶你穿越時光的河流。\r\n如果你曾因一首歌而落淚，因一段旋律而憶起某個遙遠的夜晚，那麼，這一個午后，你必須親自來聽。\r\n讓我們在音樂與文字的光影中，再次相遇。', '音樂巷文化股份有限公司', '新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', '2025-06-21 00:00:00', '2025-06-21 00:00:00', '音樂巷(原竹東文創藝術村)', 24.73075802, 121.0753632, '無資料', 'https://musicalley.freestore.tw/ticket', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025愛你愛我週末音樂會》 - 午后月光——范俊逸沙龍演唱會', `description`='詩人·小說家·詞曲作家·歌手·廣播主持人，這些標籤交織出范俊逸的藝術生命。他的文字溫柔深邃，他的音樂如月色般靜靜流淌，影響了一代人的記憶與情感。他用詩寫歌，用音樂講述故事，用廣播陪伴無數個靜謐的夜晚。\r\n這個午后，他將在舞台上，為你唱歌、朗讀、分享，與你共度一場詩意滿溢的音樂時光。\r\n從他創作的《想你的夜》到《不是我不小心》，從《河岸月光》到《我在梵谷的回憶等你》，他的作品承載著時光的餘韻，見證了音樂與文字如何在歲月裡悄然發酵，成為記憶的一部分。這場演唱會，不僅是一場音樂饗宴，更是一場心靈的對話，他將用音樂訴說人生的離合悲歡，也將以文學帶你穿越時光的河流。\r\n如果你曾因一首歌而落淚，因一段旋律而憶起某個遙遠的夜晚，那麼，這一個午后，你必須親自來聽。\r\n讓我們在音樂與文字的光影中，再次相遇。', `organizer`='音樂巷文化股份有限公司', `address`='新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', `start_date`='2025-06-21 00:00:00', `end_date`='2025-06-21 00:00:00', `location`='音樂巷(原竹東文創藝術村)', `latitude`=24.73075802, `longitude`=121.0753632, `ticket_price`='無資料', `source_url`='https://musicalley.freestore.tw/ticket', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ac26b32418d001b81b', '《2025愛你愛我週末音樂會》 - 阿淘說唱《傳弦》', '日頭   從古老海洋出生\r\n時光浪漫  輕撫沙灘\r\n愛的足跡忽隱忽現\r\n是誰   在呼喚\r\n\r\n老伙房樑上  小蜘蛛靜靜補夢\r\n甕中沉睡的泥蜂  等待春天\r\n小河在腳下  淌過童年\r\n鳳凰花如火  化作思念的蝴蝶\r\n暗夜裡  星斗滿天\r\n\r\n追風少年飆成滿頭白髮，青春未曾老去，浪漫無可救藥。土地傳情，海洋呼喚，說不盡的故事唱不完的歌。阿淘說唱全新創作專輯《傳弦》， 觸動你的心弦!', '音樂巷文化股份有限公司', '新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', '2025-06-28 00:00:00', '2025-06-28 00:00:00', '音樂巷(原竹東文創藝術村)', 24.73075802, 121.0753632, '無資料', 'https://musicalley.freestore.tw/ticket', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2025愛你愛我週末音樂會》 - 阿淘說唱《傳弦》', `description`='日頭   從古老海洋出生\r\n時光浪漫  輕撫沙灘\r\n愛的足跡忽隱忽現\r\n是誰   在呼喚\r\n\r\n老伙房樑上  小蜘蛛靜靜補夢\r\n甕中沉睡的泥蜂  等待春天\r\n小河在腳下  淌過童年\r\n鳳凰花如火  化作思念的蝴蝶\r\n暗夜裡  星斗滿天\r\n\r\n追風少年飆成滿頭白髮，青春未曾老去，浪漫無可救藥。土地傳情，海洋呼喚，說不盡的故事唱不完的歌。阿淘說唱全新創作專輯《傳弦》， 觸動你的心弦!', `organizer`='音樂巷文化股份有限公司', `address`='新竹縣竹東鎮新竹縣竹東鎮東林路194巷8號', `start_date`='2025-06-28 00:00:00', `end_date`='2025-06-28 00:00:00', `location`='音樂巷(原竹東文創藝術村)', `latitude`=24.73075802, `longitude`=121.0753632, `ticket_price`='無資料', `source_url`='https://musicalley.freestore.tw/ticket', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ac26b32418d001b81c', '琂藏・樂現・遊藝會–台北琂樂堂喬遷開幕展', '金蛇獻瑞，迎春接福，台北琂樂堂藝文空間全新啟航！\r\n我們誠摯邀請您蒞臨新址，共同見證這個嶄新的開始。\r\n\r\n\r\n琂樂堂自2019年創立以來，始終堅持推薦嚴謹、真誠、純粹且充滿內蘊的藝術作品，致力於推動藝術成為日常的一部分。新址位於大稻埕的環河北路上，並以開幕展「琂藏・樂現・遊藝會」揭開新空間的序幕。\r\n\r\n「遊藝會」強調藝術的多元、豐富與無界，真正「好」的藝術創作，不僅是視覺的享受，更是心靈與思想的交流，是創作者與觀賞者之間奇妙的感通。而「琂藏‧樂現」則精選攝影、書法、繪畫等收藏作品，透過不同媒材，展現藝術獨特的魅力與深度。\r\n\r\n本次展覽為您帶來一場輕鬆而有趣的藝術體驗，在這個嶄新的空間裡，感受創作的溫度與故事。我們期待舊雨新知的到來，與您一同邂逅藝術的美好。\r\n\r\n\r\nGolden serpents bring fortune, welcoming the new year with blessings! Taipei Joyful Art Gallery embarks on a new journey, and we sincerely invite you to visit our new location and witness this fresh beginning together.\r\n\r\nSince its establishment in 2019, Joyful Art has been dedicated to curating rigorous, sincere, pure, and profoundly rich artworks, striving to make art an integral part of daily life. Our new venue remains on Huanhe North Road in Dadaocheng, and we are inaugurating the space with the opening exhibition "Hidden Joys Art Soirée."\r\n\r\n"Art Soirée" highlights the diversity, richness, and boundless nature of art. Truly exceptional artistic creations are not only a feast for the eyes but also an interaction of the soul and mind, forming a magical resonance between the creator and the audience. Meanwhile, "Hidden Joys" presents a curated selection of photography, calligraphy, and painting collections, showcasing the unique charm and depth of art through various mediums.\r\n\r\nThis exhibition offers a lighthearted and engaging artistic experience. In this brand-new space, you are invited to feel the warmth and stories behind the creations. We look forward to welcoming both old and new friends, coming together to embrace the beauty of art.\r\n\r\n\r\n\r\n\r\n琂藏・樂現・遊藝會–台北琂樂堂喬遷開幕展\r\nHidden Joys Art Soirée - The Grand Reopening Exhibition of Joyful Art Gallery\r\n\r\n日期 Date｜\r\n2025 . 03 . 07（Fri）~ 04 . 06（Sun） 11:00~19:00 （Closed on Monday）\r\n\r\n開幕 Opening｜\r\n2025 . 03 . 08（Sat） 15:00\r\n\r\n地點 Venue｜\r\n台北市大同區環河北路一段111號1樓 & 3樓  琂樂堂藝文空間  \r\nJoyful Art Gallery, 1F & 3F., No. 111, Sec. 1, Huanhe N. Rd., Datong Dist., Taipei City , Taiwan\r\n', '琂樂堂藝文空間', '臺北市大同區', '2025-03-07 00:00:00', '2025-04-06 00:00:00', '大同區（臺北市）=', 25.06342433, 121.5130417, '無資料', 'https://www.instagram.com/joyfulart_gallery/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='琂藏・樂現・遊藝會–台北琂樂堂喬遷開幕展', `description`='金蛇獻瑞，迎春接福，台北琂樂堂藝文空間全新啟航！\r\n我們誠摯邀請您蒞臨新址，共同見證這個嶄新的開始。\r\n\r\n\r\n琂樂堂自2019年創立以來，始終堅持推薦嚴謹、真誠、純粹且充滿內蘊的藝術作品，致力於推動藝術成為日常的一部分。新址位於大稻埕的環河北路上，並以開幕展「琂藏・樂現・遊藝會」揭開新空間的序幕。\r\n\r\n「遊藝會」強調藝術的多元、豐富與無界，真正「好」的藝術創作，不僅是視覺的享受，更是心靈與思想的交流，是創作者與觀賞者之間奇妙的感通。而「琂藏‧樂現」則精選攝影、書法、繪畫等收藏作品，透過不同媒材，展現藝術獨特的魅力與深度。\r\n\r\n本次展覽為您帶來一場輕鬆而有趣的藝術體驗，在這個嶄新的空間裡，感受創作的溫度與故事。我們期待舊雨新知的到來，與您一同邂逅藝術的美好。\r\n\r\n\r\nGolden serpents bring fortune, welcoming the new year with blessings! Taipei Joyful Art Gallery embarks on a new journey, and we sincerely invite you to visit our new location and witness this fresh beginning together.\r\n\r\nSince its establishment in 2019, Joyful Art has been dedicated to curating rigorous, sincere, pure, and profoundly rich artworks, striving to make art an integral part of daily life. Our new venue remains on Huanhe North Road in Dadaocheng, and we are inaugurating the space with the opening exhibition "Hidden Joys Art Soirée."\r\n\r\n"Art Soirée" highlights the diversity, richness, and boundless nature of art. Truly exceptional artistic creations are not only a feast for the eyes but also an interaction of the soul and mind, forming a magical resonance between the creator and the audience. Meanwhile, "Hidden Joys" presents a curated selection of photography, calligraphy, and painting collections, showcasing the unique charm and depth of art through various mediums.\r\n\r\nThis exhibition offers a lighthearted and engaging artistic experience. In this brand-new space, you are invited to feel the warmth and stories behind the creations. We look forward to welcoming both old and new friends, coming together to embrace the beauty of art.\r\n\r\n\r\n\r\n\r\n琂藏・樂現・遊藝會–台北琂樂堂喬遷開幕展\r\nHidden Joys Art Soirée - The Grand Reopening Exhibition of Joyful Art Gallery\r\n\r\n日期 Date｜\r\n2025 . 03 . 07（Fri）~ 04 . 06（Sun） 11:00~19:00 （Closed on Monday）\r\n\r\n開幕 Opening｜\r\n2025 . 03 . 08（Sat） 15:00\r\n\r\n地點 Venue｜\r\n台北市大同區環河北路一段111號1樓 & 3樓  琂樂堂藝文空間  \r\nJoyful Art Gallery, 1F & 3F., No. 111, Sec. 1, Huanhe N. Rd., Datong Dist., Taipei City , Taiwan\r\n', `organizer`='琂樂堂藝文空間', `address`='臺北市大同區', `start_date`='2025-03-07 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='大同區（臺北市）=', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='無資料', `source_url`='https://www.instagram.com/joyfulart_gallery/', `image_url`='[]';
