INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ac26b32418d001b820', '114年3-4月主題書展：《童心飛翔》學童與幼兒色彩與想像力的奇幻旅程', '114年3-4月主題書展\r\n《童心飛翔》：學童與幼兒色彩與想像力的奇幻旅程\r\n學童與幼兒的世界充滿無限的想像與好奇，邀請孩子們在閱讀與創作中，展開一段段奇妙的藝術冒險！精選繪本故事書籍，在趣味故事與繽紛插畫的陪伴下每一頁都是一場冒險，每一幅色彩都激發孩子的創造力，培養對閱讀的熱愛。\r\n有趣繽紛色彩繪本，激發孩子的藝術想像力\r\n互動式書籍，讓孩子在探索中學習\r\n培養對閱讀的熱愛與無窮好奇心\r\n讓孩子們在這片繽紛的藝術世界中自由飛翔，開啟他們的創作旅程，與創意一起飛翔！', '南投縣中寮鄉公所', '南投縣中寮鄉永平路270號四樓', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '南投縣中寮鄉立圖書館', 23.8790949, 120.7659918, '無資料', 'https://www.facebook.com/profile.php?id=100081167516780#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年3-4月主題書展：《童心飛翔》學童與幼兒色彩與想像力的奇幻旅程', `description`='114年3-4月主題書展\r\n《童心飛翔》：學童與幼兒色彩與想像力的奇幻旅程\r\n學童與幼兒的世界充滿無限的想像與好奇，邀請孩子們在閱讀與創作中，展開一段段奇妙的藝術冒險！精選繪本故事書籍，在趣味故事與繽紛插畫的陪伴下每一頁都是一場冒險，每一幅色彩都激發孩子的創造力，培養對閱讀的熱愛。\r\n有趣繽紛色彩繪本，激發孩子的藝術想像力\r\n互動式書籍，讓孩子在探索中學習\r\n培養對閱讀的熱愛與無窮好奇心\r\n讓孩子們在這片繽紛的藝術世界中自由飛翔，開啟他們的創作旅程，與創意一起飛翔！', `organizer`='南投縣中寮鄉公所', `address`='南投縣中寮鄉永平路270號四樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='南投縣中寮鄉立圖書館', `latitude`=23.8790949, `longitude`=120.7659918, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100081167516780#', `image_url`='[]';
