INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ac26b32418d001b822', '「織藝循環-植染采川」展覽', '展覽以「舊衣回收的循環利用」為核心主題，透過收集舊衣物與老布料，將其回收再利用，結合社區長者、青年與孩童的創意發想，展現世代共創的美學與永續精神，並深化社區的文化連結。\r\n展場規劃四大展區：包含「織藝循環-打造永續創藝」、「植染采川-在地創生實踐」、「社區藝術-生活療育美學」、「心享世成-世代互助共榮」等四大主題。歡迎民眾前往觀賞。', '苗栗縣藝耆協會', '苗栗縣頭份市中山路232號', '2025-03-07 00:00:00', '2025-03-16 00:00:00', '苗栗縣頭份市公所', 24.6861065, 120.9119437, '無資料', 'https://www.facebook.com/profile.php?id=100068581104944#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「織藝循環-植染采川」展覽', `description`='展覽以「舊衣回收的循環利用」為核心主題，透過收集舊衣物與老布料，將其回收再利用，結合社區長者、青年與孩童的創意發想，展現世代共創的美學與永續精神，並深化社區的文化連結。\r\n展場規劃四大展區：包含「織藝循環-打造永續創藝」、「植染采川-在地創生實踐」、「社區藝術-生活療育美學」、「心享世成-世代互助共榮」等四大主題。歡迎民眾前往觀賞。', `organizer`='苗栗縣藝耆協會', `address`='苗栗縣頭份市中山路232號', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='苗栗縣頭份市公所', `latitude`=24.6861065, `longitude`=120.9119437, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100068581104944#', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ac26b32418d001b823', '好客劇場（114年2月）', '放映影片介紹：\r\n神影之龍\r\n片長：約22分鐘\r\n內容簡介：\r\n一年一度的祥龍點睛典禮即將在伯公廟前舉行，但阿公辛苦多日作的糊龍，卻意外被阿福與喜妹嬉鬧玩耍下弄壞了。\r\n　　喜妹因為被阿公責備，生氣之下跑到庄外的伯公廟躲了起來。巧遇到頑皮的哈古，假扮成龍貓伯公要騙喜妹口袋裡的柿餅吃，不料卻把喜妹嚇昏了…\r\n一場人與土地守護神及伯公神祇相遇的奇妙故事就此展開!\r\n\r\n我的爸爸是森林之王\r\n片長：12分鐘\r\n內容簡介：\r\n孤獨的少年亞當，踏上前往森林、尋找他失散多年的父親的旅途。\r\n在森林深處，亞當面臨著一個難以置信的身分轉變：他的父親就是大腳怪。\r\n加入大腳怪父子以及他們所有古怪的森林動物朋友們，抵抗來自獵人的威脅，一起來體驗一生的冒險吧！\r\n\r\n諾亞方舟大冒險\r\n片長：約18分鐘\r\n內容簡介：\r\n由獅王帶領的眾動物們已經待在諾亞方舟上數個月，他們在海上漂流尋找著陸地。\r\n另一方面，總是喜歡在船上調皮搗蛋菲尼與好朋友莉亞，因為突如其來的意外讓兩人失足落水，無法回到方舟上的他們漂流到一座神祕的島嶼，發現一群特別的動物已經在這裡定居已久，而且不是很歡迎他們的到來...\r\n面對各種困境，菲尼、莉亞以及船上得動物們該如何是好？\r\n\r\n歡迎來好客劇場感受全新3D影片的精彩炫目，以及杜比全景聲音效，給您彷彿身歷其境的聽覺效果！', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '全票(好客劇場)+50;團體票(好客劇場)+40;優待票(好客劇場)+30', 'https://www.facebook.com/hakkapark/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='好客劇場（114年2月）', `description`='放映影片介紹：\r\n神影之龍\r\n片長：約22分鐘\r\n內容簡介：\r\n一年一度的祥龍點睛典禮即將在伯公廟前舉行，但阿公辛苦多日作的糊龍，卻意外被阿福與喜妹嬉鬧玩耍下弄壞了。\r\n　　喜妹因為被阿公責備，生氣之下跑到庄外的伯公廟躲了起來。巧遇到頑皮的哈古，假扮成龍貓伯公要騙喜妹口袋裡的柿餅吃，不料卻把喜妹嚇昏了…\r\n一場人與土地守護神及伯公神祇相遇的奇妙故事就此展開!\r\n\r\n我的爸爸是森林之王\r\n片長：12分鐘\r\n內容簡介：\r\n孤獨的少年亞當，踏上前往森林、尋找他失散多年的父親的旅途。\r\n在森林深處，亞當面臨著一個難以置信的身分轉變：他的父親就是大腳怪。\r\n加入大腳怪父子以及他們所有古怪的森林動物朋友們，抵抗來自獵人的威脅，一起來體驗一生的冒險吧！\r\n\r\n諾亞方舟大冒險\r\n片長：約18分鐘\r\n內容簡介：\r\n由獅王帶領的眾動物們已經待在諾亞方舟上數個月，他們在海上漂流尋找著陸地。\r\n另一方面，總是喜歡在船上調皮搗蛋菲尼與好朋友莉亞，因為突如其來的意外讓兩人失足落水，無法回到方舟上的他們漂流到一座神祕的島嶼，發現一群特別的動物已經在這裡定居已久，而且不是很歡迎他們的到來...\r\n面對各種困境，菲尼、莉亞以及船上得動物們該如何是好？\r\n\r\n歡迎來好客劇場感受全新3D影片的精彩炫目，以及杜比全景聲音效，給您彷彿身歷其境的聽覺效果！', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='全票(好客劇場)+50;團體票(好客劇場)+40;優待票(好客劇場)+30', `source_url`='https://www.facebook.com/hakkapark/', `image_url`='[]';
