INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ad26b32418d001b828', '2025苗北側廊系列1：小確幸—精選木雕作品展', '生活中的小確幸，來自那些微小卻溫暖的瞬間。當我們品嚐一口美味的冰淇淋、遇見可愛的貓狗，或擁抱柔軟的抱枕時，這些細微的感動都能療癒人心。苗北藝文中心精選三義木雕博物館的7件療癒系木雕作品，將這些幸福時刻轉化為動人的藝術創作，邀請您一同體驗木雕帶來的溫暖力量。\r\n木材因生長環境的不同，展現獨特的質地與紋理，年輪更記錄著歲月的軌跡。藝術家們透過雕刻，讓木頭承載故事與情感，將貓味十足的「冰淇淋」、溫暖的貓狗身影、孩子擁抱香菇的可愛畫面，化為細膩的雕塑作品。每一道刀刻痕跡，不僅展現木材的生命力，也傳遞著藝術家對生活的觀察與體悟。', '苗栗縣苗北藝文中心', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-03-04 00:00:00', '2025-03-30 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025苗北側廊系列1：小確幸—精選木雕作品展', `description`='生活中的小確幸，來自那些微小卻溫暖的瞬間。當我們品嚐一口美味的冰淇淋、遇見可愛的貓狗，或擁抱柔軟的抱枕時，這些細微的感動都能療癒人心。苗北藝文中心精選三義木雕博物館的7件療癒系木雕作品，將這些幸福時刻轉化為動人的藝術創作，邀請您一同體驗木雕帶來的溫暖力量。\r\n木材因生長環境的不同，展現獨特的質地與紋理，年輪更記錄著歲月的軌跡。藝術家們透過雕刻，讓木頭承載故事與情感，將貓味十足的「冰淇淋」、溫暖的貓狗身影、孩子擁抱香菇的可愛畫面，化為細膩的雕塑作品。每一道刀刻痕跡，不僅展現木材的生命力，也傳遞著藝術家對生活的觀察與體悟。', `organizer`='苗栗縣苗北藝文中心', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-03-04 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ad26b32418d001b829', '漢語教學課程', '講座使用授課老師編纂教材，內容是正教育部「推薦用字」、坊間用字標音文、白並呈 釋義通古貫今義切音合的\r\n古今臺灣台語妥當漢字詞、語、音典，說明漢語教學語法初級項目的語法形式、語義特點及語用條件，並配以有針對性的例句加以展示。學習掌握漢語語法系統，也能夠滿足學習過程中查疑、解難的具體需求。', '桃園市桃園區中正里辦公處', '桃園市桃園區', '2025-01-06 00:00:00', '2025-03-31 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='漢語教學課程', `description`='講座使用授課老師編纂教材，內容是正教育部「推薦用字」、坊間用字標音文、白並呈 釋義通古貫今義切音合的\r\n古今臺灣台語妥當漢字詞、語、音典，說明漢語教學語法初級項目的語法形式、語義特點及語用條件，並配以有針對性的例句加以展示。學習掌握漢語語法系統，也能夠滿足學習過程中查疑、解難的具體需求。', `organizer`='桃園市桃園區中正里辦公處', `address`='桃園市桃園區', `start_date`='2025-01-06 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
