INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ad26b32418d001b830', '苗栗特色館假日「現地創作」活動（114年2月-4場）', '為營造園區陶藝特色亮點，讓民眾體驗手作互動的樂趣，於國定假日下午1時至4時辦理苗栗特色館假日「現地創作」活動，邀請陶藝老師至園區以手捏陶與民眾互動體驗，敬邀大家於假日期間來苗栗特色館看展、嘗美食、感受陶藝手作樂趣。\r\n\r\n陶藝老師：\r\n2月09日／許錦色\r\n2月15日／邱俊斌\r\n2月16日／黃明玉\r\n2月28日／葉慧美', '苗栗縣政府', '苗栗縣公館鄉14鄰館南352號', '2025-02-09 00:00:00', '2025-02-28 00:00:00', '苗栗陶瓷農創園區', 25.0422099, 121.51947, '無資料', 'https://www.facebook.com/miaoliceramics', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗栗特色館假日「現地創作」活動（114年2月-4場）', `description`='為營造園區陶藝特色亮點，讓民眾體驗手作互動的樂趣，於國定假日下午1時至4時辦理苗栗特色館假日「現地創作」活動，邀請陶藝老師至園區以手捏陶與民眾互動體驗，敬邀大家於假日期間來苗栗特色館看展、嘗美食、感受陶藝手作樂趣。\r\n\r\n陶藝老師：\r\n2月09日／許錦色\r\n2月15日／邱俊斌\r\n2月16日／黃明玉\r\n2月28日／葉慧美', `organizer`='苗栗縣政府', `address`='苗栗縣公館鄉14鄰館南352號', `start_date`='2025-02-09 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='苗栗陶瓷農創園區', `latitude`=25.0422099, `longitude`=121.51947, `ticket_price`='無資料', `source_url`='https://www.facebook.com/miaoliceramics', `image_url`='[]';
