INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ae26b32418d001b849', '2025竹山迎媽祖祈福文化節', '2025竹山迎媽祖祈福文化節Coming Soon\r\n每年「農曆三月」許多地區都會舉辦媽祖遶境活動，今年竹山鎮公所與竹山連興宮(三級古蹟)、社寮四里社區發展協會共同辦理 2025竹山迎媽祖祈福文化節。\r\n連興宮軟身媽祖將於3月13日上午9點起駕回社寮四里繞境，媽祖於社寮四里駐駕時，分別舉辦4場晚會及平安餐活動(3/13山崇里北天宮、3/15社寮里武德宮、3/16富州里天元宮、3/17中央里靈天宮)；3月18日回鑾連興宮，當日下午1點30分起有一系列表演活動、安座大典、晚會期間還有歌手林紫君、葡萄姑娘粉絲團、曾瑋中 x Kuljelje將展現天籟歌喉，帶來精彩的演出。下午5點至廟口參加抽好運籤活動，就送平安餐券 及媽祖貼身磁鐵（數量有限，送完為止）。\r\n還有還有限量媽祖護身帽，只要在晚會期間有獎徵答成功，就有機會獲得。\r\n誠摯邀請鄉親們一起來參加一年一度的2025竹山迎媽祖祈福文化節，做伙來逗熱鬧。\r\n\r\n\r\n2025竹山迎媽祖祈福文化節活動\r\n活動期間：114年3月13日起至3月18日（回鑾晚會時間： 3月18日）\r\n活動地點：連興宮、北天宮 (山崇里)、武德宮 (社寮里)、天元宮 (富州里)、中央里（靈天宮)\r\n抽好運及平安餐預約：3月10日起可於竹山鎮公所APP預約參加3月18日抽好運吃平安餐活動(名額有限，額滿即止) \r\n活動相關問題可電洽：049-2642175轉303 葉小姐', '南投縣竹山鎮公所', '南投縣竹山鎮下橫街28號', '2025-03-13 00:00:00', '2025-03-18 00:00:00', '南投縣竹山鎮連興宮', 23.7560755, 120.6848322, '無資料', 'https://www.facebook.com/CHENTUNGMU', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025竹山迎媽祖祈福文化節', `description`='2025竹山迎媽祖祈福文化節Coming Soon\r\n每年「農曆三月」許多地區都會舉辦媽祖遶境活動，今年竹山鎮公所與竹山連興宮(三級古蹟)、社寮四里社區發展協會共同辦理 2025竹山迎媽祖祈福文化節。\r\n連興宮軟身媽祖將於3月13日上午9點起駕回社寮四里繞境，媽祖於社寮四里駐駕時，分別舉辦4場晚會及平安餐活動(3/13山崇里北天宮、3/15社寮里武德宮、3/16富州里天元宮、3/17中央里靈天宮)；3月18日回鑾連興宮，當日下午1點30分起有一系列表演活動、安座大典、晚會期間還有歌手林紫君、葡萄姑娘粉絲團、曾瑋中 x Kuljelje將展現天籟歌喉，帶來精彩的演出。下午5點至廟口參加抽好運籤活動，就送平安餐券 及媽祖貼身磁鐵（數量有限，送完為止）。\r\n還有還有限量媽祖護身帽，只要在晚會期間有獎徵答成功，就有機會獲得。\r\n誠摯邀請鄉親們一起來參加一年一度的2025竹山迎媽祖祈福文化節，做伙來逗熱鬧。\r\n\r\n\r\n2025竹山迎媽祖祈福文化節活動\r\n活動期間：114年3月13日起至3月18日（回鑾晚會時間： 3月18日）\r\n活動地點：連興宮、北天宮 (山崇里)、武德宮 (社寮里)、天元宮 (富州里)、中央里（靈天宮)\r\n抽好運及平安餐預約：3月10日起可於竹山鎮公所APP預約參加3月18日抽好運吃平安餐活動(名額有限，額滿即止) \r\n活動相關問題可電洽：049-2642175轉303 葉小姐', `organizer`='南投縣竹山鎮公所', `address`='南投縣竹山鎮下橫街28號', `start_date`='2025-03-13 00:00:00', `end_date`='2025-03-18 00:00:00', `location`='南投縣竹山鎮連興宮', `latitude`=23.7560755, `longitude`=120.6848322, `ticket_price`='無資料', `source_url`='https://www.facebook.com/CHENTUNGMU', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ae26b32418d001b84a', '2025台灣燈會：航城光點共創展', '航空城計畫區內的快速變動，融合新的展望、未來的藍圖，以及家園記憶和在地元素的保存，都是同時進行、同時發生的。透過駐地工作站的視角，帶領民眾認識航空城計畫及大園的文史脈絡。參加者以竹子組構燈籠基座，並覆以宣紙，以大園產業元素或意象進行彩繪創作，更可綴以自家的記憶物件，作為裝飾。活動將進行個人物件創作及共創兩部份，讓民眾在活動後可帶回自己的燈籠，也另留下一組彩繪成品，供團隊製成展示。大園的故事，讓大家一起來說！\r\n現場設有猜燈謎活動，歡迎賞燈的朋友們一起動動腦解謎，並上粉絲專頁回答問題參加抽獎！', '無資料', '桃園市大園區', '2025-02-12 00:00:00', '2025-03-02 00:00:00', '大園區（桃園市）=', 25.06384709, 121.21177, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會：航城光點共創展', `description`='航空城計畫區內的快速變動，融合新的展望、未來的藍圖，以及家園記憶和在地元素的保存，都是同時進行、同時發生的。透過駐地工作站的視角，帶領民眾認識航空城計畫及大園的文史脈絡。參加者以竹子組構燈籠基座，並覆以宣紙，以大園產業元素或意象進行彩繪創作，更可綴以自家的記憶物件，作為裝飾。活動將進行個人物件創作及共創兩部份，讓民眾在活動後可帶回自己的燈籠，也另留下一組彩繪成品，供團隊製成展示。大園的故事，讓大家一起來說！\r\n現場設有猜燈謎活動，歡迎賞燈的朋友們一起動動腦解謎，並上粉絲專頁回答問題參加抽獎！', `organizer`='無資料', `address`='桃園市大園區', `start_date`='2025-02-12 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='大園區（桃園市）=', `latitude`=25.06384709, `longitude`=121.21177, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ae26b32418d001b84b', '家與家的距離', '本展覽主要期望探討了原住民傳統手工藝與當代藝術的關係，並深入分析了台灣魯凱族女性的視角與歷史背景如何影響這一創作過程。傳統手工藝，特別是魯凱族女性的編織技術，不僅是日常生活中的實用品，更是文化信仰與族群認同的象徵。這些工藝傳達著對祖靈與自然的尊敬，並反映了魯凱族在歷史上多次遷徙過程中的文化變遷與適應。從台灣近代魯凱族的遷徙歷史來看，這些工藝形式也承載著族群的生存智慧與精神力量，成為傳統文化的持續記憶。\r\n\r\n在當代藝術中，這些傳統元素被創新地與現代社會議題結合。現代原住民藝術家，像安聖惠等，將傳統的編織技法與現代視覺語言、數位媒材融合，從而探索和表達對歷史記憶與文化認同的再創造。在魯凱族女性的編織過程中，織布技術的傳統圖案透過數位影像或互動媒體被重新詮釋，使其跨越了傳統工藝的界限，進一步拓展了表現範疇，賦予其新的現代意義。', '臺東縣政府', '臺東縣臺東市浙江路350號', '2025-01-19 00:00:00', '2025-03-11 00:00:00', '臺東美術館', 22.75165721, 121.1103647, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='家與家的距離', `description`='本展覽主要期望探討了原住民傳統手工藝與當代藝術的關係，並深入分析了台灣魯凱族女性的視角與歷史背景如何影響這一創作過程。傳統手工藝，特別是魯凱族女性的編織技術，不僅是日常生活中的實用品，更是文化信仰與族群認同的象徵。這些工藝傳達著對祖靈與自然的尊敬，並反映了魯凱族在歷史上多次遷徙過程中的文化變遷與適應。從台灣近代魯凱族的遷徙歷史來看，這些工藝形式也承載著族群的生存智慧與精神力量，成為傳統文化的持續記憶。\r\n\r\n在當代藝術中，這些傳統元素被創新地與現代社會議題結合。現代原住民藝術家，像安聖惠等，將傳統的編織技法與現代視覺語言、數位媒材融合，從而探索和表達對歷史記憶與文化認同的再創造。在魯凱族女性的編織過程中，織布技術的傳統圖案透過數位影像或互動媒體被重新詮釋，使其跨越了傳統工藝的界限，進一步拓展了表現範疇，賦予其新的現代意義。', `organizer`='臺東縣政府', `address`='臺東縣臺東市浙江路350號', `start_date`='2025-01-19 00:00:00', `end_date`='2025-03-11 00:00:00', `location`='臺東美術館', `latitude`=22.75165721, `longitude`=121.1103647, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ae26b32418d001b84c', '跟著聖王公去請土地公—─走讀大溪百吉復興宮開漳聖王聖誕慶典', '跟著聖王公去請土地公—─走讀大溪百吉復興宮開漳聖王聖誕慶典、介紹大溪、百吉、復興之歷史，並至現地參訪，了解相關歷史。', '桃園市立大溪木藝生態博物館', '桃園市大溪區', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '大溪區（桃園市）=', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='跟著聖王公去請土地公—─走讀大溪百吉復興宮開漳聖王聖誕慶典', `description`='跟著聖王公去請土地公—─走讀大溪百吉復興宮開漳聖王聖誕慶典、介紹大溪、百吉、復興之歷史，並至現地參訪，了解相關歷史。', `organizer`='桃園市立大溪木藝生態博物館', `address`='桃園市大溪區', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='大溪區（桃園市）=', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ae26b32418d001b84d', '澎湖憶舊-陳景容師生展', '陳景容教授偕同師生藝術家十人，前往望安花宅，展開為期一周的駐地創作。本次展出作品有現場速寫、素描、陶瓷版、粉彩、油畫、攝影等30多幅。\r\n', '澎湖縣政府', '澎湖縣馬公市中華路230號', '2025-03-29 00:00:00', '2025-06-01 00:00:00', '澎湖縣政府文化局', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='澎湖憶舊-陳景容師生展', `description`='陳景容教授偕同師生藝術家十人，前往望安花宅，展開為期一周的駐地創作。本次展出作品有現場速寫、素描、陶瓷版、粉彩、油畫、攝影等30多幅。\r\n', `organizer`='澎湖縣政府', `address`='澎湖縣馬公市中華路230號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='澎湖縣政府文化局', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ae26b32418d001b84e', '藝啟十方－工藝地圖上的繁星：幸福之源', '在快速流轉的現代社會中，工藝以緩慢而堅韌的姿態，深耕土地、融入生活，為我們提供重新審視生活本質的契機。114年是國立臺灣工藝研究發展中心創建「70+1」年之際，本中心規劃「藝啟十方一工藝地圖上的繁星」展覽，以「活工藝•工藝活」為核心，探索工藝家如何集結技術、美學及智慧，讓工藝創作成為與時代俱進的永續力量。\r\n\r\n本展覽以「一展二檔」，精彩呈現工藝品的豐富樣態，以雙重視角詮釋工藝之美：「慢活SLOW」專注於慢工藝的哲學，探索工藝在健康( Health) 與永續( Sustainability) 層面的深遠影響；而「樂活LOHAS」則以美學( Aesthetics)為核心，展現工藝如何豐富我們的生活與文化想像，兩檔展覽建構出「工藝漫活SLOHAS」的概念。\r\n\r\n從天然材質的溫潤觸感到創新設計的實用之美，每一件工藝品不僅是功能性與藝術性的結合，更是人與自然深層對話的橋梁，工藝之家在臺灣各地的工藝據點，如同工藝地圖上的繁星，藉由本展覽的策畫，串聯起工藝的繁星閃耀，連結臺灣土地的溫度、文化、根基與情感連結。\r\n\r\n這是一場探索工藝之美、生活之藝的旅程，也是一個關於未來的提案，讓我們在「漫活」中感受工藝的智慧，在「樂活」中觸摸永續的力量，攜手共築一個健康、美學與永續交織的世界，讓工藝點亮生活的光彩。', '國立臺灣工藝研究發展中心', '臺北市中正區南海路41號', '2025-03-22 00:00:00', '2025-05-11 00:00:00', '國立臺灣工藝研究發展中心-臺北當代工藝設計分館', 25.03240487, 121.5198839, '無資料', 'https://www.ntcri.gov.tw/home/zh-tw/exhibition/7476423', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝啟十方－工藝地圖上的繁星：幸福之源', `description`='在快速流轉的現代社會中，工藝以緩慢而堅韌的姿態，深耕土地、融入生活，為我們提供重新審視生活本質的契機。114年是國立臺灣工藝研究發展中心創建「70+1」年之際，本中心規劃「藝啟十方一工藝地圖上的繁星」展覽，以「活工藝•工藝活」為核心，探索工藝家如何集結技術、美學及智慧，讓工藝創作成為與時代俱進的永續力量。\r\n\r\n本展覽以「一展二檔」，精彩呈現工藝品的豐富樣態，以雙重視角詮釋工藝之美：「慢活SLOW」專注於慢工藝的哲學，探索工藝在健康( Health) 與永續( Sustainability) 層面的深遠影響；而「樂活LOHAS」則以美學( Aesthetics)為核心，展現工藝如何豐富我們的生活與文化想像，兩檔展覽建構出「工藝漫活SLOHAS」的概念。\r\n\r\n從天然材質的溫潤觸感到創新設計的實用之美，每一件工藝品不僅是功能性與藝術性的結合，更是人與自然深層對話的橋梁，工藝之家在臺灣各地的工藝據點，如同工藝地圖上的繁星，藉由本展覽的策畫，串聯起工藝的繁星閃耀，連結臺灣土地的溫度、文化、根基與情感連結。\r\n\r\n這是一場探索工藝之美、生活之藝的旅程，也是一個關於未來的提案，讓我們在「漫活」中感受工藝的智慧，在「樂活」中觸摸永續的力量，攜手共築一個健康、美學與永續交織的世界，讓工藝點亮生活的光彩。', `organizer`='國立臺灣工藝研究發展中心', `address`='臺北市中正區南海路41號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='國立臺灣工藝研究發展中心-臺北當代工藝設計分館', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://www.ntcri.gov.tw/home/zh-tw/exhibition/7476423', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ae26b32418d001b84f', '2025臺北文學季', '文化局主辦的「臺北文學季」將自3月2日正式起跑，並於今（25）日在臺北市長官邸藝文沙龍舉辦活動起跑記者會。今年文學季以「靈距離」為題，希望透過科技工具等多重議題探討數位浪潮下的「溝通術」，從3月到6月陸續以系列活動、主題特展、市圖好書展、國際華文作家及文學閱影展等分別策畫，以「靈距離」的概念為核心出發，邀請民眾一起拉近文學與你我的距離。記者會開場由景美女中與成功高中兩校手語社合作，以充滿活力的舞蹈結合手語動作，呈現出溝通的不同形式與熱烈可能性，最後更於現場教學「我們之間沒有距離」的手語動作給在場貴賓。\r\n本次臺北文學季系列活動更改過去型態，除了傳統講座、對談外，本次更新增多元型態、更多元、「斜槓」領域的講師群。「靈魂觸碰」邀請到作家/影評人馬欣、諮商心理師海苔熊以「溝通」為主題暢聊對話；關注性別的作家/學者李欣倫與腦科學專家/學者謝伯讓，談談世俗的刻板印象究竟有沒有道理；作家/記者李桐豪搭配音樂/訪談類型YouTuber那那大師，則要暢談「訪問的藝術」與倫理；作家/樂評人馬世芳在明星咖啡館的「飲食體驗」則帶出日常餐桌對話；演員陳家逵的「限定讀劇會」則教導民眾學會聲音表情的溝通術。', '臺北市政府文化局', '臺北市全區域', '2025-03-02 00:00:00', '2025-06-05 00:00:00', '臺北市', 0, 0, '無資料', 'https://literature.festival.taipei/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺北文學季', `description`='文化局主辦的「臺北文學季」將自3月2日正式起跑，並於今（25）日在臺北市長官邸藝文沙龍舉辦活動起跑記者會。今年文學季以「靈距離」為題，希望透過科技工具等多重議題探討數位浪潮下的「溝通術」，從3月到6月陸續以系列活動、主題特展、市圖好書展、國際華文作家及文學閱影展等分別策畫，以「靈距離」的概念為核心出發，邀請民眾一起拉近文學與你我的距離。記者會開場由景美女中與成功高中兩校手語社合作，以充滿活力的舞蹈結合手語動作，呈現出溝通的不同形式與熱烈可能性，最後更於現場教學「我們之間沒有距離」的手語動作給在場貴賓。\r\n本次臺北文學季系列活動更改過去型態，除了傳統講座、對談外，本次更新增多元型態、更多元、「斜槓」領域的講師群。「靈魂觸碰」邀請到作家/影評人馬欣、諮商心理師海苔熊以「溝通」為主題暢聊對話；關注性別的作家/學者李欣倫與腦科學專家/學者謝伯讓，談談世俗的刻板印象究竟有沒有道理；作家/記者李桐豪搭配音樂/訪談類型YouTuber那那大師，則要暢談「訪問的藝術」與倫理；作家/樂評人馬世芳在明星咖啡館的「飲食體驗」則帶出日常餐桌對話；演員陳家逵的「限定讀劇會」則教導民眾學會聲音表情的溝通術。', `organizer`='臺北市政府文化局', `address`='臺北市全區域', `start_date`='2025-03-02 00:00:00', `end_date`='2025-06-05 00:00:00', `location`='臺北市', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://literature.festival.taipei/', `image_url`='[]';
