INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf76ae26b32418d001b857', '2025臺北文學季：聲音的自我修養術（讀劇會）', '文化局主辦的「臺北文學季」將自3月2日正式起跑，並於今（25）日在臺北市長官邸藝文沙龍舉辦活動起跑記者會。今年文學季以「靈距離」為題，希望透過科技工具等多重議題探討數位浪潮下的「溝通術」，從3月到6月陸續以系列活動、主題特展、市圖好書展、國際華文作家及文學閱影展等分別策畫，以「靈距離」的概念為核心出發，邀請民眾一起拉近文學與你我的距離。記者會開場由景美女中與成功高中兩校手語社合作，以充滿活力的舞蹈結合手語動作，呈現出溝通的不同形式與熱烈可能性，最後更於現場教學「我們之間沒有距離」的手語動作給在場貴賓。\r\n本次臺北文學季系列活動更改過去型態，除了傳統講座、對談外，本次更新增多元型態、更多元、「斜槓」領域的講師群。「靈魂觸碰」邀請到作家/影評人馬欣、諮商心理師海苔熊以「溝通」為主題暢聊對話；關注性別的作家/學者李欣倫與腦科學專家/學者謝伯讓，談談世俗的刻板印象究竟有沒有道理；作家/記者李桐豪搭配音樂/訪談類型YouTuber那那大師，則要暢談「訪問的藝術」與倫理；作家/樂評人馬世芳在明星咖啡館的「飲食體驗」則帶出日常餐桌對話；演員陳家逵的「限定讀劇會」則教導民眾學會聲音表情的溝通術。', '臺北市政府文化局', '臺北市中正區', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '中正區（臺北市）=', 25.03240487, 121.5198839, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺北文學季：聲音的自我修養術（讀劇會）', `description`='文化局主辦的「臺北文學季」將自3月2日正式起跑，並於今（25）日在臺北市長官邸藝文沙龍舉辦活動起跑記者會。今年文學季以「靈距離」為題，希望透過科技工具等多重議題探討數位浪潮下的「溝通術」，從3月到6月陸續以系列活動、主題特展、市圖好書展、國際華文作家及文學閱影展等分別策畫，以「靈距離」的概念為核心出發，邀請民眾一起拉近文學與你我的距離。記者會開場由景美女中與成功高中兩校手語社合作，以充滿活力的舞蹈結合手語動作，呈現出溝通的不同形式與熱烈可能性，最後更於現場教學「我們之間沒有距離」的手語動作給在場貴賓。\r\n本次臺北文學季系列活動更改過去型態，除了傳統講座、對談外，本次更新增多元型態、更多元、「斜槓」領域的講師群。「靈魂觸碰」邀請到作家/影評人馬欣、諮商心理師海苔熊以「溝通」為主題暢聊對話；關注性別的作家/學者李欣倫與腦科學專家/學者謝伯讓，談談世俗的刻板印象究竟有沒有道理；作家/記者李桐豪搭配音樂/訪談類型YouTuber那那大師，則要暢談「訪問的藝術」與倫理；作家/樂評人馬世芳在明星咖啡館的「飲食體驗」則帶出日常餐桌對話；演員陳家逵的「限定讀劇會」則教導民眾學會聲音表情的溝通術。', `organizer`='臺北市政府文化局', `address`='臺北市中正區', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='中正區（臺北市）=', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
