INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9364109', '114年2月28日至3月2日連續假期，臺北市建國假日花市仍維持週六、日(114年3月1、2日)營業。', '本市其他產業活動相關資訊請利用「臺北市政府產業發展局網站」（網址：http://www.doed.gov.taipei/）新聞稿或活動訊息查詢。', '臺北市政府產業發展局', '無資料', '2025-02-27 00:00:00', '2025-03-03 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=DAAEF5BE480CE099', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年2月28日至3月2日連續假期，臺北市建國假日花市仍維持週六、日(114年3月1、2日)營業。', `description`='本市其他產業活動相關資訊請利用「臺北市政府產業發展局網站」（網址：http://www.doed.gov.taipei/）新聞稿或活動訊息查詢。', `organizer`='臺北市政府產業發展局', `address`='無資料', `start_date`='2025-02-27 00:00:00', `end_date`='2025-03-03 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=DAAEF5BE480CE099', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9364088', '都市田園家庭種菜樂3月號北市產業局　綠化教育講座 熱烈招生中，請注意新規報名辦法', '　　114年度都市田園教育講座3月份課程來囉!為鼓勵市民運用閒置空間栽種蔬果花卉，一同體會都市農夫的樂趣，北市產業局於3月8、15、22、29日懷生國中綠化教室開辦「臺北市民田園綠化教育講座」系列，今年度規劃四大主題：A都市農園藝初階課程、B都市農園藝進階課程、C食農教育推廣及應用、D綠化療育及趣味應用課程，請見分類標示，搭配各類DIY手作課程，歡迎市民朋友一同動手玩園藝。　　3月份課程包括有「春滿台北城 市花杜鵑的認識與栽培 」、「如何打造一座生物多樣性的水花園 」、「如何種好米，選好米及煮好飯 」、「臺灣茶的認識與品評 」、「初階蔬菜栽培技巧 」、「植栽的基礎維護管理 」、「居家蔬菜播種及繁殖綠手指 」、「有機蔬菜 裁培技術 」，課程內容多元且兼具養生實用性及保健性，因課程名額有限，請市民朋友儘早報名。　　相關課程內容與時間請上「台北市社區綠化聯盟促進會」網站查詢，報名時間為週一至週五上午9:30-11:30及下午1:30-4:30，報名專線(02)2731-8214（如遇電話忙線無法接通時，請稍後再撥），亦接受e-mail報名：service@topgreen.org.tw 或線上報名：https://reurl.cc/G51Ojp 如要參加 DIY 課程，請使用電話或 EMAIL 報名 。　　為了學員的健康，教室仍定期消毒。更多有關都市田園綠化教育講座訊息請上北市產業局官網-活動訊息查詢，亦可於北市產業局FB粉絲專頁「臺北市政府產業發展局」及FB粉絲專頁「田園城市」確認。', '臺北市政府產業發展局', '無資料', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A2DB6A3EF17F284A', '[]') ON DUPLICATE KEY UPDATE `activity_name`='都市田園家庭種菜樂3月號北市產業局　綠化教育講座 熱烈招生中，請注意新規報名辦法', `description`='　　114年度都市田園教育講座3月份課程來囉!為鼓勵市民運用閒置空間栽種蔬果花卉，一同體會都市農夫的樂趣，北市產業局於3月8、15、22、29日懷生國中綠化教室開辦「臺北市民田園綠化教育講座」系列，今年度規劃四大主題：A都市農園藝初階課程、B都市農園藝進階課程、C食農教育推廣及應用、D綠化療育及趣味應用課程，請見分類標示，搭配各類DIY手作課程，歡迎市民朋友一同動手玩園藝。　　3月份課程包括有「春滿台北城 市花杜鵑的認識與栽培 」、「如何打造一座生物多樣性的水花園 」、「如何種好米，選好米及煮好飯 」、「臺灣茶的認識與品評 」、「初階蔬菜栽培技巧 」、「植栽的基礎維護管理 」、「居家蔬菜播種及繁殖綠手指 」、「有機蔬菜 裁培技術 」，課程內容多元且兼具養生實用性及保健性，因課程名額有限，請市民朋友儘早報名。　　相關課程內容與時間請上「台北市社區綠化聯盟促進會」網站查詢，報名時間為週一至週五上午9:30-11:30及下午1:30-4:30，報名專線(02)2731-8214（如遇電話忙線無法接通時，請稍後再撥），亦接受e-mail報名：service@topgreen.org.tw 或線上報名：https://reurl.cc/G51Ojp 如要參加 DIY 課程，請使用電話或 EMAIL 報名 。　　為了學員的健康，教室仍定期消毒。更多有關都市田園綠化教育講座訊息請上北市產業局官網-活動訊息查詢，亦可於北市產業局FB粉絲專頁「臺北市政府產業發展局」及FB粉絲專頁「田園城市」確認。', `organizer`='臺北市政府產業發展局', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A2DB6A3EF17F284A', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9363999', '臺北市政府地政局114年地政講堂系列講座「性別主流化：家庭與工作平衡政策和措施」訂於3月13日下午2時至5時舉行，歡迎報名參加！', '臺北市政府地政局114年地政講堂系列講座「性別主流化：家庭與工作平衡政策和措施」訂於3月13日下午2時至5時舉行，歡迎報名參加！內容：本局訂於本(114)年3月13日(星期四)下午2時至5時，假本市地政講堂(臺北市古亭地政事務所2樓，地址為臺北市文山區萬隆街47-12號)舉辦「性別主流化：家庭與工作平衡政策和措施」講座，讓實踐大學嚴祥鸞教授為您做深入的分析與探討，歡迎於114年2月27日起報名參加(連結至網路報名網址)！', '臺北市政府地政局', '無資料', '2025-02-27 00:00:00', '2025-03-14 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=118AF993F7BB11B9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺北市政府地政局114年地政講堂系列講座「性別主流化：家庭與工作平衡政策和措施」訂於3月13日下午2時至5時舉行，歡迎報名參加！', `description`='臺北市政府地政局114年地政講堂系列講座「性別主流化：家庭與工作平衡政策和措施」訂於3月13日下午2時至5時舉行，歡迎報名參加！內容：本局訂於本(114)年3月13日(星期四)下午2時至5時，假本市地政講堂(臺北市古亭地政事務所2樓，地址為臺北市文山區萬隆街47-12號)舉辦「性別主流化：家庭與工作平衡政策和措施」講座，讓實踐大學嚴祥鸞教授為您做深入的分析與探討，歡迎於114年2月27日起報名參加(連結至網路報名網址)！', `organizer`='臺北市政府地政局', `address`='無資料', `start_date`='2025-02-27 00:00:00', `end_date`='2025-03-14 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=118AF993F7BB11B9', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9363940', '「114年臺北市食農教育推廣」教案競賽申請簡章', '為促進臺北市食農教育的普及與深化，特辦理旨揭競賽鼓勵本市教育工作者及農業推廣人員運用創意，設計兼具趣味性與創意性的教案，讓食農教育能夠以多元、創新的方式融入校園、農業場域及市民大眾的生活，透過具創意與實用性的教學方案，培養市民對環境永續與健康飲食的責任感。報名期間：即日起至114年7月28日(一)17:00截止。報名方式採網路報名，填寫線上表單，並上傳以下資料（詳簡章附件）：(一)114年臺北市食農教育推廣教案競賽申請書(二)提案單位/個人經歷資料表(三)教案摘要與理念(四)智慧財產權聲明暨個人資料使用同意書(五)參賽切結書(六)影音檔案', '臺北市政府客家事務委員會', '無資料', '2025-02-25 00:00:00', '2025-07-28 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=78F7FF44AA4E5C4D', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「114年臺北市食農教育推廣」教案競賽申請簡章', `description`='為促進臺北市食農教育的普及與深化，特辦理旨揭競賽鼓勵本市教育工作者及農業推廣人員運用創意，設計兼具趣味性與創意性的教案，讓食農教育能夠以多元、創新的方式融入校園、農業場域及市民大眾的生活，透過具創意與實用性的教學方案，培養市民對環境永續與健康飲食的責任感。報名期間：即日起至114年7月28日(一)17:00截止。報名方式採網路報名，填寫線上表單，並上傳以下資料（詳簡章附件）：(一)114年臺北市食農教育推廣教案競賽申請書(二)提案單位/個人經歷資料表(三)教案摘要與理念(四)智慧財產權聲明暨個人資料使用同意書(五)參賽切結書(六)影音檔案', `organizer`='臺北市政府客家事務委員會', `address`='無資料', `start_date`='2025-02-25 00:00:00', `end_date`='2025-07-28 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=78F7FF44AA4E5C4D', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('22ebd8830714b0d61e156fb9afebf42c', '「施麗花拾礫再生娃娃千嬌百媚展」', '展覽期間：114年2月26日至3月21日現場導覽：3/4、3/11、3/18之14時至15時30分開放時間：週一至週五09：00-17：00(2/28不開放參觀)展覽地點：新北市土城區公所市民文化走廊（新北市土城區金城路1段101號2樓）歡迎同仁廣邀親朋好友踴躍蒞臨參觀新北市土城區公所 社會人文課　蔡小姐電話:2270-3379‧傳真:2270-2996', '土城區公所', '新北市土城區金城路1段101號2樓', '新北市土城區公所市民文化走廊', 24.96425102, 121.445737, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「施麗花拾礫再生娃娃千嬌百媚展」', `description`='展覽期間：114年2月26日至3月21日現場導覽：3/4、3/11、3/18之14時至15時30分開放時間：週一至週五09：00-17：00(2/28不開放參觀)展覽地點：新北市土城區公所市民文化走廊（新北市土城區金城路1段101號2樓）歡迎同仁廣邀親朋好友踴躍蒞臨參觀新北市土城區公所 社會人文課　蔡小姐電話:2270-3379‧傳真:2270-2996', `organizer`='土城區公所', `address`='新北市土城區金城路1段101號2樓', `location`='新北市土城區公所市民文化走廊', `latitude`=24.96425102, `longitude`=121.445737, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('05acc0da61bd6f885d9e4e007103d5b5', '【新北市立圖書館樹林三多圖書閱覽室】114年3月彩虹故事屋', '【新北市立圖書館樹林三多圖書閱覽室】114年3月彩虹故事屋與故事有約故事志工於假日時光，以豐富的故事內容及活潑生動的方式與兒童互動，激發兒童閱讀的興趣，也可增進親子交流，歡迎大人及小孩一同來參加～活動日期：3/15(六) 10:30-11:30 與您相約～ 故事名稱：「鱷魚艾倫又大又可怕的牙齒」故事簡介：艾倫是一隻兇猛的鱷魚，有著又大又可怕的牙齒，但是，艾倫有個不為人知的秘密……艾倫是隻凶猛可怕、有著尖牙的鱷魚，家族世代都以嚇人著稱，艾倫更是箇中高手。每一天，艾倫都會為了嚇人做好準備：刷牙、擦亮鱗片、練習恐怖的聲音和表情。然後進叢林嚇其他動物，他實在太可怕了！傍晚，艾倫會回到沼澤休息，並且脫下他的假牙，沒有人知道艾倫其實戴著假牙。有一天早上，艾倫發現假牙不見了！失去假牙，他還能繼續嚇人嗎？艾倫該怎麼辦呢？這是一本非常有趣的圖畫書，讓親子除了享受故事的趣味之外，還有許多討論的空間～我們可以嚇人或者欺負人嗎？可是如果我只會做這事情怎麼辦？常常被艾倫嚇的動物們可以怎麼處理艾倫的假牙呢？如果你是艾倫，拿回假牙後，你會？《鱷魚艾倫又大又可怕的牙齒》不只好笑，也發人深省。※活動時間若有更動，以現場公告為主，不便之處，敬請見諒。', '新北市立圖書館', '新北市樹林區福興街17號2樓', '新北市立圖書館樹林三多圖書閱覽室', 24.97970609, 121.401034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館樹林三多圖書閱覽室】114年3月彩虹故事屋', `description`='【新北市立圖書館樹林三多圖書閱覽室】114年3月彩虹故事屋與故事有約故事志工於假日時光，以豐富的故事內容及活潑生動的方式與兒童互動，激發兒童閱讀的興趣，也可增進親子交流，歡迎大人及小孩一同來參加～活動日期：3/15(六) 10:30-11:30 與您相約～ 故事名稱：「鱷魚艾倫又大又可怕的牙齒」故事簡介：艾倫是一隻兇猛的鱷魚，有著又大又可怕的牙齒，但是，艾倫有個不為人知的秘密……艾倫是隻凶猛可怕、有著尖牙的鱷魚，家族世代都以嚇人著稱，艾倫更是箇中高手。每一天，艾倫都會為了嚇人做好準備：刷牙、擦亮鱗片、練習恐怖的聲音和表情。然後進叢林嚇其他動物，他實在太可怕了！傍晚，艾倫會回到沼澤休息，並且脫下他的假牙，沒有人知道艾倫其實戴著假牙。有一天早上，艾倫發現假牙不見了！失去假牙，他還能繼續嚇人嗎？艾倫該怎麼辦呢？這是一本非常有趣的圖畫書，讓親子除了享受故事的趣味之外，還有許多討論的空間～我們可以嚇人或者欺負人嗎？可是如果我只會做這事情怎麼辦？常常被艾倫嚇的動物們可以怎麼處理艾倫的假牙呢？如果你是艾倫，拿回假牙後，你會？《鱷魚艾倫又大又可怕的牙齒》不只好笑，也發人深省。※活動時間若有更動，以現場公告為主，不便之處，敬請見諒。', `organizer`='新北市立圖書館', `address`='新北市樹林區福興街17號2樓', `location`='新北市立圖書館樹林三多圖書閱覽室', `latitude`=24.97970609, `longitude`=121.401034, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('05acc0da61bd6f88571c298ded3e839c', '【新北市立圖書館樹林三多圖書閱覽室】114年3月影友會', '【新北市立圖書館樹林三多圖書閱覽室】114年3月影友會場次介紹地點：研習教室時間：每星期日14:00開始一、3/02(日) 【片名：媽哩媽哩烘】，普遍級，112分鐘莎拉是一位馬來穆斯林名廚的女兒，她聘請青年攝影師阿文，來拍攝製作她的烘焙影片頻道，兩人之間隨著相處感情增溫，擦出愛火，並即將走入婚姻殿堂，但雙方卻因家族背景差異，譜出許多笑料，種族隔閡與信仰習俗的差異讓他們的戀情遭受波折，究竟這兩個家庭如何跨越文化鴻溝呢？二、3/09(日) 【片名：喵喵博物館】，普遍級，80分鐘 （動畫片）流浪貓文森與老鼠好友莫瑞斯因意外，被運送到艾米塔吉博物館，博物館內有一群冬宮菁英貓小隊，他們多年來為了保護博物館的館藏不受老鼠侵害不遺餘力，文森加入了捕捉老鼠的貓小隊，但暗自卻一直掩護莫瑞斯，不讓他被捕獲。今晚，世界上最偉大的名畫「蒙娜麗莎」即將被送到博物館，文森和他的菁英貓小隊夥伴們也做好了守護「蒙娜麗莎」的準備，卻沒想到一夜之間「蒙娜麗莎」不翼而飛……。三、3/16(日) 【片名：鄰人Ｘ：謎樣的女子】，保護級，120分鐘日本宣布將接收來自外星的難民Ｘ，但是人們心中充滿了對外星人難以言喻的恐懼和焦慮，週刊記者笹憲太郎一心想揭發Ｘ的真實樣貌，他鎖定兩名在超商工作的女性：文靜總是深居簡出的柏木良子以及來自台灣的留學生蓮，笹隱瞞自己的身分接近良子，卻在調查過程中愛上了良子……。四、3/23(日) 【片名：哥吉拉大戰金剛】，保護級，113分鐘金剛與牠的保護者，踏上危險的旅程，尋找牠真正的家園，同行的還有吉雅，這名年輕的小孤女，與金剛間有著獨特且強大的聯繫，但他們意外地與憤怒的哥吉拉狹路相逢，並在全球引發一片腥風血雨。五、3/30(日) 【片名：晨曦將至】，保護級，140分鐘無法生育的栗原夫婦透過領養機構收養男嬰朝斗，一家三口住在窗明几淨的高級公寓，與生母片倉光僅有一面之緣。六年後，一通神祕電話翻攪栗原家的命運，自稱為生母的女人要求栗原夫婦歸還或買下孩子，否則將揭露朝斗的身世，然而當她現身時，卻與當年的片倉光判若兩人，另一方面，警察突然帶著一個女人的照片上門？？她究竟是誰？而誰才是朝斗的母親？※活動時間若有更動，以現場公告為主，不便之處，敬請見諒。', '新北市立圖書館', '新北市樹林區福興街17號2樓', '新北市立圖書館樹林三多圖書閱覽室研習教室', 24.97970609, 121.401034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館樹林三多圖書閱覽室】114年3月影友會', `description`='【新北市立圖書館樹林三多圖書閱覽室】114年3月影友會場次介紹地點：研習教室時間：每星期日14:00開始一、3/02(日) 【片名：媽哩媽哩烘】，普遍級，112分鐘莎拉是一位馬來穆斯林名廚的女兒，她聘請青年攝影師阿文，來拍攝製作她的烘焙影片頻道，兩人之間隨著相處感情增溫，擦出愛火，並即將走入婚姻殿堂，但雙方卻因家族背景差異，譜出許多笑料，種族隔閡與信仰習俗的差異讓他們的戀情遭受波折，究竟這兩個家庭如何跨越文化鴻溝呢？二、3/09(日) 【片名：喵喵博物館】，普遍級，80分鐘 （動畫片）流浪貓文森與老鼠好友莫瑞斯因意外，被運送到艾米塔吉博物館，博物館內有一群冬宮菁英貓小隊，他們多年來為了保護博物館的館藏不受老鼠侵害不遺餘力，文森加入了捕捉老鼠的貓小隊，但暗自卻一直掩護莫瑞斯，不讓他被捕獲。今晚，世界上最偉大的名畫「蒙娜麗莎」即將被送到博物館，文森和他的菁英貓小隊夥伴們也做好了守護「蒙娜麗莎」的準備，卻沒想到一夜之間「蒙娜麗莎」不翼而飛……。三、3/16(日) 【片名：鄰人Ｘ：謎樣的女子】，保護級，120分鐘日本宣布將接收來自外星的難民Ｘ，但是人們心中充滿了對外星人難以言喻的恐懼和焦慮，週刊記者笹憲太郎一心想揭發Ｘ的真實樣貌，他鎖定兩名在超商工作的女性：文靜總是深居簡出的柏木良子以及來自台灣的留學生蓮，笹隱瞞自己的身分接近良子，卻在調查過程中愛上了良子……。四、3/23(日) 【片名：哥吉拉大戰金剛】，保護級，113分鐘金剛與牠的保護者，踏上危險的旅程，尋找牠真正的家園，同行的還有吉雅，這名年輕的小孤女，與金剛間有著獨特且強大的聯繫，但他們意外地與憤怒的哥吉拉狹路相逢，並在全球引發一片腥風血雨。五、3/30(日) 【片名：晨曦將至】，保護級，140分鐘無法生育的栗原夫婦透過領養機構收養男嬰朝斗，一家三口住在窗明几淨的高級公寓，與生母片倉光僅有一面之緣。六年後，一通神祕電話翻攪栗原家的命運，自稱為生母的女人要求栗原夫婦歸還或買下孩子，否則將揭露朝斗的身世，然而當她現身時，卻與當年的片倉光判若兩人，另一方面，警察突然帶著一個女人的照片上門？？她究竟是誰？而誰才是朝斗的母親？※活動時間若有更動，以現場公告為主，不便之處，敬請見諒。', `organizer`='新北市立圖書館', `address`='新北市樹林區福興街17號2樓', `location`='新北市立圖書館樹林三多圖書閱覽室研習教室', `latitude`=24.97970609, `longitude`=121.401034, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('05acc0da61bd6f88df1fc45248ea0acf', '【新北市立圖書館樹林三多圖書閱覽室】114年3月閱讀書籤-主題書展', '【新北市立圖書館樹林三多圖書閱覽室】114年3月閱讀書籤-主題書展展出期間：114.03.01-03.31一.【樂齡主題書展】痠痛保健肩腰僵硬、久坐背痛；日常行走、伸手拿高處物品……都令你萬分吃力嗎？身體痠痛已是生活節奏緊湊的現代人文明病，若放任肌肉緊繃與疲勞，將會演變成慢性疼痛，嚴重的話，肌肉甚至會發炎，千萬不可忽視！鎖定本書展透過專家「對症下藥」，讓你不再為舊疾所擾，痠痛麻自然舒緩，不再來∼二.【主題書展】翻一頁～台灣的美麗與哀愁葡萄牙人第一次看見台灣時的驚呼「福爾摩沙！」，就是我們的寶島。台灣既美麗又迷人，有時卻顯得哀愁而可怕。你知道「杜聰明」是台灣史上首位醫學博士嗎？你知道「艋舺謀殺事件」是台灣文學史上第一部犯罪推理小說嗎？除了國語外，你有看過有關「台語」文集，以及「性別文學」的書籍嗎？你可曾聽過台灣早期可能由於慢性砷中毒，而導致的「烏腳病」；及「樂生療養院」為日治時期強制收容痲瘋病患之防治與隔離機構的歷史嗎？讓我們從書的角度，帶領讀者看見美麗與哀愁並存的台灣，從文字感受到勇氣，並獲得療癒～< 歡迎踴躍借閱！>※活動時間若有更動，以現場公告為主，不便之處，敬請見諒。', '新北市立圖書館', '新北市樹林區福興街17號2樓', '新北市立圖書館樹林三多圖書閱覽室', 24.97970609, 121.401034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館樹林三多圖書閱覽室】114年3月閱讀書籤-主題書展', `description`='【新北市立圖書館樹林三多圖書閱覽室】114年3月閱讀書籤-主題書展展出期間：114.03.01-03.31一.【樂齡主題書展】痠痛保健肩腰僵硬、久坐背痛；日常行走、伸手拿高處物品……都令你萬分吃力嗎？身體痠痛已是生活節奏緊湊的現代人文明病，若放任肌肉緊繃與疲勞，將會演變成慢性疼痛，嚴重的話，肌肉甚至會發炎，千萬不可忽視！鎖定本書展透過專家「對症下藥」，讓你不再為舊疾所擾，痠痛麻自然舒緩，不再來∼二.【主題書展】翻一頁～台灣的美麗與哀愁葡萄牙人第一次看見台灣時的驚呼「福爾摩沙！」，就是我們的寶島。台灣既美麗又迷人，有時卻顯得哀愁而可怕。你知道「杜聰明」是台灣史上首位醫學博士嗎？你知道「艋舺謀殺事件」是台灣文學史上第一部犯罪推理小說嗎？除了國語外，你有看過有關「台語」文集，以及「性別文學」的書籍嗎？你可曾聽過台灣早期可能由於慢性砷中毒，而導致的「烏腳病」；及「樂生療養院」為日治時期強制收容痲瘋病患之防治與隔離機構的歷史嗎？讓我們從書的角度，帶領讀者看見美麗與哀愁並存的台灣，從文字感受到勇氣，並獲得療癒～< 歡迎踴躍借閱！>※活動時間若有更動，以現場公告為主，不便之處，敬請見諒。', `organizer`='新北市立圖書館', `address`='新北市樹林區福興街17號2樓', `location`='新北市立圖書館樹林三多圖書閱覽室', `latitude`=24.97970609, `longitude`=121.401034, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a0f2ffdc02b3096ec4bed293b4dcf577', '樹林地所「春櫻時光‧定格浪漫」(攝影徵選活動)', '春暖花開，正是賞櫻好時節，樹林地政事務所廣場兩旁的八重櫻已感受到春意，一朵朵緋紅在枝頭! 該所將於2月26日至3月10日止舉辦「春櫻時光‧定格浪漫」活動，邀請民眾一同感受櫻花綻放的美麗時刻，用鏡頭記錄這份春日浪漫，參與活動可獲取精美好禮!', '新北市樹林地政事務所', '新北市樹林區地政街12號', '新北市樹林地政事務所廣場', 24.97970609, 121.401034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樹林地所「春櫻時光‧定格浪漫」(攝影徵選活動)', `description`='春暖花開，正是賞櫻好時節，樹林地政事務所廣場兩旁的八重櫻已感受到春意，一朵朵緋紅在枝頭! 該所將於2月26日至3月10日止舉辦「春櫻時光‧定格浪漫」活動，邀請民眾一同感受櫻花綻放的美麗時刻，用鏡頭記錄這份春日浪漫，參與活動可獲取精美好禮!', `organizer`='新北市樹林地政事務所', `address`='新北市樹林區地政街12號', `location`='新北市樹林地政事務所廣場', `latitude`=24.97970609, `longitude`=121.401034, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6712af3926b32468988294f9', '語文寫作素養-啟蒙B(適2-3年級初學、無上過寫作課程者)', '創藝學園學員參加中華民國作文教育會第64屆全國作文徵文比賽得獎人獎狀及參賽作品https://drive.google.com/drive/folders/1_wVdEhZMwVMimcIliP5wEF951Q6i_ReR?usp=sharing\n\n★本課程計有6套不同課程大綱，舊學員學習上不會重複，完整學習至少須為1年。\n\n★本課程開班標準：報名繳費達16人。\n\n★授課師資：林雪淇老師(本期因故授課至1/18日)、曾寶萱老師(2/15起授課)\n\n★前期(113年9-12月)課程表  供參考\n\n\n	\n		\n			\n			堂數\n			\n			\n			日期\n			\n			\n			課程主題\n			\n			\n			學習目標\n			\n		\n		\n			\n			1\n			\n			\n			1/4\n			\n			\n			舉一反三\n			\n			\n			同義詞、反義詞的練習\n			\n		\n		\n			\n			2\n			\n			\n			1/11\n			\n			\n			心領神會\n			\n			\n			五感摹寫的運用\n			\n		\n		\n			\n			3\n			\n			\n			1/18\n			\n			\n			震古鑠今\n			\n			\n			引用名言佳句，讓文章更有深度\n			\n		\n		\n			\n			停課\n			\n			\n			1/25\n			\n			\n			農曆春節連假\n			\n		\n		\n			\n			停課\n			\n			\n			2/1\n			\n			\n			農曆春節連假\n			\n		\n		\n			\n			停課\n			\n			\n			2/8\n			\n			\n			補行上班課日\n			\n		\n		\n			\n			4\n			\n			\n			2/15\n			\n			\n			伺機而「動」\n			\n			\n			動作摹寫的練習\n			\n		\n		\n			\n			5\n			\n			\n			2/22\n			\n			\n			引經據典\n			\n			\n			舉出史實或事例，加強文章論點\n			\n		\n		\n			\n			停課\n			\n			\n			3/1\n			\n			\n			和平紀念日連假\n			\n		\n		\n			\n			6\n			\n			\n			3/8\n			\n			\n			綜合演練\n			\n		\n		\n			\n			7\n			\n			\n			3/15\n			\n			\n			瞻前顧後\n			\n			\n			讓主題鮮明深刻，全文連貫\n			\n		\n		\n			\n			8\n			\n			\n			3/22\n			\n			\n			連雲疊嶂\n			\n			\n			學習運用類疊修辭\n			\n		\n		\n			\n			9\n			\n			\n			3/29\n			\n			\n			錦上添花\n			\n			\n			運用擴寫技巧，使文章內容更豐富\n			\n		\n		\n			\n			停課\n			\n			\n			4/5\n			\n			\n			兒童節及民族掃墓節連假\n			\n		\n		\n			\n			10\n			\n			\n			4/12\n			\n			\n			龍吟虎嘯\n			\n			\n			學習狀聲詞，並運用造句。\n			\n		\n		\n			\n			11\n			\n			\n			4/19\n			\n			\n			大展鴻圖\n			\n			\n			練習視覺摹寫。\n			\n		\n		\n			\n			12\n			\n			\n			4/26\n			\n			\n			綜合演練\n			\n		\n	\n\n\n上課教室位置圖 \n\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路2