INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('675722c326b324689882a728', '2025林筱純中提琴獨奏會', '無資料', '無資料', '臺北市中正區中山南路21-1號', '2025-03-02 00:00:00', '2025-03-02 00:00:00', '國家兩廳院演奏廳', 25.0367564, 121.519047, '無資料', 'https://www.opentix.life/program/1864630701195341825', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025林筱純中提琴獨奏會', `description`='無資料', `organizer`='無資料', `address`='臺北市中正區中山南路21-1號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='國家兩廳院演奏廳', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://www.opentix.life/program/1864630701195341825', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('678f0dee26b32458d4363840', '2025臺北攝影獎暨會員優秀作品展', '\n『臺北攝影獎』創辦19年，累計參賽人數逾三千人、作品超過一萬五千件，成為國內重要攝影賽事。2025年第19屆共設《自由創作》與《紀實攝影》兩組，頒發95個獎項，規模歷年之最。本次展覽呈現得獎作品，並展示臺北攝影學會會員優秀作品，包括新科榮銜會士、資深會員及顧問等佳作。學會成立於1956年，會員遍布全球，致力推廣攝影藝術，誠邀蒞臨展覽，感受影像藝術的多元魅力與深刻感動。\nFounded 19 years ago, the "Taipei Photography Awards" has attracted over 3,000 participants and showcased more than 15,000 works, establishing itself as a prestigious national competition. The 19th edition in 2025 will feature two categories: "Creative Works" and "Documentary Photography," awarding a record 95 prizes. This exhibition presents the winning entries alongside stellar works from members of The Photographic Society of Taipei, including newly titled fellows, senior members, and advisors.\n', '無資料', '臺北市南海路四十七號', '2025-02-21 00:00:00', '2025-03-05 00:00:00', '美學空間', 25.032319, 121.51206, '無資料', 'https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4413', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺北攝影獎暨會員優秀作品展', `description`='\n『臺北攝影獎』創辦19年，累計參賽人數逾三千人、作品超過一萬五千件，成為國內重要攝影賽事。2025年第19屆共設《自由創作》與《紀實攝影》兩組，頒發95個獎項，規模歷年之最。本次展覽呈現得獎作品，並展示臺北攝影學會會員優秀作品，包括新科榮銜會士、資深會員及顧問等佳作。學會成立於1956年，會員遍布全球，致力推廣攝影藝術，誠邀蒞臨展覽，感受影像藝術的多元魅力與深刻感動。\nFounded 19 years ago, the "Taipei Photography Awards" has attracted over 3,000 participants and showcased more than 15,000 works, establishing itself as a prestigious national competition. The 19th edition in 2025 will feature two categories: "Creative Works" and "Documentary Photography," awarding a record 95 prizes. This exhibition presents the winning entries alongside stellar works from members of The Photographic Society of Taipei, including newly titled fellows, senior members, and advisors.\n', `organizer`='無資料', `address`='臺北市南海路四十七號', `start_date`='2025-02-21 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='美學空間', `latitude`=25.032319, `longitude`=121.51206, `ticket_price`='無資料', `source_url`='https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4413', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('679414a926b32458d4363967', '【相聲瓦舍】《狐說》', '【相聲瓦舍】2025年全新創作《狐說》\r\n傳說…狐狸精修煉百年成人，千年成仙。\r\n今晚戲台上沒有人！\r\n水靈動人的狐媚妖精，把好色的雪神、貪杯的風神搞到PTSD？\r\n帥氣歐爸的九尾狐仙，夜夜笙歌，滿足各位姨太太。\r\n糊里糊塗的野狐禪，到底說的是什麼禪？\r\n【相聲瓦舍】前所未見的作品。來自平行宇宙的妖魔、獸靈、狐仙、女鬼。變身、飛天、打架、畸戀？！\r\n防不勝防的囈語狂想。小心，別露出狐狸尾巴！2025歡迎來聽我們胡說……，喔，是《狐說》。\r\n\r\n演出人員：馮翊綱、時一修、 御天十兵衛 、趙逸嵐 、巫明如、古辛', '相聲瓦舍', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '票價+600;票價+800;票價+1000;票價+1200;票價+1500;票價+1800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【相聲瓦舍】《狐說》', `description`='【相聲瓦舍】2025年全新創作《狐說》\r\n傳說…狐狸精修煉百年成人，千年成仙。\r\n今晚戲台上沒有人！\r\n水靈動人的狐媚妖精，把好色的雪神、貪杯的風神搞到PTSD？\r\n帥氣歐爸的九尾狐仙，夜夜笙歌，滿足各位姨太太。\r\n糊里糊塗的野狐禪，到底說的是什麼禪？\r\n【相聲瓦舍】前所未見的作品。來自平行宇宙的妖魔、獸靈、狐仙、女鬼。變身、飛天、打架、畸戀？！\r\n防不勝防的囈語狂想。小心，別露出狐狸尾巴！2025歡迎來聽我們胡說……，喔，是《狐說》。\r\n\r\n演出人員：馮翊綱、時一修、 御天十兵衛 、趙逸嵐 、巫明如、古辛', `organizer`='相聲瓦舍', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='票價+600;票價+800;票價+1000;票價+1200;票價+1500;票價+1800', `source_url`='https://www.opentix.life/', `image_url`='[]';
