INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e55226b32418d001b869', '2025活力滿滿 成長跳躍 世界紀錄跳繩活動(需事先報名)', '邀請小夥伴與爸爸媽媽一同參與萬人跳繩的挑戰紀錄，也能成為成長過程中最難忘的回憶和紀錄！\n此次活動希望家長與孩子共同參與，在歡樂的氛圍中一同學習與實踐健康生活的要素，不僅提升親子關係，更能在日常生活中自然地落實健康的行為模式。透過「活力滿滿 成長跳躍」，讓每個家庭都能邁向更健康、更幸福的未來！', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '民主大道', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50530', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025活力滿滿 成長跳躍 世界紀錄跳繩活動(需事先報名)', `description`='邀請小夥伴與爸爸媽媽一同參與萬人跳繩的挑戰紀錄，也能成為成長過程中最難忘的回憶和紀錄！\n此次活動希望家長與孩子共同參與，在歡樂的氛圍中一同學習與實踐健康生活的要素，不僅提升親子關係，更能在日常生活中自然地落實健康的行為模式。透過「活力滿滿 成長跳躍」，讓每個家庭都能邁向更健康、更幸福的未來！', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='民主大道', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50530', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e55526b32418d001b86a', '靜思書軒親恩封茶茶會(付費參加)', '封茶，讓茶葉隨著時間轉化更具風味，也是封藏一份對自己、對親友或法親深深的祝福。\n\n若干年後，開啟茶甕，靜心品味茶香的濃郁與甘醇，體驗大自然孕育的純淨好茶。\n\n現場提供手摘蜜香、清雅甘醇的小葉紅茶，精緻手作茶食。邀請闔家、親友一同來品嘗。\n\n活動時間：114年3月8日(六)\n\n第一梯次 14：00-15：00 (13:30 大忠門靜思書軒報到)\n\n第二梯次 15：30-16：30 (15:30 大忠門靜思書軒報到)\n\n地點：中正紀念堂園區教室二\n\n活動名額：每梯次40位。\n\n費用：封茶A組合: 2130元   封茶B組合: 1950元   封茶C組合: 1752元 ( 含活動費、靜思茶品及點心 )。贈送限量精美提袋，送完為止。\n\n詳情可參考報名網址：https://forms.gle/P6sutojsftm8a29y8', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '園區教室二', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50738', '[]') ON DUPLICATE KEY UPDATE `activity_name`='靜思書軒親恩封茶茶會(付費參加)', `description`='封茶，讓茶葉隨著時間轉化更具風味，也是封藏一份對自己、對親友或法親深深的祝福。\n\n若干年後，開啟茶甕，靜心品味茶香的濃郁與甘醇，體驗大自然孕育的純淨好茶。\n\n現場提供手摘蜜香、清雅甘醇的小葉紅茶，精緻手作茶食。邀請闔家、親友一同來品嘗。\n\n活動時間：114年3月8日(六)\n\n第一梯次 14：00-15：00 (13:30 大忠門靜思書軒報到)\n\n第二梯次 15：30-16：30 (15:30 大忠門靜思書軒報到)\n\n地點：中正紀念堂園區教室二\n\n活動名額：每梯次40位。\n\n費用：封茶A組合: 2130元   封茶B組合: 1950元   封茶C組合: 1752元 ( 含活動費、靜思茶品及點心 )。贈送限量精美提袋，送完為止。\n\n詳情可參考報名網址：https://forms.gle/P6sutojsftm8a29y8', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='園區教室二', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50738', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e55d26b32418d001b86e', '「權」是你的選擇—南島廳人權主題導覽', '南島的世界裡存在各種的議題，不論是環境的變遷或是歷史的過往都深刻地影響到你我存在的這個當下。\n\n這趟導覽，我們將透過南島廳的物件，穿梭人權議題與南島文化的交織，一同重新思考我們與世界的關係。\n\n \n\n1、  時間：3/1（六）上午11：00-12：00、下午15：00-16：00（共2場次）\n\n2、  地點：購票後至展廳服務台集合報到\n\n3、  費用：購票入場即可參加\n\n4、  人數：20人\n\n5、  報名：本館藝文平台（視網路報名情況開放當天現場報名）\n\n \n\n \n\n \n\n注意事項：\n\n1.報名時請逐一填寫參加者資料，大人小孩皆需報名。\n\n2.凡報名參加即表示同意肖像權授權予史前館及文化部於本次活動拍攝記錄作為學術交流、教學應用、藝文推廣及計畫成果發表之用。\n\n ', '國立臺灣史前文化博物館', '無資料', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=50150', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「權」是你的選擇—南島廳人權主題導覽', `description`='南島的世界裡存在各種的議題，不論是環境的變遷或是歷史的過往都深刻地影響到你我存在的這個當下。\n\n這趟導覽，我們將透過南島廳的物件，穿梭人權議題與南島文化的交織，一同重新思考我們與世界的關係。\n\n \n\n1、  時間：3/1（六）上午11：00-12：00、下午15：00-16：00（共2場次）\n\n2、  地點：購票後至展廳服務台集合報到\n\n3、  費用：購票入場即可參加\n\n4、  人數：20人\n\n5、  報名：本館藝文平台（視網路報名情況開放當天現場報名）\n\n \n\n \n\n \n\n注意事項：\n\n1.報名時請逐一填寫參加者資料，大人小孩皆需報名。\n\n2.凡報名參加即表示同意肖像權授權予史前館及文化部於本次活動拍攝記錄作為學術交流、教學應用、藝文推廣及計畫成果發表之用。\n\n ', `organizer`='國立臺灣史前文化博物館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=50150', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e55e26b32418d001b871', '【臺灣文學基地】「噤聲的密室—白恐文學讀心術」行動展推廣活動（臺北）', '「噤聲的密室—白恐文學讀心術」行動展推廣活動 \n\n\n\n這不只是一次遊戲與走讀，而是一場穿越歷史的體驗，讓我們在文學與城市的對話之中，感受禁忌時代的壓抑與抗爭，聆聽那些未曾被訴說的故事。\n\n*活動皆需線上報名\n\n \n\n\n\n\n \n\n桌遊體驗《文壇封鎖中》 \n\n隨著桌遊「文壇封鎖中」的腳步，進入1949-1992年白色恐怖時期的文學世界，尋訪作家書案、探索那些曾被查禁的書刊、在遊戲中感受文壇封鎖的風聲鶴唳！活動邀請協助本館開發桌遊的張俐璇教授主講、周郁穎助教帶領，機會難得！\n\n\n\n一、時間：2025.03.09 (日) 14:00－17:00\n二、地點：臺文基地 創作坊\n三、主講：張俐璇 教授 / 周郁穎 助教\n\n\n四、活動流程： \n\n\n	       遊戲設計背景介紹\n	       《文壇封鎖中》桌遊體驗\n	       體驗回饋分享及討論\n\n\n \n\n\n \n\n踏訪活動《不義遺址走讀》 \n\n二二八事件與白色恐怖不只是課本裡的歷史，而是這座城市裡仍能尋訪的記憶。你知道臺文基地週遭有哪些白色恐怖時期的痕跡嗎？一起跟著人權走讀專家曹欽榮老師，從臺文基地出發，邁開腳步認識腳下的歷史吧！\n\n\n\n踏訪活動《不義遺址走\n\n一、場次：2025.03.15(六)、03.16(日) 共兩場\n二、主講：曹欽榮 老師 《流麻溝十五號：綠島女生分隊及其他》\n三、時間：每場次 14:00-17:00\n四、行前報到：03.15(六)臺灣文學基地 悅讀館 / 03.16(日) 創作坊\n\n\n五、走讀踏點：華山車站舊址、青島東路三號(現喜來登飯店)、行政院、臺大醫院、二二八和平公園、二二八和平紀念碑、白色恐怖紀念碑、臺北二二八紀念館。\n\n\n六、導覽設備：每人提供戶外導覽接收器、耳機各一（均有消毒，如有衛生疑慮，歡迎自行攜帶耳機）\n\n\n七、活動流程：  \n\n       13：30－14：00 報到、換領導覽機\n       14：00－14：30 行前說明\n       14：30－17：00 戶外走讀\n       17：00 -            設備歸還、解散\n\n\n八、注意事項：\n\n\n	活動全程步行，參與者需配戴口罩、穿著輕便衣服，及自備飲用水、雨具。\n	導覽課程將使用導覽耳機，參與者須以個人證件（或押金500元）換領設備。\n	導覽當天若遇下雨，行程仍會照常進行。請攜帶雨具，小心步行。如遇颱風等天災，則依臺北市政府停班停課發布為標準，行程將取消舉行。\n	本活動保險相關事宜由臺灣文學基地統一協助辦理，於報名時請填寫正確旅遊平安險投保資料，如資料缺漏將影響報名資格，造成不便，敬請見諒。\n\n\n ', '國立台灣文學館', '100  臺北市中正區濟南路二段27號', '2025-03-09 00:00:00', '2025-03-16 00:00:00', '臺灣文學基地 創作坊', 25.0421407, 121.5198716, '無資料', 'https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=50051', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【臺灣文學基地】「噤聲的密室—白恐文學讀心術」行動展推廣活動（臺北）', `description`='「噤聲的密室—白恐文學讀心術」行動展推廣活動 \n\n\n\n這不只是一次遊戲與走讀，而是一場穿越歷史的體驗，讓我們在文學與城市的對話之中，感受禁忌時代的壓抑與抗爭，聆聽那些未曾被訴說的故事。\n\n*活動皆需線上報名\n\n \n\n\n\n\n \n\n桌遊體驗《文壇封鎖中》 \n\n隨著桌遊「文壇封鎖中」的腳步，進入1949-1992年白色恐怖時期的文學世界，尋訪作家書案、探索那些曾被查禁的書刊、在遊戲中感受文壇封鎖的風聲鶴唳！活動邀請協助本館開發桌遊的張俐璇教授主講、周郁穎助教帶領，機會難得！\n\n\n\n一、時間：2025.03.09 (日) 14:00－17:00\n二、地點：臺文基地 創作坊\n三、主講：張俐璇 教授 / 周郁穎 助教\n\n\n四、活動流程： \n\n\n	       遊戲設計背景介紹\n	       《文壇封鎖中》桌遊體驗\n	       體驗回饋分享及討論\n\n\n \n\n\n \n\n踏訪活動《不義遺址走讀》 \n\n二二八事件與白色恐怖不只是課本裡的歷史，而是這座城市裡仍能尋訪的記憶。你知道臺文基地週遭有哪些白色恐怖時期的痕跡嗎？一起跟著人權走讀專家曹欽榮老師，從臺文基地出發，邁開腳步認識腳下的歷史吧！\n\n\n\n踏訪活動《不義遺址走\n\n一、場次：2025.03.15(六)、03.16(日) 共兩場\n二、主講：曹欽榮 老師 《流麻溝十五號：綠島女生分隊及其他》\n三、時間：每場次 14:00-17:00\n四、行前報到：03.15(六)臺灣文學基地 悅讀館 / 03.16(日) 創作坊\n\n\n五、走讀踏點：華山車站舊址、青島東路三號(現喜來登飯店)、行政院、臺大醫院、二二八和平公園、二二八和平紀念碑、白色恐怖紀念碑、臺北二二八紀念館。\n\n\n六、導覽設備：每人提供戶外導覽接收器、耳機各一（均有消毒，如有衛生疑慮，歡迎自行攜帶耳機）\n\n\n七、活動流程：  \n\n       13：30－14：00 報到、換領導覽機\n       14：00－14：30 行前說明\n       14：30－17：00 戶外走讀\n       17：00 -            設備歸還、解散\n\n\n八、注意事項：\n\n\n	活動全程步行，參與者需配戴口罩、穿著輕便衣服，及自備飲用水、雨具。\n	導覽課程將使用導覽耳機，參與者須以個人證件（或押金500元）換領設備。\n	導覽當天若遇下雨，行程仍會照常進行。請攜帶雨具，小心步行。如遇颱風等天災，則依臺北市政府停班停課發布為標準，行程將取消舉行。\n	本活動保險相關事宜由臺灣文學基地統一協助辦理，於報名時請填寫正確旅遊平安險投保資料，如資料缺漏將影響報名資格，造成不便，敬請見諒。\n\n\n ', `organizer`='國立台灣文學館', `address`='100  臺北市中正區濟南路二段27號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺灣文學基地 創作坊', `latitude`=25.0421407, `longitude`=121.5198716, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=50051', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e55e26b32418d001b872', '【飛越文學天際線】愛的神蹟與《零度分離》：當人類、鯨豚與AI都在練習說我愛你', '2025【飛越文學天際線系列活動】第4場登場！\n\n愛的神蹟與《零度分離》：當人類、鯨豚與AI都在練習說我愛你\n\n伊格言 X 白蓮娜 \n\n\n時間：2025/3/22（六）14:30~16:30\n\n地點：國立臺灣文學館2樓第一會議室（將視報名情況調整）\n\n\n我們如何理解「愛」？當語言能被複製和學習，「我愛你」是否仍真實而純粹？人們與AI互動時，是否也能感受到某種深層的情感連結？在這場特別的講座，作家伊格言與捷臺翻譯家白蓮娜（Pavlína Krámská）將帶領我們探索愛的不同面向，也討論語言、記憶與情感之間的關係。\n\n伊格言的作品《零度分離》以報導文學方式書寫未來，聚焦科技、道德與愛，思考AI如何學習「愛」這個抽象卻深刻的情感。首篇〈再說一次我愛你〉收錄在《穿別人的皮膚：現代臺灣文學選集》，於2024年12月在捷克發行。當人類與鯨豚，人類與AI彼此交織，我們該如何重新定義「愛」的邊界？本場講座將帶來充滿愛與哲思的對話，邀請大家一起探索愛的可能性。\n\n\n​●關於V cizi kůži\n\n《穿別人的皮膚：現代臺灣文學選集》（V cizi kůži）由本館和麋鹿出版社合作於捷克出版，主題關注臺灣對身分、性別與生命的書寫。總共收錄十位作家十一篇作品，包含伊格言作品〈再說一次我愛你〉（收錄於《零度分離》）、多馬斯．哈漾〈泰雅爾巴萊〉〈解壓縮〉、賴香吟〈暮色將至〉、王文興〈命運的迹線〉、甘耀明 〈吊死貓〉、吳明益 〈黑夜、黑土與黑色的山〉、言叔夏 〈袋蟲〉、平路 〈接納〉、白先勇〈月夢〉、陳雪 〈夜的迷宮〉。\n\n\n​●講者簡介\n\n伊格言\n\n小說家／詩人，《聯合文學》雜誌二〇一〇年八月號封面人物、《印刻》雜誌二〇二一年三月號封面人物。\n\n曾獲臺灣文學金典獎、台北國際書展大獎、聯合文學小說新人獎、自由時報林榮三文學獎、吳濁流文學獎長篇小說獎、華文科幻星雲獎長篇小說獎、《聯合文學》雜誌二〇一〇年度之書、中央社臺灣十大潛力人物等獎項。\n\n作品已譯為多國文字，並售出日、韓、捷、中等國版權。\n\n白蓮娜（Pavlína Krámská）\n\n捷克布拉格查理大學文學院東亞研究所博士，2020年國立臺灣文學館駐村譯者。長期研究、翻譯臺灣自然文學，在捷克麋鹿出版社（Mi:Lù Publishing）擔任總編輯。\n\n捷克文翻譯臺灣作品有：《小鼯鼠的看法》（劉克襄著）、《複眼人》（吳明益著）、《討海人》（廖鴻基著）、《奇萊前書》（楊牧著）等書。\n\n\n​◆名額有限，趕快手刀報名！\n\n\n活動洽詢：覃小姐 TEL: 06-2217201＃2203, EMAIL: ccs@nmtl.gov.tw\n\n ', '國立台灣文學館', '700  臺南市中西區中正路(湯德章大道)1號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '國立臺灣文學館2樓第一會議室（將視報名情況調整）', 22.99594458, 120.192874, '無資料', 'https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=50052', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【飛越文學天際線】愛的神蹟與《零度分離》：當人類、鯨豚與AI都在練習說我愛你', `description`='2025【飛越文學天際線系列活動】第4場登場！\n\n愛的神蹟與《零度分離》：當人類、鯨豚與AI都在練習說我愛你\n\n伊格言 X 白蓮娜 \n\n\n時間：2025/3/22（六）14:30~16:30\n\n地點：國立臺灣文學館2樓第一會議室（將視報名情況調整）\n\n\n我們如何理解「愛」？當語言能被複製和學習，「我愛你」是否仍真實而純粹？人們與AI互動時，是否也能感受到某種深層的情感連結？在這場特別的講座，作家伊格言與捷臺翻譯家白蓮娜（Pavlína Krámská）將帶領我們探索愛的不同面向，也討論語言、記憶與情感之間的關係。\n\n伊格言的作品《零度分離》以報導文學方式書寫未來，聚焦科技、道德與愛，思考AI如何學習「愛」這個抽象卻深刻的情感。首篇〈再說一次我愛你〉收錄在《穿別人的皮膚：現代臺灣文學選集》，於2024年12月在捷克發行。當人類與鯨豚，人類與AI彼此交織，我們該如何重新定義「愛」的邊界？本場講座將帶來充滿愛與哲思的對話，邀請大家一起探索愛的可能性。\n\n\n​●關於V cizi kůži\n\n《穿別人的皮膚：現代臺灣文學選集》（V cizi kůži）由本館和麋鹿出版社合作於捷克出版，主題關注臺灣對身分、性別與生命的書寫。總共收錄十位作家十一篇作品，包含伊格言作品〈再說一次我愛你〉（收錄於《零度分離》）、多馬斯．哈漾〈泰雅爾巴萊〉〈解壓縮〉、賴香吟〈暮色將至〉、王文興〈命運的迹線〉、甘耀明 〈吊死貓〉、吳明益 〈黑夜、黑土與黑色的山〉、言叔夏 〈袋蟲〉、平路 〈接納〉、白先勇〈月夢〉、陳雪 〈夜的迷宮〉。\n\n\n​●講者簡介\n\n伊格言\n\n小說家／詩人，《聯合文學》雜誌二〇一〇年八月號封面人物、《印刻》雜誌二〇二一年三月號封面人物。\n\n曾獲臺灣文學金典獎、台北國際書展大獎、聯合文學小說新人獎、自由時報林榮三文學獎、吳濁流文學獎長篇小說獎、華文科幻星雲獎長篇小說獎、《聯合文學》雜誌二〇一〇年度之書、中央社臺灣十大潛力人物等獎項。\n\n作品已譯為多國文字，並售出日、韓、捷、中等國版權。\n\n白蓮娜（Pavlína Krámská）\n\n捷克布拉格查理大學文學院東亞研究所博士，2020年國立臺灣文學館駐村譯者。長期研究、翻譯臺灣自然文學，在捷克麋鹿出版社（Mi:Lù Publishing）擔任總編輯。\n\n捷克文翻譯臺灣作品有：《小鼯鼠的看法》（劉克襄著）、《複眼人》（吳明益著）、《討海人》（廖鴻基著）、《奇萊前書》（楊牧著）等書。\n\n\n​◆名額有限，趕快手刀報名！\n\n\n活動洽詢：覃小姐 TEL: 06-2217201＃2203, EMAIL: ccs@nmtl.gov.tw\n\n ', `organizer`='國立台灣文學館', `address`='700  臺南市中西區中正路(湯德章大道)1號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='國立臺灣文學館2樓第一會議室（將視報名情況調整）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=50052', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e56226b32418d001b873', '《錦衣》臺灣豫劇團｜穿梭真實與虛幻—揭密《錦衣》撲朔迷離的角色世界', '免費預約報名，限額 100 名\n\n \n\n 講座資訊 \n\n講座：穿梭真實與虛幻—揭密《錦衣》撲朔迷離的角色世界\n時間：3月29日(六) 14:00-16:00(13:30開放入場)\n地點：臺灣戲曲中心─臺灣音樂館B1視聽室\n主講人：\n編劇 劉建幗\n與談人：\n臺灣豫劇團藝術總監 王海玲\n臺灣豫劇團當家花旦 蕭揚玲\n臺灣豫劇團豫劇王子 劉建華\n\n \n\n 報名方式 \n\n報名鏈結：https://forms.gle/2HhrS8JbfK7hUUcZ6\n請填寫Google線上報名表單，並完整填寫基本資訊，即代表報名成功。 (講座名額：限量100名，額滿為止。)\n\n \n\n 好康加碼 \n\n好禮大放送：\n〔參加禮〕凡到場參與並完成問卷填寫的觀眾即可獲參加禮一份。\n〔摸彩禮〕現場提供數樣精美禮物，凡入場即有抽獎資格。\n〔購票禮〕於活動現場購票即可獲得購票禮一份。\n※主辦單位保留活動變更權利※\n\n \n\n 劇情簡介 \n\n一個人可以為了復仇走多遠？一襲錦衣下傷痕累累的靈魂，在逐漸黑化的報仇之路上，被自己編織的心結層層纏繞，既脆弱又難解。\n\n復仇，如同一把雙刃劍，向前傷敵，亦會傷己；過往陰霾難以抹去，瞋恨如同野火肆意蔓延，吞噬著俠客曾經的赤子之心。\n\n滾滾紅塵的險峻江湖，正邪相爭，派系之間各有所謀，在仇恨為鋒的血腥戰場中廝殺，刀光劍影中暗藏玄機，誰能尋得那把開啟真相之門的金鑰？ \n\n \n\n\n\n 團隊成員 \n\n\n主講人：\n編　劇｜劉建幗\n\n與談人：\n臺灣豫劇團藝術總監｜王海玲\n臺灣豫劇團當家花旦｜蕭揚玲\n臺灣豫劇團豫劇王子｜劉建華\n\n \n\n\n 演出團隊｜臺灣豫劇團 \n\n豫劇屬梆子劇種，深具北方率真、奔放、豪邁之特色。臺灣豫劇團立基高雄左營耕耘至今70年，由臺灣豫劇皇后王海玲與開枝散葉的新生代演員，不斷努力創新，融入臺灣在地人文風情及藝術涵養，形成獨特的臺灣風格豫劇。每年皆製作年度大戲，結合現代劇場菁英並廣於跨界合作、教育推廣，足跡履及海內外，成果豐碩。\n\n \n\n 主要人員 \n\n主講人：編劇　劉建幗\n劇場編劇、導演，作品橫跨歌仔戲、豫劇、京劇、音樂劇及大型活動典禮。臺灣藝術大學藝術學博士，高雄師範大學兼任助理教授、臺南大學兼任講師。2004年創立奇巧劇團，以跨劇種、混融多元語境與音樂形式的風格為其特色。\n\n與談人：臺灣豫劇團藝術總監 王海玲\n臺灣國寶級戲曲藝術家。國立中山大學劇場藝術系兼任副教授、國立高雄大學兼任副教授，1969年中國文藝協會頒贈戲曲表演獎章（歷年最年輕得獎人）、第六屆「中華文化藝術薪傳獎」得主、第四屆「國家文藝獎」戲劇類得主。\n\n與談人：臺灣豫劇團當家花旦 蕭揚玲\n臺灣豫劇團當家花旦，國立高雄師範大學表演藝術碩士，師承張岫雲、王海玲兩代豫劇皇后，專攻花旦及青衣。曾獲大陸2007年第11 屆「香玉杯」藝術獎、河南戲劇演員排行榜2010、2012 年度十大演員「寶島之星」獎。\n\n \n\n 票價 \n\n免費預約報名，限額100名\n\n \n\n演出單位／策畫者：臺灣豫劇團\n主辦單位：國立傳統藝術中心\n*講座將全程架機錄影\n*講座為華語發音\n*更多相關資訊隨時更新\n*主辦單位保有節目異動的權利\n\n \n\n \n\n \n\n ', '臺灣戲曲中心', '111  臺北市士林區文林路751號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '臺灣戲曲中心臺灣音樂館B1視聽室', 25.1023211, 121.5196346, '免費預約報名，限額 100 名', 'https://forms.gle/2HhrS8JbfK7hUUcZ6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《錦衣》臺灣豫劇團｜穿梭真實與虛幻—揭密《錦衣》撲朔迷離的角色世界', `description`='免費預約報名，限額 100 名\n\n \n\n 講座資訊 \n\n講座：穿梭真實與虛幻—揭密《錦衣》撲朔迷離的角色世界\n時間：3月29日(六) 14:00-16:00(13:30開放入場)\n地點：臺灣戲曲中心─臺灣音樂館B1視聽室\n主講人：\n編劇 劉建幗\n與談人：\n臺灣豫劇團藝術總監 王海玲\n臺灣豫劇團當家花旦 蕭揚玲\n臺灣豫劇團豫劇王子 劉建華\n\n \n\n 報名方式 \n\n報名鏈結：https://forms.gle/2HhrS8JbfK7hUUcZ6\n請填寫Google線上報名表單，並完整填寫基本資訊，即代表報名成功。 (講座名額：限量100名，額滿為止。)\n\n \n\n 好康加碼 \n\n好禮大放送：\n〔參加禮〕凡到場參與並完成問卷填寫的觀眾即可獲參加禮一份。\n〔摸彩禮〕現場提供數樣精美禮物，凡入場即有抽獎資格。\n〔購票禮〕於活動現場購票即可獲得購票禮一份。\n※主辦單位保留活動變更權利※\n\n \n\n 劇情簡介 \n\n一個人可以為了復仇走多遠？一襲錦衣下傷痕累累的靈魂，在逐漸黑化的報仇之路上，被自己編織的心結層層纏繞，既脆弱又難解。\n\n復仇，如同一把雙刃劍，向前傷敵，亦會傷己；過往陰霾難以抹去，瞋恨如同野火肆意蔓延，吞噬著俠客曾經的赤子之心。\n\n滾滾紅塵的險峻江湖，正邪相爭，派系之間各有所謀，在仇恨為鋒的血腥戰場中廝殺，刀光劍影中暗藏玄機，誰能尋得那把開啟真相之門的金鑰？ \n\n \n\n\n\n 團隊成員 \n\n\n主講人：\n編　劇｜劉建幗\n\n與談人：\n臺灣豫劇團藝術總監｜王海玲\n臺灣豫劇團當家花旦｜蕭揚玲\n臺灣豫劇團豫劇王子｜劉建華\n\n \n\n\n 演出團隊｜臺灣豫劇團 \n\n豫劇屬梆子劇種，深具北方率真、奔放、豪邁之特色。臺灣豫劇團立基高雄左營耕耘至今70年，由臺灣豫劇皇后王海玲與開枝散葉的新生代演員，不斷努力創新，融入臺灣在地人文風情及藝術涵養，形成獨特的臺灣風格豫劇。每年皆製作年度大戲，結合現代劇場菁英並廣於跨界合作、教育推廣，足跡履及海內外，成果豐碩。\n\n \n\n 主要人員 \n\n主講人：編劇　劉建幗\n劇場編劇、導演，作品橫跨歌仔戲、豫劇、京劇、音樂劇及大型活動典禮。臺灣藝術大學藝術學博士，高雄師範大學兼任助理教授、臺南大學兼任講師。2004年創立奇巧劇團，以跨劇種、混融多元語境與音樂形式的風格為其特色。\n\n與談人：臺灣豫劇團藝術總監 王海玲\n臺灣國寶級戲曲藝術家。國立中山大學劇場藝術系兼任副教授、國立高雄大學兼任副教授，1969年中國文藝協會頒贈戲曲表演獎章（歷年最年輕得獎人）、第六屆「中華文化藝術薪傳獎」得主、第四屆「國家文藝獎」戲劇類得主。\n\n與談人：臺灣豫劇團當家花旦 蕭揚玲\n臺灣豫劇團當家花旦，國立高雄師範大學表演藝術碩士，師承張岫雲、王海玲兩代豫劇皇后，專攻花旦及青衣。曾獲大陸2007年第11 屆「香玉杯」藝術獎、河南戲劇演員排行榜2010、2012 年度十大演員「寶島之星」獎。\n\n \n\n 票價 \n\n免費預約報名，限額100名\n\n \n\n演出單位／策畫者：臺灣豫劇團\n主辦單位：國立傳統藝術中心\n*講座將全程架機錄影\n*講座為華語發音\n*更多相關資訊隨時更新\n*主辦單位保有節目異動的權利\n\n \n\n \n\n \n\n ', `organizer`='臺灣戲曲中心', `address`='111  臺北市士林區文林路751號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺灣戲曲中心臺灣音樂館B1視聽室', `latitude`=25.1023211, `longitude`=121.5196346, `ticket_price`='免費預約報名，限額 100 名', `source_url`='https://forms.gle/2HhrS8JbfK7hUUcZ6', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e56326b32418d001b874', '躍然紙上｜2025文學與戲曲系列講座', '本節目預計2025/03/04中午12:00於Opentix售票系統早鳥啟售、03/07 晚上00:00 全面啟售\n\n \n\n 活動介紹 \n\n***從筆端到舞台，頂尖文學與戲曲大師齊聚，激盪新思想火花****\n***地表最強國文老師 陳茻 x 「打開戲箱說故事」podcast主持人 羅仕龍***\n\n【場次資訊】：臺灣音樂館視聽室(B1)\n\n\n	\n		\n			場次\n			日期\n			時間\n			主題\n			講者\n		\n		\n			第一講\n			03/22(六)\n			14:00-16:00\n			文本內外的鏡像：《源氏物語》與《光華之君》\n			◎主持人：羅仕龍\n			◎與談人：\n			盛浩偉／臺灣新生代小說家\n			陳健星／傳藝金曲獎最佳編劇\n		\n		\n			第二講\n			03/30(日)\n			14:00-16:00\n			跟詞帝玩跨界！李後主的浪漫新聲\n			◎主持人：羅仕龍\n			◎與談人：\n			陳茻／與點堂創辦人\n			陳歆翰／傳藝金曲獎最佳音樂設計\n		\n		\n			第三講\n			04/06(日)\n			14:00-16:00\n			歷史的操偶師：《得時の夢》的權力遊戲\n			◎主持人：陳茻\n			◎與談人：\n			朱宥勳／作家、文學評論家\n			伍姍姍／跨現代、傳統戲曲導演\n			吳聲杰／傳藝金曲獎最佳偶戲主演\n		\n		\n			第四講\n			04/13(日)\n			14:00-16:00\n			愛到盡頭終成空？《芙蓉歌》的哲思燒腦局\n			◎主持人：陳茻\n			◎與談人：\n			紀金慶／高人氣網紅級哲學教授\n			孫富叡／歌仔戲文學跨界先河\n			孫詩珮／一心戲劇團當家小生\n		\n		\n			第五講\n			04/20(日)\n			14:00-16:00\n			洪流中的異鄉人：民族、身分與戲劇的交會\n			◎主持人：羅仕龍\n			◎與談人：\n			謝宜安／《特搜！臺灣都市傳說》作者\n			林曉英／劇作家、客家戲曲發展史研究專家\n			蘇國慶／榮興客家採茶劇團當家小生\n		\n		\n			第六講\n			05/04(日)\n			14:00-16:00\n			孟婆的湯能洗去誰的枷鎖？戲曲、性別與命運的再詮釋\n			◎主持人：羅仕龍\n			◎與談人：\n			蔡宜文／「蔡宜文的多元宇宙」podcast主持人\n			柯世宏／真快樂掌中劇團操偶師\n			姜富琴／跨現代、傳統戲曲資深編劇、《孟婆‧湯》編劇\n		\n		\n			第七講\n			05/18(日)\n			14:00-16:00\n			未來文學診療室：請AI為靈魂開一張處方箋\n			◎主持人：羅仕龍\n			◎與談人：\n			蕭詒徽／多元領域寫作家\n			劉建幗／奇巧劇團團長\n		\n		\n			第八講\n			05/31(六)\n			14:00-16:00\n			千年賣鬼狂想曲：慾望、詭詐與靈界交易\n			◎主持人：陳茻\n			◎與談人：\n			祁立峰／鄉民教授\n			邢本寧／本事劇團團長\n		\n	\n\n\n\n• 講座全長約120分鐘，無中場休息\n• 本活動全程進行平面及影像紀錄，報名即同意主辦單位取得活動影像拍攝肖像權。\n【凡參與本系列講座任一堂，可獲得一枚戳章，集滿指定數量即可獲得臺灣戲曲中心專屬紀念好禮】\n• 集滿3點-漁夫帽，限量50組\n• 集滿5點-三合一快充線，限量50組\n• 集滿8點-環保吸管杯，限量30組\n（須至本活動現場服務台免費索取集點卡，每人每次限持一張集點卡。）\n• 主辦單位保留活動異動權\n• 視覺設計：兩隻老虎設計工作室 懷瑾\n\n \n\n 票價 \n\n新臺幣200元\n\n \n\n\n\n 票價優惠折扣 \n\n\n【早鳥】2025/3/4(二) 中午12:00～2025/3/6(四) 23:59 ，享8折優惠；「追戲迷」、「戀戲家」，享7折優惠。\n\n【全面啟售】2025/3/7(五) 00:00起，「追戲迷」、「戀戲家」、與點堂會員：享8折優惠。\n\n【套票優惠】2025/3/4(二) 中午12:00啟售\n• 任購8張(不限場次)，享7折優惠。\n•「追戲迷」、「戀戲家」、與點堂會員：任購8張(不限場次)，享6折優惠。\n※本節目適用「戀戲家」、「戲曲人」專屬生日禮5折電子購票禮券\n※本節目適用「追戲迷」8折續約電子購票禮券、「戀戲家」7折續約電子購票禮券」\n\n※一般套票購買連結：https://tttc.tw/ttc01l2iYr\n※會員套票購票連結：https://tttc.tw/ttc01XRFFv\n※單場購票連結：https://tttc.tw/ttc02ravrf    \n\n  \n\n\n主辦單位：國立傳統藝術中心\n協辦單位：與點堂\n\n \n\n \n\n \n\n ', '臺灣戲曲中心', '111  臺北市士林區文林路751號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺音館B1視聽室', 25.1023211, 121.5196346, '新臺幣200元', 'https://tttc.tw/ttc02ravrf', '[]') ON DUPLICATE KEY UPDATE `activity_name`='躍然紙上｜2025文學與戲曲系列講座', `description`='本節目預計2025/03/04中午12:00於Opentix售票系統早鳥啟售、03/07 晚上00:00 全面啟售\n\n \n\n 活動介紹 \n\n***從筆端到舞台，頂尖文學與戲曲大師齊聚，激盪新思想火花****\n***地表最強國文老師 陳茻 x 「打開戲箱說故事」podcast主持人 羅仕龍***\n\n【場次資訊】：臺灣音樂館視聽室(B1)\n\n\n	\n		\n			場次\n			日期\n			時間\n			主題\n			講者\n		\n		\n			第一講\n			03/22(六)\n			14:00-16:00\n			文本內外的鏡像：《源氏物語》與《光華之君》\n			◎主持人：羅仕龍\n			◎與談人：\n			盛浩偉／臺灣新生代小說家\n			陳健星／傳藝金曲獎最佳編劇\n		\n		\n			第二講\n			03/30(日)\n			14:00-16:00\n			跟詞帝玩跨界！李後主的浪漫新聲\n			◎主持人：羅仕龍\n			◎與談人：\n			陳茻／與點堂創辦人\n			陳歆翰／傳藝金曲獎最佳音樂設計\n		\n		\n			第三講\n			04/06(日)\n			14:00-16:00\n			歷史的操偶師：《得時の夢》的權力遊戲\n			◎主持人：陳茻\n			◎與談人：\n			朱宥勳／作家、文學評論家\n			伍姍姍／跨現代、傳統戲曲導演\n			吳聲杰／傳藝金曲獎最佳偶戲主演\n		\n		\n			第四講\n			04/13(日)\n			14:00-16:00\n			愛到盡頭終成空？《芙蓉歌》的哲思燒腦局\n			◎主持人：陳茻\n			◎與談人：\n			紀金慶／高人氣網紅級哲學教授\n			孫富叡／歌仔戲文學跨界先河\n			孫詩珮／一心戲劇團當家小生\n		\n		\n			第五講\n			04/20(日)\n			14:00-16:00\n			洪流中的異鄉人：民族、身分與戲劇的交會\n			◎主持人：羅仕龍\n			◎與談人：\n			謝宜安／《特搜！臺灣都市傳說》作者\n			林曉英／劇作家、客家戲曲發展史研究專家\n			蘇國慶／榮興客家採茶劇團當家小生\n		\n		\n			第六講\n			05/04(日)\n			14:00-16:00\n			孟婆的湯能洗去誰的枷鎖？戲曲、性別與命運的再詮釋\n			◎主持人：羅仕龍\n			◎與談人：\n			蔡宜文／「蔡宜文的多元宇宙」podcast主持人\n			柯世宏／真快樂掌中劇團操偶師\n			姜富琴／跨現代、傳統戲曲資深編劇、《孟婆‧湯》編劇\n		\n		\n			第七講\n			05/18(日)\n			14:00-16:00\n			未來文學診療室：請AI為靈魂開一張處方箋\n			◎主持人：羅仕龍\n			◎與談人：\n			蕭詒徽／多元領域寫作家\n			劉建幗／奇巧劇團團長\n		\n		\n			第八講\n			05/31(六)\n			14:00-16:00\n			千年賣鬼狂想曲：慾望、詭詐與靈界交易\n			◎主持人：陳茻\n			◎與談人：\n			祁立峰／鄉民教授\n			邢本寧／本事劇團團長\n		\n	\n\n\n\n• 講座全長約120分鐘，無中場休息\n• 本活動全程進行平面及影像紀錄，報名即同意主辦單位取得活動影像拍攝肖像權。\n【凡參與本系列講座任一堂，可獲得一枚戳章，集滿指定數量即可獲得臺灣戲曲中心專屬紀念好禮】\n• 集滿3點-漁夫帽，限量50組\n• 集滿5點-三合一快充線，限量50組\n• 集滿8點-環保吸管杯，限量30組\n（須至本活動現場服務台免費索取集點卡，每人每次限持一張集點卡。）\n• 主辦單位保留活動異動權\n• 視覺設計：兩隻老虎設計工作室 懷瑾\n\n \n\n 票價 \n\n新臺幣200元\n\n \n\n\n\n 票價優惠折扣 \n\n\n【早鳥】2025/3/4(二) 中午12:00～2025/3/6(四) 23:59 ，享8折優惠；「追戲迷」、「戀戲家」，享7折優惠。\n\n【全面啟售】2025/3/7(五) 00:00起，「追戲迷」、「戀戲家」、與點堂會員：享8折優惠。\n\n【套票優惠】2025/3/4(二) 中午12:00啟售\n• 任購8張(不限場次)，享7折優惠。\n•「追戲迷」、「戀戲家」、與點堂會員：任購8張(不限場次)，享6折優惠。\n※本節目適用「戀戲家」、「戲曲人」專屬生日禮5折電子購票禮券\n※本節目適用「追戲迷」8折續約電子購票禮券、「戀戲家」7折續約電子購票禮券」\n\n※一般套票購買連結：https://tttc.tw/ttc01l2iYr\n※會員套票購票連結：https://tttc.tw/ttc01XRFFv\n※單場購票連結：https://tttc.tw/ttc02ravrf    \n\n  \n\n\n主辦單位：國立傳統藝術中心\n協辦單位：與點堂\n\n \n\n \n\n \n\n ', `organizer`='臺灣戲曲中心', `address`='111  臺北市士林區文林路751號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺音館B1視聽室', `latitude`=25.1023211, `longitude`=121.5196346, `ticket_price`='新臺幣200元', `source_url`='https://tttc.tw/ttc02ravrf', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e56e26b32418d001b878', '攝影上桌「影像宴」創作者分享座談', ' \n\n\n\n\n活動亮點\n\n\n \n\n►國家攝影文化中心 × 攝影上桌\n\n→四位青年創作者，在桌上開展精彩《影像宴》，邀您上桌觀賞！\n\n \n\n►本場次由攝影上桌總策劃馬立群主持，邀請創作者陳冠霖、楊佳馨、李明憲、王莉婷分享他們的創作！\n\n→從對照片媒材、攝影本質的思考，到回憶保存、創傷經驗和信仰慾望等議題的探究，且聽他們娓娓道來自己的創作思考！\n\n \n\n \n\n\n活動時間\n\n\n2025年3月16日（日）\n\n15:00~16:00\n\n \n\n\n活動地點\n\n\n國家攝影文化中心 臺北館 206教室\n\n來館交通：交通資訊點此\n\n \n\n\n講者簡介\n\n\n \n\n陳冠霖｜參展創作者\n\n1997 年生，臺北人。就讀國立臺北藝術大學美術學系碩士班，在學期間於德國斯圖加特高等設計學院（Merz Akademie， Stuttgart）進行交換。以平面攝影及影像裝置為主要創作媒材，攝影主題圍繞在廢墟空間，如八仙水上樂園及新竹第六燃料廠；影像裝置著重於探討拍攝者與被攝者的對立關係，如何透過影像與觀者產生實質的互動。1997 年生，臺北人。就讀國立臺北藝術大學美術學系碩士班，在學期間於德國斯圖加特高等設計學院（Merz Akademie， Stuttgart）進行交換。以平面攝影及影像裝置為主要創作媒材，攝影主題圍繞在廢墟空間，如八仙水上樂園及新竹第六燃料廠；影像裝置著重於探討拍攝者與被攝者的對立關係，如何透過影像與觀者產生實質的互動。\n\n \n\n\n \n\n楊佳馨｜參展創作者\n\n1999 年出生於臺灣臺南，目前創作生活於臺灣臺北。透過攝影、影像裝置、藝術家書等多元媒材、媒介分享「病痛經驗與其創傷」之課題，由疼痛、印痕與其延伸探索身體、影像經驗、材質、物與空間的連結，反思病痛經驗與創傷所帶來的感性敍事、片面感知、身體感與多感世界等面向，以及疾病記憶與現實狀態等生命課題。\n\n \n\n\n \n\n李明憲｜參展創作者\n\n1982 年生，桃園人。社恐、口拙，以上。\n\n \n\n\n \n\n王莉婷｜參展創作者\n\n1994 年出生於臺北，目前在臺北從事攝影師和視覺藝術家的工作。從小就對世界充滿好奇心，總是在腦袋中編織各種想像的可能性。關注任何有趣且天馬行空的事物，習慣以潛意識、自我、夢作為創作內容。憑藉敏銳的直覺和本能，透過夢和潛意識中的自我延展，以時而荒誕、時而超現實的表現手法，將攝影作為媒介，讓每張照片成為攝影師自我意識的成像。\n\n \n\n\n \n\n馬立群｜攝影上桌總策劃\n\n「一影像」創辦人、大學兼任助理教授，早期從事新聞媒體工作，關注於政治、社會、城市變遷等相關議題。目前以攝影、錄像為創作的形式，其《山水形》系列作品於 2014 年全國美術展獲獎與 2016 年 11th TAGBOAT AWARD，並獲得台灣藝術銀行藏購並曾於臺灣、日本、法國、澳門、義大利等地展出。曾擔任2018年高雄攝影節發起人與策展人與 2020 年臺北國際攝影節策展人、策劃台南國際攝影節的「攝影上桌」活動，近年聚焦於臺灣攝影創作者與紀錄片導演紀錄片拍攝，於 2022 年完成「有影台灣」紀錄片。\n\n \n\n ', '國家攝影文化中心', '100  臺北市中正區忠孝西路一段70號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '國家攝影文化中心臺北館 206教室', 25.0466999, 121.514495, '無資料', 'https://event.culture.tw/mocweb/reg/NCPI/Detail.init.ctr?actId=50004', '[]') ON DUPLICATE KEY UPDATE `activity_name`='攝影上桌「影像宴」創作者分享座談', `description`=' \n\n\n\n\n活動亮點\n\n\n \n\n►國家攝影文化中心 × 攝影上桌\n\n→四位青年創作者，在桌上開展精彩《影像宴》，邀您上桌觀賞！\n\n \n\n►