INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e64826b32418d001b883', '釉下瓷器彩繪師生聯展', '展品為後驛社大學員的學習成果，從泥素胚到彩釉堆疊，經過1,230度的高溫窯燒，每件作品都是令人愛不釋手，獨一無二！\r\n', '臺中市南區戶政事務所', '臺中市南區', '2025-02-03 00:00:00', '2025-07-31 00:00:00', '南區（臺中市）=', 24.12114107, 120.6646178, '無資料', 'https://reurl.cc/M6mEYv', '[]') ON DUPLICATE KEY UPDATE `activity_name`='釉下瓷器彩繪師生聯展', `description`='展品為後驛社大學員的學習成果，從泥素胚到彩釉堆疊，經過1,230度的高溫窯燒，每件作品都是令人愛不釋手，獨一無二！\r\n', `organizer`='臺中市南區戶政事務所', `address`='臺中市南區', `start_date`='2025-02-03 00:00:00', `end_date`='2025-07-31 00:00:00', `location`='南區（臺中市）=', `latitude`=24.12114107, `longitude`=120.6646178, `ticket_price`='無資料', `source_url`='https://reurl.cc/M6mEYv', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e64826b32418d001b884', '《3D紙小龍》紙藝工作坊', '閩南地區的紙藝文化與三月的宗教與民俗活動密切相關，特別是在媽祖誕辰、送王船和廟會期間，承載著祈福、紀念與美學的多重功能。\r\n《3D紙小龍》紙藝工作坊，透過裁、折、拼等手法專業指導與組裝技法，製作富有層次感與立體感的作品，展現創新文化之美。', '桃園市政府文化局', '桃園市八德區重慶街36-1號', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '八塊厝民俗藝術村', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《3D紙小龍》紙藝工作坊', `description`='閩南地區的紙藝文化與三月的宗教與民俗活動密切相關，特別是在媽祖誕辰、送王船和廟會期間，承載著祈福、紀念與美學的多重功能。\r\n《3D紙小龍》紙藝工作坊，透過裁、折、拼等手法專業指導與組裝技法，製作富有層次感與立體感的作品，展現創新文化之美。', `organizer`='桃園市政府文化局', `address`='桃園市八德區重慶街36-1號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='八塊厝民俗藝術村', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e64826b32418d001b885', '2月主題書展', '1F主題書展\r\n[蛇我其誰] ✨新年主題書展\r\n身披鱗外衣 沒腳水陸行\r\n從史萊哲林學院徽章\r\n到醫神的蛇杖\r\n🐍蛇的蛻皮技能\r\n有著 恢復 和 更新 的過程\r\n像是重生一般\r\n🐍蛇所含的蛇毒\r\n可致死也能製藥\r\n象徵生與死的兩面\r\n🐍人類對蛇的敬畏\r\n就像是寫入基因一樣的深刻\r\n讓我們從閱讀認識蛇\r\n保持最剛剛好的社交距離\r\n🙋蛇年到\r\n溜來圖書館多看幾本書\r\n蛇年「溜」到不行\r\n事事滑順愜意\r\n\r\n2F 主題書展\r\n [閱讀外埔] ✨主題書展\r\n外埔在地文史紀錄資料\r\n閱讀 從腳踩的這塊土地開始\r\n原來 外埔那~麼精彩！\r\n', '臺中市立圖書館外埔分館', '臺中市外埔區甲后路三段1060號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺中市立圖書館外埔分館', 24.33551071, 120.6650639, '無資料', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月主題書展', `description`='1F主題書展\r\n[蛇我其誰] ✨新年主題書展\r\n身披鱗外衣 沒腳水陸行\r\n從史萊哲林學院徽章\r\n到醫神的蛇杖\r\n🐍蛇的蛻皮技能\r\n有著 恢復 和 更新 的過程\r\n像是重生一般\r\n🐍蛇所含的蛇毒\r\n可致死也能製藥\r\n象徵生與死的兩面\r\n🐍人類對蛇的敬畏\r\n就像是寫入基因一樣的深刻\r\n讓我們從閱讀認識蛇\r\n保持最剛剛好的社交距離\r\n🙋蛇年到\r\n溜來圖書館多看幾本書\r\n蛇年「溜」到不行\r\n事事滑順愜意\r\n\r\n2F 主題書展\r\n [閱讀外埔] ✨主題書展\r\n外埔在地文史紀錄資料\r\n閱讀 從腳踩的這塊土地開始\r\n原來 外埔那~麼精彩！\r\n', `organizer`='臺中市立圖書館外埔分館', `address`='臺中市外埔區甲后路三段1060號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺中市立圖書館外埔分館', `latitude`=24.33551071, `longitude`=120.6650639, `ticket_price`='無資料', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e64926b32418d001b886', '桃園光影文化館【光聚影像】角落小夥伴電影版：奇幻的玩具工廠【國語配音版】 Sumikkogurashi : The Patched-Up Toy Factory in the Woods ［普］', '某日，住在北極的家人請企鵝將兒時的絨毛玩偶帶給白熊，沒想到玩偶胸前的鈕扣卻不見了。正當小夥伴們一同進入森林尋找時，卻意外發現一間老舊的玩具工廠。受到工廠裡「棕熊廠長」的邀請，小夥伴們發揮專長試著生產玩具。但他們萬萬沒想到，自己努力生產的玩具，卻為角落小鎮帶來超級大麻煩！？究竟這間工廠藏著什麼秘密？剛上工的小夥伴要如何面對這個挑戰？', '桃園市政府文化局', '桃園市桃園區埔新路12號', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '桃園光影文化館', 25.00040024, 121.2996612, '無資料', 'https://kktix.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園光影文化館【光聚影像】角落小夥伴電影版：奇幻的玩具工廠【國語配音版】 Sumikkogurashi : The Patched-Up Toy Factory in the Woods ［普］', `description`='某日，住在北極的家人請企鵝將兒時的絨毛玩偶帶給白熊，沒想到玩偶胸前的鈕扣卻不見了。正當小夥伴們一同進入森林尋找時，卻意外發現一間老舊的玩具工廠。受到工廠裡「棕熊廠長」的邀請，小夥伴們發揮專長試著生產玩具。但他們萬萬沒想到，自己努力生產的玩具，卻為角落小鎮帶來超級大麻煩！？究竟這間工廠藏著什麼秘密？剛上工的小夥伴要如何面對這個挑戰？', `organizer`='桃園市政府文化局', `address`='桃園市桃園區埔新路12號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='桃園光影文化館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='https://kktix.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e64926b32418d001b887', '桃園光影文化館【光聚影像】角頭-大橋頭 GATAO: Like Father Like Son［限］', 'Michael哥回來了，他「跟天借膽」 ，帶著瘋蠍子想拿下頂莊、北城、北館，在貴董、哈達、勇桑的眼皮子底下賣藥，甚至想仗著自己幾分交情，拉攏勇桑的二把手清楓，沒想到被打得灰頭土臉， 卻在這時，他看不上眼的土狗們阿猛、阿慶、宗保，竟然能闖入仁哥、憨春的賭場，搶下巨款，還活著回來，讓他又驚又喜。', '桃園市政府文化局', '桃園市桃園區埔新路12號', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '桃園光影文化館', 25.00040024, 121.2996612, '無資料', 'https://kktix.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園光影文化館【光聚影像】角頭-大橋頭 GATAO: Like Father Like Son［限］', `description`='Michael哥回來了，他「跟天借膽」 ，帶著瘋蠍子想拿下頂莊、北城、北館，在貴董、哈達、勇桑的眼皮子底下賣藥，甚至想仗著自己幾分交情，拉攏勇桑的二把手清楓，沒想到被打得灰頭土臉， 卻在這時，他看不上眼的土狗們阿猛、阿慶、宗保，竟然能闖入仁哥、憨春的賭場，搶下巨款，還活著回來，讓他又驚又喜。', `organizer`='桃園市政府文化局', `address`='桃園市桃園區埔新路12號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='桃園光影文化館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='https://kktix.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e64926b32418d001b888', '桃園光影文化館【光聚影像】阿凡達 Avatar［普］', '貪婪人類為了掠奪潘朵拉星球上珍貴的資源，以人類和納美人DNA混種的三公尺高媒介阿凡達，作為人類心智操控的身軀，進出美麗卻不適合人類活超過5分鐘的險惡潘朵拉。傑克躺在像是核子共振掃描的船艙裡，傳送心智訊息到阿凡達，深入潘朵拉、取得納美人的信賴和從事情資蒐集活動。這位和平使者將歷經三個月的納美文化體驗，學習傾聽大自然的聲音和感受無所不在流動的能量，最後陷入選邊站的掙扎。', '桃園市政府文化局', '桃園市桃園區埔新路12號', '2025-03-02 00:00:00', '2025-03-02 00:00:00', '桃園光影文化館', 25.00040024, 121.2996612, '無資料', 'https://kktix.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園光影文化館【光聚影像】阿凡達 Avatar［普］', `description`='貪婪人類為了掠奪潘朵拉星球上珍貴的資源，以人類和納美人DNA混種的三公尺高媒介阿凡達，作為人類心智操控的身軀，進出美麗卻不適合人類活超過5分鐘的險惡潘朵拉。傑克躺在像是核子共振掃描的船艙裡，傳送心智訊息到阿凡達，深入潘朵拉、取得納美人的信賴和從事情資蒐集活動。這位和平使者將歷經三個月的納美文化體驗，學習傾聽大自然的聲音和感受無所不在流動的能量，最後陷入選邊站的掙扎。', `organizer`='桃園市政府文化局', `address`='桃園市桃園區埔新路12號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='桃園光影文化館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='https://kktix.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e64926b32418d001b889', '桃園光影文化館【光聚影像】阿凡達：水之道 Avatar: The Way of Water［護］', '成為納美人並與奈蒂莉共結連理的傑克，在潘朵拉星上與他們的孩子組成蘇里一家，過著與世無爭的幸福生活，未料威脅再度降臨，他們不遺餘力保護彼此，為了生存再度奮戰，還得承受隨之而來的悲痛創傷。', '桃園市政府文化局', '桃園市桃園區埔新路12號', '2025-03-02 00:00:00', '2025-03-02 00:00:00', '桃園光影文化館', 25.00040024, 121.2996612, '無資料', 'https://kktix.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園光影文化館【光聚影像】阿凡達：水之道 Avatar: The Way of Water［護］', `description`='成為納美人並與奈蒂莉共結連理的傑克，在潘朵拉星上與他們的孩子組成蘇里一家，過著與世無爭的幸福生活，未料威脅再度降臨，他們不遺餘力保護彼此，為了生存再度奮戰，還得承受隨之而來的悲痛創傷。', `organizer`='桃園市政府文化局', `address`='桃園市桃園區埔新路12號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='桃園光影文化館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='https://kktix.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e64926b32418d001b88a', '臺中市藝術亮點-何志隆翡翠青瓷特展', '青瓷，介於藍色和綠色之間，呈現如翡翠般的色澤和質感，「素胎入窯，滿釉出窯」，經過焠火淬煉，展現渾然天成的氣韻美感。\r\n\r\n這場獨特的青瓷藝術盛宴，於霧峰林家宮保第園區隆重展出，展覽由青瓷大師—何志隆，攜手其子 何竹昉、何宜謙\r\n共同展現翡翠青瓷的窯燒技藝之美。不僅展現對工藝的極致追求，更體現了對文化傳承的深刻探索與情感連結。', '翡翠青瓷藝術文化有限公司', '臺中市霧峰區民生路26號', '2025-01-25 00:00:00', '2025-03-20 00:00:00', '霧峰林家宮保第園區', 24.04332785, 120.7201989, '全票+250;12歲以上學生、65歲以上老人、台中市民+200;6歲以上學童票+125', 'https://www.wufenglins.com.tw/news_d.php?i=344', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-何志隆翡翠青瓷特展', `description`='青瓷，介於藍色和綠色之間，呈現如翡翠般的色澤和質感，「素胎入窯，滿釉出窯」，經過焠火淬煉，展現渾然天成的氣韻美感。\r\n\r\n這場獨特的青瓷藝術盛宴，於霧峰林家宮保第園區隆重展出，展覽由青瓷大師—何志隆，攜手其子 何竹昉、何宜謙\r\n共同展現翡翠青瓷的窯燒技藝之美。不僅展現對工藝的極致追求，更體現了對文化傳承的深刻探索與情感連結。', `organizer`='翡翠青瓷藝術文化有限公司', `address`='臺中市霧峰區民生路26號', `start_date`='2025-01-25 00:00:00', `end_date`='2025-03-20 00:00:00', `location`='霧峰林家宮保第園區', `latitude`=24.04332785, `longitude`=120.7201989, `ticket_price`='全票+250;12歲以上學生、65歲以上老人、台中市民+200;6歲以上學童票+125', `source_url`='https://www.wufenglins.com.tw/news_d.php?i=344', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e64926b32418d001b88b', '如果我有一輛車｜ 施姵伃 個展', '如果我有一輛車...\r\nIf I had a car ...\r\n- \r\n繁忙的生活不外乎就是往返工作與家之間,一天下來鮮少有時間與自己靜下心來對話,不能停下來思考這件事使人身心俱疲,除了在通勤時乘坐交通工具的破碎時光,在這樣的密閉空間裡,成了生活中唯一可以喘息的放鬆時間。\r\n小時候很喜歡躲藏在棉被中、櫃子裡,那樣的封閉、靜謐往往帶來了一些安全感,就像世界只剩下我一個人。我發現乘車時也有一樣的感覺,坐在這個安心的小空間裡,能冷靜下來,讓思緒可以飛得很遠,暫時遠離繁忙的外界,這是在成為大人後少數、可以擁有的純粹時光,若這時候再搭配個美食就再好不過了!\r\n這段從一個地方到另一個地方的過渡時間,是一天中難得的休憩時光,而食物就像苦悶生活的甜味增強劑,當咀嚼著甜滋滋的零食時,身體和心理都瞬間得到放鬆,在這些片刻之間,微小的享受,也成為了生活中不可或缺的解藥。\r\n此次展覽我想透過對日常的經歷和觀察,將常見的場景和情感聯繫起來,即使我們身處在喧囂的世界中,卻仍需要有屬於自己的空間與寧靜。如果我有一輛車,是一輛......。\r\n\r\n#陶瓷  #個展', '雨果曐Gallery', '臺中市西區', '2025-02-08 00:00:00', '2025-03-16 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/RL7yjD', '[]') ON DUPLICATE KEY UPDATE `activity_name`='如果我有一輛車｜ 施姵伃 個展', `description`='如果我有一輛車...\r\nIf I had a car ...\r\n- \r\n繁忙的生活不外乎就是往返工作與家之間,一天下來鮮少有時間與自己靜下心來對話,不能停下來思考這件事使人身心俱疲,除了在通勤時乘坐交通工具的破碎時光,在這樣的密閉空間裡,成了生活中唯一可以喘息的放鬆時間。\r\n小時候很喜歡躲藏在棉被中、櫃子裡,那樣的封閉、靜謐往往帶來了一些安全感,就像世界只剩下我一個人。我發現乘車時也有一樣的感覺,坐在這個安心的小空間裡,能冷靜下來,讓思緒可以飛得很遠,暫時遠離繁忙的外界,這是在成為大人後少數、可以擁有的純粹時光,若這時候再搭配個美食就再好不過了!\r\n這段從一個地方到另一個地方的過渡時間,是一天中難得的休憩時光,而食物就像苦悶生活的甜味增強劑,當咀嚼著甜滋滋的零食時,身體和心理都瞬間得到放鬆,在這些片刻之間,微小的享受,也成為了生活中不可或缺的解藥。\r\n此次展覽我想透過對日常的經歷和觀察,將常見的場景和情感聯繫起來,即使我們身處在喧囂的世界中,卻仍需要有屬於自己的空間與寧靜。如果我有一輛車,是一輛......。\r\n\r\n#陶瓷  #個展', `organizer`='雨果曐Gallery', `address`='臺中市西區', `start_date`='2025-02-08 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/RL7yjD', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e64a26b32418d001b88c', '大視界：當代女性藝術的多重詮釋', '本展覽將視角投射於女性創作，揭示時代交織下的宏觀視野與細膩感知，接軌當代潮流與思想，探討文化、情感與自然的多重維度。參展藝術家有：王綺穗WANG Chi-Sui、申吏羅SHIN Rira、石垣美幸ISHIGAKI Miyuki、江宇（馮慧中）JIANG Yu（FENG Hui-Chung）、吳欣宇WU Hsin-Yu、高山琴KOH San-Keum、崔娜利CHOI Nari、張若綺CHANG Ruo-Chi、梁美琪Maartje BLANS、許維頴HSU Wei-Ying、游孟書YOU Meng-Shu、黃曼滋Ng Buan-Cher、蓓特•絲珂約特迦德Bente SKJøTTGAARD 共13位，分為五個展覽子題。\r\n\r\n\r\n文化重構：記憶與身份\r\n藝術家：高山琴KOH San-Keum、王綺穗WANG Chi-Sui、江宇（馮慧中）JIANG Yu（FENG Hui-Chung）\r\n\r\n「我們不是出生時就成為我們所是的，而是經過不斷的歷程，成為我們所成為的。」 — 卡爾•榮格（Carl Jung）\r\n\r\n聚焦在當代社會中身份認同的變遷與記憶的重構。面對全球化、移民潮以及身份模糊的現實，藝術家從個人記憶與社會文化的交匯處，探索如何重塑自我與他者的關係，探索當代藝術中文化和身份的重構。高山琴（KOH San-Keum）《L''Etranger Albert Camus Pp.25-80》（《異鄉人》阿爾貝‧卡繆第25-80頁），以珍珠與丙烯為媒材，將文學內容簡化為編碼的視覺元素，呈現出語言的內在價值與純粹的美學形式。她融合傳統與現代的文化符號，讓觀者感受形式與意義之間的深邃對話。王綺穗（WANG Chi-Sui）《縫縫之線空間》以縫合的行為象徵修補與連結，反映生命中的斷裂與重塑過程。線條在作品中延展出空間的張力，既是連結的載體，也是記憶的痕跡。江宇（JIANG Yu）《春天A花》與《戴耳環的夫人》運用幽默與細膩的視覺語言，探討女性形象與日常物品的象徵意義；挑戰傳統的性別與身份框架，傳達對當代社會中性別角色及自我認同的深刻思考。\r\n\r\n\r\n衝突與融合：文化的再造\r\n藝術家：游孟書YOU Meng-Shu、崔娜利CHOI Nari\r\n\r\n「文化是一種無形的力量，能夠塑造一個民族的靈魂。」 — 雷蒙•威廉斯（Raymond Williams）\r\n\r\n這系列作品突顯了當下文化交流的迅速擴展及其對個人與集體身份的深刻影響，讓藝術家對文化再造的過程進行反思。游孟書（YOU Meng-Shu）以當代流行文化符號如小熊維尼、忍者龜等為創作元素，挑戰現代社會中文化的表象與其背後隱藏的情感，並展現對跨文化的深刻探討；作品中的「美力」與「拜拜」將美國文化的符號與臺灣的宗教儀式相結合，藉由象徵性與諷刺性的手法，強調兩者間的衝突與融合。崔娜利（CHOI Nari）的作品《他與她的波長》則透過細膩的畫面結構，探索人際間情感的共鳴與不協調，反映了現代社會中情感與文化的斷層；她的創作不僅是對當代人際關係的深刻反思，還對當前全球化與文化多樣性的交流進行了探索。\r\n\r\n\r\n情感印記：畫中的迴響\r\n藝術家：張若綺CHANG Ruo-Chi、黃曼滋Ng Buan-Cher\r\n\r\n「時間的流逝使得一切變得模糊，然而記憶像鑽石一樣，在心中嵌入深深的印記。」 — 薩爾瓦多•達利（Salvador Dalí）\r\n\r\n探討生命的流轉、時間的流逝，以及情感與記憶之間的深刻聯繫。張若綺（CHANG Ruo-Chi）以抽象語彙映照出自然、社會與內心的多重層次。《痕》以金色象徵光明與希望，承載自然復甦的力量；蜿蜒如河的線條流動著記憶的碎片，隱喻個體與環境間的深層交織，呼應人類在時光中留下的印記與對未來的期許。《流轉之境》呈現人類與地球共生的永恆哲理，關注個體的情感與記憶，更延伸至當代社會快速變遷的集體經驗，並反思科技進步對環境與情感連結的影響：在無序中尋找秩序，於混亂中擁抱希望。黃曼滋（Ng Buan-Cher）的作品以黑白為主，透過簡潔的色彩對比與細膩的層次處理，營造出內斂而充滿力量的視覺空間，邀請觀者進行沉靜的心靈對話。她以抽象表現手法探索時間、記憶與情感的多重層次，通過層疊的筆觸與線條構築時間流逝的軌跡與情感波動。《The Day - I》表達過去的未解，《The Day After - II》象徵重建與反思，《The Day After - I》捕捉特定瞬間的深刻影響。作品結合個人情感與普遍生命經驗，啟發觀者重新審視時間與存在的深刻意義。\r\n\r\n\r\n空間邊界：日常感知的探索\r\n藝術家：吳欣宇WU Hsin-Yu、梁美琪Maartje BLANS、申吏羅SHIN Rira\r\n\r\n「我們的視覺世界是我們經驗的反映，而這反映並非固定，而是隨著每一個當下的感知變化。」 — 賽義德•胡塞因（Sayed Kashua）\r\n\r\n創作透過抽象與具象形式探討了空間與感知之間的互動，呈現出空間如何影響觀者的感知，並挑戰我們對視覺與時間的理解。吳欣宇（WU Hsin-Yu）的《無題16740》運用層疊結構，隱喻時間的流逝與記憶的斷裂，畫面中的層次變化，呈現了空間的深度與複雜性，挑戰觀者對視覺元素反映出空間的動態流動。梁美琪Maartje BLANS的《筆墨裝置》突破了平面界限，通過裝置形式將筆觸與材質融入空間，將日常物品轉化為空間中的情境，讓觀者重新思考感知的方式，挑戰當代藝術的傳統界限。申吏羅（SHIN Rira）的《Afternoon''s Montage》將空間作為構建感知的基礎，將觀者引入一個超扁平、虛擬的空間，挑戰日常視覺的習慣性理解；這一作品讓觀者步入一個充滿層次感與對比的視覺世界，在此空間中，時間與記憶逐漸模糊，進而引發對日常生活中空間感知的深刻反思。他們都探討了空間與感知之間的微妙關聯，並呈現出視覺、時間與空間的交互作用。\r\n\r\n\r\n自然軌跡：詩意的探索\r\n藝術家：石垣美幸ISHIGAKI Miyuki、蓓特•絲珂約特迦德Bente SKJøTTGAARD、許維頴HSU Wei-Ying\r\n\r\n「我們與自然的關係並不是依賴它，而是與它共同成長。」 — 阿爾多•李奧波德（Aldo Leopold）\r\n\r\n在全球環境危機日益嚴峻的背景下，這一系列反映了人類與自然之間愈加疏遠的關係。藝術家們以各自獨特的視角，探索自然與人類活動的交織，將自然的詩意與力量融入作品中，呼應當前生態意識的覺醒，並呈現無形的美學。石垣美幸（ISHIGAKI Miyuki）以編織技術巧妙地將植物和自然形態融入其中，營造出一個生命力與自然息息相關的世界，傳達出自然的動態與生命的延續。蓓特•絲珂約特迦德Bente SKJøTTGAARD的陶瓷作品則通過釉料的起泡與滴落技法，創造出有機且抽象的視覺效果，將自然形式的變化與無序之美帶入陶瓷藝術的新領域。許維頴（HSU Wei-Ying）則運用光影作為媒介，通過簡潔的表現手法深入探討人類與自然界之間的共生關係，將自然界的生命力以光影延續於作品中，表現出人類與自然和諧共處的可能性。這些作品共同呈現了對自然與生命深刻的詩意探索，並強調了回歸與重視自然的必要性，在當今快速變遷的時代背景下，呼喚人們反思與自然的聯繫。\r\n\r\n展覽的子題順序呈現由內到外、由個人到全球的敘事邏輯。「文化重構：記憶與身份」和「衝突與融合：文化的再造」先探討了個體與文化的關係，接著進入情感與記憶的層面，再到自然與環境的關聯。引導觀者從個體的內心世界，逐步走向更宏觀的社會與全球議題。這五個系列在藝術創作中反映了當代社會的潮流與趨勢，無論是對身份、情感還是自然的詮釋，都呼應了當下人類面對的全球性挑戰與情感需求，強調了藝術作為當代文化表達的價值和力量。藉由這些主題，探索藝術如何成為女性對自身與世界對話的媒介。正如西蒙娜•波娃所言：「女人不是天生的，而是後天成為的。」此展覽呼應全球性別議題與環境變遷，藉藝術之手重塑存在的哲學意義，透過多元媒材與形式，展現女性創作者對生命與社會的深刻反思與前瞻性願景。\r\n\r\n#油畫  #粉彩  #水墨  #聯展', '大象藝術空間館', '臺中市北區博館路15號', '2025-02-08 00:00:00', '2025-05-03 00:00:00', '大象藝術空間館', 24.15863985, 120.6809521, '無資料', 'https://daxiang.com.tw/exhib/current', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大視界：當代女性藝術的多重詮釋', `description`='本展覽將視角投射於女性創作，揭示時代交織下的宏觀視野與細膩感知，接軌當代潮流與思想，探討文化、情感與自然的多重維度。參展藝術家有：王綺穗WANG Chi-Sui、申吏羅SHIN Rira、石垣美幸ISHIGAKI Miyuki、江宇（馮慧中）JIANG Yu（FENG Hui-Chung）、吳欣宇WU Hsin-Yu、高山琴KOH San-Keum、崔娜利CHOI Nari、張若綺CHANG Ruo-Chi、梁美琪Maartje BLANS、許維頴HSU Wei-Ying、游孟書YOU Meng-Shu、黃曼滋Ng Buan-Cher、蓓特•絲珂約特迦德Bente SKJøTTGAARD 共13位，分為五個展覽子題。\r\n\r\n\r\n文化重構：記憶與身份\r\n藝術家：高山琴KOH San-Keum、王綺穗WANG Chi-Sui、江宇（馮慧中）JIANG Yu（FENG Hui-Chung）\r\n\r\n「我們不是出生時就成為我們所是的，而是經過不斷的歷程，成為我們所成為的。」 — 卡爾•榮格（Carl Jung）\r\n\r\n聚焦在當代社會中身份認同的變遷與記憶的重構。面對全球化、移民潮以及身份模糊的現實，藝術家從個人記憶與社會文化的交匯處，探索如何重塑自我與他者的關係，探索當代藝術中文化和身份的重構。高山琴（KOH San-Keum）《L''Etranger Albert Camus Pp.25-80》（《異鄉人》阿爾貝‧卡繆第25-80頁），以珍珠與丙烯為媒材，將文學內容簡化為編碼的視覺元素，呈現出語言的內在價值與純粹的美學形式。她融合傳統與現代的文化符號，讓觀者感受形式與意義之間的深邃對話。王綺穗（WANG Chi-Sui）《縫縫之線空間》以縫合的行為象徵修補與連結，反映生命中的斷裂與重塑過程。線條在作品中延展出空間的張力，既是連結的載體，也是記憶的痕跡。江宇（JIANG Yu）《春天A花》與《戴耳環的夫人》運用幽默與細膩的視覺語言，探討女性形象與日常物品的象徵意義；挑戰傳統的性別與身份框架，傳達對當代社會中性別角色及自我認同的深刻思考。\r\n\r\n\r\n衝突與融合：文化的再造\r\n藝術家：游孟書YOU Meng-Shu、崔娜利CHOI Nari\r\n\r\n「文化是一種無形的力量，能夠塑造一個民族的靈魂。」 — 雷蒙•威廉斯（Raymond Williams）\r\n\r\n這系列作品突顯了當下文化交流的迅速擴展及其對個人與集體身份的深刻影響，讓藝術家對文化再造的過程進行反思。游孟書（YOU Meng-Shu）以當代流行文化符號如小熊維尼、忍者龜等為創作元素，挑戰現代社會中文化的表象與其背後隱藏的情感，並展現對跨文化的深刻探討；作品中的「美力」與「拜拜」將美國文化的符號與臺灣的宗教儀式相結合，藉由象徵性與諷刺性的手法，強調兩者間的衝突與融合。崔娜利（CHOI Nari）的作品《他與她的波長》則透過細膩的畫面結構，探索人際間情感的共鳴與不協調，反映了現代社會中情感與文化的斷層；她的創作不僅是對當代人際關係的深刻反思，還對當前全球化與文化多樣性的交流進行了探索。\r\n\r\n\r\n情感印記：畫中的迴響\r\n藝術家：張若綺CHANG Ruo-Chi、黃曼滋Ng Buan-Cher\r\n\r\n「時間的流逝使得一切變得模糊，然而記憶像鑽石一樣，在心中嵌入深深的印記。」 — 薩爾瓦多•達利（Salvador Dalí）\r\n\r\n探討生命的流轉、時間的流逝，以及情感與記憶之間的深刻聯繫。張若綺（CHANG Ruo-Chi）以抽象語彙映照出自然、社會與內心的多重層次。《痕》以金色象徵光明與希望，承載自然復甦的力量；蜿蜒如河的線條流動著記憶的碎片，隱喻個體與環境間的深層交織，呼應人類在時光中留下的印記與對未來的期許。《流轉之境》呈現人類與地球共生的永恆哲理，關注個體的情感與記憶，更延伸至當代社會快速變遷的集體經驗，並反思科技進步對環境與情感連結的影響：在無序中尋找秩序，於混亂中擁抱希望。黃曼滋（Ng Buan-Cher）的作品以黑白為主，透過簡潔的色彩對比與細膩的層次處理，營造出內斂而充滿力量的視覺空間，邀請觀者進行沉靜的心靈對話。她以抽象表現手法探索時間、記憶與情感的多重層次，通過層疊的筆觸與線條構築時間流逝的軌跡與情感波動。《The Day - I》表達過去的未解，《The Day After - II》象徵重建與反思，《The Day After - I》捕捉特定瞬間的深刻影響。作品結合個人情感與普遍生命經驗，啟發觀者重新審視時間與存在的深刻意義。\r\n\r\n\r\n空間邊界：日常感知的探索\r\n藝術家：吳欣宇WU Hsin-Yu、梁美琪Maartje BLANS、申吏羅SHIN Rira\r\n\r\n「我們的視覺世界是我們經驗的反映，而這反映並非固定，而是隨著每一個當下的感知變化。」 — 賽義德•胡塞因（Sayed Kashua）\r\n\r\n創作透過抽象與具象形式探討了空間與感知之間的互動，呈現出空間如何影響觀者的感知，並挑戰我們對視覺與時間的理解。吳欣宇（WU Hsin-Yu）的《無題16740》運用層疊結構，隱喻時間的流逝與記憶的斷裂，畫面中的層次變化，呈現了空間的深度與複雜性，挑戰觀者對視覺元素反映出空間的動態流動。梁美琪Maartje BLANS的《筆墨裝置》突破了平面界限，通過裝置形式將筆觸與材質融入空間，將日常物品轉化為空間中的情境，讓觀者重新思考感知的方式，挑戰當代藝術的傳統界限。申吏羅（SHIN Rira）的《Afternoon''s Montage》將空間作為構建感知的基礎，將觀者引入一個超扁平、虛擬的空間，挑戰日常視覺的習慣性理解；這一作品讓觀者步入一個充滿層次感與對比的視覺世界，在此空間中，時間與記憶逐漸模糊，進而引發對日常生活中空間感知的深刻反思。他們都探討了空間與感知之間的微妙關聯，並呈現出視覺、時間與空間的交互作用。\r\n\r\n\r\n自然軌跡：詩意的探索\r\n藝術家：石垣美幸ISHIGAKI Miyuki、蓓特•絲珂約特迦德Bente SKJøTTGAARD、許維頴HSU Wei-Ying\r\n\r\n「我們與自然的關係並不是依賴它，而是與它共同成長。」 — 阿爾多•李奧波德（Aldo Leopold）\r\n\r\n在全球環境危機日益嚴峻的背景下，這一系列反映了人類與自然之間愈加疏遠的關係。藝術家們以各自獨特的視角，探索自然與人類活動的交織，將自然的詩意與力量融入作品中，呼應當前生態意識的覺醒，並呈現無形的美學。石垣美幸（ISHIGAKI Miyuki）以編織技術巧妙地將植物和自然形態融入其中，營造出一個生命力與自然息息相關的世界，傳達出自然的動態與生命的延續。蓓特•絲珂約特迦德Bente SKJøTTGAARD的陶瓷作品則通過釉料的起泡與滴落技法，創造出有機且抽象的視覺效果，將自然形式的變化與無序之美帶入陶瓷藝術的新領域。許維頴（HSU Wei-Ying）則運用光影作為媒介，通過簡潔的表現手法深入探討人類與自然界之間的共生關係，將自然界的生命力以光影延續於作品中，表現出人類與自然和諧共處的可能性。這些作品共同呈現了對自然與生命深刻的詩意探索，並強調了回歸與重視自然的必要性，在當今快速變遷的時代背景下，呼喚人們反思與自然的聯繫。\r\n\r\n展覽的子題順序呈現由內到外、由個人到全球的敘事邏輯。「文化重構：記憶與身份」和「衝突與融合：文化的再造」先探討了個體與文化的關係，接著進入情感與記憶的層面，再到自然與環境的關聯。引導觀者從個體的內心世界，逐步走向更宏觀的社會與全球議題。這五個系列在藝術創作中反映了當代社會的潮流與趨勢，無論是對身份、情感還是自然的詮釋，都呼應了當下人類面對的全球性挑戰與情感需求，強調了藝術作為當代文化表達的價值和力量。藉由這些主題，探索藝術如何成為女性對自身與世界對話的媒介。正如西蒙娜•波娃所言：「女人不是天生的，而是後天成為的。」此展覽呼應全球性別議題與環境變遷，藉藝術之手重塑存在的哲學意義，透過多元媒材與形式，展現女性創作者對生命與社會的深刻反思與前瞻性願景。\r\n\r\n#油畫  #粉彩  #水墨  #聯展', `organizer`='大象藝術空間館', `address`='臺中市北區博館路15號', `start_date`='2025-02-08 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='大象藝術空間館', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://daxiang.com.tw/exhib/current', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e64d26b32418d001b88d', 'Dreams within a dream │李兆起  林芳瑜  陳孟潔 聯展', '展覽介紹Exhibition Introduction｜\r\n\r\n夢境，如同現實的遮蔽，日常景觀的浸染，彷如幻境，一個猶如舞台䆋置般的 世界。是一個希冀維持某種美好生活秩序的「波坦金村」(Potemkin Village)。\r\n\r\n「波坦金村(Potemkin Village) 」一詞源自俄國陸軍元帥為了取悅女皇，將出 巡的沿線設置了徒具外觀的村莊繪板，用以妝點、掩飾，刻意地豎起建築物的 立面，這些模型般的建築被寄託著繁榮的假象。直至現今，波坦金村也存在。\r\n\r\n本次展出三位藝術家的作品，均代表著他們由生活所衍生出的「現實夢」與 「波坦金村」，展覽空間是一個實際上從無人居住之地，而藝術家們除了建造， 也為「現實」進行刪修，創作作品，從而衍生關於藝術的用與不用，能與不能。\r\n\r\n這些作品或多或少具備「可愛」的特質，不過引用與延伸評論家四方田犬彥所 言：「可愛已經成為遍布全球的一大現象，具有獨一無二的徹底去政治化。」可 愛亦有所圖，藝術又何嘗不是？\r\n\r\n本檔展覽，試以詼諧輕鬆的視覺角度切入，希望觀者由「已知」思考「未見」、 由「觀察」思索「未思」、由「遮蔽」意識「彰顯」，我們都活在現實與想像之間，共時的切面，若找尋「真生活」沒有「方法」(way)，也能使用「詭計」 (ruse)。\r\n\r\n#裝置作品  #雕塑  #壓克力畫  #聯展', '寬藝術空間', '臺中市西區台中市西區向上路一段79巷38號', '2025-02-15 00:00:00', '2025-03-30 00:00:00', '寬藝術空間', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/WAZQo5', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Dreams within a dream │李兆起  林芳瑜  陳孟潔 聯展', `description`='展覽介紹Exhibition Introduction｜\r\n\r\n夢境，如同現實的遮蔽，日常景觀的浸染，彷如幻境，一個猶如舞台䆋置般的 世界。是一個希冀維持某種美好生活秩序的「波坦金村」(Potemkin Village)。\r\n\r\n「波坦金村(Potemkin Village) 」一詞源自俄國陸軍元帥為了取悅女皇，將出 巡的沿線設置了徒具外觀的村莊繪板，用以妝點、掩飾，刻意地豎起建築物的 立面，這些模型般的建築被寄託著繁榮的假象。直至現今，波坦金村也存在。\r\n\r\n本次展出三位藝術家的作品，均代表著他們由生活所衍生出的「現實夢」與 「波坦金村」，展覽空間是一個實際上從無人居住之地，而藝術家們除了建造， 也為「現實」進行刪修，創作作品，從而衍生關於藝術的用與不用，能與不能。\r\n\r\n這些作品或多或少具備「可愛」的特質，不過引用與延伸評論家四方田犬彥所 言：「可愛已經成為遍布全球的一大現象，具有獨一無二的徹底去政治化。」可 愛亦有所圖，藝術又何嘗不是？\r\n\r\n本檔展覽，試以詼諧輕鬆的視覺角度切入，希望觀者由「已知」思考「未見」、 由「觀察」思索「未思」、由「遮蔽」意識「彰顯」，我們都活在現實與想像之間，共時的切面，若找尋「真生活」沒有「方法」(way)，也能使用「詭計」 (ruse)。\r\n\r\n#裝置作品  #雕塑  #壓克力畫  #聯展', `organizer`='寬藝術空間', `address`='臺中市西區台中市西區向上路一段79巷38號', `start_date`='2025-02-15 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='寬藝術空間', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/WAZQo5', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e64d26b32418d001b88e', '舊夢新材-林彥甫創作個展', '「舊夢新材」為藝術家林彥甫賦予作品平凡材質與物件新角色與說法，展開「近似語言」的詩意對話。透過低頻幽默與躁動，引導探索內在邏輯，觀者於作品之間往返，在理解與疑問間重新審視情感與存在，尋找共鳴與棲身之處。', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-03-14 00:00:00', '2025-03-30 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='舊夢新材-林彥甫創作個展', `description`='「舊夢新材」為藝術家林彥甫賦予作品平凡材質與物件新角色與說法，展開「近似語言」的詩意對話。透過低頻幽默與躁動，引導探索內在邏輯，觀者於作品之間往返，在理解與疑問間重新審視情感與存在，尋找共鳴與棲身之處。', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65026b32418d001b890', '《這個片刻，我們在記憶中凝視》 ', '記憶是時間與空間的凝鍊，藉由人無盡的情感中交織，形成當下的永恆。 來自不同音樂文化脈絡下的演奏者黃立騰與劉航，以琵琶、大提琴、電子音樂的組合形式，攜手多位海內外作編曲家，以臺北生活的風貌為題，勾勒出臺北內斂及外顯的多元文化樣貌及獨特性。', '臺北市立國樂團', '臺北市中正區延平南路98號', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '臺北市中山堂', 25.03240487, 121.5198839, '/+500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《這個片刻，我們在記憶中凝視》 ', `description`='記憶是時間與空間的凝鍊，藉由人無盡的情感中交織，形成當下的永恆。 來自不同音樂文化脈絡下的演奏者黃立騰與劉航，以琵琶、大提琴、電子音樂的組合形式，攜手多位海內外作編曲家，以臺北生活的風貌為題，勾勒出臺北內斂及外顯的多元文化樣貌及獨特性。', `organizer`='臺北市立國樂團', `address`='臺北市中正區延平南路98號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='臺北市中山堂', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='/+500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65126b32418d001b892', '情─劉孟捷 & TCO', '歷經苦難，更顯純粹。來自臺灣，享譽國際的鋼琴名家劉孟捷精湛技巧和深厚的音樂素養，在國際舞臺大放異彩，就在事業日正當中之際遭逢病魔，但他以堅強意志力與巨大音樂信念支撐，一指一指練回來，重新站上世界樂壇。揚琴演奏家陳廷宇年紀雖輕，舞臺經驗卻是身經百戰。這場音樂會，劉孟捷將世界首演作曲家顏名秀為其量身創作的鋼琴協奏曲，陳廷宇則將挑戰張朝近年力作《盤古》揚琴協奏曲。名家名曲，盡在北市國。', '臺北市立國樂團', '臺北市中正區延平南路98號', '2025-05-09 00:00:00', '2025-05-09 00:00:00', '臺北市中山堂', 25.03240487, 121.5198839, '/+300;/+500;/+800;/+1000', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='情─劉孟捷 & TCO', `description`='歷經苦難，更顯純粹。來自臺灣，享譽國際的鋼琴名家劉孟捷精湛技巧和深厚的音樂素養，在國際舞臺大放異彩，就在事業日正當中之際遭逢病魔，但他以堅強意志力與巨大音樂信念支撐，一指一指練回來，重新站上世界樂壇。揚琴演奏家陳廷宇年紀雖輕，舞臺經驗卻是身經百戰。這場音樂會，劉孟捷將世界首演作曲家顏名秀為其量身創作的鋼琴協奏曲，陳廷宇則將挑戰張朝近年力作《盤古》揚琴協奏曲。名家名曲，盡在北市國。', `organizer`='臺北市立國樂團', `address`='臺北市中正區延平南路98號', `start_date`='2025-05-09 00:00:00', `end_date`='2025-05-09 00:00:00', `location`='臺北市中山堂', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='/+300;/+500;/+800;/+1000', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65226b32418d001b895', '「秋天來了」主題書展', '「秋天來了」主題書展\r\n於二樓設置專區放置相關主題書籍。定期更換推薦書籍，歡迎大家借閱。\r\n▪展演時間｜114年4月1日至4月30日／開館時間\r\n▪展演書單｜也是秋天、秋天的星空觀察、秋天鳴叫的昆蟲、北京秋天下午的我、岸上的秋天、開出金秋天、秋天裏的重逢、魔法的秋天、夏天的太陽懶散到秋天、秋風裡的低語 :這一代的歌、秋天的墾丁、小松鼠的秋天學校..等書籍', '高雄市立圖書館總館', '高雄市湖內區3鄰保生路101號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '高雄市立圖書館湖內分館', 22.8955499, 120.2225563, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「秋天來了」主題書展', `description`='「秋天來了」主題書展\r\n於二樓設置專區放置相關主題書籍。定期更換推薦書籍，歡迎大家借閱。\r\n▪展演時間｜114年4月1日至4月30日／開館時間\r\n▪展演書單｜也是秋天、秋天的星空觀察、秋天鳴叫的昆蟲、北京秋天下午的我、岸上的秋天、開出金秋天、秋天裏的重逢、魔法的秋天、夏天的太陽懶散到秋天、秋風裡的低語 :這一代的歌、秋天的墾丁、小松鼠的秋天學校..等書籍', `organizer`='高雄市立圖書館總館', `address`='高雄市湖內區3鄰保生路101號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市立圖書館湖內分館', `latitude`=22.8955499, `longitude`=120.2225563, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65226b32418d001b896', 'TCO劇院─臺灣歌劇《我的媽媽欠栽培》', '原創歌劇經典再現，最貼心的故鄉回憶，還全天下「欠栽培」 的媽媽一個溫暖的公道。《花甲男孩》作家楊富閔深情原著，北市國跨界製作臺灣歌劇《我的媽媽欠栽培》，用歌、用戲、用偶、用音樂，歌詠最悲喜交織的倫理親情，懷想最 哭笑不得的成長回憶。在城鄉差距與人倫關係的變動間，留下最深刻的文化風景，一同喚醒深藏在心底的陳年感動。\r\n\r\n展演者︰鄭立彬/中華民國、邱誓舷/中華民國 呂雪鳳、謝銘祐、湯發凱、劉毓真、林慈音、程伯仁、李增銘、蘇皇任、葉昇峻/中華民國 臺北市立國樂團/中華民國 無獨有偶工作室劇團/中華民國 TCO合唱團/中華民國\r\n\r\n', '臺北市立國樂團', '臺北市士林區劍潭路1號', '2025-05-23 00:00:00', '2025-05-25 00:00:00', '臺北表演藝術中心', 25.12546704, 121.5508473, '/+500;/+1000;/+1500;/+2000;/+2500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='TCO劇院─臺灣歌劇《我的媽媽欠栽培》', `description`='原創歌劇經典再現，最貼心的故鄉回憶，還全天下「欠栽培」 的媽媽一個溫暖的公道。《花甲男孩》作家楊富閔深情原著，北市國跨界製作臺灣歌劇《我的媽媽欠栽培》，用歌、用戲、用偶、用音樂，歌詠最悲喜交織的倫理親情，懷想最 哭笑不得的成長回憶。在城鄉差距與人倫關係的變動間，留下最深刻的文化風景，一同喚醒深藏在心底的陳年感動。\r\n\r\n展演者︰鄭立彬/中華民國、邱誓舷/中華民國 呂雪鳳、謝銘祐、湯發凱、劉毓真、林慈音、程伯仁、李增銘、蘇皇任、葉昇峻/中華民國 臺北市立國樂團/中華民國 無獨有偶工作室劇團/中華民國 TCO合唱團/中華民國\r\n\r\n', `organizer`='臺北市立國樂團', `address`='臺北市士林區劍潭路1號', `start_date`='2025-05-23 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='臺北表演藝術中心', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='/+500;/+1000;/+1500;/+2000;/+2500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65226b32418d001b899', '113年下學期育藝深遠', '《貝茲王國的逆襲》\r\n傳說中「貝茲國」是一個古老的聖地，聽得懂貝茲國語言的人就能得到貝茲國王的祝福，因此常常有苦惱的人類跑去貝茲國，希望能獲得國王的祝福、實現願望。\r\n皮皮、卡卡、球球是三個好朋友，皮皮和卡卡曾經幫助球球生病的外婆獲得祝福，和貝茲國的人民成為了好朋友，正當三人想再去貝茲國玩的時候，貝茲國王卻換人了！新的貝茲國王覺得人類很貪心，不想再幫人們實現願望，於是附身到卡卡身上，帶領貝茲國的人民們闖進人類的世界，想毀滅人類，就不會有人來吵他們。\r\n卡卡該如何阻止小龍王、拯救被困在貝茲國的好朋友、讓貝茲國與人類恢復友好、和樂的光景呢？', '臺北市政府文化局', '臺北市中正區延平南路98號', '2025-03-17 00:00:00', '2025-03-27 00:00:00', '臺北市中山堂', 25.03240487, 121.5198839, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='113年下學期育藝深遠', `description`='《貝茲王國的逆襲》\r\n傳說中「貝茲國」是一個古老的聖地，聽得懂貝茲國語言的人就能得到貝茲國王的祝福，因此常常有苦惱的人類跑去貝茲國，希望能獲得國王的祝福、實現願望。\r\n皮皮、卡卡、球球是三個好朋友，皮皮和卡卡曾經幫助球球生病的外婆獲得祝福，和貝茲國的人民成為了好朋友，正當三人想再去貝茲國玩的時候，貝茲國王卻換人了！新的貝茲國王覺得人類很貪心，不想再幫人們實現願望，於是附身到卡卡身上，帶領貝茲國的人民們闖進人類的世界，想毀滅人類，就不會有人來吵他們。\r\n卡卡該如何阻止小龍王、拯救被困在貝茲國的好朋友、讓貝茲國與人類恢復友好、和樂的光景呢？', `organizer`='臺北市政府文化局', `address`='臺北市中正區延平南路98號', `start_date`='2025-03-17 00:00:00', `end_date`='2025-03-27 00:00:00', `location`='臺北市中山堂', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
