INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65526b32418d001b89c', '陽明分館114年4月主題書展', '陽明分館114年4月主題書展\r\n當月主題如下：\r\n1.東南亞主題書展：越讀越愛~閱讀越南之旅\r\n展期：114/01/01~114/12/31\r\n展示：看故事學越南語、用中文說越南語、越南語一學就上手\r\n等優良圖書。\r\n', '高雄市立圖書館總館', '高雄市三民區陽明路300號3樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '高雄市立圖書館陽明分館', 22.643485, 120.34232, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陽明分館114年4月主題書展', `description`='陽明分館114年4月主題書展\r\n當月主題如下：\r\n1.東南亞主題書展：越讀越愛~閱讀越南之旅\r\n展期：114/01/01~114/12/31\r\n展示：看故事學越南語、用中文說越南語、越南語一學就上手\r\n等優良圖書。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區陽明路300號3樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市立圖書館陽明分館', `latitude`=22.643485, `longitude`=120.34232, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65726b32418d001b89d', '鏽染風景 — 陳穎亭個展', '陳穎亭\r\n當代纖維藝術家，畢業於國立臺南藝術大學應用藝術研究所纖維組。\r\n_\r\n面對創作的動機，源自於生活中不停流轉的時間，在這流轉的時間中像個旅行者。\r\n旅途中，紀行在不同時空裡的移動、收集與紀錄間，嘗試、探尋與反思的過程中，所引發的創作想法。並試圖從自我成長的生命經驗裡來提取創作的引子，藉著生活中收集而來的物件，並聚焦在纖維材質的思考上，回溯自己過往存在的記憶，與纖維對自己的原生情感。\r\n藉由一段段長時間手作的過程中，漸漸累積與形構一個自我的整體面貌，藉此探尋自我存在的位置，進而覺察我與外在環境之間的遭遇。\r\n\r\n#鏽染  #織品 #當代纖維藝術  #個展', '永茗藝術 Studio', '臺中市西區', '2025-02-06 00:00:00', '2025-03-30 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/L5Kp0e', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鏽染風景 — 陳穎亭個展', `description`='陳穎亭\r\n當代纖維藝術家，畢業於國立臺南藝術大學應用藝術研究所纖維組。\r\n_\r\n面對創作的動機，源自於生活中不停流轉的時間，在這流轉的時間中像個旅行者。\r\n旅途中，紀行在不同時空裡的移動、收集與紀錄間，嘗試、探尋與反思的過程中，所引發的創作想法。並試圖從自我成長的生命經驗裡來提取創作的引子，藉著生活中收集而來的物件，並聚焦在纖維材質的思考上，回溯自己過往存在的記憶，與纖維對自己的原生情感。\r\n藉由一段段長時間手作的過程中，漸漸累積與形構一個自我的整體面貌，藉此探尋自我存在的位置，進而覺察我與外在環境之間的遭遇。\r\n\r\n#鏽染  #織品 #當代纖維藝術  #個展', `organizer`='永茗藝術 Studio', `address`='臺中市西區', `start_date`='2025-02-06 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/L5Kp0e', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65726b32418d001b89e', '「藝遊春風」經典藝術創作聯展', '國璽藝術於2025年開春之際，特別規劃代理十一位藝術家經典創作聯展。\r\n「曹文瑞」架構超現實的真實與假象場域；\r\n「柯適中」天馬行空想像的塗鴉風景；\r\n「蔡英君」女孩與自然大地互動故事；\r\n「海 至」以光鹿形象療癒與溫暖人心；\r\n「林國瑋」形塑人與動物環境共存議題；\r\n「廖文彬」擬人化的布手套與自然環境共生；\r\n「陳彥伯」打造想像裝滿水的趣味世界；\r\n「高堉銓」透過記憶畫面轉化成奇幻的境界；\r\n「卓振宇」以米粒人角色探索那些山的所在；\r\n「雷凱勛」以太空人穿越時空回歸內心的寧靜；\r\n「詹哲名」以兔子打造形象傳達溫暖幸福感。\r\n藉由每位藝術家擅長的媒材、技法，共同呈現多元的視覺語彙面貌。\r\n誠摯地邀請藝術愛好者，共同欣賞這場優質的藝術盛會，歡迎蒞臨現場參觀精彩的展品！\r\n\r\n#油畫  #複合媒材  #壓克力  #雕塑  #聯展', '國璽藝術', '臺中市南屯區', '2025-02-22 00:00:00', '2025-04-30 00:00:00', '南屯區（臺中市）=', 24.14165524, 120.6177379, '無資料', 'https://artemperor.tw/tidbits/17818', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「藝遊春風」經典藝術創作聯展', `description`='國璽藝術於2025年開春之際，特別規劃代理十一位藝術家經典創作聯展。\r\n「曹文瑞」架構超現實的真實與假象場域；\r\n「柯適中」天馬行空想像的塗鴉風景；\r\n「蔡英君」女孩與自然大地互動故事；\r\n「海 至」以光鹿形象療癒與溫暖人心；\r\n「林國瑋」形塑人與動物環境共存議題；\r\n「廖文彬」擬人化的布手套與自然環境共生；\r\n「陳彥伯」打造想像裝滿水的趣味世界；\r\n「高堉銓」透過記憶畫面轉化成奇幻的境界；\r\n「卓振宇」以米粒人角色探索那些山的所在；\r\n「雷凱勛」以太空人穿越時空回歸內心的寧靜；\r\n「詹哲名」以兔子打造形象傳達溫暖幸福感。\r\n藉由每位藝術家擅長的媒材、技法，共同呈現多元的視覺語彙面貌。\r\n誠摯地邀請藝術愛好者，共同欣賞這場優質的藝術盛會，歡迎蒞臨現場參觀精彩的展品！\r\n\r\n#油畫  #複合媒材  #壓克力  #雕塑  #聯展', `organizer`='國璽藝術', `address`='臺中市南屯區', `start_date`='2025-02-22 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://artemperor.tw/tidbits/17818', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65726b32418d001b89f', ' 通往花園的路徑│李佳玲個展', '《Pathways to a Garden 》以織品藝術為媒介，邀請觀眾走進一場文化與時間的旅程。歷經2024年個展《Traces of Softness柔軟痕跡》的探索，以及米蘭、巴黎、東京、台北及首爾的國際巡展後，織品藝術家李佳玲持續以古代生活器物為創作基礎，帶來軟花瓶《Soft Vase》與新作，融合東西方文化交融的視角,透過細緻的絎縫與刺繡工藝，勾勒出一個想像中的花園路徑。\r\n\r\n#織品藝術  #雕塑  #個展', 'ZASSO 草也', '臺中市西區', '2025-02-08 00:00:00', '2025-03-02 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/Q5Kj09', '[]') ON DUPLICATE KEY UPDATE `activity_name`=' 通往花園的路徑│李佳玲個展', `description`='《Pathways to a Garden 》以織品藝術為媒介，邀請觀眾走進一場文化與時間的旅程。歷經2024年個展《Traces of Softness柔軟痕跡》的探索，以及米蘭、巴黎、東京、台北及首爾的國際巡展後，織品藝術家李佳玲持續以古代生活器物為創作基礎，帶來軟花瓶《Soft Vase》與新作，融合東西方文化交融的視角,透過細緻的絎縫與刺繡工藝，勾勒出一個想像中的花園路徑。\r\n\r\n#織品藝術  #雕塑  #個展', `organizer`='ZASSO 草也', `address`='臺中市西區', `start_date`='2025-02-08 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/Q5Kj09', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65726b32418d001b8a0', '反覆安靜地練習│謝福源個展', '在《反覆安靜地練習》這檔展覽中,是我在近期對於自己生活中的回應,藝術創作對我來說是一個反覆探索的旅程,透過放慢自身生活的步調,更深刻的感受當下的存在。\r\n在這島嶼上,濕氣彷彿在空氣中流動,植物和花卉以不同的姿態綻放生機,這是四季變化中最具詩意的時刻,而我希望透過我的作品來捕捉這些瞬間。季節的輪替教會了我珍惜每個當下,從春天的盛放、夏天的綠意,再到秋冬的孤寂,我嘗試在季節的轉變中,找尋那些被我們忽略的微小變化,擷取當下所發現的小物件進行描寫。每一層顏料的堆疊,都像是對時間流逝的凝練與回顧,這些顏料不僅是色彩的表現,更是對環境和心情的詮釋,呈現出那潮濕的空氣和自然的韻律。\r\n\r\n#壓克力  #個展', '雨果曐Gallery', '臺中市西區', '2025-02-08 00:00:00', '2025-03-16 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/6jnZQM', '[]') ON DUPLICATE KEY UPDATE `activity_name`='反覆安靜地練習│謝福源個展', `description`='在《反覆安靜地練習》這檔展覽中,是我在近期對於自己生活中的回應,藝術創作對我來說是一個反覆探索的旅程,透過放慢自身生活的步調,更深刻的感受當下的存在。\r\n在這島嶼上,濕氣彷彿在空氣中流動,植物和花卉以不同的姿態綻放生機,這是四季變化中最具詩意的時刻,而我希望透過我的作品來捕捉這些瞬間。季節的輪替教會了我珍惜每個當下,從春天的盛放、夏天的綠意,再到秋冬的孤寂,我嘗試在季節的轉變中,找尋那些被我們忽略的微小變化,擷取當下所發現的小物件進行描寫。每一層顏料的堆疊,都像是對時間流逝的凝練與回顧,這些顏料不僅是色彩的表現,更是對環境和心情的詮釋,呈現出那潮濕的空氣和自然的韻律。\r\n\r\n#壓克力  #個展', `organizer`='雨果曐Gallery', `address`='臺中市西區', `start_date`='2025-02-08 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/6jnZQM', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65726b32418d001b8a1', '師藝之路：傳承與開新', '「師藝之路：傳承與開新」我們邀請到四位書畫界的七年級代表，柯良志老師、紀冠地老師、陳俋佐老師和江柏萱老師擔任本學期的開展先鋒啦，並同時邀請現正在國立彰化生活美學館舉行個展的於同生老師擔任策展人。\r\n關於這次的展覽內容，下方引用於同生老師為此次展覽所撰寫的策展導覽：\r\n「這次展覽，我們邀請四位七年級的代表性書法家，紀冠地、柯良志、陳俋佐、江柏萱共同展出。這四位都是學院派出身，自幼習書，各自作品特色鮮明且獨樹一格，且目前皆於大學任教。它們幾乎具有類似的學習背景，卻開展出各自的特殊風格，這值得我們深入討論與思考。藉由這樣的聯展，我們希望梳理四位書法家如何在傳統技法的基礎上，進行創新與探索，展現出不同的風格與個性，並且向我們展示了書法在傳承中的不斷創新，使文化記憶與當代視角進行深度對話。不論對於書法創作抑或是書法教育的新模式，皆具有其指標性的代表意義。」\r\n從於同生老師的策展導覽就知道，這次的展覽希望能讓觀眾看見青壯世代的書法家，在扎實的傳統基礎上，展現屬於他們世代的創新特色與其對於書畫藝術的探索，並再從自身出發，企圖與傳統和歷史重新開啟對話。\r\n「師藝之路：傳承與開新」展覽資訊\r\n時間：2025年2月22日(星期六)至4月13日(星期日) 10:00至17:00\r\n地點：逢甲大學 游翰堂 漢字文化中心（圖書館一樓）\r\n開幕式暨創作論壇：2025年3月2日 10:00至12:00\r\n\r\n#書法   #聯展', '逢甲大學游翰堂漢字文化中心', '臺中市西屯區文華路100號', '2025-02-22 00:00:00', '2025-04-13 00:00:00', '逢甲大學', 24.18308895, 120.6270131, '無資料', 'https://reurl.cc/eGK31W', '[]') ON DUPLICATE KEY UPDATE `activity_name`='師藝之路：傳承與開新', `description`='「師藝之路：傳承與開新」我們邀請到四位書畫界的七年級代表，柯良志老師、紀冠地老師、陳俋佐老師和江柏萱老師擔任本學期的開展先鋒啦，並同時邀請現正在國立彰化生活美學館舉行個展的於同生老師擔任策展人。\r\n關於這次的展覽內容，下方引用於同生老師為此次展覽所撰寫的策展導覽：\r\n「這次展覽，我們邀請四位七年級的代表性書法家，紀冠地、柯良志、陳俋佐、江柏萱共同展出。這四位都是學院派出身，自幼習書，各自作品特色鮮明且獨樹一格，且目前皆於大學任教。它們幾乎具有類似的學習背景，卻開展出各自的特殊風格，這值得我們深入討論與思考。藉由這樣的聯展，我們希望梳理四位書法家如何在傳統技法的基礎上，進行創新與探索，展現出不同的風格與個性，並且向我們展示了書法在傳承中的不斷創新，使文化記憶與當代視角進行深度對話。不論對於書法創作抑或是書法教育的新模式，皆具有其指標性的代表意義。」\r\n從於同生老師的策展導覽就知道，這次的展覽希望能讓觀眾看見青壯世代的書法家，在扎實的傳統基礎上，展現屬於他們世代的創新特色與其對於書畫藝術的探索，並再從自身出發，企圖與傳統和歷史重新開啟對話。\r\n「師藝之路：傳承與開新」展覽資訊\r\n時間：2025年2月22日(星期六)至4月13日(星期日) 10:00至17:00\r\n地點：逢甲大學 游翰堂 漢字文化中心（圖書館一樓）\r\n開幕式暨創作論壇：2025年3月2日 10:00至12:00\r\n\r\n#書法   #聯展', `organizer`='逢甲大學游翰堂漢字文化中心', `address`='臺中市西屯區文華路100號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='逢甲大學', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://reurl.cc/eGK31W', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65726b32418d001b8a2', '反覆徘徊之後 After Repeated Wandering', '反覆徘徊之後 After Repeated Wandering\r\n沈易頡 YiJie Shen\r\n「要畫什麼？」這個問題如同夢魘，在每一次落筆前響起。\r\n繪畫的學習始於模仿現實，寫實與抽象的選擇總帶來遲疑，面對繪畫形式的焦慮與質疑，則如無形的制約，長期作用於創作之中。藝術家面對這種困境的回應並非做出選擇，而是在形式與描繪對象之間不斷試探與徘徊。在過程中，發現畫面本身也乘載與再現著這種不確定性：直覺與控制交錯，顏料的流動、畫面的切割、粉彩的批改——每一道痕跡都是對這份困境的再現。隨著試探的深入，藝術家意識到，再現並非束縛，而是對最初疑問的回應。不同的視覺語言，不斷回應同一個問題，使困境在畫面中層層顯現。\r\n從最初原以為的消極承受 ，到逐漸轉變為主動參與，這種游移的過程本身，也成為創作的驅動力。直覺不再只是抗衡焦慮的手段，而成為主宰畫面的手段之一，也構成了對於既有繪畫訓練的反叛。也了解到，再現的意義不僅是對影像的還原，更是對無以名狀的心理狀態的顯現——那些無法確切言說的狀態，在筆跡之間得以顯形。\r\n在長期的實驗與拉扯之間，形式的邊界開始變得模糊，控制與偶然交織並存。不再急於某種確定性，而是維持未決的張力。過去的執著或許仍存，但在反覆徘徊之後，鬆動的裂隙開始帶來更大的可能性。\r\n\r\n#油畫  #裝置  #個展', '窯座', '臺中市西區', '2025-03-08 00:00:00', '2025-03-30 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/96mpvj', '[]') ON DUPLICATE KEY UPDATE `activity_name`='反覆徘徊之後 After Repeated Wandering', `description`='反覆徘徊之後 After Repeated Wandering\r\n沈易頡 YiJie Shen\r\n「要畫什麼？」這個問題如同夢魘，在每一次落筆前響起。\r\n繪畫的學習始於模仿現實，寫實與抽象的選擇總帶來遲疑，面對繪畫形式的焦慮與質疑，則如無形的制約，長期作用於創作之中。藝術家面對這種困境的回應並非做出選擇，而是在形式與描繪對象之間不斷試探與徘徊。在過程中，發現畫面本身也乘載與再現著這種不確定性：直覺與控制交錯，顏料的流動、畫面的切割、粉彩的批改——每一道痕跡都是對這份困境的再現。隨著試探的深入，藝術家意識到，再現並非束縛，而是對最初疑問的回應。不同的視覺語言，不斷回應同一個問題，使困境在畫面中層層顯現。\r\n從最初原以為的消極承受 ，到逐漸轉變為主動參與，這種游移的過程本身，也成為創作的驅動力。直覺不再只是抗衡焦慮的手段，而成為主宰畫面的手段之一，也構成了對於既有繪畫訓練的反叛。也了解到，再現的意義不僅是對影像的還原，更是對無以名狀的心理狀態的顯現——那些無法確切言說的狀態，在筆跡之間得以顯形。\r\n在長期的實驗與拉扯之間，形式的邊界開始變得模糊，控制與偶然交織並存。不再急於某種確定性，而是維持未決的張力。過去的執著或許仍存，但在反覆徘徊之後，鬆動的裂隙開始帶來更大的可能性。\r\n\r\n#油畫  #裝置  #個展', `organizer`='窯座', `address`='臺中市西區', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/96mpvj', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65726b32418d001b8a3', '臺中市藝術亮點-千年一瞬 心旅永恆特展', '「在最美的時刻遇見最好的自己」\r\n透過油畫作品，述說著旅行時的點點滴滴，鐫刻著一步步踏出去的足跡，也紀錄著美好景色眼中的風情。\r\n展覽展出精采畫作，邀請大家一同感受畫中美好的記憶與繽紛的色彩！\r\n', '全安堂太陽餅博物館', '臺中市中區台灣大道一段145號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '全安堂臺灣太陽餅博物館', 24.14168566, 120.680598, '無資料', 'https://www.artspots-taichung.com.tw/tw/news-detail/322?kind=11&root=8&page=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-千年一瞬 心旅永恆特展', `description`='「在最美的時刻遇見最好的自己」\r\n透過油畫作品，述說著旅行時的點點滴滴，鐫刻著一步步踏出去的足跡，也紀錄著美好景色眼中的風情。\r\n展覽展出精采畫作，邀請大家一同感受畫中美好的記憶與繽紛的色彩！\r\n', `organizer`='全安堂太陽餅博物館', `address`='臺中市中區台灣大道一段145號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='全安堂臺灣太陽餅博物館', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='https://www.artspots-taichung.com.tw/tw/news-detail/322?kind=11&root=8&page=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65826b32418d001b8a4', '大樹下聽故事3月份', '花園裡的香草魔法 \r\n\r\n春天來了，微風輕拂，花園裡的香草輕輕搖曳，彷彿向小朋友揮手，邀請大家一起來 「大樹聽故事」！\r\n\r\n我們將透過演奏《奶奶的香草課》、《春天真的來了》、《奇妙的花園》等經典繪本，帶領孩子們走進香草的療癒世界，感受春天的氣息。\r\n\r\n綠生活療癒時間 \r\n香草不只是大自然的禮物，更能透過氣味安撫心靈，帶來滿滿的幸福感。', '桃園市立大溪木藝生態博物館', '桃園市大溪區普濟路13巷2號', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '桃園市立大溪木藝生態博物館-親子空間', 24.86797026, 121.296342, '費用/人+300', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大樹下聽故事3月份', `description`='花園裡的香草魔法 \r\n\r\n春天來了，微風輕拂，花園裡的香草輕輕搖曳，彷彿向小朋友揮手，邀請大家一起來 「大樹聽故事」！\r\n\r\n我們將透過演奏《奶奶的香草課》、《春天真的來了》、《奇妙的花園》等經典繪本，帶領孩子們走進香草的療癒世界，感受春天的氣息。\r\n\r\n綠生活療癒時間 \r\n香草不只是大自然的禮物，更能透過氣味安撫心靈，帶來滿滿的幸福感。', `organizer`='桃園市立大溪木藝生態博物館', `address`='桃園市大溪區普濟路13巷2號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='桃園市立大溪木藝生態博物館-親子空間', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='費用/人+300', `source_url`='無資料', `image_url`='[]';
