INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65926b32418d001b8b4', '東南亞故事時間-「亞熱帶故事家」-印尼說故事', '大家了解過印尼的文化與傳統故事嗎？\r\n這次的說故事活動，我們邀請到來自印尼的楊美香老師，為大家帶來印尼的經典傳說《海盜鱷魚》。故事中將帶領孩子們體驗印尼的奇幻故事與豐富文化，故事結束後，老師將帶領大家一起進行手作活動，親子共同製作不織布鱷魚，讓孩子們能在動手做的過程中更加深入了解印尼的獨特文化與創意。活動採自由入場，無需報名，期待與您在圖書館一起分享這場精彩的故事與手作之旅！\r\n', '高雄市立圖書館總館', '高雄市前鎮區21鄰新光路61號', '2025-04-13 00:00:00', '2025-04-13 00:00:00', '高雄市立圖書館總館', 22.6115529, 120.3024491, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='東南亞故事時間-「亞熱帶故事家」-印尼說故事', `description`='大家了解過印尼的文化與傳統故事嗎？\r\n這次的說故事活動，我們邀請到來自印尼的楊美香老師，為大家帶來印尼的經典傳說《海盜鱷魚》。故事中將帶領孩子們體驗印尼的奇幻故事與豐富文化，故事結束後，老師將帶領大家一起進行手作活動，親子共同製作不織布鱷魚，讓孩子們能在動手做的過程中更加深入了解印尼的獨特文化與創意。活動採自由入場，無需報名，期待與您在圖書館一起分享這場精彩的故事與手作之旅！\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市前鎮區21鄰新光路61號', `start_date`='2025-04-13 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='高雄市立圖書館總館', `latitude`=22.6115529, `longitude`=120.3024491, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
