INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65926b32418d001b8ba', '114年第一期小蜻蜓兒童讀書會', '圖書館一直是扮演「推廣閱讀」重要推手，「小蜻蜓兒童讀書會」更是重點活動之一，本活動由老師帶領小朋友透過繪本閱讀、影片欣賞、主題分享及課後討論方式進行，而藉此活動不但鼓勵小朋友多看書、瞭解閱讀好處外，並能增進閱讀能力及開闊知識視野，更讓「閱讀」成為生活習慣，創造閱讀書香新氛圍。\r\n閱讀書籍:當你想打人的時候、晶晶的桃花源記、唱家己的歌......等。\r\n', '高雄市立圖書館總館', '高雄市楠梓區', '2025-03-11 00:00:00', '2025-05-06 00:00:00', '楠梓區（高雄市）=', 22.72109961, 120.300758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年第一期小蜻蜓兒童讀書會', `description`='圖書館一直是扮演「推廣閱讀」重要推手，「小蜻蜓兒童讀書會」更是重點活動之一，本活動由老師帶領小朋友透過繪本閱讀、影片欣賞、主題分享及課後討論方式進行，而藉此活動不但鼓勵小朋友多看書、瞭解閱讀好處外，並能增進閱讀能力及開闊知識視野，更讓「閱讀」成為生活習慣，創造閱讀書香新氛圍。\r\n閱讀書籍:當你想打人的時候、晶晶的桃花源記、唱家己的歌......等。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市楠梓區', `start_date`='2025-03-11 00:00:00', `end_date`='2025-05-06 00:00:00', `location`='楠梓區（高雄市）=', `latitude`=22.72109961, `longitude`=120.300758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65a26b32418d001b8bb', '百的篇章-洪明露創作個展', '「百的篇章」為藝術家洪明露以解構與簡化的形式，探討生命的百種樣態。作品透過油彩、鉛筆於木板上創作，呈現井然有序的圖像反覆排列，卻於細微處流露著變化之美。這些圖像猶如日常中的細碎分子，靜待觀者注視與發現。', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-03-14 00:00:00', '2025-03-30 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='百的篇章-洪明露創作個展', `description`='「百的篇章」為藝術家洪明露以解構與簡化的形式，探討生命的百種樣態。作品透過油彩、鉛筆於木板上創作，呈現井然有序的圖像反覆排列，卻於細微處流露著變化之美。這些圖像猶如日常中的細碎分子，靜待觀者注視與發現。', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65c26b32418d001b8bc', '藍晶翠燦迎春年陶藝創作展', '本次聯展由賴秀蓁、蔣駿騰、陳正文、張建鈞、林阿滿、賴宜琳等6位藝術家共同展出陶藝創作。展出以排灣族傳統陶壺為創作主軸，排灣族陶壺承載部落文化，獨特的手工技藝與精緻紋飾見證了族群歷史。藝術家們在傳統基礎上融入時尚元素，為古老圖騰注入新生命，展現豐富的陶藝文化風貌。', '臺中市政府文化局', '臺中市西屯區臺灣大道三段99號', '2025-01-15 00:00:00', '2025-04-23 00:00:00', '臺中市政府新市政大樓', 24.173738, 120.637283, '無資料', 'https://www.culture.taichung.gov.tw/2878247/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藍晶翠燦迎春年陶藝創作展', `description`='本次聯展由賴秀蓁、蔣駿騰、陳正文、張建鈞、林阿滿、賴宜琳等6位藝術家共同展出陶藝創作。展出以排灣族傳統陶壺為創作主軸，排灣族陶壺承載部落文化，獨特的手工技藝與精緻紋飾見證了族群歷史。藝術家們在傳統基礎上融入時尚元素，為古老圖騰注入新生命，展現豐富的陶藝文化風貌。', `organizer`='臺中市政府文化局', `address`='臺中市西屯區臺灣大道三段99號', `start_date`='2025-01-15 00:00:00', `end_date`='2025-04-23 00:00:00', `location`='臺中市政府新市政大樓', `latitude`=24.173738, `longitude`=120.637283, `ticket_price`='無資料', `source_url`='https://www.culture.taichung.gov.tw/2878247/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65c26b32418d001b8bd', '三老書法作品展', '書法是中華民族傳承數千年的藝術，一旦進入學習都給人欲罷不能的吸引力，本次聯展由吳義馴、陳耀東、康文鳳3位共同展出，作品皆展現致力揮灑創作的成果，3人曾於臺中都會公園辦理展覽，此次在市府藝術廊道展出，期待觀眾看見書法藝術之美。', '臺中市政府文化局', '臺中市西屯區臺灣大道三段99號', '2025-01-22 00:00:00', '2025-03-26 00:00:00', '臺中市政府新市政大樓', 24.173738, 120.637283, '無資料', 'https://www.culture.taichung.gov.tw/2878275/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三老書法作品展', `description`='書法是中華民族傳承數千年的藝術，一旦進入學習都給人欲罷不能的吸引力，本次聯展由吳義馴、陳耀東、康文鳳3位共同展出，作品皆展現致力揮灑創作的成果，3人曾於臺中都會公園辦理展覽，此次在市府藝術廊道展出，期待觀眾看見書法藝術之美。', `organizer`='臺中市政府文化局', `address`='臺中市西屯區臺灣大道三段99號', `start_date`='2025-01-22 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺中市政府新市政大樓', `latitude`=24.173738, `longitude`=120.637283, `ticket_price`='無資料', `source_url`='https://www.culture.taichung.gov.tw/2878275/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65c26b32418d001b8be', '記憶拼裝交流所', '本次展覽整合了藝術家蔡佩儒從日常生活中蒐集並轉化的創作，以影像與空間為基礎，拆解為創作的基本元素與符號，再透過陶藝技術進行呈現，探討生活情境的記錄與實踐。同時，展覽深入探索現代與過去生活空間中的內容與議題轉換的可能性。除了展現個人生活記憶的探索，亦嘗試結合民眾的個人記憶，以多元形式共同探討當代藝術脈絡中的陶藝實踐。', '臺中市政府文化局', '臺中市西屯區臺灣大道三段99號', '2025-02-12 00:00:00', '2025-05-14 00:00:00', '臺中市政府新市政大樓', 24.173738, 120.637283, '無資料', 'https://www.culture.taichung.gov.tw/2907474/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='記憶拼裝交流所', `description`='本次展覽整合了藝術家蔡佩儒從日常生活中蒐集並轉化的創作，以影像與空間為基礎，拆解為創作的基本元素與符號，再透過陶藝技術進行呈現，探討生活情境的記錄與實踐。同時，展覽深入探索現代與過去生活空間中的內容與議題轉換的可能性。除了展現個人生活記憶的探索，亦嘗試結合民眾的個人記憶，以多元形式共同探討當代藝術脈絡中的陶藝實踐。', `organizer`='臺中市政府文化局', `address`='臺中市西屯區臺灣大道三段99號', `start_date`='2025-02-12 00:00:00', `end_date`='2025-05-14 00:00:00', `location`='臺中市政府新市政大樓', `latitude`=24.173738, `longitude`=120.637283, `ticket_price`='無資料', `source_url`='https://www.culture.taichung.gov.tw/2907474/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65c26b32418d001b8bf', '山•海•羽•空｜柯蕙蘭粉彩創作展', '本次個展以「山•海•羽•空」為主題，透過粉彩獨特的層疊流轉色彩，邀請觀者走進內心深處，展開一場自我觀照的靜心之旅。\r\n展覽作品包括《山在•我不在》、《光之流淌》、《羽光同在》及《尋光》等等，帶領觀者體驗藝術與心靈的深度連結。', '臺中市政府文化局', '臺中市西屯區臺灣大道三段99號', '2025-03-12 00:00:00', '2025-05-14 00:00:00', '臺中市政府新市政大樓', 24.173738, 120.637283, '無資料', 'https://www.culture.taichung.gov.tw/2907498/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='山•海•羽•空｜柯蕙蘭粉彩創作展', `description`='本次個展以「山•海•羽•空」為主題，透過粉彩獨特的層疊流轉色彩，邀請觀者走進內心深處，展開一場自我觀照的靜心之旅。\r\n展覽作品包括《山在•我不在》、《光之流淌》、《羽光同在》及《尋光》等等，帶領觀者體驗藝術與心靈的深度連結。', `organizer`='臺中市政府文化局', `address`='臺中市西屯區臺灣大道三段99號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-05-14 00:00:00', `location`='臺中市政府新市政大樓', `latitude`=24.173738, `longitude`=120.637283, `ticket_price`='無資料', `source_url`='https://www.culture.taichung.gov.tw/2907498/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65c26b32418d001b8c0', '「迎伯公·有保庇」客家文化音樂饗宴', '藉由歡慶伯公生日，辦理客家歌舞表演、客家諺語宣導等，並發放愛心物資。', '桃園市慈馨公益關懷協會', '桃園市楊梅區', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '楊梅區（桃園市）=', 24.91820989, 121.1291697, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「迎伯公·有保庇」客家文化音樂饗宴', `description`='藉由歡慶伯公生日，辦理客家歌舞表演、客家諺語宣導等，並發放愛心物資。', `organizer`='桃園市慈馨公益關懷協會', `address`='桃園市楊梅區', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='楊梅區（桃園市）=', `latitude`=24.91820989, `longitude`=121.1291697, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65d26b32418d001b8c1', '「他處的圖像」陳建榮個展', '陳建榮經常以壓克力顏料和綜合媒材在畫布上創作，透過幾何色塊的堆疊、模糊的色彩邊界，以及不合常理的景觀與結構拼接，構築出人工景觀，呈現理性與感性交織的獨特風格。\r\n\r\n#壓克力  #綜合媒材  #個展', '月臨畫廊', '臺中市西區台中市西區英才路589巷6號1樓', '2025-03-08 00:00:00', '2025-04-12 00:00:00', '月臨畫廊(一館)', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/Eg9pvn', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「他處的圖像」陳建榮個展', `description`='陳建榮經常以壓克力顏料和綜合媒材在畫布上創作，透過幾何色塊的堆疊、模糊的色彩邊界，以及不合常理的景觀與結構拼接，構築出人工景觀，呈現理性與感性交織的獨特風格。\r\n\r\n#壓克力  #綜合媒材  #個展', `organizer`='月臨畫廊', `address`='臺中市西區台中市西區英才路589巷6號1樓', `start_date`='2025-03-08 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='月臨畫廊(一館)', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/Eg9pvn', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65d26b32418d001b8c2', '2025年2月24日【IPAD珠寶繪圖】平日班', 'Procreate是近年最廣泛使用的珠寶2D電繪創作應用程式，舉凡各大國際珠寶設計競賽都能看到其優異表現。齊全的繪圖功能、豐富的筆刷效果、簡潔的介面與先進的圖層系統，讓零基礎的你也能在很短的時間繪製專業的珠寶設計圖。\r\n臺灣珠寶藝術學院專任珠寶設計講師-李曉晴，同時也是國際珠寶設計競賽常勝軍，利用系統化思維籌備教案，幫助你運用「觀念、邏輯、方法」，掌握Procreate繪製珠寶首飾的表現技巧。\r\n【您將擁有】\r\n	一套精選的貴金屬、寶石調色板（檔案）。\r\n	一組便利的筆刷工具，包含珠寶線條繪製筆刷、特殊效果筆刷、金屬效果筆刷、寶石刻面筆刷（檔案）。\r\n	熟悉Procreate實務操作技巧，表現出如職業水準之設計圖。\r\n	認識各式寶石，掌握其最佳呈現效果。\r\n	步驟化表現圖解，做為複習自修的資源。\r\n	無限次數「免費重讀」的機會（詳見注意事項）。\r\n【教學大綱】\r\n1.	Procreate應用程式介面及功能介紹。\r\n2.	光影/圖層概念表現：明亮式寶石(標準版/簡易版) 。\r\n3.	光影/圖層概念表現：切磨寶石(透明/不透明) 。\r\n4.	光影/圖層概念表現：雕件寶石(透明/不透明) 。\r\n5.	光影/圖層概念表現：自然形式寶石(珍珠/珊瑚) 。\r\n6.	特殊筆刷表現：蛋白石、孔雀石、瑪瑙、星石、水晶、月光石、土耳其石、青金石。\r\n7.	光影/圖層/色調概念表現：金屬(白/黃/紅) 。\r\n8.	光影/圖層/色調概念表現：金屬(造形/質感) 。\r\n9.	光影/圖層/色調概念表現：金屬密釘鑲。\r\n10.	光影/圖層/色調概念表現：副石組配、主副石組配。\r\n11.	光影/圖層/色調概念表現：綜合表現。\r\n12.	透視原理/戒指表現。\r\n13.	三視圖概念表現。\r\n14.	繪圖過程影片功能設定。\r\n15.	特殊筆刷表現：珍珠串、鑽石串。\r\n16.	基礎寶石學識/鑲嵌工藝。\r\n17.	珠寶金屬配件表現：扣頭、耳勾、鍊子。\r\n18.	其他優質素材表現：琺瑯、點翠、鈦金屬。\r\n【上課時間】\r\n《平日班》2025年2月24日至3月7日，每週一至五9:30-17:00（午休時間12:00-13:30），共10堂。\r\n【課程費用】\r\n學費為新台幣20,500元整。\r\n【教室地址】\r\n台北市中山區松江路5號之1→Google map\r\n【自備工具】\r\n	學員需自行攜帶Ipad、Apple Pencil、充電器，需使用支援Apple Pencil的iPad機型。\r\n（參閱：https://support.apple.com/zh-tw/HT211029）\r\n	請於Apple Store自行購買安裝Procreate應用程式（新台幣330元）\r\n【報名方式】\r\n線上報名：goo.gl/UXWwds\r\n請完成線上報名表提交，並完成訂金新台幣2,000元（或全額）之繳付，即完成受理報名程序，未完成訂金繳付恕無法保留學籍資格或名額。\r\n【加Line聯繫】請搜尋ID『@jart』或連結 https://line.me/R/ti/p/%40jart。\r\n課程詳細內容請連結: https://www.jart.org.tw/products/ipad', '臺灣珠寶藝術學院', '臺北市中山區', '2025-02-24 00:00:00', '2025-03-07 00:00:00', '中山區（臺北市）=', 25.06969917, 121.5381597, '/+20500', 'https://jart.org.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年2月24日【IPAD珠寶繪圖】平日班', `description`='Procreate是近年最廣泛使用的珠寶2D電繪創作應用程式，舉凡各大國際珠寶設計競賽都能看到其優異表現。齊全的繪圖功能、豐富的筆刷效果、簡潔的介面與先進的圖層系統，讓零基礎的你也能在很短的時間繪製專業的珠寶設計圖。\r\n臺灣珠寶藝術學院專任珠寶設計講師-李曉晴，同時也是國際珠寶設計競賽常勝軍，利用系統化思維籌備教案，幫助你運用「觀念、邏輯、方法」，掌握Procreate繪製珠寶首飾的表現技巧。\r\n【您將擁有】\r\n	一套精選的貴金屬、寶石調色板（檔案）。\r\n	一組便利的筆刷工具，包含珠寶線條繪製筆刷、特殊效果筆刷、金屬效果筆刷、寶石刻面筆刷（檔案）。\r\n	熟悉Procreate實務操作技巧，表現出如職業水準之設計圖。\r\n	認識各式寶石，掌握其最佳呈現效果。\r\n	步驟化表現圖解，做為複習自修的資源。\r\n	無限次數「免費重讀」的機會（詳見注意事項）。\r\n【教學大綱】\r\n1.	Procreate應用程式介面及功能介紹。\r\n2.	光影/圖層概念表現：明亮式寶石(標準版/簡易版) 。\r\n3.	光影/圖層概念表現：切磨寶石(透明/不透明) 。\r\n4.	光影/圖層概念表現：雕件寶石(透明/不透明) 。\r\n5.	光影/圖層概念表現：自然形式寶石(珍珠/珊瑚) 。\r\n6.	特殊筆刷表現：蛋白石、孔雀石、瑪瑙、星石、水晶、月光石、土耳其石、青金石。\r\n7.	光影/圖層/色調概念表現：金屬(白/黃/紅) 。\r\n8.	光影/圖層/色調概念表現：金屬(造形/質感) 。\r\n9.	光影/圖層/色調概念表現：金屬密釘鑲。\r\n10.	光影/圖層/色調概念表現：副石組配、主副石組配。\r\n11.	光影/圖層/色調概念表現：綜合表現。\r\n12.	透視原理/戒指表現。\r\n13.	三視圖概念表現。\r\n14.	繪圖過程影片功能設定。\r\n15.	特殊筆刷表現：珍珠串、鑽石串。\r\n16.	基礎寶石學識/鑲嵌工藝。\r\n17.	珠寶金屬配件表現：扣頭、耳勾、鍊子。\r\n18.	其他優質素材表現：琺瑯、點翠、鈦金屬。\r\n【上課時間】\r\n《平日班》2025年2月24日至3月7日，每週一至五9:30-17:00（午休時間12:00-13:30），共10堂。\r\n【課程費用】\r\n學費為新台幣20,500元整。\r\n【教室地址】\r\n台北市中山區松江路5號之1→Google map\r\n【自備工具】\r\n	學員需自行攜帶Ipad、Apple Pencil、充電器，需使用支援Apple Pencil的iPad機型。\r\n（參閱：https://support.apple.com/zh-tw/HT211029）\r\n	請於Apple Store自行購買安裝Procreate應用程式（新台幣330元）\r\n【報名方式】\r\n線上報名：goo.gl/UXWwds\r\n請完成線上報名表提交，並完成訂金新台幣2,000元（或全額）之繳付，即完成受理報名程序，未完成訂金繳付恕無法保留學籍資格或名額。\r\n【加Line聯繫】請搜尋ID『@jart』或連結 https://line.me/R/ti/p/%40jart。\r\n課程詳細內容請連結: https://www.jart.org.tw/products/ipad', `organizer`='臺灣珠寶藝術學院', `address`='臺北市中山區', `start_date`='2025-02-24 00:00:00', `end_date`='2025-03-07 00:00:00', `location`='中山區（臺北市）=', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='/+20500', `source_url`='https://jart.org.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65d26b32418d001b8c3', '2025年4月7日【珠寶設計入門】平日班', '設計，通常透過「繪製圖形」來產生作用，繪圖成為設計師的「語言」。\r\n有豐富的想法，如果沒有表現的方法，等於沒想法。\r\n所謂的珠寶設計，簡單來說就是將「寶石」與「貴金屬」加以安排成為裝飾物品，對材料進行的「安排過程」，即是設計。\r\n課程應用【珠寶設計型系統思考模式】引導您從事珠寶設計創作。\r\n創造，是不斷「欣賞」的過程。人的雙眼可輕易地觀察出比例或對稱是否美好，本能地察覺歪或粗等與醜有關的訊息。\r\n觀是看法。念是想法，建立看法和想法，才有作法。【珠寶設計入門】學習過程，讓您對珠寶業產生認知觀念。\r\n€教學內容\r\n‧創造是不斷欣賞的過程，以「設計原則」建立審美的觀念。\r\n‧課程以手繪為主，傳授線的表現技巧、設計素描、水彩技法。\r\n‧切割、切磨、雕刻、自然形式之寶石的水彩分解步驟繪製方法。\r\n‧立體戒檯形式3D手繪技法。\r\n‧配石應用技法，寶石組配成形法。\r\n€您將擁有\r\n‧您將擁有一套專屬的設計繪圖器具。\r\n‧您將接受基礎設計素描訓練，具備勾勒造形輪廓的能力。\r\n‧您將熟悉彩繪技巧實務操作，表現出如職業水準之設計圖。\r\n‧您將進一步認識各式寶石，掌握其物理特性。\r\n‧您將擁有課程講義圖稿，做為複習自修的資源。\r\n€課程期間\r\n【平日班】2025年4月7日至2025年4月25日止。每週一至五 9:30－16:30，午休1.5小時，共15堂。\r\n\r\n€教室地址\r\n台北市中山區松江路5號之1→Google map\r\n\r\n€課程費用\r\n學費為新台幣30,500元整，含一套個人專屬畫具及課程期間所需耗材。\r\n\r\n€報名方式\r\n請完成線上訂金繳付，即完成受理報名程序，\r\n未繳付訂金恕無法保留名額。\r\n【加Line聯繫】請搜尋ID『@jart』或連結 https://line.me/R/ti/p/%40jart。\r\n\r\n課程詳細內容請連結: https://www.jart.org.tw/products/ipad', '臺灣珠寶藝術學院', '臺北市中山區', '2025-04-07 00:00:00', '2025-04-25 00:00:00', '中山區（臺北市）=', 25.06969917, 121.5381597, '/+30500', 'https://jart.org.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年4月7日【珠寶設計入門】平日班', `description`='設計，通常透過「繪製圖形」來產生作用，繪圖成為設計師的「語言」。\r\n有豐富的想法，如果沒有表現的方法，等於沒想法。\r\n所謂的珠寶設計，簡單來說就是將「寶石」與「貴金屬」加以安排成為裝飾物品，對材料進行的「安排過程」，即是設計。\r\n課程應用【珠寶設計型系統思考模式】引導您從事珠寶設計創作。\r\n創造，是不斷「欣賞」的過程。人的雙眼可輕易地觀察出比例或對稱是否美好，本能地察覺歪或粗等與醜有關的訊息。\r\n觀是看法。念是想法，建立看法和想法，才有作法。【珠寶設計入門】學習過程，讓您對珠寶業產生認知觀念。\r\n€教學內容\r\n‧創造是不斷欣賞的過程，以「設計原則」建立審美的觀念。\r\n‧課程以手繪為主，傳授線的表現技巧、設計素描、水彩技法。\r\n‧切割、切磨、雕刻、自然形式之寶石的水彩分解步驟繪製方法。\r\n‧立體戒檯形式3D手繪技法。\r\n‧配石應用技法，寶石組配成形法。\r\n€您將擁有\r\n‧您將擁有一套專屬的設計繪圖器具。\r\n‧您將接受基礎設計素描訓練，具備勾勒造形輪廓的能力。\r\n‧您將熟悉彩繪技巧實務操作，表現出如職業水準之設計圖。\r\n‧您將進一步認識各式寶石，掌握其物理特性。\r\n‧您將擁有課程講義圖稿，做為複習自修的資源。\r\n€課程期間\r\n【平日班】2025年4月7日至2025年4月25日止。每週一至五 9:30－16:30，午休1.5小時，共15堂。\r\n\r\n€教室地址\r\n台北市中山區松江路5號之1→Google map\r\n\r\n€課程費用\r\n學費為新台幣30,500元整，含一套個人專屬畫具及課程期間所需耗材。\r\n\r\n€報名方式\r\n請完成線上訂金繳付，即完成受理報名程序，\r\n未繳付訂金恕無法保留名額。\r\n【加Line聯繫】請搜尋ID『@jart』或連結 https://line.me/R/ti/p/%40jart。\r\n\r\n課程詳細內容請連結: https://www.jart.org.tw/products/ipad', `organizer`='臺灣珠寶藝術學院', `address`='臺北市中山區', `start_date`='2025-04-07 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='中山區（臺北市）=', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='/+30500', `source_url`='https://jart.org.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65d26b32418d001b8c4', '2025年4月7日【珠寶設計師專業職能】', '你不該知道的珠寶業營運秘密，3個月讓你成為珠寶行內人。\r\n設計是一種「品味」和「品味」的交換，珠寶設計師不但要彰顯佩戴者的氣質，更要將自已的風格融入設計之中。\r\n設計師必須有「估價」的能力，懂得利用最少的「物力、財力、人力、時間」來獲取最大的經濟效果。\r\n因此，珠寶設計要學習的包括材料：貴金屬和寶石。工法：金屬工藝、首飾製程、鑲嵌工法等。\r\n繪畫，只是一種表現技法而已。\r\n臺灣並無珠寶原料礦藏，沒有產地優勢條件。珠寶業自然要強化「珠寶設計」和「製造工藝」的經營利基，珠寶設計師角色扮演關鍵。\r\n透過珠寶設計師的專業啟蒙，勝過十年的經歷摸索，快速掌握珠寶事業的成功要素，開啟您的珠寶人生。\r\n\r\n教學大綱\r\n一、熟悉珠寶產業概況\r\n二、學會珠寶專業知識\r\n三、訓練設計表現技巧\r\n四、應用珠寶設計系統\r\n五、珠寶設計實習演練\r\n六、結業延續輔助發展\r\n\r\n您將擁有\r\n‧您將擁有一套專屬的珠寶設計繪圖工具。\r\n‧您將擁有簡易鑑定工具，以及一組克拉尺寸樣本裸石。\r\n‧您將接受基礎設計素描訓練，具備勾勒造型輪廓的能力。\r\n‧您將熟悉彩繪技巧實務操作，表現出如職業水準之設計圖。\r\n‧您將擁有藝術美學的鑑賞能力，有能力將想法轉化成圖形。\r\n‧您將擁有完整的課程講義書面資料，供為複習自修之用。\r\n\r\n適用對象\r\n課程適用本國籍人民，參與者不須具備任何基礎，建議年齡20歲至40歲，對珠寶設計有興趣之金工師傅、珠寶業者、學習第二技能者，或有志從事珠寶事業之經營管理者參與，具美術設計學歷背景者尤佳。\r\n班級規模\r\n班級人數以18名為上限，採小班制教學，候補備取5名。\r\n班別時段\r\n●【第1梯次】2025年4月7日至6月27日。為期12週，時數總計390小時。 每週一至週五9:00–17:00，午休12:00–13:30。※期間遇國定假日不放假。\r\n●【第2梯次】2025年7月28日至10月17日。為期12週，時數總計390小時。 每週一至週五9:00–17:00，午休12:00–13:30。※期間遇國定假日不放假。\r\n班別費用\r\n學費為新臺幣153,500元整。\r\n	學費包含一套完整的課程講義，共有18個章節及其他教案。\r\n	學費包含一套專屬於個人的畫具，以及課程期間所需的耗材。\r\n教室地址\r\n台北市中山區松江路5之1號。(捷運忠孝新生站4號出口)\r\n結業文憑\r\n通過本院考核，授予「珠寶設計師專業職能研習」結業證書。\r\n報名方式─線上報名：goo.gl/UXWwds\r\n請完成線上報名表提交，並完成訂金10%（或全額學費）繳付，即完成受理報名程序，未完成訂金繳付恕無法保留學籍資格或名額。\r\n【加Line聯繫】請搜尋ID『@jart』或連結 https://line.me/R/ti/p/%40jart。\r\n課程詳細內容請連結: https://www.jart.org.tw/products/jeweller', '臺灣珠寶藝術學院', '臺北市中山區', '2025-04-07 00:00:00', '2025-06-27 00:00:00', '中山區（臺北市）=', 25.06969917, 121.5381597, '/+153500', 'https://jart.org.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年4月7日【珠寶設計師專業職能】', `description`='你不該知道的珠寶業營運秘密，3個月讓你成為珠寶行內人。\r\n設計是一種「品味」和「品味」的交換，珠寶設計師不但要彰顯佩戴者的氣質，更要將自已的風格融入設計之中。\r\n設計師必須有「估價」的能力，懂得利用最少的「物力、財力、人力、時間」來獲取最大的經濟效果。\r\n因此，珠寶設計要學習的包括材料：貴金屬和寶石。工法：金屬工藝、首飾製程、鑲嵌工法等。\r\n繪畫，只是一種表現技法而已。\r\n臺灣並無珠寶原料礦藏，沒有產地優勢