INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e65d26b32418d001b8c5', '2025年3月17日【基礎金工技術班–10天紮實基本功】平日班', '從一塊金屬版開始，掌握「鋸、磨、焊、鍛、拋」等綜合金屬技法，在高級珠寶首飾製造業師的陪同指導過程，引領您認識珠寶藝術之「工序、工具、工法、工藝」等生產邏輯，認識珠寶首飾金工的專業性和趣味性，同時引帶「珠寶業」給您認識，鼓勵大家選擇珠寶為職業。\r\n【基礎珠寶金工】課程特色在於每個步驟，都是您親自動手完成，獨立製作【素圈手鍊、鏤空圖樣墜、素面戒、線圈戒、包鑲飾品、爪鑲飾品】，完成共6~10款作品。\r\n\r\n授課內容\r\n	課程簡介，珠寶工藝概論。\r\n	認識貴金屬（黃金、鉑金、銀、鈀、銅、K金、玫瑰金。）\r\n	備料示範：條材、版材、管材。\r\n	線的應用、焊圈。\r\n	手鍊的製作實習。\r\n	鋸法應用與實習。\r\n	斗圈戒的製作實習。\r\n	花式線圈戒的製作實習。\r\n	包圈鑲法的應用。\r\n	包圈鑲法的延伸應用與實習。\r\n	圓鑽管鑲座與鑲爪。\r\n	管鑲座墬飾應用與實習。\r\n\r\n適用對象\r\n參與者不須具備任何基礎，對珠寶金工、飾品製造技術有興趣者皆可參加。\r\n班別時段\r\n【平日班】2025年3月17日始至2025年3月28日止，週一至五9:30至17:00，共計10堂。\r\n教室地址\r\n台北市中山區松江路5號之1。(捷運忠孝新生站4號出口)\r\n課程費用\r\n學費為新臺幣25,500元整。學費包含課程期間所需材料，其他器具設備教室均有配置提供，學員毋需另購任何器材。\r\n結業文憑\r\n通過本院考核，頒發珠寶基礎金工技術培訓結業證書。\r\n報名方式─線上報名：goo.gl/UXWwds\r\n請完成線上報名表提交，並完成訂金10%（或全額學費）繳付，即完成受理報名程序，未完成訂金繳付恕無法保留學籍資格或名額。\r\n【加Line聯繫】請搜尋ID『@jart』或連結 https://line.me/R/ti/p/%40jart。\r\n課程詳細內容請連結: https://www.jart.org.tw/products/intro-goldsmiths', '臺灣珠寶藝術學院', '臺北市中山區', '2025-03-17 00:00:00', '2025-03-28 00:00:00', '中山區（臺北市）=', 25.06969917, 121.5381597, '/+25500', 'https://jart.org.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年3月17日【基礎金工技術班–10天紮實基本功】平日班', `description`='從一塊金屬版開始，掌握「鋸、磨、焊、鍛、拋」等綜合金屬技法，在高級珠寶首飾製造業師的陪同指導過程，引領您認識珠寶藝術之「工序、工具、工法、工藝」等生產邏輯，認識珠寶首飾金工的專業性和趣味性，同時引帶「珠寶業」給您認識，鼓勵大家選擇珠寶為職業。\r\n【基礎珠寶金工】課程特色在於每個步驟，都是您親自動手完成，獨立製作【素圈手鍊、鏤空圖樣墜、素面戒、線圈戒、包鑲飾品、爪鑲飾品】，完成共6~10款作品。\r\n\r\n授課內容\r\n	課程簡介，珠寶工藝概論。\r\n	認識貴金屬（黃金、鉑金、銀、鈀、銅、K金、玫瑰金。）\r\n	備料示範：條材、版材、管材。\r\n	線的應用、焊圈。\r\n	手鍊的製作實習。\r\n	鋸法應用與實習。\r\n	斗圈戒的製作實習。\r\n	花式線圈戒的製作實習。\r\n	包圈鑲法的應用。\r\n	包圈鑲法的延伸應用與實習。\r\n	圓鑽管鑲座與鑲爪。\r\n	管鑲座墬飾應用與實習。\r\n\r\n適用對象\r\n參與者不須具備任何基礎，對珠寶金工、飾品製造技術有興趣者皆可參加。\r\n班別時段\r\n【平日班】2025年3月17日始至2025年3月28日止，週一至五9:30至17:00，共計10堂。\r\n教室地址\r\n台北市中山區松江路5號之1。(捷運忠孝新生站4號出口)\r\n課程費用\r\n學費為新臺幣25,500元整。學費包含課程期間所需材料，其他器具設備教室均有配置提供，學員毋需另購任何器材。\r\n結業文憑\r\n通過本院考核，頒發珠寶基礎金工技術培訓結業證書。\r\n報名方式─線上報名：goo.gl/UXWwds\r\n請完成線上報名表提交，並完成訂金10%（或全額學費）繳付，即完成受理報名程序，未完成訂金繳付恕無法保留學籍資格或名額。\r\n【加Line聯繫】請搜尋ID『@jart』或連結 https://line.me/R/ti/p/%40jart。\r\n課程詳細內容請連結: https://www.jart.org.tw/products/intro-goldsmiths', `organizer`='臺灣珠寶藝術學院', `address`='臺北市中山區', `start_date`='2025-03-17 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='中山區（臺北市）=', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='/+25500', `source_url`='https://jart.org.tw', `image_url`='[]';
