INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66826b32418d001b8f2', '國際民俗舞蹈體驗及書展（114年4月）', '「國際民俗舞蹈」體驗營，每月第三個週六下午舉辦，教授不同國家民俗舞蹈，帶領民眾藉由音樂與舞蹈，享受環遊世界的樂趣。現場並展示教授國家相關書籍及服飾。\r\n活動完全免費，歡迎體驗，洽詢電話：049-2317071', '國立公共資訊圖書館中興分館', '南投縣南投市中興新村光華路 123 號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '國立公共資訊圖書館中興分館', 23.949518, 120.694397, '無資料', 'https://www.facebook.com/NLPICH/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國際民俗舞蹈體驗及書展（114年4月）', `description`='「國際民俗舞蹈」體驗營，每月第三個週六下午舉辦，教授不同國家民俗舞蹈，帶領民眾藉由音樂與舞蹈，享受環遊世界的樂趣。現場並展示教授國家相關書籍及服飾。\r\n活動完全免費，歡迎體驗，洽詢電話：049-2317071', `organizer`='國立公共資訊圖書館中興分館', `address`='南投縣南投市中興新村光華路 123 號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='國立公共資訊圖書館中興分館', `latitude`=23.949518, `longitude`=120.694397, `ticket_price`='無資料', `source_url`='https://www.facebook.com/NLPICH/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66926b32418d001b8f3', '熱門書展＆新進童書展（114年4月）', '熱門書展／圖書館一樓門廳、三樓書庫\r\n 本展每月規劃精選主題圖書展出\r\n新進童書展／圖書館兒童室\r\n 展出每月進館優良童書\r\n歡迎到館閱覽，一起享受閱讀的樂趣！', '國立公共資訊圖書館中興分館', '南投縣南投市中興新村光華路 123 號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '國立公共資訊圖書館中興分館', 23.949518, 120.694397, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='熱門書展＆新進童書展（114年4月）', `description`='熱門書展／圖書館一樓門廳、三樓書庫\r\n 本展每月規劃精選主題圖書展出\r\n新進童書展／圖書館兒童室\r\n 展出每月進館優良童書\r\n歡迎到館閱覽，一起享受閱讀的樂趣！', `organizer`='國立公共資訊圖書館中興分館', `address`='南投縣南投市中興新村光華路 123 號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='國立公共資訊圖書館中興分館', `latitude`=23.949518, `longitude`=120.694397, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66926b32418d001b8f4', '2025竹山『小鎮躍動』藝文表演：優秀樂團', '每週六「小鎮躍動」由駐唱歌手、樂團、魔術、泡泡秀…等，來自不同團體帶來的各類精彩演出，歡迎鄉親們來菸葉館欣賞表演。\r\n如遇天候不佳，主辦單位有取消活動的權利。', '南投縣竹山鎮公所', '南投縣竹山鎮', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '竹山鎮（南投縣）=', 23.69805518, 120.7100797, '無資料', 'https://www.facebook.com/JhuShan', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025竹山『小鎮躍動』藝文表演：優秀樂團', `description`='每週六「小鎮躍動」由駐唱歌手、樂團、魔術、泡泡秀…等，來自不同團體帶來的各類精彩演出，歡迎鄉親們來菸葉館欣賞表演。\r\n如遇天候不佳，主辦單位有取消活動的權利。', `organizer`='南投縣竹山鎮公所', `address`='南投縣竹山鎮', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='竹山鎮（南投縣）=', `latitude`=23.69805518, `longitude`=120.7100797, `ticket_price`='無資料', `source_url`='https://www.facebook.com/JhuShan', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66926b32418d001b8f5', '【新化演藝廳】成大南工管樂社-室內樂的競技', '室內樂與個人獨奏的魅力其音樂會形式非常多樣，其中室內樂與個人獨奏各具特色。\r\n室內樂由少數音樂家合作演奏，如弦樂四重奏、銅管五重奏，講究默契與互動，營造親密氛圍。\r\n而個人獨奏則聚焦於單一演奏者的技巧與詮釋，展現個人魅力與音樂表現力。\r\n一種強調團隊協作，一種凸顯個人風采，各有獨特韻味。無論是欣賞細膩的合奏，還是感受獨奏的張力，都能體驗音樂的無限魅力。', '臺南市政府文化局', '臺南市新化區信義路142-1號', '2025-03-02 00:00:00', '2025-03-02 00:00:00', '新化演藝廳', 23.03394545, 120.3357964, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新化演藝廳】成大南工管樂社-室內樂的競技', `description`='室內樂與個人獨奏的魅力其音樂會形式非常多樣，其中室內樂與個人獨奏各具特色。\r\n室內樂由少數音樂家合作演奏，如弦樂四重奏、銅管五重奏，講究默契與互動，營造親密氛圍。\r\n而個人獨奏則聚焦於單一演奏者的技巧與詮釋，展現個人魅力與音樂表現力。\r\n一種強調團隊協作，一種凸顯個人風采，各有獨特韻味。無論是欣賞細膩的合奏，還是感受獨奏的張力，都能體驗音樂的無限魅力。', `organizer`='臺南市政府文化局', `address`='臺南市新化區信義路142-1號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='新化演藝廳', `latitude`=23.03394545, `longitude`=120.3357964, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66926b32418d001b8f6', '將軍區圖書館:2月主題書展 _台語悄悄地說話', '在書頁翻動的聲音裡，台語悄悄地說話。\r\n台語書展不僅是一本本書籍的集會，更像是一場跨世代的文化對話——用文字拾起語言的餘溫，讓土地的聲音重新被聽見。', '臺南市將軍區公所', '臺南市將軍區180-50號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南市將軍區圖書館', 23.20834413, 120.1276958, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='將軍區圖書館:2月主題書展 _台語悄悄地說話', `description`='在書頁翻動的聲音裡，台語悄悄地說話。\r\n台語書展不僅是一本本書籍的集會，更像是一場跨世代的文化對話——用文字拾起語言的餘溫，讓土地的聲音重新被聽見。', `organizer`='臺南市將軍區公所', `address`='臺南市將軍區180-50號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市將軍區圖書館', `latitude`=23.20834413, `longitude`=120.1276958, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66926b32418d001b8f7', '2月藝術展覽活動-巧手剪出幸福(剪紙)', '在一張薄薄的紙上，時光輕輕落下刀痕。\r\n\r\n剪紙，是手與紙交談的藝術，也是記憶與生活的溫柔連結。當銀髮長者執起剪刀，將圖案從紙張裡慢慢剪出，彷彿把歲月裡的故事與細碎情感，一刀一剪細細雕琢出來。\r\n樂齡剪紙創作者:黃玉花、陳麗華、邱春英等人。', '臺南市將軍區公所', '臺南市將軍區180-50號', '2025-02-01 00:00:00', '2025-02-28 00:00:00', '臺南市將軍區圖書館', 23.20834413, 120.1276958, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2月藝術展覽活動-巧手剪出幸福(剪紙)', `description`='在一張薄薄的紙上，時光輕輕落下刀痕。\r\n\r\n剪紙，是手與紙交談的藝術，也是記憶與生活的溫柔連結。當銀髮長者執起剪刀，將圖案從紙張裡慢慢剪出，彷彿把歲月裡的故事與細碎情感，一刀一剪細細雕琢出來。\r\n樂齡剪紙創作者:黃玉花、陳麗華、邱春英等人。', `organizer`='臺南市將軍區公所', `address`='臺南市將軍區180-50號', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='臺南市將軍區圖書館', `latitude`=23.20834413, `longitude`=120.1276958, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66926b32418d001b8f8', '影片：繼承風暴', '無資料', '花蓮縣文化局', '花蓮縣花蓮市中山路71號', '2025-03-07 00:00:00', '2025-03-07 00:00:00', '花蓮鐵道文化館一館', 23.99700271, 121.6071463, '全票+200;學生票+150;愛心票+100', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='影片：繼承風暴', `description`='無資料', `organizer`='花蓮縣文化局', `address`='花蓮縣花蓮市中山路71號', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-07 00:00:00', `location`='花蓮鐵道文化館一館', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='全票+200;學生票+150;愛心票+100', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66926b32418d001b8f9', '寶島四季的土地神光-林飛雄攝影展', '這是一場信仰與大自然交融的靈光之旅。\r\n土地公是最「接地氣」的神明，展覽以四季為經，二十四節氣為緯，結合土地公信仰與自然景致，用光影記錄節氣更迭中的信仰之美。\r\n二十四節氣是民俗文化的瑰寶，土地公則是守護一方的神祇，兩者皆深植於常民的生活中。本次展覽透過攝影師林飛雄的視角，呈現土地公在四季流轉中充滿詩意的不同守護。', '桃園市土地公文化館', '桃園市桃園區三民路一段100號', '2025-02-22 00:00:00', '2025-03-30 00:00:00', '桃園市土地公文化館', 24.998189, 121.321246, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='寶島四季的土地神光-林飛雄攝影展', `description`='這是一場信仰與大自然交融的靈光之旅。\r\n土地公是最「接地氣」的神明，展覽以四季為經，二十四節氣為緯，結合土地公信仰與自然景致，用光影記錄節氣更迭中的信仰之美。\r\n二十四節氣是民俗文化的瑰寶，土地公則是守護一方的神祇，兩者皆深植於常民的生活中。本次展覽透過攝影師林飛雄的視角，呈現土地公在四季流轉中充滿詩意的不同守護。', `organizer`='桃園市土地公文化館', `address`='桃園市桃園區三民路一段100號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='桃園市土地公文化館', `latitude`=24.998189, `longitude`=121.321246, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
