INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66926b32418d001b900', '伯公生-走讀東山客家聚落', '走讀東山客家聚落 感受文化底蘊\r\n東山地區因日治時期氣候與土壤適宜種植香蕉，吸引來自新竹、苗栗等地的客家人南下拓墾定居。本次活動將帶領民眾走訪東原福興宮，依循傳統客家祭典儀式為伯公祝壽，並深入探索青山崎仔頭李家家祠、青山埤角詹家家祠、郭家宗祠等客底聚落，親身體驗客家文化的歷史風華。', '臺南市政府客家事務委員會', '臺南市東山區', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '東山區（臺南市）=', 23.2783187, 120.4441211, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='伯公生-走讀東山客家聚落', `description`='走讀東山客家聚落 感受文化底蘊\r\n東山地區因日治時期氣候與土壤適宜種植香蕉，吸引來自新竹、苗栗等地的客家人南下拓墾定居。本次活動將帶領民眾走訪東原福興宮，依循傳統客家祭典儀式為伯公祝壽，並深入探索青山崎仔頭李家家祠、青山埤角詹家家祠、郭家宗祠等客底聚落，親身體驗客家文化的歷史風華。', `organizer`='臺南市政府客家事務委員會', `address`='臺南市東山區', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='東山區（臺南市）=', `latitude`=23.2783187, `longitude`=120.4441211, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
