INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66926b32418d001b905', '何景窗書法創作個展', '書法詩人何景窗筆下的「一嗅一吸」，\r\n是書法運筆時呼吸輕重緩急的頻率，是創作過程中靈感吐納的以詩入墨。亦是旅人在綉溪的五感休息——\r\n靜態作品展示——綉溪安平 1F 大廳／咖啡廳／沉浸式互動空間、2F 廊道、R2 綉溪之眼\r\n沉浸式全新場景——沉浸式互動空間首播何景窗主題全新創作影片', '綉溪安平', '臺南市安平區', '2025-01-10 00:00:00', '2025-03-03 00:00:00', '安平區（臺南市）=', 22.99008437, 120.1649949, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='何景窗書法創作個展', `description`='書法詩人何景窗筆下的「一嗅一吸」，\r\n是書法運筆時呼吸輕重緩急的頻率，是創作過程中靈感吐納的以詩入墨。亦是旅人在綉溪的五感休息——\r\n靜態作品展示——綉溪安平 1F 大廳／咖啡廳／沉浸式互動空間、2F 廊道、R2 綉溪之眼\r\n沉浸式全新場景——沉浸式互動空間首播何景窗主題全新創作影片', `organizer`='綉溪安平', `address`='臺南市安平區', `start_date`='2025-01-10 00:00:00', `end_date`='2025-03-03 00:00:00', `location`='安平區（臺南市）=', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66926b32418d001b906', '台南暖暖蛇 - 林百貨', '「 #台南暖暖蛇 」靈感來自蛇年的生肖文化\r\n主視覺設計以萌趣的蛇年生肖為靈感，再搭配鞭炮、燈籠、圍爐等經典元素，濃濃年味撲面而來！另外用剪紙 藝術風格，讓畫面充滿傳統年節的喜慶美感，手繪的主題字更散發出濃厚的暖心氣息。⁣⁣', '市定古蹟原林百貨店', '臺南市中西區忠義路二段63號', '2025-01-10 00:00:00', '2025-03-03 00:00:00', '市定古蹟原林百貨店', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台南暖暖蛇 - 林百貨', `description`='「 #台南暖暖蛇 」靈感來自蛇年的生肖文化\r\n主視覺設計以萌趣的蛇年生肖為靈感，再搭配鞭炮、燈籠、圍爐等經典元素，濃濃年味撲面而來！另外用剪紙 藝術風格，讓畫面充滿傳統年節的喜慶美感，手繪的主題字更散發出濃厚的暖心氣息。⁣⁣', `organizer`='市定古蹟原林百貨店', `address`='臺南市中西區忠義路二段63號', `start_date`='2025-01-10 00:00:00', `end_date`='2025-03-03 00:00:00', `location`='市定古蹟原林百貨店', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66926b32418d001b907', '蛇年神農街元宵花燈展', '活動內容｜彩繪花燈展、猜燈謎、攝影比賽、提燈夜遊、國際友人彩繪花燈、神農街超級比一比...超多精彩活動,歡迎你來', '臺南市中西區公所', '臺南市中西區', '2025-01-24 00:00:00', '2025-03-02 00:00:00', '中西區（臺南市）=', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蛇年神農街元宵花燈展', `description`='活動內容｜彩繪花燈展、猜燈謎、攝影比賽、提燈夜遊、國際友人彩繪花燈、神農街超級比一比...超多精彩活動,歡迎你來', `organizer`='臺南市中西區公所', `address`='臺南市中西區', `start_date`='2025-01-24 00:00:00', `end_date`='2025-03-02 00:00:00', `location`='中西區（臺南市）=', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66926b32418d001b908', '台灣祭_南國趴', '2/28\r\n南方大唱樂團全國前20強比拚選出前10強\r\n緊接著\r\n一起聽團吧！工口紳士、固定客、溫蒂漫步熱鬧演出\r\n🎤3/1\r\n玖壹壹、高爾宣壓軸登場\r\n\r\n演出陣容👇\r\n玖壹壹｜溫蒂漫步｜高爾宣｜固定客｜閃閃閃閃｜王Aden｜PIZZALI｜歐吉虎｜工口紳士｜五木｜Lilhao｜南方大唱20強\r\n\r\n「南方大唱比賽」持續挖掘台灣本土音樂人才，經過激烈海選後，前20強隊伍將於2月28日下午2點，在墾丁大灣草地進行全國複賽，包括如選秀節目《一起聽團吧》全明星樂團組合「FLOAT」、台北音樂不斷電十強「漁光倒」、來自香港知名創作歌手「迪子」，以及全國知名的「徐行」、「孔雀眼」等', '屏東縣政府', '屏東縣恆春鎮', '2025-02-28 00:00:00', '2025-03-01 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台灣祭_南國趴', `description`='2/28\r\n南方大唱樂團全國前20強比拚選出前10強\r\n緊接著\r\n一起聽團吧！工口紳士、固定客、溫蒂漫步熱鬧演出\r\n🎤3/1\r\n玖壹壹、高爾宣壓軸登場\r\n\r\n演出陣容👇\r\n玖壹壹｜溫蒂漫步｜高爾宣｜固定客｜閃閃閃閃｜王Aden｜PIZZALI｜歐吉虎｜工口紳士｜五木｜Lilhao｜南方大唱20強\r\n\r\n「南方大唱比賽」持續挖掘台灣本土音樂人才，經過激烈海選後，前20強隊伍將於2月28日下午2點，在墾丁大灣草地進行全國複賽，包括如選秀節目《一起聽團吧》全明星樂團組合「FLOAT」、台北音樂不斷電十強「漁光倒」、來自香港知名創作歌手「迪子」，以及全國知名的「徐行」、「孔雀眼」等', `organizer`='屏東縣政府', `address`='屏東縣恆春鎮', `start_date`='2025-02-28 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66a26b32418d001b909', '屏東的蘭花生活美學', '本次蘭花系列主題以「屏東的蘭花生活美學」為主題，在屏東農業物產館2樓展示空間分別用蘭花借用咖啡館、居酒屋、水族館和早午餐的空間營造蘭花和在地物產，以超現實感的融合，共創不同空間風貌和心境感受。\r\n蘭花就是屏東的日常生活，也許在田野、樹林、街口轉角或居家一隅。這次策展讓蘭花出現在日常個場所，以不同空間創意營造讓參觀者可以品味創意生活提案。', '屏東縣政府', '屏東縣長治鄉', '2025-02-26 00:00:00', '2025-03-23 00:00:00', '長治鄉（屏東縣）=', 22.69454952, 120.555979, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='屏東的蘭花生活美學', `description`='本次蘭花系列主題以「屏東的蘭花生活美學」為主題，在屏東農業物產館2樓展示空間分別用蘭花借用咖啡館、居酒屋、水族館和早午餐的空間營造蘭花和在地物產，以超現實感的融合，共創不同空間風貌和心境感受。\r\n蘭花就是屏東的日常生活，也許在田野、樹林、街口轉角或居家一隅。這次策展讓蘭花出現在日常個場所，以不同空間創意營造讓參觀者可以品味創意生活提案。', `organizer`='屏東縣政府', `address`='屏東縣長治鄉', `start_date`='2025-02-26 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='長治鄉（屏東縣）=', `latitude`=22.69454952, `longitude`=120.555979, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66a26b32418d001b90a', '𝟐𝟐𝟖紀念音樂劇《以愛相會》', '屏東縣政府製作𝟐𝟐𝟖紀念音樂劇《以愛相會》\r\nꕥ改編自屏東真實人物——高齡96歲「阿會阿嬤」 的生命經驗\r\n她與丈夫玉杉在228事件期間一趟生死交關的新婚旅行。透過這段動人故事，在歷史洪流中共同反思，以愛代替仇恨\r\n主演 ▚ 陽光美人小嫻 （黃瑜嫻） ╳ 明華園當家武生 #陳子豪\r\nꗃ多首原創曲，現場管弦及搖滾樂團伴奏\r\nꗃ 改編自真人真事的劇情，不自覺動容\r\nꗃ 盛大歌舞場面，令人身歷其境', '屏東縣政府', '屏東縣屏東市民生路4之17號', '2025-02-28 00:00:00', '2025-02-28 00:00:00', '屏東演藝廳', 22.6647375, 120.4799948, '全票+400;全票+600;全票+800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='𝟐𝟐𝟖紀念音樂劇《以愛相會》', `description`='屏東縣政府製作𝟐𝟐𝟖紀念音樂劇《以愛相會》\r\nꕥ改編自屏東真實人物——高齡96歲「阿會阿嬤」 的生命經驗\r\n她與丈夫玉杉在228事件期間一趟生死交關的新婚旅行。透過這段動人故事，在歷史洪流中共同反思，以愛代替仇恨\r\n主演 ▚ 陽光美人小嫻 （黃瑜嫻） ╳ 明華園當家武生 #陳子豪\r\nꗃ多首原創曲，現場管弦及搖滾樂團伴奏\r\nꗃ 改編自真人真事的劇情，不自覺動容\r\nꗃ 盛大歌舞場面，令人身歷其境', `organizer`='屏東縣政府', `address`='屏東縣屏東市民生路4之17號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-02-28 00:00:00', `location`='屏東演藝廳', `latitude`=22.6647375, `longitude`=120.4799948, `ticket_price`='全票+400;全票+600;全票+800', `source_url`='https://www.opentix.life/', `image_url`='[]';
