INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66a26b32418d001b90c', '【總爺國際藝術駐村計畫】《在消逝之前》黃建寰創作個展', '1823年曾文溪因豪雨被迫改道，夾帶大量泥沙導致臺江內海的淤積。2024年7月，凱米颱風肆虐，大水又淹出曾經的海港形狀。水與陸地的消長，邊界的浮動，兩個時空疊合的遇見，水帶回消失的記憶。藝術家黃建寰用空間與聲裝置，訴說這些傳說裏歷經滄海桑田的海河港變遷，以及層疊交錯卻逐漸消逝的土地記憶。', '臺南市政府文化局', '臺南市麻豆區總爺5號', '2025-01-01 00:00:00', '2025-04-06 00:00:00', '臺南市總爺藝文中心', 23.18248033, 120.241308, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【總爺國際藝術駐村計畫】《在消逝之前》黃建寰創作個展', `description`='1823年曾文溪因豪雨被迫改道，夾帶大量泥沙導致臺江內海的淤積。2024年7月，凱米颱風肆虐，大水又淹出曾經的海港形狀。水與陸地的消長，邊界的浮動，兩個時空疊合的遇見，水帶回消失的記憶。藝術家黃建寰用空間與聲裝置，訴說這些傳說裏歷經滄海桑田的海河港變遷，以及層疊交錯卻逐漸消逝的土地記憶。', `organizer`='臺南市政府文化局', `address`='臺南市麻豆區總爺5號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='臺南市總爺藝文中心', `latitude`=23.18248033, `longitude`=120.241308, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
