INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66a26b32418d001b90f', '【器載柚香】藝術創作聯展－2025麻豆柚花季柚花陶藝特展', '台南的三月屬於花，特別是麻豆柚子花，本展以麻豆區在地特色作物柚子為主軸，將柚花之韻、自然的呼吸、傳統與創新三大主題，結合柚花的純淨與自然意象，透過藝術作品展現土地、文化與工藝的結合，不僅展出以柚花為核心的藝術作品，也涵蓋其他創新陶藝創作與書畫，為2025麻豆柚花季拉開序幕。', '臺南市政府文化局', '臺南市麻豆區總爺5號', '2025-03-01 00:00:00', '2025-04-27 00:00:00', '臺南市總爺藝文中心', 23.18248033, 120.241308, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【器載柚香】藝術創作聯展－2025麻豆柚花季柚花陶藝特展', `description`='台南的三月屬於花，特別是麻豆柚子花，本展以麻豆區在地特色作物柚子為主軸，將柚花之韻、自然的呼吸、傳統與創新三大主題，結合柚花的純淨與自然意象，透過藝術作品展現土地、文化與工藝的結合，不僅展出以柚花為核心的藝術作品，也涵蓋其他創新陶藝創作與書畫，為2025麻豆柚花季拉開序幕。', `organizer`='臺南市政府文化局', `address`='臺南市麻豆區總爺5號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺南市總爺藝文中心', `latitude`=23.18248033, `longitude`=120.241308, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
