INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66a26b32418d001b911', '【性別符號】│雙姝怨', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│北非諜影+幕後花絮\r\n英文片│Casablanca\r\n\r\n導演│麥可•寇蒂斯\r\n法國.美國│1942│普遍級│劇情片│黑白│英.法.德.義大利語│185分鐘\r\n\r\n簡介\r\n前美國情報員瑞克於當地經營一間酒吧，有一天瑞克的昔日女友伊莎及其丈夫維克多走進了瑞克的酒吧，兩人回憶起過去、舊情復燃，最後瑞克選擇幫助伊莎及其丈夫維克多逃離納粹的魔掌，完成捨愛取義的功績。', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【性別符號】│雙姝怨', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│北非諜影+幕後花絮\r\n英文片│Casablanca\r\n\r\n導演│麥可•寇蒂斯\r\n法國.美國│1942│普遍級│劇情片│黑白│英.法.德.義大利語│185分鐘\r\n\r\n簡介\r\n前美國情報員瑞克於當地經營一間酒吧，有一天瑞克的昔日女友伊莎及其丈夫維克多走進了瑞克的酒吧，兩人回憶起過去、舊情復燃，最後瑞克選擇幫助伊莎及其丈夫維克多逃離納粹的魔掌，完成捨愛取義的功績。', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
