INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66a26b32418d001b914', '【性別符號】│鐵娘子：堅固柔情', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│鐵娘子：堅固柔情\r\n英文片│The Iron Lady\r\n\r\n導演│菲莉妲•洛伊德\r\n法國.英國│2011│保護級│劇情類│彩色│英語│104分\r\n\r\n簡介\r\n1979年瑪格麗特柴契爾突破重重考驗，打破性別的藩籬，順利進入上議院成為議員，可真正的阻礙才正要開始，她提出的政見總是被男性議員揶揄，可是她沒有因此放棄，她在由男性主導的社會體制下成功獲選為英國首任女性首相，開創一段不凡成就的傳奇人生。故事重展當年柴契爾夫人職掌大權的氣魄風姿及其為了權力所付出的巨大代價，真實呈現這位不平凡的女性當年的傳奇風貌。', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【性別符號】│鐵娘子：堅固柔情', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│鐵娘子：堅固柔情\r\n英文片│The Iron Lady\r\n\r\n導演│菲莉妲•洛伊德\r\n法國.英國│2011│保護級│劇情類│彩色│英語│104分\r\n\r\n簡介\r\n1979年瑪格麗特柴契爾突破重重考驗，打破性別的藩籬，順利進入上議院成為議員，可真正的阻礙才正要開始，她提出的政見總是被男性議員揶揄，可是她沒有因此放棄，她在由男性主導的社會體制下成功獲選為英國首任女性首相，開創一段不凡成就的傳奇人生。故事重展當年柴契爾夫人職掌大權的氣魄風姿及其為了權力所付出的巨大代價，真實呈現這位不平凡的女性當年的傳奇風貌。', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66a26b32418d001b915', '織心織藝—林喜美藝師賽德克族傳統織布工藝暨創作個展', '南投縣仁愛鄉是賽德克族人口最集中的地區，賽德克族的織布工藝以精緻的手工技法與獨特的紋飾設計聞名，展現濃厚的民族藝術風格與文化底蘊，因此被列為國家文化資產保存項目之一。林喜美藝師作為南投縣傳統工藝「Tninun na Seediq bale賽德克族傳統織布工藝」的保存者，不僅熟稔各種傳統織法，還精通苧麻線的製作工序，從原料採集到織品完成，每一個細節都展現出她對文化的尊重與熱愛。\r\n本次展覽以「織心織藝」為題，代表藝師以一顆堅定的心，承襲先祖智慧，並在創作中融合傳統與創新，使織藝不僅是文化的傳承，更是藝術的延續。展出作品涵蓋經典的傳統織品與融入當代設計的創新之作，讓觀眾在欣賞工藝之餘，也能感受到賽德克族文化的活力與變遷。\r\n歡迎大家蒞臨，共同見證賽德克族傳統織布工藝的細膩技法與文化價值，親身感受賽德克族傳統織布工藝的卓越之美，體驗台灣原住民文化的深遠魅力。\r\n開幕茶會：114年3月1日下午2時30分', '南投縣政府文化局', '南投縣南投市彰南路二段65號', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '南投縣文化園區', 23.9080665, 120.685073, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='織心織藝—林喜美藝師賽德克族傳統織布工藝暨創作個展', `description`='南投縣仁愛鄉是賽德克族人口最集中的地區，賽德克族的織布工藝以精緻的手工技法與獨特的紋飾設計聞名，展現濃厚的民族藝術風格與文化底蘊，因此被列為國家文化資產保存項目之一。林喜美藝師作為南投縣傳統工藝「Tninun na Seediq bale賽德克族傳統織布工藝」的保存者，不僅熟稔各種傳統織法，還精通苧麻線的製作工序，從原料採集到織品完成，每一個細節都展現出她對文化的尊重與熱愛。\r\n本次展覽以「織心織藝」為題，代表藝師以一顆堅定的心，承襲先祖智慧，並在創作中融合傳統與創新，使織藝不僅是文化的傳承，更是藝術的延續。展出作品涵蓋經典的傳統織品與融入當代設計的創新之作，讓觀眾在欣賞工藝之餘，也能感受到賽德克族文化的活力與變遷。\r\n歡迎大家蒞臨，共同見證賽德克族傳統織布工藝的細膩技法與文化價值，親身感受賽德克族傳統織布工藝的卓越之美，體驗台灣原住民文化的深遠魅力。\r\n開幕茶會：114年3月1日下午2時30分', `organizer`='南投縣政府文化局', `address`='南投縣南投市彰南路二段65號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='南投縣文化園區', `latitude`=23.9080665, `longitude`=120.685073, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66a26b32418d001b917', '泰雅原住民文化產業區「原音傳世」假日藝文展演：街頭藝人表演 （114年3月）', '114年苗栗縣原住民族文物館假日藝文展演活動，以「原音傳世」為主題，分別象徵著原住民族的音樂、舞蹈、歌謠及藝術的歷史延續與傳承。\r\n「原音」指的是原住民族純粹且具有特色的音樂與聲音，承載著各族群的歷史、故事和情感，原音常與舞蹈相伴相生，音樂的節奏牽引舞步，歌聲的抑揚訴說情感，音樂與舞蹈如靈魂雙翼，共繪生命張力與自然和諧。「傳世」則強調了文化精粹的歷史傳承及跨世代的影響力，透過藝文展演，原聲與舞蹈交融，兩者相映，共同喚醒對原住民族文化的敬意，傳遞珍貴聲音背後的靈魂與故事。\r\n泰雅文物館假日藝文展演活動自1月29日（農曆正月初一）至2月2日（農曆正月初五）期間，每日安排街頭藝人或表演團體共5場次的演出，2月15日至12月27日止，邀請原住民團體或樂團演出，每週六表演一場次，14:20～15:00；共計45場次。2月9日至12月28日止，安排街頭藝人演出，每個月第2、4個週日表演一場次，表演時間10:00~12:00；共計22場。', '苗栗縣政府原住民族及族群發展處', '苗栗縣泰安鄉圓墩6鄰46-3號', '2025-03-09 00:00:00', '2025-03-23 00:00:00', '苗栗縣泰雅原住民文化產業區', 24.41925819, 121.0681571, '無資料', 'https://www.facebook.com/TAYALMUSEUM', '[]') ON DUPLICATE KEY UPDATE `activity_name`='泰雅原住民文化產業區「原音傳世」假日藝文展演：街頭藝人表演 （114年3月）', `description`='114年苗栗縣原住民族文物館假日藝文展演活動，以「原音傳世」為主題，分別象徵著原住民族的音樂、舞蹈、歌謠及藝術的歷史延續與傳承。\r\n「原音」指的是原住民族純粹且具有特色的音樂與聲音，承載著各族群的歷史、故事和情感，原音常與舞蹈相伴相生，音樂的節奏牽引舞步，歌聲的抑揚訴說情感，音樂與舞蹈如靈魂雙翼，共繪生命張力與自然和諧。「傳世」則強調了文化精粹的歷史傳承及跨世代的影響力，透過藝文展演，原聲與舞蹈交融，兩者相映，共同喚醒對原住民族文化的敬意，傳遞珍貴聲音背後的靈魂與故事。\r\n泰雅文物館假日藝文展演活動自1月29日（農曆正月初一）至2月2日（農曆正月初五）期間，每日安排街頭藝人或表演團體共5場次的演出，2月15日至12月27日止，邀請原住民團體或樂團演出，每週六表演一場次，14:20～15:00；共計45場次。2月9日至12月28日止，安排街頭藝人演出，每個月第2、4個週日表演一場次，表演時間10:00~12:00；共計22場。', `organizer`='苗栗縣政府原住民族及族群發展處', `address`='苗栗縣泰安鄉圓墩6鄰46-3號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='苗栗縣泰雅原住民文化產業區', `latitude`=24.41925819, `longitude`=121.0681571, `ticket_price`='無資料', `source_url`='https://www.facebook.com/TAYALMUSEUM', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66a26b32418d001b918', '泰雅原住民文化產業區「原音傳世」假日藝文展演：怡啦文化藝術團舞蹈表演', '114年苗栗縣原住民族文物館假日藝文展演活動，以「原音傳世」為主題，分別象徵著原住民族的音樂、舞蹈、歌謠及藝術的歷史延續與傳承。\r\n「原音」指的是原住民族純粹且具有特色的音樂與聲音，承載著各族群的歷史、故事和情感，原音常與舞蹈相伴相生，音樂的節奏牽引舞步，歌聲的抑揚訴說情感，音樂與舞蹈如靈魂雙翼，共繪生命張力與自然和諧。「傳世」則強調了文化精粹的歷史傳承及跨世代的影響力，透過藝文展演，原聲與舞蹈交融，兩者相映，共同喚醒對原住民族文化的敬意，傳遞珍貴聲音背後的靈魂與故事。\r\n泰雅文物館假日藝文展演活動自1月29日（農曆正月初一）至2月2日（農曆正月初五）期間，每日安排街頭藝人或表演團體共5場次的演出，2月15日至12月27日止，邀請原住民團體或樂團演出，每週六表演一場次，14:20～15:00；共計45場次。2月9日至12月28日止，安排街頭藝人演出，每個月第2、4個週日表演一場次，表演時間10:00~12:00；共計22場。', '苗栗縣政府原住民族及族群發展處', '苗栗縣泰安鄉圓墩6鄰46-3號', '2025-03-01 00:00:00', '2025-03-01 00:00:00', '苗栗縣泰雅原住民文化產業區', 24.41925819, 121.0681571, '無資料', 'https://www.facebook.com/TAYALMUSEUM', '[]') ON DUPLICATE KEY UPDATE `activity_name`='泰雅原住民文化產業區「原音傳世」假日藝文展演：怡啦文化藝術團舞蹈表演', `description`='114年苗栗縣原住民族文物館假日藝文展演活動，以「原音傳世」為主題，分別象徵著原住民族的音樂、舞蹈、歌謠及藝術的歷史延續與傳承。\r\n「原音」指的是原住民族純粹且具有特色的音樂與聲音，承載著各族群的歷史、故事和情感，原音常與舞蹈相伴相生，音樂的節奏牽引舞步，歌聲的抑揚訴說情感，音樂與舞蹈如靈魂雙翼，共繪生命張力與自然和諧。「傳世」則強調了文化精粹的歷史傳承及跨世代的影響力，透過藝文展演，原聲與舞蹈交融，兩者相映，共同喚醒對原住民族文化的敬意，傳遞珍貴聲音背後的靈魂與故事。\r\n泰雅文物館假日藝文展演活動自1月29日（農曆正月初一）至2月2日（農曆正月初五）期間，每日安排街頭藝人或表演團體共5場次的演出，2月15日至12月27日止，邀請原住民團體或樂團演出，每週六表演一場次，14:20～15:00；共計45場次。2月9日至12月28日止，安排街頭藝人演出，每個月第2、4個週日表演一場次，表演時間10:00~12:00；共計22場。', `organizer`='苗栗縣政府原住民族及族群發展處', `address`='苗栗縣泰安鄉圓墩6鄰46-3號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-01 00:00:00', `location`='苗栗縣泰雅原住民文化產業區', `latitude`=24.41925819, `longitude`=121.0681571, `ticket_price`='無資料', `source_url`='https://www.facebook.com/TAYALMUSEUM', `image_url`='[]';
