INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e66a26b32418d001b91d', '埔里鎮立圖書館-3月份故事列車', '歡迎大手牽小手一起來埔里圖書館二樓聽故事。洽詢電話：049-2984144轉40。', '南投縣埔里鎮公所', '南投縣埔里鎮六合路178號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '南投縣埔里鎮立圖書館', 23.9702357, 120.9713659, '無資料', 'https://www.facebook.com/pulilibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='埔里鎮立圖書館-3月份故事列車', `description`='歡迎大手牽小手一起來埔里圖書館二樓聽故事。洽詢電話：049-2984144轉40。', `organizer`='南投縣埔里鎮公所', `address`='南投縣埔里鎮六合路178號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='南投縣埔里鎮立圖書館', `latitude`=23.9702357, `longitude`=120.9713659, `ticket_price`='無資料', `source_url`='https://www.facebook.com/pulilibrary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c0e55926b32418d001b86d', '物有所適 - 生活儀式感特展', '隨著工藝角色的演變，它成為我們對生活品質的「期待」——不僅在於便利，更在於生活中的美學與質感。同樣當代人已不再只追求快速與效率，而更渴望緩慢、沉靜的生活節奏。透過放慢生活步調的倡議，引導人們在日常中培養對器物的覺察，體會工藝在生活中帶來的舒適與心靈上的寬慰（Comfort）。這種細微的覺察過程，是一條通向生活質感的儀式途徑。\n\n \n\n我們期許通過本次展覽，讓每個人發現與自身生活相適的工藝之美，同時，每件工藝器物都能在最適合的生活空間中找到其位置，成為日常生活中不可或缺的質感來源。\n\n \n\n這些物件本身，不只是滿足實用需求，更是一種對生活用心、細緻的追求。它引導我們以更為講究的態度，品味生活的精妙。這種追求並不僅是生活的表象，而是對當下的深刻「覺察」。而這種覺察的過程，正是我們所稱的「生活儀式感」。讓日常提升質感、賦予意義。\n\n \n\n展出資訊\n物有所適 - 生活儀式感特展\n第一檔展出日期：2025年1月21日至11月30日\n開館時間：每週二至週日 09:00-17:00\n展出地點：工藝文化館 2F-3F (南投縣草屯鎮中正路573號)\n\n \n\n📌相關網頁連結：工藝文化館展覽資訊\n\n ', '國立台灣工藝研究發展中心', '542  南投縣草屯鎮中正路573號', '2025-01-21 00:00:00', '2025-11-30 00:00:00', '工藝文化館', 23.9797002, 120.69095, '無資料', 'https://event.culture.tw/mocweb/reg/NTCRI/Detail.init.ctr?actId=50158', '[]') ON DUPLICATE KEY UPDATE `activity_name`='物有所適 - 生活儀式感特展', `description`='隨著工藝角色的演變，它成為我們對生活品質的「期待」——不僅在於便利，更在於生活中的美學與質感。同樣當代人已不再只追求快速與效率，而更渴望緩慢、沉靜的生活節奏。透過放慢生活步調的倡議，引導人們在日常中培養對器物的覺察，體會工藝在生活中帶來的舒適與心靈上的寬慰（Comfort）。這種細微的覺察過程，是一條通向生活質感的儀式途徑。\n\n \n\n我們期許通過本次展覽，讓每個人發現與自身生活相適的工藝之美，同時，每件工藝器物都能在最適合的生活空間中找到其位置，成為日常生活中不可或缺的質感來源。\n\n \n\n這些物件本身，不只是滿足實用需求，更是一種對生活用心、細緻的追求。它引導我們以更為講究的態度，品味生活的精妙。這種追求並不僅是生活的表象，而是對當下的深刻「覺察」。而這種覺察的過程，正是我們所稱的「生活儀式感」。讓日常提升質感、賦予意義。\n\n \n\n展出資訊\n物有所適 - 生活儀式感特展\n第一檔展出日期：2025年1月21日至11月30日\n開館時間：每週二至週日 09:00-17:00\n展出地點：工藝文化館 2F-3F (南投縣草屯鎮中正路573號)\n\n \n\n📌相關網頁連結：工藝文化館展覽資訊\n\n ', `organizer`='國立台灣工藝研究發展中心', `address`='542  南投縣草屯鎮中正路573號', `start_date`='2025-01-21 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='工藝文化館', `latitude`=23.9797002, `longitude`=120.69095, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTCRI/Detail.init.ctr?actId=50158', `image_url`='[]';
