INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9364700', '114年長者悠活健康促進系列課程', '一、&nbsp; &nbsp;&nbsp;課程日期：114年3月5日至5月28日(詳如課程表)二、&nbsp; &nbsp;&nbsp;課程地點：臺北市中山區健康服務中心(松江路367號7樓)第一會議室三、&nbsp; &nbsp;&nbsp;報名對象：65歲以上有高血壓、糖尿病、腦中風病史之長者或家屬優先四、&nbsp; &nbsp;&nbsp;報名時間：即日起至3月4日，額滿為止(限額30名)五、&nbsp; &nbsp;&nbsp;報名方式：(一)報名網址：https://reurl.cc/RLMW2r&nbsp;(二)電話報名：(02)2501-4616轉6335吳護理師六、&nbsp; &nbsp;&nbsp;課程表詳如附件。', '臺北市中山區健康服務中心', '無資料', '2025-02-05 00:00:00', '2025-05-28 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=9FDC5F436E433901', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年長者悠活健康促進系列課程', `description`='一、&nbsp; &nbsp;&nbsp;課程日期：114年3月5日至5月28日(詳如課程表)二、&nbsp; &nbsp;&nbsp;課程地點：臺北市中山區健康服務中心(松江路367號7樓)第一會議室三、&nbsp; &nbsp;&nbsp;報名對象：65歲以上有高血壓、糖尿病、腦中風病史之長者或家屬優先四、&nbsp; &nbsp;&nbsp;報名時間：即日起至3月4日，額滿為止(限額30名)五、&nbsp; &nbsp;&nbsp;報名方式：(一)報名網址：https://reurl.cc/RLMW2r&nbsp;(二)電話報名：(02)2501-4616轉6335吳護理師六、&nbsp; &nbsp;&nbsp;課程表詳如附件。', `organizer`='臺北市中山區健康服務中心', `address`='無資料', `start_date`='2025-02-05 00:00:00', `end_date`='2025-05-28 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=9FDC5F436E433901', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9361825', '星姊姊說故事【雙魚座的星座親子故事】', '雙魚座裡的兩條魚，可不是一般的小魚喔！而是愛與美之女神-阿芙羅黛媞及她的兒子艾羅斯所幻化而成的，為什麼母子倆會從天神變成魚兒呢？想瞭解雙魚座的星座故事並學會如何在夜空中找到這對親子魚，請報名參加3月8日的活動，共享親子天文時光。活動時間：3月8日（六）14:00-15:00。活動對象：親子（幼稚園大班至國小三年級的孩童及其家長）。活動地點：展示場二樓兒童區。活動內容 : 熱場活動-故事時間-雙魚座摺紙-小導覽(尋找展示場中的親子魚)。活動費用：免費。報名方式：線上報名注意事項：報名時只要填報參加兒童。購票參觀展示場即可免費參加活動（收費基準請參見購票資訊）。洽詢電話：02-28314551轉703展示組莊小姐。', '臺北市立天文科學教育館', '無資料', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=98D0163720EDA43B', '[]') ON DUPLICATE KEY UPDATE `activity_name`='星姊姊說故事【雙魚座的星座親子故事】', `description`='雙魚座裡的兩條魚，可不是一般的小魚喔！而是愛與美之女神-阿芙羅黛媞及她的兒子艾羅斯所幻化而成的，為什麼母子倆會從天神變成魚兒呢？想瞭解雙魚座的星座故事並學會如何在夜空中找到這對親子魚，請報名參加3月8日的活動，共享親子天文時光。活動時間：3月8日（六）14:00-15:00。活動對象：親子（幼稚園大班至國小三年級的孩童及其家長）。活動地點：展示場二樓兒童區。活動內容 : 熱場活動-故事時間-雙魚座摺紙-小導覽(尋找展示場中的親子魚)。活動費用：免費。報名方式：線上報名注意事項：報名時只要填報參加兒童。購票參觀展示場即可免費參加活動（收費基準請參見購票資訊）。洽詢電話：02-28314551轉703展示組莊小姐。', `organizer`='臺北市立天文科學教育館', `address`='無資料', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=98D0163720EDA43B', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9364540', '「靜‧物」開幕特別活動｜Photogram物件投影：和我⼀起⽣活的夥伴', '「靜‧物」開幕特別活動：Photogram物件投影傳統的「實物投影」是一種不需要相機拍攝的影像製作方式，只需把要塑造影像的物件直接放在感光相紙上曝光，之後再進行正常沖洗的暗房工作。本次工作坊配合「靜．物」展覽，以「和我一起生活的夥伴」為主題，使用數位方式製作實物投影，並加入其他材質與繪畫的元素，創造屬於自己的靜物作品。物件主題｜和我⼀起⽣活的夥伴請攜帶與記憶有關的物件，可以帶小孩的玩具或是喜歡的玩具、陪伴成⻑的物品、收藏物件，也可以帶乳⽛、眼鏡、⼿環等貼身物件，或是機票、貼紙等紀念品，尺⼨需為⻑30x寬19cm（約A4），⾼30cm以內，可帶3-4件物品視現場拍攝效果篩選調整。請盡量挑選物件局部有透明或半透明、能透光的物件，拍攝效果較佳，例如很薄的葉⼦、錄⾳帶、燈泡、塑膠透明⽔壺等。【活動場次】開幕特別場｜3月22日（六）14:00-15:00、15:30-16:30青少年專場｜4月26日（六）18:30-19:30（青少年專場3月24日開放報名）【活動對象】6-12歲小朋友（親子1小+1大），每場次10組人【活動報名與費用】**請穿著舒適、容易伸展之衣物**請事先於本網頁預約報名**活動免費參加，入館請依本館購票辦法購票**如遇颱風等不可抗力之因素，將另行公告是否取消或延期&nbsp;&nbsp;【工作坊網路預約注意事項】2025年3月10日（一）&nbsp;10:00&nbsp;起開放線上報名建議使用電腦操作；手機因版本而異，操作步驟不同不建議使用報名成功後，系統會自動發送錄取通知信至e-mail；相關活動通知以e-mail聯繫為準，請務必填寫正確e-mail因系統區別之故，一個e-mail帳號限報名一次(如有2名小朋友，需使用2個不同mail報名)如遇無法參與之情況，請務必事先線上取消或來電告知，將名額釋出給其他參加者。【工作坊報到及現場候補注意事項】工作坊報到活動開始前15分鐘進行報到，請務必準時於兒藝中心諮詢台報到活動開始前5分鐘未報到者，將釋出名額予現場候補之參加者依順序遞補為確保參加品質，工作坊設有年齡及人數限制，報到時請主動提示年齡證明文件（健保卡等），以便現場人員進行驗證&nbsp;現場候補視網路預約報名報到狀況開放現場候補名額，請於地下樓諮詢台填寫候補報名表於每場次活動前30分鐘開放填寫現場候補報名表，活動前5分鐘開始候補程序&nbsp;為確保參加品質，工作坊設有年齡及人數限制，希望每位參與者和我們共同維護工作坊的規範，一同創造豐富的藝術學習經驗。若有以下情況，本館保有取消參加資格之權利：年齡不符工作坊設定、未攜帶年齡證明文件、工作坊未準時報到&nbsp;&nbsp;工作坊帶領老師｜陳含瑜曾任《Voices of Photography攝影之聲》、《藝術觀點ACT》雜誌編輯，現為華梵大學攝影與VR系兼任講師。關注日常生活中積累的身體感受，如何在時空的縫隙間產生意象。創作以影像為主體，媒材形式橫跨紀錄片、攝影、空間裝置與書本，藉由不同形式、材料的編輯剪接，嘗試其時延的意義與可能。喜歡藉由駐地短居的過程中，探索人與地方之間的關係、情感與記憶，漂流與歸屬的相互拉扯，尋找其詩意、傳說以及精神的所在。&nbsp; #教育', '臺北市立美術館', '無資料', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A927C823823AB53D', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「靜‧物」開幕特別活動｜Photogram物件投影：和我⼀起⽣活的夥伴', `description`='「靜‧物」開幕特別活動：Photogram物件投影傳統的「實物投影」是一種不需要相機拍攝的影像製作方式，只需把要塑造影像的物件直接放在感光相紙上曝光，之後再進行正常沖洗的暗房工作。本次工作坊配合「靜．物」展覽，以「和我一起生活的夥伴」為主題，使用數位方式製作實物投影，並加入其他材質與繪畫的元素，創造屬於自己的靜物作品。物件主題｜和我⼀起⽣活的夥伴請攜帶與記憶有關的物件，可以帶小孩的玩具或是喜歡的玩具、陪伴成⻑的物品、收藏物件，也可以帶乳⽛、眼鏡、⼿環等貼身物件，或是機票、貼紙等紀念品，尺⼨需為⻑30x寬19cm（約A4），⾼30cm以內，可帶3-4件物品視現場拍攝效果篩選調整。請盡量挑選物件局部有透明或半透明、能透光的物件，拍攝效果較佳，例如很薄的葉⼦、錄⾳帶、燈泡、塑膠透明⽔壺等。【活動場次】開幕特別場｜3月22日（六）14:00-15:00、15:30-16:30青少年專場｜4月26日（六）18:30-19:30（青少年專場3月24日開放報名）【活動對象】6-12歲小朋友（親子1小+1大），每場次10組人【活動報名與費用】**請穿著舒適、容易伸展之衣物**請事先於本網頁預約報名**活動免費參加，入館請依本館購票辦法購票**如遇颱風等不可抗力之因素，將另行公告是否取消或延期&nbsp;&nbsp;【工作坊網路預約注意事項】2025年3月10日（一）&nbsp;10:00&nbsp;起開放線上報名建議使用電腦操作；手機因版本而異，操作步驟不同不建議使用報名成功後，系統會自動發送錄取通知信至e-mail；相關活動通知以e-mail聯繫為準，請務必填寫正確e-mail因系統區別之故，一個e-mail帳號限報名一次(如有2名小朋友，需使用2個不同mail報名)如遇無法參與之情況，請務必事先線上取消或來電告知，將名額釋出給其他參加者。【工作坊報到及現場候補注意事項】工作坊報到活動開始前15分鐘進行報到，請務必準時於兒藝中心諮詢台報到活動開始前5分鐘未報到者，將釋出名額予現場候補之參加者依順序遞補為確保參加品質，工作坊設有年齡及人數限制，報到時請主動提示年齡證明文件（健保卡等），以便現場人員進行驗證&nbsp;現場候補視網路預約報名報到狀況開放現場候補名額，請於地下樓諮詢台填寫候補報名表於每場次活動前30分鐘開放填寫現場候補報名表，活動前5分鐘開始候補程序&nbsp;為確保參加品質，工作坊設有年齡及人數限制，希望每位參與者和我們共同維護工作坊的規範，一同創造豐富的藝術學習經驗。若有以下情況，本館保有取消參加資格之權利：年齡不符工作坊設定、未攜帶年齡證明文件、工作坊未準時報到&nbsp;&nbsp;工作坊帶領老師｜陳含瑜曾任《Voices of Photography攝影之聲》、《藝術觀點ACT》雜誌編輯，現為華梵大學攝影與VR系兼任講師。關注日常生活中積累的身體感受，如何在時空的縫隙間產生意象。創作以影像為主體，媒材形式橫跨紀錄片、攝影、空間裝置與書本，藉由不同形式、材料的編輯剪接，嘗試其時延的意義與可能。喜歡藉由駐地短居的過程中，探索人與地方之間的關係、情感與記憶，漂流與歸屬的相互拉扯，尋找其詩意、傳說以及精神的所在。&nbsp; #教育', `organizer`='臺北市立美術館', `address`='無資料', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A927C823823AB53D', `image_url`='[]';
