INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9364538', '團體預約導覽｜「靜‧物」', '團體預約導覽｜「靜‧物」場次時間｜每週三、四 上午10:00-11:00，50-60分鐘注意事項｜場次開始時間超過20分鐘未到地下樓服務台報到，本館將自動取消預約資格，請團體自行參觀活動對象｜10～30人團體集合地點｜地下樓諮詢中心前活動費用｜免費，入館請依本館購票辦法購票報名方式｜網路預約報名，團體須至少於活動前7日預約&nbsp;免票申請臺北市公私立學校團體或美術相關科系如需免票參觀，請下載本頁附件申請表，並於參訪7日前提出並完成申請，表格填妥後請傳真至02-2585-1041，或將掃描檔電郵至：edu_info-tfam,gov.taipei。傳送後敬請來電02-2595-7656分機307，確認本館是否確實收到文件。預約團體報到及入場注意事項為配合入館驗票與寄物，以及讓團體喝水及上廁所，建議提前10分鐘抵達本館。預約報名時，可於備註欄位填寫孩子年齡（混齡者請備註填寫最多數人年齡，以便導覽老師依年齡調整內容）。如有申請免票參觀，團體到齊後請告知1F驗票口人員，以核對團體參觀名冊；若無申請免票參觀，則比照一般觀眾各自購票入館。*團體預約導覽設有人數限制，希望每位參與者和我們共同維護美術館參觀品質，一同創造豐富的藝術學習經驗。&nbsp; #教育', '臺北市立美術館', '無資料', '2025-04-09 00:00:00', '2025-08-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=CA1948CAD9D632A6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='團體預約導覽｜「靜‧物」', `description`='團體預約導覽｜「靜‧物」場次時間｜每週三、四 上午10:00-11:00，50-60分鐘注意事項｜場次開始時間超過20分鐘未到地下樓服務台報到，本館將自動取消預約資格，請團體自行參觀活動對象｜10～30人團體集合地點｜地下樓諮詢中心前活動費用｜免費，入館請依本館購票辦法購票報名方式｜網路預約報名，團體須至少於活動前7日預約&nbsp;免票申請臺北市公私立學校團體或美術相關科系如需免票參觀，請下載本頁附件申請表，並於參訪7日前提出並完成申請，表格填妥後請傳真至02-2585-1041，或將掃描檔電郵至：edu_info-tfam,gov.taipei。傳送後敬請來電02-2595-7656分機307，確認本館是否確實收到文件。預約團體報到及入場注意事項為配合入館驗票與寄物，以及讓團體喝水及上廁所，建議提前10分鐘抵達本館。預約報名時，可於備註欄位填寫孩子年齡（混齡者請備註填寫最多數人年齡，以便導覽老師依年齡調整內容）。如有申請免票參觀，團體到齊後請告知1F驗票口人員，以核對團體參觀名冊；若無申請免票參觀，則比照一般觀眾各自購票入館。*團體預約導覽設有人數限制，希望每位參與者和我們共同維護美術館參觀品質，一同創造豐富的藝術學習經驗。&nbsp; #教育', `organizer`='臺北市立美術館', `address`='無資料', `start_date`='2025-04-09 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=CA1948CAD9D632A6', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9364537', '「靜‧物」故事日', '「靜‧物」故事日地點｜兒藝中心大工作坊對象｜適合4-7 歲親子觀眾人數｜每場次8組（不須事先報名，現場額滿為止，每組至多3人，其中須含至少1位成人陪同）參加方式｜免費參加，入館請依本館購票辦法購票時間｜雙週六（日期偶數日）上午10:00-11:00，50-60分鐘場次時間4/12、4/26、5/10、5/24、6/14、6/28、7/12、7/26、8/2、8/16、8/30活動介紹位每個藝術家都畫過或畫過靜物場景。也許是一盤水果、一個玩具、一瓶花，或是一張椅子。唯一的規則是......靜物畫必須保持靜止不動！但如果沒有呢？保持靜止真的很難，尤其是對於一隻好奇的老鼠、一條飢餓的龍和一位認真的公主。有人會注意到他的靜物畫違反了所有規則嗎？邀請大小朋友，透過繪本故事，一起來重新定義「靜物畫」。什麼事靜物呢？歡迎一起來參加。&nbsp;本活動不需事先報名，請務必於活動開始5-10分鐘前抵達，因場地空間有限，活動準時開始。​​​​​​&nbsp; #教育', '臺北市立美術館', '無資料', '2025-04-12 00:00:00', '2025-08-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B3353573753131A6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「靜‧物」故事日', `description`='「靜‧物」故事日地點｜兒藝中心大工作坊對象｜適合4-7 歲親子觀眾人數｜每場次8組（不須事先報名，現場額滿為止，每組至多3人，其中須含至少1位成人陪同）參加方式｜免費參加，入館請依本館購票辦法購票時間｜雙週六（日期偶數日）上午10:00-11:00，50-60分鐘場次時間4/12、4/26、5/10、5/24、6/14、6/28、7/12、7/26、8/2、8/16、8/30活動介紹位每個藝術家都畫過或畫過靜物場景。也許是一盤水果、一個玩具、一瓶花，或是一張椅子。唯一的規則是......靜物畫必須保持靜止不動！但如果沒有呢？保持靜止真的很難，尤其是對於一隻好奇的老鼠、一條飢餓的龍和一位認真的公主。有人會注意到他的靜物畫違反了所有規則嗎？邀請大小朋友，透過繪本故事，一起來重新定義「靜物畫」。什麼事靜物呢？歡迎一起來參加。&nbsp;本活動不需事先報名，請務必於活動開始5-10分鐘前抵達，因場地空間有限，活動準時開始。​​​​​​&nbsp; #教育', `organizer`='臺北市立美術館', `address`='無資料', `start_date`='2025-04-12 00:00:00', `end_date`='2025-08-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B3353573753131A6', `image_url`='[]';
