INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9359243', '臺北市立圖書館「臺北拾光－臺北市老照片徵集成果展」歡迎參加！', '活動宗旨：藉由臺北市老照片的徵集、整理、保存、數位典藏及展覽等作業，使臺北市的歷史影像資料，得以永久留存，增進臺北市在地資料的應用與推廣效能。活動地點：臺北市立文獻館樹心會館﹙地址：臺北市萬華區中華路1段174－2號﹚報名方式：自由參加。活動內容：◎展覽主題：臺北拾光－臺北市老照片徵集成果展臺北建城以來，隨著時代變遷，從清領時期的奠基、日治時期的現代化發展，到戰後都市化的迅速推進，每一個階段都留下了獨特的城市記憶。本次展覽透過珍貴的老照片，記錄臺北不同時期的街景、建築與人文風貌，帶領觀眾回溯這座城市的歷史軌跡。本次展出內容涵蓋繁華一時的中華商場、南門市場的熱鬧景象、西門町電影街的人潮，以及松山機場、臺北車站、松山火車站的交通發展。中山橋、光復橋、雙園堤防等影像見證了通行要道變遷。政治大學、大龍峒公學校、東園國小、景美女中等學校舊照，呈現學子的求學時光。總統府閱兵、市政府大樓等影像則勾勒城市政治發展。艋舺龍山寺、大稻埕、臺北府城東門，東和禪寺鐘樓等歷史建築展現文化脈絡，臺北臺灣神社影像則見證圓山飯店舊址的變遷。薙刀課、電報課記錄日治教育風貌。人物方面，黃啟瑞市長、李登輝總統視察舊照，1975年蔣公移靈，串聯政經與歷史變遷核心記憶。臺北歷史如鵬，時而振翅高翔，時而羽落於塵世，與藍天並存。羽毛輕盈散落在城市的角落，留下繁華與變遷的印記。我們透過老照片拾起這些羽毛，探尋其中蘊藏的歷史軌跡，感受曾經輝煌、轉身蛻變的城市風貌。◎「拾光映像」影片欣賞，當日場次影片重複輪播(10:00~17:00)3/15（六）臺灣人文之旅：臺北市系列－萬華區3/16（日）臺灣人文之旅：臺北市系列－萬華區、城內3/17（一）臺灣人文之旅：臺北市系列－城內（中正區）3/18（二）臺灣人文之旅：臺北市系列－大稻埕（大同區）3/19（三）臺灣人文之旅：臺北市系列－士林區3/20（四）臺灣人文之旅：臺北市系列－北投區3/21（五）臺灣人文之旅：臺北市系列－中山區3/22（六）臺灣人文之旅：臺北市系列－內湖、松山、信義區3/23（日）臺灣人文之旅：臺北市系列－南港、大安區3/24（一）臺灣人文之旅：臺北市系列－文山區3/25（二）臺北我城．文學散步3/26（三）傳說中的城牆石－紀錄片暨活動集錦3/27（四）瘋臺灣第7季：陽明山國家公園3/28（五）發現臺北願景臺北：社區影像全紀錄(第一集)3/29（六）發現臺北願景臺北：社區影像全紀錄(第二集)3/30（日）臺北城二甲子:2004市政影片精彩集錦◎「拾光書影」主題書展主題：展示記載臺北今昔相關圖書地點：樹心會館交通路線：公車路線：(路線若有修改，請利用臺北市大眾運輸及公車路線查詢系統查詢最新資訊) 可搭乘 9、49、綠17至長沙街站下車直走。&nbsp;捷運路線：可搭乘淡水線至捷運西門站下車，1號出口右轉直走至長沙街。&nbsp;', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=2CAB4AC4199C2FA4', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺北市立圖書館「臺北拾光－臺北市老照片徵集成果展」歡迎參加！', `description`='活動宗旨：藉由臺北市老照片的徵集、整理、保存、數位典藏及展覽等作業，使臺北市的歷史影像資料，得以永久留存，增進臺北市在地資料的應用與推廣效能。活動地點：臺北市立文獻館樹心會館﹙地址：臺北市萬華區中華路1段174－2號﹚報名方式：自由參加。活動內容：◎展覽主題：臺北拾光－臺北市老照片徵集成果展臺北建城以來，隨著時代變遷，從清領時期的奠基、日治時期的現代化發展，到戰後都市化的迅速推進，每一個階段都留下了獨特的城市記憶。本次展覽透過珍貴的老照片，記錄臺北不同時期的街景、建築與人文風貌，帶領觀眾回溯這座城市的歷史軌跡。本次展出內容涵蓋繁華一時的中華商場、南門市場的熱鬧景象、西門町電影街的人潮，以及松山機場、臺北車站、松山火車站的交通發展。中山橋、光復橋、雙園堤防等影像見證了通行要道變遷。政治大學、大龍峒公學校、東園國小、景美女中等學校舊照，呈現學子的求學時光。總統府閱兵、市政府大樓等影像則勾勒城市政治發展。艋舺龍山寺、大稻埕、臺北府城東門，東和禪寺鐘樓等歷史建築展現文化脈絡，臺北臺灣神社影像則見證圓山飯店舊址的變遷。薙刀課、電報課記錄日治教育風貌。人物方面，黃啟瑞市長、李登輝總統視察舊照，1975年蔣公移靈，串聯政經與歷史變遷核心記憶。臺北歷史如鵬，時而振翅高翔，時而羽落於塵世，與藍天並存。羽毛輕盈散落在城市的角落，留下繁華與變遷的印記。我們透過老照片拾起這些羽毛，探尋其中蘊藏的歷史軌跡，感受曾經輝煌、轉身蛻變的城市風貌。◎「拾光映像」影片欣賞，當日場次影片重複輪播(10:00~17:00)3/15（六）臺灣人文之旅：臺北市系列－萬華區3/16（日）臺灣人文之旅：臺北市系列－萬華區、城內3/17（一）臺灣人文之旅：臺北市系列－城內（中正區）3/18（二）臺灣人文之旅：臺北市系列－大稻埕（大同區）3/19（三）臺灣人文之旅：臺北市系列－士林區3/20（四）臺灣人文之旅：臺北市系列－北投區3/21（五）臺灣人文之旅：臺北市系列－中山區3/22（六）臺灣人文之旅：臺北市系列－內湖、松山、信義區3/23（日）臺灣人文之旅：臺北市系列－南港、大安區3/24（一）臺灣人文之旅：臺北市系列－文山區3/25（二）臺北我城．文學散步3/26（三）傳說中的城牆石－紀錄片暨活動集錦3/27（四）瘋臺灣第7季：陽明山國家公園3/28（五）發現臺北願景臺北：社區影像全紀錄(第一集)3/29（六）發現臺北願景臺北：社區影像全紀錄(第二集)3/30（日）臺北城二甲子:2004市政影片精彩集錦◎「拾光書影」主題書展主題：展示記載臺北今昔相關圖書地點：樹心會館交通路線：公車路線：(路線若有修改，請利用臺北市大眾運輸及公車路線查詢系統查詢最新資訊) 可搭乘 9、49、綠17至長沙街站下車直走。&nbsp;捷運路線：可搭乘淡水線至捷運西門站下車，1號出口右轉直走至長沙街。&nbsp;', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=2CAB4AC4199C2FA4', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9363221', '廣慈分館「悅讀人生讀書會」，歡迎參加！', '一、活動目的透過讀書會匯集對閱讀與分享有興趣之讀者，期盼藉由文本賞析與互動討論深化學習，達到豐富知識與自我成長之目的。二、活動內容由讀書會帶領人及成員共同討論及分享閱讀書目相關之主題與個人想法。三、活動時間3/7、3/21、4/11、4/25、5/9、5/23、6/6、6/20、7/4、7/18，星期五下午4：30〜6：30。（時間若因故調整，將事先公告於本館服務臺公布欄與臉書粉專）四、活動地點臺北市立圖書館廣慈分館4樓多功能活動室。﹙地址：臺北市信義區福德街86號4樓﹚五、讀書會帶領人丁碧慧 老師。六、參加對象凡對閱讀與分享有興趣之讀者皆可參加。七、報名方式自由參加，無需報名。八、交通方式[連結]九、本分館保留活動詮釋、異動之權利，如有內容更動，以分館公告為主。', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-07-18 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=6C86F715C1074533', '[]') ON DUPLICATE KEY UPDATE `activity_name`='廣慈分館「悅讀人生讀書會」，歡迎參加！', `description`='一、活動目的透過讀書會匯集對閱讀與分享有興趣之讀者，期盼藉由文本賞析與互動討論深化學習，達到豐富知識與自我成長之目的。二、活動內容由讀書會帶領人及成員共同討論及分享閱讀書目相關之主題與個人想法。三、活動時間3/7、3/21、4/11、4/25、5/9、5/23、6/6、6/20、7/4、7/18，星期五下午4：30〜6：30。（時間若因故調整，將事先公告於本館服務臺公布欄與臉書粉專）四、活動地點臺北市立圖書館廣慈分館4樓多功能活動室。﹙地址：臺北市信義區福德街86號4樓﹚五、讀書會帶領人丁碧慧 老師。六、參加對象凡對閱讀與分享有興趣之讀者皆可參加。七、報名方式自由參加，無需報名。八、交通方式[連結]九、本分館保留活動詮釋、異動之權利，如有內容更動，以分館公告為主。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-07-18 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=6C86F715C1074533', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9361975', '永春分館「平凡中的不平凡」人物傳記館藏特色主題書展', '希望透過小人物的故事，展現臺灣各行各業、不同背景的平凡人如何在生活中堅持夢想、面對挑戰與創造改變。他們的經歷也許不為人知，但卻是構成臺灣社會的基石，代表著勇氣、毅力與人性光輝。永春分館將展出一系列相關傳記書籍，帶您瞭解他們背後的故事。歡迎各位愛書人到館閱覽與借閱！活動對象：一般民眾活動日期：自3月1日起至4月30日止活動地點：臺北市立圖書館永春分館館藏特色書展區（臺北市信義區松山路294號4樓）', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A5D7D41EB5F2A06C', '[]') ON DUPLICATE KEY UPDATE `activity_name`='永春分館「平凡中的不平凡」人物傳記館藏特色主題書展', `description`='希望透過小人物的故事，展現臺灣各行各業、不同背景的平凡人如何在生活中堅持夢想、面對挑戰與創造改變。他們的經歷也許不為人知，但卻是構成臺灣社會的基石，代表著勇氣、毅力與人性光輝。永春分館將展出一系列相關傳記書籍，帶您瞭解他們背後的故事。歡迎各位愛書人到館閱覽與借閱！活動對象：一般民眾活動日期：自3月1日起至4月30日止活動地點：臺北市立圖書館永春分館館藏特色書展區（臺北市信義區松山路294號4樓）', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A5D7D41EB5F2A06C', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9361970', '《貪書蛇@北投分館》借書抽北投分館明信片', '凡於活動期間內，使用自助借書機或手機APP在北投分館借閱書籍/視聽資料，即可至服務臺抽取一張北投分館明信片！一、活動時間：3月1日至12月31日二、活動地點：北投分館1樓服務臺三、注意事項：(一)、當日單張借書證限參加活動一次。(二)、請於櫃檯服務時間內參加活動。（週二至週六下午8：30前；週日及週一下午4：30前）(三)、本館保留修改、終止、變更活動內容細節之權力。三、交通路線：https://reurl.cc/lQxVAq四、更多活動內容請見北投分館臉書粉絲專頁：https://www.facebook.com/BeitouBranch/', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-12-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=E9B33EEA96C4B34F', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《貪書蛇@北投分館》借書抽北投分館明信片', `description`='凡於活動期間內，使用自助借書機或手機APP在北投分館借閱書籍/視聽資料，即可至服務臺抽取一張北投分館明信片！一、活動時間：3月1日至12月31日二、活動地點：北投分館1樓服務臺三、注意事項：(一)、當日單張借書證限參加活動一次。(二)、請於櫃檯服務時間內參加活動。（週二至週六下午8：30前；週日及週一下午4：30前）(三)、本館保留修改、終止、變更活動內容細節之權力。三、交通路線：https://reurl.cc/lQxVAq四、更多活動內容請見北投分館臉書粉絲專頁：https://www.facebook.com/BeitouBranch/', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=E9B33EEA96C4B34F', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9361958', '景新分館「書香集點禮相隨」借閱集點兌獎活動', '活動內容：　　在圖書館借書，充實自我的同時還可以兌換獎品？今年3月來景新分館借書，只要當天以自助借書機或手機借書借閱累積10件館藏（含浮動館藏區圖書），就可至7樓服務臺領取集點卡並蓋章，集滿5個章再加上閱讀存摺點數，即可兌換精美禮物！不同禮物所需點數不同，禮物清單及兌換方式請至洽7樓服務臺。禮物數量有限，兌完為止！活動時間： 3月1日（六）至3月31日（一）活動地點： 景新分館7樓服務臺（臺北市文山區景後街151號7樓）活動注意事項：1.每張借閱證限兌換一份獎品。2.集點卡不得合併計算，兌換後應繳回，不得重複使用。3.本活動限於景新分館兌換，不得跨館兌換。4.本次活動借閱冊數不得與其他活動併計。5.「點閱成金－閱讀存摺」系統說明請參考：https://reurl.cc/oVob7j', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=66BC3919EBD8F6E6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='景新分館「書香集點禮相隨」借閱集點兌獎活動', `description`='活動內容：　　在圖書館借書，充實自我的同時還可以兌換獎品？今年3月來景新分館借書，只要當天以自助借書機或手機借書借閱累積10件館藏（含浮動館藏區圖書），就可至7樓服務臺領取集點卡並蓋章，集滿5個章再加上閱讀存摺點數，即可兌換精美禮物！不同禮物所需點數不同，禮物清單及兌換方式請至洽7樓服務臺。禮物數量有限，兌完為止！活動時間： 3月1日（六）至3月31日（一）活動地點： 景新分館7樓服務臺（臺北市文山區景後街151號7樓）活動注意事項：1.每張借閱證限兌換一份獎品。2.集點卡不得合併計算，兌換後應繳回，不得重複使用。3.本活動限於景新分館兌換，不得跨館兌換。4.本次活動借閱冊數不得與其他活動併計。5.「點閱成金－閱讀存摺」系統說明請參考：https://reurl.cc/oVob7j', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=66BC3919EBD8F6E6', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9361951', '3月1日至6月30日於三民分館舉辦「篆印千秋，刻出方寸間的文化瑰寶」篆刻書展。', '一、活動宗旨：三民分館希望讀者在耳熟能詳的書法外，也能再次認識篆刻藝術之美，特準備一系列篆刻圖書，提供借閱。二、活動內容：展出本館特選「篆刻藝術」圖書約30-50冊。配合本館海報以及市圖電子報和藝文活動的宣傳，廣為告知民眾，歡迎借閱。三、展出日期： 3月1日至6月30日，每日上午9時至下午5時。四、展出地點：臺北市松山區民生東路5段163-1號三民分館5樓展覽室。五、交通路線：https://reurl.cc/aLRjR4', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-06-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=158892E9C7A8B1A0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月1日至6月30日於三民分館舉辦「篆印千秋，刻出方寸間的文化瑰寶」篆刻書展。', `description`='一、活動宗旨：三民分館希望讀者在耳熟能詳的書法外，也能再次認識篆刻藝術之美，特準備一系列篆刻圖書，提供借閱。二、活動內容：展出本館特選「篆刻藝術」圖書約30-50冊。配合本館海報以及市圖電子報和藝文活動的宣傳，廣為告知民眾，歡迎借閱。三、展出日期： 3月1日至6月30日，每日上午9時至下午5時。四、展出地點：臺北市松山區民生東路5段163-1號三民分館5樓展覽室。五、交通路線：https://reurl.cc/aLRjR4', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=158892E9C7A8B1A0', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9361947', '吉利分館「浮動館藏抽好禮·存摺集點享閱讀」浮動館藏推廣活動，歡迎參加!', '一、活動目的：為鼓勵讀者利用及借閱浮動館藏，特辦理此自助借書推廣活動。二、活動時間：3月1日(六)至5月30日(五)三、活動地點：吉利分館6樓浮動館藏區、永明民眾閱覽室7樓浮動館藏區四、活動辦法：1.凡活動期間內，於吉利分館或永明民眾閱覽室借閱浮動館藏，單次達5本(含)以上者，可獲得閱讀存摺點數20點，並可至服務臺登記當月份抽商品禮券，一個帳號一天登記一次。2.次月5日前抽出得獎者3名，並以電話通知且公告於館內及本分館臉書粉絲專頁。3.得獎者須出示借閱證或身分證供館員核對，並於公告當月份領畢。4,活動期間內，可於閱讀存摺系統上兌換禮物，包含精美杯墊、原子筆、飲料提袋等。五、地址：臺北市北投區立農街一段366號6樓六、聯絡方式：電話:(02)28201633電子信箱:L15@email.tpml.edu.tw七、交通：https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=91DF3FAE1633F461&sms=CFFFC938B352678A', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-05-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=DA2B6F4337D66A5C', '[]') ON DUPLICATE KEY UPDATE `activity_name`='吉利分館「浮動館藏抽好禮·存摺集點享閱讀」浮動館藏推廣活動，歡迎參加!', `description`='一、活動目的：為鼓勵讀者利用及借閱浮動館藏，特辦理此自助借書推廣活動。二、活動時間：3月1日(六)至5月30日(五)三、活動地點：吉利分館6樓浮動館藏區、永明民眾閱覽室7樓浮動館藏區四、活動辦法：1.凡活動期間內，於吉利分館或永明民眾閱覽室借閱浮動館藏，單次達5本(含)以上者，可獲得閱讀存摺點數20點，並可至服務臺登記當月份抽商品禮券，一個帳號一天登記一次。2.次月5日前抽出得獎者3名，並以電話通知且公告於館內及本分館臉書粉絲專頁。3.得獎者須出示借閱證或身分證供館員核對，並於公告當月份領畢。4,活動期間內，可於閱讀存摺系統上兌換禮物，包含精美杯墊、原子筆、飲料提袋等。五、地址：臺北市北投區立農街一段366號6樓六、聯絡方式：電話:(02)28201633電子信箱:L15@email.tpml.edu.tw七、交通：https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=91DF3FAE1633F461&sms=CFFFC938B352678A', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-05-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=DA2B6F4337D66A5C', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9359266', '天母分館「中文讀書會」3月起開放參加，邀您一同樂享閱讀人生！', '&nbsp; &nbsp; &nbsp; 天母分館中文讀書會藉由共同討論選定書籍，分享讀書心得及生活中的點點滴滴，享受「閱讀人生」的樂趣。歡迎喜愛閱讀的您加入！一、時間&nbsp;3月至12月，每週二下午2:00-4:00&nbsp;※停課時間1.逢國定假日、休館日停課2.暑假期間 （7月至8月）停課二、地點天母分館4樓視聽室（臺北市士林區中山北路7段154巷6號4樓）三、對象一般民眾四、參加方式自由入場，無需報名，請於活動時間逕洽讀書會現場成員。　　五、交通資訊https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=50DF61E26C3A0BFA&sms=CFFFC938B352678A六、聯絡方式：（一）電話：2873-6203（二）FB粉專：https://www.facebook.com/tpmltianmulibrary（三）IG：https://www.instagram.com/tianmulibrary/', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-04-13 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=81EBCDA3F66BA9E3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='天母分館「中文讀書會」3月起開放參加，邀您一同樂享閱讀人生！', `description`='&nbsp; &nbsp; &nbsp; 天母分館中文讀書會藉由共同討論選定書籍，分享讀書心得及生活中的點點滴滴，享受「閱讀人生」的樂趣。歡迎喜愛閱讀的您加入！一、時間&nbsp;3月至12月，每週二下午2:00-4:00&nbsp;※停課時間1.逢國定假日、休館日停課2.暑假期間 （7月至8月）停課二、地點天母分館4樓視聽室（臺北市士林區中山北路7段154巷6號4樓）三、對象一般民眾四、參加方式自由入場，無需報名，請於活動時間逕洽讀書會現場成員。　　五、交通資訊https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=50DF61E26C3A0BFA&sms=CFFFC938B352678A六、聯絡方式：（一）電話：2873-6203（二）FB粉專：https://www.facebook.com/tpmltianmulibrary（三）IG：https://www.instagram.com/tianmulibrary/', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=81EBCDA3F66BA9E3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9359258', '天母分館「日文文法讀書會」，邀您一起暢遊日文文法世界！', '&nbsp; &nbsp; &nbsp; 「日文文法讀書會」以基本日文文法與解析為主，輔以日本文化與時事討論，歡迎對日文文法有興趣的民眾一同切磋精進日文能力！一、時間3月至12月，每週一下午3:00-4:50※停課時間1.逢國定假日、休館日停課2.暑假期間（7月至8月）停課二、地點天母分館4樓視聽室（臺北市士林區中山北路7段154巷6號4樓）三、對象一般民眾四、參加方式自由入場，無需報名，請於活動時間逕洽讀書會現場成員。　　五、交通資訊https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=50DF61E26C3A0BFA&sms=CFFFC938B352678A六、聯絡方式：（一）電話：2873-6203（二）FB粉專：https://www.facebook.com/tpmltianmulibrary（三）IG：https://www.instagram.com/tianmulibrary/', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-04-13 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A62A67DC9F49A6E5', '[]') ON DUPLICATE KEY UPDATE `activity_name`='天母分館「日文文法讀書會」，邀您一起暢遊日文文法世界！', `description`='&nbsp; &nbsp; &nbsp; 「日文文法讀書會」以基本日文文法與解析為主，輔以日本文化與時事討論，歡迎對日文文法有興趣的民眾一同切磋精進日文能力！一、時間3月至12月，每週一下午3:00-4:50※停課時間1.逢國定假日、休館日停課2.暑假期間（7月至8月）停課二、地點天母分館4樓視聽室（臺北市士林區中山北路7段154巷6號4樓）三、對象一般民眾四、參加方式自由入場，無需報名，請於活動時間逕洽讀書會現場成員。　　五、交通資訊https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=50DF61E26C3A0BFA&sms=CFFFC938B352678A六、聯絡方式：（一）電話：2873-6203（二）FB粉專：https://www.facebook.com/tpmltianmulibrary（三）IG：https://www.instagram.com/tianmulibrary/', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A62A67DC9F49A6E5', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9359237', '東湖分館「學會溝通」主題書展', '　　在我們的生活中總是充斥著無效溝通，讓我們試著練習溝通技巧、學習如何順利地與他人對話，進而減少衝突並擺脫溝通障礙！一、書展日期：3月1日至3月31日二、書展地點：東湖分館3樓（臺北市內湖區五分街6號）三、書展內容：展出以「溝通技巧」、「說話藝術」為主題的實體書。四、交通方式：https://is.gd/sIDmLV若有任何問題，歡迎來電洽詢(02-26323378)東湖分館。', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=0E6AC76EDE622635', '[]') ON DUPLICATE KEY UPDATE `activity_name`='東湖分館「學會溝通」主題書展', `description`='　　在我們的生活中總是充斥著無效溝通，讓我們試著練習溝通技巧、學習如何順利地與他人對話，進而減少衝突並擺脫溝通障礙！一、書展日期：3月1日至3月31日二、書展地點：東湖分館3樓（臺北市內湖區五分街6號）三、書展內容：展出以「溝通技巧」、「說話藝術」為主題的實體書。四、交通方式：https://is.gd/sIDmLV若有任何問題，歡迎來電洽詢(02-26323378)東湖分館。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=0E6AC76EDE622635', `image_url`='[]';
