INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9356198', '建成分館「雙連2410讀書會-第9期」', '每月精選閱讀一本好書，藉由讀書會分享及討論，賞析圖書內容，交流心得，以拓展學習視野及提升閱讀風氣。一、活動時間：3至6月（3/13、4/10、5/8、6/12）週四上午10:00-12:00二、活動內容：3月13日《我是人生整理師：死亡清掃x遺物整理x囤積歸納》 &nbsp; &nbsp;4月10日《上癮臺灣史：一部400年的島嶼生存角力賽》 &nbsp; &nbsp;5月8日《吃藥前，你必須知道的事：看懂高消費低知識的台灣食藥文化與真相》6月12日《追風箏的孩子》三、活動地點：建成分館多功能活動室。（臺北市大同區民生西路198-20號4樓）[交通資訊連結]四、活動對象：一般民眾，上限10名。五、參加方式：請事先洽服務臺或電話(02-25582320)報名。', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-06-11 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=D08A23FE5B0E183C', '[]') ON DUPLICATE KEY UPDATE `activity_name`='建成分館「雙連2410讀書會-第9期」', `description`='每月精選閱讀一本好書，藉由讀書會分享及討論，賞析圖書內容，交流心得，以拓展學習視野及提升閱讀風氣。一、活動時間：3至6月（3/13、4/10、5/8、6/12）週四上午10:00-12:00二、活動內容：3月13日《我是人生整理師：死亡清掃x遺物整理x囤積歸納》 &nbsp; &nbsp;4月10日《上癮臺灣史：一部400年的島嶼生存角力賽》 &nbsp; &nbsp;5月8日《吃藥前，你必須知道的事：看懂高消費低知識的台灣食藥文化與真相》6月12日《追風箏的孩子》三、活動地點：建成分館多功能活動室。（臺北市大同區民生西路198-20號4樓）[交通資訊連結]四、活動對象：一般民眾，上限10名。五、參加方式：請事先洽服務臺或電話(02-25582320)報名。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-06-11 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=D08A23FE5B0E183C', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9353490', '「水與墨的交織 許玉惠個展」。', '一、活動宗旨：學習欣賞美的事物，讓藝術貼近生活。二、活動內容：菁英獎得主許玉惠擅長在筆墨粗細和水墨濃淡間取得平衡，讓一筆一畫間透過水的張力，展現大自然景物在四季更迭中各自獨特的氣韻。讓觀者彷彿跳脫時光隧道，親臨其境，畫中人物景物，與你同遊。此次展出的30幅作品，篇篇佳作，許女士浸淫水墨畫多年的功力，即是最佳見證。三、畫作素材：水墨顏料、水，宣、棉紙四、展出日期：114年3月1日至3月15日，每日上午9時至下午5時。五、展出地點：臺北市松山區民生東路5段163-1號三民分館5樓展覽室。六、交通路線：https://reurl.cc/aLRjR4', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-03-15 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C90B3FB86E6DAAA7', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「水與墨的交織 許玉惠個展」。', `description`='一、活動宗旨：學習欣賞美的事物，讓藝術貼近生活。二、活動內容：菁英獎得主許玉惠擅長在筆墨粗細和水墨濃淡間取得平衡，讓一筆一畫間透過水的張力，展現大自然景物在四季更迭中各自獨特的氣韻。讓觀者彷彿跳脫時光隧道，親臨其境，畫中人物景物，與你同遊。此次展出的30幅作品，篇篇佳作，許女士浸淫水墨畫多年的功力，即是最佳見證。三、畫作素材：水墨顏料、水，宣、棉紙四、展出日期：114年3月1日至3月15日，每日上午9時至下午5時。五、展出地點：臺北市松山區民生東路5段163-1號三民分館5樓展覽室。六、交通路線：https://reurl.cc/aLRjR4', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C90B3FB86E6DAAA7', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9353397', '【吉利分館】玩拼布手作研習班', '一、活動名稱：【吉利分館】玩拼布手作研習班。二、活動館別：臺北市立圖書館─吉利分館三、活動目的：當針線布及萬能的雙手相遇，是拼布手作的開端，再加上一點巧思與創意，運用手縫拼布技巧即可上手，期望藉此研習班能夠縫製出日常生活中可以使用的美麗作品，創作屬於自己手作獨一無二的生活雜貨，用針線陪伴自己、享受生活！四、活動對象：一般民眾。無須經驗，有興趣最重要，只要跟著老師的步驟，一步一步就能完成作品。歡迎初學者！五、活動時間：114年3月4日到6月17日，每週二下午2：00~4：30六、活動地點：吉利分館多功能活動室七、活動名額：15名，學員需自備針、線、剪刀。八、活動內容：時間週次課程內容3/4第一週相見歡＆課程介紹：長命百歲金龜掛飾零錢包13/11第二週長命百歲金龜掛飾零錢包23/18第三週長命百歲金龜掛飾零錢包33/25第四週長命百歲金龜掛飾零錢包44/1第五週口金零錢包14/8第六週口金零錢包24/15第七週口金包34/22第八週口金包44/29第九週縮口手提、斜背兩用袋1~拼布圖案之運用5/6第十週縮口手提、斜背兩用袋1~拼布圖案之運用5/13第十一週縮口手提、斜背兩用袋1~拼布圖案之運用5/20第十二週縮口手提、斜背兩用袋1~拼布圖案之運用5/27第十三週肩背包1~拼布圖案之運用6/3第十四週肩背包1~拼布圖案之運用6/10第十五週肩背包1~拼布圖案之運用6/17第十六週肩背包1~拼布圖案之運用*上課順序、內容和作品細項老師會因學生學習狀況與進度有可能調整與更動。九、交通：https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=91DF3FAE1633F461&sms=CFFFC938B352678A', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-06-17 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=9F0179617A02DD56', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【吉利分館】玩拼布手作研習班', `description`='一、活動名稱：【吉利分館】玩拼布手作研習班。二、活動館別：臺北市立圖書館─吉利分館三、活動目的：當針線布及萬能的雙手相遇，是拼布手作的開端，再加上一點巧思與創意，運用手縫拼布技巧即可上手，期望藉此研習班能夠縫製出日常生活中可以使用的美麗作品，創作屬於自己手作獨一無二的生活雜貨，用針線陪伴自己、享受生活！四、活動對象：一般民眾。無須經驗，有興趣最重要，只要跟著老師的步驟，一步一步就能完成作品。歡迎初學者！五、活動時間：114年3月4日到6月17日，每週二下午2：00~4：30六、活動地點：吉利分館多功能活動室七、活動名額：15名，學員需自備針、線、剪刀。八、活動內容：時間週次課程內容3/4第一週相見歡＆課程介紹：長命百歲金龜掛飾零錢包13/11第二週長命百歲金龜掛飾零錢包23/18第三週長命百歲金龜掛飾零錢包33/25第四週長命百歲金龜掛飾零錢包44/1第五週口金零錢包14/8第六週口金零錢包24/15第七週口金包34/22第八週口金包44/29第九週縮口手提、斜背兩用袋1~拼布圖案之運用5/6第十週縮口手提、斜背兩用袋1~拼布圖案之運用5/13第十一週縮口手提、斜背兩用袋1~拼布圖案之運用5/20第十二週縮口手提、斜背兩用袋1~拼布圖案之運用5/27第十三週肩背包1~拼布圖案之運用6/3第十四週肩背包1~拼布圖案之運用6/10第十五週肩背包1~拼布圖案之運用6/17第十六週肩背包1~拼布圖案之運用*上課順序、內容和作品細項老師會因學生學習狀況與進度有可能調整與更動。九、交通：https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=91DF3FAE1633F461&sms=CFFFC938B352678A', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-06-17 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=9F0179617A02DD56', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9353361', '三興分館「彩虹讀書會（32）」', '一、活動目的：藉由「閱讀」引領著你我遊歷各類各式精采人生。二、活動內容：閱讀與討論《小王子》、《英倫情人》及《人生圖書館》三本書籍，賞析電影《英倫情人》與參加戶外藝文活動。三、活動時間：3月3日起至6月23日止，每週一下午2時至5時。四、活動地點：臺北市立圖書館三興分館5樓會議室。五、參加對象：凡對閱讀分享有興趣的朋友。六、活動費用：免費。七、報名方式：自由參加。', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-06-23 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=AA76B3010EF0C602', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三興分館「彩虹讀書會（32）」', `description`='一、活動目的：藉由「閱讀」引領著你我遊歷各類各式精采人生。二、活動內容：閱讀與討論《小王子》、《英倫情人》及《人生圖書館》三本書籍，賞析電影《英倫情人》與參加戶外藝文活動。三、活動時間：3月3日起至6月23日止，每週一下午2時至5時。四、活動地點：臺北市立圖書館三興分館5樓會議室。五、參加對象：凡對閱讀分享有興趣的朋友。六、活動費用：免費。七、報名方式：自由參加。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-06-23 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=AA76B3010EF0C602', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9353358', '三興分館「HAPPY讀書會（36）」', '一、活動目的：透過讀書會培養閱讀的習慣，進而提升美麗的人生，共創優質的書香社會。二、活動內容：閱讀與討論《呼吸》、《仲夏夜之夢》兩本書籍，並賞析音樂影視作品《仲夏夜之夢》及參加戶外藝文活動。三、活動時間：3月4日起至6月24日止，每週二上午9時30分至11時30分。四、活動地點：臺北市立圖書館三興分館5樓會議室。五、參加對象：凡對閱讀分享有興趣的朋友。六、活動費用：免費。七、報名方式：自由參加。', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-06-24 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C1439A3D6971D381', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三興分館「HAPPY讀書會（36）」', `description`='一、活動目的：透過讀書會培養閱讀的習慣，進而提升美麗的人生，共創優質的書香社會。二、活動內容：閱讀與討論《呼吸》、《仲夏夜之夢》兩本書籍，並賞析音樂影視作品《仲夏夜之夢》及參加戶外藝文活動。三、活動時間：3月4日起至6月24日止，每週二上午9時30分至11時30分。四、活動地點：臺北市立圖書館三興分館5樓會議室。五、參加對象：凡對閱讀分享有興趣的朋友。六、活動費用：免費。七、報名方式：自由參加。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-06-24 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C1439A3D6971D381', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9352385', '總館北區資源中心「新春刮刮樂，刮出好手氣」，邀您一同閱讀好書，驚喜拿好禮！', '為了推廣北區資源中心館藏，本館特別推出「新春刮刮樂，刮出好手氣！」活動，讓讀者在借閱好書的同時，也能享受遊戲的樂趣，刮出滿滿好運！活動期間只要單次借閱北區資源中心館藏7冊，即可憑借閱紀錄至閱讀存摺平臺兌換刮刮卡1張，每張刮刮卡都藏著精美好禮，讓閱讀變得更加驚喜有趣~快來借書試手氣！一、活動日期：3月1日（六）至3月31日（一）二、活動地點：臺北市立圖書館總館1樓。三、活動內容：（一）自3月1日起讀者使用總館自助借書機或APP之手機借書功能，借閱7冊北區資源中心館藏，憑自助借閱收據或借閱紀錄加總7冊及閱讀存摺點數5點即可兌換刮刮卡1張，數量有限，送完為止，刮刮卡獎品內容如下：獎品內容獎品品項數量「悅讀曆」2025年北市圖桌曆15平面口罩1個80洗手露10造型牙刷架20閱讀存摺點數5點35閱讀存摺點數15點30閱讀存摺點數30點10（二）本活動僅收取總館自助借書機收據，兌獎完之收據將蓋印館戳，不可重複累積兌獎。每人限換取刮刮卡3張，每兌換1張需出示當次借閱紀錄符合資格者方可兌換，如兌換1張需借閱北區資源中心書籍7冊、兌換2張需借閱北區資源中心書籍14冊，以此類推。憑刮刮卡臨櫃兌換刮出獎品（閱讀存摺點數統一於次月10日前匯入），兌換期限至114年3月31日止，請務必於期限內至總館1樓服務臺兌換，逾期將無法兌換。（三）閱讀存摺點數累積方式1.凡臨櫃借閱，每張借閱證借閱1冊（件）可累積1點；凡以自助借書機借閱1冊（件）可累積2點；手機借閱1冊（件）可累積3點；每張借閱證每日借閱圖書資料可累積點數上限為40點，每月累積上限600點（期間限定活動借閱贈點及累積點數上限加倍時除外）。2.借閱圖書資料以本館可外借之圖書資料為認定標準，惟圖書資料之附件、同一館藏當日重複借閱及續借則不予計入。3.活動期間內，閱讀存摺集點方式如有變更，則以本館公告之最新點數累積規則為集點依據。（四）閱讀存摺獎品兌換方式1.讀者利用館藏查詢系統登入個人書房至「點閱成金－閱讀存摺」，點選「閱讀集點」功能，檢視累積點數，選擇欲兌換之獎勵品、兌換地點及數量，再至「待換清單」透過手機產生兌換條碼或持借閱證至兌換地點兌獎。2.讀者兌換獎勵品須於總館櫃檯兌換，不提供跨館領取獎勵品服務。3.活動期間內，閱讀存摺獎品兌換方式如有變更，則以本館公告之最新兌換規則為獎勵品兌換依據。四、交通資訊：詳見https://reurl.cc/aZ0LeY', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F526E5DF645FC937', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館北區資源中心「新春刮刮樂，刮出好手氣」，邀您一同閱讀好書，驚喜拿好禮！', `description`='為了推廣北區資源中心館藏，本館特別推出「新春刮刮樂，刮出好手氣！」活動，讓讀者在借閱好書的同時，也能享受遊戲的樂趣，刮出滿滿好運！活動期間只要單次借閱北區資源中心館藏7冊，即可憑借閱紀錄至閱讀存摺平臺兌換刮刮卡1張，每張刮刮卡都藏著精美好禮，讓閱讀變得更加驚喜有趣~快來借書試手氣！一、活動日期：3月1日（六）至3月31日（一）二、活動地點：臺北市立圖書館總館1樓。三、活動內容：（一）自3月1日起讀者使用總館自助借書機或APP之手機借書功能，借閱7冊北區資源中心館藏，憑自助借閱收據或借閱紀錄加總7冊及閱讀存摺點數5點即可兌換刮刮卡1張，數量有限，送完為止，刮刮卡獎品內容如下：獎品內容獎品品項數量「悅讀曆」2025年北市圖桌曆15平面口罩1個80洗手露10造型牙刷架20閱讀存摺點數5點35閱讀存摺點數15點30閱讀存摺點數30點10（二）本活動僅收取總館自助借書機收據，兌獎完之收據將蓋印館戳，不可重複累積兌獎。每人限換取刮刮卡3張，每兌換1張需出示當次借閱紀錄符合資格者方可兌換，如兌換1張需借閱北區資源中心書籍7冊、兌換2張需借閱北區資源中心書籍14冊，以此類推。憑刮刮卡臨櫃兌換刮出獎品（閱讀存摺點數統一於次月10日前匯入），兌換期限至114年3月31日止，請務必於期限內至總館1樓服務臺兌換，逾期將無法兌換。（三）閱讀存摺點數累積方式1.凡臨櫃借閱，每張借閱證借閱1冊（件）可累積1點；凡以自助借書機借閱1冊（件）可累積2點；手機借閱1冊（件）可累積3點；每張借閱證每日借閱圖書資料可累積點數上限為40點，每月累積上限600點（期間限定活動借閱贈點及累積點數上限加倍時除外）。2.借閱圖書資料以本館可外借之圖書資料為認定標準，惟圖書資料之附件、同一館藏當日重複借閱及續借則不予計入。3.活動期間內，閱讀存摺集點方式如有變更，則以本館公告之最新點數累積規則為集點依據。（四）閱讀存摺獎品兌換方式1.讀者利用館藏查詢系統登入個人書房至「點閱成金－閱讀存摺」，點選「閱讀集點」功能，檢視累積點數，選擇欲兌換之獎勵品、兌換地點及數量，再至「待換清單」透過手機產生兌換條碼或持借閱證至兌換地點兌獎。2.讀者兌換獎勵品須於總館櫃檯兌換，不提供跨館領取獎勵品服務。3.活動期間內，閱讀存摺獎品兌換方式如有變更，則以本館公告之最新兌換規則為獎勵品兌換依據。四、交通資訊：詳見https://reurl.cc/aZ0LeY', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F526E5DF645FC937', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9349908', '永春分館3月「假日電影院」', '一、活動內容：永春分館每週精選優良電影，讓民眾利用假日下午時光，一起走進圖書館，走進電影的繽紛世界。二、活動日期：3月2日起至3月30日止每週日下午1:30起播放三、活動地點：永春分館4樓多功能活動室(臺北市信義區松山路294號4樓)四、播放影片：日期片名分級片長3月2日失控的審判輔15級129分鐘3月9日禍水保護級117分鐘3月16日德士當家保護級92分鐘3月23日豪門幽魂輔12級106分鐘五、參加對象：一般民眾。六、洽詢電話：永春分館﹙02-27609730﹚', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B765790D70CAB746', '[]') ON DUPLICATE KEY UPDATE `activity_name`='永春分館3月「假日電影院」', `description`='一、活動內容：永春分館每週精選優良電影，讓民眾利用假日下午時光，一起走進圖書館，走進電影的繽紛世界。二、活動日期：3月2日起至3月30日止每週日下午1:30起播放三、活動地點：永春分館4樓多功能活動室(臺北市信義區松山路294號4樓)四、播放影片：日期片名分級片長3月2日失控的審判輔15級129分鐘3月9日禍水保護級117分鐘3月16日德士當家保護級92分鐘3月23日豪門幽魂輔12級106分鐘五、參加對象：一般民眾。六、洽詢電話：永春分館﹙02-27609730﹚', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B765790D70CAB746', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9345855', '石牌分館「動畫時光」館藏特色電子資源特展', '動畫作品陪伴許多人度過無數美好時光，本次書展將介紹動畫產業發展史，解析迪士尼的劇本魔法，亦收錄《名偵探柯南》劇場版資料集及新海誠代表作《你的名字》等美術畫集。●活動時間：3月1日至4月30日止●活動地點：石牌分館8樓館藏特色書展區【臺北市北投區明德路208巷5號3-10樓，電話：（02）28239634】●交通路線：聯營公車：奎山國中站（223、267、1801）捷運明德站（淡水信義線）1號出口●書單', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A4E65EF0C5CCE055', '[]') ON DUPLICATE KEY UPDATE `activity_name`='石牌分館「動畫時光」館藏特色電子資源特展', `description`='動畫作品陪伴許多人度過無數美好時光，本次書展將介紹動畫產業發展史，解析迪士尼的劇本魔法，亦收錄《名偵探柯南》劇場版資料集及新海誠代表作《你的名字》等美術畫集。●活動時間：3月1日至4月30日止●活動地點：石牌分館8樓館藏特色書展區【臺北市北投區明德路208巷5號3-10樓，電話：（02）28239634】●交通路線：聯營公車：奎山國中站（223、267、1801）捷運明德站（淡水信義線）1號出口●書單', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A4E65EF0C5CCE055', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9341855', '南港分館「自助借書選好書」 自助借書機推廣活動', '您是否因為趕時間而沒空在櫃檯排隊等待借書呢?利用自助借書機即可輕鬆解決這個問題!南港分館推出「自助借書選好書」活動，使用自助借書機借書並累積閱讀存摺80點，即可憑借閱證明至服務臺兌換精選贈書1本，想知道有哪些精選好書嗎？快來使用自助借書機吧！一、活動時間：3月1日至12月31日。二、活動地點：南港分館1樓服務臺。三、活動對象：一般民眾。四、活動方式：(一)憑活動期間南港分館之自助借書機使用證明（可從市圖官網或手機App之個人書房出示借閱證明）及累積閱讀存摺點數80點兌換，即可挑選本館精選贈書1本，活動獎品數量有限，兌完為止。(二)集點、兌獎方式:請詳閱「臺北市立圖書館閱讀存摺集點及點數兌換說明」。', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-12-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=0BD075C7AC31A07F', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南港分館「自助借書選好書」 自助借書機推廣活動', `description`='您是否因為趕時間而沒空在櫃檯排隊等待借書呢?利用自助借書機即可輕鬆解決這個問題!南港分館推出「自助借書選好書」活動，使用自助借書機借書並累積閱讀存摺80點，即可憑借閱證明至服務臺兌換精選贈書1本，想知道有哪些精選好書嗎？快來使用自助借書機吧！一、活動時間：3月1日至12月31日。二、活動地點：南港分館1樓服務臺。三、活動對象：一般民眾。四、活動方式：(一)憑活動期間南港分館之自助借書機使用證明（可從市圖官網或手機App之個人書房出示借閱證明）及累積閱讀存摺點數80點兌換，即可挑選本館精選贈書1本，活動獎品數量有限，兌完為止。(二)集點、兌獎方式:請詳閱「臺北市立圖書館閱讀存摺集點及點數兌換說明」。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=0BD075C7AC31A07F', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9341851', '總館「她者困境」熱門主題書展', '本次展覽以「她者困境」為主題，專注於現代社會中女性角色所面臨的性別議題與社會挑戰，展出女性在當代生活中如何應對多重身分與社會期望的矛盾，如何在傳統觀念與新興價值觀之間尋找平衡，並努力打破性別限制，實現自我價值，並引發讀者對於性別平等與社會正義的深入思考。本館舉辦「她者困境」主題書展，為您展出本館典藏身處各種角色的女性面臨社會及性別議題之主題圖書，歡迎您到館閱覽，亦推薦利用本館Ebook Taipei電子書。時間：3月1日至4月30日地點：總館1樓書展區(臺北市建國南路2段125號)Ebook Taipei‧臺北好讀電子書平臺網址：https://tpml.ebook.hyread.com.tw/操作方式：點選「登入」，輸入北市圖帳號密碼，即可上線閱讀。※平板電腦及手機等載具，建議可先免費下載HyRead Library APP', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=57911CEB887173A4', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館「她者困境」熱門主題書展', `description`='本次展覽以「她者困境」為主題，專注於現代社會中女性角色所面臨的性別議題與社會挑戰，展出女性在當代生活中如何應對多重身分與社會期望的矛盾，如何在傳統觀念與新興價值觀之間尋找平衡，並努力打破性別限制，實現自我價值，並引發讀者對於性別平等與社會正義的深入思考。本館舉辦「她者困境」主題書展，為您展出本館典藏身處各種角色的女性面臨社會及性別議題之主題圖書，歡迎您到館閱覽，亦推薦利用本館Ebook Taipei電子書。時間：3月1日至4月30日地點：總館1樓書展區(臺北市建國南路2段125號)Ebook Taipei‧臺北好讀電子書平臺網址：https://tpml.ebook.hyread.com.tw/操作方式：點選「登入」，輸入北市圖帳號密碼，即可上線閱讀。※平板電腦及手機等載具，建議可先免費下載HyRead Library APP', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=57911CEB887173A4', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9338058', '吉利分館「唭哩岸電影院」邀您與親朋好友共同觀賞系列好片~~', '為成為社區民眾休閒的好去處，吉利分館「唭哩岸電影院」特於3-4月精選各種類型影片供民眾觀賞。歡迎大家扶老攜幼，到館欣賞精采好片。一、活動對象：一般民眾二、報名方式：無需報名三、活動費用：無四、活動地點：吉利分館7樓多功能活動室（臺北市北投區立農街一段366號7樓，請由6樓進入）五、活動日期與內容：每月第2、4個星期日上午10：00起播放日期片名級別片長3月9日蜘蛛人驚奇再起保護級136分3月23日自殺突擊隊輔12級123分4月13日愛.重來保護級104分4月27日非誠勿擾普遍級125分六、交通：https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=91DF3FAE1633F461&sms=CFFFC938B352678A', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=6C539623A013E953', '[]') ON DUPLICATE KEY UPDATE `activity_name`='吉利分館「唭哩岸電影院」邀您與親朋好友共同觀賞系列好片~~', `description`='為成為社區民眾休閒的好去處，吉利分館「唭哩岸電影院」特於3-4月精選各種類型影片供民眾觀賞。歡迎大家扶老攜幼，到館欣賞精采好片。一、活動對象：一般民眾二、報名方式：無需報名三、活動費用：無四、活動地點：吉利分館7樓多功能活動室（臺北市北投區立農街一段366號7樓，請由6樓進入）五、活動日期與內容：每月第2、4個星期日上午10：00起播放日期片名級別片長3月9日蜘蛛人驚奇再起保護級136分3月23日自殺突擊隊輔12級123分4月13日愛.重來保護級104分4月27日非誠勿擾普遍級125分六、交通：https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=91DF3FAE1633F461&sms=CFFFC938B352678A', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=6C539623A013E953', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9337686', '歡迎加入天母分館「英文聊天室」，一起說英語！', '&nbsp; &nbsp; 天母分館「英文聊天室」每週選定不同主題，參與者針對主題使用英語交流分享，以提升英文語感，精進英語能力。歡迎加入我們，讓你不再害怕開口說英文！一、時間&nbsp; 114年3月至12月，每週五下午1:30-3:00※停課時間1. 逢國定假日、休館日停課2. 7月4日至7月25日停課二、地點天母分館4樓視聽室（臺北市士林區中山北路7段154巷6號4樓）三、對象具一定英語聽說能力之民眾四、參加方式自由入場，無需事先報名，請於活動時間逕洽讀書會現場成員五、交通資訊https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=50DF61E26C3A0BFA&sms=CFFFC938B352678A六、聯絡方式（一）電話：2873-6203（二）FB粉專：https://www.facebook.com/tpmltianmulibrary（三）IG：https://www.instagram.com/tianmulibrary/', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-05-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=E8B15522F565DF04', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歡迎加入天母分館「英文聊天室」，一起說英語！', `description`='&nbsp; &nbsp; 天母分館「英文聊天室」每週選定不同主題，參與者針對主題使用英語交流分享，以提升英文語感，精進英語能力。歡迎加入我們，讓你不再害怕開口說英文！一、時間&nbsp; 114年3月至12月，每週五下午1:30-3:00※停課時間1. 逢國定假日、休館日停課2. 7月4日至7月25日停課二、地點天母分館4樓視聽室（臺北市士林區中山北路7段154巷6號4樓）三、對象具一定英語聽說能力之民眾四、參加方式自由入場，無需事先報名，請於活動時間逕洽讀書會現場成員五、交通資訊https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=50DF61E26C3A0BFA&sms=CFFFC938B352678A六、聯絡方式（一）電話：2873-6203（二）FB粉專：https://www.facebook.com/tpmltianmulibrary（三）IG：https://www.instagram.com/tianmulibrary/', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=E8B15522F565DF04', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9331538', '木柵分館「樂活玩手作讀書會」，歡迎您的加入!', '利用圖書館豐富的家政及手藝類圖書，由讀書會帶領人專業個別指導，學習縫紉及手作技巧，製作專屬的手拿包、零錢包、小吊飾、手機袋等手工縫紉製品，在研習中精進技術、發揮創意，從手作藝品中領略閱讀及生活樂趣。活動日期：3-12月每月第2、4個週二下午2時至4時 (暑假7、8月暫停)活動對象：一般民眾(須自備材料)活動地點：臺北市立圖書館木柵分館視聽室（臺北市文山區保儀路13巷3號4樓）報名方式：無需事先報名，於活動時間至本分館4樓視聽室參與即可。', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-12-23 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8C3556CF55AD8810', '[]') ON DUPLICATE KEY UPDATE `activity_name`='木柵分館「樂活玩手作讀書會」，歡迎您的加入!', `description`='利用圖書館豐富的家政及手藝類圖書，由讀書會帶領人專業個別指導，學習縫紉及手作技巧，製作專屬的手拿包、零錢包、小吊飾、手機袋等手工縫紉製品，在研習中精進技術、發揮創意，從手作藝品中領略閱讀及生活樂趣。活動日期：3-12月每月第2、4個週二下午2時至4時 (暑假7、8月暫停)活動對象：一般民眾(須自備材料)活動地點：臺北市立圖書館木柵分館視聽室（臺北市文山區保儀路13巷3號4樓）報名方式：無需事先報名，於活動時間至本分館4樓視聽室參與即可。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-12-23 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8C3556CF55AD8810', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9327653', '文山分館「文山週四電影院」3月節目表', '文山分館每月雙週四精選電影放映，提供民眾休憩和充電的好去處。歡迎來到圖書館度過愉快的電影時光！一、活動時間：每月雙週四下午1：30起放映。二、播映影片：3月13日：7號房的禮物（護）127分由柳承龍、朴信惠主演的韓國電影。故事描述一名有智能障礙的中年男子，蒙受不白之冤而入獄，與6歲女兒在獄中的感人故事。3月27日：大雨大雨一直下（普）87分法國動畫，本片榮獲柏林影展最佳動畫大獎。三、活動地點：臺北市立圖書館文山分館9樓多功能活動室。(臺北市文山區興隆路2段160號，電話：2931-5339)四、注意事項：&nbsp;本活動免費參加，入場請遵守影片分級制度。', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-03-27 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B5438FAAA89908A9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='文山分館「文山週四電影院」3月節目表', `description`='文山分館每月雙週四精選電影放映，提供民眾休憩和充電的好去處。歡迎來到圖書館度過愉快的電影時光！一、活動時間：每月雙週四下午1：30起放映。二、播映影片：3月13日：7號房的禮物（護）127分由柳承龍、朴信惠主演的韓國電影。故事描述一名有智能障礙的中年男子，蒙受不白之冤而入獄，與6歲女兒在獄中的感人故事。3月27日：大雨大雨一直下（普）87分法國動畫，本片榮獲柏林影展最佳動畫大獎。三、活動地點：臺北市立圖書館文山分館9樓多功能活動室。(臺北市文山區興隆路2段160號，電話：2931-5339)四、注意事項：&nbsp;本活動免費參加，入場請遵守影片分級制度。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-27 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B5438FAAA89908A9', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9314958', '六合分館：「閱讀悅心」主題書展（3月運動健身）', '活動名稱：114 年度「閱讀悅心」主題書展（3月運動健身）活動宗旨：將於每月設定主題書展，將相關書籍展出，不僅鼓勵讀者踴躍借閱書籍，也讓民眾享受愉快閱讀好時光，使讀者達愉悅身心之效。活動時間：3月1日起至3月31日。活動對象：一般民眾。活動內容：這次書展以「運動健身」為主題，帶您開啟健康生活之旅！我們精選各類運動、體能訓練、營養知識及心靈健康書籍，從基礎入門到進階提升，無論您是健身新手或運動愛好者，都能在此找到專業建議與靈感，助您塑造理想的健康體魄！活動地點：臺北市立圖書館六合分館（地址：臺北市信義區松仁路240巷19號4樓，若有相關問題歡迎來電洽詢，電話：2729-2485）交通路線：交通路線', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C24D6EA9AAC5B0BB', '[]') ON DUPLICATE KEY UPDATE `activity_name`='六合分館：「閱讀悅心」主題書展（3月運動健身）', `description`='活動名稱：114 年度「閱讀悅心」主題書展（3月運動健身）活動宗旨：將於每月設定主題書展，將相關書籍展出，不僅鼓勵讀者踴躍借閱書籍，也讓民眾享受愉快閱讀好時光，使讀者達愉悅身心之效。活動時間：3月1日起至3月31日。活動對象：一般民眾。活動內容：這次書展以「運動健身」為主題，帶您開啟健康生活之旅！我們精選各類運動、體能訓練、營養知識及心靈健康書籍，從基礎入門到進階提升，無論您是健身新手或運動愛好者，都能在此找到專業建議與靈感，助您塑造理想的健康體魄！活動地點：臺北市立圖書館六合分館（地址：臺北市信義區松仁路240巷19號4樓，若有相關問題歡迎來電洽詢，電話：2729-2485）交通路線：交通路線', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C24D6EA9AAC5B0BB', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9304152', '總館視聽室「表演藝術同樂會」3月節目表', '活動地點：總館8樓團體欣賞室活動時間：上午9:30-12:00(結束時間視節目長短而定)洽詢電話：2755-2823分機2801、2802參加方式：不需報名，免費自由入場(非講座)場次內容：1. 3/15(六) 09:30-羊毛與千葉花（演唱會）114分鐘2013年10月於天王洲銀河劇場舉辦的10周年紀念演唱會，首次以Live DVD的形式記錄下來，獻給廣大歌迷。會場內洋溢著溫暖而美好的氛圍，豪華伴奏陣容攜手創造出一場極致的音樂盛宴。每一個音符都彷彿在空氣中流淌，讓人沉浸在美妙的旋律中。2. 3/22(六) 09:30-斜坡上的老歌手（紀錄片）79分鐘隨著旋律在舞臺上下穿梭，歲月飛逝，見證了包曉娟與謝英雄的輝煌時刻。在族語的呢喃中，我們感受到藍石化對古謠堅持的深刻情感。最後一曲《乾杯》則激盪出製作人魏榮貴的不老樂團的精神，儘管微醺，他們對音樂的熱情依然如故，令人動容。', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-03-22 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=BDBE44A21382E309', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館視聽室「表演藝術同樂會」3月節目表', `description`='活動地點：總館8樓團體欣賞室活動時間：上午9:30-12:00(結束時間視節目長短而定)洽詢電話：2755-2823分機2801、2802參加方式：不需報名，免費自由入場(非講座)場次內容：1. 3/15(六) 09:30-羊毛與千葉花（演唱會）114分鐘2013年10月於天王洲銀河劇場舉辦的10周年紀念演唱會，首次以Live DVD的形式記錄下來，獻給廣大歌迷。會場內洋溢著溫暖而美好的氛圍，豪華伴奏陣容攜手創造出一場極致的音樂盛宴。每一個音符都彷彿在空氣中流淌，讓人沉浸在美妙的旋律中。2. 3/22(六) 09:30-斜坡上的老歌手（紀錄片）79分鐘隨著旋律在舞臺上下穿梭，歲月飛逝，見證了包曉娟與謝英雄的輝煌時刻。在族語的呢喃中，我們感受到藍石化對古謠堅持的深刻情感。最後一曲《乾杯》則激盪出製作人魏榮貴的不老樂團的精神，儘管微醺，他們對音樂的熱情依然如故，令人動容。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=BDBE44A21382E309', `image_url`='[]';
