INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('22ebd8830714b0d62ee3390a7fb35d8c', '【新北市立圖書館新店寶興圖書閱覽室】114年3月主題書展:和大自然做朋友', '以捷運、公車、郊山、海岸、水圳步道、水漾溼地，藉由大眾運輸可到達的地點，接近大自然，聆聽大自然的故事，以更多元的角度，認識、體驗自然。展出時間：3月1日至3月31日 開館時間3月27日 不對外開放展出地點：新北市立圖書館新店區寶興圖書閱覽室主題書展區新北市新店區寶中路65巷59號3樓展出期間 圖書可外借', '新北市立圖書館', '新北市新店區寶中路65巷59號3樓', '新店寶興圖書閱覽室主題書展區', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店寶興圖書閱覽室】114年3月主題書展:和大自然做朋友', `description`='以捷運、公車、郊山、海岸、水圳步道、水漾溼地，藉由大眾運輸可到達的地點，接近大自然，聆聽大自然的故事，以更多元的角度，認識、體驗自然。展出時間：3月1日至3月31日 開館時間3月27日 不對外開放展出地點：新北市立圖書館新店區寶興圖書閱覽室主題書展區新北市新店區寶中路65巷59號3樓展出期間 圖書可外借', `organizer`='新北市立圖書館', `address`='新北市新店區寶中路65巷59號3樓', `location`='新店寶興圖書閱覽室主題書展區', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('22ebd8830714b0d66db8836adfef168c', '【新北市立圖書館新店分館】114年3月主題書展:每天五分鐘做更好的自己草木世界', '想成為什麼樣的自己，就每天花點時間做改變，慢慢地朝目標前進，每天朝目標前進一小步，然後在將來的某一天就能成為更好的自己，試試看，從今天開始做起！展出時間：3月1日至3月31日 開館時間3月27日 不對外開放展出地點：新北市立圖書館新店分館主題書展區新北市新店區北新路三段105巷2號3樓書展示期間 可外借', '新北市立圖書館', '新北市新店區北新路三段105巷2號3樓', '新店分館主題書展區', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店分館】114年3月主題書展:每天五分鐘做更好的自己草木世界', `description`='想成為什麼樣的自己，就每天花點時間做改變，慢慢地朝目標前進，每天朝目標前進一小步，然後在將來的某一天就能成為更好的自己，試試看，從今天開始做起！展出時間：3月1日至3月31日 開館時間3月27日 不對外開放展出地點：新北市立圖書館新店分館主題書展區新北市新店區北新路三段105巷2號3樓書展示期間 可外借', `organizer`='新北市立圖書館', `address`='新北市新店區北新路三段105巷2號3樓', `location`='新店分館主題書展區', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('22ebd8830714b0d6fcbd03ea29b3cd99', '【新北市市立圖書館新店大鵬圖書閱覽室】114年3月主題書展:春日好點心', '如日本有賞櫻的習俗活動，在觀賞櫻花的美麗同時享受美味又好看的日式和果子點心、精神與味蕾的雙重饗宴。展出時間：3月1日至3月31日 開館時間3月27日 不對外開放展出地點：新北市立圖書館新店大鵬圖書閱覽室主題書展區新店區中正路700巷26號2樓展出期間 可外借', '新北市立圖書館', '新北市新店區中正路700巷26號2樓', '新店大鵬圖書閱覽室主題書展區', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市市立圖書館新店大鵬圖書閱覽室】114年3月主題書展:春日好點心', `description`='如日本有賞櫻的習俗活動，在觀賞櫻花的美麗同時享受美味又好看的日式和果子點心、精神與味蕾的雙重饗宴。展出時間：3月1日至3月31日 開館時間3月27日 不對外開放展出地點：新北市立圖書館新店大鵬圖書閱覽室主題書展區新店區中正路700巷26號2樓展出期間 可外借', `organizer`='新北市立圖書館', `address`='新北市新店區中正路700巷26號2樓', `location`='新店大鵬圖書閱覽室主題書展區', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('22ebd8830714b0d6c6701af25ecd37c1', '【新北市立圖書館新店分館】114年3月15日(六)14:00駐館藝術家:瞰見台灣-讓空拍機陪你去旅行', '新店分館為鼓勵藝術創作及美學交流，以營造書香社會之藝術風情，特舉辦「駐館藝術家」活動，以實作的方式現場示範。藝術是欣賞世界的媒介，新店分館本月駐館藝術家邀請張嘉文老師分享空中拍攝的經驗， 看到台灣的美麗。藝術家：張嘉文老師簡介：我是一位熱愛空拍攝影的攝影人, 擅長用無人機捕捉令人驚嘆的影像。我相信每個場景都有其獨特的故事, 我的使命就是透過鏡頭, 向觀眾講述這些故事。無論是在大自然飛翔, 或是在都市中探索, 我都致力於捕捉那些難以言喻的美麗瞬間, 並將其轉化為令人難以忘懷的影像。希望的我的作品能讓您重新發現台灣的美。時間：114年3月15日(六)14:00-16:00報名：即日起網路報名 https://reurl.cc/nqG8Y8 30名。地點：新店分館3樓多功能教室(地址：新店區北新路3段105巷2號3樓)連絡電話：2918-3181#230', '新北市立圖書館', '新北市新店區北新路三段105巷2號3樓', '新店分館多功能教室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店分館】114年3月15日(六)14:00駐館藝術家:瞰見台灣-讓空拍機陪你去旅行', `description`='新店分館為鼓勵藝術創作及美學交流，以營造書香社會之藝術風情，特舉辦「駐館藝術家」活動，以實作的方式現場示範。藝術是欣賞世界的媒介，新店分館本月駐館藝術家邀請張嘉文老師分享空中拍攝的經驗， 看到台灣的美麗。藝術家：張嘉文老師簡介：我是一位熱愛空拍攝影的攝影人, 擅長用無人機捕捉令人驚嘆的影像。我相信每個場景都有其獨特的故事, 我的使命就是透過鏡頭, 向觀眾講述這些故事。無論是在大自然飛翔, 或是在都市中探索, 我都致力於捕捉那些難以言喻的美麗瞬間, 並將其轉化為令人難以忘懷的影像。希望的我的作品能讓您重新發現台灣的美。時間：114年3月15日(六)14:00-16:00報名：即日起網路報名 https://reurl.cc/nqG8Y8 30名。地點：新店分館3樓多功能教室(地址：新店區北新路3段105巷2號3樓)連絡電話：2918-3181#230', `organizer`='新北市立圖書館', `address`='新北市新店區北新路三段105巷2號3樓', `location`='新店分館多功能教室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('22ebd8830714b0d620cc2b3b5d576ae2', '【新北市立圖書館新店龜山圖書閱覽室】114年3月主題書展:春天賞蝶去', '台灣環境得天獨厚，具有多種不同的蝴蝶生存繁衍需要的氣候、地形等條件，造就了十分豐富的蝴蝶生態，為台灣贏得蝴蝶王國的美譽。　展出時間：3月1日至3月31日 開館時間3月27日 不對外開放展出地點：新北市立圖書館新店龜山圖書閱覽室主題書展區新北市新店區新烏路三段136號書展示期間 可外借', '新北市立圖書館', '新北市新店區新烏路三段136號', '新店龜山圖書閱覽室主題書展區', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店龜山圖書閱覽室】114年3月主題書展:春天賞蝶去', `description`='台灣環境得天獨厚，具有多種不同的蝴蝶生存繁衍需要的氣候、地形等條件，造就了十分豐富的蝴蝶生態，為台灣贏得蝴蝶王國的美譽。　展出時間：3月1日至3月31日 開館時間3月27日 不對外開放展出地點：新北市立圖書館新店龜山圖書閱覽室主題書展區新北市新店區新烏路三段136號書展示期間 可外借', `organizer`='新北市立圖書館', `address`='新北市新店區新烏路三段136號', `location`='新店龜山圖書閱覽室主題書展區', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('22ebd8830714b0d63e6531cb11519289', '【新北市立圖書館新店仁愛圖書閱覽室】114年3月主題書展:女人當家', '女力不容小覷，女人綻放的光彩，絕對閃耀奪目！祝福女人們婦女節快樂！　展出時間：3月1日至3月31日 開館時間3月27日 不對外開放展出地點：新北市立圖書館新店仁愛圖書閱覽室書展區新店區建國路58號2樓展出期間 可外借', '新北市立圖書館', '新北市新店區建國路58號2樓', '新店仁愛圖書閱覽室主題書展區', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店仁愛圖書閱覽室】114年3月主題書展:女人當家', `description`='女力不容小覷，女人綻放的光彩，絕對閃耀奪目！祝福女人們婦女節快樂！　展出時間：3月1日至3月31日 開館時間3月27日 不對外開放展出地點：新北市立圖書館新店仁愛圖書閱覽室書展區新店區建國路58號2樓展出期間 可外借', `organizer`='新北市立圖書館', `address`='新北市新店區建國路58號2樓', `location`='新店仁愛圖書閱覽室主題書展區', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('22ebd8830714b0d6e9435139147fc6c8', '【新北市立圖書館新店北新圖書閱覽室】114年3月主題書展:屬於春天的節日', '藉此了解屬於春天各節日的節慶習俗、歷史背景、傳統故事以及節日的文化意義。同時讓我們可以在節日的氛圍中，有更深的認識。展出時間：3月1日至3月31日 開館時間3月27日 不對外開放展出地點：新北市立圖書館新店北新圖書閱覽室主題書展區新北市新店區北新路一段92號2樓書展示期間 可外借', '新北市立圖書館', '新北市新店區北新路一段92樓2樓', '新店北新圖書閱覽室主題書展區', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店北新圖書閱覽室】114年3月主題書展:屬於春天的節日', `description`='藉此了解屬於春天各節日的節慶習俗、歷史背景、傳統故事以及節日的文化意義。同時讓我們可以在節日的氛圍中，有更深的認識。展出時間：3月1日至3月31日 開館時間3月27日 不對外開放展出地點：新北市立圖書館新店北新圖書閱覽室主題書展區新北市新店區北新路一段92號2樓書展示期間 可外借', `organizer`='新北市立圖書館', `address`='新北市新店區北新路一段92樓2樓', `location`='新店北新圖書閱覽室主題書展區', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('65e2359c73f77c986017e0e9', '2024-2025年臺史博戲劇【戲遊時光：小人物說歷史】', '📣《戲遊時光：小人物說歷史》單人互動導覽📣\n\n到底各時代中的「小人物」是怎麼看歷史的呢？\n透過「17世紀的西拉雅青年」、「清末的農夫」及「臺灣文化協會的新青年」這3個角色的觀點，來聊聊他們在歷史的洪流中面臨了怎樣的衝擊？又該如何生存下去呢？💪\n❗❗ 注意：小人物們將在常設展中的定點驚喜現身！💫歡迎看準時間來和他們巧遇喔～\n本活動為「國家語言整體發展方案」支持 \n\n🕚演出時間：每場次40分鐘（各片段約10分鐘）\n⛳演出地點：展示教育大樓2F常設展（臺南市安南區長和路一段250號）\n🗓 演出場次：\n\n\n\n※主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，若有相關異動將會公告於本網站， 恕不另行通知。\n\n\n🎭2024-2025年度合作團隊「影響．新劇場」🎭\n\n「影響．新劇場」多次榮獲Taiwan Top年度獎助演藝團隊，與臺南市傑出演藝團隊、臺北兒童藝術節演出獎。致力為兒童、青少年、年輕觀眾量身製作富有人文意涵、精緻多元的好戲，創作內容豐富，跨域多元。除傑出演藝表現，劇團積極以劇場做為社會服務與行動的推進器，致力文化平權、兒童青少年劇場、樂齡藝術等。\n\n ', '國立臺灣歷史博物館', '無資料', '無資料', 0, 0, '無資料', 'https://event.culture.tw/mocweb/reg/NMTH/Detail.init.ctr?actId=40041', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2024-2025年臺史博戲劇【戲遊時光：小人物說歷史】', `description`='📣《戲遊時光：小人物說歷史》單人互動導覽📣\n\n到底各時代中的「小人物」是怎麼看歷史的呢？\n透過「17世紀的西拉雅青年」、「清末的農夫」及「臺灣文化協會的新青年」這3個角色的觀點，來聊聊他們在歷史的洪流中面臨了怎樣的衝擊？又該如何生存下去呢？💪\n❗❗ 注意：小人物們將在常設展中的定點驚喜現身！💫歡迎看準時間來和他們巧遇喔～\n本活動為「國家語言整體發展方案」支持 \n\n🕚演出時間：每場次40分鐘（各片段約10分鐘）\n⛳演出地點：展示教育大樓2F常設展（臺南市安南區長和路一段250號）\n🗓 演出場次：\n\n\n\n※主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，若有相關異動將會公告於本網站， 恕不另行通知。\n\n\n🎭2024-2025年度合作團隊「影響．新劇場」🎭\n\n「影響．新劇場」多次榮獲Taiwan Top年度獎助演藝團隊，與臺南市傑出演藝團隊、臺北兒童藝術節演出獎。致力為兒童、青少年、年輕觀眾量身製作富有人文意涵、精緻多元的好戲，創作內容豐富，跨域多元。除傑出演藝表現，劇團積極以劇場做為社會服務與行動的推進器，致力文化平權、兒童青少年劇場、樂齡藝術等。\n\n ', `organizer`='國立臺灣歷史博物館', `address`='無資料', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMTH/Detail.init.ctr?actId=40041', `image_url`='[]';
