INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c3845d26b32418d001b937', '【銀藝流光】2025年第1季銀齡主題推廣活動-非常「動」人˙「藝」起長大－(親子場)', '童年與兒時玩伴一起玩遊戲，打彈珠、跳格子、紅綠燈、躲貓貓……好多熟悉的身體動作和聲音陪伴我們，成為我們青春的記憶。你是否也想跟家人、朋友、夥伴分享這些青春的美好片刻？南美館今年度第1季推出肢體工作坊，除了以繪本故事帶領大家回顧或想像「長大」這件事，更將透過奔跑、跳躍等等身體動作與遊戲參與，探索自己的生命故事，與夥伴一起找尋青春的印記、想像無限可能的未來、重拾童心未泯的快樂！', '臺南市美術館', '臺南市中西區臺南市中西區南門路 37 號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '臺南市美術館1館', 22.99594458, 120.192874, '活動免費，入館需依規定購票+--', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【銀藝流光】2025年第1季銀齡主題推廣活動-非常「動」人˙「藝」起長大－(親子場)', `description`='童年與兒時玩伴一起玩遊戲，打彈珠、跳格子、紅綠燈、躲貓貓……好多熟悉的身體動作和聲音陪伴我們，成為我們青春的記憶。你是否也想跟家人、朋友、夥伴分享這些青春的美好片刻？南美館今年度第1季推出肢體工作坊，除了以繪本故事帶領大家回顧或想像「長大」這件事，更將透過奔跑、跳躍等等身體動作與遊戲參與，探索自己的生命故事，與夥伴一起找尋青春的印記、想像無限可能的未來、重拾童心未泯的快樂！', `organizer`='臺南市美術館', `address`='臺南市中西區臺南市中西區南門路 37 號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='臺南市美術館1館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='活動免費，入館需依規定購票+--', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c3845d26b32418d001b938', '時空交織的府城記憶：探索大臺南文化與歷史軌跡', '🏛️ 走進歷史，感受台南的文化脈動！\r\n這不只是一場導覽，更是一場跨越時空的文化探索之旅！🚶‍♂️🏰\r\n📅 活動日期｜2025/03/15（六）\r\n📍 集合地點｜佳里國中大門口（提供遊覽車）\r\n💰 費用｜150元（含保險＋車資＋午餐）\r\n📝 報名方式｜現場繳費 / 匯款（請來電告知後五碼）\r\n🔍 行程亮點\r\n🎭 場域走讀｜從臺南市立博物館到延平郡王祠，穿梭在歷史的記憶中\r\n📖 專題導讀｜專業講師帶你深入解析府城文化與博物館館藏亮點\r\n🏛️ 常設展《自造臺南》｜見證臺南歷史與文化的演進\r\n🎉 特展《府城300年》｜重溫清領時期府城的發展與文化遺產\r\n✨ 一次探索 歷史 X 文化 X 時空 的深度體驗，快來報名吧！📩\r\n', '臺南市北門社區大學', '臺南市佳里區', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '佳里區（臺南市）=', 23.1669941, 120.178593, '150元（含保險＋車資＋午餐）+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='時空交織的府城記憶：探索大臺南文化與歷史軌跡', `description`='🏛️ 走進歷史，感受台南的文化脈動！\r\n這不只是一場導覽，更是一場跨越時空的文化探索之旅！🚶‍♂️🏰\r\n📅 活動日期｜2025/03/15（六）\r\n📍 集合地點｜佳里國中大門口（提供遊覽車）\r\n💰 費用｜150元（含保險＋車資＋午餐）\r\n📝 報名方式｜現場繳費 / 匯款（請來電告知後五碼）\r\n🔍 行程亮點\r\n🎭 場域走讀｜從臺南市立博物館到延平郡王祠，穿梭在歷史的記憶中\r\n📖 專題導讀｜專業講師帶你深入解析府城文化與博物館館藏亮點\r\n🏛️ 常設展《自造臺南》｜見證臺南歷史與文化的演進\r\n🎉 特展《府城300年》｜重溫清領時期府城的發展與文化遺產\r\n✨ 一次探索 歷史 X 文化 X 時空 的深度體驗，快來報名吧！📩\r\n', `organizer`='臺南市北門社區大學', `address`='臺南市佳里區', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='佳里區（臺南市）=', `latitude`=23.1669941, `longitude`=120.178593, `ticket_price`='150元（含保險＋車資＋午餐）+--', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c3845e26b32418d001b939', '《看我、聽我》校園民歌公益音樂劇', '《看我、聽我》校園民歌公益音樂劇\r\n本劇以一段溫馨感人的故事作為音樂劇情主軸\r\n串入二十餘首熟悉動聽的民歌曲目\r\n以混聲合唱團、演員重唱的多元方式演出\r\n帶領大家坐著時光機\r\n一起回到那段純真、樸實的年代\r\n重拾歌頌青春的美好時光', '嘉義男聲合唱團', '臺南市新營區中正路23號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '300 、500+--', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《看我、聽我》校園民歌公益音樂劇', `description`='《看我、聽我》校園民歌公益音樂劇\r\n本劇以一段溫馨感人的故事作為音樂劇情主軸\r\n串入二十餘首熟悉動聽的民歌曲目\r\n以混聲合唱團、演員重唱的多元方式演出\r\n帶領大家坐著時光機\r\n一起回到那段純真、樸實的年代\r\n重拾歌頌青春的美好時光', `organizer`='嘉義男聲合唱團', `address`='臺南市新營區中正路23號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='300 、500+--', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c3846126b32418d001b93a', '關廟區圖書館:中文繪本說故事~跑跑鎮', '關廟區圖書館每月精選中文繪本說故事活動,於114年03月15日(星期六)上午10:00-11:00於圖書館嬰幼兒閱讀區舉辦,由佳宜老師帶來—【跑跑鎮】繪本。一本創意遊戲書，透過兩個不相關的東西快跑、碰撞在一起後，變成「新」事物；趣味化的拆解元素，再添入有形的融合和無形的融合，讓孩子啟動水平思考與聯想力！活動免費參加,歡迎有興趣之家長及孩童一起來聽故事。', '臺南市關廟區圖書館', '臺南市關廟區文化街1號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '臺南市關廟區圖書館', 22.95577909, 120.3342821, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='關廟區圖書館:中文繪本說故事~跑跑鎮', `description`='關廟區圖書館每月精選中文繪本說故事活動,於114年03月15日(星期六)上午10:00-11:00於圖書館嬰幼兒閱讀區舉辦,由佳宜老師帶來—【跑跑鎮】繪本。一本創意遊戲書，透過兩個不相關的東西快跑、碰撞在一起後，變成「新」事物；趣味化的拆解元素，再添入有形的融合和無形的融合，讓孩子啟動水平思考與聯想力！活動免費參加,歡迎有興趣之家長及孩童一起來聽故事。', `organizer`='臺南市關廟區圖書館', `address`='臺南市關廟區文化街1號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='臺南市關廟區圖書館', `latitude`=22.95577909, `longitude`=120.3342821, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
