INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c3847326b32418d001b93c', '葉石濤文學紀念館-蝸牛漫步文學地景踏查3/15場次「悠然過日子」', '「這是個適合人們做夢、幹活、戀愛、結婚，悠然過日子的好地方。」讓我們跟著葉老的腳步，一同悠然漫步午後的府城吧！\r\n主題：悠然過日子\r\n活動時間：2025/03/15(六) 14:00-16:30\r\n導覽講師：台南市導覽協會常務理事陳冠州\r\n集合出發地點：葉石濤文學紀念館(臺南市中西區友愛街8-3號)\r\n預計走訪路線：葉石濤文學紀念館→銀座通→打銀街→葉老舊居(蝸牛巷)→中央市場→臺灣祀典武廟。\r\n(實際路線依導覽老師當日走讀為準。)', '臺南市政府文化局', '臺南市中西區友愛街8-3號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '葉石濤文學紀念館（直轄市定古蹟原臺南山林事務所）', 22.99594458, 120.192874, '新台幣150元+--', 'https://culture.tainan.gov.tw/registration/Details?Parser=99,7,51,,,,,1200', '[]') ON DUPLICATE KEY UPDATE `activity_name`='葉石濤文學紀念館-蝸牛漫步文學地景踏查3/15場次「悠然過日子」', `description`='「這是個適合人們做夢、幹活、戀愛、結婚，悠然過日子的好地方。」讓我們跟著葉老的腳步，一同悠然漫步午後的府城吧！\r\n主題：悠然過日子\r\n活動時間：2025/03/15(六) 14:00-16:30\r\n導覽講師：台南市導覽協會常務理事陳冠州\r\n集合出發地點：葉石濤文學紀念館(臺南市中西區友愛街8-3號)\r\n預計走訪路線：葉石濤文學紀念館→銀座通→打銀街→葉老舊居(蝸牛巷)→中央市場→臺灣祀典武廟。\r\n(實際路線依導覽老師當日走讀為準。)', `organizer`='臺南市政府文化局', `address`='臺南市中西區友愛街8-3號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='葉石濤文學紀念館（直轄市定古蹟原臺南山林事務所）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='新台幣150元+--', `source_url`='https://culture.tainan.gov.tw/registration/Details?Parser=99,7,51,,,,,1200', `image_url`='[]';
