INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c3847b26b32418d001b93f', '南區鹽埕圖書館：3月周日電影開麥拉', '漫長的冬天裡，\r\n難得的陽光讓人格外感到幸福。\r\n空氣中開始飄散著淺淺的花香\r\n美好的時節即使遲到了，但仍終究會來臨\r\n懷抱著等待的心情，一起看場電影吧！\r\n\r\n【電影開麥拉3月片單】\r\n3月2日(日)小木偶:馬戲團奇遇記\r\n普/93分鐘/動畫片\r\n3月9日(日)救救菜英文 (性平映像)\r\n普/134分鐘/劇情片\r\n3月16日(日)我和喵喵的冒險旅行\r\n普/83分鐘/劇情片\r\n3月23日(日)哈勇家\r\n普/111分鐘/劇情片\r\n3月30日(日)超級瑪利歐兄弟 電影版\r\n普/92分鐘/劇情片\r\n\r\n免報名，自由入場', '臺南市南區鹽埕圖書館', '臺南市南區新和東路51號', '2025-03-02 00:00:00', '2025-03-30 00:00:00', '臺南市南區鹽埕圖書館', 22.95561863, 120.1903743, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南區鹽埕圖書館：3月周日電影開麥拉', `description`='漫長的冬天裡，\r\n難得的陽光讓人格外感到幸福。\r\n空氣中開始飄散著淺淺的花香\r\n美好的時節即使遲到了，但仍終究會來臨\r\n懷抱著等待的心情，一起看場電影吧！\r\n\r\n【電影開麥拉3月片單】\r\n3月2日(日)小木偶:馬戲團奇遇記\r\n普/93分鐘/動畫片\r\n3月9日(日)救救菜英文 (性平映像)\r\n普/134分鐘/劇情片\r\n3月16日(日)我和喵喵的冒險旅行\r\n普/83分鐘/劇情片\r\n3月23日(日)哈勇家\r\n普/111分鐘/劇情片\r\n3月30日(日)超級瑪利歐兄弟 電影版\r\n普/92分鐘/劇情片\r\n\r\n免報名，自由入場', `organizer`='臺南市南區鹽埕圖書館', `address`='臺南市南區新和東路51號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市南區鹽埕圖書館', `latitude`=22.95561863, `longitude`=120.1903743, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
