INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c3848626b32418d001b946', '【性別符號】│我是女生也是男生', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│我是女生也是男生\r\n英文片│XXY\r\n\r\n導演│露西雅.普恩佐\r\n阿根廷、西班牙、法國│2007│限制級│劇情類│彩色│西班牙語│91分\r\n\r\n簡介\r\n青春期荷爾蒙的肆虐，使得雅莉絲身上同時具備的男女性徵愈發明顯。16歲雅莉絲的煩惱，已經不僅是對青春單純的茫然與迷惘。', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【性別符號】│我是女生也是男生', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│我是女生也是男生\r\n英文片│XXY\r\n\r\n導演│露西雅.普恩佐\r\n阿根廷、西班牙、法國│2007│限制級│劇情類│彩色│西班牙語│91分\r\n\r\n簡介\r\n青春期荷爾蒙的肆虐，使得雅莉絲身上同時具備的男女性徵愈發明顯。16歲雅莉絲的煩惱，已經不僅是對青春單純的茫然與迷惘。', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c3848726b32418d001b947', '【性別符號】│丹麥女孩', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│丹麥女孩\r\n英文片│The Danish Girl\r\n\r\n導演│湯姆•霍伯\r\n英、美、比利時│2016│輔導15級│劇情類│彩色│英語│120分\r\n\r\n簡介\r\n在1926年的哥本哈根，畫家格蕾塔•魏格納一次因模特兒失約，而說服她的風景畫家丈夫埃納爾•魏格納穿上女裝來充當女模特以完成畫作。', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-03-14 00:00:00', '2025-03-14 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【性別符號】│丹麥女孩', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│丹麥女孩\r\n英文片│The Danish Girl\r\n\r\n導演│湯姆•霍伯\r\n英、美、比利時│2016│輔導15級│劇情類│彩色│英語│120分\r\n\r\n簡介\r\n在1926年的哥本哈根，畫家格蕾塔•魏格納一次因模特兒失約，而說服她的風景畫家丈夫埃納爾•魏格納穿上女裝來充當女模特以完成畫作。', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-14 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c3848726b32418d001b948', '【性別符號】│月光下的藍色男孩', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│月光下的藍色男孩\r\n英文片│Moonlight\r\n\r\n導演│巴瑞•賈金斯\r\n美國│2016│輔15級│劇情片│彩色│英語│111分鐘\r\n\r\n簡介\r\n居住在邁阿密的男孩席隆，因個子矮小、平時沈默寡言，在學校時常成為被霸凌的對象，痛苦中掙扎求生的他，憑著意志生存下來，但他漸漸發現真正殘酷的不是外面的世界，而是他已偷偷愛上自己的好朋友…', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【性別符號】│月光下的藍色男孩', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│月光下的藍色男孩\r\n英文片│Moonlight\r\n\r\n導演│巴瑞•賈金斯\r\n美國│2016│輔15級│劇情片│彩色│英語│111分鐘\r\n\r\n簡介\r\n居住在邁阿密的男孩席隆，因個子矮小、平時沈默寡言，在學校時常成為被霸凌的對象，痛苦中掙扎求生的他，憑著意志生存下來，但他漸漸發現真正殘酷的不是外面的世界，而是他已偷偷愛上自己的好朋友…', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c3848726b32418d001b949', '「夜訪螢河 與光同行」主題活動', '本活動邀請秀峰國小舞蹈班、廣興國小弦樂隊、南投親善大使高曼容、奇幻腹語等精彩演出，還有免費賞螢導覽及星空茶席體驗，並邀請在地特色業者展售特色農特產伴手好禮、文創品與小吃，另有打卡送螢火蟲燈籠及市集抵用券等活動，廣邀全國民眾前來賞螢遊玩，推廣地方觀光產業。', '南投縣政府', '南投縣鹿谷鄉', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '鹿谷鄉（南投縣）=', 23.73776029, 120.7815065, '無資料', 'https://www.nantou.gov.tw/big5/index.php', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「夜訪螢河 與光同行」主題活動', `description`='本活動邀請秀峰國小舞蹈班、廣興國小弦樂隊、南投親善大使高曼容、奇幻腹語等精彩演出，還有免費賞螢導覽及星空茶席體驗，並邀請在地特色業者展售特色農特產伴手好禮、文創品與小吃，另有打卡送螢火蟲燈籠及市集抵用券等活動，廣邀全國民眾前來賞螢遊玩，推廣地方觀光產業。', `organizer`='南投縣政府', `address`='南投縣鹿谷鄉', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='鹿谷鄉（南投縣）=', `latitude`=23.73776029, `longitude`=120.7815065, `ticket_price`='無資料', `source_url`='https://www.nantou.gov.tw/big5/index.php', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c3848726b32418d001b94a', '賽夏族民俗文物館「原音傳世」假日藝文展演：街頭藝人表演（114年3月）', '「原音」指的是原住民族純粹且具有特色的音樂與聲音，承載著各族群的歷史、故事和情感，原音常與舞蹈相伴相生，音樂的節奏牽引舞步，歌聲的抑揚訴說情感，音樂與舞蹈如靈魂雙翼，共繪生命張力與自然和諧。「傳世」則強調了文化精粹的歷史傳承及跨世代的影響力，透過藝文展演，原聲與舞蹈交融，兩者相映，共同喚醒對原住民族文化的敬意，傳遞珍貴聲音背後的靈魂與故事。\r\n賽夏族民俗文物館假日藝文系列活動自1月29日（農曆正月初一）至2月2日（農曆正月初五）期間，每日安排街頭藝人或表演團體共5場次的演出。自2月22日起至12月27日，每月的第2個和第4個週六，舉辦街頭藝人與表演團體的演出。表演將於14:20至16:20進行，共計10場；表演團體則於14:20至15:00進行，總共11場。', '苗栗縣政府原住民族及族群發展處', '苗栗縣南庄鄉苗栗縣南庄鄉東河村16鄰向天湖25號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '苗栗縣賽夏族民俗文物館', 24.56608432, 121.017471, '全票+30;團體票+20;優待票+10', 'https://www.facebook.com/rareme037825024', '[]') ON DUPLICATE KEY UPDATE `activity_name`='賽夏族民俗文物館「原音傳世」假日藝文展演：街頭藝人表演（114年3月）', `description`='「原音」指的是原住民族純粹且具有特色的音樂與聲音，承載著各族群的歷史、故事和情感，原音常與舞蹈相伴相生，音樂的節奏牽引舞步，歌聲的抑揚訴說情感，音樂與舞蹈如靈魂雙翼，共繪生命張力與自然和諧。「傳世」則強調了文化精粹的歷史傳承及跨世代的影響力，透過藝文展演，原聲與舞蹈交融，兩者相映，共同喚醒對原住民族文化的敬意，傳遞珍貴聲音背後的靈魂與故事。\r\n賽夏族民俗文物館假日藝文系列活動自1月29日（農曆正月初一）至2月2日（農曆正月初五）期間，每日安排街頭藝人或表演團體共5場次的演出。自2月22日起至12月27日，每月的第2個和第4個週六，舉辦街頭藝人與表演團體的演出。表演將於14:20至16:20進行，共計10場；表演團體則於14:20至15:00進行，總共11場。', `organizer`='苗栗縣政府原住民族及族群發展處', `address`='苗栗縣南庄鄉苗栗縣南庄鄉東河村16鄰向天湖25號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='苗栗縣賽夏族民俗文物館', `latitude`=24.56608432, `longitude`=121.017471, `ticket_price`='全票+30;團體票+20;優待票+10', `source_url`='https://www.facebook.com/rareme037825024', `image_url`='[]';
