INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('d31febefa3d87d3f35d8477bd2c9729e', '【新北市立圖書館石碇分館】114年4月份閱讀書籤主題書展-「與野鳥做朋友系列書展」', '《與野鳥做朋友系列書展》1.住家。公園的野鳥都市裡的小麻雀都住在什麼地方？燕子為什麼喜歡在住家的屋簷下築巢？白頭翁和烏頭翁又有哪裡不一樣？2.濕地。沼澤的野鳥有的有長長腳和細長的腳趾，有的有扁扁嘴和厚厚的蹼，有的頭頂翹一根辮，有的有向上彎的細嘴尖…來濕地、沼澤和野鳥一起做朋友。3.田園的野鳥夜鶯為什麼又叫做「蚊子鳥」？空中惡霸指的是哪一種鳥？長的像蘋果臉的草鶚為什麼是農人的好朋友？4.山區。樹林的野鳥大冠鷲張開翅膀隨著氣流盤旋而上，小彎嘴在草叢裡唱歌，綠畫眉在樹枝間跳躍…山區和樹林是鳥兒的快樂天堂。', '新北市立圖書館', '新北市石碇區潭邊里碇坪路一段65號', '新北市立圖書館石碇分館新書展示區', 24.94714107, 121.6472277, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館石碇分館】114年4月份閱讀書籤主題書展-「與野鳥做朋友系列書展」', `description`='《與野鳥做朋友系列書展》1.住家。公園的野鳥都市裡的小麻雀都住在什麼地方？燕子為什麼喜歡在住家的屋簷下築巢？白頭翁和烏頭翁又有哪裡不一樣？2.濕地。沼澤的野鳥有的有長長腳和細長的腳趾，有的有扁扁嘴和厚厚的蹼，有的頭頂翹一根辮，有的有向上彎的細嘴尖…來濕地、沼澤和野鳥一起做朋友。3.田園的野鳥夜鶯為什麼又叫做「蚊子鳥」？空中惡霸指的是哪一種鳥？長的像蘋果臉的草鶚為什麼是農人的好朋友？4.山區。樹林的野鳥大冠鷲張開翅膀隨著氣流盤旋而上，小彎嘴在草叢裡唱歌，綠畫眉在樹枝間跳躍…山區和樹林是鳥兒的快樂天堂。', `organizer`='新北市立圖書館', `address`='新北市石碇區潭邊里碇坪路一段65號', `location`='新北市立圖書館石碇分館新書展示區', `latitude`=24.94714107, `longitude`=121.6472277, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
