INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('673f92d426b324689882a012', '植物的果實與種子(小朋友6-10歲)', ' ※ 本課程最低開班人數：12 組 (須完成繳費)  。 \n\n（小朋友參加年齡依照學校入學分齡標準，以9月2日為分界）\n\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			植物的纖維（親子課程/小朋友年齡6-10歲）\n			\n		\n		\n			\n			課程目標\n			\n			認識植物的各種趣味小知識，讓親子運用自然素材進行藝術創作，並學習如何與植物相處以及愛護自然環境。\n		\n		\n			\n			時 間\n			\n			\n			課 程 主 題\n			\n			\n			教 學 內 容\n			\n		\n		\n			\n			3/23(日)\n\n			10:00-12:00\n			\n			\n			植物的纖維\n			\n			\n			紙張與衣服究竟是怎麼產生?\n\n			一起探索植物纖維的奧秘，跟著老師製作創意手抄紙！\n			\n		\n		\n			\n			    備註：\n\n			  1. 手抄紙上所搭配的植物視季節調整，圖片僅為示意圖。\n\n			  2. 請穿著不怕髒的衣服，或自備美術圍裙。\n			\n		\n	\n\n\n \n\n👉同類型動植物相關、環境生態課程：\n\n植物的纖維(3/23) 、甲蟲王者-鍬形蟲與獨角仙(6/15)、永生花小樹球(8/3)、\n\n賞蛙趣-是蟾蜍還是青蛙?(11/16)、松果聖誕樹(12/21)\n\n\n \n\n【教室位置圖】：上課地點在W315教室\n\n\n\n★ 【W315教室位置圖】\n\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-04-27 00:00:00', '2025-04-27 00:00:00', 'W315教室', 25.0367564, 121.519047, '650', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=41244', '[]') ON DUPLICATE KEY UPDATE `activity_name`='植物的果實與種子(小朋友6-10歲)', `description`=' ※ 本課程最低開班人數：12 組 (須完成繳費)  。 \n\n（小朋友參加年齡依照學校入學分齡標準，以9月2日為分界）\n\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			植物的纖維（親子課程/小朋友年齡6-10歲）\n			\n		\n		\n			\n			課程目標\n			\n			認識植物的各種趣味小知識，讓親子運用自然素材進行藝術創作，並學習如何與植物相處以及愛護自然環境。\n		\n		\n			\n			時 間\n			\n			\n			課 程 主 題\n			\n			\n			教 學 內 容\n			\n		\n		\n			\n			3/23(日)\n\n			10:00-12:00\n			\n			\n			植物的纖維\n			\n			\n			紙張與衣服究竟是怎麼產生?\n\n			一起探索植物纖維的奧秘，跟著老師製作創意手抄紙！\n			\n		\n		\n			\n			    備註：\n\n			  1. 手抄紙上所搭配的植物視季節調整，圖片僅為示意圖。\n\n			  2. 請穿著不怕髒的衣服，或自備美術圍裙。\n			\n		\n	\n\n\n \n\n👉同類型動植物相關、環境生態課程：\n\n植物的纖維(3/23) 、甲蟲王者-鍬形蟲與獨角仙(6/15)、永生花小樹球(8/3)、\n\n賞蛙趣-是蟾蜍還是青蛙?(11/16)、松果聖誕樹(12/21)\n\n\n \n\n【教室位置圖】：上課地點在W315教室\n\n\n\n★ 【W315教室位置圖】\n\n\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='W315教室', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='650', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=41244', `image_url`='[]';
