INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bf02d68f15adefa04e0c6d', '青天白日滿地「虹」心球與攝影之旅 - 積吶虹光 LEF', '在浩瀚的宇宙間，我捧著一顆顆「虹」心球，踏上一次次未知的展覽旅途，「虹」心球在空中輕盈漂浮，宛如一座通往遙遠邊境的時光大道，穿越了心靈最深處的邊界。\r\n\r\n每當行走於不同維度的展間，感受到藝術、時間與空間的無常變化，如一陣清風拂過，將心靈堅固的堡壘吹散，放眼望去那白日下的「虹」心球竟成心中最柔軟的夢。\r\n\r\n攝影鏡頭如一場永恆的夢，而藝術也早已超越了靜止的狀態，那如一次次與自己心靈相遇的化身，在鏡頭前試圖捕捉每一段與「虹」同行的旅程，無論走多遠，青天白日依然在頭頂守護，而光與彩的交織早已悄然融入每個角落，成為我與世界的永恆聯結。\r\n\r\nhttps://vocus.cc/article/66ff9bddfd897800014e25c6', '無資料', '雲林縣國立臺灣大學醫學院附設醫院雲林分院虎尾院區2F', '2025-03-05 00:00:00', '2025-03-05 00:00:00', '青天白日滿地虹心球與攝影之旅-積吶虹光LEF', 0, 0, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='青天白日滿地「虹」心球與攝影之旅 - 積吶虹光 LEF', `description`='在浩瀚的宇宙間，我捧著一顆顆「虹」心球，踏上一次次未知的展覽旅途，「虹」心球在空中輕盈漂浮，宛如一座通往遙遠邊境的時光大道，穿越了心靈最深處的邊界。\r\n\r\n每當行走於不同維度的展間，感受到藝術、時間與空間的無常變化，如一陣清風拂過，將心靈堅固的堡壘吹散，放眼望去那白日下的「虹」心球竟成心中最柔軟的夢。\r\n\r\n攝影鏡頭如一場永恆的夢，而藝術也早已超越了靜止的狀態，那如一次次與自己心靈相遇的化身，在鏡頭前試圖捕捉每一段與「虹」同行的旅程，無論走多遠，青天白日依然在頭頂守護，而光與彩的交織早已悄然融入每個角落，成為我與世界的永恆聯結。\r\n\r\nhttps://vocus.cc/article/66ff9bddfd897800014e25c6', `organizer`='無資料', `address`='雲林縣國立臺灣大學醫學院附設醫院雲林分院虎尾院區2F', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-05 00:00:00', `location`='青天白日滿地虹心球與攝影之旅-積吶虹光LEF', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
