INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5683226b32418d001b958', '【新北市立圖書館中和分館】3月影友會', '樂齡電影院\r\n3月11日(二)神人之家（普）65分分\r\n簡介：離家二十年, 導演阿良回到偏遠農村的家鄉, 當他與家人重新面對彼此時, 卻發現當年迫使他逃跑的人事物不曾改變。國小就通靈的哥哥, 與十二尊神明讓信仰成為一家人的救贖, 也成了詛咒。從沉默到慢慢說出心裡話, 阿良日復一日記錄著這一次的重逢, 逐漸意識到他的缺席也是這個家難以癒合的傷口。', '新北市立圖書館總館', '新北市中和區南山路236號6樓', '2025-03-11 00:00:00', '2025-03-11 00:00:00', '新北市立圖書館中和分館', 24.99088039, 121.4936744, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館中和分館】3月影友會', `description`='樂齡電影院\r\n3月11日(二)神人之家（普）65分分\r\n簡介：離家二十年, 導演阿良回到偏遠農村的家鄉, 當他與家人重新面對彼此時, 卻發現當年迫使他逃跑的人事物不曾改變。國小就通靈的哥哥, 與十二尊神明讓信仰成為一家人的救贖, 也成了詛咒。從沉默到慢慢說出心裡話, 阿良日復一日記錄著這一次的重逢, 逐漸意識到他的缺席也是這個家難以癒合的傷口。', `organizer`='新北市立圖書館總館', `address`='新北市中和區南山路236號6樓', `start_date`='2025-03-11 00:00:00', `end_date`='2025-03-11 00:00:00', `location`='新北市立圖書館中和分館', `latitude`=24.99088039, `longitude`=121.4936744, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5683326b32418d001b959', '【新北市立圖書館平溪分館】114年3月影友會', '2025影片欣賞\r\n3月份\r\n播放時間：週六14:00起\r\n地點: 平溪分館/研習教室\r\n03/01［六］創意料理新人王（普）68分\r\n03/08［六］居家運動健身的真相（普）50分\r\n03/15［六］羅馬假期（普）117分\r\n03/22［六］海上鋼琴師（普）125分\r\n03/29［六］小婦人（普）122分\r\n加註*為卡通或動畫片\r\n播放影片與時間若有更動，以活動現場公告為主', '新北市立圖書館總館', '新北市平溪區公園街17號3樓', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '新北市立圖書館平溪分館', 25.02607068, 121.7578817, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館平溪分館】114年3月影友會', `description`='2025影片欣賞\r\n3月份\r\n播放時間：週六14:00起\r\n地點: 平溪分館/研習教室\r\n03/01［六］創意料理新人王（普）68分\r\n03/08［六］居家運動健身的真相（普）50分\r\n03/15［六］羅馬假期（普）117分\r\n03/22［六］海上鋼琴師（普）125分\r\n03/29［六］小婦人（普）122分\r\n加註*為卡通或動畫片\r\n播放影片與時間若有更動，以活動現場公告為主', `organizer`='新北市立圖書館總館', `address`='新北市平溪區公園街17號3樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='新北市立圖書館平溪分館', `latitude`=25.02607068, `longitude`=121.7578817, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5683326b32418d001b95a', '「後•花園之旅（Post-Garden Journey）」個人創作畫展', '為營造優雅而富有人文涵養的洽公環境，樹林地政事務所自114年1月2日起至114年6月30日止，將舉辦「後•花園之旅（Post-Garden Journey）」個人創作畫展，此次展覽主題以 Difflora 和 Mutanimal 系列的創作為主，探討著人類與自然元素以及空間環境之間多種形式的連結，闡述地球生態系統所有生物、植物、動物和真菌的平衡，以及它們的生存和發展、轉變和進化的方式，歡迎有興趣的民眾撥冗前往欣賞。', '新北市樹林地政事務所', '新北市樹林區', '2025-01-02 00:00:00', '2025-06-30 00:00:00', '樹林區（新北市）=', 24.97970609, 121.401034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「後•花園之旅（Post-Garden Journey）」個人創作畫展', `description`='為營造優雅而富有人文涵養的洽公環境，樹林地政事務所自114年1月2日起至114年6月30日止，將舉辦「後•花園之旅（Post-Garden Journey）」個人創作畫展，此次展覽主題以 Difflora 和 Mutanimal 系列的創作為主，探討著人類與自然元素以及空間環境之間多種形式的連結，闡述地球生態系統所有生物、植物、動物和真菌的平衡，以及它們的生存和發展、轉變和進化的方式，歡迎有興趣的民眾撥冗前往欣賞。', `organizer`='新北市樹林地政事務所', `address`='新北市樹林區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='樹林區（新北市）=', `latitude`=24.97970609, `longitude`=121.401034, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5683426b32418d001b95b', '「陪你成長+1圓夢工程――偏鄉小學義拍成果展」', '新北市三重地政事務所為營造藝文美學空間、提供市民舒適的洽公環境，邀請台灣攝影家交流協會舉辦「陪你成長+1圓夢工程――偏鄉小學義拍成果展」，展期自114年1月2日起至3月31日止，歡迎市民蒞臨參觀。', '新北市三重地政事務所', '新北市三重區', '2025-01-02 00:00:00', '2025-03-31 00:00:00', '三重區（新北市）=', 25.06281651, 121.4870977, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「陪你成長+1圓夢工程――偏鄉小學義拍成果展」', `description`='新北市三重地政事務所為營造藝文美學空間、提供市民舒適的洽公環境，邀請台灣攝影家交流協會舉辦「陪你成長+1圓夢工程――偏鄉小學義拍成果展」，展期自114年1月2日起至3月31日止，歡迎市民蒞臨參觀。', `organizer`='新北市三重地政事務所', `address`='新北市三重區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='三重區（新北市）=', `latitude`=25.06281651, `longitude`=121.4870977, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5683526b32418d001b95c', '《大東講堂》傳統工藝的時尚新生', '　　講者透過深厚的學習背景、純熟的技法加上細膩的情感表現，以金屬為主要媒材，融合各項傳統工藝素材與技法，如：天然樹漆工藝、竹籐編織工藝、空窗琺瑯工藝跨媒材結合來創作，秉持對自然環境的關懷，堅持使用不造成汙染、可回收的金屬材料及無毒素不殘留的天然樹漆，開創了當代時尚工藝的新接點。演講內容透過實際案例分享(文化部獎章、總統府獎盃、oqLiq眼鏡)，期望聽眾對金工藝術之美有全新的領會與認知。', '高雄市立圖書館總館', '高雄市鳳山區017鄰光遠路161號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '大東文化藝術中心', 22.625059, 120.363422, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《大東講堂》傳統工藝的時尚新生', `description`='　　講者透過深厚的學習背景、純熟的技法加上細膩的情感表現，以金屬為主要媒材，融合各項傳統工藝素材與技法，如：天然樹漆工藝、竹籐編織工藝、空窗琺瑯工藝跨媒材結合來創作，秉持對自然環境的關懷，堅持使用不造成汙染、可回收的金屬材料及無毒素不殘留的天然樹漆，開創了當代時尚工藝的新接點。演講內容透過實際案例分享(文化部獎章、總統府獎盃、oqLiq眼鏡)，期望聽眾對金工藝術之美有全新的領會與認知。', `organizer`='高雄市立圖書館總館', `address`='高雄市鳳山區017鄰光遠路161號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='大東文化藝術中心', `latitude`=22.625059, `longitude`=120.363422, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5685f26b32418d001b964', '紙風車劇團-巫頂環遊世界', '今年「太平枇杷節」活動特別邀請最受大小朋友喜愛的「紙風車劇團」演出劇目《巫頂環遊世界》，集合各種寓教於樂的故事，內容精采，歡迎闔家蒞臨。', '臺中市太平區農會', '臺中市太平區', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '太平區（臺中市）=', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/A65mk3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='紙風車劇團-巫頂環遊世界', `description`='今年「太平枇杷節」活動特別邀請最受大小朋友喜愛的「紙風車劇團」演出劇目《巫頂環遊世界》，集合各種寓教於樂的故事，內容精采，歡迎闔家蒞臨。', `organizer`='臺中市太平區農會', `address`='臺中市太平區', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='太平區（臺中市）=', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/A65mk3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5686426b32418d001b965', '小丑默劇團【歡樂特派的遊樂園】', '歡樂特派的遊樂園帶來全球各地的歡樂氣息！故事中，大巴與叮叮噹因疫情已久無法出國，渴望探索世界。當門鈴響起，他們懷疑是鬼，卻迎來了實現願望的歡樂特派員，帶他們環遊世界，體驗獨特的兒童節慶祝方式。\r\n\r\n特派員像小叮噹的任意門，帶領他們到世界各地的遊樂園，結合真實遊樂場與當地風俗。小朋友們透過戲劇表演、舞蹈和遊戲，沉浸在歡樂的氛圍中，享受美好的時光。小丑默劇團加入小丑、默劇、雜耍、魔術、歌舞劇等元素，提供精彩的互動劇場，讓大小朋友在這裡盡情玩耍，歡樂一整天！', '國立中正紀念堂管理處', '臺北市中正區中山南路21號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '國立中正紀念堂管理處', 25.03240487, 121.5198839, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50677&utm_source=moc&utm_medium=quer', '[]') ON DUPLICATE KEY UPDATE `activity_name`='小丑默劇團【歡樂特派的遊樂園】', `description`='歡樂特派的遊樂園帶來全球各地的歡樂氣息！故事中，大巴與叮叮噹因疫情已久無法出國，渴望探索世界。當門鈴響起，他們懷疑是鬼，卻迎來了實現願望的歡樂特派員，帶他們環遊世界，體驗獨特的兒童節慶祝方式。\r\n\r\n特派員像小叮噹的任意門，帶領他們到世界各地的遊樂園，結合真實遊樂場與當地風俗。小朋友們透過戲劇表演、舞蹈和遊戲，沉浸在歡樂的氛圍中，享受美好的時光。小丑默劇團加入小丑、默劇、雜耍、魔術、歌舞劇等元素，提供精彩的互動劇場，讓大小朋友在這裡盡情玩耍，歡樂一整天！', `organizer`='國立中正紀念堂管理處', `address`='臺北市中正區中山南路21號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='國立中正紀念堂管理處', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50677&utm_source=moc&utm_medium=quer', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5686426b32418d001b966', '踢踏電台舞團【踢踏復古學-1920踢踏爵士舞宴】', '結合爵士舞、搖擺舞舞風，分析踢踏黃金年代，舞步作為時代顯影，復刻過去經典曲目、舞碼，跨足1920、30、40年代，融合近代編舞，與舞蹈發展維度，一同見證屬於踢踏舞與爵士音樂的共融性格，回歸美式踢踏的復古傳承，迸發出屬於百年前的傳承踢踏聲響。\r\n\r\n除了踢踏電台擅長的爵士曲風，本次演出也將挑戰不一樣的樂風混搭，歡迎一起前來與我們一起同樂!', '國立中正紀念堂管理處', '臺北市中正區中山南路21號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '國立中正紀念堂管理處', 25.03240487, 121.5198839, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50680&utm_source=moc&utm_medium=quer', '[]') ON DUPLICATE KEY UPDATE `activity_name`='踢踏電台舞團【踢踏復古學-1920踢踏爵士舞宴】', `description`='結合爵士舞、搖擺舞舞風，分析踢踏黃金年代，舞步作為時代顯影，復刻過去經典曲目、舞碼，跨足1920、30、40年代，融合近代編舞，與舞蹈發展維度，一同見證屬於踢踏舞與爵士音樂的共融性格，回歸美式踢踏的復古傳承，迸發出屬於百年前的傳承踢踏聲響。\r\n\r\n除了踢踏電台擅長的爵士曲風，本次演出也將挑戰不一樣的樂風混搭，歡迎一起前來與我們一起同樂!', `organizer`='國立中正紀念堂管理處', `address`='臺北市中正區中山南路21號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='國立中正紀念堂管理處', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50680&utm_source=moc&utm_medium=quer', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5686426b32418d001b967', '台灣魔術師聯盟劇團【魔幻奇舞歡樂秀】', '台灣魔術師聯盟劇團成立於民國九十八年，是由一群熱愛魔術表演的愛好者所組成，成員中除了有魔術師外、還有四川變臉、奇門遁甲、搞笑小丑、雜耍特技吞火、口技模仿腹語術、變裝秀、舞蹈…等表演者。本聯盟擁有許多表演經驗---無論是商業場、藝文活動、街頭表演、各縣市文化節、或是公益性活動、教學…演出場次一年超過百場！更常受邀於電視台演出，近年更是舉辦全國性的魔術大會師大型活動，備受好評！本聯盟是一個表演經歷豐富，且充滿娛樂性的表演藝術團體，每2年都會舉辦一場全國性魔術大會。', '國立中正紀念堂管理處', '臺北市中正區中山南路21號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '國立中正紀念堂管理處', 25.03240487, 121.5198839, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50681&utm_source=moc&utm_medium=quer', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台灣魔術師聯盟劇團【魔幻奇舞歡樂秀】', `description`='台灣魔術師聯盟劇團成立於民國九十八年，是由一群熱愛魔術表演的愛好者所組成，成員中除了有魔術師外、還有四川變臉、奇門遁甲、搞笑小丑、雜耍特技吞火、口技模仿腹語術、變裝秀、舞蹈…等表演者。本聯盟擁有許多表演經驗---無論是商業場、藝文活動、街頭表演、各縣市文化節、或是公益性活動、教學…演出場次一年超過百場！更常受邀於電視台演出，近年更是舉辦全國性的魔術大會師大型活動，備受好評！本聯盟是一個表演經歷豐富，且充滿娛樂性的表演藝術團體，每2年都會舉辦一場全國性魔術大會。', `organizer`='國立中正紀念堂管理處', `address`='臺北市中正區中山南路21號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='國立中正紀念堂管理處', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50681&utm_source=moc&utm_medium=quer', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5686526b32418d001b969', ' 竹風戲劇講堂——關於劇場，我們所知道的事！', '你是否曾經好奇，在那場你滿心期待的劇場演出背後，究竟是怎樣的一群人埋頭攜手所創造劇場魔幻？他們又是怎麼構思，讓每一個故事都變得栩栩如生呢？\r\n「劇場」一是門集結眾人之力的藝術。2025年，「竹風戲劇講堂」特別策劃四大主題課程：「編劇」、「導演」、「表演」及「設計與舞監」，講師們將打開一扇扇不同的劇場大門，帶領您發現那些鮮為人知的創作歷程，從多元、有趣的課程中探索劇場的魅力。\r\n不論您是從未接觸過劇場創作的劇場觀眾，或是曾經淺嚐涉略劇場課程的初學者，都歡迎您加入這趟學習之旅。期待課程結束後，您在觀賞劇場演出的時候，能夠擁有一雙更加敏銳的眼睛，愛上那些不只是「演出」，而是「創作」的每一個瞬間。\r\n\r\n●編劇篇\r\nⅠ：透過獨幕劇帶領學員初探劇本寫作的世界，再用類型寫作的介紹與各式寫作練習去了解劇本的多樣形態。\r\nⅡ：透過講解和寫作練習帶領學員掌握劇情結構與其運用。後續練習真實事件在劇本的運用與切入，了解事件創作的要點和其操作方法。\r\n\r\n●導演與表演篇\r\nⅠ：透過劇場遊戲、即興對話，二人對話文本等，從中認識如何在對話中建立角色、控制對話節奏，並從導演及演員角度重新認識舞台中的寫實風格。\r\nⅡ：透過詩歌、接觸即興、新文本等，從中認識劇場中的非寫實風格如何建立，包括如何在劇場中與觀眾建立關係、透過物件建立畫面，並初探呈現新文本的各種形式。\r\n\r\n●表演篇\r\n本課程將帶領學員體驗劇場演員的工作與日常。從戲劇遊戲的帶領、演員必備的能力訓練、到接觸文本後的分析與角色建立，在一天的時間裡讓學員更貼近劇場。\r\n\r\n●導演篇\r\n本課程嘗試從業界作品分享，認識一個導演的工作流程，從前期（文本工作、設計會議）、中期（與演員排練）到後期（進劇場後的實戰），從中認識一個導演的基本工序與心態準備。\r\n\r\n●燈光設計篇 \r\n本課程將帶你認識燈光的魅力，運用手邊的小道具與發光玩具，親手設計一場屬於自己的燈光秀，感受光影如何為戲劇增添生命力。\r\n\r\n●舞台監督篇\r\n本課程帶你深入舞臺監督的世界，學會排練管理、技術協調與現場執行，讓演出順利進行！ \r\n', '盜火劇團', '新竹縣竹北市縣政九路146號', '2025-03-16 00:00:00', '2025-06-29 00:00:00', '新竹縣政府文化局', 24.83816209, 120.9948704, '無資料', 'https://www.voldufeu.com/2025chuwindlesson', '[]') ON DUPLICATE KEY UPDATE `activity_name`=' 竹風戲劇講堂——關於劇場，我們所知道的事！', `description`='你是否曾經好奇，在那場你滿心期待的劇場演出背後，究竟是怎樣的一群人埋頭攜手所創造劇場魔幻？他們又是怎麼構思，讓每一個故事都變得栩栩如生呢？\r\n「劇場」一是門集結眾人之力的藝術。2025年，「竹風戲劇講堂」特別策劃四大主題課程：「編劇」、「導演」、「表演」及「設計與舞監」，講師們將打開一扇扇不同的劇場大門，帶領您發現那些鮮為人知的創作歷程，從多元、有趣的課程中探索劇場的魅力。\r\n不論您是從未接觸過劇場創作的劇場觀眾，或是曾經淺嚐涉略劇場課程的初學者，都歡迎您加入這趟學習之旅。期待課程結束後，您在觀賞劇場演出的時候，能夠擁有一雙更加敏銳的眼睛，愛上那些不只是「演出」，而是「創作」的每一個瞬間。\r\n\r\n●編劇篇\r\nⅠ：透過獨幕劇帶領學員初探劇本寫作的世界，再用類型寫作的介紹與各式寫作練習去了解劇本的多樣形態。\r\nⅡ：透過講解和寫作練習帶領學員掌握劇情結構與其運用。後續練習真實事件在劇本的運用與切入，了解事件創作的要點和其操作方法。\r\n\r\n●導演與表演篇\r\nⅠ：透過劇場遊戲、即興對話，二人對話文本等，從中認識如何在對話中建立角色、控制對話節奏，並從導演及演員角度重新認識舞台中的寫實風格。\r\nⅡ：透過詩歌、接觸即興、新文本等，從中認識劇場中的非寫實風格如何建立，包括如何在劇場中與觀眾建立關係、透過物件建立畫面，並初探呈現新文本的各種形式。\r\n\r\n●表演篇\r\n本課程將帶領學員體驗劇場演員的工作與日常。從戲劇遊戲的帶領、演員必備的能力訓練、到接觸文本後的分析與角色建立，在一天的時間裡讓學員更貼近劇場。\r\n\r\n●導演篇\r\n本課程嘗試從業界作品分享，認識一個導演的工作流程，從前期（文本工作、設計會議）、中期（與演員排練）到後期（進劇場後的實戰），從中認識一個導演的基本工序與心態準備。\r\n\r\n●燈光設計篇 \r\n本課程將帶你認識燈光的魅力，運用手邊的小道具與發光玩具，親手設計一場屬於自己的燈光秀，感受光影如何為戲劇增添生命力。\r\n\r\n●舞台監督篇\r\n本課程帶你深入舞臺監督的世界，學會排練管理、技術協調與現場執行，讓演出順利進行！ \r\n', `organizer`='盜火劇團', `address`='新竹縣竹北市縣政九路146號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='新竹縣政府文化局', `latitude`=24.83816209, `longitude`=120.9948704, `ticket_price`='無資料', `source_url`='https://www.voldufeu.com/2025chuwindlesson', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5686526b32418d001b96a', '講座：瓷器上的花卉與寓意', '主講人：廖寶秀；國立故宮博物院器物處前研究員。\r\n歷代以花卉做為陶瓷器的裝飾題材作品十分豐富，南北各地名窯，隨著陶瓷工藝的演進，各擅其能，表現的技法有刻劃、雕印、或描繪施彩等，將其佈置成園景花卉、折枝花卉、盆景花卉、或瓶花裝飾等，美不勝收。其花卉裝飾的選材，有的是表現四時節令、有的則富於吉祥寓意，各具意態。\r\n各季節不同的花卉，除表示歲月的更迭之外，亦彰顯節氣節令的慶祝，如歲朝、花朝、端午、重陽等，因此帶有寓意的花卉紋陶瓷器也成為廣受歡迎的重要器皿。', '國立故宮博物院', '嘉義縣太保市故宮大道888號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '國立故宮博物院南部院區', 23.4704066, 120.2913281, '無資料', 'https://south.npm.gov.tw/ActivityInfoDetailC003210.aspx?Cond=7ceef1c9-e63d-4e26-92d3-3431e6018480&ap', '[]') ON DUPLICATE KEY UPDATE `activity_name`='講座：瓷器上的花卉與寓意', `description`='主講人：廖寶秀；國立故宮博物院器物處前研究員。\r\n歷代以花卉做為陶瓷器的裝飾題材作品十分豐富，南北各地名窯，隨著陶瓷工藝的演進，各擅其能，表現的技法有刻劃、雕印、或描繪施彩等，將其佈置成園景花卉、折枝花卉、盆景花卉、或瓶花裝飾等，美不勝收。其花卉裝飾的選材，有的是表現四時節令、有的則富於吉祥寓意，各具意態。\r\n各季節不同的花卉，除表示歲月的更迭之外，亦彰顯節氣節令的慶祝，如歲朝、花朝、端午、重陽等，因此帶有寓意的花卉紋陶瓷器也成為廣受歡迎的重要器皿。', `organizer`='國立故宮博物院', `address`='嘉義縣太保市故宮大道888號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='國立故宮博物院南部院區', `latitude`=23.4704066, `longitude`=120.2913281, `ticket_price`='無資料', `source_url`='https://south.npm.gov.tw/ActivityInfoDetailC003210.aspx?Cond=7ceef1c9-e63d-4e26-92d3-3431e6018480&ap', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5686526b32418d001b96b', '花徑浮影 - 莊道明創作展', '對我來說，繪畫最迷人的地方，正是那些跳脫預設的直覺和各種意料之外的發現。為了持續在創作中保有新鮮感，ㄧ直以來我嘗試以多樣的繪製手法，讓每一次繪畫的過程都充滿想像的可能。\r\n\r\n本次展覽「花徑浮影」涵蓋了三個系列：歲花季、撕繪畫與創世紀。而這三個系列也分別運用了不同的創作方式。在歲花季中，我通過影像編輯的方式來重組花型，表現介於似花非花的抽象語境；撕繪畫則以撕下紙膠帶的動作為核心，採用非控制的繪製程序，感受創作中那些出乎意料的瞬間；創世紀則運用刮線和色塊的疊加，模擬靈感正在醞釀，創造正在發生，想像開始具象化的過程。\r\n\r\n這三個系列雖然在創作手法上各異，但它們想要追求的創作方向卻是ㄧ致的，也就是製造出看似清晰同時卻被打破與穿透的視覺狀態，使想像才剛剛成形的瞬間，便開始流動、變化，並持續延伸，帶來難以言喻的微妙感受。這正是繪畫最迷人的特質，也是我不斷創作的熱情所在。\r\n', '新竹縣竹東鎮名冠藝術館', '新竹縣竹東鎮忠孝街95號(美之城)', '2025-03-08 00:00:00', '2025-04-26 00:00:00', '新竹縣竹東鎮名冠藝術館', 24.73075802, 121.0753632, '無資料', 'https://sunnyartmuseum.blogspot.com/2025/02/blog-post.html', '[]') ON DUPLICATE KEY UPDATE `activity_name`='花徑浮影 - 莊道明創作展', `description`='對我來說，繪畫最迷人的地方，正是那些跳脫預設的直覺和各種意料之外的發現。為了持續在創作中保有新鮮感，ㄧ直以來我嘗試以多樣的繪製手法，讓每一次繪畫的過程都充滿想像的可能。\r\n\r\n本次展覽「花徑浮影」涵蓋了三個系列：歲花季、撕繪畫與創世紀。而這三個系列也分別運用了不同的創作方式。在歲花季中，我通過影像編輯的方式來重組花型，表現介於似花非花的抽象語境；撕繪畫則以撕下紙膠帶的動作為核心，採用非控制的繪製程序，感受創作中那些出乎意料的瞬間；創世紀則運用刮線和色塊的疊加，模擬靈感正在醞釀，創造正在發生，想像開始具象化的過程。\r\n\r\n這三個系列雖然在創作手法上各異，但它們想要追求的創作方向卻是ㄧ致的，也就是製造出看似清晰同時卻被打破與穿透的視覺狀態，使想像才剛剛成形的瞬間，便開始流動、變化，並持續延伸，帶來難以言喻的微妙感受。這正是繪畫最迷人的特質，也是我不斷創作的熱情所在。\r\n', `organizer`='新竹縣竹東鎮名冠藝術館', `address`='新竹縣竹東鎮忠孝街95號(美之城)', `start_date`='2025-03-08 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='新竹縣竹東鎮名冠藝術館', `latitude`=24.73075802, `longitude`=121.0753632, `ticket_price`='無資料', `source_url`='https://sunnyartmuseum.blogspot.com/2025/02/blog-post.html', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5686526b32418d001b96c', 'FUN心聽故事(美濃分館114年3月)', '由故事媽媽取材繪本故事來帶領小朋友，從不同故事內容去瞭解各自所含意境及學習其繪本正面所帶來影響，透過老師豐富的肢體動作與帶動唱，透過簡單的律動營造歡樂的故事情境。', '高雄市立圖書館總館', '高雄市美濃區6鄰中正路一段59號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '高雄市立圖書館美濃分館', 22.9001672, 120.5418427, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽故事(美濃分館114年3月)', `description`='由故事媽媽取材繪本故事來帶領小朋友，從不同故事內容去瞭解各自所含意境及學習其繪本正面所帶來影響，透過老師豐富的肢體動作與帶動唱，透過簡單的律動營造歡樂的故事情境。', `organizer`='高雄市立圖書館總館', `address`='高雄市美濃區6鄰中正路一段59號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='高雄市立圖書館美濃分館', `latitude`=22.9001672, `longitude`=120.5418427, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
