INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5686526b32418d001b96e', '【春天的花蕊】台語主題書展', '本次書展以詩人路寒袖著名的台語詩歌「春天的花蕊」為活動名稱，旨在象徵台語文化與本土精神的傳承，透過精選的台語文學作品，帶領讀者探索台語的豐富歷史與文化，書展內容將涵蓋詩詞、小說、散文、兒童書籍。', '高雄市立圖書館總館', '高雄市鳳山區24鄰中崙5路1號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '高雄市立圖書館中崙分館', 22.601569, 120.349661, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【春天的花蕊】台語主題書展', `description`='本次書展以詩人路寒袖著名的台語詩歌「春天的花蕊」為活動名稱，旨在象徵台語文化與本土精神的傳承，透過精選的台語文學作品，帶領讀者探索台語的豐富歷史與文化，書展內容將涵蓋詩詞、小說、散文、兒童書籍。', `organizer`='高雄市立圖書館總館', `address`='高雄市鳳山區24鄰中崙5路1號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='高雄市立圖書館中崙分館', `latitude`=22.601569, `longitude`=120.349661, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
