INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5686526b32418d001b973', 'fun心聽故事 (114年03月份)', '由故事達人於圖書館內辦理主題故事說演活動，並透過故事導讀，提起學齡前幼兒對繪本故事的興趣與表達自己對故事內容的想像與創造。', '高雄市立圖書館總館', '高雄市永安區005鄰永華路49號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '高雄市立圖書館永安分館', 22.8159848, 120.2244381, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='fun心聽故事 (114年03月份)', `description`='由故事達人於圖書館內辦理主題故事說演活動，並透過故事導讀，提起學齡前幼兒對繪本故事的興趣與表達自己對故事內容的想像與創造。', `organizer`='高雄市立圖書館總館', `address`='高雄市永安區005鄰永華路49號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='高雄市立圖書館永安分館', `latitude`=22.8159848, `longitude`=120.2244381, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5686526b32418d001b974', '台語書展-「傳承母語  愛我家鄉」', '本次書展以台語文學與文化為核心，精選豐富的台語書籍，包括台語詩歌、小說、散文及文化研究等，帶領讀者探索台灣在地語言的美學與力量。', '高雄市立圖書館總館', '高雄市永安區005鄰永華路49號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '高雄市立圖書館永安分館', 22.8159848, 120.2244381, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台語書展-「傳承母語  愛我家鄉」', `description`='本次書展以台語文學與文化為核心，精選豐富的台語書籍，包括台語詩歌、小說、散文及文化研究等，帶領讀者探索台灣在地語言的美學與力量。', `organizer`='高雄市立圖書館總館', `address`='高雄市永安區005鄰永華路49號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='高雄市立圖書館永安分館', `latitude`=22.8159848, `longitude`=120.2244381, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5686526b32418d001b975', '世界母語日：“女人心”台語歌謠音樂會：悠揚歌聲中的文化與情感', '利用婦女節當天透過與女性相關的台語歌謠的演出，帶領觀眾穿越時光，感受台灣在地文化與歷史記憶。音樂會邀請台語素人歌手及鍵盤老師現場演出，以生動的歌聲與動人的旋律，展現台灣特有的音樂風采，並邀請民眾一同樂。從傳統到現代，讓參與者不僅沉浸於歌聲中，也更了解台語歌謠背後的文化故事。', '高雄市立圖書館總館', '高雄市永安區005鄰永華路49號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '高雄市立圖書館永安分館', 22.8159848, 120.2244381, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='世界母語日：“女人心”台語歌謠音樂會：悠揚歌聲中的文化與情感', `description`='利用婦女節當天透過與女性相關的台語歌謠的演出，帶領觀眾穿越時光，感受台灣在地文化與歷史記憶。音樂會邀請台語素人歌手及鍵盤老師現場演出，以生動的歌聲與動人的旋律，展現台灣特有的音樂風采，並邀請民眾一同樂。從傳統到現代，讓參與者不僅沉浸於歌聲中，也更了解台語歌謠背後的文化故事。', `organizer`='高雄市立圖書館總館', `address`='高雄市永安區005鄰永華路49號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='高雄市立圖書館永安分館', `latitude`=22.8159848, `longitude`=120.2244381, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5686626b32418d001b976', '第17屆草草戲劇節《以上與未滿》', '草草戲劇節邁入第17年，在這個眾多文本中主人翁開始探索未來的徬徨少年時，我們想談生命裡頭必然存在的各種模糊與流動——來回擺盪的念頭、難以定義的關係、無以名狀的情感，正是這些處於界線之間的反覆思索與試探，一次次地形塑了後來最真實的我們。\r\n活動結合戲劇、展覽、市集與影展的藝術展演平台，在逐年累積的品牌效益下，成為雲嘉南地區最具代表性的戲劇節慶活動。', '嘉義縣文化觀光局', '嘉義縣民雄鄉建國路二段265號', '2025-03-15 00:00:00', '2025-03-23 00:00:00', '嘉義縣表演藝術中心', 23.54255347, 120.4442798, '全票+300;全票+800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第17屆草草戲劇節《以上與未滿》', `description`='草草戲劇節邁入第17年，在這個眾多文本中主人翁開始探索未來的徬徨少年時，我們想談生命裡頭必然存在的各種模糊與流動——來回擺盪的念頭、難以定義的關係、無以名狀的情感，正是這些處於界線之間的反覆思索與試探，一次次地形塑了後來最真實的我們。\r\n活動結合戲劇、展覽、市集與影展的藝術展演平台，在逐年累積的品牌效益下，成為雲嘉南地區最具代表性的戲劇節慶活動。', `organizer`='嘉義縣文化觀光局', `address`='嘉義縣民雄鄉建國路二段265號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='嘉義縣表演藝術中心', `latitude`=23.54255347, `longitude`=120.4442798, `ticket_price`='全票+300;全票+800', `source_url`='https://www.opentix.life/', `image_url`='[]';
