INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c624e426b32418d001b9bc', '【基北北桃台語家庭意識培力講座】台北場—Ná真熟sāi，koh無了解 ——台語意識你ài知', '【基北北桃台語家庭意識培力講座】\r\n\r\n台北場—Ná真熟sāi，koh無了解 ——台語意識你ài知\r\n\r\n\r\n費用：免費參加，請先報名，實名制。\r\n報名網址  https://forms.gle/rq5d2AA9wrx1TZtx5\r\n\r\n台語使用比例:100%\r\n預計認列點數:2\r\n#配合文化部培育台語家庭計畫集點  ＃文化部國家語言整體發展方案支持\r\n\r\n主講人：林佳怡\r\n國家教育研究院語譯中心助理研究員\r\n\r\n\r\n內容：台語hōo真濟人感覺熟sāi koh生份，是按怎khah早是台灣ê共通語，suah變做需要保護ê弱勢語言？Lán對台語ê了解有偌濟？Kám有影ē-tàng用全台語生活？Tsit場講座除了討論tsia-ê問題，mā ē講台語ê基礎智識，招逐家做伙kā台語khioh--tńg-來！\r\n\r\n\r\n\r\n▎活動時間：2025/3/15(拜六) 下晡2:00～4:00\r\n\r\n▎名額：網路報名25人\r\n\r\n▎地點：市民書店 (台北市松山區市民大道四段25號)\r\n\r\n\r\n\r\n\r\n洽詢電話：02-23112199\r\n聯絡信箱：bongpo1996@gmail.com\r\n\r\n\r\n主辦單位：李江却台語文教基金會\r\n\r\n補助單位：文化部\r\n\r\n\r\n\r\n------------------------------\r\n\r\n題目：若真熟似，閣無了解——台語意識你愛知\r\n\r\n內容：台語讓很多人覺得既熟悉又陌生，為什麼曾經是臺灣的共通語，會變成需要保護的弱勢語言呢？我們對台語的了解有多少？真的能用全台語生活嗎？本場講座除了討論以上問題，也會講解台語的基礎知識，邀請大家一起把台語撿回來！\r\n\r\n------------------------------\r\n\r\n台語家庭集點計劃：上「國家語言數位資訊網」，進入台語家庭會員平台，登錄成做預備台語家庭，每一个人lóng ài先申請會員口座(身分證抑是健保卡電子檔)，其中一位綁定厝內人，選擇「台語學習/文化家庭」，開始報名活動kah課程，集點換台語獎勵金、抽獎機會。\r\n\r\n台語家庭會員平台常見問題  https://tg.moc.gov.tw/ptgl-user-service/faq-login.html\r\n\r\n--------------------------------\r\n\r\n歡迎捐款贊助　#李江却台語文教基金會　\r\n（捐款可抵稅，匯款後請通知02-23112199）\r\n線上捐款(定期定額)\r\nhttps://donate.newebpay.com/Period/akhioh/lkk\r\n線上捐款(單筆)\r\nhttps://donate.newebpay.com/akhioh/lkk\r\n\r\n郵政劃撥：19021486\r\n戶名：財團法人李江却台語文教基金會\r\n\r\n電匯：123-20-050514-2 華南銀行士林分行活儲\r\n戶名：財團法人李江却台語文教基金會', '李江却台語文教基金會', '臺北市松山區', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '松山區（臺北市）=', 25.05999101, 121.5575876, '無資料', 'https://www.tgb.org.tw/2025/02/nasaikoh-ai.html', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【基北北桃台語家庭意識培力講座】台北場—Ná真熟sāi，koh無了解 ——台語意識你ài知', `description`='【基北北桃台語家庭意識培力講座】\r\n\r\n台北場—Ná真熟sāi，koh無了解 ——台語意識你ài知\r\n\r\n\r\n費用：免費參加，請先報名，實名制。\r\n報名網址  https://forms.gle/rq5d2AA9wrx1TZtx5\r\n\r\n台語使用比例:100%\r\n預計認列點數:2\r\n#配合文化部培育台語家庭計畫集點  ＃文化部國家語言整體發展方案支持\r\n\r\n主講人：林佳怡\r\n國家教育研究院語譯中心助理研究員\r\n\r\n\r\n內容：台語hōo真濟人感覺熟sāi koh生份，是按怎khah早是台灣ê共通語，suah變做需要保護ê弱勢語言？Lán對台語ê了解有偌濟？Kám有影ē-tàng用全台語生活？Tsit場講座除了討論tsia-ê問題，mā ē講台語ê基礎智識，招逐家做伙kā台語khioh--tńg-來！\r\n\r\n\r\n\r\n▎活動時間：2025/3/15(拜六) 下晡2:00～4:00\r\n\r\n▎名額：網路報名25人\r\n\r\n▎地點：市民書店 (台北市松山區市民大道四段25號)\r\n\r\n\r\n\r\n\r\n洽詢電話：02-23112199\r\n聯絡信箱：bongpo1996@gmail.com\r\n\r\n\r\n主辦單位：李江却台語文教基金會\r\n\r\n補助單位：文化部\r\n\r\n\r\n\r\n------------------------------\r\n\r\n題目：若真熟似，閣無了解——台語意識你愛知\r\n\r\n內容：台語讓很多人覺得既熟悉又陌生，為什麼曾經是臺灣的共通語，會變成需要保護的弱勢語言呢？我們對台語的了解有多少？真的能用全台語生活嗎？本場講座除了討論以上問題，也會講解台語的基礎知識，邀請大家一起把台語撿回來！\r\n\r\n------------------------------\r\n\r\n台語家庭集點計劃：上「國家語言數位資訊網」，進入台語家庭會員平台，登錄成做預備台語家庭，每一个人lóng ài先申請會員口座(身分證抑是健保卡電子檔)，其中一位綁定厝內人，選擇「台語學習/文化家庭」，開始報名活動kah課程，集點換台語獎勵金、抽獎機會。\r\n\r\n台語家庭會員平台常見問題  https://tg.moc.gov.tw/ptgl-user-service/faq-login.html\r\n\r\n--------------------------------\r\n\r\n歡迎捐款贊助　#李江却台語文教基金會　\r\n（捐款可抵稅，匯款後請通知02-23112199）\r\n線上捐款(定期定額)\r\nhttps://donate.newebpay.com/Period/akhioh/lkk\r\n線上捐款(單筆)\r\nhttps://donate.newebpay.com/akhioh/lkk\r\n\r\n郵政劃撥：19021486\r\n戶名：財團法人李江却台語文教基金會\r\n\r\n電匯：123-20-050514-2 華南銀行士林分行活儲\r\n戶名：財團法人李江却台語文教基金會', `organizer`='李江却台語文教基金會', `address`='臺北市松山區', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='松山區（臺北市）=', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='https://www.tgb.org.tw/2025/02/nasaikoh-ai.html', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c624e426b32418d001b9bd', '2025焦點舞團：狂潮計劃', '2025焦點舞團【狂潮計劃】Tempestuous 由藝術總監蔣秋娥、行政總監林佳鋒、技術總監吳文安率領北藝大舞蹈系二十四位團員，在行政與演出兼顧下，歷經一年的籌備，將帶來精采豐富的節目，包含兩首大師作與八首新銳作品，在臺灣北中南進行巡迴演出。\r\n', '焦點舞團', '嘉義縣民雄鄉建國路二段265號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '嘉義縣表演藝術中心', 23.54255347, 120.4442798, '全票+400;全票+600;全票+1000', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025焦點舞團：狂潮計劃', `description`='2025焦點舞團【狂潮計劃】Tempestuous 由藝術總監蔣秋娥、行政總監林佳鋒、技術總監吳文安率領北藝大舞蹈系二十四位團員，在行政與演出兼顧下，歷經一年的籌備，將帶來精采豐富的節目，包含兩首大師作與八首新銳作品，在臺灣北中南進行巡迴演出。\r\n', `organizer`='焦點舞團', `address`='嘉義縣民雄鄉建國路二段265號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='嘉義縣表演藝術中心', `latitude`=23.54255347, `longitude`=120.4442798, `ticket_price`='全票+400;全票+600;全票+1000', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c624e426b32418d001b9be', '時代劇場：當代影像的複數演繹', '「時代劇場：當代影像的複數演繹」（簡稱「時代劇場」）展覽關注在科技快速進展下，報導攝影從類比時代專業的攝影技術發展至人手一機的數位攝影時代，從紙媒到數位平台以至數位演算所生產的數位影像，從拍攝者、影像生產與影像內涵所產生的變化與反思。美國觀點藝術先驅索爾．勒維特（Solomon LeWitt，1928- 2007）在《觀念藝術散敘》中提到「觀念成為製造藝術的機器」的概念，也正是當代紀實攝影的核心價值。\r\n\r\n展覽以日本攝影家杉本博司《劇院》系列為隱喻，反思創作者、攝相機功能、攝影與時間、影像生產之間的關係。進入數位影像的時代，當代攝影家基本上採取一種反報導（anti-reportage）的創作方式，改變與放慢先前報導攝影的拍攝節奏、不那麼重視決定性瞬間與衝突時刻、或使用中片幅或大片幅相機，試圖以一種設想周全的、沈思的態度，以風格化的手法呈現其主觀的世界。\r\n\r\n蘇珊．桑塔格（Susan Sontag）於《論攝影》（On Photography）指出：「攝影本身無法解釋任何事情，但卻是無窮無盡的演繹、推測和幻想的邀請。」展覽從「持攝相機的拍攝者」、與「使用攝相機影像紀錄的創作者」兩個面向，與涵蓋「隱形的主角」、「轉變與重生」、「視覺風景」等3項子題，從攝影作為一門藝術類型所具有的獨特屬性，透過17位藝術家的攝影、動態影像、影像裝置、攝影劇場、攝影電影等多元化的作品，探討當代紀實影像所反映的現實為何，與再思考之於人類社會的觀點、影響及義意。\r\n\r\n展演者︰張乾琦、周慶輝、全明遠、何經泰、謝三泰、劉振祥、羅晟文、沈昭良/中華民國；石內都、森山大道、西野壯平、杉本博司/日本；盧純澤Suntag Noh/韓國、凱薩琳．歐佩/美國安娜．里德勒/英國；黃海昌/馬來西亞；徐冰/中國\r\n\r\n', '臺北市立美術館', '臺北市中山區中山北路3段181號', '2025-03-29 00:00:00', '2025-07-13 00:00:00', '臺北市立美術館', 25.06969917, 121.5381597, '全票+30;優待票+15', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='時代劇場：當代影像的複數演繹', `description`='「時代劇場：當代影像的複數演繹」（簡稱「時代劇場」）展覽關注在科技快速進展下，報導攝影從類比時代專業的攝影技術發展至人手一機的數位攝影時代，從紙媒到數位平台以至數位演算所生產的數位影像，從拍攝者、影像生產與影像內涵所產生的變化與反思。美國觀點藝術先驅索爾．勒維特（Solomon LeWitt，1928- 2007）在《觀念藝術散敘》中提到「觀念成為製造藝術的機器」的概念，也正是當代紀實攝影的核心價值。\r\n\r\n展覽以日本攝影家杉本博司《劇院》系列為隱喻，反思創作者、攝相機功能、攝影與時間、影像生產之間的關係。進入數位影像的時代，當代攝影家基本上採取一種反報導（anti-reportage）的創作方式，改變與放慢先前報導攝影的拍攝節奏、不那麼重視決定性瞬間與衝突時刻、或使用中片幅或大片幅相機，試圖以一種設想周全的、沈思的態度，以風格化的手法呈現其主觀的世界。\r\n\r\n蘇珊．桑塔格（Susan Sontag）於《論攝影》（On Photography）指出：「攝影本身無法解釋任何事情，但卻是無窮無盡的演繹、推測和幻想的邀請。」展覽從「持攝相機的拍攝者」、與「使用攝相機影像紀錄的創作者」兩個面向，與涵蓋「隱形的主角」、「轉變與重生」、「視覺風景」等3項子題，從攝影作為一門藝術類型所具有的獨特屬性，透過17位藝術家的攝影、動態影像、影像裝置、攝影劇場、攝影電影等多元化的作品，探討當代紀實影像所反映的現實為何，與再思考之於人類社會的觀點、影響及義意。\r\n\r\n展演者︰張乾琦、周慶輝、全明遠、何經泰、謝三泰、劉振祥、羅晟文、沈昭良/中華民國；石內都、森山大道、西野壯平、杉本博司/日本；盧純澤Suntag Noh/韓國、凱薩琳．歐佩/美國安娜．里德勒/英國；黃海昌/馬來西亞；徐冰/中國\r\n\r\n', `organizer`='臺北市立美術館', `address`='臺北市中山區中山北路3段181號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-07-13 00:00:00', `location`='臺北市立美術館', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='全票+30;優待票+15', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c624e426b32418d001b9bf', '展覽漫遊77｜黑潮:賴純純回顧展 ', '隨著展間移動，藝術家和策展人將透過漫步對談，與觀眾分享創作生涯中的國際移動、在台灣的移動，來談論創作階段和觀點的轉變，以至匯聚為多元且自由的個人色彩。「我們的前面是什麼？」不僅是藝術家早期創作的啟蒙觀點之一，也是創作生涯不斷推進的提問和趨力。賴純純的作品從不設限，自由地探詢世界於心的觸動，化為造形。本次「展覽漫遊」將帶領觀眾共同泅泳於賴純純創作的「黑潮」，一起發現「我們的前面是什麼」。', '臺北市立美術館', '臺北市中山區中山北路3段181號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺北市立美術館', 25.06969917, 121.5381597, '全票+30;優待票+15', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='展覽漫遊77｜黑潮:賴純純回顧展 ', `description`='隨著展間移動，藝術家和策展人將透過漫步對談，與觀眾分享創作生涯中的國際移動、在台灣的移動，來談論創作階段和觀點的轉變，以至匯聚為多元且自由的個人色彩。「我們的前面是什麼？」不僅是藝術家早期創作的啟蒙觀點之一，也是創作生涯不斷推進的提問和趨力。賴純純的作品從不設限，自由地探詢世界於心的觸動，化為造形。本次「展覽漫遊」將帶領觀眾共同泅泳於賴純純創作的「黑潮」，一起發現「我們的前面是什麼」。', `organizer`='臺北市立美術館', `address`='臺北市中山區中山北路3段181號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺北市立美術館', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='全票+30;優待票+15', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c624e426b32418d001b9c0', '展覽漫遊78｜黑潮:賴純純回顧展', '自1980年代開始以複合媒材創作，賴純純就表現亮眼，接連獲得台北市立美術館舉辦的繪畫新展望優選獎以及現代雕塑首獎。此後，在不同時代、不同生命階段，其藝術面貌都有轉變，類型涵蓋平面繪畫、立體雕塑、空間裝置到觀念行動等，2000年起投入公共藝術，創造力豐盈充沛。\r\n\r\n除此，1986年成立「SOCA藝術工作室」推廣前衛藝術，為台灣「替代空間」的先聲；2000年發起「臺灣女性藝術家協會」匯集女性力量，皆為社會參與的踐行。\r\n\r\n藝術，是賴純純對生命的實踐，也是她對女性主體性的堅定追求，因為無懼，藝術得以生生不息的創造；因為自由，她的創作型態多元不限。賴純純近半世紀的創作生涯錘鍊打造個人的「WONDERLAND」，也讓人看見一位女性擁抱藝術與生命「閃亮的愛」。\r\n', '臺北市立美術館', '臺北市中山區中山北路3段181號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '臺北市立美術館', 25.06969917, 121.5381597, '全票+30;優待票+15', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='展覽漫遊78｜黑潮:賴純純回顧展', `description`='自1980年代開始以複合媒材創作，賴純純就表現亮眼，接連獲得台北市立美術館舉辦的繪畫新展望優選獎以及現代雕塑首獎。此後，在不同時代、不同生命階段，其藝術面貌都有轉變，類型涵蓋平面繪畫、立體雕塑、空間裝置到觀念行動等，2000年起投入公共藝術，創造力豐盈充沛。\r\n\r\n除此，1986年成立「SOCA藝術工作室」推廣前衛藝術，為台灣「替代空間」的先聲；2000年發起「臺灣女性藝術家協會」匯集女性力量，皆為社會參與的踐行。\r\n\r\n藝術，是賴純純對生命的實踐，也是她對女性主體性的堅定追求，因為無懼，藝術得以生生不息的創造；因為自由，她的創作型態多元不限。賴純純近半世紀的創作生涯錘鍊打造個人的「WONDERLAND」，也讓人看見一位女性擁抱藝術與生命「閃亮的愛」。\r\n', `organizer`='臺北市立美術館', `address`='臺北市中山區中山北路3段181號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='臺北市立美術館', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='全票+30;優待票+15', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c624e426b32418d001b9c1', '展覽漫遊79｜黑潮:賴純純回顧展', '賴純純的創作基調，來自於1980年代框架解放的前衛藝術潮流。藝術表現不再僅止於畫框及台座內的封閉空間，而是實際與觀眾同在的空間與材質。材質是她探觸世界的介質，藉由材質引介她由自然的所得。但不必過度牽掛於材質，在材質信步閒走後，能夠循著自然的韻律才是重點。材質，不再是作品裡為人作嫁的透明元素，而是收放著內涵的自在。她的創作從自然的萬千世界而來，展現著變化，在簡潔中跳耀著色彩。透過 「存在與變化」韻律的覺察，她藉著東方美學、宗教反覆咀嚼著自然的況味。於是自然而然地，她來到了山與太平洋交會的都蘭，每日放眼的景象變化，在她作品中散發著光，於是材質與色彩愈發地輕盈。', '臺北市立美術館', '臺北市中山區中山北路3段181號', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '臺北市立美術館', 25.06969917, 121.5381597, '全票+30;優待票+15', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='展覽漫遊79｜黑潮:賴純純回顧展', `description`='賴純純的創作基調，來自於1980年代框架解放的前衛藝術潮流。藝術表現不再僅止於畫框及台座內的封閉空間，而是實際與觀眾同在的空間與材質。材質是她探觸世界的介質，藉由材質引介她由自然的所得。但不必過度牽掛於材質，在材質信步閒走後，能夠循著自然的韻律才是重點。材質，不再是作品裡為人作嫁的透明元素，而是收放著內涵的自在。她的創作從自然的萬千世界而來，展現著變化，在簡潔中跳耀著色彩。透過 「存在與變化」韻律的覺察，她藉著東方美學、宗教反覆咀嚼著自然的況味。於是自然而然地，她來到了山與太平洋交會的都蘭，每日放眼的景象變化，在她作品中散發著光，於是材質與色彩愈發地輕盈。', `organizer`='臺北市立美術館', `address`='臺北市中山區中山北路3段181號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='臺北市立美術館', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='全票+30;優待票+15', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c624e426b32418d001b9c2', '「靜‧物」開幕特別活動', '靜·物｜開幕特別活動\r\n2025年3月22日（六）14:00-16:30\r\n臺北市立美術館兒童藝術教育中心\r\n活動免費參加 · 入館請依本館購票辦法購票\r\n\r\n\r\n「Photogram物件投影：和我⼀起⽣活的夥伴」工作坊（請點此報名）\r\n帶著一起生活的夥伴，與藝術家共同製作實物投影，創造屬於自己的靜物作品。\r\n時間｜14:00-15:00、15:30-16:30\r\n地點｜大工作坊\r\n活動對象｜1+1親子（6-12歲小朋友）\r\n參加辦法｜須事先預約（3月10日上午10:00開放報名）\r\n\r\n策展人導覽\r\n大手牽小手，跟著策展人進入靜物畫作中，一同拆解靜物，體驗一場藝術饗宴。\r\n時間｜15:00-16:00\r\n地點｜請於活動前5分鐘至地下樓諮詢台集合\r\n活動對象｜親子觀眾\r\n參加辦法｜不須預約', '臺北市立美術館', '臺北市中山區中山北路3段181號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺北市立美術館', 25.06969917, 121.5381597, '全票+30;優待票+15', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「靜‧物」開幕特別活動', `description`='靜·物｜開幕特別活動\r\n2025年3月22日（六）14:00-16:30\r\n臺北市立美術館兒童藝術教育中心\r\n活動免費參加 · 入館請依本館購票辦法購票\r\n\r\n\r\n「Photogram物件投影：和我⼀起⽣活的夥伴」工作坊（請點此報名）\r\n帶著一起生活的夥伴，與藝術家共同製作實物投影，創造屬於自己的靜物作品。\r\n時間｜14:00-15:00、15:30-16:30\r\n地點｜大工作坊\r\n活動對象｜1+1親子（6-12歲小朋友）\r\n參加辦法｜須事先預約（3月10日上午10:00開放報名）\r\n\r\n策展人導覽\r\n大手牽小手，跟著策展人進入靜物畫作中，一同拆解靜物，體驗一場藝術饗宴。\r\n時間｜15:00-16:00\r\n地點｜請於活動前5分鐘至地下樓諮詢台集合\r\n活動對象｜親子觀眾\r\n參加辦法｜不須預約', `organizer`='臺北市立美術館', `address`='臺北市中山區中山北路3段181號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺北市立美術館', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='全票+30;優待票+15', `source_url`='無資料', `image_url`='[]';
