INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c773e226b32408680be8d7', '2025南風高揚—台南市師美學會與高雄市藝術聯盟畫會交流展', '臺南市師美學會與高雄藝術聯盟畫會分別成立於1997年與1985年，兩會主要成員主要由由國立臺灣師範大學美術學系及美術研究所畢業校友所組成，會員們除了在各級學校、學術單位、私人畫室與產業界等各行業機構從事美術教育的深耕與傳承，作育無數英才，同時也持續不斷堅守著藝術創作之實踐，每年定期合作舉辦畫展，增進會員情感聯誼，切磋畫藝，對外發表新作品，會員們在藝術家與教育者的雙重身份之間，游刃於藝界而追求更高境界之自我理想實現。', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-03-21 00:00:00', '2025-04-06 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025南風高揚—台南市師美學會與高雄市藝術聯盟畫會交流展', `description`='臺南市師美學會與高雄藝術聯盟畫會分別成立於1997年與1985年，兩會主要成員主要由由國立臺灣師範大學美術學系及美術研究所畢業校友所組成，會員們除了在各級學校、學術單位、私人畫室與產業界等各行業機構從事美術教育的深耕與傳承，作育無數英才，同時也持續不斷堅守著藝術創作之實踐，每年定期合作舉辦畫展，增進會員情感聯誼，切磋畫藝，對外發表新作品，會員們在藝術家與教育者的雙重身份之間，游刃於藝界而追求更高境界之自我理想實現。', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c773e826b32408680be8d8', '臺南市東區裕文圖書館- 114年3月 小葫蘆歡樂唱遊', '由志工老師精心挑選優質繪本，推廣親子共讀，帶領孩子一起進入書中世界，同時會在故事結束後增加一些小手作，讓孩子聽得開心、玩得開心。 \r\n3/5 情緒大飯店 (性平) 圓圓阿姨 \r\n3/12 章魚先生買褲子 小蟲子阿姨 \r\n3/19 我的身體哪裡最重要(性平) Apple 阿姨 \r\n3/26 小蛇肚子咕嚕嚕 餅乾阿姨\r\n', '臺南市東區裕文圖書館', '臺南市東區裕信路237號', '2025-03-05 00:00:00', '2025-03-26 00:00:00', '臺南市東區裕文圖書館', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市東區裕文圖書館- 114年3月 小葫蘆歡樂唱遊', `description`='由志工老師精心挑選優質繪本，推廣親子共讀，帶領孩子一起進入書中世界，同時會在故事結束後增加一些小手作，讓孩子聽得開心、玩得開心。 \r\n3/5 情緒大飯店 (性平) 圓圓阿姨 \r\n3/12 章魚先生買褲子 小蟲子阿姨 \r\n3/19 我的身體哪裡最重要(性平) Apple 阿姨 \r\n3/26 小蛇肚子咕嚕嚕 餅乾阿姨\r\n', `organizer`='臺南市東區裕文圖書館', `address`='臺南市東區裕信路237號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺南市東區裕文圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
