INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c773ed26b32408680be8e5', '2024我愛我家世界兒童青少年繪畫比賽得獎作品展', '2024 我愛我家世界兒童青少年繪畫比賽展覽暨開幕茶會」陸續於於2025年3月至5月分別於桃園，新北及台北舉行。主辦單位理事長陳子弘表示，本屆繪畫繪賽的特色其一就是邀請2022 年至2024年前三屆參賽入圍及得獎小朋友的作品參加展覽。\r\n為了讓兒童及青少年畫展能有優質的展覽場地，主辦單位CCTC社團法人中華國際文旅商發展協會及共同主辦單位GJW 美國乾淨世界公司經實際履勘確認展覽場地：桃園場-桃園市文化局，新北場-新北市圖書館樹林分館，台北場-遠東SOGO 北復興館8 樓等場地。本屆繪畫大賽另一特色為：將直播連線美國洛杉磯LA 團體報名之學生、家長及老師，讓活動現場活動無時差分享，見證繪畫大賽的核心價值：家庭、信仰、傳統、倫理以及美學教育無遠弗屆。', '無資料', '桃園市桃園區縣府路21號', '2025-03-05 00:00:00', '2025-03-16 00:00:00', '桃園市政府文化局', 24.994125, 121.300519, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2024我愛我家世界兒童青少年繪畫比賽得獎作品展', `description`='2024 我愛我家世界兒童青少年繪畫比賽展覽暨開幕茶會」陸續於於2025年3月至5月分別於桃園，新北及台北舉行。主辦單位理事長陳子弘表示，本屆繪畫繪賽的特色其一就是邀請2022 年至2024年前三屆參賽入圍及得獎小朋友的作品參加展覽。\r\n為了讓兒童及青少年畫展能有優質的展覽場地，主辦單位CCTC社團法人中華國際文旅商發展協會及共同主辦單位GJW 美國乾淨世界公司經實際履勘確認展覽場地：桃園場-桃園市文化局，新北場-新北市圖書館樹林分館，台北場-遠東SOGO 北復興館8 樓等場地。本屆繪畫大賽另一特色為：將直播連線美國洛杉磯LA 團體報名之學生、家長及老師，讓活動現場活動無時差分享，見證繪畫大賽的核心價值：家庭、信仰、傳統、倫理以及美學教育無遠弗屆。', `organizer`='無資料', `address`='桃園市桃園區縣府路21號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='桃園市政府文化局', `latitude`=24.994125, `longitude`=121.300519, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
