INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c773f326b32408680be8e8', '來自太空的寶石-蕭雅之個展', '由台灣隕寶石隕落帶發現者蕭雅之展出的隕寶石，包括「台灣經營之神與拇指讚」、「十二獸首」、重達3000克的大蟾蜍及「蛇(什)麼都順利」等奇特天然造型，展示隕寶石莫氏硬度7至9的驚人質感與大自然的奇蹟創作。\r\n蕭雅之也將太空隕石的天然光澤結合翡翠，成為美麗健康的墬飾，讓更多蒐藏家一起享有太空能量寶石珍藏的樂趣！', '桃園市立圖書館', '桃園市平鎮區環南路三段88號', '2025-03-03 00:00:00', '2025-03-30 00:00:00', '桃園市立圖書館平鎮分館', 24.92117923, 121.2140051, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='來自太空的寶石-蕭雅之個展', `description`='由台灣隕寶石隕落帶發現者蕭雅之展出的隕寶石，包括「台灣經營之神與拇指讚」、「十二獸首」、重達3000克的大蟾蜍及「蛇(什)麼都順利」等奇特天然造型，展示隕寶石莫氏硬度7至9的驚人質感與大自然的奇蹟創作。\r\n蕭雅之也將太空隕石的天然光澤結合翡翠，成為美麗健康的墬飾，讓更多蒐藏家一起享有太空能量寶石珍藏的樂趣！', `organizer`='桃園市立圖書館', `address`='桃園市平鎮區環南路三段88號', `start_date`='2025-03-03 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='桃園市立圖書館平鎮分館', `latitude`=24.92117923, `longitude`=121.2140051, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c773f426b32408680be8e9', '小百科，請回答！美術工作坊(2場)', '主題：醜蔬果與羊毛氈\r\n以想像力和創造力用軟軟、暖暖的羊毛，讓醜蔬果們變身超可愛的表情和造型！戳出專屬自己獨一無二的可愛醜蔬果吊飾！\r\n課程：\r\n(一)介紹羊毛氈：教學示範及讓學員瞭解製作步驟。\r\n(二)認識醜蔬果：透過製作羊毛氈水果小物。\r\n(三)創意發揮：實際製作，講師會現場協助指導每位學員，順利完成作品。\r\n(四)作品交流分享及大合照。', '桃園市兒童美術館', '桃園市中壢區高鐵南路二段90號', '2025-03-01 00:00:00', '2025-03-15 00:00:00', '桃園市兒童美術館', 24.97993803, 121.2147243, '費用+200', 'https://event.culture.tw/mocweb/reg/TMOFA/Detail.init.ctr?actId=50006', '[]') ON DUPLICATE KEY UPDATE `activity_name`='小百科，請回答！美術工作坊(2場)', `description`='主題：醜蔬果與羊毛氈\r\n以想像力和創造力用軟軟、暖暖的羊毛，讓醜蔬果們變身超可愛的表情和造型！戳出專屬自己獨一無二的可愛醜蔬果吊飾！\r\n課程：\r\n(一)介紹羊毛氈：教學示範及讓學員瞭解製作步驟。\r\n(二)認識醜蔬果：透過製作羊毛氈水果小物。\r\n(三)創意發揮：實際製作，講師會現場協助指導每位學員，順利完成作品。\r\n(四)作品交流分享及大合照。', `organizer`='桃園市兒童美術館', `address`='桃園市中壢區高鐵南路二段90號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='桃園市兒童美術館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='費用+200', `source_url`='https://event.culture.tw/mocweb/reg/TMOFA/Detail.init.ctr?actId=50006', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c773f526b32408680be8ea', '錦飛鳳傀儡戲劇團《迎春納福慶元宵》', '錦飛鳳傀儡戲劇團《迎春納福慶元宵》\r\n\r\n祝幸福與真美滿是一對恩愛又搞笑的夫妻，於過年元宵節慶相偕出遊賞燈觀藝。\r\n東街上有熱鬧的祥獅獻瑞、西街有精采的花童耍球玩特技、南大街有好玩的盪鞦韆、北大街有喜慶的財神獻元寶，夫妻倆觀賞之餘，風趣、幽默的倆人最後還不忘用吉祥話祝福大家一定要「幸福」與「美滿」喔！\r\n ', '無資料', '臺南市鹽水區過港路21號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '臺南市鹽水永成戲院', 23.29798622, 120.2482977, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='錦飛鳳傀儡戲劇團《迎春納福慶元宵》', `description`='錦飛鳳傀儡戲劇團《迎春納福慶元宵》\r\n\r\n祝幸福與真美滿是一對恩愛又搞笑的夫妻，於過年元宵節慶相偕出遊賞燈觀藝。\r\n東街上有熱鬧的祥獅獻瑞、西街有精采的花童耍球玩特技、南大街有好玩的盪鞦韆、北大街有喜慶的財神獻元寶，夫妻倆觀賞之餘，風趣、幽默的倆人最後還不忘用吉祥話祝福大家一定要「幸福」與「美滿」喔！\r\n ', `organizer`='無資料', `address`='臺南市鹽水區過港路21號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='臺南市鹽水永成戲院', `latitude`=23.29798622, `longitude`=120.2482977, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
