INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c773fd26b32408680be8ec', '舞蹈肢體工作坊《舞步單純Ⅳ》(2場)', '當代舞蹈不只是動作，更是生活與人的連結。透過身體接觸，感受重量的交換、肢體的回應，在即興對話中探索舞蹈的可能性。本次工作坊由張堅志老師帶領，從技術訓練到身體覺察，引導學員打開感知，重新認識「人與人之間」的舞蹈語彙。', '君舞蹈劇場', '桃園市中壢區中美路16號', '2025-03-02 00:00:00', '2025-03-09 00:00:00', '中壢藝術館', 24.958126, 121.227384, '單堂+700', 'https://forms.gle/HRhnD2xE3WLDAoXs6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='舞蹈肢體工作坊《舞步單純Ⅳ》(2場)', `description`='當代舞蹈不只是動作，更是生活與人的連結。透過身體接觸，感受重量的交換、肢體的回應，在即興對話中探索舞蹈的可能性。本次工作坊由張堅志老師帶領，從技術訓練到身體覺察，引導學員打開感知，重新認識「人與人之間」的舞蹈語彙。', `organizer`='君舞蹈劇場', `address`='桃園市中壢區中美路16號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='中壢藝術館', `latitude`=24.958126, `longitude`=121.227384, `ticket_price`='單堂+700', `source_url`='https://forms.gle/HRhnD2xE3WLDAoXs6', `image_url`='[]';
