INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7740326b32408680be8f9', '「史特拉底瓦里．傳奇之音」奇美提琴音樂饗宴', '本次音樂會以【史特拉底瓦里．傳奇之音】為主題，演出曲目邀請倫敦國王學院音樂學博士焦元溥規劃，時間跨度從十八到二十世紀約兩百年間的創作，涵蓋義大利、德奧、俄國與法國等不同風格與時期作品，展現史式名琴完美演繹各種曲目與風格的驚人能力；樂器則是由奇美博物館資深提琴顧問鍾岱廷規劃史氏從早期到晚期六把曠世名作，包括《史特拉提琴雜誌》(The Strad) 讚譽擁有最完美音色「瑪麗．霍爾–維奧第」小提琴，及兒子歐莫柏諾極富特色又傑出的作品，加上基羅拉摩．阿瑪蒂（Girolamo Amati, ca. 1550-1630）的中提琴「亨利四世」（Henry IV）等八把奇美殿堂級名琴。演出形式包含開場使用三把小提琴音色比較、提琴二重奏，以及下半場的兩組弦樂四重奏競演；八把名琴首次同臺競技，千載難逢不容錯過！', '財團法人奇美博物館基金會', '臺南市仁德區文華路二段66號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '臺南市奇美博物館', 22.94130931, 120.2418788, '2800 、3300 、3800+--', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「史特拉底瓦里．傳奇之音」奇美提琴音樂饗宴', `description`='本次音樂會以【史特拉底瓦里．傳奇之音】為主題，演出曲目邀請倫敦國王學院音樂學博士焦元溥規劃，時間跨度從十八到二十世紀約兩百年間的創作，涵蓋義大利、德奧、俄國與法國等不同風格與時期作品，展現史式名琴完美演繹各種曲目與風格的驚人能力；樂器則是由奇美博物館資深提琴顧問鍾岱廷規劃史氏從早期到晚期六把曠世名作，包括《史特拉提琴雜誌》(The Strad) 讚譽擁有最完美音色「瑪麗．霍爾–維奧第」小提琴，及兒子歐莫柏諾極富特色又傑出的作品，加上基羅拉摩．阿瑪蒂（Girolamo Amati, ca. 1550-1630）的中提琴「亨利四世」（Henry IV）等八把奇美殿堂級名琴。演出形式包含開場使用三把小提琴音色比較、提琴二重奏，以及下半場的兩組弦樂四重奏競演；八把名琴首次同臺競技，千載難逢不容錯過！', `organizer`='財團法人奇美博物館基金會', `address`='臺南市仁德區文華路二段66號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺南市奇美博物館', `latitude`=22.94130931, `longitude`=120.2418788, `ticket_price`='2800 、3300 、3800+--', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7740426b32408680be8fa', '怪藝-山豐國小第5屆藝術才能美術班畢業美展', '「怪」-不是一個貶抑詞，「怪」是每個人獨有特性。有人怪美的，有人怪帥的，像我們是怪的很另類、各有各的怪特色，這次的展出，將呈現屬於我們的怪藝 !\r\n「怪」這個詞常常被視為負面的標籤，然而，在這次山豐國小第五屆藝才班畢業展，我們重新定義了「怪」。這次展覽的主題《怪藝》，旨在彰顯每個人獨特的個性與特質，「怪」並不是貶抑詞，而是每個人獨有的標誌，而這次展出的作品，正是我們用藝術語言表達出來的與眾不同。', '桃園市平鎮區山豐國民小學', '桃園市中壢區中美路16號', '2025-03-04 00:00:00', '2025-03-16 00:00:00', '中壢藝術館', 24.958126, 121.227384, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='怪藝-山豐國小第5屆藝術才能美術班畢業美展', `description`='「怪」-不是一個貶抑詞，「怪」是每個人獨有特性。有人怪美的，有人怪帥的，像我們是怪的很另類、各有各的怪特色，這次的展出，將呈現屬於我們的怪藝 !\r\n「怪」這個詞常常被視為負面的標籤，然而，在這次山豐國小第五屆藝才班畢業展，我們重新定義了「怪」。這次展覽的主題《怪藝》，旨在彰顯每個人獨特的個性與特質，「怪」並不是貶抑詞，而是每個人獨有的標誌，而這次展出的作品，正是我們用藝術語言表達出來的與眾不同。', `organizer`='桃園市平鎮區山豐國民小學', `address`='桃園市中壢區中美路16號', `start_date`='2025-03-04 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='中壢藝術館', `latitude`=24.958126, `longitude`=121.227384, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
