INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7740926b32408680be900', '桃園市政府文化局114年社區營造補助計畫提案培力課程「社造維他命」', '2025的春天，一起來補充社造能量吧！​\r\n桃園市社造中心精心準備4堂系列培力課程＋4場模擬簡報交流，號召關心公共事務的熱心夥伴，共同來思考生活中面臨的公共議題及打造地方魅力，學習提出具有公民參與力的社造計畫，用行動讓桃園變得更美好！​\r\n採網路報名，受理報名期限至114年3月1日止，填寫線上報名表單https://forms.gle/KxntYAjQ2AqHJb7D7。\r\n時間：四堂系列培力課程：3/04（二）、3/06（四）、3/11（二）、3/13（四）10:00-17:00（共24小時）＆四場模擬簡報交流：3/18（二）、3/20（四）09:00-17:00（共14小時），課程可依各自需求，選擇參與場次。​', '桃園市政府文化局', '桃園市八德區', '2025-03-04 00:00:00', '2025-03-20 00:00:00', '八德區（桃園市）=', 24.94968903, 121.2913102, '無資料', 'https://taidi.tycg.gov.tw/News/NewsInfo/429', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園市政府文化局114年社區營造補助計畫提案培力課程「社造維他命」', `description`='2025的春天，一起來補充社造能量吧！​\r\n桃園市社造中心精心準備4堂系列培力課程＋4場模擬簡報交流，號召關心公共事務的熱心夥伴，共同來思考生活中面臨的公共議題及打造地方魅力，學習提出具有公民參與力的社造計畫，用行動讓桃園變得更美好！​\r\n採網路報名，受理報名期限至114年3月1日止，填寫線上報名表單https://forms.gle/KxntYAjQ2AqHJb7D7。\r\n時間：四堂系列培力課程：3/04（二）、3/06（四）、3/11（二）、3/13（四）10:00-17:00（共24小時）＆四場模擬簡報交流：3/18（二）、3/20（四）09:00-17:00（共14小時），課程可依各自需求，選擇參與場次。​', `organizer`='桃園市政府文化局', `address`='桃園市八德區', `start_date`='2025-03-04 00:00:00', `end_date`='2025-03-20 00:00:00', `location`='八德區（桃園市）=', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='https://taidi.tycg.gov.tw/News/NewsInfo/429', `image_url`='[]';
