INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7740f26b32408680be914', '2025台北國際書展大獎入圍書展', '2025台北國際書展大獎於2024年12月6日公布入圍名單！邁入第18屆的「書展大獎」，徵件限自2023年10月1日起至2024年9月30日（含）期間首次出版之作品參賽，總件數達660件，包括「小說獎」110件，「非小說獎」329件，「兒童及青少年獎」221件。各獎項參賽作品水準精彩，競爭激烈，不僅呈現台灣年度出版趨勢、表彰台灣原創，也希冀透過台北國際書展、全台北中南圖書館串聯展出、線上及實體書展啟動等豐富多元活動，邀請全民矚目樂讀得獎好書。\r\n\r\n \r\n\r\n2025台北國際書展大獎三大獎項入圍名單熱騰騰公布，小說獎、非小說獎、兒童及青少年獎，各獎項入圍10本，選出首獎3本。將於2024年12月19日舉行「書展大獎公布記者會」盛大公布各首獎名單，邀請得主榮耀現身，同時與博客來、誠品、金石堂、HyRead凌網、Readmoo讀墨、三民網路書店等平台舉辦線上書展，誠品及金石堂實體書展同步啟動，以饗讀者，敬請期待！', '文化部', '桃園市觀音區新生路76巷8弄1號2樓之1', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '桃園市立圖書館新坡分館', 25.02671611, 121.1155021, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台北國際書展大獎入圍書展', `description`='2025台北國際書展大獎於2024年12月6日公布入圍名單！邁入第18屆的「書展大獎」，徵件限自2023年10月1日起至2024年9月30日（含）期間首次出版之作品參賽，總件數達660件，包括「小說獎」110件，「非小說獎」329件，「兒童及青少年獎」221件。各獎項參賽作品水準精彩，競爭激烈，不僅呈現台灣年度出版趨勢、表彰台灣原創，也希冀透過台北國際書展、全台北中南圖書館串聯展出、線上及實體書展啟動等豐富多元活動，邀請全民矚目樂讀得獎好書。\r\n\r\n \r\n\r\n2025台北國際書展大獎三大獎項入圍名單熱騰騰公布，小說獎、非小說獎、兒童及青少年獎，各獎項入圍10本，選出首獎3本。將於2024年12月19日舉行「書展大獎公布記者會」盛大公布各首獎名單，邀請得主榮耀現身，同時與博客來、誠品、金石堂、HyRead凌網、Readmoo讀墨、三民網路書店等平台舉辦線上書展，誠品及金石堂實體書展同步啟動，以饗讀者，敬請期待！', `organizer`='文化部', `address`='桃園市觀音區新生路76巷8弄1號2樓之1', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='桃園市立圖書館新坡分館', `latitude`=25.02671611, `longitude`=121.1155021, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7740f26b32408680be917', '114年度新屋區東明社區歌唱班教學活動', '邀請講師教授國台客語流行歌曲演唱技巧，歡迎民眾自由參加。', '桃園市新屋區東明社區發展協會', '桃園市新屋區', '2025-03-04 00:00:00', '2025-08-19 00:00:00', '新屋區（桃園市）=', 24.97280352, 121.067758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度新屋區東明社區歌唱班教學活動', `description`='邀請講師教授國台客語流行歌曲演唱技巧，歡迎民眾自由參加。', `organizer`='桃園市新屋區東明社區發展協會', `address`='桃園市新屋區', `start_date`='2025-03-04 00:00:00', `end_date`='2025-08-19 00:00:00', `location`='新屋區（桃園市）=', `latitude`=24.97280352, `longitude`=121.067758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7740f26b32408680be918', '3月影片欣賞', '片名:湯恩與劍客汪汪隊\r\n身為犬劍士的湯恩希望追隨父親的腳步，成為皇家劍客汪汪隊一員。\r\n在前往巴黎冒險的途中結識了三名驍勇善戰的犬劍客並偶遇美麗的茱麗葉，湯恩與戰友們，不僅要力抗邪惡的紅衣主教及其黨羽，還要阻止英法爆發戰爭。湯恩最終能否成為劍客汪汪隊的一員並贏得佳人的芳心呢？', '臺中市立圖書館太平分館', '臺中市太平區太平三街20號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '臺中市立圖書館太平分館', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/mR80RY', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月影片欣賞', `description`='片名:湯恩與劍客汪汪隊\r\n身為犬劍士的湯恩希望追隨父親的腳步，成為皇家劍客汪汪隊一員。\r\n在前往巴黎冒險的途中結識了三名驍勇善戰的犬劍客並偶遇美麗的茱麗葉，湯恩與戰友們，不僅要力抗邪惡的紅衣主教及其黨羽，還要阻止英法爆發戰爭。湯恩最終能否成為劍客汪汪隊的一員並贏得佳人的芳心呢？', `organizer`='臺中市立圖書館太平分館', `address`='臺中市太平區太平三街20號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='臺中市立圖書館太平分館', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/mR80RY', `image_url`='[]';
