INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741026b32408680be91a', '3月 繪本說故事 (6場)', '大里托育資源行動車-繪本大變身\r\n(合辦單位：大里親子館)\r\n本館透過社區巡迴服務,把0-3歲嬰幼兒免費資源帶入社區中(繪本大變身、親子遊戲、借用服務),借由故事遊戲的領導讓家長與小寶貝們一起學習、親密互動,希望帶親子一個幸福愉快的歡樂時光!\r\n主講人:台中市托育資源行動車人員\r\n\r\n太平貓頭鷹故事屋－說故事活動\r\n每週六由故事志工來講述兒童文學主題及手作帶給親子們一個快樂的週未時光\r\n主講人:太平貓頭鷹故事屋', '臺中市立圖書館太平分館', '臺中市太平區太平三街20號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '臺中市立圖書館太平分館', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/zp3Dnp', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月 繪本說故事 (6場)', `description`='大里托育資源行動車-繪本大變身\r\n(合辦單位：大里親子館)\r\n本館透過社區巡迴服務,把0-3歲嬰幼兒免費資源帶入社區中(繪本大變身、親子遊戲、借用服務),借由故事遊戲的領導讓家長與小寶貝們一起學習、親密互動,希望帶親子一個幸福愉快的歡樂時光!\r\n主講人:台中市托育資源行動車人員\r\n\r\n太平貓頭鷹故事屋－說故事活動\r\n每週六由故事志工來講述兒童文學主題及手作帶給親子們一個快樂的週未時光\r\n主講人:太平貓頭鷹故事屋', `organizer`='臺中市立圖書館太平分館', `address`='臺中市太平區太平三街20號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市立圖書館太平分館', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/zp3Dnp', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741026b32408680be91b', '3月 臺語說故事 (2場)', '台語說故事爸媽-我本來就足愛汝阿!\r\n用閩南語說好故事，傳承閩南文化\r\n\r\n作伙來講古\r\n每週六由故事志工來講述兒童文學主題及手作帶給親子們一個快樂的週未時光\r\n主講人:太平貓頭鷹故事屋', '臺中市立圖書館太平分館', '臺中市太平區太平三街20號', '2025-03-01 00:00:00', '2025-03-16 00:00:00', '臺中市立圖書館太平分館', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/Q5rEq0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月 臺語說故事 (2場)', `description`='台語說故事爸媽-我本來就足愛汝阿!\r\n用閩南語說好故事，傳承閩南文化\r\n\r\n作伙來講古\r\n每週六由故事志工來講述兒童文學主題及手作帶給親子們一個快樂的週未時光\r\n主講人:太平貓頭鷹故事屋', `organizer`='臺中市立圖書館太平分館', `address`='臺中市太平區太平三街20號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺中市立圖書館太平分館', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/Q5rEq0', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741026b32408680be91c', '3月 紙生萬物摺紙展', '探索摺紙藝術的無限可能，呈現動物、昆蟲、幾何結構、數學圖形、機器人及立體紙機關等多元作品。\r\n每一道摺痕都是創意的展現，每一張紙都蘊含巧思，從栩栩如生的生物到精密的數學與機械結構，帶來藝術與科學的交融之美。', '臺中市立圖書館太平分館', '臺中市太平區太平三街20號', '2025-03-18 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館太平分館', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/kMxybG', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月 紙生萬物摺紙展', `description`='探索摺紙藝術的無限可能，呈現動物、昆蟲、幾何結構、數學圖形、機器人及立體紙機關等多元作品。\r\n每一道摺痕都是創意的展現，每一張紙都蘊含巧思，從栩栩如生的生物到精密的數學與機械結構，帶來藝術與科學的交融之美。', `organizer`='臺中市立圖書館太平分館', `address`='臺中市太平區太平三街20號', `start_date`='2025-03-18 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館太平分館', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/kMxybG', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741026b32408680be91d', '3月 春日綻放攝影展', '以鏡頭記錄春天的絢爛與生機，捕捉花朵綻放的美妙瞬間，展現春風拂過的柔和光影與大地甦醒的詩意畫面。\r\n透過不同視角詮釋春天的色彩與韻律，感受春日的浪漫與活力。', '臺中市立圖書館太平分館', '臺中市太平區太平三街20號', '2025-03-15 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館太平分館', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/WA6NZ5', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月 春日綻放攝影展', `description`='以鏡頭記錄春天的絢爛與生機，捕捉花朵綻放的美妙瞬間，展現春風拂過的柔和光影與大地甦醒的詩意畫面。\r\n透過不同視角詮釋春天的色彩與韻律，感受春日的浪漫與活力。', `organizer`='臺中市立圖書館太平分館', `address`='臺中市太平區太平三街20號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館太平分館', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/WA6NZ5', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741126b32408680be91e', '【台語家庭】系列講座 - 做伙讀趣味的、生活的、文學的、美學的台文繪本', '做伙讀趣味的、生活的、文學的、美學的台文繪本\r\n\r\n台語是我們的母語，因此我們用台文創作繪本，除了展現台語的趣味和生活化，更希望可以傳遞台語的文學性、優雅和美。\r\n\r\n🔶﹝講師﹞黃郁欽\r\n\r\n喜歡天馬行空的幻想，自由自在的畫圖。1988年開始做繪本，曾獲得第三屆牧笛獎首獎、第七屆陳國政兒童文學獎優選和第二十四屆信誼幼兒文學獎佳作，及2016年入選義大利波隆那插畫展。\r\n已出版《寂寞的天才—黃土水》、《兩撇喙鬚醫生—賴和》、《媽媽是天使》、《要站哪一邊？》、《小鷹與老鷹》 ⋯等23本繪本。\r\n\r\n \r\n\r\n🔶﹝講師﹞陶樂蒂\r\n\r\n法律學碩士，喜歡畫圖投入創作，開始繪本創作的生涯。曾獲得第九屆陳國政兒童文學獎圖畫書類首獎及第十四屆信誼幼兒文學獎佳作。\r\n已出版《好佳哉！》、《無公平！》、《無佮意！》、《陶樂蒂沒有寵物》、《大野狼的餐桌》、《起床囉》、⋯⋯等18本作品。', '臺中市立圖書館李科永紀念圖書分館', '臺中市南屯區龍富路五段1號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺中市立圖書館李科永紀念圖書分館', 24.14165524, 120.6177379, '無資料', 'https://is.gd/288vEZ', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【台語家庭】系列講座 - 做伙讀趣味的、生活的、文學的、美學的台文繪本', `description`='做伙讀趣味的、生活的、文學的、美學的台文繪本\r\n\r\n台語是我們的母語，因此我們用台文創作繪本，除了展現台語的趣味和生活化，更希望可以傳遞台語的文學性、優雅和美。\r\n\r\n🔶﹝講師﹞黃郁欽\r\n\r\n喜歡天馬行空的幻想，自由自在的畫圖。1988年開始做繪本，曾獲得第三屆牧笛獎首獎、第七屆陳國政兒童文學獎優選和第二十四屆信誼幼兒文學獎佳作，及2016年入選義大利波隆那插畫展。\r\n已出版《寂寞的天才—黃土水》、《兩撇喙鬚醫生—賴和》、《媽媽是天使》、《要站哪一邊？》、《小鷹與老鷹》 ⋯等23本繪本。\r\n\r\n \r\n\r\n🔶﹝講師﹞陶樂蒂\r\n\r\n法律學碩士，喜歡畫圖投入創作，開始繪本創作的生涯。曾獲得第九屆陳國政兒童文學獎圖畫書類首獎及第十四屆信誼幼兒文學獎佳作。\r\n已出版《好佳哉！》、《無公平！》、《無佮意！》、《陶樂蒂沒有寵物》、《大野狼的餐桌》、《起床囉》、⋯⋯等18本作品。', `organizer`='臺中市立圖書館李科永紀念圖書分館', `address`='臺中市南屯區龍富路五段1號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺中市立圖書館李科永紀念圖書分館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://is.gd/288vEZ', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741126b32408680be91f', '2025多元閱讀繽紛季「母語歌謠講座」- 唱歌是回家的路：當代原住民族歌謠的創作與展演', '2025多元閱讀繽紛季「母語歌謠講座」\r\n\r\n時間：114年3月16日（日）14:00－16:00\r\n\r\n地點：李科永紀念圖書分館\r\n\r\n講題：唱歌是回家的路：當代原住民族母語歌謠的創作與展演\r\n\r\n講師：劉智濬\r\n\r\n內容：語言，是身份認同的重要介面；寫母語歌、唱母語歌，是歌謠創作與身份認同的深度連結。本場講座分享當代原住民族母語歌謠的創作與展演，透過唱歌，歌謠創作者找到回家的路，一條復振文化與尋找身份的認同之路。', '臺中市立圖書館李科永紀念圖書分館', '臺中市南屯區龍富路五段1號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '臺中市立圖書館李科永紀念圖書分館', 24.14165524, 120.6177379, '無資料', 'https://www.beclass.com/rid=294fe5b67a0777426722', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025多元閱讀繽紛季「母語歌謠講座」- 唱歌是回家的路：當代原住民族歌謠的創作與展演', `description`='2025多元閱讀繽紛季「母語歌謠講座」\r\n\r\n時間：114年3月16日（日）14:00－16:00\r\n\r\n地點：李科永紀念圖書分館\r\n\r\n講題：唱歌是回家的路：當代原住民族母語歌謠的創作與展演\r\n\r\n講師：劉智濬\r\n\r\n內容：語言，是身份認同的重要介面；寫母語歌、唱母語歌，是歌謠創作與身份認同的深度連結。本場講座分享當代原住民族母語歌謠的創作與展演，透過唱歌，歌謠創作者找到回家的路，一條復振文化與尋找身份的認同之路。', `organizer`='臺中市立圖書館李科永紀念圖書分館', `address`='臺中市南屯區龍富路五段1號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺中市立圖書館李科永紀念圖書分館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://www.beclass.com/rid=294fe5b67a0777426722', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741126b32408680be920', '永康區圖書館:3月份歡樂美語故事坊', '3/16 Hugless Douglas\r\n剛從冬眠狀態中醒來的小熊Douglas需要一\r\n個抱抱，於是，牠先抱了大石頭，可是太\r\n重了。後來，牠又抱了大樹，可是被樹的\r\n刺刺到了。牠想抱動物們，大家卻尖叫狂\r\n奔。Douglas能不能順利找到可以抱抱的對\r\n象呢？', '臺南市永康區圖書館', '臺南市永康區永大二路88號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '臺南市永康區社教中心(永康區圖書館)', 23.02729532, 120.2542795, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='永康區圖書館:3月份歡樂美語故事坊', `description`='3/16 Hugless Douglas\r\n剛從冬眠狀態中醒來的小熊Douglas需要一\r\n個抱抱，於是，牠先抱了大石頭，可是太\r\n重了。後來，牠又抱了大樹，可是被樹的\r\n刺刺到了。牠想抱動物們，大家卻尖叫狂\r\n奔。Douglas能不能順利找到可以抱抱的對\r\n象呢？', `organizer`='臺南市永康區圖書館', `address`='臺南市永康區永大二路88號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺南市永康區社教中心(永康區圖書館)', `latitude`=23.02729532, `longitude`=120.2542795, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
