INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741126b32408680be922', '《西班牙大提琴家Pablo Ferrández 與鋼琴家左章台灣巡演》', '《西班牙大提琴家Pablo Ferrández 與鋼琴家左章台灣巡演》\r\n「年度青年音樂家獎」西班牙大提琴家巴勃羅．費蘭德斯與BBC 讚譽「新一代青年藝術家」的華人女鋼琴家左章\r\n2025年3月將攜手帶給你最浪漫的白色情人節。\r\n\r\n曾在2016國際古典音樂大獎ICMA 獲得「年度青年音樂家獎」的西班牙大提琴家巴勃羅．費蘭德斯，即將在2025年3月份將自己獨特典雅的音樂造詣帶來到高雄衛武營國家藝術文化中心。\r\n這次演出將攜手國際鋼琴家左章，左章更是曾被獲選為 BBC 極具影響力的「新一代青年藝術家」。\r\n兩人皆享譽國際、同時也與許多知名樂團合奏演出過。在2025年3月將為臺灣樂迷獻上一個充滿音樂典雅氣息的最浪漫白色情人節。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n製作團隊｜好滿意音樂\r\n\r\n大提琴｜巴勃羅·費蘭德斯\r\n\r\n鋼琴｜左章', '好滿意音樂有限公司', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-20 00:00:00', '2025-03-20 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+800;--+1000;--+1300;--+1600;--+2000;--+2200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《西班牙大提琴家Pablo Ferrández 與鋼琴家左章台灣巡演》', `description`='《西班牙大提琴家Pablo Ferrández 與鋼琴家左章台灣巡演》\r\n「年度青年音樂家獎」西班牙大提琴家巴勃羅．費蘭德斯與BBC 讚譽「新一代青年藝術家」的華人女鋼琴家左章\r\n2025年3月將攜手帶給你最浪漫的白色情人節。\r\n\r\n曾在2016國際古典音樂大獎ICMA 獲得「年度青年音樂家獎」的西班牙大提琴家巴勃羅．費蘭德斯，即將在2025年3月份將自己獨特典雅的音樂造詣帶來到高雄衛武營國家藝術文化中心。\r\n這次演出將攜手國際鋼琴家左章，左章更是曾被獲選為 BBC 極具影響力的「新一代青年藝術家」。\r\n兩人皆享譽國際、同時也與許多知名樂團合奏演出過。在2025年3月將為臺灣樂迷獻上一個充滿音樂典雅氣息的最浪漫白色情人節。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n製作團隊｜好滿意音樂\r\n\r\n大提琴｜巴勃羅·費蘭德斯\r\n\r\n鋼琴｜左章', `organizer`='好滿意音樂有限公司', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-20 00:00:00', `end_date`='2025-03-20 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+800;--+1000;--+1300;--+1600;--+2000;--+2200', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741126b32408680be923', '《星晞望管弦樂團年度音樂會-武星吉》', '《星晞望管弦樂團年度音樂會-武星吉》\r\n星晞望管弦樂團來自於臺中，成立於2012年，由一群愛樂人士所組成，本場音樂會邀請日本指揮山路讓以及日本長笛家坂橋矢波共同演出，除了帶來熱情的德佛札克狂歡節序曲，還有小約翰史特勞斯的蝙蝠序曲，更由兩位日本音樂家與星晞望管弦樂團帶來的杜普勒匈牙利田園幻想曲，更有代表星晞望管弦樂團的主題曲starwish，用不同樂派的音樂來帶給觀眾了解一個年輕樂團的活力。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n德佛札克：《狂歡節序曲》，作品92\r\n\r\n小約翰˙史特勞斯：《蝙蝠序曲》，作品362\r\n\r\n杜普勒：⟪匈牙利田園狂想曲⟫ ，作品26\r\n\r\n比才：第一號⟪阿萊城姑娘組曲⟫\r\n\r\n⟪納尼亞傳奇⟫\r\n\r\n電影配樂\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n星晞望管弦樂團', '星晞望管弦樂團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-21 00:00:00', '2025-03-21 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+300;--+500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《星晞望管弦樂團年度音樂會-武星吉》', `description`='《星晞望管弦樂團年度音樂會-武星吉》\r\n星晞望管弦樂團來自於臺中，成立於2012年，由一群愛樂人士所組成，本場音樂會邀請日本指揮山路讓以及日本長笛家坂橋矢波共同演出，除了帶來熱情的德佛札克狂歡節序曲，還有小約翰史特勞斯的蝙蝠序曲，更由兩位日本音樂家與星晞望管弦樂團帶來的杜普勒匈牙利田園幻想曲，更有代表星晞望管弦樂團的主題曲starwish，用不同樂派的音樂來帶給觀眾了解一個年輕樂團的活力。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n德佛札克：《狂歡節序曲》，作品92\r\n\r\n小約翰˙史特勞斯：《蝙蝠序曲》，作品362\r\n\r\n杜普勒：⟪匈牙利田園狂想曲⟫ ，作品26\r\n\r\n比才：第一號⟪阿萊城姑娘組曲⟫\r\n\r\n⟪納尼亞傳奇⟫\r\n\r\n電影配樂\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n星晞望管弦樂團', `organizer`='星晞望管弦樂團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+300;--+500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be924', '2025經典法文音樂劇《鐘樓怪人》', '2025經典法文音樂劇《鐘樓怪人》\r\n★ 豪華升級，首度三地巡演：25週年世界巡迴，首度北中高三地巡演，打造殿堂級視聽覺饗宴\r\n\r\n★ 榮登金氏世界紀錄：21世紀最成功的音樂劇之一，連續七次「史上開演後最賣座的音樂劇」\r\n\r\n★ 歐美音樂劇頂尖指標：百老匯Playbill票選最受歡迎音樂劇前三名。\r\n\r\n★ 風靡全球，破天荒熱賣佳績：開演至今，被翻譯9種語言並於超過23個國家演出，各國版本《鐘樓怪人》感動全球千萬名觀眾。\r\n\r\n★ 打破倫敦西區紀錄：第一部於倫敦西區演出的法文音樂劇，倫敦劇評盛讚，破紀錄於倫敦演出長達17個月，開啟法國當代音樂劇之新紀元。 \r\n\r\n \r\n\r\n經典法文音樂劇《鐘樓怪人》改編自法國大文豪雨果巨作，以十五世紀末巴黎聖母院為背景，故事描述美麗的吉普賽女郎艾斯梅拉達，與四位不同階級的角色－副主教弗侯洛、侍衛隊長菲比斯、遊唱詩人葛林果利與鐘樓怪人科西莫多之間的愛恨情結。\r\n\r\n \r\n\r\n艾斯梅拉達對菲比斯一見鐘情，而菲比斯雖有未婚妻芙蘿德莉卻想要兩者兼得。於此同時，副主教弗侯洛無法抗拒神職人員禁忌，也拜倒在艾斯梅拉達裙下；自小被副主教收養、 長相畸形的敲鐘人科西莫多也傾慕著艾斯梅拉達，卻自慚形穢，而將愛意藏在⼼中。\r\n\r\n \r\n\r\n此齣劇劇中人物生存在動盪不安的封建社會中，深刻刻劃出人物間的對立衝突，突顯人性良善與醜惡、忠誠與背叛的對比，展現出強烈的戲劇張力。 \r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n製作人｜NICOLAS TALAR, ENZO PRODUCTIONS \r\n\r\n歌詞｜Luc Plamondon \r\n\r\n歌曲｜Richard Cocciante \r\n\r\n導演｜Gilles Maheu \r\n\r\n編舞｜Martino Muller', '聯合數位文創股份有限公司', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-21 00:00:00', '2025-03-30 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+900;--+1600;--+1800;--+2100;--+2200;--+2500;--+2700;--+3100;--+3300;--+3600;--+3800;--+4200;--+4400;--+4700;--+4900;--+5600;--+5800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025經典法文音樂劇《鐘樓怪人》', `description`='2025經典法文音樂劇《鐘樓怪人》\r\n★ 豪華升級，首度三地巡演：25週年世界巡迴，首度北中高三地巡演，打造殿堂級視聽覺饗宴\r\n\r\n★ 榮登金氏世界紀錄：21世紀最成功的音樂劇之一，連續七次「史上開演後最賣座的音樂劇」\r\n\r\n★ 歐美音樂劇頂尖指標：百老匯Playbill票選最受歡迎音樂劇前三名。\r\n\r\n★ 風靡全球，破天荒熱賣佳績：開演至今，被翻譯9種語言並於超過23個國家演出，各國版本《鐘樓怪人》感動全球千萬名觀眾。\r\n\r\n★ 打破倫敦西區紀錄：第一部於倫敦西區演出的法文音樂劇，倫敦劇評盛讚，破紀錄於倫敦演出長達17個月，開啟法國當代音樂劇之新紀元。 \r\n\r\n \r\n\r\n經典法文音樂劇《鐘樓怪人》改編自法國大文豪雨果巨作，以十五世紀末巴黎聖母院為背景，故事描述美麗的吉普賽女郎艾斯梅拉達，與四位不同階級的角色－副主教弗侯洛、侍衛隊長菲比斯、遊唱詩人葛林果利與鐘樓怪人科西莫多之間的愛恨情結。\r\n\r\n \r\n\r\n艾斯梅拉達對菲比斯一見鐘情，而菲比斯雖有未婚妻芙蘿德莉卻想要兩者兼得。於此同時，副主教弗侯洛無法抗拒神職人員禁忌，也拜倒在艾斯梅拉達裙下；自小被副主教收養、 長相畸形的敲鐘人科西莫多也傾慕著艾斯梅拉達，卻自慚形穢，而將愛意藏在⼼中。\r\n\r\n \r\n\r\n此齣劇劇中人物生存在動盪不安的封建社會中，深刻刻劃出人物間的對立衝突，突顯人性良善與醜惡、忠誠與背叛的對比，展現出強烈的戲劇張力。 \r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n製作人｜NICOLAS TALAR, ENZO PRODUCTIONS \r\n\r\n歌詞｜Luc Plamondon \r\n\r\n歌曲｜Richard Cocciante \r\n\r\n導演｜Gilles Maheu \r\n\r\n編舞｜Martino Muller', `organizer`='聯合數位文創股份有限公司', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+900;--+1600;--+1800;--+2100;--+2200;--+2500;--+2700;--+3100;--+3300;--+3600;--+3800;--+4200;--+4400;--+4700;--+4900;--+5600;--+5800', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be925', '巴赫340《心境》2025陳鈺雯小提琴獨奏會', '巴赫340《心境》2025陳鈺雯小提琴獨奏會\r\n在數字低音(basso continuo)當道的年代創作無數字低音(senza basso)的作品是挑戰傳統?跳脫規範?顛覆想像?抑或是無視樂器的生理疆界，意圖探索、體現最純然、絕對、不受限的音樂想法?\r\n\r\n巴赫創作許多六首一套的作品，只有1720年完成的小提琴無伴奏又分為三對教會奏鳴曲與室內組曲，這一聖一俗的組合是否記錄作曲家內向回應自己、外向迴響環境的過程?\r\n\r\n2025陳鈺雯小提琴獨奏會《心境》將用全本無伴奏來演繹巴赫的人生試煉、考驗與轉化。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n巴赫給獨奏小提琴的三首奏鳴曲與三首組曲\r\nSonata I (g minor), BWV 1001\r\nPartita I (b minor), BWV 1002\r\nSonata II (a minor), BWV 1003\r\nPartita II (d minor), BWV 1004\r\nSonata III (C Major), BWV 1005\r\nPartita III (E Major), BWV 1006\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n小提琴｜陳鈺雯 \r\n\r\n中山大學音樂系專任副教授，波士頓新英格蘭音樂院小提琴演奏博士。在美師事Michele Auclair、Eric Rosenblith、Patricia Zander及Eugene Lehner，在台灣時師事莊玲惠老師、游文良老師、蘇顯達老師。演出足跡遍佈臺灣、美國、加拿大、澳洲及歐洲，曾應邀至Überlingen、Insel Mainau及Passau等音樂節、2013愛丁堡藝穗節及2017荷蘭古鋼琴節演出。曾擔任中山大學巴洛克獨奏家駐校樂團的首席及駐校藝術家外，也受邀擔任極地之光管絃樂團的首席。定期發表學術論文及錄製演奏出版品外，也受邀至公家及民間單位演講藉以推廣古典音樂，每年更以不同文學主題結合音樂，推出深耕校園的《聽見文學 看見音樂》講座音樂會及《古典音樂宅急便》系列，2018年獲得中山大學教學績優獎的肯定。', '當代室內樂團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-21 00:00:00', '2025-03-21 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='巴赫340《心境》2025陳鈺雯小提琴獨奏會', `description`='巴赫340《心境》2025陳鈺雯小提琴獨奏會\r\n在數字低音(basso continuo)當道的年代創作無數字低音(senza basso)的作品是挑戰傳統?跳脫規範?顛覆想像?抑或是無視樂器的生理疆界，意圖探索、體現最純然、絕對、不受限的音樂想法?\r\n\r\n巴赫創作許多六首一套的作品，只有1720年完成的小提琴無伴奏又分為三對教會奏鳴曲與室內組曲，這一聖一俗的組合是否記錄作曲家內向回應自己、外向迴響環境的過程?\r\n\r\n2025陳鈺雯小提琴獨奏會《心境》將用全本無伴奏來演繹巴赫的人生試煉、考驗與轉化。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n巴赫給獨奏小提琴的三首奏鳴曲與三首組曲\r\nSonata I (g minor), BWV 1001\r\nPartita I (b minor), BWV 1002\r\nSonata II (a minor), BWV 1003\r\nPartita II (d minor), BWV 1004\r\nSonata III (C Major), BWV 1005\r\nPartita III (E Major), BWV 1006\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n小提琴｜陳鈺雯 \r\n\r\n中山大學音樂系專任副教授，波士頓新英格蘭音樂院小提琴演奏博士。在美師事Michele Auclair、Eric Rosenblith、Patricia Zander及Eugene Lehner，在台灣時師事莊玲惠老師、游文良老師、蘇顯達老師。演出足跡遍佈臺灣、美國、加拿大、澳洲及歐洲，曾應邀至Überlingen、Insel Mainau及Passau等音樂節、2013愛丁堡藝穗節及2017荷蘭古鋼琴節演出。曾擔任中山大學巴洛克獨奏家駐校樂團的首席及駐校藝術家外，也受邀擔任極地之光管絃樂團的首席。定期發表學術論文及錄製演奏出版品外，也受邀至公家及民間單位演講藉以推廣古典音樂，每年更以不同文學主題結合音樂，推出深耕校園的《聽見文學 看見音樂》講座音樂會及《古典音樂宅急便》系列，2018年獲得中山大學教學績優獎的肯定。', `organizer`='當代室內樂團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be926', '《錦衣》的復仇之道——跨越虛實邊界的武俠人物剖析', '《錦衣》的復仇之道——跨越虛實邊界的武俠人物剖析\r\n※本場講座原訂由編劇劉建幗主講，原主講劉建幗因故不克參加，故講座將異動為臺灣豫劇團藝術總監王海玲主講，並邀請臨床心理師王三瑜與談。因應講者更換，講座內容調整為「《錦衣》的復仇之道——跨越虛實邊界的武俠人物剖析」，造成不便敬請見諒。\r\n\r\n \r\n\r\n復仇，既是江湖故事的推進力，也是人性深處最複雜、最難解的課題。在年度武俠大戲《錦衣》中，復仇不僅僅是一場情節衝突，更是一場跨越虛實邊界的心理與情感探索。作為當代戲曲推手，臺灣豫劇團藝術總監王海玲致力於傳統戲曲的傳承，更大膽創新、跨界實驗，用現代視角重塑戲曲美學。此次講座將從創作初衷開展，分享如何注入時下劇場最受歡迎的武俠元素，讓江湖軼事在現代舞臺上煥發新生。\r\n\r\n本場講座更特邀心理師王三瑜，聯手主演劉建華與蕭揚玲，共同解析劇中角色的內心掙扎與情感，揭示人物之間錯綜複雜的關係網絡。復仇之道，究竟是救贖，還是無盡深淵？從心理學的角度與傳統戲曲深度對話，引領您穿越虛實邊界，揭開角色心理與情感的深層謎團。\r\n\r\n \r\n\r\n  活動及報名資訊  \r\n\r\n活動時間：3/22(六)14:00-16:00\r\n\r\n參加對象：歡迎喜愛藝術活動，對於傳統戲曲有興趣者報名！ \r\n\r\n報名時間：即日起至3/17(一)18:00止（限量100名，額滿為止）\r\n\r\n報名流程：官網報名（一組帳號僅可報名一次）→檢視官網報名狀況→完成報名。\r\n\r\n活動地點：衛武營 演講廳\r\n\r\n \r\n\r\n  主講人  \r\n\r\n臺灣豫劇團藝術總監｜王海玲\r\n\r\n圖片\r\n臺灣國寶級戲曲藝術家。國立中山大學劇場藝術系兼任副教授、國立高雄師範大學兼任副教授、國立高雄大學兼任副教授，1969年中國文藝協會頒贈戲曲表演獎章（歷年最年輕得獎人）、第6屆「中華文化藝術薪傳獎」得主、第4屆「國家文藝獎」戲劇類得主，得獎評語：「臺灣的豫劇因王海玲而存在，因王海玲而出色」。\r\n\r\n \r\n\r\n  與談人  \r\n\r\n\r\n豫劇天后｜蕭揚玲\r\n\r\n圖片\r\n臺灣豫劇團當家花旦，國立高雄師範大學表演藝術碩士，師承張岫雲、王海玲兩代豫劇皇后，專攻花旦及青衣。曾獲大陸2007年第11屆「香玉杯」藝術獎、河南戲劇演員排行榜2010、2012年度十大演員「寶島之星」獎、入圍2016年傳藝金曲獎「年度最佳演員」。致力提升表演技藝，跨界參與實驗劇、舞臺劇、歌仔戲等演出，近年代表作品：豫劇《蘭若寺》、《飛馬行》、《香囊記》、《青春作伴杜蘭朵》、《武皇投簡》、《龍袍》、《鏢客》、《長安花》、《劈棺驚夢》等。\r\n\r\n \r\n\r\n豫劇王子｜劉建華 \r\n\r\n圖片\r\n國立臺南大學戲劇創作與應用學系碩士、國立高雄師範大學兼任助理教授。出生戲曲世家，曾創辦高雄女中豫劇社、考入楊麗花歌仔戲團第四期藝生，其後於2005年考入臺灣豫劇團，師承王海玲、朱海珊老師，以優異表現逐漸嶄露頭角，獲封為「豫劇王子」。主演戲碼包括：豫劇《龍袍》、《金蓮纒夢》、《金殿抗婚》等；並支援主演奇巧劇團《鞍馬天狗》、《蝴.蝶.效.應》、《二郎哮天》等劇目。亦多次嘗試幕後工作，擔任明華園天字團《國士無雙》身段指導；奇巧劇團《鞍馬天狗》、歌仔音樂劇《1624》及高雄巿政府《船愛》副導演；並執導奇巧劇團《空空戒戒木偶奇遇記》與《劍俠秦少游》等劇目。\r\n\r\n \r\n\r\n臨床心理師｜王三瑜\r\n\r\n圖片\r\n現任美術館禾好心理治療所所長，擁有高雄醫學大學臨床心理所碩士學位。她專長於成人心理治療、生理回饋、神經回饋（注意力訓練）、情緒困擾（如憂鬱、焦慮、恐慌等）、情感議題（如伴侶、親子溝通等）、人際關係及生涯規劃。王心理師亦擔任臺灣生理與神經回饋理事長，並曾於小港醫院精神科、高雄張老師中心等單位兼任臨床心理師。她熱衷心理健康推廣，曾參與《青春發言人》與《哇賽心理學》等節目合作，以深入淺出的方式分享心理專業，啟發大眾關注心理健康與身心平衡。\r\n\r\n \r\n\r\n  節目資訊  \r\n\r\n5/24(六)14:30、5/25(日)14:30\r\n\r\n►臺灣豫劇團 《錦衣》', '國家表演藝術中心衛武營國家藝術文化中心', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '無資料', 'https://www.npac-weiwuying.org/programs/676b6aeb3c9d47000a871655', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《錦衣》的復仇之道——跨越虛實邊界的武俠人物剖析', `description`='《錦衣》的復仇之道——跨越虛實邊界的武俠人物剖析\r\n※本場講座原訂由編劇劉建幗主講，原主講劉建幗因故不克參加，故講座將異動為臺灣豫劇團藝術總監王海玲主講，並邀請臨床心理師王三瑜與談。因應講者更換，講座內容調整為「《錦衣》的復仇之道——跨越虛實邊界的武俠人物剖析」，造成不便敬請見諒。\r\n\r\n \r\n\r\n復仇，既是江湖故事的推進力，也是人性深處最複雜、最難解的課題。在年度武俠大戲《錦衣》中，復仇不僅僅是一場情節衝突，更是一場跨越虛實邊界的心理與情感探索。作為當代戲曲推手，臺灣豫劇團藝術總監王海玲致力於傳統戲曲的傳承，更大膽創新、跨界實驗，用現代視角重塑戲曲美學。此次講座將從創作初衷開展，分享如何注入時下劇場最受歡迎的武俠元素，讓江湖軼事在現代舞臺上煥發新生。\r\n\r\n本場講座更特邀心理師王三瑜，聯手主演劉建華與蕭揚玲，共同解析劇中角色的內心掙扎與情感，揭示人物之間錯綜複雜的關係網絡。復仇之道，究竟是救贖，還是無盡深淵？從心理學的角度與傳統戲曲深度對話，引領您穿越虛實邊界，揭開角色心理與情感的深層謎團。\r\n\r\n \r\n\r\n  活動及報名資訊  \r\n\r\n活動時間：3/22(六)14:00-16:00\r\n\r\n參加對象：歡迎喜愛藝術活動，對於傳統戲曲有興趣者報名！ \r\n\r\n報名時間：即日起至3/17(一)18:00止（限量100名，額滿為止）\r\n\r\n報名流程：官網報名（一組帳號僅可報名一次）→檢視官網報名狀況→完成報名。\r\n\r\n活動地點：衛武營 演講廳\r\n\r\n \r\n\r\n  主講人  \r\n\r\n臺灣豫劇團藝術總監｜王海玲\r\n\r\n圖片\r\n臺灣國寶級戲曲藝術家。國立中山大學劇場藝術系兼任副教授、國立高雄師範大學兼任副教授、國立高雄大學兼任副教授，1969年中國文藝協會頒贈戲曲表演獎章（歷年最年輕得獎人）、第6屆「中華文化藝術薪傳獎」得主、第4屆「國家文藝獎」戲劇類得主，得獎評語：「臺灣的豫劇因王海玲而存在，因王海玲而出色」。\r\n\r\n \r\n\r\n  與談人  \r\n\r\n\r\n豫劇天后｜蕭揚玲\r\n\r\n圖片\r\n臺灣豫劇團當家花旦，國立高雄師範大學表演藝術碩士，師承張岫雲、王海玲兩代豫劇皇后，專攻花旦及青衣。曾獲大陸2007年第11屆「香玉杯」藝術獎、河南戲劇演員排行榜2010、2012年度十大演員「寶島之星」獎、入圍2016年傳藝金曲獎「年度最佳演員」。致力提升表演技藝，跨界參與實驗劇、舞臺劇、歌仔戲等演出，近年代表作品：豫劇《蘭若寺》、《飛馬行》、《香囊記》、《青春作伴杜蘭朵》、《武皇投簡》、《龍袍》、《鏢客》、《長安花》、《劈棺驚夢》等。\r\n\r\n \r\n\r\n豫劇王子｜劉建華 \r\n\r\n圖片\r\n國立臺南大學戲劇創作與應用學系碩士、國立高雄師範大學兼任助理教授。出生戲曲世家，曾創辦高雄女中豫劇社、考入楊麗花歌仔戲團第四期藝生，其後於2005年考入臺灣豫劇團，師承王海玲、朱海珊老師，以優異表現逐漸嶄露頭角，獲封為「豫劇王子」。主演戲碼包括：豫劇《龍袍》、《金蓮纒夢》、《金殿抗婚》等；並支援主演奇巧劇團《鞍馬天狗》、《蝴.蝶.效.應》、《二郎哮天》等劇目。亦多次嘗試幕後工作，擔任明華園天字團《國士無雙》身段指導；奇巧劇團《鞍馬天狗》、歌仔音樂劇《1624》及高雄巿政府《船愛》副導演；並執導奇巧劇團《空空戒戒木偶奇遇記》與《劍俠秦少游》等劇目。\r\n\r\n \r\n\r\n臨床心理師｜王三瑜\r\n\r\n圖片\r\n現任美術館禾好心理治療所所長，擁有高雄醫學大學臨床心理所碩士學位。她專長於成人心理治療、生理回饋、神經回饋（注意力訓練）、情緒困擾（如憂鬱、焦慮、恐慌等）、情感議題（如伴侶、親子溝通等）、人際關係及生涯規劃。王心理師亦擔任臺灣生理與神經回饋理事長，並曾於小港醫院精神科、高雄張老師中心等單位兼任臨床心理師。她熱衷心理健康推廣，曾參與《青春發言人》與《哇賽心理學》等節目合作，以深入淺出的方式分享心理專業，啟發大眾關注心理健康與身心平衡。\r\n\r\n \r\n\r\n  節目資訊  \r\n\r\n5/24(六)14:30、5/25(日)14:30\r\n\r\n►臺灣豫劇團 《錦衣》', `organizer`='國家表演藝術中心衛武營國家藝術文化中心', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='無資料', `source_url`='https://www.npac-weiwuying.org/programs/676b6aeb3c9d47000a871655', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be928', 'KSAF《星‧海》郭勇德與高雄市國樂團音樂會', 'KSAF《星‧海》郭勇德與高雄市國樂團音樂會\r\n活躍於國際樂壇，目前任職新加坡華樂團首席指揮的郭勇德，擁有超過25年的指揮經驗，廣受“人民的指揮”讚譽。再度與高雄市國樂團合作。將帶領您以多元感官，遍歷南洋的風光與傳奇。\r\n\r\n郭勇德指揮技法學貫中西，擅長以敘事性的創新節目和富有激情的指揮風格，把各地風情的音樂帶給大眾。是場音樂會安排6首曲目、展現6種面貌，豐富的樂風與形式，匯聚了現代與傳統的風格特色，融合東西文化精粹。擔任獨奏部分則邀請臺灣青年中阮演奏家邱絜安、吳如晴及樂團首席彭苙榳共同展現美麗的樂音，和樂迷們一同徜徉探索南洋風的音樂饗宴。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n馮國駿：《芬芳的交響》  \r\n\r\n江賜良：捕風掠影II《刺的回味》    \r\n\r\n王辰威：雙中阮協奏曲《姊妹島》    \r\n\r\n劉錫津：高胡協奏曲《魚尾獅傳奇》  \r\n\r\n趙俊毅：樂隊與音效《明日之城》\r\n\r\n羅偉倫：《海上第一人：鄭和》之〈海路〉 \r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n指揮｜郭勇德\r\n\r\n高胡｜彭苙榳\r\n\r\n中阮｜邱絜安、吳如晴\r\n\r\n高雄市國樂團', '財團法人高雄市愛樂文化藝術基金會', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+300;--+500;--+700;--+900;--+1200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='KSAF《星‧海》郭勇德與高雄市國樂團音樂會', `description`='KSAF《星‧海》郭勇德與高雄市國樂團音樂會\r\n活躍於國際樂壇，目前任職新加坡華樂團首席指揮的郭勇德，擁有超過25年的指揮經驗，廣受“人民的指揮”讚譽。再度與高雄市國樂團合作。將帶領您以多元感官，遍歷南洋的風光與傳奇。\r\n\r\n郭勇德指揮技法學貫中西，擅長以敘事性的創新節目和富有激情的指揮風格，把各地風情的音樂帶給大眾。是場音樂會安排6首曲目、展現6種面貌，豐富的樂風與形式，匯聚了現代與傳統的風格特色，融合東西文化精粹。擔任獨奏部分則邀請臺灣青年中阮演奏家邱絜安、吳如晴及樂團首席彭苙榳共同展現美麗的樂音，和樂迷們一同徜徉探索南洋風的音樂饗宴。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n馮國駿：《芬芳的交響》  \r\n\r\n江賜良：捕風掠影II《刺的回味》    \r\n\r\n王辰威：雙中阮協奏曲《姊妹島》    \r\n\r\n劉錫津：高胡協奏曲《魚尾獅傳奇》  \r\n\r\n趙俊毅：樂隊與音效《明日之城》\r\n\r\n羅偉倫：《海上第一人：鄭和》之〈海路〉 \r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n指揮｜郭勇德\r\n\r\n高胡｜彭苙榳\r\n\r\n中阮｜邱絜安、吳如晴\r\n\r\n高雄市國樂團', `organizer`='財團法人高雄市愛樂文化藝術基金會', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+300;--+500;--+700;--+900;--+1200', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be929', '《EaccidLent》2025張育瑞鋼琴即興演奏會', '《EaccidLent》2025張育瑞鋼琴即興演奏會\r\n\r\n \r\n\r\n演奏會名稱「EaccidLent」源自一場2023年Rick在演奏會中發生的鋼琴斷弦意外(Accident)，Rick靈機一動在等待處理時間與觀眾互動讓觀眾點歌，意外(Accident)造就一場出色(Excellent)的演出，觀眾點歌金曲歌后彭佳慧的「大齡女子」，影片更吸引金曲歌后本人轉發。本次演奏會結合Accident與Excellent，延續「Accident, but Excellent」的精神為本次音樂會主題，以最純粹的鋼琴原聲創造不凡的聲響與律動，呈現鋼琴剛柔並濟的多變風格，並與聽眾粉絲現場互動，即興與改編經典古典、流行名曲。\r\n\r\n新銳跨界鋼琴家Rick Chang（張育瑞）以其獨具一格的古典搖滾風格深受樂迷喜愛，畢業於美國知名流行音樂學院- Berklee College of Music，取得演奏與音樂製作碩士學位（Master of Music in Contemporary Performance）。擅長將古典鋼琴技巧融合流行元素與即興創作，現為碩樂國際娛樂（Showing Music Entertainment）簽約鋼琴家及環球音樂（Universal Music Publishing Group）專屬詞曲創作者。\r\n\r\n首張跨界鋼琴專輯《Fire!》發行後，即登上博客來「品味」類排行榜第一，並榮獲美國全球音樂獎「新銳藝術家」與「器樂演奏家」銅牌殊榮。多部YouTube上的Cover影片廣受歡迎，2024年台灣奧運奪金時創作之奧運之歌於48小時內觀看次數突破200萬。此外，與布達佩斯配樂交響樂團合作的原創鋼琴協奏曲「黑暗世界 The Dark World」亦在發佈一個月內於YouTube創下超過十萬次點閱佳績。\r\n\r\n2024年，受YAMAHA鋼琴及采盟免稅集團之邀，於桃園國際機場舉辦快閃演奏會。同年受德國 C.Bechstein 貝希斯坦鋼琴之邀，舉辦個人演奏會，以創新演奏風格於不同場域持續拓展鋼琴的新可能。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n張育瑞Rick Chang：Fire!\r\n\r\n張育瑞Rick Chang：Crossover\r\n\r\n張育瑞Rick Chang：Piano Battle\r\n\r\n張育瑞Rick Chang：Ron con Cola\r\n\r\n張育瑞Rick Chang：Alien 異類\r\n\r\n張育瑞Rick Chang：Chubby Chubby\r\n\r\n張育瑞Rick Chang：Sacrifice 犧牲\r\n\r\n張育瑞Rick Chang：The Dark World\r\n\r\n張育瑞Rick Chang：The Moments 致每個當下\r\n\r\n(由上方挑選6首演出，以及流行曲目與現場互動)\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n鋼琴｜張育瑞', '碩樂國際娛樂股份有限公司', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500;--+800;--+1200;--+1500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《EaccidLent》2025張育瑞鋼琴即興演奏會', `description`='《EaccidLent》2025張育瑞鋼琴即興演奏會\r\n\r\n \r\n\r\n演奏會名稱「EaccidLent」源自一場2023年Rick在演奏會中發生的鋼琴斷弦意外(Accident)，Rick靈機一動在等待處理時間與觀眾互動讓觀眾點歌，意外(Accident)造就一場出色(Excellent)的演出，觀眾點歌金曲歌后彭佳慧的「大齡女子」，影片更吸引金曲歌后本人轉發。本次演奏會結合Accident與Excellent，延續「Accident, but Excellent」的精神為本次音樂會主題，以最純粹的鋼琴原聲創造不凡的聲響與律動，呈現鋼琴剛柔並濟的多變風格，並與聽眾粉絲現場互動，即興與改編經典古典、流行名曲。\r\n\r\n新銳跨界鋼琴家Rick Chang（張育瑞）以其獨具一格的古典搖滾風格深受樂迷喜愛，畢業於美國知名流行音樂學院- Berklee College of Music，取得演奏與音樂製作碩士學位（Master of Music in Contemporary Performance）。擅長將古典鋼琴技巧融合流行元素與即興創作，現為碩樂國際娛樂（Showing Music Entertainment）簽約鋼琴家及環球音樂（Universal Music Publishing Group）專屬詞曲創作者。\r\n\r\n首張跨界鋼琴專輯《Fire!》發行後，即登上博客來「品味」類排行榜第一，並榮獲美國全球音樂獎「新銳藝術家」與「器樂演奏家」銅牌殊榮。多部YouTube上的Cover影片廣受歡迎，2024年台灣奧運奪金時創作之奧運之歌於48小時內觀看次數突破200萬。此外，與布達佩斯配樂交響樂團合作的原創鋼琴協奏曲「黑暗世界 The Dark World」亦在發佈一個月內於YouTube創下超過十萬次點閱佳績。\r\n\r\n2024年，受YAMAHA鋼琴及采盟免稅集團之邀，於桃園國際機場舉辦快閃演奏會。同年受德國 C.Bechstein 貝希斯坦鋼琴之邀，舉辦個人演奏會，以創新演奏風格於不同場域持續拓展鋼琴的新可能。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n張育瑞Rick Chang：Fire!\r\n\r\n張育瑞Rick Chang：Crossover\r\n\r\n張育瑞Rick Chang：Piano Battle\r\n\r\n張育瑞Rick Chang：Ron con Cola\r\n\r\n張育瑞Rick Chang：Alien 異類\r\n\r\n張育瑞Rick Chang：Chubby Chubby\r\n\r\n張育瑞Rick Chang：Sacrifice 犧牲\r\n\r\n張育瑞Rick Chang：The Dark World\r\n\r\n張育瑞Rick Chang：The Moments 致每個當下\r\n\r\n(由上方挑選6首演出，以及流行曲目與現場互動)\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n鋼琴｜張育瑞', `organizer`='碩樂國際娛樂股份有限公司', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500;--+800;--+1200;--+1500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be92a', '【性別符號】│父親的衣櫃', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│父親的衣櫃\r\n英文片│All about My Father\r\n\r\n導演│伊文．班尼斯泰\r\n挪威│2002│輔導級│紀錄片│彩色│挪威語│71分\r\n\r\n簡介\r\n是一部導演兒子速寫變裝父親的紀錄片， 26歲的年輕挪威導演Even Benestad用短短71分鐘，探討了一個日漸普遍卻依舊充滿爭議..', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【性別符號】│父親的衣櫃', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│父親的衣櫃\r\n英文片│All about My Father\r\n\r\n導演│伊文．班尼斯泰\r\n挪威│2002│輔導級│紀錄片│彩色│挪威語│71分\r\n\r\n簡介\r\n是一部導演兒子速寫變裝父親的紀錄片， 26歲的年輕挪威導演Even Benestad用短短71分鐘，探討了一個日漸普遍卻依舊充滿爭議..', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be92b', '《心境澄明－白建宇的莫札特之聲》', '《心境澄明－白建宇的莫札特之聲》\r\n「名副其實且值得信賴的藝術大師、完美的音樂家。」《費加洛報》\r\n\r\n「白建宇的演奏如電閃雷鳴，能喚醒古老傳奇中的幽魂。」《紐約時報》\r\n\r\n「白建宇演奏的戲劇感、睿智、對細節的掌握、富有內涵的和弦，以及極致靈活的技巧，皆屬非凡。」《獨立報》\r\n\r\n \r\n\r\n白建宇十歲與韓國國家交響樂團合作演出葛利格的鋼琴協奏曲；15歲前往紐約茱麗亞音樂學院，師從羅西娜．列文涅（Rosina Lhevinne），並在倫敦拜師伊洛娜．卡波斯（Ilona Kabos）；同時白建宇也在義大利學習，師從圭多．阿戈斯蒂（Guido Agosti）與威廉．肯普夫（Willhelm Kempff）。白建宇的國際演奏生涯始於他的紐約首演，當時他在林肯中心演出拉威爾的鋼琴獨奏作品全集，聲名大噪，不久後也在卡內基大廳演出。白建宇曾經獲得許多國際鋼琴大賽首獎，最著名的是1969年布梭尼國際鋼琴大賽首獎。\r\n \r\n\r\n白建宇在林肯中心、卡內基廳、維格摩廳以及柏林愛樂廳等地舉行鋼琴獨奏會，此外他也與祖賓．梅塔（Zubin Mehta）、馬捷爾（Lorin Maazel）、揚頌斯（Mariss Jansons）、余隆（Long Yu）、馬利納爵士（Sir. Neville Marriner）、薩瓦利許（Wolfgang Sawallisch）、貝洛拉維克（Jiri Belohlavek）尤洛維斯基（Vladimir Jurowsky）、季坦科（Dmitri Kitaenko）、帕沃．賈維（Paavo Jarvi）、伊凡．費雪（Ivan Fischer）、潘德瑞茲基（Penderecki）等指揮家合作許多鋼琴協奏曲。白建宇合作過的樂團包括以色列愛樂、紐約愛樂、聖彼特堡愛樂、倫敦交響樂團、BBC交響樂團（1987年逍遙音樂會）、巴黎管弦樂團、法國國家交響樂團、柏林交響樂團、匈牙利國家交響樂團、奧斯陸愛樂、鹿特丹愛樂、義大利國家廣播交響樂團、華沙愛樂以及英國室內樂團等等。\r\n \r\n\r\n白建宇灌錄許多唱片，包括史克里亞賓、李斯特以及穆索斯基的作品，以及拉赫曼尼諾夫的鋼琴協奏曲全集。白建宇的普羅高夫鋼琴協奏曲全集獲得1993年法國「金叉獎」，之後錄製布梭尼的巴赫改編曲以及佛瑞的專輯，樂評給予極高評價；另外，白建宇也與魏特（Antoni Wit）／華沙愛樂合作，灌錄蕭邦的鋼琴與管弦樂團作品全集。2005-2007年，白建宇在Decca錄製貝多芬全本32首鋼琴奏鳴曲。\r\n\r\n\r\n白建宇在卡內基音樂廳與史卡拉歌劇院舉行音樂會，由泰米卡諾夫指揮聖彼德堡愛樂樂團共同演出。此外，白建宇也做客新日本愛樂交響樂團、中國愛樂樂團、上海交響樂團以及貝根愛樂樂團；在法國、義大利、西班牙等地舉行鋼琴獨奏會。近年來白建宇在DG發行包括布拉姆斯的第一號鋼琴協奏曲、晚期鋼琴小品錄音，舒伯特即興曲、三首鋼琴小品、樂興之時，最新的發行包括蕭邦的夜曲全集，以及舒曼鋼琴獨奏作品集，葛拉納多斯的《哥雅畫冊》等錄音。\r\n \r\n\r\n白建宇於2002年獲得法國政府頒發的「文學與藝術勳章」，目前定居巴黎。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n莫札特：C大調第16號鋼琴奏鳴曲，K. 545\r\n\r\n莫札特：a小調輪旋曲，K. 511\r\n\r\n莫札特：F大調第12號鋼琴奏鳴曲，K. 332\r\n\r\n莫札特：C大調寫給玻璃琴的慢板，K. 356 (617a)\r\n\r\n莫札特：C大調進行曲，K. 408/1\r\n\r\n莫札特：C大調第十號鋼琴奏鳴曲，K. 330\r\n\r\n莫札特：c小調幻想曲，K. 475', '鵬博藝術股份有限公司Blooming Arts', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500;--+800;--+1200;--+1800;--+2400;--+3000', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《心境澄明－白建宇的莫札特之聲》', `description`='《心境澄明－白建宇的莫札特之聲》\r\n「名副其實且值得信賴的藝術大師、完美的音樂家。」《費加洛報》\r\n\r\n「白建宇的演奏如電閃雷鳴，能喚醒古老傳奇中的幽魂。」《紐約時報》\r\n\r\n「白建宇演奏的戲劇感、睿智、對細節的掌握、富有內涵的和弦，以及極致靈活的技巧，皆屬非凡。」《獨立報》\r\n\r\n \r\n\r\n白建宇十歲與韓國國家交響樂團合作演出葛利格的鋼琴協奏曲；15歲前往紐約茱麗亞音樂學院，師從羅西娜．列文涅（Rosina Lhevinne），並在倫敦拜師伊洛娜．卡波斯（Ilona Kabos）；同時白建宇也在義大利學習，師從圭多．阿戈斯蒂（Guido Agosti）與威廉．肯普夫（Willhelm Kempff）。白建宇的國際演奏生涯始於他的紐約首演，當時他在林肯中心演出拉威爾的鋼琴獨奏作品全集，聲名大噪，不久後也在卡內基大廳演出。白建宇曾經獲得許多國際鋼琴大賽首獎，最著名的是1969年布梭尼國際鋼琴大賽首獎。\r\n \r\n\r\n白建宇在林肯中心、卡內基廳、維格摩廳以及柏林愛樂廳等地舉行鋼琴獨奏會，此外他也與祖賓．梅塔（Zubin Mehta）、馬捷爾（Lorin Maazel）、揚頌斯（Mariss Jansons）、余隆（Long Yu）、馬利納爵士（Sir. Neville Marriner）、薩瓦利許（Wolfgang Sawallisch）、貝洛拉維克（Jiri Belohlavek）尤洛維斯基（Vladimir Jurowsky）、季坦科（Dmitri Kitaenko）、帕沃．賈維（Paavo Jarvi）、伊凡．費雪（Ivan Fischer）、潘德瑞茲基（Penderecki）等指揮家合作許多鋼琴協奏曲。白建宇合作過的樂團包括以色列愛樂、紐約愛樂、聖彼特堡愛樂、倫敦交響樂團、BBC交響樂團（1987年逍遙音樂會）、巴黎管弦樂團、法國國家交響樂團、柏林交響樂團、匈牙利國家交響樂團、奧斯陸愛樂、鹿特丹愛樂、義大利國家廣播交響樂團、華沙愛樂以及英國室內樂團等等。\r\n \r\n\r\n白建宇灌錄許多唱片，包括史克里亞賓、李斯特以及穆索斯基的作品，以及拉赫曼尼諾夫的鋼琴協奏曲全集。白建宇的普羅高夫鋼琴協奏曲全集獲得1993年法國「金叉獎」，之後錄製布梭尼的巴赫改編曲以及佛瑞的專輯，樂評給予極高評價；另外，白建宇也與魏特（Antoni Wit）／華沙愛樂合作，灌錄蕭邦的鋼琴與管弦樂團作品全集。2005-2007年，白建宇在Decca錄製貝多芬全本32首鋼琴奏鳴曲。\r\n\r\n\r\n白建宇在卡內基音樂廳與史卡拉歌劇院舉行音樂會，由泰米卡諾夫指揮聖彼德堡愛樂樂團共同演出。此外，白建宇也做客新日本愛樂交響樂團、中國愛樂樂團、上海交響樂團以及貝根愛樂樂團；在法國、義大利、西班牙等地舉行鋼琴獨奏會。近年來白建宇在DG發行包括布拉姆斯的第一號鋼琴協奏曲、晚期鋼琴小品錄音，舒伯特即興曲、三首鋼琴小品、樂興之時，最新的發行包括蕭邦的夜曲全集，以及舒曼鋼琴獨奏作品集，葛拉納多斯的《哥雅畫冊》等錄音。\r\n \r\n\r\n白建宇於2002年獲得法國政府頒發的「文學與藝術勳章」，目前定居巴黎。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n莫札特：C大調第16號鋼琴奏鳴曲，K. 545\r\n\r\n莫札特：a小調輪旋曲，K. 511\r\n\r\n莫札特：F大調第12號鋼琴奏鳴曲，K. 332\r\n\r\n莫札特：C大調寫給玻璃琴的慢板，K. 356 (617a)\r\n\r\n莫札特：C大調進行曲，K. 408/1\r\n\r\n莫札特：C大調第十號鋼琴奏鳴曲，K. 330\r\n\r\n莫札特：c小調幻想曲，K. 475', `organizer`='鵬博藝術股份有限公司Blooming Arts', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500;--+800;--+1200;--+1800;--+2400;--+3000', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be92c', '《鋼琴的多重宇宙~江恬儀2025鋼琴音樂會》', '《鋼琴的多重宇宙~江恬儀2025鋼琴音樂會》\r\n江恬儀將從不同角度探索鋼琴複音演奏的可能性，李斯特改編巴赫的管風琴聲響為鋼琴獨奏、貝多芬自己改編交響曲為鋼琴三重奏，顯現他在作曲過程中對鋼琴與管弦樂器聲響異同的看法；而舒曼將鋼琴獨奏曲特別取名為「沒有樂團的協奏曲」，更是明白表示了他要鋼琴同時扮演兩種聲音角色的野心。江恬儀近年來透過多個面向的曲目安排，以充滿想像空間的主題貫穿整個音樂會企劃，每一次的呈現都是不同的風景。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n巴哈-李斯特：A小調前奏與賦格，BWV. 543\r\n\r\n貝多芬：D大調第二號交響曲（改編鋼琴三重奏版），作品36\r\n\r\n舒曼：F小調第三號鋼琴奏鳴曲『無管弦樂團的協奏曲』，作品14\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n鋼琴｜江恬儀\r\n\r\n大提琴｜李百佳（協演）\r\n\r\n小提琴｜黃詠雩（協演）', '斐亞文化藝術股份有限公司', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500;--+800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《鋼琴的多重宇宙~江恬儀2025鋼琴音樂會》', `description`='《鋼琴的多重宇宙~江恬儀2025鋼琴音樂會》\r\n江恬儀將從不同角度探索鋼琴複音演奏的可能性，李斯特改編巴赫的管風琴聲響為鋼琴獨奏、貝多芬自己改編交響曲為鋼琴三重奏，顯現他在作曲過程中對鋼琴與管弦樂器聲響異同的看法；而舒曼將鋼琴獨奏曲特別取名為「沒有樂團的協奏曲」，更是明白表示了他要鋼琴同時扮演兩種聲音角色的野心。江恬儀近年來透過多個面向的曲目安排，以充滿想像空間的主題貫穿整個音樂會企劃，每一次的呈現都是不同的風景。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n巴哈-李斯特：A小調前奏與賦格，BWV. 543\r\n\r\n貝多芬：D大調第二號交響曲（改編鋼琴三重奏版），作品36\r\n\r\n舒曼：F小調第三號鋼琴奏鳴曲『無管弦樂團的協奏曲』，作品14\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n鋼琴｜江恬儀\r\n\r\n大提琴｜李百佳（協演）\r\n\r\n小提琴｜黃詠雩（協演）', `organizer`='斐亞文化藝術股份有限公司', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500;--+800', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be92d', '《風馳電掣－陳必先2025鋼琴獨奏會》', '《風馳電掣－陳必先2025鋼琴獨奏會》\r\n陳必先1950年出生於臺灣，五歲開始學習鋼琴，九歲獲准為第一位以音樂資賦優異兒童身分出國深造。隔年進入科隆音樂學院，受教於史密特-紐豪斯 (Hans Otto Schmidt-Neuhaus)、史托克豪森 (Karlheinz Stockhausen)。之後她陸續接受雷格拉夫 (Hans Leygraf)、肯普夫 (Wilhelm Kempff)、阿勞 (Claudio Arrau)、安達 (Geza Anda)，以及尼可萊耶娃 (Tatjana Nikolajewa) 的指導。陳必先1972年6月參加比利時布魯塞爾伊莉莎白大賽得獎，同年9月獲得ARD國際大賽首獎，1977年在鹿特丹國際荀貝格大賽獲得首獎，1980年在華盛頓國際巴赫大賽獲得首獎。1983年起陳必先應邀擔任科隆音樂學院鋼琴教授，2004年起於弗萊堡音樂大學任教，並且定居德國。\r\n\r\n陳必先受邀在倫敦、柏林、慕尼黑、蘇黎世、阿姆斯特丹、東京、南美、波士頓、聖地牙哥、北京、上海、廣州等地演出，並且和世界一流的著名樂團合作，包括英國皇家愛樂管弦樂團、倫敦交響樂團、BBC英國廣播交響樂團、蘇格蘭室內樂團、阿姆斯特丹大會堂交響樂團、蘇黎世室內樂團、蘇黎世音樂廳管弦樂團、日本NHK交響樂團。\r\n\r\n在與布列茲 (Pierre Boulez)、史托克豪森、庫塔克、卡特 (Elliot Carter) 等作曲家的頻繁合作之下，陳必先對當代作品產生濃厚的興趣：她與許多現代作曲家合作拍攝紀錄片，包括由法國龐畢度聲學暨音樂研究協調學會 (IRCAM) 所拍攝、布列茲《符號》(Notations) 首演的準備過程，還有在紀錄片《黑與白》中演奏卡特《鋼琴大鍵琴與兩個室內樂團的雙協奏曲》。ARTE於2014年在奇美博物館的協助下製作紀錄片《稻田裡的音符》，也提及陳必先對臺灣音樂生活所扮演之先鋒角色。陳必先頻繁受邀於多瑙興根音樂節 (Donaueschingen Festival)，於2010年首演哈斯 (Georg Friedrich Haas)《有限的近似》(limited approximation)，對當代作品極具開創性之貢獻。 \r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n巴赫：D大調第四號組曲，BWV 828\r\n\r\n布列茲：第三號鋼琴奏鳴曲\r\n\r\n貝爾格：鋼琴奏鳴曲，作品一\r\n\r\n德布西：第9，10，11號練習曲，選自12首練習曲，L 136\r\n\r\n貝多芬：c小調第32號鋼琴奏鳴曲，作品111', '鵬博藝術股份有限公司Blooming Arts', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-26 00:00:00', '2025-03-26 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500;--+800;--+1200;--+1600;--+2000;--+2500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《風馳電掣－陳必先2025鋼琴獨奏會》', `description`='《風馳電掣－陳必先2025鋼琴獨奏會》\r\n陳必先1950年出生於臺灣，五歲開始學習鋼琴，九歲獲准為第一位以音樂資賦優異兒童身分出國深造。隔年進入科隆音樂學院，受教於史密特-紐豪斯 (Hans Otto Schmidt-Neuhaus)、史托克豪森 (Karlheinz Stockhausen)。之後她陸續接受雷格拉夫 (Hans Leygraf)、肯普夫 (Wilhelm Kempff)、阿勞 (Claudio Arrau)、安達 (Geza Anda)，以及尼可萊耶娃 (Tatjana Nikolajewa) 的指導。陳必先1972年6月參加比利時布魯塞爾伊莉莎白大賽得獎，同年9月獲得ARD國際大賽首獎，1977年在鹿特丹國際荀貝格大賽獲得首獎，1980年在華盛頓國際巴赫大賽獲得首獎。1983年起陳必先應邀擔任科隆音樂學院鋼琴教授，2004年起於弗萊堡音樂大學任教，並且定居德國。\r\n\r\n陳必先受邀在倫敦、柏林、慕尼黑、蘇黎世、阿姆斯特丹、東京、南美、波士頓、聖地牙哥、北京、上海、廣州等地演出，並且和世界一流的著名樂團合作，包括英國皇家愛樂管弦樂團、倫敦交響樂團、BBC英國廣播交響樂團、蘇格蘭室內樂團、阿姆斯特丹大會堂交響樂團、蘇黎世室內樂團、蘇黎世音樂廳管弦樂團、日本NHK交響樂團。\r\n\r\n在與布列茲 (Pierre Boulez)、史托克豪森、庫塔克、卡特 (Elliot Carter) 等作曲家的頻繁合作之下，陳必先對當代作品產生濃厚的興趣：她與許多現代作曲家合作拍攝紀錄片，包括由法國龐畢度聲學暨音樂研究協調學會 (IRCAM) 所拍攝、布列茲《符號》(Notations) 首演的準備過程，還有在紀錄片《黑與白》中演奏卡特《鋼琴大鍵琴與兩個室內樂團的雙協奏曲》。ARTE於2014年在奇美博物館的協助下製作紀錄片《稻田裡的音符》，也提及陳必先對臺灣音樂生活所扮演之先鋒角色。陳必先頻繁受邀於多瑙興根音樂節 (Donaueschingen Festival)，於2010年首演哈斯 (Georg Friedrich Haas)《有限的近似》(limited approximation)，對當代作品極具開創性之貢獻。 \r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n巴赫：D大調第四號組曲，BWV 828\r\n\r\n布列茲：第三號鋼琴奏鳴曲\r\n\r\n貝爾格：鋼琴奏鳴曲，作品一\r\n\r\n德布西：第9，10，11號練習曲，選自12首練習曲，L 136\r\n\r\n貝多芬：c小調第32號鋼琴奏鳴曲，作品111', `organizer`='鵬博藝術股份有限公司Blooming Arts', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-26 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500;--+800;--+1200;--+1600;--+2000;--+2500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be92e', '【衛武營小時光】C MUSICAL《陪伴．有真與有真》音樂劇讀演會', '【衛武營小時光】C MUSICAL《陪伴．有真與有真》音樂劇讀演會\r\n\r\n好評迴響\r\n\r\n本身是服務相關議題的社工，因此看到有談論這個議題的作品感到相當開心，也透過整個觀演歷程跟著劇中角色一起找到治癒自己的能力、彼此陪伴的力量。很感動能夠把劇中角色的處境感受表現出來，非常希望能有更多人因為透過這個作品關注這個議題、一起被療癒。——臺北觀眾\r\n\r\n很喜歡用這樣溫暖的手法去觸碰一些很難過的議題，有些共感的地方也讓人不禁落淚，但還是獲得了一股勇敢面對明天的力量。——臺北觀眾\r\n\r\n這不是容易處理的素材，很感謝以溫柔的方式而堅強，有希望的方式，讓人重新燃起對於活下去和面對自己與家人的希望。——臺北觀眾\r\n\r\n\r\n \r\n\r\n療癒型音樂劇讀演會首度來訪衛武營\r\n\r\n透過陪伴的溫度，帶你找尋傷痛的出口\r\n\r\n \r\n\r\n大甜、李玲葦 feat. 陳明珠＝絕無僅有的三人同台組合！\r\n\r\n衛武營限定！不只演給你看還說給你聽！\r\n\r\n由大甜與李玲葦溫柔詮釋兩位同名的青春少女，\r\n\r\n特別邀請陳明珠主持獨家版本，帶你一同走進有真與有真的故事。\r\n\r\n60分鐘裡，衛武營表演廳中不插電樂器的原聲音響與獨家三人組合，\r\n\r\n聽見我們為你精選的歌曲片段，聊聊這齣戲從韓國來到臺灣的點點滴滴，\r\n\r\n說說排練期間裡演員的心路歷程。\r\n\r\n \r\n\r\n這世界上有許多「有真」，徘徊在困頓、茫然和無法宣洩的自責中。\r\n\r\n讓我們成為攜手陪伴的人，溫柔地說著：「這不是妳的錯」。\r\n\r\n \r\n\r\n★ 2021年韓國首演，180多場好評巡演\r\n\r\n★ 改編自韓國熱銷30萬本同名青少年文學著作\r\n\r\n★ 入圍第六屆韓國音樂劇大賞最佳劇本和最佳作曲\r\n\r\n \r\n\r\n國中二年級一開學，李有真遇見了轉學生李有真，同名同姓讓大家分別以個性開朗的「大有真」，和課業優異卻高冷的轉學生「小有真」區隔；大有真認出曾為幼兒園同學的小有真，相認後卻遭到迴避，隨著兩人生活緊密交織，當年的「幼兒園事件」再次浮上記憶，揭開兩人和家人間不再提起的傷痛。而究竟痛苦的回憶該遺忘，或是負重前行？\r\n\r\n \r\n\r\n「即使重重落下，還是能再高高飛起。」\r\n\r\n \r\n\r\n改編自韓國知名青少年文學作家李琴䬁（一ˊ）熱銷代表作，出版20年療癒超過30萬名不同世代的讀者，以青少年語彙，溫柔呈現兒童性剝削與青春期傷痛；音樂劇於2021年韓國首演，隔年好評加演，2023年首次以中文版讀劇演出，全女性創作團隊的暖心之作，2025年在衛武營以演唱精選片段的形式，陪伴全世界的「李有真」找到傷痛的出口。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n演員｜大甜、李玲葦\r\n\r\n特邀演出｜陳明珠\r\n\r\n鋼琴｜施怡安\r\n\r\n大提琴｜羅翡翠\r\n\r\n \r\n\r\n主創團隊\r\n\r\n藝術總監｜Damiro\r\n\r\n原著｜이금이 李琴䬁\r\n\r\n原創導演｜이기쁨 LEE Kipeum\r\n\r\n劇本｜김솔지 金率智\r\n\r\n作曲｜안예은 安藝恩\r\n\r\n音樂執導｜양지해 羊智海\r\n\r\n影像設計｜고동욱 高東煜（EASThug）\r\n\r\n影像助理｜문유진 文有眞\r\n\r\n \r\n\r\n劇本譯詞暨藝術總監｜張芯慈\r\n\r\n執行導演｜洪信惠\r\n\r\n歌唱指導｜陳品伶\r\n\r\n燈光設計｜曹芯慈\r\n\r\n舞台監督暨排練助理｜詹宜玫\r\n\r\n舞台技術指導｜徐嘉瑜\r\n\r\n製作人｜張芯慈、黃肇璟\r\n\r\n \r\n\r\n  團隊介紹  \r\n\r\n陳明珠\r\n\r\n知名主持人與歌手。曾出演音樂劇《苦魯人生》，客串嘉賓客家電視台《客庄好味道》《一家之煮》，亦曾主持八大第一台《Gogo講客話》、《超級巨星紅白藝能大賞》、金鐘獎、金曲獎典禮及紅毯。\r\n\r\n \r\n\r\n大甜\r\n\r\n表演藝術工作者。常嶄露頭角於音樂劇及現代戲劇演出中，近年更嘗試傳統戲曲跨界。聲音渾厚飽滿且清透溫暖，表演極具爆發力及能量。詮釋角色多元且豐沛，已是臺灣備受矚目的演員。但依然期許能成為良好載體，跨度更多不同可能，不設限自己存在於舞台的樣態和方式，企圖找尋身體與聲音的寬闊景觀。\r\n\r\n近期演出作品｜\r\n\r\nC MUSICAL製作《有真與有真》、《小王子》、2023臺北藝術節《飆舞士林2.0》；果陀劇場《解憂雜貨店》；飛人集社《藏畫》；國表藝三館共製《鯨之嶋》；NCO《馬偕情書》；瘋戲樂工作室《LPC》中文版；台南人劇團《第十二夜》；天作之合劇場《飲食男女》；人力飛行劇團《向左走向右走》...等。\r\n\r\n \r\n\r\n李玲葦\r\n\r\n活躍於電影、電視、MV及舞台劇演出。\r\n\r\n主演影視作品包含電影《青春並不溫柔》、電影《生而為人》、公視人生劇展《同名同姓》、臺法合製短片《長夜》、公視影集《返校》等。\r\n\r\n參演多部劇場作品包含C MUSICAL製作《有真與有真》、《我的上海天菜》；森焱堂×幾米《忘記親一下》多媒體操偶音樂劇、《關於那些愛情場景》音樂劇、《分手快樂》音樂劇、鄧九雲溫聲細語讀劇會《一個可能的進行式》等。\r\n\r\n \r\n\r\nC MUSICAL 芯誠所製\r\n\r\nC MUSICAL．SEE MUSICAL\r\n\r\n以製作與創作中文音樂劇為發展核心，原創作品不僅受到觀眾的歡迎與肯定，IP更授權至海外、影視進行製作。\r\n\r\n創團以來，C MUSICAL致力於將作品帶上國際舞臺以及跨國交流、合作，作品曾受邀至韓國大邱國際音樂劇節、北京兩岸小劇場藝術節、上海大觀藝術節演出。近年來也多次邀請韓國音樂劇導演、編舞、編劇、歌唱指導來臺合作，並引進韓國音樂劇作品中文化，期許帶給觀眾更多元的音樂劇體驗。\r\n\r\n \r\n\r\nCare．Cure．Comfort\r\n\r\n讓音樂劇成為一種日常，用音樂劇去照顧、療癒、撫慰現代生活裡的忙碌、疲憊與孤獨。授權製作與國際共製的音樂劇有：韓版授權音樂劇《Let Me Fly》、臺韓合製兒童音樂劇《救援小英雄POLI：出動吧，找回黃金獎杯》、韓版授權音樂劇中文版讀劇演出《有真與有真》、臺韓合創音樂劇《伊底帕斯》（與韓國拼死奔跑劇團合製）、韓版授權音樂劇《小王子》、音樂劇《徽因》（與廣藝基金會合製）、臺韓合創懸疑音樂劇《傾城記》、音樂劇《馬卡龍與羅密歐》（與上海墨依文化傳播有限公司合製）；國際巡演：韓國音樂劇《拉赫曼尼諾夫》、臺韓合創音樂劇《伊底帕斯》新北音樂劇節演出節目（與韓國拼死奔跑劇團合製）；原創音樂劇：音樂劇《我的上海天菜》、獨角音樂劇《焢肉遇見你》（授權北京開心麻花改編為獨角音樂劇《求婚女王》）、原創中文音樂劇《最美的一天》（廣藝基金會委託創作）、影集式音樂劇《不讀書俱樂部》EP.1-3（獲2015年DIMF評審委員特別獎、授權影視拍攝）。\r\n\r\n \r\n\r\n圖片\r\n\r\n圖片\r\n ', '國家表演藝術中心衛武營國家藝術文化中心', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-26 00:00:00', '2025-03-26 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+300;--+500;--+800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【衛武營小時光】C MUSICAL《陪伴．有真與有真》音樂劇讀演會', `description`='【衛武營小時光】C MUSICAL《陪伴．有真與有真》音樂劇讀演會\r\n\r\n好評迴響\r\n\r\n本身是服務相關議題的社工，因此看到有談論這個議題的作品感到相當開心，也透過整個觀演歷程跟著劇中角色一起找到治癒自己的能力、彼此陪伴的力量。很感動能夠把劇中角色的處境感受表現出來，非常希望能有更多人因為透過這個作品關注這個議題、一起被療癒。——臺北觀眾\r\n\r\n很喜歡用這樣溫暖的手法去觸碰一些很難過的議題，有些共感的地方也讓人不禁落淚，但還是獲得了一股勇敢面對明天的力量。——臺北觀眾\r\n\r\n這不是容易處理的素材，很感謝以溫柔的方式而堅強，有希望的方式，讓人重新燃起對於活下去和面對自己與家人的希望。——臺北觀眾\r\n\r\n\r\n \r\n\r\n療癒型音樂劇讀演會首度來訪衛武營\r\n\r\n透過陪伴的溫度，帶你找尋傷痛的出口\r\n\r\n \r\n\r\n大甜、李玲葦 feat. 陳明珠＝絕無僅有的三人同台組合！\r\n\r\n衛武營限定！不只演給你看還說給你聽！\r\n\r\n由大甜與李玲葦溫柔詮釋兩位同名的青春少女，\r\n\r\n特別邀請陳明珠主持獨家版本，帶你一同走進有真與有真的故事。\r\n\r\n60分鐘裡，衛武營表演廳中不插電樂器的原聲音響與獨家三人組合，\r\n\r\n聽見我們為你精選的歌曲片段，聊聊這齣戲從韓國來到臺灣的點點滴滴，\r\n\r\n說說排練期間裡演員的心路歷程。\r\n\r\n \r\n\r\n這世界上有許多「有真」，徘徊在困頓、茫然和無法宣洩的自責中。\r\n\r\n讓我們成為攜手陪伴的人，溫柔地說著：「這不是妳的錯」。\r\n\r\n \r\n\r\n★ 2021年韓國首演，180多場好評巡演\r\n\r\n★ 改編自韓國熱銷30萬本同名青少年文學著作\r\n\r\n★ 入圍第六屆韓國音樂劇大賞最佳劇本和最佳作曲\r\n\r\n \r\n\r\n國中二年級一開學，李有真遇見了轉學生李有真，同名同姓讓大家分別以個性開朗的「大有真」，和課業優異卻高冷的轉學生「小有真」區隔；大有真認出曾為幼兒園同學的小有真，相認後卻遭到迴避，隨著兩人生活緊密交織，當年的「幼兒園事件」再次浮上記憶，揭開兩人和家人間不再提起的傷痛。而究竟痛苦的回憶該遺忘，或是負重前行？\r\n\r\n \r\n\r\n「即使重重落下，還是能再高高飛起。」\r\n\r\n \r\n\r\n改編自韓國知名青少年文學作家李琴䬁（一ˊ）熱銷代表作，出版20年療癒超過30萬名不同世代的讀者，以青少年語彙，溫柔呈現兒童性剝削與青春期傷痛；音樂劇於2021年韓國首演，隔年好評加演，2023年首次以中文版讀劇演出，全女性創作團隊的暖心之作，2025年在衛武營以演唱精選片段的形式，陪伴全世界的「李有真」找到傷痛的出口。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n演員｜大甜、李玲葦\r\n\r\n特邀演出｜陳明珠\r\n\r\n鋼琴｜施怡安\r\n\r\n大提琴｜羅翡翠\r\n\r\n \r\n\r\n主創團隊\r\n\r\n藝術總監｜Damiro\r\n\r\n原著｜이금이 李琴䬁\r\n\r\n原創導演｜이기쁨 LEE Kipeum\r\n\r\n劇本｜김솔지 金率智\r\n\r\n作曲｜안예은 安藝恩\r\n\r\n音樂執導｜양지해 羊智海\r\n\r\n影像設計｜고동욱 高東煜（EASThug）\r\n\r\n影像助理｜문유진 文有眞\r\n\r\n \r\n\r\n劇本譯詞暨藝術總監｜張芯慈\r\n\r\n執行導演｜洪信惠\r\n\r\n歌唱指導｜陳品伶\r\n\r\n燈光設計｜曹芯慈\r\n\r\n舞台監督暨排練助理｜詹宜玫\r\n\r\n舞台技術指導｜徐嘉瑜\r\n\r\n製作人｜張芯慈、黃肇璟\r\n\r\n \r\n\r\n  團隊介紹  \r\n\r\n陳明珠\r\n\r\n知名主持人與歌手。曾出演音樂劇《苦魯人生》，客串嘉賓客家電視台《客庄好味道》《一家之煮》，亦曾主持八大第一台《Gogo講客話》、《超級巨星紅白藝能大賞》、金鐘獎、金曲獎典禮及紅毯。\r\n\r\n \r\n\r\n大甜\r\n\r\n表演藝術工作者。常嶄露頭角於音樂劇及現代戲劇演出中，近年更嘗試傳統戲曲跨界。聲音渾厚飽滿且清透溫暖，表演極具爆發力及能量。詮釋角色多元且豐沛，已是臺灣備受矚目的演員。但依然期許能成為良好載體，跨度更多不同可能，不設限自己存在於舞台的樣態和方式，企圖找尋身體與聲音的寬闊景觀。\r\n\r\n近期演出作品｜\r\n\r\nC MUSICAL製作《有真與有真》、《小王子》、2023臺北藝術節《飆舞士林2.0》；果陀劇場《解憂雜貨店》；飛人集社《藏畫》；國表藝三館共製《鯨之嶋》；NCO《馬偕情書》；瘋戲樂工作室《LPC》中文版；台南人劇團《第十二夜》；天作之合劇場《飲食男女》；人力飛行劇團《向左走向右走》...等。\r\n\r\n \r\n\r\n李玲葦\r\n\r\n活躍於電影、電視、MV及舞台劇演出。\r\n\r\n主演影視作品包含電影《青春並不溫柔》、電影《生而為人》、公視人生劇展《同名同姓》、臺法合製短片《長夜》、公視影集《返校》等。\r\n\r\n參演多部劇場作品包含C MUSICAL製作《有真與有真》、《我的上海天菜》；森焱堂×幾米《忘記親一下》多媒體操偶音樂劇、《關於那些愛情場景》音樂劇、《分手快樂》音樂劇、鄧九雲溫聲細語讀劇會《一個可能的進行式》等。\r\n\r\n \r\n\r\nC MUSICAL 芯誠所製\r\n\r\nC MUSICAL．SEE MUSICAL\r\n\r\n以製作與創作中文音樂劇為發展核心，原創作品不僅受到觀眾的歡迎與肯定，IP更授權至海外、影視進行製作。\r\n\r\n創團以來，C MUSICAL致力於將作品帶上國際舞臺以及跨國交流、合作，作品曾受邀至韓國大邱國際音樂劇節、北京兩岸小劇場藝術節、上海大觀藝術節演出。近年來也多次邀請韓國音樂劇導演、編舞、編劇、歌唱指導來臺合作，並引進韓國音樂劇作品中文化，期許帶給觀眾更多元的音樂劇體驗。\r\n\r\n \r\n\r\nCare．Cure．Comfort\r\n\r\n讓音樂劇成為一種日常，用音樂劇去照顧、療癒、撫慰現代生活裡的忙碌、疲憊與孤獨。授權製作與國際共製的音樂劇有：韓版授權音樂劇《Let Me Fly》、臺韓合製兒童音樂劇《救援小英雄POLI：出動吧，找回黃金獎杯》、韓版授權音樂劇中文版讀劇演出《有真與有真》、臺韓合創音樂劇《伊底帕斯》（與韓國拼死奔跑劇團合製）、韓版授權音樂劇《小王子》、音樂劇《徽因》（與廣藝基金會合製）、臺韓合創懸疑音樂劇《傾城記》、音樂劇《馬卡龍與羅密歐》（與上海墨依文化傳播有限公司合製）；國際巡演：韓國音樂劇《拉赫曼尼諾夫》、臺韓合創音樂劇《伊底帕斯》新北音樂劇節演出節目（與韓國拼死奔跑劇團合製）；原創音樂劇：音樂劇《我的上海天菜》、獨角音樂劇《焢肉遇見你》（授權北京開心麻花改編為獨角音樂劇《求婚女王》）、原創中文音樂劇《最美的一天》（廣藝基金會委託創作）、影集式音樂劇《不讀書俱樂部》EP.1-3（獲2015年DIMF評審委員特別獎、授權影視拍攝）。\r\n\r\n \r\n\r\n圖片\r\n\r\n圖片\r\n ', `organizer`='國家表演藝術中心衛武營國家藝術文化中心', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-26 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+300;--+500;--+800', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be92f', '《音樂晚會的跨文化激盪》', '《音樂晚會的跨文化激盪》\r\n屏東大學音樂學系教授群聯合演出古典時期至當代美、德、奧、義、西、俄及台灣作曲家作品，包含：伊瓦森、舒伯特、李斯特、理察·史特勞斯、唐尼采第、康戈爾德、圖里納、蕭斯塔高維奇、臺灣作曲家蕭永陞（屏東大學專任助理教授）及前輩作曲家黃輔棠等之獨奏、獨唱、二重奏、三重奏、四重奏及雙鋼琴作品。期以多元音樂文化激盪跨國樂想，共饗樂友。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n伊瓦森：《野花》三重奏，第一樂章〈麒麟菊〉與第三樂章〈草原松果菊〉\r\n\r\n舒伯特：A大調小提琴與鋼琴的奏鳴曲，作品574，第三樂章與第四樂章\r\n\r\n李斯特改編羅西尼：《音樂晚會》第五首〈譴責〉與第九首〈舞蹈〉，作品 424\r\n\r\n史特勞斯：奉獻\r\n\r\n董尼采第：心靈之光（選自歌劇「村女琳達」）\r\n\r\n康戈爾德：給兩把小提琴、大提琴及左手鋼琴的組曲，作品23，第三樂章\r\n\r\n圖里納﹕a小調鋼琴四重奏，作品67\r\n\r\n蕭永陞：《星火流影》，為雙鋼琴 \r\n\r\n蕭斯塔高維奇：A小調雙鋼琴小協奏曲\r\n\r\n阿鏜：《神鵰俠侶》交響曲第七樂章-「群英賀壽」雙鋼琴版 （世界首演）\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n國立屏東大學音樂學系教授群', '國立屏東大學', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-27 00:00:00', '2025-03-27 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+300;--+500;--+800;--+1000', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《音樂晚會的跨文化激盪》', `description`='《音樂晚會的跨文化激盪》\r\n屏東大學音樂學系教授群聯合演出古典時期至當代美、德、奧、義、西、俄及台灣作曲家作品，包含：伊瓦森、舒伯特、李斯特、理察·史特勞斯、唐尼采第、康戈爾德、圖里納、蕭斯塔高維奇、臺灣作曲家蕭永陞（屏東大學專任助理教授）及前輩作曲家黃輔棠等之獨奏、獨唱、二重奏、三重奏、四重奏及雙鋼琴作品。期以多元音樂文化激盪跨國樂想，共饗樂友。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n伊瓦森：《野花》三重奏，第一樂章〈麒麟菊〉與第三樂章〈草原松果菊〉\r\n\r\n舒伯特：A大調小提琴與鋼琴的奏鳴曲，作品574，第三樂章與第四樂章\r\n\r\n李斯特改編羅西尼：《音樂晚會》第五首〈譴責〉與第九首〈舞蹈〉，作品 424\r\n\r\n史特勞斯：奉獻\r\n\r\n董尼采第：心靈之光（選自歌劇「村女琳達」）\r\n\r\n康戈爾德：給兩把小提琴、大提琴及左手鋼琴的組曲，作品23，第三樂章\r\n\r\n圖里納﹕a小調鋼琴四重奏，作品67\r\n\r\n蕭永陞：《星火流影》，為雙鋼琴 \r\n\r\n蕭斯塔高維奇：A小調雙鋼琴小協奏曲\r\n\r\n阿鏜：《神鵰俠侶》交響曲第七樂章-「群英賀壽」雙鋼琴版 （世界首演）\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n國立屏東大學音樂學系教授群', `organizer`='國立屏東大學', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-27 00:00:00', `end_date`='2025-03-27 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+300;--+500;--+800;--+1000', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be930', '舞台劇《最後14堂星期二的課》', '舞台劇《最後14堂星期二的課》\r\n\r\n \r\n\r\n罹患「肌萎縮性脊髓側索硬化症」（簡稱ALS）的莫利教授，利用14個星期二的時間裡與學生米奇展開了既幽默又觸動人心的生死對話。\r\n\r\n一位體育專欄作家米奇畢業十六年後，在自己的許多理想中迷失了自我。偶然從電視上看見大學時期對他期望最大的教授莫利竟罹患了無藥可醫的「肌萎縮性脊髓側索硬化症」（簡稱ALS）。師生二人久別重逢，不畏懼「死亡」的教授以自己的生命為活教材，把自己最真實的生命經驗教授給這位世故而冷漠、追求物質的學生，希望透過學生的記錄，把自己走過來的生命歷程、生死的領悟記錄下來，利用14個星期二的時間裡與學生展開了既幽默又觸動人心的生死對話。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n導演／劇本翻譯｜楊世彭\r\n\r\n小說原著｜Mitch Albom\r\n\r\n原著劇本｜Jeffrey Hatcher、Mitch Albom\r\n\r\n服裝造型設計｜王怡美\r\n\r\n舞台設計｜劉達倫\r\n\r\n燈光設計｜曹安徽\r\n\r\n音樂暨音效設計｜Jeff Mockus\r\n\r\n影像設計｜王奕盛\r\n\r\n主演｜金士傑、卜學亮', '果陀百娛股份有限公司', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-28 00:00:00', '2025-03-30 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500;--+900;--+1400;--+1700;--+2000;--+2300;--+2600', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='舞台劇《最後14堂星期二的課》', `description`='舞台劇《最後14堂星期二的課》\r\n\r\n \r\n\r\n罹患「肌萎縮性脊髓側索硬化症」（簡稱ALS）的莫利教授，利用14個星期二的時間裡與學生米奇展開了既幽默又觸動人心的生死對話。\r\n\r\n一位體育專欄作家米奇畢業十六年後，在自己的許多理想中迷失了自我。偶然從電視上看見大學時期對他期望最大的教授莫利竟罹患了無藥可醫的「肌萎縮性脊髓側索硬化症」（簡稱ALS）。師生二人久別重逢，不畏懼「死亡」的教授以自己的生命為活教材，把自己最真實的生命經驗教授給這位世故而冷漠、追求物質的學生，希望透過學生的記錄，把自己走過來的生命歷程、生死的領悟記錄下來，利用14個星期二的時間裡與學生展開了既幽默又觸動人心的生死對話。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n導演／劇本翻譯｜楊世彭\r\n\r\n小說原著｜Mitch Albom\r\n\r\n原著劇本｜Jeffrey Hatcher、Mitch Albom\r\n\r\n服裝造型設計｜王怡美\r\n\r\n舞台設計｜劉達倫\r\n\r\n燈光設計｜曹安徽\r\n\r\n音樂暨音效設計｜Jeff Mockus\r\n\r\n影像設計｜王奕盛\r\n\r\n主演｜金士傑、卜學亮', `organizer`='果陀百娛股份有限公司', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500;--+900;--+1400;--+1700;--+2000;--+2300;--+2600', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be932', '《金秋歌廳秀》', '《金秋歌廳秀》\r\n★『金秋大樂隊的演出混合著藝術性與娛樂性，在開心聽音樂的同時，也能體驗到團員們的精湛技巧。』——臺北爵士大樂隊團長／李承育\r\n\r\n★「一起感受閩南與爵士樂再製改編，引領大家懷舊回憶。」——享象 Rhythmscape  \r\n\r\n \r\n\r\n看過金秋大樂隊的現場演出，不禁被他們的音樂所吸引，接地氣的風格和即興默契都是特色，如果說演唱會是歌手的現場考驗，金秋大樂隊的現場演出就是樂團界的經典！\r\n\r\n加上二次改編經典歌曲亦是我們的強項與特色，音樂呈現為純管樂搭配節奏組樂器表演，即使沒有歌手演唱，音樂感染力亦撼動人心，而且音樂能帶給聽眾不可思議的力量！希望大家用輕鬆愉悅的方式來聽音樂看表演，達到兼具音樂教育與寓教於樂的效果，建立金秋大樂隊即代表臺灣代表樂隊的品牌印象。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n北酒場、望月想愛人、舞女、愛情騙子、等一下呢、飲淡薄、葉啟田、江蕙組曲、愛情恰恰、含淚跳恰恰、一支小雨傘、歡喜來恰恰\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n音樂總監｜游鎮宇、鄧世偉\r\n\r\n貝斯｜游鎮宇\r\n\r\n吉他｜范君豪\r\n\r\n鼓手｜林冠宏\r\n\r\n鍵盤｜蔡慧蓮\r\n\r\n長號｜鄧世偉、哈博元\r\n\r\n小號｜林昀佋、呂家欣、費元、劉承執\r\n\r\n薩克斯風｜魯湘永、江川徹、李東耘、謝青峰\r\n\r\n音控｜魏世瑋\r\n\r\n樂團總監｜林欣\r\n\r\n樂團助理｜林怡均、彭盈慈', '音樂工人工作室', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《金秋歌廳秀》', `description`='《金秋歌廳秀》\r\n★『金秋大樂隊的演出混合著藝術性與娛樂性，在開心聽音樂的同時，也能體驗到團員們的精湛技巧。』——臺北爵士大樂隊團長／李承育\r\n\r\n★「一起感受閩南與爵士樂再製改編，引領大家懷舊回憶。」——享象 Rhythmscape  \r\n\r\n \r\n\r\n看過金秋大樂隊的現場演出，不禁被他們的音樂所吸引，接地氣的風格和即興默契都是特色，如果說演唱會是歌手的現場考驗，金秋大樂隊的現場演出就是樂團界的經典！\r\n\r\n加上二次改編經典歌曲亦是我們的強項與特色，音樂呈現為純管樂搭配節奏組樂器表演，即使沒有歌手演唱，音樂感染力亦撼動人心，而且音樂能帶給聽眾不可思議的力量！希望大家用輕鬆愉悅的方式來聽音樂看表演，達到兼具音樂教育與寓教於樂的效果，建立金秋大樂隊即代表臺灣代表樂隊的品牌印象。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n北酒場、望月想愛人、舞女、愛情騙子、等一下呢、飲淡薄、葉啟田、江蕙組曲、愛情恰恰、含淚跳恰恰、一支小雨傘、歡喜來恰恰\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n音樂總監｜游鎮宇、鄧世偉\r\n\r\n貝斯｜游鎮宇\r\n\r\n吉他｜范君豪\r\n\r\n鼓手｜林冠宏\r\n\r\n鍵盤｜蔡慧蓮\r\n\r\n長號｜鄧世偉、哈博元\r\n\r\n小號｜林昀佋、呂家欣、費元、劉承執\r\n\r\n薩克斯風｜魯湘永、江川徹、李東耘、謝青峰\r\n\r\n音控｜魏世瑋\r\n\r\n樂團總監｜林欣\r\n\r\n樂團助理｜林怡均、彭盈慈', `organizer`='音樂工人工作室', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+800', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741226b32408680be933', '《愛無限---台北愛樂少年及兒童合唱團高雄巡迴音樂會》', '《愛無限---台北愛樂少年及兒童合唱團高雄巡迴音樂會》\r\n為展現精湛的實力與演唱技巧，以「愛」為主題我們將為您演出裴哥雷西《聖母悼歌》，特別邀請女高音梁又中、次女高音鄭海芸及私立靜心弦樂團演出，期盼以優異的表現能完整呈現裴哥雷西曠世巨作。挑選多首與愛相關曲目，一同迎接2025年春季的到來！ \r\n\r\n \r\n\r\n  演出曲目  \r\n\r\nPergolesi：Stabat Mater 聖母悼歌\r\n\r\n冉天豪：Cina （媽媽）&心肝寶貝\r\n\r\nKurt Knecht：Manly Men『男子氣慨』\r\n\r\nDamijan Močnik：Si Vox est , Canta\r\n\r\nEric Whitacre：Five Hebrew Love Songs\r\n\r\nRollo Dilworth：Elijah Rock\r\n\r\n劉毅：憨囝仔\r\n\r\nClaude-Michel Schönberg (arr. Bob Lowden)：Selections from Les Misérables\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n合唱團｜台北愛樂少年及兒童合唱團\r\n\r\n客席指揮｜謝斯韻、鍾華琳\r\n\r\n指揮｜傅湘雲、劉曉書\r\n\r\n鋼琴｜黃語蓁、蘇于宸\r\n\r\n特邀演出｜臺北市靜心高級中學國中部管弦樂團\r\n\r\n指揮｜金秉翔\r\n\r\n聯演團體｜天生音籟兒童合唱團\r\n\r\n藝術總監｜陳安瑜\r\n\r\n音樂總監暨指揮｜周奕伶\r\n\r\n鋼琴合作｜林亭君 ', '臺北愛樂兒童合唱團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+300;--+500;--+800;--+1000;--+1200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《愛無限---台北愛樂少年及兒童合唱團高雄巡迴音樂會》', `description`='《愛無限---台北愛樂少年及兒童合唱團高雄巡迴音樂會》\r\n為展現精湛的實力與演唱技巧，以「愛」為主題我們將為您演出裴哥雷西《聖母悼歌》，特別邀請女高音梁又中、次女高音鄭海芸及私立靜心弦樂團演出，期盼以優異的表現能完整呈現裴哥雷西曠世巨作。挑選多首與愛相關曲目，一同迎接2025年春季的到來！ \r\n\r\n \r\n\r\n  演出曲目  \r\n\r\nPergolesi：Stabat Mater 聖母悼歌\r\n\r\n冉天豪：Cina （媽媽）&心肝寶貝\r\n\r\nKurt Knecht：Manly Men『男子氣慨』\r\n\r\nDamijan Močnik：Si Vox est , Canta\r\n\r\nEric Whitacre：Five Hebrew Love Songs\r\n\r\nRollo Dilworth：Elijah Rock\r\n\r\n劉毅：憨囝仔\r\n\r\nClaude-Michel Schönberg (arr. Bob Lowden)：Selections from Les Misérables\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n合唱團｜台北愛樂少年及兒童合唱團\r\n\r\n客席指揮｜謝斯韻、鍾華琳\r\n\r\n指揮｜傅湘雲、劉曉書\r\n\r\n鋼琴｜黃語蓁、蘇于宸\r\n\r\n特邀演出｜臺北市靜心高級中學國中部管弦樂團\r\n\r\n指揮｜金秉翔\r\n\r\n聯演團體｜天生音籟兒童合唱團\r\n\r\n藝術總監｜陳安瑜\r\n\r\n音樂總監暨指揮｜周奕伶\r\n\r\n鋼琴合作｜林亭君 ', `organizer`='臺北愛樂兒童合唱團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+300;--+500;--+800;--+1000;--+1200', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741326b32408680be934', '陳惠湄2025長笛演奏會《2025陳惠湄與她的朋友們－長笛與中提琴、豎琴篇》', '陳惠湄2025長笛演奏會《2025陳惠湄與她的朋友們－長笛與中提琴、豎琴篇》\r\n長笛家陳惠湄邀請豎琴家陳淑杏以及多年好友與音樂搭檔中提琴家富澤直子，演出德布西寫給長笛、中提琴與豎琴的奏鳴曲這個夢幻曲目，同時將介紹幾首以德布西為典範而寫給相同編制的樂曲。法國女性作曲家蕾傑曾受教於若利維，師徒倆都受到德布西啟發而為此編制創作；日本作曲家武滿徹不但以此編制寫作，在樂曲中還直接引用了德布西的音樂片段，可說是向德布西致敬的作品。本音樂會選取為這個特別的室內樂組合所創作的動聽樂曲，期望能帶給聽眾一場浪漫豐富的聽覺饗宴。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n狄奧多爾．杜步瓦：《三重奏小品》給長笛、中提琴與豎琴\r\n\r\n安德烈．若利維：《小組曲》給長笛、中提琴與豎琴\r\n\r\n艾狄特．蕾傑：《回憶的影子》給長笛、中提琴與豎琴（臺灣首演）\r\n\r\n武滿徹 ：《於是，我知道那是風》（そして、それが風であることを知った）給長笛、中提琴與豎琴\r\n\r\n克勞德．德布西：長笛、中提琴與豎琴奏鳴曲\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n長笛｜陳惠湄\r\n\r\n中提琴｜富澤直子\r\n\r\n豎琴｜陳淑杏', '就是愛樂管弦樂團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陳惠湄2025長笛演奏會《2025陳惠湄與她的朋友們－長笛與中提琴、豎琴篇》', `description`='陳惠湄2025長笛演奏會《2025陳惠湄與她的朋友們－長笛與中提琴、豎琴篇》\r\n長笛家陳惠湄邀請豎琴家陳淑杏以及多年好友與音樂搭檔中提琴家富澤直子，演出德布西寫給長笛、中提琴與豎琴的奏鳴曲這個夢幻曲目，同時將介紹幾首以德布西為典範而寫給相同編制的樂曲。法國女性作曲家蕾傑曾受教於若利維，師徒倆都受到德布西啟發而為此編制創作；日本作曲家武滿徹不但以此編制寫作，在樂曲中還直接引用了德布西的音樂片段，可說是向德布西致敬的作品。本音樂會選取為這個特別的室內樂組合所創作的動聽樂曲，期望能帶給聽眾一場浪漫豐富的聽覺饗宴。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n狄奧多爾．杜步瓦：《三重奏小品》給長笛、中提琴與豎琴\r\n\r\n安德烈．若利維：《小組曲》給長笛、中提琴與豎琴\r\n\r\n艾狄特．蕾傑：《回憶的影子》給長笛、中提琴與豎琴（臺灣首演）\r\n\r\n武滿徹 ：《於是，我知道那是風》（そして、それが風であることを知った）給長笛、中提琴與豎琴\r\n\r\n克勞德．德布西：長笛、中提琴與豎琴奏鳴曲\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n長笛｜陳惠湄\r\n\r\n中提琴｜富澤直子\r\n\r\n豎琴｜陳淑杏', `organizer`='就是愛樂管弦樂團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741326b32408680be936', '【樹洞耳機電影院】海上鋼琴師', '【樹洞耳機電影院】海上鋼琴師\r\n戴上專屬無線耳機、窩進舒適躺椅，曲面牆的400吋投影，耳內流竄的飽滿聲音，樹洞耳機電影院歡樂呈現！\r\n\r\n \r\n\r\n  活動日期與地點  \r\n\r\n活動日期：3/30(日)19:30 開始播映\r\n\r\n活動地點：榕樹廣場\r\n\r\n \r\n\r\n  報名對象與方式  \r\n\r\n參與對象：歡迎各年齡層共同參與\r\n\r\n報名時程：即日起至2025/3/26(三)23:59止\r\n\r\n報名費用：免費\r\n\r\n報名網址：點我報名\r\n\r\n參與方式：本活動採線上報名，限量100名，額滿為止；現場報到後於19:00開放自由入座。\r\n\r\n19:00-19:15 開放「已報名」者報到並領取耳機兌換憑證，若時間內無完成報到，將釋出該名額\r\n\r\n19:16 開放「現場報名」者領取耳機兌換憑證\r\n\r\n※耳機兌換憑證為入場資格非入座順序\r\n\r\n19:30 開始放映\r\n\r\n\r\n \r\n\r\n  播映節目  \r\n\r\n\r\n海上鋼琴師\r\n\r\n義大利文｜1998｜普遍級｜121 min\r\n\r\n導演｜朱賽佩．托納多雷 Giuseppe TORNATORE\r\n\r\n圖片\r\n圖片\r\n20世紀交替之初，一名棄嬰在渡洋郵輪上被尋獲並命名為「1900」。出身不詳、沒有國籍的他以海為家，陸地彷彿異鄉，絕緣於俗世之外，卻憑天賦成為鋼琴家，以超凡琴藝驚豔無數旅客。數十年來，他以局外人的視角，在船上看盡人間蒼涼繁華，卻寧可一生漂泊不願靠岸，直到某日邂逅一名千里尋父的美麗女子……。\r\n\r\n《新天堂樂園》導演的首部英語製作，由御用配樂大師顏尼歐．莫利克奈譜寫動人配樂。曾以昆汀．塔倫提諾的《霸道橫行》、《黑色追緝令》等黑幫惡煞形象走紅國際的英國演員提姆．羅斯，在本片褪去暴戾氣息，化身為純真而孤獨的憂鬱琴師。不諳鋼琴的他，開拍前苦練將近半年，精湛擬仿琴師指法及神態，一場與傳奇爵士樂手「海上鬥琴」的經典戲碼，表演層次從輕盈優雅走向賁張狂放，看得令人屏氣凝神，堪稱演技教科書。\r\n\r\n \r\n\r\n\r\n▲電影預告片\r\n\r\n \r\n\r\n照片:2018年樹洞電影院活動照\r\n\r\n▲活動現場示意', '國家表演藝術中心衛武營國家藝術文化中心', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '無資料', 'https://www.npac-weiwuying.org/programs/678a1101b207620008ba7624', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【樹洞耳機電影院】海上鋼琴師', `description`='【樹洞耳機電影院】海上鋼琴師\r\n戴上專屬無線耳機、窩進舒適躺椅，曲面牆的400吋投影，耳內流竄的飽滿聲音，樹洞耳機電影院歡樂呈現！\r\n\r\n \r\n\r\n  活動日期與地點  \r\n\r\n活動日期：3/30(日)19:30 開始播映\r\n\r\n活動地點：榕樹廣場\r\n\r\n \r\n\r\n  報名對象與方式  \r\n\r\n參與對象：歡迎各年齡層共同參與\r\n\r\n報名時程：即日起至2025/3/26(三)23:59止\r\n\r\n報名費用：免費\r\n\r\n報名網址：點我報名\r\n\r\n參與方式：本活動採線上報名，限量100名，額滿為止；現場報到後於19:00開放自由入座。\r\n\r\n19:00-19:15 開放「已報名」者報到並領取耳機兌換憑證，若時間內無完成報到，將釋出該名額\r\n\r\n19:16 開放「現場報名」者領取耳機兌換憑證\r\n\r\n※耳機兌換憑證為入場資格非入座順序\r\n\r\n19:30 開始放映\r\n\r\n\r\n \r\n\r\n  播映節目  \r\n\r\n\r\n海上鋼琴師\r\n\r\n義大利文｜1998｜普遍級｜121 min\r\n\r\n導演｜朱賽佩．托納多雷 Giuseppe TORNATORE\r\n\r\n圖片\r\n圖片\r\n20世紀交替之初，一名棄嬰在渡洋郵輪上被尋獲並命名為「1900」。出身不詳、沒有國籍的他以海為家，陸地彷彿異鄉，絕緣於俗世之外，卻憑天賦成為鋼琴家，以超凡琴藝驚豔無數旅客。數十年來，他以局外人的視角，在船上看盡人間蒼涼繁華，卻寧可一生漂泊不願靠岸，直到某日邂逅一名千里尋父的美麗女子……。\r\n\r\n《新天堂樂園》導演的首部英語製作，由御用配樂大師顏尼歐．莫利克奈譜寫動人配樂。曾以昆汀．塔倫提諾的《霸道橫行》、《黑色追緝令》等黑幫惡煞形象走紅國際的英國演員提姆．羅斯，在本片褪去暴戾氣息，化身為純真而孤獨的憂鬱琴師。不諳鋼琴的他，開拍前苦練將近半年，精湛擬仿琴師指法及神態，一場與傳奇爵士樂手「海上鬥琴」的經典戲碼，表演層次從輕盈優雅走向賁張狂放，看得令人屏氣凝神，堪稱演技教科書。\r\n\r\n \r\n\r\n\r\n▲電影預告片\r\n\r\n \r\n\r\n照片:2018年樹洞電影院活動照\r\n\r\n▲活動現場示意', `organizer`='國家表演藝術中心衛武營國家藝術文化中心', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='無資料', `source_url`='https://www.npac-weiwuying.org/programs/678a1101b207620008ba7624', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741326b32408680be937', '《黃凱珉 2025 小提琴獨奏會》', '《黃凱珉 2025 小提琴獨奏會》\r\n2025年黃凱珉將帶來克萊斯勒《柯賴里主題與變奏曲》、艾米·比奇《浪漫曲》、貝多芬《C小調第七號奏鳴曲為小提琴與鋼琴，作品30之2》、威廉·格蘭特·斯蒂爾《為小提琴與鋼琴的組曲》、普浪克《奏鳴曲為小提琴與鋼琴，作品119》及聖桑/易薩伊《圓舞曲式隨想曲，改編自聖桑第六號圓舞曲形式的練習曲，作品52》等作品，這些跨越不同樂派、不同風格的精彩曲目勢必為台灣樂迷帶來精采完美的音樂饗宴。 \r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n克萊斯勒：柯賴里主題與變奏曲\r\n\r\n艾米·比奇：浪漫曲\r\n\r\n貝多芬：C小調第七號奏鳴曲為小提琴與鋼琴，作品30之2\r\n\r\n威廉·格蘭特·斯蒂爾：為小提琴與鋼琴的組曲\r\n\r\n普浪克：奏鳴曲為小提琴與鋼琴，作品119\r\n\r\n聖桑／易薩伊：圓舞曲式隨想曲，改編自聖桑第六號圓舞曲形式的練習曲，作品52\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n小提琴家｜黃凱珉\r\n\r\n鋼琴家｜陳志毅', '鴻宇國際藝術有限公司', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-31 00:00:00', '2025-03-31 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500;--+800;--+1200;--+1600;--+2000;--+2500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《黃凱珉 2025 小提琴獨奏會》', `description`='《黃凱珉 2025 小提琴獨奏會》\r\n2025年黃凱珉將帶來克萊斯勒《柯賴里主題與變奏曲》、艾米·比奇《浪漫曲》、貝多芬《C小調第七號奏鳴曲為小提琴與鋼琴，作品30之2》、威廉·格蘭特·斯蒂爾《為小提琴與鋼琴的組曲》、普浪克《奏鳴曲為小提琴與鋼琴，作品119》及聖桑/易薩伊《圓舞曲式隨想曲，改編自聖桑第六號圓舞曲形式的練習曲，作品52》等作品，這些跨越不同樂派、不同風格的精彩曲目勢必為台灣樂迷帶來精采完美的音樂饗宴。 \r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n克萊斯勒：柯賴里主題與變奏曲\r\n\r\n艾米·比奇：浪漫曲\r\n\r\n貝多芬：C小調第七號奏鳴曲為小提琴與鋼琴，作品30之2\r\n\r\n威廉·格蘭特·斯蒂爾：為小提琴與鋼琴的組曲\r\n\r\n普浪克：奏鳴曲為小提琴與鋼琴，作品119\r\n\r\n聖桑／易薩伊：圓舞曲式隨想曲，改編自聖桑第六號圓舞曲形式的練習曲，作品52\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n小提琴家｜黃凱珉\r\n\r\n鋼琴家｜陳志毅', `organizer`='鴻宇國際藝術有限公司', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-31 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500;--+800;--+1200;--+1600;--+2000;--+2500', `source_url`='https://www.opentix.life/', `image_url`='[]';
