INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741326b32408680be939', '藝文展覽：躍然「紙」上  精「雕」細刻', '躍然「紙」上  精「雕」細刻\r\n本次我們將展出來自王訓鋒老師的精緻紙雕作品。\r\n每一件作品都蘊含著老師的深厚情感與巧妙構思，\r\n以紙作為媒介，生動地雕刻出日常生活中珍貴感動畫面。\r\n誠摯邀請您來到現場，一同細細品味王訓鋒老師所呈現的生活點滴，感受每一幅作品背後的細膩心思。\r\n展覽者:王訓鋒\r\n展覽時間:3/1~3/14\r\n展覽地點:大肚瑞井分館 1F\r\n', '臺中市立圖書館大肚瑞井分館', '臺中市大肚區華山路700號', '2025-03-01 00:00:00', '2025-03-14 00:00:00', '臺中市立圖書館大肚瑞井分館', 24.14467504, 120.5543243, '無資料', 'https://reurl.cc/Eg3r9m', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝文展覽：躍然「紙」上  精「雕」細刻', `description`='躍然「紙」上  精「雕」細刻\r\n本次我們將展出來自王訓鋒老師的精緻紙雕作品。\r\n每一件作品都蘊含著老師的深厚情感與巧妙構思，\r\n以紙作為媒介，生動地雕刻出日常生活中珍貴感動畫面。\r\n誠摯邀請您來到現場，一同細細品味王訓鋒老師所呈現的生活點滴，感受每一幅作品背後的細膩心思。\r\n展覽者:王訓鋒\r\n展覽時間:3/1~3/14\r\n展覽地點:大肚瑞井分館 1F\r\n', `organizer`='臺中市立圖書館大肚瑞井分館', `address`='臺中市大肚區華山路700號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-14 00:00:00', `location`='臺中市立圖書館大肚瑞井分館', `latitude`=24.14467504, `longitude`=120.5543243, `ticket_price`='無資料', `source_url`='https://reurl.cc/Eg3r9m', `image_url`='[]';
