INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741426b32408680be940', '新營區圖書館:3月故事列車', '3月1日 張麗梅 阿松爺爺的柚子樹\r\n3月8日 王貴金 我很特別妳很特別\r\n3月15日 楊千慧 超神奇種子鋪\r\n3月22日 劉秀香 巫婆阿尼參加運動會\r\n3月29日 王櫻臻 我們來洗手', '臺南市新營區圖書館', '臺南市新營區45之8號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '臺南市新營區圖書館', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新營區圖書館:3月故事列車', `description`='3月1日 張麗梅 阿松爺爺的柚子樹\r\n3月8日 王貴金 我很特別妳很特別\r\n3月15日 楊千慧 超神奇種子鋪\r\n3月22日 劉秀香 巫婆阿尼參加運動會\r\n3月29日 王櫻臻 我們來洗手', `organizer`='臺南市新營區圖書館', `address`='臺南市新營區45之8號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺南市新營區圖書館', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741426b32408680be941', '【2025鳳凰城台灣系列講座】- 台灣王船信仰', '王爺是臺灣重要的民間信仰，根據內政部統計，臺灣主祀王爺的宮廟數量僅次於土地公。王爺信仰起源歷來有許多版本，其中最普遍的說法是「瘟神」信仰。王爺數量眾多、造型不同，且大多只有姓氏而不知其名。\r\n臺灣位於亞熱帶，氣候高溫溼熱，自然環境蚊蚋孳生，加上往昔衛生不良、醫藥不發達，致使傳染病瘟疫頻傳，每當瘟疫流傳經常在短期間集體感染，造成眾多死亡。瘟疫流傳的原因，民眾認為乃因百姓行為不正違背天理，故天降疫疾集體、連坐懲罰人民，所謂：「人若沒照天理，天就沒照甲子」。意謂人民不照天理行事，老天就不按自然規則形成災害。面對瘟疫流傳造成許多百姓死亡，民眾束手無策求助無門，只能尋求宗教的救贖，祈求代天巡狩的王爺帶走瘟疫驅除災難。是故，王爺信仰反映臺灣移民社會的自然環境與人文思想的社會背景。', '臺南市鳳凰城文史協會', '臺南市北區公園北路3號', '2025-03-06 00:00:00', '2025-03-06 00:00:00', '臺南市立圖書館(北區)', 23.01012179, 120.2068735, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025鳳凰城台灣系列講座】- 台灣王船信仰', `description`='王爺是臺灣重要的民間信仰，根據內政部統計，臺灣主祀王爺的宮廟數量僅次於土地公。王爺信仰起源歷來有許多版本，其中最普遍的說法是「瘟神」信仰。王爺數量眾多、造型不同，且大多只有姓氏而不知其名。\r\n臺灣位於亞熱帶，氣候高溫溼熱，自然環境蚊蚋孳生，加上往昔衛生不良、醫藥不發達，致使傳染病瘟疫頻傳，每當瘟疫流傳經常在短期間集體感染，造成眾多死亡。瘟疫流傳的原因，民眾認為乃因百姓行為不正違背天理，故天降疫疾集體、連坐懲罰人民，所謂：「人若沒照天理，天就沒照甲子」。意謂人民不照天理行事，老天就不按自然規則形成災害。面對瘟疫流傳造成許多百姓死亡，民眾束手無策求助無門，只能尋求宗教的救贖，祈求代天巡狩的王爺帶走瘟疫驅除災難。是故，王爺信仰反映臺灣移民社會的自然環境與人文思想的社會背景。', `organizer`='臺南市鳳凰城文史協會', `address`='臺南市北區公園北路3號', `start_date`='2025-03-06 00:00:00', `end_date`='2025-03-06 00:00:00', `location`='臺南市立圖書館(北區)', `latitude`=23.01012179, `longitude`=120.2068735, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741426b32408680be942', '時光藝遊 - 張文鶯 ‧ 張思群 ‧ 陳玉梅三人聯展', '張文鶯、張思群、陳玉梅三人因緣際會透過畫畫的學習，在觀音鄉土畫家李建星老師的指導下開啟彩繪的人生，由基礎素描開始接續水彩靜物的學習，慢慢地畫出屬於自己的色彩及風格。\r\n年輕時期總是為了工作、家庭、育兒而忙碌，退休之後能夠拾\r\n起以往畫畫的夢想，拿起畫筆彩繪下半段的快樂生活，能在輕\r\n鬆自在學習中成長，慢慢看到自己完成的作品，享受到另一種\r\n成就的快樂，也在學習中結識許多興趣相投的好朋友，互相鼓\r\n勵分享一起成長，為自己的樂齡生活找到重心也增添許多色\r\n彩。', '桃園市立圖書館', '桃園市新屋區中興路91巷11號', '2025-03-02 00:00:00', '2025-03-30 00:00:00', '桃園市立圖書館新屋分館', 24.97280352, 121.067758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='時光藝遊 - 張文鶯 ‧ 張思群 ‧ 陳玉梅三人聯展', `description`='張文鶯、張思群、陳玉梅三人因緣際會透過畫畫的學習，在觀音鄉土畫家李建星老師的指導下開啟彩繪的人生，由基礎素描開始接續水彩靜物的學習，慢慢地畫出屬於自己的色彩及風格。\r\n年輕時期總是為了工作、家庭、育兒而忙碌，退休之後能夠拾\r\n起以往畫畫的夢想，拿起畫筆彩繪下半段的快樂生活，能在輕\r\n鬆自在學習中成長，慢慢看到自己完成的作品，享受到另一種\r\n成就的快樂，也在學習中結識許多興趣相投的好朋友，互相鼓\r\n勵分享一起成長，為自己的樂齡生活找到重心也增添許多色\r\n彩。', `organizer`='桃園市立圖書館', `address`='桃園市新屋區中興路91巷11號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='桃園市立圖書館新屋分館', `latitude`=24.97280352, `longitude`=121.067758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741426b32408680be943', '新營區圖書館:3月女性影展', '經由電影欣賞來學習電影值得探討或反思的內容。每月撥放1至4部電影供讀者欣賞。\r\n3月05日 14:00-16:00 情書\r\n3月12日 14:00-16:00 女影人生\r\n3月19日 14:00-16:00 關於她的二三事\r\n3月26日 14:00-16:00 安妮要自由', '臺南市新營區圖書館', '臺南市新營區45之8號', '2025-03-05 00:00:00', '2025-03-26 00:00:00', '臺南市新營區圖書館', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新營區圖書館:3月女性影展', `description`='經由電影欣賞來學習電影值得探討或反思的內容。每月撥放1至4部電影供讀者欣賞。\r\n3月05日 14:00-16:00 情書\r\n3月12日 14:00-16:00 女影人生\r\n3月19日 14:00-16:00 關於她的二三事\r\n3月26日 14:00-16:00 安妮要自由', `organizer`='臺南市新營區圖書館', `address`='臺南市新營區45之8號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺南市新營區圖書館', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741426b32408680be944', '3月高雄市電影館｜夜校女生【普遍級】', '「日校是太陽，夜校是月亮。」\r\n\r\n\r\n\r\n1997年，小愛（陳姸霏 飾）在升學壓力下進入體制特殊的「一女中夜校」就讀。但夜校生總被認為不如日校生優秀，造成她極度自卑。她與日校好友敏敏（項婕如 飾）一起喜歡上男校的資優生路克（邱以太 飾），持續假冒成日校生，並把自己推向巨大的謊言坑洞，直到謊言被揭穿。\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n票價資訊\r\n票價：原價260元\r\n．影友優惠票200元：持有效期限內「高雄市電影館CLASSIC／GOLD+影友卡」購買者(進場請出示卡片)\r\n．兒童票208元：未滿12歲兒童（憑相關證件）享全票八折優惠\r\n．愛心票130元：65歲以上人士（憑相關證件）、身心障礙人士（憑相關證件）與陪同者限一名享愛心票優惠\r\n\r\n\r\n\r\n注意事項\r\n◆內惟藝術中心 Reel two 2廳Ａ排、Ｂ排為單人沙發座\r\n◆現場購票可至官方網站查詢場館營業時間；年代售票網站(郵寄.便利商店取票)、全台年代售票端點、四大超商機台皆可購票\r\n\r\n◆CLASSIC／GOLD+會員之影友優惠票規範詳情請參閱官方網站公告\r\n\r\n◆場次開演後10分停止售票／20分後不得入場；持優惠票入場時須出示證件，如未出示須補足差額方可入場\r\n\r\n◆退票需於開演前30分臨櫃依規定辦理；換票視同退票，如需更換場次，請依退票方式辦理並酌收退票手續費10%\r\n\r\n◆取票手續費、轉帳手續費及郵資票券等額外手續費非屬票價部分不在退款範圍之內，需由購票人自行負擔\r\n\r\n◆本節目退換票請洽主辦單位-高雄市電影館07-5511211# 2015\r\n\r\n◆如不可抗因素致演出取消，購票者同意依據主辦方制定退票規則辦理', '高雄市電影館', '高雄市鹽埕區4鄰河西路10號', '2025-03-01 00:00:00', '2025-03-26 00:00:00', '高雄市電影館', 22.622671, 120.289122, '愛心票+130;影友優惠票+200;兒童票+208;原價+260', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月高雄市電影館｜夜校女生【普遍級】', `description`='「日校是太陽，夜校是月亮。」\r\n\r\n\r\n\r\n1997年，小愛（陳姸霏 飾）在升學壓力下進入體制特殊的「一女中夜校」就讀。但夜校生總被認為不如日校生優秀，造成她極度自卑。她與日校好友敏敏（項婕如 飾）一起喜歡上男校的資優生路克（邱以太 飾），持續假冒成日校生，並把自己推向巨大的謊言坑洞，直到謊言被揭穿。\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n票價資訊\r\n票價：原價260元\r\n．影友優惠票200元：持有效期限內「高雄市電影館CLASSIC／GOLD+影友卡」購買者(進場請出示卡片)\r\n．兒童票208元：未滿12歲兒童（憑相關證件）享全票八折優惠\r\n．愛心票130元：65歲以上人士（憑相關證件）、身心障礙人士（憑相關證件）與陪同者限一名享愛心票優惠\r\n\r\n\r\n\r\n注意事項\r\n◆內惟藝術中心 Reel two 2廳Ａ排、Ｂ排為單人沙發座\r\n◆現場購票可至官方網站查詢場館營業時間；年代售票網站(郵寄.便利商店取票)、全台年代售票端點、四大超商機台皆可購票\r\n\r\n◆CLASSIC／GOLD+會員之影友優惠票規範詳情請參閱官方網站公告\r\n\r\n◆場次開演後10分停止售票／20分後不得入場；持優惠票入場時須出示證件，如未出示須補足差額方可入場\r\n\r\n◆退票需於開演前30分臨櫃依規定辦理；換票視同退票，如需更換場次，請依退票方式辦理並酌收退票手續費10%\r\n\r\n◆取票手續費、轉帳手續費及郵資票券等額外手續費非屬票價部分不在退款範圍之內，需由購票人自行負擔\r\n\r\n◆本節目退換票請洽主辦單位-高雄市電影館07-