INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741526b32408680be956', '臺南市立圖書館:3月中文說故事', '蛀牙蟲家族大搬家、大野狼和神奇的扁豆湯、春天的野餐會、愛吃青菜的鱷魚、蟲出沒，熊小心、怕浪費的奶奶、叢林派對、三隻小豬拿冠軍、我吃拉麵的時候、媽媽的一碗湯、一起釣星星、花地藏、翠翠掉下去了、三隻山羊嘎啦嘎啦、劍獅祈福、蠟筆小黑和小小白、小蛇肚子咕嚕嚕、、世界上最棒的蛇', '臺南市立圖書館', '臺南市永康區710038 臺南市永康區東橋里康橋大道255號', '2025-03-02 00:00:00', '2025-03-23 00:00:00', '臺南市立圖書館(新總館)', 23.02729532, 120.2542795, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市立圖書館:3月中文說故事', `description`='蛀牙蟲家族大搬家、大野狼和神奇的扁豆湯、春天的野餐會、愛吃青菜的鱷魚、蟲出沒，熊小心、怕浪費的奶奶、叢林派對、三隻小豬拿冠軍、我吃拉麵的時候、媽媽的一碗湯、一起釣星星、花地藏、翠翠掉下去了、三隻山羊嘎啦嘎啦、劍獅祈福、蠟筆小黑和小小白、小蛇肚子咕嚕嚕、、世界上最棒的蛇', `organizer`='臺南市立圖書館', `address`='臺南市永康區710038 臺南市永康區東橋里康橋大道255號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='臺南市立圖書館(新總館)', `latitude`=23.02729532, `longitude`=120.2542795, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
