INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741726b32408680be95d', '龍潭電影院3月 (20場)', '週三FUN電影:\r\n03/05(三) 聽見歌再唱\r\n改編自真實故事。電影講述偏鄉原住民孩童透過歌唱改變命運，參與合唱團，並在音樂中找到希望與自信。影片展現動人歌聲與文化傳承，感人至深。\r\n03/12(三) 法律女王\r\n全片透過不同背景，不同家庭再日常不過的生活，讓他們面臨突如其來的災難龍捲風情節搬上舞台，也警示人們切勿漠視氣候異常所造成的災害。\r\n03/19(三) 做工的人\r\n講述阿祈與阿欽等工地工人面對生活困境與夢想的故事。電影融合幽默與寫實風格，刻畫底層勞工的艱辛與堅持，感人又發人深省。\r\n03/26(三) 天崩颶裂\r\n講述一場突如其來的超級颶風席捲城市，引發毀滅性災難。主角們在極端天候中奮力求生，對抗狂風暴雨與隨之而來的危機。震撼特效搭配緊湊劇情，帶來極限災難體驗。\r\n\r\n週日電影院:\r\n03/02(日) 海豚男孩\r\n03/23(日) 飢餓大冒險\r\n\r\n魯冰花電影特映場:\r\n03/01、03/02、03/03、03/04、03/05、03/06、03/07\r\n', '桃園市立圖書館', '桃園市龍潭區中興路680號', '2025-03-02 00:00:00', '2025-03-26 00:00:00', '桃園市立圖書館龍潭分館', 24.85064954, 121.2117877, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='龍潭電影院3月 (20場)', `description`='週三FUN電影:\r\n03/05(三) 聽見歌再唱\r\n改編自真實故事。電影講述偏鄉原住民孩童透過歌唱改變命運，參與合唱團，並在音樂中找到希望與自信。影片展現動人歌聲與文化傳承，感人至深。\r\n03/12(三) 法律女王\r\n全片透過不同背景，不同家庭再日常不過的生活，讓他們面臨突如其來的災難龍捲風情節搬上舞台，也警示人們切勿漠視氣候異常所造成的災害。\r\n03/19(三) 做工的人\r\n講述阿祈與阿欽等工地工人面對生活困境與夢想的故事。電影融合幽默與寫實風格，刻畫底層勞工的艱辛與堅持，感人又發人深省。\r\n03/26(三) 天崩颶裂\r\n講述一場突如其來的超級颶風席捲城市，引發毀滅性災難。主角們在極端天候中奮力求生，對抗狂風暴雨與隨之而來的危機。震撼特效搭配緊湊劇情，帶來極限災難體驗。\r\n\r\n週日電影院:\r\n03/02(日) 海豚男孩\r\n03/23(日) 飢餓大冒險\r\n\r\n魯冰花電影特映場:\r\n03/01、03/02、03/03、03/04、03/05、03/06、03/07\r\n', `organizer`='桃園市立圖書館', `address`='桃園市龍潭區中興路680號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='桃園市立圖書館龍潭分館', `latitude`=24.85064954, `longitude`=121.2117877, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741726b32408680be95e', 'Hello! 蕭宇珊插畫個展 & 繪本原畫展', '本次展覽展出繪本作家蕭宇珊（雨傘）的原畫作品，包括《南瓜車車》與《Together》兩本繪本，以及她旅法期間的寫生插畫。您將可一窺繪本從草稿到完成的歷程，感受創作者如何一步步將想像具象化，甚至發現自己閱讀時未曾注意的細節。\r\n\r\n展覽期間還將舉辦分享會與工作坊，讓插畫家親自揭開創作時的小秘密，歡迎一同來感受繪本的魅力！\r\n\r\n展覽分為兩個階段：\r\n2/21 - 3/23｜Hello! 《南瓜車車》繪本原畫展\r\n3/26 - 4/20｜Hello! 《Together》繪本原畫展\r\n\r\n｜創作者介紹｜\r\n蕭宇珊，雨傘 Yushan Hsiao，曾出版繪本《南瓜車車》及《花小獅的煩惱》。過去曾獲桃園環教繪本比賽首獎、桃園插畫大展競賽金獎。\r\n\r\nIG: @yushan.illustration\r\nFB: 雨傘 Yushan Hsiao', '蕭宇珊', '桃園市蘆竹區', '2025-02-21 00:00:00', '2025-04-20 00:00:00', '蘆竹區（桃園市）=', 25.06073337, 121.2831266, '無資料', 'https://www.accupass.com/event/2502281532264525119590?utm_source=web&utm_medium=search_result_%E6%8F', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Hello! 蕭宇珊插畫個展 & 繪本原畫展', `description`='本次展覽展出繪本作家蕭宇珊（雨傘）的原畫作品，包括《南瓜車車》與《Together》兩本繪本，以及她旅法期間的寫生插畫。您將可一窺繪本從草稿到完成的歷程，感受創作者如何一步步將想像具象化，甚至發現自己閱讀時未曾注意的細節。\r\n\r\n展覽期間還將舉辦分享會與工作坊，讓插畫家親自揭開創作時的小秘密，歡迎一同來感受繪本的魅力！\r\n\r\n展覽分為兩個階段：\r\n2/21 - 3/23｜Hello! 《南瓜車車》繪本原畫展\r\n3/26 - 4/20｜Hello! 《Together》繪本原畫展\r\n\r\n｜創作者介紹｜\r\n蕭宇珊，雨傘 Yushan Hsiao，曾出版繪本《南瓜車車》及《花小獅的煩惱》。過去曾獲桃園環教繪本比賽首獎、桃園插畫大展競賽金獎。\r\n\r\nIG: @yushan.illustration\r\nFB: 雨傘 Yushan Hsiao', `organizer`='蕭宇珊', `address`='桃園市蘆竹區', `start_date`='2025-02-21 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='蘆竹區（桃園市）=', `latitude`=25.06073337, `longitude`=121.2831266, `ticket_price`='無資料', `source_url`='https://www.accupass.com/event/2502281532264525119590?utm_source=web&utm_medium=search_result_%E6%8F', `image_url`='[]';
