INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741726b32408680be964', '2025春來客韻滿洄瀾音樂會—花蓮與新竹縣原客混聲合唱團聯合演出', '花蓮高中校友會，為延續花中之藝文傳承，邀請比賽常勝軍「新竹縣原客混聲合唱團」來花蓮與在地歷史最悠久的”花蓮合唱團”同台聯演以客家歌曲為主的合唱音樂會，讓花蓮鄉親經由欣賞合唱之美，提升人文素養 。\r\n上半場「新竹縣原客混聲合唱團」製作演出【行過】音樂劇，以11首客家歌曲勾串成一段溫馨的故事。下半場由「花蓮合唱團」選唱多元而豐富的歌曲，除了傳統由鋼琴伴奏之外，部分歌曲加入爵士鼓、非洲鼓協助演出，”舞動人聲”三首歌曲特別安排專業舞團設計”歌與舞”在舞台呈現給觀眾不一樣的視聽感受。\r\n    \r\n\r\n \r\n', '花蓮縣文化局', '花蓮縣花蓮市文復路六號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '全票+100', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025春來客韻滿洄瀾音樂會—花蓮與新竹縣原客混聲合唱團聯合演出', `description`='花蓮高中校友會，為延續花中之藝文傳承，邀請比賽常勝軍「新竹縣原客混聲合唱團」來花蓮與在地歷史最悠久的”花蓮合唱團”同台聯演以客家歌曲為主的合唱音樂會，讓花蓮鄉親經由欣賞合唱之美，提升人文素養 。\r\n上半場「新竹縣原客混聲合唱團」製作演出【行過】音樂劇，以11首客家歌曲勾串成一段溫馨的故事。下半場由「花蓮合唱團」選唱多元而豐富的歌曲，除了傳統由鋼琴伴奏之外，部分歌曲加入爵士鼓、非洲鼓協助演出，”舞動人聲”三首歌曲特別安排專業舞團設計”歌與舞”在舞台呈現給觀眾不一樣的視聽感受。\r\n    \r\n\r\n \r\n', `organizer`='花蓮縣文化局', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='全票+100', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741726b32408680be965', '白河區圖書館:「蓮鄉荷香」 彩墨畫展', '本季圖書館邀請張慧盈老師辦理「蓮鄉荷香」彩墨畫展\r\n展覽日於2025年3月4日至6月30日止。\r\n張慧盈老師是在地白河女兒，源於北部工作後因需照顧年邁父母及身體亮起紅燈，決定回歸家鄉。在抵抗病魔時，老師直言治療過程心力交瘁一度頭髮掉光，轉念在友人的建議下提筆創作，而老師曾是白河洪靈老師的學徒，本身就有繪畫底子，決定透過畫來淡忘疾病帶來的痛，開始以家鄉之美「荷花」為主題，展開一系列的彩墨創作。\r\n\r\n歡迎熱愛繪畫或對於荷花畫作有興趣的朋友們，誠摯邀請您走進圖書館，欣賞一系列的美麗畫作。', '臺南市白河區圖書館', '臺南市白河區新興路573號', '2025-03-04 00:00:00', '2025-06-30 00:00:00', '張慶芳紀念圖書館(白河區圖書館)', 23.35132068, 120.4578565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='白河區圖書館:「蓮鄉荷香」 彩墨畫展', `description`='本季圖書館邀請張慧盈老師辦理「蓮鄉荷香」彩墨畫展\r\n展覽日於2025年3月4日至6月30日止。\r\n張慧盈老師是在地白河女兒，源於北部工作後因需照顧年邁父母及身體亮起紅燈，決定回歸家鄉。在抵抗病魔時，老師直言治療過程心力交瘁一度頭髮掉光，轉念在友人的建議下提筆創作，而老師曾是白河洪靈老師的學徒，本身就有繪畫底子，決定透過畫來淡忘疾病帶來的痛，開始以家鄉之美「荷花」為主題，展開一系列的彩墨創作。\r\n\r\n歡迎熱愛繪畫或對於荷花畫作有興趣的朋友們，誠摯邀請您走進圖書館，欣賞一系列的美麗畫作。', `organizer`='臺南市白河區圖書館', `address`='臺南市白河區新興路573號', `start_date`='2025-03-04 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='張慶芳紀念圖書館(白河區圖書館)', `latitude`=23.35132068, `longitude`=120.4578565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
