INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741826b32408680be96e', '114年音樂故事小劇場：鋼琴巫師故事音樂會', '鋼琴巫師 故事音樂會  The Piano Wizard \r\n《鋼琴巫師》是布拉茲·普奇哈爾 (Blaž Pucihar) 在舞台上栩栩如生的鋼琴音樂童話，收錄了十三位年輕鋼琴家與一隻狗的故事，融入了一個關於巫師音樂天賦、他對不同風格樂曲的尊重、即興創作的重要性以及他一生的摯愛的故事。    \r\n說書人：Flora 許慧玲   \r\n鋼琴：謝承晏\r\n\r\n報名資格及方式：\r\n大班以上即可免費報名/各場次限額30位\r\n即日起電洽圖書館一樓049-2984144轉9', '南投縣埔里鎮公所', '南投縣埔里鎮六合路178號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '南投縣埔里鎮立圖書館', 23.9702357, 120.9713659, '無資料', 'https://www.facebook.com/pulilibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年音樂故事小劇場：鋼琴巫師故事音樂會', `description`='鋼琴巫師 故事音樂會  The Piano Wizard \r\n《鋼琴巫師》是布拉茲·普奇哈爾 (Blaž Pucihar) 在舞台上栩栩如生的鋼琴音樂童話，收錄了十三位年輕鋼琴家與一隻狗的故事，融入了一個關於巫師音樂天賦、他對不同風格樂曲的尊重、即興創作的重要性以及他一生的摯愛的故事。    \r\n說書人：Flora 許慧玲   \r\n鋼琴：謝承晏\r\n\r\n報名資格及方式：\r\n大班以上即可免費報名/各場次限額30位\r\n即日起電洽圖書館一樓049-2984144轉9', `organizer`='南投縣埔里鎮公所', `address`='南投縣埔里鎮六合路178號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='南投縣埔里鎮立圖書館', `latitude`=23.9702357, `longitude`=120.9713659, `ticket_price`='無資料', `source_url`='https://www.facebook.com/pulilibrary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741826b32408680be96f', '114年音樂故事小劇場：露娜的魔笛故事音樂會', '露娜的魔笛 故事音樂會 Luna’s Magic Flute \r\n埔里～吹笛手的城鎮，住著許多喜愛吹笛的大小朋友，這次吹笛手帶著來自斯洛維尼亞剛的童話故事-露娜的魔笛，透過說書人 Vivi老師，以及長笛與鋼琴的合奏，搭配繪畫大師 Igor Sinkovec 雨果．欣可維克的繪圖，透過露娜的好朋友，小馬、烏龜、老虎、海豚等～\r\n帶著孩子們走一趟充滿挑戰的音樂旅程！ \r\n說書人：Vivi 廖瑋娸。    \r\n鋼琴：謝承晏     \r\n長笛：謝志偉\r\n\r\n報名資格及方式\r\n大班以上即可免費報名/各場次限額30位\r\n即日起電洽圖書館一樓049-2984144轉9', '南投縣埔里鎮公所', '南投縣埔里鎮六合路178號', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '南投縣埔里鎮立圖書館', 23.9702357, 120.9713659, '無資料', 'https://www.facebook.com/pulilibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年音樂故事小劇場：露娜的魔笛故事音樂會', `description`='露娜的魔笛 故事音樂會 Luna’s Magic Flute \r\n埔里～吹笛手的城鎮，住著許多喜愛吹笛的大小朋友，這次吹笛手帶著來自斯洛維尼亞剛的童話故事-露娜的魔笛，透過說書人 Vivi老師，以及長笛與鋼琴的合奏，搭配繪畫大師 Igor Sinkovec 雨果．欣可維克的繪圖，透過露娜的好朋友，小馬、烏龜、老虎、海豚等～\r\n帶著孩子們走一趟充滿挑戰的音樂旅程！ \r\n說書人：Vivi 廖瑋娸。    \r\n鋼琴：謝承晏     \r\n長笛：謝志偉\r\n\r\n報名資格及方式\r\n大班以上即可免費報名/各場次限額30位\r\n即日起電洽圖書館一樓049-2984144轉9', `organizer`='南投縣埔里鎮公所', `address`='南投縣埔里鎮六合路178號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='南投縣埔里鎮立圖書館', `latitude`=23.9702357, `longitude`=120.9713659, `ticket_price`='無資料', `source_url`='https://www.facebook.com/pulilibrary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741826b32408680be970', '世界閱讀日-向一代經典繪本作家致敬：14隻老鼠的小小世界', '世界閱讀日~14隻老鼠的生活四季，邀您一起溫暖出發！\r\n日本繪本大師岩村和朗細膩筆觸下描繪經典《14隻老鼠》系列帶領讀者走進森林，感受四季變化。\r\n跟著老鼠家族一起探索自然的奇妙，三代同堂的溫馨故事，陪伴成長時光。細膩插圖＋簡潔文字，啟發讀者們的觀察力與想像力。展出中～讓這套經典閱讀帶您發現生活觀察、合作與愛的力量。', '南投縣中寮鄉公所', '南投縣中寮鄉永平路270號四樓', '2025-03-04 00:00:00', '2025-04-30 00:00:00', '南投縣中寮鄉立圖書館', 23.8790949, 120.7659918, '無資料', 'https://www.facebook.com/profile.php?id=100081167516780#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='世界閱讀日-向一代經典繪本作家致敬：14隻老鼠的小小世界', `description`='世界閱讀日~14隻老鼠的生活四季，邀您一起溫暖出發！\r\n日本繪本大師岩村和朗細膩筆觸下描繪經典《14隻老鼠》系列帶領讀者走進森林，感受四季變化。\r\n跟著老鼠家族一起探索自然的奇妙，三代同堂的溫馨故事，陪伴成長時光。細膩插圖＋簡潔文字，啟發讀者們的觀察力與想像力。展出中～讓這套經典閱讀帶您發現生活觀察、合作與愛的力量。', `organizer`='南投縣中寮鄉公所', `address`='南投縣中寮鄉永平路270號四樓', `start_date`='2025-03-04 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='南投縣中寮鄉立圖書館', `latitude`=23.8790949, `longitude`=120.7659918, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100081167516780#', `image_url`='[]';
