INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741826b32408680be973', '114年度「張牙舞爪特展培訓」研習', '講座內容：\r\n上午／認識原住民文化主題課程\r\n下午／「張牙舞爪特展」介紹及導覽解說活動\r\n\r\n參加對象：志工、對研習主題有興趣者，共25名。\r\n114年3月10日（一）前網路報名，請至活動網站線上報名。聯絡電話：049-2802619轉103陳小姐或轉106分機張主任。', '南投縣自然史教育館', '南投縣仁愛鄉山農巷27號', '2025-03-19 00:00:00', '2025-03-19 00:00:00', '國立仁愛高級農業職業學校', 24.0212391, 121.1345879, '無資料', 'https://www.facebook.com/nhamfans', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度「張牙舞爪特展培訓」研習', `description`='講座內容：\r\n上午／認識原住民文化主題課程\r\n下午／「張牙舞爪特展」介紹及導覽解說活動\r\n\r\n參加對象：志工、對研習主題有興趣者，共25名。\r\n114年3月10日（一）前網路報名，請至活動網站線上報名。聯絡電話：049-2802619轉103陳小姐或轉106分機張主任。', `organizer`='南投縣自然史教育館', `address`='南投縣仁愛鄉山農巷27號', `start_date`='2025-03-19 00:00:00', `end_date`='2025-03-19 00:00:00', `location`='國立仁愛高級農業職業學校', `latitude`=24.0212391, `longitude`=121.1345879, `ticket_price`='無資料', `source_url`='https://www.facebook.com/nhamfans', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741826b32408680be974', '草屯走讀', '草屯，舊名草鞋墩，位於南投縣內，曾為交通中繼站，百工百業蓬勃發展；隨著交通開發，過往人潮不再經過……\r\n和興街曾是草屯市區最熱鬧的一條街，繁華時有戲院、綜合市場、果菜市場、蛇肉店、碾米廠、國術館、漫畫出租店、雜貨店等，可以說網羅了草屯吃、喝、玩、樂，生活必需品也都囊括在內，只要來到草屯和興街一趟，應有盡有無須再去別處。\r\n生長在草屯的南投故事館梁志忠老師，見證草屯從古至今的變化，從古蹟歷史建築，到蓬勃發展的商業街道，如今的街區亦是延續著上一代人的生活樣貌，梁老師將帶領你一路探訪，深度認識在地店家故事，窺探草鞋墩的生活樣貌，一起跟著走進梁老師的兒時記憶吧！\r\n\r\n活動免費，活動限額30位。\r\n報名網址 https://forms.gle/aiYZisvh75JqVa1d6', '錦春堂文化基金會', '南投縣草屯鎮', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '草屯鎮（南投縣）=', 23.98321081, 120.7326182, '無資料', 'https://www.facebook.com/groups/915191218565731', '[]') ON DUPLICATE KEY UPDATE `activity_name`='草屯走讀', `description`='草屯，舊名草鞋墩，位於南投縣內，曾為交通中繼站，百工百業蓬勃發展；隨著交通開發，過往人潮不再經過……\r\n和興街曾是草屯市區最熱鬧的一條街，繁華時有戲院、綜合市場、果菜市場、蛇肉店、碾米廠、國術館、漫畫出租店、雜貨店等，可以說網羅了草屯吃、喝、玩、樂，生活必需品也都囊括在內，只要來到草屯和興街一趟，應有盡有無須再去別處。\r\n生長在草屯的南投故事館梁志忠老師，見證草屯從古至今的變化，從古蹟歷史建築，到蓬勃發展的商業街道，如今的街區亦是延續著上一代人的生活樣貌，梁老師將帶領你一路探訪，深度認識在地店家故事，窺探草鞋墩的生活樣貌，一起跟著走進梁老師的兒時記憶吧！\r\n\r\n活動免費，活動限額30位。\r\n報名網址 https://forms.gle/aiYZisvh75JqVa1d6', `organizer`='錦春堂文化基金會', `address`='南投縣草屯鎮', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='草屯鎮（南投縣）=', `latitude`=23.98321081, `longitude`=120.7326182, `ticket_price`='無資料', `source_url`='https://www.facebook.com/groups/915191218565731', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c7741826b32408680be976', '台灣獅（鼓）藝民俗技藝研習', '同義堂舞獅團始祖羅乾章目前已傳承至第五代子弟，活躍於竹山鎮德興里（車店仔）。並承缽傳授獅藝、鼓藝、兵器、拳術、獅頭製作及彩繪⋯等技藝。為了讓台灣獅文化傳承並發揚光大，竹山同義堂獅技（鼓）藝研習開堂。\r\n學習民俗技藝，不僅讓孩童與里內長者走出戶外，提供情感支持和歸屬感，還能提升專注力、增強柔韌性。\r\n歡迎有興趣～想強身健體的大朋友與小朋友來體驗，趕緊相揪厝邊隔壁來參加吧。\r\n竹山同義堂台灣獅技藝研習\r\n活動地點：竹山鎮德興里接天宮廣場\r\n開課日期：3月2日至5月18日\r\n上課時間：每週日上午09:30-12:30團練時間為3小時，以戶外訓練為主\r\n報名電話：049-2642175轉616或701（名額有限，滿額停招）', '南投縣竹山鎮公所', '南投縣竹山鎮', '2025-03-02 00:00:00', '2025-05-18 00:00:00', '竹山鎮（南投縣）=', 23.69805518, 120.7100797, '無資料', 'https://www.facebook.com/CHENTUNGMU', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台灣獅（鼓）藝民俗技藝研習', `description`='同義堂舞獅團始祖羅乾章目前已傳承至第五代子弟，活躍於竹山鎮德興里（車店仔）。並承缽傳授獅藝、鼓藝、兵器、拳術、獅頭製作及彩繪⋯等技藝。為了讓台灣獅文化傳承並發揚光大，竹山同義堂獅技（鼓）藝研習開堂。\r\n學習民俗技藝，不僅讓孩童與里內長者走出戶外，提供情感支持和歸屬感，還能提升專注力、增強柔韌性。\r\n歡迎有興趣～想強身健體的大朋友與小朋友來體驗，趕緊相揪厝邊隔壁來參加吧。\r\n竹山同義堂台灣獅技藝研習\r\n活動地點：竹山鎮德興里接天宮廣場\r\n開課日期：3月2日至5月18日\r\n上課時間：每週日上午09:30-12:30團練時間為3小時，以戶外訓練為主\r\n報名電話：049-2642175轉616或701（名額有限，滿額停招）', `organizer`='南投縣竹山鎮公所', `address`='南投縣竹山鎮', `start_date`='2025-03-02 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='竹山鎮（南投縣）=', `latitude`=23.69805518, `longitude`=120.7100797, `ticket_price`='無資料', `source_url`='https://www.facebook.com/CHENTUNGMU', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5683a26b32418d001b95d', '【新北市立圖書館金山分館】李賜民「燭夢舞臺，嶼您有約」創作個展', '【新北市立圖書館金山分館】李賜民「燭夢舞臺，嶼您有約」創作個展\r\n展覽時間：1/2~12/31開館時間\r\n展覽地點：新北市立圖書館金山分館／樓梯廊道\r\n聯絡電話：02-2498-4714#201\r\n簡介：\r\n「整個北海岸，都是我的畫室！」退休後返回金山老家的銀髮素人速寫藝術家家李賜民，六年來走訪北海岸各地，用一支彩筆速寫家鄉之美。不管是金山的地標「燭臺雙嶼」，還是療癒的荷花田，甚至朱銘美術館的雕塑作品，都是畫筆捕捉的對象。從三芝、石門、金山、一路畫到萬里，將北海岸的美景變成一幅幅畫作，於金山分館推出創作個展，一同來欣賞不一樣的北海岸之美。', '新北市立圖書館總館', '新北市金山區龜子山8號', '2025-01-02 00:00:00', '2025-12-31 00:00:00', '新北市立圖書館金山分館', 25.21714594, 121.6052639, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館金山分館】李賜民「燭夢舞臺，嶼您有約」創作個展', `description`='【新北市立圖書館金山分館】李賜民「燭夢舞臺，嶼您有約」創作個展\r\n展覽時間：1/2~12/31開館時間\r\n展覽地點：新北市立圖書館金山分館／樓梯廊道\r\n聯絡電話：02-2498-4714#201\r\n簡介：\r\n「整個北海岸，都是我的畫室！」退休後返回金山老家的銀髮素人速寫藝術家家李賜民，六年來走訪北海岸各地，用一支彩筆速寫家鄉之美。不管是金山的地標「燭臺雙嶼」，還是療癒的荷花田，甚至朱銘美術館的雕塑作品，都是畫筆捕捉的對象。從三芝、石門、金山、一路畫到萬里，將北海岸的美景變成一幅幅畫作，於金山分館推出創作個展，一同來欣賞不一樣的北海岸之美。', `organizer`='新北市立圖書館總館', `address`='新北市金山區龜子山8號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='新北市立圖書館金山分館', `latitude`=25.21714594, `longitude`=121.6052639, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5683b26b32418d001b95e', '大安分館親子讀經班', '培養孩子從小閱讀，從四書五經的閱讀中，讓孩子與大人一起共讀是最棒的陪伴。孝經、論語、唐詩、道德經、聲律啟蒙、弟子規等，增進孩子的語言與作文能力。\r\n~歡迎親子電話報名參加~\r\n可至臨櫃索取報名表', '臺中市立圖書館大安分館', '臺中市大安區興安路378號', '2025-02-12 00:00:00', '2025-12-31 00:00:00', '臺中市立圖書館大安分館', 24.36509555, 120.5914407, '無資料', 'https://www.facebook.com/share/p/19dA6joBYY/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大安分館親子讀經班', `description`='培養孩子從小閱讀，從四書五經的閱讀中，讓孩子與大人一起共讀是最棒的陪伴。孝經、論語、唐詩、道德經、聲律啟蒙、弟子規等，增進孩子的語言與作文能力。\r\n~歡迎親子電話報名參加~\r\n可至臨櫃索取報名表', `organizer`='臺中市立圖書館大安分館', `address`='臺中市大安區興安路378號', `start_date`='2025-02-12 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺中市立圖書館大安分館', `latitude`=24.36509555, `longitude`=120.5914407, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/19dA6joBYY/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5683d26b32418d001b95f', '【新北市立圖書館淡水分館】《常設藝文展覽 : 歷史與文化交融的五樓特展區~大河東去：從滬尾到淡水》', '歷史與文化交融的五樓特展區~大河東去：從滬尾到淡水\r\n時間：1/2(四)~12/31(三) 08:30-17:00\r\n地點：淡水分館5樓展覽區（淡水區文化路65號）\r\n電話：02-26224664分機255\r\n\r\n簡介：\r\n匯集了百年來的珍貴史料，包括首任淡水區長蔡葉偉授權的蔡坤煌醫師攝影作品，希望能完整呈現淡水的文化底蘊。特展以「港、河、山、交通、都市與人」為脈絡，淡水在時代洪流中蛻變與傳承，呈現淡水的獨特風貌與水運故事，邀請您踏上這段跨越時光的探索之旅，細細品味淡水的過去與現在。\r\n\r\n在這座擁有絕美夕陽與河景的文化地標中，攝影師陳金隆的《喜事淡水：歲月迴廊》作品，與圖書館重啟的喜悅相互輝映。五樓特展空間不只是展示歷史的場域，更成為連結過去與現在的文化平台，見證淡水從漁港小鎮到文化重鎮的精采蛻變。\r\n\r\n\r\n備註：國定假日及清館日不開放。', '新北市立圖書館總館', '新北市淡水區文化路65號', '2025-01-02 00:00:00', '2025-12-31 00:00:00', '新北市立圖書館淡水分館', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡水分館】《常設藝文展覽 : 歷史與文化交融的五樓特展區~大河東去：從滬尾到淡水》', `description`='歷史與文化交融的五樓特展區~大河東去：從滬尾到淡水\r\n時間：1/2(四)~12/31(三) 08:30-17:00\r\n地點：淡水分館5樓展覽區（淡水區文化路65號）\r\n電話：02-26224664分機255\r\n\r\n簡介：\r\n匯集了百年來的珍貴史料，包括首任淡水區長蔡葉偉授權的蔡坤煌醫師攝影作品，希望能完整呈現淡水的文化底蘊。特展以「港、河、山、交通、都市與人」為脈絡，淡水在時代洪流中蛻變與傳承，呈現淡水的獨特風貌與水運故事，邀請您踏上這段跨越時光的探索之旅，細細品味淡水的過去與現在。\r\n\r\n在這座擁有絕美夕陽與河景的文化地標中，攝影師陳金隆的《喜事淡水：歲月迴廊》作品，與圖書館重啟的喜悅相互輝映。五樓特展空間不只是展示歷史的場域，更成為連結過去與現在的文化平台，見證淡水從漁港小鎮到文化重鎮的精采蛻變。\r\n\r\n\r\n備註：國定假日及清館日不開放。', `organizer`='新北市立圖書館總館', `address`='新北市淡水區文化路65號', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='新北市立圖書館淡水分館', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5684826b32418d001b960', '新高親子才藝讀經班', '新高親子才藝讀經班開始招生！\r\n\r\n讀經~奠定孩子的國學基礎，提升語文、閱讀能力及作文寫作能力！\r\n讀經~可同時開發左右腦，開啟智慧與潛能！\r\n讀經~訓練兒童記憶力，增進專注力、理解力、表達力、耐力、定力！\r\n讀經~涵養孩子的品德教育，知書達禮，提升人格！', '正仁書院人文發展協會', '臺中市太平區', '2025-02-14 00:00:00', '2025-12-26 00:00:00', '太平區（臺中市）=', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/yDb6z2', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新高親子才藝讀經班', `description`='新高親子才藝讀經班開始招生！\r\n\r\n讀經~奠定孩子的國學基礎，提升語文、閱讀能力及作文寫作能力！\r\n讀經~可同時開發左右腦，開啟智慧與潛能！\r\n讀經~訓練兒童記憶力，增進專注力、理解力、表達力、耐力、定力！\r\n讀經~涵養孩子的品德教育，知書達禮，提升人格！', `organizer`='正仁書院人文發展協會', `address`='臺中市太平區', `start_date`='2025-02-14 00:00:00', `end_date`='2025-12-26 00:00:00', `location`='太平區（臺中市）=', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/yDb6z2', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5684926b32418d001b961', '台中太平圓滿親子讀經班', '我們是位於台中太平旱溪的圓滿親子讀經班，這邊有熱心的志工老師和一群愛孩子的家長，在每週五的夜晚一同陪伴孩子們讀經~\r\n期待您和孩子一起來吸收聖賢的智慧，歡迎隨時報名加入', '財團法人崇德文化教育基金會', '臺中市太平區', '2025-02-07 00:00:00', '2025-12-26 00:00:00', '太平區（臺中市）=', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/96AYnO', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台中太平圓滿親子讀經班', `description`='我們是位於台中太平旱溪的圓滿親子讀經班，這邊有熱心的志工老師和一群愛孩子的家長，在每週五的夜晚一同陪伴孩子們讀經~\r\n期待您和孩子一起來吸收聖賢的智慧，歡迎隨時報名加入', `organizer`='財團法人崇德文化教育基金會', `address`='臺中市太平區', `start_date`='2025-02-07 00:00:00', `end_date`='2025-12-26 00:00:00', `location`='太平區（臺中市）=', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/96AYnO', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5685526b32418d001b962', '時代留聲－114年轉型正義推廣活動：戲劇工作坊第4場', '本處規劃20場轉型正義活動，鼓勵社會大眾多元參與，以共同討論、互動分享與傾聽，在轉型正義的反思過程中，凝聚對人權與民主價值的共識，進而實現普世之人權關懷。', '國立中正紀念堂管理處', '臺北市中正區中山南路21號', '2025-09-07 00:00:00', '2025-09-07 00:00:00', '國立中正紀念堂管理處', 25.03240487, 121.5198839, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50518', '[]') ON DUPLICATE KEY UPDATE `activity_name`='時代留聲－114年轉型正義推廣活動：戲劇工作坊第4場', `description`='本處規劃20場轉型正義活動，鼓勵社會大眾多元參與，以共同討論、互動分享與傾聽，在轉型正義的反思過程中，凝聚對人權與民主價值的共識，進而實現普世之人權關懷。', `organizer`='國立中正紀念堂管理處', `address`='臺北市中正區中山南路21號', `start_date`='2025-09-07 00:00:00', `end_date`='2025-09-07 00:00:00', `location`='國立中正紀念堂管理處', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50518', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c5685f26b32418d001b963', '太平豐年社區親子品德繪本暨讀經班', '讓經典成為孩子一生高遠見識、優美人格的活水源頭～我們推廣的「讀經教育」，正是父母協助孩子培養迎向未來能力的極佳教育方式。讀經教育是老祖宗傳承的優秀教育方法，被遺忘了將近百年!早自兩千五百多年前，孔老夫子教導子弟以「詩禮傳家」，讀經教育便一直是中國人傳承文化、啟迪智慧及陶冶人格的最佳教育方式。今日我們如獲至寶，重新在經典教育中找到現代教育的新希望！因此從小讓孩子熟讀「四書五經」，趁他心靈最純淨、記憶力最好的時期，接觸最有價值的經典作品，在幼小的心靈中不斷地反獨、發酵、潛移默化，成為一生高遠見識、優美人格的活水源頭。', '崇德光慧文化教育學會', '臺中市太平區', '2025-03-07 00:00:00', '2025-12-26 00:00:00', '太平區（臺中市）=', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/V09Z7n', '[]') ON DUPLICATE KEY UPDATE `activity_name`='太平豐年社區親子品德繪本暨讀經班', `description`='讓經典成為孩子一生高遠見識、優美人格的活水源頭～我們推廣的「讀經教育」，正是父母協助孩子培養迎向未來能力的極佳教育方式。讀經教育是老祖宗傳承的優秀教育方法，被遺忘了將近百年!早自兩千五百多年前，孔老夫子教導子弟以「詩禮傳家」，讀經教育便一直是中國人傳承文化、啟迪智慧及陶冶人格的最佳教育方式。今日我們如獲至寶，重新在經典教育中找到現代教育的新希望！因此從小讓孩子熟讀「四書五經」，趁他心靈最純淨、記憶力最好的時期，接觸最有價值的經典作品，在幼小的心靈中不斷地反獨、發酵、潛移默化，成為一生高遠見識、優美人格的活水源頭。', `organizer`='崇德光慧文化教育學會', `address`='臺中市太平區', `start_date`='2025-03-07 00:00:00', `end_date`='2025-12-26 00:00:00', `location`='太平區（臺中市）=', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/V09Z7n', `image_url`='[]';
