INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9366527', '總館03/16作家與讀者有約講座《不被束縛的晚年》', '&nbsp; &nbsp; 本館將於3月16日(週日)14：00至16：00於總館10樓國際會議廳舉辦作家與讀者有約講座「不被束縛的晚年：自立支援照顧，讓長者脫離臥床」，活動將邀請作者老年醫學與安寧緩和醫師朱為民和臺灣自立支援推行者林金立，與現場讀者一同探討如何透過正確的照護方式，讓長者脫離臥床、自理生活、自由行動，過自己想過的生活，並減輕照顧者的負擔。。新書講座無須報名，自由入場，歡迎您踴躍參加。活動時間：3月16日（週日）14:00-16:00活動講師：朱為民、林金立（本書作者）&nbsp; &nbsp;&nbsp;活動地點：總館10樓國際會議廳（臺北市大安區建國南路2段125號10樓）※免費講座歡迎您踴躍參加！※本講座提供「公務人員終身學習」時數。', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-03-16 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C82C45E9F5139271', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館03/16作家與讀者有約講座《不被束縛的晚年》', `description`='&nbsp; &nbsp; 本館將於3月16日(週日)14：00至16：00於總館10樓國際會議廳舉辦作家與讀者有約講座「不被束縛的晚年：自立支援照顧，讓長者脫離臥床」，活動將邀請作者老年醫學與安寧緩和醫師朱為民和臺灣自立支援推行者林金立，與現場讀者一同探討如何透過正確的照護方式，讓長者脫離臥床、自理生活、自由行動，過自己想過的生活，並減輕照顧者的負擔。。新書講座無須報名，自由入場，歡迎您踴躍參加。活動時間：3月16日（週日）14:00-16:00活動講師：朱為民、林金立（本書作者）&nbsp; &nbsp;&nbsp;活動地點：總館10樓國際會議廳（臺北市大安區建國南路2段125號10樓）※免費講座歡迎您踴躍參加！※本講座提供「公務人員終身學習」時數。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C82C45E9F5139271', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9362236', '南港分館「小方老師的親子摺紙課」', '一、活動主旨: 利用學習摺紙時的摺摺疊疊，培養小朋友的空間概念與手指的靈活度，有趣的內容帶出小朋友的耐心，是增進親子互動的最佳選擇。課程中擺放摺紙相關書籍，鼓勵大小朋友借閱。二、活動時間及主題:3月23日(星期日)9:30-11:30分格盒及戒指(摺紙)3月23日(星期日)13:30-15:30分格盒及戒指(摺紙)4月27日(星期日)9:30-12:00拖板車(紙模型)4月27日(星期日)13:30-16:00拖板車(紙模型) &nbsp;三、活動對象: 國小兒童。四、活動辦法: 須事先報名，親子組限額5組，免費提供材料及工具，額滿截止。五、報名方式: 1.報名日期: 3月16日 至3月18日2.電話報名: 02-27825232六、活動地點: 臺北市立圖書館南港分館3樓活動室。(臺北市南港區南港路一段350號)', '臺北市立圖書館', '無資料', '2025-03-05 00:00:00', '2025-04-01 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=6FE7E791CAEA4BCF', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南港分館「小方老師的親子摺紙課」', `description`='一、活動主旨: 利用學習摺紙時的摺摺疊疊，培養小朋友的空間概念與手指的靈活度，有趣的內容帶出小朋友的耐心，是增進親子互動的最佳選擇。課程中擺放摺紙相關書籍，鼓勵大小朋友借閱。二、活動時間及主題:3月23日(星期日)9:30-11:30分格盒及戒指(摺紙)3月23日(星期日)13:30-15:30分格盒及戒指(摺紙)4月27日(星期日)9:30-12:00拖板車(紙模型)4月27日(星期日)13:30-16:00拖板車(紙模型) &nbsp;三、活動對象: 國小兒童。四、活動辦法: 須事先報名，親子組限額5組，免費提供材料及工具，額滿截止。五、報名方式: 1.報名日期: 3月16日 至3月18日2.電話報名: 02-27825232六、活動地點: 臺北市立圖書館南港分館3樓活動室。(臺北市南港區南港路一段350號)', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-05 00:00:00', `end_date`='2025-04-01 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=6FE7E791CAEA4BCF', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9353979', '六合分館：心靈捕手讀書會', '活動名稱：心靈捕手讀書會活動目的：透過閱讀分享，釋放生活壓力，增長人生智慧，從而獲得心靈的成長主辦單位：臺北市立圖書館六合分館活動時間：3月11日至6月24日，每週二上午9：00-11：00 共16堂課活動地點：臺北市立圖書館六合分館5樓視聽室(臺北市松仁路240巷19號)活動對象：凡對閱讀分享有興趣的朋友帶領人：詹美玲老師閱讀書籍：《只有兩個人》、《莫斯科紳士》、《生命中不能承受之輕》觀賞影片：電影「歡迎來到布達佩斯大飯店」、日劇「重啟人生」活動費用：免費報名時間：即日起接受報名至人數額滿截止，請於開館時間內洽詢本分館4樓櫃檯，電話：（02）2729-2485。', '臺北市立圖書館', '無資料', '2025-03-05 00:00:00', '2025-06-18 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=E3E0AAF3B13CF337', '[]') ON DUPLICATE KEY UPDATE `activity_name`='六合分館：心靈捕手讀書會', `description`='活動名稱：心靈捕手讀書會活動目的：透過閱讀分享，釋放生活壓力，增長人生智慧，從而獲得心靈的成長主辦單位：臺北市立圖書館六合分館活動時間：3月11日至6月24日，每週二上午9：00-11：00 共16堂課活動地點：臺北市立圖書館六合分館5樓視聽室(臺北市松仁路240巷19號)活動對象：凡對閱讀分享有興趣的朋友帶領人：詹美玲老師閱讀書籍：《只有兩個人》、《莫斯科紳士》、《生命中不能承受之輕》觀賞影片：電影「歡迎來到布達佩斯大飯店」、日劇「重啟人生」活動費用：免費報名時間：即日起接受報名至人數額滿截止，請於開館時間內洽詢本分館4樓櫃檯，電話：（02）2729-2485。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-05 00:00:00', `end_date`='2025-06-18 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=E3E0AAF3B13CF337', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9337691', '大同分館：2025年市民生活講座「養生健康吃」', '邀請老師來教大家食材養生概念，如何吃得健康，並且可以幫助大家全面了解如何在生活中實踐養生健康，改善日常習慣，達到長期的健康效果，趕快來報名喔!【講座時間】3月29日（週六）下午2:00-4:00【講座地點】大同分館B1樂齡學習中心【講座對象】一般民眾【報名時間】3月4日(二)至3月24日(一)【報名說明】共50人，抽籤決定，錄取名單於3/25下午6點前公布於大同分館Facebook，開放進場與候補簽到時間為活動前半小時，活動開始10分鐘未到將失去資格，依候補名單順序補上。【報名網址】https://www.beclass.com/rid=294db42676262a1cbafc&nbsp;', '臺北市立圖書館', '無資料', '2025-03-05 00:00:00', '2025-03-19 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=BA7B2C375DAFAF8C', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大同分館：2025年市民生活講座「養生健康吃」', `description`='邀請老師來教大家食材養生概念，如何吃得健康，並且可以幫助大家全面了解如何在生活中實踐養生健康，改善日常習慣，達到長期的健康效果，趕快來報名喔!【講座時間】3月29日（週六）下午2:00-4:00【講座地點】大同分館B1樂齡學習中心【講座對象】一般民眾【報名時間】3月4日(二)至3月24日(一)【報名說明】共50人，抽籤決定，錄取名單於3/25下午6點前公布於大同分館Facebook，開放進場與候補簽到時間為活動前半小時，活動開始10分鐘未到將失去資格，依候補名單順序補上。【報名網址】https://www.beclass.com/rid=294db42676262a1cbafc&nbsp;', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-19 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=BA7B2C375DAFAF8C', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9327661', '六合分館：兒童電影院-週三FUN電影（114年03月）', '活動名稱：114 年度「兒童電影院-週三FUN電影」活動活動宗旨：兒童服務是公共圖書館服務中重要的一環，為引導兒童善用圖書館資源以擴大學習層面、豐富學習效果、激發學習興趣，本館特以視聽放映活動吸引兒童及其家長踏入圖書館，進而培養兒童從小利用圖書館的習慣。活動時間：3月5日起至3月26日，每週三下午2：30例行放映。活動地點：臺北市立圖書館六合分館5樓視聽室。（地址：臺北市信義區松仁路240巷19號5樓，若有相關問題歡迎來電洽詢，電話：2729-2485）。活動對象：以12歲以下兒童為對象，由圖書館排定時間及影片，定期播放，自由欣賞。活動辦法：每週三下午2：30於六合分館視聽室，利用投影機及DVD放影機播放影片，並於一個月前以海報方式預告影片名稱及內容簡介。影片安排：&nbsp;3/5 &nbsp;寶萊塢之麻吉大明星 &nbsp;(普)3/12 歡樂滿人間 &nbsp;(普)3/19 逆風飛翔 &nbsp;(普)3/26 低糖愛情 &nbsp;(普)交通路線：交通路線', '臺北市立圖書館', '無資料', '2025-03-05 00:00:00', '2025-03-26 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=4BDC24C32CCE4CFA', '[]') ON DUPLICATE KEY UPDATE `activity_name`='六合分館：兒童電影院-週三FUN電影（114年03月）', `description`='活動名稱：114 年度「兒童電影院-週三FUN電影」活動活動宗旨：兒童服務是公共圖書館服務中重要的一環，為引導兒童善用圖書館資源以擴大學習層面、豐富學習效果、激發學習興趣，本館特以視聽放映活動吸引兒童及其家長踏入圖書館，進而培養兒童從小利用圖書館的習慣。活動時間：3月5日起至3月26日，每週三下午2：30例行放映。活動地點：臺北市立圖書館六合分館5樓視聽室。（地址：臺北市信義區松仁路240巷19號5樓，若有相關問題歡迎來電洽詢，電話：2729-2485）。活動對象：以12歲以下兒童為對象，由圖書館排定時間及影片，定期播放，自由欣賞。活動辦法：每週三下午2：30於六合分館視聽室，利用投影機及DVD放影機播放影片，並於一個月前以海報方式預告影片名稱及內容簡介。影片安排：&nbsp;3/5 &nbsp;寶萊塢之麻吉大明星 &nbsp;(普)3/12 歡樂滿人間 &nbsp;(普)3/19 逆風飛翔 &nbsp;(普)3/26 低糖愛情 &nbsp;(普)交通路線：交通路線', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=4BDC24C32CCE4CFA', `image_url`='[]';
