INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9366055', '2025年新光醫院母乳支持團體活動~歡迎哺乳家庭成員踴躍參與!!', '2025年新光醫院母乳支持團體活動-歡迎哺乳家庭成員踴躍參與~本中心為增進媽媽們母乳哺餵知識及概念，以提升母乳的哺餵意願，並建立完善支持性環境，辦理相關課程訊息如下：一、時間：114年2月22日至12月20日，共計6次聚會。二&nbsp;、地點：新光醫院B2第六會議室。三、對象：正在哺乳的婦女、對母乳哺育有興趣者。四、費用：課程免費。五、報名方式：採電話報名，名額有限，請盡早報名。&nbsp; &nbsp;六、報名專線：(02)28332211#3881或3882七、詳情請見附件: 2025母乳支持團體活動。', '臺北市士林區健康服務中心', '無資料', '2025-03-04 00:00:00', '2025-12-20 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=D798A4C598684AA2', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年新光醫院母乳支持團體活動~歡迎哺乳家庭成員踴躍參與!!', `description`='2025年新光醫院母乳支持團體活動-歡迎哺乳家庭成員踴躍參與~本中心為增進媽媽們母乳哺餵知識及概念，以提升母乳的哺餵意願，並建立完善支持性環境，辦理相關課程訊息如下：一、時間：114年2月22日至12月20日，共計6次聚會。二&nbsp;、地點：新光醫院B2第六會議室。三、對象：正在哺乳的婦女、對母乳哺育有興趣者。四、費用：課程免費。五、報名方式：採電話報名，名額有限，請盡早報名。&nbsp; &nbsp;六、報名專線：(02)28332211#3881或3882七、詳情請見附件: 2025母乳支持團體活動。', `organizer`='臺北市士林區健康服務中心', `address`='無資料', `start_date`='2025-03-04 00:00:00', `end_date`='2025-12-20 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=D798A4C598684AA2', `image_url`='[]';
