INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9365071', '北投就業服務站將於114年3月11日(週二)下午2-4時辦理【中興保全科技股份有限公司台北分公司】微型徵才活動', '北投就業服務站將於114年3月11日(週二)下午2-4時辦理【中興保全科技股份有限公司台北分公司】微型徵才活動活動時間：3月11日(二)下午2:00~4:00活動地點：北投就業服務站 (臺北市北投區新市街30號5樓)洽詢電話：(02)28981819#115公司簡介：中興保全科技股份有限公司為中保科技集團的主要成員之ㄧ，以結合科技應用的「中保無限＋」服務體系，做為物聯網實踐者。在安全服務之外，增加服務的方便性與趣味性。福利制度：1.股利紅利2.三節獎金3.員工團體保險4.員工社團5.完整職前及在職訓練6.員工年度健檢7.子女獎助學金職務名稱：服務工程師需求人數：10學歷要求：高中職以上工作經驗：不拘工作內容：1.系統維護、維修。2.客戶現場異常狀況處理(純待命制)。3.須外出執行工作。薪資待遇：月薪36453元起(技能津貼及加班費另計外加，此職缺薪資依每月排定時數多寡而會有浮動)工作時間：早班8:30-21:30/晚班20:30-9:30，內含休息一小時工作地點：台北市(按居住地分派)職務名稱：業務專員需求人數：10學歷要求：高中職以上工作經驗：不拘工作內容：科技安全相關產品推廣銷售。薪資待遇：月薪31000元起(另有高額業績獎金，依業績或績效獎金核算) (獎金因案件規模各有不同)工作時間：8:30-17:30工作地點：台北市(按居住地分派)職務名稱：客服人員需求人數：10學歷要求：高中職以上工作經驗：不拘工作內容：1.客戶服務諮詢。2.客戶售後服務及問題諮詢。3.純內勤線上客服人員，非電銷工作。薪資待遇：月薪30800元起(滿一個月後月薪36453元起)(輪值津貼另計)工作時間：早班、小夜班、大夜班，需輪班工作地點：台北市內湖區', '北投就業服務站', '台北市北投區新市街30號5樓', '2025-03-11 00:00:00', '2025-03-11 00:00:00', '北投就業服務站', 25.1480682, 121.5177992, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=0F59404974B58D15', '[]') ON DUPLICATE KEY UPDATE `activity_name`='北投就業服務站將於114年3月11日(週二)下午2-4時辦理【中興保全科技股份有限公司台北分公司】微型徵才活動', `description`='北投就業服務站將於114年3月11日(週二)下午2-4時辦理【中興保全科技股份有限公司台北分公司】微型徵才活動活動時間：3月11日(二)下午2:00~4:00活動地點：北投就業服務站 (臺北市北投區新市街30號5樓)洽詢電話：(02)28981819#115公司簡介：中興保全科技股份有限公司為中保科技集團的主要成員之ㄧ，以結合科技應用的「中保無限＋」服務體系，做為物聯網實踐者。在安全服務之外，增加服務的方便性與趣味性。福利制度：1.股利紅利2.三節獎金3.員工團體保險4.員工社團5.完整職前及在職訓練6.員工年度健檢7.子女獎助學金職務名稱：服務工程師需求人數：10學歷要求：高中職以上工作經驗：不拘工作內容：1.系統維護、維修。2.客戶現場異常狀況處理(純待命制)。3.須外出執行工作。薪資待遇：月薪36453元起(技能津貼及加班費另計外加，此職缺薪資依每月排定時數多寡而會有浮動)工作時間：早班8:30-21:30/晚班20:30-9:30，內含休息一小時工作地點：台北市(按居住地分派)職務名稱：業務專員需求人數：10學歷要求：高中職以上工作經驗：不拘工作內容：科技安全相關產品推廣銷售。薪資待遇：月薪31000元起(另有高額業績獎金，依業績或績效獎金核算) (獎金因案件規模各有不同)工作時間：8:30-17:30工作地點：台北市(按居住地分派)職務名稱：客服人員需求人數：10學歷要求：高中職以上工作經驗：不拘工作內容：1.客戶服務諮詢。2.客戶售後服務及問題諮詢。3.純內勤線上客服人員，非電銷工作。薪資待遇：月薪30800元起(