INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9365035', '戶外親子走讀-萬華百年教育與文教', '活動時間：2025年3月8日下午2時30分至4時30分活動集合地點：臺北市鄉土教育中心 一樓大廳 (臺北市萬華區廣州街101號)活動內容：走讀中萬華艋舺剝皮寮歷史街區、萬華社區大學、龍山國中、昔日警察專科學校、老松國小、老松補校、昔日老松商校、艋舺龍山寺、艋舺長老教會松年社區大學、愛心幼兒園、艋舺祖師廟、艋舺青山宮、艋舺學海書院、龍山國小，以及廣州街、西昌街、康定路，臺北第一街貴陽街等老廟與街廓內老店，有關萬華百年教育與文教(文具與教科書)相關的在地生活故事。主講人：高傳棋(臺北水窗口執行長、萬華地區文史工作者)報名網址：https://www.beclass.com/rid=294fe5b67a071683889d', '臺北市萬華區公所', '無資料', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=199383C761014AFE', '[]') ON DUPLICATE KEY UPDATE `activity_name`='戶外親子走讀-萬華百年教育與文教', `description`='活動時間：2025年3月8日下午2時30分至4時30分活動集合地點：臺北市鄉土教育中心 一樓大廳 (臺北市萬華區廣州街101號)活動內容：走讀中萬華艋舺剝皮寮歷史街區、萬華社區大學、龍山國中、昔日警察專科學校、老松國小、老松補校、昔日老松商校、艋舺龍山寺、艋舺長老教會松年社區大學、愛心幼兒園、艋舺祖師廟、艋舺青山宮、艋舺學海書院、龍山國小，以及廣州街、西昌街、康定路，臺北第一街貴陽街等老廟與街廓內老店，有關萬華百年教育與文教(文具與教科書)相關的在地生活故事。主講人：高傳棋(臺北水窗口執行長、萬華地區文史工作者)報名網址：https://www.beclass.com/rid=294fe5b67a071683889d', `organizer`='臺北市萬華區公所', `address`='無資料', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=199383C761014AFE', `image_url`='[]';
