INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9364874', '稻香分館「114年度親子讀經讀書會」歡迎參加！', '一、活動內容：藉由親子共讀學習的方式，帶領閱讀論語、中庸、唐詩，讓小朋友吸收中華文化的智慧，儲備一生受用的文化素養。二、活動時間及地點：114年3月5日至115年1月7日，每週三下午7:00-9:00，稻香分館8樓研習教室。三、活動對象：歡迎家長帶高中（含）以下的孩子一同參加。四、讀書會帶領人：稻香分館閱讀推廣志工。五、交通路線：https://reurl.cc/Z9gDXW粉絲專頁：https://www.facebook.com/daoxianglib六、地　　址：112臺北市北投區稻香路81號7-9樓電　　話：28940662', '臺北市立圖書館', '臺北市北投區稻香路81號7-9樓', '2025-03-03 00:00:00', '2025-12-31 00:00:00', '無資料', 25.1480682, 121.5177992, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F40E7ABCEF249253', '[]') ON DUPLICATE KEY UPDATE `activity_name`='稻香分館「114年度親子讀經讀書會」歡迎參加！', `description`='一、活動內容：藉由親子共讀學習的方式，帶領閱讀論語、中庸、唐詩，讓小朋友吸收中華文化的智慧，儲備一生受用的文化素養。二、活動時間及地點：114年3月5日至115年1月7日，每週三下午7:00-9:00，稻香分館8樓研習教室。三、活動對象：歡迎家長帶高中（含）以下的孩子一同參加。四、讀書會帶領人：稻香分館閱讀推廣志工。五、交通路線：https://reurl.cc/Z9gDXW粉絲專頁：https://www.facebook.com/daoxianglib六、地　　址：112臺北市北投區稻香路81號7-9樓電　　話：28940662', `organizer`='臺北市立圖書館', `address`='臺北市北投區稻香路81號7-9樓', `start_date`='2025-03-03 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='無資料', `latitude`=25.1480682, `longitude`=121.5177992, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F40E7ABCEF249253', `image_url`='[]';
