INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8056207f3d4433af95547', '2025朱宗慶打擊樂團第二季音樂會《打擊樂與他的好朋友們》', '╲╲大提琴・笙・小號・電吉他・電子人聲╱╱\r\n樂界好朋友，迸發新火花！\r\n\r\n廣受好評的《打擊樂與他的好朋友們》，今年將以全新陣容開啟嶄新篇章！\r\n \r\n本次，特別邀請五組好朋友—大提琴演奏家陳世霖、臺灣國樂團笙首席陳麒米、小號演奏家侯傳安、知名西塔琴演奏家暨職業吉他手AZeR吳欣澤，以及金曲獎「最佳演唱組合」尋人啟事—共同演出。\r\n \r\n來自不同領域的頂尖音樂家，將與打擊樂融合，激盪出耳目一新的聽覺饗宴。\r\n \r\n邀請您走進音樂廳，親身感受打擊樂與五個全新組合的精彩互動，體驗多元風格交織的獨特魅力！', '財團法人擊樂文教基金會', '臺北市中山南路21-1號', '2025-05-17 00:00:00', '2025-05-17 00:00:00', '國家音樂廳', 0, 0, '$600　$900　$1,200　$1,500　$1,800　$2,000', 'https://www.opentix.life/event/1889225722384187392', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025朱宗慶打擊樂團第二季音樂會《打擊樂與他的好朋友們》', `description`='╲╲大提琴・笙・小號・電吉他・電子人聲╱╱\r\n樂界好朋友，迸發新火花！\r\n\r\n廣受好評的《打擊樂與他的好朋友們》，今年將以全新陣容開啟嶄新篇章！\r\n \r\n本次，特別邀請五組好朋友—大提琴演奏家陳世霖、臺灣國樂團笙首席陳麒米、小號演奏家侯傳安、知名西塔琴演奏家暨職業吉他手AZeR吳欣澤，以及金曲獎「最佳演唱組合」尋人啟事—共同演出。\r\n \r\n來自不同領域的頂尖音樂家，將與打擊樂融合，激盪出耳目一新的聽覺饗宴。\r\n \r\n邀請您走進音樂廳，親身感受打擊樂與五個全新組合的精彩互動，體驗多元風格交織的獨特魅力！', `organizer`='財團法人擊樂文教基金會', `address`='臺北市中山南路21-1號', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='國家音樂廳', `latitude`=0, `longitude`=0, `ticket_price`='$600　$900　$1,200　$1,500　$1,800　$2,000', `source_url`='https://www.opentix.life/event/1889225722384187392', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c80e8607f3d4433af95548', '【新北市立圖書館泰山分館】李安琪「享繡․植感生活個展」', '藝術家李安琪 生活在一片蓬勃的自然環境中，窗外的鳥鳴宛如天籟，植物在微風中輕輕搖曳與陽光映照下，綻放無限的生命脈動與美好的瞬間。\r\n\r\n創作以「觀察」、「審美」、「創造」的歷程為基礎，巧妙運用刺繡、繪畫、雕塑等手工技藝與植物元素，讓生活與大自然完美結合，層層堆疊出夢幻與現實的時空交融。\r\n這次展覽的核心圍繞著以愛交流，萬物共存，美麗淨土，平靜溫暖的故事，並以立體的鳥和菇菇為創作的輔助元素。\r\n展現了繽紛的色彩和多樣的創作媒材，旨在讓觀者透過不同的視角，探索這個神秘而富饒的生命世界，發掘出屬於自己的感悟，不僅是滿足視覺上的享受，更感受到大自然所帶來的獨特啟發與深刻連結，也共感著創作者的靈魂與訴說。\r\n\r\n展覽期間為2025年3月01日至2025年4月30日，誠摯邀請各界人士與鄰里闔家蒞臨參觀。\r\n', '新北市立圖書館泰山分館', '新北市新北市泰山區全興路212號5樓', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館泰山分館', 0, 0, '無資料', 'https://sites.google.com/view/frshouse7/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館泰山分館】李安琪「享繡․植感生活個展」', `description`='藝術家李安琪 生活在一片蓬勃的自然環境中，窗外的鳥鳴宛如天籟，植物在微風中輕輕搖曳與陽光映照下，綻放無限的生命脈動與美好的瞬間。\r\n\r\n創作以「觀察」、「審美」、「創造」的歷程為基礎，巧妙運用刺繡、繪畫、雕塑等手工技藝與植物元素，讓生活與大自然完美結合，層層堆疊出夢幻與現實的時空交融。\r\n這次展覽的核心圍繞著以愛交流，萬物共存，美麗淨土，平靜溫暖的故事，並以立體的鳥和菇菇為創作的輔助元素。\r\n展現了繽紛的色彩和多樣的創作媒材，旨在讓觀者透過不同的視角，探索這個神秘而富饒的生命世界，發掘出屬於自己的感悟，不僅是滿足視覺上的享受，更感受到大自然所帶來的獨特啟發與深刻連結，也共感著創作者的靈魂與訴說。\r\n\r\n展覽期間為2025年3月01日至2025年4月30日，誠摯邀請各界人士與鄰里闔家蒞臨參觀。\r\n', `organizer`='新北市立圖書館泰山分館', `address`='新北市新北市泰山區全興路212號5樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館泰山分館', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://sites.google.com/view/frshouse7/', `image_url`='[]';
