INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c21e26b32408680be97e', '良朋雅集‧十里清香－中華民國工筆畫學會會員聯展（免費參觀）', '中華民國工筆畫學會，前身為「中國工筆畫研究會」，自1991年吳文彬先生創會以來，經過歷任理事長吳文彬、張克齊、林淑女、陳忠平、徐仁崇、邱素美、陳九熹、林碧麗等前輩們的悉心耕耘，34年來始終致力於工筆畫的推廣與傳承，不僅定期出版《工筆畫》季刊，舉辦會員聯展並印製畫冊，更多次舉辦「海峽兩岸名家交流展」，出版專刊，促進藝術對話。\n\n本次盛大舉辦會員聯展，精選117位創作者的佳作，集結全國工筆畫名家與菁英精彩呈現。作品涵蓋花鳥、人物（佛畫）、山水、動物等多元題材，無論是寫生描繪或個人創作，皆工致精微、雅逸脫俗，兼具傳統韻味與當代創新。\n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-03-14 00:00:00', '2025-03-24 00:00:00', '2展廳', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50748', '[]') ON DUPLICATE KEY UPDATE `activity_name`='良朋雅集‧十里清香－中華民國工筆畫學會會員聯展（免費參觀）', `description`='中華民國工筆畫學會，前身為「中國工筆畫研究會」，自1991年吳文彬先生創會以來，經過歷任理事長吳文彬、張克齊、林淑女、陳忠平、徐仁崇、邱素美、陳九熹、林碧麗等前輩們的悉心耕耘，34年來始終致力於工筆畫的推廣與傳承，不僅定期出版《工筆畫》季刊，舉辦會員聯展並印製畫冊，更多次舉辦「海峽兩岸名家交流展」，出版專刊，促進藝術對話。\n\n本次盛大舉辦會員聯展，精選117位創作者的佳作，集結全國工筆畫名家與菁英精彩呈現。作品涵蓋花鳥、人物（佛畫）、山水、動物等多元題材，無論是寫生描繪或個人創作，皆工致精微、雅逸脫俗，兼具傳統韻味與當代創新。\n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-24 00:00:00', `location`='2展廳', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50748', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c23126b32408680be97f', '【環教課程假日場】植物調查員-馬丁博士找小樟', ' \n\n【環教課程假日場】植物調查員-馬丁博士找小樟\n\n🌳 時間：\n\n\n	3/16(日)13:00-15:00   \n	3/30(日)13:00-15:00        \n\n\n🌳 地點：台北市中正區南昌路一段1號   小白宮\n\n🌳 對象：歡迎一般民眾報名（建議年齡為國小中年級以上）\n\n \n\n臺灣博物館為環境教育設施認證場所，提供「植物調查員-馬丁博士找小樟」環境教育課程，增進學員認識生活周遭的樟樹、人們運用樟樹資源的方式，邀請參與者一同關懷臺灣的樹木與自然環境，從中觀察了解相關環境議題。今規劃開放假日場，讓一般大眾也有機會參與體驗本課程內容 (預計四、五月將分別推出其他環教課程假日場，有興趣者請留意官網訊息)。\n\n\n	\n		\n			\n			\n			\n		\n	\n\n\n \n\n🌳 課程流程：\n\n「遠的要命王國」的「坎弗爾自然史博物館」裡工作的馬丁博士，寄來一封信！請大家幫忙進行一場樟樹的植物調查！快來幫他解開秘密吧！課程透過五感體驗，帶領參與環教課程學員認識樟樹的特徵、生態特性，學習與實際進行基礎植物調查，揭開南門館的樟樹秘密。\n\n\n	\n		\n			\n			時間\n			\n			\n			單元名稱\n			\n			\n			內容\n			\n			\n			教學地點\n			\n		\n		\n			\n			 \n\n			13:00-13:30\n			\n			\n			小樟調查員\n			\n			\n			馬丁博士是坎弗爾自然史博物館的研究員，想對臺灣樟樹進行研究，來信請臺博館協助。本單元將由學員扮演小樟調查員，透過馬丁博士提供的三道線索，認識樟樹構造、特色與辨識方法。\n			\n			\n			小白宮\n			\n		\n		\n			\n			13:30-14:00\n			\n			\n			樟樹健康檢查\n			\n			\n			南門館種植許多樟樹，調查南門館戶外園區內的樟樹分布情形。並觀察生長情形，瞭解的植物調查方式，發現大自然生物與植物互相依存關係。 \n			\n			\n			南門館\n\n			戶外園區\n			\n		\n		\n			\n			14:00-14:40\n			\n			\n			全身是寶—\n\n			樟樹前世今生\n			\n			\n			南門館在日本時代曾生產樟腦產量第一的工場，本單元帶領引導學員認識樟樹如何製成樟腦，樟腦有哪些用途，透過遊戲加深學員對樟腦用途的印象，了解樟樹全身是寶。 \n			\n			\n			紅樓展場\n\n			+小白宮 \n			\n		\n		\n			\n			14:40-15:00\n			\n			\n			我知道了!!!\n\n			馬丁博士!\n			\n			\n			課程總結，討論樟腦在環境中的角色與功能。請學員將所得各項調查回信給馬丁博士，完成調查。帶領學員認識FSC標章環保樹林的意義。\n			\n			\n			小白宮\n			\n		\n	\n\n\n \n\n🌳 報名方式：請於每場活動前十分鐘至服務台登記。\n\n🌳 活動本身免費，但請於活動前至服務台購買門票（含陪同者）。\n\n🌳 為辦理活動成果紀錄及相關宣傳，將進行課程拍攝或攝影；報名預設為視同同意進行攝像，如有不希望肖像授權使用者，再請告知現場工作人員。\n\n \n\n ', '國立臺灣博物館', '100  臺北市中正區南昌路一段1號', '2025-03-16 00:00:00', '2025-03-30 00:00:00', '臺博館南門館', 25.0331483, 121.5159774, '無資料', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=50080', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【環教課程假日場】植物調查員-馬丁博士找小樟', `description`=' \n\n【環教課程假日場】植物調查員-馬丁博士找小樟\n\n🌳 時間：\n\n\n	3/16(日)13:00-15:00   \n	3/30(日)13:00-15:00        \n\n\n🌳 地點：台北市中正區南昌路一段1號   小白宮\n\n🌳 對象：歡迎一般民眾報名（建議年齡為國小中年級以上）\n\n \n\n臺灣博物館為環境教育設施認證場所，提供「植物調查員-馬丁博士找小樟」環境教育課程，增進學員認識生活周遭的樟樹、人們運用樟樹資源的方式，邀請參與者一同關懷臺灣的樹木與自然環境，從中觀察了解相關環境議題。今規劃開放假日場，讓一般大眾也有機會參與體驗本課程內容 (預計四、五月將分別推出其他環教課程假日場，有興趣者請留意官網訊息)。\n\n\n	\n		\n			\n			\n			\n		\n	\n\n\n \n\n🌳 課程流程：\n\n「遠的要命王國」的「坎弗爾自然史博物館」裡工作的馬丁博士，寄來一封信！請大家幫忙進行一場樟樹的植物調查！快來幫他解開秘密吧！課程透過五感體驗，帶領參與環教課程學員認識樟樹的特徵、生態特性，學習與實際進行基礎植物調查，揭開南門館的樟樹秘密。\n\n\n	\n		\n			\n			時間\n			\n			\n			單元名稱\n			\n			\n			內容\n			\n			\n			教學地點\n			\n		\n		\n			\n			 \n\n			13:00-13:30\n			\n			\n			小樟調查員\n			\n			\n			馬丁博士是坎弗爾自然史博物館的研究員，想對臺灣樟樹進行研究，來信請臺博館協助。本單元將由學員扮演小樟調查員，透過馬丁博士提供的三道線索，認識樟樹構造、特色與辨識方法。\n			\n			\n			小白宮\n			\n		\n		\n			\n			13:30-14:00\n			\n			\n			樟樹健康檢查\n			\n			\n			南門館種植許多樟樹，調查南門館戶外園區內的樟樹分布情形。並觀察生長情形，瞭解的植物調查方式，發現大自然生物與植物互相依存關係。 \n			\n			\n			南門館\n\n			戶外園區\n			\n		\n		\n			\n			14:00-14:40\n			\n			\n			全身是寶—\n\n			樟樹前世今生\n			\n			\n			南門館在日本時代曾生產樟腦產量第一的工場，本單元帶領引導學員認識樟樹如何製成樟腦，樟腦有哪些用途，透過遊戲加深學員對樟腦用途的印象，了解樟樹全身是寶。 \n			\n			\n			紅樓展場\n\n			+小白宮 \n			\n		\n		\n			\n			14:40-15:00\n			\n			\n			我知道了!!!\n\n			馬丁博士!\n			\n			\n			課程總結，討論樟腦在環境中的角色與功能。請學員將所得各項調查回信給馬丁博士，完成調查。帶領學員認識FSC標章環保樹林的意義。\n			\n			\n			小白宮\n			\n		\n	\n\n\n \n\n🌳 報名方式：請於每場活動前十分鐘至服務台登記。\n\n🌳 活動本身免費，但請於活動前至服務台購買門票（含陪同者）。\n\n🌳 為辦理活動成果紀錄及相關宣傳，將進行課程拍攝或攝影；報名預設為視同同意進行攝像，如有不希望肖像授權使用者，再請告知現場工作人員。\n\n \n\n ', `organizer`='國立臺灣博物館', `address`='100  臺北市中正區南昌路一段1號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺博館南門館', `latitude`=25.0331483, `longitude`=121.5159774, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=50080', `image_url`='[]';
