INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c29526b32408680be98e', '【劇場Art 報馬仔系列講座】究竟是孤獨成癮，還是窮到只剩自己？', '有人說劇場是一群人一起完成一件事， 那今天整個演出，幕前到幕後，只有一個人， 那該有多寂寞？ 一個畢業於戲劇系主修表演的演員，從台上做到台下，從後台做到側台，坐上控台站在前台。總是跟人家說：「我是做劇場的。」 要說我是做哪個位置的呢？ 嗯，我想這次我全做了。', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', 'https://tixfun.com/UTK0101_', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【劇場Art 報馬仔系列講座】究竟是孤獨成癮，還是窮到只剩自己？', `description`='有人說劇場是一群人一起完成一件事， 那今天整個演出，幕前到幕後，只有一個人， 那該有多寂寞？ 一個畢業於戲劇系主修表演的演員，從台上做到台下，從後台做到側台，坐上控台站在前台。總是跟人家說：「我是做劇場的。」 要說我是做哪個位置的呢？ 嗯，我想這次我全做了。', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='https://tixfun.com/UTK0101_', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c29626b32408680be98f', '「心．創客」腦X手美麗境界 師生作品聯展｜竹夢園流畫藝廊 ', '「竹夢園流畫藝廊」將舉辦首場的師生作品聯展，會中\r\n歡迎大家前來會場一起著色。\r\n#致贈日本陶瓷百步蛇大鈴鐺，自己著色並帶回家。\r\n新年新氣象。祝願平安喜樂健康。\r\n為準備顏料，請接龍。感謝您。（百步蛇鈴鐺僅限25位）手刀要快搶先報名喔！', '竹夢園流畫藝廊', '新竹市北區', '2025-01-01 00:00:00', '2025-06-30 00:00:00', '北區（新竹市）=', 24.82269542, 120.9491233, '無資料', 'https://www.facebook.com/chinglin424933/posts/pfbid0rCpmuGfMfpz7GBVxfVVD6AGvzdXZ18uG9h8LuH9Wae5dNCMT', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「心．創客」腦X手美麗境界 師生作品聯展｜竹夢園流畫藝廊 ', `description`='「竹夢園流畫藝廊」將舉辦首場的師生作品聯展，會中\r\n歡迎大家前來會場一起著色。\r\n#致贈日本陶瓷百步蛇大鈴鐺，自己著色並帶回家。\r\n新年新氣象。祝願平安喜樂健康。\r\n為準備顏料，請接龍。感謝您。（百步蛇鈴鐺僅限25位）手刀要快搶先報名喔！', `organizer`='竹夢園流畫藝廊', `address`='新竹市北區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='北區（新竹市）=', `latitude`=24.82269542, `longitude`=120.9491233, `ticket_price`='無資料', `source_url`='https://www.facebook.com/chinglin424933/posts/pfbid0rCpmuGfMfpz7GBVxfVVD6AGvzdXZ18uG9h8LuH9Wae5dNCMT', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c29b26b32408680be990', '2025風動室內樂團《無限》電影配樂音樂會', '《無限》電影配樂音樂會精選了八首源自不同電影的配樂佳作，搭配華麗的燈光效果，就是要讓粉絲們身歷其境體驗到最震撼的瞬間、感受到這些電影所帶來的經典場景！\r\n風動室內樂團與一群活躍於台灣樂壇的頂尖音樂家合作，以無懈可擊的實力帶來一場又一場的精彩演出。\r\n', '花格子藝術有限公司', '臺南市東區中華東路三段332號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '600/900/1200/1400/1600/1800元+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025風動室內樂團《無限》電影配樂音樂會', `description`='《無限》電影配樂音樂會精選了八首源自不同電影的配樂佳作，搭配華麗的燈光效果，就是要讓粉絲們身歷其境體驗到最震撼的瞬間、感受到這些電影所帶來的經典場景！\r\n風動室內樂團與一群活躍於台灣樂壇的頂尖音樂家合作，以無懈可擊的實力帶來一場又一場的精彩演出。\r\n', `organizer`='花格子藝術有限公司', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='600/900/1200/1400/1600/1800元+--', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2a626b32408680be991', '靜謐 — 鄭文珠粉彩創作展', '「靜謐」，緣起於生活中難免會有些紛擾，能夠體會生活當下的一點靜謐感，是生命中的禮物。藝術家鄭文珠藉由色彩與畫面安排，提供一個空間，讓觀者在觀賞畫作的當下，能體驗到一份恬靜感，進而獲得心靈上的休憩。此次展出的創作題材皆源自於台灣日常生活的景色：涵蓋鄉間街景、花卉、田野等元素，因爲是生活小品，無形中讓人有一份熟悉感，邀請觀者一同展開一場靜謐藝術之旅。\r\n「粉彩」，這裡所指的是乾性粉彩，是一種古老的媒材，在歐美極為風行，色彩多元又飽和，用於寫生及創作極為方便。鄭文珠專於粉彩創作，此次展出42件粉彩作品，誠摯邀請您蒞臨指教，共同來欣賞「粉彩」與「靜謐」的藝術饗宴。', '新竹市文化局', '新竹市北區中正路120號', '2025-03-12 00:00:00', '2025-03-30 00:00:00', '新竹市政府/新竹州廳', 24.82269542, 120.9491233, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='靜謐 — 鄭文珠粉彩創作展', `description`='「靜謐」，緣起於生活中難免會有些紛擾，能夠體會生活當下的一點靜謐感，是生命中的禮物。藝術家鄭文珠藉由色彩與畫面安排，提供一個空間，讓觀者在觀賞畫作的當下，能體驗到一份恬靜感，進而獲得心靈上的休憩。此次展出的創作題材皆源自於台灣日常生活的景色：涵蓋鄉間街景、花卉、田野等元素，因爲是生活小品，無形中讓人有一份熟悉感，邀請觀者一同展開一場靜謐藝術之旅。\r\n「粉彩」，這裡所指的是乾性粉彩，是一種古老的媒材，在歐美極為風行，色彩多元又飽和，用於寫生及創作極為方便。鄭文珠專於粉彩創作，此次展出42件粉彩作品，誠摯邀請您蒞臨指教，共同來欣賞「粉彩」與「靜謐」的藝術饗宴。', `organizer`='新竹市文化局', `address`='新竹市北區中正路120號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='新竹市政府/新竹州廳', `latitude`=24.82269542, `longitude`=120.9491233, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2a626b32408680be992', '241藝術空間 SS新銳藝術家-島嶼幻境：沉浸式動畫趙憶憫個展', '此作品透過描繪台灣各城鄉的風情與獨特符碼，構築出一個如繪本般奇幻的島嶼世界，在這個動畫作品中，一名女孩持續行走於不同的城鄉之間，每到一處便融入當地的人文掌故與景象之中，成為每段情節的見證者和連結者。她的旅程在每個場景中隨著時空的轉變而演繹出新的故事，展現出每個城市的深層底蘊，從城鎮街頭的現代氣息到鄉間小巷的傳統人情，讓觀者與之共鳴，心隨情境遷移，當女孩行走於這片虛實交織的夢境之中，她所經歷的場景不僅是她的旅程，更是每位觀者心中的情感線索。那些她走過的畫面，在觀眾腦海中化為無數記憶的拼圖，連結著各自對台灣的不同的情感與回憶。\r\n島嶼行腳Walking Island 透過創意的媒材轉譯手法，重新詮釋台灣的地方特色與文化，並探討人與環境之間的深層連結，期望這個展覽能成為觀者心中一段難忘的回憶，在有限的沉浸體驗中，得以折射出無限的情懷，細細地品味台灣的美麗與多元，靜靜地聆賞在地的風土與人情，並帶著這份感動，繼續深耕這座悠遊於婆娑之洋的美麗之島。\r\n', '新竹市文化局', '新竹市東區中央路241號6樓', '2025-03-18 00:00:00', '2025-04-20 00:00:00', '新竹市241藝術空間', 24.79028174, 120.9927505, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='241藝術空間 SS新銳藝術家-島嶼幻境：沉浸式動畫趙憶憫個展', `description`='此作品透過描繪台灣各城鄉的風情與獨特符碼，構築出一個如繪本般奇幻的島嶼世界，在這個動畫作品中，一名女孩持續行走於不同的城鄉之間，每到一處便融入當地的人文掌故與景象之中，成為每段情節的見證者和連結者。她的旅程在每個場景中隨著時空的轉變而演繹出新的故事，展現出每個城市的深層底蘊，從城鎮街頭的現代氣息到鄉間小巷的傳統人情，讓觀者與之共鳴，心隨情境遷移，當女孩行走於這片虛實交織的夢境之中，她所經歷的場景不僅是她的旅程，更是每位觀者心中的情感線索。那些她走過的畫面，在觀眾腦海中化為無數記憶的拼圖，連結著各自對台灣的不同的情感與回憶。\r\n島嶼行腳Walking Island 透過創意的媒材轉譯手法，重新詮釋台灣的地方特色與文化，並探討人與環境之間的深層連結，期望這個展覽能成為觀者心中一段難忘的回憶，在有限的沉浸體驗中，得以折射出無限的情懷，細細地品味台灣的美麗與多元，靜靜地聆賞在地的風土與人情，並帶著這份感動，繼續深耕這座悠遊於婆娑之洋的美麗之島。\r\n', `organizer`='新竹市文化局', `address`='新竹市東區中央路241號6樓', `start_date`='2025-03-18 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='新竹市241藝術空間', `latitude`=24.79028174, `longitude`=120.9927505, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2a826b32408680be993', '五洲桃興閣掌中劇團《白馬風雲傳》', '五洲桃興閣掌中劇團《白馬風雲傳》\r\n\r\n星宿海靈魂教奪走了武林密笈「天機寶鑑」並獻給了大魔頭，欲作亂武林。茶山派群雄通力合作，破了星宿海靈魂教教的大本營。\r\n以互動式演出提升觀眾參與感，強調戲偶的裝扮、臉部雕刻、彩繪等工藝，透過氣勢磅礴的配樂、五彩布巾、七彩燈光、煙霧等效果，營造臨場演出的震撼效果。', '無資料', '臺南市鹽水區過港路21號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺南市鹽水永成戲院', 23.29798622, 120.2482977, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='五洲桃興閣掌中劇團《白馬風雲傳》', `description`='五洲桃興閣掌中劇團《白馬風雲傳》\r\n\r\n星宿海靈魂教奪走了武林密笈「天機寶鑑」並獻給了大魔頭，欲作亂武林。茶山派群雄通力合作，破了星宿海靈魂教教的大本營。\r\n以互動式演出提升觀眾參與感，強調戲偶的裝扮、臉部雕刻、彩繪等工藝，透過氣勢磅礴的配樂、五彩布巾、七彩燈光、煙霧等效果，營造臨場演出的震撼效果。', `organizer`='無資料', `address`='臺南市鹽水區過港路21號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺南市鹽水永成戲院', `latitude`=23.29798622, `longitude`=120.2482977, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2a826b32408680be994', '張浮明師生書法展', '這次的展覽主題是以「道東詩社-詩書畫聯」為主題，在此次詩書畫聯展中，我們透過詩詞的含蓄、書法的瀟灑和畫作的構思，將心靈的情感與意境融合呈現。希望能夠感受到這份詩書畫的韻味與意境，共同領略中國文化的深厚底蘊，感受心靈的觸動與靈感的迸發。\r\n', '臺中市大里區公所', '臺中市大里區新興路2號', '2025-02-14 00:00:00', '2025-04-30 00:00:00', '大里杙文化館', 24.0981305, 120.67719, '無資料', 'https://www.dali.taichung.gov.tw/3596183/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='張浮明師生書法展', `description`='這次的展覽主題是以「道東詩社-詩書畫聯」為主題，在此次詩書畫聯展中，我們透過詩詞的含蓄、書法的瀟灑和畫作的構思，將心靈的情感與意境融合呈現。希望能夠感受到這份詩書畫的韻味與意境，共同領略中國文化的深厚底蘊，感受心靈的觸動與靈感的迸發。\r\n', `organizer`='臺中市大里區公所', `address`='臺中市大里區新興路2號', `start_date`='2025-02-14 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='大里杙文化館', `latitude`=24.0981305, `longitude`=120.67719, `ticket_price`='無資料', `source_url`='https://www.dali.taichung.gov.tw/3596183/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2a826b32408680be995', '大甲文昌祠甲辰圓醮攝影展', '還記得113年大甲文昌祠舉行百年來第一次的圓醮大典嗎!! 🙏🙏\r\n活動當時邀請攝影師 捕捉了各種精采畫面🎋  \r\n將於2025年2月13日至3月30日（日）📷 攝影展開展！\r\n✨ 本次展覽將呈現甲辰年二朝宿啟祈安圓醮大典113年9月3日至9月6日期間不同科儀畫面，現場並展示斗燈樣品，讓各位再次回顧，感受當時醮典的神聖及熱鬧氛圍，沒參與過的民眾也可藉此次攝影展，慢慢品味圓醮過程喔‼️\r\n📅 展覽時間：2025年2月13日（四）- 2025年3月30日（日）\r\n⏰開放時間：上午8:00至下午5:00（中午12:00-13:00休息）\r\n⛔休館日：每週一及國定假日\r\n📍 地點：大甲區中正紀念館（臺中市大甲區水源路190號）', '臺中市大甲區公所', '臺中市大甲區水源路190號', '2025-02-13 00:00:00', '2025-03-30 00:00:00', '臺中市大甲區中正紀念館', 24.37827161, 120.6357901, '無資料', 'https://www.facebook.com/share/p/1AFNT3VaZf/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大甲文昌祠甲辰圓醮攝影展', `description`='還記得113年大甲文昌祠舉行百年來第一次的圓醮大典嗎!! 🙏🙏\r\n活動當時邀請攝影師 捕捉了各種精采畫面🎋  \r\n將於2025年2月13日至3月30日（日）📷 攝影展開展！\r\n✨ 本次展覽將呈現甲辰年二朝宿啟祈安圓醮大典113年9月3日至9月6日期間不同科儀畫面，現場並展示斗燈樣品，讓各位再次回顧，感受當時醮典的神聖及熱鬧氛圍，沒參與過的民眾也可藉此次攝影展，慢慢品味圓醮過程喔‼️\r\n📅 展覽時間：2025年2月13日（四）- 2025年3月30日（日）\r\n⏰開放時間：上午8:00至下午5:00（中午12:00-13:00休息）\r\n⛔休館日：每週一及國定假日\r\n📍 地點：大甲區中正紀念館（臺中市大甲區水源路190號）', `organizer`='臺中市大甲區公所', `address`='臺中市大甲區水源路190號', `start_date`='2025-02-13 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市大甲區中正紀念館', `latitude`=24.37827161, `longitude`=120.6357901, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1AFNT3VaZf/', `image_url`='[]';
