INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b126b32408680be99a', '童武義小品展/金變堂藝術空間', '童武義老師的水彩作品有一種魔法。\r\n你知道眼前是一張水彩作品，但是可以在眼前的作品看見空氣、水氣。這是照片、Ai無法帶來的視覺感，真心推薦與歡迎到現場看原作。', '金變堂藝術空間', '新竹市東區', '2025-02-04 00:00:00', '2025-03-31 00:00:00', '東區（新竹市）=', 24.79028174, 120.9927505, '無資料', 'https://www.facebook.com/JBT.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='童武義小品展/金變堂藝術空間', `description`='童武義老師的水彩作品有一種魔法。\r\n你知道眼前是一張水彩作品，但是可以在眼前的作品看見空氣、水氣。這是照片、Ai無法帶來的視覺感，真心推薦與歡迎到現場看原作。', `organizer`='金變堂藝術空間', `address`='新竹市東區', `start_date`='2025-02-04 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='東區（新竹市）=', `latitude`=24.79028174, `longitude`=120.9927505, `ticket_price`='無資料', `source_url`='https://www.facebook.com/JBT.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b226b32408680be99b', '中山73影視114年3月:該死的阿修羅(3場)', '詹文在成年那天做了決定:讓子彈在夜市裡飛。唯一的死者是小盛；Vita接到未婚夫的死訊，社畜人生戛然而止；網路盜圖詐騙的琳琳，與記者黴菌在夜市約訪，讓他意外成了制伏兇手的證人；阿興深信摯友不是故意殺人，六人命運在夜市交錯，被迫面對生命的困境。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-03-08 00:00:00', '2025-03-20 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年3月:該死的阿修羅(3場)', `description`='詹文在成年那天做了決定:讓子彈在夜市裡飛。唯一的死者是小盛；Vita接到未婚夫的死訊，社畜人生戛然而止；網路盜圖詐騙的琳琳，與記者黴菌在夜市約訪，讓他意外成了制伏兇手的證人；阿興深信摯友不是故意殺人，六人命運在夜市交錯，被迫面對生命的困境。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-20 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b326b32408680be99c', '中山73影視114年3月:金孫爆富攻略(3場)', '小安辭去工作，回到家中照顧罹癌的阿嬤。孫子看似孝順照顧的心，其實並非出自於對阿嬤的愛。在得知朋友從阿公那裡繼承了價值千萬的房產後，他費盡千辛萬苦，博取阿嬤的信任。然而，阿嬤用智慧讓小安慢慢地學會生活，在朝夕相處下小安的心態漸漸改變。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-03-01 00:00:00', '2025-03-14 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年3月:金孫爆富攻略(3場)', `description`='小安辭去工作，回到家中照顧罹癌的阿嬤。孫子看似孝順照顧的心，其實並非出自於對阿嬤的愛。在得知朋友從阿公那裡繼承了價值千萬的房產後，他費盡千辛萬苦，博取阿嬤的信任。然而，阿嬤用智慧讓小安慢慢地學會生活，在朝夕相處下小安的心態漸漸改變。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-14 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b326b32408680be99d', '中山73影視114年3月:金魚俱樂部(3場)', '奧利佛是工作勤奮的投顧經理，但一場車禍卻讓他半身不遂。但他並不認命，在復健中心休養時，他參加了由各樣殘疾人士所組成的「金魚俱樂部」。當他發現自己在蘇黎世的非法資金快曝光時，他想到一個點子:號召這群殘疾人士前往蘇黎世，掩人耳目將鉅款偷渡出去。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-03-08 00:00:00', '2025-03-27 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年3月:金魚俱樂部(3場)', `description`='奧利佛是工作勤奮的投顧經理，但一場車禍卻讓他半身不遂。但他並不認命，在復健中心休養時，他參加了由各樣殘疾人士所組成的「金魚俱樂部」。當他發現自己在蘇黎世的非法資金快曝光時，他想到一個點子:號召這群殘疾人士前往蘇黎世，掩人耳目將鉅款偷渡出去。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-27 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b326b32408680be99e', '中山73影視114年3月:巴黎交易員(3場)', '傑宏的父親是個鍋爐工人，母親則是理髮師。頂著金融碩士頭銜的他，彷彿有彈指魔法，總能幫銀行賺進驚人的利潤，卻也逐漸沉迷於金錢遊戲。在銀行默許下，他越發大膽展開最瘋狂交易，不僅買賣金額逐步超越權限，投資金額更超乎銀行股本，導致不可收拾局面。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-03-16 00:00:00', '2025-03-29 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年3月:巴黎交易員(3場)', `description`='傑宏的父親是個鍋爐工人，母親則是理髮師。頂著金融碩士頭銜的他，彷彿有彈指魔法，總能幫銀行賺進驚人的利潤，卻也逐漸沉迷於金錢遊戲。在銀行默許下，他越發大膽展開最瘋狂交易，不僅買賣金額逐步超越權限，投資金額更超乎銀行股本，導致不可收拾局面。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b326b32408680be99f', '中山73影視114年3月:日麗(3場)', '充滿好奇心的11歲女孩蘇菲和她年輕的單身父親卡倫，一起前往碧海藍天的土耳其渡假。即將成為青少女的她，珍惜與父親難得的共處時光，那裡發生的每一件小事，更不知不覺刻畫出他們互為磐石的情感。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-03-03 00:00:00', '2025-03-16 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年3月:日麗(3場)', `description`='充滿好奇心的11歲女孩蘇菲和她年輕的單身父親卡倫，一起前往碧海藍天的土耳其渡假。即將成為青少女的她，珍惜與父親難得的共處時光，那裡發生的每一件小事，更不知不覺刻畫出他們互為磐石的情感。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-03-03 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b326b32408680be9a0', '中山73影視114年3月:七五計劃(3場)', '為解決人口老化問題，日本國會通過認可75歲以上長者享有選擇死亡權利，俗稱「七五計劃」。獨居婦人阿道，因高齡被資遣，該如何面對餘生?總是親切計劃招募公務員、照顧老人們至最後的女移工、輔導參與計劃的心理輔道員，日復一日直面生死，又將做出什麼樣的抉擇?\r\n', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-03-05 00:00:00', '2025-03-24 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年3月:七五計劃(3場)', `description`='為解決人口老化問題，日本國會通過認可75歲以上長者享有選擇死亡權利，俗稱「七五計劃」。獨居婦人阿道，因高齡被資遣，該如何面對餘生?總是親切計劃招募公務員、照顧老人們至最後的女移工、輔導參與計劃的心理輔道員，日復一日直面生死，又將做出什麼樣的抉擇?\r\n', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-24 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b326b32408680be9a1', '中山73影視114年3月:總是有個人在愛你(3場)', '單親媽媽希薇亞是個頂尖律師。忙碌的她除照顧5歲兒子，更因和難搞的母親水火不容。被診斷癌末的母親，不肯接受她任何安排，甚至拒絕化療，讓他傷透腦筋。她在法庭上所向無敵，但面對重病的母親，卻毫無招架之力。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-03-07 00:00:00', '2025-03-31 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年3月:總是有個人在愛你(3場)', `description`='單親媽媽希薇亞是個頂尖律師。忙碌的她除照顧5歲兒子，更因和難搞的母親水火不容。被診斷癌末的母親，不肯接受她任何安排，甚至拒絕化療，讓他傷透腦筋。她在法庭上所向無敵，但面對重病的母親，卻毫無招架之力。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b326b32408680be9a2', '中山73影視114年3月:快樂告別的方法(3場)', '天才發明家梅斯可，為助久病多年的好友早日脫離苦海，發明了一台「安樂死」機器，讓人們自行了結生命，沒想到竟大受歡迎。本片聚集了以色列資歷最深的演員，展現出他們淬礪人生後的精湛演技。尤其他們能百無禁忌地展現生命的熱忱，更加率直可愛。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-03-06 00:00:00', '2025-03-17 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年3月:快樂告別的方法(3場)', `description`='天才發明家梅斯可，為助久病多年的好友早日脫離苦海，發明了一台「安樂死」機器，讓人們自行了結生命，沒想到竟大受歡迎。本片聚集了以色列資歷最深的演員，展現出他們淬礪人生後的精湛演技。尤其他們能百無禁忌地展現生命的熱忱，更加率直可愛。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-03-06 00:00:00', `end_date`='2025-03-17 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
