INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b326b32408680be9a4', '中山73影視114年3月:殺夫(數位修復版)(3場)', '失去父親的年幼林市在深夜見證了母親為食物出賣身體。成長後，她從叔叔的建議嫁給屠夫江水，卻被當作性慾發洩的工具，生存與尊嚴完全受制於他。殘酷的婚姻生活、村裡的閒言碎語，和童年的創傷導致她精神崩潰，最終在江水沉睡時，拿起了屠夫的刀。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-03-02 00:00:00', '2025-03-30 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+220;愛心票+110', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年3月:殺夫(數位修復版)(3場)', `description`='失去父親的年幼林市在深夜見證了母親為食物出賣身體。成長後，她從叔叔的建議嫁給屠夫江水，卻被當作性慾發洩的工具，生存與尊嚴完全受制於他。殘酷的婚姻生活、村裡的閒言碎語，和童年的創傷導致她精神崩潰，最終在江水沉睡時，拿起了屠夫的刀。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+220;愛心票+110', `source_url`='無資料', `image_url`='[]';
