INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b326b32408680be9a6', '中山73影視114年3月:東京牛仔很忙(3場)', '身著西裝，手提公事包，穿梭在東京地鐵，他庸碌奔波於工作，正籌備著新提案:利用和牛畜牧整合計劃轉化為利潤來源。然而，煩惱不僅於此，女友擔心計畫，更對兩人的未來不知所措。遠赴異地，與他前往當地牧場的夥伴竟出了意外，他只得獨自面對眼前一切挑戰。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-03-23 00:00:00', '2025-03-30 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+220;愛心票+110', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年3月:東京牛仔很忙(3場)', `description`='身著西裝，手提公事包，穿梭在東京地鐵，他庸碌奔波於工作，正籌備著新提案:利用和牛畜牧整合計劃轉化為利潤來源。然而，煩惱不僅於此，女友擔心計畫，更對兩人的未來不知所措。遠赴異地，與他前往當地牧場的夥伴竟出了意外，他只得獨自面對眼前一切挑戰。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+220;愛心票+110', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b326b32408680be9a7', '好餓好餓的毛毛蟲創作展', '這是志工老師帶著親子們親手一個一個做出來的表演用道具，以好餓好餓的毛毛蟲這個繪本故事為背景，做出很大很長很可愛的毛毛蟲和一些繪本中的其他道具景物如房子等，創作媒材為色紙、彩色筆、漿糊、膠水、剪刀、畫筆、瓦楞紙、美工刀、蠟筆等，現於3月份在本分館大廳做舞台道具展，歡迎大家到館參觀。', '臺中市立圖書館霧峰以文分館', '臺中市霧峰區大同路8號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館霧峰以文分館', 24.0615719, 120.699002, '無資料', 'https://reurl.cc/V0bAEb', '[]') ON DUPLICATE KEY UPDATE `activity_name`='好餓好餓的毛毛蟲創作展', `description`='這是志工老師帶著親子們親手一個一個做出來的表演用道具，以好餓好餓的毛毛蟲這個繪本故事為背景，做出很大很長很可愛的毛毛蟲和一些繪本中的其他道具景物如房子等，創作媒材為色紙、彩色筆、漿糊、膠水、剪刀、畫筆、瓦楞紙、美工刀、蠟筆等，現於3月份在本分館大廳做舞台道具展，歡迎大家到館參觀。', `organizer`='臺中市立圖書館霧峰以文分館', `address`='臺中市霧峰區大同路8號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館霧峰以文分館', `latitude`=24.0615719, `longitude`=120.699002, `ticket_price`='無資料', `source_url`='https://reurl.cc/V0bAEb', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b326b32408680be9a8', '中山73影視114年3月:成為星星的少女(3場)', '東由宇立志「要當上偶像」，她的校園生活貫徹「不用社群網路媒體」、「不交男朋友」、「在學校保持低調」、「結識東西南北的美少女」高中女生為夢想付出一切的故事揭開序幕。由「乃木坂46」前成員高山一實所寫，懷抱不同情緒的少女們，為了什麼成為偶像?', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-03-05 00:00:00', '2025-03-29 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+220;愛心票+110', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年3月:成為星星的少女(3場)', `description`='東由宇立志「要當上偶像」，她的校園生活貫徹「不用社群網路媒體」、「不交男朋友」、「在學校保持低調」、「結識東西南北的美少女」高中女生為夢想付出一切的故事揭開序幕。由「乃木坂46」前成員高山一實所寫，懷抱不同情緒的少女們，為了什麼成為偶像?', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+220;愛心票+110', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b326b32408680be9a9', '中山73影視114年3月:200%小狼人(3場)', '福來弟即將繼位成為狼人家族的領袖，然而在他14歲生日第一次變身時，居然變成一隻貴賓犬，讓他美夢破碎。狼群長老給他一項任務，在明天月出之前，證明自己夠格當狼人，否則就會遭受家族放逐。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-03-01 00:00:00', '2025-03-23 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年3月:200%小狼人(3場)', `description`='福來弟即將繼位成為狼人家族的領袖，然而在他14歲生日第一次變身時，居然變成一隻貴賓犬，讓他美夢破碎。狼群長老給他一項任務，在明天月出之前，證明自己夠格當狼人，否則就會遭受家族放逐。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b526b32408680be9aa', '國立臺南大學戲劇創作與應用學系114級畢業製作《掰啦 女孩》', '《掰啦女孩》透過大量的對話和獨白，帶領觀眾進入角色韓茵錯綜複雜的內心世界。這不僅僅是一個劇團的故事，而是一場關於自我、成長與情感鬥爭的深刻旅程。更是一部層次深刻、情感激烈的作品，通過突破性的劇情設計，讓觀眾進入角色的內心世界，體驗情感的碰撞與自我探索的痛苦。', '國立臺南藝術大學', '臺南市東區榮譽街67號', '2025-03-21 00:00:00', '2025-03-30 00:00:00', '國立臺南大學(榮譽校區)', 22.98178202, 120.2281858, '票價:400元+--', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國立臺南大學戲劇創作與應用學系114級畢業製作《掰啦 女孩》', `description`='《掰啦女孩》透過大量的對話和獨白，帶領觀眾進入角色韓茵錯綜複雜的內心世界。這不僅僅是一個劇團的故事，而是一場關於自我、成長與情感鬥爭的深刻旅程。更是一部層次深刻、情感激烈的作品，通過突破性的劇情設計，讓觀眾進入角色的內心世界，體驗情感的碰撞與自我探索的痛苦。', `organizer`='國立臺南藝術大學', `address`='臺南市東區榮譽街67號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='國立臺南大學(榮譽校區)', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='票價:400元+--', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2b626b32408680be9ab', '「她．MMXXV 如是說」謝鴻均薪傳展', '「她．MMXXV 如是說」是一份關於「回應」的備忘語錄，藉由「神話/傳說」、「回音/沉默」、「諾言/召喚」三個子題交織鋪陳，反思有別於正典的知識體系下，女性拓展更多面向的發聲語境，形塑流變性的互文言說。\r\n謝鴻均以藝術家視角探究母性系譜的脈絡，透過繪畫、物件、光影與書寫，叨叨絮絮地如是說……在重複中碰撞出差異、在岐異間彰顯能動性。作品聚焦於女性創作者身分的感悟，於主體不斷變形的蒙太奇式文本，反覆咀嚼神話，再如春蠶吐絲般娓娓道來，運用帶有微光的筆觸，穿針引線，勾勒出潛藏於回音與沉默之間尚待細細品味的姿態。從線性生命始中的「我」串連至無數個「她」，並轉化為「我們」的諾言與召喚，實踐於生活日常中每個當下。', '新竹市政府', '新竹市北區中正路120號', '2025-03-18 00:00:00', '2025-05-11 00:00:00', '新竹市政府/新竹州廳', 24.82269542, 120.9491233, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「她．MMXXV 如是說」謝鴻均薪傳展', `description`='「她．MMXXV 如是說」是一份關於「回應」的備忘語錄，藉由「神話/傳說」、「回音/沉默」、「諾言/召喚」三個子題交織鋪陳，反思有別於正典的知識體系下，女性拓展更多面向的發聲語境，形塑流變性的互文言說。\r\n謝鴻均以藝術家視角探究母性系譜的脈絡，透過繪畫、物件、光影與書寫，叨叨絮絮地如是說……在重複中碰撞出差異、在岐異間彰顯能動性。作品聚焦於女性創作者身分的感悟，於主體不斷變形的蒙太奇式文本，反覆咀嚼神話，再如春蠶吐絲般娓娓道來，運用帶有微光的筆觸，穿針引線，勾勒出潛藏於回音與沉默之間尚待細細品味的姿態。從線性生命始中的「我」串連至無數個「她」，並轉化為「我們」的諾言與召喚，實踐於生活日常中每個當下。', `organizer`='新竹市政府', `address`='新竹市北區中正路120號', `start_date`='2025-03-18 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='新竹市政府/新竹州廳', `latitude`=24.82269542, `longitude`=120.9491233, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2ba26b32408680be9ac', '114年春季音樂系列講座：電影動畫配樂和它們的產地 ', '【114年春季音樂系列講座】\r\n許石音樂圖書館以《與光影交織的樂章》作為系列講座主題，介紹電影、動畫或是電視戲劇當中的配樂，「音樂」很多時候是與影像同等重要的存在，不僅具有畫龍點睛的效果，甚至極具代表性，成為讓人辨識這部作品的關鍵角色。希望藉由影像作品中的音樂賞析，配合館內典藏書籍，帶領民眾樂在其中，認識音樂的美好。⫸免費精彩活動，歡迎報名參加⫷\r\n◖講題◗ 電影動畫配樂和它們的產地 \r\n◖時間◗ 114/03/22(六) 14:00~16:30\r\n◖地點◗ 許石音樂圖書館1F黑盒子劇場\r\n◖講師◗ 周宣宏 配樂作曲家', '許石音樂圖書館', '臺南市北區公園北路3號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '許石音樂圖書館', 23.01012179, 120.2068735, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年春季音樂系列講座：電影動畫配樂和它們的產地 ', `description`='【114年春季音樂系列講座】\r\n許石音樂圖書館以《與光影交織的樂章》作為系列講座主題，介紹電影、動畫或是電視戲劇當中的配樂，「音樂」很多時候是與影像同等重要的存在，不僅具有畫龍點睛的效果，甚至極具代表性，成為讓人辨識這部作品的關鍵角色。希望藉由影像作品中的音樂賞析，配合館內典藏書籍，帶領民眾樂在其中，認識音樂的美好。⫸免費精彩活動，歡迎報名參加⫷\r\n◖講題◗ 電影動畫配樂和它們的產地 \r\n◖時間◗ 114/03/22(六) 14:00~16:30\r\n◖地點◗ 許石音樂圖書館1F黑盒子劇場\r\n◖講師◗ 周宣宏 配樂作曲家', `organizer`='許石音樂圖書館', `address`='臺南市北區公園北路3號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='許石音樂圖書館', `latitude`=23.01012179, `longitude`=120.2068735, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2bb26b32408680be9ad', '公共圖書館在地資料徵集計畫【趣讀桃園．穿越古今】系列講座：埔心眷村的意義', '公共圖書館在地資料徵集計畫講座\r\n在桃園楊梅的埔心，一個丁點大的地方，緊挨著10個眷村，超過10個軍、師和特種部隊的核心幹部，當年，他們保衛臺海，硬是將共軍頂在大陸沿海的金門、登步、大二擔等島嶼，出不了海，他們還突擊南日島、湄洲島，頂住了九三砲戰，也頂住平均每1平方公尺就落下10發砲彈的八二三砲戰。當年，他們甚至待命反攻，傳說中的《野馬計畫》、三一訓練班、《武漢計畫》、《國光計畫》就是他們的故事。', '桃園市立圖書館', '桃園市桃園區南平路303號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '桃園市立圖書館總館', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='公共圖書館在地資料徵集計畫【趣讀桃園．穿越古今】系列講座：埔心眷村的意義', `description`='公共圖書館在地資料徵集計畫講座\r\n在桃園楊梅的埔心，一個丁點大的地方，緊挨著10個眷村，超過10個軍、師和特種部隊的核心幹部，當年，他們保衛臺海，硬是將共軍頂在大陸沿海的金門、登步、大二擔等島嶼，出不了海，他們還突擊南日島、湄洲島，頂住了九三砲戰，也頂住平均每1平方公尺就落下10發砲彈的八二三砲戰。當年，他們甚至待命反攻，傳說中的《野馬計畫》、三一訓練班、《武漢計畫》、《國光計畫》就是他們的故事。', `organizer`='桃園市立圖書館', `address`='桃園市桃園區南平路303號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='桃園市立圖書館總館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2bb26b32408680be9ae', '公共圖書館在地資料徵集計畫【趣讀桃園．穿越古今】系列講座：地方文化轉譯', '公共圖書館在地資料徵集計畫講座\r\n「文化的轉譯，非一時半刻之事，唯有不斷前行，方能抵達目的地。」桃園楊梅富岡信義街上的「富富·小山岡」，1930年代老屋，前身為富岡派報社，採用「以修代租」方式承租，保留原住戶空間，青年集結力量推動地方創生，透過導覽培訓、打造品牌與店鋪策展，打造文化共榮基地。', '桃園市立圖書館', '桃園市桃園區南平路303號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '桃園市立圖書館總館', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='公共圖書館在地資料徵集計畫【趣讀桃園．穿越古今】系列講座：地方文化轉譯', `description`='公共圖書館在地資料徵集計畫講座\r\n「文化的轉譯，非一時半刻之事，唯有不斷前行，方能抵達目的地。」桃園楊梅富岡信義街上的「富富·小山岡」，1930年代老屋，前身為富岡派報社，採用「以修代租」方式承租，保留原住戶空間，青年集結力量推動地方創生，透過導覽培訓、打造品牌與店鋪策展，打造文化共榮基地。', `organizer`='桃園市立圖書館', `address`='桃園市桃園區南平路303號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='桃園市立圖書館總館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2bb26b32408680be9af', '公共圖書館在地資料徵集計畫【趣讀桃園．穿越古今】系列講座：老城之鷹－大漢溪溪谷空拍影片分享會 ', '公共圖書館在地資料徵集計畫講座\r\n集合桃園市最大溪流、華麗老街、最美溼地、唯一國定古蹟、市立博物館、獨特傳統產業等等於一身的「大漢溪溪谷」文化與環境，以24年春夏秋冬的影像紀錄介紹，加上「空拍影片」分享可以感受到「文化飛行者」的樂趣。', '桃園市立圖書館', '桃園市桃園區南平路303號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '桃園市立圖書館總館', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='公共圖書館在地資料徵集計畫【趣讀桃園．穿越古今】系列講座：老城之鷹－大漢溪溪谷空拍影片分享會 ', `description`='公共圖書館在地資料徵集計畫講座\r\n集合桃園市最大溪流、華麗老街、最美溼地、唯一國定古蹟、市立博物館、獨特傳統產業等等於一身的「大漢溪溪谷」文化與環境，以24年春夏秋冬的影像紀錄介紹，加上「空拍影片」分享可以感受到「文化飛行者」的樂趣。', `organizer`='桃園市立圖書館', `address`='桃園市桃園區南平路303號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='桃園市立圖書館總館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2bb26b32408680be9b0', '公共圖書館在地資料徵集計畫【趣讀桃園．穿越古今】系列講座：桃園老城怎麼玩？ ', '公共圖書館在地資料徵集計畫講座\r\n桃園老城區的故事與我們的文化行動\r\n桃園老城區是桃園區發展最久，文化最豐厚的地方，這裡除了有百年古蹟，也有新的店家、新的故事在這裡慢慢醞釀，讓這裡呈現獨有的氛圍，這次的講座將帶大家聽聽桃園老城區有趣的故事，以及桃托邦藝文聯盟的在地實踐，讓大家感受原來桃園老城區這麼有趣！', '桃園市立圖書館', '桃園市桃園區南平路303號', '2025-04-05 00:00:00', '2025-04-05 00:00:00', '桃園市立圖書館總館', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='公共圖書館在地資料徵集計畫【趣讀桃園．穿越古今】系列講座：桃園老城怎麼玩？ ', `description`='公共圖書館在地資料徵集計畫講座\r\n桃園老城區的故事與我們的文化行動\r\n桃園老城區是桃園區發展最久，文化最豐厚的地方，這裡除了有百年古蹟，也有新的店家、新的故事在這裡慢慢醞釀，讓這裡呈現獨有的氛圍，這次的講座將帶大家聽聽桃園老城區有趣的故事，以及桃托邦藝文聯盟的在地實踐，讓大家感受原來桃園老城區這麼有趣！', `organizer`='桃園市立圖書館', `address`='桃園市桃園區南平路303號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-05 00:00:00', `location`='桃園市立圖書館總館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2bb26b32408680be9b1', '公共圖書館在地資料徵集計畫【趣讀桃園．穿越古今】系列講座：尋找地方的不思議', '公共圖書館在地資料徵集計畫講座\r\n中壢老街及老街溪－常民生活及地方文化議題觀察\r\n1.以日常生活為起點，透過觀察，在日常生活場景中發現生活與文化的趣味。學習如何在細節中發掘創意靈感，培養敏銳的觀察力。\r\n2.以輕鬆散步的方式在街區一邊漫遊，感受城市之美，召喚出民眾對於生活空間的記憶與認同，並透過設計思考，引領參與民眾分享整理對於城市紋理的記憶及感受。', '桃園市立圖書館', '桃園市桃園區南平路303號', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '桃園市立圖書館總館', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='公共圖書館在地資料徵集計畫【趣讀桃園．穿越古今】系列講座：尋找地方的不思議', `description`='公共圖書館在地資料徵集計畫講座\r\n中壢老街及老街溪－常民生活及地方文化議題觀察\r\n1.以日常生活為起點，透過觀察，在日常生活場景中發現生活與文化的趣味。學習如何在細節中發掘創意靈感，培養敏銳的觀察力。\r\n2.以輕鬆散步的方式在街區一邊漫遊，感受城市之美，召喚出民眾對於生活空間的記憶與認同，並透過設計思考，引領參與民眾分享整理對於城市紋理的記憶及感受。', `organizer`='桃園市立圖書館', `address`='桃園市桃園區南平路303號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='桃園市立圖書館總館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2bc26b32408680be9b2', 'FUN心聽故事(中庄分館4月份)', '孩子是精靈，故事是魔法棒，點綴孩子的心，開啟孩子的夢，透過故事達人的口，故事將變成幸福的種子，灑向每個角落，讓小朋友的世界變成一座開滿五彩繽紛幸福花朵的書香城市。', '高雄市立圖書館總館', '高雄市大寮區40鄰光明路3段1437號', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '高雄市立圖書館中庄分館', 22.6285347, 120.4098142, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽故事(中庄分館4月份)', `description`='孩子是精靈，故事是魔法棒，點綴孩子的心，開啟孩子的夢，透過故事達人的口，故事將變成幸福的種子，灑向每個角落，讓小朋友的世界變成一座開滿五彩繽紛幸福花朵的書香城市。', `organizer`='高雄市立圖書館總館', `address`='高雄市大寮區40鄰光明路3段1437號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄市立圖書館中庄分館', `latitude`=22.6285347, `longitude`=120.4098142, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2be26b32408680be9b3', '製造場所現代藝術展座談—不在廠證明', '當一座曾經忙碌運轉的工廠，不再製造產品，而是轉變成展覽空間，這樣的環境，會不會影響藝術家對創作的想法？當藝術走進這樣的場域，它是與空間對話，還是成了一種「裝飾」？\r\n在三月我們即將開啟一場藝術座談，邀請了駐廠策展人與藝術家跟與談人 #李芊 一起來聊聊，當藝術存在在這樣的特殊空間裡，能夠激起什麼樣的火花。\r\n', '富興工廠1962', '臺中市東區復興路四段37巷2號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '富興工廠1962', 24.13733209, 120.6970865, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='製造場所現代藝術展座談—不在廠證明', `description`='當一座曾經忙碌運轉的工廠，不再製造產品，而是轉變成展覽空間，這樣的環境，會不會影響藝術家對創作的想法？當藝術走進這樣的場域，它是與空間對話，還是成了一種「裝飾」？\r\n在三月我們即將開啟一場藝術座談，邀請了駐廠策展人與藝術家跟與談人 #李芊 一起來聊聊，當藝術存在在這樣的特殊空間裡，能夠激起什麼樣的火花。\r\n', `organizer`='富興工廠1962', `address`='臺中市東區復興路四段37巷2號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='富興工廠1962', `latitude`=24.13733209, `longitude`=120.6970865, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c126b32408680be9b4', '114年上半年小蜻蜓兒童讀書會', '爲發揮公共圖書館既有圖書資源，推動社區閱讀，讓孩童在同儕學習的模式，體驗閱讀的樂趣，培養小小閱讀種子，提升社區閱讀風氣。\r\n導讀繪本書單：變色龍不變色、無佮意、大象林旺是怎麼到動物園?、虎姑婆。\r\n活動日期：3/8、3/15、3/21、3/29，下午13:30~16:30。\r\n課程對象：國小3-4年級，每場限20名。\r\n活動費用:完全免費。\r\n報名方式:親自或委託他人至鳳二分館櫃台辦理。', '高雄市立圖書館總館', '高雄市鳳山區7鄰自強一路119巷75號', '2025-03-08 00:00:00', '2025-03-29 00:00:00', '高雄市立圖書館鳳山二館', 22.589421, 120.3273098, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年上半年小蜻蜓兒童讀書會', `description`='爲發揮公共圖書館既有圖書資源，推動社區閱讀，讓孩童在同儕學習的模式，體驗閱讀的樂趣，培養小小閱讀種子，提升社區閱讀風氣。\r\n導讀繪本書單：變色龍不變色、無佮意、大象林旺是怎麼到動物園?、虎姑婆。\r\n活動日期：3/8、3/15、3/21、3/29，下午13:30~16:30。\r\n課程對象：國小3-4年級，每場限20名。\r\n活動費用:完全免費。\r\n報名方式:親自或委託他人至鳳二分館櫃台辦理。', `organizer`='高雄市立圖書館總館', `address`='高雄市鳳山區7鄰自強一路119巷75號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='高雄市立圖書館鳳山二館', `latitude`=22.589421, `longitude`=120.3273098, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c326b32408680be9b5', '2025青春美展國立屏東大學 視覺藝術學系114級畢業展【吹夢者】『Dream Weaver』', '《吹夢者》象徵著熱愛創作的我們，各自懷抱著夢想，躍躍欲試想將其具象化。而編織出「夢」的大小、形狀等等的不同，表示了我們即使懷揣著相似的理想，但會因著每個人不同的經歷，進而展示出與眾不同的獨特性。\r\n此次展覽包含了西畫、立體造型作品等多方面進行，以展示多樣化及同學對在學專長的熱忱。並同時進行周邊商品的設計及製作，讓同學擁有宣傳自身作品的經驗，也讓參與的客人能透過文宣品，更理解作品其中涵義及製作過程的精彩之處。\r\n', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-05-16 00:00:00', '2025-05-27 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4098', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展國立屏東大學 視覺藝術學系114級畢業展【吹夢者】『Dream Weaver』', `description`='《吹夢者》象徵著熱愛創作的我們，各自懷抱著夢想，躍躍欲試想將其具象化。而編織出「夢」的大小、形狀等等的不同，表示了我們即使懷揣著相似的理想，但會因著每個人不同的經歷，進而展示出與眾不同的獨特性。\r\n此次展覽包含了西畫、立體造型作品等多方面進行，以展示多樣化及同學對在學專長的熱忱。並同時進行周邊商品的設計及製作，讓同學擁有宣傳自身作品的經驗，也讓參與的客人能透過文宣品，更理解作品其中涵義及製作過程的精彩之處。\r\n', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-16 00:00:00', `end_date`='2025-05-27 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4098', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c426b32408680be9b6', '【性別符號】│出租老爸', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│出租老爸\r\n英文片│Dad for Rent\r\n\r\n導演│金德秀\r\n韓國│2014│普遍級│劇情類│彩色│韓語│112分鐘\r\n\r\n簡介\r\n某天雅英再也看不下去，靈機一動開始在二手物品交易網上刊登「租借爸爸」的訊息，要想辦法讓這個沒用的爸爸好好振作。她也把爸爸帶到學校的物品分享日上大聲宣布：我要把爸爸拿出來交換！意外造成不小的騷動。在這之後泰萬的手機開始接到各種想來「租借爸爸」的電話和訊息，沒想到這門生意居然開始發展壯大，激發了泰萬想要努力工作的決心，也因為這份工作讓他們遇見了各式各樣需要「爸爸」的人…。', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-03-21 00:00:00', '2025-03-21 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【性別符號】│出租老爸', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│出租老爸\r\n英文片│Dad for Rent\r\n\r\n導演│金德秀\r\n韓國│2014│普遍級│劇情類│彩色│韓語│112分鐘\r\n\r\n簡介\r\n某天雅英再也看不下去，靈機一動開始在二手物品交易網上刊登「租借爸爸」的訊息，要想辦法讓這個沒用的爸爸好好振作。她也把爸爸帶到學校的物品分享日上大聲宣布：我要把爸爸拿出來交換！意外造成不小的騷動。在這之後泰萬的手機開始接到各種想來「租借爸爸」的電話和訊息，沒想到這門生意居然開始發展壯大，激發了泰萬想要努力工作的決心，也因為這份工作讓他們遇見了各式各樣需要「爸爸」的人…。', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c426b32408680be9b7', '【性別符號】│零距離', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│零距離\r\n英文片│Distance\r\n\r\n導演│吳韋樵\r\n臺灣│2011│普遍級│紀錄類│彩色│華語│45分鐘\r\n\r\n簡介\r\n本片真實紀錄四位女大學生單車環島15天的挑戰,這個挑戰不是路途的遙遠或身體的勞累,而是家人的耽心與反對.在父母的眼中,似乎永遠沒有長大的孩子.這群勇敢的女孩,帶著家人的反對與祝福,展開一場出發追尋與重新回家的夢想旅程.一場單車環島之旅,她們完成了夢想,感受到家人的愛.特別是,女孩們環島經過家門時,每一個家庭給予的支持與溫暖,都是最純粹的親情.放心去飛吧!你會發現,當實現夢想時,家人都在背後默默支持你;你會發現"家"原來是這麼的近.', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【性別符號】│零距離', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│零距離\r\n英文片│Distance\r\n\r\n導演│吳韋樵\r\n臺灣│2011│普遍級│紀錄類│彩色│華語│45分鐘\r\n\r\n簡介\r\n本片真實紀錄四位女大學生單車環島15天的挑戰,這個挑戰不是路途的遙遠或身體的勞累,而是家人的耽心與反對.在父母的眼中,似乎永遠沒有長大的孩子.這群勇敢的女孩,帶著家人的反對與祝福,展開一場出發追尋與重新回家的夢想旅程.一場單車環島之旅,她們完成了夢想,感受到家人的愛.特別是,女孩們環島經過家門時,每一個家庭給予的支持與溫暖,都是最純粹的親情.放心去飛吧!你會發現,當實現夢想時,家人都在背後默默支持你;你會發現"家"原來是這麼的近.', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c526b32408680be9b8', '感受肢體的平衡與失衡---《人之島》肢體工作坊', '感受肢體的平衡與失衡---《人之島》肢體工作坊\r\n離開生長的島嶼時，是否疑惑過「我是誰?」、「如何證明我來自哪裡?」\r\n\r\n踏上《人之島》的你將會明白，原來經歷失衡之後，才能重新找回平衡。\r\n\r\n此工作坊將由《人之島》舞者之一的王宇光帶領大家透過肢體的探索，感受失衡與平衡的拉扯、感受自我內在的絮語。\r\n\r\n \r\n\r\n  活動及報名資訊  \r\n\r\n活動時間：3/9(日) 10:30-12:00\r\n\r\n參加對象：歡迎喜愛藝術活動、對於探索肢體或舞蹈有興趣的朋友，一起來參與！ \r\n\r\n報名時間：即日起至3/5(三)18:00止（限量30名，額滿為止）\r\n\r\n報名流程：官網報名（一組帳號僅可報名一次）→檢視官網報名狀況→完成報名。\r\n\r\n活動地點：衛武營 排練室1192\r\n \r\n\r\n  主講人  \r\n\r\n微光製造 藝術總監｜王宇光 \r\n\r\n編舞家王宇光曾獲日本橫濱舞蹈節暨舞蹈大賽雙獎肯定，也是首位入圍英國沙德勒之井劇院「國際玫瑰舞蹈獎」新興編舞家決選的臺灣編舞家，其作品《人之島》2022 年於臺灣舞蹈平台發表前期創作《去你的島》，獲 FACP 亞洲文化推展聯盟雙獎肯定，今年大勢入圍台新藝術獎，展現其獨特的藝術視角與舞蹈能量。\r\n\r\n \r\n\r\n  節目資訊  \r\n\r\n3/22(六)、3/23(日)14:30\r\n\r\n►微光製造 王宇光《人之島》', '國家表演藝術中心衛武營國家藝術文化中心', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='感受肢體的平衡與失衡---《人之島》肢體工作坊', `description`='感受肢體的平衡與失衡---《人之島》肢體工作坊\r\n離開生長的島嶼時，是否疑惑過「我是誰?」、「如何證明我來自哪裡?」\r\n\r\n踏上《人之島》的你將會明白，原來經歷失衡之後，才能重新找回平衡。\r\n\r\n此工作坊將由《人之島》舞者之一的王宇光帶領大家透過肢體的探索，感受失衡與平衡的拉扯、感受自我內在的絮語。\r\n\r\n \r\n\r\n  活動及報名資訊  \r\n\r\n活動時間：3/9(日) 10:30-12:00\r\n\r\n參加對象：歡迎喜愛藝術活動、對於探索肢體或舞蹈有興趣的朋友，一起來參與！ \r\n\r\n報名時間：即日起至3/5(三)18:00止（限量30名，額滿為止）\r\n\r\n報名流程：官網報名（一組帳號僅可報名一次）→檢視官網報名狀況→完成報名。\r\n\r\n活動地點：衛武營 排練室1192\r\n \r\n\r\n  主講人  \r\n\r\n微光製造 藝術總監｜王宇光 \r\n\r\n編舞家王宇光曾獲日本橫濱舞蹈節暨舞蹈大賽雙獎肯定，也是首位入圍英國沙德勒之井劇院「國際玫瑰舞蹈獎」新興編舞家決選的臺灣編舞家，其作品《人之島》2022 年於臺灣舞蹈平台發表前期創作《去你的島》，獲 FACP 亞洲文化推展聯盟雙獎肯定，今年大勢入圍台新藝術獎，展現其獨特的藝術視角與舞蹈能量。\r\n\r\n \r\n\r\n  節目資訊  \r\n\r\n3/22(六)、3/23(日)14:30\r\n\r\n►微光製造 王宇光《人之島》', `organizer`='國家表演藝術中心衛武營國家藝術文化中心', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c526b32408680be9b9', '從流浪者計畫到一支舞蹈的誕生---《人之島》的身體漂泊之旅', '從流浪者計畫到一支舞蹈的誕生---《人之島》的身體漂泊之旅\r\n從流浪者計畫中想要釣到一條跟自己一樣重的魚啟程，王宇光前往東南方島國--印尼，與印尼舞蹈家 Danang Pamungkas 以身體和生命體驗展開對話交流。在《人之島》這趟漂泊之旅中，踏訪了許多地方：印尼、英國、日本，最後回到了臺灣。這些身體在不同國家間的軌跡，一一化做創作中的無數細節，在每段音樂、每個舞蹈動作、每道燈光中。王宇光將帶領大家穿梭在這段旅程，揭密隱藏在《人之島》中關於自我、關於夥伴、關於島嶼的故事。\r\n\r\n\r\n  活動及報名資訊    \r\n\r\n活動時間：3/8(六)14:00-16:00\r\n\r\n參加對象：歡迎喜愛藝術活動，對於創作幕後故事有興趣者報名！ \r\n\r\n報名時間：即日起至3/5(三)18:00止（限量100名，額滿為止）\r\n\r\n報名流程：官網報名（一組帳號僅可報名一次）→檢視官網報名狀況→完成報名。\r\n活動地點：衛武營 演講廳\r\n \r\n\r\n  主講人  \r\n\r\n微光製造 藝術總監｜王宇光 \r\n\r\n編舞家王宇光曾獲日本橫濱舞蹈節暨舞蹈大賽雙獎肯定，也是首位入圍英國沙德勒之井劇院「國際玫瑰舞蹈獎」新興編舞家決選的臺灣編舞家，其作品《人之島》2022 年於臺灣舞蹈平台發表前期創作《去你的島》，獲 FACP 亞洲文化推展聯盟雙獎肯定，今年大勢入圍台新藝術獎，展現其獨特的藝術視角與舞蹈能量。\r\n\r\n \r\n\r\n  節目資訊  \r\n\r\n3/22(六)、3/23(日)14:30\r\n\r\n►微光製造 王宇光《人之島》', '國家表演藝術中心衛武營國家藝術文化中心', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='從流浪者計畫到一支舞蹈的誕生---《人之島》的身體漂泊之旅', `description`='從流浪者計畫到一支舞蹈的誕生---《人之島》的身體漂泊之旅\r\n從流浪者計畫中想要釣到一條跟自己一樣重的魚啟程，王宇光前往東南方島國--印尼，與印尼舞蹈家 Danang Pamungkas 以身體和生命體驗展開對話交流。在《人之島》這趟漂泊之旅中，踏訪了許多地方：印尼、英國、日本，最後回到了臺灣。這些身體在不同國家間的軌跡，一一化做創作中的無數細節，在每段音樂、每個舞蹈動作、每道燈光中。王宇光將帶領大家穿梭在這段旅程，揭密隱藏在《人之島》中關於自我、關於夥伴、關於島嶼的故事。\r\n\r\n\r\n  活動及報名資訊    \r\n\r\n活動時間：3/8(六)14:00-16:00\r\n\r\n參加對象：歡迎喜愛藝術活動，對於創作幕後故事有興趣者報名！ \r\n\r\n報名時間：即日起至3/5(三)18:00止（限量100名，額滿為止）\r\n\r\n報名流程：官網報名（一組帳號僅可報名一次）→檢視官網報名狀況→完成報名。\r\n活動地點：衛武營 演講廳\r\n \r\n\r\n  主講人  \r\n\r\n微光製造 藝術總監｜王宇光 \r\n\r\n編舞家王宇光曾獲日本橫濱舞蹈節暨舞蹈大賽雙獎肯定，也是首位入圍英國沙德勒之井劇院「國際玫瑰舞蹈獎」新興編舞家決選的臺灣編舞家，其作品《人之島》2022 年於臺灣舞蹈平台發表前期創作《去你的島》，獲 FACP 亞洲文化推展聯盟雙獎肯定，今年大勢入圍台新藝術獎，展現其獨特的藝術視角與舞蹈能量。\r\n\r\n \r\n\r\n  節目資訊  \r\n\r\n3/22(六)、3/23(日)14:30\r\n\r\n►微光製造 王宇光《人之島》', `organizer`='國家表演藝術中心衛武營國家藝術文化中心', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c526b32408680be9ba', '兒童繪本書展：很久很久以前', '藉由兒童繪本書展的方式傳遞歷史故事，引起兒童對於歷史故事的興趣，在豐富多彩的故事中，不僅獲得閱讀的快樂，也能對歷史產生更深刻的理解和興趣，引導兒童們更好地理解和學習歷史。', '高雄市立圖書館總館', '高雄市旗山區大德里6鄰中學路42號', '2025-03-14 00:00:00', '2025-04-30 00:00:00', '高雄市立圖書館旗山分館', 25.0421407, 121.5198716, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='兒童繪本書展：很久很久以前', `description`='藉由兒童繪本書展的方式傳遞歷史故事，引起兒童對於歷史故事的興趣，在豐富多彩的故事中，不僅獲得閱讀的快樂，也能對歷史產生更深刻的理解和興趣，引導兒童們更好地理解和學習歷史。', `organizer`='高雄市立圖書館總館', `address`='高雄市旗山區大德里6鄰中學路42號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市立圖書館旗山分館', `latitude`=25.0421407, `longitude`=121.5198716, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c626b32408680be9bb', '說說唱唱-陪寶貝讀繪本', '04/05 馬鈴薯村的可樂餅慶典、世界第一長的圍巾、猜一猜我喜歡吃什麼? /林月娥、范秀盈老師帶領\r\n04/06 我是霸王龍、野貓軍團飛上天、第七位客人/孫路得、林月娥老師帶領\r\n04/11 一起玩、五個黃金罈子、九層之家/周紫蓉、黃美芳老師帶領\r\n04/12 報恩的老鼠、不想告訴媽媽的祕密、猴與龜/陳玲月、葉惠喜、孫若薇老師帶領\r\n04/13 不想開花的高麗菜、我要吃掉你、不會寫字的獅子/楊秀貞、李素榮老師帶領\r\n04/18 布利不要再生氣、阿吉的魔法紅球、阿寶的生日禮物/古馨如、梁台玲、呂淑貞老師帶領\r\n04/19 狐假虎威、月亮，你好嗎?、我不怕，我再試試看/范秀盈、陳玲月、熊筱薇老師帶領\r\n04/20 小蛇散步、躱貓貓真好玩、酪梨很想問：我是水果還是蔬菜？/孫路得、楊秀貞老師帶領\r\n04/25 小桃妹、小彌的奇幻之旅、獅子變小了?/張美君、周紫蓉老師帶領\r\n04/26 我想要養一隻獅子、感冒的魚、動物大派對 /丘淑芳、葉惠喜老師帶領\r\n04/27 嘟嘟嘟、鴨子家族大搬家、小鵪鶉捉迷藏/李素榮、陳秀和、熊筱薇老師帶領\r\n', '高雄市立圖書館總館', '高雄市鼓山區4鄰鼓山三路19-3號', '2025-04-05 00:00:00', '2025-04-27 00:00:00', '高雄市立圖書館鼓山分館', 22.6544722, 120.275386, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='說說唱唱-陪寶貝讀繪本', `description`='04/05 馬鈴薯村的可樂餅慶典、世界第一長的圍巾、猜一猜我喜歡吃什麼? /林月娥、范秀盈老師帶領\r\n04/06 我是霸王龍、野貓軍團飛上天、第七位客人/孫路得、林月娥老師帶領\r\n04/11 一起玩、五個黃金罈子、九層之家/周紫蓉、黃美芳老師帶領\r\n04/12 報恩的老鼠、不想告訴媽媽的祕密、猴與龜/陳玲月、葉惠喜、孫若薇老師帶領\r\n04/13 不想開花的高麗菜、我要吃掉你、不會寫字的獅子/楊秀貞、李素榮老師帶領\r\n04/18 布利不要再生氣、阿吉的魔法紅球、阿寶的生日禮物/古馨如、梁台玲、呂淑貞老師帶領\r\n04/19 狐假虎威、月亮，你好嗎?、我不怕，我再試試看/范秀盈、陳玲月、熊筱薇老師帶領\r\n04/20 小蛇散步、躱貓貓真好玩、酪梨很想問：我是水果還是蔬菜？/孫路得、楊秀貞老師帶領\r\n04/25 小桃妹、小彌的奇幻之旅、獅子變小了?/張美君、周紫蓉老師帶領\r\n04/26 我想要養一隻獅子、感冒的魚、動物大派對 /丘淑芳、葉惠喜老師帶領\r\n04/27 嘟嘟嘟、鴨子家族大搬家、小鵪鶉捉迷藏/李素榮、陳秀和、熊筱薇老師帶領\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市鼓山區4鄰鼓山三路19-3號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='高雄市立圖書館鼓山分館', `latitude`=22.6544722, `longitude`=120.275386, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c726b32408680be9bc', '3月高雄市電影館｜高雄拍學院—追逐電影的創作力', '先是影迷，才是電影人！\r\n\r\n金獎大師 X 專業影人  一起嗑爆電影！\r\n\r\n金獎大師喜歡什麼樣的電影？從電影人眼中看到的電影是否別有風味？3月高雄拍學院邀請2位重量級大師，由專業影人引領大師對談，帶領大家從「導演」與「編劇」視角感受光影藝術的無限魅力。與創作者一同品讀電影世界的奇妙與深度！\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n講堂內容：\r\n\r\n▌03/16(日)13:30-18:00追逐電影的創作力\r\n\r\n講師：蕭雅全/金馬最佳劇情片《老狐狸》導演\r\n\r\n主持人：鄭秉泓/影評人\r\n\r\n \r\n\r\n▌03/30(日)13:30-18:00執筆寫執念：從影迷走入創作世界 \r\n\r\n講師：林冠慧/金鐘戲劇節目編劇獎《不良執念清除師》編劇\r\n\r\n主持人：鄭秉泓/影評人\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n課程資訊：\r\n\r\n單日票原價360元／影友優惠票288元（進場請出示有效影友卡）／高中生優惠票180元（進場請出示有效學生證）\r\n早鳥優惠套票限量開賣，完整參與2025高雄拍學院！購票請點此\r\n講堂地點：高雄市電影館三樓放映廳（自由入座）\r\n購票請至高雄市電影館1F服務台、內惟藝術中心服務台、年代售票網站（郵寄、便利商店取票）、四大超商機台\r\n每堂課皆須憑票入場，請務必妥善保存票券\r\n \r\n\r\n \r\n\r\n \r\n\r\n注意事項：\r\n\r\n每場課程均未供餐，請學員自行安排。\r\n本課程所有內容禁止私人錄音錄影、平面攝影等，及任何形式之轉載公開。\r\n購票後欲退出課程，請參考「電影館官網＞節目資訊＞票務資訊 票務Q&A＞Q3：請問如何退票？辦理─退票須於開課前30分鐘至高雄市電影館一樓售票處臨櫃辦理，並酌收票面金額10％之手續費。各場次開課後恕不接受退票。\r\n若遇不可抗力之因素（如：天災），電影館保留修改、變更、暫停、取消課程之權利。學員若無法配合，得根據變動之課程申請全額退費。\r\n如不可抗因素致演出取消，購票者同意依據主辦方制定退票規則辦理。\r\n電影館保有活動最終解釋權。', '高雄市電影館', '高雄市鹽埕區4鄰河西路10號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '高雄市電影館', 22.622671, 120.289122, '高中生優惠票+180;影友優惠票+288;單日票原價+360;早鳥套票+1750', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月高雄市電影館｜高雄拍學院—追逐電影的創作力', `description`='先是影迷，才是電影人！\r\n\r\n金獎大師 X 專業影人  一起嗑爆電影！\r\n\r\n金獎大師喜歡什麼樣的電影？從電影人眼中看到的電影是否別有風味？3月高雄拍學院邀請2位重量級大師，由專業影人引領大師對談，帶領大家從「導演」與「編劇」視角感受光影藝術的無限魅力。與創作者一同品讀電影世界的奇妙與深度！\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n講堂內容：\r\n\r\n▌03/16(日)13:30-18:00追逐電影的創作力\r\n\r\n講師：蕭雅全/金馬最佳劇情片《老狐狸》導演\r\n\r\n主持人：鄭秉泓/影評人\r\n\r\n \r\n\r\n▌03/30(日)13:30-18:00執筆寫執念：從影迷走入創作世界 \r\n\r\n講師：林冠慧/金鐘戲劇節目編劇獎《不良執念清除師》編劇\r\n\r\n主持人：鄭秉泓/影評人\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n課程資訊：\r\n\r\n單日票原價360元／影友優惠票288元（進場請出示有效影友卡）／高中生優惠票180元（進場請出示有效學生證）\r\n早鳥優惠套票限量開賣，完整參與2025高雄拍學院！購票請點此\r\n講堂地點：高雄市電影館三樓放映廳（自由入座）\r\n購票請至高雄市電影館1F服務台、內惟藝術中心服務台、年代售票網站（郵寄、便利商店取票）、四大超商機台\r\n每堂課皆須憑票入場，請務必妥善保存票券\r\n \r\n\r\n \r\n\r\n \r\n\r\n注意事項：\r\n\r\n每場課程均未供餐，請學員自行安排。\r\n本課程所有內容禁止私人錄音錄影、平面攝影等，及任何形式之轉載公開。\r\n購票後欲退出課程，請參考「電影館官網＞節目資訊＞票務資訊 票務Q&A＞Q3：請問如何退票？辦理─退票須於開課前30分鐘至高雄市電影館一樓售票處臨櫃辦理，並酌收票面金額10％之手續費。各場次開課後恕不接受退票。\r\n若遇不可抗力之因素（如：天災），電影館保留修改、變更、暫停、取消課程之權利。學員若無法配合，得根據變動之課程申請全額退費。\r\n如不可抗因素致演出取消，購票者同意依據主辦方制定退票規則辦理。\r\n電影館保有活動最終解釋權。', `organizer`='高雄市電影館', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='高中生優惠票+180;影友優惠票+288;單日票原價+360;早鳥套票+1750', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c726b32408680be9be', '采實姐姐說故事《屁屁魚》/誠品書局新竹巨城店', '時間｜3／09（日）3：30pm─4：00pm\r\n地點｜誠品新竹巨城店 5F兒童館\r\n★ 我們長得不一樣，但是我們都很棒！★\r\n屁屁魚有顆像屁屁的頭，大家都為此嘲笑他。\r\n他最好的朋友，是一隻長得像切塊起司的魚。\r\n「救命啊！」被漁夫抓到的他們，能夠逃離大危機嗎？\r\n主　　講｜采實姐姐\r\n適讀年齡｜3-6歲親子共讀，6歲以上自己閱讀\r\n主辦單位｜采實文化\r\n', '采實文化', '新竹市東區', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '東區（新竹市）=', 24.79028174, 120.9927505, '無資料', 'https://www.facebook.com/events/627528769864121', '[]') ON DUPLICATE KEY UPDATE `activity_name`='采實姐姐說故事《屁屁魚》/誠品書局新竹巨城店', `description`='時間｜3／09（日）3：30pm─4：00pm\r\n地點｜誠品新竹巨城店 5F兒童館\r\n★ 我們長得不一樣，但是我們都很棒！★\r\n屁屁魚有顆像屁屁的頭，大家都為此嘲笑他。\r\n他最好的朋友，是一隻長得像切塊起司的魚。\r\n「救命啊！」被漁夫抓到的他們，能夠逃離大危機嗎？\r\n主　　講｜采實姐姐\r\n適讀年齡｜3-6歲親子共讀，6歲以上自己閱讀\r\n主辦單位｜采實文化\r\n', `organizer`='采實文化', `address`='新竹市東區', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='東區（新竹市）=', `latitude`=24.79028174, `longitude`=120.9927505, `ticket_price`='無資料', `source_url`='https://www.facebook.com/events/627528769864121', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c726b32408680be9bf', '《吉娃娃入侵地球計畫》新書分享會/誠品書局新竹巨城店', '時間｜3／16（日）2：30pm─3：30pm\r\n地點｜誠品新竹巨城店 5F閱讀書區\r\n主講｜尼爾森式症（本書作者及繪者）\r\n奇異夢境困擾著吉爾森，他發現眼前這些「吉化名畫」並非巧合，而是來自邪神吉娃娃的腦控之力——牠暗中操控人類文明，密謀全面入侵。隨著真相揭露，他驚覺早已陷入吉娃娃的陰謀之中……\r\n主辦單位｜燈籠出版\r\n活動報名｜https://forms.gle/7dShBu277fCqV1WW6\r\n', '誠品書店新竹SOGO店', '新竹市東區', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '東區（新竹市）=', 24.79028174, 120.9927505, '無資料', 'https://www.facebook.com/events/1341380210510903', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《吉娃娃入侵地球計畫》新書分享會/誠品書局新竹巨城店', `description`='時間｜3／16（日）2：30pm─3：30pm\r\n地點｜誠品新竹巨城店 5F閱讀書區\r\n主講｜尼爾森式症（本書作者及繪者）\r\n奇異夢境困擾著吉爾森，他發現眼前這些「吉化名畫」並非巧合，而是來自邪神吉娃娃的腦控之力——牠暗中操控人類文明，密謀全面入侵。隨著真相揭露，他驚覺早已陷入吉娃娃的陰謀之中……\r\n主辦單位｜燈籠出版\r\n活動報名｜https://forms.gle/7dShBu277fCqV1WW6\r\n', `organizer`='誠品書店新竹SOGO店', `address`='新竹市東區', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='東區（新竹市）=', `latitude`=24.79028174, `longitude`=120.9927505, `ticket_price`='無資料', `source_url`='https://www.facebook.com/events/1341380210510903', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c726b32408680be9c0', '《台灣美聲~從愛上唱歌到站上舞台的過程》新書分享會/誠品書局新竹巨城店', '時間｜3／22（六）2：30pm─3：30pm\r\n地點｜誠品新竹巨城店 5F閱讀書區\r\n主持｜曾心怡 (本書作者）\r\n來賓｜林玲慧老師、羅俊穎老師、張殷齊老師\r\n愛唱歌，想唱歌給大家聽，但是要怎樣才能站上舞台呢？前輩們又是經歷多少挫折與辛苦才能站在舞台唱出台灣美聲？讓這本書來為您解答。\r\n主辦單位｜相信夢想藝術經紀有限公司\r\n活動報名｜https://www.accupass.com/go/TaiwanBelCanto_HC​', '相信夢想藝術經紀有限公司', '新竹市東區', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '東區（新竹市）=', 24.79028174, 120.9927505, '無資料', 'https://www.facebook.com/events/1185810739916639', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《台灣美聲~從愛上唱歌到站上舞台的過程》新書分享會/誠品書局新竹巨城店', `description`='時間｜3／22（六）2：30pm─3：30pm\r\n地點｜誠品新竹巨城店 5F閱讀書區\r\n主持｜曾心怡 (本書作者）\r\n來賓｜林玲慧老師、羅俊穎老師、張殷齊老師\r\n愛唱歌，想唱歌給大家聽，但是要怎樣才能站上舞台呢？前輩們又是經歷多少挫折與辛苦才能站在舞台唱出台灣美聲？讓這本書來為您解答。\r\n主辦單位｜相信夢想藝術經紀有限公司\r\n活動報名｜https://www.accupass.com/go/TaiwanBelCanto_HC​', `organizer`='相信夢想藝術經紀有限公司', `address`='新竹市東區', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='東區（新竹市）=', `latitude`=24.79028174, `longitude`=120.9927505, `ticket_price`='無資料', `source_url`='https://www.facebook.com/events/1185810739916639', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c926b32408680be9c2', 'FUN心聽說故事', '繪本是講究視覺效果的兒童文學作品，本活動邀請兒童繪本專業講師引導孩子藉由繪本領受其中豐富的面貌與所要傳達的意義，讓孩子感受生命的快樂與力量，也是能讓成人恢復青春活力，提升親子之間的感情，同時引導孩子從繪本閱讀進入文字閱讀。', '高雄市立圖書館總館', '高雄市梓官區4鄰梓官路263號', '2025-03-15 00:00:00', '2025-03-29 00:00:00', '高雄市立圖書館梓官分館', 22.7615972, 120.2669499, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽說故事', `description`='繪本是講究視覺效果的兒童文學作品，本活動邀請兒童繪本專業講師引導孩子藉由繪本領受其中豐富的面貌與所要傳達的意義，讓孩子感受生命的快樂與力量，也是能讓成人恢復青春活力，提升親子之間的感情，同時引導孩子從繪本閱讀進入文字閱讀。', `organizer`='高雄市立圖書館總館', `address`='高雄市梓官區4鄰梓官路263號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='高雄市立圖書館梓官分館', `latitude`=22.7615972, `longitude`=120.2669499, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
