INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c926b32408680be9c4', '「尋味東南亞~走進伊斯蘭文化」--東南亞主題書展', ' 什麼是【清真認證】、【清真寺】、【回教】、事【清真認證】、【清真寺】、【回教】....?\r\n 伊斯蘭文化，既熟悉又陌生，似乎和伊斯蘭婦女的面紗一樣，朦朧又神秘。透過館藏閱讀，走進伊斯蘭世界。\r\n', '高雄市立圖書館總館', '高雄市彌陀區14鄰四維路一之一號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館彌陀分館', 22.7832231, 120.2455033, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「尋味東南亞~走進伊斯蘭文化」--東南亞主題書展', `description`=' 什麼是【清真認證】、【清真寺】、【回教】、事【清真認證】、【清真寺】、【回教】....?\r\n 伊斯蘭文化，既熟悉又陌生，似乎和伊斯蘭婦女的面紗一樣，朦朧又神秘。透過館藏閱讀，走進伊斯蘭世界。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市彌陀區14鄰四維路一之一號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館彌陀分館', `latitude`=22.7832231, `longitude`=120.2455033, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2ca26b32408680be9c5', '114年3〜4月—漫墨逍遙—鷺洲書畫會聯展', '「漫墨逍遙」，傳達藝術家們在創作時隨興所至於逍遙天地的樣貌，同時亦表達樂藝者在創作與創作之間逍遙自在的內在神往。\r\n此次展覽之書畫有50餘件作品，件件作品韻致超逸、氣度曠遠且契冥自然，十足展現藝術家們的創作神思，由衷冀盼喜愛藝術的先進與志友們蒞臨參觀。\r\n', '新北市鷺洲書畫會', '臺北市信義區松仁路3號', '2025-03-03 00:00:00', '2025-04-29 00:00:00', '臺灣中油股份有限公司大樓', 25.03062083, 121.5716697, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年3〜4月—漫墨逍遙—鷺洲書畫會聯展', `description`='「漫墨逍遙」，傳達藝術家們在創作時隨興所至於逍遙天地的樣貌，同時亦表達樂藝者在創作與創作之間逍遙自在的內在神往。\r\n此次展覽之書畫有50餘件作品，件件作品韻致超逸、氣度曠遠且契冥自然，十足展現藝術家們的創作神思，由衷冀盼喜愛藝術的先進與志友們蒞臨參觀。\r\n', `organizer`='新北市鷺洲書畫會', `address`='臺北市信義區松仁路3號', `start_date`='2025-03-03 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='臺灣中油股份有限公司大樓', `latitude`=25.03062083, `longitude`=121.5716697, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2ca26b32408680be9c6', '新興民眾閱覽室114年3月FUN心聽故事', '由故事媽媽藉由繪本講故事給孩童聽，讓孩童對書本產生閱讀興趣，帶領活動，手腦並用，啟發智慧。\r\n', '高雄市立圖書館總館', '高雄市新興區6鄰民生一路271號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '高雄市立圖書館新興民眾閱覽室', 22.6272175, 120.3068429, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新興民眾閱覽室114年3月FUN心聽故事', `description`='由故事媽媽藉由繪本講故事給孩童聽，讓孩童對書本產生閱讀興趣，帶領活動，手腦並用，啟發智慧。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市新興區6鄰民生一路271號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='高雄市立圖書館新興民眾閱覽室', `latitude`=22.6272175, `longitude`=120.3068429, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2ca26b32408680be9c7', '寶島台語囡仔古', '由寶島台語囡仔古社團的故事志工為親子們說演台語故事，並加入延伸的手作活動。\r\n繪本：蛀齒蟲 tāi chiàn 牙槽王\r\n      (蛀牙蟲大戰牙槽王)\r\n', '高雄市立圖書館總館', '高雄市新興區6鄰民生一路271號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '高雄市立圖書館新興民眾閱覽室', 22.6272175, 120.3068429, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='寶島台語囡仔古', `description`='由寶島台語囡仔古社團的故事志工為親子們說演台語故事，並加入延伸的手作活動。\r\n繪本：蛀齒蟲 tāi chiàn 牙槽王\r\n      (蛀牙蟲大戰牙槽王)\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市新興區6鄰民生一路271號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='高雄市立圖書館新興民眾閱覽室', `latitude`=22.6272175, `longitude`=120.3068429, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2ca26b32408680be9c8', '星光系列英雄的璀璨─姜智譯與TSO附設青年管弦樂團', '過往在討論當代音樂時，往往會忽略電影配樂的價值，認為太過商業化、不夠「嚴肅」。但在電影藝術經歷百餘年後，人們才驚訝地發現，電影配樂或許是最具影響力、流傳最廣的當代音樂作品，耐聽度與深度完全經得起大雅之堂的考驗！TSO附設青年管弦樂團與指揮姜智譯，將在「英雄的璀璨」音樂會中，精選多部耳熟能詳的經典配樂：《阿甘正傳》由音樂訴說小人物的不平凡一生、《印第安那瓊斯》主題旋律一響起就帶觀眾上天遁地探險、《神鬼戰士》則穿越時空展現羅馬時代的史詩浩瀚，以及《魔戒》用精巧編曲勾勒出奇幻篇章；另外，《悲慘世界》與《阿根廷別為我哭泣》兩部改編自百老匯音樂劇的電影，也充滿著令人回味無窮的經典旋律；姜智譯更精選了兩首正統古典樂曲：羅西尼《威廉．泰爾》序曲中的騎兵隊旋律，在各種影視作品出現的時機不勝枚舉，而奧斯卡最佳影片《王者之聲》中，用貝多芬第七號交響曲的第二樂章，搭配英國國王努力克服口吃，向人民進行現場廣播的鏡頭，更是完美結合古典樂與影視畫面的影史典範！\r\n【演出曲目】\r\n羅西尼：《威廉‧泰爾》序曲\r\nGioachino Rossini: "William Tell" Overture\r\n席維斯崔：電影《阿甘正傳》組曲（卡斯特編曲）\r\nAlan Silvestri: Suite from "Forrest Gump" (arr. Calvin Custer)\r\n貝多芬：A大調第七號交響曲，作品92，第二樂章，選自電影《王者之聲》\r\nLudwig van Beethoven: Symphony in A Major, Op.92, Mov.2, from "The King’s Speech"\r\n約翰‧威廉斯：電影《印第安那瓊斯》組曲\r\nJohn Williams: Suite from "Indiana Jones"\r\n中場休息 Intermission\r\n漢斯‧季默：電影《神鬼戰士》組曲\r\nHans Zimmer: Suite from "Gladiator"\r\n勛伯格：音樂劇《悲慘世界》組曲（洛登編曲）\r\nClaude-Michel Schönberg: Suite from "Les Miserables" (arr. Bob Lowden)\r\n安德魯‧洛伊‧韋伯：電影《阿根廷別為我哭泣》組曲（卡斯特編曲）\r\nAndrew Lloyd Webber: Suite from "Don’t Cry for Me Argentina" (arr. Calvin Custer)\r\n霍華‧蕭：電影《魔戒》組曲（惠特尼編曲）\r\nHoward Shore: Suite from "The Lord of the Rings" (arr. John Whitney)\r\n\r\n', '臺北市立交響樂團', '臺北市中正區延平南路98號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺北市中山堂', 25.03240487, 121.5198839, '/+200;/+300;/+500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='星光系列英雄的璀璨─姜智譯與TSO附設青年管弦樂團', `description`='過往在討論當代音樂時，往往會忽略電影配樂的價值，認為太過商業化、不夠「嚴肅」。但在電影藝術經歷百餘年後，人們才驚訝地發現，電影配樂或許是最具影響力、流傳最廣的當代音樂作品，耐聽度與深度完全經得起大雅之堂的考驗！TSO附設青年管弦樂團與指揮姜智譯，將在「英雄的璀璨」音樂會中，精選多部耳熟能詳的經典配樂：《阿甘正傳》由音樂訴說小人物的不平凡一生、《印第安那瓊斯》主題旋律一響起就帶觀眾上天遁地探險、《神鬼戰士》則穿越時空展現羅馬時代的史詩浩瀚，以及《魔戒》用精巧編曲勾勒出奇幻篇章；另外，《悲慘世界》與《阿根廷別為我哭泣》兩部改編自百老匯音樂劇的電影，也充滿著令人回味無窮的經典旋律；姜智譯更精選了兩首正統古典樂曲：羅西尼《威廉．泰爾》序曲中的騎兵隊旋律，在各種影視作品出現的時機不勝枚舉，而奧斯卡最佳影片《王者之聲》中，用貝多芬第七號交響曲的第二樂章，搭配英國國王努力克服口吃，向人民進行現場廣播的鏡頭，更是完美結合古典樂與影視畫面的影史典範！\r\n【演出曲目】\r\n羅西尼：《威廉‧泰爾》序曲\r\nGioachino Rossini: "William Tell" Overture\r\n席維斯崔：電影《阿甘正傳》組曲（卡斯特編曲）\r\nAlan Silvestri: Suite from "Forrest Gump" (arr. Calvin Custer)\r\n貝多芬：A大調第七號交響曲，作品92，第二樂章，選自電影《王者之聲》\r\nLudwig van Beethoven: Symphony in A Major, Op.92, Mov.2, from "The King’s Speech"\r\n約翰‧威廉斯：電影《印第安那瓊斯》組曲\r\nJohn Williams: Suite from "Indiana Jones"\r\n中場休息 Intermission\r\n漢斯‧季默：電影《神鬼戰士》組曲\r\nHans Zimmer: Suite from "Gladiator"\r\n勛伯格：音樂劇《悲慘世界》組曲（洛登編曲）\r\nClaude-Michel Schönberg: Suite from "Les Miserables" (arr. Bob Lowden)\r\n安德魯‧洛伊‧韋伯：電影《阿根廷別為我哭泣》組曲（卡斯特編曲）\r\nAndrew Lloyd Webber: Suite from "Don’t Cry for Me Argentina" (arr. Calvin Custer)\r\n霍華‧蕭：電影《魔戒》組曲（惠特尼編曲）\r\nHoward Shore: Suite from "The Lord of the Rings" (arr. John Whitney)\r\n\r\n', `organizer`='臺北市立交響樂團', `address`='臺北市中正區延平南路98號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺北市中山堂', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='/+200;/+300;/+500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2ca26b32408680be9c9', '三秦公孫 乙巳張克晉書畫展', '三秦公孫 乙巳張克晉書畫展\r\n展期：2025.4.1-15\r\n茶會：2025.4.5  15:00\r\n\r\n台灣出生，祖籍陝西，曾經是高考狀元，每佇立曲江池畔，引頸遙望整座長安城，彷彿能看到大唐盛世「春風得意馬蹄疾，一日看盡長安花」的榮光景象。\r\n一座十三朝古都，寫盡半部中國歷史，流傳千百年的王公將相、文人雅士、沈魚落雁、國色天香的故事，多出於長安城。\r\n他是三秦公孫，北宋理學家張載直系後裔----張克晉。\r\n士林孟焦畫坊於114年4月1日至114年4月15日「三秦公孫乙巳張克晉書畫展」，為張克晉教授第二十次個展。\r\n張克晉教授，字子健、號瑞樓，齋館號「玲瓏山房」，為錢穆先生弟子。張教授除於國立台灣師範大學、東吳大學教中國古典文學外，更專研中國古文物、中國書畫史，不僅在學問、思想上有卓越貢獻，在書畫方面，更是近現代在尊崇「文人書畫」絕無僅有的代表人物之一，書法師承戴蘭邨、汪中教授；國畫宗仰唐寅、溥心畬、陳雲彰，作品中常能見其自賦詩詞，自得其樂，用紙、用印更是極其講究。\r\n獨特的「中國文人書畫」，講究的是全面的文化修養，必須「詩、書、畫、印」樣樣兼備，學問、思想、才情、人品缺一不可。\r\n有人說溥心畬被尊為「中國文人畫的最後一筆」，此一說除了代表世人對文人畫的沈寂，雖然無盡感嘆，但卻也無能為力。\r\n然而張教授認為，中國文人的精神，是永不消失的，中國最獨特、最典雅、最能彰顯文人氣節的精神，更無所謂「最後一筆」一說，有志之士應以傳承及發揚為己任，除了要求書畫的典雅與寧靜，在用絹、用紙、用墨、用色皆堅持使用傳統材料，恬靜地書寫、自得其樂的作詩、尊崇典雅的山水文人畫、精選印材、名家印刻及篆刻內容，走訪出產紙墨筆硯的名鄉、搜羅最傳統最齊全的傳統國畫顏料、用最好最美印色的印泥，毫不馬虎地講究裝裱的品質，將中國古典文學優美的境界，融入其作，希望能成為「繼溥心畬之後，肩負中國文人畫傳承發揚使命的重要角色之一」，更希望作品能成為中國藝術史上，被保留的精采一頁。\r\n他說：「傳承，是一種使命感。」\r\n大哉此言！\r\n美哉書畫，治世傳家，作品值得慧眼收藏。\r\n                                                                               (撰文：曾宇涵) \r\n\r\n 開放時間  AM11:00-PM19:00 (週一休假)\r\n展出地點  孟焦畫坊  臺北市士林區雨農路17-2號1樓\r\n電話      (02)2834-4319\r\n網址      https://web.hocom.tw/h/?key=399852860856  \r\n  \r\n', '孟焦畫廊', '臺北市士林區雨農路17-2號1樓', '2025-04-01 00:00:00', '2025-04-15 00:00:00', '孟焦畫坊', 25.12546704, 121.5508473, '無資料', 'https://web.hocom.tw/h/?key=399852860856', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三秦公孫 乙巳張克晉書畫展', `description`='三秦公孫 乙巳張克晉書畫展\r\n展期：2025.4.1-15\r\n茶會：2025.4.5  15:00\r\n\r\n台灣出生，祖籍陝西，曾經是高考狀元，每佇立曲江池畔，引頸遙望整座長安城，彷彿能看到大唐盛世「春風得意馬蹄疾，一日看盡長安花」的榮光景象。\r\n一座十三朝古都，寫盡半部中國歷史，流傳千百年的王公將相、文人雅士、沈魚落雁、國色天香的故事，多出於長安城。\r\n他是三秦公孫，北宋理學家張載直系後裔----張克晉。\r\n士林孟焦畫坊於114年4月1日至114年4月15日「三秦公孫乙巳張克晉書畫展」，為張克晉教授第二十次個展。\r\n張克晉教授，字子健、號瑞樓，齋館號「玲瓏山房」，為錢穆先生弟子。張教授除於國立台灣師範大學、東吳大學教中國古典文學外，更專研中國古文物、中國書畫史，不僅在