INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2ca26b32408680be9ca', '中山73影視114年3月: 查無此心(3場)', '冷面女警吳潔背負傷痛過往，準備在跨年夜自殺，就下她一命的，是一具水流屍。都說屍體任人辦案，然而一心轉調的吳潔與不諳世故的新進菜鳥，卻在查案過程遭遇重重難關，直到頭號嫌疑犯非法移工仲介林佑生的出現，彷彿一下子旋動連環殺人案的開關。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-03-02 00:00:00', '2025-03-21 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年3月: 查無此心(3場)', `description`='冷面女警吳潔背負傷痛過往，準備在跨年夜自殺，就下她一命的，是一具水流屍。都說屍體任人辦案，然而一心轉調的吳潔與不諳世故的新進菜鳥，卻在查案過程遭遇重重難關，直到頭號嫌疑犯非法移工仲介林佑生的出現，彷彿一下子旋動連環殺人案的開關。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2ca26b32408680be9cb', '中山73影視114年4月:消失的紫斑蝶(3場)', '導演詹家龍耗時五年、花費數百萬，深入紫蝶幽谷，叩訪成千上萬紫斑蝶神祕避冬點滴，記錄紫斑蝶在臺灣的生命軌跡、窺探紫斑蝶奇幻的一生。本片邀請創作歌手安溥深情獻聲，導演詹家龍以高速攝影機，捕捉蝴蝶脫皮、捕食、破蛹而出的瞬間，帶給觀眾微距細膩的視覺震撼。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-04-07 00:00:00', '2025-04-27 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年4月:消失的紫斑蝶(3場)', `description`='導演詹家龍耗時五年、花費數百萬，深入紫蝶幽谷，叩訪成千上萬紫斑蝶神祕避冬點滴，記錄紫斑蝶在臺灣的生命軌跡、窺探紫斑蝶奇幻的一生。本片邀請創作歌手安溥深情獻聲，導演詹家龍以高速攝影機，捕捉蝴蝶脫皮、捕食、破蛹而出的瞬間，帶給觀眾微距細膩的視覺震撼。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-04-07 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2ca26b32408680be9cc', '中山73影視114年4月:哈勇家(3場)', '三代同堂的泰雅家庭，哈勇阿公是家族的精神支柱，一直奉行gaga (泰雅傳統的原則) 生活，孫女阿莉 從紐西蘭打工兩年，剛回家不久，阿公在睡夢中過世。而阿莉的父親巴尚為了家中土地所有權的問題，不顧阿公生前的反對，決定參選鄉長，提升家族地位，同時，阿嬤發現阿莉竟然懷孕了，新的小生命即將來到哈勇家！然而巴尚參與的這場選戰，讓家族感情一夕凍結，如同高山上冬季的那一場雪。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-04-04 00:00:00', '2025-04-20 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年4月:哈勇家(3場)', `description`='三代同堂的泰雅家庭，哈勇阿公是家族的精神支柱，一直奉行gaga (泰雅傳統的原則) 生活，孫女阿莉 從紐西蘭打工兩年，剛回家不久，阿公在睡夢中過世。而阿莉的父親巴尚為了家中土地所有權的問題，不顧阿公生前的反對，決定參選鄉長，提升家族地位，同時，阿嬤發現阿莉竟然懷孕了，新的小生命即將來到哈勇家！然而巴尚參與的這場選戰，讓家族感情一夕凍結，如同高山上冬季的那一場雪。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-04-04 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2ca26b32408680be9cd', '米豆電影院(3月)', '播放影片：消失的紫斑蝶\r\n  追蝶超過三十年的生態導演詹家龍，深入紫蝶幽谷，扣訪成千上萬的紫斑蝶神祕避冬點滴，紀錄紫斑蝶在台灣的生命軌跡、窺紫斑蝶奇幻一生。導演以超高速攝影機，捕捉蝴蝶脫皮、捕食、破蛹而出的瞬間，帶給觀眾細膩的視覺震撼。\r\n紫斑蝶漸漸消失是否跟環境及植物有息息相關的關係呢?\r\n', '高雄市立圖書館總館', '高雄市彌陀區2鄰中正路281巷50號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '高雄市立圖書館彌陀公園分館', 22.780227, 120.249503, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='米豆電影院(3月)', `description`='播放影片：消失的紫斑蝶\r\n  追蝶超過三十年的生態導演詹家龍，深入紫蝶幽谷，扣訪成千上萬的紫斑蝶神祕避冬點滴，紀錄紫斑蝶在台灣的生命軌跡、窺紫斑蝶奇幻一生。導演以超高速攝影機，捕捉蝴蝶脫皮、捕食、破蛹而出的瞬間，帶給觀眾細膩的視覺震撼。\r\n紫斑蝶漸漸消失是否跟環境及植物有息息相關的關係呢?\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市彌陀區2鄰中正路281巷50號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='高雄市立圖書館彌陀公園分館', `latitude`=22.780227, `longitude`=120.249503, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2ca26b32408680be9ce', '「佮台語𨑨迌」-台語主題書展', '  響應母語日，透過台語書展、實作活動、及教學來熟悉台語特色之美，藉此認識鄉土文化內涵並傳承鄉土文化。\r\n1.舉辦「佮台語𨑨迌」主題書展，紙本及數位源。\r\n2.同步展出「彌陀心-彌陀情:老照片說故事」，彌羅港特有的口頭禪及耆老創作台語四句聯。\r\n', '高雄市立圖書館總館', '高雄市彌陀區2鄰中正路281巷50號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館彌陀公園分館', 22.780227, 120.249503, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「佮台語𨑨迌」-台語主題書展', `description`='  響應母語日，透過台語書展、實作活動、及教學來熟悉台語特色之美，藉此認識鄉土文化內涵並傳承鄉土文化。\r\n1.舉辦「佮台語𨑨迌」主題書展，紙本及數位源。\r\n2.同步展出「彌陀心-彌陀情:老照片說故事」，彌羅港特有的口頭禪及耆老創作台語四句聯。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市彌陀區2鄰中正路281巷50號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館彌陀公園分館', `latitude`=22.780227, `longitude`=120.249503, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2ca26b32408680be9cf', '室內沙龍系列李道特與TSO獨奏家', '1980年，為紀念世界首位中提琴炫技名家特蒂斯（Lionel Tertis），英國舉辦了國際特蒂斯中提琴大賽，許多耀眼名家皆在此邁向國際舞臺，然而一直要到2016年的第12屆大賽，由英國中提琴家李道特奪下首獎，才終於出現了第一位本土冠軍。李道特也成為不折不扣的「故鄉英雄」，此後更拿下BBC新一代藝術家、2023年皇家愛樂協會青年藝術家獎等殊榮，成為中提琴界不可忽視的英國力量。2025年，TSO力邀李道特來臺合作，在【2025 TSO名家系列】艾爾茲、李道特與TSO演出協奏曲外，更率先以【2025 TSO室內沙龍】展現他的個人魅力，曲目由小至大，先以巴赫無伴奏大提琴組曲的改編版呈現中提琴獨有的音色，再透過艾爾加、維爾納、布魯赫與羅拉等室內樂作品，與TSO弦樂聲部互相唱和，展現弦樂編制的綿密織體，以及越聽越令人沈醉的香醇！\r\n【演出曲目】\r\n巴赫：G大調第一號無伴奏大提琴組曲（改編給中提琴）\r\nJohann Sebastian Bach: Cello Suite No.1 in G Major, BWV 1007 (arr. for Viola Solo)\r\n巴赫：D小調第二號無伴奏小提琴組曲（改編給中提琴）\r\nJohann Sebastian Bach: Violin Partita No.2 in D Minor, BWV 1004 (arr. for Viola Solo)\r\n中場休息 Intermission\r\n艾爾加：《嘆息》，作品70（改編給中提琴、弦樂四重奏及豎琴）\r\nEdward Elgar: "Sospiri", Op.70 (arr. for Viola, Quartet and Harp)\r\n維爾納：2首小品，給中提琴及鋼琴，作品5\r\nLouise Vierne: 2 Pieces for Viola and Piano, Op.5\r\n布魯赫：浪漫曲，給中提琴與弦樂四重奏\r\nMax Bruch: Romance for Viola & String Quartet\r\n羅拉 : F大調嬉遊曲，給中提琴與弦樂四重奏\r\nAlessandro Rolla: Divertimento in F Major for Viola & String Quartet\r\n\r\n展演者︰〝小提琴：楊雅淳/中華民國〞；〝小提琴：裴誼庭/中華民國〞；〝中提琴：提摩西·李道特/英國〞；〝中提琴：何君恆/中華民國〞；〝大提琴：詹書婷/中華民國〞；〝豎琴：曾韋晴/中華民國〞；〝鋼琴：王憶茹/中華民國〞。\r\n\r\n\r\n', '臺北市立交響樂團', '臺北市中正區中山南路21之1號', '2025-04-07 00:00:00', '2025-04-07 00:00:00', '國家兩廳院', 25.03240487, 121.5198839, '/+300;/+500;/+800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='室內沙龍系列李道特與TSO獨奏家', `description`='1980年，為紀念世界首位中提琴炫技名家特蒂斯（Lionel Tertis），英國舉辦了國際特蒂斯中提琴大賽，許多耀眼名家皆在此邁向國際舞臺，然而一直要到2016年的第12屆大賽，由英國中提琴家李道特奪下首獎，才終於出現了第一位本土冠軍。李道特也成為不折不扣的「故鄉英雄」，此後更拿下BBC新一代藝術家、2023年皇家愛樂協會青年藝術家獎等殊榮，成為中提琴界不可忽視的英國力量。2025年，TSO力邀李道特來臺合作，在【2025 TSO名家系列】艾爾茲、李道特與TSO演出協奏曲外，更率先以【2025 TSO室內沙龍】展現他的個人魅力，曲目由小至大，先以巴赫無伴奏大提琴組曲的改編版呈現中提琴獨有的音色，再透過艾爾加、維爾納、布魯赫與羅拉等室內樂作品，與TSO弦樂聲部互相唱和，展現弦樂編制的綿密織體，以及越聽越令人沈醉的香醇！\r\n【演出曲目】\r\n巴赫：G大調第一號無伴奏大提琴組曲（改編給中提琴）\r\nJohann Sebastian Bach: Cello Suite No.1 in G Major, BWV 1007 (arr. for Viola Solo)\r\n巴赫：D小調第二號無伴奏小提琴組曲（改編給中提琴）\r\nJohann Sebastian Bach: Violin Partita No.2 in D Minor, BWV 1004 (arr. for Viola Solo)\r\n中場休息 Intermission\r\n艾爾加：《嘆息》，作品70（改編給中提琴、弦樂四重奏及豎琴）\r\nEdward Elgar: "Sospiri", Op.70 (arr. for Viola, Quartet and Harp)\r\n維爾納：2首小品，給中提琴及鋼琴，作品5\r\nLouise Vierne: 2 Pieces for Viola and Piano, Op.5\r\n布魯赫：浪漫曲，給中提琴與弦樂四重奏\r\nMax Bruch: Romance for Viola & String Quartet\r\n羅拉 : F大調嬉遊曲，給中提琴與弦樂四重奏\r\nAlessandro Rolla: Divertimento in F Major for Viola & String Quartet\r\n\r\n展演者︰〝小提琴：楊雅淳/中華民國〞；〝小提琴：裴誼庭/中華民國〞；〝中提琴：提摩西·李道特/英國〞；〝中提琴：何君恆/中華民國〞；〝大提琴：詹書婷/中華民國〞；〝豎琴：曾韋晴/中華民國〞；〝鋼琴：王憶茹/中華民國〞。\r\n\r\n\r\n', `organizer`='臺北市立交響樂團', `address`='臺北市中正區中山南路21之1號', `start_date`='2025-04-07 00:00:00', `end_date`='2025-04-07 00:00:00', `location`='國家兩廳院', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='/+300;/+500;/+800', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2ca26b32408680be9d0', '名家系列艾爾茲、李道特與TSO', '波羅的海三國在1990年前後，以「歌唱革命」凝聚人民的心，最終成功獨立於蘇聯，成為東北歐閃亮的一角；歷史上不斷被俄國與瑞典佔領的芬蘭，也在1900年西貝流士寫下的《芬蘭頌》中，用音符唱出民族的驕傲，更成為芬蘭的第二國歌——這樣的文化背景，在愛沙尼亞國家交響樂團音樂總監及首席指揮艾爾茲（Olari Elts）的帶領下，更具說服力。艾爾茲挑選的勞塔瓦拉《北極之歌》雀鳥協奏曲、帕特《天鵝之歌》與西貝流士第五號交響曲，不但具現愛沙尼亞與芬蘭的文化獨特性，三首曲目不約而同皆以「鳥類」做為主題，更展現了崇尚自由的展翅翱翔。\r\n\r\n \r\n\r\n同時，本場更特別安排了巴爾托克的中提琴協奏曲，這是作曲家在對抗白血病時，仍不放棄的最後創作，即便最後只完成了獨奏與鋼琴段落，樂團配器交由友人完成，巴爾托克充分掌握了中提琴柔中帶剛、暗中透亮的音色，成為中提琴協奏曲的代表作，也紀念2025年為作曲家逝世80週年。獨奏家則邀請2023年獲皇家愛樂協會青年藝術家獎、BBT信託獎（Borletti-Buitoni Trust）、也是BBC新生代藝術家計畫成員的英國中提琴家李道特（Timothy Ridout）演出，展現如日中天的巨星風采！\r\n【演出曲目】\r\n勞塔瓦拉：《北極之歌》雀鳥協奏曲\r\nEinojuhani Rautavaara: "Cantus Arcticus", Concerto for Birds and Orchestra\r\n巴爾托克：中提琴協奏曲，Sz.120\r\nBéla Bartók: Viola Concerto, Sz.120\r\n帕特：《天鵝之歌》\r\nArvo Pärt: "Swansong"\r\n中場休息 Intermission\r\n西貝流士：降E大調第五號交響曲，作品82\r\nJean Sibelius: Symphony No.5 in E-flat Major, Op.82  \r\n', '臺北市立交響樂團', '臺北市中正區延平南路98號', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '臺北市中山堂', 25.03240487, 121.5198839, '/+300;/+500;/+800;/+1200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='名家系列艾爾茲、李道特與TSO', `description`='波羅的海三國在1990年前後，以「歌唱革命」凝聚人民的心，最終成功獨立於蘇聯，成為東北歐閃亮的一角；歷史上不斷被俄國與瑞典佔領的芬蘭，也在1900年西貝流士寫下的《芬蘭頌》中，用音符唱出民族的驕傲，更成為芬蘭的第二國歌——這樣的文化背景，在愛沙尼亞國家交響樂團音樂總監及首席指揮艾爾茲（Olari Elts）的帶領下，更具說服力。艾爾茲挑選的勞塔瓦拉《北極之歌》雀鳥協奏曲、帕特《天鵝之歌》與西貝流士第五號交響曲，不但具現愛沙尼亞與芬蘭的文化獨特性，三首曲目不約而同皆以「鳥類」做為主題，更展現了崇尚自由的展翅翱翔。\r\n\r\n \r\n\r\n同時，本場更特別安排了巴爾托克的中提琴協奏曲，這是作曲家在對抗白血病時，仍不放棄的最後創作，即便最後只完成了獨奏與鋼琴段落，樂團配器交由友人完成，巴爾托克充分掌握了中提琴柔中帶剛、暗中透亮的音色，成為中提琴協奏曲的代表作，也紀念2025年為作曲家逝世80週年。獨奏家則邀請2023年獲皇家愛樂協會青年藝術家獎、BBT信託獎（Borletti-Buitoni Trust）、也是BBC新生代藝術家計畫成員的英國中提琴家李道特（Timothy Ridout）演出，展現如日中天的巨星風采！\r\n【演出曲目】\r\n勞塔瓦拉：《北極之歌》雀鳥協奏曲\r\nEinojuhani Rautavaara: "Cantus Arcticus", Concerto for Birds and Orchestra\r\n巴爾托克：中提琴協奏曲，Sz.120\r\nBéla Bartók: Viola Concerto, Sz.120\r\n帕特：《天鵝之歌》\r\nArvo Pärt: "Swansong"\r\n中場休息 Intermission\r\n西貝流士：降E大調第五號交響曲，作品82\r\nJean Sibelius: Symphony No.5 in E-flat Major, Op.82  \r\n', `organizer`='臺北市立交響樂團', `address`='臺北市中正區延平南路98號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='臺北市中山堂', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='/+300;/+500;/+800;/+1200', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2cb26b32408680be9d1', '【See Different 看見不同的學習風景】教科圖書設計獎特展延伸書展', '「教科圖書設計獎」是台灣第一個以教科書為主題的設計競賽。透過獎賽制度鼓勵出版業者自主設計開發，結合「教科圖書設計輔導計畫」與協助教科圖書出版業與設計串連，運用設計思維，發展創新服務與應用，串連教育設計產業鏈，推動台灣「教育設計產業」永續發展。\r\n教科書是孩子學習的主要工具，「教科圖書設計獎」 希望從孩子的美感從教科書開始，讓台灣的教育力與設計力能夠完美結合，從日常之中帶動改變。讓教科書不只是傳遞知識的工具，更是培養美感的途徑，孩子能從中提升學習動機、喜歡上上學。在未來，教科書可以是什麼形式？什麼樣貌呢？教科圖書設計獎邀請大家一起思考、一起為教育帶來改變。', '桃園市立圖書館', '桃園市桃園區南平路303號', '2025-02-17 00:00:00', '2025-03-31 00:00:00', '桃園市立圖書館總館', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【See Different 看見不同的學習風景】教科圖書設計獎特展延伸書展', `description`='「教科圖書設計獎」是台灣第一個以教科書為主題的設計競賽。透過獎賽制度鼓勵出版業者自主設計開發，結合「教科圖書設計輔導計畫」與協助教科圖書出版業與設計串連，運用設計思維，發展創新服務與應用，串連教育設計產業鏈，推動台灣「教育設計產業」永續發展。\r\n教科書是孩子學習的主要工具，「教科圖書設計獎」 希望從孩子的美感從教科書開始，讓台灣的教育力與設計力能夠完美結合，從日常之中帶動改變。讓教科書不只是傳遞知識的工具，更是培養美感的途徑，孩子能從中提升學習動機、喜歡上上學。在未來，教科書可以是什麼形式？什麼樣貌呢？教科圖書設計獎邀請大家一起思考、一起為教育帶來改變。', `organizer`='桃園市立圖書館', `address`='桃園市桃園區南平路303號', `start_date`='2025-02-17 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='桃園市立圖書館總館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2cb26b32408680be9d2', '2025青春美展 摸象TOUCH ANLEPHANT BEYOND DESCRIPTION 114級國立台南大學視覺藝術與設計學系', '現今科技發展使訊息傳播爆炸性增長，現代人生活中充斥著大量資訊。在盲人摸象的故事中，每位盲人感知的部分象徵片面資訊，強調訊息傳播過程中的失真與偏見，讓“真實”變得多樣且無法完全把握。展覽中的作品並無固定意義，每件作品具多義性，觀眾的解讀受自身背景與經驗影響。每位同學的作品都像是對“象”的不同詮釋，作品間的差異構成展覽的整體意義，觀眾則是站在盲人位置，像在探索藝術中拼湊真實的過程。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-05-02 00:00:00', '2025-05-13 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4100', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展 摸象TOUCH ANLEPHANT BEYOND DESCRIPTION 114級國立台南大學視覺藝術與設計學系', `description`='現今科技發展使訊息傳播爆炸性增長，現代人生活中充斥著大量資訊。在盲人摸象的故事中，每位盲人感知的部分象徵片面資訊，強調訊息傳播過程中的失真與偏見，讓“真實”變得多樣且無法完全把握。展覽中的作品並無固定意義，每件作品具多義性，觀眾的解讀受自身背景與經驗影響。每位同學的作品都像是對“象”的不同詮釋，作品間的差異構成展覽的整體意義，觀眾則是站在盲人位置，像在探索藝術中拼湊真實的過程。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-02 00:00:00', `end_date`='2025-05-13 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4100', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2cb26b32408680be9d3', '2025臺南七股紅蔥頭產業文化活動-舞台表演', '紅蔥頭產業文化活動以邀請在地國小來到現場演出方式吸引民眾參與活動,七股國小演出臺灣囡仔來鹽山;後港國小帶來直笛表演;大文國小則演奏烏克麗麗,透過藝文演出方式結合農特產品的推廣,提升活動的藝文氣息', '臺南市七股區農會', '臺南市七股區', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '七股區（臺南市）=', 23.12326578, 120.1005854, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺南七股紅蔥頭產業文化活動-舞台表演', `description`='紅蔥頭產業文化活動以邀請在地國小來到現場演出方式吸引民眾參與活動,七股國小演出臺灣囡仔來鹽山;後港國小帶來直笛表演;大文國小則演奏烏克麗麗,透過藝文演出方式結合農特產品的推廣,提升活動的藝文氣息', `organizer`='臺南市七股區農會', `address`='臺南市七股區', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='七股區（臺南市）=', `latitude`=23.12326578, `longitude`=120.1005854, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2cb26b32408680be9d4', '就是愛，台灣：2025林磐聳台灣意象展', '為推動藝文，讓各界認識國內藝術家如何在台灣的土地上找到養分、展現特色，本處於2025年初，推出重量級設計藝術家展覽，邀請2007年國家文藝獎美術類得主、2023年文化部文協獎章得主–林磐聳教授舉辦本次展覽。林磐聳被譽為「台灣設計發光體」、「臺灣設計界導師」，不但是國內設計文化推手，更是創作能量源源不絕的設計藝術家，於2003年獲選紐約Phaidon出版的《Area： 100 Grphic Designers,10 Curators,10 Designclassics》， 名列世界百大設計家之一。\r\n\r\n此次展覽完整呈現他長期聚焦在「台灣形象」CI設計、「台灣印象」海報設計及「台灣意象」藝術創作，展現出其多年來從事創作的核心概念：「就是愛，台灣」，期待透過藝術與設計作為文化載體，讓世界看見台灣。', '國立中正紀念堂管理處', '臺北市中正區中山南路21號', '2025-01-15 00:00:00', '2025-03-10 00:00:00', '國立中正紀念堂管理處', 25.03240487, 121.5198839, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50519', '[]') ON DUPLICATE KEY UPDATE `activity_name`='就是愛，台灣：2025林磐聳台灣意象展', `description`='為推動藝文，讓各界認識國內藝術家如何在台灣的土地上找到養分、展現特色，本處於2025年初，推出重量級設計藝術家展覽，邀請2007年國家文藝獎美術類得主、2023年文化部文協獎章得主–林磐聳教授舉辦本次展覽。林磐聳被譽為「台灣設計發光體」、「臺灣設計界導師」，不但是國內設計文化推手，更是創作能量源源不絕的設計藝術家，於2003年獲選紐約Phaidon出版的《Area： 100 Grphic Designers,10 Curators,10 Designclassics》， 名列世界百大設計家之一。\r\n\r\n此次展覽完整呈現他長期聚焦在「台灣形象」CI設計、「台灣印象」海報設計及「台灣意象」藝術創作，展現出其多年來從事創作的核心概念：「就是愛，台灣」，期待透過藝術與設計作為文化載體，讓世界看見台灣。', `organizer`='國立中正紀念堂管理處', `address`='臺北市中正區中山南路21號', `start_date`='2025-01-15 00:00:00', `end_date`='2025-03-10 00:00:00', `location`='國立中正紀念堂管理處', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50519', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2cc26b32408680be9d5', '觸動時刻-鄭志德師生聯展', '藝術家鄭志德現任教於國立臺灣師範大學進修推廣學院，個人作品曾獲得第16屆奇美藝術人才培訓首獎、第4屆聯邦美術新人獎優選、第2屆全國百號油畫大賽第二名、2013年法國藝術家沙龍銀牌獎等國內外許多藝術獎項，此次展覽由鄭老師帶領16位學生展現師生創作成果，展覽名稱「觸動時刻」，傳達出參展者在人物、風景、靜物等主題創作及生活中的體悟及靈光乍現的感動時刻。\r\n\r\n本次展品類別多元，如鄭老師的《太空遊記》－期許將來臺灣可以放眼國際也放眼太空，表現童趣。林美嫻的《穿和服的女孩》－以溫潤色調表現女孩的稚嫩及喜氣。陳俊誠的《誰打破恐龍蛋》－以詼諧趣味導引觀眾重新組合他們的故事。劉立潔的《佛朗明哥舞者》－透過描繪舞者傳遞異國文化的風采。簡子寧的《池塘》－看似微不足道的事物，卻有其獨特與價值等等。敬邀一同感受藝術家的觸動時刻。', '無資料', '臺北市中正區中山南路21號', '2025-02-22 00:00:00', '2025-03-09 00:00:00', '國立中正紀念堂管理處', 25.03240487, 121.5198839, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='觸動時刻-鄭志德師生聯展', `description`='藝術家鄭志德現任教於國立臺灣師範大學進修推廣學院，個人作品曾獲得第16屆奇美藝術人才培訓首獎、第4屆聯邦美術新人獎優選、第2屆全國百號油畫大賽第二名、2013年法國藝術家沙龍銀牌獎等國內外許多藝術獎項，此次展覽由鄭老師帶領16位學生展現師生創作成果，展覽名稱「觸動時刻」，傳達出參展者在人物、風景、靜物等主題創作及生活中的體悟及靈光乍現的感動時刻。\r\n\r\n本次展品類別多元，如鄭老師的《太空遊記》－期許將來臺灣可以放眼國際也放眼太空，表現童趣。林美嫻的《穿和服的女孩》－以溫潤色調表現女孩的稚嫩及喜氣。陳俊誠的《誰打破恐龍蛋》－以詼諧趣味導引觀眾重新組合他們的故事。劉立潔的《佛朗明哥舞者》－透過描繪舞者傳遞異國文化的風采。簡子寧的《池塘》－看似微不足道的事物，卻有其獨特與價值等等。敬邀一同感受藝術家的觸動時刻。', `organizer`='無資料', `address`='臺北市中正區中山南路21號', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='國立中正紀念堂管理處', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
