INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2cc26b32408680be9db', '114年南投好客文化學院：生活客語研習班', '本研習於3月5日開課，課程由本縣客語薪傳師莊鈺珍老師擔任講座，每週2小時，為期18週，於草屯鎮福客平安學堂上課，課程以客家委員會客語能力認證教材為依據，從發音教起，教授生活客語、初級客語能力認證考試基本詞彙，讓客語連結社區，在生活中自然使用客語對話，課程免費，名額有限，歡迎對客語及客家文化有興趣的民眾踴躍參加。報名者名單主辦單位保有錄取審核權。如有報名相關疑問，可逕洽南投縣客家發展所（週二至週六9時至18時），連絡電話：049-2246421分機710林先生。', '南投縣客家發展所', '南投縣草屯鎮', '2025-03-05 00:00:00', '2025-07-02 00:00:00', '草屯鎮（南投縣）=', 23.98321081, 120.7326182, '無資料', 'https://www.facebook.com/profile.php?id=100063965196974', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年南投好客文化學院：生活客語研習班', `description`='本研習於3月5日開課，課程由本縣客語薪傳師莊鈺珍老師擔任講座，每週2小時，為期18週，於草屯鎮福客平安學堂上課，課程以客家委員會客語能力認證教材為依據，從發音教起，教授生活客語、初級客語能力認證考試基本詞彙，讓客語連結社區，在生活中自然使用客語對話，課程免費，名額有限，歡迎對客語及客家文化有興趣的民眾踴躍參加。報名者名單主辦單位保有錄取審核權。如有報名相關疑問，可逕洽南投縣客家發展所（週二至週六9時至18時），連絡電話：049-2246421分機710林先生。', `organizer`='南投縣客家發展所', `address`='南投縣草屯鎮', `start_date`='2025-03-05 00:00:00', `end_date`='2025-07-02 00:00:00', `location`='草屯鎮（南投縣）=', `latitude`=23.98321081, `longitude`=120.7326182, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100063965196974', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2cc26b32408680be9dc', '114年南投好客文化學院：客語詩詞吟唱班', '讓我們一起在課程中，感受客家語詩詞的美麗與深度，並共同傳承這份珍貴的文化！\r\n名額有限，有意報名者請洽：\r\n南投縣客家協會\r\n呂老師 0922-678088\r\n蕭老師 0912-120010', '南投縣客家發展所', '南投縣南投市', '2025-02-25 00:00:00', '2025-07-01 00:00:00', '南投市（南投縣）=', 23.92173537, 120.6787658, '無資料', 'https://www.facebook.com/profile.php?id=100063965196974', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年南投好客文化學院：客語詩詞吟唱班', `description`='讓我們一起在課程中，感受客家語詩詞的美麗與深度，並共同傳承這份珍貴的文化！\r\n名額有限，有意報名者請洽：\r\n南投縣客家協會\r\n呂老師 0922-678088\r\n蕭老師 0912-120010', `organizer`='南投縣客家發展所', `address`='南投縣南投市', `start_date`='2025-02-25 00:00:00', `end_date`='2025-07-01 00:00:00', `location`='南投市（南投縣）=', `latitude`=23.92173537, `longitude`=120.6787658, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100063965196974', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2cd26b32408680be9dd', '114年文化在巷子裡音樂會-中正區愛國里', 'TSO社區音樂會「文化就在巷子裡」\r\n將美好音樂饗宴帶到鄰里之間，提升社區藝術品質、讓民眾在住家附近更輕易的欣賞到優質的音樂演出，豐富市民文化內涵，一直是TSO努力目標。\r\n近年來TSO「文化就在巷子裡」音樂會投入更多人力及物力，強化演出內容，希望藉由悅耳的音樂帶給市民愉悅的心情，也用淺顯易懂的說明讓民眾得到更多基本音樂常識、提昇全民文化底蘊。\r\n演出曲目：\r\n莫札特：小夜曲，作品編號525，第一樂章\r\n莫札特：小夜曲，作品編號525，第三樂章\r\n蕭士塔高維契：第二號圓舞曲\r\n阿布瑞尤：蜂鳥\r\n皮耶佐拉：自由探戈\r\n瑤族舞曲\r\n李哲音：月夜愁、天黑黑\r\n陳哲聖：台北的天空\r\n李哲藝：廟埕\r\n安可-李哲藝：蘭陽舞曲\r\n兒歌大會串：滿山春色、流水年華.....等\r\n', '臺北市政府文化局', '臺北市中正區', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '中正區（臺北市）=', 25.03240487, 121.5198839, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年文化在巷子裡音樂會-中正區愛國里', `description`='TSO社區音樂會「文化就在巷子裡」\r\n將美好音樂饗宴帶到鄰里之間，提升社區藝術品質、讓民眾在住家附近更輕易的欣賞到優質的音樂演出，豐富市民文化內涵，一直是TSO努力目標。\r\n近年來TSO「文化就在巷子裡」音樂會投入更多人力及物力，強化演出內容，希望藉由悅耳的音樂帶給市民愉悅的心情，也用淺顯易懂的說明讓民眾得到更多基本音樂常識、提昇全民文化底蘊。\r\n演出曲目：\r\n莫札特：小夜曲，作品編號525，第一樂章\r\n莫札特：小夜曲，作品編號525，第三樂章\r\n蕭士塔高維契：第二號圓舞曲\r\n阿布瑞尤：蜂鳥\r\n皮耶佐拉：自由探戈\r\n瑤族舞曲\r\n李哲音：月夜愁、天黑黑\r\n陳哲聖：台北的天空\r\n李哲藝：廟埕\r\n安可-李哲藝：蘭陽舞曲\r\n兒歌大會串：滿山春色、流水年華.....等\r\n', `organizer`='臺北市政府文化局', `address`='臺北市中正區', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='中正區（臺北市）=', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
