INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9367547', '臺北市政府體育局114年3月行事曆 ', '無資料', '臺北市政府體育局', '無資料', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8F4E17826F46C966', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺北市政府體育局114年3月行事曆 ', `description`='無資料', `organizer`='臺北市政府體育局', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8F4E17826F46C966', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9367487', '北市圖辦理114年初階臺語推廣課程', '語言不只是溝通工具，也是歷史文化的媒介，期望母語能夠在時代變遷下繼續保有韌性，展現不同的面貌與時代接軌，進而活躍於我們的生活之中。此次本館與台灣台語文化協會合作辦理系列課程，邀請有興趣的市民一起學習具有悠久歷史、文詞美、聲韻豐富的臺語，並增強學習效果。一、課程內容：1.針對臺語初學者及想參加教育部閩南語認證考試者提供學習與練習機會。2.培養臺語入門之初學者聽、說、讀、寫的能力。二、報名網址：https://www.beclass.com/rid=294fe7467c176abc28e3三、聯絡資訊：如有相關疑問請洽總館推廣課林先生，電話：(02)2755-2823轉2112', '臺北市立圖書館', '無資料', '2025-03-04 00:00:00', '2025-03-20 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=509FAD13DE5E70E7', '[]') ON DUPLICATE KEY UPDATE `activity_name`='北市圖辦理114年初階臺語推廣課程', `description`='語言不只是溝通工具，也是歷史文化的媒介，期望母語能夠在時代變遷下繼續保有韌性，展現不同的面貌與時代接軌，進而活躍於我們的生活之中。此次本館與台灣台語文化協會合作辦理系列課程，邀請有興趣的市民一起學習具有悠久歷史、文詞美、聲韻豐富的臺語，並增強學習效果。一、課程內容：1.針對臺語初學者及想參加教育部閩南語認證考試者提供學習與練習機會。2.培養臺語入門之初學者聽、說、讀、寫的能力。二、報名網址：https://www.beclass.com/rid=294fe7467c176abc28e3三、聯絡資訊：如有相關疑問請洽總館推廣課林先生，電話：(02)2755-2823轉2112', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-04 00:00:00', `end_date`='2025-03-20 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=509FAD13DE5E70E7', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9367433', '北投就業服務站將於114年3月18日(週二)下午2-4時辦理【三商家購股份有限公司(美廉社)】微型徵才活動', '北投就業服務站將於114年3月18日(週二)下午2-4時辦理【三商家購股份有限公司(美廉社)】微型徵才活動活動時間：3月18日(二)下午2:00~4:00活動地點：北投就業服務站 (臺北市北投區新市街30號5樓)洽詢電話：(02)28981819#115公司簡介：三商家購為三商集團旗下之社區型連鎖超市業者，擁有眾多通路品牌，包括：「美廉社」、「心樸市集」、「Go 美廉」及「OFFICE Mart 美廉便利架」等，其中「美廉社」為主要核心品牌。美廉社創立於 2006 年，為社區民生消費品零售通路，其中所販售的，均為精心篩選過的民生消費核心商品，並以『物美價廉』為主要訴求。「美廉社」目前全台有820 間門市且持續積極展店中，同時與跨國集團日本住友商事旗下日藥妝品牌 Tomod&#39;s開出複合式店型，員工職涯發展有多元可能，歡迎對零售業/百貨業/連鎖超市有興趣的您一起加入我們的行列 !!福利制度：★團保/年終獎金/績效獎金/推薦獎金/免費電子會員卡/員購優惠★福委會津貼-婚/喪/生育/旅遊補助/中秋禮金/端午禮金(盒)生日禮金/勞動節禮券/特約商店優惠★公司提供完善升遷制度(提供專業技能訓練+實務經驗)，最快半年通過考核者，可升遷為門市管理職。晉升為店主管年薪達40~45萬，工作績效表現傑出者可繼續升等，年薪可達50~56萬職務名稱：儲備幹部需求人數：10學歷要求：大專以上工作經驗：具備相關經驗工作內容：店務管理/門市經營/庫存管理/人員管理/排班管理薪資待遇：月薪32500元起(獎金另計)工作時間：早班06:30-15:30/晚班15:00-24:00(中間休息一小時)工作地點：北投區、士林區職務名稱：正職人員需求人數：30學歷要求：高中職以上工作經驗：不拘工作內容：商品陳列/補貨/收貨驗收/結帳收銀/賣場清潔薪資待遇：月薪30000-32000元(獎金另計)&nbsp;工作時間：早班06:30-15:30/晚班15:00-24:00(中間休息一小時)工作地點：北投區、士林區職務名稱：(固定班)正職人員需求人數：30學歷要求：高中職以上工作經驗：不拘工作內容：商品陳列/補貨/收貨驗收/結帳收銀/賣場清潔薪資待遇：月薪28590-31000元(獎金另計)&nbsp;&nbsp;工作時間：早班06:30-15:30/晚班15:00-24:00(中間休息一小時)工作地點：北投區、士林區職務名稱：計時人員需求人數：20學歷要求：高中職以上工作經驗：不拘工作內容：商品陳列/補貨/收貨驗收/結帳收銀/賣場清潔薪資待遇：時薪190元起工作時間：06:30-24:00(彈性排班4-6小時)工作地點：北投區、士林區', '北投就業服務站', '台北市北投區新市街30號5樓', '2025-03-18 00:00:00', '2025-03-18 00:00:00', '北投就業服務站', 25.1480682, 121.5177992, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=489F4A89211F86F1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='北投就業服務站將於114年3月18日(週二)下午2-4時辦理【三商家購股份有限公司(美廉社)】微型徵才活動', `description`='北投就業服務站將於114年3月18日(週二)下午2-4時辦理【三商家購股份有限公司(美廉社)】微型徵才活動活動時間：3月18日(二)下午2:00~4:00活動地點：北投就業服務站 (臺北市北投區新市街30號5樓)洽詢電話：(02)28981819#115公司簡介：三商家購為三商集團旗下之社區型連鎖超市業者，擁有眾多通路品牌，包括：「美廉社」、「心樸市集」、「Go 美廉」及「OFFICE Mart 美廉便利架」等，其中「美廉社」為主要核心品牌。美廉社創立於 2006 年，為社區民生消費品零售通路，其中所販售的，均為精心篩選過的民生消費核心商品，並以『物美價廉』為主要訴求