INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9367060', 'Ｅ起玩髮悅讀有禮—中獎名單出爐囉！', '本館與小林髮廊攜手辦理「E起玩髮悅讀有禮」活動日前已圓滿結束，中獎名單（請見：https://reurl.cc/XZ7rxD），快看看幸運兒是不是你！一、中獎通知：(1) 全聯禮券中獎者：由本館以電話及Email通知，若因聯絡資料有誤導致無法取得通知，視同放棄中獎資格。(2) 小林髮廊電子優惠券：中獎者將可獲得專屬兌換網址1組，將於114年3月10日前，以手機簡訊發送至讀者提供之手機號碼，若因聯絡資料有誤，導致無法取得發送簡訊者視同放棄中獎資格。二、領獎方式：(1) 全聯禮券中獎者：依規定需填寫領獎申請資料，並於114年3月31 &nbsp;日前持身分證明文件及中獎通知至北市圖總館3樓諮詢服務課領取，逾期未領取者視同放棄。(2) 小林髮廊電子優惠券：☆兌換時間：114年3月10日至114年3月31日☆兌換方式：★於兌換期限內，得獎者使用專屬兌換網址加入【小林髮廊】官方LINE好友&rarr;點擊訊息提供登錄位置&rarr;填寫資料成為會員&rarr;成功加入會員領取300元優惠券★使用說明(請詳見優惠券說明)：・成為小林髮廊LINE好友方可登錄會員・本券適用剪、燙、染、護消費項目・本券小林髮廊分店皆可使用・本券限不指定設計師・本券不限消費金額，不找零・本優惠券不得與其他優惠同時使用★注意事項：・本券使用期限：114年3月10日至4月30日 ・本券逾期失效不補發・使用時請事先出示本券並告知門店人員・優惠券須經由門店人員核銷後方可生效・逾期未兌換之優惠券及未使用之優惠券將自動失效，不得要求補發或延長使用期限。・若有未盡事宜，小林髮廊保有變更、調整及終止本券之權力四、服務專線：如有活動相關疑問，歡迎利用開館時間電洽諮詢服務課(02)27552823轉2301。', '臺北市立圖書館', '無資料', '2025-03-06 00:00:00', '2025-03-27 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=EC5D301D6D918458', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Ｅ起玩髮悅讀有禮—中獎名單出爐囉！', `description`='本館與小林髮廊攜手辦理「E起玩髮悅讀有禮」活動日前已圓滿結束，中獎名單（請見：https://reurl.cc/XZ7rxD），快看看幸運兒是不是你！一、中獎通知：(1) 全聯禮券中獎者：由本館以電話及Email通知，若因聯絡資料有誤導致無法取得通知，視同放棄中獎資格。(2) 小林髮廊電子優惠券：中獎者將可獲得專屬兌換網址1組，將於114年3月10日前，以手機簡訊發送至讀者提供之手機號碼，若因聯絡資料有誤，導致無法取得發送簡訊者視同放棄中獎資格。二、領獎方式：(1) 全聯禮券中獎者：依規定需填寫領獎申請資料，並於114年3月31 &nbsp;日前持身分證明文件及中獎通知至北市圖總館3樓諮詢服務課領取，逾期未領取者視同放棄。(2) 小林髮廊電子優惠券：☆兌換時間：114年3月10日至114年3月31日☆兌換方式：★於兌換期限內，得獎者使用專屬兌換網址加入【小林髮廊】官方LINE好友&rarr;點擊訊息提供登錄位置&rarr;填寫資料成為會員&rarr;成功加入會員領取300元優惠券★使用說明(請詳見優惠券說明)：・成為小林髮廊LINE好友方可登錄會員・本券適用剪、燙、染、護消費項目・本券小林髮廊分店皆可使用・本券限不指定設計師・本券不限消費金額，不找零・本優惠券不得與其他優惠同時使用★注意事項：・本券使用期限：114年3月10日至4月30日 ・本券逾期失效不補發・使用時請事先出示本券並告知門店人員・優惠券須經由門店人員核銷後方可生效・逾期未兌換之優惠券及未使用之優惠券將自動失效，不得要求補發或延長使用期限。・若有未盡事宜，小林髮廊保有變更、調整及終止本券之權力四、服務專線：如有活動相關疑問，歡迎利用開館時間電洽諮詢服務課(02)27552823轉2301。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-06 00:00:00', `end_date`='2025-03-27 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=EC5D301D6D918458', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9367096', '「直潭壩及青潭堰增設魚道可行性評估及規劃委託技術服務」生態檢核民眾參與公開說明會', '本案為辦理「直潭壩及青潭堰增設魚道可行性評估及規劃委託技術服務」生態檢核，目前尚在可行性評估階段，並向在地民眾說明規劃內容，歡迎各界先進共同參與。 開會事由：本處辦理「直潭壩及青潭堰增設魚道可行性評估及規劃委託技術服務」生態檢核民眾參與公開說明會，敬請撥冗蒞臨指導。一、開會時間：中華民國114年3月11日 (星期二) 下午2時0分 。&nbsp;二、 開會地點：屈尺市民活動中心2樓禮堂（新北市新店區屈尺路125號）&nbsp;三、參加人員：各界先進、在地里民及市民朋友。&nbsp;四、主辦單位：臺北自來水事業處。&nbsp;五、可行性評估及規劃單位：中興工程顧問股份有限公司、清華生態顧問有限公司。', '臺北自來水事業處工程總隊', '無資料', '2025-03-11 00:00:00', '2025-03-11 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1D8F608FC6AD698C', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「直潭壩及青潭堰增設魚道可行性評估及規劃委託技術服務」生態檢核民眾參與公開說明會', `description`='本案為辦理「直潭壩及青潭堰增設魚道可行性評估及規劃委託技術服務」生態檢核，目前尚在可行性評估階段，並向在地民眾說明規劃內容，歡迎各界先進共同參與。 開會事由：本處辦理「直潭壩及青潭堰增設魚道可行性評估及規劃委託技術服務」生態檢核民眾參與公開說明會，敬請撥冗蒞臨指導。一、開會時間：中華民國114年3月11日 (星期二) 下午2時0分 。&nbsp;二、 開會地點：屈尺市民活動中心2樓禮堂（新北市新店區屈尺路125號）&nbsp;三、參加人員：各界先進、在地里民及市民朋友。&nbsp;四、主辦單位：臺北自來水事業處。&nbsp;五、可行性評估及規劃單位：中興工程顧問股份有限公司、清華生態顧問有限公司。', `organizer`='臺北自來水事業處工程總隊', `address`='無資料', `start_date`='2025-03-11 00:00:00', `end_date`='2025-03-11 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1D8F608FC6AD698C', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9367095', '客家委員會擴大辦理「來去客庄尞」短影音徵件活動簡章', '一、客家委員會為鼓勵青年走入客庄，接觸客家文化及語言，逐步建構客語環境，特舉辦「來去客庄尞」短影音徵件活動（下稱本活動），邀集青年至70個文化重點發展區的客庄旅遊，並拍攝短影音，經審核通過者，可獲得獎勵金（共6,000個名額），以帶動客庄觀光。二、活動將擴大辦理，鼓勵18歲至35歲本國籍青年（出生日期須為79年1月1日至96年12月31日間）至戶籍地鄉鎮市區以外之客家文化重點發展區旅遊並體驗客家文化，於114年6月30日前優先上傳影片且審核通過者可獲得新臺幣2,500元獎勵金。三、委辦單位：台北市電腦商業同業公會，服務電話：02-2358-4546；電子郵件信箱：ihakkatour@gmail.com。', '臺北市政府客家事務委員會', '無資料', '2025-03-04 00:00:00', '2025-06-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=611EEF418602E741', '[]') ON DUPLICATE KEY UPDATE `activity_name`='客家委員會擴大辦理「來去客庄尞」短影音徵件活動簡章', `description`='一、客家委員會為鼓勵青年走入客庄，接觸客家文化及語言，逐步建構客語環境，特舉辦「來去客庄尞」短影音徵件活動（下稱本活動），邀集青年至70個文化重點發展區的客庄旅遊，並拍攝短影音，經審核通過者，可獲得獎勵金（共6,000個名額），以帶動客庄觀光。二、活動將擴大辦理，鼓勵18歲至35歲本國籍青年（出生日期須為79年1月1日至96年12月31日間）至戶籍地鄉鎮市區以外之客家文化重點發展區旅遊並體驗客家文化，於114年6月30日前優先上傳影片且審核通過者可獲得新臺幣2,500元獎勵金。三、委辦單位：台北市電腦商業同業公會，服務電話：02-2358-4546；電子郵件信箱：ihakkatour@gmail.com。', `organizer`='臺北市政府客家事務委員會', `address`='無資料', `start_date`='2025-03-04 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=611EEF418602E741', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9367069', '景美就服站114年3月10日(一)14:00-16:00【統一超商】微型徵才活動', '活動時間：114.03.10(一)14:00-16:00活動地點：台北市文山區羅斯福路6段393號4樓(捷運景美站1號出口)&nbsp;統一超商股份有限公司門市兼職夥伴10人&nbsp;&nbsp;時薪190-200元&nbsp;職缺詳情請看附件檔案', '臺北市就業服務處', '無資料', '2025-03-10 00:00:00', '2025-03-10 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=0A875071AD9B624F', '[]') ON DUPLICATE KEY UPDATE `activity_name`='景美就服站114年3月10日(一)14:00-16:00【統一超商】微型徵才活動', `description`='活動時間：114.03.10(一)14:00-16:00活動地點：台北市文山區羅斯福路6段393號4樓(捷運景美站1號出口)&nbsp;統一超商股份有限公司門市兼職夥伴10人&nbsp;&nbsp;時薪190-200元&nbsp;職缺詳情請看附件檔案', `organizer`='臺北市就業服務處', `address`='無資料', `start_date`='2025-03-10 00:00:00', `end_date`='2025-03-10 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=0A875071AD9B624F', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9367036', '艋舺就服站114/03/12(三)下午2-4時，舉辦【地樺營造事業股份有限公司】現場徵才活動', '一、工程名稱：富邦人壽南港區玉成段新建工程案總包工程。二、職務名稱：基層技術工及勞力工。三、雇用人數：140人四、核薪方式：月薪新臺幣33,425元(依勞動部113年12月25日勞動發管字第第1130517344A號令辦理)。五、工作時間：08時00分至17時00分(含休息時間1小時)六、工作內容：搬運(約40公斤，有輔助工具)、清潔、泥土清運、支援雜項工作及其他相關體力工作，需高架作業約60米，符合職業安全衛生法及相關規定。七、工作地點：工程地點：臺北市南港區玉成段二小段723、725地號等2筆土地。 &nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;工務所地址：臺北市南港區南港路3段153號。八、供膳狀況：供膳宿(膳宿每月合計扣款最高5,000元)。九、專長資格：不拘。十、聘僱期間：至116年1月4日。', '雇主服務課', '無資料', '2025-03-12 00:00:00', '2025-03-12 00:00:00', '艋舺就服站', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=93972D414CFABA1E', '[]') ON DUPLICATE KEY UPDATE `activity_name`='艋舺就服站114/03/12(三)下午2-4時，舉辦【地樺營造事業股份有限公司】現場徵才活動', `description`='一、工程名稱：富邦人壽南港區玉成段新建工程案總包工程。二、職務名稱：基層技術工及勞力工。三、雇用人數：140人四、核薪方式：月薪新臺幣33,425元(依勞動部113年12月25日勞動發管字第第1130517344A號令辦理)。五、工作時間：08時00分至17時00分(含休息時間1小時)六、工作內容：搬運(約40公斤，有輔助工具)、清潔、泥土清運、支援雜項工作及其他相關體力工作，需高架作業約60米，符合職業安全衛生法及相關規定。七、工作地點：工程地點：臺北市南港區玉成段二小段723、725地號等2筆土地。 &nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;工務所地址：臺北市南港區南港路3段153號。八、供膳狀況：供膳宿(膳宿每月合計扣款最高5,000元)。九、專長資格：不拘。十、聘僱期間：至116年1月4日。', `organizer`='雇主服務課', `address`='無資料', `start_date`='2025-03-12 00:00:00', `end_date`='2025-03-12 00:00:00', `location`='艋舺就服站', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=93972D414CFABA1E', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('eca4e2acc402ced1b6aa750083494fac', '114年度「新北知識充電站」土城生活講座（第三場次），歡迎踴躍參加！', '本所訂於114年3月11日(星期二)晚上7時至9時，假新北市立圖書館土城分館3樓演講廳（新北市土城區中正路18號3樓）辦理「新北知識充電站」土城生活講座(第三場次)，詳細資訊如下：【主題】減重非難事‧打造好體態【講師】營佳營養諮詢中心門診部主任 吳芃彧老師＊本講座免費、免報名，每場提供20份價值 200元禮券大摸彩，並發放集點卡，每參加一場可得1點，集滿3點可兌換精美紀念品!（欲知本年度其他場次詳如附件ＤＭ）＊公務人員可登錄終身學習時數2小時、志工可領取2小時研習時數條＊因應防疫，請全程配戴口罩，謝謝＊如有疑問請電洽(02)2273-2000分機153社會人文課鄭小姐', '土城區公所', '新北市土城區中正路18號3樓', '新北市立圖書館土城分館3樓演講廳', 24.96425102, 121.445737, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度「新北知識充電站」土城生活講座（第三場次），歡迎踴躍參加！', `description`='本所訂於114年3月11日(星期二)晚上7時至9時，假新北市立圖書館土城分館3樓演講廳（新北市土城區中正路18號3樓）辦理「新北知識充電站」土城生活講座(第三場次)，詳細資訊如下：【主題】減重非難事‧打造好體態【講師】營佳營養諮詢中心門診部主任 吳芃彧老師＊本講座免費、免報名，每場提供20份價值 200元禮券大摸彩，並發放集點卡，每參加一場可得1點，集滿3點可兌換精美紀念品!（欲知本年度其他場次詳如附件ＤＭ）＊公務人員可登錄終身學習時數2小時、志工可領取2小時研習時數條＊因應防疫，請全程配戴口罩，謝謝＊如有疑問請電洽(02)2273-2000分機153社會人文課鄭小姐', `organizer`='土城區公所', `address`='新北市土城區中正路18號3樓', `location`='新北市立圖書館土城分館3樓演講廳', `latitude`=24.96425102, `longitude`=121.445737, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67463cee26b324689882a2af', 'Kacacefelisan 交會：阿美陶文化特展', '本次展覽以花蓮縣壽豐鄉豐田地區的臺灣閃玉礦產業為焦點，重現民國50年代的產業盛況。展覽將透過動態影像、聲音營造、學習體驗等多種展示教育資源，讓觀眾能夠身臨其境地感受當時閃玉礦業帶動臺灣玉產業的各個階段，從開礦、加工到銷售的全貌。此外，展覽還將展示豐富的文獻、照片、物件等資料，讓觀者對這段歷史產生深刻的情感連結。展覽籌備過程中，考古博物館積極與在地居民合作，反映他們探索、蒐整及解釋自己歷史的需求，真正體現了社區博物館的精神。\r\n值得一提的是，展覽場地本身就是一座饒富歷史意義的建築，現今的花蓮縣考古博物館二館前身是豐田村移民指導所事務室，其建築物可追溯至日治時期，原為移民村行政中心。戰後，這座建築又曾作為國語教學民教班和豐裡國小輔導教室使用，它見證了豐田地區村落發展的各個階段，凝聚了不同時代住民的生活記憶，選擇這樣一個富有歷史底蘊的場地舉辦臺灣玉產業歷史特展，更增添了展覽的深度和意義。', '花蓮縣文化局', '花蓮縣壽豐鄉', '2025-01-01 00:00:00', '2025-04-20 00:00:00', '壽豐鄉（花蓮縣）=', 23.84459714, 121.5341569, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Kacacefelisan 交會：阿美陶文化特展', `description`='本次展覽以花蓮縣壽豐鄉豐田地區的臺灣閃玉礦產業為焦點，重現民國50年代的產業盛況。展覽將透過動態影像、聲音營造、學習體驗等多種展示教育資源，讓觀眾能夠身臨其境地感受當時閃玉礦業帶動臺灣玉產業的各個階段，從開礦、加工到銷售的全貌。此外，展覽還將展示豐富的文獻、照片、物件等資料，讓觀者對這段歷史產生深刻的情感連結。展覽籌備過程中，考古博物館積極與在地居民合作，反映他們探索、蒐整及解釋自己歷史的需求，真正體現了社區博物館的精神。\r\n值得一提的是，展覽場地本身就是一座饒富歷史意義的建築，現今的花蓮縣考古博物館二館前身是豐田村移民指導所事務室，其建築物可追溯至日治時期，原為移民村行政中心。戰後，這座建築又曾作為國語教學民教班和豐裡國小輔導教室使用，它見證了豐田地區村落發展的各個階段，凝聚了不同時代住民的生活記憶，選擇這樣一個富有歷史底蘊的場地舉辦臺灣玉產業歷史特展，更增添了展覽的深度和意義。', `organizer`='花蓮縣文化局', `address`='花蓮縣壽豐鄉', `start_date`='2025-01-01 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='壽豐鄉（花蓮縣）=', `latitude`=23.84459714, `longitude`=121.5341569, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
