INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8edf88f15adefa04e0c70', '【日午音樂會174】笛簫重奏與競奏', '笛與簫一向是以獨奏姿態出現在舞台上，笛簫協會本著獨樂樂不如眾樂樂的宗旨，開拓笛簫新的演奏形式，通過重奏與競奏，展現樂器的對話與表現力，探索其音質對比、和諧與競爭的藝術美感。\r\n\r\n本場音樂會內容豐富，一半以上都是首演曲目，從台灣民歌到山東、陝西、新疆，再到日本、美國，還有以金庸武俠小說為題的《玉女心經》。除了笛簫協會北區優秀會員外，一向對各類笛簫都有涉獵的西洋長笛名家華姵，也將應邀演奏陳氏半音簫，與理事長合奏爵士風的兩首樂曲。\r\n\r\n■演出：臺灣笛簫協會北區會員\r\n笛、蕭｜陳中申、劉穎蓉、王煜凱、華姵（客席，長笛藝術家）、成心如、陳靜、蕭力升、林以政、張貴茂、周炎生\r\n鋼琴｜林上傑\r\n\r\n■時間：2025年5 月4 日（日）14:30（遲到或中途離場的聽眾至中場休息方可入場，建議提早抵達）\r\n\r\n■地點：林建生紀念圖書館演奏廳（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額200位，七歲以上，免費報名入場。\r\n#恕無現場後補\r\n\r\n■報名方式：  4月24日（四）10:00 起，網路報名： https://www.accupass.com/go/1140504\r\n\r\n**80歲以上長者可電話報名：02-22855188\r\n\r\n■演出曲目 :  \r\n（一） 二重奏 \r\n宮田耕八朗：五月的歌（尺八、洞簫二重奏）\r\n劉穎蓉：皐月（尺八、洞簫二重奏）\r\n台灣客家民歌：蟾蜍囉（把烏、笛子二重奏）\r\n民間音樂：金蛇狂舞（笛子二重奏）\r\n山東民間音樂：喜新婚（笛子二重奏）\r\n\r\n（二）半音簫、長笛二重奏\r\n 哈萊恩・李：向星星許願\r\n科茲馬・約瑟夫：枯葉 \r\n\r\n（三）笛子三重奏 \r\n新疆民歌：手挽手\r\n陳揚、陳中申：結婚\r\n\r\n（四）笛簫競奏 : \r\n陳中申：玉女心經（半音笛簫雙協奏）\r\n陳中申：草螟弄雞公（笛子雙協奏）\r\n\r\n （五）笛簫合奏\r\n土井啟輔：流星夜樂\r\n傑拉瑪・威卓達：啤酒桶波爾卡\r\n\r\n', '財團法人紀念林建生教育基金會、臺灣笛簫協會', '新北市蘆洲區三民路178號', '2025-05-04 00:00:00', '2025-05-04 00:00:00', '林建生紀念圖書館', 25.08927173, 121.4712461, '七歲以上，免費報名入場', 'https://www.accupass.com/go/1140504', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【日午音樂會174】笛簫重奏與競奏', `description`='笛與簫一向是以獨奏姿態出現在舞台上，笛簫協會本著獨樂樂不如眾樂樂的宗旨，開拓笛簫新的演奏形式，通過重奏與競奏，展現樂器的對話與表現力，探索其音質對比、和諧與競爭的藝術美感。\r\n\r\n本場音樂會內容豐富，一半以上都是首演曲目，從台灣民歌到山東、陝西、新疆，再到日本、美國，還有以金庸武俠小說為題的《玉女心經》。除了笛簫協會北區優秀會員外，一向對各類笛簫都有涉獵的西洋長笛名家華姵，也將應邀演奏陳氏半音簫，與理事長合奏爵士風的兩首樂曲。\r\n\r\n■演出：臺灣笛簫協會北區會員\r\n笛、蕭｜陳中申、劉穎蓉、王煜凱、華姵（客席，長笛藝術家）、成心如、陳靜、蕭力升、林以政、張貴茂、周炎生\r\n鋼琴｜林上傑\r\n\r\n■時間：2025年5 月4 日（日）14:30（遲到或中途離場的聽眾至中場休息方可入場，建議提早抵達）\r\n\r\n■地點：林建生紀念圖書館演奏廳（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額200位，七歲以上，免費報名入場。\r\n#恕無現場後補\r\n\r\n■報名方式：  4月24日（四）10:00 起，網路報名： https://www.accupass.com/go/1140504\r\n\r\n**80歲以上長者可電話報名：02-22855188\r\n\r\n■演出曲目 :  \r\n（一） 二重奏 \r\n宮田耕八朗：五月的歌（尺八、洞簫二重奏）\r\n劉穎蓉：皐月（尺八、洞簫二重奏）\r\n台灣客家民歌：蟾蜍囉（把烏、笛子二重奏）\r\n民間音樂：金蛇狂舞（笛子二重奏）\r\n山東民間音樂：喜新婚（笛子二重奏）\r\n\r\n（二）半音簫、長笛二重奏\r\n 哈萊恩・李：向星星許願\r\n科茲馬・約瑟夫：枯葉 \r\n\r\n（三）笛子三重奏 \r\n新疆民歌：手挽手\r\n陳揚、陳中申：結婚\r\n\r\n（四）笛簫競奏 : \r\n陳中申：玉女心經（半音笛簫雙協奏）\r\n陳中申：草螟弄雞公（笛子雙協奏）\r\n\r\n （五）笛簫合奏\r\n土井啟輔：流星夜樂\r\n傑拉瑪・威卓達：啤酒桶波爾卡\r\n\r\n', `organizer`='財團法人紀念林建生教育基金會、臺灣笛簫協會', `address`='新北市蘆洲區三民路178號', `start_date`='2025-05-04 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='林建生紀念圖書館', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='七歲以上，免費報名入場', `source_url`='https://www.accupass.com/go/1140504', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c9070f07f3d4433af95549', 'EMBA雜誌我們學堂-03月場(20250320)', '每月一堂90分鐘真人線上課，\r\n邀請資深領導人與顧問分享經驗，\r\n搭配專屬網站看回放，以及閱讀影音文章，協助提升專業與領導能力。\r\n歡迎參加「我們學堂」，用最沒有壓力的方式一起成長。\r\n\r\n\r\n\r\n2025年03月【我們學堂】吸引人才與留住人才\r\n重量級導師：陽明交大兼任副教授 李河泉\r\n課程時間：2025.03.20(四) 19:30-21:00 Zoom會議室\r\n\r\n\r\n\r\n【我們學堂】標竿企業領導人都在參加的線上課程 「我們學堂」是EMBA雜誌為新一代主管推出的學習計畫。\r\n每月一堂90分鐘真人線上課，邀請傑出資深領導人分享經驗，搭配影片回放，網站影音、文章閱讀，解答你的困惑。\r\n\r\n\r\n\r\n費用：1年12個主題特別優惠價 3600 元 (原價4800元)\r\n了解更多>>https://reademba.pse.is/4ujrek\r\n\r\n\r\n', 'EMBA雜誌', '臺北市松山區', '2025-03-20 00:00:00', '2025-03-20 00:00:00', 'Zoom會議室', 25.05999101, 121.5575876, '一年12期特惠價 | 3600元（原價4800元）', 'https://www.shopemba.com/products/learning', '[]') ON DUPLICATE KEY UPDATE `activity_name`='EMBA雜誌我們學堂-03月場(20250320)', `description`='每月一堂90分鐘真人線上課，\r\n邀請資深領導人與顧問分享經驗，\r\n搭配專屬網站看回放，以及閱讀影音文章，協助提升專業與領導能力。\r\n歡迎參加「我們學堂」，用最沒有壓力的方式一起成長。\r\n\r\n\r\n\r\n2025年03月【我們學堂】吸引人才與留住人才\r\n重量級導師：陽明交大兼任副教授 李河泉\r\n課程時間：2025.03.20(四) 19:30-21:00 Zoom會議室\r\n\r\n\r\n\r\n【我們學堂】標竿企業領導人都在參加的線上課程 「我們學堂」是EMBA雜誌為新一代主管推出的學習計畫。\r\n每月一堂90分鐘真人線上課，邀請傑出資深領導人分享經驗，搭配影片回放，網站影音、文章閱讀，解答你的困惑。\r\n\r\n\r\n\r\n費用：1年12個主題特別優惠價 3600 元 (原價4800元)\r\n了解更多>>https://reademba.pse.is/4ujrek\r\n\r\n\r\n', `organizer`='EMBA雜誌', `address`='臺北市松山區', `start_date`='2025-03-20 00:00:00', `end_date`='2025-03-20 00:00:00', `location`='Zoom會議室', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='一年12期特惠價 | 3600元（原價4800元）', `source_url`='https://www.shopemba.com/products/learning', `image_url`='[]';
