INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0b9d26b32408680bea16', '【藝文講座】節氣．情詩．台灣島～周蘇宗台語詩', '周蘇宗先生為熱心公益的慈善家和閩南語詩人，其詩作《斯卡羅戰歌》獲「教育部第八屆閩客文學獎」閩南語現代詩社會組首獎。周老師經多年浸淫研究，將台語「文、語、字」一體到位，並用在台語詩的創作上。\r\n\r\n講座中，將發表其最近作品《風吹》詩集中的多首新作，同時將詩詞與音樂創作結合，更顯台語之美。期盼透過台語詩的吟唱改變大家對台語的刻板印象，共同領略台語之美！\r\n\r\n■時間：2025年3月15日（六）14：00-16：00\r\n■地點：林建生紀念圖書館地下樓（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額180位，七歲以上，免費報名入場。\r\n\r\n■報名方式：3/5（三）10:00起，網路報名  https://www.accupass.com/go/1140315\r\n#額滿後恕無現場報名\r\n\r\n■講者：周蘇宗（詩人）\r\n\r\n★凡參加講座者，將獲贈《風吹》詩集一本。\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★網址： https://www.ljsedu.org.tw\r\n★歡迎加入《林建生基金會》line 好友～ https://bit.ly/2KFVgg2\r\n', '財團法人紀念林建生文教基金會', '新北市蘆洲區三民路178號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '林建生紀念圖書館', 25.08927173, 121.4712461, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【藝文講座】節氣．情詩．台灣島～周蘇宗台語詩', `description`='周蘇宗先生為熱心公益的慈善家和閩南語詩人，其詩作《斯卡羅戰歌》獲「教育部第八屆閩客文學獎」閩南語現代詩社會組首獎。周老師經多年浸淫研究，將台語「文、語、字」一體到位，並用在台語詩的創作上。\r\n\r\n講座中，將發表其最近作品《風吹》詩集中的多首新作，同時將詩詞與音樂創作結合，更顯台語之美。期盼透過台語詩的吟唱改變大家對台語的刻板印象，共同領略台語之美！\r\n\r\n■時間：2025年3月15日（六）14：00-16：00\r\n■地點：林建生紀念圖書館地下樓（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額180位，七歲以上，免費報名入場。\r\n\r\n■報名方式：3/5（三）10:00起，網路報名  https://www.accupass.com/go/1140315\r\n#額滿後恕無現場報名\r\n\r\n■講者：周蘇宗（詩人）\r\n\r\n★凡參加講座者，將獲贈《風吹》詩集一本。\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★網址： https://www.ljsedu.org.tw\r\n★歡迎加入《林建生基金會》line 好友～ https://bit.ly/2KFVgg2\r\n', `organizer`='財團法人紀念林建生文教基金會', `address`='新北市蘆洲區三民路178號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='林建生紀念圖書館', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
