INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0b9e26b32408680bea1b', '【淡海小書房】114年3月主題書展 :《搭地鐵玩遍世界》', '「搭地鐵玩遍世界」主題書展\r\n\r\n時間：3/1(六)-3/31(一) 開館時間\r\n地點：淡海小書房（淡水區中正東路2段68號）\r\n電話：02-2808-0400\r\n\r\n簡介：\r\n旅行是煩悶、忙碌生活的最佳調劑，近年來自由行更是蔚為風潮，因此善用鐡路進行有效率的移動方式，怎麼買票最划算、怎樣安排路線最方便，既能省錢、又能玩得開心也玩得安全，書中整理了所有的資訊，讓讀者能一目瞭然。\r\n\r\n\r\n備註：\r\n1.開館時間為每日11時至19時。\r\n2.3月27日(四)清館日，不對外開放。', '新北市立圖書館總館', '新北市淡水區中正東路2段68號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '淡海小書房', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【淡海小書房】114年3月主題書展 :《搭地鐵玩遍世界》', `description`='「搭地鐵玩遍世界」主題書展\r\n\r\n時間：3/1(六)-3/31(一) 開館時間\r\n地點：淡海小書房（淡水區中正東路2段68號）\r\n電話：02-2808-0400\r\n\r\n簡介：\r\n旅行是煩悶、忙碌生活的最佳調劑，近年來自由行更是蔚為風潮，因此善用鐡路進行有效率的移動方式，怎麼買票最划算、怎樣安排路線最方便，既能省錢、又能玩得開心也玩得安全，書中整理了所有的資訊，讓讀者能一目瞭然。\r\n\r\n\r\n備註：\r\n1.開館時間為每日11時至19時。\r\n2.3月27日(四)清館日，不對外開放。', `organizer`='新北市立圖書館總館', `address`='新北市淡水區中正東路2段68號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='淡海小書房', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0b9e26b32408680bea1c', '【新北市立圖書館淡水分館】2/14(五)-3/9(日) 【淡水與我】- 佘心婷藝術創作個展', '【淡水與我】- 佘心婷藝術創作個展\r\n時間：2/14(五)-3/9(日) 08:30-17:00\r\n地點：淡水分館B1藝文中心（淡水區文化路65號）\r\n電話：02-2622-4664分機224\r\n\r\n簡介：\r\n    長期關注環境變遷與社會議題的佘心婷，經常藉由生活之多重面向反思並進行創作。創作多以纖維材質作為主要媒材，藉由當代的藝術形式，嘗試在藝術與生活中探索更多元之可能性。作品主要透過現地製作、裝置及多媒材方式呈現。\r\n    進駐淡水期間，通過田野踏查、植物收集與歷史空間探訪。以日常生活與個人視角來進行探索，點滴累積串起與淡水這塊土地的連結。本次展覽的作品，是將踏查淡水期間所收集到的植物集合在一起，並以不同的方式來呈現。有些透過加工處理，有些保有自然發展的樣貌，有些則經由媒介轉化。在這些重複踏查、持續收集與反覆勞動的日子裡。總是會引領著我不斷去思考，社會在追求發展的同時，那些被我們捨棄或遺忘的東西。\r\n\r\n\r\n備註：2/27清館日、2/28和平紀念日  休館\r\n', '新北市立圖書館總館', '新北市淡水區文化路65號', '2025-02-14 00:00:00', '2025-03-09 00:00:00', '新北市立圖書館淡水分館', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡水分館】2/14(五)-3/9(日) 【淡水與我】- 佘心婷藝術創作個展', `description`='【淡水與我】- 佘心婷藝術創作個展\r\n時間：2/14(五)-3/9(日) 08:30-17:00\r\n地點：淡水分館B1藝文中心（淡水區文化路65號）\r\n電話：02-2622-4664分機224\r\n\r\n簡介：\r\n    長期關注環境變遷與社會議題的佘心婷，經常藉由生活之多重面向反思並進行創作。創作多以纖維材質作為主要媒材，藉由當代的藝術形式，嘗試在藝術與生活中探索更多元之可能性。作品主要透過現地製作、裝置及多媒材方式呈現。\r\n    進駐淡水期間，通過田野踏查、植物收集與歷史空間探訪。以日常生活與個人視角來進行探索，點滴累積串起與淡水這塊土地的連結。本次展覽的作品，是將踏查淡水期間所收集到的植物集合在一起，並以不同的方式來呈現。有些透過加工處理，有些保有自然發展的樣貌，有些則經由媒介轉化。在這些重複踏查、持續收集與反覆勞動的日子裡。總是會引領著我不斷去思考，社會在追求發展的同時，那些被我們捨棄或遺忘的東西。\r\n\r\n\r\n備註：2/27清館日、2/28和平紀念日  休館\r\n', `organizer`='新北市立圖書館總館', `address`='新北市淡水區文化路65號', `start_date`='2025-02-14 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='新北市立圖書館淡水分館', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0b9e26b32408680bea1d', '【新北市立圖書館淡水分館】《3月主題書展 : 巴哈姆特ACG創作大賽》', '《巴哈姆特ACG創作大賽》\r\n\r\n\r\n時間：3/3(一)-3/30(日)\r\n地點：淡水分館3F漫畫區\r\n（淡水區文化路65號3F）\r\n電話：02-26224664\r\n\r\n簡介：\r\n「巴哈姆特ACG創作大賽」是當代台灣年輕人的年度盛事，不僅是年輕人展現才華的舞台，更是年輕人透過網路投票凝聚認同的關鍵時刻。「ACG創作大賽」共分為「動畫組」、「漫畫組」、「遊戲組」三大賽事組別，並串連廠商贊助增設各類特別獎項，自2012年開辦至今培養不少台灣漫迷和創作者。身為台灣人我們必須認識這股原創的力量。', '新北市立圖書館總館', '新北市淡水區文化路65號', '2025-03-03 00:00:00', '2025-03-30 00:00:00', '新北市立圖書館淡水分館', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡水分館】《3月主題書展 : 巴哈姆特ACG創作大賽》', `description`='《巴哈姆特ACG創作大賽》\r\n\r\n\r\n時間：3/3(一)-3/30(日)\r\n地點：淡水分館3F漫畫區\r\n（淡水區文化路65號3F）\r\n電話：02-26224664\r\n\r\n簡介：\r\n「巴哈姆特ACG創作大賽」是當代台灣年輕人的年度盛事，不僅是年輕人展現才華的舞台，更是年輕人透過網路投票凝聚認同的關鍵時刻。「ACG創作大賽」共分為「動畫組」、「漫畫組」、「遊戲組」三大賽事組別，並串連廠商贊助增設各類特別獎項，自2012年開辦至今培養不少台灣漫迷和創作者。身為台灣人我們必須認識這股原創的力量。', `organizer`='新北市立圖書館總館', `address`='新北市淡水區文化路65號', `start_date`='2025-03-03 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='新北市立圖書館淡水分館', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0b9f26b32408680bea1e', 'Fun  心聽故事(林園二館114年04月)', '由高雄市立圖書館所培訓一群義務及熱情的故事志工伙伴，\r\n透過豐富的肢體語言及生動活潑表情演出，\r\n每週六將帶來不同驚奇、有趣、精彩動聽的故事，\r\n不僅為小朋友們說故事、更帶領小朋友們與家長間的親子互動與閱讀推廣，\r\n享受親子間的閱讀樂趣。\r\n每週六上午10點-11點，將在林園二館 2F 兒童閱覽室演出，每場將有意想不到的精采故事，邀請喜愛聽故事的大朋友、小朋友們，一同大手牽小手，相約到林園二館聽故事唷~', '高雄市立圖書館總館', '高雄市林園區中芸里西溪路56~20號2樓', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '高雄市立圖書館林園二館', 22.4875473, 120.3929374, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Fun  心聽故事(林園二館114年04月)', `description`='由高雄市立圖書館所培訓一群義務及熱情的故事志工伙伴，\r\n透過豐富的肢體語言及生動活潑表情演出，\r\n每週六將帶來不同驚奇、有趣、精彩動聽的故事，\r\n不僅為小朋友們說故事、更帶領小朋友們與家長間的親子互動與閱讀推廣，\r\n享受親子間的閱讀樂趣。\r\n每週六上午10點-11點，將在林園二館 2F 兒童閱覽室演出，每場將有意想不到的精采故事，邀請喜愛聽故事的大朋友、小朋友們，一同大手牽小手，相約到林園二館聽故事唷~', `organizer`='高雄市立圖書館總館', `address`='高雄市林園區中芸里西溪路56~20號2樓', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄市立圖書館林園二館', `latitude`=22.4875473, `longitude`=120.3929374, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0ba026b32408680bea1f', '【日午音樂會172】董運昌指彈演奏會2025', '臺灣指彈吉他（Finger-Style Guitar）先驅，有「吉他詩人」之稱的董運昌，同時也是第10、14及第16屆金曲獎「最佳流行音樂演奏唱片獎」及「最佳流行音樂演奏專輯獎」得主。今年2025年適逢民歌50，董運昌將帶來數首民歌演奏版、鋼弦吉他經典曲目，以及曾經引領風潮的原創曲。\r\n\r\n■演出： 吉他｜董運昌\r\n\r\n■時間：2025年3月23日（日）14:30（遲到或中途離場的聽眾至中場休息方可入場，建議提早抵達）\r\n\r\n■地點：林建生紀念圖書館演奏廳（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額200位，七歲以上，免費報名入場。\r\n#恕無現場後補\r\n\r\n■報名方式：3月13 日（四）10:00 起，網路報名：　https://www.accupass.com/go/1140323\r\n\r\n■演出曲目：\r\n左岸印象、淚光閃閃、民歌組曲、雪落下的聲音、雪之華 、缺角地圖、阿爾罕布拉宮的回憶、南都夜曲、快樂的出航…等\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★歡迎加入Line 好友： https://bit.ly/2KFVgg2\r\n', '財團法人紀念林建生文教基金會', '新北市蘆洲區三民路178號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '林建生紀念圖書館', 25.08927173, 121.4712461, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【日午音樂會172】董運昌指彈演奏會2025', `description`='臺灣指彈吉他（Finger-Style Guitar）先驅，有「吉他詩人」之稱的董運昌，同時也是第10、14及第16屆金曲獎「最佳流行音樂演奏唱片獎」及「最佳流行音樂演奏專輯獎」得主。今年2025年適逢民歌50，董運昌將帶來數首民歌演奏版、鋼弦吉他經典曲目，以及曾經引領風潮的原創曲。\r\n\r\n■演出： 吉他｜董運昌\r\n\r\n■時間：2025年3月23日（日）14:30（遲到或中途離場的聽眾至中場休息方可入場，建議提早抵達）\r\n\r\n■地點：林建生紀念圖書館演奏廳（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額200位，七歲以上，免費報名入場。\r\n#恕無現場後補\r\n\r\n■報名方式：3月13 日（四）10:00 起，網路報名：　https://www.accupass.com/go/1140323\r\n\r\n■演出曲目：\r\n左岸印象、淚光閃閃、民歌組曲、雪落下的聲音、雪之華 、缺角地圖、阿爾罕布拉宮的回憶、南都夜曲、快樂的出航…等\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★歡迎加入Line 好友： https://bit.ly/2KFVgg2\r\n', `organizer`='財團法人紀念林建生文教基金會', `address`='新北市蘆洲區三民路178號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='林建生紀念圖書館', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0ba226b32408680bea20', '張正傑親子音樂會-大提琴找新娘 ', '正傑叔叔的愛琴「盧傑利」突然有了結婚的念頭,人可以結婚,那樂器呢?\r\n「張正傑親子音樂會-大提琴找新娘」特別邀請親子天王主持人-趙自強 擔任媒婆,為盧傑利\r\n推薦東西方音樂世界的候選新娘,猜猜誰是新娘候選人? 新娘候選人之間是火花四射,還是\r\n意外鬧劇!?\r\n', '花格子藝術有限公司', '臺南市東區中華東路三段332號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '300元、200元(12歲以下)+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='張正傑親子音樂會-大提琴找新娘 ', `description`='正傑叔叔的愛琴「盧傑利」突然有了結婚的念頭,人可以結婚,那樂器呢?\r\n「張正傑親子音樂會-大提琴找新娘」特別邀請親子天王主持人-趙自強 擔任媒婆,為盧傑利\r\n推薦東西方音樂世界的候選新娘,猜猜誰是新娘候選人? 新娘候選人之間是火花四射,還是\r\n意外鬧劇!?\r\n', `organizer`='花格子藝術有限公司', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='300元、200元(12歲以下)+--', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0ba326b32408680bea21', '假日廣場--鳴馨歌唱音樂坊《臺灣百年金曲演唱》', '臺灣百年金曲演唱會所提共的演唱曲目內容豐富多元，從早期的民謠、\r\n戒嚴時期的禁歌、清新雋永的民歌、風行一時的舞曲、最新的流行音樂...等等。一\r\n首首娓娓動聽的經典名曲，重新見證臺灣的歷史變遷，對時代背景的情感有了深度\r\n的了解與認同，進而跨越了歷史的鴻溝，接受了流行音樂的美與藝術，無形中增添\r\n了市民們好的人文素養。我們將有力量的歌聲傳達給每一位聆聽者，幫助參與的聽\r\n眾們都能透過好的歌曲淨化心靈，紓解壓力，降低痛苦指數，對社會充滿期待，對\r\n人生充滿希望。\r\n鳴馨歌唱音樂坊在蘇中民團長的帶領下，是由一群熱愛唱歌，堅持要發揚臺南在地\r\n本土文化的社會人士所組成，希望藉由傳唱，將值得珍藏的歌如同珍貴的歷史蹟，留給後代子孫，綿延不絕。\r\n', '鳴馨歌唱音樂坊', '臺南市東區中華東路三段332號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='假日廣場--鳴馨歌唱音樂坊《臺灣百年金曲演唱》', `description`='臺灣百年金曲演唱會所提共的演唱曲目內容豐富多元，從早期的民謠、\r\n戒嚴時期的禁歌、清新雋永的民歌、風行一時的舞曲、最新的流行音樂...等等。一\r\n首首娓娓動聽的經典名曲，重新見證臺灣的歷史變遷，對時代背景的情感有了深度\r\n的了解與認同，進而跨越了歷史的鴻溝，接受了流行音樂的美與藝術，無形中增添\r\n了市民們好的人文素養。我們將有力量的歌聲傳達給每一位聆聽者，幫助參與的聽\r\n眾們都能透過好的歌曲淨化心靈，紓解壓力，降低痛苦指數，對社會充滿期待，對\r\n人生充滿希望。\r\n鳴馨歌唱音樂坊在蘇中民團長的帶領下，是由一群熱愛唱歌，堅持要發揚臺南在地\r\n本土文化的社會人士所組成，希望藉由傳唱，將值得珍藏的歌如同珍貴的歷史蹟，留給後代子孫，綿延不絕。\r\n', `organizer`='鳴馨歌唱音樂坊', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0ba926b32408680bea22', '【中市圖沙鹿深波分館】胡潤英油畫創作展', '胡潤英油畫創作展\r\n  本次展覽精選沙鹿在地藝術家胡潤英的代表性油畫作品，帶領觀眾感受他多年的創作歷程與藝術熱情。將以個展形式呈現，展出包括《沙鹿深波圖書館》、《鬥牛士》、《歲月》等30餘幅精彩油畫作品。胡潤英的作品以鮮明的色彩、豐富的層次感及細膩的筆觸著稱，充分展現其對自然、生活與人文的深刻觀察與感悟。作品中的油彩層次與流動筆觸，不僅彰顯出創作者內心的澎湃熱情，更訴說著他在繪畫世界中的心靈旅程。\r\n◇畫家介紹：胡潤英自106年開始學習油畫，啟蒙於東海，師承邱建銘老師，108年繼續跟隨陳威杰老師深造，110年轉至長青學苑，師從阮麗英老師。作為台中市青溪文藝學會總幹事，他積極參與多場聯展，展覽足跡遍及地方稅務局沙鹿分局、港區藝術中心、葫蘆墩文化中心及署立豐原醫院等地。\r\nFB:https://pse.is/749uvq\r\nIG:https://pse.is/749uxq\r\n★展覽時間：114/02/07(五)-114/03/30(日)\r\n★展覽地點：沙鹿深波分館 1樓、2樓\r\n', '臺中市立圖書館沙鹿深波分館', '臺中市沙鹿區鎮南路二段 488號', '2025-02-07 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館沙鹿深波分館', 24.23425212, 120.5838628, '無資料', 'https://pse.is/749uvq', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖沙鹿深波分館】胡潤英油畫創作展', `description`='胡潤英油畫創作展\r\n  本次展覽精選沙鹿在地藝術家胡潤英的代表性油畫作品，帶領觀眾感受他多年的創作歷程與藝術熱情。將以個展形式呈現，展出包括《沙鹿深波圖書館》、《鬥牛士》、《歲月》等30餘幅精彩油畫作品。胡潤英的作品以鮮明的色彩、豐富的層次感及細膩的筆觸著稱，充分展現其對自然、生活與人文的深刻觀察與感悟。作品中的油彩層次與流動筆觸，不僅彰顯出創作者內心的澎湃熱情，更訴說著他在繪畫世界中的心靈旅程。\r\n◇畫家介紹：胡潤英自106年開始學習油畫，啟蒙於東海，師承邱建銘老師，108年繼續跟隨陳威杰老師深造，110年轉至長青學苑，師從阮麗英老師。作為台中市青溪文藝學會總幹事，他積極參與多場聯展，展覽足跡遍及地方稅務局沙鹿分局、港區藝術中心、葫蘆墩文化中心及署立豐原醫院等地。\r\nFB:https://pse.is/749uvq\r\nIG:https://pse.is/749uxq\r\n★展覽時間：114/02/07(五)-114/03/30(日)\r\n★展覽地點：沙鹿深波分館 1樓、2樓\r\n', `organizer`='臺中市立圖書館沙鹿深波分館', `address`='臺中市沙鹿區鎮南路二段 488號', `start_date`='2025-02-07 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館沙鹿深波分館', `latitude`=24.23425212, `longitude`=120.5838628, `ticket_price`='無資料', `source_url`='https://pse.is/749uvq', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0ba926b32408680bea23', '【中市圖沙鹿深波分館】張凌文電影收藏展：「電火戲1895~1965」', '張凌文電影收藏展：「電火戲1895~1965」\r\n沙鹿深波電影圖書館 跨館合作再添一樁❗\r\n\r\n「電火戲 1895~1965 張凌文電影收藏展」巡展 🎥 即將來到最後一站！從3月3日起，展覽將移師至靜宜大學蓋夏圖書館，並持續至6月19日！\r\n電影放映機收藏家張凌文，綽號「電影文」，從國中時期便開始製作簡易電影放映機，並在一生中不遺餘力地收藏各式各樣的放映機、膠卷、海報及劇照等珍貴電影文物。40多年來，他累積了超過700台不同規格的放映機，涵蓋35毫米、16毫米、9.5毫米、8毫米等各種規格；影片收藏則多達1,000部，包含了全球首部公開放映的電影以及台灣早期的家庭紀錄片。他的家猶如一座小型影像博物館，承載著豐富的電影歷史。🎬✨\r\n\r\n熱愛電影的朋友們，千萬別錯過這次機會！歡迎前來靜宜大學蓋夏圖書館，欣賞「電火戲」的獨特魅力，一同感受電影的魔力與情感！\r\n\r\n★活動網址：https://pse.is/75894h\r\n🎬 指導單位 🎬\r\n臺中市政府\r\n🎬 主辦單位 🎬\r\n臺中市立圖書館、臺中市立圖書館沙鹿深波分館、臺中市影視發展基金會\r\n🎬 合作單位 🎬\r\n靜宜大學蓋夏圖書館、逢甲大學\r\n🎬 場地協力 🎬\r\n中山73影視藝文空間', '財團法人臺中市影視發展基金會', '臺中市沙鹿區臺灣大道7段200號', '2025-03-03 00:00:00', '2025-06-19 00:00:00', '靜宜大學', 24.23425212, 120.5838628, '無資料', 'https://pse.is/768vrr', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖沙鹿深波分館】張凌文電影收藏展：「電火戲1895~1965」', `description`='張凌文電影收藏展：「電火戲1895~1965」\r\n沙鹿深波電影圖書館 跨館合作再添一樁❗\r\n\r\n「電火戲 1895~1965 張凌文電影收藏展」巡展 🎥 即將來到最後一站！從3月3日起，展覽將移師至靜宜大學蓋夏圖書館，並持續至6月19日！\r\n電影放映機收藏家張凌文，綽號「電影文」，從國中時期便開始製作簡易電影放映機，並在一生中不遺餘力地收藏各式各樣的放映機、膠卷、海報及劇照等珍貴電影文物。40多年來，他累積了超過700台不同規格的放映機，涵蓋35毫米、16毫米、9.5毫米、8毫米等各種規格；影片收藏則多達1,000部，包含了全球首部公開放映的電影以及台灣早期的家庭紀錄片。他的家猶如一座小型影像博物館，承載著豐富的電影歷史。🎬✨\r\n\r\n熱愛電影的朋友們，千萬別錯過這次機會！歡迎前來靜宜大學蓋夏圖書館，欣賞「電火戲」的獨特魅力，一同感受電影的魔力與情感！\r\n\r\n★活動網址：https://pse.is/75894h\r\n🎬 指導單位 🎬\r\n臺中市政府\r\n🎬 主辦單位 🎬\r\n臺中市立圖書館、臺中市立圖書館沙鹿深波分館、臺中市影視發展基金會\r\n🎬 合作單位 🎬\r\n靜宜大學蓋夏圖書館、逢甲大學\r\n🎬 場地協力 🎬\r\n中山73影視藝文空間', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市沙鹿區臺灣大道7段200號', `start_date`='2025-03-03 00:00:00', `end_date`='2025-06-19 00:00:00', `location`='靜宜大學', `latitude`=24.23425212, `longitude`=120.5838628, `ticket_price`='無資料', `source_url`='https://pse.is/768vrr', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0ba926b32408680bea24', '【中市圖沙鹿深波分館】3月【收藏電影的人 李建成導演 x 張凌文先生】 映後座談', '【收藏電影的人 李建成導演 x 張凌文先生】 映後座談\r\n⧐時間｜114年3月13日（四）15:10-17:00\r\n⧐地點｜靜宜大學蓋夏圖書館 2樓 音樂欣賞室\r\n\r\n為了更深入了解電影收藏的奧秘與魅力，我們誠摯邀請您參加由李建成導演與張凌文先生共同主持的映後座談會。在這場座談中，兩位電影收藏領域的專家將分享他們的故事與經驗，深入探討電影收藏與保存的價值，並與觀眾交流他們對電影的熱愛與執著。這將是一場充滿啟發與感動的對話，讓電影愛好者能夠更全面地理解電影收藏背後的意義。\r\n\r\n無論您是影迷、電影研究者，或是對電影歷史有興趣的朋友，都不容錯過這次難得的機會！\r\n沙鹿深波圖書館「暖心 善心」 邀請您蒞臨靜宜大學蓋夏圖書館，與我們一起探索電影收藏的魅力與深度，感受電影背後隱藏的故事與情感。\r\n\r\n報名網址：https://reurl.cc/DKE40d', '財團法人臺中市影視發展基金會', '臺中市沙鹿區臺灣大道7段200號', '2025-03-13 00:00:00', '2025-03-13 00:00:00', '靜宜大學', 24.23425212, 120.5838628, '無資料', 'https://pse.is/768yyk', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖沙鹿深波分館】3月【收藏電影的人 李建成導演 x 張凌文先生】 映後座談', `description`='【收藏電影的人 李建成導演 x 張凌文先生】 映後座談\r\n⧐時間｜114年3月13日（四）15:10-17:00\r\n⧐地點｜靜宜大學蓋夏圖書館 2樓 音樂欣賞室\r\n\r\n為了更深入了解電影收藏的奧秘與魅力，我們誠摯邀請您參加由李建成導演與張凌文先生共同主持的映後座談會。在這場座談中，兩位電影收藏領域的專家將分享他們的故事與經驗，深入探討電影收藏與保存的價值，並與觀眾交流他們對電影的熱愛與執著。這將是一場充滿啟發與感動的對話，讓電影愛好者能夠更全面地理解電影收藏背後的意義。\r\n\r\n無論您是影迷、電影研究者，或是對電影歷史有興趣的朋友，都不容錯過這次難得的機會！\r\n沙鹿深波圖書館「暖心 善心」 邀請您蒞臨靜宜大學蓋夏圖書館，與我們一起探索電影收藏的魅力與深度，感受電影背後隱藏的故事與情感。\r\n\r\n報名網址：https://reurl.cc/DKE40d', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市沙鹿區臺灣大道7段200號', `start_date`='2025-03-13 00:00:00', `end_date`='2025-03-13 00:00:00', `location`='靜宜大學', `latitude`=24.23425212, `longitude`=120.5838628, `ticket_price`='無資料', `source_url`='https://pse.is/768yyk', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0baa26b32408680bea25', 'Fun心聽故事(鹽埕分館2025年4月)', '由高雄市立圖書館所培訓的故事志工，透過豐富的肢體語言與生動有趣的互動方式，為小朋友說故事，歡迎親子一起參加！本活動免費參加，自由入場（禁止攜帶飲料、食物）', '高雄市立圖書館總館', '高雄市鹽埕區1鄰大仁路179號5樓、6樓', '2025-04-05 00:00:00', '2025-04-27 00:00:00', '高雄市立圖書館鹽埕分館', 22.626715, 120.281874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Fun心聽故事(鹽埕分館2025年4月)', `description`='由高雄市立圖書館所培訓的故事志工，透過豐富的肢體語言與生動有趣的互動方式，為小朋友說故事，歡迎親子一起參加！本活動免費參加，自由入場（禁止攜帶飲料、食物）', `organizer`='高雄市立圖書館總館', `address`='高雄市鹽埕區1鄰大仁路179號5樓、6樓', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='高雄市立圖書館鹽埕分館', `latitude`=22.626715, `longitude`=120.281874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bac26b32408680bea27', '香蕉電影院：童年時光馬拉松', '在螢幕前度過的時光，電影成為了我們通往不同世界的窗戶。無論是感人至深的劇情、驚心動魄的動作場面，還是輕鬆幽默的喜劇，觀看電影讓我們沉浸於各種情感之中，享受故事所帶來的魅力和心靈的震撼。\r\n播放影片：\r\n4/5  獅子王\r\n4/11 小王子\r\n4/18 小飛俠\r\n4/25 愛麗絲夢遊仙境', '高雄市立圖書館總館', '高雄市旗山區大德里6鄰中學路42號', '2025-04-05 00:00:00', '2025-04-25 00:00:00', '高雄市立圖書館旗山分館', 25.0421407, 121.5198716, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='香蕉電影院：童年時光馬拉松', `description`='在螢幕前度過的時光，電影成為了我們通往不同世界的窗戶。無論是感人至深的劇情、驚心動魄的動作場面，還是輕鬆幽默的喜劇，觀看電影讓我們沉浸於各種情感之中，享受故事所帶來的魅力和心靈的震撼。\r\n播放影片：\r\n4/5  獅子王\r\n4/11 小王子\r\n4/18 小飛俠\r\n4/25 愛麗絲夢遊仙境', `organizer`='高雄市立圖書館總館', `address`='高雄市旗山區大德里6鄰中學路42號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='高雄市立圖書館旗山分館', `latitude`=25.0421407, `longitude`=121.5198716, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bb026b32408680bea28', '湖內分館114年4月FUN心聽故事', '由志工老師們精心挑選出優質的故事繪本，以親子共讀方式，帶領學童故事分享，不定時會加入小活動，增進親子間的情感交流。', '高雄市立圖書館總館', '高雄市湖內區3鄰保生路101號', '2025-04-12 00:00:00', '2025-04-26 00:00:00', '高雄市立圖書館湖內分館', 22.8955499, 120.2225563, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='湖內分館114年4月FUN心聽故事', `description`='由志工老師們精心挑選出優質的故事繪本，以親子共讀方式，帶領學童故事分享，不定時會加入小活動，增進親子間的情感交流。', `organizer`='高雄市立圖書館總館', `address`='高雄市湖內區3鄰保生路101號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄市立圖書館湖內分館', `latitude`=22.8955499, `longitude`=120.2225563, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bb326b32408680bea29', '六藝成果發表展-傳統畫藝水墨花鳥班(114年度孔廟春季水墨花鳥展)', '孔廟開設六藝研習班已近20年，孔廟有著良好的學習環境及聘請擅長花鳥工筆之的張麗珠及陳麗玲講師，來指導對水墨繪畫有興趣的民眾，讓學員能夠在學習的過程中能夠陶冶心性，培養嗜好，讓自己有揮灑的空間，還可以把所學應用在布置居家與生活美學上。\r\n此次展出主題為春暖花開慶新年，以花卉及鳥獸的來喻意春天的來到萬物歡愉的表象，且配合孔廟辦理之春節揮毫活動展出，更讓孔廟更有年節氣氛。', '臺中市孔廟忠烈祠聯合管理所', '臺中市北區雙十路二段30號', '2025-01-07 00:00:00', '2025-03-31 00:00:00', '臺中市孔廟忠烈祠聯合管理所', 24.1538161, 120.6894073, '無資料', 'https://www.confucius.taichung.gov.tw/3603752/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='六藝成果發表展-傳統畫藝水墨花鳥班(114年度孔廟春季水墨花鳥展)', `description`='孔廟開設六藝研習班已近20年，孔廟有著良好的學習環境及聘請擅長花鳥工筆之的張麗珠及陳麗玲講師，來指導對水墨繪畫有興趣的民眾，讓學員能夠在學習的過程中能夠陶冶心性，培養嗜好，讓自己有揮灑的空間，還可以把所學應用在布置居家與生活美學上。\r\n此次展出主題為春暖花開慶新年，以花卉及鳥獸的來喻意春天的來到萬物歡愉的表象，且配合孔廟辦理之春節揮毫活動展出，更讓孔廟更有年節氣氛。', `organizer`='臺中市孔廟忠烈祠聯合管理所', `address`='臺中市北區雙十路二段30號', `start_date`='2025-01-07 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺中市孔廟忠烈祠聯合管理所', `latitude`=24.1538161, `longitude`=120.6894073, `ticket_price`='無資料', `source_url`='https://www.confucius.taichung.gov.tw/3603752/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bb526b32408680bea2a', '轉型 ‧ 文化　王行恭/創價藝文', '早年台灣並無正規培訓專業設計師的教育管道，設計皆由從事美術創作的畫家兼差。1980 年代是台灣政治、經濟、社會、文化等不同面向的轉型時期，亦是「設計家」專業定位的轉型階段。此時，由歐美吸收自由民主養分、帶著西方藝術設計的新知返回台灣的王行恭，在台灣平面設計發展歷程中，創造深刻的視覺印記。本次展出設計家王行恭「文化海報」、「創作海報」、「編輯設計」三個面向的作品，呈現其個人的生命軌跡，並一窺臺灣設計的發展進程。', '臺灣創價學會新竹藝文中心', '新竹市北區國華街68號2、3樓', '2025-02-05 00:00:00', '2025-05-09 00:00:00', '臺灣創價學會新竹藝文中心', 24.8170381, 120.970421, '無資料', 'https://www.sokaculture.org.tw/exhibition/%E8%BD%89%E5%9E%8B-%E6%96%87%E5%8C%96-%E7%8E%8B%E8%A1%8C%E', '[]') ON DUPLICATE KEY UPDATE `activity_name`='轉型 ‧ 文化　王行恭/創價藝文', `description`='早年台灣並無正規培訓專業設計師的教育管道，設計皆由從事美術創作的畫家兼差。1980 年代是台灣政治、經濟、社會、文化等不同面向的轉型時期，亦是「設計家」專業定位的轉型階段。此時，由歐美吸收自由民主養分、帶著西方藝術設計的新知返回台灣的王行恭，在台灣平面設計發展歷程中，創造深刻的視覺印記。本次展出設計家王行恭「文化海報」、「創作海報」、「編輯設計」三個面向的作品，呈現其個人的生命軌跡，並一窺臺灣設計的發展進程。', `organizer`='臺灣創價學會新竹藝文中心', `address`='新竹市北區國華街68號2、3樓', `start_date`='2025-02-05 00:00:00', `end_date`='2025-05-09 00:00:00', `location`='臺灣創價學會新竹藝文中心', `latitude`=24.8170381, `longitude`=120.970421, `ticket_price`='無資料', `source_url`='https://www.sokaculture.org.tw/exhibition/%E8%BD%89%E5%9E%8B-%E6%96%87%E5%8C%96-%E7%8E%8B%E8%A1%8C%E', `image_url`='[]';
