INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bb526b32408680bea2f', '週六說故事(3月2場)', '-3/1故事百寶箱-\r\n本系列說故事活動免事先報名，歡迎踴躍參加\r\n由台中故事協會老師分享繪本故事，快來聽故事吧。\r\n\r\n-3/15魔法故事森林-\r\n由南屯分館魔法故事森林的故事精靈帶領小朋友一起讀繪本、玩手作。\r\n本系列活動免報名，歡迎踴躍參加。\r\n\r\n每週故事主題會提前公告於FB粉絲專頁，歡迎關注我們！', '臺中市立圖書館南屯分館', '臺中市南屯區大墩12街361號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '臺中市立圖書館南屯分館', 24.14165524, 120.6177379, '無資料', 'https://reurl.cc/V0bp3b ,https://reurl.cc/M6K1Zn ,https://reurl.cc/V0bpE6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='週六說故事(3月2場)', `description`='-3/1故事百寶箱-\r\n本系列說故事活動免事先報名，歡迎踴躍參加\r\n由台中故事協會老師分享繪本故事，快來聽故事吧。\r\n\r\n-3/15魔法故事森林-\r\n由南屯分館魔法故事森林的故事精靈帶領小朋友一起讀繪本、玩手作。\r\n本系列活動免報名，歡迎踴躍參加。\r\n\r\n每週故事主題會提前公告於FB粉絲專頁，歡迎關注我們！', `organizer`='臺中市立圖書館南屯分館', `address`='臺中市南屯區大墩12街361號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市立圖書館南屯分館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://reurl.cc/V0bp3b ,https://reurl.cc/M6K1Zn ,https://reurl.cc/V0bpE6', `image_url`='[]';
