INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bb526b32408680bea32', '3月假日電影院-魔籽公主', '《魔籽公主》描寫六歲的杜妮亞是個活潑開朗的敘利亞女孩，深愛著位於阿勒坡古城的家園。遺憾的是，她最心愛的母親英年早逝，富正義感的父親也無端陷冤獄，戰爭的爆發又迫使杜妮亞和阿公阿嬤逃離家鄉，踏上尋找新家的驚奇旅程。儘管眼前充滿挑戰，杜妮亞相信手中的魔法黑種草籽和神話中的阿勒坡公主會守護他們。歡迎大家一起來欣賞電影！', '臺中市立圖書館南屯分館', '臺中市南屯區大墩12街361號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館南屯分館', 24.14165524, 120.6177379, '無資料', 'https://reurl.cc/26RMW4', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月假日電影院-魔籽公主', `description`='《魔籽公主》描寫六歲的杜妮亞是個活潑開朗的敘利亞女孩，深愛著位於阿勒坡古城的家園。遺憾的是，她最心愛的母親英年早逝，富正義感的父親也無端陷冤獄，戰爭的爆發又迫使杜妮亞和阿公阿嬤逃離家鄉，踏上尋找新家的驚奇旅程。儘管眼前充滿挑戰，杜妮亞相信手中的魔法黑種草籽和神話中的阿勒坡公主會守護他們。歡迎大家一起來欣賞電影！', `organizer`='臺中市立圖書館南屯分館', `address`='臺中市南屯區大墩12街361號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館南屯分館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://reurl.cc/26RMW4', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bba26b32408680bea33', '扁豆測量 Measuring a Lentil', '久等了！我們很開心能夠和大家分享重新開幕後的第一檔展覽 — 由三古三土藝術計畫展出的「扁豆測量 Measuring a Lentil」。\r\n此檔展覽是以播種器為主要媒材而發展出的一系列印畫動作。\r\n「扁豆測量」名稱來自於與播種器廠商的一段溝通過程，討論商業生產與實用價值的矛盾，進而帶入利用生產工具表達器物挪用、無用的用途、勞動與創作關係。拆解秩序並重新規範不同語境下的物件，以農作、繪畫、印刷、食材規劃而成的一套創作工作思維與步驟。從材料訂製、工具轉化到具體創作，將動作重新編排並濃縮至一張工作台之上，邀請參與者透過身體勞動共同建構展覽作品。', '鯉魚藝廊Carp Gallery', '臺中市西區', '2025-02-15 00:00:00', '2025-04-06 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/zp9YO0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='扁豆測量 Measuring a Lentil', `description`='久等了！我們很開心能夠和大家分享重新開幕後的第一檔展覽 — 由三古三土藝術計畫展出的「扁豆測量 Measuring a Lentil」。\r\n此檔展覽是以播種器為主要媒材而發展出的一系列印畫動作。\r\n「扁豆測量」名稱來自於與播種器廠商的一段溝通過程，討論商業生產與實用價值的矛盾，進而帶入利用生產工具表達器物挪用、無用的用途、勞動與創作關係。拆解秩序並重新規範不同語境下的物件，以農作、繪畫、印刷、食材規劃而成的一套創作工作思維與步驟。從材料訂製、工具轉化到具體創作，將動作重新編排並濃縮至一張工作台之上，邀請參與者透過身體勞動共同建構展覽作品。', `organizer`='鯉魚藝廊Carp Gallery', `address`='臺中市西區', `start_date`='2025-02-15 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/zp9YO0', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bba26b32408680bea34', '面粉趴2025春', '｜關於面粉趴｜\r\n面白大丈夫劇團繼職男人生系列後，又一全新嘗試，現場即興節目-面粉趴。沒有劇本，沒有台詞，只有一個又一個的現場企劃，四位成員的搞笑實力直接見真章，全場爆笑還是尷尬冷場，就在一瞬之間！\r\n\r\n｜製作團隊｜\r\n製作人｜面白大丈夫\r\n演員｜董軒、阿量、耿賢、木森、扣扣', '面白大丈夫有限公司', '臺中市西區民生路140號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '國立臺中教育大學', 24.14391082, 120.6647579, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='面粉趴2025春', `description`='｜關於面粉趴｜\r\n面白大丈夫劇團繼職男人生系列後，又一全新嘗試，現場即興節目-面粉趴。沒有劇本，沒有台詞，只有一個又一個的現場企劃，四位成員的搞笑實力直接見真章，全場爆笑還是尷尬冷場，就在一瞬之間！\r\n\r\n｜製作團隊｜\r\n製作人｜面白大丈夫\r\n演員｜董軒、阿量、耿賢、木森、扣扣', `organizer`='面白大丈夫有限公司', `address`='臺中市西區民生路140號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='國立臺中教育大學', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
