INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bbc26b32408680bea36', '【中市圖沙鹿深波分館】電影與文學講座：「閱讀李安」', '電影與文學講座：「閱讀李安」\r\n◆講座講師 │ 許建崑教授(中華民國兒童文學學會前理事長)\r\n◆講座時間 │ 03.15㊅ 14:00-16:00\r\n◆講座地點 │ 沙鹿深波分館 2F團體視聽室\r\n◆活動報名 │ https://tinyurl.com/2475473e\r\n◆線上活動網址：\r\nFB https://pse.is/74pb9l\r\nIG https://pse.is/74pba9\r\n★講座內容 │ \r\n細膩與溫暖：李安電影的特色\r\n父親三部曲：省察傳統文化下的家庭倫理\r\n復現美國夢：找回即將消失的記憶\r\n面向全世界：經典或商轉的選擇\r\n嘗試新視覺：電影拍攝與敘事技巧的突破\r\n中場迴旋曲：娛樂觀眾或直擊良知\r\n×╳〃°。♪×╳〃°。♪×╳〃°。♪×╳〃°。♪×╳〃°。♪\r\n🎥 李安的電影是如何呈現人性的複雜與家庭的溫暖？\r\n🎬他又如何在視覺創新與敘事技巧上創造突破？\r\n這些問題，許建崑老師將帶領大家一起思考與探索！\r\n在這場講座中，許建崑教授將帶領我們探索李安電影的深層意涵，並與大家一同思考這位影壇巨匠如何用影像訴說最動人的故事。\r\n📢 快來報名，一起深度閱讀李安的電影世界吧！', '臺中市立圖書館沙鹿深波分館', '臺中市沙鹿區鎮南路二段 488號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '臺中市立圖書館沙鹿深波分館', 24.23425212, 120.5838628, '無資料', 'https://pse.is/74pb9l', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖沙鹿深波分館】電影與文學講座：「閱讀李安」', `description`='電影與文學講座：「閱讀李安」\r\n◆講座講師 │ 許建崑教授(中華民國兒童文學學會前理事長)\r\n◆講座時間 │ 03.15㊅ 14:00-16:00\r\n◆講座地點 │ 沙鹿深波分館 2F團體視聽室\r\n◆活動報名 │ https://tinyurl.com/2475473e\r\n◆線上活動網址：\r\nFB https://pse.is/74pb9l\r\nIG https://pse.is/74pba9\r\n★講座內容 │ \r\n細膩與溫暖：李安電影的特色\r\n父親三部曲：省察傳統文化下的家庭倫理\r\n復現美國夢：找回即將消失的記憶\r\n面向全世界：經典或商轉的選擇\r\n嘗試新視覺：電影拍攝與敘事技巧的突破\r\n中場迴旋曲：娛樂觀眾或直擊良知\r\n×╳〃°。♪×╳〃°。♪×╳〃°。♪×╳〃°。♪×╳〃°。♪\r\n🎥 李安的電影是如何呈現人性的複雜與家庭的溫暖？\r\n🎬他又如何在視覺創新與敘事技巧上創造突破？\r\n這些問題，許建崑老師將帶領大家一起思考與探索！\r\n在這場講座中，許建崑教授將帶領我們探索李安電影的深層意涵，並與大家一同思考這位影壇巨匠如何用影像訴說最動人的故事。\r\n📢 快來報名，一起深度閱讀李安的電影世界吧！', `organizer`='臺中市立圖書館沙鹿深波分館', `address`='臺中市沙鹿區鎮南路二段 488號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='臺中市立圖書館沙鹿深波分館', `latitude`=24.23425212, `longitude`=120.5838628, `ticket_price`='無資料', `source_url`='https://pse.is/74pb9l', `image_url`='[]';
