INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bbd26b32408680bea39', '【中市圖沙鹿深波分館】3月主題書展(2025/03–4場) ', '3月主題書展\r\n★「環遊世界大冒險」兒童書展\r\n展出有關世界各國歷史、文化和地理環境之書籍，增進對各國的認識。\r\n展示時間：2025/03/01(六)-2025/03/30(日)\r\n展示地點：1樓兒童書展區\r\n\r\n★2025多元閱讀繽紛季–「古早味．台灣歌」書展\r\n以台語歌謠為主題，展出相關台語、音樂書籍，讓母語透過書本語文字融入日常生活。\r\n展示時間：2025/03/01(六)-2025/03/30(日)\r\n展示地點：1樓主題書展區\r\n\r\n★「親近文學」書展\r\n本分館藉由一系列新到圖書的展示，來與讀者分享親近文學的感動及心靈洗滌的重要。\r\n展示時間：2025/03/01(六)-2025/03/30(日)\r\n展示地點：沙鹿深波分館1樓新書書展區\r\n\r\n★「情緒療癒」主題書展\r\n展示有助放鬆身心及情緒療癒圖書，如心理勵志、哲學、手作、烹飪、園藝、旅行、運動……等相關書籍開放讀者閱覽、借閱，透過療癒閱讀，讓書成為每個人最好的朋友，協助達到情緒療癒效果。\r\n展示時間：2025/03/01(六)-2025/03/30(日)\r\n展示地點：沙鹿深波2樓開架閱覽區 ', '臺中市立圖書館沙鹿深波分館', '臺中市沙鹿區鎮南路二段 488號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館沙鹿深波分館', 24.23425212, 120.5838628, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖沙鹿深波分館】3月主題書展(2025/03–4場) ', `description`='3月主題書展\r\n★「環遊世界大冒險」兒童書展\r\n展出有關世界各國歷史、文化和地理環境之書籍，增進對各國的認識。\r\n展示時間：2025/03/01(六)-2025/03/30(日)\r\n展示地點：1樓兒童書展區\r\n\r\n★2025多元閱讀繽紛季–「古早味．台灣歌」書展\r\n以台語歌謠為主題，展出相關台語、音樂書籍，讓母語透過書本語文字融入日常生活。\r\n展示時間：2025/03/01(六)-2025/03/30(日)\r\n展示地點：1樓主題書展區\r\n\r\n★「親近文學」書展\r\n本分館藉由一系列新到圖書的展示，來與讀者分享親近文學的感動及心靈洗滌的重要。\r\n展示時間：2025/03/01(六)-2025/03/30(日)\r\n展示地點：沙鹿深波分館1樓新書書展區\r\n\r\n★「情緒療癒」主題書展\r\n展示有助放鬆身心及情緒療癒圖書，如心理勵志、哲學、手作、烹飪、園藝、旅行、運動……等相關書籍開放讀者閱覽、借閱，透過療癒閱讀，讓書成為每個人最好的朋友，協助達到情緒療癒效果。\r\n展示時間：2025/03/01(六)-2025/03/30(日)\r\n展示地點：沙鹿深波2樓開架閱覽區 ', `organizer`='臺中市立圖書館沙鹿深波分館', `address`='臺中市沙鹿區鎮南路二段 488號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館沙鹿深波分館', `latitude`=24.23425212, `longitude`=120.5838628, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bbe26b32408680bea3a', '【中市圖沙鹿深波分館】3月飛揚書香音樂會 ', '3月飛揚書香音樂會 \r\n🎵飛揚書香音樂會 報名開始！！🎵\r\n💥3月份飛揚書香音樂會報名來囉！\r\n只要會樂器就能報名喔！\r\n🔥歡迎來演奏出屬於你悅耳的曲子🔥\r\n\r\n⏰時間:114/3/16(日) 9:30\r\n🏫地點:沙鹿深波分館 B1多功能活動室\r\n👉報名連結 : https://pse.is/74pund(曲目務必請確認後再填寫)\r\n👉活動宣傳網址：\r\nFB：https://pse.is/76wdkt\r\n‼️注意事項：\r\n1.如填完表單發現資料有誤，請以私訊臉書修改，勿再重填一次表單。\r\n2.作業流程關係表演前二週將無法再更改曲目，敬請見諒。\r\n3.表演者限演出一次合奏或獨奏，每次演奏時間在5分鐘以內。\r\n4.填寫資料、曲目時請完整填寫，事後填寫將無法受理。\r\n5.填完表單即報名成功。\r\n💥名額有限，歡迎報名💥\r\n★3月份樂音悠揚音樂會\r\n時間：2025/03/16(日)上午9:30起~\r\n地點：沙鹿深波分館B1多功能活動室\r\n歡迎喜愛音樂的大小朋友，一起聆聽演出，也給予努力學習、演出者支持、鼓勵^^ ', '臺中市立圖書館沙鹿深波分館', '臺中市沙鹿區鎮南路二段 488號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '臺中市立圖書館沙鹿深波分館', 24.23425212, 120.5838628, '無資料', 'https://reurl.cc/b3MYbl', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖沙鹿深波分館】3月飛揚書香音樂會 ', `description`='3月飛揚書香音樂會 \r\n🎵飛揚書香音樂會 報名開始！！🎵\r\n💥3月份飛揚書香音樂會報名來囉！\r\n只要會樂器就能報名喔！\r\n🔥歡迎來演奏出屬於你悅耳的曲子🔥\r\n\r\n⏰時間:114/3/16(日) 9:30\r\n🏫地點:沙鹿深波分館 B1多功能活動室\r\n👉報名連結 : https://pse.is/74pund(曲目務必請確認後再填寫)\r\n👉活動宣傳網址：\r\nFB：https://pse.is/76wdkt\r\n‼️注意事項：\r\n1.如填完表單發現資料有誤，請以私訊臉書修改，勿再重填一次表單。\r\n2.作業流程關係表演前二週將無法再更改曲目，敬請見諒。\r\n3.表演者限演出一次合奏或獨奏，每次演奏時間在5分鐘以內。\r\n4.填寫資料、曲目時請完整填寫，事後填寫將無法受理。\r\n5.填完表單即報名成功。\r\n💥名額有限，歡迎報名💥\r\n★3月份樂音悠揚音樂會\r\n時間：2025/03/16(日)上午9:30起~\r\n地點：沙鹿深波分館B1多功能活動室\r\n歡迎喜愛音樂的大小朋友，一起聆聽演出，也給予努力學習、演出者支持、鼓勵^^ ', `organizer`='臺中市立圖書館沙鹿深波分館', `address`='臺中市沙鹿區鎮南路二段 488號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺中市立圖書館沙鹿深波分館', `latitude`=24.23425212, `longitude`=120.5838628, `ticket_price`='無資料', `source_url`='https://reurl.cc/b3MYbl', `image_url`='[]';
