INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bc626b32408680bea3d', '鐵支路開花–烏樹林糖鐵軌跡', '鐵支路開花–烏樹林糖鐵軌跡 \r\n日期：2025/03/23(日)  上午10:00-11:30\r\n集合地點：烏樹林休閒園區車站 (臺南市後壁區福安里184號)\r\n講師：王翔 (鐵道研究員)\r\n\r\n烏樹林糖廠關廠後轉型為休閒園區與精緻農業中心，是培育蝴蝶蘭的重要基地，而烏樹林車站更是連通後壁、東山、新營、白河的重要鐵道樞紐，讓我們跟著講師的腳步，沿著軌道再見烏樹林糖廠的風華時光！\r\n報名連結：https://forms.gle/dvJuW9M5tYGWkFHs5', '臺南市政府文化局', '臺南市後壁區', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '後壁區（臺南市）=', 23.36201478, 120.3485081, '100元 現場收費 (含保險、導覽設備)+--', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鐵支路開花–烏樹林糖鐵軌跡', `description`='鐵支路開花–烏樹林糖鐵軌跡 \r\n日期：2025/03/23(日)  上午10:00-11:30\r\n集合地點：烏樹林休閒園區車站 (臺南市後壁區福安里184號)\r\n講師：王翔 (鐵道研究員)\r\n\r\n烏樹林糖廠關廠後轉型為休閒園區與精緻農業中心，是培育蝴蝶蘭的重要基地，而烏樹林車站更是連通後壁、東山、新營、白河的重要鐵道樞紐，讓我們跟著講師的腳步，沿著軌道再見烏樹林糖廠的風華時光！\r\n報名連結：https://forms.gle/dvJuW9M5tYGWkFHs5', `organizer`='臺南市政府文化局', `address`='臺南市後壁區', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='後壁區（臺南市）=', `latitude`=23.36201478, `longitude`=120.3485081, `ticket_price`='100元 現場收費 (含保險、導覽設備)+--', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bc826b32408680bea3e', '臺中市南屯親子館（114年3月繪本故事書12場）', '114年3月份行事曆出爐\r\n本月主題:遠古探險家\r\n很久很久以前\r\n世界上有許多失落的寶藏、神秘的文明，還有未解的謎團 \r\n小朋友你們知道嗎\r\n快來咖咖的家，一起去揭開遠古世界的秘密吧\r\n遊戲區上限共為68組\r\n(以寶貝為單位)(分別為網路/現場)\r\n網路預約48組\r\nhttps://reurl.cc/XqX8oa\r\n(於三天前中午12時開放預約，當日無網路預約)\r\n當日現場登記20組\r\n(上下午場次開館前5分鐘開始登記)\r\n三月份報名親子活動\r\n預約https://reurl.cc/Vz0W6N\r\n親子活動(藍色字體):前一週中午12點開放育兒資源網報名\r\n各項活動請查閱相關活動須知及海報\r\n咖咖小叮嚀：\r\n依據當月活動報名依公告為主，並於「臺中市育兒資源網」報名\r\n每週一及國定假日為固定休館\r\n遊戲區開放時間: 週二至週日 09:30-11:30/13:30-16:30\r\n(最後入館時間為11:00/16:00)\r\n電話服務時間：週二至週日 09:00-12:00/13:00-17:00\r\n若有不清楚的地方，歡迎來電詢問\r\n04-23803141，我們將樂意為您解答唷!', '臺中市政府社會局', '臺中市南屯區', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '南屯區（臺中市）=', 24.14165524, 120.6177379, '無資料', 'https://user271806.pse.is/77rw2w', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市南屯親子館（114年3月繪本故事書12場）', `description`='114年3月份行事曆出爐\r\n本月主題:遠古探險家\r\n很久很久以前\r\n世界上有許多失落的寶藏、神秘的文明，還有未解的謎團 \r\n小朋友你們知道嗎\r\n快來咖咖的家，一起去揭開遠古世界的秘密吧\r\n遊戲區上限共為68組\r\n(以寶貝為單位)(分別為網路/現場)\r\n網路預約48組\r\nhttps://reurl.cc/XqX8oa\r\n(於三天前中午12時開放預約，當日無網路預約)\r\n當日現場登記20組\r\n(上下午場次開館前5分鐘開始登記)\r\n三月份報名親子活動\r\n預約https://reurl.cc/Vz0W6N\r\n親子活動(藍色字體):前一週中午12點開放育兒資源網報名\r\n各項活動請查閱相關活動須知及海報\r\n咖咖小叮嚀：\r\n依據當月活動報名依公告為主，並於「臺中市育兒資源網」報名\r\n每週一及國定假日為固定休館\r\n遊戲區開放時間: 週二至週日 09:30-11:30/13:30-16:30\r\n(最後入館時間為11:00/16:00)\r\n電話服務時間：週二至週日 09:00-12:00/13:00-17:00\r\n若有不清楚的地方，歡迎來電詢問\r\n04-23803141，我們將樂意為您解答唷!', `organizer`='臺中市政府社會局', `address`='臺中市南屯區', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://user271806.pse.is/77rw2w', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bc826b32408680bea3f', '臺中市北區親子館（114年3月繪本故事書15場）', '114年3月行事曆\r\n時間過好快呀~~\r\n默默地第一季即將來到三月份啦!!\r\n有發現Pon Pon的家主題不一樣了嗎?\r\n歡迎寶貝們一起來探索、一起來找我們玩哦~~~\r\n以下為3月份的行事曆，請大家詳閱以下資訊，敬請配合唷❣\r\n出外要記得勤洗手，保護好自己也可以保護別人喔!\r\n每週一固定休館！\r\n3/4(二)休館\r\n借閱教具服務已於2/18開始恢復借閱\r\n煩請各位寶貝們來辦理借閱證、借閱教玩具回家玩要留意時間哦\r\n接聽電話時間：週二至週日 9:00-17:00\r\n接聽活動報名時間：週二至週六 9:00-17:00\r\n服務電話：04-2205858', '臺中市政府社會局', '臺中市北區', '2025-03-05 00:00:00', '2025-03-28 00:00:00', '北區（臺中市）=', 24.15863985, 120.6809521, '無資料', 'https://user271806.pse.is/77rzh8', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市北區親子館（114年3月繪本故事書15場）', `description`='114年3月行事曆\r\n時間過好快呀~~\r\n默默地第一季即將來到三月份啦!!\r\n有發現Pon Pon的家主題不一樣了嗎?\r\n歡迎寶貝們一起來探索、一起來找我們玩哦~~~\r\n以下為3月份的行事曆，請大家詳閱以下資訊，敬請配合唷❣\r\n出外要記得勤洗手，保護好自己也可以保護別人喔!\r\n每週一固定休館！\r\n3/4(二)休館\r\n借閱教具服務已於2/18開始恢復借閱\r\n煩請各位寶貝們來辦理借閱證、借閱教玩具回家玩要留意時間哦\r\n接聽電話時間：週二至週日 9:00-17:00\r\n接聽活動報名時間：週二至週六 9:00-17:00\r\n服務電話：04-2205858', `organizer`='臺中市政府社會局', `address`='臺中市北區', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='北區（臺中市）=', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://user271806.pse.is/77rzh8', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bc826b32408680bea40', '臺中市大里親子館（114年3月繪本故事書7場）', '「114年3月份活動行事曆」\r\n親愛的爸爸媽媽與寶貝你們好：本館3月份主題為「好餓的毛毛蟲」，認識多種水果和外觀特徵、念讀或指認水果，並且學習簡單的數理概念，包含顏色、點算數量、大小序列或配對等遊戲和活動。\r\n3月份每個據點的行動車服務也會提供很多不同遊戲，快點看看哪個據點比較近，請踴躍報名，跟我們一起玩吧！\r\n借用服務已經開放囉，請記得攜帶借閱證前來為寶貝挑選圖書或教玩具唷！【借用服務時間：0930-1200、1300-1600】\r\n3/4(二)消毒日，不對外開放\r\n3/23(日)辦理第一季親親寶貝古禮抓周，上下午入館暫停，報名方式擇日公告。\r\n提醒大家持續關注活動報名的資訊，#活動前三天的中午12點就可以開始網路預約了喔^^\r\n每場次都有現場名額，#網路正取為25組，#現場有10組正取，若該場次有網路名額未滿或遲到親子，也會將名額釋出給現場親子。\r\n入館請配合出示證件登記、量測體溫。\r\n成人或寶貝身體若有發燒或各種感冒症狀，請避免預約入館並暫停參與活動，好好在家休息。', '臺中市政府社會局', '臺中市大里區', '2025-03-02 00:00:00', '2025-03-29 00:00:00', '大里區（臺中市）=', 24.09575742, 120.6926261, '無資料', 'https://user271806.pse.is/77s4p9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市大里親子館（114年3月繪本故事書7場）', `description`='「114年3月份活動行事曆」\r\n親愛的爸爸媽媽與寶貝你們好：本館3月份主題為「好餓的毛毛蟲」，認識多種水果和外觀特徵、念讀或指認水果，並且學習簡單的數理概念，包含顏色、點算數量、大小序列或配對等遊戲和活動。\r\n3月份每個據點的行動車服務也會提供很多不同遊戲，快點看看哪個據點比較近，請踴躍報名，跟我們一起玩吧！\r\n借用服務已經開放囉，請記得攜帶借閱證前來為寶貝挑選圖書或教玩具唷！【借用服務時間：0930-1200、1300-1600】\r\n3/4(二)消毒日，不對外開放\r\n3/23(日)辦理第一季親親寶貝古禮抓周，上下午入館暫停，報名方式擇日公告。\r\n提醒大家持續關注活動報名的資訊，#活動前三天的中午12點就可以開始網路預約了喔^^\r\n每場次都有現場名額，#網路正取為25組，#現場有10組正取，若該場次有網路名額未滿或遲到親子，也會將名額釋出給現場親子。\r\n入館請配合出示證件登記、量測體溫。\r\n成人或寶貝身體若有發燒或各種感冒症狀，請避免預約入館並暫停參與活動，好好在家休息。', `organizer`='臺中市政府社會局', `address`='臺中市大里區', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='大里區（臺中市）=', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://user271806.pse.is/77s4p9', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bcd26b32408680bea41', '居家空間系列I【構築沉澱與想像的空間】講座', '四月份晨講學來囉！\r\n🏠居家空間系列I【構築沉澱與想像的空間】\r\n這次特別邀請到 @水相設計 Waterfrom Design  設計總監-李智翔來擔任主講者。他深耕設計領域二十餘年，曾榮獲 FRAME Award 評審團大獎、APIDA 亞太室內設計金獎、DFA 亞洲最具影響力設計銀獎、iF Award 等多項國際大獎。\r\n李智翔總監將透過他的專業，分享如何在空間中打造沉浸式體驗，並以創新的住宅設計手法，為人們的生活帶來更多價值與可能性。\r\n【講座資訊】\r\n⭓時間：2025/４/19（六）14:30\r\n⭓地點：丰二三－晨露廳', '財團法人晨露文化藝術基金會', '臺中市西區', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/vplRrj', '[]') ON DUPLICATE KEY UPDATE `activity_name`='居家空間系列I【構築沉澱與想像的空間】講座', `description`='四月份晨講學來囉！\r\n🏠居家空間系列I【構築沉澱與想像的空間】\r\n這次特別邀請到 @水相設計 Waterfrom Design  設計總監-李智翔來擔任主講者。他深耕設計領域二十餘年，曾榮獲 FRAME Award 評審團大獎、APIDA 亞太室內設計金獎、DFA 亞洲最具影響力設計銀獎、iF Award 等多項國際大獎。\r\n李智翔總監將透過他的專業，分享如何在空間中打造沉浸式體驗，並以創新的住宅設計手法，為人們的生活帶來更多價值與可能性。\r\n【講座資訊】\r\n⭓時間：2025/４/19（六）14:30\r\n⭓地點：丰二三－晨露廳', `organizer`='財團法人晨露文化藝術基金會', `address`='臺中市西區', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/vplRrj', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bce26b32408680bea42', 'Chiu Yueh Garden | 秋月園 INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bce26b32408680bea43', '【史特拉底瓦里．傳奇之音】奇美提琴音樂饗宴', '奇美博物館 Chimei Museum \r\n史特拉底瓦里．傳奇之音來到晨露廳演出啦~🎻\r\n(不在台中的朋友們還有台南及台北場可以選擇唷)\r\n史上最偉大的製琴巨擘史特拉底瓦里，確立提琴最佳規格，其完美琴體架構、無懈可擊的音色、優美線條與塗漆，成為製琴師與提琴家追求的夢想。\r\n八把奇美博物館殿堂級收藏，包括史特拉底瓦里劃時代鉅作，及兒子歐莫柏諾與基羅拉摩．阿瑪蒂的傑出作品，邀您聆賞傳奇之音！\r\n🎵早鳥75折倒數\r\nhttps://reurl.cc/ger4Vz\r\n【史特拉底瓦里．傳奇之音】奇美提琴音樂饗宴\r\n2025/03/16（日）14:00 台南/奇美博物館奇美廳\r\n2025/03/23（日）14:00 台中/丰二三晨露廳\r\n2025/03/29（六）19:00 台北/誠品表演廳\r\n\r\n本次音樂會以【史特拉底瓦里．傳奇之音】為主題，演出曲目邀請倫敦國王學院音樂學博士焦元溥規劃，時間跨度從十八到二十世紀約兩百年間的創作，涵蓋義大利、德奧、俄國與法國等不同風格與時期作品，展現史式名琴完美演繹各種曲目與風格的驚人能力；樂器則是由奇美博物館資深提琴顧問鍾岱廷規劃史氏從早期到晚期六把曠世名作，包括《史特拉提琴雜誌》（The Strad）讚譽擁有最完美音色「瑪麗．霍爾–維奧第」（Marie Hall-Viotti）小提琴，及兒子歐莫柏諾極富特色又傑出的作品，加上基羅拉摩．阿瑪蒂（Girolamo Amati, ca. 1550-1630）的中提琴「亨利四世」（Henry IV）等八把奇美殿堂級名琴。演出形式包含開場使用三把小提琴音色比較、提琴二重奏，以及下半場的兩組弦樂四重奏競演；八把名琴首次同臺競技，千載難逢不容錯過！\r\n\r\n \r\n', '財團法人奇美博物館基金會', '臺中市西區', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【史特拉底瓦里．傳奇之音】奇美提琴音樂饗宴', `description`='奇美博物館 Chimei Museum \r\n史特拉底瓦里．傳奇之音來到晨露廳演出啦~🎻\r\n(不在台中的朋友們還有台南及台北場可以選擇唷)\r\n史上最偉大的製琴巨擘史特拉底瓦里，確立提琴最佳規格，其完美琴體架構、無懈可擊的音色、優美線條與塗漆，成為製琴師與提琴家追求的夢想。\r\n八把奇美博物館殿堂級收藏，包括史特拉底瓦里劃時代鉅作，及兒子歐莫柏諾與基羅拉摩．阿瑪蒂的傑出作品，邀您聆賞傳奇之音！\r\n🎵早鳥75折倒數\r\nhttps://reurl.cc/ger4Vz\r\n【史特拉底瓦里．傳奇之音】奇美提琴音樂饗宴\r\n2025/03/16（日）14:00 台南/奇美博物館奇美廳\r\n2025/03/23（日）14:00 台中/丰二三晨露廳\r\n2025/03/29（六）19:00 台北/誠品表演廳\r\n\r\n本次音樂會以【史特拉底瓦里．傳奇之音】為主題，演出曲目邀請倫敦國王學院音樂學博士焦元溥規劃，時間跨度從十八到二十世紀約兩百年間的創作，涵蓋義大利、德奧、俄國與法國等不同風格與時期作品，展現史式名琴完美演繹各種曲目與風格的驚人能力；樂器則是由奇美博物館資深提琴顧問鍾岱廷規劃史氏從早期到晚期六把曠世名作，包括《史特拉提琴雜誌》（The Strad）讚譽擁有最完美音色「瑪麗．霍爾–維奧第」（Marie Hall-Viotti）小提琴，及兒子歐莫柏諾極富特色又傑出的作品，加上基羅拉摩．阿瑪蒂（Girolamo Amati, ca. 1550-1630）的中提琴「亨利四世」（Henry IV）等八把奇美殿堂級名琴。演出形式包含開場使用三把小提琴音色比較、提琴二重奏，以及下半場的兩組弦樂四重奏競演；八把名琴首次同臺競技，千載難逢不容錯過！\r\n\r\n \r\n', `organizer`='財團法人奇美博物館基金會', `address`='臺中市西區', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bce26b32408680bea44', '「蘭之美」- 孫少英的微噴藝術畫收藏展', '☘️展名｜「蘭之美」- 孫少英的微噴藝術畫收藏展\r\n☘️展期｜114/3/1-3/31\r\n☘️地點｜盧安潮-日廳 (營業時間9:30-17:30)\r\n( 台中市西區台灣大道二段375號11樓之2)\r\n三月就是要如此隨性！走進孫少英老師的水彩 #蘭花世界，\r\n感受 「蘭之美，靜而不爭，幽香自遠」的境界。🌷\r\n蘭花有花中君子之稱，可以欣賞各種珍稀蘭花品種，\r\n能領略靜物畫的活潑生動。🌻\r\n收藏一幅 #藝術微噴複製畫 是收藏的入門首選，\r\n畫中的蘭花永不凋謝，輕鬆就能為居家增添典雅氣息，\r\n為一成不變的生活來一段感動。🍂\r\n收藏複製畫，請洽：04-23263928。\r\n#孫少英 #盧安潮 #盧安藝術', '盧安藝術文化有限公司', '臺中市西區', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/aZoW93', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「蘭之美」- 孫少英的微噴藝術畫收藏展', `description`='☘️展名｜「蘭之美」- 孫少英的微噴藝術畫收藏展\r\n☘️展期｜114/3/1-3/31\r\n☘️地點｜盧安潮-日廳 (營業時間9:30-17:30)\r\n( 台中市西區台灣大道二段375號11樓之2)\r\n三月就是要如此隨性！走進孫少英老師的水彩 #蘭花世界，\r\n感受 「蘭之美，靜而不爭，幽香自遠」的境界。🌷\r\n蘭花有花中君子之稱，可以欣賞各種珍稀蘭花品種，\r\n能領略靜物畫的活潑生動。🌻\r\n收藏一幅 #藝術微噴複製畫 是收藏的入門首選，\r\n畫中的蘭花永不凋謝，輕鬆就能為居家增添典雅氣息，\r\n為一成不變的生活來一段感動。🍂\r\n收藏複製畫，請洽：04-23263928。\r\n#孫少英 #盧安潮 #盧安藝術', `organizer`='盧安藝術文化有限公司', `address`='臺中市西區', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/aZoW93', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bce26b32408680bea45', '布川愛子 台湾個展「Fluffy Wonder Friends」', 'Fluffy Wonder Friends\r\n描繪了這些彷彿閉上眼就能看見的軟蓬蓬的小夥伴們。我覺得捧著花或是小鳥的他們正傳遞著愛。對於既是這個世界和畫作之境，亦是窗框一角的畫框也十分講究，使其成為世界上獨一無二的作品。使用了粉末顏料和壓印箔的作品則是會隨著光線角度而呈現各種面貌。除了原畫，另有販售翻譯版的繪本和文具小物等。真的非常開心有機會與台灣的粉絲朋友們分享畫作。我也很期待在廊日能與各位見面！\r\n====\r\n作家在廊日\r\n3/8（六）：14:00-19:00\r\n3/9（日）：14:00-19:00\r\n＊請注意其中包含畫家的休息時間，有可能遇到老師不在現場的狀況\r\n在廊活動：\r\n開幕首二日，收藏布川愛子老師原畫作品的朋友\r\n老師將現場繪製明信片大小的小卡作為小禮物給您\r\n可以繪製收藏者本人或家人動物化的模樣\r\n或是家裡的狗狗貓貓等小夥伴\r\n請注意，這個特別活動僅限開幕首二日\r\n參考範例將公布於策展人帳號\r\n另外，畫家也將於現場以單色筆為各位簡單簽繪（簽名+簡易小圖）\r\n＊收藏原畫的小卡片則是會比上述簽繪更精緻\r\n歡迎大家來購買繪本及周邊商品找老師簽名\r\n', '綠光+marüte', '臺中市西區', '2025-03-08 00:00:00', '2025-03-30 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/O5lyjr', '[]') ON DUPLICATE KEY UPDATE `activity_name`='布川愛子 台湾個展「Fluffy Wonder Friends」', `description`='Fluffy Wonder Friends\r\n描繪了這些彷彿閉上眼就能看見的軟蓬蓬的小夥伴們。我覺得捧著花或是小鳥的他們正傳遞著愛。對於既是這個世界和畫作之境，亦是窗框一角的畫框也十分講究，使其成為世界上獨一無二的作品。使用了粉末顏料和壓印箔的作品則是會隨著光線角度而呈現各種面貌。除了原畫，另有販售翻譯版的繪本和文具小物等。真的非常開心有機會與台灣的粉絲朋友們分享畫作。我也很期待在廊日能與各位見面！\r\n====\r\n作家在廊日\r\n3/8（六）：14:00-19:00\r\n3/9（日）：14:00-19:00\r\n＊請注意其中包含畫家的休息時間，有可能遇到老師不在現場的狀況\r\n在廊活動：\r\n開幕首二日，收藏布川愛子老師原畫作品的朋友\r\n老師將現場繪製明信片大小的小卡作為小禮物給您\r\n可以繪製收藏者本人或家人動物化的模樣\r\n或是家裡的狗狗貓貓等小夥伴\r\n請注意，這個特別活動僅限開幕首二日\r\n參考範例將公布於策展人帳號\r\n另外，畫家也將於現場以單色筆為各位簡單簽繪（簽名+簡易小圖）\r\n＊收藏原畫的小卡片則是會比上述簽繪更精緻\r\n歡迎大家來購買繪本及周邊商品找老師簽名\r\n', `organizer`='綠光+marüte', `address`='臺中市西區', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/O5lyjr', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bce26b32408680bea46', '＜建築師的小小藝緣展＞賴世晃收藏展', '＜看展上癮成藏家－賴世晃建築師的小小藝緣展＞\r\n文／郎亞玲\r\n（連結見留言）\r\n台灣大大小小視覺藝術展眾多，美術館、畫廊、藝博會林立，從東方風格到西方門派，從前輩藝術家作品到青壯世代創作，琳瑯滿目、目不暇給，賴世晃建築師在藝術圈內小有名氣，因為他「逐藝術而居」，雖然職業是開業建築師，也同時在大學任教兼課。但自55歲開始接觸藝術欣賞及收藏，樂此不疲，從來不錯過各項大大小小的展出，拍攝作品鉅細靡遺，發表在個人臉書與粉絲專頁分享，也令未能躬逢其盛的同好，一睹盛況。他自行開車南征北討，如今風塵僕僕已邁入第八年，故藝術同業對他的身影絕不陌生。\r\n「收藏家」的名號乍聽高不可攀，因為對一般大眾而言，觀賞藝術品是一回事，購買和收藏藝術品又是另一回事，「收藏」的先決條件似乎就是要有相當的財力，才能跨出第一步。賴世晃謙虛低調不敢以「藏家」自居，認為看畫、買畫只是自己的嗜好，但也不諱言這些行為已是他生活中不可切割的一部分，以及精神上的重要依靠：\r\n「對於藝術欣賞的酷愛到早已融入生活之中，平日不是去畫廊賞畫，就是去美術館參觀的路上。將我的觀展紀錄分享在臉書社群媒體上，也成為生活中不可或缺的精神養分。」\r\n談起自己收藏的第一件作品，賴世晃反問：「你還記得人生的第一件收藏是什麼嗎？雖然不一定是藝術作品！」他強調的是，「收藏」行為本身就是那麼美好的事情，「收藏」的意義不只是擁有「收藏品」，同時它也代表著收藏當下的心境與情感經驗。他說：\r\n「當我們不期而遇的看見一件作品，並且從喜歡到愛上了它…最後決定要帶它回家，珍藏它的時候，這整個過程應該是一件很單純而自然的事情。」\r\n他覺得成為一位「藏家」並非遙不可及，只要先把念頭放在心上，不疾不徐，等待瓜熟蒂落，每個人總有個開始。而隨著藝術欣賞經驗的累積，與藝術經營者、藝術家的交流互動，個人眼界的開拓等，收藏的深度與廣度便自然會有所增長。\r\n「從一個藝術愛好者，轉變成為所謂藏家，這個過程其實是始料未及的事情！但是我很享受這樣的人生轉變，尤其是在心靈與精神層面上的獲益！」賴世晃表示：「隨心而收，隨緣而藏」地放慢收藏步調，既是自己的收藏歷程，也是勉勵後進的心得。\r\n至於為何有《賴世晃建築師的小小藝緣展》的舉辦?賴世晃表示：\r\n「收藏的這個行為，其實就是在參與推動藝術產業的發生與延續！這次《建築師的小小藝緣展》所分享的藝術作品，目的在分享自己生命中所經歷的，許多美好的藝術欣賞的足跡，藉由此次的展覽，更希望能交流或讓藏給同好，替美好的作品找到新的主人珍愛。」\r\n賴世晃相信：「作品會自己去找主人」，也就是說，好的作品是有生命的！從生命的永恆意義上看，個人都只是暫時保管某個作品。當收藏家從藝術家的創作成果接手後，也許經過了一段歲月，因緣際會之下，作品會有欣賞它的新主人出現。就像拍賣會一樣，好的作品如生命流轉，有種不斷更新與延續的感覺，美好一直不斷被傳承下去。\r\n\r\n賴世晃建築師一向支持中外年輕藝術家，這個展除了透顯他的個人品味，也十足反映了這十年台灣畫壇年輕一輩藝術家的創意力與活力,炫目的色彩，狂飆的線條，隱喻的力道，魔幻的空間，預告了未來世紀的人類處境與藝術家獨特的自我告解與救贖。在2025開春之日，你應當大步向前，為美禮讚！❤️', '亞書藝所', '臺中市西區', '2025-02-05 00:00:00', '2025-03-16 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/XZdzDD', '[]') ON DUPLICATE KEY UPDATE `activity_name`='＜建築師的小小藝緣展＞賴世晃收藏展', `description`='＜看展上癮成藏家－賴世晃建築師的小小藝緣展＞\r\n文／郎亞玲\r\n（連結見留言）\r\n台灣大大小小視覺藝術展眾多，美術館、畫廊、藝博會林立，從東方風格到西方門派，從前輩藝術家作品到青壯世代創作，琳瑯滿目、目不暇給，賴世晃建築師在藝術圈內小有名氣，因為他「逐藝術而居」，雖然職業是開業建築師，也同時在大學任教兼課。但自55歲開始接觸藝術欣賞及收藏，樂此不疲，從來不錯過各項大大小小的展出，拍攝作品鉅細靡遺，發表在個人臉書與粉絲專頁分享，也令未能躬逢其盛的同好，一睹盛況。他自行開車南征北討，如今風塵僕僕已邁入第八年，故藝術同業對他的身影絕不陌生。\r\n「收藏家」的名號乍聽高不可攀，因為對一般大眾而言，觀賞藝術品是一回事，購買和收藏藝術品又是另一回事，「收藏」的先決條件似乎就是要有相當的財力，才能跨出第一步。賴世晃謙虛低調不敢以「藏家」自居，認為看畫、買畫只是自己的嗜好，但也不諱言這些行為已是他生活中不可切割的一部分，以及精神上的重要依靠：\r\n「對於藝術欣賞的酷愛到早已融入生活之中，平日不是去畫廊賞畫，就是去美術館參觀的路上。將我的觀展紀錄分享在臉書社群媒體上，也成為生活中不可或缺的精神養分。」\r\n談起自己收藏的第一件作品，賴世晃反問：「你還記得人生的第一件收藏是什麼嗎？雖然不一定是藝術作品！」他強調的是，「收藏」行為本身就是那麼美好的事情，「收藏」的意義不只是擁有「收藏品」，同時它也代表著收藏當下的心境與情感經驗。他說：\r\n「當我們不期而遇的看見一件作品，並且從喜歡到愛上了它…最後決定要帶它回家，珍藏它的時候，這整個過程應該是一件很單純而自然的事情。」\r\n他覺得成為一位「藏家」並非遙不可及，只要先把念頭放在心上，不疾不徐，等待瓜熟蒂落，每個人總有個開始。而隨著藝術欣賞經驗的累積，與藝術經營者、藝術家的交流互動，個人眼界的開拓等，收藏的深度與廣度便自然會有所增長。\r\n「從一個藝術愛好者，轉變成為所謂藏家，這個過程其實是始料未及的事情！但是我很享受這樣的人生轉變，尤其是在心靈與精神層面上的獲益！」賴世晃表示：「隨心而收，隨緣而藏」地放慢收藏步調，既是自己的收藏歷程，也是勉勵後進的心得。\r\n至於為何有《賴世晃建築師的小小藝緣展》的舉辦?賴世晃表示：\r\n「收藏的這個行為，其實就是在參與推動藝術產業的發生與延續！這次《建築師的小小藝緣展》所分享的藝術作品，目的在分享自己生命中所經歷的，許多美好的藝術欣賞的足跡，藉由此次的展覽，更希望能交流或讓藏給同好，替美好的作品找到新的主人珍愛。」\r\n賴世晃相信：「作品會自己去找主人」，也就是說，好的作品是有生命的！從生命的永恆意義上看，個人都只是暫時保管某個作品。當收藏家從藝術家的創作成果接手後，也許經過了一段歲月，因緣際會之下，作品會有欣賞它的新主人出現。就像拍賣會一樣，好的作品如生命流轉，有種不斷更新與延續的感覺，美好一直不斷被傳承下去。\r\n\r\n賴世晃建築師一向支持中外年輕藝術家，這個展除了透顯他的個人品味，也十足反映了這十年台灣畫壇年輕一輩藝術家的創意力與活力,炫目的色彩，狂飆的線條，隱喻的力道，魔幻的空間，預告了未來世紀的人類處境與藝術家獨特的自我告解與救贖。在2025開春之日，你應當大步向前，為美禮讚！❤️', `organizer`='亞書藝所', `address`='臺中市西區', `start_date`='2025-02-05 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/XZdzDD', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bce26b32408680bea47', '〔 繁華若夢 Dreamscape 〕藝術聯展', '◞◞◞ 2025，夢境與現實的奇幻交錯！ ◟◟◟\r\n#夢境的拼圖 #舊城與光影 #繁華若夢\r\n#虛實交織的藝術多重面貌\r\n​\r\n你是否曾在夢裡迷失於一個既熟悉又陌生的世界？是否想過，那些破碎的回憶與光影，可以拼湊出一場華麗的故事？\r\n​\r\n〈#繁華若夢 #Dreamscape ​〉藝術聯展\r\n帶你踏入如同萬花筒般的空間\r\n探索過去與現在的交匯\r\n揭開每個夢境碎片背後的深刻意義\r\n​\r\n在這座充滿故事的台中百年歷史老宅裡\r\n我們邀請了 7 位才華洋溢的藝術家\r\n以獨特的視覺與聽覺藝術\r\n重新賦予空間生命，讓它在光影間甦醒\r\n​\r\n當你望向那面鏡子，是否看到自己的夢？\r\n伸手觸碰，卻又聽見夢碎的聲音\r\n現實與虛幻在此交織\r\n這是一場心靈與藝術的碰撞\r\n重新定義記憶與情感\r\n​\r\n​\r\n▹ 展覽期間｜2025.01.18 ㊅ - 2025.03.15 ㊅\r\n​\r\n▹ 預約到訪｜https://lihi.cc/gN93S\r\n#全面預約制 到訪前請提前預約\r\n​\r\n▹ 參展人｜王奕恩Iann、王昱喬、白若潔、陌光 柳昱瑄、陳愛莉、張芸家、黃靜萱\r\n▹ 策展人｜石澤芳、許巧郁、莊沛珣、游瑞瑜、楊淵升\r\n​\r\n---\r\n讓我們在這新的一年，共同展開一場穿越夢境的旅程，期待有機會與您相遇在《繁華若夢》現場，一起感受藝術與夢境交疊的深邃與無限可能，並一起拾起這些碎片，打造屬於自己的夢境～ \r\n\r\n2024 年，來自台灣各地的5位青年，因緣際會走進藏身臺中州廳後方、舊城巷弄裡的「民生路老宅56-3」。因感臺中舊城與老宅的美麗與哀愁、因對藝術的熱忱而聚首，這場自告奮勇的藝術策展行動，對這群來自不同專業領域的大學生和社會青年，既是一項全新挑戰，更是一個突破自我界限的契機。\r\n2025 年，希望透過這次策展與7位藝術家的合作，將老宅打造成夢境的畫布，以藝術的語言喚起夢幻的記憶與想像，邀請每位參與者一同入夢，共築夢中之景。', '民生路老宅56-3', '臺中市西區', '2025-01-18 00:00:00', '2025-03-15 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://laozhai.club/2025/01/18/%E7%B9%81%E8%8F%AF%E8%8B%A5%E5%A4%A2dreamscape/?utm_source=blog&utm_', '[]') ON DUPLICATE KEY UPDATE `activity_name`='〔 繁華若夢 Dreamscape 〕藝術聯展', `description`='◞◞◞ 2025，夢境與現實的奇幻交錯！ ◟◟◟\r\n#夢境的拼圖 #舊城與光影 #繁華若夢\r\n#虛實交織的藝術多重面貌\r\n​\r\n你是否曾在夢裡迷失於一個既熟悉又陌生的世界？是否想過，那些破碎的回憶與光影，可以拼湊出一場華麗的故事？\r\n​\r\n〈#繁華若夢 #Dreamscape ​〉藝術聯展\r\n帶你踏入如同萬花筒般的空間\r\n探索過去與現在的交匯\r\n揭開每個夢境碎片背後的深刻意義\r\n​\r\n在這座充滿故事的台中百年歷史老宅裡\r\n我們邀請了 7 位才華洋溢的藝術家\r\n以獨特的視覺與聽覺藝術\r\n重新賦予空間生命，讓它在光影間甦醒\r\n​\r\n當你望向那面鏡子，是否看到自己的夢？\r\n伸手觸碰，卻又聽見夢碎的聲音\r\n現實與虛幻在此交織\r\n這是一場心靈與藝術的碰撞\r\n重新定義記憶與情感\r\n​\r\n​\r\n▹ 展覽期間｜2025.01.18 ㊅ - 2025.03.15 ㊅\r\n​\r\n▹ 預約到訪｜https://lihi.cc/gN93S\r\n#全面預約制 到訪前請提前預約\r\n​\r\n▹ 參展人｜王奕恩Iann、王昱喬、白若潔、陌光 柳昱瑄、陳愛莉、張芸家、黃靜萱\r\n▹ 策展人｜石澤芳、許巧郁、莊沛珣、游瑞瑜、楊淵升\r\n​\r\n---\r\n讓我們在這新的一年，共同展開一場穿越夢境的旅程，期待有機會與您相遇在《繁華若夢》現場，一起感受藝術與夢境交疊的深邃與無限可能，並一起拾起這些碎片，打造屬於自己的夢境～ \r\n\r\n2024 年，來自台灣各地的5位青年，因緣際會走進藏身臺中州廳後方、舊城巷弄裡的「民生路老宅56-3」。因感臺中舊城與老宅的美麗與哀愁、因對藝術的熱忱而聚首，這場自告奮勇的藝術策展行動，對這群來自不同專業領域的大學生和社會青年，既是一項全新挑戰，更是一個突破自我界限的契機。\r\n2025 年，希望透過這次策展與7位藝術家的合作，將老宅打造成夢境的畫布，以藝術的語言喚起夢幻的記憶與想像，邀請每位參與者一同入夢，共築夢中之景。', `organizer`='民生路老宅56-3', `address`='臺中市西區', `start_date`='2025-01-18 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://laozhai.club/2025/01/18/%E7%B9%81%E8%8F%AF%E8%8B%A5%E5%A4%A2dreamscape/?utm_source=blog&utm_', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd026b32408680bea48', '樂活員本-午后時光音樂會', '員本隸屬一個純樸的客家庄，居民多數務農維生，客家農村居民對於客家歌謠情有獨鍾，客家歌謠蘊藏豐富多元的客家生活情感內涵，也孕育出不同的地方人情與歷史文化，冀望可以把先人遺留下來的生活智慧發揚光大，為使目前生活中已日趨沒落的客家山歌得以風華再現，首先我們要從在地居民開始做起，要把哼哼唱唱成為日常生活閒暇嗜好，特以社區為推廣及整合的場域，同時能讓銀髮長者站上舞台延伸音樂美學觸角，音樂可促使族群之間關係和諧與共融。\r\n\r\n13:30-13:50 來賓致詞\r\n13:50-15:50 舞蹈暨客家山歌展演\r\n15:50-16:00 合影賦歸\r\n\r\n活動於員本市民活動中心舉辦，開放非特定對象參與，歡迎民眾踴躍參加。', '桃園市楊梅區員本社區發展協會', '桃園市楊梅區', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '楊梅區（桃園市）=', 24.91820989, 121.1291697, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樂活員本-午后時光音樂會', `description`='員本隸屬一個純樸的客家庄，居民多數務農維生，客家農村居民對於客家歌謠情有獨鍾，客家歌謠蘊藏豐富多元的客家生活情感內涵，也孕育出不同的地方人情與歷史文化，冀望可以把先人遺留下來的生活智慧發揚光大，為使目前生活中已日趨沒落的客家山歌得以風華再現，首先我們要從在地居民開始做起，要把哼哼唱唱成為日常生活閒暇嗜好，特以社區為推廣及整合的場域，同時能讓銀髮長者站上舞台延伸音樂美學觸角，音樂可促使族群之間關係和諧與共融。\r\n\r\n13:30-13:50 來賓致詞\r\n13:50-15:50 舞蹈暨客家山歌展演\r\n15:50-16:00 合影賦歸\r\n\r\n活動於員本市民活動中心舉辦，開放非特定對象參與，歡迎民眾踴躍參加。', `organizer`='桃園市楊梅區員本社區發展協會', `address`='桃園市楊梅區', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='楊梅區（桃園市）=', `latitude`=24.91820989, `longitude`=121.1291697, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd126b32408680bea49', '2025青春美展  【框金又包銀】臺藝大古蹟系110級畢業展', '國立臺灣藝術大學古蹟藝術修護學系成立超過二十年，多年來致力傳授傳統建築裝飾的技法知識予年輕學子。【框金又包銀】展出多件揉合傳統工藝和吉祥寓意的作品，涵蓋古蹟系木雕、彩繪、剪黏以及交趾陶等核心術科課程，是一眾「師仔」希望向大眾分享的四年學藝成果，以期回應民眾對文化資產教育的關切。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-05-17 00:00:00', '2025-05-27 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4101', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展  【框金又包銀】臺藝大古蹟系110級畢業展', `description`='國立臺灣藝術大學古蹟藝術修護學系成立超過二十年，多年來致力傳授傳統建築裝飾的技法知識予年輕學子。【框金又包銀】展出多件揉合傳統工藝和吉祥寓意的作品，涵蓋古蹟系木雕、彩繪、剪黏以及交趾陶等核心術科課程，是一眾「師仔」希望向大眾分享的四年學藝成果，以期回應民眾對文化資產教育的關切。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-27 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4101', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd126b32408680bea4a', '3月份土城圖書館-魔法故事團歡樂說故事', '3/2	這有什麼好怕的\r\n3/9	我不吃手手了\r\n3/16	星期天，你要去哪裡玩？ \r\n3/23	動物園的秘密 ', '臺南市安南區土城圖書館', '臺南市安南區城安路85號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺南市安南區土城圖書館', 23.04869681, 120.1526189, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月份土城圖書館-魔法故事團歡樂說故事', `description`='3/2	這有什麼好怕的\r\n3/9	我不吃手手了\r\n3/16	星期天，你要去哪裡玩？ \r\n3/23	動物園的秘密 ', `organizer`='臺南市安南區土城圖書館', `address`='臺南市安南區城安路85號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市安南區土城圖書館', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd126b32408680bea4c', '「古今共奏 一曲萣情」公益演奏會', '「古今共奏 一曲萣情」公益演奏會\r\n\r\n一、演出人員:\r\n\r\n        茄萣國中國樂團、高雄市牙醫薩克斯風樂團、爵沛薩克斯風重奏團、\r\n\r\n        郭瑩璱音樂創作者、郭進財嗩吶音樂家\r\n\r\n一、主辦單位 : 高雄市茄萣區茄萣國民中學、高雄市牙醫薩克斯風樂團、\r\n\r\n爵沛薩克斯風重奏團\r\n\r\n三、活動時間：114年3月30日下午3:00～5:00\r\n\r\n四、活動地點：高雄市立文化中心至德堂\r\n\r\n五、活動內容及演出曲目與流程：\r\n\r\n    上半場\r\n\r\n    1. 爵沛薩克斯風重奏團 《薩克斯風四重奏》\r\n\r\n    (1) 追追追 (原曲：陳明章，編曲：王裕文)\r\n\r\n    (2) 龍貓組曲 (編曲：福田洋介)\r\n\r\n    (3) 天空落水 (客家民謠，編曲：郭育瑄)\r\n\r\n    (4) 魔女宅急便組曲 (編曲：宮川成治)\r\n\r\n    2. 特別嘉賓郭進財老師嗩吶演奏\r\n\r\n    3. 高雄市牙醫薩克斯風樂團 《薩克斯風四重奏》\r\n\r\n    (1) 寶島曼波 (原曲：洪一峰，編曲：曾雅芳)\r\n\r\n    (2) 愛拚才會贏 (原曲：陳百潭，編曲：曾雅芳)\r\n\r\n    (3) Hymne à l''amour (愛的讚歌) (原曲：Marguerite Monnot，編曲：曾雅芳)\r\n\r\n    (4) Y.M.C.A. (原曲：Henri Belolo/Jacques Morali/Victor Willis，編曲：曾雅芳)\r\n\r\n   中場休息\r\n\r\n    下半場\r\n\r\n   1. 茄萣國中國樂團-山海印象(原曲：蘇文慶)\r\n\r\n   2. 茄萣國中絲竹樂團-搖著槳茉莉小六(原曲：任重)\r\n\r\n   3. 茄萣國中絲竹樂團- Re La(原曲：徐瑋廷)(選段)\r\n\r\n   4. 郭瑩璱演唱/蔡明志 中國笛/國樂團伴奏-情人碼頭(郭瑩璱詞曲創作)\r\n\r\n\r\n   5. 郭瑩璱、賴薇如演唱/蔡明志 中國笛/國樂團伴奏-信魚傳說\r\n\r\n  (郭瑩璱詞曲創作)\r\n\r\n   6. 茄萣國中國樂團-絲綢之路(原曲：姜瑩)\r\n\r\n   演奏會結束\r\n\r\n 六、活動意義\r\n\r\n        茄萣國中國樂團已有110年在大東藝術中心及113年在至德堂的演出經驗，均獲佳評，讓學生再次能在大舞台上以呈現平時練習的成績，及展現信心。\r\n\r\n    而高雄市牙醫薩克斯風樂團、爵沛薩克斯風重奏團這二團的成員大都在中年之後才開始學習樂器，為忙碌工作之餘增添調劑生活的樂趣，進而斜槓藝界的人生。相對於茄萣國中國樂團的學子，在年齡上呈現兩極的反差，但不管老少都有站上大舞台的夢想，在畫面上將有「大手牽小手 同心齊圓夢」的溫馨與感動。\r\n\r\n        同時邀請郭瑩璱為茄萣地區創作的兩首歌曲，以國樂團伴奏形式由郭瑩璱和賴薇如二人演唱，為茄萣地區增添美麗的故事傳說。以及邀請高雄市國樂團嗩吶首席郭進財老師特別演出，給予茄萣國中國樂團的學生領略頂尖國樂演奏的機會。\r\n\r\n\r\n        希望藉由此次演奏會票房收益幫助對茄萣國中國樂團持續推動與發展。', '高雄市牙醫薩克斯風樂團', '高雄市苓雅區001鄰五福一路67號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '--+100;--+200', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「古今共奏 一曲萣情」公益演奏會', `description`='「古今共奏 一曲萣情」公益演奏會\r\n\r\n一、演出人員:\r\n\r\n        茄萣國中國樂團、高雄市牙醫薩克斯風樂團、爵沛薩克斯風重奏團、\r\n\r\n        郭瑩璱音樂創作者、郭進財嗩吶音樂家\r\n\r\n一、主辦單位 : 高雄市茄萣區茄萣國民中學、高雄市牙醫薩克斯風樂團、\r\n\r\n爵沛薩克斯風重奏團\r\n\r\n三、活動時間：114年3月30日下午3:00～5:00\r\n\r\n四、活動地點：高雄市立文化中心至德堂\r\n\r\n五、活動內容及演出曲目與流程：\r\n\r\n    上半場\r\n\r\n    1. 爵沛薩克斯風重奏團 《薩克斯風四重奏》\r\n\r\n    (1) 追追追 (原曲：陳明章，編曲：王裕文)\r\n\r\n    (2) 龍貓組曲 (編曲：福田洋介)\r\n\r\n    (3) 天空落水 (客家民謠，編曲：郭育瑄)\r\n\r\n    (4) 魔女宅急便組曲 (編曲：宮川成治)\r\n\r\n    2. 特別嘉賓郭進財老師嗩吶演奏\r\n\r\n    3. 高雄市牙醫薩克斯風樂團 《薩克斯風四重奏》\r\n\r\n    (1) 寶島曼波 (原曲：洪一峰，編曲：曾雅芳)\r\n\r\n    (2) 愛拚才會贏 (原曲：陳百潭，編曲：曾雅芳)\r\n\r\n    (3) Hymne à l''amour (愛的讚歌) (原曲：Marguerite Monnot，編曲：曾雅芳)\r\n\r\n    (4) Y.M.C.A. (原曲：Henri Belolo/Jacques Morali/Victor Willis，編曲：曾雅芳)\r\n\r\n   中場休息\r\n\r\n    下半場\r\n\r\n   1. 茄萣國中國樂團-山海印象(原曲：蘇文慶)\r\n\r\n   2. 茄萣國中絲竹樂團-搖著槳茉莉小六(原曲：任重)\r\n\r\n   3. 茄萣國中絲竹樂團- Re La(原曲：徐瑋廷)(選段)\r\n\r\n   4. 郭瑩璱演唱/蔡明志 中國笛/國樂團伴奏-情人碼頭(郭瑩璱詞曲創作)\r\n\r\n\r\n   5. 郭瑩璱、賴薇如演唱/蔡明志 中國笛/國樂團伴奏-信魚傳說\r\n\r\n  (郭瑩璱詞曲創作)\r\n\r\n   6. 茄萣國中國樂團-絲綢之路(原曲：姜瑩)\r\n\r\n   演奏會結束\r\n\r\n 六、活動意義\r\n\r\n        茄萣國中國樂團已有110年在大東藝術中心及113年在至德堂的演出經驗，均獲佳評，讓學生再次能在大舞台上以呈現平時練習的成績，及展現信心。\r\n\r\n    而高雄市牙醫薩克斯風樂團、爵沛薩克斯風重奏團這二團的成員大都在中年之後才開始學習樂器，為忙碌工作之餘增添調劑生活的樂趣，進而斜槓藝界的人生。相對於茄萣國中國樂團的學子，在年齡上呈現兩極的反差，但不管老少都有站上大舞台的夢想，在畫面上將有「大手牽小手 同心齊圓夢」的溫馨與感動。\r\n\r\n        同時邀請郭瑩璱為茄萣地區創作的兩首歌曲，以國樂團伴奏形式由郭瑩璱和賴薇如二人演唱，為茄萣地區增添美麗的故事傳說。以及邀請高雄市國樂團嗩吶首席郭進財老師特別演出，給予茄萣國中國樂團的學生領略頂尖國樂演奏的機會。\r\n\r\n\r\n        希望藉由此次演奏會票房收益幫助對茄萣國中國樂團持續推動與發展。', `organizer`='高雄市牙醫薩克斯風樂團', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='--+100;--+200', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd126b32408680bea4d', 'Takeshi Sakamoto T.S.O.P Band', 'T.S.O.P., Takeshi Sakamoto Original Project，為日籍爵士鼓手坂本健志Takeshi Sakamoto個人Project。現代爵士具有多樣性，每個樂手受不同的音樂的影響，進而創作自己的音樂。T.S.O.P.受Neo Soul、HipHop、Post Rock、Contenporary Jazz等各種音樂影響。以爵士鼓手為主的現代樂團，如Brian Blade Fellowship、 Kendrick Scott Oracle、Antonio Sanchez Migration、Nate Smith & Kinfolk等，鼓手為了追求音樂性所成立的Project樂團，T.S.O.P. 期以同樣團員追究新時代爵士樂。', '爵式 WiJazz Records', '高雄市鹽埕區17鄰真愛路1號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人+600', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Takeshi Sakamoto T.S.O.P Band', `description`='T.S.O.P., Takeshi Sakamoto Original Project，為日籍爵士鼓手坂本健志Takeshi Sakamoto個人Project。現代爵士具有多樣性，每個樂手受不同的音樂的影響，進而創作自己的音樂。T.S.O.P.受Neo Soul、HipHop、Post Rock、Contenporary Jazz等各種音樂影響。以爵士鼓手為主的現代樂團，如Brian Blade Fellowship、 Kendrick Scott Oracle、Antonio Sanchez Migration、Nate Smith & Kinfolk等，鼓手為了追求音樂性所成立的Project樂團，T.S.O.P. 期以同樣團員追究新時代爵士樂。', `organizer`='爵式 WiJazz Records', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人+600', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd226b32408680bea4e', '【2025永康區社教中心研習班成果展】 ', '【2025永康區社教中心研習班成果展】 \r\n人文美學研習班展出之成果有書法、水墨畫、美食水彩畫、色鉛筆、粉彩畫、手捏壺、皮件包及織布包等，小編已幫大家美美的作品上架囉~每件作品都非常優秀！充分展現研習班學員們的學習成果，歡迎有興趣的民眾到場欣賞參觀喔 \r\n', '臺南市永康區社教中心', '臺南市永康區永大二路88號', '2025-03-04 00:00:00', '2025-04-06 00:00:00', '臺南市永康區社教中心(永康區圖書館)', 23.02729532, 120.2542795, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025永康區社教中心研習班成果展】 ', `description`='【2025永康區社教中心研習班成果展】 \r\n人文美學研習班展出之成果有書法、水墨畫、美食水彩畫、色鉛筆、粉彩畫、手捏壺、皮件包及織布包等，小編已幫大家美美的作品上架囉~每件作品都非常優秀！充分展現研習班學員們的學習成果，歡迎有興趣的民眾到場欣賞參觀喔 \r\n', `organizer`='臺南市永康區社教中心', `address`='臺南市永康區永大二路88號', `start_date`='2025-03-04 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='臺南市永康區社教中心(永康區圖書館)', `latitude`=23.02729532, `longitude`=120.2542795, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd226b32408680bea4f', '高雄市立圖書館大樹三館114年3月主題書展', '1.【SDGs#10(減少國內及國家間不平等)主題書展】--因應聯合國2015年宣佈「2030永續發展目標」中第十項目標，減少國家内部和國家之間的不平等，展出多元文化、移工、食物銀行、志工、宗教信仰、交朋友、尊重他人等相關書籍，供民眾翻閱。\r\n2.【講客話，親山水】主題書展--\r\n★推廣客語書籍，讓民眾透過閱讀感受客家語言與文化的山水情懷。\r\n★營造簡約雅緻的書展氛圍，讓參觀者自然融入客語文化的美好。 \r\n\r\n \r\n', '高雄市立圖書館總館', '高雄市大樹區溪埔路77號3樓', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館大樹三館', 22.71100364, 120.425407, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市立圖書館大樹三館114年3月主題書展', `description`='1.【SDGs#10(減少國內及國家間不平等)主題書展】--因應聯合國2015年宣佈「2030永續發展目標」中第十項目標，減少國家内部和國家之間的不平等，展出多元文化、移工、食物銀行、志工、宗教信仰、交朋友、尊重他人等相關書籍，供民眾翻閱。\r\n2.【講客話，親山水】主題書展--\r\n★推廣客語書籍，讓民眾透過閱讀感受客家語言與文化的山水情懷。\r\n★營造簡約雅緻的書展氛圍，讓參觀者自然融入客語文化的美好。 \r\n\r\n \r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市大樹區溪埔路77號3樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館大樹三館', `latitude`=22.71100364, `longitude`=120.425407, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd226b32408680bea50', '高雄市立圖書館大樹分館114年3月主題書展', '1.【SDGs#5(性別平等)主題書展】--因應聯合國2015年宣佈「2030永續發展目標」中第五項目標，實現性別平等及所有女性之賦權，展出刻板印象、女性權利、性平教育、人權、性別歧視、性騷擾等相關書籍，供民眾翻閱。(展期:114.1.2~3.30)\r\n2.【多元之美：「泰」、「印」、「越」書香之旅】--透過書籍增進對泰國、印度和越南豐富文化的認識,促進包容性和理解，這次書展將成為一個讓人們相遇與對話的場所，展示書籍的力量如何連結不同文化的心靈。(展期:114.1.2~3.30)', '高雄市立圖書館總館', '高雄市大樹區17鄰中興西路50號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館大樹分館', 22.6912015, 120.4303983, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市立圖書館大樹分館114年3月主題書展', `description`='1.【SDGs#5(性別平等)主題書展】--因應聯合國2015年宣佈「2030永續發展目標」中第五項目標，實現性別平等及所有女性之賦權，展出刻板印象、女性權利、性平教育、人權、性別歧視、性騷擾等相關書籍，供民眾翻閱。(展期:114.1.2~3.30)\r\n2.【多元之美：「泰」、「印」、「越」書香之旅】--透過書籍增進對泰國、印度和越南豐富文化的認識,促進包容性和理解，這次書展將成為一個讓人們相遇與對話的場所，展示書籍的力量如何連結不同文化的心靈。(展期:114.1.2~3.30)', `organizer`='高雄市立圖書館總館', `address`='高雄市大樹區17鄰中興西路50號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館大樹分館', `latitude`=22.6912015, `longitude`=120.4303983, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd226b32408680bea51', '客庄小探險', '★選擇簡單、有趣的客語繪本故事，如《山上的小花貓、或阿婆的客家菜園》。引導孩子用客語簡單回答。 \r\n★以活潑生動的方式，引導孩子對客語文化產生興趣與親近感。\r\n', '高雄市立圖書館總館', '高雄市大樹區溪埔路77號3樓', '2025-03-18 00:00:00', '2025-03-18 00:00:00', '高雄市立圖書館大樹三館', 22.71100364, 120.425407, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='客庄小探險', `description`='★選擇簡單、有趣的客語繪本故事，如《山上的小花貓、或阿婆的客家菜園》。引導孩子用客語簡單回答。 \r\n★以活潑生動的方式，引導孩子對客語文化產生興趣與親近感。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市大樹區溪埔路77號3樓', `start_date`='2025-03-18 00:00:00', `end_date`='2025-03-18 00:00:00', `location`='高雄市立圖書館大樹三館', `latitude`=22.71100364, `longitude`=120.425407, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd226b32408680bea52', '苗栗賽夏族聚落70-80年代人文風景老照片特展', '本展透過照片的紀錄呈現來介紹民國70-80年代左右在南庄向天湖及蓬萊等地，完整呈現當年賽夏族人文風情、地理景觀珍貴記憶，內容豐富多元，值得前來賽夏館一睹當時風采。', '苗栗縣政府原住民族及族群發展處', '苗栗縣南庄鄉苗栗縣南庄鄉東河村16鄰向天湖25號', '2025-03-11 00:00:00', '2025-06-11 00:00:00', '苗栗縣賽夏族民俗文物館', 24.56608432, 121.017471, '全票+30;團體票+20;優待票+10', 'https://www.facebook.com/rareme037825024', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗栗賽夏族聚落70-80年代人文風景老照片特展', `description`='本展透過照片的紀錄呈現來介紹民國70-80年代左右在南庄向天湖及蓬萊等地，完整呈現當年賽夏族人文風情、地理景觀珍貴記憶，內容豐富多元，值得前來賽夏館一睹當時風采。', `organizer`='苗栗縣政府原住民族及族群發展處', `address`='苗栗縣南庄鄉苗栗縣南庄鄉東河村16鄰向天湖25號', `start_date`='2025-03-11 00:00:00', `end_date`='2025-06-11 00:00:00', `location`='苗栗縣賽夏族民俗文物館', `latitude`=24.56608432, `longitude`=121.017471, `ticket_price`='全票+30;團體票+20;優待票+10', `source_url`='https://www.facebook.com/rareme037825024', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd226b32408680bea53', '看卡通學美語 Cartoon Movie(三月)', '活動內容：寶珠分館「美國專區」每月播放一部好看卡通~歡迎家長與小朋友一同歡賞！卡通內容皆為英文發音中文字幕，歡迎家長與小朋友一起，快樂看卡通輕鬆學美語！\r\n\r\n卡通名稱：鐘樓怪人 The Hunchback of Notre Dame\r\n活動時間：3月15日 14：00－16：00（依影片長度增減）\r\n※毋需報名，現場參加即可。\r\n費用：免費\r\n活動對象：有興趣之家長與小朋友', '高雄市立圖書館總館', '高雄市三民區002鄰大順二路468號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '高雄市立圖書館寶珠分館', 22.649382, 120.3249695, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='看卡通學美語 Cartoon Movie(三月)', `description`='活動內容：寶珠分館「美國專區」每月播放一部好看卡通~歡迎家長與小朋友一同歡賞！卡通內容皆為英文發音中文字幕，歡迎家長與小朋友一起，快樂看卡通輕鬆學美語！\r\n\r\n卡通名稱：鐘樓怪人 The Hunchback of Notre Dame\r\n活動時間：3月15日 14：00－16：00（依影片長度增減）\r\n※毋需報名，現場參加即可。\r\n費用：免費\r\n活動對象：有興趣之家長與小朋友', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區002鄰大順二路468號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='高雄市立圖書館寶珠分館', `latitude`=22.649382, `longitude`=120.3249695, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd226b32408680bea55', 'English Storytelling 英語故事快樂頌(三月)', '為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動志工，至寶珠分館說故事。運用本館館藏，以說演繪本故事。\r\n\r\n課程內容：故事是最棒的橋樑，使孩子與英文相遇相知。歡迎孩子們一同踏上英語故事的奇幻之旅，探索未知的廣大世界吧！\r\n\r\n活動時間：每週日10:30~11:30\r\n師資簡介：關翠萍等(英語故事達人)\r\n活動對象：有興趣的小朋友，自由參加\r\n活動費用：免費', '高雄市立圖書館總館', '高雄市三民區002鄰大順二路468號', '2025-03-02 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館寶珠分館', 22.649382, 120.3249695, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='English Storytelling 英語故事快樂頌(三月)', `description`='為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動志工，至寶珠分館說故事。運用本館館藏，以說演繪本故事。\r\n\r\n課程內容：故事是最棒的橋樑，使孩子與英文相遇相知。歡迎孩子們一同踏上英語故事的奇幻之旅，探索未知的廣大世界吧！\r\n\r\n活動時間：每週日10:30~11:30\r\n師資簡介：關翠萍等(英語故事達人)\r\n活動對象：有興趣的小朋友，自由參加\r\n活動費用：免費', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區002鄰大順二路468號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館寶珠分館', `latitude`=22.649382, `longitude`=120.3249695, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd226b32408680bea56', 'Fun 心聽故事(寶珠分館三月)', '為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動志工，至寶珠分館說故事。運用本館館藏，以說演繪本故事。\r\n\r\n活動時間：週五10:00~11:00 週六10:00~11:00 週日15:00~16:00\r\n\r\n師資簡介：郭淑玲等(故事達人)\r\n活動對象：有興趣的小朋友，自由參加\r\n活動費用：免費', '高雄市立圖書館總館', '高雄市三民區002鄰大順二路468號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館寶珠分館', 22.649382, 120.3249695, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Fun 心聽故事(寶珠分館三月)', `description`='為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動志工，至寶珠分館說故事。運用本館館藏，以說演繪本故事。\r\n\r\n活動時間：週五10:00~11:00 週六10:00~11:00 週日15:00~16:00\r\n\r\n師資簡介：郭淑玲等(故事達人)\r\n活動對象：有興趣的小朋友，自由參加\r\n活動費用：免費', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區002鄰大順二路468號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館寶珠分館', `latitude`=22.649382, `longitude`=120.3249695, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd226b32408680bea57', '毛絨絨的陪伴-寵物主題書展', '寵物是許多人家庭中不可或缺的家人，與我們的生活密不可分，本次書展以寵物為主題，展出推薦主題圖書如德叔寵物聯合國、心中住了一隻貓、帶戈壁回家...等，舉辦圖書展覽，增進讀者知識。\r\n\r\n活動對象：自由參加。\r\n費用：免費。\r\n活動時間：開館時間內。', '高雄市立圖書館總館', '高雄市三民區002鄰大順二路468號', '2025-03-01 00:00:00', '2025-04-25 00:00:00', '高雄市立圖書館寶珠分館', 22.649382, 120.3249695, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='毛絨絨的陪伴-寵物主題書展', `description`='寵物是許多人家庭中不可或缺的家人，與我們的生活密不可分，本次書展以寵物為主題，展出推薦主題圖書如德叔寵物聯合國、心中住了一隻貓、帶戈壁回家...等，舉辦圖書展覽，增進讀者知識。\r\n\r\n活動對象：自由參加。\r\n費用：免費。\r\n活動時間：開館時間內。', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區002鄰大順二路468號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='高雄市立圖書館寶珠分館', `latitude`=22.649382, `longitude`=120.3249695, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd226b32408680bea58', '貓熊警察繪本遊戲特展', '寶珠圖書館藝文走廊現正展示超可愛、超有趣的遊戲特展，由鬼才繪本作家 信子 創作的《貓熊警察》可是台灣第一本原創的繪本遊戲書，同時展示老師親手繪製的手稿，細膩入微，歡迎有興趣的讀者、親子蒞臨參觀！\r\n展出時間：114/03/01~114/04/17 開館時間週二~週六09:00-21:00，週日09:00-17:00\r\n展出地點：高市圖寶珠分館 藝文走廊', '高雄市立圖書館總館', '高雄市三民區002鄰大順二路468號', '2025-03-01 00:00:00', '2025-04-17 00:00:00', '高雄市立圖書館寶珠分館', 22.649382, 120.3249695, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='貓熊警察繪本遊戲特展', `description`='寶珠圖書館藝文走廊現正展示超可愛、超有趣的遊戲特展，由鬼才繪本作家 信子 創作的《貓熊警察》可是台灣第一本原創的繪本遊戲書，同時展示老師親手繪製的手稿，細膩入微，歡迎有興趣的讀者、親子蒞臨參觀！\r\n展出時間：114/03/01~114/04/17 開館時間週二~週六09:00-21:00，週日09:00-17:00\r\n展出地點：高市圖寶珠分館 藝文走廊', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區002鄰大順二路468號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-17 00:00:00', `location`='高雄市立圖書館寶珠分館', `latitude`=22.649382, `longitude`=120.3249695, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd226b32408680bea5a', 'FUN心聽故事(楠仔坑分館3月份)', '由高雄市立圖書館所培訓，說故事經驗豐富的故事達人，透過豐富的肢體語言與生動有趣的互動方式，帶領大小朋友從故事中遨遊書海，引導孩子從繪本閱讀進入文字閱讀，歡迎大朋友小朋友踴躍參加。', '高雄市立圖書館總館', '高雄市楠梓區楠梓路262號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '高雄市立圖書館楠仔坑分館', 22.7334902, 120.3278826, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽故事(楠仔坑分館3月份)', `description`='由高雄市立圖書館所培訓，說故事經驗豐富的故事達人，透過豐富的肢體語言與生動有趣的互動方式，帶領大小朋友從故事中遨遊書海，引導孩子從繪本閱讀進入文字閱讀，歡迎大朋友小朋友踴躍參加。', `organizer`='高雄市立圖書館總館', `address`='高雄市楠梓區楠梓路262號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='高雄市立圖書館楠仔坑分館', `latitude`=22.7334902, `longitude`=120.3278826, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd326b32408680bea5b', '世界母語日—語你童樂唱歌謠', '講師以台語帶領親子透過歌謠與念謠進入母語的世界，活動從耳熟能詳的台語歌謠開始，讓參與者在輕鬆歡樂的氛圍中自然而然接觸母語詞彙，增強對母語的感官記憶。', '高雄市立圖書館總館', '高雄市楠梓區楠梓路262號', '2025-03-08 00:00:00', '2025-03-22 00:00:00', '高雄市立圖書館楠仔坑分館', 22.7334902, 120.3278826, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='世界母語日—語你童樂唱歌謠', `description`='講師以台語帶領親子透過歌謠與念謠進入母語的世界，活動從耳熟能詳的台語歌謠開始，讓參與者在輕鬆歡樂的氛圍中自然而然接觸母語詞彙，增強對母語的感官記憶。', `organizer`='高雄市立圖書館總館', `address`='高雄市楠梓區楠梓路262號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='高雄市立圖書館楠仔坑分館', `latitude`=22.7334902, `longitude`=120.3278826, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd326b32408680bea5c', '阿嬤故鄉ㄟ故事-台語講古', '以台語說演精彩有趣之繪本故事及童謠，讓故事達人帶著大小朋友進圖書館一同感受台語之美，歡迎大朋友小朋友踴躍參加，共度歡樂的週末時光!!！\r\n報名方式:自由入場\r\n活動日期:3/1(六)、3/2(日)、3/8(六)、3/9(日)、3/15(六)、3/16(日)、3/22(六)、3/23(日)、3/29(六)、3/30(日)，上午10：00~11：00。', '高雄市立圖書館總館', '高雄市鳳山區7鄰自強一路119巷75號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館鳳山二館', 22.589421, 120.3273098, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='阿嬤故鄉ㄟ故事-台語講古', `description`='以台語說演精彩有趣之繪本故事及童謠，讓故事達人帶著大小朋友進圖書館一同感受台語之美，歡迎大朋友小朋友踴躍參加，共度歡樂的週末時光!!！\r\n報名方式:自由入場\r\n活動日期:3/1(六)、3/2(日)、3/8(六)、3/9(日)、3/15(六)、3/16(日)、3/22(六)、3/23(日)、3/29(六)、3/30(日)，上午10：00~11：00。', `organizer`='高雄市立圖書館總館', `address`='高雄市鳳山區7鄰自強一路119巷75號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館鳳山二館', `latitude`=22.589421, `longitude`=120.3273098, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
