INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd326b32408680bea5f', 'FUN心聽故事 (小港分館三月)', '由高雄市立圖書館所培訓的一群義務故事志工，透過豐富的肢體語言與生動有大象不跳趣的互動方式，為小朋友說故事，現場並擺設相關書籍展示，歡迎大家踴躍參加。', '高雄市立圖書館總館', '高雄市小港區博學路365號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館小港分館', 22.5605891, 120.3705758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽故事 (小港分館三月)', `description`='由高雄市立圖書館所培訓的一群義務故事志工，透過豐富的肢體語言與生動有大象不跳趣的互動方式，為小朋友說故事，現場並擺設相關書籍展示，歡迎大家踴躍參加。', `organizer`='高雄市立圖書館總館', `address`='高雄市小港區博學路365號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館小港分館', `latitude`=22.5605891, `longitude`=120.3705758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd326b32408680bea60', '新南國小社團成果發表會', '每年5月份是溫馨的月份，同時也是歡迎一年級新生報到的日子，為了讓家長對於新南國小的認識能夠更全面化，我們會挑選5月初的第一天作為教學與社團的成果展示。\r\n苗北藝文中心是一個代表苗栗縣藝文表演的殿堂，在新南國小家長會的支持下，希望學校能夠提供給學生一個很棒的表演舞台。此次的表演內容有氣勢磅礡的新南國小三大音樂社團之一，節令鼓隊《雷霆萬鈞慶佳節》來帶動學生才藝活動的開幕，緊接的學生的對口相聲《我來送禮啦》引導嘉賓對新南國小的讚譽；校長要為身先士卒為表率口琴演奏的《迎賓曲》歡迎今晚的嘉賓，一年級《當你的小孩真好》演出新南師生關係融洽，在新南國小學習是件幸福的事，新南國小旁邊是五穀宮，三年級《農家樂》表達出新南里的居民純樸厚實一片祥樂，除了務實之外學校也重視學生課外活動，四年級《三振舞》帶了國民棒球歡慶喜悅，如此的歡慶代表著我們幸福滿滿，感謝二年級帶來《幸福甜甜圈》，每個人的嘴角都是微微上揚，內心是甜甜的欣喜。\r\n班級教學成果展示完後就是本校第二個音樂社團展出，直笛隊帶來《D大調卡農》、《少年》、《Havin'' Fun》、《月亮代表我的心》告訴即將畢業的三位老師(王乙財、徐正忠、何進)以及教育處服務的儲備校長-莊夏萍主任，你們是學生的指引，就如同晚上的月亮溫暖、皎潔。\r\n下半場是邱美燕老師《戰颱風》古箏演出，訴說這群在新南奮鬥的師長，您們的奮鬥都是有意義的，緊接上場國樂團3-6年級合奏《踏江》、《杵舞石音》後，演出的學生是剛入國樂門的3-4年級學生，表演《歡樂的夜晚&洋娃與小熊跳舞》與畢業生《鬧新春》來一段薪火相傳，今晚整場表演到此畫下一個完美的ending。\r\n\r\n入場方式：4/18(五)起，請洽苗北服務台或新南國小學務處林老師037-613843#103，每人限索4張。', '苗栗縣竹南鎮新南國民小學', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-05-07 00:00:00', '2025-05-07 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新南國小社團成果發表會', `description`='每年5月份是溫馨的月份，同時也是歡迎一年級新生報到的日子，為了讓家長對於新南國小的認識能夠更全面化，我們會挑選5月初的第一天作為教學與社團的成果展示。\r\n苗北藝文中心是一個代表苗栗縣藝文表演的殿堂，在新南國小家長會的支持下，希望學校能夠提供給學生一個很棒的表演舞台。此次的表演內容有氣勢磅礡的新南國小三大音樂社團之一，節令鼓隊《雷霆萬鈞慶佳節》來帶動學生才藝活動的開幕，緊接的學生的對口相聲《我來送禮啦》引導嘉賓對新南國小的讚譽；校長要為身先士卒為表率口琴演奏的《迎賓曲》歡迎今晚的嘉賓，一年級《當你的小孩真好》演出新南師生關係融洽，在新南國小學習是件幸福的事，新南國小旁邊是五穀宮，三年級《農家樂》表達出新南里的居民純樸厚實一片祥樂，除了務實之外學校也重視學生課外活動，四年級《三振舞》帶了國民棒球歡慶喜悅，如此的歡慶代表著我們幸福滿滿，感謝二年級帶來《幸福甜甜圈》，每個人的嘴角都是微微上揚，內心是甜甜的欣喜。\r\n班級教學成果展示完後就是本校第二個音樂社團展出，直笛隊帶來《D大調卡農》、《少年》、《Havin'' Fun》、《月亮代表我的心》告訴即將畢業的三位老師(王乙財、徐正忠、何進)以及教育處服務的儲備校長-莊夏萍主任，你們是學生的指引，就如同晚上的月亮溫暖、皎潔。\r\n下半場是邱美燕老師《戰颱風》古箏演出，訴說這群在新南奮鬥的師長，您們的奮鬥都是有意義的，緊接上場國樂團3-6年級合奏《踏江》、《杵舞石音》後，演出的學生是剛入國樂門的3-4年級學生，表演《歡樂的夜晚&洋娃與小熊跳舞》與畢業生《鬧新春》來一段薪火相傳，今晚整場表演到此畫下一個完美的ending。\r\n\r\n入場方式：4/18(五)起，請洽苗北服務台或新南國小學務處林老師037-613843#103，每人限索4張。', `organizer`='苗栗縣竹南鎮新南國民小學', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-05-07 00:00:00', `end_date`='2025-05-07 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd326b32408680bea61', '主題書展─想要車子嗎？書裡(應該)都有！', '科技日新月異，橫跨千里從要耗時數月甚至是數年，成為有多種快速又省力的交通工具可以選擇，像是汽車、火車、高鐵等等。\r\n　　車輛發展的歷史是技術的革新，也是人類文明進步的縮影。從早期驅使動物或人力的拉車，到現今使用電力、石油驅動的汽車，這些演變不僅改變了交通方式，也深刻影響了人們的生活。近年來，車子也成為人們不可或缺好夥伴。\r\n', '高雄市立圖書館總館', '高雄市小港區博學路365號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '高雄市立圖書館小港分館', 22.5605891, 120.3705758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='主題書展─想要車子嗎？書裡(應該)都有！', `description`='科技日新月異，橫跨千里從要耗時數月甚至是數年，成為有多種快速又省力的交通工具可以選擇，像是汽車、火車、高鐵等等。\r\n　　車輛發展的歷史是技術的革新，也是人類文明進步的縮影。從早期驅使動物或人力的拉車，到現今使用電力、石油驅動的汽車，這些演變不僅改變了交通方式，也深刻影響了人們的生活。近年來，車子也成為人們不可或缺好夥伴。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市小港區博學路365號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='高雄市立圖書館小港分館', `latitude`=22.5605891, `longitude`=120.3705758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd326b32408680bea62', '2025東海大學音樂系協奏曲優勝者暨管弦樂團音樂會', '演出介紹\r\n指揮 / 賴鏡淳\r\n薩克斯風 / 張紀鐸\r\n樂團 / 東海大學音樂系管弦樂團\r\n\r\n演出曲目 /\r\nR. Wagner: Siegfried Idyll\r\nR. Molinelli: Four Pictures from New York\r\nW. A. Mozart Arr. Claudio Estay: Die Zauberflöte Overture\r\nW. A. Mozart: Symphony No. 36 " Linz "', '東海大學音樂學系', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-05-11 00:00:00', '2025-05-11 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '票價+100;票價+300;票價+500', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025東海大學音樂系協奏曲優勝者暨管弦樂團音樂會', `description`='演出介紹\r\n指揮 / 賴鏡淳\r\n薩克斯風 / 張紀鐸\r\n樂團 / 東海大學音樂系管弦樂團\r\n\r\n演出曲目 /\r\nR. Wagner: Siegfried Idyll\r\nR. Molinelli: Four Pictures from New York\r\nW. A. Mozart Arr. Claudio Estay: Die Zauberflöte Overture\r\nW. A. Mozart: Symphony No. 36 " Linz "', `organizer`='東海大學音樂學系', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-05-11 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='票價+100;票價+300;票價+500', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd326b32408680bea63', '《管弦絲竹知多少》－可愛動物系列', '《管弦絲竹知多少》藝文列車系列活動，邀請竹苗地區學生至苗北藝文中心欣賞演出。一段優美的旋律、拍手的節奏，擁抱音樂記憶中最美好的時刻，期待透過旋律啟動一個意念、將國樂之美注入竹苗地區的孩子心中，激發每一位孩子對於國樂的認識與喜愛。\r\n由新竹青年國樂團與台灣光罩基金會及苗北藝文中心合作，落實地方資源整合之目的，透過三方合作，讓國樂樹苗向下紮根、向上伸展，每一片葉子都是一個意念，藉由各界的澆灌、吸取善意的養份。音樂不只療癒人心、更是對生命的記憶，在這個充滿希望、新生的春天裡，竹青帶著音樂走向苗北藝文中心、邀請您一起將國樂的感動植入人心。\r\n音樂會安排從《管弦絲竹知多少》樂曲掀起序幕，帶領小小聽眾們，認識國樂器各家族的獨特音色及演奏法，接著安排多首富有特色及趣味的器樂獨奏及經典合奏曲目。2025藝文列車－管弦絲竹知多少系列音樂會，此次演出的主題「可愛動物系列」，藉由國樂曲目的多元，帶領孩子欣賞國樂美妙的動人旋律，藉指揮劉江濱老師妙語如珠的主持，由淺入深帶領聽眾進入美妙的國樂世界，同時將欣賞音樂會的禮儀傳遞給孩子們，以達到寓教於樂之目的，進而在孩子們的心中種下音樂的種子。\r\n入場方式：索票，4/15(二)9時起，請洽苗北服務台或新竹青年國樂團李小姐(0916-853-848)，每人限索2張。', '新竹青年國樂團', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-05-14 00:00:00', '2025-05-14 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《管弦絲竹知多少》－可愛動物系列', `description`='《管弦絲竹知多少》藝文列車系列活動，邀請竹苗地區學生至苗北藝文中心欣賞演出。一段優美的旋律、拍手的節奏，擁抱音樂記憶中最美好的時刻，期待透過旋律啟動一個意念、將國樂之美注入竹苗地區的孩子心中，激發每一位孩子對於國樂的認識與喜愛。\r\n由新竹青年國樂團與台灣光罩基金會及苗北藝文中心合作，落實地方資源整合之目的，透過三方合作，讓國樂樹苗向下紮根、向上伸展，每一片葉子都是一個意念，藉由各界的澆灌、吸取善意的養份。音樂不只療癒人心、更是對生命的記憶，在這個充滿希望、新生的春天裡，竹青帶著音樂走向苗北藝文中心、邀請您一起將國樂的感動植入人心。\r\n音樂會安排從《管弦絲竹知多少》樂曲掀起序幕，帶領小小聽眾們，認識國樂器各家族的獨特音色及演奏法，接著安排多首富有特色及趣味的器樂獨奏及經典合奏曲目。2025藝文列車－管弦絲竹知多少系列音樂會，此次演出的主題「可愛動物系列」，藉由國樂曲目的多元，帶領孩子欣賞國樂美妙的動人旋律，藉指揮劉江濱老師妙語如珠的主持，由淺入深帶領聽眾進入美妙的國樂世界，同時將欣賞音樂會的禮儀傳遞給孩子們，以達到寓教於樂之目的，進而在孩子們的心中種下音樂的種子。\r\n入場方式：索票，4/15(二)9時起，請洽苗北服務台或新竹青年國樂團李小姐(0916-853-848)，每人限索2張。', `organizer`='新竹青年國樂團', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-05-14 00:00:00', `end_date`='2025-05-14 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0bd326b32408680bea64', '苗栗縣頭份市僑善國民小學2025藝術才能舞蹈班年度舞展-三十舞啟程', '入場方式：索票，4/28(一)起，請洽苗北服務台或僑善國小舞蹈班037-663137#177，每人限索4張。\r\n\r\n揉合現代與古典，結合活力與纖細。\r\n以豐富多元的姿態、多采多姿的舞蹈，展現孩子們的成長印記。\r\n僑善國小舞蹈班自79年成立迄今，不遺餘力的推展舞蹈教育。\r\n經過多年的經營，在專業的舞蹈教師指導下，打下了堅實的基礎與口碑，榮獲無數舞蹈競賽佳績，且經常受邀參與校內外機關團體及社區藝文活動演出。\r\n每年為了展現學生辛苦的學習成果，皆規劃一場次之成果展演，讓學生能將一年來之學習內容，展現在眾人眼前。今年，我們同樣規劃了一場精采可期的舞蹈成果展演，以芭蕾、民俗、現代等多樣化的型態，讓孩子們將自己一年來的成長，以多元化的舞蹈姿態展現在眾人眼前。表演中，孩子們的活潑、動感、柔美、細膩，都將能分別於三、四、五、六年級舞蹈班學生的表演中，一一展現，期待能為觀眾帶來一場令人耳目一新，且充滿感動的感官享受。', '苗栗縣頭份市僑善國民小學', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-05-16 00:00:00', '2025-05-16 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗栗縣頭份市僑善國民小學2025藝術才能舞蹈班年度舞展-三十舞啟程', `description`='入場方式：索票，4/28(一)起，請洽苗北服務台或僑善國小舞蹈班037-663137#177，每人限索4張。\r\n\r\n揉合現代與古典，結合活力與纖細。\r\n以豐富多元的姿態、多采多姿的舞蹈，展現孩子們的成長印記。\r\n僑善國小舞蹈班自79年成立迄今，不遺餘力的推展舞蹈教育。\r\n經過多年的經營，在專業的舞蹈教師指導下，打下了堅實的基礎與口碑，榮獲無數舞蹈競賽佳績，且經常受邀參與校內外機關團體及社區藝文活動演出。\r\n每年為了展現學生辛苦的學習成果，皆規劃一場次之成果展演，讓學生能將一年來之學習內容，展現在眾人眼前。今年，我們同樣規劃了一場精采可期的舞蹈成果展演，以芭蕾、民俗、現代等多樣化的型態，讓孩子們將自己一年來的成長，以多元化的舞蹈姿態展現在眾人眼前。表演中，孩子們的活潑、動感、柔美、細膩，都將能分別於三、四、五、六年級舞蹈班學生的表演中，一一展現，期待能為觀眾帶來一場令人耳目一新，且充滿感動的感官享受。', `organizer`='苗栗縣頭份市僑善國民小學', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-05-16 00:00:00', `end_date`='2025-05-16 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
