INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67caa03e07f3d4433af9554a', '木雕分館「遊木‧逛歷史」教育手作市集', '無資料', '中台世界博物館木雕分館', '南投縣埔里鎮中台路6號', '2025-04-05 00:00:00', '2025-04-05 00:00:00', '中台世界博物館木雕分館 雲華餐廳戶外空間', 23.97892591, 120.9625259, '免費參加，活動當天憑貼紙或集章卡可入館參觀本館及木雕分館', 'https://lihi.cc/UAnlW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='木雕分館「遊木‧逛歷史」教育手作市集', `description`='無資料', `organizer`='中台世界博物館木雕分館', `address`='南投縣埔里鎮中台路6號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-05 00:00:00', `location`='中台世界博物館木雕分館 雲華餐廳戶外空間', `latitude`=23.97892591, `longitude`=120.9625259, `ticket_price`='免費參加，活動當天憑貼紙或集章卡可入館參觀本館及木雕分館', `source_url`='https://lihi.cc/UAnlW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67caad8d07f3d4433af9554b', '2025 台南藝術博覽會｜暮拉多元藝術空間｜展間625', 'ART TAINAN 2025 台南藝術博覽會 ｜展間625｜暮拉多元藝術空間\r\n\r\n「迴聲之形 Retentir」\r\n\r\n2025年，暮拉多元藝術空間以「迴聲之形」作為於 2025 台南藝術博覽會 的策展主題，其構想概念源自於哲學家尤金．閔可夫斯基 (Eugene Minkowski) 的「迴盪 (retentir)」一詞，用來描述一種以身體與自然作為介質，如同知覺意念的波長之延伸，如同聲響般的擴張所體現出的共鳴。\r\n\r\n細膩地感受音韻所產生的力道與塑形，期待透過六位涵括繪畫、水墨、版畫、陶瓷、活脫乾漆，於不同材質創作表現的藝術家們，以文化思考、角色隱喻、社群景觀，引領觀眾感受對世界探尋的自由精神與未知想像。\r\n\r\n\r\n—\r\nART TAINAN 2025 台南藝術博覽會 \r\n暮拉多元藝術空間｜Booth 625\r\n\r\n▌藝術家\r\n夏愛華　HSIA, Ai-Hua\r\n黃椿元　HUANG, Chun-Yuan\r\n王亮尹　WANG, Liang-Yin\r\n陳于文　CHEN, Yu-Wun\r\n蔡佳宏　TSAI, Jia-Hong\r\n高安柏　KAO, An-Bo\r\n\r\n▌展期\r\nVIP Preview\r\n2025.03.13 Thu. 15:00-19:00\r\n\r\nPublic Days\r\n2025.03.14 Fri. 12:00-19:00\r\n2025.03.15 Sat. 12:00-19:00\r\n2025.03.16 Sun. 12:00-18:00\r\n\r\n▌地點\r\n台南晶英酒店\r\n台南市中西區和意路1號\r\n', '社團法人中華民國畫廊協會', '臺南市中西區和意路1號', '2025-03-13 00:00:00', '2025-03-16 00:00:00', 'ART TAINAN 2025 台南藝術博覽會 ｜展間625｜暮拉多元藝術空間', 22.99594458, 120.192874, '無資料', 'https://2025.art-taipei.com/tainan/tw/ticket/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 台南藝術博覽會｜暮拉多元藝術空間｜展間625', `description`='ART TAINAN 2025 台南藝術博覽會 ｜展間625｜暮拉多元藝術空間\r\n\r\n「迴聲之形 Retentir」\r\n\r\n2025年，暮拉多元藝術空間以「迴聲之形」作為於 2025 台南藝術博覽會 的策展主題，其構想概念源自於哲學家尤金．閔可夫斯基 (Eugene Minkowski) 的「迴盪 (retentir)」一詞，用來描述一種以身體與自然作為介質，如同知覺意念的波長之延伸，如同聲響般的擴張所體現出的共鳴。\r\n\r\n細膩地感受音韻所產生的力道與塑形，期待透過六位涵括繪畫、水墨、版畫、陶瓷、活脫乾漆，於不同材質創作表現的藝術家們，以文化思考、角色隱喻、社群景觀，引領觀眾感受對世界探尋的自由精神與未知想像。\r\n\r\n\r\n—\r\nART TAINAN 2025 台南藝術博覽會 \r\n暮拉多元藝術空間｜Booth 625\r\n\r\n▌藝術家\r\n夏愛華　HSIA, Ai-Hua\r\n黃椿元　HUANG, Chun-Yuan\r\n王亮尹　WANG, Liang-Yin\r\n陳于文　CHEN, Yu-Wun\r\n蔡佳宏　TSAI, Jia-Hong\r\n高安柏　KAO, An-Bo\r\n\r\n▌展期\r\nVIP Preview\r\n2025.03.13 Thu. 15:00-19:00\r\n\r\nPublic Days\r\n2025.03.14 Fri. 12:00-19:00\r\n2025.03.15 Sat. 12:00-19:00\r\n2025.03.16 Sun. 12:00-18:00\r\n\r\n▌地點\r\n台南晶英酒店\r\n台南市中西區和意路1號\r\n', `organizer`='社團法人中華民國畫廊協會', `address`='臺南市中西區和意路1號', `start_date`='2025-03-13 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='ART TAINAN 2025 台南藝術博覽會 ｜展間625｜暮拉多元藝術空間', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='https://2025.art-taipei.com/tainan/tw/ticket/', `image_url`='[]';
