INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5b8526b32408680bea7c', 'Fun  心聽故事(林園分館114年04月)', '由高雄市立圖書館所培訓一群義務及熱情的故事志工伙伴，\r\n透過豐富的肢體語言及生動活潑表情演出，\r\n每週六將帶來不同驚喜、有趣、感人動聽的故事，\r\n不僅為小朋友們說故事、更帶領小朋友們與家長間的親子互動與閱讀推廣，\r\n享受親子間的閱讀樂趣。\r\n每週六上午10點-11點，將在林園分館 1F 兒童閱覽室演出，每場將有意想不到的精采故事，邀請喜愛聽故事的大朋友、小朋友們，一同大手牽小手，相約到林園分館聽故事唷~', '高雄市立圖書館總館', '高雄市林園區林園北路236號', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '高雄市立圖書館林園分館', 22.5075991, 120.3949167, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Fun  心聽故事(林園分館114年04月)', `description`='由高雄市立圖書館所培訓一群義務及熱情的故事志工伙伴，\r\n透過豐富的肢體語言及生動活潑表情演出，\r\n每週六將帶來不同驚喜、有趣、感人動聽的故事，\r\n不僅為小朋友們說故事、更帶領小朋友們與家長間的親子互動與閱讀推廣，\r\n享受親子間的閱讀樂趣。\r\n每週六上午10點-11點，將在林園分館 1F 兒童閱覽室演出，每場將有意想不到的精采故事，邀請喜愛聽故事的大朋友、小朋友們，一同大手牽小手，相約到林園分館聽故事唷~', `organizer`='高雄市立圖書館總館', `address`='高雄市林園區林園北路236號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄市立圖書館林園分館', `latitude`=22.5075991, `longitude`=120.3949167, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5b8726b32408680bea7d', '頂天綠地~一刀一流陳聰個展', '/頂天綠地/\r\n在天地之間，有無垠的天空，亦有寬廣的大地。\r\n以一刀一流的筆觸，創作者刻劃出峽谷與山巒，也描摹星辰與海洋的壯麗。這創作如同自然本身，無邊無際，流動著屬於創作者的詩意與永恆。\r\n這場藝術的流動，將於淡水河畔與觀音山相融。自然的靈魂與心靈的回應，化為創作者陳聰的全新篇章。顏料在畫布上的律動，宛若大地得起伏，每一抹色彩的交融，如光與影的共舞，彷彿在時間中流轉生息。\r\n頂天綠地/是一次創作者對自然的深情對話\r\n沒有刻意線條，沒有預設的呈現，讓顏料隨著水的氣息自由流動，塑造出這片土地律動與生命的節奏。一幅幅作品如同峽谷經過千萬年的雕琢，又如河流的波光無聲閃爍，傳遞著對大地的深情與天空的無盡想像。\r\n這是一首自然的詩篇，也是一則關於生命的寓言。每一位觀賞者，都將以自己的視角讀懂陳聰的創作，感受易燃的力量與內心的微光。\r\n期許這場展覽將玩畫學笑的精神延展至台灣的每一寸土地。誠摯邀請您，共同見證這場流動於天地之間的藝術饗宴。\r\n\r\n開幕儀式日期:2025/01/18(六)\r\n時間:14:30\r\n開幕地點:滬尾藝文休閒園區 將捷金鬱金香酒店 望高樓\r\n展出地點:滬尾藝文休閒園區 滬尾故事館\r\n\r\n', '滬尾藝文休閒園區', '新北市淡水區中正路一段2號', '2025-01-18 00:00:00', '2025-03-18 00:00:00', '滬尾藝文休閒園區', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='頂天綠地~一刀一流陳聰個展', `description`='/頂天綠地/\r\n在天地之間，有無垠的天空，亦有寬廣的大地。\r\n以一刀一流的筆觸，創作者刻劃出峽谷與山巒，也描摹星辰與海洋的壯麗。這創作如同自然本身，無邊無際，流動著屬於創作者的詩意與永恆。\r\n這場藝術的流動，將於淡水河畔與觀音山相融。自然的靈魂與心靈的回應，化為創作者陳聰的全新篇章。顏料在畫布上的律動，宛若大地得起伏，每一抹色彩的交融，如光與影的共舞，彷彿在時間中流轉生息。\r\n頂天綠地/是一次創作者對自然的深情對話\r\n沒有刻意線條，沒有預設的呈現，讓顏料隨著水的氣息自由流動，塑造出這片土地律動與生命的節奏。一幅幅作品如同峽谷經過千萬年的雕琢，又如河流的波光無聲閃爍，傳遞著對大地的深情與天空的無盡想像。\r\n這是一首自然的詩篇，也是一則關於生命的寓言。每一位觀賞者，都將以自己的視角讀懂陳聰的創作，感受易燃的力量與內心的微光。\r\n期許這場展覽將玩畫學笑的精神延展至台灣的每一寸土地。誠摯邀請您，共同見證這場流動於天地之間的藝術饗宴。\r\n\r\n開幕儀式日期:2025/01/18(六)\r\n時間:14:30\r\n開幕地點:滬尾藝文休閒園區 將捷金鬱金香酒店 望高樓\r\n展出地點:滬尾藝文休閒園區 滬尾故事館\r\n\r\n', `organizer`='滬尾藝文休閒園區', `address`='新北市淡水區中正路一段2號', `start_date`='2025-01-18 00:00:00', `end_date`='2025-03-18 00:00:00', `location`='滬尾藝文休閒園區', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5b8726b32408680bea7e', '【新北市立圖書館永和保生分館】3月萬花盛世主題書展', '在林野鄉間搖曳生姿的花草，只要掌握方式，就能移植到家中或工作場所中，綠化身處的環境，並且讓人時時有花可賞。也可藉由此次書展讓親子一起玩玩土、澆澆水，就能輕鬆打造小花園，讓陽臺、客、書桌變得更美麗。', '新北市立圖書館總館', '新北市永和區新生路218號5、6樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館永和保生分館', 25.00810199, 121.516745, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館永和保生分館】3月萬花盛世主題書展', `description`='在林野鄉間搖曳生姿的花草，只要掌握方式，就能移植到家中或工作場所中，綠化身處的環境，並且讓人時時有花可賞。也可藉由此次書展讓親子一起玩玩土、澆澆水，就能輕鬆打造小花園，讓陽臺、客、書桌變得更美麗。', `organizer`='新北市立圖書館總館', `address`='新北市永和區新生路218號5、6樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館永和保生分館', `latitude`=25.00810199, `longitude`=121.516745, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
