INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5b8e26b32408680bea81', '【新北市立圖書館八里分館】114年3月書展', '114/3/1-3/31　五樓書展：文藝油畫\r\n你知道3/25是臺灣「美術節」嗎？而這天和臺灣畫家陳澄波密切相關。就讓我們透過本月書展，好好認識這位卓越的本土畫家，知曉他對於臺灣藝術文化上的成就與貢獻。', '新北市立圖書館總館', '新北市八里區舊城路19號5、6樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館八里分館', 25.13812763, 121.4138359, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館八里分館】114年3月書展', `description`='114/3/1-3/31　五樓書展：文藝油畫\r\n你知道3/25是臺灣「美術節」嗎？而這天和臺灣畫家陳澄波密切相關。就讓我們透過本月書展，好好認識這位卓越的本土畫家，知曉他對於臺灣藝術文化上的成就與貢獻。', `organizer`='新北市立圖書館總館', `address`='新北市八里區舊城路19號5、6樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館八里分館', `latitude`=25.13812763, `longitude`=121.4138359, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5b9126b32408680bea82', '桃園光影文化館【光聚影像】女兒的女兒 Daughter''s Daughter ［普］', '《女兒的女兒》\r\n2024年上映的台灣劇情片\r\n邁入人生下半場的金艾霞，除了固定探訪回台養老的母親，就是擔心倔強小女兒范祖兒的未來，偶爾也會問候在紐約的大女兒Emma，生活過得休閒愜意。卻沒想到這樣的日子，卻因為一場意外打亂了節奏... 面對難解的親情抉擇，台北與紐約，過去與未來，母親與女兒，能否重新開啟一段承諾？\r\n', '桃園市政府文化局', '桃園市桃園區埔新路12號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '桃園光影文化館', 25.00040024, 121.2996612, '無資料', 'https://kktix.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園光影文化館【光聚影像】女兒的女兒 Daughter''s Daughter ［普］', `description`='《女兒的女兒》\r\n2024年上映的台灣劇情片\r\n邁入人生下半場的金艾霞，除了固定探訪回台養老的母親，就是擔心倔強小女兒范祖兒的未來，偶爾也會問候在紐約的大女兒Emma，生活過得休閒愜意。卻沒想到這樣的日子，卻因為一場意外打亂了節奏... 面對難解的親情抉擇，台北與紐約，過去與未來，母親與女兒，能否重新開啟一段承諾？\r\n', `organizer`='桃園市政府文化局', `address`='桃園市桃園區埔新路12號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='桃園光影文化館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='https://kktix.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5b9126b32408680bea83', '桃園光影文化館【光聚影像】飛月情海 Fly Me to the Moon［普］', '《飛月情海》（英語：Fly Me to the Moon）\r\n2024年美國浪漫喜劇劇情片\r\n白宮找上她負責行銷太空總署 NASA 的登月任務，當她必須與帥氣但過於正直的火箭發射總監柯爾攜手合作，行銷腦對上工程腦，看得上眼還是相看兩厭?登月任務不能失敗，凱莉決定設計一場假造登月計劃，賭上她的愛情與事業...。', '桃園市政府文化局', '桃園市桃園區埔新路12號', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '桃園光影文化館', 25.00040024, 121.2996612, '無資料', 'https://kktix.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園光影文化館【光聚影像】飛月情海 Fly Me to the Moon［普］', `description`='《飛月情海》（英語：Fly Me to the Moon）\r\n2024年美國浪漫喜劇劇情片\r\n白宮找上她負責行銷太空總署 NASA 的登月任務，當她必須與帥氣但過於正直的火箭發射總監柯爾攜手合作，行銷腦對上工程腦，看得上眼還是相看兩厭?登月任務不能失敗，凱莉決定設計一場假造登月計劃，賭上她的愛情與事業...。', `organizer`='桃園市政府文化局', `address`='桃園市桃園區埔新路12號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='桃園光影文化館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='https://kktix.com/', `image_url`='[]';
