INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5b9326b32408680bea85', '大師講座：教你用AI創作出自己的客家歌', '#大師開講 #共創講座\r\n🎼AI創作曲培力坊\r\n邀請到曾入圍金曲獎客語男歌手-曾仲瑋蒞臨，教你用AI創作出自己的客家歌。\r\n◆課程內容\r\n第一場-認識ChatGPT、歌詞創作理念、認識SunoAI-AI編曲製作。\r\n第二場-音樂演唱教學、人聲錄製、混音製作。\r\n◆報名資訊\r\n喜歡音樂的夥伴們都可以參加喔！', '桃園市政府客家事務局', '桃園市八德區崁頂路60號', '2025-03-08 00:00:00', '2025-03-15 00:00:00', '桃園北區客家會館', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大師講座：教你用AI創作出自己的客家歌', `description`='#大師開講 #共創講座\r\n🎼AI創作曲培力坊\r\n邀請到曾入圍金曲獎客語男歌手-曾仲瑋蒞臨，教你用AI創作出自己的客家歌。\r\n◆課程內容\r\n第一場-認識ChatGPT、歌詞創作理念、認識SunoAI-AI編曲製作。\r\n第二場-音樂演唱教學、人聲錄製、混音製作。\r\n◆報名資訊\r\n喜歡音樂的夥伴們都可以參加喔！', `organizer`='桃園市政府客家事務局', `address`='桃園市八德區崁頂路60號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='桃園北區客家會館', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
