INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5b9e26b32408680bea88', '職男人生2-搞笑重啟 (3場)', '面白大丈夫劇團的表演為現場喜劇演出，表演方式主要為漫才以及短劇兩種。漫才類似傳統相聲，以更加輕快的節奏及平易近人的生活題材，更能讓觀眾產生共鳴及歡笑。\r\n', '面白大丈夫劇團', '桃園市中壢區中美路16號', '2025-03-07 00:00:00', '2025-03-08 00:00:00', '中壢藝術館', 24.958126, 121.227384, '票價+600;票價+800;票價+1000;票價+1200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='職男人生2-搞笑重啟 (3場)', `description`='面白大丈夫劇團的表演為現場喜劇演出，表演方式主要為漫才以及短劇兩種。漫才類似傳統相聲，以更加輕快的節奏及平易近人的生活題材，更能讓觀眾產生共鳴及歡笑。\r\n', `organizer`='面白大丈夫劇團', `address`='桃園市中壢區中美路16號', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='中壢藝術館', `latitude`=24.958126, `longitude`=121.227384, `ticket_price`='票價+600;票價+800;票價+1000;票價+1200', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba026b32408680bea89', '「藝遊春風」經典藝術創作聯展 「Art in Spring Breeze」Joint Exhibition', '「藝遊春風」經典展—十一位藝術家的內在風景\r\n\r\n春節過後，萬物甦醒，國璽藝術推出「藝遊春風」經典聯展，策展十一位藝術家以油畫與立體雕塑，呈現內化後的風景創作。他們不僅描繪眼前的自然風光，更在藝術語彙中揉合記憶、情感與思考，勾勒出現實與心靈共鳴的景象。\r\n\r\n油彩流動間，春風輕拂；雕塑起伏中，大地律動。本展覽透過多維度的視覺語言，引領觀者走入藝術家心中之境，感受春意不僅存在於外在世界，更在內心深處綻放。\r\n\r\n展覽地點｜國璽藝術\r\n誠邀您一同在初春之季遊歷藝術，尋覓屬於自己的風景。\r\n\r\nArt in Spring Breeze: A Classic Exhibition – The Inner Landscapes of Eleven Artists\r\n\r\nAs the Spring Festival passes and nature awakens, GSA Gallery presents Art in Spring Breeze: A Classic Exhibition. This showcase brings together ten artists who express their inner landscapes through oil painting and sculpture. Beyond capturing the beauty of nature, they weave memory, emotion, and contemplation into their artistic language, creating a dialogue between reality and the soul.\r\n\r\nWith flowing brushstrokes, the spring breeze whispers; through sculptural forms, the earth pulses with rhythm. This exhibition unfolds a multi-dimensional visual experience, inviting viewers to step into the artists’ inner worlds, where art exists not only in the external landscape but also in the depths of the heart.\r\n\r\nExhibition Venue | GSA Gallery\r\nWe warmly invite you to embark on this artistic journey in early spring and discover a landscape of your own.\r\n\r\n\r\n', '國璽藝術', '臺中市南屯區', '2025-02-22 00:00:00', '2025-04-30 00:00:00', '南屯區（臺中市）=', 24.14165524, 120.6177379, '無資料', 'https://pse.is/75v2xz', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「藝遊春風」經典藝術創作聯展 「Art in Spring Breeze」Joint Exhibition', `description`='「藝遊春風」經典展—十一位藝術家的內在風景\r\n\r\n春節過後，萬物甦醒，國璽藝術推出「藝遊春風」經典聯展，策展十一位藝術家以油畫與立體雕塑，呈現內化後的風景創作。他們不僅描繪眼前的自然風光，更在藝術語彙中揉合記憶、情感與思考，勾勒出現實與心靈共鳴的景象。\r\n\r\n油彩流動間，春風輕拂；雕塑起伏中，大地律動。本展覽透過多維度的視覺語言，引領觀者走入藝術家心中之境，感受春意不僅存在於外在世界，更在內心深處綻放。\r\n\r\n展覽地點｜國璽藝術\r\n誠邀您一同在初春之季遊歷藝術，尋覓屬於自己的風景。\r\n\r\nArt in Spring Breeze: A Classic Exhibition – The Inner Landscapes of Eleven Artists\r\n\r\nAs the Spring Festival passes and nature awakens, GSA Gallery presents Art in Spring Breeze: A Classic Exhibition. This showcase brings together ten artists who express their inner landscapes through oil painting and sculpture. Beyond capturing the beauty of nature, they weave memory, emotion, and contemplation into their artistic language, creating a dialogue between reality and the soul.\r\n\r\nWith flowing brushstrokes, the spring breeze whispers; through sculptural forms, the earth pulses with rhythm. This exhibition unfolds a multi-dimensional visual experience, inviting viewers to step into the artists’ inner worlds, where art exists not only in the external landscape but also in the depths of the heart.\r\n\r\nExhibition Venue | GSA Gallery\r\nWe warmly invite you to embark on this artistic journey in early spring and discover a landscape of your own.\r\n\r\n\r\n', `organizer`='國璽藝術', `address`='臺中市南屯區', `start_date`='2025-02-22 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://pse.is/75v2xz', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba126b32408680bea8a', ' 月圓珍好創意聯想畫展', '人人都是藝術家！2024年裕珍馨文化基金會睽違六年後，在中秋節前夕重新舉辦繪畫比賽，以「中秋月圓，有你真好」創意聯想為題，並首次擴大參賽年齡層。本次裕珍馨大甲三寶文化館共展出七十幅得獎作品，參賽者年齡自六歲至八十七歲，可說是一場跨世代的藝術饗宴，邀請您一同重溫心中最美的中秋場景！\r\n\r\n       本次展覽作品涵蓋各個年齡層，從國小組到社會組，作品裡傳遞著參賽者對中秋節的獨特想像與感受。無論是對月亮的憧憬、家人團聚的溫馨，還是傳統習俗的深思，每一幅畫作都蘊含著豐富的文化內涵與創意巧思，尤其社會組的作品，不僅保有童心趣味，更展現出成熟的創意視角，令人讚嘆。\r\n\r\n       「中秋月圓，有你真好」裕珍馨文化基金會期許透過創意繪畫比賽，讓文化藝術融入日常，達到文化生活化、生活文化的境界，在藝術的世界裡不分族群與世代，人人都能揮灑創意與想像，也同時經由創作來感謝身旁的人事物，發覺生活裡的各種美好。本次展覽不僅適合各方藝術人士參觀，更適合所有喜愛繪畫的小朋友、大朋友，來一同感受每位參賽者創作時的感動。\r\n\r\n展期自114年3月8日至114年4月20日，歡迎蒞臨參觀！', '財團法人裕珍馨文化基金會', '臺中市大甲區光明路67號', '2025-03-08 00:00:00', '2025-04-20 00:00:00', '大甲三寶文化館', 24.37827161, 120.6357901, '無資料', 'https://www.yjs.com.tw/Foundation/Detail/597', '[]') ON DUPLICATE KEY UPDATE `activity_name`=' 月圓珍好創意聯想畫展', `description`='人人都是藝術家！2024年裕珍馨文化基金會睽違六年後，在中秋節前夕重新舉辦繪畫比賽，以「中秋月圓，有你真好」創意聯想為題，並首次擴大參賽年齡層。本次裕珍馨大甲三寶文化館共展出七十幅得獎作品，參賽者年齡自六歲至八十七歲，可說是一場跨世代的藝術饗宴，邀請您一同重溫心中最美的中秋場景！\r\n\r\n       本次展覽作品涵蓋各個年齡層，從國小組到社會組，作品裡傳遞著參賽者對中秋節的獨特想像與感受。無論是對月亮的憧憬、家人團聚的溫馨，還是傳統習俗的深思，每一幅畫作都蘊含著豐富的文化內涵與創意巧思，尤其社會組的作品，不僅保有童心趣味，更展現出成熟的創意視角，令人讚嘆。\r\n\r\n       「中秋月圓，有你真好」裕珍馨文化基金會期許透過創意繪畫比賽，讓文化藝術融入日常，達到文化生活化、生活文化的境界，在藝術的世界裡不分族群與世代，人人都能揮灑創意與想像，也同時經由創作來感謝身旁的人事物，發覺生活裡的各種美好。本次展覽不僅適合各方藝術人士參觀，更適合所有喜愛繪畫的小朋友、大朋友，來一同感受每位參賽者創作時的感動。\r\n\r\n展期自114年3月8日至114年4月20日，歡迎蒞臨參觀！', `organizer`='財團法人裕珍馨文化基金會', `address`='臺中市大甲區光明路67號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='大甲三寶文化館', `latitude`=24.37827161, `longitude`=120.6357901, `ticket_price`='無資料', `source_url`='https://www.yjs.com.tw/Foundation/Detail/597', `image_url`='[]';
