INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba326b32408680bea92', '中壢光影電影館3月主題影展-她說｜地獄新娘 數位修復版 The Bride Who Has Returned from Hell', '03/14 (五) 18:30\r\n地獄新娘 數位修復版 The Bride Who Has Returned from Hell\r\n辛奇｜1965｜臺灣｜劇情｜HD｜118分｜護｜臺語\r\n\r\n★2016國家電影中心數位修復成果\r\n★2019 法國國家電影資料館專題播出\r\n★改編自歌德羅曼史小說《米蘭夫人》、臺語廣播劇《古樓遺恨》\r\n\r\n新加坡華僑白瑞美，返台應聘為王家的家庭教師，卻隱瞞自己是女主人之妹的真實身分，以利潛入調查姊姊的死因。王家接連發生鬧鬼事件，瑞美也意外發現姊姊的日記，逐步逼近命案的真相。王家男主人與瑞美日久生情，論及婚嫁，未料婚禮前夜，兇手出現……坡華僑白瑞美，返台應聘為王家的家庭教師，卻隱瞞自己是女主人之妹的真實身分，以利潛入調查姊姊的死因。王家接連發生鬧鬼事件，瑞美也意外發現姊姊的日記，逐步逼近命案的真相。王家男主人與瑞美日久生情，論及婚嫁，未料婚禮前夜，兇手出現……', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-14 00:00:00', '2025-03-14 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜地獄新娘 數位修復版 The Bride Who Has Returned from Hell', `description`='03/14 (五) 18:30\r\n地獄新娘 數位修復版 The Bride Who Has Returned from Hell\r\n辛奇｜1965｜臺灣｜劇情｜HD｜118分｜護｜臺語\r\n\r\n★2016國家電影中心數位修復成果\r\n★2019 法國國家電影資料館專題播出\r\n★改編自歌德羅曼史小說《米蘭夫人》、臺語廣播劇《古樓遺恨》\r\n\r\n新加坡華僑白瑞美，返台應聘為王家的家庭教師，卻隱瞞自己是女主人之妹的真實身分，以利潛入調查姊姊的死因。王家接連發生鬧鬼事件，瑞美也意外發現姊姊的日記，逐步逼近命案的真相。王家男主人與瑞美日久生情，論及婚嫁，未料婚禮前夜，兇手出現……坡華僑白瑞美，返台應聘為王家的家庭教師，卻隱瞞自己是女主人之妹的真實身分，以利潛入調查姊姊的死因。王家接連發生鬧鬼事件，瑞美也意外發現姊姊的日記，逐步逼近命案的真相。王家男主人與瑞美日久生情，論及婚嫁，未料婚禮前夜，兇手出現……', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-14 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba326b32408680bea93', '中壢光影電影館3月主題影展-她說｜名偵探柯南：漆黑的追跡者 Detective Conan:The Raven Chaser', '03/29 (六) 14:00\r\n名偵探柯南：漆黑的追跡者 Detective Conan:The Raven Chaser\r\n山本泰一郎｜2009｜日本｜動畫｜BD｜111分｜護｜國語\r\n\r\n★《名偵探柯南》劇場版第17部\r\n★日本票房34.9億日元，超越《貝克街的亡靈》，一度高居柯南劇場版系列票房之冠\r\n★2010 日本電影學院最佳動畫優秀賞\r\n\r\n梅雨季剛結束不久，在東京、神奈川、靜岡、長野等地發生了一共6起殺人事件。由於被害者身邊都遺留著神秘的麻將牌，因此被認定為由同一嫌犯或組織所犯下的大範圍連續殺人事件，這引起警政高層的高度重視並召開搜查會議，包括目暮警官、各縣刑警以及毛利小五郎等人都來參加。此時，柯南卻意外發現一名刑警中途離席，而且搭的是黑暗組織成員「琴酒」的車！黑暗組織的成員突然變得異常活躍，香緹與科倫負責妨礙警方的調查，苦艾酒負責追蹤殺人事件的進展。琴酒與伏特加計劃暗殺重要人物，另外還出現一名神秘人物‧愛爾蘭。就在警方調查該事件的同時，與柯南、新一有關的帝丹小學及高中卻遭到不明人士入侵。正當柯南察覺黑暗組織的陰影正朝著自己逼近之際。\r\n七夕之日，在7月7日到來前，第七起殺人事件發生了……', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜名偵探柯南：漆黑的追跡者 Detective Conan:The Raven Chaser', `description`='03/29 (六) 14:00\r\n名偵探柯南：漆黑的追跡者 Detective Conan:The Raven Chaser\r\n山本泰一郎｜2009｜日本｜動畫｜BD｜111分｜護｜國語\r\n\r\n★《名偵探柯南》劇場版第17部\r\n★日本票房34.9億日元，超越《貝克街的亡靈》，一度高居柯南劇場版系列票房之冠\r\n★2010 日本電影學院最佳動畫優秀賞\r\n\r\n梅雨季剛結束不久，在東京、神奈川、靜岡、長野等地發生了一共6起殺人事件。由於被害者身邊都遺留著神秘的麻將牌，因此被認定為由同一嫌犯或組織所犯下的大範圍連續殺人事件，這引起警政高層的高度重視並召開搜查會議，包括目暮警官、各縣刑警以及毛利小五郎等人都來參加。此時，柯南卻意外發現一名刑警中途離席，而且搭的是黑暗組織成員「琴酒」的車！黑暗組織的成員突然變得異常活躍，香緹與科倫負責妨礙警方的調查，苦艾酒負責追蹤殺人事件的進展。琴酒與伏特加計劃暗殺重要人物，另外還出現一名神秘人物‧愛爾蘭。就在警方調查該事件的同時，與柯南、新一有關的帝丹小學及高中卻遭到不明人士入侵。正當柯南察覺黑暗組織的陰影正朝著自己逼近之際。\r\n七夕之日，在7月7日到來前，第七起殺人事件發生了……', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba326b32408680bea94', '中壢光影電影館3月主題影展-她說｜驀然回首 Look Back', '03/22 (六) 14:00\r\n驀然回首 Look Back\r\n押山清高｜2024｜日本｜動畫｜DCP｜58分｜普｜日語\r\n\r\n★2024 報知電影獎最佳動畫、黃金收入獎特別賞\r\n★2025 安妮獎最佳獨立動畫長片入圍\r\n★《鏈鋸人》、《再見繪梨》鬼才漫畫家藤本樹催淚神作登上大銀幕！\r\n\r\n擅長創作四格漫畫的小學生藤野，意外得知長期「家裡蹲」拒絕上學的京本，也跟她一起在校刊上連載四格漫畫。在藤野眼中，京本的畫功遠遠優異於她，讓藤野在自尊心作祟下，將其轉化成自己成長的動力，一路精進畫功到小學六年級，不料還是自認無法超越京本，導致放棄作畫念頭。畢業前夕，藤野在老師的請託下，被交付轉交畢業證書給京本的任務，兩個性格相反的少女，也在此時正式相會，並因為對漫畫的熱愛而結為好友。隨著歲月流逝，有喜有悲，但她們仍在彼此身後，或許回頭就又能夠重逢…。', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜驀然回首 Look Back', `description`='03/22 (六) 14:00\r\n驀然回首 Look Back\r\n押山清高｜2024｜日本｜動畫｜DCP｜58分｜普｜日語\r\n\r\n★2024 報知電影獎最佳動畫、黃金收入獎特別賞\r\n★2025 安妮獎最佳獨立動畫長片入圍\r\n★《鏈鋸人》、《再見繪梨》鬼才漫畫家藤本樹催淚神作登上大銀幕！\r\n\r\n擅長創作四格漫畫的小學生藤野，意外得知長期「家裡蹲」拒絕上學的京本，也跟她一起在校刊上連載四格漫畫。在藤野眼中，京本的畫功遠遠優異於她，讓藤野在自尊心作祟下，將其轉化成自己成長的動力，一路精進畫功到小學六年級，不料還是自認無法超越京本，導致放棄作畫念頭。畢業前夕，藤野在老師的請託下，被交付轉交畢業證書給京本的任務，兩個性格相反的少女，也在此時正式相會，並因為對漫畫的熱愛而結為好友。隨著歲月流逝，有喜有悲，但她們仍在彼此身後，或許回頭就又能夠重逢…。', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680bea95', '中壢光影電影館3月主題影展-她說｜春行 A Journey in Spring + 映後座談', '03/09 (日) 14:00\r\n春行 A Journey in Spring + 映後座談\r\n王品文、彭紫惠｜2024｜臺灣｜劇情｜HD｜89分｜護｜國語、臺語\r\n\r\n★2023 聖賽巴斯提安國際影展最佳導演銀貝殼獎；最佳電影金貝殼獎提名\r\n★2024 金馬獎最佳新導演、最佳男主角入圍\r\n★2024 桃園電影節台灣獎最佳女演員獎\r\n\r\n跛腳男人欽福與妻子秀緞相依為命，住在臺北近郊的老房子裡。妻子秀緞驟然逝世後，欽福隱藏起她已死的事實，繼續過著看似平靜的生活。然而離家多年的兒子與他的新伴侶突然出現，欽福終究必須面對妻子的死亡。帶著對妻子的思念，欽福在潮濕的春季，開始一段面對生命遺憾的旅程。\r\n', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜春行 A Journey in Spring + 映後座談', `description`='03/09 (日) 14:00\r\n春行 A Journey in Spring + 映後座談\r\n王品文、彭紫惠｜2024｜臺灣｜劇情｜HD｜89分｜護｜國語、臺語\r\n\r\n★2023 聖賽巴斯提安國際影展最佳導演銀貝殼獎；最佳電影金貝殼獎提名\r\n★2024 金馬獎最佳新導演、最佳男主角入圍\r\n★2024 桃園電影節台灣獎最佳女演員獎\r\n\r\n跛腳男人欽福與妻子秀緞相依為命，住在臺北近郊的老房子裡。妻子秀緞驟然逝世後，欽福隱藏起她已死的事實，繼續過著看似平靜的生活。然而離家多年的兒子與他的新伴侶突然出現，欽福終究必須面對妻子的死亡。帶著對妻子的思念，欽福在潮濕的春季，開始一段面對生命遺憾的旅程。\r\n', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680bea96', '中壢光影電影館3月主題影展-她說｜感謝上帝 By the Grace of God', '03/09 (日) 18:00\r\n感謝上帝 By the Grace of God\r\n法蘭索瓦歐容｜2018｜法國、比利時｜劇情｜HD｜137分｜護｜法語\r\n\r\n★2019 柏林影展評審團大獎銀熊獎；最佳電影金熊獎提名\r\n★2020 凱薩獎最佳男配角；最佳導演、最佳電影等7項提名\r\n★2020 盧米埃獎最佳電影、最佳男主角等5項提名\r\n\r\n亞歷山大事業有成，家庭美滿，他有深愛他的嬌妻，還是五個小孩的爸爸。\r\n某天，他偶然得知當年曾經性侵他的神父又回到這個教區，他開始害怕有其他的小孩遭受他的魔爪，於是他選擇挺身而出，向社會大眾揭露神父的罪刑，一個接著一個的受害者紛紛加入「不再沉默」協會。但是並非所有受害者都這麼幸運，艾曼努因為幼時遭受性侵，具有暴力傾向，最後成為社會底層的癮君子。來自社會不同階層的他們合力對抗教會這個至高無上的龐大體系。\r\n', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜感謝上帝 By the Grace of God', `description`='03/09 (日) 18:00\r\n感謝上帝 By the Grace of God\r\n法蘭索瓦歐容｜2018｜法國、比利時｜劇情｜HD｜137分｜護｜法語\r\n\r\n★2019 柏林影展評審團大獎銀熊獎；最佳電影金熊獎提名\r\n★2020 凱薩獎最佳男配角；最佳導演、最佳電影等7項提名\r\n★2020 盧米埃獎最佳電影、最佳男主角等5項提名\r\n\r\n亞歷山大事業有成，家庭美滿，他有深愛他的嬌妻，還是五個小孩的爸爸。\r\n某天，他偶然得知當年曾經性侵他的神父又回到這個教區，他開始害怕有其他的小孩遭受他的魔爪，於是他選擇挺身而出，向社會大眾揭露神父的罪刑，一個接著一個的受害者紛紛加入「不再沉默」協會。但是並非所有受害者都這麼幸運，艾曼努因為幼時遭受性侵，具有暴力傾向，最後成為社會底層的癮君子。來自社會不同階層的他們合力對抗教會這個至高無上的龐大體系。\r\n', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680bea97', '中壢光影電影館3月主題影展-她說｜少女的孤島 My Small Land', '03/11 (二) 18:30\r\n少女的孤島 My Small Land\r\n川和田惠真｜2022｜日本、法國｜劇情｜HD｜115分｜護｜日語、土耳其語、庫德語\r\n\r\n★2022 柏林影展國際特赦組織獎特別提及；水晶熊獎新世代單元最佳影片提名\r\n★2023 大阪電影節新晉女演員獎、新晉女導演獎\r\n★2023 日本電影旬報獎最佳新演員、讀者票選年度十大日本電影第10位\r\n\r\n對來到日本的庫德族少女莎雅來說，生活正逐漸好轉，她在學校的成績夠好，足以讓她上大學，周遭也總是有好朋友陪伴，此外，她與聰太也開始培養出特別的關係…然而，因為難民申請沒有通過，莎雅一家的生活跟著遭逢巨變，不僅工作權遭限制也被規定不能離開所居住的埼玉縣。莎雅的爸爸為了維持生計而繼續工作，卻被以非法就業的名義拘留，莎雅現在不僅要照顧年幼弟妹也要開始自力更生…\r\n', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-11 00:00:00', '2025-03-11 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜少女的孤島 My Small Land', `description`='03/11 (二) 18:30\r\n少女的孤島 My Small Land\r\n川和田惠真｜2022｜日本、法國｜劇情｜HD｜115分｜護｜日語、土耳其語、庫德語\r\n\r\n★2022 柏林影展國際特赦組織獎特別提及；水晶熊獎新世代單元最佳影片提名\r\n★2023 大阪電影節新晉女演員獎、新晉女導演獎\r\n★2023 日本電影旬報獎最佳新演員、讀者票選年度十大日本電影第10位\r\n\r\n對來到日本的庫德族少女莎雅來說，生活正逐漸好轉，她在學校的成績夠好，足以讓她上大學，周遭也總是有好朋友陪伴，此外，她與聰太也開始培養出特別的關係…然而，因為難民申請沒有通過，莎雅一家的生活跟著遭逢巨變，不僅工作權遭限制也被規定不能離開所居住的埼玉縣。莎雅的爸爸為了維持生計而繼續工作，卻被以非法就業的名義拘留，莎雅現在不僅要照顧年幼弟妹也要開始自力更生…\r\n', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-11 00:00:00', `end_date`='2025-03-11 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680bea98', '中壢光影電影館3月主題影展-她說｜她他 Make a Wish + 地獄催淚部 Cry Me Through Hell + 映後座談 (二部聯映)', '03/16 (日) 14:00 聯映\r\n她他 Make a Wish\r\n陳可芸｜2019｜臺灣｜劇情｜HD｜25分｜普｜國語\r\n\r\n★2020 金穗獎一般作品類最佳劇情片入圍\r\n★2020 第22屆東京短片影展 亞洲國際競賽\r\n★2020 台灣國際女性影展\r\n\r\n傳說，在七夕的晚上，摺一千顆星星帶到廢墟燒掉，寫在星星裡的願望，就會實現…。一對「友達以上，戀人未滿」的⻘梅竹馬。七夕這晚，女孩為了打破關係決定色誘男孩，卻換來男孩永遠不可能愛上她的答案。看似曖昧不明的青春期賀爾蒙，一個衝動，身體的真相才慢慢流瀉...。\r\n\r\n--\r\n\r\n地獄催淚部 Cry Me Through Hell + 映後座談\r\n楊婕｜2023｜臺灣｜劇情｜HD｜29分｜護｜國語\r\n\r\n★2023 金馬影展\r\n★2024 金穗獎評審團特別獎\r\n★2024 桃園電影節台灣獎最佳女配角獎 \r\n\r\n年邁的吳先生獨自前往櫃台報到登機，卻遲遲等不到忙碌的女兒；女導演對拍片現場百般挑剔，問題不在演技而在過不去的心緒。在班機起飛之際，跨越異地的淚水是否能牽引思念？戲精們同台飆戲，將眼淚催出十八層地獄。\r\n', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜她他 Make a Wish + 地獄催淚部 Cry Me Through Hell + 映後座談 (二部聯映)', `description`='03/16 (日) 14:00 聯映\r\n她他 Make a Wish\r\n陳可芸｜2019｜臺灣｜劇情｜HD｜25分｜普｜國語\r\n\r\n★2020 金穗獎一般作品類最佳劇情片入圍\r\n★2020 第22屆東京短片影展 亞洲國際競賽\r\n★2020 台灣國際女性影展\r\n\r\n傳說，在七夕的晚上，摺一千顆星星帶到廢墟燒掉，寫在星星裡的願望，就會實現…。一對「友達以上，戀人未滿」的⻘梅竹馬。七夕這晚，女孩為了打破關係決定色誘男孩，卻換來男孩永遠不可能愛上她的答案。看似曖昧不明的青春期賀爾蒙，一個衝動，身體的真相才慢慢流瀉...。\r\n\r\n--\r\n\r\n地獄催淚部 Cry Me Through Hell + 映後座談\r\n楊婕｜2023｜臺灣｜劇情｜HD｜29分｜護｜國語\r\n\r\n★2023 金馬影展\r\n★2024 金穗獎評審團特別獎\r\n★2024 桃園電影節台灣獎最佳女配角獎 \r\n\r\n年邁的吳先生獨自前往櫃台報到登機，卻遲遲等不到忙碌的女兒；女導演對拍片現場百般挑剔，問題不在演技而在過不去的心緒。在班機起飛之際，跨越異地的淚水是否能牽引思念？戲精們同台飆戲，將眼淚催出十八層地獄。\r\n', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680bea99', '中壢光影電影館3月主題影展-她說｜金同學的成績單 Kim Min-young of the Report Card', '03/18 (二) 19:00\r\n金同學的成績單 Kim Min-young of the Report Card\r\n李在恩、任志旋｜2021｜韓國｜劇情｜HD｜94分｜普｜韓語\r\n\r\n★2021 韓國全州國際電影節韓國電影競賽單元首獎\r\n★2021 首爾獨立電影節\r\n★2021 首爾國際女性影展\r\n\r\n這是我們的友情成績單。\r\n高中生正希、敏永和珊娜決定結束詩社，專心準備大學入學考試。隔年，她們打算重啟詩社，無奈距離與時差讓她們無法如願。一天，敏永邀請正希到她首爾的公寓做客。正希很高興可以和她的老朋友碰面，然而敏永卻忙著寫電郵給教授，請他修改她的成績，兩人的友情似乎已不如當年…\r\n', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-18 00:00:00', '2025-03-18 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜金同學的成績單 Kim Min-young of the Report Card', `description`='03/18 (二) 19:00\r\n金同學的成績單 Kim Min-young of the Report Card\r\n李在恩、任志旋｜2021｜韓國｜劇情｜HD｜94分｜普｜韓語\r\n\r\n★2021 韓國全州國際電影節韓國電影競賽單元首獎\r\n★2021 首爾獨立電影節\r\n★2021 首爾國際女性影展\r\n\r\n這是我們的友情成績單。\r\n高中生正希、敏永和珊娜決定結束詩社，專心準備大學入學考試。隔年，她們打算重啟詩社，無奈距離與時差讓她們無法如願。一天，敏永邀請正希到她首爾的公寓做客。正希很高興可以和她的老朋友碰面，然而敏永卻忙著寫電郵給教授，請他修改她的成績，兩人的友情似乎已不如當年…\r\n', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-18 00:00:00', `end_date`='2025-03-18 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680bea9a', '中壢光影電影館3月主題影展-她說｜安妮要自由 Angry Annie', '03/21 (五) 18:00\r\n安妮要自由 Angry Annie\r\n布朗蒂妮勒諾瓦｜2022｜法國｜劇情｜DCP｜120分｜護｜法語\r\n\r\n★2022 盧卡諾影展名堂廣場偉大獎\r\n★2022 那慕爾國際法語電影節最佳影片提名\r\n★2022 昂古萊姆法語電影節\r\n\r\n真人真事改編\r\n故事發生在1974年的法國農村，意外懷孕的安妮是名職業婦女，她有兩個正值青年的小孩。她剛好遇上了「提倡墮胎與避孕自由的民間團體MLAC」，該團體的成員與醫生為女性提供免費又安全的墮胎手術，卻被視為非法。漸漸地安妮也開始加入這場解放運動的戰役，而這為她的人生帶來了新的意義。\r\n', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-21 00:00:00', '2025-03-21 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜安妮要自由 Angry Annie', `description`='03/21 (五) 18:00\r\n安妮要自由 Angry Annie\r\n布朗蒂妮勒諾瓦｜2022｜法國｜劇情｜DCP｜120分｜護｜法語\r\n\r\n★2022 盧卡諾影展名堂廣場偉大獎\r\n★2022 那慕爾國際法語電影節最佳影片提名\r\n★2022 昂古萊姆法語電影節\r\n\r\n真人真事改編\r\n故事發生在1974年的法國農村，意外懷孕的安妮是名職業婦女，她有兩個正值青年的小孩。她剛好遇上了「提倡墮胎與避孕自由的民間團體MLAC」，該團體的成員與醫生為女性提供免費又安全的墮胎手術，卻被視為非法。漸漸地安妮也開始加入這場解放運動的戰役，而這為她的人生帶來了新的意義。\r\n', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
