INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680bea9c', '中壢光影電影館3月主題影展-她說｜波紋 Ripples', '03/23 (日) 17:00\r\n波紋 Ripples\r\n荻上直子｜2023｜日本｜劇情｜HD｜121分｜普｜日語\r\n\r\n★2023 釜山國際影展\r\n★2024 日本電影影評人大獎最佳導演、最佳女主角雙料大獎得主\r\n★2024 金馬奇幻影展\r\n\r\n早起、購物、煮飯、餵食，依子一成不變的平凡日常圍繞著丈夫、兒子和公公打轉，直到某日丈夫因恐懼核電輻射一去不復返，公公離世、兒子離家，有了喘息時間的她，全身心投入新興宗教，巧手打理庭院的造景漣漪，只求心靈平靜，然而丈夫與兒子的相繼回歸，卻又將她推向暗黑邊緣。\r\n', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜波紋 Ripples', `description`='03/23 (日) 17:00\r\n波紋 Ripples\r\n荻上直子｜2023｜日本｜劇情｜HD｜121分｜普｜日語\r\n\r\n★2023 釜山國際影展\r\n★2024 日本電影影評人大獎最佳導演、最佳女主角雙料大獎得主\r\n★2024 金馬奇幻影展\r\n\r\n早起、購物、煮飯、餵食，依子一成不變的平凡日常圍繞著丈夫、兒子和公公打轉，直到某日丈夫因恐懼核電輻射一去不復返，公公離世、兒子離家，有了喘息時間的她，全身心投入新興宗教，巧手打理庭院的造景漣漪，只求心靈平靜，然而丈夫與兒子的相繼回歸，卻又將她推向暗黑邊緣。\r\n', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680bea9d', '中壢光影電影館3月主題影展-她說｜進擊的大媽 Woman At War', '03/28 (五) 19:00\r\n進擊的大媽 Woman At War\r\n班尼迪克艾靈森｜2018｜冰島、法國、烏克蘭｜劇情｜DCP｜100分｜護｜冰島語、英語、烏克蘭語、中文、西班牙語\r\n\r\n★2018 坎城影展影評人週單元SACD獎\r\n★2018 德國漢堡影展藝術電影獎\r\n★2018 歐盟光線電影大獎\r\n\r\n50歲的漢拉是名獨立自主的女性，表面上過著平靜而規律的生活，私底下卻是活躍的環保行動人士—居民只聞其名、不知其人的「高地救星」，孤身對抗當地的鋁製業對高地環境的破壞。她的行動日趨大膽，從一開始的小破壞，到後來癱瘓工廠，成功迫使冰島政府暫緩與製鋁公司的協商，阻止新煉鋁廠的興建。就在她準備策畫更大規模的行動時，卻收到打亂一切的通知：她等待多時的領養申請終於通過，一個來自烏克蘭的小女孩正等著跟她回家！為了實現為人母的心願，漢拉決定卸下高地救星的身分，但在那之前，她要再搞一場大破壞，給鋁製業致命一擊！\r\n', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-28 00:00:00', '2025-03-28 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜進擊的大媽 Woman At War', `description`='03/28 (五) 19:00\r\n進擊的大媽 Woman At War\r\n班尼迪克艾靈森｜2018｜冰島、法國、烏克蘭｜劇情｜DCP｜100分｜護｜冰島語、英語、烏克蘭語、中文、西班牙語\r\n\r\n★2018 坎城影展影評人週單元SACD獎\r\n★2018 德國漢堡影展藝術電影獎\r\n★2018 歐盟光線電影大獎\r\n\r\n50歲的漢拉是名獨立自主的女性，表面上過著平靜而規律的生活，私底下卻是活躍的環保行動人士—居民只聞其名、不知其人的「高地救星」，孤身對抗當地的鋁製業對高地環境的破壞。她的行動日趨大膽，從一開始的小破壞，到後來癱瘓工廠，成功迫使冰島政府暫緩與製鋁公司的協商，阻止新煉鋁廠的興建。就在她準備策畫更大規模的行動時，卻收到打亂一切的通知：她等待多時的領養申請終於通過，一個來自烏克蘭的小女孩正等著跟她回家！為了實現為人母的心願，漢拉決定卸下高地救星的身分，但在那之前，她要再搞一場大破壞，給鋁製業致命一擊！\r\n', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
