INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680bea9f', '中壢光影電影館3月主題影展-她說｜莎莉 Salli', '03/30 (日) 14:00\r\n莎莉 Salli\r\n練建宏｜2023｜臺灣｜劇情｜HD｜105分｜護｜國語、臺語、法語、英語\r\n\r\n★2023 第28屆釜山影展亞洲之窗單元入選\r\n★2024 台北電影獎最佳配樂；最佳劇情片、最佳女主角等5項提名\r\n★2024 第19屆大阪亞洲電影節最具潛力創作者獎、ABC TV獎\r\n\r\n超過適婚年齡的女主角林惠君在台中山裡養雞、種玉米，過著簡單愜意的日子，身邊有總擔心自己嫁不出去的姑姑、從上海回來且正值叛逆期的姪女林心茹，還有整天和未婚妻你濃我濃的弟弟林偉宏，看著兩人的甜膩模樣，也讓她心生想談戀愛的念頭。內心渴望愛情卻又怯於表達的她，只能透過交友軟體化名「莎莉」與法國男子馬丁談情說愛，此舉一出不僅弟弟唱酸，全村的人還都說她被騙了，她決定義無反顧飛到巴黎，展開一場屬於自己的追愛之旅！\r\n', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜莎莉 Salli', `description`='03/30 (日) 14:00\r\n莎莉 Salli\r\n練建宏｜2023｜臺灣｜劇情｜HD｜105分｜護｜國語、臺語、法語、英語\r\n\r\n★2023 第28屆釜山影展亞洲之窗單元入選\r\n★2024 台北電影獎最佳配樂；最佳劇情片、最佳女主角等5項提名\r\n★2024 第19屆大阪亞洲電影節最具潛力創作者獎、ABC TV獎\r\n\r\n超過適婚年齡的女主角林惠君在台中山裡養雞、種玉米，過著簡單愜意的日子，身邊有總擔心自己嫁不出去的姑姑、從上海回來且正值叛逆期的姪女林心茹，還有整天和未婚妻你濃我濃的弟弟林偉宏，看著兩人的甜膩模樣，也讓她心生想談戀愛的念頭。內心渴望愛情卻又怯於表達的她，只能透過交友軟體化名「莎莉」與法國男子馬丁談情說愛，此舉一出不僅弟弟唱酸，全村的人還都說她被騙了，她決定義無反顧飛到巴黎，展開一場屬於自己的追愛之旅！\r\n', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680beaa0', '中壢光影電影館3月主題影展-她說｜女影人生 HOMMAGE', '03/30 (日) 17:00\r\n女影人生 HOMMAGE\r\n申秀媛｜2021｜韓國｜劇情｜DCP｜108分｜護｜韓語\r\n\r\n★2022 亞太電影大獎最佳女演員\r\n★2022 佛羅倫斯韓國電影節評審團大獎\r\n★2022 首爾國際女性影展Park Nam-ok獎\r\n\r\n智婉是一位49歲的女導演，在她的第三部電影乏人問津後，是否要繼續拍第四部成了她的難題。在家中，智婉跟丈夫也失和，眼看她經濟陷入困境，丈夫不願再協助她。此時，電影館請智婉幫忙修復一部老電影，該電影是由韓國第一位女導演所拍攝，但影片中某些音檔已損壞，在事業及婚姻都失意的情況下，智婉決定全心投入影片修復工作。為了補回失去的音檔，智婉去拜訪一些60年代的電影工作者，透過與這些前輩的對談，智婉開始以不同的角度看待這世界，她也開始審視自己的人生及電影對她的意義。\r\n', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜女影人生 HOMMAGE', `description`='03/30 (日) 17:00\r\n女影人生 HOMMAGE\r\n申秀媛｜2021｜韓國｜劇情｜DCP｜108分｜護｜韓語\r\n\r\n★2022 亞太電影大獎最佳女演員\r\n★2022 佛羅倫斯韓國電影節評審團大獎\r\n★2022 首爾國際女性影展Park Nam-ok獎\r\n\r\n智婉是一位49歲的女導演，在她的第三部電影乏人問津後，是否要繼續拍第四部成了她的難題。在家中，智婉跟丈夫也失和，眼看她經濟陷入困境，丈夫不願再協助她。此時，電影館請智婉幫忙修復一部老電影，該電影是由韓國第一位女導演所拍攝，但影片中某些音檔已損壞，在事業及婚姻都失意的情況下，智婉決定全心投入影片修復工作。為了補回失去的音檔，智婉去拜訪一些60年代的電影工作者，透過與這些前輩的對談，智婉開始以不同的角度看待這世界，她也開始審視自己的人生及電影對她的意義。\r\n', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680beaa1', '中壢光影電影館3月主題影展-她說｜仙戒奇緣 Cinderella and The Secret Prince', '03/15 (六) 14:00\r\n仙戒奇緣 Cinderella and The Secret Prince\r\n林恩薩瑟蘭｜2018｜美國｜動畫｜DCP｜87分｜普｜國語\r\n\r\n★2019 新竹兒童影展特別選映\r\n★全球票房4億臺幣\r\n★《花木蘭2》導演林恩薩瑟蘭，聯手好萊塢動畫團隊打造顛覆童話\r\n\r\n神仙教母的學徒水晶，幫助仙杜瑞拉與她的三隻老鼠遠離他們居住的閣樓，前往皇宮參加舞會，但他們很快就發現一件可怕的驚人事實：真正的王子被邪惡女巫變成了老鼠，舞會裡眾人眼前的王子是個冒牌貨！仙杜瑞拉與她忠心的朋友決定踏上危險的旅途，協助真正的王子找回身分，並擊敗邪惡勢力。', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜仙戒奇緣 Cinderella and The Secret Prince', `description`='03/15 (六) 14:00\r\n仙戒奇緣 Cinderella and The Secret Prince\r\n林恩薩瑟蘭｜2018｜美國｜動畫｜DCP｜87分｜普｜國語\r\n\r\n★2019 新竹兒童影展特別選映\r\n★全球票房4億臺幣\r\n★《花木蘭2》導演林恩薩瑟蘭，聯手好萊塢動畫團隊打造顛覆童話\r\n\r\n神仙教母的學徒水晶，幫助仙杜瑞拉與她的三隻老鼠遠離他們居住的閣樓，前往皇宮參加舞會，但他們很快就發現一件可怕的驚人事實：真正的王子被邪惡女巫變成了老鼠，舞會裡眾人眼前的王子是個冒牌貨！仙杜瑞拉與她忠心的朋友決定踏上危險的旅途，協助真正的王子找回身分，並擊敗邪惡勢力。', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680beaa2', '中壢光影電影館3月主題影展-她說｜她們 LITTLE WOMEN', '03/16 (日) 17:00\r\n她們 LITTLE WOMEN\r\n葛莉塔潔薇｜2020｜美國｜劇情｜HD｜134分｜普｜英語、法語\r\n\r\n★2020 美國電影學會年度十大電影\r\n★2020 奧斯卡最佳影片、最佳女主角、最佳改編劇本等7項提名\r\n★2020 國家影評人協會最佳導演、最佳女配角\r\n\r\n「我的夢想跟妳的不同，不代表它們就不重要」\r\n電影改編自世界經典名著《小婦人》，並將其原著作者露易莎梅奧爾柯特的真實人生故事，復刻融入至女主角喬馬區（瑟夏羅南飾）的生活中。電影將透過葛莉塔潔薇的視角，重新詮釋馬區家族中，這四位個性截然不同的姊妹；她們將透過自己的信念與理想，活出橫跨時空且不受時代背景限制的生活。\r\n', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜她們 LITTLE WOMEN', `description`='03/16 (日) 17:00\r\n她們 LITTLE WOMEN\r\n葛莉塔潔薇｜2020｜美國｜劇情｜HD｜134分｜普｜英語、法語\r\n\r\n★2020 美國電影學會年度十大電影\r\n★2020 奧斯卡最佳影片、最佳女主角、最佳改編劇本等7項提名\r\n★2020 國家影評人協會最佳導演、最佳女配角\r\n\r\n「我的夢想跟妳的不同，不代表它們就不重要」\r\n電影改編自世界經典名著《小婦人》，並將其原著作者露易莎梅奧爾柯特的真實人生故事，復刻融入至女主角喬馬區（瑟夏羅南飾）的生活中。電影將透過葛莉塔潔薇的視角，重新詮釋馬區家族中，這四位個性截然不同的姊妹；她們將透過自己的信念與理想，活出橫跨時空且不受時代背景限制的生活。\r\n', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680beaa3', '梧棲親子館_台語說故事(114年3月份，4場)', '在多元文化交織的台灣，台語 我們的母語，承載著豐富的歷史文化，在逐漸面臨失傳的危機。\r\n讓孩子學習台語，不僅僅是傳承語言，更能開啟他們探索世界的大門，帶來許多意想不到的益處。\r\n透過台語故事，讓孩子接觸台灣傳統的歌謠、故事和習俗，進而學習台灣人的生活智慧和處世哲學，培養對台灣文化的認同感和歸屬感。學習、感受台語文的獨特魅力!\r\n3/09 洪麗卿老師：動物園\r\n3/15 綠豆媽媽：來𨑨迌\r\n3/16 楊焜顯老師：1.蜈蚣e鞋仔 2.我只撿一個\r\n3/22 連連看阿姨：風吹風吹，佇天頂飛', '臺中市立圖書館梧棲親子館', '臺中市梧棲區民生街15之77號', '2025-03-09 00:00:00', '2025-03-22 00:00:00', '臺中市立圖書館梧棲親子館', 24.251815, 120.533022, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='梧棲親子館_台語說故事(114年3月份，4場)', `description`='在多元文化交織的台灣，台語 我們的母語，承載著豐富的歷史文化，在逐漸面臨失傳的危機。\r\n讓孩子學習台語，不僅僅是傳承語言，更能開啟他們探索世界的大門，帶來許多意想不到的益處。\r\n透過台語故事，讓孩子接觸台灣傳統的歌謠、故事和習俗，進而學習台灣人的生活智慧和處世哲學，培養對台灣文化的認同感和歸屬感。學習、感受台語文的獨特魅力!\r\n3/09 洪麗卿老師：動物園\r\n3/15 綠豆媽媽：來𨑨迌\r\n3/16 楊焜顯老師：1.蜈蚣e鞋仔 2.我只撿一個\r\n3/22 連連看阿姨：風吹風吹，佇天頂飛', `organizer`='臺中市立圖書館梧棲親子館', `address`='臺中市梧棲區民生街15之77號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺中市立圖書館梧棲親子館', `latitude`=24.251815, `longitude`=120.533022, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680beaa4', '英文繪本故事屋_Fun English Stories(114年3月，2場)', '閱讀是一個文化扎根的工作，英文語言能力不僅是一種溝通工具，更是一扇連接全球的窗戶。\r\n而今英語學習更是國民教育的重要一環，為了有效提升全國人民英語能力，親子館邀集英文老師每月挑選一本英文繪本書，以活潑生動的故事，穿插日常生活中常聽到的對話，也藉由一些道具的操作，讓親子更容易進入狀況並加深小朋友的印象。\r\n讓兒童聽故事學英語兼閱讀遊戲，增強孩子詞彙量和識字能力，並培養帶著走的英文素養力。\r\n英文故事繪本書：\r\n3/29 Ayumi姊姊：Magic shoelaces\r\n3/30 Lyvia姊姊：海底世界(中文繪本以英語說故事)', '臺中市立圖書館梧棲親子館', '臺中市梧棲區民生街15之77號', '2025-03-29 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館梧棲親子館', 24.251815, 120.533022, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='英文繪本故事屋_Fun English Stories(114年3月，2場)', `description`='閱讀是一個文化扎根的工作，英文語言能力不僅是一種溝通工具，更是一扇連接全球的窗戶。\r\n而今英語學習更是國民教育的重要一環，為了有效提升全國人民英語能力，親子館邀集英文老師每月挑選一本英文繪本書，以活潑生動的故事，穿插日常生活中常聽到的對話，也藉由一些道具的操作，讓親子更容易進入狀況並加深小朋友的印象。\r\n讓兒童聽故事學英語兼閱讀遊戲，增強孩子詞彙量和識字能力，並培養帶著走的英文素養力。\r\n英文故事繪本書：\r\n3/29 Ayumi姊姊：Magic shoelaces\r\n3/30 Lyvia姊姊：海底世界(中文繪本以英語說故事)', `organizer`='臺中市立圖書館梧棲親子館', `address`='臺中市梧棲區民生街15之77號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館梧棲親子館', `latitude`=24.251815, `longitude`=120.533022, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680beaa5', '中壢光影電影館3月主題影展-她說｜淑女鳥 Lady Bird', '03/23 (日) 14:00\r\n淑女鳥 Lady Bird\r\n葛莉塔潔薇｜2017｜美國｜劇情｜HD｜93分｜輔12｜英語、西班牙語\r\n\r\n★2018 奧斯卡最佳影片、最佳女主角等5項提名\r\n★2018 金球獎最佳音樂及喜劇電影類最佳電影、最佳女主角獎；最佳劇本、最佳女配角提名\r\n★2018 英國電影學院獎最佳女主角、最佳女配角、最佳原創劇本提名\r\n\r\n克莉絲汀娜麥克弗森 (瑟夏羅南 飾) 是一名家境平庸的天主教高中學生。她渴望著各種冒險和機會，甚至特立獨行地幫自己取了Lady Bird(淑女鳥)這個名字。但是在她所生活的加州沙加緬度卻像文化沙漠般令她想趕快逃離。然而就在她高中的最後一年，隨著申請大學的壓力持續飆高，她的生活包括初戀、友誼、和母女關係也開始爆炸性地發展。\r\n', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜淑女鳥 Lady Bird', `description`='03/23 (日) 14:00\r\n淑女鳥 Lady Bird\r\n葛莉塔潔薇｜2017｜美國｜劇情｜HD｜93分｜輔12｜英語、西班牙語\r\n\r\n★2018 奧斯卡最佳影片、最佳女主角等5項提名\r\n★2018 金球獎最佳音樂及喜劇電影類最佳電影、最佳女主角獎；最佳劇本、最佳女配角提名\r\n★2018 英國電影學院獎最佳女主角、最佳女配角、最佳原創劇本提名\r\n\r\n克莉絲汀娜麥克弗森 (瑟夏羅南 飾) 是一名家境平庸的天主教高中學生。她渴望著各種冒險和機會，甚至特立獨行地幫自己取了Lady Bird(淑女鳥)這個名字。但是在她所生活的加州沙加緬度卻像文化沙漠般令她想趕快逃離。然而就在她高中的最後一年，隨著申請大學的壓力持續飆高，她的生活包括初戀、友誼、和母女關係也開始爆炸性地發展。\r\n', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5ba426b32408680beaa6', '中壢光影電影館3月主題影展-她說｜臭鼬小姐 Miss Boots', '03/25 (二) 18:30\r\n臭鼬小姐 Miss Boots \r\n雅恩朗諾特多情｜2024｜加拿大｜劇情｜HD｜111分｜普｜法語\r\n\r\n★2024 德國SCHLiNGEL影展兒童電影類最佳國際劇情片、最佳兒童演員鑽石獎；兒童評審團最佳影片、一般評審團最佳影片等5項提名\r\n★《臭皮匠發財夢》、《星叭克超有種》安托萬貝特朗領銜主演\r\n\r\n菲利普是一位缺乏靈感的歌劇作曲家，他被迫收留他的侄女西蒙娜，一個叛逆、古怪的孤兒，而她的最好的朋友是一隻臭鼬。儘管性格截然相反，菲利普和西蒙娜很快就發現，他們可能比最初想像的更需要彼此。\r\n', '桃園市政府文化局', '桃園市中壢區龍清街116巷31號', '2025-03-25 00:00:00', '2025-03-25 00:00:00', '中壢光影電影館', 24.97993803, 121.2147243, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月主題影展-她說｜臭鼬小姐 Miss Boots', `description`='03/25 (二) 18:30\r\n臭鼬小姐 Miss Boots \r\n雅恩朗諾特多情｜2024｜加拿大｜劇情｜HD｜111分｜普｜法語\r\n\r\n★2024 德國SCHLiNGEL影展兒童電影類最佳國際劇情片、最佳兒童演員鑽石獎；兒童評審團最佳影片、一般評審團最佳影片等5項提名\r\n★《臭皮匠發財夢》、《星叭克超有種》安托萬貝特朗領銜主演\r\n\r\n菲利普是一位缺乏靈感的歌劇作曲家，他被迫收留他的侄女西蒙娜，一個叛逆、古怪的孤兒，而她的最好的朋友是一隻臭鼬。儘管性格截然相反，菲利普和西蒙娜很快就發現，他們可能比最初想像的更需要彼此。\r\n', `organizer`='桃園市政府文化局', `address`='桃園市中壢區龍清街116巷31號', `start_date`='2025-03-25 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='中壢光影電影館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
