INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bad26b32408680beaab', '假日影片欣賞-3月(5場)', '時間:每週六下午14:00-16:00     \r\n地點:2樓嬰幼兒區               \r\n內容:\r\n3/1捍衛聯盟                 \r\n3/8仙戒奇緣                 \r\n3/15美人魚：深海奇緣\r\n3/22熊出沒.伴我~熊芯\r\n3/29神偷奶爸', '臺中市立圖書館梧棲分館', '臺中市梧棲區雲集街72號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '臺中市立圖書館梧棲分館', 24.24552431, 120.5301259, '無資料', 'https://reurl.cc/EgkE31', '[]') ON DUPLICATE KEY UPDATE `activity_name`='假日影片欣賞-3月(5場)', `description`='時間:每週六下午14:00-16:00     \r\n地點:2樓嬰幼兒區               \r\n內容:\r\n3/1捍衛聯盟                 \r\n3/8仙戒奇緣                 \r\n3/15美人魚：深海奇緣\r\n3/22熊出沒.伴我~熊芯\r\n3/29神偷奶爸', `organizer`='臺中市立圖書館梧棲分館', `address`='臺中市梧棲區雲集街72號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市立圖書館梧棲分館', `latitude`=24.24552431, `longitude`=120.5301259, `ticket_price`='無資料', `source_url`='https://reurl.cc/EgkE31', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bad26b32408680beaac', '魔法故事屋-3月(3場)', '時間:周三10:00-11:00           \r\n地點:2樓嬰幼兒區               \r\n內容:                        \r\n3/12【陪你一起等風】                              大意：我的影子說她很孤單，想流浪遠方，可是她不能搭火車，坐飛機也繫不了安全帶，怎麼辦？還有其他辦法嗎？别急！也許風可以幫忙。                      \r\n3/26【好想好想趕快長大】            \r\n大意：學會堅持與耐心，好事就會發生\r\n每個孩子都想知道——我什麼時候會騎腳踏車？要長多高才能打籃球？喜歡的食物為什麼不能馬上吃到？我什麼時候才會長大？\r\n\r\n*2025多元閱讀繽紛季-快樂學母語\r\n3/8(六)咱的日子(我們的日常)\r\n活動內容：由志工說台語繪本～咱的日子(我們的日常)，作者用緩慢的語調，敘述一隻老狗「黑兜」對自己生命的變化、衰老、逝去、死亡，了然於心也自然的接受。讓參與活動的民眾能夠藉由故事了解接受生命的自然老化。而圖文緩緩並進，文字變成了老狗說的話、唱的歌讓我們能感受到老狗「黑兜」對主人滿滿的愛。', '臺中市立圖書館梧棲分館', '臺中市梧棲區雲集街72號', '2025-03-08 00:00:00', '2025-03-26 00:00:00', '臺中市立圖書館梧棲分館', 24.24552431, 120.5301259, '無資料', 'https://reurl.cc/Egx22K', '[]') ON DUPLICATE KEY UPDATE `activity_name`='魔法故事屋-3月(3場)', `description`='時間:周三10:00-11:00           \r\n地點:2樓嬰幼兒區               \r\n內容:                        \r\n3/12【陪你一起等風】                              大意：我的影子說她很孤單，想流浪遠方，可是她不能搭火車，坐飛機也繫不了安全帶，怎麼辦？還有其他辦法嗎？别急！也許風可以幫忙。                      \r\n3/26【好想好想趕快長大】            \r\n大意：學會堅持與耐心，好事就會發生\r\n每個孩子都想知道——我什麼時候會騎腳踏車？要長多高才能打籃球？喜歡的食物為什麼不能馬上吃到？我什麼時候才會長大？\r\n\r\n*2025多元閱讀繽紛季-快樂學母語\r\n3/8(六)咱的日子(我們的日常)\r\n活動內容：由志工說台語繪本～咱的日子(我們的日常)，作者用緩慢的語調，敘述一隻老狗「黑兜」對自己生命的變化、衰老、逝去、死亡，了然於心也自然的接受。讓參與活動的民眾能夠藉由故事了解接受生命的自然老化。而圖文緩緩並進，文字變成了老狗說的話、唱的歌讓我們能感受到老狗「黑兜」對主人滿滿的愛。', `organizer`='臺中市立圖書館梧棲分館', `address`='臺中市梧棲區雲集街72號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺中市立圖書館梧棲分館', `latitude`=24.24552431, `longitude`=120.5301259, `ticket_price`='無資料', `source_url`='https://reurl.cc/Egx22K', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bae26b32408680beaad', '『2025多元閱讀繽紛季書展 -臺語冊．講乎咱聽』書展', '日期:3/1-3/30                          \r\n時間:8:30-21:00                \r\n地點:1樓大廳                   \r\n內容:人類自出生開始，學習用語言對話溝通、建立身分認同，語言伴隨我們走過生命歷程。母語，就是最初學習的語言。因為時代、環境與教育的變化，母語逐漸在生活中弱化，母語的保護與使用已成為重要課題。我們不該遺忘，在文化多元的臺灣，每個族群都擁有自己最美好的語言，就讓我們ㄧ步步走過冷冬，遇見春天，擁抱母語。透過主題書展方式，連結閱讀使民眾親近閱讀，放鬆心靈。', '臺中市立圖書館梧棲分館', '臺中市梧棲區雲集街72號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館梧棲分館', 24.24552431, 120.5301259, '無資料', 'https://reurl.cc/xp5gee', '[]') ON DUPLICATE KEY UPDATE `activity_name`='『2025多元閱讀繽紛季書展 -臺語冊．講乎咱聽』書展', `description`='日期:3/1-3/30                          \r\n時間:8:30-21:00                \r\n地點:1樓大廳                   \r\n內容:人類自出生開始，學習用語言對話溝通、建立身分認同，語言伴隨我們走過生命歷程。母語，就是最初學習的語言。因為時代、環境與教育的變化，母語逐漸在生活中弱化，母語的保護與使用已成為重要課題。我們不該遺忘，在文化多元的臺灣，每個族群都擁有自己最美好的語言，就讓我們ㄧ步步走過冷冬，遇見春天，擁抱母語。透過主題書展方式，連結閱讀使民眾親近閱讀，放鬆心靈。', `organizer`='臺中市立圖書館梧棲分館', `address`='臺中市梧棲區雲集街72號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館梧棲分館', `latitude`=24.24552431, `longitude`=120.5301259, `ticket_price`='無資料', `source_url`='https://reurl.cc/xp5gee', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bae26b32408680beaae', '『做伙來講台語』 書展', '日期:3/17~3/31\r\n時間:8:00~17:30\r\n內容:台語不輪轉沒關係~~來來來~~台語書展~有各式各樣的台語書籍教你說台語，讓我們開開心心的【做伙來講台語】', '臺中市立圖書館梧棲分館', '臺中市梧棲區', '2025-03-17 00:00:00', '2025-03-31 00:00:00', '梧棲區（臺中市）=', 24.24552431, 120.5301259, '無資料', 'https://reurl.cc/yDdn36', '[]') ON DUPLICATE KEY UPDATE `activity_name`='『做伙來講台語』 書展', `description`='日期:3/17~3/31\r\n時間:8:00~17:30\r\n內容:台語不輪轉沒關係~~來來來~~台語書展~有各式各樣的台語書籍教你說台語，讓我們開開心心的【做伙來講台語】', `organizer`='臺中市立圖書館梧棲分館', `address`='臺中市梧棲區', `start_date`='2025-03-17 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='梧棲區（臺中市）=', `latitude`=24.24552431, `longitude`=120.5301259, `ticket_price`='無資料', `source_url`='https://reurl.cc/yDdn36', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bb626b32408680beab2', '兒童巡迴國際書展2025 ', '與禾流一起體驗親子共讀的美好\r\n觸摸香味、音樂書、認知操作、科普知識、立體機關等書籍，一次滿足孩子的閱讀需求。\r\n-\r\n【台中場新書首發】 #全通路都未曝光的新書\r\n🐯動物聲音來比較-我是老虎跟我吼吼叫\r\n▷ 結合「真實動物音效」和「動物立體頁」\r\n收錄五種動物：老虎 / 猴子 / 河馬 / 鸚鵡 / 大象\r\n聽覺視覺大大滿足～快來現場看看誰最大聲👂\r\n【強打新書＆熱銷再版獲獎繪本】\r\n🤤大白熊\r\n美味 / 白白 / 麵包 / 肉肉\r\n▷ 幽默故事呈現48種誘人食物，激發孩子的好奇心與食慾。\r\n🦕恐龍博士的心情小教室\r\n好心情 / 壞心情\r\n▷ 兒童的情緒及感受實用手冊。撰寫10種緩和心情的小撇步，用漫畫的方式帶領孩子認識心情。\r\n🦁大吼大叫的獅子國王 ( 熱銷再版 )\r\n▷ 建立良好的人際關係對於學齡前的孩童是相當重要的生活課題！\r\n☑ 人際互動表達善意\r\n☑ 學會同理心\r\n☑ 包容每個人的不同\r\n☑ 友善的一起交朋友', '禾流文創', '臺中市后里區寺山路41號', '2025-03-14 00:00:00', '2025-03-16 00:00:00', '后里馬場', 24.30962483, 120.7146127, '全票+199', 'https://www.facebook.com/share/p/166RtDpE7z/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='兒童巡迴國際書展2025 ', `description`='與禾流一起體驗親子共讀的美好\r\n觸摸香味、音樂書、認知操作、科普知識、立體機關等書籍，一次滿足孩子的閱讀需求。\r\n-\r\n【台中場新書首發】 #全通路都未曝光的新書\r\n🐯動物聲音來比較-我是老虎跟我吼吼叫\r\n▷ 結合「真實動物音效」和「動物立體頁」\r\n收錄五種動物：老虎 / 猴子 / 河馬 / 鸚鵡 / 大象\r\n聽覺視覺大大滿足～快來現場看看誰最大聲👂\r\n【強打新書＆熱銷再版獲獎繪本】\r\n🤤大白熊\r\n美味 / 白白 / 麵包 / 肉肉\r\n▷ 幽默故事呈現48種誘人食物，激發孩子的好奇心與食慾。\r\n🦕恐龍博士的心情小教室\r\n好心情 / 壞心情\r\n▷ 兒童的情緒及感受實用手冊。撰寫10種緩和心情的小撇步，用漫畫的方式帶領孩子認識心情。\r\n🦁大吼大叫的獅子國王 ( 熱銷再版 )\r\n▷ 建立良好的人際關係對於學齡前的孩童是相當重要的生活課題！\r\n☑ 人際互動表達善意\r\n☑ 學會同理心\r\n☑ 包容每個人的不同\r\n☑ 友善的一起交朋友', `organizer`='禾流文創', `address`='臺中市后里區寺山路41號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='后里馬場', `latitude`=24.30962483, `longitude`=120.7146127, `ticket_price`='全票+199', `source_url`='https://www.facebook.com/share/p/166RtDpE7z/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bb626b32408680beab4', '同術異形~臺中市立長億高中國中部美術班第十六屆畢業展', '長億高中國中部美術班，位於臺中巿太平區的頭汴坑溪旁，環境優美，校園廣闊，是一所培養優質卓越學生的優質國高中。自建校1991年8月即將邁入第16個年頭，長億高中的教育願景「健康活力創新，精緻人文品德」，本校以多元化的方式積極提升教育品質，培育優秀人才，亦積極融入雙語教育。\r\n學校近年打造齊備的硬體空間、擁有新穎專業的美術專科教室，更充實膠彩、水墨、中西繪畫、書法、平面設計等專業師資。自一百零六學年度起，和豐原高中美術班、台中一中美術班策略結盟，用紮實、創新、前瞻的態度，讓學生擁有獨立研究與發表的創見。\r\n此外，美術班更培養學生以紮實的基礎技法與藝術史概念，設計出創意的課程內容，鼓勵學生獨立研究與發表，藉由不斷的探索與對話，摸索出個人獨特的創作方向與風格。\r\n本屆畢展主題為{同術異形}，源自於人生來赤裸的概念，自己的顏色是藉由後天與環境形成。同樣的術法，藉由不同的人都能生出不同的色彩，藝術亦是同理；每個人都有自己的「藝」和「術」，形不同，神韻亦不同；以此作為本次展覽的主題。', '無資料', '臺中市太平區大興路201號', '2025-03-01 00:00:00', '2025-03-23 00:00:00', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', 'https://www.ttdac.taichung.gov.tw/nb5454056579564634112/nbArticleContent', '[]') ON DUPLICATE KEY UPDATE `activity_name`='同術異形~臺中市立長億高中國中部美術班第十六屆畢業展', `description`='長億高中國中部美術班，位於臺中巿太平區的頭汴坑溪旁，環境優美，校園廣闊，是一所培養優質卓越學生的優質國高中。自建校1991年8月即將邁入第16個年頭，長億高中的教育願景「健康活力創新，精緻人文品德」，本校以多元化的方式積極提升教育品質，培育優秀人才，亦積極融入雙語教育。\r\n學校近年打造齊備的硬體空間、擁有新穎專業的美術專科教室，更充實膠彩、水墨、中西繪畫、書法、平面設計等專業師資。自一百零六學年度起，和豐原高中美術班、台中一中美術班策略結盟，用紮實、創新、前瞻的態度，讓學生擁有獨立研究與發表的創見。\r\n此外，美術班更培養學生以紮實的基礎技法與藝術史概念，設計出創意的課程內容，鼓勵學生獨立研究與發表，藉由不斷的探索與對話，摸索出個人獨特的創作方向與風格。\r\n本屆畢展主題為{同術異形}，源自於人生來赤裸的概念，自己的顏色是藉由後天與環境形成。同樣的術法，藉由不同的人都能生出不同的色彩，藝術亦是同理；每個人都有自己的「藝」和「術」，形不同，神韻亦不同；以此作為本次展覽的主題。', `organizer`='無資料', `address`='臺中市太平區大興路201號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='https://www.ttdac.taichung.gov.tw/nb5454056579564634112/nbArticleContent', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bb726b32408680beab5', '春來草自生~羅翠真油畫展', '不管朔風多麼凜冽，冰雪如何厚重地覆蓋大地，當春陽\r\n輕輕撫過，冰雪終將消融，草木自然且欣然接受大地召喚而探出頭擁抱新生，這是自然的韌性，是一種不動聲色的堅強，是白居易「野火燒不盡 春風吹又生」的旺盛生命力。\r\n這次展覽的主題是「春來草自生」，即是源於這種自然哲理與我對生命的體悟。俯仰人世，無論經歷多麼艱難的困境，如同寒冬般漫長而無情，只要內心存有希望與熱忱，便能在春天到來時迎來自己的新生。繪畫是視覺語言，在創作上我以訴說「現實所隱藏的美」為職志，藉由鮮亮的色彩、撲朔迷離的光影、剛柔的筆觸彩繪出當下的時光或一段記憶。不論是街景、人物、風景、鄉間ㄧ隅、城市ㄧ瞥⋯皆以草木生長隱喻人生境遇與力量，來表達內心深處那份安靜而有力的信念，使作品流露美、善、清朗、和諧與光明的氛圍，期待以這份感動與觀賞者進行溝通、交流，進而達到心領神會的共鳴，共享心靈的舒放與喜悅。\r\n「所謂春天，就是即使鞋子灌滿了泥巴，仍然想吹口哨」。我之於繪畫正是這樣的心情，縱使遭遇瓶頸也能在苦澀中咀嚼出甘美的人。梵谷說：「讓我沿著自己的路奮鬥吧！不要失去勇氣，不要鬆懈」，我無法斷捨離於繪畫，它豐富了我的心靈，璀璨了我的人生旅程。不離不棄，是唯一抉擇。', '無資料', '臺中市太平區大興路201號', '2025-03-15 00:00:00', '2025-04-06 00:00:00', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', 'https://www.ttdac.taichung.gov.tw/nb5355402210621059292/nbArticleContent', '[]') ON DUPLICATE KEY UPDATE `activity_name`='春來草自生~羅翠真油畫展', `description`='不管朔風多麼凜冽，冰雪如何厚重地覆蓋大地，當春陽\r\n輕輕撫過，冰雪終將消融，草木自然且欣然接受大地召喚而探出頭擁抱新生，這是自然的韌性，是一種不動聲色的堅強，是白居易「野火燒不盡 春風吹又生」的旺盛生命力。\r\n這次展覽的主題是「春來草自生」，即是源於這種自然哲理與我對生命的體悟。俯仰人世，無論經歷多麼艱難的困境，如同寒冬般漫長而無情，只要內心存有希望與熱忱，便能在春天到來時迎來自己的新生。繪畫是視覺語言，在創作上我以訴說「現實所隱藏的美」為職志，藉由鮮亮的色彩、撲朔迷離的光影、剛柔的筆觸彩繪出當下的時光或一段記憶。不論是街景、人物、風景、鄉間ㄧ隅、城市ㄧ瞥⋯皆以草木生長隱喻人生境遇與力量，來表達內心深處那份安靜而有力的信念，使作品流露美、善、清朗、和諧與光明的氛圍，期待以這份感動與觀賞者進行溝通、交流，進而達到心領神會的共鳴，共享心靈的舒放與喜悅。\r\n「所謂春天，就是即使鞋子灌滿了泥巴，仍然想吹口哨」。我之於繪畫正是這樣的心情，縱使遭遇瓶頸也能在苦澀中咀嚼出甘美的人。梵谷說：「讓我沿著自己的路奮鬥吧！不要失去勇氣，不要鬆懈」，我無法斷捨離於繪畫，它豐富了我的心靈，璀璨了我的人生旅程。不離不棄，是唯一抉擇。', `organizer`='無資料', `address`='臺中市太平區大興路201號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='https://www.ttdac.taichung.gov.tw/nb5355402210621059292/nbArticleContent', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bb726b32408680beab6', '童年回藝~2025 年大元國小第十四屆美術班畢業美展暨聯合展覽', '許多孩子在幼年時期,都喜歡隨手拿起筆到處塗鴉,因為畫圖是一件讓人感到非常開心的事情。但隨著年紀增長,大部分的人失去對於畫圖的熱情,大元國小美術班的孩子卻不一樣喔!在大元國小四年的美術教育薰陶下,孩子的熱情不減!他們用畫筆揮灑出一幅幅生動的作品,台灣山林裡瀕危的小精靈再現於畫布中,孩子也嘗試使用各種藝術表現方式,以生活點滴為主題來進行創作,例如:利用紙箱板變成一道道美味早餐、用廢棄物打造成一棟棟臺灣特色火車站模型...等,而這些作品都將成為屬於他們的童年回藝。\r\n\r\n大元國小美術班成立於民國97年,歷年來學生的藝術學習表現相當亮眼。我們提供每一位孩子藝術探索、體驗學習的空間,著重在「創意」、「愛與關懷」、「美學」的能力發展,從藝術欣賞的培養與藝術創作興趣的激發,使其擁有自己獨特與豐富多元的學習歷程與成就。', '臺中市屯區藝文中心', '臺中市太平區大興路201號', '2025-03-22 00:00:00', '2025-04-13 00:00:00', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', 'https://www.ttdac.taichung.gov.tw/nb5223341336949911809/nbArticleContent', '[]') ON DUPLICATE KEY UPDATE `activity_name`='童年回藝~2025 年大元國小第十四屆美術班畢業美展暨聯合展覽', `description`='許多孩子在幼年時期,都喜歡隨手拿起筆到處塗鴉,因為畫圖是一件讓人感到非常開心的事情。但隨著年紀增長,大部分的人失去對於畫圖的熱情,大元國小美術班的孩子卻不一樣喔!在大元國小四年的美術教育薰陶下,孩子的熱情不減!他們用畫筆揮灑出一幅幅生動的作品,台灣山林裡瀕危的小精靈再現於畫布中,孩子也嘗試使用各種藝術表現方式,以生活點滴為主題來進行創作,例如:利用紙箱板變成一道道美味早餐、用廢棄物打造成一棟棟臺灣特色火車站模型...等,而這些作品都將成為屬於他們的童年回藝。\r\n\r\n大元國小美術班成立於民國97年,歷年來學生的藝術學習表現相當亮眼。我們提供每一位孩子藝術探索、體驗學習的空間,著重在「創意」、「愛與關懷」、「美學」的能力發展,從藝術欣賞的培養與藝術創作興趣的激發,使其擁有自己獨特與豐富多元的學習歷程與成就。', `organizer`='臺中市屯區藝文中心', `address`='臺中市太平區大興路201號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='https://www.ttdac.taichung.gov.tw/nb5223341336949911809/nbArticleContent', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bb726b32408680beab7', '台中市華藝女子畫會2025年會員聯展', '台中市華藝女子畫會成立於西元2008年，是中部地區唯一的女性菁英藝術家組成的畫會，現有海內外80餘位藝術家，共同追求水墨藝術之美，連年辦理會員聯展，備受各界肯定。\r\n此次展出題材涵蓋山水、花鳥、人物，筆法上有工筆、寫意，風格上不拘傳統及現代，是一次豐富多元的繪畫饗宴，歡迎對水墨、書畫藝術有興趣的民眾前來參觀。', '無資料', '臺中市太平區大興路201號', '2025-03-29 00:00:00', '2025-04-20 00:00:00', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', 'https://www.ttdac.taichung.gov.tw/nb4822827010685310917/nbArticleContent', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台中市華藝女子畫會2025年會員聯展', `description`='台中市華藝女子畫會成立於西元2008年，是中部地區唯一的女性菁英藝術家組成的畫會，現有海內外80餘位藝術家，共同追求水墨藝術之美，連年辦理會員聯展，備受各界肯定。\r\n此次展出題材涵蓋山水、花鳥、人物，筆法上有工筆、寫意，風格上不拘傳統及現代，是一次豐富多元的繪畫饗宴，歡迎對水墨、書畫藝術有興趣的民眾前來參觀。', `organizer`='無資料', `address`='臺中市太平區大興路201號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='https://www.ttdac.taichung.gov.tw/nb4822827010685310917/nbArticleContent', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bb826b32408680beab9', '114年文化在巷子裡音樂會-南港區玉成里', 'TSO社區音樂會「文化就在巷子裡」\r\n將美好音樂饗宴帶到鄰里之間，提升社區藝術品質、讓民眾在住家附近更輕易的欣賞到優質的音樂演出，豐富市民文化內涵，一直是TSO努力目標。\r\n近年來TSO「文化就在巷子裡」音樂會投入更多人力及物力，強化演出內容，希望藉由悅耳的音樂帶給市民愉悅的心情，也用淺顯易懂的說明讓民眾得到更多基本音樂常識、提昇全民文化底蘊。\r\n演出曲目：\r\n莫札特：小夜曲，作品編號525，第一樂章\r\n莫札特：小夜曲，作品編號525，第三樂章\r\n蕭士塔高維契：第二號圓舞曲\r\n阿布瑞尤：蜂鳥\r\n皮耶佐拉：自由探戈\r\n瑤族舞曲\r\n李哲音：月夜愁、天黑黑\r\n陳哲聖：台北的天空\r\n李哲藝：廟埕\r\n安可-李哲藝：蘭陽舞曲\r\n兒歌大會串：滿山春色、流水年華.....等\r\n', '臺北市立交響樂團', '臺北市內湖區', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '南港區（臺北市）=', 25.08370623, 121.5923828, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年文化在巷子裡音樂會-南港區玉成里', `description`='TSO社區音樂會「文化就在巷子裡」\r\n將美好音樂饗宴帶到鄰里之間，提升社區藝術品質、讓民眾在住家附近更輕易的欣賞到優質的音樂演出，豐富市民文化內涵，一直是TSO努力目標。\r\n近年來TSO「文化就在巷子裡」音樂會投入更多人力及物力，強化演出內容，希望藉由悅耳的音樂帶給市民愉悅的心情，也用淺顯易懂的說明讓民眾得到更多基本音樂常識、提昇全民文化底蘊。\r\n演出曲目：\r\n莫札特：小夜曲，作品編號525，第一樂章\r\n莫札特：小夜曲，作品編號525，第三樂章\r\n蕭士塔高維契：第二號圓舞曲\r\n阿布瑞尤：蜂鳥\r\n皮耶佐拉：自由探戈\r\n瑤族舞曲\r\n李哲音：月夜愁、天黑黑\r\n陳哲聖：台北的天空\r\n李哲藝：廟埕\r\n安可-李哲藝：蘭陽舞曲\r\n兒歌大會串：滿山春色、流水年華.....等\r\n', `organizer`='臺北市立交響樂團', `address`='臺北市內湖區', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='南港區（臺北市）=', `latitude`=25.08370623, `longitude`=121.5923828, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
