INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bba26b32408680beac9', '「全民拉二胡」巡迴展會式活動-桃園場', '推廣二胡樂器，結合專業指導老師分享領奏、現場樂器整理維修保養、樂器廠商二胡部品展示體驗與廣招各地二胡琴友現場交流為主軸，目標將二胡相關藝文活動傳播至全台各角落，讓樂音飄揚全台。\r\n10:40-11:10 逸軒流行二胡音樂會 \r\n11:40-12:10 爪哥音樂廳/由爪哥老師帶來大家耳熟能詳的經典歌曲，體會二胡細膩豐富的情感詮釋。 \r\n12:30-13:30 休息時間\r\n13:30-14:30 活動名稱：二胡煥新·美學重生 \r\n主講者：謝沛諺（孔振平琴廠認證二胡維護技師）、 \r\n現場演示：二胡外觀從舊到新的精美蛻變過程。 \r\n15:30-16:00 全民合奏趣 \r\n五塊老師帶領現場琴友一同演奏，現場發譜。 \r\n16:00-17:00琴友自由交流\r\n', '金爍爍企業社', '桃園市桃園區', '2025-03-09 00:00:00', '2025-03-09 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「全民拉二胡」巡迴展會式活動-桃園場', `description`='推廣二胡樂器，結合專業指導老師分享領奏、現場樂器整理維修保養、樂器廠商二胡部品展示體驗與廣招各地二胡琴友現場交流為主軸，目標將二胡相關藝文活動傳播至全台各角落，讓樂音飄揚全台。\r\n10:40-11:10 逸軒流行二胡音樂會 \r\n11:40-12:10 爪哥音樂廳/由爪哥老師帶來大家耳熟能詳的經典歌曲，體會二胡細膩豐富的情感詮釋。 \r\n12:30-13:30 休息時間\r\n13:30-14:30 活動名稱：二胡煥新·美學重生 \r\n主講者：謝沛諺（孔振平琴廠認證二胡維護技師）、 \r\n現場演示：二胡外觀從舊到新的精美蛻變過程。 \r\n15:30-16:00 全民合奏趣 \r\n五塊老師帶領現場琴友一同演奏，現場發譜。 \r\n16:00-17:00琴友自由交流\r\n', `organizer`='金爍爍企業社', `address`='桃園市桃園區', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbb26b32408680beaca', '兒童美術館3月說故事活動', '兒童美術館的故事志工，在每個禮拜日及每月兩天的週三為小朋友們帶來精采的故事時間。小朋友們在半小時的活動內，不僅有故事聽、有帶動跳，有時更有簡易手作，讓大家能帶回可愛的紀念品！\r\n\r\n週三胖叔叔說故事：每月一天，第一場10點、第二場11點，為時半小時；\r\n週三阿姨說故事：每月一天，10點30分，為時半小時；\r\n週日說故事：每週日10點30分，為時半小時。', '高雄市立美術館', '高雄市鼓山區馬卡道路330號', '2025-03-02 00:00:00', '2025-03-30 00:00:00', '高雄兒童美術館', 22.6578576, 120.2828147, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='兒童美術館3月說故事活動', `description`='兒童美術館的故事志工，在每個禮拜日及每月兩天的週三為小朋友們帶來精采的故事時間。小朋友們在半小時的活動內，不僅有故事聽、有帶動跳，有時更有簡易手作，讓大家能帶回可愛的紀念品！\r\n\r\n週三胖叔叔說故事：每月一天，第一場10點、第二場11點，為時半小時；\r\n週三阿姨說故事：每月一天，10點30分，為時半小時；\r\n週日說故事：每週日10點30分，為時半小時。', `organizer`='高雄市立美術館', `address`='高雄市鼓山區馬卡道路330號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄兒童美術館', `latitude`=22.6578576, `longitude`=120.2828147, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbc26b32408680bead2', 'FUN心聽故事 (小港分館四月)', '由高雄市立圖書館所培訓的一群義務故事志工，透過豐富的肢體語言與生動有大象不跳趣的互動方式，為小朋友說故事，現場並擺設相關書籍展示，歡迎大家踴躍參加。', '高雄市立圖書館總館', '高雄市小港區博學路365號', '2025-04-05 00:00:00', '2025-04-27 00:00:00', '高雄市立圖書館小港分館', 22.5605891, 120.3705758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽故事 (小港分館四月)', `description`='由高雄市立圖書館所培訓的一群義務故事志工，透過豐富的肢體語言與生動有大象不跳趣的互動方式，為小朋友說故事，現場並擺設相關書籍展示，歡迎大家踴躍參加。', `organizer`='高雄市立圖書館總館', `address`='高雄市小港區博學路365號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='高雄市立圖書館小港分館', `latitude`=22.5605891, `longitude`=120.3705758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbc26b32408680bead3', '「Xin chào！越南」主題書展', 'Xin chào的意思是你好，也是一場相遇的開始，透過書展認識不一樣的越南! 從旅遊探險、文化歷史、語言學習到文學經典，每本書都藏著越南的故事，用不同角度探索這個迷人的國度，無論是想計畫一場旅行、學幾句越南話，或是單純被這個美麗的國家吸引，都歡迎翻翻書，一起用閱讀開啟與越南的美好相遇!藉由書展，提升館藏借閱率。\r\n\r\n本次展示書：\r\n一本搞定，生活越南語脫口說\r\n開始在越南自助旅行\r\n越南旅繪手帖：深入走訪5大城市，體驗美食x建築x生活\r\n越南心適代：越南歷史文化解密\r\n越南美食史：米飯與長棍麵包\r\n越南語，越說越上口！\r\n越南啟示錄\r\n越南：世界史的失語者\r\n用中文說越南語\r\n西貢淪陷：美國在越南的最後時刻\r\n......等書籍', '高雄市立圖書館總館', '高雄市美濃區6鄰中正路一段59號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館美濃分館', 22.9001672, 120.5418427, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「Xin chào！越南」主題書展', `description`='Xin chào的意思是你好，也是一場相遇的開始，透過書展認識不一樣的越南! 從旅遊探險、文化歷史、語言學習到文學經典，每本書都藏著越南的故事，用不同角度探索這個迷人的國度，無論是想計畫一場旅行、學幾句越南話，或是單純被這個美麗的國家吸引，都歡迎翻翻書，一起用閱讀開啟與越南的美好相遇!藉由書展，提升館藏借閱率。\r\n\r\n本次展示書：\r\n一本搞定，生活越南語脫口說\r\n開始在越南自助旅行\r\n越南旅繪手帖：深入走訪5大城市，體驗美食x建築x生活\r\n越南心適代：越南歷史文化解密\r\n越南美食史：米飯與長棍麵包\r\n越南語，越說越上口！\r\n越南啟示錄\r\n越南：世界史的失語者\r\n用中文說越南語\r\n西貢淪陷：美國在越南的最後時刻\r\n......等書籍', `organizer`='高雄市立圖書館總館', `address`='高雄市美濃區6鄰中正路一段59號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館美濃分館', `latitude`=22.9001672, `longitude`=120.5418427, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbc26b32408680bead4', '麗麗食品', '「Lili Deli 麗麗食品」歷經一年籌備，即將在美術館開張，這間運進數十噸紙磚作為台座的「店舖」，不含熟悉的添加物和化學調料，捨棄便宜的美耐皿、塑膠食器和耐用不銹鋼，取而代之的是易鏽不穩的黑鐵桌、日漸氧化的銅製魚骨、風乾豆莢和貝類、裸裝裱的攝影、易(已)碎的玻璃、回收鐵罐、隨時會消失的點餐單和難以保存的包裝材。藝術家選擇使用非傳統、有機的物料，將消費行為的剩料細心組裝成各式樣的雕塑裝置，反應現代人追求廉價和效率，方便與實用至上的時代切面，和我們一起在集體無意識的湧流中前行。 \r\n\r\n展覽特別推出「The Tower of Freebies 廢比塔計劃」，邀請觀眾攜帶家中的陳年贈品，共同在現場堆砌出華麗塔樓。為過往刺激消費而造成的剩餘，創造一個重返光榮的舞台。', '臺北市立美術館', '臺北市中山區中山北路3段181號', '2025-03-29 00:00:00', '2025-06-22 00:00:00', '臺北市立美術館', 25.06969917, 121.5381597, '全票+30;優待票+15', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='麗麗食品', `description`='「Lili Deli 麗麗食品」歷經一年籌備，即將在美術館開張，這間運進數十噸紙磚作為台座的「店舖」，不含熟悉的添加物和化學調料，捨棄便宜的美耐皿、塑膠食器和耐用不銹鋼，取而代之的是易鏽不穩的黑鐵桌、日漸氧化的銅製魚骨、風乾豆莢和貝類、裸裝裱的攝影、易(已)碎的玻璃、回收鐵罐、隨時會消失的點餐單和難以保存的包裝材。藝術家選擇使用非傳統、有機的物料，將消費行為的剩料細心組裝成各式樣的雕塑裝置，反應現代人追求廉價和效率，方便與實用至上的時代切面，和我們一起在集體無意識的湧流中前行。 \r\n\r\n展覽特別推出「The Tower of Freebies 廢比塔計劃」，邀請觀眾攜帶家中的陳年贈品，共同在現場堆砌出華麗塔樓。為過往刺激消費而造成的剩餘，創造一個重返光榮的舞台。', `organizer`='臺北市立美術館', `address`='臺北市中山區中山北路3段181號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-06-22 00:00:00', `location`='臺北市立美術館', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='全票+30;優待票+15', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbc26b32408680bead5', '2025傳統戲曲縣內巡迴演出－陳麗香歌仔戲團《楊金盔掛帥》（溪湖鎮天元宮）', '15：00～17：00  扮仙酬神\r\n19：00～21：00  演出「楊金盔掛帥」\r\n劇情簡介：\r\n宋朝名將楊家將征戰沙場，至楊宗保後皆代代單傳，為保一點血脈，宋天子同意佘太君「辭朝不辭官」，遠離朝政。左相龐錦福而不暢、意欲篡位,暗中拉攏徐、羅兩將，卻遭拒絕，龐錦反咬二人通敵賣國，宋天子下旨抄家，兩家後代流落金雞山為寇。龐相得知後，請旨命楊金魁掛帥征剿，佘太君知曉龐相計謀一箭雙鵰，故令呼延家後人呼延忠為先鋒同行，並藉錦囊促成曾孫陣前招親。\r\n誰料龐相再次弄權，誣指佘太君有謀反之心，宋天子怒斬佘太君，幸楊金魁四人校場救下，並將龐相惡行與謀反證據面呈天子，忠臣良將得以洗刷冤情，喜成良配。', '彰化縣文化局', '彰化縣溪湖鎮', '2025-03-14 00:00:00', '2025-03-14 00:00:00', '溪湖鎮（彰化縣）=', 23.95171456, 120.4831739, '無資料', 'https://www.facebook.com/Chen.Li.Xiang.048330415/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025傳統戲曲縣內巡迴演出－陳麗香歌仔戲團《楊金盔掛帥》（溪湖鎮天元宮）', `description`='15：00～17：00  扮仙酬神\r\n19：00～21：00  演出「楊金盔掛帥」\r\n劇情簡介：\r\n宋朝名將楊家將征戰沙場，至楊宗保後皆代代單傳，為保一點血脈，宋天子同意佘太君「辭朝不辭官」，遠離朝政。左相龐錦福而不暢、意欲篡位,暗中拉攏徐、羅兩將，卻遭拒絕，龐錦反咬二人通敵賣國，宋天子下旨抄家，兩家後代流落金雞山為寇。龐相得知後，請旨命楊金魁掛帥征剿，佘太君知曉龐相計謀一箭雙鵰，故令呼延家後人呼延忠為先鋒同行，並藉錦囊促成曾孫陣前招親。\r\n誰料龐相再次弄權，誣指佘太君有謀反之心，宋天子怒斬佘太君，幸楊金魁四人校場救下，並將龐相惡行與謀反證據面呈天子，忠臣良將得以洗刷冤情，喜成良配。', `organizer`='彰化縣文化局', `address`='彰化縣溪湖鎮', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-14 00:00:00', `location`='溪湖鎮（彰化縣）=', `latitude`=23.95171456, `longitude`=120.4831739, `ticket_price`='無資料', `source_url`='https://www.facebook.com/Chen.Li.Xiang.048330415/', `image_url`='[]';
