INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbc26b32408680beada', '【弦鍵熾戀】Pablo Ferrández × 左章 大提琴與鋼琴二重奏', '這是一位來自西班牙的寶藏級大提琴藝術家。自2015年榮獲含金量極高的柴可夫斯基國際大賽大提琴獎後，他便嶄露頭角，隨後憑藉華麗的技巧、深刻的音樂表現力與無法抗拒的舞台魅力，征服了全球樂迷。\r\n\r\n巴勃羅・費蘭德斯（Pablo Ferrández） 出生於音樂世家，13歲便進入享譽世界的索菲亞王后高等音樂學院學習。如今34歲的他被《費加羅報》譽為**「天才大提琴家」，而小提琴大師安-索菲・慕特（Anne-Sophie Mutter）** 更是盛讚：「他擁有極為宏亮的音色、精緻的顫音，以及完美無瑕的左右手技藝，他是真正的音樂家。」\r\n\r\n他的演奏如春風拂面，溫暖而動人。無論是與世界頂級樂團合作，還是在國際音樂節的精彩演出，總能讓觀眾沉浸在純粹的音樂之美中。他毫無疑問是當今年輕一代中世界頂尖的大提琴家之一。\r\n\r\n \r\n\r\n她，是當今中國青年鋼琴家中最璀璨的明星之一——迷人、明亮、激情而純粹。\r\n\r\n左章 於1995年拜入中國鋼琴教父但昭義門下學習，並憑藉卓越的音樂才華蜚聲國際。世界著名指揮家帕沃・耶爾維（Paavo Järvi） 曾直言：「她是我遇見過最傑出且最富激情的鋼琴天才之一。」\r\n\r\n闊別多年，2025年，他將再度登上台灣舞台，演奏20世紀最重要的大提琴經典曲目之一——杜替耶《遙遠的世界》。此次更邀請到左章同台飆技，勢必帶來一場驚艷絕倫的音樂對話！', '好滿意音樂有限公司', '臺中市霧峰區中正路738之2號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '國立臺灣交響樂團', 24.04332785, 120.7201989, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【弦鍵熾戀】Pablo Ferrández × 左章 大提琴與鋼琴二重奏', `description`='這是一位來自西班牙的寶藏級大提琴藝術家。自2015年榮獲含金量極高的柴可夫斯基國際大賽大提琴獎後，他便嶄露頭角，隨後憑藉華麗的技巧、深刻的音樂表現力與無法抗拒的舞台魅力，征服了全球樂迷。\r\n\r\n巴勃羅・費蘭德斯（Pablo Ferrández） 出生於音樂世家，13歲便進入享譽世界的索菲亞王后高等音樂學院學習。如今34歲的他被《費加羅報》譽為**「天才大提琴家」，而小提琴大師安-索菲・慕特（Anne-Sophie Mutter）** 更是盛讚：「他擁有極為宏亮的音色、精緻的顫音，以及完美無瑕的左右手技藝，他是真正的音樂家。」\r\n\r\n他的演奏如春風拂面，溫暖而動人。無論是與世界頂級樂團合作，還是在國際音樂節的精彩演出，總能讓觀眾沉浸在純粹的音樂之美中。他毫無疑問是當今年輕一代中世界頂尖的大提琴家之一。\r\n\r\n \r\n\r\n她，是當今中國青年鋼琴家中最璀璨的明星之一——迷人、明亮、激情而純粹。\r\n\r\n左章 於1995年拜入中國鋼琴教父但昭義門下學習，並憑藉卓越的音樂才華蜚聲國際。世界著名指揮家帕沃・耶爾維（Paavo Järvi） 曾直言：「她是我遇見過最傑出且最富激情的鋼琴天才之一。」\r\n\r\n闊別多年，2025年，他將再度登上台灣舞台，演奏20世紀最重要的大提琴經典曲目之一——杜替耶《遙遠的世界》。此次更邀請到左章同台飆技，勢必帶來一場驚艷絕倫的音樂對話！', `organizer`='好滿意音樂有限公司', `address`='臺中市霧峰區中正路738之2號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='國立臺灣交響樂團', `latitude`=24.04332785, `longitude`=120.7201989, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beadd', '114年「文化局故事達人秀」奇幻冒險啟程！小朋友說故事比賽', '今年的主題是「奇幻」，從神秘的魔法王國到未曾發現的深海城市，從會說話的動物到時空穿梭的奇幻旅程……小朋友們可以選擇任何與「奇幻」相關的故事，發揮創造力與表達力，帶領觀眾進入充滿驚喜與奇遇的奇幻世界。', '澎湖縣政府文化局', '澎湖縣馬公市中華路230號', '2025-04-26 00:00:00', '2025-04-27 00:00:00', '澎湖縣政府文化局', 23.55534, 119.59234, '無資料', 'http:www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年「文化局故事達人秀」奇幻冒險啟程！小朋友說故事比賽', `description`='今年的主題是「奇幻」，從神秘的魔法王國到未曾發現的深海城市，從會說話的動物到時空穿梭的奇幻旅程……小朋友們可以選擇任何與「奇幻」相關的故事，發揮創造力與表達力，帶領觀眾進入充滿驚喜與奇遇的奇幻世界。', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路230號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='澎湖縣政府文化局', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http:www.phhcc.gov.tw', `image_url`='[]';
