INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beae0', '名間鄉立圖書館假日電影院（114年3月）', '圖書館每週星期六下午2:00播放影片供大家欣賞，歡迎您全家前來圖書館欣賞影片。活動洽詢：049-2734848\r\n\r\n放映影片：\r\n3月01日-羊子喬\r\n3月08日-黃勁連\r\n3月15日-馬祖容顏\r\n3月22日-節慶在臺灣 從傳統到現在\r\n3月29日-流浪者之歌\r\n\r\n電影級別：\r\n輔導級：未滿十五歲之人不宜觀賞。\r\n保護級：未滿六歲之兒童不宜觀賞，六歲以上未滿十二歲之兒童需父母、陪伴輔導觀賞。\r\n普遍級：一般觀眾皆可觀賞。', '南投縣名間鄉公所', '南投縣名間鄉彰南路42-2號三樓', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '南投縣名間鄉立圖書館', 23.8385841, 120.702733, '無資料', 'https://www.facebook.com/profile.php?id=100064507040051', '[]') ON DUPLICATE KEY UPDATE `activity_name`='名間鄉立圖書館假日電影院（114年3月）', `description`='圖書館每週星期六下午2:00播放影片供大家欣賞，歡迎您全家前來圖書館欣賞影片。活動洽詢：049-2734848\r\n\r\n放映影片：\r\n3月01日-羊子喬\r\n3月08日-黃勁連\r\n3月15日-馬祖容顏\r\n3月22日-節慶在臺灣 從傳統到現在\r\n3月29日-流浪者之歌\r\n\r\n電影級別：\r\n輔導級：未滿十五歲之人不宜觀賞。\r\n保護級：未滿六歲之兒童不宜觀賞，六歲以上未滿十二歲之兒童需父母、陪伴輔導觀賞。\r\n普遍級：一般觀眾皆可觀賞。', `organizer`='南投縣名間鄉公所', `address`='南投縣名間鄉彰南路42-2號三樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='南投縣名間鄉立圖書館', `latitude`=23.8385841, `longitude`=120.702733, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064507040051', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beae1', '2025竹山『小鎮躍動』藝文表演：小花樂團', '每週六「小鎮躍動」由駐唱歌手、樂團、魔術、泡泡秀…等，來自不同團體帶來的各類精彩演出，歡迎鄉親們來菸葉館欣賞表演。\r\n如遇天候不佳，主辦單位有取消活動的權利。', '南投縣竹山鎮公所', '南投縣竹山鎮', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '竹山鎮（南投縣）=', 23.69805518, 120.7100797, '無資料', 'https://www.facebook.com/JhuShan', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025竹山『小鎮躍動』藝文表演：小花樂團', `description`='每週六「小鎮躍動」由駐唱歌手、樂團、魔術、泡泡秀…等，來自不同團體帶來的各類精彩演出，歡迎鄉親們來菸葉館欣賞表演。\r\n如遇天候不佳，主辦單位有取消活動的權利。', `organizer`='南投縣竹山鎮公所', `address`='南投縣竹山鎮', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='竹山鎮（南投縣）=', `latitude`=23.69805518, `longitude`=120.7100797, `ticket_price`='無資料', `source_url`='https://www.facebook.com/JhuShan', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beae2', '114年工藝校園扎根．種子教師培育計畫：藍染教師培力工作坊（3月26日13:00線上報名） ', '為推動工藝融入學校教育，促進工藝美學校園扎根，透過教師增能培力課程，培育學校教師成為種子教師，回到教學現場傳遞工藝的美好，誘發學生工藝學習興趣，開啟工藝與教育融合共好的無限可能性。\r\n本研習透過認識藍草植物、建缸示範以及折縫染、噴繪染、槌染、生葉染色等技法介紹與實作，給予學員系統性的工藝知識，包括：材料、工具、工法及工序等，培養學員對藍染工藝的基本認識及實作技能，進而回到學校發展藍染體驗課程及實踐。\r\n\r\n授課講師：湯文君老師，自然色手作坊負責人。\r\n招生對象：幼兒園、國小、國中及高級中等學校之教師\r\n招生人數：招收 20 人(6 人開班)\r\n報名方式：採網路報名，於 3/26（三）下午 1 點在【全國教師在職進修資訊網】線上報名（課程代碼：4939487）。\r\n錄取方式：為落實工藝校園扎根政策推動所需，主辦單位得保留一半名額供工藝中心培育之種子教師課程實踐者或具有工藝校園扎根潛力者優先錄取（需回填學習動機以及教學實踐成果，俾利審核），其餘名額則依報名優先順序錄取，錄取名單請至【全國教師在職進修資訊網】查詢。', '國立臺灣工藝研究發展中心', '南投縣草屯鎮中正路573號', '2025-04-26 00:00:00', '2025-05-04 00:00:00', '國立臺灣工藝研究發展中心（臺灣工藝文化園區）', 23.9807747, 120.6918567, '學雜費+588;材料費+2200', 'https://www.ntcri.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年工藝校園扎根．種子教師培育計畫：藍染教師培力工作坊（3月26日13:00線上報名） ', `description`='為推動工藝融入學校教育，促進工藝美學校園扎根，透過教師增能培力課程，培育學校教師成為種子教師，回到教學現場傳遞工藝的美好，誘發學生工藝學習興趣，開啟工藝與教育融合共好的無限可能性。\r\n本研習透過認識藍草植物、建缸示範以及折縫染、噴繪染、槌染、生葉染色等技法介紹與實作，給予學員系統性的工藝知識，包括：材料、工具、工法及工序等，培養學員對藍染工藝的基本認識及實作技能，進而回到學校發展藍染體驗課程及實踐。\r\n\r\n授課講師：湯文君老師，自然色手作坊負責人。\r\n招生對象：幼兒園、國小、國中及高級中等學校之教師\r\n招生人數：招收 20 人(6 人開班)\r\n報名方式：採網路報名，於 3/26（三）下午 1 點在【全國教師在職進修資訊網】線上報名（課程代碼：4939487）。\r\n錄取方式：為落實工藝校園扎根政策推動所需，主辦單位得保留一半名額供工藝中心培育之種子教師課程實踐者或具有工藝校園扎根潛力者優先錄取（需回填學習動機以及教學實踐成果，俾利審核），其餘名額則依報名優先順序錄取，錄取名單請至【全國教師在職進修資訊網】查詢。', `organizer`='國立臺灣工藝研究發展中心', `address`='南投縣草屯鎮中正路573號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='國立臺灣工藝研究發展中心（臺灣工藝文化園區）', `latitude`=23.9807747, `longitude`=120.6918567, `ticket_price`='學雜費+588;材料費+2200', `source_url`='https://www.ntcri.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beae3', '化石無價．生命有愛—化石達人王坤愉榮獲全球熱愛生命獎章暨終身奉獻化石特展', '王坤愉老師1984年畢業於台北師專（現今為國立臺北教育大學），就回南投縣中寮故鄉，終身奉獻偏鄉小學教育，而且利用教學之餘分秒必爭，發掘近3千件台灣千萬年化石，是全台發現鸚鵡螺化石岩層的第一人，書寫地球生命史書、見證千萬年生命，搏命尋寶記—贏得「地下三吋」封號，更大公無私將1200件千萬年化石捐贈國立自然科學博物館，推廣自然科學的知識，把台灣千萬年化石的愛，撒播世界每個角落，還立志帶動200多萬憂鬱症者活出希望，不愧為「化石達人」，從全球各界推薦3683位熱愛生命獎章候選人中脫穎而出，榮獲周大觀文教基金會「2025年第28屆全球熱愛生命獎章」。  \r\n\r\n開幕日期：114年3月10（一）上午10時10分', '國立中興高級中學', '南投縣南投市中興新村中學路2號', '2025-03-10 00:00:00', '2025-03-17 00:00:00', '國立中興高級中學', 23.9179739, 120.6774812, '無資料', 'https://ta.org.tw/news.php?lang=zh&idept=0&isdept=0&pk=7222', '[]') ON DUPLICATE KEY UPDATE `activity_name`='化石無價．生命有愛—化石達人王坤愉榮獲全球熱愛生命獎章暨終身奉獻化石特展', `description`='王坤愉老師1984年畢業於台北師專（現今為國立臺北教育大學），就回南投縣中寮故鄉，終身奉獻偏鄉小學教育，而且利用教學之餘分秒必爭，發掘近3千件台灣千萬年化石，是全台發現鸚鵡螺化石岩層的第一人，書寫地球生命史書、見證千萬年生命，搏命尋寶記—贏得「地下三吋」封號，更大公無私將1200件千萬年化石捐贈國立自然科學博物館，推廣自然科學的知識，把台灣千萬年化石的愛，撒播世界每個角落，還立志帶動200多萬憂鬱症者活出希望，不愧為「化石達人」，從全球各界推薦3683位熱愛生命獎章候選人中脫穎而出，榮獲周大觀文教基金會「2025年第28屆全球熱愛生命獎章」。  \r\n\r\n開幕日期：114年3月10（一）上午10時10分', `organizer`='國立中興高級中學', `address`='南投縣南投市中興新村中學路2號', `start_date`='2025-03-10 00:00:00', `end_date`='2025-03-17 00:00:00', `location`='國立中興高級中學', `latitude`=23.9179739, `longitude`=120.6774812, `ticket_price`='無資料', `source_url`='https://ta.org.tw/news.php?lang=zh&idept=0&isdept=0&pk=7222', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beae4', '「捧場：陳冠良畫師與他的佈景彩繪」特展', '佈景畫師陳冠良出生自屏東布袋戲世家，自幼對繪畫產生興趣，其繪畫技巧融合各家所學之精髓，琢磨出自我獨特風格，二十多年來為明華園戲劇團繪製不少戲棚作品，被喻為明華園的御用畫師。本展以一位佈景彩繪工作者的角度，透過「蘊生」、「景幕」、「造像」等輪廓，帶領觀眾入門窺睹戲台佈景的堂奧，希冀人們在汲取戲曲文化新知之餘，也能感受傳統戲台佈景所呈現的獨特美學觀。', '屏東縣政府文化處', '屏東縣潮州鎮建基路58號', '2025-01-01 00:00:00', '2025-06-15 00:00:00', '屏東戲曲故事館', 22.5503224, 120.5431596, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「捧場：陳冠良畫師與他的佈景彩繪」特展', `description`='佈景畫師陳冠良出生自屏東布袋戲世家，自幼對繪畫產生興趣，其繪畫技巧融合各家所學之精髓，琢磨出自我獨特風格，二十多年來為明華園戲劇團繪製不少戲棚作品，被喻為明華園的御用畫師。本展以一位佈景彩繪工作者的角度，透過「蘊生」、「景幕」、「造像」等輪廓，帶領觀眾入門窺睹戲台佈景的堂奧，希冀人們在汲取戲曲文化新知之餘，也能感受傳統戲台佈景所呈現的獨特美學觀。', `organizer`='屏東縣政府文化處', `address`='屏東縣潮州鎮建基路58號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='屏東戲曲故事館', `latitude`=22.5503224, `longitude`=120.5431596, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beae6', '紅鼻子馬戲團《友丸的巡夢大遊行》', '當代馬戲團以人為本，帶來歡樂；馬戲巡遊，夢想無限；打造未曾有過的馬戲花車遊行，而乘載夢想的《巡夢號》即將停靠屏東春風調戲藝術節。\r\n\r\n紅鼻子馬戲團希望讓馬戲的歡樂能夠藉由遊行以貼近地方民眾的方式來進行演出。以由知名遊國際遊樂園的遊行花車做為發想，打造屬於台灣本土IP的馬戲團造型，並創造團隊專屬的可愛吉祥物，安排精靈舞者隨著花車跟觀眾互動耍特技，繽紛歡樂的《巡夢號》緊隨其後，從視覺上琢磨，有別於傳統廟會及燈會的電子花車，讓有趣的事在遊行過程發生。', '屏東縣政府文化處', '屏東縣屏東市殺蛇溪畔（東起縱貫鐵路，西至復興路，南臨和生路，北接台糖街）', '2025-03-07 00:00:00', '2025-03-09 00:00:00', '屏東縣民公園', 22.6647375, 120.4799948, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='紅鼻子馬戲團《友丸的巡夢大遊行》', `description`='當代馬戲團以人為本，帶來歡樂；馬戲巡遊，夢想無限；打造未曾有過的馬戲花車遊行，而乘載夢想的《巡夢號》即將停靠屏東春風調戲藝術節。\r\n\r\n紅鼻子馬戲團希望讓馬戲的歡樂能夠藉由遊行以貼近地方民眾的方式來進行演出。以由知名遊國際遊樂園的遊行花車做為發想，打造屬於台灣本土IP的馬戲團造型，並創造團隊專屬的可愛吉祥物，安排精靈舞者隨著花車跟觀眾互動耍特技，繽紛歡樂的《巡夢號》緊隨其後，從視覺上琢磨，有別於傳統廟會及燈會的電子花車，讓有趣的事在遊行過程發生。', `organizer`='屏東縣政府文化處', `address`='屏東縣屏東市殺蛇溪畔（東起縱貫鐵路，西至復興路，南臨和生路，北接台糖街）', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-09 00:00:00', `location`='屏東縣民公園', `latitude`=22.6647375, `longitude`=120.4799948, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beae7', '黃旭磊笛簫獨奏音樂會', '演奏傳統音樂並加以發想、創新之曲目，節目內容中安排音樂多樣性及本土性，將屬於我們居住與熱愛的這片的土地的聲音和帶回家鄉。\r\n\r\n【演出曲目】\r\n莫凡：《綠洲》 4"00 竹笛與鋼琴\r\n郭文景：《侯方域夢游莫愁湖》竹笛獨奏\r\n陳中申：《馬蘭姑娘》簫與擊樂\r\n洪千惠：《Di-Day》竹笛與鋼琴\r\n張維良：《花泣》竹笛與琵琶\r\n陳中申：《雨夜花開》簫與中阮、揚琴\r\n穆祥來：《深秋敘》竹笛與小樂隊\r\n陸橒：《山·樂》 竹笛與國樂團', '屏東縣政府文化處', '屏東縣屏東市民生路4之17號', '2025-03-08 00:00:00', '2025-03-08 00:00:00', '屏東演藝廳', 22.6647375, 120.4799948, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='黃旭磊笛簫獨奏音樂會', `description`='演奏傳統音樂並加以發想、創新之曲目，節目內容中安排音樂多樣性及本土性，將屬於我們居住與熱愛的這片的土地的聲音和帶回家鄉。\r\n\r\n【演出曲目】\r\n莫凡：《綠洲》 4"00 竹笛與鋼琴\r\n郭文景：《侯方域夢游莫愁湖》竹笛獨奏\r\n陳中申：《馬蘭姑娘》簫與擊樂\r\n洪千惠：《Di-Day》竹笛與鋼琴\r\n張維良：《花泣》竹笛與琵琶\r\n陳中申：《雨夜花開》簫與中阮、揚琴\r\n穆祥來：《深秋敘》竹笛與小樂隊\r\n陸橒：《山·樂》 竹笛與國樂團', `organizer`='屏東縣政府文化處', `address`='屏東縣屏東市民生路4之17號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-08 00:00:00', `location`='屏東演藝廳', `latitude`=22.6647375, `longitude`=120.4799948, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beae8', '2025《消失的密室》管風琴導覽(3月)', '一探管風琴室最深處的心臟，只在屏東𖣐\r\n✦全台第三大管風琴 ✦獨特水平音管設計 ✦在地特色「福爾摩沙笛管」\r\n\r\n精彩內容\r\nꚰ 揭秘管風琴建置、內部結構與發聲原理\r\nꚰ 管風琴老師演出與導聆，展現多層次琴音之美\r\nꚰ 親自體驗管風琴彈奏，感受震撼音效\r\n\r\n主講：謝金相 先生\r\n經歷：任職功學社集團年資共計39年\r\n-功學社貿易公司五福分公司主任\r\n-功學社山葉樂器公司南區營業課長\r\n-功學社音樂中心中南區營業部經理\r\n\r\n管風琴：王安琪老師\r\n高雄市人。1991~1994就讀東吳大學音樂系，主修管風琴，師事陳相瑜老師；副修鋼琴，師事諸大明教授。1994~1999就讀於柏林藝術大學音樂系，主修管風琴，師事Prof. Heinemann；副修大鍵琴，師事Prof. Meyerson。先後取得管風琴藝術家文憑與獨奏家文憑。熱心公益與教會事工。目前全心致力於推廣管風琴音樂。', '屏東縣政府文化處', '屏東縣屏東市民生路4之17號', '2025-03-12 00:00:00', '2025-03-12 00:00:00', '屏東演藝廳', 22.6647375, 120.4799948, '全票+200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025《消失的密室》管風琴導覽(3月)', `description`='一探管風琴室最深處的心臟，只在屏東𖣐\r\n✦全台第三大管風琴 ✦獨特水平音管設計 ✦在地特色「福爾摩沙笛管」\r\n\r\n精彩內容\r\nꚰ 揭秘管風琴建置、內部結構與發聲原理\r\nꚰ 管風琴老師演出與導聆，展現多層次琴音之美\r\nꚰ 親自體驗管風琴彈奏，感受震撼音效\r\n\r\n主講：謝金相 先生\r\n經歷：任職功學社集團年資共計39年\r\n-功學社貿易公司五福分公司主任\r\n-功學社山葉樂器公司南區營業課長\r\n-功學社音樂中心中南區營業部經理\r\n\r\n管風琴：王安琪老師\r\n高雄市人。1991~1994就讀東吳大學音樂系，主修管風琴，師事陳相瑜老師；副修鋼琴，師事諸大明教授。1994~1999就讀於柏林藝術大學音樂系，主修管風琴，師事Prof. Heinemann；副修大鍵琴，師事Prof. Meyerson。先後取得管風琴藝術家文憑與獨奏家文憑。熱心公益與教會事工。目前全心致力於推廣管風琴音樂。', `organizer`='屏東縣政府文化處', `address`='屏東縣屏東市民生路4之17號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-03-12 00:00:00', `location`='屏東演藝廳', `latitude`=22.6647375, `longitude`=120.4799948, `ticket_price`='全票+200', `source_url`='https://www.opentix.life/', `image_url`='[]';
