INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beaf2', '《風琴•繁響》尚•吉優的音樂色彩', '尚•吉優(Jean Guillou)是歐洲最傑出和最受尊敬的管風琴家之一，作品豐富、擅長即興、精湛演奏譽滿全球。他的管風琴作品非常不同，深植於文化、藝術、文學等各方面，並透過他的即興音樂直接表達出來，展示Jean Guillou身為音樂家、管風琴家和作曲家的非凡才華。Jean Guillou是他那個時代的大師，他的音樂與同時代所有法國音樂截然不同，其作品都是創新深刻的原創，代表他在管風琴上獨特敏感的精湛風格。本場獨奏會的選曲皆是Jean Guillou最令人難以忘懷的作品，演奏這些大作品將是一個挑戰；但透過德國管風琴家坤薩瓦教授爐火純青的藝術造詣，屏東演藝廳的管風琴，給了坤薩瓦教授一個豐富光影效果的調色盤，將樂器的音色線條揚起夢幻般的、詩意的、激情的音響果效，讓聽眾捕捉管風琴色彩光芒的美妙動態。Jean Guillou獨特的作品，為聽眾們開拓管風琴聽覺世界的新邊界。\r\n曲目介紹｜Program(皆為尚•吉優作品/ All pieces by Jean Guillou)\r\n1. 作品第9號《觸技曲》 Toccata, op. 9 \r\n2. 作品第26號《阿比姆的夏貝爾》La chapelle des Abîmes, op. 26 \r\n3. 作品第50號《薩亞》Säya ou L'' oiseau bleu, op. 50 \r\n4. 作品第28號《童年情景》Scènes d'' enfants, op. 28 ', '屏東縣政府', '屏東縣屏東市民生路4之17號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '屏東演藝廳', 22.6647375, 120.4799948, '全票+400;全票+600', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《風琴•繁響》尚•吉優的音樂色彩', `description`='尚•吉優(Jean Guillou)是歐洲最傑出和最受尊敬的管風琴家之一，作品豐富、擅長即興、精湛演奏譽滿全球。他的管風琴作品非常不同，深植於文化、藝術、文學等各方面，並透過他的即興音樂直接表達出來，展示Jean Guillou身為音樂家、管風琴家和作曲家的非凡才華。Jean Guillou是他那個時代的大師，他的音樂與同時代所有法國音樂截然不同，其作品都是創新深刻的原創，代表他在管風琴上獨特敏感的精湛風格。本場獨奏會的選曲皆是Jean Guillou最令人難以忘懷的作品，演奏這些大作品將是一個挑戰；但透過德國管風琴家坤薩瓦教授爐火純青的藝術造詣，屏東演藝廳的管風琴，給了坤薩瓦教授一個豐富光影效果的調色盤，將樂器的音色線條揚起夢幻般的、詩意的、激情的音響果效，讓聽眾捕捉管風琴色彩光芒的美妙動態。Jean Guillou獨特的作品，為聽眾們開拓管風琴聽覺世界的新邊界。\r\n曲目介紹｜Program(皆為尚•吉優作品/ All pieces by Jean Guillou)\r\n1. 作品第9號《觸技曲》 Toccata, op. 9 \r\n2. 作品第26號《阿比姆的夏貝爾》La chapelle des Abîmes, op. 26 \r\n3. 作品第50號《薩亞》Säya ou L'' oiseau bleu, op. 50 \r\n4. 作品第28號《童年情景》Scènes d'' enfants, op. 28 ', `organizer`='屏東縣政府', `address`='屏東縣屏東市民生路4之17號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='屏東演藝廳', `latitude`=22.6647375, `longitude`=120.4799948, `ticket_price`='全票+400;全票+600', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beaf3', '2025管風琴─于爾根•坤薩瓦 (Jürgen Kursawa)大師班', '德國管風琴家 于爾根•坤薩瓦 (Jürgen Kursawa) 教授將在屏東演藝廳親自主持管風琴大師班，傳授演奏技巧與音樂詮釋的精髓。\r\n🎼 將與大師面對面交流，汲取寶貴經驗\r\n🎼 深入探討演奏技巧與音樂詮釋\r\n🎼 本次大師班將開放旁聽，讓更多人感受大師風采', '屏東縣政府', '屏東縣屏東市民生路4之17號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '屏東演藝廳', 22.6647375, 120.4799948, '旁聽生 (不限)/次+200;正式生 (6位為上限)/每小時+6000', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025管風琴─于爾根•坤薩瓦 (Jürgen Kursawa)大師班', `description`='德國管風琴家 于爾根•坤薩瓦 (Jürgen Kursawa) 教授將在屏東演藝廳親自主持管風琴大師班，傳授演奏技巧與音樂詮釋的精髓。\r\n🎼 將與大師面對面交流，汲取寶貴經驗\r\n🎼 深入探討演奏技巧與音樂詮釋\r\n🎼 本次大師班將開放旁聽，讓更多人感受大師風采', `organizer`='屏東縣政府', `address`='屏東縣屏東市民生路4之17號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='屏東演藝廳', `latitude`=22.6647375, `longitude`=120.4799948, `ticket_price`='旁聽生 (不限)/次+200;正式生 (6位為上限)/每小時+6000', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beaf4', 'FOCASA馬戲團《潘朵拉的盒子》', '傳說，在很久很久以前，⼀個神奇的森林裡頭，住著許多⾝懷絕技的精靈，聽說他們擁有⼀個神秘的寶藏箱，每次打開時，都會有意想不到的驚喜。有⼀個熱愛冒險跟帥氣的探險家來到這片森林，準備來尋找這個神秘的寶藏箱，讓我們⼀起來進入這片森林⼀起探險吧！\r\n\r\n馬戲就像一座森林ㄧ樣，等著你來探索和冒險，特技、雜耍、舞蹈和⼩丑，都是森林的寶藏。《潘朵拉的盒⼦》的誕⽣是為了讓第一次接觸馬戲的觀眾，和現場的表演者，一起沉浸在愉悅、歡樂、刺激、感動的的氛圍之中，發現⾺戲森林的極致魅力。', '屏東縣政府', '屏東縣屏東市和平路427路', '2025-03-22 00:00:00', '2025-03-23 00:00:00', '屏東藝術館', 22.678594, 120.4777635, '全票+400;全票+600;全票+800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FOCASA馬戲團《潘朵拉的盒子》', `description`='傳說，在很久很久以前，⼀個神奇的森林裡頭，住著許多⾝懷絕技的精靈，聽說他們擁有⼀個神秘的寶藏箱，每次打開時，都會有意想不到的驚喜。有⼀個熱愛冒險跟帥氣的探險家來到這片森林，準備來尋找這個神秘的寶藏箱，讓我們⼀起來進入這片森林⼀起探險吧！\r\n\r\n馬戲就像一座森林ㄧ樣，等著你來探索和冒險，特技、雜耍、舞蹈和⼩丑，都是森林的寶藏。《潘朵拉的盒⼦》的誕⽣是為了讓第一次接觸馬戲的觀眾，和現場的表演者，一起沉浸在愉悅、歡樂、刺激、感動的的氛圍之中，發現⾺戲森林的極致魅力。', `organizer`='屏東縣政府', `address`='屏東縣屏東市和平路427路', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='屏東藝術館', `latitude`=22.678594, `longitude`=120.4777635, `ticket_price`='全票+400;全票+600;全票+800', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beaf5', '真雲林閣掌中劇團《台灣演義—金湖春秋》', '改編自雲林縣口湖鄉口耳相傳的傳說，神奇的萬善爺形象深植人心，但卻鮮少有人知道背後的故事，劇團透過布袋戲的形式，演繹在地故事，讓觀眾尤其是孩子們，可以更加認識臺灣的文化，體會不同的風俗民情。 \r\n此劇將以輕鬆趣味的互動戲劇方式展演出來，搭配活潑的偶戲表演，希望觀眾在看戲之餘，能夠深刻體會劇中的情感，並發揮戲劇寓教於樂的功能。期望在本團的努力下，能讓更多觀眾被布袋戲的演出所打動，進而更加喜愛布袋戲、喜愛傳統戲曲。', '屏東縣政府', '屏東縣屏東市青島街106號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '勝利星村創意生活園區V.I.P Zone', 22.6647375, 120.4799948, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='真雲林閣掌中劇團《台灣演義—金湖春秋》', `description`='改編自雲林縣口湖鄉口耳相傳的傳說，神奇的萬善爺形象深植人心，但卻鮮少有人知道背後的故事，劇團透過布袋戲的形式，演繹在地故事，讓觀眾尤其是孩子們，可以更加認識臺灣的文化，體會不同的風俗民情。 \r\n此劇將以輕鬆趣味的互動戲劇方式展演出來，搭配活潑的偶戲表演，希望觀眾在看戲之餘，能夠深刻體會劇中的情感，並發揮戲劇寓教於樂的功能。期望在本團的努力下，能讓更多觀眾被布袋戲的演出所打動，進而更加喜愛布袋戲、喜愛傳統戲曲。', `organizer`='屏東縣政府', `address`='屏東縣屏東市青島街106號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='勝利星村創意生活園區V.I.P Zone', `latitude`=22.6647375, `longitude`=120.4799948, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
