INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bb126b32408680beab0', '親子讀經班-第27期', '時間:每周日早上09:00-10:30\r\n地點:B1多功能活動室\r\n主旨:\r\n讀誦中、英文經典，不僅可以使兒童從小感受中方與西方的文化精神，同時掌握精粹語言的方法，使其人格健全發展，增進家庭親子和諧，以營造祥和的文化書香社會，開拓文化志業無量發展空間。\r\n讀經的好處：\r\n開發左右腦、正音、識字力、作文力、品格力、專注力、英文力\r\n課程內容:\r\n唐詩、百孝經讀本、中庸、論語、品格故事、英文故事繪本、自然發音法', '無資料', '臺中市梧棲區雲集街72號', '2025-03-01 00:00:00', '2025-07-06 00:00:00', '臺中市立圖書館梧棲分館', 24.24552431, 120.5301259, '無資料', 'https://reurl.cc/M6pQm3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='親子讀經班-第27期', `description`='時間:每周日早上09:00-10:30\r\n地點:B1多功能活動室\r\n主旨:\r\n讀誦中、英文經典，不僅可以使兒童從小感受中方與西方的文化精神，同時掌握精粹語言的方法，使其人格健全發展，增進家庭親子和諧，以營造祥和的文化書香社會，開拓文化志業無量發展空間。\r\n讀經的好處：\r\n開發左右腦、正音、識字力、作文力、品格力、專注力、英文力\r\n課程內容:\r\n唐詩、百孝經讀本、中庸、論語、品格故事、英文故事繪本、自然發音法', `organizer`='無資料', `address`='臺中市梧棲區雲集街72號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-07-06 00:00:00', `location`='臺中市立圖書館梧棲分館', `latitude`=24.24552431, `longitude`=120.5301259, `ticket_price`='無資料', `source_url`='https://reurl.cc/M6pQm3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bb226b32408680beab1', '社區親子讀經班', '時間:每周三晚上19:30-20:30     \r\n地點:B1多功能活動室           \r\n主旨:\r\n1、經由古文薰習造就文化素養，啟發良知、涵養道德。\r\n2、透過親子讀經，增進親子間良好的互動。\r\n3、加強孝思，令孩子由衷感恩與感動，更懂得孝順父母。\r\n4、推動倫理道德，提倡敬老與尊賢。\r\n5、促進家庭和樂，社會安定與和諧。\r\n教學內容:弟子規、唐詩律動、品格教育課程、繪本分享。', '無資料', '臺中市梧棲區雲集街72號', '2025-03-05 00:00:00', '2025-07-30 00:00:00', '臺中市立圖書館梧棲分館', 24.24552431, 120.5301259, '無資料', 'https://reurl.cc/qn7evN', '[]') ON DUPLICATE KEY UPDATE `activity_name`='社區親子讀經班', `description`='時間:每周三晚上19:30-20:30     \r\n地點:B1多功能活動室           \r\n主旨:\r\n1、經由古文薰習造就文化素養，啟發良知、涵養道德。\r\n2、透過親子讀經，增進親子間良好的互動。\r\n3、加強孝思，令孩子由衷感恩與感動，更懂得孝順父母。\r\n4、推動倫理道德，提倡敬老與尊賢。\r\n5、促進家庭和樂，社會安定與和諧。\r\n教學內容:弟子規、唐詩律動、品格教育課程、繪本分享。', `organizer`='無資料', `address`='臺中市梧棲區雲集街72號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-07-30 00:00:00', `location`='臺中市立圖書館梧棲分館', `latitude`=24.24552431, `longitude`=120.5301259, `ticket_price`='無資料', `source_url`='https://reurl.cc/qn7evN', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bb626b32408680beab3', '【交流展】謝棟樑《川流不息》', '藝術家謝棟樑是台灣第一位榮獲全省美展永久免審查資格雕塑名家，現居太平區，作品強調人與人、自然之間的關係和互動。本次交流展作品融合陰陽概念，如空間的虛實變化，質感的粗細感覺，顏色的明暗處理，都是陰陽和諧的體現。本件作品有如觀瀑，即觀賞水瀑由上而下蜿蜒流下之意。', '無資料', '臺中市太平區大興路201號', '2025-03-01 00:00:00', '2025-08-01 00:00:00', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', 'https://www.ttdac.taichung.gov.tw/n35436709707562448388/n3ArticleContent', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【交流展】謝棟樑《川流不息》', `description`='藝術家謝棟樑是台灣第一位榮獲全省美展永久免審查資格雕塑名家，現居太平區，作品強調人與人、自然之間的關係和互動。本次交流展作品融合陰陽概念，如空間的虛實變化，質感的粗細感覺，顏色的明暗處理，都是陰陽和諧的體現。本件作品有如觀瀑，即觀賞水瀑由上而下蜿蜒流下之意。', `organizer`='無資料', `address`='臺中市太平區大興路201號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-08-01 00:00:00', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='https://www.ttdac.taichung.gov.tw/n35436709707562448388/n3ArticleContent', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bba26b32408680beac4', '114年文化在巷子裡音樂會-文山區萬興里', 'TSO社區音樂會「文化就在巷子裡」\r\n將美好音樂饗宴帶到鄰里之間，提升社區藝術品質、讓民眾在住家附近更輕易的欣賞到優質的音樂演出，豐富市民文化內涵，一直是TSO努力目標。\r\n近年來TSO「文化就在巷子裡」音樂會投入更多人力及物力，強化演出內容，希望藉由悅耳的音樂帶給市民愉悅的心情，也用淺顯易懂的說明讓民眾得到更多基本音樂常識、提昇全民文化底蘊。\r\n演出曲目：\r\n莫札特：小夜曲，作品編號525，第一樂章\r\n莫札特：小夜曲，作品編號525，第三樂章\r\n蕭士塔高維契：第二號圓舞曲\r\n阿布瑞尤：蜂鳥\r\n皮耶佐拉：自由探戈\r\n瑤族舞曲\r\n李哲音：月夜愁、天黑黑\r\n陳哲聖：台北的天空\r\n李哲藝：廟埕\r\n安可-李哲藝：蘭陽舞曲\r\n兒歌大會串：滿山春色、流水年華.....等\r\n', '臺北市政府文化局', '臺北市文山區', '2025-08-02 00:00:00', '2025-08-02 00:00:00', '文山區（臺北市）=', 24.98857934, 121.5736082, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年文化在巷子裡音樂會-文山區萬興里', `description`='TSO社區音樂會「文化就在巷子裡」\r\n將美好音樂饗宴帶到鄰里之間，提升社區藝術品質、讓民眾在住家附近更輕易的欣賞到優質的音樂演出，豐富市民文化內涵，一直是TSO努力目標。\r\n近年來TSO「文化就在巷子裡」音樂會投入更多人力及物力，強化演出內容，希望藉由悅耳的音樂帶給市民愉悅的心情，也用淺顯易懂的說明讓民眾得到更多基本音樂常識、提昇全民文化底蘊。\r\n演出曲目：\r\n莫札特：小夜曲，作品編號525，第一樂章\r\n莫札特：小夜曲，作品編號525，第三樂章\r\n蕭士塔高維契：第二號圓舞曲\r\n阿布瑞尤：蜂鳥\r\n皮耶佐拉：自由探戈\r\n瑤族舞曲\r\n李哲音：月夜愁、天黑黑\r\n陳哲聖：台北的天空\r\n李哲藝：廟埕\r\n安可-李哲藝：蘭陽舞曲\r\n兒歌大會串：滿山春色、流水年華.....等\r\n', `organizer`='臺北市政府文化局', `address`='臺北市文山區', `start_date`='2025-08-02 00:00:00', `end_date`='2025-08-02 00:00:00', `location`='文山區（臺北市）=', `latitude`=24.98857934, `longitude`=121.5736082, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
