INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbc26b32408680bead9', '《犀旺邸家》陳金旺創作展', '　　2025首檔展覽「犀旺邸家」，聚焦於家的意義。透過仿青銅新作犀牛穩健踏實的姿態與力量，詮釋民眾對安居的嚮往與堅持，也深刻映照出年輕世代在低收入、高房價時代，對「家」的渴望與追尋。\r\n　　邀請藝術愛好者與社會大眾，一同走進《犀旺邸家》，\r\n欣賞各種造型犀牛，體驗陶藝與生活交織的深刻對話。', '鉅虹建設', '臺中市北屯區', '2025-03-03 00:00:00', '2025-06-30 00:00:00', '北屯區（臺中市）=', 24.18400298, 120.7362319, '無資料', 'https://reurl.cc/aZQo73', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《犀旺邸家》陳金旺創作展', `description`='　　2025首檔展覽「犀旺邸家」，聚焦於家的意義。透過仿青銅新作犀牛穩健踏實的姿態與力量，詮釋民眾對安居的嚮往與堅持，也深刻映照出年輕世代在低收入、高房價時代，對「家」的渴望與追尋。\r\n　　邀請藝術愛好者與社會大眾，一同走進《犀旺邸家》，\r\n欣賞各種造型犀牛，體驗陶藝與生活交織的深刻對話。', `organizer`='鉅虹建設', `address`='臺中市北屯區', `start_date`='2025-03-03 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='北屯區（臺中市）=', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://reurl.cc/aZQo73', `image_url`='[]';
