INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beae5', '文學異界－南方的奇幻國度', '文學東方的盤古開天到西方的宙斯、阿波羅，神話自古以來便是文學想像的核心，甚至可說是文學史的起點。屏東地方文學中，信仰與傳說亦是不可或缺的養分——神話帶來信仰，妖怪激發想像，這些神妖故事如神來之筆，讓作品情節更加曲折且具地方特色。像是萬丹斷指媽祖、東港溫王爺、荷蘭八寶公主等皆成為描寫南方故事的主角，彰顯神話之力在文學中的無限可能性。', '屏東縣政府文化處', '屏東縣屏東市大連路69號', '2025-01-25 00:00:00', '2025-07-20 00:00:00', '屏東縣政府文化處/屏東縣立圖書館總館', 22.665122, 120.502426, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='文學異界－南方的奇幻國度', `description`='文學東方的盤古開天到西方的宙斯、阿波羅，神話自古以來便是文學想像的核心，甚至可說是文學史的起點。屏東地方文學中，信仰與傳說亦是不可或缺的養分——神話帶來信仰，妖怪激發想像，這些神妖故事如神來之筆，讓作品情節更加曲折且具地方特色。像是萬丹斷指媽祖、東港溫王爺、荷蘭八寶公主等皆成為描寫南方故事的主角，彰顯神話之力在文學中的無限可能性。', `organizer`='屏東縣政府文化處', `address`='屏東縣屏東市大連路69號', `start_date`='2025-01-25 00:00:00', `end_date`='2025-07-20 00:00:00', `location`='屏東縣政府文化處/屏東縣立圖書館總館', `latitude`=22.665122, `longitude`=120.502426, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cb5bbd26b32408680beaec', '2025《消失的密室》管風琴導覽(7月)', '一探管風琴室最深處的心臟，只在屏東𖣐\r\n✦全台第三大管風琴 ✦獨特水平音管設計 ✦在地特色「福爾摩沙笛管」\r\n\r\n精彩內容\r\nꚰ 揭秘管風琴建置、內部結構與發聲原理\r\nꚰ 管風琴老師演出與導聆，展現多層次琴音之美\r\nꚰ 親自體驗管風琴彈奏，感受震撼音效\r\n\r\n主講：謝金相 先生\r\n經歷：任職功學社集團年資共計39年\r\n-功學社貿易公司五福分公司主任\r\n-功學社山葉樂器公司南區營業課長\r\n-功學社音樂中心中南區營業部經理\r\n\r\n管風琴：王安琪老師\r\n高雄市人。1991~1994就讀東吳大學音樂系，主修管風琴，師事陳相瑜老師；副修鋼琴，師事諸大明教授。1994~1999就讀於柏林藝術大學音樂系，主修管風琴，師事Prof. Heinemann；副修大鍵琴，師事Prof. Meyerson。先後取得管風琴藝術家文憑與獨奏家文憑。熱心公益與教會事工。目前全心致力於推廣管風琴音樂。', '屏東縣政府文化處', '屏東縣屏東市民生路4之17號', '2025-07-09 00:00:00', '2025-07-23 00:00:00', '屏東演藝廳', 22.6647375, 120.4799948, '全票+200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025《消失的密室》管風琴導覽(7月)', `description`='一探管風琴室最深處的心臟，只在屏東𖣐\r\n✦全台第三大管風琴 ✦獨特水平音管設計 ✦在地特色「福爾摩沙笛管」\r\n\r\n精彩內容\r\nꚰ 揭秘管風琴建置、內部結構與發聲原理\r\nꚰ 管風琴老師演出與導聆，展現多層次琴音之美\r\nꚰ 親自體驗管風琴彈奏，感受震撼音效\r\n\r\n主講：謝金相 先生\r\n經歷：任職功學社集團年資共計39年\r\n-功學社貿易公司五福分公司主任\r\n-功學社山葉樂器公司南區營業課長\r\n-功學社音樂中心中南區營業部經理\r\n\r\n管風琴：王安琪老師\r\n高雄市人。1991~1994就讀東吳大學音樂系，主修管風琴，師事陳相瑜老師；副修鋼琴，師事諸大明教授。1994~1999就讀於柏林藝術大學音樂系，主修管風琴，師事Prof. Heinemann；副修大鍵琴，師事Prof. Meyerson。先後取得管風琴藝術家文憑與獨奏家文憑。熱心公益與教會事工。目前全心致力於推廣管風琴音樂。', `organizer`='屏東縣政府文化處', `address`='屏東縣屏東市民生路4之17號', `start_date`='2025-07-09 00:00:00', `end_date`='2025-07-23 00:00:00', `location`='屏東演藝廳', `latitude`=22.6647375, `longitude`=120.4799948, `ticket_price`='全票+200', `source_url`='https://www.opentix.life/', `image_url`='[]';
