INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9368489', '臺北市中正區公所114年度新住民「電影欣賞走讀班」，歡迎報名參加。', '臺北市中正區公所將於114年3月16日（星期日）下午13時至17時及4月12日（星期六）上午9時至12時辦理114年「新住民電影欣賞走讀班」，集合地點：錄取者將發送行前通知，屆時以通知地點為主，報名方式採網路線上報名，114年3月5日上午9時30分起受理線上報名，將依報名時間依序錄取至額滿為止，歡迎報名參加，詳情請洽2341-6721轉317張小姐。', '臺北市內湖區戶政事務所', '無資料', '2025-03-16 00:00:00', '2025-04-12 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=14FCC4C8E67DF86B', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺北市中正區公所114年度新住民「電影欣賞走讀班」，歡迎報名參加。', `description`='臺北市中正區公所將於114年3月16日（星期日）下午13時至17時及4月12日（星期六）上午9時至12時辦理114年「新住民電影欣賞走讀班」，集合地點：錄取者將發送行前通知，屆時以通知地點為主，報名方式採網路線上報名，114年3月5日上午9時30分起受理線上報名，將依報名時間依序錄取至額滿為止，歡迎報名參加，詳情請洽2341-6721轉317張小姐。', `organizer`='臺北市內湖區戶政事務所', `address`='無資料', `start_date`='2025-03-16 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=14FCC4C8E67DF86B', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9350832', '天文魔法小書包(3/15)', '臺北天文館推出融入STEAM教育的「天文魔法小書包」活動，讓親子跟隨著專業解說員，體驗展場好玩的展品，搭乘宇宙探險車遨遊太陽系，並完成科學教具動手做，透過輕鬆有趣的方式學習天文，共享親子間美好的共學時光。活動時間：3月15日（六）14:00-16:00。活動對象：親子（家長、幼稚園大班至國小四年級以下學童皆可）。活動地點：展示場、宇宙探險。活動費用：本活動須購買展示場、宇宙探險門票 ，票價請參閱購票資訊。報名方式：線上報名。注意事項：家長及孩童皆需報名（每張表單僅填一名參加者），每場次以50位親子為限，額滿為止。如有餘額則開放合乎資格之現場民眾參加。活動一週前，接受網路預約報名。洽詢電話：02-28314551轉706展示組陳小姐。「天文魔法小書包」活動流程表時間活動內容活動地點14:00-14:15報到中庭服務台14:15-15:00搭乘軌道車、主題導覽展示場、4F宇宙探險15:00-16:00DIY課程展示場1F天文教室16:00活動證請交還工作人員如有疑問，請找現場服務人員。', '臺北市立天文科學教育館', '無資料', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A393CF2E85656866', '[]') ON DUPLICATE KEY UPDATE `activity_name`='天文魔法小書包(3/15)', `description`='臺北天文館推出融入STEAM教育的「天文魔法小書包」活動，讓親子跟隨著專業解說員，體驗展場好玩的展品，搭乘宇宙探險車遨遊太陽系，並完成科學教具動手做，透過輕鬆有趣的方式學習天文，共享親子間美好的共學時光。活動時間：3月15日（六）14:00-16:00。活動對象：親子（家長、幼稚園大班至國小四年級以下學童皆可）。活動地點：展示場、宇宙探險。活動費用：本活動須購買展示場、宇宙探險門票 ，票價請參閱購票資訊。報名方式：線上報名。注意事項：家長及孩童皆需報名（每張表單僅填一名參加者），每場次以50位親子為限，額滿為止。如有餘額則開放合乎資格之現場民眾參加。活動一週前，接受網路預約報名。洽詢電話：02-28314551轉706展示組陳小姐。「天文魔法小書包」活動流程表時間活動內容活動地點14:00-14:15報到中庭服務台14:15-15:00搭乘軌道車、主題導覽展示場、4F宇宙探險15:00-16:00DIY課程展示場1F天文教室16:00活動證請交還工作人員如有疑問，請找現場服務人員。', `organizer`='臺北市立天文科學教育館', `address`='無資料', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A393CF2E85656866', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9366011', '萬興分館【萬興里親子讀經班】歡迎報名參加', '為推廣幼兒品德教育，招收5歲-國小六年級學童及家長進行親子讀經活動(需由家長陪讀)，課程規劃上分為學童及家長兩部分。學童部分為：啟蒙文學、百孝經、論語等。家長部分為：親子教育、親子及身心靈講座、讀書會等。&sect;活動時間：3月7日至6月20日每週五19：30-20：40&sect;活動地點：臺北市立圖書館萬興分館5樓多功能活動室、惇德書苑&sect;活動對象：5歲-國小六年級學童及家長(需家長陪同讀經)&sect;報名方式：活動日現場（臺北市文山區萬壽路27號5樓多功能能活動室）&sect;電話聯繫：萬興圖書館02-22345501轉9林金生老師02-29399913或0935790360&sect;交通資訊：https://reurl.cc/xLjln1', '臺北市立圖書館', '無資料', '2025-03-07 00:00:00', '2025-06-20 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=ECD96F2796FB5B53', '[]') ON DUPLICATE KEY UPDATE `activity_name`='萬興分館【萬興里親子讀經班】歡迎報名參加', `description`='為推廣幼兒品德教育，招收5歲-國小六年級學童及家長進行親子讀經活動(需由家長陪讀)，課程規劃上分為學童及家長兩部分。學童部分為：啟蒙文學、百孝經、論語等。家長部分為：親子教育、親子及身心靈講座、讀書會等。&sect;活動時間：3月7日至6月20日每週五19：30-20：40&sect;活動地點：臺北市立圖書館萬興分館5樓多功能活動室、惇德書苑&sect;活動對象：5歲-國小六年級學童及家長(需家長陪同讀經)&sect;報名方式：活動日現場（臺北市文山區萬壽路27號5樓多功能能活動室）&sect;電話聯繫：萬興圖書館02-22345501轉9林金生老師02-29399913或0935790360&sect;交通資訊：https://reurl.cc/xLjln1', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-07 00:00:00', `end_date`='2025-06-20 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=ECD96F2796FB5B53', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9362237', '【民生分館x傳鈺資產管理顧問】樂齡生活法律講座', '臺灣人口老化，逐漸走入高齡化社會，在退休生活中我們可能碰到關於財務及遺囑規劃的問題，民生分館特與傳鈺資產管理顧問公司合作，邀請專業的財務規劃師及律師到館演講，讓我們一起了解生活中的法律知識！各場次時間及主題： 第1場：3月28日(五) 上午10:00～12:00財規做得好～樂齡沒煩惱：銀髮族應知的財務法律大小事第2場：4月19日(六) 上午10:00～12:00&nbsp;最後一封家書～談遺囑規劃地點：臺北市立圖書館民生分館5樓視聽室活動對象：55歲以上樂齡民眾參加方式：本活動採事先報名，請親自到民生分館服務臺，或撥打電話(02)2713-8083登記報名。（如有剩餘名額當日亦開放現場報名入場。）聯絡資訊：臺北市立圖書館民生分館地址：臺北市松山區敦化北路199巷5號4樓電話：(02)2713-8083本館保有修改、變更或暫停活動之權益，最新資訊以館內公告為主。如有未盡事宜，本館保有調整及最終解釋之權利。', '臺北市立圖書館', '無資料', '2025-03-07 00:00:00', '2025-04-19 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=BA07438909A61BD2', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【民生分館x傳鈺資產管理顧問】樂齡生活法律講座', `description`='臺灣人口老化，逐漸走入高齡化社會，在退休生活中我們可能碰到關於財務及遺囑規劃的問題，民生分館特與傳鈺資產管理顧問公司合作，邀請專業的財務規劃師及律師到館演講，讓我們一起了解生活中的法律知識！各場次時間及主題： 第1場：3月28日(五) 上午10:00～12:00財規做得好～樂齡沒煩惱：銀髮族應知的財務法律大小事第2場：4月19日(六) 上午10:00～12:00&nbsp;最後一封家書～談遺囑規劃地點：臺北市立圖書館民生分館5樓視聽室活動對象：55歲以上樂齡民眾參加方式：本活動採事先報名，請親自到民生分館服務臺，或撥打電話(02)2713-8083登記報名。（如有剩餘名額當日亦開放現場報名入場。）聯絡資訊：臺北市立圖書館民生分館地址：臺北市松山區敦化北路199巷5號4樓電話：(02)2713-8083本館保有修改、變更或暫停活動之權益，最新資訊以館內公告為主。如有未盡事宜，本館保有調整及最終解釋之權利。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-07 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=BA07438909A61BD2', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9367982', '道藩成功「萬花書境」雙月主題書展之花境Ⅱ', '本年度書展以金蛇年「萬花書境」為意象，每兩個月推出不同主題的書展，邀請讀者如祥蛇穿梭於群花爭妍的綺麗花叢，探索多彩多姿的書籍世界。書展形式結合實體書與電子書同步展出，希望為讀者提供豐富的選擇，便捷的閱讀體驗與全新的視野。3至4月將以「童話繽紛夢：奇境大冒險」為主題，結合國際兒童圖書日的精神，本書展以「童話」為主題，帶領讀者進入經典與現代童話的奇幻世界！從格林童話到當代童書佳作，精選作品涵蓋冒險、勇氣與夢想，適合孩子和大人一同探索。讓我們在春日的童話王國中，感受閱讀的魔力，發現每個故事背後的無限可能！一、活動時間：3月1日至4月30日二、活動地點：道藩分館書展區、成功民閱書展區三、主辦單位：臺北市立圖書館道藩分館地 &nbsp;址：臺北市大安區辛亥路3段11號3樓電 &nbsp;話：(02)27334031臺北市立圖書館成功民眾閱覽室地 &nbsp;址：臺北市大安區和平東路2段311巷29號4樓電 &nbsp;話：(02)27013604', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B458697FD64AB3F4', '[]') ON DUPLICATE KEY UPDATE `activity_name`='道藩成功「萬花書境」雙月主題書展之花境Ⅱ', `description`='本年度書展以金蛇年「萬花書境」為意象，每兩個月推出不同主題的書展，邀請讀者如祥蛇穿梭於群花爭妍的綺麗花叢，探索多彩多姿的書籍世界。書展形式結合實體書與電子書同步展出，希望為讀者提供豐富的選擇，便捷的閱讀體驗與全新的視野。3至4月將以「童話繽紛夢：奇境大冒險」為主題，結合國際兒童圖書日的精神，本書展以「童話」為主題，帶領讀者進入經典與現代童話的奇幻世界！從格林童話到當代童書佳作，精選作品涵蓋冒險、勇氣與夢想，適合孩子和大人一同探索。讓我們在春日的童話王國中，感受閱讀的魔力，發現每個故事背後的無限可能！一、活動時間：3月1日至4月30日二、活動地點：道藩分館書展區、成功民閱書展區三、主辦單位：臺北市立圖書館道藩分館地 &nbsp;址：臺北市大安區辛亥路3段11號3樓電 &nbsp;話：(02)27334031臺北市立圖書館成功民眾閱覽室地 &nbsp;址：臺北市大安區和平東路2段311巷29號4樓電 &nbsp;話：(02)27013604', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B458697FD64AB3F4', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9367850', '總館留學資料中心4/19「福岡留學札記」講座，歡迎參加！', '日本九州大學是位於福岡縣福岡市的一所綜合性大學，屬日本舊帝國大學之一，排名日本第四位、QS世界大學在第124名，除自身學術研究精進外，該校也積極進行學術交流與研究合作，與世界百校簽訂學術交流協議與設立多項交換學生計劃。本館於4月19日（六）邀請畢業於日本九州大學化學所的林昱銘講師，分享日本留學前的準備、院試合格之前的路、留日生活點滴與九州文化體驗等分享，本次講座講師亦分享獎學金申請過程，機會難得不容錯過。(本講座不特別錄影，欲參加者請把握機會!)主題：福岡留學札記時間：4月19日（星期六）下午2時至4時地點：總館9樓多功能教室講師：林昱銘成功大學化學系學士日本九州大學化學系碩士工研院 材化所副研究員活動對象：一般大眾及計劃出國留學者報名方式：網路報名本場講座人數限額60名，請事先線上報名，報名成功者活動當週將以email通知，若當日已達限額人數恕無法直接入場。講座大綱：1. 你也可以 : 留日動機與準備2. 我的經驗 : 院試合格前的路3. 留日雜談 : 碩士生活不簡單4. 忙裡偷閒 : 一個人的九州行5. 結語◆交通資訊：到館資訊服務據點一覽---------------------臺北市立圖書館留學資料中心地址：臺北市大安區建國南路2段125號3樓服務時間：週一、週日9：00～17：00；週二至週六8：30～21：00洽詢電話：（02）2707-1008網址：https://studyabroad-tpml.gov.taipei/', '臺北市立圖書館', '無資料', '2025-03-05 00:00:00', '2025-04-19 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=4BE71E3A7EB8A9D4', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館留學資料中心4/19「福岡留學札記」講座，歡迎參加！', `description`='日本九州大學是位於福岡縣福岡市的一所綜合性大學，屬日本舊帝國大學之一，排名日本第四位、QS世界大學在第124名，除自身學術研究精進外，該校也積極進行學術交流與研究合作，與世界百校簽訂學術交流協議與設立多項交換學生計劃。本館於4月19日（六）邀請畢業於日本九州大學化學所的林昱銘講師，分享日本留學前的準備、院試合格之前的路、留日生活點滴與九州文化體驗等分享，本次講座講師亦分享獎學金申請過程，機會難得不容錯過。(本講座不特別錄影，欲參加者請把握機會!)主題：福岡留學札記時間：4月19日（星期六）下午2時至4時地點：總館9樓多功能教室講師：林昱銘成功大學化學系學士日本九州大學化學系碩士工研院 材化所副研究員活動對象：一般大眾及計劃出國留學者報名方式：網路報名本場講座人數限額60名，請事先線上報名，報名成功者活動當週將以email通知，若當日已達限額人數恕無法直接入場。講座大綱：1. 你也可以 : 留日動機與準備2. 我的經驗 : 院試合格前的路3. 留日雜談 : 碩士生活不簡單4. 忙裡偷閒 : 一個人的九州行5. 結語◆交通資訊：到館資訊服務據點一覽---------------------臺北市立圖書館留學資料中心地址：臺北市大安區建國南路2段125號3樓服務時間：週一、週日9：00～17：00；週二至週六8：30～21：00洽詢電話：（02）2707-1008網址：https://studyabroad-tpml.gov.taipei/', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-05 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=4BE71E3A7EB8A9D4', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('c443388c39dfa195f9c0125eafaded59', '三重地政邀請您參加「手機攝影好好玩-手機影片剪輯」志工講座', '新北市三重地政事務所訂於114年3月12日(星期三)下午2點至5點，在該所9樓會議室（地址：新北市三重區新北大道一段11號9樓）舉辦「手機攝影好好玩-手機影片剪輯」志工講座，誠摯歡迎感興趣的市民朋友踴躍報名參加。', '新北市三重地政事務所', '新北市三重區新北大道一段11號9樓', '新北市三重地政事務所', 25.06281651, 121.4870977, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三重地政邀請您參加「手機攝影好好玩-手機影片剪輯」志工講座', `description`='新北市三重地政事務所訂於114年3月12日(星期三)下午2點至5點，在該所9樓會議室（地址：新北市三重區新北大道一段11號9樓）舉辦「手機攝影好好玩-手機影片剪輯」志工講座，誠摯歡迎感興趣的市民朋友踴躍報名參加。', `organizer`='新北市三重地政事務所', `address`='新北市三重區新北大道一段11號9樓', `location`='新北市三重地政事務所', `latitude`=25.06281651, `longitude`=121.4870977, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('c1cebf2f1efab18b1e25243aa43b5014', 'Vets on air獸醫師與您暢聊毛寶貝--寵物醫療線上諮詢服務', '宣導動保處與新北市獸醫師公會合作，藉由邀請獸醫師在直播平台傳遞寵物衛教知識及開放觀看者提問互動等方式，讓民眾不再只能藉由實體的動物醫院和獸醫師互動，而是有更開放且多元的管道接觸有關寵物醫療衛教常識，線上諮詢預計每月固定時間進行，晚上9時至11時，由公會臉書直播，動保處臉書轉發分享。', '新北市政府動物保護防疫處', '新北市板橋區板城路28-1號', '新北市毛寶貝生命教育園區', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Vets on air獸醫師與您暢聊毛寶貝--寵物醫療線上諮詢服務', `description`='宣導動保處與新北市獸醫師公會合作，藉由邀請獸醫師在直播平台傳遞寵物衛教知識及開放觀看者提問互動等方式，讓民眾不再只能藉由實體的動物醫院和獸醫師互動，而是有更開放且多元的管道接觸有關寵物醫療衛教常識，線上諮詢預計每月固定時間進行，晚上9時至11時，由公會臉書直播，動保處臉書轉發分享。', `organizer`='新北市政府動物保護防疫處', `address`='新北市板橋區板城路28-1號', `location`='新北市毛寶貝生命教育園區', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
