INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('61dd724dd083a3542803f570', '【地球you & me】鯨奇石光跡', '【地球You & Me】假日定時兒童活動\n\n■ 主題：鯨奇石光跡🐳🐳\n\n \n\n■ 日期|  3/23(日)\n\n■ 時間| 14:00-15:00 / 15:30-16:30 \n\n■ 內容|「鯨奇石光跡」 透過抹香鯨來到古生物館故事，帶領小朋友認識「鯨豚」以及「標本和化石差異」，再透過鯨豚骨骼標本觀察小遊戲，了解人類與鯨豚的骨骼對應，思考人類與鯨豚的關係。\n\n■地點|古生物館 鯨豚平台\n\n■對象與人數|10組親子觀眾(建議6-12歲學童參加，歡迎家長一同參與)\n\n■報名方式|現場報名，每組親子皆須填寫參與者姓名(活動免費需購票入館)\n\n​***課程若遇特殊狀況臨時更動，本館保有更改或取消場次之權利，敬請包涵***\n\n\n\n ', '國立臺灣博物館', '100  臺北市中正區中正區襄陽路25號(臺博館斜對面)', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '臺博館古生物館 鯨豚平台', 25.0435644, 121.5143628, '活動免費，須憑當日古生物館或本館門票參加', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=12139', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【地球you & me】鯨奇石光跡', `description`='【地球You & Me】假日定時兒童活動\n\n■ 主題：鯨奇石光跡🐳🐳\n\n \n\n■ 日期|  3/23(日)\n\n■ 時間| 14:00-15:00 / 15:30-16:30 \n\n■ 內容|「鯨奇石光跡」 透過抹香鯨來到古生物館故事，帶領小朋友認識「鯨豚」以及「標本和化石差異」，再透過鯨豚骨骼標本觀察小遊戲，了解人類與鯨豚的骨骼對應，思考人類與鯨豚的關係。\n\n■地點|古生物館 鯨豚平台\n\n■對象與人數|10組親子觀眾(建議6-12歲學童參加，歡迎家長一同參與)\n\n■報名方式|現場報名，每組親子皆須填寫參與者姓名(活動免費需購票入館)\n\n​***課程若遇特殊狀況臨時更動，本館保有更改或取消場次之權利，敬請包涵***\n\n\n\n ', `organizer`='國立臺灣博物館', `address`='100  臺北市中正區中正區襄陽路25號(臺博館斜對面)', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='臺博館古生物館 鯨豚平台', `latitude`=25.0435644, `longitude`=121.5143628, `ticket_price`='活動免費，須憑當日古生物館或本館門票參加', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=12139', `image_url`='[]';
