INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9317958', '內湖分館3月「Fun電影」活動', '一、活動地點：臺北市立圖書館內湖分館視聽室(臺北市民權東路6段99號6樓電話:27918772)。二、活動辦法：免費入場，自由參加，並請遵守影片分級制度入場觀賞。三、活動時間：3月16日（週日）上午10：00四、播放影片：&nbsp; &nbsp;《阿嬤的夢中情人》片長125分鐘 (保護級)簡介：當年台語電影正狂熱時人稱北投為「台灣好萊塢」。小婕始終不信台語電影曾經那麼美好，但阿公總驕傲地說:「我可是當年最紅的王牌編劇...」對此小婕始終存疑。小婕失憶症的阿嬤病情日益嚴重，陷入現實與「夢境」的兩茫，並自稱是當年巨星萬寶龍的太太...終於，阿公說出當年在「台灣好萊塢」，如夢似幻般追逐夢想與愛情的故事...', '臺北市立圖書館', '無資料', '2025-03-09 00:00:00', '2025-03-16 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=251D7612971745C4', '[]') ON DUPLICATE KEY UPDATE `activity_name`='內湖分館3月「Fun電影」活動', `description`='一、活動地點：臺北市立圖書館內湖分館視聽室(臺北市民權東路6段99號6樓電話:27918772)。二、活動辦法：免費入場，自由參加，並請遵守影片分級制度入場觀賞。三、活動時間：3月16日（週日）上午10：00四、播放影片：&nbsp; &nbsp;《阿嬤的夢中情人》片長125分鐘 (保護級)簡介：當年台語電影正狂熱時人稱北投為「台灣好萊塢」。小婕始終不信台語電影曾經那麼美好，但阿公總驕傲地說:「我可是當年最紅的王牌編劇...」對此小婕始終存疑。小婕失憶症的阿嬤病情日益嚴重，陷入現實與「夢境」的兩茫，並自稱是當年巨星萬寶龍的太太...終於，阿公說出當年在「台灣好萊塢」，如夢似幻般追逐夢想與愛情的故事...', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=251D7612971745C4', `image_url`='[]';
