INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0226b32408680beb1b', '國立臺東高級商業職業學校廣告設計科第五屆畢業成果展', '凝聚學生們三年的努力，用學習與創意呈現具啟發性和視覺震撼的盛會，東商廣設科畢業展運用仿金屬雕塑、文學雷雕、AI生成畫作以及專題實作等豐富成果，期盼「設計」深耕，透過多元的視覺表達方式擴大推展，在數位化、全球化時代，廣告成為企業與消費者之間溝通的橋樑，也是品牌建立與塑造的關鍵，東商廣設科致力創意創新、實踐導向，且尊重個性、多元性及社會責任感，歡迎前來共賞這場「現實動態」。', '臺東縣政府文化處', '臺東縣臺東市南京路25號', '2025-03-08 00:00:00', '2025-03-25 00:00:00', '臺東縣政府文化處', 22.75165721, 121.1103647, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國立臺東高級商業職業學校廣告設計科第五屆畢業成果展', `description`='凝聚學生們三年的努力，用學習與創意呈現具啟發性和視覺震撼的盛會，東商廣設科畢業展運用仿金屬雕塑、文學雷雕、AI生成畫作以及專題實作等豐富成果，期盼「設計」深耕，透過多元的視覺表達方式擴大推展，在數位化、全球化時代，廣告成為企業與消費者之間溝通的橋樑，也是品牌建立與塑造的關鍵，東商廣設科致力創意創新、實踐導向，且尊重個性、多元性及社會責任感，歡迎前來共賞這場「現實動態」。', `organizer`='臺東縣政府文化處', `address`='臺東縣臺東市南京路25號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='臺東縣政府文化處', `latitude`=22.75165721, `longitude`=121.1103647, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0226b32408680beb1c', '臺東美術館《家與家的距離》', '展覽從兩位不同世代的魯凱族女性藝術家，對這條不斷遷徙、移居與流離的創作生命歷程路徑中，找到對於家的想像與己身文化的連結，並進一步探討原住民傳統工藝與當代藝術的關係，且從深入分析台灣魯凱族女性的視角與歷史背景如何影響創作過程，也藉由兩位藝術家作品的對話中，來窺探這一過程。', '臺東縣政府', '臺東縣臺東市浙江路350號', '2025-03-01 00:00:00', '2025-03-16 00:00:00', '臺東美術館', 22.75165721, 121.1103647, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺東美術館《家與家的距離》', `description`='展覽從兩位不同世代的魯凱族女性藝術家，對這條不斷遷徙、移居與流離的創作生命歷程路徑中，找到對於家的想像與己身文化的連結，並進一步探討原住民傳統工藝與當代藝術的關係，且從深入分析台灣魯凱族女性的視角與歷史背景如何影響創作過程，也藉由兩位藝術家作品的對話中，來窺探這一過程。', `organizer`='臺東縣政府', `address`='臺東縣臺東市浙江路350號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺東美術館', `latitude`=22.75165721, `longitude`=121.1103647, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0226b32408680beb1d', '臺東美術館《2025 蔡明亮電影放映暨專題演講會》', '放映電影:《不散》\r\n→放映地點:臺東美術館山歌廳\r\n→名額限制:100名\r\n→座談貴賓:蔡明亮、羅素萍\r\n\r\n蔡明亮，1957年出生於馬來西亞的國際知名臺灣電影導演，絕對是臺灣電影代表人物之一。\r\n\r\n「我覺得我電影最大的功能是變成天上的月亮、地上的一朵花。你看月亮、花朵，不會想看懂，不會想得到什麼啟示、知識，你有你自己的月亮跟理解，但最起碼你要懂得抬頭看。每個人都有每個人的月亮，這句話是李安說的。\r\n所有藝術創作都像一朵花，長在那邊，讓你有所啟發、感受，不是讓你獲得什麽，你獲得的是你早就已經有的，所以我想把『看』這件事帶回電影的思考。我花了20年都在做一樣的事，我相信有很多觀眾因此知道怎麽看電影、享受電影，我想我已經足夠了。 」 --- 蔡明亮', '臺東縣政府', '臺東縣臺東市浙江路350號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺東美術館', 22.75165721, 121.1103647, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺東美術館《2025 蔡明亮電影放映暨專題演講會》', `description`='放映電影:《不散》\r\n→放映地點:臺東美術館山歌廳\r\n→名額限制:100名\r\n→座談貴賓:蔡明亮、羅素萍\r\n\r\n蔡明亮，1957年出生於馬來西亞的國際知名臺灣電影導演，絕對是臺灣電影代表人物之一。\r\n\r\n「我覺得我電影最大的功能是變成天上的月亮、地上的一朵花。你看月亮、花朵，不會想看懂，不會想得到什麼啟示、知識，你有你自己的月亮跟理解，但最起碼你要懂得抬頭看。每個人都有每個人的月亮，這句話是李安說的。\r\n所有藝術創作都像一朵花，長在那邊，讓你有所啟發、感受，不是讓你獲得什麽，你獲得的是你早就已經有的，所以我想把『看』這件事帶回電影的思考。我花了20年都在做一樣的事，我相信有很多觀眾因此知道怎麽看電影、享受電影，我想我已經足夠了。 」 --- 蔡明亮', `organizer`='臺東縣政府', `address`='臺東縣臺東市浙江路350號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺東美術館', `latitude`=22.75165721, `longitude`=121.1103647, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
