INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0226b32408680beb20', '第十四屆野望影展《流失的沙》', '十多年來，柬埔寨政府授予多家私營公司特許權， 在當地紅樹林中開採沙石。每年，數百萬公噸的沙石被運往新加坡，以擴大這個島國的陸地面積，而柬埔寨卻失去了自己唯一的天然保護屏障。', '社團法人台灣野望傳播學社', '屏東縣恆春鎮', '2025-05-04 00:00:00', '2025-05-04 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十四屆野望影展《流失的沙》', `description`='十多年來，柬埔寨政府授予多家私營公司特許權， 在當地紅樹林中開採沙石。每年，數百萬公噸的沙石被運往新加坡，以擴大這個島國的陸地面積，而柬埔寨卻失去了自己唯一的天然保護屏障。', `organizer`='社團法人台灣野望傳播學社', `address`='屏東縣恆春鎮', `start_date`='2025-05-04 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0226b32408680beb21', '第十四屆野望影展《先祖的吶喊》', '幾內亞擁有西非最大的黑猩猩族群，世代以來，黑猩猩與人類和平共處。如今因為鋁土礦的開採，迫使黑猩猩與人類離開家園，流離失所，過去共享水源和森林資源的他們，要如何生存下去？', '社團法人台灣野望傳播學社', '屏東縣恆春鎮', '2025-06-08 00:00:00', '2025-06-08 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十四屆野望影展《先祖的吶喊》', `description`='幾內亞擁有西非最大的黑猩猩族群，世代以來，黑猩猩與人類和平共處。如今因為鋁土礦的開採，迫使黑猩猩與人類離開家園，流離失所，過去共享水源和森林資源的他們，要如何生存下去？', `organizer`='社團法人台灣野望傳播學社', `address`='屏東縣恆春鎮', `start_date`='2025-06-08 00:00:00', `end_date`='2025-06-08 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0226b32408680beb22', '第十四屆野望影展《野性古巴 II》', '由於政治與外交的緣故，古巴面臨了60年的與世隔絕，但也保留了加勒比海未被破壞的景象和棲息環境。狂野古巴有著無窮魅力，但現代世界又將如何影響這座島嶼天堂？', '社團法人台灣野望傳播學社', '屏東縣恆春鎮', '2025-06-14 00:00:00', '2025-06-14 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十四屆野望影展《野性古巴 II》', `description`='由於政治與外交的緣故，古巴面臨了60年的與世隔絕，但也保留了加勒比海未被破壞的景象和棲息環境。狂野古巴有著無窮魅力，但現代世界又將如何影響這座島嶼天堂？', `organizer`='社團法人台灣野望傳播學社', `address`='屏東縣恆春鎮', `start_date`='2025-06-14 00:00:00', `end_date`='2025-06-14 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0226b32408680beb23', '第十四屆野望影展《西域兀鷲之境》', '薩丁尼亞島是義大利最後的西域兀鷲棲息地，然而食腐的兀鷲卻因為牧羊人獵殺狐狸或流浪犬等動物的毒餌，導致族群數量減少，反而失去處理羊群屍體的功能。牧羊人將採取什麼方法得以和西域兀鷲和平相處、各蒙其利呢？', '社團法人台灣野望傳播學社', '屏東縣恆春鎮', '2025-06-07 00:00:00', '2025-06-07 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十四屆野望影展《西域兀鷲之境》', `description`='薩丁尼亞島是義大利最後的西域兀鷲棲息地，然而食腐的兀鷲卻因為牧羊人獵殺狐狸或流浪犬等動物的毒餌，導致族群數量減少，反而失去處理羊群屍體的功能。牧羊人將採取什麼方法得以和西域兀鷲和平相處、各蒙其利呢？', `organizer`='社團法人台灣野望傳播學社', `address`='屏東縣恆春鎮', `start_date`='2025-06-07 00:00:00', `end_date`='2025-06-07 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0226b32408680beb24', '第十四屆野望影展《世界屋脊之聲：消失的溼地》', '水壩和污染已傷害了巴基斯坦命脈的印度河，然後另一個重大威脅正在逼近。若是融化中的冰川發生縮減，會造成什麼後果呢？阿拉伯灣的海水漸漸吞沒印度河口三角洲，魚類及耕地都將面臨威脅。', '社團法人台灣野望傳播學社', '屏東縣恆春鎮', '2025-05-11 00:00:00', '2025-05-25 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十四屆野望影展《世界屋脊之聲：消失的溼地》', `description`='水壩和污染已傷害了巴基斯坦命脈的印度河，然後另一個重大威脅正在逼近。若是融化中的冰川發生縮減，會造成什麼後果呢？阿拉伯灣的海水漸漸吞沒印度河口三角洲，魚類及耕地都將面臨威脅。', `organizer`='社團法人台灣野望傳播學社', `address`='屏東縣恆春鎮', `start_date`='2025-05-11 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0326b32408680beb25', '第十四屆野望影展《巴塔哥尼亞：邊緣生命》', '南美洲的巴塔哥尼亞面積超過百萬平方公里，豐富多變的地貌，交織著繁盛的野生動物和人文歷史，本片從美洲獅漫步的低地草原，到高聳的巴塔哥尼亞安地斯山脈，與這裡最靈巧強悍的動物，展開一場壯闊的旅程。', '社團法人台灣野望傳播學社', '屏東縣恆春鎮', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十四屆野望影展《巴塔哥尼亞：邊緣生命》', `description`='南美洲的巴塔哥尼亞面積超過百萬平方公里，豐富多變的地貌，交織著繁盛的野生動物和人文歷史，本片從美洲獅漫步的低地草原，到高聳的巴塔哥尼亞安地斯山脈，與這裡最靈巧強悍的動物，展開一場壯闊的旅程。', `organizer`='社團法人台灣野望傳播學社', `address`='屏東縣恆春鎮', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0326b32408680beb26', '第十四屆野望影展《橡膠水母》', '亂丟垃圾是錯誤行為，那如果任由氣球亂飄呢？即將成為人母的卡莉．威爾遜展開了一場重要的旅程，討論氦氣氣球對於環境、動物與人類的影響，也將揭露這個在人類世界中受到喜愛的派對產品背後令人不安的真相。', '社團法人台灣野望傳播學社', '屏東縣恆春鎮', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十四屆野望影展《橡膠水母》', `description`='亂丟垃圾是錯誤行為，那如果任由氣球亂飄呢？即將成為人母的卡莉．威爾遜展開了一場重要的旅程，討論氦氣氣球對於環境、動物與人類的影響，也將揭露這個在人類世界中受到喜愛的派對產品背後令人不安的真相。', `organizer`='社團法人台灣野望傳播學社', `address`='屏東縣恆春鎮', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0326b32408680beb27', '第十四屆野望影展《倖存者：短尾擬螯蝦再現》', '2020年底，新冠疫情讓全球的多數地區陷入停擺狀態，一支小型研究團隊進入偏遠的塔斯馬尼亞島嶼野地，尋找一種被認為已經滅絕，卻在生態系中扮演重要角色的極危物種--短尾擬螯蝦。', '社團法人台灣野望傳播學社', '屏東縣恆春鎮', '2025-04-13 00:00:00', '2025-04-13 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十四屆野望影展《倖存者：短尾擬螯蝦再現》', `description`='2020年底，新冠疫情讓全球的多數地區陷入停擺狀態，一支小型研究團隊進入偏遠的塔斯馬尼亞島嶼野地，尋找一種被認為已經滅絕，卻在生態系中扮演重要角色的極危物種--短尾擬螯蝦。', `organizer`='社團法人台灣野望傳播學社', `address`='屏東縣恆春鎮', `start_date`='2025-04-13 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0326b32408680beb28', '第十四屆野望影展《自然網絡》', '從婆羅洲到巴西，從塔斯馬尼亞、肯亞到挪威峽灣，這些自然棲息地的物種組成看似不同，然而牠們都在自然世界的複雜網絡上有著明確的角色。而這樣複雜而精細的網絡就建立在生物多樣性的基礎之上。', '社團法人台灣野望傳播學社', '屏東縣恆春鎮', '2025-04-12 00:00:00', '2025-04-26 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十四屆野望影展《自然網絡》', `description`='從婆羅洲到巴西，從塔斯馬尼亞、肯亞到挪威峽灣，這些自然棲息地的物種組成看似不同，然而牠們都在自然世界的複雜網絡上有著明確的角色。而這樣複雜而精細的網絡就建立在生物多樣性的基礎之上。', `organizer`='社團法人台灣野望傳播學社', `address`='屏東縣恆春鎮', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0326b32408680beb29', '第十四屆野望影展《海鳥》', '從孩提時期開始，亞當．尼克森便經常造訪蘇格蘭的偏遠島嶼。那裡曾是海鳥在夏季時生氣勃勃的棲息地。他親眼目睹這些海鳥族群令人痛心的衰落後，為島嶼上的海鳥存亡大聲疾呼。', '社團法人台灣野望傳播學社', '屏東縣恆春鎮', '2025-03-02 00:00:00', '2025-03-16 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十四屆野望影展《海鳥》', `description`='從孩提時期開始，亞當．尼克森便經常造訪蘇格蘭的偏遠島嶼。那裡曾是海鳥在夏季時生氣勃勃的棲息地。他親眼目睹這些海鳥族群令人痛心的衰落後，為島嶼上的海鳥存亡大聲疾呼。', `organizer`='社團法人台灣野望傳播學社', `address`='屏東縣恆春鎮', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0326b32408680beb2a', '第十四屆野望影展《美洲獅：冰山傳奇 II》', '南美巴塔哥尼亞的山巔，存在一座美洲獅的天堂。智利的百內國家公園為美洲獅的生存和繁衍提供了一切所需：遼闊的漫遊空間、可獵捕的大量原駝族群，而且不需與其他大型掠食者競爭。然而天寒地凍中，幼獅卡薩朵拉和手足們被母親拋下，孤依無靠的幼獅們能在嚴酷的環境下生存嗎？卡薩朵拉的未來又會如何呢？', '社團法人台灣野望傳播學社', '屏東縣恆春鎮', '2025-04-05 00:00:00', '2025-04-06 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十四屆野望影展《美洲獅：冰山傳奇 II》', `description`='南美巴塔哥尼亞的山巔，存在一座美洲獅的天堂。智利的百內國家公園為美洲獅的生存和繁衍提供了一切所需：遼闊的漫遊空間、可獵捕的大量原駝族群，而且不需與其他大型掠食者競爭。然而天寒地凍中，幼獅卡薩朵拉和手足們被母親拋下，孤依無靠的幼獅們能在嚴酷的環境下生存嗎？卡薩朵拉的未來又會如何呢？', `organizer`='社團法人台灣野望傳播學社', `address`='屏東縣恆春鎮', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0326b32408680beb2b', '第十四屆野望影展《地中海：圍困而生》', '我們將在美麗而莫測的地中海，踏上一段驚奇的旅程。這片湛藍海水見證了地球生命的演化、古文明的興起以及航海時代的誕生。每年有數百萬人湧向地中海享受著自然美景，但然這片海洋正遭受著巨大的威脅。本片拍攝歷時兩年，跨越了12個不同國家，展示了生存於這座藍色天堂裡動物們，受到人類活動威脅而引發的危機。而在讚嘆地中海之美的同時，我們可以做些什麼保護這些瀕危的生態系嗎？', '社團法人台灣野望傳播學社', '屏東縣恆春鎮', '2025-06-01 00:00:00', '2025-06-15 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十四屆野望影展《地中海：圍困而生》', `description`='我們將在美麗而莫測的地中海，踏上一段驚奇的旅程。這片湛藍海水見證了地球生命的演化、古文明的興起以及航海時代的誕生。每年有數百萬人湧向地中海享受著自然美景，但然這片海洋正遭受著巨大的威脅。本片拍攝歷時兩年，跨越了12個不同國家，展示了生存於這座藍色天堂裡動物們，受到人類活動威脅而引發的危機。而在讚嘆地中海之美的同時，我們可以做些什麼保護這些瀕危的生態系嗎？', `organizer`='社團法人台灣野望傳播學社', `address`='屏東縣恆春鎮', `start_date`='2025-06-01 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0326b32408680beb2e', '114年鹿野鄉立圖書館-3月SDGs永續發展書籍主題展', '氣候變遷、資源短缺、社會公平——這些關鍵議題與我們息息相關！本館精選永續發展目標（SDGs）主題書籍，帶您了解全球挑戰與解決方案。', '臺東縣鹿野鄉公所', '臺東縣鹿野鄉中華路二段137號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺東縣鹿野鄉立圖書館', 22.95125666, 121.1560376, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年鹿野鄉立圖書館-3月SDGs永續發展書籍主題展', `description`='氣候變遷、資源短缺、社會公平——這些關鍵議題與我們息息相關！本館精選永續發展目標（SDGs）主題書籍，帶您了解全球挑戰與解決方案。', `organizer`='臺東縣鹿野鄉公所', `address`='臺東縣鹿野鄉中華路二段137號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺東縣鹿野鄉立圖書館', `latitude`=22.95125666, `longitude`=121.1560376, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0326b32408680beb2c', '臺東美術館114年度系列邀請展—「 Éric Poitevin 個人攝影展 」', '展覽預計展出埃里克．普瓦特凡三個系列的作品：「森林」、「野花」、「動物之殤」。\r\n        「森林」系列，每幅作品約200-300cm長不等，以大尺幅的相片在展場中呈現不同面貌的「自然之景」。當觀眾在展場中行走時，觀看每一幅作品都彷彿是望向一座幽深的樹林，在失去時間失去空間的畫面中映照出自己，存在於那片自然之中，卻不知那片自然存在於何處，是熟悉也是陌生。\r\n       \r\n「野花」系列，則是呈現了原本生長於鄉間野地的雜花野草，在被攝影師從生長之處帶回工作室，並拍攝成影像後，將「無名」與「平凡無奇」的花草從自然中獨立而出，賦予了「定義」與「獨特性」，並與中世紀繪畫產生了聯想，花草不再是花花草草，而是成為了帶有神秘與象徵意義的形象。枯榮之間，短暫與永恆，這些草花從自然原野中被抽離至人類文明的注視中，不生不死。\r\n      \r\n        在不忍心卻又無能為力的情況下，他會將這些動物的屍體帶回工作室，在已經不用擔心「打擾」牠們的狀態中，留下牠們已經走向終點的影像。這些在森林中尋常不過的動物，在純白的背景下，昇華為帶有某種神聖性的意涵，微微滲流的血跡，是為了尊敬及保護這一片自然，而不得不為的「犧牲」，每張影像就彷彿是一座祭壇，在人類的注視中。', '臺東縣政府', '臺東縣臺東市浙江路350號', '2025-03-29 00:00:00', '2025-07-28 00:00:00', '臺東美術館', 22.75165721, 121.1103647, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺東美術館114年度系列邀請展—「 Éric Poitevin 個人攝影展 」', `description`='展覽預計展出埃里克．普瓦特凡三個系列的作品：「森林」、「野花」、「動物之殤」。\r\n        「森林」系列，每幅作品約200-300cm長不等，以大尺幅的相片在展場中呈現不同面貌的「自然之景」。當觀眾在展場中行走時，觀看每一幅作品都彷彿是望向一座幽深的樹林，在失去時間失去空間的畫面中映照出自己，存在於那片自然之中，卻不知那片自然存在於何處，是熟悉也是陌生。\r\n       \r\n「野花」系列，則是呈現了原本生長於鄉間野地的雜花野草，在被攝影師從生長之處帶回工作室，並拍攝成影像後，將「無名」與「平凡無奇」的花草從自然中獨立而出，賦予了「定義」與「獨特性」，並與中世紀繪畫產生了聯想，花草不再是花花草草，而是成為了帶有神秘與象徵意義的形象。枯榮之間，短暫與永恆，這些草花從自然原野中被抽離至人類文明的注視中，不生不死。\r\n      \r\n        在不忍心卻又無能為力的情況下，他會將這些動物的屍體帶回工作室，在已經不用擔心「打擾」牠們的狀態中，留下牠們已經走向終點的影像。這些在森林中尋常不過的動物，在純白的背景下，昇華為帶有某種神聖性的意涵，微微滲流的血跡，是為了尊敬及保護這一片自然，而不得不為的「犧牲」，每張影像就彷彿是一座祭壇，在人類的注視中。', `organizer`='臺東縣政府', `address`='臺東縣臺東市浙江路350號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-07-28 00:00:00', `location`='臺東美術館', `latitude`=22.75165721, `longitude`=121.1103647, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cdfe0326b32408680beb2d', '江賢二藝術園區《光、美與淨化》', '策展人：南條史生、紀嘉華（協同策展人）\r\n由內在光的追尋，到外在光的映現，江賢二以藝術昇華了自我，同時印證「藝術可以淨化人心」的信念。開幕首展「光、美與淨化」以「追尋自由」、「音樂與自然」、「精神性與希望」三個主題，呈現江賢二在藝術創作臻於圓熟之際，回望創作歷程，展出精選作品和藝術家親手打造的場域交相呼應，產生精神性的共鳴。', '財團法人江賢二藝術文化基金會', '臺東縣東河鄉', '2025-03-15 00:00:00', '2025-09-28 00:00:00', '東河鄉（臺東縣）=', 22.98006921, 121.2517917, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='江賢二藝術園區《光、美與淨化》', `description`='策展人：南條史生、紀嘉華（協同策展人）\r\n由內在光的追尋，到外在光的映現，江賢二以藝術昇華了自我，同時印證「藝術可以淨化人心」的信念。開幕首展「光、美與淨化」以「追尋自由」、「音樂與自然」、「精神性與希望」三個主題，呈現江賢二在藝術創作臻於圓熟之際，回望創作歷程，展出精選作品和藝術家親手打造的場域交相呼應，產生精神性的共鳴。', `organizer`='財團法人江賢二藝術文化基金會', `address`='臺東縣東河鄉', `start_date`='2025-03-15 00:00:00', `end_date`='2025-09-28 00:00:00', `location`='東河鄉（臺東縣）=', `latitude`=22.98006921, `longitude`=121.2517917, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9369154', '大安分處-花伴野餐暨租稅宣導活動', '&nbsp; &nbsp; (一)活動名稱：花伴野餐暨租稅宣導活動。&nbsp; &nbsp;&nbsp;(二)活動時間：114年3月15日（星期六）下午1時至5時。&nbsp; &nbsp;&nbsp;(三)活動地點：大安森林公園綠遊派對區。&nbsp; &nbsp;&nbsp;(四)活動內容：&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;１、完成現場指定活動，即可兌換精美小禮物1份。&ensp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;２、捐贈114年1-3月未登打統一編號且消費金額大於10元雲端發票，可兌換宣導品。（每人每次&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;限兌換3份宣導品，數量有限，換完為止。）&nbsp; &nbsp;&nbsp;(五)說明：&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;１、本活動所募發票將全數捐贈公益慈善團體，雲端發票經捐贈完成，即無法退還或兌獎。&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;２、宣導品兌換以現場實物為準，主辦單位保有修改或變更宣導品的權利。&ensp;&ensp;&ensp; &nbsp; 聯絡人：大安分處&ensp;范小姐&ensp;&ensp;&ensp;&ensp; 聯絡電話：2358-1770分機413=====================稅務宣導=========================★雲端發票專屬獎高達13.67億元，500元獎245萬組！發票存載具，對獎機會多1次！★房屋稅差別稅率2.0新制(俗稱囤房稅2.0)於113年7月起施行，自住住家用房屋本人、配偶或直系親屬&nbsp; &nbsp;應辦竣戶籍登記，始可適用自住住家用稅率課徵房屋稅。★稅務視訊服務雲空中E化無國界，一鍵就能搞定稅務大小事。★國地稅免付費專線整合為0800-000-321。★納稅者權利保護法已施行，本處設置納保官保障納稅者權益。★請多加利用財政部地方稅LINE官方帳號與智慧客服。★直撥退稅線上回復，免擔心支票遺失或逾期。★當志工樂趣多，邀請一同加入志工服務行列。★申辦「稅籍異動即時通」服務，讓您掌握不動產移轉動態。★稅捐稽徵法修正，稅捐逾繳納期限始繳納，須加徵滯納金之加徵方式，修正為「每逾3日」按滯納數&nbsp; &nbsp;額加徵1％，總加徵率降為10％。★性別平等從你我做起，落實性別平權繼承與贈與不分性別。★臺北市公益性出租房屋租稅優惠。★國外帶回之免稅菸酒不得販賣，網路禁賣菸酒。★對滯納（欠）使用牌照稅案件，請交通工具所有人或使用人依限繳納，以免欠稅車輛使用（停放）&nbsp; &nbsp;公共道路被查獲而受罰。★交通工具如不擬使用，請向監理機關申報停止使用。★請多加利用各項E化繳稅管道（含行動支付、臨櫃信用卡、TW&ensp;FidO、Line&ensp;Pay等）及財政部擴大&nbsp; &nbsp;線上繳稅機制。★不動產移轉一站式服務。★臺北市分期繳納地方稅申請辦法。★全功能自動化服務機自助申辦或查調稅務案件、補發稅單及繳稅。★歡迎申辦以電子方式傳送繳款書及繳納證明。', '臺北市稅捐稽徵處', '無資料', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F1EDFF72174631F8', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大安分處-花伴野餐暨租稅宣導活動', `description`='&nbsp; &nbsp; (一)活動名稱：花伴野餐暨租稅宣導活動。&nbsp; &nbsp;&nbsp;(二)活動時間：114年3月15日（星期六）下午1時至5時。&nbsp; &nbsp;&nbsp;(三)活動地點：大安森林公園綠遊派對區。&nbsp; &nbsp;&nbsp;(四)活動內容：&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;１、完成現場指定活動，即可兌換精美小禮物1份。&ensp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;２、捐贈114年1-3月未登打統一編號且消費金額大於10元雲端發票，可兌換宣導品。（每人每次&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;限兌換3份宣導品，數量有限，換完為止。）&nbsp; &nbsp;&nbsp;(五)說明：&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;１、本活動所募發票將全數捐贈公益慈善團體，雲端發票經捐贈完成，即無法退還或兌獎。&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;２、宣導品兌換以現場實物為準，主辦單位保有修改或變更宣導品的權利。&ensp;&ensp;&ensp; &nbsp; 聯絡人：大安分處&ensp;范小姐&ensp;&ensp;&ensp;&ensp; 聯絡電話：2358-1770分機413=====================稅務宣導=========================★雲端發票專屬獎高達13.67億元，500元獎245萬組！發票存載具，對獎機會多1次！★房屋稅差別稅率2.0新制(俗稱囤房稅2.0)於113年7月起施行，自住住家用房屋本人、配偶或直系親屬&nbsp; &nbsp;應辦竣戶籍登記，始可適用自住住家用稅率課徵房屋稅。★稅務視訊服務雲空中E化無國界，一鍵就能搞定稅務大小事。★國地稅免付費專線整合為0800-000-321。★納稅者權利保護法已施行，本處設置納保官保障納稅者權益。★請多加利用財政部地方稅LINE官方帳號與智慧客服。★直撥退稅線上回復，免擔心支票遺失或逾期。★當志工樂趣多，邀請一同加入志工服務行列。★申辦「稅籍異動即時通」服務，讓您掌握不動產移轉動態。★稅捐稽徵法修正，稅捐逾繳納期限始繳納，須加徵滯納金之加徵方式，修正為「每逾3日」按滯納數&nbsp; &nbsp;額加徵1％，總加徵率降為10％。★性別平等從你我做起，落實性別平權繼承與贈與不分性別。★臺北市公益性出租房屋租稅優惠。★國外帶回之免稅菸酒不得販賣，網路禁賣菸酒。★對滯納（欠）使用牌照稅案件，請交通工具所有人或使用人依限繳納，以免欠稅車輛使用（停放）&nbsp; &nbsp;公共道路被查獲而受罰。★交通工具如不擬使用，請向監理機關申報停止使用。★請多加利用各項E化繳稅管道（含行動支付、臨櫃信用卡、TW&ensp;FidO、Line&ensp;Pay等）及財政部擴大&nbsp; &nbsp;線上繳稅機制。★不動產移轉一站式服務。★臺北市分期繳納地方稅申請辦法。★全功能自動化服務機自助申辦或查調稅務案件、補發稅單及繳稅。★歡迎申辦以電子方式傳送繳款書及繳納證明。', `organizer`='臺北市稅捐稽徵處', `address`='無資料', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F1EDFF72174631F8', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9369818', '景美就服站114年3月14日(五)14:00-16:00【中興保全科技】微型徵才活動', '活動時間：114.03.14(五)14:00-16:00活動地點：台北市文山區羅斯福路6段393號4樓(捷運景美站1號出口)&nbsp;中興保全科技股份有限公司台北分公司服務工程師15人&nbsp; &nbsp;月薪36453元起(技能津貼及加班費另計)業務專員15人&nbsp; &nbsp; &nbsp; &nbsp;前6個月保障底薪35000-38000元(第7個月月薪31,000元起+高額業績獎金，獎金因案件規模各有不同；保障年薪14個月。)客服人員15人&nbsp; &nbsp; &nbsp; &nbsp;起薪30800元(第1個月固定班，第2個月月薪36453元需輪3班；另有輪值津貼。)&nbsp;職缺詳情請看附件檔案', '臺北市就業服務處', '無資料', '2025-03-14 00:00:00', '2025-03-14 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=FFC5BF1BF37B88DD', '[]') ON DUPLICATE KEY UPDATE `activity_name`='景美就服站114年3月14日(五)14:00-16:00【中興保全科技】微型徵才活動', `description`='活動時間：114.03.14(五)14:00-16:00活動地點：台北市文山區羅斯福路6段393號4樓(捷運景美站1號出口)&nbsp;中興保全科技股份有限公司台北分公司服務工程師15人&nbsp; &nbsp;月薪36453元起(技能津貼及加班費另計)業務專員15人&nbsp; &nbsp; &nbsp; &nbsp;前6個月保障底薪35000-38000元(第7個月月薪31,000元起+高額業績獎金，獎金因案件規模各有不同；保障年薪14個月。)客服人員15人&nbsp; &nbsp; &nbsp; &nbsp;起薪30800元(第1個月固定班，第2個月月薪36453元需輪3班；另有輪值津貼。)&nbsp;職缺詳情請看附件檔案', `organizer`='臺北市就業服務處', `address`='無資料', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-14 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=FFC5BF1BF37B88DD', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9369816', '臺北願景館即將在2025智慧城市展 3/18~3/21登場', '【臺北願景館】即將在2025智慧城市展 3/18~3/21登場快來一探究竟!臺北如何以AI驅動智慧城市的發展現場有集點送限量小禮物還有多項亮點互動️*消防車開箱、AI消防設備展示*AI眼底攝影機、AI專業醫療級12導程心電圖檢測*AI運動科學設備實機體驗*實機操作AI英語聽力練習、AI輔助手寫批閱臺北市政府願景館以「AI驅動&middot;未來臺北」為主軸預覽 #安全之都 &nbsp;#運動之都 #未來之都 的創新科技🚀親身體驗AI如何塑造未來臺北，共創智慧城市新典範!~趕快標註日曆️~一起來【南港展覽館2館1樓攤位P1013】體驗臺北的無限可能！#FutureTaipei #智慧城市展 #南港展覽館 #臺北願景─── 入場方式 ───◆憑國內參觀入場證線上登記https://smartcity.org.tw/m_login.php◆現場購票200元/人◆不開放未滿12歲以下兒童入場，勿穿涼鞋及拖鞋───展覽資訊───展覽日期｜2024/3/18~3/21開放時間｜10:00-18:00（展期最後一天僅至17:00）', '臺北市政府警察局文山第二分局', '無資料', '2025-03-18 00:00:00', '2025-03-21 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F3F527C47C5B60FA', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺北願景館即將在2025智慧城市展 3/18~3/21登場', `description`='【臺北願景館】即將在2025智慧城市展 3/18~3/21登場快來一探究竟!臺北如何以AI驅動智慧城市的發展現場有集點送限量小禮物還有多項亮點互動️*消防車開箱、AI消防設備展示*AI眼底攝影機、AI專業醫療級12導程心電圖檢測*AI運動科學設備實機體驗*實機操作AI英語聽力練習、AI輔助手寫批閱臺北市政府願景館以「AI驅動&middot;未來臺北」為主軸預覽 #安全之都 &nbsp;#運動之都 #未來之都 的創新科技🚀親身體驗AI如何塑造未來臺北，共創智慧城市新典範!~趕快標註日曆️~一起來【南港展覽館2館1樓攤位P1013】體驗臺北的無限可能！#FutureTaipei #智慧城市展 #南港展覽館 #臺北願景─── 入場方式 ───◆憑國內參觀入場證線上登記https://smartcity.org.tw/m_login.php◆現場購票200元/人◆不開放未滿12歲以下兒童入場，勿穿涼鞋及拖鞋───展覽資訊───展覽日期｜2024/3/18~3/21開放時間｜10:00-18:00（展期最後一天僅至17:00）', `organizer`='臺北市政府警察局文山第二分局', `address`='無資料', `start_date`='2025-03-18 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F3F527C47C5B60FA', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9369659', '萬華區114年健行活動(3/10下午1:45已額滿，謝謝大家!)', '活動時間：114年3月22日（六）上午8:30前報到，集合。集合地點：臺北市馬場町紀念公園廣場活動路線：臺北市馬場町紀念公園&rarr;華中河濱公園&rarr;光復橋下&rarr;折返回臺北市馬場町紀念公園【全程5.8公里，路程約2時】。電話：(02)23064468#115(已額滿為止，恕不另行公告。)交通資訊：&nbsp; (一)搭公車：搭乘 20、棕22、中山幹線至「青年公園（馬場町）站」下車。&nbsp; (二)開車:請至下列地點停車&nbsp; &nbsp; &nbsp; 1.馬場町紀念公園停車場。&nbsp; &nbsp; &nbsp; 2.青年公園棒球場地下停車場。&nbsp; (三)U-bike：租賃站點為「青年公園3號出口」（青年路/青年路106巷東側）&nbsp;※名額額滿即停止受理報名，不另行公告。', '臺北市萬華區公所', '無資料', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8DEB59D76EBE7679', '[]') ON DUPLICATE KEY UPDATE `activity_name`='萬華區114年健行活動(3/10下午1:45已額滿，謝謝大家!)', `description`='活動時間：114年3月22日（六）上午8:30前報到，集合。集合地點：臺北市馬場町紀念公園廣場活動路線：臺北市馬場町紀念公園&rarr;華中河濱公園&rarr;光復橋下&rarr;折返回臺北市馬場町紀念公園【全程5.8公里，路程約2時】。電話：(02)23064468#115(已額滿為止，恕不另行公告。)交通資訊：&nbsp; (一)搭公車：搭乘 20、棕22、中山幹線至「青年公園（馬場町）站」下車。&nbsp; (二)開車:請至下列地點停車&nbsp; &nbsp; &nbsp; 1.馬場町紀念公園停車場。&nbsp; &nbsp; &nbsp; 2.青年公園棒球場地下停車場。&nbsp; (三)U-bike：租賃站點為「青年公園3號出口」（青年路/青年路106巷東側）&nbsp;※名額額滿即停止受理報名，不另行公告。', `organizer`='臺北市萬華區公所', `address`='無資料', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8DEB59D76EBE7679', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9369571', '防詐宣導 - 警惕海外求職詐騙！勿輕信「海外求職」要求，保持要存疑、要確定及要連繫，以避免自身至海外，掉入假求職陷阱，遭人受騙。', '一、分析本市114年2月各類詐欺案件發生數共計1,208件，財損新臺幣（以下同）10億3,915萬元，前3大詐欺手法之受理件數及財損金額：　（一）網路購物詐騙267件，財損873.7萬元。　（二）假投資詐騙236件，財損5億1,729.7萬元。　（三）假交友(投資詐財)詐騙74件，財損1億5,602.9萬元。二、海外求職詐騙，高薪工作背後可能是器官販賣或詐騙工廠：　（一）要存疑，查證徵才公司是否合法立案。　（二）要確定，要確定工作地點與工作內容。　（三）要聯繫，行蹤隨時告知國內親友。', '臺北市政府資訊局', '無資料', '2025-03-10 00:00:00', '2025-03-31 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=11943F22FFCDCCED', '[]') ON DUPLICATE KEY UPDATE `activity_name`='防詐宣導 - 警惕海外求職詐騙！勿輕信「海外求職」要求，保持要存疑、要確定及要連繫，以避免自身至海外，掉入假求職陷阱，遭人受騙。', `description`='一、分析本市114年2月各類詐欺案件發生數共計1,208件，財損新臺幣（以下同）10億3,915萬元，前3大詐欺手法之受理件數及財損金額：　（一）網路購物詐騙267件，財損873.7萬元。　（二）假投資詐騙236件，財損5億1,729.7萬元。　（三）假交友(投資詐財)詐騙74件，財損1億5,602.9萬元。二、海外求職詐騙，高薪工作背後可能是器官販賣或詐騙工廠：　（一）要存疑，查證徵才公司是否合法立案。　（二）要確定，要確定工作地點與工作內容。　（三）要聯繫，行蹤隨時告知國內親友。', `organizer`='臺北市政府資訊局', `address`='無資料', `start_date`='2025-03-10 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=11943F22FFCDCCED', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9369271', '【臺北願景館】即將在2025智慧城市展 3/18~3/21登場', '快來一探究竟！臺北如何以AI驅動智慧城市的發展現場有集點送限量小禮，還有多項亮點互動消防車開箱、AI消防設備展示AI眼底攝影機AI專業醫療級12導程心電圖檢測AI運動科學設備實機體驗實機操作AI英語聽力練習AI輔助手寫批閱臺北市政府願景館以「AI驅動&middot;未來臺北」為主軸 預覽 #安全之都 #運動之都 #未來之都 的創新科技🚀親身體驗AI如何塑造未來臺北，共創智慧城市新典範!&nbsp;📢趕快標註日曆🗓️ 一起來【南港展覽館2館1樓攤位P1013】體驗臺北的無限可能！#FutureTaipei #智慧城市展 #南港展覽館 #臺北願景─── 入場方式 ───&nbsp;◆憑國內參觀入場證👉線上登記https://smartcity.org.tw/m_login.php&nbsp;◆現場購票200元/人&nbsp;◆不開放未滿12歲以下兒童入場，勿穿涼鞋及拖鞋&nbsp;───展覽資訊───展覽日期｜2024/3/18~3/21開放時間｜10:00-18:00（展期最後一天僅至17:00）展覽地點｜南港展覽館2館1樓【攤位P1013】', '臺北市內湖區戶政事務所', '無資料', '2025-03-18 00:00:00', '2025-03-21 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=590FA6D62685A2CD', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【臺北願景館】即將在2025智慧城市展 3/18~3/21登場', `description`='快來一探究竟！臺北如何以AI驅動智慧城市的發展現場有集點送限量小禮，還有多項亮點互動消防車開箱、AI消防設備展示AI眼底攝影機AI專業醫療級12導程心電圖檢測AI運動科學設備實機體驗實機操作AI英語聽力練習AI輔助手寫批閱臺北市政府願景館以「AI驅動&middot;未來臺北」為主軸 預覽 #安全之都 #運動之都 #未來之都 的創新科技🚀親身體驗AI如何塑造未來臺北，共創智慧城市新典範!&nbsp;📢趕快標註日曆🗓️ 一起來【南港展覽館2館1樓攤位P1013】體驗臺北的無限可能！#FutureTaipei #智慧城市展 #南港展覽館 #臺北願景─── 入場方式 ───&nbsp;◆憑國內參觀入場證👉線上登記https://smartcity.org.tw/m_login.php&nbsp;◆現場購票200元/人&nbsp;◆不開放未滿12歲以下兒童入場，勿穿涼鞋及拖鞋&nbsp;───展覽資訊───展覽日期｜2024/3/18~3/21開放時間｜10:00-18:00（展期最後一天僅至17:00）展覽地點｜南港展覽館2館1樓【攤位P1013】', `organizer`='臺北市內湖區戶政事務所', `address`='無資料', `start_date`='2025-03-18 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=590FA6D62685A2CD', `image_url`='[]';
