INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4fd326b32408680beb46', '【新北市立圖書館中和大同圖書閱覽室】3月萬花盛世主題書展', '在林野鄉間搖曳生姿的花草，只要掌握方式，就能移植到家中或工作場所中，綠化身處的環境，並且讓人時時有花可賞。也可藉由此次書展讓親子一起玩玩土、澆澆水，就能輕鬆打造小花園，讓陽臺、客、書桌變得更美麗。', '新北市立圖書館總館', '新北市中和區圓通路121巷5號1樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館中和大同圖書閱覽室', 24.99088039, 121.4936744, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館中和大同圖書閱覽室】3月萬花盛世主題書展', `description`='在林野鄉間搖曳生姿的花草，只要掌握方式，就能移植到家中或工作場所中，綠化身處的環境，並且讓人時時有花可賞。也可藉由此次書展讓親子一起玩玩土、澆澆水，就能輕鬆打造小花園，讓陽臺、客、書桌變得更美麗。', `organizer`='新北市立圖書館總館', `address`='新北市中和區圓通路121巷5號1樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館中和大同圖書閱覽室', `latitude`=24.99088039, `longitude`=121.4936744, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
