INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4fe426b32408680beb4a', '【新北市立圖書館貢寮分館】嗨!玩一波，旅行趣主題書展', '邀您在閱讀中旅行、在旅行中閱讀。翱遊四海，精彩人生。', '新北市立圖書館總館', '新北市貢寮區仁愛路79號三樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館貢寮分館', 25.02485641, 121.9182466, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館貢寮分館】嗨!玩一波，旅行趣主題書展', `description`='邀您在閱讀中旅行、在旅行中閱讀。翱遊四海，精彩人生。', `organizer`='新北市立圖書館總館', `address`='新北市貢寮區仁愛路79號三樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館貢寮分館', `latitude`=25.02485641, `longitude`=121.9182466, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4fea26b32408680beb4b', '大墩講堂~臺灣國寶孫翠鳳的半生淬鍊 ', '26歲的孫翠鳳，不只不會唱戲，連台語都說得零零落落。她不挑角色，下台就埋頭練功，她花了整整三年揣摩男人，直到她的每一個男人都不普通，都是只有孫翠鳳才能超越的孫翠鳳。而最無敵的角色，是她自己。她不只是威震四方的霸王，更甘願為孩子擋下風雨、為丈夫藏起光芒。她不怕滿身傷，帶著戲班孩子將練功路走得安全寬敞。走過半生，無論什麼身分，都沒有主配角之分。人生淬鍊出她的剛柔並濟──她是無敵小生，更是逆風前行的勇敢查某子。\r\n孫翠鳳女士勇於挑戰極限，文戲、武戲、生旦淨丑各種行當不設限，擅長為角色注入鮮活生命。近二十年來更積極投入歌仔戲的傳承推廣，力挺新生代、培養傳承種子。走訪國際舞台23個國家65座城市，孫翠鳳讓外國人也能比起蘭花指唱歌仔戲，寫下東方戲劇傳奇，且看孫翠鳳充滿血汗、淚水與歡笑的戲劇人生！\r\n活動現場除了講座主軸外，孫翠鳳女士也會配合演講內容即興展示幾段歌仔戲演出示範，推廣並傳承歌仔戲。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=BBD0000208', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大墩講堂~臺灣國寶孫翠鳳的半生淬鍊 ', `description`='26歲的孫翠鳳，不只不會唱戲，連台語都說得零零落落。她不挑角色，下台就埋頭練功，她花了整整三年揣摩男人，直到她的每一個男人都不普通，都是只有孫翠鳳才能超越的孫翠鳳。而最無敵的角色，是她自己。她不只是威震四方的霸王，更甘願為孩子擋下風雨、為丈夫藏起光芒。她不怕滿身傷，帶著戲班孩子將練功路走得安全寬敞。走過半生，無論什麼身分，都沒有主配角之分。人生淬鍊出她的剛柔並濟──她是無敵小生，更是逆風前行的勇敢查某子。\r\n孫翠鳳女士勇於挑戰極限，文戲、武戲、生旦淨丑各種行當不設限，擅長為角色注入鮮活生命。近二十年來更積極投入歌仔戲的傳承推廣，力挺新生代、培養傳承種子。走訪國際舞台23個國家65座城市，孫翠鳳讓外國人也能比起蘭花指唱歌仔戲，寫下東方戲劇傳奇，且看孫翠鳳充滿血汗、淚水與歡笑的戲劇人生！\r\n活動現場除了講座主軸外，孫翠鳳女士也會配合演講內容即興展示幾段歌仔戲演出示範，推廣並傳承歌仔戲。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=BBD0000208', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4fee26b32408680beb4c', '114年3月電影饗宴(2場)', '【電影饗宴】\r\n電影名稱：屁屁偵探電影～天才惡人屁屁亞蒂\r\n播放日期：2025/03/02(日)\r\n播放時間：早上10:00-12:00\r\n電影片長：74分鐘\r\n電影簡介：\r\n呼呼博物館地下有一扇終止於此的門，汪汪警察逮捕了想破門而入的犯人，卻出現了一輛可疑的車將犯人救走。這次事件的幕後主使是邪惡的天才屁屁亞蒂教授，他的目標是祕寶「帕茲」。為了抓住不擇手段的冷酷罪犯屁屁亞蒂，屁屁偵探與國際警察組織的奧多莉搜查官一起合作調查。屁屁偵探在接連不斷的謎案中展開推理，最後，屁屁亞蒂教授引發了一起動搖全鎮的事件。\r\n\r\n電影名稱：德古拉的新娘\r\n播放日期：2025/03/16(日)\r\n播放時間：早上10:00-12:00\r\n電影片長：76分鐘\r\n電影簡介：\r\n長生不老的吸血鬼德古拉一直找不到願意嫁給他的女孩，對愛情感到失望的他決定獨自在城堡度過餘生。突然有天德古拉落入心懷不軌的國王和玩偶設下的圈套，還受到黑暗女巫的威脅，被迫綁架了勇敢的女戰士芭芭拉，而這其實是倫蒂爾國王打算控制世界的邪惡陰謀的一部分。\r\n德古拉在與芭芭拉相處一段時間後，漸漸發現如果沒有芭芭拉，他活得再久也沒有意思。眼看著世界就要落入壞人手中，吸血鬼也將失去一切之際，終究吸血鬼會決定願意犧牲自己不朽的生命，來阻止邪惡的國王贏得芭芭拉的芳心？還是看著芭芭拉被國王搶走？', '臺中市立圖書館中區分館', '臺中市中區成功路300號7樓', '2025-03-02 00:00:00', '2025-03-16 00:00:00', '臺中市立圖書館中區分館', 24.14168566, 120.680598, '無資料', 'https://reurl.cc/WA2Ng5', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年3月電影饗宴(2場)', `description`='【電影饗宴】\r\n電影名稱：屁屁偵探電影～天才惡人屁屁亞蒂\r\n播放日期：2025/03/02(日)\r\n播放時間：早上10:00-12:00\r\n電影片長：74分鐘\r\n電影簡介：\r\n呼呼博物館地下有一扇終止於此的門，汪汪警察逮捕了想破門而入的犯人，卻出現了一輛可疑的車將犯人救走。這次事件的幕後主使是邪惡的天才屁屁亞蒂教授，他的目標是祕寶「帕茲」。為了抓住不擇手段的冷酷罪犯屁屁亞蒂，屁屁偵探與國際警察組織的奧多莉搜查官一起合作調查。屁屁偵探在接連不斷的謎案中展開推理，最後，屁屁亞蒂教授引發了一起動搖全鎮的事件。\r\n\r\n電影名稱：德古拉的新娘\r\n播放日期：2025/03/16(日)\r\n播放時間：早上10:00-12:00\r\n電影片長：76分鐘\r\n電影簡介：\r\n長生不老的吸血鬼德古拉一直找不到願意嫁給他的女孩，對愛情感到失望的他決定獨自在城堡度過餘生。突然有天德古拉落入心懷不軌的國王和玩偶設下的圈套，還受到黑暗女巫的威脅，被迫綁架了勇敢的女戰士芭芭拉，而這其實是倫蒂爾國王打算控制世界的邪惡陰謀的一部分。\r\n德古拉在與芭芭拉相處一段時間後，漸漸發現如果沒有芭芭拉，他活得再久也沒有意思。眼看著世界就要落入壞人手中，吸血鬼也將失去一切之際，終究吸血鬼會決定願意犧牲自己不朽的生命，來阻止邪惡的國王贏得芭芭拉的芳心？還是看著芭芭拉被國王搶走？', `organizer`='臺中市立圖書館中區分館', `address`='臺中市中區成功路300號7樓', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='臺中市立圖書館中區分館', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='https://reurl.cc/WA2Ng5', `image_url`='[]';
