INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4ff126b32408680beb4f', '「臺語冊．講乎咱聽」書展、「城市閱讀」書展--3月書展', '【臺語冊．講乎咱聽】書展\r\n展出期間：2025/03/01~2025/03/30\r\n展出內容：2025「多元閱讀繽紛季」-作伙，以臺語歌謠為主題，展出臺語相關音樂書籍，讓母語透過書本語文字融入日常生活。\r\n\r\n臺中市立圖書館中區分館 邀請您\r\n【城市閱讀】書展\r\n展出期間：2025/03/01~2025/03/30\r\n展出內容：書展期間將展出臺中舊城區，臺中文化歷史，生命教育等相關書籍，提供讀者閱讀。', '臺中市立圖書館中區分館', '臺中市中區成功路300號7樓', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館中區分館', 24.14168566, 120.680598, '無資料', 'https://reurl.cc/zpddK7 ； https://reurl.cc/kMzz8b', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「臺語冊．講乎咱聽」書展、「城市閱讀」書展--3月書展', `description`='【臺語冊．講乎咱聽】書展\r\n展出期間：2025/03/01~2025/03/30\r\n展出內容：2025「多元閱讀繽紛季」-作伙，以臺語歌謠為主題，展出臺語相關音樂書籍，讓母語透過書本語文字融入日常生活。\r\n\r\n臺中市立圖書館中區分館 邀請您\r\n【城市閱讀】書展\r\n展出期間：2025/03/01~2025/03/30\r\n展出內容：書展期間將展出臺中舊城區，臺中文化歷史，生命教育等相關書籍，提供讀者閱讀。', `organizer`='臺中市立圖書館中區分館', `address`='臺中市中區成功路300號7樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館中區分館', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='https://reurl.cc/zpddK7 ； https://reurl.cc/kMzz8b', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4ff126b32408680beb50', '【速寫•臺灣老建築〜臺中舊城】黃至民建築師速寫創作展', '「速寫•臺灣老建築〜臺中舊城」黃至民建築師速寫創作展\r\n展出時間:114年3/08~3/30\r\n展出地點:中區分館藝文廊道\r\n展出內容:\r\n    臺中市中區是全臺灣第一個都市計畫施行的區域，在臺灣的城市史上具有一個獨特的地位。本館此次在藝文廊道的展覽特別邀請前中區區長黃至民建築師展出收錄在去年付梓成書的《速寫․臺灣老建築》一系列中區的速寫作品，如：臺中媽祖萬春宮、彰化銀行總行、第四信用合作社、全安堂、柳原長老教會、第二市場等。藉由黃建築師不同速寫媒材及工具的搭配與運用讓參觀民眾感受畫家筆下舊城區裡不一樣的藝術風格。本次展覽期間自3月8日至3月30日止。\r\n臺中市立圖書館中區分館 邀請您', '臺中市立圖書館中區分館', '臺中市中區成功路300號7樓', '2025-03-08 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館中區分館', 24.14168566, 120.680598, '無資料', 'https://activity.culture.taichung.gov.tw/activites/index-1.asp?id=143965', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【速寫•臺灣老建築〜臺中舊城】黃至民建築師速寫創作展', `description`='「速寫•臺灣老建築〜臺中舊城」黃至民建築師速寫創作展\r\n展出時間:114年3/08~3/30\r\n展出地點:中區分館藝文廊道\r\n展出內容:\r\n    臺中市中區是全臺灣第一個都市計畫施行的區域，在臺灣的城市史上具有一個獨特的地位。本館此次在藝文廊道的展覽特別邀請前中區區長黃至民建築師展出收錄在去年付梓成書的《速寫․臺灣老建築》一系列中區的速寫作品，如：臺中媽祖萬春宮、彰化銀行總行、第四信用合作社、全安堂、柳原長老教會、第二市場等。藉由黃建築師不同速寫媒材及工具的搭配與運用讓參觀民眾感受畫家筆下舊城區裡不一樣的藝術風格。本次展覽期間自3月8日至3月30日止。\r\n臺中市立圖書館中區分館 邀請您', `organizer`='臺中市立圖書館中區分館', `address`='臺中市中區成功路300號7樓', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館中區分館', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='https://activity.culture.taichung.gov.tw/activites/index-1.asp?id=143965', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4ff226b32408680beb51', '「光流影轉/氣象萬千」林順孝西畫創作展', '  「光流影轉/氣象萬千」林順孝西畫創作展訂於2025年3月3日至3月25日（週一至週五）AM9:00~PM12:00/PM13:30~PM17:00在財團法人英才文教基金會全球藝術中心（台中市西屯區府會園道179號4樓）展出，開幕式訂於3月5日（週三）下午2:30舉行，誠摯邀請愛好藝術的朋友蒞臨參觀指教。\r\n    藝術家林順孝畫中流動的雲彩筆意，閃耀的煙塵光影，氣象萬千、璀璨壯麗，表現出非具象世界獨具的魅惑，神秘、夢幻之美觸動人心。\r\n    林順孝1962年生於台中市、東海大學美術研究所碩士，2015年獲選藝術薪火相傳第6屆臺中市美術家接力展油彩類，2016年榮獲第17屆南投縣玉山美術獎油畫類首獎。近年作品更進軍國際，連續獲選2020、2021及2024年法國秋季沙龍展暨2021年法國藝術家沙龍展，作品並受邀刊行於2021年《與時代同行-世界郵票紀念集》發行於荷蘭、紐西蘭、芬蘭、盧森堡等國郵票。\r\n   林順孝表示：「藝術的追求恰似探險者對未知領域的探索，是一種理想、一種浪漫情懷」。其創作擅長藉由光流影轉之氣化美學原創語彙，跨越抽象與具象之界限，營造一種深具東方人文特質的韻律與抒情氣象，呈現出渾沌浩瀚、充斥無限精神能量如極光的日耀雲彩與流盪大氣，展現出一種氣象萬千的獨特原創美學。\r\n   林順孝將於英才文教基金會，展出60餘件近期壓克力媒材作品，尺寸從5號小品系列至240號三聯畫大型平面創作，多元的創作風格，讓觀賞者體會小品精緻之美及大型作品大氣壯闊氛圍。 歡迎蒞臨參觀，感受耳目一新的原創風格及療癒性美感。\r\n', '財團法人英才文教基金會', '臺中市西屯區府會園道179號4樓', '2025-03-03 00:00:00', '2025-03-25 00:00:00', '財團法人英才文教基金會全球藝術中心', 24.1604928, 120.6455336, '無資料', 'https://reurl.cc/qnEgMy', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「光流影轉/氣象萬千」林順孝西畫創作展', `description`='  「光流影轉/氣象萬千」林順孝西畫創作展訂於2025年3月3日至3月25日（週一至週五）AM9:00~PM12:00/PM13:30~PM17:00在財團法人英才文教基金會全球藝術中心（台中市西屯區府會園道179號4樓）展出，開幕式訂於3月5日（週三）下午2:30舉行，誠摯邀請愛好藝術的朋友蒞臨參觀指教。\r\n    藝術家林順孝畫中流動的雲彩筆意，閃耀的煙塵光影，氣象萬千、璀璨壯麗，表現出非具象世界獨具的魅惑，神秘、夢幻之美觸動人心。\r\n    林順孝1962年生於台中市、東海大學美術研究所碩士，2015年獲選藝術薪火相傳第6屆臺中市美術家接力展油彩類，2016年榮獲第17屆南投縣玉山美術獎油畫類首獎。近年作品更進軍國際，連續獲選2020、2021及2024年法國秋季沙龍展暨2021年法國藝術家沙龍展，作品並受邀刊行於2021年《與時代同行-世界郵票紀念集》發行於荷蘭、紐西蘭、芬蘭、盧森堡等國郵票。\r\n   林順孝表示：「藝術的追求恰似探險者對未知領域的探索，是一種理想、一種浪漫情懷」。其創作擅長藉由光流影轉之氣化美學原創語彙，跨越抽象與具象之界限，營造一種深具東方人文特質的韻律與抒情氣象，呈現出渾沌浩瀚、充斥無限精神能量如極光的日耀雲彩與流盪大氣，展現出一種氣象萬千的獨特原創美學。\r\n   林順孝將於英才文教基金會，展出60餘件近期壓克力媒材作品，尺寸從5號小品系列至240號三聯畫大型平面創作，多元的創作風格，讓觀賞者體會小品精緻之美及大型作品大氣壯闊氛圍。 歡迎蒞臨參觀，感受耳目一新的原創風格及療癒性美感。\r\n', `organizer`='財團法人英才文教基金會', `address`='臺中市西屯區府會園道179號4樓', `start_date`='2025-03-03 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='財團法人英才文教基金會全球藝術中心', `latitude`=24.1604928, `longitude`=120.6455336, `ticket_price`='無資料', `source_url`='https://reurl.cc/qnEgMy', `image_url`='[]';
