INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4ff526b32408680beb55', '天上人間-王美玥創作40年回顧展', '藝術家王美玥老師於1994年到1995年間開創「洗墨法」，結合宣紙與描圖紙，創作水波紋畫，顛覆傳統繪畫理念，為現代水墨寫下歷史新頁。\r\n本次展出抑是40年載的創作回顧，「天上人間」指的是創作心境，此系列多為近三年新作，總共分為五大主軸: 1.意象水墨2.行雲水墨3.百年思索4.時光彼岸5.自由的風。隨著人生閱歷增廣，繪畫技巧更臻純熟，作品題材也融入更多元素及議題關注，讓作品再創新局。作品媒材分水墨、水波紋畫與油畫三大類，藉由自然景物延伸心靈哲思、探源歷史與文學透視，演繹當代藝術，透過特殊風格的作品，創新思維並提純美學，從心靈哲思到生命回歸，從傳統水墨到當代藝術，可以窺見作者於不同時期的心境轉換，以及風格、技巧之革新；象由心生，以人文角度關注人生，希望藉由此展，回顧歷史也前瞻未來。', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-02-28 00:00:00', '2025-03-23 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=07ed91dc5feb49d9a52822b991600764', '[]') ON DUPLICATE KEY UPDATE `activity_name`='天上人間-王美玥創作40年回顧展', `description`='藝術家王美玥老師於1994年到1995年間開創「洗墨法」，結合宣紙與描圖紙，創作水波紋畫，顛覆傳統繪畫理念，為現代水墨寫下歷史新頁。\r\n本次展出抑是40年載的創作回顧，「天上人間」指的是創作心境，此系列多為近三年新作，總共分為五大主軸: 1.意象水墨2.行雲水墨3.百年思索4.時光彼岸5.自由的風。隨著人生閱歷增廣，繪畫技巧更臻純熟，作品題材也融入更多元素及議題關注，讓作品再創新局。作品媒材分水墨、水波紋畫與油畫三大類，藉由自然景物延伸心靈哲思、探源歷史與文學透視，演繹當代藝術，透過特殊風格的作品，創新思維並提純美學，從心靈哲思到生命回歸，從傳統水墨到當代藝術，可以窺見作者於不同時期的心境轉換，以及風格、技巧之革新；象由心生，以人文角度關注人生，希望藉由此展，回顧歷史也前瞻未來。', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=07ed91dc5feb49d9a52822b991600764', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4ff626b32408680beb56', '藝次元-王瑋名數位藝術個展 ', 'AI時代來臨，藝術也掀起一波新面向與風潮，而這股力量正全方位衝擊整個世代的改革。機器人時代勢必提前一世紀進入人類家庭，全新世代的人類亦將在未來20年內有令人意想不到的生活方式與藝術發展。\r\n\r\n王瑋名數位藝術個展，展出的作品包含VR、數位影像、3D動畫、數位3D木雕及AI數位作品。全方位探討與解析數位藝術未來的發展面向。而這次主題《藝次元》即在表達藝術的不同維度，有別傳統藝術的油畫、水墨…等平面視覺藝術。\r\n\r\n王瑋名數位影像藝術近年屢獲國際藝術大獎，作品《檑枷》數位影像作品前後獲：2024米蘭Milan Gold Awards實驗片金獎、倫敦London Movie Awards實驗片金獎、2023巴黎Paris Film Awards Certificate動畫片銀獎、2023倫羅倫斯電影節實驗片銀獎，也將會在現場展出，歡迎有興趣的民眾蒞臨參觀。', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-03-08 00:00:00', '2025-04-06 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=1a8d23ea6f444cd2a4188c89bb46361c', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝次元-王瑋名數位藝術個展 ', `description`='AI時代來臨，藝術也掀起一波新面向與風潮，而這股力量正全方位衝擊整個世代的改革。機器人時代勢必提前一世紀進入人類家庭，全新世代的人類亦將在未來20年內有令人意想不到的生活方式與藝術發展。\r\n\r\n王瑋名數位藝術個展，展出的作品包含VR、數位影像、3D動畫、數位3D木雕及AI數位作品。全方位探討與解析數位藝術未來的發展面向。而這次主題《藝次元》即在表達藝術的不同維度，有別傳統藝術的油畫、水墨…等平面視覺藝術。\r\n\r\n王瑋名數位影像藝術近年屢獲國際藝術大獎，作品《檑枷》數位影像作品前後獲：2024米蘭Milan Gold Awards實驗片金獎、倫敦London Movie Awards實驗片金獎、2023巴黎Paris Film Awards Certificate動畫片銀獎、2023倫羅倫斯電影節實驗片銀獎，也將會在現場展出，歡迎有興趣的民眾蒞臨參觀。', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=1a8d23ea6f444cd2a4188c89bb46361c', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4ff626b32408680beb57', 'DO something_music台中街頭表演組合_吉他彈唱', '街頭藝人證號:A1131117林紫琦(吉他彈奏). A1120261葉柏成(電吉他演奏)\r\n\r\n展演內容:\r\n\r\n1.台中街頭表演組合_吉他彈唱\r\n\r\n2.和現場民眾良好互動', '林紫琦', '臺中市西區英才路600號', '2025-03-16 00:00:00', '2025-03-30 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000704', '[]') ON DUPLICATE KEY UPDATE `activity_name`='DO something_music台中街頭表演組合_吉他彈唱', `description`='街頭藝人證號:A1131117林紫琦(吉他彈奏). A1120261葉柏成(電吉他演奏)\r\n\r\n展演內容:\r\n\r\n1.台中街頭表演組合_吉他彈唱\r\n\r\n2.和現場民眾良好互動', `organizer`='林紫琦', `address`='臺中市西區英才路600號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000704', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4ff726b32408680beb58', '「臺中港中區扶輪社第十三屆學童寫生比賽-得獎作品展」 ', '學童是國家未來的主人翁，更是社會安定的力量，為讓將來每一位青年學子將來可成為國家富強的中堅份子，在其幼兒期、兒童期間需給予充分的多面向訓練，以培養為T型人才，締造每一位學童的斜槓人才。\r\n臺中港中區扶輪社為關懷港區兒童才藝發展，激發學童潛能，將親子活動導入日常生活中，暨培養兒童對寫生才藝之高度興趣，特舉辦學童寫生比賽，本社過去歷屆已舉辦12屆學童寫生比賽，但在2019年因COVID-19疫情的突襲，而停辦有四年之久。等COVID-19疫情過後百業回歸正軌，開始思考如何來恢復舉辦學童寫生比賽。但該項寫生比賽不只勞師動眾，而且所花費也不貲。因此，有些想輕鬆以對的社長就會望之卻步。今年在大多數社友的期盼與夫人支持下重新回來舉辦學童寫生比賽，以此讓兒童們展現他們的美術成就，童心、童趣地觀察生活周邊的人事物表現他們的感覺和想法，並融入了獨特美學的見解。\r\n今年度的學童寫生比賽加入一些創新元素，特別設計了「多才多藝加加樂」、「五花八門減減樂」、「手眼協調夾夾樂」、「膽大心細疊疊樂」等四種益智遊戲，以增加學童寫生比賽現場的豐富性與趣味性，為學童才藝能有多角的發展。', '臺中市中區扶輪社', '臺中市清水區忠貞路21號', '2025-03-15 00:00:00', '2025-04-13 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=b1f6097d7dd3470fbda2da88957cf673', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「臺中港中區扶輪社第十三屆學童寫生比賽-得獎作品展」 ', `description`='學童是國家未來的主人翁，更是社會安定的力量，為讓將來每一位青年學子將來可成為國家富強的中堅份子，在其幼兒期、兒童期間需給予充分的多面向訓練，以培養為T型人才，締造每一位學童的斜槓人才。\r\n臺中港中區扶輪社為關懷港區兒童才藝發展，激發學童潛能，將親子活動導入日常生活中，暨培養兒童對寫生才藝之高度興趣，特舉辦學童寫生比賽，本社過去歷屆已舉辦12屆學童寫生比賽，但在2019年因COVID-19疫情的突襲，而停辦有四年之久。等COVID-19疫情過後百業回歸正軌，開始思考如何來恢復舉辦學童寫生比賽。但該項寫生比賽不只勞師動眾，而且所花費也不貲。因此，有些想輕鬆以對的社長就會望之卻步。今年在大多數社友的期盼與夫人支持下重新回來舉辦學童寫生比賽，以此讓兒童們展現他們的美術成就，童心、童趣地觀察生活周邊的人事物表現他們的感覺和想法，並融入了獨特美學的見解。\r\n今年度的學童寫生比賽加入一些創新元素，特別設計了「多才多藝加加樂」、「五花八門減減樂」、「手眼協調夾夾樂」、「膽大心細疊疊樂」等四種益智遊戲，以增加學童寫生比賽現場的豐富性與趣味性，為學童才藝能有多角的發展。', `organizer`='臺中市中區扶輪社', `address`='臺中市清水區忠貞路21號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=b1f6097d7dd3470fbda2da88957cf673', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4ff726b32408680beb59', '2025臺灣藝術家協會聯展', '臺灣藝術家協會成立迄今約滿25年。創會之初的會員包括了臺灣北中南、東西部各大專院校之教授及中小學教師，另有職業畫家與業餘藝術家等所共同組成。協會自成立以來，曾於國父紀念館、中正紀念堂、臺中市火車站、各個文化中心與文教機構等地，先後舉辦會員聯展數十餘次，亦出版過畫冊4本。\r\n\r\n此次聯展作品包含水墨、書法、水彩、油畫、壓克力彩、複合媒材等媒材，創作風格有寫實、抽象、抒情、想像、清麗、厚重等多樣面貌，會員們作品之創作形式、内容與媒材等風格迥異，而共同不變的是，皆努力從事於書畫教學和創作實踐，致力於彩繪豐富的人生、以涵蘊藝文風氣，提昇美感素養。', '臺灣藝術家協會', '臺中市清水區忠貞路21號', '2025-03-29 00:00:00', '2025-04-20 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=d2b9d4e462b0469e83bd5a6c619180f4', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺灣藝術家協會聯展', `description`='臺灣藝術家協會成立迄今約滿25年。創會之初的會員包括了臺灣北中南、東西部各大專院校之教授及中小學教師，另有職業畫家與業餘藝術家等所共同組成。協會自成立以來，曾於國父紀念館、中正紀念堂、臺中市火車站、各個文化中心與文教機構等地，先後舉辦會員聯展數十餘次，亦出版過畫冊4本。\r\n\r\n此次聯展作品包含水墨、書法、水彩、油畫、壓克力彩、複合媒材等媒材，創作風格有寫實、抽象、抒情、想像、清麗、厚重等多樣面貌，會員們作品之創作形式、内容與媒材等風格迥異，而共同不變的是，皆努力從事於書畫教學和創作實踐，致力於彩繪豐富的人生、以涵蘊藝文風氣，提昇美感素養。', `organizer`='臺灣藝術家協會', `address`='臺中市清水區忠貞路21號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=d2b9d4e462b0469e83bd5a6c619180f4', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4ff826b32408680beb5a', '大道書畫學會聯展', '本次聯展為近年來會員們的精心創作，內容豐富多元，展現書畫藝術的深厚底蘊與創新發展。', '臺中市政府地方稅務局', '臺中市西屯區文心路二段99號', '2025-03-03 00:00:00', '2025-03-28 00:00:00', '臺中市政府地方稅務局', 24.18308895, 120.6270131, '無資料', 'https://www.tax.taichung.gov.tw/4499/5200/5420/35242/normalPost', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大道書畫學會聯展', `description`='本次聯展為近年來會員們的精心創作，內容豐富多元，展現書畫藝術的深厚底蘊與創新發展。', `organizer`='臺中市政府地方稅務局', `address`='臺中市西屯區文心路二段99號', `start_date`='2025-03-03 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='臺中市政府地方稅務局', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://www.tax.taichung.gov.tw/4499/5200/5420/35242/normalPost', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4ff826b32408680beb5b', '做伙說台語活動(3月2場)', '【「多元閱讀繽紛季」做伙說台語活動二場】\r\n台語聽故事、學習母語，增進親子間的情感與溝通！三月，我們準備了兩場精彩的台語故事時間，邀請5~10歲的幼兒及家長一起來參加，快來加入我們的快樂學習旅程吧！\r\n\r\n3月1日（六）INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4ff826b32408680beb5c', '2025海灣故事繪本館「故事種子接接力/週末故事派」(3月份20場)', '[故事種子接接力]\r\n3/1(六)10:30繪本故事:好一個瓜啊!(迷蘺老師)\r\n3/2(日)10:30繪本故事:春天的野餐會(莫莉老師)\r\n3/8(六)10:30繪本故事:會飛的禮物(秀秀老師)\r\n3/9(日)10:30繪本故事:請問一下，採得到底嗎?(葉葉老師)\r\n3/15(六)10:30繪本故事:到烏龜國去(小山老師)\r\n3/16(日)10:30繪本故事:誰是第一名(Nana老師)\r\n3/22(六)10:30繪本故事:賽米希的煩惱(雲朵老師)\r\n3/23(日)10:30繪本故事:沒有公雞怎麼辦(小草老師)\r\n3/29(六)10:30繪本故事:愛漂亮的小象芬芬(Lavender老師)\r\n3/30(日)10:30繪本故事:藏在箱子裡的大象、鈴乃的腦袋瓜(嘻哈貝莉、Nana老師)\r\n[週末故事派]\r\n3/1(六)14:00繪本故事:《掉了》(Jolin老師)&手作:熱縮片名牌$200/人\r\n3/2(日)14:00繪本故事:《情緒氣球》(芯語老師)&手作:情緒旋轉盤$200/人\r\n3/8(六)14:00繪本故事:《林桃奶奶的桃子樹》(葉葉老師)&手作:蠟筆彩繪$250/人\r\n3/9(日)14:00繪本故事:《會生氣的山》(魔女琪琪)&活動:兒童花藝-森林之王$350/人\r\n3/15(六)14:00繪本故事:《雨》(小山老師)&手作:油畫布畫字(含木架)$150/人\r\n3/16(日)14:00繪本故事:《老婆婆的種子》(星星老師)&手作:創作壓花書籤$200/人\r\n3/22(六)14:00繪本故事:《蟬鳴森林》(葉葉老師)&手作:療癒粉彩$150/人\r\n3/23(日)14:00繪本故事:《貓房子》(莫莉老師)&手作:貓咪.房子.老奶奶$250/人\r\n3/29(六)14:00繪本故事:《陶樂蒂沒有寵物》(迷蘺老師)&手作:動物襪子娃娃$200/人\r\n3/30(日)14:00繪本故事:《橘色的馬》(Lala老師)&手作:親子創作:sweet home相框作$250/人', '海灣繪本館', '臺中市清水區忠貞路21號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://www.facebook.com/share/p/16FBGnJyB7/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025海灣故事繪本館「故事種子接接力/週末故事派」(3月份20場)', `description`='[故事種子接接力]\r\n3/1(六)10:30繪本故事:好一個瓜啊!(迷蘺老師)\r\n3/2(日)10:30繪本故事:春天的野餐會(莫莉老師)\r\n3/8(六)10:30繪本故事:會飛的禮物(秀秀老師)\r\n3/9(日)10:30繪本故事:請問一下，採得到底嗎?(葉葉老師)\r\n3/15(六)10:30繪本故事:到烏龜國去(小山老師)\r\n3/16(日)10:30繪本故事:誰是第一名(Nana老師)