INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4ffa26b32408680beb64', '英語故事時間(3月2場)', '英語故事時間 \r\n愛聽英語故事的小朋友和家長們，三月我們為你準備了兩場充滿趣味的英語繪本故事活動！這次的活動特別適合5到10歲的幼兒及家長，專業老師將用生動有趣的方式演繹故事，並結合親子互動遊戲，讓學習更加輕鬆和有趣！快來一起享受故事的魔力吧！\r\n3月2日（日）INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf4ffa26b32408680beb65', '臺語冊．講乎咱聽', '以台語歌謠為主題，展出相關台語、音樂書籍，讓母語透過書本語文字融入日常生活。\r\n', '臺中市立圖書館豐原分館', '臺中市豐原區育仁路81號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館豐原分館', 24.24990298, 120.7375715, '無資料', 'https://reurl.cc/V09g9n', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺語冊．講乎咱聽', `description`='以台語歌謠為主題，展出相關台語、音樂書籍，讓母語透過書本語文字融入日常生活。\r\n', `organizer`='臺中市立圖書館豐原分館', `address`='臺中市豐原區育仁路81號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館豐原分館', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://reurl.cc/V09g9n', `image_url`='[]';
