INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf500626b32408680beb73', '【現場導覽】「花影橫斜」沈東榮2025個展', '時序的花語形像落於油畫畫布中，繁櫻紛飛、黃金如雨阿勃勒、荷塘亭亭、如蝶野薑花，都是自然生命美好的靜觀收藏，緩緩描繪下它的細節姿態，那段對語的過程，無待且沈靜。花影橫斜，歲月無言。畫家得幸參與其中，且觀得這一季美好。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000874', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【現場導覽】「花影橫斜」沈東榮2025個展', `description`='時序的花語形像落於油畫畫布中，繁櫻紛飛、黃金如雨阿勃勒、荷塘亭亭、如蝶野薑花，都是自然生命美好的靜觀收藏，緩緩描繪下它的細節姿態，那段對語的過程，無待且沈靜。花影橫斜，歲月無言。畫家得幸參與其中，且觀得這一季美好。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000874', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf500726b32408680beb74', '2025年神韻臺灣巡迴演出', '神韻以藝術的形式復興華夏五千年的正統文化。\r\n神韻演出包括約20個節目，從漢唐盛世到明清宮廷，從江南美景到西北高原，舞蹈和舞劇節目的場景設置涵蓋神州每一處土地、每一段時光。節目中也展現了各式各樣的人物，從端莊秀美的仕女到馳騁沙場的大將，從仙風道骨的道教祖師到嬉笑怒罵的市井小民，個個都栩栩如生。節目中更描繪了現代中國社會堅持信仰的一群人，他們雖然遭受迫害，卻依然堅貞不屈，他們的故事催人淚下、感人至深。', '社團法人臺灣法輪大法學會', '基隆市中正區信一路181號', '2025-03-20 00:00:00', '2025-03-20 00:00:00', '基隆文化中心', 25.1314199, 121.7437065, '全票+2600;全票+3000;全票+3500;全票+4000;全票+5000', 'ShenYun.com', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年神韻臺灣巡迴演出', `description`='神韻以藝術的形式復興華夏五千年的正統文化。\r\n神韻演出包括約20個節目，從漢唐盛世到明清宮廷，從江南美景到西北高原，舞蹈和舞劇節目的場景設置涵蓋神州每一處土地、每一段時光。節目中也展現了各式各樣的人物，從端莊秀美的仕女到馳騁沙場的大將，從仙風道骨的道教祖師到嬉笑怒罵的市井小民，個個都栩栩如生。節目中更描繪了現代中國社會堅持信仰的一群人，他們雖然遭受迫害，卻依然堅貞不屈，他們的故事催人淚下、感人至深。', `organizer`='社團法人臺灣法輪大法學會', `address`='基隆市中正區信一路181號', `start_date`='2025-03-20 00:00:00', `end_date`='2025-03-20 00:00:00', `location`='基隆文化中心', `latitude`=25.1314199, `longitude`=121.7437065, `ticket_price`='全票+2600;全票+3000;全票+3500;全票+4000;全票+5000', `source_url`='ShenYun.com', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf500726b32408680beb75', '午後電影院(3月2場)', '3/12 熊出沒，伴我熊芯\r\n3/26 功夫熊貓2', '臺中市立圖書館龍井分館', '臺中市龍井區觀光路2號', '2025-03-12 00:00:00', '2025-03-26 00:00:00', '臺中市立圖書館龍井分館', 24.20062892, 120.5283728, '無資料', 'https://reurl.cc/04L8Ql', '[]') ON DUPLICATE KEY UPDATE `activity_name`='午後電影院(3月2場)', `description`='3/12 熊出沒，伴我熊芯\r\n3/26 功夫熊貓2', `organizer`='臺中市立圖書館龍井分館', `address`='臺中市龍井區觀光路2號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺中市立圖書館龍井分館', `latitude`=24.20062892, `longitude`=120.5283728, `ticket_price`='無資料', `source_url`='https://reurl.cc/04L8Ql', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf500726b32408680beb76', '張卉青創作個展-禪繞景泰藍', '●作品內容 : 花瓶系列\r\n●展覽介紹\r\n禪繞畫是新穎靈動又平易近人的新興畫派，在線條和幾何圖形重複的繪圖過程中，可感受到專注平靜與放鬆，卉青老師愛上這種感覺，對禪繞藝術深深著迷，傾心於創作與教學之中。\r\n一般禪繞畫作品尺寸較小巧， 然而卉青老師以獨有的創意將作品的畫心擴大至80x50cm。 超大尺寸的創作構圖極具巧思，繪圖更需功力，耐力與專注力。\r\n本次於臺中市立圖書館龍井分館舉辦的”張卉青創作個展~禪繞景泰藍”是卉青老師的第23場的創作個展，本次展出以花瓶為主題的禪繞藝術作品，利用獨特禪繞繪畫技法，將景泰藍、青花瓷、多種顏色與各種型態的花瓶樣貌呈現禪繞畫中，帶領大家進入另類禪繞藝術的美麗境界，歡迎各位民眾蒞臨參觀。', '臺中市立圖書館龍井分館', '臺中市龍井區觀光路2號', '2025-03-02 00:00:00', '2025-03-29 00:00:00', '臺中市立圖書館龍井分館', 24.20062892, 120.5283728, '無資料', 'https://reurl.cc/04L8Ql', '[]') ON DUPLICATE KEY UPDATE `activity_name`='張卉青創作個展-禪繞景泰藍', `description`='●作品內容 : 花瓶系列\r\n●展覽介紹\r\n禪繞畫是新穎靈動又平易近人的新興畫派，在線條和幾何圖形重複的繪圖過程中，可感受到專注平靜與放鬆，卉青老師愛上這種感覺，對禪繞藝術深深著迷，傾心於創作與教學之中。\r\n一般禪繞畫作品尺寸較小巧， 然而卉青老師以獨有的創意將作品的畫心擴大至80x50cm。 超大尺寸的創作構圖極具巧思，繪圖更需功力，耐力與專注力。\r\n本次於臺中市立圖書館龍井分館舉辦的”張卉青創作個展~禪繞景泰藍”是卉青老師的第23場的創作個展，本次展出以花瓶為主題的禪繞藝術作品，利用獨特禪繞繪畫技法，將景泰藍、青花瓷、多種顏色與各種型態的花瓶樣貌呈現禪繞畫中，帶領大家進入另類禪繞藝術的美麗境界，歡迎各位民眾蒞臨參觀。', `organizer`='臺中市立圖書館龍井分館', `address`='臺中市龍井區觀光路2號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市立圖書館龍井分館', `latitude`=24.20062892, `longitude`=120.5283728, `ticket_price`='無資料', `source_url`='https://reurl.cc/04L8Ql', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf500826b32408680beb77', 'FUN心聽故事－故事百匯/故事達人(旗津分館4月)', 'FUN心聽故事－故事百匯/故事達人\r\n為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」故事志工，至各分館說繪本故事。', '高雄市立圖書館總館', '高雄市旗津區中洲三路528號', '2025-04-05 00:00:00', '2025-04-27 00:00:00', '高雄市立圖書館旗津分館', 22.561674, 120.306998, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽故事－故事百匯/故事達人(旗津分館4月)', `description`='FUN心聽故事－故事百匯/故事達人\r\n為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」故事志工，至各分館說繪本故事。', `organizer`='高雄市立圖書館總館', `address`='高雄市旗津區中洲三路528號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='高雄市立圖書館旗津分館', `latitude`=22.561674, `longitude`=120.306998, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf500826b32408680beb78', 'SDGS性別平等主題書展', '本館藉由辦理之『主題書展』，使到館民眾進一步認識館藏資源。所展示的主題書籍及相關延伸作品，都能使讀者徜徉在書海中，進一步領略閱讀之美、享受閱讀樂趣，亦能提升視野。\r\n', '高雄市立圖書館總館', '高雄市旗津區中洲三路528號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '高雄市立圖書館旗津分館', 22.561674, 120.306998, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='SDGS性別平等主題書展', `description`='本館藉由辦理之『主題書展』，使到館民眾進一步認識館藏資源。所展示的主題書籍及相關延伸作品，都能使讀者徜徉在書海中，進一步領略閱讀之美、享受閱讀樂趣，亦能提升視野。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市旗津區中洲三路528號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市立圖書館旗津分館', `latitude`=22.561674, `longitude`=120.306998, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cf500826b32408680beb79', '2025年神韻臺灣巡迴演出', '神韻以藝術的形式復興華夏五千年的正統文化。\r\n神韻演出包括約20個節目，從漢唐盛世到明清宮廷，從江南美景到西北高原，舞蹈和舞劇節目的場景設置涵蓋神州每一處土地、每一段時光。節目中也展現了各式各樣的人物，從端莊秀美的仕女到馳騁沙場的大將，從仙風道骨的道教祖師到嬉笑怒罵的市井小民，個個都栩栩如生。節目中更描繪了現代中國社會堅持信仰的一群人，他們雖然遭受迫害，卻依然堅貞不屈，他們的故事催人淚下、感人至深。', '社團法人臺灣法輪大法學會', '基隆市中正區信一路181號', '2025-03-21 00:00:00', '2025-03-21 00:00:00', '基隆文化中心', 25.1314199, 121.7437065, '全票+2600;全票+3000;全票+3500;全票+4000;全票+5000', 'ShenYun.com', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年神韻臺灣巡迴演出', `description`='神韻以藝術的形式復興華夏五千年的正統文化。\r\n神韻演出包括約20個節目，從漢唐盛世到明清宮廷，從江南美景到西北高原，舞蹈和舞劇節目的場景設置涵蓋神州每一處土地、每一段時光。節目中也展現了各式各樣的人物，從端莊秀美的仕女到馳騁沙場的大將，從仙風道骨的道教祖師到嬉笑怒罵的市井小民，個個都栩栩如生。節目中更描繪了現代中國社會堅持信仰的一群人，他們雖然遭受迫害，卻依然堅貞不屈，他們的故事催人淚下、感人至深。', `organizer`='社團法人臺灣法輪大法學會', `address`='基隆市中正區信一路181號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='基隆文化中心', `latitude`=25.1314199, `longitude`=121.7437065, `ticket_price`='全票+2600;全票+3000;全票+3500;全票+4000;全票+5000', `source_url`='ShenYun.com', `image_url`='[]';
