INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fb226b32408680beb96', '臺中市藝術亮點-2025花廳X京劇：貴妃醉酒', '活動邀請國光劇團旦角名家劉珈后老師，演譯梅派經典《貴妃醉酒》，一場精心準備的宮廷盛宴，換來獨飲悵然的落寞與傷感。\r\n透過細膩的情感詮釋與優雅精湛的身段技巧，帶領觀眾走入楊貴妃的醉夢人生，感受京劇藝術的極致之美。', '霧峰林家宮保第園區', '臺中市霧峰區民生路26號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '霧峰林家宮保第園區', 24.04332785, 120.7201989, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-2025花廳X京劇：貴妃醉酒', `description`='活動邀請國光劇團旦角名家劉珈后老師，演譯梅派經典《貴妃醉酒》，一場精心準備的宮廷盛宴，換來獨飲悵然的落寞與傷感。\r\n透過細膩的情感詮釋與優雅精湛的身段技巧，帶領觀眾走入楊貴妃的醉夢人生，感受京劇藝術的極致之美。', `organizer`='霧峰林家宮保第園區', `address`='臺中市霧峰區民生路26號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='霧峰林家宮保第園區', `latitude`=24.04332785, `longitude`=120.7201989, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fb326b32408680beb97', '心相：洪鈺富個展', '台灣身心障礙藝術發展協會2025年首檔展覽，特邀藝術家洪鈺富，以近二十餘件自2012年以來的經典作品，呈現他十年間的心境轉變，並為春天揭開藝術的序幕。\r\n洪鈺富自2012年首次參與光之藝廊徵件比賽後，連續三度榮獲光之藝廊創作獎，並獲得國內多項藝術獎項的肯定，作品更巡展至日本等國。自幼熱愛繪畫的他，在國中一年級時罹患重病，導致身體右半側近乎癱瘓，只能依靠左側行動，視力與語言功能也大受影響，並伴隨癲癇發作。然而，即便只能以顫抖的左手勾勒不穩定的線條，他仍將這份限制化為獨特的創作風格，超越身體的束縛，展現驚人的生命力。\r\n本次展覽以「心相」為名，正如鈺富的創作—純粹且無雜念的心靈映照。他將情緒、思想、夢境與夢想轉化為具象的線條與色塊，在畫布上層層疊染出內心世界的波瀾。其早期作品多以「惡魔」為主題，夢魘、地獄與怪物的形象往往讓觀者感到震撼，然而，這些畫面實則映照了他經歷身體變故後的內心掙扎與磨難，透過藝術抒發無法言說的情感。\r\n《錯不在我》是洪鈺富於2012年參與光之藝廊創作獎時的得獎作品，畫面中數隻黑色的手指向中央的人物，象徵現實生活中因身障而遭受異樣眼光的他，內心的自卑與脆弱躍然紙上。近年來，受到父親的影響，他開始創作觀世音、三太子等佛道宗教題材，儘管對佛法理解不深，卻在描繪佛像的過程中獲得心靈上的安定。同時，在繪畫老師的引導下，他逐漸拓展創作主題，不再排斥風景、動物等較為大眾熟悉的題材，並融入自身獨特的詮釋方式，使作品色調比以往更加明亮飽滿，充分展現他心境的轉變與日漸堅定的自信。\r\n本次展覽共展出22件歷年作品，透過創作主題與色彩變化，映照鈺富的心理成長歷程，邀請觀者一同見證他以畫筆自我療癒的過程，並在作品中感受那份非凡的生命力。', '無資料', '臺中市西區美村路一段492號', '2025-03-15 00:00:00', '2025-05-03 00:00:00', '光之藝廊', 24.14391082, 120.6647579, '無資料', 'https://www.lumin-art.org.tw/?p=6453', '[]') ON DUPLICATE KEY UPDATE `activity_name`='心相：洪鈺富個展', `description`='台灣身心障礙藝術發展協會2025年首檔展覽，特邀藝術家洪鈺富，以近二十餘件自2012年以來的經典作品，呈現他十年間的心境轉變，並為春天揭開藝術的序幕。\r\n洪鈺富自2012年首次參與光之藝廊徵件比賽後，連續三度榮獲光之藝廊創作獎，並獲得國內多項藝術獎項的肯定，作品更巡展至日本等國。自幼熱愛繪畫的他，在國中一年級時罹患重病，導致身體右半側近乎癱瘓，只能依靠左側行動，視力與語言功能也大受影響，並伴隨癲癇發作。然而，即便只能以顫抖的左手勾勒不穩定的線條，他仍將這份限制化為獨特的創作風格，超越身體的束縛，展現驚人的生命力。\r\n本次展覽以「心相」為名，正如鈺富的創作—純粹且無雜念的心靈映照。他將情緒、思想、夢境與夢想轉化為具象的線條與色塊，在畫布上層層疊染出內心世界的波瀾。其早期作品多以「惡魔」為主題，夢魘、地獄與怪物的形象往往讓觀者感到震撼，然而，這些畫面實則映照了他經歷身體變故後的內心掙扎與磨難，透過藝術抒發無法言說的情感。\r\n《錯不在我》是洪鈺富於2012年參與光之藝廊創作獎時的得獎作品，畫面中數隻黑色的手指向中央的人物，象徵現實生活中因身障而遭受異樣眼光的他，內心的自卑與脆弱躍然紙上。近年來，受到父親的影響，他開始創作觀世音、三太子等佛道宗教題材，儘管對佛法理解不深，卻在描繪佛像的過程中獲得心靈上的安定。同時，在繪畫老師的引導下，他逐漸拓展創作主題，不再排斥風景、動物等較為大眾熟悉的題材，並融入自身獨特的詮釋方式，使作品色調比以往更加明亮飽滿，充分展現他心境的轉變與日漸堅定的自信。\r\n本次展覽共展出22件歷年作品，透過創作主題與色彩變化，映照鈺富的心理成長歷程，邀請觀者一同見證他以畫筆自我療癒的過程，並在作品中感受那份非凡的生命力。', `organizer`='無資料', `address`='臺中市西區美村路一段492號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='光之藝廊', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.lumin-art.org.tw/?p=6453', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fb426b32408680beb98', '藍染時光-三峽的歷史織影 特展', '藍染時光-三峽的歷史織影\r\n114/2/28-4/27\r\n臺中市纖維工藝博物館 1A 展廳\r\n\r\n策展人：王淑宜、陳建維。\r\n參展者：\r\n王淑宜、吳珮慈、杜佳欣、林美麗、張瑋婷、章麗君、陳明理、陳昭蓉、陳瑞美、陳淑真、曾玉鈴、黃淑女、廖寶桂、劉美鈴、劉月瑩、蘇正芳\r\n\r\n為深化本館與全臺各天然染色工藝專業團隊之連結，打造交流發展之平臺，本館特別策劃「天然染✕地方力―臺灣天然染色地方創生故事」系列特展。首場邀請新北市三峽區三角湧文化協進會舉辦「藍染時光―三峽的歷史織影」，以藍峽客大襟衫、藍色洋裝、藍潮西服、夜三峽寢具及藍染龍柱等展區，展現三峽藍染工藝及地方創生的故事。本館也配合展出館藏藍染洋裝作品，期待不同領域的天然染色工藝師和地方團隊在此對話交流，持續激盪出更精采豐富的發展。\r\n\r\n藍峽客大襟衫區：\r\n展示以藍染及薯榔染技術製作的清代漢服和「藍峽客」計畫的代表一一大襟衫。展現漢人服飾的樸實之美。配合歷史背景的文字和圖片資料，參觀者可瞭解清朝激人的服飾特色與生活方式，感受藍染技藝在該時代的文化意義。\r\n\r\n藍潮西服區：\r\n本展區展示以藍染為主色調的西服服飾，展現日治時期西化潮流對服飾的影響。透過展品與背景介紹，參觀者可瞭解當時三峽文化的變遷，以及西方風尚如何融入傳統，開啟一段東西交融的時代風華。\r\n\r\n藍色洋裝區：\r\n本展區展示以藍染技術製作的小洋裝(藍色小洋裝)及大人的洋裝，展現民國時期服飾風格的演變。透過展品與背景介紹，參觀者可一窺民國時代的時尚潮流與三峽居民的生活面貌，感受藍染如何融入現代服飾的設計中。\r\n\r\n夜三峽寢具區：\r\n三峽染工坊的藍染老師們以藍染床包組為設計主題，包括枕套、抱枕套、床包和被套等形式多元的創意作品，展現三峽藍染結合傳統技藝與當代生活，透過模擬「夜晚臥室」的場景，參觀者可直觀感受藍染寢具的實用性與美學價值，體驗藍染如何融入日常，為生活增添美的氛圍。\r\n\r\n主辦單位：臺中市政府文化局\r\n執行單位：臺中市纖維工藝博物館\r\n策展單位：新北市三峽區三角湧文化協進會・三峽染工坊', '臺中市政府文化局', '臺中市大里區勝利二路1號', '2025-02-28 00:00:00', '2025-04-27 00:00:00', '臺中市纖維工藝博物館', 24.09575742, 120.6926261, '無資料', 'https://mofia.taichung.gov.tw/Exhibit/124', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藍染時光-三峽的歷史織影 特展', `description`='藍染時光-三峽的歷史織影\r\n114/2/28-4/27\r\n臺中市纖維工藝博物館 1A 展廳\r\n\r\n策展人：王淑宜、陳建維。\r\n參展者：\r\n王淑宜、吳珮慈、杜佳欣、林美麗、張瑋婷、章麗君、陳明理、陳昭蓉、陳瑞美、陳淑真、曾玉鈴、黃淑女、廖寶桂、劉美鈴、劉月瑩、蘇正芳\r\n\r\n為深化本館與全臺各天然染色工藝專業團隊之連結，打造交流發展之平臺，本館特別策劃「天然染✕地方力―臺灣天然染色地方創生故事」系列特展。首場邀請新北市三峽區三角湧文化協進會舉辦「藍染時光―三峽的歷史織影」，以藍峽客大襟衫、藍色洋裝、藍潮西服、夜三峽寢具及藍染龍柱等展區，展現三峽藍染工藝及地方創生的故事。本館也配合展出館藏藍染洋裝作品，期待不同領域的天然染色工藝師和地方團隊在此對話交流，持續激盪出更精采豐富的發展。\r\n\r\n藍峽客大襟衫區：\r\n展示以藍染及薯榔染技術製作的清代漢服和「藍峽客」計畫的代表一一大襟衫。展現漢人服飾的樸實之美。配合歷史背景的文字和圖片資料，參觀者可瞭解清朝激人的服飾特色與生活方式，感受藍染技藝在該時代的文化意義。\r\n\r\n藍潮西服區：\r\n本展區展示以藍染為主色調的西服服飾，展現日治時期西化潮流對服飾的影響。透過展品與背景介紹，參觀者可瞭解當時三峽文化的變遷，以及西方風尚如何融入傳統，開啟一段東西交融的時代風華。\r\n\r\n藍色洋裝區：\r\n本展區展示以藍染技術製作的小洋裝(藍色小洋裝)及大人的洋裝，展現民國時期服飾風格的演變。透過展品與背景介紹，參觀者可一窺民國時代的時尚潮流與三峽居民的生活面貌，感受藍染如何融入現代服飾的設計中。\r\n\r\n夜三峽寢具區：\r\n三峽染工坊的藍染老師們以藍染床包組為設計主題，包括枕套、抱枕套、床包和被套等形式多元的創意作品，展現三峽藍染結合傳統技藝與當代生活，透過模擬「夜晚臥室」的場景，參觀者可直觀感受藍染寢具的實用性與美學價值，體驗藍染如何融入日常，為生活增添美的氛圍。\r\n\r\n主辦單位：臺中市政府文化局\r\n執行單位：臺中市纖維工藝博物館\r\n策展單位：新北市三峽區三角湧文化協進會・三峽染工坊', `organizer`='臺中市政府文化局', `address`='臺中市大里區勝利二路1號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺中市纖維工藝博物館', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://mofia.taichung.gov.tw/Exhibit/124', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fb626b32408680beb99', 'Chiu Yueh Garden | 秋月園', '世上沒有一種美能取悅所有人，但我們能讓每棵樹擁有它的性格。 INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fb626b32408680beb9a', '日本江戶至明治之漆器展(四)-天皇與諸雄', '日本江戶至明治之漆器展(四)-天皇與諸雄\r\n展期：2／22－3／23\r\n時間：週二至週日13:00 - 21:00\r\n極致奢華的時代瑰寶！\r\n穿越時空，步入日本皇室與武將的輝煌世界！本次展覽匯聚江戶至明治時期無比珍貴的漆器寶物，這些曾經專屬於天皇、德川將軍與戰國名將的御用品，如今近距離呈現在您眼前！\r\n從金碧輝煌的酒器、氣勢恢宏的禮器，到極盡奢華的珠寶箱、典雅精緻的文具，每一件皆是工藝巔峰之作，巧奪天工，絕無僅有！蒔繪、螺鈿、金銀箔裝飾，每道工序皆耗費匠人畢生心血，造就歷史上最華美的藝術珍品！\r\n這不僅是一場視覺與文化的饗宴，更是一次直擊日本權貴審美極限的機會。這些跨越時代的藝術品，將帶您感受古代權貴的奢華生活與無與倫比的匠藝魅力。如此難得一見的極品展覽，豈能錯過？\r\n\r\n#日本漆器  #聯展', '臺中市鶴軒藝術', '臺中市西屯區惠來路二段90號1~3F、18F', '2025-02-22 00:00:00', '2025-03-23 00:00:00', '鶴軒藝術(歌劇店)', 24.18308895, 120.6270131, '無資料', 'https://reurl.cc/Eg3vDA', '[]') ON DUPLICATE KEY UPDATE `activity_name`='日本江戶至明治之漆器展(四)-天皇與諸雄', `description`='日本江戶至明治之漆器展(四)-天皇與諸雄\r\n展期：2／22－3／23\r\n時間：週二至週日13:00 - 21:00\r\n極致奢華的時代瑰寶！\r\n穿越時空，步入日本皇室與武將的輝煌世界！本次展覽匯聚江戶至明治時期無比珍貴的漆器寶物，這些曾經專屬於天皇、德川將軍與戰國名將的御用品，如今近距離呈現在您眼前！\r\n從金碧輝煌的酒器、氣勢恢宏的禮器，到極盡奢華的珠寶箱、典雅精緻的文具，每一件皆是工藝巔峰之作，巧奪天工，絕無僅有！蒔繪、螺鈿、金銀箔裝飾，每道工序皆耗費匠人畢生心血，造就歷史上最華美的藝術珍品！\r\n這不僅是一場視覺與文化的饗宴，更是一次直擊日本權貴審美極限的機會。這些跨越時代的藝術品，將帶您感受古代權貴的奢華生活與無與倫比的匠藝魅力。如此難得一見的極品展覽，豈能錯過？\r\n\r\n#日本漆器  #聯展', `organizer`='臺中市鶴軒藝術', `address`='臺中市西屯區惠來路二段90號1~3F、18F', `start_date`='2025-02-22 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='鶴軒藝術(歌劇店)', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://reurl.cc/Eg3vDA', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fb626b32408680beb9b', '《享受吧！一個人的旅行》電影放映', '電影放映：改編自伊莉莎白吉兒伯特暢銷全球七百多萬本的同名小說，劇情描述莉茲擁有全世界女人想要的一切：老公、事業和房子，但富有的她依然覺得內心失落。之後，離婚的打擊讓她面臨了人生的十字路口，於是她決定拋開一切，上路展開心靈追尋之旅。 \r\n\r\n在週五的晚上，誠品書店邀請您加入好讀俱樂部，共享人文時光！ 活動免費參加，數量有限，請有興趣的民眾洽詢報名！', '誠品書店', '臺中市西屯區', '2025-03-28 00:00:00', '2025-03-28 00:00:00', '西屯區（臺中市）=', 24.18308895, 120.6270131, '無資料', 'https://meet.eslite.com/tw/tc/artshow/202502250003', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《享受吧！一個人的旅行》電影放映', `description`='電影放映：改編自伊莉莎白吉兒伯特暢銷全球七百多萬本的同名小說，劇情描述莉茲擁有全世界女人想要的一切：老公、事業和房子，但富有的她依然覺得內心失落。之後，離婚的打擊讓她面臨了人生的十字路口，於是她決定拋開一切，上路展開心靈追尋之旅。 \r\n\r\n在週五的晚上，誠品書店邀請您加入好讀俱樂部，共享人文時光！ 活動免費參加，數量有限，請有興趣的民眾洽詢報名！', `organizer`='誠品書店', `address`='臺中市西屯區', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='西屯區（臺中市）=', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://meet.eslite.com/tw/tc/artshow/202502250003', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fb926b32408680beb9c', '黃秀寧 竹籐編藝術特展', '黃老師以竹編為主體，配合傳統刺繡、中國結、拼布縫紉，讓竹籐編織走出實用物品的限制框架，進入高境界的藝術領域。\r\n\r\n大型作品「收成」以一顆竹編的大南瓜為主題，配上一根彎曲延伸的孟宗竹老根，用薄竹片組成栩栩如生的南瓜花，鱔魚編織法編成的竹蜻蜓，最後加上以竹根精雕細琢而成的黑紅螞蟻，都是黃老師以桂竹、籐心、籐皮彎折細編而成，作品耗費一整年才完成。', '臺中市葫蘆墩文化中心', '臺中市豐原區圓環東路782號', '2025-03-07 00:00:00', '2025-05-11 00:00:00', '臺中市葫蘆墩文化中心', 24.24990298, 120.7375715, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144528,99,,,2', '[]') ON DUPLICATE KEY UPDATE `activity_name`='黃秀寧 竹籐編藝術特展', `description`='黃老師以竹編為主體，配合傳統刺繡、中國結、拼布縫紉，讓竹籐編織走出實用物品的限制框架，進入高境界的藝術領域。\r\n\r\n大型作品「收成」以一顆竹編的大南瓜為主題，配上一根彎曲延伸的孟宗竹老根，用薄竹片組成栩栩如生的南瓜花，鱔魚編織法編成的竹蜻蜓，最後加上以竹根精雕細琢而成的黑紅螞蟻，都是黃老師以桂竹、籐心、籐皮彎折細編而成，作品耗費一整年才完成。', `organizer`='臺中市葫蘆墩文化中心', `address`='臺中市豐原區圓環東路782號', `start_date`='2025-03-07 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='臺中市葫蘆墩文化中心', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144528,99,,,2', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fba26b32408680beb9d', '[母語新聲．世代共鳴] 台語說故事培訓課程（4場）', '一 、台語故事的無限可能~趣味延伸活動設計\r\n時間：3/8(六)14:00-16:00\r\n講師：李芮楹\r\n講師簡介：教育部閩南語語言能力認證考試中高級合格；現為頭家國小本土語文教師\r\n\r\n二 、走進繪本的台語世界：發現故事的美\r\n時間：3/15(六)14:00-16:00\r\n講師：陳芊榕\r\n講師簡介：教育部閩南語語言能力認證考試中高級合格；《神奇漢藥房：規年迵天照顧咱的健康》作者、繪者\r\n\r\n三、 台語故事新玩法：創意說故事的技巧\r\n時間：3/22(六)14:00-16:00\r\n講師：連惠宜\r\n講師簡介：現為台中市台中故事協會監事\r\n台語演出經驗:\r\n111、112年:屯區、港區藝文中心—大里Darling ,連篇歌集台語音樂劇\r\n113年6月:國台交演奏廳—台語講古音樂會 , 管樂故事島:邁向和諧的奇幻樂章\r\n113年11月:港區清水眷村文化園區好有藝思節：台語戲劇-阿嬤的收音機\r\n\r\n四、 輕鬆說台語：讓故事更動人\r\n時間：3/29(六)14:00-16:00\r\n講師：賈玉玲\r\n講師簡介：教育部閩南語語言能力認證考試中高級合格；現為頭家國小本土語文教師', '臺中市立圖書館總館', '臺中市北屯區豐樂路二段158號', '2025-03-08 00:00:00', '2025-03-29 00:00:00', '臺中市立圖書館總館', 24.18400298, 120.7362319, '無資料', 'https://reurl.cc/46Z6rY', '[]') ON DUPLICATE KEY UPDATE `activity_name`='[母語新聲．世代共鳴] 台語說故事培訓課程（4場）', `description`='一 、台語故事的無限可能~趣味延伸活動設計\r\n時間：3/8(六)14:00-16:00\r\n講師：李芮楹\r\n講師簡介：教育部閩南語語言能力認證考試中高級合格；現為頭家國小本土語文教師\r\n\r\n二 、走進繪本的台語世界：發現故事的美\r\n時間：3/15(六)14:00-16:00\r\n講師：陳芊榕\r\n講師簡介：教育部閩南語語言能力認證考試中高級合格；《神奇漢藥房：規年迵天照顧咱的健康》作者、繪者\r\n\r\n三、 台語故事新玩法：創意說故事的技巧\r\n時間：3/22(六)14:00-16:00\r\n講師：連惠宜\r\n講師簡介：現為台中市台中故事協會監事\r\n台語演出經驗:\r\n111、112年:屯區、港區藝文中心—大里Darling ,連篇歌集台語音樂劇\r\n113年6月:國台交演奏廳—台語講古音樂會 , 管樂故事島:邁向和諧的奇幻樂章\r\n113年11月:港區清水眷村文化園區好有藝思節：台語戲劇-阿嬤的收音機\r\n\r\n四、 輕鬆說台語：讓故事更動人\r\n時間：3/29(六)14:00-16:00\r\n講師：賈玉玲\r\n講師簡介：教育部閩南語語言能力認證考試中高級合格；現為頭家國小本土語文教師', `organizer`='臺中市立圖書館總館', `address`='臺中市北屯區豐樂路二段158號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市立圖書館總館', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://reurl.cc/46Z6rY', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fbb26b32408680beb9e', '臺中市青溪文藝學會會員聯展 創作導覽', '臺中市青溪文藝學會迄今年已邁入第42年，並以提昇美術鑑賞能力、美化人生為宗旨，對於美術的推廣，更是不遺餘力。會員來自各方翹楚，每年均定期舉行會員聯展，並舉辦戶外寫生活動，不論會員素質或作品深度，均有目共睹。這次展出包含石雕、書法、雕塑、西畫、膠彩、攝影、水墨、工藝等精彩作品。', '臺中市葫蘆墩文化中心', '臺中市豐原區圓環東路782號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '臺中市葫蘆墩文化中心', 24.24990298, 120.7375715, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,143659,99', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市青溪文藝學會會員聯展 創作導覽', `description`='臺中市青溪文藝學會迄今年已邁入第42年，並以提昇美術鑑賞能力、美化人生為宗旨，對於美術的推廣，更是不遺餘力。會員來自各方翹楚，每年均定期舉行會員聯展，並舉辦戶外寫生活動，不論會員素質或作品深度，均有目共睹。這次展出包含石雕、書法、雕塑、西畫、膠彩、攝影、水墨、工藝等精彩作品。', `organizer`='臺中市葫蘆墩文化中心', `address`='臺中市豐原區圓環東路782號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市葫蘆墩文化中心', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,143659,99', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fbc26b32408680beb9f', 'Cinema-國立苑裡高中美術班第22屆畢業展', '本展覽以「Cinema」為主題，帶領參觀者穿越時光，回到90年代的台灣。復古的裝飾與電影元素，將學生們的青春歲月與光影故事串聯在一起。展覽中的每一處細節，都承載著對時光的記憶與情感。\r\n青春歲月如一部電影，時而熱血，時而感動，每一幕都刻畫著學生們的追求與努力。三年的歲月如光影閃爍，學生們將走向不同的片場，但這段燦爛的旅程，始終是他們心中最難以忘懷的經典篇章。\r\n展出內容涵蓋水墨、素描、水彩、油畫、版畫、粉彩、壓克力畫、平面設計、裝置藝術等等', '臺中市葫蘆墩文化中心', '臺中市豐原區圓環東路782號', '2025-04-11 00:00:00', '2025-05-04 00:00:00', '臺中市葫蘆墩文化中心', 24.24990298, 120.7375715, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144530,1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Cinema-國立苑裡高中美術班第22屆畢業展', `description`='本展覽以「Cinema」為主題，帶領參觀者穿越時光，回到90年代的台灣。復古的裝飾與電影元素，將學生們的青春歲月與光影故事串聯在一起。展覽中的每一處細節，都承載著對時光的記憶與情感。\r\n青春歲月如一部電影，時而熱血，時而感動，每一幕都刻畫著學生們的追求與努力。三年的歲月如光影閃爍，學生們將走向不同的片場，但這段燦爛的旅程，始終是他們心中最難以忘懷的經典篇章。\r\n展出內容涵蓋水墨、素描、水彩、油畫、版畫、粉彩、壓克力畫、平面設計、裝置藝術等等', `organizer`='臺中市葫蘆墩文化中心', `address`='臺中市豐原區圓環東路782號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='臺中市葫蘆墩文化中心', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144530,1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fbc26b32408680beba0', '巧工藝境-臺灣工藝之家協會會員創作展', '本展匯集臺灣工藝之家協會10位頂尖工藝大師精湛作品，有竹籐編、琉璃、染織、春仔花、拼布、金工等。\r\n包括國家工藝成就獎竹籐藝術家張憲平，竹編傳統工藝保存者邱錦緞、劉興澤，造劍傳統藝術保存者陳遠芳，原住民染織工藝林淑莉，琉璃藝術家林芳仕、林瑤農，纏花設計林佩瑩，榮獲美國AQS國際拼布大獎周秀惠，知名藍染講師林潔怡等工藝家一同展出，展現臺灣工藝的傳統與創新，值得細細品味。', '臺中市葫蘆墩文化中心', '臺中市豐原區圓環東路782號', '2025-04-25 00:00:00', '2025-05-25 00:00:00', '臺中市葫蘆墩文化中心', 24.24990298, 120.7375715, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144529,1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='巧工藝境-臺灣工藝之家協會會員創作展', `description`='本展匯集臺灣工藝之家協會10位頂尖工藝大師精湛作品，有竹籐編、琉璃、染織、春仔花、拼布、金工等。\r\n包括國家工藝成就獎竹籐藝術家張憲平，竹編傳統工藝保存者邱錦緞、劉興澤，造劍傳統藝術保存者陳遠芳，原住民染織工藝林淑莉，琉璃藝術家林芳仕、林瑤農，纏花設計林佩瑩，榮獲美國AQS國際拼布大獎周秀惠，知名藍染講師林潔怡等工藝家一同展出，展現臺灣工藝的傳統與創新，值得細細品味。', `organizer`='臺中市葫蘆墩文化中心', `address`='臺中市豐原區圓環東路782號', `start_date`='2025-04-25 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='臺中市葫蘆墩文化中心', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144529,1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fbc26b32408680beba1', '無垠-第39屆豐原高中美術班畢業展', '本次展覽集結了東方畫與西畫的多元創作，每一幅作品都是我們活潑靈魂與創意思維的具現化。從傳統水墨的細膩筆觸，到西方油畫的熱烈色彩，展現了多元的創作能力與學習成果，每一件作品都充滿對藝術的熱情與對未來的無限想像。讓我們一同見證這群年輕藝術家的創意與成長，期待您的參與！', '臺中市葫蘆墩文化中心', '臺中市豐原區圓環東路782號', '2025-04-25 00:00:00', '2025-05-18 00:00:00', '臺中市葫蘆墩文化中心', 24.24990298, 120.7375715, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144531,1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無垠-第39屆豐原高中美術班畢業展', `description`='本次展覽集結了東方畫與西畫的多元創作，每一幅作品都是我們活潑靈魂與創意思維的具現化。從傳統水墨的細膩筆觸，到西方油畫的熱烈色彩，展現了多元的創作能力與學習成果，每一件作品都充滿對藝術的熱情與對未來的無限想像。讓我們一同見證這群年輕藝術家的創意與成長，期待您的參與！', `organizer`='臺中市葫蘆墩文化中心', `address`='臺中市豐原區圓環東路782號', `start_date`='2025-04-25 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='臺中市葫蘆墩文化中心', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144531,1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fbe26b32408680beba2', '筆墨彩釉舞春-澄懷畫會聯展 創作導覽', '澄懷畫會旨在推動花鳥畫並使其根植於臺灣。會員筆法精準而簡要，線條之啟承轉折流暢無滯，墨色之濃淡乾溼生動而有韻味，有致力於寫意花鳥、工筆、有潛於瓷器彩繪、山水、膠彩，各個都有非凡的成就。藉由本展以畫會友，本次展出內容包含工筆、山水、膠彩等多項作品，就教於同好藝文各界，以臻真、善、美之境界。', '臺中市葫蘆墩文化中心', '臺中市豐原區圓環東路782號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '臺中市葫蘆墩文化中心', 24.24990298, 120.7375715, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,143541,99,,,1,,', '[]') ON DUPLICATE KEY UPDATE `activity_name`='筆墨彩釉舞春-澄懷畫會聯展 創作導覽', `description`='澄懷畫會旨在推動花鳥畫並使其根植於臺灣。會員筆法精準而簡要，線條之啟承轉折流暢無滯，墨色之濃淡乾溼生動而有韻味，有致力於寫意花鳥、工筆、有潛於瓷器彩繪、山水、膠彩，各個都有非凡的成就。藉由本展以畫會友，本次展出內容包含工筆、山水、膠彩等多項作品，就教於同好藝文各界，以臻真、善、美之境界。', `organizer`='臺中市葫蘆墩文化中心', `address`='臺中市豐原區圓環東路782號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市葫蘆墩文化中心', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,143541,99,,,1,,', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc026b32408680beba3', '｜東區林森圖書館｜3月 歡樂唱遊時間｜共4場', '由小葫蘆故事劇團各個志工老師為親子嬰幼兒帶來有趣的聽故事活動，從小培養聆聽故事的習慣。\r\n\r\n3月5日《怕浪費的奶奶》音符鳥\r\n3月12日《森林裡的小松鼠：春天來了》貝貝媽咪\r\n3月19日《怪獸湖》橘子\r\n3月26日《哈利的花毛衣》藍鯨阿姨\r\n', '臺南市東區林森圖書館', '臺南市東區林森路二段46號', '2025-03-05 00:00:00', '2025-03-26 00:00:00', '臺南市東區林森圖書館', 22.98178202, 120.2281858, '無資料', 'https://www.facebook.com/profile.php?id=100064371172026', '[]') ON DUPLICATE KEY UPDATE `activity_name`='｜東區林森圖書館｜3月 歡樂唱遊時間｜共4場', `description`='由小葫蘆故事劇團各個志工老師為親子嬰幼兒帶來有趣的聽故事活動，從小培養聆聽故事的習慣。\r\n\r\n3月5日《怕浪費的奶奶》音符鳥\r\n3月12日《森林裡的小松鼠：春天來了》貝貝媽咪\r\n3月19日《怪獸湖》橘子\r\n3月26日《哈利的花毛衣》藍鯨阿姨\r\n', `organizer`='臺南市東區林森圖書館', `address`='臺南市東區林森路二段46號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺南市東區林森圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064371172026', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc026b32408680beba4', '｜東區林森圖書館｜生態攝影常設展', '本館與荒野保護協會-台南分會合作，於本館公共樓梯間展示各攝影作家精彩生態攝影作品，藉由藝術美學傳達環境保護與重視生態觀念。', '臺南市東區林森圖書館', '臺南市東區林森路二段46號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺南市東區林森圖書館', 22.98178202, 120.2281858, '無資料', 'https://www.facebook.com/profile.php?id=100064371172026', '[]') ON DUPLICATE KEY UPDATE `activity_name`='｜東區林森圖書館｜生態攝影常設展', `description`='本館與荒野保護協會-台南分會合作，於本館公共樓梯間展示各攝影作家精彩生態攝影作品，藉由藝術美學傳達環境保護與重視生態觀念。', `organizer`='臺南市東區林森圖書館', `address`='臺南市東區林森路二段46號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市東區林森圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064371172026', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc226b32408680beba6', '114年曼丁鼓舞樂長青', '曼丁鼓演奏是為了舞蹈而伴奏，鼓聲和舞蹈是無法分割的文化總體，因此上課內容將鼓舞學習 和而為一，透過身體律動找回手部打擊的本能․挑選入門曲目和節奏，設計「集體鼓樂」 的互動環境，引導學員由「聆聽」、「唱節奏」「身體律動」，開始進入節奏世界․由講師現場進行打擊示範及講解，學員模仿、親自操作，分組練習、合奏。', '桃園市桃園區新埔社區發展協會', '桃園市桃園區', '2025-02-19 00:00:00', '2025-05-07 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年曼丁鼓舞樂長青', `description`='曼丁鼓演奏是為了舞蹈而伴奏，鼓聲和舞蹈是無法分割的文化總體，因此上課內容將鼓舞學習 和而為一，透過身體律動找回手部打擊的本能․挑選入門曲目和節奏，設計「集體鼓樂」 的互動環境，引導學員由「聆聽」、「唱節奏」「身體律動」，開始進入節奏世界․由講師現場進行打擊示範及講解，學員模仿、親自操作，分組練習、合奏。', `organizer`='桃園市桃園區新埔社區發展協會', `address`='桃園市桃園區', `start_date`='2025-02-19 00:00:00', `end_date`='2025-05-07 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc226b32408680beba7', '長濱鄉立圖書館｜親子繪本共讀與手做創意種子精靈', '【114年多元閱讀活動】\r\n你知道每年的3月12日是植樹節嗎?\r\n多多老師再度來跟我們講故事囉!\r\n並跟著多多老師一起來˙做有趣的創意種子精靈吧\r\n(一).活動時間-3月15日，星期六，0930-1130\r\n(二).活動對象-親子(低年級以下需家長陪同)、一般民眾，共25人 \r\n(三).報名專線-832450(採事先報名)', '臺東縣長濱鄉公所', '臺東縣長濱鄉長濱路4鄰9號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '臺東縣長濱鄉立圖書館', 23.33476899, 121.4261725, '無資料', 'https://www.facebook.com/share/p/169YudN5eA/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='長濱鄉立圖書館｜親子繪本共讀與手做創意種子精靈', `description`='【114年多元閱讀活動】\r\n你知道每年的3月12日是植樹節嗎?\r\n多多老師再度來跟我們講故事囉!\r\n並跟著多多老師一起來˙做有趣的創意種子精靈吧\r\n(一).活動時間-3月15日，星期六，0930-1130\r\n(二).活動對象-親子(低年級以下需家長陪同)、一般民眾，共25人 \r\n(三).報名專線-832450(採事先報名)', `organizer`='臺東縣長濱鄉公所', `address`='臺東縣長濱鄉長濱路4鄰9號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='臺東縣長濱鄉立圖書館', `latitude`=23.33476899, `longitude`=121.4261725, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/169YudN5eA/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc226b32408680beba8', '114年3月FUN心聽故事', '本活動邀請故事達人以生動活動的方式進行故事分享及延伸活動，希望籍由中外精彩故事內容分享，增進兒童的語言能力、創作力及想像力，逐步培養閱讀能力，歡迎親子一同參加，共渡美好閱讀時光。3/1 世界上最美麗的村子 3/29拐杖狗', '高雄市立圖書館總館', '高雄市橋頭區24鄰隆豐路7號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '高雄市立圖書館橋頭分館', 22.758444, 120.3060122, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年3月FUN心聽故事', `description`='本活動邀請故事達人以生動活動的方式進行故事分享及延伸活動，希望籍由中外精彩故事內容分享，增進兒童的語言能力、創作力及想像力，逐步培養閱讀能力，歡迎親子一同參加，共渡美好閱讀時光。3/1 世界上最美麗的村子 3/29拐杖狗', `organizer`='高雄市立圖書館總館', `address`='高雄市橋頭區24鄰隆豐路7號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='高雄市立圖書館橋頭分館', `latitude`=22.758444, `longitude`=120.3060122, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc226b32408680beba9', '2025世界母語日~百變的萬能阿嬤', '本活動邀請王思吟老師分享台語繪本-阿嬤家、阿嬤的碗公、過年就是要吃阿媽的菜頭粿和外婆的蘿蔔糕，進行台語繞口令PK賽，畫出心中的萬能阿嬤，鼓勵親子多說台語。', '高雄市立圖書館總館', '高雄市橋頭區24鄰隆豐路7號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '高雄市立圖書館橋頭分館', 22.758444, 120.3060122, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025世界母語日~百變的萬能阿嬤', `description`='本活動邀請王思吟老師分享台語繪本-阿嬤家、阿嬤的碗公、過年就是要吃阿媽的菜頭粿和外婆的蘿蔔糕，進行台語繞口令PK賽，畫出心中的萬能阿嬤，鼓勵親子多說台語。', `organizer`='高雄市立圖書館總館', `address`='高雄市橋頭區24鄰隆豐路7號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='高雄市立圖書館橋頭分館', `latitude`=22.758444, `longitude`=120.3060122, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc226b32408680bebaa', '2025世界母語日~囝仔歌作伙唱', '本活動邀請邀請紙芝居故事達人紅豆冰哥哥以歡樂的氛圍，為小朋友說台語故事「小河馬找新家人」，教小朋友唱囝仔歌及有獎徵答，在快樂中學習台語。', '高雄市立圖書館總館', '高雄市橋頭區24鄰隆豐路7號', '2025-03-08 00:00:00', '2025-03-22 00:00:00', '高雄市立圖書館橋頭分館', 22.758444, 120.3060122, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025世界母語日~囝仔歌作伙唱', `description`='本活動邀請邀請紙芝居故事達人紅豆冰哥哥以歡樂的氛圍，為小朋友說台語故事「小河馬找新家人」，教小朋友唱囝仔歌及有獎徵答，在快樂中學習台語。', `organizer`='高雄市立圖書館總館', `address`='高雄市橋頭區24鄰隆豐路7號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='高雄市立圖書館橋頭分館', `latitude`=22.758444, `longitude`=120.3060122, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
