INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc326b32408680bebac', '【春神來了】主題繪本書展、女神節繪本展', '【春神來了-主題繪本書展】\r\n天氣一暖，總覺得世界就明亮了...蜷縮的萬物也開始活躍了...配合著季節和五感感受，陪孩子讀本「春天」的書吧！\r\n一起在書裡散步...兜風..，一起感受藍天白雲下蓬勃的生命力。\r\n\r\n【女神節繪本展】\r\n甚麼時候「婦女節」升級成「女神節」了？光這名稱就值得好好慶祝了。\r\n臨下班前才驚覺明天是3月8日婦女節，上網一看，全網都稱為「女神節」，還說…女生寵愛自己無須理由…。哈哈哈，店家有店家的行銷口號，我們....就...\r\n趕快讓我們館裡的「女主角繪本」集合起來，陪大家一起歡慶「女神節」，歡迎借閱，還可參加集點活動。', '苗栗縣三灣鄉公所', '苗栗縣三灣鄉11鄰親民路17-1 號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '苗栗縣三灣鄉立圖書館', 24.63599405, 120.9525745, '無資料', 'https://www.facebook.com/sanwanlib#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【春神來了】主題繪本書展、女神節繪本展', `description`='【春神來了-主題繪本書展】\r\n天氣一暖，總覺得世界就明亮了...蜷縮的萬物也開始活躍了...配合著季節和五感感受，陪孩子讀本「春天」的書吧！\r\n一起在書裡散步...兜風..，一起感受藍天白雲下蓬勃的生命力。\r\n\r\n【女神節繪本展】\r\n甚麼時候「婦女節」升級成「女神節」了？光這名稱就值得好好慶祝了。\r\n臨下班前才驚覺明天是3月8日婦女節，上網一看，全網都稱為「女神節」，還說…女生寵愛自己無須理由…。哈哈哈，店家有店家的行銷口號，我們....就...\r\n趕快讓我們館裡的「女主角繪本」集合起來，陪大家一起歡慶「女神節」，歡迎借閱，還可參加集點活動。', `organizer`='苗栗縣三灣鄉公所', `address`='苗栗縣三灣鄉11鄰親民路17-1 號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='苗栗縣三灣鄉立圖書館', `latitude`=24.63599405, `longitude`=120.9525745, `ticket_price`='無資料', `source_url`='https://www.facebook.com/sanwanlib#', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc326b32408680bebad', '凡所有相。皆是虛妄-張桂珍壓克力畫展', '藝術家張桂珍展出22張30號之畫作，透過壓克力創作，將個人視覺心象完整呈現，藉此表達並反映個人藝術創作的意念與內心的情感。', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-03-12 00:00:00', '2025-04-13 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='凡所有相。皆是虛妄-張桂珍壓克力畫展', `description`='藝術家張桂珍展出22張30號之畫作，透過壓克力創作，將個人視覺心象完整呈現，藉此表達並反映個人藝術創作的意念與內心的情感。', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
