INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc326b32408680bebaf', '國立東華大學藝術與設計學系教授聯展', '此展集合了國立東華大學藝術與設計學系17位專兼任教授，展出包含油畫、攝影、水墨、陶藝、設計和複合媒材等20件作品，內容豐富。', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-03-12 00:00:00', '2025-04-13 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國立東華大學藝術與設計學系教授聯展', `description`='此展集合了國立東華大學藝術與設計學系17位專兼任教授，展出包含油畫、攝影、水墨、陶藝、設計和複合媒材等20件作品，內容豐富。', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc326b32408680bebb0', '海端鄉公所｜海端鄉114年度各部落射耳祭', '【2025年海端鄉各部落布農族射耳祭儀日程】\r\n海端的遊子們，該回來了\r\n--------\r\n04/04(五)-加拿村\r\n04/05(六)-利稻村、海端村新武部落\r\n04/12(六)-廣原村\r\n04/19(六)-崁頂村\r\n04/26(六)-霧鹿村(不對外開放)\r\n05/03(六)-海端村初來部落\r\n--------\r\n◇◇malahtangia 射耳祭\r\n由耆老帶領男子們進行射耳儀式，\r\n靶上的耳以hangvang(水鹿)、sakut(山羌)取下的耳為主，「碰！」槍聲一響，男子祈福順利平安，增進能力。「咻！」弓箭射出，男孩祈福健康長大，未來有能力保護家族。\r\n◇◇mapulaung 報戰功\r\n大聲宣揚自己的戰績，展現自己的狩獵能力，\r\n自信且謙遜，大聲榮耀自己的名字，\r\n大聲強調自己從何來。\r\n---------------------------\r\n圖像繪製│胡子珺\r\n更多詳細資訊請逕洽各村辦電話或各村幹事。\r\n※祭典參與期間請遵守各部落祭儀規範※', '臺東縣海端鄉公所', '臺東縣海端鄉', '2025-04-04 00:00:00', '2025-05-03 00:00:00', '海端鄉（臺東縣）=', 23.11478528, 121.0175672, '無資料', 'https://www.facebook.com/share/p/16nXSjP1ja/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='海端鄉公所｜海端鄉114年度各部落射耳祭', `description`='【2025年海端鄉各部落布農族射耳祭儀日程】\r\n海端的遊子們，該回來了\r\n--------\r\n04/04(五)-加拿村\r\n04/05(六)-利稻村、海端村新武部落\r\n04/12(六)-廣原村\r\n04/19(六)-崁頂村\r\n04/26(六)-霧鹿村(不對外開放)\r\n05/03(六)-海端村初來部落\r\n--------\r\n◇◇malahtangia 射耳祭\r\n由耆老帶領男子們進行射耳儀式，\r\n靶上的耳以hangvang(水鹿)、sakut(山羌)取下的耳為主，「碰！」槍聲一響，男子祈福順利平安，增進能力。「咻！」弓箭射出，男孩祈福健康長大，未來有能力保護家族。\r\n◇◇mapulaung 報戰功\r\n大聲宣揚自己的戰績，展現自己的狩獵能力，\r\n自信且謙遜，大聲榮耀自己的名字，\r\n大聲強調自己從何來。\r\n---------------------------\r\n圖像繪製│胡子珺\r\n更多詳細資訊請逕洽各村辦電話或各村幹事。\r\n※祭典參與期間請遵守各部落祭儀規範※', `organizer`='臺東縣海端鄉公所', `address`='臺東縣海端鄉', `start_date`='2025-04-04 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='海端鄉（臺東縣）=', `latitude`=23.11478528, `longitude`=121.0175672, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/16nXSjP1ja/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc326b32408680bebb1', '劉貞老師「意象之美」書畫個展', '意象繪畫是將自己內在心靈視窗所見的物象感受與情感之反應相互產生共鳴，透過筆墨來表現、書法和詩句意境創作表現、是中國極為特殊的藝術創作為西方藝術所無。\r\n苗栗高中退休教師「劉貞」將近年來的田園生活、爬山、旅行和閱讀心得把所見所聞放在創作裡展出內容是水墨和書法兩大項。歡迎喜愛藝術的朋友前來欣賞與指導。', '苗栗縣西湖鄉公所', '苗栗縣西湖鄉13鄰194-4號', '2025-03-05 00:00:00', '2025-04-25 00:00:00', '吳濁流文學藝術館', 24.5235061, 120.7780948, '無資料', 'https://www.facebook.com/profile.php?id=100083139282083', '[]') ON DUPLICATE KEY UPDATE `activity_name`='劉貞老師「意象之美」書畫個展', `description`='意象繪畫是將自己內在心靈視窗所見的物象感受與情感之反應相互產生共鳴，透過筆墨來表現、書法和詩句意境創作表現、是中國極為特殊的藝術創作為西方藝術所無。\r\n苗栗高中退休教師「劉貞」將近年來的田園生活、爬山、旅行和閱讀心得把所見所聞放在創作裡展出內容是水墨和書法兩大項。歡迎喜愛藝術的朋友前來欣賞與指導。', `organizer`='苗栗縣西湖鄉公所', `address`='苗栗縣西湖鄉13鄰194-4號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='吳濁流文學藝術館', `latitude`=24.5235061, `longitude`=120.7780948, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100083139282083', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc326b32408680bebb2', '親子相伴、與陶同行～114年桃竹苗青年推動在地陶文化計畫：親子陶藝活動（4場次）', '課程內容含導覽苗栗陶瓷博物館、陶土材料介紹及基本操作示範+親子共創活動，讓親子共同了解陶藝與在地生活息息相關的連結，啟發大家對陶藝的重視及興趣，同時搭接在地藝術創作者，結合實作，辦理具美學教育之課程，帶動特色生活文化。\r\n參與對象：親子家庭，一場次50人。\r\n報名時間：即日起至3月14日止，或額滿為止\r\n報名連結 https://forms.gle/3sym9XZyxkUwqEDz7\r\n聯絡資訊：037-220313(羅小姐/呂小姐)', '苗栗縣政府', '苗栗縣公館鄉14鄰館南352號', '2025-03-29 00:00:00', '2025-03-30 00:00:00', '苗栗陶瓷農創園區', 25.0422099, 121.51947, '活動費用／人+150', 'https://www.facebook.com/miaoliceramics', '[]') ON DUPLICATE KEY UPDATE `activity_name`='親子相伴、與陶同行～114年桃竹苗青年推動在地陶文化計畫：親子陶藝活動（4場次）', `description`='課程內容含導覽苗栗陶瓷博物館、陶土材料介紹及基本操作示範+親子共創活動，讓親子共同了解陶藝與在地生活息息相關的連結，啟發大家對陶藝的重視及興趣，同時搭接在地藝術創作者，結合實作，辦理具美學教育之課程，帶動特色生活文化。\r\n參與對象：親子家庭，一場次50人。\r\n報名時間：即日起至3月14日止，或額滿為止\r\n報名連結 https://forms.gle/3sym9XZyxkUwqEDz7\r\n聯絡資訊：037-220313(羅小姐/呂小姐)', `organizer`='苗栗縣政府', `address`='苗栗縣公館鄉14鄰館南352號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='苗栗陶瓷農創園區', `latitude`=25.0422099, `longitude`=121.51947, `ticket_price`='活動費用／人+150', `source_url`='https://www.facebook.com/miaoliceramics', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc326b32408680bebb3', '延平鄉公所｜2025年延平鄉各村射耳祭', '2025年延平鄉各村射耳祭時間表\r\n==============================\r\nmalahtangia射耳祭是布農族所有祭典中最為盛大的，\r\n祭儀中除了展現族群與自然生存共融的生活型態，\r\n更是文化傳承的重要祭典。\r\n男孩跟隨長輩入山狩獵、女孩學習織布、釀酒，\r\n從祭槍(pislai)至報戰功(malastapang)；\r\n從搗米(mabazu)至釀酒(kadavus)，\r\n族語(halinga)、禁忌(samu)、文化(bungka)、歌謠(huzas)\r\n依著我們一起呼吸，\r\n大手握著小手，世世代代不忘祖先的祖訓，遵守與月亮的約定，\r\n讓我們在一步一腳印中，成為真正的布農族人【min bunun】\r\n#Kulumaha #minduduaz\r\n#青年們 #回家吧\r\n==============================\r\n04/03(四)上午8點-鸞山村：鸞山村祭祀廣場\r\n04/05(六)上午9點-永康村：永康村祭祀廣場\r\n04/12(六)上午8點-桃源村：桃源村祭祀廣場\r\n04/19(六)上午9點-紅葉村：紅葉村祭祀廣場\r\n04/26(六)上午8點-武陵村：武陵村祭祀廣場\r\n==============================\r\n※參與祭典請遵守各部落祭儀規範※\r\n==============================\r\n各村祭儀聯絡人：\r\n鸞山村：村幹事 余平凡 0983195219\r\n永康村：村幹事 邱展蕾 0980568252\r\n桃源村：村幹事 蕭喬宇 0981961473\r\n紅葉村：村幹事 胡中強 0985526506\r\n武陵村：村幹事 賴思璇 0972869910', '臺東縣延平鄉公所', '臺東縣延平鄉', '2025-04-03 00:00:00', '2025-04-26 00:00:00', '延平鄉（臺東縣）=', 22.90343174, 120.9831902, '無資料', 'https://www.facebook.com/share/p/1A2cycaVeK/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='延平鄉公所｜2025年延平鄉各村射耳祭', `description`='2025年延平鄉各村射耳祭時間表\r\n==============================\r\nmalahtangia射耳祭是布農族所有祭典中最為盛大的，\r\n祭儀中除了展現族群與自然生存共融的生活型態，\r\n更是文化傳承的重要祭典。\r\n男孩跟隨長輩入山狩獵、女孩學習織布、釀酒，\r\n從祭槍(pislai)至報戰功(malastapang)；\r\n從搗米(mabazu)至釀酒(kadavus)，\r\n族語(halinga)、禁忌(samu)、文化(bungka)、歌謠(huzas)\r\n依著我們一起呼吸，\r\n大手握著小手，世世代代不忘祖先的祖訓，遵守與月亮的約定，\r\n讓我們在一步一腳印中，成為真正的布農族人【min bunun】\r\n#Kulumaha #minduduaz\r\n#青年們 #回家吧\r\n==============================\r\n04/03(四)上午8點-鸞山村：鸞山村祭祀廣場\r\n04/05(六)上午9點-永康村：永康村祭祀廣場\r\n04/12(六)上午8點-桃源村：桃源村祭祀廣場\r\n04/19(六)上午9點-紅葉村：紅葉村祭祀廣場\r\n04/26(六)上午8點-武陵村：武陵村祭祀廣場\r\n==============================\r\n※參與祭典請遵守各部落祭儀規範※\r\n==============================\r\n各村祭儀聯絡人：\r\n鸞山村：村幹事 余平凡 0983195219\r\n永康村：村幹事 邱展蕾 0980568252\r\n桃源村：村幹事 蕭喬宇 0981961473\r\n紅葉村：村幹事 胡中強 0985526506\r\n武陵村：村幹事 賴思璇 0972869910', `organizer`='臺東縣延平鄉公所', `address`='臺東縣延平鄉', `start_date`='2025-04-03 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='延平鄉（臺東縣）=', `latitude`=22.90343174, `longitude`=120.9831902, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1A2cycaVeK/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc326b32408680bebb4', '頭份豆染藍韻-技藝培力工坊', '課程內容：\r\n(一)型染結構要點、黃豆糊調製、刮糊練習\r\n(二)點的結構運用練習、型染吊染練習\r\n(三)線的結構運用練習、黃豆糊調製、刮糊練習\r\n(四)面的結構運用練習、黃豆糊調製、刮糊變化練習(遮版\r\n(五)圖案刻版運用練習(藍底白花)\r\n(六)圖案刻版修版討論\r\n(七)型染圖案刻版討論、型版圖案應用練習\r\n(八)綜合討論、型版圖案應用練習(拔染應用練習)\r\n\r\n課程對象：對染布技法有興趣之民眾，限額10名。\r\n線上報名 https://www.beclass.com/rid=294fec067c6e63bf21e6', '苗栗縣藝耆協會', '苗栗縣頭份市', '2025-04-02 00:00:00', '2025-05-21 00:00:00', '頭份市（苗栗縣）=', 24.67628243, 120.9189437, '課程費用+3800', 'https://www.facebook.com/parrot12345/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='頭份豆染藍韻-技藝培力工坊', `description`='課程內容：\r\n(一)型染結構要點、黃豆糊調製、刮糊練習\r\n(二)點的結構運用練習、型染吊染練習\r\n(三)線的結構運用練習、黃豆糊調製、刮糊練習\r\n(四)面的結構運用練習、黃豆糊調製、刮糊變化練習(遮版\r\n(五)圖案刻版運用練習(藍底白花)\r\n(六)圖案刻版修版討論\r\n(七)型染圖案刻版討論、型版圖案應用練習\r\n(八)綜合討論、型版圖案應用練習(拔染應用練習)\r\n\r\n課程對象：對染布技法有興趣之民眾，限額10名。\r\n線上報名 https://www.beclass.com/rid=294fec067c6e63bf21e6', `organizer`='苗栗縣藝耆協會', `address`='苗栗縣頭份市', `start_date`='2025-04-02 00:00:00', `end_date`='2025-05-21 00:00:00', `location`='頭份市（苗栗縣）=', `latitude`=24.67628243, `longitude`=120.9189437, `ticket_price`='課程費用+3800', `source_url`='https://www.facebook.com/parrot12345/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc326b32408680bebb5', '2025青春美展 轉存為Export as – 義守大學創意整合設計學系110級畢業展', '本次畢業展以「轉存為」作為展覽名稱及核心概念，象徵著同學們畢業後就像檔案完成後能轉存為各種格式，也同時暗示每個人在人生中都具備無限的可能性。除了畢業展的同學們外，也希望來看展覽的人們能知道自己的人生並非固定的格式，而是可以隨時「轉存為」更加豐富的自己。\r\n主視覺除了簡單的黑白灰三色外，還增加了基礎的三原色作為陪襯。色彩的混和象徵著人生中的各種轉變，每個顏色都有個體獨特的風格，也展示了我們在面對不同的經歷後的成長與蛻變。\r\n', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-05-16 00:00:00', '2025-05-27 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4102', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展 轉存為Export as – 義守大學創意整合設計學系110級畢業展', `description`='本次畢業展以「轉存為」作為展覽名稱及核心概念，象徵著同學們畢業後就像檔案完成後能轉存為各種格式，也同時暗示每個人在人生中都具備無限的可能性。除了畢業展的同學們外，也希望來看展覽的人們能知道自己的人生並非固定的格式，而是可以隨時「轉存為」更加豐富的自己。\r\n主視覺除了簡單的黑白灰三色外，還增加了基礎的三原色作為陪襯。色彩的混和象徵著人生中的各種轉變，每個顏色都有個體獨特的風格，也展示了我們在面對不同的經歷後的成長與蛻變。\r\n', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-16 00:00:00', `end_date`='2025-05-27 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4102', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc326b32408680bebb6', '114年苗栗縣兒童節活動：2025苗栗童樂會', '【2025苗栗童樂會】，這場超級好玩的活動！不只有MOMO姐姐親自帶動跳舞，還有愛唱歌劇場，為我們帶來超人氣的歌曲，在活動中也有超級有趣的童玩遊戲等著你來挑戰！這一天，快樂和笑聲滿滿，讓你開心一整天！快呼朋引伴，來和我們一起度過一個充滿歡樂的童趣時光。', '苗栗縣政府', '苗栗縣苗栗市經國路4段79 號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '苗栗縣立體育場（巨蛋體育館）', 24.56382141, 120.8112299, '無資料', 'https://www.facebook.com/profile.php?id=100086910531086', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年苗栗縣兒童節活動：2025苗栗童樂會', `description`='【2025苗栗童樂會】，這場超級好玩的活動！不只有MOMO姐姐親自帶動跳舞，還有愛唱歌劇場，為我們帶來超人氣的歌曲，在活動中也有超級有趣的童玩遊戲等著你來挑戰！這一天，快樂和笑聲滿滿，讓你開心一整天！快呼朋引伴，來和我們一起度過一個充滿歡樂的童趣時光。', `organizer`='苗栗縣政府', `address`='苗栗縣苗栗市經國路4段79 號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='苗栗縣立體育場（巨蛋體育館）', `latitude`=24.56382141, `longitude`=120.8112299, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100086910531086', `image_url`='[]';
