INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc326b32408680bebb8', '居家植感 療癒紓壓主題書展', '根據國外科學期刊的研究表示，種植植物、照顧植物，可以有效促進身心健康、增加幸福感與成就感並改善室內空氣品質，可謂好處多多。邀請大小朋友一起來愛上多肉植物，本次除了展示相關書籍外，在一旁更展出賞心悅目的多肉造景組盆，趕緊來享受輕鬆片刻吧！\r\n洽詢電話：049-2984144轉40。', '南投縣埔里鎮公所', '南投縣埔里鎮六合路178號', '2025-03-08 00:00:00', '2025-03-30 00:00:00', '南投縣埔里鎮立圖書館', 23.9702357, 120.9713659, '無資料', 'https://www.facebook.com/pulilibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='居家植感 療癒紓壓主題書展', `description`='根據國外科學期刊的研究表示，種植植物、照顧植物，可以有效促進身心健康、增加幸福感與成就感並改善室內空氣品質，可謂好處多多。邀請大小朋友一起來愛上多肉植物，本次除了展示相關書籍外，在一旁更展出賞心悅目的多肉造景組盆，趕緊來享受輕鬆片刻吧！\r\n洽詢電話：049-2984144轉40。', `organizer`='南投縣埔里鎮公所', `address`='南投縣埔里鎮六合路178號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='南投縣埔里鎮立圖書館', `latitude`=23.9702357, `longitude`=120.9713659, `ticket_price`='無資料', `source_url`='https://www.facebook.com/pulilibrary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc326b32408680bebb9', '2025青春美展 「Hi貝斯曼」長榮大學書畫藝術學系畢業展', '2025長榮大學書畫藝術學系畢業展主題「Hi貝斯曼」，象徵畢業生在地下B1教室四年耕耘的成果。從基礎到創作，筆墨承載成長與探索，「貝斯曼」成為共同學習與陪伴的象徵。在充滿朝氣的「Hi」中啟程，畢業非終點，而是邁向新階段的開始。\r\n', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-05-02 00:00:00', '2025-05-13 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4103', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展 「Hi貝斯曼」長榮大學書畫藝術學系畢業展', `description`='2025長榮大學書畫藝術學系畢業展主題「Hi貝斯曼」，象徵畢業生在地下B1教室四年耕耘的成果。從基礎到創作，筆墨承載成長與探索，「貝斯曼」成為共同學習與陪伴的象徵。在充滿朝氣的「Hi」中啟程，畢業非終點，而是邁向新階段的開始。\r\n', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-02 00:00:00', `end_date`='2025-05-13 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4103', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09fc326b32408680bebba', '南投古街讀書會42：陳千武老師《獵女犯》', '讀書會所累積的是認識地方學，建立對地方的認識論，我們讀了許多的文本，也邀請專家來演講，透過各種方式試圖建構屬於南投自己的知識系統。\r\n而第五年的「南投古街讀書會」，在閱讀書籍與形式上也有所進展，從凱惠發起人帶著大家讀書，到參與者自己願意去導讀，現在好幾個夥伴們願意自己導讀關心南投的各種文化知識，真的非常的開心。歡迎有興趣的朋友一起來！\r\n\r\n南投古街讀書會43\r\n時間：2025/4/2 PM7:00-9:00\r\n導讀主題：陳千武老師《獵女犯》\r\n地點：維克多（南投市集賢路10號）\r\n南投古街讀書會流程：\r\n19:00-19:30 自我介紹（介紹自己以及為什麼參加讀書會）\r\n19:30-20:20 閱讀文本\r\n20:20-21:00 討論分享與回饋', '也品文藝工作室', '南投縣南投市', '2025-04-02 00:00:00', '2025-04-02 00:00:00', '南投市（南投縣）=', 23.92173537, 120.6787658, '無資料', 'https://www.facebook.com/JISArtCenter/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南投古街讀書會42：陳千武老師《獵女犯》', `description`='讀書會所累積的是認識地方學，建立對地方的認識論，我們讀了許多的文本，也邀請專家來演講，透過各種方式試圖建構屬於南投自己的知識系統。\r\n而第五年的「南投古街讀書會」，在閱讀書籍與形式上也有所進展，從凱惠發起人帶著大家讀書，到參與者自己願意去導讀，現在好幾個夥伴們願意自己導讀關心南投的各種文化知識，真的非常的開心。歡迎有興趣的朋友一起來！\r\n\r\n南投古街讀書會43\r\n時間：2025/4/2 PM7:00-9:00\r\n導讀主題：陳千武老師《獵女犯》\r\n地點：維克多（南投市集賢路10號）\r\n南投古街讀書會流程：\r\n19:00-19:30 自我介紹（介紹自己以及為什麼參加讀書會）\r\n19:30-20:20 閱讀文本\r\n20:20-21:00 討論分享與回饋', `organizer`='也品文藝工作室', `address`='南投縣南投市', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-02 00:00:00', `location`='南投市（南投縣）=', `latitude`=23.92173537, `longitude`=120.6787658, `ticket_price`='無資料', `source_url`='https://www.facebook.com/JISArtCenter/', `image_url`='[]';
