INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('795', '客家桐花祭', '每年四月間，當第一朵桐花綻放伊始，即宣告「客家桐花祭」的來臨。四至六月期間，各地客庄全家悠遊、旅客穿梭如織的畫面常映眼簾，體驗結合文化、旅遊、生態、產業之賞桐活動，儼然成為各地遊客每年共赴的美麗饗宴。桐花季節之開花資訊請見桐花花況預測平台。\r\n\r\n    新竹縣客家桐花祭．桐遊湖口健行趣\r\n\r\n ', '客家委員會', '基隆市 暖暖區暖暖東勢坑產業步道', '2025-04-01 00:00:00', '2025-05-31 00:00:00', '基隆市 暖暖區暖暖東勢坑產業步道', 25.0768133, 121.7550346, '無資料', 'https://tung.romantichakka.com/home?lang=ch', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081426/9f1146e9e168d184808b7f545ac4c40f67f942e3.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='客家桐花祭', `description`='每年四月間，當第一朵桐花綻放伊始，即宣告「客家桐花祭」的來臨。四至六月期間，各地客庄全家悠遊、旅客穿梭如織的畫面常映眼簾，體驗結合文化、旅遊、生態、產業之賞桐活動，儼然成為各地遊客每年共赴的美麗饗宴。桐花季節之開花資訊請見桐花花況預測平台。\r\n\r\n    新竹縣客家桐花祭．桐遊湖口健行趣\r\n\r\n ', `organizer`='客家委員會', `address`='基隆市 暖暖區暖暖東勢坑產業步道', `start_date`='2025-04-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='基隆市 暖暖區暖暖東勢坑產業步道', `latitude`=25.0768133, `longitude`=121.7550346, `ticket_price`='無資料', `source_url`='https://tung.romantichakka.com/home?lang=ch', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081426/9f1146e9e168d184808b7f545ac4c40f67f942e3.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9362239', '親子美育數位圖書館-兒童親子芳香手作擴香花', '&nbsp; 春季是百花勝放的季節，除了自然的花卉，生活中還有很多其他的方式可留下芬芳的痕跡。本次活動將由陳麗英老師引領學童一同學習擴香花的魅力。除了可以親自動手嘗試以外，老師還會帶領大小朋友一同學習利用五感感受周遭的美好、體驗日常的樂趣。一、活動講題：兒童親子芳香手作擴香花二、活動時間：4月13日(日) 14:00-16:00三、活動講師：陳麗英老師(芳香愛好家版主)四、活動地點：親子美育數位圖書館2樓多功能放映室(臺北市南港區研究院路2段61巷15號2樓)五、報名方式：線上報名：https://reurl.cc/36Qv6l六、活動對象：國小兒童及其家長(名額限定12組親子，活動開始後10分鐘未到者，則將名額開放現場候補參加者。)七、交通路線交通路線：https://reurl.cc/yYX9Xl', '臺北市立圖書館', '無資料', '2025-03-12 00:00:00', '2025-04-09 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A6CA673D15BABBD9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='親子美育數位圖書館-兒童親子芳香手作擴香花', `description`='&nbsp; 春季是百花勝放的季節，除了自然的花卉，生活中還有很多其他的方式可留下芬芳的痕跡。本次活動將由陳麗英老師引領學童一同學習擴香花的魅力。除了可以親自動手嘗試以外，老師還會帶領大小朋友一同學習利用五感感受周遭的美好、體驗日常的樂趣。一、活動講題：兒童親子芳香手作擴香花二、活動時間：4月13日(日) 14:00-16:00三、活動講師：陳麗英老師(芳香愛好家版主)四、活動地點：親子美育數位圖書館2樓多功能放映室(臺北市南港區研究院路2段61巷15號2樓)五、報名方式：線上報名：https://reurl.cc/36Qv6l六、活動對象：國小兒童及其家長(名額限定12組親子，活動開始後10分鐘未到者，則將名額開放現場候補參加者。)七、交通路線交通路線：https://reurl.cc/yYX9Xl', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-12 00:00:00', `end_date`='2025-04-09 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A6CA673D15BABBD9', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9356203', '4月12日(六) 舊莊分館「敦煌舞的印度基因」講座，歡迎參加！', '敦煌舞是從敦煌沙漠石窟中挖掘出的天女壁畫、菩薩雕塑等古代藝術遺產而來，融合薈萃了印度舞蹈之原形、西域舞蹈風格、中國民族舞蹈與現代的舞蹈技巧，模擬出歷代的舞蹈情狀。本次活動邀請飛天舞集藝術總監林珊影老師蒞臨演講，和大家分享這充滿特殊風情的美妙舞蹈。不管大朋友還是小朋友，歡迎來舊莊分館一起聽講座，為生活增添趣味！活動時間：4月12日(六)下午2時至4時活動講師：林珊影(飛天舞集藝術總監)活動地點：舊莊分館5樓多功能活動室(臺北市南港區舊莊街1段91巷11號5樓)活動對象：一般民眾，限額50人報名網址：https://docs.google.com/forms/d/e/1FAIpQLSfuegaBEOVJHe_v71A4V4q7o9ciyaio7I92qP7SyWYJyMOP_Q/viewform?usp=header（因場地能容納人數有限，活動建議事先報名）*「探索印度表演藝術」系列講座，歡迎踴躍參加交通路線：https://reurl.cc/RWQoln注意事項：一、因名額有限，請務必於報名前確認是否如期參與，以避免占用名額影響他人權益。二、報名成功者請務必準時與會，逾時10分後則不予入場，並開放現場參加者候補。三、若報名後無法參加，至遲於活動前1日以電話聯絡本館，以確保其他參加者權益。', '臺北市立圖書館', '無資料', '2025-03-12 00:00:00', '2025-04-12 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=983302A9953F631E', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月12日(六) 舊莊分館「敦煌舞的印度基因」講座，歡迎參加！', `description`='敦煌舞是從敦煌沙漠石窟中挖掘出的天女壁畫、菩薩雕塑等古代藝術遺產而來，融合薈萃了印度舞蹈之原形、西域舞蹈風格、中國民族舞蹈與現代的舞蹈技巧，模擬出歷代的舞蹈情狀。本次活動邀請飛天舞集藝術總監林珊影老師蒞臨演講，和大家分享這充滿特殊風情的美妙舞蹈。不管大朋友還是小朋友，歡迎來舊莊分館一起聽講座，為生活增添趣味！活動時間：4月12日(六)下午2時至4時活動講師：林珊影(飛天舞集藝術總監)活動地點：舊莊分館5樓多功能活動室(臺北市南港區舊莊街1段91巷11號5樓)活動對象：一般民眾，限額50人報名網址：https://docs.google.com/forms/d/e/1FAIpQLSfuegaBEOVJHe_v71A4V4q7o9ciyaio7I92qP7SyWYJyMOP_Q/viewform?usp=header（因場地能容納人數有限，活動建議事先報名）*「探索印度表演藝術」系列講座，歡迎踴躍參加交通路線：https://reurl.cc/RWQoln注意事項：一、因名額有限，請務必於報名前確認是否如期參與，以避免占用名額影響他人權益。二、報名成功者請務必準時與會，逾時10分後則不予入場，並開放現場參加者候補。三、若報名後無法參加，至遲於活動前1日以電話聯絡本館，以確保其他參加者權益。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=983302A9953F631E', `image_url`='[]';
