INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9370625', '臺北願景館即將在2025智慧城市展 3/18~3/21登場', '【臺北願景館】即將在2025智慧城市展 3/18~3/21登場快來一探究竟!臺北如何以AI驅動智慧城市的發展現場有集點送限量小禮物還有多項亮點互動️*消防車開箱、AI消防設備展示*AI眼底攝影機、AI專業醫療級12導程心電圖檢測*AI運動科學設備實機體驗*實機操作AI英語聽力練習、AI輔助手寫批閱臺北市政府願景館以「AI驅動&middot;未來臺北」為主軸預覽 #安全之都 &nbsp;#運動之都 #未來之都 的創新科技🚀親身體驗AI如何塑造未來臺北，共創智慧城市新典範!~趕快標註日曆️~一起來【南港展覽館2館1樓攤位P1013】體驗臺北的無限可能！#FutureTaipei #智慧城市展 #南港展覽館 #臺北願景─── 入場方式 ───◆憑國內參觀入場證線上登記https://smartcity.org.tw/m_login.php◆現場購票200元/人◆不開放未滿12歲以下兒童入場，勿穿涼鞋及拖鞋───展覽資訊───展覽日期｜2024/3/18~3/21開放時間｜10:00-18:00（展期最後一天僅至17:00）', '臺北市政府警察局刑事警察大隊', '無資料', '2025-03-18 00:00:00', '2025-03-21 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=98C904FDB2DC2FED', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺北願景館即將在2025智慧城市展 3/18~3/21登場', `description`='【臺北願景館】即將在2025智慧城市展 3/18~3/21登場快來一探究竟!臺北如何以AI驅動智慧城市的發展現場有集點送限量小禮物還有多項亮點互動️*消防車開箱、AI消防設備展示*AI眼底攝影機、AI專業醫療級12導程心電圖檢測*AI運動科學設備實機體驗*實機操作AI英語聽力練習、AI輔助手寫批閱臺北市政府願景館以「AI驅動&middot;未來臺北」為主軸預覽 #安全之都 &nbsp;#運動之都 #未來之都 的創新科技🚀親身體驗AI如何塑造未來臺北，共創智慧城市新典範!~趕快標註日曆️~一起來【南港展覽館2館1樓攤位P1013】體驗臺北的無限可能！#FutureTaipei #智慧城市展 #南港展覽館 #臺北願景─── 入場方式 ───◆憑國內參觀入場證線上登記https://smartcity.org.tw/m_login.php◆現場購票200元/人◆不開放未滿12歲以下兒童入場，勿穿涼鞋及拖鞋───展覽資訊───展覽日期｜2024/3/18~3/21開放時間｜10:00-18:00（展期最後一天僅至17:00）', `organizer`='臺北市政府警察局刑事警察大隊', `address`='無資料', `start_date`='2025-03-18 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=98C904FDB2DC2FED', `image_url`='[]';
