INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9370293', '南港樂運動愛健康-90天健康養成挑戰賽(3/17-7/17)', '臺北市南港區健康服務中心南港樂運動愛健康- 90天健康養成 挑戰賽活動時間: 114/3/17-114/7/17活動對象:18歲以上活動內容:活動期間內使用 `相同量測儀器`完成體重、體脂肪及肌肉量前後量測(量測時間需間隔 3個月 ，表單填寫(前測最晚 4/17 上傳,後測最晚 7/22 上傳)，填寫網址🏣量測地點(擇一):1.南港區行政中心1樓2.舞動陽光-成德國中運動中心(需線上預約，專人聯繫安排)，預約網址3.職場或健身房可量測體脂及肌肉量之場所🎁獎勵措施:1. 挑戰成功獎 :(前測體脂肪-後測體脂肪)+(後測肌肉量-前測肌肉量)為正值者，&nbsp;前100名可獲得200元7-11禮券2. 參加獎 :完成者皆可獲得精美禮品一份(限量200份)📢得獎公布及領獎資訊:⭐️ 公布時間 :114年7月31日📍 公布地點 :刊登於臺北市南港區健康服務中心官網、臉書、LINE⭐️ 領獎時間 :114年8月1日-9月15日(週一至週五8:30-17:30)📍 領取地點 :臺北市南港區健康服務中心7樓服務台(現場本人或委託領取)', '臺北市南港區健康服務中心', '無資料', '2025-03-17 00:00:00', '2025-07-17 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=DDC0829E8752F584', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南港樂運動愛健康-90天健康養成挑戰賽(3/17-7/17)', `description`='臺北市南港區健康服務中心南港樂運動愛健康- 90天健康養成 挑戰賽活動時間: 114/3/17-114/7/17活動對象:18歲以上活動內容:活動期間內使用 `相同量測儀器`完成體重、體脂肪及肌肉量前後量測(量測時間需間隔 3個月 ，表單填寫(前測最晚 4/17 上傳,後測最晚 7/22 上傳)，填寫網址🏣量測地點(擇一):1.南港區行政中心1樓2.舞動陽光-成德國中運動中心(需線上預約，專人聯繫安排)，預約網址3.職場或健身房可量測體脂及肌肉量之場所🎁獎勵措施:1. 挑戰成功獎 :(前測體脂肪-後測體脂肪)+(後測肌肉量-前測肌肉量)為正值者，&nbsp;前100名可獲得200元7-11禮券2. 參加獎 :完成者皆可獲得精美禮品一份(限量200份)📢得獎公布及領獎資訊:⭐️ 公布時間 :114年7月31日📍 公布地點 :刊登於臺北市南港區健康服務中心官網、臉書、LINE⭐️ 領獎時間 :114年8月1日-9月15日(週一至週五8:30-17:30)📍 領取地點 :臺北市南港區健康服務中心7樓服務台(現場本人或委託領取)', `organizer`='臺北市南港區健康服務中心', `address`='無資料', `start_date`='2025-03-17 00:00:00', `end_date`='2025-07-17 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=DDC0829E8752F584', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9370108', '獨居高齡者彩繪課程開放報名囉！歡迎踴躍報名參加！名額有限，額滿為止！', '為了鼓勵獨居長者走出家門，本中心與台北市東欣扶輪社共同開辦「我愛士林 彩繪獨居長者人生」課程，透過簡單繪畫方式-色鉛筆手繪，彩繪出美麗的人、事、物，以促進獨居長者手眼協調、動動腦訓練及心靈紓壓，進而促進長輩身心靈健康。一、課程時間：114年3/18-4/8每週二上午9:30-11:30 (共4次)二、活動地點:士林區行政中心2樓大會議室（中正路439號2樓）三、對象:士林區65歲以上獨居長者，名額30人四、報名方式:電話28813039分機7142&nbsp;連護理師報名五、詳情請洽報名表。', '臺北市士林區健康服務中心', '無資料', '2025-03-11 00:00:00', '2025-03-17 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=04F7C2E06BF655DB', '[]') ON DUPLICATE KEY UPDATE `activity_name`='獨居高齡者彩繪課程開放報名囉！歡迎踴躍報名參加！名額有限，額滿為止！', `description`='為了鼓勵獨居長者走出家門，本中心與台北市東欣扶輪社共同開辦「我愛士林 彩繪獨居長者人生」課程，透過簡單繪畫方式-色鉛筆手繪，彩繪出美麗的人、事、物，以促進獨居長者手眼協調、動動腦訓練及心靈紓壓，進而促進長輩身心靈健康。一、課程時間：114年3/18-4/8每週二上午9:30-11:30 (共4次)二、活動地點:士林區行政中心2樓大會議室（中正路439號2樓）三、對象:士林區65歲以上獨居長者，名額30人四、報名方式:電話28813039分機7142&nbsp;連護理師報名五、詳情請洽報名表。', `organizer`='臺北市士林區健康服務中心', `address`='無資料', `start_date`='2025-03-11 00:00:00', `end_date`='2025-03-17 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=04F7C2E06BF655DB', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9370105', '獨居高齡者正向心理與靈性健康促進課程開放報名囉！歡迎踴躍報名參加！名額有限，額滿為止！', '為了強化獨居高齡者的社交網絡、自我效能與正確的疾病健康知識，規劃「從心藝起．與快樂相遇」課程，以養生保健、藝術輔療及主題式生命回顧，進而降低寂寞感、提高正向情緒與幸福感受。一、課程時間：114年4/15-7/1每週二上午9:30-11:30 (共12次)二、活動地點:士林區行政中心2樓大會議室（中正路439號2樓）三、對象:士林區65歲以上獨居長者，名額30人四、報名方式:電話28813039分機714&nbsp;連護理師報名五、詳情請洽報名表。', '臺北市士林區健康服務中心', '無資料', '2025-03-11 00:00:00', '2025-03-17 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=2ADA929F6C25FAA2', '[]') ON DUPLICATE KEY UPDATE `activity_name`='獨居高齡者正向心理與靈性健康促進課程開放報名囉！歡迎踴躍報名參加！名額有限，額滿為止！', `description`='為了強化獨居高齡者的社交網絡、自我效能與正確的疾病健康知識，規劃「從心藝起．與快樂相遇」課程，以養生保健、藝術輔療及主題式生命回顧，進而降低寂寞感、提高正向情緒與幸福感受。一、課程時間：114年4/15-7/1每週二上午9:30-11:30 (共12次)二、活動地點:士林區行政中心2樓大會議室（中正路439號2樓）三、對象:士林區65歲以上獨居長者，名額30人四、報名方式:電話28813039分機714&nbsp;連護理師報名五、詳情請洽報名表。', `organizer`='臺北市士林區健康服務中心', `address`='無資料', `start_date`='2025-03-11 00:00:00', `end_date`='2025-03-17 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=2ADA929F6C25FAA2', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9369942', '石內都X遺物：美麗之物 (Relics: Beautiful Things)', '時代劇場：當代影像的複數演繹｜藝術家面對面座談系列石內都X遺物：美麗之物（Relics: Beautiful Things）座談內容涵蓋石內都的成長歷程與代表性的創作實踐；《ひろしま/廣島》系列與其文化背景的關係，以及作為女性創作者的獨特視角。時間：2025年3月29日（週六）14:00－15:30地點：臺北市立美術館3C迴廊（近三樓展場入口右側）講者：石內都｜參展藝術家全場以中日文進行，備有逐步口譯；免預約報名，自由入座，設50席講者介紹石內都 (Ishiuchi Miyako)&nbsp;1947年出生於日本群馬縣，成長於神奈川縣橫須賀市，專職攝影。1979年以《公寓》獲得第四屆木村伊平獎。2005年代表日本參加威尼斯雙年展，展出《母親》系列。2007年至今，她拍攝原子彈爆炸受害者的物品《ひろしま/廣島》系列，並於2013年獲得了日本紫絲帶榮譽勳章。2014年榮獲被稱作「攝影界的諾貝爾獎」之最高榮譽「哈蘇獎」。注意事項：&nbsp;&nbsp;&nbsp;&nbsp;。本活動須購買門票入館，購票資訊及得免費入館者請詳閱本館售票頁面&nbsp;&nbsp;&nbsp;&nbsp;。議程內容如有更動，請以官網公告為準&nbsp; #教育', '臺北市立美術館', '無資料', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=DEB773D66E5193A3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='石內都X遺物：美麗之物 (Relics: Beautiful Things)', `description`='時代劇場：當代影像的複數演繹｜藝術家面對面座談系列石內都X遺物：美麗之物（Relics: Beautiful Things）座談內容涵蓋石內都的成長歷程與代表性的創作實踐；《ひろしま/廣島》系列與其文化背景的關係，以及作為女性創作者的獨特視角。時間：2025年3月29日（週六）14:00－15:30地點：臺北市立美術館3C迴廊（近三樓展場入口右側）講者：石內都｜參展藝術家全場以中日文進行，備有逐步口譯；免預約報名，自由入座，設50席講者介紹石內都 (Ishiuchi Miyako)&nbsp;1947年出生於日本群馬縣，成長於神奈川縣橫須賀市，專職攝影。1979年以《公寓》獲得第四屆木村伊平獎。2005年代表日本參加威尼斯雙年展，展出《母親》系列。2007年至今，她拍攝原子彈爆炸受害者的物品《ひろしま/廣島》系列，並於2013年獲得了日本紫絲帶榮譽勳章。2014年榮獲被稱作「攝影界的諾貝爾獎」之最高榮譽「哈蘇獎」。注意事項：&nbsp;&nbsp;&nbsp;&nbsp;。本活動須購買門票入館，購票資訊及得免費入館者請詳閱本館售票頁面&nbsp;&nbsp;&nbsp;&nbsp;。議程內容如有更動，請以官網公告為準&nbsp; #教育', `organizer`='臺北市立美術館', `address`='無資料', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=DEB773D66E5193A3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9369941', '羅晟文X降維陷阱：我們與扁掉的動物們', '時代劇場：當代影像的複數演繹｜藝術家面對面座談系列羅晟文X降維陷阱：我們與扁掉的動物們時間：2025年3月30日（週日）14:00－16:00地點：臺北市立美術館3C迴廊（近三樓展場入口右側）主持：　　　劉偉蘋｜「挺挺動物應援團」創辦人與談：　　　羅晟文｜參展藝術家　　　林德恩｜農業部生物多樣性研究所副研究員、「路殺社」社長　　　曾翊捷｜金工珠寶藝術家免預約報名，自由入座，設50席座談簡介我們也許不常留意生活中的野生動物，但偶爾會突然看到路上扁掉的各種動物。在台灣的各類道路上，每年約有1,500萬至2,000萬隻陸生脊椎動物遭車輛撞擊。想趕快到達目的地是人之常情，但道路也因此成為一種危險的人造棲地，對許多野生動物、保育類動物造成生存威脅。如何重新連結車上的人類與車外的生態環境？參與式創作如何介入路殺議題？本活動由「挺挺動物應援團」創辦人劉偉蘋主持，邀請「時代劇場」藝術家羅晟文、生物多樣性研究所副研究員/「路殺社」社長林德恩，與關注生態的珠寶設計師曾翊捷，介紹於本館「時代劇場」展出的大型尋寶遊戲《看路》，和同時在南投集集生多所舉辦的「保育我最&ldquo;行&rdquo;一起平安歸」特展，共同梳理台灣當前的路殺課題、公民科學參與經驗，以及「遊戲」在生態議題中的角色。注意事項：&nbsp;&nbsp;&nbsp;&nbsp;。本活動須購買門票入館，購票資訊及得免費入館者請詳閱本館售票頁面&nbsp;&nbsp;&nbsp;&nbsp;。議程內容如有更動，請以官網公告為準&nbsp; #教育', '臺北市立美術館', '無資料', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=0E1F0BCE7D3A251E', '[]') ON DUPLICATE KEY UPDATE `activity_name`='羅晟文X降維陷阱：我們與扁掉的動物們', `description`='時代劇場：當代影像的複數演繹｜藝術家面對面座談系列羅晟文X降維陷阱：我們與扁掉的動物們時間：2025年3月30日（週日）14:00－16:00地點：臺北市立美術館3C迴廊（近三樓展場入口右側）主持：　　　劉偉蘋｜「挺挺動物應援團」創辦人與談：　　　羅晟文｜參展藝術家　　　林德恩｜農業部生物多樣性研究所副研究員、「路殺社」社長　　　曾翊捷｜金工珠寶藝術家免預約報名，自由入座，設50席座談簡介我們也許不常留意生活中的野生動物，但偶爾會突然看到路上扁掉的各種動物。在台灣的各類道路上，每年約有1,500萬至2,000萬隻陸生脊椎動物遭車輛撞擊。想趕快到達目的地是人之常情，但道路也因此成為一種危險的人造棲地，對許多野生動物、保育類動物造成生存威脅。如何重新連結車上的人類與車外的生態環境？參與式創作如何介入路殺議題？本活動由「挺挺動物應援團」創辦人劉偉蘋主持，邀請「時代劇場」藝術家羅晟文、生物多樣性研究所副研究員/「路殺社」社長林德恩，與關注生態的珠寶設計師曾翊捷，介紹於本館「時代劇場」展出的大型尋寶遊戲《看路》，和同時在南投集集生多所舉辦的「保育我最&ldquo;行&rdquo;一起平安歸」特展，共同梳理台灣當前的路殺課題、公民科學參與經驗，以及「遊戲」在生態議題中的角色。注意事項：&nbsp;&nbsp;&nbsp;&nbsp;。本活動須購買門票入館，購票資訊及得免費入館者請詳閱本館售票頁面&nbsp;&nbsp;&nbsp;&nbsp;。議程內容如有更動，請以官網公告為準&nbsp; #教育', `organizer`='臺北市立美術館', `address`='無資料', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=0E1F0BCE7D3A251E', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9369943', '「想像驚奇箱：物件的故事」親子工作坊', '「想像驚奇箱：物件的故事」親子工作坊本次工作坊配合「靜．物」展覽，以「想像驚奇箱」為主軸，從靜物畫作品的構圖出發，帶領參與者從分析、觀看畫面構圖的基本元素，提出各自解讀背後事件與故事的想像詮釋。並利用個自的物件嘗試擺放畫面，透過構圖想像創造畫面的事件、成因與人物，以畫面創造故敘事。「想像驚奇箱」設定了「物件的故事」、「物件接龍」及「流動的物件畫」三大主題，本次為「物件的故事」：從展出作品的靜物畫出發，想像是什麼原因創造了畫面，畫家又為什麼想要畫下這樣的畫面，一起來為靜物構圖說故事。【活動場次】2025年4月6日(日) 14:00-16:00【活動對象】活動對象｜限15組，9-12歲小朋友（親子1小+1大）【活動報名與費用】**請穿著舒適、容易伸展之衣物**請事先於本網頁預約報名**活動免費參加，入館請依本館購票辦法購票**如遇颱風等不可抗力之因素，將另行公告是否取消或延期&nbsp;&nbsp;【工作坊網路預約注意事項】2025年3月25日（二）&nbsp;10:00&nbsp;起開放線上報名建議使用電腦操作；手機因版本而異，操作步驟不同不建議使用報名成功後，系統會自動發送錄取通知信至e-mail；相關活動通知以e-mail聯繫為準，請務必填寫正確e-mail因系統區別之故，一個e-mail帳號限報名一次如遇無法參與之情況，請務必事先線上取消或來電告知，將名額釋出給其他參加者。【工作坊報到及現場候補注意事項】工作坊報到活動開始前15分鐘進行報到，請務必準時於兒藝中心諮詢台報到活動開始前5分鐘未報到者，將釋出名額予現場候補之參加者依順序遞補為確保參加品質，工作坊設有年齡及人數限制，報到時請主動提示年齡證明文件（健保卡等），以便現場人員進行驗證&nbsp;現場候補視網路預約報名報到狀況開放現場候補名額，請於地下樓諮詢台填寫候補報名表於每場次活動前30分鐘開放填寫現場候補報名表，活動前5分鐘開始候補程序&nbsp;為確保參加品質，工作坊設有年齡及人數限制，希望每位參與者和我們共同維護工作坊的規範，一同創造豐富的藝術學習經驗。若有以下情況，本館保有取消參加資格之權利：年齡不符工作坊設定、未攜帶年齡證明文件、工作坊未準時報到&nbsp;&nbsp;工作坊帶領老師｜囝仔人不設限題材、場域、形式的可能，回歸單純的「玩」心一如「囝仔人」的命名，我們希望如孩童般，保持童心與好奇，嘗試物件、光影、偶戲的各種形式，盡情探索日常細節作為創作素材，延展物件的想像與創發，戲劇創作外，也研發結合地域特質、文化的主題式兒童戲劇課程教案，以及任何新奇好玩的藝術形式。&nbsp; #教育', '臺北市立美術館', '無資料', '2025-04-06 00:00:00', '2025-04-06 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F0F8DA3C508BBBF8', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「想像驚奇箱：物件的故事」親子工作坊', `description`='「想像驚奇箱：物件的故事」親子工作坊本次工作坊配合「靜．物」展覽，以「想像驚奇箱」為主軸，從靜物畫作品的構圖出發，帶領參與者從分析、觀看畫面構圖的基本元素，提出各自解讀背後事件與故事的想像詮釋。並利用個自的物件嘗試擺放畫面，透過構圖想像創造畫面的事件、成因與人物，以畫面創造故敘事。「想像驚奇箱」設定了「物件的故事」、「物件接龍」及「流動的物件畫」三大主題，本次為「物件的故事」：從展出作品的靜物畫出發，想像是什麼原因創造了畫面，畫家又為什麼想要畫下這樣的畫面，一起來為靜物構圖說故事。【活動場次】2025年4月6日(日) 14:00-16:00【活動對象】活動對象｜限15組，9-12歲小朋友（親子1小+1大）【活動報名與費用】**請穿著舒適、容易伸展之衣物**請事先於本網頁預約報名**活動免費參加，入館請依本館購票辦法購票**如遇颱風等不可抗力之因素，將另行公告是否取消或延期&nbsp;&nbsp;【工作坊網路預約注意事