INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cfb7a107f3d4433af9554f', '免費講座 - 外食族必學！營養師的健康聰明點餐術', '來自美國專業生醫團隊的「UniTAIR」攜手好樣「VVG」集團一起舉辦講座，與民眾面對面交流啦！ 特邀知性美麗又有多重身分的營養師黃酀茙與#好樣主廚 分享寶貴的健康知識 台灣民眾每週外食機率高達七成，因為外食營養十分不均衡，會導致身體一步一步地提高肥胖、慢性病等風險！要怎麼吃才能均衡美味與營養？我們在好樣餐桌餐廳為你解答各種健康疑難雜症！', '好樣本事股份有限公司', '臺北市松山區民生東路五段237號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', 'VVG Table', 25.05999101, 121.5575876, '無資料', 'https://www.accupass.com/go/vvglecture_yenny0329', '[]') ON DUPLICATE KEY UPDATE `activity_name`='免費講座 - 外食族必學！營養師的健康聰明點餐術', `description`='來自美國專業生醫團隊的「UniTAIR」攜手好樣「VVG」集團一起舉辦講座，與民眾面對面交流啦！ 特邀知性美麗又有多重身分的營養師黃酀茙與#好樣主廚 分享寶貴的健康知識 台灣民眾每週外食機率高達七成，因為外食營養十分不均衡，會導致身體一步一步地提高肥胖、慢性病等風險！要怎麼吃才能均衡美味與營養？我們在好樣餐桌餐廳為你解答各種健康疑難雜症！', `organizer`='好樣本事股份有限公司', `address`='臺北市松山區民生東路五段237號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='VVG Table', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='https://www.accupass.com/go/vvglecture_yenny0329', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cfe11f8f15adefa04e0c72', '身聲劇場2025第一號全新製作《落頭氏》', '2025身聲劇場全新製作《落頭氏》\r\n流離與游離、馬來西亞華人、女性、傳說\r\n現場音樂x肢體x吟唱x戲劇\r\n \r\n阮的身驅是一列無頭的火車\r\n阮的身驅是一支無腳的船仔\r\n \r\n我的身體在陽光下頭塞在陰影裡。我的頭在海上身體在叢林。哪個國家愛我的頭哪個國家需要我的身體。我連「這裡、那裡」都沒有。這並不是一個鬼故事，而是一段思念之歌、記憶之詩。\r\n會飛的人頭傳說，從中國到印尼、越南、寮國、馬來西亞等地盛傳，身聲劇場此次幽幽召喚出的既非身世之謎、亦非遠古傳說，竟是斷代女性異人錄。由資深創作者暨表演者莊惠勻、劉佩芬與陳姿吟共同演出，《落頭氏》除了再次發揮演樂舞合一的核心特色，融入意象的視覺、戲劇與吟唱，更以肢體與現場音樂娓娓道來逆著時間而行的南洋遺民或疑民，在中心與邊緣、真實與想像繼續穿梭、挪移、雜揉交錯。\r\n\r\n【費用】\r\n\r\n全票：800 元\r\n\r\n◎早鳥優惠75折優待，4/8止。\r\n◎兩廳院會員、學生（需憑證入場）9折優惠。\r\n◎「牯嶺街小劇場燈亮有戲會員」8折優惠。\r\n◎身心障礙人士及陪同者1名購票5折優待，入場時應出示身心障礙手冊，陪同者與身障者需同時入場。\r\n◎年滿65歲以上長者可享5折優待，入場時請出示有效證件。\r\n◎身聲柱腳會會員享75折優惠。\r\n\r\n【展演須知】\r\n．入場時間：演前15分鐘開放入場。\r\n\r\n\r\n．演出全長：60分鐘，無中場休息。\r\n\r\n\r\n．語言：中文、檳城福建話(有中文字幕)。\r\n\r\n\r\n．建議10歲以上觀眾欣賞。\r\n\r\n\r\n．12歲以下孩童建議由家長或成年親友陪同進場觀賞。\r\n\r\n\r\n．遲到觀眾須等候帶位，無法退換票。\r\n\r\n\r\n．須持紙本票券入場，無開放電子票。牯嶺街小劇場為售票端點，為避免取票人潮眾多及維護觀賞權益，敬請現場取票觀眾提早到場。\r\n\r\n\r\n．小劇場座位較緊密，建議輕裝蒞臨劇場看戲。\r\n\r\n\r\n．因場地位置有限，如有輪椅席以及輪椅陪同席之需求，請於購票前聯繫主辦單位協助處理。聯繫電話 (02)2809-5885。\r\n', '身聲劇場', '臺北市臺北市中正區牯嶺街5巷2號', '2025-05-02 00:00:00', '2025-05-02 00:00:00', '牯嶺街小劇場一樓實驗劇場', 0, 0, '【票價】\r\n\r\n全票：800 元\r\n\r\n◎早鳥優惠75折優待，4/8止。\r\n◎兩廳院會員、學生（需憑證入場）9折優惠。\r\n◎「牯嶺街小劇場燈亮有戲會員」8折優惠。\r\n◎身心障礙人士及陪同者1名購票5折優待，入場時應出示身心障礙手冊，陪同者與身障者需同時入場。\r\n◎年滿65歲以上長者可享5折優待，入場時請出示有效證件。\r\n◎身聲柱腳會會員享75折優惠。\r\n', 'https://www.opentix.life/event/1896901246930100225', '[]') ON DUPLICATE KEY UPDATE `activity_name`='身聲劇場2025第一號全新製作《落頭氏》', `description`='2025身聲劇場全新製作《落頭氏》\r\n流離與游離、馬來西亞華人、女性、傳說\r\n現場音樂x肢體x吟唱x戲劇\r\n \r\n阮的身驅是一列無頭的火車\r\n阮的身驅是一支無腳的船仔\r\n \r\n我的身體在陽光下頭塞在陰影裡。我的頭在海上身體在叢林。哪個國家愛我的頭哪個國家需要我的身體。我連「這裡、那裡」都沒有。這並不是一個鬼故事，而是一段思念之歌、記憶之詩。\r\n會飛的人頭傳說，從中國到印尼、越南、寮國、馬來西亞等地盛傳，身聲劇場此次幽幽召喚出的既非身世之謎、亦非遠古傳說，竟是斷代女性異人錄。由資深創作者暨表演者莊惠勻、劉佩芬與陳姿吟共同演出，《落頭氏》除了再次發揮演樂舞合一的核心特色，融入意象的視覺、戲劇與吟唱，更以肢體與現場音樂娓娓道來逆著時間而行的南洋遺民或疑民，在中心與邊緣、真實與想像繼續穿梭、挪移、雜揉交錯。\r\n\r\n【費用】\r\n\r\n全票：800 元\r\n\r\n◎早鳥優惠75折優待，4/8止。\r\n◎兩廳院會員、學生（需憑證入場）9折優惠。\r\n◎「牯嶺街小劇場燈亮有戲會員」8折優惠。\r\n◎身心障礙人士及陪同者1名購票5折優待，入場時應出示身心障礙手冊，陪同者與身障者需同時入場。\r\n◎年滿65歲以上長者可享5折優待，入場時請出示有效證件。\r\n◎身聲柱腳會會員享75折優惠。\r\n\r\n【展演須知】\r\n．入場時間：演前15分鐘開放入場。\r\n\r\n\r\n．演出全長：60分鐘，無中場休息。\r\n\r\n\r\n．語言：中文、檳城福建話(有中文字幕)。\r\n\r\n\r\n．建議10歲以上觀眾欣賞。\r\n\r\n\r\n．12歲以下孩童建議由家長或成年親友陪同進場觀賞。\r\n\r\n\r\n．遲到觀眾須等候帶位，無法退換票。\r\n\r\n\r\n．須持紙本票券入場，無開放電子票。牯嶺街小劇場為售票端點，為避免取票人潮眾多及維護觀賞權益，敬請現場取票觀眾提早到場。\r\n\r\n\r\n．小劇場座位較緊密，建議輕裝蒞臨劇場看戲。\r\n\r\n\r\n．因場地位置有限，如有輪椅席以及輪椅陪同席之需求，請於購票前聯繫主辦單位協助處理。聯繫電話 (02)2809-5885。\r\n', `organizer`='身聲劇場', `address`='臺北市臺北市中正區牯嶺街5巷2號', `start_date`='2025-05-02 00:00:00', `end_date`='2025-05-02 00:00:00', `location`='牯嶺街小劇場一樓實驗劇場', `latitude`=0, `longitude`=0, `ticket_price`='【票價】\r\n\r\n全票：800 元\r\n\r\n◎早鳥優惠75折優待，4/8止。\r\n◎兩廳院會員、學生（需憑證入場）9折優惠。\r\n◎「牯嶺街小劇場燈亮有戲會員」8折優惠。\r\n◎身心障礙人士及陪同者1名購票5折優待，入場時應出示身心障礙手冊，陪同者與身障者需同時入場。\r\n◎年滿65歲以上長者可享5折優待，入場時請出示有效證件。\r\n◎身聲柱腳會會員享75折優惠。\r\n', `source_url`='https://www.opentix.life/event/1896901246930100225', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67cfecc007f3d4433af95550', '你的孩子還是孩子嗎？─關於青少年的身心困擾', '【情感教育與情緒管理系列講座】\r\n你的孩子還是孩子嗎？──關於青少年的身心困擾\r\n| 講者：林洪異 醫師（中國醫藥大學新竹附設醫院身心醫學科主治醫師）\r\n\r\n| 日期：2025年3月28日（五）下午14:30–16:30\r\n\r\n| 地點：Wells Space 共同空間（新竹市東區林森路32號2樓，新竹火車站步行約4分）\r\n\r\n| 活動對象：市民朋友、社會大眾，並可核給「公務人員終身學習時數」、「教師研習時數」2小時。\r\n\r\n| 活動資訊：https://reurl.cc/G593zd\r\n\r\n| 報名連結：https://reurl.cc/qnEbqD\r\n\r\n| 更多活動：https://www.facebook.com/fixcd\r\n\r\n| 主辦單位：財團法人社教文化基金會', '財團法人社教文化基金會', '新竹市東區林森路32號2樓', '2025-03-28 00:00:00', '2025-03-28 00:00:00', 'Wells Space共同空間(新竹火車站步行4分鐘)', 24.79028174, 120.9927505, '無資料', 'https://reurl.cc/qnEbqD', '[]') ON DUPLICATE KEY UPDATE `activity_name`='你的孩子還是孩子嗎？─關於青少年的身心困擾', `description`='【情感教育與情緒管理系列講座】\r\n你的孩子還是孩子嗎？──關於青少年的身心困擾\r\n| 講者：林洪異 醫師（中國醫藥大學新竹附設醫院身心醫學科主治醫師）\r\n\r\n| 日期：2025年3月28日（五）下午14:30–16:30\r\n\r\n| 地點：Wells Space 共同空間（新竹市東區林森路32號2樓，新竹火車站步行約4分）\r\n\r\n| 活動對象：市民朋友、社會大眾，並可核給「公務人員終身學習時數」、「教師研習時數」2小時。\r\n\r\n| 活動資訊：https://reurl.cc/G593zd\r\n\r\n| 報名連結：https://reurl.cc/qnEbqD\r\n\r\n| 更多活動：https://www.facebook.com/fixcd\r\n\r\n| 主辦單位：財團法人社教文化基金會', `organizer`='財團法人社教文化基金會', `address`='新竹市東區林森路32號2樓', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='Wells Space共同空間(新竹火車站步行4分鐘)', `latitude`=24.79028174, `longitude`=120.9927505, `ticket_price`='無資料', `source_url`='https://reurl.cc/qnEbqD', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9371577', '天母分館「天母水道祭：山光水色」3月熱鬧登場，歡迎大小朋友共襄盛舉！', '天母地區2025年的水道祭活動隆重登場！3月11日上午從三玉宮出發，揭開今年度水道祭活動的序幕。天母地區的學生們以「森林」為主題精心裝扮，一路踩街遊行至三角埔發電廠參加水道祭典禮儀式與多所社教單位設置的闖關活動。配合天母水道祭的舉辦，3月11日至4月30日天母分館策劃「天母水道祭：山光水色」系列活動，包括「SDGs：山光水色‧閱讀永續」主題書展、「世界水資源日：保護冰川」Quiz、「心視界假日電影院」。而在4月22日「世界地球日」，林老師會為小朋友們說特別的故事。「2025天母水道祭主題創作得獎作品特展」3月12日起在天母分館展出至4月30日，邀請各位大小朋友前來同樂，來天母分館看展、閱讀、聽故事、看電影！一、活動內容（一）天母水道祭趣味闖關1. 時間：3月11日上午2. 地點：三角埔發電廠（臺北市士林區中山北路7段末端）（二）「SDGs：山光水色‧閱讀永續」主題書展1. 時間：3月11日至4月30日2. 地點：天母分館3樓（三）2025天母水道祭主題創作得獎作品特展1. 時間：3月12日至4月30日2. 地點：天母分館3樓（四）「世界水資源日：保護冰川」Quiz1. 時間：3月22日2. 地點：天母分館3樓櫃檯3. 參加方式：借閱5本書，完成「保護冰川」問答，使用閱讀存摺點數120點，即可兌換風獅爺杯墊1個，數量有限，兌完為止。（※每張借閱證限參加1次）（五）林老師說特別的故事1. 時間：4月22日，下午2:30-4:002. 地點：天母分館3樓兒童室（六）心視界假日電影院1. 時間：下午2:00起4月6日，《哪啊哪啊~神去村》（普遍級，片長116分）4月20日，《哆啦A夢:大雄與奇跡之島》（普遍級，片長99分）2. 地點：天母分館3樓兒童室3. 全程參與當日影片欣賞者，可獲得閱讀存摺點數5點。二、活動對象：一般民眾三、交通資訊：https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=50DF61E26C3A0BFA&sms=CFFFC938B352678A四、洽詢管道：（一）電話：02-28736203（二）Facebook粉絲專頁：https://www.facebook.com/tpmltianmulibrary/（三）IG：https://www.instagram.com/tianmulibrary/', '臺北市立圖書館', '無資料', '2025-03-11 00:00:00', '2025-04-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=94B90711B501D2A0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='天母分館「天母水道祭：山光水色」3月熱鬧登場，歡迎大小朋友共襄盛舉！', `description`='天母地區2025年的水道祭活動隆重登場！3月11日上午從三玉宮出發，揭開今年度水道祭活動的序幕。天母地區的學生們以「森林」為主題精心裝扮，一路踩街遊行至三角埔發電廠參加水道祭典禮儀式與多所社教單位設置的闖關活動。配合天母水道祭的舉辦，3月11日至4月30日天母分館策劃「天母水道祭：山光水色」系列活動，包括「SDGs：山光水色‧閱讀永續」主題書展、「世界水資源日：保護冰川」Quiz、「心視界假日電影院」。而在4月22日「世界地球日」，林老師會為小朋友們說特別的故事。「2025天母水道祭主題創作得獎作品特展」3月12日起在天母分館展出至4月30日，邀請各位大小朋友前來同樂，來天母分館看展、閱讀、聽故事、看電影！一、活動內容（一）天母水道祭趣味闖關1. 時間：3月11日上午2. 地點：三角埔發電廠（臺北市士林區中山北路7段末端）（二）「SDGs：山光水色‧閱讀永續」主題書展1. 時間：3月11日至4月30日2. 地點：天母分館3樓（三）2025天母水道祭主題創作得獎作品特展1. 時間：3月12日至4月30日2. 地點：天母分館3樓（四）「世界水資源日：保護冰川」Quiz1. 時間：3月22日2. 地點：天母分館3樓櫃檯3. 參加方式：借閱5本書，完成「保護冰川」問答，使用閱讀存摺點數120點，即可兌換風獅爺杯墊1個，數量有限，兌完為止。（※每張借閱證限參加1次）（五）林老師說特別的故事1. 時間：4月22日，下午2:30-4:002. 地點：天母分館3樓兒童室（六）心視界假日電影院1. 時間：下午2:00起4月6日，《哪啊哪啊~神去村》（普遍級，片長116分）4月20日，《哆啦A夢:大雄與奇跡之島》（普遍級，片長99分）2. 地點：天母分館3樓兒童室3. 全程參與當日影片欣賞者，可獲得閱讀存摺點數5點。二、活動對象：一般民眾三、交通資訊：https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=50DF61E26C3A0BFA&sms=CFFFC938B352678A四、洽詢管道：（一）電話：02-28736203（二）Facebook粉絲專頁：https://www.facebook.com/tpmltianmulibrary/（三）IG：https://www.instagram.com/tianmulibrary/', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-11 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=94B90711B501D2A0', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9371572', '臺北市內湖區公所-114年度人口政策宣導活動 「內湖親子電影院-飛兔學園：金蛋守護者」', '親愛的家長們，還在等什麼？快來參加內湖親子電影院活動吧！活動日期：114年4月12日（週六）上午9時至12時114年4月19日（週六）上午9時至12時活動地點：內湖區公所8樓大禮堂我們誠摯邀請您帶著孩子來欣賞《飛兔學園：金蛋守護者》，並參加精彩的問答闖關活動！參加的小朋友可獲得健達出奇蛋等驚喜獎勵，每位來賓還可享用免費爆米花，絕對是親子互動的好機會。名額有限，每場次僅有100名孩子名額，快到內湖區公所報名參加吧！讓我們一起度過一個充滿歡樂與回憶的觀影時光！如有疑問，請聯繫內湖區公所人文課洪小姐2792-5828分機605，我們期待您的到來！', '臺北市內湖區公所', '無資料', '2025-04-12 00:00:00', '2025-04-19 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=6BA0A977608750F9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺北市內湖區公所-114年度人口政策宣導活動 「內湖親子電影院-飛兔學園：金蛋守護者」', `description`='親愛的家長們，還在等什麼？快來參加內湖親子電影院活動吧！活動日期：114年4月12日（週六）上午9時至12時114年4月19日（週六）上午9時至12時活動地點：內湖區公所8樓大禮堂我們誠摯邀請您帶著孩子來欣賞《飛兔學園：金蛋守護者》，並參加精彩的問答闖關活動！參加的小朋友可獲得健達出奇蛋等驚喜獎勵，每位來賓還可享用免費爆米花，絕對是親子互動的好機會。名額有限，每場次僅有100名孩子名額，快到內湖區公所報名參加吧！讓我們一起度過一個充滿歡樂與回憶的觀影時光！如有疑問，請聯繫內湖區公所人文課洪小姐2792-5828分機605，我們期待您的到來！', `organizer`='臺北市內湖區公所', `address`='無資料', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=6BA0A977608750F9', `image_url`='[]';
