INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9371155', '「雲端發票四部曲，快樂得獎進行曲」租稅暨納稅者權利保護宣導', '☕時間：114年3月22日(六) 12:00至19:00☕ 地點：松山車站交4廣場23號攤位☕ 活動內容：雲端發票換好禮：完成以下任務，即可兌換宣導品1份，每人每次限換5份。1.&nbsp; 完成【雲端發票四部曲】其中任2部曲。2.&nbsp; 由本處代為捐贈未開獎未書立買受人統一編號且金額10元以上之雲端發票。3.&nbsp; 已捐贈之發票無法退還。4.&nbsp; 數量有限，換完為止。☕ 租稅及納保宣導訊息：⇨下載統一發票兌獎APP，輕鬆完成雲端發票樂透四部曲⇨ 租稅正義為你在，賦稅人權讚起來⇨ 稅籍異動即時通，移轉資訊早知道⇨ 地稅小幫手來！24小時智能客服+LINE隨手查⇨ 活動現場可兌換宣導品（只有收雲端發票喔～^^）：&diams; IKEA BEVARA袋子封口夾，碳黑色/深黃色 ------------------------------------------- 7張/1組&diams; IKEA &Ouml;RINGABBORR，袋子封口夾 9件組，彩色 -------------------------------- 15張/1組&diams; 德國雙人牌 ZWILLING TWIN削皮刀 ------------------------------------------------- 100張/1把&diams; 臺北市專用垃圾袋5公升 --------------------------------------------------------------------- 5張/1包&diams; 動物刺繡方巾 ----------------------------------------------------------------------------------- 3張/1條&diams; 立體密封袋（18cm * 20cm）--------------------------------------------------------------- 5張/1包&diams; 動物造型擦手巾 -------------------------------------------------------------------------------- 5張/1條☕ 租稅及納保宣導訊息：謹言慎行少煩惱，廉政倫理要遵行', '臺北市稅捐稽徵處', '無資料', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1EC9563A63CDFD38', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「雲端發票四部曲，快樂得獎進行曲」租稅暨納稅者權利保護宣導', `description`='☕時間：114年3月22日(六) 12:00至19:00☕ 地點：松山車站交4廣場23號攤位☕ 活動內容：雲端發票換好禮：完成以下任務，即可兌換宣導品1份，每人每次限換5份。1.&nbsp; 完成【雲端發票四部曲】其中任2部曲。2.&nbsp; 由本處代為捐贈未開獎未書立買受人統一編號且金額10元以上之雲端發票。3.&nbsp; 已捐贈之發票無法退還。4.&nbsp; 數量有限，換完為止。☕ 租稅及納保宣導訊息：⇨下載統一發票兌獎APP，輕鬆完成雲端發票樂透四部曲⇨ 租稅正義為你在，賦稅人權讚起來⇨ 稅籍異動即時通，移轉資訊早知道⇨ 地稅小幫手來！24小時智能客服+LINE隨手查⇨ 活動現場可兌換宣導品（只有收雲端發票喔～^^）：&diams; IKEA BEVARA袋子封口夾，碳黑色/深黃色 ------------------------------------------- 7張/1組&diams; IKEA &Ouml;RINGABBORR，袋子封口夾 9件組，彩色 -------------------------------- 15張/1組&diams; 德國雙人牌 ZWILLING TWIN削皮刀 ------------------------------------------------- 100張/1把&diams; 臺北市專用垃圾袋5公升 --------------------------------------------------------------------- 5張/1包&diams; 動物刺繡方巾 ----------------------------------------------------------------------------------- 3張/1條&diams; 立體密封袋（18cm * 20cm）--------------------------------------------------------------- 5張/1包&diams; 動物造型擦手巾 -------------------------------------------------------------------------------- 5張/1條☕ 租稅及納保宣導訊息：謹言慎行少煩惱，廉政倫理要遵行', `organizer`='臺北市稅捐稽徵處', `address`='無資料', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1EC9563A63CDFD38', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9370869', '歡慶兒童節！ 北市圖邀請大小朋友一起參加臺北兒童月活動！', '一年一度的兒童節來囉！為慶祝兒童月，北市圖特別在兒童月期間，於吉利分館、萬興分館、稻香分館、永春分館、廣慈分館、清江分館辦理手作活動，活動主題橫跨書籍結構認識創意、情緒、木工等不同領域，內容豐富又多元。此外，文山分館及內湖分館也辦理林老師說故事特別活動，內容精彩可期，歡迎各位小朋友和家長一同參與，在這個兒童節，與家人共創美好的回憶!兒童活動兒童活動日期館別走入繪本的世界-從小認識書本與閱讀／謝心瑜老師（報名請點此）4/5（六）14:00-16:00吉利分館7樓多功能教室2820-1633限額15組親子(適合3-9歲兒童)須事先以網路報名、電話報名、臨櫃報名（3/14 09:00開放報名）捏出創意共學玩黏土／呂靜玉老師4/12 (六)10:00-12:00萬興分館 5樓多功能活動室2234-5501限額15組親子(每位家長至多攜帶1名子女，兒童需滿6歲，每組限領1份材料)須事先以電話報名、臨櫃報名（3/14開放報名）我的情緒房間－拼貼創意親子手作／黃兆逸老師（報名請點此）4/12 (六)10:00-12:00稻香分館 9樓多功能活動室2894-0662限額15組親子（國小1-4年級） 須事先以網路報名（3/25 09:00開放報名）地球動脈彩繪／詹歷蓁老師（報名請點此）4/13 (日)10:00-12:00永春分館 4樓多功能教室2760-9730限額15組親子須事先以網路報名 （3/25 09:00開放報名）城市木業風-木作小黑板體驗／江鳴謙老師（報名請點此）4/19 (六)10:00-12:00廣慈分館 4樓多功能活動室2727-7872限額15組親子須事先以網路報名（3/25 09:00開放報名）玩出創造力-生肖故事與手作童玩交織的火花／張宇文老師（報名請點此）4/26(六)10:00-12:00清江分館 3樓多功能活動室2896-0315限額15組親子須事先以網路報名、電話報名、臨櫃報名（3/25 09:00開放報名）林老師說故事林老師說故事日期館別「假面派對，繪本角色扮演」 林老師特別活動4/12（六）14:30-16:00內湖分館 視聽室2791-8772限額15組無須事先報名紅包／林老師說故事兒童劇團4/19（六）14:30-16:00文山分館 9樓多功能活動室2931-5339無須事先報名', '臺北市立圖書館', '無資料', '2025-03-12 00:00:00', '2025-04-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=D40E83D14B7A52A0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歡慶兒童節！ 北市圖邀請大小朋友一起參加臺北兒童月活動！', `description`='一年一度的兒童節來囉！為慶祝兒童月，北市圖特別在兒童月期間，於吉利分館、萬興分館、稻香分館、永春分館、廣慈分館、清江分館辦理手作活動，活動主題橫跨書籍結構認識創意、情緒、木工等不同領域，內容豐富又多元。此外，文山分館及內湖分館也辦理林老師說故事特別活動，內容精彩可期，歡迎各位小朋友和家長一同參與，在這個兒童節，與家人共創美好的回憶!兒童活動兒童活動日期館別走入繪本的世界-從小認識書本與閱讀／謝心瑜老師（報名請點此）4/5（六）14:00-16:00吉利分館7樓多功能教室2820-1633限額15組親子(適合3-9歲兒童)須事先以網路報名、電話報名、臨櫃報名（3/14 09:00開放報名）捏出創意共學玩黏土／呂靜玉老師4/12 (六)10:00-12:00萬興分館 5樓多功能活動室2234-5501限額15組親子(每位家長至多攜帶1名子女，兒童需滿6歲，每組限領1份材料)須事先以電話報名、臨櫃報名（3/14開放報名）我的情緒房間－拼貼創意親子手作／黃兆逸老師（報名請點此）4/12 (六)10:00-12:00稻香分館 9樓多功能活動室2894-0662限額15組親子（國小1-4年級） 須事先以網路報名（3/25 09:00開放報