INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d09d7c8f15adefa04e0c73', '2025金鷹閣電視木偶劇團《叱吒風雲－新哪吒》', '2025金鷹閣電視木偶劇團\r\n顛覆經典神魔小說《叱吒風雲－新哪吒》\r\n\r\n4／26（六）、4／27（日）、14：30\r\n大稻埕戲苑－9樓劇場\r\n售票網址 https://reurl.cc/74ZRll\r\n\r\n【演出特色】\r\n● 國家扶植【Taiwan Top演藝團隊】。\r\n● 蟬聯十三屆【高雄市傑出演藝團隊】。\r\n● 一場，由布袋戲劇場售票先鋒，帶來精采好戲。\r\n● 一本，以全新角度，詮釋經典封神榜－哪吒文本。\r\n● 一齣，結合3D科技動畫投影的新挑戰，宛如電影般震撼場景。\r\n● 集結所有戲曲、劇場、文學及設計人才。\r\n● 大型擬真電視木偶，傳統戲曲文武場、現場演奏。\r\n● 顛覆經典神魔小說，北部劇場巡迴，僅此兩場！\r\n▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂\r\n\r\n【演出日期】2025年\r\n　4／26（週六）14：30\r\n　4／27（週日）14：30\r\n\r\n【演出地址】\r\n　大稻埕戲苑－9樓劇場\r\n　（臺北市大同區迪化街一段21號9樓）\r\n\r\n【購瞟資訊】\r\n　OPENTIX 兩廳院售票系統\r\n　售票網址 https://reurl.cc/74ZRll\r\n　全臺售票據點、7-11、全家、萊爾富皆可購票\r\n▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂\r\n\r\n【演出介紹】\r\n哪吒靈珠轉世，身負使命至凡間，對陳塘關是吉還是兇？\r\n學藝下山後的哪吒，秉持著斬妖除魔的正義，一心協助父親李靖收服妖魔，殊不知不懂得區分善惡，造成陳塘大亂。\r\n哪吒無意間到了東海遇見虛弱且被欺侮的龍三太子敖丙，哪吒相救並且同情敖丙的處境，展開人與妖怪的友誼，本以為這段友情會為陳塘關帶來祥瑞，誰知道竟然是一場人、妖、魔三界惡戰的開始……', '金鷹閣電視木偶劇團', '臺北市大同區迪化街一段21號9樓', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '大稻埕戲苑－9樓劇場', 25.06342433, 121.5130417, '500元、300元。', 'https://www.opentix.life/event/1897908563536801793', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025金鷹閣電視木偶劇團《叱吒風雲－新哪吒》', `description`='2025金鷹閣電視木偶劇團\r\n顛覆經典神魔小說《叱吒風雲－新哪吒》\r\n\r\n4／26（六）、4／27（日）、14：30\r\n大稻埕戲苑－9樓劇場\r\n售票網址 https://reurl.cc/74ZRll\r\n\r\n【演出特色】\r\n● 國家扶植【Taiwan Top演藝團隊】。\r\n● 蟬聯十三屆【高雄市傑出演藝團隊】。\r\n● 一場，由布袋戲劇場售票先鋒，帶來精采好戲。\r\n● 一本，以全新角度，詮釋經典封神榜－哪吒文本。\r\n● 一齣，結合3D科技動畫投影的新挑戰，宛如電影般震撼場景。\r\n● 集結所有戲曲、劇場、文學及設計人才。\r\n● 大型擬真電視木偶，傳統戲曲文武場、現場演奏。\r\n● 顛覆經典神魔小說，北部劇場巡迴，僅此兩場！\r\n▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂\r\n\r\n【演出日期】2025年\r\n　4／26（週六）14：30\r\n　4／27（週日）14：30\r\n\r\n【演出地址】\r\n　大稻埕戲苑－9樓劇場\r\n　（臺北市大同區迪化街一段21號9樓）\r\n\r\n【購瞟資訊】\r\n　OPENTIX 兩廳院售票系統\r\n　售票網址 https://reurl.cc/74ZRll\r\n　全臺售票據點、7-11、全家、萊爾富皆可購票\r\n▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂▂\r\n\r\n【演出介紹】\r\n哪吒靈珠轉世，身負使命至凡間，對陳塘關是吉還是兇？\r\n學藝下山後的哪吒，秉持著斬妖除魔的正義，一心協助父親李靖收服妖魔，殊不知不懂得區分善惡，造成陳塘大亂。\r\n哪吒無意間到了東海遇見虛弱且被欺侮的龍三太子敖丙，哪吒相救並且同情敖丙的處境，展開人與妖怪的友誼，本以為這段友情會為陳塘關帶來祥瑞，誰知道竟然是一場人、妖、魔三界惡戰的開始……', `organizer`='金鷹閣電視木偶劇團', `address`='臺北市大同區迪化街一段21號9樓', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='大稻埕戲苑－9樓劇場', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='500元、300元。', `source_url`='https://www.opentix.life/event/1897908563536801793', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1404b8f15adefa04e0c74', '【無齡世代】教案及文宣徵選比賽', '一、目的：\r\n50歲後，食力、肌力、腦力開始流失，需透過良好飲食與運動習慣來培養這三個健康力，為推動健康老化與預防老年疾病，提升銀髮族晚年生活品質，透過蒐集各式優良作品，以增加銀髮族健康衛教資源，未來可做為實體教具或課程素材，供第一線人員及相關推廣活動所運用。\r\n\r\n二、 主辦單位：\r\n財團法人董氏基金會\r\n\r\n三、 參加對象：\r\n凡具有中華民國國民身分或居留證，均可以「個人」、「團體組隊」方式參加。\r\n\r\n四、 比賽主題說明：\r\n(一) 以五十歲以上長者為目標對象，設計實用且具吸引力的教案或文宣品，旨在激發其建立良好生活習慣的動機、提升健康相關知能。作品內容應以飲食為主，從預防疾病與促進健康的角度出發，避免涉及特定疾病的處置或醫療行為。\r\n(二) 比賽組別分「教案企劃組」及「文宣設計組」。單一件作品僅限報名一項類組，不可跨組。組別說明如下：\r\n(1) 教案企劃組：發想一套衛教宣導活動或相關課程之可行性企劃案，須包含一項文宣(文宣形式不限)。\r\n內容要求：須至少涵蓋標題、目的、目標對象、執行規劃、活動/課程內容、文宣(設計內容及使用說明)、成本評估、預期效益。\r\n格式：A4版面且不超過15頁之PDF檔。\r\n(2) 文宣設計組：發想一套可實際使用之文宣教材，例如手冊、生活用品、宣導簡報、影片、程式軟體、懶人包圖文等，類型不限。\r\n內容要求：作品名稱、學習目標、適用對象、製作過程、使用說明(教學指導）、作品規格(物品類須含設計圖)。\r\n格式：作品本身格式不限，文字說明部分請彙整為一份PDF檔。\r\n(三) 設計方向可參考附件三，亦可引用 董氏食品營養中心官網→主題倡議→無齡世代銀髮專區之內容。\r\n\r\n五、 參賽方法：\r\n詳細資訊請至官網查詢\r\nhttps://www.nutri.jtf.org.tw//News/Info/3598', '財團法人董氏基金會', '臺北市松山區復興北路57號12樓之3', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '財團法人董氏基金會', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【無齡世代】教案及文宣徵選比賽', `description`='一、目的：\r\n50歲後，食力、肌力、腦力開始流失，需透過良好飲食與運動習慣來培養這三個健康力，為推動健康老化與預防老年疾病，提升銀髮族晚年生活品質，透過蒐集各式優良作品，以增加銀髮族健康衛教資源，未來可做為實體教具或課程素材，供第一線人員及相關推廣活動所運用。\r\n\r\n二、 主辦單位：\r\n財團法人董氏基金會\r\n\r\n三、 參加對象：\r\n凡具有中華民國國民身分或居留證，均可以「個人」、「團體組隊」方式參加。\r\n\r\n四、 比賽主題說明：\r\n(一) 以五十歲以上長者為目標對象，設計實用且具吸引力的教案或文宣品，旨在激發其建立良好生活習慣的動機、提升健康相關知能。作品內容應以飲食為主，從預防疾病與促進健康的角度出發，避免涉及特定疾病的處置或醫療行為。\r\n(二) 比賽組別分「教案企劃組」及「文宣設計組」。單一件作品僅限報名一項類組，不可跨組。組別說明如下：\r\n(1) 教案企劃組：發想一套衛教宣導活動或相關課程之可行性企劃案，須包含一項文宣(文宣形式不限)。\r\n內容要求：須至少涵蓋標題、目的、目標對象、執行規劃、活動/課程內容、文宣(設計內容及使用說明)、成本評估、預期效益。\r\n格式：A4版面且不超過15頁之PDF檔。\r\n(2) 文宣設計組：發想一套可實際使用之文宣教材，例如手冊、生活用品、宣導簡報、影片、程式軟體、懶人包圖文等，類型不限。\r\n內容要求：作品名稱、學習目標、適用對象、製作過程、使用說明(教學指導）、作品規格(物品類須含設計圖)。\r\n格式：作品本身格式不限，文字說明部分請彙整為一份PDF檔。\r\n(三) 設計方向可參考附件三，亦可引用 董氏食品營養中心官網→主題倡議→無齡世代銀髮專區之內容。\r\n\r\n五、 參賽方法：\r\n詳細資訊請至官網查詢\r\nhttps://www.nutri.jtf.org.tw//News/Info/3598', `organizer`='財團法人董氏基金會', `address`='臺北市松山區復興北路57號12樓之3', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='財團法人董氏基金會', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d142548f15adefa04e0c75', '【民間史料講座】 戰爭與戰爭中的平民： 從「長春圍城」談歷史為什麼被消失', '那幾個月當中究竟發生了什麼事情，讓長春圍城在中國大陸成為禁忌，以至於 「好像根本就未曾發生過」？這段被噤聲的歷史，給我們留下了什麼啟示？\r\n\r\n•時間：2025年4月12日 週六 下午2:00-4:30 \r\n•地點：華山文創園區 中4B館區2F (台北市中正區八德路一段1號)\r\n•主辦單位：社團法人臺北市民間史料協會 | 國立政治大學人文中心\r\n\r\n主持人:\r\n孫曼蘋—民間史料數位平台1937-1949執行長\r\n主講人:\r\n楊維真—國立中正大學歷史學系教授\r\n\r\n遠藤 譽（Homare ENDO）—筑波大學名譽教授 理學博士/中國問題全球研究所所長/《卡子：沒有出口的大地》作者\r\n\r\n江紀良—民間史料數位平台1937-1949編撰\r\n\r\n活動報名https://www.beclass.com/rid=294fec767cfbbb8014f7', '社團法人臺北市民間史料協會', '臺北市中正區八德路一段1號', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '華山文創園區 中4B館區2F', 25.03240487, 121.5198839, '無資料', 'https://www.beclass.com/rid=294fec767cfbbb8014f7', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【民間史料講座】 戰爭與戰爭中的平民： 從「長春圍城」談歷史為什麼被消失', `description`='那幾個月當中究竟發生了什麼事情，讓長春圍城在中國大陸成為禁忌，以至於 「好像根本就未曾發生過」？這段被噤聲的歷史，給我們留下了什麼啟示？\r\n\r\n•時間：2025年4月12日 週六 下午2:00-4:30 \r\n•地點：華山文創園區 中4B館區2F (台北市中正區八德路一段1號)\r\n•主辦單位：社團法人臺北市民間史料協會 | 國立政治大學人文中心\r\n\r\n主持人:\r\n孫曼蘋—民間史料數位平台1937-1949執行長\r\n主講人:\r\n楊維真—國立中正大學歷史學系教授\r\n\r\n遠藤 譽（Homare ENDO）—筑波大學名譽教授 理學博士/中國問題全球研究所所長/《卡子：沒有出口的大地》作者\r\n\r\n江紀良—民間史料數位平台1937-1949編撰\r\n\r\n活動報名https://www.beclass.com/rid=294fec767cfbbb8014f7', `organizer`='社團法人臺北市民間史料協會', `address`='臺北市中正區八德路一段1號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='華山文創園區 中4B館區2F', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://www.beclass.com/rid=294fec767cfbbb8014f7', `image_url`='[]';
