INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1ee3826b32408680bebcf', '【講座】畫女話她─她的身體不是她的身體', '📜講座介紹: 隨著時代變遷以及教育界的倡導，臺灣於性別議題的落實上已有相當成效。然而，性別是社會文化的長期建構，諸多隱而不現的性別偏見及刻板印象仍常匿跡於表面的平權機制之下，本講座將探查藝術世界中對性別議題「看不到的排斥力量」，檢視當性別差異被位階化後，外顯於藝術界中的權力結構。\n\n🙋講師:趙惠玲/國立臺灣師範大學美術學系教授\n\n-----------------------------------------------\n\n📆時間:114年4月20日（日）14:00~16:00\n\n📍地點:中正紀念堂3樓W318教室\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁現場填答問卷憑完成畫面可獲得紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍教室地點指引:教室位於藍色屋頂主堂體內，學員請直接由銅門(玻璃門)進入1樓大廳，利用樓梯或電梯前往3樓W318教室，教室位置詳參下方圖示：\n\n\n\n\n\n \n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', 'W318教室', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50741', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【講座】畫女話她─她的身體不是她的身體', `description`='📜講座介紹: 隨著時代變遷以及教育界的倡導，臺灣於性別議題的落實上已有相當成效。然而，性別是社會文化的長期建構，諸多隱而不現的性別偏見及刻板印象仍常匿跡於表面的平權機制之下，本講座將探查藝術世界中對性別議題「看不到的排斥力量」，檢視當性別差異被位階化後，外顯於藝術界中的權力結構。\n\n🙋講師:趙惠玲/國立臺灣師範大學美術學系教授\n\n-----------------------------------------------\n\n📆時間:114年4月20日（日）14:00~16:00\n\n📍地點:中正紀念堂3樓W318教室\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁現場填答問卷憑完成畫面可獲得紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍教室地點指引:教室位於藍色屋頂主堂體內，學員請直接由銅門(玻璃門)進入1樓大廳，利用樓梯或電梯前往3樓W318教室，教室位置詳參下方圖示：\n\n\n\n\n\n \n\n \n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='W318教室', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50741', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1ee3826b32408680bebd0', '【講座】她的旋律，音妳而生─音樂與女性', '📜講座介紹: 隨著臺灣流行音樂的發展，音樂不僅是旋律的流轉，更是時代故事的記錄。本講座將以臺灣流行音樂發展半個世紀為主軸，依時間脈絡展開音樂導聆，從不同時代的音樂作品中，讀出女性的處境、樣貌與心聲。\n\n🙋講師:洪芳怡/歷史錄音與流行音樂文化研究者\n\n-----------------------------------------------\n\n📆時間:114年5月18日（日）14:00~16:00\n\n📍地點:中正紀念堂3樓W318教室\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁現場填答問卷憑完成畫面可獲得紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍教室地點指引:教室位於藍色屋頂主堂體內，學員請直接由銅門(玻璃門)進入1樓大廳，利用樓梯或電梯前往3樓W318教室，教室位置詳參下方圖示：\n\n\n\n\n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-18 00:00:00', '2025-05-18 00:00:00', 'W318教室', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50742', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【講座】她的旋律，音妳而生─音樂與女性', `description`='📜講座介紹: 隨著臺灣流行音樂的發展，音樂不僅是旋律的流轉，更是時代故事的記錄。本講座將以臺灣流行音樂發展半個世紀為主軸，依時間脈絡展開音樂導聆，從不同時代的音樂作品中，讀出女性的處境、樣貌與心聲。\n\n🙋講師:洪芳怡/歷史錄音與流行音樂文化研究者\n\n-----------------------------------------------\n\n📆時間:114年5月18日（日）14:00~16:00\n\n📍地點:中正紀念堂3樓W318教室\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁現場填答問卷憑完成畫面可獲得紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍教室地點指引:教室位於藍色屋頂主堂體內，學員請直接由銅門(玻璃門)進入1樓大廳，利用樓梯或電梯前往3樓W318教室，教室位置詳參下方圖示：\n\n\n\n\n\n \n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-05-18 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='W318教室', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50742', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eeb626b32408680bebd7', '【日午音樂會173】竹樂世界', '台灣竹樂團為國內第一支由純竹樂器組成的樂團，樂團演奏曲目豐富多元且生動富創意。本次帶來許多膾炙人口的經典曲目，除了台灣民謠之外，還有美國、印尼、馬來西亞民歌，以及榮獲2020年傳統藝術金曲獎羅正楎團長的多首精彩創作。節目並搭配各種竹樂器的介紹，邀您一起進入豐富多彩的竹樂世界。\r\n\r\n■演出：台灣竹樂團\r\n（竹琴、搖竹｜羅正楎； 叮咚琴｜陳思如；拍筒琴｜劉育伶；竹笛｜劉宗岳；高笙｜李家駿；擊樂｜林桀名）\r\n\r\n■時間：2025年4月20日（日）14:30（遲到或中途離場的聽眾至中場休息方可入場，建議提早抵達）\r\n\r\n■地點：林建生紀念圖書館演奏廳（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額200位，七歲以上，免費報名入場。\r\n#恕無現場後補\r\n\r\n■報名方式：4月10日（四）10:00 起，網路報名：  https://www.accupass.com/go/1140420\r\n\r\n■演出曲目：\r\n1.《台灣風情》台灣民謠，羅正楎配器\r\n2.《綠動》羅正楎作曲\r\n3.《望春風》鄧雨賢作曲，羅正楎編配\r\n4.《黑色武士》羅正楎作曲\r\n5.《竹雨蛙》羅正楎作曲\r\n6.《千島風情》印尼民歌，羅正楎編配\r\n7.《城市光蹤》羅正楎作曲\r\n8.《美國民歌》美國民謠，羅正楎編配\r\n9.竹鑼互動\r\n10.《沙巴之歌聯奏》馬來西亞民歌，羅正楎編配\r\n11.《鼓動》羅正楎、王姮云作曲\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★歡迎加入Line 好友： https://bit.ly/2KFVgg2\r\n★網址： https://www.ljsedu.org.tw\r\n★粉絲專頁：https://www.facebook.com/linjiansheng\r\n', '財團法人紀念林建生文教基金會', '新北市蘆洲區三民路178號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '林建生紀念圖書館', 25.08927173, 121.4712461, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【日午音樂會173】竹樂世界', `description`='台灣竹樂團為國內第一支由純竹樂器組成的樂團，樂團演奏曲目豐富多元且生動富創意。本次帶來許多膾炙人口的經典曲目，除了台灣民謠之外，還有美國、印尼、馬來西亞民歌，以及榮獲2020年傳統藝術金曲獎羅正楎團長的多首精彩創作。節目並搭配各種竹樂器的介紹，邀您一起進入豐富多彩的竹樂世界。\r\n\r\n■演出：台灣竹樂團\r\n（竹琴、搖竹｜羅正楎； 叮咚琴｜陳思如；拍筒琴｜劉育伶；竹笛｜劉宗岳；高笙｜李家駿；擊樂｜林桀名）\r\n\r\n■時間：2025年4月20日（日）14:30（遲到或中途離場的聽眾至中場休息方可入場，建議提早抵達）\r\n\r\n■地點：林建生紀念圖書館演奏廳（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額200位，七歲以上，免費報名入場。\r\n#恕無現場後補\r\n\r\n■報名方式：4月10日（四）10:00 起，網路報名：  https://www.accupass.com/go/1140420\r\n\r\n■演出曲目：\r\n1.《台灣風情》台灣民謠，羅正楎配器\r\n2.《綠動》羅正楎作曲\r\n3.《望春風》鄧雨賢作曲，羅正楎編配\r\n4.《黑色武士》羅正楎作曲\r\n5.《竹雨蛙》羅正楎作曲\r\n6.《千島風情》印尼民歌，羅正楎編配\r\n7.《城市光蹤》羅正楎作曲\r\n8.《美國民歌》美國民謠，羅正楎編配\r\n9.竹鑼互動\r\n10.《沙巴之歌聯奏》馬來西亞民歌，羅正楎編配\r\n11.《鼓動》羅正楎、王姮云作曲\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★歡迎加入Line 好友： https://bit.ly/2KFVgg2\r\n★網址： https://www.ljsedu.org.tw\r\n★粉絲專頁：https://www.facebook.com/linjiansheng\r\n', `organizer`='財團法人紀念林建生文教基金會', `address`='新北市蘆洲區三民路178號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='林建生紀念圖書館', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
