INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eee426b32408680bebd9', '【新北市立圖書館永和親子圖書閱覽室】114年3月主題書展', '【主題書展】\r\n主題：「恐龍的故事」\r\n對孩子來說，恐龍充滿了神奇的魅力，其巨大的外表、豐富的種類、多彩神祕的生活型態，都深深吸引著孩子目光，圖書館展示恐龍的故事，歡迎一起來解恐龍。\r\n時間：114年3月1日至3月31日 開館時間\r\n地點：新北市立圖書館永和親子圖書閱覽室\r\n地址：新北市永和區保安路132號2樓 書展區\r\n電話：02-29290464\r\n\r\n\r\n\r\n', '新北市立圖書館總館', '新北市永和區保安路132號2樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館永和親子圖書閱覽室', 25.00810199, 121.516745, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館永和親子圖書閱覽室】114年3月主題書展', `description`='【主題書展】\r\n主題：「恐龍的故事」\r\n對孩子來說，恐龍充滿了神奇的魅力，其巨大的外表、豐富的種類、多彩神祕的生活型態，都深深吸引著孩子目光，圖書館展示恐龍的故事，歡迎一起來解恐龍。\r\n時間：114年3月1日至3月31日 開館時間\r\n地點：新北市立圖書館永和親子圖書閱覽室\r\n地址：新北市永和區保安路132號2樓 書展區\r\n電話：02-29290464\r\n\r\n\r\n\r\n', `organizer`='新北市立圖書館總館', `address`='新北市永和區保安路132號2樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館永和親子圖書閱覽室', `latitude`=25.00810199, `longitude`=121.516745, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
