INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eef526b32408680bebe1', 'ART TAINAN 2025 台南藝術博覽會 ｜展間625｜暮拉多元藝術空間', 'ART TAINAN 2025 台南藝術博覽會 ｜展間625｜暮拉多元藝術空間\r\n\r\n迴聲之形 Retentir\r\n2025年，暮拉多元藝術空間以「迴聲之形」作為於 2025 台南藝術博覽會 的策展主題，其構想概念源自於哲學家尤金．閔可夫斯基 (Eugene Minkowski) 的「迴盪 (retentir)」一詞，用來描述一種以身體與自然作為介質，如同知覺意念的波長之延伸，如同聲響般的擴張所體現出的共鳴。\r\n\r\n細膩地感受音韻所產生的力道與塑形，期待透過六位涵括繪畫、水墨、版畫、陶瓷、活脫乾漆，於不同材質創作表現的藝術家們，以文化思考、角色隱喻、社群景觀，引領觀眾感受對世界探尋的自由精神與未知想像', '暮拉多元藝術空間', '臺南市中西區', '2025-03-13 00:00:00', '2025-03-16 00:00:00', '中西區（臺南市）=', 22.99594458, 120.192874, '無資料', 'https://themoolahart.com/art-tainan-2025/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='ART TAINAN 2025 台南藝術博覽會 ｜展間625｜暮拉多元藝術空間', `description`='ART TAINAN 2025 台南藝術博覽會 ｜展間625｜暮拉多元藝術空間\r\n\r\n迴聲之形 Retentir\r\n2025年，暮拉多元藝術空間以「迴聲之形」作為於 2025 台南藝術博覽會 的策展主題，其構想概念源自於哲學家尤金．閔可夫斯基 (Eugene Minkowski) 的「迴盪 (retentir)」一詞，用來描述一種以身體與自然作為介質，如同知覺意念的波長之延伸，如同聲響般的擴張所體現出的共鳴。\r\n\r\n細膩地感受音韻所產生的力道與塑形，期待透過六位涵括繪畫、水墨、版畫、陶瓷、活脫乾漆，於不同材質創作表現的藝術家們，以文化思考、角色隱喻、社群景觀，引領觀眾感受對世界探尋的自由精神與未知想像', `organizer`='暮拉多元藝術空間', `address`='臺南市中西區', `start_date`='2025-03-13 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='中西區（臺南市）=', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='https://themoolahart.com/art-tainan-2025/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eef526b32408680bebe2', '編織玩藝趣-毛線編織技法', '邀請吳秀月老師為學員介紹毛線材料特性，並教導學員運用勾針技巧將毛線編織出喜歡的物品，運用於日常生活中。', '臺南市南關社區大學', '臺南市歸仁區', '2025-03-14 00:00:00', '2025-05-23 00:00:00', '歸仁區（臺南市）=', 22.94679469, 120.2930627, '1300元/人+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='編織玩藝趣-毛線編織技法', `description`='邀請吳秀月老師為學員介紹毛線材料特性，並教導學員運用勾針技巧將毛線編織出喜歡的物品，運用於日常生活中。', `organizer`='臺南市南關社區大學', `address`='臺南市歸仁區', `start_date`='2025-03-14 00:00:00', `end_date`='2025-05-23 00:00:00', `location`='歸仁區（臺南市）=', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='1300元/人+--', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eef626b32408680bebe3', '金車文藝講堂：李惠貞【閱讀，是為了更自由】', '我們每天被無數的標題、推播與短影音包圍。\r\n新聞快訊、社群貼文、AI 摘要工具幾乎無時無刻不在簡化我們接收資訊的方式。於是，我們讀得更快了，卻未必理解得更深；我們接收的資訊更多了，卻未必內化成真正的知識。\r\n在這樣的時代，我們為何仍需要閱讀？閱讀還能為我們帶來什麼樣的改變？本次金車文藝講堂我們邀請到「獨角獸計劃」的創辦人李惠貞老師，引領我們在新的一年重新思考閱讀的意義與價值。', '金車文藝中心', '臺北市中山區', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '中山區（臺北市）=', 25.06969917, 121.5381597, '無資料', 'https://www.kingcarart.org.tw/projects-detail/174', '[]') ON DUPLICATE KEY UPDATE `activity_name`='金車文藝講堂：李惠貞【閱讀，是為了更自由】', `description`='我們每天被無數的標題、推播與短影音包圍。\r\n新聞快訊、社群貼文、AI 摘要工具幾乎無時無刻不在簡化我們接收資訊的方式。於是，我們讀得更快了，卻未必理解得更深；我們接收的資訊更多了，卻未必內化成真正的知識。\r\n在這樣的時代，我們為何仍需要閱讀？閱讀還能為我們帶來什麼樣的改變？本次金車文藝講堂我們邀請到「獨角獸計劃」的創辦人李惠貞老師，引領我們在新的一年重新思考閱讀的意義與價值。', `organizer`='金車文藝中心', `address`='臺北市中山區', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='中山區（臺北市）=', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='https://www.kingcarart.org.tw/projects-detail/174', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eef826b32408680bebe5', '2025年神韻臺灣巡迴演出(臺北)', '神韻以藝術的形式復興華夏五千年的正統文化。\r\n神韻演出包括約20個節目，從漢唐盛世到明清宮廷，從江南美景到西北高原，舞蹈和舞劇節目的場景設置涵蓋神州每一處土地、每一段時光。節目中也展現了各式各樣的人物，從端莊秀美的仕女到馳騁沙場的大將，從仙風道骨的道教祖師到嬉笑怒罵的市井小民，個個都栩栩如生。節目中更描繪了現代中國社會堅持信仰的一群人，他們雖然遭受迫害，卻依然堅貞不屈，他們的故事催人淚下、感人至深。', '社團法人臺灣法輪大法學會', '臺北市士林區劍潭路1號', '2025-03-26 00:00:00', '2025-03-30 00:00:00', '臺北表演藝術中心', 25.12546704, 121.5508473, '/+2600;/+3000;/+3500;/+4000;/+5000', 'ShenYun.com', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年神韻臺灣巡迴演出(臺北)', `description`='神韻以藝術的形式復興華夏五千年的正統文化。\r\n神韻演出包括約20個節目，從漢唐盛世到明清宮廷，從江南美景到西北高原，舞蹈和舞劇節目的場景設置涵蓋神州每一處土地、每一段時光。節目中也展現了各式各樣的人物，從端莊秀美的仕女到馳騁沙場的大將，從仙風道骨的道教祖師到嬉笑怒罵的市井小民，個個都栩栩如生。節目中更描繪了現代中國社會堅持信仰的一群人，他們雖然遭受迫害，卻依然堅貞不屈，他們的故事催人淚下、感人至深。', `organizer`='社團法人臺灣法輪大法學會', `address`='臺北市士林區劍潭路1號', `start_date`='2025-03-26 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺北表演藝術中心', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='/+2600;/+3000;/+3500;/+4000;/+5000', `source_url`='ShenYun.com', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eef926b32408680bebe7', '安定區圖書館:3月小葫蘆故事團', '3/9誰是我的好朋友-榛果媽媽\r\n3/23你的身體是你的-冰淇淋阿姨', '臺南市安定區公所', '臺南市安定區262之8號', '2025-03-09 00:00:00', '2025-03-23 00:00:00', '臺南市安定區圖書館', 23.09974927, 120.2296235, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='安定區圖書館:3月小葫蘆故事團', `description`='3/9誰是我的好朋友-榛果媽媽\r\n3/23你的身體是你的-冰淇淋阿姨', `organizer`='臺南市安定區公所', `address`='臺南市安定區262之8號', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='臺南市安定區圖書館', `latitude`=23.09974927, `longitude`=120.2296235, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eef926b32408680bebe8', '安定區圖書館:3月影片欣賞', '3/5星星知我心\r\n3/12我的失憶阿公\r\n3/19極限長征\r\n3/26名偵探柯南:往天國的倒數計時', '臺南市安定區公所', '臺南市安定區262之8號', '2025-03-05 00:00:00', '2025-03-26 00:00:00', '臺南市安定區圖書館', 23.09974927, 120.2296235, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='安定區圖書館:3月影片欣賞', `description`='3/5星星知我心\r\n3/12我的失憶阿公\r\n3/19極限長征\r\n3/26名偵探柯南:往天國的倒數計時', `organizer`='臺南市安定區公所', `address`='臺南市安定區262之8號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺南市安定區圖書館', `latitude`=23.09974927, `longitude`=120.2296235, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eef926b32408680bebe9', '歲月．痕跡 - 四聯展', '此次聯展以「歲月·痕跡」為名，四位藝術家，透過他們的畫筆，進行表演生命歷程中與自然、內心、以及現實的靈光結合，每幅作品，無論是古典的風景畫、細膩的工筆花鳥，或是充滿想像的超現實題材，皆蘊含著藝術家對歲月的沉澱與感悟。', '臺南市麻豆區公所', '臺南市麻豆區興國路11號', '2025-03-08 00:00:00', '2025-04-09 00:00:00', '臺南市麻豆區文化館', 23.18248033, 120.241308, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歲月．痕跡 - 四聯展', `description`='此次聯展以「歲月·痕跡」為名，四位藝術家，透過他們的畫筆，進行表演生命歷程中與自然、內心、以及現實的靈光結合，每幅作品，無論是古典的風景畫、細膩的工筆花鳥，或是充滿想像的超現實題材，皆蘊含著藝術家對歲月的沉澱與感悟。', `organizer`='臺南市麻豆區公所', `address`='臺南市麻豆區興國路11號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-04-09 00:00:00', `location`='臺南市麻豆區文化館', `latitude`=23.18248033, `longitude`=120.241308, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefa26b32408680bebea', '奧利・艾普的小鹹點', '師大美術館推出「奧利・艾普的小鹹點」（Hors d’œuvres）展覽，呈現英國藝術家奧利・艾普（Oli Epp）擬仿螢幕表面質感的繪畫。本次展覽以統一畫布尺寸的一系列混種肖像為特色，精心塑造的角色位於構圖中心，以超乎常理的方式將各種元素融合。透過這些作品，展覽試圖映射當代社交媒體對形象迷戀與刻意表演的現象。', '師大美術館', '臺北市大安區和平東路一段162號', '2025-03-16 00:00:00', '2025-05-15 00:00:00', '國立臺灣師範大學', 25.02677012, 121.5434446, '無資料', 'https://www.artmuse.ntnu.edu.tw/index.php/oli-epp-hors-doeuvres/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='奧利・艾普的小鹹點', `description`='師大美術館推出「奧利・艾普的小鹹點」（Hors d’œuvres）展覽，呈現英國藝術家奧利・艾普（Oli Epp）擬仿螢幕表面質感的繪畫。本次展覽以統一畫布尺寸的一系列混種肖像為特色，精心塑造的角色位於構圖中心，以超乎常理的方式將各種元素融合。透過這些作品，展覽試圖映射當代社交媒體對形象迷戀與刻意表演的現象。', `organizer`='師大美術館', `address`='臺北市大安區和平東路一段162號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-05-15 00:00:00', `location`='國立臺灣師範大學', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='無資料', `source_url`='https://www.artmuse.ntnu.edu.tw/index.php/oli-epp-hors-doeuvres/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefa26b32408680bebeb', '「究・南物」歷史文物小展覽（南區場）', '今年由臺南市政府文化局臺南市文化資產管處出版的《南都物語：物件裡的臺南史》，推出歷史文物小展覽。\r\n\r\n《南都物語：物件裡的臺南史》書本中的不同時間軸介紹不同時代的文物，每件文物上都記錄著臺南甚至臺灣曾經發生過的事件，以及在此生活的人們所留下的痕跡。\r\n\r\n「究・南物」則在這些既熟悉又陌生的歷史紀錄當中，為大家整理了重點年代並介紹該時代的特殊文物，同時整理出分別被典藏在什麼地方，設計了一些有趣的體驗，從3/7~5/11，分別在白雪珈琲店及臺南市立博物館開展。\r\n除了看展覽認識文物與歷史，也希望能透過這個機會認識展覽地區周邊特色景點或者書上文物的本尊。', '臺南市文化資產管理處', '臺南市南區', '2025-03-07 00:00:00', '2025-04-06 00:00:00', '南區（臺南市）=', 22.95561863, 120.1903743, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「究・南物」歷史文物小展覽（南區場）', `description`='今年由臺南市政府文化局臺南市文化資產管處出版的《南都物語：物件裡的臺南史》，推出歷史文物小展覽。\r\n\r\n《南都物語：物件裡的臺南史》書本中的不同時間軸介紹不同時代的文物，每件文物上都記錄著臺南甚至臺灣曾經發生過的事件，以及在此生活的人們所留下的痕跡。\r\n\r\n「究・南物」則在這些既熟悉又陌生的歷史紀錄當中，為大家整理了重點年代並介紹該時代的特殊文物，同時整理出分別被典藏在什麼地方，設計了一些有趣的體驗，從3/7~5/11，分別在白雪珈琲店及臺南市立博物館開展。\r\n除了看展覽認識文物與歷史，也希望能透過這個機會認識展覽地區周邊特色景點或者書上文物的本尊。', `organizer`='臺南市文化資產管理處', `address`='臺南市南區', `start_date`='2025-03-07 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='南區（臺南市）=', `latitude`=22.95561863, `longitude`=120.1903743, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefa26b32408680bebec', '身聲劇場2025第一號全新製作《落頭氏》', '2025身聲劇場全新製作《落頭氏》\r\n\r\n流離與游離、馬來西亞華人、女性、傳說\r\n\r\n現場音樂x肢體x吟唱x戲劇\r\n\r\n展演者︰【製作團隊】 創辦人：吳忠良(1973-2021) 戲劇顧問：高俊耀 創作發想 ：莊惠勻 共同導演：張偉來、 莊惠勻 劇本創作： 莊惠勻 音樂設計：陳姿吟 吟唱設計：劉佩芬 表演者：莊惠勻、劉佩芬、陳姿吟 服裝設計、舞台裝置：陳明澤 燈光設計：彭久芳 劇名題字：陳明澤 文宣製作：莊惠勻 行政執行、行銷宣傳：蕭文怡 特別感謝、臺語唱詞改寫：劉秀庭老師 主辦單位：身聲劇場 贊助單位：財團法人國家文化藝術基金會、台北市文化局 長期贊助單位：文來金屬工業股份有限公司、身聲柱腳會\r\n\r\n\r\n \r\n\r\n阮的身驅是一列無頭的火車\r\n\r\n阮的身驅是一支無腳的船仔\r\n\r\n \r\n\r\n我的身體在陽光下頭塞在陰影裡。我的頭在海上身體在叢林。哪個國家愛我的頭哪個國家需要我的身體。我連「這裡、那裡」都沒有。這並不是一個鬼故事，而是一段思念之歌、記憶之詩。\r\n\r\n會飛的人頭傳說，從中國到印尼、越南、寮國、馬來西亞等地盛傳，身聲劇場此次幽幽召喚出的既非身世之謎、亦非遠古傳說，竟是斷代女性異人錄。由資深創作者暨表演者莊惠勻、劉佩芬與陳姿吟共同演出，《落頭氏》除了再次發揮演樂舞合一的核心特色，融入意象的視覺、戲劇與吟唱，更以肢體與現場音樂娓娓道來逆著時間而行的南洋遺民或疑民，在中心與邊緣、真實與想像繼續穿梭、挪移、雜揉交錯。\r\n\r\n【團隊介紹】\r\n\r\n身聲是一個透過整合音樂、肢體戲劇、美術等不同領域專長夥伴，發展出表演者「演樂舞合一」劇場特色的團隊。創辦人吳忠良相信每個人都有屬於自己「身體」與「聲音」獨一無二的表達能力，成員長期集體創作，自多元的傳統技藝學習、並透過現代劇場手法轉化。以「身聲劇場」為核心，演出融合世界樂器、肢體戲劇、吟唱、傀儡乃至結合動畫等各種表演形式，演者同時是舞者、也是樂師。發展至今作品風格多元，從室內到戶外；從儀式或實驗性的議題作品、到闔家觀賞的親子戲劇類型，創造出現代劇場藝術的無限可能。除了現代劇場之外，還延伸出「身聲擊樂團」與廣場藝術的「身聲跨劇場」，作品風格多元，並持續探索跨領域表演藝術的無限可能。\r\n\r\n【展演須知】\r\n．入場時間：演前15分鐘開放入場。\r\n\r\n．演出全長：60分鐘，無中場休息。\r\n\r\n．語言：中文、檳城福建話(有中文字幕)。\r\n\r\n．建議10歲以上觀眾欣賞。\r\n\r\n．12歲以下孩童建議由家長或成年親友陪同進場觀賞。\r\n\r\n．遲到觀眾須等候帶位，無法退換票。\r\n\r\n．須持紙本票券入場，無開放電子票。牯嶺街小劇場為售票端點，為避免取票人潮眾多及維護觀賞權益，敬請現場取票觀眾提早到場。\r\n\r\n．小劇場座位較緊密，建議輕裝蒞臨劇場看戲。\r\n\r\n．因場地位置有限，如有輪椅席以及輪椅陪同席之需求，請於購票前聯繫主辦單位協助處理。聯繫電話 (02)2809-5885。\r\n\r\n', '身聲劇場', '臺北市中正區牯嶺街5巷2號', '2025-05-02 00:00:00', '2025-05-04 00:00:00', '牯嶺街小劇場', 25.03240487, 121.5198839, '/+800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='身聲劇場2025第一號全新製作《落頭氏》', `description`='2025身聲劇場全新製作《落頭氏》\r\n\r\n流離與游離、馬來西亞華人、女性、傳說\r\n\r\n現場音樂x肢體x吟唱x戲劇\r\n\r\n展演者︰【製作團隊】 創辦人：吳忠良(1973-2021) 戲劇顧問：高俊耀 創作發想 ：莊惠勻 共同導演：張偉來、 莊惠勻 劇本創作： 莊惠勻 音樂設計：陳姿吟 吟唱設計：劉佩芬 表演者：莊惠勻、劉佩芬、陳姿吟 服裝設計、舞台裝置：陳明澤 燈光設計：彭久