INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefa26b32408680bebee', '仁德區圖書館:3月說故事活動(2場)', '3/15 小蛇散步:　小蛇散步時，遇到了好多想過河的動物，好心的小蛇，把自己的身體變成橋，讓牠們走到對岸。牠幫了小螞蟻、小蝸牛，可是，連獅子、大象都來了！小蛇會怎麼做呢……結束後再利用色紙做一隻小蛇當玩具。\r\n3/29我的媽媽是救火英雄:媽媽為什麼想當救火英雄？\r\n　　當救火英雄需要接受哪些訓練？\r\n　　媽媽當救火英雄需要執行哪些勤務？\r\n    讓這本繪本為我們，\r\n　　打破女生擔任救火英雄的刻板印象。\r\n    活動中讓小朋友體驗噴水的技巧。', '臺南市仁德區圖書館', '臺南市仁德區正義一街39號2樓', '2025-03-15 00:00:00', '2025-03-29 00:00:00', '臺南市仁德區圖書館', 22.94130931, 120.2418788, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='仁德區圖書館:3月說故事活動(2場)', `description`='3/15 小蛇散步:　小蛇散步時，遇到了好多想過河的動物，好心的小蛇，把自己的身體變成橋，讓牠們走到對岸。牠幫了小螞蟻、小蝸牛，可是，連獅子、大象都來了！小蛇會怎麼做呢……結束後再利用色紙做一隻小蛇當玩具。\r\n3/29我的媽媽是救火英雄:媽媽為什麼想當救火英雄？\r\n　　當救火英雄需要接受哪些訓練？\r\n　　媽媽當救火英雄需要執行哪些勤務？\r\n    讓這本繪本為我們，\r\n　　打破女生擔任救火英雄的刻板印象。\r\n    活動中讓小朋友體驗噴水的技巧。', `organizer`='臺南市仁德區圖書館', `address`='臺南市仁德區正義一街39號2樓', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺南市仁德區圖書館', `latitude`=22.94130931, `longitude`=120.2418788, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefa26b32408680bebef', ' 丹麥最高工藝級陶盆．Bergs Potter .漫步哥本哈根祕密花園', '綠意芽萌，森/CASA 帶著「 丹麥最高工藝級陶盆．Bergs Potter 」漫步漁光小島的森初。海風吹拂，優雅綠意的經典陶盆映上微光，一閃一閃綻放最高工藝技術。粗曠細膩的裸陶，映著林谷的大地之色；柔亮高雅的彩釉，繪著北歐自然的四季色彩。古典童話般的森林世界，凝縮在手中的陶盆。坐落哥本哈根街道，自 1942 年開始以傳統工藝帶著愛與永恆設計，將美好傳承世代。\r\n坐落哥本哈根街道，自 1942 年開始以傳統工藝帶著愛與永恆設計，將美好傳承世代。', '森初．moricasa art', '臺南市安平區', '2025-03-08 00:00:00', '2025-04-12 00:00:00', '安平區（臺南市）=', 22.99008437, 120.1649949, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`=' 丹麥最高工藝級陶盆．Bergs Potter .漫步哥本哈根祕密花園', `description`='綠意芽萌，森/CASA 帶著「 丹麥最高工藝級陶盆．Bergs Potter 」漫步漁光小島的森初。海風吹拂，優雅綠意的經典陶盆映上微光，一閃一閃綻放最高工藝技術。粗曠細膩的裸陶，映著林谷的大地之色；柔亮高雅的彩釉，繪著北歐自然的四季色彩。古典童話般的森林世界，凝縮在手中的陶盆。坐落哥本哈根街道，自 1942 年開始以傳統工藝帶著愛與永恆設計，將美好傳承世代。\r\n坐落哥本哈根街道，自 1942 年開始以傳統工藝帶著愛與永恆設計，將美好傳承世代。', `organizer`='森初．moricasa art', `address`='臺南市安平區', `start_date`='2025-03-08 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='安平區（臺南市）=', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefb26b32408680bebf3', '2025竹山迎媽祖祈福文化節：連興宮軟身媽祖回鑾安座晚會', '2025竹山迎媽祖祈福文化節Coming Soon\r\n每年「農曆三月」許多地區都會舉辦媽祖遶境活動，今年竹山鎮公所與竹山連興宮(三級古蹟)、社寮四里社區發展協會共同辦理 2025竹山迎媽祖祈福文化節。\r\n連興宮軟身媽祖將於3月13日上午9點起駕回社寮四里繞境，媽祖於社寮四里駐駕時，分別舉辦4場晚會及平安餐活動(3/13山崇里北天宮、3/15社寮里武德宮、3/16富州里天元宮、3/17中央里靈天宮)。\r\n連興宮是南投縣縣定古蹟。3月18日回鑾安座晚會，當日下午1點30分起有一系列表演活動、安座大典、晚會期間還有歌手林紫君、葡萄姑娘粉絲團、曾瑋中 x Kuljelje將展現天籟歌喉，帶來精彩的演出。\r\n連興宮軟身媽祖回鑾安座晚會\r\n13:30-17:30 暖身表演節目\r\n 13:00 扯鈴特技\r\n 14:30 變臉特技\r\n 15:30 黑人雜耍\r\n 16:30 小丑魔術\r\n 17:30 童話氣球\r\n18:30-18:50 媽祖安座大典\r\n18:50-19:00 國樂表演\r\n19:00-19:20 晚會開場\r\n19:20-19:45 竹山姑娘-林紫君\r\n19:45-19:55 有獎徵答\r\n19:55-20:20 台語人氣歌手-曾瑋中\r\n20:25-20:30 發送媽祖護身帽', '南投縣竹山鎮公所', '南投縣竹山鎮下橫街28號', '2025-03-18 00:00:00', '2025-03-18 00:00:00', '南投縣竹山鎮連興宮', 23.7560755, 120.6848322, '無資料', 'https://www.facebook.com/CHENTUNGMU', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025竹山迎媽祖祈福文化節：連興宮軟身媽祖回鑾安座晚會', `description`='2025竹山迎媽祖祈福文化節Coming Soon\r\n每年「農曆三月」許多地區都會舉辦媽祖遶境活動，今年竹山鎮公所與竹山連興宮(三級古蹟)、社寮四里社區發展協會共同辦理 2025竹山迎媽祖祈福文化節。\r\n連興宮軟身媽祖將於3月13日上午9點起駕回社寮四里繞境，媽祖於社寮四里駐駕時，分別舉辦4場晚會及平安餐活動(3/13山崇里北天宮、3/15社寮里武德宮、3/16富州里天元宮、3/17中央里靈天宮)。\r\n連興宮是南投縣縣定古蹟。3月18日回鑾安座晚會，當日下午1點30分起有一系列表演活動、安座大典、晚會期間還有歌手林紫君、葡萄姑娘粉絲團、曾瑋中 x Kuljelje將展現天籟歌喉，帶來精彩的演出。\r\n連興宮軟身媽祖回鑾安座晚會\r\n13:30-17:30 暖身表演節目\r\n 13:00 扯鈴特技\r\n 14:30 變臉特技\r\n 15:30 黑人雜耍\r\n 16:30 小丑魔術\r\n 17:30 童話氣球\r\n18:30-18:50 媽祖安座大典\r\n18:50-19:00 國樂表演\r\n19:00-19:20 晚會開場\r\n19:20-19:45 竹山姑娘-林紫君\r\n19:45-19:55 有獎徵答\r\n19:55-20:20 台語人氣歌手-曾瑋中\r\n20:25-20:30 發送媽祖護身帽', `organizer`='南投縣竹山鎮公所', `address`='南投縣竹山鎮下橫街28號', `start_date`='2025-03-18 00:00:00', `end_date`='2025-03-18 00:00:00', `location`='南投縣竹山鎮連興宮', `latitude`=23.7560755, `longitude`=120.6848322, `ticket_price`='無資料', `source_url`='https://www.facebook.com/CHENTUNGMU', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefb26b32408680bebf4', '講座:台灣周邊海域的沉船事件-以澎湖為例 ', '講座邀請李其霖老師帶您認識澎湖的海洋歷程及船舶遭難事件。藉由澎湖海洋文化歷史來了解澎湖海域附近的沉船及船隻沉沒原因以及水下文物的相關知識，亦能更認識海洋歷史中的澎湖！', '文化部文化資產局', '澎湖縣馬公市', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '馬公市（澎湖縣）=', 23.55534, 119.59234, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='講座:台灣周邊海域的沉船事件-以澎湖為例 ', `description`='講座邀請李其霖老師帶您認識澎湖的海洋歷程及船舶遭難事件。藉由澎湖海洋文化歷史來了解澎湖海域附近的沉船及船隻沉沒原因以及水下文物的相關知識，亦能更認識海洋歷史中的澎湖！', `organizer`='文化部文化資產局', `address`='澎湖縣馬公市', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='馬公市（澎湖縣）=', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefb26b32408680bebf5', '「AI繪紅樓・紅樓會AI」展覽', '「AI繪紅樓・紅樓會AI」展覽登場，探索科技與文學的交融之美\r\n由國立金門大學華語文學系主辦、金門縣文化局協辦的「AI繪紅樓・紅樓會AI」展覽將於114年3月14日(五)至3月20日(四)止，在金門縣文化局第三展場展出。本展覽結合生成式人工智慧（Generative AI, GAI）與《紅樓夢》經典意象，展現科技與文學交織的無限可能，誠摯邀請各界蒞臨參觀。\r\n此次展覽由國立金門大學華語文學系李瑄教授攜手紅學家張玉明教授，共同指導金大華文系學生運用GAI技術創作《紅樓夢》中的八大人物（賈寶玉、林黛玉、薛寶釵等），以及「共讀西廂」、「黛玉葬花」、「寶釵撲蝶」、「寶玉出家」等經典場景，是本次展覽主軸。李瑄教授表示：「ChatGPT 3.5於2022年問世後，AI技術迅速發展，翻轉了教育與創作方式。本展覽是華語文學系探索AI與文學融合的階段性成果，每個人都可以讓《紅樓夢》人物與場景從書中走出來，開啟嶄新的詮釋可能。」。展區內將播放AI生成的紅樓音樂作品，讓觀眾透過多元形式感受紅樓文化的魅力。\r\n除了科技創作，亦展出手作文創作品，如花籤、紙雕、人物小書等，讓手作文創與科技創作相互輝映，共同勾勒出當代的紅樓詮釋。此外，特別邀請金門文人雅士陳邦祥老師與洪篤欽先生展出珍藏品，如各版本《紅樓夢》、近現代著名畫家之紅樓夢畫冊等珍貴書籍，並陳列清代束冠、髮簪、鎖片、點翠、紙鳶等文物，帶領觀眾穿越時空，窺探紅樓時代的日常生活。\r\n這場結合AI科技、文學藝術的展覽，將帶領觀眾從創作、古物、書籍等多重視角，再次閱讀《紅樓夢》。歡迎有興趣的民眾把握機會，一同走進AI與紅樓交會的時空！\r\n展覽資訊：\r\n●展覽期間：114年3月14日（五）至3月20日（四）\r\n●展覽地點：金門縣文化局一樓第三展場\r\n●定時導覽：由國立金門大學華語文學系師生進行導覽，並介紹如何使用AI生成圖片及音樂\r\n114年3月15日（六）上午11時、下午2時、4時\r\n114年3月16日（日）上午11時、下午2時、4時\r\n114年3月17日（一）下午2時\r\n114年3月18日（二）下午2時\r\n●展覽宣傳影片：https://youtu.be/cdJ4ISmnVGo?si=qOLdhq48kHmFlsja\r\n●更多詳情請看展覽介紹：https://aimixtheredchamber.my.canva.site/', '國立金門大學', '金門縣金城鎮環島北路一段66號', '2025-03-14 00:00:00', '2025-03-20 00:00:00', '金門縣文化局', 24.38402, 118.30128, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「AI繪紅樓・紅樓會AI」展覽', `description`='「AI繪紅樓・紅樓會AI」展覽登場，探索科技與文學的交融之美\r\n由國立金門大學華語文學系主辦、金門縣文化局協辦的「AI繪紅樓・紅樓會AI」展覽將於114年3月14日(五)至3月20日(四)止，在金門縣文化局第三展場展出。本展覽結合生成式人工智慧（Generative AI, GAI）與《紅樓夢》經典意象，展現科技與文學交織的無限可能，誠摯邀請各界蒞臨參觀。\r\n此次展覽由國立金門大學華語文學系李瑄教授攜手紅學家張玉明教授，共同指導金大華文系學生運用GAI技術創作《紅樓夢》中的八大人物（賈寶玉、林黛玉、薛寶釵等），以及「共讀西廂」、「黛玉葬花」、「寶釵撲蝶」、「寶玉出家」等經典場景，是本次展覽主軸。李瑄教授表示：「ChatGPT 3.5於2022年問世後，AI技術迅速發展，翻轉了教育與創作方式。本展覽是華語文學系探索AI與文學融合的階段性成果，每個人都可以讓《紅樓夢》人物與場景從書中走出來，開啟嶄新的詮釋可能。」。展區內將播放AI生成的紅樓音樂作品，讓觀眾透過多元形式感受紅樓文化的魅力。\r\n除了科技創作，亦展出手作文創作品，如花籤、紙雕、人物小書等，讓手作文創與科技創作相互輝映，共同勾勒出當代的紅樓詮釋。此外，特別邀請金門文人雅士陳邦祥老師與洪篤欽先生展出珍藏品，如各版本《紅樓夢》、近現代著名畫家之紅樓夢畫冊等珍貴書籍，並陳列清代束冠、髮簪、鎖片、點翠、紙鳶等文物，帶領觀眾穿越時空，窺探紅樓時代的日常生活。\r\n這場結合AI科技、文學藝術的展覽，將帶領觀眾從創作、古物、書籍等多重視角，再次閱讀《紅樓夢》。歡迎有興趣的民眾把握機會，一同走進AI與紅樓交會的時空！\r\n展覽資訊：\r\n●展覽期間：114年3月14日（五）至3月20日（四）\r\n●展覽地點：金門縣文化局一樓第三展場\r\n●定時導覽：由國立金門大學華語文學系師生進行導覽，並介紹如何使用AI生成圖片及音樂\r\n114年3月15日（六）上午11時、下午2時、4時\r\n114年3月16日（日）上午11時、下午2時、4時\r\n114年3月17日（一）下午2時\r\n114年3月18日（二）下午2時\r\n●展覽宣傳影片：https://youtu.be/cdJ4ISmnVGo?si=qOLdhq48kHmFlsja\r\n●更多詳情請看展覽介紹：https://aimixtheredchamber.my.canva.site/', `organizer`='國立金門大學', `address`='金門縣金城鎮環島北路一段66號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-20 00:00:00', `location`='金門縣文化局', `latitude`=24.38402, `longitude`=118.30128, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefb26b32408680bebf6', '「策展人陪我看展覽」故宮專題導覽：歲時吉慶－院藏節令文物精萃(第2場)', '本院北部院區展覽區除常設展外，每季皆陸續熱烈推出器物、書畫、圖書、文獻等多樣特展，各種不同的展示主題藉由策展人的巧思安排與設計規畫，向觀眾呈現了本院典藏文物的豐富精華。爰此，各展覽將各別安排教育活動，由本院策展團隊成員在展場為觀眾導覽，陪伴觀眾一同探索當期展覽！\r\n\r\n活動名稱：「策展人陪我看展覽」導覽活動\r\n活動時間：2025年 (每場次導覽約50-90分鐘)。\r\n活動地點：本院北部院區第一展覽區(正館)陳列室。\r\n活動對象與人數：凡對文化、藝術、故宮文物有興趣的人士(適合高中以上之人士參加)，每場次參加者為10-20人。本活動須至本院線上系統報名，額滿為止(※本活動採單人報名，恕不受理團體報名)。\r\n活動語言：華語。', '國立故宮博物院', '臺北市士林區外雙溪至善路2段221號', '2025-03-21 00:00:00', '2025-03-21 00:00:00', '國立故宮博物院', 25.12546704, 121.5508473, '優惠參觀券+150;團體參觀券+230;普通參觀券+250;至善園+20', 'http://www.npm.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「策展人陪我看展覽」故宮專題導覽：歲時吉慶－院藏節令文物精萃(第2場)', `description`='本院北部院區展覽區除常設展外，每季皆陸續熱烈推出器物、書畫、圖書、文獻等多樣特展，各種不同的展示主題藉由策展人的巧思安排與設計規畫，向觀眾呈現了本院典藏文物的豐富精華。爰此，各展覽將各別安排教育活動，由本院策展團隊成員在展場為觀眾導覽，陪伴觀眾一同探索當期展覽！\r\n\r\n活動名稱：「策展人陪我看展覽」導覽活動\r\n活動時間：2025年 (每場次導覽約50-90分鐘)。\r\n活動地點：本院北部院區第一展覽區(正館)陳列室。\r\n活動對象與人數：凡對文化、藝術、故宮文物有興趣的人士(適合高中以上之人士參加)，每場次參加者為10-20人。本活動須至本院線上系統報名，額滿為止(※本活動採單人報名，恕不受理團體報名)。\r\n活動語言：華語。', `organizer`='國立故宮博物院', `address`='臺北市士林區外雙溪至善路2段221號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='國立故宮博物院', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='優惠參觀券+150;團體參觀券+230;普通參觀券+250;至善園+20', `source_url`='http://www.npm.gov.tw', `image_url`='[]';
