INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefb26b32408680bebf9', '「策展人陪我看展覽」故宮專題導覽：賞賜有禮－清代文獻中的天子禮物(第1場)', '本院北部院區展覽區除常設展外，每季皆陸續熱烈推出器物、書畫、圖書、文獻等多樣特展，各種不同的展示主題藉由策展人的巧思安排與設計規畫，向觀眾呈現了本院典藏文物的豐富精華。爰此，各展覽將各別安排教育活動，由本院策展團隊成員在展場為觀眾導覽，陪伴觀眾一同探索當期展覽！\r\n\r\n活動名稱：「策展人陪我看展覽」導覽活動\r\n活動時間：2025年 (每場次導覽約50-90分鐘)。\r\n活動地點：本院北部院區第一展覽區(正館)陳列室。\r\n活動對象與人數：凡對文化、藝術、故宮文物有興趣的人士(適合高中以上之人士參加)，每場次參加者為10-20人。本活動須至本院線上系統報名，額滿為止(※本活動採單人報名，恕不受理團體報名)。\r\n活動語言：華語。', '國立故宮博物院', '臺北市士林區外雙溪至善路2段221號', '2025-04-18 00:00:00', '2025-04-18 00:00:00', '國立故宮博物院', 25.12546704, 121.5508473, '優惠參觀券+150;團體參觀券+230;普通參觀券+250;至善園+20', 'http://www.npm.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「策展人陪我看展覽」故宮專題導覽：賞賜有禮－清代文獻中的天子禮物(第1場)', `description`='本院北部院區展覽區除常設展外，每季皆陸續熱烈推出器物、書畫、圖書、文獻等多樣特展，各種不同的展示主題藉由策展人的巧思安排與設計規畫，向觀眾呈現了本院典藏文物的豐富精華。爰此，各展覽將各別安排教育活動，由本院策展團隊成員在展場為觀眾導覽，陪伴觀眾一同探索當期展覽！\r\n\r\n活動名稱：「策展人陪我看展覽」導覽活動\r\n活動時間：2025年 (每場次導覽約50-90分鐘)。\r\n活動地點：本院北部院區第一展覽區(正館)陳列室。\r\n活動對象與人數：凡對文化、藝術、故宮文物有興趣的人士(適合高中以上之人士參加)，每場次參加者為10-20人。本活動須至本院線上系統報名，額滿為止(※本活動採單人報名，恕不受理團體報名)。\r\n活動語言：華語。', `organizer`='國立故宮博物院', `address`='臺北市士林區外雙溪至善路2段221號', `start_date`='2025-04-18 00:00:00', `end_date`='2025-04-18 00:00:00', `location`='國立故宮博物院', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='優惠參觀券+150;團體參觀券+230;普通參觀券+250;至善園+20', `source_url`='http://www.npm.gov.tw', `image_url`='[]';
