INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefb26b32408680bec01', '冶野藝術工作室《人間探戈》（地點：陳景蘭洋樓）', '《人間探戈》震撼登場🔥\r\n跨越百年 探戈舞動金門古蹟 \r\n4月19日16:00｜陳景蘭洋樓\r\n\r\n本作融合探戈、芭蕾與當代舞蹈語彙，搭配阿根廷音樂大師皮亞佐拉的經典鉅作《探戈的歷史》，以舞蹈詮釋時代變遷，帶領觀眾跨越百年時光，沉浸於藝術與歷史交織的情感共鳴。\r\n《人間探戈》是一部深具哲思與藝術張力的作品，探討個體與社會的微妙關係，並透過舞蹈空間的轉換，呈現不同時代社交場域的變遷。演出將帶來六支風格迥異、層次豐富的舞碼，從音樂、肢體動作與舞台場景設計出發，構築一場跨時代的感官饗宴。探戈舞步間的張力與流動，不僅象徵人類面對變遷的掙扎與適應，更展現人性對愛、自由與歸屬感的不懈追尋。每一個動作、每一次轉身，都是對生命與歷史的詮釋，讓觀眾在觀賞過程中產生深刻共鳴。\r\n\r\n演出特別採用環境劇場的創新形式，突破傳統舞台與觀眾席的界線，使舞蹈與環境相互交融。演出空間將根據陳景蘭洋樓的歷史背景與建築特色量身打造，透過場域的獨特氛圍，使舞蹈作品更具歷史厚度與藝術張力，讓觀眾在沉浸式體驗中，感受藝術與空間共鳴的獨特魅力。透過舞者與觀眾的零距離互動，打破觀看與表演的界線，創造全新的藝術體驗。\r\n\r\n冶野藝術工作室 Untamind Art Studio自成立以來，持續推動成人藝術教育與身心靈發展，致力於以舞蹈為媒介進行跨領域創作，並積極策辦舞蹈工作坊與藝術參與活動，促進藝術與大眾之間的交流。此次《人間探戈》不僅是舞蹈藝術的一次重要展演，更是一場文化與歷史的深度對話，期望透過藝術的力量，引發觀眾對於時代變遷與個體價值的深刻省思。\r\n主辦／金門縣文化局\r\n承辦／冶野藝術工作室', '金門縣文化局', '金門縣金湖鎮', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '金湖鎮（金門縣）=', 24.41496, 118.40373, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='冶野藝術工作室《人間探戈》（地點：陳景蘭洋樓）', `description`='《人間探戈》震撼登場🔥\r\n跨越百年 探戈舞動金門古蹟 \r\n4月19日16:00｜陳景蘭洋樓\r\n\r\n本作融合探戈、芭蕾與當代舞蹈語彙，搭配阿根廷音樂大師皮亞佐拉的經典鉅作《探戈的歷史》，以舞蹈詮釋時代變遷，帶領觀眾跨越百年時光，沉浸於藝術與歷史交織的情感共鳴。\r\n《人間探戈》是一部深具哲思與藝術張力的作品，探討個體與社會的微妙關係，並透過舞蹈空間的轉換，呈現不同時代社交場域的變遷。演出將帶來六支風格迥異、層次豐富的舞碼，從音樂、肢體動作與舞台場景設計出發，構築一場跨時代的感官饗宴。探戈舞步間的張力與流動，不僅象徵人類面對變遷的掙扎與適應，更展現人性對愛、自由與歸屬感的不懈追尋。每一個動作、每一次轉身，都是對生命與歷史的詮釋，讓觀眾在觀賞過程中產生深刻共鳴。\r\n\r\n演出特別採用環境劇場的創新形式，突破傳統舞台與觀眾席的界線，使舞蹈與環境相互交融。演出空間將根據陳景蘭洋樓的歷史背景與建築特色量身打造，透過場域的獨特氛圍，使舞蹈作品更具歷史厚度與藝術張力，讓觀眾在沉浸式體驗中，感受藝術與空間共鳴的獨特魅力。透過舞者與觀眾的零距離互動，打破觀看與表演的界線，創造全新的藝術體驗。\r\n\r\n冶野藝術工作室 Untamind Art Studio自成立以來，持續推動成人藝術教育與身心靈發展，致力於以舞蹈為媒介進行跨領域創作，並積極策辦舞蹈工作坊與藝術參與活動，促進藝術與大眾之間的交流。此次《人間探戈》不僅是舞蹈藝術的一次重要展演，更是一場文化與歷史的深度對話，期望透過藝術的力量，引發觀眾對於時代變遷與個體價值的深刻省思。\r\n主辦／金門縣文化局\r\n承辦／冶野藝術工作室', `organizer`='金門縣文化局', `address`='金門縣金湖鎮', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='金湖鎮（金門縣）=', `latitude`=24.41496, `longitude`=118.40373, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
