INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bac26b32408680bec11', '【新北市立圖書館三重分館】114年3月【閱讀書籤】- 「財源滾滾來」主題書展', '館名：三重分館\r\n地址：三重區自強路一段158號\r\n電話：02-2981-4887 #11、13 服務臺\r\n時間：3/1~3/31    開館時間\r\n\r\n書展名稱：財源滾滾來\r\n簡介：無論你是社會新鮮人、邁入中年的三明治族，還是屆齡退休的養老樂活族，學習儲蓄、理財、投資幾乎是每個人一生必學的功課。畢竟「錢不是萬能，但沒有錢萬萬不能」，為了自己的未來，請學習將寶貴的金錢和時間好好規劃、滾出長長的複利，讓自己有個與眾不同的美好未來。', '新北市立圖書館總館', '新北市三重區自強路一段158號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館三重分館', 25.06281651, 121.4870977, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三重分館】114年3月【閱讀書籤】- 「財源滾滾來」主題書展', `description`='館名：三重分館\r\n地址：三重區自強路一段158號\r\n電話：02-2981-4887 #11、13 服務臺\r\n時間：3/1~3/31    開館時間\r\n\r\n書展名稱：財源滾滾來\r\n簡介：無論你是社會新鮮人、邁入中年的三明治族，還是屆齡退休的養老樂活族，學習儲蓄、理財、投資幾乎是每個人一生必學的功課。畢竟「錢不是萬能，但沒有錢萬萬不能」，為了自己的未來，請學習將寶貴的金錢和時間好好規劃、滾出長長的複利，讓自己有個與眾不同的美好未來。', `organizer`='新北市立圖書館總館', `address`='新北市三重區自強路一段158號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館三重分館', `latitude`=25.06281651, `longitude`=121.4870977, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bac26b32408680bec12', '【新北市立圖書館三重田中分館】114年3月【閱讀書籤】- 「花季植栽」主題書展', '館名：三重田中分館\r\n地址：三重區忠孝路三段40巷51號2樓\r\n電話：02-2971-1633\r\n時間：3/1~3/31 開館時間\r\n\r\n書展名稱：花季植栽\r\n簡介：春天來了！在亞熱帶氣候型態的台灣，隨著季節的變化，可以輕鬆栽培景觀植物，藉由園藝、花草栽培的相關書籍，一起來打造屬於自己的小花園，把春天迎接到家裡。', '新北市立圖書館總館', '新北市三重區忠孝路三段40巷51號2樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館三重田中分館', 25.06281651, 121.4870977, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三重田中分館】114年3月【閱讀書籤】- 「花季植栽」主題書展', `description`='館名：三重田中分館\r\n地址：三重區忠孝路三段40巷51號2樓\r\n電話：02-2971-1633\r\n時間：3/1~3/31 開館時間\r\n\r\n書展名稱：花季植栽\r\n簡介：春天來了！在亞熱帶氣候型態的台灣，隨著季節的變化，可以輕鬆栽培景觀植物，藉由園藝、花草栽培的相關書籍，一起來打造屬於自己的小花園，把春天迎接到家裡。', `organizer`='新北市立圖書館總館', `address`='新北市三重區忠孝路三段40巷51號2樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館三重田中分館', `latitude`=25.06281651, `longitude`=121.4870977, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bac26b32408680bec13', '【新北市立圖書館三重培德分館】114年3月【閱讀書籤】- 「藝術與美術館」主題書展', '館名：三重培德分館\r\n地址：三重區忠孝路二段35號\r\n電話：02-2984-2179\r\n時間：3/1~3/31    開館時間\r\n \r\n書展名稱：藝術與美術館\r\n簡介：美術館是一個能夠讓人們接觸藝術作品、深入了解藝術家的生平和文化背景，並促進文化交流和藝術教育的地方。它們在保存和傳播藝術遺產方面發揮了重要作用，並提供了一個能夠啟發和豐富人們的生活的場所。', '新北市立圖書館總館', '新北市三重區忠孝路2段35號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館三重培德分館', 25.06281651, 121.4870977, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三重培德分館】114年3月【閱讀書籤】- 「藝術與美術館」主題書展', `description`='館名：三重培德分館\r\n地址：三重區忠孝路二段35號\r\n電話：02-2984-2179\r\n時間：3/1~3/31    開館時間\r\n \r\n書展名稱：藝術與美術館\r\n簡介：美術館是一個能夠讓人們接觸藝術作品、深入了解藝術家的生平和文化背景，並促進文化交流和藝術教育的地方。它們在保存和傳播藝術遺產方面發揮了重要作用，並提供了一個能夠啟發和豐富人們的生活的場所。', `organizer`='新北市立圖書館總館', `address`='新北市三重區忠孝路2段35號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館三重培德分館', `latitude`=25.06281651, `longitude`=121.4870977, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bb126b32408680bec14', '【新北市立圖書館三芝分館】《閱讀書籤》3月主題書展', '「『她』有話說」\r\n書展期間：3/01-3/08\r\n書展簡介：\r\n國際婦女節與女權有深遠的關聯，在歷史的推動下，讓女性的得以在經濟、政治和社會等領域佔有一席之地。而這些積極爭取的權益的女性們，每一位都有著精采的故事，就讓我們一起來看看吧!\r\n\r\n「有樹真好」\r\n書展期間：3/09-3/16\r\n書展簡介：\r\n有樹木的存在讓空氣得以淨化，有樹的存在讓小動物有避風港，有樹的存在讓我們烈陽下有遮蔽地方，你們說有樹好不好呢?可是根據調查人類砍樹的數量，遠遠大於種樹的數量，許多學者們都證明了樹對於地球永續的重要性，希望我們可以一起停止過度砍伐。藉由書籍我們一起學習如何護樹吧!\r\n\r\n「改造體態靠拉伸」\r\n書展期間：3/17-3/24\r\n書展簡介：\r\n想要完美體態除了攝取均衡的飲食外，可以配合適當的拉伸來達成。平日裡習慣所造成的姿勢不良，也可以透過拉伸導正骨骼回到正確位置，一起看書學習打造好體態吧~!\r\n\r\n「彩蛋兔子」\r\n書展期間：3/25-3/31\r\n書展簡介：\r\n嘿!你知道復活節其實每年的日期其實都不一定會一樣嗎?可愛的兔子、復活節彩蛋之間又有什麼關聯呢?讓我們一起看書找找答案吧!\r\n\r\n', '新北市立圖書館總館', '新北市三芝區淡金路1段37號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館三芝分館', 25.23159891, 121.515558, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三芝分館】《閱讀書籤》3月主題書展', `description`='「『她』有話說」\r\n書展期間：3/01-3/08\r\n書展簡介：\r\n國際婦女節與女權有深遠的關聯，在歷史的推動下，讓女性的得以在經濟、政治和社會等領域佔有一席之地。而這些積極爭取的權益的女性們，每一位都有著精采的故事，就讓我們一起來看看吧!\r\n\r\n「有樹真好」\r\n書展期間：3/09-3/16\r\n書展簡介：\r\n有樹木的存在讓空氣得以淨化，有樹的存在讓小動物有避風港，有樹的存在讓我們烈陽下有遮蔽地方，你們說有樹好不好呢?可是根據調查人類砍樹的數量，遠遠大於種樹的數量，許多學者們都證明了樹對於地球永續的重要性，希望我們可以一起停止過度砍伐。藉由書籍我們一起學習如何護樹吧!\r\n\r\n「改造體態靠拉伸」\r\n書展期間：3/17-3/24\r\n書展簡介：\r\n想要完美體態除了攝取均衡的飲食外，可以配合適當的拉伸來達成。平日裡習慣所造成的姿勢不良，也可以透過拉伸導正骨骼回到正確位置，一起看書學習打造好體態吧~!\r\n\r\n「彩蛋兔子」\r\n書展期間：3/25-3/31\r\n書展簡介：\r\n嘿!你知道復活節其實每年的日期其實都不一定會一樣嗎?可愛的兔子、復活節彩蛋之間又有什麼關聯呢?讓我們一起看書找找答案吧!\r\n\r\n', `organizer`='新北市立圖書館總館', `address`='新北市三芝區淡金路1段37號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館三芝分館', `latitude`=25.23159891, `longitude`=121.515558, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bb226b32408680bec15', '【新北市立圖書館板橋江子翠分館】114年3月《閱讀書籤》主題書展「醫療與健康」', '展出日期：114年3月1日至3月31日\r\n開放時間：週二至週六 8時30分至21時；週日至週一 8時30分至17時\r\n展示地點：新北市板橋區莊敬路62號 / 3樓書展區\r\n主題說明：\r\n【醫療與健康】\r\n健康是快樂的人生不可或缺的條件之一，除了養成良好的飲食與生活習慣， 醫療更是我們維護健康的一大助力，透過閱讀我們可以更了解醫療相關知識，讓我們更懂得如何提升醫療行為的品質，進而維持身體健康。', '新北市立圖書館總館', '新北市板橋區莊敬路62號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館板橋江子翠分館', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館板橋江子翠分館】114年3月《閱讀書籤》主題書展「醫療與健康」', `description`='展出日期：114年3月1日至3月31日\r\n開放時間：週二至週六 8時30分至21時；週日至週一 8時30分至17時\r\n展示地點：新北市板橋區莊敬路62號 / 3樓書展區\r\n主題說明：\r\n【醫療與健康】\r\n健康是快樂的人生不可或缺的條件之一，除了養成良好的飲食與生活習慣， 醫療更是我們維護健康的一大助力，透過閱讀我們可以更了解醫療相關知識，讓我們更懂得如何提升醫療行為的品質，進而維持身體健康。', `organizer`='新北市立圖書館總館', `address`='新北市板橋區莊敬路62號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館板橋江子翠分館', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
