INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bcd26b32408680bec1c', '鋁線動物園展覽', '本次將展出鋁線動物作品。\r\n用鋁線精心編織出各種動物，每一隻動物都栩栩如生，在金屬線條的交織中展現生命的靈動與力量！', '臺中市立圖書館后里分館', '臺中市后里區文化路28號', '2025-03-01 00:00:00', '2025-03-25 00:00:00', '臺中市立圖書館后里分館', 24.30962483, 120.7146127, '無資料', 'https://reurl.cc/r3mZq1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鋁線動物園展覽', `description`='本次將展出鋁線動物作品。\r\n用鋁線精心編織出各種動物，每一隻動物都栩栩如生，在金屬線條的交織中展現生命的靈動與力量！', `organizer`='臺中市立圖書館后里分館', `address`='臺中市后里區文化路28號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='臺中市立圖書館后里分館', `latitude`=24.30962483, `longitude`=120.7146127, `ticket_price`='無資料', `source_url`='https://reurl.cc/r3mZq1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bcd26b32408680bec1d', '腸道菌點點名展覽', '展出電腦繪圖腸道菌擬人化角色。\r\n\r\n寵物的腸道中居住著數以萬計的微生物，它們默默影響著健康、情緒。\r\n科學毛怪 PetSci將這些微生物以「電腦繪圖」，透過擬人化讓這些隱藏在體內的菌種「現身」，化身為獨具個性的角色。\r\n現在，就讓我們一起進入微觀世界，看看他們會長什麼樣子吧！', '臺中市立圖書館后里分館', '臺中市后里區文化路28號', '2025-03-01 00:00:00', '2025-03-27 00:00:00', '臺中市立圖書館后里分館', 24.30962483, 120.7146127, '無資料', 'https://reurl.cc/L58XKa', '[]') ON DUPLICATE KEY UPDATE `activity_name`='腸道菌點點名展覽', `description`='展出電腦繪圖腸道菌擬人化角色。\r\n\r\n寵物的腸道中居住著數以萬計的微生物，它們默默影響著健康、情緒。\r\n科學毛怪 PetSci將這些微生物以「電腦繪圖」，透過擬人化讓這些隱藏在體內的菌種「現身」，化身為獨具個性的角色。\r\n現在，就讓我們一起進入微觀世界，看看他們會長什麼樣子吧！', `organizer`='臺中市立圖書館后里分館', `address`='臺中市后里區文化路28號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-27 00:00:00', `location`='臺中市立圖書館后里分館', `latitude`=24.30962483, `longitude`=120.7146127, `ticket_price`='無資料', `source_url`='https://reurl.cc/L58XKa', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bcd26b32408680bec1f', '台語聽故事(3月，3場)', '※台語聽故事爸媽\r\n03/08 唱歌予貓仔聽\r\n一本可讀、可看又可唱的繪本！\r\n作息規律的鋼琴家杜魯魯先生，每天準時十一點上床睡覺，可是今晚，公寓的屋頂上來了一隻貓，喵喵喵的叫聲打破了原本安靜的夜晚。於是，杜魯魯決定起床彈奏搖籃曲來哄貓咪入睡，他一邊彈一邊唱，昏昏欲睡的他怎麼也想不到，他的歌聲不但讓貓變得更有精神，而且還吸引來了更多蹦蹦跳跳的貓……\r\n\r\n📌活動自由入場，歡迎大家與我們一同聽故事學台語\r\n📌前8位報名者，於活動前簽到、活動後簽退，即可領取獎勵貼紙一份(不挑款)\r\n📌全程參與活動並簽到者贈送小氣球1個(不挑款)\r\n報名網址：https://www.beclass.com/rid=294fe6667aea3f851bb0\r\n\r\n※母語故事屋\r\n03/22 不管，我就是要買!\r\n獅子、鱷魚和貓咪為了想吃鮮魚料理，相約一起上市場買魚。市場裡各種攤位應有盡有，琳瑯滿目，他們馬上就被吸引住了。\r\n獅子買了帥氣的帽子、鱷魚買了口感刺激的汽水、貓咪買了高跟鞋。他們買完一個又繼續買另一個。「買東西讓人超開心的！」於是，三個好朋友越買越多，東西塞滿了購物車……\r\n奇怪，他們好像忘了一開始為什麼要來市場？\r\n\r\n03/29 瞎子和跛子、果樹村的故事\r\n中國孩子的故事-瞎子和跛子、果樹村的故事', '臺中市立圖書館后里分館', '臺中市后里區文化路28號', '2025-03-08 00:00:00', '2025-03-29 00:00:00', '臺中市立圖書館后里分館', 24.30962483, 120.7146127, '無資料', 'https://reurl.cc/Q5yW8q 、 https://reurl.cc/V0rRyA', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台語聽故事(3月，3場)', `description`='※台語聽故事爸媽\r\n03/08 唱歌予貓仔聽\r\n一本可讀、可看又可唱的繪本！\r\n作息規律的鋼琴家杜魯魯先生，每天準時十一點上床睡覺，可是今晚，公寓的屋頂上來了一隻貓，喵喵喵的叫聲打破了原本安靜的夜晚。於是，杜魯魯決定起床彈奏搖籃曲來哄貓咪入睡，他一邊彈一邊唱，昏昏欲睡的他怎麼也想不到，他的歌聲不但讓貓變得更有精神，而且還吸引來了更多蹦蹦跳跳的貓……\r\n\r\n📌活動自由入場，歡迎大家與我們一同聽故事學台語\r\n📌前8位報名者，於活動前簽到、活動後簽退，即可領取獎勵貼紙一份(不挑款)\r\n📌全程參與活動並簽到者贈送小氣球1個(不挑款)\r\n報名網址：https://www.beclass.com/rid=294fe6667aea3f851bb0\r\n\r\n※母語故事屋\r\n03/22 不管，我就是要買!\r\n獅子、鱷魚和貓咪為了想吃鮮魚料理，相約一起上市場買魚。市場裡各種攤位應有盡有，琳瑯滿目，他們馬上就被吸引住了。\r\n獅子買了帥氣的帽子、鱷魚買了口感刺激的汽水、貓咪買了高跟鞋。他們買完一個又繼續買另一個。「買東西讓人超開心的！」於是，三個好朋友越買越多，東西塞滿了購物車……\r\n奇怪，他們好像忘了一開始為什麼要來市場？\r\n\r\n03/29 瞎子和跛子、果樹村的故事\r\n中國孩子的故事-瞎子和跛子、果樹村的故事', `organizer`='臺中市立圖書館后里分館', `address`='臺中市后里區文化路28號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市立圖書館后里分館', `latitude`=24.30962483, `longitude`=120.7146127, `ticket_price`='無資料', `source_url`='https://reurl.cc/Q5yW8q 、 https://reurl.cc/V0rRyA', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bce26b32408680bec20', '烏日分館：銀髮達人~竹編雕刻作品展', '銀髮達人~竹編雕刻作品展\r\n日期：3/5(三)-3/26(三)\r\n地點：4樓中庭\r\n銀髮編刻達人劉素靜老師，師承國寶級竹編工藝大師李榮烈先生，累計17年竹編雕刻畫之技藝。不斷運用編織與雕刻技能，創作許多竹藝作品(包含多樣的竹編籃子瓶子及竹藝雕刻飾品等)，展現出銀髮長者的文化手藝及生命韌性。', '無資料', '臺中市烏日區興祥街121號', '2025-03-05 00:00:00', '2025-03-26 00:00:00', '臺中市立圖書館烏日分館', 24.1096375, 120.6374111, '無資料', 'https://reurl.cc/eGe3aR', '[]') ON DUPLICATE KEY UPDATE `activity_name`='烏日分館：銀髮達人~竹編雕刻作品展', `description`='銀髮達人~竹編雕刻作品展\r\n日期：3/5(三)-3/26(三)\r\n地點：4樓中庭\r\n銀髮編刻達人劉素靜老師，師承國寶級竹編工藝大師李榮烈先生，累計17年竹編雕刻畫之技藝。不斷運用編織與雕刻技能，創作許多竹藝作品(包含多樣的竹編籃子瓶子及竹藝雕刻飾品等)，展現出銀髮長者的文化手藝及生命韌性。', `organizer`='無資料', `address`='臺中市烏日區興祥街121號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='臺中市立圖書館烏日分館', `latitude`=24.1096375, `longitude`=120.6374111, `ticket_price`='無資料', `source_url`='https://reurl.cc/eGe3aR', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bce26b32408680bec21', '下課後電影院(3月，5場)', '03/02 阿拉丁\r\n緊張刺激的沙漠冒險，神祕魔幻的阿拉伯元素，獨立自主的公主愛上街頭小混混，神燈精靈讓三個願望成真，真人版《阿拉丁》不但還原了動畫的盛大場面和經典音樂，導演蓋瑞奇的加入讓故事更精采緊湊，還有威爾史密斯飾演神燈精靈， 嘻哈搞笑的風格給了電影嶄新的世界。\r\n\r\n03/09 小豆腐大冒險\r\n以妖怪世界中最可愛的小豆腐為主角，因模樣太過可愛，嚇人類不成反被嘲笑，殊不知父親非但沒輕言細語地安慰心靈受傷的小豆腐、反而大聲的怒斥，小豆腐難過地跑進森林要找媽媽，卻不慎上了壞蛋狸貓的當而被封印。\r\n\r\n03/16 侏儸紀世界\r\n「侏儸紀公園」被重新建立，並規劃成主題樂園，成功吸引世界各地人潮慕名而來。 新的樂園號稱100%安全，更有在前3集未出現過的全新物種。 園方每日讓恐龍在遊客面前表演，就在人類與恐龍「和平共存」時，發生了一場意外讓恐龍展開攻擊，人類開始面臨生死存亡的危機！\r\n\r\n03/23 怪獸電力公司\r\n一個與人類世界並存的怪物世界，怪物會從衣櫥的門溜進來嚇小孩，因為人類小孩的驚叫聲，正是怪物世界運作的能量來源，「怪獸電力公司」正是製造能量的工廠。但隨著時代愈來愈進步，小朋友也愈來愈不容易被嚇到，怪物的世界因此面臨嚴重的能源危機……\r\n\r\n03/30 小鬼當家4\r\n這個耶誕節，凱文又陷入了水深火熱之中，馬夫和他的夥伴也無法倖免。馬夫一夥想偷竊娜塔莉房子裡的東西! 在這部闔家歡爆笑喜劇中，凱文阻攔犯罪的裝置比以往更有趣也更高科技，他甚至有可能把這些騙子永遠雪藏，還可能讓父母團聚！', '臺中市立圖書館后里分館', '臺中市后里區文化路28號', '2025-03-02 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館后里分館', 24.30962483, 120.7146127, '無資料', 'https://reurl.cc/xpylx1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='下課後電影院(3月，5場)', `description`='03/02 阿拉丁\r\n緊張刺激的沙漠冒險，神祕魔幻的阿拉伯元素，獨立自主的公主愛上街頭小混混，神燈精靈讓三個願望成真，真人版《阿拉丁》不但還原了動畫的盛大場面和經典音樂，導演蓋瑞奇的加入讓故事更精采緊湊，還有威爾史密斯飾演神燈精靈， 嘻哈搞笑的風格給了電影嶄新的世界。\r\n\r\n03/09 小豆腐大冒險\r\n以妖怪世界中最可愛的小豆腐為主角，因模樣太過可愛，嚇人類不成反被嘲笑，殊不知父親非但沒輕言細語地安慰心靈受傷的小豆腐、反而大聲的怒斥，小豆腐難過地跑進森林要找媽媽，卻不慎上了壞蛋狸貓的當而被封印。\r\n\r\n03/16 侏儸紀世界\r\n「侏儸紀公園」被重新建立，並規劃成主題樂園，成功吸引世界各地人潮慕名而來。 新的樂園號稱100%安全，更有在前3集未出現過的全新物種。 園方每日讓恐龍在遊客面前表演，就在人類與恐龍「和平共存」時，發生了一場意外讓恐龍展開攻擊，人類開始面臨生死存亡的危機！\r\n\r\n03/23 怪獸電力公司\r\n一個與人類世界並存的怪物世界，怪物會從衣櫥的門溜進來嚇小孩，因為人類小孩的驚叫聲，正是怪物世界運作的能量來源，「怪獸電力公司」正是製造能量的工廠。但隨著時代愈來愈進步，小朋友也愈來愈不容易被嚇到，怪物的世界因此面臨嚴重的能源危機……\r\n\r\n03/30 小鬼當家4\r\n這個耶誕節，凱文又陷入了水深火熱之中，馬夫和他的夥伴也無法倖免。馬夫一夥想偷竊娜塔莉房子裡的東西! 在這部闔家歡爆笑喜劇中，凱文阻攔犯罪的裝置比以往更有趣也更高科技，他甚至有可能把這些騙子永遠雪藏，還可能讓父母團聚！', `organizer`='臺中市立圖書館后里分館', `address`='臺中市后里區文化路28號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館后里分館', `latit