INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bce26b32408680bec25', '心嶼測繪 Echoes of an Island', '《心嶼測繪》聯展 "Echoes of an Island"\r\n\r\n❙ 藝術家：林志瑜、張庭甄、練佳昕、胡家瑜\r\n❙ 開幕茶會：3/15(六)15:00\r\n❙ 展期：2025/3/8(六) - 4/12(六)\r\n❙ 地點：台中市西區忠誠街35號\r\n❙ 營業時間：週二至週六 9:30-18:30（週日、週ㄧ休館） \r\n\r\n• ≈ • ≈ • ≈ • ≈ •\r\n\r\n迎接春分暖煦時節，臻品藝術推出《心嶼測繪 Echoes of an Island》聯展，匯聚四位青年藝術家——林志瑜、張庭甄、練佳昕與胡家瑜的最新作品。他們以臺灣這片土地為靈感，將日常即景、自然生態與文化傳承融入創作中，呈現對島嶼觀察、內化後的錦繡風光。\r\n\r\n林志瑜的山居景色、張庭甄的流動水韻、練佳昕的過渡風景與胡家瑜的布農族敘事，共同勾勒出島嶼心靈地圖。3月8日至4月12日，歡迎您傾聽這片土地的回音，感受其中蘊藏的記憶、變遷與歸屬，測繪屬於自己的內在坐標。\r\n', '無資料', '臺中市西區', '2025-03-08 00:00:00', '2025-04-12 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://www.lpd.com.tw/art-content.php?ID=209', '[]') ON DUPLICATE KEY UPDATE `activity_name`='心嶼測繪 Echoes of an Island', `description`='《心嶼測繪》聯展 "Echoes of an Island"\r\n\r\n❙ 藝術家：林志瑜、張庭甄、練佳昕、胡家瑜\r\n❙ 開幕茶會：3/15(六)15:00\r\n❙ 展期：2025/3/8(六) - 4/12(六)\r\n❙ 地點：台中市西區忠誠街35號\r\n❙ 營業時間：週二至週六 9:30-18:30（週日、週ㄧ休館） \r\n\r\n• ≈ • ≈ • ≈ • ≈ •\r\n\r\n迎接春分暖煦時節，臻品藝術推出《心嶼測繪 Echoes of an Island》聯展，匯聚四位青年藝術家——林志瑜、張庭甄、練佳昕與胡家瑜的最新作品。他們以臺灣這片土地為靈感，將日常即景、自然生態與文化傳承融入創作中，呈現對島嶼觀察、內化後的錦繡風光。\r\n\r\n林志瑜的山居景色、張庭甄的流動水韻、練佳昕的過渡風景與胡家瑜的布農族敘事，共同勾勒出島嶼心靈地圖。3月8日至4月12日，歡迎您傾聽這片土地的回音，感受其中蘊藏的記憶、變遷與歸屬，測繪屬於自己的內在坐標。\r\n', `organizer`='無資料', `address`='臺中市西區', `start_date`='2025-03-08 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.lpd.com.tw/art-content.php?ID=209', `image_url`='[]';
