INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bce26b32408680bec27', '臺中市立圖書館北屯分館3月主題書展', '運動主題書展是一個專注於運動、體育及相關領域書籍的展示活動，旨在鼓勵人們了解運動的價值、益處，並推動健康生活方式。', '臺中市立圖書館北屯分館', '臺中市北屯區大連路三段122號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺中市立圖書館北屯分館', 24.18400298, 120.7362319, '無資料', 'https://reurl.cc/geOadb', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館北屯分館3月主題書展', `description`='運動主題書展是一個專注於運動、體育及相關領域書籍的展示活動，旨在鼓勵人們了解運動的價值、益處，並推動健康生活方式。', `organizer`='臺中市立圖書館北屯分館', `address`='臺中市北屯區大連路三段122號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺中市立圖書館北屯分館', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://reurl.cc/geOadb', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bce26b32408680bec28', '臺中市立圖書館北屯分館假日電影院-月球歷險記', '有時候聽妹妹的話會比較保險！身為太空迷彼德在某個夜晚發現妹妹不見了，他才突然意識到妹妹之前瘋狂談論的會說話的六月金龜子「樹樹蟲」並不是虛構的。於是，彼德踏上了月球之旅，要將妹妹從大壞蛋「月人」手中拯救出來。旅途中他遇到了許多自然界的神靈，也才發現自己一直忽視了妹妹…\r\n', '臺中市立圖書館北屯分館', '臺中市北屯區大連路三段122號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '臺中市立圖書館北屯分館', 24.18400298, 120.7362319, '無資料', 'https://reurl.cc/geOadb', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館北屯分館假日電影院-月球歷險記', `description`='有時候聽妹妹的話會比較保險！身為太空迷彼德在某個夜晚發現妹妹不見了，他才突然意識到妹妹之前瘋狂談論的會說話的六月金龜子「樹樹蟲」並不是虛構的。於是，彼德踏上了月球之旅，要將妹妹從大壞蛋「月人」手中拯救出來。旅途中他遇到了許多自然界的神靈，也才發現自己一直忽視了妹妹…\r\n', `organizer`='臺中市立圖書館北屯分館', `address`='臺中市北屯區大連路三段122號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市立圖書館北屯分館', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://reurl.cc/geOadb', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bd226b32408680bec2a', '臺中市立圖書館興安分館~台語故事列車(台語3月3場)', '閱讀列車啟動，逗陣來學台語。\r\n透過繪本裡的精采故事，讓台語的文字與聲調語言之美，讓更多人愛上多元語言、愛上閱讀，鬥陣來講台語。\r\n推薦繪本:\r\n1.阿媽的果子園\r\n2.事情沒那麼容易 \r\n3.唱歌予貓仔聽                                                                          \r\n', '臺中市立圖書館興安分館', '臺中市北屯區興安路一段162號', '2025-03-05 00:00:00', '2025-03-19 00:00:00', '臺中市立圖書館興安分館', 24.18400298, 120.7362319, '無資料', 'https://reurl.cc/aZ2noX', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館興安分館~台語故事列車(台語3月3場)', `description`='閱讀列車啟動，逗陣來學台語。\r\n透過繪本裡的精采故事，讓台語的文字與聲調語言之美，讓更多人愛上多元語言、愛上閱讀，鬥陣來講台語。\r\n推薦繪本:\r\n1.阿媽的果子園\r\n2.事情沒那麼容易 \r\n3.唱歌予貓仔聽                                                                          \r\n', `organizer`='臺中市立圖書館興安分館', `address`='臺中市北屯區興安路一段162號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-03-19 00:00:00', `location`='臺中市立圖書館興安分館', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://reurl.cc/aZ2noX', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bd226b32408680bec2b', '臺中市立圖書館興安分館~新住民說愛的故事(3月2場)', '一起探索、認識多元文化、多元語言的美好。\r\n歡迎來親體驗聽故事，一起拉拉手、大人小孩來聽故事。\r\n邀請多元大使越南老師、緬甸老師，到圖書館說故事。\r\n', '臺中市立圖書館興安分館', '臺中市北屯區興安路一段162號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '臺中市立圖書館興安分館', 24.18400298, 120.7362319, '無資料', 'https://reurl.cc/6jrZok', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館興安分館~新住民說愛的故事(3月2場)', `description`='一起探索、認識多元文化、多元語言的美好。\r\n歡迎來親體驗聽故事，一起拉拉手、大人小孩來聽故事。\r\n邀請多元大使越南老師、緬甸老師，到圖書館說故事。\r\n', `organizer`='臺中市立圖書館興安分館', `address`='臺中市北屯區興安路一段162號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市立圖書館興安分館', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://reurl.cc/6jrZok', `image_url`='[]';
