INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bd326b32408680bec31', '臺中市立圖書館興安分館~電影放映賞析(3/22)', '影片簡介: 《沙丘》\r\n本電影改編自作家法蘭克·赫伯特1965年英文同名科幻小說。電影《沙丘》前半部分內容，是兩部改編電影計畫中的第一部；講述出身貴族家庭的年輕繼承者背負起守護銀河系中最寶貴的資產也是最重要的元素的任務的故事。歡迎一起來看電影。', '臺中市立圖書館興安分館', '臺中市北屯區興安路一段162號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺中市立圖書館興安分館', 24.18400298, 120.7362319, '無資料', 'https://reurl.cc/b30Ee6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館興安分館~電影放映賞析(3/22)', `description`='影片簡介: 《沙丘》\r\n本電影改編自作家法蘭克·赫伯特1965年英文同名科幻小說。電影《沙丘》前半部分內容，是兩部改編電影計畫中的第一部；講述出身貴族家庭的年輕繼承者背負起守護銀河系中最寶貴的資產也是最重要的元素的任務的故事。歡迎一起來看電影。', `organizer`='臺中市立圖書館興安分館', `address`='臺中市北屯區興安路一段162號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺中市立圖書館興安分館', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://reurl.cc/b30Ee6', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bd426b32408680bec34', '禪繞畫展：心之所安-禪繞在書海的浪漫', '❝創作禪繞的靜心過程，讓心安住在當下，剎那間世界只有全然的自己。從書海閱讀中找到相應的美好。❞\r\n創作者曾雅楓老師(美國禪繞認證講師)，透過閱讀與書中的字句邂逅，並將這份美好的感動融入到禪繞畫創作之中，邀請大家來館欣賞~\r\n', '臺中市立圖書館李科永紀念圖書分館', '臺中市南屯區龍富路五段1號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館李科永紀念圖書分館', 24.14165524, 120.6177379, '無資料', 'https://is.gd/g2EQwN', '[]') ON DUPLICATE KEY UPDATE `activity_name`='禪繞畫展：心之所安-禪繞在書海的浪漫', `description`='❝創作禪繞的靜心過程，讓心安住在當下，剎那間世界只有全然的自己。從書海閱讀中找到相應的美好。❞\r\n創作者曾雅楓老師(美國禪繞認證講師)，透過閱讀與書中的字句邂逅，並將這份美好的感動融入到禪繞畫創作之中，邀請大家來館欣賞~\r\n', `organizer`='臺中市立圖書館李科永紀念圖書分館', `address`='臺中市南屯區龍富路五段1號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館李科永紀念圖書分館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://is.gd/g2EQwN', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bd426b32408680bec37', '臺中市立圖書館大肚瑞井分館-114年03月主題書展', '1樓書展\r\n3月主題書展 【臺語冊･講乎咱聽】\r\n多元閱讀繽紛季來囉!☺️\r\n本月將展出相關臺語、音樂等書籍📖\r\n做伙透過書本與文字讓母語融入我們生活日常😍\r\n逐家ta̍k-ke做伙tsuè-hé來lâi讀書tha̍k-tsu📖\r\n鬥陣講臺語tàu-tīn kóng Tâi-gí😄\r\n書展時間:3/1~3/30\r\n書展地點:大肚瑞井分館 1F\r\n2樓書展\r\n【神祇與文明：東西神話的傳說故事】\r\n本次書展將為讀者呈現東西方神話奇幻故事，😉\r\n帶領大家深入探索各國神祇的神秘與有趣傳說，並如何影響當地的傳統與習俗。😲\r\n大肚瑞井分館邀您一起走進書中世界，體驗不同文化的風情、民俗與價值觀。👻\r\n展覽時間:3/1~4/30\r\n展覽地點:大肚瑞井分館 2F', '臺中市立圖書館大肚瑞井分館', '臺中市大肚區華山路700號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館大肚瑞井分館', 24.14467504, 120.5543243, '無資料', 'https://reurl.cc/86dXAR；https://reurl.cc/geK6X4', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館大肚瑞井分館-114年03月主題書展', `description`='1樓書展\r\n3月主題書展 【臺語冊･講乎咱聽】\r\n多元閱讀繽紛季來囉!☺️\r\n本月將展出相關臺語、音樂等書籍📖\r\n做伙透過書本與文字讓母語融入我們生活日常😍\r\n逐家ta̍k-ke做伙tsuè-hé來lâi讀書tha̍k-tsu📖\r\n鬥陣講臺語tàu-tīn kóng Tâi-gí😄\r\n書展時間:3/1~3/30\r\n書展地點:大肚瑞井分館 1F\r\n2樓書展\r\n【神祇與文明：東西神話的傳說故事】\r\n本次書展將為讀者呈現東西方神話奇幻故事，😉\r\n帶領大家深入探索各國神祇的神秘與有趣傳說，並如何影響當地的傳統與習俗。😲\r\n大肚瑞井分館邀您一起走進書中世界，體驗不同文化的風情、民俗與價值觀。👻\r\n展覽時間:3/1~4/30\r\n展覽地點:大肚瑞井分館 2F', `organizer`='臺中市立圖書館大肚瑞井分館', `address`='臺中市大肚區華山路700號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館大肚瑞井分館', `latitude`=24.14467504, `longitude`=120.5543243, `ticket_price`='無資料', `source_url`='https://reurl.cc/86dXAR；https://reurl.cc/geK6X4', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bd726b32408680bec38', '2025 台灣光環境獎│徵件', '2025台灣光環境獎由中強光電文化藝術基金會（以下簡稱本會） 發起。為鼓勵公、民營組織共同營造優良的光環境，本會創立「台灣光環境獎」，期以推舉公共文化設施及環境中的優質照明設計，為台灣公共環境品質樹立典範。', '中強光電文化藝術基金會', '新北市淡水區中正路一段6巷36號', '2025-03-01 00:00:00', '2025-05-31 00:00:00', '雲門劇場', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 台灣光環境獎│徵件', `description`='2025台灣光環境獎由中強光電文化藝術基金會（以下簡稱本會） 發起。為鼓勵公、民營組織共同營造優良的光環境，本會創立「台灣光環境獎」，期以推舉公共文化設施及環境中的優質照明設計，為台灣公共環境品質樹立典範。', `organizer`='中強光電文化藝術基金會', `address`='新北市淡水區中正路一段6巷36號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='雲門劇場', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
