INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bdf26b32408680bec3c', '【新北市立圖書館板橋分館】114年3月《閱讀書籤》哲學之道', '	館名：新北市立圖書館板橋分館\r\n地址：新北市板橋區文化路一段23號\r\n電話：02-29664347#9\r\n時間：週二～週六 08:30-21:00；週日～週一 08:30-17:00；每月最後一週週四及國定假日休館\r\n書展主題：本次書展帶您走進思想的殿堂，探索人生的意義、道德的抉擇與世界的本質。精選東西方哲學經典與當代思辨著作，啟發智慧，拓展視野，讓哲學成為理解世界與自我的指南。', '新北市立圖書館總館', '新北市板橋區文化路一段23號3樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館板橋分館', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館板橋分館】114年3月《閱讀書籤》哲學之道', `description`='	館名：新北市立圖書館板橋分館\r\n地址：新北市板橋區文化路一段23號\r\n電話：02-29664347#9\r\n時間：週二～週六 08:30-21:00；週日～週一 08:30-17:00；每月最後一週週四及國定假日休館\r\n書展主題：本次書展帶您走進思想的殿堂，探索人生的意義、道德的抉擇與世界的本質。精選東西方哲學經典與當代思辨著作，啟發智慧，拓展視野，讓哲學成為理解世界與自我的指南。', `organizer`='新北市立圖書館總館', `address`='新北市板橋區文化路一段23號3樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館板橋分館', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bdf26b32408680bec3e', '2025年3月書法講堂-莊連棚《講黑說白-書法藝術空間的意象》', '書法講堂「講黑說白-書法藝術空間的意象」\r\n時    間：3/22（六）14:00~16:00\r\n地    點：彰化縣立圖書館三樓-書道館\r\n師    資：莊連棚\r\n  邀請新竹教育大學美勞教學碩士—莊連棚講師主講「講黑說白-書法藝術空間的意象」。\r\n\r\n【參加方式】 免報名※自由參加 \r\n【參加對象】想認識書法文字藝術之美的民眾或學童（需家長陪同）\r\n【洽詢電話】04-7250057轉2395 李小姐\r\n●各場全程參與之公務員，核予研習時數2小時。公務人員請於活動前至公務人員終身學習入口網站報名\r\n\r\n★想要了解更多書法活動和訊息者，歡迎加入「書道館之友」社群\r\n◎加入密碼請輸入：2395 ', '彰化縣文化局', '彰化縣彰化市中山路2段500號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '彰化縣立圖書館', 24.07532909, 120.5694208, '無資料', 'https://www.bocach.gov.tw/News_Content.aspx?n=193&s=45514', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年3月書法講堂-莊連棚《講黑說白-書法藝術空間的意象》', `description`='書法講堂「講黑說白-書法藝術空間的意象」\r\n時    間：3/22（六）14:00~16:00\r\n地    點：彰化縣立圖書館三樓-書道館\r\n師    資：莊連棚\r\n  邀請新竹教育大學美勞教學碩士—莊連棚講師主講「講黑說白-書法藝術空間的意象」。\r\n\r\n【參加方式】 免報名※自由參加 \r\n【參加對象】想認識書法文字藝術之美的民眾或學童（需家長陪同）\r\n【洽詢電話】04-7250057轉2395 李小姐\r\n●各場全程參與之公務員，核予研習時數2小時。公務人員請於活動前至公務人員終身學習入口網站報名\r\n\r\n★想要了解更多書法活動和訊息者，歡迎加入「書道館之友」社群\r\n◎加入密碼請輸入：2395 ', `organizer`='彰化縣文化局', `address`='彰化縣彰化市中山路2段500號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='彰化縣立圖書館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.bocach.gov.tw/News_Content.aspx?n=193&s=45514', `image_url`='[]';
