INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bdf26b32408680bec40', '2025太平洋左岸藝術季《2025世界盃街頭藝人錦標賽》', '邀請2024日本大道藝世界杯(DAIDOGE world cup in靜岡) 3組優秀深具民眾口碑的國際街頭藝人團隊義大利 Compagnia Bellavita 、日本天平、韓國Circus.D.Lab 與台灣虎劇團的鄭湧蒼辦理演出。\r\n作品將帶來國際性街頭藝人表演的水平融合馬戲表演、魔術、雜耍和音樂，以魔法般的高超技巧，將藝術表演的歡樂氛圍搬上舞台，精湛、令人耳目一新的肢體劇場盛宴並由花蓮觀眾投票選出心目中的第一名最優秀的表演者。\r\n#票選冠軍，購票入場觀眾有機會摸彩獲得1500元禮券~~', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '全票+300', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025太平洋左岸藝術季《2025世界盃街頭藝人錦標賽》', `description`='邀請2024日本大道藝世界杯(DAIDOGE world cup in靜岡) 3組優秀深具民眾口碑的國際街頭藝人團隊義大利 Compagnia Bellavita 、日本天平、韓國Circus.D.Lab 與台灣虎劇團的鄭湧蒼辦理演出。\r\n作品將帶來國際性街頭藝人表演的水平融合馬戲表演、魔術、雜耍和音樂，以魔法般的高超技巧，將藝術表演的歡樂氛圍搬上舞台，精湛、令人耳目一新的肢體劇場盛宴並由花蓮觀眾投票選出心目中的第一名最優秀的表演者。\r\n#票選冠軍，購票入場觀眾有機會摸彩獲得1500元禮券~~', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='全票+300', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bdf26b32408680bec41', '澳洲瑟卡馬戲團 ʚ 動物狂歡節 Carnival of the Animals ɞ', '꒰꒰動物狂歡節꒱꒱ 以法國浪漫主義作曲家卡米爾．聖桑的同名音樂作品為靈感融合馬戲、肢體特技、多媒體、古典音樂展開一場前所未有的動物探險旅程。\r\n𝟐𝟎𝟐𝟒年首登衛武營獲得熱銷好評\r\n𝟐𝟎𝟐𝟓年𝟓月動物狂潮獨降花蓮，為花蓮地區的大小朋友帶來驚奇不斷的肢體劇場盛宴', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-05-02 00:00:00', '2025-05-02 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '全票+690;全票+990', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='澳洲瑟卡馬戲團 ʚ 動物狂歡節 Carnival of the Animals ɞ', `description`='꒰꒰動物狂歡節꒱꒱ 以法國浪漫主義作曲家卡米爾．聖桑的同名音樂作品為靈感融合馬戲、肢體特技、多媒體、古典音樂展開一場前所未有的動物探險旅程。\r\n𝟐𝟎𝟐𝟒年首登衛武營獲得熱銷好評\r\n𝟐𝟎𝟐𝟓年𝟓月動物狂潮獨降花蓮，為花蓮地區的大小朋友帶來驚奇不斷的肢體劇場盛宴', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-05-02 00:00:00', `end_date`='2025-05-02 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='全票+690;全票+990', `source_url`='無資料', `image_url`='[]';
