INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29be026b32408680bec4d', '金門縣攝影學會會員聯展「祭‧平安」攝影展', '本次展覽的主題為「祭‧平安」，透過鏡頭捕捉金門寺廟與民間信仰活動的莊嚴與熱烈，呈現祭典過程中的虔誠氛圍，讓人感受到金門人民對信仰與傳統文化的深厚情感。展覽展現宗教信仰如何安定人心，培養同理心與慈悲，並給予心靈的安慰與內在的寧靜。\r\n\r\n參展的藝術家包括王衛煌、蔡添丁、王婷、蔡顯國、許進西、方朝良、鄭碧珍、許志恆、許雅玲、林筱雯、黃逸煥、黃奕偉、悟真、辛甫道、辛甫愿、陳宗新、俞政君、李衛脩、徐國輝、黃邦培、洪金池、許文科、蔡木在、王賢德等24位攝影家，共同呈現60幅精彩作品。', '金門縣文化局', '金門縣金城鎮環島北路一段66號', '2025-03-08 00:00:00', '2025-03-19 00:00:00', '金門縣文化局', 24.38402, 118.30128, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='金門縣攝影學會會員聯展「祭‧平安」攝影展', `description`='本次展覽的主題為「祭‧平安」，透過鏡頭捕捉金門寺廟與民間信仰活動的莊嚴與熱烈，呈現祭典過程中的虔誠氛圍，讓人感受到金門人民對信仰與傳統文化的深厚情感。展覽展現宗教信仰如何安定人心，培養同理心與慈悲，並給予心靈的安慰與內在的寧靜。\r\n\r\n參展的藝術家包括王衛煌、蔡添丁、王婷、蔡顯國、許進西、方朝良、鄭碧珍、許志恆、許雅玲、林筱雯、黃逸煥、黃奕偉、悟真、辛甫道、辛甫愿、陳宗新、俞政君、李衛脩、徐國輝、黃邦培、洪金池、許文科、蔡木在、王賢德等24位攝影家，共同呈現60幅精彩作品。', `organizer`='金門縣文化局', `address`='金門縣金城鎮環島北路一段66號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-19 00:00:00', `location`='金門縣文化局', `latitude`=24.38402, `longitude`=118.30128, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29be026b32408680bec4f', '114年度仁愛鄉製梅系列活動-梅好時光．玩樂部落', '梅好時光．玩樂部落\r\n一年一度的採製梅活動來囉，一起來中原部落來場採製梅體驗×賽德克文化探索。活動內容豐富，有原住民歌舞表演、傳統屋導覽、採梅、製梅體驗、烤大豬、在地市集。\r\n限額120名。\r\n報名連結 https://forms.gle/SsiZ1gwSVSq6EGus5\r\n活動洽詢：0955-676405 張小姐、0988-028377 林理事長。', '南投縣政府', '南投縣仁愛鄉', '2025-04-06 00:00:00', '2025-04-06 00:00:00', '仁愛鄉（南投縣）=', 24.02886513, 121.1443879, '成年人收費+500;6-12歲收費+350', 'https://www.facebook.com/profile.php?id=100064769920762', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度仁愛鄉製梅系列活動-梅好時光．玩樂部落', `description`='梅好時光．玩樂部落\r\n一年一度的採製梅活動來囉，一起來中原部落來場採製梅體驗×賽德克文化探索。活動內容豐富，有原住民歌舞表演、傳統屋導覽、採梅、製梅體驗、烤大豬、在地市集。\r\n限額120名。\r\n報名連結 https://forms.gle/SsiZ1gwSVSq6EGus5\r\n活動洽詢：0955-676405 張小姐、0988-028377 林理事長。', `organizer`='南投縣政府', `address`='南投縣仁愛鄉', `start_date`='2025-04-06 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='仁愛鄉（南投縣）=', `latitude`=24.02886513, `longitude`=121.1443879, `ticket_price`='成年人收費+500;6-12歲收費+350', `source_url`='https://www.facebook.com/profile.php?id=100064769920762', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29be026b32408680bec51', '2025年3月【雲林縣斗南鎮立圖書館-主題書展】愛上自已', '今天，你好嗎？　\r\n其實每個人都會有點小憂鬱...\r\n圖書館為總是因為那句話受傷的你...\r\n準備了豪華版心理學的閱讀饗宴"\r\n', '雲林縣斗南鎮立圖書館', '雲林縣斗南鎮福德街151號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '雲林縣斗南鎮立圖書館', 23.67066393, 120.4826356, '無資料', 'https://www.facebook.com/profile.php?id=100067848325539', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年3月【雲林縣斗南鎮立圖書館-主題書展】愛上自已', `description`='今天，你好嗎？　\r\n其實每個人都會有點小憂鬱...\r\n圖書館為總是因為那句話受傷的你...\r\n準備了豪華版心理學的閱讀饗宴"\r\n', `organizer`='雲林縣斗南鎮立圖書館', `address`='雲林縣斗南鎮福德街151號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='雲林縣斗南鎮立圖書館', `latitude`=23.67066393, `longitude`=120.4826356, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100067848325539', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29be026b32408680bec53', '2025年3月【雲林縣斗南鎮立圖書館-電影欣賞】(共2場)', '斗南鎮立圖書館-電影欣賞(共2場)\r\n日期：3/2 3/16\r\n地點：斗南鎮立圖書館\r\n片名：史蒂芬金之猴子\r\n改編自史蒂芬金1980年的同名短篇故事，溫子仁監製。《分歧者》席歐詹姆斯一人分飾兩角，對抗史上最兇殘詛咒！發條聲響起，離奇死亡事件即將展開！\r\n\r\n片名：喵的奇幻漂流\r\n2024金球獎最佳動畫片、2024安錫國際動畫影展評審團獎、觀眾票選獎、最佳原創音樂獎，2024 坎城影展一種注目單元選映。\r\n', '雲林縣斗南鎮立圖書館', '雲林縣斗南鎮福德街151號', '2025-03-02 00:00:00', '2025-03-16 00:00:00', '雲林縣斗南鎮立圖書館', 23.67066393, 120.4826356, '無資料', 'https://www.facebook.com/profile.php?id=100067848325539', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年3月【雲林縣斗南鎮立圖書館-電影欣賞】(共2場)', `description`='斗南鎮立圖書館-電影欣賞(共2場)\r\n日期：3/2 3/16\r\n地點：斗南鎮立圖書館\r\n片名：史蒂芬金之猴子\r\n改編自史蒂芬金1980年的同名短篇故事，溫子仁監製。《分歧者》席歐詹姆斯一人分飾兩角，對抗史上最兇殘詛咒！發條聲響起，離奇死亡事件即將展開！\r\n\r\n片名：喵的奇幻漂流\r\n2024金球獎最佳動畫片、2024安錫國際動畫影展評審團獎、觀眾票選獎、最佳原創音樂獎，2024 坎城影展一種注目單元選映。\r\n', `organizer`='雲林縣斗南鎮立圖書館', `address`='雲林縣斗南鎮福德街151號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='雲林縣斗南鎮立圖書館', `latitude`=23.67066393, `longitude`=120.4826356, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100067848325539', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d2aa6507f3d4433af95551', '凝視他方的旋轉小路—關於寫實', '金車文藝中心臺北南京館將於 4 月推出「凝視他方的旋轉小路 － 關於寫實」群展，由亞紀畫廊策劃，集結九位藝術家：詹詠幀、陳昭宏、鄺鉅裁、李吉祥、李秉璈、廖震平、黃海恩、吳逸寒、葉子奇，探討寫實主義如何超越技術性的框架，回歸其作為抵抗與表達的力量。從傳統寫生、文學對抗殖民視角，到數位時代的虛擬真實界線，藝術家們在各自的創作中回應寫實的當代意義，試圖重構寫實主義的多重面向。', '亞紀畫廊', '臺北市中山區南京東路二段1號3樓', '2025-04-08 00:00:00', '2025-05-18 00:00:00', '金車文藝中心 臺北南京館', 25.06969917, 121.5381597, '無資料', 'https://www.kingcarart.org.tw/exhibitions-detail/222', '[]') ON DUPLICATE KEY UPDATE `activity_name`='凝視他方的旋轉小路—關於寫實', `description`='金車文藝中心臺北南京館將於 4 月推出「凝視他方的旋轉小路 － 關於寫實」群展，由亞紀畫廊策劃，集結九位藝術家：詹詠幀、陳昭宏、鄺鉅裁、李吉祥、李秉璈、廖震平、黃海恩、吳逸寒、葉子奇，探討寫實主義如何超越技術性的框架，回歸其作為抵抗與表達的力量。從傳統寫生、文學對抗殖民視角，到數位時代的虛擬真實界線，藝術家們在各自的創作中回應寫實的當代意義，試圖重構寫實主義的多重面向。', `organizer`='亞紀畫廊', `address`='臺北市中山區南京東路二段1號3樓', `start_date`='2025-04-08 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='金車文藝中心 臺北南京館', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='https://www.kingcarart.org.tw/exhibitions-detail/222', `image_url`='[]';
