INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d3416726b32408680bec5f', '【新北市立圖書館三重分館】114年3月【彩虹故事屋】', '彩虹故事屋\r\n※故事繪本與時間若有更動，以活動現場為主※\r\n114年3月\r\n時間：週六下午2點-3點\r\n地點：三重分館兒童室\r\n(三重區自強路一段158號B1)\r\n \r\n03/01（六）\r\n免費贈送／林秋蘭（蘭花阿姨）\r\n我的願望：天天不挨罵／張雲賢（Apple姐姐）\r\n \r\n03/08（六）\r\nHello Kitty一起去賞花／賴怡璇（彩虹姐姐）\r\n寶從天上來／楊月雲（匠奶咪）\r\n驚天動地小命難保／李心渝（星星姐姐）\r\n \r\n03/15（六）\r\n安那害怕的時候／范鳳娥（玫瑰阿姨）\r\n怕浪費的奶奶／李怡青（QQ綠姐姐）\r\n沒有尾巴的小美人魚／葉俊男（Uncle安可） \r\n \r\n03/22（六）台語故事推廣週+手作DIY活動\r\n音樂唱遊說故事-虎姑婆（台語）／唐書惠（糖糖阿姨）\r\n迷你劇場-大口大口吃掉一半（台語）／李秀嬌（香香姐姐）\r\n黏土DIY-兒童節快樂／張雲賢（Apple姐姐）\r\n            \r\n03/29（六）\r\n阿摩的聰明藥／何靜宜（鯨魚阿姨）\r\n吃書的狐狸先生／李秀嬌（香香姐姐）\r\n章魚先生買褲子／趙麗芬（yoyo阿姨）', '新北市立圖書館總館', '新北市三重區自強路一段158號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '新北市立圖書館三重分館', 25.06281651, 121.4870977, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三重分館】114年3月【彩虹故事屋】', `description`='彩虹故事屋\r\n※故事繪本與時間若有更動，以活動現場為主※\r\n114年3月\r\n時間：週六下午2點-3點\r\n地點：三重分館兒童室\r\n(三重區自強路一段158號B1)\r\n \r\n03/01（六）\r\n免費贈送／林秋蘭（蘭花阿姨）\r\n我的願望：天天不挨罵／張雲賢（Apple姐姐）\r\n \r\n03/08（六）\r\nHello Kitty一起去賞花／賴怡璇（彩虹姐姐）\r\n寶從天上來／楊月雲（匠奶咪）\r\n驚天動地小命難保／李心渝（星星姐姐）\r\n \r\n03/15（六）\r\n安那害怕的時候／范鳳娥（玫瑰阿姨）\r\n怕浪費的奶奶／李怡青（QQ綠姐姐）\r\n沒有尾巴的小美人魚／葉俊男（Uncle安可） \r\n \r\n03/22（六）台語故事推廣週+手作DIY活動\r\n音樂唱遊說故事-虎姑婆（台語）／唐書惠（糖糖阿姨）\r\n迷你劇場-大口大口吃掉一半（台語）／李秀嬌（香香姐姐）\r\n黏土DIY-兒童節快樂／張雲賢（Apple姐姐）\r\n            \r\n03/29（六）\r\n阿摩的聰明藥／何靜宜（鯨魚阿姨）\r\n吃書的狐狸先生／李秀嬌（香香姐姐）\r\n章魚先生買褲子／趙麗芬（yoyo阿姨）', `organizer`='新北市立圖書館總館', `address`='新北市三重區自強路一段158號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='新北市立圖書館三重分館', `latitude`=25.06281651, `longitude`=121.4870977, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
