INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d3416926b32408680bec62', '【新北市立圖書館總館】114年3月閱讀書籤主題書展：證據會說話，鑑識搜查最前線', '「凡兩個物體接觸，必會產生轉移現象」。\r\n\r\n法國法醫學家、犯罪學家埃德蒙·羅卡創建的羅卡定律，\r\n其理論應用在於犯罪現場調查中，行為人（犯罪嫌疑者）必然會帶走一些東西，亦會留下一些東西。\r\n\r\n這些現場留下的微量跡證，能幫助還原事發當下、協助破案。然而，想抓到罪證可沒那麼簡單！讓我們一起初探鑑識的奧祕！', '新北市立圖書館總館', '新北市板橋區貴興路139號', '2025-03-03 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館總館', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館總館】114年3月閱讀書籤主題書展：證據會說話，鑑識搜查最前線', `description`='「凡兩個物體接觸，必會產生轉移現象」。\r\n\r\n法國法醫學家、犯罪學家埃德蒙·羅卡創建的羅卡定律，\r\n其理論應用在於犯罪現場調查中，行為人（犯罪嫌疑者）必然會帶走一些東西，亦會留下一些東西。\r\n\r\n這些現場留下的微量跡證，能幫助還原事發當下、協助破案。然而，想抓到罪證可沒那麼簡單！讓我們一起初探鑑識的奧祕！', `organizer`='新北市立圖書館總館', `address`='新北市板橋區貴興路139號', `start_date`='2025-03-03 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館總館', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
