INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d490df26b32408680bec83', '歡樂週末親子說故事活動3月份(共3場)', '為培養兒童閱讀習慣，讓閱讀向下扎根，本館說故事活動邀請說故事志工及社團法人台灣親子共學教育促進會，和大家一起玩故事、說故事，增添說故事活動的互動性和有趣性。\r\n3/08(六)14:00-15:00蘭蘭老師、美美老師【一顆小石頭，壞了一鍋米？】 \r\n3/22(六)14:00-15:00社團法人台灣親子共學教育促進會【和孩子同一國系列繪本】 \r\n3/29(六)14:30-15:00英文說故事小隊-Auntie Bee老師【Doctor De Soto】', '桃園市立圖書館', '桃園市中壢區強國路60號', '2025-03-08 00:00:00', '2025-03-29 00:00:00', '桃園市立圖書館自強分館', 24.97993803, 121.2147243, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歡樂週末親子說故事活動3月份(共3場)', `description`='為培養兒童閱讀習慣，讓閱讀向下扎根，本館說故事活動邀請說故事志工及社團法人台灣親子共學教育促進會，和大家一起玩故事、說故事，增添說故事活動的互動性和有趣性。\r\n3/08(六)14:00-15:00蘭蘭老師、美美老師【一顆小石頭，壞了一鍋米？】 \r\n3/22(六)14:00-15:00社團法人台灣親子共學教育促進會【和孩子同一國系列繪本】 \r\n3/29(六)14:30-15:00英文說故事小隊-Auntie Bee老師【Doctor De Soto】', `organizer`='桃園市立圖書館', `address`='桃園市中壢區強國路60號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='桃園市立圖書館自強分館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d490e526b32408680bec84', '神韻晚會2025年台灣巡迴演出 (6場)', '隨著一聲鑼響，大幕拉開，天國聖界的勝景、故國神州的美景將呈現在您的眼前。飛天仙女從雲海中升起；蒙古少年在草原上奔馳。那些蕩氣回腸的英雄事蹟，那些感人肺腑的美麗傳奇，被再度賦予生命。您將看到，一場演出，五千文明，如星漢般璀璨奪目。', '社團法人臺灣法輪大法學會', '桃園市桃園區中正路1188號', '2025-04-23 00:00:00', '2025-04-27 00:00:00', '桃園展演中心', 25.00040024, 121.2996612, '票價+2600;票價+3000;票價+3500;票價+4000;票價+5000', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='神韻晚會2025年台灣巡迴演出 (6場)', `description`='隨著一聲鑼響，大幕拉開，天國聖界的勝景、故國神州的美景將呈現在您的眼前。飛天仙女從雲海中升起；蒙古少年在草原上奔馳。那些蕩氣回腸的英雄事蹟，那些感人肺腑的美麗傳奇，被再度賦予生命。您將看到，一場演出，五千文明，如星漢般璀璨奪目。', `organizer`='社團法人臺灣法輪大法學會', `address`='桃園市桃園區中正路1188號', `start_date`='2025-04-23 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='桃園展演中心', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='票價+2600;票價+3000;票價+3500;票價+4000;票價+5000', `source_url`='無資料', `image_url`='[]';
