INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d490fe26b32408680bec89', '桃園光影文化館【光聚影像】闔家辣 Chilli Laugh Story［普］', '《闔家辣》是一部2022年香港電影，由鄭晉軒執導，吳君如監製兼領銜主演，鄭中基、梁詠琪及呂爵安領銜主演。\r\n新冠病毒疫情爆發，剛開始因為可以無拘無束地工作感到興奮，可是漸漸地就發現在家工作，比上班更艱難。年輕男孩柏軒在家工作期間，每天跟家人大眼瞪小眼，無意間發現母親的手工辣椒醬大受朋友好評，決定說服父親、大姑媽一起製作辣椒醬，再到社群平台上銷售，維護家庭和諧氣氛。沒想到這個無心插柳柳橙汁的突發奇想，正好迎合消費者在家吃飯的需要，辣椒醬生意一鳴驚人，創造銷售奇蹟，更為這一家人帶來許多意想不到的發展！', '桃園市政府文化局', '桃園市桃園區埔新路12號', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '桃園光影文化館', 25.00040024, 121.2996612, '無資料', 'https://kktix.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園光影文化館【光聚影像】闔家辣 Chilli Laugh Story［普］', `description`='《闔家辣》是一部2022年香港電影，由鄭晉軒執導，吳君如監製兼領銜主演，鄭中基、梁詠琪及呂爵安領銜主演。\r\n新冠病毒疫情爆發，剛開始因為可以無拘無束地工作感到興奮，可是漸漸地就發現在家工作，比上班更艱難。年輕男孩柏軒在家工作期間，每天跟家人大眼瞪小眼，無意間發現母親的手工辣椒醬大受朋友好評，決定說服父親、大姑媽一起製作辣椒醬，再到社群平台上銷售，維護家庭和諧氣氛。沒想到這個無心插柳柳橙汁的突發奇想，正好迎合消費者在家吃飯的需要，辣椒醬生意一鳴驚人，創造銷售奇蹟，更為這一家人帶來許多意想不到的發展！', `organizer`='桃園市政府文化局', `address`='桃園市桃園區埔新路12號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='桃園光影文化館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='https://kktix.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d490fe26b32408680bec8a', '桃園光影文化館【光聚影像】飯戲攻心 Table For Six［普］', '《飯戲攻心》（英語：Table For Six）是2022年香港喜劇電影，由陳詠燊編劇及導演，黃子華、鄧麗欣、張繼聰、王菀之、林明禎、陳湛文主演。\r\n一個家，最重要的是「人到齊了，開飯」！深信此道的大哥陳鴻廚藝普普，但用各種心靈雞湯式的金句餵飽二個不同父不同母的二弟陳禮及小弟陳熹。還請來小弟的廚神女友 Josephine煮晚餐，美味上桌，讓每晚 8 點的飯局更為和睦。', '桃園市政府文化局', '桃園市桃園區埔新路12號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '桃園光影文化館', 25.00040024, 121.2996612, '無資料', 'https://kktix.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園光影文化館【光聚影像】飯戲攻心 Table For Six［普］', `description`='《飯戲攻心》（英語：Table For Six）是2022年香港喜劇電影，由陳詠燊編劇及導演，黃子華、鄧麗欣、張繼聰、王菀之、林明禎、陳湛文主演。\r\n一個家，最重要的是「人到齊了，開飯」！深信此道的大哥陳鴻廚藝普普，但用各種心靈雞湯式的金句餵飽二個不同父不同母的二弟陳禮及小弟陳熹。還請來小弟的廚神女友 Josephine煮晚餐，美味上桌，讓每晚 8 點的飯局更為和睦。', `organizer`='桃園市政府文化局', `address`='桃園市桃園區埔新路12號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='桃園光影文化館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='https://kktix.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d490fe26b32408680bec8b', '桃園光影文化館【光聚影像】飯戲攻心2  Table For Six 2［普］', '《飯戲攻心2》（英語：Table For Six 2）是2024年上映的香港喜劇賀歲片，由陳詠燊編劇及導演，2022年電影《飯戲攻心》的續集。\r\n大哥離家遠行之際，家中的二哥和老三竟然擇定吉日，要把女友Monica和Josephine娶進門，而和大哥談戀愛的阿Meow又帶來了一場混亂，他們計畫連搞三場世紀婚宴，想要「喜上加喜喜」！怎料婚宴發展成自家叔伯兄弟之間的鬥獸場、姨媽姑姐的追星大會，接連上演勾大嫂風雲、超級賺錢大計等瘋狂戲碼，一家人還能開開心心的準時開飯嗎？', '桃園市政府文化局', '桃園市桃園區埔新路12號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '桃園光影文化館', 25.00040024, 121.2996612, '無資料', 'https://kktix.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園光影文化館【光聚影像】飯戲攻心2  Table For Six 2［普］', `description`='《飯戲攻心2》（英語：Table For Six 2）是2024年上映的香港喜劇賀歲片，由陳詠燊編劇及導演，2022年電影《飯戲攻心》的續集。\r\n大哥離家遠行之際，家中的二哥和老三竟然擇定吉日，要把女友Monica和Josephine娶進門，而和大哥談戀愛的阿Meow又帶來了一場混亂，他們計畫連搞三場世紀婚宴，想要「喜上加喜喜」！怎料婚宴發展成自家叔伯兄弟之間的鬥獸場、姨媽姑姐的追星大會，接連上演勾大嫂風雲、超級賺錢大計等瘋狂戲碼，一家人還能開開心心的準時開飯嗎？', `organizer`='桃園市政府文化局', `address`='桃園市桃園區埔新路12號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='桃園光影文化館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='https://kktix.com/', `image_url`='[]';
