INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4910f26b32408680bec8f', '狂美《讓我們從白雪公主開始》交響音樂會(2場)', '翻開手上厚厚的精裝書，銀白色華麗城堡躍然紙上！\r\n午夜12點的鐘聲響，南瓜馬車疾駛在路上找尋灰姑娘。\r\n狂美樂隊裡的樂手們，奏響首首童話主題曲的悠揚；\r\n公主與王子們在舞台高唱愛與夢想。\r\n當然，那位在現場說故事的領航者一樣重要。\r\n來吧！讓我們步步走進狂美的綺麗樂章。\r\n\r\n\r\n', '狂美交響管樂團', '桃園市中壢區中美路16號', '2025-03-14 00:00:00', '2025-03-15 00:00:00', '中壢藝術館', 24.958126, 121.227384, '票價+400;票價+600;票價+800;票價+1,000;票價+1,200;票價+1,500;票價+1,800;票價+2,200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='狂美《讓我們從白雪公主開始》交響音樂會(2場)', `description`='翻開手上厚厚的精裝書，銀白色華麗城堡躍然紙上！\r\n午夜12點的鐘聲響，南瓜馬車疾駛在路上找尋灰姑娘。\r\n狂美樂隊裡的樂手們，奏響首首童話主題曲的悠揚；\r\n公主與王子們在舞台高唱愛與夢想。\r\n當然，那位在現場說故事的領航者一樣重要。\r\n來吧！讓我們步步走進狂美的綺麗樂章。\r\n\r\n\r\n', `organizer`='狂美交響管樂團', `address`='桃園市中壢區中美路16號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='中壢藝術館', `latitude`=24.958126, `longitude`=121.227384, `ticket_price`='票價+400;票價+600;票價+800;票價+1,000;票價+1,200;票價+1,500;票價+1,800;票價+2,200', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4912726b32408680bec93', '中壢光影電影館3月影視工作坊｜光影變化師 (2場)', '(因老師拍攝檔期變動，原定3/8、3/9工作坊課程改至3/15、3/16)\r\n\r\n【影視培訓工作坊｜光影變化師】\r\n從影視燈光中，了解對於光的認識，到了解如何使用燈光設備去營造現場氛圍，透過實際的操作方式，讓學員可以對攝影與燈光有更進一步的認識，課程上另外安排講師經驗分享、用電與相關公安注意安全事項等介紹。\r\n【課程內容】\r\n📽03/15(六) 13:30-16:30｜第一堂：燈光基礎設計\r\n本節課程從基礎光的認識，教導民眾日常所見的光，透過課程去辦光的種類，從進階影視燈光中，去了解設備的使用，與燈光是如何被架構執行出來，並教導民眾正確安全的用電安全觀念。\r\n\r\n📽03/16(日) 13:30-16:30｜第二堂：燈光進階應用\r\n本節課程承接課程一，透過課程一對於燈光的學習實際操作演練，由講師出題，讓民眾實際透過影視設備完成題目所需的燈光設計，並且透過解析交流討論。\r\n\r\n✦ 參加方式：免費課程，需事先透過中壢光影電影館官方Accupass活動通報名系統線上報名，採分堂報名，額滿為止。\r\n✦ 課程人數：預計每堂課程20人。\r\n✦ 課程講師：蔡維陽(導演、燈光師)\r\n✦課程說明：本次課程分為兩部分，建議兩堂課程都報名參加，學習更完整！\r\n\r\n講師：蔡維陽(導演、燈光師)\r\n玖壹壹-嘻哈庄腳情/MV/製片\r\n眷戀‧慢漫光復/政府短片/導演、剪接（臺中市政府勞工局）\r\n女孩賀爾蒙/劇情短片/副導(公視學生劇展)\r\n釘子花/劇情短片/燈光（入圍第55屆金鐘獎電視電影獎/第41屆金穗獎學生組最佳劇情片)\r\n腸躁男孩/劇情短片/燈光（公視學生劇展）\r\n手事業/劇情短片/執行燈光（第57屆金馬獎最佳劇情短片入圍/第43屆金穗獎最佳劇情片）', '桃園市政府文化局', '桃園市中壢區馬祖新村11~20號', '2025-03-15 00:00:00', '2025-03-16 00:00:00', '馬祖新村眷村文創園區', 24.935843, 121.237822, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中壢光影電影館3月影視工作坊｜光影變化師 (2場)', `description`='(因老師拍攝檔期變動，原定3/8、3/9工作坊課程改至3/15、3/16)\r\n\r\n【影視培訓工作坊｜光影變化師】\r\n從影視燈光中，了解對於光的認識，到了解如何使用燈光設備去營造現場氛圍，透過實際的操作方式，讓學員可以對攝影與燈光有更進一步的認識，課程上另外安排講師經驗分享、用電與相關公安注意安全事項等介紹。\r\n【課程內容】\r\n📽03/15(六) 13:30-16:30｜第一堂：燈光基礎設計\r\n本節課程從基礎光的認識，教導民眾日常所見的光，透過課程去辦光的種類，從進階影視燈光中，去了解設備的使用，與燈光是如何被架構執行出來，並教導民眾正確安全的用電安全觀念。\r\n\r\n📽03/16(日) 13:30-16:30｜第二堂：燈光進階應用\r\n本節課程承接課程一，透過課程一對於燈光的學習實際操作演練，由講師出題，讓民眾實際透過影視設備完成題目所需的燈光設計，並且透過解析交流討論。\r\n\r\n✦ 參加方式：免費課程，需事先透過中壢光影電影館官方Accupass活動通報名系統線上報名，採分堂報名，額滿為止。\r\n✦ 課程人數：預計每堂課程20人。\r\n✦ 課程講師：蔡維陽(導演、燈光師)\r\n✦課程說明：本次課程分為兩部分，建議兩堂課程都報名參加，學習更完整！\r\n\r\n講師：蔡維陽(導演、燈光師)\r\n玖壹壹-嘻哈庄腳情/MV/製片\r\n眷戀‧慢漫光復/政府短片/導演、剪接（臺中市政府勞工局）\r\n女孩賀爾蒙/劇情短片/副導(公視學生劇展)\r\n釘子花/劇情短片/燈光（入圍第55屆金鐘獎電視電影獎/第41屆金穗獎學生組最佳劇情片)\r\n腸躁男孩/劇情短片/燈光（公視學生劇展）\r\n手事業/劇情短片/執行燈光（第57屆金馬獎最佳劇情短片入圍/第43屆金穗獎最佳劇情片）', `organizer`='桃園市政府文化局', `address`='桃園市中壢區馬祖新村11~20號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='馬祖新村眷村文創園區', `latitude`=24.935843, `longitude`=121.237822, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4913126b32408680bec94', '費登奎斯身體工作坊', '「抬頭！挺胸！收小腹！」大家一定都曾經聽過這樣地諄諄教誨，不管我們怎麼詮釋這個指令，好像永遠都不太到位，為什麼呢？到底標準是什麼？姿勢和姿態有什麼不同？\r\n這個工作坊會探索人類的脊椎，頭和骨盆之間的關鍵連結，就像是潛水艇裡的潛望鏡一般，有透視也有探勘的功能。你不需要擁有完美的身型、也不需要靈活的身軀來參與這一系列的動中覺察課程，只要帶著足夠的好奇心，每個人都可以為自己打造出一組最適合自己的潛望鏡！然後你可能會發現裝上潛望鏡的自己，變得更優雅靈活，你解讀「抬頭、挺胸、收小腹」的方式，會有所不同呢！', '慢島劇團', '桃園市桃園區新生路169號、169-1號', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '米倉劇場', 25.00040024, 121.2996612, '雙人同行+3600;表演藝術工作者優惠/人+1500;單人+2000', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='費登奎斯身體工作坊', `description`='「抬頭！挺胸！收小腹！」大家一定都曾經聽過這樣地諄諄教誨，不管我們怎麼詮釋這個指令，好像永遠都不太到位，為什麼呢？到底標準是什麼？姿勢和姿態有什麼不同？\r\n這個工作坊會探索人類的脊椎，頭和骨盆之間的關鍵連結，就像是潛水艇裡的潛望鏡一般，有透視也有探勘的功能。你不需要擁有完美的身型、也不需要靈活的身軀來參與這一系列的動中覺察課程，只要帶著足夠的好奇心，每個人都可以為自己打造出一組最適合自己的潛望鏡！然後你可能會發現裝上潛望鏡的自己，變得更優雅靈活，你解讀「抬頭、挺胸、收小腹」的方式，會有所不同呢！', `organizer`='慢島劇團', `address`='桃園市桃園區新生路169號、169-1號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='米倉劇場', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='雙人同行+3600;表演藝術工作者優惠/人+1500;單人+2000', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4913626b32408680bec95', '《場勘-众藝術》王弘志個展', '王弘志延續對空間記憶捕捉與辨識的探索，展覽中呈現的「中介物」（如展場、臺座、展示層板、椅凳等），在特定的時空位置上重新排列，試圖勾勒出創作者對該空間慣性運用的脈絡，進而體現並重新描繪創作者、作品、空間與觀者之間動態而多變的從屬關係。他經常在同一展場不同檔期展覽的觀察中發現，創作者呈現實體作品時，依循空間中錨定的對應方式：於相仿的位置裝設類似的臺座與層板，甚至座談時的桌椅安排亦極為相似；這些在空間中看似偶然與巧合的配置，是創作者順應觀者既有的觀看習慣，或是作品與該空間必然的既定連結？因此，王弘志將該空間中過往展覽中反覆出現的「中介物」置於共時狀態，以影像、物件、雕塑、空間裝置作為形式，希冀提供一個跨幅式、不同於以往的視角探究創作者對展覽空間的思考，進一步突顯藝術實體展覽空間的獨特性。\r\n「場勘─众藝術」將於3月15日（六）下午2點開幕，當天藝術家將於現場進行作品導覽，並邀請兩位視覺藝術家劉和讓、邱承宏參與開幕座談。展覽將延續至2025年4月13日（日）。', 'ZONE ART 众藝術', '桃園市桃園區中埔六街196巷22號', '2025-03-12 00:00:00', '2025-04-13 00:00:00', 'ZONE ART 众藝術', 25.00040024, 121.2996612, '無資料', 'https://www.facebook.com/ZATaoyuan', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《場勘-众藝術》王弘志個展', `description`='王弘志延續對空間記憶捕捉與辨識的探索，展覽中呈現的「中介物」（如展場、臺座、展示層板、椅凳等），在特定的時空位置上重新排列，試圖勾勒出創作者對該空間慣性運用的脈絡，進而體現並重新描繪創作者、作品、空間與觀者之間動態而多變的從屬關係。他經常在同一展場不同檔期展覽的觀察中發現，創作者呈現實體作品時，依循空間中錨定的對應方式：於相仿的位置裝設類似的臺座與層板，甚至座談時的桌椅安排亦極為相似；這些在空間中看似偶然與巧合的配置，是創作者順應觀者既有的觀看習慣，或是作品與該空間必然的既定連結？因此，王弘志將該空間中過往展覽中反覆出現的「中介物」置於共時狀態，以影像、物件、雕塑、空間裝置作為形式，希冀提供一個跨幅式、不同於以往的視角探究創作者對展覽空間的思考，進一步突顯藝術實體展覽空間的獨特性。\r\n「場勘─众藝術」將於3月15日（六）下午2點開幕，當天藝術家將於現場進行作品導覽，並邀請兩位視覺藝術家劉和讓、邱承宏參與開幕座談。展覽將延續至2025年4月13日（日）。', `organizer`='ZONE ART 众藝術', `address`='桃園市桃園區中埔六街196巷22號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='ZONE ART 众藝術', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='https://www.facebook.com/ZATaoyuan', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4913b26b32408680bec96', '2025年神韻臺灣巡迴演出(臺中-4場)', '神韻以藝術的形式復興華夏五千年的正統文化。\r\n神韻演出包括約20個節目，從漢唐盛世到明清宮廷，從江南美景到西北高原，舞蹈和舞劇節目的場景設置涵蓋神州每一處土地、每一段時光。節目中也展現了各式各樣的人物，從端莊秀美的仕女到馳騁沙場的大將，從仙風道骨的道教祖師到嬉笑怒罵的市井小民，個個都栩栩如生。節目中更描繪了現代中國社會堅持信仰的一群人，他們雖然遭受迫害，卻依然堅貞不屈，他們的故事催人淚下、感人至深。', '社團法人臺灣法輪大法學會', '臺中市北區學士路98號', '2025-04-02 00:00:00', '2025-04-04 00:00:00', '臺中市中山堂', 24.15863985, 120.6809521, '無資料', 'https://reurl.cc/2KMnWO', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年神韻臺灣巡迴演出(臺中-4場)', `description`='神韻以藝術的形式復興華夏五千年的正統文化。\r\n神韻演出包括約20個節目，從漢唐盛世到明清宮廷，從江南美景到西北高原，舞蹈和舞劇節目的場景設置涵蓋神州每一處土地、每一段時光。節目中也展現了各式各樣的人物，從端莊秀美的仕女到馳騁沙場的大將，從仙風道骨的道教祖師到嬉笑怒罵的市井小民，個個都栩栩如生。節目中更描繪了現代中國社會堅持信仰的一群人，他們雖然遭受迫害，卻依然堅貞不屈，他們的故事催人淚下、感人至深。', `organizer`='社團法人臺灣法輪大法學會', `address`='臺中市北區學士路98號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-04 00:00:00', `location`='臺中市中山堂', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://reurl.cc/2KMnWO', `image_url`='[]';
