INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4913d26b32408680bec99', '八德國中美術班學生藝文展', '此次展出的作品是學生將三年來在校所學淋漓盡致地呈現。孩子們藉由廣泛地蒐集資料，進行專題討論，其題材包含生命教育、海洋教育、環境生態與保護多元文化之議題，甚至霸凌、AI與戰爭等等，從不同視角觀看我們所處的環境。學生以視覺美學為基礎，運用多元媒材，進行創作，表現對生命與社會的關懷。此次展出作品包括西畫、水墨、版畫、平面設計、漫畫及書法等類別。期待透過這些作品與大家分享，讓創作者與觀賞者一同在藝術殿堂裡沈浸於這一場藝術饗宴。', '桃園市立八德國民中學', '桃園市八德區', '2025-03-03 00:00:00', '2025-05-30 00:00:00', '八德區（桃園市）=', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='八德國中美術班學生藝文展', `description`='此次展出的作品是學生將三年來在校所學淋漓盡致地呈現。孩子們藉由廣泛地蒐集資料，進行專題討論，其題材包含生命教育、海洋教育、環境生態與保護多元文化之議題，甚至霸凌、AI與戰爭等等，從不同視角觀看我們所處的環境。學生以視覺美學為基礎，運用多元媒材，進行創作，表現對生命與社會的關懷。此次展出作品包括西畫、水墨、版畫、平面設計、漫畫及書法等類別。期待透過這些作品與大家分享，讓創作者與觀賞者一同在藝術殿堂裡沈浸於這一場藝術饗宴。', `organizer`='桃園市立八德國民中學', `address`='桃園市八德區', `start_date`='2025-03-03 00:00:00', `end_date`='2025-05-30 00:00:00', `location`='八德區（桃園市）=', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4913d26b32408680bec9a', '客家歌謠班', '體驗客家文化的魅力，從基礎發音到優美歌聲，學會客家歌曲\r\n用音樂傳承客家文化。', '桃園市龜山區長庚社區發展協會', '桃園市龜山區', '2025-03-06 00:00:00', '2025-04-17 00:00:00', '龜山區（桃園市）=', 25.02417472, 121.3569265, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='客家歌謠班', `description`='體驗客家文化的魅力，從基礎發音到優美歌聲，學會客家歌曲\r\n用音樂傳承客家文化。', `organizer`='桃園市龜山區長庚社區發展協會', `address`='桃園市龜山區', `start_date`='2025-03-06 00:00:00', `end_date`='2025-04-17 00:00:00', `location`='龜山區（桃園市）=', `latitude`=25.02417472, `longitude`=121.3569265, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4913d26b32408680bec9b', '詩與三月的邂逅-傅鈺個展', '春風三月，詩意悄然氤氳，春的清麗與光影流轉。本次展覽以「邂逅」為題，象徵藝術與時間、情感與空間的相遇。因某個偶然讓傅鈺行走在今春的詩篇裡，每一幅畫作皆是一場與時光的偶遇，是三月未竟的詩、是光影、是色彩與情感的流動，在畫布上緩緩展開。\r\n\r\n傅鈺擅長以詩的語言做抽象表現，季節遞嬗為她創作生命的來源，窗外景色更迭，心中畫面跟著詩意高低起伏，用詩的情感創作，以細膩、自由的情感、筆觸與層層交疊的色彩，創造出詩般的氛圍，讓觀者在視覺與心靈間尋找共鳴。作品在老靈魂與現代語境間游移，展現詩性的無垠可能。畫面或輕柔、或濃烈，如春輕拂。而三月、既是萬物新生的季節，也是記憶甦醒的時刻。在這場展覽中，觀者或許能在這些作品中，與自己的思緒不期而遇。\r\n邀請每一位觀者在其中閱讀自己的故事，感受三月流轉的詩意與生命的悸動。', '隱藝空間工作室', '桃園市大園區大仁路48號', '2025-03-12 00:00:00', '2025-03-23 00:00:00', '隱藝術', 25.06384709, 121.21177, '無資料', 'https://www.yinartspace.org', '[]') ON DUPLICATE KEY UPDATE `activity_name`='詩與三月的邂逅-傅鈺個展', `description`='春風三月，詩意悄然氤氳，春的清麗與光影流轉。本次展覽以「邂逅」為題，象徵藝術與時間、情感與空間的相遇。因某個偶然讓傅鈺行走在今春的詩篇裡，每一幅畫作皆是一場與時光的偶遇，是三月未竟的詩、是光影、是色彩與情感的流動，在畫布上緩緩展開。\r\n\r\n傅鈺擅長以詩的語言做抽象表現，季節遞嬗為她創作生命的來源，窗外景色更迭，心中畫面跟著詩意高低起伏，用詩的情感創作，以細膩、自由的情感、筆觸與層層交疊的色彩，創造出詩般的氛圍，讓觀者在視覺與心靈間尋找共鳴。作品在老靈魂與現代語境間游移，展現詩性的無垠可能。畫面或輕柔、或濃烈，如春輕拂。而三月、既是萬物新生的季節，也是記憶甦醒的時刻。在這場展覽中，觀者或許能在這些作品中，與自己的思緒不期而遇。\r\n邀請每一位觀者在其中閱讀自己的故事，感受三月流轉的詩意與生命的悸動。', `organizer`='隱藝空間工作室', `address`='桃園市大園區大仁路48號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='隱藝術', `latitude`=25.06384709, `longitude`=121.21177, `ticket_price`='無資料', `source_url`='https://www.yinartspace.org', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4913e26b32408680bec9e', '客韻悠揚、音傳千里', '透過本活動，促進客家文化的永續發展，讓更多人感受到客家音樂的魅力。除協會會員外，一般民眾亦可參與。\r\n古箏&薩克斯風 \r\n1.11:20-11:25捱是你个人 \r\n2.11:25-11:30 細妹仔按靚 薩克斯風合奏 \r\n3.11:30-11:35 印岡戀歌 \r\n4.11:35-11:40 十七十八田莊女 舞蹈表演 \r\n5.11:40-11:45 我是客家人 \r\n6.11:45-11:50 大家來跳舞 電鋼琴演奏 \r\n7.11:50-11:55 客家本色 \r\n8.11:55-12:00 怨嘆自家 口琴表演 \r\n9.12:00-12:05 一條花手巾 \r\n10.12:05-12:10 思戀歌 二胡演奏 \r\n11.12:10-12:15 桃花開 \r\n12.12:15-12:20 瓜子仁 薩克斯風合奏 \r\n13.12:20-12:25 採茶細妹 \r\n14.12:25-12:30 雪梅思君 客家歌曲演唱 \r\n15.12:30-12:38 孤枕難眠 \r\n16.12:38-12:45 英雄淚', '桃園市金古錐才藝文化發展協會', '桃園市新屋區', '2025-03-16 00:00:00', '2025-03-16 00:00:00', '新屋區（桃園市）=', 24.97280352, 121.067758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='客韻悠揚、音傳千里', `description`='透過本活動，促進客家文化的永續發展，讓更多人感受到客家音樂的魅力。除協會會員外，一般民眾亦可參與。\r\n古箏&薩克斯風 \r\n1.11:20-11:25捱是你个人 \r\n2.11:25-11:30 細妹仔按靚 薩克斯風合奏 \r\n3.11:30-11:35 印岡戀歌 \r\n4.11:35-11:40 十七十八田莊女 舞蹈表演 \r\n5.11:40-11:45 我是客家人 \r\n6.11:45-11:50 大家來跳舞 電鋼琴演奏 \r\n7.11:50-11:55 客家本色 \r\n8.11:55-12:00 怨嘆自家 口琴表演 \r\n9.12:00-12:05 一條花手巾 \r\n10.12:05-12:10 思戀歌 二胡演奏 \r\n11.12:10-12:15 桃花開 \r\n12.12:15-12:20 瓜子仁 薩克斯風合奏 \r\n13.12:20-12:25 採茶細妹 \r\n14.12:25-12:30 雪梅思君 客家歌曲演唱 \r\n15.12:30-12:38 孤枕難眠 \r\n16.12:38-12:45 英雄淚', `organizer`='桃園市金古錐才藝文化發展協會', `address`='桃園市新屋區', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-16 00:00:00', `location`='新屋區（桃園市）=', `latitude`=24.97280352, `longitude`=121.067758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4913f26b32408680beca1', '我的旅行指「南」— 東南亞旅遊書展', '旅行不僅是移動，更是心靈的探索與文化的交會。本次東南亞主題書展《我的旅行指「南」》，以東南亞地區的旅遊為主題，邀請讀者透過書頁開啟一場紙上旅程，探索鄰近台灣的東南亞國家。從壯麗的山海風景到繽紛的文化傳統，從獨特的歷史風貌到當地的風土人情，讓閱讀成為一場沉浸式的旅行。菲律賓、越南、馬來西亞、新加坡……下一站，會是哪裡呢？', '高雄市立圖書館總館', '高雄市甲仙區6鄰中山路48號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '高雄市立圖書館甲仙分館', 23.0837971, 120.5877319, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='我的旅行指「南」— 東南亞旅遊書展', `description`='旅行不僅是移動，更是心靈的探索與文化的交會。本次東南亞主題書展《我的旅行指「南」》，以東南亞地區的旅遊為主題，邀請讀者透過書頁開啟一場紙上旅程，探索鄰近台灣的東南亞國家。從壯麗的山海風景到繽紛的文化傳統，從獨特的歷史風貌到當地的風土人情，讓閱讀成為一場沉浸式的旅行。菲律賓、越南、馬來西亞、新加坡……下一站，會是哪裡呢？', `organizer`='高雄市立圖書館總館', `address`='高雄市甲仙區6鄰中山路48號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='高雄市立圖書館甲仙分館', `latitude`=23.0837971, `longitude`=120.5877319, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4913f26b32408680beca3', '世界母語日主題書特展-上媠ê花蕊臺灣話', '展示臺灣在地語言、歷史、文學故事，以生活主題鼓勵讀者認識母語。', '高雄市立圖書館總館', '高雄市左營區2鄰啟文路12號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '高雄市立圖書館左營分館', 22.6735284, 120.2843433, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='世界母語日主題書特展-上媠ê花蕊臺灣話', `description`='展示臺灣在地語言、歷史、文學故事，以生活主題鼓勵讀者認識母語。', `organizer`='高雄市立圖書館總館', `address`='高雄市左營區2鄰啟文路12號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市立圖書館左營分館', `latitude`=22.6735284, `longitude`=120.2843433, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4913f26b32408680beca5', '從大港埔到大港的光輝歲月', '1.以新興區在地文史為主題，並結合台語文化元素，透過實地走讀，了解新興區的老地名、傳統風俗及台語俚語故事。\r\n2.活動路線：新興閱覽室、鼓壽宮、新興市場、銀行街、婚紗街、大港埔、美麗島捷運站、大港，愛河支流幸福川。\r\n講師:廖德嵩老師\r\n\r\n日期:3/29(六)下午14:00~16:00\r\n\r\n集合地點:新興民眾閱覽室(忠孝公園內)\r\n\r\n對象:親子/10組\r\n\r\n洽詢電話:07-241-1805\r\n\r\n', '高雄市立圖書館總館', '高雄市新興區', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '新興區（高雄市）=', 22.62992906, 120.3067337, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='從大港埔到大港的光輝歲月', `description`='1.以新興區在地文史為主題，並結合台語文化元素，透過實地走讀，了解新興區的老地名、傳統風俗及台語俚語故事。\r\n2.活動路線：新興閱覽室、鼓壽宮、新興市場、銀行街、婚紗街、大港埔、美麗島捷運站、大港，愛河支流幸福川。\r\n講師:廖德嵩老師\r\n\r\n日期:3/29(六)下午14:00~16:00\r\n\r\n集合地點:新興民眾閱覽室(忠孝公園內)\r\n\r\n對象:親子/10組\r\n\r\n洽詢電話:07-241-1805\r\n\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市新興區', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='新興區（高雄市）=', `latitude`=22.62992906, `longitude`=120.3067337, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914126b32408680beca6', '知識再生-圖書館的綠色未來 (書展)', '以圖書館與永續循環為結合相關書籍兒童繪本，讓孩童們於繪本了解永續經營。', '高雄市立圖書館總館', '高雄市前金區民生二路37號', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '高雄市立圖書館李科永紀念圖書館', 25.0421407, 121.5198716, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='知識再生-圖書館的綠色未來 (書展)', `description`='以圖書館與永續循環為結合相關書籍兒童繪本，讓孩童們於繪本了解永續經營。', `organizer`='高雄市立圖書館總館', `address`='高雄市前金區民生二路37號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市立圖書館李科永紀念圖書館', `latitude`=25.0421407, `longitude`=121.5198716, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914226b32408680beca8', '2025青春美展  即食島嶼－鳳新高級中學第29屆美術班畢業美展', '每個人都如同獨特的島嶼，看似孤立，卻能透過藝術相互連結。\r\n創作就像一場心靈具象化的淬煉，將我們的情感、思想與記憶，濃縮為驚艷又可即時品味的藝術作品。每件作品都像是一道獨特的即食料理，不需贅述，便能體會創作者的心境與思緒流動。\r\n在「即食島嶼」中，每件作品蘊含的情感彼此交織，創造出微妙的共鳴與連結，期待能給予觀者登臨佇足的心靈歸屬。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-05-30 00:00:00', '2025-06-10 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4108', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展  即食島嶼－鳳新高級中學第29屆美術班畢業美展', `description`='每個人都如同獨特的島嶼，看似孤立，卻能透過藝術相互連結。\r\n創作就像一場心靈具象化的淬煉，將我們的情感、思想與記憶，濃縮為驚艷又可即時品味的藝術作品。每件作品都像是一道獨特的即食料理，不需贅述，便能體會創作者的心境與思緒流動。\r\n在「即食島嶼」中，每件作品蘊含的情感彼此交織，創造出微妙的共鳴與連結，期待能給予觀者登臨佇足的心靈歸屬。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-30 00:00:00', `end_date`='2025-06-10 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4108', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914226b32408680becaa', '大峽谷的油彩詩人-威廉霍金斯', '美國油畫家威廉霍金斯 William Hawkins(1962~) 現居亞利桑那州鳳凰城，自1995年開始以油畫紀錄美國西部和墨西哥的土地與天空。 \r\n威廉霍金斯以色彩豐富、風格化的印象派油畫而聞名；他的靈感來自於美國西部和墨西哥西北部的自然景觀：雲朵、樹木、牛、被雨水浸透的田野，都是他喜歡的主題。\r\n', '彼思文化工作室', '桃園市桃園區埔新路12號', '2025-03-07 00:00:00', '2025-03-17 00:00:00', '桃園光影文化館', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大峽谷的油彩詩人-威廉霍金斯', `description`='美國油畫家威廉霍金斯 William Hawkins(1962~) 現居亞利桑那州鳳凰城，自1995年開始以油畫紀錄美國西部和墨西哥的土地與天空。 \r\n威廉霍金斯以色彩豐富、風格化的印象派油畫而聞名；他的靈感來自於美國西部和墨西哥西北部的自然景觀：雲朵、樹木、牛、被雨水浸透的田野，都是他喜歡的主題。\r\n', `organizer`='彼思文化工作室', `address`='桃園市桃園區埔新路12號', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-17 00:00:00', `location`='桃園光影文化館', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914226b32408680becab', '書生朗朗：本土繪本作家說故事', '讓孩子與家長一同走進陶樂蒂的繪本世界，感受故事與色彩的魅力，感受作家溫暖動人的故事、充滿童趣的故事，一起享受畫風繽紛明亮、深受孩子家長喜愛的溫暖童書作家，享受繪本帶來的美好時光。', '國立臺灣圖書館', '高雄市六龜區2鄰光復路70號', '2025-05-04 00:00:00', '2025-05-04 00:00:00', '高雄市立圖書館六龜分館', 23.0063302, 120.6549199, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='書生朗朗：本土繪本作家說故事', `description`='讓孩子與家長一同走進陶樂蒂的繪本世界，感受故事與色彩的魅力，感受作家溫暖動人的故事、充滿童趣的故事，一起享受畫風繽紛明亮、深受孩子家長喜愛的溫暖童書作家，享受繪本帶來的美好時光。', `organizer`='國立臺灣圖書館', `address`='高雄市六龜區2鄰光復路70號', `start_date`='2025-05-04 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='高雄市立圖書館六龜分館', `latitude`=23.0063302, `longitude`=120.6549199, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914226b32408680becac', '【凝視他方的旋轉小路—關於寫實】 Gazing at the Twisting Paths Beyond：Taiwan Realism from 1960’s', '金車文藝中心臺北南京館將於 4 月推出「凝視他方的旋轉小路 － 關於寫實」群展，由亞紀畫廊策劃，集結九位藝術家：詹詠幀、陳昭宏、鄺鉅裁、李吉祥、李秉璈、廖震平、黃海恩、吳逸寒、葉子奇，探討寫實主義如何超越技術性的框架，回歸其作為抵抗與表達的力量。從傳統寫生、文學對抗殖民視角，到數位時代的虛擬真實界線，藝術家們在各自的創作中回應寫實的當代意義，試圖重構寫實主義的多重面向。\r\n\r\n展演者︰詹詠幀、陳昭宏、鄺鉅裁 李吉祥、李秉璈、廖震平 黃海恩、吳逸寒、葉子奇\r\n\r\n', '亞紀畫廊', '臺北市中山區', '2025-04-08 00:00:00', '2025-05-18 00:00:00', '中山區（臺北市）=', 25.06969917, 121.5381597, '無資料', 'https://www.kingcarart.org.tw/exhibitions-detail/222', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【凝視他方的旋轉小路—關於寫實】 Gazing at the Twisting Paths Beyond：Taiwan Realism from 1960’s', `description`='金車文藝中心臺北南京館將於 4 月推出「凝視他方的旋轉小路 － 關於寫實」群展，由亞紀畫廊策劃，集結九位藝術家：詹詠幀、陳昭宏、鄺鉅裁、李吉祥、李秉璈、廖震平、黃海恩、吳逸寒、葉子奇，探討寫實主義如何超越技術性的框架，回歸其作為抵抗與表達的力量。從傳統寫生、文學對抗殖民視角，到數位時代的虛擬真實界線，藝術家們在各自的創作中回應寫實的當代意義，試圖重構寫實主義的多重面向。\r\n\r\n展演者︰詹詠幀、陳昭宏、鄺鉅裁 李吉祥、李秉璈、廖震平 黃海恩、吳逸寒、葉子奇\r\n\r\n', `organizer`='亞紀畫廊', `address`='臺北市中山區', `start_date`='2025-04-08 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='中山區（臺北市）=', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='https://www.kingcarart.org.tw/exhibitions-detail/222', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914226b32408680becae', '苗栗縣蟠桃國小113級音樂暨舞蹈成果發表會-童韻飛揚・舞動樂章', '兒童樂隊將帶來多首動人的樂曲，包含各式兒童樂器的獨奏與合奏，讓悠揚的旋律在空中流轉，展現孩子們這一年來的努力與成長。\r\n舞蹈社則將帶來精彩的現代流行舞蹈，展現熱情奔放的舞姿與青春洋溢的活力，讓現場觀眾一同感受音樂與舞蹈的魅力。\r\n這場發表會不僅是孩子們的舞台，更是他們夢想閃耀的時刻！每一個音符、每一個舞步，都是孩子們的夢想在舞台上閃耀，都是他們努力與成長的見證。這不僅是一場成果發表，更是一場視覺與聽覺的雙重盛宴，一次對藝術、夢想與童年美好的禮讚！讓我們一起見證他們的努力與成長，感受音樂與舞蹈帶來的歡樂與感動！\r\n演出曲目：精選自古典及流行樂曲\r\n指導老師：吳龍翔老師、邢瑞蘭老師、廖苡均老師\r\n演出人員：蟠桃國小兒童樂隊暨舞蹈社\r\n入場方式：索票，5/19(一)起，請洽苗北服務台或蟠桃國小么老師037-685410#15，每人限索2張。', '苗栗縣頭份市蟠桃國民小學', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-05-29 00:00:00', '2025-05-29 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗栗縣蟠桃國小113級音樂暨舞蹈成果發表會-童韻飛揚・舞動樂章', `description`='兒童樂隊將帶來多首動人的樂曲，包含各式兒童樂器的獨奏與合奏，讓悠揚的旋律在空中流轉，展現孩子們這一年來的努力與成長。\r\n舞蹈社則將帶來精彩的現代流行舞蹈，展現熱情奔放的舞姿與青春洋溢的活力，讓現場觀眾一同感受音樂與舞蹈的魅力。\r\n這場發表會不僅是孩子們的舞台，更是他們夢想閃耀的時刻！每一個音符、每一個舞步，都是孩子們的夢想在舞台上閃耀，都是他們努力與成長的見證。這不僅是一場成果發表，更是一場視覺與聽覺的雙重盛宴，一次對藝術、夢想與童年美好的禮讚！讓我們一起見證他們的努力與成長，感受音樂與舞蹈帶來的歡樂與感動！\r\n演出曲目：精選自古典及流行樂曲\r\n指導老師：吳龍翔老師、邢瑞蘭老師、廖苡均老師\r\n演出人員：蟠桃國小兒童樂隊暨舞蹈社\r\n入場方式：索票，5/19(一)起，請洽苗北服務台或蟠桃國小么老師037-685410#15，每人限索2張。', `organizer`='苗栗縣頭份市蟠桃國民小學', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-05-29 00:00:00', `end_date`='2025-05-29 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becaf', '【ESO大師精選】時代狂想——梵志登、周善祥與ESO', '當演出足跡遍及柏林愛樂廳、維也納金色大廳、阿姆斯特丹皇家音樂廳、卡內基音樂廳等世界級舞\r\n台的驚艷奇才周善祥，與由指揮大師梵志登所帶領的長榮交響樂團相遇，必將激盪出拉赫瑪尼諾夫\r\n《帕格尼尼主題狂想曲》的24 種繽紛色彩！當電影《似曾相識》的浪漫情懷餘音繞樑之際，蕭斯\r\n塔科維契第五號交響曲為我們揭開時代的荒謬與個人的掙扎。細細品味作曲家在蘇聯大清洗的陰\r\n霾中，面對官方譴責後，究竟是以筆下的壯闊篇章熱烈歌頌共產政權，抑或暗藏對獨裁者的嘲諷與\r\n批判。\r\n演出曲目\r\n1. 莫札特：歌劇《唐．喬凡尼》序曲\r\nMozart: Overture to Don Giovanni\r\n2. 拉赫瑪尼諾夫：《帕格尼尼主題狂想曲》\r\nRachmaninoff: Rhapsody on a Theme of Paganini, Op. 43\r\n3. 蕭斯塔科維契：D 小調第五號交響曲\r\nShostakovich: Symphony No. 5 in D minor, Op. 47', '長榮交響樂團', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-05-31 00:00:00', '2025-05-31 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '票價+400;票價+700;票價+1000;票價+1200;票價+1500', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【ESO大師精選】時代狂想——梵志登、周善祥與ESO', `description`='當演出足跡遍及柏林愛樂廳、維也納金色大廳、阿姆斯特丹皇家音樂廳、卡內基音樂廳等世界級舞\r\n台的驚艷奇才周善祥，與由指揮大師梵志登所帶領的長榮交響樂團相遇，必將激盪出拉赫瑪尼諾夫\r\n《帕格尼尼主題狂想曲》的24 種繽紛色彩！當電影《似曾相識》的浪漫情懷餘音繞樑之際，蕭斯\r\n塔科維契第五號交響曲為我們揭開時代的荒謬與個人的掙扎。細細品味作曲家在蘇聯大清洗的陰\r\n霾中，面對官方譴責後，究竟是以筆下的壯闊篇章熱烈歌頌共產政權，抑或暗藏對獨裁者的嘲諷與\r\n批判。\r\n演出曲目\r\n1. 莫札特：歌劇《唐．喬凡尼》序曲\r\nMozart: Overture to Don Giovanni\r\n2. 拉赫瑪尼諾夫：《帕格尼尼主題狂想曲》\r\nRachmaninoff: Rhapsody on a Theme of Paganini, Op. 43\r\n3. 蕭斯塔科維契：D 小調第五號交響曲\r\nShostakovich: Symphony No. 5 in D minor, Op. 47', `organizer`='長榮交響樂團', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-05-31 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='票價+400;票價+700;票價+1000;票價+1200;票價+1500', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becb3', '音閱室內樂古典音樂會系列《樂色迷人》', '本場音樂會帶來的曲目風格多元，上半場除了有取自神劇《索羅門》的名曲「席巴女王的進場」，還有源自於西班牙風格的瘋狂舞曲「拉佛利亞」和以文藝復興及巴洛克時期的古調改編的傳統民謠名曲。\r\n下半場的曲目以童趣為主軸，演出由丹麥作曲家Ludvig Schytte所創作的「兒童組曲」，組曲中改編加入西方文化中的童謠音樂，並加入一些帶有趣味性聲效的樂器，音樂會也將邀請苗栗縣公館國小音樂班的學生一起共同完成演出。除了西方文化的童謠歌曲，另外也將演出由台灣新生代作曲家陳羿婷所創作的作品「童謠狂想」。作曲家將數首台灣童謠加入自身對台灣的情感創作而成，用音樂引領我們找回孩童時期的單純，以及對台灣文化的認同和記憶。', '音閱室內樂', '苗栗縣苗栗市自治路50號', '2025-05-04 00:00:00', '2025-05-04 00:00:00', '苗栗縣政府文化觀光局', 24.565963, 120.8203986, '票價+150;票價+250;票價+300', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='音閱室內樂古典音樂會系列《樂色迷人》', `description`='本場音樂會帶來的曲目風格多元，上半場除了有取自神劇《索羅門》的名曲「席巴女王的進場」，還有源自於西班牙風格的瘋狂舞曲「拉佛利亞」和以文藝復興及巴洛克時期的古調改編的傳統民謠名曲。\r\n下半場的曲目以童趣為主軸，演出由丹麥作曲家Ludvig Schytte所創作的「兒童組曲」，組曲中改編加入西方文化中的童謠音樂，並加入一些帶有趣味性聲效的樂器，音樂會也將邀請苗栗縣公館國小音樂班的學生一起共同完成演出。除了西方文化的童謠歌曲，另外也將演出由台灣新生代作曲家陳羿婷所創作的作品「童謠狂想」。作曲家將數首台灣童謠加入自身對台灣的情感創作而成，用音樂引領我們找回孩童時期的單純，以及對台灣文化的認同和記憶。', `organizer`='音閱室內樂', `address`='苗栗縣苗栗市自治路50號', `start_date`='2025-05-04 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='苗栗縣政府文化觀光局', `latitude`=24.565963, `longitude`=120.8203986, `ticket_price`='票價+150;票價+250;票價+300', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becb4', '2025青春美展  高雄市中華藝術學校美術科-「春藝啟程-繪未來」', '「春藝啟程-繪未來」展覽匯聚了美術科的創意精華，展出學生們的藝術探索與多元表現。展品涵蓋金工、繪畫、動畫、專題製作與陶藝等多樣形式，展現當代學生對未來的構想與藝術的無限可能。金屬的冷冽與繪畫的柔美、動畫的動感與陶藝的質感在此交織融合，呈現出一個跨領域的藝術盛宴，啟發觀者對藝術未來的無限想像。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-04-04 00:00:00', '2025-04-15 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4097', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展  高雄市中華藝術學校美術科-「春藝啟程-繪未來」', `description`='「春藝啟程-繪未來」展覽匯聚了美術科的創意精華，展出學生們的藝術探索與多元表現。展品涵蓋金工、繪畫、動畫、專題製作與陶藝等多樣形式，展現當代學生對未來的構想與藝術的無限可能。金屬的冷冽與繪畫的柔美、動畫的動感與陶藝的質感在此交織融合，呈現出一個跨領域的藝術盛宴，啟發觀者對藝術未來的無限想像。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-04-04 00:00:00', `end_date`='2025-04-15 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4097', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becb5', '2025青春美展  台南應用科技大學美術系114級畢業展《驀驀蒼蒼》', '《驀驀蒼蒼》《When The Light Shimmer》「驀」（suddenly）為「忽然、突然」之意，是忽明忽暗，曦光反射映在瞳孔的蒼鬱草木虆虆。本展透過藝術作品的展示，以「驀」與「蒼」來傳達「創作路上不一定光明，或許跌跌撞撞、或許絢麗奪目，但一定會有人為此紀錄。如徜徉在蒼鬱森林裡，讓人為之心曠神怡的心境。 作品傳達「與生命相互映照」不僅是藝術家的個人表達，也是與觀眾心靈的共鳴。藝術的創造源於生命的經驗，而藝術家的生命與作品相互交融，形成一種獨特的存在。人與其處境交相互動的過程中所引發之覺知與思考。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-05-02 00:00:00', '2025-05-13 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4107', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展  台南應用科技大學美術系114級畢業展《驀驀蒼蒼》', `description`='《驀驀蒼蒼》《When The Light Shimmer》「驀」（suddenly）為「忽然、突然」之意，是忽明忽暗，曦光反射映在瞳孔的蒼鬱草木虆虆。本展透過藝術作品的展示，以「驀」與「蒼」來傳達「創作路上不一定光明，或許跌跌撞撞、或許絢麗奪目，但一定會有人為此紀錄。如徜徉在蒼鬱森林裡，讓人為之心曠神怡的心境。 作品傳達「與生命相互映照」不僅是藝術家的個人表達，也是與觀眾心靈的共鳴。藝術的創造源於生命的經驗，而藝術家的生命與作品相互交融，形成一種獨特的存在。人與其處境交相互動的過程中所引發之覺知與思考。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-02 00:00:00', `end_date`='2025-05-13 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4107', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becb6', '2025青春美展 台南應用科技大學時尚設計系《RE;重啟》', '台南應用科技大學時尚設計系114級，總共 47位即將畢業的學生用創意與實力打造的近150件時尚作品。以袋包、鞋靴、帽飾及各式時尚配件為主題，呈現學生們三年多來的學習成果，結合課程中的創造力訓練、材質設計應用、3D數位打樣、以及品牌行銷實務等專業技術，展現對時尚設計的獨到見解與豐富表現。\r\n此展覽主題為「RE;重啟」，將分為三類小主題，分別是；\r\n初始Initial\r\n覺醒Awakening\r\n綻放Bloom\r\n每件作品展現了學生的對專業的理解和創新思維，表達他們對未來的期待與無限可能。\r\n', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-05-30 00:00:00', '2025-06-10 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4105', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展 台南應用科技大學時尚設計系《RE;重啟》', `description`='台南應用科技大學時尚設計系114級，總共 47位即將畢業的學生用創意與實力打造的近150件時尚作品。以袋包、鞋靴、帽飾及各式時尚配件為主題，呈現學生們三年多來的學習成果，結合課程中的創造力訓練、材質設計應用、3D數位打樣、以及品牌行銷實務等專業技術，展現對時尚設計的獨到見解與豐富表現。\r\n此展覽主題為「RE;重啟」，將分為三類小主題，分別是；\r\n初始Initial\r\n覺醒Awakening\r\n綻放Bloom\r\n每件作品展現了學生的對專業的理解和創新思維，表達他們對未來的期待與無限可能。\r\n', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-30 00:00:00', `end_date`='2025-06-10 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4105', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becb8', '昇平五洲園「豬八戒娶親」', '來自雲林縣西螺鎮的布袋戲團【昇平五洲園】，由老團長林宗男先生師承黃海岱大師的五洲園門派，取名昇平五洲園，亦即象徵「四海昇平，五洲揚名」，現已傳承第二代，由林政興團長帶領下，以傳統與創新結合為主旨，多元發展布袋戲，並落實文化與技藝傳承。\r\n該團連續七年入選國家文化藝術基金會年度獎助專案團隊，多次參加雲林國際偶戲節金掌獎比賽榮獲佳績，昇平五洲園近年來在各地方文化場館嶄露頭角，致力推廣布袋戲演出。團長林政興於2022年榮獲傳藝金曲獎「最佳偶戲主演獎」殊榮，其五音分明之口白特色、詮釋台語詩詞韻味之技藝受到高度肯定。亦鑽研戲台、佈景的創作及各種聲光效果的創新，並能針對演出場所打造適合觀眾年齡的傳統戲及兒童劇，期許觀眾都能收穫滿載、回味無窮。林政興以「立足傳統，放眼創新」作為經營理念，更為傳統布袋戲藝術保存、活化與發揚創新技術，提升大眾對民俗技藝之重視而努力。\r\n本次演出劇目《豬八戒娶親》是一齣老少咸宜的親子好戲，演出題材引自家喻戶曉的《西遊記》著名橋段，使得角色一登場便能與現場觀眾產生共鳴，透過靈活靈現的戲偶、豐富的肢體語言，使唐三藏、豬八戒、孫悟空...等角色，彷彿從故事書中躍然而出，想像力就是超能力，期盼經由布袋戲結合現代敘事手法呈現出多樣化的藝術演出，拓展觀眾更廣闊的想像力。', '無資料', '苗栗縣公館鄉', '2025-05-01 00:00:00', '2025-05-01 00:00:00', '公館鄉（苗栗縣）=', 24.50249686, 120.8505904, '無資料', 'https://www.mlc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='昇平五洲園「豬八戒娶親」', `description`='來自雲林縣西螺鎮的布袋戲團【昇平五洲園】，由老團長林宗男先生師承黃海岱大師的五洲園門派，取名昇平五洲園，亦即象徵「四海昇平，五洲揚名」，現已傳承第二代，由林政興團長帶領下，以傳統與創新結合為主旨，多元發展布袋戲，並落實文化與技藝傳承。\r\n該團連續七年入選國家文化藝術基金會年度獎助專案團隊，多次參加雲林國際偶戲節金掌獎比賽榮獲佳績，昇平五洲園近年來在各地方文化場館嶄露頭角，致力推廣布袋戲演出。團長林政興於2022年榮獲傳藝金曲獎「最佳偶戲主演獎」殊榮，其五音分明之口白特色、詮釋台語詩詞韻味之技藝受到高度肯定。亦鑽研戲台、佈景的創作及各種聲光效果的創新，並能針對演出場所打造適合觀眾年齡的傳統戲及兒童劇，期許觀眾都能收穫滿載、回味無窮。林政興以「立足傳統，放眼創新」作為經營理念，更為傳統布袋戲藝術保存、活化與發揚創新技術，提升大眾對民俗技藝之重視而努力。\r\n本次演出劇目《豬八戒娶親》是一齣老少咸宜的親子好戲，演出題材引自家喻戶曉的《西遊記》著名橋段，使得角色一登場便能與現場觀眾產生共鳴，透過靈活靈現的戲偶、豐富的肢體語言，使唐三藏、豬八戒、孫悟空...等角色，彷彿從故事書中躍然而出，想像力就是超能力，期盼經由布袋戲結合現代敘事手法呈現出多樣化的藝術演出，拓展觀眾更廣闊的想像力。', `organizer`='無資料', `address`='苗栗縣公館鄉', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-01 00:00:00', `location`='公館鄉（苗栗縣）=', `latitude`=24.50249686, `longitude`=120.8505904, `ticket_price`='無資料', `source_url`='https://www.mlc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becb9', '卓蘭鎮立圖書館說故事活動（114年3月）', '故事：大象忘忘\r\n手作：紙杯科學勞作\r\n參加人數：大班以上，15人。\r\n報名請至卓蘭圖臉書留言，或掃描QRcode\r\n', '苗栗縣卓蘭鎮立圖書館', '苗栗縣卓蘭鎮中山路125-1號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '苗栗縣卓蘭鎮立圖書館', 24.3129076, 120.8245351, '無資料', 'https://www.facebook.com/groups/1065739886784498', '[]') ON DUPLICATE KEY UPDATE `activity_name`='卓蘭鎮立圖書館說故事活動（114年3月）', `description`='故事：大象忘忘\r\n手作：紙杯科學勞作\r\n參加人數：大班以上，15人。\r\n報名請至卓蘭圖臉書留言，或掃描QRcode\r\n', `organizer`='苗栗縣卓蘭鎮立圖書館', `address`='苗栗縣卓蘭鎮中山路125-1號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='苗栗縣卓蘭鎮立圖書館', `latitude`=24.3129076, `longitude`=120.8245351, `ticket_price`='無資料', `source_url`='https://www.facebook.com/groups/1065739886784498', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becba', '苗栗縣行動托育資源車-三月山區活動：星球故事屋-好餓的毛毛蟲', '活動內容：故事屋、音樂律動、小手DIY。\r\n歡迎0-3歲（未滿4歲）親子家庭報名參與\r\n線上報名 https://reurl.cc/K8KW0g\r\n\r\n', '苗栗縣政府', '苗栗縣卓蘭鎮中山路125-1號', '2025-03-21 00:00:00', '2025-03-21 00:00:00', '苗栗縣卓蘭鎮立圖書館', 24.3129076, 120.8245351, '無資料', 'https://www.facebook.com/groups/1065739886784498', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗栗縣行動托育資源車-三月山區活動：星球故事屋-好餓的毛毛蟲', `description`='活動內容：故事屋、音樂律動、小手DIY。\r\n歡迎0-3歲（未滿4歲）親子家庭報名參與\r\n線上報名 https://reurl.cc/K8KW0g\r\n\r\n', `organizer`='苗栗縣政府', `address`='苗栗縣卓蘭鎮中山路125-1號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='苗栗縣卓蘭鎮立圖書館', `latitude`=24.3129076, `longitude`=120.8245351, `ticket_price`='無資料', `source_url`='https://www.facebook.com/groups/1065739886784498', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becbb', '小空間大智慧：居家收納主題書展', '今天是傳統二十四節氣中的第三個節氣——「驚蟄」。顧名思義，就是上天以打雷方式驚醒蟄居萬物的冬眠，表示春天準備報到啦。\r\n冬眠的萬物即將甦醒，亂亂的家裡和書桌是不是該整理起來了。《不丟東西的整理術》、《令人怦然心動的3日奇蹟整理術》、《沒時間才更要學的理家術》、《文具整理術》、《美感收納術》......還在尋找整理收納的靈感嗎？讓圖書館提供一些靈活實用的idea給您。【小空間大智慧：居家收納主題書展】歡迎借閱。', '苗栗縣頭份市公所', '苗栗縣頭份市7鄰中華路1082號', '2025-03-03 00:00:00', '2025-03-31 00:00:00', '苗栗縣頭份市立圖書館', 24.67628243, 120.9189437, '無資料', 'https://www.facebook.com/toufenlib', '[]') ON DUPLICATE KEY UPDATE `activity_name`='小空間大智慧：居家收納主題書展', `description`='今天是傳統二十四節氣中的第三個節氣——「驚蟄」。顧名思義，就是上天以打雷方式驚醒蟄居萬物的冬眠，表示春天準備報到啦。\r\n冬眠的萬物即將甦醒，亂亂的家裡和書桌是不是該整理起來了。《不丟東西的整理術》、《令人怦然心動的3日奇蹟整理術》、《沒時間才更要學的理家術》、《文具整理術》、《美感收納術》......還在尋找整理收納的靈感嗎？讓圖書館提供一些靈活實用的idea給您。【小空間大智慧：居家收納主題書展】歡迎借閱。', `organizer`='苗栗縣頭份市公所', `address`='苗栗縣頭份市7鄰中華路1082號', `start_date`='2025-03-03 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='苗栗縣頭份市立圖書館', `latitude`=24.67628243, `longitude`=120.9189437, `ticket_price`='無資料', `source_url`='https://www.facebook.com/toufenlib', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becbd', '紙風車劇團【紙風車幻想曲】', '與竹山孩子相約每年的兒童節相見\r\n今年，要帶著《紙風車幻想曲》出發​\r\n老朋友唐吉軻德與雙頭龍之戰\r\n喚起大家「相信自己，堅持到底」的心​\r\n連假在家可以睡到太陽曬屁股\r\n但平常上學，究竟誰最愛賴床的〈起床號〉​\r\n臺灣的後山有一位國外來的老爺爺\r\n在臺東種下了一粒麥子，被稱為〈後山天使〉​\r\n想在山裡奔跑的賽狗們與美麗黑光\r\n陪竹山的孩子們盡情狂歡，記得要來看喔！​', '南投縣竹山鎮公所', '南投縣竹山鎮公所路100號', '2025-04-04 00:00:00', '2025-04-04 00:00:00', '南投縣竹山鎮公所', 23.7578635, 120.6716995, '無資料', 'https://www.facebook.com/paperwindmilltheatre', '[]') ON DUPLICATE KEY UPDATE `activity_name`='紙風車劇團【紙風車幻想曲】', `description`='與竹山孩子相約每年的兒童節相見\r\n今年，要帶著《紙風車幻想曲》出發​\r\n老朋友唐吉軻德與雙頭龍之戰\r\n喚起大家「相信自己，堅持到底」的心​\r\n連假在家可以睡到太陽曬屁股\r\n但平常上學，究竟誰最愛賴床的〈起床號〉​\r\n臺灣的後山有一位國外來的老爺爺\r\n在臺東種下了一粒麥子，被稱為〈後山天使〉​\r\n想在山裡奔跑的賽狗們與美麗黑光\r\n陪竹山的孩子們盡情狂歡，記得要來看喔！​', `organizer`='南投縣竹山鎮公所', `address`='南投縣竹山鎮公所路100號', `start_date`='2025-04-04 00:00:00', `end_date`='2025-04-04 00:00:00', `location`='南投縣竹山鎮公所', `latitude`=23.7578635, `longitude`=120.6716995, `ticket_price`='無資料', `source_url`='https://www.facebook.com/paperwindmilltheatre', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becbe', '2025竹山『小鎮躍動』藝文表演：肆月樂團', '每週六「小鎮躍動」由駐唱歌手、樂團、魔術、泡泡秀…等，來自不同團體帶來的各類精彩演出，歡迎鄉親們來菸葉館欣賞表演。\r\n如遇天候不佳，主辦單位有取消活動的權利。', '南投縣竹山鎮公所', '南投縣竹山鎮', '2025-03-15 00:00:00', '2025-03-15 00:00:00', '竹山鎮（南投縣）=', 23.69805518, 120.7100797, '無資料', 'https://www.facebook.com/JhuShan', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025竹山『小鎮躍動』藝文表演：肆月樂團', `description`='每週六「小鎮躍動」由駐唱歌手、樂團、魔術、泡泡秀…等，來自不同團體帶來的各類精彩演出，歡迎鄉親們來菸葉館欣賞表演。\r\n如遇天候不佳，主辦單位有取消活動的權利。', `organizer`='南投縣竹山鎮公所', `address`='南投縣竹山鎮', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-15 00:00:00', `location`='竹山鎮（南投縣）=', `latitude`=23.69805518, `longitude`=120.7100797, `ticket_price`='無資料', `source_url`='https://www.facebook.com/JhuShan', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becbf', '埔里鎮立圖書館114年SDGs聯合國永續目標閱讀推廣：繪本導讀《不平凡的職業》＆DIY活動（小磚疊疊樂）', '3月SDGs8公平就業繪本導讀&DIY活動\r\n活動內容：繪本導讀《不平凡的職業》、DIY活動（小磚疊疊樂）\r\n報名對象：限小一以上兒童參加，每場限20組，額滿為止。\r\n報名資格：單次借閱30本書(限用兒童卡)，即可至圖書館一樓櫃台報名。\r\n報名方式：即日起額滿為止。\r\n報名費用：免費。', '南投縣埔里鎮公所', '南投縣埔里鎮六合路178號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '南投縣埔里鎮立圖書館', 23.9702357, 120.9713659, '無資料', 'https://www.facebook.com/pulilibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='埔里鎮立圖書館114年SDGs聯合國永續目標閱讀推廣：繪本導讀《不平凡的職業》＆DIY活動（小磚疊疊樂）', `description`='3月SDGs8公平就業繪本導讀&DIY活動\r\n活動內容：繪本導讀《不平凡的職業》、DIY活動（小磚疊疊樂）\r\n報名對象：限小一以上兒童參加，每場限20組，額滿為止。\r\n報名資格：單次借閱30本書(限用兒童卡)，即可至圖書館一樓櫃台報名。\r\n報名方式：即日起額滿為止。\r\n報名費用：免費。', `organizer`='南投縣埔里鎮公所', `address`='南投縣埔里鎮六合路178號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='南投縣埔里鎮立圖書館', `latitude`=23.9702357, `longitude`=120.9713659, `ticket_price`='無資料', `source_url`='https://www.facebook.com/pulilibrary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becc0', '113-1期「熊愛閱讀」說情畫意活動縣長獎作品展', '南投縣政府文化局與18度C文化基金會合作辦理「熊愛閱讀」閱讀護照計畫，其中學生以8開圖畫紙作畫並書寫心得的「『說』情『畫』意」活動，係由各校學生完成項目一「閱讀集點趣」活動之基本閱讀冊數門檻後，由各校老師認證資格後方可參加。學生以8開圖畫紙作畫並書寫心得，鼓勵學生藉由閱讀發揮想像力，進而獨立創作，參與圖、文閱讀分享活動，倡導閱讀風氣，增進學生寫作思考能力，歡迎大家一起到圖書館欣賞獲獎學生的創作心得！\r\n113-1期「熊愛閱讀」縣長獎選出心得達人共計36位，歡迎大家一起到圖書館欣賞獲獎學生的創作心得！', '南投縣政府文化局', '南投縣集集鎮育才街166號', '2025-04-17 00:00:00', '2025-05-29 00:00:00', '集集鎮文化服務所（圖書館）', 23.828033, 120.788368, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='113-1期「熊愛閱讀」說情畫意活動縣長獎作品展', `description`='南投縣政府文化局與18度C文化基金會合作辦理「熊愛閱讀」閱讀護照計畫，其中學生以8開圖畫紙作畫並書寫心得的「『說』情『畫』意」活動，係由各校學生完成項目一「閱讀集點趣」活動之基本閱讀冊數門檻後，由各校老師認證資格後方可參加。學生以8開圖畫紙作畫並書寫心得，鼓勵學生藉由閱讀發揮想像力，進而獨立創作，參與圖、文閱讀分享活動，倡導閱讀風氣，增進學生寫作思考能力，歡迎大家一起到圖書館欣賞獲獎學生的創作心得！\r\n113-1期「熊愛閱讀」縣長獎選出心得達人共計36位，歡迎大家一起到圖書館欣賞獲獎學生的創作心得！', `organizer`='南投縣政府文化局', `address`='南投縣集集鎮育才街166號', `start_date`='2025-04-17 00:00:00', `end_date`='2025-05-29 00:00:00', `location`='集集鎮文化服務所（圖書館）', `latitude`=23.828033, `longitude`=120.788368, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914426b32408680becc2', '天上人間：古典與流行的跨界之夜 女高音謝淑文獨唱會', '在這個令人心醉神迷的夜晚，我們將音樂的翅膀延伸至天上人間的境界。這不僅僅是一場音樂會，更是一場靈感的邂逅，一次跨越時空的旅程。\r\n\r\n從古典音樂的清新氣息到中文流行音樂的激情，天上人間將展現出多元且豐富的音樂風貌。古典樂器與流行音樂相互融合，讓你身臨其境地感受到音樂的奇妙魅力。\r\n\r\n謝淑文，一生致力於跨界歌唱研究，這次為觀眾帶來一場融合古典與流行的音樂盛宴。\r\n\r\n本次演出與古典音樂藝術家們合作，融入跨界演奏，不僅有古典藝術歌曲的純淨唱腔，還有現代流行的抒情旋律。無論你是古典樂迷還是流行音樂愛好者，這裡都能滿足你對音樂的所有想象，享受一場天上人間的奇妙饗宴。\r\n\r\n【演出曲目】\r\n\r\n \r\n\r\n人間\r\n\r\n1.中文流行歌曲集錦：京戲戲歌與流行音樂的結合\r\n\r\n編曲：李哲音\r\n\r\n2.中文流行歌曲串燒\r\n\r\n編曲：李哲音\r\n\r\n3.孟姜女\r\n\r\n曲：中國民謠\r\n\r\n詞：劉麟\r\n\r\n編曲：李哲音\r\n\r\n4.Journey to the past (from Anastasia)\r\n\r\n詞：Lynn Ahrens 曲：Steven Flaherty\r\n\r\n5.A Dream is a wish your heart makes\r\n\r\n詞：Al Hoffman/ David Pack 曲：Jerry Livingston / Mack David\r\n\r\n6.Amaziing Grace\r\n\r\n詞：John Newton 曲: Tradition\r\n\r\n編曲：李哲音\r\n\r\n7.La Califfa\r\n\r\n詞：Alberto Bevilacqua 曲：Ennio Morricone 編曲：李哲音\r\n\r\n \r\n\r\n天上\r\n\r\n8.Auf Flügeln des Gesanges, Op. 34, No. 2\r\n\r\n詞：Christian Johann Heinrich Heine 曲：F. Mendelssohn\r\n\r\n9.Si mes vers avaient des ailes\r\n\r\n詞：Victor Hugo 曲：Reynaldo Hahn\r\n\r\n10.Vocalise, Op.34 No.14\r\n\r\n曲：S.Rachmaninoff 編曲：李哲音\r\n\r\n11.Cinema paradiso\r\n\r\n詞：Alessio De Sensi 曲： Andrea Morricone / Ennio Morricone 編曲：李哲音\r\n\r\n12.Gabriel’s oboe (whispers in a dream) 詞：Hayley Westenra 曲：Ennio Morricone 編曲：李哲音\r\n\r\n13.Bach: Cantata BWV 147: Jesu, Joy of Man’s Desiring\r\n\r\n曲：Johann Sebastian Bach', '大地音樂精靈樂團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-05-11 00:00:00', '2025-05-11 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500;--+1000', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='天上人間：古典與流行的跨界之夜 女高音謝淑文獨唱會', `description`='在這個令人心醉神迷的夜晚，我們將音樂的翅膀延伸至天上人間的境界。這不僅僅是一場音樂會，更是一場靈感的邂逅，一次跨越時空的旅程。\r\n\r\n從古典音樂的清新氣息到中文流行音樂的激情，天上人間將展現出多元且豐富的音樂風貌。古典樂器與流行音樂相互融合，讓你身臨其境地感受到音樂的奇妙魅力。\r\n\r\n謝淑文，一生致力於跨界歌唱研究，這次為觀眾帶來一場融合古典與流行的音樂盛宴。\r\n\r\n本次演出與古典音樂藝術家們合作，融入跨界演奏，不僅有古典藝術歌曲的純淨唱腔，還有現代流行的抒情旋律。無論你是古典樂迷還是流行音樂愛好者，這裡都能滿足你對音樂的所有想象，享受一場天上人間的奇妙饗宴。\r\n\r\n【演出曲目】\r\n\r\n \r\n\r\n人間\r\n\r\n1.中文流行歌曲集錦：京戲戲歌與流行音樂的結合\r\n\r\n編曲：李哲音\r\n\r\n2.中文流行歌曲串燒\r\n\r\n編曲：李哲音\r\n\r\n3.孟姜女\r\n\r\n曲：中國民謠\r\n\r\n詞：劉麟\r\n\r\n編曲：李哲音\r\n\r\n4.Journey to the past (from Anastasia)\r\n\r\n詞：Lynn Ahrens 曲：Steven Flaherty\r\n\r\n5.A Dream is a wish your heart makes\r\n\r\n詞：Al Hoffman/ David Pack 曲：Jerry Livingston / Mack David\r\n\r\n6.Amaziing Grace\r\n\r\n詞：John Newton 曲: Tradition\r\n\r\n編曲：李哲音\r\n\r\n7.La Califfa\r\n\r\n詞：Alberto Bevilacqua 曲：Ennio Morricone 編曲：李哲音\r\n\r\n \r\n\r\n天上\r\n\r\n8.Auf Flügeln des Gesanges, Op. 34, No. 2\r\n\r\n詞：Christian Johann Heinrich Heine 曲：F. Mendelssohn\r\n\r\n9.Si mes vers avaient des ailes\r\n\r\n詞：Victor Hugo 曲：Reynaldo Hahn\r\n\r\n10.Vocalise, Op.34 No.14\r\n\r\n曲：S.Rachmaninoff 編曲：李哲音\r\n\r\n11.Cinema paradiso\r\n\r\n詞：Alessio De Sensi 曲： Andrea Morricone / Ennio Morricone 編曲：李哲音\r\n\r\n12.Gabriel’s oboe (whispers in a dream) 詞：Hayley Westenra 曲：Ennio Morricone 編曲：李哲音\r\n\r\n13.Bach: Cantata BWV 147: Jesu, Joy of Man’s Desiring\r\n\r\n曲：Johann Sebastian Bach', `organizer`='大地音樂精靈樂團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-05-11 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500;--+1000', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914426b32408680becc3', '文學力－書寫LÁN臺灣主題展導覽互動活動', '陽荷老師帶領民眾參觀及互動遊戲，需事先報名，電話：049-2221619陳小姐', '南投縣政府文化局', '南投縣南投市中興路669號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '南投縣政府文化局圖書館', 23.9027891, 120.691332, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='文學力－書寫LÁN臺灣主題展導覽互動活動', `description`='陽荷老師帶領民眾參觀及互動遊戲，需事先報名，電話：049-2221619陳小姐', `organizer`='南投縣政府文化局', `address`='南投縣南投市中興路669號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='南投縣政府文化局圖書館', `latitude`=23.9027891, `longitude`=120.691332, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914426b32408680becc4', '2025青春美展 高雄市立鼓山高級中學第24屆美術班畢業成果展  在 再 (Here, Again)', '「在 再」融合了三年來的成長與蛻變。每一件作品都蘊含著「在」的當下空間感知與「再」的時間循環——無論是過去的回憶，還是對未來的憧憬，都在創作中找到了自己的位置。從初入高中時的懵懂，到逐漸成熟的體悟，每一幅畫、每一字句都是這段青春歲月烙印的痕跡。', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-05-30 00:00:00', '2025-06-10 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4110', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展 高雄市立鼓山高級中學第24屆美術班畢業成果展  在 再 (Here, Again)', `description`='「在 再」融合了三年來的成長與蛻變。每一件作品都蘊含著「在」的當下空間感知與「再」的時間循環——無論是過去的回憶，還是對未來的憧憬，都在創作中找到了自己的位置。從初入高中時的懵懂，到逐漸成熟的體悟，每一幅畫、每一字句都是這段青春歲月烙印的痕跡。', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-30 00:00:00', `end_date`='2025-06-10 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4110', `image_url`='[]';
