INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1ee3226b32408680bebcb', '【講座】親密戲不親密?探討演員身心的安全防護', '📜講座介紹: 親密戲該如何拍攝，才能讓演員感到安全與被尊重？隨著2023年臺灣MeToo運動引發關注，親密指導員的專業角色逐漸受到重視。本講座將邀請親密指導員分享他們如何透過細緻的溝通與規範，守護演員的身心界線，並為劇組營造安心的合作氛圍。一起來探索親密戲背後的用心與尊重，為表演帶來更多信任與溫度。\n\n🙋講師:林微弋/演員、親密戲指導員\n\n-----------------------------------------------\n\n📆時間:114年7月20日（日）14:00~16:00\n\n📍地點:中正紀念堂3樓W318教室\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁現場填答問卷憑完成畫面可獲得紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍教室地點指引:教室位於藍色屋頂主堂體內，學員請直接由銅門(玻璃門)進入1樓大廳，利用樓梯或電梯前往3樓W318教室，教室位置詳參下方圖示：\n\n\n\n\n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-07-20 00:00:00', '2025-07-20 00:00:00', 'W318教室', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50744', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【講座】親密戲不親密?探討演員身心的安全防護', `description`='📜講座介紹: 親密戲該如何拍攝，才能讓演員感到安全與被尊重？隨著2023年臺灣MeToo運動引發關注，親密指導員的專業角色逐漸受到重視。本講座將邀請親密指導員分享他們如何透過細緻的溝通與規範，守護演員的身心界線，並為劇組營造安心的合作氛圍。一起來探索親密戲背後的用心與尊重，為表演帶來更多信任與溫度。\n\n🙋講師:林微弋/演員、親密戲指導員\n\n-----------------------------------------------\n\n📆時間:114年7月20日（日）14:00~16:00\n\n📍地點:中正紀念堂3樓W318教室\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁現場填答問卷憑完成畫面可獲得紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍教室地點指引:教室位於藍色屋頂主堂體內，學員請直接由銅門(玻璃門)進入1樓大廳，利用樓梯或電梯前往3樓W318教室，教室位置詳參下方圖示：\n\n\n\n\n\n \n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-07-20 00:00:00', `end_date`='2025-07-20 00:00:00', `location`='W318教室', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50744', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1ee3226b32408680bebcc', '【講座】流浪的公主：魯凱族藝術家安聖惠（峨冷.魯魯安）的夢與編織藝術', '📜講座介紹: 安聖惠出生在屏東的深山裡舊好茶部落。兒時在山上的牧羊時光與在森林嬉戲的情景，成為永恆的回憶。自幼叛逆的公主，長大後，迫不及待離家到都會工作。但後來部落幾次的遷移，遇到颱風洪水與土石流，使得她也失去了家。所幸當她重拾小時候在部落模仿媽媽與女性長輩編織的技藝，編織藝術成為她與部落再次的連結，尋找心靈故鄉的路徑。\n\n🙋講師:許瀞月/臺北市立大學視覺藝術系教授\n\n-----------------------------------------------\n\n📆時間:114年8月10日（日）14:00~16:00\n\n📍地點:中正紀念堂3樓W318教室\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁現場填答問卷憑完成畫面可獲得紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍教室地點指引:教室位於藍色屋頂主堂體內，學員請直接由銅門(玻璃門)進入1樓大廳，利用樓梯或電梯前往3樓W318教室，教室位置詳參下方圖示：\n\n\n\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-08-10 00:00:00', '2025-08-10 00:00:00', 'W318教室', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50745', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【講座】流浪的公主：魯凱族藝術家安聖惠（峨冷.魯魯安）的夢與編織藝術', `description`='📜講座介紹: 安聖惠出生在屏東的深山裡舊好茶部落。兒時在山上的牧羊時光與在森林嬉戲的情景，成為永恆的回憶。自幼叛逆的公主，長大後，迫不及待離家到都會工作。但後來部落幾次的遷移，遇到颱風洪水與土石流，使得她也失去了家。所幸當她重拾小時候在部落模仿媽媽與女性長輩編織的技藝，編織藝術成為她與部落再次的連結，尋找心靈故鄉的路徑。\n\n🙋講師:許瀞月/臺北市立大學視覺藝術系教授\n\n-----------------------------------------------\n\n📆時間:114年8月10日（日）14:00~16:00\n\n📍地點:中正紀念堂3樓W318教室\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁現場填答問卷憑完成畫面可獲得紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍教室地點指引:教室位於藍色屋頂主堂體內，學員請直接由銅門(玻璃門)進入1樓大廳，利用樓梯或電梯前往3樓W318教室，教室位置詳參下方圖示：\n\n\n\n\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-08-10 00:00:00', `end_date`='2025-08-10 00:00:00', `location`='W318教室', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50745', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1ee3326b32408680bebcd', '【講座】鏡頭下的雙面人生：從《雙面曹里歐》看變裝皇后妮妃雅的生命故事', '📜講座介紹: 在舞台上，他是閃耀全場的變裝皇后「妮妃雅」；在日常中，他是充滿矛盾與熱情的曹里歐。短短27分鐘的紀錄片《雙面曹里歐》，導演潘信安以細膩的鏡頭語言捕捉曹里歐的創作能量與生活掙扎，展現了他在藝術與現實間的矛盾與渴望。\n\n🙋講師:潘信安/導演\n\n-----------------------------------------------\n\n📆時間:114年9月28日（日）14:00~16:30\n\n📍地點:中正紀念堂演藝廳\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁現場填答問卷憑完成畫面可獲得紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍地點指引:演藝廳位於藍色屋頂主堂體內，民眾可從愛國東路大孝門牌樓或信義路大忠門牌樓步行進入1樓大廳，演藝廳位置詳參下方圖示：\n\n\n\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-09-28 00:00:00', '2025-09-28 00:00:00', '演藝廳', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50746', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【講座】鏡頭下的雙面人生：從《雙面曹里歐》看變裝皇后妮妃雅的生命故事', `description`='📜講座介紹: 在舞台上，他是閃耀全場的變裝皇后「妮妃雅」；在日常中，他是充滿矛盾與熱情的曹里歐。短短27分鐘的紀錄片《雙面曹里歐》，導演潘信安以細膩的鏡頭語言捕捉曹里歐的創作能量與生活掙扎，展現了他在藝術與現實間的矛盾與渴望。\n\n🙋講師:潘信安/導演\n\n-----------------------------------------------\n\n📆時間:114年9月28日（日）14:00~16:30\n\n📍地點:中正紀念堂演藝廳\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁現場填答問卷憑完成畫面可獲得紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍地點指引:演藝廳位於藍色屋頂主堂體內，民眾可從愛國東路大孝門牌樓或信義路大忠門牌樓步行進入1樓大廳，演藝廳位置詳參下方圖示：\n\n\n\n\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-09-28 00:00:00', `end_date`='2025-09-28 00:00:00', `location`='演藝廳', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50746', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1ee3326b32408680bebce', '【講座】女人專用之髒話：夏宇的女性詩學', '📜講座介紹:「身為女人，我發現我們沒有自己專用的髒話，這是非常令人不滿的。」夏宇在《腹語術》中的這句話，道出了她對語言與性別的深刻思考。她的詩學不僅是語言的實驗場，更是一場性別顛覆的革命。從顛覆愛情想像、戲擬男性中心語言，到呈現女性的多重樣貌，夏宇以獨特的詩語言開創「女性詩學」，挑戰性別規範，為當代詩壇帶來全新視角。\n\n🙋講師:李癸雲/國立清華大學台灣文學所教授兼人社院副院長\n\n-----------------------------------------------\n\n📆時間:114年11月16日（日）14:00~16:00\n\n📍地點:中正紀念堂3樓W318教室\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁現場填答問卷憑完成畫面可獲得紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍教室地點指引:教室位於藍色屋頂主堂體內，學員請直接由銅門(玻璃門)進入1樓大廳，利用樓梯或電梯前往3樓W318教室，教室位置詳參下方圖示：\n\n\n\n\n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-11-16 00:00:00', '2025-11-16 00:00:00', 'W318教室', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50747', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【講座】女人專用之髒話：夏宇的女性詩學', `description`='📜講座介紹:「身為女人，我發現我們沒有自己專用的髒話，這是非常令人不滿的。」夏宇在《腹語術》中的這句話，道出了她對語言與性別的深刻思考。她的詩學不僅是語言的實驗場，更是一場性別顛覆的革命。從顛覆愛情想像、戲擬男性中心語言，到呈現女性的多重樣貌，夏宇以獨特的詩語言開創「女性詩學」，挑戰性別規範，為當代詩壇帶來全新視角。\n\n🙋講師:李癸雲/國立清華大學台灣文學所教授兼人社院副院長\n\n-----------------------------------------------\n\n📆時間:114年11月16日（日）14:00~16:00\n\n📍地點:中正紀念堂3樓W318教室\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁現場填答問卷憑完成畫面可獲得紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍教室地點指引:教室位於藍色屋頂主堂體內，學員請直接由銅門(玻璃門)進入1樓大廳，利用樓梯或電梯前往3樓W318教室，教室位置詳參下方圖示：\n\n\n\n\n\n \n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-11-16 00:00:00', `end_date`='2025-11-16 00:00:00', `location`='W318教室', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50747', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1ee3826b32408680bebd1', '【工作坊】打破性別框架的即興探索─戲劇工作坊', '📜講座介紹: 由帶領者陪著大家進行舞台演員的戲劇表演練習，透過戲劇、肢體或即興練習等體驗活動打破性別定型，藉由一系列的戲劇遊戲探索關於性別、關於身體、關於內在的議題，發掘心中的性別自我，探索身體更多的可能性。\n\n🙋講師:藍貝芝/台灣性別平等教育協會理事\n\n-----------------------------------------------\n\n📆時間:114年6月21日（六）14:00~16:00\n\n📍地點:中正紀念堂E201教室\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁憑問卷填答完成畫面將得到紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍E201教室地點指引(教室位於藍色屋頂主堂體內，詳下方圖示)：\n\n\n	從大忠門(信義路側) 1樓入口：進入堂內後左轉，經過商店及用餐區由樓梯上二樓。\n	從大孝門(愛國東路側) 1樓入口：進入堂內後直行穿過中央通廊，在郵局前右轉，經過商店及用餐區，由樓梯上二樓。\n\n\n\n\n\n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-06-21 00:00:00', '2025-06-21 00:00:00', 'E201教室', 25.0367564, 121.519047, '200', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50743', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【工作坊】打破性別框架的即興探索─戲劇工作坊', `description`='📜講座介紹: 由帶領者陪著大家進行舞台演員的戲劇表演練習，透過戲劇、肢體或即興練習等體驗活動打破性別定型，藉由一系列的戲劇遊戲探索關於性別、關於身體、關於內在的議題，發掘心中的性別自我，探索身體更多的可能性。\n\n🙋講師:藍貝芝/台灣性別平等教育協會理事\n\n-----------------------------------------------\n\n📆時間:114年6月21日（六）14:00~16:00\n\n📍地點:中正紀念堂E201教室\n\n📋公務人員得辦理終身學習時數認證。\n\n🎁憑問卷填答完成畫面將得到紀念品1份🤍🤍🤍\n\n-----------------------------------------------\n\n🌏地理及交通資訊:https://www.cksmh.gov.tw/cp.aspx?n=6027\n\n📍E201教室地點指引(教室位於藍色屋頂主堂體內，詳下方圖示)：\n\n\n	從大忠門(信義路側) 1樓入口：進入堂內後左轉，經過商店及用餐區由樓梯上二樓。\n	從大孝門(愛國東路側) 1樓入口：進入堂內後直行穿過中央通廊，在郵局前右轉，經過商店及用餐區，由樓梯上二樓。\n\n\n\n\n\n\n \n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-06-21 00:00:00', `end_date`='2025-06-21 00:00:00', `location`='E201教室', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='200', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50743', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1ee3f26b32408680bebd3', '「發現第一人巡迴展—臺南站」特展', '考古犬收到委託，協助調查誰是「臺灣史前第一人」？透過時空資料庫搜尋大量考古資料，發現二條線索，分別位於馬祖亮島及臺南科學園區。憑藉生物人類學和考古學的專業知識，考古犬與夥伴逐步探索「第一人」的生活與生命故事。四處探訪收集眾多資料，終於回到臺南的研究室。接下來要進行彙整與分析工作了。特展結合生物類人學與考古學的研究方法，交叉比對研究成果，不僅可以呈現先民豐富多元的生活樣貌，也接露更多土地與人群之間的故事─從過去延伸到現在，並持續向未來延伸發展。\n\n\n主辦單位：文化部文化資產局\n\n執行單位：國立臺灣史前文化博物館\n\n協辦單位：連江縣政府\n\n督導：陳濟民、蔡政良、王忠銘、陳俊男、吳曉雲\n\n策展團隊：林芳儀、林秀嫚、陳晏竺、邊鈺皓\n\n展示協力：曹嘉玲、陳壽延\n\n展品協力：陳慧雯、蘇嘉蓉、洪惠琴、葉長庚、劉宜婷\n\n教育推廣：陳韻如、林弘君、高麗英、陳姵璇、吳宛穗\n\n翻譯：洪瑞恬\n\n執行製作：果匠室內裝修設計有限公司\n\n幻·古環境執行製作：愛迪斯科技股份有限公司\n\n幻·古環境感官擴充執行製作：雷米多媒體科技有限公司\n\n ', '國立臺灣史前文化博物館', '744  臺南市新市區南科三路10號', '2025-03-25 00:00:00', '2025-10-19 00:00:00', '南科考古館2樓特展廳', 23.1002927, 120.2837665, '無資料', 'https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=50158', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「發現第一人巡迴展—臺南站」特展', `description`='考古犬收到委託，協助調查誰是「臺灣史前第一人」？透過時空資料庫搜尋大量考古資料，發現二條線索，分別位於馬祖亮島及臺南科學園區。憑藉生物人類學和考古學的專業知識，考古犬與夥伴逐步探索「第一人」的生活與生命故事。四處探訪收集眾多資料，終於回到臺南的研究室。接下來要進行彙整與分析工作了。特展結合生物類人學與考古學的研究方法，交叉比對研究成果，不僅可以呈現先民豐富多元的生活樣貌，也接露更多土地與人群之間的故事─從過去延伸到現在，並持續向未來延伸發展。\n\n\n主辦單位：文化部文化資產局\n\n執行單位：國立臺灣史前文化博物館\n\n協辦單位：連江縣政府\n\n督導：陳濟民、蔡政良、王忠銘、陳俊男、吳曉雲\n\n策展團隊：林芳儀、林秀嫚、陳晏竺、邊鈺皓\n\n展示協力：曹嘉玲、陳壽延\n\n展品協力：陳慧雯、蘇嘉蓉、洪惠琴、葉長庚、劉宜婷\n\n教育推廣：陳韻如、林弘君、高麗英、陳姵璇、吳宛穗\n\n翻譯：洪瑞恬\n\n執行製作：果匠室內裝修設計有限公司\n\n幻·古環境執行製作：愛迪斯科技股份有限公司\n\n幻·古環境感官擴充執行製作：雷米多媒體科技有限公司\n\n ', `organizer`='國立臺灣史前文化博物館', `address`='744  臺南市新市區南科三路10號', `start_date`='2025-03-25 00:00:00', `end_date`='2025-10-19 00:00:00', `location`='南科考古館2樓特展廳', `latitude`=23.1002927, `longitude`=120.2837665, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=50158', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1ee3f26b32408680bebd4', '聖堂光影-白冷會傅義修士花東現代教堂建築展', '展示緣起於民國 96 年 9 月 9 日天主教白冷外方傳教會傅義修士決定將他的建築設計圖 229 卷 2649 張捐贈給史前館典藏，希望讓文物典藏於更適合的環境，也讓史前館的典藏更加豐富。本展覽挑選傅義修士生平中具代表性的七座天主教教堂，透過模型重製、建築藍圖原稿以及各教堂耆老對教堂與傅修士的口述影像，與社會大眾分享白冷會及傅義修士對花東地區居民與臺灣建築文化的影響。\n\n展覽資訊：\n\n日期丨2025.03.18-2025.10.7\n\n時間丨週二至週日 09:00~17:00(週一休館)\n\n地點丨國立臺灣史前文化博物館康樂本館第二特展室\n\n地址丨臺東縣臺東市豐田里博物館路1號\n\n電話丨089-381166\n\n \n\n \n\n ', '國立臺灣史前文化博物館', '950  臺東縣臺東市博物館路1號', '2025-03-18 00:00:00', '2025-10-07 00:00:00', '康樂本館第二特展室', 22.759955, 121.090697, '無資料', 'https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=50159', '[]') ON DUPLICATE KEY UPDATE `activity_name`='聖堂光影-白冷會傅義修士花東現代教堂建築展', `description`='展示緣起於民國 96 年 9 月 9 日天主教白冷外方傳教會傅義修士決定將他的建築設計圖 229 卷 2649 張捐贈給史前館典藏，希望讓文物典藏於更適合的環境，也讓史前館的典藏更加豐富。本展覽挑選傅義修士生平中具代表性的七座天主教教堂，透過模型重製、建築藍圖原稿以及各教堂耆老對教堂與傅修士的口述影像，與社會大眾分享白冷會及傅義修士對花東地區居民與臺灣建築文化的影響。\n\n展覽資訊：\n\n日期丨2025.03.18-2025.10.7\n\n時間丨週二至週日 09:00~17:00(週一休館)\n\n地點丨國立臺灣史前文化博物館康樂本館第二特展室\n\n地址丨臺東縣臺東市豐田里博物館路1號\n\n電話丨089-381166\n\n \n\n \n\n ', `organizer`='國立臺灣史前文化博物館', `address`='950  臺東縣臺東市博物館路1號', `start_date`='2025-03-18 00:00:00', `end_date`='2025-10-07 00:00:00', `location`='康樂本館第二特展室', `latitude`=22.759955, `longitude`=121.090697, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=50159', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eef926b32408680bebe6', '身體展演：從歷史圖像看身體之謎', '我們擁有身體，但對它卻是既熟悉又陌生。身體不僅難以理解，且隨著時間演進，衍生出許多不同的觀點。其實，除了生物上的構造之外，還有諸多觀看身體的面向。我們的身體與所處的社會關係密切，是由醫療、宗教、文化、法律等社會所共同接受的機制建構而成。身體不僅依據這些機制運作，也受其影響和支配，遵守規則，臣服常規。然而，在此過程中，人對於自身身體，仍然有一定的主宰與運籌能力，並非完全只是追隨社會既有的規則和制度。\r\n展覽精選院藏古籍、器物、繪畫等不同類型文物，藉由這些文物上面的圖像，讓文物自身透過醫療、宗教、文化、法律等不同層面，重新展示與演繹身體。展覽一共分為「身體透視」、「身體操練」、「身體變異」以及「身體規戒」四個單元，探索醫學、法醫、佛道兩教等不同文化脈絡的身體觀，並展現武術、房中、秘戲、舞蹈、體育、導引等身體操練手段。同時，本展覽亦關注人面獸身、獸面人身與殘疾的身體，以及政治、禮教、刑罰對身體的束縛，呈現過去對身體的各種描繪與表述方式。\r\n此次展演邀請觀眾探索古人觀看身體的形式，及其對身體的認識和想像，進而促使我們重新檢視自己究竟是如何思考、看待自身身體，以及各種身體的感知作用。藉此理解身體所表達的意義，解開自身的身體之謎，從而找到人在變化不斷之世界的存在意義。', '國立故宮博物院', '臺北市士林區外雙溪至善路2段221號', '2025-03-13 00:00:00', '2025-08-31 00:00:00', '國立故宮博物院', 25.12546704, 121.5508473, '優惠參觀券+150;團體參觀券+320;普通參觀券+350;至善園+20', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='身體展演：從歷史圖像看身體之謎', `description`='我們擁有身體，但對它卻是既熟悉又陌生。身體不僅難以理解，且隨著時間演進，衍生出許多不同的觀點。其實，除了生物上的構造之外，還有諸多觀看身體的面向。我們的身體與所處的社會關係密切，是由醫療、宗教、文化、法律等社會所共同接受的機制建構而成。身體不僅依據這些機制運作，也受其影響和支配，遵守規則，臣服常規。然而，在此過程中，人對於自身身體，仍然有一定的主宰與運籌能力，並非完全只是追隨社會既有的規則和制度。\r\n展覽精選院藏古籍、器物、繪畫等不同類型文物，藉由這些文物上面的圖像，讓文物自身透過醫療、宗教、文化、法律等不同層面，重新展示與演繹身體。展覽一共分為「身體透視」、「身體操練」、「身體變異」以及「身體規戒」四個單元，探索醫學、法醫、佛道兩教等不同文化脈絡的身體觀，並展現武術、房中、秘戲、舞蹈、體育、導引等身體操練手段。同時，本展覽亦關注人面獸身、獸面人身與殘疾的身體，以及政治、禮教、刑罰對身體的束縛，呈現過去對身體的各種描繪與表述方式。\r\n此次展演邀請觀眾探索古人觀看身體的形式，及其對身體的認識和想像，進而促使我們重新檢視自己究竟是如何思考、看待自身身體，以及各種身體的感知作用。藉此理解身體所表達的意義，解開自身的身體之謎，從而找到人在變化不斷之世界的存在意義。', `organizer`='國立故宮博物院', `address`='臺北市士林區外雙溪至善路2段221號', `start_date`='2025-03-13 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='國立故宮博物院', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='優惠參觀券+150;團體參觀券+320;普通參觀券+350;至善園+20', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefa26b32408680bebf1', '南投縣天然染色技藝研習第一階段', '《南投縣天然染色技藝研習第一階段》開始招生\r\n天然染色技藝研習：以最完整的規劃、嚴謹的教學，理論、色彩、技藝、設計、造形一併學習。歡迎有志於長期投入天然染色的青年朋友們，如果您願意長期投入，歡迎報名參加遴選。本計畫為南投縣政府文化局主辦，文化部文資局補助之為期3年的人才培育計畫。學費由公部門負擔，您只要付出時間、努力與自己使用的材料費，即可進入天然染色園地自在揮灑。\r\n請詳閱遴選辦法及課程表，報名表請至活動網站下載。\r\n基本資格：具有中華民國國籍、男女不限，年齡為20至45歲（含）之間，行動自如，身手矯健者。8-10名。\r\n報名時間：備齊報名資料，於3月31日前寄達-南投市環山路51號 天染工坊 張雅硯收。\r\n洽詢電話：049-2392028 張小姐。', '南投縣政府文化局', '南投縣南投市', '2025-04-19 00:00:00', '2025-10-18 00:00:00', '南投市（南投縣）=', 23.92173537, 120.6787658, '保證金+5000', 'https://tennii.smartweb.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南投縣天然染色技藝研習第一階段', `description`='《南投縣天然染色技藝研習第一階段》開始招生\r\n天然染色技藝研習：以最完整的規劃、嚴謹的教學，理論、色彩、技藝、設計、造形一併學習。歡迎有志於長期投入天然染色的青年朋友們，如果您願意長期投入，歡迎報名參加遴選。本計畫為南投縣政府文化局主辦，文化部文資局補助之為期3年的人才培育計畫。學費由公部門負擔，您只要付出時間、努力與自己使用的材料費，即可進入天然染色園地自在揮灑。\r\n請詳閱遴選辦法及課程表，報名表請至活動網站下載。\r\n基本資格：具有中華民國國籍、男女不限，年齡為20至45歲（含）之間，行動自如，身手矯健者。8-10名。\r\n報名時間：備齊報名資料，於3月31日前寄達-南投市環山路51號 天染工坊 張雅硯收。\r\n洽詢電話：049-2392028 張小姐。', `organizer`='南投縣政府文化局', `address`='南投縣南投市', `start_date`='2025-04-19 00:00:00', `end_date`='2025-10-18 00:00:00', `location`='南投市（南投縣）=', `latitude`=23.92173537, `longitude`=120.6787658, `ticket_price`='保證金+5000', `source_url`='https://tennii.smartweb.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefb26b32408680bebf2', '第十四屆元太道堂盃全國書法比賽', '「第十四屆【元太道堂盃】全國書法比賽」，即日起開始接受投稿報名初賽至6月30日截止，本屆賽事並獲臺北市政府教育局、臺北市文山區民俗委員會指導，共分為國小中低年級組、國小高年級組、國中組、高中組、社會組、長青組等六組，編列第一名總獎金近5萬元，歡迎書法界大朋友、老朋友、小朋友共同響應參賽。\r\n\r\n本賽事自101年辦理迄今已辦理14載，在中國書法學會、中國標準草書學會、財團法人恆安社會福利慈善事業基金會、臺北市文山區萬興里辦公處、文山區老泉里辦公處等機構大力協助推廣下，已有6,692人次參賽民眾至臺北市文山區進行書法創作、參與競賽。相關訊息請上「社團法人臺北市元太慈愛人文推廣協進會」網站 http://www.yuantai.org.tw/index.php 或官方臉書查詢。', '社團法人臺北市元太慈愛人文推廣協進會', '臺北市文山區', '2025-03-12 00:00:00', '2025-08-23 00:00:00', '文山區（臺北市）=', 24.98857934, 121.5736082, '無資料', 'http://www.yuantai.org.tw/index.php', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第十四屆元太道堂盃全國書法比賽', `description`='「第十四屆【元太道堂盃】全國書法比賽」，即日起開始接受投稿報名初賽至6月30日截止，本屆賽事並獲臺北市政府教育局、臺北市文山區民俗委員會指導，共分為國小中低年級組、國小高年級組、國中組、高中組、社會組、長青組等六組，編列第一名總獎金近5萬元，歡迎書法界大朋友、老朋友、小朋友共同響應參賽。\r\n\r\n本賽事自101年辦理迄今已辦理14載，在中國書法學會、中國標準草書學會、財團法人恆安社會福利慈善事業基金會、臺北市文山區萬興里辦公處、文山區老泉里辦公處等機構大力協助推廣下，已有6,692人次參賽民眾至臺北市文山區進行書法創作、參與競賽。相關訊息請上「社團法人臺北市元太慈愛人文推廣協進會」網站 http://www.yuantai.org.tw/index.php 或官方臉書查詢。', `organizer`='社團法人臺北市元太慈愛人文推廣協進會', `address`='臺北市文山區', `start_date`='2025-03-12 00:00:00', `end_date`='2025-08-23 00:00:00', `location`='文山區（臺北市）=', `latitude`=24.98857934, `longitude`=121.5736082, `ticket_price`='無資料', `source_url`='http://www.yuantai.org.tw/index.php', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d1eefb26b32408680bec02', '「策展人陪我看展覽」故宮專題導覽：沈浸故宮3.0：神話(第1場)', '本院北部院區展覽區除常設展外，每季皆陸續熱烈推出器物、書畫、圖書、文獻等多樣特展，各種不同的展示主題藉由策展人的巧思安排與設計規畫，向觀眾呈現了本院典藏文物的豐富精華。爰此，各展覽將各別安排教育活動，由本院策展團隊成員在展場為觀眾導覽，陪伴觀眾一同探索當期展覽！\r\n\r\n活動名稱：「策展人陪我看展覽」導覽活動\r\n活動時間：2025年 (每場次導覽約50-90分鐘)。\r\n活動地點：本院北部院區第一展覽區(正館)陳列室。\r\n活動對象與人數：凡對文化、藝術、故宮文物有興趣的人士(適合高中以上之人士參加)，每場次參加者為10-20人。本活動須至本院線上系統報名，額滿為止(※本活動採單人報名，恕不受理團體報名)。\r\n活動語言：華語。', '國立故宮博物院', '臺北市士林區外雙溪至善路2段221號', '2025-06-20 00:00:00', '2025-06-20 00:00:00', '國立故宮博物院', 25.12546704, 121.5508473, '優惠參觀券+150;團體參觀券+230;普通參觀券+250;至善園+20', 'http://www.npm.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「策展人陪我看展覽」故宮專題導覽：沈浸故宮3.0：神話(第1場)', `description`='本院北部院區展覽區除常設展外，每季皆陸續熱烈推出器物、書畫、圖書、文獻等多樣特展，各種不同的展示主題藉由策展人的巧思安排與設計規畫，向觀眾呈現了本院典藏文物的豐富精華。爰此，各展覽將各別安排教育活動，由本院策展團隊成員在展場為觀眾導覽，陪伴觀眾一同探索當期展覽！\r\n\r\n活動名稱：「策展人陪我看展覽」導覽活動\r\n活動時間：2025年 (每場次導覽約50-90分鐘)。\r\n活動地點：本院北部院區第一展覽區(正館)陳列室。\r\n活動對象與人數：凡對文化、藝術、故宮文物有興趣的人士(適合高中以上之人士參加)，每場次參加者為10-20人。本活動須至本院線上系統報名，額滿為止(※本活動採單人報名，恕不受理團體報名)。\r\n活動語言：華語。', `organizer`='國立故宮博物院', `address`='臺北市士林區外雙溪至善路2段221號', `start_date`='2025-06-20 00:00:00', `end_date`='2025-06-20 00:00:00', `location`='國立故宮博物院', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='優惠參觀券+150;團體參觀券+230;普通參觀券+250;至善園+20', `source_url`='http://www.npm.gov.tw', `image_url`='[]';
