INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29baa26b32408680bec0a', '器：天地人之器特展', '以「容器」為題，打造出天地間奇珍異寶的魔幻珍奇屋。展覽以前衛巨觀視角，從茶器文化延伸至科學、藝術、文學、哲學等領域，由「器」的說文解字出發，帶領民眾透過遠古神話及東方哲學認識器的起源，並蒐羅包括種子、葫蘆、鸚鵡螺、蛋、獸角等的「自然之器」，以及歷代茶器等「人造之器」，還有不可思議的「神奇之器」等，從鬼斧神工到巧奪天工之器一次盡覽，打造前所未見的器之展。', '新北市政府文化局', '新北市坪林區水聳淒坑19-1號', '2025-01-01 00:00:00', '2025-08-31 00:00:00', '新北市坪林茶業博物館', 24.91097073, 121.724223, '門票+80', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='器：天地人之器特展', `description`='以「容器」為題，打造出天地間奇珍異寶的魔幻珍奇屋。展覽以前衛巨觀視角，從茶器文化延伸至科學、藝術、文學、哲學等領域，由「器」的說文解字出發，帶領民眾透過遠古神話及東方哲學認識器的起源，並蒐羅包括種子、葫蘆、鸚鵡螺、蛋、獸角等的「自然之器」，以及歷代茶器等「人造之器」，還有不可思議的「神奇之器」等，從鬼斧神工到巧奪天工之器一次盡覽，打造前所未見的器之展。', `organizer`='新北市政府文化局', `address`='新北市坪林區水聳淒坑19-1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='新北市坪林茶業博物館', `latitude`=24.91097073, `longitude`=121.724223, `ticket_price`='門票+80', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29baa26b32408680bec0b', '茶與王特展', '展出東、西方君王的茶文化故事，在博物館內打造出一座跨時空的皇家宮殿，邀請大家感受帝王茶宴的尊爵體驗！茶在東、西方歷史脈絡中，皆為皇室貴族珍視喜愛的飲品，連君王們也為之著迷，相應而生的飲茶形式、政策制度、品茗器物與藝術創作，不僅反映出皇家思想與品味，更是人類文明中，工藝技術與精緻文化的體現。展覽以恢弘的歷史觀，發掘罕為人知的宮闈茶事祕辛，以新型態數位互動科技展示手法，生動巧妙地詮釋古老宮廷茶文化，打造出沉浸式劇場般的體驗，帶領民眾穿越時空，赴一場皇家的極致茶宴。', '新北市政府文化局', '新北市坪林區水聳淒坑19-1號', '2025-01-01 00:00:00', '2025-11-11 00:00:00', '新北市坪林茶業博物館', 24.91097073, 121.724223, '門票+80', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='茶與王特展', `description`='展出東、西方君王的茶文化故事，在博物館內打造出一座跨時空的皇家宮殿，邀請大家感受帝王茶宴的尊爵體驗！茶在東、西方歷史脈絡中，皆為皇室貴族珍視喜愛的飲品，連君王們也為之著迷，相應而生的飲茶形式、政策制度、品茗器物與藝術創作，不僅反映出皇家思想與品味，更是人類文明中，工藝技術與精緻文化的體現。展覽以恢弘的歷史觀，發掘罕為人知的宮闈茶事祕辛，以新型態數位互動科技展示手法，生動巧妙地詮釋古老宮廷茶文化，打造出沉浸式劇場般的體驗，帶領民眾穿越時空，赴一場皇家的極致茶宴。', `organizer`='新北市政府文化局', `address`='新北市坪林區水聳淒坑19-1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-11-11 00:00:00', `location`='新北市坪林茶業博物館', `latitude`=24.91097073, `longitude`=121.724223, `ticket_price`='門票+80', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29baa26b32408680bec0c', '曉茶塾', '以茶神陸羽的《茶經》內容為基礎，透過五感體驗及互動科技將茶知識轉化為大、小朋友都能輕鬆理解的趣味內容，民眾可以從採茶、炒茶、揉捻、烘焙，一直到設計出自己專屬的茶葉罐，完整體驗製茶流程，透過寓教於樂的方式讓茶知識學習變的新奇又好玩，進而吸引更多兒童及年輕人成為茶學種子，強化茶文化的推廣與傳承。', '新北市政府文化局', '新北市坪林區水聳淒坑19-1號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '新北市坪林茶業博物館', 24.91097073, 121.724223, '門票+80', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='曉茶塾', `description`='以茶神陸羽的《茶經》內容為基礎，透過五感體驗及互動科技將茶知識轉化為大、小朋友都能輕鬆理解的趣味內容，民眾可以從採茶、炒茶、揉捻、烘焙，一直到設計出自己專屬的茶葉罐，完整體驗製茶流程，透過寓教於樂的方式讓茶知識學習變的新奇又好玩，進而吸引更多兒童及年輕人成為茶學種子，強化茶文化的推廣與傳承。', `organizer`='新北市政府文化局', `address`='新北市坪林區水聳淒坑19-1號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='新北市坪林茶業博物館', `latitude`=24.91097073, `longitude`=121.724223, `ticket_price`='門票+80', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29bdf26b32408680bec42', '114年南投好客文化學院：客家語言文化手作研習班', '參加對象：以家庭親子（小學3年級以上為佳）或夫妻共學為主。招收名額30名。報名時間：即日起至開課日或額滿為止。本研習免費，詳細課程資訊及報名方式可至南投縣政府文化局網站/最新消息（https://www.nthcc.gov.tw/A3_1/）項下查詢。活動洽詢：049-2246421轉710林先生。', '南投縣客家發展所', '南投縣南投市建國路135號', '2025-04-12 00:00:00', '2025-06-21 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.facebook.com/profile.php?id=100063965196974', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年南投好客文化學院：客家語言文化手作研習班', `description`='參加對象：以家庭親子（小學3年級以上為佳）或夫妻共學為主。招收名額30名。報名時間：即日起至開課日或額滿為止。本研習免費，詳細課程資訊及報名方式可至南投縣政府文化局網站/最新消息（https://www.nthcc.gov.tw/A3_1/）項下查詢。活動洽詢：049-2246421轉710林先生。', `organizer`='南投縣客家發展所', `address`='南投縣南投市建國路135號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-06-21 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100063965196974', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d29be026b32408680bec4e', '欣榮紀念圖書館暨玉蘭文化會館114年第一期研習班', '開設班別：瑜珈養生、行書入門、風水之三元玄空、中國竹笛輕鬆學、有氧體適能、幸福空間裝修設計、日本自助旅遊快樂行（實務操作）、行動支付應用、咖啡知識與手沖實作班、輕鬆學英文、漢音詩詞朗誦與吟唱、草藥養生應用、二胡中級進階班、陳氏太極拳三十八式、綠生活食尚營養、觀光日語2、拉丁有氧健身、易經卜卦解卦實用班，共規劃18門課程。\r\n報名時間：自3月22日起至4月2日止，開館時間。\r\n報名地點：一樓服務台現場報名。\r\n報名方式：報名須出示個人借閱證，並詳填報名表、繳交保證金及一吋照片1張。未帶身分證件、照片者，請於三日內補件。\r\n參加對象：僅限成人\r\n洽詢電話：049-2637666。', '財團法人福田文教基金會', '南投縣竹山鎮大勇路 26 號', '2025-04-08 00:00:00', '2025-06-27 00:00:00', '欣榮紀念圖書館暨玉蘭文化會館', 23.7569747, 120.6749408, '保證金+1000', 'http://hsinrong.org/index.php', '[]') ON DUPLICATE KEY UPDATE `activity_name`='欣榮紀念圖書館暨玉蘭文化會館114年第一期研習班', `description`='開設班別：瑜珈養生、行書入門、風水之三元玄空、中國竹笛輕鬆學、有氧體適能、幸福空間裝修設計、日本自助旅遊快樂行（實務操作）、行動支付應用、咖啡知識與手沖實作班、輕鬆學英文、漢音詩詞朗誦與吟唱、草藥養生應用、二胡中級進階班、陳氏太極拳三十八式、綠生活食尚營養、觀光日語2、拉丁有氧健身、易經卜卦解卦實用班，共規劃18門課程。\r\n報名時間：自3月22日起至4月2日止，開館時間。\r\n報名地點：一樓服務台現場報名。\r\n報名方式：報名須出示個人借閱證，並詳填報名表、繳交保證金及一吋照片1張。未帶身分證件、照片者，請於三日內補件。\r\n參加對象：僅限成人\r\n洽詢電話：049-2637666。', `organizer`='財團法人福田文教基金會', `address`='南投縣竹山鎮大勇路 26 號', `start_date`='2025-04-08 00:00:00', `end_date`='2025-06-27 00:00:00', `location`='欣榮紀念圖書館暨玉蘭文化會館', `latitude`=23.7569747, `longitude`=120.6749408, `ticket_price`='保證金+1000', `source_url`='http://hsinrong.org/index.php', `image_url`='[]';
