INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d33d9026b32408680bec5b', '114年暑期實習生招募', '114年暑期實習生招募\n\n國立臺灣工藝研究發展中心邀請國內大專院校系所同學一起參與加入工藝的行列。\n歡迎對工藝文化、博物館研究、展示與教育推廣等領域有興趣者報名申請參加。\n\n實習期間：114年7月1日－8月31日（累計時數210小時）\n\n招募對象：大專院校（含研究所）相關科系，或對工藝文化推廣濃厚興趣之在學學生\n\n實習內容：館務運作、導覽解說、工藝人才培訓、典藏庫房管理等相見[附件、實習生招募需求]\n\n實習地點：國立臺灣工藝研究發展中心（南投草屯）\n\n聯絡人：049-2334141分機319 美學推廣組 沈先生\n\n ', '國立台灣工藝研究發展中心', '542  南投縣草屯鎮中正路573號', '2025-07-01 00:00:00', '2025-08-29 00:00:00', '無資料', 23.9797002, 120.69095, '無資料', 'https://event.culture.tw/mocweb/reg/NTCRI/Detail.init.ctr?actId=50160', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年暑期實習生招募', `description`='114年暑期實習生招募\n\n國立臺灣工藝研究發展中心邀請國內大專院校系所同學一起參與加入工藝的行列。\n歡迎對工藝文化、博物館研究、展示與教育推廣等領域有興趣者報名申請參加。\n\n實習期間：114年7月1日－8月31日（累計時數210小時）\n\n招募對象：大專院校（含研究所）相關科系，或對工藝文化推廣濃厚興趣之在學學生\n\n實習內容：館務運作、導覽解說、工藝人才培訓、典藏庫房管理等相見[附件、實習生招募需求]\n\n實習地點：國立臺灣工藝研究發展中心（南投草屯）\n\n聯絡人：049-2334141分機319 美學推廣組 沈先生\n\n ', `organizer`='國立台灣工藝研究發展中心', `address`='542  南投縣草屯鎮中正路573號', `start_date`='2025-07-01 00:00:00', `end_date`='2025-08-29 00:00:00', `location`='無資料', `latitude`=23.9797002, `longitude`=120.69095, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTCRI/Detail.init.ctr?actId=50160', `image_url`='[]';
