INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d490eb26b32408680bec85', '【新北市立圖書館萬里分館】許捷芳「東北角地質景觀攝影個展」', '【新北市立圖書館萬里分館】許捷芳「東北角地質景觀攝影個展」\r\n活動時間：01/02-12/31開館時間\r\n活動地點：新北市立圖書館萬里分館／藝文走廊（新北市萬里區瑪鋉路221號4樓）\r\n聯絡電話：02-2492-4490#12\r\n簡介：\r\n攝影，是一門觀察的藝術。在光影與雲彩的襯托下捕捉每個稍縱即逝的感動，充分展現出東北角得天獨厚的自然景緻。以一幀幀美不勝收的攝影作品，來傳達對台灣土地的熱忱，透過鏡頭刻劃出動人的瞬間，引領讀者以不同的角度探索全新的視野，發現不曾見過的東北角。\r\n歡迎闔家蒞臨觀賞！', '新北市立圖書館總館', '新北市萬里區瑪鍊路221號4樓', '2025-01-02 00:00:00', '2025-12-31 00:00:00', '新北市立圖書館萬里分館', 25.17572457, 121.6439307, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館萬里分館】許捷芳「東北角地質景觀攝影個展」', `description`='【新北市立圖書館萬里分館】許捷芳「東北角地質景觀攝影個展」\r\n活動時間：01/02-12/31開館時間\r\n活動地點：新北市立圖書館萬里分館／藝文走廊（新北市萬里區瑪鋉路221號4樓）\r\n聯絡電話：02-2492-4490#12\r\n簡介：\r\n攝影，是一門觀察的藝術。在光影與雲彩的襯托下捕捉每個稍縱即逝的感動，充分展現出東北角得天獨厚的自然景緻。以一幀幀美不勝收的攝影作品，來傳達對台灣土地的熱忱，透過鏡頭刻劃出動人的瞬間，引領讀者以不同的角度探索全新的視野，發現不曾見過的東北角。\r\n歡迎闔家蒞臨觀賞！', `organizer`='新北市立圖書館總館', `address`='新北市萬里區瑪鍊路221號4樓', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='新北市立圖書館萬里分館', `latitude`=25.17572457, `longitude`=121.6439307, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
