INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914226b32408680beca9', '情感空間－台南市藝術家協會會員高雄聯展', '本會成立歷史悠久會員眾多，是台南地區大型文化藝術團體。會員們的資歷完整，作品涵蓋東、西方藝術，從傳統工藝到當代藝術共20多項類別，是難得能凝聚各大藝術類融於一會的大型藝術團體，在文化藝術界難得一見。此次首跨高雄市舉辦會員聯展，展出作者亦不乏國內外參賽獲獎的傑出菁英暨各類文化技術保存者，作品精彩可期。\r\n', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-06-27 00:00:00', '2025-07-08 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='情感空間－台南市藝術家協會會員高雄聯展', `description`='本會成立歷史悠久會員眾多，是台南地區大型文化藝術團體。會員們的資歷完整，作品涵蓋東、西方藝術，從傳統工藝到當代藝術共20多項類別，是難得能凝聚各大藝術類融於一會的大型藝術團體，在文化藝術界難得一見。此次首跨高雄市舉辦會員聯展，展出作者亦不乏國內外參賽獲獎的傑出菁英暨各類文化技術保存者，作品精彩可期。\r\n', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-06-27 00:00:00', `end_date`='2025-07-08 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becb0', '苗栗縣私立欣欣幼兒園第43屆畢業成果發表', '欣欣幼兒園的小朋友透過美語律動、體適能活動、創意舞蹈及樂器合奏…等多項豐富精采的成果展演中創造耀眼的自我，讓這群可愛的小小表演家獲得肯定及喝采，在與家長分享幼兒們的學習成果過程中共創美好的回憶。', '苗栗縣私立欣欣幼兒園', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-06-27 00:00:00', '2025-06-27 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗栗縣私立欣欣幼兒園第43屆畢業成果發表', `description`='欣欣幼兒園的小朋友透過美語律動、體適能活動、創意舞蹈及樂器合奏…等多項豐富精采的成果展演中創造耀眼的自我，讓這群可愛的小小表演家獲得肯定及喝采，在與家長分享幼兒們的學習成果過程中共創美好的回憶。', `organizer`='苗栗縣私立欣欣幼兒園', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-06-27 00:00:00', `end_date`='2025-06-27 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becb7', '南濤人體畫會 人體藝術生活展 ', '高雄市南濤人體畫會是一個專業的人體藝術、生活繪創作團體，早期人員組成為高雄區重量級美術教師除學校做育英才外更結合民間團體推廣美育。\r\n本次由一群愛好人體藝術畫者，藉由固定畫聚，創作出巧思畫作，除了自己賞心悅目外還有推廣人體藝術生活之美想法，讓無法同步者亦能參與欣賞。\r\n展出作品作品一律為西畫類，然媒材有不同屬性如鉛筆、水彩、油畫…平面等亦有3D多媒體的表達，雖只是一項人物卻有多元化銓釋，實為難得。本次除了人體藝術外也一併展出生活風景畫增添元素。\r\n人體美學的表達平易，不高深，需長期持續並堅持。做對的事，自己走過的路，印象最清楚，並懇請各界指教。\r\n', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-06-20 00:00:00', '2025-07-01 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4104', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南濤人體畫會 人體藝術生活展 ', `description`='高雄市南濤人體畫會是一個專業的人體藝術、生活繪創作團體，早期人員組成為高雄區重量級美術教師除學校做育英才外更結合民間團體推廣美育。\r\n本次由一群愛好人體藝術畫者，藉由固定畫聚，創作出巧思畫作，除了自己賞心悅目外還有推廣人體藝術生活之美想法，讓無法同步者亦能參與欣賞。\r\n展出作品作品一律為西畫類，然媒材有不同屬性如鉛筆、水彩、油畫…平面等亦有3D多媒體的表達，雖只是一項人物卻有多元化銓釋，實為難得。本次除了人體藝術外也一併展出生活風景畫增添元素。\r\n人體美學的表達平易，不高深，需長期持續並堅持。做對的事，自己走過的路，印象最清楚，並懇請各界指教。\r\n', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-06-20 00:00:00', `end_date`='2025-07-01 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4104', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d4914326b32408680becc1', '文學力－書寫LÁN臺灣主題展', '本展為南投縣文學資料館向國立臺灣文學館借用之「文學力─書寫LÁN臺灣」行動展。國立臺灣文學館為國家級的文學博物館，該館將龐雜的臺灣文學體系與史料化繁為簡，透過常設展將百年來的文學史，化為日常且有趣的生活體驗。\r\n展出主題分為「注意，你已被文學包圍了」、「始動，島孕育的‧與海帶來的（～1895）」、「立志，文明開化的夢與傷（1895～1945）」、「跨越，窒息年代的游擊戰（1945～1980）」、「爆炸，每個人都飆出高音（1980～2000）」、「＿＿，寫我們一起的未來」等六大主題，將文學以最日常的方式，引導你試著與臺灣文學互動。\r\n現場並設置臺灣文學互動遊戲，「文學二選一」幫你找出最有感的文體，《文青養成指南——台灣文學史基本教材》讓你了解台灣百年文學史，而如果你想要找到你的閱讀新方向，就來現場抽個「文學籤詩」，讓你以書解籤。\r\n「文學力─書寫LÁN臺灣主題展」以「行動展」的方式，做為臺灣文學館分身告訴大家，這裏有豐富、活潑的文學內涵，不需到台南，也能輕鬆走進臺灣文學的世界。\r\n本展歡迎縣內國中以上學校預約週二至週五時間參觀導覽，提昇學子之臺灣文學知識，預約網址：https://reurl.cc/Dqymm6。', '南投縣政府文化局', '南投縣南投市中興路669號', '2025-04-01 00:00:00', '2025-07-20 00:00:00', '南投縣政府文化局圖書館', 23.9027891, 120.691332, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='文學力－書寫LÁN臺灣主題展', `description`='本展為南投縣文學資料館向國立臺灣文學館借用之「文學力─書寫LÁN臺灣」行動展。國立臺灣文學館為國家級的文學博物館，該館將龐雜的臺灣文學體系與史料化繁為簡，透過常設展將百年來的文學史，化為日常且有趣的生活體驗。\r\n展出主題分為「注意，你已被文學包圍了」、「始動，島孕育的‧與海帶來的（～1895）」、「立志，文明開化的夢與傷（1895～1945）」、「跨越，窒息年代的游擊戰（1945～1980）」、「爆炸，每個人都飆出高音（1980～2000）」、「＿＿，寫我們一起的未來」等六大主題，將文學以最日常的方式，引導你試著與臺灣文學互動。\r\n現場並設置臺灣文學互動遊戲，「文學二選一」幫你找出最有感的文體，《文青養成指南——台灣文學史基本教材》讓你了解台灣百年文學史，而如果你想要找到你的閱讀新方向，就來現場抽個「文學籤詩」，讓你以書解籤。\r\n「文學力─書寫LÁN臺灣主題展」以「行動展」的方式，做為臺灣文學館分身告訴大家，這裏有豐富、活潑的文學內涵，不需到台南，也能輕鬆走進臺灣文學的世界。\r\n本展歡迎縣內國中以上學校預約週二至週五時間參觀導覽，提昇學子之臺灣文學知識，預約網址：https://reurl.cc/Dqymm6。', `organizer`='南投縣政府文化局', `address`='南投縣南投市中興路669號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-07-20 00:00:00', `location`='南投縣政府文化局圖書館', `latitude`=23.9027891, `longitude`=120.691332, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9367967', '總館03/30作家與讀者有約講座《這樣生活不失智》', '&nbsp; &nbsp; 本館將於3月30日(週日)14：00至16：00於總館10樓國際會議廳舉辦作家與讀者有約講座「這樣生活不失智」，活動將邀請國立臺灣大學職能治療學系毛慧芬老師及天主教失智老人基金會陳俊佑社工處長，與現場讀者一同分享以科學實證為基礎，分享預防失智的原則與實用招式，帶領現場讀者藉由測驗、問答檢視自己的生活模式，再依照測驗結果選擇合適的健腦活動，陪你量身打造不失智的生活！新書講座無須報名，自由入場，本講座提供公務人員學習時數認證2小時，參加者更有機會獲得限量桌遊版書衣海報，歡迎您踴躍參加。活動時間：3月30日（週日）14:00-16:00活動講師：臺灣大學職能治療學系教授 毛慧芬天主教失智老人基金會社工處長 陳俊佑（本書作者） &nbsp; &nbsp;活動地點：總館10樓國際會議廳（臺北市大安區建國南路2段125號）※本講座不需報名及收費，如滿座、演講開始30分鐘後，恕不開放入場，敬請提早入座歡迎您踴躍參加！※本講座提供「公務人員終身學習」時數。', '臺北市立圖書館', '無資料', '2025-03-15 00:00:00', '2025-03-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C07F1AA2853D3110', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館03/30作家與讀者有約講座《這樣生活不失智》', `description`='&nbsp; &nbsp; 本館將於3月30日(週日)14：00至16：00於總館10樓國際會議廳舉辦作家與讀者有約講座「這樣生活不失智」，活動將邀請國立臺灣大學職能治療學系毛慧芬老師及天主教失智老人基金會陳俊佑社工處長，與現場讀者一同分享以科學實證為基礎，分享預防失智的原則與實用招式，帶領現場讀者藉由測驗、問答檢視自己的生活模式，再依照測驗結果選擇合適的健腦活動，陪你量身打造不失智的生活！新書講座無須報名，自由入場，本講座提供公務人員學習時數認證2小時，參加者更有機會獲得限量桌遊版書衣海報，歡迎您踴躍參加。活動時間：3月30日（週日）14:00-16:00活動講師：臺灣大學職能治療學系教授 毛慧芬天主教失智老人基金會社工處長 陳俊佑（本書作者） &nbsp; &nbsp;活動地點：總館10樓國際會議廳（臺北市大安區建國南路2段125號）※本講座不需報名及收費，如滿座、演講開始30分鐘後，恕不開放入場，敬請提早入座歡迎您踴躍參加！※本講座提供「公務人員終身學習」時數。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C07F1AA2853D3110', `image_url`='[]';
