INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9373135', '轉知「114年臺北市青年盃網球錦標賽」賽程總表及籤表 (3/14更新)', '比賽日期：114年3月22日至23日比賽地點：臺北市天母運動公園網球場主辦單位：臺北市體育總會網球協會聯絡方式：0928-038-808 &nbsp;陳小姐&nbsp;註：比賽時間為上午8時30分，請第一輪選手於8點報到餘各組選手請提早半小時報到。如因故無法前往比賽，亦請來電告知，謝謝。', '臺北市政府體育局', '無資料', '2025-03-22 00:00:00', '2025-03-23 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=914A69A003E8C838', '[]') ON DUPLICATE KEY UPDATE `activity_name`='轉知「114年臺北市青年盃網球錦標賽」賽程總表及籤表 (3/14更新)', `description`='比賽日期：114年3月22日至23日比賽地點：臺北市天母運動公園網球場主辦單位：臺北市體育總會網球協會聯絡方式：0928-038-808 &nbsp;陳小姐&nbsp;註：比賽時間為上午8時30分，請第一輪選手於8點報到餘各組選手請提早半小時報到。如因故無法前往比賽，亦請來電告知，謝謝。', `organizer`='臺北市政府體育局', `address`='無資料', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=914A69A003E8C838', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9373125', '總館「性別教育讀書會」，歡迎報名參加！', '當兒童進入少年時期，伴隨著身理變化以及渴望獨立自主，需要有人能指引未來方向。經由教育統計，多數青少年的成長學習，來自於媒體，若有經典少年小說陪伴，在不說教的氛圍下，更能達成對己真誠、對人友善、對世界常保關懷的成熟人格。本館與台灣兒童閱讀學會於3月26日至6月4日合作辦理「性別教育讀書會」，以尊重多元與包容差異為內容，挑選10本經典得獎作品，分析內容並設計成教案，方便教師、家長與閱讀推手推廣閱讀，內容包含討論喜愛研究科學的少女所受到的歧視、如何在身材議題下又能有自信的國中女孩、移民女孩的文化包容、勇敢追夢的少年故事、探究自然生態與自我認識等等具有時代意義下的議題，期待在圖書館主動協助下，成就書香滿寶島的美好。一、活動地點：總館9樓多功能教室二、講師：國立政治大學實驗教育推動中心執行長徐永康老師三、活動時間：3月26日至6月4日止（共10週）星期三9:30-11:30四、課程日期/使用教材： 1.3/26 &nbsp;《最後的北極熊》2.4/9 &nbsp; 《樂透男孩》3.4/16 &nbsp;《星星滿口袋》4.4/23 &nbsp;《頭條新聞大作戰》5.4/30 &nbsp;《最後的製圖師》6.5/7 &nbsp; 《靈鳥的守護》7.5/14 &nbsp;《老船長的木偶》8.5/21 &nbsp;《未曾上映的電影》9.5/28 &nbsp;《台北捷運冒險記》10.6/4 &nbsp;《消失的灰鯨》五、參加對象：對兒童文學、青少年文學或性別教育有興趣之讀者皆可參加六、報名時間與名額：即日起至額滿為止，共20位名額。七、報名方式：線上報名：請至https://www.beclass.com/rid=294fec767cfcc71ce9d4報名如有相關疑問請洽總館推廣課林先生，電話：(02)2755-2823轉2112', '臺北市立圖書館', '無資料', '2025-03-13 00:00:00', '2025-03-25 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=DF9ED640E2234308', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館「性別教育讀書會」，歡迎報名參加！', `description`='當兒童進入少年時期，伴隨著身理變化以及渴望獨立自主，需要有人能指引未來方向。經由教育統計，多數青少年的成長學習，來自於媒體，若有經典少年小說陪伴，在不說教的氛圍下，更能達成對己真誠、對人友善、對世界常保關懷的成熟人格。本館與台灣兒童閱讀學會於3月26日至6月4日合作辦理「性別教育讀書會」，以尊重多元與包容差異為內容，挑選10本經典得獎作品，分析內容並設計成教案，方便教師、家長與閱讀推手推廣閱讀，內容包含討論喜愛研究科學的少女所受到的歧視、如何在身材議題下又能有自信的國中女孩、移民女孩的文化包容、勇敢追夢的少年故事、探究自然生態與自我認識等等具有時代意義下的議題，期待在圖書館主動協助下，成就書香滿寶島的美好。一、活動地點：總館9樓多功能教室二、講師：國立政治大學實驗教育推動中心執行長徐永康老師三、活動時間：3月26日至6月4日止（共10週）星期三9:30-11:30四、課程日期/使用教材： 1.3/26 &nbsp;《最後的北極熊》2.4/9 &nbsp; 《樂透男孩》3.4/16 &nbsp;《星星滿口袋》4.4/23 &nbsp;《頭條新聞大作戰》5.4/30 &nbsp;《最後的製圖師》6.5/7 &nbsp; 《靈鳥的守護》7.5/14 &nbsp;《老船長的木偶》8.5/21 &nbsp;《未曾上映的電影》9.5/28 &nbsp;《台北捷運冒險記》10.6/4 &nbsp;《消失的灰鯨》五、參加對象：對兒童文學、青少年文學或性別教育有興趣之讀者皆可參加六、報名時間與名額：即日起至額滿為止，共20位名額。七、報名方式：線上報名：請至https://www.beclass.com/rid=294fec767cfcc71ce9d4報名如有相關疑問請洽總館推廣課林先生，電話：(02)2755-2823轉2112', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-13 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=DF9ED640E2234308', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9373076', '秀山民眾閱覽室「好禮獨秀」閱讀存摺點數贈獎活動來囉!', '一、活動方式：讀者可持有效個人借閱證或行動借閱證，於「秀山民眾閱覽室」借閱5本圖書，並憑閱讀存摺系統點數，兌換秀山限定獎勵品。本館將不定期推出獎勵品，提供線上兌換。詳情可關注秀山民眾閱覽室Facebook粉絲專頁：https://www.facebook.com/profile.php?id=100063726228928二、活動時間： 3月1日（週六）至12月31日（週三）【服務臺獎勵品兌換時間】週二至週六：8:30-20:30週日與週一：9:00-16:30三、交通路線：https://reurl.cc/RqxRog', '臺北市立圖書館', '無資料', '2025-03-01 00:00:00', '2025-12-31 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=7B8755AB8FEECAA5', '[]') ON DUPLICATE KEY UPDATE `activity_name`='秀山民眾閱覽室「好禮獨秀」閱讀存摺點數贈獎活動來囉!', `description`='一、活動方式：讀者可持有效個人借閱證或行動借閱證，於「秀山民眾閱覽室」借閱5本圖書，並憑閱讀存摺系統點數，兌換秀山限定獎勵品。本館將不定期推出獎勵品，提供線上兌換。詳情可關注秀山民眾閱覽室Facebook粉絲專頁：https://www.facebook.com/profile.php?id=100063726228928二、活動時間： 3月1日（週六）至12月31日（週三）【服務臺獎勵品兌換時間】週二至週六：8:30-20:30週日與週一：9:00-16:30三、交通路線：https://reurl.cc/RqxRog', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=7B8755AB8FEECAA5', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9369184', '星姊姊說故事【春季星空-烏鴉座的星座故事】', '原本歌聲悅耳又有著雪白羽毛的烏鴉，因為犯了貪吃和愛說謊的毛病使得自己受到天神的處罰而變成&hellip;。想瞭解烏鴉座的星座故事並學會如何在春季夜空中找到隻烏鴉，請報名參加3月22日的活動，共享親子天文時光。活動時間：3月22日（六）14:00-15:00。活動對象：親子（幼稚園大班至國小三年級的孩童及其家長）。活動地點：展示場二樓兒童區。活動內容 : 熱場活動-故事時間-烏鴉座星點DIY-小導覽(尋找展示場中的烏鴉)。活動費用：免費。報名方式：線上報名注意事項：報名時只要填報參加兒童。購票參觀展示場即可免費參加活動（收費基準請參見購票資訊）。洽詢電話：02-28314551轉703展示組莊小姐。', '臺北市立天文科學教育館', '無資料', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A29BE2035493C2F9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='星姊姊說故事【春季星空-烏鴉座的星座故事】', `description`='原本歌聲悅耳又有著雪白羽毛的烏鴉，因為犯了貪吃和愛說謊的毛病使得自己受到天神的處罰而變成&hellip;。想瞭解烏鴉座的星座故事並學會如何在春季夜空中找到隻烏鴉，請報名參加3月22日的活動，共享親子天文時光。活動時間：3月22日（六）14:00-15:00。活動對象：親子（幼稚園大班至國小三年級的孩童及其家長）。活動地點：展示場二樓兒童區。活動內容 : 熱場活動-故事時間-烏鴉座星點DIY-小導覽(尋找展示場中的烏鴉)。活動費用：免費。報名方式：線上報名注意事項：報名時只要填報參加兒童。購票參觀展示場即可免費參加活動（收費基準請參見購票資訊）。洽詢電話：02-28314551轉703展示組莊小姐。', `organizer`='臺北市立天文科學教育館', `address`='無資料', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=A29BE2035493C2F9', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9372275', '總館視聽室「法語國家小影展」', '「臺灣法語節」是每年三月由在臺法語國家機構及使館共同合作，向臺灣民眾呈現世界法語文化的活動 。在全球同步歡慶3月20日世界法語日的同時，邀請在臺灣的法語人士共同體驗、享受法語。「法語國家小影展」由三個國家各自選擇一部電影，讓臺灣觀眾透過螢幕體驗不同的文化情境。原3月28日總館B2演講廳場次，因故取消，改為總館8樓團體欣賞室播映《巴黎沙龍》（14:30播映／97分鐘／輔12）（8樓場次請於開館後至8樓視聽室自助劃位區電腦，使用借書證或身分證等相關證件自助劃位，並抽取票券(限當日場次)免費入場。）1.主辦單位：比利時台北辦事處、瑞士商務辦事處、盧森堡台北辦事處2.合辦單位：臺北市立圖書館3.活動資訊：(1)3月24日 14:30-&nbsp;電影名稱：The Empire of Silence《沉默的帝國》地點：總館B2演講廳報名方式：不須報名，自由入座&nbsp;(2)3月25日14:30-電影名稱：Bisons《野牛》地點：總館B2演講廳報名方式：不須報名，自由入座(3)3月26日14:30-電影名稱：Black Tea《以愛之茗》地點：總館B2演講廳報名方式：不須報名，自由入座4.洽詢電話: 總館視聽室(02)27552823分機2801', '臺北市立圖書館', '無資料', '2025-03-14 00:00:00', '2025-03-26 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=00216EE9CD664081', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館視聽室「法語國家小影展」', `description`='「臺灣法語節」是每年三月由在臺法語國家機構及使館共同合作，向臺灣民眾呈現世界法語文化的活動 。在全球同步歡慶3月20日世界法語日的同時，邀請在臺灣的法語人士共同體驗、享受法語。「法語國家小影展」由三個國家各自選擇一部電影，讓臺灣觀眾透過螢幕體驗不同的文化情境。原3月28日總館B2演講廳場次，因故取消，改為總館8樓團體欣賞室播映《巴黎沙龍》（14:30播映／97分鐘／輔12）（8樓場次請於開館後至8樓視聽室自助劃位區電腦，使用借書證或身分證等相關證件自助劃位，並抽取票券(限當日場次)免費入場。）1.主辦單位：比利時台北辦事處、瑞士商務辦事處、盧森堡台北辦事處2.合辦單位：臺北市立圖書館3.活動資訊：(1)3月24日 14:30-&nbsp;電影名稱：The Empire of Silence《沉默的帝國》地點：總館B2演講廳報名方式：不須報名，自由入座&nbsp;(2)3月25日14:30-電影名稱：Bisons《野牛》地點：總館B2演講廳報名方式：不須報名，自由入座(3)3月26日14:30-電影名稱：Black Tea《以愛之茗》地點：總館B2演講廳報名方式：不須報名，自由入座4.洽詢電話: 總館視聽室(02)27552823分機2801', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=00216EE9CD664081', `image_url`='[]';
