INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9372324', '永春分館「臺灣語初級研習班」，歡迎報名參加!', '一、活動內容：配合教育部頒布臺語羅馬拼音方案與詞彙之推廣與普及，以及本土語文教育政策，特別規劃「臺灣語初級研習班」，期能建立多元文化的學習環境。二、活動時間：3月26日起至7月9日止，每週三14:00-16:00上課。(每次2小時，共計32小時)三、上課地點：永春分館4樓多功能活動室(臺北市信義區松山路294號4樓)四、參加對象：對臺語有興趣且略具聽、說能力的民眾，15~30人。五、費用：免學費(惟學員需自行負擔講義影印費)六、講師：由臺北市台灣語協會優秀臺語教師擔任。七、報名方式：1、採線上報名(https://forms.gle/gHUttKTpjEMr4uzA6)2、現場報名（臺北市立圖書館永春分館3樓服務臺）', '臺北市立圖書館', '無資料', '2025-03-13 00:00:00', '2025-07-09 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1195A025EEF8B3CA', '[]') ON DUPLICATE KEY UPDATE `activity_name`='永春分館「臺灣語初級研習班」，歡迎報名參加!', `description`='一、活動內容：配合教育部頒布臺語羅馬拼音方案與詞彙之推廣與普及，以及本土語文教育政策，特別規劃「臺灣語初級研習班」，期能建立多元文化的學習環境。二、活動時間：3月26日起至7月9日止，每週三14:00-16:00上課。(每次2小時，共計32小時)三、上課地點：永春分館4樓多功能活動室(臺北市信義區松山路294號4樓)四、參加對象：對臺語有興趣且略具聽、說能力的民眾，15~30人。五、費用：免學費(惟學員需自行負擔講義影印費)六、講師：由臺北市台灣語協會優秀臺語教師擔任。七、報名方式：1、採線上報名(https://forms.gle/gHUttKTpjEMr4uzA6)2、現場報名（臺北市立圖書館永春分館3樓服務臺）', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-13 00:00:00', `end_date`='2025-07-09 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1195A025EEF8B3CA', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9372084', '陽明借還書工作站辦理「何不先學會快樂的獨老？」失智症講座暨主題書展，歡迎參加！', '臺灣於2025年邁向超高齡社會，健康不是無病痛，而是有病治療、無病健身，人生七十才開始「生病」，接受變老是一個自然過程，狀態調整好，身邊長輩就是我們變老的教材。圖書館是知識力量的來源之一，希望經由醫師與作家的引言及對談、透過主題館藏閱讀方式，以理性與樂觀的態度學會快樂的獨老與面對失智症議題，歡迎有興趣者以附檔海報資訊報名參加。活動資訊如下：一、「何不先學會快樂的獨老？」失智症講座1.活動時間： 3月26日（三）上午10：30至12：152.活動地點：陽明借還書工作站3.活動主講人：郭文華博士、劉秀枝醫生及王琄小姐二、「何不先學會快樂的獨老？」失智症相關主題書展1.活動時間： 3月17日（一）至4月30日（三）2.活動地點：陽明借還書工作站3.活動內容：展出與失智症、健康飲食、情緒療育相關主題圖書及劉秀枝醫生著作，展書均可外借。', '臺北市立圖書館', '無資料', '2025-03-13 00:00:00', '2025-04-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=41A965C7400CBE0A', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陽明借還書工作站辦理「何不先學會快樂的獨老？」失智症講座暨主題書展，歡迎參加！', `description`='臺灣於2025年邁向超高齡社會，健康不是無病痛，而是有病治療、無病健身，人生七十才開始「生病」，接受變老是一個自然過程，狀態調整好，身邊長輩就是我們變老的教材。圖書館是知識力量的來源之一，希望經由醫師與作家的引言及對談、透過主題館藏閱讀方式，以理性與樂觀的態度學會快樂的獨老與面對失智症議題，歡迎有興趣者以附檔海報資訊報名參加。活動資訊如下：一、「何不先學會快樂的獨老？」失智症講座1.活動時間： 3月26日（三）上午10：30至12：152.活動地點：陽明借還書工作站3.活動主講人：郭文華博士、劉秀枝醫生及王琄小姐二、「何不先學會快樂的獨老？」失智症相關主題書展1.活動時間： 3月17日（一）至4月30日（三）2.活動地點：陽明借還書工作站3.活動內容：展出與失智症、健康飲食、情緒療育相關主題圖書及劉秀枝醫生著作，展書均可外借。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-13 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=41A965C7400CBE0A', `image_url`='[]';
