INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('95e51a48c4d3e6f45f1cd288e7c1dd8c', '【新北市立圖書館中和員山分館】「Home Library」系列活動：點心讀書會(芝麻饅頭)', '講師：小雨老師、張金龍老師、趙淑清老師搭配故事：白雲麵包一、時間：4/19(六) 14:00-15:30二、地點：新北市中和區自治街67號三、對象：只要對活動有興趣都可以，小朋友需要家長陪同，至多10對親子四、材料費：免費五、活動前請攜帶：保鮮盒2個、烘焙墊、圍裙、麵糰切割板、桿麵棍、抹布、筷子一雙六、報名方式：自由入場七、洽詢電話：(02) 8221-1152主辦單位：新北市立圖書館中和員山分館合辦單位：中和區民享藝文中心', '新北市立圖書館', '新北市中和區民享街37號2樓', '新北市立圖書館中和員山分館', 24.99088039, 121.4936744, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館中和員山分館】「Home Library」系列活動：點心讀書會(芝麻饅頭)', `description`='講師：小雨老師、張金龍老師、趙淑清老師搭配故事：白雲麵包一、時間：4/19(六) 14:00-15:30二、地點：新北市中和區自治街67號三、對象：只要對活動有興趣都可以，小朋友需要家長陪同，至多10對親子四、材料費：免費五、活動前請攜帶：保鮮盒2個、烘焙墊、圍裙、麵糰切割板、桿麵棍、抹布、筷子一雙六、報名方式：自由入場七、洽詢電話：(02) 8221-1152主辦單位：新北市立圖書館中和員山分館合辦單位：中和區民享藝文中心', `organizer`='新北市立圖書館', `address`='新北市中和區民享街37號2樓', `location`='新北市立圖書館中和員山分館', `latitude`=24.99088039, `longitude`=121.4936744, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('95e51a48c4d3e6f4661d343e716a9385', '【新北市立圖書館三芝分館】與讀者有約-多元生活系列講座：「對症運動，鬆出好健康。」', '【新北市立圖書館三芝分館】與讀者有約-多元生活系列講座：「對症運動，鬆出好健康。」課程時間：4/26（六）14:00-16:00課程地點：新北市立圖書館三芝分館／閱覽區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11(電話/臨櫃/網路報名https://reurl.cc/OY7VlA)課程內容：隨著高齡化社會到來，人們逐漸重視老年生活品質及健康，骨性關節炎影響現代老年人至深，但你知道骨性關節炎是怎麼引起的呢?要怎麼預防及療護?本課程講師將分享，有效地從飲食、運動、工作、起居等各方面讓你正確了解膝關節及身體保養方式，讓你「活到老，人不老」。', '新北市立圖書館', '新北市三芝區民生街31號4樓', '新北市立圖書館三芝分館／閱覽區', 25.23159891, 121.515558, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三芝分館】與讀者有約-多元生活系列講座：「對症運動，鬆出好健康。」', `description`='【新北市立圖書館三芝分館】與讀者有約-多元生活系列講座：「對症運動，鬆出好健康。」課程時間：4/26（六）14:00-16:00課程地點：新北市立圖書館三芝分館／閱覽區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11(電話/臨櫃/網路報名https://reurl.cc/OY7VlA)課程內容：隨著高齡化社會到來，人們逐漸重視老年生活品質及健康，骨性關節炎影響現代老年人至深，但你知道骨性關節炎是怎麼引起的呢?要怎麼預防及療護?本課程講師將分享，有效地從飲食、運動、工作、起居等各方面讓你正確了解膝關節及身體保養方式，讓你「活到老，人不老」。', `organizer`='新北市立圖書館', `address`='新北市三芝區民生街31號4樓', `location`='新北市立圖書館三芝分館／閱覽區', `latitude`=25.23159891, `longitude`=121.515558, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
