INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('95e51a48c4d3e6f4c1a8f3a8e971a7f2', '【新北市立圖書館三芝分館】《閱讀書籤》4月主題書展「整理筆記大作戰」', '【新北市立圖書館三芝分館】《閱讀書籤》4月主題書展「整理筆記大作戰」書展期間：4/25-4/30（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館三芝分館／書展區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11書展簡介：做筆記不但能讓我們掌握課程重點，也能在整理的過程中加深對於內容的理解。筆記技巧甚至也可以應用於生活，幫助我們完成日常瑣碎的待辦事項。長期養成筆記的習慣，還能訓練出規劃和統整的能力，現在就讓我們一起看書學習各種整理筆記的技巧吧!', '新北市立圖書館', '新北市三芝區民生街31號4樓', '新北市立圖書館三芝分館／書展區', 25.23159891, 121.515558, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三芝分館】《閱讀書籤》4月主題書展「整理筆記大作戰」', `description`='【新北市立圖書館三芝分館】《閱讀書籤》4月主題書展「整理筆記大作戰」書展期間：4/25-4/30（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館三芝分館／書展區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11書展簡介：做筆記不但能讓我們掌握課程重點，也能在整理的過程中加深對於內容的理解。筆記技巧甚至也可以應用於生活，幫助我們完成日常瑣碎的待辦事項。長期養成筆記的習慣，還能訓練出規劃和統整的能力，現在就讓我們一起看書學習各種整理筆記的技巧吧!', `organizer`='新北市立圖書館', `address`='新北市三芝區民生街31號4樓', `location`='新北市立圖書館三芝分館／書展區', `latitude`=25.23159891, `longitude`=121.515558, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
