INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('95e51a48c4d3e6f4c035a3e0cc9a9163', '【新北市立圖書館金山分館】與讀者有約-多元生活系列講座：「3C時代脊椎預防」', '【新北市立圖書館金山分館】與讀者有約-多元生活系列講座：「3C時代脊椎預防」課程時間：4/5（六）14:00-16:00課程地點：新北市立圖書館金山分館／3樓團體視聽區（新北市金山區龜子山8號）聯絡電話：02-2498-4714#201(電話/臨櫃)課程內容：3C時代下，腰痠背痛沒事就跑出來發作一下，趕也趕不走。研究發現，只要停止彎腰駝背，保持良好姿勢，不僅能預防背痛、避免消化不良，更能因美姿美儀讓自己充滿自信，快跟著張晏傑老師一起掌握正確的健康觀念，學習脊椎舒壓保健操。', '新北市立圖書館', '新北市金山區龜子山8號', '新北市立圖書館金山分館／3樓團體視聽區', 25.21714594, 121.6052639, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館金山分館】與讀者有約-多元生活系列講座：「3C時代脊椎預防」', `description`='【新北市立圖書館金山分館】與讀者有約-多元生活系列講座：「3C時代脊椎預防」課程時間：4/5（六）14:00-16:00課程地點：新北市立圖書館金山分館／3樓團體視聽區（新北市金山區龜子山8號）聯絡電話：02-2498-4714#201(電話/臨櫃)課程內容：3C時代下，腰痠背痛沒事就跑出來發作一下，趕也趕不走。研究發現，只要停止彎腰駝背，保持良好姿勢，不僅能預防背痛、避免消化不良，更能因美姿美儀讓自己充滿自信，快跟著張晏傑老師一起掌握正確的健康觀念，學習脊椎舒壓保健操。', `organizer`='新北市立圖書館', `address`='新北市金山區龜子山8號', `location`='新北市立圖書館金山分館／3樓團體視聽區', `latitude`=25.21714594, `longitude`=121.6052639, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
