INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('95e51a48c4d3e6f4e077cb6db3476996', '【新北市立圖書館萬里分館】與讀者有約-多元生活系列講座：「低碳蔬活愛地球～樂活陽台蔬菜盆栽」', '【新北市立圖書館萬里分館】與讀者有約-多元生活系列講座：「低碳蔬活愛地球～樂活陽台蔬菜盆栽」課程時間：4/12（六）14:00-16:00課程地點：新北市立圖書館萬里分館／閱覽室（新北市萬里區瑪鋉路221號4樓）聯絡電話：02-2492-4490#12(電話/臨櫃/網路報名https://reurl.cc/466KVL)課程內容：吳俊偉老師為國立臺灣大學園藝暨景觀學系農學博士，現為宏國德霖科技大學助理教授。植物不再只是裝飾空間的角色，也能療癒我們的身心，吳老師將用淺顯易懂的方式說明如何佈置空氣淨化植物，讓讀者能體會植物相伴的綠意生活。', '新北市立圖書館', '新北市萬里區瑪鋉路221號4樓', '新北市立圖書館萬里分館／閱覽室', 25.17572457, 121.6439307, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館萬里分館】與讀者有約-多元生活系列講座：「低碳蔬活愛地球～樂活陽台蔬菜盆栽」', `description`='【新北市立圖書館萬里分館】與讀者有約-多元生活系列講座：「低碳蔬活愛地球～樂活陽台蔬菜盆栽」課程時間：4/12（六）14:00-16:00課程地點：新北市立圖書館萬里分館／閱覽室（新北市萬里區瑪鋉路221號4樓）聯絡電話：02-2492-4490#12(電話/臨櫃/網路報名https://reurl.cc/466KVL)課程內容：吳俊偉老師為國立臺灣大學園藝暨景觀學系農學博士，現為宏國德霖科技大學助理教授。植物不再只是裝飾空間的角色，也能療癒我們的身心，吳老師將用淺顯易懂的方式說明如何佈置空氣淨化植物，讓讀者能體會植物相伴的綠意生活。', `organizer`='新北市立圖書館', `address`='新北市萬里區瑪鋉路221號4樓', `location`='新北市立圖書館萬里分館／閱覽室', `latitude`=25.17572457, `longitude`=121.6439307, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('95e51a48c4d3e6f447a2d467920a7fc2', '【新北市立圖書館萬里分館】《閱讀書籤》4月主題書展「春風詩語」', '【新北市立圖書館萬里分館】《閱讀書籤》4月主題書展「春風詩語」( 文化部要加)書展期間：3/22-4/22（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館萬里分館／書展區（新北市萬里區瑪鋉路221號4樓）聯絡電話：02-2492-4490#12書展簡介：2025新北詩歌節以「我和春天有個約會」為主題，結合春天的生命力與詩意之美，邀請民眾透過聽覺、視覺、嗅覺、味覺、觸覺，探索詩與五感的跨域體驗。活動包含年度詩選新書發表會與系列詩歌活動、講座等，讓詩歌融入日常，感受生活中的詩意與感動，於萬里分館辦理相關書展，歡迎到館借閱。', '新北市立圖書館', '新北市萬里區瑪鋉路221號4樓', '新北市立圖書館萬里分館／書展區', 25.17572457, 121.6439307, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館萬里分館】《閱讀書籤》4月主題書展「春風詩語」', `description`='【新北市立圖書館萬里分館】《閱讀書籤》4月主題書展「春風詩語」( 文化部要加)書展期間：3/22-4/22（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館萬里分館／書展區（新北市萬里區瑪鋉路221號4樓）聯絡電話：02-2492-4490#12書展簡介：2025新北詩歌節以「我和春天有個約會」為主題，結合春天的生命力與詩意之美，邀請民眾透過聽覺、視覺、嗅覺、味覺、觸覺，探索詩與五感的跨域體驗。活動包含年度詩選新書發表會與系列詩歌活動、講座等，讓詩歌融入日常，感受生活中的詩意與感動，於萬里分館辦理相關書展，歡迎到館借閱。', `organizer`='新北市立圖書館', `address`='新北市萬里區瑪鋉路221號4樓', `location`='新北市立圖書館萬里分館／書展區', `latitude`=25.17572457, `longitude`=121.6439307, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80beb26b3240c403d979c', '台灣魔術師聯盟劇團【魔幻奇舞歡樂秀】（免費觀賞）', '💖演出團體介紹：\n\n台灣魔術師聯盟劇團成立於民國九十八年，是由一群熱愛魔術表演的愛好者所組成，成員中除了有魔術師外、還有四川變臉、奇門遁甲、搞笑小丑、雜耍特技吞火、口技模仿腹語術、變裝秀、舞蹈…等表演者。本聯盟擁有許多表演經驗---無論是商業場、藝文活動、街頭表演、各縣市文化節、或是公益性活動、教學…演出場次一年超過百場！更常受邀於電視台演出，近年更是舉辦全國性的魔術大會師大型活動，備受好評！本聯盟是一個表演經歷豐富，且充滿娛樂性的表演藝術團體，每2年都會舉辦一場全國性魔術大會。\n\n🕒演出時間：114年3月23日(日) 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n蔡雅雯、蔣淑玲《戰翅舞魂》：中東肚皮舞\n黃瑞賢《西洋魔法秀》：變色手套、彩連三環、空盒出彩\n張慶州《歡樂互動秀》：猴子上樹氣球秀、出鈔秀、錢筒出錢\n方坤祺《驚奇雜耍秀》：轉盤子、轉鐵碗、轉瓷碗、轉中臉盆、嘴上轉盤、戴安全帽轉盤和互動\n范民豐《搞笑腹語秀》：腹語鳥+面具\n蔡雅雯、蔣淑玲《帶動跳》：阿帕茲\n方坤祺、蔡雅雯《大型幻術秀》：萬劍吉運\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50681', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台灣魔術師聯盟劇團【魔幻奇舞歡樂秀】（免費觀賞）', `description`='💖演出團體介紹：\n\n台灣魔術師聯盟劇團成立於民國九十八年，是由一群熱愛魔術表演的愛好者所組成，成員中除了有魔術師外、還有四川變臉、奇門遁甲、搞笑小丑、雜耍特技吞火、口技模仿腹語術、變裝秀、舞蹈…等表演者。本聯盟擁有許多表演經驗---無論是商業場、藝文活動、街頭表演、各縣市文化節、或是公益性活動、教學…演出場次一年超過百場！更常受邀於電視台演出，近年更是舉辦全國性的魔術大會師大型活動，備受好評！本聯盟是一個表演經歷豐富，且充滿娛樂性的表演藝術團體，每2年都會舉辦一場全國性魔術大會。\n\n🕒演出時間：114年3月23日(日) 16:00-17:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n蔡雅雯、蔣淑玲《戰翅舞魂》：中東肚皮舞\n黃瑞賢《西洋魔法秀》：變色手套、彩連三環、空盒出彩\n張慶州《歡樂互動秀》：猴子上樹氣球秀、出鈔秀、錢筒出錢\n方坤祺《驚奇雜耍秀》：轉盤子、轉鐵碗、轉瓷碗、轉中臉盆、嘴上轉盤、戴安全帽轉盤和互動\n范民豐《搞笑腹語秀》：腹語鳥+面具\n蔡雅雯、蔣淑玲《帶動跳》：阿帕茲\n方坤祺、蔡雅雯《大型幻術秀》：萬劍吉運\n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50681', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ca0b4426b32408680bea0e', '憑石礫生活-卑南遺址公園', ' 史前生活挑戰賽  \n開放報名，每個挑戰報名費：50元\n線上報名成功，並完成現場繳費者\n可獲得現場石礫磨製體驗１次(100元)\n\n挑戰1 構厲害裁縫店\n\n繡學號、修改西裝褲現代技能不容易\n史前裁縫店有夠厲害一起穿暖暖\n需3-5人組團報名（派１人報名即可）\n生存挑戰：敲樹皮、鑽孔、穿線\n比速度快，取前三名有獎\n建議三歲以上和家長親友共同參與\n\n挑戰2 雙人獸宅急便\n\n史前知識傳送宅急便，5題挑戰積分賽\n需2人一起參賽挑戰（派１人報名即可）\n生存挑戰：習得史前人的生活常識\n比正確性與速度，取前三名有獎\n建議三歲以上和家長親友共同參與\n但身高一致會比較輕鬆\n\n挑戰3 台9線釣魚場\n\n溪釣高手最艱難的挑戰，尋找史前釣魚王\n只要1人即可報名\n生存挑戰：魚卡子釣魚限時挑戰\n比數量多，取前三名有獎\n建議七歲以上可獨立挑戰，能靈活運用大小肌肉\n\n 以物易物公益市集 \n公益兌換物品及市集攤商近期公布，請密切關注！\n\n 史前小學堂 \n現場闖關、兌換禮物資訊近期公布，請密切關注！\n\n 百米定向體驗活動 \n活動進行方式近期公布，請密切關注！\n\n \n\n \n\n ', '國立臺灣史前文化博物館', '無資料', '2025-04-05 00:00:00', '2025-04-05 00:00:00', '無資料', 0, 0, '無資料', 'https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=50155', '[]') ON DUPLICATE KEY UPDATE `activity_name`='憑石礫生活-卑南遺址公園', `description`=' 史前生活挑戰賽  \n開放報名，每個挑戰報名費：50元\n線上報名成功，並完成現場繳費者\n可獲得現場石礫磨製體驗１次(100元)\n\n挑戰1 構厲害裁縫店\n\n繡學號、修改西裝褲現代技能不容易\n史前裁縫店有夠厲害一起穿暖暖\n需3-5人組團報名（派１人報名即可）\n生存挑戰：敲樹皮、鑽孔、穿線\n比速度快，取前三名有獎\n建議三歲以上和家長親友共同參與\n\n挑戰2 雙人獸宅急便\n\n史前知識傳送宅急便，5題挑戰積分賽\n需2人一起參賽挑戰（派１人報名即可）\n生存挑戰：習得史前人的生活常識\n比正確性與速度，取前三名有獎\n建議三歲以上和家長親友共同參與\n但身高一致會比較輕鬆\n\n挑戰3 台9線釣魚場\n\n溪釣高手最艱難的挑戰，尋找史前釣魚王\n只要1人即可報名\n生存挑戰：魚卡子釣魚限時挑戰\n比數量多，取前三名有獎\n建議七歲以上可獨立挑戰，能靈活運用大小肌肉\n\n 以物易物公益市集 \n公益兌換物品及市集攤商近期公布，請密切關注！\n\n 史前小學堂 \n現場闖關、兌換禮物資訊近期公布，請密切關注！\n\n 百米定向體驗活動 \n活動進行方式近期公布，請密切關注！\n\n \n\n \n\n ', `organizer`='國立臺灣史前文化博物館', `address`='無資料', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-05 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=50155', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d992c', '斑馬人演劇團【動物森林大賽】（免費觀賞）', '💖演出團體介紹：\n\n斑馬人演劇團創立自2016年，2018年正式於桃園市完成劇團登記，由一群科班出身、熱愛戲劇並身懷絕技的演員所組成，表演內容結合肢體喜劇、特技、雜耍、魔術、舞蹈與音樂節奏等元素，作品強調原創，更將創意埋於各個細節中，每次演出並帶入本團最強特色「互動」，不只拉近觀眾們之間得距離更兼具教化與娛樂，透過輕鬆詼諧的戲劇小品以及精彩的動作設計，帶給所有與我們相遇的觀眾，不一樣的創新表演方式，更是適合各個年齡層觀賞的演出。\n\n🕒演出時間：114年7月5日(六) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n阿龍、羊妹妹以及猴弟弟為了參加動物森林大賽，決定各自展現練習成果互相給予意見，沒想到竟起了衝突，讓原本感情十分良好的三人不歡而散，阿龍氣呼呼回到家中，龍媽媽見阿龍臉色鐵青而開口詢問，得知三個孩子都覺得自己的演出比較優秀所以起了口角，龍媽媽開導阿龍每個人的喜好各有不同，每個人的演出也總是各有優缺點，不要一直想著跟其他人分出高下，最重要的是自己是不是有進步，大家能不能團結一心，阿龍聽了媽媽的勸導後豁然開朗，解開心結，跟羊妹妹與猴弟弟三人和好，努力邁向動物森林大賽。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-07-05 00:00:00', '2025-07-05 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50702', '[]') ON DUPLICATE KEY UPDATE `activity_name`='斑馬人演劇團【動物森林大賽】（免費觀賞）', `description`='💖演出團體介紹：\n\n斑馬人演劇團創立自2016年，2018年正式於桃園市完成劇團登記，由一群科班出身、熱愛戲劇並身懷絕技的演員所組成，表演內容結合肢體喜劇、特技、雜耍、魔術、舞蹈與音樂節奏等元素，作品強調原創，更將創意埋於各個細節中，每次演出並帶入本團最強特色「互動」，不只拉近觀眾們之間得距離更兼具教化與娛樂，透過輕鬆詼諧的戲劇小品以及精彩的動作設計，帶給所有與我們相遇的觀眾，不一樣的創新表演方式，更是適合各個年齡層觀賞的演出。\n\n🕒演出時間：114年7月5日(六) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n阿龍、羊妹妹以及猴弟弟為了參加動物森林大賽，決定各自展現練習成果互相給予意見，沒想到竟起了衝突，讓原本感情十分良好的三人不歡而散，阿龍氣呼呼回到家中，龍媽媽見阿龍臉色鐵青而開口詢問，得知三個孩子都覺得自己的演出比較優秀所以起了口角，龍媽媽開導阿龍每個人的喜好各有不同，每個人的演出也總是各有優缺點，不要一直想著跟其他人分出高下，最重要的是自己是不是有進步，大家能不能團結一心，阿龍聽了媽媽的勸導後豁然開朗，解開心結，跟羊妹妹與猴弟弟三人和好，努力邁向動物森林大賽。\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-07-05 00:00:00', `end_date`='2025-07-05 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50702', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d992e', '魯夿旮文化樂團【洄游】（免費觀賞）', '💖演出團體介紹：\n\n來自花蓮萬榮鄉一群太魯閣族樂器演奏家。  長期深耕族群文化音樂，也致力教學傳統樂器。\n\n曾帶太魯閣傳統樂器至數個國家展演與交流。2020年開發新型獵首笛ABS製。2022年發行專輯《還能當多久原住民》。2023年受邀於臺灣世界音樂節演出。2024年辦理北流SUB LIVE《洄游》演唱會。2024年受邀美國關島演出與交流、花蓮太魯閣峽谷音樂節演出。\n\n🕒演出時間：114年7月13日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n此次主題洄游，透過生態的規律，魚類及其他海洋動物可能會因為覓食、繁殖或過冬 等原因而洄游，對比我們山上的泛紋面原住民族也因為生活、工作、覓食、繁衍與傳承等， 部分的族人都有從部落來到都市生活，再洄游到部落找文化，甚至定居在都市又或者將所 學、教育、文化重新帶回部落共享彼此的技藝與記憶等等...但又或許時間久了，年代久了， 孕育出更多代的孩子了，我們的文化、我們的血液、我們的記憶是否還是完整的原住民族 呢?又或者只剩下空殼了? \n\n音樂展演-以泛紋面族群傳統樂器貫穿全場演奏專輯音樂，結合現場樂團演出，為專 輯釋出蘊造能量。期望透過跨文化的音樂組合，讓更多人看見太魯閣族傳統樂器多元的可 能性，並吸引跨族群、跨年齡的群眾，有更多意願及興趣一同認識、學習文面族群傳統樂器。 \n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-07-13 00:00:00', '2025-07-13 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50704', '[]') ON DUPLICATE KEY UPDATE `activity_name`='魯夿旮文化樂團【洄游】（免費觀賞）', `description`='💖演出團體介紹：\n\n來自花蓮萬榮鄉一群太魯閣族樂器演奏家。  長期深耕族群文化音樂，也致力教學傳統樂器。\n\n曾帶太魯閣傳統樂器至數個國家展演與交流。2020年開發新型獵首笛ABS製。2022年發行專輯《還能當多久原住民》。2023年受邀於臺灣世界音樂節演出。2024年辦理北流SUB LIVE《洄游》演唱會。2024年受邀美國關島演出與交流、花蓮太魯閣峽谷音樂節演出。\n\n🕒演出時間：114年7月13日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n此次主題洄游，透過生態的規律，魚類及其他海洋動物可能會因為覓食、繁殖或過冬 等原因而洄游，對比我們山上的泛紋面原住民族也因為生活、工作、覓食、繁衍與傳承等， 部分的族人都有從部落來到都市生活，再洄游到部落找文化，甚至定居在都市又或者將所 學、教育、文化重新帶回部落共享彼此的技藝與記憶等等...但又或許時間久了，年代久了， 孕育出更多代的孩子了，我們的文化、我們的血液、我們的記憶是否還是完整的原住民族 呢?又或者只剩下空殼了? \n\n音樂展演-以泛紋面族群傳統樂器貫穿全場演奏專輯音樂，結合現場樂團演出，為專 輯釋出蘊造能量。期望透過跨文化的音樂組合，讓更多人看見太魯閣族傳統樂器多元的可 能性，並吸引跨族群、跨年齡的群眾，有更多意願及興趣一同認識、學習文面族群傳統樂器。 \n\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-07-13 00:00:00', `end_date`='2025-07-13 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50704', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d992f', '旋風樂團【療育旋風-歡喜樂融融】（免費觀賞）', '💖演出團體介紹：\n\n我們發現大多數的人心靈空虛需要「信仰」!\n心理(靈)受創，找不到出口的人不是傷害自己(自殺)就是傷害別人(言語、行為暴力)，製造許多社會問題。\n我們決定要主動出擊當拆彈者、掃雷者，發覺並搶救人群中被忽視的「隱性弱勢族群」!透過音樂的關懷傳遞與互動，為大家療癒身心，並且藉由團員的醫療專業以及身障感受，為大家帶來生命的力量!\n\n🕒演出時間：114年7月20日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n《演出名稱: 療癒旋風-歡喜樂融融》\n演出型態以樂團演奏與現場帶動為主軸~貼近你我的心!\n\n歌曲內容包括:\n★紓壓心情★\n1.Price tag\n2.海闊天空\n3.Kiss me\n4.Wish you were here\n\n★生命激勵★\n1.運轉人生\n2.你是我的眼\n3.天空沒有極限\n4.當\n\n★歡喜療癒★\n1.心花開\n2.甜蜜蜜 \n3.愛情限時批\n4.Firework\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-07-20 00:00:00', '2025-07-20 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50705', '[]') ON DUPLICATE KEY UPDATE `activity_name`='旋風樂團【療育旋風-歡喜樂融融】（免費觀賞）', `description`='💖演出團體介紹：\n\n我們發現大多數的人心靈空虛需要「信仰」!\n心理(靈)受創，找不到出口的人不是傷害自己(自殺)就是傷害別人(言語、行為暴力)，製造許多社會問題。\n我們決定要主動出擊當拆彈者、掃雷者，發覺並搶救人群中被忽視的「隱性弱勢族群」!透過音樂的關懷傳遞與互動，為大家療癒身心，並且藉由團員的醫療專業以及身障感受，為大家帶來生命的力量!\n\n🕒演出時間：114年7月20日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n《演出名稱: 療癒旋風-歡喜樂融融》\n演出型態以樂團演奏與現場帶動為主軸~貼近你我的心!\n\n歌曲內容包括:\n★紓壓心情★\n1.Price tag\n2.海闊天空\n3.Kiss me\n4.Wish you were here\n\n★生命激勵★\n1.運轉人生\n2.你是我的眼\n3.天空沒有極限\n4.當\n\n★歡喜療癒★\n1.心花開\n2.甜蜜蜜 \n3.愛情限時批\n4.Firework\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-07-20 00:00:00', `end_date`='2025-07-20 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50705', `image_url`='[]';
