INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67c8c2c726b32408680be9bd', '【高雄拍學院】幕前幕後嗑電影', '先是影迷，才是電影人！\r\n\r\n金獎大師 X 專業影人  一起嗑爆電影！\r\n\r\n金獎大師喜歡什麼樣的電影？從電影人眼中看到的電影是否別有風味？3月高雄拍學院邀請2位重量級大師，由專業影人引領大師對談，帶領大家從「導演」與「編劇」視角感受光影藝術的無限魅力。與創作者一同品讀電影世界的奇妙與深度！\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n講堂內容：\r\n\r\n▌03/16(日)13:30-18:00追逐電影的創作力\r\n\r\n講師：蕭雅全/金馬最佳劇情片《老狐狸》導演\r\n\r\n主持人：鄭秉泓/影評人\r\n\r\n \r\n\r\n▌03/30(日)13:30-18:00執筆寫執念：從影迷走入創作世界 \r\n\r\n講師：林冠慧/金鐘戲劇節目編劇獎《不良執念清除師》編劇\r\n\r\n主持人：鄭秉泓/影評人\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n課程資訊：\r\n\r\n單日票原價360元／影友優惠票288元（進場請出示有效影友卡）／高中生優惠票180元（進場請出示有效學生證）\r\n早鳥優惠套票限量開賣，完整參與2025高雄拍學院！購票請點此\r\n講堂地點：高雄市電影館三樓放映廳（自由入座）\r\n購票請至高雄市電影館1F服務台、內惟藝術中心服務台、年代售票網站（郵寄、便利商店取票）、四大超商機台\r\n每堂課皆須憑票入場，請務必妥善保存票券\r\n \r\n\r\n \r\n\r\n \r\n\r\n注意事項：\r\n\r\n每場課程均未供餐，請學員自行安排。\r\n本課程所有內容禁止私人錄音錄影、平面攝影等，及任何形式之轉載公開。\r\n購票後欲退出課程，請參考「電影館官網＞節目資訊＞票務資訊 票務Q&A＞Q3：請問如何退票？辦理─退票須於開課前30分鐘至高雄市電影館一樓售票處臨櫃辦理，並酌收票面金額10％之手續費。各場次開課後恕不接受退票。\r\n若遇不可抗力之因素（如：天災），電影館保留修改、變更、暫停、取消課程之權利。學員若無法配合，得根據變動之課程申請全額退費。\r\n如不可抗因素致演出取消，購票者同意依據主辦方制定退票規則辦理。\r\n電影館保有活動最終解釋權。', '高雄市電影館', '高雄市鹽埕區4鄰河西路10號', '2025-03-16 00:00:00', '2025-03-30 00:00:00', '高雄市電影館', 22.622671, 120.289122, '高中生優惠票+180;影友優惠票+288;單日票原價+360;早鳥套票+1750', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【高雄拍學院】幕前幕後嗑電影', `description`='先是影迷，才是電影人！\r\n\r\n金獎大師 X 專業影人  一起嗑爆電影！\r\n\r\n金獎大師喜歡什麼樣的電影？從電影人眼中看到的電影是否別有風味？3月高雄拍學院邀請2位重量級大師，由專業影人引領大師對談，帶領大家從「導演」與「編劇」視角感受光影藝術的無限魅力。與創作者一同品讀電影世界的奇妙與深度！\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n講堂內容：\r\n\r\n▌03/16(日)13:30-18:00追逐電影的創作力\r\n\r\n講師：蕭雅全/金馬最佳劇情片《老狐狸》導演\r\n\r\n主持人：鄭秉泓/影評人\r\n\r\n \r\n\r\n▌03/30(日)13:30-18:00執筆寫執念：從影迷走入創作世界 \r\n\r\n講師：林冠慧/金鐘戲劇節目編劇獎《不良執念清除師》編劇\r\n\r\n主持人：鄭秉泓/影評人\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n課程資訊：\r\n\r\n單日票原價360元／影友優惠票288元（進場請出示有效影友卡）／高中生優惠票180元（進場請出示有效學生證）\r\n早鳥優惠套票限量開賣，完整參與2025高雄拍學院！購票請點此\r\n講堂地點：高雄市電影館三樓放映廳（自由入座）\r\n購票請至高雄市電影館1F服務台、內惟藝術中心服務台、年代售票網站（郵寄、便利商店取票）、四大超商機台\r\n每堂課皆須憑票入場，請務必妥善保存票券\r\n \r\n\r\n \r\n\r\n \r\n\r\n注意事項：\r\n\r\n每場課程均未供餐，請學員自行安排。\r\n本課程所有內容禁止私人錄音錄影、平面攝影等，及任何形式之轉載公開。\r\n購票後欲退出課程，請參考「電影館官網＞節目資訊＞票務資訊 票務Q&A＞Q3：請問如何退票？辦理─退票須於開課前30分鐘至高雄市電影館一樓售票處臨櫃辦理，並酌收票面金額10％之手續費。各場次開課後恕不接受退票。\r\n若遇不可抗力之因素（如：天災），電影館保留修改、變更、暫停、取消課程之權利。學員若無法配合，得根據變動之課程申請全額退費。\r\n如不可抗因素致演出取消，購票者同意依據主辦方制定退票規則辦理。\r\n電影館保有活動最終解釋權。', `organizer`='高雄市電影館', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='高中生優惠票+180;影友優惠票+288;單日票原價+360;早鳥套票+1750', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d5713f8f15adefa04e0c7b', '舒曼：三首小提琴與鋼琴奏鳴曲', '舒曼的三首小提琴與鋼琴奏鳴曲出現在作曲家創作生涯晚期，多年來被認為是精神不穩定下的產物而受到嚴重的誤解與忽視。這三首作品展現出舒曼獨特的浪漫風格，它們不僅在貝多芬與布拉姆斯的同類作品中扮演著極其重要的傳承角色，更是古典室內樂曲目中不可多得的傑出作品。由台灣古典音樂界最受歡迎的兩位優秀演奏家合作演繹這場難得一見的全場舒曼小提琴奏鳴曲音樂會，勢必在仲夏之夜的台北掀起眾所企盼的藝文高潮。\r\n\r\n2025/06/01(日)19:30 國家兩廳院 演奏廳\r\n\r\n演出者：\r\n魏靖儀／小提琴  William Wei / Violin \r\n王佩瑤 / 鋼琴  Pei-Yao Wang / Piano\r\n\r\n演出曲目：\r\nA小調第一號小提琴奏鳴曲，作品一零五\r\nD小調第二號小提琴奏鳴曲，作品一二一\r\nA小調第三號小提琴奏鳴曲，遺作二十七\r\nSonata No. 1 in A Minor, Op. 105\r\nSonata No. 2 in D Minor, Op. 121\r\nSonata No. 3 in A Minor, WoO 27\r\n\r\nOPENTIX 售票系統 : https://www.opentix.life/event/1893862606409043968\r\n\r\n【優惠折扣】\r\n◆套票 _ 同時購買兩場8折、三場6折\r\n◆三張以上7折\r\n◆兩廳院會員9折優惠\r\n\r\n#文化幣', '財團法人台北獨奏家室內樂基金會', '臺北市臺北市中正區中山南路21-1號，信義路側', '2025-06-01 00:00:00', '2025-06-01 00:00:00', '國家兩廳院 演奏廳', 0, 0, 'NT$500、800、1000 (兩廳院 Opentix) \r\n\r\n【優惠折扣】\r\n◆套票 _ 同時購買兩場8折、三場6折\r\n◆三張以上7折\r\n◆兩廳院會員9折優惠\r\n#文化幣\r\n#套票', 'https://www.opentix.life/event/1893862606409043968', '[]') ON DUPLICATE KEY UPDATE `activity_name`='舒曼：三首小提琴與鋼琴奏鳴曲', `description`='舒曼的三首小提琴與鋼琴奏鳴曲出現在作曲家創作生涯晚期，多年來被認為是精神不穩定下的產物而受到嚴重的誤解與忽視。這三首作品展現出舒曼獨特的浪漫風格，它們不僅在貝多芬與布拉姆斯的同類作品中扮演著極其重要的傳承角色，更是古典室內樂曲目中不可多得的傑出作品。由台灣古典音樂界最受歡迎的兩位優秀演奏家合作演繹這場難得一見的全場舒曼小提琴奏鳴曲音樂會，勢必在仲夏之夜的台北掀起眾所企盼的藝文高潮。\r\n\r\n2025/06/01(日)19:30 國家兩廳院 演奏廳\r\n\r\n演出者：\r\n魏靖儀／小提琴  William Wei / Violin \r\n王佩瑤 / 鋼琴  Pei-Yao Wang / Piano\r\n\r\n演出曲目：\r\nA小調第一號小提琴奏鳴曲，作品一零五\r\nD小調第二號小提琴奏鳴曲，作品一二一\r\nA小調第三號小提琴奏鳴曲，遺作二十七\r\nSonata No. 1 in A Minor, Op. 105\r\nSonata No. 2 in D Minor, Op. 121\r\nSonata No. 3 in A Minor, WoO 27\r\n\r\nOPENTIX 售票系統 : https://www.opentix.life/event/1893862606409043968\r\n\r\n【優惠折扣】\r\n◆套票 _ 同時購買兩場8折、三場6折\r\n◆三張以上7折\r\n◆兩廳院會員9折優惠\r\n\r\n#文化幣', `organizer`='財團法人台北獨奏家室內樂基金會', `address`='臺北市臺北市中正區中山南路21-1號，信義路側', `start_date`='2025-06-01 00:00:00', `