INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d5df3b26b32408680becc8', '昱刀瘤形–李昱進雕刻藝術創作展（免費參觀）', '李昱進，藝界雅稱「阿進師」，來自屏東縣小琉球，師從學徒、匠師到廟宇大型整體設計規劃，期間曾因手傷而停止創作，而後從新形式藝術看到了木雕的重生與再現，他以樹瘤做為藝術創作主要形式表現，進而將木雕融入生活，是一位木雕創作的耕耘者與實踐者。\n\n本次展覽共有七個主題展區：「藝生維肖」、「神超形越」、「龍血鳳髓」、「獸豼南山」、「自然釋然」、「星想藝成」與「五行蟾蜍」，展出逾80件作品，可說是集李昱進木雕工法與風格最完整的一次個展，氣勢磅礡、巧妙生趣，展現其新舊作品在觀念與技術交融下產生的時代氛圍。\n\n \n\n \n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-03-28 00:00:00', '2025-04-21 00:00:00', '2展廳', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50753', '[]') ON DUPLICATE KEY UPDATE `activity_name`='昱刀瘤形–李昱進雕刻藝術創作展（免費參觀）', `description`='李昱進，藝界雅稱「阿進師」，來自屏東縣小琉球，師從學徒、匠師到廟宇大型整體設計規劃，期間曾因手傷而停止創作，而後從新形式藝術看到了木雕的重生與再現，他以樹瘤做為藝術創作主要形式表現，進而將木雕融入生活，是一位木雕創作的耕耘者與實踐者。\n\n本次展覽共有七個主題展區：「藝生維肖」、「神超形越」、「龍血鳳髓」、「獸豼南山」、「自然釋然」、「星想藝成」與「五行蟾蜍」，展出逾80件作品，可說是集李昱進木雕工法與風格最完整的一次個展，氣勢磅礡、巧妙生趣，展現其新舊作品在觀念與技術交融下產生的時代氛圍。\n\n \n\n \n\n \n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-03-28 00:00:00', `end_date`='2025-04-21 00:00:00', `location`='2展廳', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50753', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d5dfb326b32408680becc9', '2025傑優青少年打擊樂團年度音樂會《青春進行式》', '每一次敲擊，都是夢想的追尋；每一段旋律，都是感動的記憶。在青春的舞台上，盡情揮灑熱情，創造只屬於我們的節奏！我們是傑優青少年打擊樂團，青春進行式，等你一同來參與！', '財團法人擊樂文教基金會', '臺南市歸仁區信義南路78號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '歸仁文化中心', 22.94679469, 120.2930627, '全票400+--', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025傑優青少年打擊樂團年度音樂會《青春進行式》', `description`='每一次敲擊，都是夢想的追尋；每一段旋律，都是感動的記憶。在青春的舞台上，盡情揮灑熱情，創造只屬於我們的節奏！我們是傑優青少年打擊樂團，青春進行式，等你一同來參與！', `organizer`='財團法人擊樂文教基金會', `address`='臺南市歸仁區信義南路78號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='歸仁文化中心', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='全票400+--', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d5dfb326b32408680becca', '《看我、聽我》校園民歌公益音樂劇', '校園民歌的特質是歌詞通俗而真摯，曲調優美而樸質、節奏明朗而生動，結構簡短而自然，曲風反映社會的光明面及正向價值觀，帶領70年代音樂創作的風潮。本劇以一段溫馨感人的故事作為音樂劇情主軸，串入二十餘首熟悉動聽的民歌曲目，以混聲合唱團、演員重唱的多元方式演出。讓我們大家一起坐著時光機回到那一個純真、樸實的年代，一起重拾歌頌青春的美好時光。', '嘉義男聲合唱團', '臺南市歸仁區信義南路78號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '歸仁文化中心', 22.94679469, 120.2930627, '全票300、500+--', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《看我、聽我》校園民歌公益音樂劇', `description`='校園民歌的特質是歌詞通俗而真摯，曲調優美而樸質、節奏明朗而生動，結構簡短而自然，曲風反映社會的光明面及正向價值觀，帶領70年代音樂創作的風潮。本劇以一段溫馨感人的故事作為音樂劇情主軸，串入二十餘首熟悉動聽的民歌曲目，以混聲合唱團、演員重唱的多元方式演出。讓我們大家一起坐著時光機回到那一個純真、樸實的年代，一起重拾歌頌青春的美好時光。', `organizer`='嘉義男聲合唱團', `address`='臺南市歸仁區信義南路78號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='歸仁文化中心', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='全票300、500+--', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d5dfbb26b32408680beccb', '臺南大學＆臺北教育大學樂團/指揮大師班音樂會 ', '本場音樂會由國立臺南大學、臺北教育大學兩校音樂系聯合舉辦，並由財團法人義美藝術教育基金會贊助，邀請知名指揮家、小提琴家辛明峰擔任本次大師班講師，兩校將在短時間內進行密集排練及大師班活動，於28日演出大師班成果音樂會。', '國立臺南大學', '臺南市東區中華東路三段332號', '2025-03-28 00:00:00', '2025-03-28 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '免費索票入場+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南大學＆臺北教育大學樂團/指揮大師班音樂會 ', `description`='本場音樂會由國立臺南大學、臺北教育大學兩校音樂系聯合舉辦，並由財團法人義美藝術教育基金會贊助，邀請知名指揮家、小提琴家辛明峰擔任本次大師班講師，兩校將在短時間內進行密集排練及大師班活動，於28日演出大師班成果音樂會。', `organizer`='國立臺南大學', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='免費索票入場+--', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d5dfbb26b32408680beccc', '青少年扮戲計畫《Authentic》-基礎養成班', '基礎養成: 自3月22日（六）9:00至6月14日（六）17:00，7天， 帶領學員認識多元表演藝術，了解潛能增進實力，作為下階段創作依據。\r\n活動簡介》由臺灣青少年劇場推手呂毅新規劃，帶領專業導師，打造專屬年輕人的三階段戲劇培訓:\r\n基礎養成：認識多元表演藝術，了解潛能增進實力。\r\n進階實務：為有興趣參與之學員進行徵選，並實際體會劇團如何創作、製作。\r\n實戰演出：製作8月《Authentic》四場售票演出。', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-03-22 00:00:00', '2025-06-14 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '3+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='青少年扮戲計畫《Authentic》-基礎養成班', `description`='基礎養成: 自3月22日（六）9:00至6月14日（六）17:00，7天， 帶領學員認識多元表演藝術，了解潛能增進實力，作為下階段創作依據。\r\n活動簡介》由臺灣青少年劇場推手呂毅新規劃，帶領專業導師，打造專屬年輕人的三階段戲劇培訓:\r\n基礎養成：認識多元表演藝術，了解潛能增進實力。\r\n進階實務：為有興趣參與之學員進行徵選，並實際體會劇團如何創作、製作。\r\n實戰演出：製作8月《Authentic》四場售票演出。', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-06-14 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='3+--', `source_url`='無資料', `image_url`='[]';
