INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d5dfbc26b32408680becce', '偶戲故事屋~舊戲重溫．舊劇新看：嗨，黑漆漆', '偶戲故事屋~舊戲重溫．舊劇新看\r\n\r\n活動名稱》嗨，黑漆漆\r\n你怕不怕黑呢？\r\n你害怕床底下的怪物？衣櫃裡的怪物？還是地下室的黑漆漆？\r\n請鼓起勇氣，和勇敢的阿雷一起拜訪黑漆漆的路。\r\n活動時間》03/22(六) 15:00~15:30\r\n活動地點》臺南文化中心B1親子藝術空間\r\n說故事志工》Linda', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='偶戲故事屋~舊戲重溫．舊劇新看：嗨，黑漆漆', `description`='偶戲故事屋~舊戲重溫．舊劇新看\r\n\r\n活動名稱》嗨，黑漆漆\r\n你怕不怕黑呢？\r\n你害怕床底下的怪物？衣櫃裡的怪物？還是地下室的黑漆漆？\r\n請鼓起勇氣，和勇敢的阿雷一起拜訪黑漆漆的路。\r\n活動時間》03/22(六) 15:00~15:30\r\n活動地點》臺南文化中心B1親子藝術空間\r\n說故事志工》Linda', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d5dfc826b32408680beccf', '關廟區圖書館:英文繪本說故事--Plant the Tiny Seed', '關廟區圖書館每月精選英文繪本說故事活動-\r\n03月29日(星期六)上午10:30-11:30\r\n鈴鐺老師帶來繪本—【Plant the Tiny Seed】。\r\n不只是一本關於植物生長的美麗繪本，也是一本好玩的互動遊戲書！只要把書打開，種下小種子，壓一壓、點一點，創新又極具互動性，跟著小小種子體驗植物的生長歷程，感受生命的奇妙！活動免費參加,歡迎有興趣之家長及孩童一起來聽故事。', '臺南市關廟區圖書館', '臺南市關廟區文化街1號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '臺南市關廟區圖書館', 22.95577909, 120.3342821, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='關廟區圖書館:英文繪本說故事--Plant the Tiny Seed', `description`='關廟區圖書館每月精選英文繪本說故事活動-\r\n03月29日(星期六)上午10:30-11:30\r\n鈴鐺老師帶來繪本—【Plant the Tiny Seed】。\r\n不只是一本關於植物生長的美麗繪本，也是一本好玩的互動遊戲書！只要把書打開，種下小種子，壓一壓、點一點，創新又極具互動性，跟著小小種子體驗植物的生長歷程，感受生命的奇妙！活動免費參加,歡迎有興趣之家長及孩童一起來聽故事。', `organizer`='臺南市關廟區圖書館', `address`='臺南市關廟區文化街1號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺南市關廟區圖書館', `latitude`=22.95577909, `longitude`=120.3342821, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d74d6926b32408680becd1', '走出校園、文化to go─自然史與考古人類史地質千層派–省躬國小', '本路線以化石為核心，帶領學童了解臺灣史前時期人文特色及古生物化石形成，見證地球生命演化繁榮與衰落，並從中了解文物保存與化石挖掘保存對於科學研究之重要性，藉由化石翻模觀察化石細節，親身走進自然史與考古人類史的驚奇之旅。', '臺南市政府文化局', '臺南市新市區南科三路10號', '2025-03-28 00:00:00', '2025-03-28 00:00:00', '國立臺灣史前文化博物館南科考古館', 23.08319496, 120.2923941, '全票(一般民眾)。+80;團體票(團體參觀人數達20人（含）以上)+60;優待票+50', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='走出校園、文化to go─自然史與考古人類史地質千層派–省躬國小', `description`='本路線以化石為核心，帶領學童了解臺灣史前時期人文特色及古生物化石形成，見證地球生命演化繁榮與衰落，並從中了解文物保存與化石挖掘保存對於科學研究之重要性，藉由化石翻模觀察化石細節，親身走進自然史與考古人類史的驚奇之旅。', `organizer`='臺南市政府文化局', `address`='臺南市新市區南科三路10號', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='國立臺灣史前文化博物館南科考古館', `latitude`=23.08319496, `longitude`=120.2923941, `ticket_price`='全票(一般民眾)。+80;團體票(團體參觀人數達20人（含）以上)+60;優待票+50', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d74d7326b32408680becd2', '2025新營藝術季｜特選舞蹈演出', '2025新營藝術季｜特選舞蹈演出\r\n「不是要看懂，而是要懂看！」\r\n還停留在舞蹈好難懂？就讓我們邊跳邊說，以幽默輕鬆的角度，帶你一起練習看舞！（甚至編舞！）\r\n舞蹈的觀眾？尖叫聲在哪裡～《看舞練習》以舞蹈推廣為核心，透過說、演、跳，與觀眾共創當代舞蹈多元樣貌。', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-03-29 00:00:00', '2025-03-30 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025新營藝術季｜特選舞蹈演出', `description`='2025新營藝術季｜特選舞蹈演出\r\n「不是要看懂，而是要懂看！」\r\n還停留在舞蹈好難懂？就讓我們邊跳邊說，以幽默輕鬆的角度，帶你一起練習看舞！（甚至編舞！）\r\n舞蹈的觀眾？尖叫聲在哪裡～《看舞練習》以舞蹈推廣為核心，透過說、演、跳，與觀眾共創當代舞蹈多元樣貌。', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d74d7426b32408680becd3', '2025新營藝術季｜李竺芯Siri Lee', '2025新營藝術季｜李竺芯Siri Lee\r\n臺南出生，以多變創新的演唱風格，天馬行空又富含文化藝術感的創作，受到各方製作人欽點並與多位藝人合作，近於2024年總統就職國宴演出。2024年底推出的全台語創作專輯《Sui 水》。', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025新營藝術季｜李竺芯Siri Lee', `description`='2025新營藝術季｜李竺芯Siri Lee\r\n臺南出生，以多變創新的演唱風格，天馬行空又富含文化藝術感的創作，受到各方製作人欽點並與多位藝人合作，近於2024年總統就職國宴演出。2024年底推出的全台語創作專輯《Sui 水》。', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d74d7426b32408680becd4', '2025新營藝術季｜開幕演出《南瀛室內樂團》', '2025新營藝術季｜開幕演出《南瀛室內樂團》\r\n南瀛室內樂團常受邀各音樂活動演出，為相當活躍的新興團體。秉持對音樂的熱愛和推廣藝文的理念，鑒於弦樂優美精緻的特色，主以弦樂四重奏的形式，其多樣化的編制及不同曲風，介紹國際不同文化的音樂風格分享給臺灣的觀眾。', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025新營藝術季｜開幕演出《南瀛室內樂團》', `description`='2025新營藝術季｜開幕演出《南瀛室內樂團》\r\n南瀛室內樂團常受邀各音樂活動演出，為相當活躍的新興團體。秉持對音樂的熱愛和推廣藝文的理念，鑒於弦樂優美精緻的特色，主以弦樂四重奏的形式，其多樣化的編制及不同曲風，介紹國際不同文化的音樂風格分享給臺灣的觀眾。', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d74d7426b32408680becd5', '2025新營藝術季｜故事三輪車「小水滴的聚集」', '2025新營藝術季｜故事三輪車「小水滴的聚集」\r\n阮劇團自 2023年起，發展出一套「故事三輪車」的說故事展演行動，由劇團的行動員以說書人的形象，騎著三輪車到各地演出，透過輕鬆有趣的方式說故事，同時進行各種互動 戲，如肢體舞動、趣味問答等。', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-03-29 00:00:00', '2025-03-30 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025新營藝術季｜故事三輪車「小水滴的聚集」', `description`='2025新營藝術季｜故事三輪車「小水滴的聚集」\r\n阮劇團自 2023年起，發展出一套「故事三輪車」的說故事展演行動，由劇團的行動員以說書人的形象，騎著三輪車到各地演出，透過輕鬆有趣的方式說故事，同時進行各種互動 戲，如肢體舞動、趣味問答等。', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d74d7426b32408680becd6', '2025新營藝術季｜走讀「與水同行-記憶的凝結」', '2025新營藝術季｜走讀「與水同行-記憶的凝結」\r\n透過走讀演出模式結合阮劇團行動員發展出的特有藝術行動，引導觀眾走入新營的常民生活，欣賞現地演出與品嚐新營地方的獨特記憶。\r\n路線:新營文化中心-新營圓環（第一銀行）-臺南市市場處新營第一市場-新營第二市場-沈武德候祠', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025新營藝術季｜走讀「與水同行-記憶的凝結」', `description`='2025新營藝術季｜走讀「與水同行-記憶的凝結」\r\n透過走讀演出模式結合阮劇團行動員發展出的特有藝術行動，引導觀眾走入新營的常民生活，欣賞現地演出與品嚐新營地方的獨特記憶。\r\n路線:新營文化中心-新營圓環（第一銀行）-臺南市市場處新營第一市場-新營第二市場-沈武德候祠', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d74d7426b32408680becd7', '2025新營藝術季｜水水市集-文化創意藝品展', '2025新營藝術季｜《公館青少年》\r\n扶植在地文化創意產業，邀集市集攤商對於生活、藝品、文創的態度與見解，讓藝術季活動熱鬧與多元。', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-03-29 00:00:00', '2025-03-30 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025新營藝術季｜水水市集-文化創意藝品展', `description`='2025新營藝術季｜《公館青少年》\r\n扶植在地文化創意產業，邀集市集攤商對於生活、藝品、文創的態度與見解，讓藝術季活動熱鬧與多元。', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d74d7626b32408680becd8', '【性別符號】│淚滴卡卡', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│淚滴卡卡\r\n英文片│Lady CaCa\r\n\r\n導演│藍文希\r\n臺灣│2018│普遍級│劇情片│彩色│華語│88分鐘\r\n\r\n簡介\r\n卡卡的身體裡藏著異樣靈魂。在決定坦承生理性別的那晚，男友志哲卻向他求婚，卡卡卻怯懦轉身，深怕坦白將打破這得之不易的幸福。為了逃避往日情傷，母親藉著酒與藥麻痺自己，父親以保護為名將母親牢牢看管在身邊，愛與控制如同糾纏的線團….', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【性別符號】│淚滴卡卡', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│淚滴卡卡\r\n英文片│Lady CaCa\r\n\r\n導演│藍文希\r\n臺灣│2018│普遍級│劇情片│彩色│華語│88分鐘\r\n\r\n簡介\r\n卡卡的身體裡藏著異樣靈魂。在決定坦承生理性別的那晚，男友志哲卻向他求婚，卡卡卻怯懦轉身，深怕坦白將打破這得之不易的幸福。為了逃避往日情傷，母親藉著酒與藥麻痺自己，父親以保護為名將母親牢牢看管在身邊，愛與控制如同糾纏的線團….', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d74d7626b32408680becd9', '【性別符號】│津輕塗的女兒', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│津輕塗的女兒\r\n英文片│Tsugaru Lacquer Girl\r\n\r\n導演│鶴岡慧子\r\n日本│2023│普遍級│劇情類│彩色│日語│118分鐘\r\n\r\n簡介\r\n津輕塗職人青木清史郎與女兒美也子，在青森縣弘前市的老工坊工作。美也子高中畢業後，為維持家計在超市打工，同時幫忙家業。她的祖父是津輕塗名匠，父親繼承家業後經營困難，母親離家出走，哥哥也未繼承家業。某日，清史郎接獲大量訂單，美也子欣然幫忙，決心用漆器挑戰自我，家人漸漸被她的決心所感動...。', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-03-28 00:00:00', '2025-03-28 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【性別符號】│津輕塗的女兒', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│津輕塗的女兒\r\n英文片│Tsugaru Lacquer Girl\r\n\r\n導演│鶴岡慧子\r\n日本│2023│普遍級│劇情類│彩色│日語│118分鐘\r\n\r\n簡介\r\n津輕塗職人青木清史郎與女兒美也子，在青森縣弘前市的老工坊工作。美也子高中畢業後，為維持家計在超市打工，同時幫忙家業。她的祖父是津輕塗名匠，父親繼承家業後經營困難，母親離家出走，哥哥也未繼承家業。某日，清史郎接獲大量訂單，美也子欣然幫忙，決心用漆器挑戰自我，家人漸漸被她的決心所感動...。', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d74d7626b32408680becda', '【性別符號】│角落', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│角落\r\n英文片│Corner''s\r\n\r\n導演│周美玲、劉芸后\r\n臺灣│2001│普遍級│紀錄類│彩色│華語│55分鐘\r\n\r\n簡介\r\n「同志」是我們真正愉快的生命形態，因為貼近我們的內在本質，雖然有人假結婚，有人出了門便判若兩人﹔雖然不時與環境拉扯、對抗扭曲﹔但請不要擅自界定我們的幸福，找回真正的自己。 「出了這個門，就是另一個人。但並不是說，在這個門內，我們就安全了。」', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【性別符號】│角落', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│角落\r\n英文片│Corner''s\r\n\r\n導演│周美玲、劉芸后\r\n臺灣│2001│普遍級│紀錄類│彩色│華語│55分鐘\r\n\r\n簡介\r\n「同志」是我們真正愉快的生命形態，因為貼近我們的內在本質，雖然有人假結婚，有人出了門便判若兩人﹔雖然不時與環境拉扯、對抗扭曲﹔但請不要擅自界定我們的幸福，找回真正的自己。 「出了這個門，就是另一個人。但並不是說，在這個門內，我們就安全了。」', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
