INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8868d26b32408680bed1b', '桃園市立美術館2025暑期實習生申請', '桃園市立美術館2025暑期實習\n\n壹、請依本館《桃園市立美術館學生實習作業要點》申請\n\n貳、申請期間：114年4月15日9:00至113年5月15日17:00止\n\n參、面試時間：114年6月6日（五），如有變更會另行通知（經書面初審後，擇優面試）\n\n肆、實習期間：114年7月1日至113年8月29日\n\n伍、開放名額及條件如下:\n\n2025桃園市立美術館各組實習生需求表\n\n\n	\n		\n			\n			申請組別\n			\n			\n			需求人數\n			\n			\n			實習內容敘述\n			\n			\n			申請條件\n			\n			\n			組別輔導員/分機\n			\n		\n		\n			\n			展覽組\n			\n			\n			2人\n			\n			\n			\n				桃源美展、桃源國際藝術獎展覽事前籌備及相關業務\n				兒美館當期展覽展務、導覽活動、展品維護協助及相關業務。\n			\n			\n			\n			\n				博物館、策展、人文、設計、藝術等相關系所\n				具備word, excel, photoshop等基本繪圖與文書處理能力\n				具備Adobe系統等高階繪圖軟體操作技能者優先\n				中文能力佳、細心者優先，歡迎檢附書寫作品\n				具備英文書寫、會話溝通能力尤佳\n				申請實習2個月者優先\n				具備展場管理、卸佈展、導覽等經驗尤佳\n				大學（含在學）以上學歷，研究生尤佳\n			\n			\n			\n			(03)2868668\n\n			柯曉如 / 9005\n\n			熊　芃 / 9009\n\n			 \n\n			 \n			\n		\n		\n			\n			書藝館\n			\n			\n			2人\n			\n			\n			\n				橫山書法藝術館展覽相關業務\n				協助橫山書法藝術館教育推廣講座及活動\n				其他臨時美術設計、資料彙整等庶務事項\n			\n			\n			\n			\n				具從事藝文產業相關經驗者優先或曾就讀藝術、教育、設計、博物館學、社會科學等相關系所\n				具備Adobe系統等高階繪圖軟體操作技能者優先\n				具備英文書寫、會話溝通能力尤佳\n				申請實習2個月者優先\n			\n			\n			\n			(03)2876176\n			陳俋佐/＃101\n\n			巫伊婷/＃104\n			\n		\n		\n			\n			教推組\n			\n			\n			2人\n			\n			\n			\n				假日工作坊及夏令營活動\n				兒童藝術教育課程開發\n				其他教育推廣組相關業務\n			\n			\n			\n			\n				藝術、教育、設計、博物館學、人文或社會科學等相關系所或具藝文產業相關經驗者\n				喜歡親近人群，對兒童藝術教育、博物館工作有熱忱者\n				具備繪圖、影音剪輯等軟體操作技能者尤佳\n				具備英文書寫、會話溝通能力尤佳\n				申請實習2個月者優先\n			\n			\n			\n			(03)2868668\n			潘詩茜/＃8002\n\n			 \n			\n		\n	\n\n\n陸、報名資料繳交說明: 本次報名皆採取線上報名，相關文件請於報名時上傳系統', '桃園市立美術館', '320  桃園市中壢區高鐵南路二段90號', '2025-04-15 00:00:00', '2025-05-15 00:00:00', '桃園市兒童美術館', 24.97993803, 121.2147243, '無資料', 'https://event.culture.tw/mocweb/reg/TMOFA/Detail.init.ctr?actId=50011', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園市立美術館2025暑期實習生申請', `description`='桃園市立美術館2025暑期實習\n\n壹、請依本館《桃園市立美術館學生實習作業