INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8870526b32408680bed1c', '我心飛揚-達達畫會聯展', '       世界的紛擾，在2020出的疫情中被打斷了！世界的色彩如未構思的油畫布般的蒼白！空白的世界……。\r\n       在安靜中刷刷聲的筆調卻開啟了節奏與跳動，色彩慢慢填補空白的畫布，世界一筆一筆地慢慢被建構。外境靜悄悄、無聲無息，但內在的思慮與i想像卻自在、飛揚！我們不知何時可以看到外面的湛藍晴空，還有蔚藍的海洋，但我們可以隨時建構！\r\n       藝術給予人心的慰藉、希望，在於自然中的和諧與歡愉。自然的力量，撫慰人心，所以人類喜歡海洋、喜歡花朵、喜歡動物、愛田園風貌、愛山林綠蔭！這些題材是藝術當中備受恆久喜愛的類別，不管是創作者或欣賞者，都感受神性無所不在的愛，因為有愛，所以「我心飛揚」是此次展覽的核心價值，因藝術讓我們平衡生活的紛擾。本次展覽由「達達畫會」以油畫創作為主，創作者都是桃園市的藝術工作者。', '桃園市立圖書館', '桃園市龍潭區中正路210號', '2025-03-07 00:00:00', '2025-03-30 00:00:00', '桃園市立圖書館龍潭閱覽室', 24.85064954, 121.2117877, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='我心飛揚-達達畫會聯展', `description`='       世界的紛擾，在2020出的疫情中被打斷了！世界的色彩如未構思的油畫布般的蒼白！空白的世界……。\r\n       在安靜中刷刷聲的筆調卻開啟了節奏與跳動，色彩慢慢填補空白的畫布，世界一筆一筆地慢慢被建構。外境靜悄悄、無聲無息，但內在的思慮與i想像卻自在、飛揚！我們不知何時可以看到外面的湛藍晴空，還有蔚藍的海洋，但我們可以隨時建構！\r\n       藝術給予人心的慰藉、希望，在於自然中的和諧與歡愉。自然的力量，撫慰人心，所以人類喜歡海洋、喜歡花朵、喜歡動物、愛田園風貌、愛山林綠蔭！這些題材是藝術當中備受恆久喜愛的類別，不管是創作者或欣賞者，都感受神性無所不在的愛，因為有愛，所以「我心飛揚」是此次展覽的核心價值，因藝術讓我們平衡生活的紛擾。本次展覽由「達達畫會」以油畫創作為主，創作者都是桃園市的藝術工作者。', `organizer`='桃園市立圖書館', `address`='桃園市龍潭區中正路210號', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='桃園市立圖書館龍潭閱覽室', `latitude`=24.85064954, `longitude`=121.2117877, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8870926b32408680bed1d', '2025傑優青少年打擊樂團年度音樂會', '每一次敲擊，都是夢想的追尋；每一段旋律，都是感動的記憶。在青春的舞台上，盡情揮灑熱情，創造只屬於我們的節奏！我們是傑優青少年打擊樂團，青春進行式，等你一同來參與！', '財團法人擊樂文教基金會', '桃園市桃園區中正路1188號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '桃園展演中心', 25.00040024, 121.2996612, '票價+400', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025傑優青少年打擊樂團年度音樂會', `description`='每一次敲擊，都是夢想的追尋；每一段旋律，都是感動的記憶。在青春的舞台上，盡情揮灑熱情，創造只屬於我們的節奏！我們是傑優青少年打擊樂團，青春進行式，等你一同來參與！', `organizer`='財團法人擊樂文教基金會', `address`='桃園市桃園區中正路1188號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='桃園展演中心', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='票價+400', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8871026b32408680bed1e', '【新北市青少年圖書館】114年3月彩虹故事屋	', '【新北市青少年圖書館】3月彩虹故事屋\r\n\r\n歡迎家長們帶著學齡前及國小兒童一同到青少年圖書館聆聽說故事志工講故事。聽著說故事志工用著活潑的語調及豐富的肢體動作，吸引小朋友們的注意力，引起他們對閱讀的興趣，搭配故事的內容做手作、問答等活動，讓小朋友們感受過程中的樂趣，家長們跟著孩子一同體驗，增加親子間的溫馨互動。\r\n\r\n【中文說故事】\r\n03/08（六）15:00-16:00 /劉寶鳳\r\n 我真的真的很會畫畫\r\n\r\n03/29（六）15:00-16:00 /徐妤嘉\r\n秘密派對 \r\n\r\n【英文說故事】\r\n03/15（六）15:00-16:00 /黃蜀玉\r\nIllustrated stories from around the world--- A story from England \r\n\r\n備註：如有異動，以現場公告為準。', '新北市立圖書館總館', '新北市新店區安康路2段151號', '2025-03-08 00:00:00', '2025-03-29 00:00:00', '新北市青少年圖書館', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市青少年圖書館】114年3月彩虹故事屋	', `description`='【新北市青少年圖書館】3月彩虹故事屋\r\n\r\n歡迎家長們帶著學齡前及國小兒童一同到青少年圖書館聆聽說故事志工講故事。聽著說故事志工用著活潑的語調及豐富的肢體動作，吸引小朋友們的注意力，引起他們對閱讀的興趣，搭配故事的內容做手作、問答等活動，讓小朋友們感受過程中的樂趣，家長們跟著孩子一同體驗，增加親子間的溫馨互動。\r\n\r\n【中文說故事】\r\n03/08（六）15:00-16:00 /劉寶鳳\r\n 我真的真的很會畫畫\r\n\r\n03/29（六）15:00-16:00 /徐妤嘉\r\n秘密派對 \r\n\r\n【英文說故事】\r\n03/15（六）15:00-16:00 /黃蜀玉\r\nIllustrated stories from around the world--- A story from England \r\n\r\n備註：如有異動，以現場公告為準。', `organizer`='新北市立圖書館總館', `address`='新北市新店區安康路2段151號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='新北市青少年圖書館', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
