INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8871026b32408680bed20', '【新北市青少年圖書館】3月主題書展 - 「建築的世界」', '建築誕生自內心情感，渴望征服、渴求平靜、對於過去的念念不忘、對於理想的追尋，種種情懷，構築出建築的世界。', '新北市立圖書館總館', '新北市新店區安康路2段151號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市青少年圖書館', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市青少年圖書館】3月主題書展 - 「建築的世界」', `description`='建築誕生自內心情感，渴望征服、渴求平靜、對於過去的念念不忘、對於理想的追尋，種種情懷，構築出建築的世界。', `organizer`='新北市立圖書館總館', `address`='新北市新店區安康路2段151號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市青少年圖書館', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8871026b32408680bed21', '【新北市立圖書館新店柴埕圖書閱覽室】3月主題書展 - 「無羈．有機」', '從居住到體驗，從物質到思維。雖說建築多半是無機物的多重組合與堆砌，人們卻能漸漸的活用這些生硬、堅韌的建材，表達有機的概念及豐富的思想。\r\n本館精選古今中外以建築為主軸的館藏，涵蓋建築藝術、工程技術、設計理念與市場運作等多元面向，引領您探索一棟棟人造物背後豐富知識與文化魅力。歡迎讀者借閱書展藏，細細品味與發掘人們如何為無機形構灌注無限而鮮活生命。', '新北市立圖書館總館', '新北市新店區安民街79號3樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館新店柴埕圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店柴埕圖書閱覽室】3月主題書展 - 「無羈．有機」', `description`='從居住到體驗，從物質到思維。雖說建築多半是無機物的多重組合與堆砌，人們卻能漸漸的活用這些生硬、堅韌的建材，表達有機的概念及豐富的思想。\r\n本館精選古今中外以建築為主軸的館藏，涵蓋建築藝術、工程技術、設計理念與市場運作等多元面向，引領您探索一棟棟人造物背後豐富知識與文化魅力。歡迎讀者借閱書展藏，細細品味與發掘人們如何為無機形構灌注無限而鮮活生命。', `organizer`='新北市立圖書館總館', `address`='新北市新店區安民街79號3樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館新店柴埕圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8871026b32408680bed22', '【新北市立圖書館新店三民圖書閱覽室】3月主題書展 - 「城市的模樣」', '建築是一座城市的皮囊，涵容一整座城市的生命，餵養人類對美學的慾望，也應許我們追求文明的渴望。\r\n建築的歷史就是人類的歷史，而每一個空間都是一篇故事。它們為人類靜靜見證這片土地發生過什麼，又留下了什麼，替我們保留最美的物換星移，每磚每瓦都是吉光片羽。\r\n人類創造建築，建築乘載歷史，而文字與書本會帶領你繼續感受這些美好，或記取那些不該被遺忘的曾經。', '新北市立圖書館總館', '新北市新店區三民路20-2號2樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館新店三民圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店三民圖書閱覽室】3月主題書展 - 「城市的模樣」', `description`='建築是一座城市的皮囊，涵容一整座城市的生命，餵養人類對美學的慾望，也應許我們追求文明的渴望。\r\n建築的歷史就是人類的歷史，而每一個空間都是一篇故事。它們為人類靜靜見證這片土地發生過什麼，又留下了什麼，替我們保留最美的物換星移，每磚每瓦都是吉光片羽。\r\n人類創造建築，建築乘載歷史，而文字與書本會帶領你繼續感受這些美好，或記取那些不該被遺忘的曾經。', `organizer`='新北市立圖書館總館', `address`='新北市新店區三民路20-2號2樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館新店三民圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8871026b32408680bed23', '【新北市立圖書館新店中央圖書閱覽室】3月主題書展 - 「建築工藝」', '隨著技術的發展，建築的結構、功能、美觀及安全等要求之外，智慧化建築的產生及綠色環保建築的思維等，進一步提升了建築品質、效率和生活環境的友好性。', '新北市立圖書館總館', '新北市新店區中央五街60號2樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館新店中央圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店中央圖書閱覽室】3月主題書展 - 「建築工藝」', `description`='隨著技術的發展，建築的結構、功能、美觀及安全等要求之外，智慧化建築的產生及綠色環保建築的思維等，進一步提升了建築品質、效率和生活環境的友好性。', `organizer`='新北市立圖書館總館', `address`='新北市新店區中央五街60號2樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館新店中央圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8871026b32408680bed24', '【新北市立圖書館新店碧潭圖書閱覽室】3月主題書展 - 「築夢未來」', '在我們生活的世界裡，每一座建築都有著自己的故事，在設計圖的線條之中，每一筆都流淌著建築師的情感和靈魂，就讓我們一起來了解不同建築的誕生歷程與文化意義，還有探討未來建築的展望，想像明日的城市風貌。就讓我們一起進入書中世界，探索建築的精妙與在這之中蘊含的夢想吧!\r\n', '新北市立圖書館總館', '新北市新店區新店路207號4樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館新店碧潭圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店碧潭圖書閱覽室】3月主題書展 - 「築夢未來」', `description`='在我們生活的世界裡，每一座建築都有著自己的故事，在設計圖的線條之中，每一筆都流淌著建築師的情感和靈魂，就讓我們一起來了解不同建築的誕生歷程與文化意義，還有探討未來建築的展望，想像明日的城市風貌。就讓我們一起進入書中世界，探索建築的精妙與在這之中蘊含的夢想吧!\r\n', `organizer`='新北市立圖書館總館', `address`='新北市新店區新店路207號4樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館新店碧潭圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8871026b32408680bed25', '【新北市立圖書館新店福民圖書閱覽室】3月主題書展 - 「特色建築」', '在你我生活的這片土地上，有許多新舊交替的特色建築正在逐漸重生與活化中。曾經一度被世人給淡忘，在保留原有風味的同時，藉由嶄新的創意，它們正以比起過往更加閃耀的樣貌呈現在眾人的眼前。\r\n', '新北市立圖書館總館', '新北市新店區福園街8號3樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館新店福民圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店福民圖書閱覽室】3月主題書展 - 「特色建築」', `description`='在你我生活的這片土地上，有許多新舊交替的特色建築正在逐漸重生與活化中。曾經一度被世人給淡忘，在保留原有風味的同時，藉由嶄新的創意，它們正以比起過往更加閃耀的樣貌呈現在眾人的眼前。\r\n', `organizer`='新北市立圖書館總館', `address`='新北市新店區福園街8號3樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館新店福民圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8871026b32408680bed26', '花火瞬影－台藝金工創作聯展', '展覽日期：2025/03/13-3/30\r\n\r\n展覽地點：新北市藝文中心 第一展覽室 (板橋區莊敬路62號)\r\n\r\nØ  本展由臺藝大工藝設計金工組師長、研究生與校友共同展出，集結超過20位金工創作者之實用工藝、金屬雕塑物件、當代首飾三大類作品展示金工的多重內涵。透過實體展出與影音宣傳，期待觸動大眾對金工創作的認知與想像。', '國立臺灣藝術大學工藝設計學系', '新北市板橋區莊敬路62號', '2025-03-13 00:00:00', '2025-03-30 00:00:00', '新北市藝文中心', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='花火瞬影－台藝金工創作聯展', `description`='展覽日期：2025/03/13-3/30\r\n\r\n展覽地點：新北市藝文中心 第一展覽室 (板橋區莊敬路62號)\r\n\r\nØ  本展由臺藝大工藝設計金工組師長、研究生與校友共同展出，集結超過20位金工創作者之實用工藝、金屬雕塑物件、當代首飾三大類作品展示金工的多重內涵。透過實體展出與影音宣傳，期待觸動大眾對金工創作的認知與想像。', `organizer`='國立臺灣藝術大學工藝設計學系', `address`='新北市板橋區莊敬路62號', `start_date`='2025-03-13 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='新北市藝文中心', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8871026b32408680bed27', '國立彰化師範大學美術學系碩士班聯展－《滔滔》', '展覽日期：2025/03/13-3/30\r\n\r\n展覽地點：新北市藝文中心 第二展覽室 (板橋區莊敬路62號)\r\n\r\nØ  此檔展覽包含平面創作、裝置藝術，隨著藝術領域的擴張，在自身創作中不斷的成長，每位藝術家將展現自己擅長的創作方式給這個時代。', '國立彰化師範大學美術系', '新北市板橋區莊敬路62號', '2025-03-13 00:00:00', '2025-03-30 00:00:00', '新北市藝文中心', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國立彰化師範大學美術學系碩士班聯展－《滔滔》', `description`='展覽日期：2025/03/13-3/30\r\n\r\n展覽地點：新北市藝文中心 第二展覽室 (板橋區莊敬路62號)\r\n\r\nØ  此檔展覽包含平面創作、裝置藝術，隨著藝術領域的擴張，在自身創作中不斷的成長，每位藝術家將展現自己擅長的創作方式給這個時代。', `organizer`='國立彰化師範大學美術系', `address`='新北市板橋區莊敬路62號', `start_date`='2025-03-13 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='新北市藝文中心', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
