INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8871426b32408680bed34', '【大里分館】03/06-03/30 擬真鋁線節肢動物創作展覽', '展出陳聰賢老師創作的鋁線工藝，利用鋁線搭配彩珠，彎折出各種昆蟲、動物等造型，例如蠍子、螞蟻、蜘蛛等藝術創作，體會鋁線的活靈活現樣貌。\r\n作品提供者:陳聰賢老師', '臺中市立圖書館大里分館', '臺中市大里區中興路一段163號', '2025-03-06 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館大里分館', 24.09575742, 120.6926261, '無資料', 'https://reurl.cc/5DxXWV', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【大里分館】03/06-03/30 擬真鋁線節肢動物創作展覽', `description`='展出陳聰賢老師創作的鋁線工藝，利用鋁線搭配彩珠，彎折出各種昆蟲、動物等造型，例如蠍子、螞蟻、蜘蛛等藝術創作，體會鋁線的活靈活現樣貌。\r\n作品提供者:陳聰賢老師', `organizer`='臺中市立圖書館大里分館', `address`='臺中市大里區中興路一段163號', `start_date`='2025-03-06 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館大里分館', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://reurl.cc/5DxXWV', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8871c26b32408680bed35', '漆語非繁-許玄昌、廖家慶漆藝聯展', '生漆有最單純的元素,卻能以多樣性與多變性存在於各種形式中,在質樸、溫潤和華麗中恰如其分的達到平衡。對於漆工藝其中一項特質即是特別繁複的工序,作漆的人需按步就班,在等待中慢慢加飾、研磨、推光、讓漆藝獨特的魅力與美感展現在作品上。此次展出即是用漆的語言將漆工藝的材美、工巧、器雅實踐在作品上。', '臺中市豐原區公所', '臺中市豐原區水源路1-1號', '2025-02-20 00:00:00', '2025-04-20 00:00:00', '臺中市豐原漆藝館', 24.255087, 120.7457894, '無資料', 'https://www.facebook.com/share/p/1BEAUFvbHn/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='漆語非繁-許玄昌、廖家慶漆藝聯展', `description`='生漆有最單純的元素,卻能以多樣性與多變性存在於各種形式中,在質樸、溫潤和華麗中恰如其分的達到平衡。對於漆工藝其中一項特質即是特別繁複的工序,作漆的人需按步就班,在等待中慢慢加飾、研磨、推光、讓漆藝獨特的魅力與美感展現在作品上。此次展出即是用漆的語言將漆工藝的材美、工巧、器雅實踐在作品上。', `organizer`='臺中市豐原區公所', `address`='臺中市豐原區水源路1-1號', `start_date`='2025-02-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺中市豐原漆藝館', `latitude`=24.255087, `longitude`=120.7457894, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1BEAUFvbHn/', `image_url`='[]';
