INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8873226b32408680bed3b', '陳子彰四重奏', '由吉他手陳子彰、鼓手謝騏隆、貝斯手林后進、鋼琴手詹宗霖以四重奏編制，演奏全新推出的專輯曲目，\r\n帶領觀眾一起走進爵士吉他手子彰心中的風景，沈浸在那一天的光線、溫度、聲音，\r\n一起唱出 The Sea, The Sky, The You and I.', '社團法人台灣打里摺文化協會', '臺中市南屯區', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '南屯區（臺中市）=', 24.14165524, 120.6177379, '無資料', 'https://docs.google.com/forms/d/e/1FAIpQLSfgrSBWPVuyi2FQxyCYhqB6kpXtyjwLF_ajguup4kHNdw0-Hw/viewform', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陳子彰四重奏', `description`='由吉他手陳子彰、鼓手謝騏隆、貝斯手林后進、鋼琴手詹宗霖以四重奏編制，演奏全新推出的專輯曲目，\r\n帶領觀眾一起走進爵士吉他手子彰心中的風景，沈浸在那一天的光線、溫度、聲音，\r\n一起唱出 The Sea, The Sky, The You and I.', `organizer`='社團法人台灣打里摺文化協會', `address`='臺中市南屯區', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://docs.google.com/forms/d/e/1FAIpQLSfgrSBWPVuyi2FQxyCYhqB6kpXtyjwLF_ajguup4kHNdw0-Hw/viewform', `image_url`='[]';
