INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8873326b32408680bed3d', '家庭主婦的藝術新生活系列之二', '劉素玲「與墨相遇」個展:53歲時觀賞藝術展覽時即深深被畫作吸引，55歲退休後師承徐菊英老師習字畫，因非常熱愛書法及水墨畫，每日習字畫已成日常，為退休生活增添色彩，更透過藝術作品發掘自我內心對生命的熱愛，字畫悠然閒逸，展出作品計19幅歡迎大家蒞臨觀賞。', '臺中市東勢戶政事務所', '臺中市東勢區', '2025-03-03 00:00:00', '2025-04-30 00:00:00', '東勢區（臺中市）=', 24.24952637, 120.8401401, '無資料', 'https://www.hdongshi.taichung.gov.tw/3534955/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='家庭主婦的藝術新生活系列之二', `description`='劉素玲「與墨相遇」個展:53歲時觀賞藝術展覽時即深深被畫作吸引，55歲退休後師承徐菊英老師習字畫，因非常熱愛書法及水墨畫，每日習字畫已成日常，為退休生活增添色彩，更透過藝術作品發掘自我內心對生命的熱愛，字畫悠然閒逸，展出作品計19幅歡迎大家蒞臨觀賞。', `organizer`='臺中市東勢戶政事務所', `address`='臺中市東勢區', `start_date`='2025-03-03 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='東勢區（臺中市）=', `latitude`=24.24952637, `longitude`=120.8401401, `ticket_price`='無資料', `source_url`='https://www.hdongshi.taichung.gov.tw/3534955/post', `image_url`='[]';
