INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8873326b32408680bed40', '墨漾書翰', '目前擔任臺中市中華書畫協會第13屆理事長。劉家鑫老師則以佛像、書法詩詞為代表，目前任教於臺中市海線社區大學「墨漾書翰」書法教師，曾參與多次聯展及個展。此次與學生聯合展覽~歡迎前往觀賞', '臺中市立圖書館大甲分館', '臺中市大甲區雁門路172號', '2025-03-02 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館大甲分館', 24.37827161, 120.6357901, '無資料', 'https://reurl.cc/NbVxKn', '[]') ON DUPLICATE KEY UPDATE `activity_name`='墨漾書翰', `description`='目前擔任臺中市中華書畫協會第13屆理事長。劉家鑫老師則以佛像、書法詩詞為代表，目前任教於臺中市海線社區大學「墨漾書翰」書法教師，曾參與多次聯展及個展。此次與學生聯合展覽~歡迎前往觀賞', `organizer`='臺中市立圖書館大甲分館', `address`='臺中市大甲區雁門路172號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館大甲分館', `latitude`=24.37827161, `longitude`=120.6357901, `ticket_price`='無資料', `source_url`='https://reurl.cc/NbVxKn', `image_url`='[]';
