INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8873426b32408680bed4b', '臺中市立圖書館大肚分館-3月份主題書展', '大肚分館2025年3月主題書展⋯⋯⋯♡\r\n1F-學習挑戰\r\n無論是正在準備考試，還是希望提升思考深度\r\n每本書都是助力學習的最佳夥伴，幫助提升學習效率，擴展知識視野\r\n讓大肚分館與您一起迎接學習挑戰，突破自我極限！\r\n•┈┈┈┈┈┈୨୧┈┈┈┈┈┈•\r\n2F-世界那麼大\r\n世界那麼大好想到處去看看\r\n但是沒有時間的話該怎麼辦呢\r\n那就透過閱讀來環遊世界吧\r\n快來大肚分館借閱相關書籍 一起體會世界的美麗\r\n•┈┈┈┈┈┈୨୧┈┈┈┈┈┈•\r\n3F-「臺語冊．講乎咱聽」\r\n在這片充滿音韻與情感的土地上，臺語是我們心靈的共鳴，也是文化的根基。無論是傳統文學、現代創作，或是語言學的探索，這裡都有您期待的閱讀寶藏。\r\n展出期間：3/1(六)~3/30(日)\r\n展出地點：各樓層主題書展區', '臺中市立圖書館大肚分館', '臺中市大肚區大德六街 30 號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館大肚分館', 24.1558358, 120.5461103, '無資料', 'https://reurl.cc/G5W0MZ', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館大肚分館-3月份主題書展', `description`='大肚分館2025年3月主題書展⋯⋯⋯♡\r\n1F-學習挑戰\r\n無論是正在準備考試，還是希望提升思考深度\r\n每本書都是助力學習的最佳夥伴，幫助提升學習效率，擴展知識視野\r\n讓大肚分館與您一起迎接學習挑戰，突破自我極限！\r\n•┈┈┈┈┈┈୨୧┈┈┈┈┈┈•\r\n2F-世界那麼大\r\n世界那麼大好想到處去看看\r\n但是沒有時間的話該怎麼辦呢\r\n那就透過閱讀來環遊世界吧\r\n快來大肚分館借閱相關書籍 一起體會世界的美麗\r\n•┈┈┈┈┈┈୨୧┈┈┈┈┈┈•\r\n3F-「臺語冊．講乎咱聽」\r\n在這片充滿音韻與情感的土地上，臺語是我們心靈的共鳴，也是文化的根基。無論是傳統文學、現代創作，或是語言學的探索，這裡都有您期待的閱讀寶藏。\r\n展出期間：3/1(六)~3/30(日)\r\n展出地點：各樓層主題書展區', `organizer`='臺中市立圖書館大肚分館', `address`='臺中市大肚區大德六街 30 號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館大肚分館', `latitude`=24.1558358, `longitude`=120.5461103, `ticket_price`='無資料', `source_url`='https://reurl.cc/G5W0MZ', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8873426b32408680bed4c', '瘋媽祖：信仰同行-主題書展', '瘋媽祖：信仰同行\r\n跟隨媽祖一步一腳印，重新找回那份內心的平靜與希望，讓我們在繁忙中，得到源源不絕的力量！\r\n這不僅僅是一次宗教的朝聖之旅，也是心靈之旅，讓每一步都充滿希望與祝福！\r\n展期｜114/3/1-/3/14\r\n展區｜臺中市大肚區衛生所藝文展覽區', '臺中市立圖書館大肚分館', '臺中市大肚區', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '大肚區（臺中市）=', 24.14467504, 120.5543243, '無資料', 'https://reurl.cc/vpVN3a', '[]') ON DUPLICATE KEY UPDATE `activity_name`='瘋媽祖：信仰同行-主題書展', `description`='瘋媽祖：信仰同行\r\n跟隨媽祖一步一腳印，重新找回那份內心的平靜與希望，讓我們在繁忙中，得到源源不絕的力量！\r\n這不僅僅是一次宗教的朝聖之旅，也是心靈之旅，讓每一步都充滿希望與祝福！\r\n展期｜114/3/1-/3/14\r\n展區｜臺中市大肚區衛生所藝文展覽區', `organizer`='臺中市立圖書館大肚分館', `address`='臺中市大肚區', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='大肚區（臺中市）=', `latitude`=24.14467504, `longitude`=120.5543243, `ticket_price`='無資料', `source_url`='https://reurl.cc/vpVN3a', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8873526b32408680bed4d', '臺中市立圖書館大墩分館3月主題書展', '  臺中市立圖書館大墩分館3月主題書展\r\n2樓兒童書展區:「藝術也能這樣玩-動手創作與實踐」書展。藝術是什麼呢？藝術是一種「方式」，而不是目的。一起透過藝術來培養小朋友的「理解力」、「觀察力」與「創造力」大腦吧！\r\n3樓開架閱覽區:「臺語冊．講乎咱聽」書展。以台語歌謠為主,展出相關臺語、音樂書籍,讓母語透過書本與文字融入日常生活。\r\n3樓青少年閱覽區:青春不隨性~青少年性健康教育書展。青少年性教育旨在幫助年輕人正確了解自己的身體、性別發展、健康和關係等，對於青少年身心發展、健康選擇和人際關係都有積極的影響。\r\n\r\n ', '臺中市立圖書館大墩分館', '臺中市西區英才路600號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館大墩分館', 24.14391082, 120.6647579, '無資料', 'https://pse.is/78p8kv; https://pse.is/78p876; https://pse.is/78p7qh', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館大墩分館3月主題書展', `description`='  臺中市立圖書館大墩分館3月主題書展\r\n2樓兒童書展區:「藝術也能這樣玩-動手創作與實踐」書展。藝術是什麼呢？藝術是一種「方式」，而不是目的。一起透過藝術來培養小朋友的「理解力」、「觀察力」與「創造力」大腦吧！\r\n3樓開架閱覽區:「臺語冊．講乎咱聽」書展。以台語歌謠為主,展出相關臺語、音樂書籍,讓母語透過書本與文字融入日常生活。\r\n3樓青少年閱覽區:青春不隨性~青少年性健康教育書展。青少年性教育旨在幫助年輕人正確了解自己的身體、性別發展、健康和關係等，對於青少年身心發展、健康選擇和人際關係都有積極的影響。\r\n\r\n ', `organizer`='臺中市立圖書館大墩分館', `address`='臺中市西區英才路600號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館大墩分館', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://pse.is/78p8kv; https://pse.is/78p876; https://pse.is/78p7qh', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8873926b32408680bed4e', '新社分館 - 繪本說故事(3月5場)', '1.故事棒棒糖:故事志工講說圖畫繪本故事及各項故事延伸的DIY勞作~\r\n2.石岡親子館說故事:本活動專為0-3歲學齡前兒童設計，由石岡親子館老師以繪本圖晝書及遊戲.律動教育為主題與親子做互動,歡迎大手牽小手,一起來參加~\r\n3.「兒童文學神奇之旅」-陶子老師說故事:透過兒童文學,提早幫孩子建立其各個領域的人文素養--(何季陶老師)\r\n安東尼布朗、李奧李歐尼、長谷川義史、吉竹伸介、岩村和朗…等知名作家系列', '臺中市立圖書館新社分館', '臺中市新社區社街四段1巷1號', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '臺中市立圖書館新社分館', 24.17769289, 120.8313228, '無資料', 'https://reurl.cc/lN3RKA；https://reurl.cc/qnMgen；https://reurl.cc/lN3R6q', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新社分館 - 繪本說故事(3月5場)', `description`='1.故事棒棒糖:故事志工講說圖畫繪本故事及各項故事延伸的DIY勞作~\r\n2.石岡親子館說故事:本活動專為0-3歲學齡前兒童設計，由石岡親子館老師以繪本圖晝書及遊戲.律動教育為主題與親子做互動,歡迎大手牽小手,一起來參加~\r\n3.「兒童文學神奇之旅」-陶子老師說故事:透過兒童文學,提早幫孩子建立其各個領域的人文素養--(何季陶老師)\r\n安東尼布朗、李奧李歐尼、長谷川義史、吉竹伸介、岩村和朗…等知名作家系列', `organizer`='臺中市立圖書館新社分館', `address`='臺中市新社區社街四段1巷1號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市立圖書館新社分館', `latitude`=24.17769289, `longitude`=120.8313228, `ticket_price`='無資料', `source_url`='https://reurl.cc/lN3RKA；https://reurl.cc/qnMgen；https://reurl.cc/lN3R6q', `image_url`='[]';
