INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8874226b32408680bed62', '2025臺中媽祖國際觀光文化節─大甲鎮瀾宮周邊演藝活動(起駕戲暨觀禮臺)', '---起駕戲---\r\n時間：114年3月27日(星期四)晚上7時起\r\n地點：大甲區蔣公路與育德路口\r\n演出團隊：蘭陽戲劇團\r\n今年配合媽祖遶境和農曆3月媽祖誕辰，3月27日晚上7時在大甲區蔣公路及育德路口演出「起駕戲」，邀請秉持保存傳統、研究創新理念，成立逾三十載的「蘭陽戲劇團」演出《鐵面情》，講述欽差吳振坤鐵面無私、大義滅親的故事，演員將藉由流暢的身段與專業唱腔，帶來強烈視、聽覺效果以外，更將忠、奸、義、理娓娓道盡，劇情高潮迭起，作為媽祖遶境進香前熱場表演獻藝，歡迎民眾一同共賞精彩戲劇演出。\r\n\r\n---觀禮臺---\r\n時間：114年4月4日(星期五)晚上6時起\r\n地點：大甲區中山路與經國路口\r\n演出團隊：妙璇舞蹈團、薪韻文化藝術團、海洋家族及多組街頭藝人如國寶、林肯、魔術南、潤潁、李泓霖、林源昇等優質演藝團隊\r\n配合為期9天8夜的大甲媽祖遶境，4月4日晚上6時在大甲區中山路與經國路口也將舉辦「觀禮臺」活動，由多組優質演藝團隊，帶來一連串音樂、舞蹈、魔術、川劇變臉、花式扯鈴等眾多精采表演。當日晚上10時45分媽祖起駕前，也將邀請民俗專家林茂賢副教授搭配李璇，介紹媽祖起駕進香的傳統科儀和藝陣文化，在傳統宗教儀式的基礎上，深入探討在地文化價值。', '臺中市政府文化局', '臺中市大甲區', '2025-03-27 00:00:00', '2025-04-04 00:00:00', '大甲區（臺中市）=', 24.37827161, 120.6357901, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺中媽祖國際觀光文化節─大甲鎮瀾宮周邊演藝活動(起駕戲暨觀禮臺)', `description`='---起駕戲---\r\n時間：114年3月27日(星期四)晚上7時起\r\n地點：大甲區蔣公路與育德路口\r\n演出團隊：蘭陽戲劇團\r\n今年配合媽祖遶境和農曆3月媽祖誕辰，3月27日晚上7時在大甲區蔣公路及育德路口演出「起駕戲」，邀請秉持保存傳統、研究創新理念，成立逾三十載的「蘭陽戲劇團」演出《鐵面情》，講述欽差吳振坤鐵面無私、大義滅親的故事，演員將藉由流暢的身段與專業唱腔，帶來強烈視、聽覺效果以外，更將忠、奸、義、理娓娓道盡，劇情高潮迭起，作為媽祖遶境進香前熱場表演獻藝，歡迎民眾一同共賞精彩戲劇演出。\r\n\r\n---觀禮臺---\r\n時間：114年4月4日(星期五)晚上6時起\r\n地點：大甲區中山路與經國路口\r\n演出團隊：妙璇舞蹈團、薪韻文化藝術團、海洋家族及多組街頭藝人如國寶、林肯、魔術南、潤潁、李泓霖、林源昇等優質演藝團隊\r\n配合為期9天8夜的大甲媽祖遶境，4月4日晚上6時在大甲區中山路與經國路口也將舉辦「觀禮臺」活動，由多組優質演藝團隊，帶來一連串音樂、舞蹈、魔術、川劇變臉、花式扯鈴等眾多精采表演。當日晚上10時45分媽祖起駕前，也將邀請民俗專家林茂賢副教授搭配李璇，介紹媽祖起駕進香的傳統科儀和藝陣文化，在傳統宗教儀式的基礎上，深入探討在地文化價值。', `organizer`='臺中市政府文化局', `address`='臺中市大甲區', `start_date`='2025-03-27 00:00:00', `end_date`='2025-04-04 00:00:00', `location`='大甲區（臺中市）=', `latitude`=24.37827161, `longitude`=120.6357901, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8874226b32408680bed63', '《日常之歌》', '▍活動簡介｜\r\n\r\n在此製作中希望呈現劇中的日常平靜之下藏著多少波瀾，去放大、放慢這些生活的節點，讓觀者看見細節中隱藏的煩惱與抉擇。我們的生活正是因為這些節點而有所變化，對於這些細節過於習以為常時，我們將忽略自己真正在意之事，心之所向將被盲目的忽視。希望能透過劇中人（時芬）感知、看見、探究自我逃避之事的過程，讓觀者能理解到這件事：感知生活的細節，看見日常之殤，才能謳歌日常。\r\n\r\n▍劇團介紹｜\r\n\r\n共舞劇集 「生命中太多情緒肆意地橫衝直撞，那就與他們共舞吧。不再失序，也不再被控制，就與情緒協調於生命之中，與之共舞於這複雜的世界之中。」\r\n\r\n本劇團於2023年創立，2024年5月出品一號作品《Dear God》。在劇團理念之下，尋覓劇本及建構文字，以戲劇集合面對情緒、創傷的處方，集合觀眾的共感，讓觀者的思緒與舞台上的演繹共舞。\r\n\r\n主辦協辦贊助單位：蕾亞專業彩妝、財團法人高雄市磐石文化藝術基金會、黃香菽議員、保力達\r\n\r\n▍執行團隊｜\r\n\r\n導 演｜陳宇恩\r\n舞台監督｜陳靜燕\r\n燈光設計｜邱筠淇\r\n舞台設計｜邱鉯崴\r\n服髮設計｜陳詩頤\r\n平面暨文案設計｜林子晅\r\n《演員名單》\r\n陳姿蓉 飾演時芬\r\n杜 威 飾演子青\r\n邱佩淳 飾演時芬母親\r\n\r\n▍展覽日期｜2025.04.25(五) ~ 2025.04.27(日)13:30、16:30\r\n▍展覽地點｜新浜碼頭藝術空間\r\n▍空間贊助單位｜國藝會\r\n▍新浜行政｜陳羚溱、吳宛倫\r\n▍實習生｜孔媛、陳咨蓉', '新浜碼頭藝術空間', '高雄市鹽埕區015鄰大勇路64號2樓', '2025-04-25 00:00:00', '2025-04-27 00:00:00', '新浜碼頭藝術空間', 22.6228436, 120.2835667, '學生票+330;全票+350;贊助票+500', 'https://sinpink.com/2025/03/15/%e6%97%a5%e5%b8%b8%e4%b9%8b%e6%ad%8c/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《日常之歌》', `description`='▍活動簡介｜\r\n\r\n在此製作中希望呈現劇中的日常平靜之下藏著多少波瀾，去放大、放慢這些生活的節點，讓觀者看見細節中隱藏的煩惱與抉擇。我們的生活正是因為這些節點而有所變化，對於這些細節過於習以為常時，我們將忽略自己真正在意之事，心之所向將被盲目的忽視。希望能透過劇中人（時芬）感知、看見、探究自我逃避之事的過程，讓觀者能理解到這件事：感知生活的細節，看見日常之殤，才能謳歌日常。\r\n\r\n▍劇團介紹｜\r\n\r\n共舞劇集 「生命中太多情緒肆意地橫衝直撞，那就與他們共舞吧。不再失序，也不再被控制，就與情緒協調於生命之中，與之共舞於這複雜的世界之中。」\r\n\r\n本劇團於2023年創立，2024年5月出品一號作品《Dear God》。在劇團理念之下，尋覓劇本及建構文字，以戲劇集合面對情緒、創傷的處方，集合觀眾的共感，讓觀者的思緒與舞台上的演繹共舞。\r\n\r\n主辦協辦贊助單位：蕾亞專業彩妝、財團法人高雄市磐石文化藝術基金會、黃香菽議員、保力達\r\n\r\n▍執行團隊｜\r\n\r\n導 演｜陳宇恩\r\n舞台監督｜陳靜燕\r\n燈光設計｜邱筠淇\r\n舞台設計｜邱鉯崴\r\n服髮設計｜陳詩頤\r\n平面暨文案設計｜林子晅\r\n《演員名單》\r\n陳姿蓉 飾演時芬\r\n杜 威 飾演子青\r\n邱佩淳 飾演時芬母親\r\n\r\n▍展覽日期｜2025.04.25(五) ~ 2025.04.27(日)13:30、16:30\r\n▍展覽地點｜新浜碼頭藝術空間\r\n▍空間贊助單位｜國藝會\r\n▍新浜行政｜陳羚溱、吳宛倫\r\n▍實習生｜孔媛、陳咨蓉', `organizer`='新浜碼頭藝術空間', `address`='高雄市鹽埕區015鄰大勇路64號2樓', `start_date`='2025-04-25 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='新浜碼頭藝術空間', `latitude`=22.6228436, `longitude`=120.2835667, `ticket_price`='學生票+330;全票+350;贊助票+500', `source_url`='https://sinpink.com/2025/03/15/%e6%97%a5%e5%b8%b8%e4%b9%8b%e6%ad%8c/', `image_url`='[]';
