INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8874226b32408680bed65', '幼幼學齡主題繪本書展', '家有學齡前的小朋友，推薦爸爸媽媽挑幾本立體書\r\n\r\n說故事翻開立體書小朋友都會超驚喜', '高雄市立圖書館總館', '高雄市鳥松區18鄰大仁北路10號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '高雄市立圖書館鳥松分館', 22.6637985, 120.3622511, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='幼幼學齡主題繪本書展', `description`='家有學齡前的小朋友，推薦爸爸媽媽挑幾本立體書\r\n\r\n說故事翻開立體書小朋友都會超驚喜', `organizer`='高雄市立圖書館總館', `address`='高雄市鳥松區18鄰大仁北路10號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市立圖書館鳥松分館', `latitude`=22.6637985, `longitude`=120.3622511, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
