INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('66f1c82026b3241dc43a8310', '2025風動室內樂團《無限》電影配樂音樂會', '無資料', '無資料', '臺南市東區中華東路三段332號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺南文化中心演藝廳', 24.9582226, 121.2275687, '無資料', 'https://www.opentix.life/program/1834105184182878209', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025風動室內樂團《無限》電影配樂音樂會', `description`='無資料', `organizer`='無資料', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺南文化中心演藝廳', `latitude`=24.9582226, `longitude`=121.2275687, `ticket_price`='無資料', `source_url`='https://www.opentix.life/program/1834105184182878209', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d572598f15adefa04e0c7c', '獨一無二 - 舒曼的奇幻世界', '舒曼晚期創作了一些專為特定樂器而寫的室內樂小品，它們每一首都具有獨特的風味，以夢幻般的色彩、美妙動人的旋律，帶著我們進入作曲家充滿想像力的奇幻世界。這些作品常常以不同樂器版本出現在音樂會中，深受眾多演奏家及聽眾喜愛。由台灣傑出鋼琴家盧易之和他優秀的器樂家朋友們，以作曲家原定樂器為我們演繹這些溫馨而動人的作品，讓我們一同見證舒曼獨一無二的創作才華，以及他色彩繽紛的異想世界。\r\n\r\n2025/06/20(五)19:30 國家兩廳院 演奏廳\r\n\r\n演出者：\r\n盧易之／鋼琴  Yi-Chih Lu／Piano\r\n蔡弦修／中提琴  Hsien-Hsiu Tsai／Viola\r\n連亦先／大提琴  Yi-Shien Lien／Cello\r\n李珮琪／雙簧管  Pei-Chi Lee／Oboe\r\n賴俊諺／單簧管  Chun-Yen Lai／Clarinet\r\n劉宜欣／法國號  Yi-Hsin Liu／Horn\r\n\r\n演出曲目：\r\nAdagio and Allegro for Horn and Piano, Op. 70\r\nFantasy Pieces for Clarinet and Piano, Op. 73\r\nThree Romances for Oboe and Piano, Op. 94\r\nFive Pieces in Folk Style for Cello and Piano, Op. 102\r\nFairy Tale Pictures for Viola and Piano, Op. 113\r\nFairy Tale Narrations for Clarinet, Viola and Piano, Op. 132\r\n\r\nOPENTIX 售票系統 : https://www.opentix.life/event/1897201058618073089\r\n', '財團法人台北獨奏家室內樂基金會', '臺北市臺北市中正區中山南路21-1號，信義路側', '2025-06-20 00:00:00', '2025-06-20 00:00:00', '國家兩廳院 演奏廳', 0, 0, 'NT$500、800、1000 (兩廳院 Opentix) \r\n\r\n【優惠折扣】\r\n◆套票 _ 同時購買兩場8折、三場6折\r\n◆三張以上7折\r\n◆兩廳院會員9折優惠\r\n#文化幣\r\n#套票\r\n\r\n', 'https://www.opentix.life/event/1897201058618073089', '[]') ON DUPLICATE KEY UPDATE `activity_name`='獨一無二 - 舒曼的奇幻世界', `description`='舒曼晚期創作了一些專為特定樂器而寫的室內樂小品，它們每一首都具有獨特的風味，以夢幻般的色彩、美妙動人的旋律，帶著我們進入作曲家充滿想像力的奇幻世界。這些作品常常以不同樂器版本出現在音樂會中，深受眾多演奏家及聽眾喜愛。由台灣傑出鋼琴家盧易之和他優秀的器樂家朋友們，以作曲家原定樂器為我們演繹這些溫馨而動人的作品，讓我們一同見證舒曼獨一無二的創作才華，以及他色彩繽紛的異想世界。\r\n\r\n2025/06/20(五)19:30 國家兩廳院 演奏廳\r\n\r\n演出者：\r\n盧易之／鋼琴  Yi-Chih Lu／Piano\r\n蔡弦修／中提琴  Hsien-Hsiu Tsai／Viola\r\n連亦先／大提琴  Yi-Shien Lien／Cello\r\n李珮琪／雙簧管  Pei-Chi Lee／Oboe\r\n賴俊諺／單簧管  Chun-Yen Lai／Clarinet\r\n劉宜欣／法國號  Yi-Hsin Liu／Horn\r\n\r\n演出曲目：\r\nAdagio and Allegro for Horn and Piano, Op. 70\r\nFantasy Pieces for Clarinet and Piano, Op. 73\r\nThree Romances for Oboe and Piano, Op. 94\r\nFive Pieces in Folk Style for Cello and Piano, Op. 102\r\nFairy Tale Pictures for Viola and Piano, Op. 113\r\nFairy Tale Narrations for Clarinet, Viola and Piano, Op. 132\r\n\r\nOPENTIX 售票系統 : https://www.opentix.life/event/1897201058618073089\r\n', `organizer`='財團法人台北獨奏家室內樂基金會', `address`='臺北市臺北市中正區中山南路21-1號，信義路側', `start_date`='2025-06-20 00:00:00', `end_date`='2025-06-20 00:00:00', `location`='國家兩廳院 演奏廳', `latitude`=0, `longitude`=0, `ticket_price`='NT$500、800、1000 (兩廳院 Opentix) \r\n\r\n【優惠折扣】\r\n◆套票 _ 同時購買兩場8折、三場6折\r\n◆三張以上7折\r\n◆兩廳院會員9折優惠\r\n#文化幣\r\n#套票\r\n\r\n', `source_url`='https://www.opentix.life/event/1897201058618073089', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8868b26b32408680bed1a', '走讀國父史蹟與多元族群建築文化活動', '本活動以孫中山先生的史蹟、現代建築、多元族群文化建築為核心，透過走讀導覽帶領學員探索國父思想在台灣的具體展現。自4月26日起至7月26日，預計於台北、台中、台南、台東舉辦10場活動，邀請學者專家及文史工作者進行導覽，解析建築與歷史的連結，並探討國父思想的當代意義。\n\n \n\n講師群（依照姓名筆畫順序排列）：\n\n\n張廣榮  大巴六九部落意見領袖\n\n游筱嵩  東海大學文化資產專案人員、台灣戰後建築導覽培訓講師 \n\n徐明松  建築史學者、銘傳大學建築系助理教授\n\n高宏奕  台灣義築協會花東專案人員\n\n黃瑋庭  中原大學設計學博士生、地景建築系兼任講師\n\n劉志鴻  台灣戰後建築導覽培訓講師\n\n鍾文博  國立國父紀念館研究員\n\n賴仕堯  台大建築與城鄉研究所兼任助理教授\n\n\n \n\n走讀活動場次：\n\n\n	\n	路徑一：國父革命起點與台灣民主記憶之路——台北中正萬華\n	\n\n\n帶領學員踏尋孫中山先生的革命足跡，探索其在台灣的活動如何影響歷史發展，並與台灣民主進程相互交織。行程從逸仙公園與國父史蹟館（梅屋敷）出發，這裡是國父在台策劃革命的重要據點，學員將參訪國父銅像與紀念設施，回顧其革命歷程。接著前往二二八和平公園，對照國父提倡的「民權」理念，探討台灣民主發展與歷史轉折。隨後參訪中山堂，這座建築見證了台灣光復典禮，承載著國父「民族獨立」的理想與戰後政治變遷的歷史。最後抵達興中會台灣分會舊址（長沙街），這是國父在台灣建立的革命組織，象徵其在亞洲推動革命的布局，為本次走讀畫下歷史性的總結。透過這次走讀，學員將串聯革命與民主的歷史脈絡，親身感受台灣如何從革命理想到現代民主發展。\n\n（一）走讀時間：114 年 4 月 26 日（六），14：00-17：00\n\n（二）集合地點/時間：逸仙公園國父史蹟館 / 13：45\n\n（三）導覽者：國立國父紀念館研究員 鍾文博\n\n（四）路線：逸仙公園國父史蹟館＞二二八和平公園＞中山堂＞西門紅樓＞興中會台灣分會＞解散【台北】\n\n**交通自理。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑二：現代建築與國家願景巡禮——台北中正大安\n\n\n帶領學員走訪台北，探索王大閎的建築作品，並思考其設計理念如何與國父孫中山先生的現代化願景相呼應。王大閎是台灣現代建築的重要推手，其作品結合國際現代主義與東方文化精神，體現國父「融合中西、推動現代化」的思想。此次行程將參訪亞洲水泥大樓，這座建築為台灣首座帷幕牆設計的大樓，象徵著科技與建築的進步；外交部大樓，其設計不僅展現國際視野，也呼應國父強調外交自主的理念；最後走訪台大舊法律學院圖書館（徐州路），作為培育法律人才的重要基地，呼應國父對於「民權」的重視。透過專業導覽，我們將探索建築如何承載時代使命，並思考國父思想在現代社會中的延續。\n\n（一）走讀時間：114 年 4 月 27 日（日），14：00-17：00\n\n（二）集合地點/時間：捷運西門站3號出口 / 13：45\n\n（三）導覽者：中原大學地景建築系兼任講師 黃瑋庭 / 助理講師 林望之\n\n（四）路線：亞洲水泥大樓＞外交部辦公大樓＞台大舊法律學院圖書館（徐州路）＞解散【台北】\n\n**交通自理。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	\n	路徑三：走讀義築與南島文化——台東南迴\n	\n\n\n帶領學員深入台東南迴地區，探索建築與文化的深度連結，並藉此體現國父提倡的多元文化包容與社會和諧理念。行程包含參觀義築工作站與香蘭之森，欣賞以國產柳杉打造的木構建築，體現永續發展與自然共生的美學；漫步南迴公路，深入了解新香蘭部落的現代南島語族生活風貌，以及舊香蘭遺址所蘊含的史前文化脈絡，彰顯各族群文化的延續與繁榮；並透過部落族人導覽，認識排灣族拉勞蘭部落與阿美族沙撒拉克部落的獨特文化，從壁畫到生活故事，體驗台灣南島文化的多元樣貌與歷史深度。這段旅程不僅是一次文化的探索，更是一次體現國父對多元族群共生、文化尊重與自然和諧精神的深刻體驗。\n\n（一）走讀時間：114 年 5 月 10 日（六），10：00-15：00\n\n（二）集合地點/時間：台東火車站 / 09：45\n\n（三）導覽者：台灣義築協會花東專案人員 高宏奕 / 助理講師 太麻里鄉香蘭村村長 蕭惠明\n\n（四）路線：台東火車站＞珍和記＞牛肉宅藜麵＞新香蘭文化健康站＞新香蘭活動中心＞義築太麻里南迴工作站＞牡立篙商行＞全家台東香蘭店＞舊香蘭遺址、太麻里靶場＞台東火車站＞解散【台東，租車中巴】\n\n**本場報名人數上限為15人。\n\n**於台東火車站集合後，集體乘坐遊覽車前往。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑四：歷史足跡與文化交融——台北大稻埕\n\n\n探索台北歷史脈絡與城市發展。從和德祠出發，感受客家聚落的宗祠文化，展現移民社群的凝聚力；隨後參訪霞海城隍廟，這座典型閩南廟宇承載庶民信仰，見證清代商業發展與地方社會結構。陳天來故居則反映南洋華僑對台灣經濟與建築風格的影響。李春生教堂作為哥德式基督教建築，體現西方傳教文化與本地社會的交融，而李臨秋故居則見證日治時期知識分子的文化影響力。永樂商場代表戰後市場經濟與城市規劃的變遷，大安醫院舊址則見證醫療現代化的發展歷程。新芳春茶行連結台灣茶葉貿易的繁榮，展現產業文化的演變，最終抵達蔣渭水紀念公園，重溫這位啟蒙者推動社會改革的精神。此次走讀串聯不同族群的建築與文化發展脈絡，呼應國父強調民生關懷、社會進步的理念，透過歷史空間理解台北如何在多元文化交織下，不斷邁向開放與發展。\n\n（一）走讀時間：114 年 5 月 24 日（六），14：00-17：00\n\n（二）集合地點/時間：捷運北門站3號出口 / 13：45\n\n（三）導覽者：國立國父紀念館研究員 鍾文博\n\n（四）路線：和德祠＞霞海城隍廟＞陳天來故居＞李春生教堂＞李臨秋故居＞永樂商場＞大安醫院舊址＞新芳春茶行＞蔣渭水紀念公園＞解散【台北】\n\n**交通自理。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑五：經濟發展與建築之路——台北中正大安\n\n\n透過台灣現代建築大師的作品，探討建築如何承載國家發展、社會變遷與國父孫中山先生的現代化理念。本次行程涵蓋彰化銀行總行辦公大樓（陳其寬/沈祖海）、嘉新大樓（張肇康/沈祖海/Eric Cumine）、三明大樓（高而潘），以及重建的建國南路自宅（王大閎），這些建築不僅展現台灣經濟發展的歷程，也回應國父強調的「民生樂利」與「現代化進程」。彰化銀行總行與嘉新大樓體現了戰後經濟起飛時期的金融與企業發展，象徵國父對於國家富強的願景。三明大樓則是台灣現代建築的經典之一，體現高而潘在空間設計上的前衛理念，反映國父對新思維與科學進步的推崇。而王大閎的建國南路自宅則呈現現代建築與個人生活空間的融合，展現其對建築美學與人文精神的獨特見解。透過專業導覽，參與者將從建築的演變中，理解國父如何透過「民族、民權、民生」的理想，推動社會進步與現代化發展。\n\n（一）走讀時間：114 年 5 月 25 日（日），14：00-17：00\n\n（二）集合地點/時間：彰化銀行（總行台北大樓）/ 13：45\n\n（三）導覽者：東海大學保管組文化資產專案人員 游筱嵩 / 助理講師 劉志鴻\n\n（四）路線：彰化銀行總行辦公大樓（陳其寬/沈祖海）＞三明大樓（高而潘）＞嘉新大樓（張肇康/沈祖海/Eric Cumine)＞建國南路自宅（王大閎）＞解散【台北】\n\n**交通自理。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑六：信仰「築」跡——台南新營【台語導覽50％】\n\n\n      ►台語活動名稱：台南新營ê信仰kap建築之跡——台南新營\n\n帶領學員走訪新營，透過天主教堂與佛教寺院的建築美學與歷史，探討國父提倡的多元包容理念如何在台灣的宗教與建築文化中相互映照。由費宥諒（Karl Freuler）神父所建的新營天主堂與果毅天主堂，不僅展現來台傳教士與在地社群的交流，更體現宗教建築在不同時代的發展與適應。接著，我們將參訪台南大仙寺，這座融合日本佛寺與台灣傳統寺廟風格的建築，見證日治時期佛教文化的影響，並展現台灣佛教空間的歷史變遷。透過專業導覽，我們將探索這些建築如何承載不同時代的價值觀，並思考國父所推崇的「博愛」精神如何在現代台灣的城市風貌與多元族群共存中延續，讓歷史與建築在旅途中鮮活呈現。\n\n（一）走讀時間：114 年 6 月 14 日（六），14：00-17：00\n\n（二）集合地點/時間：新營火車站 / 13：45\n\n（三）導覽者：銘傳大學建築系助理教授 徐明松 / 助理講師 黃瑋庭\n\n（四）路線：新營火車站＞新營天主堂（費宥諒）＞果毅天主堂（費宥諒）＞台南大仙寺＞新營火車站＞解散【台南，租車】\n\n**於新營火車站集合後，集體乘坐遊覽車前往。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑七：公共建築與信仰之路——台南東區【台語導覽50％】\n\n\n ►台語活動名稱：公共kap信仰ê建築之路——台南東區\n\n帶學員探索台南的歷史與建築，透過公共建築與宗教空間的設計，探討國父提倡的民權思想與社會福祉理念如何體現在建築文化中。台南勞工育樂中心與松柏育樂中心由吳增榮設計，兩者兼具實用與美學功能，體現對勞工與長者福利的關懷，呼應國父對「民生樂利」的重視。碧岳神學院則由賀陳詞設計，其現代主義建築語彙承載了宗教教育的使命，展現信仰與知識的融合。透過專業導覽，我們將探索這些建築如何回應時代需求，並思考國父的社會關懷精神如何在公共設施與宗教建築中延續，讓歷史與建築在旅途中鮮活呈現。\n\n（一）走讀時間：114 年 6 月 15 日（日），9：00-12：00\n\n（二）集合地點/時間：台南火車站 / 8：45\n\n（三）導覽者：銘傳大學建築系助理教授 徐明松 / 助理講師 黃瑋庭\n\n（四）路線：台南火車站＞台南勞工育樂中心（吳增榮）＞松柏育樂中心（吳增榮）＞碧岳神學院（賀陳詞）＞三山國王廟＞台南火車站＞解散【台南，租車】\n\n**於台南火車站集合後，集體乘坐遊覽車前往。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑八：社會建築與民生之道——台中東勢【台語導覽50％】\n\n\n      ►台語活動名稱：社會kap民生ê建築之道——台中東勢\n\n帶領學員深入台中東勢地區，探索建築與社會福祉的深層聯繫，並將國父提倡的民生關懷與社會進步理念融入旅程之中。首先，參訪毘盧禪寺，其建築融合中西風格，大雄寶殿採用西洋歷史式樣，與傳統中式佛寺不同，展現日治時期台灣佛教建築的多元特色。寺內的多寶塔建於1957年，為三層樓塔式建築，亦體現當時建築風格的多樣性。接著，走訪由吳增榮設計的東勢鎮公所，這座建築以人本關懷為核心理念，充分體現國父關心人民生活、推動社會平等的精神。隨後，參訪同樣由吳增榮設計的東勢鎮農會，其建築結合了公共空間與農民福祉，具體詮釋國父對農業發展與民生改善的願景。透過專業導覽，學員將深入理解這些建築如何實踐國父的理念，並體驗台中在現代城市發展與社會福祉方面的成就。\n\n（一）走讀時間：114 年 6 月 28 日（六），9：00-12：00\n\n（二）集合地點/時間：豐原火車站 / 8：45\n\n（三）導覽者：台灣戰後建築導覽培訓講師 劉志鴻 / 助理講師 黃幼筠\n\n（四）路線：豐原火車站＞毘盧禪寺、多寶塔（楊貽炳）＞東勢鎮公所（吳增榮）＞東勢鎮農會（吳增榮）＞豐原火車站＞解散【台中，租車】\n\n**於豐原火車站集合後，集體乘坐遊覽車前往。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑九：現代化與航空設計巡禮——台北信義松山【台語導覽50％】\n\n\n      ►台語活動名稱：現代化kap航空設計ê巡禮——台北信義松山\n\n探索台灣現代建築的發展脈絡與航空歷史的深厚背景。首先，參觀由王大閎設計的良士大廈，這座摩登建築以獨特造型與現代化設計，展現國父所推崇的現代化進程與城市發展理念。接著，走訪松山機場立面，由王大閎、陳其寬與沈祖海三位知名建築師聯手設計，此建築不僅見證航空業的快速發展，更呼應國父推動現代化與國際交流的精神。最後，深入了解民航局辦公大樓及車棚，這些設施見證台灣航空業的蓬勃發展，並體現國父對台灣基礎建設與現代化發展的關懷。\n\n透過專業導覽，學員將深入理解這些建築如何實踐國父推動現代化與國際化的理想，並感受台北城市面貌的變遷與發展。\n\n（一）走讀時間：114 年 7 月 12 日（六），14：00-17：00\n\n（二）集合地點/時間：良士大廈 / 13：45\n\n（三）導覽者：台大建築與城鄉研究所兼任助理教授 賴仕堯 /助理講師 游筱嵩\n\n（四）路線：良士大廈（王大閎）＞松山機場立面（王大閎/陳其寬/沈祖海）＞民航局辦公大樓及車棚＞解散【台北】\n\n**交通自理。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑十：走「近」大巴六九部落——台東卑南\n\n\n「大巴六九部落小旅行」帶領學員走進卑南族傳統八社之一的大巴六九部落（tamalakaw），探索太平溪與利嘉林道的絕美自然景觀。行程包含大巴六九植物園區賞月夜、螢火蟲與瀑布生態體驗，並走訪利嘉林道，欣賞多樣昆蟲與鳥類，探尋老蕃社遺址的史前文化遺跡。透過部落導覽，深入了解卑南族「石生傳說」，參與手工藝坊的十字繡、木刻及傳統花環製作，感受卑南族文化之美，還可體驗傳統舞蹈與品味特色藥膳，享受自然與文化交織的深度旅程。\n\n（一）走讀時間：114 年 7 月 26 日（六），10：00-15：00\n\n（二）集合地點/時間：台東火車站 / 09：50-10：10\n\n（三）導覽者：部落意見領袖 張廣榮\n\n（四）路線：台東火車站＞泰安村大巴六九部落＞台東火車站＞解散【台東，租車】\n\n**於台東火車站集合後，集體乘坐遊覽車前往。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n \n\n \n\n \n\n ', '國立國父紀念館', '無資料', '2025-04-26 00:00:00', '2025-07-26 00:00:00', '逸仙公園國父史蹟館＞二二八和平公園＞中山堂＞西門紅樓＞興中會台灣分會', 0, 0, '無資料', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=51047', '[]') ON DUPLICATE KEY UPDATE `activity_name`='走讀國父史蹟與多元族群建築文化活動', `description`='本活動以孫中山先生的史蹟、現代建築、多元族群文化建築為核心，透過走讀導覽帶領學員探索國父思想在台灣的具體展現。自4月26日起至7月26日，預計於台北、台中、台南、台東舉辦10場活動，邀請學者專家及文史工作者進行導覽，解析建築與歷史的連結，並探討國父思想的當代意義。\n\n \n\n講師群（依照姓名筆畫順序排列）：\n\n\n張廣榮  大巴六九部落意見領袖\n\n游筱嵩  東海大學文化資產專案人員、台灣戰後建築導覽培訓講師 \n\n徐明松  建築史學者、銘傳大學建築系助理教授\n\n高宏奕  台灣義築協會花東專案人員\n\n黃瑋庭  中原大學設計學博士生、地景建築系兼任講師\n\n劉志鴻  台灣戰後建築導覽培訓講師\n\n鍾文博  國立國父紀念館研究員\n\n賴仕堯  台大建築與城鄉研究所兼任助理教授\n\n\n \n\n走讀活動場次：\n\n\n	\n	路徑一：國父革命起點與台灣民主記憶之路——台北中正萬華\n	\n\n\n帶領學員踏尋孫中山先生的革命足跡，探索其在台灣的活動如何影響歷史發展，並與台灣民主進程相互交織。行程從逸仙公園與國父史蹟館（梅屋敷）出發，這裡是國父在台策劃革命的重要據點，學員將參訪國父銅像與紀念設施，回顧其革命歷程。接著前往二二八和平公園，對照國父提倡的「民權」理念，探討台灣民主發展與歷史轉折。隨後參訪中山堂，這座建築見證了台灣光復典禮，承載著國父「民族獨立」的理想與戰後政治變遷的歷史。最後抵達興中會台灣分會舊址（長沙街），這是國父在台灣建立的革命組織，象徵其在亞洲推動革命的布局，為本次走讀畫下歷史性的總結。透過這次走讀，學員將串聯革命與民主的歷史脈絡，親身感受台灣如何從革命理想到現代民主發展。\n\n（一）走讀時間：114 年 4 月 26 日（六），14：00-17：00\n\n（二）集合地點/時間：逸仙公園國父史蹟館 / 13：45\n\n（三）導覽者：國立國父紀念館研究員 鍾文博\n\n（四）路線：逸仙公園國父史蹟館＞二二八和平公園＞中山堂＞西門紅樓＞興中會台灣分會＞解散【台北】\n\n**交通自理。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑二：現代建築與國家願景巡禮——台北中正大安\n\n\n帶領學員走訪台北，探索王大閎的建築作品，並思考其設計理念如何與國父孫中山先生的現代化願景相呼應。王大閎是台灣現代建築的重要推手，其作品結合國際現代主義與東方文化精神，體現國父「融合中西、推動現代化」的思想。此次行程將參訪亞洲水泥大樓，這座建築為台灣首座帷幕牆設計的大樓，象徵著科技與建築的進步；外交部大樓，其設計不僅展現國際視野，也呼應國父強調外交自主的理念；最後走訪台大舊法律學院圖書館（徐州路），作為培育法律人才的重要基地，呼應國父對於「民權」的重視。透過專業導覽，我們將探索建築如何承載時代使命，並思考國父思想在現代社會中的延續。\n\n（一）走讀時間：114 年 4 月 27 日（日），14：00-17：00\n\n（二）集合地點/時間：捷運西門站3號出口 / 13：45\n\n（三）導覽者：中原大學地景建築系兼任講師 黃瑋庭 / 助理講師 林望之\n\n（四）路線：亞洲水泥大樓＞外交部辦公大樓＞台大舊法律學院圖書館（徐州路）＞解散【台北】\n\n**交通自理。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	\n	路徑三：走讀義築與南島文化——台東南迴\n	\n\n\n帶領學員深入台東南迴地區，探索建築與文化的深度連結，並藉此體現國父提倡的多元文化包容與社會和諧理念。行程包含參觀義築工作站與香蘭之森，欣賞以國產柳杉打造的木構建築，體現永續發展與自然共生的美學；漫步南迴公路，深入了解新香蘭部落的現代南島語族生活風貌，以及舊香蘭遺址所蘊含的史前文化脈絡，彰顯各族群文化的延續與繁榮；並透過部落族人導覽，認識排灣族拉勞蘭部落與阿美族沙撒拉克部落的獨特文化，從壁畫到生活故事，體驗台灣南島文化的多元樣貌與歷史深度。這段旅程不僅是一次文化的探索，更是一次體現國父對多元族群共生、文化尊重與自然和諧精神的深刻體驗。\n\n（一）走讀時間：114 年 5 月 10 日（六），10：00-15：00\n\n（二）集合地點/時間：台東火車站 / 09：45\n\n（三）導覽者：台灣義築協會花東專案人員 高宏奕 / 助理講師 太麻里鄉香蘭村村長 蕭惠明\n\n（四）路線：台東火車站＞珍和記＞牛肉宅藜麵＞新香蘭文化健康站＞新香蘭活動中心＞義築太麻里南迴工作站＞牡立篙商行＞全家台東香蘭店＞舊香蘭遺址、太麻里靶場＞台東火車站＞解散【台東，租車中巴】\n\n**本場報名人數上限為15人。\n\n**於台東火車站集合後，集體乘坐遊覽車前往。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑四：歷史足跡與文化交融——台北大稻埕\n\n\n探索台北歷史脈絡與城市發展。從和德祠出發，感受客家聚落的宗祠文化，展現移民社群的凝聚力；隨後參訪霞海城隍廟，這座典型閩南廟宇承載庶民信仰，見證清代商業發展與地方社會結構。陳天來故居則反映南洋華僑對台灣經濟與建築風格的影響。李春生教堂作為哥德式基督教建築，體現西方傳教文化與本地社會的交融，而李臨秋故居則見證日治時期知識分子的文化影響力。永樂商場代表戰後市場經濟與城市規劃的變遷，大安醫院舊址則見證醫療現代化的發展歷程。新芳春茶行連結台灣茶葉貿易的繁榮，展現產業文化的演變，最終抵達蔣渭水紀念公園，重溫這位啟蒙者推動社會改革的精神。此次走讀串聯不同族群的建築與文化發展脈絡，呼應國父強調民生關懷、社會進步的理念，透過歷史空間理解台北如何在多元文化交織下，不斷邁向開放與發展。\n\n（一）走讀時間：114 年 5 月 24 日（六），14：00-17：00\n\n（二）集合地點/時間：捷運北門站3號出口 / 13：45\n\n（三）導覽者：國立國父紀念館研究員 鍾文博\n\n（四）路線：和德祠＞霞海城隍廟＞陳天來故居＞李春生教堂＞李臨秋故居＞永樂商場＞大安醫院舊址＞新芳春茶行＞蔣渭水紀念公園＞解散【台北】\n\n**交通自理。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑五：經濟發展與建築之路——台北中正大安\n\n\n透過台灣現代建築大師的作品，探討建築如何承載國家發展、社會變遷與國父孫中山先生的現代化理念。本次行程涵蓋彰化銀行總行辦公大樓（陳其寬/沈祖海）、嘉新大樓（張肇康/沈祖海/Eric Cumine）、三明大樓（高而潘），以及重建的建國南路自宅（王大閎），這些建築不僅展現台灣經濟發展的歷程，也回應國父強調的「民生樂利」與「現代化進程」。彰化銀行總行與嘉新大樓體現了戰後經濟起飛時期的金融與企業發展，象徵國父對於國家富強的願景。三明大樓則是台灣現代建築的經典之一，體現高而潘在空間設計上的前衛理念，反映國父對新思維與科學進步的推崇。而王大閎的建國南路自宅則呈現現代建築與個人生活空間的融合，展現其對建築美學與人文精神的獨特見解。透過專業導覽，參與者將從建築的演變中，理解國父如何透過「民族、民權、民生」的理想，推動社會進步與現代化發展。\n\n（一）走讀時間：114 年 5 月 25 日（日），14：00-17：00\n\n（二）集合地點/時間：彰化銀行（總行台北大樓）/ 13：45\n\n（三）導覽者：東海大學保管組文化資產專案人員 游筱嵩 / 助理講師 劉志鴻\n\n（四）路線：彰化銀行總行辦公大樓（陳其寬/沈祖海）＞三明大樓（高而潘）＞嘉新大樓（張肇康/沈祖海/Eric Cumine)＞建國南路自宅（王大閎）＞解散【台北】\n\n**交通自理。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑六：信仰「築」跡——台南新營【台語導覽50％】\n\n\n      ►台語活動名稱：台南新營ê信仰kap建築之跡——台南新營\n\n帶領學員走訪新營，透過天主教堂與佛教寺院的建築美學與歷史，探討國父提倡的多元包容理念如何在台灣的宗教與建築文化中相互映照。由費宥諒（Karl Freuler）神父所建的新營天主堂與果毅天主堂，不僅展現來台傳教士與在地社群的交流，更體現宗教建築在不同時代的發展與適應。接著，我們將參訪台南大仙寺，這座融合日本佛寺與台灣傳統寺廟風格的建築，見證日治時期佛教文化的影響，並展現台灣佛教空間的歷史變遷。透過專業導覽，我們將探索這些建築如何承載不同時代的價值觀，並思考國父所推崇的「博愛」精神如何在現代台灣的城市風貌與多元族群共存中延續，讓歷史與建築在旅途中鮮活呈現。\n\n（一）走讀時間：114 年 6 月 14 日（六），14：00-17：00\n\n（二）集合地點/時間：新營火車站 / 13：45\n\n（三）導覽者：銘傳大學建築系助理教授 徐明松 / 助理講師 黃瑋庭\n\n（四）路線：新營火車站＞新營天主堂（費宥諒）＞果毅天主堂（費宥諒）＞台南大仙寺＞新營火車站＞解散【台南，租車】\n\n**於新營火車站集合後，集體乘坐遊覽車前往。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑七：公共建築與信仰之路——台南東區【台語導覽50％】\n\n\n ►台語活動名稱：公共kap信仰ê建築之路——台南東區\n\n帶學員探索台南的歷史與建築，透過公共建築與宗教空間的設計，探討國父提倡的民權思想與社會福祉理念如何體現在建築文化中。台南勞工育樂中心與松柏育樂中心由吳增榮設計，兩者兼具實用與美學功能，體現對勞工與長者福利的關懷，呼應國父對「民生樂利」的重視。碧岳神學院則由賀陳詞設計，其現代主義建築語彙承載了宗教教育的使命，展現信仰與知識的融合。透過專業導覽，我們將探索這些建築如何回應時代需求，並思考國父的社會關懷精神如何在公共設施與宗教建築中延續，讓歷史與建築在旅途中鮮活呈現。\n\n（一）走讀時間：114 年 6 月 15 日（日），9：00-12：00\n\n（二）集合地點/時間：台南火車站 / 8：45\n\n（三）導覽者：銘傳大學建築系助理教授 徐明松 / 助理講師 黃瑋庭\n\n（四）路線：台南火車站＞台南勞工育樂中心（吳增榮）＞松柏育樂中心（吳增榮）＞碧岳神學院（賀陳詞）＞三山國王廟＞台南火車站＞解散【台南，租車】\n\n**於台南火車站集合後，集體乘坐遊覽車前往。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑八：社會建築與民生之道——台中東勢【台語導覽50％】\n\n\n      ►台語活動名稱：社會kap民生ê建築之道——台中東勢\n\n帶領學員深入台中東勢地區，探索建築與社會福祉的深層聯繫，並將國父提倡的民生關懷與社會進步理念融入旅程之中。首先，參訪毘盧禪寺，其建築融合中西風格，大雄寶殿採用西洋歷史式樣，與傳統中式佛寺不同，展現日治時期台灣佛教建築的多元特色。寺內的多寶塔建於1957年，為三層樓塔式建築，亦體現當時建築風格的多樣性。接著，走訪由吳增榮設計的東勢鎮公所，這座建築以人本關懷為核心理念，充分體現國父關心人民生活、推動社會平等的精神。隨後，參訪同樣由吳增榮設計的東勢鎮農會，其建築結合了公共空間與農民福祉，具體詮釋國父對農業發展與民生改善的願景。透過專業導覽，學員將深入理解這些建築如何實踐國父的理念，並體驗台中在現代城市發展與社會福祉方面的成就。\n\n（一）走讀時間：114 年 6 月 28 日（六），9：00-12：00\n\n（二）集合地點/時間：豐原火車站 / 8：45\n\n（三）導覽者：台灣戰後建築導覽培訓講師 劉志鴻 / 助理講師 黃幼筠\n\n（四）路線：豐原火車站＞毘盧禪寺、多寶塔（楊貽炳）＞東勢鎮公所（吳增榮）＞東勢鎮農會（吳增榮）＞豐原火車站＞解散【台中，租車】\n\n**於豐原火車站集合後，集體乘坐遊覽車前往。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑九：現代化與航空設計巡禮——台北信義松山【台語導覽50％】\n\n\n      ►台語活動名稱：現代化kap航空設計ê巡禮——台北信義松山\n\n探索台灣現代建築的發展脈絡與航空歷史的深厚背景。首先，參觀由王大閎設計的良士大廈，這座摩登建築以獨特造型與現代化設計，展現國父所推崇的現代化進程與城市發展理念。接著，走訪松山機場立面，由王大閎、陳其寬與沈祖海三位知名建築師聯手設計，此建築不僅見證航空業的快速發展，更呼應國父推動現代化與國際交流的精神。最後，深入了解民航局辦公大樓及車棚，這些設施見證台灣航空業的蓬勃發展，並體現國父對台灣基礎建設與現代化發展的關懷。\n\n透過專業導覽，學員將深入理解這些建築如何實踐國父推動現代化與國際化的理想，並感受台北城市面貌的變遷與發展。\n\n（一）走讀時間：114 年 7 月 12 日（六），14：00-17：00\n\n（二）集合地點/時間：良士大廈 / 13：45\n\n（三）導覽者：台大建築與城鄉研究所兼任助理教授 賴仕堯 /助理講師 游筱嵩\n\n（四）路線：良士大廈（王大閎）＞松山機場立面（王大閎/陳其寬/沈祖海）＞民航局辦公大樓及車棚＞解散【台北】\n\n**交通自理。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n\n \n\n\n	路徑十：走「近」大巴六九部落——台東卑南\n\n\n「大巴六九部落小旅行」帶領學員走進卑南族傳統八社之一的大巴六九部落（tamalakaw），探索太平溪與利嘉林道的絕美自然景觀。行程包含大巴六九植物園區賞月夜、螢火蟲與瀑布生態體驗，並走訪利嘉林道，欣賞多樣昆蟲與鳥類，探尋老蕃社遺址的史前文化遺跡。透過部落導覽，深入了解卑南族「石生傳說」，參與手工藝坊的十字繡、木刻及傳統花環製作，感受卑南族文化之美，還可體驗傳統舞蹈與品味特色藥膳，享受自然與文化交織的深度旅程。\n\n（一）走讀時間：114 年 7 月 26 日（六），10：00-15：00\n\n（二）集合地點/時間：台東火車站 / 09：50-10：10\n\n（三）導覽者：部落意見領袖 張廣榮\n\n（四）路線：台東火車站＞泰安村大巴六九部落＞台東火車站＞解散【台東，租車】\n\n**於台東火車站集合後，集體乘坐遊覽車前往。\n\n**主辦單位保有最終修改、變更、活動解釋及取消本活動之權利，實際走讀地點將視實際狀況適當調整進行，敬請見諒。\n\n \n\n \n\n \n\n ', `organizer`='國立國父紀念館', `address`='無資料', `start_date`='2025-04-26 00:00:00', `end_date`='2025-07-26 00:00:00', `location`='逸仙公園國父史蹟館＞二二八和平公園＞中山堂＞西門紅樓＞興中會台灣分會', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=51047', `image_url`='[]';
