INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8874126b32408680bed61', '都歷遊客中心｜沉浸式體驗故事館', '全新的！東海岸親子場域「都歷沉浸式體驗故事館」\r\n就在📍#台東 都歷遊客中心一樓\r\n    \r\n全新打造的沉浸式體驗區開放啦～\r\n\r\n結合數位科技與在地文化，以「東部海岸故事書」為主軸，透過虛實交織的投影與互動，帶領大小朋友探索阿美族的神話傳說、自然生態與文化價值，感受到東海岸山海生活的智慧。\r\n超厲害的聲光視覺，位於都歷遊客中心一樓，「東海岸沉浸式故事體驗區」，有科技結合也有在地文化，搭配環繞投影及互動裝置，細膩呈現這片土地的故事。沒想到東海岸有這麼前衛的場域。\r\n都歷遊客中心，室外不但可以溜毛孩，室內也有溜小孩放電的沉浸式故事書，大人的知識含金量也不容小覷，內容都是與阿美族有關的傳說故事，跟著故事動線走，還有大小朋友一起打boss的互動關卡，美照拍好拍滿～\r\n地點：台東 都歷遊客中心一樓\r\n展期：即日起開展', '交通部觀光署東部海岸國家風景區管理處', '臺東縣成功鎮新村路25號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '交通部觀光局東部海岸國家風景區管理處', 23.12663716, 121.3537983, '無資料', 'https://www.facebook.com/share/p/1Ep7B2A5em/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='都歷遊客中心｜沉浸式體驗故事館', `description`='全新的！東海岸親子場域「都歷沉浸式體驗故事館」\r\n就在📍#台東 都歷遊客中心一樓\r\n    \r\n全新打造的沉浸式體驗區開放啦～\r\n\r\n結合數位科技與在地文化，以「東部海岸故事書」為主軸，透過虛實交織的投影與互動，帶領大小朋友探索阿美族的神話傳說、自然生態與文化價值，感受到東海岸山海生活的智慧。\r\n超厲害的聲光視覺，位於都歷遊客中心一樓，「東海岸沉浸式故事體驗區」，有科技結合也有在地文化，搭配環繞投影及互動裝置，細膩呈現這片土地的故事。沒想到東海岸有這麼前衛的場域。\r\n都歷遊客中心，室外不但可以溜毛孩，室內也有溜小孩放電的沉浸式故事書，大人的知識含金量也不容小覷，內容都是與阿美族有關的傳說故事，跟著故事動線走，還有大小朋友一起打boss的互動關卡，美照拍好拍滿～\r\n地點：台東 都歷遊客中心一樓\r\n展期：即日起開展', `organizer`='交通部觀光署東部海岸國家風景區管理處', `address`='臺東縣成功鎮新村路25號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='交通部觀光局東部海岸國家風景區管理處', `latitude`=23.12663716, `longitude`=121.3537983, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1Ep7B2A5em/', `image_url`='[]';
