INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8874426b32408680bed6f', '基隆故事館「STORY100%」特展', '基隆故事館，作為訴說基隆故事的場所，以新的面貌重新開幕，此次常設展主題為「見證百年基隆」，以「基隆港」為核心主軸，帶領觀眾穿越百年歷史，一同探索基隆從「雞籠」到「基隆」的轉變，見證這座城市的興衰與繁榮。\r\n本次展覽分為三大展區「漁撈港灣到海港市街」、「戰後復甦到繁華盛世」、「國際觀光到百年導航」。透過船艙廊道的展示手法，喚起不同年代旅人對基隆的第一印象；空拍影像及歷史地圖區則細膩呈現基隆百年來的城市發展脈絡。從1924年基隆從「街」升格為「市」，歷經太平洋戰爭時期（1941-1945）的軍事要港，到戰後的黃金歲月，完整記錄了基隆從在地到國際的蛻變歷程。將涵蓋1990年代至2024年，基隆依然作為臺灣北部的國際貿易大港，持續訴說著百年來的興衰起落。從1924年到2024年，基隆以港口城市的姿態，繼續流轉著未來的篇章，展現出其獨特的歷史與文化。', '基隆市文化觀光局', '基隆市中正區信一路181號', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '基隆文化中心', 25.1314199, 121.7437065, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='基隆故事館「STORY100%」特展', `description`='基隆故事館，作為訴說基隆故事的場所，以新的面貌重新開幕，此次常設展主題為「見證百年基隆」，以「基隆港」為核心主軸，帶領觀眾穿越百年歷史，一同探索基隆從「雞籠」到「基隆」的轉變，見證這座城市的興衰與繁榮。\r\n本次展覽分為三大展區「漁撈港灣到海港市街」、「戰後復甦到繁華盛世」、「國際觀光到百年導航」。透過船艙廊道的展示手法，喚起不同年代旅人對基隆的第一印象；空拍影像及歷史地圖區則細膩呈現基隆百年來的城市發展脈絡。從1924年基隆從「街」升格為「市」，歷經太平洋戰爭時期（1941-1945）的軍事要港，到戰後的黃金歲月，完整記錄了基隆從在地到國際的蛻變歷程。將涵蓋1990年代至2024年，基隆依然作為臺灣北部的國際貿易大港，持續訴說著百年來的興衰起落。從1924年到2024年，基隆以港口城市的姿態，繼續流轉著未來的篇章，展現出其獨特的歷史與文化。', `organizer`='基隆市文化觀光局', `address`='基隆市中正區信一路181號', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='基隆文化中心', `latitude`=25.1314199, `longitude`=121.7437065, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
