INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9375747', '2025雙北世壯運開幕門票3/20中午開賣！好康加碼再抽機票', '2025雙北世界壯年運動會即將於5月17日至5月30日盛大登場！來自全球的壯年選手將齊聚一堂，共同展現運動精神與生命力。其中開幕典禮不容錯過，門票將於3月20日中午12點整正式開賣！邀請市民朋友相約臺北大巨蛋，除了可以欣賞精采表演節目與選手風采外，還有三大購票好康等你來拿。三大好康優惠，購票就能輕鬆帶走！好康1：周邊商品9折優惠 &mdash; 購票時加購官方周邊商品，獨家紀念品一次入手！好康2：百家特約店家優惠 &mdash; 憑票證即可於100家大巨蛋周邊特約店家享專屬折扣！好康3：東京單人來回機票抽獎 &mdash; 購票即獲抽獎資格，有機會免費飛往東京親自為中華隊應援！3/20中午12點起等你來購票，與世界一起迎接熱血時刻！不論你是運動愛好者，還是想親身感受國際賽事氛圍，這都是不容錯過的難得機會！購票詳情請至世壯運官網/賽會活動/開閉幕/「開幕典禮購票資訊」查詢，門票數量有限，售完為止。─── 售票資訊 ───&nbsp;🛎️時間｜台灣時間 3/20(四)12：00正式開賣&nbsp;💰票價｜NT$300 / NT$400 / NT$500&nbsp;🔗連結｜https://reurl.cc/1KjKQG', '臺北市內湖區戶政事務所', '無資料', '2025-03-20 00:00:00', '2025-05-17 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1B9AE5CF49A4ACF0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025雙北世壯運開幕門票3/20中午開賣！好康加碼再抽機票', `description`='2025雙北世界壯年運動會即將於5月17日至5月30日盛大登場！來自全球的壯年選手將齊聚一堂，共同展現運動精神與生命力。其中開幕典禮不容錯過，門票將於3月20日中午12點整正式開賣！邀請市民朋友相約臺北大巨蛋，除了可以欣賞精采表演節目與選手風采外，還有三大購票好康等你來拿。三大好康優惠，購票就能輕鬆帶走！好康1：周邊商品9折優惠 &mdash; 購票時加購官方周邊商品，獨家紀念品一次入手！好康2：百家特約店家優惠 &mdash; 憑票證即可於100家大巨蛋周邊特約店家享專屬折扣！好康3：東京單人來回機票抽獎 &mdash; 購票即獲抽獎資格，有機會免費飛往東京親自為中華隊應援！3/20中午12點起等你來購票，與世界一起迎接熱血時刻！不論你是運動愛好者，還是想親身感受國際賽事氛圍，這都是不容錯過的難得機會！購票詳情請至世壯運官網/賽會活動/開閉幕/「開幕典禮購票資訊」查詢，門票數量有限，售完為止。─── 售票資訊 ───&nbsp;🛎️時間｜台灣時間 3/20(四)12：00正式開賣&nbsp;💰票價｜NT$300 / NT$400 / NT$500&nbsp;🔗連結｜https://reurl.cc/1KjKQG', `organizer`='臺北市內湖區戶政事務所', `address`='無資料', `start_date`='2025-03-20 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1B9AE5CF49A4ACF0', `image_url`='[]';
