INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9374023', '北投就業服務站將於114年3月25日(週二)下午2-4時辦理【柯旅天閣股份有限公司】微型徵才活動', '北投就業服務站將於114年3月25日(週二)下午2-4時辦理【柯旅天閣股份有限公司】微型徵才活動活動時間：3月25日(二)下午2:00~4:00活動地點：北投就業服務站 (臺北市北投區新市街30號5樓)洽詢電話：(02)28981819#115公司簡介：近年來休閒旅遊業的蓬勃發展，影響所及的是旅館業的精緻化，THE Tango天閣酒店就是因應這個趨勢而成。地處絕佳生活機能、交通樞紐地利之便；全館的設施以房客舒適度為設計初衷，靜謐而幽雅的簡約風格；褪去館外繁鬧景致，臨門一隔，時尚生活可遠可近。福利制度：公司每日免費供餐、提供制服及換洗服務、享連鎖飯店的住宿優惠、年資滿一年可申請集團住宿一晚、完備的訓練系統及內部晉升制度、年終獎金、三節獎金/禮品、員工團保、績效獎金、完整的教育訓練、順暢的升遷管道、員工餐廳、生日假、家庭照顧假、健康檢查職務名稱：櫃台禮賓接待員需求人數：10學歷要求：高中職以上工作經驗：不拘工作內容：1.迎賓、大廳接待2.辦理住宿、退房相關作業3.資料輸入、旅客訂單建立4.總機電話客服5.國外旅客接待服務&nbsp;(具備基本英文或日文會話能力)6.飯店相關櫃檯事務7.可配合輪班、具合作精神、能與團隊成員合作達成任務薪資待遇：月薪33000-34000元工作時間：(需輪班)早班07:00-15:00/晚班15:00-23:00/夜班23:00-07:00工作地點：中正區、中山區、士林區、松山區、信義區職務名稱：服務中心需求人數：5學歷要求：不拘工作經驗：不拘工作內容：1.飯店迎賓接待及行李運送服務2.提供館內各項業務服務諮詢等工作3.反應靈敏，具服務熱忱&nbsp;4.可配合輪班5.備汽車(手排)駕照薪資待遇：月薪29000-30000元工作時間：早班08:00-16:00/晚班15:00-23:00工作地點：中正區、中山區、士林區、松山區、信義區職務名稱：房務員需求人數：10學歷要求：不拘工作經驗：不拘工作內容：1.客房清潔整理工作及執行房務相關事項2.支援公共區域清理維護3.客房備品管理及補給4.客房定期保養5.保管處理遺失物品6.其他主管交辦事項薪資待遇：月薪32000-33000元工作時間：早班09:00-17:00工作地點：中正區、中山區、士林區、松山區、信義區', '北投就業服務站', '台北市北投區新市街30號5樓', '2025-03-25 00:00:00', '2025-03-25 00:00:00', '北投就業服務站', 25.1480682, 121.5177992, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B0497281CE5044FD', '[]') ON DUPLICATE KEY UPDATE `activity_name`='北投就業服務站將於114年3月25日(週二)下午2-4時辦理【柯旅天閣股份有限公司】微型徵才活動', `description`='北投就業服務站將於114年3月25日(週二)下午2-4時辦理【柯旅天閣股份有限公司】微型徵才活動活動時間：3月25日(二)下午2:00~4:00活動地點：北投就業服務站 (臺北市北投區新市街30號5樓)洽詢電話：(02)28981819#115公司簡介：近年來休閒旅遊業的蓬勃發展，影響所及的是旅館業的精緻化，THE Tango天閣酒店就是因應這個趨勢而成。地處絕佳生活機能、交通樞紐地利之便；全館的設施以房客舒適度為設計初衷，靜謐而幽雅的簡約風格；褪去館外繁鬧景致，臨門一隔，時尚生活可遠可近。福利制度：公司每日免費供餐、提供制服及換洗服務、享連鎖飯店的住宿優惠、年資滿一年可申請集團住宿一晚、完備的訓練系統及內部晉升制度、年終獎金、三節獎金/禮品、員工團保、績效獎金、完整的教育訓練、順暢的升遷管道、員工餐廳、生日假、家庭照顧假、健康檢查職務名稱：櫃台禮賓接待員需求人數：10學歷要求：高中職以上工作經驗：不拘工作內容：1.迎賓、大廳接待2.辦理住宿、退房相關作業3.資料輸入、旅客訂單建立4.總機電話客服5.國外旅客接待服務&nbsp;(具備基本英文或日文會話能力)6.飯店相關櫃檯事務7.可配合輪班、具合作精神、能與團隊成員合作達成任務薪資待遇：月薪33000-34000元工作時間：(需輪班)早班07:00-15:00/晚班15:00-23:00/夜班23:00-07:00工作地點：中正區、中山區、士林區、松山區、信義區職務名稱：服務中心需求人數：5學歷要求：不拘工作經驗：不拘工作內容：1.飯店迎賓接待及行李運送服務2.提供館內各項業務服務諮詢等工作3.反應靈敏，具服務熱忱&nbsp;4.可配合輪班5.備汽車(手排)駕照薪資待遇：月薪29000-30000元工作時間：早班08:00-16:00/晚班15:00-23:00工作地點：中正區、中山區、士林區、松山區、信義區職務名稱：房務員需求人數：10學歷要求：不拘工作經驗：不拘工作內容：1.客房清潔整理工作及執行房務相關事項2.支援公共區域清理維護3.客房備品管理及補給4.客房定期保養5.保管處理遺失物品6.其他主管交辦事項薪資待遇：月薪32000-33000元工作時間：早班09:00-17:00工作地點：中正區、中山區、士林區、松山區、信義區', `organizer`='北投就業服務站', `address`='台北市北投區新市街30號5樓', `start_date`='2025-03-25 00:00:00', `end_date`='2025-03-25 00:00:00', `location`='北投就業服務站', `latitude`=25.1480682, `longitude`=121.5177992, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B0497281CE5044FD', `image_url`='[]';
