INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9373929', '艋舺就服站114/03/26(三)下午2-4時，舉辦【勝堡村營造工程股份有限公司】現場徵才活動', '一、工程名稱：南港調車場都市更新案（更新單元二）主體新建工程。二、職務名稱：基層技術工及勞力工。三、雇用人數：388人四、核薪方式：月薪新臺幣33,425元(依勞動部113年12月25日勞動發管字第130517344A&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;號令辦理)。五、工作時間：08時00分至17時00分(含休息時間1小時)六、工作內容：搬運60公斤(有輔具)、清潔、泥土清運、支援雜項工作及其他相關體力工&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;作，須高架作業約1米，符合職業安全衛生法及相關規定。七、工 程 地 點：臺北市南港區玉成段二小段253-1、254-2、277-3、280、281-1、283-&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;3、283-4、283-5、285、286、287-1、291、292、292-1、293-8、&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;294等16筆地號&nbsp; &nbsp; &nbsp; &nbsp;工 務 所 地 址：臺北市南港區市民大道7段220號對面八、供膳狀況：供膳宿(膳宿每月合計扣款最高5,000元)。九、專長資格：不拘。十、聘僱期間：至117年8月31日。', '臺北市就業服務處', '無資料', '2025-03-26 00:00:00', '2025-03-26 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=ED2AEE8C769C9FC8', '[]') ON DUPLICATE KEY UPDATE `activity_name`='艋舺就服站114/03/26(三)下午2-4時，舉辦【勝堡村營造工程股份有限公司】現場徵才活動', `description`='一、工程名稱：南港調車場都市更新案（更新單元二）主體新建工程。二、職務名稱：基層技術工及勞力工。三、雇用人數：388人四、核薪方式：月薪新臺幣33,425元(依勞動部113年12月25日勞動發管字第130517344A&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;號令辦理)。五、工作時間：08時00分至17時00分(含休息時間1小時)六、工作內容：搬運60公斤(有輔具)、清潔、泥土清運、支援雜項工作及其他相關體力工&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;作，須高架作業約1米，符合職業安全衛生法及相關規定。七、工 程 地 點：臺北市南港區玉成段二小段253-1、254-2、277-3、280、281-1、283-&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;3、283-4、283-5、285、286、287-1、291、292、292-1、293-8、&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;294等16筆地號&nbsp; &nbsp; &nbsp; &nbsp;工 務 所 地 址：臺北市南港區市民大道7段220號對面八、供膳狀況：供膳宿(膳宿每月合計扣款最高5,000元)。九、專長資格：不拘。十、聘僱期間：至117年8月31日。', `organizer`='臺北市就業服務處', `address`='無資料', `start_date`='2025-03-26 00:00:00', `end_date`='2025-03-26 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=ED2AEE8C769C9FC8', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9373912', '大安分處-臺科大校慶園遊會', '&nbsp; &nbsp; (一)活動名稱：臺科大校慶園遊會暨租稅宣導活動。&nbsp; &nbsp;&nbsp;(二)活動時間：114年3月22日（星期六）上午10時至12時。&nbsp; &nbsp;&nbsp;(三)活動地點：臺科大行政大樓後方草地。&nbsp; &nbsp;&nbsp;(四)活動內容：&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;１、完成現場指定活動，即可兌換精美小禮物1份。&ensp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;２、捐贈114年1-3月未登打統一編號且消費金額大於10元雲端發票，可兌換宣導品。（每人每次&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;限兌換3份宣導品，數量有限，換完為止。）&nbsp; &nbsp;&nbsp;(五)說明：&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;１、本活動所募發票將全數捐贈公益慈善團體，雲端發票經捐贈完成，即無法退還或兌獎。&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;２、宣導品兌換以現場實物為準，主辦單位保有修改或變更宣導品的權利。&ensp;&ensp;&ensp;&ensp;&ensp;&ensp;聯絡人：大安分處&ensp;范小姐&ensp;&ensp;&ensp;&ensp;&ensp;&ensp;聯絡電話：2358-1770分機413=====================稅務宣導=========================★雲端發票專屬獎高達13.67億元，500元獎245萬組！發票存載具，對獎機會多1次！★房屋稅差別稅率2.0新制(俗稱囤房稅2.0)於113年7月起施行，自住住家用房屋本人、配偶或直系親屬&nbsp; &nbsp;應辦竣戶籍登記，始可適用自住住家用稅率課徵房屋稅。★稅務視訊服務雲空中E化無國界，一鍵就能搞定稅務大小事。★國地稅免付費專線整合為0800-000-321。★納稅者權利保護法已施行，本處設置納保官保障納稅者權益。★請多加利用財政部地方稅LINE官方帳號與智慧客服。★直撥退稅線上回復，免擔心支票遺失或逾期。★當志工樂趣多，邀請一同加入志工服務行列。★申辦「稅籍異動即時通」服務，讓您掌握不動產移轉動態。★稅捐稽徵法修正，稅捐逾繳納期限始繳納，須加徵滯納金之加徵方式，修正為「每逾3日」按滯納數&nbsp; &nbsp;額加徵1％，總加徵率降為10％。★性別平等從你我做起，落實性別平權繼承與贈與不分性別。★臺北市公益性出租房屋租稅優惠。★國外帶回之免稅菸酒不得販賣，網路禁賣菸酒。★對滯納（欠）使用牌照稅案件，請交通工具所有人或使用人依限繳納，以免欠稅車輛使用（停放）&nbsp; &nbsp;公共道路被查獲而受罰。★自114年1月17日起，身心障礙者有駕照且名下無車輛者，得以其配偶或同一戶籍二親等以內親屬之&nbsp; &nbsp;車輛申請免徵使用牌照稅，且每一身心障礙者以1輛為限。★交通工具如不擬使用，請向監理機關申報停止使用。★請多加利用各項E化繳稅管道（含行動支付、臨櫃信用卡、TW&ensp;FidO、Line&ensp;Pay等）及財政部擴大&nbsp; &nbsp;線上繳稅機制。★不動產移轉一站式服務。★臺北市分期繳納地方稅申請辦法。★全功能自動化服務機自助申辦或查調稅務案件、補發稅單及繳稅。★歡迎申辦以電子方式傳送繳款書及繳納證明。★民法成年年齡下修為18歲，地方稅、國稅皆有影響。', '臺北市稅捐稽徵處', '無資料', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=BDB3A1BBEFABA15C', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大安分處-臺科大校慶園遊會', `description`='&nbsp; &nbsp; (