INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9375981', '景新分館多元閱讀推廣系列講座「即使如此還是想畫畫——繪本創作的持續探索與心態平衡」', '活動內容：　　我喜歡畫畫，但畫畫可以養活自己嗎？作為插畫工作者的嘎又，大學時期起從零開始接觸繪本，歷經赴外就讀童書插畫所、返臺後坐辦公室、兼職接案，十年來從無到有，用童趣自由的畫風、善於發現生活的眼睛，刻畫人與群體最純粹真實的聯繫。希望透過嘎又的心路歷程分享，讓參與的每個人更認識創作與生活的距離，也能與同為創作者的人產生一些共鳴。主講人：嘎又Gayo（插畫工作者、繪本創作者）活動時間：4月13日（日）14:00-16:00活動地點： 景新分館10樓視聽室（臺北市文山區景後街151號10樓）', '臺北市立圖書館', '無資料', '2025-03-18 00:00:00', '2025-04-13 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=ADA406B5CCF64B2B', '[]') ON DUPLICATE KEY UPDATE `activity_name`='景新分館多元閱讀推廣系列講座「即使如此還是想畫畫——繪本創作的持續探索與心態平衡」', `description`='活動內容：　　我喜歡畫畫，但畫畫可以養活自己嗎？作為插畫工作者的嘎又，大學時期起從零開始接觸繪本，歷經赴外就讀童書插畫所、返臺後坐辦公室、兼職接案，十年來從無到有，用童趣自由的畫風、善於發現生活的眼睛，刻畫人與群體最純粹真實的聯繫。希望透過嘎又的心路歷程分享，讓參與的每個人更認識創作與生活的距離，也能與同為創作者的人產生一些共鳴。主講人：嘎又Gayo（插畫工作者、繪本創作者）活動時間：4月13日（日）14:00-16:00活動地點： 景新分館10樓視聽室（臺北市文山區景後街151號10樓）', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-18 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=ADA406B5CCF64B2B', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9375855', '北投就業服務站將於114年3月25日(週二)下午2-4時辦理【萬金國際科技股份有限公司】微型徵才活動', '北投就業服務站將於114年3月25日(週二)下午2-4時辦理【萬金國際科技股份有限公司】微型徵才活動活動時間：3月25日(二)下午2:00~4:00活動地點：北投就業服務站 (臺北市北投區新市街30號5樓)洽詢電話：(02)28981819#115職務名稱：(北投/內湖)軌道勞務需求人數：5學歷要求：不拘工作經驗：無經驗可、有證照佳工作內容：1.負責捷運巡視工作。2.執行其它維護相關交辦 &nbsp; 事項。3.員工須配合督導安排輪班、調班及調站事宜維修 (無經驗可、有臺北捷運承商証者佳)薪資待遇：月薪33300元(月薪31500元、全勤獎金1800元、大修津貼250元/天)工作時間：23:00-07:00工作地點：北投機廠/內湖機廠職務名稱：(臺北捷運) 中山地下街或東區地下街助理技術員需求人數：2學歷要求：高中職以上工作經驗：不拘工作內容：1.工作地點現場設施設備巡檢，報修及完修工單確認作業。2.工作地點現場施工監督、水電抄表計價及履約管理作業。3.工作地點清潔、保全等承商管理作業。4.工作地點旅客諮詢服務、遺失物處理作業。5.檔案彙整、消耗性物品申請作業、會議及走動管理列管案件彙整作業，或其它依機關臨時指派之服務事項。6.現場臨時交辦事項與緊急狀況處理。薪資待遇：月薪34275元工作時間：輪班，7:00-15:00/8:30-17:30/15:00-23:00工作地點：臺北捷運中山地下街或東區地下街職務名稱：(淡水捷運站)停車場管理員需求人數：2學歷要求：高中職以上工作經驗：不拘工作內容：1.工作地點現場設施設備巡檢，報修及完修工單確認作業。2.工作地點現場施工監督、水電抄表計價及履約管理作業。3.工作地點清潔、保全等承商管理作業。4.工作地點旅客諮詢服務、遺失物處理作業。5.停車場票證管理(含票證販售、現金結帳投袋、含全自動繳費機結帳等)。6.停車場場務管理(含隔夜車查核、身障格位佔用處理、車流引導、閉錄電視監控及操作、門禁管制等)。7.檔案彙整、消耗性物品申請作業、會議及走動管理列管案件彙整作業，或其它依機關臨時指派之服務事項。8.現場臨時交辦事項與緊急狀況處理。薪資待遇：月薪34275元工作時間：輪班，6:30-14:30/14:20-22:20/22:10-6:40工作地點：淡水捷運站', '北投就業服務站', '台北市北投區新市街30號5樓', '2025-03-25 00:00:00', '2025-03-25 00:00:00', '北投就業服務站', 25.1480682, 121.5177992, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F7B4B1568B5274E1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='北投就業服務站將於114年3月25日(週二)下午2-4時辦理【萬金國際科技股份有限公司】微型徵才活動', `description`='北投就業服務站將於114年3月25日(週二)下午2-4時辦理【萬金國際科技股份有限公司】微型徵才活動活動時間：3月25日(二)下午2:00~4:00活動地點：北投就業服務站 (臺北市北投區新市街30號5樓)洽詢電話：(02)28981819#115職務名稱：(北投/內湖)軌道勞務需求人數：5學歷要求：不拘工作經驗：無經驗可、有證照佳工作內容：1.負責捷運巡視工作。2.執行其它維護相關交辦 &nbsp; 事項。3.員工須配合督導安排輪班、調班及調站事宜維修 (無經驗可、有臺北捷運承商証者佳)薪資待遇：月薪33300元(月薪31500元、全勤獎金1800元、大修津貼250元/天)工作時間：23:00-07:00工作地點：北投機廠/內湖機廠職務名稱：(臺北捷運) 中山地下街或東區地下街助理技術員需求人數：2學歷要求：高中職以上工作經驗：不拘工作內容：1.工作地點現場設施設備巡檢，報修及完修工單確認作業。2.工作地點現場施工監督、水電抄表計價及履約管理作業。3.工作地點清潔、保全等承商