INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67afafc726b3240c403d958e', '靜心慢活瑜珈B班', '瑜珈養生由淺而深，反覆練習，正確示範安全動作講解，讓學員易懂，以有趣的學習方式進行教學。\n\n瑜珈能使人健康，心靈提昇，推廣瑜珈為全民運動，提高公民素養。', '國立彰化生活美學館', '500  彰化縣彰化市卦山路18號', '2025-04-11 00:00:00', '2025-06-13 00:00:00', '舞蹈教室', 24.0768296, 120.5585119, '1500', 'https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50329', '[]') ON DUPLICATE KEY UPDATE `activity_name`='靜心慢活瑜珈B班', `description`='瑜珈養生由淺而深，反覆練習，正確示範安全動作講解，讓學員易懂，以有趣的學習方式進行教學。\n\n瑜珈能使人健康，心靈提昇，推廣瑜珈為全民運動，提高公民素養。', `organizer`='國立彰化生活美學館', `address`='500  彰化縣彰化市卦山路18號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-06-13 00:00:00', `location`='舞蹈教室', `latitude`=24.0768296, `longitude`=120.5585119, `ticket_price`='1500', `source_url`='https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50329', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80beb26b3240c403d979f', '【新開班】創藝科技玩家(適3-5年級)', '★本課程開班標準：報名繳費達9人。 \n\n★授課老師：陳亞馨老師\n\n★課程主題及教學內容將依學員程度及學習狀況斟酌調整\n\n★需自備平板、文具用品、剪刀。\n\n※平板規格：可安裝「octostudio」 App (請於課前完成下載與安裝)\n\n \n\n\n	\n		\n			\n			堂數\n			\n			\n			日期\n			\n			\n			課 程 主 題\n			\n			\n			教 學 內 容\n			\n		\n		\n			\n			1\n			\n			\n			5/3\n			\n			\n			Octostudio基礎功能\n			\n			\n			\n				介紹Octostudio介面與基本功能\n				理解積木型程式語言的運作\n				完成簡單的互動效果\n			\n			\n		\n		\n			\n			2\n			\n			\n			5/10\n			\n			\n			Octostudio互動電子書-基礎\n			\n			\n			\n				學習物件觸發效果\n				自製簡單互動電子書\n			\n			\n		\n		\n			\n			3\n			\n			\n			5/17\n			\n			\n			Octostudio互動電子書-聲音\n			\n			\n			\n				加入音樂與音效功能\n				改變視覺效果\n			\n			\n		\n		\n			\n			4\n			\n			\n			5/24\n			\n			\n			Octostudio互動電子書-創作\n			\n			\n			\n				改編經典故事\n				設計自己的角色與場景，製作互動電子書\n			\n			\n		\n		\n			\n			停課\n			\n			\n			5/31\n			\n			\n			端午節連假\n			\n		\n		\n			\n			5\n			\n			\n			6/7\n			\n			\n			Octostudio體感遊戲-賽車\n			\n			\n			\n				自製方向盤\n				運用程式設計一款賽車遊戲\n			\n			\n		\n		\n			\n			6\n			\n			\n			6/14\n			\n			\n			Octostudio體感遊戲-收集\n			\n			\n			\n				繪製收集物品\n				運用程式設計一款收集遊戲\n			\n			\n		\n		\n			\n			7\n			\n			\n			6/21\n			\n			\n			Octostudio體感遊戲-球類\n			\n			\n			1.運用程式設計一款球類遊戲\n\n			2.實際玩遊戲並調整設定\n			\n		\n		\n			\n			8\n			\n			\n			6/28\n			\n			\n			Octostudio電玩遊戲-\n\n			料理遊戲\n			\n			\n			1.認識料理製作過程\n\n			2.運用程式設計一款料理遊戲\n			\n		\n		\n			\n			9\n			\n			\n			7/5\n			\n			\n			Octostudio電玩遊戲-\n\n			迷宮遊戲\n			\n			\n			\n				設計紙本迷宮\n				運用程式設計設計一款迷宮遊戲\n			\n			\n		\n		\n			\n			10\n			\n			\n			7/12\n			\n			\n			Octostudio電玩遊戲-橫向捲軸小恐龍\n			\n			\n			\n				運用程式設計一款橫向捲軸遊戲\n				設計道具關卡\n			\n			\n		\n		\n			\n			11\n			\n			\n			7/19\n			\n			\n			Octostudio創意小專題\n\n			關於「我」的動畫\n			\n			\n			綜合上述所學，製作一款關於自己的動畫故事，包含自己的興趣、愛好等\n			\n		\n		\n			\n			12\n			\n			\n			7/26\n			\n			\n			Octostudio創意小專題關於「我」的遊戲\n			\n			\n			隨機抽選題目，讓學生創意發想遊戲\n			\n		\n		\n			\n			13\n			\n			\n			8/2\n			\n			\n			期末專題分享\n			\n			\n			期末分享會，統整所學與分享心得\n			\n		\n	\n\n\n上課教室位置圖\n\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-03 00:00:00', '2025-08-02 00:00:00', '303教室', 25.0367564, 121.519047, '3900', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50713', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新開班】創藝科技玩家(適3-5年級)', `description`='★本課程開班標準：報名繳費達9人。 \n\n★授課老師：陳亞馨老師\n\n★課程主題及教學內容將依學員程度及學習狀況斟酌調整\n\n★需自備平板、文具用品、剪刀。\n\n※平板規格：可安裝「octostudio」 App (請於課前完成下載與安裝)\n\n \n\n\n	\n		\n			\n			堂數\n			\n			\n			日期\n			\n			\n			課 程 主 題\n			\n			\n			教 學 內 容\n			\n		\n		\n			\n			1\n			\n			\n			5/3\n			\n			\n			Octostudio基礎功能\n			\n			\n			\n				介紹Octostudio介面與基本功能\n				理解積木型程式語言的運作\n				完成簡單的互動效果\n			\n			\n		\n		\n			\n			2\n			\n			\n			5/10\n			\n			\n			Octostudio互動電子書-基礎\n			\n			\n			\n				學習物件觸發效果\n				自製簡單互動電子書\n			\n			\n		\n		\n			\n			3\n			\n			\n			5/17\n			\n			\n			Octostudio互動電子書-聲音\n			\n			\n			\n				加入音樂與音效功能\n				改變視覺效果\n			\n			\n		\n		\n			\n			4\n			\n			\n			5/24\n			\n			\n			Octostudio互動電子書-創作\n			\n			\n			\n				改編經典故事\n				設計自己的角色與場景，製作互動電子書\n			\n			\n		\n		\n			\n			停課\n			\n			\n			5/31\n			\n			\n			端午節連假\n			\n		\n		\n			\n			5\n			\n			\n			6/7\n			\n			\n			Octostudio體感遊戲-賽車\n			\n			\n			\n				自製方向盤\n				運用程式設計一款賽車遊戲\n			\n			\n		\n		\n			\n			6\n			\n			\n			6/14\n			\n			\n			Octostudio體感遊戲-收集\n			\n			\n			\n				繪製收集物品\n				運用程式設計一款收集遊戲\n			\n			\n		\n		\n			\n			7\n			\n			\n			6/21\n			\n			\n			Octostudio體感遊戲-球類\n			\n			\n			1.運用程式設計一款球類遊戲\n\n			2.實際玩遊戲並調整設定\n			\n		\n		\n			\n			8\n			\n			\n			6/28\n			\n			\n			Octostudio電玩遊戲-\n\n			料理遊戲\n			\n			\n			1.認識料理製作過程\n\n			2.運用程式設計一款料理遊戲\n			\n		\n		\n			\n			9\n			\n			\n			7/5\n			\n			\n			Octostudio電玩遊戲-\n\n			迷宮遊戲\n			\n			\n			\n				設計紙本迷宮\n				運用程式設計設計一款迷宮遊戲\n			\n			\n		\n		\n			\n			10\n			\n			\n			7/12\n			\n			\n			Octostu