INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bf226b3240c403d981e', '兒童體適能(適幼兒園大班-3年級)', '★本課程開班標準：報名繳費達11人。 \n\n★授課師資：謝如容老師\n\n★前期(114年1-4月)課程表  供參考\n\n★課程主題及教學內容將依學員程度及學習狀況斟酌調整\n\n\n	\n		\n			\n			堂數\n			\n			\n			日期\n			\n			\n			課程主題\n			\n			\n			教學內容\n			\n		\n		\n			\n			1\n			\n			\n			5/3\n			\n			\n			繩梯\n			\n			\n			訓練心肺及敏捷性\n\n			以循序漸進的方式進行課程，如走到跑、快到慢等等\n			\n		\n		\n			\n			2\n			\n			\n			5/10\n			\n			\n			足球\n			\n			\n			訓練學生的心肺及協調力\n\n			運用簡易的足球比賽培養團隊合作的能力\n			\n		\n		\n			\n			3\n			\n			\n			5/17\n			\n			\n			跳繩\n			\n			\n			訓練學生的心肺耐力及手腳協調\n\n			了解基本跳繩動作並以節奏音樂增加心肺能力\n			\n		\n		\n			\n			4\n			\n			\n			5/24\n			\n			\n			躲避球\n			\n			\n			訓練學生的頭手眼協調及反應力\n\n			了解躲避球基本規則，運用簡單規則進行比賽\n			\n		\n		\n			\n			停課\n			\n			\n			5/31\n			\n			\n			端午節連假\n			\n		\n		\n			\n			5\n			\n			\n			6/7\n			\n			\n			小布球、圓盤墊\n			\n			\n			訓練學生的反應力及專注力\n\n			培養團隊合作能力以及提升丟擲能力\n			\n		\n		\n			\n			6\n			\n			\n			6/14\n			\n			\n			力波墊\n			\n			\n			訓練學生平衡性及協調性\n\n			了解基本翻滾動作並訓練協調性\n			\n		\n		\n			\n			7\n			\n			\n			6/21\n			\n			\n			聰明小8\n			\n			\n			訓練學生敏捷性及團隊合作能力\n\n			讓學生學習前後移動能力，且尊重團隊合作之精神\n			\n		\n		\n			\n			8\n			\n			\n			6/28\n			\n			\n			巧拼\n			\n			\n			訓練學生的平衡感及心肺耐力\n\n			以趣味競賽之模式，使學生能與同儕共同合作完成遊戲任務\n			\n		\n		\n			\n			9\n			\n			\n			7/5\n			\n			\n			籃球\n			\n			\n			訓練學生的肌力及協調性\n\n			練習投籃技巧及團隊合作能力\n			\n		\n		\n			\n			10\n			\n			\n			7/12\n			\n			\n			麻繩\n			\n			\n			訓練學生的心肺及爆發力\n\n			運用音樂節奏帶著學生一起訓練心肺能力\n			\n		\n		\n			\n			11\n			\n			\n			7/19\n			\n			\n			動態平衡組\n			\n			\n			訓練學生靜動態平衡\n\n			加強學生的平衡能力及增加球感，且讓他們了解到團隊合作的重要性\n			\n		\n		\n			\n			12\n			\n			\n			7/26\n			\n			\n			跳箱、平衡木\n			\n			\n			訓練學生的協調及平衡能力\n\n			了解跳箱基本動作及專注力\n			\n		\n		\n			\n			13\n			\n			\n			8/2\n			\n			\n			軟式彈力帶\n			\n			\n			訓練學生手部肌耐力及平衡能力\n\n			會以遊戲模式進行課程，讓課程不無聊或只有單一動作\n			\n		\n		\n			\n