INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d8e6628f15adefa04e0c80', '《所在 - 物件離合》許旭倫陶藝創作展', '陶土，經烈焰千錘百鍊，從鬆散的泥土凝結成形，在烈焰中裂變、交融，最終成為具有時間痕跡與獨特語彙的創作。許旭倫老師的作品，正是在這樣的過程中，與環境對話，與時間共鳴，映照出「所在」與「離合」的詩意思考。\r\n\r\n本次展覽 《所在 - 物件離合》，是許旭倫老師對物件、空間與變遷的深刻探問。創作不僅僅是對形式的塑造，更是對時間、記憶、環境變遷的回應。作品表面肌理細膩，層層疊疊的紋理宛如歲月刻畫出的印記，展現陶土經歷火焰洗禮後的生命力。裂隙之間，或許有金光閃爍，或許有虛實交錯的構造，那不僅是材質的延伸，更象徵著聚合與分離、消逝與新生之間的微妙關係。\r\n\r\n展覽資訊\r\n展覽名稱｜【所在 - 物件離合】許旭倫陶藝創作展\r\n展覽期間｜2025.04.04－2025.05.26\r\n開幕茶會｜2025.04.13 (Sun.) 15:00開放時間｜**10:00－19:00（每月一、三週之星期二休館）\r\n展覽地點｜光點藝術中心 三樓展覽廳\r\n展覽地址｜新北市鶯歌區陶瓷街18號\r\n展覽專線｜02-2678-6577\r\n\r\n這是一場陶土與時間、火焰與空間的對話，誠摯邀請您走進展覽現場，親身感受陶藝創作的溫度與哲思！', '鶯歌光點美學館', '新北市鶯歌區陶瓷街18號3F', '2025-04-04 00:00:00', '2025-05-26 00:00:00', '光點藝術中心', 24.9566258, 121.3466269, '無資料', 'https://www.yinggo.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《所在 - 物件離合》許旭倫陶藝創作展', `description`='陶土，經烈焰千錘百鍊，從鬆散的泥土凝結成形，在烈焰中裂變、交融，最終成為具有時間痕跡與獨特語彙的創作。許旭倫老師的作品，正是在這樣的過程中，與環境對話，與時間共鳴，映照出「所在」與「離合」的詩意思考。\r\n\r\n本次展覽 《所在 - 物件離合》，是許旭倫老師對物件、空間與變遷的深刻探問。創作不僅僅是對形式的塑造，更是對時間、記憶、環境變遷的回應。作品表面肌理細膩，層層疊疊的紋理宛如歲月刻畫出的印記，展現陶土經歷火焰洗禮後的生命力。裂隙之間，或許有金光閃爍，或許有虛實交錯的構造，那不僅是材質的延伸，更象徵著聚合與分離、消逝與新生之間的微妙關係。\r\n\r\n展覽資訊\r\n展覽名稱｜【所在 - 物件離合】許旭倫陶藝創作展\r\n展覽期間｜2025.04.04－2025.05.26\r\n開幕茶會｜2025.04.13 (Sun.) 15:00開放時間｜**10:00－19:00（每月一、三週之星期二休館）\r\n展覽地點｜光點藝術中心 三樓展覽廳\r\n展覽地址｜新北市鶯歌區陶瓷街18號\r\n展覽專線｜02-2678-6577\r\n\r\n這是一場陶土與時間、火焰與空間的對話，誠摯邀請您走進展覽現場，親身感受陶藝創作的溫度與哲思！', `organizer`='鶯歌光點美學館', `address`='新北市鶯歌區陶瓷街18號3F', `start_date`='2025-04-04 00:00:00', `end_date`='2025-05-26 00:00:00', `location`='光點藝術中心', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='https://www.yinggo.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d905b28f15adefa04e0c81', '《日子在說話 The Days Speak》張文菀個展', '│關於展覽│\r\n\r\n當物品開口說話，你會聽見什麼？\r\n在本次展覽中，藝術家張文菀透過對物件的詮釋，讓觀者意識到自身對世界的理解是如何被習慣塑造的。張文菀的作品擅長透過幽默與反思，鬆動既定的符號系統，讓尋常事物獲得新的生命。她的創作不只是對日常的描繪，更是對觀看習慣的挑戰——當鉛筆自稱為魔杖，當衣架懸掛的不只是衣物，而是意義本身，這些看似平凡的物件開始訴說我們未曾察覺的故事。\r\n\r\n我們如何賦予物品意義？物品如何反映我們的思維與情感？在這場展覽中，每一個細節都是一則等待被解讀的寓言，邀請你以新的方式觀看、思考，並重新認識那些「看似」熟悉的日常。', '當代一畫廊', '臺北市松山區光復南路22巷32號1樓', '2025-03-28 00:00:00', '2025-03-28 00:00:00', '當代一畫廊', 25.05999101, 121.5575876, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《日子在說話 The Days Speak》張文菀個展', `description`='│關於展覽│\r\n\r\n當物品開口說話，你會聽見什麼？\r\n在本次展覽中，藝術家張文菀透過對物件的詮釋，讓觀者意識到自身對世界的理解是如何被習慣塑造的。張文菀的作品擅長透過幽默與反思，鬆動既定的符號系統，讓尋常事物獲得新的生命。她的創作不只是對日常的描繪，更是對觀看習慣的挑戰——當鉛筆自稱為魔杖，當衣架懸掛的不只是衣物，而是意義本身，這些看似平凡的物件開始訴說我們未曾察覺的故事。\r\n\r\n我們如何賦予物品意義？物品如何反映我們的思維與情感？在這場展覽中，每一個細節都是一則等待被解讀的寓言，邀請你以新的方式觀看、思考，並重新認識那些「看似」熟悉的日常。', `organizer`='當代一畫廊', `address`='臺北市松山區光復南路22巷32號1樓', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='當代一畫廊', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d91af58f15adefa04e0c82', '順益台灣原住民博物館2025年4月兒童節特別活動', '4月兒童節特別活動出爐囉\r\n聽．原住民說故事\r\n原住民繪本故事 | 導覽 | 故事闖關遊戲 | 原風明信片DIY！\r\n快來加入我們，一同走進原住民的故事吧\r\n\r\n小朋友不僅可以靜心聆聽充滿智慧的繪本故事，還能透過專人導覽了解展品的故事，參與趣味闖關遊戲，以及動手設計一張獨一無二的原住民風格明信片！\r\n\r\n透過這場寓教於樂的文化冒險，小朋友將深刻體驗原住民豐富的文化傳統，並從故事中學習珍貴的生活智慧。 不論是用耳朵傾聽，用雙手創造，還是用心靈體驗，這都將是一次難忘的成長旅程！\r\n\r\n 活動日期： 2025/4/1-2025/4/13(日)\r\n活動時段：上午時段10:00-12:00；下午時段13:00~15:00\r\n活動地點： 順益台灣原住民博物館\r\n報名方式1(擇一)： https://forms.gle/FLEaArwkuqpv7zTo7\r\n報名方式2(擇一)：來電報名02-28412611轉115\r\n\r\n場次有限，快帶上孩子們來參加這場文化探索之旅吧！\r\n\r\n4月兒童超級專屬優惠\r\n全國12歲(含)以下兒童，持2025臺北兒童月「探索摺頁」參加兒童節特別活動，可再兌換卷卷百步蛇手作乙份帶回家，限量兩百份喔，送完就沒了唷', '順益台灣原住民博物館', '臺北市士林區至善路二段282號', '2025-04-01 00:00:00', '2025-04-01 00:00:00', '順益台灣原住民博物館', 25.12546704, 121.5508473, '學生優惠價200元(含門票、DIY材料)，教師免收費，家長陪同者門票80元', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='順益台灣原住民博物館2025年4月兒童節特別活動', `description`='4月兒童節特別活動出爐囉\r\n聽．原住民說故事\r\n原住民繪本故事 | 導覽 | 故事闖關遊戲 | 原風明信片DIY！\r\n快來加入我們，一同走進原住民的故事吧\r\n\r\n小朋友不僅可以靜心聆聽充滿智慧的繪本故事，還能透過專人導覽了解展品的故事，參與趣味闖關遊戲，以及動手設計一張獨一無二的原住民風格明信片！\r\n\r\n透過這場寓教於樂的文化冒險，小朋友將深刻體驗原住民豐富的文化傳統，並從故事中學習珍貴的生活智慧。 不論是用耳朵傾聽，用雙手創造，還是用心靈體驗，這都將是一次難忘的成長旅程！\r\n\r\n 活動日期： 2025/4/1-2025/4/13(日)\r\n活動時段：上午時段10:00-12:00；下午時段13:00~15:00\r\n活動地點： 順益台灣原住民博物館\r\n報名方式1(擇一)： https://forms.gle/FLEaArwkuqpv7zTo7\r\n報名方式2(擇一)：來電報名02-28412611轉115\r\n\r\n場次有限，快帶上孩子們來參加這場文化探索之旅吧！\r\n\r\n4月兒童超級專屬優惠\r\n全國12歲(含)以下兒童，持2025臺北兒童月「探索摺頁」參加兒童節特別活動，可再兌換卷卷百步蛇手作乙份帶回家，限量兩百份喔，送完就沒了唷', `organizer`='順益台灣原住民博物館', `address`='臺北市士林區至善路二段282號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-01 00:00:00', `location`='順益台灣原住民博物館', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='學生優惠價200元(含門票、DIY材料)，教師免收費，家長陪同者門票80元', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d920dd8f15adefa04e0c83', 'EMBA雜誌「給自己的10堂管理大師課」新書發表會', '給自己的10堂管理大師課\r\n新書分享會｜一場思想饗宴，一次與大師對話的機會\r\n\r\n百年古蹟×榻榻米×穿越時光的智慧交流\r\n多年來，EMBA雜誌總編輯方素惠專訪超過50位全球頂尖管理思想家，親炙世界級智慧，探索領導、創新、企業經營的深層思考。\r\n坐在人生的搖滾區，三十多年來我有機會遇見全世界最聰明的腦袋和最有智慧的典範，我有責任記錄下來，與更多人分享。—方素惠\r\n\r\n\r\n這場獨家讀者見面會，方素惠將親自分享她在第一線對話大師的學習心法、幕後故事，並公開全球頂尖管理思想家的獨家專訪影片，讓你感受最純粹的智慧衝擊！\r\n\r\n\r\n你將收穫：\r\n坐在人生的搖滾區，第一手學習10位管理大師的智慧\r\n深入探索領導、創新、決策與人生思維的關鍵洞察\r\n在百年古蹟的沉靜氛圍中，與志同道合的夥伴交流思想\r\n回答讀者提問，分享專訪大師的獨家影片\r\n\r\n\r\n活動資訊\r\n日期：4/16（三）19:00-20:30（18:30報到入場）\r\n地點：中山堂台北書院（台北市中正區延平南路98號3F）\r\n交通：捷運西門站5號出口，步行3分鐘\r\n報名表單：https://reurl.cc/RYnXLr\r\n\r\n\r\n活動憑書入場，請事先報名，座位有限，額滿為止（現場也可購書）\r\n\r\n\r\n\r\n服務專線：(02)2768-0105#211,213\r\nEmail：service2@emba.com.tw\r\n\r\n\r\n', 'EMBA雜誌', '臺北市中正區延平南路98號3F', '2025-04-16 00:00:00', '2025-04-16 00:00:00', '中山堂台北書院', 25.03240487, 121.5198839, '填寫活動表單報名，活動憑書入場，請事先報名，座位有限，額滿為止', 'https://reurl.cc/RYnXLr', '[]') ON DUPLICATE KEY UPDATE `activity_name`='EMBA雜誌「給自己的10堂管理大師課」新書發表會', `description`='給自己的10堂管理大師課\r\n新書分享會｜一場思想饗宴，一次與大師對話的機會\r\n\r\n百年古蹟×榻榻米×穿越時光的智慧交流\r\n多年來，EMBA雜誌總編輯方素惠專訪超過50位全球頂尖管理思想家，親炙世界級智慧，探索領導、創新、企業經營的深層思考。\r\n坐在人生的搖滾區，三十多年來我有機會遇見全世界最聰明的腦袋和最有智慧的典範，我有責任記錄下來，與更多人分享。—方素惠\r\n\r\n\r\n這場獨家讀者見面會，方素惠將親自分享她在第一線對話大師的學習心法、幕後故事，並公開全球頂尖管理思想家的獨家專訪影片，讓你感受最純粹的智慧衝擊！\r\n\r\n\r\n你將收穫：\r\n坐在人生的搖滾區，第一手學習10位管理大師的智慧\r\n深入探索領導、創新、決策與人生思維的關鍵洞察\r\n在百年古蹟的沉靜氛圍中，與志同道合的夥伴交流思想\r\n回答讀者提問，分享專訪大師的獨家影片\r\n\r\n\r\n活動資訊\r\n日期：4/16（三）19:00-20:30（18:30報到入場）\r\n地點：中山堂台北書院（台北市中正區延平南路98號3F）\r\n交通：捷運西門站5號出口，步行3分鐘\r\n報名表單：https://reurl.cc/RYnXLr\r\n\r\n\r\n活動憑書入場，請事先報名，座位有限，額滿為止（現場也可購書）\r\n\r\n\r\n\r\n服務專線：(02)2768-0105#211,213\r\nEmail：service2@emba.com.tw\r\n\r\n\r\n', `organizer`='EMBA雜誌', `address`='臺北市中正區延平南路98號3F', `start_date`='2025-04-16 00:00:00', `end_date`='2025-04-16 00:00:00', `location`='中山堂台北書院', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='填寫活動表單報名，活動憑書入場，請事先報名，座位有限，額滿為止', `source_url`='https://reurl.cc/RYnXLr', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d93df107f3d4433af95552', '唐律長笛合奏團四十一週年音樂會', '唐律長笛合奏團自1983年成立以來，致力於推廣長笛精緻音樂，並不斷追求長笛合奏和聲的飽滿與均衡，力求展現貼近原作、更勝原作的演出。此次音樂會囊括跨越國界跨越世代的各種曲目，透過不同風格的編曲和演出型態，呈現浪漫的情感、刻劃動人的旋律，是一場多樣而豐富的音樂饗宴。', '燈角樂團', '臺北市中正區中山南路21-1號', '2025-04-03 00:00:00', '2025-04-03 00:00:00', '國家兩廳院演奏廳', 25.03240487, 121.5198839, 'NT.600。OPENTIX兩廳院文化生活 ', 'https://www.opentix.life/event/1876554016436432897', '[]') ON DUPLICATE KEY UPDATE `activity_name`='唐律長笛合奏團四十一週年音樂會', `description`='唐律長笛合奏團自1983年成立以來，致力於推廣長笛精緻音樂，並不斷追求長笛合奏和聲的飽滿與均衡，力求展現貼近原作、更勝原作的演出。此次音樂會囊括跨越國界跨越世代的各種曲目，透過不同風格的編曲和演出型態，呈現浪漫的情感、刻劃動人的旋律，是一場多樣而豐富的音樂饗宴。', `organizer`='燈角樂團', `address`='臺北市中正區中山南路21-1號', `start_date`='2025-04-03 00:00:00', `end_date`='2025-04-03 00:00:00', `location`='國家兩廳院演奏廳', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='NT.600。OPENTIX兩廳院文化生活 ', `source_url`='https://www.opentix.life/event/1876554016436432897', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d93ee307f3d4433af95553', '朱志祥鋼琴獨奏會 - 兒時情景', '音樂，是穿越時間與空間的魔法。本場音樂會發想是從藝術家的3歲兒子受到啟發，相信每個人孩童時期對於音樂的好奇心與所有事物的好奇心都是最純真無瑕且最具能量的。藉由這次的曲目編排將帶領觀眾從純真的童年記憶出發，穿越浪漫的情感漩渦，最終到達炙熱與狂放的巔峰，展現鋼琴音樂豐富的情感層次與無限的可能性。\r\n\r\n \r\n\r\n\r\n上半場的曲目以舒曼的《兒時情景》（Kinderszenen, Op. 15）拉開序幕，這部作品捕捉了童年的純真與夢幻，特別是其中的〈夢幻曲〉更是無數人心中的永恆經典。隨後，德布西的《兒童天地》（Children''s Corner）為我們帶來法國印象派的繽紛與想像力，以音符描繪兒童的嬉戲與幻想，充滿靈動的畫面感；下半場則是以鋼琴家回憶青年時期所演奏的曲目為主題，用目前稍長的年紀帶領聽眾回味青年時的激昂情感。首先，蕭邦的C大調練習曲（Op.10 No.1）以如浪潮般的和弦展現技術的巔峰，接著是G小調第一敘事曲（Op.23），描繪了內心的激盪與英雄氣概。隨後，李斯特的F小調超技練習曲（No.10）展現了作曲家對力量與抒情的極致平衡。而壓軸的《梅菲斯特圓舞曲第一號》（Mephisto Waltz No. 1, S.514），以炙熱的激情與狂歡將全場推向高潮，宛如魔鬼的舞步般令人目眩神迷。 \r\n\r\n\r\n\r\n這是一場從童真到青年狂熱、從抒情到澎湃的音樂旅程，誠摯邀請您一同體驗這場心靈的洗禮與藝術的饗宴。', '燈角樂團', '臺北市中正區中山南路21-1號', '2025-04-05 00:00:00', '2025-04-05 00:00:00', '國家兩廳院演奏廳', 25.03240487, 121.5198839, 'NT.600 、800 、1,200 、2,000。OPENTIX兩廳院文化生活', 'https://www.opentix.life/event/1876817806154350593', '[]') ON DUPLICATE KEY UPDATE `activity_name`='朱志祥鋼琴獨奏會 - 兒時情景', `description`='音樂，是穿越時間與空間的魔法。本場音樂會發想是從藝術家的3歲兒子受到啟發，相信每個人孩童時期對於音樂的好奇心與所有事物的好奇心都是最純真無瑕且最具能量的。藉由這次的曲目編排將帶領觀眾從純真的童年記憶出發，穿越浪漫的情感漩渦，最終到達炙熱與狂放的巔峰，展現鋼琴音樂豐富的情感層次與無限的可能性。\r\n\r\n \r\n\r\n\r\n上半場的曲目以舒曼的《兒時情景》（Kinderszenen, Op. 15）拉開序幕，這部作品捕捉了童年的純真與夢幻，特別是其中的〈夢幻曲〉更是無數人心中的永恆經典。隨後，德布西的《兒童天地》（Children''s Corner）為我們帶來法國印象派的繽紛與想像力，以音符描繪兒童的嬉戲與幻想，充滿靈動的畫面感；下半場則是以鋼琴家回憶青年時期所演奏的曲目為主題，用目前稍長的年紀帶領聽眾回味青年時的激昂情感。首先，蕭邦的C大調練習曲（Op.10 No.1）以如浪潮般的和弦展現技術的巔峰，接著是G小調第一敘事曲（Op.23），描繪了內心的激盪與英雄氣概。隨後，李斯特的F小調超技練習曲（No.10）展現了作曲家對力量與抒情的極致平衡。而壓軸的《梅菲斯特圓舞曲第一號》（Mephisto Waltz No. 1, S.514），以炙熱的激情與狂歡將全場推向高潮，宛如魔鬼的舞步般令人目眩神迷。 \r\n\r\n\r\n\r\n這是一場從童真到青年狂熱、從抒情到澎湃的音樂旅程，誠摯邀請您一同體驗這場心靈的洗禮與藝術的饗宴。', `organizer`='燈角樂團', `address`='臺北市中正區中山南路21-1號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-05 00:00:00', `location`='國家兩廳院演奏廳', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='NT.600 、800 、1,200 、2,000。OPENTIX兩廳院文化生活', `source_url`='https://www.opentix.life/event/1876817806154350593', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d93fa507f3d4433af95554', '鋼琴合作藝術聲樂篇系列音樂會（一）/ 英國藝術歌曲', '在鋼琴合作領域中，「聲樂合作」是一門相當複雜且深奧的學問，尤其是有關「藝術歌曲」的彈奏，最能展現鋼琴合作家之演奏功力及內涵。鋼琴家不僅需協助聲樂家的演唱，更需在演奏之中將詩詞的意境表達到最極致。\r\n\r\n \r\n\r\n這是一場系列音樂會的開端，主要目的在於探究「聲樂合作藝術」之精髓，從中體會鋼琴家如何協助歌者演唱及詮釋，並以英國為開端，讓聽眾認識英國作曲家及其藝術歌曲，徜徉在歌聲、詩詞及琴聲所交織的美好樂音裡。', '燈角樂團', '臺北市中正區中山南路21-1號', '2025-05-05 00:00:00', '2025-05-05 00:00:00', '國家兩廳院演奏廳', 25.03240487, 121.5198839, 'NT. 500 、800。OPENTIX兩廳院文化生活', 'https://www.opentix.life/event/1876479570442891265', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鋼琴合作藝術聲樂篇系列音樂會（一）/ 英國藝術歌曲', `description`='在鋼琴合作領域中，「聲樂合作」是一門相當複雜且深奧的學問，尤其是有關「藝術歌曲」的彈奏，最能展現鋼琴合作家之演奏功力及內涵。鋼琴家不僅需協助聲樂家的演唱，更需在演奏之中將詩詞的意境表達到最極致。\r\n\r\n \r\n\r\n這是一場系列音樂會的開端，主要目的在於探究「聲樂合作藝術」之精髓，從中體會鋼琴家如何協助歌者演唱及詮釋，並以英國為開端，讓聽眾認識英國作曲家及其藝術歌曲，徜徉在歌聲、詩詞及琴聲所交織的美好樂音裡。', `organizer`='燈角樂團', `address`='臺北市中正區中山南路21-1號', `start_date`='2025-05-05 00:00:00', `end_date`='2025-05-05 00:00:00', `location`='國家兩廳院演奏廳', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='NT. 500 、800。OPENTIX兩廳院文化生活', `source_url`='https://www.opentix.life/event/1876479570442891265', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9407e07f3d4433af95555', '「聽見蕭邦 2」簡孟軍鋼琴獨奏會', '自 2023 年初的聽見蕭邦(ㄧ)，鋼琴演奏家簡孟軍將於 2025年更深入的將 觀眾進入「聽見蕭邦」(二)的饗宴中。本次饗宴以多種蕭邦的曲風呈現多風貌的蕭 邦，在輕快中的圓舞曲中帶入蕭邦的舞蹈魅力、在波蘭舞曲中呈現英雄的氣息、在詼 諧曲中表達不同性格的對比、在優美的夜曲中表現出蕭邦的多愁善感，然而整場音樂 會以蕭邦的奏鳴曲第二號為重頭戲，這首奏鳴曲將蕭邦的樂曲帶出不同的層次，以大 型曲目及結構一探究竟蕭邦如何在作曲上呈現多風貌並合而為一的經典巨作。', '燈角樂團', '臺北市中正區中山南路21-1號', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '國家兩廳院演奏廳', 25.03240487, 121.5198839, 'NT. 500 、800。OPENTIX兩廳院文化生活 ', 'https://www.opentix.life/event/1888060977999339521', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「聽見蕭邦 2」簡孟軍鋼琴獨奏會', `description`='自 2023 年初的聽見蕭邦(ㄧ)，鋼琴演奏家簡孟軍將於 2025年更深入的將 觀眾進入「聽見蕭邦」(二)的饗宴中。本次饗宴以多種蕭邦的曲風呈現多風貌的蕭 邦，在輕快中的圓舞曲中帶入蕭邦的舞蹈魅力、在波蘭舞曲中呈現英雄的氣息、在詼 諧曲中表達不同性格的對比、在優美的夜曲中表現出蕭邦的多愁善感，然而整場音樂 會以蕭邦的奏鳴曲第二號為重頭戲，這首奏鳴曲將蕭邦的樂曲帶出不同的層次，以大 型曲目及結構一探究竟蕭邦如何在作曲上呈現多風貌並合而為一的經典巨作。', `organizer`='燈角樂團', `address`='臺北市中正區中山南路21-1號', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='國家兩廳院演奏廳', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='NT. 500 、800。OPENTIX兩廳院文化生活 ', `source_url`='https://www.opentix.life/event/1888060977999339521', `image_url`='[]';
