INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d71026b32419285b6fcd', '【新北市立圖書館樹林樂山圖書閱覽室】114年3月主題書展', '玩樂綠生活\r\n植物不僅可以淨化空氣、美化環境，加上一些獨特的創意巧思後，小盆栽馬上搖身一變成為吸睛焦點，打造的過程更充滿治癒心靈的魔力，趕快來打造自己的專屬花草園吧！\r\n\r\n活動時間：114年03月01日至03月31日\r\n\r\n活動地點︰樹林樂山圖書閱覽室主題展示區(樹林區中和街38號)\r\n \r\n洽詢電話：(02) 2680-7120\r\n \r\n※展示期間，歡迎借閱。', '新北市立圖書館總館', '新北市樹林區中和街38號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館樹林樂山圖書閱覽室', 24.97970609, 121.401034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館樹林樂山圖書閱覽室】114年3月主題書展', `description`='玩樂綠生活\r\n植物不僅可以淨化空氣、美化環境，加上一些獨特的創意巧思後，小盆栽馬上搖身一變成為吸睛焦點，打造的過程更充滿治癒心靈的魔力，趕快來打造自己的專屬花草園吧！\r\n\r\n活動時間：114年03月01日至03月31日\r\n\r\n活動地點︰樹林樂山圖書閱覽室主題展示區(樹林區中和街38號)\r\n \r\n洽詢電話：(02) 2680-7120\r\n \r\n※展示期間，歡迎借閱。', `organizer`='新北市立圖書館總館', `address`='新北市樹林區中和街38號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館樹林樂山圖書閱覽室', `latitude`=24.97970609, `longitude`=121.401034, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
