INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d71426b32419285b6fd3', '【新北市立圖書館泰山分館】114年3月「運轉語言腦」主題書展', '【泰山分館】3月份《閱讀書籤》主題書展\r\n【運轉語言腦】每人都有天生的語言天賦，只要找到適合自己的學習技巧，就能運轉內建大腦裡的語言腦。\r\n\r\n【童話世界】童話世界充滿著奇思妙想，任何可能皆存在，任何事都不奇怪。\r\n\r\n書展名稱：運轉語言腦/童話世界\r\n展出日期：114年3月1日至3月31日(開館時間)\r\n展出地點：泰山分館／5樓主題書展區(泰山區全興路212號5樓)\r\n連絡電話：2909-1727 服務台\r\n※書展期間歡迎借閱※', '新北市立圖書館總館', '新北市泰山區全興路212號5樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館泰山分館', 25.05549774, 121.4162785, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館泰山分館】114年3月「運轉語言腦」主題書展', `description`='【泰山分館】3月份《閱讀書籤》主題書展\r\n【運轉語言腦】每人都有天生的語言天賦，只要找到適合自己的學習技巧，就能運轉內建大腦裡的語言腦。\r\n\r\n【童話世界】童話世界充滿著奇思妙想，任何可能皆存在，任何事都不奇怪。\r\n\r\n書展名稱：運轉語言腦/童話世界\r\n展出日期：114年3月1日至3月31日(開館時間)\r\n展出地點：泰山分館／5樓主題書展區(泰山區全興路212號5樓)\r\n連絡電話：2909-1727 服務台\r\n※書展期間歡迎借閱※', `organizer`='新北市立圖書館總館', `address`='新北市泰山區全興路212號5樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館泰山分館', `latitude`=25.05549774, `longitude`=121.4162785, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d71426b32419285b6fd4', '【新北市立圖書館泰山貴子分館】114年3月「樂齡俱樂部」主題書展', '【泰山貴子分館】3月份《閱讀書籤》主題書展\r\n【樂齡俱樂部】這是一個專門為銀髮族設計的地方。從養身食譜、身體鍛鍊、醫學常識、理財規劃到心靈照顧。讓「樂齡俱樂部」幫你打造快樂人生下半場！\r\n\r\n【好忙的鳥兒】鳥兒一下子打開鮮豔的大尾巴；一下子抓樹幹裡的蟲子吃；一會兒伸長脖子，在湖面上悠閒地划呀划。我們一起來看看這些五彩繽紛的鳥兒在忙什麼吧！\r\n\r\n書展名稱：樂齡俱樂部/好忙的鳥兒\r\n展出日期：114年3月1日至3月31日(開館時間)\r\n展出地點：泰山貴子分館／3樓主題書展區(泰山區工專路22號3樓)\r\n連絡電話：2904-1923 服務台\r\n※書展期間歡迎借閱※', '新北市立圖書館總館', '新北市泰山區工專路22號3樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館泰山貴子分館', 25.05549774, 121.4162785, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館泰山貴子分館】114年3月「樂齡俱樂部」主題書展', `description`='【泰山貴子分館】3月份《閱讀書籤》主題書展\r\n【樂齡俱樂部】這是一個專門為銀髮族設計的地方。從養身食譜、身體鍛鍊、醫學常識、理財規劃到心靈照顧。讓「樂齡俱樂部」幫你打造快樂人生下半場！\r\n\r\n【好忙的鳥兒】鳥兒一下子打開鮮豔的大尾巴；一下子抓樹幹裡的蟲子吃；一會兒伸長脖子，在湖面上悠閒地划呀划。我們一起來看看這些五彩繽紛的鳥兒在忙什麼吧！\r\n\r\n書展名稱：樂齡俱樂部/好忙的鳥兒\r\n展出日期：114年3月1日至3月31日(開館時間)\r\n展出地點：泰山貴子分館／3樓主題書展區(泰山區工專路22號3樓)\r\n連絡電話：2904-1923 服務台\r\n※書展期間歡迎借閱※', `organizer`='新北市立圖書館總館', `address`='新北市泰山區工專路22號3樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館泰山貴子分館', `latitude`=25.05549774, `longitude`=121.4162785, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
