INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d71826b32419285b6fd8', '【新化演藝廳】荷絃箏樂團-醉美箏聲音', '2025春季音樂會，本場以古箏為主，輔以多元音樂素材的運用重新編曲，以重奏和齊奏的演出形式搭配打擊樂、人聲等，融合現代元素表現傳統文化之美、呈現多樣曲風。\r\n音樂會呈現經典樂曲【金蛇狂舞】【上春山】【男兒當自強】【步步高】迎接蛇年好運來，耳熟能詳的樂曲節奏輕快曲風溫馨【愛江山更愛美人】【大魚】【菊次郎的夏天】【勇氣大爆發】【你笑起來真好看】等，【臥虎藏龍】運用的獨特色彩，渲染出大漠飛揚、竹林見舞等具有武俠風格的音樂情境。音樂中情緒跌宕起伏、蕩氣迴腸，刻畫出如江湖兒女般的瀟灑自在與俠骨柔情。\r\n藉此深耕並推展古箏樂韻，達到雅俗共賞，視覺與聽覺的雙重悸動與體驗，要給聽眾不一樣的，用最震撼、最感動人心的樂音。[醉美箏聲音]與大家春天賞樂共享清音繞樑！', '臺南市政府文化局', '臺南市新化區信義路142-1號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '新化演藝廳', 23.03394545, 120.3357964, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新化演藝廳】荷絃箏樂團-醉美箏聲音', `description`='2025春季音樂會，本場以古箏為主，輔以多元音樂素材的運用重新編曲，以重奏和齊奏的演出形式搭配打擊樂、人聲等，融合現代元素表現傳統文化之美、呈現多樣曲風。\r\n音樂會呈現經典樂曲【金蛇狂舞】【上春山】【男兒當自強】【步步高】迎接蛇年好運來，耳熟能詳的樂曲節奏輕快曲風溫馨【愛江山更愛美人】【大魚】【菊次郎的夏天】【勇氣大爆發】【你笑起來真好看】等，【臥虎藏龍】運用的獨特色彩，渲染出大漠飛揚、竹林見舞等具有武俠風格的音樂情境。音樂中情緒跌宕起伏、蕩氣迴腸，刻畫出如江湖兒女般的瀟灑自在與俠骨柔情。\r\n藉此深耕並推展古箏樂韻，達到雅俗共賞，視覺與聽覺的雙重悸動與體驗，要給聽眾不一樣的，用最震撼、最感動人心的樂音。[醉美箏聲音]與大家春天賞樂共享清音繞樑！', `organizer`='臺南市政府文化局', `address`='臺南市新化區信義路142-1號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='新化演藝廳', `latitude`=23.03394545, `longitude`=120.3357964, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
