INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72126b32419285b6fdc', '【新北市立圖書館土城分館】114年3月份書展', '【新北市立圖書館土城分館】114年3月份書展\r\n3月樂齡書展「樂齡台灣小旅行」\r\n臺灣是美麗的寶島，有得天獨厚的美景與豐富的人文，還記得年輕時的熱門景點嗎？不論是舊的臺灣八景還是新的臺灣八景，總吸引人一遊再遊。您心目中的臺灣八景又是哪些地方呢？\r\n\r\n3月主題書展「植感生活趣」\r\n從三月的櫻花，到四月的桐花，土城的春天充滿植感，只要簡單步驟，在家也可以創造植感生活。\r\n\r\n展示期間：114年3月01日-3月31日／開館時間\r\n週二~週六，08:30~21:00\r\n週日~週一，08:30~17:00\r\n國定假日與清館日(每月最後一個星期四)不對外開放。\r\n書展場地：土城分館7樓書展區\r\n活動電話：02-22602952#9\r\n活動地址：土城區中正路18號7樓\r\n捷運：【板南線】土城站2號出口步行約2分鐘 \r\n公車：《中正路》707\r\n《土城農會站》705、707、805\r\n《土城區公所站》706、藍17、藍40 、847區繞駛土城醫院\r\n', '新北市立圖書館總館', '新北市土城區中正路18號7樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館土城分館', 24.96425102, 121.445737, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館土城分館】114年3月份書展', `description`='【新北市立圖書館土城分館】114年3月份書展\r\n3月樂齡書展「樂齡台灣小旅行」\r\n臺灣是美麗的寶島，有得天獨厚的美景與豐富的人文，還記得年輕時的熱門景點嗎？不論是舊的臺灣八景還是新的臺灣八景，總吸引人一遊再遊。您心目中的臺灣八景又是哪些地方呢？\r\n\r\n3月主題書展「植感生活趣」\r\n從三月的櫻花，到四月的桐花，土城的春天充滿植感，只要簡單步驟，在家也可以創造植感生活。\r\n\r\n展示期間：114年3月01日-3月31日／開館時間\r\n週二~週六，08:30~21:00\r\n週日~週一，08:30~17:00\r\n國定假日與清館日(每月最後一個星期四)不對外開放。\r\n書展場地：土城分館7樓書展區\r\n活動電話：02-22602952#9\r\n活動地址：土城區中正路18號7樓\r\n捷運：【板南線】土城站2號出口步行約2分鐘 \r\n公車：《中正路》707\r\n《土城農會站》705、707、805\r\n《土城區公所站》706、藍17、藍40 、847區繞駛土城醫院\r\n', `organizer`='新北市立圖書館總館', `address`='新北市土城區中正路18號7樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館土城分館', `latitude`=24.96425102, `longitude`=121.445737, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
