INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72126b32419285b6fe0', '【新北市立圖書館板橋浮洲圖書閱覽室】114年3月份書展', '【新北市立圖書館板橋浮洲圖書閱覽室】114年3月份書展\r\n3月樂齡書展「樂齡台灣小旅行」\r\n臺灣是美麗的寶島，有得天獨厚的美景與豐富的人文，還記得年輕時的熱門景點嗎？不論是舊的臺灣八景還是新的臺灣八景，總吸引人一遊再遊。您心目中的臺灣八景又是哪些地方呢？\r\n\r\n3月主題書展「植感生活趣」\r\n從三月的櫻花，到四月的桐花，土城的春天充滿植感，只要簡單步驟，在家也可以創造植感生活。\r\n\r\n展示期間：114年3月01日-3月31日／開館時間\r\n週二~週六，08:30~21:00\r\n週日~週一，08:30~17:00\r\n國定假日與清館日(每月最後一個星期四)不對外開放。\r\n書展場地：板橋浮洲圖書閱覽室2樓書展區\r\n地址：板橋區大觀路2段163號2樓\r\n電話：02-82751617\r\n\r\n公車：701、702、234(南下)、841(北上)→至板橋榮家→福德宮(右側門)至2樓即可到達。\r\n火車：浮洲火車站→(往南走)僑中二街→龍興街→大觀路二段140巷→向左轉→大觀路二段(114縣道)→向右轉120公尺即可到達。\r\n板橋浮洲圖書閱覽室位於浮洲福德宮2樓，請由福德宮右側樓梯上去即可到達。\r\n', '新北市立圖書館總館', '新北市板橋區大觀路二段163號2樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館板橋浮洲圖書閱覽室', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館板橋浮洲圖書閱覽室】114年3月份書展', `description`='【新北市立圖書館板橋浮洲圖書閱覽室】114年3月份書展\r\n3月樂齡書展「樂齡台灣小旅行」\r\n臺灣是美麗的寶島，有得天獨厚的美景與豐富的人文，還記得年輕時的熱門景點嗎？不論是舊的臺灣八景還是新的臺灣八景，總吸引人一遊再遊。您心目中的臺灣八景又是哪些地方呢？\r\n\r\n3月主題書展「植感生活趣」\r\n從三月的櫻花，到四月的桐花，土城的春天充滿植感，只要簡單步驟，在家也可以創造植感生活。\r\n\r\n展示期間：114年3月01日-3月31日／開館時間\r\n週二~週六，08:30~21:00\r\n週日~週一，08:30~17:00\r\n國定假日與清館日(每月最後一個星期四)不對外開放。\r\n書展場地：板橋浮洲圖書閱覽室2樓書展區\r\n地址：板橋區大觀路2段163號2樓\r\n電話：02-82751617\r\n\r\n公車：701、702、234(南下)、841(北上)→至板橋榮家→福德宮(右側門)至2樓即可到達。\r\n火車：浮洲火車站→(往南走)僑中二街→龍興街→大觀路二段140巷→向左轉→大觀路二段(114縣道)→向右轉120公尺即可到達。\r\n板橋浮洲圖書閱覽室位於浮洲福德宮2樓，請由福德宮右側樓梯上去即可到達。\r\n', `organizer`='新北市立圖書館總館', `address`='新北市板橋區大觀路二段163號2樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館板橋浮洲圖書閱覽室', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72226b32419285b6fe1', '【新北市立圖書館板橋民生圖書閱覽室】114年3月《閱讀書籤》「退休生活規劃」主題書展', '【板橋民生圖書閱覽室】114年3月《閱讀書籤》主題書展\r\n書展名稱：義大利圖書精選主題書展\r\n展出日期：113年3月1日至3月31日\r\n開放時間：週二至週六 8時30分至21時；週日至週一 8時30分至17時\r\n展示地點：新北市板橋區民生路一段30號 / 2樓書展區\r\n主題說明：本次書展展出有關於退休後，不僅要面臨生活型態的改變，還需考量財務狀況、身體素質等問題。因此，到底該如何規劃，才能避免上述情況發生，並享有高品質的晚年人生？\r\n備註：書展展示期間，歡迎借閱；3月27日為清館日，不對外開放。', '新北市立圖書館總館', '新北市板橋區民生路一段30號2樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館板橋民生圖書閱覽室', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館板橋民生圖書閱覽室】114年3月《閱讀書籤》「退休生活規劃」主題書展', `description`='【板橋民生圖書閱覽室】114年3月《閱讀書籤》主題書展\r\n書展名稱：義大利圖書精選主題書展\r\n展出日期：113年3月1日至3月31日\r\n開放時間：週二至週六 8時30分至21時；週日至週一 8時30分至17時\r\n展示地點：新北市板橋區民生路一段30號 / 2樓書展區\r\n主題說明：本次書展展出有關於退休後，不僅要面臨生活型態的改變，還需考量財務狀況、身體素質等問題。因此，到底該如何規劃，才能避免上述情況發生，並享有高品質的晚年人生？\r\n備註：書展展示期間，歡迎借閱；3月27日為清館日，不對外開放。', `organizer`='新北市立圖書館總館', `address`='新北市板橋區民生路一段30號2樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館板橋民生圖書閱覽室', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72326b32419285b6fe2', '創作講座3月(3場)', '透過高科技工具3D列印筆，將手繪境界從2D平面創作轉化成3D立體藝術。\r\n3/08(六)導電漆-蛋糕卡片燈【材料費250元】 \r\n3/16(日)3D列印筆-可愛魟魚【材料費200元】 \r\n3/29(六)導電漆-發光台灣燈卡【材料費300元】', '桃園市立圖書館', '桃園市八德區桃園市八德區廣盧路218號', '2025-03-08 00:00:00', '2025-03-29 00:00:00', '桃園市立圖書館景雲分館', 24.94968903, 121.2913102, '3/08費用+250;3/16費用+200;3/29費用+300', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='創作講座3月(3場)', `description`='透過高科技工具3D列印筆，將手繪境界從2D平面創作轉化成3D立體藝術。\r\n3/08(六)導電漆-蛋糕卡片燈【材料費250元】 \r\n3/16(日)3D列印筆-可愛魟魚【材料費200元】 \r\n3/29(六)導電漆-發光台灣燈卡【材料費300元】', `organizer`='桃園市立圖書館', `address`='桃園市八德區桃園市八德區廣盧路218號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='桃園市立圖書館景雲分館', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='3/08費用+250;3/16費用+200;3/29費用+300', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72426b32419285b6fe4', '【臺中市立圖書館潭子分館】3月 ~「心像遊記」~郭心迦油畫及漆畫個展', '活動內容:\r\n本展覽由畫家郭心迦展出，主題為「心像遊記」，藉由國內外旅遊風景，以畫筆及豐富的色彩，再次呈現心像的回憶與感懷。\r\n展出時間:114/03/01-114/03/31\r\n展出地點:臺中市立圖書館 潭子分館 B1多功能活動室', '臺中市立圖書館潭子分館', '臺中市潭子區中山路二段399號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺中市立圖書館潭子分館', 24.21171121, 120.710997, '無資料', 'https://www.library.taichung.gov.tw/public/topreview/index-1.asp?Parser=99,20,697,50,,,25147', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【臺中市立圖書館潭子分館】3月 ~「心像遊記」~郭心迦油畫及漆畫個展', `description`='活動內容:\r\n本展覽由畫家郭心迦展出，主題為「心像遊記」，藉由國內外旅遊風景，以畫筆及豐富的色彩，再次呈現心像的回憶與感懷。\r\n展出時間:114/03/01-114/03/31\r\n展出地點:臺中市立圖書館 潭子分館 B1多功能活動室', `organizer`='臺中市立圖書館潭子分館', `address`='臺中市潭子區中山路二段399號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺中市立圖書館潭子分館', `latitude`=24.21171121, `longitude`=120.710997, `ticket_price`='無資料', `source_url`='https://www.library.taichung.gov.tw/public/topreview/index-1.asp?Parser=99,20,697,50,,,25147', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72426b32419285b6fe5', '臺中市立圖書館東區分館 3月主題書展', '【臺語冊．講乎咱聽】書展-1F特展區\r\n「臺語冊．講乎咱聽」書展以台語歌謠為主，\r\n展出相關臺語、音樂書籍，讓母語透過書本語文字融入日常生活。\r\n\r\n【奇幻冒險之旅】書展-2F兒童閱覽區\r\n專注於奇幻故事和冒險類書籍，鼓勵孩子探索想像力的世界。\r\n\r\n【歷史不思議】書展-3F青少年閱讀區\r\n沙場的凌雲壯志  豪傑的蓋世功勳\r\n帝王的千秋萬世  歷代的神機妙算\r\n智囊的奇謀妙計\r\n世代的交替，演化成歷史的篇章\r\n\r\n【傳統VS現代 建築之旅】書展-B1開架閱覽區\r\n想了解不同世代建築的演變嗎?\r\n在傳統與現代交織的建築城市中\r\n透過書籍的解說\r\n讓我們一同探索不同世代的建築特色！\r\n\r\n【樂享人生】書展-1F期刊報紙區\r\n退休金要怎麼開始準備？ \r\n退休理財需要注意什麼？\r\n樂齡理財，人生更精彩。', '臺中市立圖書館東區分館', '臺中市東區建德街144號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館東區分館', 24.13733209, 120.6970865, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館東區分館 3月主題書展', `description`='【臺語冊．講乎咱聽】書展-1F特展區\r\n「臺語冊．講乎咱聽」書展以台語歌謠為主，\r\n展出相關臺語、音樂書籍，讓母語透過書本語文字融入日常生活。\r\n\r\n【奇幻冒險之旅】書展-2F兒童閱覽區\r\n專注於奇幻故事和冒險類書籍，鼓勵孩子探索想像力的世界。\r\n\r\n【歷史不思議】書展-3F青少年閱讀區\r\n沙場的凌雲壯志  豪傑的蓋世功勳\r\n帝王的千秋萬世  歷代的神機妙算\r\n智囊的奇謀妙計\r\n世代的交替，演化成歷史的篇章\r\n\r\n【傳統VS現代 建築之旅】書展-B1開架閱覽區\r\n想了解不同世代建築的演變嗎?\r\n在傳統與現代交織的建築城市中\r\n透過書籍的解說\r\n讓我們一同探索不同世代的建築特色！\r\n\r\n【樂享人生】書展-1F期刊報紙區\r\n退休金要怎麼開始準備？ \r\n退休理財需要注意什麼？\r\n樂齡理財，人生更精彩。', `organizer`='臺中市立圖書館東區分館', `address`='臺中市東區建德街144號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館東區分館', `latitude`=24.13733209, `longitude`=120.6970865, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72526b32419285b6fe6', '主題書展3月 (2檔)', '1.療癒心方向主題書展：\r\n隨科技的發展，現代社會節奏被急遽加快。長期的高壓生活，使人們甚至忘記喘息時間。書籍不只是知識的保存，還是諸多問題的答案所在！人們可以透過閱讀書籍脫離負面情緒，改善心靈。歡迎來體驗這種另類自然療法！\r\n\r\n2.立體書展：\r\n哇！書本竟然能「跳」出來？快來參加充滿驚喜的 立體書展 吧！在這裡，故事中的角色會從書頁中活靈活現地「躍」出來，讓你彷彿置身於奇幻世界。', '桃園市立圖書館', '桃園市龍潭區中興路680號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '桃園市立圖書館龍潭分館', 24.85064954, 121.2117877, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='主題書展3月 (2檔)', `description`='1.療癒心方向主題書展：\r\n隨科技的發展，現代社會節奏被急遽加快。長期的高壓生活，使人們甚至忘記喘息時間。書籍不只是知識的保存，還是諸多問題的答案所在！人們可以透過閱讀書籍脫離負面情緒，改善心靈。歡迎來體驗這種另類自然療法！\r\n\r\n2.立體書展：\r\n哇！書本竟然能「跳」出來？快來參加充滿驚喜的 立體書展 吧！在這裡，故事中的角色會從書頁中活靈活現地「躍」出來，讓你彷彿置身於奇幻世界。', `organizer`='桃園市立圖書館', `address`='桃園市龍潭區中興路680號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='桃園市立圖書館龍潭分館', `latitude`=24.85064954, `longitude`=121.2117877, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72526b32419285b6fec', '臺灣銀行藝術祭', '臺灣銀行致力於專業金融服務，亦積極踐履企業社會責任，自2017年起將社會參與提升至文化藝術層面，舉辦臺灣銀行藝術祭-繪畫、攝影及書法季等系列活動，傳達臺銀追求美學與永續的信念，提供多元藝術創作交流平台，支持臺灣藝術創作新秀。為提升優秀藝術家的能見度，規劃「2024臺灣銀行藝術祭系列」得獎作品於全台巡迴展覽。歡迎民眾攜家帶眷踴躍參觀，廣為周知親友前往欣賞作品，為得獎藝術家喝采，給予藝術家實質鼓勵，增添生活美學。', '臺中市政府地方稅務局沙鹿分局', '臺中市沙鹿區', '2025-03-20 00:00:00', '2025-04-18 00:00:00', '沙鹿區（臺中市）=', 24.23425212, 120.5838628, '無資料', 'https://www.tax.taichung.gov.tw/4499/5200/5420/35806/normalPost', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺灣銀行藝術祭', `description`='臺灣銀行致力於專業金融服務，亦積極踐履企業社會責任，自2017年起將社會參與提升至文化藝術層面，舉辦臺灣銀行藝術祭-繪畫、攝影及書法季等系列活動，傳達臺銀追求美學與永續的信念，提供多元藝術創作交流平台，支持臺灣藝術創作新秀。為提升優秀藝術家的能見度，規劃「2024臺灣銀行藝術祭系列」得獎作品於全台巡迴展覽。歡迎民眾攜家帶眷踴躍參觀，廣為周知親友前往欣賞作品，為得獎藝術家喝采，給予藝術家實質鼓勵，增添生活美學。', `organizer`='臺中市政府地方稅務局沙鹿分局', `address`='臺中市沙鹿區', `start_date`='2025-03-20 00:00:00', `end_date`='2025-04-18 00:00:00', `location`='沙鹿區（臺中市）=', `latitude`=24.23425212, `longitude`=120.5838628, `ticket_price`='無資料', `source_url`='https://www.tax.taichung.gov.tw/4499/5200/5420/35806/normalPost', `image_url`='[]';
