INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72726b32419285b6ffc', '【新北市立圖書館新店分館】114年3月主題書展:每天五分鐘做更好的自己', '想成為什麼樣的自己，就每天花點時間做改變，慢慢地朝目標前進，每天朝目標前進一小步，然後在將來的某一天就能成為更好的自己，試試看，從今天開始做起！\r\n\r\n展出時間：3月1日至3月31日 開館時間\r\n         3月27日         不對外開放\r\n展出地點：新北市立圖書館新店分館主題書展區\r\n         新北市新店區北新路三段105巷2號3樓\r\n書展示期間 可外借', '新北市立圖書館總館', '新北市新店區北新路三段105巷2號3樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館新店分館', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店分館】114年3月主題書展:每天五分鐘做更好的自己', `description`='想成為什麼樣的自己，就每天花點時間做改變，慢慢地朝目標前進，每天朝目標前進一小步，然後在將來的某一天就能成為更好的自己，試試看，從今天開始做起！\r\n\r\n展出時間：3月1日至3月31日 開館時間\r\n         3月27日         不對外開放\r\n展出地點：新北市立圖書館新店分館主題書展區\r\n         新北市新店區北新路三段105巷2號3樓\r\n書展示期間 可外借', `organizer`='新北市立圖書館總館', `address`='新北市新店區北新路三段105巷2號3樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館新店分館', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72726b32419285b6ffd', '【新北市立圖書館新店寶興圖書閱覽室】114年3月主題書展:和大自然做朋友', '以捷運、公車、郊山、海岸、水圳步道、水漾溼地，藉由大眾運輸可到達的地點，接近大自然，聆聽大自然的故事，以更多元的角度，認識、體驗自然。\r\n\r\n展出時間：3月1日至3月31日 開館時間\r\n         3月27日 不對外開放\r\n展出地點：新北市立圖書館新店區寶興圖書閱覽室主題書展區\r\n         新北市新店區寶中路65巷59號3樓\r\n\r\n展出期間 圖書可外借', '新北市立圖書館總館', '新北市新店區寶中路65巷59號3樓', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '新北市立圖書館新店寶興圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店寶興圖書閱覽室】114年3月主題書展:和大自然做朋友', `description`='以捷運、公車、郊山、海岸、水圳步道、水漾溼地，藉由大眾運輸可到達的地點，接近大自然，聆聽大自然的故事，以更多元的角度，認識、體驗自然。\r\n\r\n展出時間：3月1日至3月31日 開館時間\r\n         3月27日 不對外開放\r\n展出地點：新北市立圖書館新店區寶興圖書閱覽室主題書展區\r\n         新北市新店區寶中路65巷59號3樓\r\n\r\n展出期間 圖書可外借', `organizer`='新北市立圖書館總館', `address`='新北市新店區寶中路65巷59號3樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='新北市立圖書館新店寶興圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
