INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72726b32419285b7000', '【新北市立圖書館新店大鵬圖書閱覽室】114年3月主題書展:春日好點心', '如日本有賞櫻的習俗活動，在觀賞櫻花的美麗同時享受美味又好看的日式和果子點心、精神與味蕾的雙重饗宴。\r\n\r\n展出時間：3月1日至3月31日 開館時間\r\n          3月27日 不對外開放\r\n展出地點：新北市立圖書館新店大鵬圖書閱覽室主題書展區\r\n          新店區中正路700巷26號2樓\r\n\r\n展出期間 可外借', '新北市立圖書館總館', '新北市新店區中正路700巷26號2樓（大鵬華城內）', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '新北市立圖書館新店大鵬圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店大鵬圖書閱覽室】114年3月主題書展:春日好點心', `description`='如日本有賞櫻的習俗活動，在觀賞櫻花的美麗同時享受美味又好看的日式和果子點心、精神與味蕾的雙重饗宴。\r\n\r\n展出時間：3月1日至3月31日 開館時間\r\n          3月27日 不對外開放\r\n展出地點：新北市立圖書館新店大鵬圖書閱覽室主題書展區\r\n          新店區中正路700巷26號2樓\r\n\r\n展出期間 可外借', `organizer`='新北市立圖書館總館', `address`='新北市新店區中正路700巷26號2樓（大鵬華城內）', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='新北市立圖書館新店大鵬圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72726b32419285b7001', '【新北市立圖書館新店龜山圖書閱覽室】114年3月主題書展:春天賞蝶去', '台灣環境得天獨厚，具有多種不同的蝴蝶生存繁衍需要的氣候、地形等條件，\r\n造就了十分豐富的蝴蝶生態，為台灣贏得蝴蝶王國的美譽。\r\n　\r\n展出時間：3月1日至3月31日 開館時間\r\n         3月27日 不對外開放\r\n展出地點：新北市立圖書館新店龜山圖書閱覽室主題書展區\r\n         新北市新店區新烏路三段136號\r\n\r\n書展示期間 可外借', '新北市立圖書館總館', '新北市新店區新烏路3段136號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '新北市立圖書館新店龜山圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店龜山圖書閱覽室】114年3月主題書展:春天賞蝶去', `description`='台灣環境得天獨厚，具有多種不同的蝴蝶生存繁衍需要的氣候、地形等條件，\r\n造就了十分豐富的蝴蝶生態，為台灣贏得蝴蝶王國的美譽。\r\n　\r\n展出時間：3月1日至3月31日 開館時間\r\n         3月27日 不對外開放\r\n展出地點：新北市立圖書館新店龜山圖書閱覽室主題書展區\r\n         新北市新店區新烏路三段136號\r\n\r\n書展示期間 可外借', `organizer`='新北市立圖書館總館', `address`='新北市新店區新烏路3段136號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='新北市立圖書館新店龜山圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72726b32419285b7002', '【中市圖潭子分館】主題書展3月(2場)', '~3月主題書展~\r\n\r\n2025多元閱讀繽紛季(臺語冊，講乎咱聽) 主題書展\r\n0301-0330 中市圖各館同步展出\r\n以臺語歌謠為主，展出相關臺語、音樂書籍，\r\n讓母語透過書本與文字融入日常生活。\r\n(貼心小提醒:書展當中有部分書籍，必須等到書展結束，才開始提供外借喔!)\r\n●時間：114年3月1日(六)~114年3月31日(一) 8:30~21:00\r\n●地點：中市圖潭子分館 1樓展覽區\r\n----------------------------------------------\r\n~3月主題書展~\r\n\r\n過完新年\r\n春天到了~~\r\n一株株超級可愛多肉植物\r\n放在桌面上\r\n是不是很療癒又賞心悅目呢\r\n\r\n趕快來到潭子分館看看這次的超級實用主題書展喔\r\n【好多可愛多肉植物】主題書展\r\n(貼心小提醒:書展當中有部分書籍，必須等到書展結束，才開始提供外借喔!)\r\n●時間：114年3月1日(六)~114年3月31日(一) 8:30~21:00\r\n●地點：中市圖潭子分館 3樓展覽區\r\n', '臺中市立圖書館潭子分館', '臺中市潭子區中山路二段399號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺中市立圖書館潭子分館', 24.21171121, 120.710997, '無資料', 'https://www.library.taichung.gov.tw/public/topreview/index-1.asp?Parser=99,20,697,50,,,25152', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖潭子分館】主題書展3月(2場)', `description`='~3月主題書展~\r\n\r\n2025多元閱讀繽紛季(臺語冊，講乎咱聽) 主題書展\r\n0301-0330 中市圖各館同步展出\r\n以臺語歌謠為主，展出相關臺語、音樂書籍，\r\n讓母語透過書本與文字融入日常生活。\r\n(貼心小提醒:書展當中有部分書籍，必須等到書展結束，才開始提供外借喔!)\r\n●時間：114年3月1日(六)~114年3月31日(一) 8:30~21:00\r\n●地點：中市圖潭子分館 1樓展覽區\r\n----------------------------------------------\r\n~3月主題書展~\r\n\r\n過完新年\r\n春天到了~~\r\n一株株超級可愛多肉植物\r\n放在桌面上\r\n是不是很療癒又賞心悅目呢\r\n\r\n趕快來到潭子分館看看這次的超級實用主題書展喔\r\n【好多可愛多肉植物】主題書展\r\n(貼心小提醒:書展當中有部分書籍，必須等到書展結束，才開始提供外借喔!)\r\n●時間：114年3月1日(六)~114年3月31日(一) 8:30~21:00\r\n●地點：中市圖潭子分館 3樓展覽區\r\n', `organizer`='臺中市立圖書館潭子分館', `address`='臺中市潭子區中山路二段399號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺中市立圖書館潭子分館', `latitude`=24.21171121, `longitude`=120.710997, `ticket_price`='無資料', `source_url`='https://www.library.taichung.gov.tw/public/topreview/index-1.asp?Parser=99,20,697,50,,,25152', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72726b32419285b7003', '太平坪林分館親子共讀讀經班', '太平坪林分館親子共讀讀經班\r\n\r\n03/14(五)~08/29(日) 19:20~20:50\r\n\r\n提升孩子凟書習慣,建立優良品格\r\n藉由親子互動增進親子之間美好體驗與回憶\r\n提昇家長教育知能,建立良好家庭關係。\r\n\r\n於本館1樓多能活動室		\r\n', '臺中市立圖書館太平坪林分館', '臺中市太平區中山路一段213號', '2025-03-14 00:00:00', '2025-08-29 00:00:00', '臺中市立圖書館太平坪林分館', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/RLANZe', '[]') ON DUPLICATE KEY UPDATE `activity_name`='太平坪林分館親子共讀讀經班', `description`='太平坪林分館親子共讀讀經班\r\n\r\n03/14(五)~08/29(日) 19:20~20:50\r\n\r\n提升孩子凟書習慣,建立優良品格\r\n藉由親子互動增進親子之間美好體驗與回憶\r\n提昇家長教育知能,建立良好家庭關係。\r\n\r\n於本館1樓多能活動室		\r\n', `organizer`='臺中市立圖書館太平坪林分館', `address`='臺中市太平區中山路一段213號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-08-29 00:00:00', `location`='臺中市立圖書館太平坪林分館', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/RLANZe', `image_url`='[]';
