INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72926b32419285b700c', '2024環境教育繪本親子劇《小神碳大冒險》', '► 114/3/22（六）台中市 寶成演藝廳 下午14:30\r\n114/2/26 中午12:00開始索票\r\n\r\n#2024環境教育繪本親子劇\r\n INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72926b32419285b700d', '卷錄潭子檔傳啓示-淬鍊潭仔墘世紀風華展', '現場規劃5大展區、6大主題，從「檔案時光機」、「潭仔墘傳奇」、「守戶檔傳」、「時光記憶」、「檔我們同在一起」到「叫我第一名」，由檔案代言人薯來寶和薯來爸帶領民眾盡覽人生大小事與在地文化歷史相關檔案，展期延長至114年12月31日止。', '臺中市潭子區戶政事務所', '臺中市潭子區', '2025-03-03 00:00:00', '2025-12-31 00:00:00', '潭子區（臺中市）=', 24.21171121, 120.710997, '無資料', 'https://www.htanzi.taichung.gov.tw/3189129/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='卷錄潭子檔傳啓示-淬鍊潭仔墘世紀風華展', `description`='現場規劃5大展區、6大主題，從「檔案時光機」、「潭仔墘傳奇」、「守戶檔傳」、「時光記憶」、「檔我們同在一起」到「叫我第一名」，由檔案代言人薯來寶和薯來爸帶領民眾盡覽人生大小事與在地文化歷史相關檔案，展期延長至114年12月31日止。', `organizer`='臺中市潭子區戶政事務所', `address`='臺中市潭子區', `start_date`='2025-03-03 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='潭子區（臺中市）=', `latitude`=24.21171121, `longitude`=120.710997, `ticket_price`='無資料', `source_url`='https://www.htanzi.taichung.gov.tw/3189129/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72926b32419285b700e', '3月主題書展', '1F主題書展\r\n【臺語冊．講乎咱聽】\r\n台語之美  說得好聽  唱得美妙\r\n「八音七調」有長短、可牽長、有收束\r\n七字仔、四句聯、全鬥句\r\n大家做伙來學習\r\n用台語了解本土ㄟ文化\r\n\r\n2F主題書展\r\n[極簡包裝術] SDGs系列書展\r\nGoal 12責任消費與生產\r\n綠色經濟主題\r\n看到精美的包裝\r\n總是心動\r\n但 它在我手上的時間\r\n卻短的可憐\r\n在拆開的興奮後\r\n垃圾桶\r\n成了它的歸宿\r\n這一瞬的心動之美\r\n背後需要人類付出多少的代價\r\n讓我們從包裝設計出發\r\n思考如何減少過度包裝\r\n\r\n2F 主題書展\r\n[閱讀外埔] ✨主題書展\r\n外埔在地文史紀錄資料\r\n閱讀 從腳踩的這塊土地開始\r\n原來 外埔那~麼精彩！', '臺中市立圖書館外埔分館', '臺中市外埔區甲后路三段1060號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺中市立圖書館外埔分館', 24.33551071, 120.6650639, '無資料', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='3月主題書展', `description`='1F主題書展\r\n【臺語冊．講乎咱聽】\r\n台語之美  說得好聽  唱得美妙\r\n「八音七調」有長短、可牽長、有收束\r\n七字仔、四句聯、全鬥句\r\n大家做伙來學習\r\n用台語了解本土ㄟ文化\r\n\r\n2F主題書展\r\n[極簡包裝術] SDGs系列書展\r\nGoal 12責任消費與生產\r\n綠色經濟主題\r\n看到精美的包裝\r\n總是心動\r\n但 它在我手上的時間\r\n卻短的可憐\r\n在拆開的興奮後\r\n垃圾桶\r\n成了它的歸宿\r\n這一瞬的心動之美\r\n背後需要人類付出多少的代價\r\n讓我們從包裝設計出發\r\n思考如何減少過度包裝\r\n\r\n2F 主題書展\r\n[閱讀外埔] ✨主題書展\r\n外埔在地文史紀錄資料\r\n閱讀 從腳踩的這塊土地開始\r\n原來 外埔那~麼精彩！', `organizer`='臺中市立圖書館外埔分館', `address`='臺中市外埔區甲后路三段1060號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺中市立圖書館外埔分館', `latitude`=24.33551071, `longitude`=120.6650639, `ticket_price`='無資料', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
