INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72c26b32419285b7011', '114年上半年「屯藝學堂-藝文研習班」', '屯區藝文中心114年上半年「屯藝學堂-藝文研習班」，課程包含—花鳥工筆畫–初級班、動植物彩墨創作、創意手作皮雕、彩繪牡丹花卉班、彩墨創作、烏克麗麗、樂活畫水彩、水墨畫創作、水墨山水、竹笛快樂頌、右軍書法、玻璃嵌畫、輕鬆學油畫、花鳥蔬果草蟲班、遊藝書法研習、壓克力彩繪畫等課程，活動預計114年1月9日開放報名，歡迎有興趣的民眾踴躍報名參加。', '臺中市屯區藝文中心', '臺中市太平區大興路201號', '2025-03-04 00:00:00', '2025-06-27 00:00:00', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', 'https://www.ttdac.taichung.gov.tw/nc5307866209084475652/ncArticleContent', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年上半年「屯藝學堂-藝文研習班」', `description`='屯區藝文中心114年上半年「屯藝學堂-藝文研習班」，課程包含—花鳥工筆畫–初級班、動植物彩墨創作、創意手作皮雕、彩繪牡丹花卉班、彩墨創作、烏克麗麗、樂活畫水彩、水墨畫創作、水墨山水、竹笛快樂頌、右軍書法、玻璃嵌畫、輕鬆學油畫、花鳥蔬果草蟲班、遊藝書法研習、壓克力彩繪畫等課程，活動預計114年1月9日開放報名，歡迎有興趣的民眾踴躍報名參加。', `organizer`='臺中市屯區藝文中心', `address`='臺中市太平區大興路201號', `start_date`='2025-03-04 00:00:00', `end_date`='2025-06-27 00:00:00', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='https://www.ttdac.taichung.gov.tw/nc5307866209084475652/ncArticleContent', `image_url`='[]';
