INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72e26b32419285b701a', '米可吉他成果發表 吉思廣藝音樂會', '上半年度的成果發表會即將舉行囉，這次由我們的新生代學員為大家演奏\r\n希望大家能一同來參與，替新手村的大家加油！\r\n\r\n演出時間：03/30(日)16:00\r\n入場時間：15:30\r\n演出地點：台中市西屯區國安一路168號3樓（米平方商場)\r\n報名方式:   免費入場(進入線上報名填寫資料，即報名成功)\r\n洽詢專線：04-24621126\r\n\r\n演出學員:  \r\n烏克麗麗:廖佩慈、蔡詠馨、楊秉燁、林赫宇、施宇秦、董佑嘉、施旻希、趙姿晴\r\n\r\n古典/流行吉他:陳茗蕎、陳廷澤、李雨諭、林沛穎、陳弈霏、許禕玹、林煒閔、梁凱涵、楊展承\r\n許芷毓、王妡伃、李悠海、林愉淨、賴睿庸\r\n\r\n\r\n指導老師：\r\n余盈穎、王瀞巧、郭瑞凡、林紘妙、余沅翰\r\n\r\n-\r\n演出時間：03/30(日)16:00開演\r\n入場時間：15:30\r\n演出地點：台中市西屯區國安一路168號3樓（米平方商場)\r\n報名方式: 免費入場(進入線上報名填寫資料，即報名成功)\r\nhttps://forms.gle/NJGvshtUvBP5rZqi9', '米可吉他室內樂團', '臺中市西屯區', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '西屯區（臺中市）=', 24.18308895, 120.6270131, '無資料', 'https://www.facebook.com/share/p/1DidnXgwJX/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='米可吉他成果發表 吉思廣藝音樂會', `description`='上半年度的成果發表會即將舉行囉，這次由我們的新生代學員為大家演奏\r\n希望大家能一同來參與，替新手村的大家加油！\r\n\r\n演出時間：03/30(日)16:00\r\n入場時間：15:30\r\n演出地點：台中市西屯區國安一路168號3樓（米平方商場)\r\n報名方式:   免費入場(進入線上報名填寫資料，即報名成功)\r\n洽詢專線：04-24621126\r\n\r\n演出學員:  \r\n烏克麗麗:廖佩慈、蔡詠馨、楊秉燁、林赫宇、施宇秦、董佑嘉、施旻希、趙姿晴\r\n\r\n古典/流行吉他:陳茗蕎、陳廷澤、李雨諭、林沛穎、陳弈霏、許禕玹、林煒閔、梁凱涵、楊展承\r\n許芷毓、王妡伃、李悠海、林愉淨、賴睿庸\r\n\r\n\r\n指導老師：\r\n余盈穎、王瀞巧、郭瑞凡、林紘妙、余沅翰\r\n\r\n-\r\n演出時間：03/30(日)16:00開演\r\n入場時間：15:30\r\n演出地點：台中市西屯區國安一路168號3樓（米平方商場)\r\n報名方式: 免費入場(進入線上報名填寫資料，即報名成功)\r\nhttps://forms.gle/NJGvshtUvBP5rZqi9', `organizer`='米可吉他室內樂團', `address`='臺中市西屯區', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='西屯區（臺中市）=', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1DidnXgwJX/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72e26b32419285b701b', '四季沙龍系列音樂會 - 春', '四季節氣變化為主題，我們在新的一年預計將開設4場關於春、夏、秋、冬的沙龍音樂會，以輕鬆有趣的導聆揭開序幕，配合古典吉他作品賞析，跟著大家一起欣賞作品背後有趣的小故事，讓音樂牽動午後的柔光，邀您一同走入古典吉他的世界！\r\n\r\n我們精心安排一場充滿春天氣息的沙龍音樂會，從偉瓦第的 四季：春 到新年歌曲春回大地的氛圍，節目中的音樂導聆結合動人的吉他演奏，為您展開一場感官饗宴。在輕柔的旋律中，搭配精緻的下午茶，讓身心沉浸於音樂與美食的交融之中。\r\n\r\n無論您是音樂愛好者，還是想找個午後放鬆身心，這場活動都將帶給您一個難忘的美好時光。讓我們在這場美好的午後相遇，與吉他的故事產生共鳴。', '米可吉他室內樂團', '臺中市西屯區', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '西屯區（臺中市）=', 24.18308895, 120.6270131, '全票+600', 'https://www.facebook.com/share/p/18fW7j83pm/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='四季沙龍系列音樂會 - 春', `description`='四季節氣變化為主題，我們在新的一年預計將開設4場關於春、夏、秋、冬的沙龍音樂會，以輕鬆有趣的導聆揭開序幕，配合古典吉他作品賞析，跟著大家一起欣賞作品背後有趣的小故事，讓音樂牽動午後的柔光，邀您一同走入古典吉他的世界！\r\n\r\n我們精心安排一場充滿春天氣息的沙龍音樂會，從偉瓦第的 四季：春 到新年歌曲春回大地的氛圍，節目中的音樂導聆結合動人的吉他演奏，為您展開一場感官饗宴。在輕柔的旋律中，搭配精緻的下午茶，讓身心沉浸於音樂與美食的交融之中。\r\n\r\n無論您是音樂愛好者，還是想找個午後放鬆身心，這場活動都將帶給您一個難忘的美好時光。讓我們在這場美好的午後相遇，與吉他的故事產生共鳴。', `organizer`='米可吉他室內樂團', `address`='臺中市西屯區', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='西屯區（臺中市）=', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='全票+600', `source_url`='https://www.facebook.com/share/p/18fW7j83pm/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72e26b32419285b701c', '日常的風景 - 膠彩創作聯展(景物篇)', '展覽【 日常的風景 - 膠彩創作聯展 】\r\n參展人：許幼歆膠彩工作室 - 學生們\r\n展期：2025/03/06(四)～2025/03/30(日)\r\n在日復一日的生活中，風景不僅存在於窗外，也藏在我們的內心深處。\r\n本次膠彩創作聯展——「日常的風景」，由二十餘位創作者共展，以礦物顏料細膩描繪各自眼中的日常，或是記憶裡的靜謐片刻。\r\n每一幅畫都是對生活的溫柔凝視，礦物顏料點點微光，閃爍我們所見的景色，誠摯邀請您來感受這份平凡中的美好。', '許幼歆膠彩工作室', '臺中市西區', '2025-03-06 00:00:00', '2025-03-30 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/RY4qDe', '[]') ON DUPLICATE KEY UPDATE `activity_name`='日常的風景 - 膠彩創作聯展(景物篇)', `description`='展覽【 日常的風景 - 膠彩創作聯展 】\r\n參展人：許幼歆膠彩工作室 - 學生們\r\n展期：2025/03/06(四)～2025/03/30(日)\r\n在日復一日的生活中，風景不僅存在於窗外，也藏在我們的內心深處。\r\n本次膠彩創作聯展——「日常的風景」，由二十餘位創作者共展，以礦物顏料細膩描繪各自眼中的日常，或是記憶裡的靜謐片刻。\r\n每一幅畫都是對生活的溫柔凝視，礦物顏料點點微光，閃爍我們所見的景色，誠摯邀請您來感受這份平凡中的美好。', `organizer`='許幼歆膠彩工作室', `address`='臺中市西區', `start_date`='2025-03-06 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/RY4qDe', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72e26b32419285b701d', '日常的風景 - 膠彩創作聯展(動物篇)', '畫室學生的聯展開始了✨\r\n在日復一日的生活裡，風景不僅存在於窗外，也藏於我們的內心深處。我們以礦物顏料細膩描繪眼中的日常風景，或記憶裡的靜謐片刻。\r\n\r\n每一幅畫，都是對生活的溫柔凝視。礦物顏料點點微光，閃爍著我們所見的景色。誠摯邀請您走入這片靜謐光影之間，感受平凡日子裡潛藏的美好。\r\n\r\n📍 展覽資訊\r\n「動物篇」3/6 - 4/5茶筆巷文具生活空間。\r\n週二～週六11:00-19:00\r\n\r\n🔔展覽活動-茶筆巷文具生活空間\r\n3/9，14:00 開幕茶會\r\n3/9，15:00 現場膠彩材料包示範活動', '許幼歆膠彩工作室', '臺中市西區', '2025-03-06 00:00:00', '2025-04-05 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/7KX0lN', '[]') ON DUPLICATE KEY UPDATE `activity_name`='日常的風景 - 膠彩創作聯展(動物篇)', `description`='畫室學生的聯展開始了✨\r\n在日復一日的生活裡，風景不僅存在於窗外，也藏於我們的內心深處。我們以礦物顏料細膩描繪眼中的日常風景，或記憶裡的靜謐片刻。\r\n\r\n每一幅畫，都是對生活的溫柔凝視。礦物顏料點點微光，閃爍著我們所見的景色。誠摯邀請您走入這片靜謐光影之間，感受平凡日子裡潛藏的美好。\r\n\r\n📍 展覽資訊\r\n「動物篇」3/6 - 4/5茶筆巷文具生活空間。\r\n週二～週六11:00-19:00\r\n\r\n🔔展覽活動-茶筆巷文具生活空間\r\n3/9，14:00 開幕茶會\r\n3/9，15:00 現場膠彩材料包示範活動', `organizer`='許幼歆膠彩工作室', `address`='臺中市西區', `start_date`='2025-03-06 00:00:00', `end_date`='2025-04-05 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/7KX0lN', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d72e26b32419285b701e', '陳縈禎油畫個展 花若盛開，蝶自來', '陳縈禎老師的創作題材擷取自生活體驗，並無限定的創作風格，因為習慣一旦養成，生命就沒有推進的能量。\r\n\r\n陳縈禎幼時喜歡塗鴉，特別喜愛美的事物及沈浸天馬行空的異想世界。畢業於明道中學美工科後，於商業繪畫貿易公司任職，因不忘繪畫的興趣，隨東海大學林世元老師習畫多年，並師事廖本生老師學習抽象繪畫，後來考上東海大學美術系，抱持永不放棄的信念，堅持著再苦也會化為甘甜的信念，逐步完成自己的藝術夢想。\r\n\r\n「花若盛開，蝶自來-陳縈禎油畫個展」2月18日展至3月22日，作品傳遞的是藝術美感與價值觀，希望反映當代藝術獨特的形式與內涵，提供觀者對藝術不同視野的美感經驗。', '印藝文空間咖啡', '臺中市西區林森路38巷1號', '2025-02-18 00:00:00', '2025-03-22 00:00:00', '印 藝文空間 / 咖啡', 24.14391082, 120.6647579, '無資料', 'https://www.facebook.com/share/p/1EXMGVMMMT/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陳縈禎油畫個展 花若盛開，蝶自來', `description`='陳縈禎老師的創作題材擷取自生活體驗，並無限定的創作風格，因為習慣一旦養成，生命就沒有推進的能量。\r\n\r\n陳縈禎幼時喜歡塗鴉，特別喜愛美的事物及沈浸天馬行空的異想世界。畢業於明道中學美工科後，於商業繪畫貿易公司任職，因不忘繪畫的興趣，隨東海大學林世元老師習畫多年，並師事廖本生老師學習抽象繪畫，後來考上東海大學美術系，抱持永不放棄的信念，堅持著再苦也會化為甘甜的信念，逐步完成自己的藝術夢想。\r\n\r\n「花若盛開，蝶自來-陳縈禎油畫個展」2月18日展至3月22日，作品傳遞的是藝術美感與價值觀，希望反映當代藝術獨特的形式與內涵，提供觀者對藝術不同視野的美感經驗。', `organizer`='印藝文空間咖啡', `address`='臺中市西區林森路38巷1號', `start_date`='2025-02-18 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='印 藝文空間 / 咖啡', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1EXMGVMMMT/', `image_url`='[]';
