INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73026b32419285b7022', '【新北市立圖書館板橋四維分館】114年3月《閱讀書籤》植感生活', '館名：新北市立圖書館板橋四維分館\r\n地址：新北市板橋區陽明街168號\r\n電話：02-2252-1933#10\r\n時間：週二～週六 08:30-21:00；週日～週一 08:30-17:00；每月最後一週週四及國定假日休館\r\n\r\n書展主題：此次書展邀您走進綠意盎然的世界，探索園藝、美學與療癒的結合。精選植物照護、綠植佈置、香草應用等書籍，讓大自然走進日常，感受植物帶來的寧靜與活力，享受身心舒展的綠意時光！', '新北市立圖書館總館', '新北市板橋區陽明街168號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館板橋四維分館', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館板橋四維分館】114年3月《閱讀書籤》植感生活', `description`='館名：新北市立圖書館板橋四維分館\r\n地址：新北市板橋區陽明街168號\r\n電話：02-2252-1933#10\r\n時間：週二～週六 08:30-21:00；週日～週一 08:30-17:00；每月最後一週週四及國定假日休館\r\n\r\n書展主題：此次書展邀您走進綠意盎然的世界，探索園藝、美學與療癒的結合。精選植物照護、綠植佈置、香草應用等書籍，讓大自然走進日常，感受植物帶來的寧靜與活力，享受身心舒展的綠意時光！', `organizer`='新北市立圖書館總館', `address`='新北市板橋區陽明街168號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館板橋四維分館', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73126b32419285b7023', '國立臺東生活美學館｜土壤的記憶-植物繪圖展', '「土壤的記憶-植物繪圖展」，開幕式1月4日(星期六)下午2時於臺東桂田喜來登酒店三樓舉行，由國立臺東生活美學館與臺東桂田喜來登酒店合辦，展期於114年1月3日起至4月2日止。\r\n  本次展覽主題「土壤的記憶」，係由研究臺灣臺東縣主要河川流域周圍土壤所生之植物研究，從北部縱谷區域如新武呂溪（大理石岩盤）、卑南溪（卑南山礫岩）、鹿野溪（礫、砂、泥），至南區海岸區域如達仁溪（硬砂岩）、大武溪（變質砂岩）、知本溪（板岩、砂岩）等。透過細緻的科學繪圖表現技法，除可以準確識別和描述不同植物物種、記錄植物的形態特徵與生長軌跡，亦能觀察植物在不同土壤中如何適應與變化，理解自然界的相互依存關係。\r\n  這次策展人為植物繪圖指導老師康毓庭表示，2022年臺東航空站「野地博物館」植物繪圖展，廣受外界驚豔與喜愛，尤其獲得美學大師-蔣勳老師自發性粉專貼文的高度肯定與紛絲超過2萬個讚的殊榮，「對於我的新課程挑戰彷彿宛若一劑強心針」，所以在2024接續規畫進行臺東在地主要河域附近的植物研究；土壤不僅是植物生長的基礎，更是生命的記憶，每一層土壤都記錄著過去的環境變化、氣候變遷及生物活動，所以定「土壤的記憶」為展覽主題，創作方法以河川流域實地踏查，透過Google地圖定位，攝影與速寫記錄場域土壤地質、植物姿態與特徵；以科學繪圖技法研究植物生長軌跡(莖、枝、葉、葉脈、花苞、花瓣、果實、種子)，以0.1油性代針筆以「點描畫技法」製作作品，展出超精細植物繪圖作品約60件。\r\n  「美感的最高境界是良善」是毓庭老師課程核心理念–透過美感設計課程，除了教授美感知識融入生活外，從喚起對社會省思至自身良善之心，於教學中傳遞奉獻、公益的精神，進而引導學生創作作品，讓學生不僅學習美術的技藝，更深受精神的感化，用己之力回饋在地。其因藝術結合公益與致力推廣藝術志工於社區之創新等課程，榮獲110年教育部師鐸獎與第九屆星雲教育獎典範教師及112年教育部社會教育貢獻獎。\r\n ※開幕當日周邊將進行2025國立臺東女中美術班第十一屆藝術結合公益義賣活動，美術班師生作品展演及作品文創商品愛心認購活動。喜愛藝術、熱衷公益的好朋友，歡迎至現場參觀及認購。。這次義賣活動以原作印製超「植」感與「質」感文創商品，有陶瓷吸水杯墊500個及線裝精美手札400本。\r\n王垠校長表示：這次義賣活動，想到京都嵐山火車站掛著一副對聯「一燈照隅，萬燈照國」。事實上，每個人都是國家的照亮者，都有各自可以照亮的黑暗角落，點亮一盞燈，便有一盞燈的價值。', '國立臺東生活美學館', '臺東縣臺東市', '2025-01-03 00:00:00', '2025-04-02 00:00:00', '臺東市（臺東縣）=', 22.75165721, 121.1103647, '無資料', 'https://www.facebook.com/share/p/1ABUi5sQuL/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國立臺東生活美學館｜土壤的記憶-植物繪圖展', `description`='「土壤的記憶-植物繪圖展」，開幕式1月4日(星期六)下午2時於臺東桂田喜來登酒店三樓舉行，由國立臺東生活美學館與臺東桂田喜來登酒店合辦，展期於114年1月3日起至4月2日止。\r\n  本次展覽主題「土壤的記憶」，係由研究臺灣臺東縣主要河川流域周圍土壤所生之植物研究，從北部縱谷區域如新武呂溪（大理石岩盤）、卑南溪（卑南山礫岩）、鹿野溪（礫、砂、泥），至南區海岸區域如達仁溪（硬砂岩）、大武溪（變質砂岩）、知本溪（板岩、砂岩）等。透過細緻的科學繪圖表現技法，除可以準確識別和描述不同植物物種、記錄植物的形態特徵與生長軌跡，亦能觀察植物在不同土壤中如何適應與變化，理解自然界的相互依存關係。\r\n  這次策展人為植物繪圖指導老師康毓庭表示，2022年臺東航空站「野地博物館」植物繪圖展，廣受外界驚豔與喜愛，尤其獲得美學大師-蔣勳老師自發性粉專貼文的高度肯定與紛絲超過2萬個讚的殊榮，「對於我的新課程挑戰彷彿宛若一劑強心針」，所以在2024接續規畫進行臺東在地主要河域附近的植物研究；土壤不僅是植物生長的基礎，更是生命的記憶，每一層土壤都記錄著過去的環境變化、氣候變遷及生物活動，所以定「土壤的記憶」為展覽主題，創作方法以河川流域實地踏查，透過Google地圖定位，攝影與速寫記錄場域土壤地質、植物姿態與特徵；以科學繪圖技法研究植物生長軌跡(莖、枝、葉、葉脈、花苞、花瓣、果實、種子)，以0.1油性代針筆以「點描畫技法」製作作品，展出超精細植物繪圖作品約60件。\r\n  「美感的最高境界是良善」是毓庭老師課程核心理念–透過美感設計課程，除了教授美感知識融入生活外，從喚起對社會省思至自身良善之心，於教學中傳遞奉獻、公益的精神，進而引導學生創作作品，讓學生不僅學習美術的技藝，更深受精神的感化，用己之力回饋在地。其因藝術結合公益與致力推廣藝術志工於社區之創新等課程，榮獲110年教育部師鐸獎與第九屆星雲教育獎典範教師及112年教育部社會教育貢獻獎。\r\n ※開幕當日周邊將進行2025國立臺東女中美術班第十一屆藝術結合公益義賣活動，美術班師生作品展演及作品文創商品愛心認購活動。喜愛藝術、熱衷公益的好朋友，歡迎至現場參觀及認購。。這次義賣活動以原作印製超「植」感與「質」感文創商品，有陶瓷吸水杯墊500個及線裝精美手札400本。\r\n王垠校長表示：這次義賣活動，想到京都嵐山火車站掛著一副對聯「一燈照隅，萬燈照國」。事實上，每個人都是國家的照亮者，都有各自可以照亮的黑暗角落，點亮一盞燈，便有一盞燈的價值。', `organizer`='國立臺東生活美學館', `address`='臺東縣臺東市', `start_date`='2025-01-03 00:00:00', `end_date`='2025-04-02 00:00:00', `location`='臺東市（臺東縣）=', `latitude`=22.75165721, `longitude`=121.1103647, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1ABUi5sQuL/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73126b32419285b7024', '和偶們一起玩台語場', '內容:偶無處不在，隱身在我們的周圍，廟會慶典、遊戲玩耍，說故事、上舞台，他們樣樣都能來，快來和偶們一起玩吧﹗為大家表演的拍拍手工作室是2020年由藝術家陳敬皓成立，為台中潭子在地劇團。創作方向旨在探究當代偶戲與肢體劇場的結合應用為主。這次表演的節目為帕婆仔山一日遊及猜猜偶是誰，以台語演出，歡迎大家來參加喔﹗', '臺中市立圖書館霧峰以文分館', '臺中市霧峰區大同路8號', '2025-03-29 00:00:00', '2025-03-29 00:00:00', '臺中市立圖書館霧峰以文分館', 24.0615719, 120.699002, '無資料', 'https://reurl.cc/M31O3K', '[]') ON DUPLICATE KEY UPDATE `activity_name`='和偶們一起玩台語場', `description`='內容:偶無處不在，隱身在我們的周圍，廟會慶典、遊戲玩耍，說故事、上舞台，他們樣樣都能來，快來和偶們一起玩吧﹗為大家表演的拍拍手工作室是2020年由藝術家陳敬皓成立，為台中潭子在地劇團。創作方向旨在探究當代偶戲與肢體劇場的結合應用為主。這次表演的節目為帕婆仔山一日遊及猜猜偶是誰，以台語演出，歡迎大家來參加喔﹗', `organizer`='臺中市立圖書館霧峰以文分館', `address`='臺中市霧峰區大同路8號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市立圖書館霧峰以文分館', `latitude`=24.0615719, `longitude`=120.699002, `ticket_price`='無資料', `source_url`='https://reurl.cc/M31O3K', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73126b32419285b7025', '聽台語故事_探索昆蟲的奧秘', '兒童節快到了，喜歡咖啡媽咪說故事的小朋友有福了，聽咖啡媽咪說阿皮佮阿敏故事，跟著咖啡媽咪唱遊台灣尚勇，做鍬形蟲彩繪及瞭解刻印陰陽的知識，獨角仙、鍬形蟲的差異。', '臺南市新市區圖書館', '臺南市新市區民族路192號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '臺南市新市區圖書館', 23.08319496, 120.2923941, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='聽台語故事_探索昆蟲的奧秘', `description`='兒童節快到了，喜歡咖啡媽咪說故事的小朋友有福了，聽咖啡媽咪說阿皮佮阿敏故事，跟著咖啡媽咪唱遊台灣尚勇，做鍬形蟲彩繪及瞭解刻印陰陽的知識，獨角仙、鍬形蟲的差異。', `organizer`='臺南市新市區圖書館', `address`='臺南市新市區民族路192號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市新市區圖書館', `latitude`=23.08319496, `longitude`=120.2923941, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73226b32419285b7026', '【2024-2025東海岸大地藝術節藝術生活平臺串聯】-「東岸水之道 : 跟著樹根去旅行」楊慕仁繪畫個展', '【2024-2025東海岸大地藝術節藝術生活平臺串聯】-「東岸水之道 : 跟著樹根去旅行」\r\n在卑南族口傳神話中，\r\n靠近祖先登陸的發祥地有棵巨大的榕樹，\r\n其延伸而出的樹根，\r\n漂浮在東岸海面上形成一條酷似水上道路的交通媒介。\r\n\r\n繪畫藝術家楊慕仁因此做為創作靈感，以「旅行遊走」的概念由南向北做為移動契機，透過本次展覽機會，結合自身族群背景-卑南族石生系統為主體的系列畫作，與東岸景色、在地人文、海洋生物等素材故事串聯結合，呈現這場「關於台灣東岸之美」的平面繪畫創作分享。\r\n\r\n開幕茶會｜ 114/02/08(六) 10:30\r\n展覽期間｜ 114/02/08(六)~114/04/06(日)\r\n開放時間｜ 08:30~17:00\r\n展覽地點｜ 都歷遊客中心2樓海洋藝廊(台東縣信義里新村路25號) ', '交通部觀光署東部海岸國家風景區管理處', '臺東縣成功鎮新村路25號', '2025-02-08 00:00:00', '2025-04-06 00:00:00', '交通部觀光局東部海岸國家風景區管理處', 23.12663716, 121.3537983, '無資料', 'https://www.facebook.com/share/p/1HhQ79LRoy/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2024-2025東海岸大地藝術節藝術生活平臺串聯】-「東岸水之道 : 跟著樹根去旅行」楊慕仁繪畫個展', `description`='【2024-2025東海岸大地藝術節藝術生活平臺串聯】-「東岸水之道 : 跟著樹根去旅行」\r\n在卑南族口傳神話中，\r\n靠近祖先登陸的發祥地有棵巨大的榕樹，\r\n其延伸而出的樹根，\r\n漂浮在東岸海面上形成一條酷似水上道路的交通媒介。\r\n\r\n繪畫藝術家楊慕仁因此做為創作靈感，以「旅行遊走」的概念由南向北做為移動契機，透過本次展覽機會，結合自身族群背景-卑南族石生系統為主體的系列畫作，與東岸景色、在地人文、海洋生物等素材故事串聯結合，呈現這場「關於台灣東岸之美」的平面繪畫創作分享。\r\n\r\n開幕茶會｜ 114/02/08(六) 10:30\r\n展覽期間｜ 114/02/08(六)~114/04/06(日)\r\n開放時間｜ 08:30~17:00\r\n展覽地點｜ 都歷遊客中心2樓海洋藝廊(台東縣信義里新村路25號) ', `organizer`='交通部觀光署東部海岸國家風景區管理處', `address`='臺東縣成功鎮新村路25號', `start_date`='2025-02-08 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='交通部觀光局東部海岸國家風景區管理處', `latitude`=23.12663716, `longitude`=121.3537983, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1HhQ79LRoy/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73226b32419285b7027', '施麗花拾礫再生娃娃千嬌百媚展', '  施麗花出生1949年，鹿港的務農之家。除幫農務外，拜師於留日洋裁老師學得一技之長。\r\n鹿港開明美女裝訂做店，婚後北漂台北市延吉街，經營美美女裝訂做店，年歲增長，退出職場。\r\n  2年前以物盡其用、廢物再生：創作娃娃服飾來消磨時間兼動動腦。收集人家玩膩、衣服髒、破、頭髮零亂糾結丟棄的娃娃，清洗後、整理(燙)直頭髮，從新創作服飾、造型，賦予娃娃新風姿、延長把玩時期。\r\n布料:以布商汰舊的樣品布、裁縫店的零頭布。作的很開 \r\n     心，基於與同好共享而辦理展出成果與大家共賞。', '新北市土城區公所', '新北市土城區金城路一段101號', '2025-02-26 00:00:00', '2025-03-21 00:00:00', '新北市土城區公所(行政大樓)', 24.96425102, 121.445737, '無資料', 'https://www.tucheng.ntpc.gov.tw/index.jsp', '[]') ON DUPLICATE KEY UPDATE `activity_name`='施麗花拾礫再生娃娃千嬌百媚展', `description`='  施麗花出生1949年，鹿港的務農之家。除幫農務外，拜師於留日洋裁老師學得一技之長。\r\n鹿港開明美女裝訂做店，婚後北漂台北市延吉街，經營美美女裝訂做店，年歲增長，退出職場。\r\n  2年前以物盡其用、廢物再生：創作娃娃服飾來消磨時間兼動動腦。收集人家玩膩、衣服髒、破、頭髮零亂糾結丟棄的娃娃，清洗後、整理(燙)直頭髮，從新創作服飾、造型，賦予娃娃新風姿、延長把玩時期。\r\n布料:以布商汰舊的樣品布、裁縫店的零頭布。作的很開 \r\n     心，基於與同好共享而辦理展出成果與大家共賞。', `organizer`='新北市土城區公所', `address`='新北市土城區金城路一段101號', `start_date`='2025-02-26 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='新北市土城區公所(行政大樓)', `latitude`=24.96425102, `longitude`=121.445737, `ticket_price`='無資料', `source_url`='https://www.tucheng.ntpc.gov.tw/index.jsp', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73326b32419285b7028', '2025南風高揚—台南市師美學會與高雄市藝術聯盟畫會交流展 ', '臺南市師美學會與高雄藝術聯盟畫會分別成立於1997年與1985年，兩會主要成員主要由由國立臺灣師範大學美術學系及美術研究所畢業校友所組成，會員們除了在各級學校、學術單位、私人畫室與產業界等各行業機構從事美術教育的深耕與傳承，作育無數英才，同時也持續不斷堅守著藝術創作之實踐，每年定期合作舉辦畫展，增進會員情感聯誼，切磋畫藝，對外發表新作品，會員們在藝術家與教育者的雙重身份之間，游刃於藝界而追求更高境界之自我理想實現。', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-03-21 00:00:00', '2025-04-06 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025南風高揚—台南市師美學會與高雄市藝術聯盟畫會交流展 ', `description`='臺南市師美學會與高雄藝術聯盟畫會分別成立於1997年與1985年，兩會主要成員主要由由國立臺灣師範大學美術學系及美術研究所畢業校友所組成，會員們除了在各級學校、學術單位、私人畫室與產業界等各行業機構從事美術教育的深耕與傳承，作育無數英才，同時也持續不斷堅守著藝術創作之實踐，每年定期合作舉辦畫展，增進會員情感聯誼，切磋畫藝，對外發表新作品，會員們在藝術家與教育者的雙重身份之間，游刃於藝界而追求更高境界之自我理想實現。', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73326b32419285b7029', '簡單的幸福  喜樂藝廊公益畫展 Pure Happiness', '喜樂家族透過開設的美術課程來幫助在繪畫上有興趣、有天賦的身心障礙者，將曾接受過的溫暖、善意或是曾遭遇的霸凌、歧視，透過繪畫創作與社會大眾溝通無法用言語表達的內心世界。讓社會大眾藉由欣賞畫作進而接受、尊重不同的生命樣貌並給予支持。', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-03-14 00:00:00', '2025-04-06 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='簡單的幸福  喜樂藝廊公益畫展 Pure Happiness', `description`='喜樂家族透過開設的美術課程來幫助在繪畫上有興趣、有天賦的身心障礙者，將曾接受過的溫暖、善意或是曾遭遇的霸凌、歧視，透過繪畫創作與社會大眾溝通無法用言語表達的內心世界。讓社會大眾藉由欣賞畫作進而接受、尊重不同的生命樣貌並給予支持。', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73326b32419285b702a', '《再次從邊際到......》 《Once Again, From the Margins to...》', '「邊際」指的是地區或空間的界線與盡頭，而繪畫作為藝術中不可或缺的一部分，其核心在於如何在有限的載體範圍內呈現創作者無邊際的想像。繪畫的過程，是將無限的思維具象化於一個有限的平面中，透過這樣的創作，形成了藝術獨特的張力與表現力。而展覽的意圖正是將這些「邊際」中的創作內容再次帶到觀眾面前，激發更多的詮釋與可能性。\r\n展覽以回應過去藝術史上常見的繪畫題材—「宗教、人、風景、靜物與動物」為核心，透過對這些傳統題材的重新探索，展現當代藝術家如何以創新的方式解構和重塑經典題材，並結合當代社會背景，對當代議題、日常生活進行敏銳的觀察與回應。\r\n', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-03-14 00:00:00', '2025-04-06 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《再次從邊際到......》 《Once Again, From the Margins to...》', `description`='「邊際」指的是地區或空間的界線與盡頭，而繪畫作為藝術中不可或缺的一部分，其核心在於如何在有限的載體範圍內呈現創作者無邊際的想像。繪畫的過程，是將無限的思維具象化於一個有限的平面中，透過這樣的創作，形成了藝術獨特的張力與表現力。而展覽的意圖正是將這些「邊際」中的創作內容再次帶到觀眾面前，激發更多的詮釋與可能性。\r\n展覽以回應過去藝術史上常見的繪畫題材—「宗教、人、風景、靜物與動物」為核心，透過對這些傳統題材的重新探索，展現當代藝術家如何以創新的方式解構和重塑經典題材，並結合當代社會背景，對當代議題、日常生活進行敏銳的觀察與回應。\r\n', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-03-14 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73326b32419285b702b', '小蜻蜓兒童讀書會', '活動日期、研習內容：\r\n04/12\r\n相見歡&自我介紹\r\n《蛇的頭上長毛了》台語繪本賞析\r\n04/19\r\n《了解年菜及食物擬人法》繪本賞析\r\n黏土捏塑-出好菜\r\n04/26\r\n《芝麻開校門2》讀本賞析\r\n趣味反應力學習\r\n05/03\r\n《誰偷食菜頭稞》繪本賞析\r\n動物名稱互動樂', '高雄市立圖書館總館', '高雄市鳥松區18鄰大仁北路10號', '2025-04-12 00:00:00', '2025-05-03 00:00:00', '高雄市立圖書館鳥松分館', 22.6637985, 120.3622511, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='小蜻蜓兒童讀書會', `description`='活動日期、研習內容：\r\n04/12\r\n相見歡&自我介紹\r\n《蛇的頭上長毛了》台語繪本賞析\r\n04/19\r\n《了解年菜及食物擬人法》繪本賞析\r\n黏土捏塑-出好菜\r\n04/26\r\n《芝麻開校門2》讀本賞析\r\n趣味反應力學習\r\n05/03\r\n《誰偷食菜頭稞》繪本賞析\r\n動物名稱互動樂', `organizer`='高雄市立圖書館總館', `address`='高雄市鳥松區18鄰大仁北路10號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='高雄市立圖書館鳥松分館', `latitude`=22.6637985, `longitude`=120.3622511, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73426b32419285b702c', '山胡椒學習基地｜內本鹿警備道百年創作展', '#山是海_古道是日本人拋進海裡的牽絆\r\n-內本鹿警備道百年創作展   開幕暨走讀活動  #開放報名中\r\n策展人-鄭勝文 (內本鹿回家行動歷年成員，山林工作者)\r\n創作概念：\r\n群山如海，內本鹿警備道就像突然拋進海裡的繩子，順著潮流在山中擺盪。\r\n在海中努力浮游的Bunun們，看到繩子時會下意識地抓住？或者做出其他選擇?\r\n另一群順著繩子流入大海的人們，與Bunun產生了哪些拉扯與糾纏？追溯繩子的起點又是什麼呢？\r\n開幕茶敘暨走讀活動：12/11 9:00-16:00\r\n集合時間&地點：08:50 延平鄉桃源國小\r\n解散時間&地點：16:00 延平鄉桃源國小\r\n展出地點：山胡椒學習基地 (位於山上)\r\n報名簡章 \r\nhttps://forms.gle/eP4EPUPDZPwkq2d78  👈👈👈\r\n報名資訊：\r\n本活動開放25人報名，對本特展有興趣者或相關研究者，展場需車程30分鐘，再步行20分鐘山路。\r\n提供午餐餐食，為部落準備方便大多為葷食，全素者建議自備些行動糧\r\n指導單位：農業部林業及自然保育署臺東分署\r\n主辦單位：內本鹿人文工作室\r\n文宣設計：勤練習工作室', '內本鹿人文工作室', '臺東縣延平鄉', '2025-01-01 00:00:00', '2025-03-31 00:00:00', '延平鄉（臺東縣）=', 22.90343174, 120.9831902, '無資料', 'https://www.facebook.com/mamahavtupasnanavan', '[]') ON DUPLICATE KEY UPDATE `activity_name`='山胡椒學習基地｜內本鹿警備道百年創作展', `description`='#山是海_古道是日本人拋進海裡的牽絆\r\n-內本鹿警備道百年創作展   開幕暨走讀活動  #開放報名中\r\n策展人-鄭勝文 (內本鹿回家行動歷年成員，山林工作者)\r\n創作概念：\r\n群山如海，內本鹿警備道就像突然拋進海裡的繩子，順著潮流在山中擺盪。\r\n在海中努力浮游的Bunun們，看到繩子時會下意識地抓住？或者做出其他選擇?\r\n另一群順著繩子流入大海的人們，與Bunun產生了哪些拉扯與糾纏？追溯繩子的起點又是什麼呢？\r\n開幕茶敘暨走讀活動：12/11 9:00-16:00\r\n集合時間&地點：08:50 延平鄉桃源國小\r\n解散時間&地點：16:00 延平鄉桃源國小\r\n展出地點：山胡椒學習基地 (位於山上)\r\n報名簡章 \r\nhttps://forms.gle/eP4EPUPDZPwkq2d78  👈👈👈\r\n報名資訊：\r\n本活動開放25人報名，對本特展有興趣者或相關研究者，展場需車程30分鐘，再步行20分鐘山路。\r\n提供午餐餐食，為部落準備方便大多為葷食，全素者建議自備些行動糧\r\n指導單位：農業部林業及自然保育署臺東分署\r\n主辦單位：內本鹿人文工作室\r\n文宣設計：勤練習工作室', `organizer`='內本鹿人文工作室', `address`='臺東縣延平鄉', `start_date`='2025-01-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='延平鄉（臺東縣）=', `latitude`=22.90343174, `longitude`=120.9831902, `ticket_price`='無資料', `source_url`='https://www.facebook.com/mamahavtupasnanavan', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73426b32419285b702d', '臺東縣池上鄉文化藝術協會｜2025 TIDF台灣國際紀錄片巡迴影展', '文化藝術協會｜活動預告\r\n誰是主體、誰又是邊緣?\r\n創作者們以獨特視角與語彙，紀錄外在現實或訴說內在感受，時而直接，時而抽象，藏著多層次的隱喻，訴說著難以直接描述的故事。\r\n⭕2025 TIDF台灣國際紀錄片巡迴影展⭕\r\n邀請您一同感受紀錄片的震撼與感動!\r\n🎦影展地點｜米倉生活館_池上鄉中西三路8號\r\n🎦影展期間｜2025年1月至7月\r\n🎦影展票價｜免費入場\r\n🎦報名方式｜ https://forms.gle/MEUUn1MqGY8HkiW97\r\n🎦池上電影院 精選播映影集\r\n      1月11日 (六) ⟪時光台灣：流離島影Reel Taiwan︰Floating Islands⟫\r\n      2月8日   (六) ⟪氣旋納吉斯：當時間停止呼吸Nargis - When Time Stopped Breathing⟫   \r\n      3月8日   (六) ⟪硝煙下的助產士Midwives⟫   \r\n      4月12日 (六) ⟪基輔穹頂下的玫瑰Roses. Film-Cabaret⟫\r\n      5月10日 (六) ⟪服刑母親107 Mothers  ⟫   \r\n      6月14日 (六) ⟪陌生成家Three Strangers  ⟫   \r\n      7月19日 (六) ⟪九龍東往事An Asian Ghost Story ﹑ 緬甸短片精選⟫\r\n【想了解更多電影詳細介紹，可點選上方網址參閱喔】\r\n🎦主辦單位｜台灣國際紀錄片影展、國家電影及視聽文化中心、臺東縣池上鄉文化藝術協會', '國家電影及視聽文化中心', '臺東縣池上鄉', '2025-01-11 00:00:00', '2025-07-19 00:00:00', '池上鄉（臺東縣）=', 23.09248714, 121.2184501, '無資料', 'https://www.facebook.com/share/p/163Hs8TL5W/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺東縣池上鄉文化藝術協會｜2025 TIDF台灣國際紀錄片巡迴影展', `description`='文化藝術協會｜活動預告\r\n誰是主體、誰又是邊緣?\r\n創作者們以獨特視角與語彙，紀錄外在現實或訴說內在感受，時而直接，時而抽象，藏著多層次的隱喻，訴說著難以直接描述的故事。\r\n⭕2025 TIDF台灣國際紀錄片巡迴影展⭕\r\n邀請您一同感受紀錄片的震撼與感動!\r\n🎦影展地點｜米倉生活館_池上鄉中西三路8號\r\n🎦影展期間｜2025年1月至7月\r\n🎦影展票價｜免費入場\r\n🎦報名方式｜ https://forms.gle/MEUUn1MqGY8HkiW97\r\n🎦池上電影院 精選播映影集\r\n      1月11日 (六) ⟪時光台灣：流離島影Reel Taiwan︰Floating Islands⟫\r\n      2月8日   (六) ⟪氣旋納吉斯：當時間停止呼吸Nargis - When Time Stopped Breathing⟫   \r\n      3月8日   (六) ⟪硝煙下的助產士Midwives⟫   \r\n      4月12日 (六) ⟪基輔穹頂下的玫瑰Roses. Film-Cabaret⟫\r\n      5月10日 (六) ⟪服刑母親107 Mothers  ⟫   \r\n      6月14日 (六) ⟪陌生成家Three Strangers  ⟫   \r\n      7月19日 (六) ⟪九龍東往事An Asian Ghost Story ﹑ 緬甸短片精選⟫\r\n【想了解更多電影詳細介紹，可點選上方網址參閱喔】\r\n🎦主辦單位｜台灣國際紀錄片影展、國家電影及視聽文化中心、臺東縣池上鄉文化藝術協會', `organizer`='國家電影及視聽文化中心', `address`='臺東縣池上鄉', `start_date`='202