INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73526b32419285b702e', '臺東縣池上鄉文化藝術協會｜蔣勳時間｜細說印象派', '蔣勳時間｜細說印象派\r\n印象派大師只憑印象作畫？\r\n梵谷為何割耳朵？\r\n高更怎麼去了遙遠的大溪地？\r\n且聽蔣老師解析經典畫作，細說大師們如何顛覆傳統繪畫，創立二十世紀的新美學。\r\n\r\n1/5、1/23 馬奈\r\n2/9、2/23 莫內\r\n3/9、3/23 雷諾瓦\r\n4/6、4/13 秀拉\r\n5/11、5/25 梵谷\r\n6/15、6/29 高更\r\n\r\n週日 下午 2:00 / 2:30 / 3:00 / 3:30  \r\n重複播映 / 免費入場\r\n若遇其他活動  取消播映\r\n播映地點｜米倉生活館_池上鄉中西三路8號\r\n諮詢電話｜089-861089', '臺東縣池上鄉文化藝術協會', '臺東縣池上鄉', '2025-01-05 00:00:00', '2025-06-29 00:00:00', '池上鄉（臺東縣）=', 23.09248714, 121.2184501, '無資料', 'https://www.facebook.com/Chishangarts.org', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺東縣池上鄉文化藝術協會｜蔣勳時間｜細說印象派', `description`='蔣勳時間｜細說印象派\r\n印象派大師只憑印象作畫？\r\n梵谷為何割耳朵？\r\n高更怎麼去了遙遠的大溪地？\r\n且聽蔣老師解析經典畫作，細說大師們如何顛覆傳統繪畫，創立二十世紀的新美學。\r\n\r\n1/5、1/23 馬奈\r\n2/9、2/23 莫內\r\n3/9、3/23 雷諾瓦\r\n4/6、4/13 秀拉\r\n5/11、5/25 梵谷\r\n6/15、6/29 高更\r\n\r\n週日 下午 2:00 / 2:30 / 3:00 / 3:30  \r\n重複播映 / 免費入場\r\n若遇其他活動  取消播映\r\n播映地點｜米倉生活館_池上鄉中西三路8號\r\n諮詢電話｜089-861089', `organizer`='臺東縣池上鄉文化藝術協會', `address`='臺東縣池上鄉', `start_date`='2025-01-05 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='池上鄉（臺東縣）=', `latitude`=23.09248714, `longitude`=121.2184501, `ticket_price`='無資料', `source_url`='https://www.facebook.com/Chishangarts.org', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73526b32419285b702f', '月光小棧,女妖藝廊｜迴望~飛魚2025個展', '來自人之島的達悟族藝術家飛魚哥，認識他二十幾年，終於邀請到他來月光小棧女妖藝廊推出睽違多年的個展！哥為了這次個展，自去年六月夏威夷參展歸來便閉關專注創作，以二十餘年磨劍出鞘的心情，敬邀舊雨新知共賞飛魚對自己創作人生的迴望。2/8週六下午三點開幕茶會時，將邀都蘭藝術家Siki，以及來自西班牙的巴魯Balu，為人之島的飛魚來一場海洋之子的高歌唱和！！\r\n1970年出生於蘭嶼東清村的達悟族藝術家，人稱飛魚，就讀復興美工時期，恰逢台灣原住民社會運動最熱烈洶湧之時，因此開啟了他以繪畫創作表達他對原住民處境的思索，諸如達悟族的正名運動、蘭嶼核廢料的議題。自二十餘年前選擇落腳定居在大島（臺灣）東海岸都蘭一帶之後，除了油畫，飛魚也開始以漂流木做裝置創作，探索生活跟土地、海洋的關係。自他的達悟認同覺醒那一刻，他始終在實踐的是：「如何回到真正的達悟人的生活」，而藝術創作也是實踐達悟生活的一部分！\r\n飛魚說：\r\n站立於第25個冬季，回頭望向當初那只會創作油畫的雙手，\r\n25年來，這雙手被鍛鍊成往十項全能不斷前進的怪手\r\n由於貪玩於各種媒材創作，\r\n差點迷航在遼闊的漂流木、鐵雕、陶土、皮革、飛魚刀、廚藝、園藝......的海洋世界裡。\r\n但在創作的航行起點，\r\n畫筆一直是我手握住的桅桿，從未遺失過，\r\n即便是忙碌於各種生活瑣事，\r\n也不能、不敢、不甘將桅桿放下。\r\n我航行了25個春夏秋冬，\r\n風帆卻不曾繪上鮮明圖騰，\r\n於是把歲月騙走的青春奪回，\r\n將之高掛在\r\n我迴望的祭壇上。', '交通部觀光署東部海岸國家風景區管理處', '臺東縣東河鄉46 鄰20 號', '2025-02-08 00:00:00', '2025-03-29 00:00:00', '月光小棧 / 女妖在說畫藝廊暨咖啡屋', 22.98006921, 121.2517917, '無資料', 'https://www.facebook.com/TOWG.Atolan', '[]') ON DUPLICATE KEY UPDATE `activity_name`='月光小棧,女妖藝廊｜迴望~飛魚2025個展', `description`='來自人之島的達悟族藝術家飛魚哥，認識他二十幾年，終於邀請到他來月光小棧女妖藝廊推出睽違多年的個展！哥為了這次個展，自去年六月夏威夷參展歸來便閉關專注創作，以二十餘年磨劍出鞘的心情，敬邀舊雨新知共賞飛魚對自己創作人生的迴望。2/8週六下午三點開幕茶會時，將邀都蘭藝術家Siki，以及來自西班牙的巴魯Balu，為人之島的飛魚來一場海洋之子的高歌唱和！！\r\n1970年出生於蘭嶼東清村的達悟族藝術家，人稱飛魚，就讀復興美工時期，恰逢台灣原住民社會運動最熱烈洶湧之時，因此開啟了他以繪畫創作表達他對原住民處境的思索，諸如達悟族的正名運動、蘭嶼核廢料的議題。自二十餘年前選擇落腳定居在大島（臺灣）東海岸都蘭一帶之後，除了油畫，飛魚也開始以漂流木做裝置創作，探索生活跟土地、海洋的關係。自他的達悟認同覺醒那一刻，他始終在實踐的是：「如何回到真正的達悟人的生活」，而藝術創作也是實踐達悟生活的一部分！\r\n飛魚說：\r\n站立於第25個冬季，回頭望向當初那只會創作油畫的雙手，\r\n25年來，這雙手被鍛鍊成往十項全能不斷前進的怪手\r\n由於貪玩於各種媒材創作，\r\n差點迷航在遼闊的漂流木、鐵雕、陶土、皮革、飛魚刀、廚藝、園藝......的海洋世界裡。\r\n但在創作的航行起點，\r\n畫筆一直是我手握住的桅桿，從未遺失過，\r\n即便是忙碌於各種生活瑣事，\r\n也不能、不敢、不甘將桅桿放下。\r\n我航行了25個春夏秋冬，\r\n風帆卻不曾繪上鮮明圖騰，\r\n於是把歲月騙走的青春奪回，\r\n將之高掛在\r\n我迴望的祭壇上。', `organizer`='交通部觀光署東部海岸國家風景區管理處', `address`='臺東縣東河鄉46 鄰20 號', `start_date`='2025-02-08 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='月光小棧 / 女妖在說畫藝廊暨咖啡屋', `latitude`=22.98006921, `longitude`=121.2517917, `ticket_price`='無資料', `source_url`='https://www.facebook.com/TOWG.Atolan', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73526b32419285b7030', '繪畫創作展-咖啡色的查克拉', '以繪畫作為主要創作形式。\r\n此主題內容，作者自述\r\n「我的體內有著很大藝術及繪畫查克拉。\r\n動漫中，忍者使用查克拉會爆氣。不同的忍者，氣的顏色、大小會不同\r\n在咖啡廳，我選擇展現咖啡色的查克拉，雖然帶點悠閒，但還是具有能量」', '信藝藏在ART', '臺南市六甲區', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '六甲區（臺南市）=', 23.2272672, 120.3800259, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='繪畫創作展-咖啡色的查克拉', `description`='以繪畫作為主要創作形式。\r\n此主題內容，作者自述\r\n「我的體內有著很大藝術及繪畫查克拉。\r\n動漫中，忍者使用查克拉會爆氣。不同的忍者，氣的顏色、大小會不同\r\n在咖啡廳，我選擇展現咖啡色的查克拉，雖然帶點悠閒，但還是具有能量」', `organizer`='信藝藏在ART', `address`='臺南市六甲區', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='六甲區（臺南市）=', `latitude`=23.2272672, `longitude`=120.3800259, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
