INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73526b32419285b7032', '【新北市立圖書館三重五常分館】114年3月【閱讀書籤】主題書展', '【三重五常分館】114年3月【閱讀書籤】-「婦幼醫學」主題書展\r\n\r\n時間：114年3月1日至3月31日，週二至週六08:30~21:00，週日至週一08:30~17:00(3月27日清館日不開放)\r\n\r\n \r\n\r\n內容簡介:\r\n\r\n懷孕前、懷孕期間要注意什麼？\r\n\r\n產後要如何調理、恢復身材？\r\n\r\n寶寶要怎樣照顧才能健康長大？\r\n\r\n一起來學習吧！\r\n\r\n \r\n\r\n＊活動單位保有取消、變更之權利，詳情請依現場為主\r\n\r\n \r\n\r\n＊免費入場，無須報名，場內禁止飲食\r\n\r\n \r\n\r\n地點:新北市立圖書館三重五常分館2樓書展區\r\n\r\n \r\n\r\n地址：新北市三重區五華街7巷30號\r\n\r\n \r\n\r\n交通：\r\n\r\n搭乘公車：62、226至【五常郵局】站下車\r\n\r\n搭乘免費社區巴士F302至【五常公園】站下車\r\n\r\n \r\n\r\n電話:02-29890559', '新北市立圖書館總館', '新北市三重區五華街七巷30號二樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館三重五常分館', 25.06281651, 121.4870977, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三重五常分館】114年3月【閱讀書籤】主題書展', `description`='【三重五常分館】114年3月【閱讀書籤】-「婦幼醫學」主題書展\r\n\r\n時間：114年3月1日至3月31日，週二至週六08:30~21:00，週日至週一08:30~17:00(3月27日清館日不開放)\r\n\r\n \r\n\r\n內容簡介:\r\n\r\n懷孕前、懷孕期間要注意什麼？\r\n\r\n產後要如何調理、恢復身材？\r\n\r\n寶寶要怎樣照顧才能健康長大？\r\n\r\n一起來學習吧！\r\n\r\n \r\n\r\n＊活動單位保有取消、變更之權利，詳情請依現場為主\r\n\r\n \r\n\r\n＊免費入場，無須報名，場內禁止飲食\r\n\r\n \r\n\r\n地點:新北市立圖書館三重五常分館2樓書展區\r\n\r\n \r\n\r\n地址：新北市三重區五華街7巷30號\r\n\r\n \r\n\r\n交通：\r\n\r\n搭乘公車：62、226至【五常郵局】站下車\r\n\r\n搭乘免費社區巴士F302至【五常公園】站下車\r\n\r\n \r\n\r\n電話:02-29890559', `organizer`='新北市立圖書館總館', `address`='新北市三重區五華街七巷30號二樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館三重五常分館', `latitude`=25.06281651, `longitude`=121.4870977, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73526b32419285b7033', '生活美學：黃金剪黏工藝', '剪黏為台灣廟宇屋頂常見的裝飾藝術之一，但他可以不只存在於廟頂上。\r\n這堂課程想將這項歷史悠久的傳統工藝融入現代生活，讓日漸凋零的技藝能重新為人拾起，於社會中綿延下去。\r\n這堂課邀請到近期完成仁壽宮屋頂剪黏工程的重磅講師黃金生老師授課，一步步帶領學員從綁鐵絲、灰泥塑形，打造粗胚到裁剪碗片、鑲嵌黏貼、線條繪畫，完成自己獨一無二的作品；從過程中練習「剪」和「黏」的技藝，欣賞剪黏工藝的魅力，並感受台灣傳統工藝與文化的深奧\r\n完成的作品可作為牆面掛飾、桌上擺飾等(還有其他創意用途等你挖掘)，讓你的生活充滿文化溫度與厚度', '臺南市南關社區大學', '臺南市歸仁區中正北路一段148號', '2025-03-22 00:00:00', '2025-05-24 00:00:00', '臺南市歸仁區新豐高級中學', 22.94679469, 120.2930627, '2600元/人+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='生活美學：黃金剪黏工藝', `description`='剪黏為台灣廟宇屋頂常見的裝飾藝術之一，但他可以不只存在於廟頂上。\r\n這堂課程想將這項歷史悠久的傳統工藝融入現代生活，讓日漸凋零的技藝能重新為人拾起，於社會中綿延下去。\r\n這堂課邀請到近期完成仁壽宮屋頂剪黏工程的重磅講師黃金生老師授課，一步步帶領學員從綁鐵絲、灰泥塑形，打造粗胚到裁剪碗片、鑲嵌黏貼、線條繪畫，完成自己獨一無二的作品；從過程中練習「剪」和「黏」的技藝，欣賞剪黏工藝的魅力，並感受台灣傳統工藝與文化的深奧\r\n完成的作品可作為牆面掛飾、桌上擺飾等(還有其他創意用途等你挖掘)，讓你的生活充滿文化溫度與厚度', `organizer`='臺南市南關社區大學', `address`='臺南市歸仁區中正北路一段148號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='臺南市歸仁區新豐高級中學', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='2600元/人+--', `source_url`='無資料', `image_url`='[]';
