INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73526b32419285b7039', '【南投縣母語燎原】柯柏榮：台語詩文趣味寫', '2025南投縣母語燎原系列活動，參加活動還有機會獲得精美小禮物！每場活動提供可愛卡通絨毛磁鐵，現南投，是多元文化交織的家園；台語，是我們熟悉的聲音，也是文化的根。透過活動，讓台語融入生活，成為每一天的陪伴與記憶。\r\n溫暖的母語，生活的日常\r\n邀請大家一起來，專業講師帶你深入淺出認識台語語言文化與脈絡，用聲音、表情、肢體，把台語故事講得生動有趣，讓你的表達技能up，聽眾聽得都入迷。不管是家長、老師，還是對台語、說故事有興趣的人都適合！\r\n參加活動，領取參加禮，還有機會參加抽獎活動，贏取更多驚喜好禮！\r\n免費參加。線上報名 https://forms.gle/P74YibTjsuAL7t2J6', '南投縣政府文化局', '南投縣草屯鎮草鞋墩一街8號', '2025-04-06 00:00:00', '2025-04-06 00:00:00', '南投縣草屯鎮立圖書館', 23.9736845, 120.6802819, '無資料', 'https://www.facebook.com/profile.php?id=61573816426704', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【南投縣母語燎原】柯柏榮：台語詩文趣味寫', `description`='2025南投縣母語燎原系列活動，參加活動還有機會獲得精美小禮物！每場活動提供可愛卡通絨毛磁鐵，現南投，是多元文化交織的家園；台語，是我們熟悉的聲音，也是文化的根。透過活動，讓台語融入生活，成為每一天的陪伴與記憶。\r\n溫暖的母語，生活的日常\r\n邀請大家一起來，專業講師帶你深入淺出認識台語語言文化與脈絡，用聲音、表情、肢體，把台語故事講得生動有趣，讓你的表達技能up，聽眾聽得都入迷。不管是家長、老師，還是對台語、說故事有興趣的人都適合！\r\n參加活動，領取參加禮，還有機會參加抽獎活動，贏取更多驚喜好禮！\r\n免費參加。線上報名 https://forms.gle/P74YibTjsuAL7t2J6', `organizer`='南投縣政府文化局', `address`='南投縣草屯鎮草鞋墩一街8號', `start_date`='2025-04-06 00:00:00', `end_date`='2025-04-06 00:00:00', `location`='南投縣草屯鎮立圖書館', `latitude`=23.9736845, `longitude`=120.6802819, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=61573816426704', `image_url`='[]';
