INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67d9d73526b32419285b703b', '【南投縣母語燎原】蕭秀瑩、廖雅玲：台語說故事（4場次）', '南投，是多元文化交織的家園；台語，是我們熟悉的聲音，也是文化的根。透過活動，讓台語融入生活，成為每一天的陪伴與記憶。\r\n溫暖的母語，生活的日常\r\n邀請大家一起來，聽故事、看戲劇、說台語，讓母語的溫暖陪伴我們每一天！帶著家人朋友，共同參與這場母語文化盛宴！\r\n參加活動，領取參加禮，還有機會參加抽獎活動，贏取更多驚喜好禮！\r\n\r\n台語說故事\r\n從3月到9月，超過50場精彩故事分享，由專業講師帶來動人的台語故事，涵蓋生活、文化、自然與歷史，適合全家大小一同參與！\r\n免費參加，名額有限。\r\n線上報名 https://forms.gle/P74YibTjsuAL7t2J6', '南投縣政府文化局', '南投縣草屯鎮草鞋墩一街8號', '2025-06-08 00:00:00', '2025-06-08 00:00:00', '南投縣草屯鎮立圖書館', 23.9736845, 120.6802819, '無資料', 'https://www.facebook.com/profile.php?id=61573816426704', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【南投縣母語燎原】蕭秀瑩、廖雅玲：台語說故事（4場次）', `description`='南投，是多元文化交織的家園；台語，是我們熟悉的聲音，也是文化的根。透過活動，讓台語融入生活，成為每一天的陪伴與記憶。\r\n溫暖的母語，生活的日常\r\n邀請大家一起來，聽故事、看戲劇、說台語，讓母語的溫暖陪伴我們每一天！帶著家人朋友，共同參與這場母語文化盛宴！\r\n參加活動，領取參加禮，還有機會參加抽獎活動，贏取更多驚喜好禮！\r\n\r\n台語說故事\r\n從3月到9月，超過50場精彩故事分享，由專業講師帶來動人的台語故事，涵蓋生活、文化、自然與歷史，適合全家大小一同參與！\r\n免費參加，名額有限。\r\n線上報名 https://forms.gle/P74YibTjsuAL7t2J6', `organizer`='南投縣政府文化局', `address`='南投縣草屯鎮草鞋墩一街8號', `start_date`='2025-06-08 00:00:00', `end_date`='2025-06-08 00:00:00', `location`='南投縣草屯鎮立圖書館', `latitude`=23.9736845, `longitude`=120.6802819, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=61573816426704', `image_url`='[]';
