INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db285b26b32419285b7054', '三芝區公所陶藝展', '李老師將岩花紋融入陶藝創作，使每件作品都擁有獨特的紋理，如同大自然雕琢出的藝術品。透過 #柴燒技法，讓落灰與火痕交織，塑造出層次豐富的顏色變化，彷彿色彩艷麗的大理石，作品表面還附著礦物結晶產生的墨綠斑點，宛如青苔覆在岩石之上，更添了古樸韻味！\r\n每一件作品，都是土、火、時間交織而成的藝術', '新北市三芝區公所', '新北市三芝區中山路1段32號', '2025-02-14 00:00:00', '2025-04-30 00:00:00', '新北市三芝區公所行政大樓', 25.23159891, 121.515558, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三芝區公所陶藝展', `description`='李老師將岩花紋融入陶藝創作，使每件作品都擁有獨特的紋理，如同大自然雕琢出的藝術品。透過 #柴燒技法，讓落灰與火痕交織，塑造出層次豐富的顏色變化，彷彿色彩艷麗的大理石，作品表面還附著礦物結晶產生的墨綠斑點，宛如青苔覆在岩石之上，更添了古樸韻味！\r\n每一件作品，都是土、火、時間交織而成的藝術', `organizer`='新北市三芝區公所', `address`='新北市三芝區中山路1段32號', `start_date`='2025-02-14 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市三芝區公所行政大樓', `latitude`=25.23159891, `longitude`=121.515558, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db285b26b32419285b7055', '【新北市立圖書館板橋江子翠分館】114年3月英文故事', '【新北市立圖書館板橋江子翠分館】114年3月英文故事\r\n3/2(日)From Head to Toe / 賈海云\r\n3/9(日)Interrupting Chicken / 張美玲\r\n3/16(日)What Do You Use to Help Your Body?/ 劉曼麗\r\n3/23(日)Little Red Hen / 黃瓊瑩\r\n3/30(日)Augustus and His Smile / 王麗真', '新北市立圖書館總館', '新北市板橋區莊敬路62號', '2025-03-02 00:00:00', '2025-03-30 00:00:00', '新北市立圖書館板橋江子翠分館', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館板橋江子翠分館】114年3月英文故事', `description`='【新北市立圖書館板橋江子翠分館】114年3月英文故事\r\n3/2(日)From Head to Toe / 賈海云\r\n3/9(日)Interrupting Chicken / 張美玲\r\n3/16(日)What Do You Use to Help Your Body?/ 劉曼麗\r\n3/23(日)Little Red Hen / 黃瓊瑩\r\n3/30(日)Augustus and His Smile / 王麗真', `organizer`='新北市立圖書館總館', `address`='新北市板橋區莊敬路62號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='新北市立圖書館板橋江子翠分館', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
