INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db286a26b32419285b7059', '《2024-25今日畫會•今日畫展》', '《2024-25今日畫會•今日畫展》先後從台北、桃園、基隆、台中巡迴展出，成員們提供作品呈現當今的藝術觀點，探討和發揚今日臺灣的美好與價值為內容表現，包括油畫、壓克力、水彩、水墨、版畫和複合媒材。33位會員他們將以精心的創作與藝文界朋友們一起交流切磋，分享創作經驗和互動。走過65個年頭的今日畫會，匯聚老、中、青三代藝術家舉行「今日畫會•今日畫展」，畫會成員在各自的風格與創作關注點追求獨立性，並在抽象與具象風格中相互融合，開創獨特的藝術之路。正是本會耕耘藝術文化的一次重要成果。', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-02-28 00:00:00', '2025-03-23 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=8d37c7202bb64611a442384d268509aa', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《2024-25今日畫會•今日畫展》', `description`='《2024-25今日畫會•今日畫展》先後從台北、桃園、基隆、台中巡迴展出，成員們提供作品呈現當今的藝術觀點，探討和發揚今日臺灣的美好與價值為內容表現，包括油畫、壓克力、水彩、水墨、版畫和複合媒材。33位會員他們將以精心的創作與藝文界朋友們一起交流切磋，分享創作經驗和互動。走過65個年頭的今日畫會，匯聚老、中、青三代藝術家舉行「今日畫會•今日畫展」，畫會成員在各自的風格與創作關注點追求獨立性，並在抽象與具象風格中相互融合，開創獨特的藝術之路。正是本會耕耘藝術文化的一次重要成果。', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=8d37c7202bb64611a442384d268509aa', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db286b26b32419285b705a', '2025年【閱讀寫作教室】系列講座', '不論是國中小學生或是高中大專院校生，都會希望能好好加強作文能力，提升自我閱讀寫作策略與技巧，但是考題文本動輒數萬字，若無有效策略，只加強學科，將無法有效因應考試題型並加強作文能力。本系列講座邀請聯合學苑專業師資，將提供實用的閱讀策略與寫作技巧，打造學生作文硬實力。', '臺中市立圖書館', '臺中市西屯區', '2025-03-09 00:00:00', '2025-11-02 00:00:00', '西屯區（臺中市）=', 24.18308895, 120.6270131, '無資料', 'https://reurl.cc/mRAe9M', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年【閱讀寫作教室】系列講座', `description`='不論是國中小學生或是高中大專院校生，都會希望能好好加強作文能力，提升自我閱讀寫作策略與技巧，但是考題文本動輒數萬字，若無有效策略，只加強學科，將無法有效因應考試題型並加強作文能力。本系列講座邀請聯合學苑專業師資，將提供實用的閱讀策略與寫作技巧，打造學生作文硬實力。', `organizer`='臺中市立圖書館', `address`='臺中市西屯區', `start_date`='2025-03-09 00:00:00', `end_date`='2025-11-02 00:00:00', `location`='西屯區（臺中市）=', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://reurl.cc/mRAe9M', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db286b26b32419285b705b', '藝屹不迷-陳柏屹書畫個展 ', '本次展覽主題為藝屹不迷，由意義不明作為出發 點所命名，藝屹：為藝術 猶如作者的一生，不迷： 寓意著作者在藝術這條路 上不是走的很順遂，路途坎坷，心中迷茫。因為緊湊的生活，壓抑著許多情緒，想藉由這份心情用中國傳統的筆、墨、紙、硯勾勒出作者的心情。\r\n「海風的呢喃」「潮石觀月」「震潮銀月」此三件小品是以「浪」為主題，「浪」分別代表著作者心境的轉變是由作者的內心所呈現出不同的感受，而此三件作品以浪的不同姿態表現了作者從茫然到堅定的心路歷程，完美契合了展覽的標題。', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-03-01 00:00:00', '2025-03-23 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=71be7430d03642cf8a313a433ccadfbc', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝屹不迷-陳柏屹書畫個展 ', `description`='本次展覽主題為藝屹不迷，由意義不明作為出發 點所命名，藝屹：為藝術 猶如作者的一生，不迷： 寓意著作者在藝術這條路 上不是走的很順遂，路途坎坷，心中迷茫。因為緊湊的生活，壓抑著許多情緒，想藉由這份心情用中國傳統的筆、墨、紙、硯勾勒出作者的心情。\r\n「海風的呢喃」「潮石觀月」「震潮銀月」此三件小品是以「浪」為主題，「浪」分別代表著作者心境的轉變是由作者的內心所呈現出不同的感受，而此三件作品以浪的不同姿態表現了作者從茫然到堅定的心路歷程，完美契合了展覽的標題。', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=71be7430d03642cf8a313a433ccadfbc', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db286c26b32419285b705c', '【新北市立圖書館總館】2025新北詩歌節【詩學座談】「詩創作與閱讀」/佘佳燕、陳克華、凌性傑', '地址：新北市立圖書館總館1樓推廣區\r\n電話：02-22953212\r\n講題：【詩學座談】「詩創作與閱讀」\r\n\r\n3/23（日）14:00，邀請詩人 佘佳燕、陳克華、凌性傑，在 新北市立圖書館總館，一起探索 詩創作與閱讀 的微妙關係！\r\n詩如何在閱讀中萌芽？\r\n創作如何回應閱讀的養分？\r\n詩人們將分享他們如何在詩與書之間往返，讓文字綻放出獨特的光彩！\r\n各位詩迷朋友們，這場精彩座談會不容錯過！快來報名，在春天的圖書館裡，一起沉浸詩的世界！\r\n\r\n時間｜3/23（日）14:00\r\n地點｜新北市立圖書館總館\r\n報名連結（https://reurl.cc/r3e6Rk）', '新北市立圖書館總館', '新北市板橋區貴興路139號', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '新北市立圖書館總館', 25.01186453, 121.4579675, '無資料', 'https://www.facebook.com/share/p/1DWQ99zq8Q/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館總館】2025新北詩歌節【詩學座談】「詩創作與閱讀」/佘佳燕、陳克華、凌性傑', `description`='地址：新北市立圖書館總館1樓推廣區\r\n電話：02-22953212\r\n講題：【詩學座談】「詩創作與閱讀」\r\n\r\n3/23（日）14:00，邀請詩人 佘佳燕、陳克華、凌性傑，在 新北市立圖書館總館，一起探索 詩創作與閱讀 的微妙關係！\r\n詩如何在閱讀中萌芽？\r\n創作如何回應閱讀的養分？\r\n詩人們將分享他們如何在詩與書之間往返，讓文字綻放出獨特的光彩！\r\n各位詩迷朋友們，這場精彩座談會不容錯過！快來報名，在春天的圖書館裡，一起沉浸詩的世界！\r\n\r\n時間｜3/23（日）14:00\r\n地點｜新北市立圖書館總館\r\n報名連結（https://reurl.cc/r3e6Rk）', `organizer`='新北市立圖書館總館', `address`='新北市板橋區貴興路139號', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='新北市立圖書館總館', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1DWQ99zq8Q/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db286d26b32419285b705d', '【新北市立圖書館泰山分館】114年3月影友會', '放映時間:周六17：00起\r\n放映地點:新北市立圖書館泰山分館研習教室\r\n(新北市泰山區全興路212號5樓)\r\n洽詢專線:02-29091727服務臺\r\n\r\n03/01（六） 小子（普）101分\r\n03/08（六） 撼山河 撼向世界（普）111分\r\n03/15（六） ＊魔籽公主（普）74分\r\n03/22（六） ＊喵的詐騙集團（普）93分\r\n03/29（六） 來自星星的少女（護）108分\r\n\r\n加註*為卡通或動畫片\r\n加註◎為樂齡片\r\n節目如有異動,請依現場播放為準\r\n免費入場,無須報名,但因為空間限制,先到先選位,額滿為止\r\n敬請各位觀眾遵守各電影分級制度進場\r\n研習教室內禁止飲食,敬請各位觀眾遵守,謝謝合作', '新北市立圖書館總館', '新北市泰山區全興路212號5樓', '2025-03-01 00:00:00', '2025-03-29 00:00:00', '新北市立圖書館泰山分館', 25.05549774, 121.4162785, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館泰山分館】114年3月影友會', `description`='放映時間:周六17：00起\r\n放映地點:新北市立圖書館泰山分館研習教室\r\n(新北市泰山區全興路212號5樓)\r\n洽詢專線:02-29091727服務臺\r\n\r\n03/01（六） 小子（普）101分\r\n03/08（六） 撼山河 撼向世界（普）111分\r\n03/15（六） ＊魔籽公主（普）74分\r\n03/22（六） ＊喵的詐騙集團（普）93分\r\n03/29（六） 來自星星的少女（護）108分\r\n\r\n加註*為卡通或動畫片\r\n加註◎為樂齡片\r\n節目如有異動,請依現場播放為準\r\n免費入場,無須報名,但因為空間限制,先到先選位,額滿為止\r\n敬請各位觀眾遵守各電影分級制度進場\r\n研習教室內禁止飲食,敬請各位觀眾遵守,謝謝合作', `organizer`='新北市立圖書館總館', `address`='新北市泰山區全興路212號5樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='新北市立圖書館泰山分館', `latitude`=25.05549774, `longitude`=121.4162785, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
