INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db286e26b32419285b7060', '【淺淺微風】－羅宇成水彩創作展', '藝術家展覽自述｜\r\n自從開始專注於「海系列」創作，不知不覺間，這段旅程已經走過近十年。至今，我依然在「海」的世界裡沉浮，持續探索，未曾止步。這次展覽的名稱為「淺淺微風」如同海風輕輕吹拂的瞬間，捕捉那份柔和而深遠的流動感。展覽中乘載我對海洋的觀察與情感，從大海到隱藏其中的生命律動，我透過畫筆呈現我對海洋的感受－既廣闊又細膩，深沈卻又輕盈。「淺淺微風」是一種輕盈的觸動，也是一場與海洋對話的邀請。\r\n海洋帶給我取之不盡、用之不竭的靈感，但我的創作不僅僅停留在「如實描繪」。因此，我嘗試以隨性的染色、率性的疊色，讓畫面在偶然與刻意之間交織，最後再尋找平衡，使作品達到完整的狀態。如今，這樣的創作方式已經成為我的習慣，讓我在作畫時能夠更輕鬆愉快地享受每一筆觸的流動。\r\n我始終在日常觀察中尋找靈感，透過生活片段來反映自己對世界的感知與理解。身為一名熱愛海洋的創作者，我深深著迷於海洋的無窮魅力，特別是海洋生物的多樣性與奇妙生態。海洋不僅是壯麗的自然景觀，更是無數生命繁衍生息的舞台。每一種生物的外型、色彩與行為，都隱藏著關於生存、逃逸、偽裝與繁衍的故事。這些故事不斷啟發著我，驅使我透過繪畫來記錄與表達海洋世界的奧秘與生命的韻律，也是與我生命中的連結。', '鶯歌光點美學館', '新北市鶯歌區陶瓷街18號', '2025-03-07 00:00:00', '2025-04-27 00:00:00', '鶯歌光點美學館', 24.951993, 121.34862, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【淺淺微風】－羅宇成水彩創作展', `description`='藝術家展覽自述｜\r\n自從開始專注於「海系列」創作，不知不覺間，這段旅程已經走過近十年。至今，我依然在「海」的世界裡沉浮，持續探索，未曾止步。這次展覽的名稱為「淺淺微風」如同海風輕輕吹拂的瞬間，捕捉那份柔和而深遠的流動感。展覽中乘載我對海洋的觀察與情感，從大海到隱藏其中的生命律動，我透過畫筆呈現我對海洋的感受－既廣闊又細膩，深沈卻又輕盈。「淺淺微風」是一種輕盈的觸動，也是一場與海洋對話的邀請。\r\n海洋帶給我取之不盡、用之不竭的靈感，但我的創作不僅僅停留在「如實描繪」。因此，我嘗試以隨性的染色、率性的疊色，讓畫面在偶然與刻意之間交織，最後再尋找平衡，使作品達到完整的狀態。如今，這樣的創作方式已經成為我的習慣，讓我在作畫時能夠更輕鬆愉快地享受每一筆觸的流動。\r\n我始終在日常觀察中尋找靈感，透過生活片段來反映自己對世界的感知與理解。身為一名熱愛海洋的創作者，我深深著迷於海洋的無窮魅力，特別是海洋生物的多樣性與奇妙生態。海洋不僅是壯麗的自然景觀，更是無數生命繁衍生息的舞台。每一種生物的外型、色彩與行為，都隱藏著關於生存、逃逸、偽裝與繁衍的故事。這些故事不斷啟發著我，驅使我透過繪畫來記錄與表達海洋世界的奧秘與生命的韻律，也是與我生命中的連結。', `organizer`='鶯歌光點美學館', `address`='新北市鶯歌區陶瓷街18號', `start_date`='2025-03-07 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='鶯歌光點美學館', `latitude`=24.951993, `longitude`=121.34862, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db287026b32419285b7061', '2025新營藝術季｜《公館青少年》', '2025新營藝術季｜《公館青少年》\r\n由幾位 Z 世代成員組成的公館青少年，創作風格除了保留青春的陽光正向，同時也映照年紀對生活、感情的迷茫與懷疑。', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025新營藝術季｜《公館青少年》', `description`='2025新營藝術季｜《公館青少年》\r\n由幾位 Z 世代成員組成的公館青少年，創作風格除了保留青春的陽光正向，同時也映照年紀對生活、感情的迷茫與懷疑。', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db287226b32419285b7062', '【性別符號】│進擊的農婦', '＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│進擊的農婦\r\n英文片│The County\r\n\r\n導演│格里莫哈科森納\r\n冰島│2019│普遍級│劇情類│彩色│冰島語│92分鐘\r\n\r\n簡介\r\n英嘉與瑞尼爾在寧靜的小鎮中以酪農為生。夫妻倆每天從早忙到晚，農場的營運依舊入不敷出。全因艾普斯菲德合作社壟斷了鎮上所有農產品以及民生用品的銷售所致。某天瑞尼爾在返家途中發生一起死亡車禍，歷經喪夫之痛的英嘉在調查亡夫死亡事件時，意外從友人口中得知丈夫死因並不單純，可能與無良合作社有關。為了替亡夫討回公道，英嘉決定在臉書上公開自己被合作社壓榨的故事。', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【性別符號】│進擊的農婦', `description`='＊免費入場，放映前半小時發放號碼牌，1人1張，24號發完為止。\r\n＊放映後10分鐘禁止入場。\r\n\r\n※※※※※※※【放映資訊】※※※※※※※\r\n           【性別符號】\r\n\r\n中文片│進擊的農婦\r\n英文片│The County\r\n\r\n導演│格里莫哈科森納\r\n冰島│2019│普遍級│劇情類│彩色│冰島語│92分鐘\r\n\r\n簡介\r\n英嘉與瑞尼爾在寧靜的小鎮中以酪農為生。夫妻倆每天從早忙到晚，農場的營運依舊入不敷出。全因艾普斯菲德合作社壟斷了鎮上所有農產品以及民生用品的銷售所致。某天瑞尼爾在返家途中發生一起死亡車禍，歷經喪夫之痛的英嘉在調查亡夫死亡事件時，意外從友人口中得知丈夫死因並不單純，可能與無良合作社有關。為了替亡夫討回公道，英嘉決定在臉書上公開自己被合作社壓榨的故事。', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db287726b32419285b7063', '【基北北桃台語家庭意識培力講座】 新北場—M̄-nā教出台語力', '【基北北桃台語家庭意識培力講座】\r\n\r\n新北場—M̄-nā教出台語力\r\n\r\n\r\n費用：免費參加，請先報名，實名制。\r\n報名網址  https://forms.gle/ZiHZMwLqH5Aia4Ri9\r\n\r\n台語使用比例:100%\r\n預計認列點數:2\r\n#配合文化部培育台語家庭計畫集點  ＃文化部國家語言整體發展方案支持\r\n\r\n主講人：董力玄\r\n台灣台語路協會理事長\r\n\r\n\r\n內容：\r\n• 100年前就有台語報紙？ ——拍破台語三大迷思\r\n• 台灣bat經過兩擺國語運動？ ——學校無教ê台語歷史 \r\n• 是按怎科學家建議囡仔先學台語？ ——對囡仔講台語ê好處 \r\n• 囡仔lóng應華語beh按怎？ ——學習語言ê歷程hām資源\r\n\r\n\r\n\r\n▎活動時間：2025/3/23(禮拜) 下晡2:00～4:00\r\n\r\n▎名額：網路報名30人\r\n\r\n▎地點：新北市立明志國民中學 數位圖書室 (新北市三重區中正北路107號)\r\n\r\n\r\n\r\n\r\n洽詢電話：02-23112199\r\n聯絡信箱：bongpo1996@gmail.com\r\n\r\n\r\n主辦單位：李江却台語文教基金會\r\n\r\n補助單位：文化部\r\n\r\n------------------------------\r\n\r\n題目：毋但教出台語力\r\n\r\n內容：\r\n\r\n• 100年前就有台語報紙？——打破台語三大迷思\r\n\r\n• 臺灣經歷兩次國語運動？——學校沒教的台語歷史\r\n\r\n• 為什麼科學家建議幼童先學台語？——對孩子講台語的益處\r\n\r\n• 小孩都回華語怎麼辦？——學習語言的歷程和資源\r\n\r\n------------------------------\r\n\r\n台語家庭集點計劃：上「國家語言數位資訊網」，進入台語家庭會員平台，登錄成做預備台語家庭，每一个人lóng ài先申請會員口座(身分證抑是健保卡電子檔)，其中一位綁定厝內人，選擇「台語學習/文化家庭」，開始報名活動kah課程，集點換台語獎勵金、抽獎機會。\r\n\r\n台語家庭會員平台常見問題  https://tg.moc.gov.tw/ptgl-user-service/faq-login.html\r\n\r\n--------------------------------\r\n\r\n歡迎捐款贊助　#李江却台語文教基金會　\r\n（捐款可抵稅，匯款後請通知02-23112199）\r\n線上捐款(定期定額)\r\nhttps://donate.newebpay.com/Period/akhioh/lkk\r\n線上捐款(單筆)\r\nhttps://donate.newebpay.com/akhioh/lkk\r\n\r\n郵政劃撥：19021486\r\n戶名：財團法人李江却台語文教基金會\r\n\r\n電匯：123-20-050514-2 華南銀行士林分行活儲\r\n戶名：財團法人李江却台語文教基金會', '李江却台語文教基金會', '新北市三重區', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '三重區（新北市）=', 25.06281651, 121.4870977, '無資料', 'https://www.tgb.org.tw/2025/02/m-na.html', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【基北北桃台語家庭意識培力講座】 新北場—M̄-nā教出台語力', `description`='【基北北桃台語家庭意識培力講座】\r\n\r\n新北場—M̄-nā教出台語力\r\n\r\n\r\n費用：免費參加，請先報名，實名制。\r\n報名網址  https://forms.gle/ZiHZMwLqH5Aia4Ri9\r\n\r\n台語使用比例:100%\r\n預計認列點數:2\r\n#配合文化部培育台語家庭計畫集點  ＃文化部國家語言整體發展方案支持\r\n\r\n主講人：董力玄\r\n台灣台語路協會理事長\r\n\r\n\r\n內容：\r\n• 100年前就有台語報紙？ ——拍破台語三大迷思\r\n• 台灣bat經過兩擺國語運動？ ——學校無教ê台語歷史 \r\n• 是按怎科學家建議囡仔先學台語？ ——對囡仔講台語ê好處 \r\n• 囡仔lóng應華語beh按怎？ ——學習語言ê歷程hām資源\r\n\r\n\r\n\r\n▎活動時間：2025/3/23(禮拜) 下晡2:00～4:00\r\n\r\n▎名額：網路報名30人\r\n\r\n▎地點：新北市立明志國民中學 數位圖書室 (新北市三重區中正北路107號)\r\n\r\n\r\n\r\n\r\n洽詢電話：02-23112199\r\n聯絡信箱：bongpo1996@gmail.com\r\n\r\n\r\n主辦單位：李江却台語文教基金會\r\n\r\n補助單位：文化部\r\n\r\n------------------------------\r\n\r\n題目：毋但教出台語力\r\n\r\n內容：\r\n\r\n• 100年前就有台語報紙？——打破台語三大迷思\r\n\r\n• 臺灣經歷兩次國語運動？——學校沒教的台語歷史\r\n\r\n• 為什麼科學家建議幼童先學台語？——對孩子講台語的益處\r\n\r\n• 小孩都回華語怎麼辦？——學習語言的歷程和資源\r\n\r\n------------------------------\r\n\r\n台語家庭集點計劃：上「國家語言數位資訊網」，進入台語家庭會員平台，登錄成做預備台語家庭，每一个人lóng ài先申請會員口座(身分證抑是健保卡電子檔)，其中一位綁定厝內人，選擇「台語學習/文化家庭」，開始報名活動kah課程，集點換台語獎勵金、抽獎機會。\r\n\r\n台語家庭會員平台常見問題  https://tg.moc.gov.tw/ptgl-user-service/faq-login.html\r\n\r\n--------------------------------\r\n\r\n歡迎捐款贊助　#李江却台語文教基金會　\r\n（捐款可抵稅，匯款後請通知02-23112199）\r\n線上捐款(定期定額)\r\nhttps://donate.newebpay.com/Period/akhioh/lkk\r\n線上捐款(單筆)\r\nhttps://donate.newebpay.com/akhioh/lkk\r\n\r\n郵政劃撥：19021486\r\n戶名：財團法人李江却台語文教基金會\r\n\r\n電匯：123-20-050514-2 華南銀行士林分行活儲\r\n戶名：財團法人李江却台語文教基金會', `organizer`='李江却台語文教基金會', `address`='新北市三重區', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='三重區（新北市）=', `latitude`=25.06281651, `longitude`=121.4870977, `ticket_price`='無資料', `source_url`='https://www.tgb.org.tw/2025/02/m-na.html', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db287726b32419285b7064', '羅馬帝國的世界遺産', '橫跨歐亞非三洲的羅馬帝國，不僅影響了歐洲歷史，也為世界留下了各方面的典範，為何羅馬不是一天造成的？為何條條大路通羅馬？\r\n羅馬帝國強權的歷史與軍事擴張、橫跨歐亞非的世界遺產、\r\n羅馬帝國帶來的文化影響 旅遊作家馬繼康老師細說給你聽。', '臺中市葫蘆墩文化中心', '臺中市豐原區圓環東路782號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '臺中市葫蘆墩文化中心', 24.24990298, 120.7375715, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144144,2', '[]') ON DUPLICATE KEY UPDATE `activity_name`='羅馬帝國的世界遺産', `description`='橫跨歐亞非三洲的羅馬帝國，不僅影響了歐洲歷史，也為世界留下了各方面的典範，為何羅馬不是一天造成的？為何條條大路通羅馬？\r\n羅馬帝國強權的歷史與軍事擴張、橫跨歐亞非的世界遺產、\r\n羅馬帝國帶來的文化影響 旅遊作家馬繼康老師細說給你聽。', `organizer`='臺中市葫蘆墩文化中心', `address`='臺中市豐原區圓環東路782號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='臺中市葫蘆墩文化中心', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144144,2', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db287e26b32419285b7065', '社交高手鳳頭鸚鵡-兒童美術研習班成果展', '在港區藝術中心小小的角落裡，有一群小畫家，正用無限的創意與熱情，妝點屬於他們的藝術銀河系！\r\n\r\n★社交高手鳳頭鸚鵡\r\n展覽日期：114/4/1-5/4\r\n展出成員：大兒童美術B班\r\n展覽內容：春季藝文研習-大兒童美術B班成果展\r\n創作媒材：蠟筆\r\n展覽地點：港區小藝廊(雅書廊川堂)', '臺中市政府文化局', '臺中市清水區忠貞路21號', '2025-04-01 00:00:00', '2025-05-04 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=ab97f59b067247058eec65b7f620f4b6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='社交高手鳳頭鸚鵡-兒童美術研習班成果展', `description`='在港區藝術中心小小的角落裡，有一群小畫家，正用無限的創意與熱情，妝點屬於他們的藝術銀河系！\r\n\r\n★社交高手鳳頭鸚鵡\r\n展覽日期：114/4/1-5/4\r\n展出成員：大兒童美術B班\r\n展覽內容：春季藝文研習-大兒童美術B班成果展\r\n創作媒材：蠟筆\r\n展覽地點：港區小藝廊(雅書廊川堂)', `organizer`='臺中市政府文化局', `address`='臺中市清水區忠貞路21號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=ab97f59b067247058eec65b7f620f4b6', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db287f26b32419285b7066', '《點亮五彩繽紛的原子筆畫》林永祥個展', '原子筆是簡單隨手易得的工具，很少人運用在繪畫的表現媒材上，有別於傳統畫法的筆觸在放大時是平的，而獨創的原子筆螺旋筆觸在放大時層層堆疊、色彩豐富更顯現其差異性及獨特性，有特色不一樣的畫作很吸晴，是很難得一見的畫展哦～', '無資料', '新北市新莊區中平路133號', '2025-03-12 00:00:00', '2025-03-30 00:00:00', '新莊文化藝術中心', 25.0358303, 121.4367535, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《點亮五彩繽紛的原子筆畫》林永祥個展', `description`='原子筆是簡單隨手易得的工具，很少人運用在繪畫的表現媒材上，有別於傳統畫法的筆觸在放大時是平的，而獨創的原子筆螺旋筆觸在放大時層層堆疊、色彩豐富更顯現其差異性及獨特性，有特色不一樣的畫作很吸晴，是很難得一見的畫展哦～', `organizer`='無資料', `address`='新北市新莊區中平路133號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='新莊文化藝術中心', `latitude`=25.0358303, `longitude`=121.4367535, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
