INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288726b32419285b7068', '臺中市立圖書館西區分館3月【主題書展】臺語冊．講乎咱聽', '語言是文化的根，音樂是情感的橋梁。臺語冊·講乎咱聽書展以臺語歌謠為主題，透過書籍與音樂的結合，讓母語更加貼近生活，融入日常。本書展精選多種與臺語及音樂相關的書籍，從傳統歌謠、現代創作，到語言學習與文化研究，帶領讀者一同走進臺語的聲音世界，感受文字與旋律交織的魅力。', '臺中市立圖書館西區分館', '臺中市西區精誠路256號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館西區分館', 24.14944, 120.654959, '無資料', 'https://reurl.cc/04Y4z9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館西區分館3月【主題書展】臺語冊．講乎咱聽', `description`='語言是文化的根，音樂是情感的橋梁。臺語冊·講乎咱聽書展以臺語歌謠為主題，透過書籍與音樂的結合，讓母語更加貼近生活，融入日常。本書展精選多種與臺語及音樂相關的書籍，從傳統歌謠、現代創作，到語言學習與文化研究，帶領讀者一同走進臺語的聲音世界，感受文字與旋律交織的魅力。', `organizer`='臺中市立圖書館西區分館', `address`='臺中市西區精誠路256號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館西區分館', `latitude`=24.14944, `longitude`=120.654959, `ticket_price`='無資料', `source_url`='https://reurl.cc/04Y4z9', `image_url`='[]';
