INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288826b32419285b706d', '欣翰 港尾水墨師生展', '展示課堂上歡喜的舞墨，在水墨藝術領域的教學成果與創作實力。   \r\n   展覽將展出多幅水墨作品，包含傳統山水、花鳥以及現代抽象風格等多樣的形式，展現水墨藝術的廣泛可能性。透過這些作品，觀眾將有機會深入了解水墨 藝術的歷史、技法與當代發展，並欣賞到師生之間的互動與成長。\r\n', '臺中市西屯區公所', '臺中市西屯區市政北二路386號', '2025-03-04 00:00:00', '2025-04-28 00:00:00', '臺中市西屯區公所', 24.1654462, 120.6337766, '無資料', 'https://www.facebook.com/story.php?story_fbid=1036638308500561&id=100064632043793&_rdr', '[]') ON DUPLICATE KEY UPDATE `activity_name`='欣翰 港尾水墨師生展', `description`='展示課堂上歡喜的舞墨，在水墨藝術領域的教學成果與創作實力。   \r\n   展覽將展出多幅水墨作品，包含傳統山水、花鳥以及現代抽象風格等多樣的形式，展現水墨藝術的廣泛可能性。透過這些作品，觀眾將有機會深入了解水墨 藝術的歷史、技法與當代發展，並欣賞到師生之間的互動與成長。\r\n', `organizer`='臺中市西屯區公所', `address`='臺中市西屯區市政北二路386號', `start_date`='2025-03-04 00:00:00', `end_date`='2025-04-28 00:00:00', `location`='臺中市西屯區公所', `latitude`=24.1654462, `longitude`=120.6337766, `ticket_price`='無資料', `source_url`='https://www.facebook.com/story.php?story_fbid=1036638308500561&id=100064632043793&_rdr', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288926b32419285b706e', '藝文研習成果展－馮雯琳師生彩墨畫展', '馮雯琳老師為國立臺灣師範大學美術系水墨創作理論博士，馮老師將學院所學的水墨新思潮帶入社區，以多元技法、觀念引導的課程安排，帶領學員探索水墨的可能。彩墨班學員來自不同背景，年齡更跨越老、中、青三代，本次師生展特色除了有當代彩墨各種形式的呈現，每件作品皆來自學員們探索自我創作的巧思。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-04-01 00:00:00', '2025-04-25 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000887', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝文研習成果展－馮雯琳師生彩墨畫展', `description`='馮雯琳老師為國立臺灣師範大學美術系水墨創作理論博士，馮老師將學院所學的水墨新思潮帶入社區，以多元技法、觀念引導的課程安排，帶領學員探索水墨的可能。彩墨班學員來自不同背景，年齡更跨越老、中、青三代，本次師生展特色除了有當代彩墨各種形式的呈現，每件作品皆來自學員們探索自我創作的巧思。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000887', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288926b32419285b706f', '筆尖上的揮灑', '臺中市腦性麻痺關懷協會致力於服務腦性麻痺患者及其家庭，並提供全方位的支持與關懷。本次展覽匯集多位腦性麻痺藝術家的油畫創作，藉由畫筆揮灑，幫助患者表達內心世界，抒發心靈、提升自信，展現他們對生命的熱愛與才華。也期望透過藝術，拉近社會大眾與腦性麻痺者的距離，喚起更多對弱勢群體的關注。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-04-05 00:00:00', '2025-04-16 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000888', '[]') ON DUPLICATE KEY UPDATE `activity_name`='筆尖上的揮灑', `description`='臺中市腦性麻痺關懷協會致力於服務腦性麻痺患者及其家庭，並提供全方位的支持與關懷。本次展覽匯集多位腦性麻痺藝術家的油畫創作，藉由畫筆揮灑，幫助患者表達內心世界，抒發心靈、提升自信，展現他們對生命的熱愛與才華。也期望透過藝術，拉近社會大眾與腦性麻痺者的距離，喚起更多對弱勢群體的關注。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-16 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000888', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288926b32419285b7070', '第72屆中部美展', '「台灣中部美術協會」在臺灣文化藝術發展歷史，佔有舉足輕重的地位，更是中部地區第一個成立的藝術團體，民國43年由林之助、楊啟東、葉火城及王水河等藝術前輩及社會賢達共同於臺中發起創立，第一屆中部美展即是在當年的中央書局隆重揭幕，帶動中部美術走向更寬闊的領域，成為全省美展以外，與台陽美展、南部美展互相輝映，規模最大的民間美展。透過每年持續舉辦的「中部美展」，挹注臺中在地的文藝氣息，進而帶動民間藝文的創作能量。\r\n\r\n本次徵件廣納在全國各地作品近600件，在多位評審委員公正的評審後，遴選出138件作品。加上會員、評議委員、顧問、預備會員有出品之作品157件，總共展出295件作品，分油彩、墨彩、膠彩、水彩、雕塑、書法、攝影、版畫8個部別展出，今年最為特別的是邀請到第一屆中部美展水墨類的特選獎/洪耀宗先生作品《日暮倚修竹》參展，在家屬的全力協助下，72年前的作品及獎狀完整呈現出來，寫下了中部美展第72屆美麗的一頁。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-04-19 00:00:00', '2025-04-27 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000889', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第72屆中部美展', `description`='「台灣中部美術協會」在臺灣文化藝術發展歷史，佔有舉足輕重的地位，更是中部地區第一個成立的藝術團體，民國43年由林之助、楊啟東、葉火城及王水河等藝術前輩及社會賢達共同於臺中發起創立，第一屆中部美展即是在當年的中央書局隆重揭幕，帶動中部美術走向更寬闊的領域，成為全省美展以外，與台陽美展、南部美展互相輝映，規模最大的民間美展。透過每年持續舉辦的「中部美展」，挹注臺中在地的文藝氣息，進而帶動民間藝文的創作能量。\r\n\r\n本次徵件廣納在全國各地作品近600件，在多位評審委員公正的評審後，遴選出138件作品。加上會員、評議委員、顧問、預備會員有出品之作品157件，總共展出295件作品，分油彩、墨彩、膠彩、水彩、雕塑、書法、攝影、版畫8個部別展出，今年最為特別的是邀請到第一屆中部美展水墨類的特選獎/洪耀宗先生作品《日暮倚修竹》參展，在家屬的全力協助下，72年前的作品及獎狀完整呈現出來，寫下了中部美展第72屆美麗的一頁。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000889', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288926b32419285b7071', '生命有一隅－歐陽佑其陶藝個展', '作者本身長年照顧養護植物，也喜愛蒐集標本與礦石，創作中融入各種大自然的元素、紋理，以及帶進對其情感的投射。透過茶器、藝術盆、花器、雕塑等創作展現出蘊含生命群生的相依，以及遺世獨立的孤寂，交織錯落成獨一無二的風景。\r\n', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-04-26 00:00:00', '2025-05-14 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000890', '[]') ON DUPLICATE KEY UPDATE `activity_name`='生命有一隅－歐陽佑其陶藝個展', `description`='作者本身長年照顧養護植物，也喜愛蒐集標本與礦石，創作中融入各種大自然的元素、紋理，以及帶進對其情感的投射。透過茶器、藝術盆、花器、雕塑等創作展現出蘊含生命群生的相依，以及遺世獨立的孤寂，交織錯落成獨一無二的風景。\r\n', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-05-14 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000890', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288926b32419285b7072', '拾墨玩藝－臺中市烏日區藝術家學會會員聯展', '作品筆法精準而簡要，線條之啟承轉折流暢無滯，墨色之濃淡乾溼生動而有韻味，各個都有非凡的成就。會員們承襲固有的國畫及書法技巧，開創新的畫風、佈局，每幅作品的呈現，各有巧思樂在其中。展覽是要以畫會友，就教於同好藝文各界，供眾人欣賞、同理、感受獨特的美學情懷。', '臺中市大墩文化中心', '臺中市西區英才路600號', '2025-04-26 00:00:00', '2025-05-14 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000891', '[]') ON DUPLICATE KEY UPDATE `activity_name`='拾墨玩藝－臺中市烏日區藝術家學會會員聯展', `description`='作品筆法精準而簡要，線條之啟承轉折流暢無滯，墨色之濃淡乾溼生動而有韻味，各個都有非凡的成就。會員們承襲固有的國畫及書法技巧，開創新的畫風、佈局，每幅作品的呈現，各有巧思樂在其中。展覽是要以畫會友，就教於同好藝文各界，供眾人欣賞、同理、感受獨特的美學情懷。', `organizer`='臺中市大墩文化中心', `address`='臺中市西區英才路600號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-05-14 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/Exhibition/ActiveDetail?g=AAD0000891', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288926b32419285b7073', '中山73影視114年4月:惡水真相(3場)', '美國戰地攝影家史密斯，以殘暴又逼真的二戰找片聞名。他在二戰後決定隱居，但雜誌編輯羅伯特帶他來到日本熊本的水俁市，那是一個因日本窒素公司排放廢棄物而造成汞中毒的城市。史密斯將自己投入在這個城市當中，用相機記錄人們受水俁病所苦的症狀。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-04-02 00:00:00', '2025-04-27 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年4月:惡水真相(3場)', `description`='美國戰地攝影家史密斯，以殘暴又逼真的二戰找片聞名。他在二戰後決定隱居，但雜誌編輯羅伯特帶他來到日本熊本的水俁市，那是一個因日本窒素公司排放廢棄物而造成汞中毒的城市。史密斯將自己投入在這個城市當中，用相機記錄人們受水俁病所苦的症狀。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288926b32419285b7074', '臺中市豐韻音樂發展協會《朗朗弦鳴音樂會》', '本場音樂會由臺中市豐韻音樂發展協會承辦，特別邀請五位在各項樂器都學有專長很年輕的學子擔綱演出，笛子〜王晨馥；高笙〜易佳穎；二胡〜楊詠喨；琵琶〜陳奕璇；揚琴〜曾永濬，他們雖然年紀很輕，但琴齡都很長，參加音樂比賽屢獲佳績，他們將帶來多首大家耳熟能詳的樂曲與鄉親們分享，有花好月圓、民謠組曲和為配合「2018世界花博在臺中」委託盧亮輝老師編曲的《繁花》等，這群國中孩子熱愛音樂，期待與大家分享他們最愛的音樂，敬邀大家一起來，共度美好的午後時光！\r\n', '臺中市葫蘆墩文化中心', '臺中市豐原區圓環東路782號', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '臺中市葫蘆墩文化中心', 24.24990298, 120.7375715, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144539,3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市豐韻音樂發展協會《朗朗弦鳴音樂會》', `description`='本場音樂會由臺中市豐韻音樂發展協會承辦，特別邀請五位在各項樂器都學有專長很年輕的學子擔綱演出，笛子〜王晨馥；高笙〜易佳穎；二胡〜楊詠喨；琵琶〜陳奕璇；揚琴〜曾永濬，他們雖然年紀很輕，但琴齡都很長，參加音樂比賽屢獲佳績，他們將帶來多首大家耳熟能詳的樂曲與鄉親們分享，有花好月圓、民謠組曲和為配合「2018世界花博在臺中」委託盧亮輝老師編曲的《繁花》等，這群國中孩子熱愛音樂，期待與大家分享他們最愛的音樂，敬邀大家一起來，共度美好的午後時光！\r\n', `organizer`='臺中市葫蘆墩文化中心', `address`='臺中市豐原區圓環東路782號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='臺中市葫蘆墩文化中心', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144539,3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288926b32419285b7075', '中山73影視114年4月:老鷹之手(3場)', '嘉義牛斗山村早年盛產蓮藕，隨著時代變遷逐年沒落，榮景卻只停格在過去，如今種植人口僅剩二十七戶。長年挖蓮藕變形的「老鷹手」是他們辛勤的歷史印記。當農村青年大量北漂，從零開始學習蓮藕，即使面對傳統產業的困境，依舊用一雙「老鷹手」，挖出夢想。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-04-03 00:00:00', '2025-04-21 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年4月:老鷹之手(3場)', `description`='嘉義牛斗山村早年盛產蓮藕，隨著時代變遷逐年沒落，榮景卻只停格在過去，如今種植人口僅剩二十七戶。長年挖蓮藕變形的「老鷹手」是他們辛勤的歷史印記。當農村青年大量北漂，從零開始學習蓮藕，即使面對傳統產業的困境，依舊用一雙「老鷹手」，挖出夢想。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-04-03 00:00:00', `end_date`='2025-04-21 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288926b32419285b7076', '中山73影視114年4月:好好說再見(3場)', '戲劇表演教師班傑明意外發現自己罹患癌症，他無法面對現實、拒絕接受治療。而他年邁的母親得知兒子病情後，強忍著悲傷，試圖說服他接受痛苦的療程。班傑明在他生命的最後一段路上，靠著母親及主治醫師埃迪的陪伴，一步步接受現況，學習理解生命的意義。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-04-06 00:00:00', '2025-04-28 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年4月:好好說再見(3場)', `description`='戲劇表演教師班傑明意外發現自己罹患癌症，他無法面對現實、拒絕接受治療。而他年邁的母親得知兒子病情後，強忍著悲傷，試圖說服他接受痛苦的療程。班傑明在他生命的最後一段路上，靠著母親及主治醫師埃迪的陪伴，一步步接受現況，學習理解生命的意義。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-04-06 00:00:00', `end_date`='2025-04-28 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288926b32419285b7077', '中山73影視114年4月:人生最後一場拍賣會(4場)', '拍賣會上充滿古典名畫、精緻音樂盒，以及其他復古味的收藏品，且罕見地以極低的價格出清拍賣，吸引鄰居爭先恐後地來搶購。如此反常的舉動引來老鄰居的關心，紛紛上前阻止，沒想到竟引來克萊兒的激動反彈，並語出驚人、宣佈今天是他人生的最後一天。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-04-06 00:00:00', '2025-04-24 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年4月:人生最後一場拍賣會(4場)', `description`='拍賣會上充滿古典名畫、精緻音樂盒，以及其他復古味的收藏品，且罕見地以極低的價格出清拍賣，吸引鄰居爭先恐後地來搶購。如此反常的舉動引來老鄰居的關心，紛紛上前阻止，沒想到竟引來克萊兒的激動反彈，並語出驚人、宣佈今天是他人生的最後一天。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-04-06 00:00:00', `end_date`='2025-04-24 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288926b32419285b7078', '【石岡分館】「臺語冊．講乎咱聽」－3月書展', '以台語歌謠為主題，展出相關台語、音樂書籍，讓母語透過書本語文字融入日常生活。', '臺中市立圖書館石岡分館', '臺中市石岡區明德路175號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺中市立圖書館石岡分館', 24.26493299, 120.7903822, '無資料', 'https://reurl.cc/Q517vq', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【石岡分館】「臺語冊．講乎咱聽」－3月書展', `description`='以台語歌謠為主題，展出相關台語、音樂書籍，讓母語透過書本語文字融入日常生活。', `organizer`='臺中市立圖書館石岡分館', `address`='臺中市石岡區明德路175號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺中市立圖書館石岡分館', `latitude`=24.26493299, `longitude`=120.7903822, `ticket_price`='無資料', `source_url`='https://reurl.cc/Q517vq', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288926b32419285b7079', '中山73影視114年4月:再見小媽(3場)', '克萊兒是個極具天賦的助產士。但這些年來，他體貼細緻的接生專長與這份自信，卻都在現代醫學的進步下逐漸摧毀。某天，克萊兒接到一通電話，電話那端他父親生前那名浮誇與揮霍無度的情婦。在失聯30年後，聲稱有個重要消息想親口告訴她，並希望能見她一面。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-04-09 00:00:00', '2025-04-17 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+150;愛心票+75', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年4月:再見小媽(3場)', `description`='克萊兒是個極具天賦的助產士。但這些年來，他體貼細緻的接生專長與這份自信，卻都在現代醫學的進步下逐漸摧毀。某天，克萊兒接到一通電話，電話那端他父親生前那名浮誇與揮霍無度的情婦。在失聯30年後，聲稱有個重要消息想親口告訴她，並希望能見她一面。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-04-09 00:00:00', `end_date`='2025-04-17 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+150;愛心票+75', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288a26b32419285b707a', '中山73影視114年4月:維和防暴隊(3場)', '應聯合國請求、受國家派遣，余衛東、楊震、丁慧等維和警察肩負神聖使命，遠赴異國他鄉，深入戰火紛飛的任務區執行維和任務。他們將要直面恐怖襲擊、武裝暴動、黑幫衡行等種種險境，為維護世界和平與安全，維和行為刻不容緩。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+220;愛心票+110', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年4月:維和防暴隊(3場)', `description`='應聯合國請求、受國家派遣，余衛東、楊震、丁慧等維和警察肩負神聖使命，遠赴異國他鄉，深入戰火紛飛的任務區執行維和任務。他們將要直面恐怖襲擊、武裝暴動、黑幫衡行等種種險境，為維護世界和平與安全，維和行為刻不容緩。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+220;愛心票+110', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288a26b32419285b707b', '【石岡分館】3月-4月「中科國小翰墨書藝展」展覽', '於石岡分館一樓展示室展出「中科國小翰墨書藝展」展覽\r\n東勢區中科國小學生的書法作品在石岡圖書館展出囉，小朋友們利用各種媒材書寫出優異的書法作品，\r\n歡迎大家前來館觀展，給予參展學生最大的掌聲及鼓勵！', '臺中市立圖書館石岡分館', '臺中市石岡區明德路175號', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館石岡分館', 24.26493299, 120.7903822, '無資料', 'https://reurl.cc/eG0Ezm', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【石岡分館】3月-4月「中科國小翰墨書藝展」展覽', `description`='於石岡分館一樓展示室展出「中科國小翰墨書藝展」展覽\r\n東勢區中科國小學生的書法作品在石岡圖書館展出囉，小朋友們利用各種媒材書寫出優異的書法作品，\r\n歡迎大家前來館觀展，給予參展學生最大的掌聲及鼓勵！', `organizer`='臺中市立圖書館石岡分館', `address`='臺中市石岡區明德路175號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館石岡分館', `latitude`=24.26493299, `longitude`=120.7903822, `ticket_price`='無資料', `source_url`='https://reurl.cc/eG0Ezm', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288a26b32419285b707c', '【石岡分館】3月-4月「百年風華－石岡農會家政班竹編&拼布作品展」', '去年是石岡區農會的百週年慶，猶記得在石忠宮舉辦了一場盛大的「石農慶百年．龍中賺大錢」活動，很開心當天在現場展出的家政班拼布&竹編作品也來石岡圖書館展出，歡迎大家一起來回顧及欣賞農會這100年的歷史及風華。', '臺中市立圖書館石岡分館', '臺中市石岡區明德路175號', '2025-03-05 00:00:00', '2025-04-29 00:00:00', '臺中市立圖書館石岡分館', 24.26493299, 120.7903822, '無資料', 'https://reurl.cc/G5zb3Z', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【石岡分館】3月-4月「百年風華－石岡農會家政班竹編&拼布作品展」', `description`='去年是石岡區農會的百週年慶，猶記得在石忠宮舉辦了一場盛大的「石農慶百年．龍中賺大錢」活動，很開心當天在現場展出的家政班拼布&竹編作品也來石岡圖書館展出，歡迎大家一起來回顧及欣賞農會這100年的歷史及風華。', `organizer`='臺中市立圖書館石岡分館', `address`='臺中市石岡區明德路175號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='臺中市立圖書館石岡分館', `latitude`=24.26493299, `longitude`=120.7903822, `ticket_price`='無資料', `source_url`='https://reurl.cc/G5zb3Z', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288a26b32419285b707d', '中山73影視114年4月:警上添花(4場)', '桑托絲在丈夫殉職後，在印度政府政策安排下，繼承他的警察職位，成為新進員警。備受同事冷嘲熱諷的桑托絲，隨即受到資深女督察的賞識，指派他負責一樁低種性女孩謀殺案，隨著調查深入，一場深不見底的風暴也隨之席捲而來。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-04-16 00:00:00', '2025-04-30 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '全票+220;愛心票+110', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年4月:警上添花(4場)', `description`='桑托絲在丈夫殉職後，在印度政府政策安排下，繼承他的警察職位，成為新進員警。備受同事冷嘲熱諷的桑托絲，隨即受到資深女督察的賞識，指派他負責一樁低種性女孩謀殺案，隨著調查深入，一場深不見底的風暴也隨之席捲而來。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-04-16 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='全票+220;愛心票+110', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288a26b32419285b707e', '中山73影視114年4月:怪奇家族(3場)', '貝貝是名天才小提琴手，卻也是家中唯一不懂魔法的小孩。當她13歲生日到來時，她嚮往如其他家庭成員:骷顱哥哥、雙胞胎姊妹、會說話的狗狗一樣學習魔法，但爸媽卻不知為何反對她接觸魔法。當貝貝努力解開這個謎團時，她偶然發現家族黑歷史。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-04-02 00:00:00', '2025-04-19 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年4月:怪奇家族(3場)', `description`='貝貝是名天才小提琴手，卻也是家中唯一不懂魔法的小孩。當她13歲生日到來時，她嚮往如其他家庭成員:骷顱哥哥、雙胞胎姊妹、會說話的狗狗一樣學習魔法，但爸媽卻不知為何反對她接觸魔法。當貝貝努力解開這個謎團時，她偶然發現家族黑歷史。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288a26b32419285b707f', '中山73影視114年4月:狗狗歌劇院(3場)', '紐約大都會歌劇院正上演著世界最著名的歌舞劇《卡門》，而一隻名叫薩姆森的流浪狗在試圖逃離捕犬隊的過程中，意外流浪到繁華的紐約大都會歌劇院。她在那裡遇見了迷人的小白犬瑪格特，瑪格特的主人正是劇院首席歌舞劇女伶阿納斯塔西婭。', '財團法人臺中市影視發展基金會', '臺中市中區中山路73號', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '中山73影視藝文空間', 24.14168566, 120.680598, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山73影視114年4月:狗狗歌劇院(3場)', `description`='紐約大都會歌劇院正上演著世界最著名的歌舞劇《卡門》，而一隻名叫薩姆森的流浪狗在試圖逃離捕犬隊的過程中，意外流浪到繁華的紐約大都會歌劇院。她在那裡遇見了迷人的小白犬瑪格特，瑪格特的主人正是劇院首席歌舞劇女伶阿納斯塔西婭。', `organizer`='財團法人臺中市影視發展基金會', `address`='臺中市中區中山路73號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='中山73影視藝文空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288c26b32419285b7080', '【新北市立圖書館板橋分館】114年3月英文讀書會', '館名：新北市立圖書館板橋分館\r\n地址：新北市板橋區文化路一段23號1-3樓\r\n電話：02-29664347#9\r\n活動日期：3/7、3/14、3/21、3/28\r\n活動內容：以英文閱讀為橋梁提供學習機會，透過讀書會有效提升英文能力並增進樂趣，除促使自我成長外也為社區注入動力與活力，期能活躍學習氛圍。\r\n展演者︰許明慧講師', '新北市立圖書館總館', '新北市板橋區文化路一段23號3樓', '2025-03-07 00:00:00', '2025-03-28 00:00:00', '新北市立圖書館板橋分館', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館板橋分館】114年3月英文讀書會', `description`='館名：新北市立圖書館板橋分館\r\n地址：新北市板橋區文化路一段23號1-3樓\r\n電話：02-29664347#9\r\n活動日期：3/7、3/14、3/21、3/28\r\n活動內容：以英文閱讀為橋梁提供學習機會，透過讀書會有效提升英文能力並增進樂趣，除促使自我成長外也為社區注入動力與活力，期能活躍學習氛圍。\r\n展演者︰許明慧講師', `organizer`='新北市立圖書館總館', `address`='新北市板橋區文化路一段23號3樓', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='新北市立圖書館板橋分館', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288d26b32419285b7081', '2025臺中市美術家接力展：空的流動，光的吟遊－曲德華雕塑創作展', '臺中市美術家接力展第266棒接力展藝術家曲德華老師1954年出生，於國立臺灣師範大學美術系求學期間師承現代主義大師李仲生，畢業後負笈法國、澳洲深造，獲取3D視覺藝術碩士學位。學成歸國後致力於藝術教育，曾任教於國立臺中教育大學美術系及東海大學建築系，培育藝術人才無數。今年度獲選臺中市美術家接力展，以「空的流動，光的吟遊」為展覽主題，將20年間作品做一次的呈現。\r\n曲德華老師擅長以不銹鋼網創作幾何立體雕塑，從不同的視角欣賞，可以感受到光影、線條相互交織的層次。鋼網雕塑考驗創作者的耐心和毅力，需經過精密計算、嘗試，並克服媒材本身的剛硬特性，方能塑造出充滿張力與美感的造型。此次接力展將展出曲德華老師三角系列、花系列、葉系列及天梯系列等作品，誠摯地邀請觀者在流動的光影間，感受作品與空間的對話。', '臺中市葫蘆墩文化中心', '臺中市豐原區圓環東路782號', '2025-04-11 00:00:00', '2025-05-11 00:00:00', '臺中市葫蘆墩文化中心', 24.24990298, 120.7375715, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144552,1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺中市美術家接力展：空的流動，光的吟遊－曲德華雕塑創作展', `description`='臺中市美術家接力展第266棒接力展藝術家曲德華老師1954年出生，於國立臺灣師範大學美術系求學期間師承現代主義大師李仲生，畢業後負笈法國、澳洲深造，獲取3D視覺藝術碩士學位。學成歸國後致力於藝術教育，曾任教於國立臺中教育大學美術系及東海大學建築系，培育藝術人才無數。今年度獲選臺中市美術家接力展，以「空的流動，光的吟遊」為展覽主題，將20年間作品做一次的呈現。\r\n曲德華老師擅長以不銹鋼網創作幾何立體雕塑，從不同的視角欣賞，可以感受到光影、線條相互交織的層次。鋼網雕塑考驗創作者的耐心和毅力，需經過精密計算、嘗試，並克服媒材本身的剛硬特性，方能塑造出充滿張力與美感的造型。此次接力展將展出曲德華老師三角系列、花系列、葉系列及天梯系列等作品，誠摯地邀請觀者在流動的光影間，感受作品與空間的對話。', `organizer`='臺中市葫蘆墩文化中心', `address`='臺中市豐原區圓環東路782號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='臺中市葫蘆墩文化中心', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144552,1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288e26b32419285b7082', '空山花望月- 林宣余山居隱創作生活 ', '膠彩畫需一層一層地上色，礦物顏料重複堆疊於畫面上，細緻地表現光線的明暗，又因為「膠」的特性，鮮豔的色彩能長期保存，即使歷經歲月淘洗，仍歷久不衰。如此特殊的畫作過程，需經時間的積累，隨著過程紀錄人生中的點點滴滴。\r\n本次展出包括藝術家林宣余較早期的作品，也呈現近年來累積淬煉的創作心血。從表現花草生命韌性到巍峨山巔的〈花園子系列〉及〈風景系列〉、察覺內在心理至人性探討的〈人物系列〉與〈卡片系列〉，以畫筆呈現對自然與人性的深刻洞察，無論是對時代變遷的反思，還是內心世界的詮釋，都向我們講述著一個又一個鮮活的故事，展現不同階段的生命感悟。', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-03-22 00:00:00', '2025-05-18 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=988bff7c5d2047aab4532edb2e57a710', '[]') ON DUPLICATE KEY UPDATE `activity_name`='空山花望月- 林宣余山居隱創作生活 ', `description`='膠彩畫需一層一層地上色，礦物顏料重複堆疊於畫面上，細緻地表現光線的明暗，又因為「膠」的特性，鮮豔的色彩能長期保存，即使歷經歲月淘洗，仍歷久不衰。如此特殊的畫作過程，需經時間的積累，隨著過程紀錄人生中的點點滴滴。\r\n本次展出包括藝術家林宣余較早期的作品，也呈現近年來累積淬煉的創作心血。從表現花草生命韌性到巍峨山巔的〈花園子系列〉及〈風景系列〉、察覺內在心理至人性探討的〈人物系列〉與〈卡片系列〉，以畫筆呈現對自然與人性的深刻洞察，無論是對時代變遷的反思，還是內心世界的詮釋，都向我們講述著一個又一個鮮活的故事，展現不同階段的生命感悟。', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=988bff7c5d2047aab4532edb2e57a710', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288f26b32419285b7083', '空山花望月- 林宣余山居隱創作生活  現場導覽', '膠彩畫需一層一層地上色，礦物顏料重複堆疊於畫面上，細緻地表現光線的明暗，又因為「膠」的特性，鮮豔的色彩能長期保存，即使歷經歲月淘洗，仍歷久不衰。如此特殊的畫作過程，需經時間的積累，隨著過程紀錄人生中的點點滴滴。\r\n本次展出包括藝術家林宣余較早期的作品，也呈現近年來累積淬煉的創作心血。從表現花草生命韌性到巍峨山巔的〈花園子系列〉及〈風景系列〉、察覺內在心理至人性探討的〈人物系列〉與〈卡片系列〉，以畫筆呈現對自然與人性的深刻洞察，無論是對時代變遷的反思，還是內心世界的詮釋，都向我們講述著一個又一個鮮活的故事，展現不同階段的生命感悟。', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-03-22 00:00:00', '2025-03-29 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://activity.culture.taichung.gov.tw/activites/index-1.asp?id=144559', '[]') ON DUPLICATE KEY UPDATE `activity_name`='空山花望月- 林宣余山居隱創作生活  現場導覽', `description`='膠彩畫需一層一層地上色，礦物顏料重複堆疊於畫面上，細緻地表現光線的明暗，又因為「膠」的特性，鮮豔的色彩能長期保存，即使歷經歲月淘洗，仍歷久不衰。如此特殊的畫作過程，需經時間的積累，隨著過程紀錄人生中的點點滴滴。\r\n本次展出包括藝術家林宣余較早期的作品，也呈現近年來累積淬煉的創作心血。從表現花草生命韌性到巍峨山巔的〈花園子系列〉及〈風景系列〉、察覺內在心理至人性探討的〈人物系列〉與〈卡片系列〉，以畫筆呈現對自然與人性的深刻洞察，無論是對時代變遷的反思，還是內心世界的詮釋，都向我們講述著一個又一個鮮活的故事，展現不同階段的生命感悟。', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-29 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://activity.culture.taichung.gov.tw/activites/index-1.asp?id=144559', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288f26b32419285b7084', '點點心緒-李安琦創作個展  ', '「表琦」是展出者的創作核心，象徵心中不同表情的自己，透過拍照、分色、輸出與剪貼的過程，這些微小的表情拼貼看似簡單，但匯聚成的密集感，猶如無所適從時內心的恐懼，將這些情感化作數萬張表琦拼貼在作品中，以此表達自我、情感、慾望、記憶與家庭的連結。藉由這樣的創作過程，重新回顧創作著的學習歷程並省思了許多往事，期將表琦拼貼作為創作著標誌性的特徵望能在創作中凝視自己的內心，並藉由創作獲得心靈上的轉換與平靜。\r\n本次展出是創作者在藝術場館的首次個展，不僅是創作的展現，也為自己多年藝術學習生涯留下紀錄。藉由個展，向觀者揭露他的內心世界，感受多種情緒與想法並存時帶來的紛擾不安，是一輩子都必須面對的課題，將這樣的困擾轉化為創作展現出來。', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-03-29 00:00:00', '2025-04-20 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=632175fcd1fb48f8a16e874152a8fbff', '[]') ON DUPLICATE KEY UPDATE `activity_name`='點點心緒-李安琦創作個展  ', `description`='「表琦」是展出者的創作核心，象徵心中不同表情的自己，透過拍照、分色、輸出與剪貼的過程，這些微小的表情拼貼看似簡單，但匯聚成的密集感，猶如無所適從時內心的恐懼，將這些情感化作數萬張表琦拼貼在作品中，以此表達自我、情感、慾望、記憶與家庭的連結。藉由這樣的創作過程，重新回顧創作著的學習歷程並省思了許多往事，期將表琦拼貼作為創作著標誌性的特徵望能在創作中凝視自己的內心，並藉由創作獲得心靈上的轉換與平靜。\r\n本次展出是創作者在藝術場館的首次個展，不僅是創作的展現，也為自己多年藝術學習生涯留下紀錄。藉由個展，向觀者揭露他的內心世界，感受多種情緒與想法並存時帶來的紛擾不安，是一輩子都必須面對的課題，將這樣的困擾轉化為創作展現出來。', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=632175fcd1fb48f8a16e874152a8fbff', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db288f26b32419285b7085', '美麗臺灣-駐館藝術家蘇智偉水印木刻版畫個展', '創作者李安琦目前服務於清水區甲南國小與槺榔國小，擔任美勞共聘教師的工作。出身於苗栗縣通霄鎮，從小立志要當老師，有幸在105年透過教師甄選分發至清水區服務至今，自求學階段都是就讀美術班，並在112年自清華大學美勞教育研究所畢業，此次展出的作品即為研究所之創作，是延續自新竹教育大學藝術與設計系畢業時的創作而來，作品主要以探討自我內在世界為主題，融合自己的成長經驗、心理狀態、情緒表達…等方面，透過一張張自己的臉孔組合而成的畫面，將自己複雜的心靈思緒以較為具象的方式呈現出來。', '臺中市港區藝術中心', '臺中市清水區忠貞路21號', '2025-03-15 00:00:00', '2025-09-14 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=a454a23ab1cc47cbbba95e6d46e22035', '[]') ON DUPLICATE KEY UPDATE `activity_name`='美麗臺灣-駐館藝術家蘇智偉水印木刻版畫個展', `description`='創作者李安琦目前服務於清水區甲南國小與槺榔國小，擔任美勞共聘教師的工作。出身於苗栗縣通霄鎮，從小立志要當老師，有幸在105年透過教師甄選分發至清水區服務至今，自求學階段都是就讀美術班，並在112年自清華大學美勞教育研究所畢業，此次展出的作品即為研究所之創作，是延續自新竹教育大學藝術與設計系畢業時的創作而來，作品主要以探討自我內在世界為主題，融合自己的成長經驗、心理狀態、情緒表達…等方面，透過一張張自己的臉孔組合而成的畫面，將自己複雜的心靈思緒以較為具象的方式呈現出來。', `organizer`='臺中市港區藝術中心', `address`='臺中市清水區忠貞路21號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-09-14 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://tcsac.taichung.gov.tw/Exhibition/Exhibition_More?id=a454a23ab1cc47cbbba95e6d46e22035', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289326b32419285b7086', '海笛學生音樂發表會', '計畫源起:\r\n以上台表演方式鼓勵並增進學生學習音樂之興趣，提昇音樂演奏水準，為台灣推廣音樂教育。希望學生透過開放式的一次次表演經驗，為孩子找出最佳學習方向，累積最佳基礎實力。自信來自於面對挑戰的勇氣，迎接挑戰，為孩子做好站上世界舞台的準備，充實自己的音樂內涵。\r\n活動計畫:\r\n1.演出內容簡介\r\n鋼琴、提琴、吉他、國樂獨奏、合奏演出\r\n2.節目規劃 (演出長度與演出人數)\r\n演出長度: 09:00-12:00\r\n演出人數兩場預計總人數50位左右\r\n演出曲目:\r\n1.程裔臻/STALEGA RHAPSODY/古凱茵老師\r\n2.鄭宸孜/TARANTELLA VIVA/古凱茵老師\r\n3.張芸紜/吹口琴的人/林己純老師\r\n4.張羽葳/BARN DANCE/古凱茵老師\r\n5.林子恩/踢踏舞者/賴妍菲老師……等……曲目演出。\r\n', '台中私立海笛音樂短期補習班', '臺中市西區英才路600號', '2025-04-27 00:00:00', '2025-04-27 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000711', '[]') ON DUPLICATE KEY UPDATE `activity_name`='海笛學生音樂發表會', `description`='計畫源起:\r\n以上台表演方式鼓勵並增進學生學習音樂之興趣，提昇音樂演奏水準，為台灣推廣音樂教育。希望學生透過開放式的一次次表演經驗，為孩子找出最佳學習方向，累積最佳基礎實力。自信來自於面對挑戰的勇氣，迎接挑戰，為孩子做好站上世界舞台的準備，充實自己的音樂內涵。\r\n活動計畫:\r\n1.演出內容簡介\r\n鋼琴、提琴、吉他、國樂獨奏、合奏演出\r\n2.節目規劃 (演出長度與演出人數)\r\n演出長度: 09:00-12:00\r\n演出人數兩場預計總人數50位左右\r\n演出曲目:\r\n1.程裔臻/STALEGA RHAPSODY/古凱茵老師\r\n2.鄭宸孜/TARANTELLA VIVA/古凱茵老師\r\n3.張芸紜/吹口琴的人/林己純老師\r\n4.張羽葳/BARN DANCE/古凱茵老師\r\n5.林子恩/踢踏舞者/賴妍菲老師……等……曲目演出。\r\n', `organizer`='台中私立海笛音樂短期補習班', `address`='臺中市西區英才路600號', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000711', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289326b32419285b7087', '小孤鼓-街頭藝人電子打擊樂演奏', '展演內容：范植傑(街頭藝人證號A1131331)喜歡現場表演，本次演出內容將會使用電子鼓(新型打擊版)，音色豐富悅耳耐聽，可控制音量輸出，同時會攜帶音箱，將串流音樂導入，選取方面涵蓋樂團歌曲到流行曲，希望能透過表演帶給經過觀眾們開心的能量。', '范植傑', '臺中市西區英才路600號', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000712', '[]') ON DUPLICATE KEY UPDATE `activity_name`='小孤鼓-街頭藝人電子打擊樂演奏', `description`='展演內容：范植傑(街頭藝人證號A1131331)喜歡現場表演，本次演出內容將會使用電子鼓(新型打擊版)，音色豐富悅耳耐聽，可控制音量輸出，同時會攜帶音箱，將串流音樂導入，選取方面涵蓋樂團歌曲到流行曲，希望能透過表演帶給經過觀眾們開心的能量。', `organizer`='范植傑', `address`='臺中市西區英才路600號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000712', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289326b32419285b7088', '悠藍音樂藝術教室成果發表會', '活動目的:\r\n1.展示才華:提供教師師生展示音樂才華和成果的平台，讓親朋好友觀眾欣賞並共同分享音樂的美好。\r\n2.促進交流:發現更多學習音樂的夥伴，讓孩子跟家長們都能分享音樂學習培養的經驗，能有更多的交流和互動。\r\n3.激勵學習:激勵參與者讚音樂領域取得更高的成就，為學生提供學習的動力，同時鼓勵學員繼續不斷精進自己的技能。\r\n4.音樂推廣:透過音樂成果發表會，讓觀眾認識不同音樂風格和曲目的多樣性，在聆聽的過程中同時提升自己的音樂素養。\r\n表演曲目:\r\n1.成奕勳、俊豪老師Ode to joy……………小提琴二重奏\r\n2.李軒亦Star Wars……………......鋼琴獨奏\r\n3.謝承祐I Just Can''t Wait toBe King獅子王……………………鋼琴獨奏\r\n4.蔡聿婕 靜夜星空……………………………烏克麗麗獨奏\r\n5.李幸恩、楟珽老師 Beauty and theBeast美女與野獸…………四手聯彈\r\n6.成奕勳 孤勇者………………..小提琴獨奏\r\n7.范家銓 一人一半……………吉他自彈自唱\r\n8.………………等曲目演出……………………..   \r\n\r\n\r\n', '悠藍音樂藝術教室', '臺中市西區英才路600號', '2025-04-13 00:00:00', '2025-04-13 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000713', '[]') ON DUPLICATE KEY UPDATE `activity_name`='悠藍音樂藝術教室成果發表會', `description`='活動目的:\r\n1.展示才華:提供教師師生展示音樂才華和成果的平台，讓親朋好友觀眾欣賞並共同分享音樂的美好。\r\n2.促進交流:發現更多學習音樂的夥伴，讓孩子跟家長們都能分享音樂學習培養的經驗，能有更多的交流和互動。\r\n3.激勵學習:激勵參與者讚音樂領域取得更高的成就，為學生提供學習的動力，同時鼓勵學員繼續不斷精進自己的技能。\r\n4.音樂推廣:透過音樂成果發表會，讓觀眾認識不同音樂風格和曲目的多樣性，在聆聽的過程中同時提升自己的音樂素養。\r\n表演曲目:\r\n1.成奕勳、俊豪老師Ode to joy……………小提琴二重奏\r\n2.李軒亦Star Wars……………......鋼琴獨奏\r\n3.謝承祐I Just Can''t Wait toBe King獅子王……………………鋼琴獨奏\r\n4.蔡聿婕 靜夜星空……………………………烏克麗麗獨奏\r\n5.李幸恩、楟珽老師 Beauty and theBeast美女與野獸…………四手聯彈\r\n6.成奕勳 孤勇者………………..小提琴獨奏\r\n7.范家銓 一人一半……………吉他自彈自唱\r\n8.………………等曲目演出……………………..   \r\n\r\n\r\n', `organizer`='悠藍音樂藝術教室', `address`='臺中市西區英才路600號', `start_date`='2025-04-13 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000713', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289326b32419285b7089', '布拉姆斯 弦樂五重奏室內樂音樂會 2', '曲目:\r\n布拉奶斯 F大训第一號强更五重费·作品88(1682)\r\nJ. Brahms: String Quintet No. 1 in F major, Op. 88 (1882)\r\n布拉姆斯:G大貂第二號弦兼五重奏·作品1111(1890)\r\nJ. Brahms: String Quintet No. 2 in G major, Op. 111 (1890)', '國立臺南藝術大學', '臺南市官田區66號', '2025-03-30 00:00:00', '2025-03-30 00:00:00', '國立臺南藝術大學', 23.19098548, 120.3479918, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='布拉姆斯 弦樂五重奏室內樂音樂會 2', `description`='曲目:\r\n布拉奶斯 F大训第一號强更五重费·作品88(1682)\r\nJ. Brahms: String Quintet No. 1 in F major, Op. 88 (1882)\r\n布拉姆斯:G大貂第二號弦兼五重奏·作品1111(1890)\r\nJ. Brahms: String Quintet No. 2 in G major, Op. 111 (1890)', `organizer`='國立臺南藝術大學', `address`='臺南市官田區66號', `start_date`='2025-03-30 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='國立臺南藝術大學', `latitude`=23.19098548, `longitude`=120.3479918, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289326b32419285b708a', '【新北市立圖書館蘆洲兒童親子分館】114年3月彩虹故事屋', '【蘆洲兒童親子分館】114年3月份彩虹故事屋\r\n\r\n時間：114年03月08日、114年03月15日、114年03月22日  13:30~14:30\r\n\r\n \r\n\r\n03/08(六)\r\n\r\n School Bus Trip\r\n\r\nPeppa Pig - Peppa And The Children''s Fete!-Cailyn\r\n \r\n\r\n03/15(六)\r\n\r\n從手動到腳-秀鳳&麗鳳\r\n \r\n\r\n03/22(六)\r\n\r\n冷吱吱便利店-麗君\r\n\r\n魯拉魯先生的腳踏車-Paggy\r\n\r\n\r\n \r\n\r\n＊活動單位保有取消、變更之權利，詳情請依現場為主。\r\n\r\n＊免費入場，無須報名，場內除白開水以外禁止飲食。\r\n\r\n \r\n\r\n位置：新北市蘆洲區集賢路221巷11號3樓/親子互動區。\r\n\r\n洽詢電話:02-2288-8294。\r\n\r\n \r\n\r\n交通\r\n\r\n搭乘公車：\r\n\r\n可搭乘811、815、816、927、928、紅9、橘13、橘19至集賢路口站下車步行約3-5分鐘即達。\r\n\r\n搭乘捷運：\r\n\r\n蘆洲線至徐匯中學站2號出口，往集賢路尼加拉瓜公園方向，步行約15-18分鐘即達。\r\n\r\n騎乘微笑單車：\r\n\r\n捷運蘆洲線徐匯中學站1號出口，往集賢路尼加拉瓜公園方向，騎行至蘆洲區重陽公園。', '新北市立圖書館總館', '新北市蘆洲區集賢路221巷11號2樓~3樓', '2025-03-08 00:00:00', '2025-03-22 00:00:00', '新北市立圖書館蘆洲兒童親子分館', 25.08927173, 121.4712461, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館蘆洲兒童親子分館】114年3月彩虹故事屋', `description`='【蘆洲兒童親子分館】114年3月份彩虹故事屋\r\n\r\n時間：114年03月08日、114年03月15日、114年03月22日  13:30~14:30\r\n\r\n \r\n\r\n03/08(六)\r\n\r\n School Bus Trip\r\n\r\nPeppa Pig - Peppa And The Children''s Fete!-Cailyn\r\n \r\n\r\n03/15(六)\r\n\r\n從手動到腳-秀鳳&麗鳳\r\n \r\n\r\n03/22(六)\r\n\r\n冷吱吱便利店-麗君\r\n\r\n魯拉魯先生的腳踏車-Paggy\r\n\r\n\r\n \r\n\r\n＊活動單位保有取消、變更之權利，詳情請依現場為主。\r\n\r\n＊免費入場，無須報名，場內除白開水以外禁止飲食。\r\n\r\n \r\n\r\n位置：新北市蘆洲區集賢路221巷11號3樓/親子互動區。\r\n\r\n洽詢電話:02-2288-8294。\r\n\r\n \r\n\r\n交通\r\n\r\n搭乘公車：\r\n\r\n可搭乘811、815、816、927、928、紅9、橘13、橘19至集賢路口站下車步行約3-5分鐘即達。\r\n\r\n搭乘捷運：\r\n\r\n蘆洲線至徐匯中學站2號出口，往集賢路尼加拉瓜公園方向，步行約15-18分鐘即達。\r\n\r\n騎乘微笑單車：\r\n\r\n捷運蘆洲線徐匯中學站1號出口，往集賢路尼加拉瓜公園方向，騎行至蘆洲區重陽公園。', `organizer`='新北市立圖書館總館', `address`='新北市蘆洲區集賢路221巷11號2樓~3樓', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='新北市立圖書館蘆洲兒童親子分館', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289326b32419285b708b', '文化部國家語言發展計畫-金枝演社《可愛冤仇人》', '臺客第一天團「金枝演社」隆重登場！\r\n一場笑聲不斷、感動滿滿的臺語歌舞喜劇《可愛冤仇人》帶你穿越50至70年代的臺灣，重現三廳電影院的浪漫、金光戲的熱鬧，以及老式臺語片的溫馨感動，搭配經典老歌，打造臺味戲劇盛宴！\r\n(本場演出獲文化部國家語言發展計畫支持)\r\n苦命酒家女癡戀街頭賣肉粽仔？\r\n火爆浪子愛上駐唱的清純少女？\r\n富家千金與公子勇闖三角戀情場？\r\n這場笑料百出的愛情追逐戰，讓你笑中帶淚，感受人生真摯情感！\r\n📅 演出時間：114/4/20 (日) 19:00\r\n📍 演出地點：潭子潭水亭觀音媽廟前廣場\r\n🎟 入場方式：免費欣賞\r\n指導單位:臺中市政府、文化部\r\n主辦單位:\r\n臺中市政府文化局、財團法人臺中市文化建設基金會、潭水亭觀音媽廟\r\n承辦單位:臺中市葫蘆墩文化中心', '臺中市政府文化局', '臺中市潭子區', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '潭子區（臺中市）=', 24.21171121, 120.710997, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144762,3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='文化部國家語言發展計畫-金枝演社《可愛冤仇人》', `description`='臺客第一天團「金枝演社」隆重登場！\r\n一場笑聲不斷、感動滿滿的臺語歌舞喜劇《可愛冤仇人》帶你穿越50至70年代的臺灣，重現三廳電影院的浪漫、金光戲的熱鬧，以及老式臺語片的溫馨感動，搭配經典老歌，打造臺味戲劇盛宴！\r\n(本場演出獲文化部國家語言發展計畫支持)\r\n苦命酒家女癡戀街頭賣肉粽仔？\r\n火爆浪子愛上駐唱的清純少女？\r\n富家千金與公子勇闖三角戀情場？\r\n這場笑料百出的愛情追逐戰，讓你笑中帶淚，感受人生真摯情感！\r\n📅 演出時間：114/4/20 (日) 19:00\r\n📍 演出地點：潭子潭水亭觀音媽廟前廣場\r\n🎟 入場方式：免費欣賞\r\n指導單位:臺中市政府、文化部\r\n主辦單位:\r\n臺中市政府文化局、財團法人臺中市文化建設基金會、潭水亭觀音媽廟\r\n承辦單位:臺中市葫蘆墩文化中心', `organizer`='臺中市政府文化局', `address`='臺中市潭子區', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='潭子區（臺中市）=', `latitude`=24.21171121, `longitude`=120.710997, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144762,3', `image_url`='[]';
