INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289426b32419285b708f', '114年【風迴大地- 部落傳聲】 兒童原民繪本主題書展', '結合今年多元閱讀推廣世界母語日活動\r\n，並在前鎮分館5樓拼板舟書展區 展示相關原民兒童繪本。讓大朋友小朋友了解台灣原住民族的歷史、語言、傳統及習俗文化等...\r\n', '高雄市立圖書館總館', '高雄市前鎮區保泰路303號4樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '高雄市立圖書館前鎮分館', 22.602476, 120.333005, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年【風迴大地- 部落傳聲】 兒童原民繪本主題書展', `description`='結合今年多元閱讀推廣世界母語日活動\r\n，並在前鎮分館5樓拼板舟書展區 展示相關原民兒童繪本。讓大朋友小朋友了解台灣原住民族的歷史、語言、傳統及習俗文化等...\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市前鎮區保泰路303號4樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市立圖書館前鎮分館', `latitude`=22.602476, `longitude`=120.333005, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289426b32419285b7090', '臺中市立圖書館西區分館【花．果．珍禽—黃苡蓁老師彩墨畫展】', '黃苡蓁老師以傳統水墨畫的精髓，融合現代彩墨技法，描繪大自然的生機與靈動。此次以花、果、珍禽為主題，呈現花卉、果實與珍禽的優雅風采，花朵綻放著生命力，果實豐潤飽滿，珍禽以靈動的姿態穿梭於枝葉間，展現出悠然自得的神態。濃淡相宜的墨韻與層層疊染的色彩交織，讓每一幅作品都彷彿蘊含著自然的氣息與故事。誠摯邀請您蒞臨展覽，一同感受彩墨藝術的獨特魅力。', '臺中市立圖書館西區分館', '臺中市西區精誠路256號', '2025-03-16 00:00:00', '2025-05-15 00:00:00', '臺中市立圖書館西區分館', 24.14944, 120.654959, '無資料', 'https://reurl.cc/OY1v8v', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館西區分館【花．果．珍禽—黃苡蓁老師彩墨畫展】', `description`='黃苡蓁老師以傳統水墨畫的精髓，融合現代彩墨技法，描繪大自然的生機與靈動。此次以花、果、珍禽為主題，呈現花卉、果實與珍禽的優雅風采，花朵綻放著生命力，果實豐潤飽滿，珍禽以靈動的姿態穿梭於枝葉間，展現出悠然自得的神態。濃淡相宜的墨韻與層層疊染的色彩交織，讓每一幅作品都彷彿蘊含著自然的氣息與故事。誠摯邀請您蒞臨展覽，一同感受彩墨藝術的獨特魅力。', `organizer`='臺中市立圖書館西區分館', `address`='臺中市西區精誠路256號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-05-15 00:00:00', `location`='臺中市立圖書館西區分館', `latitude`=24.14944, `longitude`=120.654959, `ticket_price`='無資料', `source_url`='https://reurl.cc/OY1v8v', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289426b32419285b7091', '二十世紀三首鋼琴協奏曲 Three Piano Concertos from 20th Century', '節目介紹\r\n拉赫瑪尼諾夫第四號鋼琴協奏曲充滿戲劇性與深刻情感，融合浪漫與現代風格，展現其晚期創作特色。\r\n\r\n蓋希文《藍色狂想曲》將古典與爵士結合，充滿城市活力與自由律動，展現美國音樂新風貌。\r\n\r\n蕭士塔高維奇第一號鋼琴協奏曲最特別的地方是採用了進行曲和圓舞曲，曲子讓人聯想到羅西尼和米老鼠共舞的滑稽畫面。\r\n\r\n演出曲目：\r\n⏣ 拉赫曼尼諾夫(1873-1943) G 小調\r\n第四號鋼琴協奏曲，作品40\r\nSergei Rachmaninov - Piano\r\nConcerto No.4 in G minor Op.40\r\n⏣ 蓋希文《藍色狂想曲》\r\nGershwin – Rhapsody in Blue\r\n⏣ 蕭士塔高維奇：C小調第一號鋼琴\r\n協奏曲，作品35\r\nShostakovich - Piano Concerto\r\nNo.1 in C minor Op.35\r\n\r\n演出人員：鋼琴／陳介涵\r\n畢業於美國茱莉亞音樂院與俄羅斯柴可夫斯基音樂院兩大名校的鋼琴家。\r\n\r\n2002年獲義大利蒙諾波利國際鋼琴大賽冠軍，並獲義大利樂評盛讚為「使鋼琴說話的女孩」。\r\n\r\n2004年獲選為中正文化中心兩廳院樂壇新秀。\r\n\r\n2005、2006年蟬聯兩屆東森育英獎學金鋼琴藝術首獎。\r\n\r\n2005年入選文建會「國際人才庫」。\r\n\r\n2011年獲教育部藝術學群演奏組留俄獎學金。\r\n\r\n近年來以鋼琴家身份嶄露頭角，經常於俄羅斯、臺灣舉行獨奏會，並與國內各大樂團演出鋼琴協奏曲，包括國家交響樂團、\r\n\r\n市民交響樂團、陽光台北交響樂團、大稻埕交響樂團、臺灣國樂團、及中華國樂團。\r\n\r\n在頻繁演出行程外，也投入相當心力於音樂教育與音樂教學，目前為國立臺灣戲曲學院兼任助理教授，同時任教師大附中、新北高中、新店高中與南門國中音樂班。\r\n\r\n鋼琴合作／王一心\r\n\r\n畢業於大安高工電子科、國立中山大學音樂系及東吳大學音樂研究所，主修鋼琴。曾師事王婷芝、陳美富、陳盤安及諸大明教授。\r\n\r\n2000年獲行天宮明日之星「菁音獎」鋼琴少年組全國第三名。2001年YAMAHA 鋼琴大賽高中組第一名。\r\n\r\n2003年台灣學生音樂比賽大專組第三名。\r\n\r\n2005年中山大學協奏曲比賽優勝，於高雄至德堂演出李斯特第一號鋼琴協奏曲。\r\n\r\n2007年參加第七屆湖湘文化之旅，於兩岸音樂交流演出史特拉汶斯基之《彼得洛西卡》。\r\n\r\n2008年東吳大學音樂系鋼琴與弦樂奏鳴曲比賽優勝。\r\n\r\n2008年第12屆國際台北蕭邦鋼琴大賽入圍複賽。\r\n\r\n2014年「哈爾濱之夏」國際手風琴大賽室內樂組第二名。\r\n\r\n2016年與探戈樂團Tanvolution 赴阿根廷探戈藝術節演出。\r\n\r\n曾多次擔任台北市立國樂團民族器樂大賽指定伴奏。並多次參與國際魔笛單簧管音樂節、北京單簧管音樂節、徐家駒低音管室內樂團夏令營及台灣國際長笛藝術節之音樂會演出。常與國內外知名演奏家合作，如前台北市立交響樂團單簧管首席陳威稜、新加坡交響樂團首席馬越、朗帕爾國際長笛大賽冠軍上野星矢、鹿特丹愛樂單簧管首席 Julien Herve、知名單簧管演奏家Florent Heau、Nathan Williams、翟耀光，及德州大學奧斯汀分校單簧管教授Jonathan Gunn、威瑪李斯特音樂院低音管教授 Frank Forst 等人。', '蘭城愛樂', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-04-21 00:00:00', '2025-04-21 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500;--+800;--+1000;--+1200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='二十世紀三首鋼琴協奏曲 Three Piano Concertos from 20th Century', `description`='節目介紹\r\n拉赫瑪尼諾夫第四號鋼琴協奏曲充滿戲劇性與深刻情感，融合浪漫與現代風格，展現其晚期創作特色。\r\n\r\n蓋希文《藍色狂想曲》將古典與爵士結合，充滿城市活力與自由律動，展現美國音樂新風貌。\r\n\r\n蕭士塔高維奇第一號鋼琴協奏曲最特別的地方是採用了進行曲和圓舞曲，曲子讓人聯想到羅西尼和米老鼠共舞的滑稽畫面。\r\n\r\n演出曲目：\r\n⏣ 拉赫曼尼諾夫(1873-1943) G 小調\r\n第四號鋼琴協奏曲，作品40\r\nSergei Rachmaninov - Piano\r\nConcerto No.4 in G minor Op.40\r\n⏣ 蓋希文《藍色狂想曲》\r\nGershwin – Rhapsody in Blue\r\n⏣ 蕭士塔高維奇：C小調第一號鋼琴\r\n協奏曲，作品35\r\nShostakovich - Piano Concerto\r\nNo.1 in C minor Op.35\r\n\r\n演出人員：鋼琴／陳介涵\r\n畢業於美國茱莉亞音樂院與俄羅斯柴可夫斯基音樂院兩大名校的鋼琴家。\r\n\r\n2002年獲義大利蒙諾波利國際鋼琴大賽冠軍，並獲義大利樂評盛讚為「使鋼琴說話的女孩」。\r\n\r\n2004年獲選為中正文化中心兩廳院樂壇新秀。\r\n\r\n2005、2006年蟬聯兩屆東森育英獎學金鋼琴藝術首獎。\r\n\r\n2005年入選文建會「國際人才庫」。\r\n\r\n2011年獲教育部藝術學群演奏組留俄獎學金。\r\n\r\n近年來以鋼琴家身份嶄露頭角，經常於俄羅斯、臺灣舉行獨奏會，並與國內各大樂團演出鋼琴協奏曲，包括國家交響樂團、\r\n\r\n市民交響樂團、陽光台北交響樂團、大稻埕交響樂團、臺灣國樂團、及中華國樂團。\r\n\r\n在頻繁演出行程外，也投入相當心力於音樂教育與音樂教學，目前為國立臺灣戲曲學院兼任助理教授，同時任教師大附中、新北高中、新店高中與南門國中音樂班。\r\n\r\n鋼琴合作／王一心\r\n\r\n畢業於大安高工電子科、國立中山大學音樂系及東吳大學音樂研究所，主修鋼琴。曾師事王婷芝、陳美富、陳盤安及諸大明教授。\r\n\r\n2000年獲行天宮明日之星「菁音獎」鋼琴少年組全國第三名。2001年YAMAHA 鋼琴大賽高中組第一名。\r\n\r\n2003年台灣學生音樂比賽大專組第三名。\r\n\r\n2005年中山大學協奏曲比賽優勝，於高雄至德堂演出李斯特第一號鋼琴協奏曲。\r\n\r\n2007年參加第七屆湖湘文化之旅，於兩岸音樂交流演出史特拉汶斯基之《彼得洛西卡》。\r\n\r\n2008年東吳大學音樂系鋼琴與弦樂奏鳴曲比賽優勝。\r\n\r\n2008年第12屆國際台北蕭邦鋼琴大賽入圍複賽。\r\n\r\n2014年「哈爾濱之夏」國際手風琴大賽室內樂組第二名。\r\n\r\n2016年與探戈樂團Tanvolution 赴阿根廷探戈藝術節演出。\r\n\r\n曾多次擔任台北市立國樂團民族器樂大賽指定伴奏。並多次參與國際魔笛單簧管音樂節、北京單簧管音樂節、徐家駒低音管室內樂團夏令營及台灣國際長笛藝術節之音樂會演出。常與國內外知名演奏家合作，如前台北市立交響樂團單簧管首席陳威稜、新加坡交響樂團首席馬越、朗帕爾國際長笛大賽冠軍上野星矢、鹿特丹愛樂單簧管首席 Julien Herve、知名單簧管演奏家Florent Heau、Nathan Williams、翟耀光，及德州大學奧斯汀分校單簧管教授Jonathan Gunn、威瑪李斯特音樂院低音管教授 Frank Forst 等人。', `organizer`='蘭城愛樂', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-04-21 00:00:00', `end_date`='2025-04-21 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500;--+800;--+1000;--+1200', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289426b32419285b7092', 'Fire Live Presents: NELL w/傻子與白痴 Fool and Idiot', '韓國搖滾天團 NELL 去年11月時隔七年訪台，在 Legacy Taipei 舉行其亞洲巡演【NELL TAIWAN CONCERT 2024 ‘Our Eutopia’】台北站。當時他們就曾表示未來希望多與海外粉絲見面，現在時隔五個月即宣布再度訪台，並將首度帶著火氣音樂的演出企劃「Fire Live」造訪高雄，並邀請樂團「傻子與白痴」擔任開場嘉賓，再度為台灣觀眾呈現專場演出【Fire Live Presents : NELL w/ 傻子與白痴 Fool and Idiot】。\r\n自2000年出道以來，NELL由創作首腦金鍾完、貝斯手李正勳、吉他手李在景組成，2023年加入客座鼓手梁兮升，是韓國獨立搖滾的先驅樂團之一。從弘大的小型Live Club起家，憑藉其觸動人心的創作和出色的演出實力逐漸累積名氣，NELL出道僅兩年便受到韓國音樂教父「徐太志」的青睞，並隨後在其公司旗下以〈Stay〉、〈Thank you〉等歌曲奠定了韓國搖滾天團的地位。\r\n\r\n2001年，NELL以〈行走記憶的時間（Time Walking on Memories）〉再度爆紅，演唱會規模逐漸擴大，至今在韓國已多次在萬人場地舉行演唱會。其獨特的搖滾樂風及敘事風格，也使得NELL成為眾多韓國音樂人景仰的對象，包括NewJeans、BLACKPINK成員ROSÉ，以及即將來台開唱的泰妍都曾公開翻唱他們的歌曲。G-DRAGON、BTS成員RM等知名歌手也與他們合作，並參與彼此的作品。\r\nFire Live Presents: NELL w/傻子與白痴 Fool and Idiot\r\n\r\n\r\n\r\n韓國搖滾天團 NELL 去年11月時隔七年訪台，在 Legacy Taipei 舉行其亞洲巡演【NELL TAIWAN CONCERT 2024 ‘Our Eutopia’】台北站。當時他們就曾表示未來希望多與海外粉絲見面，現在時隔五個月即宣布再度訪台，並將首度帶著火氣音樂的演出企劃「Fire Live」造訪高雄，並邀請樂團「傻子與白痴」擔任開場嘉賓，再度為台灣觀眾呈現專場演出【Fire Live Presents : NELL w/ 傻子與白痴 Fool and Idiot】。\r\n\r\n\r\n\r\n自2000年出道以來，NELL由創作首腦金鍾完、貝斯手李正勳、吉他手李在景組成，2023年加入客座鼓手梁兮升，是韓國獨立搖滾的先驅樂團之一。從弘大的小型Live Club起家，憑藉其觸動人心的創作和出色的演出實力逐漸累積名氣，NELL出道僅兩年便受到韓國音樂教父「徐太志」的青睞，並隨後在其公司旗下以〈Stay〉、〈Thank you〉等歌曲奠定了韓國搖滾天團的地位。\r\n\r\n2001年，NELL以〈行走記憶的時間（Time Walking on Memories）〉再度爆紅，演唱會規模逐漸擴大，至今在韓國已多次在萬人場地舉行演唱會。其獨特的搖滾樂風及敘事風格，也使得NELL成為眾多韓國音樂人景仰的對象，包括NewJeans、BLACKPINK成員ROSÉ，以及即將來台開唱的泰妍都曾公開翻唱他們的歌曲。G-DRAGON、BTS成員RM等知名歌手也與他們合作，並參與彼此的作品。\r\n\r\n\r\n\r\n2024年，NELL時隔多年再度訪台，並在【NELL TAIWAN CONCERT 2024 ‘Our Eutopia’】台北站的演出中，除了讓期待已久的台灣樂迷感動外，也以精湛的演出獲得音樂人及業界人士的盛讚，紛紛表示「這是我今年看過最精彩的演出」、「從音樂到聲光效果，NELL的演出高度讓我大開眼界」。如今，NELL超高速再訪台灣，並選定高雄舉辦專場演出，期望未來能與更多海外觀眾見面。\r\n\r\n此次NELL專場演出將由樂團「傻子與白痴」擔任開場嘉賓，NELL在聆聽他們的作品後，親自發出邀請，也令人期待未來NELL與台灣音樂人有更多合作的可能性。【Fire Live Presents : NELL w/ 傻子與白痴 Fool and Idiot】將於下週一中午12點開賣，同時推出限量VIP加購套組，提供觀眾近距離與樂團互動的機會，購票詳情請參閱主辦單位火氣音樂及Unknown Hasayyo! 的官方社群平台。', 'CHAU CHAU 悄悄通信', '高雄市鹽埕區17鄰真愛路1號', '2025-04-05 00:00:00', '2025-04-05 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '限量 VIP 加購套組+1300;一般預售票+1680', 'https://kktix.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Fire Live Presents: NELL w/傻子與白痴 Fool and Idiot', `description`='韓國搖滾天團 NELL 去年11月時隔七年訪台，在 Legacy Taipei 舉行其亞洲巡演【NELL TAIWAN CONCERT 2024 ‘Our Eutopia’】台北站。當時他們就曾表示未來希望多與海外粉絲見面，現在時隔五個月即宣布再度訪台，並將首度帶著火氣音樂的演出企劃「Fire Live」造訪高雄，並邀請樂團「傻子與白痴」擔任開場嘉賓，再度為台灣觀眾呈現專場演出【Fire Live Presents : NELL w/ 傻子與白痴 Fool and Idiot】。\r\n自2000年出道以來，NELL由創作首腦金鍾完、貝斯手李正勳、吉他手李在景組成，2023年加入客座鼓手梁兮升，是韓國獨立搖滾的先驅樂團之一。從弘大的小型Live Club起家，憑藉其觸動人心的創作和出色的演出實力逐漸累積名氣，NELL出道僅兩年便受到韓國音樂教父「徐太志」的青睞，並隨後在其公司旗下以〈Stay〉、〈Thank you〉等歌曲奠定了韓國搖滾天團的地位。\r\n\r\n2001年，NELL以〈行走記憶的時間（Time Walking on Memories）〉再度爆紅，演唱會規模逐漸擴大，至今在韓國已多次在萬人場地舉行演唱會。其獨特的搖滾樂風及敘事風格，也使得NELL成為眾多韓國音樂人景仰的對象，包括NewJeans、BLACKPINK成員ROSÉ，以及即將來台開唱的泰妍都曾公開翻唱他們的歌曲。G-DRAGON、BTS成員RM等知名歌手也與他們合作，並參與彼此的作品。\r\nFire Live Presents: NELL w/傻子與白痴 Fool and Idiot\r\n\r\n\r\n\r\n韓國搖滾天團 NELL 去年11月時隔七年訪台，在 Legacy Taipei 舉行其亞洲巡演【NELL TAIWAN CONCERT 2024 ‘Our Eutopia’】台北站。當時他們就曾表示未來希望多與海外粉絲見面，現在時隔五個月即宣布再度訪台，並將首度帶著火氣音樂的演出企劃「Fire Live」造訪高雄，並邀請樂團「傻子與白痴」擔任開場嘉賓，再度為台灣觀眾呈現專場演出【Fire Live Presents : NELL w/ 傻子與白痴 Fool and Idiot】。\r\n\r\n\r\n\r\n自2000年出道以來，NELL由創作首腦金鍾完、貝斯手李正勳、吉他手李在景組成，2023年加入客座鼓手梁兮升，是韓國獨立搖滾的先驅樂團之一。從弘大的小型Live Club起家，憑藉其觸動人心的創作和出色的演出實力逐漸累積名氣，NELL出道僅兩年便受到韓國音樂教父「徐太志」的青睞，並隨後在其公司旗下以〈Stay〉、〈Thank you〉等歌曲奠定了韓國搖滾天團的地位。\r\n\r\n2001年，NELL以〈行走記憶的時間（Time Walking on Memories）〉再度爆紅，演唱會規模逐漸擴大，至今在韓國已多次在萬人場地舉行演唱會。其獨特的搖滾樂風及敘事風格，也使得NELL成為眾多韓國音樂人景仰的對象，包括NewJeans、BLACKPINK成員ROSÉ，以及即將來台開唱的泰妍都曾公開翻唱他們的歌曲。G-DRAGON、BTS成員RM等知名歌手也與他們合作，並參與彼此的作品。\r\n\r\n\r\n\r\n2024年，NELL時隔多年再度訪台，並在【NELL TAIWAN CONCERT 2024 ‘Our Eutopia’】台北站的演出中，除了讓期待已久的台灣樂迷感動外，也以精湛的演出獲得音樂人及業界人士的盛讚，紛紛表示「這是我今年看過最精彩的演出」、「從音樂到聲光效果，NELL的演出高度讓我大開眼界」。如今，NELL超高速再訪台灣，並選定高雄舉辦專場演出，期望未來能與更多海外觀眾見面。\r\n\r\n此次NELL專場演出將由樂團「傻子與白痴」擔任開場嘉賓，NELL在聆聽他們的作品後，親自發出邀請，也令人期待未來NELL與台灣音樂人有更多合作的可能性。【Fire Live Presents : NELL w/ 傻子與白痴 Fool and Idiot】將於下週一中午12點開賣，同時推出限量VIP加購套組，提供觀眾近距離與樂團互動的機會，購票詳情請參閱主辦單位火氣音樂及Unknown Hasayyo! 的官方社群平台。', `organizer`='CHAU CHAU 悄悄通信', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-05 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='限量 VIP 加購套組+1300;一般預售票+1680', `source_url`='https://kktix.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289426b32419285b7093', '2025 FTISLAND LIVE ‘PULSE’ THE FINAL IN KAOHSIUNG', '與粉絲相約今年也要常見面 FTISLAND 宣布重返高流再開唱！​\r\n\r\n韓國人氣樂團 FTISLAND 即將於 4 月 12 日重返高雄流行音樂中心舉辦《2025 FTISLAND LIVE ‘PULSE’ THE FINAL IN KAOHSIUNG》，演唱會門票將於 3 月 15 日上午 11 點在 ibon 售票網站及全臺 7-11 ibon 機台開賣。\r\n\r\n演唱會票價為 TWD 5,880 / TWD 4,880 / TWD 3,880 / TWD 2,880，另推出限量 VIP 套票 TWD 6,580 （含價值 TWD 5,880 票券乙張、特區享優先入場資格、會前彩排福利、獨家小卡一組），凡於 3 月 24 日前購票者，還有機會在 3 月 29 日使用一元加購親筆簽名海報、會後歡送、親筆簽名拍立得等福利。', '希林國際有限公司', '高雄市鹽埕區17鄰真愛路1號', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '--+2880;--+3880;--+4880;--+5880', 'https://www.ibon.com.tw/default.aspx#gsc.tab=0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 FTISLAND LIVE ‘PULSE’ THE FINAL IN KAOHSIUNG', `description`='與粉絲相約今年也要常見面 FTISLAND 宣布重返高流再開唱！​\r\n\r\n韓國人氣樂團 FTISLAND 即將於 4 月 12 日重返高雄流行音樂中心舉辦《2025 FTISLAND LIVE ‘PULSE’ THE FINAL IN KAOHSIUNG》，演唱會門票將於 3 月 15 日上午 11 點在 ibon 售票網站及全臺 7-11 ibon 機台開賣。\r\n\r\n演唱會票價為 TWD 5,880 / TWD 4,880 / TWD 3,880 / TWD 2,880，另推出限量 VIP 套票 TWD 6,580 （含價值 TWD 5,880 票券乙張、特區享優先入場資格、會前彩排福利、獨家小卡一組），凡於 3 月 24 日前購票者，還有機會在 3 月 29 日使用一元加購親筆簽名海報、會後歡送、親筆簽名拍立得等福利。', `organizer`='希林國際有限公司', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='--+2880;--+3880;--+4880;--+5880', `source_url`='https://www.ibon.com.tw/default.aspx#gsc.tab=0', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289426b32419285b7094', 'Shino林曉培2025 START Tour高雄', 'Shino林曉培2025 START Tour高雄\r\n\r\n如果你問Shino林曉培為什麼那麼愛唱：\r\n26年前出道的她說：音樂一輩子，搖滾一輩子。\r\n\r\n現在的她說：音樂半輩子；還想安可半輩子！\r\n不同的舞台伴隨著她的成長，現場演出不斷的\r\n鞭策著愛音樂的她，甚至拯救了她！完整了她。\r\n……音樂永遠為她準備了出路。\r\n\r\n舞臺是她最溫暖的家；歌迷則是她感激的家人。\r\n壓傷的蘆葦，他不折斷。曾有的挫敗、艱難、懊悔、失去\r\n都讓她更堅強。\r\n\r\n2025的開始；她要勇敢回應生命的歷練；把握每一份祝福\r\n換來的演出。搖滾女王霸氣的說: 高雄 我來了！', '萊茯音樂', '高雄市鹽埕區17鄰真愛路1號', '2025-04-25 00:00:00', '2025-04-25 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '預售座票+1500;現場座票+1800', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Shino林曉培2025 START Tour高雄', `description`='Shino林曉培2025 START Tour高雄\r\n\r\n如果你問Shino林曉培為什麼那麼愛唱：\r\n26年前出道的她說：音樂一輩子，搖滾一輩子。\r\n\r\n現在的她說：音樂半輩子；還想安可半輩子！\r\n不同的舞台伴隨著她的成長，現場演出不斷的\r\n鞭策著愛音樂的她，甚至拯救了她！完整了她。\r\n……音樂永遠為她準備了出路。\r\n\r\n舞臺是她最溫暖的家；歌迷則是她感激的家人。\r\n壓傷的蘆葦，他不折斷。曾有的挫敗、艱難、懊悔、失去\r\n都讓她更堅強。\r\n\r\n2025的開始；她要勇敢回應生命的歷練；把握每一份祝福\r\n換來的演出。搖滾女王霸氣的說: 高雄 我來了！', `organizer`='萊茯音樂', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-04-25 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='預售座票+1500;現場座票+1800', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289426b32419285b7095', '喧嘩祭', '🔥喧嘩祭🔥——文化衝擊・明星大亂鬪！\r\n🎤 K-Roww鴉 x 柯蕭 x Ruka Banana 🎤\r\n當搖滾樂、饒舌、地下偶像三大風格正面衝突，究竟會摩擦出怎樣的火花？\r\n這是一場打破框架、文化衝擊的大亂鬪！\r\nK-Roww鴉——極道系搖滾樂來襲，以近乎不講理的強勢風格，將搖滾樂的魅力推至極限！\r\n柯蕭——街頭詩人無情開麥，犀利的唇槍舌劍劃破一切界線！\r\nRuka Banana——反差偶像甜美降臨，糖衣裹著刀鋒，讓你在旋律中淪陷！準備接招，今晚的香蕉電波會特別猛烈！\r\n🔥 硬派音樂 x 戰鬥美學 x 無法預測的現場化學反應 🔥', '高雄流行音樂中心', '高雄市鹽埕區17鄰真愛路1號', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '佛心預售票+650;現場黃牛票+1200', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='喧嘩祭', `description`='🔥喧嘩祭🔥——文化衝擊・明星大亂鬪！\r\n🎤 K-Roww鴉 x 柯蕭 x Ruka Banana 🎤\r\n當搖滾樂、饒舌、地下偶像三大風格正面衝突，究竟會摩擦出怎樣的火花？\r\n這是一場打破框架、文化衝擊的大亂鬪！\r\nK-Roww鴉——極道系搖滾樂來襲，以近乎不講理的強勢風格，將搖滾樂的魅力推至極限！\r\n柯蕭——街頭詩人無情開麥，犀利的唇槍舌劍劃破一切界線！\r\nRuka Banana——反差偶像甜美降臨，糖衣裹著刀鋒，讓你在旋律中淪陷！準備接招，今晚的香蕉電波會特別猛烈！\r\n🔥 硬派音樂 x 戰鬥美學 x 無法預測的現場化學反應 🔥', `organizer`='高雄流行音樂中心', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='佛心預售票+650;現場黃牛票+1200', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289526b32419285b7096', '一笑春溫彩墨茶器展', '地點\r\n台中市西屯區市政路567號B1F\r\n\r\n相關連結\r\nFacebook\r\n\r\n參展藝術家\r\n古心、葉文極、蔡宛書\r\n\r\n一笑春溫：彩墨與茶器的對話\r\n此次展覽邀請三位藝術創作家，以彩墨與茶器為媒材，在傳統與現代的交融中，展開一場關於自然、器物與心境的對話。「依然一笑作春溫」— 相逢一笑時仍然如春天般溫暖，藉由蘇軾筆下的詩意，也映照出三位作者間友情、生活與藝術交織的溫度。', '大美無言藝術空間', '臺中市西屯區', '2025-03-08 00:00:00', '2025-05-18 00:00:00', '西屯區（臺中市）=', 24.18308895, 120.6270131, '無資料', 'https://artemperor.tw/tidbits/17925', '[]') ON DUPLICATE KEY UPDATE `activity_name`='一笑春溫彩墨茶器展', `description`='地點\r\n台中市西屯區市政路567號B1F\r\n\r\n相關連結\r\nFacebook\r\n\r\n參展藝術家\r\n古心、葉文極、蔡宛書\r\n\r\n一笑春溫：彩墨與茶器的對話\r\n此次展覽邀請三位藝術創作家，以彩墨與茶器為媒材，在傳統與現代的交融中，展開一場關於自然、器物與心境的對話。「依然一笑作春溫」— 相逢一笑時仍然如春天般溫暖，藉由蘇軾筆下的詩意，也映照出三位作者間友情、生活與藝術交織的溫度。', `organizer`='大美無言藝術空間', `address`='臺中市西屯區', `start_date`='2025-03-08 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='西屯區（臺中市）=', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://artemperor.tw/tidbits/17925', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289526b32419285b7097', '【Fly Me to the Moon】女性藝術家聯展', '這場展覽的名稱 “Fly Me to the Moon” 來自經典爵士樂曲，而這首歌的靈魂正是那份輕盈、愜意與深情。承襲了這樣的氛圍，在作品與空間間流淌出柔和的旋律，讓藝術與觀者的心靈輕輕共振。', 'C Square Gallery', '臺中市西屯區', '2025-03-15 00:00:00', '2025-05-18 00:00:00', '西屯區（臺中市）=', 24.18308895, 120.6270131, '無資料', 'https://artemperor.tw/tidbits/17913', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【Fly Me to the Moon】女性藝術家聯展', `description`='這場展覽的名稱 “Fly Me to the Moon” 來自經典爵士樂曲，而這首歌的靈魂正是那份輕盈、愜意與深情。承襲了這樣的氛圍，在作品與空間間流淌出柔和的旋律，讓藝術與觀者的心靈輕輕共振。', `organizer`='C Square Gallery', `address`='臺中市西屯區', `start_date`='2025-03-15 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='西屯區（臺中市）=', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://artemperor.tw/tidbits/17913', `image_url`='[]';
