INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289526b32419285b7099', '114年5月週末FUN電影：櫻時(保護級；23分)', '奇幻的神鬼世界——台灣民俗題材動畫作品\r\n\r\n播出：櫻時(保護級；23分)\r\n內容：南台灣的午後身影，總有個孤單男孩阿太，獨自一人跟著他的虛擬朋友玩著捉迷藏。就在追進一間不知什麼原因燒毀的神祕黑暗舊廟後，開始被一群惡鬼猴子欺負。當阿太又逃到舊廟時，巷弄奇蹟般的時空倒轉，舊廟回復成華簷神壇的樣子，廟中的一位神祕男孩阿亮挺身而出保護了阿太。阿太不再孤獨，神明都從神壇活起來和他玩，廟前電影神明遊行讓阿太體驗不曾經歷的快樂。但在這時候，莫名的拿香惡鬼又齊聚廟前，阿太終於看到舊廟被燒毀的原因了...\r\n\r\n創作理念\r\n\r\n這部動畫取材至台灣文化中特別的民俗色彩與宗教信仰，整片採獨立製片創作。前置構思準備花費將近一年時間，大量取景與參考台南與高雄等南台灣中大家熟悉的巷道小徑、與各種廟宇古蹟與街頭陣頭慶典，來營造動畫影像中台灣人最熟悉的風景與氛圍。而在接下來的兩年製作期,完全由電腦動畫和數位工具製作，並在影像表現上盡量呈現有如傳統手繪美術風景與卡通動畫的特色。\r\n\r\n在故事上以魔幻的動畫表現，加上類似民間故事的架構，來描述一個小男孩在街道上一間廢棄的神祕廟宇中遭遇到的奇幻事件。故事裡充滿台灣民俗常見的宗教儀式、與台灣各種神明色彩的形象。並用一種比較童言童語接近卡通的可愛手法表現出來。音樂上以貼近台灣特有的民俗風味，用著民俗節奏與樂器如嗩吶，加上兒童合唱團純真又有神祕感的嗓音，來營造台灣原創具有現在草根味的動畫配樂。', '高雄市立圖書館總館', '高雄市湖內區3鄰保生路101號', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '高雄市立圖書館湖內分館', 22.8955499, 120.2225563, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年5月週末FUN電影：櫻時(保護級；23分)', `description`='奇幻的神鬼世界——台灣民俗題材動畫作品\r\n\r\n播出：櫻時(保護級；23分)\r\n內容：南台灣的午後身影，總有個孤單男孩阿太，獨自一人跟著他的虛擬朋友玩著捉迷藏。就在追進一間不知什麼原因燒毀的神祕黑暗舊廟後，開始被一群惡鬼猴子欺負。當阿太又逃到舊廟時，巷弄奇蹟般的時空倒轉，舊廟回復成華簷神壇的樣子，廟中的一位神祕男孩阿亮挺身而出保護了阿太。阿太不再孤獨，神明都從神壇活起來和他玩，廟前電影神明遊行讓阿太體驗不曾經歷的快樂。但在這時候，莫名的拿香惡鬼又齊聚廟前，阿太終於看到舊廟被燒毀的原因了...\r\n\r\n創作理念\r\n\r\n這部動畫取材至台灣文化中特別的民俗色彩與宗教信仰，整片採獨立製片創作。前置構思準備花費將近一年時間，大量取景與參考台南與高雄等南台灣中大家熟悉的巷道小徑、與各種廟宇古蹟與街頭陣頭慶典，來營造動畫影像中台灣人最熟悉的風景與氛圍。而在接下來的兩年製作期,完全由電腦動畫和數位工具製作，並在影像表現上盡量呈現有如傳統手繪美術風景與卡通動畫的特色。\r\n\r\n在故事上以魔幻的動畫表現，加上類似民間故事的架構，來描述一個小男孩在街道上一間廢棄的神祕廟宇中遭遇到的奇幻事件。故事裡充滿台灣民俗常見的宗教儀式、與台灣各種神明色彩的形象。並用一種比較童言童語接近卡通的可愛手法表現出來。音樂上以貼近台灣特有的民俗風味，用著民俗節奏與樂器如嗩吶，加上兒童合唱團純真又有神祕感的嗓音，來營造台灣原創具有現在草根味的動畫配樂。', `organizer`='高雄市立圖書館總館', `address`='高雄市湖內區3鄰保生路101號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='高雄市立圖書館湖內分館', `latitude`=22.8955499, `longitude`=120.2225563, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289526b32419285b709a', '【南投縣母語燎原-台語教音樂】蕭澤倫：台灣心民謠聊唱會', '南投，是多元文化交織的家園；台語，是我們熟悉的聲音，也是文化的根。透過活動，讓台語融入生活，成為每一天的陪伴與記憶。\r\n溫暖的母語，生活的日常\r\n邀請大家一起來，聽故事、看戲劇、說台語，讓母語的溫暖陪伴我們每一天！帶著家人朋友，共同參與這場母語文化盛宴！\r\n參加活動，領取參加禮，還有機會參加抽獎活動，贏取更多驚喜好禮！\r\n\r\n台語教音樂\r\n學唱台語歌、唸歌與戲曲，讓你用耳朵感受台語的美妙旋律，共有10場音樂教學活動，千萬別錯過！\r\n免費參加，名額有限。\r\n線上報名 https://forms.gle/P74YibTjsuAL7t2J6', '南投縣政府文化局', '南投縣南投市中興路669號', '2025-04-05 00:00:00', '2025-04-05 00:00:00', '南投縣政府文化局圖書館', 23.9027891, 120.691332, '無資料', 'https://www.facebook.com/profile.php?id=61573816426704', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【南投縣母語燎原-台語教音樂】蕭澤倫：台灣心民謠聊唱會', `description`='南投，是多元文化交織的家園；台語，是我們熟悉的聲音，也是文化的根。透過活動，讓台語融入生活，成為每一天的陪伴與記憶。\r\n溫暖的母語，生活的日常\r\n邀請大家一起來，聽故事、看戲劇、說台語，讓母語的溫暖陪伴我們每一天！帶著家人朋友，共同參與這場母語文化盛宴！\r\n參加活動，領取參加禮，還有機會參加抽獎活動，贏取更多驚喜好禮！\r\n\r\n台語教音樂\r\n學唱台語歌、唸歌與戲曲，讓你用耳朵感受台語的美妙旋律，共有10場音樂教學活動，千萬別錯過！\r\n免費參加，名額有限。\r\n線上報名 https://forms.gle/P74YibTjsuAL7t2J6', `organizer`='南投縣政府文化局', `address`='南投縣南投市中興路669號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-05 00:00:00', `location`='南投縣政府文化局圖書館', `latitude`=23.9027891, `longitude`=120.691332, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=61573816426704', `image_url`='[]';
