INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67db289626b32419285b70b2', '「山海交融墨韻紛飛」台馬名家聯展', '「山海交融墨韻紛飛」台馬名家聯展，聚集馬祖與台灣的書畫家共42幅作品，於3月20日起至4月10日南竿民俗文物館展出。\r\n\r\n馬名家聯展以「山海交融」為主軸，透過藝術家的作品，捕捉馬祖壯麗的自然景觀與獨特的人文風情，展現小島四季變換的美麗景致，觀眾近距離欣賞作品同時，感受山海交織的純粹之美。\r\n\r\n除畫作與攝影外，更邀請知名書法家張炳煌等，透過不同書體詮釋歷史詩詞與典故，寫出馬祖的軼事與風華，讓觀展者在墨韻飄香間，體驗書法藝術與地方文化的深度對話。此外，展期中參觀民眾將有機會與藝術家們當面深度交流。\r\n\r\n參與書畫家包括馬祖在地畫家陳合成、劉玉燕、曹賽娥、周碧玉，以及中華書道學會理事長楊旭堂，以及知名水墨畫家余振明、廖仁彬等，作品種類則涵蓋寫生、攝影、書法等多元表現形式。\r\n\r\n盼透過此次台馬名家聯展，深化與台灣本島間藝術交流，帶動馬祖藝文欣賞風氣，並為地區的藝術發展開創更多可能性。', '連江縣政府', '連江縣南竿鄉135號', '2025-03-20 00:00:00', '2025-04-10 00:00:00', '馬祖民俗文物館', 26.154321, 119.931128, '全票+40;優待票+20', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「山海交融墨韻紛飛」台馬名家聯展', `description`='「山海交融墨韻紛飛」台馬名家聯展，聚集馬祖與台灣的書畫家共42幅作品，於3月20日起至4月10日南竿民俗文物館展出。\r\n\r\n馬名家聯展以「山海交融」為主軸，透過藝術家的作品，捕捉馬祖壯麗的自然景觀與獨特的人文風情，展現小島四季變換的美麗景致，觀眾近距離欣賞作品同時，感受山海交織的純粹之美。\r\n\r\n除畫作與攝影外，更邀請知名書法家張炳煌等，透過不同書體詮釋歷史詩詞與典故，寫出馬祖的軼事與風華，讓觀展者在墨韻飄香間，體驗書法藝術與地方文化的深度對話。此外，展期中參觀民眾將有機會與藝術家們當面深度交流。\r\n\r\n參與書畫家包括馬祖在地畫家陳合成、劉玉燕、曹賽娥、周碧玉，以及中華書道學會理事長楊旭堂，以及知名水墨畫家余振明、廖仁彬等，作品種類則涵蓋寫生、攝影、書法等多元表現形式。\r\n\r\n盼透過此次台馬名家聯展，深化與台灣本島間藝術交流，帶動馬祖藝文欣賞風氣，並為地區的藝術發展開創更多可能性。', `organizer`='連江縣政府', `address`='連江縣南竿鄉135號', `start_date`='2025-03-20 00:00:00', `end_date`='2025-04-10 00:00:00', `location`='馬祖民俗文物館', `latitude`=26.154321, `longitude`=119.931128, `ticket_price`='全票+40;優待票+20', `source_url`='無資料', `image_url`='[]';
