INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7e3e26b32419285b70da', '「光影･靜思」靜思語暨李屏賓攝影展(免費參觀)', '主辦單位靜思書軒表示，為慶祝慈濟三節合一，靜思語出版36週年，本次展覽特別結合證嚴法師雋永深邃的靜思語與國際知名攝影大師李屏賓四十多年來於世界各地捕捉的瞬間精彩，無論是一片落葉、一大片樹林、不同的雲、或是不同的海，都是拍攝當下的心情紀錄，這些最質樸、未經處理的畫面，將透過影像與文字的交織，帶領觀眾進入一場心靈與視覺的沉澱之旅。\n\n主辦單位表示，靜思語自出版以來，已發行超過八百萬冊，翻譯成24種語文，跨越宗教、種族與語言的藩籬，啟發無數人的智慧與善念。展覽核心以「影像映照世界，智慧點亮心靈」為概念，搭配《愛，最好的祝福》與《善，最好的禮物》、《慈悲，時時歡喜，處處安身》三本靜思語中英對照系列書籍的溫暖氣息，讓每一幅畫面與每一句話語都成為人生體悟的見證。\n\n主辦單位期待透過這場結合人文與藝術的盛宴，讓更多人感受靜思語的智慧與攝影藝術的魅力，從中獲得心靈的寧靜與啟發，一同「說好話、做好事」，為世界帶來更多美好與祝福，歡迎各界人士蒞臨參觀。\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-04-12 00:00:00', '2025-06-03 00:00:00', '中央通廊', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50754', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「光影･靜思」靜思語暨李屏賓攝影展(免費參觀)', `description`='主辦單位靜思書軒表示，為慶祝慈濟三節合一，靜思語出版36週年，本次展覽特別結合證嚴法師雋永深邃的靜思語與國際知名攝影大師李屏賓四十多年來於世界各地捕捉的瞬間精彩，無論是一片落葉、一大片樹林、不同的雲、或是不同的海，都是拍攝當下的心情紀錄，這些最質樸、未經處理的畫面，將透過影像與文字的交織，帶領觀眾進入一場心靈與視覺的沉澱之旅。\n\n主辦單位表示，靜思語自出版以來，已發行超過八百萬冊，翻譯成24種語文，跨越宗教、種族與語言的藩籬，啟發無數人的智慧與善念。展覽核心以「影像映照世界，智慧點亮心靈」為概念，搭配《愛，最好的祝福》與《善，最好的禮物》、《慈悲，時時歡喜，處處安身》三本靜思語中英對照系列書籍的溫暖氣息，讓每一幅畫面與每一句話語都成為人生體悟的見證。\n\n主辦單位期待透過這場結合人文與藝術的盛宴，讓更多人感受靜思語的智慧與攝影藝術的魅力，從中獲得心靈的寧靜與啟發，一同「說好話、做好事」，為世界帶來更多美好與祝福，歡迎各界人士蒞臨參觀。\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-06-03 00:00:00', `location`='中央通廊', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50754', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7e4326b32419285b70dc', '2025 NTSO 講座音樂會系列 來自北歐', '3/21 12:00 VIP預購，3/26全面啟售\n\n講座早鳥1+1講座音樂會系列不限場次任選2張，買一送一。(4月10日截止)\n\n北歐雙響套票2場講座音樂會(芬蘭篇&丹麥篇)一次購買，享定價7折優惠。\n\n\n\n2025 NTSO 講座音樂會系列 來自北歐\n\n策劃、主講／吳毓庭\nPlanning, narrator: Yu-Ting Wu\n\n芬蘭篇\n2025/05/23(五)19:30 臺中國家歌劇院中劇院(臺中市西屯區惠來路二段101號)\n2025/05/23(Fri.)19:30 National Taichung Theater Playhouse\n\n小提琴／謝佩殷、劉芳佑\nViolin: Pei-Yin Hsieh, Fang-Yu Liu\n中提琴／蔡依倫\nViola: Yi-Lun Tsai\n大提琴／劉孟蓁\nCello: Meng-Jhen Liu\n\n【曲目】Program\n西貝流士：D小調弦樂四重奏《親密之聲》，作品56\nJ. Sibelius: String Quartet in D minor, Op. 56 "Voces Intimae"\n\n【節目長度參考】約90分(無中場休息)\n*以上演出內容或順序等若有異動，以實際演出為準。\n\n\n丹麥篇\n\n2025/06/15(日)14:30 臺中國家歌劇院中劇院(臺中市西屯區惠來路二段101號)\n2025/06/15(Sun.)14:30 National Taichung Theater Playhouse\n\n小提琴／張睿洲、鍾璟棛\nViolin: Ray-Chou Chang, Ching-Yu Chung\n中提琴／蕭惠珠\nViola: Hui-Chu Hsiao\n大提琴／陳廷瑋\nCello: Ting-Wei Chen\n\n【曲目】Program\n尼爾森：降E大調第三號弦樂四重奏，作品14\nC. Nielsen: String Quartet No. 3 in E-flat Major, Op. 14\n\n【節目長度參考】約90分(含無場休息)\n*以上演出內容或順序等若有異動，以實際演出為準。\n\n\n【票價】NT 300\n\n購票資訊：OPENTIX兩廳院文化生活　www.opentix.life\n臺中04-22595358\n售票地點：OPENTIX全臺售票處，全家、7-11及萊爾富超商機台\n\n指導單位：文化部\n主辦、演出單位：國立臺灣交響樂團\n購票請洽OPENTIX兩廳院文化生活\n各項優惠請點擊詳閱說明\n活動洽詢電話：國立臺灣交響樂團04-23391141(代表號)\n\nNTSO YouTube (超過800萬瀏覽次數)\nNTSO線上音樂廳\nNTSO《樂覽》雜誌\nNTSO照亮古典\nNTSO國立臺灣交響樂團LINE官方帳號\n更多國臺交精彩畫面及音樂會訊息，請造訪國臺交Facebook粉絲專頁\n\n \n\n \n\n更新日期2025.3.19\n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n ', '國立臺灣交響樂團', '407  臺中市西屯區惠來路二段101號', '2025-05-23 00:00:00', '2025-05-23 00:00:00', '臺中國家歌劇院中劇院National Taichung Theater Playhouse', 24.1626492, 120.6403028, '無資料', 'https://www.opentix.life/event/1900000397973274625', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 NTSO 講座音樂會系列 來自北歐', `description`='3/21 12:00 VIP預購，3/26全面啟售\n\n講座早鳥1+1講座音樂會系列不限場次任選2