INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7e5126b32419285b70e3', '與心對話--色彩心理與自我探索-郭蕙寧', ' \n\n\n	\n		\n			\n			 國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：色彩心理與自我探索-與心對話\n\n			授課教師: 郭蕙寧\n\n			適合對象：一般民眾\n			\n		\n		\n			\n			週次\n			\n			\n			日期\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			一\n			\n			\n			5/15\n			\n			\n			色彩概念、生活中的色彩探析\n			\n			\n			色彩基本概念、色彩歷史、色彩如何影響人們？生活中的色彩心理學。\n			\n		\n		\n			\n			二\n			\n			\n			5/22\n			\n			\n			喜歡/不喜歡的色彩與自我的關係\n			\n			\n			示範色彩分析、喜歡和不喜歡的色彩（匱乏與過多）、色彩特質/外放內收/深淺/時間長短、色彩用在企業logo中的象徵意義、探索自己的色彩經驗/代表意義\n			\n		\n		\n			\n			三\n			\n			\n			5/29\n			\n			\n			紅色系列/紅、暗紅色之色彩心理學\n			\n			\n			色彩積極想像、色彩代表物探索、色彩心理特質、性格與正負能量定義、行為需求、情結議題等探討\n			\n		\n		\n			\n			四\n			\n			\n			6/5\n			\n			\n			紅色系列/粉紅色之色彩心理學\n			\n		\n		\n			\n			五\n			\n			\n			6/12\n			\n			\n			橙色系列/橘、淡橘、橘紅之色彩心理學\n			\n		\n		\n			\n			六\n			\n			\n			6/19\n			\n			\n			黃色系列/黃、淡黃之色彩心理學\n			\n		\n		\n			\n			七\n			\n			\n			6/26\n			\n			\n			黃色系列/土黃、咖啡\n			\n		\n		\n			\n			八\n			\n			\n			7/3\n			\n			\n			綠色系列/綠、淡綠、深綠之色彩心理學\n			\n		\n		\n			\n			九\n			\n			\n			8/7\n			\n			\n			藍色系列/藍、天藍、深藍之色彩心理學\n			\n		\n		\n			\n			十\n			\n			\n			8/14\n			\n			\n			紫、淡紫、深紫之色彩心理學\n			\n		\n		\n			\n			十一\n			\n			\n			8/21\n			\n			\n			黑、白、灰、銀、金之色彩心理學\n			\n		\n		\n			\n			十二\n			\n			\n			8/28\n			\n			\n			色彩分析練習\n			\n			\n			透過一個人對色彩的喜好、厭惡，分析個人的性格、溝通模式、內在需求、潛在生命議題、並提供回饋與建議\n			\n		\n	\n\n\n註：1.本表所安排之課題及教學內容,將依據學員之學習狀況斟酌調整\n\n        2.停課日期：7/10-31( 老師因事請假 )\n\n \n\n \n\n ', '國立國父紀念館', '106  臺北市大安區信義路四段186巷8號', '2025-05-15 00:00:00', '2025-08-28 00:00:00', '自衡樓教室3', 25.02677012, 121.5434446, '1800', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=50973', '[]') ON DUPLICATE KEY UPDATE `activity_name`='與心對話--色彩心理與自我探索-郭蕙寧', `description`=' \n\n\n	\n		\n			\n			 國立國父紀念館第65期生活美學班課程大綱\n\n			課