INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7e5126b32419285b70e9', '水墨進階-蕭進發', '1\n\n      \n\n\n	\n		\n			\n			國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：水墨進階                          授課教師：蕭進發\n\n			適合對象：對水墨畫有興趣者\n			\n		\n		\n			\n			週次\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			一\n			\n			\n			樹木、石頭種類畫法練習\n			\n			\n			講解山水畫法中各式樹木、石頭技法示範\n			\n		\n		\n			\n			二\n			\n			\n			各式山形皴法練習\n			\n			\n			講解山水畫中各式山形及水墨濃淡的控制\n			\n		\n		\n			\n			三\n			\n			\n			瀑布、流泉、田野(梯田、稻田)畫法\n			\n			\n			畫理淺說學習暨瀑布、流泉、田野等基本畫法練習\n			\n		\n		\n			\n			四\n			\n			\n			鄉村房舍、現代高樓，表現畫法\n			\n			\n			畫理淺說學習暨房舍、高樓之基本表現畫法練習\n			\n		\n		\n			\n			五\n			\n			\n			點景、人物、鳥、畜的表現畫法\n			\n			\n			畫理淺說學習，暨景、物、鳥、畜的表現畫法\n			\n		\n		\n			\n			六\n			\n			\n			氣韻生動，瀑布畫法\n			\n			\n			傳模移寫，透過臨摹畫稿而瞭解畫法\n			\n		\n		\n			\n			七\n			\n			\n			氣韻生動，瀑布畫法\n			\n			\n			傳模移寫，透過臨摹畫稿而瞭解畫法\n			\n		\n		\n			\n			八\n			\n			\n			氣韻生動，雲霧畫法\n			\n			\n			傳模移寫，透過臨摹畫稿而瞭解畫法\n			\n		\n		\n			\n			九\n			\n			\n			氣韻生動，雲霧畫法\n			\n			\n			傳模移寫，透過臨摹畫稿而瞭解畫法\n			\n		\n		\n			\n			十\n			\n			\n			氣韻生動，山形畫法\n			\n			\n			傳模移寫，透過臨摹畫稿而瞭解畫法\n			\n		\n		\n			\n			十一\n			\n			\n			春天百花齊放背景搭配及構圖練習\n			\n			\n			現場教學示範，山水畫論述及特點\n			\n		\n		\n			\n			十二\n			\n			\n			夏天綠意盎然背景搭配及構圖練習\n			\n			\n			現場教學示範，山水畫論述及特點\n			\n		\n	\n\n\n註:本表所安排之課題及教學內容，將依據學員之學習狀況斟酌調整。\n\n \n\n \n\n \n\n ', '國立國父紀念館', '106  臺北市大安區信義路四段186巷8號', '2025-05-10 00:00:00', '2025-08-02 00:00:00', '東方科技教學大樓3樓教室6', 25.02677012, 121.5434446, '2600', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=50980', '[]') ON DUPLICATE KEY UPDATE `activity_name`='水墨進階-蕭進發', `description`='1\n\n      \n\n\n	\n		\n			\n			國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：水墨進階                          授課教師：蕭進發\n\n			適合對象：對水墨畫有興趣者\n			\n		\n		\n			\n			週次\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			一\n			\n		