INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7e5226b32419285b70ee', '炭筆素描-鄭志德', '國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：炭筆素描                                              授課教師：鄭志德\n\n			適合對象：具基礎素描者\n			\n		\n		\n			\n			週次\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			一\n			\n			\n			認識炭筆素描及教師示範\n			\n			\n			介紹炭筆畫材料與技法,教師示範完整靜物畫步驟,整期課程介紹與注意事項\n			\n		\n		\n			\n			二\n			\n			\n			學員正方體、圓柱、圓錐體練習\n			\n			\n			                                   老師示範,並講解如何精確掌握比例的構圖法,與明暗   色調的運用關係,學員實際操作練習,學員作品成果檢討\n			\n		\n		\n			\n			三\n			\n			\n			學員六角柱與圓球體練習\n			\n			\n			老師示範,並講解六角柱的點、線、面關係與圓球體光源於物體明暗漸層的表現,學員作品成果檢討\n			\n		\n		\n			\n			四\n			\n			\n			簡易蔬果與幾何體練習\n			\n			\n			加強幾何體透視觀念，與白色石膏與蔬果間調子的明暗差關係,學員作品成果檢討\n			\n		\n		\n			\n			五\n			\n			\n			教師示範金屬物與蔬果\n			\n			\n			強調金屬質感的呈現,重視明暗調性的差別,並安排畫面的均衡構圖,加強灰色調之呈現\n			\n		\n		\n			\n			六\n			\n			\n			學員金屬物與蔬果練習\n			\n			\n			以簡易蔬果為主,並講解如何使用金屬物特有的反射製造金屬感,學員實際操作練習,學員作品成果檢討\n			\n		\n		\n			\n			七\n			\n			\n			學員酒瓶複合式靜物練習\n			\n			\n			以酒瓶物為主,重視酒瓶與桌布的視點關係,強調對稱性與質感呈現,注意構圖的虛實關係,學員作品成果檢討\n			\n		\n		\n			\n			八\n			\n			\n			學員粗糙物複合式靜物練習\n			\n			\n			以粗糙物為主，強調炭筆素描獨特的按壓與手擦拭來呈現粗糙物之質感練習,強調描寫的虛實呈現,學員作品成果檢討\n			\n		\n		\n			\n			九\n			\n			\n			教師示範藤籃與蔬果畫法\n			\n			\n			老師示範,以手擦拭來強調竹藤的編織,重視結構,強調竹籃與蔬果間依存之關係,並強調光線的變化與空間性\n			\n		\n		\n			\n			十\n			\n			\n			學員簡易竹籃與蔬果練習\n			\n			\n			強調竹子編織的合理性與蔬果間之依存關係,強調光影的變化輕重,學員作品成果檢討\n			\n		\n		\n			\n			十一\n			\n			\n			瓷器與透明物質感表現法練習\n			\n			\n			講解構圖的重點,並強調如何透過構圖的安排巧妙的製造透明感,並區隔瓷器與透明玻璃間質感的差異性,學員作品成果檢討\n			\n		\n		\n			\n			十二\n			\n			\n			教師示範石膏像素描\n			\n			\n			講解如何量比例並精準的打稿,並強調結構的關聯性與動態的掌握,及輔助線的使用,重視石膏像灰色階的變化與虛實的描寫\n			\n		\n		\n			\n			十三\n			\n			\n			石膏像素描(一)\n			\n			\n			學員落實將比例精準的打稿,強調結構與輔助線,石膏大調子上色，並注意大面的關係\n			\n		\n		\n			\n			十四\n			\n			\n			石膏像素描(二)\n			\n			\n			強調骨骼結構與光影變化,重視石膏細膩調子的呈現,強調立體與空間的變化並加強細節的刻畫,學員作品成果檢討\n			\n		\n		\n			\n			十五\n			\n			\n			成果觀摩與投影片教學\n			\n			\n			以名作為主,強調素描的表現手法,透過作品賞析加強素描的觀念與視野,瞭解構圖與光線的微妙關係,學員作品成果檢討\n			\n		\n	\n\n\n     註：1.本課程內容可能會隨著學員上課情形而有所調整,以實際上課情況為準\n\n             \n\n ', '國立國父紀念館', '106  臺北市大安區信義路四段186巷7號3樓', '2025-05-08 00:00:00', '2025-08-14 00:00:00', '東方科技教學大樓3樓教室5', 25.02677012, 121.5434446, '3200', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=50986', '[]') ON DUPLICATE KEY UPDATE `activity_name`='炭筆素描-鄭志德', `description`='國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：炭筆素描                                              授課教師：鄭志德\n\n			適合對象：具基礎素描者\n			\n		\n		\n			\n			週次\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			一\n			\n			\n			認識炭筆素描及教師示範\n			\n			\n			介紹炭筆畫材料與技法,教師示範完整靜物畫步驟,整期課程介紹與注意事項\n			\n		\n		\n			\n			二\n			\n			\n			學員正方體、圓柱、圓錐體練習\n			\n			\n			                                   老師示範,並講解如何精確掌握比例的構圖法,與明暗   色調的運用關係,學員實際操作練習,學員作品成果檢討\n			\n		\n		\n			\n			三\n			\n			\n			學員六角柱與圓球體練習\n			\n			\n			老師示範,並講解六角柱的點、線、面關係與圓球體光源於物體明暗漸層的表現,學員作品成果檢討\n			\n		\n		\n			\n			四\n			\n			\n			簡易蔬果與幾何體練習\n			\n			\n			加強幾何體透視觀念，與白色石膏與蔬果間調子的明暗差關係,學員作品成果檢討\n			\n		\n		\n			\n			五\n			\n			\n			教師示範金屬物與蔬果\n			\n			\n			強調金屬質感的呈現,重視明暗調性的差別,並安排畫面的均衡構圖,加強灰色調之呈現\n			\n		\n		\n			\n			六\n			\n			\n			學員金屬物與蔬果練習\n			\n			\n			以簡易蔬果為主,並講解如何使用金屬物特有的反射製造金屬感,學員實際操作練習,學員作品成果檢討\n			\n		\n		\n			\n			七\n			\n			\n			學員酒瓶複合式靜物練習\n			\n			\n			以酒瓶物為主,重視酒瓶與桌布的視點關係,強調對稱性與質感呈現,注意構圖的虛實關係,學員作品成果檢討\n			\n		\n		\n			\n			八\n			\n			\n			學員粗糙物複合式靜物練習\n			\n			\n			以粗糙物為主，強調炭筆素描獨特的按壓與手擦拭來呈現粗糙物之質感練習,強調描寫的虛實呈現,學員作品成果檢討\n			\n		\n		\n			\n			九\n			\n			\n			教師示範藤籃與蔬果畫法\n			\n			\n			老師示範,以手擦拭來強調竹藤的編織,重視結構,強調竹籃與蔬果間依存之關係,並強調光線的變化與空間性\n			\n		\n		\n			\n			十\n			\n			\n			學員簡易竹籃與蔬果練習\n			\n			\n			強調竹子編織的合理性與蔬果間之依存關係,強調光影的變化輕重,學員作品成果檢討\n			\n		\n		\n			\n			十一\n			\n			\n			瓷器與透明物質感表現法練習\n			\n			\n			講解構圖的重點,並強調如何透過構圖的安排巧妙的製造透明感,並區隔瓷器與透明玻璃間質感的差異性,學員作品成果檢討\n			\n		\n		\n			\n			十二\n			\n			\n			教師示範石膏像素描\n			\n			\n			講解如何量比例並精準的打稿,並強調結構的關聯性與動態的掌握,及輔助