INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7e5226b32419285b70ef', '輕鬆快樂書法-龔朝陽', '                               \n\n	\n		\n			\n			國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：輕鬆快樂書法                        授課教師：龔朝陽\n\n			適合對象：對書法有興趣者，不拘程度\n			\n		\n		\n			\n			週次\n			\n			\n			日期\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			一\n			\n			\n			5/7\n			\n			\n			蘭亭序王羲之、趙孟頫字體行草示範\n			\n			\n			圓轉、方折、橫直劃、帶筆、接筆、撇捺\n			\n		\n		\n			\n			二\n			\n			\n			5/14\n			\n			\n			蘭亭序王羲之、趙孟頫字體行草示範\n			\n			\n			點、鉤、粗細、伸展、大小和外形，章法\n			\n		\n		\n			\n			三\n			\n			\n			5/21\n			\n			\n			蘭亭序王羲之、趙孟頫字體行草示範\n			\n			\n			學草先從章草入門〔索靖月儀帖〕\n			\n		\n		\n			\n			四\n			\n			\n			5/28\n			\n			\n			課堂上創作\n			\n			\n			認識書譜、全文釋文\n			\n		\n		\n			\n			五\n			\n			\n			6/4\n			\n			\n			蘭亭序王羲之、趙孟頫字體行草示範\n			\n			\n			認識草書、草書符號\n			\n		\n		\n			\n			六\n			\n			\n			6/11\n			\n			\n			蘭亭序王羲之、趙孟頫字體行草示範\n			\n			\n			學草書的基本順序\n			\n		\n		\n			\n			七\n			\n			\n			6/18\n			\n			\n			蘭亭序王羲之、趙孟頫字體行草示範\n			\n			\n			寫行草需要注意的向背\n			\n		\n		\n			\n			八\n			\n			\n			6/25\n			\n			\n			課堂上創作、書法作品賞析\n			\n			\n			作品展示、觀摩、講評\n			\n		\n		\n			\n			九\n			\n			\n			7/2\n			\n			\n			蘭亭序王羲之、趙孟頫字體行草示範\n			\n			\n			一幅行草書法創作配合比率\n			\n		\n		\n			\n			十\n			\n			\n			7/9\n			\n			\n			蘭亭序王羲之、趙孟頫字體行草示範\n			\n			\n			減到極致的35個草書你認幾個\n			\n		\n		\n			\n			十一\n			\n			\n			7/16\n			\n			\n			蘭亭序王羲之、趙孟頫字體行草示範\n			\n			\n			書法的骨、肉、筋、脈、皮、節\n			\n		\n		\n			\n			十二\n			\n			\n			7/23\n			\n			\n			蘭亭序王羲之、趙孟頫字體行草示範\n			\n			\n			平行四邊形構成美麗的字\n			\n		\n		\n			\n			十三\n			\n			\n			7/30\n			\n			\n			課堂上創作\n			\n			\n			書法結字三大原則、五種方法\n			\n		\n		\n			\n			十四\n			\n			\n			8/6\n			\n			\n			蘭亭序王羲之、趙孟頫字體行草示範\n			\n			\n			大書法家的小錯誤，你發現了嗎？\n			\n		\n		\n			\n			十五\n			\n			\n			8/13\n			\n			\n			蘭亭序王羲之、趙孟頫字體行草示範\n			\n			\n			謹記書法學習6條禁忌\n			\n		\n	\n\n    註：本表所安排之課題及教學