INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7e5326b32419285b70f3', '花鳥動物-洪瑞霞', '                \n\n\n	\n		\n			\n			國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：花鳥動物                   授課教師：洪瑞霞\n\n			適合對象：一般民眾\n			\n		\n		\n			\n			週次\n			\n			\n			日期\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			一\n			\n			\n			5/9\n			\n			\n			孔雀\n			\n			\n			繪其聲色、寓意吉祥太平、美麗的象徵\n			\n		\n		\n			\n			二\n			\n			\n			5/16\n			\n			\n			牡丹\n			\n			\n			雍容華貴、富麗堂皇，絢麗多彩花卉中上品\n			\n		\n		\n			\n			三\n			\n			\n			5/23\n			\n			\n			大利長壽\n			\n			\n			荔枝壽岱：象徵長壽，荔枝吉祥有大利之意\n			\n		\n		\n			\n			四\n			\n			\n			6/6\n			\n			\n			荷花\n			\n			\n			象徵清白堅貞、純潔信仰及出淤泥而\n\n			不染的高尚情操\n			\n		\n		\n			\n			五\n			\n			\n			6/13\n			\n			\n			松鶴圖\n			\n			\n			松齡鶴壽吉祥畫，可作為祝壽之畫\n			\n		\n		\n			\n			六\n			\n			\n			6/20\n			\n			\n			玫瑰\n			\n			\n			玫瑰有百變嬌顏，既美麗又神秘\n			\n		\n		\n			\n			七\n			\n			\n			6/27\n			\n			\n			芭蕉雄雞\n			\n			\n			紅了櫻桃，綠了芭蕉\n			\n		\n		\n			\n			八\n			\n			\n			7/4\n			\n			\n			紫藤\n			\n			\n			傳說紫藤是醉人的戀情與依依的思念\n			\n		\n		\n			\n			九\n			\n			\n			7/11\n			\n			\n			貓之畫法\n			\n			\n			包括背景、絨毛、上色及佈局\n			\n		\n		\n			\n			十\n			\n			\n			7/18\n			\n			\n			葡萄\n			\n			\n			成串葡萄有豐收之意與田園之風\n			\n		\n		\n			\n			十一\n			\n			\n			7/25\n			\n			\n			狗之畫法\n			\n			\n			狗的構圖及與畫貓的區別\n			\n		\n		\n			\n			十二\n			\n			\n			8/1\n			\n			\n			枇杷\n			\n			\n			枇杷稱為一樹金、滿樹黃澄澄\n\n			的感覺像黃金一樣\n			\n		\n	\n\n\n 註：本表所安排之課題及教學內容,將依據學員之學習狀況斟酌調整 。                   \n\n\n \n\n \n\n \n\n ', '國立國父紀念館', '106  臺北市大安區信義路四段186巷8號', '2025-05-09 00:00:00', '2025-08-01 00:00:00', '東方科技教學大樓3樓教室6', 25.02677012, 121.5434446, '2200', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=50991', '[]') ON DUPLICATE KEY UPDATE `activity_name`='花鳥動物-洪瑞霞', `description`='                \n\n\n	\n		\n			\n			國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：花