INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7e5326b32419285b70ff', '彩墨山水進階-廖賜福', ' \n                             \n\n\n	\n		\n			\n			國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：彩墨山水進階                      授課教師：廖賜福\n\n			適合對象 : 一般民眾\n			\n		\n		\n			\n			週次\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			一\n			\n			\n			山水畫概述\n			\n			\n			山水畫之特色\n			\n		\n		\n			\n			二\n			\n			\n			理論\n			\n			\n			關於「六法」之介紹\n			\n		\n		\n			\n			三\n			\n			\n			技法\n			\n			\n			中鋒、側鋒、順鋒、逆鋒支用筆\n			\n		\n		\n			\n			四\n			\n			\n			技法\n			\n			\n			聚鋒、散鋒之執筆法\n			\n		\n		\n			\n			五\n			\n			\n			技法\n			\n			\n			勾、皴、擦、點、染之表現手法\n			\n		\n		\n			\n			六\n			\n			\n			筆法\n			\n			\n			線條長短、粗細、繁簡、疏密、濃淡、虛實之變化運用\n			\n		\n		\n			\n			七\n			\n			\n			墨法\n			\n			\n			工筆、寫意之畫法\n			\n		\n		\n			\n			八\n			\n			\n			設色技法\n			\n			\n			山水畫之設色\n			\n		\n		\n			\n			九\n			\n			\n			雲的畫法\n			\n			\n			山中雲霧縹緲之畫法\n			\n		\n		\n			\n			十\n			\n			\n			雲海畫法\n			\n			\n			乾染、濕染並用,注重雲之動感\n			\n		\n		\n			\n			十一\n			\n			\n			山泉流水技法\n			\n			\n			江河、小溪之畫法\n			\n		\n		\n			\n			十二\n			\n			\n			瀑布技法\n			\n			\n			動感瀑布畫法(以抖筆表現)\n			\n		\n		\n			\n			十三\n			\n			\n			四季山水畫\n			\n			\n			春景、夏景、秋景、冬景山水畫\n			\n		\n		\n			\n			十四\n			\n			\n			     工筆山水畫\n			\n			\n			工筆畫黃山\n			\n		\n		\n			\n			十五\n			\n			\n			潑墨山水畫\n			\n			\n			潑墨畫黃山\n			\n		\n	\n\n\n                註：本表所安排之課題及教學內容,將依據學員之學習狀況斟酌調整。                                                                    \n\n\n\n\n ', '國立國父紀念館', '106  臺北市大安區信義路四段186巷8號', '2025-05-07 00:00:00', '2025-08-13 00:00:00', '東方科技教學大樓3樓教室6', 25.02677012, 121.5434446, '2200', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=51003', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彩墨山水進階-廖賜福', `description`=' \n                             \n\n\n	\n		\n			\n			國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：彩墨山