INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7e5426b32419285b710c', '彩墨山水花鳥-宋瑞和', '                        \n\n\n	\n		\n			\n			國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：彩墨山水花鳥                 授課教師：宋瑞和\n\n			適合對象：對彩墨有興趣者\n			\n		\n		\n			\n			週次\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			一\n			\n			\n			石之畫法(一)\n			\n			\n			以岩石為題，示範各種皴法，在皴、擦、點、染之中，掌握各種石頭之造型與質感應用山水之畫面結構，亦為日後山水畫筆法立下基礎\n			\n		\n		\n			\n			二\n			\n			\n			石之畫法(二)\n			\n			\n			以岩石為題，示範各種皴法，在皴、擦、點、染之中，掌握各種石頭之造型與質感應用山水之畫面結構，亦為日後山水畫筆法立下基礎\n			\n		\n		\n			\n			三\n			\n			\n			皴、擦、點、染之\n\n			綜合應用(一)\n			\n			\n			雲的表現為主\n			\n		\n		\n			\n			四\n			\n			\n			皴、擦、點、染之\n\n			綜合應用(二)\n			\n			\n			水的表現為主\n			\n		\n		\n			\n			五\n			\n			\n			紅梅\n			\n			\n			紅梅的畫法\n			\n		\n		\n			\n			六\n			\n			\n			柳鷺\n			\n			\n			白鷺的畫法，柳樹的寫法介紹\n			\n		\n		\n			\n			七\n			\n			\n			鷺鷥\n			\n			\n			夜鷺的畫法，池水的染法\n			\n		\n		\n			\n			八\n			\n			\n			公雞\n			\n			\n			墨公雞的畫法，配以石頭的介紹\n			\n		\n		\n			\n			九\n			\n			\n			母雞-小雞\n			\n			\n			母子雞的畫法，配以野草的介紹\n			\n		\n		\n			\n			十\n			\n			\n			鼠\n			\n			\n			松鼠與老鼠的寫法\n			\n		\n		\n			\n			十一\n			\n			\n			兔\n			\n			\n			家兔的畫法\n			\n		\n		\n			\n			十二\n			\n			\n			菜根香\n			\n			\n			各種蔬果之畫法介紹\n			\n		\n		\n			\n			十三\n			\n			\n			貓\n			\n			\n			家貓的結構與畫法介紹\n			\n		\n		\n			\n			十四\n			\n			\n			狗\n			\n			\n			北京狗的畫法\n			\n		\n		\n			\n			十五\n			\n			\n			牡丹花\n			\n			\n			沒骨牡丹花、葉之寫意與白頭翁之畫法\n			\n		\n	\n\n\n                註：本表所安排之課題及教學內容,將依據學員之學習狀況斟酌調整。\n                     \n                       \n\n\n\n\n ', '國立國父紀念館', '106  臺北市大安區信義路四段186巷8號', '2025-05-08 00:00:00', '2025-08-14 00:00:00', '東方科技教學大樓3樓教室5', 25.02677012, 121.5434446, '3200', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=51018', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彩墨山水花鳥-宋瑞和', `description`='              