INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7e5426b32419285b7111', '快樂玩皮手工皮件製作-何世棟', ' \n\n	\n		\n			\n			國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：快樂玩皮手工皮件製作                           授課教師：何世棟\n\n			適合對象：對手工皮件有興趣者，或想開發第二專長者\n			\n		\n		\n			\n			週次\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			ㄧ\n			\n			\n			認識手工皮件\n			\n			\n			皮革種類及工具使用說明\n\n			本期課程作品介紹\n			\n		\n		\n			\n			二\n			\n			\n			零錢包\n			\n			\n			包身黏貼及裁切\n\n			包身打孔縫合\n			\n		\n		\n			\n			三\n			\n			\n			編織拉鍊長夾\n			\n			\n			皮革表面處理及染色\n\n			內裡及內袋製作\n			\n		\n		\n			\n			四\n			\n			\n			編織拉鍊長夾\n			\n			\n			拉鍊黏貼及內袋處理\n\n			編織皮革切割及編織處理\n			\n		\n		\n			\n			五\n			\n			\n			編織拉鍊長夾\n			\n			\n			外皮皮革黏合處理\n\n			外皮和內裡結合縫製\n			\n		\n		\n			\n			六\n			\n			\n			斜背包\n			\n			\n			包身製作\n\n			內裡及內袋製作\n			\n		\n		\n			\n			七\n			\n			\n			斜背包\n			\n			\n			包口拉鍊及包底製作\n			\n		\n		\n			\n			八\n			\n			\n			斜背包\n			\n			\n			包身和內裡組合\n			\n		\n		\n			\n			九\n			\n			\n			托特包\n			\n			\n			拉鏈外袋及內袋製作\n			\n		\n		\n			\n			十\n			\n			\n			托特包\n			\n			\n			口金縫合及安裝\n			\n		\n		\n			\n			十一\n			\n			\n			托特包\n			\n			\n			包身製作\n\n			包底製作\n			\n		\n		\n			\n			十二\n			\n			\n			托特包\n			\n			\n			拉鏈及提帶組合\n\n			包身包底組合\n			\n		\n	\n\n\n註:1.課程及教學內容,將依據學員之學習狀況斟酌調整    \n\n 2.材料費約3,000元，工具費約1,800元\n\n3.停課:5/31\n\n      \n\n \n\n \n\n \n   \n\n\n \n\n \n\n \n\n \n\n ', '國立國父紀念館', '106  臺北市大安區信義路4段186巷7號3樓(東方工商)', '2025-05-10 00:00:00', '2025-08-23 00:00:00', '教室4', 25.02677012, 121.5434446, '2600', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=51023', '[]') ON DUPLICATE KEY UPDATE `activity_name`='快樂玩皮手工皮件製作-何世棟', `description`=' \n\n	\n		\n			\n			國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：快樂玩皮手工皮件製作                           授課教師：何世棟\n\n			適合對象：對手工皮件有興趣者，或想開發第二專長者\n			\n		\n		\n			\n			週次\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			ㄧ\n			