INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7e5426b32419285b7113', '樂活激力居家瑜珈-佘雪紅', '            \n\n\n	\n		\n			\n			國立國父紀念館第65期生活美學班課程綱要\n\n			課程名稱：樂活激力居家瑜伽     授課教師：佘雪紅(台灣逗齡閤家樂健康瑜伽協會創會理事長)\n\n			適合對象：年長者或硬梆梆族，又害怕受到運動傷害的人\n			\n		\n		\n			\n			週次\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			ㄧ\n			\n			\n			簡易椅子瑜伽\n			\n			\n			藉由椅子輕鬆學習認識自己的身體，達到身心安頓\n			\n		\n		\n			\n			二\n			\n			\n			桌椅瑜伽基礎暖身\n			\n			\n			學習身體七大關節的協調，預防骨質疏鬆\n			\n		\n		\n			\n			三\n			\n			\n			身心連結零距離\n			\n			\n			藉由肢體間的連結、運作、強化末稍的循環,透過巧妙教學達到身心和諧\n			\n		\n		\n			\n			四\n			\n			\n			腹式呼吸\n			\n			\n			藉由調息過程中深、沉、慢、緩學習放鬆達到身心靈合一\n			\n		\n		\n			\n			五\n			\n			\n			居家基本功法\n			\n			\n			人老腳先衰，從預防醫學、人體工學的專業知識與技巧，避免運動傷害，並激發肌肉力量\n			\n		\n		\n			\n			六\n			\n			\n			居家基本功法\n			\n			\n			骨盆腔的功法\n			\n		\n		\n			\n			七\n			\n			\n			居家基本功法\n			\n			\n			脊椎保健減緩上背沉重下背疼痛\n			\n		\n		\n			\n			八\n			\n			\n			居家基本功法\n			\n			\n			肩膀的功法，預防五十肩輕緩肩膀不適\n			\n		\n		\n			\n			九\n			\n			\n			輔助教材\n			\n			\n			藉由瑜伽帶的運作，輕鬆學瑜伽，達到肢體間的協調與和諧\n			\n		\n		\n			\n			十\n			\n			\n			輔助教材\n			\n			\n			藉由瑜伽帶的運作，完成牛面式\n			\n		\n		\n			\n			十一\n			\n			\n			輔助教材\n			\n			\n			藉由瑜伽帶的運作，完成鷲鳥式、簡易弓式\n			\n		\n		\n			\n			十二\n			\n			\n			簡易雙人居家瑜伽\n			\n			\n			藉由雙人瑜伽，將透過互助合作，借力使力，讓肌肉群延展的更為深層舒服，並增強平衡感\n			\n		\n		\n			\n			十三\n			\n			\n			簡易雙人居家瑜伽\n			\n			\n			藉由雙人瑜伽達到人、我連結的喜悅\n			\n		\n		\n			\n			十四\n			\n			\n			簡易雙人居家瑜伽\n			\n			\n			藉由肢體觸摸、按摩學會彼此交流、分享的合一\n			\n		\n		\n			\n			十五\n			\n			\n			總複習\n			\n			\n			身體像團隊需透過學習過程連結熟悉、和諧、平衡、融合達到和平、喜悅的實踐\n			\n		\n	\n\n\n備註:1.所有輔助教具由老師提供\n\n     2.上課請穿著寬鬆衣服                                                                           \n                                                                        \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n ', '國立國父紀念館', '106  臺北市大安區信義路4段186巷7號3樓', '2025-05-05 00:00:00', '2025-08-11 00:00:00', '教室5', 25.02677012, 121.5434446, '4700', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=51025', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樂活激力居家瑜珈-佘雪紅', `description`='            \n\n\n	\n		\n			\n			國立國父紀念館第65期生活美學班課程綱要\n\n			課程名稱：樂活激力居家瑜伽     授課教師：佘雪紅(台灣逗齡閤家樂健康瑜伽協會創會理事長)\n\n			適合對象：年長者或硬梆梆族，又害怕受到運動傷害的人\n			\n		\n		\n			\n			週次\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			ㄧ\n			\n			\n			簡易椅子瑜伽\n			\n			\n			藉由椅子輕鬆學習認識自己的身體，達到身心安頓\n			\n		\n		\n			\n			二\n			\n			\n			桌椅瑜伽基礎暖身\n			\n			\n			學習身體七大關節的協調，預防骨質疏鬆\n			\n		\n		\n			\n			三\n			\n			\n			身心連結零距離\n			\n			\n			藉由肢體間的連結、運作、強化末稍的循環,透過巧妙教學達到身心和諧\n			\n		\n		\n			\n			四\n			\n			\n			腹式呼吸\n			\n			\n			藉由調息過程中深、沉、慢、緩學習放鬆達到身心靈合一\n			\n		\n		\n			\n			五\n			\n			\n			居家基本功法\n			\n			\n			人老腳先衰，從預防醫學、人體工學的專業知識與技巧，避免運動傷害，並激發肌肉力量\n			\n		\n		\n			\n			六\n			\n			\n			居家基本功法\n			\n			\n			骨盆腔的功法\n			\n		\n		\n			\n			七\n			\n			\n			居家基本功法\n			\n			\n			脊椎保健減緩上背沉重下背疼痛\n			\n		\n		\n			\n			八\n			\n			\n			居家基本功法\n			\n			\n			肩膀的功法，預防五十肩輕緩肩膀不適\n			\n		\n		\n			\n			九\n			\n			\n			輔助教材\n			\n			\n			藉由瑜伽帶的運作，輕鬆學瑜伽，達到肢體間的協調與和諧\n			\n		\n		\n			\n			十\n			\n			\n			輔助教材\n			\n			\n			藉由瑜伽帶的運作，完成牛面式\n			\n		\n		\n			\n			十一\n			\n			\n			輔助教材\n			\n			\n			藉由瑜伽帶的運作，完成鷲鳥式、簡易弓式\n			\n		\n		\n			\n			十二\n			\n			\n			簡易雙人居家瑜伽\n			\n			\n			藉由雙人瑜伽，將透過互助合作，借力使力，讓肌肉群延展的更為深層舒服，並增強平衡感\n			\n		\n		\n			\n			十三\n			\n			\n			簡易雙人居家瑜伽\n			\n			\n			藉由雙人瑜伽達到人、我連結的喜悅\n			\n		\n		\n			\n			十四\n			\n			\n			簡易雙人居家瑜伽\n			\n			\n			藉由肢體觸摸、按摩學會彼此交流、分享的合一\n			\n		\n		\n			\n			十五\n			\n			\n			總複習\n			\n			\n			身體像團隊需透過學習過程連結熟悉、和諧、平衡、融合達到和平、喜悅的實踐\n			\n		\n	\n\n\n備註:1.所有輔助教具由老師提供\n\n     2.上課請穿著寬鬆衣服                                                                           \n                                                                        \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n ', `organizer`='國立國父紀念館', `address`='106  臺北市大安區信義路4段186巷7