INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7e5526b32419285b711b', '古典音樂欣賞-詹明棧', ' \n\n \n\n\n\n              \n\n	\n		\n			\n			國立國父紀念館第65期生活美學班課程大綱\n\n			課程名稱：古典音樂欣賞        授課教師：詹明棧              適合對象:\n			\n		\n		\n			\n			週次\n			\n			\n			日期\n			\n			\n			單元名稱\n			\n			\n			內容摘要\n			\n		\n		\n			\n			一\n			\n			\n			5/6\n			\n			\n			古典音樂的發展簡史\n			\n			\n			中世紀、文藝復興、巴洛克、古典、浪漫、現代\n			\n		\n		\n			\n			二\n			\n			\n			5/13\n			\n			\n			古典音樂體裁的四大類型\n			\n			\n			管弦樂、室內樂、獨奏樂、聲樂 \n			\n		\n		\n			\n			三\n			\n			\n			5/20\n			\n			\n			著名管弦樂曲選輯—\n\n			         交響曲(之一)\n			\n			\n			貝多芬第六號交響曲\n\n			布拉姆斯第一號交響曲\n			\n		\n		\n			\n			四\n			\n			\n			5/27\n			\n			\n			著名管弦樂曲選輯—\n\n			         交響曲(之二)\n			\n			\n			舒伯特「未完成」交響曲\n\n			德弗札克第九號交響曲\n			\n		\n		\n			\n			五\n			\n			\n			6/3\n			\n			\n			著名管弦樂曲選輯—\n\n			         協奏篇(之一)\n			\n			\n			貝多芬第三號鋼琴協奏曲\n\n			葛利格a小調鋼琴協奏曲\n			\n		\n		\n			\n			六\n			\n			\n			6/10\n			\n			\n			著名管弦樂曲選輯—\n\n			         協奏曲(之二)\n			\n			\n			布拉姆斯第一號鋼琴協奏曲\n\n			布拉姆斯小提琴協奏曲\n			\n		\n		\n			\n			七\n			\n			\n			6/17\n			\n			\n			著名管弦樂曲選輯—\n\n			         音樂會序曲篇\n			\n			\n			孟德爾頌：仲夏夜之夢序曲及婚禮進行曲、\n\n			柴可夫斯基：羅密歐與茱麗葉幻\n\n			          想序曲\n			\n		\n		\n			\n			八\n			\n			\n			6/24\n			\n			\n			著名管弦樂曲選輯—\n\n			         歌劇序曲篇\n			\n			\n			羅西尼：塞維里亞理髮師序曲、威廉泰爾序曲等\n			\n		\n		\n			\n			九\n			\n			\n			7/1\n			\n			\n			著名管弦樂曲選輯—\n\n			         歌劇序曲篇\n			\n			\n			威爾第：命運之力序曲、\n\n			華格納：唐懷瑟序曲、\n\n			小約翰：蝙蝠序曲\n			\n		\n		\n			\n			十\n			\n			\n			7/8\n			\n			\n			著名管弦樂曲選輯—\n\n			         交響詩\n			\n			\n			史麥塔納：我的祖國\n\n			德布希：牧神的午後\n			\n		\n		\n			\n			十一\n			\n			\n			7/15\n			\n			\n			著名管弦樂曲選輯—\n\n			         交響組曲\n			\n			\n			林姆斯基‧高沙可夫：\n\n			      天方夜譚組曲、\n\n			柴可夫斯基：胡桃鉗組曲\n			\n		\n		\n			\n			十二\n			\n			\n			7/22\n			\n			\n			著名管弦樂曲選輯—\n\n			         幻想曲與狂想曲\n			\n			\n			林姆斯基‧