INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7eb726b32419285b7125', '楠西區圖書館：3月主題書展「性別平等」', '不同個體間因文化的不同而時有衝突，因此，個體間應相互尊重、接納、理解、合作與包容，以消弭偏見呼籲弭平性別刻板印象讓我們意識到問題的存在。來楠西圖書館九月舉辦《性別平等》能夠建立正確性平觀念', '臺南市楠西區圖書館', '臺南市楠西區中正路309號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺南市楠西區圖書館', 23.17885854, 120.5170304, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='楠西區圖書館：3月主題書展「性別平等」', `description`='不同個體間因文化的不同而時有衝突，因此，個體間應相互尊重、接納、理解、合作與包容，以消弭偏見呼籲弭平性別刻板印象讓我們意識到問題的存在。來楠西圖書館九月舉辦《性別平等》能夠建立正確性平觀念', `organizer`='臺南市楠西區圖書館', `address`='臺南市楠西區中正路309號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市楠西區圖書館', `latitude`=23.17885854, `longitude`=120.5170304, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7eb926b32419285b7126', '夢想成真魔術劇團-親子魔幻秀', '結合魔術表演、歡樂小丑及氣球藝術，打造充滿歡樂及互動性強的親子節目!\r\n\r\n內容豐富多彩，包含大型魔術及逗趣的互動魔術秀、歡樂小丑要帶領大家來到他有趣的世界與眾不同的氣球藝術饗宴，從卡通人物到美味佳餚打造無限驚喜與歡笑，是您不可錯過的精彩盛宴!', '夢想成真魔術劇團', '桃園市桃園區中正路1188號', '2025-04-05 00:00:00', '2025-04-05 00:00:00', '桃園展演中心', 25.00040024, 121.2996612, '票價+500;票價+600;票價+700;票價+800;票價+900;票價+1,000', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='夢想成真魔術劇團-親子魔幻秀', `description`='結合魔術表演、歡樂小丑及氣球藝術，打造充滿歡樂及互動性強的親子節目!\r\n\r\n內容豐富多彩，包含大型魔術及逗趣的互動魔術秀、歡樂小丑要帶領大家來到他有趣的世界與眾不同的氣球藝術饗宴，從卡通人物到美味佳餚打造無限驚喜與歡笑，是您不可錯過的精彩盛宴!', `organizer`='夢想成真魔術劇團', `address`='桃園市桃園區中正路1188號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-05 00:00:00', `location`='桃園展演中心', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='票價+500;票價+600;票價+700;票價+800;票價+900;票價+1,000', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7eb926b32419285b7127', '日本飛行船劇團-小飛俠彼得潘 (2場)', '所有的孩子都知道一個叫做「夢幻島」的地方（Neverland），大家可以在睡夢中到那兒玩耍。島上有一個叫做彼得潘的男孩，他不但會飛，而且永遠不會長大。他是孩子們心目中的英雄，也是夢幻島上迷途的孩子們最可靠的首領。為了找尋新的故事，他和小精靈來到另一個世界，卻不小心被溫蒂及她的兩個弟弟發現……。', '童歡藝術有限公司', '桃園市桃園區中正路1188號', '2025-04-13 00:00:00', '2025-04-13 00:00:00', '桃園展演中心', 25.00040024, 121.2996612, '票價+400;票價+600;票價+800;票價+1000;票價+1200;票價+1500', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='日本飛行船劇團-小飛俠彼得潘 (2場)', `description`='所有的孩子都知道一個叫做「夢幻島」的地方（Neverland），大家可以在睡夢中到那兒玩耍。島上有一個叫做彼得潘的男孩，他不但會飛，而且永遠不會長大。他是孩子們心目中的英雄，也是夢幻島上迷途的孩子們最可靠的首領。為了找尋新的故事，他和小精靈來到另一個世界，卻不小心被溫蒂及她的兩個弟弟發現……。', `organizer`='童歡藝術有限公司', `address`='桃園市桃園區中正路1188號', `start_date`='2025-04-13 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='桃園展演中心', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='票價+400;票價+600;票價+800;票價+1000;票價+1200;票價+1500', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7eb926b32419285b7128', 'Yamaha山谷兒童音樂嘉年華會', 'Yamaha音樂教室學生成果展演', '桃園市私立惠育音樂短期補習班', '桃園市桃園區中正路1188號', '2025-05-18 00:00:00', '2025-05-18 00:00:00', '桃園展演中心', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Yamaha山谷兒童音樂嘉年華會', `description`='Yamaha音樂教室學生成果展演', `organizer`='桃園市私立惠育音樂短期補習班', `address`='桃園市桃園區中正路1188號', `start_date`='2025-05-18 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='桃園展演中心', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ec426b32419285b7129', '「穿山而過 Passing Through」戶外園區展', '「穿山而過(Passing Through)」以各異媒材的筆觸和線條勾勒出一幅幅與地景共生的樣態，並輻射出於作品內外、彼此之間因應間隙而生的碎散空間。通過充滿穿透性，富含份量感的「空」，以素描與寫生的姿態描繪人與自然之間的關係。\r\n沿山而行，穿山而過。\r\n「穿山」除了講述作品如何與自然相互依存，藉由其形貌與美術館周遭的地景對焦，也想像一種同寫生一般，描摹眼前所見景物的姿態。好似一邊拿著寫生簿，一邊觀察，一邊持續地走。強調如此移動不止的狀態，在三鶯新生地這樣處於城市邊緣與自然的交界地帶，或是在九件風格各異的作品之間，沿著邊線游移，挪步之間以身作筆。於是人與作品乃至山河的身體，得以形成外廓，有了素描般奔流洗鍊的肌理，便開始有機地起伏，通透地，有了呼吸。\r\n在與周遭景觀以輪廓對話的同時，「穿山而過」也思考作品如何穿梭於空間、建立空間，最終成為空間本身——一個足夠輕盈的身體得以自由穿梭的空間；一個流動不居而逐漸滲透出形體的空間。像河水，也像風，奔著遠方的白沫，滾著渴慕向著更深處流。雕塑的不動如河中石群，蔓生群山；你我則像河水，像風，在呼吸間沖刷而過。', '新北市美術館', '新北市鶯歌區館前路300號', '2025-01-18 00:00:00', '2025-03-30 00:00:00', '新北市美術館', 24.9566258, 121.3466269, '無資料', 'https://ntcart.museum/exhibition/H2412001', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「穿山而過 Passing Through」戶外園區展', `description`='「穿山而過(Passing Through)」以各異媒材的筆觸和線條勾勒出一幅幅與地景共生的樣態，並輻射出於作品內外、彼此之間因應間隙而生的碎散空間。通過充滿穿透性，富含份量感的「空」，以素描與寫生的姿態描繪人與自然之間的關係。\r\n沿山而行，穿山而過。\r\n「穿山」除了講述作品如何與自然相互依存，藉由其形貌與美術館周遭的地景對焦，也想像一種同寫生一般，描摹眼前所見景物的姿態。好似一邊拿著寫生簿，一邊觀察，一邊持續地走。強調如此移動不止的狀態，在三鶯新生地這樣處於城市邊緣與自然的交界地帶，或是在九件風格各異的作品之間，沿著邊線游移，挪步之間以身作筆。於是人與作品乃至山河的身體，得以形成外廓，有了素描般奔流洗鍊的肌理，便開始有機地起伏，通透地，有了呼吸。\r\n在與周遭景觀以輪廓對話的同時，「穿山而過」也思考作品如何穿梭於空間、建立空間，最終成為空間本身——一個足夠輕盈的身體得以自由穿梭的空間；一個流動不居而逐漸滲透出形體的空間。像河水，也像風，奔著遠方的白沫，滾著渴慕向著更深處流。雕塑的不動如河中石群，蔓生群山；你我則像河水，像風，在呼吸間沖刷而過。', `organizer`='新北市美術館', `address`='新北市鶯歌區館前路300號', `start_date`='2025-01-18 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='新北市美術館', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='https://ntcart.museum/exhibition/H2412001', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ec726b32419285b712a', '新化區圖書館:114年3月份-主題書展-性平教育', '新化區圖書館:114年3月份-主題書展-性平教育', '臺南市新化區圖書館', '臺南市新化區中山路132號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺南市新化區圖書館', 23.03394545, 120.3357964, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新化區圖書館:114年3月份-主題書展-性平教育', `description`='新化區圖書館:114年3月份-主題書展-性平教育', `organizer`='臺南市新化區圖書館', `address`='臺南市新化區中山路132號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市新化區圖書館', `latitude`=23.03394545, `longitude`=120.3357964, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ecb26b32419285b712b', '蕭壠兒童圖書館-3月主題書展-五彩繽紛的植物', '台灣的植物有很多種，也因為有這些與眾不同的植物，我們才有美麗的地球，這些隨處可見的植物，常常會忽略它們的美麗身影，因此藉由各種的生態繪本，來了解這些植物如何生長，形成萬紫千紅的美麗世界。', '蕭壠兒童圖書館', '臺南市佳里區六安130號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺南市蕭壠文化園區', 23.1669941, 120.178593, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蕭壠兒童圖書館-3月主題書展-五彩繽紛的植物', `description`='台灣的植物有很多種，也因為有這些與眾不同的植物，我們才有美麗的地球，這些隨處可見的植物，常常會忽略它們的美麗身影，因此藉由各種的生態繪本，來了解這些植物如何生長，形成萬紫千紅的美麗世界。', `organizer`='蕭壠兒童圖書館', `address`='臺南市佳里區六安130號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市蕭壠文化園區', `latitude`=23.1669941, `longitude`=120.178593, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ecb26b32419285b712c', '臺南市東區裕文圖書館- 114年3月 主題書展 - 自煮食光', '每月主題書展，提供讀者快速選擇主題相關書籍，並借閱。\r\n自煮食光-- 不管是因為健康還是因為衛生的關係，現在很多人都會選擇自己烹煮三餐。\r\n但煮著煮著，也會沒有想法要煮什麼，沒關係，現在來裕文圖書館給你想法，讓你的餐桌上出現新菜色吧! Let''s go!\r\n', '臺南市東區裕文圖書館', '臺南市東區裕信路237號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺南市東區裕文圖書館', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市東區裕文圖書館- 114年3月 主題書展 - 自煮食光', `description`='每月主題書展，提供讀者快速選擇主題相關書籍，並借閱。\r\n自煮食光-- 不管是因為健康還是因為衛生的關係，現在很多人都會選擇自己烹煮三餐。\r\n但煮著煮著，也會沒有想法要煮什麼，沒關係，現在來裕文圖書館給你想法，讓你的餐桌上出現新菜色吧! Let''s go!\r\n', `organizer`='臺南市東區裕文圖書館', `address`='臺南市東區裕信路237號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市東區裕文圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
