INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7eda26b32419285b712e', '【2025台文系列講座】 Thiaⁿ kò͘-sū台語繪本說故事《神奇漢藥房》', '高雄文學館自2020年開始與在地台語推廣社團「打狗台語文促進協會」合作，結合在地台語社團活力，帶動高雄在地台語文學之推廣以及母語學習。\r\n\r\n【做夥聽故事──Thiaⁿ kò͘-sū台語繪本說故事】\r\n以孩童、親子及家庭為對象，舉辦三場說故事活動，邀請作者本人以台語朗讀說故事。\r\n\r\n第一場\r\n時間｜4/19(六)15:00-16:00\r\n講師｜陳芊蓉\r\n讀本｜《神奇漢藥房》（2024，蔚藍文化）\r\n\r\n', '高雄市立圖書館總館', '高雄市前金區24鄰民生二路39號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '高雄市立圖書館高雄文學館', 22.625524, 120.298017, '無資料', 'https://www.facebook.com/ksliterary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025台文系列講座】 Thiaⁿ kò͘-sū台語繪本說故事《神奇漢藥房》', `description`='高雄文學館自2020年開始與在地台語推廣社團「打狗台語文促進協會」合作，結合在地台語社團活力，帶動高雄在地台語文學之推廣以及母語學習。\r\n\r\n【做夥聽故事──Thiaⁿ kò͘-sū台語繪本說故事】\r\n以孩童、親子及家庭為對象，舉辦三場說故事活動，邀請作者本人以台語朗讀說故事。\r\n\r\n第一場\r\n時間｜4/19(六)15:00-16:00\r\n講師｜陳芊蓉\r\n讀本｜《神奇漢藥房》（2024，蔚藍文化）\r\n\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市前金區24鄰民生二路39號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='高雄市立圖書館高雄文學館', `latitude`=22.625524, `longitude`=120.298017, `ticket_price`='無資料', `source_url`='https://www.facebook.com/ksliterary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7edc26b32419285b712f', '阿姆个話～共下打嘴鼓(一)、(二)', '客語說繪本故事的形式，針對樂齡族介紹一本有趣的繪本書，以說故事的形式進行，為協助視力較不佳的樂齡者，並使用投影機，介紹繪本內容。', '高雄市立圖書館總館', '高雄市六龜區', '2025-03-14 00:00:00', '2025-03-21 00:00:00', '六龜區（高雄市）=', 23.01195426, 120.6585635, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='阿姆个話～共下打嘴鼓(一)、(二)', `description`='客語說繪本故事的形式，針對樂齡族介紹一本有趣的繪本書，以說故事的形式進行，為協助視力較不佳的樂齡者，並使用投影機，介紹繪本內容。', `organizer`='高雄市立圖書館總館', `address`='高雄市六龜區', `start_date`='2025-03-14 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='六龜區（高雄市）=', `latitude`=23.01195426, `longitude`=120.6585635, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7edc26b32419285b7130', '仁德區圖書館-3月主題書展:她的故事與我們的未來-性平女力書展', '透過呈現性別角色的多樣性，挑戰社會對於固有性別期望的刻板印象，期望啟發讀者對於性別角色的反思，對於性別抱持更加開放與尊重的觀念，並促進社會的性別平等與包容。本活動約有50冊成人與兒童繪本書籍。\r\n', '臺南市仁德區圖書館', '臺南市仁德區正義一街39號2樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺南市仁德區圖書館', 22.94130931, 120.2418788, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='仁德區圖書館-3月主題書展:她的故事與我們的未來-性平女力書展', `description`='透過呈現性別角色的多樣性，挑戰社會對於固有性別期望的刻板印象，期望啟發讀者對於性別角色的反思，對於性別抱持更加開放與尊重的觀念，並促進社會的性別平等與包容。本活動約有50冊成人與兒童繪本書籍。\r\n', `organizer`='臺南市仁德區圖書館', `address`='臺南市仁德區正義一街39號2樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市仁德區圖書館', `latitude`=22.94130931, `longitude`=120.2418788, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7edd26b32419285b7131', '【新北市立圖書館蘆洲仁愛智慧圖書館】3月閱讀書籤', '3月聯合書展:玩美\r\n簡介:\r\n女人的美是由內而外散發出來的，但內在的美也需要外在的美來一起襯托才能讓人眼前一亮，從各式各樣的保養教學書來使自己變得更加美麗，也才能更愛自己。\r\n---------------------------------------------\r\n3月書展:數學π對\r\n簡介:\r\n圓周率，這個看似簡單的數學常數，蘊藏著深奧的理論和廣泛的應用，無論幾何學、微積分，還是數據科學，都與它息息相關。誠邀您參加這場數學派對。讓我們一起走進數學的殿堂，感受數學之美，享受無窮知識帶來的樂趣和啟發。\r\n---------------------------------------------\r\n3月書展:草木情懷\r\n簡介:\r\n漫步在花園庭院中，五彩斑斕的花卉與翠綠的葉子交織成美麗的畫卷。蝴蝶與蜜蜂在花間翩翩起舞，微風輕拂，溫暖的氣息撲面而來。這些景象不僅讓人陶醉其中，更喚起內心對大自然的熱愛和珍惜。\r\n---------------------------------------------\r\n◎活動單位保有取消、變更之權利，詳情請依現場為主。\r\n◎免費入場，無需事先報名，禁止飲食  \r\n ', '新北市立圖書館總館', '新北市蘆洲區民權路143號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館蘆洲仁愛智慧圖書館', 25.08927173, 121.4712461, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館蘆洲仁愛智慧圖書館】3月閱讀書籤', `description`='3月聯合書展:玩美\r\n簡介:\r\n女人的美是由內而外散發出來的，但內在的美也需要外在的美來一起襯托才能讓人眼前一亮，從各式各樣的保養教學書來使自己變得更加美麗，也才能更愛自己。\r\n---------------------------------------------\r\n3月書展:數學π對\r\n簡介:\r\n圓周率，這個看似簡單的數學常數，蘊藏著深奧的理論和廣泛的應用，無論幾何學、微積分，還是數據科學，都與它息息相關。誠邀您參加這場數學派對。讓我們一起走進數學的殿堂，感受數學之美，享受無窮知識帶來的樂趣和啟發。\r\n---------------------------------------------\r\n3月書展:草木情懷\r\n簡介:\r\n漫步在花園庭院中，五彩斑斕的花卉與翠綠的葉子交織成美麗的畫卷。蝴蝶與蜜蜂在花間翩翩起舞，微風輕拂，溫暖的氣息撲面而來。這些景象不僅讓人陶醉其中，更喚起內心對大自然的熱愛和珍惜。\r\n---------------------------------------------\r\n◎活動單位保有取消、變更之權利，詳情請依現場為主。\r\n◎免費入場，無需事先報名，禁止飲食  \r\n ', `organizer`='新北市立圖書館總館', `address`='新北市蘆洲區民權路143號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館蘆洲仁愛智慧圖書館', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ee126b32419285b7132', '新市區圖書館:三月主題書展', '三月主題書展\r\n兒童：我也可以\r\n每個故事裡都有一個勇敢的主角，只要相信自己無論遇到什麼挑戰，都能勇往直前，只要有自信，就能在這片無限的創作領域中 找到屬於自己的天地！\r\n\r\n成人：DIY烘培大挑戰\r\n在一個溫暖的家庭廚房裡，陽光透過窗子灑在木製餐桌上，桌上放滿了新鮮的黃油、麵粉和雞蛋，空氣中彌漫著香草精的味道，烤箱裡已經預熱，準備迎接即將出爐的美味 ~', '臺南市新市區圖書館', '臺南市新市區民族路192號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺南市新市區圖書館', 23.08319496, 120.2923941, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新市區圖書館:三月主題書展', `description`='三月主題書展\r\n兒童：我也可以\r\n每個故事裡都有一個勇敢的主角，只要相信自己無論遇到什麼挑戰，都能勇往直前，只要有自信，就能在這片無限的創作領域中 找到屬於自己的天地！\r\n\r\n成人：DIY烘培大挑戰\r\n在一個溫暖的家庭廚房裡，陽光透過窗子灑在木製餐桌上，桌上放滿了新鮮的黃油、麵粉和雞蛋，空氣中彌漫著香草精的味道，烤箱裡已經預熱，準備迎接即將出爐的美味 ~', `organizer`='臺南市新市區圖書館', `address`='臺南市新市區民族路192號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市新市區圖書館', `latitude`=23.08319496, `longitude`=120.2923941, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
