INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ee126b32419285b7134', '下營區圖書館:2024Openbook好書獎聯合書展', 'Openbook閱讀誌是2017年創立、文化部鼎力支持的非營利線上書評媒體,總編及顧問團隊皆出身具30年歷史的專業書評版「開卷」。2024好書獎並邀請到金馬獎最佳新導演—阮鳳儀代言,為好書獎增添知性魅力。下營區圖書館將配合展出將近30本書籍，包含：年度中文創作、年度翻譯書、年度生活書、年度青少年圖書、年度童書，敬邀您一起來品味創作者的文字。\r\n', '臺南市下營區圖書館', '臺南市下營區文化街117號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺南市下營區圖書館', 23.23103978, 120.26484, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='下營區圖書館:2024Openbook好書獎聯合書展', `description`='Openbook閱讀誌是2017年創立、文化部鼎力支持的非營利線上書評媒體,總編及顧問團隊皆出身具30年歷史的專業書評版「開卷」。2024好書獎並邀請到金馬獎最佳新導演—阮鳳儀代言,為好書獎增添知性魅力。下營區圖書館將配合展出將近30本書籍，包含：年度中文創作、年度翻譯書、年度生活書、年度青少年圖書、年度童書，敬邀您一起來品味創作者的文字。\r\n', `organizer`='臺南市下營區圖書館', `address`='臺南市下營區文化街117號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市下營區圖書館', `latitude`=23.23103978, `longitude`=120.26484, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ee226b32419285b7135', '台江圖書館：3月主題書展「動物」', '歡迎加入一場與動物的奇妙邂逅！動物是我們生活中不可或缺的夥伴，也是地球生態的重要一環。本次「動物」主題書展，將帶您走進動物的世界，從科學知識到文學故事，從野生動物到寵物之愛，讓我們一同探索生命的多樣性。', '臺南市政府文化局', '臺南市安南區安吉路一段205、207號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '台江文化中心', 23.04869681, 120.1526189, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台江圖書館：3月主題書展「動物」', `description`='歡迎加入一場與動物的奇妙邂逅！動物是我們生活中不可或缺的夥伴，也是地球生態的重要一環。本次「動物」主題書展，將帶您走進動物的世界，從科學知識到文學故事，從野生動物到寵物之愛，讓我們一同探索生命的多樣性。', `organizer`='臺南市政府文化局', `address`='臺南市安南區安吉路一段205、207號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='台江文化中心', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ee326b32419285b7136', '【五股守讓堂】114年3月【閱讀書籤】她筆之間：全球女性作家的智慧 書展', '主題：3月主題書展─她筆之間：全球女性作家的智慧  \r\n\r\n她說：「那種與現實脫節的假象， 反而徹底背離了年輕人最重要的價值──真實與勇敢…… 害怕失去青春、愛、優勢，過度的抗拒現實，結果卻失去了更多。」\r\n現實就是 ~~ 不畏懼，不強求，不偽裝...... 每個人都會老去，無須掩飾青春的逝去。\r\n\r\n汲取書中智慧，關愛自己，安然接受，戰勝現實。。\r\n\r\n\r\n\r\n展期：114年3月1日-3月31日／開館時間\r\n\r\n\r\n地點：五股守讓堂  (三讓文房書籍僅提供館內閱讀，均不外借)\r\n【五股守讓堂】三讓文房書展區（新北市五股區新五路二段169號）洽詢電話：02-22953212', '新北市立圖書館總館', '新北市五股區新五路二段169號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '五股守讓堂', 25.09614746, 121.4332139, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【五股守讓堂】114年3月【閱讀書籤】她筆之間：全球女性作家的智慧 書展', `description`='主題：3月主題書展─她筆之間：全球女性作家的智慧  \r\n\r\n她說：「那種與現實脫節的假象， 反而徹底背離了年輕人最重要的價值──真實與勇敢…… 害怕失去青春、愛、優勢，過度的抗拒現實，結果卻失去了更多。」\r\n現實就是 ~~ 不畏懼，不強求，不偽裝...... 每個人都會老去，無須掩飾青春的逝去。\r\n\r\n汲取書中智慧，關愛自己，安然接受，戰勝現實。。\r\n\r\n\r\n\r\n展期：114年3月1日-3月31日／開館時間\r\n\r\n\r\n地點：五股守讓堂  (三讓文房書籍僅提供館內閱讀，均不外借)\r\n【五股守讓堂】三讓文房書展區（新北市五股區新五路二段169號）洽詢電話：02-22953212', `organizer`='新北市立圖書館總館', `address`='新北市五股區新五路二段169號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='五股守讓堂', `latitude`=25.09614746, `longitude`=121.4332139, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ee326b32419285b7137', '新營文化中心《顏色的多重宇宙》主題書展', '《顏色的多重宇宙》主題書展\r\n踏入文化、設計與色彩交織的奇妙世界，探索無限可能的多重宇宙。從文化符號到現代設計的創新，讓色彩引領你穿越時空，發現藝術靈感的源泉。', '臺南市立新營文化中心', '臺南市新營區中正路23號', '2025-03-05 00:00:00', '2025-04-30 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新營文化中心《顏色的多重宇宙》主題書展', `description`='《顏色的多重宇宙》主題書展\r\n踏入文化、設計與色彩交織的奇妙世界，探索無限可能的多重宇宙。從文化符號到現代設計的創新，讓色彩引領你穿越時空，發現藝術靈感的源泉。', `organizer`='臺南市立新營文化中心', `address`='臺南市新營區中正路23號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ee326b32419285b7138', '新營文化中心《你是你或是妳都行》主題書展', '《你是你或是妳都行》主題書展\r\n性別不只是單單的二元性，透過書展打破對性別的刻板印象，尊重並包容性別的多元性，並破除性別歧視與偏見。\r\n\r\n', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-03-05 00:00:00', '2025-04-30 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新營文化中心《你是你或是妳都行》主題書展', `description`='《你是你或是妳都行》主題書展\r\n性別不只是單單的二元性，透過書展打破對性別的刻板印象，尊重並包容性別的多元性，並破除性別歧視與偏見。\r\n\r\n', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ee326b32419285b7139', '新營文化中心《【家】的故事—我們這一家》主題書展', '《【家】的故事—我們這一家》主題書展\r\n你會想到…房屋、居住在裡面的人及寵物…，在同一屋簷下生活，多多少少都有互動，就有故事發生…。讓我們看看別人家的故事…\r\n\r\n', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-03-05 00:00:00', '2025-04-30 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新營文化中心《【家】的故事—我們這一家》主題書展', `description`='《【家】的故事—我們這一家》主題書展\r\n你會想到…房屋、居住在裡面的人及寵物…，在同一屋簷下生活，多多少少都有互動，就有故事發生…。讓我們看看別人家的故事…\r\n\r\n', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ee726b32419285b713a', '安平區圖書館:3月書展性別平等', '有鑑於近年來教育部對性別平等議題之重視，\r\n帶領讀者探討現今社會中多元性別、\r\n情感教育等議題。\r\n\r\n『尊重』是開啟性別平等大門的一把鑰匙。\r\n消除歧視ˋ性別平權ˋ性別平等，\r\n統上等同於兩性平等（即男女平等或女男平等），\r\n主張不同性別者在政治、經濟、\r\n社會和家庭中應受到平等對待，\r\n而不應該基於性別而歧視某一方。\r\n共創兩性和諧社會。\r\n\r\n', '無資料', '臺南市安平區育平路320號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺南市安平區圖書館', 22.99008437, 120.1649949, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='安平區圖書館:3月書展性別平等', `description`='有鑑於近年來教育部對性別平等議題之重視，\r\n帶領讀者探討現今社會中多元性別、\r\n情感教育等議題。\r\n\r\n『尊重』是開啟性別平等大門的一把鑰匙。\r\n消除歧視ˋ性別平權ˋ性別平等，\r\n統上等同於兩性平等（即男女平等或女男平等），\r\n主張不同性別者在政治、經濟、\r\n社會和家庭中應受到平等對待，\r\n而不應該基於性別而歧視某一方。\r\n共創兩性和諧社會。\r\n\r\n', `organizer`='無資料', `address`='臺南市安平區育平路320號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市安平區圖書館', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ee926b32419285b713b', '北門區圖書館: 03月主題書展-女力崛起', '國際婦女節係於每年的3月8日為慶祝婦女在經濟、政治和社會等領域做出的重要貢獻的節日，以此主題辦理相關書展，並透過書展的辦理，讓讀者多了解圖書館的館藏資源，也藉由這樣的活動與讀者有更多的互動與交流。', '臺南市北門區圖書館', '臺南市北門區港北49號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺南市北門區圖書館', 23.2777708, 120.1262357, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='北門區圖書館: 03月主題書展-女力崛起', `description`='國際婦女節係於每年的3月8日為慶祝婦女在經濟、政治和社會等領域做出的重要貢獻的節日，以此主題辦理相關書展，並透過書展的辦理，讓讀者多了解圖書館的館藏資源，也藉由這樣的活動與讀者有更多的互動與交流。', `organizer`='臺南市北門區圖書館', `address`='臺南市北門區港北49號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市北門區圖書館', `latitude`=23.2777708, `longitude`=120.1262357, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
