INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ee926b32419285b713d', '六甲區圖書館:3月主題書展-絕代紅妝', '女性撐撐起半邊天，女力也是推動整個社會前進不可或缺的力量。\r\n\r\n希望藉由圖書館不斷的推動性別平等議題，讓更多人同理女性在社會所面對的差異、歧視。並在每一個時空中看見女力，詮釋女力！', '臺南市六甲區圖書館', '臺南市六甲區中山路202號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺南市六甲區公所/六甲區圖書館', 23.2272672, 120.3800259, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='六甲區圖書館:3月主題書展-絕代紅妝', `description`='女性撐撐起半邊天，女力也是推動整個社會前進不可或缺的力量。\r\n\r\n希望藉由圖書館不斷的推動性別平等議題，讓更多人同理女性在社會所面對的差異、歧視。並在每一個時空中看見女力，詮釋女力！', `organizer`='臺南市六甲區圖書館', `address`='臺南市六甲區中山路202號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市六甲區公所/六甲區圖書館', `latitude`=23.2272672, `longitude`=120.3800259, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
