INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7eef26b32419285b7142', '麻豆區圖書館:3月主題書展-精選英文讀物', '精選英文讀物，供來館民眾借閱及翻閱，藉以提升孩童及民眾的英語閱讀力。', '臺南市麻豆區圖書館', '臺南市麻豆區興國路11號3&4F', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺南市麻豆區圖書館', 23.18248033, 120.241308, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='麻豆區圖書館:3月主題書展-精選英文讀物', `description`='精選英文讀物，供來館民眾借閱及翻閱，藉以提升孩童及民眾的英語閱讀力。', `organizer`='臺南市麻豆區圖書館', `address`='臺南市麻豆區興國路11號3&4F', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市麻豆區圖書館', `latitude`=23.18248033, `longitude`=120.241308, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ef126b32419285b7143', '土城圖書館-3月書展「植感生活」、「男生女生配 性別無框界」', '「植感生活」：植物與我們的生活息息相關，從賴以為生的空氣，以及營養來源的食物，都可見到植物的身影。多數植物不僅對人的身體健康有好處，其樣貌還能撫慰人心，許多神奇的植物值得讓我們一起來認識與探究，歡迎借閱。\r\n「男生女生配 性別無框界」：我們如何區分性別？如何判斷正常的戀愛關係？如何定義「性」的樣態？人們習慣對周遭的事物定下定義、套上框架。框架，簡單的幫助人類分類所有概念，卻也同時限制了人類的想像，好似一旦超出框架，就注定成為「不正常」。本次書展涵蓋了所有性別議題，希冀觀展者踏入展間中，能暫時放下自身對於性別的既定印象，以開闊的心胸思索框架如何被形塑以及背後隱含的意義。', '臺南市安南區土城圖書館', '臺南市安南區城安路85號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺南市安南區土城圖書館', 23.04869681, 120.1526189, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='土城圖書館-3月書展「植感生活」、「男生女生配 性別無框界」', `description`='「植感生活」：植物與我們的生活息息相關，從賴以為生的空氣，以及營養來源的食物，都可見到植物的身影。多數植物不僅對人的身體健康有好處，其樣貌還能撫慰人心，許多神奇的植物值得讓我們一起來認識與探究，歡迎借閱。\r\n「男生女生配 性別無框界」：我們如何區分性別？如何判斷正常的戀愛關係？如何定義「性」的樣態？人們習慣對周遭的事物定下定義、套上框架。框架，簡單的幫助人類分類所有概念，卻也同時限制了人類的想像，好似一旦超出框架，就注定成為「不正常」。本次書展涵蓋了所有性別議題，希冀觀展者踏入展間中，能暫時放下自身對於性別的既定印象，以開闊的心胸思索框架如何被形塑以及背後隱含的意義。', `organizer`='臺南市安南區土城圖書館', `address`='臺南市安南區城安路85號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市安南區土城圖書館', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
