INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ef226b32419285b7145', '永康區圖書館 : 3月主題書展「就愛寵著~~你」', '📚🐶 三月主題書展～就愛寵著~~你 🐱📚\r\n「狗狗」是人類最忠實的朋友，人類是「喵喵」最好的僕人！\r\n在現代生活中，寵物佔據了我們生活的一大部分，\r\n但牠們只是被人餵養著而已嗎？？？\r\n牠們也有自己的情緒與喜惡，你真的瞭解牠們嗎？ \r\n牠們真的喜歡你嗎？快來探索動物與人類間奇妙的牽絆吧！ \r\n書展期間： 114年3月4日～114年3月30日\r\n地點： 一樓兒童書區、二樓成人書區，歡迎借閱！\r\n快來讓可愛的毛小孩走進你的閱讀時光吧！ ', '臺南市永康區圖書館', '臺南市永康區永大二路88號', '2025-03-04 00:00:00', '2025-03-30 00:00:00', '臺南市永康區社教中心(永康區圖書館)', 23.02729532, 120.2542795, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='永康區圖書館 : 3月主題書展「就愛寵著~~你」', `description`='📚🐶 三月主題書展～就愛寵著~~你 🐱📚\r\n「狗狗」是人類最忠實的朋友，人類是「喵喵」最好的僕人！\r\n在現代生活中，寵物佔據了我們生活的一大部分，\r\n但牠們只是被人餵養著而已嗎？？？\r\n牠們也有自己的情緒與喜惡，你真的瞭解牠們嗎？ \r\n牠們真的喜歡你嗎？快來探索動物與人類間奇妙的牽絆吧！ \r\n書展期間： 114年3月4日～114年3月30日\r\n地點： 一樓兒童書區、二樓成人書區，歡迎借閱！\r\n快來讓可愛的毛小孩走進你的閱讀時光吧！ ', `organizer`='臺南市永康區圖書館', `address`='臺南市永康區永大二路88號', `start_date`='2025-03-04 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市永康區社教中心(永康區圖書館)', `latitude`=23.02729532, `longitude`=120.2542795, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ef626b32419285b7146', '【新北市立圖書館新店分館】114年3月故事Show Time', '3/1(六)14:00 《傑瑞德忘記了》/Vivien 老師\r\n3/8(六)14:00  英語故事/Vozaco老師\r\n3/12(三)14:00 《我撒了一個謊》 *適合國小1-3年級/Elma老師\r\n3/22(六)14:00  《貓咪家的失望大餐》/Mia老師\r\n\r\n*報名後，將會收到系統電子信箱回覆，代表已報名成功。\r\n\r\n地點：新店分館3樓親子閱覽室(新北市新店區北新路3段105巷2號3樓)\r\n報名：即日起網路報名https://reurl.cc/qneMLy\r\n電話：2918-3181#230 ', '新北市立圖書館總館', '新北市新店區北新路三段105巷2號3樓', '2025-03-01 00:00:00', '2025-03-22 00:00:00', '新北市立圖書館新店分館', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店分館】114年3月故事Show Time', `description`='3/1(六)14:00 《傑瑞德忘記了》/Vivien 老師\r\n3/8(六)14:00  英語故事/Vozaco老師\r\n3/12(三)14:00 《我撒了一個謊》 *適合國小1-3年級/Elma老師\r\n3/22(六)14:00  《貓咪家的失望大餐》/Mia老師\r\n\r\n*報名後，將會收到系統電子信箱回覆，代表已報名成功。\r\n\r\n地點：新店分館3樓親子閱覽室(新北市新店區北新路3段105巷2號3樓)\r\n報名：即日起網路報名https://reurl.cc/qneMLy\r\n電話：2918-3181#230 ', `organizer`='新北市立圖書館總館', `address`='新北市新店區北新路三段105巷2號3樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='新北市立圖書館新店分館', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7ef826b32419285b7147', '｜東區林森圖書館｜3月主題書展 -捕捉瞬間，留住永恆', '由館員選書，針對各式的「攝影」專題書籍，主軸：「捕捉瞬間，留住永恆」，進行小型策展，提供讀者參考與借閱指引。', '臺南市東區林森圖書館', '臺南市東區林森路二段46號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺南市東區林森圖書館', 22.98178202, 120.2281858, '無資料', 'https://www.facebook.com/profile.php?id=100064371172026', '[]') ON DUPLICATE KEY UPDATE `activity_name`='｜東區林森圖書館｜3月主題書展 -捕捉瞬間，留住永恆', `description`='由館員選書，針對各式的「攝影」專題書籍，主軸：「捕捉瞬間，留住永恆」，進行小型策展，提供讀者參考與借閱指引。', `organizer`='臺南市東區林森圖書館', `address`='臺南市東區林森路二段46號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市東區林森圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064371172026', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7efa26b32419285b7148', '安定區圖書館:3月主題書展-飽讀食蔬', '隨著環境與生活的轉變，簡單烹煮方式及調味，達到健康養生的飲食型態，種植蔬果低碳愛地球。展出書籍有:食蔬好日子、香草運用完全指南、自己種菜吃、吃素越來越健康、今天不吃肉、蔬果花草共生秘訣、無農藥水耕裁培、呷菜等37本書籍。', '臺南市安定區公所', '臺南市安定區262之8號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺南市安定區圖書館', 23.09974927, 120.2296235, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='安定區圖書館:3月主題書展-飽讀食蔬', `description`='隨著環境與生活的轉變，簡單烹煮方式及調味，達到健康養生的飲食型態，種植蔬果低碳愛地球。展出書籍有:食蔬好日子、香草運用完全指南、自己種菜吃、吃素越來越健康、今天不吃肉、蔬果花草共生秘訣、無農藥水耕裁培、呷菜等37本書籍。', `organizer`='臺南市安定區公所', `address`='臺南市安定區262之8號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市安定區圖書館', `latitude`=23.09974927, `longitude`=120.2296235, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7efd26b32419285b7149', '大內區圖書館:3月份寵愛女性悅讀好書主題書展', '寵愛女性悅讀好書書展所展的書籍內容多元，包含實用型如彩妝、運動等，或是創意類如設計、繪本、健康、飲食等，另也有休閒如旅遊，或是文學、女性文學等類型書籍，邀請平日忙碌於家庭和工作的女性朋友們一起來享受閱讀的幸福。', '臺南市大內區圖書館', '臺南市大內區1-45號', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺南市大內區圖書館', 23.14482152, 120.3988147, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大內區圖書館:3月份寵愛女性悅讀好書主題書展', `description`='寵愛女性悅讀好書書展所展的書籍內容多元，包含實用型如彩妝、運動等，或是創意類如設計、繪本、健康、飲食等，另也有休閒如旅遊，或是文學、女性文學等類型書籍，邀請平日忙碌於家庭和工作的女性朋友們一起來享受閱讀的幸福。', `organizer`='臺南市大內區圖書館', `address`='臺南市大內區1-45號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市大內區圖書館', `latitude`=23.14482152, `longitude`=120.3988147, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7eff26b32419285b714a', '山上區圖書館:3月主題書展-快速上菜.自已也能變大廚', '每週只要固定買菜 一次，每次花2～3個小時整理食材，就能換得未來至少一週都能快速上菜，確實省下時間和金錢， 這才是我想要的生活模式。\r\n女人不要學做大廚，只要學會把菜丟鍋裡煮熟就行了」。但別以為「直接放鍋裡煮」是隨便亂來、敷衍了事，我之所以可以做到這點，全是拜母親傳授的食材處理與保存概念，我再把母親教我的概念發揚光大，讓下廚更快速輕省，而且沒有壓力。', '臺南市山上區圖書館', '臺南市山上區53號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺南市山上區圖書館', 23.09689329, 120.370977, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='山上區圖書館:3月主題書展-快速上菜.自已也能變大廚', `description`='每週只要固定買菜 一次，每次花2～3個小時整理食材，就能換得未來至少一週都能快速上菜，確實省下時間和金錢， 這才是我想要的生活模式。\r\n女人不要學做大廚，只要學會把菜丟鍋裡煮熟就行了」。但別以為「直接放鍋裡煮」是隨便亂來、敷衍了事，我之所以可以做到這點，全是拜母親傳授的食材處理與保存概念，我再把母親教我的概念發揚光大，讓下廚更快速輕省，而且沒有壓力。', `organizer`='臺南市山上區圖書館', `address`='臺南市山上區53號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市山上區圖書館', `latitude`=23.09689329, `longitude`=120.370977, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0126b32419285b714b', '中西區圖書館:「性別平等」主題書展', '本次書展精選各類性別議題書籍，從女性主義、兩性關係到性別平權等，帶您深入思考，開啟對話。歡迎到館借閱，讓我們學會互相尊重、包容彼此，一起為性別平等而努力！', '臺南市中西區圖書館', '臺南市中西區中正路3號(湯德章大道)', '2025-03-01 00:00:00', '2025-03-30 00:00:00', '臺南市中西區圖書館', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中西區圖書館:「性別平等」主題書展', `description`='本次書展精選各類性別議題書籍，從女性主義、兩性關係到性別平權等，帶您深入思考，開啟對話。歡迎到館借閱，讓我們學會互相尊重、包容彼此，一起為性別平等而努力！', `organizer`='臺南市中西區圖書館', `address`='臺南市中西區中正路3號(湯德章大道)', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-30 00:00:00', `location`='臺南市中西區圖書館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
