INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0326b32419285b714d', '柚愛了－🌸2025麻豆柚花季', '🌸 臺南的三月屬於花香，特別是麻豆的柚子花。\r\n春天的快樂，從花開時便悄然展開。柚花像愛笑的小姑娘，芬芳的印象一路延續至秋天的詩篇——中秋。\r\n\r\n🌿 柚花季，讓香氣綻放生活！\r\n以賞花、茶席、音樂、藝術與市集等多元活動，迎接麻豆三月最迷人的香氣。\r\n\r\n📍 活動資訊\r\n📅 日期： 3/22（六）\r\n📍 地點： 總爺國小旁柚子園\r\n\r\n🍵「愛靜靜」茶席（需預約報名）\r\n🌸 時間： 9:30-12:00\r\n📍 地點： 吉園休閒農場（總爺國小旁柚子園）\r\n🌿 特色：\r\n在柚子花香圍繞的春陽裡，茶席隨風飄散花韻。來自日本、香港與台灣各地的茶人，專程跨海、跨縣市設席，以特製的柚子花烏龍茶沖泡出專屬麻豆的氣息，邀請茶友共賞這場春日雅宴。\r\n\r\n🎶 花下音樂會（免報名，現場觀賞）\r\n🌸 時間： 15:00-16:30\r\n📍 地點： 總爺國小旁柚子園\r\n由臺南市立民族管絃樂團獻上悠揚樂章，與春日的柚花香氣交織成美好午後。\r\n\r\n🎭 柚花藝術與音樂表演（需預約報名）\r\n🌸 時間： 9:50-12:00\r\n📍 地點： 「愛靜靜」茶席區（總爺國小旁柚子園）\r\n✨ 活動流程：\r\n🍀 9:50-10:00 詩歌吟頌 —— 葉東泰（茶人）、劉建志（樂者）\r\n🍀 10:00-10:50 《三柚之裂：花氣．茶韻．身之非常態》\r\n行為藝術演出 —— 劉寅生、姚志杰、張嘉文\r\n🍀 10:50-11:10 中場休息\r\n🍀 11:10-12:00 音樂演出\r\n🎼《春来了》《櫻花》《春神來了》《春天啊》《花心》\r\n🎼 沖繩民謠《Tinsagunu hana》、台灣歌謠組曲\r\n聲樂家： 岡野麗\r\n電鋼琴演奏： 王夏儷\r\n\r\n在柚花滿開的時節，感受茶香、樂聲與藝術交織的春日時光，歡迎一同來麻豆，與春天相遇！ 🌿🌸✨', '臺南市政府文化局', '臺南市麻豆區總爺5號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '臺南市總爺藝文中心', 23.18248033, 120.241308, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='柚愛了－🌸2025麻豆柚花季', `description`='🌸 臺南的三月屬於花香，特別是麻豆的柚子花。\r\n春天的快樂，從花開時便悄然展開。柚花像愛笑的小姑娘，芬芳的印象一路延續至秋天的詩篇——中秋。\r\n\r\n🌿 柚花季，讓香氣綻放生活！\r\n以賞花、茶席、音樂、藝術與市集等多元活動，迎接麻豆三月最迷人的香氣。\r\n\r\n📍 活動資訊\r\n📅 日期： 3/22（六）\r\n📍 地點： 總爺國小旁柚子園\r\n\r\n🍵「愛靜靜」茶席（需預約報名）\r\n🌸 時間： 9:30-12:00\r\n📍 地點： 吉園休閒農場（總爺國小旁柚子園）\r\n🌿 特色：\r\n在柚子花香圍繞的春陽裡，茶席隨風飄散花韻。來自日本、香港與台灣各地的茶人，專程跨海、跨縣市設席，以特製的柚子花烏龍茶沖泡出專屬麻豆的氣息，邀請茶友共賞這場春日雅宴。\r\n\r\n🎶 花下音樂會（免報名，現場觀賞）\r\n🌸 時間： 15:00-16:30\r\n📍 地點： 總爺國小旁柚子園\r\n由臺南市立民族管絃樂團獻上悠揚樂章，與春日的柚花香氣交織成美好午後。\r\n\r\n🎭 柚花藝術與音樂表演（需預約報名）\r\n🌸 時間： 9:50-12:00\r\n📍 地點： 「愛靜靜」茶席區（總爺國小旁柚子園）\r\n✨ 活動流程：\r\n🍀 9:50-10:00 詩歌吟頌 —— 葉東泰（茶人）、劉建志（樂者）\r\n🍀 10:00-10:50 《三柚之裂：花氣．茶韻．身之非常態》\r\n行為藝術演出 —— 劉寅生、姚志杰、張嘉文\r\n🍀 10:50-11:10 中場休息\r\n🍀 11:10-12:00 音樂演出\r\n🎼《春来了》《櫻花》《春神來了》《春天啊》《花心》\r\n🎼 沖繩民謠《Tinsagunu hana》、台灣歌謠組曲\r\n聲樂家： 岡野麗\r\n電鋼琴演奏： 王夏儷\r\n\r\n在柚花滿開的時節，感受茶香、樂聲與藝術交織的春日時光，歡迎一同來麻豆，與春天相遇！ 🌿🌸✨', `organizer`='臺南市政府文化局', `address`='臺南市麻豆區總爺5號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='臺南市總爺藝文中心', `latitude`=23.18248033, `longitude`=120.241308, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0326b32419285b714e', '【新北市立圖書館三重東區分館】114年3月【閱讀書籤】主題書展', '【三重東區分館】114年3月份【閱讀書籤】「生活實用數學課」主題書展\r\n\r\n發佈館別：三重東區分館\r\n\r\n \r\n\r\n時間：114年3月1日至3月31日，週二至週六08:30~21:00，週日至週一08:30~17:00 (3月27日清館日休館不對外開放)\r\n\r\n \r\n\r\n書展簡介：\r\n\r\n數學這門科目，在多數人的印象中，可能只是既單調又冷冰冰的數字，又或是艱深複雜又難記的公式或定理…其實在生活中，無論食衣住行育樂，到處都充滿了數學的概念。本次書展，特別推出一系列關於生活實用的數學相關書籍，邀請您一起學習數學，並將數學概念活用在生活上，讓您不再覺得數學是枯燥乏味的課程，您的人生也因數學而將無往不利。\r\n\r\n \r\n\r\n＊活動單位保有取消、變更之權利，詳情請依現場為主。\r\n\r\n＊免費入場，無須報名，場內禁止飲食。\r\n\r\n\r\n地點：新北市立圖書館三重東區分館\r\n\r\n地址：新北市三重區溪尾街303號 / 1樓書展區\r\n\r\n電話：02-28575270\r\n\r\n \r\n\r\n‧公車 ：\r\n\r\n39、508、539  →  【碧華寺】站下車，步行約1分鐘\r\n\r\n62、226  →  【碧華國小】站或【分子尾】站下車，步行約5分鐘\r\n\r\n‧捷運 ：\r\n\r\n蘆洲線【三和國中站】下車，2號出口轉乘39、或1號出口轉乘508公車至【碧華寺】站下車，步行約1分鐘\r\n\r\n‧免費社區巴士：\r\n\r\n新北市新巴士【F303永福線】 → 【碧華寺】站下車，步行約1分鐘。', '新北市立圖書館總館', '新北市三重區溪尾街303號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館三重東區分館', 25.06281651, 121.4870977, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三重東區分館】114年3月【閱讀書籤】主題書展', `description`='【三重東區分館】114年3月份【閱讀書籤】「生活實用數學課」主題書展\r\n\r\n發佈館別：三重東區分館\r\n\r\n \r\n\r\n時間：114年3月1日至3月31日，週二至週六08:30~21:00，週日至週一08:30~17:00 (3月27日清館日休館不對外開放)\r\n\r\n \r\n\r\n書展簡介：\r\n\r\n數學這門科目，在多數人的印象中，可能只是既單調又冷冰冰的數字，又或是艱深複雜又難記的公式或定理…其實在生活中，無論食衣住行育樂，到處都充滿了數學的概念。本次書展，特別推出一系列關於生活實用的數學相關書籍，邀請您一起學習數學，並將數學概念活用在生活上，讓您不再覺得數學是枯燥乏味的課程，您的人生也因數學而將無往不利。\r\n\r\n \r\n\r\n＊活動單位保有取消、變更之權利，詳情請依現場為主。\r\n\r\n＊免費入場，無須報名，場內禁止飲食。\r\n\r\n\r\n地點：新北市立圖書館三重東區分館\r\n\r\n地址：新北市三重區溪尾街303號 / 1樓書展區\r\n\r\n電話：02-28575270\r\n\r\n \r\n\r\n‧公車 ：\r\n\r\n39、508、539  →  【碧華寺】站下車，步行約1分鐘\r\n\r\n62、226  →  【碧華國小】站或【分子尾】站下車，步行約5分鐘\r\n\r\n‧捷運 ：\r\n\r\n蘆洲線【三和國中站】下車，2號出口轉乘39、或1號出口轉乘508公車至【碧華寺】站下車，步行約1分鐘\r\n\r\n‧免費社區巴士：\r\n\r\n新北市新巴士【F303永福線】 → 【碧華寺】站下車，步行約1分鐘。', `organizer`='新北市立圖書館總館', `address`='新北市三重區溪尾街303號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館三重東區分館', `latitude`=25.06281651, `longitude`=121.4870977, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0326b32419285b714f', '【新北市立圖書館蘆洲兒童親子分館】114年3月【閱讀書籤】主題書展', '【蘆洲兒童親子分館】114年3月份【閱讀書籤】主題書展-春天來了\r\n時間：114年03月01日至114年03月31日 開館時間內\r\n\r\n \r\n\r\n簡介\r\n\r\n      展示與主題相關之圖書，提昇閱讀風氣\r\n\r\n\r\n\r\n \r\n\r\n＊活動單位保有取消、變更之權利，詳情請依現場為主。\r\n\r\n＊免費入場，無須報名，場內除白開水以外禁止飲食。\r\n\r\n\r\n \r\n\r\n位置：新北市蘆洲區集賢路221巷11號2樓/主題書展區。\r\n\r\n洽詢電話:02-2288-8294。\r\n\r\n\r\n\r\n \r\n\r\n交通\r\n\r\n搭乘公車：\r\n\r\n可搭乘811、815、816、927、928、紅9、橘13、橘19至集賢路口站下車步行約3-5分鐘即達。\r\n\r\n搭乘捷運：\r\n\r\n蘆洲線至徐匯中學站2號出口，往集賢路尼加拉瓜公園方向，步行約15-18分鐘即達。\r\n\r\n騎乘微笑單車：\r\n\r\n捷運蘆洲線徐匯中學站1號出口，往集賢路尼加拉瓜公園方向，騎行至蘆洲區重陽公園。', '新北市立圖書館總館', '新北市蘆洲區集賢路221巷11號2樓~3樓', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館蘆洲兒童親子分館', 25.08927173, 121.4712461, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館蘆洲兒童親子分館】114年3月【閱讀書籤】主題書展', `description`='【蘆洲兒童親子分館】114年3月份【閱讀書籤】主題書展-春天來了\r\n時間：114年03月01日至114年03月31日 開館時間內\r\n\r\n \r\n\r\n簡介\r\n\r\n      展示與主題相關之圖書，提昇閱讀風氣\r\n\r\n\r\n\r\n \r\n\r\n＊活動單位保有取消、變更之權利，詳情請依現場為主。\r\n\r\n＊免費入場，無須報名，場內除白開水以外禁止飲食。\r\n\r\n\r\n \r\n\r\n位置：新北市蘆洲區集賢路221巷11號2樓/主題書展區。\r\n\r\n洽詢電話:02-2288-8294。\r\n\r\n\r\n\r\n \r\n\r\n交通\r\n\r\n搭乘公車：\r\n\r\n可搭乘811、815、816、927、928、紅9、橘13、橘19至集賢路口站下車步行約3-5分鐘即達。\r\n\r\n搭乘捷運：\r\n\r\n蘆洲線至徐匯中學站2號出口，往集賢路尼加拉瓜公園方向，步行約15-18分鐘即達。\r\n\r\n騎乘微笑單車：\r\n\r\n捷運蘆洲線徐匯中學站1號出口，往集賢路尼加拉瓜公園方向，騎行至蘆洲區重陽公園。', `organizer`='新北市立圖書館總館', `address`='新北市蘆洲區集賢路221巷11號2樓~3樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館蘆洲兒童親子分館', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0326b32419285b7150', '【新北市立圖書館蘆洲集賢分館】114年3月【閱讀書籤】主題書展', '【蘆洲集賢分館】114年3月【閱讀書籤】主題書展\r\n\r\n【健康的養生術】~114年3月1日至3月31日。\r\n\r\n   吃對食物健康自然來，吃出健康食物能量滿滿，有效預防疾病，一天的營養怎麼吃?食物就是最美味的藥物，有效活用食物療效，聰明選擇、用心搭配，兼顧營養與美味，活力一整天!增強免疫力，疾病不上身，吃出一生好健康!\r\n\r\n \r\n\r\n週二至週六08:30~21:00，週日至週一08:30~17:00。\r\n\r\n3月27日清館日，不對外開放。\r\n\r\n地點:蘆洲集賢分館(蘆洲區集賢路245號4樓)\r\n\r\n＊活動單位保有取消變更之權利，詳情請依現場為主。\r\n\r\n＊免費入場，場內禁止飲食\r\n\r\n交通：\r\n\r\n搭乘公車：811、815、816、927、928、紅9、橘13、\r\n\r\n橘19至尼加拉瓜公園站下車步行約3-5分鐘\r\n\r\n搭乘捷運：蘆洲線徐匯中學站2號出口步行約12-15分鐘\r\n\r\n搭乘社區免費巴士：蘆洲區F313民和線、蘆洲區F316蘆\r\n\r\n洲線至尼加拉瓜公園站下車步行約3-5分鐘\r\n\r\n \r\n\r\n洽詢電話：02-82831792\r\n\r\n歡迎闔家光臨', '新北市立圖書館總館', '新北市蘆洲區集賢路245號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '新北市立圖書館蘆洲集賢分館（蘆洲藝文中心）', 25.08927173, 121.4712461, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館蘆洲集賢分館】114年3月【閱讀書籤】主題書展', `description`='【蘆洲集賢分館】114年3月【閱讀書籤】主題書展\r\n\r\n【健康的養生術】~114年3月1日至3月31日。\r\n\r\n   吃對食物健康自然來，吃出健康食物能量滿滿，有效預防疾病，一天的營養怎麼吃?食物就是最美味的藥物，有效活用食物療效，聰明選擇、用心搭配，兼顧營養與美味，活力一整天!增強免疫力，疾病不上身，吃出一生好健康!\r\n\r\n \r\n\r\n週二至週六08:30~21:00，週日至週一08:30~17:00。\r\n\r\n3月27日清館日，不對外開放。\r\n\r\n地點:蘆洲集賢分館(蘆洲區集賢路245號4樓)\r\n\r\n＊活動單位保有取消變更之權利，詳情請依現場為主。\r\n\r\n＊免費入場，場內禁止飲食\r\n\r\n交通：\r\n\r\n搭乘公車：811、815、816、927、928、紅9、橘13、\r\n\r\n橘19至尼加拉瓜公園站下車步行約3-5分鐘\r\n\r\n搭乘捷運：蘆洲線徐匯中學站2號出口步行約12-15分鐘\r\n\r\n搭乘社區免費巴士：蘆洲區F313民和線、蘆洲區F316蘆\r\n\r\n洲線至尼加拉瓜公園站下車步行約3-5分鐘\r\n\r\n \r\n\r\n洽詢電話：02-82831792\r\n\r\n歡迎闔家光臨', `organizer`='新北市立圖書館總館', `address`='新北市蘆洲區集賢路245號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='新北市立圖書館蘆洲集賢分館（蘆洲藝文中心）', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0526b32419285b7151', '2025青春美展 「3.14159」高雄市立前鎮高級中學第39屆美術班畢業美展', '「3.14159」——宇宙最純粹的形態，是藝術無邊無際的象徵。無起點，亦無終點；既是流動的詩篇，也是無窮的軌跡，如創作般，在探索與演變中生生不息。\r\n本次展覽以「圓周率」為引，拋出藝術的無限可能。創作不止步，而是如波紋擴展，似星軌交織，每次靈感的迴旋，皆是美術班「15班」同學們對未知的躍進。\r\n3.14159，不僅是圓周率的無窮序列，亦蘊藏我們的印記——前鎮高中美術班第39屆（3與9）與乙巳年（14）。 展覽結合莫比烏斯環的無限概念，這一無界流動的結構，象徵藝術的循環與永恆。\r\n本展不僅是一場展覽，更是一場無盡可能的冒險——在筆墨與思辨間行走，於感知與創造中延展，誠摯邀請您共探圓滿與無垠。\r\n*莫比烏斯環：是一種只有單一表面與單一邊界的奇特幾何結構。若沿著其表面行走，會發現不需穿越邊界即可回到起點，象徵無限、循環與連續性。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-05-30 00:00:00', '2025-06-10 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4114', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青春美展 「3.14159」高雄市立前鎮高級中學第39屆美術班畢業美展', `description`='「3.14159」——宇宙最純粹的形態，是藝術無邊無際的象徵。無起點，亦無終點；既是流動的詩篇，也是無窮的軌跡，如創作般，在探索與演變中生生不息。\r\n本次展覽以「圓周率」為引，拋出藝術的無限可能。創作不止步，而是如波紋擴展，似星軌交織，每次靈感的迴旋，皆是美術班「15班」同學們對未知的躍進。\r\n3.14159，不僅是圓周率的無窮序列，亦蘊藏我們的印記——前鎮高中美術班第39屆（3與9）與乙巳年（14）。 展覽結合莫比烏斯環的無限概念，這一無界流動的結構，象徵藝術的循環與永恆。\r\n本展不僅是一場展覽，更是一場無盡可能的冒險——在筆墨與思辨間行走，於感知與創造中延展，誠摯邀請您共探圓滿與無垠。\r\n*莫比烏斯環：是一種只有單一表面與單一邊界的奇特幾何結構。若沿著其表面行走，會發現不需穿越邊界即可回到起點，象徵無限、循環與連續性。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-30 00:00:00', `end_date`='2025-06-10 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4114', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0526b32419285b7152', '龍崎區圖書館:3月主題書展-不只是女生', '書展展出的方式以敞開大門·暢聊平等等相關書籍，不同類型之作品，傳記、小說、散文：後女性主義、素食者、我想看你變老的樣子、目送等書，探討女性在社會期待中的掙扎奮鬥乃至自我成長與覺醒，展現女子的各種不同面貌。', '臺南市龍崎區圖書館', '臺南市龍崎區新市子38號', '2025-03-01 00:00:00', '2025-03-31 00:00:00', '臺南市龍崎區圖書館', 22.95482276, 120.3869373, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='龍崎區圖書館:3月主題書展-不只是女生', `description`='書展展出的方式以敞開大門·暢聊平等等相關書籍，不同類型之作品，傳記、小說、散文：後女性主義、素食者、我想看你變老的樣子、目送等書，探討女性在社會期待中的掙扎奮鬥乃至自我成長與覺醒，展現女子的各種不同面貌。', `organizer`='臺南市龍崎區圖書館', `address`='臺南市龍崎區新市子38號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 00:00:00', `location`='臺南市龍崎區圖書館', `latitude`=22.95482276, `longitude`=120.3869373, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0526b32419285b7153', '藝術講座 : 吉他與烏克在一起_差在哪裡?', '烏克麗麗跟吉他差在哪裡?\r\n手腕位置，琴怎麼拿都有小訣竅，挑戰手指靈活度!\r\n烏克麗麗雖然只有四條弦，卻是簡單純粹的享受\r\n而吉他六條弦則是可以彈奏出更完整的旋律樂曲。\r\n彈久了除了自己技巧熟練以外，樂器的聲音也會越來越好聽!\r\n歡迎都想學無法決定的你，跟著楊明松老師 一起在上午享受彈奏的快樂!', '臺南市南關社區大學', '臺南市歸仁區', '2025-03-06 00:00:00', '2025-07-03 00:00:00', '歸仁區（臺南市）=', 22.94679469, 120.2930627, '2500元/人+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝術講座 : 吉他與烏克在一起_差在哪裡?', `description`='烏克麗麗跟吉他差在哪裡?\r\n手腕位置，琴怎麼拿都有小訣竅，挑戰手指靈活度!\r\n烏克麗麗雖然只有四條弦，卻是簡單純粹的享受\r\n而吉他六條弦則是可以彈奏出更完整的旋律樂曲。\r\n彈久了除了自己技巧熟練以外，樂器的聲音也會越來越好聽!\r\n歡迎都想學無法決定的你，跟著楊明松老師 一起在上午享受彈奏的快樂!', `organizer`='臺南市南關社區大學', `address`='臺南市歸仁區', `start_date`='2025-03-06 00:00:00', `end_date`='2025-07-03 00:00:00', `location`='歸仁區（臺南市）=', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='2500元/人+--', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0526b32419285b7154', '卡通大冒險《親子音樂會》', '全台最有趣的銅管親子互動音樂會全台巡演，一起動腦賓果與甜心姊姊互動唱跳玩遊戲，選號完成BINGO連線，贏得各式精美獎品；音樂會帶來許多銅管樂器介紹及吹奏方式，親子同歡，寓教於樂。\r\n\r\n', '高雄市政府文化局', '高雄市岡山區009鄰岡山南路42號', '2025-04-13 00:00:00', '2025-04-13 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '--+300;--+400;--+600;--+800;--+1000;--+1200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='卡通大冒險《親子音樂會》', `description`='全台最有趣的銅管親子互動音樂會全台巡演，一起動腦賓果與甜心姊姊互動唱跳玩遊戲，選號完成BINGO連線，贏得各式精美獎品；音樂會帶來許多銅管樂器介紹及吹奏方式，親子同歡，寓教於樂。\r\n\r\n', `organizer`='高雄市政府文化局', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-04-13 00:00:00', `end_date`='2025-04-13 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='--+300;--+400;--+600;--+800;--+1000;--+1200', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0626b32419285b7155', '「忘年書懷」–忘年書畫推展協會會員聯展', '「忘年書畫推展協會」是一群來自社會各個領域的書法同好，我們不分年齡、階層聚在一起飲文舞墨、暢懷於書趣中，沒有刻意編排的書寫目的，卻能自然流暢地演繹出「忘年書懷」的初衷。「書法」從古至今未曾離開過我們的生活，只要稍加停下腳步、關注周遭的畫面，將會發現如此生活化的書藝在你我的一回眸、一轉身中，彼此行影不離數千年⋯⋯。以書會友，讓書法拉近我們彼此的距離，透過書法，從文字、書寫內容來場無聲的心靈饗宴～', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-05-16 00:00:00', '2025-05-27 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4115', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「忘年書懷」–忘年書畫推展協會會員聯展', `description`='「忘年書畫推展協會」是一群來自社會各個領域的書法同好，我們不分年齡、階層聚在一起飲文舞墨、暢懷於書趣中，沒有刻意編排的書寫目的，卻能自然流暢地演繹出「忘年書懷」的初衷。「書法」從古至今未曾離開過我們的生活，只要稍加停下腳步、關注周遭的畫面，將會發現如此生活化的書藝在你我的一回眸、一轉身中，彼此行影不離數千年⋯⋯。以書會友，讓書法拉近我們彼此的距離，透過書法，從文字、書寫內容來場無聲的心靈饗宴～', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-16 00:00:00', `end_date`='2025-05-27 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4115', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0626b32419285b7156', 'fun心聽故事 (114年04月份)', '由故事達人於圖書館內辦理主題故事說演活動，並透過故事導讀，提起學齡前幼兒對繪本故事的興趣與表達自己對故事內容的想像與創造。', '高雄市立圖書館總館', '高雄市永安區005鄰永華路49號', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '高雄市立圖書館永安分館', 22.8159848, 120.2244381, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='fun心聽故事 (114年04月份)', `description`='由故事達人於圖書館內辦理主題故事說演活動，並透過故事導讀，提起學齡前幼兒對繪本故事的興趣與表達自己對故事內容的想像與創造。', `organizer`='高雄市立圖書館總館', `address`='高雄市永安區005鄰永華路49號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄市立圖書館永安分館', `latitude`=22.8159848, `longitude`=120.2244381, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0626b32419285b7157', '114年全縣美術家聯展', '114年全縣美術家聯展\r\n展期｜114年3月22日-4月09日\r\n展地｜金門縣文化局第一、二、三展場\r\n開幕式｜3月22日(六)上午10:00\r\n\r\n開幕式特邀地區傀儡戲達人蔡遠進老師配合其特藏室展出「嘉禮豐華─傀儡戲偶展」在開幕前表演拿手的傀儡戱暖場，將為地區一年一度的藝術盛事的聯合開幕增添熱鬧氣氛，歡迎鄉親踴躍參與。\r\n藝術講座｜3月22日(六)下午2時\r\n\r\n邀請張國英 老師於三樓會議室舉行「草圖與創作」藝術講座 ； 張老師將多年來從事美術教育及藝術創作的個人豐富經驗和體認心得作有系統的整理，內容包括為創作的準備工作：\r\n1.繪畫的基礎—-關於學習（應該學什麼？）\r\n2.心中的典範是什麼—-自己決定未來方向。\r\n3.一件藝術品的產生經歷——草圖與創作。\r\n4.靈感？題材、內容、主題、形式、技巧。並結合畫展觀摩，以和地區從事美學工作者和喜好藝術的人士來場面對面交流激盪，以提升地區美學的感染力，極度令人期待。\r\n\r\n本展已進入第34個年頭，致力於提供本縣和旅外的藝術創作者，提供他們一個展現才華與交流的平台。此次徵件涵蓋水墨、書法、水彩、油畫、膠彩、版畫、陶藝、雕塑、攝影、及綜合媒材等10個類別，經過本縣各藝術團體收集各類型作品及共約180餘件參展。\r\n展覽將呈現近年來地區藝文團體和藝術工作者在不停的教學相長和相互成長中呈現多元風格，作品內容主要涵蓋鄉土風情、日常寫生經驗、以及對金門發展現況的觀察與反思。透過不同媒材與技法，將各自的理念轉化為對摰愛家鄉獨特的藝術呈現，以激盪創意並促進藝術交流。\r\n期待透過此次展出，能讓來地區的鄉親在工作或閒暇之餘仍能徜徉於不同的山水墨韻、彩筆鄉情和不同藝術展現的人文空間裡，透過畫作與民眾來場心靈交流，讓文化局也能成為一座豐富多元的藝術展館。歡迎對這場美術展有興趣的民眾鄉親，在展期內前往金門縣文化局展場參觀，並請密切關注臉書「藝起金門」或查閱官方資訊以了解更多細節。\r\n\r\n金門縣文化局/主辦\r\n金門縣美術學會/𠄘辦', '金門縣文化局', '金門縣金城鎮環島北路一段66號', '2025-03-22 00:00:00', '2025-04-09 00:00:00', '金門縣文化局', 24.38402, 118.30128, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年全縣美術家聯展', `description`='114年全縣美術家聯展\r\n展期｜114年3月22日-4月09日\r\n展地｜金門縣文化局第一、二、三展場\r\n開幕式｜3月22日(六)上午10:00\r\n\r\n開幕式特邀地區傀儡戲達人蔡遠進老師配合其特藏室展出「嘉禮豐華─傀儡戲偶展」在開幕前表演拿手的傀儡戱暖場，將為地區一年一度的藝術盛事的聯合開幕增添熱鬧氣氛，歡迎鄉親踴躍參與。\r\n藝術講座｜3月22日(六)下午2時\r\n\r\n邀請張國英 老師於三樓會議室舉行「草圖與創作」藝術講座 ； 張老師將多年來從事美術教育及藝術創作的個人豐富經驗和體認心得作有系統的整理，內容包括為創作的準備工作：\r\n1.繪畫的基礎—-關於學習（應該學什麼？）\r\n2.心中的典範是什麼—-自己決定未來方向。\r\n3.一件藝術品的產生經歷——草圖與創作。\r\n4.靈感？題材、內容、主題、形式、技巧。並結合畫展觀摩，以和地區從事美學工作者和喜好藝術的人士來場面對面交流激盪，以提升地區美學的感染力，極度令人期待。\r\n\r\n本展已進入第34個年頭，致力於提供本縣和旅外的藝術創作者，提供他們一個展現才華與交流的平台。此次徵件涵蓋水墨、書法、水彩、油畫、膠彩、版畫、陶藝、雕塑、攝影、及綜合媒材等10個類別，經過本縣各藝術團體收集各類型作品及共約180餘件參展。\r\n展覽將呈現近年來地區藝文團體和藝術工作者在不停的教學相長和相互成長中呈現多元風格，作品內容主要涵蓋鄉土風情、日常寫生經驗、以及對金門發展現況的觀察與反思。透過不同媒材與技法，將各自的理念轉化為對摰愛家鄉獨特的藝術呈現，以激盪