INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0626b32419285b7158', '「藻安！澎湖」--藍晒海藻手工紙扇工作坊', '由鍾怡慧與陳瑞鴻兩位老師指導，教大家使用海藻手工紙進行藍晒創作，利用澎湖天然植物銀合歡與海藻特色創作素材與文創品。', '澎湖縣政府文化局', '澎湖縣馬公市民族路22號', '2025-03-16 00:00:00', '2025-04-19 00:00:00', '洪根深美術館', 23.55534, 119.59234, '無資料', '--', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「藻安！澎湖」--藍晒海藻手工紙扇工作坊', `description`='由鍾怡慧與陳瑞鴻兩位老師指導，教大家使用海藻手工紙進行藍晒創作，利用澎湖天然植物銀合歡與海藻特色創作素材與文創品。', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市民族路22號', `start_date`='2025-03-16 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='洪根深美術館', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='--', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc7f0626b32419285b7159', '細人仔成長禮', '客家文化發展中心自2016年起辦理客家成長禮，至今已陪伴超過上千名學子走過人生的重要階段。今年，活動將延續感恩奉茶傳統儀式，並加入「孝親擂茶」，讓孩子們為家長研磨出充滿心意的滋味；儀式中也加入了感人的「期勉授禮」，讓家長為孩子準備獨一無二的成長「禮」，為孩子與家長帶來滿滿祝福，讓家庭一同參與，感受客家文化的深厚底蘊。自2016年起辦理客家成長禮（hagˋ gaˊ siinˇ zongˋliˊ），到今已陪伴超過千位个學生仔行過人生當重要个階段，今年特別開「親子場」，邀請細人仔摎家長共下來創造難忘个回憶！\r\n孝親擂茶 感恩奉茶-孩子親手製作擂茶，為父母奉上。 \r\n期勉授禮-家長寫下期許送分自家个細人仔滿滿祝福个成長「禮」。\r\n親情加值 幸福樂章-在感動个樂聲中回顧自家細人仔還細个時節。\r\n完成儀式贈成長禮物：\r\n1.客語桌遊一份\r\n2.點心一份\r\n3.授禮內的三份祝福禮物\r\n報到須知：請於活動當日10:30-11:00，攜帶小朋友的健保卡(或學生證)至臺灣客家文化館一樓斜坡舞台進行報到。\r\n參加對象：限國小4-6年級的學童與一位家長共下參與。\r\n名額：100組，親子兩人一組。\r\n即日起受理線上報名，報名網址 https://www.accupass.com/event/2502271324571085392291', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '費用/組+100', 'https://www.facebook.com/hakkapark/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='細人仔成長禮', `description`='客家文化發展中心自2016年起辦理客家成長禮，至今已陪伴超過上千名學子走過人生的重要階段。今年，活動將延續感恩奉茶傳統儀式，並加入「孝親擂茶」，讓孩子們為家長研磨出充滿心意的滋味；儀式中也加入了感人的「期勉授禮」，讓家長為孩子準備獨一無二的成長「禮」，為孩子與家長帶來滿滿祝福，讓家庭一同參與，感受客家文化的深厚底蘊。自2016年起辦理客家成長禮（hagˋ gaˊ siinˇ zongˋliˊ），到今已陪伴超過千位个學生仔行過人生當重要个階段，今年特別開「親子場」，邀請細人仔摎家長共下來創造難忘个回憶！\r\n孝親擂茶 感恩奉茶-孩子親手製作擂茶，為父母奉上。 \r\n期勉授禮-家長寫下期許送分自家个細人仔滿滿祝福个成長「禮」。\r\n親情加值 幸福樂章-在感動个樂聲中回顧自家細人仔還細个時節。\r\n完成儀式贈成長禮物：\r\n1.客語桌遊一份\r\n2.點心一份\r\n3.授禮內的三份祝福禮物\r\n報到須知：請於活動當日10:30-11:00，攜帶小朋友的健保卡(或學生證)至臺灣客家文化館一樓斜坡舞台進行報到。\r\n參加對象：限國小4-6年級的學童與一位家長共下參與。\r\n名額：100組，親子兩人一組。\r\n即日起受理線上報名，報名網址 https://www.accupass.com/event/2502271324571085392291', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='費用/組+100', `source_url`='https://www.facebook.com/hakkapark/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dc817b26b32419285b715a', '2025兒童藝術節', '無資料', '無資料', '花蓮市', '2025-03-28 00:00:00', '2025-09-28 00:00:00', '秀林鄉、光復鄉、富里鄉、新城鄉、瑞穗鄉、吉安鄉、玉里鎮', 23.9910732, 121.6111949, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025兒童藝術節', `description`='無資料', `organizer`='無資料', `address`='花蓮市', `start_date`='2025-03-28 00:00:00', `end_date`='2025-09-28 00:00:00', `location`='秀林鄉、光復鄉、富里鄉、新城鄉、瑞穗鄉、吉安鄉、玉里鎮', `latitude`=23.9910732, `longitude`=121.6111949, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9378542', '有關 2025 雙北世界壯年運動會全系列官方周邊商品販售及優惠事宜，詳如說明， 敬請參考訂購', '2025雙北世界壯年運動會將於今年5月17日至30日舉行，全系列周邊商品，包括壯寶系列、運動休閒系列及紀念商品系列，再推出兼具在地文化特色及實用性的12項周邊商品，包括藍染口袋短Tee、薄機能外套、自動摺傘、鞋袋、平安符、在地文化徽章等品項，未來亦將陸續推出新商品。參見【2025雙北世界壯年運動會】周邊商品販售專區（網址：）。另2025雙北世界壯年運動會周邊商品北市府快閃店於3月18日至3月28日(不含假日)於市政大樓1樓熊讚辦公室進行實體展示及販售，每日對外開放時間為10點至17點，歡迎前往參觀或洽購。', '臺北市士林區健康服務中心', '無資料', '2025-03-21 00:00:00', '2025-05-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=E331A71F07C3E0D6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='有關 2025 雙北世界壯年運動會全系列官方周邊商品販售及優惠事宜，詳如說明， 敬請參考訂購', `description`='2025雙北世界壯年運動會將於今年5月17日至30日舉行，全系列周邊商品，包括壯寶系列、運動休閒系列及紀念商品系列，再推出兼具在地文化特色及實用性的12項周邊商品，包括藍染口袋短Tee、薄機能外套、自動摺傘、鞋袋、平安符、在地文化徽章等品項，未來亦將陸續推出新商品。參見【2025雙北世界壯年運動會】周邊商品販售專區（網址：）。另2025雙北世界壯年運動會周邊商品北市府快閃店於3月18日至3月28日(不含假日)於市政大樓1樓熊讚辦公室進行實體展示及販售，每日對外開放時間為10點至17點，歡迎前往參觀或洽購。', `organizer`='臺北市士林區健康服務中心', `address`='無資料', `start_date`='2025-03-21 00:00:00', `end_date`='2025-05-30 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=E331A71F07C3E0D6', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9378063', '114 / 03 / 22 青年職涯X就業博覽會', '徵才活動採訪重點：就服處本次活動為全國公辦最大場，邀請鼎泰豐、雲雀國際、雲品國際酒店、國賓大飯店、富邦媒體、欣興電子、京元電子、台北捷運等知名企業，共計214家徵才廠商，提供逾8,500個工作機會，平均月薪達4萬1,429元。履歷智慧健檢：針對不同職缺和產業，幫助求職者，量身打造專業履歷，並提供現場列印服務，提升求職者的履歷亮點，共計500名。職涯講座：協助求職者掌握關鍵求職策略。現場免費提供專業彩妝與形象照。(1)第一場：11:45~12:15「全球人才趨勢：AI 如何改變求職方式？新時代關鍵求職技能大公開」(2)第二場：14:05~14:35「職涯導航：履歷製作、面試技巧與職涯選擇全解析」青年局實習就業區：全國最大場實體實習博覽會，其中包含世界500強及上市上櫃公司，本次共邀請台灣微軟、華碩電腦、廣信益群、台新金控、臺灣水泥、杏輝藥品、台北萬豪、ACCUPASS、遠雄巨蛋及無印良品等36家企業。職前準備區：由12名專業職涯顧問透過履歷健檢等方式，為參與者提供專業建議。職涯講座區：幫助參與者探索自身特質，了解適合的職涯路徑，同時聚焦當前就業市場的最新發展，為參與者提供選擇職業的實用參考。(1)第一場：11:00-12:30「從DISC看性格-為你的職涯找到方向」(2)第二場：13:30-15:00「職場新動向-如何根據趨勢選擇職業」 1.舞台活動流程（將依實際狀況彈性調整時間）1.舞台活動流程（將依實際狀況彈性調整時間）時段流程說明/備註10:15－10:30長官貴賓就座10:30－10:32開場長官貴賓介紹10:33－10:37開場表演：心鼓社開場表演西松國小10:37－10:52長官貴賓致詞10:55－11:00大合影11:10－11:30參與職前準備、企業拜訪2.活動流程時段活動地點備註10:30－16:00徵才區/履歷智慧健檢/彩妝與形象照舞臺11:45－12:15講座：全球人才趨勢：AI 如何改變求職方式？新時代關鍵求職技能大公開講師：Trantor Liu14:05－14:35講座：職涯導航：履歷製作、面試技巧與職涯選擇全解析講師：陳惟邦10:30－16:00實習徵才區/一對一職涯諮詢工作坊11:00－12:30從DISC看性格-為你的職涯找到方向講師：黃庭妤13:30－15:00職場新動向-如何根據趨勢選擇職業講師：林重儀～誠摯邀請各位媒體先進親臨現場採訪～', '臺北市政府勞動局', '台北市中山區玉門街1號', '2025-03-22 00:00:00', '2025-03-22 00:00:00', '圓山花博公園爭艷館', 25.06969917, 121.5381597, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=2DDEA0579B38C0E7', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114 / 03 / 22 青年職涯X就業博覽會', `description`='徵才活動採訪重點：就服處本次活動為全國公辦最大場，邀請鼎泰豐、雲雀國際、雲品國際酒店、國賓大飯店、富邦媒體、欣興電子、京元電子、台北捷運等知名企業，共計214家徵才廠商，提供逾8,500個工作機會，平均月薪達4萬1,429元。履歷智慧健檢：針對不同職缺和產業，幫助求職者，量身打造專業履歷，並提供現場列印服務，提升求職者的履歷亮點，共計500名。職涯講座：協助求職者掌握關鍵求職策略。現場免費提供專業彩妝與形象照。(1)第一場：11:45~12:15「全球人才趨勢：AI 如何改變求職方式？新時代關鍵求職技能大公開」(2)第二場：14:05~14:35「職涯導航：履歷製作、面試技巧與職涯選擇全解析」青年局實習就業區：全國最大場實體實習博覽會，其中包含世界500強及上市上櫃公司，本次共邀請台灣微軟、華碩電腦、廣信益群、台新金控、臺灣水泥、杏輝藥品、台北萬豪、ACCUPASS、遠雄巨蛋及無印良品等36家企業。職前準備區：由12名專業職涯顧問透過履歷健檢等方式，為參與者提供專業建議。職涯講座區：幫助參與者探索自身特質，了解適合的職涯路徑，同時聚焦當前就業市場的最新發展，為參與者提供選擇職業的實用參考。(1)第一場：11:00-12:30「從DISC看性格-為你的職涯找到方向」(2)第二場：13:30-15:00「職場新動向-如何根據趨勢選擇職業」 1.舞台活動流程（將依實際狀況彈性調整時間）1.舞台活動流程（將依實際狀況彈性調整時間）時段流程說明/備註10:15－10:30長官貴賓就座10:30－10:32開場長官貴賓介紹10:33－10:37開場表演：心鼓社開場表演西松國小10:37－10:52長官貴賓致詞10:55－11:00大合影11:10－11:30參與職前準備、企業拜訪2.活動流程時段活動地點備註10:30－16:00徵才區/履歷智慧健檢/彩妝與形象照舞臺11:45－12:15講座：全球人才趨勢：AI 如何改變求職方式？新時代關鍵求職技能大公開講師：Trantor Liu14:05－14:35講座：職涯導航：履歷製作、面試技巧與職涯選擇全解析講師：陳惟邦10:30－16:00實習徵才區/一對一職涯諮詢工作坊11:00－12:30從DISC看性格-為你的職涯找到方向講師：黃庭妤13:30－15:00職場新動向-如何根據趨勢選擇職業講師：林重儀～誠摯邀請各位媒體先進親臨現場採訪～', `organizer`='臺北市政府勞動局', `address`='台北市中山區玉門街1號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-03-22 00:00:00', `location`='圓山花博公園爭艷館', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=2DDEA0579B38C0E7', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9378303', '插秧趣！4/12「鵝尾山水田一日農夫體驗」歡迎報名參加~', '臺北市士林區公所將於114年4月12日(星期六)8時至11時在鵝尾山水田辦理「鵝尾山水田一日農夫體驗」活動。活動內容包含鵝尾山水梯田故事解說、插秧體驗、農趣闖關遊戲，邀請民眾一起入田插秧，體驗水田文化魅力，透過實地走訪自然田野風貌，帶領民眾認識平等百年農村生活的人文歷史景點。活動免費！名額限38位，114年3月21日(星期五)早上10時起至114年3月28日（星期四）下午5時開放報名（額滿為止），欲報名者請填寫線上表單(https://forms.gle/vQxoBzaQDhxEfpqx9)，有問題請洽：02-28826200轉6504施小姐。', '臺北市士林區公所', '無資料', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=70021972057EC0A8', '[]') ON DUPLICATE KEY UPDATE `activity_name`='插秧趣！4/12「鵝尾山水田一日農夫體驗」歡迎報名參加~', `description`='臺北市士林區公所將於114年4月12日(星期六)8時至11時在鵝尾山水田辦理「鵝尾山水田一日農夫體驗」活動。活動內容包含鵝尾山水梯田故事解說、插秧體驗、農趣闖關遊戲，邀請民眾一起入田插秧，體驗水田文化魅力，透過實地走訪自然田野風貌，帶領民眾認識平等百年農村生活的人文歷史景點。活動免費！名額限38位，114年3月21日(星期五)早上10時起至114年3月28日（星期四）下午5時開放報名（額滿為止），欲報名者請填寫線上表單(https://forms.gle/vQxoBzaQDhxEfpqx9)，有問題請洽：02-28826200轉6504施小姐。', `organizer`='臺北市士林區公所', `address`='無資料', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=70021972057EC0A8', `image_url`='[]';
