INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9378104', '萬興分館「性別共好‧閱讀平權」性別平等系列活動，歡迎踴躍參加。', '為推廣性別平等觀念，以尊重差異、認識性別多樣性為主軸規劃辦理老少皆宜的系列活動。活動內容包含：一、鼓勵參與者超越性別角色限制的手作活動，透過紙藝手作創造多元形象；二、精選相關主題圖書辦理書展；佐以三、說故事活動引導孩童認識不同性別角色的生活經驗並理解身體差異與界限。歡迎踴躍參加。活動資訊如下：一、「性別共好‧紙藝秀多元」手作活動（需事先報名）（一）日期：4月20日(週日，國定性別平等教育日)（二）時間：上午10時至12時（三）講師：白啟峰老師（「孔夫紙手創坊」、「懷特紙屋」坊主）（四）地點：萬興分館5樓多功能活動室（五）參加對象：一般民眾、親子（兒童需滿6歲），名額24人。（六）報名方式：請洽服務臺或電話02-22345501報名。二、「性別共好‧平權交享閱」書展（一）日期：4月1日至4月30日（二）地點：萬興分館4樓書展區（三）展書提供外借。三、「性別共好‧繪本故事屋」說故事活動（一）日期：4月26日(週六)（二）時間：下午2時30分至4時（三）地點：萬興分館4樓親子共讀區若有相關問題歡迎來電詢問(電話：02-22345501)，萬興分館地址為臺北市萬壽路27號，鄰近政治大學，交通路線（點選分館簡介網頁）', '臺北市立圖書館', '無資料', '2025-03-20 00:00:00', '2025-04-20 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=CFA8C77A731740A1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='萬興分館「性別共好‧閱讀平權」性別平等系列活動，歡迎踴躍參加。', `description`='為推廣性別平等觀念，以尊重差異、認識性別多樣性為主軸規劃辦理老少皆宜的系列活動。活動內容包含：一、鼓勵參與者超越性別角色限制的手作活動，透過紙藝手作創造多元形象；二、精選相關主題圖書辦理書展；佐以三、說故事活動引導孩童認識不同性別角色的生活經驗並理解身體差異與界限。歡迎踴躍參加。活動資訊如下：一、「性別共好‧紙藝秀多元」手作活動（需事先報名）（一）日期：4月20日(週日，國定性別平等教育日)（二）時間：上午10時至12時（三）講師：白啟峰老師（「孔夫紙手創坊」、「懷特紙屋」坊主）（四）地點：萬興分館5樓多功能活動室（五）參加對象：一般民眾、親子（兒童需滿6歲），名額24人。（六）報名方式：請洽服務臺或電話02-22345501報名。二、「性別共好‧平權交享閱」書展（一）日期：4月1日至4月30日（二）地點：萬興分館4樓書展區（三）展書提供外借。三、「性別共好‧繪本故事屋」說故事活動（一）日期：4月26日(週六)（二）時間：下午2時30分至4時（三）地點：萬興分館4樓親子共讀區若有相關問題歡迎來電詢問(電話：02-22345501)，萬興分館地址為臺北市萬壽路27號，鄰近政治大學，交通路線（點選分館簡介網頁）', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=CFA8C77A731740A1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9378092', '轉知財團法人弘道老人福利基金會舉辦「2025爺奶Color Walk」健走活動訊息，歡迎民眾報名參加。', '附件。', '臺北市士林區健康服務中心', '無資料', '2025-03-20 00:00:00', '2025-04-18 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=67D0E689A8E7E9AF', '[]') ON DUPLICATE KEY UPDATE `activity_name`='轉知財團法人弘道老人福利基金會舉辦「2025爺奶Color Walk」健走活動訊息，歡迎民眾報名參加。', `description`='附件。', `organizer`='臺北市士林區健康服務中心', `address`='無資料', `start_date`='2025-03-20 00:00:00', `end_date`='2025-04-18 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=67D0E689A8E7E9AF', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9377913', '臺北市中山區辦理113年度山坡地老舊聚落疏散避難演習', '臺北市中山區公所訂於113年4月12日（星期五）上午10時於劍潭里通北街118巷及146巷山坡地老舊聚落辦理山坡地災害疏散避難演習。鑑於近年來災害型天氣發生之頻率愈發頻繁，如何加強行政機關防災能力，以及培養民眾自主防災減災觀念，以減少民眾受災損失，已成為政府部門的重要課題。本次演習地點通北街118巷及146巷山坡地老舊聚落因有建築物緊鄰陡峭邊坡、退縮距離不足等坡地災害風險因子，且在87年瑞伯颱風、90年納莉颱風時皆曾發生土石坍方案例，因此被臺北市政府列管進行整治；而為了保障聚落住戶安全，臺北市政府並制定預警撤離及收容安置措施，當24小時累積雨量達400毫米時，即將住戶疏散至緊急安置所進行安置。本年度的演習將動員區內消防、警察、學校、民間團體、企業防災夥伴等單位，以及里鄰防災應變小組、地區民眾等共同參與，藉由演習，期能於災害發生時立即動員、迅速疏散，達到減災、避災的主要目標。演習內容則分為四部分：一為颱風來臨前，區災害應變中心的緊急開設與聚落社區的防颱宣導；二為雨量達到黃色警戒值（24小時累積雨量300毫米）時，宣導民眾自主疏散避難作業；三為雨量達到紅色警戒值（24小時累積雨量400毫米）時，進行保全住戶的強制疏散與區域管制作為；四為避難收容說明。本次演習依據真實災害狀況進行模擬，中山區公所表示希望藉此加強民眾防災意識及觀念，平時能做好自主防範、災時則能熟稔避難場所之位置及疏散路線而得以快速應變逃生，達到保障市民生命財產權益之目的。', '臺北市中山區公所', '無資料', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=4579D66252840D25', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺北市中山區辦理113年度山坡地老舊聚落疏散避難演習', `description`='臺北市中山區公所訂於113年4月12日（星期五）上午10時於劍潭里通北街118巷及146巷山坡地老舊聚落辦理山坡地災害疏散避難演習。鑑於近年來災害型天氣發生之頻率愈發頻繁，如何加強行政機關防災能力，以及培養民眾自主防災減災觀念，以減少民眾受災損失，已成為政府部門的重要課題。本次演習地點通北街118巷及146巷山坡地老舊聚落因有建築物緊鄰陡峭邊坡、退縮距離不足等坡地災害風險因子，且在87年瑞伯颱風、90年納莉颱風時皆曾發生土石坍方案例，因此被臺北市政府列管進行整治；而為了保障聚落住戶安全，臺北市政府並制定預警撤離及收容安置措施，當24小時累積雨量達400毫米時，即將住戶疏散至緊急安置所進行安置。本年度的演習將動員區內消防、警察、學校、民間團體、企業防災夥伴等單位，以及里鄰防災應變小組、地區民眾等共同參與，藉由演習，期能於災害發生時立即動員、迅速疏散，達到減災、避災的主要目標。演習內容則分為四部分：一為颱風來臨前，區災害應變中心的緊急開設與聚落社區的防颱宣導；二為雨量達到黃色警戒值（24小時累積雨量300毫米）時，宣導民眾自主疏散避難作業；三為雨量達到紅色警戒值（24小時累積雨量400毫米）時，進行保全住戶的強制疏散與區域管制作為；四為避難收容說明。本次演習依據真實災害狀況進行模擬，中山區公所表示希望藉此加強民眾防災意識及觀念，平時能做好自主防範、災時則能熟稔避難場所之位置及疏散路線而得以快速應變逃生，達到保障市民生命財產權益之目的。', `organizer`='臺北市中山區公所', `address`='無資料', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1