INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9377542', '西湖分館4月19日愛樂賞析講座：音樂參與作為全民運動--談音樂教育新的可能與想像', '音樂可以視為人類跨文化的普遍行為。以生物演化的觀點來看，我們透過音樂來表達情感，可能促進了個體之間的彼此理解，進而促進了社群和諧。也因此，音樂教育除了從理解音樂作品、培養美感之外，也應該思考人類音樂的本能應該如何發揮。本次演講將會從音樂行為出發，討論人類的音樂本能，並且從認知科學對於大腦學習方式的研究，來討論音樂教育新的可能與想像，並且試著探討人工智慧快速發展的時代，對於音樂行為以及音樂作品的影響，歡迎相約到場參加!※活動時間：4月19日(週六)下午2:00~5:00※活動地點：臺北市立圖書館西湖分館4樓音樂廳 (臺北市內湖區內湖路一段594號)※活動講師：李承宗老師(東海大學通識中心兼任助理教授/音樂工作者)※洽詢電話：02-27973183※備註：不需事先報名，下午1:30開放入場。全程參與者提供公務人員終身學習認證時數2小時及閱讀存摺點數5點(公務人員如需認證者，請先至「公務人員終身學習網」線上報名。）', '臺北市立圖書館', '無資料', '2025-03-19 00:00:00', '2025-04-19 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=7893FE21D36A1C1A', '[]') ON DUPLICATE KEY UPDATE `activity_name`='西湖分館4月19日愛樂賞析講座：音樂參與作為全民運動--談音樂教育新的可能與想像', `description`='音樂可以視為人類跨文化的普遍行為。以生物演化的觀點來看，我們透過音樂來表達情感，可能促進了個體之間的彼此理解，進而促進了社群和諧。也因此，音樂教育除了從理解音樂作品、培養美感之外，也應該思考人類音樂的本能應該如何發揮。本次演講將會從音樂行為出發，討論人類的音樂本能，並且從認知科學對於大腦學習方式的研究，來討論音樂教育新的可能與想像，並且試著探討人工智慧快速發展的時代，對於音樂行為以及音樂作品的影響，歡迎相約到場參加!※活動時間：4月19日(週六)下午2:00~5:00※活動地點：臺北市立圖書館西湖分館4樓音樂廳 (臺北市內湖區內湖路一段594號)※活動講師：李承宗老師(東海大學通識中心兼任助理教授/音樂工作者)※洽詢電話：02-27973183※備註：不需事先報名，下午1:30開放入場。全程參與者提供公務人員終身學習認證時數2小時及閱讀存摺點數5點(公務人員如需認證者，請先至「公務人員終身學習網」線上報名。）', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=7893FE21D36A1C1A', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9376797', '《終身微學習資訊站》第39期《遇到詐騙？我識詐我不慌！》出刊囉！一起來閱讀', '近年詐騙案件頻傳，手法不斷翻新，我們是否有可能在發生損失前，便察覺自己遇到詐騙並冷靜面對呢？本期資訊站邀請到內政部警政署刑事警察局預防科與臺北市政府警察局刑事警察大隊經濟組，為大家解析常見的詐騙手法&mdash;&mdash;投資詐騙如何讓人掉入陷阱？長輩最容易遇到哪些騙局？此外，也特別邀請臨床心理師，教您如何善用直覺與邏輯，在關鍵時刻冷靜判斷、不落入騙局。透過專業分享，帶您提升防詐意識，守護自己與家人的財產安全！&nbsp;本期精彩內容請見：臺北市立圖書館首頁 &gt; 推薦服務 &gt; 終身微學習資訊站', '臺北市立圖書館', '無資料', '2025-03-20 00:00:00', '2025-04-15 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1DD81743CBFC2418', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《終身微學習資訊站》第39期《遇到詐騙？我識詐我不慌！》出刊囉！一起來閱讀', `description`='近年詐騙案件頻傳，手法不斷翻新，我們是否有可能在發生損失前，便察覺自己遇到詐騙並冷靜面對呢？本期資訊站邀請到內政部警政署刑事警察局預防科與臺北市政府警察局刑事警察大隊經濟組，為大家解析常見的詐騙手法&mdash;&mdash;投資詐騙如何讓人掉入陷阱？長輩最容易遇到哪些騙局？此外，也特別邀請臨床心理師，教您如何善用直覺與邏輯，在關鍵時刻冷靜判斷、不落入騙局。透過專業分享，帶您提升防詐意識，守護自己與家人的財產安全！&nbsp;本期精彩內容請見：臺北市立圖書館首頁 &gt; 推薦服務 &gt; 終身微學習資訊站', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-20 00:00:00', `end_date`='2025-04-15 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1DD81743CBFC2418', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9367972', '延吉民眾閱覽室「是幾米啊！你看過了嗎?」書展', '在國內外獲獎不斷的幾米，每次出書，總是造成轟動。每每讓人期待他的下一部作品。延吉民眾閱覽室特別選在4月兒童月，推薦優質臺灣作家幾米創作之繪本，舉辦「是幾米啊!你看過了嗎?」書展。邀請讀者們，一起來閱讀幾米，不論您是初次閱讀幾米、再次閱讀幾米，我們相信，您一定能從繪本中，獲得力量與感動。一.活動時間：&nbsp;3月25日至4月30日&nbsp;二.活動地點：&nbsp;延吉民眾閱覽室主題書展區&nbsp;三.活動對象：持有本館個人借閱證或家庭借閱證之讀者&nbsp;四.活動方式：書展活動期間，展示幾米創作的書籍，限館內閱讀之書展。五.活動地點臺北市立圖書館延吉民眾閱覽室臺北市延吉街236巷17號3、4樓&nbsp;電話：27081964　傳真：27052653&nbsp;', '臺北市立圖書館', '無資料', '2025-03-20 00:00:00', '2025-04-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1459AFA6B0B2BD9E', '[]') ON DUPLICATE KEY UPDATE `activity_name`='延吉民眾閱覽室「是幾米啊！你看過了嗎?」書展', `description`='在國內外獲獎不斷的幾米，每次出書，總是造成轟動。每每讓人期待他的下一部作品。延吉民眾閱覽室特別選在4月兒童月，推薦優質臺灣作家幾米創作之繪本，舉辦「是幾米啊!你看過了嗎?」書展。邀請讀者們，一起來閱讀幾米，不論您是初次閱讀幾米、再次閱讀幾米，我們相信，您一定能從繪本中，獲得力量與感動。一.活動時間：&nbsp;3月25日至4月30日&nbsp;二.活動地點：&nbsp;延吉民眾閱覽室主題書展區&nbsp;三.活動對象：持有本館個人借閱證或家庭借閱證之讀者&nbsp;四.活動方式：書展活動期間，展示幾米創作的書籍，限館內閱讀之書展。五.活動地點臺北市立圖書館延吉民眾閱覽室臺北市延吉街236巷17號3、4樓&nbsp;電話：27081964　傳真：27052653&nbsp;', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-20 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=1459AFA6B0B2BD9E', `image_url`='[]';
