INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9377212', '北市圖×數感實驗室 兒童月「城市解謎與走讀」活動開跑', '&nbsp; &nbsp; 還在煩惱今年的兒童節如何安排嗎？來臺北市立圖書館就對了！北市圖與數感實驗室攜手合作，於3月24日至4月26日推出「城市解謎與走讀」活動。解謎題目巧妙結合數學概念與總館特色場域，歡迎讀者透過酷課雲LINE官方帳號參與，體會解謎過程中的樂趣與驚奇。另外，4月13日的總館走讀活動也千萬別錯過!活動當日將由專業導師親自帶領，引導各位大小朋友探索總館獨特魅力！活動需提前報名，詳細內容請至2025兒童月官網查詢（https://act.tp.edu.tw/）。歡迎家長和孩子一起來北市圖感受閱讀的樂趣，共度充滿驚喜的兒童月！聯絡人資訊：數感實驗室徐小姐電話：（02）2391-6020#14', '臺北市立圖書館', '無資料', '2025-03-19 00:00:00', '2025-04-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=726CD11B966E2E82', '[]') ON DUPLICATE KEY UPDATE `activity_name`='北市圖×數感實驗室 兒童月「城市解謎與走讀」活動開跑', `description`='&nbsp; &nbsp; 還在煩惱今年的兒童節如何安排嗎？來臺北市立圖書館就對了！北市圖與數感實驗室攜手合作，於3月24日至4月26日推出「城市解謎與走讀」活動。解謎題目巧妙結合數學概念與總館特色場域，歡迎讀者透過酷課雲LINE官方帳號參與，體會解謎過程中的樂趣與驚奇。另外，4月13日的總館走讀活動也千萬別錯過!活動當日將由專業導師親自帶領，引導各位大小朋友探索總館獨特魅力！活動需提前報名，詳細內容請至2025兒童月官網查詢（https://act.tp.edu.tw/）。歡迎家長和孩子一起來北市圖感受閱讀的樂趣，共度充滿驚喜的兒童月！聯絡人資訊：數感實驗室徐小姐電話：（02）2391-6020#14', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-19 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=726CD11B966E2E82', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9377143', '士林分處-「童玩鄰舍節」社區租稅暨政風宣導活動', '士林分處-「童玩鄰舍節」社區租稅暨政風宣導活動時間：114年3月23日(日)上午9時00分至12時00分地點：臺北市士林區百齡國小操場 福港街205號 (請由東側門出入)內容：1.現場完成下列活動即贈宣導品1份。❤雲端發票四部曲。❤參加宣導遊戲。&nbsp;說明：1.捐贈之雲端發票限114年1-3月未登打統一編號且消費金額10元以上。2.本活動所募發票將全數捐贈社福團體。3.雲端發票經捐贈完成，即無法退還或兌獎。4.宣導品兌換以現場實物為準，主辦單位保有修改或變更宣導品的權利。5.數量有限，換完為止。&nbsp;聯絡人：士林分處 戴小姐 &nbsp;&nbsp;聯絡電話：2831-8101分機412======================稅務宣導==========================■北市稅處的全功能自動化服務機，可以查調臺北市、新北市、基隆市及桃園市稅務文件了!■稅務視訊服務雲結合全功能櫃檯申辦項目，提供多達70項視訊服務，其中32項可跨縣市查調。■本處設置納保官保障納稅者權益，申請納保視訊安心又方便。■性別平等從你我做起；落實性別平權，繼承與贈與不分性別。■人權大步走，生活更快活；人權兩公約請至人權大步走網頁查詢。■歡迎申辦電子化稅單及以電子方式傳送繳款書、轉帳通知及證明。■適用條件可分期繳納地方稅，包含：使用牌照稅、房屋稅、地價稅及印花稅之應繳稅款。■交通工具如不擬使用，請向監理機關申報停止使用。對報停、繳銷或註銷（含逕行註銷）牌照車輛，於恢復使用前，請車主重新申領牌照、驗車等，以免因使用（停放）公共道路經查獲而受罰。■利用地方稅網路申報作業系統申辦印花稅彙總繳納及印花稅大額總繳，省時又便利。■北市稅處提供直撥退稅線上回復、到府服務、預約取件及免費節稅教室等多項便民服務。●加入北市稅處粉絲團(FB、IG、Youtube)、地方稅LINE好友，獲取最新稅務資訊。●智慧客服24小時服務不打烊！●國稅及地方稅中英文免付費服務電話0800-000-321。●雲端發票四部曲，申請手機條碼、下載統一發票兌獎APP、載具歸戶並設定領獎帳戶。●雲端發票專屬獎項，總獎金高達13.67億元。●使用行動支付繳稅或消費並儲存雲端發票，方便又環保。●將跨境電商電子郵件及五大電信帳單發票綁定載具歸戶，發票自動存，獎金不漏接。●北市稅處於4/10、6/12、8/7、10/16、12/4晚上7:00至8:30在總處節稅教室辦理免費租稅講座。▲民眾得線上查詢被繼承人金融遺產及下載資料，並由國稅局統一回復，且申請查詢被繼承人金融遺產一併提供「遺產稅申報稅額試算」及「延期申報」服務。▲節能家電減徵貨物稅。▲符合自用住宅用地條件者，提醒於當年度9月22日前提出申請自用住宅用地優惠稅率。▲非都市土地供公共設施使用，被徵收前移轉，免徵土地增值稅。▲移送執行繳款書新增QR-Code專區，民眾可透過多元方式繳納稅款。▲透過財政部稅務入口網站、臺北市政府市民服務大平臺、地方稅網路申辦作業系統申辦地方稅案件。▲繳稅第ｅ等，下載支援pay.taipei繳稅業者APP，掃描繳款書上三段式條碼繳納臺北市地方稅。▲不動產移轉網路申報一站式服務。●洽公不送禮、不受禮，心意存心裡。●廉潔政府，公帑不浪費；誠信社會，你我不行賄。●法務部廉政署檢舉服務專線:0800-286-586。●本府廉政熱線:1999轉1743(一起肅貪)。', '臺北市稅捐稽徵處', '無資料', '2025-03-23 00:00:00', '2025-03-23 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=344715B1CFCFBBF3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='士林分處-「童玩鄰舍節」社區租稅暨政風宣導活動', `description`='士林分處-「童玩鄰舍節」社區租稅暨政風宣導活動時間：114年3月23日(日)上午9時00分至12時00分地點：臺北市士林區百齡國小操場 福港街205號 (請由東側門出入)內容：1.現場完成下列活動即贈宣導品1份。❤雲端發票四部曲。❤參加宣導遊戲。&nbsp;說明：1.捐贈之雲端發票限114年1-3月未登打統一編號且消費金額10元以上。2.本活動所募發票將全數捐贈社福團體。3.雲端發票經捐贈完成，即無法退還或兌獎。4.宣導品兌換以現場實物為準，主辦單位保有修改或變更宣導品的權利。5.數量有限，換完為止。&nbsp;聯絡人：士林分處 戴小姐 &nbsp;&nbsp;聯絡電話：2831-8101分機412======================稅務宣導==========================■北市稅處的全功能自動化服務機，可以查調臺北市、新北市、基隆市及桃園市稅務文件了!■稅務視訊服務雲結合全功能櫃檯申辦項目，提供多達70項視訊服務，其中32項可跨縣市查調。■本處設置納保官保障納稅者權益，申請納保視訊安心又方便。■性別平等從你我做起；落實性別平權，繼承與贈與不分性別。■人權大步走，生活更快活；人權兩公約請至人權大步走網頁查詢。■歡迎申辦電子化稅單及以電子方式傳送繳款書、轉帳通知及證明。■適用條件可分期繳納地方稅，包含：使用牌照稅、房屋稅、地價稅及印花稅之應繳稅款。■交通工具如不擬使用，請向監理機關申報停止使用。對報停、繳銷或註銷（含逕行註銷）牌照車輛，於恢復使用前，請車主重新申領牌照、驗車等，以免因使用（停放）公共道路經查獲而受罰。■利用地方稅網路申報作業系統申辦印花稅彙總繳納及印花稅大額總繳，省時又便利。■北市稅處提供直撥退稅線上回復、到府服務、預約取件及免費節稅教室等多項便民服務。●加入北市稅處粉絲團(FB、IG、Youtube)、地方稅LINE好友，獲取最新稅務資訊。●智慧客服24小時服務不打烊！●國稅及地方稅中英文免付費服務電話0800-000-321。●雲端發票四部曲，申請手機條碼、下載統一發票兌獎APP、載具歸戶並設定領獎帳戶。●雲端發票專屬獎項，總獎金高達13.67億元。●使用行動支付繳稅或消費並儲存雲端發票，方便又環保。●將跨境電商電子郵件及五大電信帳單發票綁定載具歸戶，發票自動存，獎金不漏接。●北市稅處於4/10、6/12、8/7、10/16、12/4晚上7:00至8:30在總處節稅教室辦理免費租稅講座。▲民眾得線上查詢被繼承人金融遺產及下載資料，並由國稅局統一回復，且申請查詢被繼承人金融遺產一併提供「遺產稅申報稅額試算」及「延期申報」服務。▲節能家電減徵貨物稅。▲符合自用住宅用地條件者，提醒於當年度9月22日前提出申請自用住宅用地優惠稅率。▲非都市土地供公共設施使用，被徵收前移轉，免徵土地增值稅。▲移送執行繳款書新增QR-Code專區，民眾可透過多元方式繳納稅款。▲透過財政部稅務入口網站、臺北市政府市民服務大平臺、地方稅網路申辦作業系統申辦地方稅案件。▲繳稅第ｅ等，下載支援pay.taipei繳稅業者APP，掃描繳款書上三段式條碼繳納臺北市地方稅。▲不動產移轉網路申報一站式服務。●洽公不送禮、不受禮，心意存心裡。●廉潔政府，公帑不浪費；誠信社會，你我不行賄。●法務部廉政署檢舉服務專線:0800-286-586。●本府廉政熱線:1999轉1743(一起肅貪)。', `organizer`='臺北市稅捐稽徵處', `address`='無資料', `start_date`='2025-03-23 00:00:00', `end_date`='2025-03-23 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=344715B1CFCFBBF3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9377071', '轉知臺北市政府衛生局114年「樂齡巨星秀」活躍老化競賽，歡迎社區長者團體報名參加', '轉知臺北市政府衛生局114年「樂齡巨星秀」活躍老化競賽，歡迎社區長者團體報名參加', '臺北市內湖區健康服務中心', '無資料', '2025-03-19 00:00:00', '2025-05-23 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=5AA9F42BFFF0140C', '[]') ON DUPLICATE KEY UPDATE `activity_name`='轉知臺北市政府衛生局114年「樂齡巨星秀」活躍老化競賽，歡迎社區長者團體報名參加', `description`='轉知臺北市政府衛生局114年「樂齡巨星秀」活躍老化競賽，歡迎社區長者團體報名參加', `organizer`='臺北市內湖區健康服務中心', `address`='無資料', `start_date`='2025-03-19 00:00:00', `end_date`='2025-05-23 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=5AA9F42BFFF0140C', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9376967', '天文親子營【極光】', '臺北市低收入家庭經過驗證後可全程免費參加，歡迎於4月8日起來電詢問及報名！「天文親子營」透過生動的展示場與「遇見歐若菈&mdash;追極光科學指南」特展導覽、深入淺出的主題課程，帶您認識極光及相關的天文新知，還有創意手指推抹畫DIY，利用雙手就可以畫出屬於自己的極光並瞭解美麗的極光是如何產生的。活動中也安排了觀賞宇宙劇場、立體劇場影片，以及搭乘宇宙探險車等，活動內容豐富有趣又活潑，歡迎親子及祖孫一起參加！活動時間：第 1 梯次：4月 12日（六）08:50-16:30。第 2 梯次：4月 13日（日）08:50-16:30。第 3 梯次：4月 20日（日）08:50-16:30。活動對象：國小一年級以上親子，歡迎祖孫報名參加，本活動為親子活動，每組報名需至少一位家長陪同參加，僅接受國小以上學童報名。活動費用：一般民眾：須購買展示場、宇宙探險、11:00宇宙劇場、13:00立體劇場門票 ，票價請參閱購票資訊。※本活動為套裝行程，不接受單獨行程購票，亦不接受其他優惠套票抵用。臺北市低收入家庭：免費（含午餐便當）。報名日期：一般民眾：4月 8日（二）09:00起開放網路報名，一次最多登錄4個名額，共130個名額，額滿為止。臺北市低收入家庭：4月 8日（二）10:00起撥打以下電話報名（每人每年度限參加1次）。洽詢電話：02-28314551轉 202或 204 &nbsp;推廣組。活動流程與其他注意事項：請參考活動簡章。', '臺北市立天文科學教育館', '無資料', '2025-04-12 00:00:00', '2025-04-20 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B62EB31ECEA5AA1F', '[]') ON DUPLICATE KEY UPDATE `activity_name`='天文親子營【極光】', `description`='臺北市低收入家庭經過驗證後可全程免費參加，歡迎於4月8日起來電詢問及報名！「天文親子營」透過生動的展示場與「遇見歐若菈&mdash;追極光科學指南」特展導覽、深入淺出的主題課程，帶您認識極光及相關的天文新知，還有創意手指推抹畫DIY，利用雙手就可以畫出屬於自己的極光並瞭解美麗的極光是如何產生的。活動中也安排了觀賞宇宙劇場、立體劇場影片，以及搭乘宇宙探險車等，活動內容豐富有趣又活潑，歡迎親子及祖孫一起參加！活動時間：第 1 梯次：4月 12日（六）08:50-16:30。第 2 梯次：4月 13日（日）08:50-16:30。第 3 梯次：4月 20日（日）08:50-16:30。活動對象：國小一年級以上親子，歡迎祖孫報名參加，本活動為親子活動，每組報名需至少一位家長陪同參加，僅接受國小以上學童報名。活動費用：一般民眾：須購買展示場、宇宙探險、11:00宇宙劇場、13:00立體劇場門票 ，票價請參閱購票資訊。※本活動為套裝行程，不接受單獨行程購票，亦不接受其他優惠套票抵用。臺北市低收入家庭：免費（含午餐便當）。報名日期：一般民眾：4月 8日（二）09:00起開放網路報名，一次最多登錄4個名額，共130個名額，額滿為止。臺北市低收入家庭：4月 8日（二）10:00起撥打以下電話報名（每人每年度限參加1次）。洽詢電話：02-28314551轉 202或 204 &nbsp;推廣組。活動流程與其他注意事項：請參考活動簡章。', `organizer`='臺北市立天文科學教育館', `address`='無資料', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=B62EB31ECEA5AA1F', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9376965', '2025雙北世界壯年運動會—開幕典禮 購票懶人包', '#2025雙北世壯運 #購票懶人包🚩【2025雙北世界壯年運動會&mdash;開幕典禮】&nbsp;✨3/20中午12點線上開賣門票‼️讓世界看見你的熱血🔥 一起迎接全球壯年運動員的精彩登場！這不只是一場典禮，更是一場凝聚力量的感動時刻！─── 開幕典禮───🏆日期｜5/17(六)19：00&nbsp;📌地點｜臺北大巨蛋🎟️購票三大好康一次拿✨周邊商品9折 &mdash; 購票同時加購官方周邊🛒輕鬆入手紀念好物！✨百家特約優惠 &mdash; 憑票證享💯家大巨蛋周邊特約店家專屬優惠🥢吃喝玩樂齊應援！✨東京來回機票抽獎 &mdash; 購票即獲抽獎資格✈️幸運之神可能就是你！─── 售票資訊 ───🛎️時間｜台灣時間 3/20(四)中午12：00 正式開賣💰票價｜NT$300 / NT$400 / NT$500🔗連結｜https://reurl.cc/1KjKQG🏅不論你是運動愛好者，還是想親身感受國際賽事氛圍，快標註好友相約購票，一起為選手加油，一同見證這場全球矚目的運動盛宴，感受汗水與榮耀交織的瞬間！', '臺北市政府財政局秘書室', '無資料', '2025-05-17 00:00:00', '2025-05-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=CF8BEEED1508BBC0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025雙北世界壯年運動會—開幕典禮 購票懶人包', `description`='#2025雙北世壯運 #購票懶人包🚩【2025雙北世界壯年運動會&mdash;開幕典禮】&nbsp;✨3/20中午12點線上開賣門票‼️讓世界看見你的熱血🔥 一起迎接全球壯年運動員的精彩登場！這不只是一場典禮，更是一場凝聚力量的感動時刻！─── 開幕典禮───🏆日期｜5/17(六)19：00&nbsp;📌地點｜臺北大巨蛋🎟️購票三大好康一次拿✨周邊商品9折 &mdash; 購票同時加購官方周邊🛒輕鬆入手紀念好物！✨百家特約優惠 &mdash; 憑票證享💯家大巨蛋周邊特約店家專屬優惠🥢吃喝玩樂齊應援！✨東京來回機票抽獎 &mdash; 購票即獲抽獎資格✈️幸運之神可能就是你！─── 售票資訊 ───🛎️時間｜台灣時間 3/20(四)中午12：00 正式開賣💰票價｜NT$300 / NT$400 / NT$500🔗連結｜https://reurl.cc/1KjKQG🏅不論你是運動愛好者，還是想親身感受國際賽事氛圍，快標註好友相約購票，一起為選手加油，一同見證這場全球矚目的運動盛宴，感受汗水與榮耀交織的瞬間！', `organizer`='臺北市政府財政局秘書室', `address`='無資料', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-30 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=CF8BEEED1508BBC0', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9376809', '內湖分處-警察局X稅捐處─租稅政風宣導活動', '內湖分處-警察局X稅捐處─租稅政風宣導活動活動時間：114年3月27日下午1時30分。活動地點：警察局內湖分局活動方式：1.完成雲端發票租稅QA問答和雲端發票四部曲任一部曲，即可參加捐贈雲端發票兌換宣導品活動，限捐贈114年3月5張以上、未登打統一編號且消費金額大於10元雲端發票，活動募集發票全數捐贈社福團體。2.稅務巡迴服務:提供地方稅務諮詢服務、受理民眾地方稅案件申請書、補發繳款書申請代收等。臺北市稅捐稽徵處內湖分處聯絡人：內湖分處 蔡小姐聯絡電話：02-27922059分機407~稅政宣導~★2025雙北世界壯年運動會於2025年5月17至30日舉行，今年2月17日官網開放報名，年滿30歲無需選拔即可報名參賽。★稅籍異動即時通服務，即時掌握名下不動產的申報移轉動態★自住房屋稅輕鬆省，房屋符合自住3要件，可申報按自住用稅率1.2%課徵房屋稅，倘本人、配偶及未成年子女全國僅持有1戶，稅率降低為1%。★房屋稅差別稅率2.0改採「全國總歸戶」，以每年2月末日為納稅義務基準日。★臺北市稅捐處智慧客服24小時服務不打烊，歡迎加入臺北市政府官方LINE QA地方稅節稅小幫手智慧客服服務。★地方稅LINE官方帳號，最新資訊立即掌握。★地方稅與國稅免付費電話0800-000321中英文雙語服務歡迎多加利用。★海外求職陷阱多，出境前請停看聽。★拒絕有禮，禮&ldquo;輕&rdquo;情意&ldquo;重&rdquo;，無禮更輕鬆。★勿因一己之喜，成洩密之道；勿因一己之誤，成安防之失。★不動產移轉一站式服務，掃描QR-Code完成土地增值稅及契稅申報，經審核無誤且查無欠稅，即可線上繳稅，免付完稅紙本至地政機關登記。★本處「房屋稅額e化查詢平台」，可線上查詢房屋稅、地價稅額及申請地價稅自用住宅用地。★請多加利用稅務視訊服務雲、視訊e櫃檯、視訊e納保、房地稅額e化查詢平台、直撥退稅線上回復等線上服務。★納稅者權利保護法施行，北市稅處設置納保官協助解決地方稅務紛爭。★免費節稅教室！每雙月第2個星期四晚間7時至8時30分，課程內容包含國稅、地方稅，歡迎來學習。★透過網路申報印花稅，省時又便利！★房屋稅、地價稅、使用牌照稅逾期繳納加徵滯納金案件，逾期30日內可掃描QR-Code繳稅。★多利用本處網站或地方稅網路申報作業申辦以電子方式傳送繳款書、轉帳繳納證明；已辦理使用牌照稅長期約定轉帳納稅者，得申請繳納通知歸戶。★自112年起民法成年年齡下修至18歲。★稅捐稽徵法修正，稅捐逾繳納期限始繳納，須加徵滯納金之加徵方式，修正為「每逾3日」按滯納數額加徵1％，總加徵率降為10％。★雲端發票專屬獎項，總獎金高達13.67億元!★電子發票網路領獎就是這麼簡單，只要設定一次，快速又便利。★電子化稅單e傳送，申請以電子方式傳送地方稅繳款書、轉帳通知及繳納證明，方便又安全。★繳稅用3C，方便用easy。使用pay.taipei或下載電子支付/行動支付APP，輕鬆繳納地價稅。★申請先預約，取件零等待，多利用簡易案件預約取件申請服務。★居住正義2.0，臺北市首創個人租賃住宅包租代管房屋享減稅優惠。★個人雲端稅務帳戶輕鬆掌握個人稅務資訊。★全功能自動化服務機(Kiosk)憑自然人/工商憑證、已註冊健保卡自助補單、發證、繳稅及申辦，一機搞定稅務大小事。★非都市土地供公共設施使用，「被徵收前」移轉，免徵土地增值稅。★性別平等從你我做起，落實性別平權繼承與贈與不分性別。★地方稅網路申報系統線上查繳稅功能除定期開徵之房屋稅、地價稅、使用牌照稅亦有土地增值稅、契稅及印花稅查繳服務；自113年11月1日起擴大繳稅項目，增加房屋稅、地價稅及使用牌照稅補稅，與使用牌照稅之試車牌、臨時牌、新領牌及重領牌查繳服務。', '臺北市稅捐稽徵處', '無資料', '2025-03-27 00:00:00', '2025-03-27 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=CA89858F51239779', '[]') ON DUPLICATE KEY UPDATE `activity_name`='內湖分處-警察局X稅捐處─租稅政風宣導活動', `description`='內湖分處-警察局X稅捐處─租稅政風宣導活動活動時間：114年3月27日下午1時30分。活動地點：警察局內湖分局活動方式：1.完成雲端發票租稅QA問答和雲端發票四部曲任一部曲，即可參加捐贈雲端發票兌換宣導品活動，限捐贈114年3月5張以上、未登打統一編號且消費金額大於10元雲端發票，活動募集發票全數捐贈社福團體。2.稅務巡迴服務:提供地方稅務諮詢服務、受理民眾地方稅案件申請書、補發繳款書申請代收等。臺北市稅捐稽徵處內湖分處聯絡人：內湖分處 蔡小姐聯絡電話：02-27922059分機407~稅政宣導~★2025雙北世界壯年運動會於2025年5月17至30日舉行，今年2月17日官網開放報名，年滿30歲無需選拔即可報名參賽。★稅籍異動即時通服務，即時掌握名下不動產的申報移轉動態★自住房屋稅輕鬆省，房屋符合自住3要件，可申報按自住用稅率1.2%課徵房屋稅，倘本人、配偶及未成年子女全國僅持有1戶，稅率降低為1%。★房屋稅差別稅率2.0改採「全國總歸戶」，以每年2月末日為納稅義務基準日。★臺北市稅捐處智慧客服24小時服務不打烊，歡迎加入臺北市政府官方LINE QA地方稅節稅小幫手智慧客服服務。★地方稅LINE官方帳號，最新資訊立即掌握。★地方稅與國稅免付費電話0800-000321中英文雙語服務歡迎多加利用。★海外求職陷阱多，出境前請停看聽。★拒絕有禮，禮&ldquo;輕&rdquo;情意&ldquo;重&rdquo;，無禮更輕鬆。★勿因一己之喜，成洩密之道；勿因一己之誤，成安防之失。★不動產移轉一站式服務，掃描QR-Code完成土地增值稅及契稅申報，經審核無誤且查無欠稅，即可線上繳稅，免付完稅紙本至地政機關登記。★本處「房屋稅額e化查詢平台」，可線上查詢房屋稅、地價稅額及申請地價稅自用住宅用地。★請多加利用稅務視訊服務雲、視訊e櫃檯、視訊e納保、房地稅額e化查詢平台、直撥退稅線上回復等線上服務。★納稅者權利保護法施行，北市稅處設置納保官協助解決地方稅務紛爭。★免費節稅教室！每雙月第2個星期四晚間7時至8時30分，課程內容包含國稅、地方稅，歡迎來學習。★透過網路申報印花稅，省時又便利！★房屋稅、地價稅、使用牌照稅逾期繳納加徵滯納金案件，逾期30日內可掃描QR-Code繳稅。★多利用本處網站或地方稅網路申報作業申辦以電子方式傳送繳款書、轉帳繳納證明；已辦理使用牌照稅長期約定轉帳納稅者，得申請繳納通知歸戶。★自112年起民法成年年齡下修至18歲。★稅捐稽徵法修正，稅捐逾繳納期限始繳納，須加徵滯納金之加徵方式，修正為「每逾3日」按滯納數額加徵1％，總加徵率降為10％。★雲端發票專屬獎項，總獎金高達13.67億元!★電子發票網路領獎就是這麼簡單，只要設定一次，快速又便利。★電子化稅單e傳送，申請以電子方式傳送地方稅繳款書、轉帳通知及繳納證明，方便又安全。★繳稅用3C，方便用easy。使用pay.taipei或下載電子支付/行動支付APP，輕鬆繳納地價稅。★申請先預約，取件零等待，多利用簡易案件預約取件申請服務。★居住正義2.0，臺北市首創個人租賃住宅包租代管房屋享減稅優惠。★個人雲端稅務帳戶輕鬆掌握個人稅務資訊。★全功能自動化服務機(Kiosk)憑自然人/工商憑證、已註冊健保卡自助補單、發證、繳稅及申辦，一機搞定稅務大小事。★非都市土地供公共設施使用，「被徵收前」移轉，免徵土地增值稅。★性別平等從你我做起，落實性別平權繼承與贈與不分性別。★地方稅網路申報系統線上查繳稅功能除定期開徵之房屋稅、地價稅、使用牌照稅亦有土地增值稅、契稅及印花稅查繳服務；自113年11月1日起擴大繳稅項目，增加房屋稅、地價稅及使用牌照稅補稅，與使用牌照稅之試車牌、臨時牌、新領牌及重領牌查繳服務。', `organizer`='臺北市稅捐稽徵處', `address`='無資料', `start_date`='2025-03-27 00:00:00', `end_date`='2025-03-27 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=CA89858F51239779', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9376789', '「春日筆記術」主題書展登場！', '一年之計在於春，現在正是規劃新目標的好時機！力行、南港、中崙、廣慈、民生五大分館聯合推出「春日筆記術」書展，精選各類筆記術相關書籍，幫助你善用筆記提升學習、工作與生活效率，讓新的一年更加精彩。▍特別活動 &nbsp;▍&nbsp;4月1日起，單日自助/手機借閱達10冊，即可用閱讀存摺150點兌換迷你筆記本1本（數量有限，換完為止）。趕快來參觀書展，發掘適合你的筆記方法，一起讓筆記成為實現目標的最佳夥伴！▍書展期間 ▍3月1日&mdash;4月30日▍展出地點 ▍▼力行分館 6樓書展區 &nbsp;(臺北市文山區一壽街22號，電話：02-86612196)▼南港分館 1樓主題書展區 (臺北市南港區南港路一段350號，電話：02-27825232)▼中崙分館 8樓書展區 (臺北市長安東路二段229號8樓，電話：02-87736858)▼廣慈分館 4樓書展區 (臺北市信義區福德街86號4樓，電話：02-27277872)▼民生分館 5樓書展區 (臺北市敦化北路199巷5號4樓，電話：02-27138083)', '臺北市立圖書館', '無資料', '2025-03-19 00:00:00', '2025-04-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=7CA2D7E43C3396D3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「春日筆記術」主題書展登場！', `description`='一年之計在於春，現在正是規劃新目標的好時機！力行、南港、中崙、廣慈、民生五大分館聯合推出「春日筆記術」書展，精選各類筆記術相關書籍，幫助你善用筆記提升學習、工作與生活效率，讓新的一年更加精彩。▍特別活動 &nbsp;▍&nbsp;4月1日起，單日自助/手機借閱達10冊，即可用閱讀存摺150點兌換迷你筆記本1本（數量有限，換完為止）。趕快來參觀書展，發掘適合你的筆記方法，一起讓筆記成為實現目標的最佳夥伴！▍書展期間 ▍3月1日&mdash;4月30日▍展出地點 ▍▼力行分館 6樓書展區 &nbsp;(臺北市文山區一壽街22號，電話：02-86612196)▼南港分館 1樓主題書展區 (臺北市南港區南港路一段350號，電話：02-27825232)▼中崙分館 8樓書展區 (臺北市長安東路二段229號8樓，電話：02-87736858)▼廣慈分館 4樓書展區 (臺北市信義區福德街86號4樓，電話：02-27277872)▼民生分館 5樓書展區 (臺北市敦化北路199巷5號4樓，電話：02-27138083)', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-19 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=7CA2D7E43C3396D3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9376589', '中山區公所114年度「甜蜜中山 幸福烘焙午茶時光」單身聯誼活動自3月24日中午12時起開放報名', '本所將於114年4月19日（星期六）上午11時30分在味全文化教育基金會舉辦114年度「甜蜜中山 幸福烘焙午茶時光」單身聯誼活動，歡迎於本市設籍、居住、就學或就業之25歲以上至50歲單身者踴躍報名參加(於中山區設籍、居住、就學或就業者及未參加過中山區單身聯誼活動者優先)，參加人數為男、女生人數各20人，共計40人，報名時間自起114年3月24日中午12時至114年4月7日中午12時或額滿為止。報名詳情請參閱活動簡章並至（https://lihi.cc/I0m8Q）報名。如有活動相關問題，請洽人文課2503-1369轉593鍾小姐。', '臺北市中山區公所', '無資料', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=FE4D1721CFFB17DD', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山區公所114年度「甜蜜中山 幸福烘焙午茶時光」單身聯誼活動自3月24日中午12時起開放報名', `description`='本所將於114年4月19日（星期六）上午11時30分在味全文化教育基金會舉辦114年度「甜蜜中山 幸福烘焙午茶時光」單身聯誼活動，歡迎於本市設籍、居住、就學或就業之25歲以上至50歲單身者踴躍報名參加(於中山區設籍、居住、就學或就業者及未參加過中山區單身聯誼活動者優先)，參加人數為男、女生人數各20人，共計40人，報名時間自起114年3月24日中午12時至114年4月7日中午12時或額滿為止。報名詳情請參閱活動簡章並至（https://lihi.cc/I0m8Q）報名。如有活動相關問題，請洽人文課2503-1369轉593鍾小姐。', `organizer`='臺北市中山區公所', `address`='無資料', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=FE4D1721CFFB17DD', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9376489', '萬華區公所辦理單身聯誼活動「新富町轉角遇見愛」', '臺北市萬華區公所114年度單身聯誼活動，將於114年5月17日上午10時30分至下午16時假新富町文化市場、剝皮寮、龍山寺舉辦，線上報名時間自3月24日至5月9日或額滿為止，凡年滿25歲以上，在臺北市居住、工作或就學，並且有穩定工作者（以萬華區者優先錄取），總計40個名額，男女各20人，免費參加， 活動洽詢（02）2256-1314、0980-891-314洪小姐或https://unijoys.com.tw網頁查詢。', '臺北市萬華區公所', '無資料', '2025-05-17 00:00:00', '2025-05-17 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=11FE76983A0F6092', '[]') ON DUPLICATE KEY UPDATE `activity_name`='萬華區公所辦理單身聯誼活動「新富町轉角遇見愛」', `description`='臺北市萬華區公所114年度單身聯誼活動，將於114年5月17日上午10時30分至下午16時假新富町文化市場、剝皮寮、龍山寺舉辦，線上報名時間自3月24日至5月9日或額滿為止，凡年滿25歲以上，在臺北市居住、工作或就學，並且有穩定工作者（以萬華區者優先錄取），總計40個名額，男女各20人，免費參加， 活動洽詢（02）2256-1314、0980-891-314洪小姐或https://unijoys.com.tw網頁查詢。', `organizer`='臺北市萬華區公所', `address`='無資料', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=11FE76983A0F6092', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9376405', '2025雙北世界壯年運動會開幕典禮門票將於3月20日中午12點線上開賣囉~購票資訊請洽世壯運官網查詢', '2025雙北世壯運開幕典禮將於114年5月17日晚間7點在臺北大巨蛋舉行，其中L4及L5看台區將開放一般民眾購票入場，開幕典禮門票將於3月20日中午12點整線上開賣。相關購票資訊，請洽世壯運官網/賽會活動/開閉幕/「開幕典禮購票資訊」查詢', '臺北市士林區健康服務中心', '無資料', '2025-03-19 00:00:00', '2025-05-17 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F984FC5D69D70CC6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025雙北世界壯年運動會開幕典禮門票將於3月20日中午12點線上開賣囉~購票資訊請洽世壯運官網查詢', `description`='2025雙北世壯運開幕典禮將於114年5月17日晚間7點在臺北大巨蛋舉行，其中L4及L5看台區將開放一般民眾購票入場，開幕典禮門票將於3月20日中午12點整線上開賣。相關購票資訊，請洽世壯運官網/賽會活動/開閉幕/「開幕典禮購票資訊」查詢', `organizer`='臺北市士林區健康服務中心', `address`='無資料', `start_date`='2025-03-19 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F984FC5D69D70CC6', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9376057', '2025兒童月天文館「極光放閃戳戳樂」系列活動', '2025年臺北天文館在4月兒童月的假日為大家舉辦特別活動，結合4月開展的年度特展『遇見歐若菈－追極光科學指南』，要讓大家製作專屬於自己極光貼畫，更加碼讓大小朋友可以玩戳戳樂，還有各種小禮物拿好拿滿！歡迎大家兒童月假日來天文館玩唷！活動訊息如下：&nbsp;極光放閃戳戳樂活動對象：現場遊客。活動時間：4月3、4、5、6、12、13、19、20、26、27日，每日09:30-12:00、13:00-16:00。活動地點：展示場、宇宙劇場、立體劇場、宇宙探險。報名方式：現場參加無需報名，每日限量400名。活動費用：本活動需購買本館各場館門票（票價及優惠依本館購票規定及相關優惠措施）。活動內容及流程：遊客向展示場1樓服務台索取極光畫卡後，憑本館各場館票根、兒童節及各式優惠免費等亦可，於展示場、宇宙劇場、立體劇場、宇宙探險等四個地點索取不同的極光貼紙自行完成貼畫。憑貼上2張以上極光貼紙的貼畫，至展示場一樓服務台玩1次戳戳樂。&nbsp; 免費搭乘宇宙探險車活動時間：4月4日當日。活動對象：全國12歲（含）以下兒童。活動方式：活動對象免費搭乘「宇宙探險車」1次，（6歲以下須家長另外購票入場陪同搭乘）。&nbsp; 星塵寶寶快閃活動時間：4月3、4日每日10時；4月5、6、13、20、27日每日16時，共7次，每次快閃約半小時。其他假日不定時快閃現身。活動內容：星塵寶寶出現快閃，與現場遊客合照互動。報名方式：現場參加無需報名。活動地點：天文館內隨機出現。&nbsp; 兒童來館禮活動時間：3月30日－4月30日之開館日，每週一休館。活動對象：全國12歲（含）以下兒童。活動方式：憑「臺北兒童月探索摺頁」至服務台領取小禮物1份，活動期間內可憑摺頁免費參觀展示場1次。&nbsp; 宇宙劇場、立體劇場免費影片欣賞活動時間：4月3日至6日，每日 09：00、09：40、10：20，共三場次。活動對象：一般大眾。活動方式：播放科學動畫短片，免費排隊入場參觀，額滿為止。&nbsp; 乖乖防詐活動說明：國泰世華配合政府防詐宣導，推出免費「防詐騙乖乖」，可掃描包裝上QRcode連結，觀看防詐騙宣導。領取方式：憑天文館任一票根（含各項優惠），可至館內兌換乖乖包處領取防詐乖乖，每人1包，數量有限，送完為止。活動時間：4月份開館日每日限量供應。以上各項活動洽詢電話：02-28314551分機747 展示組陳先生。', '臺北市立天文科學教育館', '無資料', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=016754BCBD61A531', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025兒童月天文館「極光放閃戳戳樂」系列活動', `description`='2025年臺北天文館在4月兒童月的假日為大家舉辦特別活動，結合4月開展的年度特展『遇見歐若菈－追極光科學指南』，要讓大家製作專屬於自己極光貼畫，更加碼讓大小朋友可以玩戳戳樂，還有各種小禮物拿好拿滿！歡迎大家兒童月假日來天文館玩唷！活動訊息如下：&nbsp;極光放閃戳戳樂活動對象：現場遊客。活動時間：4月3、4、5、6、12、13、19、20、26、27日，每日09:30-12:00、13:00-16:00。活動地點：展示場、宇宙劇場、立體劇場、宇宙探險。報名方式：現場參加無需報名，每日限量400名。活動費用：本活動需購買本館各場館門票（票價及優惠依本館購票規定及相關優惠措施）。活動內容及流程：遊客向展示場1樓服務台索取極光畫卡後，憑本館各場館票根、兒童節及各式優惠免費等亦可，於展示場、宇宙劇場、立體劇場、宇宙探險等四個地點索取不同的極光貼紙自行完成貼畫。憑貼上2張以上極光貼紙的貼畫，至展示場一樓服務台玩1次戳戳樂。&nbsp; 免費搭乘宇宙探險車活動時間：4月4日當日。活動對象：全國12歲（含）以下兒童。活動方式：活動對象免費搭乘「宇宙探險車」1次，（6歲以下須家長另