INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9377645', '2025智慧城市展「臺北市政府願景館」展示活動', '📢【臺北願景館】即將在2025智慧城市展 3/18~3/21登場 📢快來一探究竟❗臺北如何以AI驅動智慧城市的發展現場有集點送限量小禮🎁 還有多項亮點互動⬇️🌟消防車開箱、AI消防設備展示🌟AI眼底攝影機、AI專業醫療級12導程心電圖檢測🌟AI運動科學設備實機體驗🌟實機操作AI英語聽力練習、AI輔助手寫批閱臺北市政府願景館以「AI驅動&middot;未來臺北」為主軸預覽 #安全之都 &nbsp;#運動之都 #未來之都 的創新科技🚀親身體驗AI如何塑造未來臺北，共創智慧城市新典範!📢 趕快標註日曆🗓️一起來【南港展覽館2館1樓攤位P1013】體驗臺北的無限可能！#FutureTaipei #智慧城市展 #南港展覽館 #臺北願景─── 入場方式 ───◆憑國內參觀入場證👉 線上登記◆現場購票200元/人◆不開放未滿12歲以下兒童入場，勿穿涼鞋及拖鞋───展覽資訊───展覽日期｜2024/3/18~3/21開放時間｜10:00-18:00（展期最後一天僅至17:00）展覽地點｜南港展覽館2館1樓【攤位P1013】', '臺北市政府財政局秘書室', '無資料', '2025-03-18 00:00:00', '2025-03-21 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=413969FFC1456A6B', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025智慧城市展「臺北市政府願景館」展示活動', `description`='📢【臺北願景館】即將在2025智慧城市展 3/18~3/21登場 📢快來一探究竟❗臺北如何以AI驅動智慧城市的發展現場有集點送限量小禮🎁 還有多項亮點互動⬇️🌟消防車開箱、AI消防設備展示🌟AI眼底攝影機、AI專業醫療級12導程心電圖檢測🌟AI運動科學設備實機體驗🌟實機操作AI英語聽力練習、AI輔助手寫批閱臺北市政府願景館以「AI驅動&middot;未來臺北」為主軸預覽 #安全之都 &nbsp;#運動之都 #未來之都 的創新科技🚀親身體驗AI如何塑造未來臺北，共創智慧城市新典範!📢 趕快標註日曆🗓️一起來【南港展覽館2館1樓攤位P1013】體驗臺北的無限可能！#FutureTaipei #智慧城市展 #南港展覽館 #臺北願景─── 入場方式 ───◆憑國內參觀入場證👉 線上登記◆現場購票200元/人◆不開放未滿12歲以下兒童入場，勿穿涼鞋及拖鞋───展覽資訊───展覽日期｜2024/3/18~3/21開放時間｜10:00-18:00（展期最後一天僅至17:00）展覽地點｜南港展覽館2館1樓【攤位P1013】', `organizer`='臺北市政府財政局秘書室', `address`='無資料', `start_date`='2025-03-18 00:00:00', `end_date`='2025-03-21 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=413969FFC1456A6B', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a2ca6f418afbd32674393eb57ca68a45', '【新北市立圖書館樹林三多圖書閱覽室】114年4月彩虹故事屋', '【新北市立圖書館樹林三多圖書閱覽室】114年4月彩虹故事屋簡介：故事志工於本月第三個星期六上午，用生動活潑的聲音帶領小朋友進入各式各樣的故事世界中，讓小朋友從中領會閱讀的樂趣。本月活動時間：4/19(六) 10:30故事名稱：咬人花*活動時間若有變動，以現場公告為主，不便之處，敬請見諒。', '新北市立圖書館', '新北市樹林區福興街17號2樓', '新北市立圖書館樹林三多圖書閱覽室', 24.97970609, 121.401034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館樹林三多圖書閱覽室】114年4月彩虹故事屋', `description`='【新北市立圖書館樹林三多圖書閱覽室】114年4月彩虹故事屋簡介：故事志工於本月第三個星期六上午，用生動活潑的聲音帶領小朋友進入各式各樣的故事世界中，讓小朋友從中領會閱讀的樂趣。本月活動時間：4/19(六) 10:30故事名稱：咬人花*活動時間若有變動，以現場公告為主，不便之處，敬請見諒。', `organizer`='新北市立圖書館', `address`='新北市樹林區福興街17號2樓', `location`='新北市立圖書館樹林三多圖書閱覽室', `latitude`=24.97970609, `longitude`=121.401034, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a2ca6f418afbd3268163bb677ce0cc65', '【新北市立圖書館樹林三多圖書閱覽室】114年4月影友會', '【樹林三多圖書閱覽室】114年4月影友會放映時間:每周日下午14:004/06 悟空傳/保護級/124分五百年前，天庭分為三六九等，而出身低賤的悟空，卻狂傲不羈，大破各處規章戒律，向天地諸神發起抗爭。結界橋之戰，悟空等人不慎落入凡間，雖歷盡浩劫，卻收穫愛情與友情。然而，宿命難改，屬於青春不朽的奮戰正將展開...4/13 熊出沒-伴我熊芯/普遍級/93分熊大、熊二自幼在熊媽媽的悉心扶養下於森林中長大，然而在某個夜晚森林中發生了大火，熊媽媽前去查看，卻自此消失，年幼的兩熊傷心不已，轉眼多年過去，熊大、熊二的人類朋友光頭強帶著他們參觀機器人研發中心，卻意外得到了熊媽媽的線索，為此熊大、熊二展開尋親之旅，兩熊最終是否能找到媽媽? 一切謎團等待揭曉...4/20 金曲快送有限公司/普遍級/96分法蘭克準備成立了一家歌曲外送公司「歌來速」，拯救失業的自己跟朋友。正如Uber外送食物，亞馬遜運送日常用品，他們公司送的是歌曲!對法蘭克跟他的朋友來說，「歌來速」不僅是一份事業，更是他們一生的夢想。4/27 海豚與我 泳不放棄/普遍級/91分十歲的路克是一個充滿天賦的游泳競賽選手，但在媽媽離開後，他開始喪失對游泳的熱情，逐漸害怕下水...。直到他遇到一個充滿好奇心又十分友善的新朋友 : 一隻落單的海豚，他們一起度過的時間，為彼此創造了永生難忘的回憶，也改變了路克的人生，他將繼續勇敢的走向未來...', '新北市立圖書館', '新北市樹林區福興街17號2樓', '新北市立圖書館樹林三多圖書閱覽室', 24.97970609, 121.401034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館樹林三多圖書閱覽室】114年4月影友會', `description`='【樹林三多圖書閱覽室】114年4月影友會放映時間:每周日下午14:004/06 悟空傳/保護級/124分五百年前，天庭分為三六九等，而出身低賤的悟空，卻狂傲不羈，大破各處規章戒律，向天地諸神發起抗爭。結界橋之戰，悟空等人不慎落入凡間，雖歷盡浩劫，卻收穫愛情與友情。然而，宿命難改，屬於青春不朽的奮戰正將展開...4/13 熊出沒-伴我熊芯/普遍級/93分熊大、熊二自幼在熊媽媽的悉心扶養下於森林中長大，然而在某個夜晚森林中發生了大火，熊媽媽前去查看，卻自此消失，年幼的兩熊傷心不已，轉眼多年過去，熊大、熊二的人類朋友光頭強帶著他們參觀機器人研發中心，卻意外得到了熊媽媽的線索，為此熊大、熊二展開尋親之旅，兩熊最終是否能找到媽媽? 一切謎團等待揭曉...4/20 金曲快送有限公司/普遍級/96分法蘭克準備成立了一家歌曲外送公司「歌來速」，拯救失業的自己跟朋友。正如Uber外送食物，亞馬遜運送日常用品，他們公司送的是歌曲!對法蘭克跟他的朋友來說，「歌來速」不僅是一份事業，更是他們一生的夢想。4/27 海豚與我 泳不放棄/普遍級/91分十歲的路克是一個充滿天賦的游泳競賽選手，但在媽媽離開後，他開始喪失對游泳的熱情，逐漸害怕下水...。直到他遇到一個充滿好奇心又十分友善的新朋友 : 一隻落單的海豚，他們一起度過的時間，為彼此創造了永生難忘的回憶，也改變了路克的人生，他將繼續勇敢的走向未來...', `organizer`='新北市立圖書館', `address`='新北市樹林區福興街17號2樓', `location`='新北市立圖書館樹林三多圖書閱覽室', `latitude`=24.97970609, `longitude`=121.401034, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('bf571b853741fdf331577745e06ab279', '【新北市立圖書館淡水分館】 4月主題書展與紀錄片影展 :《2025新北詩歌節》', '2025新北詩歌節~主題書展《2025新北詩歌節 : 我和春天有一個約會 : 從詩出發》時間：4/1(二)-4/20(日)地點：淡水分館5F自修室(淡水區文化路65號3F)電話：02-26224664簡介：「陽春召我以煙景，大塊假我以文章」，春天是適合讀詩的季節，透過詩認識時間體會土地。隨著新北詩歌節遍撒詩歌種子，淡水分館特別精選台灣自1993年至2023年現代詩選，讓我們一起認識台灣這30年來所孕育的詩人詩作，感受歲月與時事如何交織出台灣的文化精神。▲詩選1999《動物新世紀：台灣文學史上第一本動物詩集》，林建隆著2003《小詩森林- -現代小詩選》，陳幸蕙編2007《小詩·牀頭書》，張默編2011《關於貓的詩（一）貓，有不理你的美》，林煥彰著2012《春天讀詩節—現代詩的100種可能》，羅智成編2013《美好的閱讀—2013春天讀詩節詩選》，羅智成編2018《詩說新北》，李魁賢等著2023《臺灣詩選》，宇文正編2025新北詩歌節~紀錄片影展(9場)【2025新北詩歌節 : 我和春天有一個約會】週六來淡水，帶一首詩回家時間：4/05（六）10:00、13:00、15:004/12（六）10:00、13:00、15:004/19（六）10:00、13:00、15:00地點：淡水分館5F研習教室（淡水區文化路65號）電話：02-26224664簡介：選映入圍金馬獎最佳紀錄片，由香港導演許鞍華所執導的《詩》，片長102分鐘。《詩》講述香港詩人黃燦然與廖偉棠的故事。許鞍華大學時主修詩歌，這部電影實現了她長久以來的拍攝願望。影片透過訪問香港詩人，討論文學與香江，特別聚焦兩位詩人的人生軌跡。黃燦然因高房價移居深圳，過著低調隱居的生活；廖偉棠則搬到台北，積極入世並講授詩學。電影展現香港詩人對抗生活壓迫、堅持創作的精神，反映香港的文化與精神出路。詩意融入銀幕，情意溶入腦海。黃燦然與廖偉棠的故事必然勾動出你我的曾經和對未來的想望。精選台灣自1999年至2023年所出版詩選，邀請你為心中所感，自詩選中挑出一首抄寫下來，在可以擁抱淡水河的圖書館，誓為一種祝福或是一個許諾。將所抄寫詩作分享於個人任一社群媒體：Facebook、Instagram等，加上有新北市圖淡水分館的 #tag，至4F或3F櫃檯由服務館員確認，可兌換一份小禮物(送完為止)，與在圖書館當天得以免申請拍攝館室的權利。', '新北市立圖書館', '新北市淡水區文化路65號', '淡水分館5F自修室與研習教室', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡水分館】 4月主題書展與紀錄片影展 :《2025新北詩歌節》', `description`='2025新北詩歌節~主題書展《2025新北詩歌節 : 我和春天有一個約會 : 從詩出發》時間：4/1(二)-4/20(日)地點：淡水分館5F自修室(淡水區文化路65號3F)電話：02-26224664簡介：「陽春召我以煙景，大塊假我以文章」，春天是適合讀詩的季節，透過詩認識時間體會土地。隨著新北詩歌節遍撒詩歌種子，淡水分館特別精選台灣自1993年至2023年現代詩選，讓我們一起認識台灣這30年來所孕育的詩人詩作，感受歲月與時事如何交織出台灣的文化精神。▲詩選1999《動物新世紀：台灣文學史上第一本動物詩集》，林建隆著2003《小詩森林- -現代小詩選》，陳幸蕙編2007《小詩·牀頭書》，張默編2011《關於貓的詩（一）貓，有不理你的美》，林煥彰著2012《春天讀詩節—現代詩的100種可能》，羅智成編2013《美好的閱讀—2013春天讀詩節詩選》，羅智成編2018《詩說新北》，李魁賢等著2023《臺灣詩選》，宇文正編2025新北詩歌節~紀錄片影展(9場)【2025新北詩歌節 : 我和春天有一個約會】週六來淡水，帶一首詩回家時間：4/05（六）10:00、13:00、15:004/12（六）10:00、13:00、15:004/19（六）10:00、13:00、15:00地點：淡水分館5F研習教室（淡水區文化路65號）電話：02-26224664簡介：選映入圍金馬獎最佳紀錄片，由香港導演許鞍華所執導的《詩》，片長102分鐘。《詩》講述香港詩人黃燦然與廖偉棠的故事。許鞍華大學時主修詩歌，這部電影實現了她長久以來的拍攝願望。影片透過訪問香港詩人，討論文學與香江，特別聚焦兩位詩人的人生軌跡。黃燦然因高房價移居深圳，過著低調隱居的生活；廖偉棠則搬到台北，積極入世並講授詩學。電影展現香港詩人對抗生活壓迫、堅持創作的精神，反映香港的文化與精神出路。詩意融入銀幕，情意溶入腦海。黃燦然與廖偉棠的故事必然勾動出你我的曾經和對未來的想望。精選台灣自1999年至2023年所出版詩選，邀請你為心中所感，自詩選中挑出一首抄寫下來，在可以擁抱淡水河的圖書館，誓為一種祝福或是一個許諾。將所抄寫詩作分享於個人任一社群媒體：Facebook、Instagram等，加上有新北市圖淡水分館的 #tag，至4F或3F櫃檯由服務館員確認，可兌換一份小禮物(送完為止)，與在圖書館當天得以免申請拍攝館室的權利。', `organizer`='新北市立圖書館', `address`='新北市淡水區文化路65號', `location`='淡水分館5F自修室與研習教室', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6d223edd7467bd4f7901f90a5edb68c2', '03/26新莊生活講座 「你其實很好騙！律師教你破解詐騙的心法與救濟療法」', '03/26(三)晚上7：00於新莊區公所10樓大禮堂(新莊區中正路176號)，邀請到秀策法律事務所主持律師沈士閎，以法律實務為基礎，透過一點點的心理學與社會學視角，揭露並剖析詐騙手法，傳授實用的防範心法與法律救濟途徑，讓您與家人遠離詐騙風險，守住辛苦賺來的血汗錢，不再成為詐騙集團眼中的肥羊！', '新莊區公所', '新北市新莊區中正路176號', '新莊區公所10樓大禮堂', 25.0358303, 121.4367535, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='03/26新莊生活講座 「你其實很好騙！律師教你破解詐騙的心法與救濟療法」', `description`='03/26(三)晚上7：00於新莊區公所10樓大禮堂(新莊區中正路176號)，邀請到秀策法律事務所主持律師沈士閎，以法律實務為基礎，透過一點點的心理學與社會學視角，揭露並剖析詐騙手法，傳授實用的防範心法與法律救濟途徑，讓您與家人遠離詐騙風險，守住辛苦賺來的血汗錢，不再成為詐騙集團眼中的肥羊！', `organizer`='新莊區公所', `address`='新北市新莊區中正路176號', `location`='新莊區公所10樓大禮堂', `latitude`=25.0358303, `longitude`=121.4367535, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6d223edd7467bd4f0ae46a699a146158', '03/25新莊生活講座「性別主流化-性別關係與婚姻經營」', '03/25(二)晚上7：00於新莊福營行政大樓6樓禮堂(新莊區四維路9號)，邀請雙和醫院臨床心理師沈晏羽，先介紹性別主流化的概念，再帶到今日的性別關係與婚姻關係的經營，已與往常的社會概念不相同，需要有不同的應對衝突及相處的方式，最後會再分享實際在婚姻經營上可使用的方法。', '新莊區公所', '新北市新莊區四維路9號', '新莊福營行政大樓6樓禮堂', 25.0358303, 121.4367535, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='03/25新莊生活講座「性別主流化-性別關係與婚姻經營」', `description`='03/25(二)晚上7：00於新莊福營行政大樓6樓禮堂(新莊區四維路9號)，邀請雙和醫院臨床心理師沈晏羽，先介紹性別主流化的概念，再帶到今日的性別關係與婚姻關係的經營，已與往常的社會概念不相同，需要有不同的應對衝突及相處的方式，最後會再分享實際在婚姻經營上可使用的方法。', `organizer`='新莊區公所', `address`='新北市新莊區四維路9號', `location`='新莊福營行政大樓6樓禮堂', `latitude`=25.0358303, `longitude`=121.4367535, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
