INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('95e51a48c4d3e6f4d137b799f6f858c0', '【新北市立圖書館淡水水碓分館】114年4月主題書展 :《快樂兒童節》', '《快樂兒童節》主題書展時間：4/1(二)-4/20(日)開館時間地點：淡水水碓分館4樓兒童室（淡水區中山北路一段158號）電話：02-26292879轉12簡介：4月4日兒童節，是為小朋友而特別制定的節日！兒童節的由來，不像其他民俗節慶有神秘的傳說，而是來自於一場溫馨的國際會議喔～西元1925年，一群來自世界各地的人，聚集在瑞士舉辦一場「兒童幸福國際大會」，並在會中通過《日內瓦兒童權利宣言》。從此各國就紛紛訂定「兒童節」來表達對保護兒童的支持。兒童是國家的未來、是家庭的寶貝，在這個專屬兒童的節日，此次書展精選多本童趣書籍邀請大小朋友一起凝聚歡樂。', '新北市立圖書館', '新北市淡水區中山北路一段158號', '淡水水碓分館4樓兒童室', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡水水碓分館】114年4月主題書展 :《快樂兒童節》', `description`='《快樂兒童節》主題書展時間：4/1(二)-4/20(日)開館時間地點：淡水水碓分館4樓兒童室（淡水區中山北路一段158號）電話：02-26292879轉12簡介：4月4日兒童節，是為小朋友而特別制定的節日！兒童節的由來，不像其他民俗節慶有神秘的傳說，而是來自於一場溫馨的國際會議喔～西元1925年，一群來自世界各地的人，聚集在瑞士舉辦一場「兒童幸福國際大會」，並在會中通過《日內瓦兒童權利宣言》。從此各國就紛紛訂定「兒童節」來表達對保護兒童的支持。兒童是國家的未來、是家庭的寶貝，在這個專屬兒童的節日，此次書展精選多本童趣書籍邀請大小朋友一起凝聚歡樂。', `organizer`='新北市立圖書館', `address`='新北市淡水區中山北路一段158號', `location`='淡水水碓分館4樓兒童室', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('95e51a48c4d3e6f47dce7e1536d81849', '【新北市立圖書館淡水竹圍分館】114年4月主題書展 :《悅讀橋》系列', '《悅讀橋系列》主題書展時間：4/1(二)-4/20(日) )開館時間地點：淡水竹圍分館4樓兒童室（淡水區民生路27號）電話：02-2624-1469轉23簡介：「悅讀橋」本系列書屬橋樑書性質的課外讀物，各書皆標有注音，讓孩子從這裡開始愛上閱讀！ 藉由不同作者所描繪不同的故事內容，帶領他們從閱讀繪本到文字。享受閱讀的樂趣。', '新北市立圖書館', '新北市淡水區民生路27號', '淡水竹圍分館4樓兒童室', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡水竹圍分館】114年4月主題書展 :《悅讀橋》系列', `description`='《悅讀橋系列》主題書展時間：4/1(二)-4/20(日) )開館時間地點：淡水竹圍分館4樓兒童室（淡水區民生路27號）電話：02-2624-1469轉23簡介：「悅讀橋」本系列書屬橋樑書性質的課外讀物，各書皆標有注音，讓孩子從這裡開始愛上閱讀！ 藉由不同作者所描繪不同的故事內容，帶領他們從閱讀繪本到文字。享受閱讀的樂趣。', `organizer`='新北市立圖書館', `address`='新北市淡水區民生路27號', `location`='淡水竹圍分館4樓兒童室', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('95e51a48c4d3e6f47ec95e1647eb3bd4', '【新北市立圖書館淡水竹圍分館】114年4月主題書展 :《趣味園藝》', '《趣味園藝》主題書展時間：4/1(二)-4/20(日) 開館時間地點：淡水竹圍分館5樓圖書室（淡水區民生路27號）電話：02-2809-7442轉9簡介：擁有自家菜園是許多人的夢想。不過當農夫哪有那麼簡單，要懂季節，也要懂植物，更要具備各種相關技巧，才能種出一番成績。透過實作多樣綠美化作品讓綠活喜悅充滿生活空間。了解植物生長特性，讓喜歡花草植物與栽種分享的朋友們，達成綠活美好分享的目標。', '新北市立圖書館', '新北市淡水區民生路27號', '淡水竹圍分館5樓圖書室', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡水竹圍分館】114年4月主題書展 :《趣味園藝》', `description`='《趣味園藝》主題書展時間：4/1(二)-4/20(日) 開館時間地點：淡水竹圍分館5樓圖書室（淡水區民生路27號）電話：02-2809-7442轉9簡介：擁有自家菜園是許多人的夢想。不過當農夫哪有那麼簡單，要懂季節，也要懂植物，更要具備各種相關技巧，才能種出一番成績。透過實作多樣綠美化作品讓綠活喜悅充滿生活空間。了解植物生長特性，讓喜歡花草植物與栽種分享的朋友們，達成綠活美好分享的目標。', `organizer`='新北市立圖書館', `address`='新北市淡水區民生路27號', `location`='淡水竹圍分館5樓圖書室', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('95e51a48c4d3e6f4f2cd0e34f09fbfff', '【新北市立圖書館淡水水碓分館】114年4月彩虹故事屋', '4月彩虹故事屋地點：淡水水碓分館4樓兒童室(淡水區中山北路1段158號)電話：02-26292879轉12◆說故事時間：14:00-15:004/05（六）清明連假暫停4/12（六）水公主4/19（六）企鵝演奏會4/26（六）想念不再傷心 歡迎家長帶著小朋友到館聆聽！', '新北市立圖書館', '新北市淡水區中山北路一段158號', '淡水水碓分館4樓兒童室', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡水水碓分館】114年4月彩虹故事屋', `description`='4月彩虹故事屋地點：淡水水碓分館4樓兒童室(淡水區中山北路1段158號)電話：02-26292879轉12◆說故事時間：14:00-15:004/05（六）清明連假暫停4/12（六）水公主4/19（六）企鵝演奏會4/26（六）想念不再傷心 歡迎家長帶著小朋友到館聆聽！', `organizer`='新北市立圖書館', `address`='新北市淡水區中山北路一段158號', `location`='淡水水碓分館4樓兒童室', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('95e51a48c4d3e6f40029ad155e3d3854', '【新北市立圖書館淡水分館】 4月主題書展 : 便當文化史', '《便當文化史》主題書展時間：4/7(一)-4/27(日)地點：淡水分館3F閱覽室（淡水區文化路65號3F）電話：02-26224664簡介：由不來梅創意設計、自由食間科技公司與銀色大門慈善機構共同推動的「老食人便當」計畫，一舉推翻便當長久以來約定俗成視之為表現幸福的定義，「隔夜雞腿飯」、「發霉鯖魚飯」、「酸味控肉飯」------打開這些便當，映入眼簾的是孤老長者面臨的飲食危機諸如被迫食用不新鮮食物，營養攝取不均加速身體機能退化等。2025年一開年農業部「幸福食材網」即公告，幸福餐盒計畫因經費問題只提供到1月底。全聯、家樂福及時表示，60元平價便當仍會持續販售，小資族對平價便當的需求無虞。便當從連結私人感情的記憶如搭火車吃便當的美好生活儀式，搖身一變成為公眾福利問題的關鍵指標！', '新北市立圖書館', '新北市淡水區文化路65號', '淡水分館3F閱覽室', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡水分館】 4月主題書展 : 便當文化史', `description`='《便當文化史》主題書展時間：4/7(一)-4/27(日)地點：淡水分館3F閱覽室（淡水區文化路65號3F）電話：02-26224664簡介：由不來梅創意設計、自由食間科技公司與銀色大門慈善機構共同推動的「老食人便當」計畫，一舉推翻便當長久以來約定俗成視之為表現幸福的定義，「隔夜雞腿飯」、「發霉鯖魚飯」、「酸味控肉飯」------打開這些便當，映入眼簾的是孤老長者面臨的飲食危機諸如被迫食用不新鮮食物，營養攝取不均加速身體機能退化等。2025年一開年農業部「幸福食材網」即公告，幸福餐盒計畫因經費問題只提供到1月底。全聯、家樂福及時表示，60元平價便當仍會持續販售，小資族對平價便當的需求無虞。便當從連結私人感情的記憶如搭火車吃便當的美好生活儀式，搖身一變成為公眾福利問題的關鍵指標！', `organizer`='新北市立圖書館', `address`='新北市淡水區文化路65號', `location`='淡水分館3F閱覽室', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('95e51a48c4d3e6f4db5c3f83cba95628', '【新北市立圖書館淡水分館】 4月主題書展 : 動物與我', '《動物與我》主題書展時間：4/7(一)-4/27(日)地點：淡水分館4F圖書室（淡水區文化路65號4F）電話：02-26224664簡介：韓國三星愛寶樂園大熊貓飼養員姜爺爺與大熊貓福寶的互動影片，治癒了韓國在疫情期間許多民眾因著無法掌握未知而擔驚焦慮的靈魂，更隨著民眾已習慣藉由應用社群媒體平台的各種編輯功能展示傳播，關注大熊貓儼然成為一種國際共通的語言，這份關注，嚴謹的說法可以是投射。大熊貓憨態可掬的模樣，彷彿是人類內心的小孩渴望受到保護，更期待可以有力量捍衛自己所愛之人事物的各種權益，野生動物變成精神上的寵物，似乎也讓人對身邊可以成為家人的寵物更有了責任意識。動物與人彼此相較同為人類更能夠相互救贖。動物不再是人類人格與個性的象徵，「動物與我」之間的關係改變將會如何引領當代文明塑造未來？', '新北市立圖書館', '新北市淡水區文化路65號', '水分館4F圖書室', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡水分館】 4月主題書展 : 動物與我', `description`='《動物與我》主題書展時間：4/7(一)-4/27(日)地點：淡水分館4F圖書室（淡水區文化路65號4F）電話：02-26224664簡介：韓國三星愛寶樂園大熊貓飼養員姜爺爺與大熊貓福寶的互動影片，治癒了韓國在疫情期間許多民眾因著無法掌握未知而擔驚焦慮的靈魂，更隨著民眾已習慣藉由應用社群媒體平台的各種編輯功能展示傳播，關注大熊貓儼然成為一種國際共通的語言，這份關注，嚴謹的說法可以是投射。大熊貓憨態可掬的模樣，彷彿是人類內心的小孩渴望受到保護，更期待可以有力量捍衛自己所愛之人事物的各種權益，野生動物變成精神上的寵物，似乎也讓人對身邊可以成為家人的寵物更有了責任意識。動物與人彼此相較同為人類更能夠相互救贖。動物不再是人類人格與個性的象徵，「動物與我」之間的關係改變將會如何引領當代文明塑造未來？', `organizer`='新北市立圖書館', `address`='新北市淡水區文化路65號', `location`='水分館4F圖書室', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
