INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003911', '元宵活動', '元宵節是農曆新年的第一個月圓之夜，是祭月、賞月的日子，也象徵著春天的到來，為復甦沙金沙生氣，用以結合傳統民俗藝術之美，打造一項親子活動，讓逐漸沒落的沙美街道能有更多人潮前來參訪。主辦單位：金沙鎮公所活動時間：2月活動地點：金沙鎮連絡電話：陳小姐 082-352150 各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-02-01 00:00:00', '2025-02-28 23:59:59', '金門縣金沙鎮', 24.48893, 118.41298, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='元宵活動', `description`='元宵節是農曆新年的第一個月圓之夜，是祭月、賞月的日子，也象徵著春天的到來，為復甦沙金沙生氣，用以結合傳統民俗藝術之美，打造一項親子活動，讓逐漸沒落的沙美街道能有更多人潮前來參訪。主辦單位：金沙鎮公所活動時間：2月活動地點：金沙鎮連絡電話：陳小姐 082-352150 各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-02-01 00:00:00', `end_date`='2025-02-28 23:59:59', `location`='金門縣金沙鎮', `latitude`=24.48893, `longitude`=118.41298, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003912', '2025綠色岐蹟．烈嶼綠石槽活動', '一、活動日期：114年3月1日起至5月31日止二、活動內容：（一）低碳載具暢遊綠石槽：活動期間搭乘電瓶車，憑票兌換宣導品1份，數量有限，贈完為止。（二）寫張明信片給一年後的自己：活動期間至青岐港生態小教室領取一張明信片，於明信片上寫下祝福的話，活動結束後本所將統一寄出，活動期間每人限領1次。（三）玩「轉」綠色岐蹟：活動期間至青岐港生態小教室領取一張明信片，並轉動轉盤，完成活動指定內容，即可領取活動紀念品1份，數量有限，贈完為止。（四）「綠色岐蹟．寫生徵圖比賽」：以本鄉綠石槽為主題，收件期間為2025年6月1日至6月16日，獎金豐富，詳情請參考活動簡章。三、好康報報：電瓶車票價限時優惠，自114年3月1日起至5月31日止，全票250元限時調降至優惠價150元，好康只在綠石槽季節限定才有喔，電瓶車預約專線082-362952、082-363455主辦單位：烈嶼鄉公所農觀課活動地點：烈嶼鄉青岐港連絡電話：羅小姐 082-364510各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-03-01 00:00:00', '2025-05-31 23:59:59', '金門縣烈嶼鄉', 24.41216, 118.23074, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025綠色岐蹟．烈嶼綠石槽活動', `description`='一、活動日期：114年3月1日起至5月31日止二、活動內容：（一）低碳載具暢遊綠石槽：活動期間搭乘電瓶車，憑票兌換宣導品1份，數量有限，贈完為止。（二）寫張明信片給一年後的自己：活動期間至青岐港生態小教室領取一張明信片，於明信片上寫下祝福的話，活動結束後本所將統一寄出，活動期間每人限領1次。（三）玩「轉」綠色岐蹟：活動期間至青岐港生態小教室領取一張明信片，並轉動轉盤，完成活動指定內容，即可領取活動紀念品1份，數量有限，贈完為止。（四）「綠色岐蹟．寫生徵圖比賽」：以本鄉綠石槽為主題，收件期間為2025年6月1日至6月16日，獎金豐富，詳情請參考活動簡章。三、好康報報：電瓶車票價限時優惠，自114年3月1日起至5月31日止，全票250元限時調降至優惠價150元，好康只在綠石槽季節限定才有喔，電瓶車預約專線082-362952、082-363455主辦單位：烈嶼鄉公所農觀課活動地點：烈嶼鄉青岐港連絡電話：羅小姐 082-364510各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-05-31 23:59:59', `location`='金門縣烈嶼鄉', `latitude`=24.41216, `longitude`=118.23074, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003913', '單車的香格里拉-金門國家公園生態樂騎活動', '1.每梯次參加人員上限35-40人。2.活動辦理方式：每梯3天、由專業領騎帶領導覽解說。3.報名費800元-1000。(以上資訊，依實際公告為主) 主辦單位：內政部國家公園署金門國家公園管理處活動時間：預計推出8梯次，分別於4、5、6、9、10、11月間擇期辦理。活動地點：大小金門連絡電話：遊憩服務科張小姐 082-313215各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-04-01 00:00:00', '2025-11-30 23:59:59', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='單車的香格里拉-金門國家公園生態樂騎活動', `description`='1.每梯次參加人員上限35-40人。2.活動辦理方式：每梯3天、由專業領騎帶領導覽解說。3.報名費800元-1000。(以上資訊，依實際公告為主) 主辦單位：內政部國家公園署金門國家公園管理處活動時間：預計推出8梯次，分別於4、5、6、9、10、11月間擇期辦理。活動地點：大小金門連絡電話：遊憩服務科張小姐 082-313215各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-04-01 00:00:00', `end_date`='2025-11-30 23:59:59', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003914', '浯島城隍文化觀光季', '結合地方社區及學校資源，表演一系列的民俗活動，並以各式地方特色陣頭活動表演表現地區各種不同習俗和傳統文化等，提供在地民眾及來金觀光遊客一個豐盛的文化饗宴及體驗金門在地傳統文化。主辦單位：金城鎮公所觀光課活動時間：4月12日至6月30日活動地點：金城鎮連絡電話：王小姐 082-325057各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-04-12 00:00:00', '2025-06-30 23:59:59', '金門縣金城鎮', 24.43206, 118.31551, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='浯島城隍文化觀光季', `description`='結合地方社區及學校資源，表演一系列的民俗活動，並以各式地方特色陣頭活動表演表現地區各種不同習俗和傳統文化等，提供在地民眾及來金觀光遊客一個豐盛的文化饗宴及體驗金門在地傳統文化。主辦單位：金城鎮公所觀光課活動時間：4月12日至6月30日活動地點：金城鎮連絡電話：王小姐 082-325057各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-04-12 00:00:00', `end_date`='2025-06-30 23:59:59', `location`='金門縣金城鎮', `latitude`=24.43206, `longitude`=118.31551, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003915', '2025金寧鄉石蚵文化季', '金寧鄉特有的石蚵，結合觀光、生態等資源，來塑造地方產業特色．以食農教育為推廣方向，與在地蚵農合作舉辦「超頂!千人剝蚵大挑戰」，親身體驗傳統產業文化。   主活動日舉辦「激鬥!石蚵大胃王最強賽」，玩轉傳統產業以創新的活動方式看到更不一樣的產業魅力，以及大型親子活動「大放電!春日親子遊樂園」，設置多樣遊樂設施與闖關活動結合在地攤商帶來歡樂有趣的嘉年華會。活動時間、地點、內容：一、114年3月24日下午2點  活動記者發布會活動地點: 古寧頭北山出海口二、114年4月12日下午4點  (一)超頂!千人剝蚵大挑戰預定114年4月12日下午16點(配合潮汐)於北山出海口舉辦，邀集民眾遊客，共同體驗蚵民剝蚵樂趣，現場自由入座，額滿為止。。(二)free!石蚵特色料理品嘗加完「超頂!千人剝蚵大挑戰」活動之民眾，公所特別加碼贈送參與民眾每人一份蚵仔麵線，數量有限，發完為止。活動地點: 古寧頭北山出海口三、114年4月19~20日下午2點~晚上9點  (一)大放電!春日親子遊樂園活動以親子遊戲嘉年華為特色，以兒童遊樂園型式，目的吸引更多的親子家庭同樂。計有刺激海盜船、飄移飛車、旋轉飛機、旋轉小火車、充氣城堡、夜市遊戲機檯等及許多親子互動遊戲，營造親子共融歡樂氣氛。(二)瘋起來!LOCAL音樂派對本次特別著重「吸引跨世代族群」的觀念，除在地社區文化團隊、金大外籍生演唱、魔術、舞蹈、雜耍等各類型表演，主活動兩日晚上的「瘋起來!LOCAL音樂派對」特別邀請「金曲歌王翁立友」、「本土女神向蕙玲」、「甜美小公主-張羽靚」、「台語情歌天后-林珊」、「開心男團黑旋風」、「YOYO台姊姊」、「慢搖女神DJ小漾」作為晚會表演。以「吸引跨世代族群」風格實踐導入文化季，透過實質的藝文表演，打破離島文化資源缺乏的藩籬，帶動民眾文化參與，充分展現世代文化的交流。(三)美食管夠!獨家市集共計50個創意市集攤位攤商販售內容以金門地區鄉民之農特產、特色小吃、金門文創商品為主並符合環保、生態、食農教育之攤商為主，熱（熟）食、冷飲、地方特色小吃、風味餐等料理品嚐。(四)送送送!闖關好禮大放爽設計活動闖關3個關卡。增加親子互...', '金門縣政府', '無資料', '2025-03-24 00:00:00', '2025-04-20 23:59:59', '金門縣金寧鄉', 24.45142, 118.30698, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025金寧鄉石蚵文化季', `description`='金寧鄉特有的石蚵，結合觀光、生態等資源，來塑造地方產業特色．以食農教育為推廣方向，與在地蚵農合作舉辦「超頂!千人剝蚵大挑戰」，親身體驗傳統產業文化。   主活動日舉辦「激鬥!石蚵大胃王最強賽」，玩轉傳統產業以創新的活動方式看到更不一樣的產業魅力，以及大型親子活動「大放電!春日親子遊樂園」，設置多樣遊樂設施與闖關活動結合在地攤商帶來歡樂有趣的嘉年華會。活動時間、地點、內容：一、114年3月24日下午2點  活動記者發布會活動地點: 古寧頭北山出海口二、114年4月12日下午4點  (一)超頂!千人剝蚵大挑戰預定114年4月12日下午16點(配合潮汐)於北山出海口舉辦，邀集民眾遊客，共同體驗蚵民剝蚵樂趣，現場自由入座，額滿為止。。(二)free!石蚵特色料理品嘗加完「超頂!千人剝蚵大挑戰」活動之民眾，公所特別加碼贈送參與民眾每人一份蚵仔麵線，數量有限，發完為止。活動地點: 古寧頭北山出海口三、114年4月19~20日下午2點~晚上9點  (一)大放電!春日親子遊樂園活動以親子遊戲嘉年華為特色，以兒童遊樂園型式，目的吸引更多的親子家庭同樂。計有刺激海盜船、飄移飛車、旋轉飛機、旋轉小火車、充氣城堡、夜市遊戲機檯等及許多親子互動遊戲，營造親子共融歡樂氣氛。(二)瘋起來!LOCAL音樂派對本次特別著重「吸引跨世代族群」的觀念，除在地社區文化團隊、金大外籍生演唱、魔術、舞蹈、雜耍等各類型表演，主活動兩日晚上的「瘋起來!LOCAL音樂派對」特別邀請「金曲歌王翁立友」、「本土女神向蕙玲」、「甜美小公主-張羽靚」、「台語情歌天后-林珊」、「開心男團黑旋風」、「YOYO台姊姊」、「慢搖女神DJ小漾」作為晚會表演。以「吸引跨世代族群」風格實踐導入文化季，透過實質的藝文表演，打破離島文化資源缺乏的藩籬，帶動民眾文化參與，充分展現世代文化的交流。(三)美食管夠!獨家市集共計50個創意市集攤位攤商販售內容以金門地區鄉民之農特產、特色小吃、金門文創商品為主並符合環保、生態、食農教育之攤商為主，熱（熟）食、冷飲、地方特色小吃、風味餐等料理品嚐。(四)送送送!闖關好禮大放爽設計活動闖關3個關卡。增加親子互...', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-03-24 00:00:00', `end_date`='2025-04-20 23:59:59', `location`='金門縣金寧鄉', `latitude`=24.45142, `longitude`=118.30698, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003916', '烈嶼親子童玩節', '烈嶼鄉公所於113年辦理首場離島街道遊戲，吸引許多親子參加，並頗獲好評，114年擬擴大辦理街道遊戲，希望能夠讓家長與孩子們在遊戲中一起學習、解決問題，共同成長。主辦單位：烈嶼鄉公所活動時間：6月活動地點：金門縣烈嶼鄉連絡電話：羅小姐 082-364510各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-06-01 00:00:00', '2025-06-30 23:59:59', '金門縣烈嶼鄉', 24.42886, 118.24755, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='烈嶼親子童玩節', `description`='烈嶼鄉公所於113年辦理首場離島街道遊戲，吸引許多親子參加，並頗獲好評，114年擬擴大辦理街道遊戲，希望能夠讓家長與孩子們在遊戲中一起學習、解決問題，共同成長。主辦單位：烈嶼鄉公所活動時間：6月活動地點：金門縣烈嶼鄉連絡電話：羅小姐 082-364510各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-06-01 00:00:00', `end_date`='2025-06-30 23:59:59', `location`='金門縣烈嶼鄉', `latitude`=24.42886, `longitude`=118.24755, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003917', '浦揪文創市集', '結合後浦十六藝文特區文創商家並邀請台金特色攤位進駐，於每季季末提供旅客及在地金門鄉親體驗及挖寶的樂趣。主辦單位：金城鎮公所觀光課活動時間：第一場 6/6-6/8第二場 9/12-9/14第三場 12/5-12/7活動地點：後浦十六藝文特區連絡電話：王小姐 082-325057各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-06-06 00:00:00', '2025-12-07 23:59:59', '金門縣金城鎮', 24.43289, 118.31687, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='浦揪文創市集', `description`='結合後浦十六藝文特區文創商家並邀請台金特色攤位進駐，於每季季末提供旅客及在地金門鄉親體驗及挖寶的樂趣。主辦單位：金城鎮公所觀光課活動時間：第一場 6/6-6/8第二場 9/12-9/14第三場 12/5-12/7活動地點：後浦十六藝文特區連絡電話：王小姐 082-325057各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-06-06 00:00:00', `end_date`='2025-12-07 23:59:59', `location`='金門縣金城鎮', `latitude`=24.43289, `longitude`=118.31687, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003918', '金門海上長泳暨金廈泳渡', '2025金門海上長泳即將邁向第22屆，結合在地美食、醇酒，主打友善、戰地、閩南、僑鄉為特色，打造優質旅遊休閒體育賽事，活動地點於習山湖海灣，海天一色的優美風景廣受泳士們好評。金廈泳渡至今仍是唯一由兩岸官方主辦的運動賽會，不僅海水清澈遼闊，沿途景觀更是優美，加上公開水域讓活動具有挑戰性，來參與的泳者均能享受乘風破浪的感覺。主辦單位：金門縣政府教育處活動時間：7月26日、27日活動地點：金廈泳渡：廈門椰風寨至烈嶼鄉雙口海域金門海上長泳：習山湖海灣連絡電話：林小姐 082-318823#62467各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-07-26 00:00:00', '2025-07-27 23:59:59', '金門縣烈嶼鄉', 24.42466, 118.25003, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='金門海上長泳暨金廈泳渡', `description`='2025金門海上長泳即將邁向第22屆，結合在地美食、醇酒，主打友善、戰地、閩南、僑鄉為特色，打造優質旅遊休閒體育賽事，活動地點於習山湖海灣，海天一色的優美風景廣受泳士們好評。金廈泳渡至今仍是唯一由兩岸官方主辦的運動賽會，不僅海水清澈遼闊，沿途景觀更是優美，加上公開水域讓活動具有挑戰性，來參與的泳者均能享受乘風破浪的感覺。主辦單位：金門縣政府教育處活動時間：7月26日、27日活動地點：金廈泳渡：廈門椰風寨至烈嶼鄉雙口海域金門海上長泳：習山湖海灣連絡電話：林小姐 082-318823#62467各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-07-26 00:00:00', `end_date`='2025-07-27 23:59:59', `location`='金門縣烈嶼鄉', `latitude`=24.42466, `longitude`=118.25003, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003919', '2025夏日金寧嗨FUN玩水節', '以金寧鄉后湖海濱公園週邊公共空間作為活動場地，布置充滿歡樂與夢幻、浪漫的親子戲水氛圍，以不同類型的親水遊具設施呈現，吸引來金遊客與一整片海灘互動拍照、打卡，戲水遊玩，藉由網路傳播及遊客口耳相傳，促進地方觀光產業的發展。主辦單位：金寧鄉公所活動時間：預計7月19日至7月27日 16:00-21:00活動地點：金寧鄉后湖海濱公園連絡電話：陳先生 082-325610各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-07-19 00:00:00', '2025-07-27 23:59:59', '金門縣金寧鄉', 24.4159, 118.34607, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025夏日金寧嗨FUN玩水節', `description`='以金寧鄉后湖海濱公園週邊公共空間作為活動場地，布置充滿歡樂與夢幻、浪漫的親子戲水氛圍，以不同類型的親水遊具設施呈現，吸引來金遊客與一整片海灘互動拍照、打卡，戲水遊玩，藉由網路傳播及遊客口耳相傳，促進地方觀光產業的發展。主辦單位：金寧鄉公所活動時間：預計7月19日至7月27日 16:00-21:00活動地點：金寧鄉后湖海濱公園連絡電話：陳先生 082-325610各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-07-19 00:00:00', `end_date`='2025-07-27 23:59:59', `location`='金門縣金寧鄉', `latitude`=24.4159, `longitude`=118.34607, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003920', '金門親子嘉年華', '親子體驗遊以公部門結合地方業者共同投入參與親子旅遊，以創新旅遊亮點，共同推出多種體驗遊程，以強化深度體驗活動，協助在地旅遊業者產品數位轉型，加強金門的國際行銷及深度體驗活動，讓觀光客感受金門獨有的生態特色，塑造觀光新亮點。主辦單位：金門縣政府觀光處活動時間：114年7月1日-8月31日主活動日：暫定7月5日活動地點：大小金門連絡電話：許小姐 082-318823各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-07-01 00:00:00', '2025-08-31 23:59:59', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='金門親子嘉年華', `description`='親子體驗遊以公部門結合地方業者共同投入參與親子旅遊，以創新旅遊亮點，共同推出多種體驗遊程，以強化深度體驗活動，協助在地旅遊業者產品數位轉型，加強金門的國際行銷及深度體驗活動，讓觀光客感受金門獨有的生態特色，塑造觀光新亮點。主辦單位：金門縣政府觀光處活動時間：114年7月1日-8月31日主活動日：暫定7月5日活動地點：大小金門連絡電話：許小姐 082-318823各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-07-01 00:00:00', `end_date`='2025-08-31 23:59:59', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003921', '後浦十六藝文特區音樂季', '邀請台金演唱者在後浦16藝文特區舉辦音樂季，享受輕鬆的夏夜風情，唯美、浪漫的音樂勢必帶給聆賞者豐富的聽覺與視覺饗宴。活動時間：1.7/11-7/122.7/18-7/193.7/25-7/264.8/1-8/25.8/8/-8/96.8/15-8/167.8/22-8/238.8/29-8/30活動地點：後浦16藝文特區主辦單位：金城鎮公所觀光課連絡電話：王小姐 082-325057各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-07-11 00:00:00', '2025-08-30 23:59:59', '金門縣金城鎮', 24.43289, 118.31687, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='後浦十六藝文特區音樂季', `description`='邀請台金演唱者在後浦16藝文特區舉辦音樂季，享受輕鬆的夏夜風情，唯美、浪漫的音樂勢必帶給聆賞者豐富的聽覺與視覺饗宴。活動時間：1.7/11-7/122.7/18-7/193.7/25-7/264.8/1-8/25.8/8/-8/96.8/15-8/167.8/22-8/238.8/29-8/30活動地點：後浦16藝文特區主辦單位：金城鎮公所觀光課連絡電話：王小姐 082-325057各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-07-11 00:00:00', `end_date`='2025-08-30 23:59:59', `location`='金門縣金城鎮', `latitude`=24.43289, `longitude`=118.31687, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003922', '114年度台灣原住民豐年節慶活動', '為凝聚本縣臺灣原住民族族人，及延續原住民族文化，特辦理此項活動。仿造本島辦理原住民相關文化活動之形式，以「原住民傳統技藝競賽」、「傳統歌舞」展縣原民特有文化。主辦單位：金門縣政府民政處活動時間：3-5月活動地點：金門縣烈嶼鄉連絡電話：全先生 082-318823#62116各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-08-02 00:00:00', '2025-08-02 23:59:59', '金門縣金城鎮', 24.42736, 118.31762, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度台灣原住民豐年節慶活動', `description`='為凝聚本縣臺灣原住民族族人，及延續原住民族文化，特辦理此項活動。仿造本島辦理原住民相關文化活動之形式，以「原住民傳統技藝競賽」、「傳統歌舞」展縣原民特有文化。主辦單位：金門縣政府民政處活動時間：3-5月活動地點：金門縣烈嶼鄉連絡電話：全先生 082-318823#62116各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-08-02 00:00:00', `end_date`='2025-08-02 23:59:59', `location`='金門縣金城鎮', `latitude`=24.42736, `longitude`=118.31762, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003923', '金門中秋博狀元餅', '博狀元餅俗稱「博餅」，以擲骰子方式進行，是盛行於閩南地區特有的民俗文化活動。相傳是出生金門洪門港(后豐港)的鄭成功營中大將洪旭，在鄭成功領軍進攻金陵時，為穩定留守廈門的官兵軍心，並撫慰思鄉情緒，發明博狀元餅遊戲，讓官兵在中秋節玩上一把，而在廈門、泉州、金門等地流傳，成為一種中秋佳節應景的民俗娛樂活動。博餅活動迄今流傳已超過300年，金門戰地政務時期一度絕跡，為傳承民俗、發展觀光，所以每年舉辦「中秋博狀元餅」活動。活動於2012年入選「台灣觀光年曆」、是國際型觀光活動!主辦單位：金門縣政府觀光處活動時間：114年9月1日-10月6日活動地點：大小金門連絡電話：082-318823各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-09-01 00:00:00', '2025-10-06 23:59:59', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='金門中秋博狀元餅', `description`='博狀元餅俗稱「博餅」，以擲骰子方式進行，是盛行於閩南地區特有的民俗文化活動。相傳是出生金門洪門港(后豐港)的鄭成功營中大將洪旭，在鄭成功領軍進攻金陵時，為穩定留守廈門的官兵軍心，並撫慰思鄉情緒，發明博狀元餅遊戲，讓官兵在中秋節玩上一把，而在廈門、泉州、金門等地流傳，成為一種中秋佳節應景的民俗娛樂活動。博餅活動迄今流傳已超過300年，金門戰地政務時期一度絕跡，為傳承民俗、發展觀光，所以每年舉辦「中秋博狀元餅」活動。活動於2012年入選「台灣觀光年曆」、是國際型觀光活動!主辦單位：金門縣政府觀光處活動時間：114年9月1日-10月6日活動地點：大小金門連絡電話：082-318823各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-09-01 00:00:00', `end_date`='2025-10-06 23:59:59', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003924', '高粱老街風獅爺文化季', '以金沙在地風獅爺特色創新發展，傳承歷史，從體驗高粱田、聆聽老街文化故事出發，貼近人心，親近金門特色，讓風獅爺重新再現，並結合地方特色消費，促進文化觀光人潮。主辦單位：金沙鎮公所活動時間：9-10月活動地點：金沙鎮連絡電話：陳小姐 082-352150各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-09-01 00:00:00', '2025-10-31 23:59:59', '金門縣金沙鎮', 24.48893, 118.41298, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高粱老街風獅爺文化季', `description`='以金沙在地風獅爺特色創新發展，傳承歷史，從體驗高粱田、聆聽老街文化故事出發，貼近人心，親近金門特色，讓風獅爺重新再現，並結合地方特色消費，促進文化觀光人潮。主辦單位：金沙鎮公所活動時間：9-10月活動地點：金沙鎮連絡電話：陳小姐 082-352150各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-09-01 00:00:00', `end_date`='2025-10-31 23:59:59', `location`='金門縣金沙鎮', `latitude`=24.48893, `longitude`=118.41298, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
