INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003926', '窯火與戰火 金門陶與瓷工藝文化特展', '以金門陶瓷產業發展與故事為主軸，呈現陶瓷與在地風土、歷史及民眾生活的關係。主辦單位：金門縣文化園區管理所活動時間：3-5月活動地點：金門歷史民俗博物館連絡電話：洪小姐 082-351030#202各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2024-10-22 00:00:00', '2025-02-16 23:59:59', '金門縣金沙鎮', 24.49928, 118.4034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='窯火與戰火 金門陶與瓷工藝文化特展', `description`='以金門陶瓷產業發展與故事為主軸，呈現陶瓷與在地風土、歷史及民眾生活的關係。主辦單位：金門縣文化園區管理所活動時間：3-5月活動地點：金門歷史民俗博物館連絡電話：洪小姐 082-351030#202各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2024-10-22 00:00:00', `end_date`='2025-02-16 23:59:59', `location`='金門縣金沙鎮', `latitude`=24.49928, `longitude`=118.4034, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003927', '金門坑道音樂節', '翟山坑道為花崗岩開挖而成，成為一個天然的音箱，還有海浪自然的聲音。因此我們特別利用坑道的水道做為表演舞臺場域，舉辦金門坑 道音樂節表演，推廣軍事史蹟活化再利用觀念，並以軟性的音樂宣揚 和平理念。主辦單位：內政部國家公園署金門國家公園管理處活動時間：暫訂114年10月活動地點：翟山坑道連絡電話：解說教育科蔡先生 082-313185各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-10-01 00:00:00', '2025-10-31 23:59:59', '金門縣金城鎮', 24.39003, 118.31995, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='金門坑道音樂節', `description`='翟山坑道為花崗岩開挖而成，成為一個天然的音箱，還有海浪自然的聲音。因此我們特別利用坑道的水道做為表演舞臺場域，舉辦金門坑 道音樂節表演，推廣軍事史蹟活化再利用觀念，並以軟性的音樂宣揚 和平理念。主辦單位：內政部國家公園署金門國家公園管理處活動時間：暫訂114年10月活動地點：翟山坑道連絡電話：解說教育科蔡先生 082-313185各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-10-01 00:00:00', `end_date`='2025-10-31 23:59:59', `location`='金門縣金城鎮', `latitude`=24.39003, `longitude`=118.31995, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003928', '金門老兵召集令', '即使時光飛逝、場景不再，金門依然是老兵記憶裡，自己青春歲月拋灑過的家園。謹以感恩的心，歡迎老兵返金走走，共話桑麻。主辦單位：金門縣政府觀光處活動時間：10月1日-12月15日活動地點：金門連絡電話：082-318823各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-10-01 00:00:00', '2025-12-15 23:59:59', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='金門老兵召集令', `description`='即使時光飛逝、場景不再，金門依然是老兵記憶裡，自己青春歲月拋灑過的家園。謹以感恩的心，歡迎老兵返金走走，共話桑麻。主辦單位：金門縣政府觀光處活動時間：10月1日-12月15日活動地點：金門連絡電話：082-318823各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-10-01 00:00:00', `end_date`='2025-12-15 23:59:59', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003929', '萬聖節活動', '藉由主題性活動的舉辦，活絡後浦商圈整體產業發展並透過變裝踩街遊行及走秀比賽活動，暫時跳脫現實生活的枷鎖，激發創意和想像力，帶給後浦城區年輕活力新朝氣。主辦單位：金城鎮公所觀光課活動時間：10月25日 星期六活動地點：金城鎮連絡電話：王小姐 082-325057各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-10-25 00:00:00', '2025-10-25 23:59:59', '金門縣金城鎮', 24.43206, 118.31551, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='萬聖節活動', `description`='藉由主題性活動的舉辦，活絡後浦商圈整體產業發展並透過變裝踩街遊行及走秀比賽活動，暫時跳脫現實生活的枷鎖，激發創意和想像力，帶給後浦城區年輕活力新朝氣。主辦單位：金城鎮公所觀光課活動時間：10月25日 星期六活動地點：金城鎮連絡電話：王小姐 082-325057各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-10-25 00:00:00', `end_date`='2025-10-25 23:59:59', `location`='金門縣金城鎮', `latitude`=24.43206, `longitude`=118.31551, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003930', '2025 金寧鄉鄉村市集', '鄉村市集派對目標客群以在地親子家庭為主，由公部門建立一個平台，提供販售、宣導及親子同樂的場域，冀望能帶動經濟文化及社區的永續發展，並提供一個溫馨有趣的兒童園地讓民眾於假日時能同享天倫一同放鬆玩樂。主辦單位：金寧鄉公所活動時間：11月1日至11月2日 10:00-17:00活動地點：金寧鄉古寧頭和平紀念園區連絡電話：薛小姐 082-325610各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-11-01 00:00:00', '2025-11-30 23:59:59', '金門縣金寧鄉', 24.47603, 118.31649, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 金寧鄉鄉村市集', `description`='鄉村市集派對目標客群以在地親子家庭為主，由公部門建立一個平台，提供販售、宣導及親子同樂的場域，冀望能帶動經濟文化及社區的永續發展，並提供一個溫馨有趣的兒童園地讓民眾於假日時能同享天倫一同放鬆玩樂。主辦單位：金寧鄉公所活動時間：11月1日至11月2日 10:00-17:00活動地點：金寧鄉古寧頭和平紀念園區連絡電話：薛小姐 082-325610各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-11-01 00:00:00', `end_date`='2025-11-30 23:59:59', `location`='金門縣金寧鄉', `latitude`=24.47603, `longitude`=118.31649, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003931', 'HOPE草地野餐音樂節', '串聯「野餐」、「餐車」和「音樂」三大元素，向鄉親及觀光客舉辦「Hope草地野餐音樂節」，引進台灣知名的特色餐車打造特色市集，除了延伸這股熱潮，優化場域運用外，更期盼可以發展為居民日常休閒樣態，成為金城鎮的常態化特色活動，藉茲彰顯後浦經典小鎮、慢活樂遊的獨特魅力；另外，還希望藉由寬闊的草地、清新的空氣、迷人的音樂表達身處自由民主之境、遠離疫病的「希望(Hope)」意涵，為所有為疫情所苦及奮戰不懈的人們加油打氣！主辦單位：金城鎮公所觀光課活動時間：11月8至11月9日活動地點：莒光公園連絡電話：王小姐 082-325057各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-11-08 00:00:00', '2025-11-09 23:59:59', '金門縣金城鎮', 24.42649, 118.31786, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='HOPE草地野餐音樂節', `description`='串聯「野餐」、「餐車」和「音樂」三大元素，向鄉親及觀光客舉辦「Hope草地野餐音樂節」，引進台灣知名的特色餐車打造特色市集，除了延伸這股熱潮，優化場域運用外，更期盼可以發展為居民日常休閒樣態，成為金城鎮的常態化特色活動，藉茲彰顯後浦經典小鎮、慢活樂遊的獨特魅力；另外，還希望藉由寬闊的草地、清新的空氣、迷人的音樂表達身處自由民主之境、遠離疫病的「希望(Hope)」意涵，為所有為疫情所苦及奮戰不懈的人們加油打氣！主辦單位：金城鎮公所觀光課活動時間：11月8至11月9日活動地點：莒光公園連絡電話：王小姐 082-325057各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-11-08 00:00:00', `end_date`='2025-11-09 23:59:59', `location`='金門縣金城鎮', `latitude`=24.42649, `longitude`=118.31786, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003932', '第六屆烈嶼定向越野錦標賽暨樂遊健走活動', '參加者繳納200元報名費即可參賽，積分排名，參賽完成者均發完賽證明與紀念品乙份。主辦單位：烈嶼鄉公所活動時間：12月活動地點：金門縣烈嶼鄉連絡電話：羅小姐 082-364510各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-12-01 00:00:00', '2025-12-31 23:59:59', '金門縣烈嶼鄉', 24.42886, 118.24755, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第六屆烈嶼定向越野錦標賽暨樂遊健走活動', `description`='參加者繳納200元報名費即可參賽，積分排名，參賽完成者均發完賽證明與紀念品乙份。主辦單位：烈嶼鄉公所活動時間：12月活動地點：金門縣烈嶼鄉連絡電話：羅小姐 082-364510各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-12-01 00:00:00', `end_date`='2025-12-31 23:59:59', `location`='金門縣烈嶼鄉', `latitude`=24.42886, `longitude`=118.24755, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003933', '2025金沙歡樂聖誕x時光繁星假日市集', '金沙歡樂聖誕x時光繁星假日市集」活動，為增加活動的豐富性與串聯性，以金沙鎮在地特色及聖誕節為主軸，規劃沙美商圈燈飾佈景，營造過節的歡樂氛圍，透過此節慶，融合本土市區樣貌，打造藝術美學的沙美市區，活躍沙美街道。主辦單位：金沙鎮公所活動時間：預計114年12月13日(週六)、14日(週日)等2日活動地點：金沙鎮連絡電話：陳小姐 082-352150各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-12-13 00:00:00', '2025-12-14 23:59:59', '金門縣金沙鎮', 24.48891, 118.41296, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025金沙歡樂聖誕x時光繁星假日市集', `description`='金沙歡樂聖誕x時光繁星假日市集」活動，為增加活動的豐富性與串聯性，以金沙鎮在地特色及聖誕節為主軸，規劃沙美商圈燈飾佈景，營造過節的歡樂氛圍，透過此節慶，融合本土市區樣貌，打造藝術美學的沙美市區，活躍沙美街道。主辦單位：金沙鎮公所活動時間：預計114年12月13日(週六)、14日(週日)等2日活動地點：金沙鎮連絡電話：陳小姐 082-352150各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-12-13 00:00:00', `end_date`='2025-12-14 23:59:59', `location`='金門縣金沙鎮', `latitude`=24.48891, `longitude`=118.41296, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003934', '2025金門跨年晚會', '2025金門跨年晚會將於12月31日（週二）晚間7時在金湖鎮新市里籃球場（山外車站對面）熱鬧登場，金門跨年晚會以「樂福金門、閃耀迎新」為主題，以創新科技結合在地文化，打造一場專屬於金門的歡樂跨年盛宴。這次跨年晚會卡司包含金曲歌王荒山亮、民歌教父陳宏銘、八點檔戲劇女神王晴、歌壇實力唱將伍浩哲、億萬點閱率神曲歌姬林芯儀、「明日之星」出身的新世代唱將郭忠祐、台語歌壇小天后蔡家蓁、城市唱作才女吳汶芳、Urban Lady都會女聲林希子，以及音樂才女Bettii杯緹，另外還有兒童界偶像泡芙姐姐、綜藝小天后張文綺、當紅啦啦隊女神宜芳，都將聯袂參與。跨年倒數時刻的無人機群飛展演秀是此次晚會的核心亮點，數百架無人機群飛展演，在金門的夜空中描繪出多個金門文化元素符號，同時以炫目的燈光編排呈現「樂福金門」的主題字樣。無人機群飛展演除了有金門在地重要代表符號的表現，另一重點畫面則是「飛去金門話」的創意展示，無人機將透過燈光拼出推廣金門話的Slogan，讓現場觀眾在視覺的體驗中感受到金門話的魅力。主辦單位於會場周邊規劃了臨時停車區（如圖），包含借用市港路重劃區的空地做為汽車臨停區（入口請從赤東路段進入）；另借用金湖國小進入大門左側之空地做為機車臨停區，請汽機車用路人遵照現場義交或工作人員引導停車。跨年晚會預計於凌晨零時30分結束之後，主辦單位安排三輛接駁車，預計元旦凌晨零時30分發車，由山外車站出發依路線前往金城車站、金沙車站、烈嶼（小金門）車站，歡迎鄉親多加利用。活動地點：金湖鎮新市里籃球場(山外車站對面)主辦單位：金門縣文化局活動日期：12月31日', '金門縣政府', '無資料', '2024-12-31 19:00:00', '2025-01-01 00:30:00', '金門縣金湖鎮', 24.44194, 118.4145, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025金門跨年晚會', `description`='2025金門跨年晚會將於12月31日（週二）晚間7時在金湖鎮新市里籃球場（山外車站對面）熱鬧登場，金門跨年晚會以「樂福金門、閃耀迎新」為主題，以創新科技結合在地文化，打造一場專屬於金門的歡樂跨年盛宴。這次跨年晚會卡司包含金曲歌王荒山亮、民歌教父陳宏銘、八點檔戲劇女神王晴、歌壇實力唱將伍浩哲、億萬點閱率神曲歌姬林芯儀、「明日之星」出身的新世代唱將郭忠祐、台語歌壇小天后蔡家蓁、城市唱作才女吳汶芳、Urban Lady都會女聲林希子，以及音樂才女Bettii杯緹，另外還有兒童界偶像泡芙姐姐、綜藝小天后張文綺、當紅啦啦隊女神宜芳，都將聯袂參與。跨年倒數時刻的無人機群飛展演秀是此次晚會的核心亮點，數百架無人機群飛展演，在金門的夜空中描繪出多個金門文化元素符號，同時以炫目的燈光編排呈現「樂福金門」的主題字樣。無人機群飛展演除了有金門在地重要代表符號的表現，另一重點畫面則是「飛去金門話」的創意展示，無人機將透過燈光拼出推廣金門話的Slogan，讓現場觀眾在視覺的體驗中感受到金門話的魅力。主辦單位於會場周邊規劃了臨時停車區（如圖），包含借用市港路重劃區的空地做為汽車臨停區（入口請從赤東路段進入）；另借用金湖國小進入大門左側之空地做為機車臨停區，請汽機車用路人遵照現場義交或工作人員引導停車。跨年晚會預計於凌晨零時30分結束之後，主辦單位安排三輛接駁車，預計元旦凌晨零時30分發車，由山外車站出發依路線前往金城車站、金沙車站、烈嶼（小金門）車站，歡迎鄉親多加利用。活動地點：金湖鎮新市里籃球場(山外車站對面)主辦單位：金門縣文化局活動日期：12月31日', `organizer`='金門縣政府', `address`='無資料', `start_date`='2024-12-31 19:00:00', `end_date`='2025-01-01 00:30:00', `location`='金門縣金湖鎮', `latitude`=24.44194, `longitude`=118.4145, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003941', '博物館蛇來運轉迎新春', '農曆新年為華人最富傳統特色之節日，更是在外金門人返鄉、回娘家等重要民俗慶典。因應金門春節及遊客人潮眾多，特於年節期間辦理春節系列活動，串聯博物館常設展、特展與互動表演等，全面營造春節喜慶氛圍，吸引返鄉過年民眾走進博物館，發揚金門傳統民俗文化。博物館迎春活動：【正月初一】蛇來運轉點燈迎春（09:00起開始贈送，發完為止）【正月初二】蛇年回娘家：好禮大放送（09:00起開始贈送，發完為止）【正月初三】傀儡戲揭春表演（第一場10:40，第二場11:30）【正月初四】蛇麼好東東：打卡按讚抽盲盒（09:00開始）常態活動（初一至元宵）博物館猜燈謎抽好禮蛇年祈福．好運年年衍派流芳．祈福點燈博物館迎春特展「開枝散葉－金門的移動之民」特展：展出「番客箱」、「印尼歸僑陳天沛書信」及「閩南文化的日常與非日常」等珍貴展件，呈現金門人的遷徙軌跡並描繪僑居地生活的點滴，探討南洋華人與原鄉之間的深厚情感，讓參觀者能夠從不同角度完整理解金門移民歷史與文化故事。「窯火與戰火～金門的陶與瓷工藝之美」特展：「窯火與戰火」交融出金門陶瓷歷史的演變，也呈現金門陶瓷深厚文化底蘊與工藝之美。中華民國第40屆版印年畫「蛇彩繽紛－蛇年年畫特展」：展出多件由國立臺灣美術館主辦之「中華民國第40屆版印年畫」精彩得獎作品。第40屆版印年畫以「蛇彩繽紛」為題，承接歷屆版畫創作者的活力與成果，期迎來更具生機、在地特色的年畫藝術創作及年節氛圍。「胡璉將軍文化特展」：介紹胡璉將軍的生平史蹟，包括軍旅生涯、駐越大使時期與晚年生活等，也展出多件博物館庫房典藏的實體文物，帶領民眾一起認識有金門恩主公之名的胡璉將軍。更多博物館常設展介紹請見粉絲專頁主辦單位：金門縣文化園區管理所活動時間：2025年1月29日-2025年2月12日活動地點：文化園區金門歷史民俗博物館連絡電話：082-351030#606【金門歷史民俗博物館　參觀資訊】●開放時間：週二至週日，09:00-17:00●休 館 日 ：每週一、農曆除夕及政府公告之天然災害停止上班日●地　　址：金門縣金沙鎮西園里文化路450巷52號（博物館位置地圖：https://reurl.cc/...', '金門縣政府', '無資料', '2025-01-29 00:00:00', '2025-02-12 23:59:59', '金門縣金沙鎮', 24.49928, 118.4034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='博物館蛇來運轉迎新春', `description`='農曆新年為華人最富傳統特色之節日，更是在外金門人返鄉、回娘家等重要民俗慶典。因應金門春節及遊客人潮眾多，特於年節期間辦理春節系列活動，串聯博物館常設展、特展與互動表演等，全面營造春節喜慶氛圍，吸引返鄉過年民眾走進博物館，發揚金門傳統民俗文化。博物館迎春活動：【正月初一】蛇來運轉點燈迎春（09:00起開始贈送，發完為止）【正月初二】蛇年回娘家：好禮大放送（09:00起開始贈送，發完為止）【正月初三】傀儡戲揭春表演（第一場10:40，第二場11:30）【正月初四】蛇麼好東東：打卡按讚抽盲盒（09:00開始）常態活動（初一至元宵）博物館猜燈謎抽好禮蛇年祈福．好運年年衍派流芳．祈福點燈博物館迎春特展「開枝散葉－金門的移動之民」特展：展出「番客箱」、「印尼歸僑陳天沛書信」及「閩南文化的日常與非日常」等珍貴展件，呈現金門人的遷徙軌跡並描繪僑居地生活的點滴，探討南洋華人與原鄉之間的深厚情感，讓參觀者能夠從不同角度完整理解金門移民歷史與文化故事。「窯火與戰火～金門的陶與瓷工藝之美」特展：「窯火與戰火」交融出金門陶瓷歷史的演變，也呈現金門陶瓷深厚文化底蘊與工藝之美。中華民國第40屆版印年畫「蛇彩繽紛－蛇年年畫特展」：展出多件由國立臺灣美術館主辦之「中華民國第40屆版印年畫」精彩得獎作品。第40屆版印年畫以「蛇彩繽紛」為題，承接歷屆版畫創作者的活力與成果，期迎來更具生機、在地特色的年畫藝術創作及年節氛圍。「胡璉將軍文化特展」：介紹胡璉將軍的生平史蹟，包括軍旅生涯、駐越大使時期與晚年生活等，也展出多件博物館庫房典藏的實體文物，帶領民眾一起