INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003944', '慶祝金門老兵召集令榮獲台灣活動卓越獎金質獎 加碼「抽中金馬獎籤王」活動', '參加辦法：仿老兵當年分發服務單位時，以抽籤方式決定服役地點之方式，讓老兵參與；未中獎之老兵偕同行親友，參照金門中秋博狀元餅方式，得參與一次博彩，取得新市之老兵特約店家彩品    1. 金馬獎籤王：普天同慶金門老兵獲得金質獎，活動期間返金旅遊之已退役之台、澎、金、馬等地老兵。    2. 博彩：未抽中金馬獎籤王之老兵及偕同返金旅遊之親友。(https://kinmen.travel/zh-tw/news/details/3938) (一) 「跟著金門馬一起跑」：114年元旦起至1月23日止，每日08:30-12:00、13:30-17:30。 (二) 「在金門與愛相遇」：114年2月3日起2月14日止，每日08:30-12:00、13:30-17:30。主辦單位：金門縣政府觀光處活動時間：跟著金門馬一起跑：114年元旦起至1月23日止在金門與愛相遇：114年2月3日起2月14日止每日08:30-12:00、13:30-17:30。活動地點：新市256連絡電話：宋小姐 082-318823各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-02-03 00:00:00', '2025-02-14 23:59:59', '金門縣金湖鎮', 24.44052, 118.41635, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='慶祝金門老兵召集令榮獲台灣活動卓越獎金質獎 加碼「抽中金馬獎籤王」活動', `description`='參加辦法：仿老兵當年分發服務單位時，以抽籤方式決定服役地點之方式，讓老兵參與；未中獎之老兵偕同行親友，參照金門中秋博狀元餅方式，得參與一次博彩，取得新市之老兵特約店家彩品    1. 金馬獎籤王：普天同慶金門老兵獲得金質獎，活動期間返金旅遊之已退役之台、澎、金、馬等地老兵。    2. 博彩：未抽中金馬獎籤王之老兵及偕同返金旅遊之親友。(https://kinmen.travel/zh-tw/news/details/3938) (一) 「跟著金門馬一起跑」：114年元旦起至1月23日止，每日08:30-12:00、13:30-17:30。 (二) 「在金門與愛相遇」：114年2月3日起2月14日止，每日08:30-12:00、13:30-17:30。主辦單位：金門縣政府觀光處活動時間：跟著金門馬一起跑：114年元旦起至1月23日止在金門與愛相遇：114年2月3日起2月14日止每日08:30-12:00、13:30-17:30。活動地點：新市256連絡電話：宋小姐 082-318823各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-02-03 00:00:00', `end_date`='2025-02-14 23:59:59', `location`='金門縣金湖鎮', `latitude`=24.44052, `longitude`=118.41635, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003945', '2025點亮金湖・天燈祈福活動', '農曆新年第一個月圓之夜，象徵著春天的到來，並於2月14日(星期五)與伍德宮一同舉辦放天燈活動，與民同樂，讓民眾了解傳統文化也親身體驗。 主辦單位：金湖鎮公所活動時間：3-5月活動地點：金湖鎮新頭伍德宮連絡電話：洪小姐 082-332528各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-02-14 00:00:00', '2025-02-14 23:59:59', '金門縣金湖鎮', 24.42778, 118.42, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025點亮金湖・天燈祈福活動', `description`='農曆新年第一個月圓之夜，象徵著春天的到來，並於2月14日(星期五)與伍德宮一同舉辦放天燈活動，與民同樂，讓民眾了解傳統文化也親身體驗。 主辦單位：金湖鎮公所活動時間：3-5月活動地點：金湖鎮新頭伍德宮連絡電話：洪小姐 082-332528各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-02-14 00:00:00', `end_date`='2025-02-14 23:59:59', `location`='金門縣金湖鎮', `latitude`=24.42778, `longitude`=118.42, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003946', '2025金門元宵燈節', '金門元宵燈節活動，以在地人文、產業導入及永續發展等概念，結合科技和文化元素，打造創新、節能及永續的元宵燈節主辦單位：金門縣文化局活動時間：2月12日至2月23日活動地點：金湖鎮蘭湖連絡電話：柯先生 082-323169各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-02-12 00:00:00', '2025-02-23 23:59:59', '金門縣金湖鎮', 24.452, 118.3829, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025金門元宵燈節', `description`='金門元宵燈節活動，以在地人文、產業導入及永續發展等概念，結合科技和文化元素，打造創新、節能及永續的元宵燈節主辦單位：金門縣文化局活動時間：2月12日至2月23日活動地點：金湖鎮蘭湖連絡電話：柯先生 082-323169各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-02-12 00:00:00', `end_date`='2025-02-23 23:59:59', `location`='金門縣金湖鎮', `latitude`=24.452, `longitude`=118.3829, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003947', 'Let''s購 2025金門購物嘉年華', 'Let&#39;s購 2025金門購物嘉年華活動內容一、購物狂歡 &bull; 週週抽大獎（3/29 - 4/30）到特約商家單筆消費滿200元就能參加摸彩！週週抽獎，豪華大獎等你拿！（iPhone 16、iPad、PS5、Switch、POP MART 盲盒等&hellip;）抽獎時間：4/11、4/18、4/25、5/2越買越有機會，還能支持金門在地商家，一起讓金門更熱鬧！二、青創市集 &bull; 文創美食 &times; 音樂派對 &times; 購物狂歡地點：後浦十六藝文特區市集時間：3/29（六）15:00 - 20:303/30（日）15:00 - 19:30市集亮點：#音浪狂潮 &bull; 音樂派對（16:30開始）文創設計 X 在地美食，24家精選攤商一次逛個夠！#繽紛童樂 &bull; 氣球派對（16:00-19:00）可愛氣球免費送給大小朋友！#集章闖關 &bull; Fun玩市集，挑戰闖關任務，拿好禮！支持金門商家，品味特色美食，來這裡度過最愜意的週末！三、旅遊商圈集點活動（3/29 - 4/30）來金門旅遊，消費就能換超萌好禮！如何參加？活動預約表單  https://form.typeform.com/to/usfOrRtgStep 1：到活動表單預約登記，憑來金機票或船票換取集點卡！Step 2：到特約商家消費，公開分享打卡，集滿3點！Step 3：至服務平台兌換限量 POP MART 公仔！玩金門、逛商圈、買好物，再把超萌盲盒帶回家！主辦單位：金門縣政府產業發展處活動時間：3月29日至4月30日活動地點：金門地區連絡電話：082-318823 #62391各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-03-29 00:00:00', '2025-04-30 23:59:59', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Let''s購 2025金門購物嘉年華', `description`='Let&#39;s購 2025金門購物嘉年華活動內容一、購物狂歡 &bull; 週週抽大獎（3/29 - 4/30）到特約商家單筆消費滿200元就能參加摸彩！週週抽獎，豪華大獎等你拿！（iPhone 16、iPad、PS5、Switch、POP MART 盲盒等&hellip;）抽獎時間：4/11、4/18、4/25、5/2越買越有機會，還能支持金門在地商家，一起讓金門更熱鬧！二、青創市集 &bull; 文創美食 &times; 音樂派對 &times; 購物狂歡地點：後浦十六藝文特區市集時間：3/29（六）15:00 - 20:303/30（日）15:00 - 19:30市集亮點：#音浪狂潮 &bull; 音樂派對（16:30開始）文創設計 X 在地美食，24家精選攤商一次逛個夠！#繽紛童樂 &bull; 氣球派對（16:00-19:00）可愛氣球免費送給大小朋友！#集章闖關 &bull; Fun玩市集，挑戰闖關任務，拿好禮！支持金門商家，品味特色美食，來這裡度過最愜意的週末！三、旅遊商圈集點活動（3/29 - 4/30）來金門旅遊，消費就能換超萌好禮！如何參加？活動預約表單  https://form.typeform.com/to/usfOrRtgStep 1：到活動表單預約登記，憑來金機票或船票換取集點卡！Step 2：到特約商家消費，公開分享打卡，集滿3點！Step 3：至服務平台兌換限量 POP MART 公仔！玩金門、逛商圈、買好物，再把超萌盲盒帶回家！主辦單位：金門縣政府產業發展處活動時間：3月29日至4月30日活動地點：金門地區連絡電話：082-318823 #62391各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-30 23: