INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003949', '114年「台電智網 點亮金門」自行車活動', '自行車運動具有休閒、健康及環保等特性，為了響應全民運動、環保地球為主軸，鼓勵全民騎行自行車，邁向健康、活力人生。主辦單位：台電-塔山發電廠活動時間：5月17日活動地點：中山林自行車館前方廣場連絡電話：陳小姐 082-323053#1105各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-01-20 00:00:00', '2025-01-20 23:59:59', '金門縣金寧鄉', 24.44378, 118.35331, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年「台電智網 點亮金門」自行車活動', `description`='自行車運動具有休閒、健康及環保等特性，為了響應全民運動、環保地球為主軸，鼓勵全民騎行自行車，邁向健康、活力人生。主辦單位：台電-塔山發電廠活動時間：5月17日活動地點：中山林自行車館前方廣場連絡電話：陳小姐 082-323053#1105各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-01-20 00:00:00', `end_date`='2025-01-20 23:59:59', `location`='金門縣金寧鄉', `latitude`=24.44378, `longitude`=118.35331, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003950', '2025跑動金門', '主辦單位：金門縣政府教育處活動時間：8月9日下午活動地點：尚未公告連絡電話：王先生 082-325630#62492各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-08-09 00:00:00', '2025-08-09 23:59:59', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025跑動金門', `description`='主辦單位：金門縣政府教育處活動時間：8月9日下午活動地點：尚未公告連絡電話：王先生 082-325630#62492各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-08-09 00:00:00', `end_date`='2025-08-09 23:59:59', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003951', '海島生活節', '在夏日的海島時光裡，浸沐在海洋文化與美感藝術當中，循著海島文化軌跡，發掘美好生活可能，邀請走進新湖漁港，找到屬於你的海洋體驗樂園！為推廣金門海洋之文化，金門海島學校將於7月1日至8月31日特別舉辦「金門海島生活節」，透過在地海島生活的呈現，展示金門海島學校所發掘之海洋文化的各種面貌，將以兩大系列活動「海島漂浪計劃」戶外藝術主題展與海島生活節系列課程，讓更多人認識金門的海洋文化及生態。主辦單位：金門區漁會活動時間：7月1日至8月31日活動地點：金門海島學校（新湖漁港）連絡電話：黃先生 082-333626#221各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-07-01 00:00:00', '2025-08-31 23:59:59', '金門縣金湖鎮', 24.43189, 118.40978, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='海島生活節', `description`='在夏日的海島時光裡，浸沐在海洋文化與美感藝術當中，循著海島文化軌跡，發掘美好生活可能，邀請走進新湖漁港，找到屬於你的海洋體驗樂園！為推廣金門海洋之文化，金門海島學校將於7月1日至8月31日特別舉辦「金門海島生活節」，透過在地海島生活的呈現，展示金門海島學校所發掘之海洋文化的各種面貌，將以兩大系列活動「海島漂浪計劃」戶外藝術主題展與海島生活節系列課程，讓更多人認識金門的海洋文化及生態。主辦單位：金門區漁會活動時間：7月1日至8月31日活動地點：金門海島學校（新湖漁港）連絡電話：黃先生 082-333626#221各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-07-01 00:00:00', `end_date`='2025-08-31 23:59:59', `location`='金門縣金湖鎮', `latitude`=24.43189, `longitude`=118.40978, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003952', '2025金湖海灘花蛤季', '藉由金湖花蛤（俗稱：沙ㄙㄨㄟˋ）季的開鑼，讓民眾有機會能親身體驗屬於金湖鎮特有的海洋資源及豐富珍貴的自然生態，藉由沙灘活動的開發與推展，讓民眾能在炎炎夏日裡，自由的在沙灘遊樂、嘻戲，充分享受大自然之美，兼具宣達海洋生態的保育觀念，讓民眾在寓教於樂的體驗過程中，身心達到徹底的解放。主辦單位：金湖鎮公所活動時間：7月18日至7月20日活動地點：82據點連絡電話：陳小姐 082332528 #282各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-07-18 00:00:00', '2025-07-20 23:59:59', '金門縣金湖鎮', 24.42486, 118.42767, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025金湖海灘花蛤季', `description`='藉由金湖花蛤（俗稱：沙ㄙㄨㄟˋ）季的開鑼，讓民眾有機會能親身體驗屬於金湖鎮特有的海洋資源及豐富珍貴的自然生態，藉由沙灘活動的開發與推展，讓民眾能在炎炎夏日裡，自由的在沙灘遊樂、嘻戲，充分享受大自然之美，兼具宣達海洋生態的保育觀念，讓民眾在寓教於樂的體驗過程中，身心達到徹底的解放。主辦單位：金湖鎮公所活動時間：7月18日至7月20日活動地點：82據點連絡電話：陳小姐 082332528 #282各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-07-18 00:00:00', `end_date`='2025-07-20 23:59:59', `location`='金門縣金湖鎮', `latitude`=24.42486, `longitude`=118.42767, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
