INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003954', '台灣觀光100亮點捲動國旅方案─2025「王師返金‧榮耀金門」軍旅體驗活動', '(一)「獅山砲光耀海珠」砲兵體驗活動114年8月30日(六)、9月13日(六)(暫定)以觀光亮點景點─民俗文化村及獅山砲陣地為主要活動地點，參觀砲操表演及參與砲兵體驗，導覽民俗文化村，活動包含景點歷史介紹、軍事據點講解、軍事設備操作解說及體驗說明等。(二)「珠江月夜之莒光行」行軍體驗活動114年9月27日(六)、10月18日(六)(暫定)以觀光亮點景點─建功嶼及莒光樓為主要活動地點，體驗行軍，活動包含景點歷史介紹、軍事據點認識與行軍體驗說明等。(三)「民防戰鬥守經武」民防隊戰鬥體驗活動114年11月1日(六)、11月15日(六)(暫定)以觀光亮點景點─ 經武酒窖及太武山為主要活動地點，體驗金門兵及導覽經武酒窖微醺之旅。 主辦單位：金門縣政府觀光處活動時間：8月30日至11月15日活動地點：台灣觀光100亮點之建功嶼、莒光樓、經武酒窖、山后民俗文化村及其周邊景點連絡電話：魏小姐 082-318823 #62791各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-08-30 00:00:00', '2025-11-15 23:59:59', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台灣觀光100亮點捲動國旅方案─2025「王師返金‧榮耀金門」軍旅體驗活動', `description`='(一)「獅山砲光耀海珠」砲兵體驗活動114年8月30日(六)、9月13日(六)(暫定)以觀光亮點景點─民俗文化村及獅山砲陣地為主要活動地點，參觀砲操表演及參與砲兵體驗，導覽民俗文化村，活動包含景點歷史介紹、軍事據點講解、軍事設備操作解說及體驗說明等。(二)「珠江月夜之莒光行」行軍體驗活動114年9月27日(六)、10月18日(六)(暫定)以觀光亮點景點─建功嶼及莒光樓為主要活動地點，體驗行軍，活動包含景點歷史介紹、軍事據點認識與行軍體驗說明等。(三)「民防戰鬥守經武」民防隊戰鬥體驗活動114年11月1日(六)、11月15日(六)(暫定)以觀光亮點景點─ 經武酒窖及太武山為主要活動地點，體驗金門兵及導覽經武酒窖微醺之旅。 主辦單位：金門縣政府觀光處活動時間：8月30日至11月15日活動地點：台灣觀光100亮點之建功嶼、莒光樓、經武酒窖、山后民俗文化村及其周邊景點連絡電話：魏小姐 082-318823 #62791各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-08-30 00:00:00', `end_date`='2025-11-15 23:59:59', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
