INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003956', '「2025年全國古蹟日及金門古蹟日」系列活動', '依照2025年全國古蹟日主題，規劃導覽本縣古蹟景點，及傳藝表演、傳產體驗、趣味互動遊戲等系列活動，俾利提升民眾參與傳承維護珍貴文化資產工作共識。主辦單位：金門縣文化局活動時間：3月29日至4月28日活動地點：金門地區連絡電話：褚小姐 082-325643 #818各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-09-27 00:00:00', '2025-09-28 23:59:59', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「2025年全國古蹟日及金門古蹟日」系列活動', `description`='依照2025年全國古蹟日主題，規劃導覽本縣古蹟景點，及傳藝表演、傳產體驗、趣味互動遊戲等系列活動，俾利提升民眾參與傳承維護珍貴文化資產工作共識。主辦單位：金門縣文化局活動時間：3月29日至4月28日活動地點：金門地區連絡電話：褚小姐 082-325643 #818各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-09-27 00:00:00', `end_date`='2025-09-28 23:59:59', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003957', '搖擺金各演-後浦小鎮音樂祭', '藉由台灣獨立樂團之新興勢力，帶動音樂觀光新浪潮，除可優化場域運用外，讓「搖擺-金各演」音樂祭成為金城鎮夏日獨特活動，期盼吸引更多年輕族群抵金旅遊，打響金門獨立音樂祭聲量，建立金門後浦小鎮音樂祭品牌，逐步打入台灣獨立音樂祭市場，並在放鬆環境及迷人音樂的烘托下，盡情享受後浦小鎮漫遊風采，體驗後浦經典小鎮樂遊的獨特魅力，帶動觀光熱潮及延續口碑及話題。主辦單位：金城鎮公所活動時間：10月3日至10月5日活動地點：金門地區連絡電話：王小姐 082-325057各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-10-03 00:00:00', '2025-10-05 23:59:59', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='搖擺金各演-後浦小鎮音樂祭', `description`='藉由台灣獨立樂團之新興勢力，帶動音樂觀光新浪潮，除可優化場域運用外，讓「搖擺-金各演」音樂祭成為金城鎮夏日獨特活動，期盼吸引更多年輕族群抵金旅遊，打響金門獨立音樂祭聲量，建立金門後浦小鎮音樂祭品牌，逐步打入台灣獨立音樂祭市場，並在放鬆環境及迷人音樂的烘托下，盡情享受後浦小鎮漫遊風采，體驗後浦經典小鎮樂遊的獨特魅力，帶動觀光熱潮及延續口碑及話題。主辦單位：金城鎮公所活動時間：10月3日至10月5日活動地點：金門地區連絡電話：王小姐 082-325057各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-10-03 00:00:00', `end_date`='2025-10-05 23:59:59', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003958', '「光影烈嶼」攝影比賽', '結合烈嶼地區推廣觀光，藉由攝影比賽活動，增進更多遊客對烈嶼地區特色自然人文風情之發現與認同，經由照片詮釋本鄉美景，藉此活動廣羅烈嶼各角度之美並吸引遊客認識烈嶼鄉。主辦單位：金門烈嶼鄉公所活動時間：拍攝期限：114年1月1日起至114年10月31日止收件日期：114年11月1日起至114年11月17日止活動地點：金門地區連絡電話：羅小姐 082-364510各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-11-01 00:00:00', '2025-11-17 23:59:59', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「光影烈嶼」攝影比賽', `description`='結合烈嶼地區推廣觀光，藉由攝影比賽活動，增進更多遊客對烈嶼地區特色自然人文風情之發現與認同，經由照片詮釋本鄉美景，藉此活動廣羅烈嶼各角度之美並吸引遊客認識烈嶼鄉。主辦單位：金門烈嶼鄉公所活動時間：拍攝期限：114年1月1日起至114年10月31日止收件日期：114年11月1日起至114年11月17日止活動地點：金門地區連絡電話：羅小姐 082-364510各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-11-01 00:00:00', `end_date`='2025-11-17 23:59:59', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
