INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003965', '鐘金水收藏台灣文獻先賢書畫展', '鐘金水收藏台灣文獻先賢書畫展展期｜1月18日至2月5日展地｜金門縣文化局第一、三展覽場由金門文化局主辦，鐘金水先生策辦，展出112位先賢及151件的書畫作品。創作年代皆屬清代、日治及光復前時期文人雅士的畫作，得以呈現出清代民初時期多樣化與豐富性，歡迎鄉親到時前往參加觀賞。追隨筆墨的足跡，一件件作品皆是30餘年來的珍藏，每件書畫背後都有其獨特的故事和意境。收藏過程中同時蒐集研讀文人雅士的生平及歷史背景，更能夠讓人了解當時社會風貌或文化精神的視角。近年來，鐘金水兒女(齊凱.雅音)在耳濡目染之下對書畫文獻史料、文物等領域備感興趣，也逐漸被先賢書畫的魅力所吸引，將可以漸漸傳承下去欣賞台灣文獻書畫能使人培養儒雅氣質，達到振興歷史文化資產保存最具特色的表徵，更因海島型氣候因素影響長久保存不易，致使本土書畫作品正漸漸急速消失，此次策展目的，希望透過收藏展先賢書畫文獻來提供對興趣台灣美術史研究參考與佐證，同時能讓觀展者了解清代民初書畫藝術發展博大精深的意義，達到拋磚引玉的效果，啟發先賢書畫藝術的新思維和創新方向。', '金門縣政府', '無資料', '2025-01-18 08:00:00', '2025-02-05 17:30:00', '金門縣金城鎮', 24.44087, 118.32351, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鐘金水收藏台灣文獻先賢書畫展', `description`='鐘金水收藏台灣文獻先賢書畫展展期｜1月18日至2月5日展地｜金門縣文化局第一、三展覽場由金門文化局主辦，鐘金水先生策辦，展出112位先賢及151件的書畫作品。創作年代皆屬清代、日治及光復前時期文人雅士的畫作，得以呈現出清代民初時期多樣化與豐富性，歡迎鄉親到時前往參加觀賞。追隨筆墨的足跡，一件件作品皆是30餘年來的珍藏，每件書畫背後都有其獨特的故事和意境。收藏過程中同時蒐集研讀文人雅士的生平及歷史背景，更能夠讓人了解當時社會風貌或文化精神的視角。近年來，鐘金水兒女(齊凱.雅音)在耳濡目染之下對書畫文獻史料、文物等領域備感興趣，也逐漸被先賢書畫的魅力所吸引，將可以漸漸傳承下去欣賞台灣文獻書畫能使人培養儒雅氣質，達到振興歷史文化資產保存最具特色的表徵，更因海島型氣候因素影響長久保存不易，致使本土書畫作品正漸漸急速消失，此次策展目的，希望透過收藏展先賢書畫文獻來提供對興趣台灣美術史研究參考與佐證，同時能讓觀展者了解清代民初書畫藝術發展博大精深的意義，達到拋磚引玉的效果，啟發先賢書畫藝術的新思維和創新方向。', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-01-18 08:00:00', `end_date`='2025-02-05 17:30:00', `location`='金門縣金城鎮', `latitude`=24.44087, `longitude`=118.32351, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003966', '陳氏收藏閩臺先賢書畫展', '陳氏收藏閩臺先賢書畫展展期｜1月18日至2月5日展地｜金門縣文化局第二展覽場、特藏室正值本縣建縣111週年之際，由文化局主辦，陳采丰女士策辦此次閩台先賢書畫展，本次展覽品為陳采丰女史之收藏品，共計約120位書畫家、120餘組書畫作品。此次展出閩臺金先賢文獻作品難得少見，歡迎鄉親，利用春節連假走訪展廳，充充電，來一趟知性之旅。此為研究閩台美術史重要的一環，民眾可藉此認識金門及台灣早期先賢與其書畫的淵源、傳承、風格。文化局表示歡迎鄉親利用春節連假，來一趟書畫藝文之旅。這些先賢書畫家們，部分來自大陸，部分原籍金門、台灣，研究其履歷、生活、書畫的風格和內容，可幫助我們了解當時金門及台灣與中國大陸間的文化聯繫。金門及臺灣因臨近大陸，人文及地理上自然息息相關，來臺移民主要閩粵，而以福建為多。論臺灣的美術活動，除了原住民雕刻、繪畫之外，論主要美術文化依現有之文獻所載，仍以明末閩粵移民入墾，中原文化被及臺疆，始有文獻可循。臺灣漢人的美術活動，應溯自明鄭時代，三百餘年前，鄭成功來臺後，随之也有美術活動，經過清朝的經營，自然有了相當成就。至日治時期之前，臺灣的美術發展，跟明清整個大國藝術潮流一樣地，以文人風格的傳統書畫為主流。臺灣明清書法風格，共分三個時期:明鄭時代臺灣書法藝術的濫觴；清初的帖學時期；道光中葉以降的碑學加入時期；日治時代碑帖互為消長时期。這也是此次展出的重點。明清時代臺灣之文化史，實為一部「科舉史」，而科舉考試，又最重書法，書法藝術之承傳，端籍科舉文人之力達到顛峰，帖學即為代表，從諸多文人的館閣體可見。道光中葉以後的碑學加入時期，主要是以金門書家呂世宜將碑帖、金石學帶入台灣，故呂世宜有「台灣金石學之父」的雅稱。一系列書家如鄭鴻猷、鄭貽林、吳如玉、王了庵等等的書家都與呂世宜的書風傳承習習相關。臺灣明清的繪畫藝術，其畫風與中原地區乃血脈相連，當時中原受元明兩代的影響，仍舊承襲文人尚水墨寫意的畫風，所以臺灣的繪畫也就接續了這個大傳統主流。就繪畫流派而言，明清時代至光復，大部分移民來自於閩粵兩地，所以當時流行於浙閩一帶揚州八怪的畫風。難免對臺灣畫家的表現有所影響。以當時臺灣地處蠻荒...', '金門縣政府', '無資料', '2025-01-18 08:00:00', '2025-02-05 17:30:00', '金門縣金城鎮', 24.44087, 118.32351, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陳氏收藏閩臺先賢書畫展', `description`='陳氏收藏閩臺先賢書畫展展期｜1月18日至2月5日展地｜金門縣文化局第二展覽場、特藏室正值本縣建縣111週年之際，由文化局主辦，陳采丰女士策辦此次閩台先賢書畫展，本次展覽品為陳采丰女史之收藏品，共計約120位書畫家、120餘組書畫作品。此次展出閩臺金先賢文獻作品難得少見，歡迎鄉親，利用春節連假走訪展廳，充充電，來一趟知性之旅。此為研究閩台美術史重要的一環，民眾可藉此認識金門及台灣早期先賢與其書畫的淵源、傳承、風格。文化局表示歡迎鄉親利用春節連假，來一趟書畫藝文之旅。這些先賢書畫家們，部分來自大陸，部分原籍金門、台灣，研究其履歷、生活、書畫的風格和內容，可幫助我們了解當時金門及台灣與中國大陸間的文化聯繫。金門及臺灣因臨近大陸，人文及地理上自然息息相關，來臺移民主要閩粵，而以福建為多。論臺灣的美術活動，除了原住民雕刻、繪畫之外，論主要美術文化依現有之文獻所載，仍以明末閩粵移民入墾，中原文化被及臺疆，始有文獻可循。臺灣漢人的美術活動，應溯自明鄭時代，三百餘年前，鄭成功來臺後，随之也有美術活動，經過清朝的經營，自然有了相當成就。至日治時期之前，臺灣的美術發展，跟明清整個大國藝術潮流一樣地，以文人風格的傳統書畫為主流。臺灣明清書法風格，共分三個時期:明鄭時代臺灣書法藝術的濫觴；清初的帖學時期；道光中葉以降的碑學加入時期；日治時代碑帖互為消長时期。這也是此次展出的重點。明清時代臺灣之文化史，實為一部「科舉史」，而科舉考試，又最重書法，書法藝術之承傳，端籍科舉文人之力達到顛峰，帖學即為代表，從諸多文人的館閣體可見。道光中葉以後