INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003967', '2025金門元宵燈節', '一年一度重頭戲2025金門 #元宵燈節「福蛇迎春」2月12日至2月23日將在金湖鎮蘭湖及瓊林登場本次燈節共規劃 #蘭湖、#瓊林 及 #小徑 三大燈區各燈區展示現代創意燈組，讓民眾尋訪老街、湖邊還能感受刺激燈光體驗！2月12日蘭湖點燈晚會有精彩樂團表演以及獎品豐富的猜燈謎趣味活動，現場並發放限量紀念小物，2月12日、2月13日還有元宵市集，要讓大家歡度兼具傳統優雅與當代震撼的華麗元宵燈節！2025金門元宵燈節瓊林聚落光環境｜01/01-02/28　18:00-22:00｜瓊林聚落水舞 ｜01/25-02/23　18:30、19:00、19:30、20:00、20:30｜蘭湖週邊蘭湖週邊光環境｜02/12-02/23　18:30-22:00｜蘭湖週邊主燈點燈、猜燈謎｜02/12　19:00｜蘭湖週邊元宵市集｜02/12-02/13　16:00-22:00｜蘭湖週邊', '金門縣政府', '無資料', '2025-01-01 08:00:00', '2025-02-23 22:00:00', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025金門元宵燈節', `description`='一年一度重頭戲2025金門 #元宵燈節「福蛇迎春」2月12日至2月23日將在金湖鎮蘭湖及瓊林登場本次燈節共規劃 #蘭湖、#瓊林 及 #小徑 三大燈區各燈區展示現代創意燈組，讓民眾尋訪老街、湖邊還能感受刺激燈光體驗！2月12日蘭湖點燈晚會有精彩樂團表演以及獎品豐富的猜燈謎趣味活動，現場並發放限量紀念小物，2月12日、2月13日還有元宵市集，要讓大家歡度兼具傳統優雅與當代震撼的華麗元宵燈節！2025金門元宵燈節瓊林聚落光環境｜01/01-02/28　18:00-22:00｜瓊林聚落水舞 ｜01/25-02/23　18:30、19:00、19:30、20:00、20:30｜蘭湖週邊蘭湖週邊光環境｜02/12-02/23　18:30-22:00｜蘭湖週邊主燈點燈、猜燈謎｜02/12　19:00｜蘭湖週邊元宵市集｜02/12-02/13　16:00-22:00｜蘭湖週邊', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-01-01 08:00:00', `end_date`='2025-02-23 22:00:00', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
