INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_003973', '周羿-二胡獨奏會', '周羿-二胡獨奏會演出時間｜114年2月14日(五) 19：30演出地點｜金門縣文化局演藝廳以胡琴藝術帶領愛樂朋友橫跨現代與古樸，擁有動機和感受的音樂體驗。主辦｜金門縣文化局承辦｜浯風愛樂、八分音符音樂坊金門縣籍學子 #周羿 在2022年(國三)時，曾於金門縣文化局舉辦首場二胡與木笛獨奏會，大獲好評與迴響，在此場音樂會後，便隻身前往有「國樂少林寺」之稱的國立臺南藝術大學中國音樂學系高中部接受專業的學習，在二胡演奏的領域更加精進，這次的音樂會，便是周羿展現高中階段苦練的成果。本音樂會由周羿獨奏表演為主體，並和金門縣籍鋼琴音樂碩士 #徐元妤 老師合作演出，另特邀台灣鋼琴合作碩士 #林雨樓 及就讀國立臺南藝術大學國樂系的 #黃晉祿 及音樂系的 #周妍 一同重奏。演出曲目為初心、風華、孤戀花、迷糊調、河南小曲、台北風華、第六二胡狂想曲。周羿主修二胡、副修鋼琴。自八歲加入金門國樂團，胡琴師事陳佳琳老師，現師事蔡鎮宇老師。鋼琴是由徐元婕老師啟蒙，曾師事陳怡靜老師，現師事潘祖欣老師。木笛，師事徐元妤、任心皓老師。自小在二胡及木笛獨奏比賽中獲獎無數，曾榮獲中華民國國樂學會全國器樂大賽二胡高中組金獎、教育部全國學生音樂比賽台南市賽直笛高中組特優第一名；演出經驗豐富，多次受國樂團邀請於國家音樂廳的演出。', '金門縣政府', '無資料', '2025-02-14 19:30:00', '2025-02-14 21:30:00', '金門縣金城鎮', 24.44087, 118.32351, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='周羿-二胡獨奏會', `description`='周羿-二胡獨奏會演出時間｜114年2月14日(五) 19：30演出地點｜金門縣文化局演藝廳以胡琴藝術帶領愛樂朋友橫跨現代與古樸，擁有動機和感受的音樂體驗。主辦｜金門縣文化局承辦｜浯風愛樂、八分音符音樂坊金門縣籍學子 #周羿 在2022年(國三)時，曾於金門縣文化局舉辦首場二胡與木笛獨奏會，大獲好評與迴響，在此場音樂會後，便隻身前往有「國樂少林寺」之稱的國立臺南藝術大學中國音樂學系高中部接受專業的學習，在二胡演奏的領域更加精進，這次的音樂會，便是周羿展現高中階段苦練的成果。本音樂會由周羿獨奏表演為主體，並和金門縣籍鋼琴音樂碩士 #徐元妤 老師合作演出，另特邀台灣鋼琴合作碩士 #林雨樓 及就讀國立臺南藝術大學國樂系的 #黃晉祿 及音樂系的 #周妍 一同重奏。演出曲目為初心、風華、孤戀花、迷糊調、河南小曲、台北風華、第六二胡狂想曲。周羿主修二胡、副修鋼琴。自八歲加入金門國樂團，胡琴師事陳佳琳老師，現師事蔡鎮宇老師。鋼琴是由徐元婕老師啟蒙，曾師事陳怡靜老師，現師事潘祖欣老師。木笛，師事徐元妤、任心皓老師。自小在二胡及木笛獨奏比賽中獲獎無數，曾榮獲中華民國國樂學會全國器樂大賽二胡高中組金獎、教育部全國學生音樂比賽台南市賽直笛高中組特優第一名；演出經驗豐富，多次受國樂團邀請於國家音樂廳的演出。', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-02-14 19:30:00', `end_date`='2025-02-14 21:30:00', `location`='金門縣金城鎮', `latitude`=24.44087, `longitude`=118.32351, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004026', '蓊蓊之森——與書相會的漫漫時光', '蓊蓊之森&mdash;&mdash;與書相會的漫漫時光・書日市集 活動日期｜2025年3月8日（六）-3月9日（日）活動時間｜10:00-16:30活動地點｜金門植物園（伯玉路五段太武山 10 號）活動亮點｜4 大區塊・9 大活動主題，探索書與島嶼的多重面貌1.認識腳下的島｜影像展覽、議題講座2.航行島與島之間｜主題書展、海島影展3.大地的親密呼喚｜手作體驗、攀樹體驗、地景導覽4.在地輕快小聚｜音樂展演、風格品牌出攤主辦單位：蓊蓊書店活動地點：金門植物園（伯玉路五段太武山 10 號）各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-03-08 10:00:00', '2025-03-09 16:30:00', '金門縣金湖鎮', 24.45052, 118.38976, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蓊蓊之森——與書相會的漫漫時光', `description`='蓊蓊之森&mdash;&mdash;與書相會的漫漫時光・書日市集 活動日期｜2025年3月8日（六）-3月9日（日）活動時間｜10:00-16:30活動地點｜金門植物園（伯玉路五段太武山 10 號）活動亮點｜4 大區塊・9 大活動主題，探索書與島嶼的多重面貌1.認識腳下的島｜影像展覽、議題講座2.航行島與島之間｜主題書展、海島影展3.大地的親密呼喚｜手作體驗、攀樹體驗、地景導覽4.在地輕快小聚｜音樂展演、風格品牌出攤主辦單位：蓊蓊書店活動地點：金門植物園（伯玉路五段太武山 10 號）各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-03-08 10:00:00', `end_date`='2025-03-09 16:30:00', `location`='金門縣金湖鎮', `latitude`=24.45052, `longitude`=118.38976, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004031', '冶野藝術工作室《人間探戈》', '《人間探戈》震撼登場跨越百年 探戈舞動金門古蹟4月19日16:00｜陳景蘭洋樓本作融合探戈、芭蕾與當代舞蹈語彙，搭配阿根廷音樂大師皮亞佐拉的經典鉅作《探戈的歷史》，以舞蹈詮釋時代變遷，帶領觀眾跨越百年時光，沉浸於藝術與歷史交織的情感共鳴。《人間探戈》是一部深具哲思與藝術張力的作品，探討個體與社會的微妙關係，並透過舞蹈空間的轉換，呈現不同時代社交場域的變遷。演出將帶來六支風格迥異、層次豐富的舞碼，從音樂、肢體動作與舞台場景設計出發，構築一場跨時代的感官饗宴。探戈舞步間的張力與流動，不僅象徵人類面對變遷的掙扎與適應，更展現人性對愛、自由與歸屬感的不懈追尋。每一個動作、每一次轉身，都是對生命與歷史的詮釋，讓觀眾在觀賞過程中產生深刻共鳴。演出特別採用環境劇場的創新形式，突破傳統舞台與觀眾席的界線，使舞蹈與環境相互交融。演出空間將根據陳景蘭洋樓的歷史背景與建築特色量身打造，透過場域的獨特氛圍，使舞蹈作品更具歷史厚度與藝術張力，讓觀眾在沉浸式體驗中，感受藝術與空間共鳴的獨特魅力。透過舞者與觀眾的零距離互動，打破觀看與表演的界線，創造全新的藝術體驗。冶野藝術工作室自成立以來，持續推動成人藝術教育與身心靈發展，致力於以舞蹈為媒介進行跨領域創作，並積極策辦舞蹈工作坊與藝術參與活動，促進藝術與大眾之間的交流。此次《人間探戈》不僅是舞蹈藝術的一次重要展演，更是一場文化與歷史的深度對話，期望透過藝術的力量，引發觀眾對於時代變遷與個體價值的深刻省思。主辦／金門縣文化局承辦／冶野藝術工作室', '金門縣政府', '無資料', '2025-04-19 16:00:00', '2025-04-19 17:30:00', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='冶野藝術工作室《人間探戈》', `description`='《人間探戈》震撼登場跨越百年 探戈舞動金門古蹟4月19日16:00｜陳景蘭洋樓本作融合探戈、芭蕾與當代舞蹈語彙，搭配阿根廷音樂大師皮亞佐拉的經典鉅作《探戈的歷史》，以舞蹈詮釋時代變遷，帶領觀眾跨越百年時光，沉浸於藝術與歷史交織的情感共鳴。《人間探戈》是一部深具哲思與藝術張力的作品，探討個體與社會的微妙關係，並透過舞蹈空間的轉換，呈現不同時代社交場域的變遷。演出將帶來六支風格迥異、層次豐富的舞碼，從音樂、肢體動作與舞台場景設計出發，構築一場跨時代的感官饗宴。探戈舞步間的張力與流動，不僅象徵人類面對變遷的掙扎與適應，更展現人性對愛、自由與歸屬感的不懈追尋。每一個動作、每一次轉身，都是對生命與歷史的詮釋，讓觀眾在觀賞過程中產生深刻共鳴。演出特別採用環境劇場的創新形式，突破傳統舞台與觀眾席的界線，使舞蹈與環境相互交融。演出空間將根據陳景蘭洋樓的歷史背景與建築特色量身打造，透過場域的獨特氛圍，使舞蹈作品更具歷史厚度與藝術張力，讓觀眾在沉浸式體驗中，感受藝術與空間共鳴的獨特魅力。透過舞者與觀眾的零距離互動，打破觀看與表演的界線，創造全新的藝術體驗。冶野藝術工作室自成立以來，持續推動成人藝術教育與身心靈發展，致力於以舞蹈為媒介進行跨領域創作，並積極策辦舞蹈工作坊與藝術參與活動，促進藝術與大眾之間的交流。此次《人間探戈》不僅是舞蹈藝術的一次重要展演，更是一場文化與歷史的深度對話，期望透過藝術的力量，引發觀眾對於時代變遷與個體價值的深刻省思。主辦／金門縣文化局承辦／冶野藝術工作室', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-04-19 16:00:00', `end_date`='2025-04-19 17:30:00', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004032', '校園柳營笙歌巡迴音樂會', '校園柳營笙歌巡迴音樂會  即將登場3月15日14:30｜金寧中小學體育場4月19日19:00｜金東戲院首場讓表演藝術走出音樂廳，深入校園與社區，更透過動人旋律訴說金門的歷史文化，串聯不同世代，共同編織一場扣人心弦的音樂盛宴。音樂會匯聚金門演出團體，包括安琪莉莎合唱團、紫韻箏樂團、碧山樂團及金寧中小學管樂團，將帶來一系列扣人心弦的音樂作品。安琪莉莎合唱團將獻唱《金門禮讚》、《戰地的春天》、《Dona nobis pacem》、《白雲歌送劉十六歸山》、《鼓浪嶼之波》和《城裡的月光》等中英文經典曲目，以悠揚歌聲詮釋戰地風華與時代記憶。此外，地區知名女高音許瑞芬校長也將帶來獨唱演出，為現場增添藝術魅力。紫韻箏樂團社會組的楊淑珍、洪培蘭、吳昀曇、莊曉芸等人，將演奏《四季紅》、《南都夜曲》、《風之彩》等古箏二重奏，琴聲婉轉悠揚，帶領觀眾穿梭於傳統與現代交融的音樂世界。碧山樂團則將以薩克斯風合奏呈現經典旋律，溫潤的音色詮釋不同音樂風情。此外，金寧中小學管樂團的學子們也將登台演出，透過純真的音符展現平日努力練習的成果，為音樂會增添青春活力。這場音樂會特別融合社會社團與學校團體，老中青三代音樂人齊聚一堂，透過音樂交流、觀摩與學習，共同為金門帶來充滿藝術氣息的春日樂章。音樂會免費開放入場，誠摯邀請金門地區民眾、學生及家長踴躍參與，在悠揚樂聲中共享美好時光。無論是熱愛音樂的樂迷，或是希望體驗不同音樂風格的觀眾，都歡迎一同走進音樂殿堂，感受音符流轉間的動人故事。主辦／金門縣文化局承辦／金門縣閩聲愛樂協會、金寧鄉公所協辦／金沙鎮公所、金寧中小學', '金門縣政府', '無資料', '2025-03-15 14:30:00', '2025-04-19 21:30:00', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='校園柳營笙歌巡迴音樂會', `description`='校園柳營笙歌巡迴音樂會  即將登場3月15日14:30｜金寧中小學體育場4月19日19:00｜金東戲院首場讓表演藝術走出音樂廳，深入校園與社區，更透過動人旋律訴說金門的歷史文化，串聯不同世代，共同編織一場扣人心弦的音樂盛宴。音樂會匯聚金門演出團體，包括安琪莉莎合唱團、紫韻箏樂團、碧山樂團及金寧中小學管樂團，將帶來一系列扣人心弦的音樂作品。安琪莉莎合唱團將獻唱《金門禮讚》、《戰地的春天》、《Dona nobis pacem》、《白雲歌送劉十六歸山》、《鼓浪嶼之波》和《城裡的月光》等中英文經典曲目，以悠揚歌聲詮釋戰地風華與時代記憶。此外，地區知名女高音許瑞芬校長也將帶來獨唱演出，為現場增添藝術魅力。紫韻箏樂團社會組的楊淑珍、洪培蘭、吳昀曇、莊曉芸等人，將演奏《四季紅》、《南都夜曲》、《風之彩》等古箏二重奏，琴聲婉轉悠揚，帶領觀眾穿梭於傳統與現代交融的音樂世界。碧山樂團則將以薩克斯風合奏呈現經典旋律，溫潤的音色詮釋不同音樂風情。此外，金寧中小學管樂團的學子們也將登台演出，透過純真的音符展現平日努力練習的成果，為音樂會增添青春活力。這場音樂會特別融合社會社團與學校團體，老中青三代音樂人齊聚一堂，透過音樂交流、觀摩與學習，共同為金門帶來充滿藝術氣息的春日樂章。音樂會免費開放入場，誠摯邀請金門地區民眾、學生及家長踴躍參與，在悠揚樂聲中共享美好時光。無論是熱愛音樂的樂迷，或是希望體驗不同音樂風格的觀眾，都歡迎一同走進音樂殿堂，感受音符流轉間的動人故事。主辦／金門縣文化局承辦／金門縣閩聲愛樂協會、金寧鄉公所協辦／金沙鎮公所、金寧中小學', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-03-15 14:30:00', `end_date`='2025-04-19 21:30:00', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004033', '「AI繪紅樓・紅樓會AI」展覽', '「AI繪紅樓・紅樓會AI」展覽登場，探索科技與文學的交融之美由國立金門大學華語文學系主辦、金門縣文化局協辦的「AI繪紅樓・紅樓會AI」展覽將於114年3月14日(五)至3月20日(四)止，在金門縣文化局第三展場展出。本展覽結合生成式人工智慧（Generative AI, GAI）與《紅樓夢》經典意象，展現科技與文學交織的無限可能，誠摯邀請各界蒞臨參觀。此次展覽由國立金門大學華語文學系李瑄教授攜手紅學家張玉明教授，共同指導金大華文系學生運用GAI技術創作《紅樓夢》中的八大人物（賈寶玉、林黛玉、薛寶釵等），以及「共讀西廂」、「黛玉葬花」、「寶釵撲蝶」、「寶玉出家」等經典場景，是本次展覽主軸。李瑄教授表示：「ChatGPT 3.5於2022年問世後，AI技術迅速發展，翻轉了教育與創作方式。本展覽是華語文學系探索AI與文學融合的階段性成果，每個人都可以讓《紅樓夢》人物與場景從書中走出來，開啟嶄新的詮釋可能。」。展區內將播放AI生成的紅樓音樂作品，讓觀眾透過多元形式感受紅樓文化的魅力。除了科技創作，亦展出手作文創作品，如花籤、紙雕、人物小書等，讓手作文創與科技創作相互輝映，共同勾勒出當代的紅樓詮釋。此外，特別邀請金門文人雅士陳邦祥老師與洪篤欽先生展出珍藏品，如各版本《紅樓夢》、近現代著名畫家之紅樓夢畫冊等珍貴書籍，並陳列清代束冠、髮簪、鎖片、點翠、紙鳶等文物，帶領觀眾穿越時空，窺探紅樓時代的日常生活。這場結合AI科技、文學藝術的展覽，將帶領觀眾從創作、古物、書籍等多重視角，再次閱讀《紅樓夢》。歡迎有興趣的民眾把握機會，一同走進AI與紅樓交會的時空！展覽資訊：●展覽期間：114年3月14日（五）至3月20日（四）●展覽地點：金門縣文化局一樓第三展場●定時導覽：由國立金門大學華語文學系師生進行導覽，並介紹如何使用AI生成圖片及音樂114年3月15日（六）上午11時、下午2時、4時114年3月16日（日）上午11時、下午2時、4時114年3月17日（一）下午2時114年3月18日（二）下午2時●展覽宣傳影片：https://youtu.be/cdJ4ISmnVGo?si=qOLdhq4...', '金門縣政府', '無資料', '2025-03-15 08:00:00', '2025-03-20 17:30:00', '金門縣金城鎮', 24.44087, 118.32351, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「AI繪紅樓・紅樓會AI」展覽', `description`='「AI繪紅樓・紅樓會AI」展覽登場，探索科技與文學的交融之美由國立金門大學華語文學系主辦、金門縣文化局協辦的「AI繪紅樓・紅樓會AI」展覽將於114年3月14日(五)至3月20日(四)止，在金門縣文化局第三展場展出。本展覽結合生成式人工智慧（Generative AI, GAI）與《紅樓夢》經典意象，展現科技與文學交織的無限可能，誠摯邀請各界蒞臨參觀。此次展覽由國立金門大學華語文學系李瑄教授攜手紅學家張玉明教授，共同指導金大華文系學生運用GAI技術創作《紅樓夢》中的八大人物（賈寶玉、林黛玉、薛寶釵等），以及「共讀西廂」、「黛玉葬花」、「寶釵撲蝶」、「寶玉出家」等經典場景，是本次展覽主軸。李瑄教授表示：「ChatGPT 3.5於2022年問世後，AI技術迅速發展，翻轉了教育與創作方式。本展覽是華語文學系探索AI與文學融合的階段性成果，每個人都可以讓《紅樓夢》人物與場景從書中走出來，開啟嶄新的詮釋可能。」。展區內將播放AI生成的紅樓音樂作品，讓觀眾透過多元形式感受紅樓文化的魅力。除了科技創作，亦展出手作文創作品，如花籤、紙雕、人物小書等，讓手作文創與科技創作相互輝映，共同勾勒出當代的紅樓詮釋。此外，特別邀請金門文人雅士陳邦祥老師與洪篤欽先生展出珍藏品，如各版本《紅樓夢》、近現代著名畫家之紅樓夢畫冊等珍貴書籍，並陳列清代束冠、髮簪、鎖片、點翠、紙鳶等文物，帶領觀眾穿越時空，窺探紅樓時代的日常生活。這場結合AI科技、文學藝術的展覽，將帶領觀眾從創作、古物、書籍等多重視角，再次閱讀《紅樓夢》。歡迎有興趣的民眾把握機會，一同走進AI與紅樓交會的時空！展覽資訊：●展覽期間：114年3月14日（五）至3月20日（四）●展覽地點：金門縣文化局一樓第三展場●定時導覽：由國立金門大學華語文學系師生進行導覽，並介紹如何使用AI生成圖片及音樂114年3月15日（六）上午11時、下午2時、4時114年3月16日（日）上午11時、下午2時、4時114年3月17日（一）下午2時114年3月18日（二）下午2時●展覽宣傳影片：https://youtu.be/cdJ4ISmnVGo?si=qOLdhq4...', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-03-15 08:00:00', `end_date`='2025-03-20 17:30:00', `location`='金門縣金城鎮', `latitude`=24.44087, `longitude`=118.32351, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004034', '嘉禮豐華─傀儡戲偶展', '嘉禮豐華─傀儡戲偶展展期｜03/22-04/30展地｜金門縣文化局文物特藏室2023年12月19日，新順興傀儡戲團孫建德藝師的女兒孫玉琴女士，致電給金門縣文化局，表示要將祖厝中整理出來，父親生前留下的傀儡戲偶捐贈給文化局，呂坤和(前任局長)與承辦人趕到古厝，從孫藝師家屬手中接過裝在一個竹籮筐中殘留的戲偶，文化局鼓勵家屬留下古厝原貌修復，並答應會好好思考如何保存這些戲偶。時隔一年，在金門傀儡戲劇團蔡遠進團長的協助整理下，加入蔡團長劇團演出的戲偶，以「嘉禮豐華~傀儡戲偶展」為主題陳展各種角色的傀儡戲偶。傀儡戲又稱木偶戲、伽儡戲或加禮戲，舊稱「四美班」，金門傀儡戲是由泉州傳入，活動時間甚早，可推至清代中葉，道士兼傀儡師的孫文華（西元1784-1833年）從晉江安海移居金門，傳子孫添順（西元1822-1869年）組新順興班，主要演傀儡戲與布袋戲，再傳給孫紫鏢（西元1851-1869年），並從晉江聘請著名的布袋戲師傅張好主演。張好綽號「好師」，生於同治初年（西元1862前後），與另一布袋戲師傅綽號「至師」的李連至齊名，新順興的孫建德（西元1926年生）便承傳自張好之衣缽。傀儡戲偶的製作與布袋戲相同，分為頭、身軀、手和腳。頭部為木製，因製作過程複雜，大部分向臺灣彰化買現成，手和腳為塑膠製也是買現成的，身軀部分則依演出者身高而不同，以便操控，由演出者自製，材料不限制。金門的傀儡戲屬「提線傀儡」，又稱為「懸絲傀儡」，演出時多與金門風俗結婚及天誕有關，如「天公生」、結婚、奠安、十六歲成年禮等。目前孫建德藝師的技藝未傳予後人，亦是一件憾事，孫女士家人決定將戲偶捐出，願這次展出，能讓更多人認識金門無形文化資產已登錄的傳統表演藝術「金門傳統傀儡戲」，除了認知上是要靠藝師之巧手外，其實還需搭配上各種重要角色的傀儡戲偶，便成就了一部完整的大戲。', '金門縣政府', '無資料', '2025-03-22 08:00:00', '2025-04-30 17:30:00', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='嘉禮豐華─傀儡戲偶展', `description`='嘉禮豐華─傀儡戲偶展展期｜03/22-04/30展地｜金門縣文化局文物特藏室2023年12月19日，新順興傀儡戲團孫建德藝師的女兒孫玉琴女士，致電給金門縣文化局，表示要將祖厝中整理出來，父親生前留下的傀儡戲偶捐贈給文化局，呂坤和(前任局長)與承辦人趕到古厝，從孫藝師家屬手中接過裝在一個竹籮筐中殘留的戲偶，文化局鼓勵家屬留下古厝原貌修復，並答應會好好思考如何保存這些戲偶。時隔一年，在金門傀儡戲劇團蔡遠進團長的協助整理下，加入蔡團長劇團演出的戲偶，以「嘉禮豐華~傀儡戲偶展」為主題陳展各種角色的傀儡戲偶。傀儡戲又稱木偶戲、伽儡戲或加禮戲，舊稱「四美班」，金門傀儡戲是由泉州傳入，活動時間甚早，可推至清代中葉，道士兼傀儡師的孫文華（西元1784-1833年）從晉江安海移居金門，傳子孫添順（西元1822-1869年）組新順興班，主要演傀儡戲與布袋戲，再傳給孫紫鏢（西元1851-1869年），並從晉江聘請著名的布袋戲師傅張好主演。張好綽號「好師」，生於同治初年（西元1862前後），與另一布袋戲師傅綽號「至師」的李連至齊名，新順興的孫建德（西元1926年生）便承傳自張好之衣缽。傀儡戲偶的製作與布袋戲相同，分為頭、身軀、手和腳。頭部為木製，因製作過程複雜，大部分向臺灣彰化買現成，手和腳為塑膠製也是買現成的，身軀部分則依演出者身高而不同，以便操控，由演出者自製，材料不限制。金門的傀儡戲屬「提線傀儡」，又稱為「懸絲傀儡」，演出時多與金門風俗結婚及天誕有關，如「天公生」、結婚、奠安、十六歲成年禮等。目前孫建德藝師的技藝未傳予後人，亦是一件憾事，孫女士家人決定將戲偶捐出，願這次展出，能讓更多人認識金門無形文化資產已登錄的傳統表演藝術「金門傳統傀儡戲」，除了認知上是要靠藝師之巧手外，其實還需搭配上各種重要角色的傀儡戲偶，便成就了一部完整的大戲。', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-03-22 08:00:00', `end_date`='2025-04-30 17:30:00', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004035', '「小兵日記兒童軍事體驗營」系列活動', '活動共辦理6梯次，適合3至12歲兒童參與，將環境教育與軍事體驗結合，讓孩子在寓教於樂的氛圍中，拓展視野，激發多元探索的興趣。活動內容分為兩大類別：「海陸特戰營」與「小小陸軍營」。活動自即日起開放報名，每梯次限額30名，額滿為止。 相關活動訊息請見本處官網及臉書粉絲專頁。主辦單位：內政部國家公園署金門國家公園管理處活動時間：3月15-16日、3月29-30日活動地點：乳山故壘連絡電話：解說教育科陳小姐 082-313182各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-03-15 00:00:00', '2025-03-30 23:59:59', '金門縣金寧鄉', 24.43711, 118.35248, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「小兵日記兒童軍事體驗營」系列活動', `description`='活動共辦理6梯次，適合3至12歲兒童參與，將環境教育與軍事體驗結合，讓孩子在寓教於樂的氛圍中，拓展視野，激發多元探索的興趣。活動內容分為兩大類別：「海陸特戰營」與「小小陸軍營」。活動自即日起開放報名，每梯次限額30名，額滿為止。 相關活動訊息請見本處官網及臉書粉絲專頁。主辦單位：內政部國家公園署金門國家公園管理處活動時間：3月15-16日、3月29-30日活動地點：乳山故壘連絡電話：解說教育科陳小姐 082-313182各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-03-15 00:00:00', `end_date`='2025-03-30 23:59:59', `location`='金門縣金寧鄉', `latitude`=24.43711, `longitude`=118.35248, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004036', '2025金門縣第十七屆端午節龍舟競賽', '發揚並傳承傳統民俗技藝活動，發揮團隊精神，啟迪愛國情操，增進社會和諧。提倡正當休閒娛樂，達到寓教於樂的效果，預估參與人數1,200人(龍舟競賽+寫生)。主辦單位：金門縣體育場活動時間：5月31日(暫訂)活動地點：金門縣體育場連絡電話：鄭先生 082-372361#31各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-05-31 00:00:00', '2025-05-31 23:59:59', '金門縣金寧鄉', 24.47752, 118.3103, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025金門縣第十七屆端午節龍舟競賽', `description`='發揚並傳承傳統民俗技藝活動，發揮團隊精神，啟迪愛國情操，增進社會和諧。提倡正當休閒娛樂，達到寓教於樂的效果，預估參與人數1,200人(龍舟競賽+寫生)。主辦單位：金門縣體育場活動時間：5月31日(暫訂)活動地點：金門縣體育場連絡電話：鄭先生 082-372361#31各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-05-31 00:00:00', `end_date`='2025-05-31 23:59:59', `location`='金門縣金寧鄉', `latitude`=24.47752, `longitude`=118.3103, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004037', '114年四季走讀—走春：賢厝、山前', '114年四季走讀&mdash;走春：賢厝、山前3月11日週二早上9點起網路報名，恕不受理現場及傳真報名上午場https://reurl.cc/RLZrdr下午場https://reurl.cc/XZ0jkj活動日期： 3月15日（六）活動梯次：上午場 08:00-12:00（08:10前報到）下午場 13:00-17:00（13:10前報到）文化局大門口辦理報到敬請準時，逾時不候 走春地點： 賢厝、山前聚落 報名對象： 幼稚園以上民眾（學童須家長陪同） 報名方式： 限網路報名（每人限報1梯次，最多報名2位） 洽詢電話： 082-323169轉174#跟隨在地文史專家，踏訪賢厝、山前的歷史文化景點，包括：、前山前的聚落概述與古厝、許獬墓、聚落後方的石井鄭氏祖瑩、泰安宮、盧若騰墓園、盧若騰故宅、盧氏家廟與盧氏源流、路邊的二孔古井、顏氏家廟與顏氏源流、顏氏古厝群泰安宮｜金門舊志記載的「#七賢祠」盧若騰故居與墓園｜明末兵部尚書的歷史足跡二孔古井｜#見證聚落發展的珍貴遺跡 顏氏、盧氏家廟與古厝群｜探索金門傳統聚落文化走讀活動中並提供圖書巡迴車及借書證辦證服務，歡迎大家多多使用現場提供圖書巡迴車與借書證辦證服務，邀請您一起走讀春天、感受歷史之美！', '金門縣政府', '無資料', '2025-03-15 08:00:00', '2025-03-15 17:00:00', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年四季走讀—走春：賢厝、山前', `description`='114年四季走讀&mdash;走春：賢厝、山前3月11日週二早上9點起網路報名，恕不受理現場及傳真報名上午場https://reurl.cc/RLZrdr下午場https://reurl.cc/XZ0jkj活動日期： 3月15日（六）活動梯次：上午場 08:00-12:00（08:10前報到）下午場 13:00-17:00（13:10前報到）文化局大門口辦理報到敬請準時，逾時不候 走春地點： 賢厝、山前聚落 報名對象： 幼稚園以上民眾（學童須家長陪同） 報名方式： 限網路報名（每人限報1梯次，最多報名2位） 洽詢電話： 082-323169轉174#跟隨在地文史專家，踏訪賢厝、山前的歷史文化景點，包括：、前山前的聚落概述與古厝、許獬墓、聚落後方的石井鄭氏祖瑩、泰安宮、盧若騰墓園、盧若騰故宅、盧氏家廟與盧氏源流、路邊的二孔古井、顏氏家廟與顏氏源流、顏氏古厝群泰安宮｜金門舊志記載的「#七賢祠」盧若騰故居與墓園｜明末兵部尚書的歷史足跡二孔古井｜#見證聚落發展的珍貴遺跡 顏氏、盧氏家廟與古厝群｜探索金門傳統聚落文化走讀活動中並提供圖書巡迴車及借書證辦證服務，歡迎大家多多使用現場提供圖書巡迴車與借書證辦證服務，邀請您一起走讀春天、感受歷史之美！', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-03-15 08:00:00', `end_date`='2025-03-15 17:00:00', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004038', '2025時光繁星-夏日灣市集', '官澳海堤上一邊是蔚藍的海岸線，另一邊是則能欣賞寧靜純樸的官澳聚落倒映在水中，景致十分優美。而「灣口海濱公園」擁有遊憩設施閒適氛圍，夏日海濱可享受親子野餐時光，擬規劃辦理野餐巿集活動，集結「餐車、美食、生活、育樂」的巿集模式，整合金門本地特色商家及台灣人氣餐車、攤商共同參與，讓市集豐富多元，振興金沙在地觀光發展。主辦單位：金沙鎮公所農業觀光課活動時間：預計114年 7月12日(週六)、13日(週日)等2日活動地點：金沙鎮官澳灣口海濱公園連絡電話：陳先生 082-352150各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-07-12 00:00:00', '2025-07-13 23:59:59', '金門縣金沙鎮', 24.51747, 118.41153, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025時光繁星-夏日灣市集', `description`='官澳海堤上一邊是蔚藍的海岸線，另一邊是則能欣賞寧靜純樸的官澳聚落倒映在水中，景致十分優美。而「灣口海濱公園」擁有遊憩設施閒適氛圍，夏日海濱可享受親子野餐時光，擬規劃辦理野餐巿集活動，集結「餐車、美食、生活、育樂」的巿集模式，整合金門本地特色商家及台灣人氣餐車、攤商共同參與，讓市集豐富多元，振興金沙在地觀光發展。主辦單位：金沙鎮公所農業觀光課活動時間：預計114年 7月12日(週六)、13日(週日)等2日活動地點：金沙鎮官澳灣口海濱公園連絡電話：陳先生 082-352150各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-07-12 00:00:00', `end_date`='2025-07-13 23:59:59', `location`='金門縣金沙鎮', `latitude`=24.51747, `longitude`=118.41153, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004039', '「八閩舞墨、烈嶼傳情」台北市八閩美術會書畫家作品聯展', '「八閩舞墨、烈嶼傳情」台北市八閩美術會書畫家作品聯展3 月1 日至4月30日｜烈嶼鄉地方文化館展覽呈現 72 幅極具藝術價值的水墨與書法精品，涵蓋了山水、花鳥、人物、走獸等多樣題材。每一幅作品，不僅 是對自然與人文情感的深刻詮釋，更是藝術家心靈的傾訴與表達。通過筆尖間流淌的墨韻，藝術家們用筆觸舞動出自然的生 動與靈動，也將山川大海、花鳥人物的壯麗與包容之美展現無遺。每一筆、每一劃，都是一種情感的傳遞，彷彿在水墨間訴說著大地與人心的共鳴。', '金門縣政府', '無資料', '2025-03-01 08:00:00', '2025-04-30 17:30:00', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「八閩舞墨、烈嶼傳情」台北市八閩美術會書畫家作品聯展', `description`='「八閩舞墨、烈嶼傳情」台北市八閩美術會書畫家作品聯展3 月1 日至4月30日｜烈嶼鄉地方文化館展覽呈現 72 幅極具藝術價值的水墨與書法精品，涵蓋了山水、花鳥、人物、走獸等多樣題材。每一幅作品，不僅 是對自然與人文情感的深刻詮釋，更是藝術家心靈的傾訴與表達。通過筆尖間流淌的墨韻，藝術家們用筆觸舞動出自然的生 動與靈動，也將山川大海、花鳥人物的壯麗與包容之美展現無遺。每一筆、每一劃，都是一種情感的傳遞，彷彿在水墨間訴說著大地與人心的共鳴。', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-03-01 08:00:00', `end_date`='2025-04-30 17:30:00', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004040', '金門縣攝影學會會員聯展「祭‧平安」攝影展暨「人像與風景攝影美學」藝術講座', '金門縣攝影學會會員聯展「祭‧平安」攝影展暨「人像與風景攝影美學」藝術講座 3月8日文化局登場由金門縣文化局主辦、金門縣攝影學會協辦的2025年「金門縣攝影學會會員聯展」，將於3月8日至3月19日在文化局第一展廳盛大展出。開幕典禮將於3月8日上午10時在金門縣文化局大廳舉行，誠摯邀請金門鄉親前來參觀與交流。本次展覽的主題為「祭‧平安」，透過鏡頭捕捉金門寺廟與民間信仰活動的莊嚴與熱烈，呈現祭典過程中的虔誠氛圍，讓人感受到金門人民對信仰與傳統文化的深厚情感。展覽展現宗教信仰如何安定人心，培養同理心與慈悲，並給予心靈的安慰與內在的寧靜。參展的藝術家包括王衛煌、蔡添丁、王婷、蔡顯國、許進西、方朝良、鄭碧珍、許志恆、許雅玲、林筱雯、黃逸煥、黃奕偉、悟真、辛甫道、辛甫愿、陳宗新、俞政君、李衛脩、徐國輝、黃邦培、洪金池、許文科、蔡木在、王賢德等24位攝影家，共同呈現60幅精彩作品。此外，金門縣文化局將邀請黃邦培老師於3月8日下午2:00，在文化局三樓會議室舉辦藝術講座「人像與風景攝影美學」。黃老師擁有近三十年的經驗，專注於婚紗與人像攝影，對攝影愛好者來說，這樣的機會可以深入了解攝影技巧並提升拍攝技術。特別是焦距選擇、鏡頭應用等，對並創造出不同的視覺效果。這活動對那些希望掌握光影處理和構圖技巧的參加者，提供了非常實用的知識。如果有興趣的朋友，本次講座不需要報名，講座中還有機會與其他攝影愛好者交流經驗。如果你有興趣，歡迎參加，了解更多攝影方面的技巧！金門縣文化局與金門縣攝影學會誠摯邀請所有對攝影有興趣的朋友，來欣賞這次精彩的攝影展覽，並與黃邦培理事長一起深入探索攝影的藝術與技術。這不僅是視覺的享受，也是心靈的對話，邀您一起感受金門獨特的宗教魅力與攝影家的情感表達。', '金門縣政府', '無資料', '2025-03-08 08:00:00', '2025-03-19 17:30:00', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='金門縣攝影學會會員聯展「祭‧平安」攝影展暨「人像與風景攝影美學」藝術講座', `description`='金門縣攝影學會會員聯展「祭‧平安」攝影展暨「人像與風景攝影美學」藝術講座 3月8日文化局登場由金門縣文化局主辦、金門縣攝影學會協辦的2025年「金門縣攝影學會會員聯展」，將於3月8日至3月19日在文化局第一展廳盛大展出。開幕典禮將於3月8日上午10時在金門縣文化局大廳舉行，誠摯邀請金門鄉親前來參觀與交流。本次展覽的主題為「祭‧平安」，透過鏡頭捕捉金門寺廟與民間信仰活動的莊嚴與熱烈，呈現祭典過程中的虔誠氛圍，讓人感受到金門人民對信仰與傳統文化的深厚情感。展覽展現宗教信仰如何安定人心，培養同理心與慈悲，並給予心靈的安慰與內在的寧靜。參展的藝術家包括王衛煌、蔡添丁、王婷、蔡顯國、許進西、方朝良、鄭碧珍、許志恆、許雅玲、林筱雯、黃逸煥、黃奕偉、悟真、辛甫道、辛甫愿、陳宗新、俞政君、李衛脩、徐國輝、黃邦培、洪金池、許文科、蔡木在、王賢德等24位攝影家，共同呈現60幅精彩作品。此外，金門縣文化局將邀請黃邦培老師於3月8日下午2:00，在文化局三樓會議室舉辦藝術講座「人像與風景攝影美學」。黃老師擁有近三十年的經驗，專注於婚紗與人像攝影，對攝影愛好者來說，這樣的機會可以深入了解攝影技巧並提升拍攝技術。特別是焦距選擇、鏡頭應用等，對並創造出不同的視覺效果。這活動對那些希望掌握光影處理和構圖技巧的參加者，提供了非常實用的知識。如果有興趣的朋友，本次講座不需要報名，講座中還有機會與其他攝影愛好者交流經驗。如果你有興趣，歡迎參加，了解更多攝影方面的技巧！金門縣文化局與金門縣攝影學會誠摯邀請所有對攝影有興趣的朋友，來欣賞這次精彩的攝影展覽，並與黃邦培理事長一起深入探索攝影的藝術與技術。這不僅是視覺的享受，也是心靈的對話，邀您一起感受金門獨特的宗教魅力與攝影家的情感表達。', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-03-08 08:00:00', `end_date`='2025-03-19 17:30:00', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004045', '碧山樂團「吹響金門」巡演', '碧山樂團「吹響金門」巡演登場透過悠揚樂聲傳遞正能量，凝聚社區情感。本次巡演將涵蓋各鄉鎮，為金門地區帶來一場場精彩的音樂饗宴，讓更多人透過音樂感受社區的溫暖與活力。#碧山樂團 成立近5年，由一群熱愛音樂的金門鄉親組成，成員來自社會各階層。樂團演奏形式以薩克斯風、小號等管樂為主，結合爵士鼓、電子琴及人聲重唱，呈現多元曲風。成立以來，樂團已巡演100場，廣受地方好評，透過每次演出，讓音樂成為連結人心的重要媒介。本次「吹響金門」巡演將演奏閩南語歌謠、民歌及輕快的現代歌曲，不僅展現金門豐富的文化底蘊，更象徵小島社區的活力與創新。碧山樂團希望透過音樂的力量，讓民眾在輕快旋律中釋放壓力，增進彼此情感交流，進而促進社區間的互動與連結。｜巡演場次｜3月22日14:30｜金湖鎮福田家園3月22日19:30｜金沙鎮何厝社區3月29日19:30｜烈嶼鄉東坑社區4月19日14:30｜金城鎮大同之家4月19日19:30｜金寧鄉古寧頭社區邀請音樂愛好者及社區居民共襄盛舉，一同感受音樂魅力，讓樂聲串聯社區，為金門藝文發展增添光彩，期待大家踴躍參與，共享音樂之美。金門縣文化局/主辦碧山樂團/承辦', '金門縣政府', '無資料', '2025-03-22 14:00:00', '2025-04-19 21:00:00', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='碧山樂團「吹響金門」巡演', `description`='碧山樂團「吹響金門」巡演登場透過悠揚樂聲傳遞正能量，凝聚社區情感。本次巡演將涵蓋各鄉鎮，為金門地區帶來一場場精彩的音樂饗宴，讓更多人透過音樂感受社區的溫暖與活力。#碧山樂團 成立近5年，由一群熱愛音樂的金門鄉親組成，成員來自社會各階層。樂團演奏形式以薩克斯風、小號等管樂為主，結合爵士鼓、電子琴及人聲重唱，呈現多元曲風。成立以來，樂團已巡演100場，廣受地方好評，透過每次演出，讓音樂成為連結人心的重要媒介。本次「吹響金門」巡演將演奏閩南語歌謠、民歌及輕快的現代歌曲，不僅展現金門豐富的文化底蘊，更象徵小島社區的活力與創新。碧山樂團希望透過音樂的力量，讓民眾在輕快旋律中釋放壓力，增進彼此情感交流，進而促進社區間的互動與連結。｜巡演場次｜3月22日14:30｜金湖鎮福田家園3月22日19:30｜金沙鎮何厝社區3月29日19:30｜烈嶼鄉東坑社區4月19日14:30｜金城鎮大同之家4月19日19:30｜金寧鄉古寧頭社區邀請音樂愛好者及社區居民共襄盛舉，一同感受音樂魅力，讓樂聲串聯社區，為金門藝文發展增添光彩，期待大家踴躍參與，共享音樂之美。金門縣文化局/主辦碧山樂團/承辦', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-03-22 14:00:00', `end_date`='2025-04-19 21:00:00', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_004840', '2025桃園跨年晚會', '￭相關內容請洽本局行銷科03-3322101#6202今年的最後一夜，要讓你感受到桃園的魅力與特色！這座城市，擁有多元的文化、族群、面貌，如同 2025 桃園跨年晚會將帶你體驗不一樣的跨年晚會。超多強大陣容，將以你從沒看過的組合方式出場，呈現超乎你想像的精采演出。今年最不能錯過的大秀，跨年夜一起來看！晚會時間：2024 年 12 月 31 日 (星期二) 19:00 ~ 2025 年 1 月 1 日 (星期三) 00:30晚會地點：桃園高鐵站前廣場(近領航南路三段)卡司陣容：☆ 4位主持絕妙搭檔 : 小鐘、何妤玟、短今、潘君侖☆ 13組藝人:姜丹尼爾 KANG DANIEL ( #강다니엘)及DAYCHILD  (#데이차일드)、丁噹、陳芳語、白安、TRASH、李芷婷、艾薇、小男孩樂團、范逸臣、原子少年Saturnday、洪暐哲、ELL&s未來少女交通方式：詳如圖卡說明  【拍出你的節奏 抽VIP PASS活動】活動時間：即日起，至113.12.26(四)晚間23：59止活動說明：於活動期間內，在「樂遊桃園」官方臉書粉絲專頁內活動指定貼文，完成指定任務，即可獲得限量《VIP PASS》抽獎機會。活動辦法：步驟1：追蹤「樂遊桃園」官方臉書粉絲專頁 步驟2：在⭐這則活動貼文下方留言，留言內容符合：       1.公開上傳你的「燈燈燈燈」短影音       2.標註「#燈燈燈燈2025桃園跨年晚會，一起High整晚~」活動獎勵：取得VIP PASS抽獎機會，將抽出15組，每組2張。&gt;&gt;更多活動詳情請看「樂遊桃園」官方臉書粉絲專頁查詢 https://www.facebook.com/share/p/15ppQTnoTn/晚會直播電視➊ 中視新聞台(CH154)&bull; 直播Live：12/31晚間19:00〜1/1凌晨 00:30&bull; 重播：1/1凌晨00:30〜早上06:00➋ 中天綜合台(CH36)&bull; 直播Live：12/31晚間19:00〜1/1凌晨 00:30 網路...', '桃園市政府', '桃園市320中壢區領航南路三段', '2024-12-31 19:00:00', '2025-01-01 00:30:00', '桃園市中壢區', 25.0099, 121.21852, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025桃園跨年晚會', `description`='￭相關內容請洽本局行銷科03-3322101#6202今年的最後一夜，要讓你感受到桃園的魅力與特色！這座城市，擁有多元的文化、族群、面貌，如同 2025 桃園跨年晚會將帶你體驗不一樣的跨年晚會。超多強大陣容，將以你從沒看過的組合方式出場，呈現超乎你想像的精采演出。今年最不能錯過的大秀，跨年夜一起來看！晚會時間：2024 年 12 月 31 日 (星期二) 19:00 ~ 2025 年 1 月 1 日 (星期三) 00:30晚會地點：桃園高鐵站前廣場(近領航南路三段)卡司陣容：☆ 4位主持絕妙搭檔 : 小鐘、何妤玟、短今、潘君侖☆ 13組藝人:姜丹尼爾 KANG DANIEL ( #강다니엘)及DAYCHILD  (#데이차일드)、丁噹、陳芳語、白安、TRASH、李芷婷、艾薇、小男孩樂團、范逸臣、原子少年Saturnday、洪暐哲、ELL&s未來少女交通方式：詳如圖卡說明  【拍出你的節奏 抽VIP PASS活動】活動時間：即日起，至113.12.26(四)晚間23：59止活動說明：於活動期間內，在「樂遊桃園」官方臉書粉絲專頁內活動指定貼文，完成指定任務，即可獲得限量《VIP PASS》抽獎機會。活動辦法：步驟1：追蹤「樂遊桃園」官方臉書粉絲專頁 步驟2：在⭐這則活動貼文下方留言，留言內容符合：       1.公開上傳你的「燈燈燈燈」短影音       2.標註「#燈燈燈燈2025桃園跨年晚會，一起High整晚~」活動獎勵：取得VIP PASS抽獎機會，將抽出15組，每組2張。&gt;&gt;更多活動詳情請看「樂遊桃園」官方臉書粉絲專頁查詢 https://www.facebook.com/share/p/15ppQTnoTn/晚會直播電視➊ 中視新聞台(CH154)&bull; 直播Live：12/31晚間19:00〜1/1凌晨 00:30&bull; 重播：1/1凌晨00:30〜早上06:00➋ 中天綜合台(CH36)&bull; 直播Live：12/31晚間19:00〜1/1凌晨 00:30 網路...', `organizer`='桃園市政府', `address`='桃園市320中壢區領航南路三段', `start_date`='2024-12-31 19:00:00', `end_date`='2025-01-01 00:30:00', `location`='桃園市中壢區', `latitude`=25.0099, `longitude`=121.21852, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005190', '2025 角板山梅花季', '✨ 霹靂布袋戲 X 迎新春揮毫 ✨ 2025探索北橫冬季活動 | 梅好時光 騎趣角板  地點：角板山行館(桃園市復興區中正路133-1號)️ 活動日期：2025年1月4日(六)至1月12日(日)⏰ 時間：上午10:00 - 下午16:00✨ 交通資訊，讓你輕鬆到場！ 大眾運輸建議 桃園客運： 桃園總站搭乘 502 台灣好行小烏來線 或 506 東眼山線，直接抵達角板山行館！ 大溪客運總站搭乘以下路線：5106、5106A、5104、5104A、5109、5093、5105、5094。✨ 停車場資訊若自行開車，建議停放以下地點： 上台地停車場：https://maps.app.goo.gl/HEYLGgHn7NMCfWk49 仁愛停車場：https://maps.app.goo.gl/zeNtWdhyenLYi7M9A 羅浮高中停車場：https://maps.app.goo.gl/Lv7cPtZgpZZFAK3V8 搭乘大眾運輸，不僅環保又便利，讓我們一起支持綠色出行！快約家人朋友，一起來角板山行館感受梅花季的迷人魅力吧！ ✨ 1/4 特別企劃：霹靂布袋戲 梅林獻蹤 時間：10:00 - 15:00一場結合傳統與創意的視覺饗宴！邀請霹靂布袋戲經典角色素還真與一頁書 大偶隆重登場，搭配無限人形COSPLAY團隊 精彩演出，帶來不同凡響的文化體驗！開幕記者會 10:30-11:30霹靂英雄：刀說素還真、刀說一頁書霹靂COS：刀說素還真、刀說一頁書、縹緲月、天道主靂英雄遊園 13:00-13:30霹靂英雄：縹緲月、天道主霹靂COS：縹緲月、天道主霹靂英雄遊園 14:00-14:30霹靂英雄：素還真、一頁書霹靂COS：素還真、一頁書漫步梅林，欣賞布袋戲與COSPLAY的精彩魅力！ 迎新春揮毫 日期：1/4-1/5、1/11-1/12 時間：10:00 - 16:00 書法家現場揮毫，為新年祈福！⚠️ 數量有限，每人限領一份，送完為止！ 別錯過這場傳統與創意的完美結合！ 快攜家...', '桃園市政府', '桃園市336復興區角板山行館園區', '2025-01-04 00:00:00', '2025-01-12 23:59:59', '桃園市復興區', 24.81626, 121.34889, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 角板山梅花季', `description`='✨ 霹靂布袋戲 X 迎新春揮毫 ✨ 2025探索北橫冬季活動 | 梅好時光 騎趣角板  地點：角板山行館(桃園市復興區中正路133-1號)️ 活動日期：2025年1月4日(六)至1月12日(日)⏰ 時間：上午10:00 - 下午16:00✨ 交通資訊，讓你輕鬆到場！ 大眾運輸建議 桃園客運： 桃園總站搭乘 502 台灣好行小烏來線 或 506 東眼山線，直接抵達角板山行館！ 大溪客運總站搭乘以下路線：5106、5106A、5104、5104A、5109、5093、5105、5094。✨ 停車場資訊若自行開車，建議停放以下地點： 上台地停車場：https://maps.app.goo.gl/HEYLGgHn7NMCfWk49 仁愛停車場：https://maps.app.goo.gl/zeNtWdhyenLYi7M9A 羅浮高中停車場：https://maps.app.goo.gl/Lv7cPtZgpZZFAK3V8 搭乘大眾運輸，不僅環保又便利，讓我們一起支持綠色出行！快約家人朋友，一起來角板山行館感受梅花季的迷人魅力吧！ ✨ 1/4 特別企劃：霹靂布袋戲 梅林獻蹤 時間：10:00 - 15:00一場結合傳統與創意的視覺饗宴！邀請霹靂布袋戲經典角色素還真與一頁書 大偶隆重登場，搭配無限人形COSPLAY團隊 精彩演出，帶來不同凡響的文化體驗！開幕記者會 10:30-11:30霹靂英雄：刀說素還真、刀說一頁書霹靂COS：刀說素還真、刀說一頁書、縹緲月、天道主靂英雄遊園 13:00-13:30霹靂英雄：縹緲月、天道主霹靂COS：縹緲月、天道主霹靂英雄遊園 14:00-14:30霹靂英雄：素還真、一頁書霹靂COS：素還真、一頁書漫步梅林，欣賞布袋戲與COSPLAY的精彩魅力！ 迎新春揮毫 日期：1/4-1/5、1/11-1/12 時間：10:00 - 16:00 書法家現場揮毫，為新年祈福！⚠️ 數量有限，每人限領一份，送完為止！ 別錯過這場傳統與創意的完美結合！ 快攜家...', `organizer`='桃園市政府', `address`='桃園市336復興區角板山行館園區', `start_date`='2025-01-04 00:00:00', `end_date`='2025-01-12 23:59:59', `location`='桃園市復興區', `latitude`=24.81626, `longitude`=121.34889, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005191', '2025龍潭迎古董接財神', '￭相關細節可電洽龍潭區公所(03-4793070#2309)「2025龍潭迎古董接財神」分別在2月8日及9日在龍潭運動公園及龍元宮舉辦「迎古董」是早期農村過年時，龍潭上街及下街居民以踩街遊行方式展現的庶民文化，從日本昭和年間至今不曾間斷，成為龍潭地區傳統百年慶典；「接財神」活動為龍潭龍元宮一年一度元宵盛大活動，自96年起「迎古董」與「接財神」活動結合，每年都受到民眾熱烈歡迎，成為龍潭在地特色活動。', '桃園市政府', '桃園市325龍潭區龍元宮', '2025-02-08 00:00:00', '2025-02-09 23:59:59', '桃園市龍潭區', 24.86528, 121.21393, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025龍潭迎古董接財神', `description`='￭相關細節可電洽龍潭區公所(03-4793070#2309)「2025龍潭迎古董接財神」分別在2月8日及9日在龍潭運動公園及龍元宮舉辦「迎古董」是早期農村過年時，龍潭上街及下街居民以踩街遊行方式展現的庶民文化，從日本昭和年間至今不曾間斷，成為龍潭地區傳統百年慶典；「接財神」活動為龍潭龍元宮一年一度元宵盛大活動，自96年起「迎古董」與「接財神」活動結合，每年都受到民眾熱烈歡迎，成為龍潭在地特色活動。', `organizer`='桃園市政府', `address`='桃園市325龍潭區龍元宮', `start_date`='2025-02-08 00:00:00', `end_date`='2025-02-09 23:59:59', `location`='桃園市龍潭區', `latitude`=24.86528, `longitude`=121.21393, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005192', '2025客家天穿日', '￭相關細節可電洽客家事務局(03-4096682#2005)「天穿日」是客家族群獨有的文化節慶，舊時相傳水神與火神相爭，將天撞出一個大洞，女媧為免去人間災苦，於是煉五色石補天，客家人感念女媧的幫助，每逢「天穿日」男不耕田，女不織布，以唱歌娛樂方式度過，並藉此感謝上天。以現代觀點來看，「天穿日」的意義在於適度給予大自然休養恢復的時間，體現讓環境生生不息、資源永續發展的精神。祭天儀式活動時間：2025/2/17(一)09:30-10:30活動地點：桃園市客家文化館假日廣場(龍潭區中正路三林段500號)三獻禮是傳統祭祀儀式之一，常用於祭天、祭祖等重要典禮，象徵敬天禮神、表達感恩與祈福之意。儀式分為三個階段，分別獻上清茶、美酒與牲禮，代表不同的祝禱與敬意。 初獻｜獻清茶，象徵虔誠敬意，感念天地恩澤。 亞獻｜獻美酒，代表祝福與誠心祈求風調雨順、國泰民安。 終獻｜獻牲禮（如三牲或五牲），表達最高敬意，祈求平安豐收。在天穿日祭天儀式中，三獻禮是核心儀式之一，藉此感謝女媧補天護佑蒼生，也為新的一年祈求好運與祥和。', '桃園市政府', '桃園市325龍潭區中正路三林段500號', '2025-02-17 00:00:00', '2025-02-17 23:59:59', '桃園市龍潭區', 24.8459, 121.23409, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025客家天穿日', `description`='￭相關細節可電洽客家事務局(03-4096682#2005)「天穿日」是客家族群獨有的文化節慶，舊時相傳水神與火神相爭，將天撞出一個大洞，女媧為免去人間災苦，於是煉五色石補天，客家人感念女媧的幫助，每逢「天穿日」男不耕田，女不織布，以唱歌娛樂方式度過，並藉此感謝上天。以現代觀點來看，「天穿日」的意義在於適度給予大自然休養恢復的時間，體現讓環境生生不息、資源永續發展的精神。祭天儀式活動時間：2025/2/17(一)09:30-10:30活動地點：桃園市客家文化館假日廣場(龍潭區中正路三林段500號)三獻禮是傳統祭祀儀式之一，常用於祭天、祭祖等重要典禮，象徵敬天禮神、表達感恩與祈福之意。儀式分為三個階段，分別獻上清茶、美酒與牲禮，代表不同的祝禱與敬意。 初獻｜獻清茶，象徵虔誠敬意，感念天地恩澤。 亞獻｜獻美酒，代表祝福與誠心祈求風調雨順、國泰民安。 終獻｜獻牲禮（如三牲或五牲），表達最高敬意，祈求平安豐收。在天穿日祭天儀式中，三獻禮是核心儀式之一，藉此感謝女媧補天護佑蒼生，也為新的一年祈求好運與祥和。', `organizer`='桃園市政府', `address`='桃園市325龍潭區中正路三林段500號', `start_date`='2025-02-17 00:00:00', `end_date`='2025-02-17 23:59:59', `location`='桃園市龍潭區', `latitude`=24.8459, `longitude`=121.23409, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005193', '2025台灣燈會', '￭相關內容請洽本局行銷科03-3322101#6202「2025台灣燈會」在桃園將以「光聚千塘串桃園」打造親子與文化結合的光影盛宴，透過桃園眾多埤塘如鏡面般的水面，映照出桃園的城市樣貌，閃閃發光的埤塘如同燈飾作品訴說著地方故事，透過燈藝串連桃園地方特色，營造一個光影交織的幸福城市。2025台灣燈會在桃園於2025年2月12日至2月23日、在機場捷運A18高鐵桃園站前廣場、A19桃園體育園區站周邊兩大展區登場2025台灣燈會在桃園，將透過燈藝，串連地方特色，帶來一年一度為期12天限定的光影展演更多詳情資訊⇛2025台灣燈會主網站。主題展區01｜A18主燈展演場地點｜機場捷運A18高鐵桃園站前廣場作品數量｜1座主燈、2大副燈、6大燈區以「無限樂園」為主題，融合抽象概念與創新科技，呈現變化萬千的視覺效果，讓你感受科技與藝術的完美交織。其中，更將「棒球場造型」融入燈區的配置，讓大家有新奇的樂趣與體驗，並讓2025臺灣燈會持續在世界發光發亮。主燈：由藝術家李明道（AKIBO）設計，以無限符號結合幾何造型，打造科技感十足的未來樂園主燈高度18公尺，融合AI動態捕捉技術，呈現千變萬化的視覺效果，絕對讓你耳目一新✨主題展區02｜A19光的遊戲場地點｜A19桃園體育園區站周邊作品數量｜5大燈區，30+作品以親子與遊戲為主題氛圍，包含活力發光站、青春光劇場、城市聚光燈、光臨千塘國及福光滿意讚5大燈區，打造「桃園親子城」。燈會專屬吉祥物：以桃子心型象徵桃園埤塘的自然意象，推出糖塘、皮埤、串串、毛毛、光光、籠龍等，6款代表燈會精神的吉祥物，設計靈感來自桃園埤塘的自然環境，結合燈會5大展區的主題，透過桃埤輪廓、桃心眼睛、葉腳倒影及埤塘光影構成形象，展現桃園的多元樣貌。2025台灣燈會-主燈&小提燈 繽紛亮相以今年的生肖「蛇」進行設計，蛇身由7段可動結構組成，可變換數字或各種造型！因為蛇在生肖中排序第六，「蹓蹓蛇」取諧音「六」，邀請大家多外出蹓蹓，一起來桃園逛燈會！半數小提燈製作成以外接行動電源發光之燈具，只需TYPE-C連接行動電源就能發亮，永續又環保！2025台灣燈會即將於2月7日...', '桃園市政府', '桃園市320中壢區高鐵站前廣場', '2025-02-12 00:00:00', '2025-02-23 23:59:59', '桃園市中壢區', 25.01192, 121.21626, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會', `description`='￭相關內容請洽本局行銷科03-3322101#6202「2025台灣燈會」在桃園將以「光聚千塘串桃園」打造親子與文化結合的光影盛宴，透過桃園眾多埤塘如鏡面般的水面，映照出桃園的城市樣貌，閃閃發光的埤塘如同燈飾作品訴說著地方故事，透過燈藝串連桃園地方特色，營造一個光影交織的幸福城市。2025台灣燈會在桃園於2025年2月12日至2月23日、在機場捷運A18高鐵桃園站前廣場、A19桃園體育園區站周邊兩大展區登場2025台灣燈會在桃園，將透過燈藝，串連地方特色，帶來一年一度為期12天限定的光影展演更多詳情資訊⇛2025台灣燈會主網站。主題展區01｜A18主燈展演場地點｜機場捷運A18高鐵桃園站前廣場作品數量｜1座主燈、2大副燈、6大燈區以「無限樂園」為主題，融合抽象概念與創新科技，呈現變化萬千的視覺效果，讓你感受科技與藝術的完美交織。其中，更將「棒球場造型」融入燈區的配置，讓大家有新奇的樂趣與體驗，並讓2025臺灣燈會持續在世界發光發亮。主燈：由藝術家李明道（AKIBO）設計，以無限符號結合幾何造型，打造科技感十足的未來樂園主燈高度18公尺，融合AI動態捕捉技術，呈現千變萬化的視覺效果，絕對讓你耳目一新✨主題展區02｜A19光的遊戲場地點｜A19桃園體育園區站周邊作品數量｜5大燈區，30+作品以親子與遊戲為主題氛圍，包含活力發光站、青春光劇場、城市聚光燈、光臨千塘國及福光滿意讚5大燈區，打造「桃園親子城」。燈會專屬吉祥物：以桃子心型象徵桃園埤塘的自然意象，推出糖塘、皮埤、串串、毛毛、光光、籠龍等，6款代表燈會精神的吉祥物，設計靈感來自桃園埤塘的自然環境，結合燈會5大展區的主題，透過桃埤輪廓、桃心眼睛、葉腳倒影及埤塘光影構成形象，展現桃園的多元樣貌。2025台灣燈會-主燈&小提燈 繽紛亮相以今年的生肖「蛇」進行設計，蛇身由7段可動結構組成，可變換數字或各種造型！因為蛇在生肖中排序第六，「蹓蹓蛇」取諧音「六」，邀請大家多外出蹓蹓，一起來桃園逛燈會！半數小提燈製作成以外接行動電源發光之燈具，只需TYPE-C連接行動電源就能發亮，永續又環保！2025台灣燈會即將於2月7日...', `organizer`='桃園市政府', `address`='桃園市320中壢區高鐵站前廣場', `start_date`='2025-02-12 00:00:00', `end_date`='2025-02-23 23:59:59', `location`='桃園市中壢區', `latitude`=25.01192, `longitude`=121.21626, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005194', '2025探索北橫春季活動-大龍門X櫻花勇士自行車活動', '￭相關細節可電洽風景管理處(03-3946061#123)2025北橫櫻花漫步地圖來囉～巴陵地區櫻花花況預估可參考「2025北橫櫻花漫步地圖」又到了一年一度的北橫櫻花季啦！過年期間北橫沿線山櫻花盛開，著實美不勝收！山櫻花後接著是粉色昭和櫻、富士櫻、千島櫻，多品種櫻花正含苞待放，想一睹櫻吹雪的朋友們，把握時機，規劃一場桃園北橫浪漫之旅吧！今年度巴陵地區賞櫻熱門景點，包含中心路的富士櫻預計將於2月15日至3月5日盛開、光華櫻花故事林道和中巴陵地區櫻木花道昭和櫻與拉拉山遊客中心周邊的吉野櫻預估將在2月15日至2月28日開花，中心路的千島櫻預估2月25日至3月15日盛開，而拉拉遊客中心附近的千島櫻預計在3月1日至3月20日盛開。實際花期受天候因素影響出發前可參考「遊桃園APP」掌握交通狀況2025探索北橫春季活動，自行車探索北橫與大龍門春季北橫的代表花卉是櫻花，平地的山櫻花、下巴陵至上巴陵昭和櫻、千島櫻等等不同品種櫻花陸續綻放至3月，這個時節氣候宜人，非常適合以騎自行車的方式漫遊北橫!今年度市府持續規劃2條不同難易度的【挑戰極限，馳騁櫻花海】X【萌運動family go】自行車活動，希望讓每一位喜歡自行車的大小朋友們都能感受到我們桃園山林風光的魅力!【挑戰極限，馳騁櫻花海】活動時間：2025年3月8日(六)~3月9日(日)每日07:00-14:00。活動地點：慈湖遊客中心（起站）&rarr;羅浮聖興宮（補給站）&rarr;拉拉山遊客中心（訖站）。報到時間：06:10-07:00，請攜帶本人身分證件，配合工作人員核對身分。報到地點：慈湖遊客中心(慈湖導覽服務站旁)2025探索北橫春季活動&mdash;櫻花勇士單車完騎認證登場！從慈湖遊客中心出發，沿著壯麗的北橫公路，穿梭於山巒與櫻花盛景間，最終抵達拉拉山遊客中心。一路上您將欣賞到櫻花的迷人美景，感受如畫春日的騎行樂趣。這是一場結合挑戰、賞櫻與在地風味的騎行體驗，邀您探索北橫，成為下一位櫻花勇士！【萌運動family go】活動時間：2025年3月15日(六)09:00-16:00...', '桃園市政府', '桃園市335大溪區桃園市大溪區復興路一段1097號', '2025-03-08 00:00:00', '2025-03-15 23:59:59', '桃園市大溪區', 24.84055, 121.29187, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025探索北橫春季活動-大龍門X櫻花勇士自行車活動', `description`='￭相關細節可電洽風景管理處(03-3946061#123)2025北橫櫻花漫步地圖來囉～巴陵地區櫻花花況預估可參考「2025北橫櫻花漫步地圖」又到了一年一度的北橫櫻花季啦！過年期間北橫沿線山櫻花盛開，著實美不勝收！山櫻花後接著是粉色昭和櫻、富士櫻、千島櫻，多品種櫻花正含苞待放，想一睹櫻吹雪的朋友們，把握時機，規劃一場桃園北橫浪漫之旅吧！今年度巴陵地區賞櫻熱門景點，包含中心路的富士櫻預計將於2月15日至3月5日盛開、光華櫻花故事林道和中巴陵地區櫻木花道昭和櫻與拉拉山遊客中心周邊的吉野櫻預估將在2月15日至2月28日開花，中心路的千島櫻預估2月25日至3月15日盛開，而拉拉遊客中心附近的千島櫻預計在3月1日至3月20日盛開。實際花期受天候因素影響出發前可參考「遊桃園APP」掌握交通狀況2025探索北橫春季活動，自行車探索北橫與大龍門春季北橫的代表花卉是櫻花，平地的山櫻花、下巴陵至上巴陵昭和櫻、千島櫻等等不同品種櫻花陸續綻放至3月，這個時節氣候宜人，非常適合以騎自行車的方式漫遊北橫!今年度市府持續規劃2條不同難易度的【挑戰極限，馳騁櫻花海】X【萌運動family go】自行車活動，希望讓每一位喜歡自行車的大小朋友們都能感受到我們桃園山林風光的魅力!【挑戰極限，馳騁櫻花海】活動時間：2025年3月8日(六)~3月9日(日)每日07:00-14:00。活動地點：慈湖遊客中心（起站）&rarr;羅浮聖興宮（補給站）&rarr;拉拉山遊客中心（訖站）。報到時間：06:10-07:00，請攜帶本人身分證件，配合工作人員核對身分。報到地點：慈湖遊客中心(慈湖導覽服務站旁)2025探索北橫春季活動&mdash;櫻花勇士單車完騎認證登場！從慈湖遊客中心出發，沿著壯麗的北橫公路，穿梭於山巒與櫻花盛景間，最終抵達拉拉山遊客中心。一路上您將欣賞到櫻花的迷人美景，感受如畫春日的騎行樂趣。這是一場結合挑戰、賞櫻與在地風味的騎行體驗，邀您探索北橫，成為下一位櫻花勇士！【萌運動family go】活動時間：2025年3月15日(六)09:00-16:00...', `organizer`='桃園市政府', `address`='桃園市335大溪區桃園市大溪區復興路一段1097號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-03-15 23:59:59', `location`='桃園市大溪區', `latitude`=24.84055, `longitude`=121.29187, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005195', '2025魯冰花季', '￭相關細節可電洽本府客家事務局 (03-4096682#6009)以能量、療癒為主軸 歡迎大家一同來到這裡享受最純粹的魯冰花饗宴。大北坑休閒農業區位於龍潭客庄重要茶區，山谷丘陵交錯茶園遍佈，擁有豐富的自然生態、歷史人文建築及客語藝術磚牆，是體驗滿山好茶、慢活美學的好地方。大北坑被視為最早種植魯冰花的地區，有「魯冰花的故鄉」之稱，每年2、3月間，金黃色的魯冰花在茶樹間綻放，讓客庄茶山大地生生不息，萬物與環境永續。活動日期：2025/2/28~2025/3/7活動地點：(1)龍潭大北坑展區:三水水土保持戶外教室停車場(2)臺灣客家茶文化館展區:臺灣客家茶文化館(桃園市龍潭區高原里高原路768號)活動官網:2025桃園魯冰花季', '桃園市政府', '桃園市325龍潭區大北坑街1998巷8號', '2025-02-28 00:00:00', '2025-03-07 23:59:59', '桃園市龍潭區', 24.87197, 121.16526, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025魯冰花季', `description`='￭相關細節可電洽本府客家事務局 (03-4096682#6009)以能量、療癒為主軸 歡迎大家一同來到這裡享受最純粹的魯冰花饗宴。大北坑休閒農業區位於龍潭客庄重要茶區，山谷丘陵交錯茶園遍佈，擁有豐富的自然生態、歷史人文建築及客語藝術磚牆，是體驗滿山好茶、慢活美學的好地方。大北坑被視為最早種植魯冰花的地區，有「魯冰花的故鄉」之稱，每年2、3月間，金黃色的魯冰花在茶樹間綻放，讓客庄茶山大地生生不息，萬物與環境永續。活動日期：2025/2/28~2025/3/7活動地點：(1)龍潭大北坑展區:三水水土保持戶外教室停車場(2)臺灣客家茶文化館展區:臺灣客家茶文化館(桃園市龍潭區高原里高原路768號)活動官網:2025桃園魯冰花季', `organizer`='桃園市政府', `address`='桃園市325龍潭區大北坑街1998巷8號', `start_date`='2025-02-28 00:00:00', `end_date`='2025-03-07 23:59:59', `location`='桃園市龍潭區', `latitude`=24.87197, `longitude`=121.16526, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005196', '2025彩色海芋季-奇芋夢幻島', '￭相關細節可電洽本府農業局(03-3322101#5415、5416)「2025桃園彩色海芋季」將於3月29日（六）至4月6日（日 ）在桃園大園溪海休閒農業區盛大回歸，為期9天的花卉盛會以「奇 芋夢幻島」為主題，現場種植彩色海芋、百合、孤挺花、小蒼蘭及各 式草花，共超過14萬株花卉，邀請您徜徉浪漫花海，共享溪海之美 。大園溪海為北台灣草花主要生產地，活動會場種植大面積 彩色海芋、百合、孤挺花、小蒼蘭、可食地景與各式草花， 以大園溪海豐富的花卉特產為核心，帶領民眾認識百花環繞、 優美芬芳的溪海。活動以農業三生架構-生產、生態、生活為發想， 設置巨型裝置藝術，並結合有趣的農場體驗活動， 最美最好玩的溪海農遊旅程即將展開！活動日期：2025/3/29~2025/4/6活動地點：桃園市大園區溪海休閒農業區', '桃園市政府', '桃園市337大園區溪海休閒農業區', '2025-03-29 00:00:00', '2025-04-06 23:59:59', '桃園市大園區', 25.03296, 121.19547, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025彩色海芋季-奇芋夢幻島', `description`='￭相關細節可電洽本府農業局(03-3322101#5415、5416)「2025桃園彩色海芋季」將於3月29日（六）至4月6日（日 ）在桃園大園溪海休閒農業區盛大回歸，為期9天的花卉盛會以「奇 芋夢幻島」為主題，現場種植彩色海芋、百合、孤挺花、小蒼蘭及各 式草花，共超過14萬株花卉，邀請您徜徉浪漫花海，共享溪海之美 。大園溪海為北台灣草花主要生產地，活動會場種植大面積 彩色海芋、百合、孤挺花、小蒼蘭、可食地景與各式草花， 以大園溪海豐富的花卉特產為核心，帶領民眾認識百花環繞、 優美芬芳的溪海。活動以農業三生架構-生產、生態、生活為發想， 設置巨型裝置藝術，並結合有趣的農場體驗活動， 最美最好玩的溪海農遊旅程即將展開！活動日期：2025/3/29~2025/4/6活動地點：桃園市大園區溪海休閒農業區', `organizer`='桃園市政府', `address`='桃園市337大園區溪海休閒農業區', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-06 23:59:59', `location`='桃園市大園區', `latitude`=25.03296, `longitude`=121.19547, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005197', '2025龍岡米干節', '￭相關細節可電洽本局行銷科(03-3322101#6202)2025桃園龍岡米干節 4/19~4/27盛大登場大家引頸期盼的潑水大戰今年熱鬧回歸;白天還有傳統踩街、打歌、文化小旅行、特色美食等你來體驗;晚上玩龍岡更精彩,火把狂歡夜及多元文化表演等驚喜節目,力與美的震撼演出 你絕不能錯過。水花火舞 X 滇緬文化 來桃園龍岡享受這場國際級的盛會吧!2025桃園龍岡米干節日期|4/19(六)-4/27(日)地點|忠貞新村文化園區、雲南文化公園', '桃園市政府', '桃園市324平鎮區忠貞新村文化園區', '2025-04-19 00:00:00', '2025-04-27 23:59:59', '桃園市平鎮區', 24.92763, 121.25433, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025龍岡米干節', `description`='￭相關細節可電洽本局行銷科(03-3322101#6202)2025桃園龍岡米干節 4/19~4/27盛大登場大家引頸期盼的潑水大戰今年熱鬧回歸;白天還有傳統踩街、打歌、文化小旅行、特色美食等你來體驗;晚上玩龍岡更精彩,火把狂歡夜及多元文化表演等驚喜節目,力與美的震撼演出 你絕不能錯過。水花火舞 X 滇緬文化 來桃園龍岡享受這場國際級的盛會吧!2025桃園龍岡米干節日期|4/19(六)-4/27(日)地點|忠貞新村文化園區、雲南文化公園', `organizer`='桃園市政府', `address`='桃園市324平鎮區忠貞新村文化園區', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-27 23:59:59', `location`='桃園市平鎮區', `latitude`=24.92763, `longitude`=121.25433, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005198', '2025桃園客家桐花祭', '￭活動相關細節可電洽本府客家事務局 (03-4096682#6008)2025桃園桐花祭活動自4月19日至5月4日，結合桃園兒童節系列活動特別打造全臺唯一兒童版桐花祭「桐花童話」，以兒童童趣視角詮釋桐花與客庄文化，以「537一起賞桐趣」為主題，串聯桃園五大賞桐區域、三大桐樂會場、七條賞桐小旅行，並推出兒童專屬企劃「親子桐樂之旅」，提供專屬孩童的互動體驗，包括兒童版客家紅粄手作、客庄文化闖關遊戲等，讓孩子們在動手做與探索中學習傳統文化。滿滿兒童專屬桐花客庄體驗、音樂、美食及童趣氛圍拍照裝置，4/19在桃園市客家文化館舉辦「2025桃園桐花祭-桐花童話」伯公祭儀暨開幕式，透過桐花祭遍地開花串聯結合客家文化館、龍潭三和社區及楊梅上湖社區等推出4/26龍潭桐樂會、4/27楊梅桐樂會三處「桐樂會」活動場地打造親子家庭沉浸式賞桐體驗。「桐花童話」的活動內容豐富多元，包含熱鬧的客庄市集、不插電音樂會、阿弟阿妹見面會、趣味闖關遊戲、客家米食與茶席體驗、親子著色趣、深度走讀桐花之旅等，讓親子家庭在輕鬆愉悅的氛圍中，深度體驗客庄文化。此外推出「賞桐秘境數位集章活動」，市民可透過官方指定平台，在五大賞桐區域內的秘境完成數位集章，並拍照打卡，即可兌換限量好禮。詳細旅遊資訊請至活動官網或桃園桐花祭臉書粉絲專頁(https://www.facebook.com/ty.hakka.tung)查詢。', '桃園市政府', '桃園市325龍潭區中正路三林段500號', '2025-04-19 00:00:00', '2025-05-04 23:59:59', '桃園市龍潭區', 24.8459, 121.23409, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025桃園客家桐花祭', `description`='￭活動相關細節可電洽本府客家事務局 (03-4096682#6008)2025桃園桐花祭活動自4月19日至5月4日，結合桃園兒童節系列活動特別打造全臺唯一兒童版桐花祭「桐花童話」，以兒童童趣視角詮釋桐花與客庄文化，以「537一起賞桐趣」為主題，串聯桃園五大賞桐區域、三大桐樂會場、七條賞桐小旅行，並推出兒童專屬企劃「親子桐樂之旅」，提供專屬孩童的互動體驗，包括兒童版客家紅粄手作、客庄文化闖關遊戲等，讓孩子們在動手做與探索中學習傳統文化。滿滿兒童專屬桐花客庄體驗、音樂、美食及童趣氛圍拍照裝置，4/19在桃園市客家文化館舉辦「2025桃園桐花祭-桐花童話」伯公祭儀暨開幕式，透過桐花祭遍地開花串聯結合客家文化館、龍潭三和社區及楊梅上湖社區等推出4/26龍潭桐樂會、4/27楊梅桐樂會三處「桐樂會」活動場地打造親子家庭沉浸式賞桐體驗。「桐花童話」的活動內容豐富多元，包含熱鬧的客庄市集、不插電音樂會、阿弟阿妹見面會、趣味闖關遊戲、客家米食與茶席體驗、親子著色趣、深度走讀桐花之旅等，讓親子家庭在輕鬆愉悅的氛圍中，深度體驗客庄文化。此外推出「賞桐秘境數位集章活動」，市民可透過官方指定平台，在五大賞桐區域內的秘境完成數位集章，並拍照打卡，即可兌換限量好禮。詳細旅遊資訊請至活動官網或桃園桐花祭臉書粉絲專頁(https://www.facebook.com/ty.hakka.tung)查詢。', `organizer`='桃園市政府', `address`='桃園市325龍潭區中正路三林段500號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-05-04 23:59:59', `location`='桃園市龍潭區', `latitude`=24.8459, `longitude`=121.23409, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005199', '2025台灣燈會在桃園｜蘆竹炫YA農遊季', '￭相關細節可電洽蘆竹區公所(03-3520000#133)今年為響應2025台灣燈會在桃園，以往在夏天舉辦的「蘆竹炫YA農遊季」提前至2月7日至3月31日開跑，延續台灣燈會的主視覺，巧妙結合大古山步道公園地勢與自然環境，融入春節、十二生肖、農曆蛇年、西洋情人節、科技互動等意象，打造17組沉浸式光影藝術作品，期間每晚6點到10點亮燈。2025台灣燈會在桃園暨蘆竹炫YA農遊季活動時間：2月7日至3月31日點燈時間：每日晚間6點至10點活動地點：1.桃園市蘆竹區大古山登山步道公園（地址：桃園市蘆竹區大古路228號）2.桃園市蘆竹區公所周邊（地址：桃園市蘆竹區南崁路150號）交通管制:管制期間：114年2月7日至3月31日，每週五、六、日 17:30 - 22:30管制措施：大古路 (大古路與泉州路口至國寶廟) 禁止臨時停車。管制期間將加強取締違規停車，請配合現場交通疏導措施。因活動現場停車位有限 (1. 福山宮前廣場停車場 2. 福山宮下私人場地)，建議於泉州路停車並步行約20分鐘至展區。', '桃園市政府', '桃園市338蘆竹區大古路228號', '2025-02-07 00:00:00', '2025-03-31 23:59:59', '桃園市蘆竹區', 25.10112, 121.29047, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台灣燈會在桃園｜蘆竹炫YA農遊季', `description`='￭相關細節可電洽蘆竹區公所(03-3520000#133)今年為響應2025台灣燈會在桃園，以往在夏天舉辦的「蘆竹炫YA農遊季」提前至2月7日至3月31日開跑，延續台灣燈會的主視覺，巧妙結合大古山步道公園地勢與自然環境，融入春節、十二生肖、農曆蛇年、西洋情人節、科技互動等意象，打造17組沉浸式光影藝術作品，期間每晚6點到10點亮燈。2025台灣燈會在桃園暨蘆竹炫YA農遊季活動時間：2月7日至3月31日點燈時間：每日晚間6點至10點活動地點：1.桃園市蘆竹區大古山登山步道公園（地址：桃園市蘆竹區大古路228號）2.桃園市蘆竹區公所周邊（地址：桃園市蘆竹區南崁路150號）交通管制:管制期間：114年2月7日至3月31日，每週五、六、日 17:30 - 22:30管制措施：大古路 (大古路與泉州路口至國寶廟) 禁止臨時停車。管制期間將加強取締違規停車，請配合現場交通疏導措施。因活動現場停車位有限 (1. 福山宮前廣場停車場 2. 福山宮下私人場地)，建議於泉州路停車並步行約20分鐘至展區。', `organizer`='桃園市政府', `address`='桃園市338蘆竹區大古路228號', `start_date`='2025-02-07 00:00:00', `end_date`='2025-03-31 23:59:59', `location`='桃園市蘆竹區', `latitude`=25.10112, `longitude`=121.29047, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005200', '2025花現台七', '￭相關細節可電洽本府農業局(03-3322101#5415、5416)活動內容尚待主辦單位公佈復興區是北台灣重要的花卉產區，聖誕紅、繡球花等重要盆花攸關當地重要產業命脈；大溪區百吉休閒農業區擁有北台灣規模最大金針花海，本案以北橫公路作為主要幹道，藉由活動串聯台七桃花源休閒農業區及百吉休閒農業區特色花卉、農場及遊程，並規劃串聯兩休區的接駁巴士及主題農遊小旅行，在賞花之餘，體驗農遊樂趣。活動日期：2025/5/10~2025/5/25活動地點：（1）台七桃花源休閒農業區遊客中心(桃園市復興區三民里丸山3之21號)（2）桃園百吉休閒農業發展協會【體驗園區】(桃園市大溪區環湖路二段688-1號)', '桃園市政府', '桃園市335大溪區環湖路二段688-1號', '2025-05-10 00:00:00', '2025-05-25 23:59:59', '桃園市大溪區', 24.8197, 121.3106, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025花現台七', `description`='￭相關細節可電洽本府農業局(03-3322101#5415、5416)活動內容尚待主辦單位公佈復興區是北台灣重要的花卉產區，聖誕紅、繡球花等重要盆花攸關當地重要產業命脈；大溪區百吉休閒農業區擁有北台灣規模最大金針花海，本案以北橫公路作為主要幹道，藉由活動串聯台七桃花源休閒農業區及百吉休閒農業區特色花卉、農場及遊程，並規劃串聯兩休區的接駁巴士及主題農遊小旅行，在賞花之餘，體驗農遊樂趣。活動日期：2025/5/10~2025/5/25活動地點：（1）台七桃花源休閒農業區遊客中心(桃園市復興區三民里丸山3之21號)（2）桃園百吉休閒農業發展協會【體驗園區】(桃園市大溪區環湖路二段688-1號)', `organizer`='桃園市政府', `address`='桃園市335大溪區環湖路二段688-1號', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-25 23:59:59', `location`='桃園市大溪區', `latitude`=24.8197, `longitude`=121.3106, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005201', '114年度原住民族歲時祭儀（5-11月）', '￭相關內容請洽本府原住民族行政局 03-3322101#6684、#6685活動內容尚待主辦單位公佈✨桃園市是擁有完整16族原住民族群的多元文化城市，轄內原住民族人口數已達8萬多人，是全國六都中原住民人口最多的直轄市，已成為原住民族的新故鄉，為落實及延續原住民族傳統文化扎根與傳承之目的，桃園市每年5月至11月舉辦轄內12行政區豐年祭及11族原住民族群歲時祭儀活動，以促進本市原住民族人之自我認同並提升各族群間之凝聚力。✨為積極行銷桃園市12區豐年祭及11族原住民族群歲時祭儀活動，首次規劃本次聯合宣傳行銷計畫，除了舉辦活動行銷記者會外，透過網路媒體及電子化平台等多樣化之宣傳管道，使民眾得以即時掌握活動相關訊息，進而提升全國民眾前來桃園參與之意願。', '桃園市政府', '桃園市320中壢區原住民集會所', '2025-05-03 00:00:00', '2025-11-09 23:59:59', '桃園市中壢區', 24.97644, 121.25414, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度原住民族歲時祭儀（5-11月）', `description`='￭相關內容請洽本府原住民族行政局 03-3322101#6684、#6685活動內容尚待主辦單位公佈✨桃園市是擁有完整16族原住民族群的多元文化城市，轄內原住民族人口數已達8萬多人，是全國六都中原住民人口最多的直轄市，已成為原住民族的新故鄉，為落實及延續原住民族傳統文化扎根與傳承之目的，桃園市每年5月至11月舉辦轄內12行政區豐年祭及11族原住民族群歲時祭儀活動，以促進本市原住民族人之自我認同並提升各族群間之凝聚力。✨為積極行銷桃園市12區豐年祭及11族原住民族群歲時祭儀活動，首次規劃本次聯合宣傳行銷計畫，除了舉辦活動行銷記者會外，透過網路媒體及電子化平台等多樣化之宣傳管道，使民眾得以即時掌握活動相關訊息，進而提升全國民眾前來桃園參與之意願。', `organizer`='桃園市政府', `address`='桃園市320中壢區原住民集會所', `start_date`='2025-05-03 00:00:00', `end_date`='2025-11-09 23:59:59', `location`='桃園市中壢區', `latitude`=24.97644, `longitude`=121.25414, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005202', '2025桃園管樂嘉年華', '￭相關內容請洽本府文化局03-3322592#8304活動內容尚待主辦單位公佈「桃園管樂嘉年華」是桃園市年度重要的音樂盛事，通常於每年5月至6月間舉行。活動結合國內外知名管樂團體、學校樂團與地方特色，帶來多場精彩的戶外音樂會、熱鬧的街頭遊行、親子互動活動及主題音樂市集，適合全家大小一同參與。無論是喜愛古典音樂、爵士樂，還是流行旋律，桃園管樂嘉年華都能滿足您的期待，讓音樂為城市增添更多活力與感動！', '桃園市政府', '桃園市330桃園區中正路1188號', '2025-05-30 00:00:00', '2025-06-08 23:59:59', '桃園市桃園區', 25.01751, 121.29867, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025桃園管樂嘉年華', `description`='￭相關內容請洽本府文化局03-3322592#8304活動內容尚待主辦單位公佈「桃園管樂嘉年華」是桃園市年度重要的音樂盛事，通常於每年5月至6月間舉行。活動結合國內外知名管樂團體、學校樂團與地方特色，帶來多場精彩的戶外音樂會、熱鬧的街頭遊行、親子互動活動及主題音樂市集，適合全家大小一同參與。無論是喜愛古典音樂、爵士樂，還是流行旋律，桃園管樂嘉年華都能滿足您的期待，讓音樂為城市增添更多活力與感動！', `organizer`='桃園市政府', `address`='桃園市330桃園區中正路1188號', `start_date`='2025-05-30 00:00:00', `end_date`='2025-06-08 23:59:59', `location`='桃園市桃園區', `latitude`=25.01751, `longitude`=121.29867, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005203', '2025桃園閩南文化節', '￭相關內容請洽本府文化局03-3322592#8521活動內容尚待主辦單位公佈桃園閩南文化節自2012年開辦，以多元活動形式詮釋傳統，同時藉由國際交流與發展論壇，發掘閩南文化更多可能，是桃園年度最盛大的閩南嘉年華盛會！', '桃園市政府', '桃園市334八德區八塊厝民俗藝術村', '2025-06-07 00:00:00', '2025-07-05 23:59:59', '桃園市八德區', 24.95482, 121.30162, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025桃園閩南文化節', `description`='￭相關內容請洽本府文化局03-3322592#8521活動內容尚待主辦單位公佈桃園閩南文化節自2012年開辦，以多元活動形式詮釋傳統，同時藉由國際交流與發展論壇，發掘閩南文化更多可能，是桃園年度最盛大的閩南嘉年華盛會！', `organizer`='桃園市政府', `address`='桃園市334八德區八塊厝民俗藝術村', `start_date`='2025-06-07 00:00:00', `end_date`='2025-07-05 23:59:59', `location`='桃園市八德區', `latitude`=24.95482, `longitude`=121.30162, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
