INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005205', '2025桃園蓮花季', '￭相關內容請洽本府農業局03-3322101#5415、5416活動內容尚待主辦單位公佈桃園市觀音區每年7月至8月期間為蓮花盛開季節，有「北觀音、南白河」美名，每年蓮花季活動結合周邊休閒農場、觀光蓮園，推出各項豐富有趣的農事體驗及一日遊套裝行程，同時提供許多在地蓮花相關農特產品、風味餐及其他衍生性商品。活動日期：2025/6/28~2025/8/3活動地點：桃園市觀音區觀音蓮花園休閒農業區', '桃園市政府', '桃園市328觀音區觀音蓮花園休閒農業區', '2025-06-28 00:00:00', '2025-08-03 23:59:59', '桃園市觀音區', 24.99836, 121.12201, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025桃園蓮花季', `description`='￭相關內容請洽本府農業局03-3322101#5415、5416活動內容尚待主辦單位公佈桃園市觀音區每年7月至8月期間為蓮花盛開季節，有「北觀音、南白河」美名，每年蓮花季活動結合周邊休閒農場、觀光蓮園，推出各項豐富有趣的農事體驗及一日遊套裝行程，同時提供許多在地蓮花相關農特產品、風味餐及其他衍生性商品。活動日期：2025/6/28~2025/8/3活動地點：桃園市觀音區觀音蓮花園休閒農業區', `organizer`='桃園市政府', `address`='桃園市328觀音區觀音蓮花園休閒農業區', `start_date`='2025-06-28 00:00:00', `end_date`='2025-08-03 23:59:59', `location`='桃園市觀音區', `latitude`=24.99836, `longitude`=121.12201, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005206', '114年度原住民族豐年祭（6-10月）', '￭相關內容請洽本府原住民族行政局 03-3322101#6684、#6685活動內容尚待主辦單位公佈本市各區原住民族的風貌皆有各異之美，豐年祭也在在展現原始開闊的生命力，更能從中觀賞到手工藝、服飾、傳統歌謠舞蹈，以及品嘗道地的風味餐。為傳承原住民族語言及文化永續扎根，以凝聚本市原住民族的向心力及認同，本市將舉辦各區原住民族暨市聯合原住民族豐年祭，讓族群之間更深入了解彼此文化之美。', '桃園市政府', '桃園市337大園區領航北路四段216號', '2025-06-07 00:00:00', '2025-10-26 23:59:59', '桃園市大園區', 25.02423, 121.21758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度原住民族豐年祭（6-10月）', `description`='￭相關內容請洽本府原住民族行政局 03-3322101#6684、#6685活動內容尚待主辦單位公佈本市各區原住民族的風貌皆有各異之美，豐年祭也在在展現原始開闊的生命力，更能從中觀賞到手工藝、服飾、傳統歌謠舞蹈，以及品嘗道地的風味餐。為傳承原住民族語言及文化永續扎根，以凝聚本市原住民族的向心力及認同，本市將舉辦各區原住民族暨市聯合原住民族豐年祭，讓族群之間更深入了解彼此文化之美。', `organizer`='桃園市政府', `address`='桃園市337大園區領航北路四段216號', `start_date`='2025-06-07 00:00:00', `end_date`='2025-10-26 23:59:59', `location`='桃園市大園區', `latitude`=25.02423, `longitude`=121.21758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
