INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005211', '2025桃園藝術巡演新屋場-即將成真火舞團《火爾摩沙傳奇Firemosa》火舞劇', '￭相關細節可電洽本府文化局(03-3322592#8313)活動節目：即將成真火舞團《火爾摩沙傳奇Firemosa》火舞劇活動時間：114年4月11日(星期五) 19:00-20:30活動地點：永安保生宮(桃園市新屋區保生路51號) 演出團隊：「即將成真火舞團」由兩位全國火舞比賽冠軍舞者郭彥甫與蔡宏毅於2014年共同創立，是目前台灣唯一表演「火劇」的職業舞團。該團於2015至2016年間曾代表台灣挑戰「亞洲達人秀」、「中國達人秀」等大型選秀比賽，並將觸角伸及世界，受邀於亞洲、歐洲各大藝術祭；2018年初在嘉義台灣燈會帶來了長達45分鐘的原創火劇，場場滿座，廣受好評；2020年於總統府前亮點演出等。節目簡介：「FireMosa」是一齣結合民俗技藝與藝陣的戶外傳奇火舞劇，以氣勢磅礴的火舞效果為觀眾帶來一場精彩難忘的火焰之旅。劇中一名遠洋冒險的葡萄王子偶然間駐足於一個名叫火爾摩莎Firemosa的美麗島嶼上，島嶼上生活著精通火焰技藝的火族住民，葡萄王子與火族公主一見鍾情卻遭到了火族族人的阻止，王子爲了贏得族人的認可必須正面迎擊島上風、火、雷神所帶來的重重考驗。入場方式：戶外演出，自由入場', '桃園市政府', '桃園市327新屋區保生路51號', '2025-04-11 00:00:00', '2025-04-11 23:59:59', '桃園市新屋區', 24.98832, 121.02781, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025桃園藝術巡演新屋場-即將成真火舞團《火爾摩沙傳奇Firemosa》火舞劇', `description`='￭相關細節可電洽本府文化局(03-3322592#8313)活動節目：即將成真火舞團《火爾摩沙傳奇Firemosa》火舞劇活動時間：114年4月11日(星期五) 19:00-20:30活動地點：永安保生宮(桃園市新屋區保生路51號) 演出團隊：「即將成真火舞團」由兩位全國火舞比賽冠軍舞者郭彥甫與蔡宏毅於2014年共同創立，是目前台灣唯一表演「火劇」的職業舞團。該團於2015至2016年間曾代表台灣挑戰「亞洲達人秀」、「中國達人秀」等大型選秀比賽，並將觸角伸及世界，受邀於亞洲、歐洲各大藝術祭；2018年初在嘉義台灣燈會帶來了長達45分鐘的原創火劇，場場滿座，廣受好評；2020年於總統府前亮點演出等。節目簡介：「FireMosa」是一齣結合民俗技藝與藝陣的戶外傳奇火舞劇，以氣勢磅礴的火舞效果為觀眾帶來一場精彩難忘的火焰之旅。劇中一名遠洋冒險的葡萄王子偶然間駐足於一個名叫火爾摩莎Firemosa的美麗島嶼上，島嶼上生活著精通火焰技藝的火族住民，葡萄王子與火族公主一見鍾情卻遭到了火族族人的阻止，王子爲了贏得族人的認可必須正面迎擊島上風、火、雷神所帶來的重重考驗。入場方式：戶外演出，自由入場', `organizer`='桃園市政府', `address`='桃園市327新屋區保生路51號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-04-11 23:59:59', `location`='桃園市新屋區', `latitude`=24.98832, `longitude`=121.02781, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
