INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005232', '2025友愛大聲說', '￭相關細節可電洽桃園市青年體驗學習園區(03-4862200)【友愛大聲說│免費挑戰16米自由落體!】愛的表達方式有很多種來問問自己 敢勇於對身邊的朋友、家人、伴侶表達愛意嗎?偷偷和大家分享其中一種方式!當你帶足勇氣前往高處大聲吶喊出愛的宣言堅信你的愛意一定會傳遞到對方心中❤讓我們一起「友愛大聲說」吧❤ 每月14號當週的週六園區免費開放挑戰自由落體設施，勇敢從上方跳下，大聲吶喊出你的夢想及目標！說不定當你回到地球表面時，你的願望就實現了❗️報名方式❗️事前預約當日基本體驗方案者(一日體驗、二日體驗等)，活動當日，可至大廳填寫報名表(限定十名參加者，額滿為止)❗️活動內容❗️限時10分鐘內攀登上告白支柱(自由落體設施)說出告白內容並完成信仰之躍即算完成挑戰，成功挑戰即送-挑戰證書一張 及 小禮品TYAC小教室16米雙柱高空自由落體，相當於離地5-6層樓高，挑戰者登頂後張開雙手向前跳躍，享受近1秒滯空的刺激感!此有助於釋放壓力、戰勝內心恐懼，提升自我的挑戰力。 溫馨提醒：友愛大聲說為&ldquo;現場體驗者&rdquo;限定活動，所以要記得提前預約體驗方案喔!活動地點：桃園市新屋區新港路16號(永安漁港旁)團體預約官方LINE@帳號：@tyac散客預約官方LINE@帳號：@tyacfun', '桃園市政府', '桃園市327新屋區新港路16號', '2025-01-18 00:00:00', '2025-12-13 23:59:59', '桃園市新屋區', 24.98919, 121.01763, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025友愛大聲說', `description`='￭相關細節可電洽桃園市青年體驗學習園區(03-4862200)【友愛大聲說│免費挑戰16米自由落體!】愛的表達方式有很多種來問問自己 敢勇於對身邊的朋友、家人、伴侶表達愛意嗎?偷偷和大家分享其中一種方式!當你帶足勇氣前往高處大聲吶喊出愛的宣言堅信你的愛意一定會傳遞到對方心中❤讓我們一起「友愛大聲說」吧❤ 每月14號當週的週六園區免費開放挑戰自由落體設施，勇敢從上方跳下，大聲吶喊出你的夢想及目標！說不定當你回到地球表面時，你的願望就實現了❗️報名方式❗️事前預約當日基本體驗方案者(一日體驗、二日體驗等)，活動當日，可至大廳填寫報名表(限定十名參加者，額滿為止)❗️活動內容❗️限時10分鐘內攀登上告白支柱(自由落體設施)說出告白內容並完成信仰之躍即算完成挑戰，成功挑戰即送-挑戰證書一張 及 小禮品TYAC小教室16米雙柱高空自由落體，相當於離地5-6層樓高，挑戰者登頂後張開雙手向前跳躍，享受近1秒滯空的刺激感!此有助於釋放壓力、戰勝內心恐懼，提升自我的挑戰力。 溫馨提醒：友愛大聲說為&ldquo;現場體驗者&rdquo;限定活動，所以要記得提前預約體驗方案喔!活動地點：桃園市新屋區新港路16號(永安漁港旁)團體預約官方LINE@帳號：@tyac散客預約官方LINE@帳號：@tyacfun', `organizer`='桃園市政府', `address`='桃園市327新屋區新港路16號', `start_date`='2025-01-18 00:00:00', `end_date`='2025-12-13 23:59:59', `location`='桃園市新屋區', `latitude`=24.98919, `longitude`=121.01763, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
