INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_005234', '2025富岡鐵道藝術生活節', '無', '桃園市政府', '桃園市326楊梅區富岡火車站', '2025-08-01 00:00:00', '2025-08-01 23:59:59', '桃園市楊梅區', 24.93443, 121.08307, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025富岡鐵道藝術生活節', `description`='無', `organizer`='桃園市政府', `address`='桃園市326楊梅區富岡火車站', `start_date`='2025-08-01 00:00:00', `end_date`='2025-08-01 23:59:59', `location`='桃園市楊梅區', `latitude`=24.93443, `longitude`=121.08307, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_006151', '2025大龍門好神 集章尋寶趣', '走訪大龍門，集章換好神今年春節，桃園市特別設計了「大龍門好神」公仔，只要在農曆初一至初五走春出遊之際，於「大龍門旅遊帶」內指定的25處景點、5間廟宇掃描QRcode，即可取得1個章，在景點、廟宇各集1個章，共取得2個章便完成1次集章活動(每日限集兩個章)，就能兌換「大龍門好神」公仔1尊!(每日只可兌換一次) (建議事先下載App；註冊為「訪客會員」即可參加本活動)好神5加1，有換有保庇!只要透過桃園市民卡完成集章任務，就可以兌換「大龍門好神」公仔1尊，數量有限，每日限量發放!還有機會獲得隱藏版財神爺!數位市民卡，新春一路發桃園市民卡APP好便利!只要簡單三步驟，讓你樂游大龍門的同時，還能歡喜迎好神!25處集章地點如下:大溪區:大溪老城區遊客中心、大溪木藝生態博物館、達文西瓜藝文館、太武新村眷村文化園區、山豬湖生態親水園區、北橫遊客中心(經國紀念館)、慈湖遊客中心、富田花園農場、康莊休閒農業園區、石門水庫管理中心、中庄吊橋(大漢溪山豬湖生態親水園區)、大溪老城四季行館民宿、大溪老茶廠、花開了休閒農場龍潭區：雄獅文具想像力製造所、台灣客家茶文化館、龍潭大池管理中心、桃園市客家文化館、十一份觀光文化園區、大北坑休閒農業區、名人堂花園大飯店棒球名人堂、小人國主題樂園、鍾肇政文學生活園區、繞山花（三和青創基地）、手信霧隱城5處兌換廟宇:大溪普濟堂、大溪三層福安宮、大溪蓮座山觀音寺、石門十一份集福宮、龍潭龍元宮更多活動詳情 請見 活動網站', '桃園市政府', '無資料', '2025-01-29 00:00:00', '2025-02-02 23:59:59', '桃園市桃園區', 24.99309, 121.29994, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025大龍門好神 集章尋寶趣', `description`='走訪大龍門，集章換好神今年春節，桃園市特別設計了「大龍門好神」公仔，只要在農曆初一至初五走春出遊之際，於「大龍門旅遊帶」內指定的25處景點、5間廟宇掃描QRcode，即可取得1個章，在景點、廟宇各集1個章，共取得2個章便完成1次集章活動(每日限集兩個章)，就能兌換「大龍門好神」公仔1尊!(每日只可兌換一次) (建議事先下載App；註冊為「訪客會員」即可參加本活動)好神5加1，有換有保庇!只要透過桃園市民卡完成集章任務，就可以兌換「大龍門好神」公仔1尊，數量有限，每日限量發放!還有機會獲得隱藏版財神爺!數位市民卡，新春一路發桃園市民卡APP好便利!只要簡單三步驟，讓你樂游大龍門的同時，還能歡喜迎好神!25處集章地點如下:大溪區:大溪老城區遊客中心、大溪木藝生態博物館、達文西瓜藝文館、太武新村眷村文化園區、山豬湖生態親水園區、北橫遊客中心(經國紀念館)、慈湖遊客中心、富田花園農場、康莊休閒農業園區、石門水庫管理中心、中庄吊橋(大漢溪山豬湖生態親水園區)、大溪老城四季行館民宿、大溪老茶廠、花開了休閒農場龍潭區：雄獅文具想像力製造所、台灣客家茶文化館、龍潭大池管理中心、桃園市客家文化館、十一份觀光文化園區、大北坑休閒農業區、名人堂花園大飯店棒球名人堂、小人國主題樂園、鍾肇政文學生活園區、繞山花（三和青創基地）、手信霧隱城5處兌換廟宇:大溪普濟堂、大溪三層福安宮、大溪蓮座山觀音寺、石門十一份集福宮、龍潭龍元宮更多活動詳情 請見 活動網站', `organizer`='桃園市政府', `address`='無資料', `start_date`='2025-01-29 00:00:00', `end_date`='2025-02-02 23:59:59', `location`='桃園市桃園區', `latitude`=24.99309, `longitude`=121.29994, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_006330', '114年度咖啡暨柑橘推廣系列活動 舞桔咖ho!', '￭相關細節可電洽復興區公所(03-3821500#2214)復興區公所將於2月22日(六)上午8時及2月23日(日)上午10時,在角板山天幕活動廣場盛大開幕「桃園市復興區114年度咖啡暨柑橘推廣系列活動」。☕鑑於去年活動成效顯著,本年度將持續推動咖啡評鑑、原住民熱舞創意競賽及在地農特產品市集等,邀請大家一同共襄盛舉舞桔咖ho!此次「咖啡評鑑」,為農民檢視自家咖啡品質的機會,透過專業評鑑反饋,深入了解產品優勢及改進空間,提升咖啡的整體品質。增強市場競爭力。隨著2月進入柑橘收穫季節,本公所將舉辦連續兩日的農特產品市集,現場不僅有新鮮的柑橘、香濃的在地咖啡,還將打造出濃厚的節慶氛圍。邀請街頭藝人,為現場增添互動,使民眾在品嚐美食及選購農特產品,也能享受充滿樂趣的現場表演,為回饋民眾支持,於市集消費滿額者可獲得精選咖啡或拉花咖啡飲品一杯。此外,今年活動中還將有一場別具特色的「原住民族熱舞創意比賽」,期望透過現代流行熱舞及傳統文化元素的巧妙結合,發展出不同特色舞蹈,創造出獨特的現代風格。這不僅是一場舞蹈表演,更是一場跨越時代的文化交流,旨在激發民眾對原住民文化的關注,並推動不同文化間的積極對話與交流,歡迎大家共襄盛舉,盡情享受這場文化與美食的盛宴!', '桃園市政府', '桃園市336復興區角板山天幕活動廣場(忠孝路20號)', '2025-02-22 00:00:00', '2025-02-23 23:59:59', '桃園市復興區', 24.81397, 121.35068, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度咖啡暨柑橘推廣系列活動 舞桔咖ho!', `description`='￭相關細節可電洽復興區公所(03-3821500#2214)復興區公所將於2月22日(六)上午8時及2月23日(日)上午10時,在角板山天幕活動廣場盛大開幕「桃園市復興區114年度咖啡暨柑橘推廣系列活動」。☕鑑於去年活動成效顯著,本年度將持續推動咖啡評鑑、原住民熱舞創意競賽及在地農特產品市集等,邀請大家一同共襄盛舉舞桔咖ho!此次「咖啡評鑑」,為農民檢視自家咖啡品質的機會,透過專業評鑑反饋,深入了解產品優勢及改進空間,提升咖啡的整體品質。增強市場競爭力。隨著2月進入柑橘收穫季節,本公所將舉辦連續兩日的農特產品市集,現場不僅有新鮮的柑橘、香濃的在地咖啡,還將打造出濃厚的節慶氛圍。邀請街頭藝人,為現場增添互動,使民眾在品嚐美食及選購農特產品,也能享受充滿樂趣的現場表演,為回饋民眾支持,於市集消費滿額者可獲得精選咖啡或拉花咖啡飲品一杯。此外,今年活動中還將有一場別具特色的「原住民族熱舞創意比賽」,期望透過現代流行熱舞及傳統文化元素的巧妙結合,發展出不同特色舞蹈,創造出獨特的現代風格。這不僅是一場舞蹈表演,更是一場跨越時代的文化交流,旨在激發民眾對原住民文化的關注,並推動不同文化間的積極對話與交流,歡迎大家共襄盛舉,盡情享受這場文化與美食的盛宴!', `organizer`='桃園市政府', `address`='桃園市336復興區角板山天幕活動廣場(忠孝路20號)', `start_date`='2025-02-22 00:00:00', `end_date`='2025-02-23 23:59:59', `location`='桃園市復興區', `latitude`=24.81397, `longitude`=121.35068, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376430000A_006346', '2025陶異星漫遊', '￭相關細節可電洽中原文創園區(03-4333833#220)《陶異星漫遊》為中原文創園區年度特展之一，於114年3月25日(二)至5月11日(日)展出，結合主題情境、角色扮演、互動任務等打造劇場式展覽，並延伸周邊多檔亮點活動，帶領觀眾以宇宙探險為故事背景，述說不一樣的陶瓷故事，探訪各式風格陶藝家的內心創作世界。本次《陶異星漫遊》共設計3大主題展區，第一章「文明大發現：地球的陶瓷軌跡」、第二章「登陸異星小宇宙」、第三章「跨越多重宇宙」，搭配聲光、情境布置的呈現，讓觀眾投身奇幻的星際之旅。本展講述一艘來自遙遠星系的星際航艦，在巡航銀河途中，意外遭隕石襲擊而嚴重受損，迫降在藍色行星&mdash;&mdash;地球。根據偵測儀掃描顯示，這顆星球的智慧種族「人類」，長久以來擅長使用地殼表面的泥層製作各式器物，艦長BOBO決定更深入了解地球文明，於是他化身人類的模樣，展開探索地球的旅程。｜展場介紹｜展覽由位於3倉的第一章節「文明大發現：地球的陶瓷軌跡」啟程，從宏觀的視角表述陶瓷在人類歷史中的變化與應用，與元智大學、和成欣業、白馬磁磚、龍燡企業有限公司等多個桃園在地陶瓷公司合作，展出衛生陶瓷、工業陶瓷、建築陶瓷、科技陶瓷、醫療陶瓷等品類，揭露陶瓷埋藏於日常生活中的痕跡，以及從實用功能中解放而出的藝術陶瓷，讓陶藝家自由、熱情的心於此綻放，共邀集29位藝術家、37件作品；２倉第二章節走進「登陸異星小宇宙」的世界，遊歷創作者天馬行空的創造力，藉由千奇百怪的陶瓷造型作品走進陶藝家內心的小宇宙，宛如未成形的細胞、形變的生命體、潛意識般流動的瓦礫等，展現出憂鬱、狂暴、科幻等特質，共25位藝術家及42件作品；最後１倉在第三章節「跨越多重宇宙」中，星際航艦將直接進入蟲洞，穿越多重宇宙。就像是在窯火裡翻騰的過程，每個陶瓷素坯都承載著無限可能，每個創作決定都會在窯爐裡的小宇宙，開啟嶄新的維度，象徵著藝術是創造可能與驚喜的永恆實驗。本章聚焦大桃園在地陶藝的風采，邀集桃園市陶藝藝術發展協會、桃園陶藝協會共15名藝術家、17件作品。星辰天體皆是由宇宙塵埃因重力匯聚而成，在地球上塵土藉由陶瓷藝術的發展，衍生成各...', '桃園市政府', '桃園市320中壢區忠仁路33號', '2025-03-25 00:00:00', '2025-05-11 23:59:59', '桃園市中壢區', 24.96451, 121.24094, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025陶異星漫遊', `description`='￭相關細節可電洽中原文創園區(03-4333833#220)《陶異星漫遊》為中原文創園區年度特展之一，於114年3月25日(二)至5月11日(日)展出，結合主題情境、角色扮演、互動任務等打造劇場式展覽，並延伸周邊多檔亮點活動，帶領觀眾以宇宙探險為故事背景，述說不一樣的陶瓷故事，探訪各式風格陶藝家的內心創作世界。本次《陶異星漫遊》共設計3大主題展區，第一章「文明大發現：地球的陶瓷軌跡」、第二章「登陸異星小宇宙」、第三章「跨越多重宇宙」，搭配聲光、情境布置的呈現，讓觀眾投身奇幻的星際之旅。本展講述一艘來自遙遠星系的星際航艦，在巡航銀河途中，意外遭隕石襲擊而嚴重受損，迫降在藍色行星&mdash;&mdash;地球。根據偵測儀掃描顯示，這顆星球的智慧種族「人類」，長久以來擅長使用地殼表面的泥層製作各式器物，艦長BOBO決定更深入了解地球文明，於是他化身人類的模樣，展開探索地球的旅程。｜展場介紹｜展覽由位於3倉的第一章節「文明大發現：地球的陶瓷軌跡」啟程，從宏觀的視角表述陶瓷在人類歷史中的變化與應用，與元智大學、和成欣業、白馬磁磚、龍燡企業有限公司等多個桃園在地陶瓷公司合作，展出衛生陶瓷、工業陶瓷、建築陶瓷、科技陶瓷、醫療陶瓷等品類，揭露陶瓷埋藏於日常生活中的痕跡，以及從實用功能中解放而出的藝術陶瓷，讓陶藝家自由、熱情的心於此綻放，共邀集29位藝術家、37件作品；２倉第二章節走進「登陸異星小宇宙」的世界，遊歷創作者天馬行空的創造力，藉由千奇百怪的陶瓷造型作品走進陶藝家內心的小宇宙，宛如未成形的細胞、形變的生命體、潛意識般流動的瓦礫等，展現出憂鬱、狂暴、科幻等特質，共25位藝術家及42件作品；最後１倉在第三章節「跨越多重宇宙」中，星際航艦將直接進入蟲洞，穿越多重宇宙。就像是在窯火裡翻騰的過程，每個陶瓷素坯都承載著無限可能，每個創作決定都會在窯爐裡的小宇宙，開啟嶄新的維度，象徵著藝術是創造可能與驚喜的永恆實驗。本章聚焦大桃園在地陶藝的風采，邀集桃園市陶藝藝術發展協會、桃園陶藝協會共15名藝術家、17件作品。星辰天體皆是由宇宙塵埃因重力匯聚而成，在地球上塵土藉由陶瓷藝術的發展，衍生成各...', `organizer`='桃園市政府', `address`='桃園市320中壢區忠仁路33號', `start_date`='2025-03-25 00:00:00', `end_date`='2025-05-11 23:59:59', `location`='桃園市中壢區', `latitude`=24.96451, `longitude`=121.24094, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376470000A_000532', '轉知「嘉義縣文化觀光局」辦理「2025嘉義瑞里紫藤花季」活動', '今年春天最浪漫的瑞里紫藤花季，即將在3月中下旬浪漫登場！紫藤花海即將迎來最美的時刻，歡迎一起來嘉義瑞里感受這場夢幻紫色饗宴。', '嘉義縣文化觀光局', '嘉義縣梅山鄉62號', '2025-03-01 00:00:00', '2025-05-31 00:00:00', '嘉義縣梅山鄉', 23.539271, 120.670861, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='轉知「嘉義縣文化觀光局」辦理「2025嘉義瑞里紫藤花季」活動', `description`='今年春天最浪漫的瑞里紫藤花季，即將在3月中下旬浪漫登場！紫藤花海即將迎來最美的時刻，歡迎一起來嘉義瑞里感受這場夢幻紫色饗宴。', `organizer`='嘉義縣文化觀光局', `address`='嘉義縣梅山鄉62號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='嘉義縣梅山鄉', `latitude`=23.539271, `longitude`=120.670861, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376490000A_000119', '《大雅之風─雲林文化藝術獎貢獻獎得主作品暨典藏藝術展》', '雲林本地人文薈萃，物產豐饒，境內藝術家人才輩出，雲林優良的環境與文化成為藝術家創作的無限泉源，其中有不少卓越的藝術家獲得雲林文化藝術獎貢獻獎殊榮。本次展覽以雲林縣文化藝術獎貢獻獎中，視覺藝術類得主的作品和部分典藏品為主要展覽內容，《大雅》是中國《詩經》中最早的詩歌，其體裁形式、藝術形象和表現手法，都有其深厚的藝術魅力；再者《大雅》的作者，皆是德高而有大才之人，本展覽取其「大雅」之意更引喻出創作者藝術上卓爾非凡之成就以及文采風華的人格內涵。「風」意味著風格、風範，與巔峰的「峰」同音，更象徵著藝術風格已達到巔峰之意。本次展覽將分四大區，分別「經典─藝術家的容顏」、「再現─藝術家的日常」、「匠心─藝術家的視野」以及「綻放─藝術互動」四區。邀請16位藝術家共同展出，屬於大師的故事，讓我們一同細細品味。展期：10月13日（四）起（上午9時至10時開幕式）請參觀民眾配戴口罩，遵守防疫措施。', '雲林縣政府文化觀光處', '雲林縣政府文化觀光處展覽館三樓', '2022-10-13 09:00:00', '2023-03-31 17:00:00', '雲林縣斗六市', 23.69525, 120.5249, '無資料', '無資料', '["https://tour.yunlin.gov.tw/public/upload/Activity/220929061503049108DRENW.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='《大雅之風─雲林文化藝術獎貢獻獎得主作品暨典藏藝術展》', `description`='雲林本地人文薈萃，物產豐饒，境內藝術家人才輩出，雲林優良的環境與文化成為藝術家創作的無限泉源，其中有不少卓越的藝術家獲得雲林文化藝術獎貢獻獎殊榮。本次展覽以雲林縣文化藝術獎貢獻獎中，視覺藝術類得主的作品和部分典藏品為主要展覽內容，《大雅》是中國《詩經》中最早的詩歌，其體裁形式、藝術形象和表現手法，都有其深厚的藝術魅力；再者《大雅》的作者，皆是德高而有大才之人，本展覽取其「大雅」之意更引喻出創作者藝術上卓爾非凡之成就以及文采風華的人格內涵。「風」意味著風格、風範，與巔峰的「峰」同音，更象徵著藝術風格已達到巔峰之意。本次展覽將分四大區，分別「經典─藝術家的容顏」、「再現─藝術家的日常」、「匠心─藝術家的視野」以及「綻放─藝術互動」四區。邀請16位藝術家共同展出，屬於大師的故事，讓我們一同細細品味。展期：10月13日（四）起（上午9時至10時開幕式）請參觀民眾配戴口罩，遵守防疫措施。', `organizer`='雲林縣政府文化觀光處', `address`='雲林縣政府文化觀光處展覽館三樓', `start_date`='2022-10-13 09:00:00', `end_date`='2023-03-31 17:00:00', `location`='雲林縣斗六市', `latitude`=23.69525, `longitude`=120.5249, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://tour.yunlin.gov.tw/public/upload/Activity/220929061503049108DRENW.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376490000A_000135', '2023 斗六燈會 Sunshine 兔 you 啟燈暨跨年晚會', '大家新年快樂~「2023 斗六燈會 Sunshine 兔 you 啟燈暨跨年晚會」12月31日（六）啟燈暨跨年晚會就在「斗六膨鼠森林公園」跨年晚會豐富活動內容、眾多精彩表演、超級大咖歌唱一流 一年一度啟燈閃耀大事，千萬不要錯過呦燈會展期 111年12月31日（六）至112年3月31日（五）閃亮不間斷展出區域主燈區在「斗六膨鼠森林公園」副燈區在「行啟記念館」#2023斗六燈會#12月31日至3月31日#啟燈暨跨年晚會#就在12月31日', '斗六市公所', '斗六膨鼠森林公園', '2023-01-01 00:00:00', '2023-03-31 21:00:00', '雲林縣斗六市', 23.69689, 120.53, '無資料', '無資料', '["https://tour.yunlin.gov.tw/public/upload/Activity/230111123011338990TPNMD.png", "https://tour.yunlin.gov.tw/public/upload/Activity/230111123011354627PTKQS.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023 斗六燈會 Sunshine 兔 you 啟燈暨跨年晚會', `description`='大家新年快樂~「2023 斗六燈會 Sunshine 兔 you 啟燈暨跨年晚會」12月31日（六）啟燈暨跨年晚會就在「斗六膨鼠森林公園」跨年晚會豐富活動內容、眾多精彩表演、超級大咖歌唱一流 一年一度啟燈閃耀大事，千萬不要錯過呦燈會展期 111年12月31日（六）至112年3月31日（五）閃亮不間斷展出區域主燈區在「斗六膨鼠森林公園」副燈區在「行啟記念館」#2023斗六燈會#12月31日至3月31日#啟燈暨跨年晚會#就在12月31日', `organizer`='斗六市公所', `address`='斗六膨鼠森林公園', `start_date`='2023-01-01 00:00:00', `end_date`='2023-03-31 21:00:00', `location`='雲林縣斗六市', `latitude`=23.69689, `longitude`=120.53, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://tour.yunlin.gov.tw/public/upload/Activity/230111123011338990TPNMD.png", "https://tour.yunlin.gov.tw/public/upload/Activity/230111123011354627PTKQS.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376500000A_000001', '布袋謝鹽祭', '布袋洲南鹽場一年一度的謝鹽祭，以鹽田為舞台，由在地的慶和軒北管以傳統戲曲結合現代劇場，演出洲南鹽場重建的故事，並邀請三組音樂創作歌手，在秋天夜晚的海風中演唱，搭配駐村藝術家的影像MV創作，凸顯布袋的產業勞動、人文特色與在地價值。', '布袋嘴文化協會', '無資料', '1911-09-01 00:00:00', '2065-09-30 23:59:00', '嘉義縣布袋鎮', 23.39079, 120.1654, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='布袋謝鹽祭', `description`='布袋洲南鹽場一年一度的謝鹽祭，以鹽田為舞台，由在地的慶和軒北管以傳統戲曲結合現代劇場，演出洲南鹽場重建的故事，並邀請三組音樂創作歌手，在秋天夜晚的海風中演唱，搭配駐村藝術家的影像MV創作，凸顯布袋的產業勞動、人文特色與在地價值。', `organizer`='布袋嘴文化協會', `address`='無資料', `start_date`='1911-09-01 00:00:00', `end_date`='2065-09-30 23:59:00', `location`='嘉義縣布袋鎮', `latitude`=23.39079, `longitude`=120.1654, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005581', '2025東浪嘉年華', '台東擁有全台最美麗的海岸線，獨具氣候及地理優勢，活動結合音樂會及運動觀光，以藝文表演、休閒運動發展在地特色活動，並活化杉原灣陸海空域，打造適合多元客群的娛樂活動，讓更多旅客體驗台東東海岸之美。活動時間｜5/17-5/18活動地點｜台東杉原灣️（免費入場）出演卡司｜5/17 陳忻玥｜美秀集團｜蔡健雅｜waa 魏如萱｜Osean 吳獻｜柯泯薰｜DJ Veena｜鳳小岳5/18無妄合作社｜滅火器 Fire EX.｜洪佩瑜｜TRASH｜芒果醬 Mango Jump｜ DJ Veena｜蛋堡 Soft Lipa沙憩及水域體驗活動✸大型風箏展演 &ndash; 繽紛巨型風箏翱翔天空，打造壯觀視覺盛宴。✸親子沙雕體驗 &ndash; 沙子變身藝術品，親子聯手打造獨一無二的海灘傑作！報名連結✸風浪板體驗 &ndash; 乘風破浪超刺激，新手也能挑戰海上衝勁快感！報名連結競賽活動✸SUP龍舟趣味競賽 &ndash; SUP結合龍舟競賽，挑戰團隊協作與平衡感！✸臺灣沙灘排球挑戰賽－最靠太平洋的沙灘排球男女混和賽報名連結', '臺東縣政府交通及觀光發展處', '無資料', '2025-05-17 00:00:00', '2025-05-18 23:59:59', '臺東縣卑南鄉', 22.83077, 121.18612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025東浪嘉年華', `description`='台東擁有全台最美麗的海岸線，獨具氣候及地理優勢，活動結合音樂會及運動觀光，以藝文表演、休閒運動發展在地特色活動，並活化杉原灣陸海空域，打造適合多元客群的娛樂活動，讓更多旅客體驗台東東海岸之美。活動時間｜5/17-5/18活動地點｜台東杉原灣️（免費入場）出演卡司｜5/17 陳忻玥｜美秀集團｜蔡健雅｜waa 魏如萱｜Osean 吳獻｜柯泯薰｜DJ Veena｜鳳小岳5/18無妄合作社｜滅火器 Fire EX.｜洪佩瑜｜TRASH｜芒果醬 Mango Jump｜ DJ Veena｜蛋堡 Soft Lipa沙憩及水域體驗活動✸大型風箏展演 &ndash; 繽紛巨型風箏翱翔天空，打造壯觀視覺盛宴。✸親子沙雕體驗 &ndash; 沙子變身藝術品，親子聯手打造獨一無二的海灘傑作！報名連結✸風浪板體驗 &ndash; 乘風破浪超刺激，新手也能挑戰海上衝勁快感！報名連結競賽活動✸SUP龍舟趣味競賽 &ndash; SUP結合龍舟競賽，挑戰團隊協作與平衡感！✸臺灣沙灘排球挑戰賽－最靠太平洋的沙灘排球男女混和賽報名連結', `organizer`='臺東縣政府交通及觀光發展處', `address`='無資料', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-18 23:59:59', `location`='臺東縣卑南鄉', `latitude`=22.83077, `longitude`=121.18612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005652', '​​2025 臺東慢食節《新．臺東辦桌》—延期團圓場', '歡迎舊雨新知前來，享用超過30組慢食市集店家，以慢食精神重新帶來的「辦桌頭盤 」、「辦桌主食」、「辦桌炸物」、「辦桌甜品」，辦上一場可以自己選擇料理的辦桌。一起在音樂、風景、美食中共度歲末，迎接新年吧！​鋪開野餐墊、取代紅桌上的塑膠布，用著自己攜帶的環保餐具、裝盛道道慢食手路菜。一場絕對不一樣的辦桌體驗，就在臺東慢食節！● 時間 |2025/1/18（六）- 1/19（日）11：00 - 16：00● 地點 | 池上大坡池（免費入場 / 請自備環保餐具 / 建議自備野餐墊）', '臺東縣政府', '無資料', '2025-01-18 00:00:00', '2025-01-19 23:59:59', '臺東縣池上鄉', 23.11921, 121.2234, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='​​2025 臺東慢食節《新．臺東辦桌》—延期團圓場', `description`='歡迎舊雨新知前來，享用超過30組慢食市集店家，以慢食精神重新帶來的「辦桌頭盤 」、「辦桌主食」、「辦桌炸物」、「辦桌甜品」，辦上一場可以自己選擇料理的辦桌。一起在音樂、風景、美食中共度歲末，迎接新年吧！​鋪開野餐墊、取代紅桌上的塑膠布，用著自己攜帶的環保餐具、裝盛道道慢食手路菜。一場絕對不一樣的辦桌體驗，就在臺東慢食節！● 時間 |2025/1/18（六）- 1/19（日）11：00 - 16：00● 地點 | 池上大坡池（免費入場 / 請自備環保餐具 / 建議自備野餐墊）', `organizer`='臺東縣政府', `address`='無資料', `start_date`='2025-01-18 00:00:00', `end_date`='2025-01-19 23:59:59', `location`='臺東縣池上鄉', `latitude`=23.11921, `longitude`=121.2234, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005751', '2025台東跨年晚會｜東漂去旅行', '✨2025台東跨年晚會-東漂去旅行✨歡迎各縣市的民眾東漂旅行到台東，一起參與跨年！｜時間｜12/31(二) 19:00-1/1(三)00:30｜地點｜台東市國際地標免費入場出演卡司：熱狗MC HotDog、頑童MJ116、洪佩瑜 Pei-Yu Hung、李權哲、熊仔、JADE、王若琳 、蘇慧倫、葉璦菱、魏如昀、許含光', '臺東縣政府文化處', '無資料', '2024-12-31 00:00:00', '2025-01-01 00:30:00', '臺東縣臺東市', 22.75312, 121.16464, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台東跨年晚會｜東漂去旅行', `description`='✨2025台東跨年晚會-東漂去旅行✨歡迎各縣市的民眾東漂旅行到台東，一起參與跨年！｜時間｜12/31(二) 19:00-1/1(三)00:30｜地點｜台東市國際地標免費入場出演卡司：熱狗MC HotDog、頑童MJ116、洪佩瑜 Pei-Yu Hung、李權哲、熊仔、JADE、王若琳 、蘇慧倫、葉璦菱、魏如昀、許含光', `organizer`='臺東縣政府文化處', `address`='無資料', `start_date`='2024-12-31 00:00:00', `end_date`='2025-01-01 00:30:00', `location`='臺東縣臺東市', `latitude`=22.75312, `longitude`=121.16464, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005777', '2024鐵花燈之祭第三季-極地童話', '鐵花燈之祭【極地童話】以夢幻極地世界為背景，結合冰雪與童話故事元素，除在鐵花市集人行步道規劃絢麗「浪漫天幕」，步道兩端也設置「耶誕禮物盒」和「音樂許願帽」為亮點入口意象，伴隨坐落市集旁草地區高7米的「冰雪白熊」，和璀璨「冰晶企鵝」共同迎接到訪遊客，另一側還有可愛的耶誕帽及枴杖糖，讓人仿佛置身耶誕童話中。展期｜113.10.25 &rarr;114.02.16亮燈｜17:30－22:30地點｜鐵花新聚落 行人徒步區&lt;耶誕限定雪花秀&gt;地點：鐵花新聚落 行人徒步區(大禮物盒旁)時間：12/21－12/29場次：19:00、19:30、20:00、20:30、21:00耶誕老公公打卡活動：12/24、12/25  19:00-21:00', '臺東縣政府', '無資料', '2024-10-25 00:00:00', '2025-02-16 23:59:59', '臺東縣臺東市', 22.75367, 121.14595, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2024鐵花燈之祭第三季-極地童話', `description`='鐵花燈之祭【極地童話】以夢幻極地世界為背景，結合冰雪與童話故事元素，除在鐵花市集人行步道規劃絢麗「浪漫天幕」，步道兩端也設置「耶誕禮物盒」和「音樂許願帽」為亮點入口意象，伴隨坐落市集旁草地區高7米的「冰雪白熊」，和璀璨「冰晶企鵝」共同迎接到訪遊客，另一側還有可愛的耶誕帽及枴杖糖，讓人仿佛置身耶誕童話中。展期｜113.10.25 &rarr;114.02.16亮燈｜17:30－22:30地點｜鐵花新聚落 行人徒步區&lt;耶誕限定雪花秀&gt;地點：鐵花新聚落 行人徒步區(大禮物盒旁)時間：12/21－12/29場次：19:00、19:30、20:00、20:30、21:00耶誕老公公打卡活動：12/24、12/25  19:00-21:00', `organizer`='臺東縣政府', `address`='無資料', `start_date`='2024-10-25 00:00:00', `end_date`='2025-02-16 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75367, `longitude`=121.14595, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005820', '2025慢遊東岸．元旦健走', '元旦晨曦，邀您一同漫步三仙台！ 迎著第一道曙光，感受海風拂面，欣賞壯麗的海岸風光。健走不僅能強身健體，更能飽覽自然美景。❚報名方式：現場報名❚報到時間：05: 40❚報到地點：成功鎮海濱公園❚健走路線：成功鎮海濱公園⬌三仙台停車場（單程約3.7公里）❚活動流程：05:40⇀06:00┃人員報到06:00⇀06:10┃升旗典禮06:10⇀06:20┃長官來賓致詞／紀念合影06:20⇀06:30┃健康操（暖身）06:30     　      ┃鳴槍出發07:30⇀09:00┃憑活動兌換卡領取餐卷', '臺東縣成功鎮公所', '無資料', '2025-01-01 00:00:00', '2025-01-01 23:59:59', '臺東縣成功鎮', 23.10404, 121.38497, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025慢遊東岸．元旦健走', `description`='元旦晨曦，邀您一同漫步三仙台！ 迎著第一道曙光，感受海風拂面，欣賞壯麗的海岸風光。健走不僅能強身健體，更能飽覽自然美景。❚報名方式：現場報名❚報到時間：05: 40❚報到地點：成功鎮海濱公園❚健走路線：成功鎮海濱公園⬌三仙台停車場（單程約3.7公里）❚活動流程：05:40⇀06:00┃人員報到06:00⇀06:10┃升旗典禮06:10⇀06:20┃長官來賓致詞／紀念合影06:20⇀06:30┃健康操（暖身）06:30     　      ┃鳴槍出發07:30⇀09:00┃憑活動兌換卡領取餐卷', `organizer`='臺東縣成功鎮公所', `address`='無資料', `start_date`='2025-01-01 00:00:00', `end_date`='2025-01-01 23:59:59', `location`='臺東縣成功鎮', `latitude`=23.10404, `longitude`=121.38497, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005821', '2025關山千人蘿蔔季', '「關山千人蘿蔔季」，於101年在兩期稻作豐收後的農閒時首次辦理，迄今已邁入第14年，成功打響關山蘿蔔的品牌。關山鎮公所鼓勵農民利用二期稻米收割後冬季裡作期間，除了種植油菜花外，也灑種子種蘿蔔，一方面做綠肥用、二方面可食用、三方面更可提振觀光增加農產品附加價值，為近年來台東開春最受歡迎的農村活動。活動日期｜2025/1/18(六)活動地點｜台九線315.5處(佛緣禪寺指標處進入)活動內容｜09:00、10:00 親子區13:00 自由拔', '關山鎮公所', '無資料', '2025-01-10 00:00:00', '2025-01-18 23:59:59', '臺東縣海端鄉', 23.07733, 121.15583, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025關山千人蘿蔔季', `description`='「關山千人蘿蔔季」，於101年在兩期稻作豐收後的農閒時首次辦理，迄今已邁入第14年，成功打響關山蘿蔔的品牌。關山鎮公所鼓勵農民利用二期稻米收割後冬季裡作期間，除了種植油菜花外，也灑種子種蘿蔔，一方面做綠肥用、二方面可食用、三方面更可提振觀光增加農產品附加價值，為近年來台東開春最受歡迎的農村活動。活動日期｜2025/1/18(六)活動地點｜台九線315.5處(佛緣禪寺指標處進入)活動內容｜09:00、10:00 親子區13:00 自由拔', `organizer`='關山鎮公所', `address`='無資料', `start_date`='2025-01-10 00:00:00', `end_date`='2025-01-18 23:59:59', `location`='臺東縣海端鄉', `latitude`=23.07733, `longitude`=121.15583, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005826', '2025綠島海陸跨年演唱會', '陸上演唱會日期：113.12.31時間：18:30-00:30地點：免稅商店前廣場 海底潛水倒數 (需報名)日期：113.12.31時間：22:30-00:30地點：石朗潛水區 豆丁海馬郵筒報名連結報名資格潛水經驗: 進階開放水域潛水員AOW，潛水經驗 20 支以上，一年內有下水經驗。健康聲明: 所有參與人員皆需填寫 PADI 健康聲明書。裝備要求: 除基本潛水裝備外，皆需佩戴潛水燈與浮力袋 (SMB)。行前簡報: 活動開始前，必須參與進行詳細的行前簡報，包含潛水計畫、安全規範、緊急應變程序等。夜潛活動進行之前將進行測潛，若經潛水教練判斷不符合資格，將無法參加跨年海底跨年。（建議若超過一年以上無潛水請主動告知，並自費參加複習／練習課程。）', '台東縣綠島鄉公所', '無資料', '2024-12-31 00:00:00', '2025-01-01 00:30:00', '臺東縣綠島鄉', 22.6558, 121.4745, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025綠島海陸跨年演唱會', `description`='陸上演唱會日期：113.12.31時間：18:30-00:30地點：免稅商店前廣場 海底潛水倒數 (需報名)日期：113.12.31時間：22:30-00:30地點：石朗潛水區 豆丁海馬郵筒報名連結報名資格潛水經驗: 進階開放水域潛水員AOW，潛水經驗 20 支以上，一年內有下水經驗。健康聲明: 所有參與人員皆需填寫 PADI 健康聲明書。裝備要求: 除基本潛水裝備外，皆需佩戴潛水燈與浮力袋 (SMB)。行前簡報: 活動開始前，必須參與進行詳細的行前簡報，包含潛水計畫、安全規範、緊急應變程序等。夜潛活動進行之前將進行測潛，若經潛水教練判斷不符合資格，將無法參加跨年海底跨年。（建議若超過一年以上無潛水請主動告知，並自費參加複習／練習課程。）', `organizer`='台東縣綠島鄉公所', `address`='無資料', `start_date`='2024-12-31 00:00:00', `end_date`='2025-01-01 00:30:00', `location`='臺東縣綠島鄉', `latitude`=22.6558, `longitude`=121.4745, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005831', '2025臺東好神愛在元宵嘉年華', '千層之愛藝術燈展邀請國內藝術家結合地景設計大型燈飾，設計主軸將融合親子、浪漫情人及元宵節慶氣氛等，為城市注入新美學元素，打造一個浪漫童趣的幸福城市。活動時間｜1/24(五)-2/11(二) 17:00-22:00 亮燈活動地點｜臺東市公所廣場宣傳記者會寒單第一炸與我們一起見證元宵嘉年華的啟動時刻！活動時間｜2/8(六) 10:00-11:00活動地點｜臺東市南京路市民廣場愛在元宵煙火晚會傳統民俗藝術表演、主題特色市集及藝人演唱活動時間｜2/14(五) 19:00-21:00 (愛神市集、愛神餐車18:00開始)活動地點｜臺東市海濱公園 國際地標藤編體驗「這杯子 藤你，這輩子 疼你」報名連結(名額已滿，歡迎當天到體驗攤位排隊候補)*抽獎券請於2025/2/14晚會當天投入服務台抽獎箱，投入時間為18:00-20:00。*請保留兌獎券做為兌獎證明。*主辦單位保有最終修改、變更、活動解釋之權利', '臺東市公所民政課', '無資料', '2025-01-24 00:00:00', '2025-02-14 23:59:59', '臺東縣臺東市', 22.75027, 121.15781, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺東好神愛在元宵嘉年華', `description`='千層之愛藝術燈展邀請國內藝術家結合地景設計大型燈飾，設計主軸將融合親子、浪漫情人及元宵節慶氣氛等，為城市注入新美學元素，打造一個浪漫童趣的幸福城市。活動時間｜1/24(五)-2/11(二) 17:00-22:00 亮燈活動地點｜臺東市公所廣場宣傳記者會寒單第一炸與我們一起見證元宵嘉年華的啟動時刻！活動時間｜2/8(六) 10:00-11:00活動地點｜臺東市南京路市民廣場愛在元宵煙火晚會傳統民俗藝術表演、主題特色市集及藝人演唱活動時間｜2/14(五) 19:00-21:00 (愛神市集、愛神餐車18:00開始)活動地點｜臺東市海濱公園 國際地標藤編體驗「這杯子 藤你，這輩子 疼你」報名連結(名額已滿，歡迎當天到體驗攤位排隊候補)*抽獎券請於2025/2/14晚會當天投入服務台抽獎箱，投入時間為18:00-20:00。*請保留兌獎券做為兌獎證明。*主辦單位保有最終修改、變更、活動解釋之權利', `organizer`='臺東市公所民政課', `address`='無資料', `start_date`='2025-01-24 00:00:00', `end_date`='2025-02-14 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75027, `longitude`=121.15781, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005832', '2025馬卡巴嗨藝術節', '透過一系列精心策劃的活動，包括傳統歌舞演繹、百年文化傳承展現以及部落特色美食品鑑等，以豐富多元的方式呈現原住民族文化與音樂之美，不僅串聯在地原民文化產業，還為原民青年打造一個展現才華與自我風采的舞台。同時，結合部落特色體驗，拉近民眾與原民文化的距離，全力推動臺東市成為原住民傳統文化與藝術的代表性城市，彰顯文化底蘊與創意活力。 2025馬卡巴嗨藝術節  (暫訂)日期：2025/7/6 (日) ~ 2025/7/28 (一) (暫訂)地點：台東市森林公園', '臺東市公所原住民行政課', '無資料', '2025-07-06 00:00:00', '2025-07-28 23:59:59', '臺東縣臺東市', 22.76818, 121.15626, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025馬卡巴嗨藝術節', `description`='透過一系列精心策劃的活動，包括傳統歌舞演繹、百年文化傳承展現以及部落特色美食品鑑等，以豐富多元的方式呈現原住民族文化與音樂之美，不僅串聯在地原民文化產業，還為原民青年打造一個展現才華與自我風采的舞台。同時，結合部落特色體驗，拉近民眾與原民文化的距離，全力推動臺東市成為原住民傳統文化與藝術的代表性城市，彰顯文化底蘊與創意活力。 2025馬卡巴嗨藝術節  (暫訂)日期：2025/7/6 (日) ~ 2025/7/28 (一) (暫訂)地點：台東市森林公園', `organizer`='臺東市公所原住民行政課', `address`='無資料', `start_date`='2025-07-06 00:00:00', `end_date`='2025-07-28 23:59:59', `location`='臺東縣臺東市', `latitude`=22.76818, `longitude`=121.15626, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005833', '114年綠島海上長泳', '黑潮暖流巡經綠島，使海域水質清澈，孕育豐富壯麗的珊瑚生態景觀，全年水溫均溫在攝氏20度以上，潛泳皆宜。賽程規劃為全齡向，讓所有對海上長泳有興趣的民眾，都可以挑選適合自身的賽程，挑戰自我，與其他海洋運動愛好者交流互動，也適合親子同樂，讓家長帶著小朋友一起領略海洋之美，培養海洋保育意識。比賽前一天在免稅店前廣場舉辦選手之夜，有精彩的音樂表演與美食市集，讓選手們在賽前可以放鬆身心，體驗綠島舒適宜人的夜晚風光及氛圍。選手之夜活動日期：114年5月17日 19:00 - 21:00地點：免稅店前廣場綠島海上長泳活動日期：114年5月18日(日)報名人數：以1000人為原則，1200人為上限。泳渡路線：大白沙潛水區(起點)－馬蹄橋下(折返點)－大白沙潛水區(終點) 備案泳渡路線：中寮船澳(起點)－柴口浮潛區(折返點)－中寮船澳(終點) 游泳距離：約3000公尺報名時間：即日起至114年3月23日下午5時止或額滿即停止報名。逾期、現場、傳真報名均不受理報名。報名連結*延期辦理：如遇颱風或不可抗拒因素至活動無法如期舉行時，將延期至114年5月25日辦理，延期後無法參加之選手亦不進行退費。', '綠島鄉公所', '無資料', '2025-05-17 00:00:00', '2025-05-18 23:59:59', '臺東縣綠島鄉', 22.66209, 121.49014, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年綠島海上長泳', `description`='黑潮暖流巡經綠島，使海域水質清澈，孕育豐富壯麗的珊瑚生態景觀，全年水溫均溫在攝氏20度以上，潛泳皆宜。賽程規劃為全齡向，讓所有對海上長泳有興趣的民眾，都可以挑選適合自身的賽程，挑戰自我，與其他海洋運動愛好者交流互動，也適合親子同樂，讓家長帶著小朋友一起領略海洋之美，培養海洋保育意識。比賽前一天在免稅店前廣場舉辦選手之夜，有精彩的音樂表演與美食市集，讓選手們在賽前可以放鬆身心，體驗綠島舒適宜人的夜晚風光及氛圍。選手之夜活動日期：114年5月17日 19:00 - 21:00地點：免稅店前廣場綠島海上長泳活動日期：114年5月18日(日)報名人數：以1000人為原則，1200人為上限。泳渡路線：大白沙潛水區(起點)－馬蹄橋下(折返點)－大白沙潛水區(終點) 備案泳渡路線：中寮船澳(起點)－柴口浮潛區(折返點)－中寮船澳(終點) 游泳距離：約3000公尺報名時間：即日起至114年3月23日下午5時止或額滿即停止報名。逾期、現場、傳真報名均不受理報名。報名連結*延期辦理：如遇颱風或不可抗拒因素至活動無法如期舉行時，將延期至114年5月25日辦理，延期後無法參加之選手亦不進行退費。', `organizer`='綠島鄉公所', `address`='無資料', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-18 23:59:59', `location`='臺東縣綠島鄉', `latitude`=22.66209, `longitude`=121.49014, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005834', '2025綠島海祭媽祖祈福活動', '來綠島參加不一樣的媽祖祈福活動--有飽覽山海風光的陸巡行程，還有體驗波瀾壯闊、海天一線美景的海巡行程，晚上還有熱鬧精彩的平安晚宴，除了欣賞內容豐富的表演，還可以品嘗綠島特色美食。在夏末秋初的宜人海風裡，帶著媽祖的祝福，在綠島給自己來一場洗滌身心靈的旅程。活動日期｜114年9月5-7日活動地點｜綠島鄉全境', '綠島鄉公所', '無資料', '2025-09-05 00:00:00', '2025-09-07 23:59:59', '臺東縣臺東市', 22.75547, 121.14834, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025綠島海祭媽祖祈福活動', `description`='來綠島參加不一樣的媽祖祈福活動--有飽覽山海風光的陸巡行程，還有體驗波瀾壯闊、海天一線美景的海巡行程，晚上還有熱鬧精彩的平安晚宴，除了欣賞內容豐富的表演，還可以品嘗綠島特色美食。在夏末秋初的宜人海風裡，帶著媽祖的祝福，在綠島給自己來一場洗滌身心靈的旅程。活動日期｜114年9月5-7日活動地點｜綠島鄉全境', `organizer`='綠島鄉公所', `address`='無資料', `start_date`='2025-09-05 00:00:00', `end_date`='2025-09-07 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75547, `longitude`=121.14834, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005835', '114年火燒島馬拉松', '來綠島讓海風與天光陪你慢跑吧。這是一場結合健康樂活、環保、趣味元素路跑活動，搭配綠島特色的變裝主題，以及綠島特色美食補給站，給你不一樣的馬拉松體驗。活動日期｜114年10月5日活動地點｜綠島鄉環島公路', '綠島鄉公所', '無資料', '2025-10-05 00:00:00', '2025-10-05 23:59:59', '臺東縣綠島鄉', 22.65802, 121.47606, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年火燒島馬拉松', `description`='來綠島讓海風與天光陪你慢跑吧。這是一場結合健康樂活、環保、趣味元素路跑活動，搭配綠島特色的變裝主題，以及綠島特色美食補給站，給你不一樣的馬拉松體驗。活動日期｜114年10月5日活動地點｜綠島鄉環島公路', `organizer`='綠島鄉公所', `address`='無資料', `start_date`='2025-10-05 00:00:00', `end_date`='2025-10-05 23:59:59', `location`='臺東縣綠島鄉', `latitude`=22.65802, `longitude`=121.47606, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005836', '2026綠島海陸跨年演唱會', '全臺唯一海底陸上同步倒數跨年!每年跨年都去人擠人，要不然就是宅在家，你膩了嗎? 來綠島體驗別開生面的跨年演唱會，喜愛潛水的你更不容錯過。除了精彩的表演，還有豐富的摸彩獎品以及綠島在地美食，來綠島有看、有吃、有拿，歡樂迎新年。活動日期｜114年12月31日活動地點｜綠島鄉免稅店前廣場', '台東縣綠島鄉公所', '無資料', '2025-12-31 00:00:00', '2026-01-01 00:30:00', '臺東縣綠島鄉', 22.66154, 121.47313, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2026綠島海陸跨年演唱會', `description`='全臺唯一海底陸上同步倒數跨年!每年跨年都去人擠人，要不然就是宅在家，你膩了嗎? 來綠島體驗別開生面的跨年演唱會，喜愛潛水的你更不容錯過。除了精彩的表演，還有豐富的摸彩獎品以及綠島在地美食，來綠島有看、有吃、有拿，歡樂迎新年。活動日期｜114年12月31日活動地點｜綠島鄉免稅店前廣場', `organizer`='台東縣綠島鄉公所', `address`='無資料', `start_date`='2025-12-31 00:00:00', `end_date`='2026-01-01 00:30:00', `location`='臺東縣綠島鄉', `latitude`=22.66154, `longitude`=121.47313, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005837', 'Pasibutbut音樂會系列活動', '《Pasibutbut-山中記憶音樂會》邀您走進延平鄉紅葉村，透過布農族「祈禱小米豐收歌Pasibutbut」的傳唱，體驗音律穿透心靈的療癒魅力。活動涵蓋手工藝體驗、靜心冥想、歌謠演唱、互動舞蹈及趣味闖關等豐富內容，還可參加森林療癒健行、故事分享與在地美食品嘗。結合文化傳承與自然生態，打造深度旅遊新體驗，沉浸在布農族的世界觀中，尋找心靈的平靜與自我。活動日期｜114/08/09-08/10活動地點｜延平鄉紅葉村天眼廣場(祭祀廣場)', '延平鄉公所', '無資料', '2025-08-09 00:00:00', '2025-08-10 23:59:59', '臺東縣臺東市', 22.75547, 121.14834, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Pasibutbut音樂會系列活動', `description`='《Pasibutbut-山中記憶音樂會》邀您走進延平鄉紅葉村，透過布農族「祈禱小米豐收歌Pasibutbut」的傳唱，體驗音律穿透心靈的療癒魅力。活動涵蓋手工藝體驗、靜心冥想、歌謠演唱、互動舞蹈及趣味闖關等豐富內容，還可參加森林療癒健行、故事分享與在地美食品嘗。結合文化傳承與自然生態，打造深度旅遊新體驗，沉浸在布農族的世界觀中，尋找心靈的平靜與自我。活動日期｜114/08/09-08/10活動地點｜延平鄉紅葉村天眼廣場(祭祀廣場)', `organizer`='延平鄉公所', `address`='無資料', `start_date`='2025-08-09 00:00:00', `end_date`='2025-08-10 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75547, `longitude`=121.14834, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005838', '延平鄉鐵花村快閃市集-延平嚴選/延味平嚐', '延平鄉將於鐵花村舉辦「快閃市集&mdash;延平嚴選/延味平嚐」，作為《Pasibutbut-山中記憶音樂會》的記者會與活動前哨站。市集以延平鄉在地特色為主軸，展示布農族文化風味及農特產品，包括手工藝品、布農傳統美食與在地農產。現場並安排布農族歌舞快閃表演，結合音律與文化展示，增進對布農族生活智慧的了解。透過市集活動，讓參與者提前感受延平鄉自然與文化的結合，並為後續活動揭開序幕。活動地點設於台東市鐵花村音樂聚落。活動日期｜114/07/26-07/27活動地點｜預計於鐵花村廣場', '延平鄉公所', '無資料', '2025-07-26 00:00:00', '2025-07-27 23:59:59', '臺東縣臺東市', 22.75376, 121.14575, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='延平鄉鐵花村快閃市集-延平嚴選/延味平嚐', `description`='延平鄉將於鐵花村舉辦「快閃市集&mdash;延平嚴選/延味平嚐」，作為《Pasibutbut-山中記憶音樂會》的記者會與活動前哨站。市集以延平鄉在地特色為主軸，展示布農族文化風味及農特產品，包括手工藝品、布農傳統美食與在地農產。現場並安排布農族歌舞快閃表演，結合音律與文化展示，增進對布農族生活智慧的了解。透過市集活動，讓參與者提前感受延平鄉自然與文化的結合，並為後續活動揭開序幕。活動地點設於台東市鐵花村音樂聚落。活動日期｜114/07/26-07/27活動地點｜預計於鐵花村廣場', `organizer`='延平鄉公所', `address`='無資料', `start_date`='2025-07-26 00:00:00', `end_date`='2025-07-27 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75376, `longitude`=121.14575, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005839', '臺東縣延平鄉全鄉暨後備軍人運動大會', '為推廣全民運動暨傳承布農傳統競技，114年度臺東縣延平鄉全鄉暨後備軍人運動大會將於本鄉棒壘球田徑綜合體育場隆重登場，屆時辦理布農族相關競賽項目，包括射箭、田徑項目等，展現布農族運動能量。活動日期｜114/10/10-10/11活動地點｜延平鄉桃源國中操場', '延平鄉公所', '無資料', '2025-10-10 00:00:00', '2025-10-11 23:59:59', '臺東縣延平鄉', 22.96779, 121.11515, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺東縣延平鄉全鄉暨後備軍人運動大會', `description`='為推廣全民運動暨傳承布農傳統競技，114年度臺東縣延平鄉全鄉暨後備軍人運動大會將於本鄉棒壘球田徑綜合體育場隆重登場，屆時辦理布農族相關競賽項目，包括射箭、田徑項目等，展現布農族運動能量。活動日期｜114/10/10-10/11活動地點｜延平鄉桃源國中操場', `organizer`='延平鄉公所', `address`='無資料', `start_date`='2025-10-10 00:00:00', `end_date`='2025-10-11 23:59:59', `location`='臺東縣延平鄉', `latitude`=22.96779, `longitude`=121.11515, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005840', '2025鹿野「花鹿米」養生樂活節實施計畫', '一、農遊(6-8月份，暫訂)：(1)永安玉龍泉-溯溪.品茶和水澗風味餐初體驗!(2)永安自然學校 窯烤披薩 小泰山趴趴GO!!(3)山川咊咊叫夢想起飛～熱氣球walk In(9梯次)   (4)脫線牧場 前棟Tauzing 雞雞食玩派對(2梯次)(5)手作控必選- 刻印出屬於自己的茶型糊染-束口袋(2梯次)   (6)為黑夜的到來揭開序幕-植物拓印燈與夜間星空導覽(7)重返山瑠sangliw原食的秘密(2梯次) (8) PARAYAP 以物易物部落 走讀(2梯次)(9)大原哈客庄-蔗視誰灶~窯(10)愛上大原哈客庄～插秧趣二、八個野鹿來辦桌(7/13，暫訂)：鹿野鄉擁有豐富的農特產，以及多元的社區部落文化，將邀請八個社區或社團，加入辦桌的行列，於本鄉風景優美的武陵綠色隧道舉辦有質感的產地餐桌活動，邀請全國200位來賓前來鹿野，享用八個野鹿所提供的「花鹿米」農村風味餐。活動地點｜鹿野鄉公所前方花燈公園', '鹿野鄉公所', '無資料', '2025-06-01 00:00:00', '2025-08-31 23:59:59', '臺東縣臺東市', 22.75547, 121.14834, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025鹿野「花鹿米」養生樂活節實施計畫', `description`='一、農遊(6-8月份，暫訂)：(1)永安玉龍泉-溯溪.品茶和水澗風味餐初體驗!(2)永安自然學校 窯烤披薩 小泰山趴趴GO!!(3)山川咊咊叫夢想起飛～熱氣球walk In(9梯次)   (4)脫線牧場 前棟Tauzing 雞雞食玩派對(2梯次)(5)手作控必選- 刻印出屬於自己的茶型糊染-束口袋(2梯次)   (6)為黑夜的到來揭開序幕-植物拓印燈與夜間星空導覽(7)重返山瑠sangliw原食的秘密(2梯次) (8) PARAYAP 以物易物部落 走讀(2梯次)(9)大原哈客庄-蔗視誰灶~窯(10)愛上大原哈客庄～插秧趣二、八個野鹿來辦桌(7/13，暫訂)：鹿野鄉擁有豐富的農特產，以及多元的社區部落文化，將邀請八個社區或社團，加入辦桌的行列，於本鄉風景優美的武陵綠色隧道舉辦有質感的產地餐桌活動，邀請全國200位來賓前來鹿野，享用八個野鹿所提供的「花鹿米」農村風味餐。活動地點｜鹿野鄉公所前方花燈公園', `organizer`='鹿野鄉公所', `address`='無資料', `start_date`='2025-06-01 00:00:00', `end_date`='2025-08-31 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75547, `longitude`=121.14834, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
