INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005842', '關山鎮Fun遊趣系列活動｜親水公園親子戲水趣', '戲水趣為本鎮Fun遊趣系列活動之一，在炎炎夏日中來到親水公園，享受大自然的芬多精，並設有多個大型滑水道，可以親子共遊攜家帶眷，來度過一個充滿歡樂的暑假。活動日期｜114/7/1-114/9/1活動地點｜親水公園', '關山鎮公所', '無資料', '2025-07-01 00:00:00', '2025-09-01 23:59:59', '臺東縣關山鎮', 23.03979, 121.17202, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='關山鎮Fun遊趣系列活動｜親水公園親子戲水趣', `description`='戲水趣為本鎮Fun遊趣系列活動之一，在炎炎夏日中來到親水公園，享受大自然的芬多精，並設有多個大型滑水道，可以親子共遊攜家帶眷，來度過一個充滿歡樂的暑假。活動日期｜114/7/1-114/9/1活動地點｜親水公園', `organizer`='關山鎮公所', `address`='無資料', `start_date`='2025-07-01 00:00:00', `end_date`='2025-09-01 23:59:59', `location`='臺東縣關山鎮', `latitude`=23.03979, `longitude`=121.17202, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005843', '原來不簡單生活節', '規劃「原式音樂、原民樂舞、農產行銷、原鄉路跑」為本系列活動辦理主軸，期以「傳承原住民族傳統文化」的想法，運用文化創意及運動觀光概念，規劃在宣傳行銷內容裡；再者本活動主要是提升關山鎮的旅遊知名度，讓享受及體驗各部落傳統文化、美景、休閒運動，品嚐道地關山米及部落美食、體驗手作原民工藝，更希冀藉由舉辦原民音樂會元素，讓各地觀光客，願意前來關山並使之消費，吸引旅遊人潮，促進本鎮農旅產業發展，帶動關山米品牌商機，朝向永續經營為最終目標。活動日期｜暫訂8月活動地點｜關山國小', '臺東縣關山鎮公所', '無資料', '2025-08-01 15:00:00', '2025-08-31 21:00:00', '臺東縣關山鎮', 23.05029, 121.16421, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='原來不簡單生活節', `description`='規劃「原式音樂、原民樂舞、農產行銷、原鄉路跑」為本系列活動辦理主軸，期以「傳承原住民族傳統文化」的想法，運用文化創意及運動觀光概念，規劃在宣傳行銷內容裡；再者本活動主要是提升關山鎮的旅遊知名度，讓享受及體驗各部落傳統文化、美景、休閒運動，品嚐道地關山米及部落美食、體驗手作原民工藝，更希冀藉由舉辦原民音樂會元素，讓各地觀光客，願意前來關山並使之消費，吸引旅遊人潮，促進本鎮農旅產業發展，帶動關山米品牌商機，朝向永續經營為最終目標。活動日期｜暫訂8月活動地點｜關山國小', `organizer`='臺東縣關山鎮公所', `address`='無資料', `start_date`='2025-08-01 15:00:00', `end_date`='2025-08-31 21:00:00', `location`='臺東縣關山鎮', `latitude`=23.05029, `longitude`=121.16421, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005844', '2025夜訪關山｜遊龍守護關山圳', '為感念關山鎮先民建造大圳，並灌溉孕育出關山最優質的好米，藉由本次活動讓在地居民與遊客參與活動，讓外來遊客了解關山大圳對關山地區的重要性，因此特舉辦夜訪關山提燈籠護水圳體驗活動，讓大家懷著感恩的心情，體會先民開田闢地的辛勞。集合地點｜關山天后宮', '臺東縣關山鎮公所', '無資料', '2025-10-01 00:00:00', '2025-10-10 23:59:59', '臺東縣關山鎮', 23.04906, 121.16281, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025夜訪關山｜遊龍守護關山圳', `description`='為感念關山鎮先民建造大圳，並灌溉孕育出關山最優質的好米，藉由本次活動讓在地居民與遊客參與活動，讓外來遊客了解關山大圳對關山地區的重要性，因此特舉辦夜訪關山提燈籠護水圳體驗活動，讓大家懷著感恩的心情，體會先民開田闢地的辛勞。集合地點｜關山天后宮', `organizer`='臺東縣關山鎮公所', `address`='無資料', `start_date`='2025-10-01 00:00:00', `end_date`='2025-10-10 23:59:59', `location`='臺東縣關山鎮', `latitude`=23.04906, `longitude`=121.16281, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005845', '114年收冬大戲', '收冬戲為知名傳統戲曲，又稱為平安戲，是指在秋天收成後，用以答謝神明保佑，風調雨順五穀豐收，除了有豐富的牲禮祭祀外，更會邀請知名戲班到眾神前獻演以表謝意。活動日期｜114/12活動地點｜關山國小活動細節待公布', '臺東縣關山鎮公所', '無資料', '2025-12-01 00:00:00', '2025-12-31 23:59:59', '臺東縣關山鎮', 23.05029, 121.16421, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年收冬大戲', `description`='收冬戲為知名傳統戲曲，又稱為平安戲，是指在秋天收成後，用以答謝神明保佑，風調雨順五穀豐收，除了有豐富的牲禮祭祀外，更會邀請知名戲班到眾神前獻演以表謝意。活動日期｜114/12活動地點｜關山國小活動細節待公布', `organizer`='臺東縣關山鎮公所', `address`='無資料', `start_date`='2025-12-01 00:00:00', `end_date`='2025-12-31 23:59:59', `location`='臺東縣關山鎮', `latitude`=23.05029, `longitude`=121.16421, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005846', '2025悠活池上-米鄉竹筏季系列活動｜竹筏季節慶嘉年華', '本鄉年度盛事-2025悠活池上米鄉竹筏季活動將邁入第24周年，活動主軸採傳統竹筏作水上相關競賽，主要為竹筏300M直道競速與竹筏拔河賽；活動每年召喚全民好手組隊共襄盛，期待能成為台灣最具特色竹筏龍舟水上活動賽事，邀請全國好手一起來挑戰!活動日期｜114/05/24、05/25（六、日）活動地點｜臺東縣池上鄉大坡池風景區', '池上鄉公所', '無資料', '2025-05-24 00:00:00', '2025-05-25 23:59:59', '臺東縣池上鄉', 23.12017, 121.22328, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025悠活池上-米鄉竹筏季系列活動｜竹筏季節慶嘉年華', `description`='本鄉年度盛事-2025悠活池上米鄉竹筏季活動將邁入第24周年，活動主軸採傳統竹筏作水上相關競賽，主要為竹筏300M直道競速與竹筏拔河賽；活動每年召喚全民好手組隊共襄盛，期待能成為台灣最具特色竹筏龍舟水上活動賽事，邀請全國好手一起來挑戰!活動日期｜114/05/24、05/25（六、日）活動地點｜臺東縣池上鄉大坡池風景區', `organizer`='池上鄉公所', `address`='無資料', `start_date`='2025-05-24 00:00:00', `end_date`='2025-05-25 23:59:59', `location`='臺東縣池上鄉', `latitude`=23.12017, `longitude`=121.22328, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005847', '2025池上星夜慢城路跑', '推動全民健康休閒觀光活動，結合池上鄉晝與夜之絕美地景、觀光產業特色，邀請各地愛好健康休閒旅遊者，用雙腳探索池上鄉間道路，運動間吸取稻香之芬芳，夜間閑靜田園與數不盡的星星與清澈的銀河之際，迎風揮灑汗水，感受最純粹的自然幸福在身心串動與親身體驗在地慢生活。活動日期｜114/10/04（六）活動地點｜臺東縣池上鄉大坡池風景區', '池上鄉公所', '無資料', '2025-10-04 00:00:00', '2025-10-04 23:59:59', '臺東縣池上鄉', 23.12017, 121.22328, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025池上星夜慢城路跑', `description`='推動全民健康休閒觀光活動，結合池上鄉晝與夜之絕美地景、觀光產業特色，邀請各地愛好健康休閒旅遊者，用雙腳探索池上鄉間道路，運動間吸取稻香之芬芳，夜間閑靜田園與數不盡的星星與清澈的銀河之際，迎風揮灑汗水，感受最純粹的自然幸福在身心串動與親身體驗在地慢生活。活動日期｜114/10/04（六）活動地點｜臺東縣池上鄉大坡池風景區', `organizer`='池上鄉公所', `address`='無資料', `start_date`='2025-10-04 00:00:00', `end_date`='2025-10-04 23:59:59', `location`='臺東縣池上鄉', `latitude`=23.12017, `longitude`=121.22328, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005848', '2025成功鎮花火之夜', '璀璨煙花迎新春！ 除夕夜將舉辦一場盛大的煙花秀。以「璀璨夜空，成功齊發」為主題，絢麗的煙花將在夜空中綻放，搭配動感的音樂，帶來一場視聽盛宴。邀請返鄉者或遊客一同前來，共度溫馨愉快的除夕夜。❚活動日期：114年1月28日 ㈡❚活動時間：20:30(發小紅包)、21:00(施放煙火)❚施放地點：成功鎮海濱公園', '成功鎮公所', '無資料', '2025-01-28 21:00:00', '2025-01-28 23:59:59', '臺東縣成功鎮', 23.10404, 121.38497, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025成功鎮花火之夜', `description`='璀璨煙花迎新春！ 除夕夜將舉辦一場盛大的煙花秀。以「璀璨夜空，成功齊發」為主題，絢麗的煙花將在夜空中綻放，搭配動感的音樂，帶來一場視聽盛宴。邀請返鄉者或遊客一同前來，共度溫馨愉快的除夕夜。❚活動日期：114年1月28日 ㈡❚活動時間：20:30(發小紅包)、21:00(施放煙火)❚施放地點：成功鎮海濱公園', `organizer`='成功鎮公所', `address`='無資料', `start_date`='2025-01-28 21:00:00', `end_date`='2025-01-28 23:59:59', `location`='臺東縣成功鎮', `latitude`=23.10404, `longitude`=121.38497, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005849', '2025成功鎮元宵遶境炸寒單', '為慶祝元宵節，成功鎮公所將於114年2月12日星期三（農曆正月15日元宵節）上午9時在成功鎮公所前廣場舉辦「炮炸寒單─慶元宵」祈福儀式，為遶境活動揭開序幕，以發揚臺東縣傳統民俗文化、提倡民俗藝術，並於當日中午12時起開始宮廟繞境祈福活動，敬邀各位鄉親共襄盛舉、敬備香案，一同來祈求國泰民安、風調雨順，同時敬祝鄉親闔家平安、生意興隆、萬事如意活動時間｜114年2月12日 星期三活動地點｜成功鎮公所前廣場', '成功鎮公所', '無資料', '2025-02-12 00:00:00', '2025-02-12 23:59:59', '臺東縣成功鎮', 23.10504, 121.38076, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025成功鎮元宵遶境炸寒單', `description`='為慶祝元宵節，成功鎮公所將於114年2月12日星期三（農曆正月15日元宵節）上午9時在成功鎮公所前廣場舉辦「炮炸寒單─慶元宵」祈福儀式，為遶境活動揭開序幕，以發揚臺東縣傳統民俗文化、提倡民俗藝術，並於當日中午12時起開始宮廟繞境祈福活動，敬邀各位鄉親共襄盛舉、敬備香案，一同來祈求國泰民安、風調雨順，同時敬祝鄉親闔家平安、生意興隆、萬事如意活動時間｜114年2月12日 星期三活動地點｜成功鎮公所前廣場', `organizer`='成功鎮公所', `address`='無資料', `start_date`='2025-02-12 00:00:00', `end_date`='2025-02-12 23:59:59', `location`='臺東縣成功鎮', `latitude`=23.10504, `longitude`=121.38076, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005850', '2025如魚得水．端午SUP', '傳統龍舟玩膩了？今年端午節，成功鎮石雨傘遊憩區邀請您體驗不一樣的水上運動！特別規劃了SUP立槳競賽，讓您在美麗的石雨傘海域盡情揮灑體力及汗水，感受不一樣的端午節！活動日期｜114/05/31活動地點｜雨傘港灣', '成功鎮公所', '無資料', '2025-05-31 09:00:00', '2025-05-31 17:00:00', '臺東縣成功鎮', 23.17452, 121.40093, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025如魚得水．端午SUP', `description`='傳統龍舟玩膩了？今年端午節，成功鎮石雨傘遊憩區邀請您體驗不一樣的水上運動！特別規劃了SUP立槳競賽，讓您在美麗的石雨傘海域盡情揮灑體力及汗水，感受不一樣的端午節！活動日期｜114/05/31活動地點｜雨傘港灣', `organizer`='成功鎮公所', `address`='無資料', `start_date`='2025-05-31 09:00:00', `end_date`='2025-05-31 17:00:00', `location`='臺東縣成功鎮', `latitude`=23.17452, `longitude`=121.40093, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005851', '2025浩瀚星河音樂會', '邀請遊客一同沉浸在星光熠熠的夜晚！「最美星空選拔賽」成功鎮榮獲一星等星空，活動將透過音樂與沉浸式的星空主題體驗，帶給您前所未有的感動。 伴隨著悠揚的旋律，仰望璀璨的星空，您將彷彿置身於浩瀚宇宙中，感受宇宙的奧祕。❚活動日期：114/07/12❚活動地點：臺東縣成功鎮海濱公園', '成功鎮公所', '無資料', '2025-07-12 17:00:00', '2025-07-12 21:00:00', '臺東縣成功鎮', 23.10404, 121.38497, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025浩瀚星河音樂會', `description`='邀請遊客一同沉浸在星光熠熠的夜晚！「最美星空選拔賽」成功鎮榮獲一星等星空，活動將透過音樂與沉浸式的星空主題體驗，帶給您前所未有的感動。 伴隨著悠揚的旋律，仰望璀璨的星空，您將彷彿置身於浩瀚宇宙中，感受宇宙的奧祕。❚活動日期：114/07/12❚活動地點：臺東縣成功鎮海濱公園', `organizer`='成功鎮公所', `address`='無資料', `start_date`='2025-07-12 17:00:00', `end_date`='2025-07-12 21:00:00', `location`='臺東縣成功鎮', `latitude`=23.10404, `longitude`=121.38497, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005852', '何爺爺跳跳屋', '暑假就是要玩水又怕危險！炎炎夏日何去呢？成功鎮邀孩童們一起來跳跳屋玩水，盡情釋放夏日熱情！多款造型可愛的水上氣墊設施，可讓孩童在玩樂中消暑一夏！日期：114/07/18~114/07/20地點：成功鎮第一停車場', '成功鎮公所', '無資料', '2025-07-18 00:00:00', '2025-07-20 23:59:59', '臺東縣成功鎮', 23.12615, 121.3656, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='何爺爺跳跳屋', `description`='暑假就是要玩水又怕危險！炎炎夏日何去呢？成功鎮邀孩童們一起來跳跳屋玩水，盡情釋放夏日熱情！多款造型可愛的水上氣墊設施，可讓孩童在玩樂中消暑一夏！日期：114/07/18~114/07/20地點：成功鎮第一停車場', `organizer`='成功鎮公所', `address`='無資料', `start_date`='2025-07-18 00:00:00', `end_date`='2025-07-20 23:59:59', `location`='臺東縣成功鎮', `latitude`=23.12615, `longitude`=121.3656, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005853', '原住民日音樂會', '法拉法黛的天(Falatfatay)，用音樂慶祝原住民日。活動日期｜114/08/01活動地點｜成功鎮原住民文物館', '成功鎮公所', '無資料', '2025-08-01 00:00:00', '2025-08-01 23:59:59', '臺東縣成功鎮', 23.10043, 121.38368, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='原住民日音樂會', `description`='法拉法黛的天(Falatfatay)，用音樂慶祝原住民日。活動日期｜114/08/01活動地點｜成功鎮原住民文物館', `organizer`='成功鎮公所', `address`='無資料', `start_date`='2025-08-01 00:00:00', `end_date`='2025-08-01 23:59:59', `location`='臺東縣成功鎮', `latitude`=23.10043, `longitude`=121.38368, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005854', '成功鎮聯合豐年祭', '成功鎮阿美族各部落將齊聚一堂！豐年祭不只跳舞，還有更多！不僅有精彩的歌舞表演，還有傳統美食、工藝品市集等，可以品嚐道地的原住民料理，選購獨特的紀念品。來聯合豐年祭，深度體驗阿美族豐富的文化底蘊，感受阿美族的熱情。活動日期｜114/08/09活動地點｜成功鎮海濱公園', '成功鎮公所', '無資料', '2025-08-09 00:00:00', '2025-08-09 23:59:59', '臺東縣成功鎮', 23.10404, 121.38497, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='成功鎮聯合豐年祭', `description`='成功鎮阿美族各部落將齊聚一堂！豐年祭不只跳舞，還有更多！不僅有精彩的歌舞表演，還有傳統美食、工藝品市集等，可以品嚐道地的原住民料理，選購獨特的紀念品。來聯合豐年祭，深度體驗阿美族豐富的文化底蘊，感受阿美族的熱情。活動日期｜114/08/09活動地點｜成功鎮海濱公園', `organizer`='成功鎮公所', `address`='無資料', `start_date`='2025-08-09 00:00:00', `end_date`='2025-08-09 23:59:59', `location`='臺東縣成功鎮', `latitude`=23.10404, `longitude`=121.38497, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005855', '114年遨遊成功。誰與箏風', '海天一色下，大型主題風箏飛舞！成功鎮白守蓮觀光公園辦理大型風箏展演秀！主要以海洋主題的風箏在湛藍的天空下翱翔，搭配壯麗的海景，絕對是今夏最難忘的視覺饗宴！ 快來感受這場風箏盛宴，留下美好的回憶！活動日期｜114/09/28活動地點｜成功鎮白守蓮觀光公園', '成功鎮公所', '無資料', '2025-09-28 00:00:00', '2025-09-28 23:59:59', '臺東縣成功鎮', 23.1329, 121.39799, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年遨遊成功。誰與箏風', `description`='海天一色下，大型主題風箏飛舞！成功鎮白守蓮觀光公園辦理大型風箏展演秀！主要以海洋主題的風箏在湛藍的天空下翱翔，搭配壯麗的海景，絕對是今夏最難忘的視覺饗宴！ 快來感受這場風箏盛宴，留下美好的回憶！活動日期｜114/09/28活動地點｜成功鎮白守蓮觀光公園', `organizer`='成功鎮公所', `address`='無資料', `start_date`='2025-09-28 00:00:00', `end_date`='2025-09-28 23:59:59', `location`='臺東縣成功鎮', `latitude`=23.1329, `longitude`=121.39799, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005856', '2025三仙台馬拉松', '成功鎮三仙台路跑活動，將帶您沿著美麗的海岸線奔跑，欣賞壯觀的三仙台地標及海岸線風景，有全馬、半馬、迷你馬等多種組別，適合不同程度的跑者挑戰自我，享受跑步的樂趣！活動日期 : 114/10/19活動地點：成功鎮海濱公園', '臺東縣成功鎮公所', '無資料', '2025-10-19 00:00:00', '2025-10-19 23:59:59', '臺東縣成功鎮', 23.10404, 121.38497, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025三仙台馬拉松', `description`='成功鎮三仙台路跑活動，將帶您沿著美麗的海岸線奔跑，欣賞壯觀的三仙台地標及海岸線風景，有全馬、半馬、迷你馬等多種組別，適合不同程度的跑者挑戰自我，享受跑步的樂趣！活動日期 : 114/10/19活動地點：成功鎮海濱公園', `organizer`='臺東縣成功鎮公所', `address`='無資料', `start_date`='2025-10-19 00:00:00', `end_date`='2025-10-19 23:59:59', `location`='臺東縣成功鎮', `latitude`=23.10404, `longitude`=121.38497, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005857', '2025南迴慢活節—太麻里“咖”好', '於舊華源國小校地舉辦大型活動，並以本鄉一大特色&mdash;栽植於高山面海的咖啡最為活動重點行銷農產；並活用閒置土地，以此活動串接本鄉各大觀光亮點，創造地方產業新的里程碑；活動形式以「夜無眠音樂會」、「夏日市集」為號召，廣邀想逃離塵世，沉浸慢活、慵懶、享受的大家參與。活動日期｜113/07/12(暫訂)活動地點｜華源國小舊校地', '太麻里鄉公所', '無資料', '2025-07-12 00:00:00', '2025-07-12 23:59:59', '臺東縣太麻里鄉', 22.66268, 121.02715, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025南迴慢活節—太麻里“咖”好', `description`='於舊華源國小校地舉辦大型活動，並以本鄉一大特色&mdash;栽植於高山面海的咖啡最為活動重點行銷農產；並活用閒置土地，以此活動串接本鄉各大觀光亮點，創造地方產業新的里程碑；活動形式以「夜無眠音樂會」、「夏日市集」為號召，廣邀想逃離塵世，沉浸慢活、慵懶、享受的大家參與。活動日期｜113/07/12(暫訂)活動地點｜華源國小舊校地', `organizer`='太麻里鄉公所', `address`='無資料', `start_date`='2025-07-12 00:00:00', `end_date`='2025-07-12 23:59:59', `location`='臺東縣太麻里鄉', `latitude`=22.66268, `longitude`=121.02715, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005858', '太麻里套裝體驗活動', '■跟著咖啡趣旅行經由推廣年度重點農產品&mdash;咖啡，舉辦咖啡體驗之旅，讓參與民眾透過活動親自體驗甩豆、去殼、烘豆及磨豆等過程，將生豆磨成粉，到最後手沖出一杯屬於自己的咖啡，不僅有成就感，也能更加的認識極具特色的臺東咖啡。■秘境探索之旅全鄉由北至南各村落都有屬於在地人才知道的秘境，透過全套行程的安排，讓你全部遊賞一番。活動日期｜113/07/01~113/08/31活動地點｜三和、華源、多良等地', '太麻里鄉公所', '無資料', '2025-07-01 00:00:00', '2025-08-31 23:59:59', '臺東縣太麻里鄉', 22.66268, 121.02715, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='太麻里套裝體驗活動', `description`='■跟著咖啡趣旅行經由推廣年度重點農產品&mdash;咖啡，舉辦咖啡體驗之旅，讓參與民眾透過活動親自體驗甩豆、去殼、烘豆及磨豆等過程，將生豆磨成粉，到最後手沖出一杯屬於自己的咖啡，不僅有成就感，也能更加的認識極具特色的臺東咖啡。■秘境探索之旅全鄉由北至南各村落都有屬於在地人才知道的秘境，透過全套行程的安排，讓你全部遊賞一番。活動日期｜113/07/01~113/08/31活動地點｜三和、華源、多良等地', `organizer`='太麻里鄉公所', `address`='無資料', `start_date`='2025-07-01 00:00:00', `end_date`='2025-08-31 23:59:59', `location`='臺東縣太麻里鄉', `latitude`=22.66268, `longitude`=121.02715, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005859', '114年臺東縣達仁鄉縫迴山海小米文化生活節-抓把小米！', '為推廣達仁鄉鄉內各項優質產業，擬以土坂村小米文化為主軸，整合串聯優良在地業者，辦理部落歲時祭儀前導推廣系列活動，並結合本鄉土坂等部落小米收穫祭，加深加廣推動本鄉旅遊品牌「縫迴山海」。預計於2025年6月份辦理「小米文化生活節」系列活動，透過文化課程、音樂饗宴、體驗巡禮走讀以及周邊市集設置，帶領旅客認識達仁鄉在地文化、特色產品與產業。除推廣達仁鄉部落旅遊，特別加入排灣族小米祭儀文化之元素，以增加達仁鄉部落旅遊之豐富度與文化深度。(暫訂)小米音樂會6/21(15:00-20:00)小米文化市集6/21(15:00-20:00)小米文化講座6/14,15,18,21,22工藝體驗6/14,15,21,22小米文化見學旅行6/15山林文化旅行6/22', '達仁鄉公所', '無資料', '2025-06-14 00:00:00', '2025-06-22 23:59:59', '臺東縣臺東市', 22.75547, 121.14834, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年臺東縣達仁鄉縫迴山海小米文化生活節-抓把小米！', `description`='為推廣達仁鄉鄉內各項優質產業，擬以土坂村小米文化為主軸，整合串聯優良在地業者，辦理部落歲時祭儀前導推廣系列活動，並結合本鄉土坂等部落小米收穫祭，加深加廣推動本鄉旅遊品牌「縫迴山海」。預計於2025年6月份辦理「小米文化生活節」系列活動，透過文化課程、音樂饗宴、體驗巡禮走讀以及周邊市集設置，帶領旅客認識達仁鄉在地文化、特色產品與產業。除推廣達仁鄉部落旅遊，特別加入排灣族小米祭儀文化之元素，以增加達仁鄉部落旅遊之豐富度與文化深度。(暫訂)小米音樂會6/21(15:00-20:00)小米文化市集6/21(15:00-20:00)小米文化講座6/14,15,18,21,22工藝體驗6/14,15,21,22小米文化見學旅行6/15山林文化旅行6/22', `organizer`='達仁鄉公所', `address`='無資料', `start_date`='2025-06-14 00:00:00', `end_date`='2025-06-22 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75547, `longitude`=121.14834, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005860', '114年臺東縣達仁鄉縫迴山海祭路跑活動', '1.為辦理健身體育活動辦理一年一度大型活動。搭配專屬遊程結合在地特色文化體驗及運動活動增加遊客停留本鄉時間，另計畫所輔導之亮點業者、在地風味餐及其他觀光業者搭配路跑活動辦理成果展。預定將路跑路線為達仁鄉南三村(安朔村、南田村及森永村)，112年花東基金完工之阿塱壹古道周邊景點加入中繼站使遊客在體運活動進行中欣賞沿路海景及意象。文宣設計加入母語更能展現本鄉較其他路跑活動更具排灣族特色。盼透過計畫將部落村民與遊客沉浸在排灣族文化享受健身慢活。競賽項目分為三種不同組別，預計競賽項目： 半馬組 (21 公里) 挑戰組 (12 公里) 趣味組 (5 公里)2.在活動周邊將設置市集區，展示部落產業、農特產品、原民手工藝和部落小吃等各式豐富多彩的商品。讓賽事之餘，品味當地的美食、感受達仁鄉文化的魅力。', '達仁鄉公所', '無資料', '2025-11-18 00:00:00', '2025-11-19 23:59:59', '臺東縣臺東市', 22.75547, 121.14834, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年臺東縣達仁鄉縫迴山海祭路跑活動', `description`='1.為辦理健身體育活動辦理一年一度大型活動。搭配專屬遊程結合在地特色文化體驗及運動活動增加遊客停留本鄉時間，另計畫所輔導之亮點業者、在地風味餐及其他觀光業者搭配路跑活動辦理成果展。預定將路跑路線為達仁鄉南三村(安朔村、南田村及森永村)，112年花東基金完工之阿塱壹古道周邊景點加入中繼站使遊客在體運活動進行中欣賞沿路海景及意象。文宣設計加入母語更能展現本鄉較其他路跑活動更具排灣族特色。盼透過計畫將部落村民與遊客沉浸在排灣族文化享受健身慢活。競賽項目分為三種不同組別，預計競賽項目： 半馬組 (21 公里) 挑戰組 (12 公里) 趣味組 (5 公里)2.在活動周邊將設置市集區，展示部落產業、農特產品、原民手工藝和部落小吃等各式豐富多彩的商品。讓賽事之餘，品味當地的美食、感受達仁鄉文化的魅力。', `organizer`='達仁鄉公所', `address`='無資料', `start_date`='2025-11-18 00:00:00', `end_date`='2025-11-19 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75547, `longitude`=121.14834, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005861', '金峰印象「攝影比賽」、金峰大地餐桌、金峰－你不知道的事「繪畫比賽」', '原鄉大地藝術生活季，係以生態博物館內之智慧農業相關活動為活動系列主軸，結合本鄉紅金寶三大作物季節時期，共同呈顯與展示系列常態或亮點活動，透過藝術的力量、當地人民生活智慧以及地域的資源，共同展示金峰鄉新面貌，重新喚起了對故鄉的思念，重新感受到了人與人，以及人與土地之間的聯繫。活動日期｜114年8月活動地點｜金峰鄉正興村(暫訂)', '金峰鄉公所', '無資料', '2025-08-01 00:00:00', '2025-08-31 23:59:59', '臺東縣臺東市', 22.75547, 121.14834, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='金峰印象「攝影比賽」、金峰大地餐桌、金峰－你不知道的事「繪畫比賽」', `description`='原鄉大地藝術生活季，係以生態博物館內之智慧農業相關活動為活動系列主軸，結合本鄉紅金寶三大作物季節時期，共同呈顯與展示系列常態或亮點活動，透過藝術的力量、當地人民生活智慧以及地域的資源，共同展示金峰鄉新面貌，重新喚起了對故鄉的思念，重新感受到了人與人，以及人與土地之間的聯繫。活動日期｜114年8月活動地點｜金峰鄉正興村(暫訂)', `organizer`='金峰鄉公所', `address`='無資料', `start_date`='2025-08-01 00:00:00', `end_date`='2025-08-31 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75547, `longitude`=121.14834, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005862', '2025柚見晚崙西亞東河馬拉松嘉年華', '全馬組(42K)、半馬組(21K)、小馬組(6K)。新路線伸延東河的山林景致，一路能遠望海岸山脈的壯麗，世外桃源的泰源幽谷，以及小馬音樂時光隧道，而在登仙橋周邊，還有猴群化身為啦啦隊為跑者加油，也將是路跑過程的一大特色，東河鄉公所更動員全鄉7村鄉民，在沿線精心佈置與準備在地農特產-晚崙西亞及豐盛的補給點心，讓跑者邊跑邊品嚐邊欣賞，感受東河鄉的風土民情與山林景致。 ❚活動日期：2025年3月9日（星期日）❚活動地點：東河國小大操場❚活動項目：全馬組 42K / 半馬組 21K / 小馬組 8K❚報名期間：即日起至 2025/2/20報名連結', '臺東縣東河鄉公所', '無資料', '2025-03-09 00:00:00', '2025-03-09 23:59:59', '臺東縣東河鄉', 22.97094, 121.3041, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025柚見晚崙西亞東河馬拉松嘉年華', `description`='全馬組(42K)、半馬組(21K)、小馬組(6K)。新路線伸延東河的山林景致，一路能遠望海岸山脈的壯麗，世外桃源的泰源幽谷，以及小馬音樂時光隧道，而在登仙橋周邊，還有猴群化身為啦啦隊為跑者加油，也將是路跑過程的一大特色，東河鄉公所更動員全鄉7村鄉民，在沿線精心佈置與準備在地農特產-晚崙西亞及豐盛的補給點心，讓跑者邊跑邊品嚐邊欣賞，感受東河鄉的風土民情與山林景致。 ❚活動日期：2025年3月9日（星期日）❚活動地點：東河國小大操場❚活動項目：全馬組 42K / 半馬組 21K / 小馬組 8K❚報名期間：即日起至 2025/2/20報名連結', `organizer`='臺東縣東河鄉公所', `address`='無資料', `start_date`='2025-03-09 00:00:00', `end_date`='2025-03-09 23:59:59', `location`='臺東縣東河鄉', `latitude`=22.97094, `longitude`=121.3041, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005863', '114年度瑪洛阿瀧聯合豐年祭', '以觀光旅遊、阿美族文化體驗、推廣在地產業等系列活動展現東河鄉人文地產景特色，帶動本鄉觀光旅遊新契機。由鄉公所家政班、語推人員及在地商店規劃在地語言文化體驗闖關(族語好好玩、唱跳原住民歌舞、撒魚網、穿阿美族服拍照及踩高蹺等)活動日期｜114/08/16活動地點｜東河鄉-東河國小', '臺東縣東河鄉公所', '無資料', '2025-08-16 00:00:00', '2025-08-16 23:59:59', '臺東縣東河鄉', 22.97094, 121.3041, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度瑪洛阿瀧聯合豐年祭', `description`='以觀光旅遊、阿美族文化體驗、推廣在地產業等系列活動展現東河鄉人文地產景特色，帶動本鄉觀光旅遊新契機。由鄉公所家政班、語推人員及在地商店規劃在地語言文化體驗闖關(族語好好玩、唱跳原住民歌舞、撒魚網、穿阿美族服拍照及踩高蹺等)活動日期｜114/08/16活動地點｜東河鄉-東河國小', `organizer`='臺東縣東河鄉公所', `address`='無資料', `start_date`='2025-08-16 00:00:00', `end_date`='2025-08-16 23:59:59', `location`='臺東縣東河鄉', `latitude`=22.97094, `longitude`=121.3041, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
