INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005866', '2025長濱雙浪金剛馬拉松選手之夜-來長濱吃辦桌', '公所配合東管處舉辦之長濱金剛雙浪馬拉松比賽，特地在前一晚舉辦「選手之夜-來長濱吃辦桌」活動，由在地的知名店家，使用在地食材製作特色佳餚，以「一家一特色」方式上菜，使來參加比賽遊客能更認識在地餐飲業者及小農產品。活動日期｜2025/05/03(六)活動地點｜長濱鄉公所前廣場 日期時間活動項目2025/05/03(六)來長濱吃辦桌 選手之夜(於報名時加購)16:30-17:00選手之夜報到17:00選手之夜開席17:00-19:00來長濱吃辦桌 選手之夜', '長濱鄉公所', '無資料', '2025-05-03 00:00:00', '2025-05-03 23:59:59', '臺東縣長濱鄉', 23.31503, 121.45153, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025長濱雙浪金剛馬拉松選手之夜-來長濱吃辦桌', `description`='公所配合東管處舉辦之長濱金剛雙浪馬拉松比賽，特地在前一晚舉辦「選手之夜-來長濱吃辦桌」活動，由在地的知名店家，使用在地食材製作特色佳餚，以「一家一特色」方式上菜，使來參加比賽遊客能更認識在地餐飲業者及小農產品。活動日期｜2025/05/03(六)活動地點｜長濱鄉公所前廣場 日期時間活動項目2025/05/03(六)來長濱吃辦桌 選手之夜(於報名時加購)16:30-17:00選手之夜報到17:00選手之夜開席17:00-19:00來長濱吃辦桌 選手之夜', `organizer`='長濱鄉公所', `address`='無資料', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 23:59:59', `location`='臺東縣長濱鄉', `latitude`=23.31503, `longitude`=121.45153, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005867', '2025來長濱~米SALAMA!系列活動', '以米為發想，每年7、8月份為本鄉長濱米豐收季節，活動取名為「米SALAMA!」為阿美族語(MISALAMA)「來玩耍!快來玩!」之意；本所將製作長濱鄉好好玩地圖，集結長濱鄉轄內餐飲、小農伴手禮、旅宿及部落遊程業者，讓來玩的民眾邊玩邊集點，達集點門檻不只能獲得好東西福袋，更能體驗到最道地的長濱日常生活。活動日期｜114/6/27-8/31活動地點｜長濱鄉2025來長濱~米SALAMA!嘉年華活動(名稱暫訂)為「來長濱~米SALAMA!」系列活動，訂於114/8/23下午15時至20時，長濱國小辦理，活動當日將設立近40個攤位，其中有本鄉餐飲店家、小農手作體驗區、小朋友塗鴉區及長濱米烹飪體驗區，另有表演節目，讓來玩的民眾們可以邊吃邊享受chill的午後時光。', '長濱鄉公所', '無資料', '2025-06-27 00:00:00', '2025-08-31 23:59:59', '臺東縣長濱鄉', 23.31682, 121.4554, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025來長濱~米SALAMA!系列活動', `description`='以米為發想，每年7、8月份為本鄉長濱米豐收季節，活動取名為「米SALAMA!」為阿美族語(MISALAMA)「來玩耍!快來玩!」之意；本所將製作長濱鄉好好玩地圖，集結長濱鄉轄內餐飲、小農伴手禮、旅宿及部落遊程業者，讓來玩的民眾邊玩邊集點，達集點門檻不只能獲得好東西福袋，更能體驗到最道地的長濱日常生活。活動日期｜114/6/27-8/31活動地點｜長濱鄉2025來長濱~米SALAMA!嘉年華活動(名稱暫訂)為「來長濱~米SALAMA!」系列活動，訂於114/8/23下午15時至20時，長濱國小辦理，活動當日將設立近40個攤位，其中有本鄉餐飲店家、小農手作體驗區、小朋友塗鴉區及長濱米烹飪體驗區，另有表演節目，讓來玩的民眾們可以邊吃邊享受chill的午後時光。', `organizer`='長濱鄉公所', `address`='無資料', `start_date`='2025-06-27 00:00:00', `end_date`='2025-08-31 23:59:59', `location`='臺東縣長濱鄉', `latitude`=23.31682, `longitude`=121.4554, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005869', '2025月光‧海音樂會', '潮起潮落之間，同時引領期盼充滿新希望的2025。把2025年東海岸大地藝術節最重要的日子筆記起來，為自己預約這年度浪漫美好的月光海音樂會夏夜！活動日期｜6月21日(六)、6月22日(日)7月11日(五)、7月12日(六)-售票場8月09日(六)-售票場、8月10日(日)-企業贊助場9月08日(一) 國立傳統藝術中心臺灣音樂館合作專場、9月9日(二)■ 活動地點：都歷遊客中心台東縣成功鎮信義里新村路25號 (都歷園區，台11線125.5K處)■ 活動時間：PM 04:00~10:00■ 市集時間：PM 04:00~09:30■ 音樂會時間：PM 05:00~10:00', '交通部觀光署東部海岸國家風景區管理處', '無資料', '2025-06-21 00:00:00', '2025-09-09 23:59:59', '臺東縣成功鎮', 23.02034, 121.32495, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025月光‧海音樂會', `description`='潮起潮落之間，同時引領期盼充滿新希望的2025。把2025年東海岸大地藝術節最重要的日子筆記起來，為自己預約這年度浪漫美好的月光海音樂會夏夜！活動日期｜6月21日(六)、6月22日(日)7月11日(五)、7月12日(六)-售票場8月09日(六)-售票場、8月10日(日)-企業贊助場9月08日(一) 國立傳統藝術中心臺灣音樂館合作專場、9月9日(二)■ 活動地點：都歷遊客中心台東縣成功鎮信義里新村路25號 (都歷園區，台11線125.5K處)■ 活動時間：PM 04:00~10:00■ 市集時間：PM 04:00~09:30■ 音樂會時間：PM 05:00~10:00', `organizer`='交通部觀光署東部海岸國家風景區管理處', `address`='無資料', `start_date`='2025-06-21 00:00:00', `end_date`='2025-09-09 23:59:59', `location`='臺東縣成功鎮', `latitude`=23.02034, `longitude`=121.32495, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005870', '2025東海岸大地藝術節及藝文平台', '關於東海岸大地藝術節大地藝術節邀請了各國的藝術家在東海岸駐地創作，除了大型的戶外作品之外，亦有開放藝術工作室、創藝市集、月光&middot;海音樂會等，也讓東海岸旅行更加浪漫豐富。', '交通部觀光署東部海岸國家風景區管理處', '無資料', '2025-06-21 00:00:00', '2025-06-21 23:59:59', '臺東縣臺東市', 22.75547, 121.14834, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025東海岸大地藝術節及藝文平台', `description`='關於東海岸大地藝術節大地藝術節邀請了各國的藝術家在東海岸駐地創作，除了大型的戶外作品之外，亦有開放藝術工作室、創藝市集、月光&middot;海音樂會等，也讓東海岸旅行更加浪漫豐富。', `organizer`='交通部觀光署東部海岸國家風景區管理處', `address`='無資料', `start_date`='2025-06-21 00:00:00', `end_date`='2025-06-21 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75547, `longitude`=121.14834, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005872', '2025臺東電音派對', '以國際級音樂派對形式，有效發揮，活動氛圍營造，也別於往年形式，現場參與超過人數約2500人次，音樂呈現方式及舞台特效設計，讓觀眾全程熱情投入。節目規劃上，也別於往年形式，有藝人跟歌手的合作歌曲，專屬於本案的亮點特色，加深演出的驚艷度。活動日期：114年4月19日活動地點：臺東森林公園活動時間：15:00~22:00', '臺東縣政府民政處自治科', '無資料', '2025-04-19 00:00:00', '2025-04-19 23:59:59', '臺東縣臺東市', 22.76818, 121.15626, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺東電音派對', `description`='以國際級音樂派對形式，有效發揮，活動氛圍營造，也別於往年形式，現場參與超過人數約2500人次，音樂呈現方式及舞台特效設計，讓觀眾全程熱情投入。節目規劃上，也別於往年形式，有藝人跟歌手的合作歌曲，專屬於本案的亮點特色，加深演出的驚艷度。活動日期：114年4月19日活動地點：臺東森林公園活動時間：15:00~22:00', `organizer`='臺東縣政府民政處自治科', `address`='無資料', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 23:59:59', `location`='臺東縣臺東市', `latitude`=22.76818, `longitude`=121.15626, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005881', '2025藍海生活節', '藍海生活節是台東每年舉辦的海洋與水域遊憩活動，結合水上運動、舟船體驗、親水活動及環保理念，讓民眾體驗、享受自然之美，並提升海洋保育意識。活動期間於活水湖有定時水舞展演，為獨特的視覺聽覺饗宴。', '臺東縣政府交通及觀光發展處', '無資料', '2025-10-03 00:00:00', '2025-10-12 23:59:59', '臺東縣臺東市', 22.76521, 121.16477, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025藍海生活節', `description`='藍海生活節是台東每年舉辦的海洋與水域遊憩活動，結合水上運動、舟船體驗、親水活動及環保理念，讓民眾體驗、享受自然之美，並提升海洋保育意識。活動期間於活水湖有定時水舞展演，為獨特的視覺聽覺饗宴。', `organizer`='臺東縣政府交通及觀光發展處', `address`='無資料', `start_date`='2025-10-03 00:00:00', `end_date`='2025-10-12 23:59:59', `location`='臺東縣臺東市', `latitude`=22.76521, `longitude`=121.16477, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005882', '2025臺灣國際熱氣球嘉年華', '臺灣國際熱氣球嘉年華即將邁入第15年，熱氣球嘉年華已成為臺東的象徵，並且是每年暑假最盛大、最具代表性的活動之一。活動秉持創新思維，挑戰各種可能性，光雕音樂會、無人積極煙火展演已是活動必備精彩內容，加上每年邀請逾20多顆來自世界各國造型獨特的熱氣球參展，這不僅吸引了大量遊客，也為地方產業注入了活力，民眾無需出國，就能體驗到國際級的活動盛宴。全國記者會3/30 (日) 19:00 台東縣立體育場將以無人機揭曉今年熱氣球最強IP2025熱氣球嘉年華光雕音樂會場次 (1) 7/05 (六) 05：30 鹿野鄉 鹿野高台(精彩首秀，萬球齊飛) (2) 7/06 (日) 19：00 鹿野鄉 鹿野高台(開幕式)【熱氣球光雕FEAT無人機+煙火】 (3) 7/10 (四) 04：00 太麻里鄉 太麻里曙光園區【曙光場光雕】 (4) 7/17 (四) 19：00 鹿野鄉 鹿野高台【熱氣球光雕FEAT無人機+煙火】 (5) 7/24 (四) 19：00 池上鄉 大坡池【熱氣球光雕+煙火】 (6) 7/31 (四) 19：00 鹿野鄉 鹿野高台【熱氣球光雕FEAT無人機】 (7) 8/07 (四) 19：00 臺東市 國際地標【熱氣球光雕FEAT無人機+煙火】 (8) 8/14 (四) 19：00 鹿野鄉 鹿野高台【熱氣球光雕FEAT無人機+煙火】 (9) 8/21 (四) 19：00 鹿野鄉 鹿野高台(閉幕式)【熱氣球光雕FEAT無人機+煙火】7/5-8/21鹿野高台造型球展演及繫留體驗上午場｜05:30-07:00下午場｜17:00-18:30*每週二為活動公休日', '臺東縣政府交通及觀光發展處', '無資料', '2025-07-05 00:00:00', '2025-08-21 23:59:59', '臺東縣鹿野鄉', 22.91645, 121.12159, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺灣國際熱氣球嘉年華', `description`='臺灣國際熱氣球嘉年華即將邁入第15年，熱氣球嘉年華已成為臺東的象徵，並且是每年暑假最盛大、最具代表性的活動之一。活動秉持創新思維，挑戰各種可能性，光雕音樂會、無人積極煙火展演已是活動必備精彩內容，加上每年邀請逾20多顆來自世界各國造型獨特的熱氣球參展，這不僅吸引了大量遊客，也為地方產業注入了活力，民眾無需出國，就能體驗到國際級的活動盛宴。全國記者會3/30 (日) 19:00 台東縣立體育場將以無人機揭曉今年熱氣球最強IP2025熱氣球嘉年華光雕音樂會場次 (1) 7/05 (六) 05：30 鹿野鄉 鹿野高台(精彩首秀，萬球齊飛) (2) 7/06 (日) 19：00 鹿野鄉 鹿野高台(開幕式)【熱氣球光雕FEAT無人機+煙火】 (3) 7/10 (四) 04：00 太麻里鄉 太麻里曙光園區【曙光場光雕】 (4) 7/17 (四) 19：00 鹿野鄉 鹿野高台【熱氣球光雕FEAT無人機+煙火】 (5) 7/24 (四) 19：00 池上鄉 大坡池【熱氣球光雕+煙火】 (6) 7/31 (四) 19：00 鹿野鄉 鹿野高台【熱氣球光雕FEAT無人機】 (7) 8/07 (四) 19：00 臺東市 國際地標【熱氣球光雕FEAT無人機+煙火】 (8) 8/14 (四) 19：00 鹿野鄉 鹿野高台【熱氣球光雕FEAT無人機+煙火】 (9) 8/21 (四) 19：00 鹿野鄉 鹿野高台(閉幕式)【熱氣球光雕FEAT無人機+煙火】7/5-8/21鹿野高台造型球展演及繫留體驗上午場｜05:30-07:00下午場｜17:00-18:30*每週二為活動公休日', `organizer`='臺東縣政府交通及觀光發展處', `address`='無資料', `start_date`='2025-07-05 00:00:00', `end_date`='2025-08-21 23:59:59', `location`='臺東縣鹿野鄉', `latitude`=22.91645, `longitude`=121.12159, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005883', '2025台東最美星空音樂會', '台東最美星空系列活動舉辦即將邁入第八年，活動以夜間觀星活動為主軸並搭配優美的樂音表演方式，每年6-8月間在臺東境內各鄉鎮擇地辦理，結合視覺與聽覺饗宴的星空音樂會，讓更多旅客在縱谷或海邊體驗不一樣的臺東璀璨夜晚星空世界！音樂會時間：18:30-21:30 / 免費入場06月07日（六）｜東河鄉 金樽陸連島沙灘06月14日（六）｜卑南鄉 達魯瑪克文化廣場06月28日（六）｜關山鎮 關山環鎮自行車道紅石溪畔07月26日（六）｜大武鄉 9420濱海休憩區08月02日（六）｜長濱鄉 八仙洞08月16日（六）｜海端鄉 （敬請期待）08月23日（六）｜成功鎮 三仙台遊憩區08月30日（六）｜綠島鄉 人權紀念公園', '臺東縣政府交通及觀光發展處', '無資料', '2025-06-07 19:00:00', '2025-08-30 21:00:00', '臺東縣臺東市', 22.76132, 121.14382, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台東最美星空音樂會', `description`='台東最美星空系列活動舉辦即將邁入第八年，活動以夜間觀星活動為主軸並搭配優美的樂音表演方式，每年6-8月間在臺東境內各鄉鎮擇地辦理，結合視覺與聽覺饗宴的星空音樂會，讓更多旅客在縱谷或海邊體驗不一樣的臺東璀璨夜晚星空世界！音樂會時間：18:30-21:30 / 免費入場06月07日（六）｜東河鄉 金樽陸連島沙灘06月14日（六）｜卑南鄉 達魯瑪克文化廣場06月28日（六）｜關山鎮 關山環鎮自行車道紅石溪畔07月26日（六）｜大武鄉 9420濱海休憩區08月02日（六）｜長濱鄉 八仙洞08月16日（六）｜海端鄉 （敬請期待）08月23日（六）｜成功鎮 三仙台遊憩區08月30日（六）｜綠島鄉 人權紀念公園', `organizer`='臺東縣政府交通及觀光發展處', `address`='無資料', `start_date`='2025-06-07 19:00:00', `end_date`='2025-08-30 21:00:00', `location`='臺東縣臺東市', `latitude`=22.76132, `longitude`=121.14382, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005884', '2025臺灣國際衝浪公開賽', '臺灣四面環海，擁有豐沛的海洋資源，其中臺東縣擁有全國最長176公里的綿延海岸線，具備海洋運動觀光發展潛力，尤其在東北季風吹拂下，助長東河、金樽一帶浪勢，金樽地勢得天獨厚，其風向與水質共同成就了我國難得的高級浪首選之地，非常適合發展東海岸衝浪活動，成為當地主要觀光海域特色。', '臺東縣政府交通及觀光發展處', '無資料', '2025-07-07 00:00:00', '2025-07-15 23:59:59', '無資料', 22.95394, 121.29321, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺灣國際衝浪公開賽', `description`='臺灣四面環海，擁有豐沛的海洋資源，其中臺東縣擁有全國最長176公里的綿延海岸線，具備海洋運動觀光發展潛力，尤其在東北季風吹拂下，助長東河、金樽一帶浪勢，金樽地勢得天獨厚，其風向與水質共同成就了我國難得的高級浪首選之地，非常適合發展東海岸衝浪活動，成為當地主要觀光海域特色。', `organizer`='臺東縣政府交通及觀光發展處', `address`='無資料', `start_date`='2025-07-07 00:00:00', `end_date`='2025-07-15 23:59:59', `location`='無資料', `latitude`=22.95394, `longitude`=121.29321, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005885', '2025臺東慢食節｜春天場', '找尋山海之間代代傳承的味蕾記憶，展演當代臺東多元迷人的飲食風貌。「臺東慢食節」從臺東土地誕生，由縣府整合臺東店家、廚人、企劃團隊一同打造一場場的飲食文化慶典，每一場次皆從不同風土食材或飲食議題探索臺東的飲食脈絡，在呈現臺東風情的同時，也進行食物教育與文化傳承。活動日期｜4/19 &ndash; 4/20活動地點｜成功海濱公園', '臺東縣政府農業處', '無資料', '2025-04-19 10:00:00', '2025-04-20 21:00:00', '臺東縣成功鎮', 23.10404, 121.38497, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺東慢食節｜春天場', `description`='找尋山海之間代代傳承的味蕾記憶，展演當代臺東多元迷人的飲食風貌。「臺東慢食節」從臺東土地誕生，由縣府整合臺東店家、廚人、企劃團隊一同打造一場場的飲食文化慶典，每一場次皆從不同風土食材或飲食議題探索臺東的飲食脈絡，在呈現臺東風情的同時，也進行食物教育與文化傳承。活動日期｜4/19 &ndash; 4/20活動地點｜成功海濱公園', `organizer`='臺東縣政府農業處', `address`='無資料', `start_date`='2025-04-19 10:00:00', `end_date`='2025-04-20 21:00:00', `location`='臺東縣成功鎮', `latitude`=23.10404, `longitude`=121.38497, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005886', '南島咖啡節市集', '臺東縣政府以競賽、市集、工作坊等系列活動推廣台東咖啡品牌，市集活動邀請國際及國內咖啡各領域品牌現場展售，能一次品嚐台東南迴、縱谷或東海岸好咖啡，更涵蓋咖啡評鑑得獎豆交流分享會、講座體驗和表演等有趣內容，歡迎來自各地的大人小孩參與，由外而內沈浸式體驗南島咖啡風格慶典。', '臺東縣政府農業處', '無資料', '2025-07-01 00:00:00', '2025-08-01 23:59:59', '臺東縣臺東市', 22.75194, 121.14705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南島咖啡節市集', `description`='臺東縣政府以競賽、市集、工作坊等系列活動推廣台東咖啡品牌，市集活動邀請國際及國內咖啡各領域品牌現場展售，能一次品嚐台東南迴、縱谷或東海岸好咖啡，更涵蓋咖啡評鑑得獎豆交流分享會、講座體驗和表演等有趣內容，歡迎來自各地的大人小孩參與，由外而內沈浸式體驗南島咖啡風格慶典。', `organizer`='臺東縣政府農業處', `address`='無資料', `start_date`='2025-07-01 00:00:00', `end_date`='2025-08-01 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75194, `longitude`=121.14705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005887', '(暫訂)2025波浪屋端午節活動', '本活動周邊配置了特色攤位、DIY體驗，透過跨域合作讓民眾沈浸於在地原民工藝及飲食文化饗宴，認識職人多彩豐富內涵，為波浪屋原創館注入更多元創意能量，歡迎民眾行動支持原住民族原創力量。', '臺東縣政府原住民族行政處', '無資料', '2025-05-30 00:00:00', '2025-06-01 23:59:59', '臺東縣臺東市', 22.75376, 121.14575, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='(暫訂)2025波浪屋端午節活動', `description`='本活動周邊配置了特色攤位、DIY體驗，透過跨域合作讓民眾沈浸於在地原民工藝及飲食文化饗宴，認識職人多彩豐富內涵，為波浪屋原創館注入更多元創意能量，歡迎民眾行動支持原住民族原創力量。', `organizer`='臺東縣政府原住民族行政處', `address`='無資料', `start_date`='2025-05-30 00:00:00', `end_date`='2025-06-01 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75376, `longitude`=121.14575, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005889', '2025波浪屋月亮聚活動', '源自於金峰鄉金崙溪流域及太麻里溪流域的排灣族早期在月圓時，部落青年吟唱傳統歌謠、聯繫情感，傳遞族人歡聚和情感交流，波浪屋月亮聚活動將於下午15時至20時(暫定)於波浪屋舉行，本活動安排原住民族歌舞表演活動、周邊配置了特色攤位、DIY體驗，透過跨域合作讓民眾沈浸於在地原民工藝及飲食文化饗宴，認識職人多彩豐富內涵，為波浪屋原創館注入更多元創意能量，歡迎民眾行動支持原住民族原創力量。', '臺東縣政府原住民族行政處', '無資料', '2025-10-04 00:00:00', '2025-10-06 23:59:59', '臺東縣臺東市', 22.75367, 121.14595, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025波浪屋月亮聚活動', `description`='源自於金峰鄉金崙溪流域及太麻里溪流域的排灣族早期在月圓時，部落青年吟唱傳統歌謠、聯繫情感，傳遞族人歡聚和情感交流，波浪屋月亮聚活動將於下午15時至20時(暫定)於波浪屋舉行，本活動安排原住民族歌舞表演活動、周邊配置了特色攤位、DIY體驗，透過跨域合作讓民眾沈浸於在地原民工藝及飲食文化饗宴，認識職人多彩豐富內涵，為波浪屋原創館注入更多元創意能量，歡迎民眾行動支持原住民族原創力量。', `organizer`='臺東縣政府原住民族行政處', `address`='無資料', `start_date`='2025-10-04 00:00:00', `end_date`='2025-10-06 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75367, `longitude`=121.14595, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005890', '流行音樂經典金曲《30-20-30》計畫｜樂廣場3樂份活動', '「樂廣場」於2025年3月到5月執行共40天的音樂展演演出活動，歡迎來臺東藝文中心前廣場，一起聽音樂、逛市集，感受臺東的創作能量，或是按下回憶的播放鍵，回味心中那一曲熟悉的旋律！▌流動樂yu&egrave; 舞台流動樂舞台 每週五六日 19:30-20:30▌樂l&egrave; 市集樂市集 每週五六日 16:00-21:00 3/15-16還有家電門診，等你帶心愛的小型家電來看病。▌樂y&agrave;o 上課音樂人才培育 演場會製作概論與實作報名連結', '臺東縣政府', '無資料', '2025-03-07 00:00:00', '2025-03-30 23:59:59', '臺東縣臺東市', 22.75654, 121.14461, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='流行音樂經典金曲《30-20-30》計畫｜樂廣場3樂份活動', `description`='「樂廣場」於2025年3月到5月執行共40天的音樂展演演出活動，歡迎來臺東藝文中心前廣場，一起聽音樂、逛市集，感受臺東的創作能量，或是按下回憶的播放鍵，回味心中那一曲熟悉的旋律！▌流動樂yu&egrave; 舞台流動樂舞台 每週五六日 19:30-20:30▌樂l&egrave; 市集樂市集 每週五六日 16:00-21:00 3/15-16還有家電門診，等你帶心愛的小型家電來看病。▌樂y&agrave;o 上課音樂人才培育 演場會製作概論與實作報名連結', `organizer`='臺東縣政府', `address`='無資料', `start_date`='2025-03-07 00:00:00', `end_date`='2025-03-30 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75654, `longitude`=121.14461, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005891', '那年，我們一起聽的歌', '以音樂展演創造表演舞台方式為主，每場次邀請3~4位藝人及在地團隊，進行2小時音樂演出活動，營造帶動地方文化產業發展契機，並提高樂齡居民參與地方社區活動參與率。活動地點｜北町日式建築宿舍群、南京路廣場、關山鎮、長濱鄉、達仁鄉', '臺東縣政府文化處', '無資料', '2025-05-01 00:00:00', '2025-10-15 23:59:59', '臺東縣臺東市', 22.75547, 121.14834, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='那年，我們一起聽的歌', `description`='以音樂展演創造表演舞台方式為主，每場次邀請3~4位藝人及在地團隊，進行2小時音樂演出活動，營造帶動地方文化產業發展契機，並提高樂齡居民參與地方社區活動參與率。活動地點｜北町日式建築宿舍群、南京路廣場、關山鎮、長濱鄉、達仁鄉', `organizer`='臺東縣政府文化處', `address`='無資料', `start_date`='2025-05-01 00:00:00', `end_date`='2025-10-15 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75547, `longitude`=121.14834, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005892', '2025臺東藝術節', '為讓民眾有更多機會接觸欣賞表演藝術，增加臺東藝文人口，推動臺東藝文消費人口的成長為目標，規劃「2025臺東藝術節」活動，帶給民眾優質表演藝術，以售票演出方式建立民眾藝文消費素養，提昇本縣表演藝術產業發展，建立長期優質藝文接軌世界舞臺。第15屆的臺東藝術節策展方向維持多元、老少咸宜、雅俗共賞等原則，邀請戲劇、音樂、舞蹈、親子等不同類型的11檔節目，讓觀眾用親民的票價就能享受優質的劇場體驗。臺東藝術節並秉持文化平權的精神，將配合文化部校外文化體驗計畫、青年席位振興方案，加強與學校單位的合作及連結，安排講座、工作坊、大師班等推廣活動，讓年輕學子及縣民對於表演藝術有更深度的認識，提升美學素養。', '臺東縣政府文化處', '無資料', '2025-05-01 00:00:00', '2025-11-01 23:59:59', '臺東縣臺東市', 22.75547, 121.14834, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺東藝術節', `description`='為讓民眾有更多機會接觸欣賞表演藝術，增加臺東藝文人口，推動臺東藝文消費人口的成長為目標，規劃「2025臺東藝術節」活動，帶給民眾優質表演藝術，以售票演出方式建立民眾藝文消費素養，提昇本縣表演藝術產業發展，建立長期優質藝文接軌世界舞臺。第15屆的臺東藝術節策展方向維持多元、老少咸宜、雅俗共賞等原則，邀請戲劇、音樂、舞蹈、親子等不同類型的11檔節目，讓觀眾用親民的票價就能享受優質的劇場體驗。臺東藝術節並秉持文化平權的精神，將配合文化部校外文化體驗計畫、青年席位振興方案，加強與學校單位的合作及連結，安排講座、工作坊、大師班等推廣活動，讓年輕學子及縣民對於表演藝術有更深度的認識，提升美學素養。', `organizer`='臺東縣政府文化處', `address`='無資料', `start_date`='2025-05-01 00:00:00', `end_date`='2025-11-01 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75547, `longitude`=121.14834, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005893', '2025臺東藝穗節｜記憶、城市與山海紀錄片', '《2025臺東藝穗節-記憶、城市與山海紀錄片》為了讓觀眾更深入了解台東的自然與人文風貌，台東藝穗節將於正式開幕前舉辦前導活動。我們選擇了台東12個具代表性的地點，透過拍攝12支短片和1支60分鐘的長片，介紹這些地點的歷史、文化與故事。這些影片將呈現台東山海景觀與人文歷史，讓觀眾在視覺的旅程中，感受台東的獨特魅力。拍攝完成後，我們將舉辦小型攝影展，展示這些短片和長片，邀請大家一同來探索台東的多元面貌，並為即將到來的台東藝穗節注入更多文化能量與情感連結。活動地點┃臺東縣自然環境場域或歷史建物', '臺東縣政府文化處', '無資料', '2025-05-01 00:00:00', '2025-06-01 23:59:59', '臺東縣臺東市', 22.76248, 121.14286, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺東藝穗節｜記憶、城市與山海紀錄片', `description`='《2025臺東藝穗節-記憶、城市與山海紀錄片》為了讓觀眾更深入了解台東的自然與人文風貌，台東藝穗節將於正式開幕前舉辦前導活動。我們選擇了台東12個具代表性的地點，透過拍攝12支短片和1支60分鐘的長片，介紹這些地點的歷史、文化與故事。這些影片將呈現台東山海景觀與人文歷史，讓觀眾在視覺的旅程中，感受台東的獨特魅力。拍攝完成後，我們將舉辦小型攝影展，展示這些短片和長片，邀請大家一同來探索台東的多元面貌，並為即將到來的台東藝穗節注入更多文化能量與情感連結。活動地點┃臺東縣自然環境場域或歷史建物', `organizer`='臺東縣政府文化處', `address`='無資料', `start_date`='2025-05-01 00:00:00', `end_date`='2025-06-01 23:59:59', `location`='臺東縣臺東市', `latitude`=22.76248, `longitude`=121.14286, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005894', '2025臺東藝穗節', '藝穗節（Fringe Festival），以自由開放的精神，提供藝術家一個能盡情迸發想像力的平台。2020年，臺東縣政府首次舉辦臺東藝穗節，在每年收穫的秋季，以臺東的山海自然與人文地景為舞台，開展系列藝文表演，希望藉不同載體與形式的演出創造對話，道出深刻的在地故事，體會臺東的獨特魅力，讓藝術融於日常。活動地點┃臺東縣自然環境場域或歷史建物徵件開跑！詳細簡章徵件時間：2025/2/10 ~ 3/28「我是誰？我在哪？」你是阿美族、泰雅族、魯凱族，還是東南亞、西方、歐洲的新臺東人？你是來自北部的繁華、西部的沃土、南部的暖陽，還是東部的曙光？你駐足於山巔、鹿野的綠、大武的寧靜，還是海邊的潮聲？在台東這片土地上，你的故事將會如何展開呢？來吧！一起走進 2025臺東藝穗節，尋找「我是誰？我在哪？」的答案！競爭型演出計畫送出演出計畫書，採審查方式給予演出補助，讓你的表演成為答案！自由分享演出計畫不設限，沒有門檻，來臺東，勇敢分享你的表演與故事！工作坊甄選讓民眾參與，透過體驗表演藝術，一起找回初心與熱愛！駐村藝術家甄選沉浸臺東的山海，與當地交融，創作屬於這片土地的故事！', '臺東縣政府文化處', '無資料', '2025-10-01 00:00:00', '2025-11-01 23:59:59', '臺東縣臺東市', 22.75547, 121.14834, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺東藝穗節', `description`='藝穗節（Fringe Festival），以自由開放的精神，提供藝術家一個能盡情迸發想像力的平台。2020年，臺東縣政府首次舉辦臺東藝穗節，在每年收穫的秋季，以臺東的山海自然與人文地景為舞台，開展系列藝文表演，希望藉不同載體與形式的演出創造對話，道出深刻的在地故事，體會臺東的獨特魅力，讓藝術融於日常。活動地點┃臺東縣自然環境場域或歷史建物徵件開跑！詳細簡章徵件時間：2025/2/10 ~ 3/28「我是誰？我在哪？」你是阿美族、泰雅族、魯凱族，還是東南亞、西方、歐洲的新臺東人？你是來自北部的繁華、西部的沃土、南部的暖陽，還是東部的曙光？你駐足於山巔、鹿野的綠、大武的寧靜，還是海邊的潮聲？在台東這片土地上，你的故事將會如何展開呢？來吧！一起走進 2025臺東藝穗節，尋找「我是誰？我在哪？」的答案！競爭型演出計畫送出演出計畫書，採審查方式給予演出補助，讓你的表演成為答案！自由分享演出計畫不設限，沒有門檻，來臺東，勇敢分享你的表演與故事！工作坊甄選讓民眾參與，透過體驗表演藝術，一起找回初心與熱愛！駐村藝術家甄選沉浸臺東的山海，與當地交融，創作屬於這片土地的故事！', `organizer`='臺東縣政府文化處', `address`='無資料', `start_date`='2025-10-01 00:00:00', `end_date`='2025-11-01 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75547, `longitude`=121.14834, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005895', '2025南迴藝術季', '為將臺東打造成一大美術館，經與在地串連而起的藝術推廣，衍生更大的社群擾動、擴大加值效益，希望借用藝術結合在地文化、土地與自然，藉由作品使藝術家、居民與訪客能感性地接觸及深度對話，匯集臺東縣境內所有地景藝術節（東海岸大地藝術季、南迴藝術季、縱谷大地藝術節），用藝術柔和臺東的山與海，呈現出本縣自然與文化藝術的地方獨特性。', '臺東縣政府文化處視覺藝術科', '無資料', '2025-07-01 00:00:00', '2025-10-01 23:59:59', '臺東縣臺東市', 22.70512, 121.0398, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025南迴藝術季', `description`='為將臺東打造成一大美術館，經與在地串連而起的藝術推廣，衍生更大的社群擾動、擴大加值效益，希望借用藝術結合在地文化、土地與自然，藉由作品使藝術家、居民與訪客能感性地接觸及深度對話，匯集臺東縣境內所有地景藝術節（東海岸大地藝術季、南迴藝術季、縱谷大地藝術節），用藝術柔和臺東的山與海，呈現出本縣自然與文化藝術的地方獨特性。', `organizer`='臺東縣政府文化處視覺藝術科', `address`='無資料', `start_date`='2025-07-01 00:00:00', `end_date`='2025-10-01 23:59:59', `location`='臺東縣臺東市', `latitude`=22.70512, `longitude`=121.0398, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005896', '2025臺東聲音藝術節', '臺東聲音藝術節以「跨域演出」、「耳朵帶路工作坊」、「藝術展覽」等多樣主題活動，邀請國內外優質藝文團隊展演，結合臺東的人文與自然資源，開拓民眾參與、社群互動及跨域應用，促進跨文化的交流，創造以五感體驗的臺東大美術館。', '臺東縣政府文化處視覺藝術科', '無資料', '2025-06-19 00:00:00', '2025-12-07 23:59:59', '臺東縣臺東市', 22.7643, 121.14991, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺東聲音藝術節', `description`='臺東聲音藝術節以「跨域演出」、「耳朵帶路工作坊」、「藝術展覽」等多樣主題活動，邀請國內外優質藝文團隊展演，結合臺東的人文與自然資源，開拓民眾參與、社群互動及跨域應用，促進跨文化的交流，創造以五感體驗的臺東大美術館。', `organizer`='臺東縣政府文化處視覺藝術科', `address`='無資料', `start_date`='2025-06-19 00:00:00', `end_date`='2025-12-07 23:59:59', `location`='臺東縣臺東市', `latitude`=22.7643, `longitude`=121.14991, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005897', '2025藝起來我家庭院分享會', '邀請在地表演團隊進入各活動家戶庭院，以音樂或其他表演形式，結合家戶人生故事，共同演繹出小人物的大故事。', '臺東縣政府文化處', '無資料', '2025-05-01 15:30:00', '2025-10-01 17:00:00', '臺東縣臺東市', 22.75547, 121.14834, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025藝起來我家庭院分享會', `description`='邀請在地表演團隊進入各活動家戶庭院，以音樂或其他表演形式，結合家戶人生故事，共同演繹出小人物的大故事。', `organizer`='臺東縣政府文化處', `address`='無資料', `start_date`='2025-05-01 15:30:00', `end_date`='2025-10-01 17:00:00', `location`='臺東縣臺東市', `latitude`=22.75547, `longitude`=121.14834, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
