INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005902', '2025南島影展', '藉由南島相關影片的放映，切入南島的各類議題，帶動民眾對於南島文化的認同與意識。同時搭配座談與工作坊活動，使民眾對於特定討論內容能有更深刻的體悟。', '臺東縣政府文化處', '無資料', '2025-05-01 00:00:00', '2025-07-01 23:59:59', '臺東縣臺東市', 22.76203, 121.14279, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025南島影展', `description`='藉由南島相關影片的放映，切入南島的各類議題，帶動民眾對於南島文化的認同與意識。同時搭配座談與工作坊活動，使民眾對於特定討論內容能有更深刻的體悟。', `organizer`='臺東縣政府文化處', `address`='無資料', `start_date`='2025-05-01 00:00:00', `end_date`='2025-07-01 23:59:59', `location`='臺東縣臺東市', `latitude`=22.76203, `longitude`=121.14279, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005903', '2025臺東跨年晚會', '為打造本縣四季主題活動，營造歲末節慶氛圍，並提供優質團隊及縣外專業團隊表演及交流、觀摩的平臺，讓本縣民眾就近參與。', '臺東縣政府文化處', '無資料', '2025-12-31 19:00:00', '2026-01-01 00:30:00', '臺東縣臺東市', 22.75289, 121.16395, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺東跨年晚會', `description`='為打造本縣四季主題活動，營造歲末節慶氛圍，並提供優質團隊及縣外專業團隊表演及交流、觀摩的平臺，讓本縣民眾就近參與。', `organizer`='臺東縣政府文化處', `address`='無資料', `start_date`='2025-12-31 19:00:00', `end_date`='2026-01-01 00:30:00', `location`='臺東縣臺東市', `latitude`=22.75289, `longitude`=121.16395, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005919', '家與家的距離', '本展覽主要期望探討了原住民傳統手工藝與當代藝術的關係，並深入分析了台灣魯凱族女性的視角與歷史背景如何影響這一創作過程。傳統手工藝，特別是魯凱族女性的編織技術，不僅是日常生活中的實用品，更是文化信仰與族群認同的象徵。這些工藝傳達著對祖靈與自然的尊敬，並反映了魯凱族在歷史上多次遷徙過程中的文化變遷與適應。從台灣近代魯凱族的遷徙歷史來看，這些工藝形式也承載著族群的生存智慧與精神力量，成為傳統文化的持續記憶。總結來看，原住民傳統手工藝與當代藝術之間的關係，既是文化延續與創新的體現，也是現代藝術家對過去記憶的重構與文化再生的過程。傳統手工藝作為文化記憶的承載體，與當代藝術的結合賦予其新的生命與意義，讓原住民文化不僅得以延續，還能在現代語境中發展出更多層次的文化對話與藝術探索。對於魯凱族女性而言，這樣的創作過程不僅是對自我身份的再確認，也是對族群歷史與精神的再生。展覽資訊日期｜114-01-19~114-03-16地點｜臺東美術館山歌、海舞廳', '臺東縣政府', '無資料', '2025-01-19 00:00:00', '2025-03-16 23:59:59', '臺東縣臺東市', 22.7643, 121.14991, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='家與家的距離', `description`='本展覽主要期望探討了原住民傳統手工藝與當代藝術的關係，並深入分析了台灣魯凱族女性的視角與歷史背景如何影響這一創作過程。傳統手工藝，特別是魯凱族女性的編織技術，不僅是日常生活中的實用品，更是文化信仰與族群認同的象徵。這些工藝傳達著對祖靈與自然的尊敬，並反映了魯凱族在歷史上多次遷徙過程中的文化變遷與適應。從台灣近代魯凱族的遷徙歷史來看，這些工藝形式也承載著族群的生存智慧與精神力量，成為傳統文化的持續記憶。總結來看，原住民傳統手工藝與當代藝術之間的關係，既是文化延續與創新的體現，也是現代藝術家對過去記憶的重構與文化再生的過程。傳統手工藝作為文化記憶的承載體，與當代藝術的結合賦予其新的生命與意義，讓原住民文化不僅得以延續，還能在現代語境中發展出更多層次的文化對話與藝術探索。對於魯凱族女性而言，這樣的創作過程不僅是對自我身份的再確認，也是對族群歷史與精神的再生。展覽資訊日期｜114-01-19~114-03-16地點｜臺東美術館山歌、海舞廳', `organizer`='臺東縣政府', `address`='無資料', `start_date`='2025-01-19 00:00:00', `end_date`='2025-03-16 23:59:59', `location`='臺東縣臺東市', `latitude`=22.7643, `longitude`=121.14991, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
