INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005956', '2025倚盃氣 歡喜來唱歌', '長青才藝競賽開放戲劇、舞蹈、合唱等多元表演形式，讓各老人會報名參加。｜時間｜4/22㊁、4/23㊂｜地點｜台東縣立體育館群星演唱會免費索票入場。台東縣籍65歲以上長者，可於4/7㊀-4/18㊄上班時間至社會處一樓服務台、四大社福中心，憑身分證每人限索取2張，長青社團會員可向老人會報名。｜時間｜4/23㊂ 14:00-16:00｜地點｜台東縣立體育館｜陣容｜南方二重唱、許富凱、李千娜、鄭進一、羅時豐', '臺東縣政府社會處', '無資料', '2025-04-22 00:00:00', '2025-04-23 23:59:59', '臺東縣臺東市', 22.75219, 121.14506, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025倚盃氣 歡喜來唱歌', `description`='長青才藝競賽開放戲劇、舞蹈、合唱等多元表演形式，讓各老人會報名參加。｜時間｜4/22㊁、4/23㊂｜地點｜台東縣立體育館群星演唱會免費索票入場。台東縣籍65歲以上長者，可於4/7㊀-4/18㊄上班時間至社會處一樓服務台、四大社福中心，憑身分證每人限索取2張，長青社團會員可向老人會報名。｜時間｜4/23㊂ 14:00-16:00｜地點｜台東縣立體育館｜陣容｜南方二重唱、許富凱、李千娜、鄭進一、羅時豐', `organizer`='臺東縣政府社會處', `address`='無資料', `start_date`='2025-04-22 00:00:00', `end_date`='2025-04-23 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75219, `longitude`=121.14506, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005957', '2025自然醒慢活祭', '⭐️全臺第一個身心靈品牌活動在臺東⭐️療癒工作坊｜淨心慢旅行｜療癒祭｜療癒沙龍｜全國助人者專場｜療癒產業培力晶礦深埋於地，吸收宇宙的靈光。山海圍繞的臺東，蘊藏這純粹的療癒能量。這裡的一切，都是豐盛的象徵。海潮、微風、綠意、靈石，時時刻刻與生命共鳴。在《自然醒慢活祭》的引領中放下塵囂。讓心回歸當下，感受身心靈的和諧流動，迎接生命最純粹的豐盛與喜悅。', '臺東縣政府', '無資料', '2025-04-11 00:00:00', '2025-11-30 23:59:59', '臺東縣臺東市', 22.75547, 121.14834, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025自然醒慢活祭', `description`='⭐️全臺第一個身心靈品牌活動在臺東⭐️療癒工作坊｜淨心慢旅行｜療癒祭｜療癒沙龍｜全國助人者專場｜療癒產業培力晶礦深埋於地，吸收宇宙的靈光。山海圍繞的臺東，蘊藏這純粹的療癒能量。這裡的一切，都是豐盛的象徵。海潮、微風、綠意、靈石，時時刻刻與生命共鳴。在《自然醒慢活祭》的引領中放下塵囂。讓心回歸當下，感受身心靈的和諧流動，迎接生命最純粹的豐盛與喜悅。', `organizer`='臺東縣政府', `address`='無資料', `start_date`='2025-04-11 00:00:00', `end_date`='2025-11-30 23:59:59', `location`='臺東縣臺東市', `latitude`=22.75547, `longitude`=121.14834, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005958', '2025 阿米斯音樂節', '2025 阿米斯音樂節日期：2025 年 11／8 （六）、11／9（日）地點：Pacifaran 都蘭鼻＠台東都蘭部落勇氣是什麼？像是種子發芽時，衝破皮殼、竄出泥土、展露頭苗，那柔軟的身軀，滿載了的是持續生長的勇氣！　每看到那張藍色、桃紅的大旗，想起每一次升起的初衷，想起每一次圍舞織起的人網，每一次你們的笑容...回頭一望，阿米斯音樂節不知不覺走的如此遙遠了...　12 年了，你的熱情是否依然？每一次快要放棄的時候，總會想到那些每一次，每一次都勇敢的決定還要有下一次！而你呢？你這一次要勇敢的牽起身邊的人的手，一起回到這個地方嗎？回到上一次我們一起牽手的地方 - Pacifaran　一起來吧！', '臺東縣政府', '無資料', '2025-11-08 00:00:00', '2025-11-09 23:59:59', '臺東縣東河鄉', 22.87192, 121.22606, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 阿米斯音樂節', `description`='2025 阿米斯音樂節日期：2025 年 11／8 （六）、11／9（日）地點：Pacifaran 都蘭鼻＠台東都蘭部落勇氣是什麼？像是種子發芽時，衝破皮殼、竄出泥土、展露頭苗，那柔軟的身軀，滿載了的是持續生長的勇氣！　每看到那張藍色、桃紅的大旗，想起每一次升起的初衷，想起每一次圍舞織起的人網，每一次你們的笑容...回頭一望，阿米斯音樂節不知不覺走的如此遙遠了...　12 年了，你的熱情是否依然？每一次快要放棄的時候，總會想到那些每一次，每一次都勇敢的決定還要有下一次！而你呢？你這一次要勇敢的牽起身邊的人的手，一起回到這個地方嗎？回到上一次我們一起牽手的地方 - Pacifaran　一起來吧！', `organizer`='臺東縣政府', `address`='無資料', `start_date`='2025-11-08 00:00:00', `end_date`='2025-11-09 23:59:59', `location`='臺東縣東河鄉', `latitude`=22.87192, `longitude`=121.22606, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
