INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_395000000A_006228', '「2025臺灣國際蘭展」蘭展月好康-旅宿業、伴手禮、觀光景點及旅行社聯合優惠大放送', '「2025亞太蘭花會議暨臺灣國際蘭展」於3月8日至3月23日在臺灣蘭花生物科技園區精彩登場，蘭展不僅是臺南溪北地區一年一度的盛事之一，今年更結合「第15屆亞太蘭花會議」盛大展開，每日開放時間為09:00~18:00，歡迎大家來臺南後壁賞花旅遊。觀光旅遊局每年均協助行銷蘭展，調查在地願意共襄盛舉的業者優惠，今年共有75家業者響應「蘭展月好康」提出優惠，業者類別有旅宿業、伴手禮、農會展售中心、觀光工廠、休閒農場等；另外有3家旅宿業者推出蘭展限定住宿專案，及3家旅行社推出套裝優惠行程，讓遊客在臺南能夠玩得更盡興。', '臺南市政府', '無資料', '2025-03-01 00:00:00', '2025-03-31 23:59:59', '臺南市安平區', 22.99166, 120.182808, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「2025臺灣國際蘭展」蘭展月好康-旅宿業、伴手禮、觀光景點及旅行社聯合優惠大放送', `description`='「2025亞太蘭花會議暨臺灣國際蘭展」於3月8日至3月23日在臺灣蘭花生物科技園區精彩登場，蘭展不僅是臺南溪北地區一年一度的盛事之一，今年更結合「第15屆亞太蘭花會議」盛大展開，每日開放時間為09:00~18:00，歡迎大家來臺南後壁賞花旅遊。觀光旅遊局每年均協助行銷蘭展，調查在地願意共襄盛舉的業者優惠，今年共有75家業者響應「蘭展月好康」提出優惠，業者類別有旅宿業、伴手禮、農會展售中心、觀光工廠、休閒農場等；另外有3家旅宿業者推出蘭展限定住宿專案，及3家旅行社推出套裝優惠行程，讓遊客在臺南能夠玩得更盡興。', `organizer`='臺南市政府', `address`='無資料', `start_date`='2025-03-01 00:00:00', `end_date`='2025-03-31 23:59:59', `location`='臺南市安平區', `latitude`=22.99166, `longitude`=120.182808, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
