INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_080678', '2023新北市貢寮海洋音樂祭', '「貢寮海洋音樂祭」起始於民國99年（西元2010年），係爲豐富新北市的海洋文化性格、建立貢寮區地方特質並發展文化觀光以鼓勵本土音樂創作之精神，選定福隆海水浴場這片黃金沙灘，藉由活動行銷新北市126公里海岸線的自然景觀旅遊資源，成功塑造貢寮為臺灣北部海洋搖滾新據點。貢寮國際海洋音樂祭即將進入第20回，所秉持的理念是鼓勵台灣本土音樂的創作，並提供獨立樂團一個專屬且不受限制的舞台，讓所有的樂團可以在這個舞台上以創作表達自我，並能擁有盡情揮灑的空間，也是讓獨立音樂人能有被看見、被欣賞及被肯定的機會。活動表演以樂團接力的方式進行，主要活動內容除了有邀請國內外知名樂團進行演出的主舞台，開放獨立樂團自由報名的小舞台與自第2屆開始舉辦重視音樂原創性及現場表演實力的「海洋獨立音樂大賞」之外，自民國107年（西元2018年）起更設立多元曲風的第三舞台，提供遊客更多元的音樂盛會。', '新北市政府', '福隆里興隆街40號', '2023-09-15 00:00:00', '2023-09-17 00:00:00', '新北市貢寮區', 25.021998, 121.943158, '無資料', 'https://hohaiyan.ntpc.gov.tw/', '["https://www.taiwan.net.tw/att/event/203b5e61-6f91-4423-8694-f45582ff80eb.jpg", "https://www.taiwan.net.tw/att/event/0391b60b-4fff-4fbc-886e-1ecf9f80a161.jpg", "https://www.taiwan.net.tw/att/event/d4a9d5cd-68d2-4049-9719-3ee59ad8cc1e.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023新北市貢寮海洋音樂祭', `description`='「貢寮海洋音樂祭」起始於民國99年（西元2010年），係爲豐富新北市的海洋文化性格、建立貢寮區地方特質並發展文化觀光以鼓勵本土音樂創作之精神，選定福隆海水浴場這片黃金沙灘，藉由活動行銷新北市126公里海岸線的自然景觀旅遊資源，成功塑造貢寮為臺灣北部海洋搖滾新據點。貢寮國際海洋音樂祭即將進入第20回，所秉持的理念是鼓勵台灣本土音樂的創作，並提供獨立樂團一個專屬且不受限制的舞台，讓所有的樂團可以在這個舞台上以創作表達自我，並能擁有盡情揮灑的空間，也是讓獨立音樂人能有被看見、被欣賞及被肯定的機會。活動表演以樂團接力的方式進行，主要活動內容除了有邀請國內外知名樂團進行演出的主舞台，開放獨立樂團自由報名的小舞台與自第2屆開始舉辦重視音樂原創性及現場表演實力的「海洋獨立音樂大賞」之外，自民國107年（西元2018年）起更設立多元曲風的第三舞台，提供遊客更多元的音樂盛會。', `organizer`='新北市政府', `address`='福隆里興隆街40號', `start_date`='2023-09-15 00:00:00', `end_date`='2023-09-17 00:00:00', `location`='新北市貢寮區', `latitude`=25.021998, `longitude`=121.943158, `ticket_price`='無資料', `source_url`='https://hohaiyan.ntpc.gov.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/203b5e61-6f91-4423-8694-f45582ff80eb.jpg", "https://www.taiwan.net.tw/att/event/0391b60b-4fff-4fbc-886e-1ecf9f80a161.jpg", "https://www.taiwan.net.tw/att/event/d4a9d5cd-68d2-4049-9719-3ee59ad8cc1e.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_080856', '2023菊島澎湖跨海馬拉松', '旅跑熱潮開始延燒吹動離島賽事崛起，也將成為馬拉松融入「運動觀光」及「旅跑概念」，醞釀而成為新賽點及新亮點。臺灣本島因可供舉辦馬拉松的場域有限，各縣市路跑賽事的路權取得不容易，許多賽事也多規劃為折返跑路線，唯獨澎湖國家風景區管理處所籌辦之菊島澎湖跨海馬拉松，是堪稱為外島首創的A-B點不折返、跳島、不繞圈的賽道，此賽道已於2018年取得中華民國田徑協會之國際田徑總會「IAAF/AIMS國際賽道認證」，搭配賽道沿線設置之特色美食補給及創意啦啦隊，讓跑友們更能全程以一步一腳印的方式，完整、深入體驗澎湖之美。', '交通部觀光署澎湖國家風景區管理處', '西嶼西臺遊客中心', '2023-11-05 00:00:00', '2023-11-05 00:00:00', '澎湖縣西嶼鄉', 23.565649, 119.489697, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/35317735-fbf8-4d5d-91eb-6c430ad36f8d.jpg", "https://www.taiwan.net.tw/att/event/e0727aa2-ee37-45ee-8548-e1da381cc1d3.jpg", "https://www.taiwan.net.tw/att/event/903655f2-5a33-46cc-a34d-959f20393ad5.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023菊島澎湖跨海馬拉松', `description`='旅跑熱潮開始延燒吹動離島賽事崛起，也將成為馬拉松融入「運動觀光」及「旅跑概念」，醞釀而成為新賽點及新亮點。臺灣本島因可供舉辦馬拉松的場域有限，各縣市路跑賽事的路權取得不容易，許多賽事也多規劃為折返跑路線，唯獨澎湖國家風景區管理處所籌辦之菊島澎湖跨海馬拉松，是堪稱為外島首創的A-B點不折返、跳島、不繞圈的賽道，此賽道已於2018年取得中華民國田徑協會之國際田徑總會「IAAF/AIMS國際賽道認證」，搭配賽道沿線設置之特色美食補給及創意啦啦隊，讓跑友們更能全程以一步一腳印的方式，完整、深入體驗澎湖之美。', `organizer`='交通部觀光署澎湖國家風景區管理處', `address`='西嶼西臺遊客中心', `start_date`='2023-11-05 00:00:00', `end_date`='2023-11-05 00:00:00', `location`='澎湖縣西嶼鄉', `latitude`=23.565649, `longitude`=119.489697, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/35317735-fbf8-4d5d-91eb-6c430ad36f8d.jpg", "https://www.taiwan.net.tw/att/event/e0727aa2-ee37-45ee-8548-e1da381cc1d3.jpg", "https://www.taiwan.net.tw/att/event/903655f2-5a33-46cc-a34d-959f20393ad5.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_080912', '2023台灣燈會', '2024台灣燈會介紹          台灣燈會已然成為臺灣代表性觀光活動，將聚焦台南獨有豐富生態、人文地理、產業發展及多元文化，各項特色意象具象化，建立臺灣觀光品牌慶典。      活動地點：台南     活動日期：2024年2月24日 ～ 3月10日交通部觀光署為能將臺灣觀光旅遊形象推廣到世界，以吸引更多國外旅客來臺旅遊，並提昇旅遊觀光外匯收入，以「民俗文化根、傳統國際化」的理念來辦理台灣燈會。元宵節提燈籠原本是傳統的民俗活動，在融合本土風情及新科技後，台灣燈會更打造出國際級觀光盛會的氣勢，不但主燈展演美不勝收，國內外民俗團體的精采獻藝，以及一波波表演團隊之熱絡表演，使得來臺參加台灣燈會的國外嘉賓及旅客都讚聲連連。民國96年（西元2007年）間美國Discovery節目製作人來臺參訪台灣燈會元宵活動，經該節目評估，台灣燈會已具世界級水準，值得向全世界推薦，因而將其評選為「全球最佳慶典活動」之一，邀請拍攝團隊特地來記錄，並製作了長達1個小時的系列節目於全球播放，向全球推薦台灣燈會的璀璨魅力。「2023台灣燈會」以在地人文、產業導入及永續發展等概念，結合科技與文化元素，打造創新、節能及永續的台灣燈會，以國家大型燈會引領節慶活動時尚潮流。「2023台灣燈會」中央展區位於國父紀念館及市府前廣場，融入創新規劃，結合花燈藝術與現代光影多媒體科技，並擴大藝術家參與的創新運作模式，使燈會成為國內外藝術家或燈藝師展現藝術創作作品的場域，提供遊客與燈會互動的旅遊體驗，短期能提升台灣燈會知名度，長期則創造台灣燈會成為一重要活動平臺，使傳統花燈製作技藝獲得傳承，並融入創意、創新元素，讓傳統與現代交互激盪，豐富民俗傳統節慶文化內涵，開創華人世界獨一無二的元宵特色活動。', '交通部觀光署、臺北市政府', '國立國父紀念館', '2023-02-05 00:00:00', '2023-02-19 00:00:00', '臺北市信義區', 25.04114, 121.560023, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/38312dfe-acc1-4b63-85bc-02c171cbe1a3.jpg", "https://www.taiwan.net.tw/att/event/c8f7bcd8-c9ed-4526-a8bd-1f91185c94b4.jpg", "https://www.taiwan.net.tw/att/event/315253fd-a1b5-4a29-b3ed-03dc52e9029b.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023台灣燈會', `description`='2024台灣燈會介紹          台灣燈會已然成為臺灣代表性觀光活動，將聚焦台南獨有豐富生態、人文地理、產業發展及多元文化，各項特色意象具象化，建立臺灣觀光品牌慶典。      活動地點：台南     活動日期：2024年2月24日 ～ 3月10日交通部觀光署為能將臺灣觀光旅遊形象推廣到世界，以吸引更多國外旅客來臺旅遊，並提昇旅遊觀光外匯收入，以「民俗文化根、傳統國際化」的理念來辦理台灣燈會。元宵節提燈籠原本是傳統的民俗活動，在融合本土風情及新科技後，台灣燈會更打造出國際級觀光盛會的氣勢，不但主燈展演美不勝收，國內外民俗團體的精采獻藝，以及一波波表演團隊之熱絡表演，使得來臺參加台灣燈會的國外嘉賓及旅客都讚聲連連。民國96年（西元2007年）間美國Discovery節目製作人來臺參訪台灣燈會元宵活動，經該節目評估，台灣燈會已具世界級水準，值得向全世界推薦，因而將其評選為「全球最佳慶典活動」之一，邀請拍攝團隊特地來記錄，並製作了長達1個小時的系列節目於全球播放，向全球推薦台灣燈會的璀璨魅力。「2023台灣燈會」以在地人文、產業導入及永續發展等概念，結合科技與文化元素，打造創新、節能及永續的台灣燈會，以國家大型燈會引領節慶活動時尚潮流。「2023台灣燈會」中央展區位於國父紀念館及市府前廣場，融入創新規劃，結合花燈藝術與現代光影多媒體科技，並擴大藝術家參與的創新運作模式，使燈會成為國內外藝術家或燈藝師展現藝術創作作品的場域，提供遊客與燈會互動的旅遊體驗，短期能提升台灣燈會知名度，長期則創造台灣燈會成為一重要活動平臺，使傳統花燈製作技藝獲得傳承，並融入創意、創新元素，讓傳統與現代交互激盪，豐富民俗傳統節慶文化內涵，開創華人世界獨一無二的元宵特色活動。', `organizer`='交通部觀光署、臺北市政府', `address`='國立國父紀念館', `start_date`='2023-02-05 00:00:00', `end_date`='2023-02-19 00:00:00', `location`='臺北市信義區', `latitude`=25.04114, `longitude`=121.560023, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/38312dfe-acc1-4b63-85bc-02c171cbe1a3.jpg", "https://www.taiwan.net.tw/att/event/c8f7bcd8-c9ed-4526-a8bd-1f91185c94b4.jpg", "https://www.taiwan.net.tw/att/event/315253fd-a1b5-4a29-b3ed-03dc52e9029b.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_080915', '2023阿里山日出印象音樂會', '阿里山是國內外知名觀賞日出的旅遊勝地的，「阿里山日出印象音樂會」自民國91年（西元2002年）底由交通部觀光署阿里山國家風景區管理處、農業部林業及自然保育署嘉義林區管理處及嘉義縣政府共同輪流主辦，是臺灣最具特色的高山音樂會，以高海拔、高品質、高格調的「高三」音樂會為活動目標，讓國內外遊客沉浸在悠揚樂曲中，迎接新年第一道曙光的首選活動；活動串聯大阿里山地區周邊旅遊路線，將日出印象主題特色與活動產品深化，提升觀光產值。活動時間：2023年1月1日 05:30~07:30 -->', '嘉義縣政府、交通部觀光署阿里山國家風景區管理處、農業部林業及自然保育署嘉義林區管理處', '阿里山國家森林遊樂區 祝山觀日平臺（停機坪）', '2023-01-01 00:00:00', '2023-01-01 00:00:00', '南投縣信義鄉', 23.510174, 120.823799, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/ef1bff5c-a2cd-468b-a96e-c1032ed89e87.jpg", "https://www.taiwan.net.tw/att/event/4cab25e5-c129-4807-9e68-ac7969df7ee7.jpg", "https://www.taiwan.net.tw/att/event/1f6846f1-8f24-4dae-ad2d-c9b3c425a8ae.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023阿里山日出印象音樂會', `description`='阿里山是國內外知名觀賞日出的旅遊勝地的，「阿里山日出印象音樂會」自民國91年（西元2002年）底由交通部觀光署阿里山國家風景區管理處、農業部林業及自然保育署嘉義林區管理處及嘉義縣政府共同輪流主辦，是臺灣最具特色的高山音樂會，以高海拔、高品質、高格調的「高三」音樂會為活動目標，讓國內外遊客沉浸在悠揚樂曲中，迎接新年第一道曙光的首選活動；活動串聯大阿里山地區周邊旅遊路線，將日出印象主題特色與活動產品深化，提升觀光產值。活動時間：2023年1月1日 05:30~07:30 -->', `organizer`='嘉義縣政府、交通部觀光署阿里山國家風景區管理處、農業部林業及自然保育署嘉義林區管理處', `address`='阿里山國家森林遊樂區 祝山觀日平臺（停機坪）', `start_date`='2023-01-01 00:00:00', `end_date`='2023-01-01 00:00:00', `location`='南投縣信義鄉', `latitude`=23.510174, `longitude`=120.823799, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/ef1bff5c-a2cd-468b-a96e-c1032ed89e87.jpg", "https://www.taiwan.net.tw/att/event/4cab25e5-c129-4807-9e68-ac7969df7ee7.jpg", "https://www.taiwan.net.tw/att/event/1f6846f1-8f24-4dae-ad2d-c9b3c425a8ae.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_080920', '2023月津港燈節', '月津港燈節是臺灣眾多燈會中，唯一獲得德國紅點設計大獎、被譽為全臺最藝術、最有質感的燈節。月津港燈節以「一府、二鹿、三艋舺、四月津」的臺南鹽水月津港作為展覽場域，特色在於藉由整治完成的月津港地景環境，結合地方豐厚文化內涵與創新藝術，邀請國內外藝術團隊以當地湖面、水岸景致來襯托藝術燈飾，營造令人驚豔的獨特燈節意象，更有如孕育新銳藝術家的交流平台。活動期間，每到黃昏，五顏六色的藝術燈飾開啟時，月津港呈現一片璀璨亮麗，有如夜之美術館，照耀在河面上，遊客穿梭於河岸旁，充滿著夢幻浪漫氛圍。藉由燈區結合河面燈光倒影，將河景、地貌、建築製作而成奇幻、詩意、飄渺的空間，參觀人潮屢創新高，「月津港燈節」已形塑其活動品牌與知名度，為臺南市最重要的文化活動之一。', '臺南市政府文化局', '月津港', '2023-01-14 00:00:00', '2023-02-12 00:00:00', '臺南市鹽水區', 23.317061, 120.266785, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/1be5cf25-28ae-4588-8450-e3d0cd75bf11.jpg", "https://www.taiwan.net.tw/att/event/9cffa41a-e821-4dd9-8d4d-49ef3e354443.jpg", "https://www.taiwan.net.tw/att/event/462ee7b2-b61d-4ed5-aeff-465750b61826.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023月津港燈節', `description`='月津港燈節是臺灣眾多燈會中，唯一獲得德國紅點設計大獎、被譽為全臺最藝術、最有質感的燈節。月津港燈節以「一府、二鹿、三艋舺、四月津」的臺南鹽水月津港作為展覽場域，特色在於藉由整治完成的月津港地景環境，結合地方豐厚文化內涵與創新藝術，邀請國內外藝術團隊以當地湖面、水岸景致來襯托藝術燈飾，營造令人驚豔的獨特燈節意象，更有如孕育新銳藝術家的交流平台。活動期間，每到黃昏，五顏六色的藝術燈飾開啟時，月津港呈現一片璀璨亮麗，有如夜之美術館，照耀在河面上，遊客穿梭於河岸旁，充滿著夢幻浪漫氛圍。藉由燈區結合河面燈光倒影，將河景、地貌、建築製作而成奇幻、詩意、飄渺的空間，參觀人潮屢創新高，「月津港燈節」已形塑其活動品牌與知名度，為臺南市最重要的文化活動之一。', `organizer`='臺南市政府文化局', `address`='月津港', `start_date`='2023-01-14 00:00:00', `end_date`='2023-02-12 00:00:00', `location`='臺南市鹽水區', `latitude`=23.317061, `longitude`=120.266785, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/1be5cf25-28ae-4588-8450-e3d0cd75bf11.jpg", "https://www.taiwan.net.tw/att/event/9cffa41a-e821-4dd9-8d4d-49ef3e354443.jpg", "https://www.taiwan.net.tw/att/event/462ee7b2-b61d-4ed5-aeff-465750b61826.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_080970', '2023鷄籠中元祭', '雞籠中元祭起源於西元1855年，從過往地方歷史事件發展至今，為臺灣規模最大的中元祭典，不僅是臺灣歷史最悠久的民俗祭典之一，也是第一個被指定為「重要民俗」類國家文化資產的節慶。由各姓氏宗親會輪流主普，活動內容涵蓋宗教祭儀、傳承研習及周邊藝文活動，以族群融合、慎終追遠、悲天憫人、博愛普施為核心精神。', '基隆市政府', '老大公廟', '2023-08-15 00:00:00', '2023-09-15 00:00:00', '基隆市安樂區', 25.12907, 121.7331, '無資料', 'https://www.klccab.gov.tw/CulturalFestival/Details/0e51aca0-c8db-4221-b01f-0d1745f58a28?itemId=21168f38-4e6d-454f-b89c-1cb99c3e8ee4&firstpage=1&secondPage=1', '["https://www.taiwan.net.tw/att/event/9c23e9f6-2266-4d45-8fde-8de6c624686f.jpg", "https://www.taiwan.net.tw/att/event/3ad0e2ad-e987-43f5-866f-cf82b848ca18.jpg", "https://www.taiwan.net.tw/att/event/894b300c-c3d7-4696-944e-722e2c5a41d9.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023鷄籠中元祭', `description`='雞籠中元祭起源於西元1855年，從過往地方歷史事件發展至今，為臺灣規模最大的中元祭典，不僅是臺灣歷史最悠久的民俗祭典之一，也是第一個被指定為「重要民俗」類國家文化資產的節慶。由各姓氏宗親會輪流主普，活動內容涵蓋宗教祭儀、傳承研習及周邊藝文活動，以族群融合、慎終追遠、悲天憫人、博愛普施為核心精神。', `organizer`='基隆市政府', `address`='老大公廟', `start_date`='2023-08-15 00:00:00', `end_date`='2023-09-15 00:00:00', `location`='基隆市安樂區', `latitude`=25.12907, `longitude`=121.7331, `ticket_price`='無資料', `source_url`='https://www.klccab.gov.tw/CulturalFestival/Details/0e51aca0-c8db-4221-b01f-0d1745f58a28?itemId=21168f38-4e6d-454f-b89c-1cb99c3e8ee4&firstpage=1&secondPage=1', `image_url`='["https://www.taiwan.net.tw/att/event/9c23e9f6-2266-4d45-8fde-8de6c624686f.jpg", "https://www.taiwan.net.tw/att/event/3ad0e2ad-e987-43f5-866f-cf82b848ca18.jpg", "https://www.taiwan.net.tw/att/event/894b300c-c3d7-4696-944e-722e2c5a41d9.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_080971', '2023雙年賞蝶', '茂林國家風景區位於高屏山區，長久以「紫蝶幽谷」特殊景象聞名國內外，亦為綠色米其林指南推薦三星生態景點。「雙年賞蝶」是每年11月開始至隔年3月在茂林國家風景區的重頭戲，此時，會有成千上萬的紫斑蝶遠渡重洋，來到此地棲息。茂林國家風景區最引以為傲的就是擁有世界上僅有的二大規模越冬蝶谷之一。紫斑蝶為罕見越冬型蝴蝶，每年冬季時，上百萬隻紫斑蝶便會集中遷往大武山麓的山谷躲避寒冬，形成壯觀的「紫蝶幽谷」生態現象。全球各地的遊客到茂林體驗世界級紫斑蝶環繞飛舞的壯觀場景，都給予本活動廣大好評與回響。', '交通部觀光署茂林國家風景區管理處、高雄市政府、高雄市茂林區公所', '茂林生態公園', '2023-11-04 00:00:00', '2024-02-29 00:00:00', '高雄市茂林區', 22.887377, 120.663144, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/faced32e-2f8e-46e5-8ffd-40c55a199b04.jpg", "https://www.taiwan.net.tw/att/event/3d608bb3-27e4-4d4b-a720-94c6f4d826ee.jpg", "https://www.taiwan.net.tw/att/event/c4b2a673-8e8b-4b2f-a3eb-85f99262ae94.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023雙年賞蝶', `description`='茂林國家風景區位於高屏山區，長久以「紫蝶幽谷」特殊景象聞名國內外，亦為綠色米其林指南推薦三星生態景點。「雙年賞蝶」是每年11月開始至隔年3月在茂林國家風景區的重頭戲，此時，會有成千上萬的紫斑蝶遠渡重洋，來到此地棲息。茂林國家風景區最引以為傲的就是擁有世界上僅有的二大規模越冬蝶谷之一。紫斑蝶為罕見越冬型蝴蝶，每年冬季時，上百萬隻紫斑蝶便會集中遷往大武山麓的山谷躲避寒冬，形成壯觀的「紫蝶幽谷」生態現象。全球各地的遊客到茂林體驗世界級紫斑蝶環繞飛舞的壯觀場景，都給予本活動廣大好評與回響。', `organizer`='交通部觀光署茂林國家風景區管理處、高雄市政府、高雄市茂林區公所', `address`='茂林生態公園', `start_date`='2023-11-04 00:00:00', `end_date`='2024-02-29 00:00:00', `location`='高雄市茂林區', `latitude`=22.887377, `longitude`=120.663144, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/faced32e-2f8e-46e5-8ffd-40c55a199b04.jpg", "https://www.taiwan.net.tw/att/event/3d608bb3-27e4-4d4b-a720-94c6f4d826ee.jpg", "https://www.taiwan.net.tw/att/event/c4b2a673-8e8b-4b2f-a3eb-85f99262ae94.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081008', '2023東海岸大地藝術節暨月光・海音樂會', '東海岸大地藝術節（TECLandArt Festival）是交通部觀光署東部海岸國家風景管理處於2015年開始委託專業承辦，沿著台灣東海岸各地舉辦的藝術活動，內容包括邀請藝術家駐地創作大型戶外作品，並設置在東海岸沿途風景區，稱之為「駐地創作營」。除此之外，還有沿著台11線公路開放藝術工作室、藝術市集、音樂會等，是一個以東部海岸線區域的自然環境、部落生活、棲息居住、旅行壯遊為主題的藝術節。東部海岸壯闊自然，有時優美有時狂野，有時神秘有時開放，生活在其中的人們，寂靜而自然，樸素而自由，本藝術節透過駐地創作、藝術品設置、藝術活動、完善的旅行設施，讓觀光者在公共場所中找到情境涉入與幸福感之關係，繼而產生夢想的在地生根。', '交通部觀光署東部海岸國家風景區管理處', '東部海岸國家風景區管理處轄區', '2023-06-21 00:00:00', '2023-09-02 00:00:00', '臺東縣成功鎮', 23.019844, 121.324258, '無資料', 'https://www.teclandart.tw/zh/home/', '["https://www.taiwan.net.tw/att/event/7691d826-23d1-496b-97f9-88462b50efa8.jpg", "https://www.taiwan.net.tw/att/event/81923f7d-c26c-4ee6-ae10-ad3a3cb7d8f5.jpg", "https://www.taiwan.net.tw/att/event/621141e2-7802-4b00-885c-aec3fdbbb9eb.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023東海岸大地藝術節暨月光・海音樂會', `description`='東海岸大地藝術節（TECLandArt Festival）是交通部觀光署東部海岸國家風景管理處於2015年開始委託專業承辦，沿著台灣東海岸各地舉辦的藝術活動，內容包括邀請藝術家駐地創作大型戶外作品，並設置在東海岸沿途風景區，稱之為「駐地創作營」。除此之外，還有沿著台11線公路開放藝術工作室、藝術市集、音樂會等，是一個以東部海岸線區域的自然環境、部落生活、棲息居住、旅行壯遊為主題的藝術節。東部海岸壯闊自然，有時優美有時狂野，有時神秘有時開放，生活在其中的人們，寂靜而自然，樸素而自由，本藝術節透過駐地創作、藝術品設置、藝術活動、完善的旅行設施，讓觀光者在公共場所中找到情境涉入與幸福感之關係，繼而產生夢想的在地生根。', `organizer`='交通部觀光署東部海岸國家風景區管理處', `address`='東部海岸國家風景區管理處轄區', `start_date`='2023-06-21 00:00:00', `end_date`='2023-09-02 00:00:00', `location`='臺東縣成功鎮', `latitude`=23.019844, `longitude`=121.324258, `ticket_price`='無資料', `source_url`='https://www.teclandart.tw/zh/home/', `image_url`='["https://www.taiwan.net.tw/att/event/7691d826-23d1-496b-97f9-88462b50efa8.jpg", "https://www.taiwan.net.tw/att/event/81923f7d-c26c-4ee6-ae10-ad3a3cb7d8f5.jpg", "https://www.taiwan.net.tw/att/event/621141e2-7802-4b00-885c-aec3fdbbb9eb.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081009', '2023基隆潮境海灣節', '望海巷潮境海灣，範圍自環保復育公園海岬至深澳岬之海域，面積約250公頃，海灣山海景觀秀麗、生態資源豐富，具有獨特海岸地質風貌與潮間帶，每年春末至秋初時節氣候溫和宜人，相當適合各類戶外休憩活動與教育體驗。希望透過海灣節辦理各項活動，以觸發觀眾「親近海洋、認識海洋、善用海洋、善待海洋、永續海洋」，打造海灣及週邊場域變成「海洋生態體驗園區」。民國104年（西元2015年）至民國106年（西元2017年）由國立海洋科技博物館辦理三屆「Aquatopia 渥托邦-海洋狂想」海洋生活博覽會系列活動，每年吸引上萬人次參加，大受好評，已成為成北臺灣年度盛事。民國107年（西元2018年）起，由基隆市政府接繼辦理相關海灣體驗活動，延續渥托邦活動的熱潮，並與本市產、關、學、研相關單位合作，如基隆區漁會、八斗子漁村、長潭漁村、特定漁業產銷班、海科館及交通部北觀處等，擴大服務對象及新增多項親海及體驗行程，針對不同族群與海洋產生關連的方式做為切入點，推出五大「潮」活動，包括「潮海洋」、「潮音樂」「潮美食」、「潮生態」與「潮漁村」，舉凡海灣可發展之海洋運動、生態旅遊、海洋工作假期、漁村活絡、海底影像記錄、海洋音樂、海洋美食等，讓不同族群與海洋交集而留下了美好生命經驗，將透過這樣的機制，規劃寓教於樂的海洋體驗活動，吸引大眾走進基隆的海洋場域，感受海洋生活之豐富。', '基隆市政府', '碧砂漁港', '2023-07-22 00:00:00', '2023-07-22 00:00:00', '基隆市中正區', 25.147141, 121.78629, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/9cb4d0df-2b40-452b-bb44-0118d778adda.jpg", "https://www.taiwan.net.tw/att/event/20596994-0743-4822-8721-f10135cb940f.jpg", "https://www.taiwan.net.tw/att/event/2121fcc8-020b-4b72-9fa8-d57727ebf8cc.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023基隆潮境海灣節', `description`='望海巷潮境海灣，範圍自環保復育公園海岬至深澳岬之海域，面積約250公頃，海灣山海景觀秀麗、生態資源豐富，具有獨特海岸地質風貌與潮間帶，每年春末至秋初時節氣候溫和宜人，相當適合各類戶外休憩活動與教育體驗。希望透過海灣節辦理各項活動，以觸發觀眾「親近海洋、認識海洋、善用海洋、善待海洋、永續海洋」，打造海灣及週邊場域變成「海洋生態體驗園區」。民國104年（西元2015年）至民國106年（西元2017年）由國立海洋科技博物館辦理三屆「Aquatopia 渥托邦-海洋狂想」海洋生活博覽會系列活動，每年吸引上萬人次參加，大受好評，已成為成北臺灣年度盛事。民國107年（西元2018年）起，由基隆市政府接繼辦理相關海灣體驗活動，延續渥托邦活動的熱潮，並與本市產、關、學、研相關單位合作，如基隆區漁會、八斗子漁村、長潭漁村、特定漁業產銷班、海科館及交通部北觀處等，擴大服務對象及新增多項親海及體驗行程，針對不同族群與海洋產生關連的方式做為切入點，推出五大「潮」活動，包括「潮海洋」、「潮音樂」「潮美食」、「潮生態」與「潮漁村」，舉凡海灣可發展之海洋運動、生態旅遊、海洋工作假期、漁村活絡、海底影像記錄、海洋音樂、海洋美食等，讓不同族群與海洋交集而留下了美好生命經驗，將透過這樣的機制，規劃寓教於樂的海洋體驗活動，吸引大眾走進基隆的海洋場域，感受海洋生活之豐富。', `organizer`='基隆市政府', `address`='碧砂漁港', `start_date`='2023-07-22 00:00:00', `end_date`='2023-07-22 00:00:00', `location`='基隆市中正區', `latitude`=25.147141, `longitude`=121.78629, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/9cb4d0df-2b40-452b-bb44-0118d778adda.jpg", "https://www.taiwan.net.tw/att/event/20596994-0743-4822-8721-f10135cb940f.jpg", "https://www.taiwan.net.tw/att/event/2121fcc8-020b-4b72-9fa8-d57727ebf8cc.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081010', '2023基隆潮藝術', '「潮藝術」視在地居民的智慧及生活為藝術，也讓藝術成為問題性，一場與自然共生的大地藝術祭在裝點港口的同時也在呼喊著文化的認同。海風的鹹味提醒著我們並非身處美術館，而是遊走在現實生活與藝術的邊緣，探討著漁港特有的文化、歷史、知識、產物與情感，將其微分化並轉譯為方便閱覽的章節。「潮藝術」不只是個展覽，而是扭動了場域、時間、故事而後建構的如同港口的載體，承載著當地住民的記憶、來訪民眾的所見以及藝術家的想像。「潮藝術」自民國104年（西元2015年）至今將邁入第7年，從潮境公園拓張至舊正濱漁會大樓、阿根納造船場遺構，並打造了極具特色的海上美術館，透過循序漸進的主題，從海洋關懷出發，不斷鼓勵及激發民眾思考基隆與海洋、藝術與環境的關係，透過藝術重新喚起在地認同，民國109年（西元2020年）展覽首周即吸引千人進港，帶動當地觀光。', '基隆市政府文化局', '正濱漁港', '2023-09-28 00:00:00', '2023-10-15 00:00:00', '基隆市中正區', 25.151951, 121.766055, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/1dd3bbeb-9d40-480b-a093-aa77c21c0ee1.jpg", "https://www.taiwan.net.tw/att/event/dc0ec6a6-9db3-44a0-8244-177775f48bd0.jpg", "https://www.taiwan.net.tw/att/event/63f35690-52c8-4827-8a63-7abd8756ef2c.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023基隆潮藝術', `description`='「潮藝術」視在地居民的智慧及生活為藝術，也讓藝術成為問題性，一場與自然共生的大地藝術祭在裝點港口的同時也在呼喊著文化的認同。海風的鹹味提醒著我們並非身處美術館，而是遊走在現實生活與藝術的邊緣，探討著漁港特有的文化、歷史、知識、產物與情感，將其微分化並轉譯為方便閱覽的章節。「潮藝術」不只是個展覽，而是扭動了場域、時間、故事而後建構的如同港口的載體，承載著當地住民的記憶、來訪民眾的所見以及藝術家的想像。「潮藝術」自民國104年（西元2015年）至今將邁入第7年，從潮境公園拓張至舊正濱漁會大樓、阿根納造船場遺構，並打造了極具特色的海上美術館，透過循序漸進的主題，從海洋關懷出發，不斷鼓勵及激發民眾思考基隆與海洋、藝術與環境的關係，透過藝術重新喚起在地認同，民國109年（西元2020年）展覽首周即吸引千人進港，帶動當地觀光。', `organizer`='基隆市政府文化局', `address`='正濱漁港', `start_date`='2023-09-28 00:00:00', `end_date`='2023-10-15 00:00:00', `location`='基隆市中正區', `latitude`=25.151951, `longitude`=121.766055, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/1dd3bbeb-9d40-480b-a093-aa77c21c0ee1.jpg", "https://www.taiwan.net.tw/att/event/dc0ec6a6-9db3-44a0-8244-177775f48bd0.jpg", "https://www.taiwan.net.tw/att/event/63f35690-52c8-4827-8a63-7abd8756ef2c.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081011', '2023竹子湖海芋季及繡球花季', '竹子湖海拔670公尺，位居大屯山、七星山與小觀音山間的谷地。曾是火山堰塞湖，湖水退去後留下肥沃的土壤，形成典型的農村聚落，近年結合在地花卉等產業與自然、人文資源發展休閒農業，成為臺北市第三個休閒農業區。「竹子湖」自民國58年（西元1969年）從日本引進白色海芋，每一株花的花期大約是8~10天，竹子湖受陽明山國家公園管制範圍的保護，擁有豐沛潔淨的山泉水源，經多年的努力推廣，目前竹子湖白色海芋年產量占全臺海芋產量百分之80~90，每年3~5月盛開時的浪漫氣氛，加上陽明山的自然風光，都吸引國內外眾多遊客前往竹子湖海芋田賞海芋、採海芋，品嚐在地美食佳餚。竹子湖海芋季迄今已辦理19年，同時思考多元發展，自民國101年（西元2012年）開始推動繡球花產業，民國106年（西元2017年）起辦理繡球花推廣活動，民國109年（西元2020年）首度將竹子湖海芋季與繡球花季串聯舉辦。活動以海芋季及繡球花季為主軸，辦理開幕式、花藝設計展、採海芋花體驗、假日免費生態人文導覽解說、平日付費生態農園體驗及花田有約等活動，近5年海芋季及繡球花季期間參與人次平均達50萬以上。', '臺北市政府產業發展局', '竹子湖路1之20號', '2023-03-14 00:00:00', '2023-06-18 00:00:00', '臺北市北投區', 25.175495, 121.536788, '無資料', 'https://flowersfestival.taipei/flower.php?id=12', '["https://www.taiwan.net.tw/att/event/38a0d7b6-432c-458a-9b29-f278fe7728ef.jpg", "https://www.taiwan.net.tw/att/event/e1f3ff98-ce95-43a3-a5dc-86f300cdbf36.jpg", "https://www.taiwan.net.tw/att/event/fd7ff22c-ab16-48dc-ba7e-2890a31edff6.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023竹子湖海芋季及繡球花季', `description`='竹子湖海拔670公尺，位居大屯山、七星山與小觀音山間的谷地。曾是火山堰塞湖，湖水退去後留下肥沃的土壤，形成典型的農村聚落，近年結合在地花卉等產業與自然、人文資源發展休閒農業，成為臺北市第三個休閒農業區。「竹子湖」自民國58年（西元1969年）從日本引進白色海芋，每一株花的花期大約是8~10天，竹子湖受陽明山國家公園管制範圍的保護，擁有豐沛潔淨的山泉水源，經多年的努力推廣，目前竹子湖白色海芋年產量占全臺海芋產量百分之80~90，每年3~5月盛開時的浪漫氣氛，加上陽明山的自然風光，都吸引國內外眾多遊客前往竹子湖海芋田賞海芋、採海芋，品嚐在地美食佳餚。竹子湖海芋季迄今已辦理19年，同時思考多元發展，自民國101年（西元2012年）開始推動繡球花產業，民國106年（西元2017年）起辦理繡球花推廣活動，民國109年（西元2020年）首度將竹子湖海芋季與繡球花季串聯舉辦。活動以海芋季及繡球花季為主軸，辦理開幕式、花藝設計展、採海芋花體驗、假日免費生態人文導覽解說、平日付費生態農園體驗及花田有約等活動，近5年海芋季及繡球花季期間參與人次平均達50萬以上。', `organizer`='臺北市政府產業發展局', `address`='竹子湖路1之20號', `start_date`='2023-03-14 00:00:00', `end_date`='2023-06-18 00:00:00', `location`='臺北市北投區', `latitude`=25.175495, `longitude`=121.536788, `ticket_price`='無資料', `source_url`='https://flowersfestival.taipei/flower.php?id=12', `image_url`='["https://www.taiwan.net.tw/att/event/38a0d7b6-432c-458a-9b29-f278fe7728ef.jpg", "https://www.taiwan.net.tw/att/event/e1f3ff98-ce95-43a3-a5dc-86f300cdbf36.jpg", "https://www.taiwan.net.tw/att/event/fd7ff22c-ab16-48dc-ba7e-2890a31edff6.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081013', '2023新北萬里蟹', '本市每年訂於9月辦理萬里蟹產季起跑記者會，除宣告萬里蟹產季正式到來，並預告10月至12月即將舉辦的一系列萬里蟹季產地活動，如淡水肥蟹宴、富基品蟹宴、野柳假日活蟹市集、龜吼漁夫市集萬里蟹促銷活動等，以萬里蟹之名串連新北特色漁港，系列活動最高潮為10月於野柳漁港盛大舉行的萬里蟹主場活動，讓民眾來到產地品嚐鱻蟹宴，現場其他民眾還可以參加搭乘娛樂漁船體驗捕蟹人生、走訪野柳咾咕厝、瑪鋉居及保安宮等漁村風情導覽以及海洋獨木舟等漁業體驗活動，藉由系列活動讓民眾就近到漁港體驗休閒漁業活動，進而以行動支持在地漁業的永續發展。', '新北市政府', '野柳漁港', '2023-10-21 00:00:00', '2023-10-22 00:00:00', '新北市萬里區', 25.205871, 121.687063, '無資料', 'https://wanlicrab.tw/index.php', '["https://www.taiwan.net.tw/att/event/82645274-2cf9-4d1a-846f-44bd14c43137.jpg", "https://www.taiwan.net.tw/att/event/fb6711c9-76e4-41af-b472-1d8037ac0606.jpg", "https://www.taiwan.net.tw/att/event/28950565-0ab6-4f44-abda-e006efac4257.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023新北萬里蟹', `description`='本市每年訂於9月辦理萬里蟹產季起跑記者會，除宣告萬里蟹產季正式到來，並預告10月至12月即將舉辦的一系列萬里蟹季產地活動，如淡水肥蟹宴、富基品蟹宴、野柳假日活蟹市集、龜吼漁夫市集萬里蟹促銷活動等，以萬里蟹之名串連新北特色漁港，系列活動最高潮為10月於野柳漁港盛大舉行的萬里蟹主場活動，讓民眾來到產地品嚐鱻蟹宴，現場其他民眾還可以參加搭乘娛樂漁船體驗捕蟹人生、走訪野柳咾咕厝、瑪鋉居及保安宮等漁村風情導覽以及海洋獨木舟等漁業體驗活動，藉由系列活動讓民眾就近到漁港體驗休閒漁業活動，進而以行動支持在地漁業的永續發展。', `organizer`='新北市政府', `address`='野柳漁港', `start_date`='2023-10-21 00:00:00', `end_date`='2023-10-22 00:00:00', `location`='新北市萬里區', `latitude`=25.205871, `longitude`=121.687063, `ticket_price`='無資料', `source_url`='https://wanlicrab.tw/index.php', `image_url`='["https://www.taiwan.net.tw/att/event/82645274-2cf9-4d1a-846f-44bd14c43137.jpg", "https://www.taiwan.net.tw/att/event/fb6711c9-76e4-41af-b472-1d8037ac0606.jpg", "https://www.taiwan.net.tw/att/event/28950565-0ab6-4f44-abda-e006efac4257.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081014', '2023桃園地景藝術節', '每年移動的藝術節地景藝術節與歐洲文化首都(ECC)的移動策略概念相近，藉由「移動」的特性，喚起地方意識。地景藝術節每年擇定不同展區，藉由藝術節翻轉空間、提升公共建設、擾動社區社群，重新認識桃園每一處地方，也藉由市府及民間資源的投入，讓各區域再次被大家認識。無圍牆美術館每年超過30件作品在大地上，桃園地景藝術節以三大主軸－「地方覺醒」、「社區風動」、「藝術打樁」，以及四大價值─「社區參與」、「在地特色」、「環境永續」、「循環經濟」，打造在地化品牌象徵。以桃園的自然景觀及人文資產為基礎，透過豐富多元的藝術展演及活動規劃，結合社區參與和民眾互動，讓藝術更貼近環境與常民生活，也讓大家以嶄新角度重新發現土地和環境，重新看到在地生態保存、人文景觀及歷史足跡。愈在地，愈國際除了邀請國內外藝術家進駐創作，另規劃國際論壇借鏡亞洲、歐洲的經驗，探討地景藝術節的多元論述，也邀請日本友好城市來參與交流活動並經驗分享，且每年的國際表演團隊因地制宜，表演融入在地地景，總能帶給民眾新的感官體驗。深度觀光桃園地景藝術節創辦於民國102年（西元2013年），每年9月辦理，搭配中秋節連假前後共3週，本屆因疫情影響，展延至隔年3月辦理。延伸無圍牆美術館的意趣，串連裝置藝術、生態，以深度體驗規劃，探訪展區及周邊自然景觀及地方人文，並串連在地社區、觀光景點及觀光工廠，每年吸引約150萬人次參與。', '桃園市政府文化局', '龍潭展區', '2023-08-04 00:00:00', '2023-10-15 00:00:00', '桃園市龍潭區', 24.861704, 121.210048, '無資料', 'https://www.taoyuanlandart.com.tw/', '["https://www.taiwan.net.tw/att/event/472a57c0-ecf7-4b08-bcb8-a2e5c0411598.jpg", "https://www.taiwan.net.tw/att/event/e852e870-a205-4adf-9c66-800831b370f3.jpg", "https://www.taiwan.net.tw/att/event/7780e00f-6f5a-4717-b2a1-718ef91944ec.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023桃園地景藝術節', `description`='每年移動的藝術節地景藝術節與歐洲文化首都(ECC)的移動策略概念相近，藉由「移動」的特性，喚起地方意識。地景藝術節每年擇定不同展區，藉由藝術節翻轉空間、提升公共建設、擾動社區社群，重新認識桃園每一處地方，也藉由市府及民間資源的投入，讓各區域再次被大家認識。無圍牆美術館每年超過30件作品在大地上，桃園地景藝術節以三大主軸－「地方覺醒」、「社區風動」、「藝術打樁」，以及四大價值─「社區參與」、「在地特色」、「環境永續」、「循環經濟」，打造在地化品牌象徵。以桃園的自然景觀及人文資產為基礎，透過豐富多元的藝術展演及活動規劃，結合社區參與和民眾互動，讓藝術更貼近環境與常民生活，也讓大家以嶄新角度重新發現土地和環境，重新看到在地生態保存、人文景觀及歷史足跡。愈在地，愈國際除了邀請國內外藝術家進駐創作，另規劃國際論壇借鏡亞洲、歐洲的經驗，探討地景藝術節的多元論述，也邀請日本友好城市來參與交流活動並經驗分享，且每年的國際表演團隊因地制宜，表演融入在地地景，總能帶給民眾新的感官體驗。深度觀光桃園地景藝術節創辦於民國102年（西元2013年），每年9月辦理，搭配中秋節連假前後共3週，本屆因疫情影響，展延至隔年3月辦理。延伸無圍牆美術館的意趣，串連裝置藝術、生態，以深度體驗規劃，探訪展區及周邊自然景觀及地方人文，並串連在地社區、觀光景點及觀光工廠，每年吸引約150萬人次參與。', `organizer`='桃園市政府文化局', `address`='龍潭展區', `start_date`='2023-08-04 00:00:00', `end_date`='2023-10-15 00:00:00', `location`='桃園市龍潭區', `latitude`=24.861704, `longitude`=121.210048, `ticket_price`='無資料', `source_url`='https://www.taoyuanlandart.com.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/472a57c0-ecf7-4b08-bcb8-a2e5c0411598.jpg", "https://www.taiwan.net.tw/att/event/e852e870-a205-4adf-9c66-800831b370f3.jpg", "https://www.taiwan.net.tw/att/event/7780e00f-6f5a-4717-b2a1-718ef91944ec.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081016', '2023龍岡米干節', '全國獨特文化櫥窗-異域金三角桃園龍岡地區，早年為國民政府撤退自滇緬泰的異域孤軍聚居，居民們帶著家鄉文化、美食來到龍岡落地生根，龍岡一帶更擁有全臺難得的少數民族文化，如景頗、傣、傈僳族等。為讓民眾對異域金三角文化有更深認識，桃園市政府自民國100年（西元2011年）以在地美食「米干」為主軸說故事，開辦第一屆「龍岡米干節」，透過活動展示異域金三角文化表演藝術、美食佳餚。異國家常到在地美食-龍岡米干米干原為雲南一帶家常料理，是孤軍們的家鄉記憶，隨著來臺落地生根，米干也融入了臺灣味，更是全國米干餐廳的擂台，100%純米製作，米干湯頭可比日式拉麵匠人的用心，經過10年龍岡米干節活動推廣，「龍岡」，「米干」二字已相生相存，龍岡成為米干的故鄉。從生活走入旅行-龍岡小旅行龍岡米干節是活動品牌，也是在地商圈品牌，在地商家也因應活動推出特色旅遊體驗，民國109年（西元2020年）龍岡米干節首次提出「忠貞商圈廚藝小旅行」，帶領遊客走進龍岡在地的日常，活動期間帶領遊客走進龍岡忠貞市場採買異國食材，並由在地的住民教導遊客製作金三角特色料理如緬甸茶葉飯，透過活動輔導讓實質的旅遊產品因應而生。', '桃園市政府觀光旅遊局', '龍岡大操場', '2023-04-22 00:00:00', '2023-05-01 00:00:00', '桃園市中壢區', 24.929561, 121.238088, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/2aefe993-7039-4a2e-a4fc-d1f46a4a6014.jpg", "https://www.taiwan.net.tw/att/event/1ab8d884-26dc-408e-b37c-bde6086c72f7.jpg", "https://www.taiwan.net.tw/att/event/bd110203-4939-48cd-8aa0-8f32fe6af56d.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023龍岡米干節', `description`='全國獨特文化櫥窗-異域金三角桃園龍岡地區，早年為國民政府撤退自滇緬泰的異域孤軍聚居，居民們帶著家鄉文化、美食來到龍岡落地生根，龍岡一帶更擁有全臺難得的少數民族文化，如景頗、傣、傈僳族等。為讓民眾對異域金三角文化有更深認識，桃園市政府自民國100年（西元2011年）以在地美食「米干」為主軸說故事，開辦第一屆「龍岡米干節」，透過活動展示異域金三角文化表演藝術、美食佳餚。異國家常到在地美食-龍岡米干米干原為雲南一帶家常料理，是孤軍們的家鄉記憶，隨著來臺落地生根，米干也融入了臺灣味，更是全國米干餐廳的擂台，100%純米製作，米干湯頭可比日式拉麵匠人的用心，經過10年龍岡米干節活動推廣，「龍岡」，「米干」二字已相生相存，龍岡成為米干的故鄉。從生活走入旅行-龍岡小旅行龍岡米干節是活動品牌，也是在地商圈品牌，在地商家也因應活動推出特色旅遊體驗，民國109年（西元2020年）龍岡米干節首次提出「忠貞商圈廚藝小旅行」，帶領遊客走進龍岡在地的日常，活動期間帶領遊客走進龍岡忠貞市場採買異國食材，並由在地的住民教導遊客製作金三角特色料理如緬甸茶葉飯，透過活動輔導讓實質的旅遊產品因應而生。', `organizer`='桃園市政府觀光旅遊局', `address`='龍岡大操場', `start_date`='2023-04-22 00:00:00', `end_date`='2023-05-01 00:00:00', `location`='桃園市中壢區', `latitude`=24.929561, `longitude`=121.238088, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/2aefe993-7039-4a2e-a4fc-d1f46a4a6014.jpg", "https://www.taiwan.net.tw/att/event/1ab8d884-26dc-408e-b37c-bde6086c72f7.jpg", "https://www.taiwan.net.tw/att/event/bd110203-4939-48cd-8aa0-8f32fe6af56d.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081017', '2023桃園彩色海芋季', '為推廣桃園溪海的彩色海芋，讓彩色海芋與地方品牌連結更強烈，延伸「海洋奇芋記」主題，打造桃園大園限定的大片彩色海芋花海，搭配海洋生物戀愛互動的大型花毯裝置，帶領民眾一起與溪海浪漫相芋。民國110年（西元2021年）桃園彩色海芋季以彩色海芋花語的意涵設計7組藝術裝置，以花卉展現海洋生物求愛的浪漫互動；除了藝術意象的裝置設計外，也規劃了一連串以彩芋 X 溪海 X 海洋為主題的創意亮點活動。 -->另整合周邊農場設計集章活動，吸引民眾於活動期間也能進到周邊農場進行消費與觀光、參與活動、認識地方；並與功學社單車合作，規劃彩色海芋單車路線，以牌面引導民眾騎乘自行車前往會場，將綠色生活美學導入遊客心中。', '桃園市政府農業局', '聖德北路與田溪路交叉口', '2023-04-01 00:00:00', '2023-04-16 00:00:00', '桃園市大園區', 25.032867, 121.195473, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/497faaee-5b75-487d-bc60-447bf8a2e9df.jpg", "https://www.taiwan.net.tw/att/event/3d59b815-20f4-41d8-a965-79bda6b62613.jpg", "https://www.taiwan.net.tw/att/event/dff6976b-a0b7-47a3-a964-f51f8ba1b1c3.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023桃園彩色海芋季', `description`='為推廣桃園溪海的彩色海芋，讓彩色海芋與地方品牌連結更強烈，延伸「海洋奇芋記」主題，打造桃園大園限定的大片彩色海芋花海，搭配海洋生物戀愛互動的大型花毯裝置，帶領民眾一起與溪海浪漫相芋。民國110年（西元2021年）桃園彩色海芋季以彩色海芋花語的意涵設計7組藝術裝置，以花卉展現海洋生物求愛的浪漫互動；除了藝術意象的裝置設計外，也規劃了一連串以彩芋 X 溪海 X 海洋為主題的創意亮點活動。 -->另整合周邊農場設計集章活動，吸引民眾於活動期間也能進到周邊農場進行消費與觀光、參與活動、認識地方；並與功學社單車合作，規劃彩色海芋單車路線，以牌面引導民眾騎乘自行車前往會場，將綠色生活美學導入遊客心中。', `organizer`='桃園市政府農業局', `address`='聖德北路與田溪路交叉口', `start_date`='2023-04-01 00:00:00', `end_date`='2023-04-16 00:00:00', `location`='桃園市大園區', `latitude`=25.032867, `longitude`=121.195473, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/497faaee-5b75-487d-bc60-447bf8a2e9df.jpg", "https://www.taiwan.net.tw/att/event/3d59b815-20f4-41d8-a965-79bda6b62613.jpg", "https://www.taiwan.net.tw/att/event/dff6976b-a0b7-47a3-a964-f51f8ba1b1c3.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081018', '2023義魄千秋-全國義民祭在新竹縣', '新埔褒忠亭（義民廟）是北臺灣客家人的信仰中心，也是新竹縣的縣定古蹟，創建至今已超過230年。褒忠亭義民祭典的十五聯庄輪值的歷史至少可以追溯至西元1835年，迄今亦超過180年，是客家族群第一項榮獲文化部指定的國家重要民俗，也由客委會列為「客庄12大節慶」之一。新埔褒忠亭兼具「有形」與「無形」兩項文化資產身份，不但是客家文化傳承的重要資產，也是我國文化豐富多元與多樣化的具體展現。義民祭之所以受到客家鄉親甚至全國的關注，主要是傳承220餘年來的文化祭典，係由新竹縣、市、桃園市等3縣市、20鄉鎮市區組成15大聯庄祭典區輪值主辦，維持嚴謹的經營管理制度，不斷投入民間資源，完整保存傳統輪值制度與祭儀，充分展現了民間自發力量與社群凝聚力。今日，新竹縣褒忠亭的分香廟宇遍佈全臺，義民信仰地位屹立不搖。', '新竹縣政府、財團法人台灣省新竹縣褒忠亭、新埔聯庄輪值祭典區', '新埔枋寮義民廟', '2023-08-24 00:00:00', '2023-09-04 00:00:00', '新竹縣新埔鎮', 24.844249, 121.03639, '無資料', 'https://www.hchcc.gov.tw/Tw/News/ActDetail?filter=e2ce565c-7042-466e-9b77-bb81937b8cf9&id=0e9e66fb-b0aa-42ea-a4b1-0841e0aad4df', '["https://www.taiwan.net.tw/att/event/c9d5d232-3288-4504-9764-cdf97ffc8a2c.jpg", "https://www.taiwan.net.tw/att/event/7fba3082-f0c7-4003-ba35-3375646e9a3f.jpg", "https://www.taiwan.net.tw/att/event/e8cad7bf-42e3-44df-8a19-710948b417a9.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023義魄千秋-全國義民祭在新竹縣', `description`='新埔褒忠亭（義民廟）是北臺灣客家人的信仰中心，也是新竹縣的縣定古蹟，創建至今已超過230年。褒忠亭義民祭典的十五聯庄輪值的歷史至少可以追溯至西元1835年，迄今亦超過180年，是客家族群第一項榮獲文化部指定的國家重要民俗，也由客委會列為「客庄12大節慶」之一。新埔褒忠亭兼具「有形」與「無形」兩項文化資產身份，不但是客家文化傳承的重要資產，也是我國文化豐富多元與多樣化的具體展現。義民祭之所以受到客家鄉親甚至全國的關注，主要是傳承220餘年來的文化祭典，係由新竹縣、市、桃園市等3縣市、20鄉鎮市區組成15大聯庄祭典區輪值主辦，維持嚴謹的經營管理制度，不斷投入民間資源，完整保存傳統輪值制度與祭儀，充分展現了民間自發力量與社群凝聚力。今日，新竹縣褒忠亭的分香廟宇遍佈全臺，義民信仰地位屹立不搖。', `organizer`='新竹縣政府、財團法人台灣省新竹縣褒忠亭、新埔聯庄輪值祭典區', `address`='新埔枋寮義民廟', `start_date`='2023-08-24 00:00:00', `end_date`='2023-09-04 00:00:00', `location`='新竹縣新埔鎮', `latitude`=24.844249, `longitude`=121.03639, `ticket_price`='無資料', `source_url`='https://www.hchcc.gov.tw/Tw/News/ActDetail?filter=e2ce565c-7042-466e-9b77-bb81937b8cf9&id=0e9e66fb-b0aa-42ea-a4b1-0841e0aad4df', `image_url`='["https://www.taiwan.net.tw/att/event/c9d5d232-3288-4504-9764-cdf97ffc8a2c.jpg", "https://www.taiwan.net.tw/att/event/7fba3082-f0c7-4003-ba35-3375646e9a3f.jpg", "https://www.taiwan.net.tw/att/event/e8cad7bf-42e3-44df-8a19-710948b417a9.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081019', '2023新竹縣客家迎天穿系列活動', '新埔花燈歷史最古，也最具特色及代表性，過去新埔迎花燈分街頭、街尾，以火炬、大鼓陣、燈籠、麒麟、獅、象、錦閣，加上花燈詩句、行動劇、化妝踩街，相互讚賞或諷刺，來反映當時社會型態與風土民情，而花燈詩句全用客語，實為客家文學之珍寶。新埔花燈遊行可考於昭和時期，並於民國99年（西元2010年）風華重現，讓新埔居民重新感受「花燈的故鄉」之情懷，凝聚新埔居民的向心力，尋回新埔傳統價值。新竹縣客家迎天穿系列活動串聯新埔傳統價值及縣內各鄉鎮市，打造具創新特色的「客家日」觀光活動，並於活動規劃中向下紮根，教育並傳承客家精神，期能揭開傳統手藝花燈製作的神秘面紗，同時打響「北天燈、南烽炮、會移動的花燈在新埔」名號，歷年的表演節目除兼顧客家傳統文化大戲及歌曲，同時規劃國際性表演團體如日本夜來祭 HONIYA YOSAKOI、重慶市銅梁火龍，讓趣味十足的新埔花燈及新竹縣迎天穿活動能夠遠近馳名。', '新竹縣政府', '新埔鎮', '2023-02-01 00:00:00', '2023-02-12 00:00:00', '新竹縣新埔鎮', 24.827113, 121.075688, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/227de2fb-ee7e-4e63-a4db-562a1e73ba11.jpg", "https://www.taiwan.net.tw/att/event/6265c154-b530-4943-8185-1e7d08bc4eb3.jpg", "https://www.taiwan.net.tw/att/event/30ee3eba-9fb2-4fbc-882d-67dd9d84a8ea.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023新竹縣客家迎天穿系列活動', `description`='新埔花燈歷史最古，也最具特色及代表性，過去新埔迎花燈分街頭、街尾，以火炬、大鼓陣、燈籠、麒麟、獅、象、錦閣，加上花燈詩句、行動劇、化妝踩街，相互讚賞或諷刺，來反映當時社會型態與風土民情，而花燈詩句全用客語，實為客家文學之珍寶。新埔花燈遊行可考於昭和時期，並於民國99年（西元2010年）風華重現，讓新埔居民重新感受「花燈的故鄉」之情懷，凝聚新埔居民的向心力，尋回新埔傳統價值。新竹縣客家迎天穿系列活動串聯新埔傳統價值及縣內各鄉鎮市，打造具創新特色的「客家日」觀光活動，並於活動規劃中向下紮根，教育並傳承客家精神，期能揭開傳統手藝花燈製作的神秘面紗，同時打響「北天燈、南烽炮、會移動的花燈在新埔」名號，歷年的表演節目除兼顧客家傳統文化大戲及歌曲，同時規劃國際性表演團體如日本夜來祭 HONIYA YOSAKOI、重慶市銅梁火龍，讓趣味十足的新埔花燈及新竹縣迎天穿活動能夠遠近馳名。', `organizer`='新竹縣政府', `address`='新埔鎮', `start_date`='2023-02-01 00:00:00', `end_date`='2023-02-12 00:00:00', `location`='新竹縣新埔鎮', `latitude`=24.827113, `longitude`=121.075688, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/227de2fb-ee7e-4e63-a4db-562a1e73ba11.jpg", "https://www.taiwan.net.tw/att/event/6265c154-b530-4943-8185-1e7d08bc4eb3.jpg", "https://www.taiwan.net.tw/att/event/30ee3eba-9fb2-4fbc-882d-67dd9d84a8ea.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081020', '2023苗栗龍系列活動', '「火旁」是客家話「炸」的意思，「火旁龍」就是在神龍舞動時燃放鞭炮，讓神龍在炮陣中騰躍的情境就像行雲駕霧般，越火旁越旺。「苗栗火旁龍」是苗栗地區最熱鬧有趣的元宵節慶活動，早期是從迎龍慶典演變而來的，分為糊龍、牽龍、祥龍點睛、迎龍、火旁龍、跈龍以及化龍返天等七部曲。苗栗火旁龍自民國88年（西元1999年）開始辦理迄今，明年即將邁入第24週年，火旁龍科儀結合了農耕文化的信仰和客家民俗工藝之美，歷經數十載社會轉型的過程，文化傳承和價值觀的轉變，因此我們在每年活動內容力求兼顧到傳統與創新，除了前述的七部曲架構活動內容以外，在民國110年（西元2021年）度首次客製化企製專屬苗栗限定節目「火旁龍映象-定幕劇」，結合聲光、影像，彙整一齣以龍為主角的劇碼，讓龍隊表演除了在街頭巷弄迎龍拜年外，也能登上劇院形式的藝術表演殿堂。另外同年首次大規模的舞龍廟埕巡演，則是承襲民間習俗典故而來，採跨鄉、鎮、市共同行銷之方式舉辦，因爲我們堅信唯有強構文化底蘊，才能流傳久遠。活動日程    112年1月27日-1月28日 祥龍巡庄    地點：頭份市、卓蘭鎮、獅潭鄉、三灣鄉    112年1月29日-2月7日 客家龍神壇    地點：苗栗火車站西站    112年1月30日 09:00-12:30 祥龍點睛、貓裏客家龍競技、神龍陣祈福    地點：苗栗市玉清宮    112年2月3日 18:00-22:00 民俗踩街    地點：苗栗市南苗三角公園至火車站東站廣場    112年2月4日 17:00-21:30 龍之夜    地點：苗栗市經國路河濱公園    112年2月7日 21:00-24:00 化龍返天    地點：苗栗市嘉盛五文昌廟', '苗栗市公所', '苗栗火車站西站廣場', '2023-01-27 00:00:00', '2023-02-07 00:00:00', '苗栗縣苗栗市', 24.57002, 120.822343, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/e647c64d-6530-46f9-9643-8fa15064b42a.jpg", "https://www.taiwan.net.tw/att/event/948d8f78-644f-4866-a7e1-3439e6174fd0.jpg", "https://www.taiwan.net.tw/att/event/cff88de4-6c9f-4acf-beda-e1144c7375c5.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023苗栗龍系列活動', `description`='「火旁」是客家話「炸」的意思，「火旁龍」就是在神龍舞動時燃放鞭炮，讓神龍在炮陣中騰躍的情境就像行雲駕霧般，越火旁越旺。「苗栗火旁龍」是苗栗地區最熱鬧有趣的元宵節慶活動，早期是從迎龍慶典演變而來的，分為糊龍、牽龍、祥龍點睛、迎龍、火旁龍、跈龍以及化龍返天等七部曲。苗栗火旁龍自民國88年（西元1999年）開始辦理迄今，明年即將邁入第24週年，火旁龍科儀結合了農耕文化的信仰和客家民俗工藝之美，歷經數十載社會轉型的過程，文化傳承和價值觀的轉變，因此我們在每年活動內容力求兼顧到傳統與創新，除了前述的七部曲架構活動內容以外，在民國110年（西元2021年）度首次客製化企製專屬苗栗限定節目「火旁龍映象-定幕劇」，結合聲光、影像，彙整一齣以龍為主角的劇碼，讓龍隊表演除了在街頭巷弄迎龍拜年外，也能登上劇院形式的藝術表演殿堂。另外同年首次大規模的舞龍廟埕巡演，則是承襲民間習俗典故而來，採跨鄉、鎮、市共同行銷之方式舉辦，因爲我們堅信唯有強構文化底蘊，才能流傳久遠。活動日程    112年1月27日-1月28日 祥龍巡庄    地點：頭份市、卓蘭鎮、獅潭鄉、三灣鄉    112年1月29日-2月7日 客家龍神壇    地點：苗栗火車站西站    112年1月30日 09:00-12:30 祥龍點睛、貓裏客家龍競技、神龍陣祈福    地點：苗栗市玉清宮    112年2月3日 18:00-22:00 民俗踩街    地點：苗栗市南苗三角公園至火車站東站廣場    112年2月4日 17:00-21:30 龍之夜    地點：苗栗市經國路河濱公園    112年2月7日 21:00-24:00 化龍返天    地點：苗栗市嘉盛五文昌廟', `organizer`='苗栗市公所', `address`='苗栗火車站西站廣場', `start_date`='2023-01-27 00:00:00', `end_date`='2023-02-07 00:00:00', `location`='苗栗縣苗栗市', `latitude`=24.57002, `longitude`=120.822343, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/e647c64d-6530-46f9-9643-8fa15064b42a.jpg", "https://www.taiwan.net.tw/att/event/948d8f78-644f-4866-a7e1-3439e6174fd0.jpg", "https://www.taiwan.net.tw/att/event/cff88de4-6c9f-4acf-beda-e1144c7375c5.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081021', '2023三義木雕藝術節系列活動', '2022三義木雕藝術節系列活動，強調木雕藝術傳承的使命感。除了木藝慢活嘉年華現場活動以動態藝表演、木雕表演、木藝體驗、文創市集、慢城旅遊、茶席等系列活動，營造親子、互動、熱鬧氛圍，塑造三義慢城獨特木雕藝術文化形象「木雕」為三義最具代表性的傳統文化特色，木雕藝術發展蓬勃，透過木雕技藝與形式的延續，讓經典成為永恆。透過節慶活動營造城市品牌意象，融合傳統工藝文化、表演藝術展出，表現地方獨特風采，同時串聯在地社區成為三義居民共同的生活記憶，形塑三義最具國際化與代表性的藝術文化。', '苗栗縣政府文化觀光局', '廣盛村廣聲新城88號', '2023-10-07 00:00:00', '2023-10-10 00:00:00', '苗栗縣三義鄉', 24.405943, 120.760973, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/5ef042c5-3d29-467c-9733-a0dff37ba7a1.jpg", "https://www.taiwan.net.tw/att/event/8960cd22-e378-47cc-a05b-22e5889afe0b.jpg", "https://www.taiwan.net.tw/att/event/0cdc98d9-a422-4375-9b60-070fb2017db6.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023三義木雕藝術節系列活動', `description`='2022三義木雕藝術節系列活動，強調木雕藝術傳承的使命感。除了木藝慢活嘉年華現場活動以動態藝表演、木雕表演、木藝體驗、文創市集、慢城旅遊、茶席等系列活動，營造親子、互動、熱鬧氛圍，塑造三義慢城獨特木雕藝術文化形象「木雕」為三義最具代表性的傳統文化特色，木雕藝術發展蓬勃，透過木雕技藝與形式的延續，讓經典成為永恆。透過節慶活動營造城市品牌意象，融合傳統工藝文化、表演藝術展出，表現地方獨特風采，同時串聯在地社區成為三義居民共同的生活記憶，形塑三義最具國際化與代表性的藝術文化。', `organizer`='苗栗縣政府文化觀光局', `address`='廣盛村廣聲新城88號', `start_date`='2023-10-07 00:00:00', `end_date`='2023-10-10 00:00:00', `location`='苗栗縣三義鄉', `latitude`=24.405943, `longitude`=120.760973, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/5ef042c5-3d29-467c-9733-a0dff37ba7a1.jpg", "https://www.taiwan.net.tw/att/event/8960cd22-e378-47cc-a05b-22e5889afe0b.jpg", "https://www.taiwan.net.tw/att/event/0cdc98d9-a422-4375-9b60-070fb2017db6.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081022', '2023苗栗通霄白沙屯拱天宮媽祖民俗文化系列活動', '苗栗縣通霄鎮拱天宮「白沙屯媽祖進香」活動為本縣一年一度民俗盛事，具有百年以上歷史，不僅歷史悠久、規模盛大，每年均有來自全國各地居民熱情參與徒步到北港朝天宮進香，全程近400公里，縱跨中部4縣市，因其進香日期與路程皆由媽祖神轎指引進行，無法事先預估且為全台路線最遠的徒步進香民俗活動，因其深具傳統性及特殊性，於民國97年登錄為本縣無形文化資產，更於民國99年（西元2010年）獲文化部指定為國家重要民俗祭儀，也在民國102年（西元2013年）被選為內政部「台灣宗教百景」之一。    放頭旗    農曆1月19日 子時    國曆2月8日（星期三）23點40分    登轎    農曆1月22日 子時    國曆2月12日（星期日）0點45分    出發    農曆1月22日 丑時    國曆2月12日（星期日）2點15分    到北港    農曆1月27日    國曆2月17日（星期五）約中午11點前後抵達北港北辰派出所    進火    農曆1月28日 子時    國曆2月17日（星期五）23點40分    回宮    農曆2月1日 申時    國曆2月20日（星期一）16點00分    開爐    農曆2月12日 子時    國曆3月3日（星期三）0點25分', '苗栗縣政府、苗栗縣政府文化觀光局、苗栗縣通霄鎮公所', '白東里8號', '2023-02-08 00:00:00', '2023-03-03 00:00:00', '苗栗縣通霄鎮', 24.571372, 120.709294, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/8d71a1f4-cbe9-4e77-ac23-c7146b5d4c31.jpg", "https://www.taiwan.net.tw/att/event/368b3474-8000-4f8a-9abc-1a2e8d692fd1.jpg", "https://www.taiwan.net.tw/att/event/68176028-ef06-43c4-a38a-532f3de1468d.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023苗栗通霄白沙屯拱天宮媽祖民俗文化系列活動', `description`='苗栗縣通霄鎮拱天宮「白沙屯媽祖進香」活動為本縣一年一度民俗盛事，具有百年以上歷史，不僅歷史悠久、規模盛大，每年均有來自全國各地居民熱情參與徒步到北港朝天宮進香，全程近400公里，縱跨中部4縣市，因其進香日期與路程皆由媽祖神轎指引進行，無法事先預估且為全台路線最遠的徒步進香民俗活動，因其深具傳統性及特殊性，於民國97年登錄為本縣無形文化資產，更於民國99年（西元2010年）獲文化部指定為國家重要民俗祭儀，也在民國102年（西元2013年）被選為內政部「台灣宗教百景」之一。    放頭旗    農曆1月19日 子時    國曆2月8日（星期三）23點40分    登轎    農曆1月22日 子時    國曆2月12日（星期日）0點45分    出發    農曆1月22日 丑時    國曆2月12日（星期日）2點15分    到北港    農曆1月27日    國曆2月17日（星期五）約中午11點前後抵達北港北辰派出所    進火    農曆1月28日 子時    國曆2月17日（星期五）23點40分    回宮    農曆2月1日 申時    國曆2月20日（星期一）16點00分    開爐    農曆2月12日 子時    國曆3月3日（星期三）0點25分', `organizer`='苗栗縣政府、苗栗縣政府文化觀光局、苗栗縣通霄鎮公所', `address`='白東里8號', `start_date`='2023-02-08 00:00:00', `end_date`='2023-03-03 00:00:00', `location`='苗栗縣通霄鎮', `latitude`=24.571372, `longitude`=120.709294, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/8d71a1f4-cbe9-4e77-ac23-c7146b5d4c31.jpg", "https://www.taiwan.net.tw/att/event/368b3474-8000-4f8a-9abc-1a2e8d692fd1.jpg", "https://www.taiwan.net.tw/att/event/68176028-ef06-43c4-a38a-532f3de1468d.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081023', '2023臺中國際踩舞嘉年華', '「臺中國際踩舞嘉年華」藉由舞蹈表演之推廣，結合節慶活動，建立運動觀光與藝術文化交流平臺，促進臺灣本土文化藝術人士與海外各國多元藝術表演團體交流合作，把臺中城市公園化為戶外舞台，創造話題亮點並打造獨特觀光特色意象，凸顯舞蹈嘉年華成為臺中的觀光盛會品牌活動。', '臺中市政府觀光旅遊局', '臺中市民廣場', '2023-09-29 00:00:00', '2023-10-01 00:00:00', '臺中市西區', 24.150027, 120.663469, '無資料', 'https://travel.taichung.gov.tw/zh-tw/event/activitydetail/8225', '["https://www.taiwan.net.tw/att/event/3abd48bd-0ee7-429e-b9f6-68bc3043f95d.jpg", "https://www.taiwan.net.tw/att/event/93e948fa-03ee-4c77-93ef-46010620cfa1.jpg", "https://www.taiwan.net.tw/att/event/6f3c929c-1f13-4c8e-b48b-cc78112b58e4.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023臺中國際踩舞嘉年華', `description`='「臺中國際踩舞嘉年華」藉由舞蹈表演之推廣，結合節慶活動，建立運動觀光與藝術文化交流平臺，促進臺灣本土文化藝術人士與海外各國多元藝術表演團體交流合作，把臺中城市公園化為戶外舞台，創造話題亮點並打造獨特觀光特色意象，凸顯舞蹈嘉年華成為臺中的觀光盛會品牌活動。', `organizer`='臺中市政府觀光旅遊局', `address`='臺中市民廣場', `start_date`='2023-09-29 00:00:00', `end_date`='2023-10-01 00:00:00', `location`='臺中市西區', `latitude`=24.150027, `longitude`=120.663469, `ticket_price`='無資料', `source_url`='https://travel.taichung.gov.tw/zh-tw/event/activitydetail/8225', `image_url`='["https://www.taiwan.net.tw/att/event/3abd48bd-0ee7-429e-b9f6-68bc3043f95d.jpg", "https://www.taiwan.net.tw/att/event/93e948fa-03ee-4c77-93ef-46010620cfa1.jpg", "https://www.taiwan.net.tw/att/event/6f3c929c-1f13-4c8e-b48b-cc78112b58e4.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081024', '2023臺中爵士音樂節', '臺中爵士音樂節，以自由即興的風格展現多元的音樂型式，呼應臺中市輕鬆、悠閒的都會生活文化特色，不但為臺中市營造令人印象深刻的文化生活氛圍，吸引民眾參與戶外藝術休閒活動，更帶動週邊商業與休閒旅遊產業的發展，透過逐年累積交流成果及活動效益，使本項活動逐漸成為臺中市最具吸引力的國際文化節慶活動，並成為和東京、曼谷、首爾等城市並列的亞洲四大爵士音樂節之一。', '臺中市政府文化局', '臺中市市民廣場', '2023-10-13 00:00:00', '2023-10-22 00:00:00', '臺中市西區', 24.15, 120.6635, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/247cedbb-96b9-4cf6-86a4-2b9bad852f53.jpg", "https://www.taiwan.net.tw/att/event/b68d261c-aa66-4034-9e84-f33f2f684147.jpg", "https://www.taiwan.net.tw/att/event/c5735ae6-fbdf-4f0c-95e1-c8a0b0d68bf1.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023臺中爵士音樂節', `description`='臺中爵士音樂節，以自由即興的風格展現多元的音樂型式，呼應臺中市輕鬆、悠閒的都會生活文化特色，不但為臺中市營造令人印象深刻的文化生活氛圍，吸引民眾參與戶外藝術休閒活動，更帶動週邊商業與休閒旅遊產業的發展，透過逐年累積交流成果及活動效益，使本項活動逐漸成為臺中市最具吸引力的國際文化節慶活動，並成為和東京、曼谷、首爾等城市並列的亞洲四大爵士音樂節之一。', `organizer`='臺中市政府文化局', `address`='臺中市市民廣場', `start_date`='2023-10-13 00:00:00', `end_date`='2023-10-22 00:00:00', `location`='臺中市西區', `latitude`=24.15, `longitude`=120.6635, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/247cedbb-96b9-4cf6-86a4-2b9bad852f53.jpg", "https://www.taiwan.net.tw/att/event/b68d261c-aa66-4034-9e84-f33f2f684147.jpg", "https://www.taiwan.net.tw/att/event/c5735ae6-fbdf-4f0c-95e1-c8a0b0d68bf1.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081025', '2023鹿港慶端陽系列活動', '「鹿港慶端陽系列活動」，以行銷鹿港古蹟、人文、工藝、文化、美食等在地特色為主軸，為臺灣觀光年曆國際級的節慶活動之一，中臺灣端午節最重要的觀光活動，自從鹿港陸續榮獲「微笑之鄉」、「臺灣十大觀光小城」、「臺灣經典小鎮」等殊榮後，「鹿港慶端陽系列活動」更是聲名大噪、國際聞名。中臺灣只有鹿港舉辦國際龍舟錦標賽，透過國內外選手組隊參與龍舟競賽，凝聚團隊向心力，已經成為國內外遊客及彰化縣鄉親年年期待的端午嘉年華節慶；鹿港以文化、體育和觀光來進行城市交流，以龍舟賽、鹿港民俗節慶活動、鹿港小鎮光影藝術等方式來歡渡端午佳節，展現鹿港的傳承與活力，遊客們能盡情徜徉文化古蹟之美，遊憩市集美食之旅，感受鹿港小鎮的熱情魅力。', '彰化縣政府、鹿港鎮公所、福興鄉公所', '福鹿溪龍舟會場', '2023-05-01 00:00:00', '2023-06-25 00:00:00', '彰化縣福興鄉', 24.04838, 120.42925, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/c6b3d8f7-4787-4e8d-8e29-92ff9e46451e.jpg", "https://www.taiwan.net.tw/att/event/e20ba147-4ecd-474e-852f-5fc8364adf24.jpg", "https://www.taiwan.net.tw/att/event/7d5294ba-57c0-4dc0-b192-0a4131803f10.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023鹿港慶端陽系列活動', `description`='「鹿港慶端陽系列活動」，以行銷鹿港古蹟、人文、工藝、文化、美食等在地特色為主軸，為臺灣觀光年曆國際級的節慶活動之一，中臺灣端午節最重要的觀光活動，自從鹿港陸續榮獲「微笑之鄉」、「臺灣十大觀光小城」、「臺灣經典小鎮」等殊榮後，「鹿港慶端陽系列活動」更是聲名大噪、國際聞名。中臺灣只有鹿港舉辦國際龍舟錦標賽，透過國內外選手組隊參與龍舟競賽，凝聚團隊向心力，已經成為國內外遊客及彰化縣鄉親年年期待的端午嘉年華節慶；鹿港以文化、體育和觀光來進行城市交流，以龍舟賽、鹿港民俗節慶活動、鹿港小鎮光影藝術等方式來歡渡端午佳節，展現鹿港的傳承與活力，遊客們能盡情徜徉文化古蹟之美，遊憩市集美食之旅，感受鹿港小鎮的熱情魅力。', `organizer`='彰化縣政府、鹿港鎮公所、福興鄉公所', `address`='福鹿溪龍舟會場', `start_date`='2023-05-01 00:00:00', `end_date`='2023-06-25 00:00:00', `location`='彰化縣福興鄉', `latitude`=24.04838, `longitude`=120.42925, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/c6b3d8f7-4787-4e8d-8e29-92ff9e46451e.jpg", "https://www.taiwan.net.tw/att/event/e20ba147-4ecd-474e-852f-5fc8364adf24.jpg", "https://www.taiwan.net.tw/att/event/7d5294ba-57c0-4dc0-b192-0a4131803f10.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081026', '2023二水國際跑水節', '「二水跑水節」為全國特有的水圳節慶活動，西元1719年彰化縣因八堡圳開鑿完成，得以引濁水溪水潤養彰化平原，而使彰化縣開發成為農業大縣。為敬天謝地及感懷先人德澤，在這個深具歷史文化意涵的「八堡圳」舉辦跑引水活動，傳揚歷經十年開鑿八堡圳的辛勞，展現不輕易放棄的毅力，是「台灣精神」最有力的表現，其意義也在推崇「飲水思源」、「食果子拜樹頭」的美德。每年11月進入秋收冬藏之際，在八堡圳舉辦一系列祈福活動，結合二水文化、跑水體驗、山海線農特產品、國際城鄉交流等，注入更多文化觀光元素，並行銷二水鄉的觀光特色，活化農村經濟，結合運動休閒及農特產，為活動注入文化創意活水，更讓二水國際跑水節提昇國際能見度。', '彰化縣政府文化局', '彰化縣二水國民小學', '2023-11-04 00:00:00', '2023-11-05 00:00:00', '彰化縣二水鄉', 23.810849, 120.617816, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/108ff595-151d-4a59-a821-2e722dba0381.jpg", "https://www.taiwan.net.tw/att/event/8723e1d5-b37d-47bc-808d-fbadeb004265.jpg", "https://www.taiwan.net.tw/att/event/246178e5-4912-4c72-8b94-88291815128b.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023二水國際跑水節', `description`='「二水跑水節」為全國特有的水圳節慶活動，西元1719年彰化縣因八堡圳開鑿完成，得以引濁水溪水潤養彰化平原，而使彰化縣開發成為農業大縣。為敬天謝地及感懷先人德澤，在這個深具歷史文化意涵的「八堡圳」舉辦跑引水活動，傳揚歷經十年開鑿八堡圳的辛勞，展現不輕易放棄的毅力，是「台灣精神」最有力的表現，其意義也在推崇「飲水思源」、「食果子拜樹頭」的美德。每年11月進入秋收冬藏之際，在八堡圳舉辦一系列祈福活動，結合二水文化、跑水體驗、山海線農特產品、國際城鄉交流等，注入更多文化觀光元素，並行銷二水鄉的觀光特色，活化農村經濟，結合運動休閒及農特產，為活動注入文化創意活水，更讓二水國際跑水節提昇國際能見度。', `organizer`='彰化縣政府文化局', `address`='彰化縣二水國民小學', `start_date`='2023-11-04 00:00:00', `end_date`='2023-11-05 00:00:00', `location`='彰化縣二水鄉', `latitude`=23.810849, `longitude`=120.617816, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/108ff595-151d-4a59-a821-2e722dba0381.jpg", "https://www.taiwan.net.tw/att/event/8723e1d5-b37d-47bc-808d-fbadeb004265.jpg", "https://www.taiwan.net.tw/att/event/246178e5-4912-4c72-8b94-88291815128b.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081027', '2023北港燈會', '北港人在媽祖的搖籃中孕育成長，歷年元宵盛典朝天宮迎媽祖更猶如北港人的第二次過年，民國54年（西元1965年）在北港朝天宮舉辦了第一屆元宵節花燈展，更帶動全國燈會熱潮，每年以北港鎮為立基，整體鄉鎮區域為主體進行規畫及活動辦理。', '雲林縣政府', '北港朝天宮', '2023-02-03 00:00:00', '2023-03-12 00:00:00', '雲林縣北港鎮', 23.567805, 120.304644, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/7817ce6a-e6d1-47ce-9b44-c9655aad20df.jpg", "https://www.taiwan.net.tw/att/event/a2194102-5618-404b-bf73-b088f0d26d07.jpg", "https://www.taiwan.net.tw/att/event/5cfb26fd-00b8-40b9-bd22-c4965696b818.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023北港燈會', `description`='北港人在媽祖的搖籃中孕育成長，歷年元宵盛典朝天宮迎媽祖更猶如北港人的第二次過年，民國54年（西元1965年）在北港朝天宮舉辦了第一屆元宵節花燈展，更帶動全國燈會熱潮，每年以北港鎮為立基，整體鄉鎮區域為主體進行規畫及活動辦理。', `organizer`='雲林縣政府', `address`='北港朝天宮', `start_date`='2023-02-03 00:00:00', `end_date`='2023-03-12 00:00:00', `location`='雲林縣北港鎮', `latitude`=23.567805, `longitude`=120.304644, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/7817ce6a-e6d1-47ce-9b44-c9655aad20df.jpg", "https://www.taiwan.net.tw/att/event/a2194102-5618-404b-bf73-b088f0d26d07.jpg", "https://www.taiwan.net.tw/att/event/5cfb26fd-00b8-40b9-bd22-c4965696b818.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081029', '高山茶都-嘉義博茶會', '嘉義的茶文化產業豐富且興盛，阿里山茶葉更是為國內外所盛讚的經典茗茶，與茶產業共生共長的還有深厚的茶文化涵養，結合嘉義縣精緻工藝與豐美農特產，讓遊客滿載而歸。嘉義縣除了傑出的茶文化產業引人入勝外，本活動亦結合本縣豐饒的農特產品、得天獨厚的優美景觀、珍貴精緻的工藝品，多元且全面的展現嘉義縣的優質條件，吸引各地旅客再三來訪。', '嘉義縣政府', '中埔鄉農會金蘭分部', '2023-12-09 00:00:00', '2023-12-17 00:00:00', '嘉義縣中埔鄉', 23.447025, 120.492779, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/808fece1-124d-4511-af44-3031a8d0d75a.jpg", "https://www.taiwan.net.tw/att/event/c581ea05-da98-4225-8d2f-0d8719fe43db.jpg", "https://www.taiwan.net.tw/att/event/b6a6de6d-7e73-4fea-846c-3ec3c501b4c1.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='高山茶都-嘉義博茶會', `description`='嘉義的茶文化產業豐富且興盛，阿里山茶葉更是為國內外所盛讚的經典茗茶，與茶產業共生共長的還有深厚的茶文化涵養，結合嘉義縣精緻工藝與豐美農特產，讓遊客滿載而歸。嘉義縣除了傑出的茶文化產業引人入勝外，本活動亦結合本縣豐饒的農特產品、得天獨厚的優美景觀、珍貴精緻的工藝品，多元且全面的展現嘉義縣的優質條件，吸引各地旅客再三來訪。', `organizer`='嘉義縣政府', `address`='中埔鄉農會金蘭分部', `start_date`='2023-12-09 00:00:00', `end_date`='2023-12-17 00:00:00', `location`='嘉義縣中埔鄉', `latitude`=23.447025, `longitude`=120.492779, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/808fece1-124d-4511-af44-3031a8d0d75a.jpg", "https://www.taiwan.net.tw/att/event/c581ea05-da98-4225-8d2f-0d8719fe43db.jpg", "https://www.taiwan.net.tw/att/event/b6a6de6d-7e73-4fea-846c-3ec3c501b4c1.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081030', '2023東石海之夏', '「東石海之夏」作為嘉義縣暑期濱海觀光指標性活動，以濱海觀光與歡樂親子遊為主題，包含流行音樂演唱會、特色產業 DIY、親子活動等，鎖定全國暑假親子家庭與青少年旅遊客群，結合嘉義夏日外傘頂洲踏浪、東石布袋吃海鮮觀海景之獨特濱海遊程，打造暑假親子戲水及年輕族群玩樂打卡熱點活動，每年都吸引上萬名遊客來嘉享受濱海旅遊，持續帶動嘉義沿海東石、布袋相關產業觀光收益。', '嘉義縣政府文化觀光局、交通部觀光署雲嘉南濱海國家風景區管理處', '東石漁人碼頭', '2023-08-01 00:00:00', '2023-08-14 00:00:00', '嘉義縣東石鄉', 23.449047, 120.135067, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/8bac3a16-9584-42c3-ac42-c975cb357cd3.jpg", "https://www.taiwan.net.tw/att/event/5c334a8c-edbf-4b7a-a610-d2e9bf02d766.jpg", "https://www.taiwan.net.tw/att/event/e5fa120b-3625-4390-bf08-a8755b17178a.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023東石海之夏', `description`='「東石海之夏」作為嘉義縣暑期濱海觀光指標性活動，以濱海觀光與歡樂親子遊為主題，包含流行音樂演唱會、特色產業 DIY、親子活動等，鎖定全國暑假親子家庭與青少年旅遊客群，結合嘉義夏日外傘頂洲踏浪、東石布袋吃海鮮觀海景之獨特濱海遊程，打造暑假親子戲水及年輕族群玩樂打卡熱點活動，每年都吸引上萬名遊客來嘉享受濱海旅遊，持續帶動嘉義沿海東石、布袋相關產業觀光收益。', `organizer`='嘉義縣政府文化觀光局、交通部觀光署雲嘉南濱海國家風景區管理處', `address`='東石漁人碼頭', `start_date`='2023-08-01 00:00:00', `end_date`='2023-08-14 00:00:00', `location`='嘉義縣東石鄉', `latitude`=23.449047, `longitude`=120.135067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/8bac3a16-9584-42c3-ac42-c975cb357cd3.jpg", "https://www.taiwan.net.tw/att/event/5c334a8c-edbf-4b7a-a610-d2e9bf02d766.jpg", "https://www.taiwan.net.tw/att/event/e5fa120b-3625-4390-bf08-a8755b17178a.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081032', '2023嘉義市光織影舞-光影藝術展', '為增加嘉義市夜間觀光亮點，吸引旅客在嘉義市住宿及消費，本府於民國109年（西元2020年）10月1日起至11月1日（橫跨中秋及國慶連假）首次舉辦「2020嘉義市光織影舞-光影藝術展」，活動結合嘉義市城市人文特色及在地文化，以四季與中秋節（全國地表最大月亮）為主題，設置7件光影藝術裝置，營造陸（園區走道、草地）、水（北香湖湖水倒影）、空（樹林）氛圍之光影造景環境意象，並搭配精心安排的特色表演活動（如無人機煙火燈光秀、雷射投影及管樂表演燈光秀等），吸引全國及國際旅客來嘉義市駐留體驗', '嘉義市政府', '北香湖公園', '2023-09-29 00:00:00', '2023-10-10 00:00:00', '嘉義市西區', 23.492048, 120.445345, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/8b20ab7e-90e0-49a8-9137-d140fa5d369a.jpg", "https://www.taiwan.net.tw/att/event/7da4b849-11a7-46c8-96fb-412f187ad8bf.jpg", "https://www.taiwan.net.tw/att/event/f04581ce-6b16-46cd-9af3-5661276b9b68.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023嘉義市光織影舞-光影藝術展', `description`='為增加嘉義市夜間觀光亮點，吸引旅客在嘉義市住宿及消費，本府於民國109年（西元2020年）10月1日起至11月1日（橫跨中秋及國慶連假）首次舉辦「2020嘉義市光織影舞-光影藝術展」，活動結合嘉義市城市人文特色及在地文化，以四季與中秋節（全國地表最大月亮）為主題，設置7件光影藝術裝置，營造陸（園區走道、草地）、水（北香湖湖水倒影）、空（樹林）氛圍之光影造景環境意象，並搭配精心安排的特色表演活動（如無人機煙火燈光秀、雷射投影及管樂表演燈光秀等），吸引全國及國際旅客來嘉義市駐留體驗', `organizer`='嘉義市政府', `address`='北香湖公園', `start_date`='2023-09-29 00:00:00', `end_date`='2023-10-10 00:00:00', `location`='嘉義市西區', `latitude`=23.492048, `longitude`=120.445345, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/8b20ab7e-90e0-49a8-9137-d140fa5d369a.jpg", "https://www.taiwan.net.tw/att/event/7da4b849-11a7-46c8-96fb-412f187ad8bf.jpg", "https://www.taiwan.net.tw/att/event/f04581ce-6b16-46cd-9af3-5661276b9b68.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081033', '2023臺南市國際龍舟錦標賽', '本活動乃結合臺灣傳統節慶習俗水上運動競賽發展而來，深具地方文化的代表性，是臺南極具特色的文化觀光活動。臺南市也是臺灣龍舟競渡的重要發源地，比賽前後循古禮舉行請水神、送水神、祭江，及封江儀式，相當別具意義。每年的國際龍舟錦標賽均廣邀國內外遊客熱情參加，是臺南市固定舉辦之重大節慶之一。民國101年（西元2012年）的參賽隊伍更高達179隊，打破歷年來參與龍舟錦標賽的輝煌紀錄，盛況空前。臺南市是兼具活力與文化氣息的城市，來臺南看龍舟比賽、品美食、品文化古都新臺南，感受道地濃濃的人情味，歡慶端午佳節。', '臺南市政府', '臺南運河（安億橋至承天橋）', '2023-06-18 00:00:00', '2023-06-22 00:00:00', '臺南市安平區', 22.998068, 120.167439, '無資料', 'https://dragonboat.tainan.gov.tw/', '["https://www.taiwan.net.tw/att/event/9e7c6515-e277-4edf-a9ba-729fd4787a95.jpg", "https://www.taiwan.net.tw/att/event/5fa551e6-3b9e-4a32-b8ae-e698d46bdea5.jpg", "https://www.taiwan.net.tw/att/event/3b67ecf6-417c-48c6-a7f9-523814c93303.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023臺南市國際龍舟錦標賽', `description`='本活動乃結合臺灣傳統節慶習俗水上運動競賽發展而來，深具地方文化的代表性，是臺南極具特色的文化觀光活動。臺南市也是臺灣龍舟競渡的重要發源地，比賽前後循古禮舉行請水神、送水神、祭江，及封江儀式，相當別具意義。每年的國際龍舟錦標賽均廣邀國內外遊客熱情參加，是臺南市固定舉辦之重大節慶之一。民國101年（西元2012年）的參賽隊伍更高達179隊，打破歷年來參與龍舟錦標賽的輝煌紀錄，盛況空前。臺南市是兼具活力與文化氣息的城市，來臺南看龍舟比賽、品美食、品文化古都新臺南，感受道地濃濃的人情味，歡慶端午佳節。', `organizer`='臺南市政府', `address`='臺南運河（安億橋至承天橋）', `start_date`='2023-06-18 00:00:00', `end_date`='2023-06-22 00:00:00', `location`='臺南市安平區', `latitude`=22.998068, `longitude`=120.167439, `ticket_price`='無資料', `source_url`='https://dragonboat.tainan.gov.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/9e7c6515-e277-4edf-a9ba-729fd4787a95.jpg", "https://www.taiwan.net.tw/att/event/5fa551e6-3b9e-4a32-b8ae-e698d46bdea5.jpg", "https://www.taiwan.net.tw/att/event/3b67ecf6-417c-48c6-a7f9-523814c93303.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081034', '2023高雄蓮潭燈會', '融合蓮池潭地景特色規劃，並邀請高雄在地設計師及藝術家擔任燈飾區創作者，兼顧燈區及燈飾日夜不同觀賞效果，營造奇幻療癒的節慶氛圍。', '高雄市政府觀光局', '蓮池潭', '2023-01-26 00:00:00', '2023-02-05 00:00:00', '高雄市左營區', 22.683332, 120.296698, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/3d4d14b7-e2e3-4412-9aee-facf96317723.jpg", "https://www.taiwan.net.tw/att/event/a500eb2d-cec8-4606-b186-fa56316a9991.jpg", "https://www.taiwan.net.tw/att/event/cd3575e6-f784-49c2-9add-8c620f02727d.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023高雄蓮潭燈會', `description`='融合蓮池潭地景特色規劃，並邀請高雄在地設計師及藝術家擔任燈飾區創作者，兼顧燈區及燈飾日夜不同觀賞效果，營造奇幻療癒的節慶氛圍。', `organizer`='高雄市政府觀光局', `address`='蓮池潭', `start_date`='2023-01-26 00:00:00', `end_date`='2023-02-05 00:00:00', `location`='高雄市左營區', `latitude`=22.683332, `longitude`=120.296698, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/3d4d14b7-e2e3-4412-9aee-facf96317723.jpg", "https://www.taiwan.net.tw/att/event/a500eb2d-cec8-4606-b186-fa56316a9991.jpg", "https://www.taiwan.net.tw/att/event/cd3575e6-f784-49c2-9add-8c620f02727d.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081035', '2023高雄左營萬年季', '每年10月中旬在左營蓮池潭登場的萬年季活動，自民國90年（西元2001年）舉辦至今已邁入第20年，運用左營獨有天然景觀（蓮池潭及周邊林立的寺廟）、結合特殊民情風俗（攻炮城、迓火獅）等在地因素規劃而成，由於活動設計極具地方特色，每年吸引許多參觀人潮，已發展成為本市重要民俗文化觀光節慶活動。', '高雄市政府民政局', '左營孔廟', '2023-10-07 00:00:00', '2023-10-09 00:00:00', '高雄市左營區', 22.689339, 120.298733, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/1044be4d-cc9c-4294-9053-b10baba417a9.jpg", "https://www.taiwan.net.tw/att/event/abea5dc4-74ed-488a-9fba-c8028d19fd17.jpg", "https://www.taiwan.net.tw/att/event/be87cf7a-ce7f-4993-8484-18fdb55611ec.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023高雄左營萬年季', `description`='每年10月中旬在左營蓮池潭登場的萬年季活動，自民國90年（西元2001年）舉辦至今已邁入第20年，運用左營獨有天然景觀（蓮池潭及周邊林立的寺廟）、結合特殊民情風俗（攻炮城、迓火獅）等在地因素規劃而成，由於活動設計極具地方特色，每年吸引許多參觀人潮，已發展成為本市重要民俗文化觀光節慶活動。', `organizer`='高雄市政府民政局', `address`='左營孔廟', `start_date`='2023-10-07 00:00:00', `end_date`='2023-10-09 00:00:00', `location`='高雄市左營區', `latitude`=22.689339, `longitude`=120.298733, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/1044be4d-cc9c-4294-9053-b10baba417a9.jpg", "https://www.taiwan.net.tw/att/event/abea5dc4-74ed-488a-9fba-c8028d19fd17.jpg", "https://www.taiwan.net.tw/att/event/be87cf7a-ce7f-4993-8484-18fdb55611ec.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081036', '2023屏東落山風藝術季', '「落山風之吹風看海地」，位於車城鄉海口港，包含看海美術館、待(呆)・風樓及沙灘歇腳站共三館及週邊廣場綠帶，藝術季以其為根據地以藝術經營地方，建立「屏東縣落山風風景特定區」文化品牌，構建地方風格、活絡社區進而豐富恆春半島之觀光內涵。屏東落山風藝術季以車城海口港「落山風之吹風看海地」及旁邊沙灘為主要場地，已辦理2屆，以大型藝術裝置及表演活動形式，展現風與地方之特色，且今年7月看海美術館推出首檔展覽「春江獸月夜」更獲得國內媒體高度關注與報導，網路討論聲量高，將為12月藝術季帶來更多關注與觀賞人次。', '屏東縣政府傳播暨國際事務處', '海口港看海美術館', '2023-11-01 00:00:00', '2024-02-29 00:00:00', '屏東縣車城鄉', 22.089952, 120.715287, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/d15d8b4a-5f67-4c53-8b83-691a3803ec8b.jpg", "https://www.taiwan.net.tw/att/event/4bc43a28-be75-4813-92dd-292a12b6e0a9.jpg", "https://www.taiwan.net.tw/att/event/385a65df-8d2e-40c3-80b9-0720f82e3625.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023屏東落山風藝術季', `description`='「落山風之吹風看海地」，位於車城鄉海口港，包含看海美術館、待(呆)・風樓及沙灘歇腳站共三館及週邊廣場綠帶，藝術季以其為根據地以藝術經營地方，建立「屏東縣落山風風景特定區」文化品牌，構建地方風格、活絡社區進而豐富恆春半島之觀光內涵。屏東落山風藝術季以車城海口港「落山風之吹風看海地」及旁邊沙灘為主要場地，已辦理2屆，以大型藝術裝置及表演活動形式，展現風與地方之特色，且今年7月看海美術館推出首檔展覽「春江獸月夜」更獲得國內媒體高度關注與報導，網路討論聲量高，將為12月藝術季帶來更多關注與觀賞人次。', `organizer`='屏東縣政府傳播暨國際事務處', `address`='海口港看海美術館', `start_date`='2023-11-01 00:00:00', `end_date`='2024-02-29 00:00:00', `location`='屏東縣車城鄉', `latitude`=22.089952, `longitude`=120.715287, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/d15d8b4a-5f67-4c53-8b83-691a3803ec8b.jpg", "https://www.taiwan.net.tw/att/event/4bc43a28-be75-4813-92dd-292a12b6e0a9.jpg", "https://www.taiwan.net.tw/att/event/385a65df-8d2e-40c3-80b9-0720f82e3625.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081037', '2023屏東黑鮪魚文化觀光季', '黑鮪魚季自民國90年（西元2001年）起迄今已邁入第20年舉辦，歷年結合農漁及觀光產業，成功打造「黑鮪魚文化觀光季在屏東」的國家品牌節慶活動，考量近年升溫之海洋資源枯竭、生態保育等議題，將回歸辦理之初衷，規劃感恩收穫─第一鮪拍賣會、開幕晚會、在地美食推廣、在地小旅行等系列活動，促進當地經濟效益、創造行銷話題！活動透過節慶氛圍營造、文化意象型塑、分眾行銷、串連地方參與、交通旅遊服務等方向，結合本縣自然景觀資源、農漁特產文化，創造周邊產業之經濟效益，以突顯屏東的獨特產業、文化觀光潛力、漁村文化精神與海洋資源永續發展，使屏東縣的發展從傳統的農業邁入「精緻美食、休閒旅遊與文化藝術」三位一體的觀光旅遊新紀元。', '屏東縣政府傳播暨國際事務處', '東隆宮', '2023-05-06 00:00:00', '2023-07-02 00:00:00', '屏東縣東港鎮', 22.463065, 120.448806, '無資料', 'https://www.amazing-pingtung.com/ptcf', '["https://www.taiwan.net.tw/att/event/a9c573b6-155f-41db-afff-3172818db9be.jpg", "https://www.taiwan.net.tw/att/event/0544c54a-100b-416c-9b30-74dffabf1310.jpg", "https://www.taiwan.net.tw/att/event/9e983bfa-af6a-4baf-90b3-6dd53841fb4f.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023屏東黑鮪魚文化觀光季', `description`='黑鮪魚季自民國90年（西元2001年）起迄今已邁入第20年舉辦，歷年結合農漁及觀光產業，成功打造「黑鮪魚文化觀光季在屏東」的國家品牌節慶活動，考量近年升溫之海洋資源枯竭、生態保育等議題，將回歸辦理之初衷，規劃感恩收穫─第一鮪拍賣會、開幕晚會、在地美食推廣、在地小旅行等系列活動，促進當地經濟效益、創造行銷話題！活動透過節慶氛圍營造、文化意象型塑、分眾行銷、串連地方參與、交通旅遊服務等方向，結合本縣自然景觀資源、農漁特產文化，創造周邊產業之經濟效益，以突顯屏東的獨特產業、文化觀光潛力、漁村文化精神與海洋資源永續發展，使屏東縣的發展從傳統的農業邁入「精緻美食、休閒旅遊與文化藝術」三位一體的觀光旅遊新紀元。', `organizer`='屏東縣政府傳播暨國際事務處', `address`='東隆宮', `start_date`='2023-05-06 00:00:00', `end_date`='2023-07-02 00:00:00', `location`='屏東縣東港鎮', `latitude`=22.463065, `longitude`=120.448806, `ticket_price`='無資料', `source_url`='https://www.amazing-pingtung.com/ptcf', `image_url`='["https://www.taiwan.net.tw/att/event/a9c573b6-155f-41db-afff-3172818db9be.jpg", "https://www.taiwan.net.tw/att/event/0544c54a-100b-416c-9b30-74dffabf1310.jpg", "https://www.taiwan.net.tw/att/event/9e983bfa-af6a-4baf-90b3-6dd53841fb4f.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081038', '2023宜蘭國際童玩藝術節', '民國85年（西元1996年）迄今，童玩節已經舉辦了20屆，在每年暑假，已成為國人期待的大型文化活動。民國90年（民國2001年）度開始更獲選為觀光署所推薦的「十二大地方節慶活動」之一。民國101年（西元2012年）度更獲選為交通部觀光署2012「台灣觀光年曆」觀光活動，成為觀光署國際推廣行銷的亮點之一；更由於童玩節所堅持之創意、服務品質之訴求，民國99年獲得了「國際民俗藝術節協會」( CIOFF&reg; )認證為國際民俗藝術節協會之國際藝術節(CIOFF&reg; International Festival)，亞洲第一個以「兒童」為主題獲得認證的民俗藝術節，民國103年（西元2014年）獲得天下雜誌「金牌服務大賞」之殊榮。童玩節自創辦迄今，累積已超過1,031萬人次曾共同參與童玩節文化饗宴。優質的生活空間搭配各項大型活動，將成為發展觀光產業最寶貴的資產；宜蘭縣更建立了一套完整的旅遊資訊網絡，讓縣民共同參與觀光資源的經營及利益，擴大宜蘭「健康」、「智慧」、「永續」的觀光發展效益。', '宜蘭縣政府', '親河路二段2號', '2023-07-01 00:00:00', '2023-08-13 00:00:00', '宜蘭縣五結鄉', 24.672993, 121.815816, '無資料', 'https://www.yicfff.tw/', '["https://www.taiwan.net.tw/att/event/23649233-ef02-4868-ac7e-00742be61731.jpg", "https://www.taiwan.net.tw/att/event/3d576942-eb36-4057-af27-52eaf7d48480.jpg", "https://www.taiwan.net.tw/att/event/c6c60fd2-e3c0-429c-ac7d-e5a9237a4efb.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023宜蘭國際童玩藝術節', `description`='民國85年（西元1996年）迄今，童玩節已經舉辦了20屆，在每年暑假，已成為國人期待的大型文化活動。民國90年（民國2001年）度開始更獲選為觀光署所推薦的「十二大地方節慶活動」之一。民國101年（西元2012年）度更獲選為交通部觀光署2012「台灣觀光年曆」觀光活動，成為觀光署國際推廣行銷的亮點之一；更由於童玩節所堅持之創意、服務品質之訴求，民國99年獲得了「國際民俗藝術節協會」( CIOFF&reg; )認證為國際民俗藝術節協會之國際藝術節(CIOFF&reg; International Festival)，亞洲第一個以「兒童」為主題獲得認證的民俗藝術節，民國103年（西元2014年）獲得天下雜誌「金牌服務大賞」之殊榮。童玩節自創辦迄今，累積已超過1,031萬人次曾共同參與童玩節文化饗宴。優質的生活空間搭配各項大型活動，將成為發展觀光產業最寶貴的資產；宜蘭縣更建立了一套完整的旅遊資訊網絡，讓縣民共同參與觀光資源的經營及利益，擴大宜蘭「健康」、「智慧」、「永續」的觀光發展效益。', `organizer`='宜蘭縣政府', `address`='親河路二段2號', `start_date`='2023-07-01 00:00:00', `end_date`='2023-08-13 00:00:00', `location`='宜蘭縣五結鄉', `latitude`=24.672993, `longitude`=121.815816, `ticket_price`='無資料', `source_url`='https://www.yicfff.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/23649233-ef02-4868-ac7e-00742be61731.jpg", "https://www.taiwan.net.tw/att/event/3d576942-eb36-4057-af27-52eaf7d48480.jpg", "https://www.taiwan.net.tw/att/event/c6c60fd2-e3c0-429c-ac7d-e5a9237a4efb.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081039', '2023花蓮夏戀嘉年華', '花蓮夏戀嘉年華是花蓮一年一度的盛大音樂饗宴，歷年以大型演唱會舞台規格，廣邀國際性巨星與知名歌手登台演出。「只要一張到花蓮的車票，等同直通台北小巨蛋演唱會門票」，是全國具指標性的盛夏音樂節。夏戀嘉年華活動是暑假期間國人熟知且熱愛的節慶活動之一，也是知名巨星歌手、偶像團體的表演殿堂，不但引領整個亞洲流行音樂，更吸引國際友人及愛好流行音樂的朋友們，來到東台灣認識花蓮、愛上花蓮。為豐富活動節目內容，近年來也特別舉辦在地表演團體徵選活動，發掘花蓮表演新秀團隊，提供優秀表演者嶄露頭角的機會，並且有機會登上夏戀嘉年華大型舞台成為耀眼的「夏戀之星」，亦藉由徵選活動培養在地表演人才，也做為孕育流行音樂巨星的平台。', '花蓮縣政府觀光處', '鯉魚潭', '2023-07-05 00:00:00', '2023-07-09 00:00:00', '花蓮縣壽豐鄉', 23.927826, 121.509878, '無資料', 'https://tour-hualien.hl.gov.tw/News_Content.aspx?n=108&s=7829', '["https://www.taiwan.net.tw/att/event/2790655b-94db-44c6-91eb-f9a8d54af59b.jpg", "https://www.taiwan.net.tw/att/event/a2aef4e9-7693-4c4c-8a4f-d53d55b01cdd.jpg", "https://www.taiwan.net.tw/att/event/04435eeb-35f4-4a12-bbb4-3b6cbe5169fd.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023花蓮夏戀嘉年華', `description`='花蓮夏戀嘉年華是花蓮一年一度的盛大音樂饗宴，歷年以大型演唱會舞台規格，廣邀國際性巨星與知名歌手登台演出。「只要一張到花蓮的車票，等同直通台北小巨蛋演唱會門票」，是全國具指標性的盛夏音樂節。夏戀嘉年華活動是暑假期間國人熟知且熱愛的節慶活動之一，也是知名巨星歌手、偶像團體的表演殿堂，不但引領整個亞洲流行音樂，更吸引國際友人及愛好流行音樂的朋友們，來到東台灣認識花蓮、愛上花蓮。為豐富活動節目內容，近年來也特別舉辦在地表演團體徵選活動，發掘花蓮表演新秀團隊，提供優秀表演者嶄露頭角的機會，並且有機會登上夏戀嘉年華大型舞台成為耀眼的「夏戀之星」，亦藉由徵選活動培養在地表演人才，也做為孕育流行音樂巨星的平台。', `organizer`='花蓮縣政府觀光處', `address`='鯉魚潭', `start_date`='2023-07-05 00:00:00', `end_date`='2023-07-09 00:00:00', `location`='花蓮縣壽豐鄉', `latitude`=23.927826, `longitude`=121.509878, `ticket_price`='無資料', `source_url`='https://tour-hualien.hl.gov.tw/News_Content.aspx?n=108&s=7829', `image_url`='["https://www.taiwan.net.tw/att/event/2790655b-94db-44c6-91eb-f9a8d54af59b.jpg", "https://www.taiwan.net.tw/att/event/a2aef4e9-7693-4c4c-8a4f-d53d55b01cdd.jpg", "https://www.taiwan.net.tw/att/event/04435eeb-35f4-4a12-bbb4-3b6cbe5169fd.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081041', '2023花蓮縣原住民族聯合豐年祭', '原住民族聯合豐年節已成為臺灣地區原住民族國際性活動，為永續發展並推廣、延續原住民族獨特的文化內涵及展演特色，民國110年（西元2021年）再度結合樂舞展演人才、宣傳行銷及舞台等軟硬體資源，賡續辦理具規模及獨特性之「原住民族聯合豐年節」，藉由展演式的呈現原住民族歌謠、肢體、舞蹈與文化祭儀的精髓，保存、傳承原住民族文化，活動亦將設置特色攤位，如：原住民特色美食區、手工藝品展售區及各原住民農特產、部落微旅行簡介等，以活化、創造部落商機，今年聯合豐年節大會舞歌曲「一曲愛海洋」，以輕快活潑風格，再創造原住民族音樂與舞蹈流行風潮。', '花蓮縣政府', '花蓮縣德興運動場旁之大草坪', '2023-07-21 00:00:00', '2023-07-23 00:00:00', '花蓮縣花蓮市', 24.00678, 121.583516, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/8a839d39-dfe4-491d-bd0a-a506ff1eef43.jpg", "https://www.taiwan.net.tw/att/event/5b80e6c2-076e-45b8-bfd4-917afe9aa40d.jpg", "https://www.taiwan.net.tw/att/event/77d9296a-3e12-4385-a1f9-9fccdf59da97.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023花蓮縣原住民族聯合豐年祭', `description`='原住民族聯合豐年節已成為臺灣地區原住民族國際性活動，為永續發展並推廣、延續原住民族獨特的文化內涵及展演特色，民國110年（西元2021年）再度結合樂舞展演人才、宣傳行銷及舞台等軟硬體資源，賡續辦理具規模及獨特性之「原住民族聯合豐年節」，藉由展演式的呈現原住民族歌謠、肢體、舞蹈與文化祭儀的精髓，保存、傳承原住民族文化，活動亦將設置特色攤位，如：原住民特色美食區、手工藝品展售區及各原住民農特產、部落微旅行簡介等，以活化、創造部落商機，今年聯合豐年節大會舞歌曲「一曲愛海洋」，以輕快活潑風格，再創造原住民族音樂與舞蹈流行風潮。', `organizer`='花蓮縣政府', `address`='花蓮縣德興運動場旁之大草坪', `start_date`='2023-07-21 00:00:00', `end_date`='2023-07-23 00:00:00', `location`='花蓮縣花蓮市', `latitude`=24.00678, `longitude`=121.583516, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/8a839d39-dfe4-491d-bd0a-a506ff1eef43.jpg", "https://www.taiwan.net.tw/att/event/5b80e6c2-076e-45b8-bfd4-917afe9aa40d.jpg", "https://www.taiwan.net.tw/att/event/77d9296a-3e12-4385-a1f9-9fccdf59da97.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081042', '2023臺東最美星空系列活動', '臺東最美星空系列活動整體區分為三部份，分別為導遊培訓、導覽活動和最美星空音樂會。由於臺東地域地廣人稀，即使交通比之西部來的不便，卻因此保留西部所沒有的天然環境，低汙染、低噪音、沒有高樓大廈的遮蔽，沒有嚴重的光害跟PM2.5，與西部相較之下，觀賞星星容易許多，觀星的地方多不勝數。搭配星空音樂會、導覽解說及相關星空活動，不僅提升遊客或民眾對天文的知識及興趣，也能增加民眾對星空的熟悉度。    星空導覽：4月~10月    星空音樂會：8月~9月※因地震頻繁，為顧及參與民眾、現場演出人員與工作人員之安全，9/18台東最美星空音樂會卑南場確認取消。其餘場次及活動請依活動粉絲專頁公告為主。 -->', '臺東縣政府', '杉原海水浴場', '2023-06-22 00:00:00', '2023-09-16 00:00:00', '臺東縣卑南鄉', 22.830767, 121.186123, '無資料', 'https://www.xn--kpr063bjtawn699e24g.tw/', '["https://www.taiwan.net.tw/att/event/655eb243-d750-4101-9b8c-448ef98c43be.jpg", "https://www.taiwan.net.tw/att/event/c2804d38-73ca-4b21-9176-edc63fa0a7c6.jpg", "https://www.taiwan.net.tw/att/event/7d349025-c7a1-4896-bbbd-b81562d53f16.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023臺東最美星空系列活動', `description`='臺東最美星空系列活動整體區分為三部份，分別為導遊培訓、導覽活動和最美星空音樂會。由於臺東地域地廣人稀，即使交通比之西部來的不便，卻因此保留西部所沒有的天然環境，低汙染、低噪音、沒有高樓大廈的遮蔽，沒有嚴重的光害跟PM2.5，與西部相較之下，觀賞星星容易許多，觀星的地方多不勝數。搭配星空音樂會、導覽解說及相關星空活動，不僅提升遊客或民眾對天文的知識及興趣，也能增加民眾對星空的熟悉度。    星空導覽：4月~10月    星空音樂會：8月~9月※因地震頻繁，為顧及參與民眾、現場演出人員與工作人員之安全，9/18台東最美星空音樂會卑南場確認取消。其餘場次及活動請依活動粉絲專頁公告為主。 -->', `organizer`='臺東縣政府', `address`='杉原海水浴場', `start_date`='2023-06-22 00:00:00', `end_date`='2023-09-16 00:00:00', `location`='臺東縣卑南鄉', `latitude`=22.830767, `longitude`=121.186123, `ticket_price`='無資料', `source_url`='https://www.xn--kpr063bjtawn699e24g.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/655eb243-d750-4101-9b8c-448ef98c43be.jpg", "https://www.taiwan.net.tw/att/event/c2804d38-73ca-4b21-9176-edc63fa0a7c6.jpg", "https://www.taiwan.net.tw/att/event/7d349025-c7a1-4896-bbbd-b81562d53f16.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081043', '2023金門馬拉松', '為提倡全民健康休閒活動，提升全民運動休閒風氣，使全民更加了解金門戰地風光及提倡全民運動，透過舉辦活動，引領民眾走進金門縣，瞭解戰地風光景觀資源之豐富及多樣性，同時藉由吸引國內外朋友造訪深具獨特戰地風光景觀及傳統人文資源特色之金門縣，達到促進地方產業發展，期使本縣觀光、全民運動休閒與國際接軌。金門馬拉松具有道路平坦、賽道風景、獨特人文及戰地風情的特色，許多海內外跑者聞香而來的金門高粱酒，沿途閩南古厝保留完好，西式洋樓建築群與傳統民俗相融的美景，已令此賽事成為兩岸三地或甚至為國際級跑者間口耳相傳的「必搶、必跑、必玩」年度經典馬拉松賽事，著實可稱為揚名國際、打響臺灣名號之國際級賽事。    1月15日(六) 健康休閒組 (5KM)    集合地點：金門縣立田徑場    1月16日(日) 競賽組 (10.8KM、半馬及全馬)    集合地點：金湖綜合體育館 -->', '金門縣政府', '金門縣立田徑場', '2023-02-11 00:00:00', '2023-02-12 00:00:00', '金門縣金城鎮', 24.429861, 118.315233, '無資料', 'https://www.sportsnet.org.tw/20230212_web/', '["https://www.taiwan.net.tw/att/event/7a95c6e5-5cde-4f2b-8d79-21763524118c.jpg", "https://www.taiwan.net.tw/att/event/202a57cc-b1b1-4879-ae91-927909df3018.jpg", "https://www.taiwan.net.tw/att/event/0ae97dc2-69f2-4a64-a6e3-3a5d140fafaf.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023金門馬拉松', `description`='為提倡全民健康休閒活動，提升全民運動休閒風氣，使全民更加了解金門戰地風光及提倡全民運動，透過舉辦活動，引領民眾走進金門縣，瞭解戰地風光景觀資源之豐富及多樣性，同時藉由吸引國內外朋友造訪深具獨特戰地風光景觀及傳統人文資源特色之金門縣，達到促進地方產業發展，期使本縣觀光、全民運動休閒與國際接軌。金門馬拉松具有道路平坦、賽道風景、獨特人文及戰地風情的特色，許多海內外跑者聞香而來的金門高粱酒，沿途閩南古厝保留完好，西式洋樓建築群與傳統民俗相融的美景，已令此賽事成為兩岸三地或甚至為國際級跑者間口耳相傳的「必搶、必跑、必玩」年度經典馬拉松賽事，著實可稱為揚名國際、打響臺灣名號之國際級賽事。    1月15日(六) 健康休閒組 (5KM)    集合地點：金門縣立田徑場    1月16日(日) 競賽組 (10.8KM、半馬及全馬)    集合地點：金湖綜合體育館 -->', `organizer`='金門縣政府', `address`='金門縣立田徑場', `start_date`='2023-02-11 00:00:00', `end_date`='2023-02-12 00:00:00', `location`='金門縣金城鎮', `latitude`=24.429861, `longitude`=118.315233, `ticket_price`='無資料', `source_url`='https://www.sportsnet.org.tw/20230212_web/', `image_url`='["https://www.taiwan.net.tw/att/event/7a95c6e5-5cde-4f2b-8d79-21763524118c.jpg", "https://www.taiwan.net.tw/att/event/202a57cc-b1b1-4879-ae91-927909df3018.jpg", "https://www.taiwan.net.tw/att/event/0ae97dc2-69f2-4a64-a6e3-3a5d140fafaf.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081044', '2023馬祖擺暝文化祭', '擺暝文化為馬祖最具代表性的文化活動，極具獨特性，近期亦積極爭取登錄重要民俗無形文化資產，「擺暝（音ㄅㄟˇ ㄇㄢˋ）」是福州話，為「排夜」的意思，簡單來說就是在夜晚的時候排放供品祭神酬神，在每年的元宵節前後舉行，夜間各廟宇的神還會出宮繞境，以祈求全境平安。此習俗最早源自於福州長樂、連江一帶，流傳至馬祖成為一年當中最重要、最盛大且特有的節慶活動，當地居民相當重視，甚至在外打拼的遊子也都會回來，全村總動員一起共同參與，北竿鄉獨一無二的「扛乩」、「燒馬糧」及「祈夢」儀式，吸引不少遊客前來一探究竟，近年來更結合兩馬同春鬧元宵活動，更增添活動的豐富性與可看性。', '連江縣政府文化處', '僑仔村', '2023-02-02 00:00:00', '2023-02-05 00:00:00', '連江縣北竿鄉', 26.272912, 119.98706, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/80ef4257-4f23-4e81-bbc9-a8dad18d6c2c.jpg", "https://www.taiwan.net.tw/att/event/eb615b25-f1fa-4f0e-887c-23e0d908791d.jpg", "https://www.taiwan.net.tw/att/event/81e94707-757f-4a7b-87ef-29613f7ab4fe.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023馬祖擺暝文化祭', `description`='擺暝文化為馬祖最具代表性的文化活動，極具獨特性，近期亦積極爭取登錄重要民俗無形文化資產，「擺暝（音ㄅㄟˇ ㄇㄢˋ）」是福州話，為「排夜」的意思，簡單來說就是在夜晚的時候排放供品祭神酬神，在每年的元宵節前後舉行，夜間各廟宇的神還會出宮繞境，以祈求全境平安。此習俗最早源自於福州長樂、連江一帶，流傳至馬祖成為一年當中最重要、最盛大且特有的節慶活動，當地居民相當重視，甚至在外打拼的遊子也都會回來，全村總動員一起共同參與，北竿鄉獨一無二的「扛乩」、「燒馬糧」及「祈夢」儀式，吸引不少遊客前來一探究竟，近年來更結合兩馬同春鬧元宵活動，更增添活動的豐富性與可看性。', `organizer`='連江縣政府文化處', `address`='僑仔村', `start_date`='2023-02-02 00:00:00', `end_date`='2023-02-05 00:00:00', `location`='連江縣北竿鄉', `latitude`=26.272912, `longitude`=119.98706, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/80ef4257-4f23-4e81-bbc9-a8dad18d6c2c.jpg", "https://www.taiwan.net.tw/att/event/eb615b25-f1fa-4f0e-887c-23e0d908791d.jpg", "https://www.taiwan.net.tw/att/event/81e94707-757f-4a7b-87ef-29613f7ab4fe.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081045', '2023北竿硬地超級馬拉松', '「北竿硬地超級馬拉松」自民國106年（西元2017年）首度舉辦，由於地形陡峻起伏多變，賽道上幾乎沒有平坦的路段，極具挑戰性，因此跑友們稱其為「最硬賽道」，故而取名為硬地超級馬拉松。除了賽道的獨特性外，北竿的戰地景觀及特殊的海島風光也是讓跑友們最津津樂道之處，沿途美景處處，藍天碧海相伴，使報名參與賽事的人數逐年成長。此外，賽事活動與當地的居民、商家合作，讓外地來的跑者在食、住、行上都享有優惠，也延長跑者待在本地旅遊的時間及增加跑者再次踏上北竿鄉的意願。另一方面，本賽事獲得國際超級馬拉松運動協會（International Association of Ultrarunners，簡稱 IAU）的銅標籤認證，賽事日期與簡介也因此得以排入 IAU 行事曆中，吸引全世界的超級馬拉松跑者來到北竿參與賽事。', '連江縣政府交通旅遊局', '北竿綜合運動場', '2023-03-18 00:00:00', '2023-03-18 00:00:00', '連江縣北竿鄉', 26.225832, 119.99795, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/92a7d077-e2fa-47b5-93da-3b7c83f559a1.jpg", "https://www.taiwan.net.tw/att/event/356055d6-8dbe-4962-b442-7072faa0a84c.jpg", "https://www.taiwan.net.tw/att/event/d347836d-57a8-4a90-a58c-44cff99c6b2c.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023北竿硬地超級馬拉松', `description`='「北竿硬地超級馬拉松」自民國106年（西元2017年）首度舉辦，由於地形陡峻起伏多變，賽道上幾乎沒有平坦的路段，極具挑戰性，因此跑友們稱其為「最硬賽道」，故而取名為硬地超級馬拉松。除了賽道的獨特性外，北竿的戰地景觀及特殊的海島風光也是讓跑友們最津津樂道之處，沿途美景處處，藍天碧海相伴，使報名參與賽事的人數逐年成長。此外，賽事活動與當地的居民、商家合作，讓外地來的跑者在食、住、行上都享有優惠，也延長跑者待在本地旅遊的時間及增加跑者再次踏上北竿鄉的意願。另一方面，本賽事獲得國際超級馬拉松運動協會（International Association of Ultrarunners，簡稱 IAU）的銅標籤認證，賽事日期與簡介也因此得以排入 IAU 行事曆中，吸引全世界的超級馬拉松跑者來到北竿參與賽事。', `organizer`='連江縣政府交通旅遊局', `address`='北竿綜合運動場', `start_date`='2023-03-18 00:00:00', `end_date`='2023-03-18 00:00:00', `location`='連江縣北竿鄉', `latitude`=26.225832, `longitude`=119.99795, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/92a7d077-e2fa-47b5-93da-3b7c83f559a1.jpg", "https://www.taiwan.net.tw/att/event/356055d6-8dbe-4962-b442-7072faa0a84c.jpg", "https://www.taiwan.net.tw/att/event/d347836d-57a8-4a90-a58c-44cff99c6b2c.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081046', '2023金門坑道音樂節', '本處擁有許多珍貴的戰役資源，尤因戰役挖鑿的各式坑道，更是金門遊憩資源的重點。為發揮金門特色，本處籌劃辦理「金門坑道音樂節」活動，以鬼斧神工的翟山坑道作為天然音箱，讓演奏、演唱者的聲音更加純淨，祈以悠揚的音樂，讓世人體會翟山坑道獨一無二的歷史場景，並以音樂化身和平的天使，共創幸福的未來。', '金門國家公園管理處', '翟山坑道', '2023-10-21 00:00:00', '2023-10-22 00:00:00', '金門縣金城鎮', 24.390301, 118.320616, '無資料', 'https://www.kinmentunnelmusic.com.tw/', '["https://www.taiwan.net.tw/att/event/0a69b7e1-df98-4b6b-9310-23ac61e579c7.jpg", "https://www.taiwan.net.tw/att/event/2c9c25ff-3f73-423a-a78c-2713f30d2d86.jpg", "https://www.taiwan.net.tw/att/event/1fd70cec-1cf9-471a-86c3-1402eb89fb5c.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023金門坑道音樂節', `description`='本處擁有許多珍貴的戰役資源，尤因戰役挖鑿的各式坑道，更是金門遊憩資源的重點。為發揮金門特色，本處籌劃辦理「金門坑道音樂節」活動，以鬼斧神工的翟山坑道作為天然音箱，讓演奏、演唱者的聲音更加純淨，祈以悠揚的音樂，讓世人體會翟山坑道獨一無二的歷史場景，並以音樂化身和平的天使，共創幸福的未來。', `organizer`='金門國家公園管理處', `address`='翟山坑道', `start_date`='2023-10-21 00:00:00', `end_date`='2023-10-22 00:00:00', `location`='金門縣金城鎮', `latitude`=24.390301, `longitude`=118.320616, `ticket_price`='無資料', `source_url`='https://www.kinmentunnelmusic.com.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/0a69b7e1-df98-4b6b-9310-23ac61e579c7.jpg", "https://www.taiwan.net.tw/att/event/2c9c25ff-3f73-423a-a78c-2713f30d2d86.jpg", "https://www.taiwan.net.tw/att/event/1fd70cec-1cf9-471a-86c3-1402eb89fb5c.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081047', '經濟部商業司臺菜餐廳系列活動', '為帶動我國餐飲產業發展，持續推廣並傳承臺菜文化，經濟部商業司特辦理「經濟部商業司臺菜餐廳」徵選活動，以「臺菜」為主軸，運用主題式行銷、國際推廣及商機促進，提升臺菜文化國際形象及服務能量，以吸引國內外旅客體驗臺灣美食好滋味。', '經濟部商業司', '星靚點花園飯店', '2023-10-01 00:00:00', '2023-10-31 00:00:00', '臺北市文山區', 24.992082, 121.543578, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/8de9d6bc-8d2b-41ee-873d-fe1cbdaeaac8.jpg", "https://www.taiwan.net.tw/att/event/9283c849-40a3-4cf8-be14-0b871ae647db.jpg", "https://www.taiwan.net.tw/att/event/53c37a18-76fe-4ecb-8aef-66a348c295a9.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='經濟部商業司臺菜餐廳系列活動', `description`='為帶動我國餐飲產業發展，持續推廣並傳承臺菜文化，經濟部商業司特辦理「經濟部商業司臺菜餐廳」徵選活動，以「臺菜」為主軸，運用主題式行銷、國際推廣及商機促進，提升臺菜文化國際形象及服務能量，以吸引國內外旅客體驗臺灣美食好滋味。', `organizer`='經濟部商業司', `address`='星靚點花園飯店', `start_date`='2023-10-01 00:00:00', `end_date`='2023-10-31 00:00:00', `location`='臺北市文山區', `latitude`=24.992082, `longitude`=121.543578, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/8de9d6bc-8d2b-41ee-873d-fe1cbdaeaac8.jpg", "https://www.taiwan.net.tw/att/event/9283c849-40a3-4cf8-be14-0b871ae647db.jpg", "https://www.taiwan.net.tw/att/event/53c37a18-76fe-4ecb-8aef-66a348c295a9.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081048', '2023鐵路便當節', '鐵路便當節為交通部臺灣鐵路管理局以便當會友，擴大邀約國際業者參與，共同展現鐵道文化之美，以軟性的行銷策略與活動規劃，使國內民眾進一步了解臺灣鐵路管理局的多元服務，對外溝通則以「臺灣」為品牌，透過雙邊互動，由單點的在地美食推廣，拓展至全方位的國際觀光交流。除了鐵道美食及商品外，主題活動還有：「成就經典戲院」，邀請到劉克襄、陳朝強、郭佩怜、凌宗魁等多位各領域專家，一同從鐵道出發，賞析與分享屬於他們與鐵道的動人故事。「親子館」則以便當研習所，主題規劃DIY體驗活動，歡迎家長帶著小朋友一同了解臺鐵美食文化。「鐵道Ｘ跨界論壇」，在展期周末及週日將舉辦四場論壇，分別以美食、文創、旅遊、與設計四大主題，邀請到多位重量級講者齊聚一堂，與民眾一同探討分享屬於臺鐵的經典與未來。今年，鐵路便當節來到了第七屆，本次主題呼應鐵路便當x旅遊x文化 3大鐵道生活面向，提供大家邊吃邊玩的童趣想象，從人、鐵道、站點，延伸至城市之間的互動模式正在改變，點到點的距離，有無限的可能性。而移動的方式更引人深思，移動美好體驗正在被顛覆，味道在移動中被延續，從移動裡認識臺灣，從移動中發現樂趣。重新觀看鐵道、美食、旅行、記憶，探索移動的美好，讓我們約定走訪Wonderland on the move吧！', '交通部臺灣鐵路管理局', '北平西路3號', '2023-06-09 00:00:00', '2023-06-12 00:00:00', '臺北市中正區', 25.047814, 121.516948, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/55278f8d-c35f-4f98-bafc-83edf5bc0ae5.jpg", "https://www.taiwan.net.tw/att/event/1ec77785-708d-473d-92c1-f6a187a597ca.jpg", "https://www.taiwan.net.tw/att/event/eafd4241-9ea7-4233-b2fb-1dde7a07778f.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023鐵路便當節', `description`='鐵路便當節為交通部臺灣鐵路管理局以便當會友，擴大邀約國際業者參與，共同展現鐵道文化之美，以軟性的行銷策略與活動規劃，使國內民眾進一步了解臺灣鐵路管理局的多元服務，對外溝通則以「臺灣」為品牌，透過雙邊互動，由單點的在地美食推廣，拓展至全方位的國際觀光交流。除了鐵道美食及商品外，主題活動還有：「成就經典戲院」，邀請到劉克襄、陳朝強、郭佩怜、凌宗魁等多位各領域專家，一同從鐵道出發，賞析與分享屬於他們與鐵道的動人故事。「親子館」則以便當研習所，主題規劃DIY體驗活動，歡迎家長帶著小朋友一同了解臺鐵美食文化。「鐵道Ｘ跨界論壇」，在展期周末及週日將舉辦四場論壇，分別以美食、文創、旅遊、與設計四大主題，邀請到多位重量級講者齊聚一堂，與民眾一同探討分享屬於臺鐵的經典與未來。今年，鐵路便當節來到了第七屆，本次主題呼應鐵路便當x旅遊x文化 3大鐵道生活面向，提供大家邊吃邊玩的童趣想象，從人、鐵道、站點，延伸至城市之間的互動模式正在改變，點到點的距離，有無限的可能性。而移動的方式更引人深思，移動美好體驗正在被顛覆，味道在移動中被延續，從移動裡認識臺灣，從移動中發現樂趣。重新觀看鐵道、美食、旅行、記憶，探索移動的美好，讓我們約定走訪Wonderland on the move吧！', `organizer`='交通部臺灣鐵路管理局', `address`='北平西路3號', `start_date`='2023-06-09 00:00:00', `end_date`='2023-06-12 00:00:00', `location`='臺北市中正區', `latitude`=25.047814, `longitude`=121.516948, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/55278f8d-c35f-4f98-bafc-83edf5bc0ae5.jpg", "https://www.taiwan.net.tw/att/event/1ec77785-708d-473d-92c1-f6a187a597ca.jpg", "https://www.taiwan.net.tw/att/event/eafd4241-9ea7-4233-b2fb-1dde7a07778f.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081049', '2023阿里山花季-櫻與音的對話', '「櫻與音的對話」是宣告一年一度的阿里山花季正式開始，從3月至4月為期一個月的阿里山花季登場。花季開幕日辦「櫻與音的對話」開幕活動，主要為音樂、舞蹈或茶席等創意表演。遊樂區幅員遼闊，櫻花品系共有31種將近3000株，山櫻花、小櫻王唐實櫻、霧社櫻、櫻王染井吉野櫻、大島櫻、重瓣花系的關山櫻、普賢象櫻等等。', '農業部林業及自然保育署嘉義林區管理處', '阿里山國家森林遊樂區', '2023-03-10 00:00:00', '2023-04-10 00:00:00', '嘉義縣阿里山鄉', 23.511294, 120.80367, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/03da87e4-0fd7-49d5-bc91-062c64bfc6ae.jpg", "https://www.taiwan.net.tw/att/event/eafdcf16-b19d-4555-bec4-4476e0276ce3.jpg", "https://www.taiwan.net.tw/att/event/8c1c8a33-45d4-48df-a5a9-6501a9ecece8.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023阿里山花季-櫻與音的對話', `description`='「櫻與音的對話」是宣告一年一度的阿里山花季正式開始，從3月至4月為期一個月的阿里山花季登場。花季開幕日辦「櫻與音的對話」開幕活動，主要為音樂、舞蹈或茶席等創意表演。遊樂區幅員遼闊，櫻花品系共有31種將近3000株，山櫻花、小櫻王唐實櫻、霧社櫻、櫻王染井吉野櫻、大島櫻、重瓣花系的關山櫻、普賢象櫻等等。', `organizer`='農業部林業及自然保育署嘉義林區管理處', `address`='阿里山國家森林遊樂區', `start_date`='2023-03-10 00:00:00', `end_date`='2023-04-10 00:00:00', `location`='嘉義縣阿里山鄉', `latitude`=23.511294, `longitude`=120.80367, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/03da87e4-0fd7-49d5-bc91-062c64bfc6ae.jpg", "https://www.taiwan.net.tw/att/event/eafdcf16-b19d-4555-bec4-4476e0276ce3.jpg", "https://www.taiwan.net.tw/att/event/8c1c8a33-45d4-48df-a5a9-6501a9ecece8.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081050', '2023奔羊節', '清境農場溯自民國50年（西元1961年）農場草創已歷60寒暑，歷年來清境農場年度的生日慶典，係為緬懷前人創業之艱辛及展現今日之成果。每年固定於2月份規劃場慶活動，是全台唯一可體驗高山牧羊樂趣的活動。本次農場特有代表動物「柯莉黛綿羊」為活動主軸，活動場地在青青草原及觀山牧區，本次邀請十鼓擊樂團演奏鼓曲，緊接著上演特有綿羊剪毛秀，集合本場百餘隻綿羊，遊客在本場員工指導下於台14甲線上進行趕羊，體驗羊咩咩逛大街的樂趣。希望藉此獨樹一格之活動，呈現本場青春、活力、健康之休閒農場形象，活化清境地區內觀光產業及經濟發展，同時吸引更多遊客上山分享體驗。', '國軍退除役官兵輔導委員會清境農場', '台14甲線7.5K-9.8K', '2023-02-17 00:00:00', '2023-02-17 00:00:00', '南投縣仁愛鄉', 24.058774, 121.163546, '無資料', 'https://gosheep.chingjing.com.tw/', '["https://www.taiwan.net.tw/att/event/e0b1b0eb-1ac9-4e7c-bf5d-805242b0a85c.jpg", "https://www.taiwan.net.tw/att/event/8aebb1ef-07f6-4e54-be7f-e3844dc42f96.jpg", "https://www.taiwan.net.tw/att/event/dacd1274-36a0-4b62-a83a-be6df0d755eb.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023奔羊節', `description`='清境農場溯自民國50年（西元1961年）農場草創已歷60寒暑，歷年來清境農場年度的生日慶典，係為緬懷前人創業之艱辛及展現今日之成果。每年固定於2月份規劃場慶活動，是全台唯一可體驗高山牧羊樂趣的活動。本次農場特有代表動物「柯莉黛綿羊」為活動主軸，活動場地在青青草原及觀山牧區，本次邀請十鼓擊樂團演奏鼓曲，緊接著上演特有綿羊剪毛秀，集合本場百餘隻綿羊，遊客在本場員工指導下於台14甲線上進行趕羊，體驗羊咩咩逛大街的樂趣。希望藉此獨樹一格之活動，呈現本場青春、活力、健康之休閒農場形象，活化清境地區內觀光產業及經濟發展，同時吸引更多遊客上山分享體驗。', `organizer`='國軍退除役官兵輔導委員會清境農場', `address`='台14甲線7.5K-9.8K', `start_date`='2023-02-17 00:00:00', `end_date`='2023-02-17 00:00:00', `location`='南投縣仁愛鄉', `latitude`=24.058774, `longitude`=121.163546, `ticket_price`='無資料', `source_url`='https://gosheep.chingjing.com.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/e0b1b0eb-1ac9-4e7c-bf5d-805242b0a85c.jpg", "https://www.taiwan.net.tw/att/event/8aebb1ef-07f6-4e54-be7f-e3844dc42f96.jpg", "https://www.taiwan.net.tw/att/event/dacd1274-36a0-4b62-a83a-be6df0d755eb.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081051', '2023棲蘭越野節', '棲蘭林道是台灣最神秘的山徑之一，擁有珍稀的森林資源、豐富的生物多樣性和迷人的自然風光。在這裡舉辦的「棲蘭林道越野」，作為全臺首場官方推動之山林運動，賽道經過臺灣難得開放的宜蘭森林秘境！最大亮點－臺灣杉三姐妹，是臺灣高山森林的生態指標，若非參與此越野盛事，平時非常難有機會親眼目睹及體驗宜蘭棲蘭山中的檜木林世界級美景。賽事具有國際超馬總會IAU越野標籤認證，並且為國際越野跑協會ITRA越野積分賽事之一。賽程共分為三種：100公里、50公里、25公里，適合不同能力的跑者來參與，在宜蘭棲蘭的原始山林區裡盡情奔馳。路況穩定的林道，是可跑性相當高的賽道；但因有超過兩千公尺的攀爬、天候的驟變、以及險峻的路途，這場賽跑即使對最厲害的跑者來說也是個挑戰。跑者在野外自然環境中享受跑步的樂趣，不但讓跑步活動更健康，也讓跑者更加認識臺灣豐富的自然資源與山林美景，更藉此了解保護山林生態完整性的重要。這場賽事將有助於推展臺灣超級馬拉松及越野跑運動與世界接軌，可推薦國際跑者來臺深度旅遊，促進宜蘭當地觀光產業發展，增加國際曝光度，持續向國際推廣臺灣山林之美。&quot;', '社團法人中華民國超級馬拉松運動協會', '力麗馬告生態園區（棲蘭、明池、神木園）', '2023-09-16 00:00:00', '2023-09-16 00:00:00', '宜蘭縣大同鄉', 24.653426, 121.471379, '無資料', 'http://www.ctau.org.tw/news/2023-09-16-%E5%8F%B0%E7%81%A3%E6%A3%B2%E8%98%AD%E6%9E%97%E9%81%93%E8%B6%8A%E9%87%8E/', '["https://www.taiwan.net.tw/att/event/aada9786-3e92-42c4-bf4b-e25afccabe84.jpg", "https://www.taiwan.net.tw/att/event/aac41c0d-bd6e-445b-b720-28d528c5ab77.jpg", "https://www.taiwan.net.tw/att/event/688400eb-db9d-407a-8492-54d81b1e371b.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023棲蘭越野節', `description`='棲蘭林道是台灣最神秘的山徑之一，擁有珍稀的森林資源、豐富的生物多樣性和迷人的自然風光。在這裡舉辦的「棲蘭林道越野」，作為全臺首場官方推動之山林運動，賽道經過臺灣難得開放的宜蘭森林秘境！最大亮點－臺灣杉三姐妹，是臺灣高山森林的生態指標，若非參與此越野盛事，平時非常難有機會親眼目睹及體驗宜蘭棲蘭山中的檜木林世界級美景。賽事具有國際超馬總會IAU越野標籤認證，並且為國際越野跑協會ITRA越野積分賽事之一。賽程共分為三種：100公里、50公里、25公里，適合不同能力的跑者來參與，在宜蘭棲蘭的原始山林區裡盡情奔馳。路況穩定的林道，是可跑性相當高的賽道；但因有超過兩千公尺的攀爬、天候的驟變、以及險峻的路途，這場賽跑即使對最厲害的跑者來說也是個挑戰。跑者在野外自然環境中享受跑步的樂趣，不但讓跑步活動更健康，也讓跑者更加認識臺灣豐富的自然資源與山林美景，更藉此了解保護山林生態完整性的重要。這場賽事將有助於推展臺灣超級馬拉松及越野跑運動與世界接軌，可推薦國際跑者來臺深度旅遊，促進宜蘭當地觀光產業發展，增加國際曝光度，持續向國際推廣臺灣山林之美。&quot;', `organizer`='社團法人中華民國超級馬拉松運動協會', `address`='力麗馬告生態園區（棲蘭、明池、神木園）', `start_date`='2023-09-16 00:00:00', `end_date`='2023-09-16 00:00:00', `location`='宜蘭縣大同鄉', `latitude`=24.653426, `longitude`=121.471379, `ticket_price`='無資料', `source_url`='http://www.ctau.org.tw/news/2023-09-16-%E5%8F%B0%E7%81%A3%E6%A3%B2%E8%98%AD%E6%9E%97%E9%81%93%E8%B6%8A%E9%87%8E/', `image_url`='["https://www.taiwan.net.tw/att/event/aada9786-3e92-42c4-bf4b-e25afccabe84.jpg", "https://www.taiwan.net.tw/att/event/aac41c0d-bd6e-445b-b720-28d528c5ab77.jpg", "https://www.taiwan.net.tw/att/event/688400eb-db9d-407a-8492-54d81b1e371b.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081052', '2023武陵農場櫻花季', '武陵農場海拔高度位於1,740至2,200公尺間，自民國82年（西元1993年）開始種植櫻花樹至今約20餘載，約植有1萬6千餘株，被譽為全台賞櫻首選勝地，近年來因撫育得當，每年1至2月櫻花季期間一片粉白花海花況甚佳，在遊客主動透過部落格、臉書及網路等傳送下廣受媒體關注，於花季期間來場採訪報導，吸引數十萬民眾蜂擁上山賞花。', '國軍退除役官兵輔導委員會武陵農場', '武陵農場', '2023-02-07 00:00:00', '2023-02-28 00:00:00', '臺中市和平區', 24.352358, 121.308597, '無資料', 'https://www.wuling-farm.com.tw/tw/index.php', '["https://www.taiwan.net.tw/att/event/e78f612e-a1dc-4c13-a5e7-2c1303508023.jpg", "https://www.taiwan.net.tw/att/event/e256e065-584f-4a07-affb-1c150abbf31e.jpg", "https://www.taiwan.net.tw/att/event/d3622ea3-4564-463c-8cc8-bc781d8d77d7.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023武陵農場櫻花季', `description`='武陵農場海拔高度位於1,740至2,200公尺間，自民國82年（西元1993年）開始種植櫻花樹至今約20餘載，約植有1萬6千餘株，被譽為全台賞櫻首選勝地，近年來因撫育得當，每年1至2月櫻花季期間一片粉白花海花況甚佳，在遊客主動透過部落格、臉書及網路等傳送下廣受媒體關注，於花季期間來場採訪報導，吸引數十萬民眾蜂擁上山賞花。', `organizer`='國軍退除役官兵輔導委員會武陵農場', `address`='武陵農場', `start_date`='2023-02-07 00:00:00', `end_date`='2023-02-28 00:00:00', `location`='臺中市和平區', `latitude`=24.352358, `longitude`=121.308597, `ticket_price`='無資料', `source_url`='https://www.wuling-farm.com.tw/tw/index.php', `image_url`='["https://www.taiwan.net.tw/att/event/e78f612e-a1dc-4c13-a5e7-2c1303508023.jpg", "https://www.taiwan.net.tw/att/event/e256e065-584f-4a07-affb-1c150abbf31e.jpg", "https://www.taiwan.net.tw/att/event/d3622ea3-4564-463c-8cc8-bc781d8d77d7.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081053', '2023 Taiwan PASIWALI Festival原住民族國際音樂節', 'Taiwan PASIWALI Festival &mdash; 一場長達數十萬公里的南島之舟部落音樂旅程。PASIWALI是台灣原住民族阿美族語，往東方的意思，東方是太陽升起的地方，台灣的東方也是孕育許多原住民族群的地方。活動期間邀請臺灣原住民歌手樂團表演，亦與當地部落、店家合作遊程規劃，音樂節期間亦會有特色文創市集攤位一同響應盛事。', '原住民族委員會', '華泰路300號', '2023-11-18 00:00:00', '2023-11-19 00:00:00', '臺東縣臺東市', 22.763418, 121.158875, '無資料', 'https://taiwanpasiwalifestival.com/', '["https://www.taiwan.net.tw/att/event/b2c77ede-8bb4-4b02-9695-b8f02517fc4e.jpg", "https://www.taiwan.net.tw/att/event/c971bfdf-932c-4f53-a2fe-532004b35044.jpg", "https://www.taiwan.net.tw/att/event/022f8c5a-917f-4673-8d8f-2585075e1db3.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023 Taiwan PASIWALI Festival原住民族國際音樂節', `description`='Taiwan PASIWALI Festival &mdash; 一場長達數十萬公里的南島之舟部落音樂旅程。PASIWALI是台灣原住民族阿美族語，往東方的意思，東方是太陽升起的地方，台灣的東方也是孕育許多原住民族群的地方。活動期間邀請臺灣原住民歌手樂團表演，亦與當地部落、店家合作遊程規劃，音樂節期間亦會有特色文創市集攤位一同響應盛事。', `organizer`='原住民族委員會', `address`='華泰路300號', `start_date`='2023-11-18 00:00:00', `end_date`='2023-11-19 00:00:00', `location`='臺東縣臺東市', `latitude`=22.763418, `longitude`=121.158875, `ticket_price`='無資料', `source_url`='https://taiwanpasiwalifestival.com/', `image_url`='["https://www.taiwan.net.tw/att/event/b2c77ede-8bb4-4b02-9695-b8f02517fc4e.jpg", "https://www.taiwan.net.tw/att/event/c971bfdf-932c-4f53-a2fe-532004b35044.jpg", "https://www.taiwan.net.tw/att/event/022f8c5a-917f-4673-8d8f-2585075e1db3.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081054', '2023世界客家博覽會', '「2023 世界客家博覽會」將是全球首次以客家文化為主題的國際性文化展會活動，融合世界在地客家文化，呈現文化多樣的獨特性，透過博覽會傳揚客家文化，並以設計導入向全球及國人推廣客庄建設成果，結合近年整備完成之客庄歷史場域，並邀請世界各地客家社團與臺灣客庄縣市共同參展，讓世界客家博覽會作為臺灣客家文化運動新起點，以客家文化為核心，與世界對話產生共鳴，讓國內外民眾看到不同的客家文化。', '客家委員會、桃園市政府', '高鐵特定區（主展場）', '2023-08-11 00:00:00', '2023-10-15 00:00:00', '桃園市中壢區', 25.011227, 121.217652, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2023世界客家博覽會', `description`='「2023 世界客家博覽會」將是全球首次以客家文化為主題的國際性文化展會活動，融合世界在地客家文化，呈現文化多樣的獨特性，透過博覽會傳揚客家文化，並以設計導入向全球及國人推廣客庄建設成果，結合近年整備完成之客庄歷史場域，並邀請世界各地客家社團與臺灣客庄縣市共同參展，讓世界客家博覽會作為臺灣客家文化運動新起點，以客家文化為核心，與世界對話產生共鳴，讓國內外民眾看到不同的客家文化。', `organizer`='客家委員會、桃園市政府', `address`='高鐵特定區（主展場）', `start_date`='2023-08-11 00:00:00', `end_date`='2023-10-15 00:00:00', `location`='桃園市中壢區', `latitude`=25.011227, `longitude`=121.217652, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081055', '2023六堆秋收祭系列活動', '客家人利用「春祈、夏耘、秋收、冬藏」大自然時序變化，來調整一年作息的生活方式，是代代相傳的優美文化，而每年十月底十一月初正是豐收的時節，各地均會酬神以慶祝一年一度秋收祭的到來。為貼近民眾生活及帶動六堆客家地區觀光，今年秋收祭特以「親近自然」為主題發想，規劃一系列「謝天、迎秋神」、「千人開幕式」、「彩妝遊園活動」、「庄頭藝文」、「秋收主題體驗」、「食福宴暨聯歡晚會」等豐富活動，將客庄秋收的歡愉與故事，透過各項活動傳遞客家多元的文化面貌以表達我們對天地最深的敬意與情感。', '客家委員會客家文化發展中心', '信義路588號', '2023-11-04 00:00:00', '2023-11-26 00:00:00', '屏東縣內埔鄉', 22.658418, 120.558815, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/b155619f-abe5-47c6-ae38-735046c86ee0.jpg", "https://www.taiwan.net.tw/att/event/497eba92-90b0-4a04-9a13-cbce40cfedee.jpg", "https://www.taiwan.net.tw/att/event/dc577834-86d1-4828-9fa2-01847e18b4ac.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023六堆秋收祭系列活動', `description`='客家人利用「春祈、夏耘、秋收、冬藏」大自然時序變化，來調整一年作息的生活方式，是代代相傳的優美文化，而每年十月底十一月初正是豐收的時節，各地均會酬神以慶祝一年一度秋收祭的到來。為貼近民眾生活及帶動六堆客家地區觀光，今年秋收祭特以「親近自然」為主題發想，規劃一系列「謝天、迎秋神」、「千人開幕式」、「彩妝遊園活動」、「庄頭藝文」、「秋收主題體驗」、「食福宴暨聯歡晚會」等豐富活動，將客庄秋收的歡愉與故事，透過各項活動傳遞客家多元的文化面貌以表達我們對天地最深的敬意與情感。', `organizer`='客家委員會客家文化發展中心', `address`='信義路588號', `start_date`='2023-11-04 00:00:00', `end_date`='2023-11-26 00:00:00', `location`='屏東縣內埔鄉', `latitude`=22.658418, `longitude`=120.558815, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/b155619f-abe5-47c6-ae38-735046c86ee0.jpg", "https://www.taiwan.net.tw/att/event/497eba92-90b0-4a04-9a13-cbce40cfedee.jpg", "https://www.taiwan.net.tw/att/event/dc577834-86d1-4828-9fa2-01847e18b4ac.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081057', '2023草嶺古道芒花季', '為讓遊客欣賞大片芒花壯闊盛開之景，感受草嶺古道那段跨越百年山海時光長廊的記憶，本處自民國91年（西元2002年）開始舉辦「草嶺古道芒花季活動」，迄至民國110年（西元2021年）已推廣近20年，近年來已成為東北角地區觀光旅遊品牌活動，每年度總吸引約8萬人次遊客前往欣賞滿山芒花搖曳的迷人風采，今年度的芒花盛宴，亦將持續以輕鬆、詼諧的方式推廣，帶領大家一同踏上擁有兩百年歷史的古道，典藏古道秋芒美麗的記憶。', '交通部觀光署東北角及宜蘭海岸國家風景區管理處', '草嶺古道', '2023-11-04 00:00:00', '2023-11-26 00:00:00', '新北市貢寮區', 24.990007, 121.925372, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/14f6e358-ef5a-4af2-8032-a00328906402.jpg", "https://www.taiwan.net.tw/att/event/c14182f7-003e-4572-88e7-4a427c288242.jpg", "https://www.taiwan.net.tw/att/event/5663bd9f-fd6b-44a2-9079-ee8bef0f1309.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023草嶺古道芒花季', `description`='為讓遊客欣賞大片芒花壯闊盛開之景，感受草嶺古道那段跨越百年山海時光長廊的記憶，本處自民國91年（西元2002年）開始舉辦「草嶺古道芒花季活動」，迄至民國110年（西元2021年）已推廣近20年，近年來已成為東北角地區觀光旅遊品牌活動，每年度總吸引約8萬人次遊客前往欣賞滿山芒花搖曳的迷人風采，今年度的芒花盛宴，亦將持續以輕鬆、詼諧的方式推廣，帶領大家一同踏上擁有兩百年歷史的古道，典藏古道秋芒美麗的記憶。', `organizer`='交通部觀光署東北角及宜蘭海岸國家風景區管理處', `address`='草嶺古道', `start_date`='2023-11-04 00:00:00', `end_date`='2023-11-26 00:00:00', `location`='新北市貢寮區', `latitude`=24.990007, `longitude`=121.925372, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/14f6e358-ef5a-4af2-8032-a00328906402.jpg", "https://www.taiwan.net.tw/att/event/c14182f7-003e-4572-88e7-4a427c288242.jpg", "https://www.taiwan.net.tw/att/event/5663bd9f-fd6b-44a2-9079-ee8bef0f1309.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081058', '2023-2024東北角迎曙光系列活動', '112年1月1日凌晨(5時起)，透過節目儀式及表演，與民眾迎接2024龜山朝日第一道光芒，共同過新年。', '交通部觀光署東北角及宜蘭海岸國家風景區管理處', '外澳沙灘', '2023-12-31 00:00:00', '2024-01-01 00:00:00', '宜蘭縣頭城鎮', 24.87781, 121.843071, '無資料', 'https://www.necoast-nsa.gov.tw/', '["https://www.taiwan.net.tw/att/event/a9f2e621-9c59-48ed-be1c-d8b9ddf0869e.jpg", "https://www.taiwan.net.tw/att/event/152b24aa-f023-4bfb-a144-e6d010130268.jpg", "https://www.taiwan.net.tw/att/event/0cf36704-4887-42bc-b4c2-ccf846d1bd4c.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023-2024東北角迎曙光系列活動', `description`='112年1月1日凌晨(5時起)，透過節目儀式及表演，與民眾迎接2024龜山朝日第一道光芒，共同過新年。', `organizer`='交通部觀光署東北角及宜蘭海岸國家風景區管理處', `address`='外澳沙灘', `start_date`='2023-12-31 00:00:00', `end_date`='2024-01-01 00:00:00', `location`='宜蘭縣頭城鎮', `latitude`=24.87781, `longitude`=121.843071, `ticket_price`='無資料', `source_url`='https://www.necoast-nsa.gov.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/a9f2e621-9c59-48ed-be1c-d8b9ddf0869e.jpg", "https://www.taiwan.net.tw/att/event/152b24aa-f023-4bfb-a144-e6d010130268.jpg", "https://www.taiwan.net.tw/att/event/0cf36704-4887-42bc-b4c2-ccf846d1bd4c.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081059', '2023東海岸運動觀光活動', '東部海岸國家風景區北起花蓮溪口，南迄小野柳風景特定區，擁有長達168公里的海岸線，還包括秀姑巒溪瑞穗以下泛舟觀光地區，以及孤懸外海的綠島，除擁有絕美的山海景色外，台11線多為坡度變化較小的道路，適合做為長距離路跑旅遊路線。此外，秀姑巒溪泛舟活動是台灣泛舟活動的第一品牌也是最佳、最早的泛舟河道，在東部海岸國家風景區管理處與業者地方人士的積極推動下，每年4月至10月的秀姑巒溪泛舟活動已蔚為風行並具國際規模。因此，東部海岸是從事路跑、自行車及泛舟等各項運動之最佳地點。', '交通部觀光署東部海岸國家風景區管理處', '秀姑巒溪遊客中心', '2023-05-07 00:00:00', '2023-06-11 00:00:00', '花蓮縣瑞穗鄉', 23.487892, 121.401078, '無資料', 'http://eastcoast-sport.ncom.tw/', '["https://www.taiwan.net.tw/att/event/c85948a5-94d2-4b1b-97c7-c95d55245cb4.jpg", "https://www.taiwan.net.tw/att/event/35a38725-7728-49fc-978c-22bcf8dbec80.jpg", "https://www.taiwan.net.tw/att/event/f55813a1-30a2-4470-a07b-f2fd9b780c5a.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023東海岸運動觀光活動', `description`='東部海岸國家風景區北起花蓮溪口，南迄小野柳風景特定區，擁有長達168公里的海岸線，還包括秀姑巒溪瑞穗以下泛舟觀光地區，以及孤懸外海的綠島，除擁有絕美的山海景色外，台11線多為坡度變化較小的道路，適合做為長距離路跑旅遊路線。此外，秀姑巒溪泛舟活動是台灣泛舟活動的第一品牌也是最佳、最早的泛舟河道，在東部海岸國家風景區管理處與業者地方人士的積極推動下，每年4月至10月的秀姑巒溪泛舟活動已蔚為風行並具國際規模。因此，東部海岸是從事路跑、自行車及泛舟等各項運動之最佳地點。', `organizer`='交通部觀光署東部海岸國家風景區管理處', `address`='秀姑巒溪遊客中心', `start_date`='2023-05-07 00:00:00', `end_date`='2023-06-11 00:00:00', `location`='花蓮縣瑞穗鄉', `latitude`=23.487892, `longitude`=121.401078, `ticket_price`='無資料', `source_url`='http://eastcoast-sport.ncom.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/c85948a5-94d2-4b1b-97c7-c95d55245cb4.jpg", "https://www.taiwan.net.tw/att/event/35a38725-7728-49fc-978c-22bcf8dbec80.jpg", "https://www.taiwan.net.tw/att/event/f55813a1-30a2-4470-a07b-f2fd9b780c5a.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081060', '2023縱谷原遊會 部落食樂園', '「縱谷原遊會&mdash;部落食樂園」是結合在地部落體驗及行銷花東縱谷原住民多元多美食為主體的活動，亦為全國首創且規模最大部落食物體驗樂園。交通部觀光署花東縱谷國家風景區管理處自民國107年（西元2018年）起推動部落旅遊品牌「縱谷原遊會」，以「部落食樂園」為主軸吸引遊客，匯聚過往三年培育之部落以樂園形式呈現部落特色，以飲食作為接觸部落文化的結點，從部落野外求生技能到居家生活，一次集結部落美食、美學、音樂及特色工藝，帶遊客認識物產豐饒的花東縱谷，同時讓縱谷間各部落在觀光產業上能彼此交流。', '交通部觀光署花東縱谷國家風景區管理處', '羅山遊客中心', '2023-08-26 00:00:00', '2023-08-27 00:00:00', '花蓮縣富里鄉', 23.20207, 121.274941, '無資料', 'https://www.erv-nsa.gov.tw/', '["https://www.taiwan.net.tw/att/event/71931bb3-9652-445f-8f62-3fd3735e8452.jpg", "https://www.taiwan.net.tw/att/event/96fd2701-181a-4271-ac5a-24c20b6a740b.jpg", "https://www.taiwan.net.tw/att/event/c957353d-6e8d-4782-9fa6-4f1de3a2484a.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023縱谷原遊會 部落食樂園', `description`='「縱谷原遊會&mdash;部落食樂園」是結合在地部落體驗及行銷花東縱谷原住民多元多美食為主體的活動，亦為全國首創且規模最大部落食物體驗樂園。交通部觀光署花東縱谷國家風景區管理處自民國107年（西元2018年）起推動部落旅遊品牌「縱谷原遊會」，以「部落食樂園」為主軸吸引遊客，匯聚過往三年培育之部落以樂園形式呈現部落特色，以飲食作為接觸部落文化的結點，從部落野外求生技能到居家生活，一次集結部落美食、美學、音樂及特色工藝，帶遊客認識物產豐饒的花東縱谷，同時讓縱谷間各部落在觀光產業上能彼此交流。', `organizer`='交通部觀光署花東縱谷國家風景區管理處', `address`='羅山遊客中心', `start_date`='2023-08-26 00:00:00', `end_date`='2023-08-27 00:00:00', `location`='花蓮縣富里鄉', `latitude`=23.20207, `longitude`=121.274941, `ticket_price`='無資料', `source_url`='https://www.erv-nsa.gov.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/71931bb3-9652-445f-8f62-3fd3735e8452.jpg", "https://www.taiwan.net.tw/att/event/96fd2701-181a-4271-ac5a-24c20b6a740b.jpg", "https://www.taiwan.net.tw/att/event/c957353d-6e8d-4782-9fa6-4f1de3a2484a.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081061', '2023馬祖馬拉松', '馬祖是台灣的離島，與國內馬拉松場地比較，其地形高低起伏較大，馬祖國際馬拉松為一挑戰型賽事，為配合天候，馬祖馬拉松訂於每年11月舉辦，希望藉由當地特色聚落文化、戰地景觀及閩東風俗民情，提高運動觀光能見度，因地形因素其相對挑戰難度亦較高，對於喜愛從事挑戰型路跑運動的民眾而言，相對具有很高的挑戰性。歡迎各位喜歡運動及旅遊的好朋友們用跑步感受不一樣的馬祖之美！', '連江縣政府、交通部觀光署馬祖國家風景區管理處', '福澳運動場', '2023-11-04 00:00:00', '2023-11-04 00:00:00', '連江縣南竿鄉', 26.159415, 119.944059, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/2c2808b0-d8ba-46e0-9a44-3370a7f04d65.jpg", "https://www.taiwan.net.tw/att/event/ac4eb5fd-5360-4b8d-9bcc-bf40f67d9f98.jpg", "https://www.taiwan.net.tw/att/event/3d696aef-aac4-4bcb-b095-f1629ba7bf67.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023馬祖馬拉松', `description`='馬祖是台灣的離島，與國內馬拉松場地比較，其地形高低起伏較大，馬祖國際馬拉松為一挑戰型賽事，為配合天候，馬祖馬拉松訂於每年11月舉辦，希望藉由當地特色聚落文化、戰地景觀及閩東風俗民情，提高運動觀光能見度，因地形因素其相對挑戰難度亦較高，對於喜愛從事挑戰型路跑運動的民眾而言，相對具有很高的挑戰性。歡迎各位喜歡運動及旅遊的好朋友們用跑步感受不一樣的馬祖之美！', `organizer`='連江縣政府、交通部觀光署馬祖國家風景區管理處', `address`='福澳運動場', `start_date`='2023-11-04 00:00:00', `end_date`='2023-11-04 00:00:00', `location`='連江縣南竿鄉', `latitude`=26.159415, `longitude`=119.944059, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/2c2808b0-d8ba-46e0-9a44-3370a7f04d65.jpg", "https://www.taiwan.net.tw/att/event/ac4eb5fd-5360-4b8d-9bcc-bf40f67d9f98.jpg", "https://www.taiwan.net.tw/att/event/3d696aef-aac4-4bcb-b095-f1629ba7bf67.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081062', '2023觀音觀鷹-樂活行腳系列活動', '觀音山位於淡水河西側，屬大屯火山群，火山噴發形成十八座連峰，形若一尊躺臥觀音菩薩，最高峰硬漢嶺海拔616公尺，擁有360度環狀視野，可眺望大屯山群峰、淡水河口、關渡平原及台北盆地，更是北臺灣日猛禽重要棲身地，山區森林茂密，物種豐富，登山步道系統完備，為大臺北近郊知名登山及賞鷹地點，每年吸引數十萬遊客與登山客造訪，極具生態旅遊發展潛力，為持續形塑觀音山觀光魅力，111至112年將以「生態旅遊」為推廣主軸，結合猛禽過境、步道生態、地方特產（綠竹筍季、文旦柚季）等觀光資源，打造觀音山成為北臺灣生態樂園，提升當地觀光產值。', '交通部觀光署北海岸及觀音山國家風景區管理處', '觀音山遊客中心', '2023-04-29 00:00:00', '2023-10-31 00:00:00', '新北市五股區', 25.129446, 121.418201, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/7683c2e0-514a-4db9-9737-47203171c829.JPG", "https://www.taiwan.net.tw/att/event/c39f58d1-a906-4424-bd7f-1d13693719df.JPG", "https://www.taiwan.net.tw/att/event/ab0d195b-b590-4a8e-9b02-d9e5450c4af5.JPG"]') ON DUPLICATE KEY UPDATE `activity_name`='2023觀音觀鷹-樂活行腳系列活動', `description`='觀音山位於淡水河西側，屬大屯火山群，火山噴發形成十八座連峰，形若一尊躺臥觀音菩薩，最高峰硬漢嶺海拔616公尺，擁有360度環狀視野，可眺望大屯山群峰、淡水河口、關渡平原及台北盆地，更是北臺灣日猛禽重要棲身地，山區森林茂密，物種豐富，登山步道系統完備，為大臺北近郊知名登山及賞鷹地點，每年吸引數十萬遊客與登山客造訪，極具生態旅遊發展潛力，為持續形塑觀音山觀光魅力，111至112年將以「生態旅遊」為推廣主軸，結合猛禽過境、步道生態、地方特產（綠竹筍季、文旦柚季）等觀光資源，打造觀音山成為北臺灣生態樂園，提升當地觀光產值。', `organizer`='交通部觀光署北海岸及觀音山國家風景區管理處', `address`='觀音山遊客中心', `start_date`='2023-04-29 00:00:00', `end_date`='2023-10-31 00:00:00', `location`='新北市五股區', `latitude`=25.129446, `longitude`=121.418201, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/7683c2e0-514a-4db9-9737-47203171c829.JPG", "https://www.taiwan.net.tw/att/event/c39f58d1-a906-4424-bd7f-1d13693719df.JPG", "https://www.taiwan.net.tw/att/event/ab0d195b-b590-4a8e-9b02-d9e5450c4af5.JPG"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081063', '2023島嶼生活節', '和平島為北台灣最早躍進世界舞台的島嶼，從最早的平埔族原住民、西班牙人、荷蘭人後來的琉球王國人、日本人、福州人等，這塊土地有著豐厚的故事，但隨著時間流動，這些文化歷史及過去的美好友誼逐漸被遺忘，和平島公園使用音樂、美食、藝術創作等來包裝文化、歷史等對於一般遊客來說較為生硬的議題。一年一度提供回憶重塑的有趣活動，邀請曾經在這片土地生活的各國人們，一起在這場無國界的美學派對中發掘更多美好生活，在這裡展演過去、現在、未來我們共享的生活樣貌。島嶼生活節打破疆界，台灣的在地文化就是經由這幾百年來不同國家文化的揉合、衝突、再轉化，在島嶼生活結節不只做跨域跨國際合作、更希望讓那條國家間的界線變得透明，並且讓台灣創作者能在這裡被看見，醞釀更豐富的「台灣永續活動品牌」的能量！', '交通部觀光署北海岸及觀音山國家風景區管理處', '和平島公園', '2023-07-15 00:00:00', '2023-09-30 00:00:00', '基隆市中正區', 25.160629, 121.76384, '無資料', 'https://www.hpigeopark.org/', '["https://www.taiwan.net.tw/att/event/7e8a8fad-0c80-4fee-8dce-7f3fcbeec6d7.jpg", "https://www.taiwan.net.tw/att/event/82d96418-d9dd-4261-ac17-9a270989fb68.jpg", "https://www.taiwan.net.tw/att/event/1aff6648-c9ca-4da8-a47e-99ba8912b2d6.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023島嶼生活節', `description`='和平島為北台灣最早躍進世界舞台的島嶼，從最早的平埔族原住民、西班牙人、荷蘭人後來的琉球王國人、日本人、福州人等，這塊土地有著豐厚的故事，但隨著時間流動，這些文化歷史及過去的美好友誼逐漸被遺忘，和平島公園使用音樂、美食、藝術創作等來包裝文化、歷史等對於一般遊客來說較為生硬的議題。一年一度提供回憶重塑的有趣活動，邀請曾經在這片土地生活的各國人們，一起在這場無國界的美學派對中發掘更多美好生活，在這裡展演過去、現在、未來我們共享的生活樣貌。島嶼生活節打破疆界，台灣的在地文化就是經由這幾百年來不同國家文化的揉合、衝突、再轉化，在島嶼生活結節不只做跨域跨國際合作、更希望讓那條國家間的界線變得透明，並且讓台灣創作者能在這裡被看見，醞釀更豐富的「台灣永續活動品牌」的能量！', `organizer`='交通部觀光署北海岸及觀音山國家風景區管理處', `address`='和平島公園', `start_date`='2023-07-15 00:00:00', `end_date`='2023-09-30 00:00:00', `location`='基隆市中正區', `latitude`=25.160629, `longitude`=121.76384, `ticket_price`='無資料', `source_url`='https://www.hpigeopark.org/', `image_url`='["https://www.taiwan.net.tw/att/event/7e8a8fad-0c80-4fee-8dce-7f3fcbeec6d7.jpg", "https://www.taiwan.net.tw/att/event/82d96418-d9dd-4261-ac17-9a270989fb68.jpg", "https://www.taiwan.net.tw/att/event/1aff6648-c9ca-4da8-a47e-99ba8912b2d6.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081064', '2023南庄花卉節', '南庄鄉為國家級觀光旅遊休閒勝地，有「花園山城」美稱，民國105年（西元2016年）獲選為國際慢城，列為國內4座國際慢城之一，人稱「好山好水在南庄」。南庄因環境氣候自然天成，適合花卉等農作物生長，近年來則逐漸興起休閒農業，設立許多特色民宿，極適合發展觀光休閒產業。本處首年於民國108年（西元2019年）舉辦南庄恆浪漫繡球花節打響南庄花卉節的品牌知名度，以代表希望、忠貞、圓滿的『繡球花』為主軸，打造村村有花卉之意象;第二年融入其他花卉為輔，擴大舉辦，營造南庄百花巷弄，建立「南庄花卉節」的品牌意涵，讓旅遊與在地資源深度連結，營造「最美的南庄」，奠定活動品牌價值。第三年透過結合地景的裝置藝術，在疫情依舊肆虐的時代，傳遞國內在地旅遊能量，並且形塑地區生態觀光特色。並邀請知名國內藝術家至此設置裝置作品，結合在地地景特色，透過多元觀點與特色媒材，挖掘與展現花卉藝術的可能性，吸引外地人潮至的南庄與獅頭山地區時，也提升鄉鎮城市的品牌包裝形象。經過三年度舉辦，南庄鄉民紛以南庄花卉節為榮，產生自發性行銷、維護花卉等感動行為，活動結束後，持續由協會、業者、居民線地認養，活動不只是煙火式綻放美麗，而是由地方接力繼續呵護，南庄村民用愛讓花卉得以運用另一種方式延續生命力，達到永續綠美化的環境循環價值，奠定強大鏈結力。', '交通部觀光署參山國家風景區管理處', '南庄鄉', '2023-04-29 00:00:00', '2023-05-28 00:00:00', '苗栗縣南庄鄉', 24.595344, 121.000355, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/656e8d19-e2f2-43dd-ab8c-c5095c0a29c5.jpg", "https://www.taiwan.net.tw/att/event/99857e1f-2f68-49c1-b359-c311d7923068.jpg", "https://www.taiwan.net.tw/att/event/787e27b1-0497-4ac7-a430-e06174ca2a6c.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023南庄花卉節', `description`='南庄鄉為國家級觀光旅遊休閒勝地，有「花園山城」美稱，民國105年（西元2016年）獲選為國際慢城，列為國內4座國際慢城之一，人稱「好山好水在南庄」。南庄因環境氣候自然天成，適合花卉等農作物生長，近年來則逐漸興起休閒農業，設立許多特色民宿，極適合發展觀光休閒產業。本處首年於民國108年（西元2019年）舉辦南庄恆浪漫繡球花節打響南庄花卉節的品牌知名度，以代表希望、忠貞、圓滿的『繡球花』為主軸，打造村村有花卉之意象;第二年融入其他花卉為輔，擴大舉辦，營造南庄百花巷弄，建立「南庄花卉節」的品牌意涵，讓旅遊與在地資源深度連結，營造「最美的南庄」，奠定活動品牌價值。第三年透過結合地景的裝置藝術，在疫情依舊肆虐的時代，傳遞國內在地旅遊能量，並且形塑地區生態觀光特色。並邀請知名國內藝術家至此設置裝置作品，結合在地地景特色，透過多元觀點與特色媒材，挖掘與展現花卉藝術的可能性，吸引外地人潮至的南庄與獅頭山地區時，也提升鄉鎮城市的品牌包裝形象。經過三年度舉辦，南庄鄉民紛以南庄花卉節為榮，產生自發性行銷、維護花卉等感動行為，活動結束後，持續由協會、業者、居民線地認養，活動不只是煙火式綻放美麗，而是由地方接力繼續呵護，南庄村民用愛讓花卉得以運用另一種方式延續生命力，達到永續綠美化的環境循環價值，奠定強大鏈結力。', `organizer`='交通部觀光署參山國家風景區管理處', `address`='南庄鄉', `start_date`='2023-04-29 00:00:00', `end_date`='2023-05-28 00:00:00', `location`='苗栗縣南庄鄉', `latitude`=24.595344, `longitude`=121.000355, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/656e8d19-e2f2-43dd-ab8c-c5095c0a29c5.jpg", "https://www.taiwan.net.tw/att/event/99857e1f-2f68-49c1-b359-c311d7923068.jpg", "https://www.taiwan.net.tw/att/event/787e27b1-0497-4ac7-a430-e06174ca2a6c.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081065', '2023阿里山四季茶旅活動', '阿里山四季茶旅活動係藉由培訓在地茶旅達人、茶旅體驗環境氛圍營造及行銷推廣活動，推廣阿里山好茶及多元品茗情境；四季茶會活動以二十四節氣為主題，結合在地茶旅達人司茶，伴著阿里山自然地景風貌（如：櫻花、螢火蟲、瀑布、竹林、森林、黃頭鷺、紫藤、雲瀑等），山林芬多精，品茗阿里山優質茶湯滋味；本計畫並將旅遊動線串連到產地製茶體驗、旅宿及品茗，開發多元茶品、茶輕食、茶文創商品，並搭配本處阿里山日產業展及國際旅展等聯合行銷茶旅遊程，提供國人與國際人士預約體驗深度茶之旅，形塑專屬阿里山茶文化體驗觀光品牌，促進阿里山茶文化、生態、產業等在地創生及深耕，活絡阿里山在地觀光產業，創造阿里山茶旅觀光產業整體效益與產值。    春季茶會：2023.04.22 - 2023.04.23    夏季茶會：2023.07.22    秋季茶會：2023.09.23    冬季茶會：2023.12.17-->', '交通部觀光署阿里山國家風景區管理處', '圓潭自然生態園區', '2023-04-01 00:00:00', '2023-12-31 00:00:00', '嘉義縣梅山鄉', 23.528943, 120.659331, '無資料', 'https://www.ali-nsa.net/zh-tw/event/calendardetail/2824', '["https://www.taiwan.net.tw/att/event/1865b1a1-b85c-4284-8282-ea6935693344.jpg", "https://www.taiwan.net.tw/att/event/37e02b28-cedd-48a0-a90b-4f7294ed23ee.jpg", "https://www.taiwan.net.tw/att/event/61e78c8c-d3b0-44e2-878c-28880dff071c.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023阿里山四季茶旅活動', `description`='阿里山四季茶旅活動係藉由培訓在地茶旅達人、茶旅體驗環境氛圍營造及行銷推廣活動，推廣阿里山好茶及多元品茗情境；四季茶會活動以二十四節氣為主題，結合在地茶旅達人司茶，伴著阿里山自然地景風貌（如：櫻花、螢火蟲、瀑布、竹林、森林、黃頭鷺、紫藤、雲瀑等），山林芬多精，品茗阿里山優質茶湯滋味；本計畫並將旅遊動線串連到產地製茶體驗、旅宿及品茗，開發多元茶品、茶輕食、茶文創商品，並搭配本處阿里山日產業展及國際旅展等聯合行銷茶旅遊程，提供國人與國際人士預約體驗深度茶之旅，形塑專屬阿里山茶文化體驗觀光品牌，促進阿里山茶文化、生態、產業等在地創生及深耕，活絡阿里山在地觀光產業，創造阿里山茶旅觀光產業整體效益與產值。    春季茶會：2023.04.22 - 2023.04.23    夏季茶會：2023.07.22    秋季茶會：2023.09.23    冬季茶會：2023.12.17-->', `organizer`='交通部觀光署阿里山國家風景區管理處', `address`='圓潭自然生態園區', `start_date`='2023-04-01 00:00:00', `end_date`='2023-12-31 00:00:00', `location`='嘉義縣梅山鄉', `latitude`=23.528943, `longitude`=120.659331, `ticket_price`='無資料', `source_url`='https://www.ali-nsa.net/zh-tw/event/calendardetail/2824', `image_url`='["https://www.taiwan.net.tw/att/event/1865b1a1-b85c-4284-8282-ea6935693344.jpg", "https://www.taiwan.net.tw/att/event/37e02b28-cedd-48a0-a90b-4f7294ed23ee.jpg", "https://