INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081066', '2023一見雙雕藝術季', '「一見雙雕藝術季」活動是南臺灣每年暑假期間盛大的雕塑藝術展演活動，活動主要於臺南市七股區的七股鹽山、七股遊客中心及將軍區馬沙溝等地方，展出以雲嘉南在地素材，包括鹽、海沙、漂流木等等材料，所雕塑創作的藝術品，甚至南臺灣炙熱的陽光，都是藝術家豐富創意裡可創作的元素。不僅創作元素取材自在地，「一見雙雕藝術季」的重要雕塑主角&ndash;鹽雕展，也是目前臺灣獨一無二的展示，藉由鹽雕再結合其他不同材料的雕塑作品，提供遊客每年不同感受的一見雙雕體驗。此外活動也結合年度觀光主題，包括小鎮旅遊、自行車旅遊等，推出假日系列活動，鼓勵親子、好友來到濱海小鎮一覽濱海美景，豐富的活動內容，每年均吸引超過十萬人次遊客前往觀賞。自民國101年（西元2012年）起創辦全臺獨一無二的「一見雙雕藝術季」，希望透過創新手法、強而有力行銷，達到吸引國、內外旅客造訪，奠定活動節慶品牌地位，同時更形成觀光與藝術兼容並蓄的新氣象，並為濱海遊樂注入新風潮，再創產業新契機。為強化西南濱海獨有的鹽業文化風情，自民國108年（西元2019年）起轉型為「鹽雕+光雕」，結合靜態「鹽雕」作品展、動態影音「光雕」秀等吸睛工藝手法，打造鹽業文化絢麗的視覺藝術饗宴。民國110年（西元2021年）進一步嘗試結合在地的「鹽」與「漂流木」兩種材料，以永續再生的環保理念，規劃鹽雕與漂流木雕地景藝術展，將雲嘉南在地特色與藝術融為一體，為遊客獻上一場不同以往的一見雙雕藝術饗宴。', '交通部觀光署雲嘉南濱海國家風景區管理處', '七股鹽山', '2023-12-01 00:00:00', '2024-03-10 00:00:00', '臺南市七股區', 23.154125, 120.099998, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/51db4ec8-b6cf-4889-92ce-037533ea5724.jpg", "https://www.taiwan.net.tw/att/event/fcb4cd3b-c0ce-4dcd-8ee0-e24daeafa929.jpg", "https://www.taiwan.net.tw/att/event/d5c90667-2d22-403a-bfdc-70e32b193498.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023一見雙雕藝術季', `description`='「一見雙雕藝術季」活動是南臺灣每年暑假期間盛大的雕塑藝術展演活動，活動主要於臺南市七股區的七股鹽山、七股遊客中心及將軍區馬沙溝等地方，展出以雲嘉南在地素材，包括鹽、海沙、漂流木等等材料，所雕塑創作的藝術品，甚至南臺灣炙熱的陽光，都是藝術家豐富創意裡可創作的元素。不僅創作元素取材自在地，「一見雙雕藝術季」的重要雕塑主角&ndash;鹽雕展，也是目前臺灣獨一無二的展示，藉由鹽雕再結合其他不同材料的雕塑作品，提供遊客每年不同感受的一見雙雕體驗。此外活動也結合年度觀光主題，包括小鎮旅遊、自行車旅遊等，推出假日系列活動，鼓勵親子、好友來到濱海小鎮一覽濱海美景，豐富的活動內容，每年均吸引超過十萬人次遊客前往觀賞。自民國101年（西元2012年）起創辦全臺獨一無二的「一見雙雕藝術季」，希望透過創新手法、強而有力行銷，達到吸引國、內外旅客造訪，奠定活動節慶品牌地位，同時更形成觀光與藝術兼容並蓄的新氣象，並為濱海遊樂注入新風潮，再創產業新契機。為強化西南濱海獨有的鹽業文化風情，自民國108年（西元2019年）起轉型為「鹽雕+光雕」，結合靜態「鹽雕」作品展、動態影音「光雕」秀等吸睛工藝手法，打造鹽業文化絢麗的視覺藝術饗宴。民國110年（西元2021年）進一步嘗試結合在地的「鹽」與「漂流木」兩種材料，以永續再生的環保理念，規劃鹽雕與漂流木雕地景藝術展，將雲嘉南在地特色與藝術融為一體，為遊客獻上一場不同以往的一見雙雕藝術饗宴。', `organizer`='交通部觀光署雲嘉南濱海國家風景區管理處', `address`='七股鹽山', `start_date`='2023-12-01 00:00:00', `end_date`='2024-03-10 00:00:00', `location`='臺南市七股區', `latitude`=23.154125, `longitude`=120.099998, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/51db4ec8-b6cf-4889-92ce-037533ea5724.jpg", "https://www.taiwan.net.tw/att/event/fcb4cd3b-c0ce-4dcd-8ee0-e24daeafa929.jpg", "https://www.taiwan.net.tw/att/event/d5c90667-2d22-403a-bfdc-70e32b193498.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081067', '2023南島族群婚禮', '2024南島族群婚禮報名網址本處轄區位於高屏山麓，在轄管的6個鄉區中，有5個鄉區為原住民地區，族群包含魯凱、排灣、布農及拉阿魯哇族等，呈現多元的原住民文化特色。為推廣本轄特有的原住民文化，帶動部落觀光發展，希望藉由「南島族群婚禮活動」之辦理，以原住民傳統婚禮為主軸，原鄉文化觀光組織為核心，運用觀光行銷手法，將婚禮活動包裝為具有文化特色的觀光活動，並以系列活動引導遊客漫遊高屏山麓，感受幸福原鄉。本婚禮主活動為排灣族、魯凱族的傳統貴族婚禮，其求婚、送採薪禮、豎鞦韆架、下聘、成婚等古禮儀式是排灣族、魯凱族獨特的文化，讓參與活動的新人們可以深度體驗原住民族傳統文化及婚禮，在部落族人及耆老共同見證下，遵循部落古禮完成人生大事，並藉觀光活動及套裝遊程的推動，讓遊客對於原住民文化有更多的了解與尊重。    開幕記者會：3/17 三地門鄉公所前廣場    Kinisenayan星空音樂會：3/18 三地門鄉地磨兒藝術公園    新人之夜：3/24 三地門鄉中山公園    排灣族貴族傳統婚禮：3/25 三地門鄉地磨兒藝術公園    TAZUA的婚禮─傳統婚禮服飾與現代轉譯特展：3/1-5/31 三地門鄉文化館    南島市集派對：3月每週六、日，共8日 禮納里遊客中心前廣場    3/4、3/5、3/11、3/12、3/18、3/19、3/25、3/26', '交通部觀光署茂林國家風景區管理處', '三地門鄉公所前廣場', '2023-03-04 00:00:00', '2023-05-31 00:00:00', '屏東縣三地門鄉', 22.716201, 120.65413, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/722cdd0f-9b45-4241-9d76-fb8d74ee1e6e.jpg", "https://www.taiwan.net.tw/att/event/d211f6ac-f189-45cf-aff2-683925984b5d.jpg", "https://www.taiwan.net.tw/att/event/cdd81f24-c9f4-401a-8e08-7c352e1d8978.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023南島族群婚禮', `description`='2024南島族群婚禮報名網址本處轄區位於高屏山麓，在轄管的6個鄉區中，有5個鄉區為原住民地區，族群包含魯凱、排灣、布農及拉阿魯哇族等，呈現多元的原住民文化特色。為推廣本轄特有的原住民文化，帶動部落觀光發展，希望藉由「南島族群婚禮活動」之辦理，以原住民傳統婚禮為主軸，原鄉文化觀光組織為核心，運用觀光行銷手法，將婚禮活動包裝為具有文化特色的觀光活動，並以系列活動引導遊客漫遊高屏山麓，感受幸福原鄉。本婚禮主活動為排灣族、魯凱族的傳統貴族婚禮，其求婚、送採薪禮、豎鞦韆架、下聘、成婚等古禮儀式是排灣族、魯凱族獨特的文化，讓參與活動的新人們可以深度體驗原住民族傳統文化及婚禮，在部落族人及耆老共同見證下，遵循部落古禮完成人生大事，並藉觀光活動及套裝遊程的推動，讓遊客對於原住民文化有更多的了解與尊重。    開幕記者會：3/17 三地門鄉公所前廣場    Kinisenayan星空音樂會：3/18 三地門鄉地磨兒藝術公園    新人之夜：3/24 三地門鄉中山公園    排灣族貴族傳統婚禮：3/25 三地門鄉地磨兒藝術公園    TAZUA的婚禮─傳統婚禮服飾與現代轉譯特展：3/1-5/31 三地門鄉文化館    南島市集派對：3月每週六、日，共8日 禮納里遊客中心前廣場    3/4、3/5、3/11、3/12、3/18、3/19、3/25、3/26', `organizer`='交通部觀光署茂林國家風景區管理處', `address`='三地門鄉公所前廣場', `start_date`='2023-03-04 00:00:00', `end_date`='2023-05-31 00:00:00', `location`='屏東縣三地門鄉', `latitude`=22.716201, `longitude`=120.65413, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/722cdd0f-9b45-4241-9d76-fb8d74ee1e6e.jpg", "https://www.taiwan.net.tw/att/event/d211f6ac-f189-45cf-aff2-683925984b5d.jpg", "https://www.taiwan.net.tw/att/event/cdd81f24-c9f4-401a-8e08-7c352e1d8978.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081068', '2023臺北白晝之夜', '「Nuit Blanche 白晝之夜」是全球的夜間城市藝術祭，民國91年（西元2002年）創始於法國巴黎，在10月第一個週六跨夜舉行。「白晝之夜」根基於「都市創新」及「公共空間設計」兩大核心概念，為市民提供親近藝術及城市的場域。「白晝之夜」有三大特色：「跨夜舉辦」、「免費參加」及「公民參與」，透過多樣化的藝術作品及演出安排，讓人自然接觸藝術，自由穿梭於城市空間之中。「白晝之夜」打破大眾娛樂與純藝術的界線，作品橫跨劇場、馬戲、舞蹈、音樂、行為藝術、新媒體藝術等不同領域，讓跨文化、跨世代的多樣美學交錯混融。「白晝之夜」在城市中塑造獨特的交流共享環境，透過藝術轉化都市空間，讓整個臺北市化身一夜限定的大型美術館。', '臺北市政府文化局', '信義商圈', '2023-10-07 00:00:00', '2023-10-08 00:00:00', '臺北市信義區', 25.04092, 121.572005, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/dc9cac41-e045-4c45-9576-767e0f6c398f.jpg", "https://www.taiwan.net.tw/att/event/cb0ebe57-e115-4002-b5ce-b8146b7f78a5.jpg", "https://www.taiwan.net.tw/att/event/f567612d-8c14-4c62-ab4d-9eeac29b11c1.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023臺北白晝之夜', `description`='「Nuit Blanche 白晝之夜」是全球的夜間城市藝術祭，民國91年（西元2002年）創始於法國巴黎，在10月第一個週六跨夜舉行。「白晝之夜」根基於「都市創新」及「公共空間設計」兩大核心概念，為市民提供親近藝術及城市的場域。「白晝之夜」有三大特色：「跨夜舉辦」、「免費參加」及「公民參與」，透過多樣化的藝術作品及演出安排，讓人自然接觸藝術，自由穿梭於城市空間之中。「白晝之夜」打破大眾娛樂與純藝術的界線，作品橫跨劇場、馬戲、舞蹈、音樂、行為藝術、新媒體藝術等不同領域，讓跨文化、跨世代的多樣美學交錯混融。「白晝之夜」在城市中塑造獨特的交流共享環境，透過藝術轉化都市空間，讓整個臺北市化身一夜限定的大型美術館。', `organizer`='臺北市政府文化局', `address`='信義商圈', `start_date`='2023-10-07 00:00:00', `end_date`='2023-10-08 00:00:00', `location`='臺北市信義區', `latitude`=25.04092, `longitude`=121.572005, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/dc9cac41-e045-4c45-9576-767e0f6c398f.jpg", "https://www.taiwan.net.tw/att/event/cb0ebe57-e115-4002-b5ce-b8146b7f78a5.jpg", "https://www.taiwan.net.tw/att/event/f567612d-8c14-4c62-ab4d-9eeac29b11c1.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081069', '2023臺北馬拉松', '臺北馬拉松自民國75年（西元1986年）首次舉辦，活動訂於每年12月第3週週日舉行，為臺北市年度重要國際運動賽事。臺北馬拉松自舉辦以來經過多年的努力，參賽選手水平逐漸提升，賽事也將朝向更加專業的菁英化領域邁進，並長期積極與國際接軌，以期提升賽事品質，除原有的國際馬拉松總會（AMIS）賽道認證之外，並已取得世界田徑總會（WA）菁英標籤認證，成為臺灣第一個取得標籤認證的「市區馬拉松」賽事，並成為國內規模最大及國際選手最多的馬拉松賽，每年吸引國內外許多菁英好手齊聚。', '臺北市政府', '臺北市市民廣場', '2023-12-17 00:00:00', '2023-12-17 00:00:00', '臺北市信義區', 25.037921, 121.56313, '無資料', 'https://www.taipeicitymarathon.com/', '["https://www.taiwan.net.tw/att/event/d24b54a1-cabb-4085-a3c7-6d3e349e72d4.jpg", "https://www.taiwan.net.tw/att/event/4b1ff3b8-038a-447a-9af9-0083c76937f6.jpg", "https://www.taiwan.net.tw/att/event/1fdf835c-1d8d-47d5-a733-360ba568868c.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023臺北馬拉松', `description`='臺北馬拉松自民國75年（西元1986年）首次舉辦，活動訂於每年12月第3週週日舉行，為臺北市年度重要國際運動賽事。臺北馬拉松自舉辦以來經過多年的努力，參賽選手水平逐漸提升，賽事也將朝向更加專業的菁英化領域邁進，並長期積極與國際接軌，以期提升賽事品質，除原有的國際馬拉松總會（AMIS）賽道認證之外，並已取得世界田徑總會（WA）菁英標籤認證，成為臺灣第一個取得標籤認證的「市區馬拉松」賽事，並成為國內規模最大及國際選手最多的馬拉松賽，每年吸引國內外許多菁英好手齊聚。', `organizer`='臺北市政府', `address`='臺北市市民廣場', `start_date`='2023-12-17 00:00:00', `end_date`='2023-12-17 00:00:00', `location`='臺北市信義區', `latitude`=25.037921, `longitude`=121.56313, `ticket_price`='無資料', `source_url`='https://www.taipeicitymarathon.com/', `image_url`='["https://www.taiwan.net.tw/att/event/d24b54a1-cabb-4085-a3c7-6d3e349e72d4.jpg", "https://www.taiwan.net.tw/att/event/4b1ff3b8-038a-447a-9af9-0083c76937f6.jpg", "https://www.taiwan.net.tw/att/event/1fdf835c-1d8d-47d5-a733-360ba568868c.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081070', '臺北最HIGH新年城-跨年晚會', '民國108年（西元2019年）國際知名媒體CNN將臺北跨年評為「全球十大跨年景點之一」，故以「一生必去 亞洲必遊」為活動目標及核心價值，將「臺北最HIGH新年城-跨年晚會」打造成亞洲最具吸引力之活動品牌，提升臺北國際能見度，吸引大量國內外旅客來臺朝聖，創造龐大觀光經濟效益。每年晚會於12月31日晚間7時至隔年1月1日凌晨1時於臺北市政府前市民廣場舉辦大型展演活動，邀請國內外知名藝人及表演團體輪番表演，並搭配101新年大秀，在五光十色的燈光煙火秀下，與全世界民眾一起倒數迎向新年到來。', '臺北市政府觀光傳播局、台北101', '臺北市市民廣場', '2023-12-31 00:00:00', '2024-01-01 00:00:00', '臺北市信義區', 25.037921, 121.56313, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/617ea19c-0894-4f18-8153-ec096d6485b1.jpg", "https://www.taiwan.net.tw/att/event/d04cfb19-9fc9-4068-9b40-a9e3d8bb9d9e.jpg", "https://www.taiwan.net.tw/att/event/41074f09-0066-494b-a746-3afde103fa2b.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='臺北最HIGH新年城-跨年晚會', `description`='民國108年（西元2019年）國際知名媒體CNN將臺北跨年評為「全球十大跨年景點之一」，故以「一生必去 亞洲必遊」為活動目標及核心價值，將「臺北最HIGH新年城-跨年晚會」打造成亞洲最具吸引力之活動品牌，提升臺北國際能見度，吸引大量國內外旅客來臺朝聖，創造龐大觀光經濟效益。每年晚會於12月31日晚間7時至隔年1月1日凌晨1時於臺北市政府前市民廣場舉辦大型展演活動，邀請國內外知名藝人及表演團體輪番表演，並搭配101新年大秀，在五光十色的燈光煙火秀下，與全世界民眾一起倒數迎向新年到來。', `organizer`='臺北市政府觀光傳播局、台北101', `address`='臺北市市民廣場', `start_date`='2023-12-31 00:00:00', `end_date`='2024-01-01 00:00:00', `location`='臺北市信義區', `latitude`=25.037921, `longitude`=121.56313, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/617ea19c-0894-4f18-8153-ec096d6485b1.jpg", "https://www.taiwan.net.tw/att/event/d04cfb19-9fc9-4068-9b40-a9e3d8bb9d9e.jpg", "https://www.taiwan.net.tw/att/event/41074f09-0066-494b-a746-3afde103fa2b.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081071', '2023新北歡樂耶誕城', '新北歡樂耶誕城自民國100年（西元2011年）開辦以來，每年活動持續創新及與國際接軌，邀請到國際頂尖光雕團隊合作，不斷突破光雕主燈秀光影藝術巔峰，透過新科技導入及融入藝術，與國內外知名企業、藝術家或在地學校合作，讓主燈、燈飾設計層次提升，相關系列活動極富含特色與國際魅力，不斷帶給大眾創新與驚喜的感受，使本活動屢獲眾多國際媒體報導，不僅讓國人能夠免出國就能體驗國際級的燈影藝術，更讓國外的朋友能因為這個活動而感受臺灣特有的節慶氛圍，一睹絕美震撼的節慶國際饗宴。', '新北市政府', '新北市市民廣場', '2023-11-17 00:00:00', '2024-01-01 00:00:00', '新北市板橋區', 25.012276, 121.465536, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/ad361c2a-2a7f-486e-be9e-e08e7b03eaa4.jpg", "https://www.taiwan.net.tw/att/event/691c1e9a-372a-4687-912e-b947f0d417d3.jpg", "https://www.taiwan.net.tw/att/event/2a6a810d-2fb4-4203-946f-63bd22c8cf54.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023新北歡樂耶誕城', `description`='新北歡樂耶誕城自民國100年（西元2011年）開辦以來，每年活動持續創新及與國際接軌，邀請到國際頂尖光雕團隊合作，不斷突破光雕主燈秀光影藝術巔峰，透過新科技導入及融入藝術，與國內外知名企業、藝術家或在地學校合作，讓主燈、燈飾設計層次提升，相關系列活動極富含特色與國際魅力，不斷帶給大眾創新與驚喜的感受，使本活動屢獲眾多國際媒體報導，不僅讓國人能夠免出國就能體驗國際級的燈影藝術，更讓國外的朋友能因為這個活動而感受臺灣特有的節慶氛圍，一睹絕美震撼的節慶國際饗宴。', `organizer`='新北市政府', `address`='新北市市民廣場', `start_date`='2023-11-17 00:00:00', `end_date`='2024-01-01 00:00:00', `location`='新北市板橋區', `latitude`=25.012276, `longitude`=121.465536, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/ad361c2a-2a7f-486e-be9e-e08e7b03eaa4.jpg", "https://www.taiwan.net.tw/att/event/691c1e9a-372a-4687-912e-b947f0d417d3.jpg", "https://www.taiwan.net.tw/att/event/2a6a810d-2fb4-4203-946f-63bd22c8cf54.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081072', '2023新北市平溪天燈節', '新北市平溪天燈節自民國88年（西元1999年）辦理至今，多年來在地方與公部門共同努力下，天燈儼然成為臺灣重要的國際意象，這個大型節慶品牌也屢獲國際好評：除了備受CNN、Discovery、全球最大旅遊出版公司Fodor''s、國家地理雜誌及The Huffington Post（赫芬頓郵報）肯定外，民國107年（西元2018年）更被全球最大旅遊網站TripAdvisor票選為「最值得推薦國際旅客的文化活動」，並獲得Reader''s digest（讀者文摘）推薦「40歲前要完成的40項旅遊清單」之一，顯見天燈節除了將平溪地區在國際上的能見度再次提升，更將平溪帶向全世界！新北市平溪天燈節儼然成為臺灣在國際舞臺上的重要亮點，更因為活動的推廣，使國內、外旅客四季都能規劃造訪平溪的遊程，體驗當地獨特的天燈文化，期能藉此地方特色民俗文化，提供人們傳遞幸福心願的節慶活動，並結合地方自然與人文資源，吸引世界各地旅客深度感受臺灣之美，亦持續推廣國際觀光，創造更多旅遊商機。', '新北市政府觀光旅遊局', '南山坪136號', '2023-02-05 00:00:00', '2023-02-11 00:00:00', '新北市平溪區', 25.046794, 121.782574, '無資料', 'https://2023skylantern.ntpc.gov.tw/', '["https://www.taiwan.net.tw/att/event/ceb08c83-cb64-4f57-a593-079676aba8ae.jpg", "https://www.taiwan.net.tw/att/event/25f9b177-033c-457a-919b-822753745faf.jpg", "https://www.taiwan.net.tw/att/event/48019830-c1fd-463c-a8a3-fb53f638cb52.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023新北市平溪天燈節', `description`='新北市平溪天燈節自民國88年（西元1999年）辦理至今，多年來在地方與公部門共同努力下，天燈儼然成為臺灣重要的國際意象，這個大型節慶品牌也屢獲國際好評：除了備受CNN、Discovery、全球最大旅遊出版公司Fodor''s、國家地理雜誌及The Huffington Post（赫芬頓郵報）肯定外，民國107年（西元2018年）更被全球最大旅遊網站TripAdvisor票選為「最值得推薦國際旅客的文化活動」，並獲得Reader''s digest（讀者文摘）推薦「40歲前要完成的40項旅遊清單」之一，顯見天燈節除了將平溪地區在國際上的能見度再次提升，更將平溪帶向全世界！新北市平溪天燈節儼然成為臺灣在國際舞臺上的重要亮點，更因為活動的推廣，使國內、外旅客四季都能規劃造訪平溪的遊程，體驗當地獨特的天燈文化，期能藉此地方特色民俗文化，提供人們傳遞幸福心願的節慶活動，並結合地方自然與人文資源，吸引世界各地旅客深度感受臺灣之美，亦持續推廣國際觀光，創造更多旅遊商機。', `organizer`='新北市政府觀光旅遊局', `address`='南山坪136號', `start_date`='2023-02-05 00:00:00', `end_date`='2023-02-11 00:00:00', `location`='新北市平溪區', `latitude`=25.046794, `longitude`=121.782574, `ticket_price`='無資料', `source_url`='https://2023skylantern.ntpc.gov.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/ceb08c83-cb64-4f57-a593-079676aba8ae.jpg", "https://www.taiwan.net.tw/att/event/25f9b177-033c-457a-919b-822753745faf.jpg", "https://www.taiwan.net.tw/att/event/48019830-c1fd-463c-a8a3-fb53f638cb52.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081073', '2023新社花海暨臺中國際花毯節', '新社花海暨臺中國際花毯節為中部地區最盛大的花卉慶典，逐年淬煉成為全臺首屈一指、具品牌知名度的花卉與休閒農業活動。推廣花卉產業是中臺灣的在地特色，藉由花卉裝置藝術、社區及在地產業協作，串連花草、農特產、觀光休閒等臺中特色產業，活絡地方商機，提升在地產業量能，深化社區營造，促進地方自立永續發展，帶動山城區域觀光產業鏈更加緊密，吸引各地及國際遊客參觀。', '臺中市政府、行政院農業部種苗改良繁殖場', '行政院農業部種苗改良繁殖場第二苗圃', '2023-11-11 00:00:00', '2023-12-03 00:00:00', '臺中市新社區', 24.203259, 120.805992, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/9bc7d3d6-83b3-4cbb-9c5c-eb467a0c6772.jpg", "https://www.taiwan.net.tw/att/event/e59b6b96-1cc3-477e-a601-20a9b24d4b14.jpg", "https://www.taiwan.net.tw/att/event/d850fea4-6d2a-4d01-b5ca-22cd11cb9db1.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023新社花海暨臺中國際花毯節', `description`='新社花海暨臺中國際花毯節為中部地區最盛大的花卉慶典，逐年淬煉成為全臺首屈一指、具品牌知名度的花卉與休閒農業活動。推廣花卉產業是中臺灣的在地特色，藉由花卉裝置藝術、社區及在地產業協作，串連花草、農特產、觀光休閒等臺中特色產業，活絡地方商機，提升在地產業量能，深化社區營造，促進地方自立永續發展，帶動山城區域觀光產業鏈更加緊密，吸引各地及國際遊客參觀。', `organizer`='臺中市政府、行政院農業部種苗改良繁殖場', `address`='行政院農業部種苗改良繁殖場第二苗圃', `start_date`='2023-11-11 00:00:00', `end_date`='2023-12-03 00:00:00', `location`='臺中市新社區', `latitude`=24.203259, `longitude`=120.805992, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/9bc7d3d6-83b3-4cbb-9c5c-eb467a0c6772.jpg", "https://www.taiwan.net.tw/att/event/e59b6b96-1cc3-477e-a601-20a9b24d4b14.jpg", "https://www.taiwan.net.tw/att/event/d850fea4-6d2a-4d01-b5ca-22cd11cb9db1.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081074', '2023田中馬拉松', '「台灣米倉田中馬拉松 Taiwan''s Rice Heaven－Tianzhong Marathon」自民國101年（西元2012年）開辦，打響國內外知名度，廣受國內外跑者民眾喜愛，並評價為臺灣經典賽事前三名，為國內外跑者來台指定參與賽事。', '彰化縣政府、中華民國舒康樂活運動協會、彰化縣馬拉松路跑協會', '景崧文化教育園區', '2023-10-10 00:00:00', '2023-11-12 00:00:00', '彰化縣田中鎮', 23.857378, 120.581634, '無資料', 'https://www.tianzhongmarathon.com/', '["https://www.taiwan.net.tw/att/event/732760a5-f7be-4705-ae8e-148300aa53ba.jpg", "https://www.taiwan.net.tw/att/event/047dd13b-2c7f-42a7-8f0b-38c06255e8c1.jpg", "https://www.taiwan.net.tw/att/event/108210c2-fa5a-4a3c-ba2c-bde66696cf3e.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023田中馬拉松', `description`='「台灣米倉田中馬拉松 Taiwan''s Rice Heaven－Tianzhong Marathon」自民國101年（西元2012年）開辦，打響國內外知名度，廣受國內外跑者民眾喜愛，並評價為臺灣經典賽事前三名，為國內外跑者來台指定參與賽事。', `organizer`='彰化縣政府、中華民國舒康樂活運動協會、彰化縣馬拉松路跑協會', `address`='景崧文化教育園區', `start_date`='2023-10-10 00:00:00', `end_date`='2023-11-12 00:00:00', `location`='彰化縣田中鎮', `latitude`=23.857378, `longitude`=120.581634, `ticket_price`='無資料', `source_url`='https://www.tianzhongmarathon.com/', `image_url`='["https://www.taiwan.net.tw/att/event/732760a5-f7be-4705-ae8e-148300aa53ba.jpg", "https://www.taiwan.net.tw/att/event/047dd13b-2c7f-42a7-8f0b-38c06255e8c1.jpg", "https://www.taiwan.net.tw/att/event/108210c2-fa5a-4a3c-ba2c-bde66696cf3e.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081075', '2023雲林國際偶戲節', '雲林縣政府每年舉辦「雲林國際偶戲節」與民眾共襄盛舉，以藝術與國際接軌。現今布袋戲也躍升台灣「國家意象」之代表，素有布袋戲的故鄉之稱-雲林，自民國88年（西元1999年）開始籌劃舉辦「雲林國際偶戲節」，邀請國際偶戲工作者來台表演，豐富全國觀眾的文化藝術內涵與視野，讓傳統文化藝術進入民眾的生活中，也能讓本土與外國偶戲團體互相觀摩切磋演技，增進彼此經驗交流，永續發展與創新。為保存及推動布袋戲傳統文化，將這項傳統民俗透過國際文化之交流與刺激，與「金掌獎」活動辦理，讓掌中乾坤的藝術與時俱進，讓即使不懂、不看布袋戲的人，能親近進而喜歡上布袋戲詼諧逗趣，欣賞到布袋戲精萃之美，使布袋戲偶戲文化得以傳承。', '雲林縣政府', '雲林布袋戲館', '2023-09-24 00:00:00', '2023-10-14 00:00:00', '雲林縣虎尾鎮', 23.709297, 120.433562, '無資料', 'https://tour.yunlin.gov.tw/wt-front/Activity/Index/A000000191', '["https://www.taiwan.net.tw/att/event/9bc0bf0f-4afd-49cb-9341-431104cd2782.jpg", "https://www.taiwan.net.tw/att/event/4bf9723d-d529-4530-a3dc-66a2ed2aee8d.jpg", "https://www.taiwan.net.tw/att/event/83819eaa-7cbd-440e-b64b-4713c7478641.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023雲林國際偶戲節', `description`='雲林縣政府每年舉辦「雲林國際偶戲節」與民眾共襄盛舉，以藝術與國際接軌。現今布袋戲也躍升台灣「國家意象」之代表，素有布袋戲的故鄉之稱-雲林，自民國88年（西元1999年）開始籌劃舉辦「雲林國際偶戲節」，邀請國際偶戲工作者來台表演，豐富全國觀眾的文化藝術內涵與視野，讓傳統文化藝術進入民眾的生活中，也能讓本土與外國偶戲團體互相觀摩切磋演技，增進彼此經驗交流，永續發展與創新。為保存及推動布袋戲傳統文化，將這項傳統民俗透過國際文化之交流與刺激，與「金掌獎」活動辦理，讓掌中乾坤的藝術與時俱進，讓即使不懂、不看布袋戲的人，能親近進而喜歡上布袋戲詼諧逗趣，欣賞到布袋戲精萃之美，使布袋戲偶戲文化得以傳承。', `organizer`='雲林縣政府', `address`='雲林布袋戲館', `start_date`='2023-09-24 00:00:00', `end_date`='2023-10-14 00:00:00', `location`='雲林縣虎尾鎮', `latitude`=23.709297, `longitude`=120.433562, `ticket_price`='無資料', `source_url`='https://tour.yunlin.gov.tw/wt-front/Activity/Index/A000000191', `image_url`='["https://www.taiwan.net.tw/att/event/9bc0bf0f-4afd-49cb-9341-431104cd2782.jpg", "https://www.taiwan.net.tw/att/event/4bf9723d-d529-4530-a3dc-66a2ed2aee8d.jpg", "https://www.taiwan.net.tw/att/event/83819eaa-7cbd-440e-b64b-4713c7478641.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081076', '2023日月潭國際萬人泳渡', '起始於民國72年（西元1983年）的日月潭國際萬人泳渡活動，每年中秋節前後舉辦，是日月潭最具歷史與規模的活動。泳渡全程約3,000公尺，每年均吸引來自海內外四面八方上萬名游泳愛好者參加，幾乎在開放報名即迅速額滿的「日月潭萬人泳渡」嘉年華盛事，場面盛況空前。', '南投縣政府、中華民國成人游泳協會、埔里鎮四季早泳會', '日月潭', '2023-09-24 00:00:00', '2023-09-24 00:00:00', '南投縣魚池鄉', 23.857334, 120.915913, '無資料', 'https://www.pulifourswim.tw/tw/index.php', '["https://www.taiwan.net.tw/att/event/32664653-b656-4e7f-bb6d-ed1b726fa3b9.jpg", "https://www.taiwan.net.tw/att/event/50882fb8-6e13-49dc-8d8a-f7b83de20fe3.jpg", "https://www.taiwan.net.tw/att/event/5caeebb0-fc57-4a9d-ab56-164edc57d959.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023日月潭國際萬人泳渡', `description`='起始於民國72年（西元1983年）的日月潭國際萬人泳渡活動，每年中秋節前後舉辦，是日月潭最具歷史與規模的活動。泳渡全程約3,000公尺，每年均吸引來自海內外四面八方上萬名游泳愛好者參加，幾乎在開放報名即迅速額滿的「日月潭萬人泳渡」嘉年華盛事，場面盛況空前。', `organizer`='南投縣政府、中華民國成人游泳協會、埔里鎮四季早泳會', `address`='日月潭', `start_date`='2023-09-24 00:00:00', `end_date`='2023-09-24 00:00:00', `location`='南投縣魚池鄉', `latitude`=23.857334, `longitude`=120.915913, `ticket_price`='無資料', `source_url`='https://www.pulifourswim.tw/tw/index.php', `image_url`='["https://www.taiwan.net.tw/att/event/32664653-b656-4e7f-bb6d-ed1b726fa3b9.jpg", "https://www.taiwan.net.tw/att/event/50882fb8-6e13-49dc-8d8a-f7b83de20fe3.jpg", "https://www.taiwan.net.tw/att/event/5caeebb0-fc57-4a9d-ab56-164edc57d959.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081077', '2023南投世界茶業博覽會', '南投有八大茶區，更是台灣茶葉主要產地，活動主要透過展館搭建與展售會，提供遊客茶知識、體驗、展演。並於活動期間舉辦數場大型特色主題活動，如千人茶會、千人擂茶以及千人野餐等活動，推廣多元豐富的茶文化。', '南投縣政府', '中興新村 中興會堂', '2023-10-07 00:00:00', '2023-10-15 00:00:00', '南投縣南投市', 23.949292, 120.696221, '無資料', 'https://teaexpo.mmweb.tw/', '["https://www.taiwan.net.tw/att/event/700ff267-3b42-49c0-9986-9ccc8f92774d.jpg", "https://www.taiwan.net.tw/att/event/815fa862-4a89-41ca-a4ff-fb7ea82fc652.jpg", "https://www.taiwan.net.tw/att/event/15ab56ee-b458-4206-a509-5fa9eeb84272.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023南投世界茶業博覽會', `description`='南投有八大茶區，更是台灣茶葉主要產地，活動主要透過展館搭建與展售會，提供遊客茶知識、體驗、展演。並於活動期間舉辦數場大型特色主題活動，如千人茶會、千人擂茶以及千人野餐等活動，推廣多元豐富的茶文化。', `organizer`='南投縣政府', `address`='中興新村 中興會堂', `start_date`='2023-10-07 00:00:00', `end_date`='2023-10-15 00:00:00', `location`='南投縣南投市', `latitude`=23.949292, `longitude`=120.696221, `ticket_price`='無資料', `source_url`='https://teaexpo.mmweb.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/700ff267-3b42-49c0-9986-9ccc8f92774d.jpg", "https://www.taiwan.net.tw/att/event/815fa862-4a89-41ca-a4ff-fb7ea82fc652.jpg", "https://www.taiwan.net.tw/att/event/15ab56ee-b458-4206-a509-5fa9eeb84272.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081078', '2023嘉義市國際管樂節', '嘉義市國際管樂節從1993年開始5校樂團表演的「音樂節」，逐漸擴大參與廣度，成為全民參與的「城市節慶活動」。於今年本活動已邁入第30屆，不僅為嘉義市最具特色的文化節慶、亦是台灣具代表性的文化活動，被交通部觀光署列為台灣國際級觀光節慶活動之一。歷年來結合重大的音樂盛會，例如，2000年辦理亞太管樂節、2011世界管樂年會、2013亞洲雙簧年會、2016亞洲薩克斯風大會，已獲得了國內外音樂界的美名與口碑，更以「聲音的城市」、「管樂城」成為全台特色。', '嘉義市政府', '中央噴水池', '2023-12-15 00:00:00', '2024-01-01 00:00:00', '嘉義市東區', 23.479915, 120.449632, '無資料', 'https://www.chiayiband.com.tw/', '["https://www.taiwan.net.tw/att/event/e527cdf7-7afa-4d0f-8cfa-9a6173809be2.jpg", "https://www.taiwan.net.tw/att/event/d5947fc5-d324-4cbd-a3b9-c2eb91b5e7f0.jpg", "https://www.taiwan.net.tw/att/event/15a552d9-0515-4b60-9730-45a4900fdeed.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023嘉義市國際管樂節', `description`='嘉義市國際管樂節從1993年開始5校樂團表演的「音樂節」，逐漸擴大參與廣度，成為全民參與的「城市節慶活動」。於今年本活動已邁入第30屆，不僅為嘉義市最具特色的文化節慶、亦是台灣具代表性的文化活動，被交通部觀光署列為台灣國際級觀光節慶活動之一。歷年來結合重大的音樂盛會，例如，2000年辦理亞太管樂節、2011世界管樂年會、2013亞洲雙簧年會、2016亞洲薩克斯風大會，已獲得了國內外音樂界的美名與口碑，更以「聲音的城市」、「管樂城」成為全台特色。', `organizer`='嘉義市政府', `address`='中央噴水池', `start_date`='2023-12-15 00:00:00', `end_date`='2024-01-01 00:00:00', `location`='嘉義市東區', `latitude`=23.479915, `longitude`=120.449632, `ticket_price`='無資料', `source_url`='https://www.chiayiband.com.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/e527cdf7-7afa-4d0f-8cfa-9a6173809be2.jpg", "https://www.taiwan.net.tw/att/event/d5947fc5-d324-4cbd-a3b9-c2eb91b5e7f0.jpg", "https://www.taiwan.net.tw/att/event/15a552d9-0515-4b60-9730-45a4900fdeed.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081079', '2023台灣慶元宵-鹽水蜂炮', '鹽水蜂炮，是元宵節轟動全台的重要觀光民俗活動。每年吸引觀光客人數，數以萬計，和「平溪天燈」有「北天燈，南蜂炮」之美稱。鹽水蜂炮起源相傳於西元1885年七、八月間，鹽水街流行霍亂、瘟疫，當時因醫藥不發達，死者日眾，居民恐慌，祈求關聖帝君解災難。關聖帝君乃於元宵夜命周倉將軍為前導，帝君神轎殿後，眾善信大德隨神轎一路燃放鞭炮，遶境大街小巷至天明，將邪魔一掃而除。自此，後代子孫每年均沿襲往例，迎請關聖帝君元宵夜出巡。這種當初單純的燃放鞭炮蛻變為「蜂炮」、「炮城」等活動，奠定今日鹽水遠近馳名的民俗特色。鹽水蜂炮的璀燦亮麗，可媲美巴西聞名世界的「嘉年華會」，元宵夜鹽水各商戶隨著神轎遶街施放蜂炮，使整個鹽水古鎮漫天震響，此起彼落，夜色中天空五光十色，聲光千變萬化，蔚為奇觀。鹽水蜂炮為臺灣重要民俗活動發展至今已將近150年，其舉辦宗旨與目的從驅逐瘟疫逐步演變至節日慶祝；活動影響範圍從鹽水擴大至全世界，成為亞洲的十大慶典、全球三大嘉年華之一，對臺灣走向國際舞台發揮重大的貢獻。', '臺南市政府觀光旅遊局、鹽水武廟', '鹽水武廟', '2023-02-04 00:00:00', '2023-02-05 00:00:00', '臺南市鹽水區', 23.323839, 120.26575, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/233c4f2c-bbc9-4abb-8d4f-9bd68badda44.jpg", "https://www.taiwan.net.tw/att/event/f665f0df-aa73-4b1f-a180-350428208c43.jpg", "https://www.taiwan.net.tw/att/event/89c3831b-4ceb-40ed-b7ea-fe18fe71c279.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023台灣慶元宵-鹽水蜂炮', `description`='鹽水蜂炮，是元宵節轟動全台的重要觀光民俗活動。每年吸引觀光客人數，數以萬計，和「平溪天燈」有「北天燈，南蜂炮」之美稱。鹽水蜂炮起源相傳於西元1885年七、八月間，鹽水街流行霍亂、瘟疫，當時因醫藥不發達，死者日眾，居民恐慌，祈求關聖帝君解災難。關聖帝君乃於元宵夜命周倉將軍為前導，帝君神轎殿後，眾善信大德隨神轎一路燃放鞭炮，遶境大街小巷至天明，將邪魔一掃而除。自此，後代子孫每年均沿襲往例，迎請關聖帝君元宵夜出巡。這種當初單純的燃放鞭炮蛻變為「蜂炮」、「炮城」等活動，奠定今日鹽水遠近馳名的民俗特色。鹽水蜂炮的璀燦亮麗，可媲美巴西聞名世界的「嘉年華會」，元宵夜鹽水各商戶隨著神轎遶街施放蜂炮，使整個鹽水古鎮漫天震響，此起彼落，夜色中天空五光十色，聲光千變萬化，蔚為奇觀。鹽水蜂炮為臺灣重要民俗活動發展至今已將近150年，其舉辦宗旨與目的從驅逐瘟疫逐步演變至節日慶祝；活動影響範圍從鹽水擴大至全世界，成為亞洲的十大慶典、全球三大嘉年華之一，對臺灣走向國際舞台發揮重大的貢獻。', `organizer`='臺南市政府觀光旅遊局、鹽水武廟', `address`='鹽水武廟', `start_date`='2023-02-04 00:00:00', `end_date`='2023-02-05 00:00:00', `location`='臺南市鹽水區', `latitude`=23.323839, `longitude`=120.26575, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/233c4f2c-bbc9-4abb-8d4f-9bd68badda44.jpg", "https://www.taiwan.net.tw/att/event/f665f0df-aa73-4b1f-a180-350428208c43.jpg", "https://www.taiwan.net.tw/att/event/89c3831b-4ceb-40ed-b7ea-fe18fe71c279.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081080', '2023臺灣國際蘭展', '一年一度的臺灣國際蘭展自民國94年（西元2005年）創辦至今，每年於臺南市後壁區臺灣蘭花生物科技園區舉辦，並已成為國際花卉界年度盛事，地位與「東京蘭展」、「世界蘭展」相當，並列為三大國際蘭展。臺灣國際蘭展每年皆規劃不同主題，逐年創造話題吸引數十萬民眾前往觀賞，舉辦宗旨為促進臺灣蘭花產業發展，並藉由蘭花展示、佈景、運用及結合文創、生物科技等產品，提升民眾賞花興趣，進而帶動花卉消費習慣，促進國際交流並維持蘭花產業永續經營。', '臺南市政府、中華民國對外貿易發展協會', '臺灣蘭花生物科技園區', '2023-03-04 00:00:00', '2023-03-19 00:00:00', '臺南市後壁區', 23.339178, 120.377635, '無資料', 'https://tios.tw/', '["https://www.taiwan.net.tw/att/event/b773a000-57fa-4979-8a6f-8afbe62420dd.jpg", "https://www.taiwan.net.tw/att/event/7da3aaf8-a24c-4a51-be4b-30807f4e8eed.jpg", "https://www.taiwan.net.tw/att/event/f3b912ec-aa44-4194-9fc8-4cc907993da3.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023臺灣國際蘭展', `description`='一年一度的臺灣國際蘭展自民國94年（西元2005年）創辦至今，每年於臺南市後壁區臺灣蘭花生物科技園區舉辦，並已成為國際花卉界年度盛事，地位與「東京蘭展」、「世界蘭展」相當，並列為三大國際蘭展。臺灣國際蘭展每年皆規劃不同主題，逐年創造話題吸引數十萬民眾前往觀賞，舉辦宗旨為促進臺灣蘭花產業發展，並藉由蘭花展示、佈景、運用及結合文創、生物科技等產品，提升民眾賞花興趣，進而帶動花卉消費習慣，促進國際交流並維持蘭花產業永續經營。', `organizer`='臺南市政府、中華民國對外貿易發展協會', `address`='臺灣蘭花生物科技園區', `start_date`='2023-03-04 00:00:00', `end_date`='2023-03-19 00:00:00', `location`='臺南市後壁區', `latitude`=23.339178, `longitude`=120.377635, `ticket_price`='無資料', `source_url`='https://tios.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/b773a000-57fa-4979-8a6f-8afbe62420dd.jpg", "https://www.taiwan.net.tw/att/event/7da3aaf8-a24c-4a51-be4b-30807f4e8eed.jpg", "https://www.taiwan.net.tw/att/event/f3b912ec-aa44-4194-9fc8-4cc907993da3.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081081', '2023高雄內門宋江陣', '高雄內門宋江陣自民國90年（西元2001年）起開始舉辦，由高雄市政府及內門三大廟宇共同辦理，結合民俗藝陣、地方節慶、觀光旅遊、產業經濟等元素，將原屬地方廟會活動擴大為融合表演藝術、宗教信仰與在地文化底蘊的在地嘉年華，係內門、旗山區一年一度宗教暨文化慶典盛事。', '高雄市政府', '內門南海紫竹寺', '2023-02-25 00:00:00', '2023-03-08 00:00:00', '高雄市內門區', 22.941761, 120.461364, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/1fb82aa1-8c09-4ddf-af75-241af1f73f3a.jpg", "https://www.taiwan.net.tw/att/event/c7ee4373-1fd0-4e44-ba77-1ac131964321.jpg", "https://www.taiwan.net.tw/att/event/207fe3aa-8458-4d16-8273-f285cae0d95d.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023高雄內門宋江陣', `description`='高雄內門宋江陣自民國90年（西元2001年）起開始舉辦，由高雄市政府及內門三大廟宇共同辦理，結合民俗藝陣、地方節慶、觀光旅遊、產業經濟等元素，將原屬地方廟會活動擴大為融合表演藝術、宗教信仰與在地文化底蘊的在地嘉年華，係內門、旗山區一年一度宗教暨文化慶典盛事。', `organizer`='高雄市政府', `address`='內門南海紫竹寺', `start_date`='2023-02-25 00:00:00', `end_date`='2023-03-08 00:00:00', `location`='高雄市內門區', `latitude`=22.941761, `longitude`=120.461364, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/1fb82aa1-8c09-4ddf-af75-241af1f73f3a.jpg", "https://www.taiwan.net.tw/att/event/c7ee4373-1fd0-4e44-ba77-1ac131964321.jpg", "https://www.taiwan.net.tw/att/event/207fe3aa-8458-4d16-8273-f285cae0d95d.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081082', '2023宜蘭綠色博覽會', '宜蘭綠色博覽會於民國89年（西元2000年）創辦，初期以綠色生活、生態保育和友善農業作為活動主軸，透過主題概念展覽、戶外教學與遊憩娛樂，傳達對釉綠稻田、蒼鬱林木、山海湖河生態等環境友善觀念，形成一種宜蘭式的綠色悠遊底蘊。經過20多年演變，積累無數對綠色生活的嚮往與實踐，融合文化藝術展演，創造園藝花卉地景，紮根環保生態教育，扶植農漁業產業轉型升級，帶動觀光休閒旅宿人潮與地方繁盛發展，綠博在全國眾多主題節慶活動中獨樹一幟，是宜蘭縣春季著名的大型環境教育旗艦活動。', '宜蘭縣政府', '冬山河生態綠舟', '2023-03-31 00:00:00', '2023-05-14 00:00:00', '宜蘭縣冬山鄉', 24.638719, 121.78828, '無資料', 'http://igreen.ilantravel.com.tw/', '["https://www.taiwan.net.tw/att/event/b2f1cfec-fe92-45c0-8ede-ca192210f954.jpg", "https://www.taiwan.net.tw/att/event/873d75a8-7fb5-4195-babe-77d9ae9201ab.jpg", "https://www.taiwan.net.tw/att/event/0d79c73a-9518-4fef-ac77-1967b643eefe.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023宜蘭綠色博覽會', `description`='宜蘭綠色博覽會於民國89年（西元2000年）創辦，初期以綠色生活、生態保育和友善農業作為活動主軸，透過主題概念展覽、戶外教學與遊憩娛樂，傳達對釉綠稻田、蒼鬱林木、山海湖河生態等環境友善觀念，形成一種宜蘭式的綠色悠遊底蘊。經過20多年演變，積累無數對綠色生活的嚮往與實踐，融合文化藝術展演，創造園藝花卉地景，紮根環保生態教育，扶植農漁業產業轉型升級，帶動觀光休閒旅宿人潮與地方繁盛發展，綠博在全國眾多主題節慶活動中獨樹一幟，是宜蘭縣春季著名的大型環境教育旗艦活動。', `organizer`='宜蘭縣政府', `address`='冬山河生態綠舟', `start_date`='2023-03-31 00:00:00', `end_date`='2023-05-14 00:00:00', `location`='宜蘭縣冬山鄉', `latitude`=24.638719, `longitude`=121.78828, `ticket_price`='無資料', `source_url`='http://igreen.ilantravel.com.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/b2f1cfec-fe92-45c0-8ede-ca192210f954.jpg", "https://www.taiwan.net.tw/att/event/873d75a8-7fb5-4195-babe-77d9ae9201ab.jpg", "https://www.taiwan.net.tw/att/event/0d79c73a-9518-4fef-ac77-1967b643eefe.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081083', '2023臺灣國際熱氣球嘉年華', '自民國100年（西元2011年）開辦熱氣球嘉年華以來，開啟了臺灣空域休閒遊憩活動的新契機，臺灣國際熱氣球嘉年華已經成為最令人期待的夏日盛宴之一，活動更是年年挑戰紀錄，舉辦時間更長、規模更大，民國107年（西元2018年）更獲知名旅遊頻道（Travel Channel）入選世界12處令人驚豔的熱氣球節，熱氣球嘉年華每年於暑假熱鬧登場，除了可飽覽花東縱谷之美的熱氣球自由飛行及繫留體驗外，還可以享受以不同地景特色為景的熱氣球光雕音樂會，欣賞世界各國的造型熱氣球在藍天綠地下爭奇鬥艷。熱氣球嘉年華每年都會邀請各國吸睛造型球來參加活動，世界當紅的明星造型球如：米奇、小小兵、海綿寶寶、憤怒鳥&hellip;等皆受邀來過臺灣，只要天氣許可，遊客可以欣賞熱氣球開展、噴火、膨脹與立球的整個過程，而在立球完成後也會開放近距離合影留念。', '臺東縣政府', '鹿野高台', '2023-08-07 00:00:00', '2023-08-28 00:00:00', '臺東縣鹿野鄉', 22.926726, 121.126734, '無資料', 'https://balloontaiwan.taitung.gov.tw/zh-tw', '["https://www.taiwan.net.tw/att/event/25afebc9-a15d-4f66-b07c-7984fcb0385d.jpg", "https://www.taiwan.net.tw/att/event/9f4b12f2-d73f-4a45-b4c6-1daf868e4e60.jpg", "https://www.taiwan.net.tw/att/event/e7633c0f-1b8f-42e4-9e0b-e81798545873.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023臺灣國際熱氣球嘉年華', `description`='自民國100年（西元2011年）開辦熱氣球嘉年華以來，開啟了臺灣空域休閒遊憩活動的新契機，臺灣國際熱氣球嘉年華已經成為最令人期待的夏日盛宴之一，活動更是年年挑戰紀錄，舉辦時間更長、規模更大，民國107年（西元2018年）更獲知名旅遊頻道（Travel Channel）入選世界12處令人驚豔的熱氣球節，熱氣球嘉年華每年於暑假熱鬧登場，除了可飽覽花東縱谷之美的熱氣球自由飛行及繫留體驗外，還可以享受以不同地景特色為景的熱氣球光雕音樂會，欣賞世界各國的造型熱氣球在藍天綠地下爭奇鬥艷。熱氣球嘉年華每年都會邀請各國吸睛造型球來參加活動，世界當紅的明星造型球如：米奇、小小兵、海綿寶寶、憤怒鳥&hellip;等皆受邀來過臺灣，只要天氣許可，遊客可以欣賞熱氣球開展、噴火、膨脹與立球的整個過程，而在立球完成後也會開放近距離合影留念。', `organizer`='臺東縣政府', `address`='鹿野高台', `start_date`='2023-08-07 00:00:00', `end_date`='2023-08-28 00:00:00', `location`='臺東縣鹿野鄉', `latitude`=22.926726, `longitude`=121.126734, `ticket_price`='無資料', `source_url`='https://balloontaiwan.taitung.gov.tw/zh-tw', `image_url`='["https://www.taiwan.net.tw/att/event/25afebc9-a15d-4f66-b07c-7984fcb0385d.jpg", "https://www.taiwan.net.tw/att/event/9f4b12f2-d73f-4a45-b4c6-1daf868e4e60.jpg", "https://www.taiwan.net.tw/att/event/e7633c0f-1b8f-42e4-9e0b-e81798545873.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081084', '2023臺灣國際衝浪公開賽', '臺灣四面環海，擁有豐沛的海洋資源，其中臺東擁有全國最長176公里海岸線，在東北季風吹拂下，助長東河、金樽一帶浪勢，尤其金樽得天獨厚地形、風向與水質，成為全臺灣難得衝浪首選之地。臺東是臺灣唯一列入ASC和WSL的國際衝浪場地，自民國100年（西元2011年）舉辦以來，以國際標準最高規格及裁判群為目標，屢次吸引超過10個國家選手前來參與。透過衝浪運動，行銷水域運動，並且推廣台灣秋冬季節的另類玩法。藉由建立衝浪意象主題，辦理遊客深度活動體驗，豐富肢體體驗、腦力知識、互動為設計主軸，深化旅客水域衝浪體驗，遊客可以到活動現場親自欣賞國際選手的表演及國內好手競賽英姿，並到臺東的衝浪店體驗衝浪相關周邊活動，如直立單槳（SUP）、獨木舟&hellip;等非動力水域體驗活動，將臺東秋冬衝浪意象深植人心。透過衝浪賽事的行銷宣傳，讓國內外更有機會認識臺灣東海岸另一種風情，將臺東打造成為更富有熱情活力的國際衝浪聖地。', '臺東縣政府、世界衝浪聯盟', '金樽遊憩區', '2023-11-06 00:00:00', '2023-11-12 00:00:00', '臺東縣東河鄉', 22.945168, 121.279906, '無資料', 'https://www.taiwanopenofsurfing.org/', '["https://www.taiwan.net.tw/att/event/cbe4faf2-7179-410d-8410-4a7553a44090.jpg", "https://www.taiwan.net.tw/att/event/f0e64a83-53d8-44c6-a4f7-1b72ebd72fd2.jpg", "https://www.taiwan.net.tw/att/event/8918d21f-50e1-4aca-838c-730efe9f29b5.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023臺灣國際衝浪公開賽', `description`='臺灣四面環海，擁有豐沛的海洋資源，其中臺東擁有全國最長176公里海岸線，在東北季風吹拂下，助長東河、金樽一帶浪勢，尤其金樽得天獨厚地形、風向與水質，成為全臺灣難得衝浪首選之地。臺東是臺灣唯一列入ASC和WSL的國際衝浪場地，自民國100年（西元2011年）舉辦以來，以國際標準最高規格及裁判群為目標，屢次吸引超過10個國家選手前來參與。透過衝浪運動，行銷水域運動，並且推廣台灣秋冬季節的另類玩法。藉由建立衝浪意象主題，辦理遊客深度活動體驗，豐富肢體體驗、腦力知識、互動為設計主軸，深化旅客水域衝浪體驗，遊客可以到活動現場親自欣賞國際選手的表演及國內好手競賽英姿，並到臺東的衝浪店體驗衝浪相關周邊活動，如直立單槳（SUP）、獨木舟&hellip;等非動力水域體驗活動，將臺東秋冬衝浪意象深植人心。透過衝浪賽事的行銷宣傳，讓國內外更有機會認識臺灣東海岸另一種風情，將臺東打造成為更富有熱情活力的國際衝浪聖地。', `organizer`='臺東縣政府、世界衝浪聯盟', `address`='金樽遊憩區', `start_date`='2023-11-06 00:00:00', `end_date`='2023-11-12 00:00:00', `location`='臺東縣東河鄉', `latitude`=22.945168, `longitude`=121.279906, `ticket_price`='無資料', `source_url`='https://www.taiwanopenofsurfing.org/', `image_url`='["https://www.taiwan.net.tw/att/event/cbe4faf2-7179-410d-8410-4a7553a44090.jpg", "https://www.taiwan.net.tw/att/event/f0e64a83-53d8-44c6-a4f7-1b72ebd72fd2.jpg", "https://www.taiwan.net.tw/att/event/8918d21f-50e1-4aca-838c-730efe9f29b5.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081085', '2023金門中秋博狀元餅', '中秋博狀元餅活動在金門地區已是三百多年歷史的民俗文化活動，以科舉進程及追求人上人為博狀元餅遊戲之寄寓發展，透過遊戲普及民間。亦藉由此活動，吸引國際觀光客一起來金門體驗閩鄉傳統民俗之趣味，每年都能吸引到近千名國外旅客蒞臨金門旅遊。', '金門縣政府', '清金門鎮總兵署', '2023-08-29 00:00:00', '2023-09-29 00:00:00', '金門縣金城鎮', 24.432299, 118.318408, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/745b59de-f797-4234-ab8f-9084d363dac1.jpg", "https://www.taiwan.net.tw/att/event/f2a14de3-a5c1-4c05-903b-f98a28522f2f.jpg", "https://www.taiwan.net.tw/att/event/518b5221-d45c-4dfe-9ec9-cec45248646f.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023金門中秋博狀元餅', `description`='中秋博狀元餅活動在金門地區已是三百多年歷史的民俗文化活動，以科舉進程及追求人上人為博狀元餅遊戲之寄寓發展，透過遊戲普及民間。亦藉由此活動，吸引國際觀光客一起來金門體驗閩鄉傳統民俗之趣味，每年都能吸引到近千名國外旅客蒞臨金門旅遊。', `organizer`='金門縣政府', `address`='清金門鎮總兵署', `start_date`='2023-08-29 00:00:00', `end_date`='2023-09-29 00:00:00', `location`='金門縣金城鎮', `latitude`=24.432299, `longitude`=118.318408, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/745b59de-f797-4234-ab8f-9084d363dac1.jpg", "https://www.taiwan.net.tw/att/event/f2a14de3-a5c1-4c05-903b-f98a28522f2f.jpg", "https://www.taiwan.net.tw/att/event/518b5221-d45c-4dfe-9ec9-cec45248646f.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081086', '2023澎湖國際海上花火節', '澎湖國際海上花火節於觀音亭園區施放，美麗的煙火與得天獨厚的海灣環境、浪漫的西瀛虹橋相得益彰，由於煙火施放地點與觀眾觀賞區只有約300公尺距離，遊客可以近距離欣賞煙火，高空煙火在海上夜空中震撼演出，仿佛就在你眼前觸手可及，獨特的臨場震撼感，為澎湖國際海上花火節最吸引人的地方，相較於其他縣市觀光花火活動，非常具有產品獨特性。除了炫麗煙火外，舞台活動則邀請許多知名藝人及在地表演團體輪番精采演出，加上觀賞區腹地寬廣、無須擔憂交通阻塞等問題，遊客可盡情沉沁在悠閒浪漫的氛圍中。澎湖旅遊資源豐富，除了美麗的自然景觀及多元文化的體驗，還可品嚐當令肥美的海鮮美食，夜晚可欣賞澎湖國際海上花火節璀燦的煙火在星空下的熱情與浪漫。', '澎湖縣政府', '觀音亭親水遊憩區', '2023-04-20 00:00:00', '2023-06-29 00:00:00', '澎湖縣馬公市', 23.568645, 119.562431, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/c39ac6c1-98c1-425f-a021-dc077f752e0c.jpg", "https://www.taiwan.net.tw/att/event/b2172127-d526-400a-800b-e8e840dd94fc.jpg", "https://www.taiwan.net.tw/att/event/51ec1b91-8803-476a-b696-3b102df4b060.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023澎湖國際海上花火節', `description`='澎湖國際海上花火節於觀音亭園區施放，美麗的煙火與得天獨厚的海灣環境、浪漫的西瀛虹橋相得益彰，由於煙火施放地點與觀眾觀賞區只有約300公尺距離，遊客可以近距離欣賞煙火，高空煙火在海上夜空中震撼演出，仿佛就在你眼前觸手可及，獨特的臨場震撼感，為澎湖國際海上花火節最吸引人的地方，相較於其他縣市觀光花火活動，非常具有產品獨特性。除了炫麗煙火外，舞台活動則邀請許多知名藝人及在地表演團體輪番精采演出，加上觀賞區腹地寬廣、無須擔憂交通阻塞等問題，遊客可盡情沉沁在悠閒浪漫的氛圍中。澎湖旅遊資源豐富，除了美麗的自然景觀及多元文化的體驗，還可品嚐當令肥美的海鮮美食，夜晚可欣賞澎湖國際海上花火節璀燦的煙火在星空下的熱情與浪漫。', `organizer`='澎湖縣政府', `address`='觀音亭親水遊憩區', `start_date`='2023-04-20 00:00:00', `end_date`='2023-06-29 00:00:00', `location`='澎湖縣馬公市', `latitude`=23.568645, `longitude`=119.562431, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/c39ac6c1-98c1-425f-a021-dc077f752e0c.jpg", "https://www.taiwan.net.tw/att/event/b2172127-d526-400a-800b-e8e840dd94fc.jpg", "https://www.taiwan.net.tw/att/event/51ec1b91-8803-476a-b696-3b102df4b060.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081087', '2023臺北時裝週', '為扶植時尚產業創新發展及提升我國時尚產業國際能見度與形象，共同推動時尚產業與影視音、藝術等產業跨界合作，進而打造臺灣成為亞洲時尚樞紐，文化部於民國107年（西元2018年）起辦理國家級時裝週，希將臺灣時尚產業推上國際舞臺，期建立屬於臺灣之時尚產業交流平臺，讓「臺北時裝週」成為亞洲或甚至全球指標性時裝週。', '文化部、經濟部、教育部、原住民族委員會', '臺北表演藝術中心', '2023-10-01 00:00:00', '2023-10-31 00:00:00', '臺北市士林區', 25.084697, 121.524401, '無資料', 'https://tpefw.com/', '["https://www.taiwan.net.tw/att/event/ebc7eb4f-b5cd-449e-9d82-d84e731f2e98.jpg", "https://www.taiwan.net.tw/att/event/868ae933-a5da-455c-9601-e994af6049de.jpg", "https://www.taiwan.net.tw/att/event/cc966752-8f8c-4f3d-9bb5-f544bd069db7.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023臺北時裝週', `description`='為扶植時尚產業創新發展及提升我國時尚產業國際能見度與形象，共同推動時尚產業與影視音、藝術等產業跨界合作，進而打造臺灣成為亞洲時尚樞紐，文化部於民國107年（西元2018年）起辦理國家級時裝週，希將臺灣時尚產業推上國際舞臺，期建立屬於臺灣之時尚產業交流平臺，讓「臺北時裝週」成為亞洲或甚至全球指標性時裝週。', `organizer`='文化部、經濟部、教育部、原住民族委員會', `address`='臺北表演藝術中心', `start_date`='2023-10-01 00:00:00', `end_date`='2023-10-31 00:00:00', `location`='臺北市士林區', `latitude`=25.084697, `longitude`=121.524401, `ticket_price`='無資料', `source_url`='https://tpefw.com/', `image_url`='["https://www.taiwan.net.tw/att/event/ebc7eb4f-b5cd-449e-9d82-d84e731f2e98.jpg", "https://www.taiwan.net.tw/att/event/868ae933-a5da-455c-9601-e994af6049de.jpg", "https://www.taiwan.net.tw/att/event/cc966752-8f8c-4f3d-9bb5-f544bd069db7.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081088', '2023臺灣文化創意設計博覽會', '臺灣文博會於民國99年（西元2010年）首辦，至今無論於參展單位、參與國家數、觀展人次及所帶動的產業效益等，皆已有倍數之成長，已成為亞洲最具規模的文創展會之一。每年臺灣文博會透過議題式策展，引領社會大眾、文創產業從業者進行文化思考與對話外，還有各式文創設計品牌、圖像授權IP齊聚，辦理如新品發表、粉絲見面會等活動，呈現臺灣文創軟實力。', '文化部', '華山1914文創園區', '2023-09-22 00:00:00', '2023-10-01 00:00:00', '臺北市中正區', 25.04413, 121.529399, '無資料', 'https://www.creativexpo.tw/zh/', '["https://www.taiwan.net.tw/att/event/c19b3109-e446-4cf2-916c-5447079174c4.jpg", "https://www.taiwan.net.tw/att/event/e5a7c2b2-214b-43c3-ac10-8b12c5f54302.jpg", "https://www.taiwan.net.tw/att/event/58de1132-0fc7-477b-80f7-51c40a84739a.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023臺灣文化創意設計博覽會', `description`='臺灣文博會於民國99年（西元2010年）首辦，至今無論於參展單位、參與國家數、觀展人次及所帶動的產業效益等，皆已有倍數之成長，已成為亞洲最具規模的文創展會之一。每年臺灣文博會透過議題式策展，引領社會大眾、文創產業從業者進行文化思考與對話外，還有各式文創設計品牌、圖像授權IP齊聚，辦理如新品發表、粉絲見面會等活動，呈現臺灣文創軟實力。', `organizer`='文化部', `address`='華山1914文創園區', `start_date`='2023-09-22 00:00:00', `end_date`='2023-10-01 00:00:00', `location`='臺北市中正區', `latitude`=25.04413, `longitude`=121.529399, `ticket_price`='無資料', `source_url`='https://www.creativexpo.tw/zh/', `image_url`='["https://www.taiwan.net.tw/att/event/c19b3109-e446-4cf2-916c-5447079174c4.jpg", "https://www.taiwan.net.tw/att/event/e5a7c2b2-214b-43c3-ac10-8b12c5f54302.jpg", "https://www.taiwan.net.tw/att/event/58de1132-0fc7-477b-80f7-51c40a84739a.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081089', '2023台北國際書展', '書籍為民族文化積累的結晶，「台北國際書展」為台灣出版產業年度盛事，兼具閱讀推廣、國際交流、出版專業等功能，於台灣尊重言論及重視出版自由的社會氛圍形塑下，台北國際書展可說是華文世界最多元、最自由的書展。台北國際書展將於111年邁入第30屆，自2015年起獲選入交通部觀光署「台灣觀光年曆」，每年台北國際書展以各種不同主題，帶領民眾進入閱讀的領域。並由各國輪流擔任書展主題國，並邀請各國出版社參加書展，使不同文化在書展會場中交流互動。自2017年起，本部推動延長開展時間、延伸閱讀場域、改造展場氛圍、強化出版專業，並降低場租費用等措施，加速台北國際書展轉型成一閱讀體驗場域，促進作者與讀者間互動，讓參觀台北國際書展不僅為單純的購書場合，更是知識與文化交流的最佳場域。', '文化部', '台北世界貿易中心展覽一館', '2023-01-31 00:00:00', '2023-02-05 00:00:00', '臺北市信義區', 25.033155, 121.562347, '無資料', 'https://www.tibe.org.tw/', '["https://www.taiwan.net.tw/att/event/1d3e8f5d-48ed-403c-8680-c2fd9dbf0c1f.jpg", "https://www.taiwan.net.tw/att/event/ba2fed03-adb6-4839-97d4-b0a849844772.jpg", "https://www.taiwan.net.tw/att/event/d9a067c3-7be9-4b90-b4d6-b2496f42862d.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023台北國際書展', `description`='書籍為民族文化積累的結晶，「台北國際書展」為台灣出版產業年度盛事，兼具閱讀推廣、國際交流、出版專業等功能，於台灣尊重言論及重視出版自由的社會氛圍形塑下，台北國際書展可說是華文世界最多元、最自由的書展。台北國際書展將於111年邁入第30屆，自2015年起獲選入交通部觀光署「台灣觀光年曆」，每年台北國際書展以各種不同主題，帶領民眾進入閱讀的領域。並由各國輪流擔任書展主題國，並邀請各國出版社參加書展，使不同文化在書展會場中交流互動。自2017年起，本部推動延長開展時間、延伸閱讀場域、改造展場氛圍、強化出版專業，並降低場租費用等措施，加速台北國際書展轉型成一閱讀體驗場域，促進作者與讀者間互動，讓參觀台北國際書展不僅為單純的購書場合，更是知識與文化交流的最佳場域。', `organizer`='文化部', `address`='台北世界貿易中心展覽一館', `start_date`='2023-01-31 00:00:00', `end_date`='2023-02-05 00:00:00', `location`='臺北市信義區', `latitude`=25.033155, `longitude`=121.562347, `ticket_price`='無資料', `source_url`='https://www.tibe.org.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/1d3e8f5d-48ed-403c-8680-c2fd9dbf0c1f.jpg", "https://www.taiwan.net.tw/att/event/ba2fed03-adb6-4839-97d4-b0a849844772.jpg", "https://www.taiwan.net.tw/att/event/d9a067c3-7be9-4b90-b4d6-b2496f42862d.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081090', '2023西藏文化藝術節', '為展現臺灣是多元族群、多元文化的國家，文化部每年舉辦以「西藏文化藝術節」為主題之系列活動，以促進文化扎根，擴大民間參與，結合公私部門、學術界、藝文界及廣大社會群體之能量，透過創新、靈活之思維推出各項措施，期建立多元民族文化藝術傳承及發展對話交流平臺，創造具國際性、獨特性、永續性之臺灣特色的西藏文化嘉年華。', '文化部', '臺灣戲曲中心', '2023-09-23 00:00:00', '2023-09-24 00:00:00', '臺北市士林區', 25.102276, 121.519778, '無資料', 'https://tibetanfestival.moc.gov.tw/index/zh-tw', '["https://www.taiwan.net.tw/att/event/002d8707-d0dc-4fb9-9390-15b4e8500d13.jpg", "https://www.taiwan.net.tw/att/event/5f7e37ca-39ef-4308-aff2-dbda2ac8da48.jpg", "https://www.taiwan.net.tw/att/event/92fe882d-510d-4489-8598-b0c8ce263783.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023西藏文化藝術節', `description`='為展現臺灣是多元族群、多元文化的國家，文化部每年舉辦以「西藏文化藝術節」為主題之系列活動，以促進文化扎根，擴大民間參與，結合公私部門、學術界、藝文界及廣大社會群體之能量，透過創新、靈活之思維推出各項措施，期建立多元民族文化藝術傳承及發展對話交流平臺，創造具國際性、獨特性、永續性之臺灣特色的西藏文化嘉年華。', `organizer`='文化部', `address`='臺灣戲曲中心', `start_date`='2023-09-23 00:00:00', `end_date`='2023-09-24 00:00:00', `location`='臺北市士林區', `latitude`=25.102276, `longitude`=121.519778, `ticket_price`='無資料', `source_url`='https://tibetanfestival.moc.gov.tw/index/zh-tw', `image_url`='["https://www.taiwan.net.tw/att/event/002d8707-d0dc-4fb9-9390-15b4e8500d13.jpg", "https://www.taiwan.net.tw/att/event/5f7e37ca-39ef-4308-aff2-dbda2ac8da48.jpg", "https://www.taiwan.net.tw/att/event/92fe882d-510d-4489-8598-b0c8ce263783.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081091', '2023 TIFA台灣國際藝術節', '台灣國際藝術節（Taiwan International Festival of Arts，簡稱TIFA）為台灣一年一度最重要的藝術節慶、亞洲最具亮點的藝文盛會。國家表演藝術中心轄下國家兩廳院、臺中國家歌劇院、衛武營國家藝術文化中心共同舉辦，串連台灣北、中、南三大國家劇場，各自發展主題特色，透過藝術的舞台與世界同步，讓國內的觀眾放眼世界潮流，更將台灣的藝術能量穿透國際。TIFA不僅是國際藝術家匯聚交流的舞台，更是精采紛呈、讓觀眾每一年都引頸期盼的藝術慶典。', '國家兩廳院、臺中國家歌劇院、衛武營國家藝術文化中心', '國家兩廳院', '2023-02-18 00:00:00', '2023-05-14 00:00:00', '臺北市中正區', 25.036885, 121.51879, '無資料', 'https://npac-ntch.org/programs/series/tifa/B0CFFA8C2CEA490B9F1C39FA1AA3EFCA', '["https://www.taiwan.net.tw/att/event/9d5506c0-a34f-4328-b429-3c22188cb798.jpg", "https://www.taiwan.net.tw/att/event/ff9a0af5-5976-4693-ac2f-36e2f9ef406a.jpg", "https://www.taiwan.net.tw/att/event/96f2b6e3-ba55-4d42-af03-aef7fa27eee1.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023 TIFA台灣國際藝術節', `description`='台灣國際藝術節（Taiwan International Festival of Arts，簡稱TIFA）為台灣一年一度最重要的藝術節慶、亞洲最具亮點的藝文盛會。國家表演藝術中心轄下國家兩廳院、臺中國家歌劇院、衛武營國家藝術文化中心共同舉辦，串連台灣北、中、南三大國家劇場，各自發展主題特色，透過藝術的舞台與世界同步，讓國內的觀眾放眼世界潮流，更將台灣的藝術能量穿透國際。TIFA不僅是國際藝術家匯聚交流的舞台，更是精采紛呈、讓觀眾每一年都引頸期盼的藝術慶典。', `organizer`='國家兩廳院、臺中國家歌劇院、衛武營國家藝術文化中心', `address`='國家兩廳院', `start_date`='2023-02-18 00:00:00', `end_date`='2023-05-14 00:00:00', `location`='臺北市中正區', `latitude`=25.036885, `longitude`=121.51879, `ticket_price`='無資料', `source_url`='https://npac-ntch.org/programs/series/tifa/B0CFFA8C2CEA490B9F1C39FA1AA3EFCA', `image_url`='["https://www.taiwan.net.tw/att/event/9d5506c0-a34f-4328-b429-3c22188cb798.jpg", "https://www.taiwan.net.tw/att/event/ff9a0af5-5976-4693-ac2f-36e2f9ef406a.jpg", "https://www.taiwan.net.tw/att/event/96f2b6e3-ba55-4d42-af03-aef7fa27eee1.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081092', '2023 Art Taipei 台北國際藝術博覽會', 'ART TAIPEI 台北國際藝術博覽會，每年透過邀請海內外畫廊的參展，帶來許多國際藝壇的重要作品，增進海內外藝術交流，並且推廣藝術生活和全民收藏。ART TAIPEI 台北國際藝術博覽會已是各畫廊和亞洲地區重要收藏家、畫廊、媒體互動的重要管道。有鑑於此，畫廊協會將會抱持著對藝術熱愛的精神，持續為臺灣藝術產業努力，不僅提供藝術家與藝術市場創造平台，更協助亞洲畫廊與國際畫廊多元交流。', '社團法人中華民國畫廊協會、文化部、中華民國對外貿易發展協會', '台北世界貿易中心展覽一館', '2023-10-20 00:00:00', '2023-10-23 00:00:00', '臺北市信義區', 25.033155, 121.562347, '無資料', 'https://2023.art-taipei.com/taipei/tw/', '["https://www.taiwan.net.tw/att/event/1c7b573e-2466-4eb9-a44e-c10c4872874e.jpg", "https://www.taiwan.net.tw/att/event/b3291546-7262-4bbd-8b97-977ff6978103.jpg", "https://www.taiwan.net.tw/att/event/97b8cac2-f3cf-4393-9496-fbb4f4514672.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023 Art Taipei 台北國際藝術博覽會', `description`='ART TAIPEI 台北國際藝術博覽會，每年透過邀請海內外畫廊的參展，帶來許多國際藝壇的重要作品，增進海內外藝術交流，並且推廣藝術生活和全民收藏。ART TAIPEI 台北國際藝術博覽會已是各畫廊和亞洲地區重要收藏家、畫廊、媒體互動的重要管道。有鑑於此，畫廊協會將會抱持著對藝術熱愛的精神，持續為臺灣藝術產業努力，不僅提供藝術家與藝術市場創造平台，更協助亞洲畫廊與國際畫廊多元交流。', `organizer`='社團法人中華民國畫廊協會、文化部、中華民國對外貿易發展協會', `address`='台北世界貿易中心展覽一館', `start_date`='2023-10-20 00:00:00', `end_date`='2023-10-23 00:00:00', `location`='臺北市信義區', `latitude`=25.033155, `longitude`=121.562347, `ticket_price`='無資料', `source_url`='https://2023.art-taipei.com/taipei/tw/', `image_url`='["https://www.taiwan.net.tw/att/event/1c7b573e-2466-4eb9-a44e-c10c4872874e.jpg", "https://www.taiwan.net.tw/att/event/b3291546-7262-4bbd-8b97-977ff6978103.jpg", "https://www.taiwan.net.tw/att/event/97b8cac2-f3cf-4393-9496-fbb4f4514672.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081093', '2023浪漫台三線藝術季', '為落實以創新為傳承、以發展為保存，珍視客家人文地景，詮釋客家文化歷史，並展現客家文藝復興成果，故辦理「浪漫台三線藝術季」以群體意識凝聚在地能量，喚醒客家族群對客家文化認同的同時，結合藝術進行地方再造。※為配合世界客家博覽會相關活動辦理，2022浪漫台三線藝術季延至2023年7月辦理。', '客家委員會', '松山文創園區', '2023-06-24 00:00:00', '2023-08-27 00:00:00', '臺北市信義區', 25.043692, 121.560641, '無資料', 'https://www.romantic3.tw/', '["https://www.taiwan.net.tw/att/event/a1d7c1aa-07f8-4649-84d8-74c8c92a886e.jpg", "https://www.taiwan.net.tw/att/event/f895e614-21fd-4809-865e-77a2bae7839c.jpg", "https://www.taiwan.net.tw/att/event/ceee18ab-29d0-4629-ac65-b61ae00cde28.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023浪漫台三線藝術季', `description`='為落實以創新為傳承、以發展為保存，珍視客家人文地景，詮釋客家文化歷史，並展現客家文藝復興成果，故辦理「浪漫台三線藝術季」以群體意識凝聚在地能量，喚醒客家族群對客家文化認同的同時，結合藝術進行地方再造。※為配合世界客家博覽會相關活動辦理，2022浪漫台三線藝術季延至2023年7月辦理。', `organizer`='客家委員會', `address`='松山文創園區', `start_date`='2023-06-24 00:00:00', `end_date`='2023-08-27 00:00:00', `location`='臺北市信義區', `latitude`=25.043692, `longitude`=121.560641, `ticket_price`='無資料', `source_url`='https://www.romantic3.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/a1d7c1aa-07f8-4649-84d8-74c8c92a886e.jpg", "https://www.taiwan.net.tw/att/event/f895e614-21fd-4809-865e-77a2bae7839c.jpg", "https://www.taiwan.net.tw/att/event/ceee18ab-29d0-4629-ac65-b61ae00cde28.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081094', '2023客家桐花祭', '客家桐花祭，以祭、生活美學（創作、表演、生活型態演示）、旅遊（桐花步道、小旅行、旅遊攻略）、產業（地方品牌-農產加工、手工藝品）及行銷（製作資源中心、季節紀念產品、桐花氣象、桐花祭夥伴）等五大面向轉型辦理，輔以生活美學演示形塑客庄小旅行品牌，並透過整體行銷，讓客家文化的美從生活中體現，讓旅人在桐花盛開的時節，自由行尞遶山花，回歸桐花祭初衷。客委會為持續推廣桐花小旅行活動，特建置IOT桐花監測設備，透過蒐集地區濕度、雨量、風向、風速、日照等相關環境數據，記錄桐花生長狀況，經比對歷史開花資料建構桐花開花預測模型，並結合中央氣象署、農業部林業及自然保育署網站共同露出桐花花況資訊，以利民眾取得即時花況提前安排行程；桐花季節之開花資訊請見桐花花況預測平台。', '客家委員會', '暖暖東勢坑產業步道', '2023-04-14 00:00:00', '2023-05-10 00:00:00', '基隆市暖暖區', 25.076813, 121.755034, '無資料', 'https://tung.romantichakka.com/home?lang=ch', '["https://www.taiwan.net.tw/att/event/f24a0dcc-e4c1-47d7-b4fa-5799a0dd3e08.jpg", "https://www.taiwan.net.tw/att/event/be2d8052-8b51-4a00-a829-5147dc2bb64f.jpg", "https://www.taiwan.net.tw/att/event/305537be-e874-4b0c-8469-dec88eed925b.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023客家桐花祭', `description`='客家桐花祭，以祭、生活美學（創作、表演、生活型態演示）、旅遊（桐花步道、小旅行、旅遊攻略）、產業（地方品牌-農產加工、手工藝品）及行銷（製作資源中心、季節紀念產品、桐花氣象、桐花祭夥伴）等五大面向轉型辦理，輔以生活美學演示形塑客庄小旅行品牌，並透過整體行銷，讓客家文化的美從生活中體現，讓旅人在桐花盛開的時節，自由行尞遶山花，回歸桐花祭初衷。客委會為持續推廣桐花小旅行活動，特建置IOT桐花監測設備，透過蒐集地區濕度、雨量、風向、風速、日照等相關環境數據，記錄桐花生長狀況，經比對歷史開花資料建構桐花開花預測模型，並結合中央氣象署、農業部林業及自然保育署網站共同露出桐花花況資訊，以利民眾取得即時花況提前安排行程；桐花季節之開花資訊請見桐花花況預測平台。', `organizer`='客家委員會', `address`='暖暖東勢坑產業步道', `start_date`='2023-04-14 00:00:00', `end_date`='2023-05-10 00:00:00', `location`='基隆市暖暖區', `latitude`=25.076813, `longitude`=121.755034, `ticket_price`='無資料', `source_url`='https://tung.romantichakka.com/home?lang=ch', `image_url`='["https://www.taiwan.net.tw/att/event/f24a0dcc-e4c1-47d7-b4fa-5799a0dd3e08.jpg", "https://www.taiwan.net.tw/att/event/be2d8052-8b51-4a00-a829-5147dc2bb64f.jpg", "https://www.taiwan.net.tw/att/event/305537be-e874-4b0c-8469-dec88eed925b.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081096', '2023野柳石光-夜訪女王', '野柳地質公園因獨特地質景觀與優質遊憩品質享譽國際，每年吸引大量國際旅客到訪，更受到國際媒體相繼報導，美國CNN曾譽為媲美太空以及獲選亞洲十大熱門打卡點。此外「2020野柳石光-夜訪女王」活動於岩壁播放「野柳異想樂園」動畫片榮獲2021德國柏林旅展（ITB）觀光多媒體金城門獎生態旅遊類五顆星首獎殊榮，再次將野柳地質公園推行於國際舞台。「野柳石光-夜訪女王」以夜間觀賞奇石地景，營造野柳夜間浪漫光環境為活動主軸，規劃具主題故事之光影互動及特效，搭配日間藝文表演、環境教育、地景保育課程等系列活動，結合周邊產業共同參與，形塑活動獨一無二與永續的價值，帶動野柳周邊觀光產值。活動藉由各種管道宣傳，並邀請國際地質公園成員共同參與，將活動推廣至國際旅遊市場，增加活動知名度亦深化野柳地質公園的國際品牌價值與無可取代的旅遊地意象。', '交通部觀光署北海岸及觀音山國家風景區管理處', '野柳地質公園', '2023-06-30 00:00:00', '2023-07-16 00:00:00', '新北市萬里區', 25.204757, 121.689617, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/46b8c03f-07b4-493c-860e-9899bb41f308.jpg", "https://www.taiwan.net.tw/att/event/a6b1b348-03d1-4b7c-9e9e-dac001bcaa69.jpg", "https://www.taiwan.net.tw/att/event/3462d621-2d7b-4ca2-94dc-539ec050574f.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023野柳石光-夜訪女王', `description`='野柳地質公園因獨特地質景觀與優質遊憩品質享譽國際，每年吸引大量國際旅客到訪，更受到國際媒體相繼報導，美國CNN曾譽為媲美太空以及獲選亞洲十大熱門打卡點。此外「2020野柳石光-夜訪女王」活動於岩壁播放「野柳異想樂園」動畫片榮獲2021德國柏林旅展（ITB）觀光多媒體金城門獎生態旅遊類五顆星首獎殊榮，再次將野柳地質公園推行於國際舞台。「野柳石光-夜訪女王」以夜間觀賞奇石地景，營造野柳夜間浪漫光環境為活動主軸，規劃具主題故事之光影互動及特效，搭配日間藝文表演、環境教育、地景保育課程等系列活動，結合周邊產業共同參與，形塑活動獨一無二與永續的價值，帶動野柳周邊觀光產值。活動藉由各種管道宣傳，並邀請國際地質公園成員共同參與，將活動推廣至國際旅遊市場，增加活動知名度亦深化野柳地質公園的國際品牌價值與無可取代的旅遊地意象。', `organizer`='交通部觀光署北海岸及觀音山國家風景區管理處', `address`='野柳地質公園', `start_date`='2023-06-30 00:00:00', `end_date`='2023-07-16 00:00:00', `location`='新北市萬里區', `latitude`=25.204757, `longitude`=121.689617, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/46b8c03f-07b4-493c-860e-9899bb41f308.jpg", "https://www.taiwan.net.tw/att/event/a6b1b348-03d1-4b7c-9e9e-dac001bcaa69.jpg", "https://www.taiwan.net.tw/att/event/3462d621-2d7b-4ca2-94dc-539ec050574f.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081097', '2023鷹揚八卦-八卦山賞鷹活動', '每年到了春天，灰面鵟鷹就會在三月到四月期間，由度冬地北返過境八卦山，中部地區民眾稱為「南路鷹」或「清明鳥」，為了長期守護灰面鵟鷹，彰化縣野鳥學會與熱情的夥伴們，取其灰面鵟「鷹」振翅飛「揚」於「八卦」山之意，特訂活動名稱為「鷹揚八卦」。', '參山國家風景區管理處、彰化縣政府、農業部林業及自然保育署南投林區管理處、農業部水土保持局南投分局', '八卦山脈生態遊客中心', '2023-03-18 00:00:00', '2023-06-30 00:00:00', '彰化縣彰化市', 24.0785, 120.555636, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/9d1842f9-1931-4515-b31e-4210ad2ae925.jpg", "https://www.taiwan.net.tw/att/event/f5b3bb16-5672-4150-8225-bbf568d9cb60.jpg", "https://www.taiwan.net.tw/att/event/1e3b2c4b-b91e-40f7-b9e1-13e4f13f3120.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023鷹揚八卦-八卦山賞鷹活動', `description`='每年到了春天，灰面鵟鷹就會在三月到四月期間，由度冬地北返過境八卦山，中部地區民眾稱為「南路鷹」或「清明鳥」，為了長期守護灰面鵟鷹，彰化縣野鳥學會與熱情的夥伴們，取其灰面鵟「鷹」振翅飛「揚」於「八卦」山之意，特訂活動名稱為「鷹揚八卦」。', `organizer`='參山國家風景區管理處、彰化縣政府、農業部林業及自然保育署南投林區管理處、農業部水土保持局南投分局', `address`='八卦山脈生態遊客中心', `start_date`='2023-03-18 00:00:00', `end_date`='2023-06-30 00:00:00', `location`='彰化縣彰化市', `latitude`=24.0785, `longitude`=120.555636, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/9d1842f9-1931-4515-b31e-4210ad2ae925.jpg", "https://www.taiwan.net.tw/att/event/f5b3bb16-5672-4150-8225-bbf568d9cb60.jpg", "https://www.taiwan.net.tw/att/event/1e3b2c4b-b91e-40f7-b9e1-13e4f13f3120.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081098', '2023日月潭Come!BikeDay花火音樂嘉年華', '日月潭花火音樂嘉年華系列活動自民國97年（西元2008年）起舉辦，從初期的煙火、交響樂、鼓樂、舞蹈、藝文展覽，逐漸導入自行車、馬拉松、定向越野、紅茶產業文化、集團結婚、公益活動等多元題材，發展為一系列之高品質戶外展演及觀光活動，多年來深獲各界好評，並為日月潭嘉年華系列活動奠定深刻之「藝文表演」與「運動休閒」品牌旅遊印象。日月潭花火音樂嘉年華系列活動將持續以音樂藝術、運動休閒、在地產業文化等活動特色與傳統為主軸，延續「Come!BikeDay自行車」及「大型戶外花火音樂會」活動雙核心亮點，以創新發展豐富各場次活動主題與內容，並持續強化與其他公私部門合作，引入民間企業、團體之資源，加強國際交流行銷推廣合作等，以吸引更多國內外旅客到訪，並帶給遊客全新旅遊體驗與深刻印象，更為台灣整體觀光產業發展進一步創造效益。', '交通部觀光署日月潭國家風景區管理處', '水社碼頭', '2023-10-05 00:00:00', '2023-11-18 00:00:00', '南投縣魚池鄉', 23.864501, 120.911917, '無資料', 'https://www.sunmoonlake.gov.tw/activities/musicfestival/Index.aspx?l=1', '["https://www.taiwan.net.tw/att/event/f4f08263-5001-40e3-9ab7-0d25748d8241.jpg", "https://www.taiwan.net.tw/att/event/2e9d2b48-baab-45c5-8daf-929270c382f9.jpg", "https://www.taiwan.net.tw/att/event/35d41cea-079c-4339-8cbd-347682797e7e.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023日月潭Come!BikeDay花火音樂嘉年華', `description`='日月潭花火音樂嘉年華系列活動自民國97年（西元2008年）起舉辦，從初期的煙火、交響樂、鼓樂、舞蹈、藝文展覽，逐漸導入自行車、馬拉松、定向越野、紅茶產業文化、集團結婚、公益活動等多元題材，發展為一系列之高品質戶外展演及觀光活動，多年來深獲各界好評，並為日月潭嘉年華系列活動奠定深刻之「藝文表演」與「運動休閒」品牌旅遊印象。日月潭花火音樂嘉年華系列活動將持續以音樂藝術、運動休閒、在地產業文化等活動特色與傳統為主軸，延續「Come!BikeDay自行車」及「大型戶外花火音樂會」活動雙核心亮點，以創新發展豐富各場次活動主題與內容，並持續強化與其他公私部門合作，引入民間企業、團體之資源，加強國際交流行銷推廣合作等，以吸引更多國內外旅客到訪，並帶給遊客全新旅遊體驗與深刻印象，更為台灣整體觀光產業發展進一步創造效益。', `organizer`='交通部觀光署日月潭國家風景區管理處', `address`='水社碼頭', `start_date`='2023-10-05 00:00:00', `end_date`='2023-11-18 00:00:00', `location`='南投縣魚池鄉', `latitude`=23.864501, `longitude`=120.911917, `ticket_price`='無資料', `source_url`='https://www.sunmoonlake.gov.tw/activities/musicfestival/Index.aspx?l=1', `image_url`='["https://www.taiwan.net.tw/att/event/f4f08263-5001-40e3-9ab7-0d25748d8241.jpg", "https://www.taiwan.net.tw/att/event/2e9d2b48-baab-45c5-8daf-929270c382f9.jpg", "https://www.taiwan.net.tw/att/event/35d41cea-079c-4339-8cbd-347682797e7e.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081099', '2023阿里山神木下婚禮', '「阿里山神木下婚禮」除聚焦主活動及貳部曲「阿里山星光下婚禮」，也將阿里山的美景、雋永的森林鐵路、千年屹立不搖的神木、傳統的鄒族文化及多元的在地產業推向國際舞台，打造戀人至阿里山約會、婚拍及蜜月的難忘浪漫回憶，吸引國內外旅客至阿里山體驗浪漫之旅。    星光下婚禮：3月13日至14日    神木下婚禮：10月', '交通部觀光署阿里山國家風景區管理處', '阿里山國家森林遊樂區-香林神木', '2023-10-01 00:00:00', '2023-10-31 00:00:00', '嘉義縣阿里山鄉', 23.51735, 120.80813, '無資料', 'https://www.ali-nsa.net/zh-tw/event/calendardetail/2823', '["https://www.taiwan.net.tw/att/event/9c742780-d584-4882-809e-d4f4a6eb57e9.jpg", "https://www.taiwan.net.tw/att/event/e7acc8d7-b66b-46a6-95cd-670d29705094.jpg", "https://www.taiwan.net.tw/att/event/3abc1e5d-65a4-4448-bda7-2280233a6f85.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023阿里山神木下婚禮', `description`='「阿里山神木下婚禮」除聚焦主活動及貳部曲「阿里山星光下婚禮」，也將阿里山的美景、雋永的森林鐵路、千年屹立不搖的神木、傳統的鄒族文化及多元的在地產業推向國際舞台，打造戀人至阿里山約會、婚拍及蜜月的難忘浪漫回憶，吸引國內外旅客至阿里山體驗浪漫之旅。    星光下婚禮：3月13日至14日    神木下婚禮：10月', `organizer`='交通部觀光署阿里山國家風景區管理處', `address`='阿里山國家森林遊樂區-香林神木', `start_date`='2023-10-01 00:00:00', `end_date`='2023-10-31 00:00:00', `location`='嘉義縣阿里山鄉', `latitude`=23.51735, `longitude`=120.80813, `ticket_price`='無資料', `source_url`='https://www.ali-nsa.net/zh-tw/event/calendardetail/2823', `image_url`='["https://www.taiwan.net.tw/att/event/9c742780-d584-4882-809e-d4f4a6eb57e9.jpg", "https://www.taiwan.net.tw/att/event/e7acc8d7-b66b-46a6-95cd-670d29705094.jpg", "https://www.taiwan.net.tw/att/event/3abc1e5d-65a4-4448-bda7-2280233a6f85.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081100', '2023鯤鯓王平安鹽祭', '雲嘉南濱海區域內擁有臺灣獨特之鹽業歷史風光，以及廣大的沙洲、潟湖以及溼地景觀，而早期西南沿海地帶，共有七個袖珍島嶼（即當今的沙洲），形狀如同七隻浮身海面的鯨魚（鯤即鯨魚、大魚之意）故得名「鯤鯓」。因此將本地沙洲景觀、結合當地傳統「王爺信仰」，並以獨特的「鹽」文化作為活動主題，辦理「鯤鯓王平安鹽祭」，活動內容包含請鹽儀式、祈福法會、開幕儀式、平安鹽袋發放、博杯挑戰賽、伴手禮展售、中英文免費廟宇導覽解說、返本還鹽儀式等。藉由此活動讓國內外的遊客更了解臺灣當地民俗信仰、鹽業文化。', '雲嘉南濱海國家風景區管理處', '南鯤鯓代天府', '2023-11-11 00:00:00', '2023-11-12 00:00:00', '臺南市北門區', 23.286086, 120.143135, '無資料', 'https://www.swcoast-nsa.gov.tw/zh-tw/event-calendar/details/1871', '["https://www.taiwan.net.tw/att/event/f90d0919-6d48-4e2d-85e0-d791665ef36e.jpg", "https://www.taiwan.net.tw/att/event/221a9c31-81db-448a-9a77-ed04e9659592.jpg", "https://www.taiwan.net.tw/att/event/adeed9ba-9cde-4ded-84b8-4c0de0cd2cb9.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023鯤鯓王平安鹽祭', `description`='雲嘉南濱海區域內擁有臺灣獨特之鹽業歷史風光，以及廣大的沙洲、潟湖以及溼地景觀，而早期西南沿海地帶，共有七個袖珍島嶼（即當今的沙洲），形狀如同七隻浮身海面的鯨魚（鯤即鯨魚、大魚之意）故得名「鯤鯓」。因此將本地沙洲景觀、結合當地傳統「王爺信仰」，並以獨特的「鹽」文化作為活動主題，辦理「鯤鯓王平安鹽祭」，活動內容包含請鹽儀式、祈福法會、開幕儀式、平安鹽袋發放、博杯挑戰賽、伴手禮展售、中英文免費廟宇導覽解說、返本還鹽儀式等。藉由此活動讓國內外的遊客更了解臺灣當地民俗信仰、鹽業文化。', `organizer`='雲嘉南濱海國家風景區管理處', `address`='南鯤鯓代天府', `start_date`='2023-11-11 00:00:00', `end_date`='2023-11-12 00:00:00', `location`='臺南市北門區', `latitude`=23.286086, `longitude`=120.143135, `ticket_price`='無資料', `source_url`='https://www.swcoast-nsa.gov.tw/zh-tw/event-calendar/details/1871', `image_url`='["https://www.taiwan.net.tw/att/event/f90d0919-6d48-4e2d-85e0-d791665ef36e.jpg", "https://www.taiwan.net.tw/att/event/221a9c31-81db-448a-9a77-ed04e9659592.jpg", "https://www.taiwan.net.tw/att/event/adeed9ba-9cde-4ded-84b8-4c0de0cd2cb9.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081101', '2023大鵬灣帆船生活節', '系列活動規劃了多元水域活動體驗及賽事，包含風帆橫渡小琉球全國錦標賽暨繞灣賽、獨木舟趣味競賽、龍舟賽、立式划槳比賽、水上摩托車比賽、創意環保船比賽、遊艇活動推廣暨周邊產業商品展、美食特展；整合當地觀光產業推出小鎮漫遊行程、套裝商品等，提供遊客方便旅遊安排旅遊行程，深度體驗大鵬灣海洋風情、美食文化。「大鵬灣帆船生活節」規劃每年四月份在濱灣碼頭辦理，結合多元展演藝術，從日出到 日落後，皆精彩連連。白天活動有帆船賽，百帆啟航畫面震撼演出，及推出划獨木舟探訪紅樹林濕地、搭乘重 型帆船等，伴著徐徐微風，欣賞潟湖上悠遊的帆船、遊艇，是必玩體驗。夜晚黃昏的濱灣碼頭，帆船桅杆襯著夕陽，金黃湖面波光粼粼，是攝影愛好者追逐的畫 面，此刻也是旅人逛市集、賞夕陽的絕佳選擇。入夜後，特安排在地樂團、街頭藝人現 場開唱，搭配藝術裝置、璀璨燈飾，為即將到來的夏天揭開序幕；完美行程規劃相當適 合入住大鵬灣周邊民宿，加碼東港海鮮美食饗宴，好好犒賞自己。 -->', '交通部觀光署大鵬灣國家風景區管理處', '濱灣碼頭', '2023-04-01 00:00:00', '2023-04-30 00:00:00', '屏東縣東港鎮', 22.436622, 120.477386, '無資料', 'https://www.dbnsa.gov.tw/Festival-Content.aspx?Lang=1&SNo=03003752', '["https://www.taiwan.net.tw/att/event/ae1cb61d-431c-4944-a783-49d3fff53379.jpg", "https://www.taiwan.net.tw/att/event/05ae8941-20e9-4db9-88c8-1c39ca628bcf.jpg", "https://www.taiwan.net.tw/att/event/ef0bad75-a8cf-4bea-968a-7adcd2790bbe.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023大鵬灣帆船生活節', `description`='系列活動規劃了多元水域活動體驗及賽事，包含風帆橫渡小琉球全國錦標賽暨繞灣賽、獨木舟趣味競賽、龍舟賽、立式划槳比賽、水上摩托車比賽、創意環保船比賽、遊艇活動推廣暨周邊產業商品展、美食特展；整合當地觀光產業推出小鎮漫遊行程、套裝商品等，提供遊客方便旅遊安排旅遊行程，深度體驗大鵬灣海洋風情、美食文化。「大鵬灣帆船生活節」規劃每年四月份在濱灣碼頭辦理，結合多元展演藝術，從日出到 日落後，皆精彩連連。白天活動有帆船賽，百帆啟航畫面震撼演出，及推出划獨木舟探訪紅樹林濕地、搭乘重 型帆船等，伴著徐徐微風，欣賞潟湖上悠遊的帆船、遊艇，是必玩體驗。夜晚黃昏的濱灣碼頭，帆船桅杆襯著夕陽，金黃湖面波光粼粼，是攝影愛好者追逐的畫 面，此刻也是旅人逛市集、賞夕陽的絕佳選擇。入夜後，特安排在地樂團、街頭藝人現 場開唱，搭配藝術裝置、璀璨燈飾，為即將到來的夏天揭開序幕；完美行程規劃相當適 合入住大鵬灣周邊民宿，加碼東港海鮮美食饗宴，好好犒賞自己。 -->', `organizer`='交通部觀光署大鵬灣國家風景區管理處', `address`='濱灣碼頭', `start_date`='2023-04-01 00:00:00', `end_date`='2023-04-30 00:00:00', `location`='屏東縣東港鎮', `latitude`=22.436622, `longitude`=120.477386, `ticket_price`='無資料', `source_url`='https://www.dbnsa.gov.tw/Festival-Content.aspx?Lang=1&SNo=03003752', `image_url`='["https://www.taiwan.net.tw/att/event/ae1cb61d-431c-4944-a783-49d3fff53379.jpg", "https://www.taiwan.net.tw/att/event/05ae8941-20e9-4db9-88c8-1c39ca628bcf.jpg", "https://www.taiwan.net.tw/att/event/ef0bad75-a8cf-4bea-968a-7adcd2790bbe.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081102', '2023台灣美食展', '台灣美食展，從早期單純的食材與料理，擴展為食器、文化與飲食氛圍，食藝文化結合名廚料理、各地特產食材結合成在地美食，風格愈來愈多樣，更帶入臺灣美食國際化領域。除了色香味美的菜色，也有動態十足的廚藝競賽，遠從各國慕名參賽的名廚讓美食展更顯國際化。', '財團法人台灣觀光協會', '台北世界貿易中心展覽一館', '2023-08-04 00:00:00', '2023-08-07 00:00:00', '臺北市信義區', 25.033155, 121.562347, '無資料', 'https://www.tcetva.tw/', '["https://www.taiwan.net.tw/att/event/80b394ca-32f9-4e29-bbe4-6ea84fcd7f68.jpg", "https://www.taiwan.net.tw/att/event/7d88d544-bb2f-40b0-ba5b-ef43888e56ae.jpg", "https://www.taiwan.net.tw/att/event/631c16d8-efc8-4816-a370-d0bab8a6158d.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023台灣美食展', `description`='台灣美食展，從早期單純的食材與料理，擴展為食器、文化與飲食氛圍，食藝文化結合名廚料理、各地特產食材結合成在地美食，風格愈來愈多樣，更帶入臺灣美食國際化領域。除了色香味美的菜色，也有動態十足的廚藝競賽，遠從各國慕名參賽的名廚讓美食展更顯國際化。', `organizer`='財團法人台灣觀光協會', `address`='台北世界貿易中心展覽一館', `start_date`='2023-08-04 00:00:00', `end_date`='2023-08-07 00:00:00', `location`='臺北市信義區', `latitude`=25.033155, `longitude`=121.562347, `ticket_price`='無資料', `source_url`='https://www.tcetva.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/80b394ca-32f9-4e29-bbe4-6ea84fcd7f68.jpg", "https://www.taiwan.net.tw/att/event/7d88d544-bb2f-40b0-ba5b-ef43888e56ae.jpg", "https://www.taiwan.net.tw/att/event/631c16d8-efc8-4816-a370-d0bab8a6158d.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081103', '2023台灣仲夏旅遊節', '仲夏節是夏至來臨時的慶祝活動，在北歐是一個重要的節日。台灣自2014年開始推廣夏季旅遊活動，從2014年起的「台灣夏至235」，延續到2019年「寶島仲夏節」，台灣夏季旅遊特色已經逐漸受到重視。為了因應疫後民眾旅遊觀念與消費習慣的改變，交通部觀光署延續推廣仲夏旅遊的宗旨，重新盤整全台夏季旅遊資源，重塑活動品牌為【台灣仲夏旅遊節】，今年活動以「清涼」、「消暑」、「涼品」為活動主軸，串聯整合台灣13個國家風景區與14個縣市共27項夏日特色旅遊活動，並與產業跨界結盟合作，以更全面和多元的主題，讓民眾感受台灣夏季的旅遊魅力，期許能捲動台灣夏季觀光熱潮，帶動周邊產業發展，型塑台灣夏日節慶活動新品牌。', '交通部觀光署', '馬沙溝濱海遊憩區', '2023-06-21 00:00:00', '2023-09-30 00:00:00', '臺南市將軍區', 23.216601, 120.083712, '無資料', 'https://summerfestival.taiwan.net.tw/', '["https://www.taiwan.net.tw/att/event/0ab60674-d293-4334-a8fd-c99314ddd394.jpg", "https://www.taiwan.net.tw/att/event/6e0bd531-bb48-41b4-b6c7-3b2ae2ac43e2.jpg", "https://www.taiwan.net.tw/att/event/e2203fca-466f-48ff-b735-e9eed3004eee.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023台灣仲夏旅遊節', `description`='仲夏節是夏至來臨時的慶祝活動，在北歐是一個重要的節日。台灣自2014年開始推廣夏季旅遊活動，從2014年起的「台灣夏至235」，延續到2019年「寶島仲夏節」，台灣夏季旅遊特色已經逐漸受到重視。為了因應疫後民眾旅遊觀念與消費習慣的改變，交通部觀光署延續推廣仲夏旅遊的宗旨，重新盤整全台夏季旅遊資源，重塑活動品牌為【台灣仲夏旅遊節】，今年活動以「清涼」、「消暑」、「涼品」為活動主軸，串聯整合台灣13個國家風景區與14個縣市共27項夏日特色旅遊活動，並與產業跨界結盟合作，以更全面和多元的主題，讓民眾感受台灣夏季的旅遊魅力，期許能捲動台灣夏季觀光熱潮，帶動周邊產業發展，型塑台灣夏日節慶活動新品牌。', `organizer`='交通部觀光署', `address`='馬沙溝濱海遊憩區', `start_date`='2023-06-21 00:00:00', `end_date`='2023-09-30 00:00:00', `location`='臺南市將軍區', `latitude`=23.216601, `longitude`=120.083712, `ticket_price`='無資料', `source_url`='https://summerfestival.taiwan.net.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/0ab60674-d293-4334-a8fd-c99314ddd394.jpg", "https://www.taiwan.net.tw/att/event/6e0bd531-bb48-41b4-b6c7-3b2ae2ac43e2.jpg", "https://www.taiwan.net.tw/att/event/e2203fca-466f-48ff-b735-e9eed3004eee.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081104', '2023-2024台灣好湯-溫泉美食嘉年華', '時序逐漸進入冬天，也正式宣告臺灣已進入溫泉泡湯旺季！臺灣得天獨厚，擁有冷泉、熱泉、濁泉、海底泉等多樣性泉質，是世界知名的溫泉勝地。交通部觀光署自民國96年（西元2007年）開始每年結合溫泉保健養生特色及現代人健康飲食需求，將臺灣「溫泉」及「美食」兩大觀光資源整合規劃推出「溫泉美食嘉年華」活動。該活動每年在全臺各地同時登場，並從全臺19個溫泉區選出啟動地點。「溫泉美食嘉年華」不但讓國內遊客全臺溫泉區泡透透，處處都享優惠，對國際觀光客也是深具魅力，更是帶動秋冬臺灣溫泉旅遊熱潮的年度盛事。活動期間，全臺溫泉區都將陸續辦理溫泉美食系列活動，並整合全臺各縣市溫泉區上百家業者，集合各溫泉區景點、人文風情與特產介紹，推薦優質店家，同時更提供好康優惠陸續引爆泡湯話題。', '交通部觀光署', '新北投溫泉區', '2023-09-18 00:00:00', '2024-06-30 00:00:00', '臺北市北投區', 25.136942, 121.502649, '無資料', '無資料', '["https://www.taiwan.net.tw/att/event/388b0f82-b621-4be2-8c5f-4dac47482d01.jpg", "https://www.taiwan.net.tw/att/event/f4adba8f-082f-45e6-9c33-36bbbab062d3.jpg", "https://www.taiwan.net.tw/att/event/636fe103-06a9-4ab8-902f-8ed983291c9e.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023-2024台灣好湯-溫泉美食嘉年華', `description`='時序逐漸進入冬天，也正式宣告臺灣已進入溫泉泡湯旺季！臺灣得天獨厚，擁有冷泉、熱泉、濁泉、海底泉等多樣性泉質，是世界知名的溫泉勝地。交通部觀光署自民國96年（西元2007年）開始每年結合溫泉保健養生特色及現代人健康飲食需求，將臺灣「溫泉」及「美食」兩大觀光資源整合規劃推出「溫泉美食嘉年華」活動。該活動每年在全臺各地同時登場，並從全臺19個溫泉區選出啟動地點。「溫泉美食嘉年華」不但讓國內遊客全臺溫泉區泡透透，處處都享優惠，對國際觀光客也是深具魅力，更是帶動秋冬臺灣溫泉旅遊熱潮的年度盛事。活動期間，全臺溫泉區都將陸續辦理溫泉美食系列活動，並整合全臺各縣市溫泉區上百家業者，集合各溫泉區景點、人文風情與特產介紹，推薦優質店家，同時更提供好康優惠陸續引爆泡湯話題。', `organizer`='交通部觀光署', `address`='新北投溫泉區', `start_date`='2023-09-18 00:00:00', `end_date`='2024-06-30 00:00:00', `location`='臺北市北投區', `latitude`=25.136942, `longitude`=121.502649, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.taiwan.net.tw/att/event/388b0f82-b621-4be2-8c5f-4dac47482d01.jpg", "https://www.taiwan.net.tw/att/event/f4adba8f-082f-45e6-9c33-36bbbab062d3.jpg", "https://www.taiwan.net.tw/att/event/636fe103-06a9-4ab8-902f-8ed983291c9e.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081105', '2023臺灣自行車旅遊節', '國片「練習曲」中一句經典對白：「有些事現在不做，一輩子都不會做了。」這句話帶動了全臺單車環島風潮，騎著自行車環繞臺灣本島之旅，也被許多人列為此生必做的事之一！自2010年以來，交通部觀光署積極舉辦「臺灣自行車節」系列活動，熱情邀請臺灣全民一同創造「騎」跡，將交通建設的創新成果，轉換成觀光旅遊的新資源，企圖把臺灣打造為國際級自行車休閒旅遊天堂。臺灣的公路系統完善，再加上地形優勢，騎著自行車時還可邊欣賞沿路壯闊美景，在臺灣單車環島是最方便又享受的旅遊行程！「臺灣自行車節」系列活動就是以自行車旅遊活動，結合了各縣市的觀光與交通資源力量，呈現出多元與在地的文化旅遊特色。在好山好水的陪伴下，吸引全世界自行車愛好者都能來朝聖，提供國內外遊客們多樣豐富休憩旅遊體驗，讓騎鐵馬不再是單純的運動，而是更豐富的身心靈上完美體驗。    台北國際自行車展：2023年3月22-25日    騎遇福爾摩沙900：2023年11月11-19日    日月潭Come!Bikeday自行車嘉年華主題日活動：2023年10月14日    臺灣登山王挑戰 KOM：2023年10月27日', '交通部觀光署', '福隆海水浴場', '2023-03-01 00:00:00', '2023-11-30 00:00:00', '新北市貢寮區', 25.021998, 121.943158, '無資料', 'https://taiwanbike.tw/', '["https://www.taiwan.net.tw/att/event/6fe79462-ec06-41fc-8f6e-291250981bbb.jpg", "https://www.taiwan.net.tw/att/event/88b7c97c-48eb-4ca2-883a-79079912c748.jpg", "https://www.taiwan.net.tw/att/event/acce6bcf-6795-47e3-8a21-7c8b2b10cccd.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023臺灣自行車旅遊節', `description`='國片「練習曲」中一句經典對白：「有些事現在不做，一輩子都不會做了。」這句話帶動了全臺單車環島風潮，騎著自行車環繞臺灣本島之旅，也被許多人列為此生必做的事之一！自2010年以來，交通部觀光署積極舉辦「臺灣自行車節」系列活動，熱情邀請臺灣全民一同創造「騎」跡，將交通建設的創新成果，轉換成觀光旅遊的新資源，企圖把臺灣打造為國際級自行車休閒旅遊天堂。臺灣的公路系統完善，再加上地形優勢，騎著自行車時還可邊欣賞沿路壯闊美景，在臺灣單車環島是最方便又享受的旅遊行程！「臺灣自行車節」系列活動就是以自行車旅遊活動，結合了各縣市的觀光與交通資源力量，呈現出多元與在地的文化旅遊特色。在好山好水的陪伴下，吸引全世界自行車愛好者都能來朝聖，提供國內外遊客們多樣豐富休憩旅遊體驗，讓騎鐵馬不再是單純的運動，而是更豐富的身心靈上完美體驗。    台北國際自行車展：2023年3月22-25日    騎遇福爾摩沙900：2023年11月11-19日    日月潭Come!Bikeday自行車嘉年華主題日活動：2023年10月14日    臺灣登山王挑戰 KOM：2023年10月27日', `organizer`='交通部觀光署', `address`='福隆海水浴場', `start_date`='2023-03-01 00:00:00', `end_date`='2023-11-30 00:00:00', `location`='新北市貢寮區', `latitude`=25.021998, `longitude`=121.943158, `ticket_price`='無資料', `source_url`='https://taiwanbike.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/6fe79462-ec06-41fc-8f6e-291250981bbb.jpg", "https://www.taiwan.net.tw/att/event/88b7c97c-48eb-4ca2-883a-79079912c748.jpg", "https://www.taiwan.net.tw/att/event/acce6bcf-6795-47e3-8a21-7c8b2b10cccd.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010000H_081149', '2023花蓮紅面鴨FUN暑假', '運用鯉魚潭特有的自然景觀，以花蓮觀光吉祥物紅面鴨於鯉魚潭展出，白天遊客可以在鯉魚潭悠遊的享受湖光山色、與紅面鴨裝置藝術合照，晚上遊客可欣賞結合現代科技與花蓮原住民的人文色彩，在鯉魚潭上的水上舞台，以舞蹈激盪出人與水共舞的劇場畫面，以及欣賞結合傳統各式水舞造型，搭配炫麗、七彩的高亮度LED燈與雷射動畫整合展演及量身打造3D投影影像、融合花蓮百景文化意象，令人驚豔的水舞秀。活動培育在地人才與觀光資源，提升觀光產值與經濟效益。', '花蓮縣政府觀光處', '鯉魚潭', '2023-07-31 00:00:00', '2023-08-13 00:00:00', '花蓮縣壽豐鄉', 23.927826, 121.509878, '無資料', 'https://happy-duck.hl.gov.tw/', '["https://www.taiwan.net.tw/att/event/4cd683ec-5938-4ff2-80df-a024b5b0754a.jpg", "https://www.taiwan.net.tw/att/event/61c8ecaa-b639-48d8-a90a-6a37de171f57.jpg", "https://www.taiwan.net.tw/att/event/88b1f12e-41af-4dee-afcd-ba34ce8310c8.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2023花蓮紅面鴨FUN暑假', `description`='運用鯉魚潭特有的自然景觀，以花蓮觀光吉祥物紅面鴨於鯉魚潭展出，白天遊客可以在鯉魚潭悠遊的享受湖光山色、與紅面鴨裝置藝術合照，晚上遊客可欣賞結合現代科技與花蓮原住民的人文色彩，在鯉魚潭上的水上舞台，以舞蹈激盪出人與水共舞的劇場畫面，以及欣賞結合傳統各式水舞造型，搭配炫麗、七彩的高亮度LED燈與雷射動畫整合展演及量身打造3D投影影像、融合花蓮百景文化意象，令人驚豔的水舞秀。活動培育在地人才與觀光資源，提升觀光產值與經濟效益。', `organizer`='花蓮縣政府觀光處', `address`='鯉魚潭', `start_date`='2023-07-31 00:00:00', `end_date`='2023-08-13 00:00:00', `location`='花蓮縣壽豐鄉', `latitude`=23.927826, `longitude`=121.509878, `ticket_price`='無資料', `source_url`='https://happy-duck.hl.gov.tw/', `image_url`='["https://www.taiwan.net.tw/att/event/4cd683ec-5938-4ff2-80df-a024b5b0754a.jpg", "https://www.taiwan.net.tw/att/event/61c8ecaa-b639-48d8-a90a-6a37de171f57.jpg", "https://www.taiwan.net.tw/att/event/88b1f12e-41af-4dee-afcd-ba34ce8310c8.jpg"]';
