INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010700H_002604', '雲端上的婚禮', '梨山耶穌堂甫於111年經本處重新整修完成並開放使用，此建築也被列為台中市重要文化資產。本處訂於今年2月續辦理雲端上的婚禮，規劃於2月份邀請新人們於梨山耶穌堂舉行浪漫婚禮，在全台最高海拔的耶穌堂讓上帝見證新人們的愛情，新人們並可於梨山拍攝婚紗照，藉由梨山山岳之壯麗襯托新人婚紗照之唯美感，也增添梨山及梨山耶穌堂浪漫氛圍。歡迎國內外遊客於2月來到梨山一同參與原民音樂會暨派對市集，也可於2月來耶穌堂觀禮一同獻上對新人們的祝福。', '參山國家風景區管理處', '臺中市424和平區', '2025-02-18 00:00:00', '2025-02-19 23:59:59', '花蓮縣花蓮市', 23.98969, 121.59407, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='雲端上的婚禮', `description`='梨山耶穌堂甫於111年經本處重新整修完成並開放使用，此建築也被列為台中市重要文化資產。本處訂於今年2月續辦理雲端上的婚禮，規劃於2月份邀請新人們於梨山耶穌堂舉行浪漫婚禮，在全台最高海拔的耶穌堂讓上帝見證新人們的愛情，新人們並可於梨山拍攝婚紗照，藉由梨山山岳之壯麗襯托新人婚紗照之唯美感，也增添梨山及梨山耶穌堂浪漫氛圍。歡迎國內外遊客於2月來到梨山一同參與原民音樂會暨派對市集，也可於2月來耶穌堂觀禮一同獻上對新人們的祝福。', `organizer`='參山國家風景區管理處', `address`='臺中市424和平區', `start_date`='2025-02-18 00:00:00', `end_date`='2025-02-19 23:59:59', `location`='花蓮縣花蓮市', `latitude`=23.98969, `longitude`=121.59407, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010700H_002607', '山谷燈光節', '山谷燈光節為參山處重點活動之一，每年12月至隔年1月於聖誕節及新年之際，藉由在梨山谷關兩處光環境布置配合聖誕佳節及跨年過節氣氛，吸引遊客來和平區賞燈、欣賞表演、與旅遊，並體驗本轄區內溫泉資源、享用當季農特產品、山岳健行、及部落觀光。本活動之亮點之一為梨山賓館前兩棵雪松，藉由各式燈具將兩顆雪松佈置成聖誕樹並結合音樂光線變化展現聲光效果，每年也會於活動辦理期間有不同主題之光環境展現，歡迎國內外遊客一起於年底之時一同來梨山谷關來體驗參與。', '參山國家風景區管理處', '臺中市424和平區', '2024-11-28 00:00:00', '2025-01-12 23:59:59', '花蓮縣花蓮市', 23.98969, 121.59407, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='山谷燈光節', `description`='山谷燈光節為參山處重點活動之一，每年12月至隔年1月於聖誕節及新年之際，藉由在梨山谷關兩處光環境布置配合聖誕佳節及跨年過節氣氛，吸引遊客來和平區賞燈、欣賞表演、與旅遊，並體驗本轄區內溫泉資源、享用當季農特產品、山岳健行、及部落觀光。本活動之亮點之一為梨山賓館前兩棵雪松，藉由各式燈具將兩顆雪松佈置成聖誕樹並結合音樂光線變化展現聲光效果，每年也會於活動辦理期間有不同主題之光環境展現，歡迎國內外遊客一起於年底之時一同來梨山谷關來體驗參與。', `organizer`='參山國家風景區管理處', `address`='臺中市424和平區', `start_date`='2024-11-28 00:00:00', `end_date`='2025-01-12 23:59:59', `location`='花蓮縣花蓮市', `latitude`=23.98969, `longitude`=121.59407, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
