INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010700H_007965', '八卦山賞鷹季系列活動', '主辦單位：交通部觀光署參山國家風景區管理處、彰化縣政府、農業部林業及自然保育署南投分署、南投市公所地點：八卦山脈生態遊客中心(500彰化縣彰化市卦山路13之7號)赤腳精靈(540南投縣南投市八卦路1-1號)、橫山賞鷹平臺彰化縣芬園鄉文德國小(502彰化縣芬園鄉大彰路一段617號)灰面鵟鷹又稱為灰面鷲，主要是因為牠的雄鳥臉部為灰色而得名，因為其在清明前後抵達八卦山及大肚山區，中部地區民眾稱其為「清明鳥」或「掃墓鳥」，又因其由南邊而來，也被稱為「南路鷹」。灰面鵟鷹也是彰化縣縣鳥，象徵彰化人重承諾、守信用及慎終追遠的意義，牠為珍貴稀有保育類動物。每年三月到四月春天期間，灰面鵟鷹由渡冬地北返過境八卦山，地區賞鷹活動至今已舉辦長達30年，活動辦理是為了長期守護灰面鵟鷹，提倡宣導生態保育觀念。', '參山國家風景區管理處', '彰化縣500彰化市永興里(橫山賞鷹平臺)', '2025-03-12 00:00:00', '2025-03-30 23:59:59', '南投縣南投市', 23.89611, 120.63314, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='八卦山賞鷹季系列活動', `description`='主辦單位：交通部觀光署參山國家風景區管理處、彰化縣政府、農業部林業及自然保育署南投分署、南投市公所地點：八卦山脈生態遊客中心(500彰化縣彰化市卦山路13之7號)赤腳精靈(540南投縣南投市八卦路1-1號)、橫山賞鷹平臺彰化縣芬園鄉文德國小(502彰化縣芬園鄉大彰路一段617號)灰面鵟鷹又稱為灰面鷲，主要是因為牠的雄鳥臉部為灰色而得名，因為其在清明前後抵達八卦山及大肚山區，中部地區民眾稱其為「清明鳥」或「掃墓鳥」，又因其由南邊而來，也被稱為「南路鷹」。灰面鵟鷹也是彰化縣縣鳥，象徵彰化人重承諾、守信用及慎終追遠的意義，牠為珍貴稀有保育類動物。每年三月到四月春天期間，灰面鵟鷹由渡冬地北返過境八卦山，地區賞鷹活動至今已舉辦長達30年，活動辦理是為了長期守護灰面鵟鷹，提倡宣導生態保育觀念。', `organizer`='參山國家風景區管理處', `address`='彰化縣500彰化市永興里(橫山賞鷹平臺)', `start_date`='2025-03-12 00:00:00', `end_date`='2025-03-30 23:59:59', `location`='南投縣南投市', `latitude`=23.89611, `longitude`=120.63314, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010700H_007966', '南庄花卉節', '南庄鄉為國家級觀光旅遊休閒勝地，有「花園山城」美稱，民國105年（西元2016年）獲選為國際慢城，現為國內5座國際慢城之一，人稱「好山好水在南庄」。南庄因環境氣候自然天成，適合花卉等農作物生長，近年來則逐漸興起休閒農業，設立許多特色民宿，極適合發展觀光休閒產業。本處於民國108年（西元2019年）初次舉辦「南庄恆浪漫繡球花節」，打響南庄花卉節的品牌知名度，以代表希望、忠貞、圓滿的繡球花為主軸，打造村村有花卉之意象；歷屆皆融入各式花卉為輔，擴大舉辦，營造南庄百花巷弄，建立「南庄花卉節」的品牌意涵，讓旅遊與在地資源深度連結，營造「最美的南庄」，奠定活動品牌價值。主要結合地景打造多座花卉主題裝置藝術，透過多元觀點與特色媒材，挖掘與展現花卉藝術的可能性，吸引外地人潮至的南庄與獅頭山地區時，也提升鄉鎮城市的品牌包裝形象。經過歷年舉辦，南庄鄉民紛以南庄花卉節為榮，商家結合活動自發性行銷並主動維護巷道上花卉環境。活動結束後，也持續由協會、業者、居民現地認養花卉植栽或裝置藝術，讓花卉節不只在每年春季綻放，而是由地方接力繼續呵護，南庄村民用愛讓花卉得以運用另一種方式延續生命力，達到永續綠美化的環境循環價值，形成強大鏈結。', '參山國家風景區管理處', '苗栗縣353南庄鄉', '2025-03-01 00:00:00', '2025-04-30 23:59:59', '花蓮縣花蓮市', 23.98969, 121.59407, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南庄花卉節', `description`='南庄鄉為國家級觀光旅遊休閒勝地，有「花園山城」美稱，民國105年（西元2016年）獲選為國際慢城，現為國內5座國際慢城之一，人稱「好山好水在南庄」。南庄因環境氣候自然天成，適合花卉等農作物生長，近年來則逐漸興起休閒農業，設立許多特色民宿，極適合發展觀光休閒產業。本處於民國108年（西元2019年）初次舉辦「南庄恆浪漫繡球花節」，打響南庄花卉節的品牌知名度，以代表希望、忠貞、圓滿的繡球花為主軸，打造村村有花卉之意象；歷屆皆融入各式花卉為輔，擴大舉辦，營造南庄百花巷弄，建立「南庄花卉節」的品牌意涵，讓旅遊與在地資源深度連結，營造「最美的南庄」，奠定活動品牌價值。主要結合地景打造多座花卉主題裝置藝術，透過多元觀點與特色媒材，挖掘與展現花卉藝術的可能性，吸引外地人潮至的南庄與獅頭山地區時，也提升鄉鎮城市的品牌包裝形象。經過歷年舉辦，南庄鄉民紛以南庄花卉節為榮，商家結合活動自發性行銷並主動維護巷道上花卉環境。活動結束後，也持續由協會、業者、居民現地認養花卉植栽或裝置藝術，讓花卉節不只在每年春季綻放，而是由地方接力繼續呵護，南庄村民用愛讓花卉得以運用另一種方式延續生命力，達到永續綠美化的環境循環價值，形成強大鏈結。', `organizer`='參山國家風景區管理處', `address`='苗栗縣353南庄鄉', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 23:59:59', `location`='花蓮縣花蓮市', `latitude`=23.98969, `longitude`=121.59407, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15010700H_007967', '石壁部落健行', '在苗栗南庄石壁部落舉辦登山健行活動，在鳴炮、撒花中，歡樂啟程，欣賞山巒、雲霧之美。南庄原住民族部落觀光資源豐富，值得遊客上山探尋石壁風情和文化。歡迎到南庄石壁部落登山健行、參加部落小旅行、原味部落市集找原風。', '參山國家風景區管理處', '苗栗縣353南庄鄉', '2025-10-01 23:59:59', '2025-10-31 00:00:00', '花蓮縣花蓮市', 23.98969, 121.59407, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='石壁部落健行', `description`='在苗栗南庄石壁部落舉辦登山健行活動，在鳴炮、撒花中，歡樂啟程，欣賞山巒、雲霧之美。南庄原住民族部落觀光資源豐富，值得遊客上山探尋石壁風情和文化。歡迎到南庄石壁部落登山健行、參加部落小旅行、原味部落市集找原風。', `organizer`='參山國家風景區管理處', `address`='苗栗縣353南庄鄉', `start_date`='2025-10-01 23:59:59', `end_date`='2025-10-31 00:00:00', `location`='花蓮縣花蓮市', `latitude`=23.98969, `longitude`=121.59407, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15011000H_000264', '野柳神明淨港文化季', '每逢元宵佳節，野柳獨特的神明淨港儀式總是吸引眾多遊客到訪參觀，相傳清嘉慶25年（西元1820年），有一艘無人駕駛的船，載著開漳聖王神像和建材，在野柳港外載浮載沉，當地里民迎此神像，建為保安宮。', '新北市萬里區公所', '新北市萬里區港東路69號', '2023-10-31 00:00:00', '2123-10-31 00:00:00', '新北市萬里區', 25.2052, 121.6878, '無資料', 'https://www.northguan-nsa.gov.tw//user/Article.aspx?Lang=1&SNo=04007990', '[]') ON DUPLICATE KEY UPDATE `activity_name`='野柳神明淨港文化季', `description`='每逢元宵佳節，野柳獨特的神明淨港儀式總是吸引眾多遊客到訪參觀，相傳清嘉慶25年（西元1820年），有一艘無人駕駛的船，載著開漳聖王神像和建材，在野柳港外載浮載沉，當地里民迎此神像，建為保安宮。', `organizer`='新北市萬里區公所', `address`='新北市萬里區港東路69號', `start_date`='2023-10-31 00:00:00', `end_date`='2123-10-31 00:00:00', `location`='新北市萬里區', `latitude`=25.2052, `longitude`=121.6878, `ticket_price`='無資料', `source_url`='https://www.northguan-nsa.gov.tw//user/Article.aspx?Lang=1&SNo=04007990', `image_url`='[]';
