INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15011300H_020381', '2022多元自行車路線 GoBikeTAIWAN玩騎認證', '2022多元自行車路線 GoBikeTAIWAN玩騎認證 為鼓勵民眾玩騎16條多元路線，觀光局於111年1月3日至4月30日期間舉辦「2022多元自行車路線GoBikeTAIWAN玩騎認證」活動，只要騎乘任一條自行車多元路線+完成指定任務，經服務人員確認後，即可獲得該路線的專屬紀念認證勳章，還有機會抽大獎：現金獎、高級自行車、知名運動用品店禮物卡等。 參加資格： 不限，參加者需使用智慧型手機之可紀錄移動路徑APP者，或透過智慧穿戴裝置將移動路徑紀錄上傳至智慧型手機者。 玩騎方式： 無需報名，自主完成觀光局公布之六大型態16條多元自行車路線。透過智慧型手機使用環騎圓夢APP或其他可記錄騎乘路徑的APP軟體（如：Relive），記錄自行車騎乘軌跡。將騎乘軌跡上傳至個人臉書或Instragram，標記「交通部觀光局玩騎認證」、「一騎踏出去」並設定公開分享至該路線指定的國家風景區旅遊服務中心，經由', '交通部觀光局', '宜蘭縣壯圍鄉壯濱路二段196巷18號', '2022-01-03 00:00:00', '2022-04-30 00:00:00', '宜蘭縣壯圍鄉', 24.74386, 121.81646, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2022多元自行車路線 GoBikeTAIWAN玩騎認證', `description`='2022多元自行車路線 GoBikeTAIWAN玩騎認證 為鼓勵民眾玩騎16條多元路線，觀光局於111年1月3日至4月30日期間舉辦「2022多元自行車路線GoBikeTAIWAN玩騎認證」活動，只要騎乘任一條自行車多元路線+完成指定任務，經服務人員確認後，即可獲得該路線的專屬紀念認證勳章，還有機會抽大獎：現金獎、高級自行車、知名運動用品店禮物卡等。 參加資格： 不限，參加者需使用智慧型手機之可紀錄移動路徑APP者，或透過智慧穿戴裝置將移動路徑紀錄上傳至智慧型手機者。 玩騎方式： 無需報名，自主完成觀光局公布之六大型態16條多元自行車路線。透過智慧型手機使用環騎圓夢APP或其他可記錄騎乘路徑的APP軟體（如：Relive），記錄自行車騎乘軌跡。將騎乘軌跡上傳至個人臉書或Instragram，標記「交通部觀光局玩騎認證」、「一騎踏出去」並設定公開分享至該路線指定的國家風景區旅遊服務中心，經由', `organizer`='交通部觀光局', `address`='宜蘭縣壯圍鄉壯濱路二段196巷18號', `start_date`='2022-01-03 00:00:00', `end_date`='2022-04-30 00:00:00', `location`='宜蘭縣壯圍鄉', `latitude`=24.74386, `longitude`=121.81646, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15011300H_020391', '2022福隆國際沙雕藝術季', '東北角鹽寮至福隆一帶，綿延三公里長的黃金沙灘，砂質屬石英沙、柔軟白細、觸感甚佳，和水後可塑性佳、易膠著，被世界沙雕協會鑑定為台灣最適合沙雕的場所，是台灣大型戶外沙雕季的創始地點。而沙雕季舉辦的地點──福隆海水浴場也可從事戲水、帆船、獨木舟等水上運動，讓參觀者不僅能欣賞令人驚嘆的沙雕創作藝術，同時能體驗多項水上遊憩活動。 沙雕，是一項結合雕塑、文化、繪畫、建築、體能與娛樂的藝術創作，適合各年齡層參與，符合綠色環保、永續使用的概念，本處自2008年起舉辦第一屆「福隆沙雕藝術季」，迄今2022年邁入第15屆，逐年創造人潮佳績。本年度(111)持續與麗寶建設福容飯店連鎖集團共同主辦，藉由投入民間多元能量，讓「2022福隆國際沙雕藝術季」能夠再創活動高潮盛況。 今年福隆沙雕展聯名經典IP「霹靂」，打造「霹靂傳奇‧掌中天下」活動主題，將台灣布袋戲文化融入沙雕藝術之中。本屆作品共計36座，其中包含了經典', '東北角暨宜蘭海岸國家風景區管理處', '新北市貢寮區福隆街41號', '2022-05-26 00:00:00', '2022-10-10 00:00:00', '新北市貢寮區', 25.01839, 121.94395, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2022福隆國際沙雕藝術季', `description`='東北角鹽寮至福隆一帶，綿延三公里長的黃金沙灘，砂質屬石英沙、柔軟白細、觸感甚佳，和水後可塑性佳、易膠著，被世界沙雕協會鑑定為台灣最適合沙雕的場所，是台灣大型戶外沙雕季的創始地點。而沙雕季舉辦的地點──福隆海水浴場也可從事戲水、帆船、獨木舟等水上運動，讓參觀者不僅能欣賞令人驚嘆的沙雕創作藝術，同時能體驗多項水上遊憩活動。 沙雕，是一項結合雕塑、文化、繪畫、建築、體能與娛樂的藝術創作，適合各年齡層參與，符合綠色環保、永續使用的概念，本處自2008年起舉辦第一屆「福隆沙雕藝術季」，迄今2022年邁入第15屆，逐年創造人潮佳績。本年度(111)持續與麗寶建設福容飯店連鎖集團共同主辦，藉由投入民間多元能量，讓「2022福隆國際沙雕藝術季」能夠再創活動高潮盛況。 今年福隆沙雕展聯名經典IP「霹靂」，打造「霹靂傳奇‧掌中天下」活動主題，將台灣布袋戲文化融入沙雕藝術之中。本屆作品共計36座，其中包含了經典', `organizer`='東北角暨宜蘭海岸國家風景區管理處', `address`='新北市貢寮區福隆街41號', `start_date`='2022-05-26 00:00:00', `end_date`='2022-10-10 00:00:00', `location`='新北市貢寮區', `latitude`=25.01839, `longitude`=121.94395, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15011300H_020392', '2022東北角福隆生活節 霹靂沙雕、在地市集 精彩一夏 等著您', '近年來自行車休閒活動的人口逐漸攀升，透過自行車騎乘旅行的方式進行深度慢旅已成為一種趨勢，更能實際深入體驗當地人文特色、自然景觀。東北角管理處馬惠達處長表示：東北角暨宜蘭海岸國家風景區擁有山海相伴的好風光，有許多值得走訪的景點：包括舊草嶺隧道、福隆海水浴場、萊萊海蝕平台、卯澳漁村、三貂角燈塔等。騎著自行車，沿著海岸線，來一趟海岸風光與懷舊小鎮的深度慢旅，是初夏時間出遊的最佳選擇！ 2022東北角福隆生活節將在6/18(六)~10/29(六)期間的每個週六舉辦，打造沙灘音樂會、福隆沙雕、市集、單車行的體驗行程等等，讓來到東北角的旅客能夠從早玩到晚。今年續推自行車一日騎乘活動，並增加新的主題路線選擇，不僅可騎訪北臺灣最經典自行車路線之一「舊草嶺環狀線自行車道」，前往卯澳漁村進行特色DIY和美食品嚐；還可探訪雙溪與貢寮地區，感受昔日淡蘭古道榮景遺跡與雙溪老街風華，結合自行車休閒活動與地方深度體驗', '東北角暨宜蘭海岸國家風景區管理處', '新北市貢寮區興隆街36號', '2022-05-31 00:00:00', '2022-05-31 00:00:00', '新北市貢寮區', 25.01692, 121.94251, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2022東北角福隆生活節 霹靂沙雕、在地市集 精彩一夏 等著您', `description`='近年來自行車休閒活動的人口逐漸攀升，透過自行車騎乘旅行的方式進行深度慢旅已成為一種趨勢，更能實際深入體驗當地人文特色、自然景觀。東北角管理處馬惠達處長表示：東北角暨宜蘭海岸國家風景區擁有山海相伴的好風光，有許多值得走訪的景點：包括舊草嶺隧道、福隆海水浴場、萊萊海蝕平台、卯澳漁村、三貂角燈塔等。騎著自行車，沿著海岸線，來一趟海岸風光與懷舊小鎮的深度慢旅，是初夏時間出遊的最佳選擇！ 2022東北角福隆生活節將在6/18(六)~10/29(六)期間的每個週六舉辦，打造沙灘音樂會、福隆沙雕、市集、單車行的體驗行程等等，讓來到東北角的旅客能夠從早玩到晚。今年續推自行車一日騎乘活動，並增加新的主題路線選擇，不僅可騎訪北臺灣最經典自行車路線之一「舊草嶺環狀線自行車道」，前往卯澳漁村進行特色DIY和美食品嚐；還可探訪雙溪與貢寮地區，感受昔日淡蘭古道榮景遺跡與雙溪老街風華，結合自行車休閒活動與地方深度體驗', `organizer`='東北角暨宜蘭海岸國家風景區管理處', `address`='新北市貢寮區興隆街36號', `start_date`='2022-05-31 00:00:00', `end_date`='2022-05-31 00:00:00', `location`='新北市貢寮區', `latitude`=25.01692, `longitude`=121.94251, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_A15011300H_020407', 'WAIAO搖滾月夜、星空浪花市集 8/28 相揪 chill 一夏', '東北角最潮打卡點在外澳！ 搖滾月夜、星空浪花市集 8/28 相揪 chill 一夏 沿岸變化多端的地景、一望無際的湛藍大海，與格外自由奔放的空氣，是吸引旅人不斷再訪的東北角式魅力，而夏天正是最能深刻感受在地獨有氛圍的季節！交通部觀光局東北角暨宜蘭海岸國家風景管理處（以下簡稱東北角管理處），今年夏季尾聲延續「悸動東北角」精神，邀請歌手高蕾雅、戰嬿舞團、即將成真火舞團、夏那樂團帶來獨具風格的搖滾月夜，串連東北角在地品牌打造星空浪花市集，廣邀民眾在8月28日來到大海邊打卡外澳最新拍照基地，享受屬於東北角的微醺浪漫，讓心情隨著起伏浪花 chill 一夏！ 東北角管理處馬惠達處長表示，隨著新型冠狀病毒肺炎（COVID-19）起伏，各地觀光產業難免遭受衝擊與影響，然而管理處長期關注轄區內休閒產業發展，這段時期正是協助業者沉寂再出發的好時機；進入相對穩定的後疫情時代，島內旅遊的興盛反映出國人出走旅遊的渴', '東北角暨宜蘭海岸國家風景區管理處', '宜蘭縣頭城鎮濱海路二段6號', '2022-08-28 00:00:00', '2022-08-28 00:00:00', '宜蘭縣頭城鎮', 24.87804, 121.8415, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='WAIAO搖滾月夜、星空浪花市集 8/28 相揪 chill 一夏', `description`='東北角最潮打卡點在外澳！ 搖滾月夜、星空浪花市集 8/28 相揪 chill 一夏 沿岸變化多端的地景、一望無際的湛藍大海，與格外自由奔放的空氣，是吸引旅人不斷再訪的東北角式魅力，而夏天正是最能深刻感受在地獨有氛圍的季節！交通部觀光局東北角暨宜蘭海岸國家風景管理處（以下簡稱東北角管理處），今年夏季尾聲延續「悸動東北角」精神，邀請歌手高蕾雅、戰嬿舞團、即將成真火舞團、夏那樂團帶來獨具風格的搖滾月夜，串連東北角在地品牌打造星空浪花市集，廣邀民眾在8月28日來到大海邊打卡外澳最新拍照基地，享受屬於東北角的微醺浪漫，讓心情隨著起伏浪花 chill 一夏！ 東北角管理處馬惠達處長表示，隨著新型冠狀病毒肺炎（COVID-19）起伏，各地觀光產業難免遭受衝擊與影響，然而管理處長期關注轄區內休閒產業發展，這段時期正是協助業者沉寂再出發的好時機；進入相對穩定的後疫情時代，島內旅遊的興盛反映出國人出走旅遊的渴', `organizer`='東北角暨宜蘭海岸國家風景區管理處', `address`='宜蘭縣頭城鎮濱海路二段6號', `start_date`='2022-08-28 00:00:00', `end_date`='2022-08-28 00:00:00', `location`='宜蘭縣頭城鎮', `latitude`=24.87804, `longitude`=121.8415, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
