INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9378805', '中山分館「借書DIY 蛇年好禮來」自助借閱推廣活動來了，歡迎參加!', '活動目的：為鼓勵讀者使用自助借書機及推廣手機借書，辦理「借書DIY 蛇年好禮來」推廣活動，希望讀者能借好書，同時拿好禮。活動對象：於活動期間以自助借書機或手機借書之個人證讀者。活動日期：3月21日至6月30日活動地點：臺北市立圖書館中山分館 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;活動辦法：1.讀者於活動期間內，使用自助借書機或手機借書5本以上，憑借書收據或手機截圖，搭配閱讀存摺點數，可至服務臺兌換獎品。有珪藻土杯墊、原子筆、二手圖書等，每位讀者一天可以兌換一次。2. 借書搭配使用閱讀存摺點數50點可兌換珪藻土杯墊。使用閱讀存摺點數10點可兌換原子筆1支，使用閱讀存摺點數50點可兌換二手書1本。二手圖書於活動期間置於櫃檯前方供讀者選取，可能隨時補充及更動。所有獎品兌換後均無法更換。3.獎品如因參與讀者踴躍致於活動截止(6/30)前換完，本項活動同時提早結束。4.如有隨借隨還等違反推廣閱讀情事，恕取消參加此活動資格。', '臺北市立圖書館', '無資料', '2025-03-21 00:00:00', '2025-06-30 00:00:00', '無資料', 0, 0, '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=016DC1EEACAB053C', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中山分館「借書DIY 蛇年好禮來」自助借閱推廣活動來了，歡迎參加!', `description`='活動目的：為鼓勵讀者使用自助借書機及推廣手機借書，辦理「借書DIY 蛇年好禮來」推廣活動，希望讀者能借好書，同時拿好禮。活動對象：於活動期間以自助借書機或手機借書之個人證讀者。活動日期：3月21日至6月30日活動地點：臺北市立圖書館中山分館 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;活動辦法：1.讀者於活動期間內，使用自助借書機或手機借書5本以上，憑借書收據或手機截圖，搭配閱讀存摺點數，可至服務臺兌換獎品。有珪藻土杯墊、原子筆、二手圖書等，每位讀者一天可以兌換一次。2. 借書搭配使用閱讀存摺點數50點可兌換珪藻土杯墊。使用閱讀存摺點數10點可兌換原子筆1支，使用閱讀存摺點數50點可兌換二手書1本。二手圖書於活動期間置於櫃檯前方供讀者選取，可能隨時補充及更動。所有獎品兌換後均無法更換。3.獎品如因參與讀者踴躍致於活動截止(6/30)前換完，本項活動同時提早結束。4.如有隨借隨還等違反推廣閱讀情事，恕取消參加此活動資格。', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-03-21 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='無資料', `latitude`=0, `longitude`=0, `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=016DC1EEACAB053C', `image_url`='[]';
