INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004047', '金門金響亮樂團「歌詠金門」音樂會', '金門金響亮樂團「歌詠金門」音樂會-巡演啟動 音樂譜寫歷史文化新篇章-展開一系列社區與機構巡演，透過音樂展現金門豐厚的歷史底蘊與獨特的人文風情，為觀眾帶來一場視覺與聽覺兼具的文化饗宴。本次演出不僅是對金門文化的致敬，更是一次創新與傳承的結合。金門金響亮樂團 以金門的自然環境與文化特色為核心，精心編排曲目，透過悠揚旋律勾勒這片土地的故事，期望讓觀眾在樂聲中感受金門的深遠韻味，並建立更深厚的文化認同。「歌詠金門」音樂會將於下列時間與地點舉行：114年2月21日(五)19:00｜山外社區發展協會114年3月8日(六) 14:30｜大同之家114年3月29日(六)19:00｜上林社區發展協會114年4月12日(六)19:00｜信義社區發展協會114年5月17日(六)19:00｜古寧頭辦公室114年6月14日)六)19:00｜瓊林里辦公室歡迎有興趣的大小朋友共襄盛舉，透過音樂感受金門的歷史脈動與文化魅力，並在樂聲中尋找到對這片土地的全新詮釋與共鳴。歡迎民眾踴躍參與，一同沉浸於這場充滿情感與故事的音樂旅程。', '金門縣政府', '無資料', '2025-02-21 14:30:00', '2025-06-14 21:00:00', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='金門金響亮樂團「歌詠金門」音樂會', `description`='金門金響亮樂團「歌詠金門」音樂會-巡演啟動 音樂譜寫歷史文化新篇章-展開一系列社區與機構巡演，透過音樂展現金門豐厚的歷史底蘊與獨特的人文風情，為觀眾帶來一場視覺與聽覺兼具的文化饗宴。本次演出不僅是對金門文化的致敬，更是一次創新與傳承的結合。金門金響亮樂團 以金門的自然環境與文化特色為核心，精心編排曲目，透過悠揚旋律勾勒這片土地的故事，期望讓觀眾在樂聲中感受金門的深遠韻味，並建立更深厚的文化認同。「歌詠金門」音樂會將於下列時間與地點舉行：114年2月21日(五)19:00｜山外社區發展協會114年3月8日(六) 14:30｜大同之家114年3月29日(六)19:00｜上林社區發展協會114年4月12日(六)19:00｜信義社區發展協會114年5月17日(六)19:00｜古寧頭辦公室114年6月14日)六)19:00｜瓊林里辦公室歡迎有興趣的大小朋友共襄盛舉，透過音樂感受金門的歷史脈動與文化魅力，並在樂聲中尋找到對這片土地的全新詮釋與共鳴。歡迎民眾踴躍參與，一同沉浸於這場充滿情感與故事的音樂旅程。', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-02-21 14:30:00', `end_date`='2025-06-14 21:00:00', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004048', '114年全縣美術家聯展', '114年全縣美術家聯展展期｜114年3月22日-4月09日展地｜金門縣文化局第一、二、三展場開幕式｜3月22日(六)上午10:00開幕式特邀地區傀儡戲達人蔡遠進老師配合其特藏室展出「嘉禮豐華─傀儡戲偶展」在開幕前表演拿手的傀儡戱暖場，將為地區一年一度的藝術盛事的聯合開幕增添熱鬧氣氛，歡迎鄉親踴躍參與。藝術講座｜3月22日(六)下午2時邀請張國英 老師於三樓會議室舉行「草圖與創作」藝術講座 ； 張老師將多年來從事美術教育及藝術創作的個人豐富經驗和體認心得作有系統的整理，內容包括為創作的準備工作：1.繪畫的基礎&mdash;-關於學習（應該學什麼？）2.心中的典範是什麼&mdash;-自己決定未來方向。3.一件藝術品的產生經歷&mdash;&mdash;草圖與創作。4.靈感？題材、內容、主題、形式、技巧。並結合畫展觀摩，以和地區從事美學工作者和喜好藝術的人士來場面對面交流激盪，以提升地區美學的感染力，極度令人期待。本展已進入第34個年頭，致力於提供本縣和旅外的藝術創作者，提供他們一個展現才華與交流的平台。此次徵件涵蓋水墨、書法、水彩、油畫、膠彩、版畫、陶藝、雕塑、攝影、及綜合媒材等10個類別，經過本縣各藝術團體收集各類型作品及共約180餘件參展。展覽將呈現近年來地區藝文團體和藝術工作者在不停的教學相長和相互成長中呈現多元風格，作品內容主要涵蓋鄉土風情、日常寫生經驗、以及對金門發展現況的觀察與反思。透過不同媒材與技法，將各自的理念轉化為對摰愛家鄉獨特的藝術呈現，以激盪創意並促進藝術交流。期待透過此次展出，能讓來地區的鄉親在工作或閒暇之餘仍能徜徉於不同的山水墨韻、彩筆鄉情和不同藝術展現的人文空間裡，透過畫作與民眾來場心靈交流，讓文化局也能成為一座豐富多元的藝術展館。歡迎對這場美術展有興趣的民眾鄉親，在展期內前往金門縣文化局展場參觀，並請密切關注臉書「藝起金門」或查閱官方資訊以了解更多細節。金門縣文化局/主辦金門縣美術學會/辦', '金門縣政府', '無資料', '2025-03-22 08:00:00', '2025-04-09 17:30:00', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年全縣美術家聯展', `description`='114年全縣美術家聯展展期｜114年3月22日-4月09日展地｜金門縣文化局第一、二、三展場開幕式｜3月22日(六)上午10:00開幕式特邀地區傀儡戲達人蔡遠進老師配合其特藏室展出「嘉禮豐華─傀儡戲偶展」在開幕前表演拿手的傀儡戱暖場，將為地區一年一度的藝術盛事的聯合開幕增添熱鬧氣氛，歡迎鄉親踴躍參與。藝術講座｜3月22日(六)下午2時邀請張國英 老師於三樓會議室舉行「草圖與創作」藝術講座 ； 張老師將多年來從事美術教育及藝術創作的個人豐富經驗和體認心得作有系統的整理，內容包括為創作的準備工作：1.繪畫的基礎&mdash;-關於學習（應該學什麼？）2.心中的典範是什麼&mdash;-自己決定未來方向。3.一件藝術品的產生經歷&mdash;&mdash;草圖與創作。4.靈感？題材、內容、主題、形式、技巧。並結合畫展觀摩，以和地區從事美學工作者和喜好藝術的人士來場面對面交流激盪，以提升地區美學的感染力，極度令人期待。本展已進入第34個年頭，致力於提供本縣和旅外的藝術創作者，提供他們一個展現才華與交流的平台。此次徵件涵蓋水墨、書法、水彩、油畫、膠彩、版畫、陶藝、雕塑、攝影、及綜合媒材等10個類別，經過本縣各藝術團體收集各類型作品及共約180餘件參展。展覽將呈現近年來地區藝文團體和藝術工作者在不停的教學相長和相互成長中呈現多元風格，作品內容主要涵蓋鄉土風情、日常寫生經驗、以及對金門發展現況的觀察與反思。透過不同媒材與技法，將各自的理念轉化為對摰愛家鄉獨特的藝術呈現，以激盪創意並促進藝術交流。期待透過此次展出，能讓來地區的鄉親在工作或閒暇之餘仍能徜徉於不同的山水墨韻、彩筆鄉情和不同藝術展現的人文空間裡，透過畫作與民眾來場心靈交流，讓文化局也能成為一座豐富多元的藝術展館。歡迎對這場美