INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005959', '2025夜訪小野柳', '活動時間｜4月1日至10月31日活動地點｜台東縣台東市松江路一段500號 (小野柳環教小屋)114年度「夜訪小野柳」環境教育活動說明每團10-20人(可以併團)，每日限量150人。若人數不足10人，將電話通知不成團。活動三日前報名者，早鳥價每人收費150元；當日或前二日(含)報名者，因增加行政作業以原價200元計收。2歲以下免費，幼童需家長陪同。活動費用請於報到時現場繳納，請留意停車費另計。(小型車停車費：假日60元、非假日50元；機車停車費：假日20元、非假日15元)報到時請派一人至報到處報到即可，其餘人至空曠處等待。請自備手電筒、飲水，穿著長褲、包鞋，並聽從解說老師指引。活動僅在園區步道上行進，行程不會走到潮間帶或踩進海水。若遇大雨取消活動，將電話通知並在當日下午五點前於「小野柳自然教室」FB粉絲專頁公告，若小雨則照常舉行，請依天氣狀況自備雨具。活動期間之合影照片將放在「小野柳自然教室」FB粉絲專頁上，活動後可自行下載。活動不提供保險，若有需求請自行投保。連絡電話：089-281238(小野柳自然教室)。', '交通部觀光署東部海岸國家風景區管理處', '無資料', '2025-04-01 00:00:00', '2025-10-31 23:59:59', '臺東縣臺東市', 22.79504, 121.19571, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025夜訪小野柳', `description`='活動時間｜4月1日至10月31日活動地點｜台東縣台東市松江路一段500號 (小野柳環教小屋)114年度「夜訪小野柳」環境教育活動說明每團10-20人(可以併團)，每日限量150人。若人數不足10人，將電話通知不成團。活動三日前報名者，早鳥價每人收費150元；當日或前二日(含)報名者，因增加行政作業以原價200元計收。2歲以下免費，幼童需家長陪同。活動費用請於報到時現場繳納，請留意停車費另計。(小型車停車費：假日60元、非假日50元；機車停車費：假日20元、非假日15元)報到時請派一人至報到處報到即可，其餘人至空曠處等待。請自備手電筒、飲水，穿著長褲、包鞋，並聽從解說老師指引。活動僅在園區步道上行進，行程不會走到潮間帶或踩進海水。若遇大雨取消活動，將電話通知並在當日下午五點前於「小野柳自然教室」FB粉絲專頁公告，若小雨則照常舉行，請依天氣狀況自備雨具。活動期間之合影照片將放在「小野柳自然教室」FB粉絲專頁上，活動後可自行下載。活動不提供保險，若有需求請自行投保。連絡電話：089-281238(小野柳自然教室)。', `organizer`='交通部觀光署東部海岸國家風景區管理處', `address`='無資料', `start_date`='2025-04-01 00:00:00', `end_date`='2025-10-31 23:59:59', `location`='臺東縣臺東市', `latitude`=22.79504, `longitude`=121.19571, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
