INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6770746c26b32458d4363284', '偶．多元文化之身 特展', '國立臺灣博物館自日本時代即陸續蒐藏閩南及南洋地區與偶戲相關的文物，在總督府博物館和台灣省立博物館的既有基礎上，累積偶戲館藏約1千餘件。2020年台原亞洲偶戲博物館的林經甫博士，將其多達1萬1千多件遍及全球之偶戲文物捐贈至臺博館，使臺博館偶戲典藏多達1萬5千餘件，躋身當今世界擁有重要亞洲偶戲藏品的博物館之列。\n\n林經甫博士捐贈的偶戲文物包含臺灣、閩南、客家的傳統戲偶，還有緬甸、越南、柬埔寨、印尼、泰國、印度、日本等國家，是亞洲最具完整性的戲偶收藏。同時有多類偶戲之戲台、戲偶、戲服、道具與劇本，亦有諸多相關的繪畫、雕塑與面具等，種類極豐。其中還有許多來自世界各地的「民間佚名」藝師之手，承載著各地多元文化中以往較不被關注的重要瑰寶。\n\n本展精選台原捐贈的偶戲文物之精華，以「偶‧多元文化之身」為名，點出：偶之身是因一地文化而塑成，因此其亦可視為文化之身。\n\n內容劃分三大主題：「打開偶戲珍寶箱」、「偶戲千面收萬象」及「觀覽偶戲萬花筒」，突破過往多從地域論偶戲的格套，以更寬廣的視角探討偶戲的文化價值與多元風貌。\n\n\n	\n		\n			\n			\n			\n			\n		\n		\n			\n			\n		\n		\n			\n			\n		\n	\n\n\n \n\n \n\n ', '國立臺灣博物館', '中正區襄陽路2號(二二八公園內)', '2024-12-31 00:00:00', '2025-08-31 00:00:00', '臺博館本館1樓東展間', 25.0418254, 121.5149875, '全票：每張 30元｜半票：每張 15元（本館及古生物館一票共用）', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40292', '[]') ON DUPLICATE KEY UPDATE `activity_name`='偶．多元文化之身 特展', `description`='國立臺灣博物館自日本時代即陸續蒐藏閩南及南洋地區與偶戲相關的文物，在總督府博物館和台灣省立博物館的既有基礎上，累積偶戲館藏約1千餘件。2020年台原亞洲偶戲博物館的林經甫博士，將其多達1萬1千多件遍及全球之偶戲文物捐贈至臺博館，使臺博館偶戲典藏多達1萬5千餘件，躋身當今世界擁有重要亞洲偶戲藏品的博物館之列。\n\n林經甫博士捐贈的偶戲文物包含臺灣、閩南、客家的傳統戲偶，還有緬甸、越南、柬埔寨、印尼、泰國、印度、日本等國家，是亞洲最具完整性的戲偶收藏。同時有多類偶戲之戲台、戲偶、戲服、道具與劇本，亦有諸多相關的繪畫、雕塑與面具等，種類極豐。其中還有許多來自世界各地的「民間佚名」藝師之手，承載著各地多元文化中以往較不被關注的重要瑰寶。\n\n本展精選台原捐贈的偶戲文物之精華，以「偶‧多元文化之身」為名，點出：偶之身是因一地文化而塑成，因此其亦可視為文化之身。\n\n內容劃分三大主題：「打開偶戲珍寶箱」、「偶戲千面收萬象」及「觀覽偶戲萬花筒」，突破過往多從地域論偶戲的格套，以更寬廣的視角探討偶戲的文化價值與多元風貌。\n\n\n	\n		\n			\n			\n			\n			\n		\n		\n			\n			\n		\n		\n			\n			\n		\n	\n\n\n \n\n \n\n ', `organizer`='國立臺灣博物館', `address`='中正區襄陽路2號(二二八公園內)', `start_date`='2024-12-31 00:00:00', `end_date`='2025-08-31 00:00:00', `location`='臺博館本館1樓東展間', `latitude`=25.0418254, `longitude`=121.5149875, `ticket_price`='全票：每張 30元｜半票：每張 15元（本館及古生物館一票共用）', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=40292', `image_url`='[]';
