INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80beb26b3240c403d979a', '吉他演奏初級班【新開班】', '課程及教學內容將依學員程度及學習狀況斟酌調整\n\n可先自備尼龍弦吉他\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			吉他演奏\n			\n			\n			授課老師：孫家偉\n			\n		\n		\n			\n			 \n\n			 \n\n			課\n\n			程\n\n			大\n\n			綱\n\n			 \n			\n			\n			次序\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			樂理基礎一 ，認識古典吉他、樂曲演奏示範 \n			\n		\n		\n			\n			2\n			\n			\n			樂理基礎二  ，左右手彈奏技巧，基本演奏姿勢\n			\n		\n		\n			\n			3\n			\n			\n			樂理基礎三   曲目指導，Ｃ大調音階（一個八度）\n			\n		\n		\n			\n			4\n			\n			\n			樂理基礎四   右手彈奏姿勢教學、觸弦技巧 \n			\n		\n		\n			\n			5\n			\n			\n			文藝復興時期音樂介紹 ，圓滑奏，簡易獨奏曲指導\n			\n		\n		\n			\n			6\n			\n			\n			巴洛克時期吉他音樂介紹 簡易獨奏曲指導，手指獨立性練習一\n			\n		\n		\n			\n			7\n			\n			\n			古典時期吉他音樂介紹，  簡易獨奏曲指導，手指獨立性練習一\n			\n		\n		\n			\n			8\n			\n			\n			浪漫時期吉他音樂介紹，節奏練習，左右手協調性練習\n			\n		\n		\n			\n			9\n			\n			\n			講座音樂會分享\n			\n		\n		\n			\n			10\n			\n			\n			國民樂派吉他音樂介紹，節奏練習，獨奏曲指導\n			\n		\n		\n			\n			11\n			\n			\n			近代吉他音樂介紹，合奏練習\n			\n		\n		\n			\n			12\n			\n			\n			合奏曲目指導，基礎和弦，Ｃ大調音階（兩個八度）\n			\n		\n		\n			\n			13\n			\n			\n			獨奏曲與合奏曲目指導，泛音奏法，分散和弦練習曲\n			\n		\n		\n			\n			14\n			\n			\n			獨奏曲與合奏曲目指導，基礎樂理\n			\n		\n		\n			\n			15\n			\n			\n			獨奏曲與合奏曲目指導，成果紀錄\n			\n		\n	\n\n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-12 00:00:00', '2025-08-18 00:00:00', '園區教室(二)', 25.0367564, 121.519047, '3000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50676', '[]') ON DUPLICATE KEY UPDATE `activity_name`='吉他演奏初級班【新開班】', `description`='課程及教學內容將依學員程度及學習狀況斟酌調整\n\n可先自備尼龍弦吉他\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			吉他演奏\n			\n			\n			授課老師：孫家偉\n			\n		\n		\n			\n			 \n\n			 \n\n			課\n\n			程\n\n			大\n\n			綱\n\n			 \n			\n			\n			次序\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			樂理基礎一 ，認識古典吉他、樂曲演奏示範 \n			\n		\n		\n			\n			2\n			\n			\n			樂理基礎二  ，左右手彈奏技巧，