INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80beb26b3240c403d97a3', '詩歌鑑賞與生活美學', '課程內容：由如何鑑賞詩歌，詩歌鑑賞與生活中的美學要義連結，到詩歌吟詠諷誦的引領、帶唱、方法學習，唐詩宋詞元曲與名家現代詩，都在講授之列。此期課程，以〈「新」如何閱讀一首詩〉一書的篇章、吟誦，以及延伸相關戲曲著名唱段欣賞為講授內容。\n\n \n\n114-2期 課程大綱\n\n\n	\n		\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			第1週\n\n			5/14\n			\n			\n			寄寓胸懷的四幅圖畫\n\n			談情景交融\n			\n			\n			唐代杜甫〈絕句‧兩個黃鸝〉\n			\n		\n		\n			\n			第2週\n\n			5/21\n			\n			\n			象徵孤高的天地沙鷗\n\n			談意象\n			\n			\n			唐代杜甫〈旅夜書懷〉\n			\n		\n		\n			\n			第3週\n\n			5/28\n			\n			\n			5/28縱橫時空的詩聖病客\n\n			談遠遊\n			\n			\n			唐代杜甫〈登高〉\n			\n		\n		\n			\n			第4週\n\n			6/4\n			\n			\n			悲憫百姓苦於烽火\n\n			談戰爭\n			\n			\n			唐代杜甫〈兵車行〉\n			\n		\n		\n			\n			第5週\n\n			6/11\n			\n			\n			秋天颶風跟詩聖開玩笑\n\n			談古代建築\n			\n			\n			唐代杜甫〈茅屋為秋風所破歌〉\n			\n		\n		\n			\n			第6週\n\n			6/18\n			\n			\n			天地人三才的燭照\n\n			談漁樵耕讀\n			\n			\n			唐代柳宗元〈江雪〉\n			\n		\n		\n			\n			第7週\n\n			6/25\n			\n			\n			天晚欲雪的溫馨情意\n\n			談鄰居\n			\n			\n			唐代白居易〈問劉十九〉\n			\n		\n		\n			\n			第8週\n\n			7/02\n			\n			\n			千古知名的離別歌\n\n			談友情\n			\n			\n			唐代白居易〈賦得古原草送別〉\n			\n		\n		\n			\n			第9週\n\n			7/09\n			\n			\n			令人感喟的貧富差距\n\n			談流行\n			\n			\n			唐代白居易〈買花〉\n			\n		\n		\n			\n			第10週\n\n			7/16\n			\n			\n			空靈如幻的水墨國畫\n\n			談墨意\n			\n			\n			唐代杜牧〈山行〉\n			\n		\n		\n			\n			第11週\n\n			7/23\n			\n			\n			醉生夢死的亡國前奏\n\n			談衰敗\n			\n			\n			唐代杜牧〈泊秦淮〉\n			\n		\n		\n			\n			第12週\n\n			7/30\n			\n			\n			景情映襯的歷史感慨\n\n			談南朝佛教信仰\n			\n			\n			唐代杜牧〈江南春〉\n			\n		\n		\n			\n			第13週\n\n			8/06\n			\n			\n			韶華不為少年留的傷逝\n\n			談唐代的樂遊原\n			\n			\n			唐代李商隱〈登樂遊原〉\n			\n		\n		\n			\n			第14週\n\n			8/13\n			\n			\n			仕途不順猶清鳴\n\n			談風骨\n			\n			\n			唐代李商隱〈蟬〉\n			\n		\n		\n			\n			第15週\n\n			8/20\n			\n			\n			前情難追難言的悵惘\n\n			談愛而不能言的淒楚\n			\n			\n			唐代李商隱〈錦瑟〉', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-14 00:00:00', '2025-08-20 00:00:0