INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bec26b3240c403d97a7', '小品基礎水彩畫', '5/26、6/2、6/30停課 \n\n★請自備2B鉛筆、橡皮擦、水彩本，顏料由班上統一購買\n\n★本表所安排之課題及教學內容將依據學員程度及學習狀況斟酌調整。\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			小品基礎水彩畫\n			\n			\n			授課老師\n			\n			\n			洪東標\n			\n		\n		\n			\n			 \n\n			 \n\n			課\n\n			程\n\n			大\n\n			綱\n\n			 \n			\n			\n			週次\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			水彩的基本概念與色階練習\n			\n		\n		\n			\n			2\n			\n			\n			幾何形體的生活物件描寫與觀察\n			\n		\n		\n			\n			3\n			\n			\n			器物組合描寫觀察與練習\n			\n		\n		\n			\n			4\n			\n			\n			蔬果的觀察與描寫\n			\n		\n		\n			\n			5\n			\n			\n			靜物作品賞析與檢討\n			\n		\n		\n			\n			6\n			\n			\n			抽象造型的創作練習\n			\n		\n		\n			\n			7\n			\n			\n			食品的觀察與描寫一\n			\n		\n		\n			\n			8\n			\n			\n			食品的觀察與描寫二\n			\n		\n		\n			\n			9\n			\n			\n			植物的觀察與描寫一\n			\n		\n		\n			\n			10\n			\n			\n			植物的觀察與描寫二\n			\n		\n		\n			\n			11\n			\n			\n			作品分享賞析與檢討\n			\n		\n		\n			\n			12\n			\n			\n			名家作品賞析與作品的裝裱\n			\n		\n	\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-12 00:00:00', '2025-08-18 00:00:00', 'W316教室', 25.0367564, 121.519047, '2400', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50600', '[]') ON DUPLICATE KEY UPDATE `activity_name`='小品基礎水彩畫', `description`='5/26、6/2、6/30停課 \n\n★請自備2B鉛筆、橡皮擦、水彩本，顏料由班上統一購買\n\n★本表所安排之課題及教學內容將依據學員程度及學習狀況斟酌調整。\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			小品基礎水彩畫\n			\n			\n			授課老師\n			\n			\n			洪東標\n			\n		\n		\n			\n			 \n\n			 \n\n			課\n\n			程\n\n			大\n\n			綱\n\n			 \n			\n			\n			週次\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			水彩的基本概念與色階練習\n			\n		\n		\n			\n			2\n			\n			\n			幾何形體的生活物件描寫與觀察\n			\n		\n		\n			\n			3\n			\n			\n			器物組合描寫觀察與練習\n			\n		\n		\n			\n			4\n			\n			\n			蔬果的觀察與描寫\n			\n		\n		\n			\n			5\n			\n			\n			靜物作品賞析與檢討\n			\n		\n		\n			\n			6\n			\n			\n			抽象造型的創作練習\n			\n		\n		\n			