INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bec26b3240c403d97a9', '中醫養生文化', '陳醫師從事中醫臨床工作超過三十年，除醫治疑難雜症，教導民眾養生及保健之道。\n\n \n\n\n	\n		\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			5/12\n			\n			\n			中醫基礎理論中氣血水的概論\n			\n			\n			介紹中醫氣血水的生理作用與病理特點\n			\n		\n		\n			\n			5/19\n			\n			\n			甚麼是氣滯症？\n			\n			\n			介紹甚麼是氣滯症，及其養生的策略\n			\n		\n		\n			\n			5/26\n			\n			\n			常用中醫理氣藥在養生的運用１\n			\n			\n			介紹常用理氣藥：橘皮類中藥的養生運用\n			\n		\n		\n			\n			6/2\n			\n			\n			常用中醫理氣藥在養生的運用２\n			\n			\n			介紹常用理氣藥：花類中藥的養生運用\n			\n		\n		\n			\n			6/9\n			\n			\n			甚麼是血瘀症？\n			\n			\n			介紹甚麼是血瘀症，及其養生的策略\n			\n		\n		\n			\n			6/16\n			\n			\n			疼痛的中醫治療與養生策略\n			\n			\n			介紹中醫對於疼痛的治療與養生理論與策略\n			\n		\n		\n			\n			6/23\n			\n			\n			常用中醫化瘀藥在養生的運用１\n			\n			\n			介紹鬱金、薑黃、益母草等的養生運用\n			\n		\n		\n			\n			6/30\n			\n			\n			常用中醫化瘀藥在養生的運用２\n			\n			\n			介紹丹參、紅花、桃仁等的養生運用\n			\n		\n		\n			\n			7/7\n			\n			\n			甚麼是痰症？\n			\n			\n			介紹甚麼是痰症，及其養生的策略\n			\n		\n		\n			\n			7/14\n			\n			\n			咳嗽的中醫治療與養生策略\n			\n			\n			介紹中醫對於咳嗽的治療與養生理論與策略\n			\n		\n		\n			\n			7/21\n			\n			\n			常用中醫化痰藥在養生的運用１\n			\n			\n			介紹貝母、竹茹等的養生運用\n			\n		\n		\n			\n			7/28\n			\n			\n			常用中醫化瘀藥在養生的運用２\n			\n			\n			介紹海藻、昆布等的養生運用\n			\n		\n		\n			\n			8/4\n			\n			\n			常用中醫止咳藥在養生的運用１\n			\n			\n			介紹杏仁、枇杷葉等的養生運用\n			\n		\n		\n			\n			8/11\n			\n			\n			睡眠的中醫養生保健策略\n			\n			\n			介紹中醫治療失眠及熬夜的養生策略\n			\n		\n		\n			\n			8/18\n			\n			\n			常用中醫安神藥在養生的運用\n			\n			\n			介紹酸棗仁、柏子仁等的養生運用', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-12 00:00:00', '2025-08-18 00:00:00', 'W311教室', 25.0367564, 121.519047, '2000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50602', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中醫養生文化', `description`='陳醫師從事中醫臨床工作超過三十年，除醫治疑難雜症，教導民眾養生及保健之道。\n\n \n\n\n	\n		\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			