INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bec26b3240c403d97af', '彼拉提斯B(初級)', '6/1停課\n\n\n	\n		\n			 \n			\n			次序\n			\n			\n			課程主題\n			\n			\n			教學內容\n			\n		\n		\n			\n			課\n\n			 \n\n			 \n\n			程\n\n			 \n\n			 \n\n			大\n\n			 \n\n			 \n\n			綱\n			\n			\n			1\n			\n			\n			身體本能\n			\n			\n			找回身體的核心價值，重啟身體的自癒能力。\n			\n		\n		\n			\n			2\n			\n			\n			氣運益體\n			\n			\n			腹式呼吸有益橫隔膜，並有益身體新陳代謝。\n			\n		\n		\n			\n			3\n			\n			\n			體感節奏\n			\n			\n			意念動而後身息運作，意念止而後心靜身正。\n			\n		\n		\n			\n			4\n			\n			\n			體態自癒\n			\n			\n			錯誤運動會勞損筋骨，正確體式能自我修復。\n			\n		\n		\n			\n			5\n			\n			\n			核心樞紐\n			\n			\n			力量運用源於核心處，核心穩定能預防傷害。\n			\n		\n		\n			\n			6\n			\n			\n			椎間柔韌\n			\n			\n			背肌訓練能強健脊柱，弓式體位能舒展脊椎。\n			\n		\n		\n			\n			7\n			\n			\n			舒展肌群\n			\n			\n			伸展肌群能增加韌性，並且改善關節穩定度。\n			\n		\n		\n			\n			8\n			\n			\n			耐力如恆\n			\n			\n			肌耐力增加有益燃脂，並能減少肌肉疲勞感。\n			\n		\n		\n			\n			9\n			\n			\n			慢伸緩屈\n			\n			\n			體位難可選替代動作，筋骨較緊可循序漸進。\n			\n		\n		\n			\n			10\n			\n			\n			緩旋慢扭\n			\n			\n			拉伸背脊可舒緩背部，扭轉體位能靈活脊椎。\n			\n		\n		\n			\n			11\n			\n			\n			妥旋關節\n			\n			\n			放任體重使關節受損，缺乏運動使關節退化。\n			\n		\n		\n			\n			12\n			\n			\n			頻舉若穩\n			\n			\n			單腳平衡強化髖關節，蚌殼式強化骨盆肌群。\n			\n		\n		\n			\n			13\n			\n			\n			柔筋潤帶\n			\n			\n			勞逸過度使韌帶鬆弛，適度運動能保健韌帶。\n			\n		\n		\n			14\n			骨盆本位\n			骨盆正位能促進循環，骨盆體操能改善腰背。\n		\n		\n			\n			15\n			\n			\n			安頓身心\n			\n			\n			意識臨在於收勢當下，靜默端坐能安頓身心。\n			\n		\n	\n\n\n   ★ 請學員自備瑜珈磚、瑜珈墊', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-18 00:00:00', '2025-08-31 00:00:00', 'E305教室', 25.0367564, 121.519047, '2000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50608', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彼拉提斯B(初級)', `description`='6/1停課\n\n\n	\n		\n			 \n			\n			次序\n			\n			\n			課程主題\n			\n			\n			教學內容\n			\n		\n		\n			\n			課\n\n			 \n\n			 \n\n			程\n\n			 \n\n			 \n