INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bec26b3240c403d97b1', '油性粉彩班', '5/31停課\n\n★新進學員第一堂課請自備：美工刀，切割墊（或代用品），直尺及2B鉛筆。\n\n★新進學員材料費預計為1000元\n\n★本表所安排之課題及教學內容將依據學員之學習狀況斟酌調整。\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			油性粉彩班\n			\n			\n			授課老師\n			\n			\n			陳瑞西\n			\n		\n		\n			\n			 \n\n			 \n\n			課\n\n			程\n\n			大\n\n			綱\n\n			 \n			\n			\n			週次\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			認識油性粉彩顏料及搭配工具\n\n			油性粉彩畫作賞析及基本技法\n			\n		\n		\n			\n			2\n			\n			\n			畫作1-1(魚)\n\n			示範講解繪畫程序:構圖、輪廓線、塊面、混色技巧\n			\n		\n		\n			\n			3\n			\n			\n			畫作1-2(魚)\n\n			示範講解繪畫程序:細節、質感、畫面整體效果\n			\n		\n		\n			\n			4\n			\n			\n			畫作2-1(鳥)\n\n			示範講解繪畫程序:構圖、輪廓線、塊面、混色技巧\n			\n		\n		\n			\n			5\n			\n			\n			畫作2-2(鳥)\n\n			示範講解繪畫程序:細節、質感、畫面整體效果\n			\n		\n		\n			\n			6\n			\n			\n			畫作3-1(花)\n\n			示範講解繪畫程序:構圖、輪廓線、塊面、混色技巧\n			\n		\n		\n			\n			7\n			\n			\n			畫作3-2(花)\n\n			示範講解繪畫程序:細節、質感、畫面整體效果\n			\n		\n		\n			\n			8\n			\n			\n			展示、講解、欣賞\n\n			個別指導\n			\n		\n		\n			\n			9\n			\n			\n			展示、講解、欣賞\n\n			個別指導\n			\n		\n		\n			\n			10\n			\n			\n			畫作4-1(靜物)\n\n			示範講解繪畫程序:構圖、輪廓線、塊面、混色技巧\n			\n		\n		\n			\n			11\n			\n			\n			畫作4-2(靜物)\n\n			示範講解繪畫程序:細節、質感、畫面整體效果\n			\n		\n		\n			\n			12\n			\n			\n			畫作5-1(風景)\n\n			示範講解繪畫程序:構圖、輪廓線、塊面、混色技巧\n			\n		\n		\n			\n			13\n			\n			\n			畫作5-2(風景)\n\n			示範講解繪畫程序:細節、質感、畫面整體效果\n			\n		\n		\n			\n			14\n			\n			\n			展示、講解、欣賞\n\n			個別指導\n			\n		\n		\n			\n			15\n			\n			\n			展示、講解、欣賞\n\n			個別指導\n			\n		\n	\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-17 00:00:00', '2025-08-30 00:00:00', 'W316教室', 25.0367564, 121.519047, '4500', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50610', '[]') ON DUPLICATE KEY UPDATE `activity_name`='油性粉彩班', `description`='5/31停課\n\n★新進學員第一堂課請自備：美工刀，切割墊（或代用品），直尺及2B鉛筆。\n\n★新進學員材料費預計為1000元\n\n★本表所安排之課題及教學內容將依據學員之學習狀況斟酌調整。\n