INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bec26b3240c403d97b2', '談星論命觀紫微', ' 5/30停課\n\n★本報名費不含教材費。\n\n114-2 課程大綱\n\n\n	\n		\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			第1週\n			\n			\n			術數論命與運吉凶概述\n			\n			\n			諸星為何需要命運歲合參\n			\n		\n		\n			\n			第2週\n			\n			\n			紫微斗數之骨髓賦格局\n			\n			\n			諸星交互影響後吉凶判斷\n			\n		\n		\n			\n			第3週\n			\n			\n			紫微斗數之骨髓賦格局\n			\n			\n			紫微、天機、太陽、武曲、天同—所成格局介紹\n			\n		\n		\n			\n			第4週\n			\n			\n			紫微斗數之骨髓賦格局\n			\n			\n			廉貞、天府、太陰、貪狼、巨門—所成格局介紹\n			\n		\n		\n			\n			第5週\n			\n			\n			紫微斗數之骨髓賦格局\n			\n			\n			天相、天梁、七殺、破軍—所成格局介紹\n			\n		\n		\n			\n			第6週\n			\n			\n			紫微斗數之骨髓賦格局\n			\n			\n			文昌、文曲、天魁、天鉞、左輔、右弼、祿存\n			\n		\n		\n			\n			第7週\n			\n			\n			紫微斗數之太微賦\n			\n			\n			擎羊、陀羅、天空、地劫、火星、鈴星、化忌\n			\n		\n		\n			\n			第8週\n			\n			\n			紫微斗數之太微賦\n			\n			\n			諸星在命盤格局論斷趨向\n			\n		\n		\n			\n			第9週\n			\n			\n			紫微斗數之太微賦\n			\n			\n			諸星在大小運的合參和功能\n			\n		\n		\n			\n			第10週\n			\n			\n			紫微斗數之太微賦\n			\n			\n			諸星在流年太歲及各神煞的影響\n			\n		\n		\n			\n			第11週\n			\n			\n			紫微斗數之女命骨髓賦\n			\n			\n			諸星在命運歲中如何造成傷害的相關論斷\n			\n		\n		\n			\n			第12週\n			\n			\n			紫微斗數之女命骨髓賦\n			\n			\n			神煞在命運歲中如何造成傷害的相關論斷\n			\n		\n		\n			\n			第13週\n			\n			\n			紫微斗數之神煞論斷\n			\n			\n			流年神煞綜合論斷 (一)\n			\n		\n		\n			\n			第14週\n			\n			\n			紫微斗數之神煞論斷\n			\n			\n			流年神煞綜合論斷 (二)\n			\n		\n		\n			\n			第15週\n			\n			\n			紫微斗數之倒限論斷\n			\n			\n			倒限成因介紹與分析\n			\n		\n	\n\n\nPS: 課程內容依實際狀況需求作適當調整。\n\n※本課程教室為階梯教室。', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-16 00:00:00', '2025-08-29 00:00:00', 'W318教室', 25.0367564, 121.519047, '2000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50611', '[]') ON DUPLICATE KEY UPDATE `activity_name`='談星論命觀紫微', `description`=' 5/30停課\n\n★本報名費不含教材費。\n\n114-2 課程大綱\n\n\n	\n		\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n	