INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bee26b3240c403d97c8', '悠墨畫韻書畫班', '5/30停課\n\n★本表所安排之課題及教學內容將依據學員程度及學習狀況斟酌調整。\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			悠墨畫韻書畫班\n			\n			\n			授課老師\n			\n			\n			鄭紅雪\n			\n		\n		\n			\n			 \n\n			 \n\n			課\n\n			程\n\n			大\n\n			綱\n\n			 \n			\n			\n			週次\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			基礎書法研習\n			\n			\n			筆、墨、紙、硯、文房四寶概念;楷、行、草、隸、篆書體介紹\n			\n		\n		\n			\n			2\n			\n			\n			基礎書法研習\n			\n			\n			書法創作與空研究、持筆示範解說; 楷書永字八法習作與示範。\n			\n		\n		\n			\n			3\n			\n			\n			認識書法碑帖與濃淡墨之運用\n			\n			\n			不同書體認識與示範;習作批改與示範﹙現場﹚。\n			\n		\n		\n			\n			4\n			\n			\n			認識書法碑帖概念\n			\n			\n			第二階段書體認識與示範;習作批改與示範\n			\n		\n		\n			\n			5\n			\n			\n			碑帖與書體學習\n			\n			\n			第二階段書體認識與示範;習作批改與示範\n			\n		\n		\n			\n			6\n			\n			\n			碑帖與書體學習\n			\n			\n			第二階段書體認識與示範;習作批改與示範\n			\n		\n		\n			\n			7\n			\n			\n			書法小品介紹\n			\n			\n			書體與空間呼應之設計\n			\n		\n		\n			\n			8\n			\n			\n			書法作品完成\n			\n			\n			書體與空間呼應之設計作品完成與修改\n			\n		\n		\n			\n			9\n			\n			\n			認識水墨畫\n			\n			\n			筆、墨、紙、硯、顏料之媒材概念\n			\n		\n		\n			\n			10\n			\n			\n			書、畫的小品介紹\n			\n			\n			書畫斗方創作構圖概念\n\n			顏色示範\n			\n		\n		\n			\n			11\n			\n			\n			畫的設計概念學習\n			\n			\n			菊花複習與學員作業修改\n			\n		\n		\n			\n			12\n			\n			\n			畫的筆法概念\n			\n			\n			梅花筆法呼應色彩示範\n			\n		\n		\n			\n			13\n			\n			\n			畫的筆法學習\n			\n			\n			竹的筆法介紹\n			\n		\n		\n			\n			14\n			\n			\n			書畫小品創意概念\n			\n			\n			學員作品完整結合調整\n			\n		\n		\n			\n			15\n			\n			\n			書畫小品完成\n			\n			\n			作品完整結合展現', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-16 00:00:00', '2025-08-29 00:00:00', 'W314教室', 25.0367564, 121.519047, '2000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50633', '[]') ON DUPLICATE KEY UPDATE `activity_name`='悠墨畫韻書畫班', `description`='5/30停課\n\n★本表所安排之課題及教學內容將依據學員程度及學習狀況斟酌調整。\n\n\n	\n		\n		