INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bee26b3240c403d97c9', '成人樂活基礎小提琴班', '5/30、6/6、7/25停課\n\n本期計13堂課\n\n本表所安排之課程及教學內容，將依學員學習狀況斟酌調整\n\n\n	\n		\n			\n			週次\n			\n			\n			教學主題\n			\n			\n			教學內容\n			\n		\n		\n			\n			第1週\n			\n			\n			認識樂器與基本空弦練習\n			\n			\n			快速複習小提琴與弓的基本構造、握法與姿勢、空弦拉奏，學習音色控制與運弓穩定性\n			\n		\n		\n			\n			第2週\n			\n			\n			左手基本手型與A弦練習\n			\n			\n			複習左手手型及練習A弦全指法，學習簡單旋律片段\n			\n		\n		\n			\n			第3週\n			\n			\n			D弦基本手型與簡單旋律\n			\n			\n			練習D弦全指法，學習簡單旋律，如《瑪麗有隻小綿羊》\n			\n		\n		\n			\n			第4週\n			\n			\n			A弦與D弦結合演奏\n			\n			\n			熟悉兩條弦指法並學習《康康舞》\n			\n		\n		\n			\n			第5週\n			\n			\n			G弦基本手型與認識換弦\n			\n			\n			練習G弦全指法，學習簡單旋律，並介紹A、D、G弦之間的換弦動作與銜接\n			\n		\n		\n			\n			第6週\n			\n			\n			E弦基本手型與換弦練習\n			\n			\n			練習E弦全指法，學習簡單旋律，結合其他弦進行旋律練習與換弦銜接\n			\n		\n		\n			\n			第7週\n			\n			\n			認識不同節奏類型及調性\n			\n			\n			學習變化的節奏類型及升降記號並結合旋律\n			\n		\n		\n			\n			第8週\n			\n			\n			弓速介紹\n			\n			\n			學習弓的位置分配及快慢弓的應用並結合樂曲\n			\n		\n		\n			\n			第9週\n			\n			\n			斷奏練習\n			\n			\n			學習斷奏及半斷奏的拉奏方式，並與連奏做混和練習\n			\n		\n		\n			\n			第10週\n			\n			\n			總練習\n			\n			\n			總複習四條弦指法並結合不同節奏類型及快慢弓\n			\n		\n		\n			\n			第11週\n			\n			\n			小組分部及合奏\n			\n			\n			增加二部合奏曲目如《Jingle Bells》、《威廉泰爾序曲》，分部練習，學習聆聽其他聲部，統一節奏與音準並加強學員間的合奏能力\n			\n		\n		\n			\n			第12週\n			\n			\n			綜合合奏曲目練習\n			\n			\n			改進合奏細節，強調樂句表達與音樂情感；重複練習已學曲目並嘗試速度變化與音量控制\n			\n		\n		\n			\n			第13週\n			\n			\n			小型成果發表\n			\n			\n			小型音樂會，展示學員學習成果，演奏簡單民謠或合奏曲目，如《Jingle Bells》《威廉泰爾序曲》\n			\n		\n	\n\n\n \n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-09 00:00:00', '2025-08-22 00:00:00', '園區教室(二)', 25.0367564, 121.519047, '3250', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50634', '[]') ON DUPLICATE KEY UPDATE `activity_name`='成人樂活基礎小提琴班', `description`='5/30、6/6、7/25停課\n\n本期計13堂課\n\n本表所安排之課程及教學內容，將依學員學習狀況斟酌調整\n\n\n	\n		\n			\n			週次\n			\n			\n			教學主題\n			\n			\n			教學內容\n			\n		\n		\n			\n			第1週\n			\n			\n			認識樂器與基本空弦練習\n			\n			\n			快速複習小提琴與弓的基本構造、握法與姿勢、空弦拉奏，學習音色控制與運弓穩定性\n			\n		\n		\n			\n			第2週\n			\n			\n			左手基本手型與A弦練習\n			\n			\n			複習左手手型及練習A弦全指法，學習簡單旋律片段\n			\n		\n		\n			\n			第3週\n			\n			\n			D弦基本手型與簡單旋律\n			\n			\n			練習D弦全指法，學習簡單旋律，如《瑪麗有隻小綿羊》\n			\n		\n		\n			\n			第4週\n			\n			\n			A弦與D弦結合演奏\n			\n			\n			熟悉兩條弦指法並學習《康康舞》\n			\n		\n		\n			\n			第5週\n			\n			\n			G弦基本手型與認識換弦\n			\n			\n			練習G弦全指法，學習簡單旋律，並介紹A、D、G弦之間的換弦動作與銜接\n			\n		\n		\n			\n			第6週\n			\n			\n			E弦基本手型與換弦練習\n			\n			\n			練習E弦全指法，學習簡單旋律，結合其他弦進行旋律練習與換弦銜接\n			\n		\n		\n			\n			第7週\n			\n			\n			認識不同節奏類型及調性\n			\n			\n			學習變化的節奏類型及升降記號並結合旋律\n			\n		\n		\n			\n			第8週\n			\n			\n			弓速介紹\n			\n			\n			學習弓的位置分配及快慢弓的應用並結合樂曲\n			\n		\n		\n			\n			第9週\n			\n			\n			斷奏練習\n			\n			\n			學習斷奏及半斷奏的拉奏方式，並與連奏做混和練習\n			\n		\n		\n			\n			第10週\n			\n			\n			總練習\n			\n			\n			總複習四條弦指法並結合不同節奏類型及快慢弓\n			\n		\n		\n			\n			第11週\n			\n			\n			小組分部及合奏\n			\n			\n			增加二部合奏曲目如《Jingle Bells》、《威廉泰爾序曲》，分部練習，學習聆聽其他聲部，統一節奏與音準並加強學員間的合奏能力\n			\n		\n		\n			\n			第12週\n			\n			\n			綜合合奏曲目練習\n			\n			\n			改進合奏細節，強調樂句表達與音樂情感；重複練習已學曲目並嘗試速度變化與音量控制\n			\n		\n		\n			\n			第13週\n			\n			\n			小型成果發表\n			\n			\n			小型音樂會，展示學員學習成果，演奏簡單民謠或合奏曲目，如《Jingle Bells》《威廉泰爾序曲》\n			\n		\n	\n\n\n \n\n \n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-05-09 00:00:00', `end_date`='2025-08-22 00:00:00', `location`='園區教室(二)', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='3250', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50634', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bee26b3240c403d97ca', '城鄉自然野簿', '★5/14為室內課，其餘為戶外課，7/30為夜間觀察課。本表所安排之教學內容將依據季節天候等因素適度調整。\n\n★每堂戶外課皆須保險 (報名費內含保險費)。\n\n★本課程於5/13辦理戶外教學保險事宜。若學員辦理退費，5/13（含）前保險費全額退還，5/14（含）之後由所繳交之費用扣除保險費後，再依退費規定辦理。\n\n★本期有兩次課程＊需租用遊覽車，第一堂課每人請繳交1000元，由班級自治並當期使用完畢不退還。如果當期未能順利選出班長群，得更改遠程課程為近郊公共交通便利的地點。\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			城鄉自然野簿\n			\n			\n			授課老師\n			\n			\n			陳信甫\n			\n		\n		\n			\n			 \n\n			 \n\n			課\n\n			程\n\n			大\n\n			綱\n			\n			\n			週次\n			\n			\n			日期\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			5/14\n			\n			\n			課程簡介與生態主題教學(蝴蝶)（東側301教室）\n			\n		\n		\n			\n			2\n			\n			\n			5/21\n			\n			\n			三重秀江街野花園～植物辨識初體驗\n			\n		\n		\n			\n			3\n			\n			\n			5/28\n			\n			\n			大屯山車道～澤蘭與斑蝶生命交織的初夏\n			\n		\n		\n			\n			4\n			\n			\n			6/4\n			\n			\n			大屯山向天池步道～閱覽大屯群山覓天池（全日）\n			\n		\n		\n			\n			5\n			\n			\n			6/11\n			\n			\n			（與第4週合併上課）\n			\n		\n		\n			\n			6\n			\n			\n			6/18\n			\n			\n			新店二叭子植物園～孟夏晌午城郊踏青去\n			\n		\n		\n			\n			7\n			\n			\n			6/25\n			\n			\n			關渡自然公園～城郊溼地公園覓自然\n			\n		\n		\n			\n			8\n			\n			\n			7/2\n			\n			\n			士林大崎頭步道～古道拾級而下觀梯田\n			\n		\n		\n			\n			9\n			\n			\n			7/9\n			\n			\n			三峽滿月圓國家森林遊樂區～蓊鬱仲夏聆蟬聲（全日）＊\n			\n		\n		\n			\n			10\n			\n			\n			7/16\n			\n			\n			（與第9週合併上課）\n			\n		\n		\n			\n			11\n			\n			\n			7/23\n			\n			\n			士林翠山步道（日觀）～夏日追尋日行蝶蹤\n			\n		\n		\n			\n			12\n			\n			\n			7/30\n			\n			\n			士林翠山步道（夜觀）～夏夜探訪夜行動物\n			\n		\n		\n			\n			13\n			\n			\n			8/6\n			\n			\n			陽明山紫明溪步道～林間小徑尋山幽\n			\n		\n		\n			\n			14\n			\n			\n			8/13\n			\n			\n			石門青山瀑布～季夏尋瀑消暑氣（全日）＊\n			\n		\n		\n			\n			15\n			\n			\n			8/20\n			\n			\n			（與第14週合併上課）\n			\n		\n	\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-14 00:00:00', '2025-08-20 00:00:00', 'E301教室', 25.0367564, 121.519047, '4819', 'https://event.culture.tw/mo