INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bee26b3240c403d97d1', '實用生活美語', '課程內容：進階閱讀文章為主題再搭配小組互動，依照指派的主題分組進行交談及討論。希望能增加英語口語流暢的機會及練習的場合。\n\n5/30停課\n\n\n	\n		\n			\n			課程名稱\n			\n			實用生活美語\n			\n			授課老師\n			\n			\n			李宜玲Elaine\n			\n		\n		\n			\n			課\n\n			程\n\n			大\n\n			綱\n			\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容 Connectivity  5\n			\n		\n		\n			\n			1\n			\n			\n			Unit 5 What’s funny?\n			\n			\n			Goals: Respond to humor / Explore the potential benefits of laughter\n			\n		\n		\n			\n			2\n			\n			\n			Unit 5 What’s funny?\n			\n			\n			Grammar: Questions in indirect speech\n			\n		\n		\n			\n			3\n			\n			\n			Unit 5 What’s funny?\n			\n			\n			Conversations:” Come see this” to invite someone to look at something you think he or she will find interesting\n			\n		\n		\n			\n			4\n			\n			\n			Unit 5 What’s funny?\n			\n			\n			Reading: An article about the health benefits of laughter\n			\n		\n		\n			\n			5\n			\n			\n			Unit 6 On the move\n			\n			\n			Goals: Describe how you deal with commuting / Talk about property lost\n			\n		\n		\n			\n			6\n			\n			\n			Unit 6 On the move\n			\n			\n			Grammar: The unreal conditional \n			\n		\n		\n			\n			7\n			\n			\n			Unit 6 On the move\n			\n			\n			Conversation strategies: Ask a stranger for help with “ I wonder if you could do me a favor?”\n			\n		\n		\n			\n			8\n			\n			\n			Unit 6 On the move\n			\n			\n			Reading: A travel hassles self-test\n			\n		\n		\n			\n			9\n			\n			\n			Unit 7 \n\n			Belief and reality\n			\n			\n			Goals: Describe a scam / fears and phobias\n			\n		\n		\n			\n			10\n			\n			\n			Unit 7 \n\n			Belief and reality\n			\n			\n			Grammar: Reporting beliefs: \n\n			It + a passive reporting verb\n			\n		\n		\n			\n			11\n			\n			\n			Unit 7 \n\n			Belief and reality\n			\n			\n			Conversation:\n\n			“Why am I not surprised?” / “Don’t tell me…” \n			\n		\n		\n			\n			12 \n			\n			\n			Unit 7 \n\n			Belief and reality\n			\n			\n			Reading: A fact sheet about scams\n			\n		\n		\n			\n			13\n			\n			\n			Unit 8\n\n			Achievement and Intelligence\n			\n			\n			Goals: Identify your unique strengths\n			\n		\n		\n			\n			14\n			\n			\n			Unit 8\n\n			Achievement and Intelligence\n			\n			\n			Grammar: Using “do” for emphatic stress \n			\n		\n		\n			\n			15\n			\n			\n			Unit 8\n\n			Achievement and Intelligence\n			\n			\n			Conversations: “So I understand (that)… / Would you say you …?” to encourage someone to express a point of view\n			\n		\n	\n\n\n \n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-16 00:00:00', '2025-08-29 00:00:00', 'W312教室', 25.0367564, 121.519047, '2000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50643', '[]') ON DUPLICATE KEY UPDATE `activity_name`='實用生活美語', `description`='課程內容：進階閱讀文章為主題再搭配小組互動，依照指派的主題分組進行交談及討論。希望能增加英語口語流暢的機會及練習的場合。\n\n5/30停課\n\n\n	\n		\n			\n			課程名稱\n			\n			實用生活美語\n			\n			授課老師\n			\n			\n			李宜玲Elaine\n			\n		\n		\n			\n			課\n\n			程\n\n			大\n\n			綱\n			\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容 Connectivity  5\n			\n		\n		\n			\n			1\n			\n			\n			Unit 5 What’s funny?\n			\n			\n			Goals: Respond to humor / Explore the potential benefits of laughter\n			\n		\n		\n			\n			2\n			\n			\n			Unit 5 What’s funny?\n			\n			\n			Grammar: Questions in indirect speech\n			\n		\n		\n			\n			3\n			\n			\n			Unit 5 What’s funny?\n			\n			\n			Conversations:” Come see this” to invite someone to look at something you think he or she will find interesting\n			\n		\n		\n			\n			4\n			\n			\n			Unit 5 What’s funny?\n			\n			\n			Reading: An article about the health benefits of laughter\n			\n		\n		\n			\n			5\n			\n			\n			Unit 6 On the move\n			\n			\n			Goals: Describe how you deal with commuting / Talk about property lost\n			\n		\n		\n			\n			6\n			\n			\n			Unit 6 On the move\n			\n			\n			Grammar: The unreal conditional \n			\n		\n		\n			\n			7\n			\n			\n			Unit 6 On the move\n			\n			\n			Conversation strategies: Ask a stranger for help with “ I wonder if you could do me a favor?”\n			\n		\n		\n			\n			8\n			\n			\n			Unit 6 On the move\n			\n			\n			Reading: A travel hassles self-test\n			\n		\n		\n			\n			9\n			\n			\n			Unit 7 \n\n			Belief and reality\n			\n			\n			Goals: Describe a scam / fears and phobias\n			\n		\n		\n			\n			10\n			\n			\n			Unit 7 \n\n			Belief and reality\n			\n			\n			Grammar: Reporting beliefs: \n\n			It + a passive reporting verb\n			\n		\n		\n			\n			11\n			\n			\n			Unit 7 \n\n			Belief and reality\n			\n			\n			Conversation:\n\n			“Why am I not surprised?” / “Don’t tell me…” \n			\n		\n		\n			\n			12 \n			\n			\n			Unit 7 \n\n			Belief and reality\n			\n			\n			Reading: A fact sheet about scams\n			\n		\n		\n			\n			13\n			\n			\n			Unit 8\n\n			Achievement and Intelligence\n			\n			\n			Goals: Identify your unique strengths\n			\n		\n		\n			\n			14\n			\n			\n			Unit 8\n\n			Achievement and Intelligence\n			\n			\n			Grammar: Using “do” for emphatic stress \n			\n		\n		\n			\n			15\n			\n			\n			Unit 8\n\n			Achievement and Intelligence\n			\n			\n			Conversations: “So I understand (that)… / Would you say you …?” to encourage someone to express a point of view\n			\n		\n	\n\n\n \n\n \n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-05-16 00:00:00', `end_date`='2025-08-29 00:00:00', `location`='W312教室', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='2000', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50643', `image_url`='[]';
