INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bee26b3240c403d97d6', '生活中的皮雕藝術A', '    \n\n       5/31停課\n\n自備：\n\n雕刻基本工具、打洞、手縫針等縫合工具、銀筆(記號筆)、著色筆、皮剪、描圖鐵筆、描圖紙、美工刀、尺、小白膠、強力膠、雙面膠。  \n\n  材料費約3000元 。\n\n     \n\n\n	\n		\n			\n			課程名稱\n			\n			\n			生活中的皮雕藝術A、B班\n			\n			\n			授課老師：葉沛玲\n			\n		\n		\n			\n			 \n\n			 \n\n			課\n\n			程\n\n			大\n\n			綱\n\n			 \n			\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			水桶包\n			\n			\n			圖案規畫與\n\n			圖案立體處理\n			\n		\n		\n			\n			2\n			\n			\n			圖案細致處理\n			\n		\n		\n			\n			3\n			\n			\n			圖案雕刻\n			\n		\n		\n			\n			4\n			\n			\n			皮革粘合及細工修飾製作\n			\n		\n		\n			\n			5\n			\n			\n			皮革與五金組合作品完成\n			\n		\n		\n			\n			6\n			\n			\n			轉印與皮革袋物應用\n			\n			\n			設計圖稿與描繪\n			\n		\n		\n			\n			7\n			\n			\n			電燒圖案立體雕刻處理\n			\n		\n		\n			\n			8\n			\n			\n			電燒圖案著色及袋物組合\n			\n		\n		\n			\n			9\n			\n			\n			袋物組合\n			\n		\n		\n			\n			10\n			\n			\n			袋物組合及組裝五金作品完成\n			\n		\n		\n			\n			11\n			\n			\n			 \n\n			 \n\n			 \n\n			 \n\n			拼貼、雕刻與作品綜合應用\n			\n			\n			圖案設計、繪製及描圖\n			\n		\n		\n			\n			12\n			\n			\n			圖案立體雕刻、彩繪處理\n			\n		\n		\n			\n			13\n			\n			\n			本體打洞縫合\n			\n		\n		\n			\n			14\n			\n			\n			本體口袋及提把製作\n			\n		\n		\n			\n			15\n			\n			\n			本體縫合與組裝五金，作品完成\n			\n		\n	\n\n\n                                              \n\n\n	\n		\n			 \n			 \n			 \n			 \n			 \n		\n	\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-17 00:00:00', '2025-08-30 00:00:00', 'W315教室', 25.0367564, 121.519047, '3000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50648', '[]') ON DUPLICATE KEY UPDATE `activity_name`='生活中的皮雕藝術A', `description`='    \n\n       5/31停課\n\n自備：\n\n雕刻基本工具、打洞、手縫針等縫合工具、銀筆(記號筆)、著色筆、皮剪、描圖鐵筆、描圖紙、美工刀、尺、小白膠、強力膠、雙面膠。  \n\n  材料費約3000元 。\n\n     \n\n\n	\n		\n			\n			課程名稱\n			\n			\n			生活中的皮雕藝術A、B班\n			\n			\n			授課老