INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bf026b3240c403d97ee', '紫微星座分析', '★本報名費不含教材費。\n\n課程內容：導讀《紫微斗數全書》、《神相全編》，紫微斗數的源起與流派介紹、安五行局、十二宮稱、諸星、諸神煞、諸星問答論及太微賦、骨髓賦等重要論賦詳解等。 \n\n     114-2 課程大綱\n\n\n	\n		\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			第1週\n			\n			\n			紫微星座分析\n			\n			\n			紫微斗數的源起與流派介紹\n			\n		\n		\n			\n			第2週\n			\n			\n			紫微星座分析\n			\n			\n			安五行局 十二宮稱\n			\n		\n		\n			\n			第3週\n			\n			\n			紫微星座分析\n			\n			\n			諸星 諸神煞(排盤神仙口訣法\n			\n		\n		\n			\n			第4週\n			\n			\n			紫微星座分析\n			\n			\n			諸星問答論及太微賦 骨髓賦等\n\n			重要論賦詳解\n			\n		\n		\n			\n			第5週\n			\n			\n			紫微星座分析\n			\n			\n			主星與相貌 體型的實例講述\n			\n		\n		\n			\n			第6週\n			\n			\n			紫微星座分析\n			\n			\n			主星與相貌 體型的實例講述\n			\n		\n		\n			\n			第7週\n			\n			\n			紫微星座分析\n			\n			\n			主星與相貌 體型的實例講述\n			\n		\n		\n			\n			第8週\n			\n			\n			紫微星座分析\n			\n			\n			十二宮稱與諸星 諸神煞 互動關係的實例講述\n			\n		\n		\n			\n			第9週\n			\n			\n			紫微星座分析\n			\n			\n			十二宮稱與諸星 諸神煞 互動關係的實例講述\n			\n		\n		\n			\n			第10週\n			\n			\n			紫微星座分析\n			\n			\n			十二宮稱與諸星 諸神煞 互動關係的實例講述\n			\n		\n		\n			\n			第11週\n			\n			\n			紫微星座分析\n			\n			\n			十二宮稱與諸星 諸神煞 互動關係的實例講述\n			\n		\n		\n			\n			第12週\n			\n			\n			紫微星座分析\n			\n			\n			如何論財 官 情 疾厄 壽及流年命運的吉凶悔吝\n			\n		\n		\n			\n			第13週\n			\n			\n			紫微星座分析\n			\n			\n			何論財 官 情 疾厄 壽及流年命運的吉凶悔吝\n			\n		\n		\n			\n			第14週\n			\n			\n			紫微星座分析\n			\n			\n			何論財 官 情 疾厄 壽及流年命運的吉凶悔吝\n			\n		\n		\n			\n			第15週\n			\n			\n			紫微星座分析\n			\n			\n			如何增進「財氣」並「生財有道」\n			\n		\n	\n\n\n \n\n P.S：課程內容視實際授課狀況做適度調整。   ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-12 00:00:00', '2025-08-18 00:00:00', 'W311教室', 25.0367564, 121.519047, '2000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50534', '[]') ON DUPLICATE KEY UPDATE `activity_name`='紫微星座分析', `description`='★本報名費不含教材費。\n\n課程內容：導讀《紫微斗數全書》、《神相全編》，紫微斗數的源起與流派介紹、安五行