INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bf026b3240c403d97ef', '意象速寫-啟發繪畫思維A', '★請自備4B素描筆、軟橡皮、A4紙\n\n★本表所安排之課題及教學內容將依據學員程度及學習狀況斟酌調整。\n\n\n	\n		\n			\n			課程名稱\n			\n			\n			意象速寫-啟發繪畫思維A\n			\n			\n			授課老師\n			\n			\n			王  弈\n			\n		\n		\n			\n			課\n\n			程\n\n			大\n\n			綱\n			\n			\n			次序\n			\n			\n			課程主題\n			\n			\n			教學內容\n			\n		\n		\n			\n			1\n			\n			\n			速寫與素描不同嗎？\n			\n			\n			速寫重意輕形是素描洗鍊後的表現。\n			\n		\n		\n			\n			2\n			\n			\n			速寫有基本筆法嗎？\n			\n			\n			輕重疏密鈍鋭長短是八種基本筆法。\n			\n		\n		\n			\n			3\n			\n			\n			畫出來的線太拘謹！\n			\n			\n			改變力距的握筆方式或讓左手試試。\n			\n		\n		\n			\n			4\n			\n			\n			速寫能表現漸層嗎？\n			\n			\n			線狀速寫的層次可通過疏密來呈現。\n			\n		\n		\n			\n			5\n			\n			\n			速度太快很難對位！\n			\n			\n			點位確定性高於連結兩點之間的線。\n			\n		\n		\n			\n			6\n			\n			\n			所謂探線如何操作？\n			\n			\n			探線具有模擬背景環境符號的特性。\n			\n		\n		\n			\n			7\n			\n			\n			如何迅速掌握畫面？\n			\n			\n			餘光練習能引發直覺式的對位觀察。\n			\n		\n		\n			\n			8\n			\n			\n			如果畫錯了怎麼辦？\n			\n			\n			複線的運用可以提升速寫的容錯性。\n			\n		\n		\n			\n			9\n			\n			\n			不小心線就畫太多！\n			\n			\n			嘗試在極短的時間內完成畫作內容。\n			\n		\n		\n			\n			10\n			\n			\n			有些筆觸不敢表現！\n			\n			\n			閉眼去畫憑直覺可練出下筆決斷力。\n			\n		\n		\n			\n			11\n			\n			\n			如何掌握關鍵細節？\n			\n			\n			去畫陌生人，就來不及看太多細節。\n			\n		\n		\n			\n			12\n			\n			\n			如何表現隨機線流？\n			\n			\n			筆尖不離畫紙，連筆完成所有畫面。\n			\n		\n		\n			\n			13\n			\n			\n			沒有水彩也能上色？\n			\n			\n			溶水筆、耐水筆與一罐噴瓶的搭配。\n			\n		\n		\n			\n			14\n			\n			\n			線條如何表現立體？\n			\n			\n			曲直線流疏密的堆疊能產生立體感。\n			\n		\n		\n			\n			15\n			\n			\n			彩墨方式也能速寫？\n			\n			\n			速寫求意境，不受任何媒材的限制。\n			\n		\n	\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-12 00:00:00', '2025-08-18 00:00:00', 'W320教室', 25.0367564, 121.519047, '4500', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50535', '[]') ON DUPLICATE KEY UPDATE `activity_name`='意象速寫-啟發繪畫思維A', `description`='★請自備4B素描筆、軟橡皮、A4紙\