INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bf026b3240c403d97f3', '數位攝影-中級班', '★本課程教學以單眼相機為主       8/12-8/13為二天二夜戶外課\n\n★每堂外拍實習課皆須辦理保險(報名費內含保險費)。\n\n★外拍實習課程依照攝影主題，可能因為天候、季節、特殊節慶活動等因素而作調整。\n\n★本課程於5/13辦理戶外教學保險事宜。若學員辦理退費，5/13 (含)前保險費全額退還，5/14 (含)之後由所繳交之費用扣除保險費後，再依退費規定辦理。\n\n\n	\n		\n			\n			次序\n			\n			\n			日期\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n			\n			講座\n			\n		\n		\n			\n			1\n			\n			\n			05/14\n			\n			\n			看見影像的意涵與語境—尋找創意的新思維。\n			\n			\n			劉燕南\n			\n		\n		\n			\n			2\n			\n			\n			05/21\n			\n			\n			戶外教學實習(一): 老梅火山熔岩－落日餘暉【慢速、重複曝光、追焦】。\n			\n			\n			劉燕南\n			\n		\n		\n			\n			3\n			\n			\n			05/28\n			\n			\n			沉寂、靜謐的夜間創作技巧與如何補光、測光、曝光。\n			\n			\n			郭炳東\n			\n		\n		\n			\n			4\n			\n			\n			06/04\n			\n			\n			戶外教學實習(二): 北海岸日出色溫與造形的詮釋。【龜吼】。\n			\n			\n			劉燕南\n			\n		\n		\n			\n			5\n			\n			\n			06/11\n			\n			\n			用相機探索世界【風景攝影】－風景攝影拍攝的技巧表現 \n			\n			\n			劉燕南\n			\n		\n		\n			\n			6\n			\n			\n			06/18\n			\n			\n			攝影眼的培養－作品獨特風格的關鍵思維。\n			\n			\n			郭炳東\n			\n		\n		\n			\n			7\n			\n			\n			06/25\n			\n			\n			戶外教學實習(三): 二格道 小格頭 雲海拍攝秘笈。\n			\n			\n			郭炳東\n			\n		\n		\n			\n			8\n			\n			\n			07/02\n			\n			\n			溪石‧海石拍攝的技巧表現。\n			\n			\n			郭炳東\n			\n		\n		\n			\n			9\n			\n			\n			07/09\n			\n			\n			戶外教學實習(四): 南方澳漁港日出‧漁港風情畫 。\n			\n			\n			郭炳東\n			\n		\n		\n			\n			10\n			\n			\n			07/16\n			\n			\n			攝影技巧的表現－線條、色調、造型。\n			\n			\n			應文進\n			\n		\n		\n			\n			11\n			\n			\n			07/23\n			\n			\n			似抽象如幻象－魚眼鏡頭的應用－改變不同的視角有全新的感受。\n			\n			\n			應文進\n			\n		\n		\n			\n			12\n			\n			\n			07/30\n			\n			\n			晨昏風景攝影之解析－高山-山巒、雲海、晨曦、夕陽之美    \n			\n			\n			應文進\n			\n		\n		\n			\n			13\n			\n			\n			08/12\n			\n			\n			戶外教學實習(五):花東攝影深度之旅－金針花開季節。二天二夜  \n\n			環島之星彩繪列車－搭配金黃色稻穗。六十石山‧【夕陽】赤柯山汪家古厝。小天祥部落【金黃色稻穗】－石梯坪【火山熔岩】。\n\n			拍攝景點:視天候或不可預知狀況調整 。\n			\n			\n			應文進\n			\n		\n		\n			\n			14\n			\n			\n			08/13\n			\n			\n			戶外教學實習(六): 金崙溪日出搭配撈魚苗。或三仙台曝星軌‧日出。地中海風－豊原国小。小野柳、玉長隧道拍雲海－全台最美東海岸景觀烏石鼻-卡片教堂。\n			\n			\n			應文進\n			\n		\n		\n			\n			15\n			\n			\n			08/20\n			\n			\n			結業式-綜合複習－作品檢討-作品成果評介、賞析。\n			\n			\n			劉燕南\n			\n		\n	\n\n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-14 00:00:00', '2025-08-20 00:00:00', 'W318教室', 25.0367564, 121.519047, '2174', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50539', '[]') ON DUPLICATE KEY UPDATE `activity_name`='數位攝影-中級班', `description`='★本課程教學以單眼相機為主       8/12-8/13為二天二夜戶外課\n\n★每堂外拍實習課皆須辦理保險(報名費內含保險費)。\n\n★外拍實習課程依照攝影主題，可能因為天候、季節、特殊節慶活動等因素而作調整。\n\n★本課程於5/13辦理戶外教學保險事宜。若學員辦理退費，5/13 (含)前保險費全額退還，5/14 (含)之後由所繳交之費用扣除保險費後，再依退費規定辦理。\n\n\n	\n		\n			\n			次序\n			\n			\n			日期\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n			\n			講座\n			\n		\n		\n			\n			1\n			\n			\n			05/14\n			\n			\n			看見影像的意涵與語境—尋找創意的新思維。\n			\n			\n			劉燕南\n			\n		\n		\n			\n			2\n			\n			\n			05/21\n			\n			\n			戶外教學實習(一): 老梅火山熔岩－落日餘暉【慢速、重複曝光、追焦】。\n			\n			\n			劉燕南\n			\n		\n		\n			\n			3\n			\n			\n			05/28\n			\n			\n			沉寂、靜謐的夜間創作技巧與如何補光、測光、曝光。\n			\n			\n			郭炳東\n			\n		\n		\n			\n			4\n			\n			\n			06/04\n			\n			\n			戶外教學實習(二): 北海岸日出色溫與造形的詮釋。【龜吼】。\n			\n			\n			劉燕南\n			\n		\n		\n			\n			5\n			\n			\n			06/11\n			\n			\n			用相機探索世界【風景攝影】－風景攝影拍攝的技巧表現 \n			\n			\n			劉燕南\n			\n		\n		\n			\n			6\n			\n			\n			06/18\n			\n			\n			攝影眼的培養－作品獨特風格的關鍵思維。\n			\n			\n			郭炳東\n			\n		\n		\n			\n			7\n			\n			\n			06/25\n			\n			\n			戶外教學實習(三): 二格道 小格頭 雲海拍攝秘笈。\n			\n			\n			郭炳東\n			\n		\n		\n			\n			8\n			\n			\n			07/02\n			\n			\n			溪石‧海石拍攝的技巧表現。\n			\n			\n			郭炳東\n			\n		\n		\n			\n			9\n			\n			\n			07/09\n			\n			\n			戶外教學實習(四): 南方澳漁港日出‧漁港風情畫 。\n			\n			\n			郭炳東\n			\n		\n		\n			\n			10\n			\n			\n			07/16\n			\n			\n			攝影技巧的表現－線條、色調、造型。\n			\n			\n			應文進\n			\n		\n		\n			\n			11\n			\n			\n			07/23\n			\n			\n			似抽象如幻象－魚眼鏡頭的應用－改變不同的視角有全新的感受。\n			\n			\n			應文進\n			\n		\n		\n			\n			12\n			\n			\n			07/30\n			\n			\n			晨昏風景攝影之解析－高山-山巒、雲海、晨