INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bf026b3240c403d97fa', '優雅生活 - 古典美人舞(A)', ' \n\n\n	\n		\n			\n			週次\n			\n			\n			課程主題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			古典舞蹈\n			\n			\n			\n				介紹本期古典舞碼之起源及其相關文化。\n				暖身動作、舞蹈身段練習、舞蹈基本動作練習。\n			\n			\n		\n		\n			\n			2\n			\n			\n			古典舞蹈\n			\n			\n			\n				暖身動作、古典舞身段練習。\n				古典舞蹈基本動作練習。\n			\n			\n		\n		\n			\n			3\n			\n			\n			古典舞蹈\n			\n			\n			\n				暖身動作、古典舞身段練習。\n				古典舞蹈基本動作練習。\n			\n			\n		\n		\n			\n			4\n			\n			\n			古典舞蹈\n			\n			\n			\n				暖身動作、古典舞身段練習。\n				古典舞蹈基本動作練習。\n			\n			\n		\n		\n			\n			5\n			\n			\n			古典舞蹈\n			\n			\n			\n				暖身+基本動作練習+古典舞身段練習(美學培養)。\n				舞曲練習+瑜珈伸展 (增進體能)。\n			\n			\n		\n		\n			\n			6\n			\n			\n			古典舞蹈\n			\n			\n			\n				暖身+基本動作練習+古典舞身段練習(美學培養)。\n				舞曲練習+瑜珈伸展 (增進體能)。\n			\n			\n		\n		\n			\n			7\n			\n			\n			古典舞蹈\n			\n			\n			\n				暖身+基本動作練習+古典舞身段練習(美學培養)。\n				舞曲練習+瑜珈伸展 (增進體能)。\n			\n			\n		\n		\n			\n			8\n			\n			\n			古典舞蹈\n			\n			\n			\n				暖身+基本動作練習+古典舞身段練習(美學培養)。\n				舞曲練習+瑜珈伸展 (增進體能)。\n			\n			\n		\n		\n			\n			9\n			\n			\n			古典舞蹈\n			\n			\n			\n				暖身+基本動作練習+古典舞身段練習(美學培養)。\n				舞曲練習+瑜珈伸展 (增進體能)。\n			\n			\n		\n		\n			\n			10\n			\n			\n			創意民俗舞蹈\n			\n			\n			\n				介紹本舞碼之民俗文化與歷史。\n				暖身動作、民俗舞蹈身段練習、民俗舞蹈基本動作練習。\n			\n			\n		\n		\n			\n			11\n			\n			\n			創意民俗舞蹈\n			\n			\n			\n				暖身動作、民俗舞身段練習。\n				民俗舞蹈基本動作練習。\n			\n			\n		\n		\n			\n			12\n			\n			\n			創意民俗舞蹈\n			\n			\n			\n				暖身動作、民俗舞身段練習。\n				民俗舞蹈基本動作練習。\n			\n			\n		\n		\n			     13\n			\n			創意民俗舞蹈\n			\n			\n			\n				暖身+基本動作練習+民俗舞身段練習(美學培養)。\n				舞曲練習+瑜珈伸展 (增進體能)。\n			\n			\n		\n		\n			     14\n			\n			創意民俗舞蹈\n			\n			\n			\n				本期古風舞蹈與創意民俗舞蹈複習。\n				舞蹈文化 : 舞蹈表演的基本禮儀。\n			\n			\n		\n		\n			\n			15\n			\n			\n			本期總複習\n			\n			\n			      1.本期教授舞碼總複習。\n\n			      2.學習心得分享。\n			\n		\n	\n\n\n \n\n \n\n \n\n ', '國立中正紀念堂管理