INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bf026b3240c403d97fc', '拼布雜貨舖', '★材料費：第一堂課500元以內，第二堂課起請自備材料。\n\n\n	\n		\n			\n			課程名稱：拼布雜貨舖\n			\n			\n			授課老師： 陳美玲\n			\n		\n		\n			\n			次序\n			\n			\n			課程主題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			彈簧眼鏡袋\n\n			(三堂課)\n			\n			\n			一.裁布,貼布.\n			\n		\n		\n			\n			2\n			\n			\n			二.袋上部份縫合.\n			\n		\n		\n			\n			3\n			\n			\n			三.組合.\n			\n		\n		\n			\n			4\n			\n			\n			珠繡胸針\n\n			(三堂課)\n			\n			\n			一.打底,備圖.\n			\n		\n		\n			\n			5\n			\n			\n			二.珠繡針法.\n			\n		\n		\n			\n			6\n			\n			\n			三.背面整理,縫別針.\n			\n		\n		\n			\n			7\n			\n			\n			玩偶\n\n			(四堂課)\n			\n			\n			一.玩偶裁布,配件裁布.\n			\n		\n		\n			\n			8\n			\n			\n			二.分開製作,縫合.\n			\n		\n		\n			\n			9\n			\n			\n			三.塞棉技法.\n			\n		\n		\n			\n			10\n			\n			\n			四.表情.\n			\n		\n		\n			\n			11\n			\n			\n			圓形貼布包\n\n			(五堂課)\n			\n			\n			一.前後片壓線,底壓線.\n			\n		\n		\n			\n			12\n			\n			\n			  二.拉鍊與側邊布料接合.\n			\n		\n		\n			\n			13\n			\n			\n			三.貼布.\n			\n		\n		\n			\n			14\n			\n			\n			四.帶子縫製.\n			\n		\n		\n			\n			15\n			\n			\n			五.組合.', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-13 00:00:00', '2025-08-19 00:00:00', 'W313教室', 25.0367564, 121.519047, '3000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50548', '[]') ON DUPLICATE KEY UPDATE `activity_name`='拼布雜貨舖', `description`='★材料費：第一堂課500元以內，第二堂課起請自備材料。\n\n\n	\n		\n			\n			課程名稱：拼布雜貨舖\n			\n			\n			授課老師： 陳美玲\n			\n		\n		\n			\n			次序\n			\n			\n			課程主題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			彈簧眼鏡袋\n\n			(三堂課)\n			\n			\n			一.裁布,貼布.\n			\n		\n		\n			\n			2\n			\n			\n			二.袋上部份縫合.\n			\n		\n		\n			\n			3\n			\n			\n			三.組合.\n			\n		\n		\n			\n			4\n			\n			\n			珠繡胸針\n\n			(三堂課)\n			\n			\n			一.打底,備圖.\n			\n		\n		\n			\n			5\n			\n			\n			二.珠繡針法.\n			\n		\n		\n			\n			6\n			\n			\n			三.背面整理,縫別針.