INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bf026b3240c403d97fe', '革命 ·英雄·歷史：藝術大師賞析', '課程內容： 不喜前朝風花雪月的「洛可可」奢華文化藝術，一代英雄拿破崙卻獨厚古代羅馬文化體制，熱衷史詩般可歌可泣的革命英雄歷史典故，偏愛傳統莊嚴的「古典藝術」風格，及稱頌璀燦亮麗的史蹟。因此，為了紀錄拿破崙英雄般的豐功偉業，進而豎立起「新古典主義」的旗幟 ，並造就藝術學院的興起，以嚴謹古典形式建立教學方式，成為百年來全世界藝術學校「學院式」的藝術教育。我們將透過藝術大師的精彩名畫，一同欣賞拿破崙時代「新古典主義」革命、英雄與歷史的篇章。\n\n\n114-2課程大綱 \n\n\n	\n		\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			第1週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			美麗與哀愁－德拉羅什\n\n			（1797-1859）\n			\n		\n		\n			\n			第2週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			偉大的歷史畫－傑洛姆\n\n			（1824-1904）\n			\n		\n		\n			\n			第3週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			藝術冠冕－羅馬大獎\n			\n		\n		\n			\n			第4週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			鯉魚躍龍門－沙龍展\n			\n		\n		\n			\n			第5週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			新故典的象徵－普呂東\n\n			（1758-1823）\n			\n		\n		\n			\n			第6週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			拿破崙的宮廷畫家－熱拉爾\n\n			（1770-1837）\n			\n		\n		\n			\n			第7週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			帝國的品味－葛耶蘭\n\n			（1774-1833）\n			\n		\n		\n			\n			第8週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			古典生活東方風情－夏瑟里奧\n\n			（1819-1856）\n			\n		\n		\n			\n			第9週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			法國繪畫的傳統－布格羅\n\n			（1825-1905）\n			\n		\n		\n			\n			第10週\n			\n			\n			革命 · 歷史 · 英雄 ：\n\n			 藝術大師賞析\n			\n			\n			東方的後花園－貝利\n\n			（1827-1877）\n			\n		\n		\n			\n			第11週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			沙龍展第一名－卡巴內爾\n\n			（1823-1889）\n			\n		\n		\n			\n			第12週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			古典情懷－方丹 · 拉突爾\n\n			（1836-1904）\n			\n		\n		\n			\n			第13週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			​​​​​​​ 藝術大師賞析\n			\n			\n			古典與現實－卡里葉\n\n			（1849-1906）\n			\n		\n		\n			\n			第14週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			​​​​​​​ 藝術大師賞析\n			\n			\n			徐悲鴻的老師－達仰\n\n			（1852-1929）\n			\n		\n		\n			\n			第15週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			​​​​​​​ 藝術大師賞析\n			\n			\n			一個荷蘭人在法國－阿里 · 謝弗\n\n			（1795－1858）\n			\n		\n	\n\n \n\nPS:課程內容視實際授課狀況做適度調整。   \n\n※本課程教室為階梯型教室​​​​​​​​​​​​​​', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-12 00:00:00', '2025-08-18 00:00:00', 'W318教室', 25.0367564, 121.519047, '2000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50550', '[]') ON DUPLICATE KEY UPDATE `activity_name`='革命 ·英雄·歷史：藝術大師賞析', `description`='課程內容： 不喜前朝風花雪月的「洛可可」奢華文化藝術，一代英雄拿破崙卻獨厚古代羅馬文化體制，熱衷史詩般可歌可泣的革命英雄歷史典故，偏愛傳統莊嚴的「古典藝術」風格，及稱頌璀燦亮麗的史蹟。因此，為了紀錄拿破崙英雄般的豐功偉業，進而豎立起「新古典主義」的旗幟 ，並造就藝術學院的興起，以嚴謹古典形式建立教學方式，成為百年來全世界藝術學校「學院式」的藝術教育。我們將透過藝術大師的精彩名畫，一同欣賞拿破崙時代「新古典主義」革命、英雄與歷史的篇章。\n\n\n114-2課程大綱 \n\n\n	\n		\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			第1週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			美麗與哀愁－德拉羅什\n\n			（1797-1859）\n			\n		\n		\n			\n			第2週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			偉大的歷史畫－傑洛姆\n\n			（1824-1904）\n			\n		\n		\n			\n			第3週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			藝術冠冕－羅馬大獎\n			\n		\n		\n			\n			第4週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			鯉魚躍龍門－沙龍展\n			\n		\n		\n			\n			第5週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			新故典的象徵－普呂東\n\n			（1758-1823）\n			\n		\n		\n			\n			第6週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			拿破崙的宮廷畫家－熱拉爾\n\n			（1770-1837）\n			\n		\n		\n			\n			第7週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			帝國的品味－葛耶蘭\n\n			（1774-1833）\n			\n		\n		\n			\n			第8週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			古典生活東方風情－夏瑟里奧\n\n			（1819-1856）\n			\n		\n		\n			\n			第9週\n			\n			\n			革命 · 歷史 · 英雄 ：\n			 藝術大師賞析\n			\n			\n			法國繪畫的傳統－布格羅\n\n			（1825-1905）\n			\n		\n		\n			\n			第10週\n			\n			\n			革命 · 歷史 · 英雄 ：\n\n			 藝術大師賞析\n			\n			\n			東方的後花園－貝利\n\n			（1827-1877）\n			\n		\n		\n			\n			第11週\n			\n			\n			革命 · 歷史 · 英雄 ：\n	