INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bf126b3240c403d9804', '樂齡體適能(進階)', '★請學員自備有厚度的止滑襪於上課時換穿及彈力帶約150公分\n\n將針對中高齡者體適能狀況設計課程內容，並根據實際能力調整循序漸進的調整強度。每堂課將利用簡單輕便、日常生活易取得的物品當器材，進行安全且有效運動課程，以達到健康促進及延緩失能的目標。\n\n\n\n	\n		\n			\n			週次\n			\n			\n			內容及進度\n			\n		\n		\n			\n			第1週\n			\n			\n			核心逆齡（肌力+爆發）\n\n			介紹核心肌群的重要性，如何加強與訓練。\n			\n		\n		\n			\n			第2週\n			\n			\n			肌力大效（肌力+協調）\n			複習核心肌群，並加強上肢與下肢肌群。\n			\n		\n		\n			\n			第3週\n			\n			\n			幫助燃脂精神好（心肺+協調）\n\n			跟者節奏超慢跑，說明快走，慢跑的差別，提高心肺能力。\n			\n		\n		\n			\n			第4週\n			\n			\n			沁人心肺（肌力+協調）\n\n			加強肌力和綜合動作。\n			\n		\n		\n			\n			第5週\n			\n			\n			銀光舞會（心肺+協調）\n			跟著有節奏的舞曲，帶者學生們歡樂共舞。\n			\n		\n		\n			\n			第6週\n			\n			\n			如虎添震（敏捷+爆發力）\n\n			如何正確地爬樓梯（視天候調整）。\n			\n		\n		\n			\n			第7週\n			\n			\n			四平八穩（爆發力+平衡）\n			平衡訓練並加上跆拳道運動的元素。\n			\n		\n		\n			\n			第8週\n			\n			\n			心肌相印（心肺+認知）\n\n			搭配歌曲，邊唱邊跳，享受音樂沉靜在舞蹈中。\n			\n		\n		\n			\n			第9週\n			\n			\n			舒壓美體（柔軟度+肌力）\n			透過瑜伽的引導進入體位法，有肌力同時也要有柔軟度。\n			\n		\n		\n			\n			第10週\n			\n			\n			刻機刻骨（肌力+敏捷）\n\n			搭配器材做肌力訓練。\n			\n		\n		\n			\n			第11週\n			\n			\n			百煉成鋼（肌力+平衡）\n			複習上週的肌力動作，並加上平衡的練習\n			\n		\n		\n			\n			第12週\n			\n			\n			太極武藝（肌力+認知）\n			融入肌力訓練與認知元素並分組互相教學以得知是否有正確的觀念與知識。\n			\n		\n		\n			\n			第13週\n			\n			\n			舞態生風（心肺+協調）\n\n			跟隨有節奏的舞曲，享受音樂並融入其中。\n			\n		\n		\n			\n			第14週\n			\n			\n			鼓樂喧天（全面性體適能）\n			\n		\n		\n			      第15週\n			盛況空前（全面性體適能）', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-13 00:00:00', '2025-08-19 00:00:00', 'W319教室', 25.0367564, 121.519047, '3000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50556', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樂齡體適能(進階)', `description`='★請學員自備有厚度的止滑襪於上課時換穿及彈力帶約150公分\n\n將針對中高齡者體適能狀況設計課程內容，並根據實際能力調整循序漸進的調整強度。每堂課將利用簡單輕便、日常生活易取得的物品當器材，進行安全且有效運動課程，以達到健康促進及延緩失能的目標。\n\n\n\n	\n		\n			\n			週次\n			\n			\n			內容及進度\n			\n		\n		\n			\n			第1週\