INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bf126b3240c403d9805', '篆刻藝術', '5/30停課\n\n★本表所安排之課題及教學內容將依據學員程度及學習狀況斟酌調整。\n\n\n\n	\n		\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			工具介紹\n			\n			\n			篆刻操作的各種工具、材料及刻製示範和練習\n			\n		\n		\n			\n			2\n			\n			\n			漢印介紹\n			\n			\n			漢印的各種形態的章法和刀法解析\n			\n		\n		\n			\n			3\n			\n			\n			漢印練習\n			\n			\n			漢印設計安排和刻製練習\n			\n		\n		\n			\n			4\n			\n			\n			秦印界格印的介紹\n			\n			\n			秦印界格印形態、章法和刀法解析\n			\n		\n		\n			\n			5\n			\n			\n			秦印界格印練習\n			\n			\n			秦印界格印的設計安排和刻製練習\n			\n		\n		\n			\n			6\n			\n			\n			兩周璽印的介紹\n			\n			\n			古鉥印形態、章法和刀法解析\n			\n		\n		\n			\n			7\n			\n			\n			鉥印製作練習\n			\n			\n			古鉥印設計安排和刻製練習(寬邊細字小朱鉥印)\n			\n		\n		\n			\n			8\n			\n			\n			鉥印製作練習\n			\n			\n			古鉥印設計安排和刻製練習(2.4公分以上鉥印)\n			\n		\n		\n			\n			9\n			\n			\n			文人印章介紹之一\n\n			文彭何震\n			\n			\n			作品章法和刀法介紹\n			\n		\n		\n			\n			10\n			\n			\n			文人印章介紹之二\n\n			黃易\n			\n			\n			作品章法和刀法介紹\n			\n		\n		\n			\n			11\n			\n			\n			浙派章法刀法製作練習\n			\n			\n			作品章法和刀法刻製練習\n			\n		\n		\n			\n			12\n			\n			\n			文人印章介紹之二\n\n			鄧石如\n			\n			\n			作品章法和刀法介紹\n			\n		\n		\n			\n			13\n			\n			\n			皖派製作練習\n			\n			\n			作品章法和刀法刻製練習\n			\n		\n		\n			\n			14\n			\n			\n			文人印章介紹之三\n\n			吳昌碩\n			\n			\n			作品章法和刀法介紹\n			\n		\n		\n			\n			15\n			\n			\n			文人印章介紹之四\n\n			王壯為\n			\n			\n			作品章法和刀法刻製練習\n			\n		\n	\n\n\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-05-16 00:00:00', '2025-08-29 00:00:00', 'W315教室', 25.0367564, 121.519047, '2000', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50557', '[]') ON DUPLICATE KEY UPDATE `activity_name`='篆刻藝術', `description`='5/30停課\n\n★本表所安排之課題及教學內容將依據學員程度及學習狀況斟酌調整。\n\n\n\n	\n		\n			\n			次序\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n		\n		\n			\n			1\n			\n			\n			工具介紹\n			\n			\n			篆刻操作的各種工具、材料及