INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67b80bf326b3240c403d9834', '手機攝影快樂拍', '本課程教學適合一般民眾與攝影初學者\n\n★每堂外拍實習課皆須辦理保險(報名費內含保險費)。\n\n★外拍實習課程依照攝影主題，可能因為天候、季節、特殊節慶活動等因素而作調整。\n\n★本課程於5/11辦理戶外教學保險事宜。若學員辦理退費，5/11（含）前保險費全額退還，5/12（含）之後由所繳交之費用扣除保險費後，再依退費規定辦理。\n\n\n	\n		\n			\n			次序\n			\n			\n			日期\n			\n			\n			課 程 主 題\n			\n			\n			教  學  內  容\n			\n			\n			講 師\n			\n		\n		\n			\n			01\n			\n			\n			05/12\n			\n			\n			手機影片素材生成想法。\n			\n			\n			手機影片紀錄時面對各種場景的運用。\n			\n			\n			陳志勇\n			\n		\n		\n			\n			02\n			\n			\n			05/19\n			\n			\n			戶外實習(一)圓山\n			\n			\n			現代建築型樣的視角。\n			\n			\n			陳志勇\n			\n		\n		\n			\n			03\n			\n			\n			05/26\n			\n			\n			影片特效在app的分割合集。\n			\n			\n			拍攝中素材經各綜合app效果剪輯組合\n			\n			\n			陳志勇\n			\n		\n		\n			\n			04\n			\n			\n			06/02\n			\n			\n			戶外實習(二)金華街\n			\n			\n			善用手機玩出-影‧音‧縮時‧照片。\n			\n			\n			陳志勇\n			\n		\n		\n			\n			05\n			\n			\n			06/09\n			\n			\n			Ai你-妳會了沒\n			\n			\n			手機ai-app的圖像生成。\n			\n			\n			陳志勇\n			\n		\n		\n			\n			06\n			\n			\n			06/16\n			\n			\n			美好的瞬間用手機即可補捉\n			\n			\n			運用攝影技巧，每張影像都可以是一個故事…。\n			\n			\n			劉燕南\n			\n		\n		\n			\n			07\n			\n			\n			06/23\n			\n			\n			戶外教學實習(三)東區-街拍\n			\n			\n			移動的風景-櫥窗的秘密\n			\n			\n			劉燕南\n			\n		\n		\n			\n			08\n			\n			\n			06/30\n			\n			\n			智慧型手機攝影輕鬆拍\n			\n			\n			手機修圖軟體設定與應用   \n			\n			\n			曾美莉\n			\n		\n		\n			\n			09\n			\n			\n			07/07\n			\n			\n			戶外教學實習(四)新板特區-光影、空間的結合。\n			\n			\n			手機攝影與影像創意編修   \n			\n			\n			曾美莉\n			\n		\n		\n			\n			10\n			\n			\n			07/14\n			\n			\n			愛瘋(I-PHONE)玩翻了\n			\n			\n			手機攝影使用小秘訣，配件選購和使用。\n			\n			\n			曾美莉\n			\n		\n		\n			\n			11\n			\n			\n			07/21\n			\n			\n			戶外教學實習(五)孔廟‧保安宮\n			\n			\n			景觀、人物、色彩色溫的表現。\n			\n			\n			曾美莉\n			\n		\n		\n			\n			12\n			\n			\n			07/28\n			\n			\n			手機攝影—彩色和黑白如何定位。\n			\n			\n			讓照片有不同樣貌呈現，黑白攝影就是一種值得嘗試的手法。\n			\n			\n			曾美莉\n			\n		\n		\n	