INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67bcf5e226b3240c403d9929', '蘭陽人銅管五重奏【「銅」來歡唱】（免費觀賞）', '💖演出團體介紹：\n\n蘭陽人銅管五重奏創團於2013年3月，於2017年3月正式立案為宜蘭在地演藝團體。秉持著以室內樂模式達到「社區即展廳」、｢文化紮根｣的目地將音樂的種子遍灑至宜蘭各個鄉鎮。\n\n🕒演出時間：114年6月15日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n音樂生活化！生活音樂化！藉由輕鬆有趣的音樂會，將音樂的種子深植在你我心中，此次「銅來歡唱」音樂會除了樂團演奏之外更邀請歌手一同與樂團合作，共同演出大家耳熟能詳的歌曲：\n● 小小世界\n● The Sound of The Music 真善美\n● SHE 新娘百分百\n● LOVE \n● Remember Me 可可夜總會 \n● 龍貓組曲 \n● 丟丟銅 \n● 淚光閃閃 \n● 愛人 \n● 我只在乎你\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', '國立中正紀念堂管理處', '100  臺北市中正區台北市中正區中山南路21號', '2025-06-15 00:00:00', '2025-06-15 00:00:00', '大孝門廣場', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50699', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蘭陽人銅管五重奏【「銅」來歡唱】（免費觀賞）', `description`='💖演出團體介紹：\n\n蘭陽人銅管五重奏創團於2013年3月，於2017年3月正式立案為宜蘭在地演藝團體。秉持著以室內樂模式達到「社區即展廳」、｢文化紮根｣的目地將音樂的種子遍灑至宜蘭各個鄉鎮。\n\n🕒演出時間：114年6月15日(日) 17:00-18:00\n\n🚩演出地點：大孝門廣場\n\n👀演出內容：\n\n音樂生活化！生活音樂化！藉由輕鬆有趣的音樂會，將音樂的種子深植在你我心中，此次「銅來歡唱」音樂會除了樂團演奏之外更邀請歌手一同與樂團合作，共同演出大家耳熟能詳的歌曲：\n● 小小世界\n● The Sound of The Music 真善美\n● SHE 新娘百分百\n● LOVE \n● Remember Me 可可夜總會 \n● 龍貓組曲 \n● 丟丟銅 \n● 淚光閃閃 \n● 愛人 \n● 我只在乎你\n✔活動方式：免費參加\n\n✔主辦單位：國立中正紀念堂管理處\n\n✔洽詢電話：推廣教育組陳小姐 02-23431100 轉 1125\n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區台北市中正區中山南路21號', `start_date`='2025-06-15 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='大孝門廣場', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50699', `image_url`='[]';
