INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dcdcba07f3d4433af95559', '《漫・游》官野良太 個展', '睽違兩年，涅普頓畫廊很榮幸再度邀請到日本藝術家- 官野良太來台舉辦全新個展「漫・游 TOUR」。官野良太1988年 生於日本神奈川，2013年畢業於東京藝術大學美術研究所。他持續透過「光之雕刻」的創作技法，與觀者分享光影與雕 塑互動的無限可能，引領進入一段關於光與雕塑的旅程。 展覽將於 2025 年 3 月 22 日(星期六)至 4 月 22 日(星期二)展出，我們誠摯邀請您親臨現場，感受光影交織的藝術魅力。 ', '涅普頓畫廊', '臺北市中山區堤頂大道二段340號', '2025-03-22 00:00:00', '2025-04-22 00:00:00', '涅普頓畫廊', 25.06969917, 121.5381597, '無資料', 'https://neptune-gallery.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《漫・游》官野良太 個展', `description`='睽違兩年，涅普頓畫廊很榮幸再度邀請到日本藝術家- 官野良太來台舉辦全新個展「漫・游 TOUR」。官野良太1988年 生於日本神奈川，2013年畢業於東京藝術大學美術研究所。他持續透過「光之雕刻」的創作技法，與觀者分享光影與雕 塑互動的無限可能，引領進入一段關於光與雕塑的旅程。 展覽將於 2025 年 3 月 22 日(星期六)至 4 月 22 日(星期二)展出，我們誠摯邀請您親臨現場，感受光影交織的藝術魅力。 ', `organizer`='涅普頓畫廊', `address`='臺北市中山區堤頂大道二段340號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-04-22 00:00:00', `location`='涅普頓畫廊', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='https://neptune-gallery.com/', `image_url`='[]';
