INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dd1ed08f15adefa04e0c86', '吾之萬象—宇化萬千    李哲儀個展', '我與累世累積存於佛教阿賴耶識以及淺意識無意識中的我，藉由與他們不段的溝通以及調閱，以及宇宙之大方向愛與人之關係作為探討。\r\n\r\n依照《薄伽梵歌》、《般若波羅蜜多心經》中所聞，以現代話語解釋，這個世界上是一場虛擬的世界，而以現代科學來說我們都是由弦理論（英語：String theory）弦與粒子構成，而這世界由陽光、空氣、水造就生命以及時代流動。因此在多視角之角度談同一件事時，會依不同維度出現，每一刻是幻象？還是過往就是幻象之過程？\r\n\r\n藝術家探討人與自我每一個面向之角度與心靈之感觸。將最柔情的心識留給自己的創作作品之中，以一種氣勢和意識型態表示千變萬化的創作。\r\n\r\n▍藝術家：李哲儀\r\n▍展覽日期：2025.4.19(六)-5.11(日)\r\n▍展覽地點：新浜碼頭藝術空間A、B展覽室\r\n▍展覽開幕：2025.4.27(日)13：30\r\n▍與談人：徐婉貞、蔡伊婷、李哲儀\r\n▍空間贊助單位：國藝會\r\n▍新浜行政：陳羚溱、吳宛倫\r\n▍實習生：孔媛、陳咨蓉\r\n\r\n', '新浜碼頭藝術空間', '高雄市鹽埕區大勇路64號2F', '2025-04-19 00:00:00', '2025-05-11 00:00:00', '新浜碼頭藝術空間', 22.62424585, 120.2842331, '無資料', 'https://sinpink.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='吾之萬象—宇化萬千    李哲儀個展', `description`='我與累世累積存於佛教阿賴耶識以及淺意識無意識中的我，藉由與他們不段的溝通以及調閱，以及宇宙之大方向愛與人之關係作為探討。\r\n\r\n依照《薄伽梵歌》、《般若波羅蜜多心經》中所聞，以現代話語解釋，這個世界上是一場虛擬的世界，而以現代科學來說我們都是由弦理論（英語：String theory）弦與粒子構成，而這世界由陽光、空氣、水造就生命以及時代流動。因此在多視角之角度談同一件事時，會依不同維度出現，每一刻是幻象？還是過往就是幻象之過程？\r\n\r\n藝術家探討人與自我每一個面向之角度與心靈之感觸。將最柔情的心識留給自己的創作作品之中，以一種氣勢和意識型態表示千變萬化的創作。\r\n\r\n▍藝術家：李哲儀\r\n▍展覽日期：2025.4.19(六)-5.11(日)\r\n▍展覽地點：新浜碼頭藝術空間A、B展覽室\r\n▍展覽開幕：2025.4.27(日)13：30\r\n▍與談人：徐婉貞、蔡伊婷、李哲儀\r\n▍空間贊助單位：國藝會\r\n▍新浜行政：陳羚溱、吳宛倫\r\n▍實習生：孔媛、陳咨蓉\r\n\r\n', `organizer`='新浜碼頭藝術空間', `address`='高雄市鹽埕區大勇路64號2F', `start_date`='2025-04-19 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='新浜碼頭藝術空間', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='無資料', `source_url`='https://sinpink.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dd2dbd07f3d4433af9555a', '「 老城故事 × 頌缽療癒｜來場文青系City Walk 」', '黎明新村，昔日省政府時期精心規劃的新市鎮，見證了台中南屯的發展軌跡。這裡鬧中取靜，街巷間彷彿藏著時光的低語，靜候每一位訪客來探索。\r\n\r\n這次，我們不只用雙腳走讀歷史，更將透過 頌缽體驗，讓身心沉浸於這片歲月靜好的秘境。當悠揚的缽音流轉於街巷之間，彷彿與舊時光產生共鳴，為這場城市散步增添一絲療癒與靜心的氛圍。\r\n\r\n走讀亮點\r\n探索黎明新村的歷史與人文——專業導覽帶你深入50年時光軌跡\r\n巷弄秘境探險——楓香步道、老宅風華，感受城市的另一面\r\n頌缽療癒體驗——在共鳴聲中沉澱心靈，感受寧靜的美好\r\n舌尖上的老時光——嚐一口招牌「跩姨蔥油餅」，感受地道風味\r\n限定旅行紀念——黎明新村專屬明信片＆郵資，帶走一份獨特記憶\r\n\r\n行程規劃\r\n13:00 - 13:30 干城194有機書店集合\r\n13:30 - 16:00 黎明生態溝 → 花宅日常 → 楓香步道 → 跩姨蔥油餅 → 候鳥西服 → 頌缽體驗 → 干城194有機書店\r\n16:00 賦歸\r\n\r\n活動日期：2025年4月19日（六）\r\n活動時間：13:00 - 16:00\r\n集合地點：干城194有機書店\r\n人數限制：20人額滿或4/16截止\r\n\r\n停車建議：\r\n干城194有機書店(集合地點周邊停車格都可停)\r\nGEOLIAM 門門(另一處停車位置，在書店後方)', '台中干城194有機書店', '臺中市黎明新村', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '0419', '無資料', '無資料', '💰 費用\r\n3/21~4/8早鳥價 $380元\r\n4/9~4/16原價 $450元\r\n(7-12歲優惠價 $250元)\r\n\r\n📦 費用包含\r\n✅ 專業導覽 & 無線耳機設備\r\n✅ 活動期間保險\r\n✅ 頌缽療癒體驗（特色亮點）\r\n✅ 蔥油餅一份\r\n✅ 黎明新村限定明信片 & 郵資\r\n\r\n📩 匯款帳號：\r\n郵局（代碼 700） 帳號：0021701-0073293\r\n\r\n📌 退款須知：報名後無法參加者，活動前三日(含)事先告知。可全額退費。\r\n\r\n📞 聯絡方式\r\n04-22589608(干城194有機書店)\r\n0912-347888(吳義舜店長)', 'https://bit.ly/4hlWFGb', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「 老城故事 × 頌缽療癒｜來場文青系City Walk 」', `description`='黎明新村，昔日省政府時期精心規劃的新市鎮，見證了台中南屯的發展軌跡。這裡鬧中取靜，街巷間彷彿藏著時光的低語，靜候每一位訪客來探索。\r\n\r\n這次，我們不只用雙腳走讀歷史，更將透過 頌缽體驗，讓身心沉浸於這片歲月靜好的秘境。當悠揚的缽音流轉於街巷之間，彷彿與舊時光產生共鳴，為這場城市散步增添一絲療癒與靜心的氛圍。\r\n\r\n走讀亮點\r\n探索黎明新村的歷史與人文——專業導覽帶你深入50年時光軌跡\r\n巷弄秘境探險——楓香步道、老宅風華，感受城市的另一面\r\n頌缽療癒體驗——在共鳴聲中沉澱心靈，感受寧靜的美好\r\n舌尖上的老時光——嚐一口招牌「跩姨蔥油餅」，感受地道風味\r\n限定旅行紀念——黎明新村專屬明信片＆郵資，帶走一份獨特記憶\r\n\r\n行程規劃\r\n13:00 - 13:30 干城194有機書店集合\r\n13:30 - 16:00 黎明生態溝 → 花宅日常 → 楓香步道 → 跩姨蔥油餅 → 候鳥西服 → 頌缽體驗 → 干城194有機書店\r\n16:00 賦歸\r\n\r\n活動日期：2025年4月19日（六）\r\n活動時間：13:00 - 16:00\r\n集合地點：干城194有機書店\r\n人數限制：20人額滿或4/16截止\r\n\r\n停車建議：\r\n干城194有機書店(集合地點周邊停車格都可停)\r\nGEOLIAM 門門(另一處停車位置，在書店後方)', `organizer`='台中干城194有機書店', `address`='臺中市黎明新村', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='0419', `latitude`='無資料', `longitude`='無資料', `ticket_price`='💰 費用\r\n3/21~4/8早鳥價 $380元\r\n4/9~4/16原價 $450元\r\n(7-12歲優惠價 $250元)\r\n\r\n📦 費用包含\r\n✅ 專業導覽 & 無線耳機設備\r\n✅ 活動期間保險\r\n✅ 頌缽療癒體驗（特色亮點）\r\n✅ 蔥油餅一份\r\n✅ 黎明新村限定明信片 & 郵資\r\n\r\n📩 匯款帳號：\r\n郵局（代碼 700） 帳號：0021701-0073293\r\n\r\n📌 退款須知：報名後無法參加者，活動前三日(含)事先告知。可全額退費。\r\n\r\n📞 聯絡方式\r\n04-22589608(干城194有機書店)\r\n0912-347888(吳義舜店長)', `source_url`='https://bit.ly/4hlWFGb', `image_url`='[]';
