INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ddd66826b32419285b7187', '賞賜有禮：清代文獻中的天子禮物', '古代來自天子的禮物，常被臣民視為一種賞賜。這份賞賜禮物的背後，有著複雜的社會學與歷史學因素，也是眾人想解開的謎團。\r\n禮物背後的意涵往往比字面上複雜，物品本身的故事，也可能更吸引人。禮尚往來，是存在於人類社會間的普世思維。「禮」可以解讀成謙和有禮貌，亦可藉由物品達到以物示禮，有時更是人與人、國與國建立關係的一種手段與目的。\r\n展覽透過清代官員上奏的奏摺、文書、檔冊等史料，了解皇帝究竟賞給臣子何種禮物？這份禮物，是令人稱羨的好禮？還是背後隱藏著看不見的責任？看看奏摺裏的硃批，找找你我心中的答案。', '國立故宮博物院', '臺北市士林區外雙溪至善路2段221號', '2025-03-22 00:00:00', '2025-06-08 00:00:00', '國立故宮博物院', 25.12546704, 121.5508473, '優惠參觀券+150;團體參觀券+320;普通參觀券+350;至善園+20', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='賞賜有禮：清代文獻中的天子禮物', `description`='古代來自天子的禮物，常被臣民視為一種賞賜。這份賞賜禮物的背後，有著複雜的社會學與歷史學因素，也是眾人想解開的謎團。\r\n禮物背後的意涵往往比字面上複雜，物品本身的故事，也可能更吸引人。禮尚往來，是存在於人類社會間的普世思維。「禮」可以解讀成謙和有禮貌，亦可藉由物品達到以物示禮，有時更是人與人、國與國建立關係的一種手段與目的。\r\n展覽透過清代官員上奏的奏摺、文書、檔冊等史料，了解皇帝究竟賞給臣子何種禮物？這份禮物，是令人稱羨的好禮？還是背後隱藏著看不見的責任？看看奏摺裏的硃批，找找你我心中的答案。', `organizer`='國立故宮博物院', `address`='臺北市士林區外雙溪至善路2段221號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-06-08 00:00:00', `location`='國立故宮博物院', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='優惠參觀券+150;團體參觀券+320;普通參觀券+350;至善園+20', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ddd66a26b32419285b718a', '石頭書 The Book of Stone', '郭志宏全新個展《石頭書 The Book of Stone》，暌違三年後於也趣藝廊盛大開展！此展以藝術家的創作核心啟程，更結合藝術生涯多年對「山」的心象描繪。山岳不是靜止的，而是在流動；郭志宏在多年的磨練和持續創作下，一路尋「山」深切出嶄新取向，自2018年《以山為名》遠觀山形、2020《嵎隅》近觀山中、2022《岳閱》環觀山貌到2025《石頭書 The Book of Stone》綜觀山體。藉由被精神化的風景遞延山的意義，拓展群山眾岳間不斷生成的語彙與風格，從不同的「攀登」中慢慢地去尋找自我淨土，最終指向藝術家與繪畫本質之間不斷流變的關係。\r\n\r\n「山不說話，只有時間，會為山說話。」\r\n\r\n山岳的存在，正如一本書，每一層岩石都是時間的見證，將地球的歷史寫入自己的肌理，而《石頭書 The Book of Stone》也試圖在一個可以翻摺的平面上，描繪時間，這個非物質卻又無所不在的力量。以礦物製成的油畫顏料，如同地質事件般在紙張表面上平塗、白描、橫掃、勾勒著內在風景、時間意識。郭志宏的作品將時間尺度與山脈並行，將自身拋擲到無法衡量的時空間之中窺探，從中投射出對群山的想像、咀嚼，高山不僅是空間中的巨人，更在時間長河裡巍然聳立，同時也在人們的內心深處延展交織。\r\n\r\n閱讀作品，能跟著山巒豐厚的曲線流於當下、在切割分層的每道皺褶面，品嚐記憶。也在留白中哲思未來。因個人生命經驗將不同時間軸纏繞一起的沉積過程，彼此翻攪次序，敘事得以重新銜接，湧現出時光的深化。這已超乎對自然景觀的描摹，而是對「時間」這一無形力量的具象表達。\r\n\r\n2025.03.29 (六) - 2025.04.26 (六)，攀爬上《石頭書 The Book of Stone》打破線性思維及文化界限，解構再構時間、地景變化以及人類視角的轉變。此書無關人名、地點、和日期，帶領觀眾一路翻閱山壁倒退回到過去，一路瞻望山峰遙想未來模樣。', '也趣藝廊', '臺北市大同區民族西路141號', '2025-03-29 00:00:00', '2025-04-26 00:00:00', '也趣藝廊 AKI Gallery', 25.06342433, 121.5130417, '無資料', 'https://www.galleryaki.com/zh/exhibition/content/post/294', '[]') ON DUPLICATE KEY UPDATE `activity_name`='石頭書 The Book of Stone', `description`='郭志宏全新個展《石頭書 The Book of Stone》，暌違三年後於也趣藝廊盛大開展！此展以藝術家的創作核心啟程，更結合藝術生涯多年對「山」的心象描繪。山岳不是靜止的，而是在流動；郭志宏在多年的磨練和持續創作下，一路尋「山」深切出嶄新取向，自2018年《以山為名》遠觀山形、2020《嵎隅》近觀山中、2022《岳閱》環觀山貌到2025《石頭書 The Book of Stone》綜觀山體。藉由被精神化的風景遞延山的意義，拓展群山眾岳間不斷生成的語彙與風格，從不同的「攀登」中慢慢地去尋找自我淨土，最終指向藝術家與繪畫本質之間不斷流變的關係。\r\n\r\n「山不說話，只有時間，會為山說話。」\r\n\r\n山岳的存在，正如一本書，每一層岩石都是時間的見證，將地球的歷史寫入自己的肌理，而《石頭書 The Book of Stone》也試圖在一個可以翻摺的平面上，描繪時間，這個非物質卻又無所不在的力量。以礦物製成的油畫顏料，如同地質事件般在紙張表面上平塗、白描、橫掃、勾勒著內在風景、時間意識。郭志宏的作品將時間尺度與山脈並行，將自身拋擲到無法衡量的時空間之中窺探，從中投射出對群山的想像、咀嚼，高山不僅是空間中的巨人，更在時間長河裡巍然聳立，同時也在人們的內心深處延展交織。\r\n\r\n閱讀作品，能跟著山巒豐厚的曲線流於當下、在切割分層的每道皺褶面，品嚐記憶。也在留白中哲思未來。因個人生命經驗將不同時間軸纏繞一起的沉積過程，彼此翻攪次序，敘事得以重新銜接，湧現出時光的深化。這已超乎對自然景觀的描摹，而是對「時間」這一無形力量的具象表達。\r\n\r\n2025.03.29 (六) - 2025.04.26 (六)，攀爬上《石頭書 The Book of Stone》打破線性思維及文化界限，解構再構時間、地景變化以及人類視角的轉變。此書無關人名、地點、和日期，帶領觀眾一路翻閱山壁倒退回到過去，一路瞻望山峰遙想未來模樣。', `organizer`='也趣藝廊', `address`='臺北市大同區民族西路141號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='也趣藝廊 AKI Gallery', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='無資料', `source_url`='https://www.galleryaki.com/zh/exhibition/content/post/294', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ddd66a26b32419285b718b', '《日子在說話》張文菀個展 ', '當物品開口說話，你會聽見什麼？\r\n在本次展覽中，藝術家張文菀透過對物件的詮釋，讓觀者意識到自身對世界的理解是如何被習慣塑造的。張文菀的作品擅長透過幽默與反思，鬆動既定的符號系統，讓尋常事物獲得新的生命。她的創作不只是對日常的描繪，更是對觀看習慣的挑戰——當鉛筆自稱為魔杖，當衣架懸掛的不只是衣物，而是意義本身，這些看似平凡的物件開始訴說我們未曾察覺的故事。\r\n我們如何賦予物品意義？物品如何反映我們的思維與情感？在這場展覽中，每一個細節都是一則等待被解讀的寓言，邀請你以新的方式觀看、思考，並重新認識那些「看似」熟悉的日常。', '當代一畫廊', '臺北市松山區', '2025-03-28 00:00:00', '2025-05-10 00:00:00', '松山區（臺北市）=', 25.05999101, 121.5575876, '無資料', 'https://sissyleelee1.wixsite.com/agallery', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《日子在說話》張文菀個展 ', `description`='當物品開口說話，你會聽見什麼？\r\n在本次展覽中，藝術家張文菀透過對物件的詮釋，讓觀者意識到自身對世界的理解是如何被習慣塑造的。張文菀的作品擅長透過幽默與反思，鬆動既定的符號系統，讓尋常事物獲得新的生命。她的創作不只是對日常的描繪，更是對觀看習慣的挑戰——當鉛筆自稱為魔杖，當衣架懸掛的不只是衣物，而是意義本身，這些看似平凡的物件開始訴說我們未曾察覺的故事。\r\n我們如何賦予物品意義？物品如何反映我們的思維與情感？在這場展覽中，每一個細節都是一則等待被解讀的寓言，邀請你以新的方式觀看、思考，並重新認識那些「看似」熟悉的日常。', `organizer`='當代一畫廊', `address`='臺北市松山區', `start_date`='2025-03-28 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='松山區（臺北市）=', `latitude`=25.05999101, `longitude`=121.5575876, `ticket_price`='無資料', `source_url`='https://sissyleelee1.wixsite.com/agallery', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ddd66c26b32419285b718c', '2025 青春美展 長榮大學美術學系 畢業展－「在□一端 on the＿side」', '《在□一端》 □是一道隱形的界線，是空格，是空白，是框，是門，是連接藝術世界的中介物。 這道界線既是限制，也是可能，既是邊界，也是通道。當你跨越它，便踏入了 一片未知與想像的領域。這裡沒有固定的形狀，沒有絕對的答案，只有無窮無 盡的詮釋空間。在不同作者的視角與你的想像交織之間，你與我共同建構出獨 屬於我們的作品。 請在□中，填入你的回應。讓你的想法流動，讓你的意識遊走，讓這道界線成 為連結，而非阻隔。在這個開放的場域中，你將發現，每一個填入的詞彙，都 是對世界新的詮釋。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-05-30 00:00:00', '2025-06-10 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4116', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 青春美展 長榮大學美術學系 畢業展－「在□一端 on the＿side」', `description`='《在□一端》 □是一道隱形的界線，是空格，是空白，是框，是門，是連接藝術世界的中介物。 這道界線既是限制，也是可能，既是邊界，也是通道。當你跨越它，便踏入了 一片未知與想像的領域。這裡沒有固定的形狀，沒有絕對的答案，只有無窮無 盡的詮釋空間。在不同作者的視角與你的想像交織之間，你與我共同建構出獨 屬於我們的作品。 請在□中，填入你的回應。讓你的想法流動，讓你的意識遊走，讓這道界線成 為連結，而非阻隔。在這個開放的場域中，你將發現，每一個填入的詞彙，都 是對世界新的詮釋。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-30 00:00:00', `end_date`='2025-06-10 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4116', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ddd66c26b32419285b718e', '美國文化系列講座─英文新聞解析', '河堤分館美國資料中心邀請了資深外籍老師Dana Helgeson來講解英語時事，透過導讀、分享及討論的方式，增進你的英語閱讀能力！', '高雄市立圖書館總館', '高雄市三民區4鄰裕誠路1號', '2025-05-04 00:00:00', '2025-05-11 00:00:00', '高雄市立圖書館河堤分館', 22.663171, 120.315269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='美國文化系列講座─英文新聞解析', `description`='河堤分館美國資料中心邀請了資深外籍老師Dana Helgeson來講解英語時事，透過導讀、分享及討論的方式，增進你的英語閱讀能力！', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區4鄰裕誠路1號', `start_date`='2025-05-04 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='高雄市立圖書館河堤分館', `latitude`=22.663171, `longitude`=120.315269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
