INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ddd66c26b32419285b7190', '玩遊戲學美語', '讓小朋友以輕鬆快樂的學習方式，從遊戲中學習到生活週遭的英文單字與片語，以期能實際應用於生活中。', '高雄市立圖書館總館', '高雄市三民區4鄰裕誠路1號', '2025-05-04 00:00:00', '2025-05-18 00:00:00', '高雄市立圖書館河堤分館', 22.663171, 120.315269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='玩遊戲學美語', `description`='讓小朋友以輕鬆快樂的學習方式，從遊戲中學習到生活週遭的英文單字與片語，以期能實際應用於生活中。', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區4鄰裕誠路1號', `start_date`='2025-05-04 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='高雄市立圖書館河堤分館', `latitude`=22.663171, `longitude`=120.315269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ddd66d26b32419285b7193', '《閱讀交通慢看停-交通標誌解謎趣》展覽', '你知道經典童書《讓路給小鴨子》 其實蘊藏著重要的「人本交通精神」嗎？\r\n2023年開始 高雄市立圖書館-國際繪本中心 承接 「閱讀交通共好行」 計畫，邀請高雄知名繪本作家 廖健宏 & 林秀穗 夫妻檔擔任導師，帶領 河堤國小 與 福東國小 的小朋友，開啟一場精彩的交通繪本創作之旅！\r\n\r\n經過32堂滿滿創意與知識的課程，孩子們親手打造出 兩本很有意義的交通主題繪本，不只畫出對周圍環境的觀察，更透過故事提及「安全、友善、尊重」來傳遞基本觀念，讓每個人都能成為人本交通的推動者！\r\n\r\n【 最新特展及活動來啦！】\r\n今年我們繼續延伸主題，將 福東國小 小朋友共創的繪本 《 交通標誌小神探 》 帶進展場，以 「閱讀交通慢看停 — 交通標誌解謎趣」 為主題，邀請大家一起來探索街道上熟悉又重要的交通標誌，透過翻翻牌互動問答，以及四大主題交通繪本特展，讓大小朋友更了解它們的正確意涵！\r\n\r\n《閱讀交通 慢看停—交通標誌解謎趣》\r\n󠀠展期｜即日起至2025年 5月 18日 (星期日)\r\n地點｜高雄市立圖書館 總館 B1繪本廣場\r\n\r\n●展區亮點\r\n1.交通標誌互動體驗｜透過遊戲認識街頭標誌\r\n2.交通安全學習站四大主題｜\r\na.交通安全停看聽、b.交通工具大集合、\r\nc.交通沿途的風景、d.特別的交通繪本、\r\ne.交通學習單挑戰！\r\n還可以到國際繪本中心櫃台兌換精美禮物喔~', '高雄市政府交通局', '高雄市前鎮區21鄰新光路61號', '2025-03-18 00:00:00', '2025-05-18 00:00:00', '高雄市立圖書館總館', 22.6115529, 120.3024491, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《閱讀交通慢看停-交通標誌解謎趣》展覽', `description`='你知道經典童書《讓路給小鴨子》 其實蘊藏著重要的「人本交通精神」嗎？\r\n2023年開始 高雄市立圖書館-國際繪本中心 承接 「閱讀交通共好行」 計畫，邀請高雄知名繪本作家 廖健宏 & 林秀穗 夫妻檔擔任導師，帶領 河堤國小 與 福東國小 的小朋友，開啟一場精彩的交通繪本創作之旅！\r\n\r\n經過32堂滿滿創意與知識的課程，孩子們親手打造出 兩本很有意義的交通主題繪本，不只畫出對周圍環境的觀察，更透過故事提及「安全、友善、尊重」來傳遞基本觀念，讓每個人都能成為人本交通的推動者！\r\n\r\n【 最新特展及活動來啦！】\r\n今年我們繼續延伸主題，將 福東國小 小朋友共創的繪本 《 交通標誌小神探 》 帶進展場，以 「閱讀交通慢看停 — 交通標誌解謎趣」 為主題，邀請大家一起來探索街道上熟悉又重要的交通標誌，透過翻翻牌互動問答，以及四大主題交通繪本特展，讓大小朋友更了解它們的正確意涵！\r\n\r\n《閱讀交通 慢看停—交通標誌解謎趣》\r\n󠀠展期｜即日起至2025年 5月 18日 (星期日)\r\n地點｜高雄市立圖書館 總館 B1繪本廣場\r\n\r\n●展區亮點\r\n1.交通標誌互動體驗｜透過遊戲認識街頭標誌\r\n2.交通安全學習站四大主題｜\r\na.交通安全停看聽、b.交通工具大集合、\r\nc.交通沿途的風景、d.特別的交通繪本、\r\ne.交通學習單挑戰！\r\n還可以到國際繪本中心櫃台兌換精美禮物喔~', `organizer`='高雄市政府交通局', `address`='高雄市前鎮區21鄰新光路61號', `start_date`='2025-03-18 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='高雄市立圖書館總館', `latitude`=22.6115529, `longitude`=120.3024491, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
