INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ddd66d26b32419285b719e', '「輕舟已過萬重山-二呆的『山』畫」特展', '趙二呆(1917-1995)，淡泊名利，於1971年(五十四歲)提早退休，二呆的理想是致力於藝術創作。二呆藝館收藏千餘件二呆的創作，同時出現小舟和山的畫作約計有63幅，本展取李白「輕舟已過萬重山」之詩句，強調趙二呆退休後的心情，是經過許多人生閱歷，而呈現雲淡風輕的節奏。', '澎湖縣政府文化局', '澎湖縣馬公市中華路230號', '2025-03-28 00:00:00', '2025-12-31 00:00:00', '澎湖縣政府文化局', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「輕舟已過萬重山-二呆的『山』畫」特展', `description`='趙二呆(1917-1995)，淡泊名利，於1971年(五十四歲)提早退休，二呆的理想是致力於藝術創作。二呆藝館收藏千餘件二呆的創作，同時出現小舟和山的畫作約計有63幅，本展取李白「輕舟已過萬重山」之詩句，強調趙二呆退休後的心情，是經過許多人生閱歷，而呈現雲淡風輕的節奏。', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路230號', `start_date`='2025-03-28 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='澎湖縣政府文化局', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
