INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ddd66d26b32419285b71a3', '心像與現象－陳鴻文個展', '2025年「心像與現象」陳鴻文個展\r\n展期｜4月12日－4月28日\r\n展地｜金門縣文化局第二展場\r\n開幕式｜4月12日上午10時\r\n展出主題為「心像與現象」，藝術家陳鴻文表示：『透過以具象寫實為主的水彩技法，畫了許多金門的風光，以及在我身邊的人，這些就是各種「現象」。但是有時候，我會畫出我想像的東西，可能是看著某個生活中的景象，聯想到一個讓我感覺印象深刻的圖像，這個帶些魔幻色彩的內心圖像，我把它們畫出來，稱為「心像」。不論是心像還是現象，都是我感到印象深刻難以忘懷，才把它們畫下來。』\r\n本次展出的作品，集結了近八年來陳鴻文水彩創作的精華，於這段期間約三百餘幅作品中，精選六十餘幅，代表各時期創作關心的主題，以各種觀看角度，試驗相應的技巧，可以說是這段時間藝術創作的總結性呈現，期望能得到蒞臨參觀畫作者的共鳴，也歡迎來訪者批評與指教。\r\n金門縣文化局與金門縣美術學會誠摯邀請所有對藝術有興趣，尤其是對水彩創作的朋友，來欣賞這次展覽，並與陳鴻文一起深入探索水彩的藝術與技術。這不僅是視覺的享受，也是心靈的對話，邀您一起感受金門獨特的地方魅力與藝術家的情感表達。\r\n主辦／金門縣文化局\r\n協辦／金門縣美術學會', '金門縣文化局', '金門縣金城鎮環島北路一段66號', '2025-04-12 00:00:00', '2025-04-28 00:00:00', '金門縣文化局', 24.38402, 118.30128, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='心像與現象－陳鴻文個展', `description`='2025年「心像與現象」陳鴻文個展\r\n展期｜4月12日－4月28日\r\n展地｜金門縣文化局第二展場\r\n開幕式｜4月12日上午10時\r\n展出主題為「心像與現象」，藝術家陳鴻文表示：『透過以具象寫實為主的水彩技法，畫了許多金門的風光，以及在我身邊的人，這些就是各種「現象」。但是有時候，我會畫出我想像的東西，可能是看著某個生活中的景象，聯想到一個讓我感覺印象深刻的圖像，這個帶些魔幻色彩的內心圖像，我把它們畫出來，稱為「心像」。不論是心像還是現象，都是我感到印象深刻難以忘懷，才把它們畫下來。』\r\n本次展出的作品，集結了近八年來陳鴻文水彩創作的精華，於這段期間約三百餘幅作品中，精選六十餘幅，代表各時期創作關心的主題，以各種觀看角度，試驗相應的技巧，可以說是這段時間藝術創作的總結性呈現，期望能得到蒞臨參觀畫作者的共鳴，也歡迎來訪者批評與指教。\r\n金門縣文化局與金門縣美術學會誠摯邀請所有對藝術有興趣，尤其是對水彩創作的朋友，來欣賞這次展覽，並與陳鴻文一起深入探索水彩的藝術與技術。這不僅是視覺的享受，也是心靈的對話，邀您一起感受金門獨特的地方魅力與藝術家的情感表達。\r\n主辦／金門縣文化局\r\n協辦／金門縣美術學會', `organizer`='金門縣文化局', `address`='金門縣金城鎮環島北路一段66號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-28 00:00:00', `location`='金門縣文化局', `latitude`=24.38402, `longitude`=118.30128, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ddd66d26b32419285b71a4', '性別齊視不歧視 繪本主題書展', '當任何人以言語或行為對特定性別、性取向、性別特質不同之人為差別對待，或製造敵意環境，即是「性別歧視」，例如：認為女性就是沒大腦、不許女性發言、宣揚同性戀都有病、取笑具陽剛味重的女性、捉弄具陰柔氣質的男性、拒絕特定性別之人擔任特定職位等。\r\n每個人都有陽剛的一面，也有陰柔的一面。我們應該尊重每個人，允許她/他有尊嚴地活出自己生命的樣貌，追尋自己的使命！「只要性別『齊』視，不要性別『歧』視」，從現在開始、你我做起，別用異樣的眼光看男女，保持一顆互相尊重、包容的心，「性別平等」的觀念就會逐漸落實在日常生活中，藉由性別齊視不歧視主題書展讓大家更進一步的認識。', '高雄市立圖書館總館', '高雄市六龜區2鄰光復路70號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '高雄市立圖書館六龜分館', 23.0063302, 120.6549199, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='性別齊視不歧視 繪本主題書展', `description`='當任何人以言語或行為對特定性別、性取向、性別特質不同之人為差別對待，或製造敵意環境，即是「性別歧視」，例如：認為女性就是沒大腦、不許女性發言、宣揚同性戀都有病、取笑具陽剛味重的女性、捉弄具陰柔氣質的男性、拒絕特定性別之人擔任特定職位等。\r\n每個人都有陽剛的一面，也有陰柔的一面。我們應該尊重每個人，允許她/他有尊嚴地活出自己生命的樣貌，追尋自己的使命！「只要性別『齊』視，不要性別『歧』視」，從現在開始、你我做起，別用異樣的眼光看男女，保持一顆互相尊重、包容的心，「性別平等」的觀念就會逐漸落實在日常生活中，藉由性別齊視不歧視主題書展讓大家更進一步的認識。', `organizer`='高雄市立圖書館總館', `address`='高雄市六龜區2鄰光復路70號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市立圖書館六龜分館', `latitude`=23.0063302, `longitude`=120.6549199, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ddd66d26b32419285b71a6', '書法特展', '由南部地區知名的書法社團高雄紫雲書藝的高雪燕老師展出個人書法及書法班成果。', '高雄市立圖書館總館', '高雄市鳳山區6鄰曹公路23號', '2025-03-15 00:00:00', '2025-05-31 00:00:00', '高雄市立圖書館鳳山曹公分館', 22.627077, 120.357172, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='書法特展', `description`='由南部地區知名的書法社團高雄紫雲書藝的高雪燕老師展出個人書法及書法班成果。', `organizer`='高雄市立圖書館總館', `address`='高雄市鳳山區6鄰曹公路23號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='高雄市立圖書館鳳山曹公分館', `latitude`=22.627077, `longitude`=120.357172, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ddd66d26b32419285b71a7', '吾之萬象—宇化萬千    李哲儀個展', '我與累世累積存於佛教阿賴耶識以及淺意識無意識中的我，藉由與他們不段的溝通以及調閱，以及宇宙之大方向愛與人之關係作為探討。\r\n\r\n依照《薄伽梵歌》、《般若波羅蜜多心經》中所聞，以現代話語解釋，這個世界上是一場虛擬的世界，而以現代科學來說我們都是由弦理論（英語：String theory）弦與粒子構成，而這世界由陽光、空氣、水造就生命以及時代流動。因此在多視角之角度談同一件事時，會依不同維度出現，每一刻是幻象？還是過往就是幻象之過程？\r\n\r\n藝術家探討人與自我每一個面向之角度與心靈之感觸。將最柔情的心識留給自己的創作作品之中，以一種氣勢和意識型態表示千變萬化的創作。\r\n\r\n▍藝術家：李哲儀\r\n▍展覽日期：2025.4.19(六)-5.11(日)\r\n▍展覽地點：新浜碼頭藝術空間A、B展覽室\r\n▍展覽開幕：2025.4.27(日)13：30\r\n▍與談人：徐婉貞、蔡伊婷、李哲儀\r\n▍空間贊助單位：國藝會\r\n▍新浜行政：陳羚溱、吳宛倫\r\n▍實習生：孔媛、陳咨蓉\r\n', '無資料', '高雄市鹽埕區015鄰大勇路64號2樓', '2025-04-19 00:00:00', '2025-05-11 00:00:00', '新浜碼頭藝術空間', 22.6228436, 120.2835667, '無資料', 'https://sinpink.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='吾之萬象—宇化萬千    李哲儀個展', `description`='我與累世累積存於佛教阿賴耶識以及淺意識無意識中的我，藉由與他們不段的溝通以及調閱，以及宇宙之大方向愛與人之關係作為探討。\r\n\r\n依照《薄伽梵歌》、《般若波羅蜜多心經》中所聞，以現代話語解釋，這個世界上是一場虛擬的世界，而以現代科學來說我們都是由弦理論（英語：String theory）弦與粒子構成，而這世界由陽光、空氣、水造就生命以及時代流動。因此在多視角之角度談同一件事時，會依不同維度出現，每一刻是幻象？還是過往就是幻象之過程？\r\n\r\n藝術家探討人與自我每一個面向之角度與心靈之感觸。將最柔情的心識留給自己的創作作品之中，以一種氣勢和意識型態表示千變萬化的創作。\r\n\r\n▍藝術家：李哲儀\r\n▍展覽日期：2025.4.19(六)-5.11(日)\r\n▍展覽地點：新浜碼頭藝術空間A、B展覽室\r\n▍展覽開幕：2025.4.27(日)13：30\r\n▍與談人：徐婉貞、蔡伊婷、李哲儀\r\n▍空間贊助單位：國藝會\r\n▍新浜行政：陳羚溱、吳宛倫\r\n▍實習生：孔媛、陳咨蓉\r\n', `organizer`='無資料', `address`='高雄市鹽埕區015鄰大勇路64號2樓', `start_date`='2025-04-19 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='新浜碼頭藝術空間', `latitude`=22.6228436, `longitude`=120.2835667, `ticket_price`='無資料', `source_url`='https://sinpink.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67de6eb98f15adefa04e0c87', '日常之歌', '▍活動簡介｜\r\n\r\n\r\n在此製作中希望呈現劇中的日常平靜之下藏著多少波瀾，去放大、放慢這些生活的節點，讓觀者看見細節中隱藏的煩惱與抉擇。我們的生活正是因為這些節點而有所變化，對於這些細節過於習以為常時，我們將忽略自己真正在意之事，心之所向將被盲目的忽視。希望能透過劇中人（時芬）感知、看見、探究自我逃避之事的過程，讓觀者能理解到這件事：感知生活的細節，看見日常之殤，才能謳歌日常。', '新浜碼頭藝術空間', '高雄市鹽埕區大勇路64號2F', '2025-04-25 00:00:00', '2025-04-27 00:00:00', '新浜碼頭藝術空間', 22.62424585, 120.2842331, '全票350\r\n贊助票500', 'https://docs.google.com/forms/d/e/1FAIpQLScgGPb4pKvuO4h7fzEl05jq3IuU4NnOhOIdsRovjnvRsvgXHg/viewform', '[]') ON DUPLICATE KEY UPDATE `activity_name`='日常之歌', `description`='▍活動簡介｜\r\n\r\n\r\n在此製作中希望呈現劇中的日常平靜之下藏著多少波瀾，去放大、放慢這些生活的節點，讓觀者看見細節中隱藏的煩惱與抉擇。我們的生活正是因為這些節點而有所變化，對於這些細節過於習以為常時，我們將忽略自己真正在意之事，心之所向將被盲目的忽視。希望能透過劇中人（時芬）感知、看見、探究自我逃避之事的過程，讓觀者能理解到這件事：感知生活的細節，看見日常之殤，才能謳歌日常。', `organizer`='新浜碼頭藝術空間', `address`='高雄市鹽埕區大勇路64號2F', `start_date`='2025-04-25 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='新浜碼頭藝術空間', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='全票350\r\n贊助票500', `source_url`='https://docs.google.com/forms/d/e/1FAIpQLScgGPb4pKvuO4h7fzEl05jq3IuU4NnOhOIdsRovjnvRsvgXHg/viewform', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67df288626b32419285b71aa', '《瑤·集》Precious Collection 台南應用科技大學美術系114級畢業小組成果展', '台南應用科技大學美術系114級學生在林鴻文與黃怡雯兩位老師的指導下，在《瑤·集》展覽中，以多元媒材與創新視角呈現內心的世界。每件作品既是對自我成長的探索，也是對社會關注的回應。創作者將生活經驗、環境影響與個人成長轉化為藝術語言，藉由作品訴說屬於這一代的獨特故事。', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-04-05 00:00:00', '2025-04-20 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', 'https://xinying-culture.tainan.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《瑤·集》Precious Collection 台南應用科技大學美術系114級畢業小組成果展', `description`='台南應用科技大學美術系114級學生在林鴻文與黃怡雯兩位老師的指導下，在《瑤·集》展覽中，以多元媒材與創新視角呈現內心的世界。每件作品既是對自我成長的探索，也是對社會關注的回應。創作者將生活經驗、環境影響與個人成長轉化為藝術語言，藉由作品訴說屬於這一代的獨特故事。', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='https://xinying-culture.tainan.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67df289326b32419285b71ab', '2025琴棋書畫在歸仁-第二季課程(4-6月)', '為活絡本區美學館各館室空間之使用，同時提供民眾假日休閒的好去處，及陶冶藝術人文氣息，特辦理本系列課程活動。\r\n第二季藝文課程:\r\n4/13、4/27、5/4、5/18、6/8、6/15 \r\n10:00-12:00 多媒材繪畫、黏土班-豆豆老師\r\n4/9、4/16、4/23、4/30、5/7、5/14、5/21、5/28、6/4、6/11\r\n14:30-16:30 吉祥工筆畫-黃士哲老師\r\n4/12、4/26、5/10、5/24、6/14、6/28\r\n10:00-12:00 禪繞繪畫班-蔡翠雲老師\r\n單次課程：\r\n4/13 10:00-12:00 鯨魚小盆栽 陶土-DIY-吳家慧老師\r\n5/4 10:00-12:00 可愛動物絨毛吊飾-謝金桃老師\r\n6/22 10:00-12:00 富士山小蓋罐 陶土-DIY-吳家慧老師', '臺南市歸仁區公所', '臺南市歸仁區中山路一段568號', '2025-04-09 00:00:00', '2025-06-28 00:00:00', '臺南市歸仁美學館', 22.94679469, 120.2930627, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025琴棋書畫在歸仁-第二季課程(4-6月)', `description`='為活絡本區美學館各館室空間之使用，同時提供民眾假日休閒的好去處，及陶冶藝術人文氣息，特辦理本系列課程活動。\r\n第二季藝文課程:\r\n4/13、4/27、5/4、5/18、6/8、6/15 \r\n10:00-12:00 多媒材繪畫、黏土班-豆豆老師\r\n4/9、4/16、4/23、4/30、5/7、5/14、5/21、5/28、6/4、6/11\r\n14:30-16:30 吉祥工筆畫-黃士哲老師\r\n4/12、4/26、5/10、5/24、6/14、6/28\r\n10:00-12:00 禪繞繪畫班-蔡翠雲老師\r\n單次課程：\r\n4/13 10:00-12:00 鯨魚小盆栽 陶土-DIY-吳家慧老師\r\n5/4 10:00-12:00 可愛動物絨毛吊飾-謝金桃老師\r\n6/22 10:00-12:00 富士山小蓋罐 陶土-DIY-吳家慧老師', `organizer`='臺南市歸仁區公所', `address`='臺南市歸仁區中山路一段568號', `start_date`='2025-04-09 00:00:00', `end_date`='2025-06-28 00:00:00', `location`='臺南市歸仁美學館', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67df28b926b32419285b71af', 'Anping 1865 洋潮來襲：回望安平商貿的黃金年代', '曾經是走私寶地的府城，在歷經開港爭論後，終於1865年正式開港對外通商，並設立海關，開啟安平貿易新時代！\r\n來到安平的洋行職員們在這裡工作、生活、形成社群。身在異國的他們，如何適應異地生活？社交娛樂又是什麼樣貌？跟著展覽，一窺19世紀的異國社群文化！', '臺南市政府文化局', '臺南市安平區安北路194號', '2025-04-04 00:00:00', '2025-12-31 00:00:00', '直轄市定古蹟原英商德記洋行暨安平樹屋', 22.99008437, 120.1649949, '半票+35;全票+70', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Anping 1865 洋潮來襲：回望安平商貿的黃金年代', `description`='曾經是走私寶地的府城，在歷經開港爭論後，終於1865年正式開港對外通商，並設立海關，開啟安平貿易新時代！\r\n來到安平的洋行職員們在這裡工作、生活、形成社群。身在異國的他們，如何適應異地生活？社交娛樂又是什麼樣貌？跟著展覽，一窺19世紀的異國社群文化！', `organizer`='臺南市政府文化局', `address`='臺南市安平區安北路194號', `start_date`='2025-04-04 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='直轄市定古蹟原英商德記洋行暨安平樹屋', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='半票+35;全票+70', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67df28c226b32419285b71b1', '竹亞軒藝術聯展•華風墨韵', '《華風墨韵》藝文展由「後山才女」陳文珍老師帶領竹亞軒藝術畫廊學員聯合展出。陳老師指導學員運用潑墨、寫意技法，將水墨結合水干膠彩交相揮灑，展出作品不論是潑墨山水、牡丹花鳥、仕女美圖創作，風格獨特多元。表現出後現代水墨的新意及巧思，豐富了水墨畫中的深度與廣度，令人讚賞。', '臺南市政府秘書處', '臺南市新營區民治路36號', '2025-04-02 00:00:00', '2025-04-29 00:00:00', '臺南市民治市政中心', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='竹亞軒藝術聯展•華風墨韵', `description`='《華風墨韵》藝文展由「後山才女」陳文珍老師帶領竹亞軒藝術畫廊學員聯合展出。陳老師指導學員運用潑墨、寫意技法，將水墨結合水干膠彩交相揮灑，展出作品不論是潑墨山水、牡丹花鳥、仕女美圖創作，風格獨特多元。表現出後現代水墨的新意及巧思，豐富了水墨畫中的深度與廣度，令人讚賞。', `organizer`='臺南市政府秘書處', `address`='臺南市新營區民治路36號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='臺南市民治市政中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67df28c326b32419285b71b6', '梁璥韓西畫創作個展', '官田區公所於本所二樓藝文迴廊舉辦「梁璥韓西畫創作個展」，展出作品共計12件，以家園為主題，歡迎洽公民眾、各界貴賓蒞臨欣賞。', '臺南市官田區公所', '臺南市官田區', '2025-04-01 00:00:00', '2025-06-30 00:00:00', '官田區（臺南市）=', 23.19098548, 120.3479918, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='梁璥韓西畫創作個展', `description`='官田區公所於本所二樓藝文迴廊舉辦「梁璥韓西畫創作個展」，展出作品共計12件，以家園為主題，歡迎洽公民眾、各界貴賓蒞臨欣賞。', `organizer`='臺南市官田區公所', `address`='臺南市官田區', `start_date`='2025-04-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='官田區（臺南市）=', `latitude`=23.19098548, `longitude`=120.3479918, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67df28c326b32419285b71b7', '福爾摩沙時代—臺灣近現代美術的知識啟蒙', '自荷人登陸，歷經清初建城、日本殖民遷都及戰後國府來臺，頻繁政治更迭及族裔往來積累多元歷史遺存，展現流動雜揉的海國徵候。「現代化」不僅促使美術走向世界，更激發文化內視之轉向，創建跨越國界及現代進步特質之新文化，已蔚為共識。猶如黃土水創造「福爾摩沙時代」的呼籲已逾百年，成為吾人建構在地意識及知識啟蒙的重大方針。\r\n\r\n為系統體現此百年成果，本展分三階段接力展出。首段選定1950年前出生藝術家，規劃(1)百年精粹/「國寶」的誕生、(2)發現「福爾摩沙」、(3)地方色彩／城鄉記憶、(4)身體意象／時代印記、(5)從南國到民國、(6)「現代性」的內在轉向、(7)「世界」美術藍圖、(8)寶島長春/重啟在地提問等子題，探討身分認同、版圖移轉及典範成立等的不同時代意義。\r\n(協辦) 國立故宮博物院、國立臺灣歷史博物館、國立臺灣美術館\r\n(協辦) 國立歷史博物館、國家攝影文化中心、中央研究院嶺南美術館\r\n(協辦) 高雄市立美術館、桃園市立美術館、臺北市立美術館、臺南市立博物\r\n(協辦) 嘉義市立美術館、農業部林業及自然保育署嘉義分署', '文化部', '臺南市中西區臺南市中西區忠義路二段 1 號', '2025-03-25 00:00:00', '2025-07-06 00:00:00', '臺南市美術館2館', 22.99594458, 120.192874, '--+--', 'https://www.tnam.museum/exhibition/detail/595', '[]') ON DUPLICATE KEY UPDATE `activity_name`='福爾摩沙時代—臺灣近現代美術的知識啟蒙', `description`='自荷人登陸，歷經清初建城、日本殖民遷都及戰後國府來臺，頻繁政治更迭及族裔往來積累多元歷史遺存，展現流動雜揉的海國徵候。「現代化」不僅促使美術走向世界，更激發文化內視之轉向，創建跨越國界及現代進步特質之新文化，已蔚為共識。猶如黃土水創造「福爾摩沙時代」的呼籲已逾百年，成為吾人建構在地意識及知識啟蒙的重大方針。\r\n\r\n為系統體現此百年成果，本展分三階段接力展出。首段選定1950年前出生藝術家，規劃(1)百年精粹/「國寶」的誕生、(2)發現「福爾摩沙」、(3)地方色彩／城鄉記憶、(4)身體意象／時代印記、(5)從南國到民國、(6)「現代性」的內在轉向、(7)「世界」美術藍圖、(8)寶島長春/重啟在地提問等子題，探討身分認同、版圖移轉及典範成立等的不同時代意義。\r\n(協辦) 國立故宮博物院、國立臺灣歷史博物館、國立臺灣美術館\r\n(協辦) 國立歷史博物館、國家攝影文化中心、中央研究院嶺南美術館\r\n(協辦) 高雄市立美術館、桃園市立美術館、臺北市立美術館、臺南市立博物\r\n(協辦) 嘉義市立美術館、農業部林業及自然保育署嘉義分署', `organizer`='文化部', `address`='臺南市中西區臺南市中西區忠義路二段 1 號', `start_date`='2025-03-25 00:00:00', `end_date`='2025-07-06 00:00:00', `location`='臺南市美術館2館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='--+--', `source_url`='https://www.tnam.museum/exhibition/detail/595', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67df28c326b32419285b71b8', '錯中錯．連環夢—陳春祿攝影典藏研究展', '陳春祿(1956-)出生於臺南，為臺灣重要實驗攝影家，本館為國內典藏陳春祿《開天》與《收藏童年》兩大系列最完整的館舍。本展奠基於展覽顧問臺灣資深攝影家莊靈、姜麗華教授研究團隊與藝術家陳春祿的鼎力支持，首次同時展出其五大系列作品——《風》、《冥色呼吸》、《開天》、《收藏童年》、《廟可廟》，進一步強調陳春祿獨具風格的攝影美學，彰顯臺灣攝影史珍貴的啟蒙時刻。', '臺南市美術館', '臺南市中西區臺南市中西區忠義路二段 1 號', '2025-04-03 00:00:00', '2025-08-17 00:00:00', '臺南市美術館2館', 22.99594458, 120.192874, '--+--', 'https://www.tnam.museum/exhibition/detail/592', '[]') ON DUPLICATE KEY UPDATE `activity_name`='錯中錯．連環夢—陳春祿攝影典藏研究展', `description`='陳春祿(1956-)出生於臺南，為臺灣重要實驗攝影家，本館為國內典藏陳春祿《開天》與《收藏童年》兩大系列最完整的館舍。本展奠基於展覽顧問臺灣資深攝影家莊靈、姜麗華教授研究團隊與藝術家陳春祿的鼎力支持，首次同時展出其五大系列作品——《風》、《冥色呼吸》、《開天》、《收藏童年》、《廟可廟》，進一步強調陳春祿獨具風格的攝影美學，彰顯臺灣攝影史珍貴的啟蒙時刻。', `organizer`='臺南市美術館', `address`='臺南市中西區臺南市中西區忠義路二段 1 號', `start_date`='2025-04-03 00:00:00', `end_date`='2025-08-17 00:00:00', `location`='臺南市美術館2館', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='--+--', `source_url`='https://www.tnam.museum/exhibition/detail/592', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67dfd3aa07f3d4433af9555b', '2025享聽長笛二重奏--時間之河', '【藝想天開室內樂集】為國內知名藝文團體，成立以來積極推廣室內樂教育，2025年再度推出《時間的流》，由長笛家/梁禮昇、王宜韻，鋼琴家/李宜倫共同演出。\r\n本次曲目從古典延伸至當代，帶領聽眾與作曲家進行跨越時空的交流。\r\n\r\n演出地點：國家演奏廳\r\n演出時間：114/05/26-晚 19:30\r\n主辦：藝想天開室內樂集\r\n贊助：博凱·六么·譜集\r\n演出者：長笛｜梁禮昇、王宜韻  鋼琴｜李宜倫 \r\n票價：400、600、800\r\n折扣訊息：學生票及兩廳院之友9折，團體票10張85折，65歲長者及身障者5折\r\n\r\n《演出曲目》\r\n1.Wilhelm Friedemann Bach：Six Flute Duets for two flutes, No.1 in E minor, F. 54\r\n2. A.B. Fürstenau：Rondo Brillant, Op.102 \r\n3.Claude Debussy：Petite Suite for two flutes and piano\r\n4.Eugene Magalif：Silva Fantasy on themes from《Die Csárdásfürstin》by Imre Kálmán\r\n5.Yuko Uebayashi：Town Light for two flutes and piano\r\n6.Anže Rozman：The Two Rivers for two flutes and piano\r\n7.Sang Jin Kim：Moonlight in Manhattan for two flutes and piano\r\n\r\n\r\n', '藝想天開室內樂集', '臺北市中正區中山南路21-1號', '2025-05-26 00:00:00', '2025-05-26 00:00:00', '國家演奏廳', 25.03240487, 121.5198839, '400、600、800', 'https://www.opentix.life/event/1889148153013129217?srsltid=AfmBOooqubvMlpkXgXQ6QiXJWhct_5UJKK_kHTfyNJc_mrQM6JdRpqgY', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025享聽長笛二重奏--時間之河', `description`='【藝想天開室內樂集】為國內知名藝文團體，成立以來積極推廣室內樂教育，2025年再度推出《時間的流》，由長笛家/梁禮昇、王宜韻，鋼琴家/李宜倫共同演出。\r\n本次曲目從古典延伸至當代，帶領聽眾與作曲家進行跨越時空的交流。\r\n\r\n演出地點：國家演奏廳\r\n演出時間：114/05/26-晚 19:30\r\n主辦：藝想天開室內樂集\r\n贊助：博凱·六么·譜集\r\n演出者：長笛｜梁禮昇、王宜韻  鋼琴｜李宜倫 \r\n票價：400、600、800\r\n折扣訊息：學生票及兩廳院之友9折，團體票10張85折，65歲長者及身障者5折\r\n\r\n《演出曲目》\r\n1.Wilhelm Friedemann Bach：Six Flute Duets for two flutes, No.1 in E minor, F. 54\r\n2. A.B. Fürstenau：Rondo Brillant, Op.102 \r\n3.Claude Debussy：Petite Suite for two flutes and piano\r\n4.Eugene Magalif：Silva Fantasy on themes from《Die Csárdásfürstin》by Imre Kálmán\r\n5.Yuko Uebayashi：Town Light for two flutes and piano\r\n6.Anže Rozman：The Two Rivers for two flutes and piano\r\n7.Sang Jin Kim：Moonlight in Manhattan for two flutes and piano\r\n\r\n\r\n', `organizer`='藝想天開室內樂集', `address`='臺北市中正區中山南路21-1號', `start_date`='2025-05-26 00:00:00', `end_date`='2025-05-26 00:00:00', `location`='國家演奏廳', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='400、600、800', `source_url`='https://www.opentix.life/event/1889148153013129217?srsltid=AfmBOooqubvMlpkXgXQ6QiXJWhct_5UJKK_kHTfyNJc_mrQM6JdRpqgY', `image_url`='[]';
