INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c03a26b32419285b71df', '跑步好好，國館RUN起來', '跑者與義工同步報名中: https://bit.ly/41O5YZR\n\n活動日期：2025年5月1日（星期四）\n活動時間：14：30至18：30\n活動地點：中山文化園區映池\n活動內容：繞行映池連續跑54分鐘，跑速自行決定。\n\n \n\n過程即是目的，每一步都是第一步。\n\n沒有競爭與比較，延續愛與希望，為世界祈福 \n\n \n\n全國第一場在國立國父紀念館舉辦的「跑步好好，國館RUN起來」，定於2025年5月1日下午4點，環繞國館映池，暖身開跑，預計可接受600位(18歲至70歲)民眾免費報名。主辦單位法鼓山世界青年會與國館還會提供路跑者，限量版馬拉松純棉緹花毛巾等結緣品。\n\n \n\n「過程即是目的；每一步都是第一步。」法鼓山世界青年會和國館聯合舉辦這場用心體驗、不分名次，全程沒有與他人、與自己競爭和比較的路跑活動，主要是希望民眾延續心中的愛與希望，透過單純喜愛的運動，用生活禪的方法來感受到清楚、放鬆的自在喜悅，並為世界祈福。\n\n \n\n至於為何要跑步54分鐘？法青會說明，法鼓山創辦人  聖嚴法師為倡導淨化人心與社會的「心靈環保」，因此提出四安、四它、四要、四感、四福的「心五四運動」，其中如「面對它、接受它、處理它、放下它」，都是大家耳熟能詳的安心之道；而「心五四」也是全球人類解決困境、增進福祉的生活方式。\n\n \n\n ', '國立國父紀念館', '110  臺北市信義區仁愛路四段505號', '2025-05-01 00:00:00', '2025-05-01 00:00:00', '中山文化園區映池全區', 25.0396974, 121.5603729, '無資料', 'https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=51048', '[]') ON DUPLICATE KEY UPDATE `activity_name`='跑步好好，國館RUN起來', `description`='跑者與義工同步報名中: https://bit.ly/41O5YZR\n\n活動日期：2025年5月1日（星期四）\n活動時間：14：30至18：30\n活動地點：中山文化園區映池\n活動內容：繞行映池連續跑54分鐘，跑速自行決定。\n\n \n\n過程即是目的，每一步都是第一步。\n\n沒有競爭與比較，延續愛與希望，為世界祈福 \n\n \n\n全國第一場在國立國父紀念館舉辦的「跑步好好，國館RUN起來」，定於2025年5月1日下午4點，環繞國館映池，暖身開跑，預計可接受600位(18歲至70歲)民眾免費報名。主辦單位法鼓山世界青年會與國館還會提供路跑者，限量版馬拉松純棉緹花毛巾等結緣品。\n\n \n\n「過程即是目的；每一步都是第一步。」法鼓山世界青年會和國館聯合舉辦這場用心體驗、不分名次，全程沒有與他人、與自己競爭和比較的路跑活動，主要是希望民眾延續心中的愛與希望，透過單純喜愛的運動，用生活禪的方法來感受到清楚、放鬆的自在喜悅，並為世界祈福。\n\n \n\n至於為何要跑步54分鐘？法青會說明，法鼓山創辦人  聖嚴法師為倡導淨化人心與社會的「心靈環保」，因此提出四安、四它、四要、四感、四福的「心五四運動」，其中如「面對它、接受它、處理它、放下它」，都是大家耳熟能詳的安心之道；而「心五四」也是全球人類解決困境、增進福祉的生活方式。\n\n \n\n ', `organizer`='國立國父紀念館', `address`='110  臺北市信義區仁愛路四段505號', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-01 00:00:00', `location`='中山文化園區映池全區', `latitude`=25.0396974, `longitude`=121.5603729, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/YATSEN/Detail.init.ctr?actId=51048', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0b326b32419285b71e1', '東勢國中「繪」心「藝」笑學生作品展', '本次展覽集結了學生們的藝術創意與心血，展出作品涵蓋書法、水彩、版畫、色鉛筆等多元素材，每一幅作品都展現出獨特的風格與創意！\r\n\r\n', '臺中市立東勢國民中學', '臺中市東勢區豐勢路518號', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館東勢分館', 24.24952637, 120.8401401, '無資料', 'https://reurl.cc/V0kxdb', '[]') ON DUPLICATE KEY UPDATE `activity_name`='東勢國中「繪」心「藝」笑學生作品展', `description`='本次展覽集結了學生們的藝術創意與心血，展出作品涵蓋書法、水彩、版畫、色鉛筆等多元素材，每一幅作品都展現出獨特的風格與創意！\r\n\r\n', `organizer`='臺中市立東勢國民中學', `address`='臺中市東勢區豐勢路518號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館東勢分館', `latitude`=24.24952637, `longitude`=120.8401401, `ticket_price`='無資料', `source_url`='https://reurl.cc/V0kxdb', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0b926b32419285b71e4', '《Soft Murmurs 溫柔呢喃》女性藝術家聯展 ', '大雋藝術誠摯邀請您參加2025年度首檔展覽《Soft Murmurs 溫柔呢喃》，此次展覽特別呈現四位卓越女性藝術家的油畫及壓克力作品——Laura Burke、Fabienne Meyer、Aliya Abs 與 Nada Elkalaawy。「溫柔呢喃」象徵女性的聲音雖然輕柔，卻能持續迴盪，帶來深刻的影響。\r\n這場展覽就像一場溫柔而深遠的對話，她們以各具風格的創作語言，深刻探討女性如何透過空間、身份與情感詮釋自我經驗與生命敘事。\r\n\r\n展覽將於2025年3月1日至4月20日盛大開展，邀請您踏入這場視覺與情感交織的對話，感受藝術如何在日常經驗的細微之處，映照出深層複雜性與情感張力。\r\n\r\n值此新年來臨之際，我們誠邀您共聚一堂，與我們一起在這靜謐與流動的時刻之中尋找生活的詩意，慶賀每一個短暫卻深刻的瞬間，讓心靈在這些轉瞬即逝的美之中共鳴。', '大雋藝術', '臺中市南屯區惠文路489號', '2025-03-01 00:00:00', '2025-04-20 00:00:00', '大雋藝術', 24.14165524, 120.6177379, '無資料', 'https://dajungallery.com/exhibitions_detail.php?id=2257', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《Soft Murmurs 溫柔呢喃》女性藝術家聯展 ', `description`='大雋藝術誠摯邀請您參加2025年度首檔展覽《Soft Murmurs 溫柔呢喃》，此次展覽特別呈現四位卓越女性藝術家的油畫及壓克力作品——Laura Burke、Fabienne Meyer、Aliya Abs 與 Nada Elkalaawy。「溫柔呢喃」象徵女性的聲音雖然輕柔，卻能持續迴盪，帶來深刻的影響。\r\n這場展覽就像一場溫柔而深遠的對話，她們以各具風格的創作語言，深刻探討女性如何透過空間、身份與情感詮釋自我經驗與生命敘事。\r\n\r\n展覽將於2025年3月1日至4月20日盛大開展，邀請您踏入這場視覺與情感交織的對話，感受藝術如何在日常經驗的細微之處，映照出深層複雜性與情感張力。\r\n\r\n值此新年來臨之際，我們誠邀您共聚一堂，與我們一起在這靜謐與流動的時刻之中尋找生活的詩意，慶賀每一個短暫卻深刻的瞬間，讓心靈在這些轉瞬即逝的美之中共鳴。', `organizer`='大雋藝術', `address`='臺中市南屯區惠文路489號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='大雋藝術', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://dajungallery.com/exhibitions_detail.php?id=2257', `image_url`='[]';
