INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0c826b32419285b71f0', '114年新屋社區歌唱研習班', '講師教授國、台、客語流行歌曲演唱技巧，歡迎自由參加。', '桃園市新屋區新屋社區發展協會', '桃園市新屋區', '2025-03-25 00:00:00', '2025-09-09 00:00:00', '新屋區（桃園市）=', 24.97280352, 121.067758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年新屋社區歌唱研習班', `description`='講師教授國、台、客語流行歌曲演唱技巧，歡迎自由參加。', `organizer`='桃園市新屋區新屋社區發展協會', `address`='桃園市新屋區', `start_date`='2025-03-25 00:00:00', `end_date`='2025-09-09 00:00:00', `location`='新屋區（桃園市）=', `latitude`=24.97280352, `longitude`=121.067758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0d426b32419285b71f4', '材創系_陸佳暉老師個展【紅月亮 Unusua】', '紅月亮 Unusual- \r\n某一天的晚上，車子因等紅燈而停下來，片刻間抬頭望向遠方看見月亮竟是紅色的，片刻被車後的喇叭聲催促，一腳踩油門上路，匆忙之間我意識到了正在開車的我與那個被紅月亮吸引的我-從異象中覺知生命的無常。\r\n以傳統藺草編織工藝應用的技術 編織不屬於為生活器皿造設的靜物 使之形成與自然環境相對應的介面, 自然中的光線在其中照射出的影子為其介面的邊境與靜物之間形成了一個尚未被定義的「非自然流域」。\r\n作品透過傳統手工的編織特徵 賦予對其固著的手工傳統期待以外的創作路徑,運用編織邏輯所形成的視覺溫度 當下使人能專注的感受到自然無時不刻的包容，卻極其微弱的存在。\r\n', '國立臺南藝術大學', '臺中市南區', '2025-02-08 00:00:00', '2025-04-26 00:00:00', '南區（臺中市）=', 24.12114107, 120.6646178, '無資料', 'https://reurl.cc/8DyQ7b', '[]') ON DUPLICATE KEY UPDATE `activity_name`='材創系_陸佳暉老師個展【紅月亮 Unusua】', `description`='紅月亮 Unusual- \r\n某一天的晚上，車子因等紅燈而停下來，片刻間抬頭望向遠方看見月亮竟是紅色的，片刻被車後的喇叭聲催促，一腳踩油門上路，匆忙之間我意識到了正在開車的我與那個被紅月亮吸引的我-從異象中覺知生命的無常。\r\n以傳統藺草編織工藝應用的技術 編織不屬於為生活器皿造設的靜物 使之形成與自然環境相對應的介面, 自然中的光線在其中照射出的影子為其介面的邊境與靜物之間形成了一個尚未被定義的「非自然流域」。\r\n作品透過傳統手工的編織特徵 賦予對其固著的手工傳統期待以外的創作路徑,運用編織邏輯所形成的視覺溫度 當下使人能專注的感受到自然無時不刻的包容，卻極其微弱的存在。\r\n', `organizer`='國立臺南藝術大學', `address`='臺中市南區', `start_date`='2025-02-08 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='南區（臺中市）=', `latitude`=24.12114107, `longitude`=120.6646178, `ticket_price`='無資料', `source_url`='https://reurl.cc/8DyQ7b', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0d426b32419285b71f5', 'Shift', 'Tessar Lo作為加拿大籍印尼華裔藝術家，其創作展現多元文化背景中的持續對話，更擅於拆解與重組文化符號。本次展出的作品，透過開放的態度與多元媒材，對與自身相關的元素進行解構與重構，探索存在、時間與物理，以及形而上之間的交互作用。\r\n\r\n日本藝術家小池一馬本次展出數件雕塑與繪畫作品，其創作圍繞「虛構的古代文物」，透過神話與歷史記憶的交錯，探索時間與文化的構成。\r\n\r\n臺灣藝術家廖以歆擅長以直覺性的筆觸與畫布進行對話，以抽象的語彙詮釋生命經驗，回應社會秩序與混亂間的矛盾共存。她的作品深受哲學、心理學與文學的影響，並延伸至潛意識與夢境的探索。\r\n\r\n大河美術期望透過《Shift》，讓三位藝術家藉由各自獨特的創作語言，呈現人類在時間與空間中探索自我與世界的複雜性，並將視覺藝術作為思考和表達的橋樑，帶領觀者進入無限的想像空間。在全球化與文化交融加速的今日，展覽呈現身份與環境的流動，促使觀眾思考身份與變遷的動態本質，誠摯邀請各位一同來到現場對話漂流，體驗一場橫跨文化、歷史與當代語境的深刻旅程。', '大河美術有限公司', '臺中市南屯區大業路281號', '2025-03-15 00:00:00', '2025-04-26 00:00:00', '大河美術 ', 24.14165524, 120.6177379, '無資料', 'https://www.facebook.com/share/p/15MqCegzVv/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Shift', `description`='Tessar Lo作為加拿大籍印尼華裔藝術家，其創作展現多元文化背景中的持續對話，更擅於拆解與重組文化符號。本次展出的作品，透過開放的態度與多元媒材，對與自身相關的元素進行解構與重構，探索存在、時間與物理，以及形而上之間的交互作用。\r\n\r\n日本藝術家小池一馬本次展出數件雕塑與繪畫作品，其創作圍繞「虛構的古代文物」，透過神話與歷史記憶的交錯，探索時間與文化的構成。\r\n\r\n臺灣藝術家廖以歆擅長以直覺性的筆觸與畫布進行對話，以抽象的語彙詮釋生命經驗，回應社會秩序與混亂間的矛盾共存。她的作品深受哲學、心理學與文學的影響，並延伸至潛意識與夢境的探索。\r\n\r\n大河美術期望透過《Shift》，讓三位藝術家藉由各自獨特的創作語言，呈現人類在時間與空間中探索自我與世界的複雜性，並將視覺藝術作為思考和表達的橋樑，帶領觀者進入無限的想像空間。在全球化與文化交融加速的今日，展覽呈現身份與環境的流動，促使觀眾思考身份與變遷的動態本質，誠摯邀請各位一同來到現場對話漂流，體驗一場橫跨文化、歷史與當代語境的深刻旅程。', `organizer`='大河美術有限公司', `address`='臺中市南屯區大業路281號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='大河美術 ', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/15MqCegzVv/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0df26b32419285b71f9', '「迢迢Endless Road」聯展', '特別向財團法人榮嘉文化藝術基金會借來臺灣重要藝術家吳昊、卓有瑞、許雨仁的四件重要作品，得以加深觀者如置身近郊山林的真實感與不經意偶遇的景象或想像，另一方面，也向桃園市立美術館借出典藏佳作─劉鳳鴒〈其後I〉、〈其後II〉，橫向繡縫的走線，疊合父親書寫字跡，隱約透露彼此文字交流過程中情感流動的堅實力量；同時邀請深具獨立創作思維與深刻刻劃生命脈動的藝術家王午、施力嘉、陳芷筠、劉鳳鴒(另外兩件作品)共同展出，由衷感謝中央大學藝文中心提供優質場地，借展單位和四位藝術家提供真誠與動人的精采作品，以及向上建設公司的熱情贊助，得以豐富本展。', '國家電影及視聽文化中心', '桃園市中壢區中大路300號', '2025-03-25 00:00:00', '2025-04-26 00:00:00', '國立中央大學', 24.96842, 121.1956658, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「迢迢Endless Road」聯展', `description`='特別向財團法人榮嘉文化藝術基金會借來臺灣重要藝術家吳昊、卓有瑞、許雨仁的四件重要作品，得以加深觀者如置身近郊山林的真實感與不經意偶遇的景象或想像，另一方面，也向桃園市立美術館借出典藏佳作─劉鳳鴒〈其後I〉、〈其後II〉，橫向繡縫的走線，疊合父親書寫字跡，隱約透露彼此文字交流過程中情感流動的堅實力量；同時邀請深具獨立創作思維與深刻刻劃生命脈動的藝術家王午、施力嘉、陳芷筠、劉鳳鴒(另外兩件作品)共同展出，由衷感謝中央大學藝文中心提供優質場地，借展單位和四位藝術家提供真誠與動人的精采作品，以及向上建設公司的熱情贊助，得以豐富本展。', `organizer`='國家電影及視聽文化中心', `address`='桃園市中壢區中大路300號', `start_date`='2025-03-25 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='國立中央大學', `latitude`=24.96842, `longitude`=121.1956658, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0e526b32419285b71ff', '西區長青學苑「彩遊西區」 (水彩及粉蠟筆班、色鉛筆班)學員作品聯展', '臺中市西區長青學苑服務設籍本市 55 歲以上之市民，透過開設多元課程讓長輩持續學習，『活到老、學到老』！本次展覽以「彩遊西區」為主題的水彩及粉蠟筆、色鉛筆作品，歡迎大家有空來走走!', '臺中市西區戶政事務所', '臺中市西區', '2025-03-17 00:00:00', '2025-05-19 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://www.hwest.taichung.gov.tw/1597466/1597554/1597573/3626195/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='西區長青學苑「彩遊西區」 (水彩及粉蠟筆班、色鉛筆班)學員作品聯展', `description`='臺中市西區長青學苑服務設籍本市 55 歲以上之市民，透過開設多元課程讓長輩持續學習，『活到老、學到老』！本次展覽以「彩遊西區」為主題的水彩及粉蠟筆、色鉛筆作品，歡迎大家有空來走走!', `organizer`='臺中市西區戶政事務所', `address`='臺中市西區', `start_date`='2025-03-17 00:00:00', `end_date`='2025-05-19 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.hwest.taichung.gov.tw/1597466/1597554/1597573/3626195/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0e626b32419285b7200', '展覽-拾．藝:廖皓婷西畫個展', '本次展覽作品為畫者喜歡用鮮艷的色彩渲染出對生活的態度、對記憶的珍藏，不論是風光旖旎的山林、名為日常的街景與純真孩童的描繪等，藉由感性承載著理性的情感來展現出作品不同的樣貌。\r\n\r\n\r\n', '臺中市立圖書館', '臺中市神岡區中山路1460號', '2025-03-01 00:00:00', '2025-04-24 00:00:00', '臺中市立圖書館神岡分館', 24.26568008, 120.6733321, '無資料', 'https://www.facebook.com/photo?fbid=1037959151710457&set=pcb.1037959265043779', '[]') ON DUPLICATE KEY UPDATE `activity_name`='展覽-拾．藝:廖皓婷西畫個展', `description`='本次展覽作品為畫者喜歡用鮮艷的色彩渲染出對生活的態度、對記憶的珍藏，不論是風光旖旎的山林、名為日常的街景與純真孩童的描繪等，藉由感性承載著理性的情感來展現出作品不同的樣貌。\r\n\r\n\r\n', `organizer`='臺中市立圖書館', `address`='臺中市神岡區中山路1460號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-24 00:00:00', `location`='臺中市立圖書館神岡分館', `latitude`=24.26568008, `longitude`=120.6733321, `ticket_price`='無資料', `source_url`='https://www.facebook.com/photo?fbid=1037959151710457&set=pcb.1037959265043779', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0e726b32419285b7206', '溪西分館_解放烏克的療癒之旅-初學者的基礎研習班', '烏克麗麗要開課囉~~~!🥳\r\n🎶烏克麗麗是來自夏威夷的四弦琴，外型酷似吉他。由於它的小巧可愛，攜帶方便和容易上手的特質，是號稱全世界最簡單的彈唱樂器今年夏天，就讓我們一起進入烏克麗麗的音樂世界吧！🎼\r\n📣活動名稱：解放烏克的療癒之旅-初學者的基礎研習班\r\n📣主辦單位：臺中市立圖書館溪西分館。\r\n📣活動時間：114年4月12日起至114年5月10日止，每週六14:00-16:00。每次上課為2小時，共10次課程。\r\n📣活動地點：臺中市立圖書館溪西分館3樓多功能活動室\r\n(溪西分館地址：407台中市西屯區福玄路1號)\r\n📣活動對象：國中以上之一般民眾，共30位名額。\r\n📣報名時間：114年3月15日起至額滿為止。\r\n📣授課講師：徐維廷老師，現任西班牙音樂中心負責人。\r\n📣報名費用：新臺幣 500 元。（請備妥整數）\r\n📣自備教材：為利課程進行，請學員自備烏克麗麗。🎵\r\n🔺(推薦MAHALO、aNueNue、Okana等都可以，建議購買2000元左右或以上的烏克麗麗，1000元以內的彩琴較不建議購買，以避免影響學習效果。)\r\n📣報名方式：開放報名後請至臺中市立圖書館溪西分館索取報名表或線上下載報名表，填妥後至溪西分館1樓服務臺報名，即完成報名手續(名額有限，額滿為止)。\r\n📣詳細課程介紹及報名表簡章請參閱連結→ https://reurl.cc/ZZRY3Q', '臺中市立圖書館西屯溪西分館', '臺中市西屯區臺中市西屯區福玄路1號', '2025-04-12 00:00:00', '2025-05-10 00:00:00', '臺中市立圖書館西屯溪西分館', 24.18308895, 120.6270131, '全票+500', 'https://reurl.cc/9DoMYd', '[]') ON DUPLICATE KEY UPDATE `activity_name`='溪西分館_解放烏克的療癒之旅-初學者的基礎研習班', `description`='烏克麗麗要開課囉~~~!🥳\r\n🎶烏克麗麗是來自夏威夷的四弦琴，外型酷似吉他。由於它的小巧可愛，攜帶方便和容易上手的特質，是號稱全世界最簡單的彈唱樂器今年夏天，就讓我們一起進入烏克麗麗的音樂世界吧！🎼\r\n📣活動名稱：解放烏克的療癒之旅-初學者的基礎研習班\r\n📣主辦單位：臺中市立圖書館溪西分館。\r\n📣活動時間：114年4月12日起至114年5月10日止，每週六14:00-16:00。每次上課為2小時，共10次課程。\r\n📣活動地點：臺中市立圖書館溪西分館3樓多功能活動室\r\n(溪西分館地址：407台中市西屯區福玄路1號)\r\n📣活動對象：國中以上之一般民眾，共30位名額。\r\n📣報名時間：114年3月15日起至額滿為止。\r\n📣授課講師：徐維廷老師，現任西班牙音樂中心負責人。\r\n📣報名費用：新臺幣 500 元。（請備妥整數）\r\n📣自備教材：為利課程進行，請學員自備烏克麗麗。🎵\r\n🔺(推薦MAHALO、aNueNue、Okana等都可以，建議購買2000元左右或以上的烏克麗麗，1000元以內的彩琴較不建議購買，以避免影響學習效果。)\r\n📣報名方式：開放報名後請至臺中市立圖書館溪西分館索取報名表或線上下載報名表，填妥後至溪西分館1樓服務臺報名，即完成報名手續(名額有限，額滿為止)。\r\n📣詳細課程介紹及報名表簡章請參閱連結→ https://reurl.cc/ZZRY3Q', `organizer`='臺中市立圖書館西屯溪西分館', `address`='臺中市西屯區臺中市西屯區福玄路1號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='臺中市立圖書館西屯溪西分館', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='全票+500', `source_url`='https://reurl.cc/9DoMYd', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0ea26b32419285b720a', '澄觀影趣-蔡岳霖水彩個展', '  「澄觀影趣-蔡岳霖水彩個展」訂於2025年4月1日至4月25日（週一至週五）AM9:00~PM12:00/PM13:30~PM17:00在財團法人英才文教基金會全球藝術中心（台中市西屯區府會園道179號4樓）展出，開幕導覽訂於4月2日（週三）下午2:30舉行，誠摯邀請愛好藝術的朋友蒞臨參觀指教。\r\n\r\n   蔡岳霖出生在台南將軍鄉，臺灣藝術大學美術系、高雄師範大學美術研究所畢業，擅長水彩創作，曾任教高雄師範大學美術系，現為專職畫家。他認為藝術源於生活而超越生活，繪畫主題的探尋、思維的歸納，如何致力於個人的創造性，強化真實而多元的現代化面貌與土地意識，進而呈顯「美學—社會—時代」的訊息是相當有意義的。\r\n\r\n    蔡岳霖喜愛旅遊，追尋台灣各處自然景觀與人文風土。他常用相機拍攝記錄或現場寫生，創作時很少打草稿，喜歡水彩透明感及簡潔的感受，不喜歡加入太多媒材，只用修飾澱粉或阿拉伯膠等媒合劑來探索水彩變化，達到他所追求即時情感的烙印，希望作品能夠在1周左右階段性完成，因為如果當下情感受到其他不同的情感介入時，作品就沒辦法完整呈現他所想表達的感動。\r\n\r\n    蔡岳霖老師曾在國內外舉辦過二十多次個展，獲獎無數次。他指導的學生在藝術界有傑出表現者無以計數，是南部盛名藝術家。他作品中天空的藍不是歐洲的天空，也不是美洲的天空，是屬於北緯23.5度獨有的色溫，畫面中的綠是感受到的在地野草與堅韌的生命力，描繪的人、事、地、物自然地在指縫間宣洩，讓平凡的日常、城市的角落裡彼此疏離的心，更緊密地連結在一起。\r\n    \r\n    歡迎對藝術有興趣的朋友，前來感受不同氛圍的藝術饗宴。\r\n', '財團法人英才文教基金會', '臺中市西屯區府會園道179號4樓', '2025-04-01 00:00:00', '2025-04-25 00:00:00', '財團法人英才文教基金會全球藝術中心', 24.1604928, 120.6455336, '無資料', 'https://reurl.cc/QY7p42', '[]') ON DUPLICATE KEY UPDATE `activity_name`='澄觀影趣-蔡岳霖水彩個展', `description`='  「澄觀影趣-蔡岳霖水彩個展」訂於2025年4月1日至4月25日（週一至週五）AM9:00~PM12:00/PM13:30~PM17:00在財團法人英才文教基金會全球藝術中心（台中市西屯區府會園道179號4樓）展出，開幕導覽訂於4月2日（週三）下午2:30舉行，誠摯邀請愛好藝術的朋友蒞臨參觀指教。\r\n\r\n   蔡岳霖出生在台南將軍鄉，臺灣藝術大學美術系、高雄師範大學美術研究所畢業，擅長水彩創作，曾任教高雄師範大學美術系，現為專職畫家。他認為藝術源於生活而超越生活，繪畫主題的探尋、思維的歸納，如何致力於個人的創造性，強化真實而多元的現代化面貌與土地意識，進而呈顯「美學—社會—時代」的訊息是相當有意義的。\r\n\r\n    蔡岳霖喜愛旅遊，追尋台灣各處自然景觀與人文風土。他常用相機拍攝記錄或現場寫生，創作時很少打草稿，喜歡水彩透明感及簡潔的感受，不喜歡加入太多媒材，只用修飾澱粉或阿拉伯膠等媒合劑來探索水彩變化，達到他所追求即時情感的烙印，希望作品能夠在1周左右階段性完成，因為如果當下情感受到其他不同的情感介入時，作品就沒辦法完整呈現他所想表達的感動。\r\n\r\n    蔡岳霖老師曾在國內外舉辦過二十多次個展，獲獎無數次。他指導的學生在藝術界有傑出表現者無以計數，是南部盛名藝術家。他作品中天空的藍不是歐洲的天空，也不是美洲的天空，是屬於北緯23.5度獨有的色溫，畫面中的綠是感受到的在地野草與堅韌的生命力，描繪的人、事、地、物自然地在指縫間宣洩，讓平凡的日常、城市的角落裡彼此疏離的心，更緊密地連結在一起。\r\n    \r\n    歡迎對藝術有興趣的朋友，前來感受不同氛圍的藝術饗宴。\r\n', `organizer`='財團法人英才文教基金會', `address`='臺中市西屯區府會園道179號4樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='財團法人英才文教基金會全球藝術中心', `latitude`=24.1604928, `longitude`=120.6455336, `ticket_price`='無資料', `source_url`='https://reurl.cc/QY7p42', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0ea26b32419285b720c', '臺中市立圖書館東勢分館-4月主題書展', '【園藝小宇宙：從盆栽到大地的綠色旅程】書展\r\n展出館藏特色園藝書籍\r\n【書海領航員】書展\r\n展出青少年相關書籍\r\n【藝術大驚奇】書展\r\n展出藝術相關書籍\r\n【咖波帶你遊中市圖】特色書展\r\n配合中市圖展出特色書籍\r\n【每月新到圖書】書展\r\n展出新到圖書', '臺中市立圖書館東勢分館', '臺中市東勢區豐勢路518號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館東勢分館', 24.24952637, 120.8401401, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市立圖書館東勢分館-4月主題書展', `description`='【園藝小宇宙：從盆栽到大地的綠色旅程】書展\r\n展出館藏特色園藝書籍\r\n【書海領航員】書展\r\n展出青少年相關書籍\r\n【藝術大驚奇】書展\r\n展出藝術相關書籍\r\n【咖波帶你遊中市圖】特色書展\r\n配合中市圖展出特色書籍\r\n【每月新到圖書】書展\r\n展出新到圖書', `organizer`='臺中市立圖書館東勢分館', `address`='臺中市東勢區豐勢路518號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館東勢分館', `latitude`=24.24952637, `longitude`=120.8401401, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0ea26b32419285b720d', '短歌～呂承祐2025短笛獨奏會3', '演出曲目:\r\nAmanda Harberg:\r\nSonata for Piccolo and Piano (2018)\r\n哈柏格:奏鳴曲給短笛與鋼琴\r\nEric Ewazen:\r\nOn Wings of Songs (2010)\r\n伊瓦森:乘著歌聲的翅膀\r\nFrancis Poulenc:\r\nOboe Sonata, FP 185 (1962)\r\n浦朗克:雙簧管奏鳴曲\r\n馬水龍:梆笛協奏曲(1981)\r\nSaariaho:\r\nDolce Tormento for Solo Piccolo (2004)\r\n薩里亞后:《甜蜜的折磨》給短笛獨奏', 'Legato樂聚', '臺中市西屯區惠來路二段101號', '2025-05-24 00:00:00', '2025-05-24 00:00:00', '臺中國家歌劇院', 24.1630875, 120.6404343, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='短歌～呂承祐2025短笛獨奏會3', `description`='演出曲目:\r\nAmanda Harberg:\r\nSonata for Piccolo and Piano (2018)\r\n哈柏格:奏鳴曲給短笛與鋼琴\r\nEric Ewazen:\r\nOn Wings of Songs (2010)\r\n伊瓦森:乘著歌聲的翅膀\r\nFrancis Poulenc:\r\nOboe Sonata, FP 185 (1962)\r\n浦朗克:雙簧管奏鳴曲\r\n馬水龍:梆笛協奏曲(1981)\r\nSaariaho:\r\nDolce Tormento for Solo Piccolo (2004)\r\n薩里亞后:《甜蜜的折磨》給短笛獨奏', `organizer`='Legato樂聚', `address`='臺中市西屯區惠來路二段101號', `start_date`='2025-05-24 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='臺中國家歌劇院', `latitude`=24.1630875, `longitude`=120.6404343, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0ea26b32419285b720e', '客家文化講座-兒童節慶活動', '邀請客語薪傳師廖玉霞老師到館講解客家俗諺的真正意涵和先人智慧及相關故事典故，進而能融會貫通並正確應用到日常生活之中。\r\n至本館服務台或來電（04）25870006報名參加', '臺中市立圖書館東勢分館', '臺中市東勢區豐勢路518號', '2025-04-11 00:00:00', '2025-04-25 00:00:00', '臺中市立圖書館東勢分館', 24.24952637, 120.8401401, '無資料', 'https://reurl.cc/j97852', '[]') ON DUPLICATE KEY UPDATE `activity_name`='客家文化講座-兒童節慶活動', `description`='邀請客語薪傳師廖玉霞老師到館講解客家俗諺的真正意涵和先人智慧及相關故事典故，進而能融會貫通並正確應用到日常生活之中。\r\n至本館服務台或來電（04）25870006報名參加', `organizer`='臺中市立圖書館東勢分館', `address`='臺中市東勢區豐勢路518號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='臺中市立圖書館東勢分館', `latitude`=24.24952637, `longitude`=120.8401401, `ticket_price`='無資料', `source_url`='https://reurl.cc/j97852', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0ea26b32419285b720f', '瀟灑情俠傳之千里查恩俠', '《瀟灑情俠傳之千里查恩俠》\r\n天下武林風雲將起，西北派魔頭之一神祕無名隱策動西域邪教人士，計畫翻動天下、顛倒乾坤，奪取天下大權。正巧武林中有四名劍客各據一方，以劍術聞名，各以才德使人欽服，但西域組成之西北派以蓋地鋪天之勢將進犯中原，四劍行蹤卻不明。因此，中原正派人士所組成的東南派，只得推選瀟灑情俠為東南派盟主，加上劉伯溫等志士為輔，共同對付西北的詭計……\r\n\r\n#臺中市政府文化局\r\n#表演藝術類活動補助', '五洲秋峰園掌中劇團', '臺中市豐原區', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '豐原區（臺中市）=', 24.24990298, 120.7375715, '無資料', 'https://www.culture.taichung.gov.tw/2935231/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='瀟灑情俠傳之千里查恩俠', `description`='《瀟灑情俠傳之千里查恩俠》\r\n天下武林風雲將起，西北派魔頭之一神祕無名隱策動西域邪教人士，計畫翻動天下、顛倒乾坤，奪取天下大權。正巧武林中有四名劍客各據一方，以劍術聞名，各以才德使人欽服，但西域組成之西北派以蓋地鋪天之勢將進犯中原，四劍行蹤卻不明。因此，中原正派人士所組成的東南派，只得推選瀟灑情俠為東南派盟主，加上劉伯溫等志士為輔，共同對付西北的詭計……\r\n\r\n#臺中市政府文化局\r\n#表演藝術類活動補助', `organizer`='五洲秋峰園掌中劇團', `address`='臺中市豐原區', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='豐原區（臺中市）=', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.culture.taichung.gov.tw/2935231/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0ea26b32419285b7210', '鍬敲踏著春日步道 (La Feria de Abril)', '春日暖暖，在鍬形蟲與甲蟲的家園，是個藝術園區的美術園道。踏入步道，佛拉明哥的敲踏聲，人潮跟著olé 聲進入市集，是春天來臨的儀式吧？吉他、歌聲踩踏聲，繽紛美麗的舞蹈與鍬形甲蟲的花園，正在舉辦迎春會。\r\n\r\n#臺中市政府文化局\r\n#表演藝術類活動補助', '迷火佛拉明哥舞坊', '臺中市西區', '2025-04-27 00:00:00', '2025-04-27 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://www.culture.taichung.gov.tw/2935225/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鍬敲踏著春日步道 (La Feria de Abril)', `description`='春日暖暖，在鍬形蟲與甲蟲的家園，是個藝術園區的美術園道。踏入步道，佛拉明哥的敲踏聲，人潮跟著olé 聲進入市集，是春天來臨的儀式吧？吉他、歌聲踩踏聲，繽紛美麗的舞蹈與鍬形甲蟲的花園，正在舉辦迎春會。\r\n\r\n#臺中市政府文化局\r\n#表演藝術類活動補助', `organizer`='迷火佛拉明哥舞坊', `address`='臺中市西區', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.culture.taichung.gov.tw/2935225/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0ec26b32419285b7218', '【 Le jardin d’Isabelle 】 伊莎貝兒的花園', '以「伊莎貝兒」為主題創作，不只是因為它的音韻動人，更因為它象徵著「上帝的誓言」，彷彿有一種神聖的意志守護著這座秘密花園。這裡的每一朵花，都是靈魂的低語，每一道芬芳，都是故事的呢喃。我在這座花園中漫步，感受時間的流轉，也窺見內心深處的悸動。\r\n\r\n在這次展出的作品中，整體風格因當下的心境而改變，張力也隨情緒波動而有所不同。正如大自然的颳風、下雨或下雪一般，或如同人有喜怒哀樂、恐懼、羞愧等多元情感——這些都是最即刻、最真實的反應。也正是在這樣的創作過程中，我不斷地尋找自我，感受那份「存在」的意義。\r\n\r\n媒材技法，例如：水墨、快速筆觸、壓擠、扭曲…', '社團法人台灣打里摺文化協會', '臺中市南屯區', '2025-03-15 00:00:00', '2025-06-14 00:00:00', '南屯區（臺中市）=', 24.14165524, 120.6177379, '無資料', 'https://www.facebook.com/share/p/1XEz6dXEyv/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【 Le jardin d’Isabelle 】 伊莎貝兒的花園', `description`='以「伊莎貝兒」為主題創作，不只是因為它的音韻動人，更因為它象徵著「上帝的誓言」，彷彿有一種神聖的意志守護著這座秘密花園。這裡的每一朵花，都是靈魂的低語，每一道芬芳，都是故事的呢喃。我在這座花園中漫步，感受時間的流轉，也窺見內心深處的悸動。\r\n\r\n在這次展出的作品中，整體風格因當下的心境而改變，張力也隨情緒波動而有所不同。正如大自然的颳風、下雨或下雪一般，或如同人有喜怒哀樂、恐懼、羞愧等多元情感——這些都是最即刻、最真實的反應。也正是在這樣的創作過程中，我不斷地尋找自我，感受那份「存在」的意義。\r\n\r\n媒材技法，例如：水墨、快速筆觸、壓擠、扭曲…', `organizer`='社團法人台灣打里摺文化協會', `address`='臺中市南屯區', `start_date`='2025-03-15 00:00:00', `end_date`='2025-06-14 00:00:00', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1XEz6dXEyv/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0ee26b32419285b721c', '2025臺中市美術家接力展：空的流動，光的吟遊－曲德華雕塑創作展 創作導覽', '臺中市美術家接力展第266棒接力展藝術家曲德華老師1954年出生，於國立臺灣師範大學美術系求學期間師承現代主義大師李仲生，畢業後負笈法國、澳洲深造，獲取3D視覺藝術碩士學位。學成歸國後致力於藝術教育，曾任教於國立臺中教育大學美術系及東海大學建築系，培育藝術人才無數。今年度獲選臺中市美術家接力展，以「空的流動，光的吟遊」為展覽主題，將20年間作品做一次的呈現。\r\n曲德華老師擅長以不銹鋼網創作幾何立體雕塑，從不同的視角欣賞，可以感受到光影、線條相互交織的層次。鋼網雕塑考驗創作者的耐心和毅力，需經過精密計算、嘗試，並克服媒材本身的剛硬特性，方能塑造出充滿張力與美感的造型。此次接力展將展出曲德華老師三角系列、花系列、葉系列及天梯系列等作品，誠摯地邀請觀者在流動的光影間，感受作品與空間的對話。', '臺中市葫蘆墩文化中心', '臺中市豐原區圓環東路782號', '2025-04-10 00:00:00', '2025-05-03 00:00:00', '臺中市葫蘆墩文化中心', 24.24990298, 120.7375715, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144784,99', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺中市美術家接力展：空的流動，光的吟遊－曲德華雕塑創作展 創作導覽', `description`='臺中市美術家接力展第266棒接力展藝術家曲德華老師1954年出生，於國立臺灣師範大學美術系求學期間師承現代主義大師李仲生，畢業後負笈法國、澳洲深造，獲取3D視覺藝術碩士學位。學成歸國後致力於藝術教育，曾任教於國立臺中教育大學美術系及東海大學建築系，培育藝術人才無數。今年度獲選臺中市美術家接力展，以「空的流動，光的吟遊」為展覽主題，將20年間作品做一次的呈現。\r\n曲德華老師擅長以不銹鋼網創作幾何立體雕塑，從不同的視角欣賞，可以感受到光影、線條相互交織的層次。鋼網雕塑考驗創作者的耐心和毅力，需經過精密計算、嘗試，並克服媒材本身的剛硬特性，方能塑造出充滿張力與美感的造型。此次接力展將展出曲德華老師三角系列、花系列、葉系列及天梯系列等作品，誠摯地邀請觀者在流動的光影間，感受作品與空間的對話。', `organizer`='臺中市葫蘆墩文化中心', `address`='臺中市豐原區圓環東路782號', `start_date`='2025-04-10 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='臺中市葫蘆墩文化中心', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144784,99', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0ee26b32419285b721d', '美麗人生－幸福Sweety油畫班2025創作展', '〈美麗人生〉展出油畫班學員：劉佳音、劉瑞倩、張菁芝、王良方、曾惠君、曹晉芳近年的油畫作品。用畫筆來展現這個美麗世界是本班一直沒變的目標，而不斷的創作就是具體的實踐的方式。此次展覽本班六位學員將近幾年來的繪畫作品展出，不論是南歐浪漫的城區、慵懶的午後庭園，亦或是回想起兒時共乘機車時內心悸動的時刻，用畫筆透過色彩、線條和形狀，賦予日常生活新的視角與生命力來展現這個世界，一種既主觀又獨特的創作過程，都藉由筆下幻化成一道光，在畫布上留下記憶。', '臺中市南屯區公所', '臺中市南屯區', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '南屯區（臺中市）=', 24.14165524, 120.6177379, '無資料', 'https://www.facebook.com/share/p/1YZsPV8S6f/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='美麗人生－幸福Sweety油畫班2025創作展', `description`='〈美麗人生〉展出油畫班學員：劉佳音、劉瑞倩、張菁芝、王良方、曾惠君、曹晉芳近年的油畫作品。用畫筆來展現這個美麗世界是本班一直沒變的目標，而不斷的創作就是具體的實踐的方式。此次展覽本班六位學員將近幾年來的繪畫作品展出，不論是南歐浪漫的城區、慵懶的午後庭園，亦或是回想起兒時共乘機車時內心悸動的時刻，用畫筆透過色彩、線條和形狀，賦予日常生活新的視角與生命力來展現這個世界，一種既主觀又獨特的創作過程，都藉由筆下幻化成一道光，在畫布上留下記憶。', `organizer`='臺中市南屯區公所', `address`='臺中市南屯區', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1YZsPV8S6f/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0ee26b32419285b721e', '大安分館 學生創作繪畫展', '畫畫沒有標準答案，可以天馬行空的畫作，讓小小心靈得到大大的成就感，多幅作品，精彩可期，歡迎前往欣賞。', '臺中市立圖書館大安分館', '臺中市大安區興安路378號', '2025-03-12 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館大安分館', 24.36509555, 120.5914407, '無資料', 'https://www.facebook.com/photo/?fbid=1068719581959499&set=pcb.1068720231959434', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大安分館 學生創作繪畫展', `description`='畫畫沒有標準答案，可以天馬行空的畫作，讓小小心靈得到大大的成就感，多幅作品，精彩可期，歡迎前往欣賞。', `organizer`='臺中市立圖書館大安分館', `address`='臺中市大安區興安路378號', `start_date`='2025-03-12 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館大安分館', `latitude`=24.36509555, `longitude`=120.5914407, `ticket_price`='無資料', `source_url`='https://www.facebook.com/photo/?fbid=1068719581959499&set=pcb.1068720231959434', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0ee26b32419285b721f', 'Echo of Your Soul 秘密集會新歌場 2.0 台中場', '在新作推出之前，回聲將提前帶它們離開錄音室，到現場感受聽眾最直接的回饋。\r\n\r\n半場音樂祭不會唱的秘密集會限定曲目。\r\n\r\n半場新歌，包含數首尚未曝光的全新創作。\r\n\r\n歡迎到現場一同參與回聲新作的誕生。', '回聲樂團 Echo of Your Soul', '臺中市西屯區', '2025-05-04 00:00:00', '2025-05-04 00:00:00', '西屯區（臺中市）=', 24.18308895, 120.6270131, '無資料', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Echo of Your Soul 秘密集會新歌場 2.0 台中場', `description`='在新作推出之前，回聲將提前帶它們離開錄音室，到現場感受聽眾最直接的回饋。\r\n\r\n半場音樂祭不會唱的秘密集會限定曲目。\r\n\r\n半場新歌，包含數首尚未曝光的全新創作。\r\n\r\n歡迎到現場一同參與回聲新作的誕生。', `organizer`='回聲樂團 Echo of Your Soul', `address`='臺中市西屯區', `start_date`='2025-05-04 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='西屯區（臺中市）=', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0ee26b32419285b7220', '微笑唸歌團《樹仔腳聽唸歌》', '本場演出為文化部國家語言發展計畫補助項下之活動，結合農曆節氣、節日、傳說等概念，由微笑唸歌團搬演臺灣民間傳說故事和在地鄉野奇談傳說，用生動活潑的唱詞搬演故事。本場演出選擇發生在文化部文化資產園區，結合2025臺灣唸歌節活動，用民間故事和傳說拼貼取材，加入微笑唸歌團的獨到創意重新詮釋，帶領民眾重溫在樹仔腳下聽唸歌的那段美好回憶。', '臺中市葫蘆墩文化中心', '臺中市南區復興路三段362號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '文化部文化資產園區', 24.1329271, 120.6808935, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144904,3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='微笑唸歌團《樹仔腳聽唸歌》', `description`='本場演出為文化部國家語言發展計畫補助項下之活動，結合農曆節氣、節日、傳說等概念，由微笑唸歌團搬演臺灣民間傳說故事和在地鄉野奇談傳說，用生動活潑的唱詞搬演故事。本場演出選擇發生在文化部文化資產園區，結合2025臺灣唸歌節活動，用民間故事和傳說拼貼取材，加入微笑唸歌團的獨到創意重新詮釋，帶領民眾重溫在樹仔腳下聽唸歌的那段美好回憶。', `organizer`='臺中市葫蘆墩文化中心', `address`='臺中市南區復興路三段362號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='文化部文化資產園區', `latitude`=24.1329271, `longitude`=120.6808935, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144904,3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0ef26b32419285b7221', '綻聲銅管五重奏《銅聲童趣親子音樂會》', '綻聲銅管五重奏在本次演出特別挑選了許多大人小孩都耳熟能詳的經典曲目，從陪伴大家成長的臺灣童謠、令人懷念的卡通主題曲，到廣告歌曲以及改編自音樂劇的電影音樂，應有盡有。我們希望透過銅管的音色與表演，喚起聽眾們的童年記憶，並帶來愉悅的音樂體驗。就讓這些由銅管五重奏編織而成的美好旋律，陪伴各位聽眾一起度過這個充滿歡樂與感動的週末悠閒午後吧！\r\n\r\n綻聲銅管五重奏： 銅管五重奏是由銅管家族樂器中的2支小號、1支法國號、1支長號及1支低音號所組成，這個組合包含了低、中、高的音域，可以吹奏的曲目種類相當多元！不論是古典音樂的優雅、流行音樂的動感，還是爵士音樂的自由節奏，銅管五重奏都能輕鬆詮釋，展現出獨特的音色魅力。這樣的組合不僅在音樂廳表現出色，還適合在戶外、社區活動等多種場合演出。\r\n\r\n∮ 演出曲目\r\n\r\n♫ This Old Man March\r\n♪ 真善美組曲\r\n♭ 台灣民謠組曲\r\n♬哆啦A夢主題曲\r\n♩ 柯南主題曲\r\n♪ 蠟筆小新主題曲\r\n♫ 我推的孩子片頭曲— Idol\r\n\r\n∮ 安可曲：可愛くてごめん', '臺中市葫蘆墩文化中心', '臺中市豐原區圓環東路782號', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '臺中市葫蘆墩文化中心', 24.24990298, 120.7375715, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144946,3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='綻聲銅管五重奏《銅聲童趣親子音樂會》', `description`='綻聲銅管五重奏在本次演出特別挑選了許多大人小孩都耳熟能詳的經典曲目，從陪伴大家成長的臺灣童謠、令人懷念的卡通主題曲，到廣告歌曲以及改編自音樂劇的電影音樂，應有盡有。我們希望透過銅管的音色與表演，喚起聽眾們的童年記憶，並帶來愉悅的音樂體驗。就讓這些由銅管五重奏編織而成的美好旋律，陪伴各位聽眾一起度過這個充滿歡樂與感動的週末悠閒午後吧！\r\n\r\n綻聲銅管五重奏： 銅管五重奏是由銅管家族樂器中的2支小號、1支法國號、1支長號及1支低音號所組成，這個組合包含了低、中、高的音域，可以吹奏的曲目種類相當多元！不論是古典音樂的優雅、流行音樂的動感，還是爵士音樂的自由節奏，銅管五重奏都能輕鬆詮釋，展現出獨特的音色魅力。這樣的組合不僅在音樂廳表現出色，還適合在戶外、社區活動等多種場合演出。\r\n\r\n∮ 演出曲目\r\n\r\n♫ This Old Man March\r\n♪ 真善美組曲\r\n♭ 台灣民謠組曲\r\n♬哆啦A夢主題曲\r\n♩ 柯南主題曲\r\n♪ 蠟筆小新主題曲\r\n♫ 我推的孩子片頭曲— Idol\r\n\r\n∮ 安可曲：可愛くてごめん', `organizer`='臺中市葫蘆墩文化中心', `address`='臺中市豐原區圓環東路782號', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='臺中市葫蘆墩文化中心', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144946,3', `image_url`='[]';
