INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0f026b32419285b7223', '梧棲親子館_故事魔法森林(114年4月份，5場)', '1.本活動為例行性每週三、六上午10:00~11:00\r\n2.加碼場每周日上午10:00~11:00\r\n4/05 金太陽銀太陽\r\n4/06 我家是動物園\r\n4/13 妖怪鬼屋大拍賣\r\n4/26 我喜歡自己\r\n4/30 大嘴鳥快遞公司', '臺中市立圖書館梧棲親子館', '臺中市梧棲區民生街15之77號', '2025-04-05 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館梧棲親子館', 24.251815, 120.533022, '無資料', 'https://reurl.cc/Z47R6W', '[]') ON DUPLICATE KEY UPDATE `activity_name`='梧棲親子館_故事魔法森林(114年4月份，5場)', `description`='1.本活動為例行性每週三、六上午10:00~11:00\r\n2.加碼場每周日上午10:00~11:00\r\n4/05 金太陽銀太陽\r\n4/06 我家是動物園\r\n4/13 妖怪鬼屋大拍賣\r\n4/26 我喜歡自己\r\n4/30 大嘴鳥快遞公司', `organizer`='臺中市立圖書館梧棲親子館', `address`='臺中市梧棲區民生街15之77號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館梧棲親子館', `latitude`=24.251815, `longitude`=120.533022, `ticket_price`='無資料', `source_url`='https://reurl.cc/Z47R6W', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0f026b32419285b7224', '英文繪本故事屋_Fun English Stories(114年4月，2場)', '閱讀是一個文化扎根的工作，英文語言能力不僅是一種溝通工具，更是一扇連接全球的窗戶。\r\n而今英語學習更是國民教育的重要一環，為了有效提升全國人民英語能力，親子館邀集英文老師每月挑選一本英文繪本書，以活潑生動的故事，穿插日常生活中常聽到的對話，也藉由一些道具的操作，讓親子更容易進入狀況並加深小朋友的印象。\r\n讓兒童聽故事學英語兼閱讀遊戲，增強孩子詞彙量和識字能力，並培養帶著走的英文素養力。\r\n\r\n英文故事繪本書：\r\n4/12 Lyvia姊姊：偉大的建築(中文繪本以英語說故事)\r\n4/27 Ayumi姊姊：Outside, inside', '臺中市立圖書館梧棲親子館', '臺中市梧棲區民生街15之77號', '2025-04-12 00:00:00', '2025-04-27 00:00:00', '臺中市立圖書館梧棲親子館', 24.251815, 120.533022, '無資料', 'https://reurl.cc/XAkOoj', '[]') ON DUPLICATE KEY UPDATE `activity_name`='英文繪本故事屋_Fun English Stories(114年4月，2場)', `description`='閱讀是一個文化扎根的工作，英文語言能力不僅是一種溝通工具，更是一扇連接全球的窗戶。\r\n而今英語學習更是國民教育的重要一環，為了有效提升全國人民英語能力，親子館邀集英文老師每月挑選一本英文繪本書，以活潑生動的故事，穿插日常生活中常聽到的對話，也藉由一些道具的操作，讓親子更容易進入狀況並加深小朋友的印象。\r\n讓兒童聽故事學英語兼閱讀遊戲，增強孩子詞彙量和識字能力，並培養帶著走的英文素養力。\r\n\r\n英文故事繪本書：\r\n4/12 Lyvia姊姊：偉大的建築(中文繪本以英語說故事)\r\n4/27 Ayumi姊姊：Outside, inside', `organizer`='臺中市立圖書館梧棲親子館', `address`='臺中市梧棲區民生街15之77號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺中市立圖書館梧棲親子館', `latitude`=24.251815, `longitude`=120.533022, `ticket_price`='無資料', `source_url`='https://reurl.cc/XAkOoj', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0f026b32419285b7225', '梧棲親子館_台語說故事(114年4月份，2場)', '在多元文化交織的台灣，台語 我們的母語，承載著豐富的歷史文化，在逐漸面臨失傳的危機。\r\n讓孩子學習台語，不僅僅是傳承語言，更能開啟他們探索世界的大門，帶來許多意想不到的益處。\r\n透過台語故事，讓孩子接觸台灣傳統的歌謠、故事和習俗，進而學習台灣人的生活智慧和處世哲學，培養對台灣文化的認同感和歸屬感。學習、感受台語文的獨特魅力!\r\n\r\n台語說故事繪本書\r\n4/19 綠豆媽媽：唱家己的歌\r\n4/20 楊焜顯老師：1.那天來的鯨魚、2.那天來的鯨魚回來了、3.那天來的鯨魚在唱歌', '臺中市立圖書館梧棲親子館', '臺中市梧棲區民生街15之77號', '2025-04-19 00:00:00', '2025-04-20 00:00:00', '臺中市立圖書館梧棲親子館', 24.251815, 120.533022, '無資料', 'https://reurl.cc/bWz4X6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='梧棲親子館_台語說故事(114年4月份，2場)', `description`='在多元文化交織的台灣，台語 我們的母語，承載著豐富的歷史文化，在逐漸面臨失傳的危機。\r\n讓孩子學習台語，不僅僅是傳承語言，更能開啟他們探索世界的大門，帶來許多意想不到的益處。\r\n透過台語故事，讓孩子接觸台灣傳統的歌謠、故事和習俗，進而學習台灣人的生活智慧和處世哲學，培養對台灣文化的認同感和歸屬感。學習、感受台語文的獨特魅力!\r\n\r\n台語說故事繪本書\r\n4/19 綠豆媽媽：唱家己的歌\r\n4/20 楊焜顯老師：1.那天來的鯨魚、2.那天來的鯨魚回來了、3.那天來的鯨魚在唱歌', `organizer`='臺中市立圖書館梧棲親子館', `address`='臺中市梧棲區民生街15之77號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺中市立圖書館梧棲親子館', `latitude`=24.251815, `longitude`=120.533022, `ticket_price`='無資料', `source_url`='https://reurl.cc/bWz4X6', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0f026b32419285b7227', '2025臺中兒童藝術節－藝文場館演出', '文化局舉辦「2025臺中兒童藝術節」，結合經典IP巴布豆「BOBDOG」帶著小朋友一起到夢之島同樂！\r\n4/3～4/5兒童節連假期間在文心森林公園舉辦「2025臺中兒童藝術節」，現場除了有大型巴布豆氣偶，還邀請12團全國優秀演藝團隊，帶來「製夢劇場」戶外匯演與9場街頭藝人演出、13場「夢的派對」親子體驗及好吃好玩的「夢禮市集」，4月周末則於屯區藝文中心有5場藝文場館售票演出，如阿甯咕劇團、臺灣青年管樂團及創造焦點等。', '臺中市政府文化局', '臺中市太平區大興路201號', '2025-04-13 00:00:00', '2025-04-27 00:00:00', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺中兒童藝術節－藝文場館演出', `description`='文化局舉辦「2025臺中兒童藝術節」，結合經典IP巴布豆「BOBDOG」帶著小朋友一起到夢之島同樂！\r\n4/3～4/5兒童節連假期間在文心森林公園舉辦「2025臺中兒童藝術節」，現場除了有大型巴布豆氣偶，還邀請12團全國優秀演藝團隊，帶來「製夢劇場」戶外匯演與9場街頭藝人演出、13場「夢的派對」親子體驗及好吃好玩的「夢禮市集」，4月周末則於屯區藝文中心有5場藝文場館售票演出，如阿甯咕劇團、臺灣青年管樂團及創造焦點等。', `organizer`='臺中市政府文化局', `address`='臺中市太平區大興路201號', `start_date`='2025-04-13 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0f026b32419285b7228', '安妮塔故事劇場《洛米與時間守護者》', '【發光故事劇場】*現場免費參加*\r\n「做事拖拖拉拉的洛米，常常因為沒寫作業而被媽媽罵。有一天他撿到了一張前往時間王國的車票。洛米在這趟旅程中會發生什麼事呢？」安妮塔老師擅於利用聲音來傳遞訊息中的情感，搭配發光故事屋與新奇有趣的道具，和安妮塔老師一起來場豐富的童話饗宴吧!\r\n\r\n場次時段：\r\n發光故事劇場一共兩場次，分別為10:30、14:00，每場次約30分鐘。\r\n\r\n【加購】主題遊戲及親子手作\r\n人數限制：每場限30名兒童，每位兒童400元(陪同大人不收費)。聽完故事後延續故事內容進行主題遊戲，並和孩子一起完成與故事有關的手作作品帶回家。\r\n\r\n*位置會安排在最前方特別區域\r\n*額外贈送迷你小鬧鐘~真的會響喔！', '臺中市葫蘆墩文化中心', '臺中市豐原區圓環東路782號', '2025-05-17 00:00:00', '2025-05-17 00:00:00', '臺中市葫蘆墩文化中心', 24.24990298, 120.7375715, '無資料', 'https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144945,3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='安妮塔故事劇場《洛米與時間守護者》', `description`='【發光故事劇場】*現場免費參加*\r\n「做事拖拖拉拉的洛米，常常因為沒寫作業而被媽媽罵。有一天他撿到了一張前往時間王國的車票。洛米在這趟旅程中會發生什麼事呢？」安妮塔老師擅於利用聲音來傳遞訊息中的情感，搭配發光故事屋與新奇有趣的道具，和安妮塔老師一起來場豐富的童話饗宴吧!\r\n\r\n場次時段：\r\n發光故事劇場一共兩場次，分別為10:30、14:00，每場次約30分鐘。\r\n\r\n【加購】主題遊戲及親子手作\r\n人數限制：每場限30名兒童，每位兒童400元(陪同大人不收費)。聽完故事後延續故事內容進行主題遊戲，並和孩子一起完成與故事有關的手作作品帶回家。\r\n\r\n*位置會安排在最前方特別區域\r\n*額外贈送迷你小鬧鐘~真的會響喔！', `organizer`='臺中市葫蘆墩文化中心', `address`='臺中市豐原區圓環東路782號', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='臺中市葫蘆墩文化中心', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.huludun.taichung.gov.tw/active/index-1.asp?Parser=99,8,40,,,,144945,3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e1c0f026b32419285b722b', '「端陽舞藝」2025高雄市藝文團體理事長協會 聯展', '高雄市藝文團體理事長協會立案成立於2004年，新加入會員須為高雄市立案之藝文團體現任理事長。為協助政府推展藝術文化，促進國際文化交流，提昇市民藝術水準為本會宗旨。本次展期逢此端午佳節特以「端陽舞藝」為本展主題，作品含西畫、攝影、立體、水墨、書法等五類別作品分享，歡迎市民蒞臨參觀，期提昇市民藝術生活涵養。', '高雄市政府文化局', '高雄市苓雅區001鄰五福一路67號', '2025-05-30 00:00:00', '2025-06-10 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4117', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「端陽舞藝」2025高雄市藝文團體理事長協會 聯展', `description`='高雄市藝文團體理事長協會立案成立於2004年，新加入會員須為高雄市立案之藝文團體現任理事長。為協助政府推展藝術文化，促進國際文化交流，提昇市民藝術水準為本會宗旨。本次展期逢此端午佳節特以「端陽舞藝」為本展主題，作品含西畫、攝影、立體、水墨、書法等五類別作品分享，歡迎市民蒞臨參觀，期提昇市民藝術生活涵養。', `organizer`='高雄市政府文化局', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-05-30 00:00:00', `end_date`='2025-06-10 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5700&IDK=2&EXEC=D&DATA=4117', `image_url`='[]';
