INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e326ed26b32419285b7254', '草木染教師培力工作坊', '課程內容：\n\n\n運用含單寧的植物來萃取染液，用生活周邊易取得植物少許的花、葉來取其型態與色素，尊重植物且延續其生命，利用植物自帶的型體來染製生活所需物品，所有資源循環再利用～\n\n5/17（六）\n\n植物染概論概論、棉布精練、各染法作品解說、認識植物與採集後處理\n無媒染圍巾示範與實作、萃取染液、綁布技法示範與實作\n\n5/18（日）\n染前媒染、染色工程\n染後媒染、後媒染染色工程\n\n5/24（六）\n\n單寧染材萃取、植物採集、鐵媒染圍巾示範與實作\n植物性纖維生態印染示範與實作\n\n5/25（日）\n動物性纖維染前處理與實作\n植物性纖維後加工\n\n\n	課程時間：5/17、5/18、5/24、5/25（週六/週日） 09：00～17：00（4天/28小時）\n	課程地點：工藝中心學員宿舍1樓多功能交誼廳及戶外區域（南投縣草屯鎮中正路573號）\n	招生對象：幼稚園、國小、國中及高級中等學校之教師\n	招收人數：20人(6人開班)\n	報名方式：於4/16（三）下午1點起在【全國教師在職進修資訊網】線上報名。【課程代碼：4971564】\n	錄取方式：為落實工藝校園扎根政策推動所需，主辦單位得保留一半名額供本中心培育之種子教師課程實踐者或具有工藝校園扎根潛力者優先錄取（需回填學習動機以及教學實踐成果，俾利審核），其餘名額則依報名優先順序錄取，錄取名單請至至【全國教師在職進修資訊網】查詢。\n	(提醒:欲爭取實踐者及潛力者優先名額者，仍需至教師網報名喔!)\n	課程費用：學雜費588元、材料費3,000元\n	洽詢專線：049-2334141*312張小姐', '國立台灣工藝研究發展中心', '542  南投縣草屯鎮中正路573號', '2025-05-17 00:00:00', '2025-05-25 00:00:00', '國立臺灣工藝研究發展中心|學員宿舍1樓多功能交誼廳', 23.9797002, 120.69095, '無資料', 'https://event.culture.tw/mocweb/reg/NTCRI/Detail.init.ctr?actId=50166', '[]') ON DUPLICATE KEY UPDATE `activity_name`='草木染教師培力工作坊', `description`='課程內容：\n\n\n運用含單寧的植物來萃取染液，用生活周邊易取得植物少許的花、葉來取其型態與色素，尊重植物且延續其生命，利用植物自帶的型體來染製生活所需物品，所有資源循環再利用～\n\n5/17（六）\n\n植物染概論概論、棉布精練、各染法作品解說、認識植物與採集後處理\n無媒染圍巾示範與實作、萃取染液、綁布技法示範與實作\n\n5/18（日）\n染前媒染、染色工程\n染後媒染、後媒染染色工程\n\n5/24（六）\n\n單寧染材萃取、植物採集、鐵媒染圍巾示範與實作\n植物性纖維生態印染示範與實作\n\n5/25（日）\n動物性纖維染前處理與實作\n植物性纖維後加工\n\n\n	課程時間：5/17、5/18、5/24、5/25（週六/週日） 09：00～17：00（4天/28小時）\n	課程地點：工藝中心學員宿舍1樓多功能交誼廳及戶外區域（南投縣草屯鎮中正路573號）\n	招生對象：幼稚園、國小、國中及高級中等學校之教師\n	招收人數：20人(6人開班)\n	報名方式：於4/16（三）下午1點起在【全國教師在職進修資訊網】線上報名。【課程代碼：4971564】\n	錄取方式：為落實工藝校園扎根政策推動所需，主辦單位得保留一半名額供本中心培育之種子教師課程實踐者或具有工藝校園扎根潛力者優先錄取（需回填學習動機以及教學實踐成果，俾利審核），其餘名額則依報名優先順序錄取，錄取名單請至至【全國教師在職進修資訊網】查詢。\n	(提醒:欲爭取實踐者及潛力者優先名額者，仍需至教師網報名喔!)\n	課程費用：學雜費588元、材料費3,000元\n	洽詢專線：049-2334141*312張小姐', `organizer`='國立台灣工藝研究發展中心', `address`='542  南投縣草屯鎮中正路573號', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='國立臺灣工藝研究發展中心|學員宿舍1樓多功能交誼廳', `latitude`=23.9797002, `longitude`=120.69095, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTCRI/Detail.init.ctr?actId=50166', `image_url`='[]';
