INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3270426b32419285b7256', '無序樂章：聲音藝術之旅', '無序樂章：聲音藝術之旅\n\n \n\n展覽日期：2025年4月12日至2025年7月6日\n展覽時間：週二至週五 09:00～17:00、週六、週日 09:00～18:00\n地點：國立臺灣美術館，戶外空間（空橋、下凹庭園）、大廳、水牛廳、102、201-202展覽室\n策展人：瑪切拉˙利斯塔 \n\n \n\n聯絡資訊 : \n\n分機: 304林小姐、713徐小姐\n \n\n展覽簡介\n\n「無序樂章：聲音藝術之旅」為法國龐畢度中心與國立臺灣美術館共同合作的一個重要大型展覽，精選龐畢度中心的新媒體藝術藏品，透過策展議題的規劃，開啟龐畢度中心藏品與臺灣及亞洲藝術家對於「聲音議題」的作品對話。\n\n \n\n本次展出來自約14個國家共30件作品，呈現當代藝術過去20年來，在實驗音樂、聲音裝置、影音創作、聲音環境和聲音表演等形式的重要跨領域經驗。本展覽所展開的聲音旅程從國立臺灣美術館的外部展開，接著進入美術館一樓和二樓空間，反映出聲音頻率的擴散性，所展出的作品可能未見其形，先聞其聲。透過藝術家選擇的多元形式、材質、符號和媒體，邀請您豎起耳朵，讓您的身心都動起來。\n\n \n\n展覽主題「無序樂章：聲音藝術之旅」刻意表現出有些不符當前潮流，同時從新的角度來觀看，引用康丁斯基（Vassily Kandinsky）的友人與合作者，德俄作曲家托馬斯·馮·哈特曼（Thomas von Hartmann）於1912年康丁斯基在慕尼黑編輯的《藍騎士》年刊（L''Almanach du Blaue Reiter）裡所發表的一篇鮮為人知的文章。該刊物彙集了藝術家、作曲家和詩人關於「破壞」和「打破落伍藝術體系」的想法所提出的反思與提議。哈特曼是「無調性」（atonality）與「微分音」（microtonality）的支持者，他認為「非協和音」（cacophonic sounds）是相當重要的，並提出「任何聲音的組合、任何音調組合的序列都是可能的」，只要能夠回應藝術家的「內在需要」（inner necessity），並脫離古典和聲學所傳承下來的規範。除了這份在20世紀初期所提出的關於現代性的宣言之外，這樣的無序、無政府（anarchist）的相關思想橫跨歷史，跨越世界各地，並在今日產生新的共鳴。\n\n \n\n展覽的主軸以下述這個政治模式為基礎：任何組織、任何架構都是臨時的，可以建構自己的臨時規則，作為超越主流結構的策略。正如人類學家大衛·格雷伯（David Graeber）所提出的，要進行解放性組織形式的思考，可能需要透過「微理論」（microtheory）來進行，也就是一種「因為轉型的作為所產生的具體與即時問題的處理方法。」\n\n \n\n本展覽分為八個段落，著重在聲音媒介相關的議題，包括科技的變革力量、對傳統音樂形式與文化的重新審視、聲學相關的調查實務，以及挑戰法律領域的方式。如今，藝術家能夠橫跨各領域，從音樂演出到裝置創作，從田野錄音採樣到人工智慧生成，從概念的規約到前所未見的舞台和故事形式，他們都能夠流暢地穿梭轉換。我們不嘗試將他們的經驗分類，企圖讓這八個段落的節奏維持為一個開放性的樂譜。\n\n \n\n參展藝術家\n\n\n	Francis ALŸS 法蘭西斯．艾利斯\n	Lawrence ABU HAMDAN 勞倫斯·阿布·哈姆丹\n	Éric BAUDELAIRE 艾瑞克．波德萊爾\n	Edmond COUCHOT and Michel BRET  艾德蒙．庫歇和米歇爾．布雷\n	Holly HERNDON and Mat DRYHURST  荷莉．亨頓和麥特．德萊赫斯特\n	DUMB TYPE   \n	Bill FONTANA    比爾·豐塔納\n	Gary HILL   蓋爾·希爾\n	JAO Chia-En     饒加恩\n	Hassan KHAN 哈桑．汗\n	Mark LECKEY 馬克．萊基\n	LIN Chi-Wei     林其蔚\n	LIU Chuang 劉窗\n	Christian MARCLAY   克里斯蒂安．馬克雷\n	Yuko MOHRI  毛利悠子\n	Emeka OGBOH     艾默加．歐格勃\n	Susan PHILIPSZ  蘇珊．菲利普茲\n	Maxime ROSSI    馬克西姆．羅西\n	Molly SODA  莫莉．索達\n	SUN Wei     孫瑋\n	Mika TAJIMA     田島美加\n	Naama TSABAR    娜瑪．察巴爾\n	Steina VASULKA and Woody VASULKA 史坦娜·瓦蘇爾卡及伍迪·瓦蘇爾卡\n	WANG Changcun   王長存\n	WANG Chung-Kun   王仲堃\n	WANG Hong-Kai, Lou MO, Alia MOSSALLAM & Keijiro SUGA   王虹凱、莫奴、\n	艾利亞．莫薩蘭與管啟次郎\n	WANG Fujui 王福瑞\n	Elsa WERTH  艾爾莎·沃斯\n	Samson YOUNG    楊嘉輝\n	ZHOU Tao    周滔\n\n\n \n\n \n\n主辦單位：龐畢度中心 \n\n共同主辦單位：國立臺灣美術館 \n\n協辦單位：文化部、藝文場館科藝創新計畫、匯聚臺流文化黑潮計畫\n\n贊助單位：國美藝術大使團 \n\n特別感謝：法國在台協會\n\n \n\n \n\n\n	「無序樂章：聲音藝術之旅」展覽由巴黎龐畢度中心主辦，並與國立臺灣美術館共同合作。\n\n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n ', '國立臺灣美術館', '403  臺中市西區535五權西路一段2號', '2025-04-12 00:00:00', '2025-07-06 00:00:00', '戶外空間（空橋、下凹庭園）、大廳、水牛廳、102、201-202展覽室', 24.1396657, 120.665874, '無資料', 'https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=54949', '[]') ON DUPLICATE KEY UPDATE `activity_name`='無序樂章：聲音藝術之旅', `description`='無序樂章：聲音藝術之旅\n\n \n\n展覽日期：2025年4月12日至2025年7月6日\n展覽時間：週二至週五 09:00～17:00、週六、週日 09:00～18:00\n地點：國立臺灣美術館，戶外空間（空橋、下凹庭園）、大廳、水牛廳、102、201-202展覽室\n策展人：瑪切拉˙利斯塔 \n\n \n\n聯絡資訊 : \n\n分機: 304林小姐、713徐小姐\n \n\n展覽簡介\n\n「無序樂章：聲音藝術之旅」為法國龐畢度中心與國立臺灣美術館共同合作的一個重要大型展覽，精選龐畢度中心的新媒體藝術藏品，透過策展議題的規劃，開啟龐畢度中心藏品與臺灣及亞洲藝術家對於「聲音議題」的作品對話。\n\n \n\n本次展出來自約14個國家共30件作品，呈現當代藝術過去20年來，在實驗音樂、聲音裝置、影音創作、聲音環境和聲音表演等形式的重要跨領域經驗。本展覽所展開的聲音旅程從國立臺灣美術館的外部展開，接著進入美術館一樓和二樓空間，反映出聲音頻率的擴散性，所展出的作品可能未見其形，先聞其聲。透過藝術家選擇的多元形式、材質、符號和媒體，邀請您豎起耳朵，讓您的身心都動起來。\n\n \n\n展覽主題「無序樂章：聲音藝術之旅」刻意表現出有些不符當前潮流，同時從新的角度來觀看，引用康丁斯基（Vassily Kandinsky）的友人與合作者，德俄作曲家托馬斯·馮·哈特曼（Thomas von Hartmann）於1912年康丁斯基在慕尼黑編輯的《藍騎士》年刊（L''Almanach du Blaue Reiter）裡所發表的一篇鮮為人知的文章。該刊物彙集了藝術家、作曲家和詩人關於「破壞」和「打破落伍藝術體系」的想法所提出的反思與提議。哈特曼是「無調性」（atonality）與「微分音」（microtonality）的支持者，他認為「非協和音」（cacophonic sounds）是相當重要的，並提出「任何聲音的組合、任何音調組合的序列都是可能的」，只要能夠回應藝術家的「內在需要」（inner necessity），並脫離古典和聲學所傳承下來的規範。除了這份在20世紀初期所提出的關於現代性的宣言之外，這樣的無序、無政府（anarchist）的相關思想橫跨歷史，跨越世界各地，並在今日產生新的共鳴。\n\n \n\n展覽的主軸以下述這個政治模式為基礎：任何組織、任何架構都是臨時的，可以建構自己的臨時規則，作為超越主流結構的策略。正如人類學家大衛·格雷伯（David Graeber）所提出的，要進行解放性組織形式的思考，可能需要透過「微理論」（microtheory）來進行，也就是一種「因為轉型的作為所產生的具體與即時問題的處理方法。」\n\n \n\n本展覽分為八個段落，著重在聲音媒介相關的議題，包括科技的變革力量、對傳統音樂形式與文化的重新審視、聲學相關的調查實務，以及挑戰法律領域的方式。如今，藝術家能夠橫跨各領域，從音樂演出到裝置創作，從田野錄音採樣到人工智慧生成，從概念的規約到前所未見的舞台和故事形式，他們都能夠流暢地穿梭轉換。我們不嘗試將他們的經驗分類，企圖讓這八個段落的節奏維持為一個開放性的樂譜。\n\n \n\n參展藝術家\n\n\n	Francis ALŸS 法蘭西斯．艾利斯\n	Lawrence ABU HAMDAN 勞倫斯·阿布·哈姆丹\n	Éric BAUDELAIRE 艾瑞克．波德萊爾\n	Edmond COUCHOT and Michel BRET  艾德蒙．庫歇和米歇爾．布雷\n	Holly HERNDON and Mat DRYHURST  荷莉．亨頓和麥特．德萊赫斯特\n	DUMB TYPE   \n	Bill FONTANA    比爾·豐塔納\n	Gary HILL   蓋爾·希爾\n	JAO Chia-En     饒加恩\n	Hassan KHAN 哈桑．汗\n	Mark LECKEY 馬克．萊基\n	LIN Chi-Wei     林其蔚\n	LIU Chuang 劉窗\n	Christian MARCLAY   克里斯蒂安．馬克雷\n	Yuko MOHRI  毛利悠子\n	Emeka OGBOH     艾默加．歐格勃\n	Susan PHILIPSZ  蘇珊．菲利普茲\n	Maxime ROSSI    馬克西姆．羅西\n	Molly SODA  莫莉．索達\n	SUN Wei     孫瑋\n	Mika TAJIMA     田島美加\n	Naama TSABAR    娜瑪．察巴爾\n	Steina VASULKA and Woody VASULKA 史坦娜·瓦蘇爾卡及伍迪·瓦蘇爾卡\n	WANG Changcun   王長存\n	WANG Chung-Kun   王仲堃\n	WANG Hong-Kai, Lou MO, Alia MOSSALLAM & Keijiro SUGA   王虹凱、莫奴、\n	艾利亞．莫薩蘭與管啟次郎\n	WANG Fujui 王福瑞\n	Elsa WERTH  艾爾莎·沃斯\n	Samson YOUNG    楊嘉輝\n	ZHOU Tao    周滔\n\n\n \n\n \n\n主辦單位：龐畢度中心 \n\n共同主辦單位：國立臺灣美術館 \n\n協辦單位：文化部、藝文場館科藝創新計畫、匯聚臺流文化黑潮計畫\n\n贊助單位：國美藝術大使團 \n\n特別感謝：法國在台協會\n\n \n\n \n\n\n	「無序樂章：聲音藝術之旅」展覽由巴黎龐畢度中心主辦，並與國立臺灣美術館共同合作。\n\n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n ', `organizer`='國立臺灣美術館', `address`='403  臺中市西區535五權西路一段2號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-07-06 00:00:00', `location`='戶外空間（空橋、下凹庭園）、大廳、水牛廳、102、201-202展覽室', `latitude`=24.1396657, `longitude`=120.665874, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=54949', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3270426b32419285b7258', '「藝起童樂繪——誠實豆沙包」系列活動', ' \n\n在兒童的人格養成與生活教育中，「誠信(實)」二字的重要性不言而喻。我們希冀透過相關題材的故事引導，以簡單且有帶入感的繪本，以及志工老師親自編寫的故事徐徐圖之，促使孩子能感同身受，型塑正確的觀念，培養誠實、守信的好習慣。\n\n \n\n一、活動地點：本館兒童繪本區\n\n二、活動對象：親子家庭觀眾\n\n三、報名方式：活動前14日開放預約，至遲於參觀前2日完成，請至「兒童繪本區入場預約申請」\n\n四、活動內容：\n\n\n	\n		\n			\n			序號\n			\n			\n			日期/時間\n			\n			\n			活動名稱\n			\n			\n			活動內容\n			\n			\n			講師\n			\n		\n		\n			\n			1\n			\n			\n			4/13 (日) \n\n			15：00-15：30\n			\n			\n			我不敢說，我怕被罵\n			\n			\n			繪本故事導賞\n			\n			\n			佘玫霓\n			\n		\n		\n			\n			2\n			\n			\n			4/27 (日) \n\n			15：00-16：00\n			\n			\n			我也想說實話啊！\n			\n			\n			繪本故事導賞\n\n			手作DIY\n			\n			\n			劉明珠\n			\n		\n		\n			\n			3\n			\n			\n			5/3 (六)\n\n			15：00-16：00\n			\n			\n			最後一根金羽毛\n			\n			\n			繪本故事導賞\n			\n			\n			謝仲毅\n			\n		\n		\n			\n			4\n			\n			\n			5/4 (日) \n\n			11：00-11：30\n			\n			\n			學說謊的人\n			\n			\n			繪本故事導賞\n			\n			\n			魏文郁\n			\n		\n	\n\n\n \n\n \n\n ', '國立臺灣美術館', '403  臺中市西區535五權西路一段2號', '2025-04-13 00:00:00', '2025-05-04 00:00:00', '兒童繪本區Picture Book Area', 24.1396657, 120.665874, '無資料', 'https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=54954', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「藝起童樂繪——誠實豆沙包」系列活動', `description`=' \n\n在兒童的人格養成與生活教育中，「誠信(實)」二字的重要性不言而喻。我們希冀透過相關題材的故事引導，以簡單且有帶入感的繪本，以及志工老師親自編寫的故事徐徐圖之，促使孩子能感同身受，型塑正確的觀念，培養誠實、守信的好習慣。\n\n \n\n一、活動地點：本館兒童繪本區\n\n二、活動對象：親子家庭觀眾\n\n三、報名方式：活動前14日開放預約，至遲於參觀前2日完成，請至「兒童繪本區入場預約申請」\n\n四、活動內容：\n\n\n	\n		\n			\n			序號\n			\n			\n			日期/時間\n			\n			\n			活動名稱\n			\n			\n			活動內容\n			\n			\n			講師\n			\n		\n		\n			\n			1\n			\n			\n			4/13 (日) \n\n			15：00-15：30\n			\n			\n			我不敢說，我怕被罵\n			\n			\n			繪本故事導賞\n			\n			\n			佘玫霓\n			\n		\n		\n			\n			2\n			\n			\n			4/27 (日) \n\n			15：00-16：00\n			\n			\n			我也想說實話啊！\n			\n			\n			繪本故事導賞\n\n			手作DIY\n			\n			\n			劉明珠\n			\n		\n		\n			\n			3\n			\n			\n			5/3 (六)\n\n			15：00-16：00\n			\n			\n			最後一根金羽毛\n			\n			\n			繪本故事導賞\n			\n			\n			謝仲毅\n			\n		\n		\n			\n			4\n			\n			\n			5/4 (日) \n\n			11：00-11：30\n			\n			\n			學說謊的人\n			\n			\n			繪本故事導賞\n			\n			\n			魏文郁\n			\n		\n	\n\n\n \n\n \n\n ', `organizer`='國立臺灣美術館', `address`='403  臺中市西區535五權西路一段2號', `start_date`='2025-04-13 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='兒童繪本區Picture Book Area', `latitude`=24.1396657, `longitude`=120.665874, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=54954', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3270426b32419285b7259', '「來美術館吧!」-美術館課程計畫 (第二階段-低幼校園團體)', '「來美術館吧!」-美術館課程計畫 \n\n (第二階段-低幼校園團體)\n\n給老師及家長的話 \n\n「來美術館吧!」是一項我們專為校園團體所策劃的「美術館課程」，內容融合了「主題式選件導賞」及「美術館資源課程化」的核心概念，連結當期的重點展覽來進行學習設計(本次配合(B1教育展示空間)-兒童藝術教育展《我記得...：關於記憶與想像的拼貼》)，並於展覽現場實行本美術館課程的探索。另外，我們將同步結合美術館自行開發的「學習資源」於本課程之中運用，期待活動後這些可供帶走的學習資源能真正回到校園裡，有機會成為老師們學校教學的一點點延伸內容，或化身為學生課後有趣的探索資源，讓美術館開發的「學習資源」融入校園，創造二次(甚至多次)具多元性的延伸運用。我們希望不僅可因此帶走參訪當下的有趣記憶外，更可延展課外學習的意義與成效，讓美術館成為陪伴師生共學的好夥伴。\n\n給小朋友的話 \n\n歡迎你加入「來美術館吧!」的美術館課程，我們希望這個小小的課程計畫，可以陪伴你和你的同學、師長一起走進美術館，用有趣的方式體驗關於藝術作品的故事!你可能會發現...原來美術館可以不只是用「看」的? 在這趟美術館的探索之旅，你可以有許多的好奇、很多的想法，還可以有超多屬於你自己逛美術館的方法!我們不只想邀請你跟著我們「一起」用有趣的方式欣賞美術館裡的作品，更期待有你們的加入帶著我們找出更多體驗藝術的獨家方法，讓我們一起把參觀美術館，成為一件很酷的事吧!\n\n課程資訊/參加說明 \n\n 課程對象：校園團體 (建議為低幼團體，錄取順序將以臺中地區優先)\n\n 課程長度：1場次約45-60分鐘\n\n 課程說明：於本館展示空間進行課程，含「主題式選件導賞」及「學習資源探索」\n\n 課程講師：由國美館館員(教育推廣組)進行課程帶領\n\n 報名方式：線上報名(此頁面)；每1場次為1班級登記(學童+隨隊教師，共約20人)\n\n 集合地點：當日於國立臺灣美術館-B1教育展示空間外(《我記得...：關於記憶與想像的拼貼》展廳外)\n\n 課程地點：本次課程配合(B1教育展示空間)-兒童藝術教育展《我記得...：關於記憶與想像的拼貼》\n\n 留意事項：於系統報名資訊後，我們將會親自與您聯繫，需收到正取及行前通知信才算報名成功!\n\n      (因本課程為免費參與，我們期待讓資源能更加有意義且不浪費的運用)', '國立臺灣美術館', '403  臺中市西區535五權西路一段2號', '2025-04-30 00:00:00', '2025-04-30 00:00:00', 'B1教育展示空間(臺灣兒童藝術基地)', 24.1396657, 120.665874, '無資料', 'https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=54955', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「來美術館吧!」-美術館課程計畫 (第二階段-低幼校園團體)', `description`='「來美術館吧!」-美術館課程計畫 \n\n (第二階段-低幼校園團體)\n\n給老師及家長的話 \n\n「來美術館吧!」是一項我們專為校園團體所策劃的「美術館課程」，內容融合了「主題式選件導賞」及「美術館資源課程化」的核心概念，連結當期的重點展覽來進行學習設計(本次配合(B1教育展示空間)-兒童藝術教育展《我記得...：關於記憶與想像的拼貼》)，並於展覽現場實行本美術館課程的探索。另外，我們將同步結合美術館自行開發的「學習資源」於本課程之中運用，期待活動後這些可供帶走的學習資源能真正回到校園裡，有機會成為老師們學校教學的一點點延伸內容，或化身為學生課後有趣的探索資源，讓美術館開發的「學習資源」融入校園，創造二次(甚至多次)具多元性的延伸運用。我們希望不僅可因此帶走參訪當下的有趣記憶外，更可延展課外學習的意義與成效，讓美術館成為陪伴師生共學的好夥伴。\n\n給小朋友的話 \n\n歡迎你加入「來美術館吧!」的美術館課程，我們希望這個小小的課程計畫，可以陪伴你和你的同學、師長一起走進美術館，用有趣的方式體驗關於藝術作品的故事!你可能會發現...原來美術館可以不只是用「看」的? 在這趟美術館的探索之旅，你可以有許多的好奇、很多的想法，還可以有超多屬於你自己逛美術館的方法!我們不只想邀請你跟著我們「一起」用有趣的方式欣賞美術館裡的作品，更期待有你們的加入帶著我們找出更多體驗藝術的獨家方法，讓我們一起把參觀美術館，成為一件很酷的事吧!\n\n課程資訊/參加說明 \n\n 課程對象：校園團體 (建議為低幼團體，錄取順序將以臺中地區優先)\n\n 課程長度：1場次約45-60分鐘\n\n 課程說明：於本館展示空間進行課程，含「主題式選件導賞」及「學習資源探索」\n\n 課程講師：由國美館館員(教育推廣組)進行課程帶領\n\n 報名方式：線上報名(此頁面)；每1場次為1班級登記(學童+隨隊教師，共約20人)\n\n 集合地點：當日於國立臺灣美術館-B1教育展示空間外(《我記得...：關於記憶與想像的拼貼》展廳外)\n\n 課程地點：本次課程配合(B1教育展示空間)-兒童藝術教育展《我記得...：關於記憶與想像的拼貼》\n\n 留意事項：於系統報名資訊後，我們將會親自與您聯繫，需收到正取及行前通知信才算報名成功!\n\n      (因本課程為免費參與，我們期待讓資源能更加有意義且不浪費的運用)', `organizer`='國立臺灣美術館', `address`='403  臺中市西區535五權西路一段2號', `start_date`='2025-04-30 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='B1教育展示空間(臺灣兒童藝術基地)', `latitude`=24.1396657, `longitude`=120.665874, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTMOFA/Detail.init.ctr?actId=54955', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3274f26b32419285b725b', '【中市圖沙鹿深波分館】慈興親子讀經班', '慈興親子讀經班\r\n培養孩子從小閱讀，從四書五經的閱讀中，尋找體會古人所遺留下來的智慧，讓孩子與大人一起共讀是最棒的陪伴。三字經、千字文、百孝經等，唱跳律動、繪本分享、品格教育課程。歡迎親子報名參加。\r\n★家長班：\r\n學習親職教育、婚姻觀、多元的財務經營、論語經典初探、情緒的魅力、語言的力量。\r\n\r\n☆活動日期：\r\n2025/01/08(三)—2025/12/31\r\n每週三 19:00-20:30\r\n★活動地點：沙鹿深波分館B1多功能活動室 ', '臺中市立圖書館沙鹿深波分館', '臺中市沙鹿區鎮南路二段 488號', '2025-01-08 00:00:00', '2025-12-31 00:00:00', '臺中市立圖書館沙鹿深波分館', 24.23425212, 120.5838628, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖沙鹿深波分館】慈興親子讀經班', `description`='慈興親子讀經班\r\n培養孩子從小閱讀，從四書五經的閱讀中，尋找體會古人所遺留下來的智慧，讓孩子與大人一起共讀是最棒的陪伴。三字經、千字文、百孝經等，唱跳律動、繪本分享、品格教育課程。歡迎親子報名參加。\r\n★家長班：\r\n學習親職教育、婚姻觀、多元的財務經營、論語經典初探、情緒的魅力、語言的力量。\r\n\r\n☆活動日期：\r\n2025/01/08(三)—2025/12/31\r\n每週三 19:00-20:30\r\n★活動地點：沙鹿深波分館B1多功能活動室 ', `organizer`='臺中市立圖書館沙鹿深波分館', `address`='臺中市沙鹿區鎮南路二段 488號', `start_date`='2025-01-08 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='臺中市立圖書館沙鹿深波分館', `latitude`=24.23425212, `longitude`=120.5838628, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3278626b32419285b7262', '郵電藝起－臺灣近代畫作郵票特展', '為擴大館際交流，分享典藏資源，在科技的電力世界注入文藝美學，郵政博物館受邀與台電北部展示館攜手合作，於北展館之藝術空間畫廊舉辦「郵電藝起－臺灣近代畫作郵票特展」，採放大郵票圖案以畫框形式與郵票併同展陳，誠摯邀請入館民眾同來欣賞，感受美好的心靈饗宴。\r\n一、主辦單位：郵政博物館、台電北部展示館\r\n二、展覽期間：114年3月11日（週二）至7月13日（週日）\r\n三、展覽地點：台電北部展示館2樓\r\n   （新北市萬里區野柳里八斗60號），免費入館參觀\r\n四、開放時間：週二至週日8：20至16：20（每週一休館）\r\n五、展覽內容：郵政博物館典藏「臺灣近代畫作郵票」系列（91、92、93、98、99、107、108、110、114年版）\r\n\r\n本次展出藝術品圖像感謝臺北市立美術館提供。\r\n\r\n', '郵政博物館', '新北市萬里區', '2025-03-11 00:00:00', '2025-07-13 00:00:00', '萬里區（新北市）=', 25.17572457, 121.6439307, '無資料', 'https://museum.post.gov.tw/post/Postal_Museum/museum/index.jsp?ID=1525402201649&control_type=page&news_no=66299&news_cat=10102', '[]') ON DUPLICATE KEY UPDATE `activity_name`='郵電藝起－臺灣近代畫作郵票特展', `description`='為擴大館際交流，分享典藏資源，在科技的電力世界注入文藝美學，郵政博物館受邀與台電北部展示館攜手合作，於北展館之藝術空間畫廊舉辦「郵電藝起－臺灣近代畫作郵票特展」，採放大郵票圖案以畫框形式與郵票併同展陳，誠摯邀請入館民眾同來欣賞，感受美好的心靈饗宴。\r\n一、主辦單位：郵政博物館、台電北部展示館\r\n二、展覽期間：114年3月11日（週二）至7月13日（週日）\r\n三、展覽地點：台電北部展示館2樓\r\n   （新北市萬里區野柳里八斗60號），免費入館參觀\r\n四、開放時間：週二至週日8：20至16：20（每週一休館）\r\n五、展覽內容：郵政博物館典藏「臺灣近代畫作郵票」系列（91、92、93、98、99、107、108、110、114年版）\r\n\r\n本次展出藝術品圖像感謝臺北市立美術館提供。\r\n\r\n', `organizer`='郵政博物館', `address`='新北市萬里區', `start_date`='2025-03-11 00:00:00', `end_date`='2025-07-13 00:00:00', `location`='萬里區（新北市）=', `latitude`=25.17572457, `longitude`=121.6439307, `ticket_price`='無資料', `source_url`='https://museum.post.gov.tw/post/Postal_Museum/museum/index.jsp?ID=1525402201649&control_type=page&news_no=66299&news_cat=10102', `image_url`='[]';
