INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279726b32419285b7278', '龎智文、黃品蓁、馬雪齡老師．學生發表音樂會', '活動主旨：\r\n音樂會的目的，是為了讓孩子提升自信，以及擁有舞台經驗。當然最重要是謝謝家長在孩子學習音樂過程中的付出與支持，也希望透過這場音樂會能創造孩子們和老師、家長們間的共同美好回憶。\r\n活動內容：\r\n呂宜庭 鋼琴d小調幻想曲\r\n陳秉銓 鋼琴 蝴蝶\r\n劉芯妤 鋼琴 土耳其進行曲\r\n簡華宏 四手聯彈 路小雨\r\n吳旻珊 長笛G大調小步舞曲\r\n廖仁輔 小提琴 獵人合唱\r\n翁珮庭 鋼琴 紅豬\r\n陳宥蓁 小提琴 快樂人生\r\n林宸羽 鋼琴 牧歌\r\n……等……曲目演出……\r\n', '龎智文', '臺中市西區英才路600號', '2025-04-27 00:00:00', '2025-04-27 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000710', '[]') ON DUPLICATE KEY UPDATE `activity_name`='龎智文、黃品蓁、馬雪齡老師．學生發表音樂會', `description`='活動主旨：\r\n音樂會的目的，是為了讓孩子提升自信，以及擁有舞台經驗。當然最重要是謝謝家長在孩子學習音樂過程中的付出與支持，也希望透過這場音樂會能創造孩子們和老師、家長們間的共同美好回憶。\r\n活動內容：\r\n呂宜庭 鋼琴d小調幻想曲\r\n陳秉銓 鋼琴 蝴蝶\r\n劉芯妤 鋼琴 土耳其進行曲\r\n簡華宏 四手聯彈 路小雨\r\n吳旻珊 長笛G大調小步舞曲\r\n廖仁輔 小提琴 獵人合唱\r\n翁珮庭 鋼琴 紅豬\r\n陳宥蓁 小提琴 快樂人生\r\n林宸羽 鋼琴 牧歌\r\n……等……曲目演出……\r\n', `organizer`='龎智文', `address`='臺中市西區英才路600號', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000710', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279a26b32419285b727a', '《心的花園》 黃里莎 拼貼創作個展', '每個人的內在花園都有獨特的模樣，盛開著夢想、記憶與情感。 在這場分享會中，我們想邀請你帶著一顆流動的心，輕鬆走進這些花園，看看、聊聊、 感受它們的能量。 \r\n活動將從畫作分享開始，聊聊「心的花園」的創作故事，讓畫面引領我們走進內在的 風景。接著，透過簡單的拼貼體驗活動，順著當下的感受動手拼貼，為自己的內在花 園留下片刻的形狀。\r\n這是一場自由且輕盈的探索，不需要有拼貼技巧，也不需要顧慮 美感上如何呈現。 只要享受剪剪貼貼的過程，與自己待在一起，創造一段溫柔的自我對話時光。\r\nPS. 分享會包含拼貼活動，大家會完成一張13 x 20cm 的小作品。\r\n', '樹瓦藝術Shu Woa', '臺中市南區', '2025-03-15 00:00:00', '2025-04-30 00:00:00', '南區（臺中市）=', 24.12114107, 120.6646178, '無資料', 'https://reurl.cc/xNZ8eE', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《心的花園》 黃里莎 拼貼創作個展', `description`='每個人的內在花園都有獨特的模樣，盛開著夢想、記憶與情感。 在這場分享會中，我們想邀請你帶著一顆流動的心，輕鬆走進這些花園，看看、聊聊、 感受它們的能量。 \r\n活動將從畫作分享開始，聊聊「心的花園」的創作故事，讓畫面引領我們走進內在的 風景。接著，透過簡單的拼貼體驗活動，順著當下的感受動手拼貼，為自己的內在花 園留下片刻的形狀。\r\n這是一場自由且輕盈的探索，不需要有拼貼技巧，也不需要顧慮 美感上如何呈現。 只要享受剪剪貼貼的過程，與自己待在一起，創造一段溫柔的自我對話時光。\r\nPS. 分享會包含拼貼活動，大家會完成一張13 x 20cm 的小作品。\r\n', `organizer`='樹瓦藝術Shu Woa', `address`='臺中市南區', `start_date`='2025-03-15 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='南區（臺中市）=', `latitude`=24.12114107, `longitude`=120.6646178, `ticket_price`='無資料', `source_url`='https://reurl.cc/xNZ8eE', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279a26b32419285b727b', '【大里大新分館】04/01-04/30 2025世界閱讀日「咖波帶你遊中市圖」特色書展', '以圖文書為主題，精選各類漫畫、繪本、插畫書籍、臺語繪本，讓讀者在閱讀中感受台灣文化與語言的魅力，歡迎大小讀者共襄盛舉！', '臺中市立圖書館大里分館', '臺中市大里區大新街36-1號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館大里大新分館', 24.09575742, 120.6926261, '無資料', 'https://reurl.cc/OY1o37', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【大里大新分館】04/01-04/30 2025世界閱讀日「咖波帶你遊中市圖」特色書展', `description`='以圖文書為主題，精選各類漫畫、繪本、插畫書籍、臺語繪本，讓讀者在閱讀中感受台灣文化與語言的魅力，歡迎大小讀者共襄盛舉！', `organizer`='臺中市立圖書館大里分館', `address`='臺中市大里區大新街36-1號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館大里大新分館', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://reurl.cc/OY1o37', `image_url`='[]';
