INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279a26b32419285b727d', '【大里大新分館】04/19 故事魔法快樂屋-說故事', '故事志工講述繪本故事，增進閱讀樂趣。故事繪本:「愛花的牛」、「轉個彎，心情不一樣」、「章魚先生買褲子」、「我要送最棒的禮物」，歡迎親子一起來聽故事。', '臺中市立圖書館大里分館', '臺中市大里區大新街36-1號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '臺中市立圖書館大里大新分館', 24.09575742, 120.6926261, '無資料', 'https://reurl.cc/0Koe5K', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【大里大新分館】04/19 故事魔法快樂屋-說故事', `description`='故事志工講述繪本故事，增進閱讀樂趣。故事繪本:「愛花的牛」、「轉個彎，心情不一樣」、「章魚先生買褲子」、「我要送最棒的禮物」，歡迎親子一起來聽故事。', `organizer`='臺中市立圖書館大里分館', `address`='臺中市大里區大新街36-1號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='臺中市立圖書館大里大新分館', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://reurl.cc/0Koe5K', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279a26b32419285b727e', 'The Best of ESL英文戲劇展演活動', '活動目標：\r\n本校為推廣英文教學，舉辦成果表演，豐富幼兒生活經驗，促進親師交流，培養幼兒感恩情懷。\r\n活動流程：\r\n以英文詩歌、演說、戲劇等方式呈現英文學習成果，各班級依序上台演出(約有5班)；支持孩子演出，全程參與觀賞。\r\n', '台中市私立道禾美語會話短期補習班', '臺中市西區英才路600號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '臺中市大墩文化中心', 24.14391082, 120.6647579, '無資料', 'https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000714', '[]') ON DUPLICATE KEY UPDATE `activity_name`='The Best of ESL英文戲劇展演活動', `description`='活動目標：\r\n本校為推廣英文教學，舉辦成果表演，豐富幼兒生活經驗，促進親師交流，培養幼兒感恩情懷。\r\n活動流程：\r\n以英文詩歌、演說、戲劇等方式呈現英文學習成果，各班級依序上台演出(約有5班)；支持孩子演出，全程參與觀賞。\r\n', `organizer`='台中市私立道禾美語會話短期補習班', `address`='臺中市西區英才路600號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='臺中市大墩文化中心', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.dadun.culture.taichung.gov.tw/MessagePublic/MessageDetail?MPID=MP00000714', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279a26b32419285b727f', '【大里大新分館】04/20 講座:「我的故鄉．我的閱讀時光」~走讀大里杙', '邀請陳永進老師和讀者一起走讀「大里杙」，從大里杙的「舊街仔」，穿過鹹菜巷，到街底的「倒栽榕」，探訪歷史悠久的福興宮、將軍廟等等，歡迎大家一起來走讀大里杙，認識大里杙豐富的歷史文化和濃濃的鄉土人情。\r\n講師：陳永進老師\r\n對象：一般民眾', '臺中市立圖書館大里大新分館', '臺中市大里區', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '大里區（臺中市）=', 24.09575742, 120.6926261, '無資料', 'https://reurl.cc/yRZbD2', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【大里大新分館】04/20 講座:「我的故鄉．我的閱讀時光」~走讀大里杙', `description`='邀請陳永進老師和讀者一起走讀「大里杙」，從大里杙的「舊街仔」，穿過鹹菜巷，到街底的「倒栽榕」，探訪歷史悠久的福興宮、將軍廟等等，歡迎大家一起來走讀大里杙，認識大里杙豐富的歷史文化和濃濃的鄉土人情。\r\n講師：陳永進老師\r\n對象：一般民眾', `organizer`='臺中市立圖書館大里大新分館', `address`='臺中市大里區', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='大里區（臺中市）=', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://reurl.cc/yRZbD2', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279c26b32419285b7285', '2025青年音樂年度音樂會', '2025年，台中市演藝團體_青年音樂將與青年高中音樂科攜手，要再次為學生量身訂做屬於高中生的熱血青春音樂會，這次的場景發生在某便利商店，藉由大夜班店員與顧客之間的情感交流，傳達出發生在你我身邊的大小故事；我們依然保有以現場樂團結合歌舞戲劇的方式，期待能夠開啟青年學子的表演視野，也期待將音樂的趨勢主流與精神，介紹給社區大眾，讓大眾更加貼近音樂、更加熟悉，這不僅是一場青春與藝術的盛會，更是展現多元藝術風采的高峰。', '無資料', '臺中市北區學士路98號', '2025-04-16 00:00:00', '2025-04-18 00:00:00', '臺中市中山堂', 24.15863985, 120.6809521, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青年音樂年度音樂會', `description`='2025年，台中市演藝團體_青年音樂將與青年高中音樂科攜手，要再次為學生量身訂做屬於高中生的熱血青春音樂會，這次的場景發生在某便利商店，藉由大夜班店員與顧客之間的情感交流，傳達出發生在你我身邊的大小故事；我們依然保有以現場樂團結合歌舞戲劇的方式，期待能夠開啟青年學子的表演視野，也期待將音樂的趨勢主流與精神，介紹給社區大眾，讓大眾更加貼近音樂、更加熟悉，這不僅是一場青春與藝術的盛會，更是展現多元藝術風采的高峰。', `organizer`='無資料', `address`='臺中市北區學士路98號', `start_date`='2025-04-16 00:00:00', `end_date`='2025-04-18 00:00:00', `location`='臺中市中山堂', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279c26b32419285b7286', '2025傑優青少年打擊樂團年度音樂會《青春進行式》', '每一次敲擊，都是夢想的追尋；每一段旋律，都是感動的記憶。\r\n\r\n在青春的舞台上，盡情揮灑熱情，創造只屬於我們的節奏！我們是傑優青少年打擊樂團，青春進行式，等你一同來參與！\r\n', '財團法人擊樂文教基金會', '臺中市北區學士路98號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '臺中市中山堂', 24.15863985, 120.6809521, '全票+400', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025傑優青少年打擊樂團年度音樂會《青春進行式》', `description`='每一次敲擊，都是夢想的追尋；每一段旋律，都是感動的記憶。\r\n\r\n在青春的舞台上，盡情揮灑熱情，創造只屬於我們的節奏！我們是傑優青少年打擊樂團，青春進行式，等你一同來參與！\r\n', `organizer`='財團法人擊樂文教基金會', `address`='臺中市北區學士路98號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='臺中市中山堂', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='全票+400', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279c26b32419285b7288', '2025爵士美樂地', '企業家爵士大樂團「爵士美樂地」系列音樂會，自2012年起已連續舉辦八年，主題自搖擺爵士、台灣風情到老情歌，用爵士音樂重新演繹經典歌曲，讓聽眾印象深刻。2021年爵士美樂地音樂會：「爵士與搖滾」於臺中市中山堂舉辦，演出多首經典爵士曲目，包含英Blues、Swing、Funk、Pop等各類型爵士音樂風格，以及改編搖滾歌曲的爵士音樂，如Welcome to the Jungle等樂曲，大受好評，引起廣大迴響。2025年爵士美樂地音樂會以「Jazz in the world」為主題，爵士風格融合民族元素，藉由大樂團形式演出，聽見不一樣的爵士風情。', '企業家爵士大樂團', '臺中市北區學士路98號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '臺中市中山堂', 24.15863985, 120.6809521, '無資料', 'https://hall.culture.taichung.gov.tw/HallFrontend/WatchShow/ShowInfoDetail?AADID=CCD0000965', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025爵士美樂地', `description`='企業家爵士大樂團「爵士美樂地」系列音樂會，自2012年起已連續舉辦八年，主題自搖擺爵士、台灣風情到老情歌，用爵士音樂重新演繹經典歌曲，讓聽眾印象深刻。2021年爵士美樂地音樂會：「爵士與搖滾」於臺中市中山堂舉辦，演出多首經典爵士曲目，包含英Blues、Swing、Funk、Pop等各類型爵士音樂風格，以及改編搖滾歌曲的爵士音樂，如Welcome to the Jungle等樂曲，大受好評，引起廣大迴響。2025年爵士美樂地音樂會以「Jazz in the world」為主題，爵士風格融合民族元素，藉由大樂團形式演出，聽見不一樣的爵士風情。', `organizer`='企業家爵士大樂團', `address`='臺中市北區學士路98號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺中市中山堂', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://hall.culture.taichung.gov.tw/HallFrontend/WatchShow/ShowInfoDetail?AADID=CCD0000965', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279c26b32419285b7289', '4月假日電影院-忍者龜：變種大亂鬥', '影片敘述忍者龜四兄弟，遠離人類世界多年之後，決定主動出擊，希望能夠靠著他們的英勇事蹟贏得紐約客的心，並且獲得他們的接納，成為正常的青少年。他們的新朋友艾波歐尼爾也協助他們試圖扳倒一個神秘的犯罪集團，但是當對方派出一支變種軍團，他們很快就發現他們根本就是自不量力。', '臺中市立圖書館南屯分館', '臺中市南屯區大墩12街361號', '2025-04-27 00:00:00', '2025-04-27 00:00:00', '臺中市立圖書館南屯分館', 24.14165524, 120.6177379, '無資料', 'https://reurl.cc/OY19gy', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月假日電影院-忍者龜：變種大亂鬥', `description`='影片敘述忍者龜四兄弟，遠離人類世界多年之後，決定主動出擊，希望能夠靠著他們的英勇事蹟贏得紐約客的心，並且獲得他們的接納，成為正常的青少年。他們的新朋友艾波歐尼爾也協助他們試圖扳倒一個神秘的犯罪集團，但是當對方派出一支變種軍團，他們很快就發現他們根本就是自不量力。', `organizer`='臺中市立圖書館南屯分館', `address`='臺中市南屯區大墩12街361號', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺中市立圖書館南屯分館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://reurl.cc/OY19gy', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279c26b32419285b728a', '週六說故事(4月3場)', '-故事百寶箱-\r\n本系列說故事活動免事先報名，歡迎踴躍參加\r\n由台中故事協會老師分享繪本故事，快來聽故事吧。\r\n\r\n-魔法故事森林-\r\n由南屯分館魔法故事森林的故事精靈帶領小朋友一起讀繪本、玩手作。\r\n本系列活動免報名，歡迎踴躍參加。\r\n\r\n每週故事主題會提前公告於FB粉絲專頁，歡迎關注我們！', '臺中市立圖書館南屯分館', '臺中市南屯區大墩12街361號', '2025-04-05 00:00:00', '2025-04-19 00:00:00', '臺中市立圖書館南屯分館', 24.14165524, 120.6177379, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='週六說故事(4月3場)', `description`='-故事百寶箱-\r\n本系列說故事活動免事先報名，歡迎踴躍參加\r\n由台中故事協會老師分享繪本故事，快來聽故事吧。\r\n\r\n-魔法故事森林-\r\n由南屯分館魔法故事森林的故事精靈帶領小朋友一起讀繪本、玩手作。\r\n本系列活動免報名，歡迎踴躍參加。\r\n\r\n每週故事主題會提前公告於FB粉絲專頁，歡迎關注我們！', `organizer`='臺中市立圖書館南屯分館', `address`='臺中市南屯區大墩12街361號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='臺中市立圖書館南屯分館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279c26b32419285b728b', '精靈小劇場(4月)', '由南屯分館故事志工，帶來戲劇演出，一起度過美好的週六時光。', '臺中市立圖書館南屯分館', '臺中市南屯區大墩12街361號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '臺中市立圖書館南屯分館', 24.14165524, 120.6177379, '無資料', 'https://reurl.cc/6K2r65', '[]') ON DUPLICATE KEY UPDATE `activity_name`='精靈小劇場(4月)', `description`='由南屯分館故事志工，帶來戲劇演出，一起度過美好的週六時光。', `organizer`='臺中市立圖書館南屯分館', `address`='臺中市南屯區大墩12街361號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='臺中市立圖書館南屯分館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://reurl.cc/6K2r65', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279c26b32419285b728c', '4月主題書展(2場)', '1F\r\n4/1-4/20【法律說白話】書展\r\n展出法律相關圖書，歡迎到館閱覽。\r\n4/22-4/30【咖波帶你遊中市圖】書展\r\n配合總館展出可愛療癒圖文書，歡迎到館閱覽。\r\n2F-【布朗克動吃動】書展\r\n本次書展以「便便」為主題展出相關圖書，歡迎到館閱覽。', '臺中市立圖書館南屯分館', '臺中市南屯區大墩12街361號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館南屯分館', 24.14165524, 120.6177379, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月主題書展(2場)', `description`='1F\r\n4/1-4/20【法律說白話】書展\r\n展出法律相關圖書，歡迎到館閱覽。\r\n4/22-4/30【咖波帶你遊中市圖】書展\r\n配合總館展出可愛療癒圖文書，歡迎到館閱覽。\r\n2F-【布朗克動吃動】書展\r\n本次書展以「便便」為主題展出相關圖書，歡迎到館閱覽。', `organizer`='臺中市立圖書館南屯分館', `address`='臺中市南屯區大墩12街361號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館南屯分館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279d26b32419285b728d', '穿越夢境：魔法冒險的世界', '新民高中附設國中部為落實雙語教學的成效，提高學生對於英語之學習興趣，透過戲劇演出之方式，展現學習的成果。以班級為單位，讓每位同學經由角色扮演，了解自己在團體中的重要性。節目共分6個故事，每場約20分鐘，由本校外籍教師編寫劇本，導師協助指導，讓孩子們自行依劇情所需製作相關道具，並透過角色扮演，以不同的表演風格及方式呈現，除了讓孩子們體會團體合作的意義外，進而從活動中培養自動自發、尊重、責任及自我成就感。', '臺中市私立新民高級中學', '臺中市北區學士路98號', '2025-04-24 00:00:00', '2025-04-25 00:00:00', '臺中市中山堂', 24.15863985, 120.6809521, '無資料', 'https://hall.culture.taichung.gov.tw/HallFrontend/WatchShow/ShowInfoDetail?AADID=CCD0000741', '[]') ON DUPLICATE KEY UPDATE `activity_name`='穿越夢境：魔法冒險的世界', `description`='新民高中附設國中部為落實雙語教學的成效，提高學生對於英語之學習興趣，透過戲劇演出之方式，展現學習的成果。以班級為單位，讓每位同學經由角色扮演，了解自己在團體中的重要性。節目共分6個故事，每場約20分鐘，由本校外籍教師編寫劇本，導師協助指導，讓孩子們自行依劇情所需製作相關道具，並透過角色扮演，以不同的表演風格及方式呈現，除了讓孩子們體會團體合作的意義外，進而從活動中培養自動自發、尊重、責任及自我成就感。', `organizer`='臺中市私立新民高級中學', `address`='臺中市北區學士路98號', `start_date`='2025-04-24 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='臺中市中山堂', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://hall.culture.taichung.gov.tw/HallFrontend/WatchShow/ShowInfoDetail?AADID=CCD0000741', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279d26b32419285b728e', '【福稅飄書香】書展(4月)', '本分館與臺中市政府地方稅務局文心分局合作，在分局閱報區展出英文童書相關圖書，歡迎大家參觀閱覽！', '臺中市立圖書館南屯分館', '臺中市西屯區', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '西屯區（臺中市）=', 24.18308895, 120.6270131, '無資料', 'https://reurl.cc/bW5MkX', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【福稅飄書香】書展(4月)', `description`='本分館與臺中市政府地方稅務局文心分局合作，在分局閱報區展出英文童書相關圖書，歡迎大家參觀閱覽！', `organizer`='臺中市立圖書館南屯分館', `address`='臺中市西屯區', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='西屯區（臺中市）=', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://reurl.cc/bW5MkX', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279d26b32419285b7290', '日本飛行船劇團《小飛俠彼得潘》', '♪如果到夢幻島上可以永遠只當個孩子，你會選擇留在那裡嗎？\r\n所有的孩子都知道一個叫做「夢幻島」的地方（Neverland），島上有一個叫做彼得潘的男孩，他不但會飛，而且永遠不會長大。他是孩子們心目中的英雄，也是夢幻島上迷途的孩子最可靠的首領。為了找尋新的故事，他和小精靈來到另一個世界，卻不小心被溫蒂及她的兩個弟弟發現。劇中有勇敢的泰雅莉莉公主、還有凶惡的虎克船長以及他的海盜們！\r\n將友誼與信念集結成一部有趣又驚奇的冒險故事，由生動活潑的人偶配合國語發音演出，雖然是兒童劇的演出，但同樣適合各年齡層觀賞。\r\n', '童歡藝術有限公司', '臺中市北區學士路98號', '2025-04-27 00:00:00', '2025-04-27 00:00:00', '臺中市中山堂', 24.15863985, 120.6809521, '無資料', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='日本飛行船劇團《小飛俠彼得潘》', `description`='♪如果到夢幻島上可以永遠只當個孩子，你會選擇留在那裡嗎？\r\n所有的孩子都知道一個叫做「夢幻島」的地方（Neverland），島上有一個叫做彼得潘的男孩，他不但會飛，而且永遠不會長大。他是孩子們心目中的英雄，也是夢幻島上迷途的孩子最可靠的首領。為了找尋新的故事，他和小精靈來到另一個世界，卻不小心被溫蒂及她的兩個弟弟發現。劇中有勇敢的泰雅莉莉公主、還有凶惡的虎克船長以及他的海盜們！\r\n將友誼與信念集結成一部有趣又驚奇的冒險故事，由生動活潑的人偶配合國語發音演出，雖然是兒童劇的演出，但同樣適合各年齡層觀賞。\r\n', `organizer`='童歡藝術有限公司', `address`='臺中市北區學士路98號', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺中市中山堂', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279d26b32419285b7291', '2025臺中市中區光復國民小學音樂班成果發表會《勇氣之歌》', '臺中市中區光復國小音樂班於1973年創立，是臺灣音樂家養成之重要搖籃，近年來推動幼兒園大班及小學一、二年級的「鋼琴特色課程」與「音樂律動社團」等相關音樂教育，栽培下一代的音樂幼苗。在師長用心經營下，學生在個人或團體之各項音樂比賽屢創佳績，參加「112學年度全國學生音樂比賽臺中市初賽」榮獲管絃樂合奏特優等第一名、國樂合奏優等、絲竹室內樂特優等佳績。\r\n 本場音樂會以「勇氣之歌」為主題，涵蓋國樂合奏、絲竹室內樂、舞蹈、合唱團、弦樂團、管樂團、管弦樂團合奏型態，展現光復國小音樂班學生多元學習成果。\r\n', '臺中市中區光復國民小學', '臺中市北區學士路98號', '2025-04-30 00:00:00', '2025-04-30 00:00:00', '臺中市中山堂', 24.15863985, 120.6809521, '無資料', 'https://hall.culture.taichung.gov.tw/HallFrontend/WatchShow/ShowInfoDetail?AADID=CCD0000817', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺中市中區光復國民小學音樂班成果發表會《勇氣之歌》', `description`='臺中市中區光復國小音樂班於1973年創立，是臺灣音樂家養成之重要搖籃，近年來推動幼兒園大班及小學一、二年級的「鋼琴特色課程」與「音樂律動社團」等相關音樂教育，栽培下一代的音樂幼苗。在師長用心經營下，學生在個人或團體之各項音樂比賽屢創佳績，參加「112學年度全國學生音樂比賽臺中市初賽」榮獲管絃樂合奏特優等第一名、國樂合奏優等、絲竹室內樂特優等佳績。\r\n 本場音樂會以「勇氣之歌」為主題，涵蓋國樂合奏、絲竹室內樂、舞蹈、合唱團、弦樂團、管樂團、管弦樂團合奏型態，展現光復國小音樂班學生多元學習成果。\r\n', `organizer`='臺中市中區光復國民小學', `address`='臺中市北區學士路98號', `start_date`='2025-04-30 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市中山堂', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://hall.culture.taichung.gov.tw/HallFrontend/WatchShow/ShowInfoDetail?AADID=CCD0000817', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279d26b32419285b7292', '臺中藝術亮點-童凱俐油畫及水彩創作個展', '「窗外的白貓與窗內的黑貓 終於相遇 原來你我的世界不就如此」，展覽展出畫家童凱俐油畫及水彩作品精采畫作，邀請大家一同感受畫中美好的記憶與繽紛的色彩！', '全安堂太陽餅博物館', '臺中市中區台灣大道一段145號', '2025-04-01 00:00:00', '2025-04-29 00:00:00', '全安堂臺灣太陽餅博物館', 24.14168566, 120.680598, '無資料', 'https://www.artspots-taichung.com.tw/tw/news-detail/327?kind=11&root=8', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中藝術亮點-童凱俐油畫及水彩創作個展', `description`='「窗外的白貓與窗內的黑貓 終於相遇 原來你我的世界不就如此」，展覽展出畫家童凱俐油畫及水彩作品精采畫作，邀請大家一同感受畫中美好的記憶與繽紛的色彩！', `organizer`='全安堂太陽餅博物館', `address`='臺中市中區台灣大道一段145號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='全安堂臺灣太陽餅博物館', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='https://www.artspots-taichung.com.tw/tw/news-detail/327?kind=11&root=8', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279e26b32419285b7299', '審計新村368新創聚落114年4月街藝表演', '台中審計新村全稱為「審計新村368新創聚落」，前身為臺中省政府審計處的員工宿舍，而在1998年凍省後被閒置荒廢多年，直到2015年因配合臺中市政府的創業基地進駐計畫，加入藝術元素整修改造，才讓審計新村得以用全新的面貌被大眾認識。\r\n喜歡音樂的你們，聚落邀請你們一同來欣賞表演，並支持你尬意的街頭藝人。', '審計368新創聚落', '臺中市西區', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/W0Lyz7', '[]') ON DUPLICATE KEY UPDATE `activity_name`='審計新村368新創聚落114年4月街藝表演', `description`='台中審計新村全稱為「審計新村368新創聚落」，前身為臺中省政府審計處的員工宿舍，而在1998年凍省後被閒置荒廢多年，直到2015年因配合臺中市政府的創業基地進駐計畫，加入藝術元素整修改造，才讓審計新村得以用全新的面貌被大眾認識。\r\n喜歡音樂的你們，聚落邀請你們一同來欣賞表演，並支持你尬意的街頭藝人。', `organizer`='審計368新創聚落', `address`='臺中市西區', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/W0Lyz7', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3279e26b32419285b729a', '【福壽康寧 後驛社區大學隽雅篆刻學會 篆刻作品聯展】', '篆刻，又稱「治印」、「刻印」，是中國傳統的一門獨特藝術，它結合了書法、繪畫、雕刻等元素，透過刀具在印石上雕刻出各式各樣的文字和圖案，再鈐蓋於書畫作品上，以增添作品的藝術價值和文化底蘊。\r\n篆刻，這門古老而精美的藝術，正等待著您的探索與觀賞!', '臺中市立圖書館東區分館', '臺中市東區建德街144號', '2025-03-11 00:00:00', '2025-05-24 00:00:00', '臺中市立圖書館東區分館', 24.13733209, 120.6970865, '無資料', 'https://reurl.cc/7KoEZ1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【福壽康寧 後驛社區大學隽雅篆刻學會 篆刻作品聯展】', `description`='篆刻，又稱「治印」、「刻印」，是中國傳統的一門獨特藝術，它結合了書法、繪畫、雕刻等元素，透過刀具在印石上雕刻出各式各樣的文字和圖案，再鈐蓋於書畫作品上，以增添作品的藝術價值和文化底蘊。\r\n篆刻，這門古老而精美的藝術，正等待著您的探索與觀賞!', `organizer`='臺中市立圖書館東區分館', `address`='臺中市東區建德街144號', `start_date`='2025-03-11 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='臺中市立圖書館東區分館', `latitude`=24.13733209, `longitude`=120.6970865, `ticket_price`='無資料', `source_url`='https://reurl.cc/7KoEZ1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e327a026b32419285b729b', '精武圖書館-4月書展', '【擁有童一片星空】 1F歲月流金區\r\n\r\n精武圖書館在今年的兒童節主題書展，邀請讀者一同走進星空書展的奇幻世界。無論你是對太空人的冒險心生向往，還是沉浸於月亮與雲朵的浪漫，這裡都能找到屬於你的故事與奇遇。書展中的每個角落，都藏著一個未知小宇宙，等著你來探索。\r\n\r\n【食在好新情】 2F文學區\r\n本次書展以香料、料理、味覺科普為主軸，\r\n帶領讀者從飲食層面認識新住民文化，\r\n香香辣辣的料理，如其人文風情熱情洋溢，\r\n不只胃開了，心花也開了，心情自然也就好起來了。\r\n\r\n【咖波帶你遊中市圖】 2F文學區\r\n本次「咖波帶你遊中市圖」特色書展，主要書籍方向以圖文書及臺語圖文書為主，帶給您滿滿的療癒感！\r\n將串聯中市圖各分館，讓您不管到哪一個分館都能感受到該分館的特色以外，還能常常看到咖波呦！\r\n其中也歡迎大家來到精武圖書館，感受本館特色：台中學及台中作家的特色館藏。', '臺中市精武圖書館', '臺中市北區精武路291之3號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺中市精武圖書館', 24.15863985, 120.6809521, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='精武圖書館-4月書展', `description`='【擁有童一片星空】 1F歲月流金區\r\n\r\n精武圖書館在今年的兒童節主題書展，邀請讀者一同走進星空書展的奇幻世界。無論你是對太空人的冒險心生向往，還是沉浸於月亮與雲朵的浪漫，這裡都能找到屬於你的故事與奇遇。書展中的每個角落，都藏著一個未知小宇宙，等著你來探索。\r\n\r\n【食在好新情】 2F文學區\r\n本次書展以香料、料理、味覺科普為主軸，\r\n帶領讀者從飲食層面認識新住民文化，\r\n香香辣辣的料理，如其人文風情熱情洋溢，\r\n不只胃開了，心花也開了，心情自然也就好起來了。\r\n\r\n【咖波帶你遊中市圖】 2F文學區\r\n本次「咖波帶你遊中市圖」特色書展，主要書籍方向以圖文書及臺語圖文書為主，帶給您滿滿的療癒感！\r\n將串聯中市圖各分館，讓您不管到哪一個分館都能感受到該分館的特色以外，還能常常看到咖波呦！\r\n其中也歡迎大家來到精武圖書館，感受本館特色：台中學及台中作家的特色館藏。', `organizer`='臺中市精武圖書館', `address`='臺中市北區精武路291之3號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市精武圖書館', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e327a026b32419285b729c', '2025 文化創意產業永續與前瞻學術研討會', '會議主題：『文化、數位+融合轉譯』\r\n研討會子題：\r\n子題一　文創產業經營&文創行銷    \r\n子題二　文物普查&文化資產\r\n子題三　數位內容&AI科技融合        \r\n子題四　文化協作&跨領域\r\n子題五　文化美學&價值創造', '國立屏東大學', '屏東縣屏東市民生路4-18號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '國立屏東大學', 22.6558442, 120.4703258, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 文化創意產業永續與前瞻學術研討會', `description`='會議主題：『文化、數位+融合轉譯』\r\n研討會子題：\r\n子題一　文創產業經營&文創行銷    \r\n子題二　文物普查&文化資產\r\n子題三　數位內容&AI科技融合        \r\n子題四　文化協作&跨領域\r\n子題五　文化美學&價值創造', `organizer`='國立屏東大學', `address`='屏東縣屏東市民生路4-18號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='國立屏東大學', `latitude`=22.6558442, `longitude`=120.4703258, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e327a126b32419285b72a7', '『2024 Openbook 好書獎』書展', '精選4大類Openbook年度選書\r\n年度中文創作\r\n年度翻譯書\r\n年度生活書 \r\n年度童書／年度青少年圖書 \r\n\r\nOpenbook閱讀誌『強調公正、客觀的年度好書評選，希望藉此推廣閱讀，鼓勵優秀作家及出版社。』\r\n評選對象：前一年度11/1之後，至當年度10/31期間，於台灣出版或代理銷售的繁體中文著作。\r\n初選：從2521本書中，選出526本成人書、242本童書\r\n複選：從768本書中，選出202本決選入圍名單\r\n決選：從202本好書中精選出4大類Openbook年度選書\r\n更多完整介紹\r\nhttps://www.openbook.org.tw/2024openbookaward\r\n活動洽詢：049-2791534洽陳小姐。', '南投縣信義鄉公所', '南投縣信義鄉玉山路47號', '2025-03-21 00:00:00', '2025-04-25 00:00:00', '南投縣信義鄉立圖書館', 23.6967966, 120.8545567, '無資料', 'https://www.facebook.com/profile.php?id=100063692516610#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='『2024 Openbook 好書獎』書展', `description`='精選4大類Openbook年度選書\r\n年度中文創作\r\n年度翻譯書\r\n年度生活書 \r\n年度童書／年度青少年圖書 \r\n\r\nOpenbook閱讀誌『強調公正、客觀的年度好書評選，希望藉此推廣閱讀，鼓勵優秀作家及出版社。』\r\n評選對象：前一年度11/1之後，至當年度10/31期間，於台灣出版或代理銷售的繁體中文著作。\r\n初選：從2521本書中，選出526本成人書、242本童書\r\n複選：從768本書中，選出202本決選入圍名單\r\n決選：從202本好書中精選出4大類Openbook年度選書\r\n更多完整介紹\r\nhttps://www.openbook.org.tw/2024openbookaward\r\n活動洽詢：049-2791534洽陳小姐。', `organizer`='南投縣信義鄉公所', `address`='南投縣信義鄉玉山路47號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='南投縣信義鄉立圖書館', `latitude`=23.6967966, `longitude`=120.8545567, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100063692516610#', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e327a126b32419285b72a8', '114年小小館員閱讀推廣體驗活動 ', '這是一場超級有趣的小小館員體驗活動，讓小朋友體驗圖書館各種工作任務，並邀請家長們共同參加！\r\n活動內容：\r\n讓小小館員親身體驗圖書館的借還書及日常工作！圖書館還準備了有趣的馬口鐵磁鐵DIY親子活動及闖關遊戲！通過解決各種有趣的題目和挑戰，您可以展現自己的智慧和技巧，同時在親子互動中一起度過愉快的時光。\r\n參加對象：親子組(祖)父或(祖)母一人及小小館員(幼兒園大班至小學四年級)一人。\r\n請家長務必攜帶「借閱證或身分證」當日報到。\r\n報名名額：12組\r\n報名時間：114年4月3日（四）起，免費參加，額滿為止。\r\n報名地點：南投市立圖書館。僅限現場報名，不接受電話、傳真報名。\r\n歡迎來和我們一起探索閱讀的樂趣，一起成為一日小小館員吧！活動詳情請參閱簡章及活動需知 ', '南投縣南投市公所', '南投縣南投市漳興巷51號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '南投市立圖書館（臨時圖書館）', 23.9146117, 120.680837, '無資料', 'https://www.facebook.com/profile.php?id=100064333496575#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年小小館員閱讀推廣體驗活動 ', `description`='這是一場超級有趣的小小館員體驗活動，讓小朋友體驗圖書館各種工作任務，並邀請家長們共同參加！\r\n活動內容：\r\n讓小小館員親身體驗圖書館的借還書及日常工作！圖書館還準備了有趣的馬口鐵磁鐵DIY親子活動及闖關遊戲！通過解決各種有趣的題目和挑戰，您可以展現自己的智慧和技巧，同時在親子互動中一起度過愉快的時光。\r\n參加對象：親子組(祖)父或(祖)母一人及小小館員(幼兒園大班至小學四年級)一人。\r\n請家長務必攜帶「借閱證或身分證」當日報到。\r\n報名名額：12組\r\n報名時間：114年4月3日（四）起，免費參加，額滿為止。\r\n報名地點：南投市立圖書館。僅限現場報名，不接受電話、傳真報名。\r\n歡迎來和我們一起探索閱讀的樂趣，一起成為一日小小館員吧！活動詳情請參閱簡章及活動需知 ', `organizer`='南投縣南投市公所', `address`='南投縣南投市漳興巷51號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='南投市立圖書館（臨時圖書館）', `latitude`=23.9146117, `longitude`=120.680837, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064333496575#', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e327a126b32419285b72aa', '澎湖縣政府文化局4月份影片欣賞', '本片為澎湖縣文化局例行性播放影片，歡迎民眾踴躍前往觀賞。4月12日：阿波羅男孩 （普） 范瑞君、巫建和（臺灣）。4月19日：我們買了動物園（普）麥特．戴蒙、史嘉蕾．喬韓森（美國）。4月26日：勇鼠闖天堂 （普）德妮莎格林莫娃(美國）。\r\n', '澎湖縣政府文化局', '澎湖縣馬公市中華路236之1號', '2025-04-12 00:00:00', '2025-04-26 00:00:00', '澎湖縣圖書館', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='澎湖縣政府文化局4月份影片欣賞', `description`='本片為澎湖縣文化局例行性播放影片，歡迎民眾踴躍前往觀賞。4月12日：阿波羅男孩 （普） 范瑞君、巫建和（臺灣）。4月19日：我們買了動物園（普）麥特．戴蒙、史嘉蕾．喬韓森（美國）。4月26日：勇鼠闖天堂 （普）德妮莎格林莫娃(美國）。\r\n', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路236之1號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='澎湖縣圖書館', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e327a126b32419285b72ab', '澎湖縣圖書館4月天人菊說故事劇坊 ', '研習課程內容，說故事的技巧、圖畫書口述故事技巧、簡易道具偶說演故事技巧等相關課程。4月6日小黃點大冒險 。4月13日莎莎奇遇記。4月20日媽媽的驚喜之旅（好夢幻喔）。4月27日五歲老奶奶去釣魚。', '澎湖縣政府文化局', '澎湖縣馬公市中華路236之1號', '2025-04-06 00:00:00', '2025-04-27 00:00:00', '澎湖縣圖書館', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='澎湖縣圖書館4月天人菊說故事劇坊 ', `description`='研習課程內容，說故事的技巧、圖畫書口述故事技巧、簡易道具偶說演故事技巧等相關課程。4月6日小黃點大冒險 。4月13日莎莎奇遇記。4月20日媽媽的驚喜之旅（好夢幻喔）。4月27日五歲老奶奶去釣魚。', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路236之1號', `start_date`='2025-04-06 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='澎湖縣圖書館', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e327a126b32419285b72ac', '114年工藝校園扎根．種子教師培育計畫：草木染教師培力工作坊（4月16日13:00線上報名） ', '為推動工藝融入學校教育，促進工藝美學校園扎根，透過手作體驗課程，培育學校教師成為種子教師，並回到教學現場發展工藝體驗課程，傳遞工藝所能帶來的生活連結與美好體驗，誘發學生「動手做工藝」的學習興趣，開啟工藝與教育融合共好的無限可能性！\r\n課程內容：\r\n運用含單寧的植物來萃取染液，用生活周邊易取得植物少許的花、葉來取其型態與色素，尊重植物且延續其生命，利用植物自帶的型體來染製生活所需物品，所有資源循環再利用。\r\n5/17（六）\r\n植物染概論概論、棉布精練、各染法作品解說、認識植物與採集後處理\r\n無媒染圍巾示範與實作、萃取染液、綁布技法示範與實作\r\n5/18（日）\r\n染前媒染、染色工程\r\n染後媒染、後媒染染色工程\r\n5/24（六）\r\n單寧染材萃取、植物採集、鐵媒染圍巾示範與實作\r\n植物性纖維生態印染示範與實作\r\n5/25（日）\r\n動物性纖維染前處理與實作\r\n植物性纖維後加工\r\n\r\n招生對象：幼稚園、國小、國中及高級中等學校之教師\r\n招收人數：20人(6人開班)\r\n報名方式：於4/16（三）下午1點起在【全國教師在職進修資訊網】線上報名。【課程代碼：4971564】\r\n錄取方式：為落實工藝校園扎根政策推動所需，主辦單位得保留一半名額供本中心培育之種子教師課程實踐者或具有工藝校園扎根潛力者優先錄取（需回填學習動機以及教學實踐成果，俾利審核），其餘名額則依報名優先順序錄取，錄取名單請至至【全國教師在職進修資訊網】查詢。\r\n(提醒:欲爭取實踐者及潛力者優先名額者，仍需至教師網報名)\r\n洽詢專線：049-2334141*312張小姐。', '國立臺灣工藝研究發展中心', '南投縣草屯鎮中正路573號', '2025-05-17 00:00:00', '2025-05-25 00:00:00', '國立臺灣工藝研究發展中心（臺灣工藝文化園區）', 23.9807747, 120.6918567, '學雜費+588;材料費+3000', 'https://www.ntcri.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年工藝校園扎根．種子教師培育計畫：草木染教師培力工作坊（4月16日13:00線上報名） ', `description`='為推動工藝融入學校教育，促進工藝美學校園扎根，透過手作體驗課程，培育學校教師成為種子教師，並回到教學現場發展工藝體驗課程，傳遞工藝所能帶來的生活連結與美好體驗，誘發學生「動手做工藝」的學習興趣，開啟工藝與教育融合共好的無限可能性！\r\n課程內容：\r\n運用含單寧的植物來萃取染液，用生活周邊易取得植物少許的花、葉來取其型態與色素，尊重植物且延續其生命，利用植物自帶的型體來染製生活所需物品，所有資源循環再利用。\r\n5/17（六）\r\n植物染概論概論、棉布精練、各染法作品解說、認識植物與採集後處理\r\n無媒染圍巾示範與實作、萃取染液、綁布技法示範與實作\r\n5/18（日）\r\n染前媒染、染色工程\r\n染後媒染、後媒染染色工程\r\n5/24（六）\r\n單寧染材萃取、植物採集、鐵媒染圍巾示範與實作\r\n植物性纖維生態印染示範與實作\r\n5/25（日）\r\n動物性纖維染前處理與實作\r\n植物性纖維後加工\r\n\r\n招生對象：幼稚園、國小、國中及高級中等學校之教師\r\n招收人數：20人(6人開班)\r\n報名方式：於4/16（三）下午1點起在【全國教師在職進修資訊網】線上報名。【課程代碼：4971564】\r\n錄取方式：為落實工藝校園扎根政策推動所需，主辦單位得保留一半名額供本中心培育之種子教師課程實踐者或具有工藝校園扎根潛力者優先錄取（需回填學習動機以及教學實踐成果，俾利審核），其餘名額則依報名優先順序錄取，錄取名單請至至【全國教師在職進修資訊網】查詢。\r\n(提醒:欲爭取實踐者及潛力者優先名額者，仍需至教師網報名)\r\n洽詢專線：049-2334141*312張小姐。', `organizer`='國立臺灣工藝研究發展中心', `address`='南投縣草屯鎮中正路573號', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='國立臺灣工藝研究發展中心（臺灣工藝文化園區）', `latitude`=23.9807747, `longitude`=120.6918567, `ticket_price`='學雜費+588;材料費+3000', `source_url`='https://www.ntcri.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e327a226b32419285b72ae', '日月潭街頭藝人表演-車埕文化廣場（114年5月）', '演出團體及演出時間請至日月潭觀光旅遊網查詢。', '交通部觀光署日月潭國家風景區管理處', '南投縣水里鄉', '2025-05-01 00:00:00', '2025-05-31 00:00:00', '水里鄉（南投縣）=', 23.79612907, 120.8622721, '無資料', 'https://www.sunmoonlake.gov.tw/zh-tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='日月潭街頭藝人表演-車埕文化廣場（114年5月）', `description`='演出團體及演出時間請至日月潭觀光旅遊網查詢。', `organizer`='交通部觀光署日月潭國家風景區管理處', `address`='南投縣水里鄉', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='水里鄉（南投縣）=', `latitude`=23.79612907, `longitude`=120.8622721, `ticket_price`='無資料', `source_url`='https://www.sunmoonlake.gov.tw/zh-tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e327a226b32419285b72af', '日月潭街頭藝人表演-文武廟、伊達邵碼頭、水社碼頭、玄光寺碼頭（114年5月）', '安排動、靜態街頭藝人展演，詳細演出團體及演出時間請上日月潭觀光旅遊網-最新快訊查詢。\r\n演出地點：文武廟廣場、水社碼頭廣場、伊達邵碼頭廣場、玄光寺碼頭。', '交通部觀光署日月潭國家風景區管理處', '南投縣魚池鄉中山路', '2025-05-01 00:00:00', '2025-05-31 00:00:00', '日月潭國家風景區', 23.8565133, 120.9021315, '無資料', 'https://www.sunmoonlake.gov.tw/zh-tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='日月潭街頭藝人表演-文武廟、伊達邵碼頭、水社碼頭、玄光寺碼頭（114年5月）', `description`='安排動、靜態街頭藝人展演，詳細演出團體及演出時間請上日月潭觀光旅遊網-最新快訊查詢。\r\n演出地點：文武廟廣場、水社碼頭廣場、伊達邵碼頭廣場、玄光寺碼頭。', `organizer`='交通部觀光署日月潭國家風景區管理處', `address`='南投縣魚池鄉中山路', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='日月潭國家風景區', `latitude`=23.8565133, `longitude`=120.9021315, `ticket_price`='無資料', `source_url`='https://www.sunmoonlake.gov.tw/zh-tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3287a26b32419285b72b2', '謝墨序', '\n畢業展為創作生涯的一個里程碑。不僅是對四年學習的總結,更是他們藝術之旅的序幕,一個新的開始。展覽以墨作為媒介,串聯了每位學生的作品,更凸顯了書畫的傳統色彩,使觀眾深入了解作品的創作背景和意義。\nA graduation exhibition is a milestone in an artist’s journey. It is not only a culmination of four years of study but also the prologue to their artistic endeavors—a new beginning. Using ink as the primary medium, this exhibition connects each student’s work, highlighting the traditional essence of painting and calligraphy while offering deeper insight into their creative backgrounds and artistic meanings.\n', '無資料', '臺北市南海路四十七號', '2025-04-30 00:00:00', '2025-05-06 00:00:00', '第1、2展覽廳', 25.032319, 121.51206, '無資料', 'https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4431', '[]') ON DUPLICATE KEY UPDATE `activity_name`='謝墨序', `description`='\n畢業展為創作生涯的一個里程碑。不僅是對四年學習的總結,更是他們藝術之旅的序幕,一個新的開始。展覽以墨作為媒介,串聯了每位學生的作品,更凸顯了書畫的傳統色彩,使觀眾深入了解作品的創作背景和意義。\nA graduation exhibition is a milestone in an artist’s journey. It is not only a culmination of four years of study but also the prologue to their artistic endeavors—a new beginning. Using ink as the primary medium, this exhibition connects each student’s work, highlighting the traditional essence of painting and calligraphy while offering deeper insight into their creative backgrounds and artistic meanings.\n', `organizer`='無資料', `address`='臺北市南海路四十七號', `start_date`='2025-04-30 00:00:00', `end_date`='2025-05-06 00:00:00', `location`='第1、2展覽廳', `latitude`=25.032319, `longitude`=121.51206, `ticket_price`='無資料', `source_url`='https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4431', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3287a26b32419285b72b3', '靜觀心藝學生書畫展', '\n靜心高中學生的美術創作作品，透過中小學學生作品交流，促進校園藝術學習氛圍，實踐美感教育。學生從作品創作到展覽規劃、現場佈置、展覽開幕都參與其中，學習並實踐策畫展覽的能力。\nThis exhibition showcases the artistic creations of students from Chingshin Academy. Through the exchange of artworks between elementary and secondary school students, the exhibition fosters an enriching artistic learning atmosphere on campus and promotes aesthetic education. Students actively participate in all aspects of the exhibition, from art creation and exhibition planning, to setup and the opening event, gaining hands-on experience in curating exhibitions.\n', '無資料', '臺北市南海路四十七號', '2025-04-30 00:00:00', '2025-05-11 00:00:00', '美學空間', 25.032319, 121.51206, '無資料', 'https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4435', '[]') ON DUPLICATE KEY UPDATE `activity_name`='靜觀心藝學生書畫展', `description`='\n靜心高中學生的美術創作作品，透過中小學學生作品交流，促進校園藝術學習氛圍，實踐美感教育。學生從作品創作到展覽規劃、現場佈置、展覽開幕都參與其中，學習並實踐策畫展覽的能力。\nThis exhibition showcases the artistic creations of students from Chingshin Academy. Through the exchange of artworks between elementary and secondary school students, the exhibition fosters an enriching artistic learning atmosphere on campus and promotes aesthetic education. Students actively participate in all aspects of the exhibition, from art creation and exhibition planning, to setup and the opening event, gaining hands-on experience in curating exhibitions.\n', `organizer`='無資料', `address`='臺北市南海路四十七號', `start_date`='2025-04-30 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='美學空間', `latitude`=25.032319, `longitude`=121.51206, `ticket_price`='無資料', `source_url`='https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4435', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e3287a26b32419285b72b5', '還沒找到獨角獸創作聯展', '\n集結7位藝術家聯合展覽，透過獨角獸這一象徵性符號，探索人類對自由、美好、以及身份認同的追求。獨角獸作為一個跨文化的神話生物，邀請大家思考理想與現實之間的距離，並在藝術的世界中尋找到內心的共鳴。\nBringing together seven artists, this exhibition explores humanity''s pursuit of freedom, beauty, and identity through the symbolic figure of the unicorn. As a cross-cultural mythical creature, the unicorn invites reflection on the gap between ideals and reality, offering a space in the art world where audiences can find resonance within themselves.\n', '無資料', '臺北市南海路四十七號', '2025-04-19 00:00:00', '2025-04-27 00:00:00', '第3展覽廳', 25.032319, 121.51206, '無資料', 'https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4433', '[]') ON DUPLICATE KEY UPDATE `activity_name`='還沒找到獨角獸創作聯展', `description`='\n集結7位藝術家聯合展覽，透過獨角獸這一象徵性符號，探索人類對自由、美好、以及身份認同的追求。獨角獸作為一個跨文化的神話生物，邀請大家思考理想與現實之間的距離，並在藝術的世界中尋找到內心的共鳴。\nBringing together seven artists, this exhibition explores humanity''s pursuit of freedom, beauty, and identity through the symbolic figure of the unicorn. As a cross-cultural mythical creature, the unicorn invites reflection on the gap between ideals and reality, offering a space in the art world where audiences can find resonance within themselves.\n', `organizer`='無資料', `address`='臺北市南海路四十七號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='第3展覽廳', `latitude`=25.032319, `longitude`=121.51206, `ticket_price`='無資料', `source_url`='https://www.arte.gov.tw/pro1_exh_now.asp?KeyID=4433', `image_url`='[]';
