INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e473fd26b32419285b72d6', 'True Colors真實色彩-林時植陶藝複合媒材創作展', '文化部所屬國立彰化生活美學館自114年4月10日至5月25日，在該館第一、二展覽室舉辦「True Colors真實色彩—林時植陶藝複合媒材創作展」，展出玄奘大學藝術與創意設計學系林時植老師的系列創作。本次展出的《異域》及《真實色彩》系列，運用了金工鐵件與陶藝雕塑的材質及手法，並巧妙地融合為一。林時植認為本次的展覽，是一次關於人性與未來的探索，帶領觀者穿越悲觀與希望交織的深淵，以全新的視角思考我們與地球的關係。\n\n林時植將性質看似對立的陶藝與金屬結合，用衝突的強烈張力，以魔幻寫實的手法，演譯末日世界的悲劇，以及人類缺席後的新生與希望。常溫下，陶土柔軟可塑、金屬冰冷剛硬；但歷經高溫淬鍊，陶器卻能定型堅固、金屬反倒柔韌如水。正是這種既衝突又互補的關係，精準演示出劫後餘生的悲與喜。透過這樣的創作，林時植希望喚醒人們對環境保護的重視，同時對未來的文明模式進行深刻的反思，為這個時代留下更多可能性的解答。\n\n \n\n \n\n ', '國立彰化生活美學館', '500  彰化縣彰化市74卦山路18號', '2025-04-10 00:00:00', '2025-05-25 00:00:00', '國立彰化生活美學館第一、二展覽室', 24.0765278, 120.5573442, '無資料', 'https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50357', '[]') ON DUPLICATE KEY UPDATE `activity_name`='True Colors真實色彩-林時植陶藝複合媒材創作展', `description`='文化部所屬國立彰化生活美學館自114年4月10日至5月25日，在該館第一、二展覽室舉辦「True Colors真實色彩—林時植陶藝複合媒材創作展」，展出玄奘大學藝術與創意設計學系林時植老師的系列創作。本次展出的《異域》及《真實色彩》系列，運用了金工鐵件與陶藝雕塑的材質及手法，並巧妙地融合為一。林時植認為本次的展覽，是一次關於人性與未來的探索，帶領觀者穿越悲觀與希望交織的深淵，以全新的視角思考我們與地球的關係。\n\n林時植將性質看似對立的陶藝與金屬結合，用衝突的強烈張力，以魔幻寫實的手法，演譯末日世界的悲劇，以及人類缺席後的新生與希望。常溫下，陶土柔軟可塑、金屬冰冷剛硬；但歷經高溫淬鍊，陶器卻能定型堅固、金屬反倒柔韌如水。正是這種既衝突又互補的關係，精準演示出劫後餘生的悲與喜。透過這樣的創作，林時植希望喚醒人們對環境保護的重視，同時對未來的文明模式進行深刻的反思，為這個時代留下更多可能性的解答。\n\n \n\n \n\n ', `organizer`='國立彰化生活美學館', `address`='500  彰化縣彰化市74卦山路18號', `start_date`='2025-04-10 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='國立彰化生活美學館第一、二展覽室', `latitude`=24.0765278, `longitude`=120.5573442, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CHCSEC/Detail.init.ctr?actId=50357', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e4740626b32419285b72d7', '114年故事「堂」果屋閱讀推廣活動', '►【1】友善平權尋寶趣 \n\n\n	時間：4/22(二)  09:30-10:30\n	講師：何昱奇老師 / 國立中正紀念堂管理處\n	人數：預計招收約60位幼兒\n	共讀文本：《從小學會說友善的話》繪本\n	延伸活動：帶領孩子認識中正紀念堂各項友善措施，並學習簡易臺灣台語詞彙\n	本場次為響應「4月23日世界閱讀日」所策辦之主題活動\n\n\n \n\n►【2】孵畫我的蛋 \n\n\n	時間：5/13(二)  10:00-11:00\n	講師：陳昱諴老師、謝瑋倫老師 / 國立中正紀念堂管理處\n	人數：預計招收約40位幼兒\n	共讀文本：《紅公雞》繪本\n	延伸活動：帶領孩子設計畫上自己的蛋，並在繪畫後進行分享，並學習簡易臺灣台語詞彙\n	本場次為響應「5月18日國際博物館日」所策辦之主題活動\n\n\n \n\n►【3】海洋環保大解密 \n\n\n	時間：6/5(四)  09:30-10:30\n	講師：楊柏軒老師 / 國立中正紀念堂管理處\n	人數：預計招收約60位幼兒\n	共讀文本：《我們製造的垃圾》繪本\n	延伸活動：帶領孩子欣賞環境教育相關影片，讓孩子更深入認識永續環保議題\n	本場次為響應「6月5日世界環境日」所策辦之主題活動\n\n\n \n\n►【4】童心同行 \n\n\n	時間：9/12(五)  09:30-10:30\n	講師：張麗英老師 / 新北市立圖書館總館新住民故事媽媽、曾任移民署緬甸通譯員\n	人數：預計招收約40位幼兒\n	共讀文本：《蕃薯村總動員》繪本\n	延伸活動：帶領孩子透過手作緬甸天然乳液、印章，認識緬甸文化與人文風情\n	本場次為響應「9月21日國際和平日」所策辦之主題活動\n\n\n \n\n►【5】天上飛來飛去的阿里棒棒 \n\n\n	時間：10/17(五)  09:30-10:30\n	講師：李庭語老師 / 花蓮玉里阿美族，臺北市北投區關渡國民小學說故事志工媽媽\n	人數：預計招收約40位幼兒\n	共讀文本：《天上飛來的魚》繪本\n	延伸活動：帶領孩子手作飛魚剪貼與著色，讓孩子更深入認識臺灣原住民族文化，並學習簡易臺灣原住民語詞彙。\n	本場次為響應「10月17日臺灣文化日」所策辦之主題活動\n\n\n \n\n►【6】點亮一盞「新」燈 \n\n\n	時間：11/14(五)  09:30-10:30\n	講師：梁麗群老師 / 南洋台灣姊妹會理事、新北市立圖書館總館新住民故事媽媽、國立臺灣博物館(本館)導覽大使\n	人數：預計招收約40位幼兒\n	共讀文本：講師自製結合兒童人權及新二代主題之文本\n	延伸活動：帶領孩子手作柬埔寨祈福水燈，讓孩子能深入認識兒童人權議題及柬埔寨文化與人文風情。\n	本場次為響應「11月20日國際兒童人權日」所策辦之主題活動\n\n\n\n交通資訊及圖書室位置詳參下方連結\n\n\n	地理及交通資訊(請點我)\n	堂內平面圖(請點我)\n	堂內圖書室(位於1樓的三展廳內)位置圖：', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-04-22 00:00:00', '2025-04-22 00:00:00', '堂內圖書室(1樓的三展廳內)', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50755', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年故事「堂」果屋閱讀推廣活動', `description`='►【1】友善平權尋寶趣 \n\n\n	時間：4/22(二)  09:30-10:30\n	講師：何昱奇老師 / 國立中正紀念堂管理處\n	人數：預計招收約60位幼兒\n	共讀文本：《從小學會說友善的話》繪本\n	延伸活動：帶領孩子認識中正紀念堂各項友善措施，並學習簡易臺灣台語詞彙\n	本場次為響應「4月23日世界閱讀日」所策辦之主題活動\n\n\n \n\n►【2】孵畫我的蛋 \n\n\n	時間：5/13(二)