INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e4741426b32419285b72da', '鐵道部園區-去去秘境走', ' 鐵道部園區的屋桁架及戰時指揮中心因內部空間較其他辦公廳舍狹小且陡峭，平時導覽僅限外觀介紹。\n\n本專場活動將參觀平日未開放的「戰時指揮中心(防空洞)」以及隱藏在廳舍中的第3層樓「屋桁架」，邀請大家一同見證鐵道部園區歷經多年的調查、修復後，重現臺灣近代社會百年歷程的演進。\n\n \n\n歡迎預先下載「臺博數位導覽APP」，搭配參觀。\n\niOS版       https://reurl.cc/vvjDma\n\nAndroid版 https://reurl.cc/ey4xWR\n\n \n\n\n	\n		\n			日期\n			時間\n			導覽路線\n		\n		\n			4/13(日)\n			14:00-15:00\n			八角樓(報到)→工務室 古蹟修復展示工坊→ 屋桁架 \n		\n		\n			15:30-16:30\n			八角樓(報到)→工務室 古蹟修復展示工坊→ 戰時指揮中心 \n		\n		\n			4/20(日)\n			11:00-12:00\n			八角樓(報到)→工務室 古蹟修復展示工坊→ 屋桁架 \n		\n		\n			14:00-15:00\n			\n			八角樓(報到)→工務室 古蹟修復展示工坊→ 戰時指揮中心  \n			\n		\n	\n\n\n \n\n\n\n \n\n\n\n \n\n \n\n \n\n \n\n \n\n \n\n ', '國立臺灣博物館', '大同區延平北路一段2號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '臺博館鐵道部園區', 25.0486841, 121.5112965, '無資料', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=50082', '[]') ON DUPLICATE KEY UPDATE `activity_name`='鐵道部園區-去去秘境走', `description`=' 鐵道部園區的屋桁架及戰時指揮中心因內部空間較其他辦公廳舍狹小且陡峭，平時導覽僅限外觀介紹。\n\n本專場活動將參觀平日未開放的「戰時指揮中心(防空洞)」以及隱藏在廳舍中的第3層樓「屋桁架」，邀請大家一同見證鐵道部園區歷經多年的調查、修復後，重現臺灣近代社會百年歷程的演進。\n\n \n\n歡迎預先下載「臺博數位導覽APP」，搭配參觀。\n\niOS版       https://reurl.cc/vvjDma\n\nAndroid版 https://reurl.cc/ey4xWR\n\n \n\n\n	\n		\n			日期\n			時間\n			導覽路線\n		\n		\n			4/13(日)\n			14:00-15:00\n			八角樓(報到)→工務室 古蹟修復展示工坊→ 屋桁架 \n		\n		\n			15:30-16:30\n			八角樓(報到)→工務室 古蹟修復展示工坊→ 戰時指揮中心 \n		\n		\n			4/20(日)\n			11:00-12:00\n			八角樓(報到)→工務室 古蹟修復展示工坊→ 屋桁架 \n		\n		\n			14:00-15:00\n			\n			八角樓(報到)→工務室 古蹟修復展示工坊→ 戰時指揮中心  \n			\n		\n	\n\n\n \n\n\n\n \n\n\n\n \n\n \n\n \n\n \n\n \n\n \n\n ', `organizer`='國立臺灣博物館', `address`='大同區延平北路一段2號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺博館鐵道部園區', `latitude`=25.0486841, `longitude`=121.5112965, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.