INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474f426b32419285b72fa', '心懷翠巒 香遺人間 - 游景翔創作個展', '貝殼、葫蘆、刀柄可以雕刻心經，黑色鉛筆芯也可以創作，這是師法自然的微雕藝術家游景翔之作。本次展覽藝術家游景翔以深情的創作，追憶母親堅韌偉大的形象與永恆馨香的品德。\r\n\r\n「心懷翠巒」象徵母愛如山般穩重深厚，「香遺人間」訴說母親高尚品格的深遠影響。每件作品蘊含藝術家對母親的深刻思念，並傳遞母愛的溫暖與普世價值。\r\n\r\n此次展覽不僅是對個人記憶的致敬，更是一場關於愛與生命的藝術對話，帶領觀眾汲取前行的力量與靈感。', '佛光山惠中寺', '臺中市南屯區惠中路三段65號', '2025-03-20 00:00:00', '2025-04-20 00:00:00', '佛光緣美術館台中館', 24.14165524, 120.6177379, '無資料', 'https://www.facebook.com/share/p/1BEe5SCKYN/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='心懷翠巒 香遺人間 - 游景翔創作個展', `description`='貝殼、葫蘆、刀柄可以雕刻心經，黑色鉛筆芯也可以創作，這是師法自然的微雕藝術家游景翔之作。本次展覽藝術家游景翔以深情的創作，追憶母親堅韌偉大的形象與永恆馨香的品德。\r\n\r\n「心懷翠巒」象徵母愛如山般穩重深厚，「香遺人間」訴說母親高尚品格的深遠影響。每件作品蘊含藝術家對母親的深刻思念，並傳遞母愛的溫暖與普世價值。\r\n\r\n此次展覽不僅是對個人記憶的致敬，更是一場關於愛與生命的藝術對話，帶領觀眾汲取前行的力量與靈感。', `organizer`='佛光山惠中寺', `address`='臺中市南屯區惠中路三段65號', `start_date`='2025-03-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='佛光緣美術館台中館', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1BEe5SCKYN/', `image_url`='[]';
