INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fa26b32419285b730a', '114年4月電影饗宴(2場)', '【電影饗宴】\r\n電影名稱：超人力霸王德卡最終章:朝向旅程的遠方\r\n播放日期：2025/04/06(日)\r\n播放時間：早上10:00-12:00\r\n電影片長：75分鐘\r\n電影簡介：\r\n一道詭異的聲音響徹天空。聽到這聲音的人紛紛失去知覺，最後甚至消失無蹤。前往調查的專家小組「GUTS-SELECT」，遇到的卻是接二連三來襲的外星人大軍，以及駕駛漆黑要塞型太空艦「佐爾加烏斯」，扭曲了地球天空的統治者「基貝魯斯教授」。一位認識基貝魯斯的神秘女子突然降臨在苦苦奮戰中的奏大等人面前。這位擁有神奇力量的女子名叫帝納斯，她和GUTS-SELECT聯手，懷著「守護的使命」，合力對抗敵人殘暴的計畫，然而此時一片陰影卻籠罩了天空，這片陰影來自於力量足以扭曲整個銀河的兇暴「皇獸」。\r\n\r\n電影名稱：月球歷險記\r\n播放日期：2025/04/20(日)\r\n播放時間：早上10:00-12:00\r\n電影片長：84分鐘\r\n電影簡介：\r\n有時候聽妹妹的話會比較保險！身為太空迷彼德在某個夜晚發現妹妹不見了，他才突然意識到妹妹之前瘋狂談論的會說話的六月金龜子「樹樹蟲」並不是虛構的。於是，彼德踏上了月球之旅，要將妹妹從大壞蛋「月人」手中拯救出來。旅途中他遇到了許多自然界的神靈，也才發現自己一直忽視了妹妹…\r\n', '臺中市立圖書館中區分館', '臺中市中區成功路300號7樓', '2025-04-06 00:00:00', '2025-04-20 00:00:00', '臺中市立圖書館中區分館', 24.14168566, 120.680598, '無資料', 'https://reurl.cc/zqbM9y', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年4月電影饗宴(2場)', `description`='【電影饗宴】\r\n電影名稱：超人力霸王德卡最終章:朝向旅程的遠方\r\n播放日期：2025/04/06(日)\r\n播放時間：早上10:00-12:00\r\n電影片長：75分鐘\r\n電影簡介：\r\n一道詭異的聲音響徹天空。聽到這聲音的人紛紛失去知覺，最後甚至消失無蹤。前往調查的專家小組「GUTS-SELECT」，遇到的卻是接二連三來襲的外星人大軍，以及駕駛漆黑要塞型太空艦「佐爾加烏斯」，扭曲了地球天空的統治者「基貝魯斯教授」。一位認識基貝魯斯的神秘女子突然降臨在苦苦奮戰中的奏大等人面前。這位擁有神奇力量的女子名叫帝納斯，她和GUTS-SELECT聯手，懷著「守護的使命」，合力對抗敵人殘暴的計畫，然而此時一片陰影卻籠罩了天空，這片陰影來自於力量足以扭曲整個銀河的兇暴「皇獸」。\r\n\r\n電影名稱：月球歷險記\r\n播放日期：2025/04/20(日)\r\n播放時間：早上10:00-12:00\r\n電影片長：84分鐘\r\n電影簡介：\r\n有時候聽妹妹的話會比較保險！身為太空迷彼德在某個夜晚發現妹妹不見了，他才突然意識到妹妹之前瘋狂談論的會說話的六月金龜子「樹樹蟲」並不是虛構的。於是，彼德踏上了月球之旅，要將妹妹從大壞蛋「月人」手中拯救出來。旅途中他遇到了許多自然界的神靈，也才發現自己一直忽視了妹妹…\r\n', `organizer`='臺中市立圖書館中區分館', `address`='臺中市中區成功路300號7樓', `start_date`='2025-04-06 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺中市立圖書館中區分館', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='https://reurl.cc/zqbM9y', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fa26b32419285b730c', '高雄市立圖書館大樹三館114年4月主題書展', '1.【SDGs#3(良好健康與社會福祉)主題書展】--因應聯合國2015年宣佈「2030永續發展目標」中第三項目標，確保健康的生活，促進各年齡階段人口的福祉，特展出情緒、規律運動、健康飲食、睡眠等相關書籍，供民眾翻閱。\r\n2.東南亞文化主題書展〜發現「馬」、「新」 文化寶藏--藉由展示書籍，推廣馬來西亞和新加坡的文化與文學提升大眾對這兩個國家的認知與欣賞；增進對東南亞文化的理解與認識的絕佳機會。', '高雄市立圖書館總館', '高雄市大樹區溪埔路77號3樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '高雄市立圖書館大樹三館', 22.71100364, 120.425407, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市立圖書館大樹三館114年4月主題書展', `description`='1.【SDGs#3(良好健康與社會福祉)主題書展】--因應聯合國2015年宣佈「2030永續發展目標」中第三項目標，確保健康的生活，促進各年齡階段人口的福祉，特展出情緒、規律運動、健康飲食、睡眠等相關書籍，供民眾翻閱。\r\n2.東南亞文化主題書展〜發現「馬」、「新」 文化寶藏--藉由展示書籍，推廣馬來西亞和新加坡的文化與文學提升大眾對這兩個國家的認知與欣賞；增進對東南亞文化的理解與認識的絕佳機會。', `organizer`='高雄市立圖書館總館', `address`='高雄市大樹區溪埔路77號3樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市立圖書館大樹三館', `latitude`=22.71100364, `longitude`=120.425407, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
