INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fc26b32419285b7316', '114年度纖維學院春季研習', '為傳承纖維工藝技藝及培訓專業人才，臺中市纖維工藝博物館特聘籐編、藍染、織布、中國結、繡畫、棒槌蕾絲、竹編、緙絲、藺草編等專業領域的講師，開設每門課為期10周的專業課程。\r\n共開設9班，包含籐編、藍染、織布趣、創意繩結與首飾設計、繡畫、棒槌蕾絲、竹編、緙絲、藺草編。\r\n\r\n課程不僅能培養專業技能，且讓學員於課後能將該技能日後持續傳承、教學。課後將依學員實際上課時數核給。', '臺中市纖維工藝博物館', '臺中市大里區勝利二路1號', '2025-03-18 00:00:00', '2025-06-17 00:00:00', '臺中市纖維工藝博物館', 24.09575742, 120.6926261, '無資料', 'https://mofia.taichung.gov.tw/ActivityWorkshopMain', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年度纖維學院春季研習', `description`='為傳承纖維工藝技藝及培訓專業人才，臺中市纖維工藝博物館特聘籐編、藍染、織布、中國結、繡畫、棒槌蕾絲、竹編、緙絲、藺草編等專業領域的講師，開設每門課為期10周的專業課程。\r\n共開設9班，包含籐編、藍染、織布趣、創意繩結與首飾設計、繡畫、棒槌蕾絲、竹編、緙絲、藺草編。\r\n\r\n課程不僅能培養專業技能，且讓學員於課後能將該技能日後持續傳承、教學。課後將依學員實際上課時數核給。', `organizer`='臺中市纖維工藝博物館', `address`='臺中市大里區勝利二路1號', `start_date`='2025-03-18 00:00:00', `end_date`='2025-06-17 00:00:00', `location`='臺中市纖維工藝博物館', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://mofia.taichung.gov.tw/ActivityWorkshopMain', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fc26b32419285b7317', '手路Tshiú-Lōo~島編生活藤工藝展', '「手路~島編生活藤工藝展」，透過6大展區、42組件珍貴館藏、5位職人、10個街區故事和3大品牌家具，總計近80件展品，呈現臺灣藤工藝的技藝和時代軌跡，並規劃舉辦「藤景走讀小旅行」、故事徵集和手作體驗活動等，展期至6月29日止，歡迎民眾一起感受藤編工藝的獨特魅力。\r\n\r\n「過去臺灣的藤工藝，是靠著一雙又一雙的手，編織出一條生活的道路和時代的印記」，藤編器物不僅是實用的日常生活用品，更是文化的傳承，這次展覽以「手路」(台語Tshiú-Lōo)為主題，透過不同世代職人特殊的技藝、手法，從藤編材料、構築技法、分門別類的作品、纖博館典藏精品，到當代潮流下復舊翻新的品牌家具、室內裝修和藝術創作等，讓觀眾看見藤從「材料」到「作品」、從實用到美學的轉化，重新認識藤的多元面貌。', '臺中市纖維工藝博物館', '臺中市大里區勝利二路1號', '2025-03-29 00:00:00', '2025-06-29 00:00:00', '臺中市纖維工藝博物館', 24.09575742, 120.6926261, '無資料', 'https://mofia.taichung.gov.tw/Exhibit/125', '[]') ON DUPLICATE KEY UPDATE `activity_name`='手路Tshiú-Lōo~島編生活藤工藝展', `description`='「手路~島編生活藤工藝展」，透過6大展區、42組件珍貴館藏、5位職人、10個街區故事和3大品牌家具，總計近80件展品，呈現臺灣藤工藝的技藝和時代軌跡，並規劃舉辦「藤景走讀小旅行」、故事徵集和手作體驗活動等，展期至6月29日止，歡迎民眾一起感受藤編工藝的獨特魅力。\r\n\r\n「過去臺灣的藤工藝，是靠著一雙又一雙的手，編織出一條生活的道路和時代的印記」，藤編器物不僅是實用的日常生活用品，更是文化的傳承，這次展覽以「手路」(台語Tshiú-Lōo)為主題，透過不同世代職人特殊的技藝、手法，從藤編材料、構築技法、分門別類的作品、纖博館典藏精品，到當代潮流下復舊翻新的品牌家具、室內裝修和藝術創作等，讓觀眾看見藤從「材料」到「作品」、從實用到美學的轉化，重新認識藤的多元面貌。', `organizer`='臺中市纖維工藝博物館', `address`='臺中市大里區勝利二路1號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='臺中市纖維工藝博物館', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://mofia.taichung.gov.tw/Exhibit/125', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fc26b32419285b731a', '2025 Willy簡嘉彣《再見你一面》專輯演唱會', '他一步一步從小房間走進你的耳機\r\n再從你的耳機走到了你的面前\r\n穿越時空，克服低潮\r\n今天他想來再見你一面\r\n提醒你陰雨之後一定會是晴天\r\n提醒你眼淚之後一定會有笑容\r\n提醒你\r\n你也在發光', '高雄流行音樂中心', '高雄市鹽埕區17鄰真愛路1號', '2025-05-24 00:00:00', '2025-05-24 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '預售票+500;現場票+600', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 Willy簡嘉彣《再見你一面》專輯演唱會', `description`='他一步一步從小房間走進你的耳機\r\n再從你的耳機走到了你的面前\r\n穿越時空，克服低潮\r\n今天他想來再見你一面\r\n提醒你陰雨之後一定會是晴天\r\n提醒你眼淚之後一定會有笑容\r\n提醒你\r\n你也在發光', `organizer`='高雄流行音樂中心', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-05-24 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='預售票+500;現場票+600', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fc26b32419285b731d', '「人像寫真攝影拍攝技巧」書展、「2025世界閱讀日」書展--4月書展', '【人像寫真攝影拍攝技巧】書展\r\n展出期間：2025/04/01~2025/04/30\r\n展出內容：無論是初學攝影還是拍了很多年，人像相片始終是一門深入的學問，學似簡單，但其實內裏有很多技巧，拍得久了便會發現很多相片也是差不多，只是model換了而已，那麼新手入門拍人像有那些rule可以學習的呢？一起閱讀這些簡單易明的人像技巧的書籍吧！\r\n\r\n【2025世界閱讀日】書展\r\n展出期間：2025/04/01~2025/04/30\r\n展出內容：1995年聯合國教科文組織（UNESCO）正式將每年4月23日訂為「世界書香及版權日」（或稱世界閱讀日），希望藉由全世界對此節日的慶祝，關注閱讀、出版及智慧權益的發展，藉以喚起世人重拾閱讀的興趣及對著作版權的重視。中區圖書館將搭配主題推出各種相關書籍與民眾共同發現閱讀的多元樣貌和美好生活，歡迎到中區圖書館借閱。', '臺中市立圖書館中區分館', '臺中市中區成功路300號7樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館中區分館', 24.14168566, 120.680598, '無資料', 'https://reurl.cc/QY9aL2 ； https://reurl.cc/OY0mkA', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「人像寫真攝影拍攝技巧」書展、「2025世界閱讀日」書展--4月書展', `description`='【人像寫真攝影拍攝技巧】書展\r\n展出期間：2025/04/01~2025/04/30\r\n展出內容：無論是初學攝影還是拍了很多年，人像相片始終是一門深入的學問，學似簡單，但其實內裏有很多技巧，拍得久了便會發現很多相片也是差不多，只是model換了而已，那麼新手入門拍人像有那些rule可以學習的呢？一起閱讀這些簡單易明的人像技巧的書籍吧！\r\n\r\n【2025世界閱讀日】書展\r\n展出期間：2025/04/01~2025/04/30\r\n展出內容：1995年聯合國教科文組織（UNESCO）正式將每年4月23日訂為「世界書香及版權日」（或稱世界閱讀日），希望藉由全世界對此節日的慶祝，關注閱讀、出版及智慧權益的發展，藉以喚起世人重拾閱讀的興趣及對著作版權的重視。中區圖書館將搭配主題推出各種相關書籍與民眾共同發現閱讀的多元樣貌和美好生活，歡迎到中區圖書館借閱。', `organizer`='臺中市立圖書館中區分館', `address`='臺中市中區成功路300號7樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館中區分館', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='https://reurl.cc/QY9aL2 ； https://reurl.cc/OY0mkA', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fd26b32419285b7321', '身聲劇場《光影戲》工作坊', '「身聲」—身體與聲音，一個融合多元藝術領域的表演藝術團體。創辦人吳忠良相信每個人都有屬於自己獨一無二的表達能力，透過整合音樂、戲劇、舞蹈、美術等不同領域專長的夥伴，發展出表演者從演戲到擊鼓全方位的劇場美學。1998年成立身聲演繹社、後更名為「身聲劇場」，自多元的傳統技藝學習並轉化為現代劇場表演語彙，創作當代實驗與親子戲劇的作品；再延伸出「身聲擊樂團」、藝術推廣課程課程為主題的「大地樂器館」，以及以街頭、高蹺與廣場藝術為特色的「身聲跨劇場」，展現豐沛的創作能量、互動特色與跨領域創作發展。', '花蓮縣文化局', '花蓮縣光復鄉', '2025-07-07 00:00:00', '2025-07-09 00:00:00', '光復鄉（花蓮縣）=', 23.64658742, 121.4351231, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='身聲劇場《光影戲》工作坊', `description`='「身聲」—身體與聲音，一個融合多元藝術領域的表演藝術團體。創辦人吳忠良相信每個人都有屬於自己獨一無二的表達能力，透過整合音樂、戲劇、舞蹈、美術等不同領域專長的夥伴，發展出表演者從演戲到擊鼓全方位的劇場美學。1998年成立身聲演繹社、後更名為「身聲劇場」，自多元的傳統技藝學習並轉化為現代劇場表演語彙，創作當代實驗與親子戲劇的作品；再延伸出「身聲擊樂團」、藝術推廣課程課程為主題的「大地樂器館」，以及以街頭、高蹺與廣場藝術為特色的「身聲跨劇場」，展現豐沛的創作能量、互動特色與跨領域創作發展。', `organizer`='花蓮縣文化局', `address`='花蓮縣光復鄉', `start_date`='2025-07-07 00:00:00', `end_date`='2025-07-09 00:00:00', `location`='光復鄉（花蓮縣）=', `latitude`=23.64658742, `longitude`=121.4351231, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fd26b32419285b7322', '2025頭份四月八 頭份拾光展（即日起至4/7止徵件）', '【2025頭份四月八-頭份拾光展】照片募集活動\r\n為保留節慶祭典、傳統文化、城市街景之風華，歡迎民眾踴躍提供頭份四月八之各式老照片，或其他具有文史意義之老照，徵得民眾同意取得使用及藝文推廣權利後，由頭份市公所辦理「2025頭份四月八 頭份拾光展」活動，期望能串起市民的集體記憶和地方傳承，共同為頭份四月八喚起情感與記憶。\r\n徵集時間：即日起至4/7止\r\n徵集條件：以《底片相機》拍攝之照片為主\r\n徵集數量：20件\r\n照片年份：2000年前(民國89年以前)為最佳、2000-2010年(民國89年-99年)為次佳。\r\n徵集回饋：經評審入選確定使用者，可獲贈禮券500元\r\n詳細徵集辦法請洽頭份市公所', '苗栗縣頭份市公所', '苗栗縣頭份市中山路232號', '2025-04-23 00:00:00', '2025-05-06 00:00:00', '苗栗縣頭份市公所', 24.6861065, 120.9119437, '無資料', 'https://www.facebook.com/profile.php?id=100068581104944#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025頭份四月八 頭份拾光展（即日起至4/7止徵件）', `description`='【2025頭份四月八-頭份拾光展】照片募集活動\r\n為保留節慶祭典、傳統文化、城市街景之風華，歡迎民眾踴躍提供頭份四月八之各式老照片，或其他具有文史意義之老照，徵得民眾同意取得使用及藝文推廣權利後，由頭份市公所辦理「2025頭份四月八 頭份拾光展」活動，期望能串起市民的集體記憶和地方傳承，共同為頭份四月八喚起情感與記憶。\r\n徵集時間：即日起至4/7止\r\n徵集條件：以《底片相機》拍攝之照片為主\r\n徵集數量：20件\r\n照片年份：2000年前(民國89年以前)為最佳、2000-2010年(民國89年-99年)為次佳。\r\n徵集回饋：經評審入選確定使用者，可獲贈禮券500元\r\n詳細徵集辦法請洽頭份市公所', `organizer`='苗栗縣頭份市公所', `address`='苗栗縣頭份市中山路232號', `start_date`='2025-04-23 00:00:00', `end_date`='2025-05-06 00:00:00', `location`='苗栗縣頭份市公所', `latitude`=24.6861065, `longitude`=120.9119437, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100068581104944#', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fd26b32419285b7323', '動物忍者太鼓', '成立近20年的日本『TAMAKKOZA』和太鼓劇團，擁有20餘名團員，曾獲邀至世界多國公演，『TAMAKKOZA』和太鼓劇團，它是現今唯一專為小朋友量身設計的太鼓座。和太鼓座的樂器包括三味線、竹笛、箏、尺八以及大小不同的鼓…等等，揮擊太鼓的震撼、舞姿動作的肢體美、笛子的清澈響亮，乃至力與美天衣無縫的結合。僅管演出是現代的型態，但日本民族性卻在表演者間自然流露。更令人嘆為觀止的是，其團員的『多才多藝』！他們不但擅長傳統日本風味的太鼓，當中還穿插含括各種樂器、道具一同串聯出趣味十足的短劇表演，團員不但是傳統藝人、喜劇演員、流行樂手，還是精采的現代演奏者。其傳統而創新的現代表演型式，透過不斷演練，塑造出如此別樹一格的舞台藝術。', '花蓮縣文化局', '花蓮縣新城鄉', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '新城鄉（花蓮縣）=', 24.05579952, 121.6137969, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='動物忍者太鼓', `description`='成立近20年的日本『TAMAKKOZA』和太鼓劇團，擁有20餘名團員，曾獲邀至世界多國公演，『TAMAKKOZA』和太鼓劇團，它是現今唯一專為小朋友量身設計的太鼓座。和太鼓座的樂器包括三味線、竹笛、箏、尺八以及大小不同的鼓…等等，揮擊太鼓的震撼、舞姿動作的肢體美、笛子的清澈響亮，乃至力與美天衣無縫的結合。僅管演出是現代的型態，但日本民族性卻在表演者間自然流露。更令人嘆為觀止的是，其團員的『多才多藝』！他們不但擅長傳統日本風味的太鼓，當中還穿插含括各種樂器、道具一同串聯出趣味十足的短劇表演，團員不但是傳統藝人、喜劇演員、流行樂手，還是精采的現代演奏者。其傳統而創新的現代表演型式，透過不斷演練，塑造出如此別樹一格的舞台藝術。', `organizer`='花蓮縣文化局', `address`='花蓮縣新城鄉', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='新城鄉（花蓮縣）=', `latitude`=24.05579952, `longitude`=121.6137969, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fd26b32419285b7324', '動物忍者太鼓', '成立近20年的日本『TAMAKKOZA』和太鼓劇團，擁有20餘名團員，曾獲邀至世界多國公演，『TAMAKKOZA』和太鼓劇團，它是現今唯一專為小朋友量身設計的太鼓座。和太鼓座的樂器包括三味線、竹笛、箏、尺八以及大小不同的鼓…等等，揮擊太鼓的震撼、舞姿動作的肢體美、笛子的清澈響亮，乃至力與美天衣無縫的結合。僅管演出是現代的型態，但日本民族性卻在表演者間自然流露。更令人嘆為觀止的是，其團員的『多才多藝』！他們不但擅長傳統日本風味的太鼓，當中還穿插含括各種樂器、道具一同串聯出趣味十足的短劇表演，團員不但是傳統藝人、喜劇演員、流行樂手，還是精采的現代演奏者。其傳統而創新的現代表演型式，透過不斷演練，塑造出如此別樹一格的舞台藝術。', '花蓮縣文化局', '花蓮縣瑞穗鄉', '2025-05-04 00:00:00', '2025-05-04 00:00:00', '瑞穗鄉（花蓮縣）=', 23.5156124, 121.4073472, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='動物忍者太鼓', `description`='成立近20年的日本『TAMAKKOZA』和太鼓劇團，擁有20餘名團員，曾獲邀至世界多國公演，『TAMAKKOZA』和太鼓劇團，它是現今唯一專為小朋友量身設計的太鼓座。和太鼓座的樂器包括三味線、竹笛、箏、尺八以及大小不同的鼓…等等，揮擊太鼓的震撼、舞姿動作的肢體美、笛子的清澈響亮，乃至力與美天衣無縫的結合。僅管演出是現代的型態，但日本民族性卻在表演者間自然流露。更令人嘆為觀止的是，其團員的『多才多藝』！他們不但擅長傳統日本風味的太鼓，當中還穿插含括各種樂器、道具一同串聯出趣味十足的短劇表演，團員不但是傳統藝人、喜劇演員、流行樂手，還是精采的現代演奏者。其傳統而創新的現代表演型式，透過不斷演練，塑造出如此別樹一格的舞台藝術。', `organizer`='花蓮縣文化局', `address`='花蓮縣瑞穗鄉', `start_date`='2025-05-04 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='瑞穗鄉（花蓮縣）=', `latitude`=23.5156124, `longitude`=121.4073472, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fd26b32419285b7325', '身聲劇場《希望之翼》', '「很久很久以前，有一雙翅膀，叫做希望之翼。漸漸地，人們不再覺得自己需要一雙翅膀，希望之翼慢慢被塵埃覆蓋......」\r\n融合戲劇、現場音樂、大型傀儡、高蹺以及觀眾互動等多元的表演元素，呈現遺忘了許願與想像力量的現代人，如何透過希望之翼展翅，引領人們找到重新飛翔的勇氣。作品為身聲劇場第一個以廣場藝術規模打造的作品。除了結合大偶裝置，還有吸睛的高蹺造型，以五彩繽紛的羽翼穿梭舞台與觀眾席，加上創意森巴鼓的熱情鼓舞，與大量現場互動設計，演出將充滿驚喜！', '花蓮縣文化局', '花蓮縣吉安鄉', '2025-06-07 00:00:00', '2025-06-07 00:00:00', '吉安鄉（花蓮縣）=', 23.95546585, 121.5646738, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='身聲劇場《希望之翼》', `description`='「很久很久以前，有一雙翅膀，叫做希望之翼。漸漸地，人們不再覺得自己需要一雙翅膀，希望之翼慢慢被塵埃覆蓋......」\r\n融合戲劇、現場音樂、大型傀儡、高蹺以及觀眾互動等多元的表演元素，呈現遺忘了許願與想像力量的現代人，如何透過希望之翼展翅，引領人們找到重新飛翔的勇氣。作品為身聲劇場第一個以廣場藝術規模打造的作品。除了結合大偶裝置，還有吸睛的高蹺造型，以五彩繽紛的羽翼穿梭舞台與觀眾席，加上創意森巴鼓的熱情鼓舞，與大量現場互動設計，演出將充滿驚喜！', `organizer`='花蓮縣文化局', `address`='花蓮縣吉安鄉', `start_date`='2025-06-07 00:00:00', `end_date`='2025-06-07 00:00:00', `location`='吉安鄉（花蓮縣）=', `latitude`=23.95546585, `longitude`=121.5646738, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fd26b32419285b7327', '身聲劇場《環保樂器打擊趣》工作坊', '「「身聲」—身體與聲音，一個融合多元藝術領域的表演藝術團體。創辦人吳忠良相信每個人都有屬於自己獨一無二的表達能力，透過整合音樂、戲劇、舞蹈、美術等不同領域專長的夥伴，發展出表演者從演戲到擊鼓全方位的劇場美學。1998年成立身聲演繹社、後更名為「身聲劇場」，自多元的傳統技藝學習並轉化為現代劇場表演語彙，創作當代實驗與親子戲劇的作品；再延伸出「身聲擊樂團」、藝術推廣課程課程為主題的「大地樂器館」，以及以街頭、高蹺與廣場藝術為特色的「身聲跨劇場」，展現豐沛的創作能量、互動特色與跨領域創作發展。', '花蓮縣文化局', '花蓮縣玉里鎮', '2025-07-03 00:00:00', '2025-07-06 00:00:00', '玉里鎮（花蓮縣）=', 23.37143588, 121.3604476, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='身聲劇場《環保樂器打擊趣》工作坊', `description`='「「身聲」—身體與聲音，一個融合多元藝術領域的表演藝術團體。創辦人吳忠良相信每個人都有屬於自己獨一無二的表達能力，透過整合音樂、戲劇、舞蹈、美術等不同領域專長的夥伴，發展出表演者從演戲到擊鼓全方位的劇場美學。1998年成立身聲演繹社、後更名為「身聲劇場」，自多元的傳統技藝學習並轉化為現代劇場表演語彙，創作當代實驗與親子戲劇的作品；再延伸出「身聲擊樂團」、藝術推廣課程課程為主題的「大地樂器館」，以及以街頭、高蹺與廣場藝術為特色的「身聲跨劇場」，展現豐沛的創作能量、互動特色與跨領域創作發展。', `organizer`='花蓮縣文化局', `address`='花蓮縣玉里鎮', `start_date`='2025-07-03 00:00:00', `end_date`='2025-07-06 00:00:00', `location`='玉里鎮（花蓮縣）=', `latitude`=23.37143588, `longitude`=121.3604476, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fd26b32419285b7328', '小青蛙劇團《熊的傳說》', '《熊的傳說》故事大綱：勇士阿卡、阿布相約上山去打獵，好不容易獵到了一頭山豬，返回部落途中卻冒出了程咬金-眼鏡蛇，為了逃命只好將到手的肥豬肉拱手讓人；在因緣際會下認識了山豬的好友–黑皮熊，兩個獵人與憨厚的黑熊、內心膽小脆弱的眼鏡蛇、愛吃的山豬共譜出了一段搞笑、溫馨的故事。全劇以輕鬆和諧的方式帶領小朋友進入森林保育的領域裏，主要在宣導人類與自然環境應和平共處的理念，以環境教育的觀念，從小培育孩子們養成愛護大自然，以及尊重生命的教育目標。', '花蓮縣文化局', '花蓮縣玉里鎮', '2025-09-28 00:00:00', '2025-09-28 00:00:00', '玉里鎮（花蓮縣）=', 23.37143588, 121.3604476, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='小青蛙劇團《熊的傳說》', `description`='《熊的傳說》故事大綱：勇士阿卡、阿布相約上山去打獵，好不容易獵到了一頭山豬，返回部落途中卻冒出了程咬金-眼鏡蛇，為了逃命只好將到手的肥豬肉拱手讓人；在因緣際會下認識了山豬的好友–黑皮熊，兩個獵人與憨厚的黑熊、內心膽小脆弱的眼鏡蛇、愛吃的山豬共譜出了一段搞笑、溫馨的故事。全劇以輕鬆和諧的方式帶領小朋友進入森林保育的領域裏，主要在宣導人類與自然環境應和平共處的理念，以環境教育的觀念，從小培育孩子們養成愛護大自然，以及尊重生命的教育目標。', `organizer`='花蓮縣文化局', `address`='花蓮縣玉里鎮', `start_date`='2025-09-28 00:00:00', `end_date`='2025-09-28 00:00:00', `location`='玉里鎮（花蓮縣）=', `latitude`=23.37143588, `longitude`=121.3604476, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fd26b32419285b732a', '好客劇場（114年5月）', '放映影片介紹：\r\n神影之龍\r\n片長：約22分鐘\r\n內容簡介：\r\n一年一度的祥龍點睛典禮即將在伯公廟前舉行，但阿公辛苦多日作的糊龍，卻意外被阿福與喜妹嬉鬧玩耍下弄壞了。\r\n　　喜妹因為被阿公責備，生氣之下跑到庄外的伯公廟躲了起來。巧遇到頑皮的哈古，假扮成龍貓伯公要騙喜妹口袋裡的柿餅吃，不料卻把喜妹嚇昏了…\r\n一場人與土地守護神及伯公神祇相遇的奇妙故事就此展開!\r\n\r\n我的爸爸是森林之王\r\n片長：12分鐘\r\n內容簡介：\r\n孤獨的少年亞當，踏上前往森林、尋找他失散多年的父親的旅途。\r\n在森林深處，亞當面臨著一個難以置信的身分轉變：他的父親就是大腳怪。\r\n加入大腳怪父子以及他們所有古怪的森林動物朋友們，抵抗來自獵人的威脅，一起來體驗一生的冒險吧！\r\n\r\n諾亞方舟大冒險\r\n片長：約18分鐘\r\n內容簡介：\r\n由獅王帶領的眾動物們已經待在諾亞方舟上數個月，他們在海上漂流尋找著陸地。\r\n另一方面，總是喜歡在船上調皮搗蛋菲尼與好朋友莉亞，因為突如其來的意外讓兩人失足落水，無法回到方舟上的他們漂流到一座神祕的島嶼，發現一群特別的動物已經在這裡定居已久，而且不是很歡迎他們的到來...\r\n面對各種困境，菲尼、莉亞以及船上得動物們該如何是好？\r\n\r\n歡迎來好客劇場感受全新3D影片的精彩炫目，以及杜比全景聲音效，給您彷彿身歷其境的聽覺效果！', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-05-01 00:00:00', '2025-05-31 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '全票(好客劇場)+50;團體票(好客劇場)+40;優待票(好客劇場)+30', 'https://www.facebook.com/hakkapark/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='好客劇場（114年5月）', `description`='放映影片介紹：\r\n神影之龍\r\n片長：約22分鐘\r\n內容簡介：\r\n一年一度的祥龍點睛典禮即將在伯公廟前舉行，但阿公辛苦多日作的糊龍，卻意外被阿福與喜妹嬉鬧玩耍下弄壞了。\r\n　　喜妹因為被阿公責備，生氣之下跑到庄外的伯公廟躲了起來。巧遇到頑皮的哈古，假扮成龍貓伯公要騙喜妹口袋裡的柿餅吃，不料卻把喜妹嚇昏了…\r\n一場人與土地守護神及伯公神祇相遇的奇妙故事就此展開!\r\n\r\n我的爸爸是森林之王\r\n片長：12分鐘\r\n內容簡介：\r\n孤獨的少年亞當，踏上前往森林、尋找他失散多年的父親的旅途。\r\n在森林深處，亞當面臨著一個難以置信的身分轉變：他的父親就是大腳怪。\r\n加入大腳怪父子以及他們所有古怪的森林動物朋友們，抵抗來自獵人的威脅，一起來體驗一生的冒險吧！\r\n\r\n諾亞方舟大冒險\r\n片長：約18分鐘\r\n內容簡介：\r\n由獅王帶領的眾動物們已經待在諾亞方舟上數個月，他們在海上漂流尋找著陸地。\r\n另一方面，總是喜歡在船上調皮搗蛋菲尼與好朋友莉亞，因為突如其來的意外讓兩人失足落水，無法回到方舟上的他們漂流到一座神祕的島嶼，發現一群特別的動物已經在這裡定居已久，而且不是很歡迎他們的到來...\r\n面對各種困境，菲尼、莉亞以及船上得動物們該如何是好？\r\n\r\n歡迎來好客劇場感受全新3D影片的精彩炫目，以及杜比全景聲音效，給您彷彿身歷其境的聽覺效果！', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='全票(好客劇場)+50;團體票(好客劇場)+40;優待票(好客劇場)+30', `source_url`='https://www.facebook.com/hakkapark/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fd26b32419285b732b', '（兒童館）繪本說故事（114年5月）', '在大大的樹下，來聽老師活潑生動的講述繪本故事。', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-05-01 00:00:00', '2025-05-31 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '無資料', 'https://www.facebook.com/hakkapark', '[]') ON DUPLICATE KEY UPDATE `activity_name`='（兒童館）繪本說故事（114年5月）', `description`='在大大的樹下，來聽老師活潑生動的講述繪本故事。', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='無資料', `source_url`='https://www.facebook.com/hakkapark', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fe26b32419285b732c', '《鷂婆山下：水光粼粼講客家》「村史回村」推廣工作坊- 富興村', '【富興村聚落記憶  講閒談客庄舊事】\r\n大湖草莓的發源地──富興村，擁有大河交匯、大山環繞、心形臺地的夢幻美景，自古以來就是「內山」入口，先民為了爭奪水源，漢人與原住民幾番爭戰，還有豐富的人文地景淵源流長的故事，多元的傳統產業造就的傳說美談……歡迎在地居民、對客家文化有興趣的大小朋友，一起來聆聽、珍藏這段客庄記憶。\r\n\r\n主講人：《鷂婆山下  水光粼粼講客家》作者：林錫霞老師\r\n與談人：東海大學歷史系副教授王政文、國立中正大學歷史學系副教授林韻柔\r\n預先報名成功者，優先領取「客家米食餐盒」壹份，限量50份。\r\n現場還有特別販售林錫霞老師的村史作品《鷂婆山下：水光粼粼講客家》\r\n原價 $250 元/本，活動限定 8 折優惠 $200 元/本！\r\n有興趣的朋友們，歡迎把這本珍貴的村史帶回家，一起珍藏客庄故事！\r\n線上報名 https://reurl.cc/eMEKxb', '客家委員會客家文化發展中心', '苗栗縣大湖鄉', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '大湖鄉（苗栗縣）=', 24.39359641, 120.8631192, '無資料', 'https://www.facebook.com/hakkapark', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《鷂婆山下：水光粼粼講客家》「村史回村」推廣工作坊- 富興村', `description`='【富興村聚落記憶  講閒談客庄舊事】\r\n大湖草莓的發源地──富興村，擁有大河交匯、大山環繞、心形臺地的夢幻美景，自古以來就是「內山」入口，先民為了爭奪水源，漢人與原住民幾番爭戰，還有豐富的人文地景淵源流長的故事，多元的傳統產業造就的傳說美談……歡迎在地居民、對客家文化有興趣的大小朋友，一起來聆聽、珍藏這段客庄記憶。\r\n\r\n主講人：《鷂婆山下  水光粼粼講客家》作者：林錫霞老師\r\n與談人：東海大學歷史系副教授王政文、國立中正大學歷史學系副教授林韻柔\r\n預先報名成功者，優先領取「客家米食餐盒」壹份，限量50份。\r\n現場還有特別販售林錫霞老師的村史作品《鷂婆山下：水光粼粼講客家》\r\n原價 $250 元/本，活動限定 8 折優惠 $200 元/本！\r\n有興趣的朋友們，歡迎把這本珍貴的村史帶回家，一起珍藏客庄故事！\r\n線上報名 https://reurl.cc/eMEKxb', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣大湖鄉', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='大湖鄉（苗栗縣）=', `latitude`=24.39359641, `longitude`=120.8631192, `ticket_price`='無資料', `source_url`='https://www.facebook.com/hakkapark', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fe26b32419285b732e', '「拼・靚：臺灣客家多重面貌展」體驗活動 :「桐花漆器蒔繪｣', '桐花季語活動邀您來尞\r\n想體驗將美麗桐花以蒔繪方式呈現嗎？或了解樟腦與漆產業在客庄个輝煌歲月嗎？「拼．靚：臺灣客家多重面貌展」桐花主題活動-手作體驗「桐花漆器蒔繪」\r\n講師：豐原漆藝館\r\n將桐花之美以點描與貼葉等技法在漆盤上重現，以色粉等材料裝飾，製作專屬个桐花漆盤。\r\n報名網址：https://reurl.cc/NY62Vq', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '費用+200', 'https://www.facebook.com/hakkapark', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「拼・靚：臺灣客家多重面貌展」體驗活動 :「桐花漆器蒔繪｣', `description`='桐花季語活動邀您來尞\r\n想體驗將美麗桐花以蒔繪方式呈現嗎？或了解樟腦與漆產業在客庄个輝煌歲月嗎？「拼．靚：臺灣客家多重面貌展」桐花主題活動-手作體驗「桐花漆器蒔繪」\r\n講師：豐原漆藝館\r\n將桐花之美以點描與貼葉等技法在漆盤上重現，以色粉等材料裝飾，製作專屬个桐花漆盤。\r\n報名網址：https://reurl.cc/NY62Vq', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='費用+200', `source_url`='https://www.facebook.com/hakkapark', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fe26b32419285b732f', '「拼・靚：臺灣客家多重面貌展」專題講座： 「客庄產業風華-樟腦與漆藝｣', '講師：南投縣文化資產學會 梁志忠理事長\r\n樟腦與採漆曾是客庄不容小覷个經濟產業，臺灣三寶之一「樟腦」如何在世界佔有一席之地？生漆又如何發展出無可替代个「臺灣蓬萊塗漆器」？\r\n報名網址：https://reurl.cc/NY62Vq', '客家委員會客家文化發展中心', '苗栗縣銅鑼鄉銅科南路6號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '臺灣客家文化館（客家委員會客家文化發展中心）', 24.4663812, 120.7645055, '無資料', 'https://www.facebook.com/hakkapark', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「拼・靚：臺灣客家多重面貌展」專題講座： 「客庄產業風華-樟腦與漆藝｣', `description`='講師：南投縣文化資產學會 梁志忠理事長\r\n樟腦與採漆曾是客庄不容小覷个經濟產業，臺灣三寶之一「樟腦」如何在世界佔有一席之地？生漆又如何發展出無可替代个「臺灣蓬萊塗漆器」？\r\n報名網址：https://reurl.cc/NY62Vq', `organizer`='客家委員會客家文化發展中心', `address`='苗栗縣銅鑼鄉銅科南路6號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='臺灣客家文化館（客家委員會客家文化發展中心）', `latitude`=24.4663812, `longitude`=120.7645055, `ticket_price`='無資料', `source_url`='https://www.facebook.com/hakkapark', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fe26b32419285b7331', '《不趕時間》高雄市政府油畫社創作展', '本次畫展揭露光影與時間在空間裡的悄然行動，逮住時光小辮子，用油彩發現這個秘密活動，有如壓縮過的時光抽屜，撿拾散落在故事時空裡的片刻光影，藏著作者的某些觀點或念頭；讓觀眾打開抽屜，一個一個，穿梭在不同時光，體驗不同的意象，欣賞時間的流動、光的物換「心」移。', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-06-20 00:00:00', '2025-07-01 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', 'https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4118', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《不趕時間》高雄市政府油畫社創作展', `description`='本次畫展揭露光影與時間在空間裡的悄然行動，逮住時光小辮子，用油彩發現這個秘密活動，有如壓縮過的時光抽屜，撿拾散落在故事時空裡的片刻光影，藏著作者的某些觀點或念頭；讓觀眾打開抽屜，一個一個，穿梭在不同時光，體驗不同的意象，欣賞時間的流動、光的物換「心」移。', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-06-20 00:00:00', `end_date`='2025-07-01 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='https://khcc.kcg.gov.tw/rwd_home03.aspx?ID=$M102&IDK=2&EXEC=D&DATA=4118', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fe26b32419285b733d', '2025第二屆全國社區交流音樂會～國樂飄揚 漫遊山城', '國樂逍遙遊於花蓮陶然雅樂集創辦，〝2023首屆全國社區交流音樂會〞，由各縣市喜愛國樂的朋友，利用退休閒暇時間，以悠閒快樂的精神學習國樂，以陶冶性情及於退休後，〉走出戶外結交更多志同道合的朋友，平時請專業老師指導各種樂器如:胡琴彈撥打擊、吹管等各種相關樂器，每位學員都覺得樂趣無窮，可提早防治失智及不用讓家裡人擔心老人孤獨的問題。\r\n今年2025年本縣舉辦〝國樂飄揚 漫遊山城〞第二屆全國社區交流音樂會，邀請花蓮陶然雅樂集、宜蘭新生/黎明國樂團、屏東長興民族音樂研究學會，共五個國樂團共襄盛舉，也讓全台各地民眾，認識美麗的山城~苗栗，也讓各縣市國樂團認識我們苗北演藝廳，是非常專業的演藝廳。\r\n\r\n演出曲目：\r\n苗栗縣中港溪國樂：1.春節序曲。2.童年的回憶。3.奔馳在千里草原。4.客家組曲。\r\n花蓮陶然雅樂集：1.茶山情歌。2.半島風情。3.節日鑼鼓。\r\n宜蘭新生/黎明國樂團：1.茉莉花。2.評劇小韻。3.韻。\r\n屏東長興民族音樂研究學會：1.阿美迎賓曲/阿美族歌謠。2.江波舞影。3.瑤族舞曲。\r\n大合奏：1.鄉音歡舞。2.望春風。3.金蛇狂舞。\r\n演出單位：音樂總監暨指揮－黎俊平、苗栗縣中港溪國樂推廣協會、花蓮陶然雅樂集、宜蘭新生/黎明國樂團、屏東長興民族音樂研究學會。', '無資料', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-05-17 00:00:00', '2025-05-17 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025第二屆全國社區交流音樂會～國樂飄揚 漫遊山城', `description`='國樂逍遙遊於花蓮陶然雅樂集創辦，〝2023首屆全國社區交流音樂會〞，由各縣市喜愛國樂的朋友，利用退休閒暇時間，以悠閒快樂的精神學習國樂，以陶冶性情及於退休後，〉走出戶外結交更多志同道合的朋友，平時請專業老師指導各種樂器如:胡琴彈撥打擊、吹管等各種相關樂器，每位學員都覺得樂趣無窮，可提早防治失智及不用讓家裡人擔心老人孤獨的問題。\r\n今年2025年本縣舉辦〝國樂飄揚 漫遊山城〞第二屆全國社區交流音樂會，邀請花蓮陶然雅樂集、宜蘭新生/黎明國樂團、屏東長興民族音樂研究學會，共五個國樂團共襄盛舉，也讓全台各地民眾，認識美麗的山城~苗栗，也讓各縣市國樂團認識我們苗北演藝廳，是非常專業的演藝廳。\r\n\r\n演出曲目：\r\n苗栗縣中港溪國樂：1.春節序曲。2.童年的回憶。3.奔馳在千里草原。4.客家組曲。\r\n花蓮陶然雅樂集：1.茶山情歌。2.半島風情。3.節日鑼鼓。\r\n宜蘭新生/黎明國樂團：1.茉莉花。2.評劇小韻。3.韻。\r\n屏東長興民族音樂研究學會：1.阿美迎賓曲/阿美族歌謠。2.江波舞影。3.瑤族舞曲。\r\n大合奏：1.鄉音歡舞。2.望春風。3.金蛇狂舞。\r\n演出單位：音樂總監暨指揮－黎俊平、苗栗縣中港溪國樂推廣協會、花蓮陶然雅樂集、宜蘭新生/黎明國樂團、屏東長興民族音樂研究學會。', `organizer`='無資料', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fe26b32419285b733e', '久拾韶華（東興擊樂團）', '無資料', '新竹縣東興國小家長委員會', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-06-01 00:00:00', '2025-06-01 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='久拾韶華（東興擊樂團）', `description`='無資料', `organizer`='新竹縣東興國小家長委員會', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-06-01 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fe26b32419285b733f', '竹南國小國樂團畢業季成果發表會', '無資料', '苗栗縣竹南鎮竹南國民小學', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-06-04 00:00:00', '2025-06-04 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='竹南國小國樂團畢業季成果發表會', `description`='無資料', `organizer`='苗栗縣竹南鎮竹南國民小學', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-06-04 00:00:00', `end_date`='2025-06-04 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474fe26b32419285b7340', '2025后庄管樂成果發表會', '曲目：Der Vogelhändler Selections from an Operetta in 3 Acts…等，約15首。\r\n演出內容：\r\n1.管樂合奏：由管樂八大分部合作進行大合奏，演出 Der Vogelhändler Selections from an Operetta in 3 Acts…等曲目。\r\n2.管樂重奏：分別由長笛、豎笛、薩克斯風、法國號、小號、長號、(上)低音號、打擊進行重奏。\r\n\r\n后庄管樂團成立於民國81年，在校長、老師及家長們的大力推動與持下，不斷自我提申、創造佳績。近年來多次蟬聯苗栗縣音樂比賽的冠軍，屢次在全國音樂比賽決賽中榮獲優異成績，今年更是在初賽及全國賽均獲特優。樂團亦於105、106、107、108、112年在苗北演藝廳進行成果發表音樂會，獲得好評。管樂團不但是后庄國小重要特色，更是苗栗縣管樂發展的重要指標。\r\n指揮：后庄國小管樂團 A團指揮/馮麗朱，B團指揮/孫永守。\r\n演出學生：\r\nA團\r\n1.長笛：沈詩侑、吳語恩、羅苡庭、邱姿瑜、吳語瑄、劉格瑜、陳莞晴、劉芷瑄、劉凱芸、黃若雅\r\n2.豎笛：陳禹潼、蕭靖妍、陳均睿、穆建熙、袁毓喬、吳友勛、邱綵姸、莊詠恩、陳亮穎、徐浚華、王柏勛、葉宇恩、吳沁禹、鍾赫軒\r\n3.薩克斯風：王品程、杜聿修、周宥慧、羅可芮、張晏緋、石家昕、林巧軒、張博恩、何秉豐\r\n4.法國號：羅萱甯、鄭羽媃、林巧穎、林友智\r\n5.小號：蔡沛錡、陳姸卉、吳俞萱、楊雁如、楊雁安、宋哲宇\r\n6.長號：徐琬祺、林祿森、吳庭宇、林欣怡、陳毅、葉倫慈、黃立昕\r\n7.上低音號：邱仲安、饒聿程、萬棨翔、陳宥蓁、鍾承諺、邱颿予、張哲瑞\r\n8.打擊：李秉翰、鄭椲辰、吳芯語、吳翌煊、陳妍昕、黎耘銨、王宏睿、蔡宜庭、鍾宇棠\r\n\r\nB團\r\n1.長笛：吳芯柔、徐安林、吳亭蓁、唐睿琳、陳芷芃\r\n2.豎笛：謝彥祖、張曦之、黃書晴\r\n3.薩克斯風：許宸睿、阮品傑、張喬淵、陳禹承\r\n4.法國號：林蔚晨、陳杰叡、邱唯廷\r\n5.小號：林昀渘、陳雨彤、陳廷睿、游佩穎、廖家諒\r\n6.上低音號：鍾卓容、李侑宸、吳沁融\r\n7.打擊：林晨曦、陳映瑀、蔡子晴\r\n\r\n指導老師：馮麗朱、孫永守、王志群、戴立人、陳心啟、吳杏芳、施芊秀、徐千惠、劉美華、田曜瑋、張鳳書、林偉邦、余盈萱。\r\n\r\n演出單位：后庄國小管樂團 指揮/馮麗朱\r\n入場方式：索票，5/7(三)起，請洽苗北服務台或后庄國小蔡主任037-663858#2618，每人限索4張。', '苗栗縣頭份市后庄國民小學', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-06-06 00:00:00', '2025-06-06 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025后庄管樂成果發表會', `description`='曲目：Der Vogelhändler Selections from an Operetta in 3 Acts…等，約15首。\r\n演出內容：\r\n1.管樂合奏：由管樂八大分部合作進行大合奏，演出 Der Vogelhändler Selections from an Operetta in 3 Acts…等曲目。\r\n2.管樂重奏：分別由長笛、豎笛、薩克斯風、法國號、小號、長號、(上)低音號、打擊進行重奏。\r\n\r\n后庄管樂團成立於民國81年，在校長、老師及家長們的大力推動與持下，不斷自我提申、創造佳績。近年來多次蟬聯苗栗縣音樂比賽的冠軍，屢次在全國音樂比賽決賽中榮獲優異成績，今年更是在初賽及全國賽均獲特優。樂團亦於105、106、107、108、112年在苗北演藝廳進行成果發表音樂會，獲得好評。管樂團不但是后庄國小重要特色，更是苗栗縣管樂發展的重要指標。\r\n指揮：后庄國小管樂團 A團指揮/馮麗朱，B團指揮/孫永守。\r\n演出學生：\r\nA團\r\n1.長笛：沈詩侑、吳語恩、羅苡庭、邱姿瑜、吳語瑄、劉格瑜、陳莞晴、劉芷瑄、劉凱芸、黃若雅\r\n2.豎笛：陳禹潼、蕭靖妍、陳均睿、穆建熙、袁毓喬、吳友勛、邱綵姸、莊詠恩、陳亮穎、徐浚華、王柏勛、葉宇恩、吳沁禹、鍾赫軒\r\n3.薩克斯風：王品程、杜聿修、周宥慧、羅可芮、張晏緋、石家昕、林巧軒、張博恩、何秉豐\r\n4.法國號：羅萱甯、鄭羽媃、林巧穎、林友智\r\n5.小號：蔡沛錡、陳姸卉、吳俞萱、楊雁如、楊雁安、宋哲宇\r\n6.長號：徐琬祺、林祿森、吳庭宇、林欣怡、陳毅、葉倫慈、黃立昕\r\n7.上低音號：邱仲安、饒聿程、萬棨翔、陳宥蓁、鍾承諺、邱颿予、張哲瑞\r\n8.打擊：李秉翰、鄭椲辰、吳芯語、吳翌煊、陳妍昕、黎耘銨、王宏睿、蔡宜庭、鍾宇棠\r\n\r\nB團\r\n1.長笛：吳芯柔、徐安林、吳亭蓁、唐睿琳、陳芷芃\r\n2.豎笛：謝彥祖、張曦之、黃書晴\r\n3.薩克斯風：許宸睿、阮品傑、張喬淵、陳禹承\r\n4.法國號：林蔚晨、陳杰叡、邱唯廷\r\n5.小號：林昀渘、陳雨彤、陳廷睿、游佩穎、廖家諒\r\n6.上低音號：鍾卓容、李侑宸、吳沁融\r\n7.打擊：林晨曦、陳映瑀、蔡子晴\r\n\r\n指導老師：馮麗朱、孫永守、王志群、戴立人、陳心啟、吳杏芳、施芊秀、徐千惠、劉美華、田曜瑋、張鳳書、林偉邦、余盈萱。\r\n\r\n演出單位：后庄國小管樂團 指揮/馮麗朱\r\n入場方式：索票，5/7(三)起，請洽苗北服務台或后庄國小蔡主任037-663858#2618，每人限索4張。', `organizer`='苗栗縣頭份市后庄國民小學', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-06-06 00:00:00', `end_date`='2025-06-06 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
