INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474ff26b32419285b7343', '竹南國中音樂班111級畢業音樂會暨社團成果發表會', '無資料', '苗栗縣立竹南國民中學', '苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', '2025-06-10 00:00:00', '2025-06-10 00:00:00', '苗栗縣苗北藝文中心', 24.6905875, 120.8886966, '無資料', 'https://www.miaobeiac.org/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='竹南國中音樂班111級畢業音樂會暨社團成果發表會', `description`='無資料', `organizer`='苗栗縣立竹南國民中學', `address`='苗栗縣竹南鎮公園路206號（公園路及永貞路口處）', `start_date`='2025-06-10 00:00:00', `end_date`='2025-06-10 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`=24.6905875, `longitude`=120.8886966, `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474ff26b32419285b7344', '精雕細鑿 三義獻藝-苗栗縣三義木雕協會會員聯展', '「精雕細鑿 三義獻藝-苗栗縣三義木雕協會會員聯展」，涵蓋了老、中、青世代，件件作品經過木雕師精心思索的將木頭賦予造型與情感生命，每年會員們作品的聯合展出，都是一次促進藝術家之間交流合作的機會，也展現藝術家豐沛的才華內涵和製作技藝，照見出三義在地木雕工作者的創作剖面，展現傳承、發揚並厚植三義地區的木雕藝術文化。\r\n一場充滿生命力與創意的藝術盛會！匯聚了台灣頂尖木雕藝術家，展現了傳統與創新的完美結合。每件作品都承載著創作者的情感，從細膩的山林景緻到現代藝術雕塑，讓人驚嘆木雕的無限可能，讓觀眾的心靈，親近藝術、深入了解木雕藝術的機會，為藝術愛好者獻上一場視覺與心靈的藝術空間饗宴。本次展出作品70件，誠摯邀請喜愛木雕藝術的愛好者蒞臨共同體驗木雕藝術之美。', '苗栗縣政府', '苗栗縣三義鄉廣聲新城88號', '2025-03-25 00:00:00', '2025-05-25 00:00:00', '三義木雕博物館', 24.4059218, 120.7611814, '本局策略聯盟+40;學生團體票（ 25 人以上）+40;學生票+50;優待票（苗栗縣縣民）+50;一般團體票（25 人以上）+70;全票+80', 'https://wood.mlc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='精雕細鑿 三義獻藝-苗栗縣三義木雕協會會員聯展', `description`='「精雕細鑿 三義獻藝-苗栗縣三義木雕協會會員聯展」，涵蓋了老、中、青世代，件件作品經過木雕師精心思索的將木頭賦予造型與情感生命，每年會員們作品的聯合展出，都是一次促進藝術家之間交流合作的機會，也展現藝術家豐沛的才華內涵和製作技藝，照見出三義在地木雕工作者的創作剖面，展現傳承、發揚並厚植三義地區的木雕藝術文化。\r\n一場充滿生命力與創意的藝術盛會！匯聚了台灣頂尖木雕藝術家，展現了傳統與創新的完美結合。每件作品都承載著創作者的情感，從細膩的山林景緻到現代藝術雕塑，讓人驚嘆木雕的無限可能，讓觀眾的心靈，親近藝術、深入了解木雕藝術的機會，為藝術愛好者獻上一場視覺與心靈的藝術空間饗宴。本次展出作品70件，誠摯邀請喜愛木雕藝術的愛好者蒞臨共同體驗木雕藝術之美。', `organizer`='苗栗縣政府', `address`='苗栗縣三義鄉廣聲新城88號', `start_date`='2025-03-25 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='三義木雕博物館', `latitude`=24.4059218, `longitude`=120.7611814, `ticket_price`='本局策略聯盟+40;學生團體票（ 25 人以上）+40;學生票+50;優待票（苗栗縣縣民）+50;一般團體票（25 人以上）+70;全票+80', `source_url`='https://wood.mlc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474ff26b32419285b7345', '永續- 台灣木雕協會會員聯展', '「永續-台灣木雕協會會員聯展」，展出者由來自各地的創作者組成，每位藝術家都有著成長背景、學習歷程、生命經驗和情緒感受，時至今日，藝術家與藝文團體勢必得回應這股永續思潮，協會本次展現主軸響應此一議題，創作者從創作材質、技術、文宣製作、包裝和材料、運送過程和展場空間的設備等，試著採用更低碳或可循環利用的解決方案，配合相關題材的創作，讓創作者主動倡議永續素養的積極角色，利用觀察自然環境與生態和諧共存議題、氣候災難的應變、種族和性平議題等題材，展現出藝術家創作上更強烈的關懷情緒和創作力。\r\n藉由創作思維實踐永續、邁向淨零的龐大資源，一方面開拓不同創作思維，另一方面讓永續的思想概念從存於腦中轉化為日常生活的具體行動，讓生活更美好，創造出更美麗的未來。', '苗栗縣政府', '苗栗縣三義鄉廣聲新城88號', '2025-04-01 00:00:00', '2025-06-01 00:00:00', '三義木雕博物館', 24.4059218, 120.7611814, '本局策略聯盟+40;學生團體票（ 25 人以上）+40;學生票+50;優待票（苗栗縣縣民）+50;一般團體票（25 人以上）+70;全票+80', 'https://wood.mlc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='永續- 台灣木雕協會會員聯展', `description`='「永續-台灣木雕協會會員聯展」，展出者由來自各地的創作者組成，每位藝術家都有著成長背景、學習歷程、生命經驗和情緒感受，時至今日，藝術家與藝文團體勢必得回應這股永續思潮，協會本次展現主軸響應此一議題，創作者從創作材質、技術、文宣製作、包裝和材料、運送過程和展場空間的設備等，試著採用更低碳或可循環利用的解決方案，配合相關題材的創作，讓創作者主動倡議永續素養的積極角色，利用觀察自然環境與生態和諧共存議題、氣候災難的應變、種族和性平議題等題材，展現出藝術家創作上更強烈的關懷情緒和創作力。\r\n藉由創作思維實踐永續、邁向淨零的龐大資源，一方面開拓不同創作思維，另一方面讓永續的思想概念從存於腦中轉化為日常生活的具體行動，讓生活更美好，創造出更美麗的未來。', `organizer`='苗栗縣政府', `address`='苗栗縣三義鄉廣聲新城88號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='三義木雕博物館', `latitude`=24.4059218, `longitude`=120.7611814, `ticket_price`='本局策略聯盟+40;學生團體票（ 25 人以上）+40;學生票+50;優待票（苗栗縣縣民）+50;一般團體票（25 人以上）+70;全票+80', `source_url`='https://wood.mlc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474ff26b32419285b7346', '2025三義木雕藝術節系列活動：三義木雕博物館30週年館慶特展', '三義木雕博物館為全臺唯一以木雕為專題之博物館， 是一座以蒐藏、展示及推廣全台灣及世界各地、兼及傳統與當代形式之木雕文物與藝術品的博物館，開創木雕藝術創作的展覽新視野，更肩負起台灣木雕產業與技藝接班傳承的使命。\r\n自1995年4月9日開館迄今，適逢30週年，因此特為規劃30週年館慶特展，以策展方式盤整並展出木雕館30年來如何發揮博物館功能，以實踐「木雕產業的薪傳與開創」的使命，帶領觀眾回顧、認識、分享木雕館這30年來為台灣社會所蒐藏、保存及推廣木雕技藝與藝術作品，以及許多投注在木雕技藝薪傳的師生們的生命故事。', '苗栗縣政府', '苗栗縣三義鄉廣聲新城88號', '2025-04-08 00:00:00', '2025-07-20 00:00:00', '三義木雕博物館', 24.4059218, 120.7611814, '本局策略聯盟+40;學生團體票（ 25 人以上）+40;學生票+50;優待票（苗栗縣縣民）+50;一般團體票（25 人以上）+70;全票+80', 'https://wood.mlc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025三義木雕藝術節系列活動：三義木雕博物館30週年館慶特展', `description`='三義木雕博物館為全臺唯一以木雕為專題之博物館， 是一座以蒐藏、展示及推廣全台灣及世界各地、兼及傳統與當代形式之木雕文物與藝術品的博物館，開創木雕藝術創作的展覽新視野，更肩負起台灣木雕產業與技藝接班傳承的使命。\r\n自1995年4月9日開館迄今，適逢30週年，因此特為規劃30週年館慶特展，以策展方式盤整並展出木雕館30年來如何發揮博物館功能，以實踐「木雕產業的薪傳與開創」的使命，帶領觀眾回顧、認識、分享木雕館這30年來為台灣社會所蒐藏、保存及推廣木雕技藝與藝術作品，以及許多投注在木雕技藝薪傳的師生們的生命故事。', `organizer`='苗栗縣政府', `address`='苗栗縣三義鄉廣聲新城88號', `start_date`='2025-04-08 00:00:00', `end_date`='2025-07-20 00:00:00', `location`='三義木雕博物館', `latitude`=24.4059218, `longitude`=120.7611814, `ticket_price`='本局策略聯盟+40;學生團體票（ 25 人以上）+40;學生票+50;優待票（苗栗縣縣民）+50;一般團體票（25 人以上）+70;全票+80', `source_url`='https://wood.mlc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474ff26b32419285b7347', '李燦瑩「陶路〜師生情誼」陶藝個展', '退休警官李燦瑩陶藝師「陶路〜師生情誼」陶藝個展，預計展出60件陶藝作品。本次展覽以小口瓶與雕塑技法為主，以日本陶土與苗栗瓷土創作，透過陶藝詮釋對人生的感悟與對土地的情感，展現獨特的人文溫度。\r\n李燦瑩老師自警官退休後投入陶藝創作，以精湛的拉坯與浮雕技法塑造出極具詩意的小口瓶，每件作品皆蘊含包容、惜福與聚財納氣的美好寓意。這些作品能幫助都市人在繁忙生活中沉澱心靈，尋得內心的平靜。創作過程中，透過與泥土的互動達到紓壓與放鬆，並藉由陶藝體現對生活的感悟。\r\n此次展覽的作品以小口瓶為主要特色，這類作品在拉坯時需要高度專注，全神貫注地塑形，一氣呵成，展現出藝術家對陶土的掌控與專業技藝。作品成形後，李老師再以浮雕技法在表面層層附著泥漿，使作品更具立體層次與動感。最後，作品經過高溫柴燒，火焰在表面留下獨特的火痕與落灰，隨受火面變化呈現自然的金屬光澤，賦予作品粗獷淳厚的質感，既保有古樸韻味，又展現現代美學特色。\r\n除了小口瓶之外，本次展覽亦呈現多件雕塑作品，展現李燦瑩老師對陶藝的多元探索。透過不同材質與燒製技法的結合，作品不僅蘊含藝術價值，更與生活美學相融合，讓陶藝成為一種能夠陪伴日常、觸動心靈的藝術形式。\r\n誠摯邀請各界陶藝愛好者及民眾蒞臨展覽，共同欣賞李燦瑩老師的陶藝之美，感受陶土在火焰淬鍊後的動人魅力。本展覽不僅呈現陶藝創作的技藝與美學，更傳遞藝術與生活的和諧關係，歡迎大家前來感受陶藝帶來的溫暖與靜謐。', '苗栗縣政府文化觀光局', '苗栗縣公館鄉14鄰館南352號', '2025-03-18 00:00:00', '2025-04-27 00:00:00', '苗栗陶瓷農創園區', 25.0422099, 121.51947, '無資料', 'https://www.mlc.gov.tw/home.aspx', '[]') ON DUPLICATE KEY UPDATE `activity_name`='李燦瑩「陶路〜師生情誼」陶藝個展', `description`='退休警官李燦瑩陶藝師「陶路〜師生情誼」陶藝個展，預計展出60件陶藝作品。本次展覽以小口瓶與雕塑技法為主，以日本陶土與苗栗瓷土創作，透過陶藝詮釋對人生的感悟與對土地的情感，展現獨特的人文溫度。\r\n李燦瑩老師自警官退休後投入陶藝創作，以精湛的拉坯與浮雕技法塑造出極具詩意的小口瓶，每件作品皆蘊含包容、惜福與聚財納氣的美好寓意。這些作品能幫助都市人在繁忙生活中沉澱心靈，尋得內心的平靜。創作過程中，透過與泥土的互動達到紓壓與放鬆，並藉由陶藝體現對生活的感悟。\r\n此次展覽的作品以小口瓶為主要特色，這類作品在拉坯時需要高度專注，全神貫注地塑形，一氣呵成，展現出藝術家對陶土的掌控與專業技藝。作品成形後，李老師再以浮雕技法在表面層層附著泥漿，使作品更具立體層次與動感。最後，作品經過高溫柴燒，火焰在表面留下獨特的火痕與落灰，隨受火面變化呈現自然的金屬光澤，賦予作品粗獷淳厚的質感，既保有古樸韻味，又展現現代美學特色。\r\n除了小口瓶之外，本次展覽亦呈現多件雕塑作品，展現李燦瑩老師對陶藝的多元探索。透過不同材質與燒製技法的結合，作品不僅蘊含藝術價值，更與生活美學相融合，讓陶藝成為一種能夠陪伴日常、觸動心靈的藝術形式。\r\n誠摯邀請各界陶藝愛好者及民眾蒞臨展覽，共同欣賞李燦瑩老師的陶藝之美，感受陶土在火焰淬鍊後的動人魅力。本展覽不僅呈現陶藝創作的技藝與美學，更傳遞藝術與生活的和諧關係，歡迎大家前來感受陶藝帶來的溫暖與靜謐。', `organizer`='苗栗縣政府文化觀光局', `address`='苗栗縣公館鄉14鄰館南352號', `start_date`='2025-03-18 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='苗栗陶瓷農創園區', `latitude`=25.0422099, `longitude`=121.51947, `ticket_price`='無資料', `source_url`='https://www.mlc.gov.tw/home.aspx', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474ff26b32419285b7348', '苗栗高中第26屆美術班畢業展—「回溯顯影」', '苗栗高中第26屆美術班畢業展—「回溯顯影」，為本屆美術班18位參展學生，集結三年來的學習成果。\r\n回憶對他們而言是一種溫存與念想，像剛洗出來的照片，隨時間推移逐漸清晰。創作過程如顯影，簡單的線條和色塊構建思維，從抽象到具象，反映對未來的憧憬。儘管藝術創作的路途艱難，他們堅持開闢屬於自己的獨特小徑。此次展出的作品媒材有素描、油畫、水彩、水墨、書法、平面設計、電腦繪圖、裝置藝術等，展現多元面貌，除了強調獨特的個人創作外，也加入了需要合作的集體創作，讓創作的經驗更豐富完整。\r\n展出作品中，巫冠霆以水墨〈涅槃〉表達只要保持信念，在困境中必能找到前行的力量；彭彩憶的油畫〈游離〉反應自己面對未來的不確定性和各種挑戰；陳巧瑜的水彩〈桎梏系列～美 〉則是反思普羅大眾的美感，在媒體操作下的單一化；周家郁的郵票設計〈傳統寄憶〉，藉由寄送，憶起逐漸消失的傳統技藝；謝易宸〈音韻悠揚—享受〉，則用素描回憶過往對音樂學習的執著，試圖找回對美術的熱情，及失去已久的初心。\r\n透過展覽回望，這些作品將成為他們青春最珍貴的印記，歡迎各位𦲷臨指教，一起回溯顯影。', '苗栗縣政府', '苗栗縣苗栗市自治路50號', '2025-05-01 00:00:00', '2025-05-25 00:00:00', '苗栗縣政府文化觀光局', 24.565963, 120.8203986, '無資料', 'https://www.mlc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗栗高中第26屆美術班畢業展—「回溯顯影」', `description`='苗栗高中第26屆美術班畢業展—「回溯顯影」，為本屆美術班18位參展學生，集結三年來的學習成果。\r\n回憶對他們而言是一種溫存與念想，像剛洗出來的照片，隨時間推移逐漸清晰。創作過程如顯影，簡單的線條和色塊構建思維，從抽象到具象，反映對未來的憧憬。儘管藝術創作的路途艱難，他們堅持開闢屬於自己的獨特小徑。此次展出的作品媒材有素描、油畫、水彩、水墨、書法、平面設計、電腦繪圖、裝置藝術等，展現多元面貌，除了強調獨特的個人創作外，也加入了需要合作的集體創作，讓創作的經驗更豐富完整。\r\n展出作品中，巫冠霆以水墨〈涅槃〉表達只要保持信念，在困境中必能找到前行的力量；彭彩憶的油畫〈游離〉反應自己面對未來的不確定性和各種挑戰；陳巧瑜的水彩〈桎梏系列～美 〉則是反思普羅大眾的美感，在媒體操作下的單一化；周家郁的郵票設計〈傳統寄憶〉，藉由寄送，憶起逐漸消失的傳統技藝；謝易宸〈音韻悠揚—享受〉，則用素描回憶過往對音樂學習的執著，試圖找回對美術的熱情，及失去已久的初心。\r\n透過展覽回望，這些作品將成為他們青春最珍貴的印記，歡迎各位𦲷臨指教，一起回溯顯影。', `organizer`='苗栗縣政府', `address`='苗栗縣苗栗市自治路50號', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='苗栗縣政府文化觀光局', `latitude`=24.565963, `longitude`=120.8203986, `ticket_price`='無資料', `source_url`='https://www.mlc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474ff26b32419285b7349', '苗栗縣書法學會114「乙巳墨緣會員書法展」', '苗栗縣書法學會秉持一貫之傳統—「以書會友」，每年都會辦理會員書法展，除了於苗栗縣政府文化觀光局展覽外，還會至頭份市公所文藝廳及竹南鎮圖書館辦理展覽，與當地喜歡書法之藝文界朋友交流。\r\n本次展出之書體多元，舉凡篆、隸、楷、行、草五種書體均有展現，其中也有甲骨文的作品，每件作品均是會員多年習作之經驗功力之展現，藉由此次之展出機會，與愛好書法之朋友做交流，教學相長，共同提升書法藝術之水準，歡迎蒞臨參觀。', '苗栗縣政府', '苗栗縣苗栗市自治路50號', '2025-04-01 00:00:00', '2025-04-27 00:00:00', '苗栗縣政府文化觀光局', 24.565963, 120.8203986, '無資料', 'https://www.mlc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='苗栗縣書法學會114「乙巳墨緣會員書法展」', `description`='苗栗縣書法學會秉持一貫之傳統—「以書會友」，每年都會辦理會員書法展，除了於苗栗縣政府文化觀光局展覽外，還會至頭份市公所文藝廳及竹南鎮圖書館辦理展覽，與當地喜歡書法之藝文界朋友交流。\r\n本次展出之書體多元，舉凡篆、隸、楷、行、草五種書體均有展現，其中也有甲骨文的作品，每件作品均是會員多年習作之經驗功力之展現，藉由此次之展出機會，與愛好書法之朋友做交流，教學相長，共同提升書法藝術之水準，歡迎蒞臨參觀。', `organizer`='苗栗縣政府', `address`='苗栗縣苗栗市自治路50號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='苗栗縣政府文化觀光局', `latitude`=24.565963, `longitude`=120.8203986, `ticket_price`='無資料', `source_url`='https://www.mlc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474ff26b32419285b734a', '窗外有藍天- 全國矯正機關收容人書法比賽優選作品展', '展出作品係2023 年由臺灣法學領航協會主辦「全國矯正機關收容人書法比賽」，並將優勝得獎作品裱褙辦理展出，作者均為全國各矯正機關之收容人，書寫內容多為中華文化之千古詩詞名句與勵志詩詞等，冀望透過書法矯正教育能使收容人有新的人生願景，於重返社會後能成為正向有用之人。\r\n收容人將平日努力學習書法的成果，提供給社會各界瞭解矯正機關從精神面改變心性、氣質，達成「脫胎換骨、浴火重生」的境界，也就是使窗內的努力成果能穿透窗外看到藍天，也讓窗外藍天的大眾瞭解窗內收容人變化氣質的不同。', '苗栗縣政府', '苗栗縣苗栗市自治路50號', '2025-04-09 00:00:00', '2025-05-04 00:00:00', '苗栗縣政府文化觀光局', 24.565963, 120.8203986, '無資料', 'https://www.mlc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='窗外有藍天- 全國矯正機關收容人書法比賽優選作品展', `description`='展出作品係2023 年由臺灣法學領航協會主辦「全國矯正機關收容人書法比賽」，並將優勝得獎作品裱褙辦理展出，作者均為全國各矯正機關之收容人，書寫內容多為中華文化之千古詩詞名句與勵志詩詞等，冀望透過書法矯正教育能使收容人有新的人生願景，於重返社會後能成為正向有用之人。\r\n收容人將平日努力學習書法的成果，提供給社會各界瞭解矯正機關從精神面改變心性、氣質，達成「脫胎換骨、浴火重生」的境界，也就是使窗內的努力成果能穿透窗外看到藍天，也讓窗外藍天的大眾瞭解窗內收容人變化氣質的不同。', `organizer`='苗栗縣政府', `address`='苗栗縣苗栗市自治路50號', `start_date`='2025-04-09 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='苗栗縣政府文化觀光局', `latitude`=24.565963, `longitude`=120.8203986, `ticket_price`='無資料', `source_url`='https://www.mlc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474ff26b32419285b734b', '林桂香水墨展—平安喜樂', '年初一到獅頭山走春拜拜，走過輔天宮、勸化堂……蘭亭古廟、風韻生春。祈求一年的平安，拜完廟拾級而上，聽聽蟲鳴鳥叫，駐足欣賞美麗的花草，陣陣涼風徐徐吹來，讓生活中的種種煩惱暫時拋開，頓時整個身心靈放鬆得到舒解。藉此次展出的水墨畫作，讓我們在人生中的酸甜苦澀中多一份寧靜與自在。', ' 財團法人為恭紀念醫院信義院區', '苗栗縣頭份市', '2025-03-04 00:00:00', '2025-07-31 00:00:00', '頭份市（苗栗縣）=', 24.67628243, 120.9189437, '無資料', 'https://epaper.mlc.gov.tw/ebook/Details.aspx?Parser=99,4,17,,,,715', '[]') ON DUPLICATE KEY UPDATE `activity_name`='林桂香水墨展—平安喜樂', `description`='年初一到獅頭山走春拜拜，走過輔天宮、勸化堂……蘭亭古廟、風韻生春。祈求一年的平安，拜完廟拾級而上，聽聽蟲鳴鳥叫，駐足欣賞美麗的花草，陣陣涼風徐徐吹來，讓生活中的種種煩惱暫時拋開，頓時整個身心靈放鬆得到舒解。藉此次展出的水墨畫作，讓我們在人生中的酸甜苦澀中多一份寧靜與自在。', `organizer`=' 財團法人為恭紀念醫院信義院區', `address`='苗栗縣頭份市', `start_date`='2025-03-04 00:00:00', `end_date`='2025-07-31 00:00:00', `location`='頭份市（苗栗縣）=', `latitude`=24.67628243, `longitude`=120.9189437, `ticket_price`='無資料', `source_url`='https://epaper.mlc.gov.tw/ebook/Details.aspx?Parser=99,4,17,,,,715', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474ff26b32419285b734c', '電影聽賞《一個人的朝聖》', '邀請資深影評人黃英雄老師，為大家呈現一場極具感官魅力的電影體驗。活動中，將播放《一個人的朝聖》這部電影，黃老師於電影播放的同時，同步口述電影中的情節、人物角色以及對白，讓視障朋友們在黃老師生動的描述和獨特的評論下，深入了解電影中角色的心路歷程和電影情節。此活動目的，讓視障者透過口這影像的描述，也能用心看電影，享受看電影的樂趣。', '高雄市立圖書館總館', '高雄市苓雅區001鄰五福一路67號', '2025-06-14 00:00:00', '2025-06-14 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='電影聽賞《一個人的朝聖》', `description`='邀請資深影評人黃英雄老師，為大家呈現一場極具感官魅力的電影體驗。活動中，將播放《一個人的朝聖》這部電影，黃老師於電影播放的同時，同步口述電影中的情節、人物角色以及對白，讓視障朋友們在黃老師生動的描述和獨特的評論下，深入了解電影中角色的心路歷程和電影情節。此活動目的，讓視障者透過口這影像的描述，也能用心看電影，享受看電影的樂趣。', `organizer`='高雄市立圖書館總館', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-06-14 00:00:00', `end_date`='2025-06-14 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474ff26b32419285b734d', '康懷方電腦古典漫畫藝術創作展', '康懷方屬於在地蓬山美術協會會員，建國科技大學商業設計系畢業，目前在家自己成立漫畫文創工作室，衷心於電腦古典人物漫畫之創意表現，最起先由布袋戲人物之繪畫漸漸的轉向到戲劇中的古典仕女漫畫造型，其藝術表現形式是屬於少數年輕人會深入的，所以有一種傳統的特異性與獨特性，必須孤立於一般時下流行之外才能獨享分享，此特質的創意表現模式，值得您前來特所觀賞。', '苗栗縣苑裡鎮公所', '苗栗縣苑裡鎮出水路64-11號', '2025-04-06 00:00:00', '2025-04-27 00:00:00', '苑裡濱海藝文中心', 24.455054, 120.6449196, '無資料', 'https://epaper.mlc.gov.tw/ebook/Details.aspx?Parser=99,4,17,,,,715', '[]') ON DUPLICATE KEY UPDATE `activity_name`='康懷方電腦古典漫畫藝術創作展', `description`='康懷方屬於在地蓬山美術協會會員，建國科技大學商業設計系畢業，目前在家自己成立漫畫文創工作室，衷心於電腦古典人物漫畫之創意表現，最起先由布袋戲人物之繪畫漸漸的轉向到戲劇中的古典仕女漫畫造型，其藝術表現形式是屬於少數年輕人會深入的，所以有一種傳統的特異性與獨特性，必須孤立於一般時下流行之外才能獨享分享，此特質的創意表現模式，值得您前來特所觀賞。', `organizer`='苗栗縣苑裡鎮公所', `address`='苗栗縣苑裡鎮出水路64-11號', `start_date`='2025-04-06 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='苑裡濱海藝文中心', `latitude`=24.455054, `longitude`=120.6449196, `ticket_price`='無資料', `source_url`='https://epaper.mlc.gov.tw/ebook/Details.aspx?Parser=99,4,17,,,,715', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e474ff26b32419285b734e', '劉貞老師書畫個展—意象之美', '意象繪畫是將自己內在心靈視窗所見的物象感受與情感之反應相互產生共鳴，透過筆墨來表現、書法和詩句意境創作表現、是中國極為特殊的藝術創作為西方藝術所無。\r\n苗栗高中退休教師「劉貞」將近年來的田園生活、爬山、旅行和閱讀心得把所見所聞放在創作裡展出內容是水墨和書法兩大項。歡迎喜愛藝術的朋友前來欣賞與指導。', '苗栗縣西湖鄉公所', '苗栗縣西湖鄉13鄰194-4號', '2025-03-05 00:00:00', '2025-04-25 00:00:00', '吳濁流文學藝術館', 24.5235061, 120.7780948, '無資料', 'https://www.facebook.com/profile.php?id=100083139282083', '[]') ON DUPLICATE KEY UPDATE `activity_name`='劉貞老師書畫個展—意象之美', `description`='意象繪畫是將自己內在心靈視窗所見的物象感受與情感之反應相互產生共鳴，透過筆墨來表現、書法和詩句意境創作表現、是中國極為特殊的藝術創作為西方藝術所無。\r\n苗栗高中退休教師「劉貞」將近年來的田園生活、爬山、旅行和閱讀心得把所見所聞放在創作裡展出內容是水墨和書法兩大項。歡迎喜愛藝術的朋友前來欣賞與指導。', `organizer`='苗栗縣西湖鄉公所', `address`='苗栗縣西湖鄉13鄰194-4號', `start_date`='2025-03-05 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='吳濁流文學藝術館', `latitude`=24.5235061, `longitude`=120.7780948, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100083139282083', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e4a6f78f15adefa04e0c89', '【藝文講座】陶淵明的田園交響曲', '陶淵明是中國文學史上的田園詩人之祖，他離棄官場選擇田園作為實踐隱逸生活的場域，既「結廬在人境」又能「復得返自然」。他所開展的田園生活得以滿足人在大地上安居最基本的生存需求，經由勞動及群居生活，與天地和諧共存。本次講座蔡瑜老師將邀請閱聽者與陶淵明共同徜徉在清和閒靜的田園氛圍裡。\r\n\r\n■時間：2025年5月17日（六）14：00-16：00\r\n\r\n■地點：林建生紀念圖書館地下樓（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額180位，七歲以上，免費報名入場。\r\n#額滿後恕無現場報名\r\n\r\n■報名方式：5/7（三）10:00起，網路報名 https://www.accupass.com/go/1140517\r\n\r\n**80歲以上長者可電話報名：02-22855188\r\n\r\n■講者：\r\n\r\n蔡瑜，臺灣大學中國文學系博士，現任臺灣大學中國文學系特聘教授。曾任日本京都大學、捷克查理大學、加州大學戴維斯分校客座教授，並獲科技部傑出研究獎。主治六朝、唐宋詩學，特別關懷身心與自然的相互關係，究心於詩歌體式的韻律美感。\r\n\r\n著有關於自然、山水、田園、風景及詩律學的系列著作。主要論著有《高棅詩學研究》、《宋代唐詩學》、《唐詩學探索》、《中國抒情詩的世界》、《陶淵明的人境詩學》、《唐代詩律發展史論》。\r\n\r\n★活動預告：5/24（六）14:00【陶淵明的生死智慧】，蔡瑜老師主講\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★網址： https://www.ljsedu.org.tw\r\n★歡迎加入《林建生基金會》line 好友～ https://bit.ly/2KFVgg2\r\n', '財團法人紀念林建生教育基金會', '新北市蘆洲區三民路178號', '2025-05-17 00:00:00', '2025-05-17 00:00:00', '林建生紀念圖書館', 25.08927173, 121.4712461, '七歲以上，免費報名入場', 'https://www.accupass.com/go/1140517', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【藝文講座】陶淵明的田園交響曲', `description`='陶淵明是中國文學史上的田園詩人之祖，他離棄官場選擇田園作為實踐隱逸生活的場域，既「結廬在人境」又能「復得返自然」。他所開展的田園生活得以滿足人在大地上安居最基本的生存需求，經由勞動及群居生活，與天地和諧共存。本次講座蔡瑜老師將邀請閱聽者與陶淵明共同徜徉在清和閒靜的田園氛圍裡。\r\n\r\n■時間：2025年5月17日（六）14：00-16：00\r\n\r\n■地點：林建生紀念圖書館地下樓（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額180位，七歲以上，免費報名入場。\r\n#額滿後恕無現場報名\r\n\r\n■報名方式：5/7（三）10:00起，網路報名 https://www.accupass.com/go/1140517\r\n\r\n**80歲以上長者可電話報名：02-22855188\r\n\r\n■講者：\r\n\r\n蔡瑜，臺灣大學中國文學系博士，現任臺灣大學中國文學系特聘教授。曾任日本京都大學、捷克查理大學、加州大學戴維斯分校客座教授，並獲科技部傑出研究獎。主治六朝、唐宋詩學，特別關懷身心與自然的相互關係，究心於詩歌體式的韻律美感。\r\n\r\n著有關於自然、山水、田園、風景及詩律學的系列著作。主要論著有《高棅詩學研究》、《宋代唐詩學》、《唐詩學探索》、《中國抒情詩的世界》、《陶淵明的人境詩學》、《唐代詩律發展史論》。\r\n\r\n★活動預告：5/24（六）14:00【陶淵明的生死智慧】，蔡瑜老師主講\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★網址： https://www.ljsedu.org.tw\r\n★歡迎加入《林建生基金會》line 好友～ https://bit.ly/2KFVgg2\r\n', `organizer`='財團法人紀念林建生教育基金會', `address`='新北市蘆洲區三民路178號', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='林建生紀念圖書館', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='七歲以上，免費報名入場', `source_url`='https://www.accupass.com/go/1140517', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e4a7a48f15adefa04e0c8a', '【藝文講座】陶淵明的生死智慧', '人生是由生至死的完整歷程，人如何面對死亡，左右著人如何面對生存。陶淵明以詩思直面人生的界限，為世人深拓生死這個永恆議題。他既與當時流行的佛教生死觀深刻論辯；也為自己寫下挽歌與祭文，接受「死亡將至」的真象；最終兼攝儒道思想，融匯出委運任化與識運知命的生死智慧。本次講座蔡瑜老師將邀請閱聽者與陶淵明一起探索面對生死的智慧。\r\n\r\n■時間：2025年5月24日（六）14：00-16：00\r\n\r\n■地點：林建生紀念圖書館地下樓（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額180位，七歲以上，免費報名入場。\r\n#額滿後恕無現場報名\r\n\r\n■報名方式：5/14（三）10:00起，網路報名 https://www.accupass.com/go/1140524\r\n\r\n**80歲以上長者可電話報名：02-22855188\r\n\r\n■講者：\r\n\r\n蔡瑜，臺灣大學中國文學系博士，現任臺灣大學中國文學系特聘教授。曾任日本京都大學、捷克查理大學、加州大學戴維斯分校客座教授，並獲科技部傑出研究獎。主治六朝、唐宋詩學，特別關懷身心與自然的相互關係，究心於詩歌體式的韻律美感。\r\n\r\n著有關於自然、山水、田園、風景及詩律學的系列著作。主要論著有《高棅詩學研究》、《宋代唐詩學》、《唐詩學探索》、《中國抒情詩的世界》、《陶淵明的人境詩學》、《唐代詩律發展史論》。\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★網址： https://www.ljsedu.org.tw\r\n★歡迎加入《林建生基金會》line 好友～ https://bit.ly/2KFVgg2\r\n', '財團法人紀念林建生教育基金會', '新北市蘆洲區三民路178號', '2025-05-24 00:00:00', '2025-05-24 00:00:00', '林建生紀念圖書館', 25.08927173, 121.4712461, '七歲以上, 免費報名入場', 'https://www.accupass.com/go/1140524', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【藝文講座】陶淵明的生死智慧', `description`='人生是由生至死的完整歷程，人如何面對死亡，左右著人如何面對生存。陶淵明以詩思直面人生的界限，為世人深拓生死這個永恆議題。他既與當時流行的佛教生死觀深刻論辯；也為自己寫下挽歌與祭文，接受「死亡將至」的真象；最終兼攝儒道思想，融匯出委運任化與識運知命的生死智慧。本次講座蔡瑜老師將邀請閱聽者與陶淵明一起探索面對生死的智慧。\r\n\r\n■時間：2025年5月24日（六）14：00-16：00\r\n\r\n■地點：林建生紀念圖書館地下樓（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額180位，七歲以上，免費報名入場。\r\n#額滿後恕無現場報名\r\n\r\n■報名方式：5/14（三）10:00起，網路報名 https://www.accupass.com/go/1140524\r\n\r\n**80歲以上長者可電話報名：02-22855188\r\n\r\n■講者：\r\n\r\n蔡瑜，臺灣大學中國文學系博士，現任臺灣大學中國文學系特聘教授。曾任日本京都大學、捷克查理大學、加州大學戴維斯分校客座教授，並獲科技部傑出研究獎。主治六朝、唐宋詩學，特別關懷身心與自然的相互關係，究心於詩歌體式的韻律美感。\r\n\r\n著有關於自然、山水、田園、風景及詩律學的系列著作。主要論著有《高棅詩學研究》、《宋代唐詩學》、《唐詩學探索》、《中國抒情詩的世界》、《陶淵明的人境詩學》、《唐代詩律發展史論》。\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★網址： https://www.ljsedu.org.tw\r\n★歡迎加入《林建生基金會》line 好友～ https://bit.ly/2KFVgg2\r\n', `organizer`='財團法人紀念林建生教育基金會', `address`='新北市蘆洲區三民路178號', `start_date`='2025-05-24 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='林建生紀念圖書館', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='七歲以上, 免費報名入場', `source_url`='https://www.accupass.com/go/1140524', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e518a88f15adefa04e0c8b', '老派趴踢Night', '節目介紹\r\n\r\n★    臺灣音樂史上第一首臺語歌《桃花泣血記 》爵士新衣\r\n★    集結國內多位金曲獎爵士好手，嶄新詮釋1930年代-1950年代經典臺灣歌曲\r\n \r\n爵士搖擺引領大家回到臺灣流行音樂的最初\r\n音樂會的開始，由第一首臺語流行歌曲〈桃花泣血記〉作為序曲，帶領大家回到1930-1950的臺灣流行之初。老歌新唱、經典旋律換上爵士新衣，音樂會將由榮獲臺北市傑出演藝團隊及Taiwan Top的臺北爵士大樂隊與實力派歌手李欣玲、陳章健聯手傳唱〈高山青〉、〈姑娘十八一朵花〉、〈阮若是打開心內的門窗〉、〈南都之夜〉等曲目。而臺灣歌謠之父鄧雨賢-四月望雨-〈四季紅〉、〈月夜愁〉、〈望春風〉、〈雨夜花〉四首經典曲目，也將由葛萊美獎得主Aaron Lington重新改編為15分鐘的爵士大樂團組曲。復古時光、爵士狂潮，老派趴踢Night將帶領您沈浸在滿滿的音符與回憶中。', '臺北爵士大樂隊', '高雄市鳳山區三多一路1號', '2025-05-15 00:00:00', '2025-05-15 00:00:00', '衛武營表演廳', 22.61379251, 120.3554359, '800 | 1200', 'https://www.opentix.life/event/1897139076826075136?srsltid=AfmBOopjPjRlw7No0J6K0Aif3PIRnU7MZbXqDEm4ckXaK9FCyVmVyc_H', '[]') ON DUPLICATE KEY UPDATE `activity_name`='老派趴踢Night', `description`='節目介紹\r\n\r\n★    臺灣音樂史上第一首臺語歌《桃花泣血記 》爵士新衣\r\n★    集結國內多位金曲獎爵士好手，嶄新詮釋1930年代-1950年代經典臺灣歌曲\r\n \r\n爵士搖擺引領大家回到臺灣流行音樂的最初\r\n音樂會的開始，由第一首臺語流行歌曲〈桃花泣血記〉作為序曲，帶領大家回到1930-1950的臺灣流行之初。老歌新唱、經典旋律換上爵士新衣，音樂會將由榮獲臺北市傑出演藝團隊及Taiwan Top的臺北爵士大樂隊與實力派歌手李欣玲、陳章健聯手傳唱〈高山青〉、〈姑娘十八一朵花〉、〈阮若是打開心內的門窗〉、〈南都之夜〉等曲目。而臺灣歌謠之父鄧雨賢-四月望雨-〈四季紅〉、〈月夜愁〉、〈望春風〉、〈雨夜花〉四首經典曲目，也將由葛萊美獎得主Aaron Lington重新改編為15分鐘的爵士大樂團組曲。復古時光、爵士狂潮，老派趴踢Night將帶領您沈浸在滿滿的音符與回憶中。', `organizer`='臺北爵士大樂隊', `address`='高雄市鳳山區三多一路1號', `start_date`='2025-05-15 00:00:00', `end_date`='2025-05-15 00:00:00', `location`='衛武營表演廳', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='800 | 1200', `source_url`='https://www.opentix.life/event/1897139076826075136?srsltid=AfmBOopjPjRlw7No0J6K0Aif3PIRnU7MZbXqDEm4ckXaK9FCyVmVyc_H', `image_url`='[]';
