INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cae326b32419285b736c', '桃園市禾心藝文協會會員聯展', '    桃園禾心藝文協會，是一群愛好藝文的夥伴們，聚集在一起，平時互相切磋琢磨，到了機會來臨時，就是各展身手的時候了，每到展覽或公益活動，正是發會團隊精神的最佳時機。\r\n    近年來。聯展或學員個展與義賣活動，不下數十場，深受好評，近年在桃園市立圖書館新屋分館展出，也有很好的成績，今年特別爭取到龍潭閱覽室展出，會員門盡心盡力，展現不同的畫風的創作，期望大家能來參觀指教，給我們鼓勵，讓我們有更大的信心與勇氣，勇往前進，繼續創作，展現更好的成績，以回饋社會。\r\n', '桃園市立圖書館', '桃園市龍潭區中正路210號', '2025-04-02 00:00:00', '2025-04-29 00:00:00', '桃園市立圖書館龍潭閱覽室', 24.85064954, 121.2117877, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園市禾心藝文協會會員聯展', `description`='    桃園禾心藝文協會，是一群愛好藝文的夥伴們，聚集在一起，平時互相切磋琢磨，到了機會來臨時，就是各展身手的時候了，每到展覽或公益活動，正是發會團隊精神的最佳時機。\r\n    近年來。聯展或學員個展與義賣活動，不下數十場，深受好評，近年在桃園市立圖書館新屋分館展出，也有很好的成績，今年特別爭取到龍潭閱覽室展出，會員門盡心盡力，展現不同的畫風的創作，期望大家能來參觀指教，給我們鼓勵，讓我們有更大的信心與勇氣，勇往前進，繼續創作，展現更好的成績，以回饋社會。\r\n', `organizer`='桃園市立圖書館', `address`='桃園市龍潭區中正路210號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='桃園市立圖書館龍潭閱覽室', `latitude`=24.85064954, `longitude`=121.2117877, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
