INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5caeb26b32419285b736f', '竹南鎮公所114年度上半年研習班：拼布進階班、草書書法研習班、手作療癒系所、油畫研習班、現代花藝創作研習班', '開設班別：拼布進階班（25人）、草書書法研習班（25人）、手作療癒系所（20人）、油畫研習班（24人）、現代花藝創作研習班（25人）。\r\n報名資格：竹南鎮民(年滿18歲以上者)，3月1日起開放外鄉鎮民眾報名。\r\n報名日期：114年2月26日上午9點起至114年3月7日下午4點止。\r\n連絡電話：037-463043\r\n報名方式：採網路報名，在名額內依報名先後錄取，額滿為止。\r\n注意事項：課程報名人數未滿15人不開課。\r\n報名網址：\r\nhttps://www.beclass.com/rid=294fe6367aaf8891dcc3\r\n\r\n本活動不收保證金。如無故缺課逾二堂以上者，暫停其參加本館辦理之相關活動一次。\r\n活動詳情請至竹南鎮公所全球資訊網-圖書館-最新消息內查詢。\r\nhttps://www.chunan.gov.tw/News_Content.aspx?n=2791&s=833475', '苗栗縣竹南鎮公所', '苗栗縣竹南鎮永貞路二段196號', '2025-04-07 00:00:00', '2025-07-04 00:00:00', '李科永紀念圖書館', 24.69862459, 120.8777316, '拼布進階班材料費+2000;手作療癒系所材料費+2250;現代花藝創作研習班材料費+3000', 'https://www.facebook.com/groups/380399781976548/user/61571662695053', '[]') ON DUPLICATE KEY UPDATE `activity_name`='竹南鎮公所114年度上半年研習班：拼布進階班、草書書法研習班、手作療癒系所、油畫研習班、現代花藝創作研習班', `description`='開設班別：拼布進階班（25人）、草書書法研習班（25人）、手作療癒系所（20人）、油畫研習班（24人）、現代花藝創作研習班（25人）。\r\n報名資格：竹南鎮民(年滿18歲以上者)，3月1日起開放外鄉鎮民眾報名。\r\n報名日期：114年2月26日上午9點起至114年3月7日下午4點止。\r\n連絡電話：037-463043\r\n報名方式：採網路報名，在名額內依報名先後錄取，額滿為止。\r\n注意事項：課程報名人數未滿15人不開課。\r\n報名網址：\r\nhttps://www.beclass.com/rid=294fe6367aaf8891dcc3\r\n\r\n本活動不收保證金。如無故缺課逾二堂以上者，暫停其參加本館辦理之相關活動一次。\r\n活動詳情請至竹南鎮公所全球資訊網-圖書館-最新消息內查詢。\r\nhttps://www.chunan.gov.tw/News_Content.aspx?n=2791&s=833475', `organizer`='苗栗縣竹南鎮公所', `address`='苗栗縣竹南鎮永貞路二段196號', `start_date`='2025-04-07 00:00:00', `end_date`='2025-07-04 00:00:00', `location`='李科永紀念圖書館', `latitude`=24.69862459, `longitude`=120.8777316, `ticket_price`='拼布進階班材料費+2000;手作療癒系所材料費+2250;現代花藝創作研習班材料費+3000', `source_url`='https://www.facebook.com/groups/380399781976548/user/61571662695053', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5caee26b32419285b7370', '客家風情，韻揚四季~2025舞韻風華社群展演', '活動內容有客家歌謠及舞蹈表演，希望透過活動的辦理及宣傳，帶動社區民眾對客家藝文活動的參與。', '桃園市樂齡發展協會', '桃園市平鎮區環南路三段88號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '桃園市立圖書館平鎮分館', 24.92117923, 121.2140051, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='客家風情，韻揚四季~2025舞韻風華社群展演', `description`='活動內容有客家歌謠及舞蹈表演，希望透過活動的辦理及宣傳，帶動社區民眾對客家藝文活動的參與。', `organizer`='桃園市樂齡發展協會', `address`='桃園市平鎮區環南路三段88號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='桃園市立圖書館平鎮分館', `latitude`=24.92117923, `longitude`=121.2140051, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5caee26b32419285b7371', '主題書展4月', '每個人都是獨一無二的存在，性別不該被單一框架所定義，愛與尊重更不應設限。圖書館誠摯邀請您參觀「愛無界：性別多元的世界」主題書展，透過閱讀探索多元性別的豐富面貌，理解性別光譜上的每一種存在，並學會以更包容與開放的心態看待世界。', '桃園市立圖書館', '桃園市平鎮區環南路三段88號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '桃園市立圖書館平鎮分館', 24.92117923, 121.2140051, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='主題書展4月', `description`='每個人都是獨一無二的存在，性別不該被單一框架所定義，愛與尊重更不應設限。圖書館誠摯邀請您參觀「愛無界：性別多元的世界」主題書展，透過閱讀探索多元性別的豐富面貌，理解性別光譜上的每一種存在，並學會以更包容與開放的心態看待世界。', `organizer`='桃園市立圖書館', `address`='桃園市平鎮區環南路三段88號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='桃園市立圖書館平鎮分館', `latitude`=24.92117923, `longitude`=121.2140051, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5caef26b32419285b7375', '十全拾美舞墨情', '中華舞墨藝術發展學會「十全拾美舞墨情」國畫展以山水、花鳥與昆蟲為創作主題，透過細膩的筆觸與豐富的墨色，展現自然界的靜謐與蓬勃生機。畫作中不僅呈現山川河流的壯闊、綠意盎然的生命姿態，更注重情感的表達與畫面的靈動。每一幅作品都是對大自然無聲的回應與詩意的詮釋，讓觀者彷彿置身於山林間，感受微風拂過的輕盈與蟲鳴鳥語的和諧。', '桃園市立圖書館', '桃園市平鎮區環南路三段88號', '2025-04-02 00:00:00', '2025-04-29 00:00:00', '桃園市立圖書館平鎮分館', 24.92117923, 121.2140051, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='十全拾美舞墨情', `description`='中華舞墨藝術發展學會「十全拾美舞墨情」國畫展以山水、花鳥與昆蟲為創作主題，透過細膩的筆觸與豐富的墨色，展現自然界的靜謐與蓬勃生機。畫作中不僅呈現山川河流的壯闊、綠意盎然的生命姿態，更注重情感的表達與畫面的靈動。每一幅作品都是對大自然無聲的回應與詩意的詮釋，讓觀者彷彿置身於山林間，感受微風拂過的輕盈與蟲鳴鳥語的和諧。', `organizer`='桃園市立圖書館', `address`='桃園市平鎮區環南路三段88號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='桃園市立圖書館平鎮分館', `latitude`=24.92117923, `longitude`=121.2140051, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5caf226b32419285b7377', '藝想不到-平鎮區文化集會所國畫寫意花鳥班研習成果展', '平鎮區文化集會所「國畫寫意花鳥班」班內大都是退休人士開始學習國畫，並在林振彪老師的指導下，逐步掌握花鳥寫意技巧。透過畫筆將四季的花鳥與山水風景呈現在作品上，細膩的筆觸以及乾、濕、濃、淡、焦繪畫出嫣然綻放的花朵還是栩栩如生的鳥兒或者是雄偉壯觀的山景，都蘊含了她們對美好生活的追求與對藝術的熱情。帶領著大家感受「藝想不到」的畫作，這也是退休後，讓我們「意想不到」會用水墨畫的方式呈現在展館中。', '無資料', '桃園市新屋區中興路91巷11號', '2025-04-02 00:00:00', '2025-04-28 00:00:00', '桃園市立圖書館新屋分館', 24.97280352, 121.067758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝想不到-平鎮區文化集會所國畫寫意花鳥班研習成果展', `description`='平鎮區文化集會所「國畫寫意花鳥班」班內大都是退休人士開始學習國畫，並在林振彪老師的指導下，逐步掌握花鳥寫意技巧。透過畫筆將四季的花鳥與山水風景呈現在作品上，細膩的筆觸以及乾、濕、濃、淡、焦繪畫出嫣然綻放的花朵還是栩栩如生的鳥兒或者是雄偉壯觀的山景，都蘊含了她們對美好生活的追求與對藝術的熱情。帶領著大家感受「藝想不到」的畫作，這也是退休後，讓我們「意想不到」會用水墨畫的方式呈現在展館中。', `organizer`='無資料', `address`='桃園市新屋區中興路91巷11號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-28 00:00:00', `location`='桃園市立圖書館新屋分館', `latitude`=24.97280352, `longitude`=121.067758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
