INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb1e26b32419285b738d', '4月高雄市電影館｜PINA  PINA【普遍級】', '「舞吧，舞吧…不然我們就迷失了。」\r\n\r\n★ 2011 歐洲電影獎 最佳歐洲紀錄片獎\r\n\r\n德國名導文溫德斯向已逝德國現代舞大師碧娜鮑許（Pina Bausch）致敬，重現皮娜鮑許生前在「烏帕塔舞蹈劇場」的表演以及三十年舞蹈生活愛恨點滴。收錄著名的四齣舞作：〈春之祭〉、〈慕勒咖啡館〉、〈交際場〉、〈滿月〉。碧娜鮑許以舞蹈劇場形式、美麗視覺加上深刻的人生思考聞名，獨特的風格始終是表演藝術界的美麗傳奇。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-08 00:00:00', '2025-04-29 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優惠票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list/43b7f1a23c9f5dd0383b3fafd7bd4cd3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜PINA  PINA【普遍級】', `description`='「舞吧，舞吧…不然我們就迷失了。」\r\n\r\n★ 2011 歐洲電影獎 最佳歐洲紀錄片獎\r\n\r\n德國名導文溫德斯向已逝德國現代舞大師碧娜鮑許（Pina Bausch）致敬，重現皮娜鮑許生前在「烏帕塔舞蹈劇場」的表演以及三十年舞蹈生活愛恨點滴。收錄著名的四齣舞作：〈春之祭〉、〈慕勒咖啡館〉、〈交際場〉、〈滿月〉。碧娜鮑許以舞蹈劇場形式、美麗視覺加上深刻的人生思考聞名，獨特的風格始終是表演藝術界的美麗傳奇。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-08 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優惠票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/43b7f1a23c9f5dd0383b3fafd7bd4cd3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb1e26b32419285b738e', '4月高雄市電影館｜我的完美日常 Perfect Days【普遍級】', '文溫德斯 × 役所廣司 交織詩意浪漫的東京日常\r\n\r\n★ 2023 坎城影展 最佳男主角獎\r\n\r\n自命師承小津安二郎的文溫德斯，這一次在東京拍出獨屬於他的日本電影。本片以路瑞德的同名神曲為名，由役所廣司飾演東京公廁清潔職人平山，他的日常大抵是起床、工作、單車散策、泡錢湯、伴書入眠，平凡間有自成一派的悠哉淡然，喜歡用底片相機拍照、聽錄音帶、喝喝小酒的他，享受著獨有的老派浪漫，在看似完美的日常裡，終究也有一言難盡的人生艱境。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-05 00:00:00', '2025-04-25 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list/43b7f1a23c9f5dd0383b3fafd7bd4cd3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜我的完美日常 Perfect Days【普遍級】', `description`='文溫德斯 × 役所廣司 交織詩意浪漫的東京日常\r\n\r\n★ 2023 坎城影展 最佳男主角獎\r\n\r\n自命師承小津安二郎的文溫德斯，這一次在東京拍出獨屬於他的日本電影。本片以路瑞德的同名神曲為名，由役所廣司飾演東京公廁清潔職人平山，他的日常大抵是起床、工作、單車散策、泡錢湯、伴書入眠，平凡間有自成一派的悠哉淡然，喜歡用底片相機拍照、聽錄音帶、喝喝小酒的他，享受著獨有的老派浪漫，在看似完美的日常裡，終究也有一言難盡的人生艱境。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/43b7f1a23c9f5dd0383b3fafd7bd4cd3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb1f26b32419285b738f', '創意族譜優勝作品展', '臺北市立文獻館自94年起辦理創意族譜設計比賽迄今，對提升中小學生族譜知識、了解本土歷史文化，起到寓教於樂之作用。本年度創意族譜展，6月6日起至7月13日於西門町的西本願寺廣場樹心會館展出，除陳列學生優勝作品外，活動免費入場，歡迎民眾到場參觀。', '臺北市立文獻館', '臺北市萬華區中華路一段174號', '2025-06-06 00:00:00', '2025-07-13 00:00:00', '西本願寺（鐘樓、樹心會館）', 25.0285899, 121.4979858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='創意族譜優勝作品展', `description`='臺北市立文獻館自94年起辦理創意族譜設計比賽迄今，對提升中小學生族譜知識、了解本土歷史文化，起到寓教於樂之作用。本年度創意族譜展，6月6日起至7月13日於西門町的西本願寺廣場樹心會館展出，除陳列學生優勝作品外，活動免費入場，歡迎民眾到場參觀。', `organizer`='臺北市立文獻館', `address`='臺北市萬華區中華路一段174號', `start_date`='2025-06-06 00:00:00', `end_date`='2025-07-13 00:00:00', `location`='西本願寺（鐘樓、樹心會館）', `latitude`=25.0285899, `longitude`=121.4979858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
