INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2626b32419285b7394', '4月高雄市電影館｜青春末世物語 Happyend【保護級】', '坂本龍一之子空音央 一鳴驚人首部劇情長片\r\n★ 2024威尼斯影展 地平線單元\r\n\r\n高中生悠多、小幸與朋友盡情玩樂。從夜店警察臨檢中逃脫、潛入教室放送電音節奏，瞧不起體制歧視的勢利造作。未料一次惡作劇引發校長追究，安裝電子保全全面監控，掀起思潮風波。悠多只想活在當下追逐音樂夢，小幸則因身分認同覺醒走上街頭，在地震頻繁的壓抑氛圍中，他們的友誼也在畢業前夕逐漸失控。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-04 00:00:00', '2025-04-19 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜青春末世物語 Happyend【保護級】', `description`='坂本龍一之子空音央 一鳴驚人首部劇情長片\r\n★ 2024威尼斯影展 地平線單元\r\n\r\n高中生悠多、小幸與朋友盡情玩樂。從夜店警察臨檢中逃脫、潛入教室放送電音節奏，瞧不起體制歧視的勢利造作。未料一次惡作劇引發校長追究，安裝電子保全全面監控，掀起思潮風波。悠多只想活在當下追逐音樂夢，小幸則因身分認同覺醒走上街頭，在地震頻繁的壓抑氛圍中，他們的友誼也在畢業前夕逐漸失控。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-04 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2726b32419285b7398', '4月高雄市電影館｜喵的奇幻漂流 Flow【普遍級】', '奧斯卡金獎名導吉勒摩戴托羅盛讚 獲獎無數年度必看動畫\r\n★ 2024 安錫國際動畫影展 評審團獎、最佳原創音樂獎\r\n★ 2025 金球獎 最佳動畫長片獎\r\n\r\n當世界即將走向末日，卻充斥著人類存在的痕跡。而當一隻黑貓的家園被大洪水摧毀後，登上一艘小船當作它的避難所，但卻發現船上住著各式各樣的動物，儘管他們無法溝通，但它們仍必須合作，穿梭於神秘的漂流世界，面對各種挑戰和危險。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-01 00:00:00', '2025-04-27 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '無資料', 'https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜喵的奇幻漂流 Flow【普遍級】', `description`='奧斯卡金獎名導吉勒摩戴托羅盛讚 獲獎無數年度必看動畫\r\n★ 2024 安錫國際動畫影展 評審團獎、最佳原創音樂獎\r\n★ 2025 金球獎 最佳動畫長片獎\r\n\r\n當世界即將走向末日，卻充斥著人類存在的痕跡。而當一隻黑貓的家園被大洪水摧毀後，登上一艘小船當作它的避難所，但卻發現船上住著各式各樣的動物，儘管他們無法溝通，但它們仍必須合作，穿梭於神秘的漂流世界，面對各種挑戰和危險。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='無資料', `source_url`='https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2726b32419285b739a', '4月高雄市電影館｜QUEER QUEER【限制級】', '《以你的名字呼喚我》名導 打造年度動人愛情力作\r\n★  2024 威尼斯影展 主競賽\r\n\r\n1950年代，居住在墨西哥移民社區的威廉李成日與同鄉好友藉酒消愁，儘管渴望愛情，卻始終無法觸及那份深刻的情感。直到某天，他邂逅了年輕俊美、初來乍到的尤金阿勒頓，尤金的出現宛如一顆石子拋進平靜的湖面，威廉的內心激起一圈圈漣漪。隨著兩人的關係發展，威廉的內心世界被深深觸動，在孤獨與渴望的交織之下，開始了面對一段難以預測的愛情旅程。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-01 00:00:00', '2025-04-29 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;全票+260', 'https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜QUEER QUEER【限制級】', `description`='《以你的名字呼喚我》名導 打造年度動人愛情力作\r\n★  2024 威尼斯影展 主競賽\r\n\r\n1950年代，居住在墨西哥移民社區的威廉李成日與同鄉好友藉酒消愁，儘管渴望愛情，卻始終無法觸及那份深刻的情感。直到某天，他邂逅了年輕俊美、初來乍到的尤金阿勒頓，尤金的出現宛如一顆石子拋進平靜的湖面，威廉的內心激起一圈圈漣漪。隨著兩人的關係發展，威廉的內心世界被深深觸動，在孤獨與渴望的交織之下，開始了面對一段難以預測的愛情旅程。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2726b32419285b739c', '4月高雄市電影館｜我依然在此 I''m Still Here【輔12級】', '《中央車站》金熊獎名導 華特沙勒斯 最新撼世鉅作\r\n★ 2025 奧斯卡金像獎 最佳國際影片獎\r\n★ 2025 金球獎 戲劇類最佳女主角獎\r\n\r\n根據真實故事改編，1970年代的巴西，台灣再熟悉不過的白色恐怖。一名母親必須挺身而出，找尋丈夫失蹤的真相，同時持續帶給孩子們愛與希望。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-02 00:00:00', '2025-04-19 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '無資料', 'https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜我依然在此 I''m Still Here【輔12級】', `description`='《中央車站》金熊獎名導 華特沙勒斯 最新撼世鉅作\r\n★ 2025 奧斯卡金像獎 最佳國際影片獎\r\n★ 2025 金球獎 戲劇類最佳女主角獎\r\n\r\n根據真實故事改編，1970年代的巴西，台灣再熟悉不過的白色恐怖。一名母親必須挺身而出，找尋丈夫失蹤的真相，同時持續帶給孩子們愛與希望。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='無資料', `source_url`='https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2726b32419285b739d', '4月高雄市電影館｜有病才會喜歡你 LoveSick【普遍級】', '有病真好？！ 一場由裝病開始的愛情故事\r\n\r\n問題少年葉子杰（詹懷雲 飾），即將面臨退學處分，在一次陰錯陽差下決定將計就計裝病。但與葉子杰同名的班長葉梓潔（江齊 飾），卻彷彿裝了測謊雷達，不放過任何一個子杰疑似裝病的證據。她到保健室查勤並沒收垃圾食物，甚至化身外送員只為確認他是否真的有病！「裝病仔」與「有病姊」，兩人在諜對諜的互動中，也開始產生了不一樣的情愫。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-02 00:00:00', '2025-04-23 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜有病才會喜歡你 LoveSick【普遍級】', `description`='有病真好？！ 一場由裝病開始的愛情故事\r\n\r\n問題少年葉子杰（詹懷雲 飾），即將面臨退學處分，在一次陰錯陽差下決定將計就計裝病。但與葉子杰同名的班長葉梓潔（江齊 飾），卻彷彿裝了測謊雷達，不放過任何一個子杰疑似裝病的證據。她到保健室查勤並沒收垃圾食物，甚至化身外送員只為確認他是否真的有病！「裝病仔」與「有病姊」，兩人在諜對諜的互動中，也開始產生了不一樣的情愫。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-23 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2726b32419285b739e', '4月高雄市電影館｜夏之庭 4K數位修復版 The Friends【普遍級】', '相米慎二創作生涯後期代表作 融合戰後省思的暖心成長故事\r\n★  1995 橫濱電影節 最佳劇本獎\r\n★  1995 電影旬報 最佳劇本獎\r\n\r\n盛夏午後的神戶港邊，小學生山下與死黨河邊、木山因參加喪禮，對「死亡」產生好奇。三人闖入一戶老屋，暗中觀察獨居老人，想見證他離世的瞬間。老人起初反感，卻逐漸習慣孩子們的陪伴。隨著庭院波斯菊盛開，老人打開心扉，講述埋藏多年不堪回首的遺憾往事⋯⋯。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-05 00:00:00', '2025-04-23 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜夏之庭 4K數位修復版 The Friends【普遍級】', `description`='相米慎二創作生涯後期代表作 融合戰後省思的暖心成長故事\r\n★  1995 橫濱電影節 最佳劇本獎\r\n★  1995 電影旬報 最佳劇本獎\r\n\r\n盛夏午後的神戶港邊，小學生山下與死黨河邊、木山因參加喪禮，對「死亡」產生好奇。三人闖入一戶老屋，暗中觀察獨居老人，想見證他離世的瞬間。老人起初反感，卻逐漸習慣孩子們的陪伴。隨著庭院波斯菊盛開，老人打開心扉，講述埋藏多年不堪回首的遺憾往事⋯⋯。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-23 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2726b32419285b73a1', '4月高雄市電影館｜衝出迷境 Away【普遍級】', '《喵的奇幻漂流》導演金茲斯巴洛迪斯 一鳴驚人動畫電影\r\n\r\n少年揹著降落傘在陌生異地醒來，黑色靈魂試圖吞蝕他，他只能憑一台摩托車、一只背包，及一隻小澄鳥的陪伴克服恐懼展開冒險。《喵的奇幻漂流》導演金茲斯巴洛迪斯耗時3年半的首部動畫長片，一人獨立完成編劇、動畫製作、電影配樂及後製工程，電影中反映了導演的心路歷程，還有突破人生困境的勇氣與反思。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-12 00:00:00', '2025-04-27 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜衝出迷境 Away【普遍級】', `description`='《喵的奇幻漂流》導演金茲斯巴洛迪斯 一鳴驚人動畫電影\r\n\r\n少年揹著降落傘在陌生異地醒來，黑色靈魂試圖吞蝕他，他只能憑一台摩托車、一只背包，及一隻小澄鳥的陪伴克服恐懼展開冒險。《喵的奇幻漂流》導演金茲斯巴洛迪斯耗時3年半的首部動畫長片，一人獨立完成編劇、動畫製作、電影配樂及後製工程，電影中反映了導演的心路歷程，還有突破人生困境的勇氣與反思。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2726b32419285b73a2', '4月高雄市電影館｜器子 Organ Child【輔15級】', '最殘暴的復仇 來自最痛苦的失去\r\n\r\n張其茂的女兒在三個月大時失蹤，疑似成為販嬰集團的下手目標，妻子過度自責而自戕，他追查真相反被誣陷入獄。出獄後，張其茂查出女兒落入活摘器官集團，成為被取走心臟的「器子」，悲憤難當的他對犯罪集團展開以暴制暴的復仇行動，卻發現女兒可能尚存人世，面對龐大的犯罪集團，他全力營救作為「器子」的女兒，奮力擺脫被宰制的命運。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-11 00:00:00', '2025-04-26 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;全票+260', 'https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜器子 Organ Child【輔15級】', `description`='最殘暴的復仇 來自最痛苦的失去\r\n\r\n張其茂的女兒在三個月大時失蹤，疑似成為販嬰集團的下手目標，妻子過度自責而自戕，他追查真相反被誣陷入獄。出獄後，張其茂查出女兒落入活摘器官集團，成為被取走心臟的「器子」，悲憤難當的他對犯罪集團展開以暴制暴的復仇行動，卻發現女兒可能尚存人世，面對龐大的犯罪集團，他全力營救作為「器子」的女兒，奮力擺脫被宰制的命運。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2726b32419285b73a3', '4月高雄市電影館｜犯罪直播 Showtime 7【保護級】', '改編自韓國賣座電影 阿部寬陷入困境無路可逃！\r\n\r\n折本眞之輔原是全國新聞節目的人氣主播，卻因故被降級為電台主持。某晚他接到一通「預告犯罪」的叩應電話，原以為是惡作劇，沒想到遠處立刻傳來爆炸巨響。再度來電的犯人指定折本進行現場連線。然而，攝影棚裡早已被安裝炸彈，稍不順從就會引爆。隨著恐怖分子的要求升級，折本與犯人對峙的場面也被全國轉播。幕後黑手究竟是誰？當真相逐漸明朗，折本選擇了令人意想不到的結局。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-18 00:00:00', '2025-04-29 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜犯罪直播 Showtime 7【保護級】', `description`='改編自韓國賣座電影 阿部寬陷入困境無路可逃！\r\n\r\n折本眞之輔原是全國新聞節目的人氣主播，卻因故被降級為電台主持。某晚他接到一通「預告犯罪」的叩應電話，原以為是惡作劇，沒想到遠處立刻傳來爆炸巨響。再度來電的犯人指定折本進行現場連線。然而，攝影棚裡早已被安裝炸彈，稍不順從就會引爆。隨著恐怖分子的要求升級，折本與犯人對峙的場面也被全國轉播。幕後黑手究竟是誰？當真相逐漸明朗，折本選擇了令人意想不到的結局。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-18 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2726b32419285b73a4', '4月高雄市電影館｜帶針的女孩 The Girl With the Needle【輔15級】', '改編自丹麥真實事件 天使殺手連環殺嬰案\r\n★ 2004 坎城影展 主競賽\r\n\r\n1919年第一次世界大戰剛結束，哥本哈根小鎮上一間紡織廠裡，有個小生命也即將來到世間。達格瑪經營一家糖果店，也是鄉間流傳幫忙領養孩子的善心婦人，他說來領養的家庭多半是商人、律師、醫生等的中產家庭，相信孩子們能在戰亂世代安好生活。不過當孩子一個個被送進亮麗甜美的糖果屋，他們卻再也沒有了聲音，只剩達格瑪揚起宛如天使般的詭異笑容，等待下個嬰孩到來。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-20 00:00:00', '2025-04-30 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜帶針的女孩 The Girl With the Needle【輔15級】', `description`='改編自丹麥真實事件 天使殺手連環殺嬰案\r\n★ 2004 坎城影展 主競賽\r\n\r\n1919年第一次世界大戰剛結束，哥本哈根小鎮上一間紡織廠裡，有個小生命也即將來到世間。達格瑪經營一家糖果店，也是鄉間流傳幫忙領養孩子的善心婦人，他說來領養的家庭多半是商人、律師、醫生等的中產家庭，相信孩子們能在戰亂世代安好生活。不過當孩子一個個被送進亮麗甜美的糖果屋，他們卻再也沒有了聲音，只剩達格瑪揚起宛如天使般的詭異笑容，等待下個嬰孩到來。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2726b32419285b73a5', '4月高雄市電影館｜看我今天怎麼說 The Way We Talk【普遍級】', '聾人青年生機蓬勃的青春故事 拍出手語動人生命力\r\n★ 2024 金馬獎 最佳女主角獎\r\n\r\n子信來自聾人家庭，雖然生活滿是障礙，卻用手語活出自信；素恩小時候植入了「人工耳蝸」，艱辛學習及採用口語，努力地去做個「正常人」；Alan也用人工耳蝸，口語能力跟素恩相若，也懂得手語，是子信的莫逆之交。他認為聾人應盡力與不同人溝通，開拓世界。友情把三人連上，彼此生命經驗的不同，撞得他們遍體鱗傷，卻也引領著大家去探索自我。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-30 00:00:00', '2025-04-30 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜看我今天怎麼說 The Way We Talk【普遍級】', `description`='聾人青年生機蓬勃的青春故事 拍出手語動人生命力\r\n★ 2024 金馬獎 最佳女主角獎\r\n\r\n子信來自聾人家庭，雖然生活滿是障礙，卻用手語活出自信；素恩小時候植入了「人工耳蝸」，艱辛學習及採用口語，努力地去做個「正常人」；Alan也用人工耳蝸，口語能力跟素恩相若，也懂得手語，是子信的莫逆之交。他認為聾人應盡力與不同人溝通，開拓世界。友情把三人連上，彼此生命經驗的不同，撞得他們遍體鱗傷，卻也引領著大家去探索自我。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-30 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/77a617dfde5c1dbeb12242fb3f684c19?filter=eyJwYWdlcyI6Mn0=', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2726b32419285b73a6', '4月高雄市電影館｜巴黎，德州（4K數位修復版） Paris, Texas【普遍級】', '影史最美公路電影之一 40週年4K數位修復\r\n★ 1984 坎城影展 金棕櫚獎\r\n★ 2024 坎城影展 經典單元\r\n\r\n神秘男子崔維斯迷失在荒無人煙的沙漠中，因為身體虛弱而昏迷。醫院聯繫了他的弟弟沃特來接他。出院的崔維斯一路沉默不語，回到洛杉磯弟弟家，和許久未見的獨子亨特重逢，他試著想找回遺失的親情溫暖、斷了聯繫的美麗妻子，然而一切是否能重新開始？', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-01 00:00:00', '2025-04-23 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;可享兒童優惠票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list/43b7f1a23c9f5dd0383b3fafd7bd4cd3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜巴黎，德州（4K數位修復版） Paris, Texas【普遍級】', `description`='影史最美公路電影之一 40週年4K數位修復\r\n★ 1984 坎城影展 金棕櫚獎\r\n★ 2024 坎城影展 經典單元\r\n\r\n神秘男子崔維斯迷失在荒無人煙的沙漠中，因為身體虛弱而昏迷。醫院聯繫了他的弟弟沃特來接他。出院的崔維斯一路沉默不語，回到洛杉磯弟弟家，和許久未見的獨子亨特重逢，他試著想找回遺失的親情溫暖、斷了聯繫的美麗妻子，然而一切是否能重新開始？', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-23 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;可享兒童優惠票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/43b7f1a23c9f5dd0383b3fafd7bd4cd3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2826b32419285b73a7', '4月高雄市電影館｜慾望之翼（4K數位修復版） Wings of Desire【保護級】', '溫德斯最膾炙人口之作 一部關於孤獨、困境、愛和希望的電影\r\n★ 1987 坎城影展 最佳導演獎\r\n\r\n冷戰結束前的柏林，天使總是靜靜地觀察人們，聆聽人們的心聲。然而天使達米爾終於厭倦了旁觀，希望能夠感受那份存在的重量，他迷戀上一名謎樣的女子，決定離開羽翼的世界，投入有血有肉的慾望人間，展開他的生命旅程。溫德斯以純淨的影像呈現天使觀看的世界，以緩慢停滯的鏡頭審視一個個寂寥的靈魂。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-05 00:00:00', '2025-04-30 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list/43b7f1a23c9f5dd0383b3fafd7bd4cd3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜慾望之翼（4K數位修復版） Wings of Desire【保護級】', `description`='溫德斯最膾炙人口之作 一部關於孤獨、困境、愛和希望的電影\r\n★ 1987 坎城影展 最佳導演獎\r\n\r\n冷戰結束前的柏林，天使總是靜靜地觀察人們，聆聽人們的心聲。然而天使達米爾終於厭倦了旁觀，希望能夠感受那份存在的重量，他迷戀上一名謎樣的女子，決定離開羽翼的世界，投入有血有肉的慾望人間，展開他的生命旅程。溫德斯以純淨的影像呈現天使觀看的世界，以緩慢停滯的鏡頭審視一個個寂寥的靈魂。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/43b7f1a23c9f5dd0383b3fafd7bd4cd3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2826b32419285b73a8', '4月高雄市電影館｜里斯本的故事（4K數位修復版） Lisbon Story【普遍級】', '獻給電影大師費里尼與電影百年的一封情書\r\n\r\n一張寫著求救字眼的風景明信片，讓電影錄音師菲利普風塵僕僕趕往葡萄牙里斯本，途中他的車壞了，最後千辛萬苦抵達時卻只找到了沒有完成音效的電影膠卷，他的導演朋友菲德利希消失了。 於是菲利普留在里斯本，發掘被人們忽略的城市聲音，並結識了一群樂團好友，他甚至迷戀上歌聲如黃鶯出谷的女歌手泰瑞莎。', '高雄市電影館', '高雄市鼓山區馬卡道路329號', '2025-04-03 00:00:00', '2025-04-30 00:00:00', '內惟藝術中心', 22.65019525, 120.274163, '電影館之友優待票+200;兒童優待票+208;全票+260', 'https://www.nwac.org.tw/tw/movies-list/43b7f1a23c9f5dd0383b3fafd7bd4cd3', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜里斯本的故事（4K數位修復版） Lisbon Story【普遍級】', `description`='獻給電影大師費里尼與電影百年的一封情書\r\n\r\n一張寫著求救字眼的風景明信片，讓電影錄音師菲利普風塵僕僕趕往葡萄牙里斯本，途中他的車壞了，最後千辛萬苦抵達時卻只找到了沒有完成音效的電影膠卷，他的導演朋友菲德利希消失了。 於是菲利普留在里斯本，發掘被人們忽略的城市聲音，並結識了一群樂團好友，他甚至迷戀上歌聲如黃鶯出谷的女歌手泰瑞莎。', `organizer`='高雄市電影館', `address`='高雄市鼓山區馬卡道路329號', `start_date`='2025-04-03 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='內惟藝術中心', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='電影館之友優待票+200;兒童優待票+208;全票+260', `source_url`='https://www.nwac.org.tw/tw/movies-list/43b7f1a23c9f5dd0383b3fafd7bd4cd3', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2a26b32419285b73ac', '【夢的輪廓】連芯妤 個展', '我的作品是對夢與記憶長期以來的紀錄，經過時間的渲染，現實和夢境的界線逐漸模糊，成了朦朧破碎的幻想；而清醒，或許只是另一場夢。光影與塵埃交錯間，夢的記憶與現實的片段相互交織，如夢幻泡影，看得見，卻無法觸及。\r\n\r\n我試圖捕捉這些稍縱即逝的感受，在探尋夢境與記憶的旅途中，與星月共舞，釋放自由。現實亦如夢境，而夢境則宛如另一種人生，並行於時間之中，層層疊疊地交錯存在。\r\n\r\n在作品中，我以破碎的圖像符號與流動的線條，重現那些轉瞬即逝的想法與已然消逝的時刻。透過漫長且不斷交織、重構與並置的創作過程，我反覆審視那些過去曾經鮮明的記憶，如今會將以何種面貌存在？\r\n', '二空間藝術經紀股份有限公司', '臺北市中山區', '2025-04-12 00:00:00', '2025-05-03 00:00:00', '中山區（臺北市）=', 25.06969917, 121.5381597, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【夢的輪廓】連芯妤 個展', `description`='我的作品是對夢與記憶長期以來的紀錄，經過時間的渲染，現實和夢境的界線逐漸模糊，成了朦朧破碎的幻想；而清醒，或許只是另一場夢。光影與塵埃交錯間，夢的記憶與現實的片段相互交織，如夢幻泡影，看得見，卻無法觸及。\r\n\r\n我試圖捕捉這些稍縱即逝的感受，在探尋夢境與記憶的旅途中，與星月共舞，釋放自由。現實亦如夢境，而夢境則宛如另一種人生，並行於時間之中，層層疊疊地交錯存在。\r\n\r\n在作品中，我以破碎的圖像符號與流動的線條，重現那些轉瞬即逝的想法與已然消逝的時刻。透過漫長且不斷交織、重構與並置的創作過程，我反覆審視那些過去曾經鮮明的記憶，如今會將以何種面貌存在？\r\n', `organizer`='二空間藝術經紀股份有限公司', `address`='臺北市中山區', `start_date`='2025-04-12 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='中山區（臺北市）=', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2b26b32419285b73ad', '藝術代理私洽展【大千藻井】【溥儒觀音】【君翁山水】', '藝術不僅是審美的體驗，更應與市場結合，讓優秀的作品能夠被更多人欣賞、收藏與傳承，市場的發展能促進書畫藝術的長遠傳承，讓創作者獲得應有的支持，並確保文化精髓得以延續，我們鼓勵藝術市場的健康發展，並透過專業品鑑與研究，提升市場對藝術價值的認知。\r\n長流美術館期待與各界交流，歡迎專家、學者及藝術愛好者提供指導與寶貴意見，共同推動書畫藝術的發展與審美提升。', '長流美術館股份有限公司', '臺北市中正區', '2025-03-27 00:00:00', '2025-04-27 00:00:00', '中正區（臺北市）=', 25.03240487, 121.5198839, '無資料', 'https://www.chanliu.com/2025/03/20/%e8%97%9d%e8%a1%93%e4%bb%a3%e7%90%86%e7%a7%81%e6%b4%bd%e5%b1%95-%', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝術代理私洽展【大千藻井】【溥儒觀音】【君翁山水】', `description`='藝術不僅是審美的體驗，更應與市場結合，讓優秀的作品能夠被更多人欣賞、收藏與傳承，市場的發展能促進書畫藝術的長遠傳承，讓創作者獲得應有的支持，並確保文化精髓得以延續，我們鼓勵藝術市場的健康發展，並透過專業品鑑與研究，提升市場對藝術價值的認知。\r\n長流美術館期待與各界交流，歡迎專家、學者及藝術愛好者提供指導與寶貴意見，共同推動書畫藝術的發展與審美提升。', `organizer`='長流美術館股份有限公司', `address`='臺北市中正區', `start_date`='2025-03-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='中正區（臺北市）=', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://www.chanliu.com/2025/03/20/%e8%97%9d%e8%a1%93%e4%bb%a3%e7%90%86%e7%a7%81%e6%b4%bd%e5%b1%95-%', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2d26b32419285b73b0', 'FUN心聽故事(中庄分館5月份)', '孩子是精靈，故事是魔法棒，點綴孩子的心，開啟孩子的夢，透過故事達人的口，故事將變成幸福的種子，灑向每個角落，讓小朋友的世界變成一座開滿五彩繽紛幸福花朵的書香城市。', '高雄市立圖書館總館', '高雄市大寮區40鄰光明路3段1437號', '2025-05-03 00:00:00', '2025-05-17 00:00:00', '高雄市立圖書館中庄分館', 22.6285347, 120.4098142, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽故事(中庄分館5月份)', `description`='孩子是精靈，故事是魔法棒，點綴孩子的心，開啟孩子的夢，透過故事達人的口，故事將變成幸福的種子，灑向每個角落，讓小朋友的世界變成一座開滿五彩繽紛幸福花朵的書香城市。', `organizer`='高雄市立圖書館總館', `address`='高雄市大寮區40鄰光明路3段1437號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='高雄市立圖書館中庄分館', `latitude`=22.6285347, `longitude`=120.4098142, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2d26b32419285b73b1', '節慶藝起來創意工作坊', '端午節親子手作體驗-唱台語童謠、猜台語謎語、做香包\r\n1.介紹端午節的由來與習俗\r\n2.教唱台語童謠，讓孩子透過音樂感受傳統節慶氛圍\r\n3.台語謎語小挑戰 ，透過台語謎語遊戲，加深孩子對端午文化的理解\r\n4.端午香包DIY親子互動：手作香包增加親子共創回憶\r\n活動特色\r\n1.台語文化學習：透過童謠與謎語，讓孩子自然學習台語\r\n2.親子互動：手作香包增加親子共創回憶\r\n3.寓教於樂：認識端午習俗，體驗傳統節慶樂趣"', '高雄市立圖書館總館', '高雄市大寮區40鄰光明路3段1437號', '2025-05-24 00:00:00', '2025-05-24 00:00:00', '高雄市立圖書館中庄分館', 22.6285347, 120.4098142, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='節慶藝起來創意工作坊', `description`='端午節親子手作體驗-唱台語童謠、猜台語謎語、做香包\r\n1.介紹端午節的由來與習俗\r\n2.教唱台語童謠，讓孩子透過音樂感受傳統節慶氛圍\r\n3.台語謎語小挑戰 ，透過台語謎語遊戲，加深孩子對端午文化的理解\r\n4.端午香包DIY親子互動：手作香包增加親子共創回憶\r\n活動特色\r\n1.台語文化學習：透過童謠與謎語，讓孩子自然學習台語\r\n2.親子互動：手作香包增加親子共創回憶\r\n3.寓教於樂：認識端午習俗，體驗傳統節慶樂趣"', `organizer`='高雄市立圖書館總館', `address`='高雄市大寮區40鄰光明路3段1437號', `start_date`='2025-05-24 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='高雄市立圖書館中庄分館', `latitude`=22.6285347, `longitude`=120.4098142, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2d26b32419285b73b2', 'FUN心聽故事 (鳳山二館114年4月)', '藉由說故事經驗豐富的故事達人，帶領大小朋友遨遊書海，推廣親子閱讀的樂趣，歡迎大朋友小朋友踴躍參加， 共度歡樂的週末時光!!\r\n報名方式：自由入場。\r\n活動日期:4/5、4/12、4/19、4/26，週六下午14:30~15:30。', '高雄市立圖書館總館', '高雄市鳳山區7鄰自強一路119巷75號', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '高雄市立圖書館鳳山二館', 22.589421, 120.3273098, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽故事 (鳳山二館114年4月)', `description`='藉由說故事經驗豐富的故事達人，帶領大小朋友遨遊書海，推廣親子閱讀的樂趣，歡迎大朋友小朋友踴躍參加， 共度歡樂的週末時光!!\r\n報名方式：自由入場。\r\n活動日期:4/5、4/12、4/19、4/26，週六下午14:30~15:30。', `organizer`='高雄市立圖書館總館', `address`='高雄市鳳山區7鄰自強一路119巷75號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄市立圖書館鳳山二館', `latitude`=22.589421, `longitude`=120.3273098, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2e26b32419285b73b3', '路邊劇場', '好戲連台，路邊劇場，從不落幕。從這邊到那邊，即便是一剎那，多少的遇見和錯過，也隨著在可控與不可控之中，飛舞。\r\n\r\n張堂龲畫裡的花鳥蟲草，翩飛的蜻蜓，是大地真正的顏色與姿態。天野喜孝的天界，喚醒了介於現實和虛擬的有趣連結。黃銘昌的土地是一方陽光下的稻田，綿延的稻禾，在阡陌間追逐著風。蘇旺伸以狗的各種神態，隱喻社會族群的生態，俯視的、寓言式的敘述，突顯出另類的深度幽默。陳景亮的陶藝是種”視覺的魅惑”，似真實木頭的樹幹壺，實為陶土精煉的現代雕塑。\r\n\r\n展演者︰張堂龲；黃銘昌；陳景亮；蘇旺伸；耿晧剛；崔旴嵐/南韓；權奇秀/南韓；李慶美/南韓；天野喜孝/日本\r\n\r\n\r\n', '形而上畫廊', '臺北市大安區', '2025-04-01 00:00:00', '2025-05-31 00:00:00', '大安區（臺北市）=', 25.02677012, 121.5434446, '無資料', 'http://www.artmap.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='路邊劇場', `description`='好戲連台，路邊劇場，從不落幕。從這邊到那邊，即便是一剎那，多少的遇見和錯過，也隨著在可控與不可控之中，飛舞。\r\n\r\n張堂龲畫裡的花鳥蟲草，翩飛的蜻蜓，是大地真正的顏色與姿態。天野喜孝的天界，喚醒了介於現實和虛擬的有趣連結。黃銘昌的土地是一方陽光下的稻田，綿延的稻禾，在阡陌間追逐著風。蘇旺伸以狗的各種神態，隱喻社會族群的生態，俯視的、寓言式的敘述，突顯出另類的深度幽默。陳景亮的陶藝是種”視覺的魅惑”，似真實木頭的樹幹壺，實為陶土精煉的現代雕塑。\r\n\r\n展演者︰張堂龲；黃銘昌；陳景亮；蘇旺伸；耿晧剛；崔旴嵐/南韓；權奇秀/南韓；李慶美/南韓；天野喜孝/日本\r\n\r\n\r\n', `organizer`='形而上畫廊', `address`='臺北市大安區', `start_date`='2025-04-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='大安區（臺北市）=', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='無資料', `source_url`='http://www.artmap.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2e26b32419285b73b4', '小蜻蜓兒童讀書會', '本活動為有效運用圖書館既有資源，期分館能深入社區推動閱讀，提昇社區閱讀風氣，推動構想如下：\r\n✽透過同儕學習模式，讓兒童體會閱讀的樂趣。\r\n✽培養兒童對社區公共圖書館的瞭解與認識。\r\n1招生對象：以國小3-4年級為優先，不足額招收5-6年級。\r\n2.實施方式：由帶領老師指導透過閱讀、影片欣賞及分享討論等方式進行，每班招收20人。\r\n書目(核心主題)-\r\n04/12 (六) 豆腐(責任與傳承)(台語唸讀迴文詩)\r\n04/19 (六) 八歲一個人去旅行(勇氣)(各地名的台語唸法)\r\n04/26 (六) 五百羅漢交通平安(廟宇文化)\r\n05/03 (六) 雄獅堡最後的衛兵(超越物種的情誼)\r\n05/10 (六) 掉落凡間的流星(自助)\r\n05/24 (六) 比心願更重要的事(助人)', '高雄市立圖書館總館', '高雄市永安區005鄰永華路49號', '2025-04-12 00:00:00', '2025-05-24 00:00:00', '高雄市立圖書館永安分館', 22.8159848, 120.2244381, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='小蜻蜓兒童讀書會', `description`='本活動為有效運用圖書館既有資源，期分館能深入社區推動閱讀，提昇社區閱讀風氣，推動構想如下：\r\n✽透過同儕學習模式，讓兒童體會閱讀的樂趣。\r\n✽培養兒童對社區公共圖書館的瞭解與認識。\r\n1招生對象：以國小3-4年級為優先，不足額招收5-6年級。\r\n2.實施方式：由帶領老師指導透過閱讀、影片欣賞及分享討論等方式進行，每班招收20人。\r\n書目(核心主題)-\r\n04/12 (六) 豆腐(責任與傳承)(台語唸讀迴文詩)\r\n04/19 (六) 八歲一個人去旅行(勇氣)(各地名的台語唸法)\r\n04/26 (六) 五百羅漢交通平安(廟宇文化)\r\n05/03 (六) 雄獅堡最後的衛兵(超越物種的情誼)\r\n05/10 (六) 掉落凡間的流星(自助)\r\n05/24 (六) 比心願更重要的事(助人)', `organizer`='高雄市立圖書館總館', `address`='高雄市永安區005鄰永華路49號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='高雄市立圖書館永安分館', `latitude`=22.8159848, `longitude`=120.2244381, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2e26b32419285b73b5', '路竹分館114年5月主題書展', '1.童心繪夢閱讀奇遇:魔法交通工具奇蹟:在這個充滿魔法與奇蹟的世界裡，精心挑選與主題相關繪本~邀請讀者們，一起探索交通工具的神奇世界。透過繪本形式，將孩子帶入一個魔法旅程，他們的故事在感動中滲透，充滿冒險精神；在這裡，孩子們不僅能看到交通工具的奇妙變化，還能激發無限的想像力，體驗每一場充滿魔法與奇蹟的交通冒險。\r\n2.閱讀無界：幸福食光，記憶中的溫柔力量：食物不僅是身體的養分，它還蘊含著情感、回憶和文化的力量。每一口食物背後，都是一段故事、一種情感的傳遞。透過書展引領讀者回到那些溫馨的時光，探索食物與人之間的深厚聯繫，體驗食物如何在我們的生活中扮演著人與人連結情感與文化的橋樑。', '高雄市立圖書館總館', '高雄市路竹區24鄰國昌路86巷9號', '2025-05-01 00:00:00', '2025-05-31 00:00:00', '高雄市立圖書館路竹分館', 22.8541831, 120.2611866, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='路竹分館114年5月主題書展', `description`='1.童心繪夢閱讀奇遇:魔法交通工具奇蹟:在這個充滿魔法與奇蹟的世界裡，精心挑選與主題相關繪本~邀請讀者們，一起探索交通工具的神奇世界。透過繪本形式，將孩子帶入一個魔法旅程，他們的故事在感動中滲透，充滿冒險精神；在這裡，孩子們不僅能看到交通工具的奇妙變化，還能激發無限的想像力，體驗每一場充滿魔法與奇蹟的交通冒險。\r\n2.閱讀無界：幸福食光，記憶中的溫柔力量：食物不僅是身體的養分，它還蘊含著情感、回憶和文化的力量。每一口食物背後，都是一段故事、一種情感的傳遞。透過書展引領讀者回到那些溫馨的時光，探索食物與人之間的深厚聯繫，體驗食物如何在我們的生活中扮演著人與人連結情感與文化的橋樑。', `organizer`='高雄市立圖書館總館', `address`='高雄市路竹區24鄰國昌路86巷9號', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='高雄市立圖書館路竹分館', `latitude`=22.8541831, `longitude`=120.2611866, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2f26b32419285b73b6', '路竹分館114年5月FUN心聽故事', '由故事達人透過繪本故事說演，引導親子共讀繪本故事，進入故事情境，進而喜歡閱讀，並配合親子共讀，設計延伸活動。\r\n5/3 默默老師 /藝起話繪本\r\n5/10 許靜淑老師 /繪本童樂會\r\n5/17林春秀老師 /童繪島\r\n5/24潘慧君老師 /英文繪本故事', '高雄市立圖書館總館', '高雄市路竹區24鄰國昌路86巷9號', '2025-05-03 00:00:00', '2025-05-24 00:00:00', '高雄市立圖書館路竹分館', 22.8541831, 120.2611866, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='路竹分館114年5月FUN心聽故事', `description`='由故事達人透過繪本故事說演，引導親子共讀繪本故事，進入故事情境，進而喜歡閱讀，並配合親子共讀，設計延伸活動。\r\n5/3 默默老師 /藝起話繪本\r\n5/10 許靜淑老師 /繪本童樂會\r\n5/17林春秀老師 /童繪島\r\n5/24潘慧君老師 /英文繪本故事', `organizer`='高雄市立圖書館總館', `address`='高雄市路竹區24鄰國昌路86巷9號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='高雄市立圖書館路竹分館', `latitude`=22.8541831, `longitude`=120.2611866, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb2f26b32419285b73b7', '閱讀新潮流~成語中的植物-黃荊', '裊裊五月節-埔姜葉手捲蚊香體驗\r\n繪本導讀：趣味植物小百科（成語中的植物-黃荊，認識植物特性，理解成語形成的道理，進而掌握運用成語的技巧。）', '高雄市立圖書館總館', '高雄市路竹區24鄰國昌路86巷9號', '2025-05-24 00:00:00', '2025-05-24 00:00:00', '高雄市立圖書館路竹分館', 22.8541831, 120.2611866, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='閱讀新潮流~成語中的植物-黃荊', `description`='裊裊五月節-埔姜葉手捲蚊香體驗\r\n繪本導讀：趣味植物小百科（成語中的植物-黃荊，認識植物特性，理解成語形成的道理，進而掌握運用成語的技巧。）', `organizer`='高雄市立圖書館總館', `address`='高雄市路竹區24鄰國昌路86巷9號', `start_date`='2025-05-24 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='高雄市立圖書館路竹分館', `latitude`=22.8541831, `longitude`=120.2611866, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb3026b32419285b73b9', '高雄市立圖書館大樹二館114年4月主題繪本展〜未來之智︰AI與人類的對話', '隨著人工智慧(AI)的快速發展，這項技術正深刻地改變我們的生活、工作與思考方式。本次書展以「AI」為主題，匯聚AI書籍、技術應用和創意作品，帶領讀者走入智能時代，探索AI科技魅力與人文價值，供民眾翻閱。', '高雄市立圖書館總館', '高雄市大樹區25鄰久堂路97-1號', '2025-05-01 00:00:00', '2025-06-29 00:00:00', '高雄市立圖書館大樹二館', 22.6586226, 120.4192897, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市立圖書館大樹二館114年4月主題繪本展〜未來之智︰AI與人類的對話', `description`='隨著人工智慧(AI)的快速發展，這項技術正深刻地改變我們的生活、工作與思考方式。本次書展以「AI」為主題，匯聚AI書籍、技術應用和創意作品，帶領讀者走入智能時代，探索AI科技魅力與人文價值，供民眾翻閱。', `organizer`='高雄市立圖書館總館', `address`='高雄市大樹區25鄰久堂路97-1號', `start_date`='2025-05-01 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='高雄市立圖書館大樹二館', `latitude`=22.6586226, `longitude`=120.4192897, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
