INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb3226b32419285b73c3', '114年客語薪傳師傳習開班-仁義客語歌謠班', '客語薪傳師傳習開班，對外開放且自由參與。\r\n透過客語歌謠的傳唱，推廣客語歌謠文化，讓不同族群之鄉親共同學習與分享。', '桃園市政府客家事務局', '桃園市大溪區', '2025-03-03 00:00:00', '2025-06-30 00:00:00', '大溪區（桃園市）=', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年客語薪傳師傳習開班-仁義客語歌謠班', `description`='客語薪傳師傳習開班，對外開放且自由參與。\r\n透過客語歌謠的傳唱，推廣客語歌謠文化，讓不同族群之鄉親共同學習與分享。', `organizer`='桃園市政府客家事務局', `address`='桃園市大溪區', `start_date`='2025-03-03 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='大溪區（桃園市）=', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb3226b32419285b73c4', '許文融美術館落成特展', '許文融，1963年出生於彰化大城鄉頂庄村，大專時期開始在藝術界嶄露頭角，在服役期間仍繼續創作，獲得金獅獎、國軍文藝金像獎及全省美展首獎，退伍後赴美深造2年，學成返國進入專校擔任講師，並逐步升任副教授及教授，期間還獲得吳三連文藝創作獎、十大傑出青年文化藝術類金手獎及全球中華文化藝術薪傳獎等，現任建國科技大學教授兼美術館館長、國立臺灣藝術大學教授、北京大學、華中科技大學客座教授等職。\r\n許文融曾在兩岸三地共開過30多次個展，1996年完成花費4年時間創作長320公尺、高1.8公尺的《臺灣風物圖卷》，曾是世界紀錄最長的當代水墨畫，也是他的代表作之一，他也擅長油畫、水彩、雕塑、書法等，作品在許文融美術館中都能見到。', '許文融美術館', '苗栗縣三義鄉', '2025-03-15 00:00:00', '2025-06-30 00:00:00', '三義鄉（苗栗縣）=', 24.38081659, 120.7701929, '無資料', 'https://www.miaoli.gov.tw/News_Content2.aspx?n=285&sms=9462&s=841026', '[]') ON DUPLICATE KEY UPDATE `activity_name`='許文融美術館落成特展', `description`='許文融，1963年出生於彰化大城鄉頂庄村，大專時期開始在藝術界嶄露頭角，在服役期間仍繼續創作，獲得金獅獎、國軍文藝金像獎及全省美展首獎，退伍後赴美深造2年，學成返國進入專校擔任講師，並逐步升任副教授及教授，期間還獲得吳三連文藝創作獎、十大傑出青年文化藝術類金手獎及全球中華文化藝術薪傳獎等，現任建國科技大學教授兼美術館館長、國立臺灣藝術大學教授、北京大學、華中科技大學客座教授等職。\r\n許文融曾在兩岸三地共開過30多次個展，1996年完成花費4年時間創作長320公尺、高1.8公尺的《臺灣風物圖卷》，曾是世界紀錄最長的當代水墨畫，也是他的代表作之一，他也擅長油畫、水彩、雕塑、書法等，作品在許文融美術館中都能見到。', `organizer`='許文融美術館', `address`='苗栗縣三義鄉', `start_date`='2025-03-15 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='三義鄉（苗栗縣）=', `latitude`=24.38081659, `longitude`=120.7701929, `ticket_price`='無資料', `source_url`='https://www.miaoli.gov.tw/News_Content2.aspx?n=285&sms=9462&s=841026', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e5cb3226b32419285b73c5', '志工說故事活動（114年4月-13場）', '清明時節雨紛紛，草木萌芽趨茂盛，大地回春景色媚﹐清明節除了掃墓祭祖之外，包「潤餅」也是習俗之一﹐而客家人稱掃墓為「掛紙」。你是否想了解掛紙的意義及其習俗？今年4月，苗栗縣立圖書館將帶來一系列以「清明祭祖聽傳奇 春日兒童閱讀樂」為主題的精彩志工說故事活動，邀請大家一同走進故事的世界，探索清明的奧妙與傳統。\r\n這次活動將從4月起推出，共計13場故事，涵蓋《清明時節外星人》、《清明節的故事》、《阿嗚國王的兒童節》、《爺爺的玩具王國》以及《機車阿姆》等精彩內容。故事將帶領大小朋友了解掛紙的習俗，感受清明節與潤餅之間的密切關聯。\r\n本次活動特別適合0至5歲嬰幼兒、幼兒園及國小低中年級的學童家庭參與。活動時間為每週三下午3:00至4:00，及每週六與週日上午10:00至11:00。歡迎家長陪同孩子一同來到圖書館，免費入場，享受與孩子共享故事的快樂時光。', '苗栗縣立圖書館', '苗栗縣苗栗市自治路50號', '2025-04-02 00:00:00', '2025-04-30 00:00:00', '苗栗縣立圖書館', 24.565963, 120.8203986, '無資料', 'https://www.miaoli.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='志工說故事活動（114年4月-13場）', `description`='清明時節雨紛紛，草木萌芽趨茂盛，大地回春景色媚﹐清明節除了掃墓祭祖之外，包「潤餅」也是習俗之一﹐而客家人稱掃墓為「掛紙」。你是否想了解掛紙的意義及其習俗？今年4月，苗栗縣立圖書館將帶來一系列以「清明祭祖聽傳奇 春日兒童閱讀樂」為主題的精彩志工說故事活動，邀請大家一同走進故事的世界，探索清明的奧妙與傳統。\r\n這次活動將從4月起推出，共計13場故事，涵蓋《清明時節外星人》、《清明節的故事》、《阿嗚國王的兒童節》、《爺爺的玩具王國》以及《機車阿姆》等精彩內容。故事將帶領大小朋友了解掛紙的習俗，感受清明節與潤餅之間的密切關聯。\r\n本次活動特別適合0至5歲嬰幼兒、幼兒園及國小低中年級的學童家庭參與。活動時間為每週三下午3:00至4:00，及每週六與週日上午10:00至11:00。歡迎家長陪同孩子一同來到圖書館，免費入場，享受與孩子共享故事的快樂時光。', `organizer`='苗栗縣立圖書館', `address`='苗栗縣苗栗市自治路50號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='苗栗縣立圖書館', `latitude`=24.565963, `longitude`=120.8203986, `ticket_price`='無資料', `source_url`='https://www.miaoli.gov.tw/', `image_url`='[]';
