INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e7208b26b32419285b740b', '2025桐花祭-造橋鄉口山步道漫步走讀（2梯次）', '活動地點：造橋鄉造橋村口山步道，及百年造橋驛站周邊景點。\r\n活動簡介：\r\n1.由專業導覽解說員帶領您走踏口山步道，沿途進行生態解說，講解百年造橋驛站周邊景點，及造橋鄉在地歷史與文化。\r\n2.中餐享用社區媽媽烹調的傳統客家美食「四炆四炒」。\r\n3.由童玩達人教導你手作竹製童玩「蕃薯鼓」。\r\n4.觀賞2025桐花祭活動會場各式表演活動與體驗活動，採購小農的農產品、客家特色美食點心。\r\n活動行程：造橋鄉公所旁廣場 (桐花祭活動會場)集合→口山步道→南港溪開基伯公→綠池鳳凰花步道→造橋車站北側公園→百年造橋車站→造橋驛→造橋鄉農會農會小舖→造橋社區活動中心(用餐、竹製童玩 DIY)→快樂賦歸→自由參加桐花祭活動會場活動\r\n\r\n分兩梯次辦理(每梯次30人)\r\n報名時間：4月8日(二)上午09:00起，開放線上報名。\r\n線上報名：\r\n第一梯次 https://forms.gle/g9cTAZM78zZNYzVA6\r\n第二梯次 https://forms.gle/iBzGovfKyCXHSkqd9', '苗栗縣造橋鄉公所', '苗栗縣造橋鄉', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '造橋鄉（苗栗縣）=', 24.62481314, 120.8695663, '報名費+300', 'https://www.facebook.com/zaoqiao540040', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025桐花祭-造橋鄉口山步道漫步走讀（2梯次）', `description`='活動地點：造橋鄉造橋村口山步道，及百年造橋驛站周邊景點。\r\n活動簡介：\r\n1.由專業導覽解說員帶領您走踏口山步道，沿途進行生態解說，講解百年造橋驛站周邊景點，及造橋鄉在地歷史與文化。\r\n2.中餐享用社區媽媽烹調的傳統客家美食「四炆四炒」。\r\n3.由童玩達人教導你手作竹製童玩「蕃薯鼓」。\r\n4.觀賞2025桐花祭活動會場各式表演活動與體驗活動，採購小農的農產品、客家特色美食點心。\r\n活動行程：造橋鄉公所旁廣場 (桐花祭活動會場)集合→口山步道→南港溪開基伯公→綠池鳳凰花步道→造橋車站北側公園→百年造橋車站→造橋驛→造橋鄉農會農會小舖→造橋社區活動中心(用餐、竹製童玩 DIY)→快樂賦歸→自由參加桐花祭活動會場活動\r\n\r\n分兩梯次辦理(每梯次30人)\r\n報名時間：4月8日(二)上午09:00起，開放線上報名。\r\n線上報名：\r\n第一梯次 https://forms.gle/g9cTAZM78zZNYzVA6\r\n第二梯次 https://forms.gle/iBzGovfKyCXHSkqd9', `organizer`='苗栗縣造橋鄉公所', `address`='苗栗縣造橋鄉', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='造橋鄉（苗栗縣）=', `latitude`=24.62481314, `longitude`=120.8695663, `ticket_price`='報名費+300', `source_url`='https://www.facebook.com/zaoqiao540040', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e7208b26b32419285b740c', '114年小蜻蜓兒童讀書會', '為了鼓勵閱讀\r\n此讀書會將會採用紙本書與電子書的共讀\r\n*雲端書庫、電子書雙平台使用介紹\r\n*備有平板電腦供學員操作學習\r\n運用電子書和繪本書籍來進行導讀\r\n透過每個禮拜不同的主題書籍，\r\n讓孩子用自己的觀點來討論，\r\n勇於表達自己的看法，結合電子書也讓孩子學習到\r\n知識不是僅限於書本，數位閱讀讓自己更有競爭力\r\n3/22書目:朱瑞福的游泳課\r\n3/29書目:來畫一棵神奇的樹\r\n4/12書目:我的朋友蹛佇隔壁庄\r\n4/19書目:果子牛Ioh謎猜\r\n4/26書目:聽說月亮有一個書房\r\n5/3 書目:佮阿公踅菜市仔\r\n5/10書目:打氣粥\r\n5/17書目:月光光踅夜市:咱的囝仔歌', '高雄市立圖書館總館', '高雄市鹽埕區1鄰大仁路179號5樓、6樓', '2025-03-22 00:00:00', '2025-05-17 00:00:00', '高雄市立圖書館鹽埕分館', 22.626715, 120.281874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年小蜻蜓兒童讀書會', `description`='為了鼓勵閱讀\r\n此讀書會將會採用紙本書與電子書的共讀\r\n*雲端書庫、電子書雙平台使用介紹\r\n*備有平板電腦供學員操作學習\r\n運用電子書和繪本書籍來進行導讀\r\n透過每個禮拜不同的主題書籍，\r\n讓孩子用自己的觀點來討論，\r\n勇於表達自己的看法，結合電子書也讓孩子學習到\r\n知識不是僅限於書本，數位閱讀讓自己更有競爭力\r\n3/22書目:朱瑞福的游泳課\r\n3/29書目:來畫一棵神奇的樹\r\n4/12書目:我的朋友蹛佇隔壁庄\r\n4/19書目:果子牛Ioh謎猜\r\n4/26書目:聽說月亮有一個書房\r\n5/3 書目:佮阿公踅菜市仔\r\n5/10書目:打氣粥\r\n5/17書目:月光光踅夜市:咱的囝仔歌', `organizer`='高雄市立圖書館總館', `address`='高雄市鹽埕區1鄰大仁路179號5樓、6樓', `start_date`='2025-03-22 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='高雄市立圖書館鹽埕分館', `latitude`=22.626715, `longitude`=120.281874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e795ab07f3d4433af95562', '路邊劇場', '好戲連台，路邊劇場，從這邊到那邊，從不落幕。即便是一剎那， \r\n張堂龲畫裡的花鳥蟲草，翩飛的蜻蜓，是大地真正的顏色與姿態。天野喜孝的天界，喚醒了介於現實和虛擬的有趣連結。黃銘昌的土地是一方陽光下的稻田，綿延的稻禾，在阡陌間追逐著風。蘇旺伸以狗的各種神態，隱喻社會族群的生態，俯視的、寓言式的敘述，突顯出另類的深度幽默。陳景亮的陶藝是種”視覺的魅惑”，似真實木頭的樹幹壺，實為陶土精煉的現代雕塑。\r\n\r\n\r\n展名：路邊劇場\r\n展期：2025.04.01 ~ 05.31\r\n藝術家：張堂龲、黃銘昌、陳景亮、蘇旺伸、耿晧剛、崔旴嵐、權奇秀、李慶美、天野喜孝 \r\n地點：形而上畫廊\r\n台北市敦化南路一段219號7樓\r\n開放時間：11:00~18:30，周一休\r\n連絡電話：02-27713236\r\n\r\n', '形而上畫廊', '臺北市大安區敦化南路一段219號7樓', '2025-04-01 00:00:00', '2025-05-31 00:00:00', '形而上畫廊', 25.02677012, 121.5434446, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='路邊劇場', `description`='好戲連台，路邊劇場，從這邊到那邊，從不落幕。即便是一剎那， \r\n張堂龲畫裡的花鳥蟲草，翩飛的蜻蜓，是大地真正的顏色與姿態。天野喜孝的天界，喚醒了介於現實和虛擬的有趣連結。黃銘昌的土地是一方陽光下的稻田，綿延的稻禾，在阡陌間追逐著風。蘇旺伸以狗的各種神態，隱喻社會族群的生態，俯視的、寓言式的敘述，突顯出另類的深度幽默。陳景亮的陶藝是種”視覺的魅惑”，似真實木頭的樹幹壺，實為陶土精煉的現代雕塑。\r\n\r\n\r\n展名：路邊劇場\r\n展期：2025.04.01 ~ 05.31\r\n藝術家：張堂龲、黃銘昌、陳景亮、蘇旺伸、耿晧剛、崔旴嵐、權奇秀、李慶美、天野喜孝 \r\n地點：形而上畫廊\r\n台北市敦化南路一段219號7樓\r\n開放時間：11:00~18:30，周一休\r\n連絡電話：02-27713236\r\n\r\n', `organizer`='形而上畫廊', `address`='臺北市大安區敦化南路一段219號7樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='形而上畫廊', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e84e3726b32419285b7411', '「究・南物」歷史文物小展覽（中西區場）', '今年由臺南市政府文化局臺南市文化資產管處出版的《南都物語：物件裡的臺南史》，推出歷史文物小展覽。\r\n\r\n《南都物語：物件裡的臺南史》書本中的不同時間軸介紹不同時代的文物，每件文物上都記錄著臺南甚至臺灣曾經發生過的事件，以及在此生活的人們所留下的痕跡。\r\n\r\n「究・南物」則在這些既熟悉又陌生的歷史紀錄當中，為大家整理了重點年代並介紹該時代的特殊文物，同時整理出分別被典藏在什麼地方，設計了一些有趣的體驗，從3/7~5/11，分別在白雪珈琲店及臺南市立博物館開展。\r\n除了看展覽認識文物與歷史，也希望能透過這個機會認識展覽地區周邊特色景點或者書上文物的本尊。', '臺南市文化資產管理處', '臺南市中西區開山路152號', '2025-04-10 00:00:00', '2025-05-11 00:00:00', '臺南市立博物館(原鄭成功文物館)', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「究・南物」歷史文物小展覽（中西區場）', `description`='今年由臺南市政府文化局臺南市文化資產管處出版的《南都物語：物件裡的臺南史》，推出歷史文物小展覽。\r\n\r\n《南都物語：物件裡的臺南史》書本中的不同時間軸介紹不同時代的文物，每件文物上都記錄著臺南甚至臺灣曾經發生過的事件，以及在此生活的人們所留下的痕跡。\r\n\r\n「究・南物」則在這些既熟悉又陌生的歷史紀錄當中，為大家整理了重點年代並介紹該時代的特殊文物，同時整理出分別被典藏在什麼地方，設計了一些有趣的體驗，從3/7~5/11，分別在白雪珈琲店及臺南市立博物館開展。\r\n除了看展覽認識文物與歷史，也希望能透過這個機會認識展覽地區周邊特色景點或者書上文物的本尊。', `organizer`='臺南市文化資產管理處', `address`='臺南市中西區開山路152號', `start_date`='2025-04-10 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='臺南市立博物館(原鄭成功文物館)', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e84e3e26b32419285b7415', '台南市文物協會_40週年慶暨會員收藏特展 ', '台南市文物協會成立已40週年，本次特展將展示協會會員多年的收藏成果與心血，展品涵蓋了瓷器、玉器、紫砂、雜項等多樣類型，讓觀眾能夠深入了解其中的文化歷史及其演變。另外安排了專題講座與導覽活動，邀請專家學者分享他們對於文物的知識與文化傳承的見解，讓參觀者能夠在欣賞展品的同時，獲得更深入的知識，並喚起社會大眾對於文化遺產的重要性認識，鼓勵更多人參與文物的保護與傳承工作。', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-04-11 00:00:00', '2025-04-27 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台南市文物協會_40週年慶暨會員收藏特展 ', `description`='台南市文物協會成立已40週年，本次特展將展示協會會員多年的收藏成果與心血，展品涵蓋了瓷器、玉器、紫砂、雜項等多樣類型，讓觀眾能夠深入了解其中的文化歷史及其演變。另外安排了專題講座與導覽活動，邀請專家學者分享他們對於文物的知識與文化傳承的見解，讓參觀者能夠在欣賞展品的同時，獲得更深入的知識，並喚起社會大眾對於文化遺產的重要性認識，鼓勵更多人參與文物的保護與傳承工作。', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e84e3e26b32419285b7416', '心象綻芳-林錦濤水墨畫展', '水墨畫家林錦濤常至各地旅遊寫生，近者本島風景，遠則對岸名山大川，平日居家則喜栽花養木、蓄禽養魚。此次展出作品有風情景觀、禽鳥畜獸，以臺灣為主要描寫對象。對生於斯，長於斯的臺灣情感深厚，難以言語，近年來經過多次的遊歷與考察，以自然景觀、生態窺探、人文戀情、環保關懷等四系列進行創作及發表。', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-04-11 00:00:00', '2025-04-27 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='心象綻芳-林錦濤水墨畫展', `description`='水墨畫家林錦濤常至各地旅遊寫生，近者本島風景，遠則對岸名山大川，平日居家則喜栽花養木、蓄禽養魚。此次展出作品有風情景觀、禽鳥畜獸，以臺灣為主要描寫對象。對生於斯，長於斯的臺灣情感深厚，難以言語，近年來經過多次的遊歷與考察，以自然景觀、生態窺探、人文戀情、環保關懷等四系列進行創作及發表。', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e84e3e26b32419285b7417', '中華書道印藝學會_乙巳會員聯展－展翅上騰 ', '中華書道印藝學會成立逾二十載，由書法篆刻大師張添原先生創立，致力於推廣書藝與文化交流。本次會員聯展以「展翅上騰」為題，展出會員多年來於書道印藝的學習成果，展現對藝術的熱忱與傳承。透過此次展覽，期待向前輩專家與社會賢達請益，進一步提升學會的藝術水準，共同推動文化發展。', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-04-11 00:00:00', '2025-05-04 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中華書道印藝學會_乙巳會員聯展－展翅上騰 ', `description`='中華書道印藝學會成立逾二十載，由書法篆刻大師張添原先生創立，致力於推廣書藝與文化交流。本次會員聯展以「展翅上騰」為題，展出會員多年來於書道印藝的學習成果，展現對藝術的熱忱與傳承。透過此次展覽，期待向前輩專家與社會賢達請益，進一步提升學會的藝術水準，共同推動文化發展。', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e84e3e26b32419285b7418', '台灣綠水畫會_第35屆會員聯展 ', '膠彩畫為東方特有的藝術表現形式，與水墨畫同為代表東方傳統文化氣韻之美的風格，向來即同為東方藝術的兩大創作主軸。\r\n「膠彩」以動物膠調和礦物顏料及植物性顏料繪製而成，其繪製過程繁複，但能營造瑰麗絢爛、富麗堂皇或典雅的藝術視覺效果。\r\n台灣綠水畫會成立已久，是目前國內最具盛名的膠彩畫創作團體。每位老師均有其特別的表現技法，成員有來自大學之教授、美術研究所之碩士、專業創作之畫家⋯等。創作主題除了來自於自然生態的表現外，亦有詮釋心靈感受的直觀表現。\r\n此次展覽，旨在呈現其多面向、多元性的藝術創作型式，期以推動真、善、美的社會責任。盼能提供給觀賞民眾更豐富精彩的視覺饗宴，美化社會、美化人生。\r\n', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-04-11 00:00:00', '2025-05-04 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台灣綠水畫會_第35屆會員聯展 ', `description`='膠彩畫為東方特有的藝術表現形式，與水墨畫同為代表東方傳統文化氣韻之美的風格，向來即同為東方藝術的兩大創作主軸。\r\n「膠彩」以動物膠調和礦物顏料及植物性顏料繪製而成，其繪製過程繁複，但能營造瑰麗絢爛、富麗堂皇或典雅的藝術視覺效果。\r\n台灣綠水畫會成立已久，是目前國內最具盛名的膠彩畫創作團體。每位老師均有其特別的表現技法，成員有來自大學之教授、美術研究所之碩士、專業創作之畫家⋯等。創作主題除了來自於自然生態的表現外，亦有詮釋心靈感受的直觀表現。\r\n此次展覽，旨在呈現其多面向、多元性的藝術創作型式，期以推動真、善、美的社會責任。盼能提供給觀賞民眾更豐富精彩的視覺饗宴，美化社會、美化人生。\r\n', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e84e4d26b32419285b7419', '繪畫藝術課程：素描水彩油畫', '邀請劉耀文老師為學員介紹各種繪畫材料特性及教導各式繪畫技巧，包含素描、水彩、油畫等，讓學員可透過課程的學習，培養繪畫興趣，並愛上繪畫藝術。', '臺南市南關社區大學', '臺南市歸仁區中正北路一段148號', '2025-03-20 00:00:00', '2025-06-26 00:00:00', '臺南市歸仁區新豐高級中學', 22.94679469, 120.2930627, '3000元/人+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='繪畫藝術課程：素描水彩油畫', `description`='邀請劉耀文老師為學員介紹各種繪畫材料特性及教導各式繪畫技巧，包含素描、水彩、油畫等，讓學員可透過課程的學習，培養繪畫興趣，並愛上繪畫藝術。', `organizer`='臺南市南關社區大學', `address`='臺南市歸仁區中正北路一段148號', `start_date`='2025-03-20 00:00:00', `end_date`='2025-06-26 00:00:00', `location`='臺南市歸仁區新豐高級中學', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='3000元/人+--', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e84e4d26b32419285b741a', '戲說臺南古都的核心地帶！府城百年時空探險隊-西城門路線', '你曾想像過，臺南 300 年前的商業中心是什麼模樣嗎？\r\n海岸線隨著時間逐漸西移，商郊貿易因而往西推進\r\n府城的經濟活動依靠著長長的城牆維繫著⋯⋯\r\n歷史的痕跡與記憶，至今仍存於西定坊的街巷之中。\r\n\r\n🎭戲說西定坊商業防禦🎭\r\n這次活動將化身清代郊商，與夥伴討論如何抵禦海盜、找出奸細，揭開商業中心不為人知的歷史事件，實地走踏一探究竟～\r\n\r\n府城不只有商業重鎮的西定坊，還有寧南坊與東安坊，等你來收集城牆的歷史畫卷！\r\n\r\n寧南坊的小南門，作為通往鳳山縣的交通樞紐，承載著繁忙的民生市集，並交織出府城歷史的轉捩點。而東安坊的迎春門，除了是城內與歸仁、關廟地區往來的重要通道，也是清代迎春牛儀式的重要場域；透過儀式與遺跡的存廢議題，我們將一同探索府城消失的歷史印記。\r\n', '臺南市文化資產管理處', '臺南市中西區', '2025-04-11 00:00:00', '2025-04-18 00:00:00', '中西區（臺南市）=', 22.99594458, 120.192874, '350+--', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='戲說臺南古都的核心地帶！府城百年時空探險隊-西城門路線', `description`='你曾想像過，臺南 300 年前的商業中心是什麼模樣嗎？\r\n海岸線隨著時間逐漸西移，商郊貿易因而往西推進\r\n府城的經濟活動依靠著長長的城牆維繫著⋯⋯\r\n歷史的痕跡與記憶，至今仍存於西定坊的街巷之中。\r\n\r\n🎭戲說西定坊商業防禦🎭\r\n這次活動將化身清代郊商，與夥伴討論如何抵禦海盜、找出奸細，揭開商業中心不為人知的歷史事件，實地走踏一探究竟～\r\n\r\n府城不只有商業重鎮的西定坊，還有寧南坊與東安坊，等你來收集城牆的歷史畫卷！\r\n\r\n寧南坊的小南門，作為通往鳳山縣的交通樞紐，承載著繁忙的民生市集，並交織出府城歷史的轉捩點。而東安坊的迎春門，除了是城內與歸仁、關廟地區往來的重要通道，也是清代迎春牛儀式的重要場域；透過儀式與遺跡的存廢議題，我們將一同探索府城消失的歷史印記。\r\n', `organizer`='臺南市文化資產管理處', `address`='臺南市中西區', `start_date`='2025-04-11 00:00:00', `end_date`='2025-04-18 00:00:00', `location`='中西區（臺南市）=', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='350+--', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e84e5326b32419285b7426', '陸爸爸故事劇場：最棒的發明在我家', '一年一度的陸爸爸說故事又來囉，今年特別邀請陸爸爸團隊帶來劇場演出，演出的戲碼是陸爸爸的創作繪本《最棒的發明在我家》，歡迎大小朋友一起來享受親子繪本的歡樂與感動，趕緊來報名作伙來看兒童故事劇。\r\n\r\n演出節目：最棒的發明在我家\r\n演出人員：Angel老師、潘潘老師、美玲老師\r\n參加對象：30組親子\r\n報名方式：電話報名 (049)2420401', '南投縣埔里鎮公所', '南投縣埔里鎮六合路178號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '南投縣埔里鎮立圖書館', 23.9702357, 120.9713659, '無資料', 'https://www.facebook.com/pulilibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陸爸爸故事劇場：最棒的發明在我家', `description`='一年一度的陸爸爸說故事又來囉，今年特別邀請陸爸爸團隊帶來劇場演出，演出的戲碼是陸爸爸的創作繪本《最棒的發明在我家》，歡迎大小朋友一起來享受親子繪本的歡樂與感動，趕緊來報名作伙來看兒童故事劇。\r\n\r\n演出節目：最棒的發明在我家\r\n演出人員：Angel老師、潘潘老師、美玲老師\r\n參加對象：30組親子\r\n報名方式：電話報名 (049)2420401', `organizer`='南投縣埔里鎮公所', `address`='南投縣埔里鎮六合路178號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='南投縣埔里鎮立圖書館', `latitude`=23.9702357, `longitude`=120.9713659, `ticket_price`='無資料', `source_url`='https://www.facebook.com/pulilibrary', `image_url`='[]';
