INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e84e5426b32419285b742f', '113年南投縣客庄地方記憶空間專案計畫說明會：「南港村及九份二山文史資源」、「以文化景觀談論紀念性空間」專家分享講座', '你經歷過那場台灣發生規模高達 7.3 級、威力相當於 46 顆原子彈的大地震嗎？1999年9月21日凌晨1點47分，車龍埔斷層帶發生持續約102秒的強震，南投中寮、國姓及臺中東勢災情慘重，滿目瘡痍。你還記得嗎？九二一大地震引發九份二山大規模崩塌，形成「震爆點」，阻斷溪流並產生兩處堰塞湖。崁斗山東南坡滑動，當地水鹿場瞬間被埋，造成41人罹難、22人失蹤，300多頭水鹿喪生。為悼念罹難者，當地設立紀念碑與地震遺跡園區，供參觀與教育。\r\n本次說明會將帶領參與者了解南港村及九份二山的文史背景，探討地震對當地客家社區造成的影響應在「災難記憶」與「地方認同」之間取得平衡，藉由紀念性空間的說明，帶領公所、地方組織、民眾等人思考園區的規劃與設置，使其成為更全面的記憶空間，而非單一災難紀念場所，也能促進地方經濟，如觀光、文化創意產業等。\r\n演講主題：\r\n14:30-15:30 南港村及九份二山文史資源\r\n主講者：張永楨，專家學者\r\n\r\n15:40-16:40 以文化景觀談論紀念性空間\r\n主講：單世瑄，專家學者\r\n\r\n報名時間：即日起至114年4月18日(星期五)下午5時止開放線上報名。\r\n報名網址 https://forms.gle/PwLphDnUBxpKUJEAA', '南投縣客家發展所', '南投縣國姓鄉', '2025-04-24 00:00:00', '2025-04-24 00:00:00', '國姓鄉（南投縣）=', 24.03135413, 120.8676052, '無資料', 'https://www.facebook.com/nantou.nthcc', '[]') ON DUPLICATE KEY UPDATE `activity_name`='113年南投縣客庄地方記憶空間專案計畫說明會：「南港村及九份二山文史資源」、「以文化景觀談論紀念性空間」專家分享講座', `description`='你經歷過那場台灣發生規模高達 7.3 級、威力相當於 46 顆原子彈的大地震嗎？1999年9月21日凌晨1點47分，車龍埔斷層帶發生持續約102秒的強震，南投中寮、國姓及臺中東勢災情慘重，滿目瘡痍。你還記得嗎？九二一大地震引發九份二山大規模崩塌，形成「震爆點」，阻斷溪流並產生兩處堰塞湖。崁斗山東南坡滑動，當地水鹿場瞬間被埋，造成41人罹難、22人失蹤，300多頭水鹿喪生。為悼念罹難者，當地設立紀念碑與地震遺跡園區，供參觀與教育。\r\n本次說明會將帶領參與者了解南港村及九份二山的文史背景，探討地震對當地客家社區造成的影響應在「災難記憶」與「地方認同」之間取得平衡，藉由紀念性空間的說明，帶領公所、地方組織、民眾等人思考園區的規劃與設置，使其成為更全面的記憶空間，而非單一災難紀念場所，也能促進地方經濟，如觀光、文化創意產業等。\r\n演講主題：\r\n14:30-15:30 南港村及九份二山文史資源\r\n主講者：張永楨，專家學者\r\n\r\n15:40-16:40 以文化景觀談論紀念性空間\r\n主講：單世瑄，專家學者\r\n\r\n報名時間：即日起至114年4月18日(星期五)下午5時止開放線上報名。\r\n報名網址 https://forms.gle/PwLphDnUBxpKUJEAA', `organizer`='南投縣客家發展所', `address`='南投縣國姓鄉', `start_date`='2025-04-24 00:00:00', `end_date`='2025-04-24 00:00:00', `location`='國姓鄉（南投縣）=', `latitude`=24.03135413, `longitude`=120.8676052, `ticket_price`='無資料', `source_url`='https://www.facebook.com/nantou.nthcc', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e84e5426b32419285b7432', '藝生玩美─劉蘇錫、林秋鳳雙人聯展', '17年，可以發生什麼事？\r\n一個新生兒已長大，即將踏入大學；而內加道長青繪畫班的長輩們，先後在石珠鈴、廖珮如和陳立老師的陪伴下，在畫筆間找到新的方向，越畫越青春，越畫越有活力。\r\n本次聯展的兩位長者，99歲的蘇錫阿媽是班上最年長的學員，87歲提筆，與大家一同作畫至今。82歲的秋鳳阿媽，則是畫最久的學員，自65歲加入繪畫班，一畫就是17年。\r\n劉蘇錫阿媽是大埔里地區第一位裁縫師，埔里第一條AB褲便出自她手。至今眼力極佳，創作速度飛快，揮灑之間流露無限活力。\r\n林秋鳳阿媽的創作已突破紙張，延伸至石雕與馬賽克拼貼，作品靈動不拘形式，卻蘊含強烈的生命力，令人動容。\r\n歡迎來紙教堂，一同見證她們的生命故事，感受創作的力量！', '財團法人新故鄉文教基金會', '南投縣埔里鎮桃米巷52-12號', '2025-03-21 00:00:00', '2025-04-29 00:00:00', '紙教堂-新故鄉見學園區', 23.9435144, 120.9245216, '入園票+70', 'https://www.facebook.com/PaperDome545', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝生玩美─劉蘇錫、林秋鳳雙人聯展', `description`='17年，可以發生什麼事？\r\n一個新生兒已長大，即將踏入大學；而內加道長青繪畫班的長輩們，先後在石珠鈴、廖珮如和陳立老師的陪伴下，在畫筆間找到新的方向，越畫越青春，越畫越有活力。\r\n本次聯展的兩位長者，99歲的蘇錫阿媽是班上最年長的學員，87歲提筆，與大家一同作畫至今。82歲的秋鳳阿媽，則是畫最久的學員，自65歲加入繪畫班，一畫就是17年。\r\n劉蘇錫阿媽是大埔里地區第一位裁縫師，埔里第一條AB褲便出自她手。至今眼力極佳，創作速度飛快，揮灑之間流露無限活力。\r\n林秋鳳阿媽的創作已突破紙張，延伸至石雕與馬賽克拼貼，作品靈動不拘形式，卻蘊含強烈的生命力，令人動容。\r\n歡迎來紙教堂，一同見證她們的生命故事，感受創作的力量！', `organizer`='財團法人新故鄉文教基金會', `address`='南投縣埔里鎮桃米巷52-12號', `start_date`='2025-03-21 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='紙教堂-新故鄉見學園區', `latitude`=23.9435144, `longitude`=120.9245216, `ticket_price`='入園票+70', `source_url`='https://www.facebook.com/PaperDome545', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e84e5426b32419285b7434', '特展王船造船圖譜', '展覽呈現「王船再現」書籍精華，並透過展示圖譜與實物，讓觀眾深入了解傳統造船技藝獨特魅力，引發民眾關注木造船舶性能與保存議題，進一步保護與傳承文化資產。不僅是一場藝術與工藝的對話，更是探索海洋文化重要平台。', '國立成功大學博物館', '臺南市東區大學路1號（成功校區）', '2025-03-18 00:00:00', '2025-07-18 00:00:00', '國立成功大學博物館', 22.98178202, 120.2281858, '無資料', 'https://www.cna.com.tw/news/acul/202503180350.aspx', '[]') ON DUPLICATE KEY UPDATE `activity_name`='特展王船造船圖譜', `description`='展覽呈現「王船再現」書籍精華，並透過展示圖譜與實物，讓觀眾深入了解傳統造船技藝獨特魅力，引發民眾關注木造船舶性能與保存議題，進一步保護與傳承文化資產。不僅是一場藝術與工藝的對話，更是探索海洋文化重要平台。', `organizer`='國立成功大學博物館', `address`='臺南市東區大學路1號（成功校區）', `start_date`='2025-03-18 00:00:00', `end_date`='2025-07-18 00:00:00', `location`='國立成功大學博物館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='https://www.cna.com.tw/news/acul/202503180350.aspx', `image_url`='[]';
