INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e99e0a26b32419285b7437', '意料之外神展開：踏上文學銀幕奇幻之旅特展', '在當代文學作品紛紛搬上影視舞臺，隨著影音串流平臺進軍國際，展開嶄新篇章之際，本館將在2025年4月1日以臺灣文學改編影視為題辦理「意料之外神展開：踏上文學銀幕奇幻之旅」特展。 展場中將帶領觀眾重溫昔日台語電影高峰；1960年代瓊瑤愛情童話及「三廳電影」風潮；1970年代武俠改編電影如何與香港跨海較勁；1980年代開創新電影形式與語言的臺灣新電影浪潮。展覽將邀請觀眾走入經典電影場景、編寫對白、獻聲為主角重新配音，並爬梳不同年代電影主題曲，搭配文學作品改編電影劇本、手稿、照片與相關器物，透過流動的聲音影像，串接臺灣風土人情。', '國立臺灣文學館', '臺南市中西區中正路1號', '2025-04-01 00:00:00', '2025-11-22 00:00:00', '國立臺灣文學館', 22.992064, 120.203953, '無資料', 'https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=50053', '[]') ON DUPLICATE KEY UPDATE `activity_name`='意料之外神展開：踏上文學銀幕奇幻之旅特展', `description`='在當代文學作品紛紛搬上影視舞臺，隨著影音串流平臺進軍國際，展開嶄新篇章之際，本館將在2025年4月1日以臺灣文學改編影視為題辦理「意料之外神展開：踏上文學銀幕奇幻之旅」特展。 展場中將帶領觀眾重溫昔日台語電影高峰；1960年代瓊瑤愛情童話及「三廳電影」風潮；1970年代武俠改編電影如何與香港跨海較勁；1980年代開創新電影形式與語言的臺灣新電影浪潮。展覽將邀請觀眾走入經典電影場景、編寫對白、獻聲為主角重新配音，並爬梳不同年代電影主題曲，搭配文學作品改編電影劇本、手稿、照片與相關器物，透過流動的聲音影像，串接臺灣風土人情。', `organizer`='國立臺灣文學館', `address`='臺南市中西區中正路1號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-11-22 00:00:00', `location`='國立臺灣文學館', `latitude`=22.992064, `longitude`=120.203953, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMTL/Detail.init.ctr?actId=50053', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e99e0a26b32419285b7438', '紙芝居故事創作工作坊~114.05月', '臺史博收藏許多反映臺灣歷史和文化的日常物件，其中紙芝居是一種用畫在紙上的圖畫來說演故事的表演形式，特別吸引小朋友的目光。這樣的表演形式不僅是視覺和聽覺的雙重享受，還能激發創造力與想像力。本次課程以紙芝居藏品出發，介紹紙芝居由來，認識紙芝居說故事技巧，學習如何透過簡單的圖畫來設計故事情節，以動手體驗創作故事的方式，讓大家了解紙芝居的特色和魅力。', '國立臺灣歷史博物館', '臺南市安南區長和路一段250號', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '國立臺灣歷史博物館', 23.04869681, 120.1526189, '無資料', 'https://event.culture.tw/mocweb/reg/NMTH/Detail.init.ctr?actId=50033', '[]') ON DUPLICATE KEY UPDATE `activity_name`='紙芝居故事創作工作坊~114.05月', `description`='臺史博收藏許多反映臺灣歷史和文化的日常物件，其中紙芝居是一種用畫在紙上的圖畫來說演故事的表演形式，特別吸引小朋友的目光。這樣的表演形式不僅是視覺和聽覺的雙重享受，還能激發創造力與想像力。本次課程以紙芝居藏品出發，介紹紙芝居由來，認識紙芝居說故事技巧，學習如何透過簡單的圖畫來設計故事情節，以動手體驗創作故事的方式，讓大家了解紙芝居的特色和魅力。', `organizer`='國立臺灣歷史博物館', `address`='臺南市安南區長和路一段250號', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='國立臺灣歷史博物館', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NMTH/Detail.init.ctr?actId=50033', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67e99e0a26b32419285b7439', '【2025展覽】在綠光中起舞—徐秀美個展', '【藝術家介紹】\r\n徐秀美（May Hsu）藝術家，為台灣當代藝術家，早年以書籍封面與插畫設計聞名，後赴紐約進修，作品曾刊登於國際專業雜誌《Print》。返台後，她的創作跨足繪畫、雕塑、服裝、影像裝置與公共藝術，擅長透過作品探討環境、社會與人文議題，代表作《鳥籠外的花園》（台北敦化南路）為台灣最具影響力的公共藝術之一。\r\n\r\n【策展論述】\r\n綠光－生機覺醒\r\n起舞－生命奮起\r\n藉由此次展出主題「在綠光中起舞」，期望透過藝術品特有的形徵能量，融入自然生態綠光般的芬多精意象。釋放當代的「美學因子」，給予環境藝術視覺面向的感性關懷，得到身、心、靈精神療癒般的愉悅氛圍。\r\n尤其處於多變紛亂的時代環境中，因之而起的生命疑惑、失落，引發的憂慮、消沉，經由作品看見「美」的感染力，從「躺平」的意象中覺醒、奮起，欣然在溫暖陽光下，迎向大自然心靈花園中翩然起舞！\r\n\r\n【創作理念】\r\n藝術不僅是視覺的展現，更是一種穿透心靈的力量。徐秀美藝術家期望透過作品的美學感染力，為身處變動環境、心中充滿不確定感的人們，帶來精神性的藝術亮光與心靈的撫慰。', '國立成功大學', '臺南市東區大學路1號', '2025-04-12 00:00:00', '2025-05-17 00:00:00', '國立成功大學', 22.98178202, 120.2281858, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025展覽】在綠光中起舞—徐秀美個展', `description`='【藝術家介紹】\r\n徐秀美（May Hsu）藝術家，為台灣當代藝術家，早年以書籍封面與插畫設計聞名，後赴紐約進修，作品曾刊登於國際專業雜誌《Print》。返台後，她的創作跨足繪畫、雕塑、服裝、影像裝置與公共藝術，擅長透過作品探討環境、社會與人文議題，代表作《鳥籠外的花園》（台北敦化南路）為台灣最具影響力的公共藝術之一。\r\n\r\n【策展論述】\r\n綠光－生機覺醒\r\n起舞－生命奮起\r\n藉由此次展出主題「在綠光中起舞」，期望透過藝術品特有的形徵能量，融入自然生態綠光般的芬多精意象。釋放當代的「美學因子」，給予環境藝術視覺面向的感性關懷，得到身、心、靈精神療癒般的愉悅氛圍。\r\n尤其處於多變紛亂的時代環境中，因之而起的生命疑惑、失落，引發的憂慮、消沉，經由作品看見「美」的感染力，從「躺平」的意象中覺醒、奮起，欣然在溫暖陽光下，迎向大自然心靈花園中翩然起舞！\r\n\r\n【創作理念】\r\n藝術不僅是視覺的展現，更是一種穿透心靈的力量。徐秀美藝術家期望透過作品的美學感染力，為身處變動環境、心中充滿不確定感的人們，帶來精神性的藝術亮光與心靈的撫慰。', `organizer`='國立成功大學', `address`='臺南市東區大學路1號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='國立成功大學', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
