INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb137526b32419285b745a', '【新北市立圖書館淡水竹圍分館】114年4月主題書展 :《趣味園藝》', '《趣味園藝》主題書展\r\n\r\n時間：4/1(二)-4/20(日)  開館時間\r\n地點：淡水竹圍分館5樓圖書室（淡水區民生路27號）\r\n電話：02-2809-7442轉9\r\n\r\n簡介：擁有自家菜園是許多人的夢想。不過當農夫哪有那麼簡單，要懂季節，也要懂植物，更要具備各種相關技巧，才能種出一番成績。透過實作多樣綠美化作品讓綠活喜悅充滿生活空間。了解植物生長特性，讓喜歡花草植物與栽種分享的朋友們，達成綠活美好分享的目標。', '新北市立圖書館總館', '新北市淡水區民生路27號4樓、5樓、6樓', '2025-04-01 00:00:00', '2025-04-20 00:00:00', '新北市立圖書館淡水竹圍分館', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡水竹圍分館】114年4月主題書展 :《趣味園藝》', `description`='《趣味園藝》主題書展\r\n\r\n時間：4/1(二)-4/20(日)  開館時間\r\n地點：淡水竹圍分館5樓圖書室（淡水區民生路27號）\r\n電話：02-2809-7442轉9\r\n\r\n簡介：擁有自家菜園是許多人的夢想。不過當農夫哪有那麼簡單，要懂季節，也要懂植物，更要具備各種相關技巧，才能種出一番成績。透過實作多樣綠美化作品讓綠活喜悅充滿生活空間。了解植物生長特性，讓喜歡花草植物與栽種分享的朋友們，達成綠活美好分享的目標。', `organizer`='新北市立圖書館總館', `address`='新北市淡水區民生路27號4樓、5樓、6樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='新北市立圖書館淡水竹圍分館', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb137526b32419285b745b', '【淡海小書房】114年4月主題書展 :《兒童知識家》', '《兒童知識家》主題書展\r\n\r\n時間：4/1(二)-4/30(三) 開館時間\r\n地點：淡海小書房（淡水區中正東路2段68號）\r\n電話：02-2808-0400\r\n\r\n簡介：\r\n豐富逼真的圖片、深入淺出的文字、趣味的補充知識、清楚的分類索引，讓孩子一目瞭然，最想知道的科普、生活、語言等內容，都在這裡等您來探索！\r\n\r\n備註：\r\n1.開館時間為每日11時至19時。\r\n2.4月3日(四)~4月4日(五)國定假日、4月24日(四)清館日，不對外開放。', '新北市立圖書館總館', '新北市淡水區中正東路2段68號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '淡海小書房', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【淡海小書房】114年4月主題書展 :《兒童知識家》', `description`='《兒童知識家》主題書展\r\n\r\n時間：4/1(二)-4/30(三) 開館時間\r\n地點：淡海小書房（淡水區中正東路2段68號）\r\n電話：02-2808-0400\r\n\r\n簡介：\r\n豐富逼真的圖片、深入淺出的文字、趣味的補充知識、清楚的分類索引，讓孩子一目瞭然，最想知道的科普、生活、語言等內容，都在這裡等您來探索！\r\n\r\n備註：\r\n1.開館時間為每日11時至19時。\r\n2.4月3日(四)~4月4日(五)國定假日、4月24日(四)清館日，不對外開放。', `organizer`='新北市立圖書館總館', `address`='新北市淡水區中正東路2段68號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='淡海小書房', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
