INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb137526b32419285b745d', '【新北市立圖書館淡水分館】 《4月主題書展 : 便當文化史》', '《便當文化史》主題書展\r\n\r\n\r\n時間：4/7(一)-4/27(日)\r\n地點：淡水分館3F閱覽室\r\n（淡水區文化路65號3F）\r\n電話：02-26224664\r\n\r\n簡介：\r\n由不來梅創意設計、自由食間科技公司與銀色大門慈善機構共同推動的「老食人便當」計畫，一舉推翻便當長久以來約定俗成視之為表現幸福的定義，「隔夜雞腿飯」、「發霉鯖魚飯」、「酸味控肉飯」------打開這些便當，映入眼簾的是孤老長者面臨的飲食危機諸如被迫食用不新鮮食物，營養攝取不均加速身體機能退化等。2025年一開年農業部「幸福食材網」即公告，幸福餐盒計畫因經費問題只提供到1月底。全聯、家樂福及時表示，60元平價便當仍會持續販售，小資族對平價便當的需求無虞。便當從連結私人感情的記憶如搭火車吃便當的美好生活儀式，搖身一變成為公眾福利問題的關鍵指標！\r\n', '新北市立圖書館總館', '新北市淡水區文化路65號', '2025-04-07 00:00:00', '2025-04-27 00:00:00', '新北市立圖書館淡水分館', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館淡水分館】 《4月主題書展 : 便當文化史》', `description`='《便當文化史》主題書展\r\n\r\n\r\n時間：4/7(一)-4/27(日)\r\n地點：淡水分館3F閱覽室\r\n（淡水區文化路65號3F）\r\n電話：02-26224664\r\n\r\n簡介：\r\n由不來梅創意設計、自由食間科技公司與銀色大門慈善機構共同推動的「老食人便當」計畫，一舉推翻便當長久以來約定俗成視之為表現幸福的定義，「隔夜雞腿飯」、「發霉鯖魚飯」、「酸味控肉飯」------打開這些便當，映入眼簾的是孤老長者面臨的飲食危機諸如被迫食用不新鮮食物，營養攝取不均加速身體機能退化等。2025年一開年農業部「幸福食材網」即公告，幸福餐盒計畫因經費問題只提供到1月底。全聯、家樂福及時表示，60元平價便當仍會持續販售，小資族對平價便當的需求無虞。便當從連結私人感情的記憶如搭火車吃便當的美好生活儀式，搖身一變成為公眾福利問題的關鍵指標！\r\n', `organizer`='新北市立圖書館總館', `address`='新北市淡水區文化路65號', `start_date`='2025-04-07 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='新北市立圖書館淡水分館', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
