INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb137e26b32419285b7461', '【新北市立圖書館八里分館】114年4月書展', '114/4/1-4/30　五樓書展：「泰」好玩啦！\r\n4月中為泰國的潑水節，\r\n藉此來介紹泰國的文化與觀光資訊，\r\n探索在地的歷史、習俗與特色文化。\r\n\r\n114/4/1-4/30　六樓兒童書展：舞吧！舞吧！\r\n你知道4/29世界舞蹈日?!\r\n創立目的是希望透過舞蹈，\r\n促進各種文化的交流與理解，\r\n本次介紹以舞蹈為主題的故事，\r\n激發大家對於肢體的表現與認識，\r\n感受舞蹈的樂趣與魅力。', '新北市立圖書館總館', '新北市八里區舊城路19號5、6樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館八里分館', 25.13812763, 121.4138359, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館八里分館】114年4月書展', `description`='114/4/1-4/30　五樓書展：「泰」好玩啦！\r\n4月中為泰國的潑水節，\r\n藉此來介紹泰國的文化與觀光資訊，\r\n探索在地的歷史、習俗與特色文化。\r\n\r\n114/4/1-4/30　六樓兒童書展：舞吧！舞吧！\r\n你知道4/29世界舞蹈日?!\r\n創立目的是希望透過舞蹈，\r\n促進各種文化的交流與理解，\r\n本次介紹以舞蹈為主題的故事，\r\n激發大家對於肢體的表現與認識，\r\n感受舞蹈的樂趣與魅力。', `organizer`='新北市立圖書館總館', `address`='新北市八里區舊城路19號5、6樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館八里分館', `latitude`=25.13812763, `longitude`=121.4138359, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb137e26b32419285b7462', '【新北市立圖書館深坑分館】《閱讀書籤》114年4月「清明時節雨紛紛 遙祭祖先倍思親」主題書展', '【新北市立圖書館深坑分館】《閱讀書籤》114年4月「清明時節雨紛紛 遙祭祖先倍思親」主題書展\r\n\r\n活動日期:114/4/1-114/4/30\r\n週二~週六 : 08:30~21:00，\r\n週日~週一 : 08:30~17:00。\r\n4月3日、4月4日國定假日、4月24日清館日不對外開放\r\n活動地點:1樓 主題書展區\r\n\r\n清明時節是慎終追遠、掃墓祭祖的大日子，除了掃墓外，還有更多你意想不到的清明傳統習俗，大家趕快來看看吧！\r\n•掃墓祭祖•吃潤餅•紅龜粿•草仔粿 •踏青•行青•放風箏\r\n\r\n書展展示期間，歡迎借閱。', '新北市立圖書館總館', '新北市深坑區深坑街10號1樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館深坑分館', 24.99767506, 121.6200624, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館深坑分館】《閱讀書籤》114年4月「清明時節雨紛紛 遙祭祖先倍思親」主題書展', `description`='【新北市立圖書館深坑分館】《閱讀書籤》114年4月「清明時節雨紛紛 遙祭祖先倍思親」主題書展\r\n\r\n活動日期:114/4/1-114/4/30\r\n週二~週六 : 08:30~21:00，\r\n週日~週一 : 08:30~17:00。\r\n4月3日、4月4日國定假日、4月24日清館日不對外開放\r\n活動地點:1樓 主題書展區\r\n\r\n清明時節是慎終追遠、掃墓祭祖的大日子，除了掃墓外，還有更多你意想不到的清明傳統習俗，大家趕快來看看吧！\r\n•掃墓祭祖•吃潤餅•紅龜粿•草仔粿 •踏青•行青•放風箏\r\n\r\n書展展示期間，歡迎借閱。', `organizer`='新北市立圖書館總館', `address`='新北市深坑區深坑街10號1樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館深坑分館', `latitude`=24.99767506, `longitude`=121.6200624, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb139026b32419285b7463', '廖修平與弟子們', '為紀念台灣版畫藝術大師廖修平對版畫藝術的卓越貢獻，以及他對後輩藝術家的深遠影響，將於3月25日至4月19日舉辦《廖修平與弟子們》台灣展。展覽由鐘有輝與宮山広明共同策劃，邀請台灣及日本的多位藝術家共同參展，呈現跨越國界與世代的藝術交流與傳承。\r\n\r\n廖修平是台灣現代版畫的重要推手，自20世紀中葉起，積極推廣現代版畫藝術，不僅在創作上屢獲國際肯定，更致力於教育與指導，培育出許多傑出的版畫藝術家。本次展覽將展出廖修平與其弟子們的作品，展示版畫藝術在不同文化背景下的延續與發展，呈現師生之間的深厚藝術脈絡。\r\n\r\n本次參展有來自台灣藝術家包括：廖修平、鐘有輝、林雪卿、沈金源、賴振輝、徐明豐、林仁信、田文筆、楊紋瑜、黃得誠及江芷萱；來自日本的藝術家則包括：新井知生、岡田匡史、金澤安宏、轡孝之、澤田祐一、鈴木司、沼尻昭子、畑順子及宮山広明。\r\n\r\n這次展覽不僅是對廖修平藝術成就的致敬，也是一場東西文化的對話，透過師徒之間的作品交流，讓觀者得以窺見版畫藝術在不同時代與地域中的多樣風貌。', '財團法人巴黎文教基金會', '臺中市西區林森路38巷1號', '2025-03-25 00:00:00', '2025-04-19 00:00:00', '印 藝文空間 / 咖啡', 24.14391082, 120.6647579, '無資料', 'https://www.facebook.com/share/p/1CzSFLpxfe/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='廖修平與弟子們', `description`='為紀念台灣版畫藝術大師廖修平對版畫藝術的卓越貢獻，以及他對後輩藝術家的深遠影響，將於3月25日至4月19日舉辦《廖修平與弟子們》台灣展。展覽由鐘有輝與宮山広明共同策劃，邀請台灣及日本的多位藝術家共同參展，呈現跨越國界與世代的藝術交流與傳承。\r\n\r\n廖修平是台灣現代版畫的重要推手，自20世紀中葉起，積極推廣現代版畫藝術，不僅在創作上屢獲國際肯定，更致力於教育與指導，培育出許多傑出的版畫藝術家。本次展覽將展出廖修平與其弟子們的作品，展示版畫藝術在不同文化背景下的延續與發展，呈現師生之間的深厚藝術脈絡。\r\n\r\n本次參展有來自台灣藝術家包括：廖修平、鐘有輝、林雪卿、沈金源、賴振輝、徐明豐、林仁信、田文筆、楊紋瑜、黃得誠及江芷萱；來自日本的藝術家則包括：新井知生、岡田匡史、金澤安宏、轡孝之、澤田祐一、鈴木司、沼尻昭子、畑順子及宮山広明。\r\n\r\n這次展覽不僅是對廖修平藝術成就的致敬，也是一場東西文化的對話，透過師徒之間的作品交流，讓觀者得以窺見版畫藝術在不同時代與地域中的多樣風貌。', `organizer`='財團法人巴黎文教基金會', `address`='臺中市西區林森路38巷1號', `start_date`='2025-03-25 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='印 藝文空間 / 咖啡', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1CzSFLpxfe/', `image_url`='[]';
