INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb139926b32419285b7469', '【新北市青少年圖書館】114年4月彩虹故事屋	', '【新北市青少年圖書館】4月彩虹故事屋\r\n\r\n歡迎家長們帶著學齡前及國小兒童一同到青少年圖書館聆聽說故事志工講故事。聽著說故事志工用著活潑的語調及豐富的肢體動作，吸引小朋友們的注意力，引起他們對閱讀的興趣，搭配故事的內容做手作、問答等活動，讓小朋友們感受過程中的樂趣，家長們跟著孩子一同體驗，增加親子間的溫馨互動。\r\n\r\n【中文說故事】\r\n04/05（六）15:00-16:00 /劉寶鳳\r\n可以一起玩嗎? \r\n\r\n04/26（六）15:00-16:00 /徐妤嘉\r\n大吼大叫的企鵝媽媽 \r\n\r\n【英文說故事】\r\n04/12（六）15:00-16:00 /黃蜀玉\r\nIllustrated stories from around the world--- Stories from Scandinavia & America\r\n\r\n備註：如有異動，以現場公告為準。', '新北市立圖書館總館', '新北市新店區安康路2段151號', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '新北市青少年圖書館', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市青少年圖書館】114年4月彩虹故事屋	', `description`='【新北市青少年圖書館】4月彩虹故事屋\r\n\r\n歡迎家長們帶著學齡前及國小兒童一同到青少年圖書館聆聽說故事志工講故事。聽著說故事志工用著活潑的語調及豐富的肢體動作，吸引小朋友們的注意力，引起他們對閱讀的興趣，搭配故事的內容做手作、問答等活動，讓小朋友們感受過程中的樂趣，家長們跟著孩子一同體驗，增加親子間的溫馨互動。\r\n\r\n【中文說故事】\r\n04/05（六）15:00-16:00 /劉寶鳳\r\n可以一起玩嗎? \r\n\r\n04/26（六）15:00-16:00 /徐妤嘉\r\n大吼大叫的企鵝媽媽 \r\n\r\n【英文說故事】\r\n04/12（六）15:00-16:00 /黃蜀玉\r\nIllustrated stories from around the world--- Stories from Scandinavia & America\r\n\r\n備註：如有異動，以現場公告為準。', `organizer`='新北市立圖書館總館', `address`='新北市新店區安康路2段151號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='新北市青少年圖書館', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
