INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13a726b32419285b7476', '惠文國民小學 2025兒童樂隊聯合音樂會：惠風竹韻共譜雅樂', '這場音樂會是由北區和中區兒童樂隊備受注目的兩支特優隊伍共同演出。\r\n大竹國小指揮是今年帶團第32年的薛老師，在網路上謙稱水牛老師，默默耕耘分享無數兒童樂隊帶團理念與音樂想法。惠文國小指揮梁老師今年則是第16年帶團，樂團曲風多元，更是開啟一股改編管樂團曲目的風潮。\r\n這場音樂會不僅是一場技藝的展現，更是音樂交流的盛會。我們特別安排導聆，帶領觀眾細細品味每一首樂曲的故事與情感，讓您不只是聆聽，更能深入理解音樂的靈魂。從悠揚的古典樂章，還是充滿活力的現代樂曲，每一段旋律都蘊含著孩子們的熱情與努力，他們用音樂架起橋樑，傳遞美好與感動。\r\n\r\n演出曲目\r\n\r\n打擊合奏\r\n世界樹を越えて、迪士尼組曲、怪物\r\n\r\n兒童樂隊合奏\r\n天堂與地獄序曲、霍爾的移動城堡、新世界交響曲第一樂章\r\nUnder the sea、歌劇魅影組曲、藍色狂想曲', '臺中市南屯區惠文國民小學', '臺中市北區學士路98號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '臺中市中山堂', 24.15863985, 120.6809521, '全票+250', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='惠文國民小學 2025兒童樂隊聯合音樂會：惠風竹韻共譜雅樂', `description`='這場音樂會是由北區和中區兒童樂隊備受注目的兩支特優隊伍共同演出。\r\n大竹國小指揮是今年帶團第32年的薛老師，在網路上謙稱水牛老師，默默耕耘分享無數兒童樂隊帶團理念與音樂想法。惠文國小指揮梁老師今年則是第16年帶團，樂團曲風多元，更是開啟一股改編管樂團曲目的風潮。\r\n這場音樂會不僅是一場技藝的展現，更是音樂交流的盛會。我們特別安排導聆，帶領觀眾細細品味每一首樂曲的故事與情感，讓您不只是聆聽，更能深入理解音樂的靈魂。從悠揚的古典樂章，還是充滿活力的現代樂曲，每一段旋律都蘊含著孩子們的熱情與努力，他們用音樂架起橋樑，傳遞美好與感動。\r\n\r\n演出曲目\r\n\r\n打擊合奏\r\n世界樹を越えて、迪士尼組曲、怪物\r\n\r\n兒童樂隊合奏\r\n天堂與地獄序曲、霍爾的移動城堡、新世界交響曲第一樂章\r\nUnder the sea、歌劇魅影組曲、藍色狂想曲', `organizer`='臺中市南屯區惠文國民小學', `address`='臺中市北區學士路98號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='臺中市中山堂', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='全票+250', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13a726b32419285b7477', '林之助講堂-展覽講座', '以年度展覽為核心延伸策畫講座，包含音樂、影像、環境美學、壁畫顏料等主題，探索藝術在不同時代轉變下如何承載靈感，並在當代創作中找到新的詮釋方式，提供大眾深入了解藝術創作與文化演變的機會。\r\n\r\n4/19 (六) 14:00-16:00 張蒼松 傾聽池上穀籟	\r\n5/17 (六) 14:00-16:00 張蒼松 影像/文字/田野調查互相幫襯	\r\n6/28 (六) 14:00-16:00 張惠蘭 環境美學的色彩敘事	\r\n8/16 (六) 14:00-16:00 鹿向夷 以質設色，以步為度—斯庇提山谷地區寺院壁畫的膠彩顏料踏查\r\n10/25 (六) 14:00-16:00 蔡根 空間中的關係美學	', '國立臺中教育大學', '臺中市西區柳川西路二段158號', '2025-04-19 00:00:00', '2025-10-25 00:00:00', '林之助紀念館', 24.14391082, 120.6647579, '無資料', 'https://www.linchihchu.com/newsContent.php?id=157', '[]') ON DUPLICATE KEY UPDATE `activity_name`='林之助講堂-展覽講座', `description`='以年度展覽為核心延伸策畫講座，包含音樂、影像、環境美學、壁畫顏料等主題，探索藝術在不同時代轉變下如何承載靈感，並在當代創作中找到新的詮釋方式，提供大眾深入了解藝術創作與文化演變的機會。\r\n\r\n4/19 (六) 14:00-16:00 張蒼松 傾聽池上穀籟	\r\n5/17 (六) 14:00-16:00 張蒼松 影像/文字/田野調查互相幫襯	\r\n6/28 (六) 14:00-16:00 張惠蘭 環境美學的色彩敘事	\r\n8/16 (六) 14:00-16:00 鹿向夷 以質設色，以步為度—斯庇提山谷地區寺院壁畫的膠彩顏料踏查\r\n10/25 (六) 14:00-16:00 蔡根 空間中的關係美學	', `organizer`='國立臺中教育大學', `address`='臺中市西區柳川西路二段158號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-10-25 00:00:00', `location`='林之助紀念館', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://www.linchihchu.com/newsContent.php?id=157', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13a826b32419285b7478', '與光同塵 - 梁景婷 阿比 雙個展', '與光同塵｜梁景婷 阿比 雙個展\r\n—— 在信仰與創作之間，尋找光的形狀\r\n\r\n光，是指引，是啟示，也是見證。在這場名為 《與光同塵》 的雙個展中，兩位非藝術本科系出身的基督徒女性，以創作回應內在的信仰歷程，透過畫筆、顏料與材質的碰撞，探索光如何穿透日常、映照靈魂，並在塵世之中留下溫柔而堅定的痕跡。\r\n她們的藝術並非來自學院的框架，而是從生活與信仰的體悟中自然生發。在這條未曾受過正規訓練的創作之路上，她們憑藉對神的信靠與內心的感動，讓作品成為一場無聲的祈禱，將個人經驗轉化為視覺語言，邀請觀者一同進入她們的世界——一個被光觸動、被恩典承載的空間。\r\n「與光同塵」，是一種姿態，也是一場有光同在的見證。在光中，我們看見自己，也看見彼此；在塵世中，我們行走，卻不迷失。願這場展覽能夠帶給每位來訪者一絲安慰、一點啟發，或是某種無法言喻的平安。\r\n\r\n❍ 與光同塵 Immanual _ 梁景婷/阿比 雙個展\r\n展期｜ 2025.04.01 – 2023.04.30\r\n開幕｜ 2025.04.06 (日) 2:00 p.m.\r\n地點｜ 新裕興咖啡 SEEN RU HING COFFEELLERY\r\n新北市板橋區大觀路二段174巷159號2樓\r\n\r\n誠摯邀請您，一同來感受光與塵的交會，在信仰與藝術的交織中，遇見內心的小塵光。\r\n', 'Abigale阿比的途中藝術', '新北市板橋區', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '板橋區（新北市）=', 25.01186453, 121.4579675, '無資料', 'https://www.facebook.com/share/1JpM5yxUg1/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='與光同塵 - 梁景婷 阿比 雙個展', `description`='與光同塵｜梁景婷 阿比 雙個展\r\n—— 在信仰與創作之間，尋找光的形狀\r\n\r\n光，是指引，是啟示，也是見證。在這場名為 《與光同塵》 的雙個展中，兩位非藝術本科系出身的基督徒女性，以創作回應內在的信仰歷程，透過畫筆、顏料與材質的碰撞，探索光如何穿透日常、映照靈魂，並在塵世之中留下溫柔而堅定的痕跡。\r\n她們的藝術並非來自學院的框架，而是從生活與信仰的體悟中自然生發。在這條未曾受過正規訓練的創作之路上，她們憑藉對神的信靠與內心的感動，讓作品成為一場無聲的祈禱，將個人經驗轉化為視覺語言，邀請觀者一同進入她們的世界——一個被光觸動、被恩典承載的空間。\r\n「與光同塵」，是一種姿態，也是一場有光同在的見證。在光中，我們看見自己，也看見彼此；在塵世中，我們行走，卻不迷失。願這場展覽能夠帶給每位來訪者一絲安慰、一點啟發，或是某種無法言喻的平安。\r\n\r\n❍ 與光同塵 Immanual _ 梁景婷/阿比 雙個展\r\n展期｜ 2025.04.01 – 2023.04.30\r\n開幕｜ 2025.04.06 (日) 2:00 p.m.\r\n地點｜ 新裕興咖啡 SEEN RU HING COFFEELLERY\r\n新北市板橋區大觀路二段174巷159號2樓\r\n\r\n誠摯邀請您，一同來感受光與塵的交會，在信仰與藝術的交織中，遇見內心的小塵光。\r\n', `organizer`='Abigale阿比的途中藝術', `address`='新北市板橋區', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='板橋區（新北市）=', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/1JpM5yxUg1/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13ad26b32419285b747a', '臺中市大里區戶政事務所114年第2期藝文展覽', '一、 一樓展覽以林穆瑛女士的作品為展出主軸林穆瑛女士在水墨畫師承陳華老師追隨古員齊老師學習流暢快速，富有動感 的行草書法。本次展覽特別搭配新春節令，展現喜氣洋洋的新春吉祥畫系列。作者從事公務工作業餘喜歡遊藝於書畫藉此滋養身心，為心靈澆灌一瓢清泉也展現在書畫的意境上；本次作品有以書為體畫為境的寫意風也有作者以簡練的筆墨來表達物象的內在精神，傳達古代文人在新春期間的深厚情懷。更有具體象徵富貴吉祥的花鳥小品，傳達作者與水墨對於自然、社會和人生的獨特理解方式 。\r\n此次展品風格形式多元，展現作者的書畫理解與創作風格配合年節喜慶，在作品中蘊含著傳統的文化底蘊和美好的祝願。這一季我們將隨著作者的創作視野，沉浸在書詩畫的視覺藝術饗宴中，歡迎各界人士賞析與指教，感受年節的喜慶與傳遞的祝福。\r\n\r\n二、 二樓廳舍的展覽作品以黃玉燕女士的粉彩作品為展出主軸，黃玉燕女士學習水墨畫多年，師承何木火、陳華老師，因喜愛粉彩的色彩變化，因此跟隨陳華老師學習粉彩畫3年多，作者特別將平時寫生隨筆創作，展示於二樓，希望所有觀畫與洽公民眾欣賞台灣獨特的景貌。粉彩因為是天然礦物，色料純淨，色彩飽和度高，因此玉燕女士以其特性，疊加出豐富的色彩層次和過渡效果。而粉彩柔和、溫潤的視覺效果，特別適合表現台灣景物的質感和光影變化。\r\n同時粉彩畫是以手指塗抹，創造出獨特的暈染效果和柔和的邊緣，從細膩的線條到粗獷的筆觸都能表現。作者外號小燕子喜歡到處遊覽台灣的山水，一景一物總能透過粉彩的穩定度，總能詮釋作者的情感。此次展覽作品中，是否有你曾經熟悉的攬勝景點，讓我們透過小燕子的視角與粉彩的對話中，一起遊覽台灣美麗的山川景緻，洗滌繁華的煩憂。歡迎各界人士賞析與指教。\r\n\r\n三、 展作品簡介 作者：黃玉燕\r\n\r\n主題：黃玉燕寫生粉彩畫個展\r\n得獎紀錄：2023年 水墨作品獲第44屆金環獎佳作\r\n展覽經歷:\r\n2024年 墨彩風情藝術展(個展-國資圖樂齡創意長廊)\r\n2023-2018年 華夏書畫協會聯展、台中市藝術家學會聯展清溪新文藝學會聯展 台中市潮中畫會中華甲骨文學會聯展\r\n2022 台中市石岡圖書館個展\r\n2011年、2019 2017台中市清水區戶政事務所個展\r\n\r\n四、展作品簡介 作者：林穆瑛\r\n\r\n主題：\r\n林穆瑛 吉祥畫 水墨 展\r\n覽經歷 :\r\n2010 年 2024 華夏書畫協會聯展\r\n2022 年 話山畫水班於 大里杙文化館 「 杙鄉情願粉墨遊」聯展 、於台中市南區區公所「林穆瑛 張美德水雙人展」\r\n2024 於臺中市大里地政事務所「華夏畫山話水班水墨畫聯展」\r\n\r\n五、展覽期間：\r\n2025/4/1 ~ 2025/6/30 08:00-17:30\r\n(配合本所辦公時間)歡迎賞析\r\n\r\n ', '臺中市大里區戶政事務所', '臺中市大里區', '2025-04-01 00:00:00', '2025-06-30 00:00:00', '大里區（臺中市）=', 24.09575742, 120.6926261, '無資料', 'https://www.hdali.taichung.gov.tw/1517312/1517322/1517323/3634696/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市大里區戶政事務所114年第2期藝文展覽', `description`='一、 一樓展覽以林穆瑛女士的作品為展出主軸林穆瑛女士在水墨畫師承陳華老師追隨古員齊老師學習流暢快速，富有動感 的行草書法。本次展覽特別搭配新春節令，展現喜氣洋洋的新春吉祥畫系列。作者從事公務工作業餘喜歡遊藝於書畫藉此滋養身心，為心靈澆灌一瓢清泉也展現在書畫的意境上；本次作品有以書為體畫為境的寫意風也有作者以簡練的筆墨來表達物象的內在精神，傳達古代文人在新春期間的深厚情懷。更有具體象徵富貴吉祥的花鳥小品，傳達作者與水墨對於自然、社會和人生的獨特理解方式 。\r\n此次展品風格形式多元，展現作者的書畫理解與創作風格配合