INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b026b32419285b7488', '2025梧棲快樂兒童創意美展_光影很有事', '光亮了，影子也登場了\r\n在圖像的舞台上\r\n光，如影隨行\r\n共同說著許多事......\r\n什麼事呢?\r\n請你一起來光影很有事', '臺中市梧棲鎮藝術文化協會', '臺中市梧棲區民生街15之77號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館梧棲親子館', 24.251815, 120.533022, '無資料', 'https://www.taichung.gov.tw/2945988/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025梧棲快樂兒童創意美展_光影很有事', `description`='光亮了，影子也登場了\r\n在圖像的舞台上\r\n光，如影隨行\r\n共同說著許多事......\r\n什麼事呢?\r\n請你一起來光影很有事', `organizer`='臺中市梧棲鎮藝術文化協會', `address`='臺中市梧棲區民生街15之77號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館梧棲親子館', `latitude`=24.251815, `longitude`=120.533022, `ticket_price`='無資料', `source_url`='https://www.taichung.gov.tw/2945988/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b226b32419285b748a', '梧童【陪我長大的親人回憶與記事】圖文創作聯展', '梧童【陪我長大的親人回憶與記事】圖文創作聯展：\r\n本次徵文展覽，請梧棲孩子們請寫/畫出，和這些感恩的親人們，相處過的難忘回憶與記事，讓天上或人間他們，在大家的文/圖作品中永遠存活，傳達久久的懷念與深深的感謝。\r\n', '臺中市立圖書館梧棲親子館', '臺中市梧棲區民生街15之77號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館梧棲親子館', 24.251815, 120.533022, '無資料', 'https://reurl.cc/EVZ91K', '[]') ON DUPLICATE KEY UPDATE `activity_name`='梧童【陪我長大的親人回憶與記事】圖文創作聯展', `description`='梧童【陪我長大的親人回憶與記事】圖文創作聯展：\r\n本次徵文展覽，請梧棲孩子們請寫/畫出，和這些感恩的親人們，相處過的難忘回憶與記事，讓天上或人間他們，在大家的文/圖作品中永遠存活，傳達久久的懷念與深深的感謝。\r\n', `organizer`='臺中市立圖書館梧棲親子館', `address`='臺中市梧棲區民生街15之77號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館梧棲親子館', `latitude`=24.251815, `longitude`=120.533022, `ticket_price`='無資料', `source_url`='https://reurl.cc/EVZ91K', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b226b32419285b748b', '【新北市立圖書館五股成功分館】114年4月份《彩虹故事屋》', '【五股成功分館】114年4月份【藝文生活圈】《彩虹故事屋》\r\n地址：新北市五股區西雲路165號4樓\r\n辦理地點：4樓故事屋\r\n電話：02-22935827\r\n\r\n-《彩虹故事屋》-\r\n§§ 歡迎闔家光臨 §§\r\n◎活動單位保有取消、變更之權利，詳情請依現場為主。\r\n◎免費入場，無須報名，禁止飲食。\r\n\r\n＊英文故事園地＊\r\n說故事日期時間 / 故事主題 / 講師(故事志工)\r\n04/05(六)14:00-15:00/Goodnight, Mr. Panda (晚安，熊貓先生) /陳沛均(故事志工)\r\n\r\n＊0-3寶寶故事園地＊\r\n說故事日期時間 / 故事主題 / 講師(故事志工)\r\n04/12(六)14:00-15:00/想點什麼菜呢 /井采苓(故事志工)\r\n\r\n＊中文故事園地＊\r\n說故事日期時間 / 故事主題 / 講師(故事志工)\r\n04/19(六)14:00-15:00/長著眼睛的火車站/我吃拉麵的時候/想要不一樣/魏文勇(故事志工)\r\n\r\n-《親子悅讀趣》(台語)-\r\n活動日期：04/26(六) 14:00-15:00\r\n中文故事 ：勇士爸爸去搶孤/林湫燕 (故事志工)＋DIY：媽媽愛心吊飾\r\n限額/ ６組親子\r\n\r\n＊勇士爸爸去搶孤＊\r\n「搶孤」是在搶什麼？為什麼在聰聰的爸爸告訴全家要在農曆七月二十九日半夜搶孤時，媽媽的臉都綠了？跟著爸爸和勇士搶孤隊的訓練過程，聰聰也開始認識了搶孤是怎麼一回事；媽媽們也轉而支持勇士爸爸們。農曆七月二十九日半夜時，盛大的搶孤活動展開了，十三支孤棧也早已矗立在廣場中央。勇士搶孤隊和家屬啦啦隊，也一同到達會場，一場精彩的搶孤活動也即將就此展開。到底聰聰的爸爸和勇士搶孤隊，能不能順利搶得順風旗呢？…...\r\n\r\n*報名請注意：\r\n1.活動前10天(04/16起)，於五股區各分館室持兒童本人借閱證借書滿5本，或於守讓堂借閱讀便利包1袋(內為5本繪本)，即可報名參加(報名成功於服務櫃臺現場加入活動LINE群組)。\r\n2.本活動為親子組活動，限親子(１大人１小孩)，若２位小孩要參加，請分別報名（才有ＤＩＹ材料喔！）。*如不需材料, 可無需報名。\r\n3.名額限６組，報名額滿為止。\r\n4.如報名後取消參加，一律不予保留資格，也不可任意自行更換參加人員。*材料包僅限借閱證本人領取。\r\n5.後補名額，一律於活動當天在FB公告，俟公告後即可攜兒童本人的新北市立圖書館借閱證，於五股成功分館現場借閱5本書籍完成，後補報名。\r\n6.每場活動後憑簽到，可參加集點活動（限國小以下並持有借閱證），集滿8點可憑集點卡至五股成功分館兌換精美小禮。\r\n7.活動單位保有取消、變更之權利，詳情請依現場為主。', '新北市立圖書館總館', '新北市五股區新北市五股區西雲路165號5樓', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '新北市立圖書館五股成功分館', 25.09614746, 121.4332139, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館五股成功分館】114年4月份《彩虹故事屋》', `description`='【五股成功分館】114年4月份【藝文生活圈】《彩虹故事屋》\r\n地址：新北市五股區西雲路165號4樓\r\n辦理地點：4樓故事屋\r\n電話：02-22935827\r\n\r\n-《彩虹故事屋》-\r\n§§ 歡迎闔家光臨 §§\r\n◎活動單位保有取消、變更之權利，詳情請依現場為主。\r\n◎免費入場，無須報名，禁止飲食。\r\n\r\n＊英文故事園地＊\r\n說故事日期時間 / 故事主題 / 講師(故事志工)\r\n04/05(六)14:00-15:00/Goodnight, Mr. Panda (晚安，熊貓先生) /陳沛均(故事志工)\r\n\r\n＊0-3寶寶故事園地＊\r\n說故事日期時間 / 故事主題 / 講師(故事志工)\r\n04/12(六)14:00-15:00/想點什麼菜呢 /井采苓(故事志工)\r\n\r\n＊中文故事園地＊\r\n說故事日期時間 / 故事主題 / 講師(故事志工)\r\n04/19(六)14:00-15:00/長著眼睛的火車站/我吃拉麵的時候/想要不一樣/魏文勇(故事志工)\r\n\r\n-《親子悅讀趣》(台語)-\r\n活動日期：04/26(六) 14:00-15:00\r\n中文故事 ：勇士爸爸去搶孤/林湫燕 (故事志工)＋DIY：媽媽愛心吊飾\r\n限額/ ６組親子\r\n\r\n＊勇士爸爸去搶孤＊\r\n「搶孤」是在搶什麼？為什麼在聰聰的爸爸告訴全家要在農曆七月二十九日半夜搶孤時，媽媽的臉都綠了？跟著爸爸和勇士搶孤隊的訓練過程，聰聰也開始認識了搶孤是怎麼一回事；媽媽們也轉而支持勇士爸爸們。農曆七月二十九日半夜時，盛大的搶孤活動展開了，十三支孤棧也早已矗立在廣場中央。勇士搶孤隊和家屬啦啦隊，也一同到達會場，一場精彩的搶孤活動也即將就此展開。到底聰聰的爸爸和勇士搶孤隊，能不能順利搶得順風旗呢？…...\r\n\r\n*報名請注意：\r\n1.活動前10天(04/16起)，於五股區各分館室持兒童本人借閱證借書滿5本，或於守讓堂借閱讀便利包1袋(內為5本繪本)，即可報名參加(報名成功於服務櫃臺現場加入活動LINE群組)。\r\n2.本活動為親子組活動，限親子(１大人１小孩)，若２位小孩要參加，請分別報名（才有ＤＩＹ材料喔！）。*如不需材料, 可無需報名。\r\n3.名額限６組，報名額滿為止。\r\n4.如報名後取消參加，一律不予保留資格，也不可任意自行更換參加人員。*材料包僅限借閱證本人領取。\r\n5.後補名額，一律於活動當天在FB公告，俟公告後即可攜兒童本人的新北市立圖書館借閱證，於五股成功分館現場借閱5本書籍完成，後補報名。\r\n6.每場活動後憑簽到，可參加集點活動（限國小以下並持有借閱證），集滿8點可憑集點卡至五股成功分館兌換精美小禮。\r\n7.活動單位保有取消、變更之權利，詳情請依現場為主。', `organizer`='新北市立圖書館總館', `address`='新北市五股區新北市五股區西雲路165號5樓', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='新北市立圖書館五股成功分館', `latitude`=25.09614746, `longitude`=121.4332139, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
