INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b226b32419285b748d', '【五股守讓堂】114年4月【閱讀書籤】以詩歌佐茶湯  書展', '主題：4月主題書展─以詩歌佐茶湯  \r\n\r\n詩歌餘韻如茶湯回甘。\r\n此時此刻，春光正好， 一手茶，品詩歌， 古今中外皆有情懷需抒發。\r\n讓我們一起循著茶香進入詩歌世界吧！。\r\n\r\n展期：114年4月1日-4月30日／開館時間\r\n\r\n地點：五股守讓堂  (三讓文房書籍僅提供館內閱讀，均不外借)\r\n【五股守讓堂】三讓文房書展區（新北市五股區新五路二段169號）洽詢電話：02-22953212', '新北市立圖書館總館', '新北市五股區新五路二段169號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '五股守讓堂', 25.09614746, 121.4332139, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【五股守讓堂】114年4月【閱讀書籤】以詩歌佐茶湯  書展', `description`='主題：4月主題書展─以詩歌佐茶湯  \r\n\r\n詩歌餘韻如茶湯回甘。\r\n此時此刻，春光正好， 一手茶，品詩歌， 古今中外皆有情懷需抒發。\r\n讓我們一起循著茶香進入詩歌世界吧！。\r\n\r\n展期：114年4月1日-4月30日／開館時間\r\n\r\n地點：五股守讓堂  (三讓文房書籍僅提供館內閱讀，均不外借)\r\n【五股守讓堂】三讓文房書展區（新北市五股區新五路二段169號）洽詢電話：02-22953212', `organizer`='新北市立圖書館總館', `address`='新北市五股區新五路二段169號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='五股守讓堂', `latitude`=25.09614746, `longitude`=121.4332139, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b326b32419285b748f', '114年第一期小蜻蜓兒童讀書會', '一、活動目的：\r\n1.為有效運用圖書館既有資源，期分館能深入社區推動閱讀，提升社區閱讀風氣。\r\n2.透過同儕學習的模式，讓兒童體會閱讀的樂趣。\r\n3.培養兒童對社區公共圖書館的瞭解與認識。\r\n二、日期-繪本書目\r\n3/29(六)-斯文豪與福爾摩沙的奇幻動物：臺灣自然探索的驚奇旅程(歷史、地理、生態跨領域學習)、台灣動物來唱歌Tâi-oân Tōng-bu̍t Lâi Chhiò-koa\r\n4/5(六)-跟著歷史名人去遊歷:愛玩大少爺郁永河遊臺灣(歷史、地理、生態跨領域學習)、你寫對台語了嗎？\r\n4/12(六)-森林裡的土壤製造機(萬物共生息/與大自然作朋友)\r\n4/19(六)-好想要回家(我們家鄉的後花園:壽山生物多樣性/動物保護以野生動物保護)、我的第一本台灣話\r\n三、活動對象：以國小3-4年級優先\r\n', '高雄市立圖書館總館', '高雄市左營區博愛三路453號', '2025-03-29 00:00:00', '2025-04-19 00:00:00', '高雄市立圖書館左新分館', 22.6783295, 120.3046289, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年第一期小蜻蜓兒童讀書會', `description`='一、活動目的：\r\n1.為有效運用圖書館既有資源，期分館能深入社區推動閱讀，提升社區閱讀風氣。\r\n2.透過同儕學習的模式，讓兒童體會閱讀的樂趣。\r\n3.培養兒童對社區公共圖書館的瞭解與認識。\r\n二、日期-繪本書目\r\n3/29(六)-斯文豪與福爾摩沙的奇幻動物：臺灣自然探索的驚奇旅程(歷史、地理、生態跨領域學習)、台灣動物來唱歌Tâi-oân Tōng-bu̍t Lâi Chhiò-koa\r\n4/5(六)-跟著歷史名人去遊歷:愛玩大少爺郁永河遊臺灣(歷史、地理、生態跨領域學習)、你寫對台語了嗎？\r\n4/12(六)-森林裡的土壤製造機(萬物共生息/與大自然作朋友)\r\n4/19(六)-好想要回家(我們家鄉的後花園:壽山生物多樣性/動物保護以野生動物保護)、我的第一本台灣話\r\n三、活動對象：以國小3-4年級優先\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市左營區博愛三路453號', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='高雄市立圖書館左新分館', `latitude`=22.6783295, `longitude`=120.3046289, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b326b32419285b7490', '114年4月三民分館Fun心聽故事活動', '孩子是精靈，故事是魔法棒，點綴孩子的心，開啟孩子的夢，透過故事媽媽的口，故事將變成幸福的種子，灑向每個角落，讓高雄變成一座開滿五彩繽紛幸福花朵的書香城市。\r\n~高雄市立圖書館各分館fun心聽故事時間於每星期五、六早上10:00及星期日下午15:00免費入場，歡迎各位小朋友踴躍參加~', '高雄市立圖書館總館', '高雄市三民區2鄰十全一路220號', '2025-04-05 00:00:00', '2025-04-27 00:00:00', '高雄市立圖書館三民分館', 22.646393, 120.306137, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年4月三民分館Fun心聽故事活動', `description`='孩子是精靈，故事是魔法棒，點綴孩子的心，開啟孩子的夢，透過故事媽媽的口，故事將變成幸福的種子，灑向每個角落，讓高雄變成一座開滿五彩繽紛幸福花朵的書香城市。\r\n~高雄市立圖書館各分館fun心聽故事時間於每星期五、六早上10:00及星期日下午15:00免費入場，歡迎各位小朋友踴躍參加~', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區2鄰十全一路220號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='高雄市立圖書館三民分館', `latitude`=22.646393, `longitude`=120.306137, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b326b32419285b7491', '汴洲太鼓研習活動', '太鼓研習活動以擊鼓為基礎，不僅僅是擊鼓的表演，還加上武術、舞蹈和配樂，形成自成一體的藝術，既有傳統鼓藝的氣勢，也有舞蹈與武術對於美的展示。', '桃園市桃園區汴洲社區發展協會', '桃園市桃園區', '2025-02-17 00:00:00', '2025-11-24 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='汴洲太鼓研習活動', `description`='太鼓研習活動以擊鼓為基礎，不僅僅是擊鼓的表演，還加上武術、舞蹈和配樂，形成自成一體的藝術，既有傳統鼓藝的氣勢，也有舞蹈與武術對於美的展示。', `organizer`='桃園市桃園區汴洲社區發展協會', `address`='桃園市桃園區', `start_date`='2025-02-17 00:00:00', `end_date`='2025-11-24 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b426b32419285b7492', '114年讀經小狀元研習活動', '本活動課程內容導讀唐詩、論語、道德經、老子等文學作品，讀經教育為華人世界最具共識的文化活動，亦是全體華夏子民應珍視、寶愛及傳承之文化寶藏。推動讀經活動雖以閱讀研習做為方法，目的是讓兒童亦動亦靜逐漸體會古文經典藝文之美來自天地萬物之中。', '桃園市桃園區瑞慶社區發展協會', '桃園市桃園區', '2025-03-19 00:00:00', '2025-10-08 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年讀經小狀元研習活動', `description`='本活動課程內容導讀唐詩、論語、道德經、老子等文學作品，讀經教育為華人世界最具共識的文化活動，亦是全體華夏子民應珍視、寶愛及傳承之文化寶藏。推動讀經活動雖以閱讀研習做為方法，目的是讓兒童亦動亦靜逐漸體會古文經典藝文之美來自天地萬物之中。', `organizer`='桃園市桃園區瑞慶社區發展協會', `address`='桃園市桃園區', `start_date`='2025-03-19 00:00:00', `end_date`='2025-10-08 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b426b32419285b7493', '北埔快樂唱歌班', '研習課程地點借用桃園區國王的城堡社區交誼廳，開放民眾自由參加。活動內容教導基礎樂理、發聲方式、如何換氣、發音咬字、抖音、顫音及真假音運用，並利用歌曲進行實練。', '桃園市桃園區北埔社區發展協會', '桃園市桃園區', '2025-01-02 00:00:00', '2025-06-19 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='北埔快樂唱歌班', `description`='研習課程地點借用桃園區國王的城堡社區交誼廳，開放民眾自由參加。活動內容教導基礎樂理、發聲方式、如何換氣、發音咬字、抖音、顫音及真假音運用，並利用歌曲進行實練。', `organizer`='桃園市桃園區北埔社區發展協會', `address`='桃園市桃園區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-06-19 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b426b32419285b7494', '綺麗國標舞研習課程', '透過系統化的教學，幫助學員掌握基本舞步、舞姿及節奏感，培養對國際標準舞（國標舞）的興趣與自信，研習課程融合了音樂、藝術、文化、社交等多種元素，能夠豐富社會文化生活，推廣藝術與美學。', '桃園市綺麗運動協會', '桃園市桃園區', '2025-01-02 00:00:00', '2025-12-18 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '每人每3個月費用+1000', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='綺麗國標舞研習課程', `description`='透過系統化的教學，幫助學員掌握基本舞步、舞姿及節奏感，培養對國際標準舞（國標舞）的興趣與自信，研習課程融合了音樂、藝術、文化、社交等多種元素，能夠豐富社會文化生活，推廣藝術與美學。', `organizer`='桃園市綺麗運動協會', `address`='桃園市桃園區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-18 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='每人每3個月費用+1000', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b426b32419285b7495', '金星社交舞蹈研習班', '課程內容結合舞蹈、音樂、社交互動的藝術活動，透過系統化的教學，幫助學員掌握基本步伐、舞姿、節奏感與舞伴溝通技巧，讓學員能在各種場合輕鬆跳舞。\r\n包括：國際標準舞、華爾滋（Waltz）、探戈（Tango）及倫巴(Rumba）、恰恰（Cha-Cha）等。', '金星舞蹈班', '桃園市桃園區', '2025-01-02 00:00:00', '2025-12-30 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '每人每3個月費用+500', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='金星社交舞蹈研習班', `description`='課程內容結合舞蹈、音樂、社交互動的藝術活動，透過系統化的教學，幫助學員掌握基本步伐、舞姿、節奏感與舞伴溝通技巧，讓學員能在各種場合輕鬆跳舞。\r\n包括：國際標準舞、華爾滋（Waltz）、探戈（Tango）及倫巴(Rumba）、恰恰（Cha-Cha）等。', `organizer`='金星舞蹈班', `address`='桃園市桃園區', `start_date`='2025-01-02 00:00:00', `end_date`='2025-12-30 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='每人每3個月費用+500', `source_url`='無資料', `image_url`='[]';
