INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b426b32419285b7497', '【新北市立圖書館三重分館】114年4月【彩虹故事屋】', '彩虹故事屋\r\n※故事繪本與時間若有更動，以活動現場為主※\r\n114年4月\r\n時間：週六下午2點-3點\r\n地點：三重分館兒童室\r\n(三重區自強路一段158號B1)\r\n \r\n\r\n04/12（六）\r\n酷老師逛動物園／賴怡璇（彩虹姐姐）\r\n腳踏車輪子／楊月雲（匠奶咪）\r\n小蠶豆的床／李心渝（星星姐姐）\r\n \r\n04/19（六）\r\n最好的復活節彩蛋／范鳳娥（玫瑰阿姨）\r\n奶茶好好喝／李怡青（QQ綠姐姐）\r\n愛唱反調的小貓熊／葉俊男（Uncle安可） \r\n \r\n04/26（六）\r\n麵包小偷：熱呼呼的麵包車／唐書惠（糖糖阿姨）\r\n神奇行李箱／趙麗芬（yoyo阿姨）\r\n廉政故事-毛毛蟲出任務／張雲賢（Apple姐姐）', '新北市立圖書館總館', '新北市三重區自強路一段158號', '2025-04-12 00:00:00', '2025-04-26 00:00:00', '新北市立圖書館三重分館', 25.06281651, 121.4870977, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三重分館】114年4月【彩虹故事屋】', `description`='彩虹故事屋\r\n※故事繪本與時間若有更動，以活動現場為主※\r\n114年4月\r\n時間：週六下午2點-3點\r\n地點：三重分館兒童室\r\n(三重區自強路一段158號B1)\r\n \r\n\r\n04/12（六）\r\n酷老師逛動物園／賴怡璇（彩虹姐姐）\r\n腳踏車輪子／楊月雲（匠奶咪）\r\n小蠶豆的床／李心渝（星星姐姐）\r\n \r\n04/19（六）\r\n最好的復活節彩蛋／范鳳娥（玫瑰阿姨）\r\n奶茶好好喝／李怡青（QQ綠姐姐）\r\n愛唱反調的小貓熊／葉俊男（Uncle安可） \r\n \r\n04/26（六）\r\n麵包小偷：熱呼呼的麵包車／唐書惠（糖糖阿姨）\r\n神奇行李箱／趙麗芬（yoyo阿姨）\r\n廉政故事-毛毛蟲出任務／張雲賢（Apple姐姐）', `organizer`='新北市立圖書館總館', `address`='新北市三重區自強路一段158號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='新北市立圖書館三重分館', `latitude`=25.06281651, `longitude`=121.4870977, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
