INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b426b32419285b749c', '兒童美術館4月說故事活動', '	兒童美術館的故事志工，在每個禮拜日及每月兩天的週三為小朋友們帶來精采的故事時間。小朋友們在半小時的活動內，不僅有故事聽、有帶動跳，有時更有簡易手作，讓大家能帶回可愛的紀念品！\r\n\r\n週三胖叔叔說故事：每月一天，第一場10點、第二場11點，為時半小時；\r\n週三阿姨說故事：每月一天，10點30分，為時半小時；\r\n週日說故事：每週日10點30分，為時半小時。', '高雄市立美術館', '高雄市鼓山區馬卡道路330號', '2025-04-02 00:00:00', '2025-04-30 00:00:00', '高雄兒童美術館', 22.6578576, 120.2828147, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='兒童美術館4月說故事活動', `description`='	兒童美術館的故事志工，在每個禮拜日及每月兩天的週三為小朋友們帶來精采的故事時間。小朋友們在半小時的活動內，不僅有故事聽、有帶動跳，有時更有簡易手作，讓大家能帶回可愛的紀念品！\r\n\r\n週三胖叔叔說故事：每月一天，第一場10點、第二場11點，為時半小時；\r\n週三阿姨說故事：每月一天，10點30分，為時半小時；\r\n週日說故事：每週日10點30分，為時半小時。', `organizer`='高雄市立美術館', `address`='高雄市鼓山區馬卡道路330號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄兒童美術館', `latitude`=22.6578576, `longitude`=120.2828147, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b426b32419285b749e', '臺中市藝術亮點-《晶圓再生》姜文如 晶圓拼貼藝術展', '藝術家姜文如以藝術喚起環保意識，為生態保育發聲，他以廢棄晶圓創作，利用馬賽克拼貼展現臺灣山林與穿山甲之美，晶圓碎片如鱗片，拼接出獨特姿態，隨光影閃爍。', '臺中市中友百貨公司', '臺中市北區三民路3段161號', '2025-03-13 00:00:00', '2025-04-21 00:00:00', '臺中中友百貨公司', 24.15863985, 120.6809521, '無資料', 'https://www.chungyo.com.tw/gallery.html?id=creativityplatform#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-《晶圓再生》姜文如 晶圓拼貼藝術展', `description`='藝術家姜文如以藝術喚起環保意識，為生態保育發聲，他以廢棄晶圓創作，利用馬賽克拼貼展現臺灣山林與穿山甲之美，晶圓碎片如鱗片，拼接出獨特姿態，隨光影閃爍。', `organizer`='臺中市中友百貨公司', `address`='臺中市北區三民路3段161號', `start_date`='2025-03-13 00:00:00', `end_date`='2025-04-21 00:00:00', `location`='臺中中友百貨公司', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://www.chungyo.com.tw/gallery.html?id=creativityplatform#', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb13b426b32419285b749f', '臺中市藝術亮點-2025朱利安．修方X閑弦室內樂集', '2024年獲得法國「藝術與文學騎士勳章」（Ordre des Arts et des Lettres）的小提琴家－朱利安．修方（Julien Chauvin），是法國知名小提琴家與指揮家，長久以來專注於古樂復興，他於2005年創立古樂團Le Cercle de l’Harmonie、並在2015年成立管弦樂團Le Concert de la Loge均為樂迷們精心呈現巴洛克時代音樂風華。2024年受國立清華大學音樂系邀請來臺舉辦大師班，並與閑弦室內樂集合作首次在臺舉辦公開演出，曲目挑選自巴洛克時期至古典時期的經典，修方不僅再現巴洛克樂章的精緻細膩，更演出其他時期的精彩曲目，向聽眾獻上一場豐富多元的音樂盛宴；2025年閑弦再度邀請大師來臺，此次將於臺北、臺中兩地演出，曲目橫跨巴洛克至浪漫時期，展現大師擅長的細膩巴洛克，亦呈現復刻古典的浪漫。', '閑弦室內樂集Cosy Chord Ensemble', '臺中市北區健行路111號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '臺中市私立新民高級中學', 24.15863985, 120.6809521, '無資料', 'https://yii.tw/events/37062', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市藝術亮點-2025朱利安．修方X閑弦室內樂集', `description`='2024年獲得法國「藝術與文學騎士勳章」（Ordre des Arts et des Lettres）的小提琴家－朱利安．修方（Julien Chauvin），是法國知名小提琴家與指揮家，長久以來專注於古樂復興，他於2005年創立古樂團Le Cercle de l’Harmonie、並在2015年成立管弦樂團Le Concert de la Loge均為樂迷們精心呈現巴洛克時代音樂風華。2024年受國立清華大學音樂系邀請來臺舉辦大師班，並與閑弦室內樂集合作首次在臺舉辦公開演出，曲目挑選自巴洛克時期至古典時期的經典，修方不僅再現巴洛克樂章的精緻細膩，更演出其他時期的精彩曲目，向聽眾獻上一場豐富多元的音樂盛宴；2025年閑弦再度邀請大師來臺，此次將於臺北、臺中兩地演出，曲目橫跨巴洛克至浪漫時期，展現大師擅長的細膩巴洛克，亦呈現復刻古典的浪漫。', `organizer`='閑弦室內樂集Cosy Chord Ensemble', `address`='臺中市北區健行路111號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺中市私立新民高級中學', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://yii.tw/events/37062', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eb8cc507f3d4433af95565', '2025苗北藝術工坊－【時尚玩生活系列】', '✧2025苗北藝術工坊 6月【時尚玩生活系列】✧\r\n\r\n本季帶來時尚玩生活系列：香水、蠟燭、咖啡體驗課程。\r\n在炎炎夏日裡找尋生活慢步調，來苗北享受一趟藝術心靈獨旅吧?\r\n\r\n06/14  ▸ 仲夏芬多精　\r\n▹▸ https://reurl.cc/qG5Ylq\r\n炎夏時節，繁忙的工作和煩亂的思緒也隨之升溫，天然植萃的芳香精華，是來自大自然的能量，也是平衡節奏、愉悅情緒、紓解煩燥的天然良方。\r\n※可攜回一瓶自己調配的香水和一張藝術家獨家授權的藝術香氛卡\r\n\r\n06/21 ▸ 冰紋藝術蠟 　\r\n▹▸ https://reurl.cc/YYv3yn\r\n融化的蠟遇上冰塊，創造出獨特的鏤空質感，點燃時，光影透過細緻的孔洞流轉，營造溫暖而夢幻的氛圍，每一顆蠟燭都是獨一無二的藝術品。\r\n※可攜回一個藝術蠟燭。(顏色不限)\r\n\r\n06/28  ▸ 咖啡漫遊記\r\n▹▸ https://reurl.cc/xN93Y5\r\n探索精品咖啡的奧秘！本課程帶您深入非洲、亞洲、中南美洲及海島四大咖啡產區，品味各區獨特風味。\r\n※可攜回老師自焙精品咖啡豆1包。(半磅)\r\n\r\n✦苗北藝術工坊，名額有限，額滿為止✦\r\n✦本期課程僅開放單人報名，無親子組呦✦', '苗栗縣苗北藝文中心', '苗栗縣苗栗縣竹南鎮公園路206號', '2025-06-14 00:00:00', '2025-06-28 00:00:00', '苗栗縣苗北藝文中心', '無資料', '無資料', '無資料', 'https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2bhRgElEGQ0QhFkRxW1UhIjglTCAFVwxJJA&nonline=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025苗北藝術工坊－【時尚玩生活系列】', `description`='✧2025苗北藝術工坊 6月【時尚玩生活系列】✧\r\n\r\n本季帶來時尚玩生活系列：香水、蠟燭、咖啡體驗課程。\r\n在炎炎夏日裡找尋生活慢步調，來苗北享受一趟藝術心靈獨旅吧?\r\n\r\n06/14  ▸ 仲夏芬多精　\r\n▹▸ https://reurl.cc/qG5Ylq\r\n炎夏時節，繁忙的工作和煩亂的思緒也隨之升溫，天然植萃的芳香精華，是來自大自然的能量，也是平衡節奏、愉悅情緒、紓解煩燥的天然良方。\r\n※可攜回一瓶自己調配的香水和一張藝術家獨家授權的藝術香氛卡\r\n\r\n06/21 ▸ 冰紋藝術蠟 　\r\n▹▸ https://reurl.cc/YYv3yn\r\n融化的蠟遇上冰塊，創造出獨特的鏤空質感，點燃時，光影透過細緻的孔洞流轉，營造溫暖而夢幻的氛圍，每一顆蠟燭都是獨一無二的藝術品。\r\n※可攜回一個藝術蠟燭。(顏色不限)\r\n\r\n06/28  ▸ 咖啡漫遊記\r\n▹▸ https://reurl.cc/xN93Y5\r\n探索精品咖啡的奧秘！本課程帶您深入非洲、亞洲、中南美洲及海島四大咖啡產區，品味各區獨特風味。\r\n※可攜回老師自焙精品咖啡豆1包。(半磅)\r\n\r\n✦苗北藝術工坊，名額有限，額滿為止✦\r\n✦本期課程僅開放單人報名，無親子組呦✦', `organizer`='苗栗縣苗北藝文中心', `address`='苗栗縣苗栗縣竹南鎮公園路206號', `start_date`='2025-06-14 00:00:00', `end_date`='2025-06-28 00:00:00', `location`='苗栗縣苗北藝文中心', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.miaobeiac.org/mod/course/index.php?REQUEST_ID=SAJTHC1UVXxKWXA2bhRgElEGQ0QhFkRxW1UhIjglTCAFVwxJJA&nonline=1', `image_url`='[]';
