INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67eba8be8f15adefa04e0c8e', '2025節慶長笛樂團音樂會─笛影輕舞的湖光傳說', '無資料', '就是愛樂管弦樂團', '臺北市中正區中山南路21-1號', '2025-06-25 00:00:00', '2025-06-25 00:00:00', '國家兩廳院演奏廳', 25.03240487, 121.5198839, '票價： 500 、1,000', 'https://www.opentix.life/event/1904351769497968640', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025節慶長笛樂團音樂會─笛影輕舞的湖光傳說', `description`='無資料', `organizer`='就是愛樂管弦樂團', `address`='臺北市中正區中山南路21-1號', `start_date`='2025-06-25 00:00:00', `end_date`='2025-06-25 00:00:00', `location`='國家兩廳院演奏廳', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='票價： 500 、1,000', `source_url`='https://www.opentix.life/event/1904351769497968640', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ebaa398f15adefa04e0c8f', '《雄心壯志》張志宇返台10週年薩克斯風獨奏會', '跨越界限的藝術，既讓經典重生，也讓未知的旋律悄然流轉——\r\n\r\n本場獨奏會中，張志宇將以獨到的音樂視野，透過精心改編與全新創作，展現薩克斯風豐富且多元的表現力。\r\n\r\n〈Passacaglia〉 賦予小提琴與中提琴二重奏經典嶄新樣貌，攜手米特薩克斯風重奏團首席 陳力鋒，透過雙高音薩克斯風交織出層次豐富的聲響。恩師 Philippe Geiss 特別為他精心改編的專屬作品 〈Sparkling Fantasy〉，炫技華麗而富含深刻音樂性，帶來震撼心靈的聆聽體驗。\r\n\r\n此外，這場演出的重要看點為 特別委託創作的全新作品《雄心壯志》由同為米特薩克斯風重奏團團員的 黃珮涵 以張志宇為演奏藍本，為他量身打造此曲，使其在高音、中音與上低音薩克斯風間自由穿梭，富含層次的音響效果與極具挑戰性的演奏技巧，展現對極限的無畏探索。\r\n\r\n音樂會吸收了改編與創作的養分，並在交融中悄然綻放，透過細緻且充滿張力的音樂語言，訴說著對音樂的熱情與希望。', 'MIT米特薩克斯風重奏團', '臺北市中正區中山南路21之1號', '2025-05-08 00:00:00', '2025-05-08 00:00:00', '國家兩廳院演奏廳', 25.03240487, 121.5198839, '$300、$500、$800、$1,000', 'https://www.opentix.life/event/1894696161913606144', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《雄心壯志》張志宇返台10週年薩克斯風獨奏會', `description`='跨越界限的藝術，既讓經典重生，也讓未知的旋律悄然流轉——\r\n\r\n本場獨奏會中，張志宇將以獨到的音樂視野，透過精心改編與全新創作，展現薩克斯風豐富且多元的表現力。\r\n\r\n〈Passacaglia〉 賦予小提琴與中提琴二重奏經典嶄新樣貌，攜手米特薩克斯風重奏團首席 陳力鋒，透過雙高音薩克斯風交織出層次豐富的聲響。恩師 Philippe Geiss 特別為他精心改編的專屬作品 〈Sparkling Fantasy〉，炫技華麗而富含深刻音樂性，帶來震撼心靈的聆聽體驗。\r\n\r\n此外，這場演出的重要看點為 特別委託創作的全新作品《雄心壯志》由同為米特薩克斯風重奏團團員的 黃珮涵 以張志宇為演奏藍本，為他量身打造此曲，使其在高音、中音與上低音薩克斯風間自由穿梭，富含層次的音響效果與極具挑戰性的演奏技巧，展現對極限的無畏探索。\r\n\r\n音樂會吸收了改編與創作的養分，並在交融中悄然綻放，透過細緻且充滿張力的音樂語言，訴說著對音樂的熱情與希望。', `organizer`='MIT米特薩克斯風重奏團', `address`='臺北市中正區中山南路21之1號', `start_date`='2025-05-08 00:00:00', `end_date`='2025-05-08 00:00:00', `location`='國家兩廳院演奏廳', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='$300、$500、$800、$1,000', `source_url`='https://www.opentix.life/event/1894696161913606144', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ebe44e8f15adefa04e0c90', '海洋碎片-李語晨攝影創作展在藝站', '展期：2025/4/5(六)-4/27(日)\r\n開幕座談會：2025/4/12(六)，2:00-4:00\r\n詩意海相遇見新竹垃圾山\r\n與談人：李語晨、戴唯峻\r\n策劃人：萬一一\r\n地點：藝站 (香山車站旁)\r\nhttps://www.facebook.com/HsinchuXiangshan/ \r\n\r\n創作理念\r\n望向大海的時候，你看見什麼？\r\n\r\n岸邊的石花菜、海面下的悠游河豚、海底的璀璨珊瑚。而在不遠的他方，有一座浮動的島逐漸壯大，滿載垃圾、纏繞海豚、攻擊海龜。載浮載沉的人造廢棄物是我們望向大海時看見、也看不見的畫面。海廢存在於此時此刻以及恆久的明天，直到人類化為塵土，他們依然相伴左右。製造、丟棄，有天我們將以粒子的身分再次相遇。\r\n\r\n《海洋碎片》是我持續進行的攝影計畫。我所拍攝看似「海洋生物」的影像，其實是垃圾的遺跡。在海洋廢物日與俱增的此時此刻，我以淨灘蒐集的物件重構海洋世界的現況。載浮載沉的廢棄物，已經成為我們的望眼所及，看著大海的同時，是否也是看著垃圾呢？\r\n\r\n藝術家簡介\r\n李語晨，1996年生，英國布萊頓大學攝影碩士畢業。喜歡攝影中的詩性，靈感來自於大自然或人與人之間的情感。影像作品反映生命的美、脆弱和複雜性。持續進行的《海洋碎片計畫》從英國漂回台灣，再從台灣漂到世界各地。\r\n\r\nFragments of the Sea - Yu-Chen Lee Solo Exhibition\r\nExhibition Dates：Sat 5 Apr - Sun 27 Apr 2025\r\nOpening Reception：Sat 12 Apr 2pm~\r\nArtist Talk：Sat 12 Apr, 2pm-4pm\r\nYu-Chen Lee, ramus\r\nCurator：YiYi Wan\r\nLocation：One Station\r\n', '藝站跨藝社', '新竹市香山區中華路五段347巷2弄1號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '藝站 One Station', 24.77104342, 120.9236727, '無資料', 'https://www.facebook.com/HsinchuXiangshan', '[]') ON DUPLICATE KEY UPDATE `activity_name`='海洋碎片-李語晨攝影創作展在藝站', `description`='展期：2025/4/5(六)-4/27(日)\r\n開幕座談會：2025/4/12(六)，2:00-4:00\r\n詩意海相遇見新竹垃圾山\r\n與談人：李語晨、戴唯峻\r\n策劃人：萬一一\r\n地點：藝站 (香山車站旁)\r\nhttps://www.facebook.com/HsinchuXiangshan/ \r\n\r\n創作理念\r\n望向大海的時候，你看見什麼？\r\n\r\n岸邊的石花菜、海面下的悠游河豚、海底的璀璨珊瑚。而在不遠的他方，有一座浮動的島逐漸壯大，滿載垃圾、纏繞海豚、攻擊海龜。載浮載沉的人造廢棄物是我們望向大海時看見、也看不見的畫面。海廢存在於此時此刻以及恆久的明天，直到人類化為塵土，他們依然相伴左右。製造、丟棄，有天我們將以粒子的身分再次相遇。\r\n\r\n《海洋碎片》是我持續進行的攝影計畫。我所拍攝看似「海洋生物」的影像，其實是垃圾的遺跡。在海洋廢物日與俱增的此時此刻，我以淨灘蒐集的物件重構海洋世界的現況。載浮載沉的廢棄物，已經成為我們的望眼所及，看著大海的同時，是否也是看著垃圾呢？\r\n\r\n藝術家簡介\r\n李語晨，1996年生，英國布萊頓大學攝影碩士畢業。喜歡攝影中的詩性，靈感來自於大自然或人與人之間的情感。影像作品反映生命的美、脆弱和複雜性。持續進行的《海洋碎片計畫》從英國漂回台灣，再從台灣漂到世界各地。\r\n\r\nFragments of the Sea - Yu-Chen Lee Solo Exhibition\r\nExhibition Dates：Sat 5 Apr - Sun 27 Apr 2025\r\nOpening Reception：Sat 12 Apr 2pm~\r\nArtist Talk：Sat 12 Apr, 2pm-4pm\r\nYu-Chen Lee, ramus\r\nCurator：YiYi Wan\r\nLocation：One Station\r\n', `organizer`='藝站跨藝社', `address`='新竹市香山區中華路五段347巷2弄1號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='藝站 One Station', `latitude`=24.77104342, `longitude`=120.9236727, `ticket_price`='無資料', `source_url`='https://www.facebook.com/HsinchuXiangshan', `image_url`='[]';
