INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec607e26b32419285b74c1', '【新北市立圖書館總館】114年04月EYE好書讀書會及口述影像分享', '早上藉由報讀新出版的雜誌文章及文學書籍，讓視障者直接跨入紙本書香的世界；下午透過口述影像讓視障者除了可以聽書，還多了可以聽電影的選擇。上下午場會依各主題討論分享，交流心靈，引導視障者追尋真理，成為生命中的同儕支持團體。\r\n場次:\r\n114年04月14日10:00-12:00及13:30-16:00\r\n114年04月28日10:00-12:00及13:30-16:00', '新北市立圖書館總館', '新北市板橋區貴興路139號', '2025-04-14 00:00:00', '2025-04-28 00:00:00', '新北市立圖書館總館', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館總館】114年04月EYE好書讀書會及口述影像分享', `description`='早上藉由報讀新出版的雜誌文章及文學書籍，讓視障者直接跨入紙本書香的世界；下午透過口述影像讓視障者除了可以聽書，還多了可以聽電影的選擇。上下午場會依各主題討論分享，交流心靈，引導視障者追尋真理，成為生命中的同儕支持團體。\r\n場次:\r\n114年04月14日10:00-12:00及13:30-16:00\r\n114年04月28日10:00-12:00及13:30-16:00', `organizer`='新北市立圖書館總館', `address`='新北市板橋區貴興路139號', `start_date`='2025-04-14 00:00:00', `end_date`='2025-04-28 00:00:00', `location`='新北市立圖書館總館', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
