INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60aa26b32419285b74c5', '旅行足跡', '吳耀中的畫作很多是旅遊寫生及拍照入畫，2016年結識國際水彩畫家劉木林老師．便經常邀約一起出遊寫生，因此此次展出個展主題：旅行足跡，便是創作的由來，今受邀台中市北區公所展出，耀中與有榮焉樂在其中，分享旅行美景敬請指教。\r\n', '臺中市北區區公所', '臺中市北區永興街301號', '2025-03-04 00:00:00', '2025-04-30 00:00:00', '臺中市北區區公所', 24.1659284, 120.6823703, '無資料', 'https://reurl.cc/G5WpmZ', '[]') ON DUPLICATE KEY UPDATE `activity_name`='旅行足跡', `description`='吳耀中的畫作很多是旅遊寫生及拍照入畫，2016年結識國際水彩畫家劉木林老師．便經常邀約一起出遊寫生，因此此次展出個展主題：旅行足跡，便是創作的由來，今受邀台中市北區公所展出，耀中與有榮焉樂在其中，分享旅行美景敬請指教。\r\n', `organizer`='臺中市北區區公所', `address`='臺中市北區永興街301號', `start_date`='2025-03-04 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市北區區公所', `latitude`=24.1659284, `longitude`=120.6823703, `ticket_price`='無資料', `source_url`='https://reurl.cc/G5WpmZ', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60af26b32419285b74c6', '【新北市立圖書館土城分館】4月影友會', '【新北市立圖書館土城分館】4月影友會\r\n地點：新北市立圖書館土城分館3樓演講廳(土城區中正路18號)\r\n時間：星期六下午14：00開始(開演前10分鐘入場)\r\n4/12拆彈倒數30分鐘98分(護)\r\n4/19戀愛中感動禁止98分(普)\r\n4/26迷霧中的孩子93分(護)\r\n時間∣ 13:00\r\n4/8(二)樂齡系列電影-金邊白樓青春夢80/普\r\n＊活動單位保有取消、變更之權利，詳情請依現場為主。\r\n＊敬請各位觀眾遵守各電影分級制度。\r\n＊免費入場，無須報名，禁止飲食。\r\n～☆歡迎闔家蒞臨觀賞☆～\r\n', '新北市立圖書館總館', '新北市土城區中正路18號7樓', '2025-04-12 00:00:00', '2025-04-27 00:00:00', '新北市立圖書館土城分館', 24.96425102, 121.445737, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館土城分館】4月影友會', `description`='【新北市立圖書館土城分館】4月影友會\r\n地點：新北市立圖書館土城分館3樓演講廳(土城區中正路18號)\r\n時間：星期六下午14：00開始(開演前10分鐘入場)\r\n4/12拆彈倒數30分鐘98分(護)\r\n4/19戀愛中感動禁止98分(普)\r\n4/26迷霧中的孩子93分(護)\r\n時間∣ 13:00\r\n4/8(二)樂齡系列電影-金邊白樓青春夢80/普\r\n＊活動單位保有取消、變更之權利，詳情請依現場為主。\r\n＊敬請各位觀眾遵守各電影分級制度。\r\n＊免費入場，無須報名，禁止飲食。\r\n～☆歡迎闔家蒞臨觀賞☆～\r\n', `organizer`='新北市立圖書館總館', `address`='新北市土城區中正路18號7樓', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='新北市立圖書館土城分館', `latitude`=24.96425102, `longitude`=121.445737, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60b226b32419285b74c7', '【新北市立圖書館貢寮分館】瘦身運動健康行主題書展', '適當運動，維持健康，腦袋思緒更清晰！ 貢寮分館4月主題書展「瘦身運動健康行」，向讀者介紹如何維持體態的書籍，不論您是對哪項運動有興趣。透過運動可以強健體能、雕塑體態、紓解壓力。歡迎來貢寮分館參觀書展獲取如何第一次瘦身就上手，促進血液循環並增進身體免疫力，透過運動釋放壓力並促進新陳代謝，讓自己有健康又美好人生。', '新北市立圖書館總館', '新北市貢寮區仁愛路79號三樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館貢寮分館', 25.02485641, 121.9182466, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館貢寮分館】瘦身運動健康行主題書展', `description`='適當運動，維持健康，腦袋思緒更清晰！ 貢寮分館4月主題書展「瘦身運動健康行」，向讀者介紹如何維持體態的書籍，不論您是對哪項運動有興趣。透過運動可以強健體能、雕塑體態、紓解壓力。歡迎來貢寮分館參觀書展獲取如何第一次瘦身就上手，促進血液循環並增進身體免疫力，透過運動釋放壓力並促進新陳代謝，讓自己有健康又美好人生。', `organizer`='新北市立圖書館總館', `address`='新北市貢寮區仁愛路79號三樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館貢寮分館', `latitude`=25.02485641, `longitude`=121.9182466, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60b326b32419285b74c8', '【新北市立圖書館新店碧潭圖書閱覽室】4月主題書展 - 「族夠精彩」', '我們生活的台灣，是一個各種族群共同生活的地方，除了原本就住在這片土地上的四大族群，現在也有越來越多的新住民來到這片土地上，每個族群都有自己的文化與習俗，生活在這片土地上我們是如何和不同族群的人相處，如何尊重彼此不同的族群差異，如何去了解不同的族群他們的語言文化與節慶，讓我們一起來了解不同族群的生活方式與文化習俗吧！', '新北市立圖書館總館', '新北市新店區新店路207號4樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館新店碧潭圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店碧潭圖書閱覽室】4月主題書展 - 「族夠精彩」', `description`='我們生活的台灣，是一個各種族群共同生活的地方，除了原本就住在這片土地上的四大族群，現在也有越來越多的新住民來到這片土地上，每個族群都有自己的文化與習俗，生活在這片土地上我們是如何和不同族群的人相處，如何尊重彼此不同的族群差異，如何去了解不同的族群他們的語言文化與節慶，讓我們一起來了解不同族群的生活方式與文化習俗吧！', `organizer`='新北市立圖書館總館', `address`='新北市新店區新店路207號4樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館新店碧潭圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60b326b32419285b74c9', '【新北市立圖書館新店福民圖書閱覽室】4月主題書展 - 「台灣多元族群歷史」', '海洋是壯闊深沉，也是自由多變的。歷史是由眾人所形構，權力者、知識者也主導歷史的記述與解釋。由各個不同書籍來看歷史，了解每個人與歷史是有機的連結，希望藉此彰顯歷史的趣味。', '新北市立圖書館總館', '新北市新店區福園街8號3樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館新店福民圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店福民圖書閱覽室】4月主題書展 - 「台灣多元族群歷史」', `description`='海洋是壯闊深沉，也是自由多變的。歷史是由眾人所形構，權力者、知識者也主導歷史的記述與解釋。由各個不同書籍來看歷史，了解每個人與歷史是有機的連結，希望藉此彰顯歷史的趣味。', `organizer`='新北市立圖書館總館', `address`='新北市新店區福園街8號3樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館新店福民圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
