INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60bd26b32419285b74ce', '【新北市立圖書館鶯歌分館】114年4月彩虹故事屋 ', '【鶯歌分館】114年4月彩虹故事屋\r\n\r\n館別:新北市立圖書館【鶯歌分館】\r\n地址:鶯歌區中山路150號/B1 兒童室\r\n電話：26780219#10\r\n時間：09:30-10:30    \r\n\r\n活動場次:\r\n4/12(六) 《你真的很棒》&《花貓與黑貓》陳淑慧老師\r\n4/19(六) 《真是太過分了》王淑青老師\r\n4/26(六)《壞皇后變美大作戰》何素娟老師\r\n\r\n希望藉由繪本來為孩子說故事，啟發孩子的語言與學習興趣，開展孩子的想像與創造力，以及學習情緒的抒發、喜歡閱讀等，不但能在親子間建立良好的共讀習慣，也能推動更美好的書香環境！\r\n\r\n了解更多活動相關訊息歡迎加入【鶯歌閱讀活動推廣】平台!\r\n\r\n**活動單位保有取消、變更之權利，詳情請依現場為主。', '新北市立圖書館總館', '新北市鶯歌區中山路150號B1至1樓及3至5樓', '2025-04-12 00:00:00', '2025-04-26 00:00:00', '新北市立圖書館鶯歌分館', 24.9566258, 121.3466269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館鶯歌分館】114年4月彩虹故事屋 ', `description`='【鶯歌分館】114年4月彩虹故事屋\r\n\r\n館別:新北市立圖書館【鶯歌分館】\r\n地址:鶯歌區中山路150號/B1 兒童室\r\n電話：26780219#10\r\n時間：09:30-10:30    \r\n\r\n活動場次:\r\n4/12(六) 《你真的很棒》&《花貓與黑貓》陳淑慧老師\r\n4/19(六) 《真是太過分了》王淑青老師\r\n4/26(六)《壞皇后變美大作戰》何素娟老師\r\n\r\n希望藉由繪本來為孩子說故事，啟發孩子的語言與學習興趣，開展孩子的想像與創造力，以及學習情緒的抒發、喜歡閱讀等，不但能在親子間建立良好的共讀習慣，也能推動更美好的書香環境！\r\n\r\n了解更多活動相關訊息歡迎加入【鶯歌閱讀活動推廣】平台!\r\n\r\n**活動單位保有取消、變更之權利，詳情請依現場為主。', `organizer`='新北市立圖書館總館', `address`='新北市鶯歌區中山路150號B1至1樓及3至5樓', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='新北市立圖書館鶯歌分館', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60bd26b32419285b74cf', '【新北市立圖書館鶯歌分館】114年4月假日瘋電影 ', '【鶯歌分館】114年4月假日瘋電影\r\n\r\n承辦館別：新北市立圖書館鶯歌分館\r\n地址：鶯歌區中山路150號/B1 故事劇場\r\n電話：26780219#10\r\n時間：每周日14:00-16:00\r\n\r\n04/06［日］*汪汪隊立大功 : 超級大電影  ( 普 ) 87分\r\n04/13［日］*名偵探柯南 : 紺青之拳 ( 普 ) 109分\r\n04/20［日］*喵喵博物館 ( 普 ) 80分 \r\n04/27［日］科學少女 = S-Girl ( 普 ) 108分\r\n\r\n希望經由影片欣賞，滿足觀賞民眾休閒娛樂的需求，並經由影片深入淺出的表演方式，給予民眾不同於日常生活領域的知識與體驗，歡迎有興趣的讀者踴躍參加。\r\n\r\n※播放影片與時間若有更動，以活動現場公告為主，不便之處，敬請見諒。', '新北市立圖書館總館', '新北市鶯歌區中山路150號B1至1樓及3至5樓', '2025-04-06 00:00:00', '2025-04-27 00:00:00', '新北市立圖書館鶯歌分館', 24.9566258, 121.3466269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館鶯歌分館】114年4月假日瘋電影 ', `description`='【鶯歌分館】114年4月假日瘋電影\r\n\r\n承辦館別：新北市立圖書館鶯歌分館\r\n地址：鶯歌區中山路150號/B1 故事劇場\r\n電話：26780219#10\r\n時間：每周日14:00-16:00\r\n\r\n04/06［日］*汪汪隊立大功 : 超級大電影  ( 普 ) 87分\r\n04/13［日］*名偵探柯南 : 紺青之拳 ( 普 ) 109分\r\n04/20［日］*喵喵博物館 ( 普 ) 80分 \r\n04/27［日］科學少女 = S-Girl ( 普 ) 108分\r\n\r\n希望經由影片欣賞，滿足觀賞民眾休閒娛樂的需求，並經由影片深入淺出的表演方式，給予民眾不同於日常生活領域的知識與體驗，歡迎有興趣的讀者踴躍參加。\r\n\r\n※播放影片與時間若有更動，以活動現場公告為主，不便之處，敬請見諒。', `organizer`='新北市立圖書館總館', `address`='新北市鶯歌區中山路150號B1至1樓及3至5樓', `start_date`='2025-04-06 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='新北市立圖書館鶯歌分館', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
