INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60c226b32419285b74d3', '【新北市立圖書館雙溪分館】114年4月影友會', '114年4月週末電影\r\n4/05(六) 我的最後秘密(普)90分\r\n4/12(六) 幸福來訪時(護)104分\r\n4/19(六) 法外見真情(護)102分\r\n4/26(六) 不花錢過生活(普)52分\r\n\r\n＊活動開始逾20分鐘如無讀者到場，本館保留取消活動權利\r\n＊播放影片與時間若有更動，以活動現場公告為主。\r\n＊敬請各位觀眾遵守各電影分級制度。\r\n＊免費入場，無須報名，禁止飲食。\r\n～☆歡迎闔家蒞臨觀賞☆～\r\n', '新北市立圖書館總館', '新北市雙溪區太平路50號3樓', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '新北市立圖書館雙溪分館', 24.99698394, 121.8329822, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館雙溪分館】114年4月影友會', `description`='114年4月週末電影\r\n4/05(六) 我的最後秘密(普)90分\r\n4/12(六) 幸福來訪時(護)104分\r\n4/19(六) 法外見真情(護)102分\r\n4/26(六) 不花錢過生活(普)52分\r\n\r\n＊活動開始逾20分鐘如無讀者到場，本館保留取消活動權利\r\n＊播放影片與時間若有更動，以活動現場公告為主。\r\n＊敬請各位觀眾遵守各電影分級制度。\r\n＊免費入場，無須報名，禁止飲食。\r\n～☆歡迎闔家蒞臨觀賞☆～\r\n', `organizer`='新北市立圖書館總館', `address`='新北市雙溪區太平路50號3樓', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='新北市立圖書館雙溪分館', `latitude`=24.99698394, `longitude`=121.8329822, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60c326b32419285b74d4', '【中市圖沙鹿深波分館】4月主題書展(2025/04–5場) ', '4月主題書展\r\n★流域生態兒童書展\r\n搭配4/22世界地球日，深波圖書館與荒野保護協會臺中分會合作規劃溪流生態書展\r\n展示時間：2025/04/01(二)-2025/04/30(三)\r\n展示地點：1樓兒童書展區\r\n\r\n★「推理小說」書展\r\n展出經典推理小說，包括阿嘉莎．克里絲蒂、柯南．道爾、愛倫．坡......等等知名作家作品。\r\n展示時間：2025/04/01(二)-2025/04/30(三)\r\n展示地點：1樓主題書展區\r\n\r\n★家庭教育圖書角—數位教養\r\n113年度臺中市家庭教育與臺中市立圖書館沙鹿深波圖書館全台首創「家庭教育圖書角」今年再度再度升級，以數位教養相關書籍及介紹，邀請沙鹿在地藝術家林庭老師手繪製輸出物，及專家諮詢委員語錄，並由弘光科技大學多媒體遊戲發展與應用系劉明昆副教授設計AR互動體驗遊戲，讓市民透過多元管道深入了解數位世界的各種議題，幫助市民家人提升數位識讀能力，確保全家大小都能安全、自信地運用科技，迎接未來挑戰。\r\n展示時間：2025/04/01(二)-2025/04/30(三)\r\n展示地點：2樓家庭教育圖書角\r\n\r\n★「親近文學」書展\r\n本分館藉由一系列新到圖書的展示，來與讀者分享親近文學的感動及心靈洗滌的重要。\r\n展示時間：2025/04/01(二)-2025/04/30(三)\r\n展示地點：沙鹿深波分館1樓新書書展區\r\n\r\n★「情緒療癒」主題書展\r\n展示有助放鬆身心及情緒療癒圖書，如心理勵志、哲學、手作、烹飪、園藝、旅行、運動……等相關書籍開放讀者閱覽、借閱，透過療癒閱讀，讓書成為每個人最好的朋友，協助達到情緒療癒效果。\r\n展示時間：2025/04/01(二)-2025/04/30(三)\r\n展示地點：沙鹿深波2樓開架閱覽區 ', '臺中市立圖書館沙鹿深波分館', '臺中市沙鹿區鎮南路二段 488號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館沙鹿深波分館', 24.23425212, 120.5838628, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖沙鹿深波分館】4月主題書展(2025/04–5場) ', `description`='4月主題書展\r\n★流域生態兒童書展\r\n搭配4/22世界地球日，深波圖書館與荒野保護協會臺中分會合作規劃溪流生態書展\r\n展示時間：2025/04/01(二)-2025/04/30(三)\r\n展示地點：1樓兒童書展區\r\n\r\n★「推理小說」書展\r\n展出經典推理小說，包括阿嘉莎．克里絲蒂、柯南．道爾、愛倫．坡......等等知名作家作品。\r\n展示時間：2025/04/01(二)-2025/04/30(三)\r\n展示地點：1樓主題書展區\r\n\r\n★家庭教育圖書角—數位教養\r\n113年度臺中市家庭教育與臺中市立圖書館沙鹿深波圖書館全台首創「家庭教育圖書角」今年再度再度升級，以數位教養相關書籍及介紹，邀請沙鹿在地藝術家林庭老師手繪製輸出物，及專家諮詢委員語錄，並由弘光科技大學多媒體遊戲發展與應用系劉明昆副教授設計AR互動體驗遊戲，讓市民透過多元管道深入了解數位世界的各種議題，幫助市民家人提升數位識讀能力，確保全家大小都能安全、自信地運用科技，迎接未來挑戰。\r\n展示時間：2025/04/01(二)-2025/04/30(三)\r\n展示地點：2樓家庭教育圖書角\r\n\r\n★「親近文學」書展\r\n本分館藉由一系列新到圖書的展示，來與讀者分享親近文學的感動及心靈洗滌的重要。\r\n展示時間：2025/04/01(二)-2025/04/30(三)\r\n展示地點：沙鹿深波分館1樓新書書展區\r\n\r\n★「情緒療癒」主題書展\r\n展示有助放鬆身心及情緒療癒圖書，如心理勵志、哲學、手作、烹飪、園藝、旅行、運動……等相關書籍開放讀者閱覽、借閱，透過療癒閱讀，讓書成為每個人最好的朋友，協助達到情緒療癒效果。\r\n展示時間：2025/04/01(二)-2025/04/30(三)\r\n展示地點：沙鹿深波2樓開架閱覽區 ', `organizer`='臺中市立圖書館沙鹿深波分館', `address`='臺中市沙鹿區鎮南路二段 488號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館沙鹿深波分館', `latitude`=24.23425212, `longitude`=120.5838628, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60c426b32419285b74d5', '【中市圖沙鹿深波分館】4月飛揚書香音樂會 ', '4月飛揚書香音樂會 \r\n飛揚書香音樂會 報名開始！！🎵\r\n💥4月份飛揚書香音樂會報名來囉！\r\n只要會樂器就能報名喔！\r\n🔥歡迎來演奏出屬於你悅耳的曲子🔥\r\n⏰時間:114/4/20(日) 9:30\r\n🏫地點:沙鹿深波分館 B1多功能活動室\r\n👉報名連結 :https://pse.is/79v6ew\r\n    (曲目務必請確認後再填寫)\r\n‼️注意事項：\r\n1.如填完表單發現資料有誤，請以私訊臉書修改，勿再重填一次表單。\r\n2.作業流程關係表演前二週將無法再更改曲目，敬請見諒。\r\n3.表演者限演出一次合奏或獨奏，每次演奏時間在5分鐘以內。\r\n4.填寫資料、曲目時請完整填寫，事後填寫將無法受理。\r\n5.填完表單即報名成功。\r\n💥名額有限，歡迎報名💥', '臺中市立圖書館沙鹿深波分館', '臺中市沙鹿區鎮南路二段 488號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '臺中市立圖書館沙鹿深波分館', 24.23425212, 120.5838628, '無資料', 'https://www.library.taichung.gov.tw/public/activity2/index-1.asp?Parser=99,20,697,50,,,26369,,,,,42', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖沙鹿深波分館】4月飛揚書香音樂會 ', `description`='4月飛揚書香音樂會 \r\n飛揚書香音樂會 報名開始！！🎵\r\n💥4月份飛揚書香音樂會報名來囉！\r\n只要會樂器就能報名喔！\r\n🔥歡迎來演奏出屬於你悅耳的曲子🔥\r\n⏰時間:114/4/20(日) 9:30\r\n🏫地點:沙鹿深波分館 B1多功能活動室\r\n👉報名連結 :https://pse.is/79v6ew\r\n    (曲目務必請確認後再填寫)\r\n‼️注意事項：\r\n1.如填完表單發現資料有誤，請以私訊臉書修改，勿再重填一次表單。\r\n2.作業流程關係表演前二週將無法再更改曲目，敬請見諒。\r\n3.表演者限演出一次合奏或獨奏，每次演奏時間在5分鐘以內。\r\n4.填寫資料、曲目時請完整填寫，事後填寫將無法受理。\r\n5.填完表單即報名成功。\r\n💥名額有限，歡迎報名💥', `organizer`='臺中市立圖書館沙鹿深波分館', `address`='臺中市沙鹿區鎮南路二段 488號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺中市立圖書館沙鹿深波分館', `latitude`=24.23425212, `longitude`=120.5838628, `ticket_price`='無資料', `source_url`='https://www.library.taichung.gov.tw/public/activity2/index-1.asp?Parser=99,20,697,50,,,26369,,,,,42', `image_url`='[]';
