INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60cb26b32419285b74db', '2025藝術行政與管理研討會《藝起走，更長‧遠》', '隨著全球化與科技加速發展，藝術在探索社會文化認同、跨文化交流以及反映時代脈動時，皆有著不可或缺的地位。\r\n這次，我們從永續出發，探討藝術在社會中的能量，讓藝術與社會發展出緊密的關係，並藉由持續對話與思辯，創造出多元文化共存的人文生態\r\n2025藝術行政與管理研討會《藝起走，更長．遠》將帶來精采的專題演講與論文發表，邀請關心藝術行政與管理議題的你／妳「藝」起參加，共同發掘藝術「永」流的「續」航力。', '國立臺北藝術大學', '臺北市北投區學園路1號', '2025-05-09 00:00:00', '2025-05-09 00:00:00', '國立臺北藝術大學', 25.1480682, 121.5177992, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025藝術行政與管理研討會《藝起走，更長‧遠》', `description`='隨著全球化與科技加速發展，藝術在探索社會文化認同、跨文化交流以及反映時代脈動時，皆有著不可或缺的地位。\r\n這次，我們從永續出發，探討藝術在社會中的能量，讓藝術與社會發展出緊密的關係，並藉由持續對話與思辯，創造出多元文化共存的人文生態\r\n2025藝術行政與管理研討會《藝起走，更長．遠》將帶來精采的專題演講與論文發表，邀請關心藝術行政與管理議題的你／妳「藝」起參加，共同發掘藝術「永」流的「續」航力。', `organizer`='國立臺北藝術大學', `address`='臺北市北投區學園路1號', `start_date`='2025-05-09 00:00:00', `end_date`='2025-05-09 00:00:00', `location`='國立臺北藝術大學', `latitude`=25.1480682, `longitude`=121.5177992, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
