INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60cd26b32419285b74dd', '微景之韻—多肉植物的寧靜角落 看展覽', '展覽透過創意組盆、自然造景，展現多肉植物的生態智慧、美學魅力與永續潛能。多肉植物為根、莖、葉具儲水構造的多年生植物，能在乾旱環境中存活。其外型多變、色彩繽紛，兼具觀賞性與療癒感，深受都市人喜愛。\r\n此次展覽以「時光凝萃的綠意」、「綠意交織的微景之韻」、「與自然共舞的綠色詩篇」、「舊物新生的時光再造」四大主題呈現，展出仙人掌科、景天科、大戟科等多樣品種，並結合藝術設計與生活美學。\r\n邀請大家走入植物園，感受自然之美與療育能量。', '國立自然科學博物館', '臺中市北區館前路1號', '2025-03-28 00:00:00', '2025-06-01 00:00:00', '國立自然科學博物館', 24.15863985, 120.6809521, '植物園溫室學生團體+10;植物園溫室全票+20;科學中心全票+20;921地震園區團體優+30;921地震園區全票+50;立體劇場學生團體+30;立體劇場一般團體+50;太空劇場學生團體+50;展示場學生團體+50;展示場一般團體+70;太空劇場一般團體+70;立體劇場全票+70;太空劇場全票+100;展示場全票+100', 'https://www.nmns.edu.tw/ch/exhibitions/special-exhibitions/Exhibition-000558/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='微景之韻—多肉植物的寧靜角落 看展覽', `description`='展覽透過創意組盆、自然造景，展現多肉植物的生態智慧、美學魅力與永續潛能。多肉植物為根、莖、葉具儲水構造的多年生植物，能在乾旱環境中存活。其外型多變、色彩繽紛，兼具觀賞性與療癒感，深受都市人喜愛。\r\n此次展覽以「時光凝萃的綠意」、「綠意交織的微景之韻」、「與自然共舞的綠色詩篇」、「舊物新生的時光再造」四大主題呈現，展出仙人掌科、景天科、大戟科等多樣品種，並結合藝術設計與生活美學。\r\n邀請大家走入植物園，感受自然之美與療育能量。', `organizer`='國立自然科學博物館', `address`='臺中市北區館前路1號', `start_date`='2025-03-28 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='國立自然科學博物館', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='植物園溫室學生團體+10;植物園溫室全票+20;科學中心全票+20;921地震園區團體優+30;921地震園區全票+50;立體劇場學生團體+30;立體劇場一般團體+50;太空劇場學生團體+50;展示場學生團體+50;展示場一般團體+70;太空劇場一般團體+70;立體劇場全票+70;太空劇場全票+100;展示場全票+100', `source_url`='https://www.nmns.edu.tw/ch/exhibitions/special-exhibitions/Exhibition-000558/', `image_url`='[]';
