INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60cf26b32419285b74df', '中區分館-英文說故事&新住民(泰國)母語說故事&臺語說故事(4月3場)', '親子共讀不僅可以培養小孩閱讀習慣、提高小孩閱讀興趣。藉由”共讀”陪伴，增進小孩和父母的親密關係。藉由說繪本故事，帶領小朋友一起進入故事的小天地。\r\n報名方式：採臨櫃或電洽服務專線\r\n\r\n【英文說故事】\r\n講師：吳明惠老師\r\n故事名稱：《Trash Truck》\r\n日期：2025/4/12(六)\r\n時間：上午10:30~11:30\r\n\r\n【新住民(泰國)母語說故事】\r\n講師：張郁馨老師(泰國)\r\n故事名稱：《食物魔法：轉化食物〜胡蘿蔔》\r\n日期：2025/4/19(六)\r\n時間：上午10:30~11:30\r\n\r\n【臺語說故事】\r\n講師：蘋果姐姐\r\n故事名稱：《感冒的魚》\r\n日期：2025/4/26(六)\r\n時間：上午10:30~11:30', '臺中市立圖書館中區分館', '臺中市中區成功路300號7樓', '2025-04-12 00:00:00', '2025-04-26 00:00:00', '臺中市立圖書館中區分館', 24.14168566, 120.680598, '無資料', 'https://reurl.cc/9Dr8vY  ；  https://reurl.cc/xNGqpZ  ；  https://reurl.cc/eMEYGK', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中區分館-英文說故事&新住民(泰國)母語說故事&臺語說故事(4月3場)', `description`='親子共讀不僅可以培養小孩閱讀習慣、提高小孩閱讀興趣。藉由”共讀”陪伴，增進小孩和父母的親密關係。藉由說繪本故事，帶領小朋友一起進入故事的小天地。\r\n報名方式：採臨櫃或電洽服務專線\r\n\r\n【英文說故事】\r\n講師：吳明惠老師\r\n故事名稱：《Trash Truck》\r\n日期：2025/4/12(六)\r\n時間：上午10:30~11:30\r\n\r\n【新住民(泰國)母語說故事】\r\n講師：張郁馨老師(泰國)\r\n故事名稱：《食物魔法：轉化食物〜胡蘿蔔》\r\n日期：2025/4/19(六)\r\n時間：上午10:30~11:30\r\n\r\n【臺語說故事】\r\n講師：蘋果姐姐\r\n故事名稱：《感冒的魚》\r\n日期：2025/4/26(六)\r\n時間：上午10:30~11:30', `organizer`='臺中市立圖書館中區分館', `address`='臺中市中區成功路300號7樓', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='臺中市立圖書館中區分館', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='https://reurl.cc/9Dr8vY  ；  https://reurl.cc/xNGqpZ  ；  https://reurl.cc/eMEYGK', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60cf26b32419285b74e1', '魔法故事屋-4月(2場)', '時間:周三10:00-11:00           \r\n地點:2樓嬰幼兒區               \r\n內容:                        \r\n4/16【運動吧!豬國王】                              大意：美食，讓國王腰圍變粗，更糟的是，一覺醒來，國王長了條豬尾巴！有特效藥可以救國王嗎？其實答案並不難─就是運動！運動量不足，是目前國人健康的一大隱憂，因此從小培養孩子的運動習慣，是刻不容緩的事。除了故事的引導，在書中我們也設計「我的骨骼」、「骨頭一級棒」的延伸課程，讓孩子藉由了解人體骨骼的構造，進而建立定時運動的生活好習慣喔！                       \r\n4/30【帶著獅子去探險】            \r\n大意：一個關於探索與成長的美好故事☆在同一片草地上，詩詩在這一頭出發，想要尋找自己的寵物，獅子在另一頭出發，想要尋找自己的寵物。他們的目標一致，遇上了彼此，詩詩看到獅子，獅子也看到詩詩。他們爭執著，他們都說：「你才是我的寵物！」還....', '臺中市立圖書館梧棲分館', '臺中市梧棲區雲集街72號', '2025-04-16 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館梧棲分館', 24.24552431, 120.5301259, '無資料', 'https://reurl.cc/knLlbr', '[]') ON DUPLICATE KEY UPDATE `activity_name`='魔法故事屋-4月(2場)', `description`='時間:周三10:00-11:00           \r\n地點:2樓嬰幼兒區               \r\n內容:                        \r\n4/16【運動吧!豬國王】                              大意：美食，讓國王腰圍變粗，更糟的是，一覺醒來，國王長了條豬尾巴！有特效藥可以救國王嗎？其實答案並不難─就是運動！運動量不足，是目前國人健康的一大隱憂，因此從小培養孩子的運動習慣，是刻不容緩的事。除了故事的引導，在書中我們也設計「我的骨骼」、「骨頭一級棒」的延伸課程，讓孩子藉由了解人體骨骼的構造，進而建立定時運動的生活好習慣喔！                       \r\n4/30【帶著獅子去探險】            \r\n大意：一個關於探索與成長的美好故事☆在同一片草地上，詩詩在這一頭出發，想要尋找自己的寵物，獅子在另一頭出發，想要尋找自己的寵物。他們的目標一致，遇上了彼此，詩詩看到獅子，獅子也看到詩詩。他們爭執著，他們都說：「你才是我的寵物！」還....', `organizer`='臺中市立圖書館梧棲分館', `address`='臺中市梧棲區雲集街72號', `start_date`='2025-04-16 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館梧棲分館', `latitude`=24.24552431, `longitude`=120.5301259, `ticket_price`='無資料', `source_url`='https://reurl.cc/knLlbr', `image_url`='[]';
