INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d026b32419285b74e5', '「咖波帶你遊中市圖」特色書展', '時間：4/22-4/30\r\n內容：配合2025世界閱讀日系列活動\r\n書展方向本次「咖波帶你遊中市圖」特色書展，主要書籍方向以圖文書及臺語圖文書為主，帶給您滿滿的療癒感！\r\n將串聯中市圖各分館，讓您不管到哪一個分館都能感受到該分館的特色以外，還能常常看到咖波呦！\r\n', '臺中市立圖書館梧棲分館', '臺中市梧棲區雲集街72號', '2025-04-22 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館梧棲分館', 24.24552431, 120.5301259, '無資料', 'https://reurl.cc/1Ko1RW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「咖波帶你遊中市圖」特色書展', `description`='時間：4/22-4/30\r\n內容：配合2025世界閱讀日系列活動\r\n書展方向本次「咖波帶你遊中市圖」特色書展，主要書籍方向以圖文書及臺語圖文書為主，帶給您滿滿的療癒感！\r\n將串聯中市圖各分館，讓您不管到哪一個分館都能感受到該分館的特色以外，還能常常看到咖波呦！\r\n', `organizer`='臺中市立圖書館梧棲分館', `address`='臺中市梧棲區雲集街72號', `start_date`='2025-04-22 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館梧棲分館', `latitude`=24.24552431, `longitude`=120.5301259, `ticket_price`='無資料', `source_url`='https://reurl.cc/1Ko1RW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d126b32419285b74e8', '《巫頂看世界》', '由巫頂帶領大小朋友進行「古文明大遊行」穿越時空到印度、埃及兩大古文明；到中美洲的貝里斯森林聽「牛蛙愛唱歌」；攜手為「海底世界運動會」馬里亞納海溝的魚群加油；最後巫頂要說「環遊世界真奇妙」，一起踏上巫頂的奇幻旅程吧！', '臺北市政府文化局', '臺北市內湖區', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '內湖區（臺北市）=', 25.08370623, 121.5923828, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《巫頂看世界》', `description`='由巫頂帶領大小朋友進行「古文明大遊行」穿越時空到印度、埃及兩大古文明；到中美洲的貝里斯森林聽「牛蛙愛唱歌」；攜手為「海底世界運動會」馬里亞納海溝的魚群加油；最後巫頂要說「環遊世界真奇妙」，一起踏上巫頂的奇幻旅程吧！', `organizer`='臺北市政府文化局', `address`='臺北市內湖區', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='內湖區（臺北市）=', `latitude`=25.08370623, `longitude`=121.5923828, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d126b32419285b74e9', '《黃金海底城》', '原本乾淨明亮的「黃金海底城」，正開心的準備歡迎新生珊瑚寶寶的到來。這時，破壞環境的油怪們趁虛而入，並拐騙小海星和他們演出一場「拯救海底城」的戲碼以引起其它人的寵愛，而油怪們真正的目的卻是汙染整座「黃金海底城」……\r\n大家要如何保護海洋生態呢?', '臺北市政府文化局', '臺北市中山區', '2025-04-25 00:00:00', '2025-04-25 00:00:00', '中山區（臺北市）=', 25.06969917, 121.5381597, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《黃金海底城》', `description`='原本乾淨明亮的「黃金海底城」，正開心的準備歡迎新生珊瑚寶寶的到來。這時，破壞環境的油怪們趁虛而入，並拐騙小海星和他們演出一場「拯救海底城」的戲碼以引起其它人的寵愛，而油怪們真正的目的卻是汙染整座「黃金海底城」……\r\n大家要如何保護海洋生態呢?', `organizer`='臺北市政府文化局', `address`='臺北市中山區', `start_date`='2025-04-25 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='中山區（臺北市）=', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d126b32419285b74ea', '《藝起瘋百戲》', '「百戲」融合中華文化藝術與臺灣傳藝精華，透過雜技、武術、幻術與民間歌舞等形式，巧妙結合傳統與現代藝術。特邀「藝響台灣劇團」呈現大型鼓曲藝陣，「特技空間」帶來驚險幻術與雜技，泡泡藝術師李孟修與世界金獎卓家宏光之扯鈴，全方位展現「東方百老匯」的風采與創新魅力，體現出臺灣特色，中華文化藝術之美。', '臺北市政府文化局', '臺北市大安區', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '大安區（臺北市）=', 25.02677012, 121.5434446, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《藝起瘋百戲》', `description`='「百戲」融合中華文化藝術與臺灣傳藝精華，透過雜技、武術、幻術與民間歌舞等形式，巧妙結合傳統與現代藝術。特邀「藝響台灣劇團」呈現大型鼓曲藝陣，「特技空間」帶來驚險幻術與雜技，泡泡藝術師李孟修與世界金獎卓家宏光之扯鈴，全方位展現「東方百老匯」的風采與創新魅力，體現出臺灣特色，中華文化藝術之美。', `organizer`='臺北市政府文化局', `address`='臺北市大安區', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='大安區（臺北市）=', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d126b32419285b74ec', '《龍鳳情緣》', '《龍鳳情緣》是唐美雲歌仔戲團成立後的第二檔年度大戲，是一齣極具傳承價值的經典作品，宛如歌仔戲版本的《羅馬假期》，講述一位公主出宮追尋理想，最後有情人終成眷屬的故事。而每當老故事遇到新生代，總能在唱唸作打中迸發出嶄新的靈魂與生命力。', '臺北市藝文推廣處', '臺北市大同區迪化街1段21號', '2025-04-19 00:00:00', '2025-04-20 00:00:00', '臺北市藝文推廣處-大稻埕戲苑', 25.06342433, 121.5130417, '/+300;/+600;/+900;/+1200;/+1500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《龍鳳情緣》', `description`='《龍鳳情緣》是唐美雲歌仔戲團成立後的第二檔年度大戲，是一齣極具傳承價值的經典作品，宛如歌仔戲版本的《羅馬假期》，講述一位公主出宮追尋理想，最後有情人終成眷屬的故事。而每當老故事遇到新生代，總能在唱唸作打中迸發出嶄新的靈魂與生命力。', `organizer`='臺北市藝文推廣處', `address`='臺北市大同區迪化街1段21號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺北市藝文推廣處-大稻埕戲苑', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='/+300;/+600;/+900;/+1200;/+1500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d126b32419285b74ed', '《洛陽橋》', '宋朝時，泉州有洛陽江每每有渡船翻落江中，人命損失。\r\n有蔡襄，承母命立志登仕途，建橋可造福鄉里。\r\n觀音菩薩慈悲，變美人坐綵船，吸引群眾丟錢，募資。\r\n而呂洞賓遊戲人間，開玩笑助賣菜小販，擲中。\r\n上帝公收伏作亂的龜蛇二將，果然洛陽橋順利完工。', '臺北市藝文推廣處', '臺北市大同區迪化街1段21號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '臺北市藝文推廣處-大稻埕戲苑', 25.06342433, 121.5130417, '/+100', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《洛陽橋》', `description`='宋朝時，泉州有洛陽江每每有渡船翻落江中，人命損失。\r\n有蔡襄，承母命立志登仕途，建橋可造福鄉里。\r\n觀音菩薩慈悲，變美人坐綵船，吸引群眾丟錢，募資。\r\n而呂洞賓遊戲人間，開玩笑助賣菜小販，擲中。\r\n上帝公收伏作亂的龜蛇二將，果然洛陽橋順利完工。', `organizer`='臺北市藝文推廣處', `address`='臺北市大同區迪化街1段21號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='臺北市藝文推廣處-大稻埕戲苑', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='/+100', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d226b32419285b74ee', '《叱吒風雲-新哪吒》', '哪吒靈珠轉世，身負使命至凡間，對陳塘關是吉還是兇？\r\n學藝下山後的哪吒，秉持著斬妖除魔的正義，一心協助父親李靖收服妖魔，殊不知不懂得區分善惡，造成陳塘大亂。\r\n哪吒無意間到了東海遇見虛弱且被欺侮的龍三太子敖丙，哪吒相救並且同情敖丙的處境，展開人與妖怪的友誼，本以為這段友情會為陳塘關帶來祥瑞，誰知道竟然是一場人、妖、魔三界惡戰的開始……', '金鷹閣電視木偶劇團', '臺北市大同區迪化街1段21號', '2025-04-26 00:00:00', '2025-04-27 00:00:00', '臺北市藝文推廣處-大稻埕戲苑', 25.06342433, 121.5130417, '/+300;/+500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《叱吒風雲-新哪吒》', `description`='哪吒靈珠轉世，身負使命至凡間，對陳塘關是吉還是兇？\r\n學藝下山後的哪吒，秉持著斬妖除魔的正義，一心協助父親李靖收服妖魔，殊不知不懂得區分善惡，造成陳塘大亂。\r\n哪吒無意間到了東海遇見虛弱且被欺侮的龍三太子敖丙，哪吒相救並且同情敖丙的處境，展開人與妖怪的友誼，本以為這段友情會為陳塘關帶來祥瑞，誰知道竟然是一場人、妖、魔三界惡戰的開始……', `organizer`='金鷹閣電視木偶劇團', `address`='臺北市大同區迪化街1段21號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺北市藝文推廣處-大稻埕戲苑', `latitude`=25.06342433, `longitude`=121.5130417, `ticket_price`='/+300;/+500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d226b32419285b74f0', '【新北市立圖書館新店北新圖書閱覽室】114年4月主題書展:多元文化大探索', '藉此書展讓孩子們能夠更深入探索不同族群、國家、語言、宗教和生活方式所帶來的多樣性，多元文化書籍涵蓋各種領域，包括文學、歷史、藝術、社會學等，讓孩子了解不同文化的思想、價值觀和生活方式。\r\n\r\n展出時間：4月1日至4月30日 開館時間\r\n         4月3、4及24日   不對外開放\r\n展出地點：新北市立圖書館新店北新圖書閱覽室主題書展區\r\n         新北市新店區北新路一段92號2樓\r\n書展示期間 可外借', '新北市立圖書館總館', '新北市新店區北新路1段92號2樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館新店北新圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店北新圖書閱覽室】114年4月主題書展:多元文化大探索', `description`='藉此書展讓孩子們能夠更深入探索不同族群、國家、語言、宗教和生活方式所帶來的多樣性，多元文化書籍涵蓋各種領域，包括文學、歷史、藝術、社會學等，讓孩子了解不同文化的思想、價值觀和生活方式。\r\n\r\n展出時間：4月1日至4月30日 開館時間\r\n         4月3、4及24日   不對外開放\r\n展出地點：新北市立圖書館新店北新圖書閱覽室主題書展區\r\n         新北市新店區北新路一段92號2樓\r\n書展示期間 可外借', `organizer`='新北市立圖書館總館', `address`='新北市新店區北新路1段92號2樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館新店北新圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d226b32419285b74f2', '【新北市立圖書館新店龜山圖書閱覽室】114年4月主題書展:親如一家', '世界這個地球村讓不同文化背景的人有機會認識彼此，一起相處，圖書館也藉由這樣的背景，在書展中讓大家認識人化的不同，增加彼此的熟悉度，不再陌生!\r\n\r\n\r\n展出時間：4月1日至4月30日 開館時間\r\n         4月3、4及24日   不對外開放\r\n展出地點：新北市立圖書館新店龜山圖書閱覽室主題書展區\r\n         新北市新店區新烏路三段136號\r\n\r\n書展示期間 可外借', '新北市立圖書館總館', '新北市新店區新烏路3段136號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館新店龜山圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店龜山圖書閱覽室】114年4月主題書展:親如一家', `description`='世界這個地球村讓不同文化背景的人有機會認識彼此，一起相處，圖書館也藉由這樣的背景，在書展中讓大家認識人化的不同，增加彼此的熟悉度，不再陌生!\r\n\r\n\r\n展出時間：4月1日至4月30日 開館時間\r\n         4月3、4及24日   不對外開放\r\n展出地點：新北市立圖書館新店龜山圖書閱覽室主題書展區\r\n         新北市新店區新烏路三段136號\r\n\r\n書展示期間 可外借', `organizer`='新北市立圖書館總館', `address`='新北市新店區新烏路3段136號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館新店龜山圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
