INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d426b32419285b74f9', '【新北市立圖書館瑞芳分館】114年4月快樂故事屋', '【瑞芳分館】114年4月快樂故事屋\r\n幼兒聽故事除了可增進親子交流關係外，還可以有助兒童的大腦發展 ；\r\n故事志工: 胡馨云及賴見禎老師準備主題生動活潑，內容豐富的故事與小小孩精彩互動。\r\n\r\n第一場: 4/13(日) 主題: 西北雨來了志工: 胡馨云主講\r\n第二場: 4/27(日) 主題: 著媽祖走志工:   賴見禎主講\r\n時間 : 10:30~11:30\r\n地點 : 瑞芳分館/2樓兒童室\r\n電話 : 02-24972980#9\r\n歡迎親子一同參加. 無需報名\r\n※活動時間若有更動，以現場公告為主，不便之處，敬請見諒。\r\n', '新北市立圖書館總館', '新北市瑞芳區民權街17號2樓', '2025-04-13 00:00:00', '2025-04-27 00:00:00', '新北市立圖書館瑞芳分館', 25.0981293, 121.8232018, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館瑞芳分館】114年4月快樂故事屋', `description`='【瑞芳分館】114年4月快樂故事屋\r\n幼兒聽故事除了可增進親子交流關係外，還可以有助兒童的大腦發展 ；\r\n故事志工: 胡馨云及賴見禎老師準備主題生動活潑，內容豐富的故事與小小孩精彩互動。\r\n\r\n第一場: 4/13(日) 主題: 西北雨來了志工: 胡馨云主講\r\n第二場: 4/27(日) 主題: 著媽祖走志工:   賴見禎主講\r\n時間 : 10:30~11:30\r\n地點 : 瑞芳分館/2樓兒童室\r\n電話 : 02-24972980#9\r\n歡迎親子一同參加. 無需報名\r\n※活動時間若有更動，以現場公告為主，不便之處，敬請見諒。\r\n', `organizer`='新北市立圖書館總館', `address`='新北市瑞芳區民權街17號2樓', `start_date`='2025-04-13 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='新北市立圖書館瑞芳分館', `latitude`=25.0981293, `longitude`=121.8232018, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d426b32419285b74fa', '《因緣起合》王雯個展', '「生活取景，無論人事時地物。畫中取景，無論計劃先還是意外間。視野伴隨年齡增長，思維開闊隨之變化。從意識周遭的斑斕，到追尋嚮往的奇景。」── 王雯\r\n\r\n《因緣起合》匯聚了藝術家王雯在不同「機緣」或「際遇」下所捕捉的畫面與景色，這些影像或許來自於有意的安排，亦或是源自偶然的巧合。隨著歲月的流逝與人生經歷的增長，王雯的視野與思維逐漸拓展，她將日常生活中的自然景致與內心深處所嚮往的境界融合，並透過個人的情感與獨特視角，傳遞著人生中的每一場相遇，皆是因緣交織下的美好證明。\r\n王雯以大漆作為創作媒介，巧妙運用雲母色粉、貝殼、蛋殼等天然素材，經過層層堆疊、打磨與推光，呈現出細緻的紋理與豔麗的色彩。漆畫的創作難度高且充滿不確定性，然而正因其無窮的可能性，深深吸引了她的心。王雯以鮮豔的色彩與華麗的構圖，描繪出世界的繁雜與多樣；超現實的畫面隱喻著她所期盼的理想世界。複雜的線條與筆觸，交織著各種材質，使得作品具有豐富的層次感。她的作品常以飽滿的構圖呈現，極少留白，這種強烈的視覺張力恰恰展現了她獨特的藝術風格。從孩童時期開始，王雯便對孔雀斑斕的羽毛印象深刻，這一元素成為她創作中的重要語彙，象徵著現代社會中人們對美好生活的嚮往與祝福。\r\n藝術家王雯畢業於文化大學美術系研究所；曾獲得阿波羅畫廊與王道銀行教育基金會主辦之「構圖‧台灣」視覺藝術創作徵件計畫的參獎。她與畫廊合作，參與了多次重要展覽，包括臺北國際當代藝術博覽會Young Art、臺南藝術博覽會、《楊桃派Young & Top》、大稻埕國際藝術節聯展、《春妍夏艷》The One 南園人文客棧個展、恆春《恆·好》個展，以及臺北市藝文推廣處楊桃派十週年特展等。\r\n此次展覽將呈現藝術家王雯近年完成的漆畫作品，並於2025年4月19日下午三點正式開幕，5月3日下午三點將舉行藝術家與談活動。誠摯邀請您蒞臨，共同欣賞！', '阿波羅畫廊', '臺北市大安區忠孝東路四段阿波羅大廈218-6號', '2025-04-19 00:00:00', '2025-05-30 00:00:00', '阿波羅畫廊', 25.02677012, 121.5434446, '無資料', 'https://artgalleryapollo.com/2021/event/《因緣起合》王雯個展/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《因緣起合》王雯個展', `description`='「生活取景，無論人事時地物。畫中取景，無論計劃先還是意外間。視野伴隨年齡增長，思維開闊隨之變化。從意識周遭的斑斕，到追尋嚮往的奇景。」── 王雯\r\n\r\n《因緣起合》匯聚了藝術家王雯在不同「機緣」或「際遇」下所捕捉的畫面與景色，這些影像或許來自於有意的安排，亦或是源自偶然的巧合。隨著歲月的流逝與人生經歷的增長，王雯的視野與思維逐漸拓展，她將日常生活中的自然景致與內心深處所嚮往的境界融合，並透過個人的情感與獨特視角，傳遞著人生中的每一場相遇，皆是因緣交織下的美好證明。\r\n王雯以大漆作為創作媒介，巧妙運用雲母色粉、貝殼、蛋殼等天然素材，經過層層堆疊、打磨與推光，呈現出細緻的紋理與豔麗的色彩。漆畫的創作難度高且充滿不確定性，然而正因其無窮的可能性，深深吸引了她的心。王雯以鮮豔的色彩與華麗的構圖，描繪出世界的繁雜與多樣；超現實的畫面隱喻著她所期盼的理想世界。複雜的線條與筆觸，交織著各種材質，使得作品具有豐富的層次感。她的作品常以飽滿的構圖呈現，極少留白，這種強烈的視覺張力恰恰展現了她獨特的藝術風格。從孩童時期開始，王雯便對孔雀斑斕的羽毛印象深刻，這一元素成為她創作中的重要語彙，象徵著現代社會中人們對美好生活的嚮往與祝福。\r\n藝術家王雯畢業於文化大學美術系研究所；曾獲得阿波羅畫廊與王道銀行教育基金會主辦之「構圖‧台灣」視覺藝術創作徵件計畫的參獎。她與畫廊合作，參與了多次重要展覽，包括臺北國際當代藝術博覽會Young Art、臺南藝術博覽會、《楊桃派Young & Top》、大稻埕國際藝術節聯展、《春妍夏艷》The One 南園人文客棧個展、恆春《恆·好》個展，以及臺北市藝文推廣處楊桃派十週年特展等。\r\n此次展覽將呈現藝術家王雯近年完成的漆畫作品，並於2025年4月19日下午三點正式開幕，5月3日下午三點將舉行藝術家與談活動。誠摯邀請您蒞臨，共同欣賞！', `organizer`='阿波羅畫廊', `address`='臺北市大安區忠孝東路四段阿波羅大廈218-6號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-05-30 00:00:00', `location`='阿波羅畫廊', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='無資料', `source_url`='https://artgalleryapollo.com/2021/event/《因緣起合》王雯個展/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d526b32419285b74fb', '天地之際的投影——趙無極《20.10.90》', '趙無極（1921-2013）作為二十世紀最重要的華裔抽象藝術大師，以其獨特的「抒情抽象」風格，成功融合東方哲學底蘊與西方表現主義形式。創作於1990年的《20.10.90》，不僅是其藝術成熟期的代表之作，更完美體現了藝術家對空間維度、光影變幻與自然本質的深刻體悟。\r\n作品資訊\r\n▍趙無極《20.10.90》1990年作​ 油彩畫布​ 65.5ｘ81cm\r\n▍簽名右下：無極 ZAO\r\n▍簽名畫背：ZAO Wou-ki 20.10.90\r\n▍出版資料：《長流藝聞NO.36》，長流畫廊，1993年7月，p.2。 \r\n 2025台北藝流春季拍賣會 2025年4月26日(六)\r\n★參與競投：https://reurl.cc/kn7OOd\r\n★高估價拍品​ 起拍價1,000萬', '長流美術館股份有限公司', '臺北市中正區仁愛路二段63號B1', '2025-03-27 00:00:00', '2025-04-27 00:00:00', '長流美術館 台北館', 25.03240487, 121.5198839, '無資料', 'https://www.chanliu.com/2025/03/29/%E5%A4%A9%E5%9C%B0%E4%B9%8B%E9%9A%9B%E7%9A%84%E6%8A%95%E5%BD%B1-%', '[]') ON DUPLICATE KEY UPDATE `activity_name`='天地之際的投影——趙無極《20.10.90》', `description`='趙無極（1921-2013）作為二十世紀最重要的華裔抽象藝術大師，以其獨特的「抒情抽象」風格，成功融合東方哲學底蘊與西方表現主義形式。創作於1990年的《20.10.90》，不僅是其藝術成熟期的代表之作，更完美體現了藝術家對空間維度、光影變幻與自然本質的深刻體悟。\r\n作品資訊\r\n▍趙無極《20.10.90》1990年作​ 油彩畫布​ 65.5ｘ81cm\r\n▍簽名右下：無極 ZAO\r\n▍簽名畫背：ZAO Wou-ki 20.10.90\r\n▍出版資料：《長流藝聞NO.36》，長流畫廊，1993年7月，p.2。 \r\n 2025台北藝流春季拍賣會 2025年4月26日(六)\r\n★參與競投：https://reurl.cc/kn7OOd\r\n★高估價拍品​ 起拍價1,000萬', `organizer`='長流美術館股份有限公司', `address`='臺北市中正區仁愛路二段63號B1', `start_date`='2025-03-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='長流美術館 台北館', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='無資料', `source_url`='https://www.chanliu.com/2025/03/29/%E5%A4%A9%E5%9C%B0%E4%B9%8B%E9%9A%9B%E7%9A%84%E6%8A%95%E5%BD%B1-%', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d526b32419285b74fc', '同磨來趣-曾達智師生聯展 ', '曾達智老師，繪畫創作與教學多年，緣起在長青學苑的授課時光，看到長輩們對繪畫的學習熱忱與投入，師生一同在藝術創作的路上，為著同樣的方向，手握畫筆努力磨練，進而深刻體會教學相長的實踐，感受相同的苦樂趣味，希望能以藝術饗宴，讓創作者與欣賞者，彼此心靈帶來豐富且美好的正能量。', '桃園市政府地方稅務局', '桃園市桃園區成功路二段179號', '2025-03-31 00:00:00', '2025-06-27 00:00:00', '桃園市政府地方稅務局', 24.9952736, 121.319965, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='同磨來趣-曾達智師生聯展 ', `description`='曾達智老師，繪畫創作與教學多年，緣起在長青學苑的授課時光，看到長輩們對繪畫的學習熱忱與投入，師生一同在藝術創作的路上，為著同樣的方向，手握畫筆努力磨練，進而深刻體會教學相長的實踐，感受相同的苦樂趣味，希望能以藝術饗宴，讓創作者與欣賞者，彼此心靈帶來豐富且美好的正能量。', `organizer`='桃園市政府地方稅務局', `address`='桃園市桃園區成功路二段179號', `start_date`='2025-03-31 00:00:00', `end_date`='2025-06-27 00:00:00', `location`='桃園市政府地方稅務局', `latitude`=24.9952736, `longitude`=121.319965, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d626b32419285b7503', '2025苗栗縣4-6月藝文展演活動：苗栗縣象山書院學會-客家歌謠', '為提供縣內藝文團隊展現才華機會，並增進民眾欣賞多元表演的文化體驗，苗栗縣政府文化觀光局今年援例於1月3日起至12月31日（每週五、六）晚上7時至8時，在苗栗後火車站西站外廣場舉辦藝文展演，並於大年初一至初五（1月29日至2月2日）農曆春節加碼安排一系列精采的表演，誠摯邀請大家一同感受熱鬧氛圍，欣賞精采藝文展演！\r\n活動詳情可查詢苗栗縣政府文化觀光局網站 http://www.mlc.gov.tw', '苗栗縣政府文化觀光局', '苗栗縣苗栗市', '2025-04-18 00:00:00', '2025-04-18 00:00:00', '苗栗市（苗栗縣）=', 24.56382141, 120.8112299, '無資料', 'https://www.mlc.gov.tw/home.aspx', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025苗栗縣4-6月藝文展演活動：苗栗縣象山書院學會-客家歌謠', `description`='為提供縣內藝文團隊展現才華機會，並增進民眾欣賞多元表演的文化體驗，苗栗縣政府文化觀光局今年援例於1月3日起至12月31日（每週五、六）晚上7時至8時，在苗栗後火車站西站外廣場舉辦藝文展演，並於大年初一至初五（1月29日至2月2日）農曆春節加碼安排一系列精采的表演，誠摯邀請大家一同感受熱鬧氛圍，欣賞精采藝文展演！\r\n活動詳情可查詢苗栗縣政府文化觀光局網站 http://www.mlc.gov.tw', `organizer`='苗栗縣政府文化觀光局', `address`='苗栗縣苗栗市', `start_date`='2025-04-18 00:00:00', `end_date`='2025-04-18 00:00:00', `location`='苗栗市（苗栗縣）=', `latitude`=24.56382141, `longitude`=120.8112299, `ticket_price`='無資料', `source_url`='https://www.mlc.gov.tw/home.aspx', `image_url`='[]';
