INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d726b32419285b751b', '寶島台語囡仔古', '由寶島台語囡仔古社團的故事志工為親子們說演台語故事，並加入延伸的手作活動。\r\n繪本：彼工來ê海翁koh轉來ah\r\n(那天來的鯨魚回來了)\r\n', '高雄市立圖書館總館', '高雄市新興區6鄰民生一路271號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '高雄市立圖書館新興民眾閱覽室', 22.6272175, 120.3068429, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='寶島台語囡仔古', `description`='由寶島台語囡仔古社團的故事志工為親子們說演台語故事，並加入延伸的手作活動。\r\n繪本：彼工來ê海翁koh轉來ah\r\n(那天來的鯨魚回來了)\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市新興區6鄰民生一路271號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='高雄市立圖書館新興民眾閱覽室', `latitude`=22.6272175, `longitude`=120.3068429, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d726b32419285b751e', '【水中スピカ 2025 3rd Album《Lux》Live in Kaohsiung】', '日本夢幻數學搖滾 / EMO 樂隊「水中スピか」3rd Album《Lux》2025 高雄專場\r\n\r\n水中スピカ 是一支來自京都的數學搖滾樂隊，去年橫跨中國、泰國和韓國的巡演場次全數售罄，他們亦參加了日本 Fuji Rock 和中國西湖音樂節等著名音樂盛會。今年他們將走向世界舞台，登上台灣的浮現祭和美國的 SXSW 音樂節。水中スピカ 的最新專輯《Lux》展現了更加成熟的美學，以詩意的歌詞和沉浸式的旋律，喚起與名字「Spica」（珍珠星）象徵意義相呼應的璀璨光輝。\r\n\r\n《Lux》邀請聽眾透過層次豐富的編曲探索情感與故事。專輯的音樂錄影帶以自然景觀與夢幻般的視覺效果為背景，將觀眾帶入栩栩如生的異世界。千愛的歌詞受日本美學啟發，傳遞出希望、韌性，以及將孤獨轉化為與宇宙和諧相融的主題。\r\n\r\n水中スピカ的現場演出是一場感官饗宴，充滿活力的節奏與溫柔高昂的嗓音交織。旋律的起伏宛如冬季列車呼嘯而過，帶來冷冽之美與炙熱的激情，喚醒沉睡的靈魂。2025 年的台灣巡迴演出將延續他們對情感與藝術的探索之旅，邀請台灣樂迷共同進入《Lux》的璀璨深處。', 'WUTANG Records', '高雄市鹽埕區17鄰真愛路1號', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人預售票+700;現場票+900;雙人預售票（限量）+1200', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【水中スピカ 2025 3rd Album《Lux》Live in Kaohsiung】', `description`='日本夢幻數學搖滾 / EMO 樂隊「水中スピか」3rd Album《Lux》2025 高雄專場\r\n\r\n水中スピカ 是一支來自京都的數學搖滾樂隊，去年橫跨中國、泰國和韓國的巡演場次全數售罄，他們亦參加了日本 Fuji Rock 和中國西湖音樂節等著名音樂盛會。今年他們將走向世界舞台，登上台灣的浮現祭和美國的 SXSW 音樂節。水中スピカ 的最新專輯《Lux》展現了更加成熟的美學，以詩意的歌詞和沉浸式的旋律，喚起與名字「Spica」（珍珠星）象徵意義相呼應的璀璨光輝。\r\n\r\n《Lux》邀請聽眾透過層次豐富的編曲探索情感與故事。專輯的音樂錄影帶以自然景觀與夢幻般的視覺效果為背景，將觀眾帶入栩栩如生的異世界。千愛的歌詞受日本美學啟發，傳遞出希望、韌性，以及將孤獨轉化為與宇宙和諧相融的主題。\r\n\r\n水中スピカ的現場演出是一場感官饗宴，充滿活力的節奏與溫柔高昂的嗓音交織。旋律的起伏宛如冬季列車呼嘯而過，帶來冷冽之美與炙熱的激情，喚醒沉睡的靈魂。2025 年的台灣巡迴演出將延續他們對情感與藝術的探索之旅，邀請台灣樂迷共同進入《Lux》的璀璨深處。', `organizer`='WUTANG Records', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人預售票+700;現場票+900;雙人預售票（限量）+1200', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d726b32419285b751f', 'InFission《血祭》－高雄場', '《血祭—血玫瑰音樂祭》\r\n世界裂變之際\r\nEYWA壯烈犧牲 以血獻祭\r\n其鮮血化作玫瑰\r\n「以我之血 獻於玫瑰」\r\n玫瑰教入教儀式 準時回歸', '高雄流行音樂中心', '高雄市鹽埕區17鄰真愛路1號', '2025-07-05 00:00:00', '2025-07-05 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人預售票+600;現場票+800;雙人預售票+1000', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='InFission《血祭》－高雄場', `description`='《血祭—血玫瑰音樂祭》\r\n世界裂變之際\r\nEYWA壯烈犧牲 以血獻祭\r\n其鮮血化作玫瑰\r\n「以我之血 獻於玫瑰」\r\n玫瑰教入教儀式 準時回歸', `organizer`='高雄流行音樂中心', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-07-05 00:00:00', `end_date`='2025-07-05 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人預售票+600;現場票+800;雙人預售票+1000', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d726b32419285b7521', '2025 怡岑《要到你想逃》音樂喜劇專場 高雄場', '要到你想逃……\r\n\r\n這是一場你看完後就會起身離開的演唱會。\r\n\r\n不然？\r\n\r\n你以為你已經可以離開這裡，\r\n\r\n但因為外面又賣很多周邊，\r\n\r\n你可能又要花一些時間才能逃離我的陷阱。\r\n\r\n是不是恨可以要到你想逃，\r\n\r\n愛也可以要到你想逃？\r\n\r\n那如果我們能夠相愛就沒事了。\r\n\r\n愛情、友情、親情，還有我和每個你。\r\n\r\n希望我們都不會輕易逃開，\r\n\r\n都能好好享受。\r\n\r\n但如果萬一我真的想逃的話，\r\n\r\n我會逃到舞台上，\r\n\r\n站著唱，大家笑，你也要笑。\r\n\r\n我只是希望你開心。', '薩泰爾娛樂股份有限公司', '高雄市鹽埕區17鄰真愛路1號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '優待票區+400;C區+800;B區+800;A區+1000', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 怡岑《要到你想逃》音樂喜劇專場 高雄場', `description`='要到你想逃……\r\n\r\n這是一場你看完後就會起身離開的演唱會。\r\n\r\n不然？\r\n\r\n你以為你已經可以離開這裡，\r\n\r\n但因為外面又賣很多周邊，\r\n\r\n你可能又要花一些時間才能逃離我的陷阱。\r\n\r\n是不是恨可以要到你想逃，\r\n\r\n愛也可以要到你想逃？\r\n\r\n那如果我們能夠相愛就沒事了。\r\n\r\n愛情、友情、親情，還有我和每個你。\r\n\r\n希望我們都不會輕易逃開，\r\n\r\n都能好好享受。\r\n\r\n但如果萬一我真的想逃的話，\r\n\r\n我會逃到舞台上，\r\n\r\n站著唱，大家笑，你也要笑。\r\n\r\n我只是希望你開心。', `organizer`='薩泰爾娛樂股份有限公司', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='優待票區+400;C區+800;B區+800;A區+1000', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d726b32419285b7522', '【最藍調特企】Dirty One Man Blues Band ｜Jack Conqueroo', '一人藍調歌手－狼人傑克Jack Conqueroo，在30 多年的職業生涯中，一直以他令人著迷的密西西比藍調風格風靡樂迷。受到了R.L.9 Burnside、Junior Kimbrough 和密西西比的FredMcDowell 的影響，傑克的音樂可以說是受到了密西西比泥土的洗禮，充滿了魔幻色彩。在爵《最藍調》黑膠展的最後壓軸，特別邀請狼人傑克帶來最具藍調靈魂，藍調迷不容錯過的一場精采演出!', '爵式 WiJazz Records', '高雄市鹽埕區17鄰真愛路1號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人+350', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【最藍調特企】Dirty One Man Blues Band ｜Jack Conqueroo', `description`='一人藍調歌手－狼人傑克Jack Conqueroo，在30 多年的職業生涯中，一直以他令人著迷的密西西比藍調風格風靡樂迷。受到了R.L.9 Burnside、Junior Kimbrough 和密西西比的FredMcDowell 的影響，傑克的音樂可以說是受到了密西西比泥土的洗禮，充滿了魔幻色彩。在爵《最藍調》黑膠展的最後壓軸，特別邀請狼人傑克帶來最具藍調靈魂，藍調迷不容錯過的一場精采演出!', `organizer`='爵式 WiJazz Records', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人+350', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d726b32419285b7523', '愛在巴黎天空下', '在巴黎的天空下，愛情有很多種樣貌，有香頌天后Edith Piaf的人生摯愛，有菸、酒和愛情不離手的創作型歌手Serge Gainsbourg 的一夜風流，有備受巴黎人愛載的美國爵士樂豎笛手Sidney Bechet 的親情回憶，還有西裝畢挺，總是叼著根菸的爵士吉他手Django Reinhardt 快慢交錯的吉普賽情歌。\r\n種種愛情，都被精選在『愛在巴黎天空下』的音樂會中，就讓優雅歌聲伴著各位重返復古年代的浪漫花都。', '爵式 WiJazz Records', '高雄市鹽埕區17鄰真愛路1號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人+500;雙人+900', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='愛在巴黎天空下', `description`='在巴黎的天空下，愛情有很多種樣貌，有香頌天后Edith Piaf的人生摯愛，有菸、酒和愛情不離手的創作型歌手Serge Gainsbourg 的一夜風流，有備受巴黎人愛載的美國爵士樂豎笛手Sidney Bechet 的親情回憶，還有西裝畢挺，總是叼著根菸的爵士吉他手Django Reinhardt 快慢交錯的吉普賽情歌。\r\n種種愛情，都被精選在『愛在巴黎天空下』的音樂會中，就讓優雅歌聲伴著各位重返復古年代的浪漫花都。', `organizer`='爵式 WiJazz Records', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人+500;雙人+900', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d826b32419285b7524', '【新北市立圖書館土城清水圖書閱覽室】114年4月份書展', '【新北市立圖書館土城清水圖書閱覽室】114年4月份書展\r\n4月樂齡書展「中醫樂齡保健之道」\r\n中醫是世界上最古老的醫學體系之一，強調「治未病」，也就是預防疾病的發生。從經絡、穴位、藥草等等，讓專家教您好好保養身體，防患未然。\r\n\r\n4月主題書展「育兒全攻略」\r\n育兒問題從A到Z，如何解決，答案全部在這裡！\r\n\r\n展示期間：114年4月01日-4月30日／開館時間\r\n週二~週六，08:30~21:00\r\n週日~週一，08:30~17:00\r\n國定假日與清館日(每月最後一個星期四)不對外開放。\r\n書展場地：土城清水圖書閱覽室 2樓書展區\r\n活動地址：土城區清水路243號2樓\r\n電話：02-22653293#9\r\n\r\n公車：清水國小站(金城路）--【藍17】【706】\r\n清水國小站(清水路）--【275】【707】【藍41】\r\n板橋地方法院站(青雲路）--【245】【656】【262】須步行約600公尺\r\n \r\n', '新北市立圖書館總館', '新北市土城區清水路243-1號2樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館土城清水圖書閱覽室', 24.96425102, 121.445737, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館土城清水圖書閱覽室】114年4月份書展', `description`='【新北市立圖書館土城清水圖書閱覽室】114年4月份書展\r\n4月樂齡書展「中醫樂齡保健之道」\r\n中醫是世界上最古老的醫學體系之一，強調「治未病」，也就是預防疾病的發生。從經絡、穴位、藥草等等，讓專家教您好好保養身體，防患未然。\r\n\r\n4月主題書展「育兒全攻略」\r\n育兒問題從A到Z，如何解決，答案全部在這裡！\r\n\r\n展示期間：114年4月01日-4月30日／開館時間\r\n週二~週六，08:30~21:00\r\n週日~週一，08:30~17:00\r\n國定假日與清館日(每月最後一個星期四)不對外開放。\r\n書展場地：土城清水圖書閱覽室 2樓書展區\r\n活動地址：土城區清水路243號2樓\r\n電話：02-22653293#9\r\n\r\n公車：清水國小站(金城路）--【藍17】【706】\r\n清水國小站(清水路）--【275】【707】【藍41】\r\n板橋地方法院站(青雲路）--【245】【656】【262】須步行約600公尺\r\n \r\n', `organizer`='新北市立圖書館總館', `address`='新北市土城區清水路243-1號2樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館土城清水圖書閱覽室', `latitude`=24.96425102, `longitude`=121.445737, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d826b32419285b7525', '賽夏族民俗文物館「原音傳世」春節演出：lolowa''樂團-樂團演唱', '「原音」指的是原住民族純粹且具有特色的音樂與聲音，承載著各族群的歷史、故事和情感，原音常與舞蹈相伴相生，音樂的節奏牽引舞步，歌聲的抑揚訴說情感，音樂與舞蹈如靈魂雙翼，共繪生命張力與自然和諧。「傳世」則強調了文化精粹的歷史傳承及跨世代的影響力，透過藝文展演，原聲與舞蹈交融，兩者相映，共同喚醒對原住民族文化的敬意，傳遞珍貴聲音背後的靈魂與故事。\r\n賽夏族民俗文物館假日藝文系列活動自1月29日（農曆正月初一）至2月2日（農曆正月初五）期間，每日安排街頭藝人或表演團體共5場次的演出。自2月22日起至12月27日，每月的第2個和第4個週六，舉辦街頭藝人與表演團體的演出。表演將於14:20至16:20進行，共計10場；表演團體則於14:20至15:00進行，總共11場。', '苗栗縣政府原住民族及族群發展處', '苗栗縣南庄鄉苗栗縣南庄鄉東河村16鄰向天湖25號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '苗栗縣賽夏族民俗文物館', 24.56608432, 121.017471, '全票+30;團體票+20;優待票+10', 'https://www.facebook.com/rareme037825024', '[]') ON DUPLICATE KEY UPDATE `activity_name`='賽夏族民俗文物館「原音傳世」春節演出：lolowa''樂團-樂團演唱', `description`='「原音」指的是原住民族純粹且具有特色的音樂與聲音，承載著各族群的歷史、故事和情感，原音常與舞蹈相伴相生，音樂的節奏牽引舞步，歌聲的抑揚訴說情感，音樂與舞蹈如靈魂雙翼，共繪生命張力與自然和諧。「傳世」則強調了文化精粹的歷史傳承及跨世代的影響力，透過藝文展演，原聲與舞蹈交融，兩者相映，共同喚醒對原住民族文化的敬意，傳遞珍貴聲音背後的靈魂與故事。\r\n賽夏族民俗文物館假日藝文系列活動自1月29日（農曆正月初一）至2月2日（農曆正月初五）期間，每日安排街頭藝人或表演團體共5場次的演出。自2月22日起至12月27日，每月的第2個和第4個週六，舉辦街頭藝人與表演團體的演出。表演將於14:20至16:20進行，共計10場；表演團體則於14:20至15:00進行，總共11場。', `organizer`='苗栗縣政府原住民族及族群發展處', `address`='苗栗縣南庄鄉苗栗縣南庄鄉東河村16鄰向天湖25號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='苗栗縣賽夏族民俗文物館', `latitude`=24.56608432, `longitude`=121.017471, `ticket_price`='全票+30;團體票+20;優待票+10', `source_url`='https://www.facebook.com/rareme037825024', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d826b32419285b7528', '泰雅原住民文化產業區「原音傳世」假日藝文展演：力爆了樂團-樂團演唱', '114年苗栗縣原住民族文物館假日藝文展演活動，以「原音傳世」為主題，分別象徵著原住民族的音樂、舞蹈、歌謠及藝術的歷史延續與傳承。\r\n「原音」指的是原住民族純粹且具有特色的音樂與聲音，承載著各族群的歷史、故事和情感，原音常與舞蹈相伴相生，音樂的節奏牽引舞步，歌聲的抑揚訴說情感，音樂與舞蹈如靈魂雙翼，共繪生命張力與自然和諧。「傳世」則強調了文化精粹的歷史傳承及跨世代的影響力，透過藝文展演，原聲與舞蹈交融，兩者相映，共同喚醒對原住民族文化的敬意，傳遞珍貴聲音背後的靈魂與故事。\r\n泰雅文物館假日藝文展演活動自1月29日（農曆正月初一）至2月2日（農曆正月初五）期間，每日安排街頭藝人或表演團體共5場次的演出，2月15日至12月27日止，邀請原住民團體或樂團演出，每週六表演一場次，14:20～15:00；共計45場次。2月9日至12月28日止，安排街頭藝人演出，每個月第2、4個週日表演一場次，表演時間10:00~12:00；共計22場。', '苗栗縣政府原住民族及族群發展處', '苗栗縣泰安鄉圓墩6鄰46-3號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '苗栗縣泰雅原住民文化產業區', 24.41925819, 121.0681571, '無資料', 'https://www.facebook.com/TAYALMUSEUM', '[]') ON DUPLICATE KEY UPDATE `activity_name`='泰雅原住民文化產業區「原音傳世」假日藝文展演：力爆了樂團-樂團演唱', `description`='114年苗栗縣原住民族文物館假日藝文展演活動，以「原音傳世」為主題，分別象徵著原住民族的音樂、舞蹈、歌謠及藝術的歷史延續與傳承。\r\n「原音」指的是原住民族純粹且具有特色的音樂與聲音，承載著各族群的歷史、故事和情感，原音常與舞蹈相伴相生，音樂的節奏牽引舞步，歌聲的抑揚訴說情感，音樂與舞蹈如靈魂雙翼，共繪生命張力與自然和諧。「傳世」則強調了文化精粹的歷史傳承及跨世代的影響力，透過藝文展演，原聲與舞蹈交融，兩者相映，共同喚醒對原住民族文化的敬意，傳遞珍貴聲音背後的靈魂與故事。\r\n泰雅文物館假日藝文展演活動自1月29日（農曆正月初一）至2月2日（農曆正月初五）期間，每日安排街頭藝人或表演團體共5場次的演出，2月15日至12月27日止，邀請原住民團體或樂團演出，每週六表演一場次，14:20～15:00；共計45場次。2月9日至12月28日止，安排街頭藝人演出，每個月第2、4個週日表演一場次，表演時間10:00~12:00；共計22場。', `organizer`='苗栗縣政府原住民族及族群發展處', `address`='苗栗縣泰安鄉圓墩6鄰46-3號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='苗栗縣泰雅原住民文化產業區', `latitude`=24.41925819, `longitude`=121.0681571, `ticket_price`='無資料', `source_url`='https://www.facebook.com/TAYALMUSEUM', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d826b32419285b7529', '泰雅原住民文化產業區「原音傳世」假日藝文展演：怡啦文化藝術團舞蹈表演', '114年苗栗縣原住民族文物館假日藝文展演活動，以「原音傳世」為主題，分別象徵著原住民族的音樂、舞蹈、歌謠及藝術的歷史延續與傳承。\r\n「原音」指的是原住民族純粹且具有特色的音樂與聲音，承載著各族群的歷史、故事和情感，原音常與舞蹈相伴相生，音樂的節奏牽引舞步，歌聲的抑揚訴說情感，音樂與舞蹈如靈魂雙翼，共繪生命張力與自然和諧。「傳世」則強調了文化精粹的歷史傳承及跨世代的影響力，透過藝文展演，原聲與舞蹈交融，兩者相映，共同喚醒對原住民族文化的敬意，傳遞珍貴聲音背後的靈魂與故事。\r\n泰雅文物館假日藝文展演活動自1月29日（農曆正月初一）至2月2日（農曆正月初五）期間，每日安排街頭藝人或表演團體共5場次的演出，2月15日至12月27日止，邀請原住民團體或樂團演出，每週六表演一場次，14:20～15:00；共計45場次。2月9日至12月28日止，安排街頭藝人演出，每個月第2、4個週日表演一場次，表演時間10:00~12:00；共計22場。', '苗栗縣政府原住民族及族群發展處', '苗栗縣泰安鄉圓墩6鄰46-3號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '苗栗縣泰雅原住民文化產業區', 24.41925819, 121.0681571, '無資料', 'https://www.facebook.com/TAYALMUSEUM', '[]') ON DUPLICATE KEY UPDATE `activity_name`='泰雅原住民文化產業區「原音傳世」假日藝文展演：怡啦文化藝術團舞蹈表演', `description`='114年苗栗縣原住民族文物館假日藝文展演活動，以「原音傳世」為主題，分別象徵著原住民族的音樂、舞蹈、歌謠及藝術的歷史延續與傳承。\r\n「原音」指的是原住民族純粹且具有特色的音樂與聲音，承載著各族群的歷史、故事和情感，原音常與舞蹈相伴相生，音樂的節奏牽引舞步，歌聲的抑揚訴說情感，音樂與舞蹈如靈魂雙翼，共繪生命張力與自然和諧。「傳世」則強調了文化精粹的歷史傳承及跨世代的影響力，透過藝文展演，原聲與舞蹈交融，兩者相映，共同喚醒對原住民族文化的敬意，傳遞珍貴聲音背後的靈魂與故事。\r\n泰雅文物館假日藝文展演活動自1月29日（農曆正月初一）至2月2日（農曆正月初五）期間，每日安排街頭藝人或表演團體共5場次的演出，2月15日至12月27日止，邀請原住民團體或樂團演出，每週六表演一場次，14:20～15:00；共計45場次。2月9日至12月28日止，安排街頭藝人演出，每個月第2、4個週日表演一場次，表演時間10:00~12:00；共計22場。', `organizer`='苗栗縣政府原住民族及族群發展處', `address`='苗栗縣泰安鄉圓墩6鄰46-3號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='苗栗縣泰雅原住民文化產業區', `latitude`=24.41925819, `longitude`=121.0681571, `ticket_price`='無資料', `source_url`='https://www.facebook.com/TAYALMUSEUM', `image_url`='[]';
