INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d826b32419285b752b', '「心靈之眼—自然與人文的多樣之美」鄒松鶴繪畫雕塑展', '鄒松鶴以細膩的筆觸與精湛的雕塑技巧，創作出一系列兼具寫實與象徵意涵的藝術作品，本次展覽將聚焦四大主題：玉山一一象徵台灣精神，傳遞堅韌不拔的意志與民族自信。人物一一描繪人類多樣的面貌與情感，探討生命的內在本質。葡萄一一象徵繁衍與豐收，傳達生命的延續與美好祝福。花卉一一代表愛情與情感的表達，透過藝術詮釋人類最純粹的情感。\r\n鄒松鶴以寫實風格詮釋上述主題，無論是畫作還是雕塑，都展現出對細節的極致掌握與獨特的藝術視角。觀眾將能透過他的作品，感受大自然的壯麗、人文情懷的深刻，以及生命本質的純粹之美。\r\n本次展覽不僅是一場視覺饗宴，更希望帶領觀眾走入當代藝術的世界，體驗多元文化與情感交融的美好。透過藝術的視角，觀眾將能重新審視自然與人文的關係，並激發對生活與美學的深層思考。\r\n本次展覽匯聚藝術家鄒松鶴繪畫與雕塑作品共計55件，創作類型橫跨油畫、鉛筆素描與立體雕塑，創作技法則是透過現代藝術語彙，呈現自然與人文交織的豐富美學。4月2日早上十點舉辦開幕式。', '苗栗縣政府', '苗栗縣苗栗市自治路50號', '2025-04-02 00:00:00', '2025-04-28 00:00:00', '苗栗縣政府文化觀光局', 24.565963, 120.8203986, '無資料', 'https://www.mlc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「心靈之眼—自然與人文的多樣之美」鄒松鶴繪畫雕塑展', `description`='鄒松鶴以細膩的筆觸與精湛的雕塑技巧，創作出一系列兼具寫實與象徵意涵的藝術作品，本次展覽將聚焦四大主題：玉山一一象徵台灣精神，傳遞堅韌不拔的意志與民族自信。人物一一描繪人類多樣的面貌與情感，探討生命的內在本質。葡萄一一象徵繁衍與豐收，傳達生命的延續與美好祝福。花卉一一代表愛情與情感的表達，透過藝術詮釋人類最純粹的情感。\r\n鄒松鶴以寫實風格詮釋上述主題，無論是畫作還是雕塑，都展現出對細節的極致掌握與獨特的藝術視角。觀眾將能透過他的作品，感受大自然的壯麗、人文情懷的深刻，以及生命本質的純粹之美。\r\n本次展覽不僅是一場視覺饗宴，更希望帶領觀眾走入當代藝術的世界，體驗多元文化與情感交融的美好。透過藝術的視角，觀眾將能重新審視自然與人文的關係，並激發對生活與美學的深層思考。\r\n本次展覽匯聚藝術家鄒松鶴繪畫與雕塑作品共計55件，創作類型橫跨油畫、鉛筆素描與立體雕塑，創作技法則是透過現代藝術語彙，呈現自然與人文交織的豐富美學。4月2日早上十點舉辦開幕式。', `organizer`='苗栗縣政府', `address`='苗栗縣苗栗市自治路50號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-28 00:00:00', `location`='苗栗縣政府文化觀光局', `latitude`=24.565963, `longitude`=120.8203986, `ticket_price`='無資料', `source_url`='https://www.mlc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ec60d826b32419285b752c', '故事達人說故事暨FUN心聽故事(中崙分館114年4月)', '規劃適合小朋友的繪本說故事活動，藉由生動活潑的說故事方式帶領小朋友一起閱讀，讓孩子愛上閱讀。', '高雄市立圖書館總館', '高雄市鳳山區24鄰中崙5路1號', '2025-04-05 00:00:00', '2025-04-27 00:00:00', '高雄市立圖書館中崙分館', 22.601569, 120.349661, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='故事達人說故事暨FUN心聽故事(中崙分館114年4月)', `description`='規劃適合小朋友的繪本說故事活動，藉由生動活潑的說故事方式帶領小朋友一起閱讀，讓孩子愛上閱讀。', `organizer`='高雄市立圖書館總館', `address`='高雄市鳳山區24鄰中崙5路1號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='高雄市立圖書館中崙分館', `latitude`=22.601569, `longitude`=120.349661, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
