INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb18a26b3242b74a3adc7', '移向Always-醒吾科大商業設計系第11屆畢業專題設計展', '「天使數字11」可能是宇宙的指標，表明自己走在正確的道路上，是宇宙中的巧妙推動。醒吾科大商業設計系期望透過數字「11」作為設計主題來表達自我實現甚至超越自我的目標，以及協作、雙贏的團隊精神。\r\n\r\n\r\n', '醒吾科技大學', '桃園市中壢區中美路16號', '2025-04-08 00:00:00', '2025-04-20 00:00:00', '中壢藝術館', 24.958126, 121.227384, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='移向Always-醒吾科大商業設計系第11屆畢業專題設計展', `description`='「天使數字11」可能是宇宙的指標，表明自己走在正確的道路上，是宇宙中的巧妙推動。醒吾科大商業設計系期望透過數字「11」作為設計主題來表達自我實現甚至超越自我的目標，以及協作、雙贏的團隊精神。\r\n\r\n\r\n', `organizer`='醒吾科技大學', `address`='桃園市中壢區中美路16號', `start_date`='2025-04-08 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='中壢藝術館', `latitude`=24.958126, `longitude`=121.227384, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb18a26b3242b74a3adc8', '桃園市國樂團兒童劇音樂會《桐花護衛隊II-王國大慶典》(2場)', '桐花國的慶典將至，公主卻苦惱表演內容，想努力展現自己不想讓國王失望。熱心的朋友們和王后提供了許多建議，當她找到最特別的演出時，國王卻錯過了預演…桃園市國樂團期望透過音樂，傳達學習過程的勇敢，邀請大小朋友共度這場充滿愛與成長意義的兒童劇音樂會！\r\n\r\n\r\n\r\n\r\n', '財團法人桃園市文化基金會', '桃園市中壢區中美路16號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '中壢藝術館', 24.958126, 121.227384, '票價+300;票價+500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桃園市國樂團兒童劇音樂會《桐花護衛隊II-王國大慶典》(2場)', `description`='桐花國的慶典將至，公主卻苦惱表演內容，想努力展現自己不想讓國王失望。熱心的朋友們和王后提供了許多建議，當她找到最特別的演出時，國王卻錯過了預演…桃園市國樂團期望透過音樂，傳達學習過程的勇敢，邀請大小朋友共度這場充滿愛與成長意義的兒童劇音樂會！\r\n\r\n\r\n\r\n\r\n', `organizer`='財團法人桃園市文化基金會', `address`='桃園市中壢區中美路16號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='中壢藝術館', `latitude`=24.958126, `longitude`=121.227384, `ticket_price`='票價+300;票價+500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb18a26b3242b74a3adc9', '夢想成真魔術劇團-親子魔幻秀', '新秀登場! 結合魔術、小丑和氣球造型藝術的打造歡樂的親子表演節目，非常適合全家同樂!充滿魔幻與驚喜的大型魔術秀演出，搞笑無俚頭的小丑，帶來雜耍、魔術、人入大氣球表演，博神羅賓老師，要帶著觀眾們度過爆笑又逗趣的魔術表演、跟著音樂舞動，邊跳舞邊運用氣球特性，展現不同凡響的造型藝術，並將觀眾帶入獨特的美食饗宴、以及寶可夢、迪士尼、光劍武士等不同主題。\r\n', '夢想成真魔術劇團', '桃園市中壢區中美路16號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '中壢藝術館', 24.958126, 121.227384, '票價+400;票價+600;票價+800;票價+1000;票價+1200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='夢想成真魔術劇團-親子魔幻秀', `description`='新秀登場! 結合魔術、小丑和氣球造型藝術的打造歡樂的親子表演節目，非常適合全家同樂!充滿魔幻與驚喜的大型魔術秀演出，搞笑無俚頭的小丑，帶來雜耍、魔術、人入大氣球表演，博神羅賓老師，要帶著觀眾們度過爆笑又逗趣的魔術表演、跟著音樂舞動，邊跳舞邊運用氣球特性，展現不同凡響的造型藝術，並將觀眾帶入獨特的美食饗宴、以及寶可夢、迪士尼、光劍武士等不同主題。\r\n', `organizer`='夢想成真魔術劇團', `address`='桃園市中壢區中美路16號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='中壢藝術館', `latitude`=24.958126, `longitude`=121.227384, `ticket_price`='票價+400;票價+600;票價+800;票價+1000;票價+1200', `source_url`='https://www.opentix.life/', `image_url`='[]';
