INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19526b3242b74a3add4', '【新北市立圖書館總館】114年4月新住民媽媽家鄉故事', '新住民媽媽家鄉故事\r\n新北市立圖書館總館安排新住民說故事活動，志工媽媽們來自印尼、緬甸、菲律賓、越南、柬埔寨、日本、馬來西亞、菲律賓等國家，除了說故事外，每年更不定期聯合演出家鄉兒童故事劇，帶大家認識多元文化，歡迎大朋友帶著小朋友們來聽故事。', '新北市立圖書館總館', '新北市板橋區貴興路139號', '2025-04-13 00:00:00', '2025-04-27 00:00:00', '新北市立圖書館總館', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館總館】114年4月新住民媽媽家鄉故事', `description`='新住民媽媽家鄉故事\r\n新北市立圖書館總館安排新住民說故事活動，志工媽媽們來自印尼、緬甸、菲律賓、越南、柬埔寨、日本、馬來西亞、菲律賓等國家，除了說故事外，每年更不定期聯合演出家鄉兒童故事劇，帶大家認識多元文化，歡迎大朋友帶著小朋友們來聽故事。', `organizer`='新北市立圖書館總館', `address`='新北市板橋區貴興路139號', `start_date`='2025-04-13 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='新北市立圖書館總館', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19726b3242b74a3add7', '記憶裡的台中舊城-五權社大師生攝影聯展', '課名：生活攝影～紀錄人生的點點滴滴\r\n屬性：城市攝影紀錄，寫實\r\n作品背景：城市寫真，利用鏡頭帶領觀眾看到攝影者的視角。\r\n\r\n班級歷史：李易霖老師是影像紀錄工作者，106年起在五權社大開班授課，對於公共參與投入相當的熱情，帶領學員外拍總能適時的與庶民生活及人生哲理結合，讓拍攝者在攝影時更能有故事性，授課的8年期間，帶領學員參與大大小小的走讀及探究臺中舊城區的巷弄，也藉由此機會讓民眾更認識台中。\r\n\r\n結合精武圖書館原因：\r\n圖書館與民眾的生活貼近，與社大在地性的理念不謀而合，藉由在精武圖書館展出除了讓學員作品能見度更高，也可能讓來到圖書館的民眾對學習產生興趣。\r\n\r\n臺中市五權社區大學辦學區域為北、中、西區，也曾是台中最為繁榮的區域，從帶領民眾守護河川，愛護環境，認識在地人文歷史與古蹟，進一步促進在地認同，凝聚社區意識，以發揚地方文化，關注社會議題，多元共學體驗，落實終身學習為辦學目標。', '臺中市精武圖書館', '臺中市北區精武路291之3號', '2025-04-02 00:00:00', '2025-05-28 00:00:00', '臺中市精武圖書館', 24.15863985, 120.6809521, '無資料', 'https://reurl.cc/5K2dKz', '[]') ON DUPLICATE KEY UPDATE `activity_name`='記憶裡的台中舊城-五權社大師生攝影聯展', `description`='課名：生活攝影～紀錄人生的點點滴滴\r\n屬性：城市攝影紀錄，寫實\r\n作品背景：城市寫真，利用鏡頭帶領觀眾看到攝影者的視角。\r\n\r\n班級歷史：李易霖老師是影像紀錄工作者，106年起在五權社大開班授課，對於公共參與投入相當的熱情，帶領學員外拍總能適時的與庶民生活及人生哲理結合，讓拍攝者在攝影時更能有故事性，授課的8年期間，帶領學員參與大大小小的走讀及探究臺中舊城區的巷弄，也藉由此機會讓民眾更認識台中。\r\n\r\n結合精武圖書館原因：\r\n圖書館與民眾的生活貼近，與社大在地性的理念不謀而合，藉由在精武圖書館展出除了讓學員作品能見度更高，也可能讓來到圖書館的民眾對學習產生興趣。\r\n\r\n臺中市五權社區大學辦學區域為北、中、西區，也曾是台中最為繁榮的區域，從帶領民眾守護河川，愛護環境，認識在地人文歷史與古蹟，進一步促進在地認同，凝聚社區意識，以發揚地方文化，關注社會議題，多元共學體驗，落實終身學習為辦學目標。', `organizer`='臺中市精武圖書館', `address`='臺中市北區精武路291之3號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-05-28 00:00:00', `location`='臺中市精武圖書館', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://reurl.cc/5K2dKz', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19c26b3242b74a3adda', '【中市圖清水分館】4月-2025世界閱讀日-遨遊書海主題書展', '你/妳今天閱讀了嗎? 逢四月二十三日「世界閱讀日（World Book Day）」及「世界讀書及版權日（World Book And Copyright Day)」的來臨，讓我們趁此關注閱讀、圖書出版、編輯與智慧財產權益，同時透過培養閱讀習慣、盡情創作與寫作，一同慶祝這個特別的日子，讀享書本的迷人美好！本書展精選閱讀、經典文學、繪本類等相關書目，歡迎閱覽！', '臺中市立圖書館清水分館', '臺中市清水區', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '清水區（臺中市）=', 24.29205743, 120.5809094, '無資料', 'https://reurl.cc/EVZW8v', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖清水分館】4月-2025世界閱讀日-遨遊書海主題書展', `description`='你/妳今天閱讀了嗎? 逢四月二十三日「世界閱讀日（World Book Day）」及「世界讀書及版權日（World Book And Copyright Day)」的來臨，讓我們趁此關注閱讀、圖書出版、編輯與智慧財產權益，同時透過培養閱讀習慣、盡情創作與寫作，一同慶祝這個特別的日子，讀享書本的迷人美好！本書展精選閱讀、經典文學、繪本類等相關書目，歡迎閱覽！', `organizer`='臺中市立圖書館清水分館', `address`='臺中市清水區', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='清水區（臺中市）=', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://reurl.cc/EVZW8v', `image_url`='[]';
