INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19e26b3242b74a3ade9', '森林油畫展', '森林油畫展	\r\n\r\n4/13(日)~4/27(日) 08:30~21:00		\r\n\r\n展出畫家方有石以百年荔枝森林為主的油畫作品;讓大家對百年荔枝森林有進一步的認識。\r\n', '臺中市立圖書館太平坪林分館', '臺中市太平區中山路一段213號', '2025-04-13 00:00:00', '2025-04-27 00:00:00', '臺中市立圖書館太平坪林分館', 24.11477375, 120.7734217, '無資料', 'https://reurl.cc/QY6G5q', '[]') ON DUPLICATE KEY UPDATE `activity_name`='森林油畫展', `description`='森林油畫展	\r\n\r\n4/13(日)~4/27(日) 08:30~21:00		\r\n\r\n展出畫家方有石以百年荔枝森林為主的油畫作品;讓大家對百年荔枝森林有進一步的認識。\r\n', `organizer`='臺中市立圖書館太平坪林分館', `address`='臺中市太平區中山路一段213號', `start_date`='2025-04-13 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺中市立圖書館太平坪林分館', `latitude`=24.11477375, `longitude`=120.7734217, `ticket_price`='無資料', `source_url`='https://reurl.cc/QY6G5q', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19e26b3242b74a3adea', '臺中市南屯親子館（114年4月繪本故事書13場）', '114年4月份行事曆出爐\r\n本月主題:重返舊時光\r\n時間像小精靈一樣好多好玩的東西唷，也有很多很多珍貴的回憶……\r\n現在，就讓我們一起搭上時光列車!出發吧~\r\n遊戲區上限共為68組\r\n(以寶貝為單位)(分別為網路/現場)\r\n網路預約48組\r\n https://reurl.cc/XqX8oa\r\n(於三天前中午12時開放預約，當日無網路預約)\r\n當日現場登記20組\r\n(上下午場次開館前5分鐘開始登記)\r\n四月份報名親子活動\r\n預約https://reurl.cc/Vz0W6N\r\n親子活動(藍色字體):前一週中午12點開放育兒資源網報名\r\n各項活動請查閱相關活動須知及海報', '臺中市政府社會局', '臺中市南屯區', '2025-04-02 00:00:00', '2025-04-30 00:00:00', '南屯區（臺中市）=', 24.14165524, 120.6177379, '無資料', 'https://user271806.pse.is/7cafru', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市南屯親子館（114年4月繪本故事書13場）', `description`='114年4月份行事曆出爐\r\n本月主題:重返舊時光\r\n時間像小精靈一樣好多好玩的東西唷，也有很多很多珍貴的回憶……\r\n現在，就讓我們一起搭上時光列車!出發吧~\r\n遊戲區上限共為68組\r\n(以寶貝為單位)(分別為網路/現場)\r\n網路預約48組\r\n https://reurl.cc/XqX8oa\r\n(於三天前中午12時開放預約，當日無網路預約)\r\n當日現場登記20組\r\n(上下午場次開館前5分鐘開始登記)\r\n四月份報名親子活動\r\n預約https://reurl.cc/Vz0W6N\r\n親子活動(藍色字體):前一週中午12點開放育兒資源網報名\r\n各項活動請查閱相關活動須知及海報', `organizer`='臺中市政府社會局', `address`='臺中市南屯區', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://user271806.pse.is/7cafru', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19e26b3242b74a3adeb', '臺中市北區親子館（114年4月繪本故事書15場）', '114年4月行事曆\r\n四月！是每年孩子們最期待的月份\r\n親子館即將聯合舉辦兒童聯歡派對\r\n各館舍也有兒童節相關小活動～～\r\n歡迎各位親子們一起來找我們玩唷\r\n以下為4月份的行事曆，請大家詳閱以下資訊，敬請配合唷❣\r\n出外要記得勤洗手，保護好自己也可以保護別人喔!\r\n每週一固定休館！\r\n4/1(二)大消毒日\r\n4/3(四)清明節\r\n4/4(五)兒童節\r\n4/12(六)上午不開放現場入館\r\n4/20(日)臺中市親子館聯合宣導活動\r\n借閱教具服務將於2/18開始恢復借閱\r\n煩請各位寶貝們來辦理借閱證、借閱教玩具回家玩要留意時間哦', '臺中市政府社會局', '臺中市北區', '2025-04-02 00:00:00', '2025-04-30 00:00:00', '北區（臺中市）=', 24.15863985, 120.6809521, '無資料', 'https://user271806.pse.is/7cajnc', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市北區親子館（114年4月繪本故事書15場）', `description`='114年4月行事曆\r\n四月！是每年孩子們最期待的月份\r\n親子館即將聯合舉辦兒童聯歡派對\r\n各館舍也有兒童節相關小活動～～\r\n歡迎各位親子們一起來找我們玩唷\r\n以下為4月份的行事曆，請大家詳閱以下資訊，敬請配合唷❣\r\n出外要記得勤洗手，保護好自己也可以保護別人喔!\r\n每週一固定休館！\r\n4/1(二)大消毒日\r\n4/3(四)清明節\r\n4/4(五)兒童節\r\n4/12(六)上午不開放現場入館\r\n4/20(日)臺中市親子館聯合宣導活動\r\n借閱教具服務將於2/18開始恢復借閱\r\n煩請各位寶貝們來辦理借閱證、借閱教玩具回家玩要留意時間哦', `organizer`='臺中市政府社會局', `address`='臺中市北區', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='北區（臺中市）=', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://user271806.pse.is/7cajnc', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19e26b3242b74a3adec', '【大里分館】04/26 故事魔法快樂屋-說故事', '故事志工講述繪本故事，增進閱讀樂趣。故事繪本:「賽米希的煩惱」、「貓熊小湯匙和貓熊平底鍋」、「蝸牛美美想獨處」，歡迎親子一起來聽故事。', '臺中市立圖書館大里分館', '臺中市大里區中興路一段163號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '臺中市立圖書館大里分館', 24.09575742, 120.6926261, '無資料', 'https://reurl.cc/DqZlNR', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【大里分館】04/26 故事魔法快樂屋-說故事', `description`='故事志工講述繪本故事，增進閱讀樂趣。故事繪本:「賽米希的煩惱」、「貓熊小湯匙和貓熊平底鍋」、「蝸牛美美想獨處」，歡迎親子一起來聽故事。', `organizer`='臺中市立圖書館大里分館', `address`='臺中市大里區中興路一段163號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='臺中市立圖書館大里分館', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://reurl.cc/DqZlNR', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19e26b3242b74a3adee', '石雨集114年聯展', '分別來自台中山線，石岡和霧峰的朋友，以家鄉名字的「首字」和「字首」發想成了這個興趣的交遊集合，「石雨集」。意象中石頭承受著雨水的潤澤，有硬氣也有柔情，在迷濛中自見迸放的光芒。', '臺中市西屯區公所', '臺中市西屯區市政北二路386號', '2025-03-18 00:00:00', '2025-12-30 00:00:00', '臺中市西屯區公所', 24.1654462, 120.6337766, '無資料', 'https://www.xitun.taichung.gov.tw/3629938/post', '[]') ON DUPLICATE KEY UPDATE `activity_name`='石雨集114年聯展', `description`='分別來自台中山線，石岡和霧峰的朋友，以家鄉名字的「首字」和「字首」發想成了這個興趣的交遊集合，「石雨集」。意象中石頭承受著雨水的潤澤，有硬氣也有柔情，在迷濛中自見迸放的光芒。', `organizer`='臺中市西屯區公所', `address`='臺中市西屯區市政北二路386號', `start_date`='2025-03-18 00:00:00', `end_date`='2025-12-30 00:00:00', `location`='臺中市西屯區公所', `latitude`=24.1654462, `longitude`=120.6337766, `ticket_price`='無資料', `source_url`='https://www.xitun.taichung.gov.tw/3629938/post', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19e26b3242b74a3adef', '狂美親子音樂劇場《射日傳說》', '泰雅族為臺灣第三大的原住民族群，狂美挑戰其古老神話「射日」之傳說。透過知名作曲家-李佳盈的量身譜曲，與戲劇、雜技的精彩結合。演繹充滿泰雅古調的樂音，真實寫意每個山水意象，讓您在音符中聽見原民的脈動與情感！傳說故事與音樂劇場感動結合，是您絕對不容錯過的音樂劇場作品！捎上您的想像，跟著狂美的腳步，帶您壯、遊、原、鄉。', '狂美交響管樂團', '臺中市西屯區惠來路二段101號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '臺中國家歌劇院', 24.1630875, 120.6404343, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='狂美親子音樂劇場《射日傳說》', `description`='泰雅族為臺灣第三大的原住民族群，狂美挑戰其古老神話「射日」之傳說。透過知名作曲家-李佳盈的量身譜曲，與戲劇、雜技的精彩結合。演繹充滿泰雅古調的樂音，真實寫意每個山水意象，讓您在音符中聽見原民的脈動與情感！傳說故事與音樂劇場感動結合，是您絕對不容錯過的音樂劇場作品！捎上您的想像，跟著狂美的腳步，帶您壯、遊、原、鄉。', `organizer`='狂美交響管樂團', `address`='臺中市西屯區惠來路二段101號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='臺中國家歌劇院', `latitude`=24.1630875, `longitude`=120.6404343, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19e26b3242b74a3adf0', '【中市圖清水分館】4月-台語說故事活動', '【台語說故事爸媽】\r\n為促進民眾深度了解母語文化，進而認同及提升母語使用能力，臺中市立圖書館規劃辦理「臺語說演故事」活動，在圖書館營造說臺語的環境，以強化母語傳承在地文化的獨特性。歡迎大朋友小朋友作伙來聽故事、學台語。\r\n▎時間：4/19(六)14:00-15:00\r\n▎地點：臺中市港區藝術中心會議室B\r\n▎講師：楊焜顯老師\r\n▎故事主題：\r\n1-燈塔的故事:奇妙的海邊生活\r\n2-燈塔你好\r\n3-以光為家 : 燈塔人的故事\r\n\r\n▎內容簡介：\r\n嘩拉嘩拉的波浪圍繞著海中的礁石島，伊娃的爺爺就住在島上的燈塔裡……請來跟伊娃一起體驗住在燈塔裡的生活。\r\n管理燈塔是很重要的工作，要很早起床是為了觀察海灣的情況，很晚睡覺則是為了引導船隻在黑暗裡平安返家。有些夜晚，狂風暴雨來襲……不但介紹燈塔內部設施，加上真實的英勇海上救援故事，帶領讀者感受認識燈塔的守護者的工作。\r\n※ 此為台語說故事，歡迎自由參加。', '臺中市立圖書館清水分館', '臺中市清水區忠貞路21號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '臺中市港區藝術中心', 24.29205743, 120.5809094, '無資料', 'https://reurl.cc/vQgoDL', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【中市圖清水分館】4月-台語說故事活動', `description`='【台語說故事爸媽】\r\n為促進民眾深度了解母語文化，進而認同及提升母語使用能力，臺中市立圖書館規劃辦理「臺語說演故事」活動，在圖書館營造說臺語的環境，以強化母語傳承在地文化的獨特性。歡迎大朋友小朋友作伙來聽故事、學台語。\r\n▎時間：4/19(六)14:00-15:00\r\n▎地點：臺中市港區藝術中心會議室B\r\n▎講師：楊焜顯老師\r\n▎故事主題：\r\n1-燈塔的故事:奇妙的海邊生活\r\n2-燈塔你好\r\n3-以光為家 : 燈塔人的故事\r\n\r\n▎內容簡介：\r\n嘩拉嘩拉的波浪圍繞著海中的礁石島，伊娃的爺爺就住在島上的燈塔裡……請來跟伊娃一起體驗住在燈塔裡的生活。\r\n管理燈塔是很重要的工作，要很早起床是為了觀察海灣的情況，很晚睡覺則是為了引導船隻在黑暗裡平安返家。有些夜晚，狂風暴雨來襲……不但介紹燈塔內部設施，加上真實的英勇海上救援故事，帶領讀者感受認識燈塔的守護者的工作。\r\n※ 此為台語說故事，歡迎自由參加。', `organizer`='臺中市立圖書館清水分館', `address`='臺中市清水區忠貞路21號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='臺中市港區藝術中心', `latitude`=24.29205743, `longitude`=120.5809094, `ticket_price`='無資料', `source_url`='https://reurl.cc/vQgoDL', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19e26b3242b74a3adf1', '臺中市大里親子館（114年4月繪本故事書5場）', '「114年4月份活動行事曆」\r\n親愛的爸爸媽媽與寶貝你們好：本館4月份主題為「媽媽的紅沙發」，引導孩子察覺與表達的各種情緒、使用故事、圖畫或手工表達對家庭的感受、分辨並命名基本情緒（如快樂、悲傷、生氣），同時帶出生命教育的相關議題。\r\n托育資源行動車的據點服務也會提供很多不同遊戲，快點看看哪個據點比較近，活動前一周開放報名，歡迎跟我們一起玩喔！\r\n4/1(二)消毒日，不對外開放\r\n4/3(四)-4/4(五)清明節、兒童節休館\r\n4/20(日)前往社區辦理臺中市親子館聯合宣導，上下午入館暫停\r\n4/27(日)辦理「童權起步走」兒童節親子活動，上下午入館暫停', '臺中市政府社會局', '臺中市大里區', '2025-04-06 00:00:00', '2025-04-24 00:00:00', '大里區（臺中市）=', 24.09575742, 120.6926261, '無資料', 'https://user271806.pse.is/7ccaj8', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市大里親子館（114年4月繪本故事書5場）', `description`='「114年4月份活動行事曆」\r\n親愛的爸爸媽媽與寶貝你們好：本館4月份主題為「媽媽的紅沙發」，引導孩子察覺與表達的各種情緒、使用故事、圖畫或手工表達對家庭的感受、分辨並命名基本情緒（如快樂、悲傷、生氣），同時帶出生命教育的相關議題。\r\n托育資源行動車的據點服務也會提供很多不同遊戲，快點看看哪個據點比較近，活動前一周開放報名，歡迎跟我們一起玩喔！\r\n4/1(二)消毒日，不對外開放\r\n4/3(四)-4/4(五)清明節、兒童節休館\r\n4/20(日)前往社區辦理臺中市親子館聯合宣導，上下午入館暫停\r\n4/27(日)辦理「童權起步走」兒童節親子活動，上下午入館暫停', `organizer`='臺中市政府社會局', `address`='臺中市大里區', `start_date`='2025-04-06 00:00:00', `end_date`='2025-04-24 00:00:00', `location`='大里區（臺中市）=', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://user271806.pse.is/7ccaj8', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19f26b3242b74a3adf2', '臺中市大甲親子館（114年4月繪本故事書10場）', '4月的行事曆出爐拉\r\n老師們每個月都會在行事曆打上休館的日期\r\n0401 消毒日，休館一日(電話服務正常)\r\n0413 大甲媽祖回鑾，休館一日，可以到神岡圖書館找我們玩\r\n0420 2025親子歡樂派對，休館一日，我們在文心森林公園唷\r\n記好異動時間，開館時間再來找老師玩唷', '臺中市政府社會局', '臺中市大甲區', '2025-04-02 00:00:00', '2025-04-29 00:00:00', '大甲區（臺中市）=', 24.37827161, 120.6357901, '無資料', 'https://user271806.pse.is/7ccm4q', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市大甲親子館（114年4月繪本故事書10場）', `description`='4月的行事曆出爐拉\r\n老師們每個月都會在行事曆打上休館的日期\r\n0401 消毒日，休館一日(電話服務正常)\r\n0413 大甲媽祖回鑾，休館一日，可以到神岡圖書館找我們玩\r\n0420 2025親子歡樂派對，休館一日，我們在文心森林公園唷\r\n記好異動時間，開館時間再來找老師玩唷', `organizer`='臺中市政府社會局', `address`='臺中市大甲區', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='大甲區（臺中市）=', `latitude`=24.37827161, `longitude`=120.6357901, `ticket_price`='無資料', `source_url`='https://user271806.pse.is/7ccm4q', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19f26b3242b74a3adf3', '光的名字｜大岡弘晃', '光的名字｜大岡弘晃\r\n展覽期間：3,29 - 4,20 2025\r\n開幕茶會：3,29 3pm - 5pm\r\n企劃協力：DIGINNER GALLERY\r\n｜光の名前｜   |光之名 |\r\n自出生的那一刻起，便對自己的性別感到困惑。那柔弱的身驅。\r\n總是被訓斥要更像男子漢。被迫矯正成不是真我的樣貌 。\r\n自出生的那一刻起，便對自己的存在感到迷惘。每天都思索著，若自己從未來到這世上該有多好。\r\n曾以為，從未有人祝福我的誕生，無論是家人，或甚至是母親。\r\n直到生命中無數的相遇與覺醒，讓我能將這些苦難化為光芒，\r\n讓我明白每個人的誕生都被某種形式所祝福。\r\n此時，我決定以光之名、以光之色彩，向曾經困惑的自己，向所有與我同樣迷惘的靈魂，傳遞如同擁抱般溫暖的訊息，不斷送出對生命誕生的祝福。\r\n願我們能早日察覺自身的誤解。\r\n願我們能早日發現，總有人在祝福我們的存在。\r\n所有的誕生，都值得祝福／所有曾經的存在，也都值得祝福。\r\n\r\n#個展  #平面繪畫  #多元媒材', 'ZASSO 草也', '臺中市西區', '2025-03-29 00:00:00', '2025-04-20 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/5K2a5V', '[]') ON DUPLICATE KEY UPDATE `activity_name`='光的名字｜大岡弘晃', `description`='光的名字｜大岡弘晃\r\n展覽期間：3,29 - 4,20 2025\r\n開幕茶會：3,29 3pm - 5pm\r\n企劃協力：DIGINNER GALLERY\r\n｜光の名前｜   |光之名 |\r\n自出生的那一刻起，便對自己的性別感到困惑。那柔弱的身驅。\r\n總是被訓斥要更像男子漢。被迫矯正成不是真我的樣貌 。\r\n自出生的那一刻起，便對自己的存在感到迷惘。每天都思索著，若自己從未來到這世上該有多好。\r\n曾以為，從未有人祝福我的誕生，無論是家人，或甚至是母親。\r\n直到生命中無數的相遇與覺醒，讓我能將這些苦難化為光芒，\r\n讓我明白每個人的誕生都被某種形式所祝福。\r\n此時，我決定以光之名、以光之色彩，向曾經困惑的自己，向所有與我同樣迷惘的靈魂，傳遞如同擁抱般溫暖的訊息，不斷送出對生命誕生的祝福。\r\n願我們能早日察覺自身的誤解。\r\n願我們能早日發現，總有人在祝福我們的存在。\r\n所有的誕生，都值得祝福／所有曾經的存在，也都值得祝福。\r\n\r\n#個展  #平面繪畫  #多元媒材', `organizer`='ZASSO 草也', `address`='臺中市西區', `start_date`='2025-03-29 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/5K2a5V', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19f26b3242b74a3adf6', '境遇ー陳世強・張秉正雙個展', ' 國立中興大學藝術中心自114年4月10日(四)至5月16日(五)舉辦「境遇—陳世強・張秉正雙個展」，展出兩位藝術家不同人生時期的藝術創作，不論是在畫面上的動線運筆，或者圖像背後的起心動念，皆蘊含著他們生命經驗的紀錄與時代文化記憶，讓創作不只是美感的呈現，更體現出「為何而畫，而不是如何畫」的自我實踐。\r\n\r\n陳世強，1967年宜蘭出生，國立臺灣師範大學美術學系、美國紐約大學藝術碩士畢業，現任國立彰化師範大學美術學系教授。陳世強作品媒材多元，常以普普藝術、漫畫風格來反映社會時事或人生經歷的片段，同時具有策展專業，擔任或主持過宜蘭人故事館「記憶河流」、總統府「宜蘭水家鄉－總統府宜蘭文化展」、國史館台灣文獻館「烽火歲月－戰時體制下的臺灣史料特展」等多項重要策展活動；建置多件知名公共藝術作品，亦受邀至日本京都美術館、美國紐約市皇后區美術館、韓國光州美術館及宜蘭美術館等國內外場館展出。曾獲美國紐約大學藝術獎、臺北市美展油畫類第一名等獎項，創作與教學兼擅。\r\n\r\n張秉正，1965年彰化溪州出生，國立臺灣師範大學美術學系、國立臺南藝術學院造形藝術研究所碩士畢業，現任關西高中美術教師。水墨師從鄭善禧教授的皺染運筆，後受劉國松大師現代繪畫的創新觀念，不拘泥於學院框架而自我養成。張秉正水墨作品早期具表現或抽象寫形的實驗風格，之後藉人生及創作歷練，抒發己性，反映社會，構圖看似嚴肅沈鬱，卻又將自我表徵隱藏其中，透露著幽默荒誕的氣息，也陳述出畫家內心情感與省思。曾應邀於臺北市立美術館、臺北美國文化中心、美國紐約市皇后區美術館、華山創意園區、新竹市文化局、宜蘭故事館等多地展出，備受好評。除專注創作外，亦深耕於美術教育。\r\n\r\n雖然兩位藝術家是西畫與水墨畫的殊域分途，各司其趣，但在創作思維上卻同為不期而遇的二造觀看，即以「冷觀旁清，涉身局迷」作為近距離觀察與審視。二人皆來自豐富的學院背景，但卻有不同的形式發展。陳世強早期的表現主義到後來的類普普風格，畫中帶有某種流動性與速度感，這源自往返臺灣東部與中部的身分游移，從早期〈臺北的天空〉、中期〈強氣少年〉及後來的〈漫遊記〉等，從諸多時空元素轉化為其繪畫性鋪陳；張秉正從渾重皺法的文人畫風與寓言式的表現體裁，擦染出對外在世界的內在感受，勾繪出如心身翻攪的慾望山水，如1995年的〈悠然山〉與2019年的〈山有虎〉作品。\r\n\r\n不同人生劇本的畫家也可同場配樂共舞，隨謀而遇。透過持續創作，紀錄走過的每一段時光，對應其境遇與觀看角度，覺察著各種變遷與議題，希望透過展覽讓具有不同身分與文化背景的觀眾能一同探討，交流不同想法，成為藝術家創作的養分，重新審視創作本質，期待「非境之遇，莫忘初衷」\r\n\r\n#雙個展  #水墨  #油畫  #水彩', '國立中興大學藝術中心', '臺中市南區興大路145號', '2025-04-10 00:00:00', '2025-05-16 00:00:00', '國立中興大學', 24.12114107, 120.6646178, '無資料', 'https://reurl.cc/Z4jLAV', '[]') ON DUPLICATE KEY UPDATE `activity_name`='境遇ー陳世強・張秉正雙個展', `description`=' 國立中興大學藝術中心自114年4月10日(四)至5月16日(五)舉辦「境遇—陳世強・張秉正雙個展」，展出兩位藝術家不同人生時期的藝術創作，不論是在畫面上的動線運筆，或者圖像背後的起心動念，皆蘊含著他們生命經驗的紀錄與時代文化記憶，讓創作不只是美感的呈現，更體現出「為何而畫，而不是如何畫」的自我實踐。\r\n\r\n陳世強，1967年宜蘭出生，國立臺灣師範大學美術學系、美國紐約大學藝術碩士畢業，現任國立彰化師範大學美術學系教授。陳世強作品媒材多元，常以普普藝術、漫畫風格來反映社會時事或人生經歷的片段，同時具有策展專業，擔任或主持過宜蘭人故事館「記憶河流」、總統府「宜蘭水家鄉－總統府宜蘭文化展」、國史館台灣文獻館「烽火歲月－戰時體制下的臺灣史料特展」等多項重要策展活動；建置多件知名公共藝術作品，亦受邀至日本京都美術館、美國紐約市皇后區美術館、韓國光州美術館及宜蘭美術館等國內外場館展出。曾獲美國紐約大學藝術獎、臺北市美展油畫類第一名等獎項，創作與教學兼擅。\r\n\r\n張秉正，1965年彰化溪州出生，國立臺灣師範大學美術學系、國立臺南藝術學院造形藝術研究所碩士畢業，現任關西高中美術教師。水墨師從鄭善禧教授的皺染運筆，後受劉國松大師現代繪畫的創新觀念，不拘泥於學院框架而自我養成。張秉正水墨作品早期具表現或抽象寫形的實驗風格，之後藉人生及創作歷練，抒發己性，反映社會，構圖看似嚴肅沈鬱，卻又將自我表徵隱藏其中，透露著幽默荒誕的氣息，也陳述出畫家內心情感與省思。曾應邀於臺北市立美術館、臺北美國文化中心、美國紐約市皇后區美術館、華山創意園區、新竹市文化局、宜蘭故事館等多地展出，備受好評。除專注創作外，亦深耕於美術教育。\r\n\r\n雖然兩位藝術家是西畫與水墨畫的殊域分途，各司其趣，但在創作思維上卻同為不期而遇的二造觀看，即以「冷觀旁清，涉身局迷」作為近距離觀察與審視。二人皆來自豐富的學院背景，但卻有不同的形式發展。陳世強早期的表現主義到後來的類普普風格，畫中帶有某種流動性與速度感，這源自往返臺灣東部與中部的身分游移，從早期〈臺北的天空〉、中期〈強氣少年〉及後來的〈漫遊記〉等，從諸多時空元素轉化為其繪畫性鋪陳；張秉正從渾重皺法的文人畫風與寓言式的表現體裁，擦染出對外在世界的內在感受，勾繪出如心身翻攪的慾望山水，如1995年的〈悠然山〉與2019年的〈山有虎〉作品。\r\n\r\n不同人生劇本的畫家也可同場配樂共舞，隨謀而遇。透過持續創作，紀錄走過的每一段時光，對應其境遇與觀看角度，覺察著各種變遷與議題，希望透過展覽讓具有不同身分與文化背景的觀眾能一同探討，交流不同想法，成為藝術家創作的養分，重新審視創作本質，期待「非境之遇，莫忘初衷」\r\n\r\n#雙個展  #水墨  #油畫  #水彩', `organizer`='國立中興大學藝術中心', `address`='臺中市南區興大路145號', `start_date`='2025-04-10 00:00:00', `end_date`='2025-05-16 00:00:00', `location`='國立中興大學', `latitude`=24.12114107, `longitude`=120.6646178, `ticket_price`='無資料', `source_url`='https://reurl.cc/Z4jLAV', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19f26b3242b74a3adf7', '【新北市立圖書館新店分館】114年4月主題書展:男女大不同', '男女的天生差異是認識男女一生的功課，讓男人與女人和諧共處，快樂生活不妨花點時間認識不同性別的差異，不管在職場或是家庭，為了彼此間的關係而努力，必能擁有美好的結果！\r\n\r\n展出時間：4月1日至4月30日 開館時間\r\n         4月3、4及24日   不對外開放\r\n展出地點：新北市立圖書館新店分館主題書展區\r\n         新北市新店區北新路三段105巷2號3樓\r\n書展示期間 可外借\r\n', '新北市立圖書館總館', '新北市新店區北新路三段105巷2號3樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館新店分館', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店分館】114年4月主題書展:男女大不同', `description`='男女的天生差異是認識男女一生的功課，讓男人與女人和諧共處，快樂生活不妨花點時間認識不同性別的差異，不管在職場或是家庭，為了彼此間的關係而努力，必能擁有美好的結果！\r\n\r\n展出時間：4月1日至4月30日 開館時間\r\n         4月3、4及24日   不對外開放\r\n展出地點：新北市立圖書館新店分館主題書展區\r\n         新北市新店區北新路三段105巷2號3樓\r\n書展示期間 可外借\r\n', `organizer`='新北市立圖書館總館', `address`='新北市新店區北新路三段105巷2號3樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館新店分館', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb19f26b3242b74a3adf8', '【新北市立圖書館新店寶興圖書閱覽室】114年4月主題書展:閱讀新住民', '關於新住民已經有愈來愈多人生活在我們身邊，認識不同的新住民文化部但有益於增進彼此的認識，對於擴展社交領域也十分有幫助，天涯若比鄰的時代讓我們有更多機會認識彼此，十分可貴!\r\n\r\n展出時間：4月1日至4月30日 開館時間\r\n         4月3、4及24日   不對外開放\r\n展出地點：新北市立圖書館新店區寶興圖書閱覽室主題書展區\r\n         新北市新店區寶中路65巷59號3樓\r\n\r\n展出期間 圖書可外借', '新北市立圖書館總館', '新北市新店區寶中路65巷59號3樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館新店寶興圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店寶興圖書閱覽室】114年4月主題書展:閱讀新住民', `description`='關於新住民已經有愈來愈多人生活在我們身邊，認識不同的新住民文化部但有益於增進彼此的認識，對於擴展社交領域也十分有幫助，天涯若比鄰的時代讓我們有更多機會認識彼此，十分可貴!\r\n\r\n展出時間：4月1日至4月30日 開館時間\r\n         4月3、4及24日   不對外開放\r\n展出地點：新北市立圖書館新店區寶興圖書閱覽室主題書展區\r\n         新北市新店區寶中路65巷59號3樓\r\n\r\n展出期間 圖書可外借', `organizer`='新北市立圖書館總館', `address`='新北市新店區寶中路65巷59號3樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館新店寶興圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a026b3242b74a3adf9', '書法的自覺性與互動性', '#書法 #講座 #當代書法\r\n\r\n【書法共好時代 3.0 春季講座】由游翰堂與臺中市書法學會共同舉辦，本場特邀華梵大學人文與藝術學院院長黃智陽老師主講「書法的自覺性與互動性」。黃老師長期致力於書法當代表現、美感轉譯與文化素養教育，具有豐富的創作與策展經歷，亦是推動書法跨領域實踐的重要推手。活動將以實體與線上同步進行，歡迎對書法與藝術教育有興趣的朋友共襄盛舉。', '臺中市書法學會', '臺中市西屯區文華路100號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '逢甲大學', 24.18308895, 120.6270131, '無資料', 'https://reurl.cc/qG1WYg', '[]') ON DUPLICATE KEY UPDATE `activity_name`='書法的自覺性與互動性', `description`='#書法 #講座 #當代書法\r\n\r\n【書法共好時代 3.0 春季講座】由游翰堂與臺中市書法學會共同舉辦，本場特邀華梵大學人文與藝術學院院長黃智陽老師主講「書法的自覺性與互動性」。黃老師長期致力於書法當代表現、美感轉譯與文化素養教育，具有豐富的創作與策展經歷，亦是推動書法跨領域實踐的重要推手。活動將以實體與線上同步進行，歡迎對書法與藝術教育有興趣的朋友共襄盛舉。', `organizer`='臺中市書法學會', `address`='臺中市西屯區文華路100號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='逢甲大學', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://reurl.cc/qG1WYg', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a026b3242b74a3adfa', '岩上之雲 Ecclesiastes｜鹿向夷 個展', '#膠彩 #天然礦物 #個展\r\n\r\n本次個展《岩上之雲 Ecclesiastes》為藝術家鹿向夷於2024年前往北印度與尼泊爾邊境地區進行長達90日的田野研究後之創作呈現。藝術家以親身徒步喜馬拉雅山脈、平均海拔4,700公尺的地貌經驗，記錄光影、地景與身體感知之間的關係。創作媒材採用當地所採集的泥土、岩石、天然礦物顏料，透過層疊、刮刻、漿洗等工法，於紙上再現遼闊與細縫交錯的視覺感受。作品展現藝術家在地書寫與文化觀察的深入，探索人在邊境地帶的研究、行走與融入之間的關係動態。', '雨果曐Gallery', '臺中市西區', '2025-03-27 00:00:00', '2025-05-03 00:00:00', '西區（臺中市）=', 24.14391082, 120.6647579, '無資料', 'https://reurl.cc/DqZrrQ', '[]') ON DUPLICATE KEY UPDATE `activity_name`='岩上之雲 Ecclesiastes｜鹿向夷 個展', `description`='#膠彩 #天然礦物 #個展\r\n\r\n本次個展《岩上之雲 Ecclesiastes》為藝術家鹿向夷於2024年前往北印度與尼泊爾邊境地區進行長達90日的田野研究後之創作呈現。藝術家以親身徒步喜馬拉雅山脈、平均海拔4,700公尺的地貌經驗，記錄光影、地景與身體感知之間的關係。創作媒材採用當地所採集的泥土、岩石、天然礦物顏料，透過層疊、刮刻、漿洗等工法，於紙上再現遼闊與細縫交錯的視覺感受。作品展現藝術家在地書寫與文化觀察的深入，探索人在邊境地帶的研究、行走與融入之間的關係動態。', `organizer`='雨果曐Gallery', `address`='臺中市西區', `start_date`='2025-03-27 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='西區（臺中市）=', `latitude`=24.14391082, `longitude`=120.6647579, `ticket_price`='無資料', `source_url`='https://reurl.cc/DqZrrQ', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a026b3242b74a3adfb', '「風兒輕輕地吹」徐凡軒 展', '《風兒輕輕地吹》為藝術家徐凡軒於鶴軒藝術舉辦的個展，透過藍灰色調與細膩筆觸，描繪山巒、水面與夜色間靜謐而療癒的氛圍。作品以岩繪具與雲肌麻紙為媒材，呈現自然風景與內心情感的深層對話。藝術家將自身療癒旅程化為視覺語言，引領觀者進入如夢似幻的山水寂境，感受風靜止後的安寧與溫柔的包圍。\r\n\r\n#水墨  #膠彩 #個展', '臺中市鶴軒藝術', '臺中市西屯區惠來路二段90號1~3F、18F', '2025-04-05 00:00:00', '2025-05-04 00:00:00', '鶴軒藝術(歌劇店)', 24.18308895, 120.6270131, '無資料', 'https://reurl.cc/eMmYmK', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「風兒輕輕地吹」徐凡軒 展', `description`='《風兒輕輕地吹》為藝術家徐凡軒於鶴軒藝術舉辦的個展，透過藍灰色調與細膩筆觸，描繪山巒、水面與夜色間靜謐而療癒的氛圍。作品以岩繪具與雲肌麻紙為媒材，呈現自然風景與內心情感的深層對話。藝術家將自身療癒旅程化為視覺語言，引領觀者進入如夢似幻的山水寂境，感受風靜止後的安寧與溫柔的包圍。\r\n\r\n#水墨  #膠彩 #個展', `organizer`='臺中市鶴軒藝術', `address`='臺中市西屯區惠來路二段90號1~3F、18F', `start_date`='2025-04-05 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='鶴軒藝術(歌劇店)', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://reurl.cc/eMmYmK', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a026b3242b74a3adfc', '【新北市立圖書館新店仁愛圖書閱覽室】114年4月主題書展:蘭嶼飛魚季', '捕捉飛魚是蘭嶼雅美/達悟族的傳統文化。每年春季，飛魚族群隨著黑潮來到蘭嶼附近海域時，蘭嶼人便開始了他們的飛魚季。從每年二至三月舉行飛魚招魚祭，到九月的飛魚終食祭為止，都可以說是飛魚季，共有飛魚招魚祭、飛魚收藏祭、飛魚終食祭等活動；而飛魚與飛魚乾也為這時期的主要食物。\r\n\r\n　\r\n展出時間：4月1日至4月30日 開館時間\r\n         4月3、4及24日   不對外開放\r\n展出地點：新北市立圖書館新店仁愛圖書閱覽室書展區\r\n         新店區建國路58號2樓\r\n\r\n展出期間 可外借', '新北市立圖書館總館', '新北市新店區建國路58號2樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館新店仁愛圖書閱覽室', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館新店仁愛圖書閱覽室】114年4月主題書展:蘭嶼飛魚季', `description`='捕捉飛魚是蘭嶼雅美/達悟族的傳統文化。每年春季，飛魚族群隨著黑潮來到蘭嶼附近海域時，蘭嶼人便開始了他們的飛魚季。從每年二至三月舉行飛魚招魚祭，到九月的飛魚終食祭為止，都可以說是飛魚季，共有飛魚招魚祭、飛魚收藏祭、飛魚終食祭等活動；而飛魚與飛魚乾也為這時期的主要食物。\r\n\r\n　\r\n展出時間：4月1日至4月30日 開館時間\r\n         4月3、4及24日   不對外開放\r\n展出地點：新北市立圖書館新店仁愛圖書閱覽室書展區\r\n         新店區建國路58號2樓\r\n\r\n展出期間 可外借', `organizer`='新北市立圖書館總館', `address`='新北市新店區建國路58號2樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館新店仁愛圖書閱覽室', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
