INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a026b3242b74a3adff', '【五股守讓堂】2025新北詩歌節【詩學講座3】「尋找一首詩」/蔡素芬', '地址：板橋總館(新北市板橋區貴興路139號3樓)\r\n電話：02-22953212\r\n講題：◣詩學講座3◢：「尋找一首詩」/蔡素芬\r\n\r\n新北詩歌節 4/19\r\n蔡素芬講座／「尋找一首詩」\r\n詩，是一場尋找的旅程—尋找字詞的光亮，尋找內心的回音。\r\n\r\n4/19詩人蔡素芬將在新北市立圖書館板橋總館帶來講座「尋找一首詩」，與讀者一同探索詩歌的靈感與秘密。\r\n從小說到詩，蔡素芬的文字總能觸動人心。在這場講座中，蔡素芬將分享她的創作歷程，以及詩歌如何成為我們理解世界與自身的一扇窗。\r\n\r\n活動資訊時間｜2025年4月19日(六)14:00-16:00\r\n地點｜新北市立圖書館總館3樓演藝廳\r\n報名連結|https://www.beclass.com/rid=294fe6267a9710ec2fa8\r\n誠摯邀請喜愛詩歌與文學的你，一起來聆聽、感受詩的力量！\r\n\r\n① 報名＋出席 現場抽【限量好禮或詩人著作】\r\n② 出席＋集點 換【詩意好禮】', '新北市立圖書館總館', '新北市板橋區貴興路139號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '新北市立圖書館總館', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【五股守讓堂】2025新北詩歌節【詩學講座3】「尋找一首詩」/蔡素芬', `description`='地址：板橋總館(新北市板橋區貴興路139號3樓)\r\n電話：02-22953212\r\n講題：◣詩學講座3◢：「尋找一首詩」/蔡素芬\r\n\r\n新北詩歌節 4/19\r\n蔡素芬講座／「尋找一首詩」\r\n詩，是一場尋找的旅程—尋找字詞的光亮，尋找內心的回音。\r\n\r\n4/19詩人蔡素芬將在新北市立圖書館板橋總館帶來講座「尋找一首詩」，與讀者一同探索詩歌的靈感與秘密。\r\n從小說到詩，蔡素芬的文字總能觸動人心。在這場講座中，蔡素芬將分享她的創作歷程，以及詩歌如何成為我們理解世界與自身的一扇窗。\r\n\r\n活動資訊時間｜2025年4月19日(六)14:00-16:00\r\n地點｜新北市立圖書館總館3樓演藝廳\r\n報名連結|https://www.beclass.com/rid=294fe6267a9710ec2fa8\r\n誠摯邀請喜愛詩歌與文學的你，一起來聆聽、感受詩的力量！\r\n\r\n① 報名＋出席 現場抽【限量好禮或詩人著作】\r\n② 出席＋集點 換【詩意好禮】', `organizer`='新北市立圖書館總館', `address`='新北市板橋區貴興路139號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='新北市立圖書館總館', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
