INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a326b3242b74a3ae14', '「書香傳愛~」書展', '新社圖書館與新社親子館一同辦理書展活動,\r\n於新社親子館,配合4月兒童節展示兒童繪本及親子教養圖書,供小朋友及爸媽爺嬤閱覽~', '臺中市立圖書館新社分館', '臺中市新社區', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新社區（臺中市）=', 24.17769289, 120.8313228, '無資料', 'https://www.library.taichung.gov.tw/public/topreview/index-1.asp?Parser=99,20,697,50,,,26707', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「書香傳愛~」書展', `description`='新社圖書館與新社親子館一同辦理書展活動,\r\n於新社親子館,配合4月兒童節展示兒童繪本及親子教養圖書,供小朋友及爸媽爺嬤閱覽~', `organizer`='臺中市立圖書館新社分館', `address`='臺中市新社區', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新社區（臺中市）=', `latitude`=24.17769289, `longitude`=120.8313228, `ticket_price`='無資料', `source_url`='https://www.library.taichung.gov.tw/public/topreview/index-1.asp?Parser=99,20,697,50,,,26707', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a326b3242b74a3ae15', '跟著圖書館去找茶書展', '茶，不只是飲品，更是一種文化的沉澱。\r\n從古至今，茶與人們的生活密不可分，不論是閒暇時的片刻寧靜，還是文化交流的橋樑，茶都扮演著重要的角色。本次書展將帶您走進茶的世界，透過精選書籍探索茶的歷史、品種、製作工藝，以及茶道美學與茶文化的深厚內涵。', '桃園市政府家庭教育中心', '桃園市龍潭區中興路680號', '2025-03-20 00:00:00', '2025-04-20 00:00:00', '桃園市立圖書館龍潭分館', 24.85064954, 121.2117877, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='跟著圖書館去找茶書展', `description`='茶，不只是飲品，更是一種文化的沉澱。\r\n從古至今，茶與人們的生活密不可分，不論是閒暇時的片刻寧靜，還是文化交流的橋樑，茶都扮演著重要的角色。本次書展將帶您走進茶的世界，透過精選書籍探索茶的歷史、品種、製作工藝，以及茶道美學與茶文化的深厚內涵。', `organizer`='桃園市政府家庭教育中心', `address`='桃園市龍潭區中興路680號', `start_date`='2025-03-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='桃園市立圖書館龍潭分館', `latitude`=24.85064954, `longitude`=121.2117877, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a326b3242b74a3ae16', '中正藝文迴廊「悠遊自在」陳妍廷師生展', '陳妍廷老師為臺中市救國團山水畫指導老師、潭雅神社區大學水墨畫講師，本次帶領學生展出墨色穠纖合度，畫境逸趣的水墨畫及追求融合詩、書、畫、印的古風藝術創作，以水與墨創造出濃淡變化，為辦公場所營造出古色古香的韻味。\r\n', '臺中市中正地政事務所', '臺中市北屯區', '2025-04-01 00:00:00', '2025-06-30 00:00:00', '北屯區（臺中市）=', 24.18400298, 120.7362319, '無資料', 'https://ccland.land.taichung.gov.tw/news/?mode=data&id=4354&parent_id=258&type_id=10719', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中正藝文迴廊「悠遊自在」陳妍廷師生展', `description`='陳妍廷老師為臺中市救國團山水畫指導老師、潭雅神社區大學水墨畫講師，本次帶領學生展出墨色穠纖合度，畫境逸趣的水墨畫及追求融合詩、書、畫、印的古風藝術創作，以水與墨創造出濃淡變化，為辦公場所營造出古色古香的韻味。\r\n', `organizer`='臺中市中正地政事務所', `address`='臺中市北屯區', `start_date`='2025-04-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='北屯區（臺中市）=', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://ccland.land.taichung.gov.tw/news/?mode=data&id=4354&parent_id=258&type_id=10719', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a426b3242b74a3ae17', '臺中文學館-【親子說故事】(114年4月8場)', '臺中文學館兒童文學區 每周六、日上午10：30-11：00舉辦「親子聽故事」活動， 歡迎爸爸媽媽帶(國小以下)小朋友，大手牽小手一起來聽故事唷！！\r\n4月5日(六)10：30-11：00夢銀行\r\n4月6日(日)10：30-11：00移動超市\r\n4月12日(六)10：30-11：00愛哭公主\r\n4月13日(日)10：30-11：00神奇穿衣鏡\r\n4月19日(六)10：30-11：00再等一下下\r\n4月20日(日)10：30-11：00禁止黑暗的國王\r\n4月26日(六)10：30-11：00阿文的小毯子\r\n4月27日(日)10：30-11：00章魚先生教跳舞', '臺中市政府文化局', '臺中市西區樂群街38號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺中文學館', 24.1396799, 120.672764, '無資料', 'https://www.tlm.taichung.gov.tw/latestevent/Details.aspx?Parser=9,5,124,,,,1961', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中文學館-【親子說故事】(114年4月8場)', `description`='臺中文學館兒童文學區 每周六、日上午10：30-11：00舉辦「親子聽故事」活動， 歡迎爸爸媽媽帶(國小以下)小朋友，大手牽小手一起來聽故事唷！！\r\n4月5日(六)10：30-11：00夢銀行\r\n4月6日(日)10：30-11：00移動超市\r\n4月12日(六)10：30-11：00愛哭公主\r\n4月13日(日)10：30-11：00神奇穿衣鏡\r\n4月19日(六)10：30-11：00再等一下下\r\n4月20日(日)10：30-11：00禁止黑暗的國王\r\n4月26日(六)10：30-11：00阿文的小毯子\r\n4月27日(日)10：30-11：00章魚先生教跳舞', `organizer`='臺中市政府文化局', `address`='臺中市西區樂群街38號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中文學館', `latitude`=24.1396799, `longitude`=120.672764, `ticket_price`='無資料', `source_url`='https://www.tlm.taichung.gov.tw/latestevent/Details.aspx?Parser=9,5,124,,,,1961', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a426b3242b74a3ae19', '「陂塘進行式」創作工作坊', '「陂塘進行式」創作工作坊\r\n活動流程\r\n(一)肢體開發及合作練習。\r\n(二)認識陂塘的變遷與都市開發的故事。\r\n(三)氣候變遷與水環境。\r\n(四)共同創作：都市中的陂塘是什麼樣子？', '桃園市兒童美術館', '桃園市中壢區高鐵南路二段90號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '桃園市兒童美術館', 24.97993803, 121.2147243, '費用+200', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「陂塘進行式」創作工作坊', `description`='「陂塘進行式」創作工作坊\r\n活動流程\r\n(一)肢體開發及合作練習。\r\n(二)認識陂塘的變遷與都市開發的故事。\r\n(三)氣候變遷與水環境。\r\n(四)共同創作：都市中的陂塘是什麼樣子？', `organizer`='桃園市兒童美術館', `address`='桃園市中壢區高鐵南路二段90號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='桃園市兒童美術館', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='費用+200', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a426b3242b74a3ae1a', '清_法_戰_爭：西仔反印象記特展', '#清_法_戰_爭 #土地公顯神威 #交趾陶現戰況\r\n1884年，受到清、法之間對越南主權爭奪的波及，基隆、淡水、澎湖相繼陷入戰火。面對這場從天而降的兵禍，臺灣人稱之為「西仔反」(Se-''á-''huán)，意即「西仔（法蘭西）」來作亂。面臨外國的侵略，在地義勇亦受到政府官員的徵召，武裝動員到戰場支援，關鍵領袖如林朝棟、張李成、姜紹基、王廷理、陳輝煌等。\r\n來自地方社會的動員與抵抗，往往留存於各地的宮廟史跡，也可能銘刻在信仰文化中。例如，基隆獅球嶺平安宮 內，有一幅講述清_法_戰_爭的 獅嶺匝雲 交趾陶壁堵，是廟方聘請名師林洸沂創作而成。臺史博策展團隊赴基隆與嘉義多次採訪製作而成的 交趾陶裡的清法戰爭影片，可瞭解基隆獅球嶺平安宮內耗時5年的交趾陶《獅嶺匝雲》壁堵，如何將基隆戰役中土地公助戰的傳說，結合清法軍備的考證，以精湛工藝重現當年戰況。\r\n', '國立臺灣歷史博物館', '臺南市安南區長和路一段250號', '2025-02-24 00:00:00', '2025-05-04 00:00:00', '國立臺灣歷史博物館', 23.04869681, 120.1526189, '全票+100;優待票+50;團體票+90', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='清_法_戰_爭：西仔反印象記特展', `description`='#清_法_戰_爭 #土地公顯神威 #交趾陶現戰況\r\n1884年，受到清、法之間對越南主權爭奪的波及，基隆、淡水、澎湖相繼陷入戰火。面對這場從天而降的兵禍，臺灣人稱之為「西仔反」(Se-''á-''huán)，意即「西仔（法蘭西）」來作亂。面臨外國的侵略，在地義勇亦受到政府官員的徵召，武裝動員到戰場支援，關鍵領袖如林朝棟、張李成、姜紹基、王廷理、陳輝煌等。\r\n來自地方社會的動員與抵抗，往往留存於各地的宮廟史跡，也可能銘刻在信仰文化中。例如，基隆獅球嶺平安宮 內，有一幅講述清_法_戰_爭的 獅嶺匝雲 交趾陶壁堵，是廟方聘請名師林洸沂創作而成。臺史博策展團隊赴基隆與嘉義多次採訪製作而成的 交趾陶裡的清法戰爭影片，可瞭解基隆獅球嶺平安宮內耗時5年的交趾陶《獅嶺匝雲》壁堵，如何將基隆戰役中土地公助戰的傳說，結合清法軍備的考證，以精湛工藝重現當年戰況。\r\n', `organizer`='國立臺灣歷史博物館', `address`='臺南市安南區長和路一段250號', `start_date`='2025-02-24 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='國立臺灣歷史博物館', `latitude`=23.04869681, `longitude`=120.1526189, `ticket_price`='全票+100;優待票+50;團體票+90', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a426b3242b74a3ae1c', '「閱讀樂多多」主題書展(4月1場)', 'Wimmelbook台灣譯為多多書，來自德語 Wimmelbuch，指的是一種畫面中包含豐富多彩的插圖，細節豐富，故事線索多條並行，令人目不暇給的圖書。\r\n適合兒童小朋友自主探索，可以培養耐心、提高專注力和細節觀察能力，鍛煉邏輯思維和推理能力。\r\n每次閱讀都會發現新的細節，小朋友會非常有成就感喔!', '臺中市立圖書館龍井山頂分館', '臺中市龍井區中沙路新庄仔巷19-1號2樓', '2025-04-05 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館龍井山頂分館', 24.20062892, 120.5283728, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「閱讀樂多多」主題書展(4月1場)', `description`='Wimmelbook台灣譯為多多書，來自德語 Wimmelbuch，指的是一種畫面中包含豐富多彩的插圖，細節豐富，故事線索多條並行，令人目不暇給的圖書。\r\n適合兒童小朋友自主探索，可以培養耐心、提高專注力和細節觀察能力，鍛煉邏輯思維和推理能力。\r\n每次閱讀都會發現新的細節，小朋友會非常有成就感喔!', `organizer`='臺中市立圖書館龍井山頂分館', `address`='臺中市龍井區中沙路新庄仔巷19-1號2樓', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館龍井山頂分館', `latitude`=24.20062892, `longitude`=120.5283728, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
