INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a626b3242b74a3ae20', '2025閩南傳統藝術巡演-明華園戲劇總團演出《蓬萊大仙》', '本次閩南傳統藝術巡演為了慶祝觀音永興宮天上聖母聖誕千秋，特別邀請明華園戲劇總團，於4月20日星期日晚上7時在觀音永興宮廟埕，為桃園市民帶來精采的歌仔戲《蓬萊大仙》。', '桃園市政府文化局', '桃園市觀音區', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '觀音區（桃園市）=', 25.02671611, 121.1155021, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025閩南傳統藝術巡演-明華園戲劇總團演出《蓬萊大仙》', `description`='本次閩南傳統藝術巡演為了慶祝觀音永興宮天上聖母聖誕千秋，特別邀請明華園戲劇總團，於4月20日星期日晚上7時在觀音永興宮廟埕，為桃園市民帶來精采的歌仔戲《蓬萊大仙》。', `organizer`='桃園市政府文化局', `address`='桃園市觀音區', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='觀音區（桃園市）=', `latitude`=25.02671611, `longitude`=121.1155021, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a626b3242b74a3ae21', '【新北市立圖書館瑞芳東和圖書閱覽室】114年4月閱讀書籤-聰明理財好生活', '簡介：每個人都希望能通過投資到達財富的天堂。但是，理財投資不是投機取巧、不是憑藉運氣，而是需要恒心、通過學習和實踐才能掌握的一門學問。所以，我們要下一些工夫去鑽研投資學，掌握其精髓，本館展示相關書籍歡迎借閱。\r\n活動時間：114年4月1日~4月30，開館時間\r\n活動地點：瑞芳東和圖書閱覽室/閱展區\r\n\r\n※圖書展示 可外借\r\n＊活動單位保有最終解釋及修正的權利，詳情請依現場為主。\r\n', '新北市立圖書館總館', '新北市瑞芳區中山路20號3樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館瑞芳東和圖書閱覽室', 25.0981293, 121.8232018, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館瑞芳東和圖書閱覽室】114年4月閱讀書籤-聰明理財好生活', `description`='簡介：每個人都希望能通過投資到達財富的天堂。但是，理財投資不是投機取巧、不是憑藉運氣，而是需要恒心、通過學習和實踐才能掌握的一門學問。所以，我們要下一些工夫去鑽研投資學，掌握其精髓，本館展示相關書籍歡迎借閱。\r\n活動時間：114年4月1日~4月30，開館時間\r\n活動地點：瑞芳東和圖書閱覽室/閱展區\r\n\r\n※圖書展示 可外借\r\n＊活動單位保有最終解釋及修正的權利，詳情請依現場為主。\r\n', `organizer`='新北市立圖書館總館', `address`='新北市瑞芳區中山路20號3樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館瑞芳東和圖書閱覽室', `latitude`=25.0981293, `longitude`=121.8232018, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
