INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a626b3242b74a3ae25', '【新北市立圖書館土城分館】114年4月份書展', '【新北市立圖書館土城分館】114年4月份書展\r\n4月樂齡書展「中醫樂齡保健之道」\r\n中醫是世界上最古老的醫學體系之一，強調「治未病」，也就是預防疾病的發生。從經絡、穴位、藥草等等，讓專家教您好好保養身體，防患未然。\r\n\r\n4月主題書展「育兒全攻略」\r\n育兒問題從A到Z，如何解決，答案全部在這裡！\r\n\r\n展示期間：114年4月01日-4月30日／開館時間\r\n週二~週六，08:30~21:00\r\n週日~週一，08:30~17:00\r\n國定假日與清館日(每月最後一個星期四)不對外開放。\r\n書展場地：土城分館7樓書展區\r\n活動電話：02-22602952#9\r\n活動地址：土城區中正路18號7樓\r\n捷運：【板南線】土城站2號出口步行約2分鐘 \r\n公車：《中正路》707\r\n《土城農會站》705、707、805\r\n《土城區公所站》706、藍17、藍40 、847區繞駛土城醫院\r\n', '新北市立圖書館總館', '新北市土城區中正路18號7樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館土城分館', 24.96425102, 121.445737, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館土城分館】114年4月份書展', `description`='【新北市立圖書館土城分館】114年4月份書展\r\n4月樂齡書展「中醫樂齡保健之道」\r\n中醫是世界上最古老的醫學體系之一，強調「治未病」，也就是預防疾病的發生。從經絡、穴位、藥草等等，讓專家教您好好保養身體，防患未然。\r\n\r\n4月主題書展「育兒全攻略」\r\n育兒問題從A到Z，如何解決，答案全部在這裡！\r\n\r\n展示期間：114年4月01日-4月30日／開館時間\r\n週二~週六，08:30~21:00\r\n週日~週一，08:30~17:00\r\n國定假日與清館日(每月最後一個星期四)不對外開放。\r\n書展場地：土城分館7樓書展區\r\n活動電話：02-22602952#9\r\n活動地址：土城區中正路18號7樓\r\n捷運：【板南線】土城站2號出口步行約2分鐘 \r\n公車：《中正路》707\r\n《土城農會站》705、707、805\r\n《土城區公所站》706、藍17、藍40 、847區繞駛土城醫院\r\n', `organizer`='新北市立圖書館總館', `address`='新北市土城區中正路18號7樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館土城分館', `latitude`=24.96425102, `longitude`=121.445737, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
