INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a726b3242b74a3ae28', '【新北市立圖書館板橋浮洲圖書閱覽室】114年4月份書展', '【新北市立圖書館板橋浮洲圖書閱覽室】114年4月份書展\r\n4月樂齡書展「中醫樂齡保健之道」\r\n中醫是世界上最古老的醫學體系之一，強調「治未病」，也就是預防疾病的發生。從經絡、穴位、藥草等等，讓專家教您好好保養身體，防患未然。\r\n\r\n4月主題書展「育兒全攻略」\r\n育兒問題從A到Z，如何解決，答案全部在這裡！\r\n\r\n展示期間：114年4月01日-4月30日／開館時間\r\n週二~週六，08:30~21:00\r\n週日~週一，08:30~17:00\r\n國定假日與清館日(每月最後一個星期四)不對外開放。\r\n書展場地：板橋浮洲圖書閱覽室2樓書展區\r\n地址：板橋區大觀路2段163號2樓\r\n電話：02-82751617\r\n\r\n公車：701、702、234(南下)、841(北上)→至板橋榮家→福德宮(右側門)至2樓即可到達。\r\n火車：浮洲火車站→(往南走)僑中二街→龍興街→大觀路二段140巷→向左轉→大觀路二段(114縣道)→向右轉120公尺即可到達。\r\n板橋浮洲圖書閱覽室位於浮洲福德宮2樓，請由福德宮右側樓梯上去即可到達。\r\n\r\n', '新北市立圖書館總館', '新北市板橋區大觀路二段163號2樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館板橋浮洲圖書閱覽室', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館板橋浮洲圖書閱覽室】114年4月份書展', `description`='【新北市立圖書館板橋浮洲圖書閱覽室】114年4月份書展\r\n4月樂齡書展「中醫樂齡保健之道」\r\n中醫是世界上最古老的醫學體系之一，強調「治未病」，也就是預防疾病的發生。從經絡、穴位、藥草等等，讓專家教您好好保養身體，防患未然。\r\n\r\n4月主題書展「育兒全攻略」\r\n育兒問題從A到Z，如何解決，答案全部在這裡！\r\n\r\n展示期間：114年4月01日-4月30日／開館時間\r\n週二~週六，08:30~21:00\r\n週日~週一，08:30~17:00\r\n國定假日與清館日(每月最後一個星期四)不對外開放。\r\n書展場地：板橋浮洲圖書閱覽室2樓書展區\r\n地址：板橋區大觀路2段163號2樓\r\n電話：02-82751617\r\n\r\n公車：701、702、234(南下)、841(北上)→至板橋榮家→福德宮(右側門)至2樓即可到達。\r\n火車：浮洲火車站→(往南走)僑中二街→龍興街→大觀路二段140巷→向左轉→大觀路二段(114縣道)→向右轉120公尺即可到達。\r\n板橋浮洲圖書閱覽室位於浮洲福德宮2樓，請由福德宮右側樓梯上去即可到達。\r\n\r\n', `organizer`='新北市立圖書館總館', `address`='新北市板橋區大觀路二段163號2樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館板橋浮洲圖書閱覽室', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a726b3242b74a3ae2a', '【2025臺中文學季】-豐原大街直直走：在地深度旅行', '豐原有三多，銀行多、診所多、糕餅店多！與豐原在地的青年團隊北山城工作室的走讀品牌「用心柑仔店」合作，從豐原火車站出發，沿著在地人口中的「豐原大街」（中正路）一直直行，深度認識這一座城鎮的歷史底蘊與故事。', '臺中市政府文化局', '臺中市豐原區', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '豐原區（臺中市）=', 24.24990298, 120.7375715, '無資料', 'https://www.tlm.taichung.gov.tw/tour/Details.aspx?Parser=13,6,134,,,,171', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025臺中文學季】-豐原大街直直走：在地深度旅行', `description`='豐原有三多，銀行多、診所多、糕餅店多！與豐原在地的青年團隊北山城工作室的走讀品牌「用心柑仔店」合作，從豐原火車站出發，沿著在地人口中的「豐原大街」（中正路）一直直行，深度認識這一座城鎮的歷史底蘊與故事。', `organizer`='臺中市政府文化局', `address`='臺中市豐原區', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='豐原區（臺中市）=', `latitude`=24.24990298, `longitude`=120.7375715, `ticket_price`='無資料', `source_url`='https://www.tlm.taichung.gov.tw/tour/Details.aspx?Parser=13,6,134,,,,171', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a726b3242b74a3ae2b', 'The Lantern of Darkness黑夜中的冥燈', '都市的喧囂 城裏的糜爛\r\n厭倦？但卻早已深陷期中\r\n只好在黑暗的世界 慢慢尋找光的蹤跡\r\n看吶！就是這道光！就是這道光！\r\n看到圓圓的盤子 越來越近 一道光過去\r\n我啥也不知道', '迴響音樂藝文展演空間', '臺中市中區中山路108號', '2025-04-24 00:00:00', '2025-04-24 00:00:00', '迴響音樂藝文展演空間', 24.14168566, 120.680598, '預售票+350;現場票+400', 'https://www.facebook.com/photo?fbid=1192959238890606&set=a.714006010119267&locale=zh_TW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='The Lantern of Darkness黑夜中的冥燈', `description`='都市的喧囂 城裏的糜爛\r\n厭倦？但卻早已深陷期中\r\n只好在黑暗的世界 慢慢尋找光的蹤跡\r\n看吶！就是這道光！就是這道光！\r\n看到圓圓的盤子 越來越近 一道光過去\r\n我啥也不知道', `organizer`='迴響音樂藝文展演空間', `address`='臺中市中區中山路108號', `start_date`='2025-04-24 00:00:00', `end_date`='2025-04-24 00:00:00', `location`='迴響音樂藝文展演空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='預售票+350;現場票+400', `source_url`='https://www.facebook.com/photo?fbid=1192959238890606&set=a.714006010119267&locale=zh_TW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a726b3242b74a3ae2e', '台灣暴走2025 Taiwan Bosou Rock Tours', '珍惜我們的台灣，讓別人也聽見我們。\r\n\r\n坐上巡迴巴士，用心感受台灣每個城市，\r\n用搖滾樂替每個城市渲然不同的色彩。\r\n結合另類、龐克、工業、Rockabilly、搖滾 大融合\r\n\r\nLoud Sonic Records Presents\r\n烙聲音樂首波獻映！又快又重烙人來聽！', '迴響音樂藝文展演空間', '臺中市中區中山路108號', '2025-05-24 00:00:00', '2025-05-24 00:00:00', '迴響音樂藝文展演空間', 24.14168566, 120.680598, '無資料', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台灣暴走2025 Taiwan Bosou Rock Tours', `description`='珍惜我們的台灣，讓別人也聽見我們。\r\n\r\n坐上巡迴巴士，用心感受台灣每個城市，\r\n用搖滾樂替每個城市渲然不同的色彩。\r\n結合另類、龐克、工業、Rockabilly、搖滾 大融合\r\n\r\nLoud Sonic Records Presents\r\n烙聲音樂首波獻映！又快又重烙人來聽！', `organizer`='迴響音樂藝文展演空間', `address`='臺中市中區中山路108號', `start_date`='2025-05-24 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='迴響音樂藝文展演空間', `latitude`=24.14168566, `longitude`=120.680598, `ticket_price`='無資料', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a726b3242b74a3ae2f', '南化書法研習會@南化教會', '在陳春良老師的指導下，大家可以循序漸進地學習各大書法家的獨特筆法，從入門到精通，深入了解各種書體的奧妙。透過掌握運筆技巧，大家將能夠揮灑自如，寫出優雅動人的書法作品', '無資料', '臺南市南化區', '2025-01-07 00:00:00', '2025-12-30 00:00:00', '南化區（臺南市）=', 23.1151111, 120.5441223, '每月600元+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南化書法研習會@南化教會', `description`='在陳春良老師的指導下，大家可以循序漸進地學習各大書法家的獨特筆法，從入門到精通，深入了解各種書體的奧妙。透過掌握運筆技巧，大家將能夠揮灑自如，寫出優雅動人的書法作品', `organizer`='無資料', `address`='臺南市南化區', `start_date`='2025-01-07 00:00:00', `end_date`='2025-12-30 00:00:00', `location`='南化區（臺南市）=', `latitude`=23.1151111, `longitude`=120.5441223, `ticket_price`='每月600元+--', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67edb1a726b3242b74a3ae30', '織夢繩語-初階班', '本課程結合花編結技法與勾針藝術，創新研發出更符合大眾市場需求的手工飾品，並賦予傳統工藝新的生命與時尚感。\r\n(1)掌握編繩與勾針技藝，提升手工飾品的美感與價值感、\r\n(2)了解原住民文化背景，學習如何將其融入設計中、\r\n(3)製作具有市場競爭力且富有文化意涵的飾品，傳承工藝之美。\r\n', '桃園市政府原住民族行政局', '桃園市大溪區員林路一段29巷101號', '2025-03-01 00:00:00', '2025-05-03 00:00:00', '桃園市原住民族文化會館', 24.896414, 121.2822299, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='織夢繩語-初階班', `description`='本課程結合花編結技法與勾針藝術，創新研發出更符合大眾市場需求的手工飾品，並賦予傳統工藝新的生命與時尚感。\r\n(1)掌握編繩與勾針技藝，提升手工飾品的美感與價值感、\r\n(2)了解原住民文化背景，學習如何將其融入設計中、\r\n(3)製作具有市場競爭力且富有文化意涵的飾品，傳承工藝之美。\r\n', `organizer`='桃園市政府原住民族行政局', `address`='桃園市大溪區員林路一段29巷101號', `start_date`='2025-03-01 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='桃園市原住民族文化會館', `latitude`=24.896414, `longitude`=121.2822299, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ee3f9207f32215730321f3', '2025「成人」Sakalatamdaw行為藝術‧劇場研習營', '2025「成人」Sakala-tamdaw行為藝術‧劇場研習營【Palamal‧Salisinan‧Talo''an升火‧祭場‧搭廬岸】\r\n\r\n\r\n「巫者舞也」，「祭」者「劇」也；\r\n升火祭場亦生活劇場，更是「創造」之泉。\r\n太平洋之濱，九天八夜的狂喜，\r\n「颯旮啦~旦老 Sakala—tamdaw 成而為~人」。\r\n\r\n策展人\r\n盧宏文\r\n \r\n協力策劃\r\n冉而山劇場\r\n \r\n主辦單位\r\n財團法人國家文化藝術基金會\r\n策展人培力@美術館\r\n臺東縣政府\r\n \r\n承辦單位\r\n臺東縣政府文化處\r\n臺東美術館\r\n \r\n贊助單位\r\n春之文化基金會\r\n\r\n場地協力\r\nMakotaay生態藝術村\r\n\r\n平面設計\r\nmaya''a taboeh hayawan 羅媛\r\n', '盧宏文（文文製造）', '花蓮縣豐濱鄉石梯灣123之2號', '2025-05-24 00:00:00', '2025-06-01 00:00:00', 'Makotaay生態藝術村', 23.58519428, 121.4942331, '無資料', 'https://forms.gle/B9srbEkLDq1o3STc9', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025「成人」Sakalatamdaw行為藝術‧劇場研習營', `description`='2025「成人」Sakala-tamdaw行為藝術‧劇場研習營【Palamal‧Salisinan‧Talo''an升火‧祭場‧搭廬岸】\r\n\r\n\r\n「巫者舞也」，「祭」者「劇」也；\r\n升火祭場亦生活劇場，更是「創造」之泉。\r\n太平洋之濱，九天八夜的狂喜，\r\n「颯旮啦~旦老 Sakala—tamdaw 成而為~人」。\r\n\r\n策展人\r\n盧宏文\r\n \r\n協力策劃\r\n冉而山劇場\r\n \r\n主辦單位\r\n財團法人國家文化藝術基金會\r\n策展人培力@美術館\r\n臺東縣政府\r\n \r\n承辦單位\r\n臺東縣政府文化處\r\n臺東美術館\r\n \r\n贊助單位\r\n春之文化基金會\r\n\r\n場地協力\r\nMakotaay生態藝術村\r\n\r\n平面設計\r\nmaya''a taboeh hayawan 羅媛\r\n', `organizer`='盧宏文（文文製造）', `address`='花蓮縣豐濱鄉石梯灣123之2號', `start_date`='2025-05-24 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='Makotaay生態藝術村', `latitude`=23.58519428, `longitude`=121.4942331, `ticket_price`='無資料', `source_url`='https://forms.gle/B9srbEkLDq1o3STc9', `image_url`='[]';
