INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028b26b3242b74a3ae4b', '2025年4月【南北管音樂戲曲館-主題書展】南管主題書展', '本期書展特別展示一系列南管相關資料，包括南管指譜、南管曲牌、南管表演內容以及保存團體的介紹，並提供相關書籍與影音資料。無論是喜愛南管音樂的專業人士，或是對傳統戲曲有興趣的讀者，都能在此找到豐富的內容，透過視覺與聽覺的饗宴，深入了解南管的獨特魅力，重溫經典之美，歡迎踴躍借閱。\r\n', '彰化縣文化局', '彰化縣彰化市平和七街66號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '南北管音樂戲曲館', 24.07532909, 120.5694208, '無資料', 'https://drama.bocach.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年4月【南北管音樂戲曲館-主題書展】南管主題書展', `description`='本期書展特別展示一系列南管相關資料，包括南管指譜、南管曲牌、南管表演內容以及保存團體的介紹，並提供相關書籍與影音資料。無論是喜愛南管音樂的專業人士，或是對傳統戲曲有興趣的讀者，都能在此找到豐富的內容，透過視覺與聽覺的饗宴，深入了解南管的獨特魅力，重溫經典之美，歡迎踴躍借閱。\r\n', `organizer`='彰化縣文化局', `address`='彰化縣彰化市平和七街66號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='南北管音樂戲曲館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://drama.bocach.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028b26b3242b74a3ae4e', '2025年創價公演「極緻天籟 無限美聲 RAJATON 芬蘭阿卡貝拉之夜」共2場', '2025 創價公演隆重邀請國際知名阿卡貝拉樂團「Rajaton」來台演出，為樂迷帶來無限驚喜！來自芬蘭的 Rajaton，致力於探索人聲的極致美感，「Rajaton」在芬蘭語中意為「無邊無際」，正好詮釋了他們自由無拘的音樂風格。Rajaton 每年舉辦百場音樂會與工作坊，擅長融合多元音樂風格，並與電影、編舞等領域合作，不斷創新突破。\r\n\r\n他們以真誠的演繹、熱情分享與純粹的音樂感染力，征服全球樂迷與評論家，榮獲 8 張金唱片、3 次「白金」及 1 次「雙白金」獎。其專輯《Maa》更在美國獲得「最佳民謠歌曲獎」及「最佳民謠專輯獎」。Rajaton的音樂魅力無遠弗屆！一起來感受這場極致天籟、無限美聲的震撼體驗吧！', '彰化縣文化局', '彰化縣員林市員林大道2段99號', '2025-04-23 00:00:00', '2025-04-24 00:00:00', '彰化縣員林演藝廳', 23.95650448, 120.593073, '全票+900;全票+1200;全票+1500;全票+1800;全票+2000', 'https://performance.bocach.gov.tw/News_Performance.aspx?n=1042&s=51026', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年創價公演「極緻天籟 無限美聲 RAJATON 芬蘭阿卡貝拉之夜」共2場', `description`='2025 創價公演隆重邀請國際知名阿卡貝拉樂團「Rajaton」來台演出，為樂迷帶來無限驚喜！來自芬蘭的 Rajaton，致力於探索人聲的極致美感，「Rajaton」在芬蘭語中意為「無邊無際」，正好詮釋了他們自由無拘的音樂風格。Rajaton 每年舉辦百場音樂會與工作坊，擅長融合多元音樂風格，並與電影、編舞等領域合作，不斷創新突破。\r\n\r\n他們以真誠的演繹、熱情分享與純粹的音樂感染力，征服全球樂迷與評論家，榮獲 8 張金唱片、3 次「白金」及 1 次「雙白金」獎。其專輯《Maa》更在美國獲得「最佳民謠歌曲獎」及「最佳民謠專輯獎」。Rajaton的音樂魅力無遠弗屆！一起來感受這場極致天籟、無限美聲的震撼體驗吧！', `organizer`='彰化縣文化局', `address`='彰化縣員林市員林大道2段99號', `start_date`='2025-04-23 00:00:00', `end_date`='2025-04-24 00:00:00', `location`='彰化縣員林演藝廳', `latitude`=23.95650448, `longitude`=120.593073, `ticket_price`='全票+900;全票+1200;全票+1500;全票+1800;全票+2000', `source_url`='https://performance.bocach.gov.tw/News_Performance.aspx?n=1042&s=51026', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028b26b3242b74a3ae4f', '2025青溪長流彰化縣青溪新文藝會員聯展', '彰化縣青溪新文藝學會創立於民國72年，迄今屆42年，是彰化地區中歷史悠久綜合性的民間藝術團體，成員包括後備軍人及藝文愛好者，各個為繪畫、攝影、書畫、篆刻及雕塑等藝術精英，多年來，青溪為促進國家藝文風尚，培養創作人才，致力推動「生活藝術化，藝術生活化」理念。\r\n\r\n  此次展覽將呈現油畫、水彩、國畫、書法、雕刻、陶藝、泥塑、攝影等項目，作品多元且豐富，學會期許本次展覽不只是一場美藝的饗宴，更是人文教育的成功與見證，敬邀民眾一同蒞臨欣賞。', '彰化縣文化局', '彰化縣員林市員林大道2段99號', '2025-04-15 00:00:00', '2025-05-04 00:00:00', '彰化縣員林演藝廳', 23.95650448, 120.593073, '無資料', 'https://performance.bocach.gov.tw/News_Content.aspx?n=1043&s=50853', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025青溪長流彰化縣青溪新文藝會員聯展', `description`='彰化縣青溪新文藝學會創立於民國72年，迄今屆42年，是彰化地區中歷史悠久綜合性的民間藝術團體，成員包括後備軍人及藝文愛好者，各個為繪畫、攝影、書畫、篆刻及雕塑等藝術精英，多年來，青溪為促進國家藝文風尚，培養創作人才，致力推動「生活藝術化，藝術生活化」理念。\r\n\r\n  此次展覽將呈現油畫、水彩、國畫、書法、雕刻、陶藝、泥塑、攝影等項目，作品多元且豐富，學會期許本次展覽不只是一場美藝的饗宴，更是人文教育的成功與見證，敬邀民眾一同蒞臨欣賞。', `organizer`='彰化縣文化局', `address`='彰化縣員林市員林大道2段99號', `start_date`='2025-04-15 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='彰化縣員林演藝廳', `latitude`=23.95650448, `longitude`=120.593073, `ticket_price`='無資料', `source_url`='https://performance.bocach.gov.tw/News_Content.aspx?n=1043&s=50853', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028b26b3242b74a3ae50', '2025臺灣青年管樂團童話沙龍系列【恐龍學園】互動音樂會', '恐龍旋風來襲！！！！全台走透透！\r\n\r\n2025年臺青管恐龍大軍即將前往苗栗及彰化！\r\n\r\n2024年廣受好評、熱烈迴響！\r\n\r\n最適合全家人一起體驗的互動音樂會，親子同樂，趣味無窮！\r\n\r\n滿滿驚喜互動橋段，結合活力十足的唱跳表演，假日小孩放電首選！\r\n\r\n等你一起來歡樂共享！\r\n\r\n深受觀眾喜愛的臺青管童話沙龍【恐龍學園】互動音樂會，2025年也即將帶給各位最好玩最好聽的音樂會，邀請大小朋友與臺上恐龍樂手們同樂，由親和力一級棒的小花姐姐–游雅芸帶領進入恐龍學園的奇幻世界，透過戲劇化的聲音表情、生動活潑的互動，帶來許多精彩互動遊戲，一同展開一場充滿歡笑與互動的音樂冒險之旅。', '彰化縣文化局', '彰化縣員林市員林大道2段99號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '彰化縣員林演藝廳', 23.95650448, 120.593073, '全票+399;全票+699', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺灣青年管樂團童話沙龍系列【恐龍學園】互動音樂會', `description`='恐龍旋風來襲！！！！全台走透透！\r\n\r\n2025年臺青管恐龍大軍即將前往苗栗及彰化！\r\n\r\n2024年廣受好評、熱烈迴響！\r\n\r\n最適合全家人一起體驗的互動音樂會，親子同樂，趣味無窮！\r\n\r\n滿滿驚喜互動橋段，結合活力十足的唱跳表演，假日小孩放電首選！\r\n\r\n等你一起來歡樂共享！\r\n\r\n深受觀眾喜愛的臺青管童話沙龍【恐龍學園】互動音樂會，2025年也即將帶給各位最好玩最好聽的音樂會，邀請大小朋友與臺上恐龍樂手們同樂，由親和力一級棒的小花姐姐–游雅芸帶領進入恐龍學園的奇幻世界，透過戲劇化的聲音表情、生動活潑的互動，帶來許多精彩互動遊戲，一同展開一場充滿歡笑與互動的音樂冒險之旅。', `organizer`='彰化縣文化局', `address`='彰化縣員林市員林大道2段99號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='彰化縣員林演藝廳', `latitude`=23.95650448, `longitude`=120.593073, `ticket_price`='全票+399;全票+699', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028b26b3242b74a3ae51', '《歡欣鼓舞》 / 飛越舞蹈團', '《歡欣鼓舞》舞者們懷著辦喜事的心情，將情感和意念融入自身肢體和節奏，期盼將觀眾帶入充滿歡樂與驚奇交織的世界，因此無論是在民俗舞的展現、古典舞的情感及自由的現代舞中，皆期盼能藉由舞蹈來啟發觀眾，用不同的角度去感受藝文世界，用心去理解如何透過舞蹈來傳達深層的藝術情感和意義。', '彰化縣文化局', '彰化縣員林市員林大道2段99號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '彰化縣員林演藝廳', 23.95650448, 120.593073, '全票+300', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《歡欣鼓舞》 / 飛越舞蹈團', `description`='《歡欣鼓舞》舞者們懷著辦喜事的心情，將情感和意念融入自身肢體和節奏，期盼將觀眾帶入充滿歡樂與驚奇交織的世界，因此無論是在民俗舞的展現、古典舞的情感及自由的現代舞中，皆期盼能藉由舞蹈來啟發觀眾，用不同的角度去感受藝文世界，用心去理解如何透過舞蹈來傳達深層的藝術情感和意義。', `organizer`='彰化縣文化局', `address`='彰化縣員林市員林大道2段99號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='彰化縣員林演藝廳', `latitude`=23.95650448, `longitude`=120.593073, `ticket_price`='全票+300', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028b26b3242b74a3ae52', '許家綝古箏獨奏會', '古箏，又稱「秦箏」或「瑤箏」，是中國歷史悠久的彈弦樂器之一，其音色典雅細膩，既能展現傳統音樂的深遠韻味，也能詮釋現代音樂的多元風貌。\r\n\r\n本場音樂會的曲目涵蓋傳統樂曲與當代古箏作品，巧妙融合各流派特色與地域風情，呈現古箏音樂的豐富層次與多變風格。\r\n\r\n嶄新的曲式與古箏獨特音色交織，考驗演奏者對技法的精準掌握，以及對傳統韻味與內在情感的細膩詮釋，期為觀眾帶來耳目一新的箏琴饗宴。', '彰化縣文化局', '彰化縣員林市員林大道2段99號', '2025-04-27 00:00:00', '2025-04-27 00:00:00', '彰化縣員林演藝廳', 23.95650448, 120.593073, '無資料', 'https://performance.bocach.gov.tw/News_Performance.aspx?n=1042&s=51239', '[]') ON DUPLICATE KEY UPDATE `activity_name`='許家綝古箏獨奏會', `description`='古箏，又稱「秦箏」或「瑤箏」，是中國歷史悠久的彈弦樂器之一，其音色典雅細膩，既能展現傳統音樂的深遠韻味，也能詮釋現代音樂的多元風貌。\r\n\r\n本場音樂會的曲目涵蓋傳統樂曲與當代古箏作品，巧妙融合各流派特色與地域風情，呈現古箏音樂的豐富層次與多變風格。\r\n\r\n嶄新的曲式與古箏獨特音色交織，考驗演奏者對技法的精準掌握，以及對傳統韻味與內在情感的細膩詮釋，期為觀眾帶來耳目一新的箏琴饗宴。', `organizer`='彰化縣文化局', `address`='彰化縣員林市員林大道2段99號', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='彰化縣員林演藝廳', `latitude`=23.95650448, `longitude`=120.593073, `ticket_price`='無資料', `source_url`='https://performance.bocach.gov.tw/News_Performance.aspx?n=1042&s=51239', `image_url`='[]';
