INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028c26b3242b74a3ae54', '「磺溪文學第33輯─彰化縣作家作品集」徵集', '彰化縣文化局辦理「磺溪文學第33輯─彰化縣作家作品集」徵集，採網路報名，報名日期自即日起至114年4月30日截止。凡身分證號開頭為N或送件當時設籍、就學、工作於彰化縣滿3年以上者；未具前述資格，其作品內容書寫彰化縣風土民情者，均可參加（每種文類每人限1冊；已獲入選出版作品之作家，需隔一年再參選徵稿）。\r\n徵集內容以作者未結集出版之傳統詩及新詩、散文、小說、報導文學等現代文學創作為主。入選作品每冊將由文化局提供稿酬新臺幣1萬元整、並贈送出版作品150本，並擇期公開頒發稿酬、獎座。\r\n', '彰化縣政府', '彰化縣彰化市中山路2段500號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '彰化縣立圖書館', 24.07532909, 120.5694208, '無資料', 'https://www.bocach.gov.tw/Default.aspx', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「磺溪文學第33輯─彰化縣作家作品集」徵集', `description`='彰化縣文化局辦理「磺溪文學第33輯─彰化縣作家作品集」徵集，採網路報名，報名日期自即日起至114年4月30日截止。凡身分證號開頭為N或送件當時設籍、就學、工作於彰化縣滿3年以上者；未具前述資格，其作品內容書寫彰化縣風土民情者，均可參加（每種文類每人限1冊；已獲入選出版作品之作家，需隔一年再參選徵稿）。\r\n徵集內容以作者未結集出版之傳統詩及新詩、散文、小說、報導文學等現代文學創作為主。入選作品每冊將由文化局提供稿酬新臺幣1萬元整、並贈送出版作品150本，並擇期公開頒發稿酬、獎座。\r\n', `organizer`='彰化縣政府', `address`='彰化縣彰化市中山路2段500號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='彰化縣立圖書館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.bocach.gov.tw/Default.aspx', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028c26b3242b74a3ae55', '文資彰化定點解說-2025年4月共8場次', '為提升遊客深入了解彰化縣文化資產的歷史文化及建築特色，推出定點中文導覽解說服務，歡迎踴躍參加。\r\n\r\n場次一：4/5（六）\r\n10:00-11:00 路線1國定古蹟彰化孔子廟\r\n15:00-16:00 路線2歷史建築八卦山大佛  \r\n場次二：4/12（六）\r\n15:00-16:00 路線1縣定古蹟彰化節孝祠→縣定古蹟彰化市武德殿\r\n15:00-16:00路線2國定古蹟元清觀\r\n場次三：4/19（六）\r\n15:00-16:00 路線1國定古蹟彰化孔子廟\r\n15:00-16:00 路線2歷史建築八卦山大佛\r\n場次四：4/26（六）\r\n15:00-16:00 路線1歷史建築彰化市公會堂→歷史建築八卦山紅毛井\r\n15:00-16:00 路線2 國定古蹟元清觀\r\n\r\n導覽約60分鐘\r\n集合地點：各場次解說地點\r\n＊本導覽解說全程免費不需事先報名，請於開始前10分鐘至定點集合。\r\n＊導覽時段如有異動，以當日解說規劃為主；如天氣不穩定、下雨或補行上班日，導覽解說暫停1次。連絡電話：0912-635030蔡先生\r\n\r\n', '彰化縣文化局', '彰化縣彰化市', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '彰化市（彰化縣）=', 24.07532909, 120.5694208, '無資料', 'https://www.bocach.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='文資彰化定點解說-2025年4月共8場次', `description`='為提升遊客深入了解彰化縣文化資產的歷史文化及建築特色，推出定點中文導覽解說服務，歡迎踴躍參加。\r\n\r\n場次一：4/5（六）\r\n10:00-11:00 路線1國定古蹟彰化孔子廟\r\n15:00-16:00 路線2歷史建築八卦山大佛  \r\n場次二：4/12（六）\r\n15:00-16:00 路線1縣定古蹟彰化節孝祠→縣定古蹟彰化市武德殿\r\n15:00-16:00路線2國定古蹟元清觀\r\n場次三：4/19（六）\r\n15:00-16:00 路線1國定古蹟彰化孔子廟\r\n15:00-16:00 路線2歷史建築八卦山大佛\r\n場次四：4/26（六）\r\n15:00-16:00 路線1歷史建築彰化市公會堂→歷史建築八卦山紅毛井\r\n15:00-16:00 路線2 國定古蹟元清觀\r\n\r\n導覽約60分鐘\r\n集合地點：各場次解說地點\r\n＊本導覽解說全程免費不需事先報名，請於開始前10分鐘至定點集合。\r\n＊導覽時段如有異動，以當日解說規劃為主；如天氣不穩定、下雨或補行上班日，導覽解說暫停1次。連絡電話：0912-635030蔡先生\r\n\r\n', `organizer`='彰化縣文化局', `address`='彰化縣彰化市', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='彰化市（彰化縣）=', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.bocach.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028c26b3242b74a3ae56', '2025年4月書法講堂-施伯松《篆書與篆刻-以書入印的精神》', '書法講堂《篆書與篆刻-以書入印的精神》\r\n時    間：4/26（六）14:00～16:00\r\n地    點：彰化縣立圖書館3樓 ─ 書道館\r\n師    資：施伯松(現任中華民國篆刻學會理事長)\r\n  \r\n【參加方式】 免報名※自由參加 \r\n【參加對象】想認識書法文字藝術之美的民眾或學童（需家長陪同）\r\n【洽詢電話】04-7250057轉2395 李小姐\r\n●各場全程參與之公務員，核予研習時數2小時。公務人員請於活動前至公務人員終身學習入口網站報名\r\n', '彰化縣文化局', '彰化縣彰化市中山路2段500號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '彰化縣立圖書館', 24.07532909, 120.5694208, '無資料', 'https://www.bocach.gov.tw/News_Content.aspx?n=193&s=45514', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年4月書法講堂-施伯松《篆書與篆刻-以書入印的精神》', `description`='書法講堂《篆書與篆刻-以書入印的精神》\r\n時    間：4/26（六）14:00～16:00\r\n地    點：彰化縣立圖書館3樓 ─ 書道館\r\n師    資：施伯松(現任中華民國篆刻學會理事長)\r\n  \r\n【參加方式】 免報名※自由參加 \r\n【參加對象】想認識書法文字藝術之美的民眾或學童（需家長陪同）\r\n【洽詢電話】04-7250057轉2395 李小姐\r\n●各場全程參與之公務員，核予研習時數2小時。公務人員請於活動前至公務人員終身學習入口網站報名\r\n', `organizer`='彰化縣文化局', `address`='彰化縣彰化市中山路2段500號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='彰化縣立圖書館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.bocach.gov.tw/News_Content.aspx?n=193&s=45514', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028c26b3242b74a3ae57', '我的彰化文學夢', '渡也本名陳啟佑，是一位著名的台灣詩人和學者，他的文學之旅跨越了四十餘年，從早期的「純情」詩到後來充滿濃郁鄉情的詩歌，渡也的詩作不僅以其詼諧幽默的風格著稱，也常常帶有機智的趣味。渡也的創作跨越了新詩、散文、極短篇、童詩等多種文類，對台灣文學的貢獻有口皆碑。\r\n渡也的文學成就不僅在於其豐富的創作，還在於他對文學教育的貢獻，他曾擔任彰師大等多所大學的教授，並屢次擔任文學獎評審，多年來，他在教學崗位上辛勤耕耘，積極推動文學教育，為無數學生啟迪智慧，渡也的文學夢想不僅停留在個人創作上，也希望能夠與更多人分享文學的樂趣。\r\n本次講座，渡也將透過回顧自己的寫作生涯，分享他對家鄉、愛情及生活的多角度觀察，並展望台灣文學的未來，在散播文學種子的同時，他將激勵更多人投入文學的世界，發現文學的美麗和價值。\r\n', '彰化縣文化局', '彰化縣彰化市中山路2段500號', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '彰化縣立圖書館', 24.07532909, 120.5694208, '無資料', 'https://www.bocach.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='我的彰化文學夢', `description`='渡也本名陳啟佑，是一位著名的台灣詩人和學者，他的文學之旅跨越了四十餘年，從早期的「純情」詩到後來充滿濃郁鄉情的詩歌，渡也的詩作不僅以其詼諧幽默的風格著稱，也常常帶有機智的趣味。渡也的創作跨越了新詩、散文、極短篇、童詩等多種文類，對台灣文學的貢獻有口皆碑。\r\n渡也的文學成就不僅在於其豐富的創作，還在於他對文學教育的貢獻，他曾擔任彰師大等多所大學的教授，並屢次擔任文學獎評審，多年來，他在教學崗位上辛勤耕耘，積極推動文學教育，為無數學生啟迪智慧，渡也的文學夢想不僅停留在個人創作上，也希望能夠與更多人分享文學的樂趣。\r\n本次講座，渡也將透過回顧自己的寫作生涯，分享他對家鄉、愛情及生活的多角度觀察，並展望台灣文學的未來，在散播文學種子的同時，他將激勵更多人投入文學的世界，發現文學的美麗和價值。\r\n', `organizer`='彰化縣文化局', `address`='彰化縣彰化市中山路2段500號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='彰化縣立圖書館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.bocach.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028c26b3242b74a3ae5a', '彰化囡仔好幸福-114年親子劇場鄉鎮巡演活動-萍蓬草劇團《金錢樹》', '歡慶兒童節，文化局特別規劃 8 場親子劇場鄉鎮巡演活動，自 3 月 22 日至 4 月 19 日，分別在 永靖、田中、伸港、鹿港、北斗、溪湖、彰化、大城 等地熱鬧登場。此次活動邀請 7 組國內知名劇團精彩演出，包括即將成真火舞團、風神寶寶兒童劇團、光興閣掌中劇團、萍蓬草劇團、蘋果劇團、豆子劇團 及 大開劇團，為親子帶來豐富多元的戲劇饗宴。活動免票入場！ 每場演出現場可獲得 1 枚戳章，累積2場以上戳章，即可兌換 精美小禮物1 份。誠摯邀請家長與小朋友們攜手參與，一同享受戲劇的樂趣，共創美好童年回憶！\r\n\r\n114年4月19日(星期六)下午3時至4時/大城鄉/彰化縣大城鄉多功能活動中心/萍蓬草劇團《金錢樹》', '彰化縣文化局', '彰化縣大城鄉', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '大城鄉（彰化縣）=', 23.85069276, 120.3113284, '無資料', 'https://www.bocach.gov.tw/News_Content.aspx?n=91&s=50946', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彰化囡仔好幸福-114年親子劇場鄉鎮巡演活動-萍蓬草劇團《金錢樹》', `description`='歡慶兒童節，文化局特別規劃 8 場親子劇場鄉鎮巡演活動，自 3 月 22 日至 4 月 19 日，分別在 永靖、田中、伸港、鹿港、北斗、溪湖、彰化、大城 等地熱鬧登場。此次活動邀請 7 組國內知名劇團精彩演出，包括即將成真火舞團、風神寶寶兒童劇團、光興閣掌中劇團、萍蓬草劇團、蘋果劇團、豆子劇團 及 大開劇團，為親子帶來豐富多元的戲劇饗宴。活動免票入場！ 每場演出現場可獲得 1 枚戳章，累積2場以上戳章，即可兌換 精美小禮物1 份。誠摯邀請家長與小朋友們攜手參與，一同享受戲劇的樂趣，共創美好童年回憶！\r\n\r\n114年4月19日(星期六)下午3時至4時/大城鄉/彰化縣大城鄉多功能活動中心/萍蓬草劇團《金錢樹》', `organizer`='彰化縣文化局', `address`='彰化縣大城鄉', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='大城鄉（彰化縣）=', `latitude`=23.85069276, `longitude`=120.3113284, `ticket_price`='無資料', `source_url`='https://www.bocach.gov.tw/News_Content.aspx?n=91&s=50946', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028c26b3242b74a3ae5b', '十鼓擊樂團《鼓映大地-拈花彰華》', '本次演出開場將以”拈花”一曲開場，寓意生命的傳承與契機，透過擊鼓的律動，展現天命所歸、自蘊而生的精神。本次演出特別編制樂團全新創作曲目，如妮芙努、東陽四神畫等，整場演出更凸顯曲風元素的多元性，透過擊樂與多元節奏的交融，營造震撼且細膩的音樂氛圍，帶領觀眾感受臺灣鼓樂的無限魅力。', '彰化縣文化局', '彰化縣彰化市健興路1號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '彰化縣立體育場', 24.07532909, 120.5694208, '無資料', 'https://www.bocach.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='十鼓擊樂團《鼓映大地-拈花彰華》', `description`='本次演出開場將以”拈花”一曲開場，寓意生命的傳承與契機，透過擊鼓的律動，展現天命所歸、自蘊而生的精神。本次演出特別編制樂團全新創作曲目，如妮芙努、東陽四神畫等，整場演出更凸顯曲風元素的多元性，透過擊樂與多元節奏的交融，營造震撼且細膩的音樂氛圍，帶領觀眾感受臺灣鼓樂的無限魅力。', `organizer`='彰化縣文化局', `address`='彰化縣彰化市健興路1號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='彰化縣立體育場', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.bocach.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028c26b3242b74a3ae5c', '長榮交響樂團', '本次音樂會將帶來多首廣為人知的古典樂曲、臺灣與世界民謠，透過悠揚動人的旋律與戲劇性的音樂演繹，讓觀眾沉浸於春日美景與文化饗宴之中，希望透過音樂提升民眾藝術素養，在節慶氛圍中與現場觀眾共度難忘時光。', '彰化縣文化局', '彰化縣彰化市健興路1號', '2025-04-27 00:00:00', '2025-04-27 00:00:00', '彰化縣立體育場', 24.07532909, 120.5694208, '無資料', 'https://www.bocach.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='長榮交響樂團', `description`='本次音樂會將帶來多首廣為人知的古典樂曲、臺灣與世界民謠，透過悠揚動人的旋律與戲劇性的音樂演繹，讓觀眾沉浸於春日美景與文化饗宴之中，希望透過音樂提升民眾藝術素養，在節慶氛圍中與現場觀眾共度難忘時光。', `organizer`='彰化縣文化局', `address`='彰化縣彰化市健興路1號', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='彰化縣立體育場', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.bocach.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028c26b3242b74a3ae5e', '攝影學術講座《漫談畫意攝影及相機內重複曝光之運用》', '為促進彰化縣攝影藝術發展，增進民眾對於攝影的技術觀念、教育推廣與創作技巧，彰化縣攝影學會與彰化縣文化局合辦「漫談畫意攝影及相機內重複曝光之運用」攝影學術講座，邀請詹益宗老師主講，分享自身攝影生涯與介紹重曝技巧之運用，歡迎愛好攝影的朋友一同精進、交流。', '彰化縣文化局', '彰化縣彰化市中山路2段500號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '彰化縣立圖書館', 24.07532909, 120.5694208, '無資料', 'https://www.bocach.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='攝影學術講座《漫談畫意攝影及相機內重複曝光之運用》', `description`='為促進彰化縣攝影藝術發展，增進民眾對於攝影的技術觀念、教育推廣與創作技巧，彰化縣攝影學會與彰化縣文化局合辦「漫談畫意攝影及相機內重複曝光之運用」攝影學術講座，邀請詹益宗老師主講，分享自身攝影生涯與介紹重曝技巧之運用，歡迎愛好攝影的朋友一同精進、交流。', `organizer`='彰化縣文化局', `address`='彰化縣彰化市中山路2段500號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='彰化縣立圖書館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.bocach.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028c26b3242b74a3ae5f', '彰化縣文化局114年夏季藝文研習班（4～6月）', '活動簡介：\r\n招生對象：有興趣之民眾均可報名。\r\n報名方式：填寫報名表，現場、電話、傳真、網路均可報名，並於開課前繳清報名費。\r\n報名請洽：彰化縣立圖書館藝文研習班報名處，電話：（04）7250057分機2102、1852\r\n報名傳真：(04)7244982，如以傳真方式報名者，請於傳真後撥打電話施小姐確認，以保障您的權益！\r\n報名時間：即日期至開課前(額滿提前截止) \r\n上課地點：縣立圖書館研習教室  標示★為南北管音樂戲曲館  ▲大成故事館（詳細內容以開課為準）\r\n (一)如遇不可抗力之天災、颱風，以縣府公告停課，不另通知，原課程順延。\r\n(二)各班不足開課人數，由本局通知辦理全額退費或轉班，請持收據辦理。\r\n(三)費用需上課前繳清，報名後除因兵役召集不克參加，可於活動前申請退費外，其餘數不退費。\r\n(四)謝絕旁聽、視聽，一人報名，一人上課，請勿攜家帶眷。\r\n(五)收費：新班一律以新生收費。\r\n(六)可登錄公務人員終身學習時數。(請於上課時將身分證字號交給研習班承辦員，以方便為您登錄公務人員終身學習時數不另通知)\r\n', '彰化縣文化局', '彰化縣彰化市中山路2段500號', '2025-04-02 00:00:00', '2025-07-05 00:00:00', '彰化縣立圖書館', 24.07532909, 120.5694208, '報名費+750;報名費+1500;報名費+1800', 'https://www.bocach.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彰化縣文化局114年夏季藝文研習班（4～6月）', `description`='活動簡介：\r\n招生對象：有興趣之民眾均可報名。\r\n報名方式：填寫報名表，現場、電話、傳真、網路均可報名，並於開課前繳清報名費。\r\n報名請洽：彰化縣立圖書館藝文研習班報名處，電話：（04）7250057分機2102、1852\r\n報名傳真：(04)7244982，如以傳真方式報名者，請於傳真後撥打電話施小姐確認，以保障您的權益！\r\n報名時間：即日期至開課前(額滿提前截止) \r\n上課地點：縣立圖書館研習教室  標示★為南北管音樂戲曲館  ▲大成故事館（詳細內容以開課為準）\r\n (一)如遇不可抗力之天災、颱風，以縣府公告停課，不另通知，原課程順延。\r\n(二)各班不足開課人數，由本局通知辦理全額退費或轉班，請持收據辦理。\r\n(三)費用需上課前繳清，報名後除因兵役召集不克參加，可於活動前申請退費外，其餘數不退費。\r\n(四)謝絕旁聽、視聽，一人報名，一人上課，請勿攜家帶眷。\r\n(五)收費：新班一律以新生收費。\r\n(六)可登錄公務人員終身學習時數。(請於上課時將身分證字號交給研習班承辦員，以方便為您登錄公務人員終身學習時數不另通知)\r\n', `organizer`='彰化縣文化局', `address`='彰化縣彰化市中山路2段500號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-07-05 00:00:00', `location`='彰化縣立圖書館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='報名費+750;報名費+1500;報名費+1800', `source_url`='https://www.bocach.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028c26b3242b74a3ae60', '彰化縣美術學會會員聯展《春意》', '彰化縣美術學會特別與彰化火車站、員林火車站及台中火車站合作，利用車站空間，展示彰化美術學會的會員作品，以自由彩繪、大地之美及風景為主題展示，讓搭火車的旅客，有新的感受與美感的欣賞，提升全民美學素養，能活化空間，同時也可讓藝術家把傑出作品呈現於大眾面前，一舉多得，感謝3位站長對藝術美學的支持，方能讓會員有機會在此場域展出作品，推展大眾美學，讓民眾在候車之餘，不用走進美術館，也能增加欣賞畫作機會。\r\n參展藝術家：\r\n林鴻銘、李賜鎮、楊家順、曾永錫、林介山、林碧霞、陳芬芬\r\n鄭采駖、黃怡華、林育如、林純珠、游惠娜、黃麗萍、常連芳\r\n林添生、謝武宏、陳志雄、胡淑媛、張彩鈴、張賞、林慶熙、邱淑惠、許秀寶、王子妤、黃明玲、林育如，共26人。\r\n\r\n天橋藝廊－春意\r\n展期：1/1(三)~6/30(一)\r\n展出地點：彰化火車站 \r\n\r\n', '彰化縣美術學會', '彰化縣彰化市', '2025-01-01 00:00:00', '2025-06-30 00:00:00', '彰化市（彰化縣）=', 24.07532909, 120.5694208, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彰化縣美術學會會員聯展《春意》', `description`='彰化縣美術學會特別與彰化火車站、員林火車站及台中火車站合作，利用車站空間，展示彰化美術學會的會員作品，以自由彩繪、大地之美及風景為主題展示，讓搭火車的旅客，有新的感受與美感的欣賞，提升全民美學素養，能活化空間，同時也可讓藝術家把傑出作品呈現於大眾面前，一舉多得，感謝3位站長對藝術美學的支持，方能讓會員有機會在此場域展出作品，推展大眾美學，讓民眾在候車之餘，不用走進美術館，也能增加欣賞畫作機會。\r\n參展藝術家：\r\n林鴻銘、李賜鎮、楊家順、曾永錫、林介山、林碧霞、陳芬芬\r\n鄭采駖、黃怡華、林育如、林純珠、游惠娜、黃麗萍、常連芳\r\n林添生、謝武宏、陳志雄、胡淑媛、張彩鈴、張賞、林慶熙、邱淑惠、許秀寶、王子妤、黃明玲、林育如，共26人。\r\n\r\n天橋藝廊－春意\r\n展期：1/1(三)~6/30(一)\r\n展出地點：彰化火車站 \r\n\r\n', `organizer`='彰化縣美術學會', `address`='彰化縣彰化市', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='彰化市（彰化縣）=', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028c26b3242b74a3ae61', '彰化縣美術學會會員聯展《納福》', '彰化縣美術學會特別與彰化火車站、員林火車站及台中火車站合作，利用車站空間，展示彰化美術學會的會員作品，以自由彩繪、大地之美及風景為主題展示，讓搭火車的旅客，有新的感受與美感的欣賞，提升全民美學素養，能活化空間，同時也可讓藝術家把傑出作品呈現於大眾面前，一舉多得，感謝3位站長對藝術美學的支持，方能讓會員有機會在此場域展出作品，推展大眾美學，讓民眾在候車之餘，不用走進美術館，也能增加欣賞畫作機會。\r\n參展藝術家：\r\n林鴻銘、李賜鎮、楊家順、曾永錫、林介山、林碧霞、陳芬芬\r\n鄭采駖、黃怡華、林育如、林純珠、游惠娜、黃麗萍、常連芳\r\n林添生、謝武宏、陳志雄、胡淑媛、張彩鈴、張賞、林慶熙、邱淑惠、許秀寶、王子妤、黃明玲、林育如，共26人。\r\n\r\n候車藝廊－納福\r\n展期：1/1(三)~6/30(一)\r\n展出地點：彰化火車站 \r\n\r\n', '彰化縣美術學會', '彰化縣彰化市', '2025-01-01 00:00:00', '2025-06-30 00:00:00', '彰化市（彰化縣）=', 24.07532909, 120.5694208, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彰化縣美術學會會員聯展《納福》', `description`='彰化縣美術學會特別與彰化火車站、員林火車站及台中火車站合作，利用車站空間，展示彰化美術學會的會員作品，以自由彩繪、大地之美及風景為主題展示，讓搭火車的旅客，有新的感受與美感的欣賞，提升全民美學素養，能活化空間，同時也可讓藝術家把傑出作品呈現於大眾面前，一舉多得，感謝3位站長對藝術美學的支持，方能讓會員有機會在此場域展出作品，推展大眾美學，讓民眾在候車之餘，不用走進美術館，也能增加欣賞畫作機會。\r\n參展藝術家：\r\n林鴻銘、李賜鎮、楊家順、曾永錫、林介山、林碧霞、陳芬芬\r\n鄭采駖、黃怡華、林育如、林純珠、游惠娜、黃麗萍、常連芳\r\n林添生、謝武宏、陳志雄、胡淑媛、張彩鈴、張賞、林慶熙、邱淑惠、許秀寶、王子妤、黃明玲、林育如，共26人。\r\n\r\n候車藝廊－納福\r\n展期：1/1(三)~6/30(一)\r\n展出地點：彰化火車站 \r\n\r\n', `organizer`='彰化縣美術學會', `address`='彰化縣彰化市', `start_date`='2025-01-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='彰化市（彰化縣）=', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
