INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef028d26b3242b74a3ae66', '彰化市公所社會學園第56期藝文研習活動', '活動簡介：\r\n為讓更多婦女朋友能利用時間學習，有機會培養自己的興趣、學習各項技能，圖書館特開設各種有益身心健康的課程，幫助婦女朋友自我成長、提升自信，豐富生活內涵。\r\n\r\n研習班別：\r\n語言類：基礎日語、實用英語\r\n生活美學：茶道、鋁線DIY、花藝、咖啡手沖入門\r\n藝術音樂：書法、攝影、繪畫、烏克麗麗、鋼琴、電子琴、長笛、二胡、歌唱\r\n身心靈運動：舞蹈、瑜伽、肌力體能、太極拳、國標舞\r\n科技應用：電腦課程、canva軟體\r\n神秘學：紫微斗數\r\n\r\n各研習班課時間，請參閱研習簡章及粉絲專頁', '彰化市公所', '彰化縣彰化市卦山路4號', '2025-04-22 00:00:00', '2025-07-10 00:00:00', '彰化市立圖書館', 24.07532909, 120.5694208, '報名費+1400', 'https://www.facebook.com/profile.php?id=100064540245972', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彰化市公所社會學園第56期藝文研習活動', `description`='活動簡介：\r\n為讓更多婦女朋友能利用時間學習，有機會培養自己的興趣、學習各項技能，圖書館特開設各種有益身心健康的課程，幫助婦女朋友自我成長、提升自信，豐富生活內涵。\r\n\r\n研習班別：\r\n語言類：基礎日語、實用英語\r\n生活美學：茶道、鋁線DIY、花藝、咖啡手沖入門\r\n藝術音樂：書法、攝影、繪畫、烏克麗麗、鋼琴、電子琴、長笛、二胡、歌唱\r\n身心靈運動：舞蹈、瑜伽、肌力體能、太極拳、國標舞\r\n科技應用：電腦課程、canva軟體\r\n神秘學：紫微斗數\r\n\r\n各研習班課時間，請參閱研習簡章及粉絲專頁', `organizer`='彰化市公所', `address`='彰化縣彰化市卦山路4號', `start_date`='2025-04-22 00:00:00', `end_date`='2025-07-10 00:00:00', `location`='彰化市立圖書館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='報名費+1400', `source_url`='https://www.facebook.com/profile.php?id=100064540245972', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67ef32dc8f150096aa5af1ff', '青天白日滿地「虹」森林 - 積吶虹光', '在青天白日的光芒下有一片神秘的「虹」森林，每一株樹木、每一片葉子都染上如彩虹般的顏色，陽光穿透樹梢灑下斑斕的光影，每一束光都是希望、每一道影都是夢想，樹枝上的露珠折射出七彩的光芒，如童話中的寶石閃爍著無盡的奇蹟。微風輕拂帶來森林的絮語，每一個音符都是自然的禮讚，鳥兒在樹間穿梭，它們的歌聲婉轉動聽，在這片虹森林中交織成一曲和諧的樂章。我們漫步在這裡感受大自然的溫柔撫慰，心靈在這片虹森林中得到了洗滌與重生，這是愛與和平的聖地，是希望與夢想的搖籃，在這片青天白日滿地「虹」森林中，每一刻都是永恆與美麗。\r\n\r\nhttps://www.peopo.org/news/803475', '無資料', '雲林縣雲科大圖資處藝術中心 雲創廳 (雲林縣斗六市大學路三段123號)', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '雲科大 圖資處藝術中心 雲創廳', '無資料', '無資料', '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='青天白日滿地「虹」森林 - 積吶虹光', `description`='在青天白日的光芒下有一片神秘的「虹」森林，每一株樹木、每一片葉子都染上如彩虹般的顏色，陽光穿透樹梢灑下斑斕的光影，每一束光都是希望、每一道影都是夢想，樹枝上的露珠折射出七彩的光芒，如童話中的寶石閃爍著無盡的奇蹟。微風輕拂帶來森林的絮語，每一個音符都是自然的禮讚，鳥兒在樹間穿梭，它們的歌聲婉轉動聽，在這片虹森林中交織成一曲和諧的樂章。我們漫步在這裡感受大自然的溫柔撫慰，心靈在這片虹森林中得到了洗滌與重生，這是愛與和平的聖地，是希望與夢想的搖籃，在這片青天白日滿地「虹」森林中，每一刻都是永恆與美麗。\r\n\r\nhttps://www.peopo.org/news/803475', `organizer`='無資料', `address`='雲林縣雲科大圖資處藝術中心 雲創廳 (雲林縣斗六市大學路三段123號)', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='雲科大 圖資處藝術中心 雲創廳', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
