INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f0351326b3242b74a3ae70', '玩味自然-親子香氛體驗', '玩味自然-親子香氛體驗\n\n 活動介紹 \n在老師的引領下，透過香氛的療癒力量，開啟一場嗅覺記憶之旅，深入了解自然資源的永續價值。活動當天，您將親手調製屬於自己的七里香精油按摩油，並與家人一起透過簡單的按摩，體驗自然的療癒力量，讓大自然的美好與香氣，療癒身心，並延續到日常生活中。\n \n 活動日期 | 114/05/03 (六)\n 報到時間 | 13：30\n 活動時間 | 14：00-17：00\n 活動流程 |\n 13:30〜14:00   報到\n 14:00〜14:20   氣味鮮體驗\n 14:20〜15:20   從森林氣味出發\n 15:20〜16:50   香氛體驗趣\n 16:50〜17:00   回饋與交流\n 17:00    賦歸\n\n收費 | 250元/人\n人數 | 30人\n地點 | 卑南遺址公園戶外園區/自然教室\n注意事項 | 學員請自備水壺及防蚊液，並穿著長袖衣物。\n\n►本活動提供環境教育時數 3小時\n\n \n\n 講師介紹   知本自然教育中心\n秉持守護環境的初衷，知本自然教育中心發揚林業及自然保育署「永續森林經營．維護生態保育」的願景。融合地方特色資源與原住民族傳統智慧文化，致力於在學員心中扎根環境意識，豐富孩童的心靈，提升學員的環境知能與保育意識。\n\n\n 活動集合地點  卑南遺址公園-自然教室 \n\n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n ', '國立臺灣史前文化博物館', 'ssroom (Peinan Site Park)', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '卑南遺址公園自然教室', '無資料', '無資料', '250', 'https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=50174', '[]') ON DUPLICATE KEY UPDATE `activity_name`='玩味自然-親子香氛體驗', `description`='玩味自然-親子香氛體驗\n\n 活動介紹 \n在老師的引領下，透過香氛的療癒力量，開啟一場嗅覺記憶之旅，深入了解自然資源的永續價值。活動當天，您將親手調製屬於自己的七里香精油按摩油，並與家人一起透過簡單的按摩，體驗自然的療癒力量，讓大自然的美好與香氣，療癒身心，並延續到日常生活中。\n \n 活動日期 | 114/05/03 (六)\n 報到時間 | 13：30\n 活動時間 | 14：00-17：00\n 活動流程 |\n 13:30〜14:00   報到\n 14:00〜14:20   氣味鮮體驗\n 14:20〜15:20   從森林氣味出發\n 15:20〜16:50   香氛體驗趣\n 16:50〜17:00   回饋與交流\n 17:00    賦歸\n\n收費 | 250元/人\n人數 | 30人\n地點 | 卑南遺址公園戶外園區/自然教室\n注意事項 | 學員請自備水壺及防蚊液，並穿著長袖衣物。\n\n►本活動提供環境教育時數 3小時\n\n \n\n 講師介紹   知本自然教育中心\n秉持守護環境的初衷，知本自然教育中心發揚林業及自然保育署「永續森林經營．維護生態保育」的願景。融合地方特色資源與原住民族傳統智慧文化，致力於在學員心中扎根環境意識，豐富孩童的心靈，提升學員的環境知能與保育意識。\n\n\n 活動集合地點  卑南遺址公園-自然教室 \n\n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n ', `organizer`='國立臺灣史前文化博物館', `address`='ssroom (Peinan Site Park)', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='卑南遺址公園自然教室', `latitude`='無資料', `longitude`='無資料', `ticket_price`='250', `source_url`='https://event.culture.tw/mocweb/reg/NMP/Detail.init.ctr?actId=50174', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f19f0126b3242b74a3ae72', '「2025 西港區花旗木活動-蛇燦生花‧旗遊金砂」', '「2025 西港區花旗木活動-蛇燦生花‧旗遊金砂」開幕典禮隆重登場，除了賞花之外，還設計了豐富的特色文化展、小朋友最愛的泡泡秀表演及地方市集小吃。另特邀樂團表演管弦樂、小提琴及薩克斯風，在如夢般的花海中，視覺與聽覺的雙重盛宴，感受自然與音樂的完美融合。\r\n西港區擁有豐富的自然資源與獨特的在地文化，透過這樣的季節性活動，不僅能吸引更多遊客前來觀光，也能提升民眾對於生態保護的意識，市政府將持續致力於環境保護與生態教育的推廣，為未來的發展打下良好的基礎。\r\n期待明年的花季能吸引更多的遊客，進一步提升西港的知名度和影響力，讓這片土地的美景和文化能夠被更多人所認識和珍惜。\r\n', '臺南市西港區公所', '臺南市西港區', '2025-03-30 00:00:00', '2025-04-30 00:00:00', '西港區（臺南市）=', 23.12491893, 120.2002309, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「2025 西港區花旗木活動-蛇燦生花‧旗遊金砂」', `description`='「2025 西港區花旗木活動-蛇燦生花‧旗遊金砂」開幕典禮隆重登場，除了賞花之外，還設計了豐富的特色文化展、小朋友最愛的泡泡秀表演及地方市集小吃。另特邀樂團表演管弦樂、小提琴及薩克斯風，在如夢般的花海中，視覺與聽覺的雙重盛宴，感受自然與音樂的完美融合。\r\n西港區擁有豐富的自然資源與獨特的在地文化，透過這樣的季節性活動，不僅能吸引更多遊客前來觀光，也能提升民眾對於生態保護的意識，市政府將持續致力於環境保護與生態教育的推廣，為未來的發展打下良好的基礎。\r\n期待明年的花季能吸引更多的遊客，進一步提升西港的知名度和影響力，讓這片土地的美景和文化能夠被更多人所認識和珍惜。\r\n', `organizer`='臺南市西港區公所', `address`='臺南市西港區', `start_date`='2025-03-30 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='西港區（臺南市）=', `latitude`=23.12491893, `longitude`=120.2002309, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
