INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f19f0926b3242b74a3ae7f', '2025「半線台語說故事列車-小肉圓的奇幻大冒險」會說話的月亮石', '「半線台語說故事列車-小肉圓的奇幻大冒險」\r\n充滿樂趣的台語說故事列車出發囉!!一路巡迴全縣圖書館，歡笑滿載走透透〜   \r\n\r\n邀請大小朋友與故事主角「小肉圓」一起巡迴全縣，聽故事、學台語、享手作，共同體驗奇幻冒險!!!!\r\n\r\n設計25個原創故事，每場故事以主角「小肉圓」展開奇幻冒險，大小朋友隨著故事情節，一起與小肉圓一同走進森林、沙漠、海底世界、冰雪城堡，面對挑戰、結交夥伴，展開一場充滿趣味的台語故事冒險。\r\n\r\n聽故事不限名額喔~依各圖書館場地可容納人數為限\r\nDIY手作每場限額40名(採現場報名方式,材料包優先提供予小朋友)', '彰化縣文化局', '彰化縣田尾鄉公所路185號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '彰化縣田尾鄉立圖書館', 23.90056065, 120.5223244, '無資料', 'https://www.bocach.gov.tw/News_Content.aspx?n=19&s=50538', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025「半線台語說故事列車-小肉圓的奇幻大冒險」會說話的月亮石', `description`='「半線台語說故事列車-小肉圓的奇幻大冒險」\r\n充滿樂趣的台語說故事列車出發囉!!一路巡迴全縣圖書館，歡笑滿載走透透〜   \r\n\r\n邀請大小朋友與故事主角「小肉圓」一起巡迴全縣，聽故事、學台語、享手作，共同體驗奇幻冒險!!!!\r\n\r\n設計25個原創故事，每場故事以主角「小肉圓」展開奇幻冒險，大小朋友隨著故事情節，一起與小肉圓一同走進森林、沙漠、海底世界、冰雪城堡，面對挑戰、結交夥伴，展開一場充滿趣味的台語故事冒險。\r\n\r\n聽故事不限名額喔~依各圖書館場地可容納人數為限\r\nDIY手作每場限額40名(採現場報名方式,材料包優先提供予小朋友)', `organizer`='彰化縣文化局', `address`='彰化縣田尾鄉公所路185號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='彰化縣田尾鄉立圖書館', `latitude`=23.90056065, `longitude`=120.5223244, `ticket_price`='無資料', `source_url`='https://www.bocach.gov.tw/News_Content.aspx?n=19&s=50538', `image_url`='[]';
