INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f19f0926b3242b74a3ae88', '福蛇獻瑞 乙巳蛇年文開詩社社友詩書畫多元聯展', '鹿港「文開詩社」為展現傳統藝術之美，特別以「福蛇獻瑞」為主題，在「鹿港鎮圖書藝文中心」，盛大舉辦「乙巳蛇年文開詩社社友聯展」，匯聚上百件精緻的書法、篆刻、漢學、國畫等創作品，融合詩詞歌賦與書藝創作，充分彰顯深厚的文化底蘊！\r\n\r\n鹿港「文開詩社」是集結社會文人雅士、熱愛古典詩詞的同好所創立，以傳承發揚古漢學文化為使命、研究詩學為宗旨，多年來致力於推廣漢學課程、傳統詩詞書寫及吟唱、國樂演奏、書法藝術；現任社長尤能銓表示，這次社員所參展的作品囊括也篆、楷、隸、行、草等各種書體，內容則涵蓋有自創詩詞、古詩詞歌賦及摹擬碑文字帖，把書藝美學發揮得淋漓盡致，是社員們共同努力學習的成果，希望藉此展覽拋磚引玉，讓更多人得以看見傳統文藝之美。', '彰化縣鹿港鎮立圖書館', '彰化縣鹿港鎮龍舟路22號', '2025-03-27 00:00:00', '2025-05-04 00:00:00', '鹿港鎮立圖書藝文中心', 24.08286685, 120.4385491, '無資料', 'https://www.facebook.com/LukangPublicLibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='福蛇獻瑞 乙巳蛇年文開詩社社友詩書畫多元聯展', `description`='鹿港「文開詩社」為展現傳統藝術之美，特別以「福蛇獻瑞」為主題，在「鹿港鎮圖書藝文中心」，盛大舉辦「乙巳蛇年文開詩社社友聯展」，匯聚上百件精緻的書法、篆刻、漢學、國畫等創作品，融合詩詞歌賦與書藝創作，充分彰顯深厚的文化底蘊！\r\n\r\n鹿港「文開詩社」是集結社會文人雅士、熱愛古典詩詞的同好所創立，以傳承發揚古漢學文化為使命、研究詩學為宗旨，多年來致力於推廣漢學課程、傳統詩詞書寫及吟唱、國樂演奏、書法藝術；現任社長尤能銓表示，這次社員所參展的作品囊括也篆、楷、隸、行、草等各種書體，內容則涵蓋有自創詩詞、古詩詞歌賦及摹擬碑文字帖，把書藝美學發揮得淋漓盡致，是社員們共同努力學習的成果，希望藉此展覽拋磚引玉，讓更多人得以看見傳統文藝之美。', `organizer`='彰化縣鹿港鎮立圖書館', `address`='彰化縣鹿港鎮龍舟路22號', `start_date`='2025-03-27 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='鹿港鎮立圖書藝文中心', `latitude`=24.08286685, `longitude`=120.4385491, `ticket_price`='無資料', `source_url`='https://www.facebook.com/LukangPublicLibrary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f19f0926b3242b74a3ae8a', '五田窯－羅平景．羅文祺父子當代陶瓷展', '發揚陶瓷藝術傳統與現代技法之美的「五田窯－羅平景．羅文祺父子當代陶瓷展」，4月9日起至5月4日止在鹿港公會堂展出約60件精選作品，呈現羅氏父子在陶瓷藝術領域的卓越造詣，透過豐富的釉色變化與細膩技法，帶來視覺與心靈的雙重饗宴，志宏歡迎大家一同前來悠遊陶藝之美，欣賞傳統與創新交匯的傑出工藝成果。', '彰化縣鹿港鎮公所', '彰化縣鹿港鎮埔頭街74號', '2025-04-09 00:00:00', '2025-05-04 00:00:00', '鹿港公會堂(藝文館)', 24.08286685, 120.4385491, '無資料', 'https://www.facebook.com/lukangculture', '[]') ON DUPLICATE KEY UPDATE `activity_name`='五田窯－羅平景．羅文祺父子當代陶瓷展', `description`='發揚陶瓷藝術傳統與現代技法之美的「五田窯－羅平景．羅文祺父子當代陶瓷展」，4月9日起至5月4日止在鹿港公會堂展出約60件精選作品，呈現羅氏父子在陶瓷藝術領域的卓越造詣，透過豐富的釉色變化與細膩技法，帶來視覺與心靈的雙重饗宴，志宏歡迎大家一同前來悠遊陶藝之美，欣賞傳統與創新交匯的傑出工藝成果。', `organizer`='彰化縣鹿港鎮公所', `address`='彰化縣鹿港鎮埔頭街74號', `start_date`='2025-04-09 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='鹿港公會堂(藝文館)', `latitude`=24.08286685, `longitude`=120.4385491, `ticket_price`='無資料', `source_url`='https://www.facebook.com/lukangculture', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f19f0926b3242b74a3ae8c', '員獅楊藝-員林獅子會員員獅墨藝社會員聯展', '員獅楊藝-員林獅子會員員獅墨藝社會員聯展	4/11(五)~5/06(二)', '成美文化園', '彰化縣永靖鄉中山路2段60號', '2025-04-11 00:00:00', '2025-05-06 00:00:00', '成美文化園', 23.92139507, 120.5416032, '無資料', 'https://www.facebook.com/cmcp1885', '[]') ON DUPLICATE KEY UPDATE `activity_name`='員獅楊藝-員林獅子會員員獅墨藝社會員聯展', `description`='員獅楊藝-員林獅子會員員獅墨藝社會員聯展	4/11(五)~5/06(二)', `organizer`='成美文化園', `address`='彰化縣永靖鄉中山路2段60號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-05-06 00:00:00', `location`='成美文化園', `latitude`=23.92139507, `longitude`=120.5416032, `ticket_price`='無資料', `source_url`='https://www.facebook.com/cmcp1885', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f19f0926b3242b74a3ae8d', '雕塑的力量-台灣雕塑今昔匯展', '台灣本土百年來諸多雕塑藝術家，以不鏽鋼、陶、青銅、鐵、石膏等不同媒材創作，展現出向度多變的雕塑發展脈絡。本展從蒲添生(1912~1996)在台早期開拓雕塑界所創作的人物塑像；丘雲(1912~2009)細膩詮釋人物形態的半身像；陳庭詩(1913~2002)饒富哲思的鐵雕；楊英風(1926~1997)具現代宏觀動態造形的鋼鐵創作；李再鈐(1928~)呈現東方哲理與西方極簡的幾何造形作品；郭清治(1939~)結合石雕與鋼雕以表現生命原質風格之作；李茂宗(1940~)以「心象」為核心精神的大膽造形陶塑系列，至高燦興(1945~2017)變化豐富的鋼鐵雕塑。各名家雕塑作品用色、主題、形象各有特色，傑出之處可見一斑。', '台灣創價學會秀水藝文中心', '彰化縣秀水鄉平安五街61號2樓', '2025-02-05 00:00:00', '2025-05-09 00:00:00', '台灣創價學會秀水藝文中心', 24.03249405, 120.5041184, '無資料', 'https://www.sokaculture.org.tw/exhibition/%E9%9B%95%E5%A1%91%E7%9A%84%E5%8A%9B%E9%87%8F-%E5%8F%B0%E7%81%A3%E4%BB%8A%E6%98%94%E9%9B%95%E5%A1%91%E6%BB%99%E5%B1%95', '[]') ON DUPLICATE KEY UPDATE `activity_name`='雕塑的力量-台灣雕塑今昔匯展', `description`='台灣本土百年來諸多雕塑藝術家，以不鏽鋼、陶、青銅、鐵、石膏等不同媒材創作，展現出向度多變的雕塑發展脈絡。本展從蒲添生(1912~1996)在台早期開拓雕塑界所創作的人物塑像；丘雲(1912~2009)細膩詮釋人物形態的半身像；陳庭詩(1913~2002)饒富哲思的鐵雕；楊英風(1926~1997)具現代宏觀動態造形的鋼鐵創作；李再鈐(1928~)呈現東方哲理與西方極簡的幾何造形作品；郭清治(1939~)結合石雕與鋼雕以表現生命原質風格之作；李茂宗(1940~)以「心象」為核心精神的大膽造形陶塑系列，至高燦興(1945~2017)變化豐富的鋼鐵雕塑。各名家雕塑作品用色、主題、形象各有特色，傑出之處可見一斑。', `organizer`='台灣創價學會秀水藝文中心', `address`='彰化縣秀水鄉平安五街61號2樓', `start_date`='2025-02-05 00:00:00', `end_date`='2025-05-09 00:00:00', `location`='台灣創價學會秀水藝文中心', `latitude`=24.03249405, `longitude`=120.5041184, `ticket_price`='無資料', `source_url`='https://www.sokaculture.org.tw/exhibition/%E9%9B%95%E5%A1%91%E7%9A%84%E5%8A%9B%E9%87%8F-%E5%8F%B0%E7%81%A3%E4%BB%8A%E6%98%94%E9%9B%95%E5%A1%91%E6%BB%99%E5%B1%95', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f19f0926b3242b74a3ae8e', '樹珮Art繪畫教室師生聯展－畫媞', '「樹珮Art繪畫教室師生聯展－畫媞」自114年3月11日（星期二）起至114年5月8日（星期四），於大村鄉公所文化藝廊展出，展出時間為每週一至週五上午8時至下午5時（適逢假日與國定假日不開放參觀）。\r\n\r\n本次展出作品係由大村鄉駐鄉藝術家聯誼會賴珮璉老師及張鶴耀老師帶領其學員共同展出，展出作品約50件，誠摯邀請民眾前來觀賞。', '彰化縣大村鄉公所', '彰化縣大村鄉中正西路338號', '2025-03-11 00:00:00', '2025-05-08 00:00:00', '彰化縣大村鄉公所', 23.99209206, 120.5586866, '無資料', 'https://town.chcg.gov.tw/dacun/00home/index05.aspx', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樹珮Art繪畫教室師生聯展－畫媞', `description`='「樹珮Art繪畫教室師生聯展－畫媞」自114年3月11日（星期二）起至114年5月8日（星期四），於大村鄉公所文化藝廊展出，展出時間為每週一至週五上午8時至下午5時（適逢假日與國定假日不開放參觀）。\r\n\r\n本次展出作品係由大村鄉駐鄉藝術家聯誼會賴珮璉老師及張鶴耀老師帶領其學員共同展出，展出作品約50件，誠摯邀請民眾前來觀賞。', `organizer`='彰化縣大村鄉公所', `address`='彰化縣大村鄉中正西路338號', `start_date`='2025-03-11 00:00:00', `end_date`='2025-05-08 00:00:00', `location`='彰化縣大村鄉公所', `latitude`=23.99209206, `longitude`=120.5586866, `ticket_price`='無資料', `source_url`='https://town.chcg.gov.tw/dacun/00home/index05.aspx', `image_url`='[]';
