INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f19f0926b3242b74a3ae91', '彰化縣育德國小 蛇影藝蹤 第六屆學生美展', '展覽內容：\r\n本展覽由育德國小所策劃，王莉老師指導。本次展覽是育德國小在二林圖書館展出的第六屆學生美展，讓孩子發揮創意，共同創作，同時也讓大家看見孩子筆下獨特的「童藝世界」，感受童心的純真與創意的力量。歡迎大家一起來欣賞孩子們的作品！', '彰化縣二林鎮立圖書館', '彰化縣二林鎮斗苑路4段626號', '2025-04-01 00:00:00', '2025-04-28 00:00:00', '彰化縣二林鎮立圖書館', 23.91621405, 120.404225, '無資料', 'https://www.facebook.com/profile.php?id=100064354342750#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彰化縣育德國小 蛇影藝蹤 第六屆學生美展', `description`='展覽內容：\r\n本展覽由育德國小所策劃，王莉老師指導。本次展覽是育德國小在二林圖書館展出的第六屆學生美展，讓孩子發揮創意，共同創作，同時也讓大家看見孩子筆下獨特的「童藝世界」，感受童心的純真與創意的力量。歡迎大家一起來欣賞孩子們的作品！', `organizer`='彰化縣二林鎮立圖書館', `address`='彰化縣二林鎮斗苑路4段626號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-28 00:00:00', `location`='彰化縣二林鎮立圖書館', `latitude`=23.91621405, `longitude`=120.404225, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064354342750#', `image_url`='[]';
