INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f19f0a26b3242b74a3ae93', '彰化縣儒林書法學會-114年儒林盃學生書法比賽', '橫豎撐天地， 撇捺寫人生。 \r\n一筆一劃皆風骨， \r\n一撇一捺是傳承。\r\n二林鎮公所與彰化縣儒林書法學會共同舉辦一年一度《儒林盃》學生書法比賽，已開始報名囉！\r\n報名截止日期：即日起至4/15日止。\r\n比賽日期：114年4月20日（星期日）上午9:00-10:30\r\n比賽地點：國立二林工商', '儒林書法學會', '彰化縣二林鎮', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '二林鎮（彰化縣）=', 23.91621405, 120.404225, '無資料', 'https://www.facebook.com/profile.php?id=100064354342750', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彰化縣儒林書法學會-114年儒林盃學生書法比賽', `description`='橫豎撐天地， 撇捺寫人生。 \r\n一筆一劃皆風骨， \r\n一撇一捺是傳承。\r\n二林鎮公所與彰化縣儒林書法學會共同舉辦一年一度《儒林盃》學生書法比賽，已開始報名囉！\r\n報名截止日期：即日起至4/15日止。\r\n比賽日期：114年4月20日（星期日）上午9:00-10:30\r\n比賽地點：國立二林工商', `organizer`='儒林書法學會', `address`='彰化縣二林鎮', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='二林鎮（彰化縣）=', `latitude`=23.91621405, `longitude`=120.404225, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064354342750', `image_url`='[]';
