INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f19f0a26b3242b74a3ae9a', '臺中市采韻美術協會第九屆會員聯展', '在此新世紀文風當盛之際，生命的美麗是每個人所追求的。然而在台灣中部地區，有一群文藝豐碩的風雅之人，他們來自社會的各行各業，更不乏在其專業領域的資深人士，但在逐夢藝術的路上，卻也不辭辛勞地追隨文人藝術家曹天韻老師，醉心於繪畫的創作。若說「畫作即是我們的生命」，豈不正是這個社團的共同信念。采韻美術協會成立迄今邁入第18年，當初由創會長曹天韻老師帶領眾多愛好繪畫及藝術的社會菁英共同組成，同時也經常舉辦聯合展出，其中主要是以生活藝術為主，涵蓋水墨、書法、編織、瓷繪、手工藝品。除了展現學習成果，也與地方文創相結合，讓藝術與生活融合。此次展覽，以繽紛的花鳥生態及生活景緻，呈現周遭環境的生命力，在宣紙之上記錄采韻之美。此次展出「采韻春曉」的系列作品，可以讓觀賞者體會台灣各階層人士的藝術涵養與文化底蘊，並在欣欣向榮的幅幅畫作中，共同迎接2025年美麗春天的來臨。', '彰化秀傳紀念醫院', '彰化縣鹿港鎮鹿工路六號  (彰濱工業區鹿港區)', '2025-03-13 00:00:00', '2025-04-20 00:00:00', '彰濱秀傳健康園區', 24.08286685, 120.4385491, '無資料', 'https://www.cbshow.org.tw/Blog/Default.aspx?blog=Q0JfQXJ0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺中市采韻美術協會第九屆會員聯展', `description`='在此新世紀文風當盛之際，生命的美麗是每個人所追求的。然而在台灣中部地區，有一群文藝豐碩的風雅之人，他們來自社會的各行各業，更不乏在其專業領域的資深人士，但在逐夢藝術的路上，卻也不辭辛勞地追隨文人藝術家曹天韻老師，醉心於繪畫的創作。若說「畫作即是我們的生命」，豈不正是這個社團的共同信念。采韻美術協會成立迄今邁入第18年，當初由創會長曹天韻老師帶領眾多愛好繪畫及藝術的社會菁英共同組成，同時也經常舉辦聯合展出，其中主要是以生活藝術為主，涵蓋水墨、書法、編織、瓷繪、手工藝品。除了展現學習成果，也與地方文創相結合，讓藝術與生活融合。此次展覽，以繽紛的花鳥生態及生活景緻，呈現周遭環境的生命力，在宣紙之上記錄采韻之美。此次展出「采韻春曉」的系列作品，可以讓觀賞者體會台灣各階層人士的藝術涵養與文化底蘊，並在欣欣向榮的幅幅畫作中，共同迎接2025年美麗春天的來臨。', `organizer`='彰化秀傳紀念醫院', `address`='彰化縣鹿港鎮鹿工路六號  (彰濱工業區鹿港區)', `start_date`='2025-03-13 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='彰濱秀傳健康園區', `latitude`=24.08286685, `longitude`=120.4385491, `ticket_price`='無資料', `source_url`='https://www.cbshow.org.tw/Blog/Default.aspx?blog=Q0JfQXJ0', `image_url`='[]';
