INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f19f0a26b3242b74a3ae9d', '陳佳秀繪畫個展', '陳佳秀，德藝美術工作室 會員、台中市葫蘆墩美術研究會會員、中華漆畫學會會員、佛教慈濟慈善基金會志工，長期跟錢靖芬老師學畫。本次繪畫主題為大地之美，畫出嘉明湖、富士山、阿拉斯加...等各地美景，歡迎蒞臨參觀。', '彰化秀傳紀念醫院', '彰化縣鹿港鎮鹿工路六號  (彰濱工業區鹿港區)', '2025-02-28 00:00:00', '2025-04-29 00:00:00', '彰濱秀傳健康園區', 24.08286685, 120.4385491, '無資料', 'https://www.cbshow.org.tw/Blog/Default.aspx?blog=Q0JfQXJ0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陳佳秀繪畫個展', `description`='陳佳秀，德藝美術工作室 會員、台中市葫蘆墩美術研究會會員、中華漆畫學會會員、佛教慈濟慈善基金會志工，長期跟錢靖芬老師學畫。本次繪畫主題為大地之美，畫出嘉明湖、富士山、阿拉斯加...等各地美景，歡迎蒞臨參觀。', `organizer`='彰化秀傳紀念醫院', `address`='彰化縣鹿港鎮鹿工路六號  (彰濱工業區鹿港區)', `start_date`='2025-02-28 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='彰濱秀傳健康園區', `latitude`=24.08286685, `longitude`=120.4385491, `ticket_price`='無資料', `source_url`='https://www.cbshow.org.tw/Blog/Default.aspx?blog=Q0JfQXJ0', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f19f0a26b3242b74a3ae9e', '2025年4月【台灣玻璃館音樂饗宴表演】共8天', '活動內容：\r\n台灣玻璃館開館至今已五年餘，來館參訪人數已達440萬人次，以『四面亮麗、八方驚奇』為座右銘，結合了台灣生態、文化之玻璃藝術，讓人來到這裡能有耳目一新的感覺。\r\n台灣玻璃館將於每週末舉辦音樂會，除了傳統國樂、西洋薩克斯風、古箏、陶笛、長笛、二胡…音樂響宴。還有靜態藝文玻璃展。\r\n', '台灣玻璃館', '彰化縣鹿港鎮鹿工南四路30號', '2025-04-05 00:00:00', '2025-04-27 00:00:00', '台灣玻璃館', 24.08286685, 120.4385491, '無資料', 'https://www.facebook.com/TGGallery/?fref=nf', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年4月【台灣玻璃館音樂饗宴表演】共8天', `description`='活動內容：\r\n台灣玻璃館開館至今已五年餘，來館參訪人數已達440萬人次，以『四面亮麗、八方驚奇』為座右銘，結合了台灣生態、文化之玻璃藝術，讓人來到這裡能有耳目一新的感覺。\r\n台灣玻璃館將於每週末舉辦音樂會，除了傳統國樂、西洋薩克斯風、古箏、陶笛、長笛、二胡…音樂響宴。還有靜態藝文玻璃展。\r\n', `organizer`='台灣玻璃館', `address`='彰化縣鹿港鎮鹿工南四路30號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='台灣玻璃館', `latitude`=24.08286685, `longitude`=120.4385491, `ticket_price`='無資料', `source_url`='https://www.facebook.com/TGGallery/?fref=nf', `image_url`='[]';
