INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f266258f150096aa5af200', '國北教藝設系藝術組 114級畢業展演《開啟新檔》', '【開啟新檔 Ctrl+N】國立臺北教育大學藝術與造形設計學系藝術組114級畢業展演 國立臺北教育大學藝術與造形設計學系 114 級畢業展 《開啟新檔 Ctrl+N》，將於 5 月 16 日至 5 月 18 日 在 臺北市華山文創園區東 C 館展出。本次展覽匯集當代經典主題創作、新媒體藝術、複合媒材創作及藝術理論與藝術教育等約 170 件作品，展現學生們豐沛的創作能量，誠摯邀請各界蒞臨，共同感受這場藝術盛宴。 《開啟新檔 Ctrl+N》不僅是鍵盤上的快捷指令，更象徵數位時代的特質——無限次重新開始的可能性。對 Z 世代的學生而言，這個幾近反射性的「指令動作」已超越其原本的功能，成為一種符號化的創作習慣。它取代了傳統紙本書寫與沉澱的過程，成為藝術創作者敘述自身、探索世界的方式。 「開啟新檔」不僅是技術上的起點，更是我們對於未來的想像與拼貼。我們透過新檔案的創建與編譯，在不斷編寫與更新的過程中直視自身，試圖在數位化的洪流中保有獨立的精神空間與個人意義。 更多活動及商品資訊請見《開啟新檔Ctrl+N》 展演活動連結：https://reurl.cc/5DODK7 線上展連結：https://ctrln114ntue.wixsite.com/ctrln114', '國立臺北教育大學藝術與造形設計114級', '臺北市100 台北市中正區八德路一段1號', '2025-05-16 00:00:00', '2025-05-18 00:00:00', '華山1914⽂創產業園區 東2C館', '無資料', '無資料', '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國北教藝設系藝術組 114級畢業展演《開啟新檔》', `description`='【開啟新檔 Ctrl+N】國立臺北教育大學藝術與造形設計學系藝術組114級畢業展演 國立臺北教育大學藝術與造形設計學系 114 級畢業展 《開啟新檔 Ctrl+N》，將於 5 月 16 日至 5 月 18 日 在 臺北市華山文創園區東 C 館展出。本次展覽匯集當代經典主題創作、新媒體藝術、複合媒材創作及藝術理論與藝術教育等約 170 件作品，展現學生們豐沛的創作能量，誠摯邀請各界蒞臨，共同感受這場藝術盛宴。 《開啟新檔 Ctrl+N》不僅是鍵盤上的快捷指令，更象徵數位時代的特質——無限次重新開始的可能性。對 Z 世代的學生而言，這個幾近反射性的「指令動作」已超越其原本的功能，成為一種符號化的創作習慣。它取代了傳統紙本書寫與沉澱的過程，成為藝術創作者敘述自身、探索世界的方式。 「開啟新檔」不僅是技術上的起點，更是我們對於未來的想像與拼貼。我們透過新檔案的創建與編譯，在不斷編寫與更新的過程中直視自身，試圖在數位化的洪流中保有獨立的精神空間與個人意義。 更多活動及商品資訊請見《開啟新檔Ctrl+N》 展演活動連結：https://reurl.cc/5DODK7 線上展連結：https://ctrln114ntue.wixsite.com/ctrln114', `organizer`='國立臺北教育大學藝術與造形設計114級', `address`='臺北市100 台北市中正區八德路一段1號', `start_date`='2025-05-16 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='華山1914⽂創產業園區 東2C館', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
