INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f33aab8f150096aa5af201', '梁實秋散文大師首獎駱以軍專題演講【靈光一閃的瞬刻】', '【2025人文季 梁實秋文學大師駐校作家專題演講】\r\n駱以軍老師：靈光一閃的瞬刻\r\n\r\n你是否也曾好奇一位文學大師如何創作出打動人心的文字？快來聽駱以軍老師現身說法為你解密！寫作中心很榮幸邀請到第37屆梁實秋散文大師獎首獎得主——駱以軍老師，蒞臨本校進行專題講座！\r\n\r\n駱以軍老師的文學成就卓著，屢獲文壇多項大獎，包括台灣文學獎長篇小說金典獎、聯合報文學大獎、紅樓夢獎世界華文長篇小說首獎等多項殊榮。他的代表作品包括《降生十二星座》、《西夏旅館》、《匡超人》、《女兒》與《大疫》等，作品風格獨特鮮明，深受讀者喜愛。並以最新力作《如何抵達人心，如何為愛畫刻度》獲得本屆的梁實秋散文大師獎首獎！\r\n\r\n在這場精彩可期的講座中，駱以軍老師將與我們分享散文創作的心路歷程與靈光一閃的瞬刻，帶領大家探索文學創作的奧秘，激發無盡的創作靈感。\r\n\r\n時間：2025年4月25日（五）12:00 – 14:00\r\n地點：文學院B1會議室\r\n報名表單：https://reurl.cc/aenx5l\r\n報名時間:即日起至114年4月23日(三)中午12:00止\r\n名額有限，趕快報名，千萬別錯過！快來與駱以軍老師一起探索文字的魔力吧！\r\n\r\n主辦單位：國立臺灣師範大學全球華文寫作中心\r\n指導單位：國立臺灣師範大學文學院', '國立臺灣師範大學全球華文寫作中心', '臺北市大安區和平東路一段162號', '2025-04-25 00:00:00', '2025-04-25 00:00:00', '國立臺灣師範大學誠大樓文學院B1會議室', 25.02677012, 121.5434446, '無資料', 'https://reurl.cc/aenx5l', '[]') ON DUPLICATE KEY UPDATE `activity_name`='梁實秋散文大師首獎駱以軍專題演講【靈光一閃的瞬刻】', `description`='【2025人文季 梁實秋文學大師駐校作家專題演講】\r\n駱以軍老師：靈光一閃的瞬刻\r\n\r\n你是否也曾好奇一位文學大師如何創作出打動人心的文字？快來聽駱以軍老師現身說法為你解密！寫作中心很榮幸邀請到第37屆梁實秋散文大師獎首獎得主——駱以軍老師，蒞臨本校進行專題講座！\r\n\r\n駱以軍老師的文學成就卓著，屢獲文壇多項大獎，包括台灣文學獎長篇小說金典獎、聯合報文學大獎、紅樓夢獎世界華文長篇小說首獎等多項殊榮。他的代表作品包括《降生十二星座》、《西夏旅館》、《匡超人》、《女兒》與《大疫》等，作品風格獨特鮮明，深受讀者喜愛。並以最新力作《如何抵達人心，如何為愛畫刻度》獲得本屆的梁實秋散文大師獎首獎！\r\n\r\n在這場精彩可期的講座中，駱以軍老師將與我們分享散文創作的心路歷程與靈光一閃的瞬刻，帶領大家探索文學創作的奧秘，激發無盡的創作靈感。\r\n\r\n時間：2025年4月25日（五）12:00 – 14:00\r\n地點：文學院B1會議室\r\n報名表單：https://reurl.cc/aenx5l\r\n報名時間:即日起至114年4月23日(三)中午12:00止\r\n名額有限，趕快報名，千萬別錯過！快來與駱以軍老師一起探索文字的魔力吧！\r\n\r\n主辦單位：國立臺灣師範大學全球華文寫作中心\r\n指導單位：國立臺灣師範大學文學院', `organizer`='國立臺灣師範大學全球華文寫作中心', `address`='臺北市大安區和平東路一段162號', `start_date`='2025-04-25 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='國立臺灣師範大學誠大樓文學院B1會議室', `latitude`=25.02677012, `longitude`=121.5434446, `ticket_price`='無資料', `source_url`='https://reurl.cc/aenx5l', `image_url`='[]';
