INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e126b3242b74a3aee6', '高雄市路竹區一甲國小國樂團113學年度成果發表會', '一甲國小國樂團成立於91年6月，歷年來獲獎無數，多次代表高雄市(縣)參加全國學生音樂比賽均獲佳績。107學年再次取得代表高雄市參加全國學生音樂比賽南區決賽國小B組國樂合奏及絲竹室內樂(連續2年特優，保送)的代表權。111、112學年度參加全國學生音樂比賽南區決賽，兩項皆榮獲雙特優的殊榮。113學年度代表高雄市參加全國學生音樂比賽南區決賽，再度兩項皆榮獲雙特優的殊榮。累積至今，連續3年特優。\r\n\r\n團員們除了平時的例行訓練外，亦常代表學校於社區活動中演出，頗獲好評。每學年度的成果發表會是孩子們展現練習成果的好機會，個個躍躍欲試，除了豐富小朋友的人生經驗，更增進其自信心，也藉此請各界先進及前輩指導提攜，期能精益求精。\r\n\r\n此次期末展演，透過大合奏、小合奏與各式樂器獨奏等多元的曲風表演，即將引領觀眾們一同浸淫悠揚悅耳的國樂響宴。\r\n', '高雄市政府文化局', '高雄市岡山區009鄰岡山南路42號', '2025-05-04 00:00:00', '2025-05-04 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='高雄市路竹區一甲國小國樂團113學年度成果發表會', `description`='一甲國小國樂團成立於91年6月，歷年來獲獎無數，多次代表高雄市(縣)參加全國學生音樂比賽均獲佳績。107學年再次取得代表高雄市參加全國學生音樂比賽南區決賽國小B組國樂合奏及絲竹室內樂(連續2年特優，保送)的代表權。111、112學年度參加全國學生音樂比賽南區決賽，兩項皆榮獲雙特優的殊榮。113學年度代表高雄市參加全國學生音樂比賽南區決賽，再度兩項皆榮獲雙特優的殊榮。累積至今，連續3年特優。\r\n\r\n團員們除了平時的例行訓練外，亦常代表學校於社區活動中演出，頗獲好評。每學年度的成果發表會是孩子們展現練習成果的好機會，個個躍躍欲試，除了豐富小朋友的人生經驗，更增進其自信心，也藉此請各界先進及前輩指導提攜，期能精益求精。\r\n\r\n此次期末展演，透過大合奏、小合奏與各式樂器獨奏等多元的曲風表演，即將引領觀眾們一同浸淫悠揚悅耳的國樂響宴。\r\n', `organizer`='高雄市政府文化局', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-05-04 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e126b3242b74a3aee7', '時光回溯', '蔡文國小國樂團成立於民國96年9月，團員們歷年所參加的高雄市音樂比賽及全國學生音樂比賽，連年都獲得優異佳績，今年不只在高雄市音樂比賽榮獲優等也取得全國賽代表權，在全國學生音樂賽的表現，維持一定的水準，榮獲優等佳績，蔡文國小國樂團致力於國樂的教育深耕，讓孩子在樂韻互動中找到自信及表現的舞台。\r\n\r\n在歷任音樂總監的指導下，團員的實力及素質日益精進，也積極參加音樂比賽及各項活動演出。目前有近四十名團員，由蔡昱嘉老師擔任音樂總監，於每週三下午進行團練，帶領團員悠遊於傳統樂器的音韻裡。\r\n\r\n今年發表會主題定為「時光回溯」，別具意義地以時下孩子們的流行音樂及孩子爸媽們學生時代的流行音樂為主軸，有如時光回溯，充滿青春回憶，以時光交錯的方式呈現不同時代的音樂，這場音樂饗宴猶如坐時光機，重溫學生時期，也聆聽孩子們喜愛的流行音樂，藉此連接起親子間的橋樑，這將是一場充滿溫馨之旅，且可盡情地感受傳統樂器所演奏的流行音樂，帶來不同的風格與韻味，是情感、樂韻及童趣間的交融與交織，邀請各種年齡層的觀眾一起共享音樂盛宴。\r\n\r\n演出曲目如下：\r\nA團：步步高、蘇堤小景、校園封神榜、台灣尚勇\r\nAB團：蘑菇濃湯\r\nBC團：三輪車、老先生進行曲\r\n吹管組：雨蝶、孤勇者\r\n揚琴組：APT、愛你\r\n彈撥組：光陰的故事、知足\r\n低音組：Popular、櫻桃小丸子\r\n古箏組：哆啦A夢、滄海一聲笑\r\n二胡組：中華一番、灌籃高手', '高雄市政府文化局', '高雄市岡山區009鄰岡山南路42號', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='時光回溯', `description`='蔡文國小國樂團成立於民國96年9月，團員們歷年所參加的高雄市音樂比賽及全國學生音樂比賽，連年都獲得優異佳績，今年不只在高雄市音樂比賽榮獲優等也取得全國賽代表權，在全國學生音樂賽的表現，維持一定的水準，榮獲優等佳績，蔡文國小國樂團致力於國樂的教育深耕，讓孩子在樂韻互動中找到自信及表現的舞台。\r\n\r\n在歷任音樂總監的指導下，團員的實力及素質日益精進，也積極參加音樂比賽及各項活動演出。目前有近四十名團員，由蔡昱嘉老師擔任音樂總監，於每週三下午進行團練，帶領團員悠遊於傳統樂器的音韻裡。\r\n\r\n今年發表會主題定為「時光回溯」，別具意義地以時下孩子們的流行音樂及孩子爸媽們學生時代的流行音樂為主軸，有如時光回溯，充滿青春回憶，以時光交錯的方式呈現不同時代的音樂，這場音樂饗宴猶如坐時光機，重溫學生時期，也聆聽孩子們喜愛的流行音樂，藉此連接起親子間的橋樑，這將是一場充滿溫馨之旅，且可盡情地感受傳統樂器所演奏的流行音樂，帶來不同的風格與韻味，是情感、樂韻及童趣間的交融與交織，邀請各種年齡層的觀眾一起共享音樂盛宴。\r\n\r\n演出曲目如下：\r\nA團：步步高、蘇堤小景、校園封神榜、台灣尚勇\r\nAB團：蘑菇濃湯\r\nBC團：三輪車、老先生進行曲\r\n吹管組：雨蝶、孤勇者\r\n揚琴組：APT、愛你\r\n彈撥組：光陰的故事、知足\r\n低音組：Popular、櫻桃小丸子\r\n古箏組：哆啦A夢、滄海一聲笑\r\n二胡組：中華一番、灌籃高手', `organizer`='高雄市政府文化局', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e126b3242b74a3aee8', '開創新局 超越巔峰 蓄滿正能量 【公益】向前行~第七屆慈善音樂會', ' 為幫助弱勢團體能夠有經費做更多的社服及幫助更多需要幫助的人，特舉辦慈善音樂會，藉由音樂會演出募款及義賣門票，所得捐款再捐贈多個社福單位，讓我們用音樂~把愛傳出去!!\r\n\r\n\r\n', '高雄市政府文化局', '高雄市岡山區009鄰岡山南路42號', '2025-05-18 00:00:00', '2025-05-18 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='開創新局 超越巔峰 蓄滿正能量 【公益】向前行~第七屆慈善音樂會', `description`=' 為幫助弱勢團體能夠有經費做更多的社服及幫助更多需要幫助的人，特舉辦慈善音樂會，藉由音樂會演出募款及義賣門票，所得捐款再捐贈多個社福單位，讓我們用音樂~把愛傳出去!!\r\n\r\n\r\n', `organizer`='高雄市政府文化局', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-05-18 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e126b3242b74a3aee9', '2025年岡山國中學生藝文、體育聯合展演-「樂舞飛揚，岡中情」', ' 2025年岡山國中學生藝文、體育聯合展演「樂舞飛揚，岡中情」，演出節目有民俗舞、現代舞、古典舞、鋼琴獨奏、雙人歌唱、管樂隊、體育班跆拳道、體操隊表演等，展現學生們學習成果。\r\n\r\n\r\n', '高雄市政府文化局', '高雄市岡山區009鄰岡山南路42號', '2025-05-22 00:00:00', '2025-05-22 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年岡山國中學生藝文、體育聯合展演-「樂舞飛揚，岡中情」', `description`=' 2025年岡山國中學生藝文、體育聯合展演「樂舞飛揚，岡中情」，演出節目有民俗舞、現代舞、古典舞、鋼琴獨奏、雙人歌唱、管樂隊、體育班跆拳道、體操隊表演等，展現學生們學習成果。\r\n\r\n\r\n', `organizer`='高雄市政府文化局', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-05-22 00:00:00', `end_date`='2025-05-22 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e126b3242b74a3aeea', '前峰國中社團成果展《時光漫溯‧乘峰飛翔》', ' 前峰國中除豐碩的升學成果外，也強調多元學習與適性發展，大力推廣社團活動，學生社團競賽結果傑出亮眼，國樂團自94年至今20連霸獲得全國音樂比賽高雄市代表權及全國比賽優等佳績，絲竹室內樂團於今年首次闖入全國四強並榮獲特優，HIP HOP社、熱舞社、流行舞蹈社、陶笛社、魔術社、跆拳道社發掘學生各項才能；家長更是與學生共學，「前峰國中家長志工太鼓隊」遠近馳名受到各地方表演邀約不斷，種種佳績皆可展現前峰國中學生活躍創意的一面，本次演出內容精彩可期，歡迎大眾踴躍蒞臨欣賞。', '高雄市政府文化局', '高雄市岡山區009鄰岡山南路42號', '2025-05-23 00:00:00', '2025-05-23 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='前峰國中社團成果展《時光漫溯‧乘峰飛翔》', `description`=' 前峰國中除豐碩的升學成果外，也強調多元學習與適性發展，大力推廣社團活動，學生社團競賽結果傑出亮眼，國樂團自94年至今20連霸獲得全國音樂比賽高雄市代表權及全國比賽優等佳績，絲竹室內樂團於今年首次闖入全國四強並榮獲特優，HIP HOP社、熱舞社、流行舞蹈社、陶笛社、魔術社、跆拳道社發掘學生各項才能；家長更是與學生共學，「前峰國中家長志工太鼓隊」遠近馳名受到各地方表演邀約不斷，種種佳績皆可展現前峰國中學生活躍創意的一面，本次演出內容精彩可期，歡迎大眾踴躍蒞臨欣賞。', `organizer`='高雄市政府文化局', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-05-23 00:00:00', `end_date`='2025-05-23 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e126b3242b74a3aeeb', '心向－宋國仲/陳素貞/劉珮螓 聯展', ' 「心向」75幅作品融入3位藝術家的思想並揉合個人生命歷程，結合具象、抽象、象徵主義、超現實主義與表現主義等特色，將各種技法之藝術語彙轉譯成美麗且深植人心的圖像，使作品更具獨特且多樣性，藝術家更期待以作品與觀看者展開一場心靈上的視覺對話。', '高雄市政府文化局', '高雄市岡山區009鄰岡山南路42號', '2025-05-07 00:00:00', '2025-05-25 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='心向－宋國仲/陳素貞/劉珮螓 聯展', `description`=' 「心向」75幅作品融入3位藝術家的思想並揉合個人生命歷程，結合具象、抽象、象徵主義、超現實主義與表現主義等特色，將各種技法之藝術語彙轉譯成美麗且深植人心的圖像，使作品更具獨特且多樣性，藝術家更期待以作品與觀看者展開一場心靈上的視覺對話。', `organizer`='高雄市政府文化局', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-05-07 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e126b3242b74a3aeec', '迴 家風景 ~ 蔡淑惠創作個展   ', ' 延續2019年首次展覽「家 風景」的精神，藉由風景表達對人、物的眷念及閒暇移居鄉間種種美好，希望作品與自我對話、與觀者敘訴，產生不同情愫，以情動人，讓展覽作品美的畫面去觸動人心。\r\n\r\n\r\n\r\n', '高雄市政府文化局', '高雄市岡山區009鄰岡山南路42號', '2025-05-28 00:00:00', '2025-06-15 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='迴 家風景 ~ 蔡淑惠創作個展   ', `description`=' 延續2019年首次展覽「家 風景」的精神，藉由風景表達對人、物的眷念及閒暇移居鄉間種種美好，希望作品與自我對話、與觀者敘訴，產生不同情愫，以情動人，讓展覽作品美的畫面去觸動人心。\r\n\r\n\r\n\r\n', `organizer`='高雄市政府文化局', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-05-28 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e126b3242b74a3aeed', '永續之藝·創意共鳴聯展 ', ' 由台灣SDGs協會策劃《永續之藝·創意共鳴聯展》，邀集來自不同領域藝術創作者共同參與，展出作品涵蓋繪畫、平面海報、立體創作、工藝設計、花藝及文創商品等，展現藝術與永續概念交織的豐富樣貌。從聯合國永續發展目標（SDGs）出發，藉由多元媒材與創新形式傳遞永續價值。\r\n\r\n\r\n\r\n', '高雄市政府文化局', '高雄市岡山區009鄰岡山南路42號', '2025-05-28 00:00:00', '2025-06-15 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='永續之藝·創意共鳴聯展 ', `description`=' 由台灣SDGs協會策劃《永續之藝·創意共鳴聯展》，邀集來自不同領域藝術創作者共同參與，展出作品涵蓋繪畫、平面海報、立體創作、工藝設計、花藝及文創商品等，展現藝術與永續概念交織的豐富樣貌。從聯合國永續發展目標（SDGs）出發，藉由多元媒材與創新形式傳遞永續價值。\r\n\r\n\r\n\r\n', `organizer`='高雄市政府文化局', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-05-28 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e126b3242b74a3aeee', 'FUN心聽故事(美濃分館114年4月)', '由故事媽媽取材繪本故事來帶領小朋友，從不同故事內容去瞭解各自所含意境及學習其繪本正面所帶來影響，透過老師豐富的肢體動作與帶動唱，透過簡單的律動營造歡樂的故事情境。', '高雄市立圖書館總館', '高雄市美濃區6鄰中正路一段59號', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '高雄市立圖書館美濃分館', 22.9001672, 120.5418427, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽故事(美濃分館114年4月)', `description`='由故事媽媽取材繪本故事來帶領小朋友，從不同故事內容去瞭解各自所含意境及學習其繪本正面所帶來影響，透過老師豐富的肢體動作與帶動唱，透過簡單的律動營造歡樂的故事情境。', `organizer`='高雄市立圖書館總館', `address`='高雄市美濃區6鄰中正路一段59號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄市立圖書館美濃分館', `latitude`=22.9001672, `longitude`=120.5418427, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e526b3242b74a3aeef', '主題書展-「魚你同在 FISH WITH YOU」', '人類與魚的關係很密切，因為魚是我們食物的一部分，還有很多人喜歡釣魚或養魚作為娛樂。而且，魚類生活在海洋和河流中，對維持水中生態系統非常重要，幫助清潔水質和保持食物鏈的平衡。\r\n要深入了解魚類，我們可以學習它們的生活習性、食物和棲息地。科學家會研究不同種類的魚，了解它們怎麼在水中游動，如何尋找食物，還有它們如何與其他生物相處。\r\n海洋保育很重要，因為如果我們不保護海洋，許多魚類和其他海洋生物可能會消失。人類可以做的事情包括減少污染、保護海洋生態區域，還有避免過度捕魚。這些方法有助於讓魚類的家園保持健康，讓我們和魚類能夠長久相處。\r\n保護海洋就是保護我們的未來，讓我們的孩子也能在未來看見美麗的海洋和各種各樣的魚類。', '高雄市立圖書館總館', '高雄市永安區005鄰永華路49號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '高雄市立圖書館永安分館', 22.8159848, 120.2244381, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='主題書展-「魚你同在 FISH WITH YOU」', `description`='人類與魚的關係很密切，因為魚是我們食物的一部分，還有很多人喜歡釣魚或養魚作為娛樂。而且，魚類生活在海洋和河流中，對維持水中生態系統非常重要，幫助清潔水質和保持食物鏈的平衡。\r\n要深入了解魚類，我們可以學習它們的生活習性、食物和棲息地。科學家會研究不同種類的魚，了解它們怎麼在水中游動，如何尋找食物，還有它們如何與其他生物相處。\r\n海洋保育很重要，因為如果我們不保護海洋，許多魚類和其他海洋生物可能會消失。人類可以做的事情包括減少污染、保護海洋生態區域，還有避免過度捕魚。這些方法有助於讓魚類的家園保持健康，讓我們和魚類能夠長久相處。\r\n保護海洋就是保護我們的未來，讓我們的孩子也能在未來看見美麗的海洋和各種各樣的魚類。', `organizer`='高雄市立圖書館總館', `address`='高雄市永安區005鄰永華路49號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市立圖書館永安分館', `latitude`=22.8159848, `longitude`=120.2244381, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e626b3242b74a3aef0', '「書海中的交通奇遇」國際繪本主題書展', '歡迎來到「書海中的交通奇遇」書展！這是充滿驚奇與發現的書展，帶領你穿越各種交通工具的奇妙世界，從歷史的車輪到未來的飛行器，讓書本成為我們通向無限旅程的橋樑。\r\n\r\n展示書單:未來夢想工程 : AI汽車的誕生 : 歡迎光臨汽車夢工廠、忙碌的交通工具、神奇便利的交通工具、各式各樣的火車、酷炫帥氣的車子、機場動起來、台灣鐵道、從前從前.火車來到小島、爸爸的小貨車、電車來囉!…等。\r\n', '高雄市立圖書館總館', '高雄市仁武區5鄰中正路80號', '2025-04-10 00:00:00', '2025-05-16 00:00:00', '高雄市立圖書館仁武分館', 22.7014517, 120.3477392, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「書海中的交通奇遇」國際繪本主題書展', `description`='歡迎來到「書海中的交通奇遇」書展！這是充滿驚奇與發現的書展，帶領你穿越各種交通工具的奇妙世界，從歷史的車輪到未來的飛行器，讓書本成為我們通向無限旅程的橋樑。\r\n\r\n展示書單:未來夢想工程 : AI汽車的誕生 : 歡迎光臨汽車夢工廠、忙碌的交通工具、神奇便利的交通工具、各式各樣的火車、酷炫帥氣的車子、機場動起來、台灣鐵道、從前從前.火車來到小島、爸爸的小貨車、電車來囉!…等。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市仁武區5鄰中正路80號', `start_date`='2025-04-10 00:00:00', `end_date`='2025-05-16 00:00:00', `location`='高雄市立圖書館仁武分館', `latitude`=22.7014517, `longitude`=120.3477392, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e726b3242b74a3aef1', '【新北市立圖書館板橋民生圖書閱覽室】114年4月《閱讀書籤》「樂遊世界」主題書展 ', '【板橋民生圖書閱覽室】114年4月《閱讀書籤》主題書展\r\n書展名稱：樂遊世界主題書展\r\n展出日期：113年4月1日至4月30日\r\n開放時間：週二至週六 8時30分至21時；週日至週一 8時30分至17時\r\n展示地點：新北市板橋區民生路一段30號 / 2樓書展區\r\n主題說明：本次書展展出有關於百年老店深度漫遊，帶你以旅人視角看見跨越世代的軌跡；帶你以文字尋訪全世界老字號，傾聽老店的心路歷程、動人故事；再從一則則故事中，探索老店的經營智慧，走進世代……\r\n備註：書展展示期間，歡迎借閱；114年4月03日及04日為兒童及民族掃墓節，114年4月24日為清館日，不對外開放。', '新北市立圖書館總館', '新北市板橋區民生路一段30號2樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館板橋民生圖書閱覽室', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館板橋民生圖書閱覽室】114年4月《閱讀書籤》「樂遊世界」主題書展 ', `description`='【板橋民生圖書閱覽室】114年4月《閱讀書籤》主題書展\r\n書展名稱：樂遊世界主題書展\r\n展出日期：113年4月1日至4月30日\r\n開放時間：週二至週六 8時30分至21時；週日至週一 8時30分至17時\r\n展示地點：新北市板橋區民生路一段30號 / 2樓書展區\r\n主題說明：本次書展展出有關於百年老店深度漫遊，帶你以旅人視角看見跨越世代的軌跡；帶你以文字尋訪全世界老字號，傾聽老店的心路歷程、動人故事；再從一則則故事中，探索老店的經營智慧，走進世代……\r\n備註：書展展示期間，歡迎借閱；114年4月03日及04日為兒童及民族掃墓節，114年4月24日為清館日，不對外開放。', `organizer`='新北市立圖書館總館', `address`='新北市板橋區民生路一段30號2樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館板橋民生圖書閱覽室', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e726b3242b74a3aef3', '行腳走讀識內惟：北邊路線', '行腳走讀識內惟：北邊路線\r\n\r\n延續113年度「內惟踏查走讀暨導覽人才培力計畫」，再度邀請有興趣的社會大眾走入內惟社區、體驗人文，以最直接的身體感官感受，臨場體驗內惟人文風光景緻背後所蘊含的故事，期成為未來導覽種子志工們帶領內惟走讀與地方紋理小旅行的能量。 \r\n\r\n●活動時間：114年4月26日（六）下午14:00-17:00 \r\n​●報到時間：活動前15分鐘開放報到，領取導覽設備及發票\r\n●集合地點：內惟鎮安宮  (鼓山區九如四路1450號)\r\n●預計走訪：鎮安宮、李氏祖厝、古井群、李榮洋樓、自強新村等。', '高雄市立美術館', '高雄市鼓山區', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '鼓山區（高雄市）=', 22.65019525, 120.274163, '--+350', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='行腳走讀識內惟：北邊路線', `description`='行腳走讀識內惟：北邊路線\r\n\r\n延續113年度「內惟踏查走讀暨導覽人才培力計畫」，再度邀請有興趣的社會大眾走入內惟社區、體驗人文，以最直接的身體感官感受，臨場體驗內惟人文風光景緻背後所蘊含的故事，期成為未來導覽種子志工們帶領內惟走讀與地方紋理小旅行的能量。 \r\n\r\n●活動時間：114年4月26日（六）下午14:00-17:00 \r\n​●報到時間：活動前15分鐘開放報到，領取導覽設備及發票\r\n●集合地點：內惟鎮安宮  (鼓山區九如四路1450號)\r\n●預計走訪：鎮安宮、李氏祖厝、古井群、李榮洋樓、自強新村等。', `organizer`='高雄市立美術館', `address`='高雄市鼓山區', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='鼓山區（高雄市）=', `latitude`=22.65019525, `longitude`=120.274163, `ticket_price`='--+350', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e826b3242b74a3aef8', '日本飛行船劇團《小飛俠彼得潘》', '如果到夢幻島上可以永遠只當個孩子，你會選擇留在那裡嗎？\r\n\r\n所有的孩子都知道一個叫做「夢幻島」的地方（Neverland），大家可以在睡夢中到那兒玩耍。島上有一個叫做彼得潘的男孩，他不但會飛，而且永遠不會長大。他是孩子們心目中的英雄，也是夢幻島上迷途的孩子們最可靠的首領。為了找尋新的故事，他和小精靈來到另一個世界，卻不小心被溫蒂及她的兩個弟弟發現……。\r\n\r\n \r\n\r\n♪劇中有愛吃醋的小精靈、勇敢的泰雅莉莉公主，還有凶惡的虎克船長以及他的海盜們！將友誼與信念集結成一部有趣又驚奇的冒險故事。\r\n\r\n 獻給每個人心中的孩子\r\n\r\n所有的孩子都會長大，除了這一個詹姆斯•馬修•貝瑞(James Matthew Barrie)\r\n\r\n彼得潘的美麗新世界是由「勇敢、堅貞、不畏惡勢力」的信念組成，期盼藉由演出喚醒沉睡在大人們心靈深處的那一份真，亦希望將這份信念散播到世界的每一個角落，讓我們的孩子能永遠保有它。 ', '童歡藝術有限公司', '高雄市苓雅區001鄰五福一路67號', '2025-04-18 00:00:00', '2025-04-19 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '--+400;--+600;--+800;--+1000;--+1200;--+1500', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='日本飛行船劇團《小飛俠彼得潘》', `description`='如果到夢幻島上可以永遠只當個孩子，你會選擇留在那裡嗎？\r\n\r\n所有的孩子都知道一個叫做「夢幻島」的地方（Neverland），大家可以在睡夢中到那兒玩耍。島上有一個叫做彼得潘的男孩，他不但會飛，而且永遠不會長大。他是孩子們心目中的英雄，也是夢幻島上迷途的孩子們最可靠的首領。為了找尋新的故事，他和小精靈來到另一個世界，卻不小心被溫蒂及她的兩個弟弟發現……。\r\n\r\n \r\n\r\n♪劇中有愛吃醋的小精靈、勇敢的泰雅莉莉公主，還有凶惡的虎克船長以及他的海盜們！將友誼與信念集結成一部有趣又驚奇的冒險故事。\r\n\r\n 獻給每個人心中的孩子\r\n\r\n所有的孩子都會長大，除了這一個詹姆斯•馬修•貝瑞(James Matthew Barrie)\r\n\r\n彼得潘的美麗新世界是由「勇敢、堅貞、不畏惡勢力」的信念組成，期盼藉由演出喚醒沉睡在大人們心靈深處的那一份真，亦希望將這份信念散播到世界的每一個角落，讓我們的孩子能永遠保有它。 ', `organizer`='童歡藝術有限公司', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-04-18 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='--+400;--+600;--+800;--+1000;--+1200;--+1500', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e826b3242b74a3aefa', '琴音繞樑·音符飛揚', '演出者團隊\r\n\r\n高雄市三民區博愛國小弦樂團、高雄市鹽埕區光榮國小弦樂團、高雄市楠梓區右昌國小弦樂團、高雄市楠梓區援中國小弦樂團\r\n\r\n \r\n\r\n演出曲目：\r\n\r\n【右昌國小弦樂團】\r\n\r\n王老先生有塊地、小蜜蜂、驚愕交響曲、神隱少女\r\n\r\n【光榮國小弦樂團】\r\n\r\n十個印地安人、奇異恩典、康康舞曲、學貓叫\r\n\r\n【援中國小弦樂團】\r\n\r\n春神來了、生日快樂歌、You are my sunshine、阿依達\r\n\r\n【博愛國小弦樂團】\r\n\r\n兩隻老虎、火車快飛、小步舞曲、火雞\r\n\r\n丹麥王子、神鬼奇航、APT、輕騎兵序曲\r\n\r\n大合奏：感恩的心', '新希望樂團', '高雄市苓雅區001鄰五福一路67號', '2025-04-25 00:00:00', '2025-04-25 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '--+200', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='琴音繞樑·音符飛揚', `description`='演出者團隊\r\n\r\n高雄市三民區博愛國小弦樂團、高雄市鹽埕區光榮國小弦樂團、高雄市楠梓區右昌國小弦樂團、高雄市楠梓區援中國小弦樂團\r\n\r\n \r\n\r\n演出曲目：\r\n\r\n【右昌國小弦樂團】\r\n\r\n王老先生有塊地、小蜜蜂、驚愕交響曲、神隱少女\r\n\r\n【光榮國小弦樂團】\r\n\r\n十個印地安人、奇異恩典、康康舞曲、學貓叫\r\n\r\n【援中國小弦樂團】\r\n\r\n春神來了、生日快樂歌、You are my sunshine、阿依達\r\n\r\n【博愛國小弦樂團】\r\n\r\n兩隻老虎、火車快飛、小步舞曲、火雞\r\n\r\n丹麥王子、神鬼奇航、APT、輕騎兵序曲\r\n\r\n大合奏：感恩的心', `organizer`='新希望樂團', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-04-25 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='--+200', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e826b3242b74a3aefc', 'A-team 出任務：重啟', 'A-Team薩克斯風合奏團\r\n\r\n   “A”是為英文字母的第一順位，撲克牌上的A代表著ACE：最大的王牌，在舞台上，我們致力成為優秀的演奏團體，成為”A” Team；而平常的練習帶給我們無價的收穫，是讓從四面八方、各行各業、各種身分的成員有了無可取代的默契，所以我們成為獨一無二的「一個團隊」a "team"。\r\n\r\n此場音樂會為A-Team 薩克斯風合奏團經過了五年，團內許多團員經過了國外的洗禮陸續地從歐洲各地歸國並以「重啟」命名為本次音樂會之名稱，象徵本樂團正式回歸並期許能夠持續舉辦各式各樣音樂會已檢視自身成果。', 'A-Team薩克斯風合奏團', '高雄市苓雅區001鄰五福一路67號', '2025-04-27 00:00:00', '2025-04-27 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '--+100', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='A-team 出任務：重啟', `description`='A-Team薩克斯風合奏團\r\n\r\n   “A”是為英文字母的第一順位，撲克牌上的A代表著ACE：最大的王牌，在舞台上，我們致力成為優秀的演奏團體，成為”A” Team；而平常的練習帶給我們無價的收穫，是讓從四面八方、各行各業、各種身分的成員有了無可取代的默契，所以我們成為獨一無二的「一個團隊」a "team"。\r\n\r\n此場音樂會為A-Team 薩克斯風合奏團經過了五年，團內許多團員經過了國外的洗禮陸續地從歐洲各地歸國並以「重啟」命名為本次音樂會之名稱，象徵本樂團正式回歸並期許能夠持續舉辦各式各樣音樂會已檢視自身成果。', `organizer`='A-Team薩克斯風合奏團', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='--+100', `source_url`='http://www.ticket.com.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e826b3242b74a3aefd', '密Si桃Do~陽明國小第21屆管樂班畢業音樂會', '陽明國小管樂團成立於1996年，希望透過樂器合奏的經驗，學習「管理自我、樂音悠揚、團隊合作」的精神，累積豐富的舞台經驗，增廣孩子的音樂視野及美學涵養，促進音樂教育的多元化。本次音樂會將帶來協奏曲、重奏曲及樂團合奏，以不同的組合帶給觀眾豐富的音樂饗宴。', '高雄市三民區陽明國民小學', '高雄市苓雅區001鄰五福一路67號', '2025-04-28 00:00:00', '2025-04-28 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='密Si桃Do~陽明國小第21屆管樂班畢業音樂會', `description`='陽明國小管樂團成立於1996年，希望透過樂器合奏的經驗，學習「管理自我、樂音悠揚、團隊合作」的精神，累積豐富的舞台經驗，增廣孩子的音樂視野及美學涵養，促進音樂教育的多元化。本次音樂會將帶來協奏曲、重奏曲及樂團合奏，以不同的組合帶給觀眾豐富的音樂饗宴。', `organizer`='高雄市三民區陽明國民小學', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-04-28 00:00:00', `end_date`='2025-04-28 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f441e826b3242b74a3aefe', '當代作曲家之作品發表與對談XX', '《當代作曲家之作品發表與對談》系列是由國立中山大學音樂學系作曲組教師們於2005年發起，每年舉辦，是兼具學術性與學術研討的音樂創作發表會。今年2025年將邁入第二十屆，我們以「共生」為議題，從不同視角來探討這個處處存在的現象。\r\n\r\n\r\n節目分為音樂會和對談兩部分，先是以音樂會形式發表作曲家李思嫺《移動島嶼I》、陳以軒《它與空想》和應廣儀《共生緣》三首作品，每首樂曲演奏結束後，由主持人國立中山大學哲學研究所楊婉儀教授邀請對應的作曲家分享關於樂曲創作設計的點滴。作品發表演出後，除了主持人和作曲家之外，還邀請兩位與談人國立中山大學中文系杜佳倫主任和業界經驗豐富的城市設計師陳敬堯先生，從不同的面向對主題及樂曲詮釋進行討論，並開放在場觀眾提問，直接交流，一起探討「共生」這個議題。', '國立中山大學', '高雄市苓雅區001鄰五福一路67號', '2025-04-29 00:00:00', '2025-04-29 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='當代作曲家之作品發表與對談XX', `description`='《當代作曲家之作品發表與對談》系列是由國立中山大學音樂學系作曲組教師們於2005年發起，每年舉辦，是兼具學術性與學術研討的音樂創作發表會。今年2025年將邁入第二十屆，我們以「共生」為議題，從不同視角來探討這個處處存在的現象。\r\n\r\n\r\n節目分為音樂會和對談兩部分，先是以音樂會形式發表作曲家李思嫺《移動島嶼I》、陳以軒《它與空想》和應廣儀《共生緣》三首作品，每首樂曲演奏結束後，由主持人國立中山大學哲學研究所楊婉儀教授邀請對應的作曲家分享關於樂曲創作設計的點滴。作品發表演出後，除了主持人和作曲家之外，還邀請兩位與談人國立中山大學中文系杜佳倫主任和業界經驗豐富的城市設計師陳敬堯先生，從不同的面向對主題及樂曲詮釋進行討論，並開放在場觀眾提問，直接交流，一起探討「共生」這個議題。', `organizer`='國立中山大學', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-04-29 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f48c2307f3c8b8c6b19b73', '【日午音樂會176】原野之聲～笛樂即興音樂會', '【日午音樂會176】原野之聲～笛樂即興音樂會\r\n\r\n『原野之聲』是即興笛樂家林小楓發起的一個演出計畫，以多種亞太及世界笛樂為核心創作，融合台灣鼻笛、笛、簫、日本能管、篠笛、斯洛伐克泛音笛、土耳其蘆笛、蒙古口簧琴、馬頭琴、以及葫蘆絲、手鼓...等樂器進行跨界演出，創造一個虛擬民族的日常，以自然、草原、大地為創作題材，透過限定的框架來即興譜曲，將帶領觀眾進入一場遼闊的、富有想像的原始世界。\r\n\r\n■演出： 笛樂／林小楓；呼麥、馬頭琴／烏尼德；世界擊樂／張幼欣；原民歌手／紫布爾正若；鋼琴／李世揚\r\n\r\n■時間：2025年6月15 日（日）14:30（遲到或中途離場的聽眾至中場休息方可入場，建議提早抵達）\r\n\r\n■地點：林建生紀念圖書館演奏廳（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額200位，七歲以上，免費報名入場。\r\n\r\n#恕無現場後補\r\n\r\n■報名方式： 6月5日（四）10:00 起，網路報名：  https://www.accupass.com/go/1140615\r\n\r\n#80歲以上長者可電話名：02-22855188\r\n\r\n■演出曲目：\r\n序・晨曦｜笛、人聲、口簧琴、擊樂、馬頭琴\r\n壹・山靈｜ 鼻笛、口簧琴、呼麥 、原住民古調\r\n貳・秋風引 ｜簫與鋼琴\r\n參・山怪 ｜ 日本能管、篠笛、手鼓\r\n肆・躍動南洋｜ 葫蘆絲、手鼓、鋼琴\r\n伍・塔克西姆幻舞｜土耳其蘆笛（Sipsi）、手鼓\r\n陸・大地的歌｜笛、鋼琴、打擊、人聲\r\n柒・過山嶺 - 取水｜ 斯洛伐克泛音笛、打擊樂、人聲、呼麥、馬頭琴、鋼琴 \r\n捌・風與牧歌｜笛、馬頭琴、呼麥、人聲、鋼琴、打擊樂\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★歡迎加入Line 好友： https://bit.ly/2KFVgg2\r\n★網址： https://www.ljsedu.org.tw\r\n', '財團法人紀念林建生教育基金會', '新北市蘆洲區三民路178號', '2025-06-15 00:00:00', '2025-06-15 00:00:00', '林建生紀念圖書館', 25.08927173, 121.4712461, '七歲以上，免費報名入場', 'https://www.accupass.com/go/1140615', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【日午音樂會176】原野之聲～笛樂即興音樂會', `description`='【日午音樂會176】原野之聲～笛樂即興音樂會\r\n\r\n『原野之聲』是即興笛樂家林小楓發起的一個演出計畫，以多種亞太及世界笛樂為核心創作，融合台灣鼻笛、笛、簫、日本能管、篠笛、斯洛伐克泛音笛、土耳其蘆笛、蒙古口簧琴、馬頭琴、以及葫蘆絲、手鼓...等樂器進行跨界演出，創造一個虛擬民族的日常，以自然、草原、大地為創作題材，透過限定的框架來即興譜曲，將帶領觀眾進入一場遼闊的、富有想像的原始世界。\r\n\r\n■演出： 笛樂／林小楓；呼麥、馬頭琴／烏尼德；世界擊樂／張幼欣；原民歌手／紫布爾正若；鋼琴／李世揚\r\n\r\n■時間：2025年6月15 日（日）14:30（遲到或中途離場的聽眾至中場休息方可入場，建議提早抵達）\r\n\r\n■地點：林建生紀念圖書館演奏廳（新北市蘆洲區三民路178號，近捷運蘆洲線三民高中站）\r\n\r\n■入場方式：限額200位，七歲以上，免費報名入場。\r\n\r\n#恕無現場後補\r\n\r\n■報名方式： 6月5日（四）10:00 起，網路報名：  https://www.accupass.com/go/1140615\r\n\r\n#80歲以上長者可電話名：02-22855188\r\n\r\n■演出曲目：\r\n序・晨曦｜笛、人聲、口簧琴、擊樂、馬頭琴\r\n壹・山靈｜ 鼻笛、口簧琴、呼麥 、原住民古調\r\n貳・秋風引 ｜簫與鋼琴\r\n參・山怪 ｜ 日本能管、篠笛、手鼓\r\n肆・躍動南洋｜ 葫蘆絲、手鼓、鋼琴\r\n伍・塔克西姆幻舞｜土耳其蘆笛（Sipsi）、手鼓\r\n陸・大地的歌｜笛、鋼琴、打擊、人聲\r\n柒・過山嶺 - 取水｜ 斯洛伐克泛音笛、打擊樂、人聲、呼麥、馬頭琴、鋼琴 \r\n捌・風與牧歌｜笛、馬頭琴、呼麥、人聲、鋼琴、打擊樂\r\n\r\n★主辦：財團法人紀念林建生教育基金會\r\n★洽詢：02-2285-5157、2285-5188\r\n★歡迎加入Line 好友： https://bit.ly/2KFVgg2\r\n★網址： https://www.ljsedu.org.tw\r\n', `organizer`='財團法人紀念林建生教育基金會', `address`='新北市蘆洲區三民路178號', `start_date`='2025-06-15 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='林建生紀念圖書館', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='七歲以上，免費報名入場', `source_url`='https://www.accupass.com/go/1140615', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f4bf048f15101f86006dfa', 'in臺南．無影藏－臺南市文化資產影像競賽', '1、 主旨\r\n\r\n「in臺南‧無影藏─2025臺南市文化資產影像競賽」廣召以影像保存臺南文化資產特色與傳承文化有興趣和熱忱的民眾踴躍報名，不論是已登錄的文化資產，亦或是生活中潛在的文化資產，透過影像徵件活動不僅能為在地文化留下更多動人的影像，更能藉以對全民推廣文化資產保護之重要性，同時建立臺南市文化資產的資源多樣性、文化故事性與城市歷史永續性。\r\n\r\n2、徵件主題\r\n\r\n臺南市已登錄及生活中潛在的文化資產(包含有形文化資產：古蹟、歷史建築、紀念建築群、考古遺址、史蹟、文化景觀、古物、自然地景/自然紀念物；無形文化資產：傳統表演藝術、傳統工藝、口述傳統、民俗、傳統知識與實踐)為創作元素與概念發想，透過創造性、故事性與原創性的方式拍攝出影像作品。\r\n※臺南市文化資產定義及項目可參閱《文化資產保存法》與「國家文化資產網」https://nchdb.boch.gov.tw/\r\n\r\n3、報名資格\r\n \r\n熱愛影像創作、拍攝製作臺南文化資產相關之影像作品，不限影片類型、長度30分鐘以內，個人或團體國內外人士皆可報名。\r\n\r\n4、報名方式\r\n \r\n本活動採電子報名，請於2025年6月30日下午17:00前完成線上報名及上傳參賽影片(已上中文字幕1080P以上MP4檔)及相關資料（劇照3張、導演照1張)至主辦單位提供的雲端網址，如有任一項未於期限內完成，視同未報名。\r\n\r\n5、競賽獎項\r\n\r\n入圍作品：於頒獎暨巡迴播映記者會分別頒發入圍證書。\r\n得獎作品：於頒獎暨巡迴播映記者會頒布獎次、獎金和獎座。\r\n\r\n首獎：1名，獎金新臺幣 150,000元，獎座1座。\r\n二獎：1名，獎金新臺幣 100,000元，獎座1座。\r\n三獎：1名，獎金新臺幣 80,000元，獎座1座。\r\n優選：3名，獎金新臺幣 30,000元，獎狀1只。\r\n佳作：3名，獎金新臺幣 10,000元，獎狀1只。\r\n※頒獎暨巡迴播映記者會：場地、時間由主辦單位另行公告及通知。', '臺南市文化資產管理處', '臺南市全區', '2025-04-02 00:00:00', '2025-06-30 00:00:00', 'in臺南．無影藏－臺南市文化資產影像競賽', '無資料', '無資料', '無資料', 'https://2025intainan.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='in臺南．無影藏－臺南市文化資產影像競賽', `description`='1、 主旨\r\n\r\n「in臺南‧無影藏─2025臺南市文化資產影像競賽」廣召以影像保存臺南文化資產特色與傳承文化有興趣和熱忱的民眾踴躍報名，不論是已登錄的文化資產，亦或是生活中潛在的文化資產，透過影像徵件活動不僅能為在地文化留下更多動人的影像，更能藉以對全民推廣文化資產保護之重要性，同時建立臺南市文化資產的資源多樣性、文化故事性與城市歷史永續性。\r\n\r\n2、徵件主題\r\n\r\n臺南市已登錄及生活中潛在的文化資產(包含有形文化資產：古蹟、歷史建築、紀念建築群、考古遺址、史蹟、文化景觀、古物、自然地景/自然紀念物；無形文化資產：傳統表演藝術、傳統工藝、口述傳統、民俗、傳統知識與實踐)為創作元素與概念發想，透過創造性、故事性與原創性的方式拍攝出影像作品。\r\n※臺南市文化資產定義及項目可參閱《文化資產保存法》與「國家文化資產網」https://nchdb.boch.gov.tw/\r\n\r\n3、報名資格\r\n \r\n熱愛影像創作、拍攝製作臺南文化資產相關之影像作品，不限影片類型、長度30分鐘以內，個人或團體國內外人士皆可報名。\r\n\r\n4、報名方式\r\n \r\n本活動採電子報名，請於2025年6月30日下午17:00前完成線上報名及上傳參賽影片(已上中文字幕1080P以上MP4檔)及相關資料（劇照3張、導演照1張)至主辦單位提供的雲端網址，如有任一項未於期限內完成，視同未報名。\r\n\r\n5、競賽獎項\r\n\r\n入圍作品：於頒獎暨巡迴播映記者會分別頒發入圍證書。\r\n得獎作品：於頒獎暨巡迴播映記者會頒布獎次、獎金和獎座。\r\n\r\n首獎：1名，獎金新臺幣 150,000元，獎座1座。\r\n二獎：1名，獎金新臺幣 100,000元，獎座1座。\r\n三獎：1名，獎金新臺幣 80,000元，獎座1座。\r\n優選：3名，獎金新臺幣 30,000元，獎狀1只。\r\n佳作：3名，獎金新臺幣 10,000元，獎狀1只。\r\n※頒獎暨巡迴播映記者會：場地、時間由主辦單位另行公告及通知。', `organizer`='臺南市文化資產管理處', `address`='臺南市全區', `start_date`='2025-04-02 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='in臺南．無影藏－臺南市文化資產影像競賽', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://2025intainan.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f4dc378f15101f86006dfb', '舒曼：三首弦樂四重奏', '舒曼的三首弦樂四重奏是他所有出版的室內樂作品中唯一一套沒有讓鋼琴參與的作品，也是作曲家「室內樂之年（1842）」的起點。這三首作品簡潔內斂，卻又充滿著舒曼獨特的浪漫與詩意。曾有音樂學者建議應將這三首作品一併欣賞，方能捕捉舒曼創作風格中多樣化的完整性。讓我們跟隨台灣首屈一指的首席四重奏，透過他們精湛純熟的琴藝，展開一場令人難忘的舒曼弦樂四重奏之旅。\r\n\r\n2025/06/29(日)14:30 國家兩廳院 演奏廳\r\n\r\n演出者：\r\nInfinite首席四重奏\r\n李宜錦／小提琴  I-Ching Li／Violin\r\n鄧皓敦／小提琴  Hao-Tun Teng／Violin\r\n陳猶白／中提琴  Jubel Chen／Viola\r\n歐陽伶宜／大提琴  Ling-Yi Ou Yang／Cello\r\n\r\n演出曲目：\r\nA小調第一號弦樂四重奏，作品四十一之一\r\nF大調第二號弦樂四重奏，作品四十一之二\r\nA大調第三號弦樂四重奏，作品四十一之三\r\nString Quartet in A Minor, Op. 41 No. 1\r\nString Quartet in F Major, Op. 41 No. 2\r\nString Quartet in A Major, Op. 41 No. 3\r\n\r\nOPENTIX 售票系統 : https://www.opentix.life/event/1897203228864602112\r\n\r\n【優惠折扣】\r\n◆套票 _ 同時購買兩場8折、三場6折\r\n◆三張以上7折\r\n◆兩廳院會員9折優惠\r\n\r\n#文化幣\r\n#套票', '財團法人台北獨奏家室內樂基金會', '臺北市中正區中山南路21之1號', '2025-06-29 00:00:00', '2025-06-29 00:00:00', '國家兩廳院 演奏廳', 25.03240487, 121.5198839, 'NT$500、800、1000 (兩廳院 Opentix) ', 'https://www.opentix.life/event/1897203228864602112', '[]') ON DUPLICATE KEY UPDATE `activity_name`='舒曼：三首弦樂四重奏', `description`='舒曼的三首弦樂四重奏是他所有出版的室內樂作品中唯一一套沒有讓鋼琴參與的作品，也是作曲家「室內樂之年（1842）」的起點。這三首作品簡潔內斂，卻又充滿著舒曼獨特的浪漫與詩意。曾有音樂學者建議應將這三首作品一併欣賞，方能捕捉舒曼創作風格中多樣化的完整性。讓我們跟隨台灣首屈一指的首席四重奏，透過他們精湛純熟的琴藝，展開一場令人難忘的舒曼弦樂四重奏之旅。\r\n\r\n2025/06/29(日)14:30 國家兩廳院 演奏廳\r\n\r\n演出者：\r\nInfinite首席四重奏\r\n李宜錦／小提琴  I-Ching Li／Violin\r\n鄧皓敦／小提琴  Hao-Tun Teng／Violin\r\n陳猶白／中提琴  Jubel Chen／Viola\r\n歐陽伶宜／大提琴  Ling-Yi Ou Yang／Cello\r\n\r\n演出曲目：\r\nA小調第一號弦樂四重奏，作品四十一之一\r\nF大調第二號弦樂四重奏，作品四十一之二\r\nA大調第三號弦樂四重奏，作品四十一之三\r\nString Quartet in A Minor, Op. 41 No. 1\r\nString Quartet in F Major, Op. 41 No. 2\r\nString Quartet in A Major, Op. 41 No. 3\r\n\r\nOPENTIX 售票系統 : https://www.opentix.life/event/1897203228864602112\r\n\r\n【優惠折扣】\r\n◆套票 _ 同時購買兩場8折、三場6折\r\n◆三張以上7折\r\n◆兩廳院會員9折優惠\r\n\r\n#文化幣\r\n#套票', 