INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2b826b3242b74a3af28', '展覽:竹師宇峰班聯展', '  本次聯展是由3位來自新竹師院美教系畢業32個寒暑的藝術家黃耿垣、曾繁琦及陳榮輝創作作品。\r\n  黃耿垣獨創鮮明對比的拼貼式視角畫法，讓畫作散發活力；曾繁琦熱愛以水墨畫的形式展現自然景觀與靜物的細膩描繪；陳榮輝則專精於版畫和水彩畫。3位各自展現出不同的藝術風格，歡迎您一同來品味美的事物。', '臺南市政府財政稅務局', '臺南市中西區', '2025-04-01 00:00:00', '2025-06-30 00:00:00', '中西區（臺南市）=', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='展覽:竹師宇峰班聯展', `description`='  本次聯展是由3位來自新竹師院美教系畢業32個寒暑的藝術家黃耿垣、曾繁琦及陳榮輝創作作品。\r\n  黃耿垣獨創鮮明對比的拼貼式視角畫法，讓畫作散發活力；曾繁琦熱愛以水墨畫的形式展現自然景觀與靜物的細膩描繪；陳榮輝則專精於版畫和水彩畫。3位各自展現出不同的藝術風格，歡迎您一同來品味美的事物。', `organizer`='臺南市政府財政稅務局', `address`='臺南市中西區', `start_date`='2025-04-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='中西區（臺南市）=', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2b826b3242b74a3af29', '114年笨港社區傳統二胡、客家歌謠暨舞蹈研習班活動 (3班)', '二胡/傳統客家歌謠/土風舞蹈及民俗舞蹈研習', '桃園市新屋區笨港社區發展協會', '桃園市新屋區', '2025-04-12 00:00:00', '2025-09-13 00:00:00', '新屋區（桃園市）=', 24.97280352, 121.067758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年笨港社區傳統二胡、客家歌謠暨舞蹈研習班活動 (3班)', `description`='二胡/傳統客家歌謠/土風舞蹈及民俗舞蹈研習', `organizer`='桃園市新屋區笨港社區發展協會', `address`='桃園市新屋區', `start_date`='2025-04-12 00:00:00', `end_date`='2025-09-13 00:00:00', `location`='新屋區（桃園市）=', `latitude`=24.97280352, `longitude`=121.067758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bc26b3242b74a3af2d', '平埔族語言復振-大內區頭社聚落西拉雅語生活會話班', '西拉雅語是臺灣平埔族西拉雅族的語言，屬於南島語系馬來-波利尼西亞語族。西拉雅語曾是西拉雅族的主要溝通語言，並在17世紀荷蘭統治臺灣時，被荷蘭人以羅馬字母記錄，用於傳教與行政事務。然而，由於歷史上的漢化與社會變遷，西拉雅語逐漸消失，成為瀕危語言，故協會積極辦理相關語言復振計畫，開辦生活會話班，期能強化社區對西拉雅語言的保存及續延功能，提供更多元的族語學習管道。', '臺南市頭社西拉雅文化發展協會', '臺南市大內區', '2025-04-01 00:00:00', '2025-10-28 00:00:00', '大內區（臺南市）=', 23.14482152, 120.3988147, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='平埔族語言復振-大內區頭社聚落西拉雅語生活會話班', `description`='西拉雅語是臺灣平埔族西拉雅族的語言，屬於南島語系馬來-波利尼西亞語族。西拉雅語曾是西拉雅族的主要溝通語言，並在17世紀荷蘭統治臺灣時，被荷蘭人以羅馬字母記錄，用於傳教與行政事務。然而，由於歷史上的漢化與社會變遷，西拉雅語逐漸消失，成為瀕危語言，故協會積極辦理相關語言復振計畫，開辦生活會話班，期能強化社區對西拉雅語言的保存及續延功能，提供更多元的族語學習管道。', `organizer`='臺南市頭社西拉雅文化發展協會', `address`='臺南市大內區', `start_date`='2025-04-01 00:00:00', `end_date`='2025-10-28 00:00:00', `location`='大內區（臺南市）=', `latitude`=23.14482152, `longitude`=120.3988147, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bc26b3242b74a3af30', '原民實用功能包設計製作班', '透過原住民族部落大學課程內容達成，認識原住民族文化、織品、工業設計、打版、剪裁、整燙、縫紉技藝、訂價策略、拍照修圖、網路上架銷售(FB,暇皮)、市集攤位陳列技巧、聯合行銷策略等學習完成。傳統文化規範修養提升、傳承文化延續，啟發觸動對自己文化熱情，融入社會家庭生活文化永續經營，傳統文化與現代生活實用結合，並量產發揚光大，促進國家經濟發展。\r\n\r\n', '桃園市政府原住民族行政局', '桃園市中壢區', '2025-03-01 00:00:00', '2025-05-04 00:00:00', '中壢區（桃園市）=', 24.97993803, 121.2147243, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='原民實用功能包設計製作班', `description`='透過原住民族部落大學課程內容達成，認識原住民族文化、織品、工業設計、打版、剪裁、整燙、縫紉技藝、訂價策略、拍照修圖、網路上架銷售(FB,暇皮)、市集攤位陳列技巧、聯合行銷策略等學習完成。傳統文化規範修養提升、傳承文化延續，啟發觸動對自己文化熱情，融入社會家庭生活文化永續經營，傳統文化與現代生活實用結合，並量產發揚光大，促進國家經濟發展。\r\n\r\n', `organizer`='桃園市政府原住民族行政局', `address`='桃園市中壢區', `start_date`='2025-03-01 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='中壢區（桃園市）=', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bc26b3242b74a3af31', '2025廳院選《少年Pi的奇幻漂流》', '🏆  李安奧斯卡獲獎電影同名之作，首度引進亞洲\r\n🏆  全球劇場神話，獲奧立佛獎及東尼獎八項大獎\r\n🏆  極致細膩巨型動物戲偶，如夢似幻視覺效果，宛如身歷其境\r\n\r\n改編自全球熱銷1400萬冊小說《少年Pi的奇幻漂流》。2012年李安導演改編為電影，並獲得奧斯卡金像獎最佳導演。劇場版作品由編劇羅莉塔．查克拉芭蒂（Lolita Chakrabarti）操刀，今年首度登上亞洲舞台，以極致細膩的巨型動物戲偶及如夢似幻的視覺效果，橫掃美國東尼獎與英國奧立佛獎共八項大獎，今年7月於臺北國家戲劇院磅礡登場！\r\n\r\n延續原著核心精神，故事講述少年派．莫里托．帕特爾（Piscine Molitor Patel）在一次船難中失去家人，獨自漂流於浩瀚大海的故事。他唯一的同伴是一隻名叫「理查．帕克」的孟加拉虎。在長達227天的孤獨求生旅途中，少年Pi與猛虎在微妙的平衡中共存。舞台劇透過栩栩如生的巨型動物戲偶與奇幻的視覺特效，帶領觀眾如臨其境，感受少年Pi與理查．帕克的驚險旅程，並在充滿未知與希望的藍色汪洋中，探索信仰與真相的深層意義。\r\n\r\n展演者︰原著作家｜楊．馬泰爾/加拿大 編劇｜羅莉塔．查克拉芭蒂/英國, 導演｜馬克斯．韋柏斯特/英國, 場景與服裝設計｜提姆．哈特利/英國, 偶戲動作指導｜芬恩．考德威爾/英國, 木偶設計｜尼克．巴恩斯/英國, 芬恩．考德威爾/英國, 影像設計｜安德列．古爾丁/英國, 燈光設計｜提姆．盧特金/英國, 音效設計｜卡洛琳．唐寧/英國, 作曲家｜安德魯．T．麥凱/英國\r\n\r\n', '國家表演藝術中心國家兩廳院', '臺北市中正區中山南路21之1號', '2025-07-17 00:00:00', '2025-07-27 00:00:00', '國家兩廳院', 25.03240487, 121.5198839, '/+800;/+1200;/+1800;/+2800;/+3800;/+4800;/+5800;/+6600', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025廳院選《少年Pi的奇幻漂流》', `description`='🏆  李安奧斯卡獲獎電影同名之作，首度引進亞洲\r\n🏆  全球劇場神話，獲奧立佛獎及東尼獎八項大獎\r\n🏆  極致細膩巨型動物戲偶，如夢似幻視覺效果，宛如身歷其境\r\n\r\n改編自全球熱銷1400萬冊小說《少年Pi的奇幻漂流》。2012年李安導演改編為電影，並獲得奧斯卡金像獎最佳導演。劇場版作品由編劇羅莉塔．查克拉芭蒂（Lolita Chakrabarti）操刀，今年首度登上亞洲舞台，以極致細膩的巨型動物戲偶及如夢似幻的視覺效果，橫掃美國東尼獎與英國奧立佛獎共八項大獎，今年7月於臺北國家戲劇院磅礡登場！\r\n\r\n延續原著核心精神，故事講述少年派．莫里托．帕特爾（Piscine Molitor Patel）在一次船難中失去家人，獨自漂流於浩瀚大海的故事。他唯一的同伴是一隻名叫「理查．帕克」的孟加拉虎。在長達227天的孤獨求生旅途中，少年Pi與猛虎在微妙的平衡中共存。舞台劇透過栩栩如生的巨型動物戲偶與奇幻的視覺特效，帶領觀眾如臨其境，感受少年Pi與理查．帕克的驚險旅程，並在充滿未知與希望的藍色汪洋中，探索信仰與真相的深層意義。\r\n\r\n展演者︰原著作家｜楊．馬泰爾/加拿大 編劇｜羅莉塔．查克拉芭蒂/英國, 導演｜馬克斯．韋柏斯特/英國, 場景與服裝設計｜提姆．哈特利/英國, 偶戲動作指導｜芬恩．考德威爾/英國, 木偶設計｜尼克．巴恩斯/英國, 芬恩．考德威爾/英國, 影像設計｜安德列．古爾丁/英國, 燈光設計｜提姆．盧特金/英國, 音效設計｜卡洛琳．唐寧/英國, 作曲家｜安德魯．T．麥凱/英國\r\n\r\n', `organizer`='國家表演藝術中心國家兩廳院', `address`='臺北市中正區中山南路21之1號', `start_date`='2025-07-17 00:00:00', `end_date`='2025-07-27 00:00:00', `location`='國家兩廳院', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='/+800;/+1200;/+1800;/+2800;/+3800;/+4800;/+5800;/+6600', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bc26b3242b74a3af32', '排灣族珠繡雲肩配件製作班', '透過課程中了解排灣族文化及價值觀，學習不同的圖騰珠繡內容，體驗珠繡技巧。訓練學員工藝技能並能學以致用，期望能帶動個人收益。\r\n本課程也係針對學習原住民耆老的頭飾縫製技能，珠繡設計技能教學及探討排灣族圖騰文化藝術意義與價值認知，幫助學員學習珠繡縫製技巧並能重視對文化之傳承，內容從基本圖騰繪圖與認識文化及學習珠繡技能，到整體頭飾車合的製作，由淺入深的階段式教學，搭配範例實際操作。', '桃園市政府原住民族行政局', '桃園市大園區', '2025-03-03 00:00:00', '2025-04-28 00:00:00', '大園區（桃園市）=', 25.06384709, 121.21177, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='排灣族珠繡雲肩配件製作班', `description`='透過課程中了解排灣族文化及價值觀，學習不同的圖騰珠繡內容，體驗珠繡技巧。訓練學員工藝技能並能學以致用，期望能帶動個人收益。\r\n本課程也係針對學習原住民耆老的頭飾縫製技能，珠繡設計技能教學及探討排灣族圖騰文化藝術意義與價值認知，幫助學員學習珠繡縫製技巧並能重視對文化之傳承，內容從基本圖騰繪圖與認識文化及學習珠繡技能，到整體頭飾車合的製作，由淺入深的階段式教學，搭配範例實際操作。', `organizer`='桃園市政府原住民族行政局', `address`='桃園市大園區', `start_date`='2025-03-03 00:00:00', `end_date`='2025-04-28 00:00:00', `location`='大園區（桃園市）=', `latitude`=25.06384709, `longitude`=121.21177, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bc26b3242b74a3af33', '原創拼布肩背包課程', '透過課程的安排可學習到傳統的技巧-圖騰構圖、拼布手縫縫法及連接拼片的運用，學習完本課程後，每個作品都可以有個人色彩，送禮、自用兩相宜。讓學員認識及瞭解開設『原創拼布肩背包課程』，是學習傳統技藝﹣圖騰構圖型、回縫、直縫、回針、壓縫等拼布手縫各種針法的運用，讓學員從做中學習到傳統技藝，可以完成自己專屬好看又實用的作品。經過講師示範實際教學，透過學員互相學習激盪出更多創意及想法，增進學員的技能及提升專業能力，製作完成作品至少一件。認同原住民傳統技藝並學習第二專長。', '桃園市政府原住民族行政局', '桃園市桃園區', '2025-03-04 00:00:00', '2025-05-06 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='原創拼布肩背包課程', `description`='透過課程的安排可學習到傳統的技巧-圖騰構圖、拼布手縫縫法及連接拼片的運用，學習完本課程後，每個作品都可以有個人色彩，送禮、自用兩相宜。讓學員認識及瞭解開設『原創拼布肩背包課程』，是學習傳統技藝﹣圖騰構圖型、回縫、直縫、回針、壓縫等拼布手縫各種針法的運用，讓學員從做中學習到傳統技藝，可以完成自己專屬好看又實用的作品。經過講師示範實際教學，透過學員互相學習激盪出更多創意及想法，增進學員的技能及提升專業能力，製作完成作品至少一件。認同原住民傳統技藝並學習第二專長。', `organizer`='桃園市政府原住民族行政局', `address`='桃園市桃園區', `start_date`='2025-03-04 00:00:00', `end_date`='2025-05-06 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bc26b3242b74a3af34', '蘭嶼傳統飾品班', '本課程旨在透過工藝課程將蘭嶼傳統文化、工藝和精神，傳承、傳遞給在桃園生活的雅美/達悟族人與媳婦。讓學員在桃園這塊土地，依舊可以學習到來自家鄉的傳統文化工藝。集結在桃園區的族人，以簡單易懂的方式教導，學員學習蘭嶼相關傳統工藝，自製屬於自己專屬的蘭嶼傳統飾品。 讓學習者從傳統工藝找回自己根源，也培育對自己家鄉文化與工藝的興趣，培養其第2職能專長。', '桃園市政府原住民族行政局', '桃園市大溪區', '2025-03-10 00:00:00', '2025-05-19 00:00:00', '大溪區（桃園市）=', 24.86797026, 121.296342, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蘭嶼傳統飾品班', `description`='本課程旨在透過工藝課程將蘭嶼傳統文化、工藝和精神，傳承、傳遞給在桃園生活的雅美/達悟族人與媳婦。讓學員在桃園這塊土地，依舊可以學習到來自家鄉的傳統文化工藝。集結在桃園區的族人，以簡單易懂的方式教導，學員學習蘭嶼相關傳統工藝，自製屬於自己專屬的蘭嶼傳統飾品。 讓學習者從傳統工藝找回自己根源，也培育對自己家鄉文化與工藝的興趣，培養其第2職能專長。', `organizer`='桃園市政府原住民族行政局', `address`='桃園市大溪區', `start_date`='2025-03-10 00:00:00', `end_date`='2025-05-19 00:00:00', `location`='大溪區（桃園市）=', `latitude`=24.86797026, `longitude`=121.296342, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af35', 'Podcast進階製作技巧與實戰應用(上)', '本課程旨在結合當代數位媒體技術與原住民族文化特色，透過Podcast製作的進階技術教學，提升學員的數位內容創作能力。課程以實務操作為核心，強調技術應用與創意表達，鼓勵學員以Podcast為平台傳播原住民族故事、文化與觀點，促進文化傳承與社會交流。\r\n', '桃園市政府原住民族行政局', '桃園市八德區', '2025-03-10 00:00:00', '2025-05-26 00:00:00', '八德區（桃園市）=', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Podcast進階製作技巧與實戰應用(上)', `description`='本課程旨在結合當代數位媒體技術與原住民族文化特色，透過Podcast製作的進階技術教學，提升學員的數位內容創作能力。課程以實務操作為核心，強調技術應用與創意表達，鼓勵學員以Podcast為平台傳播原住民族故事、文化與觀點，促進文化傳承與社會交流。\r\n', `organizer`='桃園市政府原住民族行政局', `address`='桃園市八德區', `start_date`='2025-03-10 00:00:00', `end_date`='2025-05-26 00:00:00', `location`='八德區（桃園市）=', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af36', '傳統改良服飾時尚禮服班', '課程將根據學員的職涯規劃，提供進階選擇，例如準備乙級及甲級證照。學員將接受更高難度的服裝設計與製作訓練，包括高級打版及車縫技巧，並完成難度更高的服裝作品，累積作品集以提升未來求職競爭力。此外，課程中亦將繼續結合家族傳統服飾設計，將專業與文化傳承相結合。\r\n', '桃園市政府原住民族行政局', '桃園市中壢區', '2025-03-11 00:00:00', '2025-05-27 00:00:00', '中壢區（桃園市）=', 24.97993803, 121.2147243, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='傳統改良服飾時尚禮服班', `description`='課程將根據學員的職涯規劃，提供進階選擇，例如準備乙級及甲級證照。學員將接受更高難度的服裝設計與製作訓練，包括高級打版及車縫技巧，並完成難度更高的服裝作品，累積作品集以提升未來求職競爭力。此外，課程中亦將繼續結合家族傳統服飾設計，將專業與文化傳承相結合。\r\n', `organizer`='桃園市政府原住民族行政局', `address`='桃園市中壢區', `start_date`='2025-03-11 00:00:00', `end_date`='2025-05-27 00:00:00', `location`='中壢區（桃園市）=', `latitude`=24.97993803, `longitude`=121.2147243, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af37', '數位影像拍攝、後製(基礎)課程', '本次計畫，工作室將以系統化課程交受學員如何使用移動工具拍攝、剪輯製作自媒體行銷短片、移動工具的正確使用方式及APP應用與直播等功能。本次計畫，工作室將以系統化課程交受學員如何使用移動工具拍攝、剪輯製作自媒體行銷短片、移動工具的正確使用方式及APP應用與直播等功能。\r\n', '桃園市政府原住民族行政局', '桃園市復興區', '2025-03-26 00:00:00', '2025-05-28 00:00:00', '復興區（桃園市）=', 24.72949884, 121.3754588, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='數位影像拍攝、後製(基礎)課程', `description`='本次計畫，工作室將以系統化課程交受學員如何使用移動工具拍攝、剪輯製作自媒體行銷短片、移動工具的正確使用方式及APP應用與直播等功能。本次計畫，工作室將以系統化課程交受學員如何使用移動工具拍攝、剪輯製作自媒體行銷短片、移動工具的正確使用方式及APP應用與直播等功能。\r\n', `organizer`='桃園市政府原住民族行政局', `address`='桃園市復興區', `start_date`='2025-03-26 00:00:00', `end_date`='2025-05-28 00:00:00', `location`='復興區（桃園市）=', `latitude`=24.72949884, `longitude`=121.3754588, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af38', 'AI時代的族語傳承：指令集開發實作之道(初階)', '隨著AI技術的飛速發展，如何利用科技保護並傳承原住民族語言已成為重要課題。本課程基於「文化永續發展」的核心理念，結合現代資訊科技，透過實作的方式，讓學員掌握AI在族語保存與創新應用中的潛力，並激發對自身文化的認同與熱情。課程強調實踐與創新，期望以技術為媒介，開啟族語傳承的新篇章。\r\n1.掌握基礎AI技術\r\n2.提升族語數位化能力\r\n3.促進文化傳承與創新\r\n4.建立族語AI應用場景\r\n5.增進社群參與意識\r\n6.教導族語教師製作課程化教材與評量工具', '桃園市政府原住民族行政局', '桃園市八德區', '2025-03-12 00:00:00', '2025-06-04 00:00:00', '八德區（桃園市）=', 24.94968903, 121.2913102, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='AI時代的族語傳承：指令集開發實作之道(初階)', `description`='隨著AI技術的飛速發展，如何利用科技保護並傳承原住民族語言已成為重要課題。本課程基於「文化永續發展」的核心理念，結合現代資訊科技，透過實作的方式，讓學員掌握AI在族語保存與創新應用中的潛力，並激發對自身文化的認同與熱情。課程強調實踐與創新，期望以技術為媒介，開啟族語傳承的新篇章。\r\n1.掌握基礎AI技術\r\n2.提升族語數位化能力\r\n3.促進文化傳承與創新\r\n4.建立族語AI應用場景\r\n5.增進社群參與意識\r\n6.教導族語教師製作課程化教材與評量工具', `organizer`='桃園市政府原住民族行政局', `address`='桃園市八德區', `start_date`='2025-03-12 00:00:00', `end_date`='2025-06-04 00:00:00', `location`='八德區（桃園市）=', `latitude`=24.94968903, `longitude`=121.2913102, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af39', '仿真多肉植感課程(進階)', '本課程的核心理念是「快樂學習」，希望在輕鬆愉快的學習環境中，學員能夠獨立完成老師所教授創作出屬於自己的獨特小品。在與同學的互動過程中，進行教學相長，激發不同的思考方式，並藉此培養友誼與學習動力。這樣的學習經歷會將快樂與正能量傳遞給身邊的朋友，並進一步擴展至社區，實現生活藝術化與終身學習的目標。\r\n', '桃園市政府原住民族行政局', '桃園市蘆竹區', '2025-03-12 00:00:00', '2025-05-28 00:00:00', '蘆竹區（桃園市）=', 25.06073337, 121.2831266, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='仿真多肉植感課程(進階)', `description`='本課程的核心理念是「快樂學習」，希望在輕鬆愉快的學習環境中，學員能夠獨立完成老師所教授創作出屬於自己的獨特小品。在與同學的互動過程中，進行教學相長，激發不同的思考方式，並藉此培養友誼與學習動力。這樣的學習經歷會將快樂與正能量傳遞給身邊的朋友，並進一步擴展至社區，實現生活藝術化與終身學習的目標。\r\n', `organizer`='桃園市政府原住民族行政局', `address`='桃園市蘆竹區', `start_date`='2025-03-12 00:00:00', `end_date`='2025-05-28 00:00:00', `location`='蘆竹區（桃園市）=', `latitude`=25.06073337, `longitude`=121.2831266, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af3a', 'drekai 魯凱槌染編織班', '為廣泛推展魯凱族傳統技藝文化在當中也加入多年的學習染（waereme)的技藝技巧融入當中，在生活如何使用在物品及如何應用為願景。探討槌染透過敲擊在棉麻布上所呈現不同的葉子葉脈，葉形，輪廓，顏色及葉子的樣貌再透過媒染接合所產生的美感，讓學員產生不一樣的創作。將所長專業知識，技藝及生活經驗與學員相互交流，營造分享共同成長學習氛圍，開闊彼此視野。引發學員進行槌染及編織文化技藝發展。傳遞槌染與編織在生活中的意義。討論出美好民族文化。', '桃園市政府原住民族行政局', '桃園市桃園區', '2025-03-13 00:00:00', '2025-05-29 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='drekai 魯凱槌染編織班', `description`='為廣泛推展魯凱族傳統技藝文化在當中也加入多年的學習染（waereme)的技藝技巧融入當中，在生活如何使用在物品及如何應用為願景。探討槌染透過敲擊在棉麻布上所呈現不同的葉子葉脈，葉形，輪廓，顏色及葉子的樣貌再透過媒染接合所產生的美感，讓學員產生不一樣的創作。將所長專業知識，技藝及生活經驗與學員相互交流，營造分享共同成長學習氛圍，開闊彼此視野。引發學員進行槌染及編織文化技藝發展。傳遞槌染與編織在生活中的意義。討論出美好民族文化。', `organizer`='桃園市政府原住民族行政局', `address`='桃園市桃園區', `start_date`='2025-03-13 00:00:00', `end_date`='2025-05-29 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af3b', '織出魅力包：編織設計與行銷全新體驗初階班', '傳統編織技藝與現代素材的結合，開啟了新的創作可能性。本課程以「傳承技藝、實踐創新」為核心，結合布感織帶及珍珠帶這樣的現代素材，發展現代實用性產品（如編織包），並導入行銷實務知識，協助學員將傳統技藝與現代市場接軌。課程設計強調文化自信、創新創業以及社區共榮，期望透過編織技藝的學習與應用，提升學員的就業及創業能力。\r\n', '桃園市政府原住民族行政局', '桃園市觀音區', '2025-03-13 00:00:00', '2025-06-26 00:00:00', '觀音區（桃園市）=', 25.02671611, 121.1155021, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='織出魅力包：編織設計與行銷全新體驗初階班', `description`='傳統編織技藝與現代素材的結合，開啟了新的創作可能性。本課程以「傳承技藝、實踐創新」為核心，結合布感織帶及珍珠帶這樣的現代素材，發展現代實用性產品（如編織包），並導入行銷實務知識，協助學員將傳統技藝與現代市場接軌。課程設計強調文化自信、創新創業以及社區共榮，期望透過編織技藝的學習與應用，提升學員的就業及創業能力。\r\n', `organizer`='桃園市政府原住民族行政局', `address`='桃園市觀音區', `start_date`='2025-03-13 00:00:00', `end_date`='2025-06-26 00:00:00', `location`='觀音區（桃園市）=', `latitude`=25.02671611, `longitude`=121.1155021, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af3c', '二級美甲證照班', '課程可以讓學員了解相關理論、技巧以及市場趨勢，培養專業化的能力。許多學員通過學習美甲找到自己的興趣，提升自信心和成就感。\r\n', '桃園市政府原住民族行政局', '桃園市龜山區', '2025-03-15 00:00:00', '2025-06-14 00:00:00', '龜山區（桃園市）=', 25.02417472, 121.3569265, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='二級美甲證照班', `description`='課程可以讓學員了解相關理論、技巧以及市場趨勢，培養專業化的能力。許多學員通過學習美甲找到自己的興趣，提升自信心和成就感。\r\n', `organizer`='桃園市政府原住民族行政局', `address`='桃園市龜山區', `start_date`='2025-03-15 00:00:00', `end_date`='2025-06-14 00:00:00', `location`='龜山區（桃園市）=', `latitude`=25.02417472, `longitude`=121.3569265, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af3d', '肩上的藝術，心中的微醺 (基礎班)', '本課程結合排灣族珠繡與釀小米酒的傳統技藝，旨在傳承部落文化與生活智慧，透過實作與文化學習，讓學員深入了解排灣族獨特的美學與飲食文化。希望以珠繡雲肩與釀酒為媒介，促進對原住民文化的認識與尊重，同時加強學員的手作技術與文化認同感。\r\n', '桃園市政府原住民族行政局', '桃園市楊梅區', '2025-03-15 00:00:00', '2025-06-28 00:00:00', '楊梅區（桃園市）=', 24.91820989, 121.1291697, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='肩上的藝術，心中的微醺 (基礎班)', `description`='本課程結合排灣族珠繡與釀小米酒的傳統技藝，旨在傳承部落文化與生活智慧，透過實作與文化學習，讓學員深入了解排灣族獨特的美學與飲食文化。希望以珠繡雲肩與釀酒為媒介，促進對原住民文化的認識與尊重，同時加強學員的手作技術與文化認同感。\r\n', `organizer`='桃園市政府原住民族行政局', `address`='桃園市楊梅區', `start_date`='2025-03-15 00:00:00', `end_date`='2025-06-28 00:00:00', `location`='楊梅區（桃園市）=', `latitude`=24.91820989, `longitude`=121.1291697, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af3e', '台東阿美族男子腰帶製作課程(勾針版)', '這次所學的是用勾針學習製作腰帶,傳承阿嬤的技藝,這是非常繁複的製作過程,必須靠雙手一針一線剪裁縫製而成,尤其要非常有耐心專注力,再由老師細心、專業地教課下,在這樣的進度下完成作品,做一套真正屬於自己的阿美族傳統男生族服.\r\n', '桃園市政府原住民族行政局', '桃園市桃園區', '2025-03-15 00:00:00', '2025-06-14 00:00:00', '桃園區（桃園市）=', 25.00040024, 121.2996612, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台東阿美族男子腰帶製作課程(勾針版)', `description`='這次所學的是用勾針學習製作腰帶,傳承阿嬤的技藝,這是非常繁複的製作過程,必須靠雙手一針一線剪裁縫製而成,尤其要非常有耐心專注力,再由老師細心、專業地教課下,在這樣的進度下完成作品,做一套真正屬於自己的阿美族傳統男生族服.\r\n', `organizer`='桃園市政府原住民族行政局', `address`='桃園市桃園區', `start_date`='2025-03-15 00:00:00', `end_date`='2025-06-14 00:00:00', `location`='桃園區（桃園市）=', `latitude`=25.00040024, `longitude`=121.2996612, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af3f', '台東阿美族十字繡''alofo班', '藉由本次課程激發學員創作立及想像力，並培養傳統藝術及現代藝術的審美感，啟發個人藝術美感及創作力，為發揚及傳承阿美族傳統技藝，促進族人對自我傳統藝術的認同，並激發對手工藝之傳承，透過課程使旅北居住族人習得傳統十字繡的由來及製作方式，也能學會之後持續學習，再往下扎根傳承手藝，使傳統手工藝及文化不會出現斷層，也鼓勵勇於創業，發揮創意的新氣象。\r\n', '桃園市政府原住民族行政局', '桃園市新屋區', '2025-03-16 00:00:00', '2025-06-15 00:00:00', '新屋區（桃園市）=', 24.97280352, 121.067758, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台東阿美族十字繡''alofo班', `description`='藉由本次課程激發學員創作立及想像力，並培養傳統藝術及現代藝術的審美感，啟發個人藝術美感及創作力，為發揚及傳承阿美族傳統技藝，促進族人對自我傳統藝術的認同，並激發對手工藝之傳承，透過課程使旅北居住族人習得傳統十字繡的由來及製作方式，也能學會之後持續學習，再往下扎根傳承手藝，使傳統手工藝及文化不會出現斷層，也鼓勵勇於創業，發揮創意的新氣象。\r\n', `organizer`='桃園市政府原住民族行政局', `address`='桃園市新屋區', `start_date`='2025-03-16 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='新屋區（桃園市）=', `latitude`=24.97280352, `longitude`=121.067758, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af40', '泰雅傳統織布初階班', '傳承傳統泰雅族織布藝術，並運用在日常用品或手工藝品的創作，增進落婦女收入，進而發展成部落傳統特色產業。泰雅織布之美讓人驚艷其文化價值，其傳統服飾更是將織布美及實用性結合如一，本次希望透過此課程，繼續延續泰雅族特有的傳統織布藝術之美，除此之外透過行銷可增加收入，改善家庭生活,發展部落文化產業。傳承泰雅傳統服飾製作工藝，傳承泰雅服飾文化。', '桃園市政府原住民族行政局', '桃園市復興區', '2025-03-19 00:00:00', '2025-05-14 00:00:00', '復興區（桃園市）=', 24.72949884, 121.3754588, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='泰雅傳統織布初階班', `description`='傳承傳統泰雅族織布藝術，並運用在日常用品或手工藝品的創作，增進落婦女收入，進而發展成部落傳統特色產業。泰雅織布之美讓人驚艷其文化價值，其傳統服飾更是將織布美及實用性結合如一，本次希望透過此課程，繼續延續泰雅族特有的傳統織布藝術之美，除此之外透過行銷可增加收入，改善家庭生活,發展部落文化產業。傳承泰雅傳統服飾製作工藝，傳承泰雅服飾文化。', `organizer`='桃園市政府原住民族行政局', `address`='桃園市復興區', `start_date`='2025-03-19 00:00:00', `end_date`='2025-05-14 00:00:00', `location`='復興區（桃園市）=', `latitude`=24.72949884, `longitude`=121.3754588, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af41', 'qwas lmuhuw 口述傳統班', '透過泰雅族的口述傳統學習遷徙的歷史與文化，於教學之中認同自己的文化；激發愛族群及關懷部落的心。期望qwas lmuhuw 口述傳統Atayal泰雅族能在年輕人的口中，再度被傳唱被興旺。\r\n', '桃園市政府原住民族行政局', '桃園市復興區', '2025-03-22 00:00:00', '2025-06-21 00:00:00', '復興區（桃園市）=', 24.72949884, 121.3754588, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='qwas lmuhuw 口述傳統班', `description`='透過泰雅族的口述傳統學習遷徙的歷史與文化，於教學之中認同自己的文化；激發愛族群及關懷部落的心。期望qwas lmuhuw 口述傳統Atayal泰雅族能在年輕人的口中，再度被傳唱被興旺。\r\n', `organizer`='桃園市政府原住民族行政局', `address`='桃園市復興區', `start_date`='2025-03-22 00:00:00', `end_date`='2025-06-21 00:00:00', `location`='復興區（桃園市）=', `latitude`=24.72949884, `longitude`=121.3754588, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bd26b3242b74a3af42', '原住民手工肚兜班', '透過課程，招聚部落族人，認識新朋友開拓視野。透過課程，更認識原住民文化。透過影片認識原住民度兜。讓學員都能趕上進度。肚兜技藝能被發揚傳承。\r\n', '桃園市政府原住民族行政局', '桃園市大園區', '2025-03-31 00:00:00', '2025-06-18 00:00:00', '大園區（桃園市）=', 25.06384709, 121.21177, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='原住民手工肚兜班', `description`='透過課程，招聚部落族人，認識新朋友開拓視野。透過課程，更認識原住民文化。透過影片認識原住民度兜。讓學員都能趕上進度。肚兜技藝能被發揚傳承。\r\n', `organizer`='桃園市政府原住民族行政局', `address`='桃園市大園區', `start_date`='2025-03-31 00:00:00', `end_date`='2025-06-18 00:00:00', `location`='大園區（桃園市）=', `latitude`=25.06384709, `longitude`=121.21177, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2bf26b3242b74a3af43', '失落祕境——劉慧中首個展', '劉慧中 (b.1990,台灣) 2012年於國立臺北藝術大學美術系畢業後，隨即赴西班牙塞維利亞大學留學並取得碩士學位。 \r\n\r\n屢獲海內外的殊榮和肯定，為Antonio Gala基金會培育年輕藝術家計畫的駐村創作者，作品並被西班牙、比利時等機構典藏。 歷來榮獲聯邦美術新人獎、全國百號油畫大展的優選，亦曾名列文化部臺北國際藝術博覽會的新人推薦，作品為中國醫藥大學美術館典藏。 \r\n\r\n劉慧中擅長以繪畫編織詩意與童話，在夢境與現實的交錯間，營造既溫暖又奇異的場景。她的畫作融合文學、詩歌、音樂與個人記憶，透過錯置、擬人化、層疊等手法，使虛實交錯、故事層層展開。其作品色彩柔和，彷彿構築出純然美好的世界，卻在綺麗的秘境之中，暗藏對現實的探問與感知的解放，呈現出一種既夢幻又充滿張力的藝術語彙。', '曙畫廊', '臺北市士林區', '2025-04-19 00:00:00', '2025-06-07 00:00:00', '士林區（臺北市）=', 25.12546704, 121.5508473, '無資料', 'https://enlighten-gallery.com/%e5%a4%b1%e8%90%bd%e7%a5%95%e5%a2%83-%e5%8a%89%e6%85%a7%e4%b8%ad%e9%a6', '[]') ON DUPLICATE KEY UPDATE `activity_name`='失落祕境——劉慧中首個展', `description`='劉慧中 (b.1990,台灣) 2012年於國立臺北藝術大學美術系畢業後，隨即赴西班牙塞維利亞大學留學並取得碩士學位。 \r\n\r\n屢獲海內外的殊榮和肯定，為Antonio Gala基金會培育年輕藝術家計畫的駐村創作者，作品並被西班牙、比利時等機構典藏。 歷來榮獲聯邦美術新人獎、全國百號油畫大展的優選，亦曾名列文化部臺北國際藝術博覽會的新人推薦，作品為中國醫藥大學美術館典藏。 \r\n\r\n劉慧中擅長以繪畫編織詩意與童話，在夢境與現實的交錯間，營造既溫暖又奇異的場景。她的畫作融合文學、詩歌、音樂與個人記憶，透過錯置、擬人化、層疊等手法，使虛實交錯、故事層層展開。其作品色彩柔和，彷彿構築出純然美好的世界，卻在綺麗的秘境之中，暗藏對現實的探問與感知的解放，呈現出一種既夢幻又充滿張力的藝術語彙。', `organizer`='曙畫廊', `address`='臺北市士林區', `start_date`='2025-04-19 00:00:00', `end_date`='2025-06-07 00:00:00', `location`='士林區（臺北市）=', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='無資料', `source_url`='https://enlighten-gallery.com/%e5%a4%b1%e8%90%bd%e7%a5%95%e5%a2%83-%e5%8a%89%e6%85%a7%e4%b8%ad%e9%a6', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2c426b3242b74a3af45', '四季之歌-油畫師生聯展', '在藝術的旅途中，每一筆都是成長的痕跡。師生攜手，以不同的視角詮釋創作歷程，展現從啟蒙到成熟的蛻變。跨越經驗與新意，以油彩捕捉四季更迭的美好，共同繪出屬於我們的成長篇章。', '桃園市楊梅地政事務所', '桃園市楊梅區', '2025-04-01 00:00:00', '2025-06-30 00:00:00', '楊梅區（桃園市）=', 24.91820989, 121.1291697, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='四季之歌-油畫師生聯展', `description`='在藝術的旅途中，每一筆都是成長的痕跡。師生攜手，以不同的視角詮釋創作歷程，展現從啟蒙到成熟的蛻變。跨越經驗與新意，以油彩捕捉四季更迭的美好，共同繪出屬於我們的成長篇章。', `organizer`='桃園市楊梅地政事務所', `address`='桃園市楊梅區', `start_date`='2025-04-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='楊梅區（桃園市）=', `latitude`=24.91820989, `longitude`=121.1291697, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f6e2c426b3242b74a3af46', '4月高雄市電影館｜東邪西毒：終極版【輔導十二歲級】', '耗時4年重新剪輯，2008坎城影展全球首映終極版\r\n\r\n歐陽鋒失去戀人後隱居沙漠，以職業殺手維生，與黃藥師、慕容燕、盲劍客、洪七、桃花，交織出一場愛恨纏繞的戰爭。戰爭沒有勝利者，只有喝下「醉生夢死」的酒，讓曾經相濡以沫的人，從此相忘於江湖。取材金庸武俠小說《射鵰英雄傳》，集結張國榮、林青霞、梁朝偉、劉嘉玲、梁家輝、楊采妮、張學友、張曼玉，並由馬友友配樂，詮釋英雄身在江湖的磅礡蒼涼。\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n票價資訊\r\n票價：原價260元\r\n．影友優惠票200元：持有效期限內「高雄市電影館CLASSIC／GOLD+影友卡」購買者(進場請出示卡片)\r\n．愛心票130元：65歲以上人士（憑相關證件）、身心障礙人士（憑相關證件）與陪同者限一名享愛心票優惠\r\n\r\n\r\n\r\n注意事項\r\n◆內惟藝術中心 Reel two 2廳Ａ排、Ｂ排為單人沙發座\r\n◆現場購票可至官方網站查詢場館營業時間；年代售票網站(郵寄.便利商店取票)、全台年代售票端點、四大超商機台皆可購票\r\n\r\n◆CLASSIC／GOLD+會員之影友優惠票規範詳情請參閱官方網站公告\r\n\r\n◆場次開演後10分停止售票／20分後不得入場；持優惠票入場時須出示證件，如未出示須補足差額方可入場\r\n\r\n◆退票需於開演前30分臨櫃依規定辦理；換票視同退票，如需更換場次，請依退票方式辦理並酌收退票手續費10%\r\n\r\n◆取票手續費、轉帳手續費及郵資票券等額外手續費非屬票價部分不在退款範圍之內，需由購票人自行負擔\r\n\r\n◆本節目退換票請洽主辦單位-高雄市電影館07-5511211# 2015\r\n\r\n◆如不可抗因素致演出取消，購票者同意依據主辦方制定退票規則辦理', '高雄市電影館', '高雄市鹽埕區4鄰河西路10號', '2025-04-01 00:00:00', '2025-04-27 00:00:00', '高雄市電影館', 22.622671, 120.289122, '愛心票+130;影友優惠票+200;兒童票+208;原價+260', 'http://www.ticket.com.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='4月高雄市電影館｜東邪西毒：終極版【輔導十二歲級】', `description`='耗時4年重新剪輯，2008坎城影展全球首映終極版\r\n\r\n歐陽鋒失去戀人後隱居沙漠，以職業殺手維生，與黃藥師、慕容燕、盲劍客、洪七、桃花，交織出一場愛恨纏繞的戰爭。戰爭沒有勝利者，只有喝下「醉生夢死」的酒，讓曾經相濡以沫的人，從此相忘於江湖。取材金庸武俠小說《射鵰英雄傳》，集結張國榮、林青霞、梁朝偉、劉嘉玲、梁家輝、楊采妮、張學友、張曼玉，並由馬友友配樂，詮釋英雄身在江湖的磅礡蒼涼。\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\n票價資訊\r\n票價：原價260元\r\n．影友優惠票200元：持有效期限內「高雄市電影館CLASSIC／GOLD+影友卡」購買者(進場請出示卡片)\r\n．愛心票130元：65歲以上人士（憑相關證件）、身心障礙人士（憑相關證件）與陪同者限一名享愛心票優惠\r\n\r\n\r\n\r\n注意事項\r\n◆內惟藝術中心 Reel two 2廳Ａ排、Ｂ排為單人沙發座\r\n◆現場購票可至官方網站查詢場館營業時間；年代售票網站(郵寄.便利商店取票)、全台年代售票端點、四大超商機台皆可購票\r\n\r\n◆CLASSIC／GOLD+會員之影友優惠票規範詳情請參閱官方網站公告\r\n\r\n◆場次開演後10分停止售票／20分後不得入場；持優惠票入場時須出示證件，如未出示須補足差額方可入場\r\n\r\n◆退票需於開演前30分臨櫃依規定辦理；換票視同退票，如需更換場次，請依退票方式辦理並酌收退票手續費10%\r\n\r\n◆取票手續費、轉帳手續費及郵資票券等額外手續費非屬票價部分不在退款範圍之內，需由購票人自行負擔\r\n\r\n◆本節