INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f8385426b3242b74a3af7c', '【新北市立圖書館林口西林圖書閱覽室】114年4月主題書展', '【林口西林圖書閱覽室】114年4月主題書展\r\n地點:林口西林圖書閱覽室3樓展示區\r\n地址:新北市林口區林口路15號3樓之1\r\n書展主題:繪本童樂會\r\n簡介:繽紛有趣的兒童繪本，多國的故事內容，一起加入繪本童樂會吧。', '新北市立圖書館總館', '新北市林口區林口路15號3樓之一', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館林口西林圖書閱覽室', 25.1000868, 121.3527235, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館林口西林圖書閱覽室】114年4月主題書展', `description`='【林口西林圖書閱覽室】114年4月主題書展\r\n地點:林口西林圖書閱覽室3樓展示區\r\n地址:新北市林口區林口路15號3樓之1\r\n書展主題:繪本童樂會\r\n簡介:繽紛有趣的兒童繪本，多國的故事內容，一起加入繪本童樂會吧。', `organizer`='新北市立圖書館總館', `address`='新北市林口區林口路15號3樓之一', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館林口西林圖書閱覽室', `latitude`=25.1000868, `longitude`=121.3527235, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f8386e26b3242b74a3af7d', '2025「妙音曼舞—敦煌樂舞文化主題展」', '此次展覽聚焦「樂舞」主題，規劃「絲路漫行」、「淨土梵音」與「繽紛散樂」三大展區，引領觀眾穿越千年，沉浸於敦煌壁畫與樂舞藝術的華彩盛景。展覽結合仿製樂器、石窟模型、壁畫再現與多媒體欣賞，營造身臨其境的觀展感受，讓觀眾得以近距離領略敦煌文化的瑰麗風華。', '財團法人沈春池文教基金會', '嘉義市東區學府路300號', '2025-03-07 00:00:00', '2025-06-20 00:00:00', '國立嘉義大學（蘭潭校區）', 23.48170334, 120.4706244, '無資料', 'https://dunhuan.sccf.org.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025「妙音曼舞—敦煌樂舞文化主題展」', `description`='此次展覽聚焦「樂舞」主題，規劃「絲路漫行」、「淨土梵音」與「繽紛散樂」三大展區，引領觀眾穿越千年，沉浸於敦煌壁畫與樂舞藝術的華彩盛景。展覽結合仿製樂器、石窟模型、壁畫再現與多媒體欣賞，營造身臨其境的觀展感受，讓觀眾得以近距離領略敦煌文化的瑰麗風華。', `organizer`='財團法人沈春池文教基金會', `address`='嘉義市東區學府路300號', `start_date`='2025-03-07 00:00:00', `end_date`='2025-06-20 00:00:00', `location`='國立嘉義大學（蘭潭校區）', `latitude`=23.48170334, `longitude`=120.4706244, `ticket_price`='無資料', `source_url`='https://dunhuan.sccf.org.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f8389626b3242b74a3af7e', '古意今情—新北市板橋區松年大學長壽會彩墨聯展', '  創設於民國96年之新北市板橋區松年大學，是以推廣及提供社區民眾優質課程與研習進修機會之成人教育機構。藉由教學與互動來培養成人終身學習之觀念，以充實生活內涵、提昇生活品質。其中長壽會國畫班是以高齡長者為對象的進修班，希望藉由此次(古意‧今情)展出，將學員多年習畫的成果與民眾分享。\r\n  「古意」代表著傳統文化的深厚底蘊，是歷史的印記與歲月的累積；「今情」則是體現了長者，面對當下社會變遷時，所產生的情感共鳴與藝術創新。\r\n  展覽希望透過「古」與「今」的對話，展現長壽會國畫班高齡長者快樂學習，以彩墨書寫生命故事的力量，尋找在文化與情感中的連結與樂齡時代的價值。', '新北市土城區公所', '新北市土城區金城路一段101號', '2025-03-26 00:00:00', '2025-04-24 00:00:00', '新北市土城區公所(行政大樓)', 24.96425102, 121.445737, '無資料', 'https://www.tucheng.ntpc.gov.tw/index.jsp', '[]') ON DUPLICATE KEY UPDATE `activity_name`='古意今情—新北市板橋區松年大學長壽會彩墨聯展', `description`='  創設於民國96年之新北市板橋區松年大學，是以推廣及提供社區民眾優質課程與研習進修機會之成人教育機構。藉由教學與互動來培養成人終身學習之觀念，以充實生活內涵、提昇生活品質。其中長壽會國畫班是以高齡長者為對象的進修班，希望藉由此次(古意‧今情)展出，將學員多年習畫的成果與民眾分享。\r\n  「古意」代表著傳統文化的深厚底蘊，是歷史的印記與歲月的累積；「今情」則是體現了長者，面對當下社會變遷時，所產生的情感共鳴與藝術創新。\r\n  展覽希望透過「古」與「今」的對話，展現長壽會國畫班高齡長者快樂學習，以彩墨書寫生命故事的力量，尋找在文化與情感中的連結與樂齡時代的價值。', `organizer`='新北市土城區公所', `address`='新北市土城區金城路一段101號', `start_date`='2025-03-26 00:00:00', `end_date`='2025-04-24 00:00:00', `location`='新北市土城區公所(行政大樓)', `latitude`=24.96425102, `longitude`=121.445737, `ticket_price`='無資料', `source_url`='https://www.tucheng.ntpc.gov.tw/index.jsp', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f8389d26b3242b74a3af82', '西拉雅語言復振-頭社教會學習班(聖歌隊)', '西拉雅語是臺灣原住民族西拉雅族的語言，屬於南島語系馬來-波利尼西亞語族。西拉雅族主要分布於臺灣西南部，包括今日的台南地區。\r\n\r\n西拉雅語曾是西拉雅族的主要溝通語言，並在17世紀荷蘭統治台灣時，被荷蘭人以羅馬字母記錄，用於傳教與行政事務，形成「新港文書」。由於漢化與社會變遷影響，西拉雅語逐漸消失，成為瀕危語言。\r\n為強化對西拉雅語保存與發展功能，提供不一樣的學習方案，藉由「詩歌西拉雅譯本」相關教材，透過練習詩歌學習族語，並使頭社教會成為學習族語的據點。', '臺南市頭社西拉雅文化發展協會', '臺南市大內區', '2025-04-06 00:00:00', '2025-11-30 00:00:00', '大內區（臺南市）=', 23.14482152, 120.3988147, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='西拉雅語言復振-頭社教會學習班(聖歌隊)', `description`='西拉雅語是臺灣原住民族西拉雅族的語言，屬於南島語系馬來-波利尼西亞語族。西拉雅族主要分布於臺灣西南部，包括今日的台南地區。\r\n\r\n西拉雅語曾是西拉雅族的主要溝通語言，並在17世紀荷蘭統治台灣時，被荷蘭人以羅馬字母記錄，用於傳教與行政事務，形成「新港文書」。由於漢化與社會變遷影響，西拉雅語逐漸消失，成為瀕危語言。\r\n為強化對西拉雅語保存與發展功能，提供不一樣的學習方案，藉由「詩歌西拉雅譯本」相關教材，透過練習詩歌學習族語，並使頭社教會成為學習族語的據點。', `organizer`='臺南市頭社西拉雅文化發展協會', `address`='臺南市大內區', `start_date`='2025-04-06 00:00:00', `end_date`='2025-11-30 00:00:00', `location`='大內區（臺南市）=', `latitude`=23.14482152, `longitude`=120.3988147, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838aa26b3242b74a3af8a', 'in臺南‧無影藏─臺南市文化資產影像競賽', '1、 主旨\r\n「in臺南‧無影藏─2025臺南市文化資產影像競賽」廣召以影像保存臺南文化資產特色與傳承文化有興趣和熱忱的民眾踴躍報名，不論是已登錄的文化資產，亦或是生活中潛在的文化資產，透過影像徵件活動不僅能為在地文化留下更多動人的影像，更能藉以對全民推廣文化資產保護之重要性，同時建立臺南市文化資產的資源多樣性、文化故事性與城市歷史永續性。\r\n\r\n2、徵件主題\r\n\r\n臺南市已登錄及生活中潛在的文化資產(包含有形文化資產：古蹟、歷史建築、紀念建築群、考古遺址、史蹟、文化景觀、古物、自然地景/自然紀念物；無形文化資產：傳統表演藝術、傳統工藝、口述傳統、民俗、傳統知識與實踐)為創作元素與概念發想，透過創造性、故事性與原創性的方式拍攝出影像作品。\r\n※臺南市文化資產定義及項目可參閱《文化資產保存法》與「國家文化資產網」https://nchdb.boch.gov.tw/\r\n\r\n3、報名資格\r\n \r\n熱愛影像創作、拍攝製作臺南文化資產相關之影像作品，不限影片類型、長度30分鐘以內，個人或團體國內外人士皆可報名。\r\n\r\n4、 競賽獎項\r\n\r\n入圍作品：於頒獎暨巡迴播映記者會分別頒發入圍證書。\r\n得獎作品：於頒獎暨巡迴播映記者會頒布獎次、獎金和獎座。\r\n\r\n首獎：1名，獎金新臺幣 150,000元，獎座1座。\r\n二獎：1名，獎金新臺幣 100,000元，獎座1座。\r\n三獎：1名，獎金新臺幣 80,000元，獎座1座。\r\n優選：3名，獎金新臺幣 30,000元，獎狀1只。\r\n佳作：3名，獎金新臺幣 10,000元，獎狀1只。\r\n※頒獎暨巡迴播映記者會：場地、時間由主辦單位另行公告及通知。\r\n\r\n', '臺南市文化資產管理處', '臺南市北區', '2025-04-02 00:00:00', '2025-06-30 00:00:00', '北區（臺南市）=', 23.01012179, 120.2068735, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='in臺南‧無影藏─臺南市文化資產影像競賽', `description`='1、 主旨\r\n「in臺南‧無影藏─2025臺南市文化資產影像競賽」廣召以影像保存臺南文化資產特色與傳承文化有興趣和熱忱的民眾踴躍報名，不論是已登錄的文化資產，亦或是生活中潛在的文化資產，透過影像徵件活動不僅能為在地文化留下更多動人的影像，更能藉以對全民推廣文化資產保護之重要性，同時建立臺南市文化資產的資源多樣性、文化故事性與城市歷史永續性。\r\n\r\n2、徵件主題\r\n\r\n臺南市已登錄及生活中潛在的文化資產(包含有形文化資產：古蹟、歷史建築、紀念建築群、考古遺址、史蹟、文化景觀、古物、自然地景/自然紀念物；無形文化資產：傳統表演藝術、傳統工藝、口述傳統、民俗、傳統知識與實踐)為創作元素與概念發想，透過創造性、故事性與原創性的方式拍攝出影像作品。\r\n※臺南市文化資產定義及項目可參閱《文化資產保存法》與「國家文化資產網」https://nchdb.boch.gov.tw/\r\n\r\n3、報名資格\r\n \r\n熱愛影像創作、拍攝製作臺南文化資產相關之影像作品，不限影片類型、長度30分鐘以內，個人或團體國內外人士皆可報名。\r\n\r\n4、 競賽獎項\r\n\r\n入圍作品：於頒獎暨巡迴播映記者會分別頒發入圍證書。\r\n得獎作品：於頒獎暨巡迴播映記者會頒布獎次、獎金和獎座。\r\n\r\n首獎：1名，獎金新臺幣 150,000元，獎座1座。\r\n二獎：1名，獎金新臺幣 100,000元，獎座1座。\r\n三獎：1名，獎金新臺幣 80,000元，獎座1座。\r\n優選：3名，獎金新臺幣 30,000元，獎狀1只。\r\n佳作：3名，獎金新臺幣 10,000元，獎狀1只。\r\n※頒獎暨巡迴播映記者會：場地、時間由主辦單位另行公告及通知。\r\n\r\n', `organizer`='臺南市文化資產管理處', `address`='臺南市北區', `start_date`='2025-04-02 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='北區（臺南市）=', `latitude`=23.01012179, `longitude`=120.2068735, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ab26b3242b74a3af8b', '【2025 TIDF巡迴展 高雄場｜免費特映】4/18《阿根廷正義審判》', '1985年春天，布宜諾斯艾利斯，一場史無前例的世紀審判浩蕩展開。民選政府追訴九名軍政府獨裁時期最位高權重的軍官，包含惡名昭彰的前獨裁者魏德拉，試圖為「骯髒戰爭」期間的受難者伸張遲來的正義。本片重新梳理長達530小時的法庭影像，不僅記錄下拉丁美洲史上最為關鍵的轉型正義時刻，也讓「永不再犯」（Never Again）的意義在現下時刻更顯擲地有聲。\r\n\r\n烏里賽斯．德拉歐丹：「這場審判總共歷經90天，全程由公共電視台用兩台磁帶攝影機錄下。從2013年起，我們開始尋找和取得這530小時的審判影像，希望能製作成一部紀錄片，一方面描述其中發生的事，另一方面訴說阿根廷經歷恐怖政治和日後尋求正義的過程。\r\n\r\n但光是找到錄影資料就相當不易。負責錄影的公共電視台擔心受到政治報復，因此拒絕與我有任何形式的合作。負責收藏錄影帶的阿根廷國家文物典藏館，則以避免不便為由，建議我到同樣擁有錄影複本的西班牙薩拉曼卡大學去找。即使審判已經過了30年，基層公務員還是會害怕、不敢承擔風險，這實在匪夷所思。\r\n\r\n到了2019年，我透過Luisa Hairebedian基金會的朋友，得知「開放記憶」NGO組織（Memoria Abierta）擁有這530小時的數位化錄影檔案。我們和開放記憶組織的團隊碰面，討論合作方案後，便開始將這些資料視覺化⋯⋯《阿根廷正義審判》是第一部以軍政府審判的文史資料為主題的影片，這場審判是阿根廷追求人權與正義的關鍵，因此相關資料對人權與歷史極其重要。」', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-18 00:00:00', '2025-04-18 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/18《阿根廷正義審判》', `description`='1985年春天，布宜諾斯艾利斯，一場史無前例的世紀審判浩蕩展開。民選政府追訴九名軍政府獨裁時期最位高權重的軍官，包含惡名昭彰的前獨裁者魏德拉，試圖為「骯髒戰爭」期間的受難者伸張遲來的正義。本片重新梳理長達530小時的法庭影像，不僅記錄下拉丁美洲史上最為關鍵的轉型正義時刻，也讓「永不再犯」（Never Again）的意義在現下時刻更顯擲地有聲。\r\n\r\n烏里賽斯．德拉歐丹：「這場審判總共歷經90天，全程由公共電視台用兩台磁帶攝影機錄下。從2013年起，我們開始尋找和取得這530小時的審判影像，希望能製作成一部紀錄片，一方面描述其中發生的事，另一方面訴說阿根廷經歷恐怖政治和日後尋求正義的過程。\r\n\r\n但光是找到錄影資料就相當不易。負責錄影的公共電視台擔心受到政治報復，因此拒絕與我有任何形式的合作。負責收藏錄影帶的阿根廷國家文物典藏館，則以避免不便為由，建議我到同樣擁有錄影複本的西班牙薩拉曼卡大學去找。即使審判已經過了30年，基層公務員還是會害怕、不敢承擔風險，這實在匪夷所思。\r\n\r\n到了2019年，我透過Luisa Hairebedian基金會的朋友，得知「開放記憶」NGO組織（Memoria Abierta）擁有這530小時的數位化錄影檔案。我們和開放記憶組織的團隊碰面，討論合作方案後，便開始將這些資料視覺化⋯⋯《阿根廷正義審判》是第一部以軍政府審判的文史資料為主題的影片，這場審判是阿根廷追求人權與正義的關鍵，因此相關資料對人權與歷史極其重要。」', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-18 00:00:00', `end_date`='2025-04-18 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ab26b3242b74a3af8c', '【2025 TIDF巡迴展 高雄場｜免費特映】4/18《記憶抹煞》', '抹煞記憶是比死刑更殘酷的懲罰，它否定存在、取消經驗。被篡改的歷史，如何成為獨裁者的治理工具，或反之作為人民抵抗霸權的武器？本片從網路蒐集眾多檔案影像，如廣島核爆、屠殺惡行、太空競賽、奧運比拚、鄧麗君明星魅力等，從政宣片、流行文化到成人情色影像，將因著建國大業、科技發展而被合理化的暴行並置提請，對不義的冷戰歷史提出犀利批判。\r\n\r\n敦斯卡．彭西迪佛拉高：「有些事情被巧妙地騙過去了。許多眾所周知的敘事裡，字裡行間藏著不曾被發覺、目睹的祕密，即人類每日重複的就是自相殘殺。雖然他們會為此感到悲傷痛苦，但從來沒有停止過，一天也沒有。『戰爭已然結束』只是另一種政宣口號，殺戮沒有止息過，它持續並麻木地增長。」', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-18 00:00:00', '2025-04-18 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/18《記憶抹煞》', `description`='抹煞記憶是比死刑更殘酷的懲罰，它否定存在、取消經驗。被篡改的歷史，如何成為獨裁者的治理工具，或反之作為人民抵抗霸權的武器？本片從網路蒐集眾多檔案影像，如廣島核爆、屠殺惡行、太空競賽、奧運比拚、鄧麗君明星魅力等，從政宣片、流行文化到成人情色影像，將因著建國大業、科技發展而被合理化的暴行並置提請，對不義的冷戰歷史提出犀利批判。\r\n\r\n敦斯卡．彭西迪佛拉高：「有些事情被巧妙地騙過去了。許多眾所周知的敘事裡，字裡行間藏著不曾被發覺、目睹的祕密，即人類每日重複的就是自相殘殺。雖然他們會為此感到悲傷痛苦，但從來沒有停止過，一天也沒有。『戰爭已然結束』只是另一種政宣口號，殺戮沒有止息過，它持續並麻木地增長。」', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-18 00:00:00', `end_date`='2025-04-18 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ab26b3242b74a3af8d', '【2025 TIDF巡迴展 高雄場｜免費特映】4/19《沉洞》', '在墨西哥猶加敦半島北部，有數以千計被稱作「天然井」（Cenote）的水下洞穴，古馬雅人視之為連接今生與死後世界的甬道，於此舉辦祭祀儀典，將人丟入洞口，向雨神獻祭。影片視角隨鏡頭在水色光影中浮沉潛行、穿梭今昔。幽冥與光亮之間，吟唱口述與影像並行，迷失靈魂的喃喃獨語交錯著現世居民的傳聞記憶，復現屬於沉洞及此地人們的歷史記憶。\r\n\r\n', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/19《沉洞》', `description`='在墨西哥猶加敦半島北部，有數以千計被稱作「天然井」（Cenote）的水下洞穴，古馬雅人視之為連接今生與死後世界的甬道，於此舉辦祭祀儀典，將人丟入洞口，向雨神獻祭。影片視角隨鏡頭在水色光影中浮沉潛行、穿梭今昔。幽冥與光亮之間，吟唱口述與影像並行，迷失靈魂的喃喃獨語交錯著現世居民的傳聞記憶，復現屬於沉洞及此地人們的歷史記憶。\r\n\r\n', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ab26b3242b74a3af8e', '【2025 TIDF巡迴展 高雄場｜免費特映】4/19《鑛》', '先是記錄礦坑外的環境，接著尾隨工人進入波士尼亞的礦坑中。攝影機成為全然的觀察者，被各種物質物件、空間環境、身體勞動所深深吸引，挖掘聲轟答答不絕於耳，進入一趟全然黑暗的地底世界之旅，當再回到地層表面上時，已完成一件關於凝視的思考儀式。\r\n\r\n小田香：「他們不被看見，而我們知道一切之所以能運作是因為他們冒著生命危險，在地底開採煤礦，但我們並未在日常生活中關注這一點。我的影片是一個契機，讓人們感受地底的生活，提醒自己生活中的電力來自何處，這算是我對這些礦工和礦願意讓我隨著他們拍攝的一點回應。」', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/19《鑛》', `description`='先是記錄礦坑外的環境，接著尾隨工人進入波士尼亞的礦坑中。攝影機成為全然的觀察者，被各種物質物件、空間環境、身體勞動所深深吸引，挖掘聲轟答答不絕於耳，進入一趟全然黑暗的地底世界之旅，當再回到地層表面上時，已完成一件關於凝視的思考儀式。\r\n\r\n小田香：「他們不被看見，而我們知道一切之所以能運作是因為他們冒著生命危險，在地底開採煤礦，但我們並未在日常生活中關注這一點。我的影片是一個契機，讓人們感受地底的生活，提醒自己生活中的電力來自何處，這算是我對這些礦工和礦願意讓我隨著他們拍攝的一點回應。」', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ab26b3242b74a3af8f', '【2025 TIDF巡迴展 高雄場｜免費特映】4/19《紀念．陳達》+《王船祭典》', '《紀念．陳達》Homage to Chen Da\r\n\r\n民俗採集與素人藝術家是張照堂紀錄片中最重要的主題之一。1970年代，張照堂陸續拍攝月琴音樂家陳達。本片拼貼了陳達於1972年屏東恆春、1977年台北稻草人西餐廳，以及同年在台北關渡河岸的彈唱表演。陳達的即興吟唱總有幾分勸世意味，攝影鏡頭也關注著他的生命狀態，片尾將多張陳達的照片進行交叉並置，向已逝的藝術家致敬。\r\n\r\n《王船祭典》The Boat-Burning Festival\r\n\r\n1970年代，張照堂於中視的「六十分鐘」紀實報導節目中擔任編導、攝影等工作。影片側拍台南蘇厝村燒王船祭典的過程，但沒有收錄任何現場聲響，僅搭配音樂家麥克・歐菲爾德的前衛搖滾民謠〈Ommadawn〉作為配樂，迸發出儀式的神聖性與神秘性，以及信眾的狂喜，不僅在電視上前所未見，也被認為開展了台灣實驗和詩意紀錄片的未來性。\r\n\r\n張照堂：「本影片不是講述一場民俗遊行的紀錄報告，而是建構一場地方村民與信仰、神靈互動糾纏的朝聖旅程。台灣的祭典文化總是吵雜零亂，然後說它有『生命力』。換個角度看，使它單純些，凝聚其中的熱情與執狂，將它演化成一場歡愉、悲壯的音像祭典，便是本片小小的期求。」', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/19《紀念．陳達》+《王船祭典》', `description`='《紀念．陳達》Homage to Chen Da\r\n\r\n民俗採集與素人藝術家是張照堂紀錄片中最重要的主題之一。1970年代，張照堂陸續拍攝月琴音樂家陳達。本片拼貼了陳達於1972年屏東恆春、1977年台北稻草人西餐廳，以及同年在台北關渡河岸的彈唱表演。陳達的即興吟唱總有幾分勸世意味，攝影鏡頭也關注著他的生命狀態，片尾將多張陳達的照片進行交叉並置，向已逝的藝術家致敬。\r\n\r\n《王船祭典》The Boat-Burning Festival\r\n\r\n1970年代，張照堂於中視的「六十分鐘」紀實報導節目中擔任編導、攝影等工作。影片側拍台南蘇厝村燒王船祭典的過程，但沒有收錄任何現場聲響，僅搭配音樂家麥克・歐菲爾德的前衛搖滾民謠〈Ommadawn〉作為配樂，迸發出儀式的神聖性與神秘性，以及信眾的狂喜，不僅在電視上前所未見，也被認為開展了台灣實驗和詩意紀錄片的未來性。\r\n\r\n張照堂：「本影片不是講述一場民俗遊行的紀錄報告，而是建構一場地方村民與信仰、神靈互動糾纏的朝聖旅程。台灣的祭典文化總是吵雜零亂，然後說它有『生命力』。換個角度看，使它單純些，凝聚其中的熱情與執狂，將它演化成一場歡愉、悲壯的音像祭典，便是本片小小的期求。」', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ab26b3242b74a3af90', '【2025 TIDF巡迴展 高雄場｜免費特映】4/20《GAMA》', '1945年4月1日，美軍登陸沖繩島，慘烈戰爭就此展開，日方有超過十萬人戰死或被俘，部分平民躲藏在洞窟之中，但被錯誤告知若投降會被美軍屠殺或拷打，間接引發集體自殺。影片隨著戰後出生的導遊先生進入洞窟，以獨白之姿講述前人傳承的戰爭記憶，神祕女子在一旁聆聽觀察，召喚著銘刻在地下景觀中的苦難歷史。\r\n\r\n小田香：「《GAMA》從頭到尾都在沖繩拍攝，但我最初之所以能製作這部電影，很大程度要歸功於與大阪豐中文化藝術中心的合作。當我在豐中研究地下場域時陷入困境，卻也得知豐中和沖繩之間存在著關聯性，其後我的研究便開始轉向沖繩的地下場域，並潛入其中。我對石灰岩洞穴一無所知，但在《GAMA》中出現的松永光男向我講述了他所傳承的洞窟記憶。\r\n\r\n在拍攝接近尾聲時，他說：『我是戰後出生的一代，我是松永光男。』聽到這句話時，我莫名感到糾結。這一切沉澱之後，它在我的身體中迴盪，彷彿在指引我這部作品應該走往的方向。這些記憶傳承給了他，而我們可以通過這部電影觀察到這些傳承記憶的一部分，並得以用這部作品的形式留存下來。我認為這個過程本身就是《GAMA》的內容。」〈山形國際紀錄片影展特刊〉，2023。', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/20《GAMA》', `description`='1945年4月1日，美軍登陸沖繩島，慘烈戰爭就此展開，日方有超過十萬人戰死或被俘，部分平民躲藏在洞窟之中，但被錯誤告知若投降會被美軍屠殺或拷打，間接引發集體自殺。影片隨著戰後出生的導遊先生進入洞窟，以獨白之姿講述前人傳承的戰爭記憶，神祕女子在一旁聆聽觀察，召喚著銘刻在地下景觀中的苦難歷史。\r\n\r\n小田香：「《GAMA》從頭到尾都在沖繩拍攝，但我最初之所以能製作這部電影，很大程度要歸功於與大阪豐中文化藝術中心的合作。當我在豐中研究地下場域時陷入困境，卻也得知豐中和沖繩之間存在著關聯性，其後我的研究便開始轉向沖繩的地下場域，並潛入其中。我對石灰岩洞穴一無所知，但在《GAMA》中出現的松永光男向我講述了他所傳承的洞窟記憶。\r\n\r\n在拍攝接近尾聲時，他說：『我是戰後出生的一代，我是松永光男。』聽到這句話時，我莫名感到糾結。這一切沉澱之後，它在我的身體中迴盪，彷彿在指引我這部作品應該走往的方向。這些記憶傳承給了他，而我們可以通過這部電影觀察到這些傳承記憶的一部分，並得以用這部作品的形式留存下來。我認為這個過程本身就是《GAMA》的內容。」〈山形國際紀錄片影展特刊〉，2023。', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ab26b3242b74a3af91', '【2025 TIDF巡迴展 高雄場｜免費特映】4/20《平行世界》', '繼2007年《雲的那端》問世後，身兼母親的導演繼續長達12年的拍攝，以影像日記、視訊影像，記錄患有亞斯伯格症台法混血女兒Elodie的成長歷程，也透過Elodie的畫作和黏土作品，一窺她的奇想世界。影片分為數條軸線，在台、法兩地時空交錯跳躍，凝視這段母女的情感糾結，母親陪伴女兒追尋自我與尋覓出路的過程，宛如一封母親寫給女兒的情書。\r\n\r\n蕭美玲：「Elodie出生後，我成為了母親，這個新的身分促使我思考文化、身分、認同和國界，因而拍攝《雲的那端》。隨著Elodie長大，開啟我另一段由外而內的探索，一個人如何與外部世界建立聯繫，解讀生命的密碼。\r\n\r\nElodie患有亞斯伯格症，有著書寫障礙，卻具有繪畫方面的天分。身為母親，我想讓我的孩子掌握在社會上生存所需的技能；但同時我也試著思考人之所以為人的命題，試著瞭解大腦、心智和行為的複雜聯結，並看到了一個人的創造力，如何在社會化的學習中被逐步地裁切、完竣削足適履的工程。然而所謂的『正常』與否，不過是多數人和少數人的比例問題而已。\r\n\r\n15歲時Elodie回到她父親的國度——法國，展開新階段的生命旅程。我接替她父親『視訊爸爸』的身分成為『視訊媽媽』，過去十多年間拍攝的影像成為我反思生活的來源。十多年來我必須將自己的情緒凝結，持續走在鋼絲上，藉由紀錄片的拍攝作為我生命的出口，檢視一個特殊兒母親的心路，而這些生命的旅程將成為我緊緊擁抱的記憶。\r\n\r\n特殊的孩子是上帝特別的禮物，身為孩子的母親，期待轉換這份生命的功課，透過文字、圖畫、影像的形式，作為一種生命的分享和自我的療癒，化作對孩子最深厚的愛與祝福。」', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/20《平行世界》', `description`='繼2007年《雲的那端》問世後，身兼母親的導演繼續長達12年的拍攝，以影像日記、視訊影像，記錄患有亞斯伯格症台法混血女兒Elodie的成長歷程，也透過Elodie的畫作和黏土作品，一窺她的奇想世界。影片分為數條軸線，在台、法兩地時空交錯跳躍，凝視這段母女的情感糾結，母親陪伴女兒追尋自我與尋覓出路的過程，宛如一封母親寫給女兒的情書。\r\n\r\n蕭美玲：「Elodie出生後，我成為了母親，這個新的身分促使我思考文化、身分、認同和國界，因而拍攝《雲的那端》。隨著Elodie長大，開啟我另一段由外而內的探索，一個人如何與外部世界建立聯繫，解讀生命的密碼。\r\n\r\nElodie患有亞斯伯格症，有著書寫障礙，卻具有繪畫方面的天分。身為母親，我想讓我的孩子掌握在社會上生存所需的技能；但同時我也試著思考人之所以為人的命題，試著瞭解大腦、心智和行為的複雜聯結，並看到了一個人的創造力，如何在社會化的學習中被逐步地裁切、完竣削足適履的工程。然而所謂的『正常』與否，不過是多數人和少數人的比例問題而已。\r\n\r\n15歲時Elodie回到她父親的國度——法國，展開新階段的生命旅程。我接替她父親『視訊爸爸』的身分成為『視訊媽媽』，過去十多年間拍攝的影像成為我反思生活的來源。十多年來我必須將自己的情緒凝結，持續走在鋼絲上，藉由紀錄片的拍攝作為我生命的出口，檢視一個特殊兒母親的心路，而這些生命的旅程將成為我緊緊擁抱的記憶。\r\n\r\n特殊的孩子是上帝特別的禮物，身為孩子的母親，期待轉換這份生命的功課，透過文字、圖畫、影像的形式，作為一種生命的分享和自我的療癒，化作對孩子最深厚的愛與祝福。」', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ab26b3242b74a3af92', '【2025 TIDF巡迴展 高雄場｜免費特映】4/22《服刑母親》', '烏克蘭這座女子監獄，允許懷孕的受刑母親生子育嬰，在監管下享天倫之樂。此規定亦有限制，當嬰孩滿三歲，若母親未出獄，孩子無人領養，將移送孤兒院。列莎因殺人判刑七年，如無減刑，母子分離就在眼前。導演以107位服刑母親訪談為底，混合專業演員與真實獄囚、獄警，著重聆聽與觀察，再現獨特封閉環境。\r\n\r\n彼得・克雷克斯：「我希望這部電影傳遞出受刑母親們的真實集體見證，不僅透過她們與女獄警的對話，也透過那些沈默的場面，例如當孩子被帶走後，她們絕望地完成生日蛋糕裝飾時的孤獨感；或是當她們短暫忘記身處監獄時，所閃現的片刻快樂。視覺上，這些場面處理得幾乎像是一張照片，像是針對一個獨立時空的一段記憶。我相信，是好奇心決定了我怎麼處理這群女性關係。我沒有要求她們做任何事，我沒有命令她們。我只是觀察與聆聽，看她們願意分享什麼給我，我再把這些轉譯成這部片。」', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-22 00:00:00', '2025-04-22 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/22《服刑母親》', `description`='烏克蘭這座女子監獄，允許懷孕的受刑母親生子育嬰，在監管下享天倫之樂。此規定亦有限制，當嬰孩滿三歲，若母親未出獄，孩子無人領養，將移送孤兒院。列莎因殺人判刑七年，如無減刑，母子分離就在眼前。導演以107位服刑母親訪談為底，混合專業演員與真實獄囚、獄警，著重聆聽與觀察，再現獨特封閉環境。\r\n\r\n彼得・克雷克斯：「我希望這部電影傳遞出受刑母親們的真實集體見證，不僅透過她們與女獄警的對話，也透過那些沈默的場面，例如當孩子被帶走後，她們絕望地完成生日蛋糕裝飾時的孤獨感；或是當她們短暫忘記身處監獄時，所閃現的片刻快樂。視覺上，這些場面處理得幾乎像是一張照片，像是針對一個獨立時空的一段記憶。我相信，是好奇心決定了我怎麼處理這群女性關係。我沒有要求她們做任何事，我沒有命令她們。我只是觀察與聆聽，看她們願意分享什麼給我，我再把這些轉譯成這部片。」', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-22 00:00:00', `end_date`='2025-04-22 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ab26b3242b74a3af93', '【2025 TIDF巡迴展 高雄場｜免費特映】4/23《星空之下》', '12年前荷蘭導演復訪父母的印尼原鄉，也開啟對一個貧民家庭的漫長紀錄。從《黎明將至》、《月亮的形狀》再到《星空之下》，三部曲走到最終章，導演繼續以詩意直覺的生猛運鏡，凝望在社會劇變下喘息的三代同堂。以微觀小家庭折射世代隔閡、宗教衝突與貧富差距。時而詼諧熱烈，時而沉靜憂傷，散發迷人人文光芒。\r\n\r\n李奧納多・瑞特・亨瑞奇：「我在拍攝《星空之下》時採用跟前兩部片一樣的拍法，亦即我獨創的『單攝電影技法』。因為我和我的主要拍攝者們非常親近，我等於身處每件事情的中心，可以拍下事情的全盤面貌。我選擇這個拍攝方式是了解到身為觀察者，我也是我所觀察的一部分。作為一個人，我不是透過一系列斷裂的鏡頭來感知現實，而是透過一個持續性的事件，我也正是以這個方式在拍電影。」', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-23 00:00:00', '2025-04-23 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/23《星空之下》', `description`='12年前荷蘭導演復訪父母的印尼原鄉，也開啟對一個貧民家庭的漫長紀錄。從《黎明將至》、《月亮的形狀》再到《星空之下》，三部曲走到最終章，導演繼續以詩意直覺的生猛運鏡，凝望在社會劇變下喘息的三代同堂。以微觀小家庭折射世代隔閡、宗教衝突與貧富差距。時而詼諧熱烈，時而沉靜憂傷，散發迷人人文光芒。\r\n\r\n李奧納多・瑞特・亨瑞奇：「我在拍攝《星空之下》時採用跟前兩部片一樣的拍法，亦即我獨創的『單攝電影技法』。因為我和我的主要拍攝者們非常親近，我等於身處每件事情的中心，可以拍下事情的全盤面貌。我選擇這個拍攝方式是了解到身為觀察者，我也是我所觀察的一部分。作為一個人，我不是透過一系列斷裂的鏡頭來感知現實，而是透過一個持續性的事件，我也正是以這個方式在拍電影。」', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-23 00:00:00', `end_date`='2025-04-23 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3af94', '【2025 TIDF巡迴展 高雄場｜免費特映】4/24《我們到底做了什麼？》', '1983年，24歲的姊姊出現思覺失調症狀，身為醫生的父親不願面對診斷結果與療程，選擇與母親居家照護無法外出求學、工作的姊姊，長達數十年。導演透過將近半輩子的時間跨度，記錄三位家庭成員的日常生活與衝突關係，寫下親情與病情相互糾葛中的生命日誌。\r\n\r\n藤野知明：「我的姊姊聰明，擅長畫畫，很有天賦。我覺得思覺失調不是精神疾病而是腦神經疾病，不需要覺得羞恥或是隱藏，因此無法解理我們的父母被視為專家，卻做出這樣的行為。因為沒有人可以交談，讓我現在了解真正的困頓是什麼感覺。我會開始記錄這些事實，是由於它們將會消失。這是一部看起來像家庭電影的無聊影片，但我拍它是因為我想避免同樣的事再發生。」', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-24 00:00:00', '2025-04-24 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/24《我們到底做了什麼？》', `description`='1983年，24歲的姊姊出現思覺失調症狀，身為醫生的父親不願面對診斷結果與療程，選擇與母親居家照護無法外出求學、工作的姊姊，長達數十年。導演透過將近半輩子的時間跨度，記錄三位家庭成員的日常生活與衝突關係，寫下親情與病情相互糾葛中的生命日誌。\r\n\r\n藤野知明：「我的姊姊聰明，擅長畫畫，很有天賦。我覺得思覺失調不是精神疾病而是腦神經疾病，不需要覺得羞恥或是隱藏，因此無法解理我們的父母被視為專家，卻做出這樣的行為。因為沒有人可以交談，讓我現在了解真正的困頓是什麼感覺。我會開始記錄這些事實，是由於它們將會消失。這是一部看起來像家庭電影的無聊影片，但我拍它是因為我想避免同樣的事再發生。」', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-24 00:00:00', `end_date`='2025-04-24 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3af95', '【2025 TIDF巡迴展 高雄場｜免費特映】4/25《烹煮歷史》', '六場戰爭、6000萬條人命，背後有何鮮為人知的關鍵因素？不談軍火談軍伙，士兵吃不飽怎打仗！以別出心裁的角度，擺上十道食譜，從二戰到九〇年代車臣戰爭，從法國、巴爾幹半島到俄羅斯，尋訪多名軍廚、伙房兵，甚至獨裁者御用名廚，幽默而犀利地叩問歷史。國族大旗當前，美味能否超越政治？片名雙關，從廚事一窺天下事。\r\n\r\n彼得・克雷克斯：「如果有人寫這是一部和平主義電影，這不是真的。如果有人寫這是一部歌頌軍隊的電影，這也不是真的。有這麼多種不同情況，我好奇人們會怎麼去解決。我會問他們同樣的問題，卻總是得到不同答案。當你是獨裁者軍隊的一員，有時你必須作個和平主義者，但有時你得拿起槍，為你的祖國戰鬥。」', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-25 00:00:00', '2025-04-25 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/25《烹煮歷史》', `description`='六場戰爭、6000萬條人命，背後有何鮮為人知的關鍵因素？不談軍火談軍伙，士兵吃不飽怎打仗！以別出心裁的角度，擺上十道食譜，從二戰到九〇年代車臣戰爭，從法國、巴爾幹半島到俄羅斯，尋訪多名軍廚、伙房兵，甚至獨裁者御用名廚，幽默而犀利地叩問歷史。國族大旗當前，美味能否超越政治？片名雙關，從廚事一窺天下事。\r\n\r\n彼得・克雷克斯：「如果有人寫這是一部和平主義電影，這不是真的。如果有人寫這是一部歌頌軍隊的電影，這也不是真的。有這麼多種不同情況，我好奇人們會怎麼去解決。我會問他們同樣的問題，卻總是得到不同答案。當你是獨裁者軍隊的一員，有時你必須作個和平主義者，但有時你得拿起槍，為你的祖國戰鬥。」', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-25 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3af96', '【2025 TIDF巡迴展 高雄場｜免費特映】4/26《鑽石水族世界》', '蝦農小杜哥憑著近20年的養殖經驗，從台灣隻身到緬甸打拼，沒想到迎來眼前的是白粉、槍枝和語言文化的隔閡。懷著養蝦夢的緬華混血女孩小蘇，與緬籍先生結婚後，想在當地復興家傳沒落的蝦場。當小杜哥與小蘇相遇，兩人決定攜手挖池養蝦，建造「鑽石水族世界」。歷時五年拍攝製作，記錄蝦場裡的人性轉折與事件衝突，恰如緬甸雨季，一波波降下。\r\n\r\n黃琇怡：「2015年，一趟為期三個月的湄公河旅行，開啟我對台灣人如何在東南亞生活與工作的好奇心。台灣就在中南半島的不遠處，但我們知道東京、紐約與巴黎的位置，卻不知道仰光在哪裡，這是我們對東南亞國家的陌生，而陌生有時會製造誤解與恐懼。在這趟拍攝旅程裡，我們透過片中來自不同文化背景的被攝者們，看見大家各自擁有不同的價值與信念。在追求成功的路上，更理解並尊重彼此的真實樣貌。」', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/26《鑽石水族世界》', `description`='蝦農小杜哥憑著近20年的養殖經驗，從台灣隻身到緬甸打拼，沒想到迎來眼前的是白粉、槍枝和語言文化的隔閡。懷著養蝦夢的緬華混血女孩小蘇，與緬籍先生結婚後，想在當地復興家傳沒落的蝦場。當小杜哥與小蘇相遇，兩人決定攜手挖池養蝦，建造「鑽石水族世界」。歷時五年拍攝製作，記錄蝦場裡的人性轉折與事件衝突，恰如緬甸雨季，一波波降下。\r\n\r\n黃琇怡：「2015年，一趟為期三個月的湄公河旅行，開啟我對台灣人如何在東南亞生活與工作的好奇心。台灣就在中南半島的不遠處，但我們知道東京、紐約與巴黎的位置，卻不知道仰光在哪裡，這是我們對東南亞國家的陌生，而陌生有時會製造誤解與恐懼。在這趟拍攝旅程裡，我們透過片中來自不同文化背景的被攝者們，看見大家各自擁有不同的價值與信念。在追求成功的路上，更理解並尊重彼此的真實樣貌。」', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3af97', '【2025 TIDF巡迴展 高雄場｜免費特映】4/27《由島至島》', '台灣在二戰期間是日本帝國的一部分。本片以此為主題，努力挖掘和重新整理台灣在二戰期間的隱藏記憶，探索在日本帝國內的台灣士兵、醫生與生活在東南亞的海外台灣人之經歷。全片從兒子對父親的提問開場，透過跨世代的對話、家書、日記和家庭成員之間的影片，探討台灣歷史記憶的複雜性，以及這一時期存在的各種身分。\r\n\r\n廖克發：「這部片無法以台灣、馬來西亞或新加坡任何地方的本位來思考，因為面對各地的事件，我認為都應以人本的態度去責問、思考和反省。片中我同樣問馬來西亞人，我們可以為了村子不被屠殺而獻出慰安婦嗎？我們要為了懲罰而公審慰安婦的家屬嗎？我們應該相信人性是脆弱的，所有人都會為了生存做出各種可怕的事。我不認為人可以覺得自己是正義的，所有邪惡的理由和正義的理由都很相似。訪問中，唯一必須而且直接傷害他人的是日本老兵，但我也選擇花些篇幅去陳述他們的痛楚。這不是責怪他們可能做過的事，而是質問，人為什麼可以選擇沉默？我們不應該相信人性是本善的，或認為只有少數邪惡的人會造成無辜的人受害，因為這是大部分旁觀者合理化自己旁觀的理由。所以更適切地說，人總是隨時合理化自己自私的行為和記憶，我們應該提醒自己『謹慎』地當一個人。」', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-27 00:00:00', '2025-04-27 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/27《由島至島》', `description`='台灣在二戰期間是日本帝國的一部分。本片以此為主題，努力挖掘和重新整理台灣在二戰期間的隱藏記憶，探索在日本帝國內的台灣士兵、醫生與生活在東南亞的海外台灣人之經歷。全片從兒子對父親的提問開場，透過跨世代的對話、家書、日記和家庭成員之間的影片，探討台灣歷史記憶的複雜性，以及這一時期存在的各種身分。\r\n\r\n廖克發：「這部片無法以台灣、馬來西亞或新加坡任何地方的本位來思考，因為面對各地的事件，我認為都應以人本的態度去責問、思考和反省。片中我同樣問馬來西亞人，我們可以為了村子不被屠殺而獻出慰安婦嗎？我們要為了懲罰而公審慰安婦的家屬嗎？我們應該相信人性是脆弱的，所有人都會為了生存做出各種可怕的事。我不認為人可以覺得自己是正義的，所有邪惡的理由和正義的理由都很相似。訪問中，唯一必須而且直接傷害他人的是日本老兵，但我也選擇花些篇幅去陳述他們的痛楚。這不是責怪他們可能做過的事，而是質問，人為什麼可以選擇沉默？我們不應該相信人性是本善的，或認為只有少數邪惡的人會造成無辜的人受害，因為這是大部分旁觀者合理化自己旁觀的理由。所以更適切地說，人總是隨時合理化自己自私的行為和記憶，我們應該提醒自己『謹慎』地當一個人。」', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3af98', '【2025 TIDF巡迴展 高雄場｜免費特映】4/29《吟唱靈魂之歌》', '緬甸東部的撣邦雖擁有古老豐富的民謠傳統，但此地60多年來也飽受內戰之苦，產生不少流離失所的悲劇。影片以近似民族誌的目光，展現撣邦獨特的生活與信仰風貌，又以歌聲為絲線，遙遙串起情感與生死的紋理。集體記憶揮之不去的傷口，在一代又一代的傳唱下，傳達無聲大地的感傷，與人民身處苦難中的昇華。\r\n\r\n賽諾康：「在我們國家，人們相信如果有人經歷可怕嚇人的事，守護靈便會從那個人身上跑走，此人將再也無法做夢，必須要把靈魂召喚回來，才能復原。《吟唱靈魂之歌》不只是一位母親在悲泣哭訴她消逝的孩子，同時也是身為電影導演的我在喚回自己的靈魂。」', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-29 00:00:00', '2025-04-29 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/29《吟唱靈魂之歌》', `description`='緬甸東部的撣邦雖擁有古老豐富的民謠傳統，但此地60多年來也飽受內戰之苦，產生不少流離失所的悲劇。影片以近似民族誌的目光，展現撣邦獨特的生活與信仰風貌，又以歌聲為絲線，遙遙串起情感與生死的紋理。集體記憶揮之不去的傷口，在一代又一代的傳唱下，傳達無聲大地的感傷，與人民身處苦難中的昇華。\r\n\r\n賽諾康：「在我們國家，人們相信如果有人經歷可怕嚇人的事，守護靈便會從那個人身上跑走，此人將再也無法做夢，必須要把靈魂召喚回來，才能復原。《吟唱靈魂之歌》不只是一位母親在悲泣哭訴她消逝的孩子，同時也是身為電影導演的我在喚回自己的靈魂。」', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-29 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3af99', '【2025 TIDF巡迴展 高雄場｜免費特映】4/30《沒有她們的星球》', '1979年，伊朗革命推翻君主制，建立共和國。但革命未必帶來全好的局面：伊朗女性自此被迫戴上頭巾。同年3月8日，導演出生，伊朗女性亦發動一場女性運動。然而運動失敗，導演從此過著兩個平行世界的生活，奔放與拘束，直到40多年後女性運動再起⋯⋯。導演在購藏的檔案影像中看見自由的過去，交織個人影像日記，揭露頭巾之下的女性生活與權利。\r\n\r\n法拉娜茲．沙里菲：「當我們與他人分享記憶，記憶就會從私領域走向公眾。為了抵禦遺忘，《沒有她們的星球》緊密交織著這些記憶。在一個權力結構致力於塑造歷史，以掩藏重要的、大眾的部分記憶之時代，分享個人細節與微型敘事變得至關重要。」', '國家電影及視聽文化中心', '高雄市鹽埕區4鄰河西路10號', '2025-04-30 00:00:00', '2025-04-30 00:00:00', '高雄市電影館', 22.622671, 120.289122, '無資料', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025 TIDF巡迴展 高雄場｜免費特映】4/30《沒有她們的星球》', `description`='1979年，伊朗革命推翻君主制，建立共和國。但革命未必帶來全好的局面：伊朗女性自此被迫戴上頭巾。同年3月8日，導演出生，伊朗女性亦發動一場女性運動。然而運動失敗，導演從此過著兩個平行世界的生活，奔放與拘束，直到40多年後女性運動再起⋯⋯。導演在購藏的檔案影像中看見自由的過去，交織個人影像日記，揭露頭巾之下的女性生活與權利。\r\n\r\n法拉娜茲．沙里菲：「當我們與他人分享記憶，記憶就會從私領域走向公眾。為了抵禦遺忘，《沒有她們的星球》緊密交織著這些記憶。在一個權力結構致力於塑造歷史，以掩藏重要的、大眾的部分記憶之時代，分享個人細節與微型敘事變得至關重要。」', `organizer`='國家電影及視聽文化中心', `address`='高雄市鹽埕區4鄰河西路10號', `start_date`='2025-04-30 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市電影館', `latitude`=22.622671, `longitude`=120.289122, `ticket_price`='無資料', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3af9a', '『四月』好書推薦主題書展', '煩惱如蕈菇般不斷滋生，在低谷中期望被愛、被接納\r\n擁抱每一個不完美，認識最真實的自己\r\n你。想成為什麼樣的人呢?\r\n\r\n展出書目：過得更好，難道只是一句自我安慰的口頭禪\r\n　　我們都在得過且過中載浮載沉\r\n　　自欺欺人，卻又在這場生存遊戲中沉淪\r\n　　想要好好生活，卻總是被生活拉扯的精疲力盡\r\n　　以為找一份優渥的工作，才能過上優越的人生\r\n    但現實總是不盡人意\r\n\r\n　　只想你從全世界的煩惱路過\r\n　　清空那些恐懼、煩悶、憋屈\r\n　　你的內心要為了承裝美好\r\n\r\n　　只想你從全世界的煩惱路過\r\n　　找到一條通往美好人生的捷徑', '高雄市立圖書館總館', '高雄市田寮區17鄰崗安路71-1號', '2025-04-10 00:00:00', '2025-04-30 00:00:00', '高雄市立圖書館田寮分館', 22.8633474, 120.4011911, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='『四月』好書推薦主題書展', `description`='煩惱如蕈菇般不斷滋生，在低谷中期望被愛、被接納\r\n擁抱每一個不完美，認識最真實的自己\r\n你。想成為什麼樣的人呢?\r\n\r\n展出書目：過得更好，難道只是一句自我安慰的口頭禪\r\n　　我們都在得過且過中載浮載沉\r\n　　自欺欺人，卻又在這場生存遊戲中沉淪\r\n　　想要好好生活，卻總是被生活拉扯的精疲力盡\r\n　　以為找一份優渥的工作，才能過上優越的人生\r\n    但現實總是不盡人意\r\n\r\n　　只想你從全世界的煩惱路過\r\n　　清空那些恐懼、煩悶、憋屈\r\n　　你的內心要為了承裝美好\r\n\r\n　　只想你從全世界的煩惱路過\r\n　　找到一條通往美好人生的捷徑', `organizer`='高雄市立圖書館總館', `address`='高雄市田寮區17鄰崗安路71-1號', `start_date`='2025-04-10 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市立圖書館田寮分館', `latitude`=22.8633474, `longitude`=120.4011911, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3af9b', '泰國 泰美麗.泰美味.泰有趣--東南亞主題書展', '讀萬卷書，才好行萬里路。\r\n透過閱讀，認識「微笑國度」泰國的種種，從飲食.節慶.信仰.設計面了解泰國的風俗.禁忌，進入色彩繽紛.樂天知命的泰國文化，來一趟書中的泰國之旅！\r\n', '高雄市立圖書館總館', '高雄市彌陀區14鄰四維路一之一號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '高雄市立圖書館彌陀分館', 22.7832231, 120.2455033, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='泰國 泰美麗.泰美味.泰有趣--東南亞主題書展', `description`='讀萬卷書，才好行萬里路。\r\n透過閱讀，認識「微笑國度」泰國的種種，從飲食.節慶.信仰.設計面了解泰國的風俗.禁忌，進入色彩繽紛.樂天知命的泰國文化，來一趟書中的泰國之旅！\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市彌陀區14鄰四維路一之一號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市立圖書館彌陀分館', `latitude`=22.7832231, `longitude`=120.2455033, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3af9c', 'FUN心聽故事(右昌分館4月)', '目的：藉由生動活潑的說故事方式帶領兒童一起閱讀，讓兒童愛上閱讀，並養成閱讀的好習慣。\r\n對象：一般民眾。\r\n費用：無。 ', '高雄市立圖書館總館', '高雄市楠梓區17鄰藍昌路72號', '2025-04-06 00:00:00', '2025-04-27 00:00:00', '高雄市立圖書館右昌分館', 22.7152924, 120.2901717, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='FUN心聽故事(右昌分館4月)', `description`='目的：藉由生動活潑的說故事方式帶領兒童一起閱讀，讓兒童愛上閱讀，並養成閱讀的好習慣。\r\n對象：一般民眾。\r\n費用：無。 ', `organizer`='高雄市立圖書館總館', `address`='高雄市楠梓區17鄰藍昌路72號', `start_date`='2025-04-06 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='高雄市立圖書館右昌分館', `latitude`=22.7152924, `longitude`=120.2901717, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3af9d', '【解鎖故事盒】│臺語導覽', '藝術鑑賞、作品觀看，有各式各樣的方式。\r\n有人享受獨立於脈絡與資訊外的自由，全然面對原作，在物質線索和材質間找出藝術對話的可能。有人追求逼近藝術家的創作思路，相視作品的同時也期待盡可能地獲取相關的訊息和說明。亦有的人求索藝術作品的詮釋，連結自我生命經驗，探詢作品何以解讀。也有一種方式，是我們可以與專家學者們同行，看見聆聽其獨有的視野，感受認識其視覺經驗和心得，了解其破譯藝術的獨門方法。\r\n邀請您來打開《故事∙集：說說典藏》，聆聽導賞，與曾獲廣播金鐘藝術文化節目主持人獎項榮譽的廖新田教授解鎖故事盒！\r\n-\r\n【解鎖故事盒】（臺語導覽）\r\n日期時間：4/20（日）15:00-16:30\r\n講者：廖新田│國立臺灣藝術大學藝術管理與文化政策研究所教授（以《寶島美術館》榮獲第56屆廣播金鐘藝術文化節目主持人獎）\r\n報到地點：雕塑大廳（14:40開放報到）', '無資料', '高雄市鼓山區6鄰美術館路80號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '高雄市立美術館', 22.6566968, 120.2865511, '無資料', 'https://www.kmfa.gov.tw/OnlineApplyDetailC001200.aspx?Cond=8beab545-9c76-4eef-b12c-56edfe2f2984', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【解鎖故事盒】│臺語導覽', `description`='藝術鑑賞、作品觀看，有各式各樣的方式。\r\n有人享受獨立於脈絡與資訊外的自由，全然面對原作，在物質線索和材質間找出藝術對話的可能。有人追求逼近藝術家的創作思路，相視作品的同時也期待盡可能地獲取相關的訊息和說明。亦有的人求索藝術作品的詮釋，連結自我生命經驗，探詢作品何以解讀。也有一種方式，是我們可以與專家學者們同行，看見聆聽其獨有的視野，感受認識其視覺經驗和心得，了解其破譯藝術的獨門方法。\r\n邀請您來打開《故事∙集：說說典藏》，聆聽導賞，與曾獲廣播金鐘藝術文化節目主持人獎項榮譽的廖新田教授解鎖故事盒！\r\n-\r\n【解鎖故事盒】（臺語導覽）\r\n日期時間：4/20（日）15:00-16:30\r\n講者：廖新田│國立臺灣藝術大學藝術管理與文化政策研究所教授（以《寶島美術館》榮獲第56屆廣播金鐘藝術文化節目主持人獎）\r\n報到地點：雕塑大廳（14:40開放報到）', `organizer`='無資料', `address`='高雄市鼓山區6鄰美術館路80號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='高雄市立美術館', `latitude`=22.6566968, `longitude`=120.2865511, `ticket_price`='無資料', `source_url`='https://www.kmfa.gov.tw/OnlineApplyDetailC001200.aspx?Cond=8beab545-9c76-4eef-b12c-56edfe2f2984', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3af9e', '臺南市東區裕文圖書館- 文創藝術展  2025動漫·畫境', '誠摯邀請大家來參觀《動漫·畫境》師生聯展！這場展覽匯聚了來自南應大美術系與熱愛二次元動漫文化的崑山學生創作，呈現出多元豐富的藝術作品。通識課的妮妮老師帶領著一群充滿創意與熱情的學生，將他們的藝術夢想轉化為一幅幅作品，與觀眾共享他們的獨特視界。這次展覽不僅展示了學生們在藝術創作上的多樣性，也反映了他們對於動漫文化的深厚情感。無論是傳統藝術的表現還是現代動漫的元素，所有的作品都呈現了每位學生獨特的風格和無限的想像力。\r\n此次展覽不僅是一個視覺的盛宴，更是一場心靈的對話。每一幅作品都蘊含著創作者的心血與情感，邀請您一同走進他們的「畫境」，感受二次元與創意的化學反應。無論您是藝術愛好者或是動漫迷，希望都能在這場展覽中找到屬於自己最初的喜愛共鳴。\r\n我們期待您的光臨，與我們一同感受這場充滿創意與熱情的藝術之旅！', '無資料', '臺南市東區裕信路237號', '2025-03-26 00:00:00', '2025-05-25 00:00:00', '臺南市東區裕文圖書館', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市東區裕文圖書館- 文創藝術展  2025動漫·畫境', `description`='誠摯邀請大家來參觀《動漫·畫境》師生聯展！這場展覽匯聚了來自南應大美術系與熱愛二次元動漫文化的崑山學生創作，呈現出多元豐富的藝術作品。通識課的妮妮老師帶領著一群充滿創意與熱情的學生，將他們的藝術夢想轉化為一幅幅作品，與觀眾共享他們的獨特視界。這次展覽不僅展示了學生們在藝術創作上的多樣性，也反映了他們對於動漫文化的深厚情感。無論是傳統藝術的表現還是現代動漫的元素，所有的作品都呈現了每位學生獨特的風格和無限的想像力。\r\n此次展覽不僅是一個視覺的盛宴，更是一場心靈的對話。每一幅作品都蘊含著創作者的心血與情感，邀請您一同走進他們的「畫境」，感受二次元與創意的化學反應。無論您是藝術愛好者或是動漫迷，希望都能在這場展覽中找到屬於自己最初的喜愛共鳴。\r\n我們期待您的光臨，與我們一同感受這場充滿創意與熱情的藝術之旅！', `organizer`='無資料', `address`='臺南市東區裕信路237號', `start_date`='2025-03-26 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='臺南市東區裕文圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3af9f', '絕美海島大公開主題書展', '無論春夏秋冬何種季節，海島國家都是療癒身心的度假勝地，東南亞更有許多著名的島嶼，除了熱門的長灘島、峇里島，還有許多海島秘境，等大家去探索。\r\n', '高雄市立圖書館總館', '高雄市岡山區009鄰岡山南路42號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='絕美海島大公開主題書展', `description`='無論春夏秋冬何種季節，海島國家都是療癒身心的度假勝地，東南亞更有許多著名的島嶼，除了熱門的長灘島、峇里島，還有許多海島秘境，等大家去探索。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3afa0', '岡山文化中心分館114年4月fun心聽故事', '遲到理由繪本導讀:鬧鐘響過了一遍又一遍，終於叫醒了熟睡的小豬。\r\n可是，早就過了上學時間啦！已經遲到了！\r\n這下該怎麼辦？\r\n\r\n小豬飛快的跑到學校，卻在快到教室前的走廊停了下來。牠癱坐在走廊角落，忐忑的想過一個又一個理由──該學大象，跟老師說是因為擤鼻涕擤太久了嗎？還是跟鱷魚一樣，刷牙刷太久了？一幕幕的內心小劇場，在小豬的腦海裡演過一遍又一遍……\r\n可是這些都是別人用的理由啊。\r\n再想想、再想想……應該要用「自己的」理由才對！\r\n\r\n小豬的思考不斷的變化著，於是，從學別人的理由，變成想自己的理由；從把遲到的原因怪罪在爸爸媽媽為他準備太多鬧鐘和早餐上，變成自己迷路、為了撿回沿路掉落在路上的文具……小豬認真的想了一個又一個理由，卻透過圖畫呈現出另外一番爆笑逗趣的幻想；而就在想出理由，又不斷的自我否定、推翻前一個想法的過程中，小豬終於可以鼓起勇氣，敲了教室的門，結局卻出乎意料。\r\n到底，老師會相信哪一個理由呢？', '高雄市立圖書館總館', '高雄市岡山區009鄰岡山南路42號', '2025-04-12 00:00:00', '2025-04-26 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='岡山文化中心分館114年4月fun心聽故事', `description`='遲到理由繪本導讀:鬧鐘響過了一遍又一遍，終於叫醒了熟睡的小豬。\r\n可是，早就過了上學時間啦！已經遲到了！\r\n這下該怎麼辦？\r\n\r\n小豬飛快的跑到學校，卻在快到教室前的走廊停了下來。牠癱坐在走廊角落，忐忑的想過一個又一個理由──該學大象，跟老師說是因為擤鼻涕擤太久了嗎？還是跟鱷魚一樣，刷牙刷太久了？一幕幕的內心小劇場，在小豬的腦海裡演過一遍又一遍……\r\n可是這些都是別人用的理由啊。\r\n再想想、再想想……應該要用「自己的」理由才對！\r\n\r\n小豬的思考不斷的變化著，於是，從學別人的理由，變成想自己的理由；從把遲到的原因怪罪在爸爸媽媽為他準備太多鬧鐘和早餐上，變成自己迷路、為了撿回沿路掉落在路上的文具……小豬認真的想了一個又一個理由，卻透過圖畫呈現出另外一番爆笑逗趣的幻想；而就在想出理由，又不斷的自我否定、推翻前一個想法的過程中，小豬終於可以鼓起勇氣，敲了教室的門，結局卻出乎意料。\r\n到底，老師會相信哪一個理由呢？', `organizer`='高雄市立圖書館總館', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3afa1', '「穿越蟲洞的書信：致外島時光」馬祖軍旅書信徵集', '第三屆馬祖國際藝術島！連江縣政府及中華文化總會共同主辦的「穿越蟲洞的書信：致外島時光」馬祖軍旅書信徵集計畫正式啟動，不僅見證戰地軍旅的通信記憶，更將建立成馬祖書信數位檔案庫，詳情請洽徵件簡章：https://shorturl.at/1KUR4。\r\n\r\n　文化處說明，馬祖與臺灣本島相隔約211公里，戰地時期的通信主要依靠海運，往返本島的運輸艦平均十天才一班，遇到惡劣氣候更可能長達一個月無法通行，使每一封信件都彌足珍貴。在那段與親人遠隔重洋、音訊渺茫的時光裡，一封封信件成為支撐心靈的重要依靠，也記錄下那個年代獨有的生活節奏與情感紋理。\r\n\r\n　文化處指出，此計畫延續2022年「書信計畫」對軍郵歷史與書信文化的探索，今年進一步擴大徵集，目標為建構更完整的書信數位檔案庫，保存馬祖戰地通信的獨特歷史與深厚情感。透過數位典藏、馬祖國際藝術島藝術家的轉譯創作，再次連結歷史與當代、個人與集體、馬祖與臺灣，讓更多人了解這裏特殊的歷史和情感。\r\n\r\n　此次徵集對象為軍旅書信，即收信或寄信人應為馬祖服役軍人。徵集類型包括寄送之紙本書信、明信片、錄音帶之數位檔案及相關照片、影像，詳細徵件辦法可於馬祖國際藝術島官方網站或Facebook粉絲專頁閱覽。符合條件的投件者將獲得數位專屬感謝狀，並有機會於2025年馬祖國際藝術島節期間展出，如同意永久公開授權，所提供的資料將可納入「馬祖記憶庫」及「國家文化記憶庫」典藏。\r\n\r\n　馬祖戰地政務時期的通信體驗，是戰地史獨特的文化記憶，每一封跨越海峽的書信，不僅見證了歷史，也承載著深刻的文化情感。本次書信徵集不只是文件保存，更是一場關於記憶與傳承的行動，邀請共同參與，讓年輕世代得以觸碰那段凝鍊於等待與書寫的時光。', '連江縣政府', '連江縣全區域', '2025-04-10 00:00:00', '2025-05-31 00:00:00', '連江縣', '無資料', '無資料', '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「穿越蟲洞的書信：致外島時光」馬祖軍旅書信徵集', `description`='第三屆馬祖國際藝術島！連江縣政府及中華文化總會共同主辦的「穿越蟲洞的書信：致外島時光」馬祖軍旅書信徵集計畫正式啟動，不僅見證戰地軍旅的通信記憶，更將建立成馬祖書信數位檔案庫，詳情請洽徵件簡章：https://shorturl.at/1KUR4。\r\n\r\n　文化處說明，馬祖與臺灣本島相隔約211公里，戰地時期的通信主要依靠海運，往返本島的運輸艦平均十天才一班，遇到惡劣氣候更可能長達一個月無法通行，使每一封信件都彌足珍貴。在那段與親人遠隔重洋、音訊渺茫的時光裡，一封封信件成為支撐心靈的重要依靠，也記錄下那個年代獨有的生活節奏與情感紋理。\r\n\r\n　文化處指出，此計畫延續2022年「書信計畫」對軍郵歷史與書信文化的探索，今年進一步擴大徵集，目標為建構更完整的書信數位檔案庫，保存馬祖戰地通信的獨特歷史與深厚情感。透過數位典藏、馬祖國際藝術島藝術家的轉譯創作，再次連結歷史與當代、個人與集體、馬祖與臺灣，讓更多人了解這裏特殊的歷史和情感。\r\n\r\n　此次徵集對象為軍旅書信，即收信或寄信人應為馬祖服役軍人。徵集類型包括寄送之紙本書信、明信片、錄音帶之數位檔案及相關照片、影像，詳細徵件辦法可於馬祖國際藝術島官方網站或Facebook粉絲專頁閱覽。符合條件的投件者將獲得數位專屬感謝狀，並有機會於2025年馬祖國際藝術島節期間展出，如同意永久公開授權，所提供的資料將可納入「馬祖記憶庫」及「國家文化記憶庫」典藏。\r\n\r\n　馬祖戰地政務時期的通信體驗，是戰地史獨特的文化記憶，每一封跨越海峽的書信，不僅見證了歷史，也承載著深刻的文化情感。本次書信徵集不只是文件保存，更是一場關於記憶與傳承的行動，邀請共同參與，讓年輕世代得以觸碰那段凝鍊於等待與書寫的時光。', `organizer`='連江縣政府', `address`='連江縣全區域', `start_date`='2025-04-10 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='連江縣', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3afa3', 'Fun 心聽故事(寶珠分館四月)', '為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動志工，至寶珠分館說故事。運用本館館藏，以說演繪本故事。\r\n\r\n活動時間：週五10:00~11:00 週六10:00~11:00 週日15:00~16:00\r\n\r\n師資簡介：郭淑玲等(故事達人)\r\n活動對象：有興趣的小朋友，自由參加\r\n活動費用：免費', '高雄市立圖書館總館', '高雄市三民區002鄰大順二路468號', '2025-04-05 00:00:00', '2025-04-27 00:00:00', '高雄市立圖書館寶珠分館', 22.649382, 120.3249695, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Fun 心聽故事(寶珠分館四月)', `description`='為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動志工，至寶珠分館說故事。運用本館館藏，以說演繪本故事。\r\n\r\n活動時間：週五10:00~11:00 週六10:00~11:00 週日15:00~16:00\r\n\r\n師資簡介：郭淑玲等(故事達人)\r\n活動對象：有興趣的小朋友，自由參加\r\n活動費用：免費', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區002鄰大順二路468號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='高雄市立圖書館寶珠分館', `latitude`=22.649382, `longitude`=120.3249695, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3afa4', 'English Storytelling 英語故事快樂頌(四月)', '為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動志工，至寶珠分館說故事。運用本館館藏，以說演繪本故事。\r\n\r\n課程內容：故事是最棒的橋樑，使孩子與英文相遇相知。歡迎孩子們一同踏上英語故事的奇幻之旅，探索未知的廣大世界吧！\r\n\r\n活動時間：每週日10:30~11:30\r\n師資簡介：關翠萍等(英語故事達人)\r\n活動對象：有興趣的小朋友，自由參加\r\n活動費用：免費', '高雄市立圖書館總館', '高雄市三民區002鄰大順二路468號', '2025-04-06 00:00:00', '2025-04-27 00:00:00', '高雄市立圖書館寶珠分館', 22.649382, 120.3249695, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='English Storytelling 英語故事快樂頌(四月)', `description`='為推廣兒童閱讀風氣，高雄市立圖書館「書香推手」活動志工，至寶珠分館說故事。運用本館館藏，以說演繪本故事。\r\n\r\n課程內容：故事是最棒的橋樑，使孩子與英文相遇相知。歡迎孩子們一同踏上英語故事的奇幻之旅，探索未知的廣大世界吧！\r\n\r\n活動時間：每週日10:30~11:30\r\n師資簡介：關翠萍等(英語故事達人)\r\n活動對象：有興趣的小朋友，自由參加\r\n活動費用：免費', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區002鄰大順二路468號', `start_date`='2025-04-06 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='高雄市立圖書館寶珠分館', `latitude`=22.649382, `longitude`=120.3249695, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3afa5', '看卡通學美語 Cartoon Movie(四月)', '活動內容：寶珠分館「美國專區」每月播放一部好看卡通~歡迎家長與小朋友一同歡賞！卡通內容皆為英文發音中文字幕，歡迎家長與小朋友一起，快樂看卡通輕鬆學美語！\r\n\r\n卡通名稱：蜘蛛人：新宇宙 Spider-Man: Into The Spider-Verse\r\n活動時間：4月19日 14：00－16：00（依影片長度增減）\r\n※毋需報名，現場參加即可。\r\n費用：免費\r\n活動對象：有興趣之家長與小朋友', '高雄市立圖書館總館', '高雄市三民區002鄰大順二路468號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '高雄市立圖書館寶珠分館', 22.649382, 120.3249695, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='看卡通學美語 Cartoon Movie(四月)', `description`='活動內容：寶珠分館「美國專區」每月播放一部好看卡通~歡迎家長與小朋友一同歡賞！卡通內容皆為英文發音中文字幕，歡迎家長與小朋友一起，快樂看卡通輕鬆學美語！\r\n\r\n卡通名稱：蜘蛛人：新宇宙 Spider-Man: Into The Spider-Verse\r\n活動時間：4月19日 14：00－16：00（依影片長度增減）\r\n※毋需報名，現場參加即可。\r\n費用：免費\r\n活動對象：有興趣之家長與小朋友', `organizer`='高雄市立圖書館總館', `address`='高雄市三民區002鄰大順二路468號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='高雄市立圖書館寶珠分館', `latitude`=22.649382, `longitude`=120.3249695, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ac26b3242b74a3afa6', '人偶舞台音樂劇：灰姑娘', '劇本對於愛情與玻璃鞋的詮釋有別於原著，傳達了正向的價值觀，在回家路上，可以藉此教育孩子！\r\n〈一則希望與愛的經典童話〉\r\n傳達「正面樂觀，同理心待人」的觀念。遭遇困境時，也能無所畏懼，不向逆境低頭。最終一定能品嚐到甜美的人生果實！\r\n仙度瑞拉平時飽受後母與姊姊們欺凌；城堡舉辦盛大舞會，一位魔法奶奶將南瓜變成馬車，灰姑娘變成美麗的公主。十二點鐘聲響起！灰姑娘慌張逃出城堡但掉了一隻玻璃鞋…第二天，城堡的大臣帶著玻璃鞋來到仙度瑞拉的家…', '銀河谷音劇團', '嘉義市東區忠孝路275號', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '嘉義市政府文化局', 23.48170334, 120.4706244, '全票+400;全票+600;全票+800;全票+1000;全票+1200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='人偶舞台音樂劇：灰姑娘', `description`='劇本對於愛情與玻璃鞋的詮釋有別於原著，傳達了正向的價值觀，在回家路上，可以藉此教育孩子！\r\n〈一則希望與愛的經典童話〉\r\n傳達「正面樂觀，同理心待人」的觀念。遭遇困境時，也能無所畏懼，不向逆境低頭。最終一定能品嚐到甜美的人生果實！\r\n仙度瑞拉平時飽受後母與姊姊們欺凌；城堡舉辦盛大舞會，一位魔法奶奶將南瓜變成馬車，灰姑娘變成美麗的公主。十二點鐘聲響起！灰姑娘慌張逃出城堡但掉了一隻玻璃鞋…第二天，城堡的大臣帶著玻璃鞋來到仙度瑞拉的家…', `organizer`='銀河谷音劇團', `address`='嘉義市東區忠孝路275號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='嘉義市政府文化局', `latitude`=23.48170334, `longitude`=120.4706244, `ticket_price`='全票+400;全票+600;全票+800;全票+1000;全票+1200', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ad26b3242b74a3afa7', '2025 年嘉義室內合唱團音樂會：嘉義聲集—好室如慕', '嘉義室內合唱團自2000成立至今已即將邁入25年，這近四分之一世紀以來凝聚了一群優秀的音樂人，藉由溫馨、優質的練唱環境營造，歌唱水平提升以及曲目的不斷擴充，獲得了廣大愛樂者的肯定。\r\n\r\n「嘉義聲集—好室如慕」，邀請嘉義女聲合唱團以及由黃湘君老師指導的子團嘉義室內兒童合唱團一同合作帶來整場多元熱鬧卻又深刻的合唱饗宴，演出曲目語言多樣化，能夠聽到國內首屈一指且獲獎無數的嘉義女聲合唱團，以及童稚可愛的嘉義兒童合唱團同台獻藝，無論是傾慕、渴慕，還是追求冥冥之中驅動世間萬物的力量。「好室如慕」因而得名，好字可拆為女與子，代表的是嘉義女聲合唱團以及嘉義室內兒童合唱團，室則是嘉義室內合唱團，三個團體想要向聽眾分享心靈的渴慕，是以「好室如慕」。', '嘉義室內合唱團', '嘉義市東區忠孝路275號', '2025-04-27 00:00:00', '2025-04-27 00:00:00', '嘉義市政府文化局', 23.48170334, 120.4706244, '全票+200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 年嘉義室內合唱團音樂會：嘉義聲集—好室如慕', `description`='嘉義室內合唱團自2000成立至今已即將邁入25年，這近四分之一世紀以來凝聚了一群優秀的音樂人，藉由溫馨、優質的練唱環境營造，歌唱水平提升以及曲目的不斷擴充，獲得了廣大愛樂者的肯定。\r\n\r\n「嘉義聲集—好室如慕」，邀請嘉義女聲合唱團以及由黃湘君老師指導的子團嘉義室內兒童合唱團一同合作帶來整場多元熱鬧卻又深刻的合唱饗宴，演出曲目語言多樣化，能夠聽到國內首屈一指且獲獎無數的嘉義女聲合唱團，以及童稚可愛的嘉義兒童合唱團同台獻藝，無論是傾慕、渴慕，還是追求冥冥之中驅動世間萬物的力量。「好室如慕」因而得名，好字可拆為女與子，代表的是嘉義女聲合唱團以及嘉義室內兒童合唱團，室則是嘉義室內合唱團，三個團體想要向聽眾分享心靈的渴慕，是以「好室如慕」。', `organizer`='嘉義室內合唱團', `address`='嘉義市東區忠孝路275號', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='嘉義市政府文化局', `latitude`=23.48170334, `longitude`=120.4706244, `ticket_price`='全票+200', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ad26b3242b74a3afa8', '南新國小藝術才能班：南新采風 音樂饗讚', '南新國小藝才班每年舉辦的成果發表會總是充滿驚喜，令人期待。本次音樂會主要將呈現南新國小十多年來音樂教育的紮根上對孩子的影響。演出的曲目包括幻想曲、國風等，作品多來自當今活躍於民族樂器樂創作的作曲家，所創作的歌謠蘊藏豐富的民族精神和民族情感，具有與民眾共鳴的浸染力，能鼓勵、教育、慰藉著人們，當傳統歌謠走向賦有現代音樂曲風的旋律，更能凝聚不同世代的情感，並形成大家共同的意識。因此期盼能與聽眾來一場心靈的對話。', '嘉義市政府文化局', '嘉義市東區忠孝路275號', '2025-04-30 00:00:00', '2025-04-30 00:00:00', '嘉義市政府文化局', 23.48170334, 120.4706244, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南新國小藝術才能班：南新采風 音樂饗讚', `description`='南新國小藝才班每年舉辦的成果發表會總是充滿驚喜，令人期待。本次音樂會主要將呈現南新國小十多年來音樂教育的紮根上對孩子的影響。演出的曲目包括幻想曲、國風等，作品多來自當今活躍於民族樂器樂創作的作曲家，所創作的歌謠蘊藏豐富的民族精神和民族情感，具有與民眾共鳴的浸染力，能鼓勵、教育、慰藉著人們，當傳統歌謠走向賦有現代音樂曲風的旋律，更能凝聚不同世代的情感，並形成大家共同的意識。因此期盼能與聽眾來一場心靈的對話。', `organizer`='嘉義市政府文化局', `address`='嘉義市東區忠孝路275號', `start_date`='2025-04-30 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='嘉義市政府文化局', `latitude`=23.48170334, `longitude`=120.4706244, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ad26b3242b74a3afa9', '嘉義市崇文國民小學2025年音樂班Flying Music成果發表會', '此次教學成果展結合音樂班學生多元化的學習，節目內容豐富。有鋼琴四手聯彈、那一年的夏天音樂劇、太鼓與合唱的肢體律動、弦樂合奏、管樂合奏及管弦樂合奏等，充分展現活潑可愛的同學們一年來的學習成果。', '嘉義市政府文化局', '嘉義市東區忠孝路275號', '2025-04-23 00:00:00', '2025-04-23 00:00:00', '嘉義市政府文化局', 23.48170334, 120.4706244, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='嘉義市崇文國民小學2025年音樂班Flying Music成果發表會', `description`='此次教學成果展結合音樂班學生多元化的學習，節目內容豐富。有鋼琴四手聯彈、那一年的夏天音樂劇、太鼓與合唱的肢體律動、弦樂合奏、管樂合奏及管弦樂合奏等，充分展現活潑可愛的同學們一年來的學習成果。', `organizer`='嘉義市政府文化局', `address`='嘉義市東區忠孝路275號', `start_date`='2025-04-23 00:00:00', `end_date`='2025-04-23 00:00:00', `location`='嘉義市政府文化局', `latitude`=23.48170334, `longitude`=120.4706244, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ad26b3242b74a3afaa', '嘉義市崇文國民小學舞蹈藝才班成果發表會：桂冠精靈', '舞蹈是一種語言，舞蹈是一種藝術。舞蹈能展現身、心、靈的美，能表達豐富的意念與情感，更能傳遞文化的樣貌與內涵，期盼能藉由這一場視覺、聽覺與心靈交織而成的饗宴，一同感受舞蹈的美好，體驗身在其中的樂趣，共創生命中令人心動的新樂章。\r\n崇文國小舞蹈班－「桂冠精靈」成果發表會節目內容多彩多姿，有典雅可愛的芭蕾，創意豐富的現代舞作，更有融合傳統與創新的民族舞呈現舞台，帶領觀眾進入不同文化與風格交織的藝術世界。展開一場無與倫比的視覺盛宴。', '嘉義市政府文化局', '嘉義市東區忠孝路275號', '2025-04-22 00:00:00', '2025-04-22 00:00:00', '嘉義市政府文化局', 23.48170334, 120.4706244, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='嘉義市崇文國民小學舞蹈藝才班成果發表會：桂冠精靈', `description`='舞蹈是一種語言，舞蹈是一種藝術。舞蹈能展現身、心、靈的美，能表達豐富的意念與情感，更能傳遞文化的樣貌與內涵，期盼能藉由這一場視覺、聽覺與心靈交織而成的饗宴，一同感受舞蹈的美好，體驗身在其中的樂趣，共創生命中令人心動的新樂章。\r\n崇文國小舞蹈班－「桂冠精靈」成果發表會節目內容多彩多姿，有典雅可愛的芭蕾，創意豐富的現代舞作，更有融合傳統與創新的民族舞呈現舞台，帶領觀眾進入不同文化與風格交織的藝術世界。展開一場無與倫比的視覺盛宴。', `organizer`='嘉義市政府文化局', `address`='嘉義市東區忠孝路275號', `start_date`='2025-04-22 00:00:00', `end_date`='2025-04-22 00:00:00', `location`='嘉義市政府文化局', `latitude`=23.48170334, `longitude`=120.4706244, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ad26b3242b74a3afab', '次世代遊戲音樂LIVE：薩克斯風的數位探險', '本場音樂會將透過精心挑選的經典遊戲配樂，以薩克斯風重奏的獨特音色，帶領觀眾穿越時空，回顧電子遊戲時代的輝煌歲月，並探討數位時代下遊戲媒介的轉變與未來發展。演出將重現《Final Fantasy》系列的史詩級旋律，喚起《薩爾達傳說》那股充滿冒險精神的悸動，感受《魔物獵人》的激昂戰鬥氣息，並沉浸於《尼爾自動人形》所帶來的深邃哲思。這些遊戲音樂不僅是遊戲世界的靈魂，也是跨越時代、串聯不同世代玩家記憶的橋樑。', '嘉義市管樂團', '嘉義市東區忠孝路275號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '嘉義市政府文化局', 23.48170334, 120.4706244, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='次世代遊戲音樂LIVE：薩克斯風的數位探險', `description`='本場音樂會將透過精心挑選的經典遊戲配樂，以薩克斯風重奏的獨特音色，帶領觀眾穿越時空，回顧電子遊戲時代的輝煌歲月，並探討數位時代下遊戲媒介的轉變與未來發展。演出將重現《Final Fantasy》系列的史詩級旋律，喚起《薩爾達傳說》那股充滿冒險精神的悸動，感受《魔物獵人》的激昂戰鬥氣息，並沉浸於《尼爾自動人形》所帶來的深邃哲思。這些遊戲音樂不僅是遊戲世界的靈魂，也是跨越時代、串聯不同世代玩家記憶的橋樑。', `organizer`='嘉義市管樂團', `address`='嘉義市東區忠孝路275號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='嘉義市政府文化局', `latitude`=23.48170334, `longitude`=120.4706244, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f838ad26b3242b74a3afad', '狂美交響管樂團：《宮崎駿動畫配樂II》交響音樂會', '在狂美《宮崎駿動畫配樂》於「臺北國家音樂廳」完售封箱後，2025終於端出巔峰動人的續作。\r\n猶記當時，每一部宮崎駿動畫所傳遞的生命色彩和體悟。透由每一次的回放，總令人再三咀嚼故事背後其深意。穿梭在影像之後，有暖心〝配樂”相伴，縈繞在畫面與畫面間，牽引著靈魂與感官遨遊。\r\n再次回歸，必有新意！自大師筆下許多現象級動畫作品中，狂美精心揀選多部配樂章節，二次攜手導聆人楊小黎(官方中文版《魔女宅急便》、《心之谷》主角配音)，創造更多精湛的呈現。北中南巡演大勢席捲而來，狂美憑藉〝初心不悔〞之姿，喚醒觀眾心底最深的樂音逆襲！', '獨秀文化有限公司', '嘉義市東區忠孝路275號', '2025-06-15 00:00:00', '2025-06-15 00:00:00', '嘉義市政府文化局', 23.48170334, 120.4706244, '全票+400;全票+600;全票+800;全票+1000;全票+1200;全票+1500;全票+1800;全票+2200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='狂美交響管樂團：《宮崎駿動畫配樂II》交響音樂會', `description`='在狂美《宮崎駿動畫配樂》於「臺北國家音樂廳」完售封箱後，2025終於端出巔峰動人的續作。\r\n猶記當時，每一部宮崎駿動畫所傳遞的生命色彩和體悟。透由每一次的回放，總令人再三咀嚼故事背後其深意。穿梭在影像之後，有暖心〝配樂”相伴，縈繞在畫面與畫面間，牽引著靈魂與感官遨遊。\r\n再次回歸，必有新意！自大師筆下許多現象級動畫作品中，狂美精心揀選多部配樂章節，二次攜手導聆人楊小黎(官方中文版《魔女宅急便》、《心之谷》主角配音)，創造更多精湛的呈現。北中南巡演大勢席捲而來，狂美憑藉〝初心不悔〞之姿，喚醒觀眾心底最深的樂音逆襲！', `organizer`='獨秀文化有限公司', `address`='嘉義市東區忠孝路275號', `start_date`='2025-06-15 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='嘉義市政府文化局', `latitude`=23.48170334, `longitude`=120.4706244, `ticket_price`='全票+400;全票+600;全票+800;全票+1000;全票+1200;全票+1500;全票+1800;全票+2200', `source_url`='https://www.opentix.life/', `image_url`='[]';
