INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f8b3d28f15101f86006dfe', '展間，在此側身 In Between Exhibitions', '​ㄧ場藝術展覽不僅僅是作品的呈現，更涉及展場與幕後之間錯綜複雜的關係。福利社 FreeS Art Space 將於2025年4月12日至5月10日展出王詠翔個展《展間，在此側身》，藝術家透過影像、聲音與空間裝置，探討展覽機制下的「側身」現象，試圖重新審視展場中被忽略的存在。\r\n​\r\n王詠翔自2018年起投入佈展相關工作，身兼藝術家與幕後工作者的角色，這樣的雙重身份讓他關注展覽過程中的隱性勞動與展間變動。《展間，在此側身》不僅指展覽空間的物理存在，也象徵展覽期間及展覽之間的時間空檔。「側身」則代表展場內幕後工作者的移動姿態，亦隱喻展覽過程中被消弭的痕跡，展場在開幕的瞬間趨於完整，幕後的種種卻彷彿不曾存在——例如臨時搭建又拆除的隔間、刻意刷白的牆面、被有意遮掩的線材設備，這些都是展覽過程中被排除和被隱藏的元素。\r\n​\r\n誠摯邀請對當代藝術、展覽機制與空間研究感興趣的朋友，共同參與這場關於展覽背後脈絡的探索。​', '福利社 FreeS Art Space', '臺北市中山區新生北路三段82號B1', '2025-04-12 00:00:00', '2025-05-10 00:00:00', '福利社 FreeS Art Space', 25.06969917, 121.5381597, '無資料', 'https://www.facebook.com/freesartspace', '[]') ON DUPLICATE KEY UPDATE `activity_name`='展間，在此側身 In Between Exhibitions', `description`='​ㄧ場藝術展覽不僅僅是作品的呈現，更涉及展場與幕後之間錯綜複雜的關係。福利社 FreeS Art Space 將於2025年4月12日至5月10日展出王詠翔個展《展間，在此側身》，藝術家透過影像、聲音與空間裝置，探討展覽機制下的「側身」現象，試圖重新審視展場中被忽略的存在。\r\n​\r\n王詠翔自2018年起投入佈展相關工作，身兼藝術家與幕後工作者的角色，這樣的雙重身份讓他關注展覽過程中的隱性勞動與展間變動。《展間，在此側身》不僅指展覽空間的物理存在，也象徵展覽期間及展覽之間的時間空檔。「側身」則代表展場內幕後工作者的移動姿態，亦隱喻展覽過程中被消弭的痕跡，展場在開幕的瞬間趨於完整，幕後的種種卻彷彿不曾存在——例如臨時搭建又拆除的隔間、刻意刷白的牆面、被有意遮掩的線材設備，這些都是展覽過程中被排除和被隱藏的元素。\r\n​\r\n誠摯邀請對當代藝術、展覽機制與空間研究感興趣的朋友，共同參與這場關於展覽背後脈絡的探索。​', `organizer`='福利社 FreeS Art Space', `address`='臺北市中山區新生北路三段82號B1', `start_date`='2025-04-12 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='福利社 FreeS Art Space', `latitude`=25.06969917, `longitude`=121.5381597, `ticket_price`='無資料', `source_url`='https://www.facebook.com/freesartspace', `image_url`='[]';
