INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f9871426b3242b74a3afbf', '維度綻放–2025台灣美術院年度大展（免費參觀）', '台灣美術院成立於2010年，聚集台灣美術界的傑出教授、藝術創作者及學術專家，目前共有50多位成員，是台灣重要美術創作與學術研究團隊之一，歷年來舉辦的展覽皆精采豐富、備受讚譽。\n\n本次2025年度大展「維度綻放」以藝術多元探索為核心，共有40位院士參與展出，例如：廖修平、蘇憲法、林磐聳、鐘有輝、江明賢、黃光男、蕭世瓊等，作品含括油畫、水彩、水墨、膠彩、設計等各種媒材創作，風格多元，亮點紛呈。期待透過此次大展，帶領觀眾認識台灣藝術創作脈動，凝聚構築臺灣藝術文化主體性輪廓，提升台灣藝術史學研究的前瞻視野。\n\n \n\n ', '國立中正紀念堂管理處', '100  臺北市中正區中山南路21號', '2025-04-12 00:00:00', '2025-05-06 00:00:00', '1展廳', 25.0367564, 121.519047, '無資料', 'https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50763', '[]') ON DUPLICATE KEY UPDATE `activity_name`='維度綻放–2025台灣美術院年度大展（免費參觀）', `description`='台灣美術院成立於2010年，聚集台灣美術界的傑出教授、藝術創作者及學術專家，目前共有50多位成員，是台灣重要美術創作與學術研究團隊之一，歷年來舉辦的展覽皆精采豐富、備受讚譽。\n\n本次2025年度大展「維度綻放」以藝術多元探索為核心，共有40位院士參與展出，例如：廖修平、蘇憲法、林磐聳、鐘有輝、江明賢、黃光男、蕭世瓊等，作品含括油畫、水彩、水墨、膠彩、設計等各種媒材創作，風格多元，亮點紛呈。期待透過此次大展，帶領觀眾認識台灣藝術創作脈動，凝聚構築臺灣藝術文化主體性輪廓，提升台灣藝術史學研究的前瞻視野。\n\n \n\n ', `organizer`='國立中正紀念堂管理處', `address`='100  臺北市中正區中山南路21號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-05-06 00:00:00', `location`='1展廳', `latitude`=25.0367564, `longitude`=121.519047, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/CKSMH/Detail.init.ctr?actId=50763', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f9872c26b3242b74a3afc0', '【翻山越嶺-與森同行】島嶼上的博物學家系列', '【翻山越嶺-與森同行】主題導覽活動\n\n走入部落是認識不同族群最直接的方式。被譽為「臺灣蕃界調查第一人」的森丑之助（Ushinosuke Mori, 1877-1926），儘管天生一足微跛，但在1896到1915年19年間，森氏以驚人的毅力，縱橫臺灣各地山區，田野調查不下百餘次，足跡幾乎遍及全島所有原住民的區域。除了留下豐富的文字記錄與大量的攝影影像外，森丑之助在調查過程中也廣泛的蒐集原住民文物。\n\n本活動結合「發現臺灣」常設展，帶領觀眾認識博物學家-森丑之助以及探索他在這座島嶼上踏查、研究的成果。透過主題導覽與學習單操作，從攀登玉山日記文字中的趣聞、發現，感受博物學家親身實地調查研究的熱忱與溫度，進而體認維護多元文化之重要性。\n\n \n\n日期：114年4月26日、4月27日\n\n時間：10:00-11:00(請在9:45-10:00完成報到，報到處於本館門廳黃虎旗前)\n\n對象：一般民眾(建議國小中年級以上至成人)\n\n辦法：\n\n1.活動採線上報名，25人/場\n\n2.活動免費(需購票入館)，活動內容包含主題導覽與學習單探索(每人限索取一份學習單)\n\n \n\n★主辦單位將同時進行場記拍攝，其影像供主辦單位成果紀錄、教育推廣使用。\n\n★本活動即展場內容中或有使用「番」或「蕃」等字眼，皆出於保持原有引用歷史文獻使用之文字，並非刻意汙衊。\n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n ', '國立臺灣博物館', '100  臺北市中正區中正區襄陽路2號(二二八公園內)', '2025-04-26 00:00:00', '2025-04-27 00:00:00', '臺博館本館', 25.0418254, 121.5149875, '無資料', 'https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=50091', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【翻山越嶺-與森同行】島嶼上的博物學家系列', `description`='【翻山越嶺-與森同行】主題導覽活動\n\n走入部落是認識不同族群最直接的方式。被譽為「臺灣蕃界調查第一人」的森丑之助（Ushinosuke Mori, 1877-1926），儘管天生一足微跛，但在1896到1915年19年間，森氏以驚人的毅力，縱橫臺灣各地山區，田野調查不下百餘次，足跡幾乎遍及全島所有原住民的區域。除了留下豐富的文字記錄與大量的攝影影像外，森丑之助在調查過程中也廣泛的蒐集原住民文物。\n\n本活動結合「發現臺灣」常設展，帶領觀眾認識博物學家-森丑之助以及探索他在這座島嶼上踏查、研究的成果。透過主題導覽與學習單操作，從攀登玉山日記文字中的趣聞、發現，感受博物學家親身實地調查研究的熱忱與溫度，進而體認維護多元文化之重要性。\n\n \n\n日期：114年4月26日、4月27日\n\n時間：10:00-11:00(請在9:45-10:00完成報到，報到處於本館門廳黃虎旗前)\n\n對象：一般民眾(建議國小中年級以上至成人)\n\n辦法：\n\n1.活動採線上報名，25人/場\n\n2.活動免費(需購票入館)，活動內容包含主題導覽與學習單探索(每人限索取一份學習單)\n\n \n\n★主辦單位將同時進行場記拍攝，其影像供主辦單位成果紀錄、教育推廣使用。\n\n★本活動即展場內容中或有使用「番」或「蕃」等字眼，皆出於保持原有引用歷史文獻使用之文字，並非刻意汙衊。\n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n ', `organizer`='國立臺灣博物館', `address`='100  臺北市中正區中正區襄陽路2號(二二八公園內)', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺博館本館', `latitude`=25.0418254, `longitude`=121.5149875, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTM/Detail.init.ctr?actId=50091', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f987ba26b3242b74a3afc1', '臺南市東區裕文圖書館- 114年4月 歡樂聽故事', '由志工老師們精心挑選出優質的故事繪本，以親子共讀方式，帶領幼兒故事分享，不定時會加入小活動，增進親子間的情感交流。\r\n4月05日 15:00-15:40 亞斯的國王新衣 - Double姐姐 \r\n4月12日 10:30-11:00 超神奇糖果鋪 - Angel阿姨 \r\n4月19日 15:00-15:40 媽媽，猜猜看 - 米妮巫婆\r\n', '臺南市東區裕文圖書館', '臺南市東區裕信路237號', '2025-04-12 00:00:00', '2025-04-26 00:00:00', '臺南市東區裕文圖書館', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市東區裕文圖書館- 114年4月 歡樂聽故事', `description`='由志工老師們精心挑選出優質的故事繪本，以親子共讀方式，帶領幼兒故事分享，不定時會加入小活動，增進親子間的情感交流。\r\n4月05日 15:00-15:40 亞斯的國王新衣 - Double姐姐 \r\n4月12日 10:30-11:00 超神奇糖果鋪 - Angel阿姨 \r\n4月19日 15:00-15:40 媽媽，猜猜看 - 米妮巫婆\r\n', `organizer`='臺南市東區裕文圖書館', `address`='臺南市東區裕信路237號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='臺南市東區裕文圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f987ba26b3242b74a3afc2', '臺南市東區裕文圖書館- 114年4月 小葫蘆歡樂唱遊', '由志工老師精心挑選優質繪本，推廣親子共讀，帶領孩子一起進入書中世界，同時會在故事結束後增加一些小手作，讓孩子聽得開心、玩得開心。\r\n4月2日 牙婆婆，我會乖乖刷牙 - 音符鳥 \r\n4月9日 說出心裡話 - Vivi姐姐 \r\n4月16日 貓咪看家 - 圓圓阿姨 \r\n4月23日 蝴蝶結 - Apple阿姨 \r\n4月30日 Guji Guji不見了 - 藍鯨阿姨', '臺南市東區裕文圖書館', '臺南市東區裕信路237號', '2025-04-02 00:00:00', '2025-04-30 00:00:00', '臺南市東區裕文圖書館', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市東區裕文圖書館- 114年4月 小葫蘆歡樂唱遊', `description`='由志工老師精心挑選優質繪本，推廣親子共讀，帶領孩子一起進入書中世界，同時會在故事結束後增加一些小手作，讓孩子聽得開心、玩得開心。\r\n4月2日 牙婆婆，我會乖乖刷牙 - 音符鳥 \r\n4月9日 說出心裡話 - Vivi姐姐 \r\n4月16日 貓咪看家 - 圓圓阿姨 \r\n4月23日 蝴蝶結 - Apple阿姨 \r\n4月30日 Guji Guji不見了 - 藍鯨阿姨', `organizer`='臺南市東區裕文圖書館', `address`='臺南市東區裕信路237號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市東區裕文圖書館', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
