INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f987bc26b3242b74a3afc6', '動靜之間—長榮大學教授暨校友聯展', '展覽除展現美術系、書畫藝術學系及台灣文創學程師生、校友多元創作外，也呼應長榮大學主辦的全國大專院校運動會主題，融合動與靜、力與美的藝術表現。「動靜之間」旨在探討藝術創作中的動態與靜態轉換，象徵競技與靜觀、力量與和諧之間的平衡與互動，邀請觀者在靜觀中感受動勢，動態中品味靜謐，體會視覺與精神的雙重感動。', '私立長榮大學', '臺南市歸仁區信義南路78號', '2025-04-18 00:00:00', '2025-05-11 00:00:00', '歸仁文化中心', 22.94679469, 120.2930627, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='動靜之間—長榮大學教授暨校友聯展', `description`='展覽除展現美術系、書畫藝術學系及台灣文創學程師生、校友多元創作外，也呼應長榮大學主辦的全國大專院校運動會主題，融合動與靜、力與美的藝術表現。「動靜之間」旨在探討藝術創作中的動態與靜態轉換，象徵競技與靜觀、力量與和諧之間的平衡與互動，邀請觀者在靜觀中感受動勢，動態中品味靜謐，體會視覺與精神的雙重感動。', `organizer`='私立長榮大學', `address`='臺南市歸仁區信義南路78號', `start_date`='2025-04-18 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='歸仁文化中心', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f987bc26b3242b74a3afc7', '層黯與光澤—龔瑩慧漆金創作個展', '運用樹漆與金屬工藝的特質，呈現層黯與光澤的交互作用，探索生命風景的變幻不息。作品如同古代手稿，記錄著時間的流動與刻痕，正如唐代詩人劉禹錫〈磨鏡篇〉所言：「流塵翳明鏡，歲月看如漆。」縱使行者足跡紛沓，記憶終將安置於心靈深處。透過感知樹漆的溫潤與金屬的堅毅調性，作品在對比與融合的創作詮釋中展現多層次現象。', '無資料', '臺南市歸仁區信義南路78號', '2025-04-18 00:00:00', '2025-05-11 00:00:00', '歸仁文化中心', 22.94679469, 120.2930627, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='層黯與光澤—龔瑩慧漆金創作個展', `description`='運用樹漆與金屬工藝的特質，呈現層黯與光澤的交互作用，探索生命風景的變幻不息。作品如同古代手稿，記錄著時間的流動與刻痕，正如唐代詩人劉禹錫〈磨鏡篇〉所言：「流塵翳明鏡，歲月看如漆。」縱使行者足跡紛沓，記憶終將安置於心靈深處。透過感知樹漆的溫潤與金屬的堅毅調性，作品在對比與融合的創作詮釋中展現多層次現象。', `organizer`='無資料', `address`='臺南市歸仁區信義南路78號', `start_date`='2025-04-18 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='歸仁文化中心', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
