INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f987fd26b3242b74a3afea', '2025中華美術家美展', '中華美術家協會成立於2024年，旨在推動文化藝術創作與交流，透過書畫展覽、藝術創作及相關文化活動，結合世界各地志同道合的藝術家，共同推動藝術發展，並促進國際文化藝術交流，提升華人在國際間的地位，傳承與發揚文化藝術。', '臺南市政府秘書處', '臺南市安平區永華路二段6號', '2025-04-15 00:00:00', '2025-05-15 00:00:00', '臺南市政府永華市政中心', 22.99008437, 120.1649949, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025中華美術家美展', `description`='中華美術家協會成立於2024年，旨在推動文化藝術創作與交流，透過書畫展覽、藝術創作及相關文化活動，結合世界各地志同道合的藝術家，共同推動藝術發展，並促進國際文化藝術交流，提升華人在國際間的地位，傳承與發揚文化藝術。', `organizer`='臺南市政府秘書處', `address`='臺南市安平區永華路二段6號', `start_date`='2025-04-15 00:00:00', `end_date`='2025-05-15 00:00:00', `location`='臺南市政府永華市政中心', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f987fe26b3242b74a3afeb', '白河區圖書館 :4月份主題書展-「童」心啟航-閱讀童樂趣、書中人，影中視', '114年4月份主題書展\r\n~「童」心啟航-閱讀童樂趣 ~\r\n展出時間：114/4/1~4/30\r\n展出地點：1樓大廳\r\n本月份圖書館準備許多兒童相關書籍，讓孩子們可以多多閱讀並啟發小朋友的學習能力，讓閱讀變得越來越有趣。⭐~歡迎借閱~⭐\r\n📢4/1~4/6還有借10本書就可以玩戳戳樂唷\r\n------------------------------\r\n2025世界閱讀日~書中人，影中視~\r\n展出地點：2樓主題書展區\r\n本月主題由改編成影視的文學作品，讓讀者從不一樣的視角欣賞這些電影或影集，讓我們一起發現其中的奧妙吧!⭐展覽用書不可外借，歡迎預約⭐', '臺南市白河區圖書館', '臺南市白河區新興路573號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '張慶芳紀念圖書館(白河區圖書館)', 23.35132068, 120.4578565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='白河區圖書館 :4月份主題書展-「童」心啟航-閱讀童樂趣、書中人，影中視', `description`='114年4月份主題書展\r\n~「童」心啟航-閱讀童樂趣 ~\r\n展出時間：114/4/1~4/30\r\n展出地點：1樓大廳\r\n本月份圖書館準備許多兒童相關書籍，讓孩子們可以多多閱讀並啟發小朋友的學習能力，讓閱讀變得越來越有趣。⭐~歡迎借閱~⭐\r\n📢4/1~4/6還有借10本書就可以玩戳戳樂唷\r\n------------------------------\r\n2025世界閱讀日~書中人，影中視~\r\n展出地點：2樓主題書展區\r\n本月主題由改編成影視的文學作品，讓讀者從不一樣的視角欣賞這些電影或影集，讓我們一起發現其中的奧妙吧!⭐展覽用書不可外借，歡迎預約⭐', `organizer`='臺南市白河區圖書館', `address`='臺南市白河區新興路573號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='張慶芳紀念圖書館(白河區圖書館)', `latitude`=23.35132068, `longitude`=120.4578565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
