INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f9880526b3242b74a3aff3', '南區鹽埕圖書館：4月周日電影開麥拉', '春天的氣息撲面而來\r\n色彩斑斕的花海中\r\n有沒有你所嚮往的風景呢？\r\n難免有些旅程未完待續\r\n但只要按下播放鍵，在電影的世界中\r\n我們永遠在路上……\r\n\r\n【電影開麥拉4月片單】\r\n4月6日(日)湯恩與劍客汪汪隊\r\n普/88分鐘/動畫片\r\n4月13日(日)以愛之茗\r\n普/110分鐘/劇情片\r\n4月20日(日)角落小夥伴電影版：魔法繪本裡的新朋友\r\n普/66分鐘/劇情片\r\n4月27日(日)鼠寶特攻\r\n保/90分鐘/劇情片\r\n\r\n免報名，自由入場', '臺南市南區鹽埕圖書館', '臺南市南區新和東路51號', '2025-04-06 00:00:00', '2025-04-27 00:00:00', '臺南市南區鹽埕圖書館', 22.95561863, 120.1903743, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南區鹽埕圖書館：4月周日電影開麥拉', `description`='春天的氣息撲面而來\r\n色彩斑斕的花海中\r\n有沒有你所嚮往的風景呢？\r\n難免有些旅程未完待續\r\n但只要按下播放鍵，在電影的世界中\r\n我們永遠在路上……\r\n\r\n【電影開麥拉4月片單】\r\n4月6日(日)湯恩與劍客汪汪隊\r\n普/88分鐘/動畫片\r\n4月13日(日)以愛之茗\r\n普/110分鐘/劇情片\r\n4月20日(日)角落小夥伴電影版：魔法繪本裡的新朋友\r\n普/66分鐘/劇情片\r\n4月27日(日)鼠寶特攻\r\n保/90分鐘/劇情片\r\n\r\n免報名，自由入場', `organizer`='臺南市南區鹽埕圖書館', `address`='臺南市南區新和東路51號', `start_date`='2025-04-06 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺南市南區鹽埕圖書館', `latitude`=22.95561863, `longitude`=120.1903743, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f9880526b3242b74a3aff4', '南區鹽埕圖書館：臺南分區資源中心巡迴書展-圖書館裡的美術館', '奇美博物館有英國國家藝廊「從拉斐爾到梵谷」，高美館有英國泰德現代美術館「瞬間－穿越繪畫與攝影之旅」，我們鹽埕有「圖書館裡的美術館」遍及古今及東西的藝術主題館藏，梵谷向日葵青花瓷梅花....同台競美。\r\n「蛙～娜麗莎」輕喚聲，欸??是什麼聲音?\r\n順聲望去，圖書館的鎮展之寶—蛙寶肖像畫「蛙娜麗莎」正露出神秘的微笑。\r\n\r\n*書展期間相關書籍皆可借閱\r\n休館日:週一、國定假日、每月最後一個週五清潔日\r\n', '臺南市南區鹽埕圖書館', '臺南市南區新和東路51號', '2025-04-02 00:00:00', '2025-04-30 00:00:00', '臺南市南區鹽埕圖書館', 22.95561863, 120.1903743, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南區鹽埕圖書館：臺南分區資源中心巡迴書展-圖書館裡的美術館', `description`='奇美博物館有英國國家藝廊「從拉斐爾到梵谷」，高美館有英國泰德現代美術館「瞬間－穿越繪畫與攝影之旅」，我們鹽埕有「圖書館裡的美術館」遍及古今及東西的藝術主題館藏，梵谷向日葵青花瓷梅花....同台競美。\r\n「蛙～娜麗莎」輕喚聲，欸??是什麼聲音?\r\n順聲望去，圖書館的鎮展之寶—蛙寶肖像畫「蛙娜麗莎」正露出神秘的微笑。\r\n\r\n*書展期間相關書籍皆可借閱\r\n休館日:週一、國定假日、每月最後一個週五清潔日\r\n', `organizer`='臺南市南區鹽埕圖書館', `address`='臺南市南區新和東路51號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市南區鹽埕圖書館', `latitude`=22.95561863, `longitude`=120.1903743, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
