INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f9880626b3242b74a3affd', '蔡淑珍風景創作個展「心中一畝田」', '蔡淑珍是一名專業藥師，在工作上接觸的是「生、老、病、死」，因此閒暇之餘喜歡追求美的事物，從日本池坊到歐美花藝，花了10年拿到池坊正教授一級總華綱;從漫步寫生到描繪自然，即將完成長榮大學美術系碩士班學業。由於不想侷限於小小的調劑室，渴望戶外新鮮的空氣，旅行變成是最大的安慰，看山、望水、讀天空，心想何不把美景繪入畫布，繪出心中一畝田，於是「風景」成為畫布的主角，在調劑人生中追尋美的事物，以風景為畫布主角，透過寫生、家鄉景色與重組手法，描繪心中的理想天地。此次展出的作品分為三個系列，分別為「一畝山水」-實景描繪大自然的美;「一畝鄉情」-紀錄個人家鄉的日常;「一畝立體」-重組拼貼幾何式的風景。', '臺南市安平區公所', '臺南市安平區育平路320號', '2025-04-15 00:00:00', '2025-05-18 00:00:00', '臺南市安平區圖書館', 22.99008437, 120.1649949, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='蔡淑珍風景創作個展「心中一畝田」', `description`='蔡淑珍是一名專業藥師，在工作上接觸的是「生、老、病、死」，因此閒暇之餘喜歡追求美的事物，從日本池坊到歐美花藝，花了10年拿到池坊正教授一級總華綱;從漫步寫生到描繪自然，即將完成長榮大學美術系碩士班學業。由於不想侷限於小小的調劑室，渴望戶外新鮮的空氣，旅行變成是最大的安慰，看山、望水、讀天空，心想何不把美景繪入畫布，繪出心中一畝田，於是「風景」成為畫布的主角，在調劑人生中追尋美的事物，以風景為畫布主角，透過寫生、家鄉景色與重組手法，描繪心中的理想天地。此次展出的作品分為三個系列，分別為「一畝山水」-實景描繪大自然的美;「一畝鄉情」-紀錄個人家鄉的日常;「一畝立體」-重組拼貼幾何式的風景。', `organizer`='臺南市安平區公所', `address`='臺南市安平區育平路320號', `start_date`='2025-04-15 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='臺南市安平區圖書館', `latitude`=22.99008437, `longitude`=120.1649949, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
