INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67f9880a26b3242b74a3b004', 'True Colors真實色彩—林時植陶藝複合媒材創作展', '文化部所屬國立彰化生活美學館自114年4月10日至5月25日，在該館第一、二展覽室舉辦「True Colors真實色彩—林時植陶藝複合媒材創作展」，展出玄奘大學藝術與創意設計學系林時植老師的系列創作。本次展出的《異域》及《真實色彩》系列，運用了金工鐵件與陶藝雕塑的材質及手法，並巧妙地融合為一。林時植認為本次的展覽，是一次關於人性與未來的探索，帶領觀者穿越悲觀與希望交織的深淵，以全新的視角思考我們與地球的關係。\r\n\r\n藝術家林時植，新竹人。出身於傳統的大家庭，卻沒有繼承父親的鐵工廠；生長在高科技業林立的都市，卻選擇自然原始的陶土藝術，做為終身志業。求學階段歷經美工、化工、工業設計，以及藝術學院等看似迥異而衝突的專業訓練，反而成為林時植的多元養分，融會體現於其複合媒材的創作上，進而卓然自成，獲得文化部臺灣工藝之家的殊榮與使命，成立「陶藝之林」，同時身兼玄奘大學藝術與創意設計學系及國立清華大學推廣教育中心講師，為藝術的傳承，貢獻心力。', '國立彰化生活美學館', '彰化縣彰化市卦山路18號', '2025-04-11 00:00:00', '2025-05-25 00:00:00', '國立彰化生活美學館', 24.07532909, 120.5694208, '無資料', 'https://www.chcsec.gov.tw/News_Content.aspx?n=4004&s=235031', '[]') ON DUPLICATE KEY UPDATE `activity_name`='True Colors真實色彩—林時植陶藝複合媒材創作展', `description`='文化部所屬國立彰化生活美學館自114年4月10日至5月25日，在該館第一、二展覽室舉辦「True Colors真實色彩—林時植陶藝複合媒材創作展」，展出玄奘大學藝術與創意設計學系林時植老師的系列創作。本次展出的《異域》及《真實色彩》系列，運用了金工鐵件與陶藝雕塑的材質及手法，並巧妙地融合為一。林時植認為本次的展覽，是一次關於人性與未來的探索，帶領觀者穿越悲觀與希望交織的深淵，以全新的視角思考我們與地球的關係。\r\n\r\n藝術家林時植，新竹人。出身於傳統的大家庭，卻沒有繼承父親的鐵工廠；生長在高科技業林立的都市，卻選擇自然原始的陶土藝術，做為終身志業。求學階段歷經美工、化工、工業設計，以及藝術學院等看似迥異而衝突的專業訓練，反而成為林時植的多元養分，融會體現於其複合媒材的創作上，進而卓然自成，獲得文化部臺灣工藝之家的殊榮與使命，成立「陶藝之林」，同時身兼玄奘大學藝術與創意設計學系及國立清華大學推廣教育中心講師，為藝術的傳承，貢獻心力。', `organizer`='國立彰化生活美學館', `address`='彰化縣彰化市卦山路18號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='國立彰化生活美學館', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='https://www.chcsec.gov.tw/News_Content.aspx?n=4004&s=235031', `image_url`='[]';
