INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad78926b3242b74a3b01e', '歸仁區圖書館-書中人影中視主題書展', '展出華燈初上，俗女養成記，地獄里長，沼澤女孩，看誰在說謊，升級，下一站，天國等相關書籍，供讀者翻閱。', '臺南市歸仁區圖書館', '臺南市歸仁區大德路127號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺南市歸仁區圖書館', 22.94679469, 120.2930627, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歸仁區圖書館-書中人影中視主題書展', `description`='展出華燈初上，俗女養成記，地獄里長，沼澤女孩，看誰在說謊，升級，下一站，天國等相關書籍，供讀者翻閱。', `organizer`='臺南市歸仁區圖書館', `address`='臺南市歸仁區大德路127號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市歸仁區圖書館', `latitude`=22.94679469, `longitude`=120.2930627, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad78b26b3242b74a3b01f', '「究・南物」在地串連小旅行：臺南市立博物館與中西區場篇', '臺南市政府文化局所出版的《南都物語：物件裡的臺南史》，書中提及的多項文物係由臺南市立博物館典藏；臺南市立博物館致力於臺南文化的典藏與展示，適逢今年為府城城垣啟建300年，除了原本的常設展「自造臺南」以時間軸的方式介紹臺南發展，特展「上(Tsiūnn)府城－啥物(siànn-mih)攏佇遮」也特別展示了過去府城內外之間的互動、來往、關係，這兩個展覽都跟《南都物語》一樣，詳實地寫下臺南的歷史與文化。\r\n​\r\n走入博物館「自造臺南」的展區，會發現一個巨大的鐵器，這是書中所寫的壁鎖，是用來穩固房子的梁柱，臺灣民間俗稱為鐵剪刀。\r\n​\r\n有時候在一些老房子看到壁鎖的身影，像是孔廟、陳世興古宅…等，起初常會以為這是從明鄭時期傳來的建築技術，但從書中的敘述發現，壁鎖的荷蘭文為「muurankers」，意思為牆壁上的錨，是隨著荷蘭人傳至臺南。\r\n​\r\n由於這個很有趣的發現，讓我們開始好奇，府城內還有哪些地方能看見壁鎖？這些建築背後又有什麼故事？路上可能還有哪些文物？這一連串的好奇便促成了這一次的主題式小旅行。', '臺南市文化資產管理處', '臺南市中西區開山路152號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '臺南市立博物館(原鄭成功文物館)', 22.99594458, 120.192874, '300元(含餐食、導覽機、博物館門票)+--', 'https://www.accupass.com/?area=all', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「究・南物」在地串連小旅行：臺南市立博物館與中西區場篇', `description`='臺南市政府文化局所出版的《南都物語：物件裡的臺南史》，書中提及的多項文物係由臺南市立博物館典藏；臺南市立博物館致力於臺南文化的典藏與展示，適逢今年為府城城垣啟建300年，除了原本的常設展「自造臺南」以時間軸的方式介紹臺南發展，特展「上(Tsiūnn)府城－啥物(siànn-mih)攏佇遮」也特別展示了過去府城內外之間的互動、來往、關係，這兩個展覽都跟《南都物語》一樣，詳實地寫下臺南的歷史與文化。\r\n​\r\n走入博物館「自造臺南」的展區，會發現一個巨大的鐵器，這是書中所寫的壁鎖，是用來穩固房子的梁柱，臺灣民間俗稱為鐵剪刀。\r\n​\r\n有時候在一些老房子看到壁鎖的身影，像是孔廟、陳世興古宅…等，起初常會以為這是從明鄭時期傳來的建築技術，但從書中的敘述發現，壁鎖的荷蘭文為「muurankers」，意思為牆壁上的錨，是隨著荷蘭人傳至臺南。\r\n​\r\n由於這個很有趣的發現，讓我們開始好奇，府城內還有哪些地方能看見壁鎖？這些建築背後又有什麼故事？路上可能還有哪些文物？這一連串的好奇便促成了這一次的主題式小旅行。', `organizer`='臺南市文化資產管理處', `address`='臺南市中西區開山路152號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺南市立博物館(原鄭成功文物館)', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='300元(含餐食、導覽機、博物館門票)+--', `source_url`='https://www.accupass.com/?area=all', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad78c26b3242b74a3b020', '仁德區圖書館:4月主題書展-書中人  影中視', '透過書籍與影片連結讓我們在閱讀的過程中，能和書中的人建立了一種特殊的特殊性連結，這種虛擬能讓閱讀者更深入地理解他們的內心世界，也豐富了閱讀者的人生經驗。閱讀是一次無窮無盡的旅程，我相信我還有無數精彩的故事等著我去發現和探索。我生命期待未來的閱讀時光，期待能和更多書中的人物對話，與他們一起感受的奇妙與美好。就讓我們繼續閱讀，並透過書籍的人與世界建立起一種獨特的連結。本次書展準備有影片、繪本童書、電影小說等將近百冊。', '臺南市仁德區圖書館', '臺南市仁德區正義一街39號2樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺南市仁德區圖書館', 22.94130931, 120.2418788, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='仁德區圖書館:4月主題書展-書中人  影中視', `description`='透過書籍與影片連結讓我們在閱讀的過程中，能和書中的人建立了一種特殊的特殊性連結，這種虛擬能讓閱讀者更深入地理解他們的內心世界，也豐富了閱讀者的人生經驗。閱讀是一次無窮無盡的旅程，我相信我還有無數精彩的故事等著我去發現和探索。我生命期待未來的閱讀時光，期待能和更多書中的人物對話，與他們一起感受的奇妙與美好。就讓我們繼續閱讀，並透過書籍的人與世界建立起一種獨特的連結。本次書展準備有影片、繪本童書、電影小說等將近百冊。', `organizer`='臺南市仁德區圖書館', `address`='臺南市仁德區正義一街39號2樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市仁德區圖書館', `latitude`=22.94130931, `longitude`=120.2418788, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
