INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79326b3242b74a3b024', '2025臺南國際音樂節-Trinity / 黃瑞豐x鍾興民x亞尼克.巴曼《金曲之夜》 ', '金曲雙組合！一場音樂會將能聽見二張專輯全歌曲！創作編曲巨擘鍾興民，遇上粹煉的生命節奏，誕生出前所未有的柔美撼動。台灣音樂傳奇人物 - 台灣鼓王黃瑞豐專輯《潮》與音樂大師鍾興民、瑞士知名小號手Yannick Barman 專輯《阿爾卑斯的日落》，即將原聲呈現在臺南文化中心。', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺南國際音樂節-Trinity / 黃瑞豐x鍾興民x亞尼克.巴曼《金曲之夜》 ', `description`='金曲雙組合！一場音樂會將能聽見二張專輯全歌曲！創作編曲巨擘鍾興民，遇上粹煉的生命節奏，誕生出前所未有的柔美撼動。台灣音樂傳奇人物 - 台灣鼓王黃瑞豐專輯《潮》與音樂大師鍾興民、瑞士知名小號手Yannick Barman 專輯《阿爾卑斯的日落》，即將原聲呈現在臺南文化中心。', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79326b3242b74a3b025', '七股區圖書館-4月主題書展', '4月主題書展:「書中人，影中視」\r\n以「改編成影視作品的文學作品」為題，讓讀者從不一樣的視角欣賞這些作品，感受文字的深度與魅力。', '臺南市七股區圖書館', '臺南市七股區377號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺南市七股區圖書館', 23.12326578, 120.1005854, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='七股區圖書館-4月主題書展', `description`='4月主題書展:「書中人，影中視」\r\n以「改編成影視作品的文學作品」為題，讓讀者從不一樣的視角欣賞這些作品，感受文字的深度與魅力。', `organizer`='臺南市七股區圖書館', `address`='臺南市七股區377號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市七股區圖書館', `latitude`=23.12326578, `longitude`=120.1005854, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79326b3242b74a3b026', '【勞動者的故事：汗水與夢想】│大地之心-一位斷層上的法國人', '中文片│大地之心-一位斷層上的法國人\r\n英文片│The Heart of Nature\r\n\r\n導演│齊怡、劉佩怡\r\n臺灣│2021│普遍級│紀錄類│彩色│華語│60分鐘\r\n\r\n簡介\r\n1981年，任教於法國居禮大學的 Jacques Angelier 安朔葉，首次來到臺灣，從事臺灣大地構造及演化研究，就此對這個年輕而活力旺盛的島嶼，一往情深。往後30年，他年年造訪，帶領臺法研究團隊翻山越嶺，走遍臺灣重要地景。', '臺南市南門電影書院', '臺南市中西區南門路與樹林街交叉路口', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '臺南市南門電影書院（含南門公園、臺灣府城大南門）', 22.99594458, 120.192874, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【勞動者的故事：汗水與夢想】│大地之心-一位斷層上的法國人', `description`='中文片│大地之心-一位斷層上的法國人\r\n英文片│The Heart of Nature\r\n\r\n導演│齊怡、劉佩怡\r\n臺灣│2021│普遍級│紀錄類│彩色│華語│60分鐘\r\n\r\n簡介\r\n1981年，任教於法國居禮大學的 Jacques Angelier 安朔葉，首次來到臺灣，從事臺灣大地構造及演化研究，就此對這個年輕而活力旺盛的島嶼，一往情深。往後30年，他年年造訪，帶領臺法研究團隊翻山越嶺，走遍臺灣重要地景。', `organizer`='臺南市南門電影書院', `address`='臺南市中西區南門路與樹林街交叉路口', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺南市南門電影書院（含南門公園、臺灣府城大南門）', `latitude`=22.99594458, `longitude`=120.192874, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79426b3242b74a3b027', '佳里區圖書館:4月份書展~書中人，影中視', '👨‍👨‍👧‍👦4月份主題 #書展「#書中人，#影中視」\r\n🎈展出時間：4月1日(二)~4月30日(三)\r\n🎈書展主題：以「改編成影視作品的文學作品」為題，讓讀者從不一樣的視角欣賞這些作品，感受文字的深度與魅力。\r\n🔗書單：https://reurl.cc/rEgdxO\r\n#世界閱讀日 #兒童樂讀月\r\n#展覽書籍 #歡迎外借', '臺南市佳里區圖書館', '臺南市佳里區安北路118號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺南市佳里區圖書館', 23.1669941, 120.178593, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='佳里區圖書館:4月份書展~書中人，影中視', `description`='👨‍👨‍👧‍👦4月份主題 #書展「#書中人，#影中視」\r\n🎈展出時間：4月1日(二)~4月30日(三)\r\n🎈書展主題：以「改編成影視作品的文學作品」為題，讓讀者從不一樣的視角欣賞這些作品，感受文字的深度與魅力。\r\n🔗書單：https://reurl.cc/rEgdxO\r\n#世界閱讀日 #兒童樂讀月\r\n#展覽書籍 #歡迎外借', `organizer`='臺南市佳里區圖書館', `address`='臺南市佳里區安北路118號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市佳里區圖書館', `latitude`=23.1669941, `longitude`=120.178593, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79426b3242b74a3b028', '北門區圖書館:4月主題書展-2024 OPENBOOK好書獎', '透過書展的辦理，讓讀者多了解圖書館的館藏資源，也藉由這樣的活動與讀者有更多的互動與交流。\r\n此次展出2024年度的Openbook好書獎得獎圖書，分5大類有年度中文創作、年度翻譯書、年度生活書、年度童書及青少年圖書。\r\n帶上一本書你並不孤單。', '臺南市北門區圖書館', '臺南市北門區港北49號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺南市北門區圖書館', 23.2777708, 120.1262357, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='北門區圖書館:4月主題書展-2024 OPENBOOK好書獎', `description`='透過書展的辦理，讓讀者多了解圖書館的館藏資源，也藉由這樣的活動與讀者有更多的互動與交流。\r\n此次展出2024年度的Openbook好書獎得獎圖書，分5大類有年度中文創作、年度翻譯書、年度生活書、年度童書及青少年圖書。\r\n帶上一本書你並不孤單。', `organizer`='臺南市北門區圖書館', `address`='臺南市北門區港北49號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市北門區圖書館', `latitude`=23.2777708, `longitude`=120.1262357, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79726b3242b74a3b029', '李聖宮媽祖聖誕祀典_新鳳珠歌仔戲', '真的超熱鬧啊！媽祖聖誕（農曆三月二十三）在台灣可是非常重要的民俗節慶，整個廟會氛圍不只是宗教信仰的展現，還有歌仔戲表演，整個廣場都像嘉年華一樣熱鬧滾滾！', '無資料', '臺南市將軍區', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '將軍區（臺南市）=', 23.20834413, 120.1276958, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='李聖宮媽祖聖誕祀典_新鳳珠歌仔戲', `description`='真的超熱鬧啊！媽祖聖誕（農曆三月二十三）在台灣可是非常重要的民俗節慶，整個廟會氛圍不只是宗教信仰的展現，還有歌仔戲表演，整個廣場都像嘉年華一樣熱鬧滾滾！', `organizer`='無資料', `address`='臺南市將軍區', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='將軍區（臺南市）=', `latitude`=23.20834413, `longitude`=120.1276958, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79826b3242b74a3b02a', '114年奇幻野獸島兒童戲劇_麻咕麻酷創作劇團', '慶祝四月兒童節的到來，善化區公所辦理「奇幻野獸島」兒童戲劇活動，透過戲劇的演出，啟發孩子們的想像力與專注力，提升地方之文藝氣息。\r\n【麻咕麻酷創作劇團】以推廣台灣在地藝文活動為宗旨,並引發社會大眾對戲劇演出及觀賞的興趣。\r\n', '臺南市善化區公所', '臺南市善化區', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '善化區（臺南市）=', 23.14031072, 120.2988274, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年奇幻野獸島兒童戲劇_麻咕麻酷創作劇團', `description`='慶祝四月兒童節的到來，善化區公所辦理「奇幻野獸島」兒童戲劇活動，透過戲劇的演出，啟發孩子們的想像力與專注力，提升地方之文藝氣息。\r\n【麻咕麻酷創作劇團】以推廣台灣在地藝文活動為宗旨,並引發社會大眾對戲劇演出及觀賞的興趣。\r\n', `organizer`='臺南市善化區公所', `address`='臺南市善化區', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='善化區（臺南市）=', `latitude`=23.14031072, `longitude`=120.2988274, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79826b3242b74a3b02b', '新營區圖書館:OPENBOOK好書獎展', '為推廣認識OPEN好書獎，透過展示好書獎得獎書籍主題相關館藏，吸引民眾關注並了解OPEN好書獎得獎好書，增進民眾對OPEN好書獎得獎書籍的認識與興趣。', '臺南市新營區圖書館', '臺南市新營區45之8號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '臺南市新營區圖書館', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新營區圖書館:OPENBOOK好書獎展', `description`='為推廣認識OPEN好書獎，透過展示好書獎得獎書籍主題相關館藏，吸引民眾關注並了解OPEN好書獎得獎好書，增進民眾對OPEN好書獎得獎書籍的認識與興趣。', `organizer`='臺南市新營區圖書館', `address`='臺南市新營區45之8號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺南市新營區圖書館', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79826b3242b74a3b02c', '中華書道印藝學會乙巳會員聯展－展翅上騰 ', '中華書道印藝學會成立逾二十載，由書法篆刻大師張添原先生創立，致力於推廣書藝與文化交流。本次會員聯展以「展翅上騰」為題，展出會員多年來於書道印藝的學習成果，展現對藝術的熱忱與傳承。透過此次展覽，期待向前輩專家與社會賢達請益，進一步提升學會的藝術水準，共同推動文化發展。\r\n\r\n', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-04-11 00:00:00', '2025-05-04 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中華書道印藝學會乙巳會員聯展－展翅上騰 ', `description`='中華書道印藝學會成立逾二十載，由書法篆刻大師張添原先生創立，致力於推廣書藝與文化交流。本次會員聯展以「展翅上騰」為題，展出會員多年來於書道印藝的學習成果，展現對藝術的熱忱與傳承。透過此次展覽，期待向前輩專家與社會賢達請益，進一步提升學會的藝術水準，共同推動文化發展。\r\n\r\n', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79826b3242b74a3b02d', '台灣綠水畫會第35屆會員聯展 ', '膠彩畫為東方特有的藝術表現形式，與水墨畫同為代表東方傳統文化氣韻之美的風格，向來即同為東方藝術的兩大創作主軸。\r\n「膠彩」以動物膠調和礦物顏料及植物性顏料繪製而成，其繪製過程繁複，但能營造瑰麗絢爛、富麗堂皇或典雅的藝術視覺效果。\r\n台灣綠水畫會成立已久，是目前國內最具盛名的膠彩畫創作團體。每位老師均有其特別的表現技法，成員有來自大學之教授、美術研究所之碩士、專業創作之畫家⋯等。創作主題除了來自於自然生態的表現外，亦有詮釋心靈感受的直觀表現。\r\n', '臺南市政府文化局', '臺南市東區中華東路三段332號', '2025-04-11 00:00:00', '2025-05-04 00:00:00', '臺南文化中心', 22.98178202, 120.2281858, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台灣綠水畫會第35屆會員聯展 ', `description`='膠彩畫為東方特有的藝術表現形式，與水墨畫同為代表東方傳統文化氣韻之美的風格，向來即同為東方藝術的兩大創作主軸。\r\n「膠彩」以動物膠調和礦物顏料及植物性顏料繪製而成，其繪製過程繁複，但能營造瑰麗絢爛、富麗堂皇或典雅的藝術視覺效果。\r\n台灣綠水畫會成立已久，是目前國內最具盛名的膠彩畫創作團體。每位老師均有其特別的表現技法，成員有來自大學之教授、美術研究所之碩士、專業創作之畫家⋯等。創作主題除了來自於自然生態的表現外，亦有詮釋心靈感受的直觀表現。\r\n', `organizer`='臺南市政府文化局', `address`='臺南市東區中華東路三段332號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='臺南文化中心', `latitude`=22.98178202, `longitude`=120.2281858, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
