INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79926b3242b74a3b033', '2025年4月【彰化縣玩具銀行-寶貝聽故事】共2場', '2025年4月【彰化縣玩具銀行-寶貝聽故事】共2場\r\n\r\n4/9、4/26\r\n10:00~11:00\r\n\r\n彰化縣政府為減輕家長負擔、提升多元教養支持及保障兒童遊戲權，創立「彰化縣玩具銀行」，提供免費全新教玩具借閱、教玩具與繪本教學示範等服務。館內教玩具及繪本多元多樣，外借回家使用歸還期限為7-14日，現場專業人員協助家長指導操作教玩具，讓親子自由選擇及探索，亦提供親子共讀空間，鼓勵家長陪伴孩子閱讀，享受共讀樂趣，促進親子互動關係。', '彰化縣政府社會處', '彰化縣溪湖鎮', '2025-04-09 00:00:00', '2025-04-26 00:00:00', '溪湖鎮（彰化縣）=', 23.95171456, 120.4831739, '無資料', 'https://www.facebook.com/CHCYC8850097', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年4月【彰化縣玩具銀行-寶貝聽故事】共2場', `description`='2025年4月【彰化縣玩具銀行-寶貝聽故事】共2場\r\n\r\n4/9、4/26\r\n10:00~11:00\r\n\r\n彰化縣政府為減輕家長負擔、提升多元教養支持及保障兒童遊戲權，創立「彰化縣玩具銀行」，提供免費全新教玩具借閱、教玩具與繪本教學示範等服務。館內教玩具及繪本多元多樣，外借回家使用歸還期限為7-14日，現場專業人員協助家長指導操作教玩具，讓親子自由選擇及探索，亦提供親子共讀空間，鼓勵家長陪伴孩子閱讀，享受共讀樂趣，促進親子互動關係。', `organizer`='彰化縣政府社會處', `address`='彰化縣溪湖鎮', `start_date`='2025-04-09 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='溪湖鎮（彰化縣）=', `latitude`=23.95171456, `longitude`=120.4831739, `ticket_price`='無資料', `source_url`='https://www.facebook.com/CHCYC8850097', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79926b3242b74a3b034', '畫我家鄉～2025兒童繪畫比賽', '二林鎮公所與彰化縣香草藝文推展協會共同主辦「畫我家鄉～2025兒童繪畫比賽暨兒童藝術創作宣導活動」，歡迎國小、幼兒園學生踴躍報名參加。\r\n本活動報名時間自即日起至114年5月30日17時止。\r\n各國小及幼兒園以團體報名參加者，請統一收件、送件至二林圖書館服務台（報名表請填寫後黏貼在作品背面），以利評審之規劃。\r\n本比賽競賽組別分為國小高年級組（5-6年級）、國小中年級組（3-4年級）、國小低年級組（1-2年級）及幼兒園組等共4組，各組擇優錄取第一名各1名、第二名各2名、第三名各3名、佳作各10名、入選各10名，如各組別參賽作品不足30件，則以件數不足，不予評分，但得選出若干名優選獎，以茲鼓勵。\r\n繪畫所需之畫紙（四開）請自備，統一以「橫式」作畫，素材不限，水彩、蠟筆、粉蠟筆、彩色筆、色鉛筆...等皆可，作畫完畢請將報名表填寫完整，黏貼在作品背面，寄送或親送至二林圖書館服務台。\r\n作品收件時間自114年5月1日（四）至5月30日（五）每日上午9時至下午5時止，凡逾時送件者恕無法報名（寄送者以郵戳日期為準）；收件地點為二林鎮立圖書館服務台（地址：526二林鎮斗苑路4段626號）。\r\n參賽作品將於評審後公告得獎名單於本所官網及彰化縣二林鎮立圖書館臉書，得獎作品集結編輯成畫冊，並預訂114年10月17日（五）晚上7:00於二林鎮立圖書館舉行頒獎典禮，屆時得獎學生皆可獲贈1本得獎作品專輯。', '彰化縣二林鎮公所', '彰化縣二林鎮斗苑路4段626號', '2025-04-12 00:00:00', '2025-05-30 00:00:00', '彰化縣二林鎮立圖書館', 23.91621405, 120.404225, '無資料', 'https://www.facebook.com/profile.php?id=100064354342750#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='畫我家鄉～2025兒童繪畫比賽', `description`='二林鎮公所與彰化縣香草藝文推展協會共同主辦「畫我家鄉～2025兒童繪畫比賽暨兒童藝術創作宣導活動」，歡迎國小、幼兒園學生踴躍報名參加。\r\n本活動報名時間自即日起至114年5月30日17時止。\r\n各國小及幼兒園以團體報名參加者，請統一收件、送件至二林圖書館服務台（報名表請填寫後黏貼在作品背面），以利評審之規劃。\r\n本比賽競賽組別分為國小高年級組（5-6年級）、國小中年級組（3-4年級）、國小低年級組（1-2年級）及幼兒園組等共4組，各組擇優錄取第一名各1名、第二名各2名、第三名各3名、佳作各10名、入選各10名，如各組別參賽作品不足30件，則以件數不足，不予評分，但得選出若干名優選獎，以茲鼓勵。\r\n繪畫所需之畫紙（四開）請自備，統一以「橫式」作畫，素材不限，水彩、蠟筆、粉蠟筆、彩色筆、色鉛筆...等皆可，作畫完畢請將報名表填寫完整，黏貼在作品背面，寄送或親送至二林圖書館服務台。\r\n作品收件時間自114年5月1日（四）至5月30日（五）每日上午9時至下午5時止，凡逾時送件者恕無法報名（寄送者以郵戳日期為準）；收件地點為二林鎮立圖書館服務台（地址：526二林鎮斗苑路4段626號）。\r\n參賽作品將於評審後公告得獎名單於本所官網及彰化縣二林鎮立圖書館臉書，得獎作品集結編輯成畫冊，並預訂114年10月17日（五）晚上7:00於二林鎮立圖書館舉行頒獎典禮，屆時得獎學生皆可獲贈1本得獎作品專輯。', `organizer`='彰化縣二林鎮公所', `address`='彰化縣二林鎮斗苑路4段626號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-05-30 00:00:00', `location`='彰化縣二林鎮立圖書館', `latitude`=23.91621405, `longitude`=120.404225, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064354342750#', `image_url`='[]';
