INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79926b3242b74a3b03f', '綻放繽紛五人聯展', '本次聯展由 黃立丹老師 所指導的周淑鈴、黃秀玲、侯宜君、黃國隆、楊玉琴等五位藝術家共同展出，展覽作品以花卉為主。展出者用最簡單的筆觸與水墨、水彩暈染的繪畫方式，呈現一幅幅精彩的畫作與觀展者互動。歡迎有興趣的民眾蒞臨觀賞這場花卉饗宴，誠摯邀請鄉親與繪畫同好們到館參觀～～', '彰化縣埔鹽鄉公所', '彰化縣埔鹽鄉員鹿路2段60號', '2025-03-22 00:00:00', '2025-04-20 00:00:00', '彰化縣埔鹽鄉立圖書館', 23.99204417, 120.4594626, '無資料', 'https://www.facebook.com/PuyanLibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='綻放繽紛五人聯展', `description`='本次聯展由 黃立丹老師 所指導的周淑鈴、黃秀玲、侯宜君、黃國隆、楊玉琴等五位藝術家共同展出，展覽作品以花卉為主。展出者用最簡單的筆觸與水墨、水彩暈染的繪畫方式，呈現一幅幅精彩的畫作與觀展者互動。歡迎有興趣的民眾蒞臨觀賞這場花卉饗宴，誠摯邀請鄉親與繪畫同好們到館參觀～～', `organizer`='彰化縣埔鹽鄉公所', `address`='彰化縣埔鹽鄉員鹿路2段60號', `start_date`='2025-03-22 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='彰化縣埔鹽鄉立圖書館', `latitude`=23.99204417, `longitude`=120.4594626, `ticket_price`='無資料', `source_url`='https://www.facebook.com/PuyanLibrary', `image_url`='[]';
