INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fad79a26b3242b74a3b04b', '臺南市兒童文學創作專輯小黑琵第15輯徵文暨封面徵圖比賽', '臺南市兒童文學年度盛事「小黑琵」徵文暨徵圖比賽讓臺南的國小師生能擁有全臺獨一無二的文學創作天地，以童詩、童話創意改編、散文、心得寫作、遊記與封面徵圖六大類評選出前三名及佳作作品，精選作品將收錄於臺南市兒童文學創作專輯《小黑琵第15輯》中。市民朋友透過作品更加認識臺南的在地文化與特色，感受臺南兒童文學豐盛的童趣!', '臺南市政府教育局', '臺南市全區域', '2025-01-01 00:00:00', '2025-10-31 00:00:00', '臺南市', '無資料', '無資料', '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺南市兒童文學創作專輯小黑琵第15輯徵文暨封面徵圖比賽', `description`='臺南市兒童文學年度盛事「小黑琵」徵文暨徵圖比賽讓臺南的國小師生能擁有全臺獨一無二的文學創作天地，以童詩、童話創意改編、散文、心得寫作、遊記與封面徵圖六大類評選出前三名及佳作作品，精選作品將收錄於臺南市兒童文學創作專輯《小黑琵第15輯》中。市民朋友透過作品更加認識臺南的在地文化與特色，感受臺南兒童文學豐盛的童趣!', `organizer`='臺南市政府教育局', `address`='臺南市全區域', `start_date`='2025-01-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='臺南市', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
