INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fc27f026b3242b74a3b070', '來恆春擁抱宇宙 《張正傑狂想音樂會-美猴王鬧場》', '微風栩栩的週末午後，起身出發恆春，徜徉在大自然的春光裡。 放鬆身心，隨著音樂搖曳身軀，跟著演出開懷大笑；動動身體，隨著瑜伽流動，將身體交給大地；夜幕降臨，五感全開，跟著屏東星空大使「施世治」一起悠遊星海\r\n線上報名 https://reurl.cc/knEVnG \r\n春之星空野餐 x 親子音樂會 ☆ 活動亮點 \r\n🔹 張正傑大提琴音樂會\r\n🔸「美猴王鬧場」互動體驗 \r\n🔹 天幕親子草地瑜伽 \r\n🔸 星空野餐 / 有獎徵答 \r\n🔹 一生一定要約會一次的滿天星斗', '屏東縣政府', '屏東縣恆春鎮', '2025-05-03 00:00:00', '2025-05-04 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='來恆春擁抱宇宙 《張正傑狂想音樂會-美猴王鬧場》', `description`='微風栩栩的週末午後，起身出發恆春，徜徉在大自然的春光裡。 放鬆身心，隨著音樂搖曳身軀，跟著演出開懷大笑；動動身體，隨著瑜伽流動，將身體交給大地；夜幕降臨，五感全開，跟著屏東星空大使「施世治」一起悠遊星海\r\n線上報名 https://reurl.cc/knEVnG \r\n春之星空野餐 x 親子音樂會 ☆ 活動亮點 \r\n🔹 張正傑大提琴音樂會\r\n🔸「美猴王鬧場」互動體驗 \r\n🔹 天幕親子草地瑜伽 \r\n🔸 星空野餐 / 有獎徵答 \r\n🔹 一生一定要約會一次的滿天星斗', `organizer`='屏東縣政府', `address`='屏東縣恆春鎮', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fc27f026b3242b74a3b071', '來恆春擁抱宇宙 《在鵝鑾鼻霸佔星星》', '鵝鑾鼻燈塔前的草地，在夜色籠罩下，成為一場夢幻音樂會的舞台。\r\n悠揚的旋律在海風中飄蕩，與遠方浪濤聲交織，營造出寧靜而動人的氛圍。音樂聲中，人們仰望夜空，欣賞璀璨星辰，如同夜幕中的寶石。這一刻，天地相映，歷史與星光交錯，恰逢恆春古城建城150年，這座古老城鎮的歲月痕跡，也彷彿在星光下閃閃發亮，訴說著過去與未來的故事。', '屏東縣政府', '屏東縣恆春鎮', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '恆春鎮（屏東縣）=', 21.98531645, 120.7632537, '保證金+100', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='來恆春擁抱宇宙 《在鵝鑾鼻霸佔星星》', `description`='鵝鑾鼻燈塔前的草地，在夜色籠罩下，成為一場夢幻音樂會的舞台。\r\n悠揚的旋律在海風中飄蕩，與遠方浪濤聲交織，營造出寧靜而動人的氛圍。音樂聲中，人們仰望夜空，欣賞璀璨星辰，如同夜幕中的寶石。這一刻，天地相映，歷史與星光交錯，恰逢恆春古城建城150年，這座古老城鎮的歲月痕跡，也彷彿在星光下閃閃發亮，訴說著過去與未來的故事。', `organizer`='屏東縣政府', `address`='屏東縣恆春鎮', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='恆春鎮（屏東縣）=', `latitude`=21.98531645, `longitude`=120.7632537, `ticket_price`='保證金+100', `source_url`='無資料', `image_url`='[]';
