INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fc27f026b3242b74a3b074', '2024 Openbook好書獎書展', '2024年Openbook好書獎得獎書展\r\n\r\n展出期間 2025/04/01 - 2025/4/30\r\nOpenbook閱讀誌每週選書小組與童書選書小組，自2023年11月1日至2024年10月31日，共計閱讀2521本書，精選出202本優質作品入圍決選。最終評選出Openbook年度選書推薦給讀者，獎項分別為「年度中文創作」、「年度翻譯書」、「年度生活書」、「年度青少年圖書」及「年度童書」，合計共選出了40本精彩的年度好書。\r\n\r\n讓我們一同探索最新年度的精彩得獎作品，感受閱讀的奇妙旅程。展出期間不外借，歡迎大家來看書！', '彰化縣田中鎮立圖書館', '彰化縣田中鎮中新路229號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '彰化縣田中鎮立圖書館', 23.85723872, 120.5903471, '無資料', 'https://www.facebook.com/TianchungLibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2024 Openbook好書獎書展', `description`='2024年Openbook好書獎得獎書展\r\n\r\n展出期間 2025/04/01 - 2025/4/30\r\nOpenbook閱讀誌每週選書小組與童書選書小組，自2023年11月1日至2024年10月31日，共計閱讀2521本書，精選出202本優質作品入圍決選。最終評選出Openbook年度選書推薦給讀者，獎項分別為「年度中文創作」、「年度翻譯書」、「年度生活書」、「年度青少年圖書」及「年度童書」，合計共選出了40本精彩的年度好書。\r\n\r\n讓我們一同探索最新年度的精彩得獎作品，感受閱讀的奇妙旅程。展出期間不外借，歡迎大家來看書！', `organizer`='彰化縣田中鎮立圖書館', `address`='彰化縣田中鎮中新路229號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='彰化縣田中鎮立圖書館', `latitude`=23.85723872, `longitude`=120.5903471, `ticket_price`='無資料', `source_url`='https://www.facebook.com/TianchungLibrary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fc27f026b3242b74a3b075', '2025年【田中鎮立圖書館-母語傳情—台語親子共讀活動】共3場', '母語傳情—台語親子共讀活動 報名自4/1開始囉！\r\n親愛的家長與長輩朋友們，誠摯邀請您與孩子（或孫子女）一同參加這場充滿溫馨又有趣的「母語傳情—台語親子共讀活動」，在故事與手作的美好時光中，一起感受台語的魅力！\r\n\r\n活動內容與時間\r\n本活動共舉辦三場次，每場皆由專業母語講師精選一本台語繪本或童書，帶領親子共讀，並搭配手作DIY，從閱讀中探索故事背後的文化與語言之美。\r\n第一場次：114年4月26日（六）上午 8:30 - 11:30\r\n第二場次：114年5月3日（六）上午 8:30 - 11:30\r\n第三場次：114年5月17日（六）上午 8:30 - 11:30\r\n活動地點：田中鎮立圖書館 2 樓藝文展覽會議室', '彰化縣田中鎮立圖書館', '彰化縣田中鎮中新路229號', '2025-04-26 00:00:00', '2025-05-17 00:00:00', '彰化縣田中鎮立圖書館', 23.85723872, 120.5903471, '無資料', 'https://www.facebook.com/TianchungLibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年【田中鎮立圖書館-母語傳情—台語親子共讀活動】共3場', `description`='母語傳情—台語親子共讀活動 報名自4/1開始囉！\r\n親愛的家長與長輩朋友們，誠摯邀請您與孩子（或孫子女）一同參加這場充滿溫馨又有趣的「母語傳情—台語親子共讀活動」，在故事與手作的美好時光中，一起感受台語的魅力！\r\n\r\n活動內容與時間\r\n本活動共舉辦三場次，每場皆由專業母語講師精選一本台語繪本或童書，帶領親子共讀，並搭配手作DIY，從閱讀中探索故事背後的文化與語言之美。\r\n第一場次：114年4月26日（六）上午 8:30 - 11:30\r\n第二場次：114年5月3日（六）上午 8:30 - 11:30\r\n第三場次：114年5月17日（六）上午 8:30 - 11:30\r\n活動地點：田中鎮立圖書館 2 樓藝文展覽會議室', `organizer`='彰化縣田中鎮立圖書館', `address`='彰化縣田中鎮中新路229號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='彰化縣田中鎮立圖書館', `latitude`=23.85723872, `longitude`=120.5903471, `ticket_price`='無資料', `source_url`='https://www.facebook.com/TianchungLibrary', `image_url`='[]';
