INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fc27f126b3242b74a3b07d', '天韻乙巳麟洛鄉福聖宮重建啟開金門入火安座20週年慶典音樂晚會', '音樂晚會將由深耕屏東的「在地音緣勞費亞TEAM」策劃執行，號召由楊壽雲及指導老師創團的《樂樂勞費亞大型樂團》、《新海威歌友社》、《麟洛樂樂薩風族》、《薩Kiss瘋樂團》，《康乃馨阿菲力卡團隊》，《在地音緣勞費亞TEAM》等在地團體，演出人員從75歲長者到10歲孩童，逾60名表演者齊聚一堂。陣容橫跨大型管樂團（25-30人）、中型管樂團（12人），並融合西洋經典歌曲、義大利民謠、流行金曲、客家山歌、台語歌謠等多元曲風，還有特別為活動量身打造重新編曲的曲目，展現麟洛豐沛的音樂創作及表演能量。', '屏東縣麟洛鄉福聖宮管理委員會', '屏東縣麟洛鄉', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '麟洛鄉（屏東縣）=', 22.64876367, 120.5299693, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='天韻乙巳麟洛鄉福聖宮重建啟開金門入火安座20週年慶典音樂晚會', `description`='音樂晚會將由深耕屏東的「在地音緣勞費亞TEAM」策劃執行，號召由楊壽雲及指導老師創團的《樂樂勞費亞大型樂團》、《新海威歌友社》、《麟洛樂樂薩風族》、《薩Kiss瘋樂團》，《康乃馨阿菲力卡團隊》，《在地音緣勞費亞TEAM》等在地團體，演出人員從75歲長者到10歲孩童，逾60名表演者齊聚一堂。陣容橫跨大型管樂團（25-30人）、中型管樂團（12人），並融合西洋經典歌曲、義大利民謠、流行金曲、客家山歌、台語歌謠等多元曲風，還有特別為活動量身打造重新編曲的曲目，展現麟洛豐沛的音樂創作及表演能量。', `organizer`='屏東縣麟洛鄉福聖宮管理委員會', `address`='屏東縣麟洛鄉', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='麟洛鄉（屏東縣）=', `latitude`=22.64876367, `longitude`=120.5299693, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
