INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fc27f126b3242b74a3b085', '醬人。釀時光/屏東客家味个守藝人', '穿越時空，品味客家族群三百年來的釀造智慧\r\n整個展場，瀰漫著屏東釀醬的香味(๑´ڡ`๑)\r\n꒰ 有哪些展區👀 ꒱\r\n🔸歲月之釀🔸技藝之釀🔸玩醬達人🔸屏東名醬\r\n꒰ 展現六堆醬人精神的玩味特展👀 ꒱\r\n一甕老醬，釀的是歲月\r\n一段故事，說的是地方味\r\n現場還有互動遊戲區，玩醬達人就是你！\r\n讓我們一起回味最熟悉的屏東味ꔛ‬♡‪', '屏東縣政府', '屏東縣屏東市菸廠路1號', '2025-04-08 00:00:00', '2025-10-26 00:00:00', '屏菸1936文化基地', 22.6647375, 120.4799948, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='醬人。釀時光/屏東客家味个守藝人', `description`='穿越時空，品味客家族群三百年來的釀造智慧\r\n整個展場，瀰漫著屏東釀醬的香味(๑´ڡ`๑)\r\n꒰ 有哪些展區👀 ꒱\r\n🔸歲月之釀🔸技藝之釀🔸玩醬達人🔸屏東名醬\r\n꒰ 展現六堆醬人精神的玩味特展👀 ꒱\r\n一甕老醬，釀的是歲月\r\n一段故事，說的是地方味\r\n現場還有互動遊戲區，玩醬達人就是你！\r\n讓我們一起回味最熟悉的屏東味ꔛ‬♡‪', `organizer`='屏東縣政府', `address`='屏東縣屏東市菸廠路1號', `start_date`='2025-04-08 00:00:00', `end_date`='2025-10-26 00:00:00', `location`='屏菸1936文化基地', `latitude`=22.6647375, `longitude`=120.4799948, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fc64cb8f15101f86006e01', '彩雲講堂－音樂與世界遺產系列講座', '文化是時間流逝中的永恆印記，見證人類文明的興衰與重生，而音樂則是傳承這份記錄最溫暖的聲音。自古以來，音樂與文化密不可分，不僅跨越語言與疆界的限制，更承載著一個民族的靈魂與記憶。\r\n\r\n音樂以獨有的魅力傳遞情感，將過去與現在串連在一起。文化則凝結了人類智慧的結晶，是精神和物質生活的見證與寫照。今年彩雲講堂我們特別邀請前金革唱片林伯杰音樂總監，以及世界遺產深度領隊馬繼康老師，帶領大家來一趟｢音樂與世界文化遺產｣的探知之旅，誠摯邀請您與我們一起透過講座，回憶你我生命中最熟悉的歌，並在旋律與文化的交織中，傾聽歷史的低語，感受歲月的痕跡。\r\n', '麗寶文化藝術基金會', '臺北市信義區菸廠路88號B1', '2025-05-02 00:00:00', '2025-05-02 00:00:00', '松菸誠品表演廳', 25.03062083, 121.5716697, '無資料', 'http://www.lihpao.org.tw/register1.php', '[]') ON DUPLICATE KEY UPDATE `activity_name`='彩雲講堂－音樂與世界遺產系列講座', `description`='文化是時間流逝中的永恆印記，見證人類文明的興衰與重生，而音樂則是傳承這份記錄最溫暖的聲音。自古以來，音樂與文化密不可分，不僅跨越語言與疆界的限制，更承載著一個民族的靈魂與記憶。\r\n\r\n音樂以獨有的魅力傳遞情感，將過去與現在串連在一起。文化則凝結了人類智慧的結晶，是精神和物質生活的見證與寫照。今年彩雲講堂我們特別邀請前金革唱片林伯杰音樂總監，以及世界遺產深度領隊馬繼康老師，帶領大家來一趟｢音樂與世界文化遺產｣的探知之旅，誠摯邀請您與我們一起透過講座，回憶你我生命中最熟悉的歌，並在旋律與文化的交織中，傾聽歷史的低語，感受歲月的痕跡。\r\n', `organizer`='麗寶文化藝術基金會', `address`='臺北市信義區菸廠路88號B1', `start_date`='2025-05-02 00:00:00', `end_date`='2025-05-02 00:00:00', `location`='松菸誠品表演廳', `latitude`=25.03062083, `longitude`=121.5716697, `ticket_price`='無資料', `source_url`='http://www.lihpao.org.tw/register1.php', `image_url`='[]';
