INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd788d26b3242b74a3b09e', '【新北市立圖書館泰山分館】享繡․植感生活-李安琪個展', '藝術家 安琪運用刺繡工藝與植物為元素，層層堆疊在夢幻與現實的時空中交融，讓觀者透過多元的視角，探索這富饒的植感生活。從中發現鳥鳴宛如天籟，植物在微風中輕輕搖曳，灑落而下的光，映照出無限的生命脈動與美好的四季。享受以愛交織讓內心的波動與自然萬物相繫。', '新北市立圖書館總館', '新北市泰山區全興路212號5樓', '2025-03-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館泰山分館', 25.05549774, 121.4162785, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館泰山分館】享繡․植感生活-李安琪個展', `description`='藝術家 安琪運用刺繡工藝與植物為元素，層層堆疊在夢幻與現實的時空中交融，讓觀者透過多元的視角，探索這富饒的植感生活。從中發現鳥鳴宛如天籟，植物在微風中輕輕搖曳，灑落而下的光，映照出無限的生命脈動與美好的四季。享受以愛交織讓內心的波動與自然萬物相繫。', `organizer`='新北市立圖書館總館', `address`='新北市泰山區全興路212號5樓', `start_date`='2025-03-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館泰山分館', `latitude`=25.05549774, `longitude`=121.4162785, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd789c26b3242b74a3b09f', '【新北市青少年圖書館】4/1(二)-4/30(三) 涵情墨墨', '此次展覽是由崇光社區大學「多元美學的水墨繪畫班」的學員成果展。從兩年前未接觸過水墨畫的學員們到能從容悠遊於水墨之間，在學習山水畫中體會到「萬物靜觀皆自得」，從中體認到繪畫需仔細觀察、訓練專注，培養美學素養，能使生活更加充實愉悅，是學員們學習水墨畫最大的目的。', '新北市立圖書館總館', '新北市新店區安康路2段151號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市青少年圖書館', 24.93039008, 121.5316565, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市青少年圖書館】4/1(二)-4/30(三) 涵情墨墨', `description`='此次展覽是由崇光社區大學「多元美學的水墨繪畫班」的學員成果展。從兩年前未接觸過水墨畫的學員們到能從容悠遊於水墨之間，在學習山水畫中體會到「萬物靜觀皆自得」，從中體認到繪畫需仔細觀察、訓練專注，培養美學素養，能使生活更加充實愉悅，是學員們學習水墨畫最大的目的。', `organizer`='新北市立圖書館總館', `address`='新北市新店區安康路2段151號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市青少年圖書館', `latitude`=24.93039008, `longitude`=121.5316565, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78a126b3242b74a3b0a0', '三重社區大學「起心動念 靈創繪畫聯展」', '新北市三重地政事務所為營造優質洽公環境、提供藝文交流場域，邀請三重社區大學合作舉辦「起心動念 靈創繪畫聯展」，展期自114年4月1日起至6月30日止，歡迎市民蒞臨參觀。', '新北市三重地政事務所', '新北市三重區', '2025-04-01 00:00:00', '2025-06-30 00:00:00', '三重區（新北市）=', 25.06281651, 121.4870977, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三重社區大學「起心動念 靈創繪畫聯展」', `description`='新北市三重地政事務所為營造優質洽公環境、提供藝文交流場域，邀請三重社區大學合作舉辦「起心動念 靈創繪畫聯展」，展期自114年4月1日起至6月30日止，歡迎市民蒞臨參觀。', `organizer`='新北市三重地政事務所', `address`='新北市三重區', `start_date`='2025-04-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='三重區（新北市）=', `latitude`=25.06281651, `longitude`=121.4870977, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78af26b3242b74a3b0a1', '池藝基地｜赤籽— 晒到赤赤', '池地之上的豐水沃田間有一群人，\r\n懷擁著極具生命力的赤色籽苗，\r\n在東部曙光的日與日間將其曬得通赤，\r\n力行不輟以赤子之身染南方之色。\r\n這群人，\r\n不在無意識地追趕中，\r\n拼湊轉瞬即逝的花團錦簇，\r\n而是在有意識的積累中，\r\n匯成滋養一方的上善若水；\r\n這群人，\r\n以此點滴澆灌內在的赤籽，\r\n並在此地一域，\r\n謙謙種下不息生命的能量初始；他們，\r\n裸心無藏，\r\n晒到赤赤。\r\n\r\n／聯展藝術家／\r\n\r\n王金生 多媒材燈具\r\n王新蓮 多媒材抽象畫\r\n李素雲 刺繡 ( 池上雲繡 )\r\n依本 裝置藝術\r\n徐沐藍 藍染與手作 ( 沐藍池上 )\r\n莊月嬌 創意食作 ( 嬌食手作食堂 )\r\n彭明通 木刻與裝置 ( 山凹工作室 )\r\n彭柏瑋 蠟畫 ( 4.5公里工作室 )\r\n潘韋如 蠟作 ( is well | 山山來池)\r\n羅正傑 影像紀錄 ( 走走池上｜島嶼東方 )\r\n\r\n游云旨 策展人\r\n牛韻茹 策展人 與談人\r\n李威萱 書道字\r\n\r\n／展覽地點——池上藝術長工基地／\r\n\r\n『巷弄池上 藝術住⺠』\r\n\r\n池上獨特的藝⽂底蘊，緊貼著⼟地和⽣活的脈動，就像在此安⾝立命的居⺠⼀般，寬厚、踏實，且不張揚。\r\n\r\n在這個知名的藝⽂⽶鄉裡，住了⼀群藝術⼯作者，他們有些出生本地，有些從外地移居⽽來，在池上落腳⽣根，實踐獨⼀無⼆的⽣活美學；⼀如勤奮的池上農⺠，在天地間默默耕耘，向下紮根，⼀同眷顧池上的美與善。\r\n\r\n這群棲居於池上巷弄的藝術⼯作者，稱⾃⼰為池上的藝術長⼯，而這個空間——「池上藝術長⼯基地」簡稱「池藝基地」，便是由這群熱愛池上的藝術⼯作者經營。此一實驗展場，將作為多功能展演空間和藝術交流的基地，持續推廣池上特有的⽣活美學。\r\n\r\n• 展覽開展日期：2025/01/10\r\n\r\n• 展覽地點：臺東縣池上鄉中正路10號（池上火車站站前）', '池上藝術長工基地', '臺東縣池上鄉', '2025-01-10 00:00:00', '2025-12-31 00:00:00', '池上鄉（臺東縣）=', 23.09248714, 121.2184501, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='池藝基地｜赤籽— 晒到赤赤', `description`='池地之上的豐水沃田間有一群人，\r\n懷擁著極具生命力的赤色籽苗，\r\n在東部曙光的日與日間將其曬得通赤，\r\n力行不輟以赤子之身染南方之色。\r\n這群人，\r\n不在無意識地追趕中，\r\n拼湊轉瞬即逝的花團錦簇，\r\n而是在有意識的積累中，\r\n匯成滋養一方的上善若水；\r\n這群人，\r\n以此點滴澆灌內在的赤籽，\r\n並在此地一域，\r\n謙謙種下不息生命的能量初始；他們，\r\n裸心無藏，\r\n晒到赤赤。\r\n\r\n／聯展藝術家／\r\n\r\n王金生 多媒材燈具\r\n王新蓮 多媒材抽象畫\r\n李素雲 刺繡 ( 池上雲繡 )\r\n依本 裝置藝術\r\n徐沐藍 藍染與手作 ( 沐藍池上 )\r\n莊月嬌 創意食作 ( 嬌食手作食堂 )\r\n彭明通 木刻與裝置 ( 山凹工作室 )\r\n彭柏瑋 蠟畫 ( 4.5公里工作室 )\r\n潘韋如 蠟作 ( is well | 山山來池)\r\n羅正傑 影像紀錄 ( 走走池上｜島嶼東方 )\r\n\r\n游云旨 策展人\r\n牛韻茹 策展人 與談人\r\n李威萱 書道字\r\n\r\n／展覽地點——池上藝術長工基地／\r\n\r\n『巷弄池上 藝術住⺠』\r\n\r\n池上獨特的藝⽂底蘊，緊貼著⼟地和⽣活的脈動，就像在此安⾝立命的居⺠⼀般，寬厚、踏實，且不張揚。\r\n\r\n在這個知名的藝⽂⽶鄉裡，住了⼀群藝術⼯作者，他們有些出生本地，有些從外地移居⽽來，在池上落腳⽣根，實踐獨⼀無⼆的⽣活美學；⼀如勤奮的池上農⺠，在天地間默默耕耘，向下紮根，⼀同眷顧池上的美與善。\r\n\r\n這群棲居於池上巷弄的藝術⼯作者，稱⾃⼰為池上的藝術長⼯，而這個空間——「池上藝術長⼯基地」簡稱「池藝基地」，便是由這群熱愛池上的藝術⼯作者經營。此一實驗展場，將作為多功能展演空間和藝術交流的基地，持續推廣池上特有的⽣活美學。\r\n\r\n• 展覽開展日期：2025/01/10\r\n\r\n• 展覽地點：臺東縣池上鄉中正路10號（池上火車站站前）', `organizer`='池上藝術長工基地', `address`='臺東縣池上鄉', `start_date`='2025-01-10 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='池上鄉（臺東縣）=', `latitude`=23.09248714, `longitude`=121.2184501, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78b326b3242b74a3b0a2', '自強書法班年度成果展', '自強里的里民們平日齊聚活動中心，在專業老師的指導下，專心練習書法，將每一筆每一劃都融入心力與專注。此次展覽包含唐詩、宋詞等作品，每一幅都是學員們努力與用心的成果！', '新北市汐止區公所', '新北市汐止區新台五路一段268號', '2025-03-03 00:00:00', '2025-05-30 00:00:00', '新北市汐止區公所行政大樓', 25.07331322, 121.6546992, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='自強書法班年度成果展', `description`='自強里的里民們平日齊聚活動中心，在專業老師的指導下，專心練習書法，將每一筆每一劃都融入心力與專注。此次展覽包含唐詩、宋詞等作品，每一幅都是學員們努力與用心的成果！', `organizer`='新北市汐止區公所', `address`='新北市汐止區新台五路一段268號', `start_date`='2025-03-03 00:00:00', `end_date`='2025-05-30 00:00:00', `location`='新北市汐止區公所行政大樓', `latitude`=25.07331322, `longitude`=121.6546992, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
