INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78c226b3242b74a3b0a6', '2025臺東電音派對', '2025 臺東電音派對\r\n⚡️Monster E-Tiyaland⚡️\r\n強勢回歸!大家期待的超人氣卡司正式揭曉🎉\r\n來自韓國的電音和尚 DJ日進大師\r\n有著音樂魔術師之稱的韓國音樂鬼才 DJ JASON\r\n擁有全球各大電音節演出經驗的 DJ A-DA\r\n活力動感著稱的甜心 DJ Molly\r\n臺東之光女神 DJ JANICE\r\n甜辣系動感女神 DJ Victoria\r\n連續入選PYRO百大MC的_MC KTWO\r\n金曲獎最佳原住民語歌手獎、評審團獎的原住民歌手_葛西瓦\r\n當然不只這樣啦😎😎結合台東的在地特色，呈現跨界合作演出🙌🙌🙌\r\n來自台東在地硬實力團體「V字輩 」、「海盜舞團」\r\n充滿力量與節奏的饒舌音樂點燃全場🔥\r\n⋯⋯✧⋯⋯⋯⋯✧⋯⋯⋯⋯✧⋯⋯⋯⋯✧⋯⋯\r\n👉活動日期：04月19日(六)\r\n👉活動地點：臺東森林公園\r\n👉活動時間：14:00~22:00\r\n👉免費入場\r\n⋯⋯✧⋯⋯⋯⋯✧⋯⋯⋯⋯✧⋯⋯⋯⋯✧⋯⋯', '臺東縣政府', '臺東縣臺東市華泰路300號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '臺東森林公園', 22.75165721, 121.1103647, '無資料', 'https://www.facebook.com/profile.php?id=61566386590164', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺東電音派對', `description`='2025 臺東電音派對\r\n⚡️Monster E-Tiyaland⚡️\r\n強勢回歸!大家期待的超人氣卡司正式揭曉🎉\r\n來自韓國的電音和尚 DJ日進大師\r\n有著音樂魔術師之稱的韓國音樂鬼才 DJ JASON\r\n擁有全球各大電音節演出經驗的 DJ A-DA\r\n活力動感著稱的甜心 DJ Molly\r\n臺東之光女神 DJ JANICE\r\n甜辣系動感女神 DJ Victoria\r\n連續入選PYRO百大MC的_MC KTWO\r\n金曲獎最佳原住民語歌手獎、評審團獎的原住民歌手_葛西瓦\r\n當然不只這樣啦😎😎結合台東的在地特色，呈現跨界合作演出🙌🙌🙌\r\n來自台東在地硬實力團體「V字輩 」、「海盜舞團」\r\n充滿力量與節奏的饒舌音樂點燃全場🔥\r\n⋯⋯✧⋯⋯⋯⋯✧⋯⋯⋯⋯✧⋯⋯⋯⋯✧⋯⋯\r\n👉活動日期：04月19日(六)\r\n👉活動地點：臺東森林公園\r\n👉活動時間：14:00~22:00\r\n👉免費入場\r\n⋯⋯✧⋯⋯⋯⋯✧⋯⋯⋯⋯✧⋯⋯⋯⋯✧⋯⋯', `organizer`='臺東縣政府', `address`='臺東縣臺東市華泰路300號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='臺東森林公園', `latitude`=22.75165721, `longitude`=121.1103647, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=61566386590164', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78ce26b3242b74a3b0a7', '【新北市立圖書館瑞芳分館】4月瑞芳區議長盃國小繪畫得獎作品展', '【瑞芳分館】4月瑞芳區議長盃國小繪畫得獎作品展\r\n提升新北市偏遠地區平溪、貢寮、雙溪、瑞芳四區兒童創作風氣與繪畫技巧，\r\n透過辦理得獎作品展啟發學生的潛能與創造力，並為學生創造多元智慧展能。\r\n \r\n展覽單位: 瑞芳國小\r\n展覽時間: 4/2(三)—4/25(五)\r\n展覽地點: 瑞芳分館/2樓展覽區   ', '新北市立圖書館總館', '新北市瑞芳區民權街17號2樓', '2025-04-02 00:00:00', '2025-04-25 00:00:00', '新北市立圖書館瑞芳分館', 25.0981293, 121.8232018, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館瑞芳分館】4月瑞芳區議長盃國小繪畫得獎作品展', `description`='【瑞芳分館】4月瑞芳區議長盃國小繪畫得獎作品展\r\n提升新北市偏遠地區平溪、貢寮、雙溪、瑞芳四區兒童創作風氣與繪畫技巧，\r\n透過辦理得獎作品展啟發學生的潛能與創造力，並為學生創造多元智慧展能。\r\n \r\n展覽單位: 瑞芳國小\r\n展覽時間: 4/2(三)—4/25(五)\r\n展覽地點: 瑞芳分館/2樓展覽區   ', `organizer`='新北市立圖書館總館', `address`='新北市瑞芳區民權街17號2樓', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='新北市立圖書館瑞芳分館', `latitude`=25.0981293, `longitude`=121.8232018, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d126b3242b74a3b0a9', '《保溫箱的藝術家音樂劇》', '《保溫箱的藝術家音樂劇》\r\n《保溫箱的藝術家》是全臺首齣由視障音樂人演出的原創音樂劇，由五位來自不同背景，擅長不同音樂風格的視障者，將他們的音樂故事，以百老匯的音樂型態編織成一部輕鬆幽默的音樂劇， 呈現他們內心完整的生命意義。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n基本上、開始的地方、當光點亮、流行組曲、保溫箱的藝術家、原諒、怎麼安慰一個朋友、No就是Yes的開始、橄欖樹、荒唐世界、Funky Night\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n製作人｜楊嘉、王晴紋 \r\n\r\n導演 / 戲劇指導｜林英杰 (Josh) \r\n\r\n編劇｜楊嘉、EyeMusic、林英杰 \r\n\r\n演員｜EyeMusic—王嬿甯、劉子瑜、江尉綺、陸羿丞、陳威辰 \r\n\r\n特別來賓｜姚黛瑋 \r\n\r\n音樂總監｜黃柏勳\r\n\r\n影像指導 / 監製｜周正隆、沈洛伊\r\n\r\n舞台總監｜闕聰華\r\n\r\n音響工程｜穩立音響\r\n\r\n燈光設計｜許小光\r\n\r\n舞台設計｜吳修和', '社團法人中華民國視障者家長協會', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-04-18 00:00:00', '2025-04-20 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+800;--+1600;--+2000;--+2500;--+3000', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《保溫箱的藝術家音樂劇》', `description`='《保溫箱的藝術家音樂劇》\r\n《保溫箱的藝術家》是全臺首齣由視障音樂人演出的原創音樂劇，由五位來自不同背景，擅長不同音樂風格的視障者，將他們的音樂故事，以百老匯的音樂型態編織成一部輕鬆幽默的音樂劇， 呈現他們內心完整的生命意義。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n基本上、開始的地方、當光點亮、流行組曲、保溫箱的藝術家、原諒、怎麼安慰一個朋友、No就是Yes的開始、橄欖樹、荒唐世界、Funky Night\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n製作人｜楊嘉、王晴紋 \r\n\r\n導演 / 戲劇指導｜林英杰 (Josh) \r\n\r\n編劇｜楊嘉、EyeMusic、林英杰 \r\n\r\n演員｜EyeMusic—王嬿甯、劉子瑜、江尉綺、陸羿丞、陳威辰 \r\n\r\n特別來賓｜姚黛瑋 \r\n\r\n音樂總監｜黃柏勳\r\n\r\n影像指導 / 監製｜周正隆、沈洛伊\r\n\r\n舞台總監｜闕聰華\r\n\r\n音響工程｜穩立音響\r\n\r\n燈光設計｜許小光\r\n\r\n舞台設計｜吳修和', `organizer`='社團法人中華民國視障者家長協會', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-04-18 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+800;--+1600;--+2000;--+2500;--+3000', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d126b3242b74a3b0ab', '《小店．小偷．小豬探！》', '《小店．小偷．小豬探！》\r\n"La Du Lu Du Du Du Lu Lu La La~你也會唱了嗎？\r\n\r\n最令人朗朗上口的主題曲，俏皮的歌詞，加上洗腦的旋律，讓小偵探們聽過一次就會唱 當豬探長還沒長大，朋友都叫他小豬探！他立志以後要當一個超厲害的大偵探！\r\n\r\n《小店．小偷．小豬探！》是豬探長小時候的故事，他就跟大家一樣，喜歡和好朋友玩、喜歡吃糖果和冰淇淋，有點傻氣、有點純真，也有膽小的時候！\r\n\r\n 除了有精彩的歌舞，還有可愛的劇情和大家最愛的互動體驗環節，以及豬探長系列絕不能少的推理解謎。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n如果兒童劇團\r\n\r\n ', '如果兒童劇團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+400;--+600;--+1000;--+1200', 'https://tixfun.com/UTK0101_', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《小店．小偷．小豬探！》', `description`='《小店．小偷．小豬探！》\r\n"La Du Lu Du Du Du Lu Lu La La~你也會唱了嗎？\r\n\r\n最令人朗朗上口的主題曲，俏皮的歌詞，加上洗腦的旋律，讓小偵探們聽過一次就會唱 當豬探長還沒長大，朋友都叫他小豬探！他立志以後要當一個超厲害的大偵探！\r\n\r\n《小店．小偷．小豬探！》是豬探長小時候的故事，他就跟大家一樣，喜歡和好朋友玩、喜歡吃糖果和冰淇淋，有點傻氣、有點純真，也有膽小的時候！\r\n\r\n 除了有精彩的歌舞，還有可愛的劇情和大家最愛的互動體驗環節，以及豬探長系列絕不能少的推理解謎。\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n如果兒童劇團\r\n\r\n ', `organizer`='如果兒童劇團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+400;--+600;--+1000;--+1200', `source_url`='https://tixfun.com/UTK0101_', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d126b3242b74a3b0ad', '【2025衛武營國際音樂節】《局外人：哈利．帕奇的故事》紀錄片放映暨座談會', '【2025衛武營國際音樂節】《局外人：哈利．帕奇的故事》紀錄片放映暨座談會\r\n為了⾃由⽽選擇逃逸、⾃⾳樂⾄⼈⽣皆然——《局外人：哈利．帕奇的故事》記述廿世紀美國先鋒派作曲家、⾳樂理論家乃⾄樂器發明家哈利．帕奇的⾳樂哲思與⼈⽣軌跡。\r\n\r\n與其說激進、更好的⽤詞或許是解放——解放聲⾳、也從⼈⽣常軌解放：他逃逸於⼗⼆⾳的陳舊桎梏，以純律為基⽯、開展出以微分⾳為特⾊的獨特⾳樂，為此，他設計出全新樂器與記譜法以實現其對聲⾳的想像，並追求建構於「⾝體性」之上的展演形式。\r\n\r\n帕奇認為「真相總是威脅既有階級。」為了追求⾳樂與⼈⽣的真，他⽢於成為局外⼈、以獲得真正的⾃由，這不僅是部⾳樂家的紀錄⽚，其哲理更⾜以啟迪我們的⼈⽣。紀錄⽚將於放映後進⾏映後座談，相信能夠帶領您認識這改變當代⾳樂聲景的逃逸者。\r\n\r\n \r\n\r\n   立即報名   \r\n\r\n \r\n\r\n  映後座談  \r\n\r\n2025/4/19(六)17:40 演講廳\r\n\r\n與談人｜奧古絲塔・里德・托瑪斯\r\n\r\n主持人｜陳宜貞\r\n\r\n \r\n\r\n  報名方式  \r\n\r\n參加對象：歡迎喜愛藝術人文活動的朋友（建議12歲以上觀眾觀賞）\r\n\r\n報名方式：報名參加，免費入場（限額100名，額滿為止）。\r\n\r\n（線上報名至2025/4/13(日)23:59止，活動優先保留席次予線上報名者；現場將視狀況開放現場報名。）\r\n\r\n報名流程：填寫線上報名表(系統自動發送回函，收到即報名成功) → 於活動前三日，統一寄送活動通知及確認出席統計信件。\r\n\r\n點我報名\r\n\r\n \r\n\r\n  與談人  \r\n\r\n2025衛武營國際音樂節駐節作曲家｜奧古絲塔・里德・托瑪斯 \r\n\r\n奧古絲塔・里德・托瑪斯乃當代最受推崇、影響力深遠且作品廣為演出的作曲家之一。托瑪斯的音樂創作領域廣泛，她曾為冠軍葛萊美專輯創作作品，亦以普立茲決選作品而備受矚目，美國藝術與文學學院形容其創作「體現奔放的熱情與激越的詩意」，並曾於2016年獲評為「芝加哥年度人物」。\r\n\r\n除作為一名活躍的作曲家，其亦投身音樂教育，創立並指導芝加哥大學當代作曲中心及葛羅斯曼室內樂團。近年來，委託托瑪斯創作的各大著名音樂節與樂團包含英國BBC逍遙音樂節、波士頓交響樂團、巴黎愛樂樂團及紐約愛樂樂團等。\r\n\r\n閱讀更多\r\n\r\n\r\n \r\n\r\n   立即報名   \r\n\r\n \r\n\r\n  在地藝文支持夥伴  \r\n\r\n陳啟川先生文教基金會\r\n ', '國家表演藝術中心衛武營國家藝術文化中心', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【2025衛武營國際音樂節】《局外人：哈利．帕奇的故事》紀錄片放映暨座談會', `description`='【2025衛武營國際音樂節】《局外人：哈利．帕奇的故事》紀錄片放映暨座談會\r\n為了⾃由⽽選擇逃逸、⾃⾳樂⾄⼈⽣皆然——《局外人：哈利．帕奇的故事》記述廿世紀美國先鋒派作曲家、⾳樂理論家乃⾄樂器發明家哈利．帕奇的⾳樂哲思與⼈⽣軌跡。\r\n\r\n與其說激進、更好的⽤詞或許是解放——解放聲⾳、也從⼈⽣常軌解放：他逃逸於⼗⼆⾳的陳舊桎梏，以純律為基⽯、開展出以微分⾳為特⾊的獨特⾳樂，為此，他設計出全新樂器與記譜法以實現其對聲⾳的想像，並追求建構於「⾝體性」之上的展演形式。\r\n\r\n帕奇認為「真相總是威脅既有階級。」為了追求⾳樂與⼈⽣的真，他⽢於成為局外⼈、以獲得真正的⾃由，這不僅是部⾳樂家的紀錄⽚，其哲理更⾜以啟迪我們的⼈⽣。紀錄⽚將於放映後進⾏映後座談，相信能夠帶領您認識這改變當代⾳樂聲景的逃逸者。\r\n\r\n \r\n\r\n   立即報名   \r\n\r\n \r\n\r\n  映後座談  \r\n\r\n2025/4/19(六)17:40 演講廳\r\n\r\n與談人｜奧古絲塔・里德・托瑪斯\r\n\r\n主持人｜陳宜貞\r\n\r\n \r\n\r\n  報名方式  \r\n\r\n參加對象：歡迎喜愛藝術人文活動的朋友（建議12歲以上觀眾觀賞）\r\n\r\n報名方式：報名參加，免費入場（限額100名，額滿為止）。\r\n\r\n（線上報名至2025/4/13(日)23:59止，活動優先保留席次予線上報名者；現場將視狀況開放現場報名。）\r\n\r\n報名流程：填寫線上報名表(系統自動發送回函，收到即報名成功) → 於活動前三日，統一寄送活動通知及確認出席統計信件。\r\n\r\n點我報名\r\n\r\n \r\n\r\n  與談人  \r\n\r\n2025衛武營國際音樂節駐節作曲家｜奧古絲塔・里德・托瑪斯 \r\n\r\n奧古絲塔・里德・托瑪斯乃當代最受推崇、影響力深遠且作品廣為演出的作曲家之一。托瑪斯的音樂創作領域廣泛，她曾為冠軍葛萊美專輯創作作品，亦以普立茲決選作品而備受矚目，美國藝術與文學學院形容其創作「體現奔放的熱情與激越的詩意」，並曾於2016年獲評為「芝加哥年度人物」。\r\n\r\n除作為一名活躍的作曲家，其亦投身音樂教育，創立並指導芝加哥大學當代作曲中心及葛羅斯曼室內樂團。近年來，委託托瑪斯創作的各大著名音樂節與樂團包含英國BBC逍遙音樂節、波士頓交響樂團、巴黎愛樂樂團及紐約愛樂樂團等。\r\n\r\n閱讀更多\r\n\r\n\r\n \r\n\r\n   立即報名   \r\n\r\n \r\n\r\n  在地藝文支持夥伴  \r\n\r\n陳啟川先生文教基金會\r\n ', `organizer`='國家表演藝術中心衛武營國家藝術文化中心', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d126b3242b74a3b0ae', '《狂熱大協奏II》', '《狂熱大協奏II》\r\n「狂熱大協奏II」，以巴洛克時期大協奏曲形式做為音樂會曲目框架，內容從巴洛克時期作曲家針對同儕作品，加以改編的大協奏曲，至二十世紀充滿民族風格之大協奏曲、二十一世紀委託台灣新銳作曲家創作具實驗性的作品。本場音樂會將配合解說，讓聽眾可以享受從巴洛克時期至今大協奏曲形式在作曲家筆下產生多元聲響、架構和對比的可能性。期望藉由具主題性，藉由精心選擇的音樂串連東、西文化，由此展現臺灣作曲家和演奏家實力，充分達到「傳承」與「創新」並進之功效。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n阿維森：根據史卡拉第奏鳴曲改寫的十二首大協奏曲，第三號\r\n\r\n李思嫺：對話（之五）：共感\r\n\r\n巴赫：根據韋瓦第雙小提琴協奏曲作品522改寫的A小調鍵盤協奏曲作品596\r\n\r\n布洛赫：第一號大協奏曲\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n委託創作｜李思嫺\r\n\r\n巴洛克獨奏家樂團', '巴洛克獨奏家樂團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+800;--+1200;--+1600;--+2000', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《狂熱大協奏II》', `description`='《狂熱大協奏II》\r\n「狂熱大協奏II」，以巴洛克時期大協奏曲形式做為音樂會曲目框架，內容從巴洛克時期作曲家針對同儕作品，加以改編的大協奏曲，至二十世紀充滿民族風格之大協奏曲、二十一世紀委託台灣新銳作曲家創作具實驗性的作品。本場音樂會將配合解說，讓聽眾可以享受從巴洛克時期至今大協奏曲形式在作曲家筆下產生多元聲響、架構和對比的可能性。期望藉由具主題性，藉由精心選擇的音樂串連東、西文化，由此展現臺灣作曲家和演奏家實力，充分達到「傳承」與「創新」並進之功效。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n阿維森：根據史卡拉第奏鳴曲改寫的十二首大協奏曲，第三號\r\n\r\n李思嫺：對話（之五）：共感\r\n\r\n巴赫：根據韋瓦第雙小提琴協奏曲作品522改寫的A小調鍵盤協奏曲作品596\r\n\r\n布洛赫：第一號大協奏曲\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n委託創作｜李思嫺\r\n\r\n巴洛克獨奏家樂團', `organizer`='巴洛克獨奏家樂團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+800;--+1200;--+1600;--+2000', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d126b3242b74a3b0b0', '《漾》2025李卿碧琵琶獨奏會', '《漾》2025李卿碧琵琶獨奏會\r\n《漾》2025李卿碧琵琶獨奏會，音樂會中演出臺灣、香港兩地作曲家的作品，陳裕剛《將進酒》、許常惠《錦瑟》、張譽馨的《穗》、陸尉俊《彈撥搖滾》，使用琵琶特殊技巧模仿音效，融合現代搖滾風格；大陸作曲家杜咏，琵琶協奏曲《尋˙耶婆瑟雞》描寫龜茲城外的佛教聖地「石窟」淒美愛情故事；而古曲《瀛洲古調》是傳統琵琶崇明派代表作品，透過音樂瞭解琵琶的發展歷史脈絡；並邀請現代作曲家郭靖沐為此場音樂會譜曲。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n《瀛洲古調》文板八首｜古曲  劉德海演奏譜\r\n\r\n《將進酒》｜陳裕剛\r\n\r\n《錦瑟》｜ 許常惠\r\n\r\n《彈撥搖滾》｜陸尉俊\r\n\r\n《穗》｜張譽馨\r\n\r\n《窗》委創首演｜郭靖沐\r\n\r\n《尋˙耶婆瑟雞》｜杜咏\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n製作團隊｜當代藝林樂集 \r\n\r\n演 出｜李卿碧、高韻堯、當代藝林樂集\r\n\r\n導 聆｜黃詩芸', '當代藝林樂集', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《漾》2025李卿碧琵琶獨奏會', `description`='《漾》2025李卿碧琵琶獨奏會\r\n《漾》2025李卿碧琵琶獨奏會，音樂會中演出臺灣、香港兩地作曲家的作品，陳裕剛《將進酒》、許常惠《錦瑟》、張譽馨的《穗》、陸尉俊《彈撥搖滾》，使用琵琶特殊技巧模仿音效，融合現代搖滾風格；大陸作曲家杜咏，琵琶協奏曲《尋˙耶婆瑟雞》描寫龜茲城外的佛教聖地「石窟」淒美愛情故事；而古曲《瀛洲古調》是傳統琵琶崇明派代表作品，透過音樂瞭解琵琶的發展歷史脈絡；並邀請現代作曲家郭靖沐為此場音樂會譜曲。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n《瀛洲古調》文板八首｜古曲  劉德海演奏譜\r\n\r\n《將進酒》｜陳裕剛\r\n\r\n《錦瑟》｜ 許常惠\r\n\r\n《彈撥搖滾》｜陸尉俊\r\n\r\n《穗》｜張譽馨\r\n\r\n《窗》委創首演｜郭靖沐\r\n\r\n《尋˙耶婆瑟雞》｜杜咏\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n製作團隊｜當代藝林樂集 \r\n\r\n演 出｜李卿碧、高韻堯、當代藝林樂集\r\n\r\n導 聆｜黃詩芸', `organizer`='當代藝林樂集', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d226b3242b74a3b0b1', '《二十世紀三首鋼琴協奏曲》', '《二十世紀三首鋼琴協奏曲》\r\n拉赫瑪尼諾夫第四號鋼琴協奏曲充滿戲劇性與深刻情感，融合浪漫與現代風格，展現其晚期創作特色；蓋希文《藍色狂想曲》將古典與爵士結合，充滿城市活力與自由律動，展現美國音樂新風貌。 蕭士塔高維奇第一號鋼琴協奏曲最特別的地方是採用了進行曲和圓舞曲，曲子讓人聯想到羅西尼和米老鼠共舞的滑稽畫面。 \r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n拉赫曼尼諾夫第四號鋼琴協奏曲\r\n\r\n蓋希文《藍色狂想曲》\r\n\r\n蕭士塔高維奇：第一號鋼琴協奏曲，作品35\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n陳介涵\r\n\r\n王一心', '蘭城愛樂', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-04-21 00:00:00', '2025-04-21 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500;--+800;--+1000;--+1200', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《二十世紀三首鋼琴協奏曲》', `description`='《二十世紀三首鋼琴協奏曲》\r\n拉赫瑪尼諾夫第四號鋼琴協奏曲充滿戲劇性與深刻情感，融合浪漫與現代風格，展現其晚期創作特色；蓋希文《藍色狂想曲》將古典與爵士結合，充滿城市活力與自由律動，展現美國音樂新風貌。 蕭士塔高維奇第一號鋼琴協奏曲最特別的地方是採用了進行曲和圓舞曲，曲子讓人聯想到羅西尼和米老鼠共舞的滑稽畫面。 \r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n拉赫曼尼諾夫第四號鋼琴協奏曲\r\n\r\n蓋希文《藍色狂想曲》\r\n\r\n蕭士塔高維奇：第一號鋼琴協奏曲，作品35\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n陳介涵\r\n\r\n王一心', `organizer`='蘭城愛樂', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-04-21 00:00:00', `end_date`='2025-04-21 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500;--+800;--+1000;--+1200', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d226b3242b74a3b0b2', '2025【探索管風琴音樂】《管風琴的夢幻音樂之旅》', '走進衛武營音樂廳，除了驚嘆葡萄園式觀眾席與極佳音響效果外，位於最頂層的管風琴，也是眾人矚目的焦點。\r\n\r\n若是您曾經好奇，這台亞洲最大的音樂廳管風琴，究竟能展現什麼樣的百變樣貌，「探索管風琴音樂」系列活動，將是得到解答的大好機會！\r\n\r\n衛武營特別邀請臺灣專業管風琴家們設計獨家節目，搭配其他樂器以及加入燈光效果等特殊聆賞規劃，加上平易近人的專業解說，展現管風琴的萬千變換與可親可愛。\r\n\r\n活動特別安排「舞台零距離體驗場」將舞台區轉變為觀眾席區，讓您近距離一睹管風琴風采；「自由移動體驗場」在曲目間安排換位橋段，透過體驗不同的觀看視角，做為您日後蒞臨音樂廳欣賞演出的座位參考。\r\n\r\n每月一小時，相約「探索管風琴音樂」，揭開管風琴的神祕面紗，拉近管風琴與我們的距離！\r\n\r\n\r\n4/23(三)14:30\r\n\r\n【管風琴的夢幻音樂之旅】\r\n\r\n※管風琴家：劉信宏、徐佳郁\r\n\r\n立即購票\r\n\r\n\r\n\r\n屬於兒童的歡樂4月，來與衛武營管風琴一起歡度佳節吧！不論是柴可夫斯基《睡美人》與《胡桃鉗》選粹、巴哈清唱劇或漢恩《致克洛麗絲》等古典樂經典，或是管風琴名家維耶爾恩、魏多或依尼斯的精彩編創，或是爵士鋼琴家烏特巴克及電影配樂大師莫利柯奈的當代經典，全部都是能展現管風琴音響難得一見的溫柔面貌的曲子，特別適合親子同賞，暢遊夢幻音樂之旅。\r\n\r\n \r\n\r\n維耶爾恩：第一號管風琴交響曲，作品14，終曲\r\n\r\n顏尼歐：《電影天堂》\r\n\r\n柴可夫斯基：〈全景〉選自《睡美人》芭蕾舞曲組曲\r\n\r\n柴可夫斯基：《胡桃鉗》組曲選粹\r\n\r\n魏多：〈幽默曲〉選自《六首鋼琴與風琴二重奏》，作品3-1\r\n\r\n烏特巴克：《這盞小光》\r\n\r\n巴赫： 〈詠敘調〉選自第156號清唱劇\r\n\r\n約翰 ‧ 伊尼斯改編：《祢的信實是何等偉大》\r\n\r\n漢恩：《致克洛麗絲》\r\n', '國家表演藝術中心衛武營國家藝術文化中心', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-04-23 00:00:00', '2025-04-23 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+300', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025【探索管風琴音樂】《管風琴的夢幻音樂之旅》', `description`='走進衛武營音樂廳，除了驚嘆葡萄園式觀眾席與極佳音響效果外，位於最頂層的管風琴，也是眾人矚目的焦點。\r\n\r\n若是您曾經好奇，這台亞洲最大的音樂廳管風琴，究竟能展現什麼樣的百變樣貌，「探索管風琴音樂」系列活動，將是得到解答的大好機會！\r\n\r\n衛武營特別邀請臺灣專業管風琴家們設計獨家節目，搭配其他樂器以及加入燈光效果等特殊聆賞規劃，加上平易近人的專業解說，展現管風琴的萬千變換與可親可愛。\r\n\r\n活動特別安排「舞台零距離體驗場」將舞台區轉變為觀眾席區，讓您近距離一睹管風琴風采；「自由移動體驗場」在曲目間安排換位橋段，透過體驗不同的觀看視角，做為您日後蒞臨音樂廳欣賞演出的座位參考。\r\n\r\n每月一小時，相約「探索管風琴音樂」，揭開管風琴的神祕面紗，拉近管風琴與我們的距離！\r\n\r\n\r\n4/23(三)14:30\r\n\r\n【管風琴的夢幻音樂之旅】\r\n\r\n※管風琴家：劉信宏、徐佳郁\r\n\r\n立即購票\r\n\r\n\r\n\r\n屬於兒童的歡樂4月，來與衛武營管風琴一起歡度佳節吧！不論是柴可夫斯基《睡美人》與《胡桃鉗》選粹、巴哈清唱劇或漢恩《致克洛麗絲》等古典樂經典，或是管風琴名家維耶爾恩、魏多或依尼斯的精彩編創，或是爵士鋼琴家烏特巴克及電影配樂大師莫利柯奈的當代經典，全部都是能展現管風琴音響難得一見的溫柔面貌的曲子，特別適合親子同賞，暢遊夢幻音樂之旅。\r\n\r\n \r\n\r\n維耶爾恩：第一號管風琴交響曲，作品14，終曲\r\n\r\n顏尼歐：《電影天堂》\r\n\r\n柴可夫斯基：〈全景〉選自《睡美人》芭蕾舞曲組曲\r\n\r\n柴可夫斯基：《胡桃鉗》組曲選粹\r\n\r\n魏多：〈幽默曲〉選自《六首鋼琴與風琴二重奏》，作品3-1\r\n\r\n烏特巴克：《這盞小光》\r\n\r\n巴赫： 〈詠敘調〉選自第156號清唱劇\r\n\r\n約翰 ‧ 伊尼斯改編：《祢的信實是何等偉大》\r\n\r\n漢恩：《致克洛麗絲》\r\n', `organizer`='國家表演藝術中心衛武營國家藝術文化中心', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-04-23 00:00:00', `end_date`='2025-04-23 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+300', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d226b3242b74a3b0b3', '【衛武營小時光】天狼星口琴樂團《天狼星的口琴律動之聲》', '【衛武營小時光】天狼星口琴樂團《天狼星的口琴律動之聲》\r\n\r\n \r\n\r\n口琴是極具特色的樂器，小巧卻蘊含無限的可能性，一向被譽為大眾樂器之王。不僅能夠演繹古典音樂，亦可跨足流行音樂、爵士樂以及現代音樂等不同樂風。然而口琴在臺灣屬於小眾樂器，大多數人對於口琴往往停留在演奏老歌古調的刻板印象。\r\n\r\n天狼星口琴樂團為2017世界口琴大賽小合奏冠軍得主，當代國際口琴代表性樂團，一直以來致力於口琴音樂的革新與推廣，以重奏的編制詮釋不同風格的樂曲。在與來自不同國家的演奏家交流時，深深為各國不同的音樂風情所感動。尤其近期受邀於歐洲演出時，當地的民眾給予十分熱烈的掌聲與深刻的迴響，讓樂團驚訝於當地音樂教育的成功，也深感落實音樂在地化與生活化的必要性。從2012年開始，天狼星口琴樂團致力於臺灣各縣市的口琴推廣演出，獲得民眾許多熱情的鼓勵與支持，希望透過表演，讓各地喜歡藝文活動的朋友們，能夠更加認識臺灣優質的口琴重奏音樂，也期望能深耕臺灣的藝文活動，帶動藝文發展。\r\n\r\n此次【衛武營小時光】系列，透過口琴重奏的律動之聲重新演繹各種曲風，在一小時的節目中，將帶領大家快速領略流行、拉丁、爵士等不同的音樂元素，融合的曲風讓每一個音符都帶來無限驚喜！\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n給克勞德的探戈\r\n\r\n名偵探柯南主題曲\r\n\r\n好好愛我\r\n\r\n殘酷天使的行動綱領\r\n\r\n小島星空\r\n\r\nTruth\r\n\r\n她如此的可愛\r\n\r\n好想大聲說喜歡你\r\n\r\n我甜美的孩子\r\n\r\n一樣的月光\r\n\r\n \r\n\r\n  演後簽名會 \r\n\r\n2025/4/23(三)21:05 表演廳二樓大廳\r\n\r\n \r\n\r\n  演出者  \r\n\r\n和弦口琴｜陳彥銘\r\n\r\n半音階口琴｜張晁滕、蔡明憲、陳奕翔、王衍華\r\n\r\n倍低音口琴｜黃冠誌\r\n\r\n \r\n\r\n  團隊介紹  \r\n\r\n天狼星口琴樂團為2017年世界口琴節小合奏冠軍得主，亦曾於2013、2021年世界口琴節受邀擔任大賽評審/演出嘉賓/講座。在2022與2023年，天狼星口琴樂團曾連續獲選為財團法人國家文化藝術基金會「TAIWAN TOP演藝團隊」。\r\n\r\n近年來持續活躍於亞太口琴節、首爾國際口琴節、德國柏林FEN音樂節、全日本口琴連盟合宿研修会、檳城口琴音樂節等歐亞口琴音樂節與各國邀演中，為現今國際琴壇最具影響力的口琴團體之一。天狼星口琴樂團曲風多元，涵蓋拉丁、探戈、爵士與流行樂等。在專業藝文演出之外，天狼星口琴樂團也致力於口琴音樂的教育與推廣。除了年度的公演與臺灣各地的巡迴演出之外，樂團定期舉辦「臺灣口琴音樂節」，此活動目前已成為臺灣規模最大的口琴年度盛會以及東亞重要的口琴音樂節之一。樂團近年更跨足口琴硬體開發，並由團員蔡明憲與張晁滕兩位老師成立手工琴品牌「Laelaps」。樂團希望能為口琴音樂創造一個更好的環境，在專業藝文、教育推廣與硬體推廣等不同面向上都能盡一份心力。', '國家表演藝術中心衛武營國家藝術文化中心', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-04-23 00:00:00', '2025-04-23 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+300;--+600', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【衛武營小時光】天狼星口琴樂團《天狼星的口琴律動之聲》', `description`='【衛武營小時光】天狼星口琴樂團《天狼星的口琴律動之聲》\r\n\r\n \r\n\r\n口琴是極具特色的樂器，小巧卻蘊含無限的可能性，一向被譽為大眾樂器之王。不僅能夠演繹古典音樂，亦可跨足流行音樂、爵士樂以及現代音樂等不同樂風。然而口琴在臺灣屬於小眾樂器，大多數人對於口琴往往停留在演奏老歌古調的刻板印象。\r\n\r\n天狼星口琴樂團為2017世界口琴大賽小合奏冠軍得主，當代國際口琴代表性樂團，一直以來致力於口琴音樂的革新與推廣，以重奏的編制詮釋不同風格的樂曲。在與來自不同國家的演奏家交流時，深深為各國不同的音樂風情所感動。尤其近期受邀於歐洲演出時，當地的民眾給予十分熱烈的掌聲與深刻的迴響，讓樂團驚訝於當地音樂教育的成功，也深感落實音樂在地化與生活化的必要性。從2012年開始，天狼星口琴樂團致力於臺灣各縣市的口琴推廣演出，獲得民眾許多熱情的鼓勵與支持，希望透過表演，讓各地喜歡藝文活動的朋友們，能夠更加認識臺灣優質的口琴重奏音樂，也期望能深耕臺灣的藝文活動，帶動藝文發展。\r\n\r\n此次【衛武營小時光】系列，透過口琴重奏的律動之聲重新演繹各種曲風，在一小時的節目中，將帶領大家快速領略流行、拉丁、爵士等不同的音樂元素，融合的曲風讓每一個音符都帶來無限驚喜！\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n給克勞德的探戈\r\n\r\n名偵探柯南主題曲\r\n\r\n好好愛我\r\n\r\n殘酷天使的行動綱領\r\n\r\n小島星空\r\n\r\nTruth\r\n\r\n她如此的可愛\r\n\r\n好想大聲說喜歡你\r\n\r\n我甜美的孩子\r\n\r\n一樣的月光\r\n\r\n \r\n\r\n  演後簽名會 \r\n\r\n2025/4/23(三)21:05 表演廳二樓大廳\r\n\r\n \r\n\r\n  演出者  \r\n\r\n和弦口琴｜陳彥銘\r\n\r\n半音階口琴｜張晁滕、蔡明憲、陳奕翔、王衍華\r\n\r\n倍低音口琴｜黃冠誌\r\n\r\n \r\n\r\n  團隊介紹  \r\n\r\n天狼星口琴樂團為2017年世界口琴節小合奏冠軍得主，亦曾於2013、2021年世界口琴節受邀擔任大賽評審/演出嘉賓/講座。在2022與2023年，天狼星口琴樂團曾連續獲選為財團法人國家文化藝術基金會「TAIWAN TOP演藝團隊」。\r\n\r\n近年來持續活躍於亞太口琴節、首爾國際口琴節、德國柏林FEN音樂節、全日本口琴連盟合宿研修会、檳城口琴音樂節等歐亞口琴音樂節與各國邀演中，為現今國際琴壇最具影響力的口琴團體之一。天狼星口琴樂團曲風多元，涵蓋拉丁、探戈、爵士與流行樂等。在專業藝文演出之外，天狼星口琴樂團也致力於口琴音樂的教育與推廣。除了年度的公演與臺灣各地的巡迴演出之外，樂團定期舉辦「臺灣口琴音樂節」，此活動目前已成為臺灣規模最大的口琴年度盛會以及東亞重要的口琴音樂節之一。樂團近年更跨足口琴硬體開發，並由團員蔡明憲與張晁滕兩位老師成立手工琴品牌「Laelaps」。樂團希望能為口琴音樂創造一個更好的環境，在專業藝文、教育推廣與硬體推廣等不同面向上都能盡一份心力。', `organizer`='國家表演藝術中心衛武營國家藝術文化中心', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-04-23 00:00:00', `end_date`='2025-04-23 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+300;--+600', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d226b3242b74a3b0b4', '《王致仁2025鋼琴獨奏會》', '《王致仁2025鋼琴獨奏會》\r\n王致仁在香港開始音樂教育，12歲移居英國，跟隨諾瑪．費希爾學習，隨後在倫敦皇家音樂學院跟隨克里斯多夫．埃爾頓學習。王致仁對作曲也深感興趣，並為此在普魯士科夫國際音樂家研討會上向阿德斯學習，也曾在巴黎成為納吉．哈基姆的私人學生學習對位法。這些接觸在王致仁的音樂歷程中留下了深刻印記。在利希慎基金會的支持下，王致仁於倫敦皇家音樂學院獲得博士學位，其研究對象是布梭尼。王致仁曾經在薩爾茲堡的莫札特夏季國際學院中獲獎，並在倫敦魏格摩爾音樂廳登台演出。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n李斯特：帕格尼尼大練習曲，S. 141\r\n\r\n王致仁：《動．靜》（小奏鳴曲描摹）\r\n\r\n巴赫／布梭尼：夏康舞曲，選自d小調第二號無伴奏小提琴組曲，BWV 1004\r\n\r\n巴赫／布梭尼：郭德堡變奏曲（王致仁校訂）\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n鋼琴｜王致仁', '鵬博藝術股份有限公司Blooming Arts', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-04-24 00:00:00', '2025-04-24 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+500;--+800;--+1200;--+1800;--+2400', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《王致仁2025鋼琴獨奏會》', `description`='《王致仁2025鋼琴獨奏會》\r\n王致仁在香港開始音樂教育，12歲移居英國，跟隨諾瑪．費希爾學習，隨後在倫敦皇家音樂學院跟隨克里斯多夫．埃爾頓學習。王致仁對作曲也深感興趣，並為此在普魯士科夫國際音樂家研討會上向阿德斯學習，也曾在巴黎成為納吉．哈基姆的私人學生學習對位法。這些接觸在王致仁的音樂歷程中留下了深刻印記。在利希慎基金會的支持下，王致仁於倫敦皇家音樂學院獲得博士學位，其研究對象是布梭尼。王致仁曾經在薩爾茲堡的莫札特夏季國際學院中獲獎，並在倫敦魏格摩爾音樂廳登台演出。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n李斯特：帕格尼尼大練習曲，S. 141\r\n\r\n王致仁：《動．靜》（小奏鳴曲描摹）\r\n\r\n巴赫／布梭尼：夏康舞曲，選自d小調第二號無伴奏小提琴組曲，BWV 1004\r\n\r\n巴赫／布梭尼：郭德堡變奏曲（王致仁校訂）\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n鋼琴｜王致仁', `organizer`='鵬博藝術股份有限公司Blooming Arts', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-04-24 00:00:00', `end_date`='2025-04-24 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+500;--+800;--+1200;--+1800;--+2400', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d326b3242b74a3b0b5', '《福爾摩沙合唱團2025藝文推廣系列音樂會之一》', '【節目異動】《福爾摩沙合唱團2025藝文推廣系列音樂會之一》\r\n※2025年4月25日（五）19:30於衛武營音樂廳演出之《福爾摩沙合唱團2025藝文推廣系列音樂會之一》，因故異動演出內容，造成不便，敬請見諒。\r\n\r\n※於異動公告發佈前之購票觀眾，如因本異動欲退票，自公告日起至2025年4月25日前（未使用之票券），可辦理全額退票。退票詳情及辦法請至售票網站查詢。\r\n\r\n \r\n\r\n福爾摩沙合唱團三十年來致力提升音樂會的精緻與深度，積極參與國際性質的音樂活動與世界音樂脈動接軌，對於保存、創作並發揚台灣音樂文化也不遺餘力。隨著合唱團腳步不斷向外擴展延伸的同時，我們看到了國內音樂教育紮根的必要性。這場音樂會將由藝術總監蘇慶俊與福爾摩沙合唱團，透過豐富且多元的樂曲面貌，期許能夠帶給觀眾充滿感動與共鳴的心靈享宴。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n西面頌｜保羅・史密斯\r\n\r\n被捕獲的獨角獸｜奧拉・葛葉洛\r\n\r\n晴空萬里｜孝恩·基希納 編曲\r\n\r\n以及多首經典臺灣歌謠曲目\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n藝術總監暨指揮｜蘇慶俊\r\n\r\n鋼琴｜蔡昱姍\r\n\r\n演出｜福爾摩沙合唱團\r\n\r\n聯演團隊｜天生歌手合唱團\r\n\r\n指揮｜陳安瑜\r\n\r\n鋼琴｜許溎芳', '福爾摩沙合唱團', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-04-25 00:00:00', '2025-04-25 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+300;--+500;--+800;--+1000', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《福爾摩沙合唱團2025藝文推廣系列音樂會之一》', `description`='【節目異動】《福爾摩沙合唱團2025藝文推廣系列音樂會之一》\r\n※2025年4月25日（五）19:30於衛武營音樂廳演出之《福爾摩沙合唱團2025藝文推廣系列音樂會之一》，因故異動演出內容，造成不便，敬請見諒。\r\n\r\n※於異動公告發佈前之購票觀眾，如因本異動欲退票，自公告日起至2025年4月25日前（未使用之票券），可辦理全額退票。退票詳情及辦法請至售票網站查詢。\r\n\r\n \r\n\r\n福爾摩沙合唱團三十年來致力提升音樂會的精緻與深度，積極參與國際性質的音樂活動與世界音樂脈動接軌，對於保存、創作並發揚台灣音樂文化也不遺餘力。隨著合唱團腳步不斷向外擴展延伸的同時，我們看到了國內音樂教育紮根的必要性。這場音樂會將由藝術總監蘇慶俊與福爾摩沙合唱團，透過豐富且多元的樂曲面貌，期許能夠帶給觀眾充滿感動與共鳴的心靈享宴。\r\n\r\n \r\n\r\n  演出曲目  \r\n\r\n西面頌｜保羅・史密斯\r\n\r\n被捕獲的獨角獸｜奧拉・葛葉洛\r\n\r\n晴空萬里｜孝恩·基希納 編曲\r\n\r\n以及多首經典臺灣歌謠曲目\r\n\r\n \r\n\r\n  演出暨製作團隊  \r\n\r\n藝術總監暨指揮｜蘇慶俊\r\n\r\n鋼琴｜蔡昱姍\r\n\r\n演出｜福爾摩沙合唱團\r\n\r\n聯演團隊｜天生歌手合唱團\r\n\r\n指揮｜陳安瑜\r\n\r\n鋼琴｜許溎芳', `organizer`='福爾摩沙合唱團', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-04-25 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+300;--+500;--+800;--+1000', `so