INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d426b3242b74a3b0c1', '性別平等-電影導讀', '利用館藏書籍和視聽資料透過導讀得方式，培養兩性平等的觀念並消除對婦女之歧視，確保男女在教育、就業、保健、家庭、法律、經濟等各方面享有平等權利。\r\n電影導讀:4/27姊妹、5/4勇敢傳說', '高雄市立圖書館總館', '高雄市茄萣區24鄰濱海路四段31巷1號', '2025-04-27 00:00:00', '2025-05-04 00:00:00', '高雄市立圖書館茄萣分館', 22.9068919, 120.1824779, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='性別平等-電影導讀', `description`='利用館藏書籍和視聽資料透過導讀得方式，培養兩性平等的觀念並消除對婦女之歧視，確保男女在教育、就業、保健、家庭、法律、經濟等各方面享有平等權利。\r\n電影導讀:4/27姊妹、5/4勇敢傳說', `organizer`='高雄市立圖書館總館', `address`='高雄市茄萣區24鄰濱海路四段31巷1號', `start_date`='2025-04-27 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='高雄市立圖書館茄萣分館', `latitude`=22.9068919, `longitude`=120.1824779, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d426b3242b74a3b0c2', '「好玩趣味ē台語冊」-主題書展', '因應國發會114年雙語合作案「2025世界閱讀日【讀想生活．玩轉世界】」系列活動。本館希望藉由辦理之『主題書展』，積極帶動地方閱讀風氣，使到館民眾進一步認識館藏資源，讓更多人了解學習本土語言的重要性，將這優質的語言文化推廣並傳承下去。', '高雄市立圖書館總館', '高雄市茄萣區24鄰濱海路四段31巷1號', '2025-04-23 00:00:00', '2025-05-23 00:00:00', '高雄市立圖書館茄萣分館', 22.9068919, 120.1824779, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「好玩趣味ē台語冊」-主題書展', `description`='因應國發會114年雙語合作案「2025世界閱讀日【讀想生活．玩轉世界】」系列活動。本館希望藉由辦理之『主題書展』，積極帶動地方閱讀風氣，使到館民眾進一步認識館藏資源，讓更多人了解學習本土語言的重要性，將這優質的語言文化推廣並傳承下去。', `organizer`='高雄市立圖書館總館', `address`='高雄市茄萣區24鄰濱海路四段31巷1號', `start_date`='2025-04-23 00:00:00', `end_date`='2025-05-23 00:00:00', `location`='高雄市立圖書館茄萣分館', `latitude`=22.9068919, `longitude`=120.1824779, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d526b3242b74a3b0c3', '2025藝術拼布國際展', '「2025藝術拼布國際展」由林幸珍纖維藝術工作室主辦，6/27-7/8於高雄市文化中心至真堂一館舉行，特別邀請來自13個國家的藝術家展出51幅作品，以不同方式介紹大家所未曾見過的拼布創作風格，及作品所隱喻的纖維表現，以針線作為畫筆，將布片化成顏料，結合刺繡、印染、編織…等技術，拼接出多采多姿的創作。', '無資料', '高雄市苓雅區001鄰五福一路67號', '2025-06-27 00:00:00', '2025-07-08 00:00:00', '高雄市政府文化局﹝高雄市文化中心﹞', 22.6278944, 120.3155406, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025藝術拼布國際展', `description`='「2025藝術拼布國際展」由林幸珍纖維藝術工作室主辦，6/27-7/8於高雄市文化中心至真堂一館舉行，特別邀請來自13個國家的藝術家展出51幅作品，以不同方式介紹大家所未曾見過的拼布創作風格，及作品所隱喻的纖維表現，以針線作為畫筆，將布片化成顏料，結合刺繡、印染、編織…等技術，拼接出多采多姿的創作。', `organizer`='無資料', `address`='高雄市苓雅區001鄰五福一路67號', `start_date`='2025-06-27 00:00:00', `end_date`='2025-07-08 00:00:00', `location`='高雄市政府文化局﹝高雄市文化中心﹞', `latitude`=22.6278944, `longitude`=120.3155406, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
