INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d826b3242b74a3b0c5', '向海致敬 -戀戀牛角，拾貝心語', '為響應行政院「向海致敬」政策，推廣海洋保育與永續發展，本次活動選在海漂垃圾嚴重的牛角沙灘舉辦，結合趣味淨灘，吸引各族群參與，提升全民海洋意識，讓環保成為有趣且富有成就感的行動。\r\n\r\n透過「淨海」清理海岸垃圾，恢復自然景觀，落實責任旅遊；並以「近海」賦予海廢新生命，轉化為創作素材與展品。\r\n\r\n● 活動日期:114年04月26日(星期日) \r\n\r\n● 活動地點：牛角沙灘 、牛角五靈宮廟下方活動中心\r\n\r\n● 活動時間：10:00 - 16:00\r\n\r\n10:00 - 12:30｜淨灘尋寶 × 分類挑戰\r\n\r\n∙ 淨灘尋寶遊戲\r\n\r\n透過「海廢挑戰卡」，組隊進行限時撿拾任務，完成指定數量或重量的海廢回收目標。\r\n\r\n∙ 海廢分類挑戰\r\n\r\n依海洋垃圾種類進行分類，初步學習回收與海廢再利用的重要性。\r\n\r\n∙ 清洗貝類準備素材\r\n\r\n將撿拾到的貝殼等自然素材進行清洗，為下午的創作活動做準備。\r\n\r\n∙ 餐盒、宣導品發放\r\n\r\n13:00 - 16:00｜海廢再生 × 花圈創作(此活動需酌收材料費100元)\r\n\r\n∙  海廢花圈手作體驗(限50人參加)\r\n\r\n認識海廢藝術與花圈創作手法，運用上午收集到的海廢及素材，發揮創意製作個人花圈。\r\n\r\n∙ 作品故事分享會\r\n\r\n每位參與者分享創作理念與花圈背後的小故事。\r\n\r\n由「芳草文創工作室」紀錄並設計成小卡，將於南竿遊客中心展出，傳遞永續精神。', '交通部觀光署馬祖國家風景區管理處', '連江縣南竿鄉', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '南竿鄉（連江縣）=', 26.154321, 119.931128, '材料費+100', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='向海致敬 -戀戀牛角，拾貝心語', `description`='為響應行政院「向海致敬」政策，推廣海洋保育與永續發展，本次活動選在海漂垃圾嚴重的牛角沙灘舉辦，結合趣味淨灘，吸引各族群參與，提升全民海洋意識，讓環保成為有趣且富有成就感的行動。\r\n\r\n透過「淨海」清理海岸垃圾，恢復自然景觀，落實責任旅遊；並以「近海」賦予海廢新生命，轉化為創作素材與展品。\r\n\r\n● 活動日期:114年04月26日(星期日) \r\n\r\n● 活動地點：牛角沙灘 、牛角五靈宮廟下方活動中心\r\n\r\n● 活動時間：10:00 - 16:00\r\n\r\n10:00 - 12:30｜淨灘尋寶 × 分類挑戰\r\n\r\n∙ 淨灘尋寶遊戲\r\n\r\n透過「海廢挑戰卡」，組隊進行限時撿拾任務，完成指定數量或重量的海廢回收目標。\r\n\r\n∙ 海廢分類挑戰\r\n\r\n依海洋垃圾種類進行分類，初步學習回收與海廢再利用的重要性。\r\n\r\n∙ 清洗貝類準備素材\r\n\r\n將撿拾到的貝殼等自然素材進行清洗，為下午的創作活動做準備。\r\n\r\n∙ 餐盒、宣導品發放\r\n\r\n13:00 - 16:00｜海廢再生 × 花圈創作(此活動需酌收材料費100元)\r\n\r\n∙  海廢花圈手作體驗(限50人參加)\r\n\r\n認識海廢藝術與花圈創作手法，運用上午收集到的海廢及素材，發揮創意製作個人花圈。\r\n\r\n∙ 作品故事分享會\r\n\r\n每位參與者分享創作理念與花圈背後的小故事。\r\n\r\n由「芳草文創工作室」紀錄並設計成小卡，將於南竿遊客中心展出，傳遞永續精神。', `organizer`='交通部觀光署馬祖國家風景區管理處', `address`='連江縣南竿鄉', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='南竿鄉（連江縣）=', `latitude`=26.154321, `longitude`=119.931128, `ticket_price`='材料費+100', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d826b3242b74a3b0c6', '「超島湖（Hyperlake）」國立臺灣藝術大學美術系學生聯展', '「超島湖」的靈感源於網絡廣為流傳的《鮫島事件》。該事件缺乏具體事實基礎，其起源、發展與結果皆透過網友的口耳相傳塑造而成。本質上，它是一則「僅有其名的謠言」，沒有固定內容或版本，成為研究謠言現象的理想案例，展現群體如何在缺乏實證的情況下，透過傳播放大其影響力。\r\n本次展覽試圖探討《鮫島事件》所折射的社會焦慮與文化現象，並分析當代網絡文化如何影響群體認知與信息傳播。同時，展覽透過展示社會面對未知或模糊信息的集體反應，幫助觀眾理解網絡文化的獨特性。\r\n此外，另有邀請藝術家以多種視角詮釋此事件，呈現謠言的多重面向，進而引導觀眾反思：謠言如何形成、擴散，並深刻影響群體思維。', '新北市立淡水古蹟博物館', '新北市淡水區觀海路91號3樓、4樓', '2025-03-13 00:00:00', '2025-04-20 00:00:00', '淡水漁人碼頭觀光休閒暨藝文空間-滬水一方', 25.18907636, 121.463904, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「超島湖（Hyperlake）」國立臺灣藝術大學美術系學生聯展', `description`='「超島湖」的靈感源於網絡廣為流傳的《鮫島事件》。該事件缺乏具體事實基礎，其起源、發展與結果皆透過網友的口耳相傳塑造而成。本質上，它是一則「僅有其名的謠言」，沒有固定內容或版本，成為研究謠言現象的理想案例，展現群體如何在缺乏實證的情況下，透過傳播放大其影響力。\r\n本次展覽試圖探討《鮫島事件》所折射的社會焦慮與文化現象，並分析當代網絡文化如何影響群體認知與信息傳播。同時，展覽透過展示社會面對未知或模糊信息的集體反應，幫助觀眾理解網絡文化的獨特性。\r\n此外，另有邀請藝術家以多種視角詮釋此事件，呈現謠言的多重面向，進而引導觀眾反思：謠言如何形成、擴散，並深刻影響群體思維。', `organizer`='新北市立淡水古蹟博物館', `address`='新北市淡水區觀海路91號3樓、4樓', `start_date`='2025-03-13 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='淡水漁人碼頭觀光休閒暨藝文空間-滬水一方', `latitude`=25.18907636, `longitude`=121.463904, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d826b3242b74a3b0c7', '【新北市立圖書館板橋四維分館】114年4月彩虹故事屋', '館名：新北市立圖書館板橋四維分館\r\n地址：新北市板橋區陽明街168號\r\n電話：02-2252-1933#10\r\n活動內容：為讓閱讀向下札根，讓兒童培養閱讀的興趣與習慣，透過故事志工熱情互與表演，增進親子互動及了解零距離，共享歡樂時光。\r\n\r\n**閱讀飛行魔毯兒童多元文化推廣活動**\r\n說故事時間：下午14：30-15：30\r\n04/02(三) The Nighlingale\r\n04/09(三) 星光盒子\r\n04/16(三) 愛打岔的小雞、Again\r\n04/23(三) 超神奇糖果舖\r\n04/30(三) 神奇變身水、Not Norman: A Goldfish Story\r\n\r\n**彩虹故事屋**\r\n說故事時間：下午14：30-16：30\r\n04/12(六) 小偵探莉莉\r\n04/19(六) 妙探阿洛、The Bear Ate Your Sandwich\r\n04/26(六) 吃人妖、大野狼、小女孩和蛋糕/Apples for little Fox\r\n\r\n**主恩教會**\r\n04/05(六) 4月兒童繪本故事時間\r\n04/12(六) 4月兒童繪本故事時間\r\n04/19(六) 4月兒童繪本故事時間\r\n04/26(六) 4月兒童繪本故事時間\r\n\r\n**臺語故事活動**\r\n04/12(六) 「爺奶說故事 萬事保篇」台語說故事', '新北市立圖書館總館', '新北市板橋區陽明街168號', '2025-04-02 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館板橋四維分館', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館板橋四維分館】114年4月彩虹故事屋', `description`='館名：新北市立圖書館板橋四維分館\r\n地址：新北市板橋區陽明街168號\r\n電話：02-2252-1933#10\r\n活動內容：為讓閱讀向下札根，讓兒童培養閱讀的興趣與習慣，透過故事志工熱情互與表演，增進親子互動及了解零距離，共享歡樂時光。\r\n\r\n**閱讀飛行魔毯兒童多元文化推廣活動**\r\n說故事時間：下午14：30-15：30\r\n04/02(三) The Nighlingale\r\n04/09(三) 星光盒子\r\n04/16(三) 愛打岔的小雞、Again\r\n04/23(三) 超神奇糖果舖\r\n04/30(三) 神奇變身水、Not Norman: A Goldfish Story\r\n\r\n**彩虹故事屋**\r\n說故事時間：下午14：30-16：30\r\n04/12(六) 小偵探莉莉\r\n04/19(六) 妙探阿洛、The Bear Ate Your Sandwich\r\n04/26(六) 吃人妖、大野狼、小女孩和蛋糕/Apples for little Fox\r\n\r\n**主恩教會**\r\n04/05(六) 4月兒童繪本故事時間\r\n04/12(六) 4月兒童繪本故事時間\r\n04/19(六) 4月兒童繪本故事時間\r\n04/26(六) 4月兒童繪本故事時間\r\n\r\n**臺語故事活動**\r\n04/12(六) 「爺奶說故事 萬事保篇」台語說故事', `organizer`='新北市立圖書館總館', `address`='新北市板橋區陽明街168號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館板橋四維分館', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
