INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d926b3242b74a3b0cb', '【新北市立圖書館板橋國光圖書閱覽室】114年4月《閱讀書籤》飛禽走獸', '館名：新北市立圖書館板橋國光閱覽室\r\n地址：新北市板橋區中正路375巷48號3樓\r\n電話：02-8965-4829\r\n時間：週二～週六 08:30-21:00；週日～週一 08:30-17:00；每月最後一週週四及國定假日休館\r\n\r\n書展主題：本次書展帶你走進動物的奇妙世界。從天空飛翔的鳥類到陸地奔馳的野獸，透過精彩書籍認識自然生態，感受生命的多樣與美麗，喚起對動物與環境的關懷。', '新北市立圖書館總館', '新北市板橋區中正路375巷48號3樓', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '新北市立圖書館板橋國光圖書閱覽室', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館板橋國光圖書閱覽室】114年4月《閱讀書籤》飛禽走獸', `description`='館名：新北市立圖書館板橋國光閱覽室\r\n地址：新北市板橋區中正路375巷48號3樓\r\n電話：02-8965-4829\r\n時間：週二～週六 08:30-21:00；週日～週一 08:30-17:00；每月最後一週週四及國定假日休館\r\n\r\n書展主題：本次書展帶你走進動物的奇妙世界。從天空飛翔的鳥類到陸地奔馳的野獸，透過精彩書籍認識自然生態，感受生命的多樣與美麗，喚起對動物與環境的關懷。', `organizer`='新北市立圖書館總館', `address`='新北市板橋區中正路375巷48號3樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='新北市立圖書館板橋國光圖書閱覽室', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d926b3242b74a3b0cc', '澎湖尚「水」-澎湖縣攝影學會聯展', '本次展覽主題「澎湖尚『水』」，除了水是澎湖得天獨厚的海洋環境，亦是臺語中的「美」，然而用「美」不足以形容，但用臺語「水啦」，更能夠貼切去反應攝影作品蘊含的豐富內容。', '國立澎湖科技大學', '澎湖縣馬公市六合路300號', '2025-03-26 00:00:00', '2025-04-20 00:00:00', '國立澎湖科技大學', 23.55534, 119.59234, '無資料', 'http://www.hs885.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='澎湖尚「水」-澎湖縣攝影學會聯展', `description`='本次展覽主題「澎湖尚『水』」，除了水是澎湖得天獨厚的海洋環境，亦是臺語中的「美」，然而用「美」不足以形容，但用臺語「水啦」，更能夠貼切去反應攝影作品蘊含的豐富內容。', `organizer`='國立澎湖科技大學', `address`='澎湖縣馬公市六合路300號', `start_date`='2025-03-26 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='國立澎湖科技大學', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.hs885.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d926b3242b74a3b0cd', '張正傑親子音樂會《大提琴找新娘》', '這場音樂界喜事，源自大提琴家張正傑的大提琴「盧傑利」突然有了結婚的念頭，誰將成為它的最佳新娘？張正傑絞盡腦汁特別邀請重金聘請親子天王知名主持人趙自強，擔任這場「相親大會」的金牌媒婆，為盧傑利推薦來自東西方音樂世界的「新娘候選人」。同時邀請知名音樂家包括六根棒子女王台北藝術大學教授、朱宗慶打擊樂團的吳珮菁；揚名國際、電視節目的大環藝術家楊世豪；文化大學教授、台北愛樂管弦樂團指揮、小提琴家林天吉；澎湖最棒的音樂家一起參與演出，包括鋼琴家張曼君及女高音高紹恩，一同聯手來演繹這場充滿幽默與粉紅泡泡的音樂故事，將帶來曲目巴赫：前奏曲，取自《第一號G大調無伴奏大提琴組曲》、聖桑：天鵝，取自《動物狂歡節》、韓德爾/哈沃森：《帕薩加里亞舞曲》、電影《女人香》配樂、台灣民謠：《白鷺鷥》等經典曲目。究竟誰能贏得盧傑利的芳心，成為它的「新娘」？\r\n', '澎湖縣政府文化局', '澎湖縣馬公市中華路230號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '澎湖縣政府文化局', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='張正傑親子音樂會《大提琴找新娘》', `description`='這場音樂界喜事，源自大提琴家張正傑的大提琴「盧傑利」突然有了結婚的念頭，誰將成為它的最佳新娘？張正傑絞盡腦汁特別邀請重金聘請親子天王知名主持人趙自強，擔任這場「相親大會」的金牌媒婆，為盧傑利推薦來自東西方音樂世界的「新娘候選人」。同時邀請知名音樂家包括六根棒子女王台北藝術大學教授、朱宗慶打擊樂團的吳珮菁；揚名國際、電視節目的大環藝術家楊世豪；文化大學教授、台北愛樂管弦樂團指揮、小提琴家林天吉；澎湖最棒的音樂家一起參與演出，包括鋼琴家張曼君及女高音高紹恩，一同聯手來演繹這場充滿幽默與粉紅泡泡的音樂故事，將帶來曲目巴赫：前奏曲，取自《第一號G大調無伴奏大提琴組曲》、聖桑：天鵝，取自《動物狂歡節》、韓德爾/哈沃森：《帕薩加里亞舞曲》、電影《女人香》配樂、台灣民謠：《白鷺鷥》等經典曲目。究竟誰能贏得盧傑利的芳心，成為它的「新娘」？\r\n', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路230號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='澎湖縣政府文化局', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fd78d926b3242b74a3b0ce', '2025春唱-阿卡貝拉瘋台灣巡迴音樂會', '「Zenith」意指「人聲是最好的樂器」，Zenith團隊成立於2008年，是韓國當今現代阿卡貝拉頂尖團隊，2015年奧地利格拉茨「vokal.total國際阿卡貝拉大賽」及2014年TCMC台灣國際重唱藝術節「世界盃現代阿卡貝拉大賽」榮獲大獎，為國際大賽中首支獲獎的韓國隊伍。熱情歡唱《Circle of Life》、《Beauty And The Beast》、《月亮代表我的心》、《APT》、《明天會更好》等曲目，採自由入場方式，歡迎鄉親屆時蒞臨聆賞！\r\n    \r\n    \r\n', '澎湖縣政府文化局', '澎湖縣馬公市中華路230號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '澎湖縣政府文化局', 23.55534, 119.59234, '無資料', 'http://www.phhcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025春唱-阿卡貝拉瘋台灣巡迴音樂會', `description`='「Zenith」意指「人聲是最好的樂器」，Zenith團隊成立於2008年，是韓國當今現代阿卡貝拉頂尖團隊，2015年奧地利格拉茨「vokal.total國際阿卡貝拉大賽」及2014年TCMC台灣國際重唱藝術節「世界盃現代阿卡貝拉大賽」榮獲大獎，為國際大賽中首支獲獎的韓國隊伍。熱情歡唱《Circle of Life》、《Beauty And The Beast》、《月亮代表我的心》、《APT》、《明天會更好》等曲目，採自由入場方式，歡迎鄉親屆時蒞臨聆賞！\r\n    \r\n    \r\n', `organizer`='澎湖縣政府文化局', `address`='澎湖縣馬公市中華路230號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='澎湖縣政府文化局', `latitude`=23.55534, `longitude`=119.59234, `ticket_price`='無資料', `source_url`='http://www.phhcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fe183e07f3c8b8c6b19b75', '臺灣風情畫', '擊颺民族室內樂樂團,為擊颺藝術文化工作內旗下之樂團,秉持「傳播中華民族室音樂為己任」之精神,以「傳」承‧散「播」為核心宗旨成立。本團集結眾多國樂專業演奏家,參與各式展演活動,致力推廣傳統音樂,冀望使這豐厚的文化底蘊,散播至巷弄中,於大眾體悟傳統音樂之美,深植人心,體現於自身涵養與生活。\r\n\r\n時間：2025/6/29\r\n\r\n地點：雅卓藝術中心 - 台北市中正區羅斯福路三段302號8樓\r\n\r\n演出者：擊颺民族室內樂樂團\r\n\r\n演出曲目：\r\n\r\n01. 《鳳陽新春》\r\n02. 《農村酒歌》\r\n03. 《鵝鑾鼻之春》\r\n04. 《月亮代表我的心》\r\n05. 《草螟弄雞公》\r\n06. 《客家本色》\r\n07. 《油紙傘下的回憶》\r\n08. 《滿山春色》\r\n09. 《海峽音詩》\r\n10. 《望春風》\r\n11. 《彝族舞曲》\r\n12. 《明天會更好》', '雅卓藝術', '臺北市中正區羅斯福路三段302號8樓', '2025-06-29 00:00:00', '2025-06-29 00:00:00', '雅卓藝術中心', 25.03240487, 121.5198839, '全票：380元', 'https://www.accupass.com/event/2502170646503874448120', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺灣風情畫', `description`='擊颺民族室內樂樂團,為擊颺藝術文化工作內旗下之樂團,秉持「傳播中華民族室音樂為己任」之精神,以「傳」承‧散「播」為核心宗旨成立。本團集結眾多國樂專業演奏家,參與各式展演活動,致力推廣傳統音樂,冀望使這豐厚的文化底蘊,散播至巷弄中,於大眾體悟傳統音樂之美,深植人心,體現於自身涵養與生活。\r\n\r\n時間：2025/6/29\r\n\r\n地點：雅卓藝術中心 - 台北市中正區羅斯福路三段302號8樓\r\n\r\n演出者：擊颺民族室內樂樂團\r\n\r\n演出曲目：\r\n\r\n01. 《鳳陽新春》\r\n02. 《農村酒歌》\r\n03. 《鵝鑾鼻之春》\r\n04. 《月亮代表我的心》\r\n05. 《草螟弄雞公》\r\n06. 《客家本色》\r\n07. 《油紙傘下的回憶》\r\n08. 《滿山春色》\r\n09. 《海峽音詩》\r\n10. 《望春風》\r\n11. 《彝族舞曲》\r\n12. 《明天會更好》', `organizer`='雅卓藝術', `address`='臺北市中正區羅斯福路三段302號8樓', `start_date`='2025-06-29 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='雅卓藝術中心', `latitude`=25.03240487, `longitude`=121.5198839, `ticket_price`='全票：380元', `source_url`='https://www.accupass.com/event/2502170646503874448120', `image_url`='[]';
