INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fead6326b3242b74a3b0dc', '三峽農會松年大學粉彩畫銀髮樂畫師生聯展', '陳炳南老師，現任臺灣粉彩畫協會理事，作品曾於國父紀念館展出，帶領三峽農會松年大學學員們，以粉彩畫展現自由奔放且多元的畫風，傳遞滿滿活力及學無止境的精神，期盼將這份積極分享給每個人，鼓勵大家一同活出精彩人生。', '新北市三峽戶政事務所', '新北市三峽區', '2025-01-01 00:00:00', '2025-12-31 00:00:00', '三峽區（新北市）=', 24.88209766, 121.4163094, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='三峽農會松年大學粉彩畫銀髮樂畫師生聯展', `description`='陳炳南老師，現任臺灣粉彩畫協會理事，作品曾於國父紀念館展出，帶領三峽農會松年大學學員們，以粉彩畫展現自由奔放且多元的畫風，傳遞滿滿活力及學無止境的精神，期盼將這份積極分享給每個人，鼓勵大家一同活出精彩人生。', `organizer`='新北市三峽戶政事務所', `address`='新北市三峽區', `start_date`='2025-01-01 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='三峽區（新北市）=', `latitude`=24.88209766, `longitude`=121.4163094, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fead8526b3242b74a3b0dd', '臺東縣政府交觀處｜2025繁星光影', '2025繁星光影以國際地標的圓形建築為中心，透過上萬顆點光源進行光源設置，用光代表能量，光點代表星空，呈現如同水晶球般星光點點的【繁星之境】，左右兩側廊道以色彩鮮豔的織帶打造與眾不同的【光織廊道】，讓遊客彷彿置身於奇幻走廊，白天與夜晚都能拍出不同效果，成為新拍照打卡點。\r\n\r\n每天19:00-22:00進行光彩炫麗演出，在每30分鐘圓形建築以點光源結合動畫效果進行動態展演，透過點光源跑動效果搭配聲光動畫的串聯，讓大家來海邊賞景的同時也能感受到國際地標新的樣貌，邀請大家沿著光廊步道漫步，仰望繁星之境，觀賞臺東海岸的浪漫夜景。\r\n\r\n國際地標𝟐/𝟐𝟖－𝟔/𝟏為期𝟗𝟒天🙌🏻\r\n亮燈｜𝟏𝟗:𝟎𝟎-𝟐𝟐:𝟎𝟎，每𝟑𝟎分鐘進行光影展演\r\n地點｜臺東國際地標（海濱公園）\r\n', '臺東縣政府', '臺東縣臺東市', '2025-02-28 00:00:00', '2025-06-01 00:00:00', '臺東市（臺東縣）=', 22.75165721, 121.1103647, '無資料', 'https://www.facebook.com/share/p/15knHgjpJ9/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺東縣政府交觀處｜2025繁星光影', `description`='2025繁星光影以國際地標的圓形建築為中心，透過上萬顆點光源進行光源設置，用光代表能量，光點代表星空，呈現如同水晶球般星光點點的【繁星之境】，左右兩側廊道以色彩鮮豔的織帶打造與眾不同的【光織廊道】，讓遊客彷彿置身於奇幻走廊，白天與夜晚都能拍出不同效果，成為新拍照打卡點。\r\n\r\n每天19:00-22:00進行光彩炫麗演出，在每30分鐘圓形建築以點光源結合動畫效果進行動態展演，透過點光源跑動效果搭配聲光動畫的串聯，讓大家來海邊賞景的同時也能感受到國際地標新的樣貌，邀請大家沿著光廊步道漫步，仰望繁星之境，觀賞臺東海岸的浪漫夜景。\r\n\r\n國際地標𝟐/𝟐𝟖－𝟔/𝟏為期𝟗𝟒天🙌🏻\r\n亮燈｜𝟏𝟗:𝟎𝟎-𝟐𝟐:𝟎𝟎，每𝟑𝟎分鐘進行光影展演\r\n地點｜臺東國際地標（海濱公園）\r\n', `organizer`='臺東縣政府', `address`='臺東縣臺東市', `start_date`='2025-02-28 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='臺東市（臺東縣）=', `latitude`=22.75165721, `longitude`=121.1103647, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/15knHgjpJ9/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67fead8a26b3242b74a3b0de', '傳承‧新意～游藝雅集聯展', '  游藝雅集畫係由華梵大學藝術設計壆院前院長故熊宜中教授創立。為宏揚並實踐親師「藝術即生活」、「生活即藝術」的理念並推廣之。本次展出作品種類：山水、書法、花鳥、人物、攝影、壓花、素描、油畫、水彩等，竭誠歡迎各界蒞臨指教，共同營造社會美術氛圍。', '新北市土城區公所', '新北市土城區金城路一段101號', '2025-03-28 00:00:00', '2025-04-23 00:00:00', '新北市土城區公所(行政大樓)', 24.96425102, 121.445737, '無資料', 'https://www.tucheng.ntpc.gov.tw/index.jsp', '[]') ON DUPLICATE KEY UPDATE `activity_name`='傳承‧新意～游藝雅集聯展', `description`='  游藝雅集畫係由華梵大學藝術設計壆院前院長故熊宜中教授創立。為宏揚並實踐親師「藝術即生活」、「生活即藝術」的理念並推廣之。本次展出作品種類：山水、書法、花鳥、人物、攝影、壓花、素描、油畫、水彩等，竭誠歡迎各界蒞臨指教，共同營造社會美術氛圍。', `organizer`='新北市土城區公所', `address`='新北市土城區金城路一段101號', `start_date`='2025-03-28 00:00:00', `end_date`='2025-04-23 00:00:00', `location`='新北市土城區公所(行政大樓)', `latitude`=24.96425102, `longitude`=121.445737, `ticket_price`='無資料', `source_url`='https://www.tucheng.ntpc.gov.tw/index.jsp', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feada026b3242b74a3b0df', '「遊畫」陳昱璇油畫創作個展', '新北市板橋地政事務所為美化洽公環境，提供一個讓民眾及同仁辦公時皆能感受人文氣息的藝文空間，自114年4月14日起至6月27日止，舉辦「遊畫」陳昱璇油畫創作個展，歡迎愛好藝文的人士共襄盛舉，一同享受藝術饗宴。', '新北市板橋地政事務所', '新北市板橋區', '2025-04-14 00:00:00', '2025-06-27 00:00:00', '板橋區（新北市）=', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「遊畫」陳昱璇油畫創作個展', `description`='新北市板橋地政事務所為美化洽公環境，提供一個讓民眾及同仁辦公時皆能感受人文氣息的藝文空間，自114年4月14日起至6月27日止，舉辦「遊畫」陳昱璇油畫創作個展，歡迎愛好藝文的人士共襄盛舉，一同享受藝術饗宴。', `organizer`='新北市板橋地政事務所', `address`='新北市板橋區', `start_date`='2025-04-14 00:00:00', `end_date`='2025-06-27 00:00:00', `location`='板橋區（新北市）=', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feada226b3242b74a3b0e0', '筆歌墨舞在水返腳–汐止社大心靈與書法班聯展', '為推廣藝文活動，新北市汐止地政事務所特邀請汐止社區大學曾麗滿與鄭德山書法老師，及其心靈與書法撰寫研究班學員聯合舉辦「筆歌墨舞在水返腳–汐止社大心靈與書法班聯展」，展出期間為114年4月7日至114年6月30日，開放展覽時間為週一至週五上午8點至下午5點，敬邀大家蒞臨參觀。', '新北市汐止地政事務所', '新北市汐止區', '2025-04-07 00:00:00', '2025-06-30 00:00:00', '汐止區（新北市）=', 25.07331322, 121.6546992, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='筆歌墨舞在水返腳–汐止社大心靈與書法班聯展', `description`='為推廣藝文活動，新北市汐止地政事務所特邀請汐止社區大學曾麗滿與鄭德山書法老師，及其心靈與書法撰寫研究班學員聯合舉辦「筆歌墨舞在水返腳–汐止社大心靈與書法班聯展」，展出期間為114年4月7日至114年6月30日，開放展覽時間為週一至週五上午8點至下午5點，敬邀大家蒞臨參觀。', `organizer`='新北市汐止地政事務所', `address`='新北市汐止區', `start_date`='2025-04-07 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='汐止區（新北市）=', `latitude`=25.07331322, `longitude`=121.6546992, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feada826b3242b74a3b0e1', '臺東縣政府文化處｜親子共度好時光-童言童語同在一起(4月)', '親子共度週末好時光-童言童語同在一起\r\n4/12 - Matt老師：Dora''s Picnic\r\n4/13 - 多多老師：彼得的椅子\r\n4/26 - 多多老師：好奇猴喬治\r\n4/27 - 多多老師：自己的顏色\r\n\r\n📢 說故事活動場地異動公告 📢\r\n親愛的大小朋友們，因應圖書館整修工程，4月份的說故事活動 將進行以下調整：\r\n📍 活動地點：藝文中心一樓大廳\r\n📆 活動日期：\r\n 4/12（六）、4/13（日）\r\n 4/26（六）、4/27（日）\r\n📆 活動時間：\r\n早上10:00-11:00\r\n✨ 雖然換了地點，但我們精彩有趣的故事依然不缺席！邀請大家帶著滿滿的好奇心，一起來藝文中心享受閱讀的樂趣吧！', '臺東縣政府', '臺東縣臺東市南京路25號', '2025-04-12 00:00:00', '2025-04-27 00:00:00', '臺東縣政府文化處', 22.75165721, 121.1103647, '無資料', 'https://www.facebook.com/profile.php?id=100064392051547', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺東縣政府文化處｜親子共度好時光-童言童語同在一起(4月)', `description`='親子共度週末好時光-童言童語同在一起\r\n4/12 - Matt老師：Dora''s Picnic\r\n4/13 - 多多老師：彼得的椅子\r\n4/26 - 多多老師：好奇猴喬治\r\n4/27 - 多多老師：自己的顏色\r\n\r\n📢 說故事活動場地異動公告 📢\r\n親愛的大小朋友們，因應圖書館整修工程，4月份的說故事活動 將進行以下調整：\r\n📍 活動地點：藝文中心一樓大廳\r\n📆 活動日期：\r\n 4/12（六）、4/13（日）\r\n 4/26（六）、4/27（日）\r\n📆 活動時間：\r\n早上10:00-11:00\r\n✨ 雖然換了地點，但我們精彩有趣的故事依然不缺席！邀請大家帶著滿滿的好奇心，一起來藝文中心享受閱讀的樂趣吧！', `organizer`='臺東縣政府', `address`='臺東縣臺東市南京路25號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺東縣政府文化處', `latitude`=22.75165721, `longitude`=121.1103647, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064392051547', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadab26b3242b74a3b0e2', '【林口區李科永紀念圖書館】114年4月英文故事列車', '英文故事志工以輕鬆活潑的讀書會方式引發孩童及家長們的興趣，讓父母可以訓練及示範，享受閱讀，孩子也可以透過閱讀探索的過程中，開啟未來的學習之旅。它的插圖和故事內容都是那麼棒，不僅可以幫助家長重溫小時候讀過的經典童話，也可以和孩子坐下來，一起分享閱讀、玩耍、陪伴帶來的美妙體驗，它能為孩子幼小的心靈，找到一個溫暖的地方。', '新北市立圖書館總館', '新北市林口區公園路192號', '2025-04-12 00:00:00', '2025-04-26 00:00:00', '林口區李科永紀念圖書館', 25.1000868, 121.3527235, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【林口區李科永紀念圖書館】114年4月英文故事列車', `description`='英文故事志工以輕鬆活潑的讀書會方式引發孩童及家長們的興趣，讓父母可以訓練及示範，享受閱讀，孩子也可以透過閱讀探索的過程中，開啟未來的學習之旅。它的插圖和故事內容都是那麼棒，不僅可以幫助家長重溫小時候讀過的經典童話，也可以和孩子坐下來，一起分享閱讀、玩耍、陪伴帶來的美妙體驗，它能為孩子幼小的心靈，找到一個溫暖的地方。', `organizer`='新北市立圖書館總館', `address`='新北市林口區公園路192號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='林口區李科永紀念圖書館', `latitude`=25.1000868, `longitude`=121.3527235, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
