INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadbd26b3242b74a3b0f6', '2025藝術行政與管理研討會「藝起走，更長‧遠」 專題演講與論文發表觀眾報名', '隨著全球化與科技加速發展，在探索社會文化認同、促進跨文化交流，以及反映時代脈動時，藝術皆展現其不可漠視的價值。\r\n　　2025研討會主題為「藝起走，更長·遠」，從永續視角出發，探討藝術在社會中的能量，關注其在社會發展的持續作用，更聚焦於藝術對社會的長遠價值與跨世代影響力。我們冀望能將藝術與社會發展緊密結合，並藉由持續地對話與思辨，一同建構多元文化共存的人文生態。\r\n　　本研討會將透過專題演講、論文發表等活動，邀請關心藝術行政與管理領域的研究者與實務工作者與會交流，分享學術研究與實務應用的成果與心得，一齊研討在面對全球環境變遷中，如何透過多元文化創新思維，回應時代趨勢、連結群體和展望未來，以持續探索藝術的永續創造力。', '國立臺北藝術大學藝術行政與管理研究所', '臺北市北投區學園路1號', '2025-05-09 00:00:00', '2025-05-09 00:00:00', '國立臺北藝術大學', 25.1480682, 121.5177992, '無資料', 'https://semmamtnua.weebly.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025藝術行政與管理研討會「藝起走，更長‧遠」 專題演講與論文發表觀眾報名', `description`='隨著全球化與科技加速發展，在探索社會文化認同、促進跨文化交流，以及反映時代脈動時，藝術皆展現其不可漠視的價值。\r\n　　2025研討會主題為「藝起走，更長·遠」，從永續視角出發，探討藝術在社會中的能量，關注其在社會發展的持續作用，更聚焦於藝術對社會的長遠價值與跨世代影響力。我們冀望能將藝術與社會發展緊密結合，並藉由持續地對話與思辨，一同建構多元文化共存的人文生態。\r\n　　本研討會將透過專題演講、論文發表等活動，邀請關心藝術行政與管理領域的研究者與實務工作者與會交流，分享學術研究與實務應用的成果與心得，一齊研討在面對全球環境變遷中，如何透過多元文化創新思維，回應時代趨勢、連結群體和展望未來，以持續探索藝術的永續創造力。', `organizer`='國立臺北藝術大學藝術行政與管理研究所', `address`='臺北市北投區學園路1號', `start_date`='2025-05-09 00:00:00', `end_date`='2025-05-09 00:00:00', `location`='國立臺北藝術大學', `latitude`=25.1480682, `longitude`=121.5177992, `ticket_price`='無資料', `source_url`='https://semmamtnua.weebly.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadbd26b3242b74a3b0f7', '「愛與尊重~性別平等」-主題書展(繪本)', '本館希望藉由辦理之『主題書展』，使到館民眾進一步認識館藏資源。入選的書具相當可讀性「是好書、也是好看的書」而我們期許，所展示的主題書籍，都能讓讀者促進性別地位之實質平等，消除性別歧視，維護人格尊嚴，厚植並建立性別平等之教育資源與環境。\r\n', '高雄市立圖書館總館', '高雄市茄萣區24鄰濱海路四段31巷1號', '2025-04-01 00:00:00', '2025-04-30 00:00:00', '高雄市立圖書館茄萣分館', 22.9068919, 120.1824779, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「愛與尊重~性別平等」-主題書展(繪本)', `description`='本館希望藉由辦理之『主題書展』，使到館民眾進一步認識館藏資源。入選的書具相當可讀性「是好書、也是好看的書」而我們期許，所展示的主題書籍，都能讓讀者促進性別地位之實質平等，消除性別歧視，維護人格尊嚴，厚植並建立性別平等之教育資源與環境。\r\n', `organizer`='高雄市立圖書館總館', `address`='高雄市茄萣區24鄰濱海路四段31巷1號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='高雄市立圖書館茄萣分館', `latitude`=22.9068919, `longitude`=120.1824779, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc126b3242b74a3b0f8', 'SDGs繪本主題書展：海好有你．守護環境', '藉由SDGs永續發展與海洋主題結合，展示海洋相關繪本書展呈現多種與海洋生物、環境保護、海洋冒險等主題相關的繪本故事，提高兒童對於海洋的重要性和保護的意識及可持續發展的認識，透過結合繪本，展示了海洋生態系統的重要性及其面臨的挑戰，例如海洋汙染、氣候變化和過度捕撈等。讓孩子們更容易理解海洋生態系統與環境的互動。', '高雄市立圖書館總館', '高雄市旗山區大德里6鄰中學路42號', '2025-05-01 00:00:00', '2025-06-30 00:00:00', '高雄市立圖書館旗山分館', 25.0421407, 121.5198716, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='SDGs繪本主題書展：海好有你．守護環境', `description`='藉由SDGs永續發展與海洋主題結合，展示海洋相關繪本書展呈現多種與海洋生物、環境保護、海洋冒險等主題相關的繪本故事，提高兒童對於海洋的重要性和保護的意識及可持續發展的認識，透過結合繪本，展示了海洋生態系統的重要性及其面臨的挑戰，例如海洋汙染、氣候變化和過度捕撈等。讓孩子們更容易理解海洋生態系統與環境的互動。', `organizer`='高雄市立圖書館總館', `address`='高雄市旗山區大德里6鄰中學路42號', `start_date`='2025-05-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='高雄市立圖書館旗山分館', `latitude`=25.0421407, `longitude`=121.5198716, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc126b3242b74a3b0f9', '114年路竹分館6月書展', '1.閱讀無界：暹羅書卷,微笑國度的文化風情:泰國這個被譽為「微笑國度」的神奇土地，透過書展提供讀者領略泰國的文學與文化遺產，體驗到泰國的宗教信仰、社會風貌、音樂、舞蹈及民俗等元素!探索這個國家的獨特魅力與深厚底蘊。走進這片充滿熱情、信仰與故事的土地，讓我們一同在文字中感受泰國文化的獨特風情，發現「微笑國度」背後的深刻人文情懷。\r\n2.閱讀無界：在地書語,台灣文學的軌跡：台灣擁有深厚且多元的文學底蘊，從原住民的口述故事，到清朝、日治時期的文學作品，再到當代作家的創作，台灣的文學風貌不斷發展，深深扎根於這片土地的歷史、文化和人民的心靈。書展提供讀者穿越時空，探索台灣文學的發展脈絡，並感受這片土地上的故事,如何形成獨特的在地文學景觀。在書頁中找到台灣的靈魂，從過去的故事中汲取對未來的啟發。', '高雄市立圖書館總館', '高雄市路竹區24鄰國昌路86巷9號', '2025-06-01 00:00:00', '2025-06-30 00:00:00', '高雄市立圖書館路竹分館', 22.8541831, 120.2611866, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年路竹分館6月書展', `description`='1.閱讀無界：暹羅書卷,微笑國度的文化風情:泰國這個被譽為「微笑國度」的神奇土地，透過書展提供讀者領略泰國的文學與文化遺產，體驗到泰國的宗教信仰、社會風貌、音樂、舞蹈及民俗等元素!探索這個國家的獨特魅力與深厚底蘊。走進這片充滿熱情、信仰與故事的土地，讓我們一同在文字中感受泰國文化的獨特風情，發現「微笑國度」背後的深刻人文情懷。\r\n2.閱讀無界：在地書語,台灣文學的軌跡：台灣擁有深厚且多元的文學底蘊，從原住民的口述故事，到清朝、日治時期的文學作品，再到當代作家的創作，台灣的文學風貌不斷發展，深深扎根於這片土地的歷史、文化和人民的心靈。書展提供讀者穿越時空，探索台灣文學的發展脈絡，並感受這片土地上的故事,如何形成獨特的在地文學景觀。在書頁中找到台灣的靈魂，從過去的故事中汲取對未來的啟發。', `organizer`='高雄市立圖書館總館', `address`='高雄市路竹區24鄰國昌路86巷9號', `start_date`='2025-06-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='高雄市立圖書館路竹分館', `latitude`=22.8541831, `longitude`=120.2611866, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc126b3242b74a3b0fa', '114年路竹分館6月FUN心聽故事', '由故事達人透過繪本故事說演，引導親子共讀繪本故事，進入故事情境，進而喜歡閱讀，並配合親子共讀，設計延伸活動。\r\n6/7  許靜淑老師 /繪本童樂會\r\n6/14 默默老師 /藝起話繪本\r\n6/21 林春秀老師 /童繪島\r\n6/28 潘慧君老師 /英文繪本故事', '高雄市立圖書館總館', '高雄市路竹區24鄰國昌路86巷9號', '2025-06-07 00:00:00', '2025-06-28 00:00:00', '高雄市立圖書館路竹分館', 22.8541831, 120.2611866, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年路竹分館6月FUN心聽故事', `description`='由故事達人透過繪本故事說演，引導親子共讀繪本故事，進入故事情境，進而喜歡閱讀，並配合親子共讀，設計延伸活動。\r\n6/7  許靜淑老師 /繪本童樂會\r\n6/14 默默老師 /藝起話繪本\r\n6/21 林春秀老師 /童繪島\r\n6/28 潘慧君老師 /英文繪本故事', `organizer`='高雄市立圖書館總館', `address`='高雄市路竹區24鄰國昌路86巷9號', `start_date`='2025-06-07 00:00:00', `end_date`='2025-06-28 00:00:00', `location`='高雄市立圖書館路竹分館', `latitude`=22.8541831, `longitude`=120.2611866, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc226b3242b74a3b0fb', '幼愛聽故事-繪本故事說演(永安社區公共托育家園)', '由故事達人於幼兒園或育兒資源中心辦理故事說演活動，並透過故事導讀與討論發想，提取學齡前幼兒對繪本故事的興趣與表達自己對故事內容的想像與創造。\r\n繪本書名-刷牙號小火車，出發!', '高雄市立圖書館總館', '高雄市永安區', '2025-05-14 00:00:00', '2025-05-14 00:00:00', '永安區（高雄市）=', 22.82224585, 120.228051, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='幼愛聽故事-繪本故事說演(永安社區公共托育家園)', `description`='由故事達人於幼兒園或育兒資源中心辦理故事說演活動，並透過故事導讀與討論發想，提取學齡前幼兒對繪本故事的興趣與表達自己對故事內容的想像與創造。\r\n繪本書名-刷牙號小火車，出發!', `organizer`='高雄市立圖書館總館', `address`='高雄市永安區', `start_date`='2025-05-14 00:00:00', `end_date`='2025-05-14 00:00:00', `location`='永安區（高雄市）=', `latitude`=22.82224585, `longitude`=120.228051, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
