INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc326b3242b74a3b100', '善化區圖書館：上半年第二期藝文研習班', '善圖為推廣普及藝文活動特開設3個月為一期的藝文研習班，特聘請專業師資到館教授，課程頗受好評，讓藝文活動更加深入民眾生活。課程分別有台語文化班、兒童美術A、B班、書法早班、花鳥水墨畫班瑜珈早、晚班、肌力及墊上核心班。', '臺南市善化區圖書館', '臺南市善化區中山路377號3樓', '2025-04-01 00:00:00', '2025-06-30 00:00:00', '臺南市善化區圖書館', 23.14031072, 120.2988274, '--+--', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='善化區圖書館：上半年第二期藝文研習班', `description`='善圖為推廣普及藝文活動特開設3個月為一期的藝文研習班，特聘請專業師資到館教授，課程頗受好評，讓藝文活動更加深入民眾生活。課程分別有台語文化班、兒童美術A、B班、書法早班、花鳥水墨畫班瑜珈早、晚班、肌力及墊上核心班。', `organizer`='臺南市善化區圖書館', `address`='臺南市善化區中山路377號3樓', `start_date`='2025-04-01 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='臺南市善化區圖書館', `latitude`=23.14031072, `longitude`=120.2988274, `ticket_price`='--+--', `source_url`='無資料', `image_url`='[]';
