INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc326b3242b74a3b103', '與愛唯舞', '推廣正統中東民俗舞蹈藝術，增加花蓮舞蹈藝術之多元面向。\r\n提升團員舞台的表現力，並啟發團員之表演潛能。\r\n讓民眾體認中東舞蹈之風行形式，推廣大眾熱情參與體驗，更以中東舞高階舞碼展演提供花蓮民眾深入認識中東舞蹈的管道，達到娛樂健身之全民運動。', '花蓮縣政府', '花蓮縣秀林鄉', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '秀林鄉（花蓮縣）=', 24.12374414, 121.4807194, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='與愛唯舞', `description`='推廣正統中東民俗舞蹈藝術，增加花蓮舞蹈藝術之多元面向。\r\n提升團員舞台的表現力，並啟發團員之表演潛能。\r\n讓民眾體認中東舞蹈之風行形式，推廣大眾熱情參與體驗，更以中東舞高階舞碼展演提供花蓮民眾深入認識中東舞蹈的管道，達到娛樂健身之全民運動。', `organizer`='花蓮縣政府', `address`='花蓮縣秀林鄉', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='秀林鄉（花蓮縣）=', `latitude`=24.12374414, `longitude`=121.4807194, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
