INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc426b3242b74a3b10a', '狐獴家族馬戲團', '一場結合戲劇、雜技與舞蹈的跨界藝術盛宴——《狐獴家族馬戲團》創新無動物的表演模式，打造充滿互動與樂趣的兒童劇場，讓小朋友們在歡樂的氛圍中，學習尊重生命、愛護動物。\r\n🎭 戲劇 × 雜技 × 舞蹈，跨界融合互動體驗\r\n透過多元藝術形式的巧妙結合，《狐獴家族馬戲團》不僅讓觀眾享受視覺與感官的精彩饗宴，更透過高互動性的設計，讓孩子們全程投入參與，成為劇情的一份子。\r\n✨ 沉浸式互動遊戲，深度體驗角色心境\r\n劇場特別設計的沉浸式互動遊戲，讓孩子們不只是旁觀者，更是故事的推動者，透過親身體驗角色轉變，深化尊重生命與理解動物權益的概念。\r\n《狐獴家族馬戲團》期盼透過寓教於樂的方式，讓孩子們從小培養同理心，理解並實踐對動物及環境的愛護，攜手創造更友善、更美好的未來世界！', '花蓮縣政府', '花蓮縣吉安鄉', '2025-08-24 00:00:00', '2025-08-24 00:00:00', '吉安鄉（花蓮縣）=', 23.95546585, 121.5646738, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='狐獴家族馬戲團', `description`='一場結合戲劇、雜技與舞蹈的跨界藝術盛宴——《狐獴家族馬戲團》創新無動物的表演模式，打造充滿互動與樂趣的兒童劇場，讓小朋友們在歡樂的氛圍中，學習尊重生命、愛護動物。\r\n🎭 戲劇 × 雜技 × 舞蹈，跨界融合互動體驗\r\n透過多元藝術形式的巧妙結合，《狐獴家族馬戲團》不僅讓觀眾享受視覺與感官的精彩饗宴，更透過高互動性的設計，讓孩子們全程投入參與，成為劇情的一份子。\r\n✨ 沉浸式互動遊戲，深度體驗角色心境\r\n劇場特別設計的沉浸式互動遊戲，讓孩子們不只是旁觀者，更是故事的推動者，透過親身體驗角色轉變，深化尊重生命與理解動物權益的概念。\r\n《狐獴家族馬戲團》期盼透過寓教於樂的方式，讓孩子們從小培養同理心，理解並實踐對動物及環境的愛護，攜手創造更友善、更美好的未來世界！', `organizer`='花蓮縣政府', `address`='花蓮縣吉安鄉', `start_date`='2025-08-24 00:00:00', `end_date`='2025-08-24 00:00:00', `location`='吉安鄉（花蓮縣）=', `latitude`=23.95546585, `longitude`=121.5646738, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc426b3242b74a3b10b', '兔兔的紅蘿蔔不見了！', '以魔術為創作核心的兒童劇團，讓孩子們都可以走進魔法的世界。', '花蓮縣政府', '花蓮縣吉安鄉', '2025-10-10 00:00:00', '2025-10-10 00:00:00', '吉安鄉（花蓮縣）=', 23.95546585, 121.5646738, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='兔兔的紅蘿蔔不見了！', `description`='以魔術為創作核心的兒童劇團，讓孩子們都可以走進魔法的世界。', `organizer`='花蓮縣政府', `address`='花蓮縣吉安鄉', `start_date`='2025-10-10 00:00:00', `end_date`='2025-10-10 00:00:00', `location`='吉安鄉（花蓮縣）=', `latitude`=23.95546585, `longitude`=121.5646738, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc426b3242b74a3b10c', '馬戲親子劇《雨星奇幻記》', '寶弟從小和爸爸一起住在飛行星球上，他最喜歡聽爸爸分享宇宙任務中的各種故事。\r\n爸爸說，宇宙中充滿各式各樣有趣的事，只是雖然很刺激，卻也充滿著危險，因此寶弟從來沒有離開過飛行星球，那裡，很安全。但是某天，爸爸為了新任務出門後，就再也沒有回來了……寶弟決定，帶著爸爸的飛行手冊，勇闖宇宙世界去找爸爸！\r\n當寶弟踏出星球才發現，原來爸爸平時故事裡的角色都是真的！活生生的紅綠燈姐妹花，出現在寶弟的眼前，她們正在討論近期出現的宇宙病毒。聽說，只要被病毒傳染後，頭就只能低低的、完全抬不起來，脖子肩膀還會變得僵硬，性情瞬間冷血無情！而且這個宇宙病毒還進一步，導致了許多交通事故？\r\n寶弟的爸爸該不會跟這個宇宙病毒有關係吧？寶弟的找爸爸之旅，越走越深了，他來到了爸爸工作的地方。接下來，他還會發現什麼驚天動地的秘密呢？一起來一探究竟吧！', '花蓮縣政府', '花蓮縣壽豐鄉', '2025-07-12 00:00:00', '2025-07-12 00:00:00', '壽豐鄉（花蓮縣）=', 23.84459714, 121.5341569, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='馬戲親子劇《雨星奇幻記》', `description`='寶弟從小和爸爸一起住在飛行星球上，他最喜歡聽爸爸分享宇宙任務中的各種故事。\r\n爸爸說，宇宙中充滿各式各樣有趣的事，只是雖然很刺激，卻也充滿著危險，因此寶弟從來沒有離開過飛行星球，那裡，很安全。但是某天，爸爸為了新任務出門後，就再也沒有回來了……寶弟決定，帶著爸爸的飛行手冊，勇闖宇宙世界去找爸爸！\r\n當寶弟踏出星球才發現，原來爸爸平時故事裡的角色都是真的！活生生的紅綠燈姐妹花，出現在寶弟的眼前，她們正在討論近期出現的宇宙病毒。聽說，只要被病毒傳染後，頭就只能低低的、完全抬不起來，脖子肩膀還會變得僵硬，性情瞬間冷血無情！而且這個宇宙病毒還進一步，導致了許多交通事故？\r\n寶弟的爸爸該不會跟這個宇宙病毒有關係吧？寶弟的找爸爸之旅，越走越深了，他來到了爸爸工作的地方。接下來，他還會發現什麼驚天動地的秘密呢？一起來一探究竟吧！', `organizer`='花蓮縣政府', `address`='花蓮縣壽豐鄉', `start_date`='2025-07-12 00:00:00', `end_date`='2025-07-12 00:00:00', `location`='壽豐鄉（花蓮縣）=', `latitude`=23.84459714, `longitude`=121.5341569, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc426b3242b74a3b10d', '晃晃二手書店｜2025進入書書果實世界', '活動 ✧ 書店串連 ྾ 書服閱讀 ྾ 書菜品嚐\r\n     ྾ 展場說書 ྾ 秘寶解說 ྾ 學校出攤✧\r\n「書書果實」特別選在 5 月 17、18 （六丶日），與「國際博物館日」同步，於國立臺灣史前文化博物館舉行，在博物館更靠近閱讀，也讓閱讀用不一樣的方式走進博物館。\r\n博物館不該只是靜態展示的空間，而是與日常生活相連的場域。「書書果實」這場「獨立書店X博物館日」創新書市，將閱讀與博物館之間的界線打開，讓知識與想像力自由流動在這片充滿歷史記憶的地方。\r\n​\r\n5/17-18 民眾可免費參觀史前館，所有人都能親近這裡，青少年更能夠在此時好好 #使用文化幣。\r\n\r\n閱讀不只是靜態也是一場流動的體驗，每個人都能從不同角度找到與書的連結。「書書果實」讓閱讀不只是書架上的靜物，讓書融入日常生活也成為節慶盛會的一部分。\r\n除了這場創新書市庄頭書展，另外還有𝟭𝟬 條走讀路徑、好幾場台東影痴結合跨域開講，帶你一整年都能走入書書果實的世界 ！', '晃晃二手書店', '臺東縣臺東市博物館路1號', '2025-05-17 00:00:00', '2025-05-18 00:00:00', '國立臺灣史前文化博物館-康樂本館', 22.75165721, 121.1103647, '優待票+50;團體票+60;全票+80', 'https://www.facebook.com/089catbooks', '[]') ON DUPLICATE KEY UPDATE `activity_name`='晃晃二手書店｜2025進入書書果實世界', `description`='活動 ✧ 書店串連 ྾ 書服閱讀 ྾ 書菜品嚐\r\n     ྾ 展場說書 ྾ 秘寶解說 ྾ 學校出攤✧\r\n「書書果實」特別選在 5 月 17、18 （六丶日），與「國際博物館日」同步，於國立臺灣史前文化博物館舉行，在博物館更靠近閱讀，也讓閱讀用不一樣的方式走進博物館。\r\n博物館不該只是靜態展示的空間，而是與日常生活相連的場域。「書書果實」這場「獨立書店X博物館日」創新書市，將閱讀與博物館之間的界線打開，讓知識與想像力自由流動在這片充滿歷史記憶的地方。\r\n​\r\n5/17-18 民眾可免費參觀史前館，所有人都能親近這裡，青少年更能夠在此時好好 #使用文化幣。\r\n\r\n閱讀不只是靜態也是一場流動的體驗，每個人都能從不同角度找到與書的連結。「書書果實」讓閱讀不只是書架上的靜物，讓書融入日常生活也成為節慶盛會的一部分。\r\n除了這場創新書市庄頭書展，另外還有𝟭𝟬 條走讀路徑、好幾場台東影痴結合跨域開講，帶你一整年都能走入書書果實的世界 ！', `organizer`='晃晃二手書店', `address`='臺東縣臺東市博物館路1號', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='國立臺灣史前文化博物館-康樂本館', `latitude`=22.75165721, `longitude`=121.1103647, `ticket_price`='優待票+50;團體票+60;全票+80', `source_url`='https://www.facebook.com/089catbooks', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc426b3242b74a3b10e', '狐獴家族馬戲團', '一場結合戲劇、雜技與舞蹈的跨界藝術盛宴——《狐獴家族馬戲團》創新無動物的表演模式，打造充滿互動與樂趣的兒童劇場，讓小朋友們在歡樂的氛圍中，學習尊重生命、愛護動物。\r\n🎭 戲劇 × 雜技 × 舞蹈，跨界融合互動體驗\r\n透過多元藝術形式的巧妙結合，《狐獴家族馬戲團》不僅讓觀眾享受視覺與感官的精彩饗宴，更透過高互動性的設計，讓孩子們全程投入參與，成為劇情的一份子。\r\n✨ 沉浸式互動遊戲，深度體驗角色心境\r\n劇場特別設計的沉浸式互動遊戲，讓孩子們不只是旁觀者，更是故事的推動者，透過親身體驗角色轉變，深化尊重生命與理解動物權益的概念。\r\n《狐獴家族馬戲團》期盼透過寓教於樂的方式，讓孩子們從小培養同理心，理解並實踐對動物及環境的愛護，攜手創造更友善、更美好的未來世界！', '花蓮縣政府', '花蓮縣鳳林鎮', '2025-08-23 00:00:00', '2025-08-23 00:00:00', '鳳林鎮（花蓮縣）=', 23.74324462, 121.4698848, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='狐獴家族馬戲團', `description`='一場結合戲劇、雜技與舞蹈的跨界藝術盛宴——《狐獴家族馬戲團》創新無動物的表演模式，打造充滿互動與樂趣的兒童劇場，讓小朋友們在歡樂的氛圍中，學習尊重生命、愛護動物。\r\n🎭 戲劇 × 雜技 × 舞蹈，跨界融合互動體驗\r\n透過多元藝術形式的巧妙結合，《狐獴家族馬戲團》不僅讓觀眾享受視覺與感官的精彩饗宴，更透過高互動性的設計，讓孩子們全程投入參與，成為劇情的一份子。\r\n✨ 沉浸式互動遊戲，深度體驗角色心境\r\n劇場特別設計的沉浸式互動遊戲，讓孩子們不只是旁觀者，更是故事的推動者，透過親身體驗角色轉變，深化尊重生命與理解動物權益的概念。\r\n《狐獴家族馬戲團》期盼透過寓教於樂的方式，讓孩子們從小培養同理心，理解並實踐對動物及環境的愛護，攜手創造更友善、更美好的未來世界！', `organizer`='花蓮縣政府', `address`='花蓮縣鳳林鎮', `start_date`='2025-08-23 00:00:00', `end_date`='2025-08-23 00:00:00', `location`='鳳林鎮（花蓮縣）=', `latitude`=23.74324462, `longitude`=121.4698848, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
