INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc426b3242b74a3b110', '搏逗兄弟經典秀', '無資料', '花蓮縣政府', '花蓮縣萬榮鄉', '2025-05-08 00:00:00', '2025-05-08 00:00:00', '萬榮鄉（花蓮縣）=', 23.72772629, 121.3189531, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='搏逗兄弟經典秀', `description`='無資料', `organizer`='花蓮縣政府', `address`='花蓮縣萬榮鄉', `start_date`='2025-05-08 00:00:00', `end_date`='2025-05-08 00:00:00', `location`='萬榮鄉（花蓮縣）=', `latitude`=23.72772629, `longitude`=121.3189531, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc426b3242b74a3b111', '馬戲親子劇《雨星奇幻記》', '天馬戲創作劇團，為臺灣第一個大膽創作原創馬戲音樂劇的藝文團體，成立於2020年，致力讓馬戲走進音樂劇文本之中，創造獨特、全新的表演形式，拓展藝文新市場，並在商業與藝文之間取得平衡，同時參與公益團體、文教基金會的教育合作，將藝術深耕至校園。在積極創作的同時，也培養孩童藝術知能與鑑賞力。', '花蓮縣政府', '花蓮縣光復鄉', '2025-07-13 00:00:00', '2025-07-13 00:00:00', '光復鄉（花蓮縣）=', 23.64658742, 121.4351231, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='馬戲親子劇《雨星奇幻記》', `description`='天馬戲創作劇團，為臺灣第一個大膽創作原創馬戲音樂劇的藝文團體，成立於2020年，致力讓馬戲走進音樂劇文本之中，創造獨特、全新的表演形式，拓展藝文新市場，並在商業與藝文之間取得平衡，同時參與公益團體、文教基金會的教育合作，將藝術深耕至校園。在積極創作的同時，也培養孩童藝術知能與鑑賞力。', `organizer`='花蓮縣政府', `address`='花蓮縣光復鄉', `start_date`='2025-07-13 00:00:00', `end_date`='2025-07-13 00:00:00', `location`='光復鄉（花蓮縣）=', `latitude`=23.64658742, `longitude`=121.4351231, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc426b3242b74a3b112', '歌仔戲~三人五目演出', '後山劇坊前身為花蓮勝安宮戲曲班；民國107/5正式立案為後山劇坊。後山意謂在花蓮，推廣深耕歌仔戲，讓廣大民眾能有欣賞及學習歌仔戲的機會。', '花蓮縣政府', '花蓮縣光復鄉', '2025-07-19 00:00:00', '2025-07-19 00:00:00', '光復鄉（花蓮縣）=', 23.64658742, 121.4351231, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='歌仔戲~三人五目演出', `description`='後山劇坊前身為花蓮勝安宮戲曲班；民國107/5正式立案為後山劇坊。後山意謂在花蓮，推廣深耕歌仔戲，讓廣大民眾能有欣賞及學習歌仔戲的機會。', `organizer`='花蓮縣政府', `address`='花蓮縣光復鄉', `start_date`='2025-07-19 00:00:00', `end_date`='2025-07-19 00:00:00', `location`='光復鄉（花蓮縣）=', `latitude`=23.64658742, `longitude`=121.4351231, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
