INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc426b3242b74a3b115', '奇奇怪怪的小馬戲', '【艸創心演擊樂場】為結合武術特技雜技演奏鼓樂概念的多方位劇團，本團名為艸創心的意思是以草創時的艱辛過程來命名，讓我們不忘原本初衷之心，來為鼓團創造出各種富有想像力的表演節目。', '花蓮縣政府', '花蓮縣瑞穗鄉', '2025-08-06 00:00:00', '2025-08-06 00:00:00', '瑞穗鄉（花蓮縣）=', 23.5156124, 121.4073472, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='奇奇怪怪的小馬戲', `description`='【艸創心演擊樂場】為結合武術特技雜技演奏鼓樂概念的多方位劇團，本團名為艸創心的意思是以草創時的艱辛過程來命名，讓我們不忘原本初衷之心，來為鼓團創造出各種富有想像力的表演節目。', `organizer`='花蓮縣政府', `address`='花蓮縣瑞穗鄉', `start_date`='2025-08-06 00:00:00', `end_date`='2025-08-06 00:00:00', `location`='瑞穗鄉（花蓮縣）=', `latitude`=23.5156124, `longitude`=121.4073472, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
