INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc426b3242b74a3b117', '新營文化中心圖書館-4月袋鼠媽媽說故事', '04/05(六) 10:00 我才不要捲頭髮、霸道小公主\r\n04/12(六) 10:00 蝌蚪的諾言、奶茶好好喝\r\n04/13(日) 10:00 胡子碰碰、小蛇肚子咕嚕嚕\r\n04/19(六) 10:00 Big boy cry、我不是討厭鬼\r\n04/26(六) 10:00 彩虹豬、小老鼠的夢想\r\n04/27(日) 10:00 花婆婆、但願我是小蝴蝶\r\n', '臺南市政府文化局', '臺南市新營區中正路23號', '2025-04-05 00:00:00', '2025-04-27 00:00:00', '臺南市新營文化中心', 23.30152488, 120.2954067, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='新營文化中心圖書館-4月袋鼠媽媽說故事', `description`='04/05(六) 10:00 我才不要捲頭髮、霸道小公主\r\n04/12(六) 10:00 蝌蚪的諾言、奶茶好好喝\r\n04/13(日) 10:00 胡子碰碰、小蛇肚子咕嚕嚕\r\n04/19(六) 10:00 Big boy cry、我不是討厭鬼\r\n04/26(六) 10:00 彩虹豬、小老鼠的夢想\r\n04/27(日) 10:00 花婆婆、但願我是小蝴蝶\r\n', `organizer`='臺南市政府文化局', `address`='臺南市新營區中正路23號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺南市新營文化中心', `latitude`=23.30152488, `longitude`=120.2954067, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc426b3242b74a3b118', '科學嚇嚇叫', '絲巾變真雞蛋，雞蛋變壽星蛋糕！探索趣味科學的奇妙之旅！\r\n歡迎來到我們的特別活動——“絲巾變真雞蛋，雞蛋在變壽星蛋糕”魔術科學秀！這是一次充滿魔幻與驚喜的互動體驗，讓你在玩樂中充分理解科學原理，同時也能享受到個性化的創意樂趣！', '花蓮縣政府', '花蓮縣卓溪鄉', '2025-10-24 00:00:00', '2025-10-24 00:00:00', '卓溪鄉（花蓮縣）=', 23.39062875, 121.1804222, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='科學嚇嚇叫', `description`='絲巾變真雞蛋，雞蛋變壽星蛋糕！探索趣味科學的奇妙之旅！\r\n歡迎來到我們的特別活動——“絲巾變真雞蛋，雞蛋在變壽星蛋糕”魔術科學秀！這是一次充滿魔幻與驚喜的互動體驗，讓你在玩樂中充分理解科學原理，同時也能享受到個性化的創意樂趣！', `organizer`='花蓮縣政府', `address`='花蓮縣卓溪鄉', `start_date`='2025-10-24 00:00:00', `end_date`='2025-10-24 00:00:00', `location`='卓溪鄉（花蓮縣）=', `latitude`=23.39062875, `longitude`=121.1804222, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
