INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc526b3242b74a3b11e', '2025太平洋左岸藝術季-AM創意《虎姑婆和他的朋友》音樂劇', '2025太平洋左岸藝術季特選演出，由富邦文教基金會授權，改編自同名新媒體跨域兒少節目，AM創意2025最新溫暖力作前進花蓮：《虎姑婆和他的朋友》音樂劇。\r\n徹底翻轉台灣民間經典故事「虎姑婆」，揮別過往對虎姑婆的恐怖印象，這次保證不唬嚨小孩，還要跟一群音樂夥伴一起歡快歌唱，在化為美麗魔法音樂森林的劇場裡，零距離陪伴孩子一起面對煩惱，戰勝恐懼！', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-06-01 00:00:00', '2025-06-01 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '全票+500;全票+700;全票+900;全票+1200', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025太平洋左岸藝術季-AM創意《虎姑婆和他的朋友》音樂劇', `description`='2025太平洋左岸藝術季特選演出，由富邦文教基金會授權，改編自同名新媒體跨域兒少節目，AM創意2025最新溫暖力作前進花蓮：《虎姑婆和他的朋友》音樂劇。\r\n徹底翻轉台灣民間經典故事「虎姑婆」，揮別過往對虎姑婆的恐怖印象，這次保證不唬嚨小孩，還要跟一群音樂夥伴一起歡快歌唱，在化為美麗魔法音樂森林的劇場裡，零距離陪伴孩子一起面對煩惱，戰勝恐懼！', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-06-01 00:00:00', `end_date`='2025-06-01 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='全票+500;全票+700;全票+900;全票+1200', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc526b3242b74a3b11f', '全民大劇團--喜劇擋不住—校狗也在逃？！', '「有時在想，我究竟是老師，還是馴獸師？」招生無所不用其極、招來的學生有夠嗆，嚇到老師要吃手手....？\r\n看來要待下去我得麻辣一點！學生打罵不得，你的武器就是「喜劇」。四位演員進入校園各出奇招，用笑聲解決危機、用故事傳遞溫暖。換個角度、加一點時間，很多事情就用笑聲帶過！心靈課程、校園霸凌、大舞台直接社死、跨年演唱大走音.....演員們親身經歷，和超ing的時事梗這邊說給你聽！ 成為「麻辣仙師」前，原來有這段經歷~', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '全票+300;全票+500;全票+700', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='全民大劇團--喜劇擋不住—校狗也在逃？！', `description`='「有時在想，我究竟是老師，還是馴獸師？」招生無所不用其極、招來的學生有夠嗆，嚇到老師要吃手手....？\r\n看來要待下去我得麻辣一點！學生打罵不得，你的武器就是「喜劇」。四位演員進入校園各出奇招，用笑聲解決危機、用故事傳遞溫暖。換個角度、加一點時間，很多事情就用笑聲帶過！心靈課程、校園霸凌、大舞台直接社死、跨年演唱大走音.....演員們親身經歷，和超ing的時事梗這邊說給你聽！ 成為「麻辣仙師」前，原來有這段經歷~', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='全票+300;全票+500;全票+700', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc526b3242b74a3b121', '有序音樂研習所：2025 電影配樂基礎創作班', '✔  曾經腦中有旋律與想法，卻不知道如何將他完整呈現嗎？\r\n\r\n✔  想幫一段畫面配上一段合適的音樂卻無從下手？\r\n\r\n✔  想了解電影配樂從無到有的過程？\r\n\r\n✔  想完成一部屬於自己的音樂作品？\r\n\r\n\r\n歡迎來到好評開辦第三屆的【有序音樂研習所 - 電影配樂基礎創作班】！\r\n由作品豐碩且常獲好評，同時具備專業教學背景與經驗的周宣宏老師（紐約大學電影配樂碩士、衛武營教學藝術家、高雄市管樂團駐團作曲家），帶領大家仔細從音樂理論與聽覺美學扎根，配合經典與當代電影配樂的精讀分析，加上數位音樂實作技術，來經歷電影配樂創作的每一段過程，一步一步在 27 小時內帶您完成屬於自己的作品！', '有序音樂 Texture Music', '高雄市鹽埕區17鄰真愛路1號', '2025-04-11 00:00:00', '2025-04-26 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '三人以上團報+8000;早鳥優惠價至3月31日+9000;原價+10000', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='有序音樂研習所：2025 電影配樂基礎創作班', `description`='✔  曾經腦中有旋律與想法，卻不知道如何將他完整呈現嗎？\r\n\r\n✔  想幫一段畫面配上一段合適的音樂卻無從下手？\r\n\r\n✔  想了解電影配樂從無到有的過程？\r\n\r\n✔  想完成一部屬於自己的音樂作品？\r\n\r\n\r\n歡迎來到好評開辦第三屆的【有序音樂研習所 - 電影配樂基礎創作班】！\r\n由作品豐碩且常獲好評，同時具備專業教學背景與經驗的周宣宏老師（紐約大學電影配樂碩士、衛武營教學藝術家、高雄市管樂團駐團作曲家），帶領大家仔細從音樂理論與聽覺美學扎根，配合經典與當代電影配樂的精讀分析，加上數位音樂實作技術，來經歷電影配樂創作的每一段過程，一步一步在 27 小時內帶您完成屬於自己的作品！', `organizer`='有序音樂 Texture Music', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-04-11 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='三人以上團報+8000;早鳥優惠價至3月31日+9000;原價+10000', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc526b3242b74a3b123', 'May We Jazz？｜爵式人聲樂團', 'May We Jazz？｜爵式人聲樂團\r\nWiJazz Singers，來自南台灣的首支 Vocal Jazz 人聲樂團，以融合爵士精神與純粹人聲為理念，致力於將 vocal jazz 的經典魅力以嶄新形式帶進大眾視野。\r\n–\r\n本次音樂會以「May We Jazz」為題，既是春日的邀約，也是對爵士的深情告白。曲目涵蓋多首經典爵士歌曲，從 Swing、Samba 到 Ballad，讓聽眾在流動的節奏與細膩的聲線中，感受 vocal jazz 的自由、溫柔與靈魂。\r\n–\r\n誠摯邀請您走進聲音的爵士夜晚，一同見證 WiJazz Singers 的首次綻放，為這個五月，灑下屬於音樂與人聲的光芒。', '爵式 WiJazz Records', '高雄市鹽埕區17鄰真愛路1號', '2025-05-01 00:00:00', '2025-05-01 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人+500;雙人+800', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='May We Jazz？｜爵式人聲樂團', `description`='May We Jazz？｜爵式人聲樂團\r\nWiJazz Singers，來自南台灣的首支 Vocal Jazz 人聲樂團，以融合爵士精神與純粹人聲為理念，致力於將 vocal jazz 的經典魅力以嶄新形式帶進大眾視野。\r\n–\r\n本次音樂會以「May We Jazz」為題，既是春日的邀約，也是對爵士的深情告白。曲目涵蓋多首經典爵士歌曲，從 Swing、Samba 到 Ballad，讓聽眾在流動的節奏與細膩的聲線中，感受 vocal jazz 的自由、溫柔與靈魂。\r\n–\r\n誠摯邀請您走進聲音的爵士夜晚，一同見證 WiJazz Singers 的首次綻放，為這個五月，灑下屬於音樂與人聲的光芒。', `organizer`='爵式 WiJazz Records', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-01 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人+500;雙人+800', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc526b3242b74a3b124', '獸神遊-台韓石雕創作交流', '「獸神遊-台韓石雕創作交流」展覽由花蓮縣石彫協會發起，促成台灣花蓮縣石雕博物館、韓國幕山美術館(MOSAN CONTEMPORARY ART MUSEUM)首次國際交流的契機，也是石博館開館24年來第一次辦理台韓石雕交流展。串聯兩國創作者，邀集台灣29位、韓國11位，以石幻化的作品跨海相會，以「獸神遊」為策展概念，讓不同地域的動物展現交會串聯，於石雕館切磋交流，展開一場藝術慶典。', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-04-12 00:00:00', '2025-06-29 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '全票+20;半票+10', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='獸神遊-台韓石雕創作交流', `description`='「獸神遊-台韓石雕創作交流」展覽由花蓮縣石彫協會發起，促成台灣花蓮縣石雕博物館、韓國幕山美術館(MOSAN CONTEMPORARY ART MUSEUM)首次國際交流的契機，也是石博館開館24年來第一次辦理台韓石雕交流展。串聯兩國創作者，邀集台灣29位、韓國11位，以石幻化的作品跨海相會，以「獸神遊」為策展概念，讓不同地域的動物展現交會串聯，於石雕館切磋交流，展開一場藝術慶典。', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='全票+20;半票+10', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc526b3242b74a3b125', '從５變４的”A Tempo“在5/4號演奏5/4拍音樂', '從５變４的”A Tempo“在5/4號演奏5/4拍音樂\r\n從5人縮編為4人的A Tempo四重奏，這次將在5/4以獨特的「5/4 拍」作為音樂主軸，帶來一場節奏感十足又富有巧思的爵士演出。經典名曲如〈Take Five〉與〈Four〉將被重新詮釋，在節拍與結構上玩出新意，展現出A Tempo對節奏的高度掌握與創造力。除了改編曲目外，還選入如〈Body And Soul〉、〈My Favorite Things〉等風格多元的作品，並融入改編的5/4拍律動，挑戰聽覺的慣性，也帶來嶄新的音樂風景。這場演出既有趣味也具深度，是對「節奏」本身的一次精彩探索。', '爵式 WiJazz Records', '高雄市鹽埕區17鄰真愛路1號', '2025-05-04 00:00:00', '2025-05-04 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人+500;雙人+900', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='從５變４的”A Tempo“在5/4號演奏5/4拍音樂', `description`='從５變４的”A Tempo“在5/4號演奏5/4拍音樂\r\n從5人縮編為4人的A Tempo四重奏，這次將在5/4以獨特的「5/4 拍」作為音樂主軸，帶來一場節奏感十足又富有巧思的爵士演出。經典名曲如〈Take Five〉與〈Four〉將被重新詮釋，在節拍與結構上玩出新意，展現出A Tempo對節奏的高度掌握與創造力。除了改編曲目外，還選入如〈Body And Soul〉、〈My Favorite Things〉等風格多元的作品，並融入改編的5/4拍律動，挑戰聽覺的慣性，也帶來嶄新的音樂風景。這場演出既有趣味也具深度，是對「節奏」本身的一次精彩探索。', `organizer`='爵式 WiJazz Records', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-05-04 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人+500;雙人+900', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc526b3242b74a3b126', 'Original Voice｜雷柏熹爵士三重奏', 'Original Voice｜雷柏熹爵士三重奏\r\n在音符與節奏之間，雷柏熹以鋼琴三重奏書寫屬於自己的聲音。本場演出以雷柏熹原創作品為主，展現他獨到的旋律感與深刻的情感語彙。\r\n–\r\n無論城市風景，還是源於人生片段的情感流動，雷柏熹每首作品都像是一段生活旅程。在本場演出，不只聽見爵士樂律動，更聽見一位音樂創作者的內在聲音。音樂，是他最誠實的語言。', '爵式 WiJazz Records', '高雄市鹽埕區17鄰真愛路1號', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人+500;雙人+900', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Original Voice｜雷柏熹爵士三重奏', `description`='Original Voice｜雷柏熹爵士三重奏\r\n在音符與節奏之間，雷柏熹以鋼琴三重奏書寫屬於自己的聲音。本場演出以雷柏熹原創作品為主，展現他獨到的旋律感與深刻的情感語彙。\r\n–\r\n無論城市風景，還是源於人生片段的情感流動，雷柏熹每首作品都像是一段生活旅程。在本場演出，不只聽見爵士樂律動，更聽見一位音樂創作者的內在聲音。音樂，是他最誠實的語言。', `organizer`='爵式 WiJazz Records', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人+500;雙人+900', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc526b3242b74a3b127', '甜約翰 A Plus Tour - 高雄場', '這是一場長遠的旅程，\r\n顛簸與靜默之後，\r\n車上的人們再度相視而笑，\r\n緩緩駛入尚未被探索的道路，\r\n前方天色泛著微光，\r\n不知是日落還是日出。\r\n \r\n以不插電(Acoustic)手法為基底，加入獨樹一格的編曲手法，成為甜約翰獨有的新風格 “A Plus”，意即Acoustic Plus，重新詮釋多首精選曲目。偏木質調的聲響烘托著主旋律和合音，給予這些作品全新樣貌，讓甜約翰的音樂走入城市裡更多不同角落。', '歪的音樂有限公司', '高雄市鹽埕區17鄰真愛路1號', '2025-05-11 00:00:00', '2025-05-11 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '身障票+400;預售票+800;現場票+1000', 'https://www.indievox.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='甜約翰 A Plus Tour - 高雄場', `description`='這是一場長遠的旅程，\r\n顛簸與靜默之後，\r\n車上的人們再度相視而笑，\r\n緩緩駛入尚未被探索的道路，\r\n前方天色泛著微光，\r\n不知是日落還是日出。\r\n \r\n以不插電(Acoustic)手法為基底，加入獨樹一格的編曲手法，成為甜約翰獨有的新風格 “A Plus”，意即Acoustic Plus，重新詮釋多首精選曲目。偏木質調的聲響烘托著主旋律和合音，給予這些作品全新樣貌，讓甜約翰的音樂走入城市裡更多不同角落。', `organizer`='歪的音樂有限公司', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-05-11 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='身障票+400;預售票+800;現場票+1000', `source_url`='https://www.indievox.com/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc526b3242b74a3b128', '花蓮公共藝術教育展(二) 『PAROD爐灶』撒部‧噶照創作展', '本次展覽以「塑生活、畫意象、唱故事」為架構，梳理藝術家的創作系譜。撒部‧噶照的創作養分多來自土地紋理、故事、自然環境與生態，他常採用竹子、木頭、石頭、土壤等天然媒材形塑作品，並加入諸如鞦韆、座椅、或與植物有機融合等互動性元素，在視覺與美感的創造外，同時拓展作品型態的多元性與可親性。\r\n展名「PAROD」來自阿美族語，意指爐灶或三石灶，象徵藝術家將來自海洋、土地、Makuta‘ay部落所給予的能量、訊息，轉化為視覺、聽覺、心靈感官結合的藝術語言。展出作品涵蓋繪畫、雕塑、音樂、裝置、影像等多元創作形式，呈現創作者在港口部落（Makuta‘ay）的生活及生命經驗，以及對自然環境與族群文化等面向的思索。透過展覽，觀眾將感受藝術家如何在花蓮這個開闊空間的尺度，以豐富的藝術形式使作品與自然環境、空間相融，賦予作品所在場域獨特的意象。\r\n值得一提的是，撒部‧噶照在創作之餘，亦長時間投入阿美族語言、歌謠、音樂旋律的創作，使他在公共藝術與大型戶外裝置創作時，能敏感捕捉空間、環境、媒材之間旋律的共振，令作品與周遭環境相互輝映，與大地景緻共生，展現撼動人心的力量。', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-04-12 00:00:00', '2025-06-29 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '全票+20;半票+10', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='花蓮公共藝術教育展(二) 『PAROD爐灶』撒部‧噶照創作展', `description`='本次展覽以「塑生活、畫意象、唱故事」為架構，梳理藝術家的創作系譜。撒部‧噶照的創作養分多來自土地紋理、故事、自然環境與生態，他常採用竹子、木頭、石頭、土壤等天然媒材形塑作品，並加入諸如鞦韆、座椅、或與植物有機融合等互動性元素，在視覺與美感的創造外，同時拓展作品型態的多元性與可親性。\r\n展名「PAROD」來自阿美族語，意指爐灶或三石灶，象徵藝術家將來自海洋、土地、Makuta‘ay部落所給予的能量、訊息，轉化為視覺、聽覺、心靈感官結合的藝術語言。展出作品涵蓋繪畫、雕塑、音樂、裝置、影像等多元創作形式，呈現創作者在港口部落（Makuta‘ay）的生活及生命經驗，以及對自然環境與族群文化等面向的思索。透過展覽，觀眾將感受藝術家如何在花蓮這個開闊空間的尺度，以豐富的藝術形式使作品與自然環境、空間相融，賦予作品所在場域獨特的意象。\r\n值得一提的是，撒部‧噶照在創作之餘，亦長時間投入阿美族語言、歌謠、音樂旋律的創作，使他在公共藝術與大型戶外裝置創作時，能敏感捕捉空間、環境、媒材之間旋律的共振，令作品與周遭環境相互輝映，與大地景緻共生，展現撼動人心的力量。', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='全票+20;半票+10', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc626b3242b74a3b129', 'Song for My Mother｜雷柏熹爵士三重奏 ft. Amanda', 'Song for My Mother｜雷柏熹爵士三重奏 ft. Amanda\r\n–\r\n在這個溫柔而充滿感謝的節日，讓音樂成為我們獻給母親最深情的禮物。雷柏熹爵士三重奏與歌手Amanda將帶來一場溫暖的母親節特別演出——Song for My Mother，向所有母親獻上最深的敬意。本場演出精選獻給母親的爵士樂章，從動人的抒情旋律到輕柔搖擺的節奏，不論是懷舊的爵士經典，還是即興之作，都是對母親深深的愛與感謝。邀請您與媽媽來與雷柏熹三重奏，在爵士的音樂流動共享一首最美的歌。', '爵式 WiJazz Records', '高雄市鹽埕區17鄰真愛路1號', '2025-05-11 00:00:00', '2025-05-11 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人+600', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='Song for My Mother｜雷柏熹爵士三重奏 ft. Amanda', `description`='Song for My Mother｜雷柏熹爵士三重奏 ft. Amanda\r\n–\r\n在這個溫柔而充滿感謝的節日，讓音樂成為我們獻給母親最深情的禮物。雷柏熹爵士三重奏與歌手Amanda將帶來一場溫暖的母親節特別演出——Song for My Mother，向所有母親獻上最深的敬意。本場演出精選獻給母親的爵士樂章，從動人的抒情旋律到輕柔搖擺的節奏，不論是懷舊的爵士經典，還是即興之作，都是對母親深深的愛與感謝。邀請您與媽媽來與雷柏熹三重奏，在爵士的音樂流動共享一首最美的歌。', `organizer`='爵式 WiJazz Records', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-05-11 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人+600', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc626b3242b74a3b12a', '李世鈞吉他三重奏 ft. 方鏡興', '李世鈞吉他三重奏 ft. 方鏡興\r\n–\r\n城市的喧囂之後，夜色裡的懸音。\r\n由四位爵士樂手組成的爵士吉他四重奏，以細膩的和聲、即興的靈光，一場靜謐而深刻的聲音旅程。\r\n\r\n你會聽見經典爵士的溫度，遇見創作靈魂的火花；主奏吉他的旋律如詩，貝斯穩健流動，鼓聲輕輕敲進心裡。\r\n\r\n一切，都只為那個屬於當下、絕無僅有的夜晚。', '爵式 WiJazz Records', '高雄市鹽埕區17鄰真愛路1號', '2025-05-17 00:00:00', '2025-05-17 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人+600;雙人+1100', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='李世鈞吉他三重奏 ft. 方鏡興', `description`='李世鈞吉他三重奏 ft. 方鏡興\r\n–\r\n城市的喧囂之後，夜色裡的懸音。\r\n由四位爵士樂手組成的爵士吉他四重奏，以細膩的和聲、即興的靈光，一場靜謐而深刻的聲音旅程。\r\n\r\n你會聽見經典爵士的溫度，遇見創作靈魂的火花；主奏吉他的旋律如詩，貝斯穩健流動，鼓聲輕輕敲進心裡。\r\n\r\n一切，都只為那個屬於當下、絕無僅有的夜晚。', `organizer`='爵式 WiJazz Records', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人+600;雙人+1100', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc626b3242b74a3b12b', '聲紋織旅', '聲紋織旅｜吳詠隆 & 葉賀璞\r\n當班多鈕手風琴的探戈語彙，攀附爵士吉他的即興紋理—吳詠隆的琴箱吞吐著布宜諾斯艾利斯的深夜酒館氣息，皮亞佐拉的稜角與地中海民謠的鹹澀，在風箱開闔間凝成霧氣與月光；葉賀璞的六弦則以冷調音色剖開寂靜，分解和弦是星子墜落的軌跡，延音踏板的迴盪如潮水漫過時間裂縫。\r\n–\r\n兩種孤獨的樂器，在二重奏的鏡面空間裡彼此凝視。手風琴簧片的顫動與吉他泛音的漣漪，交織成未經命名的聲景：可能是布魯克林凌晨三點的地下爵士俱樂部，或是南歐老城石板路上被遺忘的即興詩篇。\r\n–\r\n他們的音樂從不複製地圖，只拓印當下呼吸的頻率。', '爵式 WiJazz Records', '高雄市鹽埕區17鄰真愛路1號', '2025-05-24 00:00:00', '2025-05-24 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人+500;雙人+900', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='聲紋織旅', `description`='聲紋織旅｜吳詠隆 & 葉賀璞\r\n當班多鈕手風琴的探戈語彙，攀附爵士吉他的即興紋理—吳詠隆的琴箱吞吐著布宜諾斯艾利斯的深夜酒館氣息，皮亞佐拉的稜角與地中海民謠的鹹澀，在風箱開闔間凝成霧氣與月光；葉賀璞的六弦則以冷調音色剖開寂靜，分解和弦是星子墜落的軌跡，延音踏板的迴盪如潮水漫過時間裂縫。\r\n–\r\n兩種孤獨的樂器，在二重奏的鏡面空間裡彼此凝視。手風琴簧片的顫動與吉他泛音的漣漪，交織成未經命名的聲景：可能是布魯克林凌晨三點的地下爵士俱樂部，或是南歐老城石板路上被遺忘的即興詩篇。\r\n–\r\n他們的音樂從不複製地圖，只拓印當下呼吸的頻率。', `organizer`='爵式 WiJazz Records', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-05-24 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人+500;雙人+900', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc626b3242b74a3b12c', '【憶在日內瓦】雷蒙湖的寂靜呼喚', '【憶在日內瓦】雷蒙湖的寂靜呼喚\r\n三位音樂家在紐約讀書時相識，因為疫情後各自回到自己的國家。去年暑假他們一同到日內瓦演出，隨後開啟來台灣的十場巡演計劃。\r\n–\r\n日內瓦，這座位於瑞士的城市，以其美麗的日內瓦湖而聞名，湖水碧藍，四周群山環繞，悠然的景致為這場音樂會提供了靈感源泉。日內瓦湖的寧靜呼喚彷彿穿越時空，帶領觀眾進入一個融合自然美景與音樂藝術的夢幻世界。\r\n–\r\n此場演出將帶給觀眾歐式爵士風格音樂及改編的傳統爵士曲，並演奏三位音樂家的個人創作曲目。作為音樂家們再度相聚的紀念，這場演出也結合了日內瓦湖畔的寧靜氛圍，讓每一首作品都散發出一種悠然自得的氣質。除此之外，演出中特別改編了鄭雨賢老師的名著〈望春風〉，這首富有台灣風情的經典曲目，在爵士的編曲下，更顯得浪漫與獨特，彷彿將日內瓦湖的柔波與台灣的民謠融合在一起。並希望在這片美麗的土地上與觀眾共同分享他們的音樂旅程。', '爵式 WiJazz Records', '高雄市鹽埕區17鄰真愛路1號', '2025-05-25 00:00:00', '2025-05-25 00:00:00', '高雄流行音樂中心', 22.62424585, 120.2842331, '單人+600', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【憶在日內瓦】雷蒙湖的寂靜呼喚', `description`='【憶在日內瓦】雷蒙湖的寂靜呼喚\r\n三位音樂家在紐約讀書時相識，因為疫情後各自回到自己的國家。去年暑假他們一同到日內瓦演出，隨後開啟來台灣的十場巡演計劃。\r\n–\r\n日內瓦，這座位於瑞士的城市，以其美麗的日內瓦湖而聞名，湖水碧藍，四周群山環繞，悠然的景致為這場音樂會提供了靈感源泉。日內瓦湖的寧靜呼喚彷彿穿越時空，帶領觀眾進入一個融合自然美景與音樂藝術的夢幻世界。\r\n–\r\n此場演出將帶給觀眾歐式爵士風格音樂及改編的傳統爵士曲，並演奏三位音樂家的個人創作曲目。作為音樂家們再度相聚的紀念，這場演出也結合了日內瓦湖畔的寧靜氛圍，讓每一首作品都散發出一種悠然自得的氣質。除此之外，演出中特別改編了鄭雨賢老師的名著〈望春風〉，這首富有台灣風情的經典曲目，在爵士的編曲下，更顯得浪漫與獨特，彷彿將日內瓦湖的柔波與台灣的民謠融合在一起。並希望在這片美麗的土地上與觀眾共同分享他們的音樂旅程。', `organizer`='爵式 WiJazz Records', `address`='高雄市鹽埕區17鄰真愛路1號', `start_date`='2025-05-25 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='高雄流行音樂中心', `latitude`=22.62424585, `longitude`=120.2842331, `ticket_price`='單人+600', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc626b3242b74a3b12d', '齒間畫藝-牙齒的美麗與哀愁', '本展「齒間畫藝-牙齒的美麗與哀愁」繪畫比賽入選作品展，係透過中華民國牙醫師公會全國聯合會精心策劃，讓牙齒特殊需求者藉由畫作描述對生活的種種體驗與情感表達，用繪畫的方式呈現他們的心情與故事。\r\n牙醫全聯會自109年舉辦第一屆特殊需求者主題繪畫比賽後，好評不斷，藉由繪畫方式，提升特殊需求者對藝術的興趣，一起發揮創意及豐沛藝術潛能。本比賽收到來自全國各地身障及老人福利機構、學校特教班等近700件作品參與，參賽者年齡從最小5歲到85歲長者皆有，他們透過畫筆，盡情揮灑對牙齒、牙醫的印象，及對美食的熱愛。', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-04-16 00:00:00', '2025-05-11 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='齒間畫藝-牙齒的美麗與哀愁', `description`='本展「齒間畫藝-牙齒的美麗與哀愁」繪畫比賽入選作品展，係透過中華民國牙醫師公會全國聯合會精心策劃，讓牙齒特殊需求者藉由畫作描述對生活的種種體驗與情感表達，用繪畫的方式呈現他們的心情與故事。\r\n牙醫全聯會自109年舉辦第一屆特殊需求者主題繪畫比賽後，好評不斷，藉由繪畫方式，提升特殊需求者對藝術的興趣，一起發揮創意及豐沛藝術潛能。本比賽收到來自全國各地身障及老人福利機構、學校特教班等近700件作品參與，參賽者年齡從最小5歲到85歲長者皆有，他們透過畫筆，盡情揮灑對牙齒、牙醫的印象，及對美食的熱愛。', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-04-16 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc626b3242b74a3b12e', '『五年』-Piaf黃碧桂油畫與多媒材作品展', '本展由過去近三十餘年擔任空服員的藝術家黃碧桂 (Piaf Huang) 所構思創作，共展出48件作品，其中包含多媒材作品12件。展覽英文副標Beauyiful Memories in 5 Years中的"Beauyiful "是結合beauty+you+I自創的新字，展現美好不是藝術的權利，是你我都可以擁有的。\r\n五年對每個人而言有著不同的意義，對一些人而言是成長的蛻變、有些人則是刻骨銘心的回憶;然而對於跨界的「空服員x藝術家」的Piaf黃碧桂而言，則是一場劇烈人生變化的時空標誌。五年內她由光鮮亮麗的空服飛行生活歷經疫情居家隔離，甚至最後她選擇放下生命中所熟悉的飛行工作轉身投入藝術創作之中。', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-04-16 00:00:00', '2025-05-11 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='『五年』-Piaf黃碧桂油畫與多媒材作品展', `description`='本展由過去近三十餘年擔任空服員的藝術家黃碧桂 (Piaf Huang) 所構思創作，共展出48件作品，其中包含多媒材作品12件。展覽英文副標Beauyiful Memories in 5 Years中的"Beauyiful "是結合beauty+you+I自創的新字，展現美好不是藝術的權利，是你我都可以擁有的。\r\n五年對每個人而言有著不同的意義，對一些人而言是成長的蛻變、有些人則是刻骨銘心的回憶;然而對於跨界的「空服員x藝術家」的Piaf黃碧桂而言，則是一場劇烈人生變化的時空標誌。五年內她由光鮮亮麗的空服飛行生活歷經疫情居家隔離，甚至最後她選擇放下生命中所熟悉的飛行工作轉身投入藝術創作之中。', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-04-16 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc626b3242b74a3b12f', '生活補丁 Life Patch 呂易倫 個展', '生活補丁 Life Patch\r\n呂易倫 個展\r\nLU, Yi-Lun Solo Exhibition\r\n展覽地點 │ 板橋435藝文特區 光復館\r\n展覽日期 │ 2025年4月12日 ( 六 ) - 4月27日 ( 日 )\r\n展覽時間 │ 平日9至17時、假日9至18時\r\n—————————\r\n本展覽以「生活補丁(Life Patch)」概念出發，透過攝影師在工作之外所捕捉的片刻，以幾年的時間拍攝的量體堆疊成可被理解、閱讀的龐大訊息。\r\n　\r\n每個人類個體存在著獨一無二的生活路徑，這些路徑穿越了許多由時間及空間所匯聚的特殊時刻，攝影師透過了機具以個人的觀點捕捉屬於個人審美品味的瞬間，並將這些帶有風味脈絡的影像重新編輯，在展場呈現。\r\n　\r\n觀眾在閱讀影像時，彷彿被牽往這些被安排好的敘事裡，以意識感受的方式重回該空間之路徑。\r\n　\r\n—————————\r\n呂易倫\r\n主要創作媒介以攝影做為主軸，以思考影像與對象物之間的延伸意義,讓攝影作為一種思考、辯證後的再生產方法。創作常切入具社會性的地誌空間，並召喚出那些被抹除或不可視的景觀與意義。\r\n　\r\n在拍攝完《左營計劃》後，近期則嘗試在擴延影像能給予的微細感知，嘗試以文字、語句、聲音甚至是抽象思維的加入,讓視覺之外的官能參與並拓展攝影多元的出路。\r\n　　\r\n曾舉辦個展「不執著於圖像 Image? Dosen＆#039;t Matter.,2022」、「Room Service From Padded Cell,2022」、「家政體_Family as Politics,2019」、「失敗作為現實與最終章(?)左營計劃2011-2016,2016」，並在2019年與林羿綺合著攝影書「在熱帶,」出版。\r\n　\r\n同時也參與多項國內外策劃展及駐村計劃;曾獲2022臺北美術獎優選、2017與2018年連續榮獲全國美術展攝影類金牌獎、2015台南新藝獎首獎以及2012高雄獎入選等殊榮。', '新北市政府文化局', '新北市板橋區中正路435號', '2025-04-12 00:00:00', '2025-04-27 00:00:00', '435藝文特區', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='生活補丁 Life Patch 呂易倫 個展', `description`='生活補丁 Life Patch\r\n呂易倫 個展\r\nLU, Yi-Lun Solo Exhibition\r\n展覽地點 │ 板橋435藝文特區 光復館\r\n展覽日期 │ 2025年4月12日 ( 六 ) - 4月27日 ( 日 )\r\n展覽時間 │ 平日9至17時、假日9至18時\r\n—————————\r\n本展覽以「生活補丁(Life Patch)」概念出發，透過攝影師在工作之外所捕捉的片刻，以幾年的時間拍攝的量體堆疊成可被理解、閱讀的龐大訊息。\r\n　\r\n每個人類個體存在著獨一無二的生活路徑，這些路徑穿越了許多由時間及空間所匯聚的特殊時刻，攝影師透過了機具以個人的觀點捕捉屬於個人審美品味的瞬間，並將這些帶有風味脈絡的影像重新編輯，在展場呈現。\r\n　\r\n觀眾在閱讀影像時，彷彿被牽往這些被安排好的敘事裡，以意識感受的方式重回該空間之路徑。\r\n　\r\n—————————\r\n呂易倫\r\n主要創作媒介以攝影做為主軸，以思考影像與對象物之間的延伸意義,讓攝影作為一種思考、辯證後的再生產方法。創作常切入具社會性的地誌空間，並召喚出那些被抹除或不可視的景觀與意義。\r\n　\r\n在拍攝完《左營計劃》後，近期則嘗試在擴延影像能給予的微細感知，嘗試以文字、語句、聲音甚至是抽象思維的加入,讓視覺之外的官能參與並拓展攝影多元的出路。\r\n　　\r\n曾舉辦個展「不執著於圖像 Image? Dosen＆#039;t Matter.,2022」、「Room Service From Padded Cell,2022」、「家政體_Family as Politics,2019」、「失敗作為現實與最終章(?)左營計劃2011-2016,2016」，並在2019年與林羿綺合著攝影書「在熱帶,」出版。\r\n　\r\n同時也參與多項國內外策劃展及駐村計劃;曾獲2022臺北美術獎優選、2017與2018年連續榮獲全國美術展攝影類金牌獎、2015台南新藝獎首獎以及2012高雄獎入選等殊榮。', `organizer`='新北市政府文化局', `address`='新北市板橋區中正路435號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='435藝文特區', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc626b3242b74a3b130', '「彩游墨意」林明耀、陳又華雙人展', '   本次展覽邀請現代國畫畫家林明耀與油畫家陳又華，透過水墨的流動與油彩的厚實，共同譜寫跨媒材、跨文化的藝術對話。林明耀擅長以傳統水墨技法結合當代視角，其筆觸靈動且充滿詩意，作品既保有中國畫的韻味，又展現現代精神，讓觀者在層層墨韻中感受時間與情感的流動。陳又華則以油畫為表現媒介，透過豐富的色彩與筆觸描繪內在情感與抽象空間，作品兼具力量與細膩，層次分明，展現油彩的厚度及光影變化，為畫面增添張力與深度。\r\n   這場聯展不僅是兩位藝術家創作成果的展示，更是一次東西方繪畫語彙的交融與碰撞。水墨的留白與油彩的厚塗、東方的意境與西方的色彩，將在同一展覽空間中產生對話，帶領觀眾進入視覺與心靈的探索之旅。\r\n誠摯邀請各界藝術愛好者與朋友們蒞臨新港社地方文化館，共同欣賞這場充滿藝術魅力的雙人展。\r\n', '國家科學及技術委員會南部科學園區管理局', '臺南市新市區道爺路3號', '2025-04-12 00:00:00', '2025-05-11 00:00:00', '臺南市新市區新港社地方文化館', 23.08319496, 120.2923941, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「彩游墨意」林明耀、陳又華雙人展', `description`='   本次展覽邀請現代國畫畫家林明耀與油畫家陳又華，透過水墨的流動與油彩的厚實，共同譜寫跨媒材、跨文化的藝術對話。林明耀擅長以傳統水墨技法結合當代視角，其筆觸靈動且充滿詩意，作品既保有中國畫的韻味，又展現現代精神，讓觀者在層層墨韻中感受時間與情感的流動。陳又華則以油畫為表現媒介，透過豐富的色彩與筆觸描繪內在情感與抽象空間，作品兼具力量與細膩，層次分明，展現油彩的厚度及光影變化，為畫面增添張力與深度。\r\n   這場聯展不僅是兩位藝術家創作成果的展示，更是一次東西方繪畫語彙的交融與碰撞。水墨的留白與油彩的厚塗、東方的意境與西方的色彩，將在同一展覽空間中產生對話，帶領觀眾進入視覺與心靈的探索之旅。\r\n誠摯邀請各界藝術愛好者與朋友們蒞臨新港社地方文化館，共同欣賞這場充滿藝術魅力的雙人展。\r\n', `organizer`='國家科學及技術委員會南部科學園區管理局', `address`='臺南市新市區道爺路3號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='臺南市新市區新港社地方文化館', `latitude`=23.08319496, `longitude`=120.2923941, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('67feadc626b3242b74a3b131', '太古踏舞團《太陽之舞》', '從黃昏到夜晚\r\n一場跨越時空的舞蹈之旅即將展開！\r\n🔥太陽之舞——#林秀偉 老師的經典舞作\r\n由吳采璘率領10位舞者，以身體訴說天地的故事𖡼𖤣𖥧\r\n以奔放原始之力與美，呈現出太陽的文明、文化記憶和生命儀式\r\n六十分鐘的舞作一氣呵成，從日出－歌頌童年、日正當中－戰舞激昂、日暮－紅土揚塵、日落－四面神夢及祭典－祈求平安，攜手共舞。\r\n在天地間感受生命的韻律與情感的流動', '屏東縣政府', '屏東縣東港鎮', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '東港鎮（屏東縣）=', 22.46265635, 120.4751333, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='太古踏舞團《太陽之舞》', `description`='從黃昏到夜晚\r\n一場跨越時空的舞蹈之旅即將展開！\r\n🔥太陽之舞——#林秀偉 老師的經典舞作\r\n由吳采璘率領10位舞者，以身體訴說天地的故事𖡼𖤣𖥧\r\n以奔放原始之力與美，呈現出太陽的文明、文化記憶和生命儀式\r\n六十分鐘的舞作一氣呵成，從日出－歌頌童年、日正當中－戰舞激昂、日暮－紅土揚塵、日落－四面神夢及祭典－祈求平安，攜手共舞。\r\n在天地間感受生命的韻律與情感的流動', `organizer`='屏東縣政府', `address`='屏東縣東港鎮', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='東港鎮（屏東縣）=', `latitude`=22.46265635, `longitude`=120.4751333, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
