INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a426b3242b74a3b17d', '台語主題書展', '因應國發會114年雙語合作案「2025世界閱讀日【讀想生活．玩轉世界】」系列活動。本館希望藉由辦理之『主題書展』，積極帶動地方閱讀風氣，使到館民眾進一步認識館藏資源，讓更多人了解學習本土語言的重要性，將這優質的語言文化推廣並傳承下去。', '高雄市立圖書館總館', '高雄市楠梓區17鄰藍昌路72號', '2025-05-01 00:00:00', '2025-05-31 00:00:00', '高雄市立圖書館右昌分館', 22.7152924, 120.2901717, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='台語主題書展', `description`='因應國發會114年雙語合作案「2025世界閱讀日【讀想生活．玩轉世界】」系列活動。本館希望藉由辦理之『主題書展』，積極帶動地方閱讀風氣，使到館民眾進一步認識館藏資源，讓更多人了解學習本土語言的重要性，將這優質的語言文化推廣並傳承下去。', `organizer`='高雄市立圖書館總館', `address`='高雄市楠梓區17鄰藍昌路72號', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-31 00:00:00', `location`='高雄市立圖書館右昌分館', `latitude`=22.7152924, `longitude`=120.2901717, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a426b3242b74a3b17e', '「永安藍圖揚海韻，繪本傳情啟綠航」繪本創作', '為深化王船祭這一富含信仰與文化意涵的傳統習俗，並推動其與環境教育之結合，特邀永安國小、崑山科技大學動畫指導教師、繪本文字與圖畫創作講師，共同研商繪本《石斑魚與王船的海洋冒險》創作方向。透過跨域合作，準確傳遞王船文化中祈福、送瘟與潔淨海洋的精神，並結合兒童視角與創意表達，形塑一部兼具文化傳承與教育意涵的圖文作品，作為在地海洋文化紮根的重要基石。', '高雄市立圖書館總館', '高雄市永安區005鄰永華路49號', '2025-04-19 00:00:00', '2025-06-28 00:00:00', '高雄市立圖書館永安分館', 22.8159848, 120.2244381, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「永安藍圖揚海韻，繪本傳情啟綠航」繪本創作', `description`='為深化王船祭這一富含信仰與文化意涵的傳統習俗，並推動其與環境教育之結合，特邀永安國小、崑山科技大學動畫指導教師、繪本文字與圖畫創作講師，共同研商繪本《石斑魚與王船的海洋冒險》創作方向。透過跨域合作，準確傳遞王船文化中祈福、送瘟與潔淨海洋的精神，並結合兒童視角與創意表達，形塑一部兼具文化傳承與教育意涵的圖文作品，作為在地海洋文化紮根的重要基石。', `organizer`='高雄市立圖書館總館', `address`='高雄市永安區005鄰永華路49號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-06-28 00:00:00', `location`='高雄市立圖書館永安分館', `latitude`=22.8159848, `longitude`=120.2244381, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a526b3242b74a3b17f', '0｜1-涂愷妍個展', '雪地之上，愷姸以攝影探尋存在與虛無的邊界，捕捉無和有交錯的靜謐瞬間。\r\n\r\n2024年2月，她在芬蘭駐村期間創作了全新攝影系列〈0／1〉，靈感來自芬蘭諺語 「Jumalan selän takana」（神的背後），意指荒涼的邊陲之地。此次展出的十五幅作品，運用豐富的白色空間與極簡線條，映現隱藏在荒涼中的贈禮，並融合存在主義的思考與本質主義的純粹性，通過黑白影像探索自然的靈性維度。\r\n涂愷姸（1986-）是一位攝影藝術家，擅長透過黑白描繪自然世界，以極簡視角捕捉心理影像。她的作品曾於多個國際展覽中展出，並獲得多項國際獎項。其原創作品 〈成道的石頭〉 獲拱門任務基金會（Arch Mission Foundation）典藏於 月球圖書館（ALAA），作為永久性的時間膠囊，存放於月球之上。\r\n', '花蓮縣政府', '花蓮縣花蓮市文復路六號', '2025-04-16 00:00:00', '2025-05-11 00:00:00', '花蓮縣文化局', 23.99700271, 121.6071463, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='0｜1-涂愷妍個展', `description`='雪地之上，愷姸以攝影探尋存在與虛無的邊界，捕捉無和有交錯的靜謐瞬間。\r\n\r\n2024年2月，她在芬蘭駐村期間創作了全新攝影系列〈0／1〉，靈感來自芬蘭諺語 「Jumalan selän takana」（神的背後），意指荒涼的邊陲之地。此次展出的十五幅作品，運用豐富的白色空間與極簡線條，映現隱藏在荒涼中的贈禮，並融合存在主義的思考與本質主義的純粹性，通過黑白影像探索自然的靈性維度。\r\n涂愷姸（1986-）是一位攝影藝術家，擅長透過黑白描繪自然世界，以極簡視角捕捉心理影像。她的作品曾於多個國際展覽中展出，並獲得多項國際獎項。其原創作品 〈成道的石頭〉 獲拱門任務基金會（Arch Mission Foundation）典藏於 月球圖書館（ALAA），作為永久性的時間膠囊，存放於月球之上。\r\n', `organizer`='花蓮縣政府', `address`='花蓮縣花蓮市文復路六號', `start_date`='2025-04-16 00:00:00', `end_date`='2025-05-11 00:00:00', `location`='花蓮縣文化局', `latitude`=23.99700271, `longitude`=121.6071463, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a526b3242b74a3b180', '陳國春八十書法回顧展', '「陳國春八十書法回顧展」，即起至5月6日於馬祖民俗文物館1樓特展室展出，現場展出陳國春先生數十年來精選近百幅書法作品，縣府文化處邀大家共賞翰墨風華，體悟書法藝術的無窮魅力。\r\n\r\n陳國春先生1945年生於福建長樂，生長於馬祖，自幼因母親重視書法習作，奠定了其對書法的熱愛與執著。他的書法啟蒙於台東普師科（今台東大學）姚梅影老師，就讀國立台灣師範大學國文系時，又師從宗孝忱、汪雨盦等書法大家，中年師事王愷和老師、唐伯度老師，悉心指導，博採眾長，日臻精進。他鍾情於北碑張玄之遒麗質樸，又仰慕顏真卿、米芾之健勁華美，從歷代書法名家中汲取養分，遂成自家風貌。\r\n\r\n此次特展從數百件書法精選近百幅佳作，呈現數十載臨池不輟的成果，呈現楷書、隸書、行書、古篆各字體，涵蓋聯幅、橫披、條屏、對聯等形式，內容精美、氣韻玄妙，不僅呈現筆墨技法，也承載文化底蘊。\r\n\r\n文化處將在4月22日下午2時舉辦開幕典禮，敬邀鄉親蒞臨參觀。', '連江縣政府文化處', '連江縣南竿鄉135號', '2025-04-16 00:00:00', '2025-05-06 00:00:00', '馬祖民俗文物館', 26.154321, 119.931128, '全票+40;優待票+20', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陳國春八十書法回顧展', `description`='「陳國春八十書法回顧展」，即起至5月6日於馬祖民俗文物館1樓特展室展出，現場展出陳國春先生數十年來精選近百幅書法作品，縣府文化處邀大家共賞翰墨風華，體悟書法藝術的無窮魅力。\r\n\r\n陳國春先生1945年生於福建長樂，生長於馬祖，自幼因母親重視書法習作，奠定了其對書法的熱愛與執著。他的書法啟蒙於台東普師科（今台東大學）姚梅影老師，就讀國立台灣師範大學國文系時，又師從宗孝忱、汪雨盦等書法大家，中年師事王愷和老師、唐伯度老師，悉心指導，博採眾長，日臻精進。他鍾情於北碑張玄之遒麗質樸，又仰慕顏真卿、米芾之健勁華美，從歷代書法名家中汲取養分，遂成自家風貌。\r\n\r\n此次特展從數百件書法精選近百幅佳作，呈現數十載臨池不輟的成果，呈現楷書、隸書、行書、古篆各字體，涵蓋聯幅、橫披、條屏、對聯等形式，內容精美、氣韻玄妙，不僅呈現筆墨技法，也承載文化底蘊。\r\n\r\n文化處將在4月22日下午2時舉辦開幕典禮，敬邀鄉親蒞臨參觀。', `organizer`='連江縣政府文化處', `address`='連江縣南竿鄉135號', `start_date`='2025-04-16 00:00:00', `end_date`='2025-05-06 00:00:00', `location`='馬祖民俗文物館', `latitude`=26.154321, `longitude`=119.931128, `ticket_price`='全票+40;優待票+20', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a526b3242b74a3b181', '2025南投縣客家桐花祭： 2025桐花祭-埔天桐慶迎客情', '這次的活動不只賞花這麼簡單，我們結合了在地文化、自然景觀，與超豐富的客家體驗內容，保證你玩到不想回家！\r\n活動亮點：\r\n伯公祭儀／體驗傳統信仰文化\r\n桐賞客音／聽見最動人的客家樂音演出\r\n桐遊市集／埔里在地好物一次帶回家\r\n百人牛汶水DIY／親手做最Q的客家點心\r\n桐食客菜／10道創意客家料理，美味爆表\r\n客庄闖關／大人小孩都玩翻\r\n活動當天還有限量超值優惠～10:30、12:00各發放100張【市集券100元】\r\n現場可直接消費，送完為止！', '南投縣埔里鎮公所', '南投縣埔里鎮', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '埔里鎮（南投縣）=', 23.97892591, 120.9625259, '無資料', 'https://www.facebook.com/nantouhakkh.2014TBF/?locale=zh_TW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025南投縣客家桐花祭： 2025桐花祭-埔天桐慶迎客情', `description`='這次的活動不只賞花這麼簡單，我們結合了在地文化、自然景觀，與超豐富的客家體驗內容，保證你玩到不想回家！\r\n活動亮點：\r\n伯公祭儀／體驗傳統信仰文化\r\n桐賞客音／聽見最動人的客家樂音演出\r\n桐遊市集／埔里在地好物一次帶回家\r\n百人牛汶水DIY／親手做最Q的客家點心\r\n桐食客菜／10道創意客家料理，美味爆表\r\n客庄闖關／大人小孩都玩翻\r\n活動當天還有限量超值優惠～10:30、12:00各發放100張【市集券100元】\r\n現場可直接消費，送完為止！', `organizer`='南投縣埔里鎮公所', `address`='南投縣埔里鎮', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='埔里鎮（南投縣）=', `latitude`=23.97892591, `longitude`=120.9625259, `ticket_price`='無資料', `source_url`='https://www.facebook.com/nantouhakkh.2014TBF/?locale=zh_TW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a526b3242b74a3b182', '2025南投縣客家桐花祭：2025桐花祭「埔天桐慶迎客情」～千茭百變—桐花小旅行', '費用：免費\r\n報名條件：\r\n報名條件：自114年1月1日起至4月18日，於埔里地區飯店、民宿住宿或於埔里鎮內各餐飲業者消費，憑發票累積滿500元，即可免費參加本次遊程體驗活動，限制40人參加，額滿為止。\r\n4／1(二)上午10:00開放報名\r\n報名網址：\r\n千茭百變—桐花小旅行\r\nhttps://forms.gle/GjQ1oKTb3UgF1Phb8', '南投縣埔里鎮公所', '南投縣埔里鎮', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '埔里鎮（南投縣）=', 23.97892591, 120.9625259, '無資料', 'https://www.facebook.com/nantouhakkh.2014TBF/?locale=zh_TW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025南投縣客家桐花祭：2025桐花祭「埔天桐慶迎客情」～千茭百變—桐花小旅行', `description`='費用：免費\r\n報名條件：\r\n報名條件：自114年1月1日起至4月18日，於埔里地區飯店、民宿住宿或於埔里鎮內各餐飲業者消費，憑發票累積滿500元，即可免費參加本次遊程體驗活動，限制40人參加，額滿為止。\r\n4／1(二)上午10:00開放報名\r\n報名網址：\r\n千茭百變—桐花小旅行\r\nhttps://forms.gle/GjQ1oKTb3UgF1Phb8', `organizer`='南投縣埔里鎮公所', `address`='南投縣埔里鎮', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='埔里鎮（南投縣）=', `latitude`=23.97892591, `longitude`=120.9625259, `ticket_price`='無資料', `source_url`='https://www.facebook.com/nantouhakkh.2014TBF/?locale=zh_TW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a526b3242b74a3b183', '2025南投縣客家桐花祭：2025好客國姓~HAKKA桐花小旅行', '2025桐花祭～「好客國姓~HAKKA桐花小旅行」引領遊客出發前進好山、好水、好客的國姓鄉，共下走入本鄉北港村山林欣賞桐花之美，讓遊客細細品嚐客家米食饗宴；除了漫步桐花步道，與本鄉在地客語導覽老師介紹國姓歷史及人文小故事，一起感受多元的客家文化及在地生活體驗。\r\n活動免費，3/24(一)上午10:00開放報名，額滿為止。\r\n報名網址：\r\n    第1梯次 https://reurl.cc/mx9N5A\r\n    第2梯次 https://reurl.cc/yRglVy\r\n    第3梯次 https://reurl.cc/qG83eR\r\n聯絡資訊：國姓鄉公所 洪小姐 (049)2724218#14', '南投縣國姓鄉公所', '南投縣國姓鄉', '2025-04-12 00:00:00', '2025-04-26 00:00:00', '國姓鄉（南投縣）=', 24.03135413, 120.8676052, '無資料', 'https://www.facebook.com/nantouhakkh.2014TBF/?locale=zh_TW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025南投縣客家桐花祭：2025好客國姓~HAKKA桐花小旅行', `description`='2025桐花祭～「好客國姓~HAKKA桐花小旅行」引領遊客出發前進好山、好水、好客的國姓鄉，共下走入本鄉北港村山林欣賞桐花之美，讓遊客細細品嚐客家米食饗宴；除了漫步桐花步道，與本鄉在地客語導覽老師介紹國姓歷史及人文小故事，一起感受多元的客家文化及在地生活體驗。\r\n活動免費，3/24(一)上午10:00開放報名，額滿為止。\r\n報名網址：\r\n    第1梯次 https://reurl.cc/mx9N5A\r\n    第2梯次 https://reurl.cc/yRglVy\r\n    第3梯次 https://reurl.cc/qG83eR\r\n聯絡資訊：國姓鄉公所 洪小姐 (049)2724218#14', `organizer`='南投縣國姓鄉公所', `address`='南投縣國姓鄉', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='國姓鄉（南投縣）=', `latitude`=24.03135413, `longitude`=120.8676052, `ticket_price`='無資料', `source_url`='https://www.facebook.com/nantouhakkh.2014TBF/?locale=zh_TW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a526b3242b74a3b186', '樂舞飛揚岡中情', '2025年岡山國中學生藝文、體育聯合展演「樂舞飛揚，岡中情」，演出節目有民俗舞、現代舞、古典舞、鋼琴獨奏、雙人歌唱、管樂隊、體育班跆拳道、體操隊表演等，展現學生們學習成果。\r\n\r\n\r\n', '高雄市政府文化局', '高雄市岡山區009鄰岡山南路42號', '2025-05-22 00:00:00', '2025-05-22 00:00:00', '高雄市政府文化局﹝岡山文化中心﹞', 22.7832758, 120.2982709, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='樂舞飛揚岡中情', `description`='2025年岡山國中學生藝文、體育聯合展演「樂舞飛揚，岡中情」，演出節目有民俗舞、現代舞、古典舞、鋼琴獨奏、雙人歌唱、管樂隊、體育班跆拳道、體操隊表演等，展現學生們學習成果。\r\n\r\n\r\n', `organizer`='高雄市政府文化局', `address`='高雄市岡山區009鄰岡山南路42號', `start_date`='2025-05-22 00:00:00', `end_date`='2025-05-22 00:00:00', `location`='高雄市政府文化局﹝岡山文化中心﹞', `latitude`=22.7832758, `longitude`=120.2982709, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
