INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a526b3242b74a3b18d', '2025南投縣客家桐花祭：2025魚池桐花趣—花現魚池 桐樂蓮華池桐花小旅行', '油桐花過去是客家人最傳統卻已式微的經濟作物，每當四、五月春夏時節，可以欣賞油桐花滿山遍布的雪白美景。魚池鄉五城村是魚池鄉面積最大、人口數最少的一村，其中居民以客籍居多，使得五城村充滿濃濃的客家風貌。\r\n恰逢客家委員會及南投縣政府舉辦「2025桐花祭」活動時期，本所延伸辦理桐花祭及桐花小旅行系列活動，結合生態、產業資源，與在地居民、外地遊客一同共襄盛舉。\r\n費用：免費\r\n聯絡資訊：魚池鄉公所 王小姐 (049)2895371#27', '南投縣魚池鄉公所', '南投縣魚池鄉', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '魚池鄉（南投縣）=', 23.87601213, 120.9256736, '無資料', 'https://www.facebook.com/nantouhakkh.2014TBF/?locale=zh_TW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025南投縣客家桐花祭：2025魚池桐花趣—花現魚池 桐樂蓮華池桐花小旅行', `description`='油桐花過去是客家人最傳統卻已式微的經濟作物，每當四、五月春夏時節，可以欣賞油桐花滿山遍布的雪白美景。魚池鄉五城村是魚池鄉面積最大、人口數最少的一村，其中居民以客籍居多，使得五城村充滿濃濃的客家風貌。\r\n恰逢客家委員會及南投縣政府舉辦「2025桐花祭」活動時期，本所延伸辦理桐花祭及桐花小旅行系列活動，結合生態、產業資源，與在地居民、外地遊客一同共襄盛舉。\r\n費用：免費\r\n聯絡資訊：魚池鄉公所 王小姐 (049)2895371#27', `organizer`='南投縣魚池鄉公所', `address`='南投縣魚池鄉', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='魚池鄉（南投縣）=', `latitude`=23.87601213, `longitude`=120.9256736, `ticket_price`='無資料', `source_url`='https://www.facebook.com/nantouhakkh.2014TBF/?locale=zh_TW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a526b3242b74a3b18e', '2025南投縣客家桐花祭：2025綻放的名間～桐遊松柏嶺', '活動內容：一桐跳舞、桐聲嗨唱、彩繪桐砂畫、桐作粢粑。\r\n現場發放兌領號碼牌：\r\n桐作粢粑(麻糬)DIY體驗，一般大眾皆可參加。限量200份，兌完即止。\r\n彩繪桐砂畫DIY體驗，國中小以下優先領取，限量100份，兌完即止。\r\n聯絡資訊：名間鄉公所 姚小姐 (049)2732116#270', '南投縣名間鄉公所', '南投縣名間鄉', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '名間鄉（南投縣）=', 23.8510771, 120.6774402, '無資料', 'https://www.facebook.com/nantouhakkh.2014TBF/?locale=zh_TW', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025南投縣客家桐花祭：2025綻放的名間～桐遊松柏嶺', `description`='活動內容：一桐跳舞、桐聲嗨唱、彩繪桐砂畫、桐作粢粑。\r\n現場發放兌領號碼牌：\r\n桐作粢粑(麻糬)DIY體驗，一般大眾皆可參加。限量200份，兌完即止。\r\n彩繪桐砂畫DIY體驗，國中小以下優先領取，限量100份，兌完即止。\r\n聯絡資訊：名間鄉公所 姚小姐 (049)2732116#270', `organizer`='南投縣名間鄉公所', `address`='南投縣名間鄉', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='名間鄉（南投縣）=', `latitude`=23.8510771, `longitude`=120.6774402, `ticket_price`='無資料', `source_url`='https://www.facebook.com/nantouhakkh.2014TBF/?locale=zh_TW', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a526b3242b74a3b18f', '穿樂時光音樂會', '這場音樂會，大人小孩都玩瘋了！\r\n社區演奏 × 草地音樂會 × 超放電親子互動\r\n邀你一起來【穿樂時光音樂會】，聽在地社區與專業樂手聯合演出，還能讓小朋友在草地上吹泡泡、做金縷樹藝DIY，現場野餐滿滿音樂、歡笑、和最棒的社區活力！\r\n活動免費參加，適合親子闔家。\r\n\r\n演出舞台（埔里藝文中心戶外廣場）\r\n3:00-3:20 政令宣導，長官致詞\r\n3:20-3:40 枇杷森巴鼓\r\n3:40-4:00 枇杷空靈鼓\r\n4:00-4:20 吹笛手家族＋響笛樂團\r\n4:20-4:40 台灣超人紀芃逢\r\n4:40-5:00 法莫爾木笛合奏團\r\n5:00-5:20 甜蕃薯陶笛\r\n5:20-6:00 古典室內樂集\r\n詳細活動資訊 https://flutesfamily.com/穿樂時光/', '吹笛手家族', '南投縣埔里鎮中華路239號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '南投縣埔里藝文中心', 23.9719221, 120.9713138, '無資料', 'https://www.facebook.com/pulilibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='穿樂時光音樂會', `description`='這場音樂會，大人小孩都玩瘋了！\r\n社區演奏 × 草地音樂會 × 超放電親子互動\r\n邀你一起來【穿樂時光音樂會】，聽在地社區與專業樂手聯合演出，還能讓小朋友在草地上吹泡泡、做金縷樹藝DIY，現場野餐滿滿音樂、歡笑、和最棒的社區活力！\r\n活動免費參加，適合親子闔家。\r\n\r\n演出舞台（埔里藝文中心戶外廣場）\r\n3:00-3:20 政令宣導，長官致詞\r\n3:20-3:40 枇杷森巴鼓\r\n3:40-4:00 枇杷空靈鼓\r\n4:00-4:20 吹笛手家族＋響笛樂團\r\n4:20-4:40 台灣超人紀芃逢\r\n4:40-5:00 法莫爾木笛合奏團\r\n5:00-5:20 甜蕃薯陶笛\r\n5:20-6:00 古典室內樂集\r\n詳細活動資訊 https://flutesfamily.com/穿樂時光/', `organizer`='吹笛手家族', `address`='南投縣埔里鎮中華路239號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='南投縣埔里藝文中心', `latitude`=23.9719221, `longitude`=120.9713138, `ticket_price`='無資料', `source_url`='https://www.facebook.com/pulilibrary', `image_url`='[]';
