INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a526b3242b74a3b191', '埔里鎮立圖書館114年SDGs聯合國永續目標閱讀推廣：繪本導讀《世界孩子上學去》＆DIY活動（一新社區導覽+茭白筍泡菜製作）', '4月SDGs4優質教育繪本導讀&DIY活動\r\n活動內容：繪本導讀《世界孩子上學去》/DIY活動：一新社區導覽+茭白筍泡菜製作\r\n報名對象：限小一以上兒童參加，每場限20組，額滿為止。\r\n報名資格：單次借閱30本書(限用兒童卡)，即可至圖書館一樓櫃台報名。\r\n報名方式：即日起額滿為止。\r\n報名費用：免費。', '南投縣埔里鎮公所', '南投縣埔里鎮', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '埔里鎮（南投縣）=', 23.97892591, 120.9625259, '無資料', 'https://www.facebook.com/pulilibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='埔里鎮立圖書館114年SDGs聯合國永續目標閱讀推廣：繪本導讀《世界孩子上學去》＆DIY活動（一新社區導覽+茭白筍泡菜製作）', `description`='4月SDGs4優質教育繪本導讀&DIY活動\r\n活動內容：繪本導讀《世界孩子上學去》/DIY活動：一新社區導覽+茭白筍泡菜製作\r\n報名對象：限小一以上兒童參加，每場限20組，額滿為止。\r\n報名資格：單次借閱30本書(限用兒童卡)，即可至圖書館一樓櫃台報名。\r\n報名方式：即日起額滿為止。\r\n報名費用：免費。', `organizer`='南投縣埔里鎮公所', `address`='南投縣埔里鎮', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='埔里鎮（南投縣）=', `latitude`=23.97892591, `longitude`=120.9625259, `ticket_price`='無資料', `source_url`='https://www.facebook.com/pulilibrary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b192', 'KSAF歌劇《弄臣》/  Giuseppe Verdi：Rigoletto', '威爾第首部成名作 × 一齣關於善惡、愛恨與復仇的交響\r\n改編自雨果戲劇《國王的弄臣》，曾因題材過於寫實面臨禁演危機，如今成為歷久不衰的歌劇經典。\r\n一場如鬧劇般的時代悲劇，帶你深入探討善與惡、愛與恨、命運與復仇。\r\n故事主角里戈萊托（Rigoletto），一位身心皆有殘缺，在風流公爵的以嘲弄諷刺為生的弄臣，卻一心守護著自己純真的女兒吉爾達（Gilda）。當女兒慘遭公爵欺騙、失去貞潔，痛苦不堪的里戈萊托決定展開復仇…\r\n🎭張力十足的劇情 × 音樂史上最動人的旋律♬\r\n從《善變的女人》、《可愛的名字》，到四重唱《美麗的愛之女》，情感與旋律交織出一部扣人心弦的現實悲劇。\r\n6月20日（五）、22日（日）高雄衛武營歌劇院全版上演，與你相約《弄臣》的愛與怒吼。', '高雄市政府文化局', '高雄市鳳山區高雄市鳳山區三多一路 1 號', '2025-06-20 00:00:00', '2025-06-22 00:00:00', '衛武營國家藝術文化中心', 22.61379251, 120.3554359, '--+600;--+1000;--+1400;--+1800;--+2200;--+2600;--+3000;--+3400;--+3800', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='KSAF歌劇《弄臣》/  Giuseppe Verdi：Rigoletto', `description`='威爾第首部成名作 × 一齣關於善惡、愛恨與復仇的交響\r\n改編自雨果戲劇《國王的弄臣》，曾因題材過於寫實面臨禁演危機，如今成為歷久不衰的歌劇經典。\r\n一場如鬧劇般的時代悲劇，帶你深入探討善與惡、愛與恨、命運與復仇。\r\n故事主角里戈萊托（Rigoletto），一位身心皆有殘缺，在風流公爵的以嘲弄諷刺為生的弄臣，卻一心守護著自己純真的女兒吉爾達（Gilda）。當女兒慘遭公爵欺騙、失去貞潔，痛苦不堪的里戈萊托決定展開復仇…\r\n🎭張力十足的劇情 × 音樂史上最動人的旋律♬\r\n從《善變的女人》、《可愛的名字》，到四重唱《美麗的愛之女》，情感與旋律交織出一部扣人心弦的現實悲劇。\r\n6月20日（五）、22日（日）高雄衛武營歌劇院全版上演，與你相約《弄臣》的愛與怒吼。', `organizer`='高雄市政府文化局', `address`='高雄市鳳山區高雄市鳳山區三多一路 1 號', `start_date`='2025-06-20 00:00:00', `end_date`='2025-06-22 00:00:00', `location`='衛武營國家藝術文化中心', `latitude`=22.61379251, `longitude`=120.3554359, `ticket_price`='--+600;--+1000;--+1400;--+1800;--+2200;--+2600;--+3000;--+3400;--+3800', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b193', '世界地球日  主題書展', '為響應世界地球日 & 2025 埔里福興悠遊樂騎─世界地球日活動，特別規劃主體書展，邀請民眾一起來從書籍中學習如何愛護地球、節能減碳的重要性，讓我們一起來守護地球，從生活中做起。\r\n綠行動闖關卡--闖關卡可於本館1樓櫃檯領取，凡完成自主綠行動三選二，可於4/19活動當天兌換1顆樹苗或1張氣墊樂園入場券。4/19活動當日再參加綠行動集點，可以再兌換限量好禮。洽詢電話：049-2984144轉40。\r\n\r\n2025 埔里福興悠遊樂騎─世界地球日活動\r\n日期：4月19日(六)09:30-15:30\r\n地點：福興溫泉親子公園\r\n主辦單位：南投縣政府', '南投縣埔里鎮公所', '南投縣埔里鎮六合路178號', '2025-04-09 00:00:00', '2025-04-30 00:00:00', '南投縣埔里鎮立圖書館', 23.9702357, 120.9713659, '無資料', 'https://www.facebook.com/pulilibrary', '[]') ON DUPLICATE KEY UPDATE `activity_name`='世界地球日  主題書展', `description`='為響應世界地球日 & 2025 埔里福興悠遊樂騎─世界地球日活動，特別規劃主體書展，邀請民眾一起來從書籍中學習如何愛護地球、節能減碳的重要性，讓我們一起來守護地球，從生活中做起。\r\n綠行動闖關卡--闖關卡可於本館1樓櫃檯領取，凡完成自主綠行動三選二，可於4/19活動當天兌換1顆樹苗或1張氣墊樂園入場券。4/19活動當日再參加綠行動集點，可以再兌換限量好禮。洽詢電話：049-2984144轉40。\r\n\r\n2025 埔里福興悠遊樂騎─世界地球日活動\r\n日期：4月19日(六)09:30-15:30\r\n地點：福興溫泉親子公園\r\n主辦單位：南投縣政府', `organizer`='南投縣埔里鎮公所', `address`='南投縣埔里鎮六合路178號', `start_date`='2025-04-09 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='南投縣埔里鎮立圖書館', `latitude`=23.9702357, `longitude`=120.9713659, `ticket_price`='無資料', `source_url`='https://www.facebook.com/pulilibrary', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b194', '2025創新書市-魅力語言伸展台：表演區-世界故事分享（越語、德語、台語各一場）', '2025年，籃城書房以語言特色作為書市集核心主題，號召書店與出版同業，當然還有你你我我的各位讀者們，來探索語言建構起來的世界，感受閱讀的魅力。\r\n市集現場搭配著此主題，安排4場專題演講、4場繪本說故事＆闖關遊戲，還有南投縣的4家國小參與，讓現場觀眾欣賞多語言的音樂表演！\r\n而書市集的核心精神，就是讓大眾用短短時間認識推廣閱讀的獨立書店們，感受書店與閱讀的魅力！\r\n歡迎來認識各位書店的選書，和認識各魅力攤位帶來的好吃、好玩、好用的各種神奇內容，並用新台幣支持各位店家。主辦單位籃城書房也加碼，只要在市集現場的書攤消費滿300元，就可以獲得市集抵用券50元，抵用在各攤位！ ', '籃城書房', '南投縣埔里鎮中華路239號', '2025-04-26 00:00:00', '2025-04-27 00:00:00', '南投縣埔里藝文中心', 23.9719221, 120.9713138, '無資料', 'https://readtaiwan.moc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025創新書市-魅力語言伸展台：表演區-世界故事分享（越語、德語、台語各一場）', `description`='2025年，籃城書房以語言特色作為書市集核心主題，號召書店與出版同業，當然還有你你我我的各位讀者們，來探索語言建構起來的世界，感受閱讀的魅力。\r\n市集現場搭配著此主題，安排4場專題演講、4場繪本說故事＆闖關遊戲，還有南投縣的4家國小參與，讓現場觀眾欣賞多語言的音樂表演！\r\n而書市集的核心精神，就是讓大眾用短短時間認識推廣閱讀的獨立書店們，感受書店與閱讀的魅力！\r\n歡迎來認識各位書店的選書，和認識各魅力攤位帶來的好吃、好玩、好用的各種神奇內容，並用新台幣支持各位店家。主辦單位籃城書房也加碼，只要在市集現場的書攤消費滿300元，就可以獲得市集抵用券50元，抵用在各攤位！ ', `organizer`='籃城書房', `address`='南投縣埔里鎮中華路239號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='南投縣埔里藝文中心', `latitude`=23.9719221, `longitude`=120.9713138, `ticket_price`='無資料', `source_url`='https://readtaiwan.moc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b195', '2025創新書市-魅力語言伸展台：表演區-繪本分享（2場次）', '講題、主講人： \r\n4月26日12:00-13:00\r\n主題：〔老師想起來了〕繪本分享\r\n主講人：Power教師潘如玲\r\n4月27日12:00-13:00\r\n主題：蜈蚣崙，「蚣」故事\r\n主講人講者：〔家在蜈蚣崙〕繪本作者全麥麵＆蘇彙伶\r\n〔家在蜈蚣崙〕繪本，一本關於噶哈巫民族植物及狩獵文化的繪本。\r\n\r\n2025年，籃城書房以語言特色作為書市集核心主題，號召書店與出版同業，當然還有你你我我的各位讀者們，來探索語言建構起來的世界，感受閱讀的魅力。\r\n市集現場搭配著此主題，安排4場專題演講、4場繪本說故事＆闖關遊戲，還有南投縣的4家國小參與，讓現場觀眾欣賞多語言的音樂表演！\r\n而書市集的核心精神，就是讓大眾用短短時間認識推廣閱讀的獨立書店們，感受書店與閱讀的魅力！\r\n歡迎來認識各位書店的選書，和認識各魅力攤位帶來的好吃、好玩、好用的各種神奇內容，並用新台幣支持各位店家。主辦單位籃城書房也加碼，只要在市集現場的書攤消費滿300元，就可以獲得市集抵用券50元，抵用在各攤位！ ', '籃城書房', '南投縣埔里鎮中華路239號', '2025-04-26 00:00:00', '2025-04-27 00:00:00', '南投縣埔里藝文中心', 23.9719221, 120.9713138, '無資料', 'https://readtaiwan.moc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025創新書市-魅力語言伸展台：表演區-繪本分享（2場次）', `description`='講題、主講人： \r\n4月26日12:00-13:00\r\n主題：〔老師想起來了〕繪本分享\r\n主講人：Power教師潘如玲\r\n4月27日12:00-13:00\r\n主題：蜈蚣崙，「蚣」故事\r\n主講人講者：〔家在蜈蚣崙〕繪本作者全麥麵＆蘇彙伶\r\n〔家在蜈蚣崙〕繪本，一本關於噶哈巫民族植物及狩獵文化的繪本。\r\n\r\n2025年，籃城書房以語言特色作為書市集核心主題，號召書店與出版同業，當然還有你你我我的各位讀者們，來探索語言建構起來的世界，感受閱讀的魅力。\r\n市集現場搭配著此主題，安排4場專題演講、4場繪本說故事＆闖關遊戲，還有南投縣的4家國小參與，讓現場觀眾欣賞多語言的音樂表演！\r\n而書市集的核心精神，就是讓大眾用短短時間認識推廣閱讀的獨立書店們，感受書店與閱讀的魅力！\r\n歡迎來認識各位書店的選書，和認識各魅力攤位帶來的好吃、好玩、好用的各種神奇內容，並用新台幣支持各位店家。主辦單位籃城書房也加碼，只要在市集現場的書攤消費滿300元，就可以獲得市集抵用券50元，抵用在各攤位！ ', `organizer`='籃城書房', `address`='南投縣埔里鎮中華路239號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='南投縣埔里藝文中心', `latitude`=23.9719221, `longitude`=120.9713138, `ticket_price`='無資料', `source_url`='https://readtaiwan.moc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b196', '2025創新書市-魅力語言伸展台：表演區-賽德克歌謠、英語戲劇與才藝表演', '多元展演，聲聲動聽\r\n在魅力語言伸展台，我們邀請大家一起前來藝文中心感受文化的韻律！\r\n來自仁愛鄉都達國小的師生，將以賽德克語歌謠傳遞原住民語的動人力量；桃源國小學生帶來英語歌謠與才藝演出，活力展現雙語學習的精彩成果！歡迎共襄盛舉，一起聽見語言的美！\r\n\r\n2025年，籃城書房以語言特色作為書市集核心主題，號召書店與出版同業，當然還有你你我我的各位讀者們，來探索語言建構起來的世界，感受閱讀的魅力。\r\n市集現場搭配著此主題，安排4場專題演講、4場繪本說故事＆闖關遊戲，還有南投縣的4家國小參與，讓現場觀眾欣賞多語言的音樂表演！\r\n而書市集的核心精神，就是讓大眾用短短時間認識推廣閱讀的獨立書店們，感受書店與閱讀的魅力！\r\n歡迎來認識各位書店的選書，和認識各魅力攤位帶來的好吃、好玩、好用的各種神奇內容，並用新台幣支持各位店家。主辦單位籃城書房也加碼，只要在市集現場的書攤消費滿300元，就可以獲得市集抵用券50元，抵用在各攤位！ ', '籃城書房', '南投縣埔里鎮中華路239號', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '南投縣埔里藝文中心', 23.9719221, 120.9713138, '無資料', 'https://readtaiwan.moc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025創新書市-魅力語言伸展台：表演區-賽德克歌謠、英語戲劇與才藝表演', `description`='多元展演，聲聲動聽\r\n在魅力語言伸展台，我們邀請大家一起前來藝文中心感受文化的韻律！\r\n來自仁愛鄉都達國小的師生，將以賽德克語歌謠傳遞原住民語的動人力量；桃源國小學生帶來英語歌謠與才藝演出，活力展現雙語學習的精彩成果！歡迎共襄盛舉，一起聽見語言的美！\r\n\r\n2025年，籃城書房以語言特色作為書市集核心主題，號召書店與出版同業，當然還有你你我我的各位讀者們，來探索語言建構起來的世界，感受閱讀的魅力。\r\n市集現場搭配著此主題，安排4場專題演講、4場繪本說故事＆闖關遊戲，還有南投縣的4家國小參與，讓現場觀眾欣賞多語言的音樂表演！\r\n而書市集的核心精神，就是讓大眾用短短時間認識推廣閱讀的獨立書店們，感受書店與閱讀的魅力！\r\n歡迎來認識各位書店的選書，和認識各魅力攤位帶來的好吃、好玩、好用的各種神奇內容，並用新台幣支持各位店家。主辦單位籃城書房也加碼，只要在市集現場的書攤消費滿300元，就可以獲得市集抵用券50元，抵用在各攤位！ ', `organizer`='籃城書房', `address`='南投縣埔里鎮中華路239號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='南投縣埔里藝文中心', `latitude`=23.9719221, `longitude`=120.9713138, `ticket_price`='無資料', `source_url`='https://readtaiwan.moc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b197', '2025創新書市-魅力語言伸展台：表演區-巴宰歌謠、英語戲劇與才藝表演', '多元展演，聲聲動聽\r\n在魅力語言伸展台，我們邀請大家一起前來藝文中心感受文化的韻律！\r\n來自埔里鎮愛蘭國小的小朋友們，則用歌聲喚起巴宰族的文化記憶；太平國小學生帶來英語歌謠與才藝演出，活力展現雙語學習的精彩成果！歡迎共襄盛舉，一起聽見語言的美！\r\n\r\n2025年，籃城書房以語言特色作為書市集核心主題，號召書店與出版同業，當然還有你你我我的各位讀者們，來探索語言建構起來的世界，感受閱讀的魅力。\r\n市集現場搭配著此主題，安排4場專題演講、4場繪本說故事＆闖關遊戲，還有南投縣的4家國小參與，讓現場觀眾欣賞多語言的音樂表演！\r\n而書市集的核心精神，就是讓大眾用短短時間認識推廣閱讀的獨立書店們，感受書店與閱讀的魅力！\r\n歡迎來認識各位書店的選書，和認識各魅力攤位帶來的好吃、好玩、好用的各種神奇內容，並用新台幣支持各位店家。主辦單位籃城書房也加碼，只要在市集現場的書攤消費滿300元，就可以獲得市集抵用券50元，抵用在各攤位！ ', '籃城書房', '南投縣埔里鎮中華路239號', '2025-04-27 00:00:00', '2025-04-27 00:00:00', '南投縣埔里藝文中心', 23.9719221, 120.9713138, '無資料', 'https://readtaiwan.moc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025創新書市-魅力語言伸展台：表演區-巴宰歌謠、英語戲劇與才藝表演', `description`='多元展演，聲聲動聽\r\n在魅力語言伸展台，我們邀請大家一起前來藝文中心感受文化的韻律！\r\n來自埔里鎮愛蘭國小的小朋友們，則用歌聲喚起巴宰族的文化記憶；太平國小學生帶來英語歌謠與才藝演出，活力展現雙語學習的精彩成果！歡迎共襄盛舉，一起聽見語言的美！\r\n\r\n2025年，籃城書房以語言特色作為書市集核心主題，號召書店與出版同業，當然還有你你我我的各位讀者們，來探索語言建構起來的世界，感受閱讀的魅力。\r\n市集現場搭配著此主題，安排4場專題演講、4場繪本說故事＆闖關遊戲，還有南投縣的4家國小參與，讓現場觀眾欣賞多語言的音樂表演！\r\n而書市集的核心精神，就是讓大眾用短短時間認識推廣閱讀的獨立書店們，感受書店與閱讀的魅力！\r\n歡迎來認識各位書店的選書，和認識各魅力攤位帶來的好吃、好玩、好用的各種神奇內容，並用新台幣支持各位店家。主辦單位籃城書房也加碼，只要在市集現場的書攤消費滿300元，就可以獲得市集抵用券50元，抵用在各攤位！ ', `organizer`='籃城書房', `address`='南投縣埔里鎮中華路239號', `start_date`='2025-04-27 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='南投縣埔里藝文中心', `latitude`=23.9719221, `longitude`=120.9713138, `ticket_price`='無資料', `source_url`='https://readtaiwan.moc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b198', '府中15-KANO', '劇情簡介：\r\n嘉農野球隊成立之初，原本只是強身健體的社團，直到神秘的日本教練近藤兵太郎出現。近藤選才不分人種，綜合了日本人善防守、漢人打擊強、原住民跑得快的優勢及斯巴達式訓練，讓嘉農野球隊由一支從未贏過的球隊漸漸脫胎換骨，過關斬將打進日本甲子園。然而，來到夢想的頂端，真正的挑戰才正要開始。', '新北市政府文化局', '新北市板橋區府中路15號', '2025-03-02 00:00:00', '2025-04-27 00:00:00', '府中15', 25.01186453, 121.4579675, '票價+20', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='府中15-KANO', `description`='劇情簡介：\r\n嘉農野球隊成立之初，原本只是強身健體的社團，直到神秘的日本教練近藤兵太郎出現。近藤選才不分人種，綜合了日本人善防守、漢人打擊強、原住民跑得快的優勢及斯巴達式訓練，讓嘉農野球隊由一支從未贏過的球隊漸漸脫胎換骨，過關斬將打進日本甲子園。然而，來到夢想的頂端，真正的挑戰才正要開始。', `organizer`='新北市政府文化局', `address`='新北市板橋區府中路15號', `start_date`='2025-03-02 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='府中15', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='票價+20', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b199', '國姓國小附設幼兒園作品展-蕉遊國姓  附幼玩莓', '由國姓國小附幼主任及老師，帶領小朋友走訪並認識國姓農特產--草莓、香蕉、檳榔，師生們親手栽種並觀察草莓的生長，一起烘焙香蕉餅乾，手作農特產的微型世界並展出，讓我們一同來看看國姓附幼小朋友們的成果，歡迎大家蒞臨參觀。', '南投縣國姓鄉公所', '南投縣國姓鄉國姓路267號5樓', '2025-04-09 00:00:00', '2025-05-10 00:00:00', '南投縣國姓鄉立圖書館', 24.0399435, 120.8574913, '無資料', 'https://www.facebook.com/profile.php?id=100067317843686', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國姓國小附設幼兒園作品展-蕉遊國姓  附幼玩莓', `description`='由國姓國小附幼主任及老師，帶領小朋友走訪並認識國姓農特產--草莓、香蕉、檳榔，師生們親手栽種並觀察草莓的生長，一起烘焙香蕉餅乾，手作農特產的微型世界並展出，讓我們一同來看看國姓附幼小朋友們的成果，歡迎大家蒞臨參觀。', `organizer`='南投縣國姓鄉公所', `address`='南投縣國姓鄉國姓路267號5樓', `start_date`='2025-04-09 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='南投縣國姓鄉立圖書館', `latitude`=24.0399435, `longitude`=120.8574913, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100067317843686', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b19a', '府中15- 我這樣過了一生', '劇情簡介：\r\n影片描寫桂美從28歲到54歲病逝的坎坷人生。孤身來臺的她勤奮持家、撫養繼子女，卻遭遇嗜賭丈夫和親情冷漠的挑戰。遠赴日本幫傭時，她面臨撫養親生與繼子的艱難抉擇。即使罹癌，桂美仍堅韌以對，展現包容與善良，留下一段動人的生命故事。', '新北市政府文化局', '新北市板橋區府中路15號', '2025-03-08 00:00:00', '2025-04-18 00:00:00', '府中15', 25.01186453, 121.4579675, '票價+20', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='府中15- 我這樣過了一生', `description`='劇情簡介：\r\n影片描寫桂美從28歲到54歲病逝的坎坷人生。孤身來臺的她勤奮持家、撫養繼子女，卻遭遇嗜賭丈夫和親情冷漠的挑戰。遠赴日本幫傭時，她面臨撫養親生與繼子的艱難抉擇。即使罹癌，桂美仍堅韌以對，展現包容與善良，留下一段動人的生命故事。', `organizer`='新北市政府文化局', `address`='新北市板橋區府中路15號', `start_date`='2025-03-08 00:00:00', `end_date`='2025-04-18 00:00:00', `location`='府中15', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='票價+20', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b19b', '府中15- 達荷美：祖靈回家', '劇情簡介：\r\n去殖民化運動於現代興起，經過多年交涉後，法國終於同意在2021年將藏於巴黎布朗利河岸博物館的26件文物歸還貝南。導演迪歐普透過虛實交織的影像詩，讓死者與生者對話、文物神靈與物質世界互動，模糊生死與現實戲劇的界線，為這場解殖之旅注入深刻而多層次的省思。', '新北市政府文化局', '新北市板橋區府中路15號', '2025-03-15 00:00:00', '2025-04-30 00:00:00', '府中15', 25.01186453, 121.4579675, '票價+20', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='府中15- 達荷美：祖靈回家', `description`='劇情簡介：\r\n去殖民化運動於現代興起，經過多年交涉後，法國終於同意在2021年將藏於巴黎布朗利河岸博物館的26件文物歸還貝南。導演迪歐普透過虛實交織的影像詩，讓死者與生者對話、文物神靈與物質世界互動，模糊生死與現實戲劇的界線，為這場解殖之旅注入深刻而多層次的省思。', `organizer`='新北市政府文化局', `address`='新北市板橋區府中路15號', `start_date`='2025-03-15 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='府中15', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='票價+20', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b19c', '2025臺灣國際茶飲文化節', '現場有茶飲比賽、美食市集，還有棋藝競賽，快來報名，有高額獎金讓你帶回家。\r\n當日有歌手楊淨宇、IG網紅貓貓 …等現場帶來精彩演出！千萬別錯過。\r\n棋藝報名連結：https://www.beclass.com/rid=294fec467cbf88e0a1ef', '南投縣名間鄉公所', '南投縣名間鄉', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '名間鄉（南投縣）=', 23.8510771, 120.6774402, '無資料', 'https://www.facebook.com/profile.php?id=100064507040051', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025臺灣國際茶飲文化節', `description`='現場有茶飲比賽、美食市集，還有棋藝競賽，快來報名，有高額獎金讓你帶回家。\r\n當日有歌手楊淨宇、IG網紅貓貓 …等現場帶來精彩演出！千萬別錯過。\r\n棋藝報名連結：https://www.beclass.com/rid=294fec467cbf88e0a1ef', `organizer`='南投縣名間鄉公所', `address`='南投縣名間鄉', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='名間鄉（南投縣）=', `latitude`=23.8510771, `longitude`=120.6774402, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064507040051', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b19d', '名間鄉立圖書館假日電影院（114年4月）', '圖書館每週星期六下午2:00播放影片供大家欣賞，歡迎您全家前來圖書館欣賞影片。活動洽詢：049-2734848\r\n\r\n播放影片：\r\n04/05-海豚男孩\r\n04/12-公共圖書館員\r\n04/19-柿子色的街灯\r\n04/26-迷雁返家路\r\n電影級別：\r\n輔導級：未滿十五歲之人不宜觀賞。\r\n保護級：未滿六歲之兒童不宜觀賞，六歲以上未滿十二歲之兒童需父母、陪伴輔導觀賞。\r\n普遍級：一般觀眾皆可觀賞。', '南投縣名間鄉公所', '南投縣名間鄉彰南路42-2號三樓', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '南投縣名間鄉立圖書館', 23.8385841, 120.702733, '無資料', 'https://www.facebook.com/profile.php?id=100064507040051', '[]') ON DUPLICATE KEY UPDATE `activity_name`='名間鄉立圖書館假日電影院（114年4月）', `description`='圖書館每週星期六下午2:00播放影片供大家欣賞，歡迎您全家前來圖書館欣賞影片。活動洽詢：049-2734848\r\n\r\n播放影片：\r\n04/05-海豚男孩\r\n04/12-公共圖書館員\r\n04/19-柿子色的街灯\r\n04/26-迷雁返家路\r\n電影級別：\r\n輔導級：未滿十五歲之人不宜觀賞。\r\n保護級：未滿六歲之兒童不宜觀賞，六歲以上未滿十二歲之兒童需父母、陪伴輔導觀賞。\r\n普遍級：一般觀眾皆可觀賞。', `organizer`='南投縣名間鄉公所', `address`='南投縣名間鄉彰南路42-2號三樓', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='南投縣名間鄉立圖書館', `latitude`=23.8385841, `longitude`=120.702733, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064507040051', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b19e', '423世界閱讀日一小小館員體驗營', '4月23日是文豪莎士比亞及多位偉大作家辭世的日子，為紀念並推廣閱讀和寫作，聯合國教科文組織於1995年將該日定為「世界閱讀日」(World Book & Copyright Day)，旨在希望民眾享受閱讀書本的樂趣。\r\n為了響應世界閱讀日，南投縣政府文化局與13鄉鎮市立圖書館共同推動「423世界閱讀日系列活動」辦理形式多元豐富的閱讀活動，鼓勵民眾至鄰近的公共圖書館讀本好書、聽場座談會，重拾閱讀的快樂。\r\n\r\n圖書館423世界閱讀日-小小館員體驗營\r\n時間：4/20(日)上午9:30-11:30\r\n地點：名間鄉立圖書館\r\n報名日期：即日起至4/16(三)下午5時止\r\n參加對象：國小以下學童共計親子15組，額滿為止。\r\n歡迎有興趣的家長報名參加。', '南投縣名間鄉公所', '南投縣名間鄉彰南路42-2號三樓', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '南投縣名間鄉立圖書館', 23.8385841, 120.702733, '無資料', 'https://www.facebook.com/profile.php?id=100064507040051', '[]') ON DUPLICATE KEY UPDATE `activity_name`='423世界閱讀日一小小館員體驗營', `description`='4月23日是文豪莎士比亞及多位偉大作家辭世的日子，為紀念並推廣閱讀和寫作，聯合國教科文組織於1995年將該日定為「世界閱讀日」(World Book & Copyright Day)，旨在希望民眾享受閱讀書本的樂趣。\r\n為了響應世界閱讀日，南投縣政府文化局與13鄉鎮市立圖書館共同推動「423世界閱讀日系列活動」辦理形式多元豐富的閱讀活動，鼓勵民眾至鄰近的公共圖書館讀本好書、聽場座談會，重拾閱讀的快樂。\r\n\r\n圖書館423世界閱讀日-小小館員體驗營\r\n時間：4/20(日)上午9:30-11:30\r\n地點：名間鄉立圖書館\r\n報名日期：即日起至4/16(三)下午5時止\r\n參加對象：國小以下學童共計親子15組，額滿為止。\r\n歡迎有興趣的家長報名參加。', `organizer`='南投縣名間鄉公所', `address`='南投縣名間鄉彰南路42-2號三樓', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='南投縣名間鄉立圖書館', `latitude`=23.8385841, `longitude`=120.702733, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100064507040051', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b19f', '2025竹山歡樂兒童月：海波兒童劇團【勇兔茹比與黃金蘿蔔 】', '下午3點開放入場\r\n不單單只是兒童劇表演\r\n現場還有有獎徵答\r\n會後並有精緻小餐點發送\r\n活動洽詢：049-2645530', '南投縣竹山鎮公所', '南投縣竹山鎮公所路100號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '南投縣竹山鎮公所', 23.7578635, 120.6716995, '無資料', 'https://www.facebook.com/profile.php?id=100084498529334#', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025竹山歡樂兒童月：海波兒童劇團【勇兔茹比與黃金蘿蔔 】', `description`='下午3點開放入場\r\n不單單只是兒童劇表演\r\n現場還有有獎徵答\r\n會後並有精緻小餐點發送\r\n活動洽詢：049-2645530', `organizer`='南投縣竹山鎮公所', `address`='南投縣竹山鎮公所路100號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='南投縣竹山鎮公所', `latitude`=23.7578635, `longitude`=120.6716995, `ticket_price`='無資料', `source_url`='https://www.facebook.com/profile.php?id=100084498529334#', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a626b3242b74a3b1a0', '週末電影院（114年5月）', '南投縣政府文化局圖書館7樓電影放映廳於星期六下午2時播放影片供民眾欣賞，提供您休閒娛樂的好去處！歡迎您全家前來圖書館欣賞影片。\r\n\r\n電影欣賞注意事項：                             \r\n一、請遵守電影分級制度：\r\n(一)普遍級：一般觀眾皆可觀賞。\r\n(二)保護級：未滿六歲之兒童不得觀賞，六歲以上未滿十二歲需父母一起觀賞、十二歲以上自行觀賞。\r\n(三)輔12級；未滿十二歲之兒童不宜觀賞。\r\n二、請於下午1：45後入場，2：00準時放映，敬請準時入場。\r\n三、請勿攜帶飲料及食物入內、手機敬請關機或設定震動狀態。\r\n四、電影播放中請勿任意走動或喧嘩，影響欣賞電影品質，謝謝合作。', '南投縣政府文化局', '南投縣南投市中興路669號', '2025-05-03 00:00:00', '2025-05-24 00:00:00', '南投縣政府文化局圖書館', 23.9027891, 120.691332, '無資料', 'https://www.nthcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='週末電影院（114年5月）', `description`='南投縣政府文化局圖書館7樓電影放映廳於星期六下午2時播放影片供民眾欣賞，提供您休閒娛樂的好去處！歡迎您全家前來圖書館欣賞影片。\r\n\r\n電影欣賞注意事項：                             \r\n一、請遵守電影分級制度：\r\n(一)普遍級：一般觀眾皆可觀賞。\r\n(二)保護級：未滿六歲之兒童不得觀賞，六歲以上未滿十二歲需父母一起觀賞、十二歲以上自行觀賞。\r\n(三)輔12級；未滿十二歲之兒童不宜觀賞。\r\n二、請於下午1：45後入場，2：00準時放映，敬請準時入場。\r\n三、請勿攜帶飲料及食物入內、手機敬請關機或設定震動狀態。\r\n四、電影播放中請勿任意走動或喧嘩，影響欣賞電影品質，謝謝合作。', `organizer`='南投縣政府文化局', `address`='南投縣南投市中興路669號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='南投縣政府文化局圖書館', `latitude`=23.9027891, `longitude`=120.691332, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a726b3242b74a3b1a1', '114年視障者電影聽賞活動：海鷗食堂（普遍級）', '劇情簡介：\r\n芬蘭首都赫爾辛基有一所由日本女性開設的日式食堂「海鷗食堂」，店主兼廚師是一位中年日本女子幸江，她以簡單美味的日本飯糰作為餐廳的招牌菜。\r\n這家奇特的店吸引了不少路人駐足觀望，可卻總是沒人願意坐下來吃點東西。店主希望以最簡單但卻最讓人感到溫暖的傳統飯糰留住客人的心，只可惜事與願違，海鷗食堂經常空空如也。\r\n幸江遇上了第一個客人是位愛好日本文化的青年湯米，然後她又在書店結識綠，並請綠來店裡幫忙，沒多久在機場丟了行李的真佐子，也成了餐廳的一員，由三個日本女子所主持的餐廳漸漸有了顧客...。這三個同樣來自日本的女子在食堂出現，為原本平靜的日子帶來陣陣漣漪。\r\n\r\n一、請遵守電影分級制度：\r\n(一)普遍級：一般觀眾皆可觀賞。\r\n(二)保護級：未滿六歲之兒童不得觀賞，六歲以上未滿十二歲需父母一起觀賞、十二歲以上自行觀賞。\r\n(三)輔12級；未滿十二歲之兒童不宜觀賞。\r\n二、請於下午1：45後入場，2：00準時放映，敬請準時入場。\r\n三、請勿攜帶飲料及食物入內、手機敬請關機或設定震動狀態。\r\n四、電影播放中請勿任意走動或喧嘩，影響欣賞電影品質，謝謝合作。', '南投縣政府文化局', '南投縣南投市中興路669號', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '南投縣政府文化局圖書館', 23.9027891, 120.691332, '無資料', 'https://www.nthcc.gov.tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年視障者電影聽賞活動：海鷗食堂（普遍級）', `description`='劇情簡介：\r\n芬蘭首都赫爾辛基有一所由日本女性開設的日式食堂「海鷗食堂」，店主兼廚師是一位中年日本女子幸江，她以簡單美味的日本飯糰作為餐廳的招牌菜。\r\n這家奇特的店吸引了不少路人駐足觀望，可卻總是沒人願意坐下來吃點東西。店主希望以最簡單但卻最讓人感到溫暖的傳統飯糰留住客人的心，只可惜事與願違，海鷗食堂經常空空如也。\r\n幸江遇上了第一個客人是位愛好日本文化的青年湯米，然後她又在書店結識綠，並請綠來店裡幫忙，沒多久在機場丟了行李的真佐子，也成了餐廳的一員，由三個日本女子所主持的餐廳漸漸有了顧客...。這三個同樣來自日本的女子在食堂出現，為原本平靜的日子帶來陣陣漣漪。\r\n\r\n一、請遵守電影分級制度：\r\n(一)普遍級：一般觀眾皆可觀賞。\r\n(二)保護級：未滿六歲之兒童不得觀賞，六歲以上未滿十二歲需父母一起觀賞、十二歲以上自行觀賞。\r\n(三)輔12級；未滿十二歲之兒童不宜觀賞。\r\n二、請於下午1：45後入場，2：00準時放映，敬請準時入場。\r\n三、請勿攜帶飲料及食物入內、手機敬請關機或設定震動狀態。\r\n四、電影播放中請勿任意走動或喧嘩，影響欣賞電影品質，謝謝合作。', `organizer`='南投縣政府文化局', `address`='南投縣南投市中興路669號', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='南投縣政府文化局圖書館', `latitude`=23.9027891, `longitude`=120.691332, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a726b3242b74a3b1a2', '「文學力-書寫LÁN臺灣主題展」參觀導覽活動（簡婉裁）', '本展為南投縣文學資料館向國立臺灣文學館借用之「文學力─書寫LÁN臺灣」行動展。國立臺灣文學館為國家級的文學博物館，該館將龐雜的臺灣文學體系與史料化繁為簡，透過常設展將百年來的文學史，化為日常且有趣的生活體驗。為增加民眾對於本展的理解，文化局辦理3場參觀導覽活動，特別邀請本縣文學家帶領解說及互動遊戲，活動為免費參加，每場名額25位。\r\n報名網址：https://reurl.cc/0KxWGl\r\n洽詢電話：049-2221619陳小姐', '南投縣政府文化局', '南投縣南投市中興路669號', '2025-05-24 00:00:00', '2025-05-24 00:00:00', '南投縣政府文化局圖書館', 23.9027891, 120.691332, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「文學力-書寫LÁN臺灣主題展」參觀導覽活動（簡婉裁）', `description`='本展為南投縣文學資料館向國立臺灣文學館借用之「文學力─書寫LÁN臺灣」行動展。國立臺灣文學館為國家級的文學博物館，該館將龐雜的臺灣文學體系與史料化繁為簡，透過常設展將百年來的文學史，化為日常且有趣的生活體驗。為增加民眾對於本展的理解，文化局辦理3場參觀導覽活動，特別邀請本縣文學家帶領解說及互動遊戲，活動為免費參加，每場名額25位。\r\n報名網址：https://reurl.cc/0KxWGl\r\n洽詢電話：049-2221619陳小姐', `organizer`='南投縣政府文化局', `address`='南投縣南投市中興路669號', `start_date`='2025-05-24 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='南投縣政府文化局圖書館', `latitude`=23.9027891, `longitude`=120.691332, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
