INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a726b3242b74a3b1a4', '2025年世界書香日：藝術創作閱讀講座-細說工筆畫', '開放現場自由參加\r\n洽詢電話：049-2317071', '國立公共資訊圖書館中興分館', '南投縣南投市中興新村光華路 123 號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '國立公共資訊圖書館中興分館', 23.949518, 120.694397, '無資料', 'https://www.facebook.com/NLPICH', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年世界書香日：藝術創作閱讀講座-細說工筆畫', `description`='開放現場自由參加\r\n洽詢電話：049-2317071', `organizer`='國立公共資訊圖書館中興分館', `address`='南投縣南投市中興新村光華路 123 號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='國立公共資訊圖書館中興分館', `latitude`=23.949518, `longitude`=120.694397, `ticket_price`='無資料', `source_url`='https://www.facebook.com/NLPICH', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('680019a726b3242b74a3b1a5', '2025年世界書香日：英文故事時間', '聽故事只能坐著聽嗎？\r\n不～，只要孩子覺得舒服與自在都是最好的故事！\r\n4/19(星期六)中興分館英文繪本活動講師運用艾瑞卡爾的2本經典繪本，和小孩跟著音樂旋律一起唱唱跳跳，在遊戲中慢慢熟悉英文的語韻&語感，逐漸習慣英語出現在生活之中！\r\n參加對象：3-8歲親子。\r\n報名網址 https://reurl.cc/4LoDD3\r\n洽詢電話：049-2317071', '國立公共資訊圖書館中興分館', '南投縣南投市中興新村光華路 123 號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '國立公共資訊圖書館中興分館', 23.949518, 120.694397, '無資料', 'https://www.facebook.com/NLPICH', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025年世界書香日：英文故事時間', `description`='聽故事只能坐著聽嗎？\r\n不～，只要孩子覺得舒服與自在都是最好的故事！\r\n4/19(星期六)中興分館英文繪本活動講師運用艾瑞卡爾的2本經典繪本，和小孩跟著音樂旋律一起唱唱跳跳，在遊戲中慢慢熟悉英文的語韻&語感，逐漸習慣英語出現在生活之中！\r\n參加對象：3-8歲親子。\r\n報名網址 https://reurl.cc/4LoDD3\r\n洽詢電話：049-2317071', `organizer`='國立公共資訊圖書館中興分館', `address`='南投縣南投市中興新村光華路 123 號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='國立公共資訊圖書館中興分館', `latitude`=23.949518, `longitude`=120.694397, `ticket_price`='無資料', `source_url`='https://www.facebook.com/NLPICH', `image_url`='[]';
