INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('6800738807f3c8b8c6b19b7b', '2025世界閱讀日—「閱讀．腦內飛」', '文化部響應423世界閱讀日，舉辦2025年世界閱讀日「閱讀．腦內飛」主題活動，將於4月19日(六)至27日(日)期間，在臺灣當代文化實驗場C-Lab(空總)，運用100本精選書籍，首度策劃連續9天，集結了各式各樣用文本改編的精采演出、互動書展與說故事活動，一系列閱讀與表演藝術的跨界文化體驗活動，希望讓閱讀從紙本走進生活、走進人與人的連結，也走進孩子們的成長記憶。', '文化部 人文司', '臺北市臺北市大安區建國南路一段177號', '2025-04-19 00:00:00', '2025-04-27 00:00:00', '臺灣當代文化實驗場', '無資料', '無資料', '無資料', 'https://lets-go-reading.com/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025世界閱讀日—「閱讀．腦內飛」', `description`='文化部響應423世界閱讀日，舉辦2025年世界閱讀日「閱讀．腦內飛」主題活動，將於4月19日(六)至27日(日)期間，在臺灣當代文化實驗場C-Lab(空總)，運用100本精選書籍，首度策劃連續9天，集結了各式各樣用文本改編的精采演出、互動書展與說故事活動，一系列閱讀與表演藝術的跨界文化體驗活動，希望讓閱讀從紙本走進生活、走進人與人的連結，也走進孩子們的成長記憶。', `organizer`='文化部 人文司', `address`='臺北市臺北市大安區建國南路一段177號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='臺灣當代文化實驗場', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://lets-go-reading.com/', `image_url`='[]';
