INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016ac926b3242b74a3b1cd', '2025暑期人才培訓營-工藝漫活-染境：茶的空間敘事【中區－工藝中心】', '研習內容：\n\n\n	天然纖維材料處理及植物染色實務。\n	藍靛建藍及藍染技法實務。\n	樹皮布纖維材質處理及製作\n	布料成型加工技法\n	專題作品設計及製作\n\n\n \n\n課程日期：7月2日~8月15日，上課日期詳見招生簡章之課程規劃表。\n\n上課地點：國立臺灣工藝研究發展中心技術組纖維研發實驗室 (南投縣草屯鎮中正路573號)\n\n學雜費用：3,360元（低/中低收入學員得減免學雜費繳納，詳見簡章注意事項二）\n\n保證金：2,000元(符合發還要件，將依招生簡章規定發還)\n\n(研習期間之專題材料費、膳、宿及交通費、保險費等自理。)\n\n報名截止：2025年5月18日(四)23:59止\n\n報名資格：\n\n      1.各大專院校美術、設計、工藝、織品服裝、視覺傳達、文化相關科系在學或應屆畢業學生。\n\n      2.國內大專院校非相關科系在校學生，對纖維工藝有興趣在學或應屆畢業學生 (須年滿18歲以上) 。\n\n※請於本簡章公告之官網報名入口進行線上報名※\n\n \n\n \n\n \n\n ', '國立台灣工藝研究發展中心', '542  南投縣草屯鎮中正路573號', '2025-07-01 00:00:00', '2025-08-15 00:00:00', '技術組大樓', 23.9797002, 120.69095, '5360', 'https://event.culture.tw/mocweb/reg/NTCRI/Detail.init.ctr?actId=50183', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025暑期人才培訓營-工藝漫活-染境：茶的空間敘事【中區－工藝中心】', `description`='研習內容：\n\n\n	天然纖維材料處理及植物染色實務。\n	藍靛建藍及藍染技法實務。\n	樹皮布纖維材質處理及製作\n	布料成型加工技法\n	專題作品設計及製作\n\n\n \n\n課程日期：7月2日~8月15日，上課日期詳見招生簡章之課程規劃表。\n\n上課地點：國立臺灣工藝研究發展中心技術組纖維研發實驗室 (南投縣草屯鎮中正路573號)\n\n學雜費用：3,360元（低/中低收入學員得減免學雜費繳納，詳見簡章注意事項二）\n\n保證金：2,000元(符合發還要件，將依招生簡章規定發還)\n\n(研習期間之專題材料費、膳、宿及交通費、保險費等自理。)\n\n報名截止：2025年5月18日(四)23:59止\n\n報名資格：\n\n      1.各大專院校美術、設計、工藝、織品服裝、視覺傳達、文化相關科系在學或應屆畢業學生。\n\n      2.國內大專院校非相關科系在校學生，對纖維工藝有興趣在學或應屆畢業學生 (須年滿18歲以上) 。\n\n※請於本簡章公告之官網報名入口進行線上報名※\n\n \n\n \n\n \n\n ', `organizer`='國立台灣工藝研究發展中心', `address`='542  南投縣草屯鎮中正路573號', `start_date`='2025-07-01 00:00:00', `end_date`='2025-08-15 00:00:00', `location`='技術組大樓', `latitude`=23.9797002, `longitude`=120.69095, `ticket_price`='5360', `source_url`='https://event.culture.tw/mocweb/reg/NTCRI/Detail.init.ctr?actId=50183', `image_url`='[]';
