INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b6326b3242b74a3b1d9', '第一屆「臺灣學」', '「臺灣學」全國研究生學術研討會為國立彰化師範大學台灣文學研究所主辦之學術研討會，於2025年舉行第一屆，提供對臺灣文學、文化、語言、影視、歷史、藝術、音樂等領域有興趣之有志發表論文的學術平台。', '國立彰化師範大學臺灣文學研究所', '彰化縣彰化市進德路1號', '2025-05-02 00:00:00', '2025-05-02 00:00:00', '國立彰化師範大學', 24.07532909, 120.5694208, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='第一屆「臺灣學」', `description`='「臺灣學」全國研究生學術研討會為國立彰化師範大學台灣文學研究所主辦之學術研討會，於2025年舉行第一屆，提供對臺灣文學、文化、語言、影視、歷史、藝術、音樂等領域有興趣之有志發表論文的學術平台。', `organizer`='國立彰化師範大學臺灣文學研究所', `address`='彰化縣彰化市進德路1號', `start_date`='2025-05-02 00:00:00', `end_date`='2025-05-02 00:00:00', `location`='國立彰化師範大學', `latitude`=24.07532909, `longitude`=120.5694208, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b6e26b3242b74a3b1da', '『 安任 』林倉霈 創作個展', '生命的本質，本自俱足的佛性恆常不變 ...\r\n而『安任』的系列作品正是反映著創作他內心循環不變的本質。', '美丘美朮 Mioka Art', '臺中市南屯區', '2025-04-08 00:00:00', '2025-05-25 00:00:00', '南屯區（臺中市）=', 24.14165524, 120.6177379, '無資料', 'https://www.facebook.com/share/p/1ARjHQjBCT/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='『 安任 』林倉霈 創作個展', `description`='生命的本質，本自俱足的佛性恆常不變 ...\r\n而『安任』的系列作品正是反映著創作他內心循環不變的本質。', `organizer`='美丘美朮 Mioka Art', `address`='臺中市南屯區', `start_date`='2025-04-08 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1ARjHQjBCT/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b6f26b3242b74a3b1db', '2025 Julien Chauvin X 閑弦室內樂集', '2024年獲得法國「藝術與文學騎士勳章」（Ordre des Arts et des Lettres）的小提琴家－朱利安．修方（Julien Chauvin），是法國知名小提琴家與指揮家，長久以來專注於古樂復興，他於2005年創立古樂團Le Cercle de l’Harmonie、並在2015年成立管弦樂團Le Concert de la Loge均為樂迷們精心呈現巴洛克時代音樂風華。2024年受國立清華大學音樂系邀請來臺舉辦大師班，並與閑弦室內樂集合作首次在臺舉辦公開演出，曲目挑選自巴洛克時期至古典時期的經典，修方不僅再現巴洛克樂章的精緻細膩，更演出其他時期的精彩曲目，向聽眾獻上一場豐富多元的音樂盛宴；2025年閑弦再度邀請大師來臺，此次將於臺北、臺中兩地演出，曲目橫跨巴洛克至浪漫時期，展現大師擅長的細膩巴洛克，亦呈現復刻古典的浪漫。', '閑弦室內樂集Cosy Chord Ensemble', '臺中市北區健行路111號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '臺中市私立新民高級中學', 24.15863985, 120.6809521, '無資料', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025 Julien Chauvin X 閑弦室內樂集', `description`='2024年獲得法國「藝術與文學騎士勳章」（Ordre des Arts et des Lettres）的小提琴家－朱利安．修方（Julien Chauvin），是法國知名小提琴家與指揮家，長久以來專注於古樂復興，他於2005年創立古樂團Le Cercle de l’Harmonie、並在2015年成立管弦樂團Le Concert de la Loge均為樂迷們精心呈現巴洛克時代音樂風華。2024年受國立清華大學音樂系邀請來臺舉辦大師班，並與閑弦室內樂集合作首次在臺舉辦公開演出，曲目挑選自巴洛克時期至古典時期的經典，修方不僅再現巴洛克樂章的精緻細膩，更演出其他時期的精彩曲目，向聽眾獻上一場豐富多元的音樂盛宴；2025年閑弦再度邀請大師來臺，此次將於臺北、臺中兩地演出，曲目橫跨巴洛克至浪漫時期，展現大師擅長的細膩巴洛克，亦呈現復刻古典的浪漫。', `organizer`='閑弦室內樂集Cosy Chord Ensemble', `address`='臺中市北區健行路111號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺中市私立新民高級中學', `latitude`=24.15863985, `longitude`=120.6809521, `ticket_price`='無資料', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b7026b3242b74a3b1dc', '東西縱橫記藝 Junie Wang 2025 春季講座【名畫裡的光影】（２場）', '　　光與影，造就藝術中的魔法與奇蹟。沒有光，蒙娜麗莎就少了那抹神秘微笑；缺乏影，林布蘭的肖像就不會如此深邃動人。\r\n　　東方繪畫講究線條與留白，西方繪畫則自文藝復興起，以陰暗背景襯托光源，讓畫面更具層次與現實感。無論拜占庭教堂隱約閃爍金箔、哥德式教堂斑斕花窗，或者攝影術誕生，光影以神奇手法，塑造空間、賦予情感，將種種細節化為永恆記憶。\r\n　　光影效果在藝術史進程有多麼重要？\r\n　　古希臘已經懂得使用陰影塑造立體感。文藝復興時期達文西發展出如夢似幻手法，使得麗莎小姐神祕迷人笑容蕩漾至今。17世紀巴洛克繪畫祖師爺卡拉瓦喬發揮「暗色調主義」（Tenebrism）強烈光影對比到極致，將畫布打造成舞台。結果他自己的人生更是抓馬（drama）到極點，嘖嘖嘖（搖頭）…\r\n　　林布蘭的氤氳光芒從內向外擴散渲染，輝映畫布和人物，可惜就是沒有照亮自己的人生。誰叫你太愛亂買（丟筆）。維梅爾的晶瑩日光更是精緻如詩，結合寫實情景與安排情節，正好讓直男金主們口水流不停（遞面紙）。維拉斯貴茲更是將光影和構圖應用到出神入化的境地，為哈布斯堡小公主繪製宮廷肖像畫，自己順便刷點存在感。\r\n　　光影大師的代表作件件精彩，地位不可撼動。但是除了名氣響亮，身價無法估算，人家到底哪裡厲害？光影在其中發揮哪些神奇作用？我們要如何觀看、解讀並感受這些被創造於畫布上的輝煌時刻？\r\n　　「名畫裡的光影」要穿梭千年歲月，感受藝術史中，那些光輝如耀眼燦爛，暗影若靜謐無華的非凡時刻。', '台中市歐洲文化創意產業協會', '臺中市南屯區', '2025-04-26 00:00:00', '2025-04-27 00:00:00', '南屯區（臺中市）=', 24.14165524, 120.6177379, '全票+800', 'https://www.facebook.com/events/1154345406000611?acontext=%7B%22event_action_history%22%3A[%7B%22mec', '[]') ON DUPLICATE KEY UPDATE `activity_name`='東西縱橫記藝 Junie Wang 2025 春季講座【名畫裡的光影】（２場）', `description`='　　光與影，造就藝術中的魔法與奇蹟。沒有光，蒙娜麗莎就少了那抹神秘微笑；缺乏影，林布蘭的肖像就不會如此深邃動人。\r\n　　東方繪畫講究線條與留白，西方繪畫則自文藝復興起，以陰暗背景襯托光源，讓畫面更具層次與現實感。無論拜占庭教堂隱約閃爍金箔、哥德式教堂斑斕花窗，或者攝影術誕生，光影以神奇手法，塑造空間、賦予情感，將種種細節化為永恆記憶。\r\n　　光影效果在藝術史進程有多麼重要？\r\n　　古希臘已經懂得使用陰影塑造立體感。文藝復興時期達文西發展出如夢似幻手法，使得麗莎小姐神祕迷人笑容蕩漾至今。17世紀巴洛克繪畫祖師爺卡拉瓦喬發揮「暗色調主義」（Tenebrism）強烈光影對比到極致，將畫布打造成舞台。結果他自己的人生更是抓馬（drama）到極點，嘖嘖嘖（搖頭）…\r\n　　林布蘭的氤氳光芒從內向外擴散渲染，輝映畫布和人物，可惜就是沒有照亮自己的人生。誰叫你太愛亂買（丟筆）。維梅爾的晶瑩日光更是精緻如詩，結合寫實情景與安排情節，正好讓直男金主們口水流不停（遞面紙）。維拉斯貴茲更是將光影和構圖應用到出神入化的境地，為哈布斯堡小公主繪製宮廷肖像畫，自己順便刷點存在感。\r\n　　光影大師的代表作件件精彩，地位不可撼動。但是除了名氣響亮，身價無法估算，人家到底哪裡厲害？光影在其中發揮哪些神奇作用？我們要如何觀看、解讀並感受這些被創造於畫布上的輝煌時刻？\r\n　　「名畫裡的光影」要穿梭千年歲月，感受藝術史中，那些光輝如耀眼燦爛，暗影若靜謐無華的非凡時刻。', `organizer`='台中市歐洲文化創意產業協會', `address`='臺中市南屯區', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='全票+800', `source_url`='https://www.facebook.com/events/1154345406000611?acontext=%7B%22event_action_history%22%3A[%7B%22mec', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b7026b3242b74a3b1dd', '《巴赫上架中》新書分享會', '　　面對書架上，林林總總都在談樂曲的書籍，你該選擇哪一本？\r\n　　如果你也喜歡聽音樂、買唱片，那麼就不能錯過這一本《巴赫上架中》由古典音樂台「這周聽什麼」節目主持人—周靖庭所編寫出版的新書！\r\n　　以10套巴赫的經典器樂作品為主，介紹100年來的私房推薦錄音，兼談作曲家的樂曲設計。\r\n書中跳脫名演名盤的榜單思維，重新蒐羅從入門聆賞到進階收藏皆宜的優異演奏。\r\n　　帶著你一起跟著小周聽準沒錯！尤其，在唱片行挖寶，還不確定是否要帶走全集的經典前，不妨先來看看這一本聊樂曲版本的《巴赫上架中》，或許會帶給你，不同的物色唱片思維，增添更多的選樂跟收藏的樂趣。', '社團法人台灣打里摺文化協會', '臺中市南屯區', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '南屯區（臺中市）=', 24.14165524, 120.6177379, '無資料', 'https://www.facebook.com/events/2391917117832288/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《巴赫上架中》新書分享會', `description`='　　面對書架上，林林總總都在談樂曲的書籍，你該選擇哪一本？\r\n　　如果你也喜歡聽音樂、買唱片，那麼就不能錯過這一本《巴赫上架中》由古典音樂台「這周聽什麼」節目主持人—周靖庭所編寫出版的新書！\r\n　　以10套巴赫的經典器樂作品為主，介紹100年來的私房推薦錄音，兼談作曲家的樂曲設計。\r\n書中跳脫名演名盤的榜單思維，重新蒐羅從入門聆賞到進階收藏皆宜的優異演奏。\r\n　　帶著你一起跟著小周聽準沒錯！尤其，在唱片行挖寶，還不確定是否要帶走全集的經典前，不妨先來看看這一本聊樂曲版本的《巴赫上架中》，或許會帶給你，不同的物色唱片思維，增添更多的選樂跟收藏的樂趣。', `organizer`='社團法人台灣打里摺文化協會', `address`='臺中市南屯區', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='無資料', `source_url`='https://www.facebook.com/events/2391917117832288/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b7026b3242b74a3b1de', '紀欣宜油畫創作展-活在當下、快樂做自己', '紀欣宜的油畫創作以色彩豐富、生動的方式表現出她對這些主題的理解，藉由畫作讓觀眾感受到「活在當下」的快樂與自由，或許還會有一些抽象的表現形式，來詮釋如何突破生活中的壓力，釋放內心的真我。', '臺中市立圖書館龍井分館', '臺中市龍井區觀光路2號', '2025-04-02 00:00:00', '2025-04-30 00:00:00', '臺中市立圖書館龍井分館', 24.20062892, 120.5283728, '無資料', 'https://reurl.cc/j91mNM', '[]') ON DUPLICATE KEY UPDATE `activity_name`='紀欣宜油畫創作展-活在當下、快樂做自己', `description`='紀欣宜的油畫創作以色彩豐富、生動的方式表現出她對這些主題的理解，藉由畫作讓觀眾感受到「活在當下」的快樂與自由，或許還會有一些抽象的表現形式，來詮釋如何突破生活中的壓力，釋放內心的真我。', `organizer`='臺中市立圖書館龍井分館', `address`='臺中市龍井區觀光路2號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='臺中市立圖書館龍井分館', `latitude`=24.20062892, `longitude`=120.5283728, `ticket_price`='無資料', `source_url`='https://reurl.cc/j91mNM', `image_url`='[]';
