INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b7226b3242b74a3b1e3', '陳景德油畫個展', '陳景德先生於70歲，終於有機會進入長青學苑學習繪畫，自幼喜愛繪畫的他，正式邁入藝術領域 。經4年學習水墨，接著8年學習油畫。歷經12年的成果展。陳先生開始策劃個人展 ，於藝文中心展出個人作品。與同好一起切磋、共享習畫的人生歷程，陳先生今年91歲，仍然不斷在繪畫術藝上精益求精。真正落實對藝術的嚮往與實踐。\r\n\r\n準備個人展的圖，就須要耗費相當的時間與精神，一張畫最快完稿也要三星期。加上構圖，往往一畫就好幾個天日。陳先生猶記得45歲已當阿公的他，帶著妻子去阿里山，把讀書時期心目中最美好的阿里山拍下來 ，那一次也是第一次帶妻子去旅行 。把阿里山的日出、日落，與當時的美好拍下來。在他的畫展裡一一的呈現那時的幸福與感動。', '無資料', '臺中市太平區大興路201號', '2025-04-12 00:00:00', '2025-05-04 00:00:00', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', 'https://www.ttdac.taichung.gov.tw/nb5488510420289596143/nbArticleContent', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陳景德油畫個展', `description`='陳景德先生於70歲，終於有機會進入長青學苑學習繪畫，自幼喜愛繪畫的他，正式邁入藝術領域 。經4年學習水墨，接著8年學習油畫。歷經12年的成果展。陳先生開始策劃個人展 ，於藝文中心展出個人作品。與同好一起切磋、共享習畫的人生歷程，陳先生今年91歲，仍然不斷在繪畫術藝上精益求精。真正落實對藝術的嚮往與實踐。\r\n\r\n準備個人展的圖，就須要耗費相當的時間與精神，一張畫最快完稿也要三星期。加上構圖，往往一畫就好幾個天日。陳先生猶記得45歲已當阿公的他，帶著妻子去阿里山，把讀書時期心目中最美好的阿里山拍下來 ，那一次也是第一次帶妻子去旅行 。把阿里山的日出、日落，與當時的美好拍下來。在他的畫展裡一一的呈現那時的幸福與感動。', `organizer`='無資料', `address`='臺中市太平區大興路201號', `start_date`='2025-04-12 00:00:00', `end_date`='2025-05-04 00:00:00', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='https://www.ttdac.taichung.gov.tw/nb5488510420289596143/nbArticleContent', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b7226b3242b74a3b1e4', '劉素惠水墨創作個展 黑韻II', '劉素惠學習水墨創作九年，在恩師水墨行者何木火大師的提點下，發現水與墨的多寡及運用組合變化無窮，自覺水墨創作不但是繪畫藝術更是空間藝術，獨具東方氣息韻味的美，視覺效果更甚於西畫的色彩繽紛。墨色層疊營造前後空間和情境氛圍，留白與潛移的墨色交織出移動的視覺吸引力，幻化無窮的水墨之韻，令人讚嘆，驚呼! 墨色是最沉穩內斂的耀眼，於是一頭栽進以墨色為主的創作樂趣。\r\n\r\n“黑韻II”是劉素惠的第三次個展，與上次展出的系列作品相較之下，”黑韻”主題更加明確。本次創作取材於大自然，呈現鄉野風情、刻畫歲月風骨、滄桑林木等…..傳承水墨精神以墨代彩，五色墨中更以濃、乾墨表現居多。\r\n\r\n創作中表現扣人心弦的深沉墨色，經營留白亦是最細膩的思考，點狀的漸層留白在黝黑墨色中創造隱約有物的視覺騷動，也是”黑韻”展覽的特色。\r\n\r\n建議各位愛好藝術的朋友，在欣賞線條與墨色律動之外；也請細細的品味黝黑情境中仍然有此起彼落的墨色深淺與留白舞動。\r\n\r\n劉素惠是業餘創作者，由於時間運用上的限制，創作之路並不順遂，但是非常享受這些得來不易的片刻，更珍惜巧遇明師的善緣，希望透過這次展出機會，分享九年來與水墨獨處、創作的喜悅和成果。', '無資料', '臺中市太平區大興路201號', '2025-04-26 00:00:00', '2025-05-18 00:00:00', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', 'https://www.ttdac.taichung.gov.tw/nb5297169551471246788/nbArticleContent', '[]') ON DUPLICATE KEY UPDATE `activity_name`='劉素惠水墨創作個展 黑韻II', `description`='劉素惠學習水墨創作九年，在恩師水墨行者何木火大師的提點下，發現水與墨的多寡及運用組合變化無窮，自覺水墨創作不但是繪畫藝術更是空間藝術，獨具東方氣息韻味的美，視覺效果更甚於西畫的色彩繽紛。墨色層疊營造前後空間和情境氛圍，留白與潛移的墨色交織出移動的視覺吸引力，幻化無窮的水墨之韻，令人讚嘆，驚呼! 墨色是最沉穩內斂的耀眼，於是一頭栽進以墨色為主的創作樂趣。\r\n\r\n“黑韻II”是劉素惠的第三次個展，與上次展出的系列作品相較之下，”黑韻”主題更加明確。本次創作取材於大自然，呈現鄉野風情、刻畫歲月風骨、滄桑林木等…..傳承水墨精神以墨代彩，五色墨中更以濃、乾墨表現居多。\r\n\r\n創作中表現扣人心弦的深沉墨色，經營留白亦是最細膩的思考，點狀的漸層留白在黝黑墨色中創造隱約有物的視覺騷動，也是”黑韻”展覽的特色。\r\n\r\n建議各位愛好藝術的朋友，在欣賞線條與墨色律動之外；也請細細的品味黝黑情境中仍然有此起彼落的墨色深淺與留白舞動。\r\n\r\n劉素惠是業餘創作者，由於時間運用上的限制，創作之路並不順遂，但是非常享受這些得來不易的片刻，更珍惜巧遇明師的善緣，希望透過這次展出機會，分享九年來與水墨獨處、創作的喜悅和成果。', `organizer`='無資料', `address`='臺中市太平區大興路201號', `start_date`='2025-04-26 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='https://www.ttdac.taichung.gov.tw/nb5297169551471246788/nbArticleContent', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b7226b3242b74a3b1e5', '《海豚男孩》電影欣賞', '在這部精彩的動畫電影《海豚男孩》中，觀眾將跟隨主角踏上一場與海豚為伴的海底大冒險，體驗友情與勇氣的力量，同時深入了解保護海洋的重要性。藉由影片，我們希望啟發觀眾珍愛海洋，並加入行動保護這片蔚藍家園。', '臺中市屯區藝文中心', '臺中市太平區大興路201號', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '臺中市屯區藝文中心', 24.1566119, 120.7346237, '無資料', 'https://www.ttdac.taichung.gov.tw/nc4858809047657421048/ncArticleContent', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《海豚男孩》電影欣賞', `description`='在這部精彩的動畫電影《海豚男孩》中，觀眾將跟隨主角踏上一場與海豚為伴的海底大冒險，體驗友情與勇氣的力量，同時深入了解保護海洋的重要性。藉由影片，我們希望啟發觀眾珍愛海洋，並加入行動保護這片蔚藍家園。', `organizer`='臺中市屯區藝文中心', `address`='臺中市太平區大興路201號', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='臺中市屯區藝文中心', `latitude`=24.1566119, `longitude`=120.7346237, `ticket_price`='無資料', `source_url`='https://www.ttdac.taichung.gov.tw/nc4858809047657421048/ncArticleContent', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b7226b3242b74a3b1e6', '且行且珍惜─陳麗娟創作展', '鉅虹美學館2025首檔展覽，除了有陶藝作品外，也展出油畫。藝術家陳麗娟油畫作品，擅長以點線面筆法，堆疊勾勒動人的美景，結合繽紛色彩，將生活的美好經驗，透過美感呈現在畫作中。活潑用色勾勒歡欣的畫面氛圍，色彩層層疊疊，堆疊出彩層紋的巨石山巒，或是陡峭蒼翠的翠谷美景，生機勃勃、如詩如畫，詮釋人生如歌、活在當下的真諦。', '鉅虹建設', '臺中市北屯區', '2025-03-03 00:00:00', '2025-06-30 00:00:00', '北屯區（臺中市）=', 24.18400298, 120.7362319, '無資料', 'https://www.facebook.com/share/p/1Dhsv771wS/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='且行且珍惜─陳麗娟創作展', `description`='鉅虹美學館2025首檔展覽，除了有陶藝作品外，也展出油畫。藝術家陳麗娟油畫作品，擅長以點線面筆法，堆疊勾勒動人的美景，結合繽紛色彩，將生活的美好經驗，透過美感呈現在畫作中。活潑用色勾勒歡欣的畫面氛圍，色彩層層疊疊，堆疊出彩層紋的巨石山巒，或是陡峭蒼翠的翠谷美景，生機勃勃、如詩如畫，詮釋人生如歌、活在當下的真諦。', `organizer`='鉅虹建設', `address`='臺中市北屯區', `start_date`='2025-03-03 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='北屯區（臺中市）=', `latitude`=24.18400298, `longitude`=120.7362319, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/1Dhsv771wS/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b7326b3242b74a3b1e7', '【基北北桃台語家庭意識培力講座】  新北場—本土語言政策ê再轉型正義', '【基北北桃台語家庭意識培力講座】\r\n\r\n新北場—本土語言政策ê再轉型正義\r\n\r\n\r\n費用：免費參加，請先報名，實名制。\r\n報名網址 https://forms.gle/ZfqoWkoS2N1sXw1Y6\r\n\r\n認列台語文化活動\r\nhttps://ntlgportal.moc.gov.tw/home/zh-tw/twactivity/135855\r\n\r\n\r\n台語使用比例:100%\r\n預計認列點數:2\r\n#配合文化部培育台語家庭計畫集點  ＃文化部國家語言整體發展方案支持\r\n\r\n主講人：許慧如\r\n臺灣師範大學臺灣語文學系教授\r\n\r\n\r\n內容：\r\n• 本土語地位無實際提升\r\n• 無看著台語ê共通語地位\r\n• 復振hām推廣ê精差huē無清楚\r\n• 強調文化、傳承，脫離日常生活\r\n• 對台灣各語言ê定位建議\r\n\r\n\r\n\r\n▎活動時間：2025/4/19(拜六) 下晡2:00～4:00\r\n\r\n▎名額：網路報名30人\r\n\r\n▎地點：新北市立圖書館總館 5樓研習教室 (新北市板橋區貴興路139號)\r\n\r\n\r\n\r\n\r\n洽詢電話：02-23112199\r\n聯絡信箱：bongpo1996@gmail.com\r\n\r\n\r\n主辦單位：李江却台語文教基金會\r\n\r\n補助單位：文化部\r\n\r\n合辦單位：新北市立圖書館\r\n\r\n------------------------------\r\n\r\n\r\n\r\n題目：本土語言政策的再轉型正義\r\n\r\n\r\n內容：\r\n\r\n• 本土語地位未實質提升\r\n\r\n• 忽略台語的共通語地位\r\n\r\n• 未釐清復振與推廣的差別\r\n\r\n• 強調文化、傳承，脫離日常生活\r\n\r\n• 對台灣各語言的定位建議\r\n\r\n------------------------------\r\n\r\n台語家庭集點計劃：上「國家語言數位資訊網」，進入台語家庭會員平台，登錄成做預備台語家庭，每一个人lóng ài先申請會員口座(身分證抑是健保卡電子檔)，其中一位綁定厝內人，選擇「台語學習/文化家庭」，開始報名活動kah課程，集點換台語獎勵金、抽獎機會。\r\n\r\n台語家庭會員平台常見問題  https://tg.moc.gov.tw/ptgl-user-service/faq-login.html\r\n\r\n--------------------------------\r\n\r\n歡迎捐款贊助　#李江却台語文教基金會　\r\n（捐款可抵稅，匯款後請通知02-23112199）\r\n線上捐款(定期定額)\r\nhttps://donate.newebpay.com/Period/akhioh/lkk\r\n線上捐款(單筆)\r\nhttps://donate.newebpay.com/akhioh/lkk\r\n\r\n郵政劃撥：19021486\r\n戶名：財團法人李江却台語文教基金會\r\n\r\n電匯：123-20-050514-2 華南銀行士林分行活儲\r\n戶名：財團法人李江却台語文教基金會\r\n\r\n#基北北桃台語家庭意識培力講座講座 #李江却台語文教基金會 #文化部 #許慧如 #新北市立圖書館', '李江却台語文教基金會', '新北市板橋區貴興路139號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '新北市立圖書館總館', 25.01186453, 121.4579675, '無資料', 'https://www.tgb.org.tw/2025/03/e.html', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【基北北桃台語家庭意識培力講座】  新北場—本土語言政策ê再轉型正義', `description`='【基北北桃台語家庭意識培力講座】\r\n\r\n新北場—本土語言政策ê再轉型正義\r\n\r\n\r\n費用：免費參加，請先報名，實名制。\r\n報名網址 https://forms.gle/ZfqoWkoS2N1sXw1Y6\r\n\r\n認列台語文化活動\r\nhttps://ntlgportal.moc.gov.tw/home/zh-tw/twactivity/135855\r\n\r\n\r\n台語使用比例:100%\r\n預計認列點數:2\r\n#配合文化部培育台語家庭計畫集點  ＃文化部國家語言整體發展方案支持\r\n\r\n主講人：許慧如\r\n臺灣師範大學臺灣語文學系教授\r\n\r\n\r\n內容：\r\n• 本土語地位無實際提升\r\n• 無看著台語ê共通語地位\r\n• 復振hām推廣ê精差huē無清楚\r\n• 強調文化、傳承，脫離日常生活\r\n• 對台灣各語言ê定位建議\r\n\r\n\r\n\r\n▎活動時間：2025/4/19(拜六) 下晡2:00～4:00\r\n\r\n▎名額：網路報名30人\r\n\r\n▎地點：新北市立圖書館總館 5樓研習教室 (新北市板橋區貴興路139號)\r\n\r\n\r\n\r\n\r\n洽詢電話：02-23112199\r\n聯絡信箱：bongpo1996@gmail.com\r\n\r\n\r\n主辦單位：李江却台語文教基金會\r\n\r\n補助單位：文化部\r\n\r\n合辦單位：新北市立圖書館\r\n\r\n------------------------------\r\n\r\n\r\n\r\n題目：本土語言政策的再轉型正義\r\n\r\n\r\n內容：\r\n\r\n• 本土語地位未實質提升\r\n\r\n• 忽略台語的共通語地位\r\n\r\n• 未釐清復振與推廣的差別\r\n\r\n• 強調文化、傳承，脫離日常生活\r\n\r\n• 對台灣各語言的定位建議\r\n\r\n------------------------------\r\n\r\n台語家庭集點計劃：上「國家語言數位資訊網」，進入台語家庭會員平台，登錄成做預備台語家庭，每一个人lóng ài先申請會員口座(身分證抑是健保卡電子檔)，其中一位綁定厝內人，選擇「台語學習/文化家庭」，開始報名活動kah課程，集點換台語獎勵金、抽獎機會。\r\n\r\n台語家庭會員平台常見問題  https://tg.moc.gov.tw/ptgl-user-service/faq-login.html\r\n\r\n--------------------------------\r\n\r\n歡迎捐款贊助　#李江却台語文教基金會　\r\n（捐款可抵稅，匯款後請通知02-23112199）\r\n線上捐款(定期定額)\r\nhttps://donate.newebpay.com/Period/akhioh/lkk\r\n線上捐款(單筆)\r\nhttps://donate.newebpay.com/akhioh/lkk\r\n\r\n郵政劃撥：19021486\r\n戶名：財團法人李江却台語文教基金會\r\n\r\n電匯：123-20-050514-2 華南銀行士林分行活儲\r\n戶名：財團法人李江却台語文教基金會\r\n\r\n#基北北桃台語家庭意識培力講座講座 #李江却台語文教基金會 #文化部 #許慧如 #新北市立圖書館', `organizer`='李江却台語文教基金會', `address`='新北市板橋區貴興路139號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='新北市立圖書館總館', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='https://www.tgb.org.tw/2025/03/e.html', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b7c26b3242b74a3b1e8', '藝享.異想-順天國小藝術才能美術班展', '　　順天國小藝術才能美術班以人文關懷、創意實踐與生活美感的藝術教育，激發孩童多元適性發展，以「美力順天」為藝術才能美術班願景。培養兒童會做、會看、會想的能力，將藝術學習統整融入生活；透過藝術教育達到全人教育日標，培植美術才能表現優秀學生；促進學生認識藝術價值，學習尊重與關懷，透過藝術創意表現充分展現自我、合作學習，以深耕藝術基礎教育與藝術华根之教育理念。\r\n　　順天國小藝術才能美術班提供多元化之學習，以藝術的內涵與學習營造社區美感活動課程，透過參觀美術館、博物館等，增廣見聞並提升審美之情操。\r\n理解在地文化與中外文化藝術的內涵與特色，並於生活中具疆實踐，鼓勵學生多參與各項美術活動，以增加創作經驗。\r\n　　順天國小藝術才能美術班學生作品，展示了學生們豐富多樣的創作成果。\r\n　　此次作品展覽精心策劃，包含多種類型作品，如大型自盡像、平面設計、精美版畫、水墨盡，以及各式繪盡與漫畫類作品。每件作品都獨具匠心，融合了創意與技術，展現了學生們在創作過程中不斷探索與試驗的精神。大型自畫像不僅呈現了藝術家的個性，更是他們內心世界的真實寫照；平面設計作品則展示了視覺傳達的魅力，凸顯了功能與美感的完美結合；而版畫和水墨畫則承載著傳統與現代的交融，讓人感受到文化的深厚底蘊。此外，漫畫類作品以其生動有趣的表現手法，傳遞了年輕人的觀察與思考，讓觀眾能在輕鬆愉快的氛圍中鱧驗藝術的魅力。此次展覽不僅是對學生們藝術才華的展示，更是他們創作熱情的體現。', '國立大甲高級工業職業學校', '臺中市大甲區', '2025-04-10 00:00:00', '2025-05-16 00:00:00', '大甲區（臺中市）=', 24.37827161, 120.6357901, '無資料', 'https://www.facebook.com/share/p/16SSW7Lfj3/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='藝享.異想-順天國小藝術才能美術班展', `description`='　　順天國小藝術才能美術班以人文關懷、創意實踐與生活美感的藝術教育，激發孩童多元適性發展，以「美力順天」為藝術才能美術班願景。培養兒童會做、會看、會想的能力，將藝術學習統整融入生活；透過藝術教育達到全人教育日標，培植美術才能表現優秀學生；促進學生認識藝術價值，學習尊重與關懷，透過藝術創意表現充分展現自我、合作學習，以深耕藝術基礎教育與藝術华根之教育理念。\r\n　　順天國小藝術才能美術班提供多元化之學習，以藝術的內涵與學習營造社區美感活動課程，透過參觀美術館、博物館等，增廣見聞並提升審美之情操。\r\n理解在地文化與中外文化藝術的內涵與特色，並於生活中具疆實踐，鼓勵學生多參與各項美術活動，以增加創作經驗。\r\n　　順天國小藝術才能美術班學生作品，展示了學生們豐富多樣的創作成果。\r\n　　此次作品展覽精心策劃，包含多種類型作品，如大型自盡像、平面設計、精美版畫、水墨盡，以及各式繪盡與漫畫類作品。每件作品都獨具匠心，融合了創意與技術，展現了學生們在創作過程中不斷探索與試驗的精神。大型自畫像不僅呈現了藝術家的個性，更是他們內心世界的真實寫照；平面設計作品則展示了視覺傳達的魅力，凸顯了功能與美感的完美結合；而版畫和水墨畫則承載著傳統與現代的交融，讓人感受到文化的深厚底蘊。此外，漫畫類作品以其生動有趣的表現手法，傳遞了年輕人的觀察與思考，讓觀眾能在輕鬆愉快的氛圍中鱧驗藝術的魅力。此次展覽不僅是對學生們藝術才華的展示，更是他們創作熱情的體現。', `organizer`='國立大甲高級工業職業學校', `address`='臺中市大甲區', `start_date`='2025-04-10 00:00:00', `end_date`='2025-05-16 00:00:00', `location`='大甲區（臺中市）=', `latitude`=24.37827161, `longitude`=120.6357901, `ticket_price`='無資料', `source_url`='https://www.facebook.com/share/p/16SSW7Lfj3/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b7f26b3242b74a3b1e9', '微光夜遊音樂會', '生活在音符迴盪間，打開夜的美術館！\r\n\r\n抓住春的尾巴，在夜幕之下感受一場跨越時空的藝術音樂之旅。\r\n當自然的聲音與音樂交織在一起，無疑會引發一場奇妙的聽覺饗宴。由手碟演奏家陳沛元及植作發聲計畫蔡瑋德Nick Tsai共同演出，融合手碟獨特的清脆音色與植物自然發出的聲音，創造出一個超越現實的音樂體驗。感受自然的脈動與和諧共鳴，每一個音符都是從大地深處傳來的低語，這不僅是一場音樂會，更是一場探索生命與自然和諧的心靈旅程。', '陸府生活美學教育基金會', '臺中市南屯區', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '南屯區（臺中市）=', 24.14165524, 120.6177379, '全票+450', 'https://live-forever.com.tw/activity-content.php?page=1&index_id=344', '[]') ON DUPLICATE KEY UPDATE `activity_name`='微光夜遊音樂會', `description`='生活在音符迴盪間，打開夜的美術館！\r\n\r\n抓住春的尾巴，在夜幕之下感受一場跨越時空的藝術音樂之旅。\r\n當自然的聲音與音樂交織在一起，無疑會引發一場奇妙的聽覺饗宴。由手碟演奏家陳沛元及植作發聲計畫蔡瑋德Nick Tsai共同演出，融合手碟獨特的清脆音色與植物自然發出的聲音，創造出一個超越現實的音樂體驗。感受自然的脈動與和諧共鳴，每一個音符都是從大地深處傳來的低語，這不僅是一場音樂會，更是一場探索生命與自然和諧的心靈旅程。', `organizer`='陸府生活美學教育基金會', `address`='臺中市南屯區', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='南屯區（臺中市）=', `latitude`=24.14165524, `longitude`=120.6177379, `ticket_price`='全票+450', `source_url`='https://live-forever.com.tw/activity-content.php?page=1&index_id=344', `image_url`='[]';
