INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8426b3242b74a3b1ec', '【新北市立圖書館萬里分館】《閱讀書籤》5月主題書展', '「致敬每一個為生活努力的人」\r\n書展期間：5/01-5/08\r\n書展簡介：\r\n致敬每一個為生活而努力的人！人生之旅，終要保有一份努力去發現自己生命的意義和價值，但同時也要保有一份努力之外的從容和豁達，去感受和珍惜每一個瞬間。生活不會辜負每一個努力的人，那些走錯的路，那些經歷的挫折，那些滴下的汗水，都會讓你成為獨一無二的自己，一起邁向美好的未來吧！\r\n\r\n「我的媽媽最棒了」\r\n書展期間：5/09-5/16\r\n書展簡介：\r\n我的媽媽是這個世界上最愛我的人，也是這世界上對我最好的人，在我生病難受時會照顧我，在我情緒低落時會安慰我，在我找不到未來方會指點我，不論何時何處都能得到愛的回應，她所給予的溫情讓我感到安心，並且能夠以相同的方式去愛身邊的人，她是最偉大的母親！我永遠愛妳。\r\n\r\n「認識不同的彼此」\r\n書展期間：5/17-5/24\r\n書展簡介：\r\n在青春期中會有各式各樣的疑問這在期間會遇見各種不同的變化像是「我的身體怎麼了？」、「為什麼聲音變得好奇怪？」、「生理期一定要來嗎？」、「粉紅色是女生的顏色？」。從青春期的身體到心理變化，樹立正確性觀念，打破傳統迷思。一同來認識寶貴的身體和心理，輕鬆度過青春期。\r\n\r\n「龍粽登場!」\r\n書展期間：5/25-5/30\r\n書展簡介：\r\n「龍」是端午節的代表，象徵著力量與智慧；而「粽子」則是端午的傳統美食，承載著對親情、友情與愛的祝福。透過書籍，我們在這個端午節，既可以傳承文化，深入了解端午的起源，也能獲得現代生活中的智慧，讓「龍粽」帶領我們走進知識的世界。\r\n\r\n\r\n\r\n\r\n\r\n', '新北市立圖書館總館', '新北市萬里區瑪鍊路221號4樓', '2025-05-01 00:00:00', '2025-05-30 00:00:00', '新北市立圖書館萬里分館', 25.17572457, 121.6439307, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館萬里分館】《閱讀書籤》5月主題書展', `description`='「致敬每一個為生活努力的人」\r\n書展期間：5/01-5/08\r\n書展簡介：\r\n致敬每一個為生活而努力的人！人生之旅，終要保有一份努力去發現自己生命的意義和價值，但同時也要保有一份努力之外的從容和豁達，去感受和珍惜每一個瞬間。生活不會辜負每一個努力的人，那些走錯的路，那些經歷的挫折，那些滴下的汗水，都會讓你成為獨一無二的自己，一起邁向美好的未來吧！\r\n\r\n「我的媽媽最棒了」\r\n書展期間：5/09-5/16\r\n書展簡介：\r\n我的媽媽是這個世界上最愛我的人，也是這世界上對我最好的人，在我生病難受時會照顧我，在我情緒低落時會安慰我，在我找不到未來方會指點我，不論何時何處都能得到愛的回應，她所給予的溫情讓我感到安心，並且能夠以相同的方式去愛身邊的人，她是最偉大的母親！我永遠愛妳。\r\n\r\n「認識不同的彼此」\r\n書展期間：5/17-5/24\r\n書展簡介：\r\n在青春期中會有各式各樣的疑問這在期間會遇見各種不同的變化像是「我的身體怎麼了？」、「為什麼聲音變得好奇怪？」、「生理期一定要來嗎？」、「粉紅色是女生的顏色？」。從青春期的身體到心理變化，樹立正確性觀念，打破傳統迷思。一同來認識寶貴的身體和心理，輕鬆度過青春期。\r\n\r\n「龍粽登場!」\r\n書展期間：5/25-5/30\r\n書展簡介：\r\n「龍」是端午節的代表，象徵著力量與智慧；而「粽子」則是端午的傳統美食，承載著對親情、友情與愛的祝福。透過書籍，我們在這個端午節，既可以傳承文化，深入了解端午的起源，也能獲得現代生活中的智慧，讓「龍粽」帶領我們走進知識的世界。\r\n\r\n\r\n\r\n\r\n\r\n', `organizer`='新北市立圖書館總館', `address`='新北市萬里區瑪鍊路221號4樓', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-30 00:00:00', `location`='新北市立圖書館萬里分館', `latitude`=25.17572457, `longitude`=121.6439307, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8526b3242b74a3b1ed', '【新北市立圖書館萬里分館】2025新北閱讀節系列活動：「享閱萬里-從書本到古蹟的文化對話」', '【新北市立圖書館萬里分館】2025新北閱讀節系列活動：「享閱萬里-從書本到古蹟的文化對話」\r\n課程時間：5/10（六）13:00-15:00\r\n課程地點：新北市立圖書館萬里分館／閱覽室（新北市萬里區瑪鋉路221號4樓）\r\n聯絡電話：02-2492-4490#12(電話/臨櫃/網路報名https://reurl.cc/eMDD0j)\r\n課程內容：\r\n搭配2025新北閱讀節辦理系列活動，隨著現代化的進程，許多珍貴的文化遺產和歷史古蹟面臨被遺忘或破壞的危機。然而，書籍作為文化傳承的重要載體，依然承擔著聯繫過去與現在的橋樑作用。本活動《享閱萬里-從書本到古蹟的文化對話》旨在透過書籍與古蹟之間的深度對話，探索書籍如何促進古蹟的文化理解與保護，並喚起大眾對歷史與文化遺產的重視。\r\n', '新北市立圖書館總館', '新北市萬里區瑪鍊路221號4樓', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '新北市立圖書館萬里分館', 25.17572457, 121.6439307, '無資料', 'https://reurl.cc/eMDD0j', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館萬里分館】2025新北閱讀節系列活動：「享閱萬里-從書本到古蹟的文化對話」', `description`='【新北市立圖書館萬里分館】2025新北閱讀節系列活動：「享閱萬里-從書本到古蹟的文化對話」\r\n課程時間：5/10（六）13:00-15:00\r\n課程地點：新北市立圖書館萬里分館／閱覽室（新北市萬里區瑪鋉路221號4樓）\r\n聯絡電話：02-2492-4490#12(電話/臨櫃/網路報名https://reurl.cc/eMDD0j)\r\n課程內容：\r\n搭配2025新北閱讀節辦理系列活動，隨著現代化的進程，許多珍貴的文化遺產和歷史古蹟面臨被遺忘或破壞的危機。然而，書籍作為文化傳承的重要載體，依然承擔著聯繫過去與現在的橋樑作用。本活動《享閱萬里-從書本到古蹟的文化對話》旨在透過書籍與古蹟之間的深度對話，探索書籍如何促進古蹟的文化理解與保護，並喚起大眾對歷史與文化遺產的重視。\r\n', `organizer`='新北市立圖書館總館', `address`='新北市萬里區瑪鍊路221號4樓', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='新北市立圖書館萬里分館', `latitude`=25.17572457, `longitude`=121.6439307, `ticket_price`='無資料', `source_url`='https://reurl.cc/eMDD0j', `image_url`='[]';
