INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8526b3242b74a3b1ef', '【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展', '「粒粒皆辛苦」\r\n書展期間：5/01-5/08\r\n書展簡介：\r\n無論是什麼職業，都有它困難、辛苦的地方，透過各行各業的配合，才構築出現今人們生活的社會，因此我們要感謝並珍惜他人的付出，更不可輕視或為任何職業評斷貴賤，趁著勞動節期間，來圖書館深入了解不曾認識過的各種職業吧！\r\n\r\n「媽咪，辛苦了！」\r\n書展期間：5/09-5/16\r\n書展簡介：\r\n屬於母親們的節日即將到來，也許一年當中只有這一天你會為母親慶祝，可母親卻是一年三百六十五天都在為孩子煩惱、愛著孩子。母愛的偉大無法用言語形容，趁著這時帶著最真誠的心，以行動表達自己的愛意吧，無論是帶著母親去吃大餐，或在家放鬆一整天，都別忘了說聲：謝謝，辛苦了！\r\n\r\n「生活處處是藝術」\r\n書展期間：5/17-5/24\r\n書展簡介：\r\n藝術存在於我們的日常當中，無論是建築、花草、環境，又或是一般的生活用品、文具，只要換個視角欣賞，都是藝術的不同呈現方式，也許有些藝術的形式是你從來沒認識過的，也或許有些事物你現在才意識到它是藝術世界的一環。不論如何，多多感受藝術，發現生活中的美好吧！\r\n\r\n「粽情粽義」\r\n書展期間：5/25-5/30\r\n書展簡介：\r\n「粽情粽義」，不只是包粽，更是包裹一層層的情感與故事；書籍也是如此，翻開每一頁，就像解開粽葉，裡面藏著溫暖、智慧與回憶。在端午佳節，用閱讀與人情味來相遇。\r\n', '新北市立圖書館總館', '新北市三芝區淡金路1段37號', '2025-05-01 00:00:00', '2025-05-30 00:00:00', '新北市立圖書館三芝分館', 25.23159891, 121.515558, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展', `description`='「粒粒皆辛苦」\r\n書展期間：5/01-5/08\r\n書展簡介：\r\n無論是什麼職業，都有它困難、辛苦的地方，透過各行各業的配合，才構築出現今人們生活的社會，因此我們要感謝並珍惜他人的付出，更不可輕視或為任何職業評斷貴賤，趁著勞動節期間，來圖書館深入了解不曾認識過的各種職業吧！\r\n\r\n「媽咪，辛苦了！」\r\n書展期間：5/09-5/16\r\n書展簡介：\r\n屬於母親們的節日即將到來，也許一年當中只有這一天你會為母親慶祝，可母親卻是一年三百六十五天都在為孩子煩惱、愛著孩子。母愛的偉大無法用言語形容，趁著這時帶著最真誠的心，以行動表達自己的愛意吧，無論是帶著母親去吃大餐，或在家放鬆一整天，都別忘了說聲：謝謝，辛苦了！\r\n\r\n「生活處處是藝術」\r\n書展期間：5/17-5/24\r\n書展簡介：\r\n藝術存在於我們的日常當中，無論是建築、花草、環境，又或是一般的生活用品、文具，只要換個視角欣賞，都是藝術的不同呈現方式，也許有些藝術的形式是你從來沒認識過的，也或許有些事物你現在才意識到它是藝術世界的一環。不論如何，多多感受藝術，發現生活中的美好吧！\r\n\r\n「粽情粽義」\r\n書展期間：5/25-5/30\r\n書展簡介：\r\n「粽情粽義」，不只是包粽，更是包裹一層層的情感與故事；書籍也是如此，翻開每一頁，就像解開粽葉，裡面藏著溫暖、智慧與回憶。在端午佳節，用閱讀與人情味來相遇。\r\n', `organizer`='新北市立圖書館總館', `address`='新北市三芝區淡金路1段37號', `start_date`='2025-05-01 00:00:00', `end_date`='2025-05-30 00:00:00', `location`='新北市立圖書館三芝分館', `latitude`=25.23159891, `longitude`=121.515558, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8526b3242b74a3b1f0', '繪畫/旅行-簡文仁油畫個展', '新北市新莊在地藝術家簡文仁即日起於新莊文化藝術中心舉辦「繪畫／旅行－簡文仁油畫個展」，展出70餘件作品，他多年來走過台灣各地，以畫筆紀錄台灣各地的人文風景，從壯麗山巒到湛藍海洋，從純樸鄉村到熱鬧街巷，細膩描繪這片土地的獨特風貌，邀請民眾透過藝術家的視角，一起走進台灣每個角落，感受他對家鄉的深情詮釋，展期至4月27日，歡迎前往欣賞。', '無資料', '新北市新莊區中平路133號', '2025-04-02 00:00:00', '2025-04-27 00:00:00', '新莊文化藝術中心', 25.0358303, 121.4367535, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='繪畫/旅行-簡文仁油畫個展', `description`='新北市新莊在地藝術家簡文仁即日起於新莊文化藝術中心舉辦「繪畫／旅行－簡文仁油畫個展」，展出70餘件作品，他多年來走過台灣各地，以畫筆紀錄台灣各地的人文風景，從壯麗山巒到湛藍海洋，從純樸鄉村到熱鬧街巷，細膩描繪這片土地的獨特風貌，邀請民眾透過藝術家的視角，一起走進台灣每個角落，感受他對家鄉的深情詮釋，展期至4月27日，歡迎前往欣賞。', `organizer`='無資料', `address`='新北市新莊區中平路133號', `start_date`='2025-04-02 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='新莊文化藝術中心', `latitude`=25.0358303, `longitude`=121.4367535, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8826b3242b74a3b1f1', '桐樂薈—114年新北市土城桐花祭藝術邀請展', '  傳承並發揚本區桐花祭以藝術展覽呈現人文精神的地方特色，特邀請39位藝術創作者，以「桐樂薈」為創作主題參與展出，將土城之人文風情、生態、地景、文化慶典…等為創作發想，透過水墨、水彩、陶瓷藝、書法、篆刻、油畫、蠟彩畫、版畫…等多元媒材表現，營造生活美學。\r\n 歡迎喜愛藝術創作同好蒞臨參觀。', '新北市土城區公所', '新北市土城區和平路24號', '2025-04-17 00:00:00', '2025-05-18 00:00:00', '土城藝文館', 24.96425102, 121.445737, '無資料', 'https://www.tucheng.ntpc.gov.tw/index.jsp', '[]') ON DUPLICATE KEY UPDATE `activity_name`='桐樂薈—114年新北市土城桐花祭藝術邀請展', `description`='  傳承並發揚本區桐花祭以藝術展覽呈現人文精神的地方特色，特邀請39位藝術創作者，以「桐樂薈」為創作主題參與展出，將土城之人文風情、生態、地景、文化慶典…等為創作發想，透過水墨、水彩、陶瓷藝、書法、篆刻、油畫、蠟彩畫、版畫…等多元媒材表現，營造生活美學。\r\n 歡迎喜愛藝術創作同好蒞臨參觀。', `organizer`='新北市土城區公所', `address`='新北市土城區和平路24號', `start_date`='2025-04-17 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='土城藝文館', `latitude`=24.96425102, `longitude`=121.445737, `ticket_price`='無資料', `source_url`='https://www.tucheng.ntpc.gov.tw/index.jsp', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8926b3242b74a3b1f2', '大鵬國小社區共讀站-Make Way for Ducklings(4月)', '4/18(五)晚上7:20辦理夜間說故事-「Make Way for Ducklings 讓路給小鴨子」，邀請家長與小朋友一起和野鴨夫妻展開都市冒險哦！\r\n建議大家可以提早10分鐘到圖書館來，找一個舒適的位置坐下來先看書、借書，好好享受夜間圖書館的寧靜氛圍!', '臺中市西屯區大鵬國民小學', '臺中市西屯區', '2025-04-18 00:00:00', '2025-04-18 00:00:00', '西屯區（臺中市）=', 24.18308895, 120.6270131, '無資料', 'https://www.facebook.com/photo/?fbid=1113966447412054&set=a.459979219477450', '[]') ON DUPLICATE KEY UPDATE `activity_name`='大鵬國小社區共讀站-Make Way for Ducklings(4月)', `description`='4/18(五)晚上7:20辦理夜間說故事-「Make Way for Ducklings 讓路給小鴨子」，邀請家長與小朋友一起和野鴨夫妻展開都市冒險哦！\r\n建議大家可以提早10分鐘到圖書館來，找一個舒適的位置坐下來先看書、借書，好好享受夜間圖書館的寧靜氛圍!', `organizer`='臺中市西屯區大鵬國民小學', `address`='臺中市西屯區', `start_date`='2025-04-18 00:00:00', `end_date`='2025-04-18 00:00:00', `location`='西屯區（臺中市）=', `latitude`=24.18308895, `longitude`=120.6270131, `ticket_price`='無資料', `source_url`='https://www.facebook.com/photo/?fbid=1113966447412054&set=a.459979219477450', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8926b3242b74a3b1f3', '府中15-邪惡根本不存在', '劇情簡介：\r\n一對住在東京近郊山村的父女，過著恬靜簡單、順應自然的平凡日子，直到村裡盛傳有開發商要將森林打造成豪華露營區，希望能讓居住在市區的男男女女有個可以逃離無聊日常的後花園。而這個為大家好的計畫看似能為村人帶來經濟效益，卻會破壞山林的生態環境，更將打亂居民的生活。', '新北市政府文化局', '新北市板橋區府中路15號', '2025-03-26 00:00:00', '2025-04-20 00:00:00', '府中15', 25.01186453, 121.4579675, '票價+20', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='府中15-邪惡根本不存在', `description`='劇情簡介：\r\n一對住在東京近郊山村的父女，過著恬靜簡單、順應自然的平凡日子，直到村裡盛傳有開發商要將森林打造成豪華露營區，希望能讓居住在市區的男男女女有個可以逃離無聊日常的後花園。而這個為大家好的計畫看似能為村人帶來經濟效益，卻會破壞山林的生態環境，更將打亂居民的生活。', `organizer`='新北市政府文化局', `address`='新北市板橋區府中路15號', `start_date`='2025-03-26 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='府中15', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='票價+20', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8926b3242b74a3b1f4', '府中15-虎紋少女', '劇情簡介：\r\n吒凡是個毫無拘束的活潑女孩，有一天，與同班同學聊起民間奇談「伊娜」的存在；她惡狠狠地坐落在樹梢看著那些即將「轉骨」的少女們，一旦碰見「伊娜」的少女似乎中邪般性情變得乖張、兇猛。本該迎向女性萌發新階段的吒凡，面對初經乍到卻總有種種不安與惶恐⋯⋯。', '新北市政府文化局', '新北市板橋區府中路15號', '2025-03-27 00:00:00', '2025-04-25 00:00:00', '府中15', 25.01186453, 121.4579675, '票價+20', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='府中15-虎紋少女', `description`='劇情簡介：\r\n吒凡是個毫無拘束的活潑女孩，有一天，與同班同學聊起民間奇談「伊娜」的存在；她惡狠狠地坐落在樹梢看著那些即將「轉骨」的少女們，一旦碰見「伊娜」的少女似乎中邪般性情變得乖張、兇猛。本該迎向女性萌發新階段的吒凡，面對初經乍到卻總有種種不安與惶恐⋯⋯。', `organizer`='新北市政府文化局', `address`='新北市板橋區府中路15號', `start_date`='2025-03-27 00:00:00', `end_date`='2025-04-25 00:00:00', `location`='府中15', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='票價+20', `source_url`='https://www.opentix.life/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8926b3242b74a3b1f5', '戶外時光影院(2場)', '𝟰/𝟮𝟲 ㊅  𝟏𝟕:𝟎𝟎  ➤  汪汪隊立大功：超級大電影\r\n𝟰/𝟮𝟳 ㊐  𝟏𝟕:𝟎𝟎  ➤  湯姆貓與傑利鼠\r\n與心愛的家人朋友一起在星空下為溫馨的週末畫下完美句點 .ᐟ', '大里藝術廣場 Dali Art Plaza ', '臺中市大里區', '2025-04-26 00:00:00', '2025-04-27 00:00:00', '大里區（臺中市）=', 24.09575742, 120.6926261, '無資料', 'https://www.facebook.com/photo?fbid=1086888193481321&set=pcb.1086888240147983', '[]') ON DUPLICATE KEY UPDATE `activity_name`='戶外時光影院(2場)', `description`='𝟰/𝟮𝟲 ㊅  𝟏𝟕:𝟎𝟎  ➤  汪汪隊立大功：超級大電影\r\n𝟰/𝟮𝟳 ㊐  𝟏𝟕:𝟎𝟎  ➤  湯姆貓與傑利鼠\r\n與心愛的家人朋友一起在星空下為溫馨的週末畫下完美句點 .ᐟ', `organizer`='大里藝術廣場 Dali Art Plaza ', `address`='臺中市大里區', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-27 00:00:00', `location`='大里區（臺中市）=', `latitude`=24.09575742, `longitude`=120.6926261, `ticket_price`='無資料', `source_url`='https://www.facebook.com/photo?fbid=1086888193481321&set=pcb.1086888240147983', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8926b3242b74a3b1f6', '府中15-老師！你會不會談戀愛【聽‧視界電影院】', '劇情簡介：\r\n補習班的數學男老師，對自己的人生振振有詞，卻是戀愛修羅場的超級白癡，於是決定聽從怪怪女學生的建議，練習追女生。從穿著、巧遇、搭訕、攻心，原來「正常人」的戀愛是這樣！女學生眼看老師越來越帥，似乎還動了真情，怪女孩卻發現她更想破壞的，是老師正在進行的戀愛。', '新北市政府文化局', '新北市板橋區府中路15號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '府中15', 25.01186453, 121.4579675, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='府中15-老師！你會不會談戀愛【聽‧視界電影院】', `description`='劇情簡介：\r\n補習班的數學男老師，對自己的人生振振有詞，卻是戀愛修羅場的超級白癡，於是決定聽從怪怪女學生的建議，練習追女生。從穿著、巧遇、搭訕、攻心，原來「正常人」的戀愛是這樣！女學生眼看老師越來越帥，似乎還動了真情，怪女孩卻發現她更想破壞的，是老師正在進行的戀愛。', `organizer`='新北市政府文化局', `address`='新北市板橋區府中路15號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='府中15', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8926b3242b74a3b1f7', '府中15-現成藝術', '劇情簡介：\r\n本片從《噴泉》神秘遺失開展剖繪，揭露現成藝術第一人，極可能是杜象所讚頌的「未來」，一名被遺忘的達達主義女藝術家洛琳霍芬男爵夫人！在小便斗簽上化名的人，是「他」還是「她」？全片攝製巧妙呼應「現成物」，犀利探討印象的破與立、創作的虛與實，引領觀眾思辨藝術的終極本質。', '新北市政府文化局', '新北市板橋區府中路15號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '府中15', 25.01186453, 121.4579675, '票價+20', 'https://www.opentix.life/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='府中15-現成藝術', `description`='劇情簡介：\r\n本片從《噴泉》神秘遺失開展剖繪，揭露現成藝術第一人，極可能是杜象所讚頌的「未來」，一名被遺忘的達達主義女藝術家洛琳霍芬男爵夫人！在小便斗簽上化名的人，是「他」還是「她」？全片攝製巧妙呼應「現成物」，犀利探討印象的破與立、創作的虛與實，引領觀眾思辨藝術的終極本質。', `organizer`='新北市政府文化局', `address`='新北市板橋區府中路15號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='府中15', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='票價+20', `source_url`='https://www.opentix.life/', `image_url`='[]';
