INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8a26b3242b74a3b1fb', '中興新村野起來─野餐MUSIC創生市集（音樂演出）', '音樂演出超豪華！14:00起連番上陣\r\n好樂團、八青哥、三巧奇工作室─下午揭開序幕\r\n梁文音、艾薇、ANGIE安吉、張語噥──超人氣卡司接力開唱，現場氣氛直衝最嗨時刻！\r\n拎著野餐墊，躺在草地上聽音樂，享受午後陽光到夜晚星空live歌唱魅力！', '國家發展委員會', '南投縣南投市光榮北路1號', '2025-05-03 00:00:00', '2025-05-03 00:00:00', '中興會堂', 23.9451121, 120.697287, '無資料', 'https://www.facebook.com/zrsi2021', '[]') ON DUPLICATE KEY UPDATE `activity_name`='中興新村野起來─野餐MUSIC創生市集（音樂演出）', `description`='音樂演出超豪華！14:00起連番上陣\r\n好樂團、八青哥、三巧奇工作室─下午揭開序幕\r\n梁文音、艾薇、ANGIE安吉、張語噥──超人氣卡司接力開唱，現場氣氛直衝最嗨時刻！\r\n拎著野餐墊，躺在草地上聽音樂，享受午後陽光到夜晚星空live歌唱魅力！', `organizer`='國家發展委員會', `address`='南投縣南投市光榮北路1號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-03 00:00:00', `location`='中興會堂', `latitude`=23.9451121, `longitude`=120.697287, `ticket_price`='無資料', `source_url`='https://www.facebook.com/zrsi2021', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8a26b3242b74a3b1fc', '南投縣114年度藝起同樂巡迴演出-名間鄉場：2025竹子動次打次~名間鄉竹音樂展演活動', '南投縣藝起同樂巡迴表演首場，由「竹鹿竹樂團」於名間鄉濁水福興宮廣場，準備以多種竹山在地的竹樂器及豐富的曲目，與大家「藝」起同樂！\r\n「竹鹿竹樂團」由團長羅凱元所成立，為竹山在地的竹音樂樂團，除了希望透過竹音樂來宣揚竹子之美，亦致力使竹音樂成為竹山文化特色，其樂器多出於竹山竹工藝師林錫裕之手，不僅樣式完整，品質優良，亦保有竹山竹工藝之美。樂團聘請台灣竹樂團副團長劉宗岳與陳思如老師為指導教師，以提升樂團表演品質，更致力於扎根推廣，為竹山開設竹樂器演奏推廣課程、竹樂器製作等推廣課程。\r\n樂團此次於藝起同樂巡迴表演，精心安排多首傳統民謠、客家小調、經典動畫歌曲及與宗教慶典相關的多首精彩曲目，而現場除了有演奏之外，亦安排竹片互動，讓民眾在欣賞之餘，還能一同體驗竹樂器與音樂的合奏饗宴，親自體驗竹子所帶來的音樂豐富趣味，與竹同樂的樂趣！是場相當適合親子闔家觀賞及體驗的竹音樂推廣活動，誠摯歡迎各位前往蒞臨觀賞！', '南投縣政府', '南投縣名間鄉', '2025-04-20 00:00:00', '2025-04-20 00:00:00', '名間鄉（南投縣）=', 23.8510771, 120.6774402, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='南投縣114年度藝起同樂巡迴演出-名間鄉場：2025竹子動次打次~名間鄉竹音樂展演活動', `description`='南投縣藝起同樂巡迴表演首場，由「竹鹿竹樂團」於名間鄉濁水福興宮廣場，準備以多種竹山在地的竹樂器及豐富的曲目，與大家「藝」起同樂！\r\n「竹鹿竹樂團」由團長羅凱元所成立，為竹山在地的竹音樂樂團，除了希望透過竹音樂來宣揚竹子之美，亦致力使竹音樂成為竹山文化特色，其樂器多出於竹山竹工藝師林錫裕之手，不僅樣式完整，品質優良，亦保有竹山竹工藝之美。樂團聘請台灣竹樂團副團長劉宗岳與陳思如老師為指導教師，以提升樂團表演品質，更致力於扎根推廣，為竹山開設竹樂器演奏推廣課程、竹樂器製作等推廣課程。\r\n樂團此次於藝起同樂巡迴表演，精心安排多首傳統民謠、客家小調、經典動畫歌曲及與宗教慶典相關的多首精彩曲目，而現場除了有演奏之外，亦安排竹片互動，讓民眾在欣賞之餘，還能一同體驗竹樂器與音樂的合奏饗宴，親自體驗竹子所帶來的音樂豐富趣味，與竹同樂的樂趣！是場相當適合親子闔家觀賞及體驗的竹音樂推廣活動，誠摯歡迎各位前往蒞臨觀賞！', `organizer`='南投縣政府', `address`='南投縣名間鄉', `start_date`='2025-04-20 00:00:00', `end_date`='2025-04-20 00:00:00', `location`='名間鄉（南投縣）=', `latitude`=23.8510771, `longitude`=120.6774402, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8a26b3242b74a3b1fd', '114年南投好客文化學院：客語薪傳師培訓研習', '為提升客語薪傳師專業知能、增進客語薪傳師傳習計畫成效，進而傳承並發揚客家文化，南投縣客家發展所辦理客語薪傳師培訓課程，提供本縣客語薪傳師學習及相互交流之機會。\r\n本次培訓內容包含「新媒體融入客語教學」及「主持人的高言值表達魔法」兩門課程，分別聘請「旅行空間」總監暨外語領隊邱羚瑜老師擔任「新媒體融入客語教學」課程之講師，從構思影片內容、基礎常用運鏡示範，到剪輯APP的介紹及實作，由專業講師帶領學員們實際操作，增進客語薪傳師影像拍攝、後製及教材製作能力，另聘請大漢之音廣播電台執行長張吟旖老師擔任「主持人的高言值表達魔法」課程之講師，以理論課程搭配實務演練，藉由此培訓課程，使參與者能夠更加精準地掌握表達要訣，學習主持技巧的表達模式。\r\n薪傳師培訓課程，強調以生動且多元化的形式應用於客語教學中，使參與者能增加自身技能，並讓教學更加豐富、提升辦理效益，鼓勵未曾參與培訓課程之客語薪傳師、外縣市之薪傳師或參與本土語教育支援人員參加。\r\n線上報名 https://forms.gle/3e4ryDf1zWXidPpU8 \r\n洽詢電話：049-2246421分機706 南投縣客家發展所。', '南投縣客家發展所', '南投縣南投市建國路135號', '2025-05-03 00:00:00', '2025-05-17 00:00:00', '南投縣政府文化局', 23.908225, 120.681559, '無資料', 'https://www.nthcc.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年南投好客文化學院：客語薪傳師培訓研習', `description`='為提升客語薪傳師專業知能、增進客語薪傳師傳習計畫成效，進而傳承並發揚客家文化，南投縣客家發展所辦理客語薪傳師培訓課程，提供本縣客語薪傳師學習及相互交流之機會。\r\n本次培訓內容包含「新媒體融入客語教學」及「主持人的高言值表達魔法」兩門課程，分別聘請「旅行空間」總監暨外語領隊邱羚瑜老師擔任「新媒體融入客語教學」課程之講師，從構思影片內容、基礎常用運鏡示範，到剪輯APP的介紹及實作，由專業講師帶領學員們實際操作，增進客語薪傳師影像拍攝、後製及教材製作能力，另聘請大漢之音廣播電台執行長張吟旖老師擔任「主持人的高言值表達魔法」課程之講師，以理論課程搭配實務演練，藉由此培訓課程，使參與者能夠更加精準地掌握表達要訣，學習主持技巧的表達模式。\r\n薪傳師培訓課程，強調以生動且多元化的形式應用於客語教學中，使參與者能增加自身技能，並讓教學更加豐富、提升辦理效益，鼓勵未曾參與培訓課程之客語薪傳師、外縣市之薪傳師或參與本土語教育支援人員參加。\r\n線上報名 https://forms.gle/3e4ryDf1zWXidPpU8 \r\n洽詢電話：049-2246421分機706 南投縣客家發展所。', `organizer`='南投縣客家發展所', `address`='南投縣南投市建國路135號', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='南投縣政府文化局', `latitude`=23.908225, `longitude`=120.681559, `ticket_price`='無資料', `source_url`='https://www.nthcc.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8a26b3242b74a3b1fe', '《雕塑家具－Sculpture Furniture》', '在充滿藝術氛圍的空間中，藝術家們以家具、光線、聲響做為溝通的語言，期待激盪出令人意想不到的美感經驗。', '國立臺南藝術大學', '臺南市官田區', '2025-04-19 00:00:00', '2025-06-08 00:00:00', '官田區（臺南市）=', 23.19098548, 120.3479918, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《雕塑家具－Sculpture Furniture》', `description`='在充滿藝術氛圍的空間中，藝術家們以家具、光線、聲響做為溝通的語言，期待激盪出令人意想不到的美感經驗。', `organizer`='國立臺南藝術大學', `address`='臺南市官田區', `start_date`='2025-04-19 00:00:00', `end_date`='2025-06-08 00:00:00', `location`='官田區（臺南市）=', `latitude`=23.19098548, `longitude`=120.3479918, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
