INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8a26b3242b74a3b200', '【新北市立圖書館蘆洲集賢分館】114年4月【影友會】', '4/01（二）幻土（輔）96分\r\n\r\n4/05（六）高年級實習生（護）122分\r\n\r\n4/08（二）飯捲男孩乖乖睡（輔）118分\r\n\r\n4/12（六）*酷巴：尋斑大冒險（普）85分   \r\n\r\n4/15（二）重綻光芒（普）84分\r\n\r\n4/19（六）天鼠探險隊（普）80分\r\n\r\n4/22（二）榮耀之路（護）113分\r\n\r\n4/26（六）*森林特攻隊：大腳ㄚ家族（普）89分\r\n\r\n4/29（二）我不是教你詐（輔）114分\r\n\r\n \r\n\r\n*為動畫片\r\n\r\n每周二、周六下午14:00起開始播放\r\n\r\n地點：蘆洲集賢分館7樓藝文中心視聽室\r\n\r\n活動單位保有取消變更之權利，詳情請依現場為主', '新北市立圖書館總館', '新北市蘆洲區集賢路245號', '2025-04-01 00:00:00', '2025-04-29 00:00:00', '新北市立圖書館蘆洲集賢分館（蘆洲藝文中心）', 25.08927173, 121.4712461, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館蘆洲集賢分館】114年4月【影友會】', `description`='4/01（二）幻土（輔）96分\r\n\r\n4/05（六）高年級實習生（護）122分\r\n\r\n4/08（二）飯捲男孩乖乖睡（輔）118分\r\n\r\n4/12（六）*酷巴：尋斑大冒險（普）85分   \r\n\r\n4/15（二）重綻光芒（普）84分\r\n\r\n4/19（六）天鼠探險隊（普）80分\r\n\r\n4/22（二）榮耀之路（護）113分\r\n\r\n4/26（六）*森林特攻隊：大腳ㄚ家族（普）89分\r\n\r\n4/29（二）我不是教你詐（輔）114分\r\n\r\n \r\n\r\n*為動畫片\r\n\r\n每周二、周六下午14:00起開始播放\r\n\r\n地點：蘆洲集賢分館7樓藝文中心視聽室\r\n\r\n活動單位保有取消變更之權利，詳情請依現場為主', `organizer`='新北市立圖書館總館', `address`='新北市蘆洲區集賢路245號', `start_date`='2025-04-01 00:00:00', `end_date`='2025-04-29 00:00:00', `location`='新北市立圖書館蘆洲集賢分館（蘆洲藝文中心）', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8a26b3242b74a3b201', '「工藝辦桌．文化饗宴」南投特別場', '「2024-2025年工藝遶境展」「工藝中心進駐工藝師特別場」隆重登場，由工藝中心114年生活工藝館進駐藝師擔任桌長，以桌面為展場、精彩工藝品為佳餚，開辦「工藝辦桌．文化饗宴」活動，由工藝師分享自己創作工藝品之想法與過程，滿足消費者全面了解工藝品的機會。\r\n2025年4月19日(星期六)，邀您品賞工藝之美～免費入席，歡迎預約報名，額滿為止\r\n\r\n報名時間：即日起至4月16日(三)23：59截止\r\n開放名額：42人\r\n報名方式：線上報名\r\n活動時間：2025.04.19(六) 14:00~16:00 (13:30報到入席)\r\n活動地點：國立臺灣工藝研究發展中心生活工藝館1F廣場\r\n票價說明：免費\r\n工藝中心為倡議「工藝活．活工藝」，讓人人生活有工藝，使工藝價值與精神能深入人心，設計以輕鬆下午茶的活工藝方式，集結各領域工藝師化身桌長，以桌面為展場、精彩工藝品為佳餚，開辦「工藝辦桌•文化饗宴」活動，由工藝師分享自已創作品之想法與過程，提供工藝師與民眾相互觀摩學習的場域，滿足消費者全面了解工藝品的機會。歡迎喜愛工藝的朋友們預約報名。\r\n114年4月19日(六)下午於生活工藝館1樓廣場，本次活動邀請114年生活工藝館「工藝體驗教學坊」進駐工藝師擔任桌長，邀請民眾參與，品賞工藝師精湛作品及創作故事。\r\n「藏知工坊」簡嘉儀老師，師承國寶藝師李榮烈，介紹竹編工藝與籃胎漆器技藝之精要；「金禾製造所」胡少中老師分享金屬工藝創作『物件』與『空間』之間的思考、「漆道坊」梁晊瑋老師，秉持『工藝，是日常生活的推延，它屬於生活的一部份』之精神，汲取各種生活事物作為創作元素；「樹藝工坊」李永謨老師，運用樹皮、葉脈、果實創造出各式各樣栩栩如生的昆蟲、動物、花卉；「蘿倫美學空間」葉千華老師為專業陶藝雕塑與版畫藝術家，致力於將工藝藝術融入日常生活，推廣陶藝與版畫創作；「安染工坊」劉俊卿老師，曾獲編織工藝獎生活工藝類、藝術創作類、臺灣工藝競賽傳統組入選、藍染流行創意服飾設計比賽客家花布組特優…等獎項，具有十餘年植物染教學及產品設計的工作經驗。\r\n4月19日（六）讓工藝師陪伴您體驗工藝辦桌的熱鬧場面，參與品賞精湛工藝作品及創作故事，近距離感受工藝創作的真切，以實際行動來支持工藝，增亮臺灣在地的工藝內涵及價值。鼓勵來賓穿戴或攜帶一件工藝品與會，以共襄盛舉。\r\n洽詢電話：049-2334141轉618柯小姐', '國立臺灣工藝研究發展中心', '南投縣草屯鎮中正路573號', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '國立臺灣工藝研究發展中心（臺灣工藝文化園區）', 23.9807747, 120.6918567, '無資料', 'https://event.culture.tw/mocweb/reg/NTCRI/Index.init.ctr?openExternalBrowser=1', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「工藝辦桌．文化饗宴」南投特別場', `description`='「2024-2025年工藝遶境展」「工藝中心進駐工藝師特別場」隆重登場，由工藝中心114年生活工藝館進駐藝師擔任桌長，以桌面為展場、精彩工藝品為佳餚，開辦「工藝辦桌．文化饗宴」活動，由工藝師分享自己創作工藝品之想法與過程，滿足消費者全面了解工藝品的機會。\r\n2025年4月19日(星期六)，邀您品賞工藝之美～免費入席，歡迎預約報名，額滿為止\r\n\r\n報名時間：即日起至4月16日(三)23：59截止\r\n開放名額：42人\r\n報名方式：線上報名\r\n活動時間：2025.04.19(六) 14:00~16:00 (13:30報到入席)\r\n活動地點：國立臺灣工藝研究發展中心生活工藝館1F廣場\r\n票價說明：免費\r\n工藝中心為倡議「工藝活．活工藝」，讓人人生活有工藝，使工藝價值與精神能深入人心，設計以輕鬆下午茶的活工藝方式，集結各領域工藝師化身桌長，以桌面為展場、精彩工藝品為佳餚，開辦「工藝辦桌•文化饗宴」活動，由工藝師分享自已創作品之想法與過程，提供工藝師與民眾相互觀摩學習的場域，滿足消費者全面了解工藝品的機會。歡迎喜愛工藝的朋友們預約報名。\r\n114年4月19日(六)下午於生活工藝館1樓廣場，本次活動邀請114年生活工藝館「工藝體驗教學坊」進駐工藝師擔任桌長，邀請民眾參與，品賞工藝師精湛作品及創作故事。\r\n「藏知工坊」簡嘉儀老師，師承國寶藝師李榮烈，介紹竹編工藝與籃胎漆器技藝之精要；「金禾製造所」胡少中老師分享金屬工藝創作『物件』與『空間』之間的思考、「漆道坊」梁晊瑋老師，秉持『工藝，是日常生活的推延，它屬於生活的一部份』之精神，汲取各種生活事物作為創作元素；「樹藝工坊」李永謨老師，運用樹皮、葉脈、果實創造出各式各樣栩栩如生的昆蟲、動物、花卉；「蘿倫美學空間」葉千華老師為專業陶藝雕塑與版畫藝術家，致力於將工藝藝術融入日常生活，推廣陶藝與版畫創作；「安染工坊」劉俊卿老師，曾獲編織工藝獎生活工藝類、藝術創作類、臺灣工藝競賽傳統組入選、藍染流行創意服飾設計比賽客家花布組特優…等獎項，具有十餘年植物染教學及產品設計的工作經驗。\r\n4月19日（六）讓工藝師陪伴您體驗工藝辦桌的熱鬧場面，參與品賞精湛工藝作品及創作故事，近距離感受工藝創作的真切，以實際行動來支持工藝，增亮臺灣在地的工藝內涵及價值。鼓勵來賓穿戴或攜帶一件工藝品與會，以共襄盛舉。\r\n洽詢電話：049-2334141轉618柯小姐', `organizer`='國立臺灣工藝研究發展中心', `address`='南投縣草屯鎮中正路573號', `start_date`='2025-04-19 00:00:00', `end_date`='2025-04-19 00:00:00', `location`='國立臺灣工藝研究發展中心（臺灣工藝文化園區）', `latitude`=23.9807747, `longitude`=120.6918567, `ticket_price`='無資料', `source_url`='https://event.culture.tw/mocweb/reg/NTCRI/Index.init.ctr?openExternalBrowser=1', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8a26b3242b74a3b202', '陳英阿媽來講古', '恆春古往今來的大小事，經由人間國寶藝師 #陳英 低吟哼唱， 乘著月琴獨特的弦音，傳遞屬於半島的人文與土地的氣味。', '屏東縣文化資產保護所', '屏東縣屏東市青島街106號', '2025-05-17 00:00:00', '2025-05-17 00:00:00', '勝利星村創意生活園區V.I.P Zone', 22.6647375, 120.4799948, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='陳英阿媽來講古', `description`='恆春古往今來的大小事，經由人間國寶藝師 #陳英 低吟哼唱， 乘著月琴獨特的弦音，傳遞屬於半島的人文與土地的氣味。', `organizer`='屏東縣文化資產保護所', `address`='屏東縣屏東市青島街106號', `start_date`='2025-05-17 00:00:00', `end_date`='2025-05-17 00:00:00', `location`='勝利星村創意生活園區V.I.P Zone', `latitude`=22.6647375, `longitude`=120.4799948, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8a26b3242b74a3b203', '114年工藝校園扎根．種子教師培育計畫：手縫皮革托特包工作坊（5月14日13:00線上報名） ', '為推動工藝融入學校教育，促進工藝美學校園扎根，透過手作體驗課程，培育學校教師成為種子教師，並回到教學現場發展工藝體驗課程，傳遞工藝所能帶來的生活連結與美好體驗，誘發學生「動手做工藝」的學習興趣，開啟工藝與教育融合共好的無限可能性！\r\n授課講師：王慕賢老師，吾革事皮藝工坊負責人。\r\n課程內容：\r\n皮革工藝需要長時間的製作與學習，本課程透過手縫皮革托特包的製作，學習皮革工藝完整流程步驟，由紙型製作、皮革裁切、打孔、染色、雕刻、縫合等實務操作，完成一件實用皮革作品，版型亦可再重複使用製作。\r\n研習時數：全程參訓者核給研習時數 28 小時，並發給結業證書。如有請假者則依實際上課時數核給研習時數，惟請假超過 4 小時者，則不發給結業證書。 \r\n招生對象：幼稚園、國小、國中及高級中等學校之教師\r\n招收人數：20人(6人開班)\r\n報名方式：於5/14（三）下午1點起在【全國教師在職進修資訊網】線上報名。【課程代碼：4980727】\r\n錄取方式：為落實工藝校園扎根政策推動所需，主辦單位得保留一半名額供本中心培育之種子教師課程實踐者或具有工藝校園扎根潛力者優先錄取（需回填學習動機以及教學實踐成果，俾利審核），其餘名額則依報名優先順序錄取，錄取名單請至【全國教師在職進修資訊網】查詢。\r\n洽詢專線：049-2334141*312張小姐', '國立臺灣工藝研究發展中心', '南投縣草屯鎮中正路573號', '2025-06-14 00:00:00', '2025-06-22 00:00:00', '國立臺灣工藝研究發展中心（臺灣工藝文化園區）', 23.9807747, 120.6918567, '學雜費+588;材料費+2300', 'https://www.ntcri.gov.tw/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年工藝校園扎根．種子教師培育計畫：手縫皮革托特包工作坊（5月14日13:00線上報名） ', `description`='為推動工藝融入學校教育，促進工藝美學校園扎根，透過手作體驗課程，培育學校教師成為種子教師，並回到教學現場發展工藝體驗課程，傳遞工藝所能帶來的生活連結與美好體驗，誘發學生「動手做工藝」的學習興趣，開啟工藝與教育融合共好的無限可能性！\r\n授課講師：王慕賢老師，吾革事皮藝工坊負責人。\r\n課程內容：\r\n皮革工藝需要長時間的製作與學習，本課程透過手縫皮革托特包的製作，學習皮革工藝完整流程步驟，由紙型製作、皮革裁切、打孔、染色、雕刻、縫合等實務操作，完成一件實用皮革作品，版型亦可再重複使用製作。\r\n研習時數：全程參訓者核給研習時數 28 小時，並發給結業證書。如有請假者則依實際上課時數核給研習時數，惟請假超過 4 小時者，則不發給結業證書。 \r\n招生對象：幼稚園、國小、國中及高級中等學校之教師\r\n招收人數：20人(6人開班)\r\n報名方式：於5/14（三）下午1點起在【全國教師在職進修資訊網】線上報名。【課程代碼：4980727】\r\n錄取方式：為落實工藝校園扎根政策推動所需，主辦單位得保留一半名額供本中心培育之種子教師課程實踐者或具有工藝校園扎根潛力者優先錄取（需回填學習動機以及教學實踐成果，俾利審核），其餘名額則依報名優先順序錄取，錄取名單請至【全國教師在職進修資訊網】查詢。\r\n洽詢專線：049-2334141*312張小姐', `organizer`='國立臺灣工藝研究發展中心', `address`='南投縣草屯鎮中正路573號', `start_date`='2025-06-14 00:00:00', `end_date`='2025-06-22 00:00:00', `location`='國立臺灣工藝研究發展中心（臺灣工藝文化園區）', `latitude`=23.9807747, `longitude`=120.6918567, `ticket_price`='學雜費+588;材料費+2300', `source_url`='https://www.ntcri.gov.tw/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8a26b3242b74a3b204', '國際口足畫家楊恩典老師「畫中有話」畫展', '此次畫作主視覺為寧靜的山水之間群鶴聚集，「鶴」寓意吉祥與長壽，也與閩南語「好」發音相似，希望藉由「畫中有話」創作情境，讓創作者成為說故事的人，傳遞勇氣和希望，讓每個人都能在困境中找到自己的光亮，分享生命故事，把最真實的感動和正能量傳達出去。\r\n口足畫家楊恩典雖然出生時就沒有雙臂，但並未因此放棄對藝術的熱愛與追求，早年在蔣故總統經國先生的鼓勵下，以非凡的毅力及努力克服障礙，先後向楊鄂西等名師習畫，展現無與倫比的創作才華，成為國際知名口足畫家，2007年獲選十大傑出青年，其故事鼓舞了無數台灣人，更曾於美國舉辦巡迴畫展。\r\n此次畫展，除了展出楊恩典的傳統國畫，以壓克力所繪製的包包外，也展出在木盤、絹扇等不同器物上創作的作品，跳脫傳統思維，將藝術融入生活，來展現不同於畫框內的呈現方式。', '交通部觀光署日月潭國家風景區管理處', '南投縣魚池鄉中山路', '2025-04-04 00:00:00', '2025-06-29 00:00:00', '日月潭國家風景區', 23.8565133, 120.9021315, '無資料', 'https://www.facebook.com/sunmoonlaketw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='國際口足畫家楊恩典老師「畫中有話」畫展', `description`='此次畫作主視覺為寧靜的山水之間群鶴聚集，「鶴」寓意吉祥與長壽，也與閩南語「好」發音相似，希望藉由「畫中有話」創作情境，讓創作者成為說故事的人，傳遞勇氣和希望，讓每個人都能在困境中找到自己的光亮，分享生命故事，把最真實的感動和正能量傳達出去。\r\n口足畫家楊恩典雖然出生時就沒有雙臂，但並未因此放棄對藝術的熱愛與追求，早年在蔣故總統經國先生的鼓勵下，以非凡的毅力及努力克服障礙，先後向楊鄂西等名師習畫，展現無與倫比的創作才華，成為國際知名口足畫家，2007年獲選十大傑出青年，其故事鼓舞了無數台灣人，更曾於美國舉辦巡迴畫展。\r\n此次畫展，除了展出楊恩典的傳統國畫，以壓克力所繪製的包包外，也展出在木盤、絹扇等不同器物上創作的作品，跳脫傳統思維，將藝術融入生活，來展現不同於畫框內的呈現方式。', `organizer`='交通部觀光署日月潭國家風景區管理處', `address`='南投縣魚池鄉中山路', `start_date`='2025-04-04 00:00:00', `end_date`='2025-06-29 00:00:00', `location`='日月潭國家風景區', `latitude`=23.8565133, `longitude`=120.9021315, `ticket_price`='無資料', `source_url`='https://www.facebook.com/sunmoonlaketw', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8a26b3242b74a3b205', '工藝故事屋（114年4月）', '「聽」是兒童吸收文化能量的重要管道，聽故事不僅充滿樂趣，且可激發兒童的創造思考能力，並與孩子分享正面的想法，培養正確的價值觀，型塑良好的品德。 小朋友在聽故事的過程中，透過故事經驗訊息的輸入與適性引導，學習正確的情緒抒發方式，並從中感受到愛與溫暖，進而健全兒童心理層面之發展，且從動手操作中，引導對工藝的認識及啟萌，使成長成為一位身心靈都健康的公民。 本活動於每週六上午及下午各辦理一場，在工藝資訊館2樓進行，不用報名，免費參加。\r\n活動對象：限國小(含)以下親子，需家長陪同', '國立臺灣工藝研究發展中心', '南投縣草屯鎮中正路573號', '2025-04-05 00:00:00', '2025-04-26 00:00:00', '國立臺灣工藝研究發展中心（臺灣工藝文化園區）', 23.9807747, 120.6918567, '無資料', 'https://www.ntcri.gov.tw/home/zh-tw', '[]') ON DUPLICATE KEY UPDATE `activity_name`='工藝故事屋（114年4月）', `description`='「聽」是兒童吸收文化能量的重要管道，聽故事不僅充滿樂趣，且可激發兒童的創造思考能力，並與孩子分享正面的想法，培養正確的價值觀，型塑良好的品德。 小朋友在聽故事的過程中，透過故事經驗訊息的輸入與適性引導，學習正確的情緒抒發方式，並從中感受到愛與溫暖，進而健全兒童心理層面之發展，且從動手操作中，引導對工藝的認識及啟萌，使成長成為一位身心靈都健康的公民。 本活動於每週六上午及下午各辦理一場，在工藝資訊館2樓進行，不用報名，免費參加。\r\n活動對象：限國小(含)以下親子，需家長陪同', `organizer`='國立臺灣工藝研究發展中心', `address`='南投縣草屯鎮中正路573號', `start_date`='2025-04-05 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='國立臺灣工藝研究發展中心（臺灣工藝文化園區）', `latitude`=23.9807747, `longitude`=120.6918567, `ticket_price`='無資料', `source_url`='https://www.ntcri.gov.tw/home/zh-tw', `image_url`='[]';
