INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8a26b3242b74a3b207', '2025南投星空季：清境星心相ing音樂趴', '節目內容：動力火車、清境國小擺夷舞蹈團、KMF極限火舞團、張家綸小提琴。\r\n\r\n亮點活動(17:00開始)\r\n星辰小集市：限量發送 100張$100市集券，憑5/10仁愛鄉任一店家消費滿$500之發票即可兌換。\r\n星辰下的秘密(闖關活動)：限量150位 參與簡單有趣的星座小遊戲，完成即可現場領取「星空幻境飲料杯套」，DIY燙印喜歡的布貼。\r\n太空裝體驗：大人小孩都可以免費體驗太空裝！（備有大人/小孩尺寸）。\r\n住清境換好禮：限量50位，憑5/10當日於清境地區住宿之發票，即可領取「絢爛星夜小提袋」。', '南投縣政府', '南投縣仁愛鄉', '2025-05-10 00:00:00', '2025-05-10 00:00:00', '仁愛鄉（南投縣）=', 24.02886513, 121.1443879, '無資料', 'https://www.rs-event.com.tw/2025NSNF/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025南投星空季：清境星心相ing音樂趴', `description`='節目內容：動力火車、清境國小擺夷舞蹈團、KMF極限火舞團、張家綸小提琴。\r\n\r\n亮點活動(17:00開始)\r\n星辰小集市：限量發送 100張$100市集券，憑5/10仁愛鄉任一店家消費滿$500之發票即可兌換。\r\n星辰下的秘密(闖關活動)：限量150位 參與簡單有趣的星座小遊戲，完成即可現場領取「星空幻境飲料杯套」，DIY燙印喜歡的布貼。\r\n太空裝體驗：大人小孩都可以免費體驗太空裝！（備有大人/小孩尺寸）。\r\n住清境換好禮：限量50位，憑5/10當日於清境地區住宿之發票，即可領取「絢爛星夜小提袋」。', `organizer`='南投縣政府', `address`='南投縣仁愛鄉', `start_date`='2025-05-10 00:00:00', `end_date`='2025-05-10 00:00:00', `location`='仁愛鄉（南投縣）=', `latitude`=24.02886513, `longitude`=121.1443879, `ticket_price`='無資料', `source_url`='https://www.rs-event.com.tw/2025NSNF/', `image_url`='[]';
