INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('68016b8b26b3242b74a3b20c', '2025省府單車騎遇記-舞台表演', '《省府單車騎遇記》今年迎來第七屆，跳脫以往的形式，帶來全新的單車生活×村落野餐體驗！讓我們一起乘著微風綠蔭，來場與大自然親密接觸的騎行之旅，還能品嚐當地特色美食，探索中興新村的獨特風光！\r\n主場地活動\r\n活動流程 \r\n10:00-10:30 開幕儀式\r\n10:30-11:30 舞台表演（一）\r\n11:00-12:00 DIY體驗（一）\r\n13:30-14:30 DIY體驗（二）\r\n14:30-15:30 舞台表演（二）\r\n15:30-16:30 舞台表演（三）\r\n16:30-17:00 單車騎遇記抽獎\r\n\r\n\r\n活動亮點\r\n單車騎遇記 - 單車闖關\r\n單車蚤之市 - 單車生活趣味闖關 \r\n任務集點，野餐食光 \r\n村落野餐 - 小村野時光\r\n草地尋寶 - 親子探險，解鎖驚喜任務\r\n預售票購買：https://reurl.cc/5K4XXG\r\n活動免費入場，但部分活動需預約報名，快來抓住這次與家人、朋友一起度過愉快一天的機會！\r\n一起來單車騎遇記，探索美麗村落，放鬆心情，享受美食與冒險吧', '南投縣中興新村商圈發展協會', '南投縣南投市', '2025-05-24 00:00:00', '2025-05-24 00:00:00', '南投市（南投縣）=', 23.92173537, 120.6787658, '無資料', 'https://www.facebook.com/nantouwelcome/', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025省府單車騎遇記-舞台表演', `description`='《省府單車騎遇記》今年迎來第七屆，跳脫以往的形式，帶來全新的單車生活×村落野餐體驗！讓我們一起乘著微風綠蔭，來場與大自然親密接觸的騎行之旅，還能品嚐當地特色美食，探索中興新村的獨特風光！\r\n主場地活動\r\n活動流程 \r\n10:00-10:30 開幕儀式\r\n10:30-11:30 舞台表演（一）\r\n11:00-12:00 DIY體驗（一）\r\n13:30-14:30 DIY體驗（二）\r\n14:30-15:30 舞台表演（二）\r\n15:30-16:30 舞台表演（三）\r\n16:30-17:00 單車騎遇記抽獎\r\n\r\n\r\n活動亮點\r\n單車騎遇記 - 單車闖關\r\n單車蚤之市 - 單車生活趣味闖關 \r\n任務集點，野餐食光 \r\n村落野餐 - 小村野時光\r\n草地尋寶 - 親子探險，解鎖驚喜任務\r\n預售票購買：https://reurl.cc/5K4XXG\r\n活動免費入場，但部分活動需預約報名，快來抓住這次與家人、朋友一起度過愉快一天的機會！\r\n一起來單車騎遇記，探索美麗村落，放鬆心情，享受美食與冒險吧', `organizer`='南投縣中興新村商圈發展協會', `address`='南投縣南投市', `start_date`='2025-05-24 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='南投市（南投縣）=', `latitude`=23.92173537, `longitude`=120.6787658, `ticket_price`='無資料', `source_url`='https://www.facebook.com/nantouwelcome/', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('879', '2025-2026雙年賞蝶', '茂林國家風景區位於高屏山區，長久以「紫蝶幽谷」特殊景象聞名國內外，亦為綠色米其林指南推薦三星生態景點。「雙年賞蝶」是每年11月開始至隔年3月在茂林國家風景區的重頭戲，此時，會有成千上萬的紫斑蝶遠渡重洋，來到此地棲息，形成壯觀的「紫蝶幽谷」生態現象。', '交通部觀光署茂林國家風景區管理處、高雄市政府、高雄市茂林區公所', '高雄市 茂林區茂林生態公園', '2025-11-01 00:00:00', '2026-03-31 00:00:00', '高雄市 茂林區茂林生態公園', 22.887377, 120.6631441, '無資料', '無資料', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081591/e40d51f57f505f5f30801d6662b9dc335da9a067.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025-2026雙年賞蝶', `description`='茂林國家風景區位於高屏山區，長久以「紫蝶幽谷」特殊景象聞名國內外，亦為綠色米其林指南推薦三星生態景點。「雙年賞蝶」是每年11月開始至隔年3月在茂林國家風景區的重頭戲，此時，會有成千上萬的紫斑蝶遠渡重洋，來到此地棲息，形成壯觀的「紫蝶幽谷」生態現象。', `organizer`='交通部觀光署茂林國家風景區管理處、高雄市政府、高雄市茂林區公所', `address`='高雄市 茂林區茂林生態公園', `start_date`='2025-11-01 00:00:00', `end_date`='2026-03-31 00:00:00', `location`='高雄市 茂林區茂林生態公園', `latitude`=22.887377, `longitude`=120.6631441, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081591/e40d51f57f505f5f30801d6662b9dc335da9a067.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('880', '2025-2026屏東落山風藝術季', '屏東落山風藝術季以車城海口港「落山風之吹風看海地」及旁邊沙灘為主要場地，以大型藝術裝置及表演活動形式，展現風與地方之特色。', '屏東縣政府傳播暨國際事務處', '屏東縣 車城鄉海口港看海美術館', '2025-12-01 00:00:00', '2026-03-31 00:00:00', '屏東縣 車城鄉海口港看海美術館', 22.0899521, 120.7152878, '無資料', 'https://www.facebook.com/lsf.arts?locale=zh_TW', '["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081423/cc82e8aef41694d75acbd3f7ac1e60b63620f398.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='2025-2026屏東落山風藝術季', `description`='屏東落山風藝術季以車城海口港「落山風之吹風看海地」及旁邊沙灘為主要場地，以大型藝術裝置及表演活動形式，展現風與地方之特色。', `organizer`='屏東縣政府傳播暨國際事務處', `address`='屏東縣 車城鄉海口港看海美術館', `start_date`='2025-12-01 00:00:00', `end_date`='2026-03-31 00:00:00', `location`='屏東縣 車城鄉海口港看海美術館', `latitude`=22.0899521, `longitude`=120.7152878, `ticket_price`='無資料', `source_url`='https://www.facebook.com/lsf.arts?locale=zh_TW', `image_url`='["https://cloud.culture.tw/e_new_upload/task/a66dc343-cd8b-4ee0-a265-8d7fff520c3b/C2_315080000H_081423/cc82e8aef41694d75acbd3f7ac1e60b63620f398.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9394434', '原住民親子談天活動', '本館為設籍臺北市原住民親子對天文的認識，規劃了適合親子共同參與的天文科學活動，內容有極光特展-遇見歐若菈介紹、欣賞宇宙劇場影片、特展導覽及搭乘宇宙探險車等活動，歡迎設籍臺北市的原住民親子一起參與學習天文科學。活動時間：5月18日（日）08:50-12:00。參加對象：設籍臺北市原住民親子（家庭成員中至少一位設籍臺北市具原住民身分），本活動為親子活動，每組報名需至少一位家長陪同參加，僅接受國小以上孩童報名。報名日期：4月29日（二）09:00起開放網路報名，一次最多登記4個名額，共60個名額，額滿為止。活動費用：免費。活動流程與其他注意事項：請參閱活動簡章。', '臺北市立天文科學教育館', '臺北市士林區基河路363號', '2025-05-18 00:00:00', '2025-05-18 00:00:00', '臺北天文館', 25.12546704, 121.5508473, '免費', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C7EF62D12D905047', '[]') ON DUPLICATE KEY UPDATE `activity_name`='原住民親子談天活動', `description`='本館為設籍臺北市原住民親子對天文的認識，規劃了適合親子共同參與的天文科學活動，內容有極光特展-遇見歐若菈介紹、欣賞宇宙劇場影片、特展導覽及搭乘宇宙探險車等活動，歡迎設籍臺北市的原住民親子一起參與學習天文科學。活動時間：5月18日（日）08:50-12:00。參加對象：設籍臺北市原住民親子（家庭成員中至少一位設籍臺北市具原住民身分），本活動為親子活動，每組報名需至少一位家長陪同參加，僅接受國小以上孩童報名。報名日期：4月29日（二）09:00起開放網路報名，一次最多登記4個名額，共60個名額，額滿為止。活動費用：免費。活動流程與其他注意事項：請參閱活動簡章。', `organizer`='臺北市立天文科學教育館', `address`='臺北市士林區基河路363號', `start_date`='2025-05-18 00:00:00', `end_date`='2025-05-18 00:00:00', `location`='臺北天文館', `latitude`=25.12546704, `longitude`=121.5508473, `ticket_price`='免費', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C7EF62D12D905047', `image_url`='[]';
