INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9394250', '財政部臺北國稅局協助宣傳113年度綜合所得稅結算申報措拖，如說明。', '財政部臺北國稅局協助宣傳113年度綜合所得稅結算申報措拖，如說明。宣導文句「113年度綜合所得稅結算申報自114年5月1日至6&nbsp;月30日，申報期間請多使用手機報稅，快速又方便」、「113年度綜合所得稅基本生活費調整為新臺幣210,000&nbsp;元」及「113年度綜合所得稅房屋租金支出改列特別扣除額，額度提高至新臺幣180,000元」。', '臺北市士林區健康服務中心', '無資料', '2025-04-18 00:00:00', '2025-06-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=95E4A14C9EF8BE25', '[]') ON DUPLICATE KEY UPDATE `activity_name`='財政部臺北國稅局協助宣傳113年度綜合所得稅結算申報措拖，如說明。', `description`='財政部臺北國稅局協助宣傳113年度綜合所得稅結算申報措拖，如說明。宣導文句「113年度綜合所得稅結算申報自114年5月1日至6&nbsp;月30日，申報期間請多使用手機報稅，快速又方便」、「113年度綜合所得稅基本生活費調整為新臺幣210,000&nbsp;元」及「113年度綜合所得稅房屋租金支出改列特別扣除額，額度提高至新臺幣180,000元」。', `organizer`='臺北市士林區健康服務中心', `address`='無資料', `start_date`='2025-04-18 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=95E4A14C9EF8BE25', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9390747', '星姊姊說故事【小翔和地球的故事】', '小翔和地球是好的朋友，但因為小翔的任性，導致地球病了，小翔到處尋找「活力能量丸」，想醫好地球，他能夠成功嗎？想瞭解故事並認識這顆人類居住的星球，請報名參加4月26日的活動，共享親子天文時光。活動時間：4月26日（六）14:00-15:00。活動對象：親子（幼稚園大班至國小三年級的孩童及其家長）。活動地點：展示場二樓兒童區。活動內容 : 熱場活動-故事時間-地球板塊設計DIY-小導覽(尋找展示場中的地球)。活動費用：免費。報名方式：線上報名注意事項：報名時只要填報參加兒童。購票參觀展示場即可免費參加活動（收費基準請參見購票資訊）。洽詢電話：02-28314551轉703展示組莊小姐。', '臺北市立天文科學教育館', '無資料', '2025-04-26 00:00:00', '2025-04-26 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=778A80F264158A15', '[]') ON DUPLICATE KEY UPDATE `activity_name`='星姊姊說故事【小翔和地球的故事】', `description`='小翔和地球是好的朋友，但因為小翔的任性，導致地球病了，小翔到處尋找「活力能量丸」，想醫好地球，他能夠成功嗎？想瞭解故事並認識這顆人類居住的星球，請報名參加4月26日的活動，共享親子天文時光。活動時間：4月26日（六）14:00-15:00。活動對象：親子（幼稚園大班至國小三年級的孩童及其家長）。活動地點：展示場二樓兒童區。活動內容 : 熱場活動-故事時間-地球板塊設計DIY-小導覽(尋找展示場中的地球)。活動費用：免費。報名方式：線上報名注意事項：報名時只要填報參加兒童。購票參觀展示場即可免費參加活動（收費基準請參見購票資訊）。洽詢電話：02-28314551轉703展示組莊小姐。', `organizer`='臺北市立天文科學教育館', `address`='無資料', `start_date`='2025-04-26 00:00:00', `end_date`='2025-04-26 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=778A80F264158A15', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9393811', '2025天母分館4-6月「心視界假日電影院」，歡迎蒞臨觀賞！', '新的一季即將到來～天母分館挑選來自日韓及美國的影集，適合各年齡的讀者欣賞。歡迎您相約家人朋友，假日來天母分館欣賞影片，共度美好時光。一、活動時間4-6，每月第1及第3週週日，下午2時起。二、播映場次4月06日：哪啊哪啊~神去村（普遍級，片長116分）4月20日：哆啦A夢:大雄與奇跡之島（普遍級，片長99分）5月04日：早安總統（普遍級，片長132分）5月18日：老爸行不行（普遍級，片長98分）6月01日：2分20秒（普遍級，片長90分）6月15日：飛吧! 蒲公英（普遍級，片長90分）三、活動地點天母分館4樓視聽室（請由館內3樓樓梯進入）（臺北市士林區中山北路7段154巷6號4樓）四、活動獎勵全程參與單一場次可獲得閱讀存摺點數5點。五、注意事項（一）本活動免費參加，入場請遵守影片分級制，請準時入場。（二）本館及視聽室內禁止飲食，並請將手機關機或靜音。（三）若有感冒症狀請配戴口罩，感謝您的合作。六、交通資訊&nbsp; &nbsp; https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=50DF61E26C3A0BFA&sms=CFFFC938B352678A七、洽詢管道（一）電話：02-28736203（二）Facebook粉絲專頁：https://www.facebook.com/tpmltianmulibrary/（三）IG：https://www.instagram.com/tianmulibrary/', '臺北市立圖書館', '無資料', '2025-04-18 00:00:00', '2025-06-15 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C0DECCA7BD108EA5', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025天母分館4-6月「心視界假日電影院」，歡迎蒞臨觀賞！', `description`='新的一季即將到來～天母分館挑選來自日韓及美國的影集，適合各年齡的讀者欣賞。歡迎您相約家人朋友，假日來天母分館欣賞影片，共度美好時光。一、活動時間4-6，每月第1及第3週週日，下午2時起。二、播映場次4月06日：哪啊哪啊~神去村（普遍級，片長116分）4月20日：哆啦A夢:大雄與奇跡之島（普遍級，片長99分）5月04日：早安總統（普遍級，片長132分）5月18日：老爸行不行（普遍級，片長98分）6月01日：2分20秒（普遍級，片長90分）6月15日：飛吧! 蒲公英（普遍級，片長90分）三、活動地點天母分館4樓視聽室（請由館內3樓樓梯進入）（臺北市士林區中山北路7段154巷6號4樓）四、活動獎勵全程參與單一場次可獲得閱讀存摺點數5點。五、注意事項（一）本活動免費參加，入場請遵守影片分級制，請準時入場。（二）本館及視聽室內禁止飲食，並請將手機關機或靜音。（三）若有感冒症狀請配戴口罩，感謝您的合作。六、交通資訊&nbsp; &nbsp; https://tpml.gov.taipei/News_Content.aspx?n=4F66F55F388033A7&s=50DF61E26C3A0BFA&sms=CFFFC938B352678A七、洽詢管道（一）電話：02-28736203（二）Facebook粉絲專頁：https://www.facebook.com/tpmltianmulibrary/（三）IG：https://www.instagram.com/tianmulibrary/', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-04-18 00:00:00', `end_date`='2025-06-15 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=C0DECCA7BD108EA5', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9390655', '總館北區資源中心x吳大猷書房-創客玩手作課程，歡迎參加！', '課程將帶領您手繪可愛麵包簡筆畫，輕鬆掌握繪圖技巧，並將設計變成專屬胸章，讓您的作品陪伴日常。此外，還有精心準備的音樂盒介紹與組裝體驗，了解音樂盒的構造與機械之美，感受音樂盒的魅力。活動全程免費，歡迎報名參加！一、活動內容及時間:播放影片日期課程內容活動對象5/24(六)10:00-12:00創客玩手作-可愛麵包簡筆畫及胸章製作一般民眾15名(學童須小學3年級以上)5/24(六)14:00-16:00創客玩手作-音樂盒介紹及組裝小學中年級親子10組，共20名(1名學童及1名家長為1組)二、活動地點:臺北市立圖書館總館11樓研習教室三、報名方式:(一)報名時間:5月7日上午10時起。(二)報名方式:線上報名1.可愛麵包簡筆畫及胸章製作2.音樂盒介紹及組裝四、注意事項:完成報名者請準時出席，課程開始10分鐘後不再開放入場，以免影響課程進行。※如有相關問題，歡迎電洽推廣課27552823轉2113張小姐', '臺北市立圖書館', '無資料', '2025-04-18 00:00:00', '2025-05-24 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=82A53DFBE8399867', '[]') ON DUPLICATE KEY UPDATE `activity_name`='總館北區資源中心x吳大猷書房-創客玩手作課程，歡迎參加！', `description`='課程將帶領您手繪可愛麵包簡筆畫，輕鬆掌握繪圖技巧，並將設計變成專屬胸章，讓您的作品陪伴日常。此外，還有精心準備的音樂盒介紹與組裝體驗，了解音樂盒的構造與機械之美，感受音樂盒的魅力。活動全程免費，歡迎報名參加！一、活動內容及時間:播放影片日期課程內容活動對象5/24(六)10:00-12:00創客玩手作-可愛麵包簡筆畫及胸章製作一般民眾15名(學童須小學3年級以上)5/24(六)14:00-16:00創客玩手作-音樂盒介紹及組裝小學中年級親子10組，共20名(1名學童及1名家長為1組)二、活動地點:臺北市立圖書館總館11樓研習教室三、報名方式:(一)報名時間:5月7日上午10時起。(二)報名方式:線上報名1.可愛麵包簡筆畫及胸章製作2.音樂盒介紹及組裝四、注意事項:完成報名者請準時出席，課程開始10分鐘後不再開放入場，以免影響課程進行。※如有相關問題，歡迎電洽推廣課27552823轉2113張小姐', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-04-18 00:00:00', `end_date`='2025-05-24 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=82A53DFBE8399867', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9393812', '臺北市農會建國假日花市114年6月農業櫥窗展出主題', '臺北市農會建國假日花市114年6月農業櫥窗展出主題臺北市建國假日花市114年6月份農業櫥窗展出主題內容如下：展&nbsp;出&nbsp;日&nbsp;期申&nbsp;請&nbsp;單&nbsp;位展&nbsp;出&nbsp;活&nbsp;動&nbsp;主&nbsp;題5月31日、6月1日北投區農會北投區花卉盆栽展售活動臺北市大安區農會大安區農會農特產品展售觀音區農會農特產品展售推廣活動雲林縣崙背鄉農會養蜂產銷班第一班雲林優良農產品聯合展售屏東縣枋山地區農會屏東縣枋山鄉芒果產品系列展售活動6月7、8日苗栗縣休閒農業發展協會苗栗縣休閒農業農特產品展售推廣活動台北市士林區山藥產銷班第一班陽明山山藥玉米濃湯推廣暨農特產品展彰化縣社頭鄉果樹產銷班第14班彰化縣優質蔬果農產品推廣促銷活動6月14、15日台北市農會供銷部優質農產品展示展售促銷暨『打造城市農園』廚餘不落地自製有機肥教學活動九如鄉花卉產銷班第二班食用玫瑰推廣6月21、22日士林區農會春季花展-蘭花、盆栽及農特產品展芬園鄉農會芬園鄉園鄉優質農產品展售促銷推廣活動6月28、29日溪州鄉農會溪州鄉農會「蔬菜、芭樂」農特產品展售關廟區農會鳳梨ㄟ故鄉「金佳蒂」優良農特產品展售大城鄉農會114年度國產安全農產品推廣活動其他本市產業活動及相關資訊請利用「臺北市政府產業發展局網站（網址：連結）」活動訊息、新聞稿或最新消息查詢。', '臺北市政府產業發展局', '無資料', '2025-04-17 00:00:00', '2025-06-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=034E05C8E8E100D5', '[]') ON DUPLICATE KEY UPDATE `activity_name`='臺北市農會建國假日花市114年6月農業櫥窗展出主題', `description`='臺北市農會建國假日花市114年6月農業櫥窗展出主題臺北市建國假日花市114年6月份農業櫥窗展出主題內容如下：展&nbsp;出&nbsp;日&nbsp;期申&nbsp;請&nbsp;單&nbsp;位展&nbsp;出&nbsp;活&nbsp;動&nbsp;主&nbsp;題5月31日、6月1日北投區農會北投區花卉盆栽展售活動臺北市大安區農會大安區農會農特產品展售觀音區農會農特產品展售推廣活動雲林縣崙背鄉農會養蜂產銷班第一班雲林優良農產品聯合展售屏東縣枋山地區農會屏東縣枋山鄉芒果產品系列展售活動6月7、8日苗栗縣休閒農業發展協會苗栗縣休閒農業農特產品展售推廣活動台北市士林區山藥產銷班第一班陽明山山藥玉米濃湯推廣暨農特產品展彰化縣社頭鄉果樹產銷班第14班彰化縣優質蔬果農產品推廣促銷活動6月14、15日台北市農會供銷部優質農產品展示展售促銷暨『打造城市農園』廚餘不落地自製有機肥教學活動九如鄉花卉產銷班第二班食用玫瑰推廣6月21、22日士林區農會春季花展-蘭花、盆栽及農特產品展芬園鄉農會芬園鄉園鄉優質農產品展售促銷推廣活動6月28、29日溪州鄉農會溪州鄉農會「蔬菜、芭樂」農特產品展售關廟區農會鳳梨ㄟ故鄉「金佳蒂」優良農特產品展售大城鄉農會114年度國產安全農產品推廣活動其他本市產業活動及相關資訊請利用「臺北市政府產業發展局網站（網址：連結）」活動訊息、新聞稿或最新消息查詢。', `organizer`='臺北市政府產業發展局', `address`='無資料', `start_date`='2025-04-17 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=034E05C8E8E100D5', `image_url`='[]';
