INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9393709', '北市稅處114年6月份節稅教室宣導活動', '一、本處於114年5月29日（星期四）晚上7:00~8:30舉辦「房地合一2.0報您知」課程，並於課程開始前(晚上6：20~6：50)舉辦捐雲端發票做公益租稅宣導活動。二、活動內容：(一)由本處代為捐贈下列張數之雲端發票，可兌換宣導品：1.雲端發票3張：「印花環保袋」1個。2.雲端發票10張：「櫸木餐具2件組」1個。3.雲端發票10張：「飪我行幸福餃好分隔盤8.75吋」1組。4.雲端發票25張：「飪我行日式簡約雙層飯盒」1個。註：雲端發票限114年5月未登打統一編號且交易金額10元以上，所募集之發票將全數捐贈公益慈善團體。宣導品數量有限，換完為止【每人限換2個】。(二)現場完成設定領獎帳戶或申請稅籍異動即時通服務或加入地方稅網路申報LINE臺北市會員，可獲得小禮物1份，數量有限，換完為止。聯絡人：企劃服務科陳小姐聯絡電話：23949211分機163', '臺北市稅捐稽徵處', '無資料', '2025-05-29 00:00:00', '2025-05-29 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=D4F00983D5AD7C44', '["https://www-ws.gov.taipei/001/Upload/336/relpic/31811/9393709/f0eb1b79-3809-4c29-8ea5-d6c3250dd2ef.png"]') ON DUPLICATE KEY UPDATE `activity_name`='北市稅處114年6月份節稅教室宣導活動', `description`='一、本處於114年5月29日（星期四）晚上7:00~8:30舉辦「房地合一2.0報您知」課程，並於課程開始前(晚上6：20~6：50)舉辦捐雲端發票做公益租稅宣導活動。二、活動內容：(一)由本處代為捐贈下列張數之雲端發票，可兌換宣導品：1.雲端發票3張：「印花環保袋」1個。2.雲端發票10張：「櫸木餐具2件組」1個。3.雲端發票10張：「飪我行幸福餃好分隔盤8.75吋」1組。4.雲端發票25張：「飪我行日式簡約雙層飯盒」1個。註：雲端發票限114年5月未登打統一編號且交易金額10元以上，所募集之發票將全數捐贈公益慈善團體。宣導品數量有限，換完為止【每人限換2個】。(二)現場完成設定領獎帳戶或申請稅籍異動即時通服務或加入地方稅網路申報LINE臺北市會員，可獲得小禮物1份，數量有限，換完為止。聯絡人：企劃服務科陳小姐聯絡電話：23949211分機163', `organizer`='臺北市稅捐稽徵處', `address`='無資料', `start_date`='2025-05-29 00:00:00', `end_date`='2025-05-29 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=D4F00983D5AD7C44', `image_url`='["https://www-ws.gov.taipei/001/Upload/336/relpic/31811/9393709/f0eb1b79-3809-4c29-8ea5-d6c3250dd2ef.png"]';
