INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9393479', '114年臺北市新人專屬，「幸福照相館」結婚登記寫真優惠來囉！', '為讓來辦理結婚登記的新人留下美好紀念的儀式感，臺北市各區戶政事務所發揮創意，設計各具特色的結婚拍照區，結合當地文化特色，或是媲美婚宴場地等級設計，就是要讓新人們拍好拍滿。如信義戶所以花卉結合簡約101大樓意象，營造時尚現代感。鄰近大安森林公園的大安戶所，則以豐富自然花卉元素，打造夢幻唯美的攝影場景。大同戶所則走在地人文風格，復刻大稻埕市定古蹟場景，充滿復古懷舊氣息。為鼓勵市民結婚，臺北市民政局與WeddingDay好婚市集特別合作推出「幸福照相館」結婚登記寫真優惠，凡即日起至114年底，至臺北市各區戶所結婚登記之新人，只要符合一方設籍本市資格，即可享用本優惠折扣方案，預約現在最夯的「結婚登記寫真」，讓攝影師在你人生最重要的幸福時刻，留下珍貴紀念！優惠組數無限制，詳細優惠內容及預約拍攝方式請見《臺北市鼓勵婚育專區》（https://reurl.cc/3KxDLL）此外，臺北市為打造友善幸福育兒城市，長期以來積極推動「助您好孕」專案，更優化推動「樂生助養好住」政策，全面提升對育兒家庭的支持與照顧！有計畫生育的新人，歡迎至臺北市助您好孕網站查詢相關育兒補助資訊(https://born.taipei/)。', '臺北市內湖區戶政事務所', '無資料', '2025-04-17 00:00:00', '2025-12-31 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=463B615E166F8BC6', '["https://www-ws.gov.taipei/001/Upload/426/relpic/31811/9393479/67749901-339a-4fd2-968e-a7780f41b50e.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='114年臺北市新人專屬，「幸福照相館」結婚登記寫真優惠來囉！', `description`='為讓來辦理結婚登記的新人留下美好紀念的儀式感，臺北市各區戶政事務所發揮創意，設計各具特色的結婚拍照區，結合當地文化特色，或是媲美婚宴場地等級設計，就是要讓新人們拍好拍滿。如信義戶所以花卉結合簡約101大樓意象，營造時尚現代感。鄰近大安森林公園的大安戶所，則以豐富自然花卉元素，打造夢幻唯美的攝影場景。大同戶所則走在地人文風格，復刻大稻埕市定古蹟場景，充滿復古懷舊氣息。為鼓勵市民結婚，臺北市民政局與WeddingDay好婚市集特別合作推出「幸福照相館」結婚登記寫真優惠，凡即日起至114年底，至臺北市各區戶所結婚登記之新人，只要符合一方設籍本市資格，即可享用本優惠折扣方案，預約現在最夯的「結婚登記寫真」，讓攝影師在你人生最重要的幸福時刻，留下珍貴紀念！優惠組數無限制，詳細優惠內容及預約拍攝方式請見《臺北市鼓勵婚育專區》（https://reurl.cc/3KxDLL）此外，臺北市為打造友善幸福育兒城市，長期以來積極推動「助您好孕」專案，更優化推動「樂生助養好住」政策，全面提升對育兒家庭的支持與照顧！有計畫生育的新人，歡迎至臺北市助您好孕網站查詢相關育兒補助資訊(https://born.taipei/)。', `organizer`='臺北市內湖區戶政事務所', `address`='無資料', `start_date`='2025-04-17 00:00:00', `end_date`='2025-12-31 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=463B615E166F8BC6', `image_url`='["https://www-ws.gov.taipei/001/Upload/426/relpic/31811/9393479/67749901-339a-4fd2-968e-a7780f41b50e.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9393470', '南港分處「2025復活節熱血公益嘉年華會」社區租稅暨政風宣導活動', '&nbsp;活動宣導資訊⇲&nbsp;活動時間：114年4月19日(星期六)10:00至13:00⇲&nbsp;活動地點：南興公園(南港區南港路一段360號對面)⇲&nbsp;活動內容：1.&nbsp; 現場完成下載統一發票兌獎APP、申請設定手機條碼、設定載具歸戶及領獎帳戶者可獲得宣導品1份。2.&nbsp; 捐贈指定張數之114年3-4月未書立統一編號且金額10元以上之雲端發票可兌換宣導品，數量有限換完為止。(活動所募發票全數捐予社福團體)。3.&nbsp; 宣導品兌換以現場實物為準，主辦單位保有修改或變更宣導品的權利。4.&nbsp; 現場每人限兌換3份，數量有限，兌完為止。臺北市稅捐稽徵處南港分處 誠摯邀請您共襄盛舉~聯絡人：南港分處李小姐聯絡電話：27834254分機314&nbsp;稅務宣導資訊1.人權大步走，生活更快活；人權兩公約請至人權大步走網頁查詢。2.落實性別平權，繼承和贈與不分性別。3.臺北市稅捐稽徵處各分處設置全功能自動化服務機，供民眾使用自然人/工商憑證、已註冊健保卡或身分證驗證QR-code（限上班時間使用），自助申請補發臺北市房屋稅、地價稅、使用牌照稅稅單、繳稅及申辦稅務案件，快速又便捷。4.北市電動汽機車免牌照稅至114年12月31日。5.對報停、繳銷或註銷(含逕行註銷)牌照車輛，於恢復使用前，請車主重新申領牌照、驗車等，以免因使用(停放)公共道路經查獲而受罰。6.臺北市稅捐稽徵處各分處提供民眾線上查詢被繼承人金融遺產及下載資料，並由國稅局統一回復，讓遺產稅申報更便利。自111年1月1日起，申請查詢被繼承人金融遺產一併提供「遺產稅申報稅額試算」及「延期申報」服務。7.北市稅處智能客服24小時服務不打烊！8.請民眾多加利用本處稅務視訊服務雲平臺、線上申辦管道、智慧客服或電話，申辦案件及諮詢。9.北市稅處創新建置「稅籍異動即時通」服務，讓您即時掌握不動產移轉動態，歡迎民眾申辦。10.本處開放非本人名義持有之信用卡繳納稅款及行動支付擴大繳稅項目。11.請多加利用各項E化繳稅管道(含行動支付、臨櫃信用卡、TW FidO、Line Pay等)及財政部擴大線上繳稅機制。12.歡迎申請以電子方式傳送地方稅繳款書、轉帳通知及繳納證明。13.直撥退稅安全迅速，申辦退稅提供本人存摺影本，或至本處網站直撥退稅線上回復帳戶資料。提醒您！稅捐機關不會請民眾利用ATM轉帳退稅喔！14.納稅者權利保護法施行，北市稅處設置納保官協助解決地方稅務紛爭。15.雲端發票好處多又中獎率高，請踴躍索取。16.國地稅雙語免付費服務電話：0800-000-321。', '臺北市稅捐稽徵處', '無資料', '2025-04-19 00:00:00', '2025-04-19 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=F32610E05DB2315C', '["https://www-ws.gov.taipei/001/Upload/336/relpic/31811/9393470/514c55ec-c4fe-403a-8c3d-a7cd3846ddba.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='南港分處「2025復活節熱血公益嘉年華會」社區租稅暨政風宣導活動', `description`='&nbsp;活動宣導資訊⇲&nbsp;活動時間：114年4月19日(星期六)10:00至13:00⇲&nbsp;活動地點：南興公園(南港區南港路一段360號對面)⇲&nbsp;活動內容：1.&nbsp; 現場完成下載統一發票兌獎APP、申請設定手機條碼、設定載具歸戶及領獎帳戶者可獲得宣導品1份。2.&nbsp; 捐贈指定張數之114年3-4月未書立統一編號且金額10元以上之雲端發票可兌換宣導品，數量有限換完為止。(活動所募發票全數捐予社福團體)。3.&nbsp; 宣導品兌換以現場實物為準，主辦單位保有修改或變更宣導品的權利。4.&nbsp; 