INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9382544', '墾丁南十字、春夏夜星空與生態之旅（報名請由此進入）', '活動時間：114年5月23日（星期五）至5月25日（星期日）三天兩夜。活動地點：水雉生態教育園區、青蛙石、港口白榕園、下坪熱帶植物園。參加對象：年滿十八歲以上對天文有興趣的民眾皆可參加。活動費用：每人新臺幣6,800元整。報名日期、方式：114年4月22日12：30開放網路登錄報名。 &nbsp;欲參加者請務必填寫資料，才有聯繫方式可通知您遞補為正取。錄取名額：錄取68名，額滿為止，額滿後登記者為候補人員。詳細行程、繳費方式及其他注意事項，請詳閱活動簡章。報名請點此 (4/22中午12:30開放報名)', '臺北市立天文科學教育館', '無資料', '2025-05-23 00:00:00', '2025-05-25 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=FEE60BF60F994150', '[]') ON DUPLICATE KEY UPDATE `activity_name`='墾丁南十字、春夏夜星空與生態之旅（報名請由此進入）', `description`='活動時間：114年5月23日（星期五）至5月25日（星期日）三天兩夜。活動地點：水雉生態教育園區、青蛙石、港口白榕園、下坪熱帶植物園。參加對象：年滿十八歲以上對天文有興趣的民眾皆可參加。活動費用：每人新臺幣6,800元整。報名日期、方式：114年4月22日12：30開放網路登錄報名。 &nbsp;欲參加者請務必填寫資料，才有聯繫方式可通知您遞補為正取。錄取名額：錄取68名，額滿為止，額滿後登記者為候補人員。詳細行程、繳費方式及其他注意事項，請詳閱活動簡章。報名請點此 (4/22中午12:30開放報名)', `organizer`='臺北市立天文科學教育館', `address`='無資料', `start_date`='2025-05-23 00:00:00', `end_date`='2025-05-25 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=FEE60BF60F994150', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9393335', '長安分館「華屋春暉居家裝潢布置」主題書展，歡迎借閱！', '　　讓住家成為讓人忘卻繁忙生活，回歸心靈的休憩角落！本次書展以室內設計、裝修、居家家飾、環境布置等國內外家居生活著作為選書主題。透過生動的圖片與文字，提供多樣選擇，讓您可以找到喜歡的方式重新規劃居家風格，打造溫暖美麗閒適的生活節奏。一、 &nbsp;活動時間：5月2日至6月30日二、 &nbsp;活動方式：挑選以室內設計、裝修、居家家飾、環境布置等以家居生活為主題的圖書，展示於主題書展區，並於臉書粉絲專頁介紹相關主題電子書。三、 &nbsp;活動地點：長安分館主題書展區（地址：臺北市中山區長安西路3號4樓[交通資訊連結]及臉書粉絲專頁[網站連結]）&nbsp;', '臺北市立圖書館', '無資料', '2025-04-16 00:00:00', '2025-06-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8CA98E13FD560ED0', '[]') ON DUPLICATE KEY UPDATE `activity_name`='長安分館「華屋春暉居家裝潢布置」主題書展，歡迎借閱！', `description`='　　讓住家成為讓人忘卻繁忙生活，回歸心靈的休憩角落！本次書展以室內設計、裝修、居家家飾、環境布置等國內外家居生活著作為選書主題。透過生動的圖片與文字，提供多樣選擇，讓您可以找到喜歡的方式重新規劃居家風格，打造溫暖美麗閒適的生活節奏。一、 &nbsp;活動時間：5月2日至6月30日二、 &nbsp;活動方式：挑選以室內設計、裝修、居家家飾、環境布置等以家居生活為主題的圖書，展示於主題書展區，並於臉書粉絲專頁介紹相關主題電子書。三、 &nbsp;活動地點：長安分館主題書展區（地址：臺北市中山區長安西路3號4樓[交通資訊連結]及臉書粉絲專頁[網站連結]）&nbsp;', `organizer`='臺北市立圖書館', `address`='無資料', `start_date`='2025-04-16 00:00:00', `end_date`='2025-06-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=8CA98E13FD560ED0', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9393106', '【梅居紫藤季｜紫藤花開．蔬食上桌】', '【梅居紫藤季｜紫藤花開．蔬食上桌】春天的陽明山，不只有海芋。藏在平菁街巷弄裡的「梅居休閒農場」，悄悄綻放出夢幻紫意。走進園區，串串紫藤沿著花架傾瀉而下，像是山林間低語的一場紫色細雨，浪漫又靜謐。&nbsp;這裡不只適合賞花，更是一處被認證的特色農業旅遊場域。農場提供無菜單蔬食料理，依照當季食材搭配設計菜色，不只是味蕾的體驗，更是一次從土地到餐桌的溫柔連結。&nbsp;🌿 一邊賞紫藤、聞香氣🥗 一邊享受用當季農產製作的蔬食佳餚🍵 如果時間允許，還可以安排園區導覽，走走看看香草植物與小農菜園&nbsp;梅居休閒農場INDEX：📍 台北市士林區平菁街43巷99號(搭乘303號公車至崙仔尾站)📞 採預約制，電話｜0905-169-176(連結)🕘 開放時間｜週三至週日 09:30&ndash;17:00（週一、二公休）🌸 紫藤花期｜即日起至4月中旬，建議趁花況最佳時前往！&nbsp;春天限定的紫色饗宴，邀你一起在梅居農場，賞花、吃菜、靜靜呼吸。', '臺北市政府產業發展局', '無資料', '2025-04-16 00:00:00', '2025-04-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=17DE6B59F20A3244', '["https://www-ws.gov.taipei/001/Upload/301/relpic/31811/9393106/fab893df-a380-40e3-9cc3-51fc53f6d030.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='【梅居紫藤季｜紫藤花開．蔬食上桌】', `description`='【梅居紫藤季｜紫藤花開．蔬食上桌】春天的陽明山，不只有海芋。藏在平菁街巷弄裡的「梅居休閒農場」，悄悄綻放出夢幻紫意。走進園區，串串紫藤沿著花架傾瀉而下，像是山林間低語的一場紫色細雨，浪漫又靜謐。&nbsp;這裡不只適合賞花，更是一處被認證的特色農業旅遊場域。農場提供無菜單蔬食料理，依照當季食材搭配設計菜色，不只是味蕾的體驗，更是一次從土地到餐桌的溫柔連結。&nbsp;🌿 一邊賞紫藤、聞香氣🥗 一邊享受用當季農產製作的蔬食佳餚🍵 如果時間允許，還可以安排園區導覽，走走看看香草植物與小農菜園&nbsp;梅居休閒農場INDEX：📍 台北市士林區平菁街43巷99號(搭乘303號公車至崙仔尾站)📞 採預約制，電話｜0905-169-176(連結)🕘 開放時間｜週三至週日 09:30&ndash;17:00（週一、二公休）🌸 紫藤花期｜即日起至4月中旬，建議趁花況最佳時前往！&nbsp;春天限定的紫色饗宴，邀你一起在梅居農場，賞花、吃菜、靜靜呼吸。', `organizer`='臺北市政府產業發展局', `address`='無資料', `start_date`='2025-04-16 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=17DE6B59F20A3244', `image_url`='["https://www-ws.gov.taipei/001/Upload/301/relpic/31811/9393106/fab893df-a380-40e3-9cc3-51fc53f6d030.jpg"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('9393105', '【福田園紅楓季｜四月限定的春日紅葉小徑】', '【福田園紅楓季｜四月限定的春日紅葉小徑】想看楓葉不一定要等秋天～你知道嗎？台北士林區的福田園教育休閒農場，四月正是「初猩猩」紅楓大放異彩的時候。園區內種植了上百棵來自日本的稀有紅楓品種，在這個季節，新葉轉紅、嫩芽染朱，形成一條夢幻的紅葉隧道，彷彿把春天也染上了溫柔的紅光。走進林蔭之中，每一張照片都像走進山裡的畫報風景。&nbsp;除了賞楓，福田園還有多種親子與體驗活動：🔹 藍染手作｜用天然植物染料，親手創造專屬作品🔹 香草餅乾DIY｜香氣撲鼻又療癒的春日點心時光🔹 桶仔雞團體餐｜最道地的農家風味，適合全家一起共享&nbsp;這裡不只是一處農場，更是認證的「休閒農業旅遊場域」，結合自然、食育與手作，讓你在輕旅行中體驗都市少見的農村魅力。&nbsp;福田園INDEX：📍地點｜台北市士林區菁山路131巷18號(搭乘303號公車至衛星電台站，走路10分鐘)🕘 營業時間｜週二至週日 09:00&ndash;17:00（週一公休）📲 建議提前電話或粉專預約!! 電話：02-2862-2145連結🍁 紅楓花期預估至5月初，把握最佳觀賞時機！&nbsp;如果你也想在四月的台北，來一場不一樣的賞楓體驗，那就出發福田園，與春天的紅葉撞個滿懷吧&nbsp;🌿🍁', '臺北市政府產業發展局', '無資料', '2025-04-16 00:00:00', '2025-04-30 00:00:00', '無資料', '無資料', '無資料', '無資料', 'https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=CC7C7390439A4202', '["https://www-ws.gov.taipei/001/Upload/301/relpic/31811/9393105/84dc59e4-1eed-480b-84f2-d20a6449f266.jpg"]') ON DUPLICATE KEY UPDATE `activity_name`='【福田園紅楓季｜四月限定的春日紅葉小徑】', `description`='【福田園紅楓季｜四月限定的春日紅葉小徑】想看楓葉不一定要等秋天～你知道嗎？台北士林區的福田園教育休閒農場，四月正是「初猩猩」紅楓大放異彩的時候。園區內種植了上百棵來自日本的稀有紅楓品種，在這個季節，新葉轉紅、嫩芽染朱，形成一條夢幻的紅葉隧道，彷彿把春天也染上了溫柔的紅光。走進林蔭之中，每一張照片都像走進山裡的畫報風景。&nbsp;除了賞楓，福田園還有多種親子與體驗活動：🔹 藍染手作｜用天然植物染料，親手創造專屬作品🔹 香草餅乾DIY｜香氣撲鼻又療癒的春日點心時光🔹 桶仔雞團體餐｜最道地的農家風味，適合全家一起共享&nbsp;這裡不只是一處農場，更是認證的「休閒農業旅遊場域」，結合自然、食育與手作，讓你在輕旅行中體驗都市少見的農村魅力。&nbsp;福田園INDEX：📍地點｜台北市士林區菁山路131巷18號(搭乘303號公車至衛星電台站，走路10分鐘)🕘 營業時間｜週二至週日 09:00&ndash;17:00（週一公休）📲 建議提前電話或粉專預約!! 電話：02-2862-2145連結🍁 紅楓花期預估至5月初，把握最佳觀賞時機！&nbsp;如果你也想在四月的台北，來一場不一樣的賞楓體驗，那就出發福田園，與春天的紅葉撞個滿懷吧&nbsp;🌿🍁', `organizer`='臺北市政府產業發展局', `address`='無資料', `start_date`='2025-04-16 00:00:00', `end_date`='2025-04-30 00:00:00', `location`='無資料', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='https://www.gov.taipei/News_Content.aspx?n=B1167F83E1FE0CD9&s=CC7C7390439A4202', `image_url`='["https://www-ws.gov.taipei/001/Upload/301/relpic/31811/9393105/84dc59e4-1eed-480b-84f2-d20a6449f266.jpg"]';
