INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('155967bf9a7eabf269acf97d2b712ecc', '「未辦繼承＆不動產防詐」　主題式地政專車出發囉!', '新北市瑞芳地政事務所「地政專車」行動服務即將出發服務囉!分別為4月21日(一)下午2時至4時在新北市瑞芳明燈公共托老中心及4月25日(五)上午9點至11點在貢寮區澳底公有零售市場1樓24號攤位作定點服務，宣導主題為「未辦繼承登記」及「不動產防詐」，歡迎市民朋友多加利用。', '新北市瑞芳地政事務所', '新北市瑞芳區明燈路三段2號2樓', '新北市瑞芳明燈公共托老中心', 25.0981293, 121.8232018, '無資料', '無資料', '["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504170158500.jpg&filedisplay=114%E5%AD%B8%E5%B9%B4%E5%BA%A6%E9%80%86%E9%A2%A8%E5%B0%91%E5%B9%B4%E6%95%99%E8%82%B2%E5%8A%A9%E5%AD%B8%E8%A8%88%E5%8A%83.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504170158501.jpg&filedisplay=114%E5%AD%B8%E5%B9%B4%E5%BA%A6%E9%80%86%E9%A2%A8%E5%B0%91%E5%B9%B4%E6%95%99%E8%82%B2%E5%8A%A9%E5%AD%B8%E8%A8%88%E5%8A%83-%E5%A0%B1%E5%90%8D%E7%94%B3%E8%AB%8B%E8%AA%AA%E6%98%8E%E6%9C%83.jpg&flag=pic"]') ON DUPLICATE KEY UPDATE `activity_name`='「未辦繼承＆不動產防詐」　主題式地政專車出發囉!', `description`='新北市瑞芳地政事務所「地政專車」行動服務即將出發服務囉!分別為4月21日(一)下午2時至4時在新北市瑞芳明燈公共托老中心及4月25日(五)上午9點至11點在貢寮區澳底公有零售市場1樓24號攤位作定點服務，宣導主題為「未辦繼承登記」及「不動產防詐」，歡迎市民朋友多加利用。', `organizer`='新北市瑞芳地政事務所', `address`='新北市瑞芳區明燈路三段2號2樓', `location`='新北市瑞芳明燈公共托老中心', `latitude`=25.0981293, `longitude`=121.8232018, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504170158500.jpg&filedisplay=114%E5%AD%B8%E5%B9%B4%E5%BA%A6%E9%80%86%E9%A2%A8%E5%B0%91%E5%B9%B4%E6%95%99%E8%82%B2%E5%8A%A9%E5%AD%B8%E8%A8%88%E5%8A%83.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504170158501.jpg&filedisplay=114%E5%AD%B8%E5%B9%B4%E5%BA%A6%E9%80%86%E9%A2%A8%E5%B0%91%E5%B9%B4%E6%95%99%E8%82%B2%E5%8A%A9%E5%AD%B8%E8%A8%88%E5%8A%83-%E5%A0%B1%E5%90%8D%E7%94%B3%E8%AB%8B%E8%AA%AA%E6%98%8E%E6%9C%83.jpg&flag=pic"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('155967bf9a7eabf2e98437f395c53b02', '114年第1場「遊艇午茶十三行」單身聯誼活動', '團康活動、大地活動及換桌等多種互動遊戲', '新北市政府民政局', '新北市八里區博物館路200號', '新北市立十三行博物館', 25.13812763, 121.4138359, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='114年第1場「遊艇午茶十三行」單身聯誼活動', `description`='團康活動、大地活動及換桌等多種互動遊戲', `organizer`='新北市政府民政局', `address`='新北市八里區博物館路200號', `location`='新北市立十三行博物館', `latitude`=25.13812763, `longitude`=121.4138359, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('88b6e9cd42908ed7f4c170667d9841ba', '04/23新莊生活講座「就是要性平-打開性別之眼」', '04/23(三)晚上7：00於新莊區公所10樓大禮堂(新莊區中正路176號)，邀請到企業講師王世勳，性別平等是近期備受關注的議題，本課程將講述性別平等重點：(1)職場不法侵害的認識與了解。(2)職場不法侵害的行為種類。(3)性別平等與互相尊重。(4)性騷擾與防治方法。', '新莊區公所', '新北市新莊區中正路176號', '新莊區公所10樓大禮堂', 25.0358303, 121.4367535, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='04/23新莊生活講座「就是要性平-打開性別之眼」', `description`='04/23(三)晚上7：00於新莊區公所10樓大禮堂(新莊區中正路176號)，邀請到企業講師王世勳，性別平等是近期備受關注的議題，本課程將講述性別平等重點：(1)職場不法侵害的認識與了解。(2)職場不法侵害的行為種類。(3)性別平等與互相尊重。(4)性騷擾與防治方法。', `organizer`='新莊區公所', `address`='新北市新莊區中正路176號', `location`='新莊區公所10樓大禮堂', `latitude`=25.0358303, `longitude`=121.4367535, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('88b6e9cd42908ed70124ec93525d9d8e', '04/22新莊生活講座「超實用的人像攝影技巧，教你如何拍好人像照片」', '04/22(二)晚上7：00於新莊福營行政大樓6樓禮堂(新莊區四維路9號)，邀請到社區大學講師徐志輝，現代手機輕便、隨身攜帶、可以迅速編輯與上傳到各大社群網站的特性，也讓手機攝影成為你我都需要的生活日常。對此，講師將教你如何掌握鏡頭、鏡位、構圖、光影、POSE五大要素，單透過手機就能隨手拍出優質人像。', '新莊區公所', '新北市新莊區四維路9號', '新莊福營行政大樓6樓禮堂', 25.0358303, 121.4367535, '無資料', '無資料', '["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504160111450.jpg&filedisplay=%E9%99%84%E4%BB%B63-114%E5%B9%B4%E6%9C%AA%E8%BE%A6%E8%AA%AA%E6%98%8E%E6%9C%83%E6%B5%B7%E5%A0%B1_page-0001.jpg&flag=pic"]') ON DUPLICATE KEY UPDATE `activity_name`='04/22新莊生活講座「超實用的人像攝影技巧，教你如何拍好人像照片」', `description`='04/22(二)晚上7：00於新莊福營行政大樓6樓禮堂(新莊區四維路9號)，邀請到社區大學講師徐志輝，現代手機輕便、隨身攜帶、可以迅速編輯與上傳到各大社群網站的特性，也讓手機攝影成為你我都需要的生活日常。對此，講師將教你如何掌握鏡頭、鏡位、構圖、光影、POSE五大要素，單透過手機就能隨手拍出優質人像。', `organizer`='新莊區公所', `address`='新北市新莊區四維路9號', `location`='新莊福營行政大樓6樓禮堂', `latitude`=25.0358303, `longitude`=121.4367535, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504160111450.jpg&filedisplay=%E9%99%84%E4%BB%B63-114%E5%B9%B4%E6%9C%AA%E8%BE%A6%E8%AA%AA%E6%98%8E%E6%9C%83%E6%B5%B7%E5%A0%B1_page-0001.jpg&flag=pic"]';
