INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('88b6e9cd42908ed7af40073029b32037', '【新北市立圖書館總館】「共讀‧未來」2025 新北閱讀節 閱讀沙龍', '為響應 4 月 23 日世界書香日，邀請市民探索多元閱讀體驗！本次活動結合「新世代未來圖書館」第二總館的建築師徵選成果，透過主題展覽、閱讀沙龍與成果發表，展現未來圖書館的創新願景。 閱讀沙龍核心主題及目標：*探索圖書館在空間設計、閱讀推廣、在地文化連結、與未來發展之間的多重面向*分別聚焦於多元閱讀、空間設計、在地文化、新世代圖書館發展等議題。*與各領域專家座談，碰撞新思維，拓展閱讀與圖書館的無限可能。閱讀沙龍講座主軸:*4/23(三) 11:00-12:00┃九典聯合建築師事務所 #郭英釗 #趙化宇 #石橋 亜紀｜《圖書館設計與閱讀氛圍的塑造》，帶大家以建築師的角度認識圖書館*4/23(三) 14:00-15:00┃逗點文創結社 #陳夏民｜《多元閱讀時代的選擇與體驗》，談紙本與電子書如何共存並豐富閱讀習慣*4/26(六) 11:00-12:00┃逃逸線書室 #王茜茜｜《看見三重:生活不在他方》， 談獨立書店與在地產業異業結合 *4/26(六) 14:00-15:30┃視覺設計師 #嚴子崴｜《圖書館在你心中的顏色 》， 帶領大朋友小朋友用顏色體驗環境（體驗活動，推薦親子共同參與）注意事項:⟡ 活動地點：新北市政府一樓⟡ 報名確認：將於活動前寄送 Email 確認通知。若有任何疑問，可聯繫窗口。⟡ 參加費用：免報名費⟡ 活動名額：4/23上下午、4/26上午講座每場次25人。4/26下午體驗活動15組親子。如有任何疑問，請隨時聯繫我們。➤ 活動洽詢：活動聯繫窗口: 陳先生0975-177925 / 方小姐0975-135795Email: reformat.taiwan@gmail.com', '新北市立圖書館', '新北市板橋區貴興路139號', '新北市政府', 25.01186453, 121.4579675, '無資料', '無資料', '["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504160843240.jpg&filedisplay=376475400A_1140005055_ATTACH1_page-0001.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504160843241.jpg&filedisplay=376475400A_1140005055_ATTACH1_page-0002.jpg&flag=pic"]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館總館】「共讀‧未來」2025 新北閱讀節 閱讀沙龍', `description`='為響應 4 月 23 日世界書香日，邀請市民探索多元閱讀體驗！本次活動結合「新世代未來圖書館」第二總館的建築師徵選成果，透過主題展覽、閱讀沙龍與成果發表，展現未來圖書館的創新願景。 閱讀沙龍核心主題及目標：*探索圖書館在空間設計、閱讀推廣、在地文化連結、與未來發展之間的多重面向*分別聚焦於多元閱讀、空間設計、在地文化、新世代圖書館發展等議題。*與各領域專家座談，碰撞新思維，拓展閱讀與圖書館的無限可能。閱讀沙龍講座主軸:*4/23(三) 11:00-12:00┃九典聯合建築師事務所 #郭英釗 #趙化宇 #石橋 亜紀｜《圖書館設計與閱讀氛圍的塑造》，帶大家以建築師的角度認識圖書館*4/23(三) 14:00-15:00┃逗點文創結社 #陳夏民｜《多元閱讀時代的選擇與體驗》，談紙本與電子書如何共存並豐富閱讀習慣*4/26(六) 11:00-12:00┃逃逸線書室 #王茜茜｜《看見三重:生活不在他方》， 談獨立書店與在地產業異業結合 *4/26(六) 14:00-15:30┃視覺設計師 #嚴子崴｜《圖書館在你心中的顏色 》， 帶領大朋友小朋友用顏色體驗環境（體驗活動，推薦親子共同參與）注意事項:⟡ 活動地點：新北市政府一樓⟡ 報名確認：將於活動前寄送 Email 確認通知。若有任何疑問，可聯繫窗口。⟡ 參加費用：免報名費⟡ 活動名額：4/23上下午、4/26上午講座每場次25人。4/26下午體驗活動15組親子。如有任何疑問，請隨時聯繫我們。➤ 活動洽詢：活動聯繫窗口: 陳先生0975-177925 / 方小姐0975-135795Email: reformat.taiwan@gmail.com', `organizer`='新北市立圖書館', `address`='新北市板橋區貴興路139號', `location`='新北市政府', `latitude`=25.01186453, `longitude`=121.4579675, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504160843240.jpg&filedisplay=376475400A_1140005055_ATTACH1_page-0001.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504160843241.jpg&filedisplay=376475400A_1140005055_ATTACH1_page-0002.jpg&flag=pic"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a5241a3bf656a8b62e4eb22fbe0b849a', '【新北市立圖書館鶯歌分館】《2025新北閱讀節主題書展》──探索圖書館', '【新北市立圖書館鶯歌分館】《2025新北閱讀節主題書展》──探索圖書館活動內容︰圖書館內書籍千變萬化，歡迎大朋友及小朋友一同進入圖書館，探索各式各樣的豐富知識！活動時間：114年04月19日至05月25日開館時間(每月最後一個星期四、國定假日固定休館)活動地點︰鶯歌分館1樓主題展示區(鶯歌區中山路150號)洽詢電話：（02）2678-0219#10▲活動單位保有取消、變更之權利，詳情請依現場為主。▲免費入場，無須報名，禁止飲食。展示期間，歡迎借閱。', '新北市立圖書館', '新北市鶯歌區中山路150號', '新北市立圖書館鶯歌分館1樓主題展示區(鶯歌區中山路150號)', 24.9566258, 121.3466269, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館鶯歌分館】《2025新北閱讀節主題書展》──探索圖書館', `description`='【新北市立圖書館鶯歌分館】《2025新北閱讀節主題書展》──探索圖書館活動內容︰圖書館內書籍千變萬化，歡迎大朋友及小朋友一同進入圖書館，探索各式各樣的豐富知識！活動時間：114年04月19日至05月25日開館時間(每月最後一個星期四、國定假日固定休館)活動地點︰鶯歌分館1樓主題展示區(鶯歌區中山路150號)洽詢電話：（02）2678-0219#10▲活動單位保有取消、變更之權利，詳情請依現場為主。▲免費入場，無須報名，禁止飲食。展示期間，歡迎借閱。', `organizer`='新北市立圖書館', `address`='新北市鶯歌區中山路150號', `location`='新北市立圖書館鶯歌分館1樓主題展示區(鶯歌區中山路150號)', `latitude`=24.9566258, `longitude`=121.3466269, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
