INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a5241a3bf656a8b623e79121c9eadeb8', '【新北市立圖書館樹林樂山圖書閱覽室】《2025新北閱讀節主題書展》──探索圖書館', '【新北市立圖書館樹林樂山圖書閱覽室】《2025新北閱讀節主題書展》──探索圖書館活動內容︰圖書館內書籍千變萬化，歡迎大朋友及小朋友一同進入圖書館，探索各式各樣的豐富知識！活動時間：114年04月19日至05月25日開館時間(每月最後一個星期四、國定假日固定休館)活動地點︰樹林樂山圖書閱覽室主題展示區(樹林區中和街38號)洽詢電話：(02) 2680-7120▲活動單位保有取消、變更之權利，詳情請依現場為主。▲免費入場，無須報名，禁止飲食。展示期間，歡迎借閱。', '新北市立圖書館', '新北市樹林區中和街38號', '新北市立圖書館樹林樂山圖書閱覽室主題展示區', 24.97970609, 121.401034, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館樹林樂山圖書閱覽室】《2025新北閱讀節主題書展》──探索圖書館', `description`='【新北市立圖書館樹林樂山圖書閱覽室】《2025新北閱讀節主題書展》──探索圖書館活動內容︰圖書館內書籍千變萬化，歡迎大朋友及小朋友一同進入圖書館，探索各式各樣的豐富知識！活動時間：114年04月19日至05月25日開館時間(每月最後一個星期四、國定假日固定休館)活動地點︰樹林樂山圖書閱覽室主題展示區(樹林區中和街38號)洽詢電話：(02) 2680-7120▲活動單位保有取消、變更之權利，詳情請依現場為主。▲免費入場，無須報名，禁止飲食。展示期間，歡迎借閱。', `organizer`='新北市立圖書館', `address`='新北市樹林區中和街38號', `location`='新北市立圖書館樹林樂山圖書閱覽室主題展示區', `latitude`=24.97970609, `longitude`=121.401034, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('88b6e9cd42908ed7663711bd0ac2d6f6', '【新北市立圖書館中和員山分館】太武山莊海山神社之文史踏查', '中和員山地區約在4200年前就有人類活動的痕跡，清領時期先民陸續來此開墾而有個四十張(犁)的舊地名，農業轉工業時期，曾有中和第二大的磚窯廠及幾個小磚窯廠，此地也被稱為“磚仔窯”。日治時期實施一街庄一神社，因板橋全境無山而選擇於此建造“海山神社”，之後爆發大東亞戰爭，為了防禦在神社下方挖了“防空壕”。山頂向南可見著名的圓通禪寺，向北方則可遠眺觀音山與蜿蜒的淡水河，因而被選為中和八景之員山遠眺。國民政府時期中和眷村一度多達26個，目前僅存太武山莊(市定古蹟)，為何它的產權屬遠隔海峽的金門縣？百年土地公廟跟漳州派大木匠師陳應彬有何關係？活動日期：05/17(六)上午09:00-11:00集合地點：新北市立圖書館中和員山分館活動對象：持有新北市立圖書館借閱證成人活動人數：30名(另開放5位候補名額，但不保證一定可以參與活動)活動講師：林志宏(雙和文史協會講師)報名方式：(一)4/21-4/22開放低收入、中低收入、高風險、身心障礙成人優先報名參加(須臨櫃且需持有新北市立圖書館借閱證、有效證明等)。(二)4/23-5/12開放一般成人及候補名額網路報名，但候補名額不保證一定可以參與活動。(三)報名額滿時將公告，詳情請上新北市立圖書館網站備 註：(一)報名額滿時將審核資格，於圖書館官網公告錄取名單。(二)活動當日建議携帶登山杖、手電筒、帽子等。(三)本活動遇大雨延期，小雨則照常辦理(請自備輕便雨衣或防雨工具)', '新北市立圖書館', '新北市中和區民享街37號2樓', '新北市立圖書館中和員山分館', 24.99088039, 121.4936744, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館中和員山分館】太武山莊海山神社之文史踏查', `description`='中和員山地區約在4200年前就有人類活動的痕跡，清領時期先民陸續來此開墾而有個四十張(犁)的舊地名，農業轉工業時期，曾有中和第二大的磚窯廠及幾個小磚窯廠，此地也被稱為“磚仔窯”。日治時期實施一街庄一神社，因板橋全境無山而選擇於此建造“海山神社”，之後爆發大東亞戰爭，為了防禦在神社下方挖了“防空壕”。山頂向南可見著名的圓通禪寺，向北方則可遠眺觀音山與蜿蜒的淡水河，因而被選為中和八景之員山遠眺。國民政府時期中和眷村一度多達26個，目前僅存太武山莊(市定古蹟)，為何它的產權屬遠隔海峽的金門縣？百年土地公廟跟漳州派大木匠師陳應彬有何關係？活動日期：05/17(六)上午09:00-11:00集合地點：新北市立圖書館中和員山分館活動對象：持有新北市立圖書館借閱證成人活動人數：30名(另開放5位候補名額，但不保證一定可以參與活動)活動講師：林志宏(雙和文史協會講師)報名方式：(一)4/21-4/22開放低收入、中低收入、高風險、身心障礙成人優先報名參加(須臨櫃且需持有新北市立圖書館借閱證、有效證明等)。(二)4/23-5/12開放一般成人及候補名額網路報名，但候補名額不保證一定可以參與活動。(三)報名額滿時將公告，詳情請上新北市立圖書館網站備 註：(一)報名額滿時將審核資格，於圖書館官網公告錄取名單。(二)活動當日建議携帶登山杖、手電筒、帽子等。(三)本活動遇大雨延期，小雨則照常辦理(請自備輕便雨衣或防雨工具)', `organizer`='新北市立圖書館', `address`='新北市中和區民享街37號2樓', `location`='新北市立圖書館中和員山分館', `latitude`=24.99088039, `longitude`=121.4936744, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('88b6e9cd42908ed74a9112a1f1b56565', '【新北市立圖書館中和員山分館 】「Home Library」系列活動：親子動手包粽子(水果冰粽)', '講師：張美麗老師一、時間：114年05/28(三) 13:30-14:30二、地點：新北市中和區自治街67號(民享藝文中心)三、招生對象：只有對活動有興趣都可以，小朋友需要家長陪同，每場20人四、報名方式：網路報名，活動當天材料費直接繳交給老師五、洽詢電話：(02) 8221-1152六、材料費：100元七、材料包含：果凍粉、白砂糖、包裝紙、水等等八、活動前請攜帶：新鮮水果丁、碗、湯匙2支(或湯匙+200cc量杯)、透明膠帶、廚房紙巾、粽子線3條、隔熱手套、保鮮盒。主辦單位：新北市立圖書館中和員山分館合辦單位：中和區民享藝文中心', '新北市立圖書館', '新北市中和區民享街37號2樓', '新北市立圖書館中和員山分館', 24.99088039, 121.4936744, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館中和員山分館 】「Home Library」系列活動：親子動手包粽子(水果冰粽)', `description`='講師：張美麗老師一、時間：114年05/28(三) 13:30-14:30二、地點：新北市中和區自治街67號(民享藝文中心)三、招生對象：只有對活動有興趣都可以，小朋友需要家長陪同，每場20人四、報名方式：網路報名，活動當天材料費直接繳交給老師五、洽詢電話：(02) 8221-1152六、材料費：100元七、材料包含：果凍粉、白砂糖、包裝紙、水等等八、活動前請攜帶：新鮮水果丁、碗、湯匙2支(或湯匙+200cc量杯)、透明膠帶、廚房紙巾、粽子線3條、隔熱手套、保鮮盒。主辦單位：新北市立圖書館中和員山分館合辦單位：中和區民享藝文中心', `organizer`='新北市立圖書館', `address`='新北市中和區民享街37號2樓', `location`='新北市立圖書館中和員山分館', `latitude`=24.99088039, `longitude`=121.4936744, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
