INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a5241a3bf656a8b6ce051161540eebfb', '【蘆洲長安分館】文化走讀-蘆洲湧蓮寺信仰中心之旅', '就從圖書館出發吧!蘆洲湧蓮寺商圈信仰中心之旅，因為信仰，所以聚集了人潮，帶動了周遭商業行為，百年來湧蓮寺市集帶動了，蘆洲、五股、八里等地的文化。路線湧蓮寺-大眾爺廟-保和宮-湧蓮商圈。活動時間：114年5月24日(六) 09:30-11:30集合地點：蘆洲湧蓮寺報名時間：114年4月21日(一) 12:00報名網址: https://reurl.cc/VY44yY 活動單位保有取消、變更之權利，詳情請依現場為主。免費入場，無須報名，禁止飲食。活動分館：蘆洲長安分館地址：新北市蘆洲區長安街96號3樓電話：02-28475873交通資訊：可搭乘至捷運蘆洲站1號出口轉搭公車至忠義廟站下車公車忠義廟(長安街)【F319蘆洲社區巴士】【F320蘆洲社區巴士】【14蘆洲-臺北車站】【232蘆洲-善導寺站】【811蘆洲-聯合醫院中興院區】', '新北市立圖書館', '新北市蘆洲區長安街96號3樓', '蘆洲長安分館', 25.08927173, 121.4712461, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【蘆洲長安分館】文化走讀-蘆洲湧蓮寺信仰中心之旅', `description`='就從圖書館出發吧!蘆洲湧蓮寺商圈信仰中心之旅，因為信仰，所以聚集了人潮，帶動了周遭商業行為，百年來湧蓮寺市集帶動了，蘆洲、五股、八里等地的文化。路線湧蓮寺-大眾爺廟-保和宮-湧蓮商圈。活動時間：114年5月24日(六) 09:30-11:30集合地點：蘆洲湧蓮寺報名時間：114年4月21日(一) 12:00報名網址: https://reurl.cc/VY44yY 活動單位保有取消、變更之權利，詳情請依現場為主。免費入場，無須報名，禁止飲食。活動分館：蘆洲長安分館地址：新北市蘆洲區長安街96號3樓電話：02-28475873交通資訊：可搭乘至捷運蘆洲站1號出口轉搭公車至忠義廟站下車公車忠義廟(長安街)【F319蘆洲社區巴士】【F320蘆洲社區巴士】【14蘆洲-臺北車站】【232蘆洲-善導寺站】【811蘆洲-聯合醫院中興院區】', `organizer`='新北市立圖書館', `address`='新北市蘆洲區長安街96號3樓', `location`='蘆洲長安分館', `latitude`=25.08927173, `longitude`=121.4712461, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a7fa633228f8ff3d64bbea066601de93', '【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「書中自有黃金屋」', '【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「書中自有黃金屋」書展期間：4/19-5/25（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館三芝分館／書展區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11書展簡介：搭配2025新北閱讀節辦理主題書展「書中自有黃金屋」，這個主題源自於中國古代詩人蘇軾的名句“書中自有黃金屋”，意味著書籍不僅能提供知識、智慧，還能帶來無限的財富與人生價值。書展將強調書籍如何成為改變命運、提升生活品質的寶貴資源，並幫助每個人找到屬於自己的“黃金屋”，歡迎到館借閱。', '新北市立圖書館', '新北市民生街31號4樓', '新北市立圖書館三芝分館／書展區', '無資料', '無資料', '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「書中自有黃金屋」', `description`='【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「書中自有黃金屋」書展期間：4/19-5/25（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館三芝分館／書展區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11書展簡介：搭配2025新北閱讀節辦理主題書展「書中自有黃金屋」，這個主題源自於中國古代詩人蘇軾的名句“書中自有黃金屋”，意味著書籍不僅能提供知識、智慧，還能帶來無限的財富與人生價值。書展將強調書籍如何成為改變命運、提升生活品質的寶貴資源，並幫助每個人找到屬於自己的“黃金屋”，歡迎到館借閱。', `organizer`='新北市立圖書館', `address`='新北市民生街31號4樓', `location`='新北市立圖書館三芝分館／書展區', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a7fa633228f8ff3d67aed0ed324df9c6', '【新北市立圖書館石門分館】《閱讀書籤》5月主題書展「閱讀的力量」', '【新北市立圖書館石門分館】《閱讀書籤》5月主題書展「閱讀的力量」書展期間：4/19-5/25（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館石門分館／2樓書展區（新北市石門區中央路9-3號2樓）聯絡電話：02-2638-1202#12書展簡介：搭配2025新北閱讀節辦理主題書展「閱讀的力量」，將強調閱讀不僅是獲取知識和娛樂的方式，更是一種改變自我、激發潛能、促進成長和社會變革的力量。書展內容可以著重於如何利用閱讀來影響思想、開闊視野、提升自我和改變生活，歡迎到館借閱。', '新北市立圖書館', '新北市中央路9-3號2樓', '新北市立圖書館石門分館／2樓書展區', '無資料', '無資料', '無資料', '無資料', '["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151014470.jpg&filedisplay=114AJ00419_2_10144925714_page-0001.jpg&flag=pic"]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館石門分館】《閱讀書籤》5月主題書展「閱讀的力量」', `description`='【新北市立圖書館石門分館】《閱讀書籤》5月主題書展「閱讀的力量」書展期間：4/19-5/25（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館石門分館／2樓書展區（新北市石門區中央路9-3號2樓）聯絡電話：02-2638-1202#12書展簡介：搭配2025新北閱讀節辦理主題書展「閱讀的力量」，將強調閱讀不僅是獲取知識和娛樂的方式，更是一種改變自我、激發潛能、促進成長和社會變革的力量。書展內容可以著重於如何利用閱讀來影響思想、開闊視野、提升自我和改變生活，歡迎到館借閱。', `organizer`='新北市立圖書館', `address`='新北市中央路9-3號2樓', `location`='新北市立圖書館石門分館／2樓書展區', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151014470.jpg&filedisplay=114AJ00419_2_10144925714_page-0001.jpg&flag=pic"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('3fda0ec6213424a2ce62ba74be8f1921', '【新北市立圖書館金山分館】2025新北閱讀節系列活動：走讀「漫遊金山趣-古道蹦火暖金泉」', '【新北市立圖書館金山分館】2025新北閱讀節系列活動：走讀「漫遊金山趣-古道蹦火暖金泉」課程時間：5/24（六）14:00-16:00連絡地點：新北市立圖書館金山分館（新北市金山區龜子山8號）聯絡電話：02-2498-4714#201(電話/臨櫃)活動地點：金山分館→金山老街→山屐下→承天宮→漁路古道起點→金山磺港→百年蹦火仔文化→金山黃金湯活動內容：金山在地文史工作者卓清松擁有豐富導覽經驗，並包含金山區公所導覽志工、法鼓山導覽組義工等經歷，本次將帶領讀者透過軍事遺址認識金山於日治時期的歷史，瞭解在地發展的歷程與人文特色，感受金山的歷史演變。', '新北市立圖書館', '新北市金山區龜子山8號', '新北市立圖書館金山分館', 25.21714594, 121.6052639, '無資料', '無資料', '["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504141409241.jpg&filedisplay=%E4%BD%9B%E5%85%89%E5%B1%B1%E4%B8%89%E9%87%8D%E7%A6%AA%E6%B7%A8%E4%B8%AD%E5%BF%83%E5%9C%A8%E5%A4%A7%E9%83%BD%E6%9C%83%E5%85%AC%E5%9C%92%E8%88%89%E8%BE%A6%E3%80%8C%E4%B8%80%E8%B5%B7%E5%90%8C%E6%A8%82%E3%80%81%E5%BE%AE%E7%AC%91%E5%89%8D%E8%A1%8C%E3%80%8D+%E5%89%8D%E6%8E%92%E5%B7%A61%E7%82%BA+%E6%96%B0%E5%8C%97%E5%B8%82%E4%BA%A4%E9%80%9A%E5%B1%80%E9%95%B7%E9%8D%BE%E9%B3%B4%E6%99%82++%E5%B7%A62%E7%82%BA%E4%B8%89%E9%87%8D%E7%A6%AA%E6%B7%A8%E4%B8%AD%E5%BF%83%E7%9B%A3%E5%AF%BA%E5%A6%82%E5%AE%97%E6%B3%95%E5%B8%AB.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504141409252.jpg&filedisplay=%E4%BD%9B%E5%85%89%E4%B8%89%E5%A5%BD%E8%A6%AA%E5%AD%90%E5%90%8C%E6%A8%82%E6%97%A5++%E9%A8%8E%E4%B9%98YouBike%E5%92%8C%E9%9F%BF%E6%87%89Vegrun%E5%85%A8%E7%90%83%E5%BE%A9%E8%94%AC%E5%85%AC%E7%9B%8A%E8%B7%AF%E8%B7%91++%E4%BB%A5%E5%81%A5%E8%B5%B0%E9%AB%94%E9%A9%97%E4%BD%8E%E7%A2%B3%E7%94%9F%E6%B4%BB.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504141409263.jpg&filedisplay=%E4%BD%9B%E5%85%89%E4%B8%89%E5%A5%BD%E8%A6%AA%E5%AD%90%E5%90%8C%E6%A8%82%E6%97%A5++%E5%90%B8%E5%BC%95%E8%BF%91500%E4%BA%BA%E5%8F%83%E5%8A%A0.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504141409264.jpg&filedisplay=%E6%B4%BB%E5%8B%95%E5%BE%8C%E6%97%A5%E5%85%89%E9%A4%90%E6%