INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('3fda0ec6213424a2c683f2fb38dbc0fc', '【新北市立圖書館金山分館】《閱讀書籤》5月主題書展「與書同行」', '【新北市立圖書館金山分館】《閱讀書籤》5月主題書展「與書同行」書展期間：4/19-5/25（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館金山分館／書展區（新北市金山區龜子山8號）聯絡電話：02-2498-4714#201書展簡介：搭配2025新北閱讀節辦理主題書展「與書同行」，是一本書、一次閱讀、一場心靈旅行。書展將邀請讀者與書籍一起走過不同的時空，開啟心靈與智慧的對話，讓書籍成為生活的夥伴，成為探索自我、理解世界的橋樑。透過各種書籍形式和活動，讓讀者體驗書籍如何成為他們的良師益友，歡迎到館借閱。', '新北市立圖書館', '新北市金山區龜子山8號', '新北市立圖書館金山分館／書展區', 25.21714594, 121.6052639, '無資料', '無資料', '["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504141422260.jpg&filedisplay=%E5%B8%AB%E7%94%9F%E5%90%88%E5%BD%B1.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504141422261.jpg&filedisplay=%E7%89%B9%E5%84%AA%E9%A0%92%E7%8D%8E.jpg&flag=pic"]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館金山分館】《閱讀書籤》5月主題書展「與書同行」', `description`='【新北市立圖書館金山分館】《閱讀書籤》5月主題書展「與書同行」書展期間：4/19-5/25（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館金山分館／書展區（新北市金山區龜子山8號）聯絡電話：02-2498-4714#201書展簡介：搭配2025新北閱讀節辦理主題書展「與書同行」，是一本書、一次閱讀、一場心靈旅行。書展將邀請讀者與書籍一起走過不同的時空，開啟心靈與智慧的對話，讓書籍成為生活的夥伴，成為探索自我、理解世界的橋樑。透過各種書籍形式和活動，讓讀者體驗書籍如何成為他們的良師益友，歡迎到館借閱。', `organizer`='新北市立圖書館', `address`='新北市金山區龜子山8號', `location`='新北市立圖書館金山分館／書展區', `latitude`=25.21714594, `longitude`=121.6052639, `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504141422260.jpg&filedisplay=%E5%B8%AB%E7%94%9F%E5%90%88%E5%BD%B1.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504141422261.jpg&filedisplay=%E7%89%B9%E5%84%AA%E9%A0%92%E7%8D%8E.jpg&flag=pic"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('3fda0ec6213424a2e97ba2f8ed1eeeb5', '【新北市立圖書館萬里分館】《閱讀書籤》5月主題書展「翻閱時光」', '【新北市立圖書館萬里分館】《閱讀書籤》5月主題書展「翻閱時光」書展期間：4/19-5/25（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館萬里分館／書展區（新北市萬里區瑪鋉路221號4樓）聯絡電話：02-2492-4490#12書展簡介：搭配2025新北閱讀節辦理主題書展「翻閱時光」，意味著翻開每一本書，就像是翻開一段歷史或未來的篇章。這個書展旨在帶領讀者穿梭於過去、現在與未來，探索時間流轉中的不同故事、知識與情感。無論是回顧歷史的經典名著，還是展望未來的科技與科幻，書展都將帶來豐富的時光旅行體驗，歡迎到館借閱。', '新北市立圖書館', '新北市萬里區瑪鋉路221號4樓', '新北市立圖書館萬里分館／書展區', 25.17572457, 121.6439307, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館萬里分館】《閱讀書籤》5月主題書展「翻閱時光」', `description`='【新北市立圖書館萬里分館】《閱讀書籤》5月主題書展「翻閱時光」書展期間：4/19-5/25（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館萬里分館／書展區（新北市萬里區瑪鋉路221號4樓）聯絡電話：02-2492-4490#12書展簡介：搭配2025新北閱讀節辦理主題書展「翻閱時光」，意味著翻開每一本書，就像是翻開一段歷史或未來的篇章。這個書展旨在帶領讀者穿梭於過去、現在與未來，探索時間流轉中的不同故事、知識與情感。無論是回顧歷史的經典名著，還是展望未來的科技與科幻，書展都將帶來豐富的時光旅行體驗，歡迎到館借閱。', `organizer`='新北市立圖書館', `address`='新北市萬里區瑪鋉路221號4樓', `location`='新北市立圖書館萬里分館／書展區', `latitude`=25.17572457, `longitude`=121.6439307, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a7fa633228f8ff3d280f3d212842fe45', '【新北市立圖書館三芝分館】與讀者有約-多元生活系列講座：「居家節能我最行～簡單打造「綠生活」」', '【新北市立圖書館三芝分館】與讀者有約-多元生活系列講座：「居家節能我最行～簡單打造「綠生活」」課程時間：5/10（六）14:00-16:00課程地點：新北市立圖書館三芝分館／閱覽區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11(電話/臨櫃/網路報名https://reurl.cc/nqenXl)課程內容：楊賢英老師為知名收納雜誌專欄作家及全方位的收納達人，擅長各種居家收納妙招，本次課程老師將透過超簡單的步驟，帶領讀者們建立綠生活的觀念，並講解如何使用空間，同時運用實際案例，讓每位讀者都能學習容易上手的生活技術。', '新北市立圖書館', '新北市民生街31號4樓', '北市立圖書館三芝分館／閱覽區', '無資料', '無資料', '無資料', '無資料', '["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151134500.jpg&filedisplay=%E6%96%B0%E5%8C%97%E5%B8%82%E6%99%BA%E6%85%A7%E5%AD%B8%E7%BF%92%E8%BC%94%E5%B0%8E%E5%B0%8F%E7%B5%84%E5%90%B3%E7%91%9E%E7%A6%8F%E8%80%81%E5%B8%AB%E5%88%86%E4%BA%AB%E6%96%B0%E5%8C%97AI%E6%95%99%E8%82%B2%E6%8E%A8%E5%8B%95%E6%88%90%E6%9E%9C_0.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151134501.jpg&filedisplay=%E6%96%B0%E5%8C%97%E5%9C%B0%E6%96%B9%E8%BC%94%E5%B0%8E%E5%9C%98%E5%9C%8B%E8%AA%9E%E6%96%87%E9%A0%98%E5%9F%9F%E5%88%86%E5%9C%98%E8%91%89%E6%9B%B8%E5%BB%B7%E8%80%81%E5%B8%AB%E5%88%86%E4%BA%AB%E8%BC%94%E5%B0%8E%E5%9C%98%E5%9C%A8%E5%85%A8%E5%B8%82%E6%95%99%E5%B8%ABAI%E6%87%89%E7%94%A8%E6%8E%A8%E5%BB%A3_0.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151134502.jpg&filedisplay=%E6%96%B0%E5%8C%97%E5%9C%B0%E6%96%B9%E8%BC%94%E5%B0%8E%E5%9C%98%E6%95%B8%E5%AD%B8%E9%A0%98%E5%9F%9F%E5%88%86%E5%9C%98%E6%9E%97%E5%BF%83%E6%80%A1%E8%80%81%E5%B8%AB%E5%88%86%E4%BA%ABAI%E5%9C%A8%E5%9C%8B%E5%B0%8F%E6%95%B8%E5%AD%B8%E6%87%89%E7%94%A8%EF%BC%8C%E4%BB%A5%E5%9B%A0%E6%9D%90%E7%B6%B2%E7%82%BA%E4%BE%8B_0.jpg&flag=pic"]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三芝分館】與讀者有約-多元生活系列講座：「居家節能我最行～簡單打造「綠生活」」', `description`='【新北市立圖書館三芝分館】與讀者有約-多元生活系列講座：「居家節能我最行～簡單打造「綠生活」」課程時間：5/10（六）14:00-16:00課程地點：新北市立圖書館三芝分館／閱覽區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11(電話/臨櫃/網路報名