INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a7fa633228f8ff3d96a797d1ec384e72', '【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「粽情粽義」', '【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「粽情粽義」書展期間：5/25-5/30（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館三芝分館／書展區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11書展簡介：「粽情粽義」，不只是包粽，更是包裹一層層的情感與故事；書籍也是如此，翻開每一頁，就像解開粽葉，裡面藏著溫暖、智慧與回憶。在端午佳節，用閱讀與人情味來相遇。', '新北市立圖書館', '新北市民生街31號4樓', '新北市立圖書館三芝分館／書展區', '無資料', '無資料', '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「粽情粽義」', `description`='【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「粽情粽義」書展期間：5/25-5/30（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館三芝分館／書展區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11書展簡介：「粽情粽義」，不只是包粽，更是包裹一層層的情感與故事；書籍也是如此，翻開每一頁，就像解開粽葉，裡面藏著溫暖、智慧與回憶。在端午佳節，用閱讀與人情味來相遇。', `organizer`='新北市立圖書館', `address`='新北市民生街31號4樓', `location`='新北市立圖書館三芝分館／書展區', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a7fa633228f8ff3daec5362cd0782ceb', '【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「生活處處是藝術」', '【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「生活處處是藝術」書展期間：5/17-5/24（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館三芝分館／書展區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11書展簡介：藝術存在於我們的日常當中，無論是建築、花草、環境，又或是一般的生活用品、文具，只要換個視角欣賞，都是藝術的不同呈現方式，也許有些藝術的形式是你從來沒認識過的，也或許有些事物你現在才意識到它是藝術世界的一環。不論如何，多多感受藝術，發現生活中的美好吧！', '新北市立圖書館', '新北市民生街31號4樓', '新北市立圖書館三芝分館／書展區', '無資料', '無資料', '無資料', '無資料', '["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151128220.jpg&filedisplay=%E5%9C%96%E4%B8%80.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151128221.jpg&filedisplay=%E5%9C%96%E4%BA%8C.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151128222.jpg&filedisplay=%E5%9C%96%E4%B8%89.jpg&flag=pic"]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「生活處處是藝術」', `description`='【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「生活處處是藝術」書展期間：5/17-5/24（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館三芝分館／書展區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11書展簡介：藝術存在於我們的日常當中，無論是建築、花草、環境，又或是一般的生活用品、文具，只要換個視角欣賞，都是藝術的不同呈現方式，也許有些藝術的形式是你從來沒認識過的，也或許有些事物你現在才意識到它是藝術世界的一環。不論如何，多多感受藝術，發現生活中的美好吧！', `organizer`='新北市立圖書館', `address`='新北市民生街31號4樓', `location`='新北市立圖書館三芝分館／書展區', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151128220.jpg&filedisplay=%E5%9C%96%E4%B8%80.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151128221.jpg&filedisplay=%E5%9C%96%E4%BA%8C.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151128222.jpg&filedisplay=%E5%9C%96%E4%B8%89.jpg&flag=pic"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a7fa633228f8ff3dbe28b7e869ee8f5f', '【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「媽咪，辛苦了！」', '【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「媽咪，辛苦了！」書展期間：5/09-5/16（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館三芝分館／書展區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11書展簡介：屬於母親們的節日即將到來，也許一年當中只有這一天你會為母親慶祝，可母親卻是一年三百六十五天都在為孩子煩惱、愛著孩子。母愛的偉大無法用言語形容，趁著這時帶著最真誠的心，以行動表達自己的愛意吧，無論是帶著母親去吃大餐，或在家放鬆一整天，都別忘了說聲：謝謝，辛苦了！', '新北市立圖書館', '新北市民生街31號4樓', '新北市立圖書館三芝分館／書展區', '無資料', '無資料', '無資料', '無資料', '["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151123270.jpg&filedisplay=%E5%9C%96%E4%B8%80.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151123271.jpg&filedisplay=%E5%9C%96%E4%BA%8C.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151123272.jpg&filedisplay=%E5%9C%96%E4%B8%89.jpg&flag=pic"]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「媽咪，辛苦了！」', `description`='【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「媽咪，辛苦了！」書展期間：5/09-5/16（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館三芝分館／書展區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11書展簡介：屬於母親們的節日即將到來，也許一年當中只有這一天你會為母親慶祝，可母親卻是一年三百六十五天都在為孩子煩惱、愛著孩子。母愛的偉大無法用言語形容，趁著這時帶著最真誠的心，以行動表達自己的愛意吧，無論是帶著母親去吃大餐，或在家放鬆一整天，都別忘了說聲：謝謝，辛苦了！', `organizer`='新北市立圖書館', `address`='新北市民生街31號4樓', `location`='新北市立圖書館三芝分館／書展區', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151123270.jpg&filedisplay=%E5%9C%96%E4%B8%80.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151123271.jpg&filedisplay=%E5%9C%96%E4%BA%8C.jpg&flag=pic", "https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151123272.jpg&filedisplay=%E5%9C%96%E4%B8%89.jpg&flag=pic"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('a7fa633228f8ff3d23627720540ec25d', '【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「粒粒皆辛苦」', '【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「粒粒皆辛苦」書展期間：5/01-5/08（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館三芝分館／書展區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11書展簡介：無論是什麼職業，都有它困難、辛苦的地方，透過各行各業的配合，才構築出現今人們生活的社會，因此我們要感謝並珍惜他人的付出，更不可輕視或為任何職業評斷貴賤，趁著勞動節期間，來圖書館深入了解不曾認識過的各種職業吧！', '新北市立圖書館', '新北市民生街31號4樓', '新北市立圖書館三芝分館／書展區', '無資料', '無資料', '無資料', '無資料', '["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151059150.jpg&filedisplay=20250415-01.jpg&flag=pic"]') ON DUPLICATE KEY UPDATE `activity_name`='【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「粒粒皆辛苦」', `description`='【新北市立圖書館三芝分館】《閱讀書籤》5月主題書展「粒粒皆辛苦」書展期間：5/01-5/08（開館時間）國定假日與每月最後一個星期四不開放。書展地點：新北市立圖書館三芝分館／書展區（新北市三芝區民生街31號4樓）聯絡電話：02-2636-2331#11書展簡介：無論是什麼職業，都有它困難、辛苦的地方，透過各行各業的配合，才構築出現今人們生活的社會，因此我們要感謝並珍惜他人的付出，更不可輕視或為任何職業評斷貴賤，趁著勞動節期間，來圖書館深入了解不曾認識過的各種職業吧！', `organizer`='新北市立圖書館', `address`='新北市民生街31號4樓', `location`='新北市立圖書館三芝分館／書展區', `latitude`='無資料', `longitude`='無資料', `ticket_price`='無資料', `source_url`='無資料', `image_url`='["https://www.ntpc.gov.tw/uploaddowndoc?file=news/202504151059150.jpg&filedisplay=20250415-01.jpg&flag=pic"]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004055', '兩岸三地合唱交流—春藝盎然音樂會', '兩岸三地合唱交流&mdash;春藝盎然音樂會時間｜3月28日19:00｜金門縣文化局音樂會由深耕合唱藝術近四十載的金門縣合唱團策劃，以「音樂跨越疆界，文化匯聚共鳴」為理念，邀請廈門市青少年宮鳳凰花女子合唱團、台北圓韵合唱團、金門縣兒童合唱團、金湖國小附設幼兒園等優秀團隊齊聚一堂，在春暖花開的季節，用歌聲傳遞真摯的情感與文化的共鳴。金門縣合唱團不僅多次代表金門征戰國內外合唱賽事，並積極參與各地文化交流，屢獲殊榮。作為「島嶼文化傳承者」，該團多年來策劃多場跨域音樂會，展現「從傳統到當代、從本土到世界」的音樂光譜，讓合唱藝術成為金門的文化驕傲。值得關注的是，今年3月剛成立的金門縣兒童合唱團將迎來首次公開演出！儘管剛組成不久，這群孩子們在指導老師李永舜、楊宜臻、蘇怡如、李宣萱的帶領下，憑藉熱情與努力展現令人驚喜的成長。這次，他們將用清澈純真的嗓音，向觀眾呈現動人的音樂魅力，期待大家以熱烈掌聲，給予這群孩子最大的鼓勵。本場音樂會匯聚兩岸三地合唱團隊，各具特色的音樂風格將交織出動人的旋律：　　廈門市青少年宮鳳凰花女子合唱團&mdash;以純淨細膩的女聲詮釋各類曲風，長年致力於兩岸文化交流，榮獲多項國際合唱獎項。　　台北圓韵合唱團&mdash;由金門金城國小合唱團校友組成，以「圓韵」象徵對音樂的執著與傳承，擅長演繹溫暖動人的經典合唱曲。金門縣合唱團&mdash;歷史悠久、獲獎無數，曲風橫跨傳統與現代，演出經歷遍及兩岸三地，備受肯定。　　金門縣兒童合唱團&mdash;全新成立，以「傳唱島嶼故事」為核心，讓金門孩子的純淨嗓音成為文化傳承的最佳載體。　　金湖國小附設幼兒園&mdash;活潑童趣的舞蹈演出，為音樂會增添活力與希望，展現音樂與舞蹈交織的美好。本次音樂會的曲目涵蓋經典與現代作品，將帶來感動人心的聆聽體驗：金門縣兒童合唱團&mdash;《甜蜜的家庭》《愉快的歌聲》，金門縣合唱團（混聲合唱）&mdash;《牽手》《牽阮的手》，金門縣合唱團（男聲重唱）&mdash;《請相信我》《康定情歌》，台北圓韵合唱團&mdash;《本事》《台北的天空》《晚霞》，廈門市鳳凰花女子合唱團&mdash;...', '金門縣政府', '無資料', '2025-03-28 00:00:00', '2025-03-28 00:00:00', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='兩岸三地合唱交流—春藝盎然音樂會', `description`='兩岸三地合唱交流&mdash;春藝盎然音樂會時間｜3月28日19:00｜金門縣文化局音樂會由深耕合唱藝術近四十載的金門縣合唱團策劃，以「音樂跨越疆界，文化匯聚共鳴」為理念，邀請廈門市青少年宮鳳凰花女子合唱團、台北圓韵合唱團、金門縣兒童合唱團、金湖國小附設幼兒園等優秀團隊齊聚一堂，在春暖花開的季節，用歌聲傳遞真摯的情感與文化的共鳴。金門縣合唱團不僅多次代表金門征戰國內外合唱賽事，並積極參與各地文化交流，屢獲殊榮。作為「島嶼文化傳承者」，該團多年來策劃多場跨域音樂會，展現「從傳統到當代、從本土到世界」的音樂光譜，讓合唱藝術成為金門的文化驕傲。值得關注的是，今年3月剛成立的金門縣兒童合唱團將迎來首次公開演出！儘管剛組成不久，這群孩子們在指導老師李永舜、楊宜臻、蘇怡如、李宣萱的帶領下，憑藉熱情與努力展現令人驚喜的成長。這次，他們將用清澈純真的嗓音，向觀眾呈現動人的音樂魅力，期待大家以熱烈掌聲，給予這群孩子最大的鼓勵。本場音樂會匯聚兩岸三地合唱團隊，各具特色的音樂風格將交織出動人的旋律：　　廈門市青少年宮鳳凰花女子合唱團&mdash;以純淨細膩的女聲詮釋各類曲風，長年致力於兩岸文化交流，榮獲多項國際合唱獎項。　　台北圓韵合唱團&mdash;由金門金城國小合唱團校友組成，以「圓韵」象徵對音樂的執著與傳承，擅長演繹溫暖動人的經典合唱曲。金門縣合唱團&mdash;歷史悠久、獲獎無數，曲風橫跨傳統與現代，演出經歷遍及兩岸三地，備受肯定。　　金門縣兒童合唱團&mdash;全新成立，以「傳唱島嶼故事」為核心，讓金門孩子的純淨嗓音成為文化傳承的最佳載體。　　金湖國小附設幼兒園&mdash;活潑童趣的舞蹈演出，為音樂會增添活力與希望，展現音樂與舞蹈交織的美好。本次音樂會的曲目涵蓋經典與現代作品，將帶來感動人心的聆聽體驗：金門縣兒童合唱團&mdash;《甜蜜的家庭》《愉快的歌聲》，金門縣合唱團（混聲合唱）&mdash;《牽手》《牽阮的手》，金門縣合唱團（男聲重唱）&mdash;《請相信我》《康定情歌》，台北圓韵合唱團&mdash;《本事》《台北的天空》《晚霞》，廈門市鳳凰花女子合唱團&mdash;...', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-03-28 00:00:00', `end_date`='2025-03-28 00:00:00', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004061', '《汝好！金門》金門國家公園古厝民宿節', '114年為內政部國家公園署金門國家公園管理處成立30週年，與傳統建築民宿經營邁入20週年的雙重里程碑辦理《汝好！金門》金門國家公園古厝民宿節，活動包含開幕、聚落走讀集點去，以及限定5月3日、5月10日兩場次聚落走讀與體驗活動，邀請民眾參與聚落走讀導覽、DIY手作及與民宿主人對談，走進金門獨特的聚落時光，感受傳統建築與在地文化的魅力。主辦單位：內政部國家公園署金門國家公園管理處活動時間：5月3日至5月26日連絡電話：興展創意數位有限公司 吳小姐 02-2392-8599分機19各活動時間及地點以主辦單位最新公告為主', '金門縣政府', '無資料', '2025-05-03 00:00:00', '2025-05-26 00:00:00', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='《汝好！金門》金門國家公園古厝民宿節', `description`='114年為內政部國家公園署金門國家公園管理處成立30週年，與傳統建築民宿經營邁入20週年的雙重里程碑辦理《汝好！金門》金門國家公園古厝民宿節，活動包含開幕、聚落走讀集點去，以及限定5月3日、5月10日兩場次聚落走讀與體驗活動，邀請民眾參與聚落走讀導覽、DIY手作及與民宿主人對談，走進金門獨特的聚落時光，感受傳統建築與在地文化的魅力。主辦單位：內政部國家公園署金門國家公園管理處活動時間：5月3日至5月26日連絡電話：興展創意數位有限公司 吳小姐 02-2392-8599分機19各活動時間及地點以主辦單位最新公告為主', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-05-03 00:00:00', `end_date`='2025-05-26 00:00:00', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_371020000A_004063', '愛戀金城祈福音樂會', '愛戀金城祈福音樂會時間|4月12日（六）晚間7時地點|金門縣文化局演藝廳愛戀金城祈福音樂會委請金門國樂團等進行演出，並由國際知名音樂指揮家黃光佑老師擔綱指揮。金門國樂團正式成立於2007年，在黃光佑老師的帶領下，多次在國內外進行大型音樂會展演，培養了豐富的舞台經驗與高度專業的演奏實力，廣受各界好評。演出曲目包括中正國小絲竹樂團《迎春曲》、《芬里爾》，金門高中絲竹樂團《江南好》、《Naomi變奏曲》，金湖國小國樂團《走馬》，中正國小國樂團《暮鼓》，以及中正國小、金湖國小、金湖國中、金城國中及金門高中等五校國樂團組成的聯合國樂團擔綱演出《料羅灣之戀》、《望春風》及《初心》等曲目。透過悠揚的國樂響宴，以虔誠的心感受揚善棄惡的城隍精神，一起祈求浯島城隍護佑鄉親，並帶來的心靈平安與力量。金城鎮公所/主辦', '金門縣政府', '無資料', '2025-04-12 00:00:00', '2025-04-12 00:00:00', '金門縣金城鎮', 24.43586, 118.31705, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='愛戀金城祈福音樂會', `description`='愛戀金城祈福音樂會時間|4月12日（六）晚間7時地點|金門縣文化局演藝廳愛戀金城祈福音樂會委請金門國樂團等進行演出，並由國際知名音樂指揮家黃光佑老師擔綱指揮。金門國樂團正式成立於2007年，在黃光佑老師的帶領下，多次在國內外進行大型音樂會展演，培養了豐富的舞台經驗與高度專業的演奏實力，廣受各界好評。演出曲目包括中正國小絲竹樂團《迎春曲》、《芬里爾》，金門高中絲竹樂團《江南好》、《Naomi變奏曲》，金湖國小國樂團《走馬》，中正國小國樂團《暮鼓》，以及中正國小、金湖國小、金湖國中、金城國中及金門高中等五校國樂團組成的聯合國樂團擔綱演出《料羅灣之戀》、《望春風》及《初心》等曲目。透過悠揚的國樂響宴，以虔誠的心感受揚善棄惡的城隍精神，一起祈求浯島城隍護佑鄉親，並帶來的心靈平安與力量。金城鎮公所/主辦', `organizer`='金門縣政府', `address`='無資料', `start_date`='2025-04-12 00:00:00', `end_date`='2025-04-12 00:00:00', `location`='金門縣金城鎮', `latitude`=24.43586, `longitude`=118.31705, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
