INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005969', '2025夜探三仙台', '「夜晚的三仙台，是甚麼樣子呢?」當月光冉冉升起海浪，也唱著另外一首歌陸蟹，好奇地探出頭寄居蟹，正努力找尋另一個家剛轉大人的青蛙，熱情地唱著情歌邀請你，跟著在地導覽老師的腳步用「剛剛好」的溫柔光源探訪三仙台夜間的小精靈們！在浪濤、星空、礫石灘觀賞東海岸最浪漫的自然饗宴。▐ 行程種類不過島行程：於遊憩區內探索動植物、觀星、聽濤，行程約１小時，屬於愜意路線。過島行程：過八拱橋至涼亭折返，行程約２小時，屬於挑戰路線。▐ 收費表不過島行程：定價300元/人，早鳥優惠200元/人。過島行程：定價500元/人，早鳥優惠400元/人。▐ 集合時間4、5、9、10月 18：15報到6&ndash;8月 18：45報到▐ 集合地點三仙台販賣部(台東縣成功鎮基翬路74號)，17:00後免收停車費。▐ 報名方式統一採線上預約制(活動前一個月開放預約報名)，若線上無法報名請來電洽詢。報名連結▐ 活動說明1. 每團10-15人(可以併團)，每日限量60人。若人數不足10人，將電話通知不成團。2. 活動10日前預約享早鳥優惠並包含保險費用，9日內報名以原價收費。兩歲以下免費。3. 最晚報名時間為活動前3日。', '交通部觀光署東部海岸國家風景區管理處', '無資料', '2025-04-01 00:00:00', '2025-10-31 00:00:00', '臺東縣成功鎮', 23.12334, 121.4083, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025夜探三仙台', `description`='「夜晚的三仙台，是甚麼樣子呢?」當月光冉冉升起海浪，也唱著另外一首歌陸蟹，好奇地探出頭寄居蟹，正努力找尋另一個家剛轉大人的青蛙，熱情地唱著情歌邀請你，跟著在地導覽老師的腳步用「剛剛好」的溫柔光源探訪三仙台夜間的小精靈們！在浪濤、星空、礫石灘觀賞東海岸最浪漫的自然饗宴。▐ 行程種類不過島行程：於遊憩區內探索動植物、觀星、聽濤，行程約１小時，屬於愜意路線。過島行程：過八拱橋至涼亭折返，行程約２小時，屬於挑戰路線。▐ 收費表不過島行程：定價300元/人，早鳥優惠200元/人。過島行程：定價500元/人，早鳥優惠400元/人。▐ 集合時間4、5、9、10月 18：15報到6&ndash;8月 18：45報到▐ 集合地點三仙台販賣部(台東縣成功鎮基翬路74號)，17:00後免收停車費。▐ 報名方式統一採線上預約制(活動前一個月開放預約報名)，若線上無法報名請來電洽詢。報名連結▐ 活動說明1. 每團10-15人(可以併團)，每日限量60人。若人數不足10人，將電話通知不成團。2. 活動10日前預約享早鳥優惠並包含保險費用，9日內報名以原價收費。兩歲以下免費。3. 最晚報名時間為活動前3日。', `organizer`='交通部觀光署東部海岸國家風景區管理處', `address`='無資料', `start_date`='2025-04-01 00:00:00', `end_date`='2025-10-31 00:00:00', `location`='臺東縣成功鎮', `latitude`=23.12334, `longitude`=121.4083, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_376540000A_005973', '2025太麻里金針花—賞花專車', '搭上專屬賞花專車，啟程前往金針花盛開的金針山，一場與金黃花海的夏日約定即將展開。沿途盡覽山海景致，沉浸在花海與微風交織的療癒時光。這不只是一趟旅程，更是一次走入在地故事、感受自然節奏的花季體驗。誠摯邀請你，一同上山看花、放慢腳步，與金針花共度最柔軟的片刻。✨活動時間｜114年8月11日～114年9月21日✨活動地點｜金針山各大花區', '太麻里鄉公所', '無資料', '2025-08-11 00:00:00', '2025-09-21 00:00:00', '臺東縣金峰鄉', 22.64279, 120.95712, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025太麻里金針花—賞花專車', `description`='搭上專屬賞花專車，啟程前往金針花盛開的金針山，一場與金黃花海的夏日約定即將展開。沿途盡覽山海景致，沉浸在花海與微風交織的療癒時光。這不只是一趟旅程，更是一次走入在地故事、感受自然節奏的花季體驗。誠摯邀請你，一同上山看花、放慢腳步，與金針花共度最柔軟的片刻。✨活動時間｜114年8月11日～114年9月21日✨活動地點｜金針山各大花區', `organizer`='太麻里鄉公所', `address`='無資料', `start_date`='2025-08-11 00:00:00', `end_date`='2025-09-21 00:00:00', `location`='臺東縣金峰鄉', `latitude`=22.64279, `longitude`=120.95712, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
