INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_395000000A_007114', '「4-5月來臺南 住一晚送一晚」台南住宿優惠活動', '為鼓勵大家平日輕鬆玩臺南，臺南市政府推出「4-5月來臺南，住一晚送一晚」專案，鼓勵民眾來臺南多玩幾天體驗深度旅遊；各家旅宿優惠名額有限，手刀訂房的遊客還有機會得到觀旅局限量加碼的精典泰迪情侶款小提燈。注意事項：1.本局網站彙整各業者優惠資訊，訂房請直洽以下合作業者。2.平日定義由業者自行定義、小提燈發放數量亦由業者自行決定，詳細情形請直洽以下合作業者。 類型業者名稱優惠方案電話Google map民宿台南安平AP7民宿安平AP7包棟民宿限定優惠6人即可包棟，平日連續住宿兩晚優惠9999元(兩天皆平日)原訂房價為20000元，再送限量小禮，每日限量1棟平日定義：周日至周四，不含國定假日(5月1日勞動節不適用)0956-167168Google Map民宿安平鵀 彩居安平鵀 彩居包棟民宿限定優惠6人即可包棟，平日連續住宿兩晚優惠9999元(兩天皆平日)原訂房價為20000元，再送限量小禮，每日限量1棟平日定義：周日至周四，不含國定假日(5月1日勞動節不適用)0956-167168Google Map民宿安平 囍宿 民宿安平囍宿包棟民宿限定優惠6人即可包棟，平日連續住宿兩晚優惠8888元(兩天皆平日)原訂房價為18000元，再送限量小禮，每日限量1棟平日定義：周日至周四，不含國定假日(5月1日勞動節不適用)0956-167168Google Map民宿九號光舟民宿九號光舟民宿限定優惠8人以下包棟，平日連續住宿兩晚官網售價24000，優惠12000元(兩天皆平日)，每日限量1棟平日定義：周日至周四，不含國定假日(5月1日勞動節不適用)(4月19日-4月24日全中運不適用)0915-495335Google Map民宿九號和和民宿九號和和民宿限定優惠8人以下包棟，平日連續住宿兩晚官網售價24000，優惠12000元(兩天皆平日)，每日限量1棟平日定義：周日至周五，不含國定假日(5月1日勞動節不適用)(4月19日-4月24日全中運不適用)0915-495335Google Map民宿安平胡桃民宿安平胡桃民宿限定優惠8人以下包棟，平日連續住宿兩晚官網售價26000，優惠13000元(...', '臺南市政府', '無資料', '2025-04-01 00:00:00', '2025-05-31 00:00:00', '臺南市安平區', 22.99166, 120.182808, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='「4-5月來臺南 住一晚送一晚」台南住宿優惠活動', `description`='為鼓勵大家平日輕鬆玩臺南，臺南市政府推出「4-5月來臺南，住一晚送一晚」專案，鼓勵民眾來臺南多玩幾天體驗深度旅遊；各家旅宿優惠名額有限，手刀訂房的遊客還有機會得到觀旅局限量加碼的精典泰迪情侶款小提燈。注意事項：1.本局網站彙整各業者優惠資訊，訂房請直洽以下合作業者。2.平日定義由業者自行定義、小提燈發放數量亦由業者自行決定，詳細情形請直洽以下合作業者。 類型業者名稱優惠方案電話Google map民宿台南安平AP7民宿安平AP7包棟民宿限定優惠6人即可包棟，平日連續住宿兩晚優惠9999元(兩天皆平日)原訂房價為20000元，再送限量小禮，每日限量1棟平日定義：周日至周四，不含國定假日(5月1日勞動節不適用)0956-167168Google Map民宿安平鵀 彩居安平鵀 彩居包棟民宿限定優惠6人即可包棟，平日連續住宿兩晚優惠9999元(兩天皆平日)原訂房價為20000元，再送限量小禮，每日限量1棟平日定義：周日至周四，不含國定假日(5月1日勞動節不適用)0956-167168Google Map民宿安平 囍宿 民宿安平囍宿包棟民宿限定優惠6人即可包棟，平日連續住宿兩晚優惠8888元(兩天皆平日)原訂房價為18000元，再送限量小禮，每日限量1棟平日定義：周日至周四，不含國定假日(5月1日勞動節不適用)0956-167168Google Map民宿九號光舟民宿九號光舟民宿限定優惠8人以下包棟，平日連續住宿兩晚官網售價24000，優惠12000元(兩天皆平日)，