INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_395000000A_007170', '2025世界自行車日-臺灣騎時很美麗', '觀光署邀請  公共自行車 一同響應環保、永續完成指定任務~就有機會獲得 #知名品牌自行車 (共6輛)太讚了吧.ᐟ.ᐟ .ᐟ.ᐟ租借各縣市 #、# 據點之公共自行車✦合計30次就能獲得扌由獎機會(可累計如60次2次機會)※借還至少分鐘以上計算1次活動時間：即日起-/ :活動據點：全臺可租借到 #YouBike、#MOOVO皆可活動獎品：知名品牌自行車輛(共計6名)【借/還車】須於活動時間內，才算次數計算【平台計算】YouBike與MOOVO的租借平台會員帳號為分開計算‼️還有還有！！接著 #年度世界自行車主場活動將再度重現盛況ʕ◉ᴥʔ請持續鎖定 #交通部觀光署 掌握最新活動消息✧˖*✧˖*✧˖*✧˖*✧˖*✧˖*活動詳情須知&公共自行車相關租借流程等可查YouBike(微笑單車)MOOVO (運點科技)多元自行車路線資訊&活動辦法 可查「臺灣騎跡-全國單一線入口網」#交通部 #觀光署 #WorldBicycleDay #世界自行車日✧˖*✧˖*✧˖*✧˖*✧˖*✧˖*', '交通部觀光署', '無資料', '2025-04-02 00:00:00', '2025-06-02 00:00:00', '臺南市安平區', 22.99166, 120.182808, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025世界自行車日-臺灣騎時很美麗', `description`='觀光署邀請  公共自行車 一同響應環保、永續完成指定任務~就有機會獲得 #知名品牌自行車 (共6輛)太讚了吧.ᐟ.ᐟ .ᐟ.ᐟ租借各縣市 #、# 據點之公共自行車✦合計30次就能獲得扌由獎機會(可累計如60次2次機會)※借還至少分鐘以上計算1次活動時間：即日起-/ :活動據點：全臺可租借到 #YouBike、#MOOVO皆可活動獎品：知名品牌自行車輛(共計6名)【借/還車】須於活動時間內，才算次數計算【平台計算】YouBike與MOOVO的租借平台會員帳號為分開計算‼️還有還有！！接著 #年度世界自行車主場活動將再度重現盛況ʕ◉ᴥʔ請持續鎖定 #交通部觀光署 掌握最新活動消息✧˖*✧˖*✧˖*✧˖*✧˖*✧˖*活動詳情須知&公共自行車相關租借流程等可查YouBike(微笑單車)MOOVO (運點科技)多元自行車路線資訊&活動辦法 可查「臺灣騎跡-全國單一線入口網」#交通部 #觀光署 #WorldBicycleDay #世界自行車日✧˖*✧˖*✧˖*✧˖*✧˖*✧˖*', `organizer`='交通部觀光署', `address`='無資料', `start_date`='2025-04-02 00:00:00', `end_date`='2025-06-02 00:00:00', `location`='臺南市安平區', `latitude`=22.99166, `longitude`=120.182808, `ticket_price`='無資料', `source_url`='無資料', `image_url`='[]';
INSERT INTO `theme_events` (`uid`, `activity_name`, `description`, `organizer`, `address`, `start_date`, `end_date`, `location`, `latitude`, `longitude`, `ticket_price`, `source_url`, `image_url`) VALUES ('C2_395000000A_007177', '2025台南雙層巴士盲盒旅遊', '【台南雙層巴士盲盒旅遊】 4大節氣+8大特色主題全新旅遊體驗──「盲盒」，事前不揭曉行程，帶您來一趟充滿驚喜與刺激的旅行，增加旅遊的新鮮感，喜愛冒險和挑戰的旅行者，絕對不要錯過2025年全新推出「台南4大節氣+8大特色主題」，深入體驗台南多元風貌，感受台南 文化、美食小吃、農特物產等旅遊魅力搭乘開頂雙層巴士，從高視角欣賞府城風光，沿途品嚐在地特色美食，參與導覽與體驗活動 遊程訂購平台  KKday － 報名時間 －【第一階段：熟客搶先報】4/17（四） AM 9:00 - 4/18（五）AM 8:59【第二階段：新客初體驗】4/21（一） AM 9:00 - 4/25（五）PM 23:59【第三階段：大家來報名】4/28（一） AM 9:00 - 至各場次辦理前 2 日（或額滿為止）－ 4 大節氣行程亮點 －【春｜春遊府城．茶香尋跡｜品茶 &times; 散步 &times; 戲劇 &times; 茶席體驗】體驗日期：5/3（六） 09:30 - 15:30集合地點：台南火車站雙層巴士站點用春風與茶香，打開一場城市風雅慢旅台南不產茶，卻藏著台灣最濃厚的茶文化底蘊。這趟以「茶」為題的春季城市散策，將帶你穿梭時光，漫步在老街巷弄，尋訪百年茶香的足跡。從低調老派的茶行，到轉角處的文青茶屋，沒有明牌，只有驚喜。你將透過五感，走進一段段茶人與老屋的故事、品嚐一桌春季茶餐、親手體驗古法手刷茶儀式，重新定義「喝茶」這件事【夏｜夏饗風味．傳統美味｜挖筍 &times; 辦桌 &times; 採鳳梨】體驗日期：6/14 （六） 08:30 - 16:00集合地點：高鐵台南站用一口辦桌好菜，打開南國夏日的鮮甜滋味南台灣的夏天，是鳳梨香與竹筍鮮交織的味覺盛季。這趟充滿人情味的料理小旅行，從田間挖筍出發，到總舖師手把手教你辦桌好菜，再走進金黃鳳梨園，用雙手感受土地的甘甜。節氣、風土、農產、料理，這不只是一趟旅行，更是一桌專屬夏天的台菜盛宴。【秋｜田野秋收．永續農趣｜採果樂 &times; 有機農 &times; 古蹟巡禮】體驗日期：8/9（六） 09:00 - 16:00集合地點：善化火車...', '臺南市政府', '無資料', '2025-05-03 00:00:00', '2025-11-15 00:00:00', '臺南市安平區', 22.99166, 120.182808, '無資料', '無資料', '[]') ON DUPLICATE KEY UPDATE `activity_name`='2025台南雙層巴士盲盒旅遊', `description`='【台南雙層巴士盲盒旅遊】 4大節氣+8大特色主題全新旅遊體驗──「盲盒」，事前不揭曉行程，帶您來一趟充滿驚喜與刺激的旅行，增加旅遊的新鮮感，喜愛冒險和挑戰的旅行者，絕對不要錯過2025年全新推出「台南4大節氣+8大特色主題」，深入體驗台南多元風貌，感受台南 文化、美食小吃、農特物產等旅遊魅力搭乘開頂雙層巴士，從高視角欣賞府城風光，沿途品嚐在地特色美食，參與導覽與體驗活動 遊程訂購平台  KKday － 報名時間 －【第一階段：熟客搶先報】4/17（四） AM 9:00 - 4/18（五）AM 8:59【第二階段：新客初體驗】4/21（一） AM 9:00 - 4/25（五）PM 23:59【第三階段：大家來報名】4/28（一） AM 9:00 - 至各場次辦理前 2 日（或額滿為止）－ 4 大節氣行程亮點 －【春｜春遊府城．茶香尋跡｜品茶 &times; 散步 &times; 戲劇 &times; 茶席體驗】體驗日期：5/3（六） 09:30 - 15:30集合地點：台南火車站雙層巴士站點用春風與茶香，打開一場城市風雅慢旅台南不產茶，卻藏著台灣最濃厚的茶文化底蘊。這趟以「茶」為題的春季城市散策，將帶你穿梭時光，漫步在老街巷弄，尋訪百年茶香的足跡。從低調老派的茶行，到轉角處的文青茶屋，沒有明牌，只有驚喜。你將透過五感，走進一段段茶人與老屋的故事、品嚐一桌春季茶餐、親手體驗古法手刷茶儀式，重新定義「喝茶」這件事【夏｜夏饗風味．傳統美味｜挖筍 &times; 辦桌 &times; 採鳳梨】體驗日期：6/14